module calculator(
    input logic [31:0] a,
    input logic [31:0] b,
    input logic reset_n,
    output logic [31:0] add,
    output logic [31:0] sub,
    output logic [31:0] mul,
    output logic [31:0] div
);

    always @(a, b, reset_n) begin
        if(!reset_n) begin
            add <= 0;
            sub <= 0;
            mul <= 0;
            div <= 0;
        end else begin
            add <= a + b;
            sub <= a - b;
            mul <= a * b;
            if(b != 0) begin
                div <= a / b;
            end else begin
                div <= 0;
            end
        end
    end

endmodule

module edge_detector (
    input clk,
    input [7:0] in,
    output [7:0] out
);

reg [7:0] prev_in;
reg [7:0] curr_in;
reg [7:0] next_in;
reg [2:0] state;

always @(posedge clk) begin
    prev_in <= curr_in;
    curr_in <= next_in;
    next_in <= in;

    case (state)
        3'b000: begin
            if (curr_in != prev_in) begin
                state <= 3'b001;
            end
        end
        3'b001: begin
            state <= 3'b010;
        end
        3'b010: begin
            state <= 3'b011;
        end
        3'b011: begin
            out <= next_in;
            state <= 3'b000;
        end
    endcase
end

endmodule

