module add_sub_mux (
    input [3:0] in1, // First 4-bit input for the adder/subtractor
    input [3:0] in2, // Second 4-bit input for the adder/subtractor
    input control, // Control signal for the adder/subtractor (0 for addition, 1 for subtraction)
    input [2:0] sel, // Select input for the multiplexer
    input [3:0] data0, // 4-bit data inputs for the multiplexer
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output reg [7:0] out // 8-bit output from the functional module
);

// 4-bit adder/subtractor using a 2-to-1 multiplexer
wire [3:0] add_out;
wire [3:0] sub_out;
assign add_out = in1 + in2;
assign sub_out = in1 - in2;
assign out[3:0] = control ? sub_out : add_out;

// 6-to-1 multiplexer
wire [3:0] mux_out;
assign mux_out = (sel == 0) ? data0 :
                 (sel == 1) ? data1 :
                 (sel == 2) ? data2 :
                 (sel == 3) ? data3 :
                 (sel == 4) ? data4 :
                 (sel == 5) ? data5 :
                 4'b0000;

// Final 8-bit output
assign out[7:4] = out[3:0];
assign out[3:0] = mux_out;

endmodule

module hamming_code (
  input [k-1:0] in,
  output [n-1:0] out
);

parameter k = 4; // number of input signals
parameter n = 7; // number of output signals (must satisfy n = 2^r - 1 where r is an integer)

// Define parity bit positions
integer i, j;
reg [3:0] parity_pos;
initial begin
  parity_pos[0] = 1;
  for (i = 1; i < 4; i = i + 1) begin
    parity_pos[i] = parity_pos[i-1] << 1;
  end
end

// Encoder
reg [k-1:0] data_bits;
reg [n-k-1:0] parity_bits;
wire [n-1:0] encoded_bits;
assign encoded_bits = {parity_bits, data_bits};
always @* begin
  for (i = 0; i < k; i = i + 1) begin
    data_bits[i] = in[i];
  end
  for (i = 0; i < n-k; i = i + 1) begin
    parity_bits[i] = 0;
    for (j = 0; j < k; j = j + 1) begin
      if (parity_pos[i] & (j+1)) begin
        parity_bits[i] = parity_bits[i] ^ data_bits[j];
      end
    end
  end
end

// Decoder
reg [n-1:0] received_bits;
reg [k-1:0] corrected_bits;
wire error_detected;
assign error_detected = (received_bits ^ encoded_bits) != 0;
always @* begin
  for (i = 0; i < n; i = i + 1) begin
    received_bits[i] = out[i];
  end
  if (error_detected) begin
    for (i = 0; i < n; i = i + 1) begin
      if (parity_pos & (i+1)) begin
        corrected_bits[i] = received_bits[i] ^ 1;
      end else begin
        corrected_bits[i] = received_bits[i];
      end
    end
  end else begin
    for (i = 0; i < k; i = i + 1) begin
      corrected_bits[i] = received_bits[i+n-k];
    end
  end
end

endmodule

module iq_comp(
    input clk,
    input RESETn,
    input freeze_iqcomp,
    input [1:0] op_mode,
    input signed [3:0] Ix,
    input signed [3:0] Qx,
    input signed [12:0] Wr_in,
    input signed [12:0] Wj_in,
    output signed [3:0] Iy,
    output signed [3:0] Qy,
    output wire settled,
    output signed [12:0] Wr,
    output signed [12:0] Wj
);

    reg signed [3:0] Iy_reg;
    reg signed [3:0] Qy_reg;
    reg signed [12:0] Wr_reg;
    reg signed [12:0] Wj_reg;
    reg settled_reg;

    always @(posedge clk) begin
        if (RESETn == 0) begin
            Iy_reg <= 4'd0;
            Qy_reg <= 4'd0;
            Wr_reg <= 13'd0;
            Wj_reg <= 13'd0;
            settled_reg <= 0;
        end else if (freeze_iqcomp == 0) begin
            Iy_reg <= Ix - Wr_in * Qx;
            Qy_reg <= Qx + Wj_in * Ix;
            Wr_reg <= Wr_in;
            Wj_reg <= Wj_in;
            settled_reg <= 1;
        end else begin
            settled_reg <= 0;
        end
    end

    assign Iy = Iy_reg;
    assign Qy = Qy_reg;
    assign Wr = Wr_reg;
    assign Wj = Wj_reg;
    assign settled = settled_reg;

endmodule

module comparator (
    input [1:0] A,
    input [1:0] B,
    output reg [1:0] out
);
    always @(*) begin
        if (A > B) begin
            out <= 2'b01;
        end else if (A < B) begin
            out <= 2'b10;
        end else begin
            out <= 2'b00;
        end
    end
endmodule

module subtractor (
    input [1:0] A,
    input [1:0] B,
    output reg [2:0] out
);
    reg [1:0] A_comp;
    assign A_comp = ~A + 2'b1;

    always @(*) begin
        out[2] = 0;
        if (A < B) begin
            out[2] = 1;
            out[1:0] = A_comp + B;
        end else begin
            out[1:0] = A - B;
        end
    end
endmodule

module top_module (
    input [1:0] A,
    input [1:0] B,
    output reg [2:0] out
);
    wire [1:0] comp_out;
    comparator comp(.A(A), .B(B), .out(comp_out));
    subtractor sub(.A(comp_out), .B(2'b01), .out(out));

    always @(*) begin
        if (out[2] == 1) begin
            out = ~out[1:0] + 3'b001;
        end
    end
endmodule

module counter_4bit(
    input clk,
    input rst,
    output reg [3:0] count,
    output reg max_reached
);

    always @(posedge clk or posedge rst) begin
        if(rst) begin
            count <= 4'b0000;
            max_reached <= 0;
        end
        else begin
            if(count == 4'b1111) begin
                count <= 4'b0000;
                max_reached <= 1;
            end
            else begin
                count <= count + 1;
                max_reached <= 0;
            end
        end
    end

endmodule

module counter(clk, rst, up_down, enable, count);

    input clk;
    input rst;
    input up_down;
    input enable;
    output reg [3:0] count;

    always @(posedge clk) begin
        if (rst) begin
            count <= 4'b0;
        end
        else if (enable) begin
            if (up_down) begin
                count <= count + 1;
            end
            else begin
                count <= count - 1;
            end
        end
    end

endmodule

