module CSLA_N4 ( A, B, Ci, S, Co );
  input [3:0] A;
  input [3:0] B;
  output [3:0] S;
  input Ci;
  output Co;

  wire [3:0] S_nocarry;
  wire [3:0] S_carry;
  wire [3:0] Co_nocarry;
  wire [3:0] Co_carry;
