module mux4 (
    input a,
    input b,
    input c,
    input d,
    input [1:0] sel,
    input en,
    output reg [15:0] out
);
    always @(*) begin
        case (sel)
            2'b00: out = a;
            2'b01: out = b;
            2'b10: out = c;
            2'b11: out = d;
        endcase
    end
    assign out = en ? out : 16'b0;
endmodule

module wr_mux
  (
