// Shift register for input data
always @(posedge clk) begin
  if (reset) begin
    data_reg <= 0;
  end else begin
    data_reg <= {data_reg[data_width-2:0], data_in};
  end
end

// Shift register for input CRC
always @(posedge clk) begin
  if (reset) begin
    crc_check <= 0;
  end else begin
    crc_check <= {crc_check[crc_width-2:0], crc_in};
  end
end

// Shift register for generated CRC
always @(posedge clk) begin
  if (reset) begin
    crc_gen <= 0;
  end else begin
    crc_gen <= {crc_gen[crc_width-2:0], crc_reg};
  end
end

// Shift register for shifted input data
always @(posedge clk) begin
  if (reset) begin
    data_in_shifted <= 0;
  end else begin
    data_in_shifted <= {data_in_shifted[data_width-2:0], data_reg};
  end
end

// Shift register for shifted input CRC
always @(posedge clk) begin
  if (reset) begin
    crc_in_shifted <= 0;
  end else begin
    crc_in_shifted <= {crc_in_shifted[crc_width-2:0], crc_check};
  end
end

// Shift register for shifted generated CRC
always @(posedge clk) begin
  if (reset) begin
    crc_gen_shifted <= 0;
  end else begin
    crc_gen_shifted <= {crc_gen_shifted[crc_width-2:0], crc_gen};
  end
end

// Calculation of CRC checksum
always @(posedge clk) begin
  if (reset) begin
    crc_reg <= 0;
  end else begin
    crc_reg <= crc_gen_shifted ^ crc_in_shifted ^ data_in_shifted;
  end
end

// Error detection
assign error_temp = (crc_check_shifted != crc_out);

// Shift register for shifted checked CRC
always @(posedge clk) begin
  if (reset) begin
    crc_check_shifted <= 0;
  end else begin
    crc_check_shifted <= {crc_check_shifted[crc_width-2:0], crc_check};
  end
end

endmodule

module shift_register (
    input clk,
    input [3:0] data_in,
    input shift_right,
    input load,
    output reg [3:0] data_out
);

reg [3:0] register;

always @(posedge clk) begin
    if (load) begin
        register <= data_in;
    end else begin
        if (shift_right) begin
            register <= {register[2:0], register[3]};
        end else begin
            register <= {register[1:3], register[0]};
        end
    end
end

assign data_out = register;

endmodule

module LZW (
  input clk,
  input rst,
  input [7:0] in,
  output reg [15:0] out
);

  reg [11:0] dictionary [0:4095];
  reg [11:0] next_code;
  reg [7:0] current_string;
  reg [11:0] new_string;
  reg [11:0] code;
  reg [11:0] prev_code;
  reg [7:0] first_char;
  reg [1:0] state;

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      state <= 2'b00;
      next_code <= 12'h100;
      current_string <= 8'h00;
      prev_code <= 12'h000;
    end else begin
      case (state)
        2'b00: begin
          current_string <= in;
          state <= 2'b01;
        end

        2'b01: begin
          new_string <= {current_string, in};
          if (new_string < next_code) begin
            current_string <= new_string;
          end else begin
            code <= current_string;
            out <= {code, 1'b1};
            dictionary[next_code] <= new_string;
            next_code <= next_code + 1;
            current_string <= in;
          end
        end
      endcase
    end
  end

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      state <= 2'b10;
      next_code <= 12'h100;
      prev_code <= 12'h000;
    end else begin
      case (state)
        2'b10: begin
          code <= in;
          if (code < next_code) begin
            out <= dictionary[code];
            first_char <= out[7:0];
            state <= 2'b11;
          end
        end

        2'b11: begin
          new_string <= {first_char, in};
          dictionary[next_code] <= new_string;
          next_code <= next_code + 1;
          prev_code <= code;
          state <= 2'b10;
        end
      endcase
    end
  end

endmodule

