                            cnt <= 'h0;
                            bps_sel <= ~sign_sel;
                            sign_sel <= ~sign_sel;
                            tran_cnt <= tran_cnt + 1'b1;
                          end else begin
                            cnt <= cnt + 1'b1;
                            bps_sel <= 1'b0;
                          end
                    3'h3: if (cnt == bps57600_2) begin
                            cnt <= 'h0;
                            bps_sel <= ~sign_sel;
                            sign_sel <= ~sign_sel;
                            tran_cnt <= tran_cnt + 1'b1;
                          end else begin
                            cnt <= cnt + 1'b1;
                            bps_sel <= 1'b0;
                          end
                    3'h4: if (cnt == bps115200_2) begin
                            cnt <= 'h0;
                            bps_sel <= ~sign_sel;
                            sign_sel <= ~sign_sel;
                            tran_cnt <= tran_cnt + 1'b1;
