module carry_select_adder(
    input [99:0] a, b,
    input cin,
    output [99:0] sum,
    output cout
);

wire [99:0] p, g;
wire [99:0] c;
wire [99:0] s;

genvar i;

generate
    for (i = 0; i < 100; i = i + 1) begin : gen
        assign p[i] = a[i] | b[i];
        assign g[i] = a[i] & b[i];
        assign c[i] = (i == 0) ? cin : (g[i-1] | (p[i-1] & c[i-1]));
        assign s[i] = a[i] ^ b[i] ^ c[i];
    end
endgenerate

assign sum = s;
assign cout = c[99];

endmodule

