module PCSCLKDIV (
	input CLKI, RST, SEL2, SEL1, SEL0,
	output CDIV1, CDIVX
);

	parameter GSR = "DISABLED";

	reg [3:0] counter;
	reg [2:0] divisor;

	always @ (posedge CLKI or negedge RST) begin
		if (RST == 0) begin
			counter <= 0;
			divisor <= 0;
		end
		else begin
			if (GSR == "ENABLED") begin
				if (rst == 1) begin
					counter <= 0;
					divisor <= 0;
				end
			end

			case ({SEL2, SEL1, SEL0})
				3'b000: divisor <= 2;
				3'b001: divisor <= 3;
				3'b010: divisor <= 4;
				3'b011: divisor <= 5;
				3'b100: divisor <= 6;
				3'b101: divisor <= 7;
				3'b110: divisor <= 8;
				3'b111: divisor <= 9;
			endcase

			if (counter == divisor - 1) begin
				CDIV1 <= ~CDIV1;
				CDIVX <= ~CDIVX;
				counter <= 0;
			end
			else begin
				counter <= counter + 1;
			end
		end
	end

	assign CDIV1 = 1'b0;
	assign CDIVX = 1'b0;

endmodule

module fifo_24bit(
  input clk,
  input rst,
  input [23:0] din,
  input wr_en,
  input rd_en,
  output [23:0] dout,
  output full,
  output empty
);

  // Parameters
  parameter ADDR_WIDTH = 13;
  parameter DATA_WIDTH = 24;
  parameter FIFO_DEPTH = 4096;

  // Internal signals
  reg [ADDR_WIDTH-1:0] wr_ptr;
  reg [ADDR_WIDTH-1:0] rd_ptr;
  reg [ADDR_WIDTH-1:0] mem_addr;
  reg [DATA_WIDTH-1:0] mem [0:FIFO_DEPTH-1];
  wire [ADDR_WIDTH-1:0] next_wr_ptr;
  wire [ADDR_WIDTH-1:0] next_rd_ptr;
  wire full_flag;
  wire empty_flag;

  // Full and empty flags
  assign full = full_flag;
  assign empty = empty_flag;

  // Write pointer
  always @(posedge clk) begin
    if (rst) begin
      wr_ptr <= 0;
    end else if (wr_en && !full_flag) begin
      wr_ptr <= next_wr_ptr;
    end
  end

  // Read pointer
  always @(posedge clk) begin
    if (rst) begin
      rd_ptr <= 0;
    end else if (rd_en && !empty_flag) begin
      rd_ptr <= next_rd_ptr;
    end
  end

  // Next write pointer
  assign next_wr_ptr = (wr_ptr == FIFO_DEPTH-1) ? 0 : wr_ptr + 1;

  // Next read pointer
  assign next_rd_ptr = (rd_ptr == FIFO_DEPTH-1) ? 0 : rd_ptr + 1;

  // Full and empty flags
  assign full_flag = (next_wr_ptr == rd_ptr);
  assign empty_flag = (wr_ptr == rd_ptr);

  // Memory address
  always @(*) begin
    mem_addr = (wr_en && !full_flag) ? wr_ptr : rd_ptr;
  end

  // Read and write operations
  always @(posedge clk) begin
    if (rst) begin
      mem <= 0;
    end else if (wr_en && !full_flag) begin
      mem[mem_addr] <= din;
    end else if (rd_en && !empty_flag) begin
      dout <= mem[mem_addr];
    end
  end

endmodule

module driver_vga_640x480(clk_vga, hs, vs, hc_visible, vc_visible);
	input clk_vga;
	output hs, vs;
	output [9:0] hc_visible;
	output [9:0] vc_visible;

	parameter hpixels = 1360;
	parameter vlines = 805;
	parameter hfp = 64;
	parameter hsc = 104;
	parameter hbp = 168;
	parameter vfp = 3;
	parameter vsc = 4;
	parameter vbp = 30;

	reg [9:0] hc, hc_next, vc, vc_next;

	assign hc_visible = ((hc < (hpixels - hfp)) && (hc > (hsc + hbp))) ? (hc - (hsc + hbp)) : 10'd0;
	assign vc_visible = ((vc < (vlines - vfp)) && (vc > (vsc + vbp))) ? (vc - (vsc + vbp)) : 10'd0;

	always @(*) begin
		if(hc == hpixels)
			hc_next = 10'd0;
		else
			hc_next = hc + 10'd1;
	end

	always @(*) begin
		if(hc == 10'd0) begin
			if(vc == vlines)
				vc_next = 10'd0;
			else
				vc_next = vc + 10'd1;
		end else
			vc_next = vc;
	end

	always @(posedge clk_vga) begin
		hc <= hc_next;
		vc <= vc_next;
	end

	assign hs = (hc < hsc) ? 1'b0 : 1'b1;
	assign vs = (vc < vsc) ? 1'b0 : 1'b1;

endmodule

module PLL (
  input ref_clk,
  input reset,
  input enable,
  output locked_clk
);

parameter N = 2; // multiplication factor
parameter M = 1; // division factor

// Phase detector
reg pd_out;
always @(posedge ref_clk or posedge locked_clk) begin
  pd_out <= ref_clk ^ locked_clk;
end

// Charge pump
reg [1:0] cp_out;
always @(posedge pd_out) begin
  if (pd_out) begin
    cp_out <= cp_out + 2'b01;
  end else begin
    cp_out <= cp_out - 2'b01;
  end
end

// Loop filter
reg [7:0] lf_out;
always @(posedge ref_clk) begin
  lf_out <= lf_out + cp_out;
end

// Voltage-controlled oscillator (VCO)
reg [7:0] vco_count;
always @(posedge ref_clk) begin
  if (enable) begin
    vco_count <= vco_count + lf_out;
  end else begin
    vco_count <= 8'h00;
  end
end

// Locked clock output
assign locked_clk = vco_count[7:0] == 8'h00 ? 1'b1 : 1'b0;

// Reset logic
always @(posedge ref_clk) begin
  if (reset) begin
    cp_out <= 2'b00;
    lf_out <= 8'h00;
    vco_count <= 8'h00;
  end
end

endmodule

