module ps2( input Rx, CLKOUT, 
            output reg Rx_error, 
            output [7:0] DATA, 
            output reg DONE);
    reg [8:0] regis;
    reg [7:0] regis0;
    reg [3:0] i;
    reg [3:0] j;
    reg init;

    initial begin
        i = 0;
        j = 0;
        init = 0;
        regis = 0;
        regis0 = 0;
        Rx_error = 0;
        DONE = 0;
    end

    always @(posedge CLKOUT) begin
        if (!Rx && !i) begin
            init <= 1;
        end
        if (init) begin
            regis[i] <= Rx;
            i <= i + 1;
            if (regis[i] && (i < 8)) begin
                j <= j + 1;
            end
        end
        if (i == 9) begin
            if (((j % 2) && (regis[8])) || (!(j % 2) && (!regis[8]))) begin
                Rx_error <= 0;
                regis0 <= {regis[7:0]};
                DONE <= 1;
            end
            else begin
                Rx_error <= 1;
                regis0 <= 0;
                DONE <= 0;
            end
            j <= 0;
            i <= 0;
            init <= 0;
        end
    end

    assign DATA = regis0;
endmodule

module stratixv_read_fifo (
                           datain,
                           wclk,
                           we,
                           rclk,
                           re,
                           areset,
                           plus2,
                           dataout
                          );

    parameter use_half_rate_read = "false";
    parameter sim_wclk_pre_delay = 0;

    reg [1:0] fifo [7:0]; // 8-entry FIFO
    reg [2:0] head = 0;
    reg [2:0] tail = 0;
    reg [2:0] count = 0;

    input [1:0] datain; 
    input wclk;
    input we;
    input rclk;
    input re;
    input areset;
    input plus2;

    output [3:0]dataout;

    always @(posedge wclk) begin
        if (we) begin
            fifo[head] <= datain;
            head <= (head == 7) ? 0 : head + 1;
            count <= count + 1;
        end
    end

    always @(posedge rclk) begin
        if (re) begin
            if (count > 0) begin
                dataout <= (plus2) ? fifo[tail] + 2 : fifo[tail];
                tail <= (tail == 7) ? 0 : tail + 1;
                count <= count - 1;
            end
        end
    end

    always @(posedge areset) begin
        if (areset) begin
            head <= 0;
            tail <= 0;
            count <= 0;
        end
    end

endmodule

