module binary_multiplier (
    input [7:0] a,
    input [7:0] b,
    output reg [15:0] result
);

reg [7:0] a_reg;
reg [7:0] b_reg;
reg [15:0] product_reg;
reg [3:0] stage;

always @(*) begin
    case (stage)
        0: begin
            a_reg = a;
            b_reg = b;
            product_reg = 0;
        end
        1: begin
            product_reg = {a_reg[0], 7'b0} + (b_reg << 1);
            a_reg = a_reg >> 1;
            stage = 2;
        end
        2: begin
            product_reg = {a_reg[0], 7'b0} + (b_reg << 1) + product_reg;
            a_reg = a_reg >> 1;
            stage = 3;
        end
        3: begin
            product_reg = {a_reg[0], 7'b0} + (b_reg << 1) + product_reg;
            a_reg = a_reg >> 1;
            stage = 4;
