            stage = 5;
        end
        5: begin
            product_reg = {a_reg[0], 7'b0} + (b_reg << 1) + product_reg;
            a_reg = a_reg >> 1;
            stage = 6;
        end
        6: begin
            product_reg = {a_reg[0], 7'b0} + (b_reg << 1) + product_reg;
            a_reg = a_reg >> 1;
            stage = 7;
        end
        7: begin
            product_reg = {a_reg[0], 7'b0} + (b_reg << 1) + product_reg;
            a_reg = a_reg >> 1;
            stage = 8;
        end
        8: begin
            product_reg = {a_reg[0], 7'b0} + (b_reg << 1) + product_reg;
            a_reg = a_reg >> 1;
            stage = 9;
        end
        9: begin
            product_reg = {a_reg[0], 7'b0} + (b_reg << 1) + product_reg;
            a_reg = a_reg >> 1;
            stage = 10;
        end
        10: begin
            product_reg = {a_reg[0], 7'b0} + (b_reg << 1) + product_reg;
            a_reg = a_reg >> 1;
            stage = 11;
        end
        11: begin
            product_reg = {a_reg[0], 7'b0} + (b_reg << 1) + product_reg;
            a_reg = a_reg >> 1;
            stage = 12;
        end
        12: begin
            product_reg = {a_reg[0], 7'b0} + (b_reg << 1) + product_reg;
            a_reg = a_reg >> 1;
            stage = 13;
        end
        13: begin
            product_reg = {a_reg[0], 7'b0} + (b_reg << 1) + product_reg;
            a_reg = a_reg >> 1;
            stage = 14;
        end
        14: begin
            product_reg = {a_reg[0], 7'b0} + (b_reg << 1) + product_reg;
