            stage = 15;
        end
        15: begin
            product_reg = {a_reg[0], 7'b0} + (b_reg << 1) + product_reg;
            a_reg = a_reg >> 1;
            stage = 16;
        end
        16: begin
            product_reg = {a_reg[0], 7'b0} + (b_reg << 1) + product_reg;
            result = product_reg;
            stage = 0;
        end
    endcase
end

endmodule

