module addsub(/*AUTOARG*/
	// Outputs
	data_c,overflow,
	// Inputs
	data_a, data_b, sign, addsub
	);

	input  [31:0]    data_a;
	input  [31:0] 	 data_b;
	input 			 sign;
	input 			 addsub;

	output           overflow;
	output reg  [31:0] data_c;

	reg [32:0] temp;

	always @(*) begin
		if (addsub == 1) begin // subtraction
			if (sign == 1) begin // signed subtraction
				if (data_a < data_b) begin
					temp = {32'h0, data_b} - {32'h0, data_a};
					data_c = -temp[31:0];
					overflow = 1;
				end else begin
					temp = {32'h0, data_a} - {32'h0, data_b};
					data_c = temp[31:0];
					overflow = 0;
				end
			end else begin // unsigned subtraction
				if (data_a < data_b) begin
					temp = {32'h0, data_b} - {32'h0, data_a};
					data_c = temp[31:0];
					overflow = 1;
				end else begin
					temp = {32'h0, data_a} - {32'h0, data_b};
					data_c = temp[31:0];
					overflow = 0;
				end
			end
		end else begin // addition
			if (sign == 1) begin // signed addition
				temp = {32'h0, data_a[31] ^ sign, data_a[30:0]} + {32'h0, data_b[31] ^ sign, data_b[30:0]};
				if (temp[32] != temp[31]) begin
					overflow = 1;
				end else begin
					overflow = 0;
				end
				data_c = temp[31:0];
			end else begin // unsigned addition
				temp = {32'h0, data_a} + {32'h0, data_b};
				if (temp[32] != 0) begin
					overflow = 1;
				end else begin
					overflow = 0;
				end
				data_c = temp[31:0];
			end
		end
	end

endmodule

module LUT_4(in_3,in_2,in_1,in_0,out);

   //Truth table parameter represents the default function of the LUT.
   //The most significant bit is the output when all inputs are logic one.
   parameter Truth_table=16'b0000000000000000; 

   input in_0,in_1,in_2,in_3;
   output reg out;
   integer     selected_row;
   wire [3:0]  a;

   interconnect inter0(in_0 , a[0]);
   interconnect inter1(in_1 , a[1]);
   interconnect inter2(in_2 , a[2]);
   interconnect inter3(in_3 , a[3]);

   always@(a[0], a[1], a[2], a[3])
     begin
	selected_row = {a[3], a[2], a[1], a[0]};
	out = Truth_table[selected_row];
     end

endmodule

module snes_bus_sync (
    input clk,           // clock (40 MHz and reset)
    input rst_n,
    input [7:0] PA,      // RAW SNES addr bus
    output reg [7:0] PA_sync,
    input [7:0] D,
    output reg [7:0] D_sync,
    output reg event_latch
);

reg [7:0] PA_reg;
reg [7:0] D_reg;
reg PARD_n_reg;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        PA_sync <= 8'h00;
        D_sync <= 8'h00;
        PA_reg <= 8'h00;
        D_reg <= 8'h00;
        PARD_n_reg <= 1'b1;
        event_latch <= 1'b0;
    end
    else begin
        PA_sync <= PA_reg;
        D_sync <= D_reg;
        PARD_n_reg <= $random % 2;
        if (PA_reg != PA) begin
            PA_reg <= PA;
            event_latch <= 1'b1;
        end
        else begin
            event_latch <= 1'b0;
        end
        if (PARD_n_reg) begin
            D_reg <= D;
        end
    end
end

endmodule

module TimeHoldOver_Qsys_pps_interrupt (
  input   [1:0] address,
  input         chipselect,
  input         clk,
  input         in_port,
  input         reset_n,
  input         write_n,
  input  [31:0] writedata,
  output        irq,
  output [31:0] readdata
);

  wire clk_en;
  reg  d1_data_in;
  reg  d2_data_in;
  wire data_in;
  reg  edge_capture;
  wire edge_capture_wr_strobe;
  wire edge_detect;
  wire irq;
  reg  irq_mask;
  wire read_mux_out;

  assign clk_en = 1;
  assign read_mux_out = ({1 {(address == 0)}} & data_in) |
                        ({1 {(address == 2)}} & irq_mask) |
                        ({1 {(address == 3)}} & edge_capture);

  always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
      readdata <= 0;
    end else if (clk_en) begin
      readdata <= {32'b0, read_mux_out};
    end
  end

  assign data_in = in_port;

  always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
      irq_mask <= 0;
    end else if (chipselect && !write_n && (address == 2)) begin
      irq_mask <= writedata;
    end
  end

  assign irq = |(edge_capture & irq_mask);
  assign edge_capture_wr_strobe = chipselect && !write_n && (address == 3);

  always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
      edge_capture <= 0;
    end else if (clk_en) begin
      if (edge_capture_wr_strobe) begin
        edge_capture <= 0;
      end else if (edge_detect) begin
        edge_capture <= -1;
      end
    end
  end

  always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
      d1_data_in <= 0;
      d2_data_in <= 0;
    end else if (clk_en) begin
      d1_data_in <= data_in;
      d2_data_in <= d1_data_in;
    end
  end

  assign edge_detect = d1_data_in & ~d2_data_in;

endmodule

module hpdmc_banktimer(
	input sys_clk,
	input sdram_rst,
	input tim_cas,
	input [1:0] tim_wr,
	input read,
	input write,
	output reg precharge_safe
);

reg [3:0] counter;

always @(posedge sys_clk) begin
	if(sdram_rst) begin
		counter <= 4'd0;
		precharge_safe <= 1'b1;
	end else begin
		if(read) begin
			counter <= 4'd8;
			precharge_safe <= 1'b0;
		end else if(write) begin
			counter <= {2'b10, tim_wr};
			precharge_safe <= 1'b0;
		end else begin
			if(counter == 4'b1) precharge_safe <= 1'b1;
			if(~precharge_safe) counter <= counter - 4'b1;
		end
	end
end

