module top_module (
    input [7:0] a,
    input [7:0] b,
    output reg [15:0] product,
    output reg overflow
);

wire [3:0] a_low = a[3:0];
wire [3:0] a_high = a[7:4];
wire [3:0] b_low = b[3:0];
wire [3:0] b_high = b[7:4];

wire [7:0] p0 = a_low * b_low;
wire [7:0] p1 = a_low * b_high;
wire [7:0] p2 = a_high * b_low;
wire [7:0] p3 = a_high * b_high;

wire [15:0] s0, s1, s2, s3, s4, s5, s6;
wire c0, c1, c2, c3, c4, c5;

adder adder0(.a({8'd0, p0}), .b({8'd0, p1}), .cin(1'b0), .sum(s0), .cout(c0));
adder adder1(.a({8'd0, p2}), .b({8'd0, p3}), .cin(1'b0), .sum(s1), .cout(c1));
adder adder2(.a({s0, 8'd0}), .b({s1, 8'd0}), .cin(c0), .sum(s2), .cout(c2));
adder adder3(.a({s2, 8'd0}), .b({8'd0, p2}), .cin(c2), .sum(s3), .cout(c3));
adder adder4(.a({s3, 8'd0}), .b({8'd0, p1}), .cin(c3), .sum(s4), .cout(c4));
adder adder5(.a({s4, 8'd0}), .b({8'd0, p0}), .cin(c4), .sum(s5), .cout(c5));
adder adder6(.a({s5, 8'd0}), .b({8'd0, 8'd0}), .cin(c5), .sum(product), .cout(overflow));

overflow_detector detector(.product(product), .overflow(overflow));

endmodule

module adder (
    input [15:0] a,
    input [15:0] b,
    input cin,
    output [15:0] sum,
    output cout
);

wire [3:0] a_low = a[3:0];
wire [3:0] a_high = a[7:4];
wire [3:0] b_low = b[3:0];
wire [3:0] b_high = b[7:4];

wire [3:0] s0 = a_low + b_low;
wire [3:0] s1 = a_high + b_high;
wire [3:0] s2 = a_low + b_high;
wire [3:0] s3 = a_high + b_low;

wire [3:0] c0 = s0[3] & s1[0];
wire [3:0] c1 = s2[3] & s3[0];

assign sum = {c1, s1[3:0], s0[3:0]};
assign cout = c0 | c1 | (s0[3] & s2[3]);

endmodule

module overflow_detector (
    input [15:0] product,
    output reg overflow
);

parameter LIMIT = 255;

assign overflow = (product > LIMIT);

endmodule

module test07(a, b, c, y);
   input signed [3:0] a;
   input signed [1:0] b;
   input [1:0] c;
   output [5:0] y;

   wire [3:0] abs_a;
   assign abs_a = (a < 0) ? (~a + 1) : a;

   wire [5:0] shifted_a;
   assign shifted_a = (b < 0) ? (abs_a << -b) : (abs_a >> b);

   assign y = (c < 0) ? (shifted_a << -c) : (shifted_a >> c);

   assign y = (a < 0) ? (~y + 1) : y;
endmodule

module four_bit_adder (
  input [3:0] a,
  input [3:0] b,
  input cin,
  output [3:0] sum,
  output cout
);

  wire c1, c2, c3;
  wire [3:0] s1, s2, s3;

  // First stage
  full_adder fa1 (
    .a(a[0]),
    .b(b[0]),
    .cin(cin),
    .sum(s1[0]),
    .cout(c1)
  );

  // Second stage
  full_adder fa2 (
    .a(a[1]),
    .b(b[1]),
    .cin(c1),
    .sum(s1[1]),
    .cout(c2)
  );

  // Third stage
  full_adder fa3 (
    .a(a[2]),
    .b(b[2]),
    .cin(c2),
    .sum(s1[2]),
    .cout(c3)
  );

  // Fourth stage
  full_adder fa4 (
    .a(a[3]),
    .b(b[3]),
    .cin(c3),
    .sum(s1[3]),
    .cout(cout)
  );

  assign sum = s1;

endmodule

module full_adder (
  input a,
  input b,
  input cin,
  output sum,
  output cout
);

  wire c1, c2, c3;

  xor x1 (
    .a(a),
    .b(b),
    .xn(c1)
  );

  xor x2 (
    .a(c1),
    .b(cin),
    .xn(sum)
  );

  and a1 (
    .a(a),
    .b(b),
    .zn(c2)
  );

  and a2 (
    .a(c1),
    .b(cin),
    .zn(c3)
  );

  or o1 (
    .a(c2),
    .b(c3),
    .zn(cout)
  );

endmodule

module barrel_shifter_4bit (
    input [3:0] A,
    input load,
    input reset,
    input [1:0] shift,
    output reg [3:0] Q
);

always @(posedge clk) begin
    if (reset) begin
        Q <= 4'b0;
    end else if (load) begin
        Q <= A;
    end else begin
        case (shift)
            2'b00: Q <= Q;
            2'b01: Q <= {Q[2:0], 1'b0};
            2'b10: Q <= {1'b0, Q[3:1]};
            2'b11: begin
                if (shift_dir) begin
                    Q <= {Q[2:0], Q[3]};
                end else begin
                    Q <= {Q[0], Q[3:1]};
                end
            end
        endcase
    end
end

endmodule

module pipelined_shift_register(
    input clk,
    input areset_n,  // async active-low reset to zero
    input load,
    input ena,
    input [3:0] data,
    output reg [3:0] q);

    reg [3:0] pipe_reg [0:1];  // 2-stage pipeline
    reg [1:0] pipe_sel = 0;     // pipeline select signal

    always @(posedge clk or negedge areset_n) begin
        if (~areset_n) begin
            pipe_reg[0] <= 4'b0;
            pipe_reg[1] <= 4'b0;
            pipe_sel <= 0;
            q <= 4'b0;
        end
        else begin
            if (load) begin
                pipe_reg[0] <= data;
                pipe_sel <= 1;
            end
            else if (ena) begin
                pipe_reg[1] <= {pipe_reg[0][2:0], 1'b0};
                pipe_sel <= 0;
            end
            q <= pipe_reg[pipe_sel];
        end
    end

endmodule

module byte_counter(
    input wire [15:0] in,
    input [254:0] in_vec,
    output wire [7:0] out
);

// Split input word into two bytes
wire [7:0] upper_byte = in[15:8];
wire [7:0] lower_byte = in[7:0];

// Count number of 1's in upper byte
wire [7:0] upper_count;
barrel_shifter barrel_upper(.in(upper_byte), .out(upper_count));
binary_tree_adder adder_upper(.in(upper_count), .out(out[7]));

// Count number of 1's in lower byte
wire [7:0] lower_count;
barrel_shifter barrel_lower(.in(lower_byte), .out(lower_count));
binary_tree_adder adder_lower(.in(lower_count), .out(out[6]));

// Count number of 1's in input vector
wire [7:0] vec_count;
barrel_shifter barrel_vec(.in(in_vec), .out(vec_count));
binary_tree_adder adder_vec(.in(vec_count), .out(out[5:0]));

// Add upper and lower byte counts to get final output
assign out = out[7:6] + out[5:0];

endmodule

module barrel_shifter(
    input [7:0] in,
    output [7:0] out
);

// Shift input left by 1, 2, 4, 8 bits and add results
wire [7:0] shift1 = {in[6:0], 1'b0};
wire [7:0] shift2 = {in[5:0], 2'b00};
wire [7:0] shift4 = {in[3:0], 4'b0000};
wire [7:0] shift8 = {in[7:0], 8'b00000000};
wire [7:0] sum1 = shift1 + in;
wire [7:0] sum2 = shift2 + sum1;
wire [7:0] sum4 = shift4 + sum2;
wire [7:0] sum8 = shift8 + sum4;

// Output sum8
assign out = sum8;

endmodule

module binary_tree_adder(
    input [7:0] in,
    output [7:0] out
);

// Add pairs of adjacent bits until only one bit is left
wire [7:0] sum1 = in[0] + in[1];
wire [7:0] sum2 = in[2] + in[3];
wire [7:0] sum3 = in[4] + in[5];
wire [7:0] sum4 = in[6] + in[7];
wire [7:0] sum5 = sum1 + sum2;
wire [7:0] sum6 = sum3 + sum4;
wire [7:0] sum7 = sum5 + sum6;
wire [7:0] sum8 = sum7[0] + sum7[1] + sum7[2] + sum7[3] + sum7[4] + sum7[5] + sum7[6] + sum7[7];

// Output sum8
assign out = sum8;

endmodule

