  reg [7:0] coreb_reg = 8'h00;
  reg [7:0] coreb_next;
  reg [7:0] globala_reg = 8'h00;
  reg [7:0] globala_next;
  reg [7:0] globalb_reg = 8'h00;
  reg [7:0] globalb_next;

