      2'b00: begin
        state_next = BYPASS ? 2'b01 : 2'b10;
      end
      2'b01: begin
        state_next = 2'b00;
      end
      2'b10: begin
        state_next = 2'b11;
      end
      2'b11: begin
        state_next = 2'b10;
      end
      default: begin
        state_next = 2'b00;
      end
    endcase
  end

  // Feedback loop
  always @ (posedge PLLIN or negedge RESETB) begin
    if (!RESETB) begin
      feedback_reg <= 8'h00;
    end else begin
      feedback_reg <= feedback_next;
    end
  end

  always @ (*) begin
    if (EXTFEEDBACK) begin
      feedback_next = {feedback_reg[6:0], PLLOUTCOREA};
    end else begin
      feedback_next = {feedback_reg[6:0], feedback_reg[7]};
    end
  end

  // Shift register
  always @ (posedge SCLK) begin
    shift_reg <= {shift_reg[6:0], SDI};
  end

  always @ (*) begin
    shift_next = {shift_reg[6:0], shift_reg[7]};
  end

