  always @ (posedge PLLIN) begin
    if (delay_count == delay_count_max) begin
      delay_count <= 0;
    end else begin
      delay_count <= delay_count + 1;
    end
  end

  always @ (*) begin
    delay_next = DYNAMICDELAY + shift_next;
  end

