        opa_nan <= &expa & (|fracta[22:0]);
        opb_nan <= &expb & (|fractb[22:0]);
        opa_inf <= (expa_ff & infa_f_r);
        opb_inf <= (expb_ff & infb_f_r);
        expa_00 <= !(|expa);
        expb_00 <= !(|expb);
        fracta_00 <= !(|fracta);
        fractb_00 <= !(|fractb);
        opa_00 <= expa_00 & fracta_00;
        opb_00 <= expb_00 & fractb_00;
        opa_dn <= expa_00;
        opb_dn <= expb_00;
    end

    assign inf = opa_inf | opb_inf;
    assign ind = ind;
    assign qnan = qnan | qnan_r_b;
    assign snan = snan | snan_r_b;
    assign opa_nan = opa_nan;
    assign opb_nan = opb_nan;
    assign opa_00 = opa_00;
    assign opb_00 = opb_00;
    assign opa_inf = opa_inf;
    assign opb_inf = opb_inf;
    assign opa_dn = opa_dn;
    assign opb_dn = opb_dn;

endmodule

module adler_checksum (
  input [n-1:0] data_in,
  output [15:0] adler_out
);

parameter n = 16; // number of input data values

reg [15:0] s1 = 16'h0001; // initialize s1 to 1
reg [15:0] s2 = 16'h0001; // initialize s2 to 1

integer i; // declare integer variable for loop index

// iterate over input data values and update s1 and s2
// using Adler checksum algorithm
always @(*) begin
  for (i = 0; i < n; i = i + 1) begin
    s1 = (s1 + data_in[i]) % 16'hFFFF;
    s2 = (s2 + s1) % 16'hFFFF;
  end
end

// compute Adler checksum using updated values of s1 and s2
assign adler_out = (s2 << 16) | s1;

endmodule

module vending_machine(
    input clk, reset, coin, button_a, button_b, button_c,
    output reg [1:0] item_dispensed,
    output reg [6:0] display
);

    parameter IDLE = 2'b00, SODA_SELECTED = 2'b01, CHIPS_SELECTED = 2'b10, CANDY_SELECTED = 2'b11;
    parameter SODA_PRICE = 75, CHIPS_PRICE = 75, CANDY_PRICE = 75;

    reg [1:0] state;
    reg [7:0] deposited;

    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            deposited <= 0;
            item_dispensed <= 0;
            display <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (coin) begin
                        deposited <= deposited + 25;
                        display <= deposited;
                    end
                    if (button_a) begin
                        state <= SODA_SELECTED;
                        display <= {deposited, 2'b00};
                    end
                    if (button_b) begin
                        state <= CHIPS_SELECTED;
                        display <= {deposited, 2'b01};
                    end
                    if (button_c) begin
                        state <= CANDY_SELECTED;
                        display <= {deposited, 2'b10};
                    end
                end
                SODA_SELECTED: begin
                    if (coin) begin
                        deposited <= deposited + 25;
                        if (deposited >= SODA_PRICE) begin
                            deposited <= deposited - SODA_PRICE;
                            item_dispensed <= 2'b00;
                            state <= IDLE;
                            display <= 0;
                        end else begin
                            display <= {deposited, 2'b00};
                        end
                    end
                end
                CHIPS_SELECTED: begin
                    if (coin) begin
                        deposited <= deposited + 25;
                        if (deposited >= CHIPS_PRICE) begin
                            deposited <= deposited - CHIPS_PRICE;
                            item_dispensed <= 2'b01;
                            state <= IDLE;
                            display <= 0;
                        end else begin
                            display <= {deposited, 2'b01};
                        end
                    end
                end
                CANDY_SELECTED: begin
                    if (coin) begin
                        deposited <= deposited + 25;
                        if (deposited >= CANDY_PRICE) begin
                            deposited <= deposited - CANDY_PRICE;
                            item_dispensed <= 2'b10;
                            state <= IDLE;
                            display <= 0;
                        end else begin
                            display <= {deposited, 2'b10};
                        end
                    end
                end
            endcase
        end
    end

endmodule

