module priority_encoder (
    input [7:0] in,
    output reg [2:0] out
);
    always @(*) begin
        case (in)
            8'b1_000_000: out = 3'b001;
            8'b01_000_000: out = 3'b010;
            8'b001_000_000: out = 3'b011;
            8'b0001_000_000: out = 3'b100;
            8'b0000_100_000: out = 3'b101;
            8'b0000_010_000: out = 3'b110;
            8'b0000_001_000: out = 3'b111;
            default: out = 3'b000;
        endcase
    end
endmodule

