module pipelined_addsub (
    input [3:0] a,
    input [3:0] b,
    input mode,
    output reg [3:0] out,
    output reg overflow
);

reg [3:0] sum1, sum2;
reg [3:0] diff1, diff2;
reg [3:0] a_reg, b_reg;
reg mode_reg;

always @(*) begin
    a_reg = a;
    b_reg = b;
    mode_reg = mode;
end

// Stage 1: Calculate sum and difference
always @(*) begin
    if (mode_reg == 0) begin
        sum1 = a_reg + b_reg;
        diff1 = a_reg - b_reg;
    end else begin
        sum1 = a_reg - b_reg;
        diff1 = a_reg + b_reg;
    end
end

// Stage 2: Calculate overflow flag
always @(*) begin
    if (mode_reg == 0) begin
        if (sum1[3] != a_reg[3] && sum1[3] != b_reg[3]) begin
            overflow = 1;
        end else begin
            overflow = 0;
        end
    end else begin
        if (diff1[3] != a_reg[3] && diff1[3] == b_reg[3]) begin
            overflow = 1;
        end else begin
            overflow = 0;
        end
    end
end

// Stage 3: Register sum and difference
always @(posedge clk) begin
    sum2 <= sum1;
    diff2 <= diff1;
end

// Stage 4: Output sum or difference based on mode
always @(posedge clk) begin
    if (mode_reg == 0) begin
        out <= sum2;
    end else begin
        out <= diff2;
    end
end

endmodule

module binary_multiplier (
  input [3:0] A,
  input [3:0] B,
  output [7:0] P
);

  // Ripple Carry Adder
  wire [3:0] S;
  wire C_out;
  ripple_carry_adder RCA(A, B, S, C_out);

  // Full Adder
  wire [3:0] partial_products [3:0];
  wire [3:0] FA_sum [3:0];
  wire [3:0] FA_carry [3:0];
  wire [4:0] OR_input;
  wire OR_output;

  // Generate partial products
  assign partial_products[0] = {4'b0000, B[0]};
  assign partial_products[1] = {3'b000, B[1], 1'b0};
  assign partial_products[2] = {2'b00, B[2], 2'b00};
  assign partial_products[3] = {1'b0, B[3], 3'b000};

  // Generate full adders
  genvar i;
  generate
    for (i = 0; i < 4; i = i + 1) begin : FA_gen
      full_adder FA(.A(A), .B(partial_products[i]), .Cin(FA_carry[i]), .Sum(FA_sum[i]), .Cout(FA_carry[i+1]));
    end
  endgenerate

  // Generate OR gate
  assign OR_input = {FA_carry[4], FA_sum};
  assign OR_output = |OR_input;

  // Output
  assign P = {C_out, OR_output, partial_products[0], partial_products[1], partial_products[2], partial_products[3]};

endmodule

