module bitwise_rotation(
    input [25:0] Data_i,
    input select_i,
    input bit_shift_i,
    input clk,
    output reg [25:0] Data_o
);

reg [25:0] temp;

always @(posedge clk) begin
    if (select_i == 0) begin
        temp[25:1] = Data_i[24:0];
        temp[0] = Data_i[25];
    end else begin
        temp[24:0] = Data_i[25:1];
        temp[25] = Data_i[0];
    end

    if (bit_shift_i == 0) begin
        Data_o <= temp;
    end else begin
        if (select_i == 0) begin
            Data_o[25] <= temp[0];
            Data_o[24:0] <= temp[25:1];
        end else begin
            Data_o[0] <= temp[25];
            Data_o[25:1] <= temp[24:0];
        end
    end
end

endmodule

module servo_control_block (
  input [7:0] ctrl,
  input clk,
  output reg [15:0] pos
);

  reg [15:0] count = 0;
  reg [15:0] pulse_width = 0;

  always @(posedge clk) begin
    count <= count + 1;
    if (count >= 20000) begin
      count <= 0;
    end
    if (count < pulse_width) begin
      pos <= 1;
    end else begin
      pos <= 0;
    end
  end

  always @(posedge clk) begin
    if (count == 0) begin
      pulse_width <= ctrl * 8 + 1000;
    end
  end

endmodule

