    if (reset) begin
        lfsr <= 8'hF0;
        d1 <= 8'hAA;
        d2 <= 8'h55;
        d3 <= 8'hA5;
        d4 <= 8'h5A;
        d5 <= 8'h33;
        d6 <= 8'hCC;
        d7 <= 8'hC3;
        d8 <= 8'h3C;
    end else begin
        lfsr <= {lfsr[6:0], lfsr[7]^lfsr[2]};
        d1 <= lfsr == 8'h00 || lfsr == 8'h34 ? 8'hAA : d;
        d2 <= d1;
        d3 <= d2;
        d4 <= d3;
        d5 <= d4;
        d6 <= d5;
        d7 <= d6;
        d8 <= d7;
    end
end

assign q = d8;

