module bit_change_detector (
    input clk,
    input reset,
    input in,
    output reg out
);

reg last_in;

always @(posedge clk) begin
    if (reset) begin
        out <= 1'b0;
        last_in <= 1'b0;
    end
    else begin
        if (in != last_in) begin
            out <= 1'b1;
        end
        else begin
            out <= 1'b0;
        end
        last_in <= in;
    end
end

endmodule
