    output reg [7:0] read_data
);

reg [7:0] mem [0:255];

always @(posedge clk) begin
    if (!rst_n) begin
        read_data <= 8'b0;
    end
    else begin
        if (write_en) begin
            mem[write_addr] <= write_data;
        end
        if (read_en) begin
            read_data <= mem[read_addr];
