module alu_p #(parameter width = 8)
       (output reg [width:0] out,
        input [width-1:0] a,
        input [width-1:0] b,
        input c_in,
        input [2:0] op);

    reg [width:0] result;

    always @* begin
        case (op)
            3'b000: result = a + b + c_in;
            3'b001: result = a - b - ~c_in;
            3'b010: result = a & b;
            3'b011: result = a | b;
            3'b100: result = a ^ b;
            3'b101: result = ~a;
            3'b110: result = ~(a ^ b);
            default: result = 0;
        endcase
    end

    assign out = result[width:0];

endmodule

module greater_value (
    input [3:0] a0,
    input [3:0] a1,
    output [3:0] out
);

    wire [3:0] sum0;
    wire [3:0] sum1;
    wire greater;

    // Two 4-bit adders to generate the sum of the two input values
    adder_4bit adder0(.a(a0), .b(a1), .sum(sum0));
    adder_4bit adder1(.a(a1), .b(a0), .sum(sum1));

    // Comparison module to determine the greater value between the two sums
    greater_than compare(.a(sum0), .b(sum1), .greater(greater));

    // 2-to-1 multiplexer to select the greater value and output it as the final output
    mux_2to1 mux(.a(sum0), .b(sum1), .select(greater), .out(out));

endmodule

module adder_4bit (
    input [3:0] a,
    input [3:0] b,
    output [3:0] sum
);

    assign sum = a + b;

endmodule

module greater_than (
    input [3:0] a,
    input [3:0] b,
    output greater
);

    assign greater = (a > b);

endmodule

module mux_2to1 (
    input [3:0] a,
    input [3:0] b,
    input select,
    output [3:0] out
);

    assign out = select ? b : a;

endmodule

