module peripheral_ultra(clk, rst, d_in, cs, addr, rd, wr, d_out, trigg, echo);

  parameter DATA_ADDR = 4'h4;
  parameter DONE_ADDR = 4'h2;
  parameter ENABLE_ADDR = 4'h0;

  input clk;
  input rst;
  input [15:0] d_in;
  input cs;
  input [3:0] addr;
  input rd;
  input wr;
  output reg [15:0] d_out;
  output trigg;
  output echo;

  reg [5:0] s;
  reg enable;
  wire [7:0] dout;
  wire done;

  ultrasonido ultra(.clk(clk), .reset(rst), .d(dout), .trigg(trigg), .ECHO(echo), .ENABLE(enable), .DONE(done));

  always @(*) begin
    case (addr)
      ENABLE_ADDR: s = (cs && wr) ? 5'b00001 : 5'b00000;
      DONE_ADDR: s = (cs && rd) ? 5'b00010 : 5'b00000;
      DATA_ADDR: s = (cs && rd) ? 5'b00100 : 5'b00000;
      default: s = 5'b00000;
    endcase
  end

  always @(negedge clk) begin
    if (s[0] == 1) begin
      enable <= d_in[0];
    end
  end

  always @(negedge clk) begin
    case (s)
      5'b00010: d_out <= {8'h00, done};
      5'b00100: d_out <= {8'h00, dout};
      default: d_out <= 16'h0000;
    endcase
  end

endmodule

module ripple_shift (
    input clk,
    input reset,
    input [3:0] A,
    input [3:0] B,
    input cin,
    input [2:0] parallel_load,
    input shift,
    input control,
    output [3:0] sum,
    output cout,
    output reg [2:0] out,
    output [2:0] xor_result
);

    // Ripple Carry Adder
    wire [3:0] ripple_sum;
    wire ripple_cout;
    ripple_adder ripple_adder_inst(.A(A), .B(B), .cin(cin), .sum(ripple_sum), .cout(ripple_cout));

    // Shift Register
    reg [2:0] shift_reg;
    always @(posedge clk) begin
        if (reset) begin
            shift_reg <= 3'b0;
        end else if (parallel_load != 3'b0) begin
            shift_reg <= parallel_load;
        end else if (shift) begin
            if (control) begin
                shift_reg <= {shift_reg[1:0], 1'b0};
            end else begin
                shift_reg <= {1'b0, shift_reg[2:1]};
            end
        end
    end

    // XOR Module
    assign xor_result = ripple_sum ^ shift_reg;

    // Output Assignments
    assign sum = ripple_sum;
    assign cout = ripple_cout;
    assign out = shift_reg;

endmodule

module ripple_adder (
    input [3:0] A,
    input [3:0] B,
    input cin,
    output [3:0] sum,
    output cout
);

    wire [3:0] full_sum;
    wire carry1, carry2, carry3;

    assign {carry1, full_sum[0]} = A[0] + B[0] + cin;
    assign {carry2, full_sum[1]} = A[1] + B[1] + carry1;
    assign {carry3, full_sum[2]} = A[2] + B[2] + carry2;
    assign {cout, full_sum[3]} = A[3] + B[3] + carry3;

    assign sum = full_sum;

endmodule

