module vending_machine (
    input clk,
    input reset,
    input nickel,
    input dime,
    input quarter,
    output candy_dispense,
    output soda_dispense,
    output reg [7:0] display
);

reg [7:0] balance = 0;

assign candy_dispense = (balance >= 10) && (nickel || dime || quarter);
assign soda_dispense = (balance >= 25) && (nickel || dime || quarter);

always @(posedge clk) begin
    if (reset) begin
        balance <= 0;
        display <= 0;
    end
    else begin
        if (nickel) begin
            balance <= balance + 5;
        end
        if (dime) begin
            balance <= balance + 10;
        end
        if (quarter) begin
            balance <= balance + 25;
        end

        if (candy_dispense) begin
            balance <= balance - 10;
        end
        if (soda_dispense) begin
            balance <= balance - 25;
        end

        display <= balance;
    end
end

endmodule

module mux4to1(
    input wire [3:0] in,
    input wire [1:0] sel,
    output reg out
);

    wire [3:0] mux_out;
    wire [3:0] dec_out;

    // 2-to-1 multiplexer
    assign mux_out[0] = (sel[0] == 0) ? in[0] : in[1];
    assign mux_out[1] = (sel[0] == 0) ? in[2] : in[3];

    // 2-bit decoder
    assign dec_out[0] = (sel[1] == 0) ? 1'b1 : 1'b0;
    assign dec_out[1] = (sel[1] == 1) ? 1'b1 : 1'b0;
    assign dec_out[2] = (sel[1] == 2) ? 1'b1 : 1'b0;
    assign dec_out[3] = (sel[1] == 3) ? 1'b1 : 1'b0;

    // Output
    assign out = (dec_out & mux_out);

endmodule

