module display4digit(
    input [15:0] A,
    input clk,
    output [7:0] segments,
    output reg [3:0] digitselect
);

    reg [18:0] counter = 0;
    wire [1:0] toptwo;
    reg [3:0] value4bit;

    always @(posedge clk)
        begin
            counter <= counter + 1'b1;
        end

    assign toptwo[1:0] = counter[18:17];  // (100*10^6 cycles/sec)/(2^17 cycles/refresh) = (763 refreshes/sec)

    always @(*)
        begin
            case(toptwo[1:0])
                2'b00: 
                    begin
                        digitselect <= ~4'b0001;
                        value4bit <= A[3:0];
                    end
                2'b01: 
                    begin
                        digitselect <= ~4'b0010;
                        value4bit <= A[7:4];
                    end
                2'b10: 
                    begin
                        digitselect <= ~4'b0100;
                        value4bit <= A[11:8];
                    end
                default:
                    begin
                        digitselect <= ~4'b1000;
                        value4bit <= A[15:12];
                    end
            endcase
        end

    HexTo7Seg myhexencoder(value4bit, segments);

endmodule

module fsm_3bit_pattern_detection (
  input clk,
  input reset,
  input data,
  output reg match
);

  // Define the states
  parameter S0 = 2'b00;
  parameter S1 = 2'b01;
  parameter S2 = 2'b10;
  parameter Match = 2'b11;

  // Define the state register and next state logic
  reg [1:0] state, next_state;
  always @ (posedge clk, posedge reset) begin
    if (reset) begin
      state <= S0;
    end else begin
      state <= next_state;
    end
  end

  // Define the output logic
  always @ (state) begin
    match = (state == Match);
  end

  // Define the next state logic
  always @ (state, data) begin
    case (state)
      S0: begin
        if (data == 1) begin
          next_state = S1;
        end else begin
          next_state = S0;
        end
      end
      S1: begin
        if (data == 0) begin
          next_state = S2;
        end else begin
          next_state = S0;
        end
      end
      S2: begin
        if (data == 1) begin
          next_state = Match;
        end else begin
          next_state = S0;
        end
      end
      Match: begin
        next_state = S0;
      end
      default: begin
        next_state = S0;
      end
    endcase
  end

endmodule

