module turnoff_ctrl (
  input clk,
  input rst_n,
  input req_compl_i,
  input compl_done_i,
  input cfg_to_turnoff_n,
  output reg cfg_turnoff_ok_n
);

  reg trn_pending;

  // Completion pending check
  always @(posedge clk) begin
    if (!rst_n) begin
      trn_pending <= 0;
    end else begin
      if (!trn_pending && req_compl_i) begin
        trn_pending <= 1'b1;
      end else if (compl_done_i) begin
        trn_pending <= 1'b0;
      end
    end
  end

  // Turn-off OK check
  always @(posedge clk) begin
    if (!rst_n) begin
      cfg_turnoff_ok_n <= 1'b1;
    end else begin
      if (!cfg_to_turnoff_n && !trn_pending) begin
        cfg_turnoff_ok_n <= 1'b0;
      end else begin
        cfg_turnoff_ok_n <= 1'b1;
      end
    end
  end

endmodule

module detect_sequence(
  input clk,
  input data,
  output reg out
);

reg [3:0] state;

always @(posedge clk) begin
  case (state)
    4'b0000: if (data == 1'b0) state <= 4'b0001; else state <= 4'b0000;
    4'b0001: if (data == 1'b1) state <= 4'b0010; else state <= 4'b0000;
    4'b0010: if (data == 1'b1) state <= 4'b0010; else state <= 4'b0011;
    4'b0011: if (data == 1'b0) state <= 4'b0100; else state <= 4'b0000;
    4'b0100: if (data == 1'b1) begin out <= 1'b1; state <= 4'b0100; end else state <= 4'b0000;
    default: state <= 4'b0000;
  endcase
end

endmodule

