module pipelined_full_adder(
  input a,
  input b,
  input carry_in,
  output sum,
  output carry_out
);

  reg p, g, c;

  assign sum = p ^ carry_in;
  assign carry_out = g | (p & carry_in);

  always @ (a, b, carry_in) begin
    p = a ^ b;
    g = a & b;
    c = carry_in;
  end

  always @ (posedge clk) begin
    carry_in <= c;
  end

endmodule

module ripple_carry_adder(
  input [3:0] a,
  input [3:0] b,
  output [3:0] sum,
  output carry_out
);

  wire [3:0] carry;

  pipelined_full_adder fa0(a[0], b[0], 1'b0, sum[0], carry[0]);
  pipelined_full_adder fa1(a[1], b[1], carry[0], sum[1], carry[1]);
  pipelined_full_adder fa2(a[2], b[2], carry[1], sum[2], carry[2]);
  pipelined_full_adder fa3(a[3], b[3], carry[2], sum[3], carry_out);

endmodule

module top_module (
    input [3:0] a,
    input [3:0] b,
    input mode,
    input [15:0] data_in,
    output reg [31:0] final_out
);

    wire [3:0] add_sub_out;
    wire [7:0] comp_concat_out;
    wire [31:0] func_out;

    add_sub add_sub_inst (
        .a(a),
        .b(b),
        .mode(mode),
        .out(add_sub_out)
    );

    complement_concat comp_concat_inst (
        .data_in(data_in),
        .out(comp_concat_out)
    );

    functional_module func_inst (
        .in1(add_sub_out),
        .in2(comp_concat_out),
        .mode(mode),
        .out(func_out)
    );

    always @* begin
        final_out = func_out;
    end

endmodule

module add_sub (
    input [3:0] a,
    input [3:0] b,
    input mode,
    output reg [3:0] out
);

    always @* begin
        if (mode == 1) begin
            out = a + b;
        end else begin
            out = a - b;
        end
    end

endmodule

module complement_concat (
    input [15:0] data_in,
    output reg [7:0] out
);

    assign out = ~data_in[15:8] & data_in[7:0];

endmodule

module functional_module (
    input [3:0] in1,
    input [7:0] in2,
    input mode,
    output reg [31:0] out
);

    always @* begin
        if (mode == 1) begin
            out = in1 + in2;
        end else begin
            out = in1 | in2;
        end
    end

endmodule

module bitwise_and(
    input [7:0] A,
    input [7:0] B,
    output [7:0] Z
);

    assign Z = A & B;

endmodule

module nand_mux_4to1 (
    input [3:0] A,
    input [1:0] S,
    output reg out
);

wire nand1, nand2, nand3, nand4, nand5, nand6;

assign nand1 = ~(S[1] & S[0]);
assign nand2 = ~(S[1] & ~S[0]);
assign nand3 = ~(~S[1] & S[0]);
assign nand4 = ~(~S[1] & ~S[0]);

assign nand5 = ~(nand1 & A[0] & A[1]);
assign nand6 = ~(nand2 & A[1] & A[2]);

assign out = ~(nand3 & A[2] & A[3]) & ~(nand4 & A[3] & A[0]) & ~(nand5) & ~(nand6);

endmodule

module vending_machine(
    input clk,
    input reset,
    input item1,
    input item2,
    input item3,
    input item4,
    input coin,
    input cancel,
    output reg [7:0] price,
    output reg [7:0] money,
    output reg dispense,
    output reg [7:0] change,
    output reg out_of_stock
);

// Define constants
parameter ITEM1_PRICE = 64;
parameter ITEM2_PRICE = 54;
parameter ITEM3_PRICE = 27;
parameter ITEM4_PRICE = 63;
parameter ITEM1_STOCK = 5;
parameter ITEM2_STOCK = 0;
parameter ITEM3_STOCK = 3;
parameter ITEM4_STOCK = 2;

// Define state variables
reg [7:0] current_item_price;
reg [7:0] current_money;
reg [7:0] current_change;
reg [7:0] item1_stock;
reg [7:0] item2_stock;
reg [7:0] item3_stock;
reg [7:0] item4_stock;
reg [1:0] current_state;
reg [1:0] next_state;

// Define state machine states
parameter IDLE_STATE = 2'b00;
parameter SELECT_ITEM_STATE = 2'b01;
parameter INSERT_COIN_STATE = 2'b10;
parameter DISPENSE_ITEM_STATE = 2'b11;

// Define state machine transitions
parameter TRANSITION_IDLE_TO_SELECT_ITEM = 2'b00;
parameter TRANSITION_SELECT_ITEM_TO_INSERT_COIN = 2'b01;
parameter TRANSITION_INSERT_COIN_TO_DISPENSE_ITEM = 2'b10;
parameter TRANSITION_DISPENSE_ITEM_TO_IDLE = 2'b11;

// Define state machine outputs
parameter OUTPUT_NONE = 2'b00;
parameter OUTPUT_DISPENSE = 2'b01;
parameter OUTPUT_RETURN_CHANGE = 2'b10;
parameter OUTPUT_RETURN_MONEY = 2'b11;

// Define state machine logic
always @(posedge clk, posedge reset) begin
    if (reset) begin
        current_item_price <= 0;
        current_money <= 0;
        current_change <= 0;
        item1_stock <= ITEM1_STOCK;
        item2_stock <= ITEM2_STOCK;
        item3_stock <= ITEM3_STOCK;
        item4_stock <= ITEM4_STOCK;
        current_state <= IDLE_STATE;
        next_state <= IDLE_STATE;
        dispense <= 0;
        out_of_stock <= 0;
    end else begin
        current_state <= next_state;
        case (current_state)
            IDLE_STATE: begin
                if (item1) begin
                    current_item_price <= ITEM1_PRICE;
                    next_state <= SELECT_ITEM_STATE;
                end else if (item2) begin
                    current_item_price <= ITEM2_PRICE;
                    next_state <= SELECT_ITEM_STATE;
                end else if (item3) begin
                    current_item_price <= ITEM3_PRICE;
                    next_state <= SELECT_ITEM_STATE;
                end else if (item4) begin
                    current_item_price <= ITEM4_PRICE;
                    next_state <= SELECT_ITEM_STATE;
                end else begin
                    next_state <= IDLE_STATE;
                end
            end
            SELECT_ITEM_STATE: begin
                if (current_item_price == 0) begin
                    next_state <= IDLE_STATE;
                end else if (current_item_price <= current_money) begin
                    next_state <= DISPENSE_ITEM_STATE;
                end else begin
                    next_state <= INSERT_COIN_STATE;
                end
            end
            INSERT_COIN_STATE: begin
                if (cancel) begin
                    next_state <= IDLE_STATE;
                end else if (coin == 5 || coin == 10 || coin == 25 || coin == 50) begin
                    current_money <= current_money + coin;
                    next_state <= SELECT_ITEM_STATE;
                end else begin
                    next_state <= INSERT_COIN_STATE;
                end
            end
            DISPENSE_ITEM_STATE: begin
                if (current_item_price == 0) begin
                    next_state <= IDLE_STATE;
                end else if (current_item_price <= current_money) begin
                    current_change <= current_money - current_item_price;
                    current_money <= 0;
                    dispense <= 1;
                    out_of_stock <= 0;
                    if (item1 && item1_stock > 0) begin
                        item1_stock <= item1_stock - 1;
                    end else if (item2 && item2_stock > 0) begin
                        item2_stock <= item2_stock - 1;
                    end else if (item3 && item3_stock > 0) begin
                        item3_stock <= item3_stock - 1;
                    end else if (item4 && item4_stock > 0) begin
                        item4_stock <= item4_stock - 1;
                    end else begin
                        out_of_stock <= 1;
                    end
                    next_state <= DISPENSE_ITEM_STATE;
                end else begin
                    next_state <= SELECT_ITEM_STATE;
                end
            end
        endcase
    end
end

// Define change and money outputs
always @(*) begin
    if (current_change > 0) begin
        change = current_change;
        money = 0;
    end else begin
        change = 0;
        money = current_money;
    end
end

// Define state machine outputs
always @(*) begin
    case (current_state)
        IDLE_STATE: begin
            dispense = 0;
        end
        SELECT_ITEM_STATE: begin
            dispense = 0;
        end
        INSERT_COIN_STATE: begin
            dispense = 0;
        end
        DISPENSE_ITEM_STATE: begin
            dispense = OUTPUT_DISPENSE;
            if (current_change > 0) begin
                dispense = OUTPUT_RETURN_CHANGE;
            end else if (out_of_stock) begin
                dispense = OUTPUT_RETURN_MONEY;
            end
        end
    endcase
end

endmodule

module PCG (
  input clk_en,
  input [3:0] freq_ctrl,
  input [3:0] duty_ctrl,
  output reg clk
);

parameter f_max = 1_000_000_000;  // 1 GHz
parameter f_min = 1_000_000;      // 1 MHz
parameter d_max = 50;             // 50%
parameter d_min = 10;             // 10%

reg [31:0] count;
reg [31:0] threshold;
reg [31:0] duty_threshold;

always @ (posedge clk or negedge clk) begin
  if (count >= threshold) begin
    count <= 0;
    clk <= ~clk;
  end else begin
    count <= count + 1;
  end
end

always @ (posedge clk or negedge clk) begin
  if (count >= duty_threshold) begin
    duty_threshold <= threshold * (d_min + (duty_ctrl * (d_max - d_min)))/100;
  end else begin
    duty_threshold <= threshold * (d_max - (duty_ctrl * (d_max - d_min)))/100;
  end
end

always @ (posedge clk or negedge clk) begin
  if (clk_en) begin
    threshold <= (f_min + (freq_ctrl * (f_max - f_min))) / 2;
  end else begin
    threshold <= 0;
    duty_threshold <= 0;
    count <= 0;
    clk <= 0;
  end
end

endmodule

module addsub_4bit(A, B, sub, Y);
    input [3:0] A, B;
    input sub;
    output [3:0] Y;

    wire [3:0] X, C;

    // Calculate the 1's complement of B
    wire [3:0] B_1s_comp;
    assign B_1s_comp = ~B;

    // Add 1 to the 1's complement of B to get the 2's complement of B
    wire [3:0] B_2s_comp;
    float_add_sub_altpriority_encoder_3e8 U1(.data({1'b0, 1'b1}), .q(B_2s_comp[0]), .zero(B_2s_comp[0]));
    assign B_2s_comp[0] = sub;
    genvar i;
    generate
        for (i = 1; i < 4; i = i + 1) begin
            float_add_sub_altpriority_encoder_3e8 U2(.data({B_1s_comp[i], B_2s_comp[i-1]}), .q(B_2s_comp[i]), .zero(B_2s_comp[i]));
        end
    endgenerate

    // Perform addition or subtraction based on the value of sub
    assign X[0] = A[0] ^ B_2s_comp[0];
    float_add_sub_altpriority_encoder_3e8 U3(.data({A[1], B_2s_comp[1]}), .q(X[1]), .zero(X[1]));
    float_add_sub_altpriority_encoder_3e8 U4(.data({A[2], B_2s_comp[2]}), .q(X[2]), .zero(X[2]));
    float_add_sub_altpriority_encoder_3e8 U5(.data({A[3], B_2s_comp[3]}), .q(X[3]), .zero(X[3]));

    // Calculate the carry-out
    assign C[0] = (sub & (~X[0])) | (~sub & X[0]);
    float_add_sub_altpriority_encoder_3e8 U6(.data({C[0], X[1]}), .q(C[1]), .zero(C[1]));
    float_add_sub_altpriority_encoder_3e8 U7(.data({C[1], X[2]}), .q(C[2]), .zero(C[2]));
    float_add_sub_altpriority_encoder_3e8 U8(.data({C[2], X[3]}), .q(C[3]), .zero(C[3]));

    // Combine the sum and the carry-out to get the final result
    assign Y[0] = X[0];
    float_add_sub_altpriority_encoder_3e8 U9(.data({X[1], C[0]}), .q(Y[1]), .zero(Y[1]));
    float_add_sub_altpriority_encoder_3e8 U10(.data({X[2], C[1]}), .q(Y[2]), .zero(Y[2]));
    float_add_sub_altpriority_encoder_3e8 U11(.data({X[3], C[2]}), .q(Y[3]), .zero(Y[3]));
endmodule

module dual_port_ram (
    address_a,
    address_b,
    clock,
    data_a,
    data_b,
    wren_a,
    wren_b,
    q_a,
    q_b
);

input [11:0] address_a;
input [11:0] address_b;
input clock;
input [7:0] data_a;
input [7:0] data_b;
input wren_a;
input wren_b;
output reg [7:0] q_a;
output reg [7:0] q_b;

reg [7:0] mem [0:3071];

always @(posedge clock) begin
    if (wren_a) begin
        mem[address_a] <= data_a;
    end
    if (wren_b) begin
        mem[address_b] <= data_b;
    end
    q_a <= mem[address_a];
    q_b <= mem[address_b];
end

endmodule

