module niosii_nios2_gen2_0_cpu_nios2_avalon_reg (
  // inputs:
  address,
  clk,
  debugaccess,
  monitor_error,
  monitor_go,
  monitor_ready,
  reset_n,
  write,
  writedata,

  // outputs:
  oci_ienable,
  oci_reg_readdata,
  oci_single_step_mode,
  ocireg_ers,
  ocireg_mrs,
  take_action_ocireg
);

  output  [31:0] oci_ienable;
  output  [31:0] oci_reg_readdata;
  output         oci_single_step_mode;
  output         ocireg_ers;
  output         ocireg_mrs;
  output         take_action_ocireg;
  input   [8:0]  address;
  input          clk;
  input          debugaccess;
  input          monitor_error;
  input          monitor_go;
  input          monitor_ready;
  input          reset_n;
  input          write;
  input   [31:0] writedata;

  reg     [31:0] oci_ienable;
  reg            oci_single_step_mode;
  wire           oci_reg_00_addressed;
  wire           oci_reg_01_addressed;
  wire    [31:0] oci_reg_readdata;
  wire           ocireg_ers;
  wire           ocireg_mrs;
  wire           ocireg_sstep;
  wire           take_action_oci_intr_mask_reg;
  wire           take_action_ocireg;
  wire           write_strobe;

  assign oci_reg_00_addressed = address == 9'h100;
  assign oci_reg_01_addressed = address == 9'h101;
  assign write_strobe = write & debugaccess;
  assign take_action_ocireg = write_strobe & oci_reg_00_addressed;
  assign take_action_oci_intr_mask_reg = write_strobe & oci_reg_01_addressed;
  assign ocireg_ers = writedata[1];
  assign ocireg_mrs = writedata[0];
  assign ocireg_sstep = writedata[3];
  assign oci_reg_readdata = oci_reg_00_addressed ? {28'b0, oci_single_step_mode, monitor_go, monitor_ready, monitor_error} : oci_reg_01_addressed ? oci_ienable : 32'b0;

  always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
      oci_single_step_mode <= 1'b0;
    end else if (take_action_ocireg) begin
      oci_single_step_mode <= ocireg_sstep;
    end
  end

  always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
      oci_ienable <= 32'b00000000000000000000000000011111;
    end else if (take_action_oci_intr_mask_reg) begin
      oci_ienable <= writedata | ~(32'b00000000000000000000000000011111);
    end
  end

endmodule

module instruction_fetch(
    input wire clk,
    input wire nrst,
    input wire [31:0] addr,
    input wire rd_cmd,
    output wire [31:0] instr_dat,
    output wire busy,
    output wire err_align,
    output wire err_bus,
    output reg [31:0] o_IAddr,
    output reg o_IRdC,
    input wire [31:0] i_IData,
    input wire i_IRdy,
    input wire i_IErr
);

    localparam IDLE = 1'b0;
    localparam WAIT = 1'b1;

    reg [31:0] lch_idata;
    reg state;

    assign err_align = (rd_cmd == 1'b1 && addr[1:0] != 2'b00);

    wire active = (!err_align && !i_IErr && rd_cmd == 1'b1);

    assign busy = ((active || (state == WAIT)) && !i_IRdy);

    assign err_bus = i_IErr;

    always @(*) begin
        o_IAddr = 32'b0;
        o_IRdC = 1'b0;

        if(active) begin
            o_IAddr = addr;
            o_IRdC = 1'b1;
        end
    end

    always @(posedge clk or negedge nrst) begin
        if(!nrst) begin
            state <= IDLE;
            lch_idata <= {32{1'b0}};
        end
        else begin
            if(state == IDLE && (active && i_IRdy)) begin
                lch_idata <= i_IData;
            end
            else if(state == IDLE && (active && !i_IRdy)) begin
                state <= !i_IErr ? WAIT : IDLE;
            end
            else if(state == WAIT && i_IRdy) begin
                state <= IDLE;
                lch_idata <= i_IData;
            end
        end
    end

