module Uart_rx(
    input clk,
    input rst_n,
    input rs232_rx,
    input [3:0] num,
    input sel_data,
    output rx_en,
    output reg tx_en,
    output reg [7:0] rx_data
);

// Internal signals
reg in_1, in_2;
reg [7:0] rx_data_r;

// Detect start bit
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        in_1 <= 1'b1;
        in_2 <= 1'b1;
    end else begin
        in_1 <= rs232_rx;
        in_2 <= in_1;
    end
end

assign rx_en = in_2 & (~in_1);

// Collect data bits
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        rx_data_r <= 8'd0;
        rx_data <= 8'd0;
    end else begin
        if (sel_data) begin
            case (num)
                0: ; // Ignore start bit
                1: rx_data_r[0] <= rs232_rx; // Collect data bits
                2: rx_data_r[1] <= rs232_rx;
                3: rx_data_r[2] <= rs232_rx;
                4: rx_data_r[3] <= rs232_rx;
                5: rx_data_r[4] <= rs232_rx;
                6: rx_data_r[5] <= rs232_rx;
                7: rx_data_r[6] <= rs232_rx;
                8: rx_data_r[7] <= rs232_rx;
                9: rx_data <= rx_data_r; // Store collected data bits
                default: ; // Default case
            endcase
        end
    end
end

// Enable transmission of data
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        tx_en <= 0;
    end else begin
        if ((num == 4'd9) && sel_data) begin
            tx_en <= 1;
        end else begin
            tx_en <= 0;
        end
    end
end

endmodule

module sky130_fd_sc_hs__fa (input A, input B, input CIN, input VPWR, input VGND, output COUT, output SUM);

    reg temp_COUT; // temporary variable to store the value of COUT
    reg temp_SUM; // temporary variable to store the value of SUM

    always @(*) begin
        if((A == 1'b0 || A == 1'b1) && (B == 1'b0 || B == 1'b1) && (CIN == 1'b0 || CIN == 1'b1)) begin
            temp_SUM = A ^ B ^ CIN;
            temp_COUT = (A & B) | (B & CIN) | (CIN & A);
        end
        else begin
            temp_SUM = 1'bx;
            temp_COUT = 1'bx;
        end
    end

    assign SUM = temp_SUM;
    assign COUT = temp_COUT;

endmodule

module twos_complement_adder (
    input [3:0] A,
    input [3:0] B,
    output reg [4:0] C
);

reg [3:0] sum1, sum2;
reg carry;

always @(A, B) begin
    sum1 = A + B;
end

always @(sum1) begin
    sum2 = sum1 + carry;
end

always @(sum2) begin
    if (sum2[3] == 1) begin
        C[4:0] = ~sum2 + 1;
    end else begin
        C[4:0] = sum2;
    end
end

always @(sum1) begin
    carry = (A[3] & B[3]) | (A[3] & ~sum1[3]) | (B[3] & ~sum1[3]);
end

endmodule

