  reg [1:0] gpio_output_reg;
  reg [1:0] gpio_input_reg;

  always @(posedge s_axi_aclk) begin
    if (s_axi_aresetn == 1'b0) begin
      gpio_output_reg <= 2'b0;
      gpio_input_reg <= 2'b0;
    end else if (s_axi_awvalid == 1'b1 && s_axi_wvalid == 1'b1) begin
