      endcase
    end
  end

  assign gpio_io_o = gpio_output_reg;
  assign gpio_io_t = (gpio_output_reg & ~gpio_input_reg) | (~gpio_output_reg & gpio_input_reg);

  assign s_axi_awready = 1'b1;
