  input B,
  input Cin,
  output S,
  output Cout
);

  wire w1, w2, w3;

  assign w1 = A ^ B;
  assign w2 = A & B;
  assign w3 = w1 & Cin;

  assign S = w1 ^ Cin;
  assign Cout = w2 | w3;

endmodule


