module clock_phase_shifter (
  input clk_in,
  input signed [31:0] shift_amount,
  output clk_out
);

  reg [31:0] counter;
  reg delayed_clk;
  reg advanced_clk;

  always @(posedge clk_in) begin
    counter <= (counter == $unsigned({31'b0, shift_amount})) ? 0 : counter + 1;
    delayed_clk <= (counter >= $unsigned({31'b0, shift_amount})) ? 1'b1 : 1'b0;
    advanced_clk <= (counter < $unsigned({31'b0, -shift_amount})) ? 1'b1 : 1'b0;
  end

  assign clk_out = (shift_amount > 0) ? delayed_clk : advanced_clk;

endmodule

module full_adder ( A, B, Ci, S, Co );
  input A, B, Ci;
  output S, Co;
  wire   n1, n2, n3, n4, n5, n6, n7, n8;

  // XOR gates
  XOR2_X1 U1 ( .A(A), .B(B), .ZN(n1) );
  XOR2_X1 U2 ( .A(n1), .B(Ci), .ZN(S) );

  // AND gates
  AND2_X1 U3 ( .A(A), .B(B), .ZN(n2) );
  AND2_X1 U4 ( .A(n1), .B(Ci), .ZN(n3) );
  AND2_X1 U5 ( .A(A), .B(Ci), .ZN(n4) );
  AND2_X1 U6 ( .A(B), .B(Ci), .ZN(n5) );

  // OR gates
  OR2_X1 U7 ( .A(n2), .B(n3), .ZN(Co) );
  OR2_X1 U8 ( .A(n4), .B(n5), .ZN(n6) );
  OR2_X1 U9 ( .A(n6), .B(n3), .ZN(n7) );
  OR2_X1 U10 ( .A(n6), .B(n5), .ZN(n8) );
  OR2_X1 U11 ( .A(n7), .B(n8), .ZN(Co) );
endmodule

module binary_to_excess_3(
    input [3:0] B, // 4-bit binary input
    output [3:0] E // 4-bit excess-3 output
);

    // Look-up table for excess-3 code generation
    assign E[3] = B[3] ^ B[2] ^ B[1];
    assign E[2] = B[2] ^ B[1] ^ B[0];
    assign E[1] = B[3] ^ B[1] ^ B[0];
    assign E[0] = B[3] ^ B[2] ^ B[0];

endmodule

module decoder_4_to_16(
    input [3:0] A, B, C, D, // 4-bit input
    output [15:0] Y // 16-bit output
);

    // 4-to-16 decoder implementation
    assign Y[0] = ~(A & B & C & D);
    assign Y[1] = ~(~A & B & C & D);
    assign Y[2] = ~(A & ~B & C & D);
    assign Y[3] = ~(~A & ~B & C & D);
    assign Y[4] = ~(A & B & ~C & D);
    assign Y[5] = ~(~A & B & ~C & D);
