    input reset,   // Synchronous active-high reset
    input a, // First input for XOR gate
    input b, // Second input for XOR gate
    input select, // Select input to choose between XOR gate and BCD counter
    output [3:1] ena, // Enable signal for upper three digits of BCD counter
    output [15:0] q // 4-digit BCD counter output or XOR gate output
);

    // XOR gate implementation using NAND and NOR gates
    wire xor_output;
    assign xor_output = ~(~(a & ~(b)) & ~(~(b) & ~(a)));

    // BCD counter implementation using Johnson counter and combinational circuit
    reg [3:0] johnson_q;
    reg [3:0] bcd_q;
    always @(posedge clk) begin
        if (reset) begin
            johnson_q <= 4'b0001;
            bcd_q <= 4'b0000;
        end else begin
            johnson_q <= {johnson_q[2:0], johnson_q[3] ^ johnson_q[0]};
            case (johnson_q)
                4'b0001: bcd_q <= 4'b0000;
                4'b0010: bcd_q <= 4'b0001;
                4'b0100: bcd_q <= 4'b0010;
                4'b1000: bcd_q <= 4'b0011;
                4'b0011: bcd_q <= 4'b0100;
                4'b0110: bcd_q <= 4'b0101;
                4'b1100: bcd_q <= 4'b0110;
                4'b0101: bcd_q <= 4'b0111;
                4'b1010: bcd_q <= 4'b1000;
                4'b1001: bcd_q <= 4'b1001;
                4'b1101: bcd_q <= 4'b1010;
                4'b1110: bcd_q <= 4'b1011;
                4'b0111: bcd_q <= 4'b1100;
                4'b1111: bcd_q <= 4'b1101;
                4'b1011: bcd_q <= 4'b1110;
                4'b1000: bcd_q <= 4'b1111;
            endcase
        end
    end

    // Functional module for upper three digits
    reg [3:1] ena_output;
    always @(posedge clk) begin
        if (reset) begin
            ena_output <= 3'b000;
        end else begin
            case ({select, xor_output})
                2'b00: ena_output <= 3'b000;
                2'b01: ena_output <= 3'b000;
                2'b10: ena_output <= {ena_output[1:0], ena_output[2]};
                2'b11: ena_output <= {ena_output[1:0], xor_output};
            endcase
        end
    end

    // Additive control logic to choose between XOR gate and BCD counter
    always @(posedge clk) begin
        if (reset) begin
            q <= 16'b0000000000000000;
        end else begin
            case (select)
                1'b0: q <= {ena_output, bcd_q};
                1'b1: q <= {16{1'b0}};
            endcase
            if (select) begin
                ena <= 3'b000;
            end else begin
                ena <= ena_output;
            end
        end
    end

endmodule

