module carry_lookahead_adder (input [3:0] a, input [3:0] b, input cin, output [3:0] s, output cout);

	wire [3:0] p, g;

	assign p[0] = a[0] | b[0];
	assign g[0] = a[0] & b[0];
	assign p[1] = a[1] ^ b[1] ^ g[0];
	assign g[1] = (a[1] & b[1]) | (a[1] & g[0]) | (b[1] & g[0]);
	assign p[2] = a[2] ^ b[2] ^ g[1];
	assign g[2] = (a[2] & b[2]) | (a[2] & g[1]) | (b[2] & g[1]);
	assign p[3] = a[3] ^ b[3] ^ g[2];
