module Viterbi (
  input [n*k-1:0] in,
  output [m-1:0] out
);

parameter k = 2; // number of bits in each encoded data symbol
parameter p = 2; // number of shift registers in the convolutional encoder
parameter n = 8; // number of encoded data bits
parameter m = 4; // number of decoded data bits

reg [p-1:0] shift_reg;
reg [n-1:0] trellis;
integer i, j;

always @ (in) begin
  // Initialize shift registers and trellis
  shift_reg = 0;
  trellis = 0;

  // Iterate through input data bits
  for (i = 0; i < n; i = i + k) begin
    // Shift input bits into shift registers
    shift_reg = {shift_reg[p-2:0], in[i]};

    // Update trellis
    for (j = 0; j < p; j = j + 1) begin
      trellis[j] = trellis[j] ^ (shift_reg[j] & in[i + 1]);
    end
  end
end

always @ (trellis) begin
  // Initialize output data bits
  out = 0;

  // Determine most likely sequence of decoded data bits
  for (i = 0; i < m; i = i + 1) begin
    out[i] = trellis[i] ^ trellis[i + p];
  end
end

endmodule

