module up_down_shift(
    input clk,
    input rst_n,
    input up_down,
    input [3:0] load_data,
    input shift_left,
    input shift_right,
    input parallel_load,
    input [3:0] data_in,
    input select,
    output reg [3:0] count,
    output [3:0] shift_out,
    output [3:0] final_output
);

reg [3:0] shift_reg;
reg [3:0] shift_out_reg;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        count <= 4'b0000;
        shift_reg <= 4'b0000;
        shift_out_reg <= 4'b0000;
    end else begin
        if (up_down) begin
            if (load_data[3:0] != 4'b0000) begin
                count <= load_data[3:0];
            end else if (shift_left) begin
                count <= {count[2:0], count[3]};
            end else if (shift_right) begin
                count <= {count[1], count[3:2]};
            end else begin
                count <= count + 1;
            end
        end else begin
            if (load_data[3:0] != 4'b0000) begin
                count <= load_data[3:0];
            end else if (shift_left) begin
                count <= {count[2:0], count[3]};
            end else if (shift_right) begin
                count <= {count[1], count[3:2]};
            end else begin
                count <= count - 1;
            end
        end

        if (parallel_load) begin
            shift_reg <= data_in[3:0];
        end else if (shift_left) begin
            shift_reg <= {shift_reg[2:0], shift_reg[3]};
        end else if (shift_right) begin
            shift_reg <= {shift_reg[1], shift_reg[3:2]};
        end

        shift_out_reg <= shift_reg;
    end
end

always @(posedge clk) begin
    if (select) begin
        final_output <= count ^ shift_out_reg;
        shift_out <= shift_out_reg;
    end else begin
        final_output <= shift_out_reg;
        shift_out <= shift_out_reg;
    end
end

endmodule

module reverse_data(
  input clk,
  input reset,
  input [7:0] data_in,
  input [3:0] control,
  output [7:0] data_out
);

  reg [7:0] data_out_reg;
  reg [3:0] counter;

  always @(posedge clk) begin
    if (reset) begin
      data_out_reg <= 8'h00;
      counter <= 4'h0;
    end
    else begin
      if (counter == control) begin
        data_out_reg <= {data_in[7], data_in[6], data_in[5], data_in[4], data_in[3], data_in[2], data_in[1], data_in[0]};
        counter <= 4'h0;
      end
      else begin
        data_out_reg <= data_out_reg;
        counter <= counter + 1;
      end
    end
  end

  assign data_out = data_out_reg;

endmodule

module shift_reg (
    input [3:0] data,
    input shift,
    output reg serial_out,
    output reg [3:0] q
);

    always @ (posedge shift) begin
        if (shift) begin
            q[0] <= q[1];
            q[1] <= q[2];
            q[2] <= q[3];
            q[3] <= data;
            serial_out <= q[0];
        end
        else begin
            q <= data;
            serial_out <= q[0];
        end
    end

endmodule

module clock_period_checker(clk, rst, max_period, clk_period);

parameter MAX_TIME = max_period * 2; // maximum time between rising edges of the clock
input clk, rst;
input [31:0] max_period;
output reg [31:0] clk_period;

reg [31:0] last_edge_time; // stores the time of the last rising edge of the clock
reg [31:0] current_time; // stores the time of the current rising edge of the clock

always @(posedge clk) begin
    if (rst == 0) begin
        clk_period <= 0;
        last_edge_time <= 0;
        current_time <= 0;
    end else begin
        // calculate the time since the last rising edge of the clock
        current_time <= $time;
        clk_period <= current_time - last_edge_time;

        if (clk_period > MAX_TIME) begin
            $display("Warning: Input clock period of %1.3f ns exceeds allowed value of %1.3f ns at time %1.3f ns.", clk_period/1000.0, max_period/1000.0, $time/1000.0);
        end

        // update the last_edge_time register
        last_edge_time <= current_time;
    end
end

endmodule

