module interrupt_controller (
  input [n-1:0] interrupt_request,
  input [n-1:0] interrupt_acknowledge,
  output [n-1:0] interrupt_vector,
  output interrupt_request_pending
);

parameter n = 4; // number of interrupt request signals

// Priority encoder
wire [n-1:0] interrupt_priority;
