module up_down_counter (
    input UD,
    input RST,
    output reg [3:0] Q,
    output reg OVF
);
    always @(posedge clk or negedge RST) begin
        if (RST == 0) begin
            Q <= 4'b0000;
            OVF <= 0;
        end else begin
            if (UD == 1) begin
                if (Q == 4'b1111) begin
                    Q <= 4'b0000;
                    OVF <= 1;
                end else begin
                    Q <= Q + 1;
                    OVF <= 0;
                end
            end else begin
                if (Q == 4'b0000) begin
                    Q <= 4'b1111;
                    OVF <= 1;
                end else begin
                    Q <= Q - 1;
                    OVF <= 0;
                end
            end
        end
    end
endmodule

module gray_code (
