    always @(*) begin
        gray_out[0] = data_in[0];
        gray_out[1] = data_in[0] ^ data_in[1];
        gray_out[2] = data_in[1] ^ data_in[2];
        gray_out[3] = data_in[2] ^ data_in[3];
    end
endmodule

