module top_module(
    input clk, // Clock input
    input reset, // Synchronous active-high reset input
    input [4:0] in, // 5-bit inputs
    output [4:0] out_max, // Output of the maximum value among all four inputs and the output of the byte-reversing module
    output [4:0] out_min, // Output of the minimum value among all four inputs and the output of the 4-bit binary count module
    output [4:0] out_avg // Output of the average value among all four inputs and the output of the byte-reversing module
);
    wire [31:0] reversed_in = 0; // 32-bit vector with reversed byte ordering
    wire [15:0] max_in = 0; // 16-bit vector used to calculate the maximum value
    wire [15:0] avg_in = 0; // 16-bit vector used to calculate the average value
    wire [4:0] min_in = 0; // 5-bit vector used to calculate the minimum value
    wire [15:0] max_out = 0; // 16-bit output of the maximum value
    wire [15:0] avg_out = 0; // 16-bit output of the average value

    byte_reverse reverse_inst(
        .in({in, 5'b0}), // Concatenate input with 0 to form 32-bit input
        .out(reversed_in)
    );

    assign max_in = reversed_in[31:16];
    assign avg_in = reversed_in[15:0];

    binary_count count_inst(
        .clk(clk),
        .reset(reset),
        .count(min_in)
    );

    assign out_max = {max_out[15:11], max_out[10:6], max_out[5:1], max_out[0]}; // Reverse byte ordering of output
    assign out_min = {min_in[4:0], min_in[4:0], min_in[4:0], min_in[4:0]}; // Set output to minimum value
    assign out_avg = {avg_out[15:11], avg_out[10:6], avg_out[5:1], avg_out[0]}; // Reverse byte ordering of output

    // Calculate maximum value
    comparator max_comp_inst(
        .a(max_in),
        .b(reversed_in[31:16]),
        .gt(max_out)
    );

    // Calculate average value
    adder avg_add_inst(
        .a(avg_in),
        .b(reversed_in[15:0]),
        .sum(avg_out)
    );

    divider avg_div_inst(
        .dividend(avg_out),
        .divisor(5'b01000), // Divide by 4 (2^2)
        .quotient(avg_out)
    );

    // Calculate minimum value
    comparator min_comp_inst1(
        .a(in),
        .b(count_inst),
        .lt(min_in[0])
    );

    comparator min_comp_inst2(
        .a(in),
        .b(count_inst),
        .lt(min_in[1])
    );

    comparator min_comp_inst3(
        .a(in),
        .b(count_inst),
        .lt(min_in[2])
    );

    comparator min_comp_inst4(
        .a(in),
        .b(count_inst),
        .lt(min_in[3])
    );

    mux min_mux_inst(
        .a(in),
        .b(count_inst),
        .sel(min_in[0:1]),
        .out(min_in[0:3])
    );
endmodule

module comparator(
