module adder_4bit(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

wire [3:0] C; // intermediate carry bits

// full-adder for each bit
full_adder FA0(.A(A[0]), .B(B[0]), .Cin(Cin), .S(S[0]), .C(C[0]));
full_adder FA1(.A(A[1]), .B(B[1]), .Cin(C[0]), .S(S[1]), .C(C[1]));
full_adder FA2(.A(A[2]), .B(B[2]), .Cin(C[1]), .S(S[2]), .C(C[2]));
full_adder FA3(.A(A[3]), .B(B[3]), .Cin(C[2]), .S(S[3]), .C(Cout));

endmodule

// full-adder module
module full_adder(
    input A,
    input B,
    input Cin,
    output S,
    output C
);

assign S = A ^ B ^ Cin;
assign C = (A & B) | (A & Cin) | (B & Cin);

endmodule

module vending_machine(
  input clk,
  input reset,
  input coin,
  input [1:0] item,
  output dispense,
  output [3:0] change
);

  // io definition
  // clk: clock signal
  // reset: reset signal
  // coin: signal indicating that a coin has been inserted
  // item: signal indicating the item that the customer wants to purchase
  // dispense: signal indicating that the item has been dispensed
  // change: signal indicating the amount of change to be returned

  // state definition
  parameter Idle = 2'b00;
  parameter AcceptingCoins = 2'b01;
  parameter SelectingItem = 2'b10;
  parameter DispensingItem = 2'b11;
  parameter ReturningChange = 2'b100;

  // state register
  reg [2:0] state_reg, state_next;

  // output register
  reg dispense_reg;
  reg [3:0] change_reg;

  // combinational logic
  always @(*) begin
    state_next = state_reg;
    dispense_reg = 0;
    change_reg = 0;

    case(state_reg)
      Idle: begin
        if(coin) begin
          state_next = AcceptingCoins;
        end
      end

      AcceptingCoins: begin
        if(coin) begin
          state_next = AcceptingCoins;
        end
        else if(item != 2'b00) begin
          state_next = SelectingItem;
        end
      end

      SelectingItem: begin
        if(item == 2'b00) begin
          state_next = SelectingItem;
        end
        else begin
          state_next = DispensingItem;
        end
      end

      DispensingItem: begin
        dispense_reg = 1;
        if(coin) begin
          state_next = ReturningChange;
          change_reg = coin - item;
        end
        else begin
          state_next = Idle;
        end
      end

      ReturningChange: begin
        change_reg = change_reg - coin;
        if(change_reg == 0) begin
          state_next = Idle;
        end
      end
    endcase
  end

  // state register update
  always @(posedge clk, posedge reset) begin
    if(reset) begin
      state_reg <= Idle;
    end
    else begin
      state_reg <= state_next;
    end
  end

  // output register update
  always @(posedge clk) begin
    dispense <= dispense_reg;
    change <= change_reg;
  end

endmodule

module Compression (
  input [n-1:0] indata,
  output [m-1:0] outdata
);

parameter n = 8; // number of bits in the input data
parameter m = 4; // number of bits in the output data

reg [n-1:0] indata_reg;
reg [m-1:0] outdata_reg;
reg [1:0] count;
reg [1:0] run_length;

always @ (posedge clk) begin
  indata_reg <= indata;
  count <= 0;
  run_length <= 0;
  outdata_reg <= 0;
  for (i = 0; i < n; i = i + 1) begin
    if (indata_reg[i] == indata_reg[i+1]) begin
      count <= count + 1;
    end else begin
      if (count > 0) begin
        outdata_reg[2*i-1:2*i] <= {1, count};
        count <= 0;
      end else begin
        outdata_reg[2*i] <= indata_reg[i];
      end
    end
  end
end

assign outdata = outdata_reg;

endmodule

module Decompression (
  input [m-1:0] indata,
  output [n-1:0] outdata
);

parameter n = 8; // number of bits in the input data
parameter m = 4; // number of bits in the output data

reg [m-1:0] indata_reg;
reg [n-1:0] outdata_reg;
reg [1:0] count;
reg [1:0] run_length;

always @ (posedge clk) begin
  indata_reg <= indata;
  count <= 0;
  run_length <= 0;
  outdata_reg <= 0;
  for (i = 0; i < n; i = i + 1) begin
    if (indata_reg[2*i] == 0) begin
      if (indata_reg[2*i+1] == 0) begin
        outdata_reg[i] <= 0;
      end else begin
        count <= indata_reg[2*i+1];
        run_length <= count;
      end
    end else begin
      if (run_length > 0) begin
        outdata_reg[i] <= 0;
        run_length <= run_length - 1;
      end else begin
        outdata_reg[i] <= 1;
      end
    end
  end
end

assign outdata = outdata_reg;

endmodule

