   always @(posedge clk)
     if(reset)
       space <= 16;
     else if(clear)
       space <= 16;
     else if(read & ~write)
       space <= space + 1;
     else if(write & ~read)
       space <= space - 1;

   always @(posedge clk)
     if(reset)
       occupied <= 0;
     else if(clear)
