module booth_multiplier (
    input [3:0] A,
    input [3:0] B,
    output reg [7:0] P
);

reg [3:0] A_reg;
reg [3:0] B_reg;
reg [1:0] count;

always @(A or B) begin
    A_reg <= A;
    B_reg <= B;
    count <= 2'b00;
    P <= 8'b00000000;
end

always @(posedge clk) begin
    if(count == 2'b00) begin
        if(B_reg[0] == 1) begin
            P <= P + (A_reg << 0);
        end
        count <= 2'b01;
    end else if(count == 2'b01) begin
        if(B_reg[0] == 0 && B_reg[1] == 0) begin
            count <= 2'b10;
        end else if(B_reg[0] == 1 && B_reg[1] == 0) begin
            P <= P + (A_reg << 4) - (A_reg << 0);
            count <= 2'b10;
        end else if(B_reg[0] == 0 && B_reg[1] == 1) begin
            P <= P + (A_reg << 0) - (A_reg << 4);
            count <= 2'b10;
        end
    end else if(count == 2'b10) begin
        if(B_reg[1] == 1) begin
            P <= P + (A_reg << 8);
        end
        count <= 2'b11;
    end else if(count == 2'b11) begin
        if(B_reg[3] == 1) begin
            P <= P - (A_reg << 4);
        end
        count <= 2'b00;
    end
end

endmodule

