assign twos_complement_A = (~A) + 1;

always @*
begin
    if (C == 1'b0) // Add
    begin
        S = O + A;
        D = S;
        B = 1'b0;
    end
    else // Subtract
    begin
        S = O + twos_complement_A;
        D = S;
        B = (S < O) ? 1'b1 : 1'b0;
    end
end

endmodule

