module quadrature_demodulator (
  input mod_in,
  input carr_in,
  output base_out
);

  reg [7:0] sin_table [0:255];
  reg [7:0] cos_table [0:255];
  reg [7:0] i;
  reg [7:0] q;
  reg [7:0] i_filtered;
  reg [7:0] q_filtered;
  reg [7:0] base_filtered;
  reg [7:0] modulated;

  // Generate sin and cos tables for quadrature carrier signals
  initial begin
    for (i = 0; i < 256; i = i + 1) begin
      sin_table[i] = $sin(2 * $pi * i / 256);
      cos_table[i] = $sin(2 * $pi * (i + 64) / 256);
    end
  end

  // Multiply modulated signal by quadrature carrier signals
  always @ (posedge carr_in) begin
    i <= mod_in * cos_table[i] >> 8;
    q <= mod_in * sin_table[q] >> 8;
  end

  // Low-pass filter to remove high-frequency components
  always @ (posedge carr_in) begin
    i_filtered <= (i_filtered * 7 + i) >> 3;
    q_filtered <= (q_filtered * 7 + q) >> 3;
    base_filtered <= i_filtered * i_filtered + q_filtered * q_filtered;
  end

  // Output the recovered baseband signal
  assign base_out = base_filtered;

endmodule

module quadrature_modulator (
  input base_in,
  input carr_in,
  output mod_out
);

  reg [7:0] sin_table [0:255];
  reg [7:0] cos_table [0:255];
  reg [7:0] i;
  reg [7:0] q;

  // Generate sin and cos tables for quadrature carrier signals
  initial begin
    for (i = 0; i < 256; i = i + 1) begin
      sin_table[i] = $sin(2 * $pi * i / 256);
      cos_table[i] = $sin(2 * $pi * (i + 64) / 256);
    end
  end

  // Multiply baseband signal by quadrature carrier signals
  always @ (posedge carr_in) begin
    i <= base_in * cos_table[i] >> 8;
    q <= base_in * sin_table[q] >> 8;
  end

  // Output the modulated signal
  assign mod_out = i + q;

endmodule

