module Counter(rst, dout, dout_fabric);

	////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
	// I/O declarations

	(* LOC = "P20" *)
	output wire dout;

	(* LOC = "P19" *)
	output wire dout_fabric;

	(* LOC = "P18" *)
	input wire rst;

	////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
	// Oscillators

	//The 25 kHz RC oscillator
	wire clk_6khz_cnt;			//dedicated output to hard IP only
	wire clk_6khz;				//general fabric output
	GP_RCOSC #(
		.PWRDN_EN(0),
		.AUTO_PWRDN(0),
		.OSC_FREQ("25k"),
		.HARDIP_DIV(4),
		.FABRIC_DIV(1)
	) rcosc (
		.PWRDN(1'b0),
		.CLKOUT_HARDIP(clk_6khz_cnt),
		.CLKOUT_FABRIC(clk_6khz)
	);

	////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
	// A hard IP counter

	localparam COUNT_MAX = 31;

	reg[7:0] count = COUNT_MAX;
	always @(posedge clk_6khz_cnt, posedge rst) begin

		//level triggered reset
		if(rst)
			count			<= 0;

		//counter
		else begin

			if(count == 0)
				count		<= COUNT_MAX;
			else
				count		<= count - 1'd1;

		end

	end

	assign dout = (count == 0);

	////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
	// A fabric counter

	(* COUNT_EXTRACT = "NO" *)
	reg[5:0] count_fabric = COUNT_MAX;					//TODO: run count_extract so we can do 7:0 and optimize
	always @(posedge clk_6khz, posedge rst) begin

		//level triggered reset
		if(rst)
			count_fabric		<= 0;

		//counter
		else begin

			if(count_fabric == 0)
				count_fabric	<= COUNT_MAX;
			else
				count_fabric	<= count_fabric - 1'd1;

		end

	end

	assign dout_fabric = (count_fabric == 0);

endmodule

module encrypt_module(
  input [15:0] input_data,
  output [15:0] encrypted_output
);

  wire [7:0] A;
  wire [7:0] B;

  assign A = input_data[15:8];
  assign B = input_data[7:0];

  wire [7:0] A_mult;
  wire [7:0] B_mult;

  assign A_mult = A * 3;
  assign B_mult = B * 5;

  wire [7:0] A_plus_B_mult;
  wire [7:0] B_plus_A_mult;

  assign A_plus_B_mult = A_mult + B;
  assign B_plus_A_mult = B_mult + A;

  assign encrypted_output = {A_plus_B_mult, B_plus_A_mult};

endmodule

module ac97_soc(
    input clk, wclk, rst, ps_ce, resume,
    output suspended, sync, out_le, in_valid, ld, valid
);

reg [7:0] cnt;
reg sync_beat, sync_resume;
reg [5:0] out_le;
reg [2:0] in_valid;
reg ld, valid;
reg [3:0] res_cnt;
wire resume_done;
reg [5:0] to_cnt;
reg suspended;
wire to;
reg [7:0] bit_clk_capture;
reg bit_clk_capture_r;
reg bit_clk_e;

assign sync = sync_beat | sync_resume;

always @(posedge clk or negedge rst) begin
    if (!rst) begin
        cnt <= 8'hff;
    end else if (suspended) begin
        cnt <= 8'hff;
    end else begin
        cnt <= cnt + 1;
    end
end

always @(posedge clk) begin
    ld <= (cnt == 8'h00);
end

always @(posedge clk) begin
    sync_beat <= (cnt == 8'h00) || ((cnt > 8'h00) && (cnt < 8'h10));
end

always @(posedge clk) begin
    valid <= (cnt > 8'h39);
end

always @(posedge clk) begin
    case (cnt)
        8'h11: out_le[0] <= 1'b1;
        8'h25: out_le[1] <= 1'b1;
        8'h39: out_le[2] <= 1'b1;
        8'h4d: out_le[3] <= 1'b1;
        8'h61: out_le[4] <= 1'b1;
        8'h89: out_le[5] <= 1'b1;
        default: out_le <= 6'b0;
    endcase
end

always @(posedge clk) begin
    in_valid[0] <= (cnt > out_le[3] + 8'h10);
    in_valid[1] <= (cnt > out_le[4] + 8'h10);
    in_valid[2] <= (cnt > out_le[5] + 8'h10);
end

always @(posedge wclk or negedge rst) begin
    if (!rst) begin
        to_cnt <= 6'h0;
    end else if (bit_clk_e) begin
        to_cnt <= 6'h0;
    end else if (!to) begin
        to_cnt <= to_cnt + 6'h1;
    end
end

always @(posedge wclk or negedge rst) begin
    if (!rst) begin
        sync_resume <= 1'b0;
    end else if (resume_done) begin
        sync_resume <= 1'b0;
    end else if (suspended && resume) begin
        sync_resume <= 1'b1;
    end
end

always @(posedge wclk) begin
    if (!sync_resume) begin
        res_cnt <= 4'h0;
    end else if (ps_ce) begin
        res_cnt <= res_cnt + 4'h1;
    end
end

always @(posedge wclk) begin
    bit_clk_capture <= {bit_clk_capture[6:0], clk};
end

always @(posedge wclk) begin
    bit_clk_capture_r <= bit_clk_capture;
end

always @(posedge wclk) begin
    bit_clk_e <= bit_clk_capture ^ bit_clk_capture_r;
end

assign to = (to_cnt == 6'h3f);

always @(posedge wclk or negedge rst) begin
    if (!rst) begin
        suspended <= 1'b0;
    end else if (bit_clk_e && (bit_clk_capture == 8'hff)) begin
        suspended <= 1'b1;
    end else if (bit_clk_e) begin
        suspended <= 1'b0;
    end
end

assign resume_done = (res_cnt == 4'hf);

endmodule

