module top_module (
    input [15:0] A,
    input [3:0] B,
    input [3:0] select,
    output reg [15:0] shift_left,
    output reg [15:0] shift_right,
    output reg [15:0] out
);

    reg [15:0] shifted_value;
    reg [3:0] decoder_enable;
    reg [15:0] decoder_output;

    always @(*) begin
        case (select)
            4'b0000: begin // Barrel Shifter
                if (B[3] == 1) begin
                    shifted_value = {A[14:0], 1'b0};
                end else begin
                    shifted_value = {1'b0, A[15:1]};
                end
                shift_left = shifted_value;
                shift_right = shifted_value;
            end
            4'b0001: begin // 4-to-16 Decoder
                decoder_enable = ~B;
                decoder_output = 16'b0;
                if (decoder_enable[0] == 1) begin
                    decoder_output[0] = 1'b1;
                end
                if (decoder_enable[1] == 1) begin
                    decoder_output[1] = 1'b1;
                end
                if (decoder_enable[2] == 1) begin
                    decoder_output[2] = 1'b1;
                end
                if (decoder_enable[3] == 1) begin
                    decoder_output[3] = 1'b1;
                end
                out = decoder_output;
            end
            default: begin
                // Do nothing
            end
        endcase
    end

endmodule

module priority_encoder (
  input [n-1:0] in,
  output reg [log2(n)-1:0] out
);

parameter n = 8; // number of input signals

always @* begin
  casez(in) // priority encoder logic
    8'b10000000: out = 3'b000; // highest priority input
    8'b01000000: out = 3'b001;
    8'b00100000: out = 3'b010;
    8'b00010000: out = 3'b011;
    8'b00001000: out = 3'b100;
    8'b00000100: out = 3'b101;
    8'b00000010: out = 3'b110;
    8'b00000001: out = 3'b111;
    default: out = 3'b000; // default output
  endcase
end

endmodule

module carry_lookahead_adder (
    input [7:0] a,
    input [7:0] b,
    output [7:0] s,
    output overflow
);
    wire [7:0] g, p, c;
    assign g = a & b;
    assign p = a ^ b;
    assign c[0] = 1'b0;
    genvar i;
    generate
        for (i = 1; i < 8; i = i + 1) begin
            assign c[i] = (g[i-1] | (p[i-1] & c[i-1]));
        end
    endgenerate
    assign s = p + c;
    assign overflow = c[7] ^ c[6];
endmodule

module edge_detection (
    input clk,
    input reset,
    input a,
    output rise,
    output down
);
    reg last_a;
    reg rise_detected;
    reg down_detected;
    always @(posedge clk) begin
        if (reset) begin
            last_a <= 1'b0;
            rise_detected <= 1'b0;
            down_detected <= 1'b0;
        end else begin
            if (a && !last_a) begin
                rise_detected <= 1'b1;
            end else begin
                rise_detected <= 1'b0;
            end
            if (!a && last_a) begin
                down_detected <= 1'b1;
            end else begin
                down_detected <= 1'b0;
            end
            last_a <= a;
        end
    end
    assign rise = rise_detected;
    assign down = down_detected;
endmodule

