module vga_sync_gen(
  input clk,
  input rst,
  input [9:0] h_count,
  input [9:0] v_count,
  output reg h_sync,
  output reg v_sync
);

  // Constants for VGA timing
  parameter H_SYNC_PULSE_WIDTH = 96;
  parameter H_FRONT_PORCH = 16;
  parameter H_BACK_PORCH = 48;
  parameter V_SYNC_PULSE_WIDTH = 2;
  parameter V_FRONT_PORCH = 10;
  parameter V_BACK_PORCH = 33;
  parameter H_TOTAL = 800;
  parameter V_TOTAL = 525;

  // Counters for tracking pixel position
  reg [9:0] h_counter = 0;
  reg [9:0] v_counter = 0;

  // Horizontal sync signal generation
  always @(posedge clk) begin
    if (rst) begin
      h_counter <= 0;
      h_sync <= 1;
    end else begin
      if (h_counter >= H_TOTAL - 1) begin
        h_counter <= 0;
        h_sync <= 0;
      end else if (h_counter >= H_TOTAL - H_SYNC_PULSE_WIDTH - H_BACK_PORCH) begin
        h_sync <= 1;
      end else begin
        h_sync <= 0;
      end
      h_counter <= h_counter + 1;
    end
  end

  // Vertical sync signal generation
  always @(posedge clk) begin
    if (rst) begin
      v_counter <= 0;
      v_sync <= 1;
    end else begin
      if (v_counter >= V_TOTAL - 1) begin
        v_counter <= 0;
        v_sync <= 0;
      end else if (v_counter >= V_TOTAL - V_SYNC_PULSE_WIDTH - V_BACK_PORCH) begin
        v_sync <= 1;
      end else begin
        v_sync <= 0;
      end
      v_counter <= v_counter + 1;
    end
  end

endmodule

module booth_shift_reg (
    input clk,
    input reset,
    input [3:0] A,
    input [3:0] B,
    input load,
    input shift_left,
    input shift_right,
    input select,
    output reg [7:0] P,
    output [7:0] P_shifted
);

reg [7:0] P_reg;
reg [3:0] A_reg;
reg [3:0] B_reg;
reg [2:0] count;
reg [3:0] B_shifted;
reg [1:0] shift_count;

always @(posedge clk) begin
    if (reset) begin
        P_reg <= 8'b0;
        A_reg <= 4'b0;
        B_reg <= 4'b0;
        count <= 3'b0;
        B_shifted <= 4'b0;
        shift_count <= 2'b0;
    end else begin
        if (load) begin
            P_reg <= 8'b0;
            A_reg <= A;
            B_reg <= B;
            count <= 3'b0;
            B_shifted <= {B[3], B};
            shift_count <= 2'b0;
        end else begin
            case (count)
                3'b000: begin
                    if (B_reg[0] == 1) begin
                        P_reg <= P_reg + (A_reg << 4);
                    end
                    B_shifted <= {B[3], B};
                    shift_count <= 2'b0;
                end
                3'b001: begin
                    if (B_reg[0] == 0 && B_shifted[0] == 1) begin
                        P_reg <= P_reg - (A_reg << 4);
                    end
                    B_shifted <= {B_shifted[3], B_shifted};
                    shift_count <= 2'b1;
                end
                3'b010: begin
                    if (B_reg[0] == 1) begin
                        P_reg <= P_reg + (A_reg << 3);
                    end
                    B_shifted <= {B[3], B};
                    shift_count <= 2'b0;
                end
                3'b011: begin
                    if (B_reg[0] == 0 && B_shifted[0] == 1) begin
                        P_reg <= P_reg - (A_reg << 3);
                    end
                    B_shifted <= {B_shifted[3], B_shifted};
                    shift_count <= 2'b1;
                end
                3'b100: begin
                    if (B_reg[0] == 1) begin
                        P_reg <= P_reg + (A_reg << 2);
                    end
                    B_shifted <= {B[3], B};
                    shift_count <= 2'b0;
                end
                3'b101: begin
                    if (B_reg[0] == 0 && B_shifted[0] == 1) begin
                        P_reg <= P_reg - (A_reg << 2);
                    end
                    B_shifted <= {B_shifted[3], B_shifted};
                    shift_count <= 2'b1;
                end
                3'b110: begin
                    if (B_reg[0] == 1) begin
                        P_reg <= P_reg + (A_reg << 1);
                    end
                    B_shifted <= {B[3], B};
                    shift_count <= 2'b0;
                end
                3'b111: begin
                    if (B_reg[0] == 0 && B_shifted[0] == 1) begin
                        P_reg <= P_reg - (A_reg << 1);
                    end
                    B_shifted <= {B_shifted[3], B_shifted};
                    shift_count <= 2'b1;
                end
            endcase
            count <= count + 1;
        end
    end
end

always @(*) begin
    if (select) begin
        P = P_reg;
        P_shifted = {P_reg[6:0], 1'b0};
    end else begin
        P = {P_reg[6:0], 1'b0};
        P_shifted = {P_reg[5:0], 2'b0};
    end
end

endmodule

module watchdog_timer (
  input clk,
  input reset,
  input [31:0] timer_duration,
  output reg timer_reset
);

reg [31:0] timer_count;

always @(posedge clk or posedge reset) begin
  if (reset) begin
    timer_count <= 0;
    timer_reset <= 0;
  end else begin
    timer_count <= timer_count + 1;
    if (timer_count >= timer_duration) begin
      timer_count <= 0;
      timer_reset <= 1;
    end else begin
      timer_reset <= 0;
    end
  end
end

endmodule

