module top_module (
    input clk,
    input areset,  // async active-high reset to zero
    input load,
    input ena,
    input [3:0] data,  // 4-bit input for shift register
    input [7:0] in,  // 8-bit input for priority encoder
    output [7:0] out
);

    // 4-bit shift register
    reg [3:0] shift_reg;
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            shift_reg <= 4'b0;
        end else if (load) begin
            shift_reg <= data;
        end else if (ena) begin
            if (shift_dir) begin
                shift_reg <= {shift_reg[2:0], 1'b0};
            end else begin
                shift_reg <= {1'b0, shift_reg[3:1]};
            end
        end
    end

    // Priority encoder
    wire [2:0] gray_code;
    wire [3:0] binary_code;
    assign gray_code = ~in ^ ({1'b0, in[7:1]});
    assign binary_code = {gray_code[2], gray_code[2]^gray_code[1], gray_code[1]^gray_code[0], gray_code[0]};
    wire [2:0] first_one_pos;
    priority_encoder pe(.in(binary_code), .out(first_one_pos));

    // Output mux
    wire [7:0] shifted_in = (shift_dir) ? {shift_reg[3:0], 4'b0} : {4'b0, shift_reg[3:0]};
    assign out = (first_one_pos == 0) ? shifted_in : {8'b0, first_one_pos};

    // Control signals
    reg shift_dir;
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            shift_dir <= 1'b0;
        end else begin
            shift_dir <= (in != 8'b0);
        end
    end

endmodule

module priority_encoder (
    input [3:0] in,
    output [2:0] out
);

    assign out = (in[3]) ? 3'b111 : (in[2]) ? 3'b110 : (in[1]) ? 3'b100 : (in[0]) ? 3'b000 : 3'b000;

endmodule

module traffic_light_controller(
    input clk,
    input reset,
    input button,
    output reg green,
    output reg yellow,
    output reg red,
    output reg walk
);

// Define constants for the state durations
localparam GREEN_TIME = 10_000_000; // 10 seconds
localparam YELLOW_TIME = 2_000_000; // 2 seconds
localparam RED_TIME = 10_000_000; // 10 seconds
localparam WALK_TIME = 2_000_000; // 2 seconds

// Define state variables
reg [1:0] state = 2'b00;
reg [23:0] state_counter = 0;
reg [23:0] walk_counter = 0;

// Define state machine
always @(posedge clk) begin
    if (reset) begin
        state <= 2'b00;
        state_counter <= 0;
        walk_counter <= 0;
        green <= 1'b1;
        yellow <= 1'b0;
        red <= 1'b0;
        walk <= 1'b0;
    end else begin
        case (state)
            2'b00: begin // Green state
                green <= 1'b1;
                yellow <= 1'b0;
                red <= 1'b0;
                walk <= 1'b0;
                if (state_counter >= GREEN_TIME) begin
                    state <= 2'b01;
                    state_counter <= 0;
                end
            end
            2'b01: begin // Yellow state
                green <= 1'b0;
                yellow <= 1'b1;
                red <= 1'b0;
                if (state_counter >= YELLOW_TIME) begin
                    state <= 2'b10;
                    state_counter <= 0;
                    walk_counter <= 0;
                end
                if (state_counter >= YELLOW_TIME - WALK_TIME) begin
                    walk <= 1'b1;
                    walk_counter <= walk_counter + 1;
                end
            end
            2'b10: begin // Red state
                green <= 1'b0;
                yellow <= 1'b0;
                red <= 1'b1;
                if (state_counter >= RED_TIME) begin
                    state <= 2'b11;
                    state_counter <= 0;
                end
                if (state_counter >= RED_TIME - WALK_TIME) begin
                    walk <= 1'b1;
                    walk_counter <= walk_counter + 1;
                end
            end
            2'b11: begin // Yellow state
                green <= 1'b0;
                yellow <= 1'b1;
                red <= 1'b0;
                if (state_counter >= YELLOW_TIME) begin
                    state <= 2'b00;
                    state_counter <= 0;
                    walk_counter <= 0;
                end
                if (state_counter >= WALK_TIME) begin
                    walk <= 1'b0;
                end
            end
        endcase
        state_counter <= state_counter + 1;
    end
end

// Handle pedestrian button
always @(posedge clk) begin
    if (button) begin
        state <= 2'b01; // Immediately switch to yellow state
        state_counter <= 0;
        walk_counter <= 0;
    end
end

endmodule

