    output [7:0] out2,
    output [7:0] out3,
    output [7:0] out4
);

reg [7:0] out1_reg, out2_reg, out3_reg, out4_reg;
reg [7:0] in_reg [0:3];
reg [1:0] enable_reg [0:3];
reg [1:0] sel_reg [0:3];

// 2-to-4 decoder
assign out1 = (enable_reg[0]) ? out1_reg : 8'b0;
assign out2 = (enable_reg[1]) ? out2_reg : 8'b0;
assign out3 = (enable_reg[2]) ? out3_reg : 8'b0;
assign out4 = (enable_reg[3]) ? out4_reg : 8'b0;

always @(posedge clk) begin
    if (rst) begin
        out1_reg <= 8'b0;
        out2_reg <= 8'b0;
        out3_reg <= 8'b0;
        out4_reg <= 8'b0;
        in_reg[0] <= 8'b0;
        in_reg[1] <= 8'b0;
        in_reg[2] <= 8'b0;
        in_reg[3] <= 8'b0;
        sel_reg[0] <= 2'b00;
        sel_reg[1] <= 2'b01;
        sel_reg[2] <= 2'b10;
        sel_reg[3] <= 2'b11;
        enable_reg[0] <= 1'b0;
        enable_reg[1] <= 1'b0;
        enable_reg[2] <= 1'b0;
        enable_reg[3] <= 1'b0;
    end else begin
        // pipeline stage 1
        in_reg[0] <= in[sel_reg[0]*8 +: 8];
        in_reg[1] <= in[sel_reg[1]*8 +: 8];
        in_reg[2] <= in[sel_reg[2]*8 +: 8];
        in_reg[3] <= in[sel_reg[3]*8 +: 8];
        sel_reg[0] <= sel;
        sel_reg[1] <= sel_reg[0];
        sel_reg[2] <= sel_reg[1];
        sel_reg[3] <= sel_reg[2];
        enable_reg[0] <= enable;
        enable_reg[1] <= enable_reg[0];
        enable_reg[2] <= enable_reg[1];
        enable_reg[3] <= enable_reg[2];
        // pipeline stage 2
        out1_reg <= (enable_reg[0]) ? in_reg[0] : out1_reg;
        out2_reg <= (enable_reg[1]) ? in_reg[1] : out2_reg;
        out3_reg <= (enable_reg[2]) ? in_reg[2] : out3_reg;
        out4_reg <= (enable_reg[3]) ? in_reg[3] : out4_reg;
    end
end

endmodule

module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [31:0]  data_out
);

    reg [7:0] data_reg [3:0];
    reg [31:0] acc_reg [2:0];
    reg [1:0] stage;
    reg [1:0] next_stage;
    wire [3:0] valid_reg;
    wire [3:0] ready_reg;

    assign ready_a = (stage == 0) ? 1'b1 : 1'b0;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            data_reg <= 0;
            acc_reg <= 0;
            stage <= 0;
            next_stage <= 0;
            valid_b <= 0;
            data_out <= 0;
        end
        else begin
            case (stage)
                0: begin
                    if (valid_a && ready_b) begin
                        data_reg[0] <= data_in;
                        valid_reg[0] <= 1'b1;
                        next_stage <= 1;
                    end
                end
                1: begin
                    data_reg[1] <= data_reg[0];
                    valid_reg[1] <= valid_reg[0];
                    data_reg[0] <= 0;
                    valid_reg[0] <= 0;
                    next_stage <= 2;
                end
                2: begin
                    data_reg[2] <= data_reg[1];
                    valid_reg[2] <= valid_reg[1];
                    data_reg[1] <= 0;
                    valid_reg[1] <= 0;
                    next_stage <= 3;
                end
                3: begin
                    data_reg[3] <= data_reg[2];
                    valid_reg[3] <= valid_reg[2];
                    data_reg[2] <= 0;
                    valid_reg[2] <= 0;
                    next_stage <= 4;
                end
                4: begin
                    acc_reg[0] <= acc_reg[0] + {valid_reg[0], data_reg[0]};
                    acc_reg[1] <= acc_reg[1] + {valid_reg[1], data_reg[1]};
                    acc_reg[2] <= acc_reg[2] + {valid_reg[2], data_reg[2]};
                    data_out <= acc_reg[0] + acc_reg[1] + acc_reg[2];
                    valid_b <= 1'b1;
                    next_stage <= 0;
                end
            endcase
            stage <= next_stage;
        end
    end

    assign ready_reg[0] = ready_b;
    assign ready_reg[1] = (stage >= 1) ? 1'b1 : 1'b0;
    assign ready_reg[2] = (stage >= 2) ? 1'b1 : 1'b0;
    assign ready_reg[3] = (stage >= 3) ? 1'b1 : 1'b0;

    assign ready_b = &ready_reg;

endmodule

