module top_module (
    input wire [255:0] in, // 256-bit input vector for the multiplexer
    input wire [7:0] sel, // 8-bit selection input for the multiplexer
    input wire [2:0] vec, // 3-bit input vector for the barrel shifter
    output wire [2:0] outv, // 3-bit output vector for the barrel shifter
    output wire o2, // 1-bit output for the shifted input at index 2
    output wire o1, // 1-bit output for the shifted input at index 1
    output wire o0, // 1-bit output for the shifted input at index 0
    output wire sum // 9-bit output for the sum of the multiplexer output and the barrel shifter output
);

// Priority encoder for the multiplexer
wire [7:0] encoded_sel;
priority_encoder pe(sel, encoded_sel);

// Decoder for the multiplexer
wire [255:0] decoded_in;
decoder dec(encoded_sel, decoded_in);

// Multiplexer
wire [7:0] sel_mux = sel[7:0];
wire [255:0] out_mux;
mux256 mux(in, sel_mux, out_mux);

// Barrel shifter
wire [2:0] shifted_vec;
barrel_shifter bs(vec, in, shifted_vec);

// Output ports for the barrel shifter
assign o2 = shifted_vec[2];
assign o1 = shifted_vec[1];
assign o0 = shifted_vec[0];

// Output vector for the barrel shifter
assign outv = shifted_vec;

// Output for the sum of the multiplexer output and the barrel shifter output
wire [8:0] sum_wire;
assign sum_wire = out_mux + {o2, o1, o0};
assign sum = sum_wire[8:0];

endmodule

