    if (~reset_n) begin
        data_in_d1 <= 0;
        data_in_d2 <= 0;
        data_out <= 0;
    end else begin
        data_in_d1 <= data_in;
        data_in_d2 <= data_in_d1;
        data_out <= data_in_d2;
