module even_parity(
    input [7:0] in,
    output [8:0] parity
);
    assign parity[8] = ~^in;
    assign parity[7:0] = in;
endmodule

module ripple_carry_adder(
    input [31:0] a,
    input [31:0] b,
    output [31:0] sum
);
    wire [31:0] carry;
    assign carry[0] = 1'b0;
    genvar i;
    generate
        for (i = 0; i < 32; i = i + 1) begin: adder
            full_adder fa(
                .a(a[i]),
                .b(b[i]),
                .c(carry[i]),
                .sum(sum[i]),
                .carry(carry[i+1])
            );
        end
    endgenerate
endmodule

module bitwise_and(
    input [8:0] in1,
    input [31:0] in2,
    output [8:0] out
);
    assign out = in1 & in2[8:0];
endmodule

module top_module(
    input clk,
    input reset,
    input [7:0] in,
    input [31:0] a,
    input [31:0] b,
    output [31:0] sum,
    output [8:0] parity_and_sum
);
    wire [8:0] parity;
    wire [31:0] adder_out;
    even_parity parity_module(
        .in(in),
        .parity(parity)
    );
    ripple_carry_adder adder(
        .a(a),
        .b(b),
        .sum(adder_out)
    );
    bitwise_and and_gate(
        .in1(parity),
        .in2(adder_out),
        .out(parity_and_sum)
    );
    assign sum = adder_out;
endmodule

