module top_module(
    input clk,
    input reset,             // Synchronous active-high reset
    input [3:0] a,           // 4-bit binary input a
    input [31:0] b,          // 32-bit binary input b
    input enable,            // Enable input to choose between binary counter and multiplier
    output reg [3:0] count,  // Binary counter output
    output reg [31:0] prod   // 32-bit binary output from multiplier module
);

// Binary Counter State Machine
reg [3:0] state;
always @(posedge clk) begin
    if (reset) begin
        state <= 4'b0000;
        count <= 4'b0000;
    end
    else begin
        case (state)
            4'b0000: begin
                count <= 4'b0000;
                state <= 4'b0001;
            end
            4'b0001: begin
                count <= 4'b0001;
                state <= 4'b0010;
            end
            4'b0010: begin
                count <= 4'b0010;
                state <= 4'b0011;
            end
            4'b0011: begin
                count <= 4'b0011;
                state <= 4'b0100;
            end
            4'b0100: begin
                count <= 4'b0100;
                state <= 4'b0101;
            end
            4'b0101: begin
                count <= 4'b0101;
                state <= 4'b0110;
            end
            4'b0110: begin
                count <= 4'b0110;
                state <= 4'b0111;
            end
            4'b0111: begin
                count <= 4'b0111;
                state <= 4'b1000;
            end
            4'b1000: begin
                count <= 4'b1000;
                state <= 4'b1001;
            end
            4'b1001: begin
                count <= 4'b1001;
                state <= 4'b1010;
            end
            4'b1010: begin
                count <= 4'b1010;
                state <= 4'b1011;
            end
            4'b1011: begin
                count <= 4'b1011;
                state <= 4'b1100;
            end
            4'b1100: begin
                count <= 4'b1100;
                state <= 4'b1101;
            end
            4'b1101: begin
                count <= 4'b1101;
                state <= 4'b1110;
            end
            4'b1110: begin
                count <= 4'b1110;
                state <= 4'b1111;
            end
            4'b1111: begin
                count <= 4'b1111;
                state <= 4'b0000;
            end
        endcase
    end
end

// Booth Multiplier
reg [35:0] m;
reg [4:0] a_reg;
reg [31:0] b_reg;
reg [63:0] prod_reg;
reg [1:0] state_reg;
always @(posedge clk) begin
    if (reset) begin
        m <= 36'b0;
        a_reg <= 5'b0;
        b_reg <= 32'b0;
        prod_reg <= 64'b0;
        prod <= 32'b0;
        state_reg <= 2'b00;
    end
    else begin
        if (enable) begin
            // Booth Multiplier State Machine
            case (state_reg)
                2'b00: begin
                    a_reg <= {1'b0, a};
                    b_reg <= b;
                    state_reg <= 2'b01;
                end
                2'b01: begin
                    if (m[0] == 1) begin
                        prod_reg <= prod_reg - {b_reg, 32'b0};
                    end
                    else begin
                        prod_reg <= prod_reg + {b_reg, 32'b0};
                    end
                    m <= {m[35], m[34], m[33], m[32], m[31], m[30], m[29], m[28], m[27], m[26], m[25], m[24], m[23], m[22], m[21], m[20], m[19], m[18], m[17], m[16], m[15], m[14], m[13], m[12], m[11], m[10], m[9], m[8], m[7], m[6], m[5], m[4], m[3], m[2], m[1], a_reg[4], a_reg[3], a_reg[2], a_reg[1], a_reg[0]};
                    state_reg <= 2'b10;
                end
                2'b10: begin
                    m <= {m[35], m[34], m[33], m[32], m[31], m[30], m[29], m[28], m[27], m[26], m[25], m[24], m[23], m[22], m[21], m[20], m[19], m[18], m[17], m[16], m[15], m[14], m[13], m[12], m[11], m[10], m[9], m[8], m[7], m[6], m[5], m[4], m[3], m[2], m[1], a_reg[4], a_reg[3], a_reg[2], a_reg[1], a_reg[0]};
                    state_reg <= 2'b01;
                end
            endcase
            prod <= prod_reg[31:0];
        end
    end
end

endmodule

module booth_multiplier (
    input [3:0] A,
    input [3:0] B,
    output reg [7:0] P
);

reg [3:0] A_reg;
reg [3:0] B_reg;
reg [2:0] counter;
reg [4:0] P_reg;
reg [1:0] state;

always @(posedge clk) begin
    case (state)
        2'b00: begin
            A_reg <= A;
            B_reg <= B;
            counter <= 3'd4;
            P_reg <= 5'd0;
            state <= 2'b01;
        end
        2'b01: begin
            if (B_reg[0] == 1) begin
                P_reg <= P_reg - A_reg;
            end else begin
                P_reg <= P_reg + A_reg;
            end
            B_reg <= {B_reg[3], B_reg[3:1]};
            state <= 2'b10;
        end
        2'b10: begin
            if (counter == 0) begin
                P <= P_reg;
                state <= 2'b00;
            end else begin
                counter <= counter - 1;
                state <= 2'b01;
            end
        end
    endcase
end

endmodule

