wire	[1:6] b1x,b2x,b3x,b4x,b5x,b6x,b7x,b8x;
wire 	[1:4] so1x,so2x,so3x,so4x,so5x,so6x,so7x,so8x;
wire 	[1:32] ppo;

// Perform XOR operation on ri and output e from xp module
xp xp(ri, e);

// Perform DES-like XOR operation on e and k using desxor1 module
desxor1 desxor1(e, b1x, b2x, b3x, b4x, b5x, b6x, b7x, b8x, k);

// Perform S-box substitutions on each of the eight 6-bit outputs using s modules
s1 s1(clk, b1x, so1x);
s2 s2(clk, b2x, so2x);
s3 s3(clk, b3x, so3x);
s4 s4(clk, b4x, so4x);
s5 s5(clk, b5x, so5x);
s6 s6(clk, b6x, so6x);
s7 s7(clk, b7x, so7x);
s8 s8(clk, b8x, so8x);

// Perform permutation operation on eight 4-bit outputs from s modules using pp module
pp pp(so1x,so2x,so3x,so4x,so5x,so6x,so7x,so8x, ppo);

// Perform DES-like XOR operation on li and ppo to obtain ro output
desxor2 desxor2(ppo, li, ro);

// Assign lo output to ri input
assign lo=ri;

endmodule

module nkmd_dai_rx(
    input wire clk,
    input wire rst,

    // dmix interface
    input wire [23:0] rx_data_i,
    input wire rx_ack_i,

    // To nkmm R bus
    input wire [31:0] data_i,
    output wire [31:0] data_o,
    input wire [31:0] addr_i,
    input wire we_i);

    // Ring buffer
    reg [23:0] ringbuf [63:0];
    reg [5:0] nextw_ff;
    always @(posedge clk) begin
        if (rst)
            nextw_ff <= 0;
        else if (rx_ack_i)
            nextw_ff <= nextw_ff + 1;
    end
    always @(posedge clk) begin
        if (rx_ack_i)
            ringbuf[nextw_ff] <= rx_data_i;
    end

    // Unread data counter and shift counter
    reg [5:0] unread_ff;
    reg [5:0] shift_ff;
    wire should_shift;
    assign should_shift = we_i && addr_i[15:12] == 4'hd && addr_i[7:0] == 8'h00;
    always @(posedge clk) begin
        if (rst) begin
            unread_ff <= 0;
            shift_ff <= 0;
        end else if (should_shift && !rx_ack_i) begin
            unread_ff <= unread_ff - 1;
            shift_ff <= shift_ff + 1;
        end else if (!should_shift && rx_ack_i) begin
            unread_ff <= unread_ff + 1;
        end else if (should_shift && rx_ack_i) begin
            shift_ff <= shift_ff + 1;
        end
    end

    // RAM interface
    reg [31:0] data_o_ff;
    assign data_o = data_o_ff;

    // Address decoding
    wire [5:0] offset_i;
    assign offset_i = addr_i[5:0];

    // Read and write data to RAM
    always @(posedge clk) begin
        if (addr_i[15:12] == 4'hf)
            data_o_ff <= ringbuf[shift_ff + offset_i];
        else if (addr_i[15:12] == 4'hd && addr_i[7:0] == 8'h00)
            data_o_ff <= unread_ff;
        else
            data_o_ff <= 0;
    end

endmodule

