module digital_lock ( 
    input [3:0] code, // 4-digit binary code input
    output reg open // Output signal indicating whether the lock is open or not
);

    // Define the stored password
    reg [3:0] password [0:3];
    initial begin
        password[0] = 4'b1100;
        password[1] = 4'b1010;
        password[2] = 4'b0110;
        password[3] = 4'b0001;
    end

    // Define the control logic
    reg [1:0] state = 2'b00;
    always @ (code) begin
        case (state)
            2'b00: if (code != 4'b0000) state = 2'b01;
            2'b01: if (code != 4'b0000) state = 2'b10;
            2'b10: if (code == 4'b0000) state = 2'b00;
        endcase
    end

    // Define the decoder and multiplexer module
    wire [3:0] password_bits [0:3];
    decoder_mux_16_4 decoder_mux (
        .in(password),
        .sel(state),
        .out(password_bits)
    );

    // Define the 32-bit adder module
    wire [31:0] sum;
    adder_32 adder (
        .a(code),
        .b(password_bits),
        .sum(sum)
    );

    // Define the output logic
    always @ (sum) begin
        if (sum == 32'b00000000000000000000000000000000) open = 1'b1;
        else open = 1'b0;
    end

endmodule

