  output reg check_next_dstaddr_tlc,
  output reg [2*LW-1:0] fifo_out_tlc,
  output reg tran_written_tlc
);

  // Implement routing logic here
  always @(*)
  begin
    if (frame_in && !wr_fifo_full) begin
      // Write data to output FIFO
      check_next_dstaddr_tlc <= 1;
      fifo_out_tlc <= tran_in;
      tran_written_tlc <= 1;
