    else if (next_access_tlc) begin
      // Read data from output FIFO
      fifo_out_tlc <= {2*LW{1'b0}};
      tran_written_tlc <= 0;
    end
    else begin
      // No data to transmit
      check_next_dstaddr_tlc <= 0;
      fifo_out_tlc <= {2*LW{1'b0}};
      tran_written_tlc <= 0;
    end
  end

endmodule

