    input in0, in1, in2, in3;
    input s0, s1;
    output out;

    assign out = (s1 & s0) ? in3 :
                 (s1 & !s0) ? in2 :
                 (!s1 & s0) ? in1 :
                 in0;

endmodule

module ICAP_config
  (
   input        fastclk,
   output [7:0] test,

   // DIP switches in and out
   input [3:0]  sw_in,
   output [3:0] sw_out,

   // Tube interface
   input [2:0]  h_addr,
   input        h_cs_b,
   inout [7:0]  h_data,
   input        h_phi2,
   input        h_rdnw,
   input        h_rst_b
  );

   reg          reconfigure_sw_changed = 1'b0;
   reg          reconfigure_hw_changed = 1'b0;
   reg          reconfigure = 1'b0;
   reg  [4:0]   design_num;
   wire [3:0]   pwr_out;
   wire         initialized;
   reg          p_rst_b = 1'b1;
   reg          h_cs_b1;
   reg [2:0]    h_addr1;
   reg          h_rdnw1;

   ICAP_core instance_core
     (
      .fastclk(fastclk),
      .design_num(design_num),
      .reconfigure(reconfigure),
      .powerup(1'b0),
      .sw_in(sw_in),
      .sw_out(sw_out),
      .pwr_out(pwr_out),
      .initialized(initialized),
      .test(test)
      );

   always @(posedge fastclk) begin
      if (!p_rst_b || !h_rst_b) begin
         reconfigure <= reconfigure_sw_changed || reconfigure_hw_changed;
      end
   end

   // Latch control signals on the rising egge of Phi2
   // (avoids hold time issues, we do the same in the tube)
   always @(posedge h_phi2) begin
      h_cs_b1 <= h_cs_b;
      h_addr1 <= h_addr;
      h_rdnw1 <= h_rdnw;
   end

   always @(negedge h_phi2) begin
      // Mirror the reset bit of register FEE0, and allow this to reconfigure
      if (!h_cs_b1 && !h_rdnw1 && h_addr1 == 3'b000) begin
        if (h_data[6] && h_data[7]) begin
            // Setting the T bit (bit 6) clears all tube registers
            p_rst_b <= 1'b1;
        end else if (h_data[5]) begin
            // Setting the S bit (bit 5) asserts the parasite reset
            // Clearing the S bit (bit 5) de-asserts the parasite reset
            p_rst_b <= !h_data[7];
        end
      end
      // Implement a write only register at FEE6 to change the current design
      if (!h_cs_b1 && !h_rdnw1 && h_addr1 == 3'b110) begin
         design_num <= h_data[4:0];
         reconfigure_sw_changed <= 1'b1;
      end
      // Detect changes in the DIP Switches, and invoke the multi boot loader as for a power up
      if (initialized) begin
         if (sw_in != pwr_out) begin
            // Someone has moved the hardware DIP switches
            design_num <= 5'b10000;
            reconfigure_hw_changed <= 1'b1;
         end else begin
            // Someone has moved them back again
            reconfigure_hw_changed <= 1'b0;
         end
      end
   end


endmodule

module add8bit (
    input [7:0] in1,
    input [7:0] in2,
    output reg [7:0] sum
    );

    // The sum of two 8-bit unsigned integers can be calculated by simply adding them together.
    // We can use the "+" operator to perform the addition.
    // Since we are using unsigned integers, the output will automatically wrap around if it exceeds 8 bits.

    assign sum = in1 + in2;

endmodule

module adder(
    input [3:0] a,
    input [3:0] b,
    output reg [3:0] sum
);
    reg carry;
    nand_gate n1(.a(a[0]), .b(b[0]), .out(sum[0]));
    nand_gate n2(.a(a[1]), .b(b[1]), .out(sum[1]));
    nand_gate n3(.a(a[2]), .b(b[2]), .out(sum[2]));
    nand_gate n4(.a(a[3]), .b(b[3]), .out(sum[3]));
    nand_gate n5(.a(sum[0]), .b(carry), .out(carry));
    nand_gate n6(.a(sum[1]), .b(sum[0]), .out(carry));
    nand_gate n7(.a(sum[2]), .b(sum[1]), .out(carry));
    nand_gate n8(.a(sum[3]), .b(sum[2]), .out(carry));
    assign carry = ~carry;
endmodule
module top_module(
    input clk,
    input [3:0] a,
    input [3:0] b,
    output reg [2:0] out
);
    reg [3:0] sum;
    wire lt_out;
    magnitude_comp comp(.a(a), .b(b), .lt_out(lt_out));
    adder add(.a(a), .b(b), .sum(sum));
    always @(posedge clk) begin
        if (lt_out) begin
            out <= 3'b001; // a < b
        end else if (a == b) begin
            out <= 3'b000; // a = b
        end else begin
            out <= 3'b010; // a > b
        end
    end
endmodule
module nand_gate(
    input a,
    input b,
    output out
);
    assign out = ~(a & b);
endmodule
module magnitude_comp(
    input [3:0] a,
    input [3:0] b,
    output lt_out
);
    assign lt_out = ~|((a < b) << 3);
endmodule

