module traffic_light_fsm (
  input clk,
  input reset,
  output reg green_light,
  output reg yellow_light,
  output reg red_light,
  output reg pedestrian_crossing
);

  // Define state variables
  parameter GREEN = 2'b00;
  parameter YELLOW = 2'b01;
  parameter RED = 2'b10;
  reg [1:0] state;

  // Define timing variables
  parameter GREEN_TIME = 4'd10; // Time for green light in seconds
  parameter YELLOW_TIME = 4'd2; // Time for yellow light in seconds
  parameter RED_TIME = 4'd8; // Time for red light in seconds
  parameter PED_TIME = 4'd5; // Time for pedestrian crossing in seconds
  reg [3:0] timer;

  // Define state transitions and outputs
  always @(posedge clk) begin
    if (reset) begin
      state <= GREEN;
      timer <= 0;
      green_light <= 1'b1;
      yellow_light <= 1'b0;
      red_light <= 1'b0;
      pedestrian_crossing <= 1'b0;
    end
    else begin
      case (state)
        GREEN: begin
          if (timer == GREEN_TIME) begin
            state <= YELLOW;
            timer <= 0;
            green_light <= 1'b0;
            yellow_light <= 1'b1;
            red_light <= 1'b0;
            pedestrian_crossing <= 1'b0;
          end
          else begin
            timer <= timer + 1;
          end
        end
        YELLOW: begin
          if (timer == YELLOW_TIME) begin
            state <= RED;
            timer <= 0;
            green_light <= 1'b0;
            yellow_light <= 1'b0;
            red_light <= 1'b1;
            pedestrian_crossing <= 1'b0;
          end
          else begin
            timer <= timer + 1;
            yellow_light <= ~yellow_light; // Flash yellow light
          end
        end
        RED: begin
          if (timer == RED_TIME) begin
            state <= GREEN;
            timer <= 0;
            green_light <= 1'b1;
            yellow_light <= 1'b0;
            red_light <= 1'b0;
            pedestrian_crossing <= 1'b0;
          end
          else begin
            timer <= timer + 1;
            if (timer == (RED_TIME - PED_TIME)) begin
              pedestrian_crossing <= 1'b1;
            end
            else if (timer == RED_TIME) begin
              pedestrian_crossing <= 1'b0;
            end
          end
        end
      endcase
    end
  end

endmodule

module ecc_check_pipe (
    input logic clk,
    input logic bank_rd_m3,
    input logic [32:0] data_i,
    output logic ecc_err_o
);

    logic [3:0] check_group_6_0;
    logic check_group_6_0_q;

    // Implement ECC to check for errors in groups of four bits
    always_comb check_group_6_0 = {data_i[0], data_i[2], data_i[4], data_i[7]};

    // Store the result of the ECC in a flip-flop on the rising edge of the clock signal
    always_ff @(posedge clk) begin
        if (bank_rd_m3) begin
            check_group_6_0_q <= ^check_group_6_0;
        end
    end

    // Output whether there is an error in the data stream
    assign ecc_err_o = check_group_6_0_q;

endmodule

module memory_address_module (
  input clk,
  input rstn,
  input [63:0] from_regf,
  input [128+1+1+73+8-1:0] from_dec,
  input db67,
  output reg [2:0] seg_src,
  output reg [31:0] add_src,
  output [7:0] to_regf
);

  wire [7:0] indrm; // Decoder intermediate input
  wire [72:0] indic; // Decoder intermediate input
  wire [127:0] in128; // Decoder intermediate input
  wire sib_dec; // Decoder intermediate input
  wire mod_dec; // Decoder intermediate input
  wire [31:0] reg_base;
  wire [31:0] reg_index;
  wire [31:0] shf_index;
  wire [7:0] modrm, modrmr;
  wire [15:0] disp16;
  wire [7:0] to_regf32, to_regf16;
  reg ov;

  // Split from_deco bus
  assign {in128, mod_dec, sib_dec, indic, indrm} = from_dec;

  // Select Base and index Register
  assign modrm = in128[15:8];
  assign to_regf = db67 ? to_regf32 : to_regf16;
  assign to_regf32[3:0] = (&indrm[1:0]) ? {1'b0, in128[18:16]} : {1'b0, in128[10:8]};
  assign to_regf32[7:4] = (&indrm[1:0]) ? {1'b0, in128[21:19]} : {4'b1111};
  assign disp16 = ({modrm[7:6], modrm[2:0]} == 5'b00110) ? in128[31:16] :
                 ({modrm[7:6]} == 2'b10) ? in128[31:16] :
                 ({modrm[7:6]} == 2'b01) ? {{8{in128[23]}}, in128[23:16]} :
                 16'b0;
  assign to_regf16[3:0] = (modrm[2:1] == 2'b11) ? {4'b1111} : {1'b0, 2'b11, modrm[0]};
  assign to_regf16[7:4] = (modrm[2:1] == 2'b10) ? {4'b1111} :
                          ({modrm[7:6], modrm[2:0]} == 5'b00110) ? {4'b1111} :
                          (modrm[2] == 1'b0) ? {1'b0, modrm[1], ~modrm[1], 1'b1} :
                          {1'b0, ~modrm[0], modrm[0], 1'b1};
  assign reg_base = from_regf[31:0];
  assign reg_index = ((in128[21:19] == 4) && (db67 == 1)) ? 0 : from_regf[63:32];
  assign shf_index = (in128[23:22] == 0) ? reg_index :
                    (in128[23:22] == 1) ? {reg_index[30:0], 1'b0} :
                    (in128[23:22] == 2) ? {reg_index[29:0], 2'b0} :
                    {reg_index[28:0], 3'b0};

  // Put in FFlops the address of memory location to be used for next operation
  always @(posedge clk) begin
    if (db67) begin
      seg_src <= 0;
      if (mod_dec) begin
        case (indrm[4:0])
          5'b00110: begin
            add_src <= in128[47:16];
          end // 32bit only displc
          5'b10010: begin
            {ov, add_src} <= reg_base + {{24{in128[23]}}, in128[23:16]};
          end // no sib - 8bit displc
          5'b10011: begin
            {ov, add_src} <= shf_index + reg_base + {{24{in128[31]}}, in128[31:24]};
          end // sib - 8bit displc
          5'b01010: begin
            {ov, add_src} <= reg_base + in128[47:16];
          end // no sib - 32bit displc
          5'b01011: begin
            {ov, add_src} <= shf_index + reg_base + in128[55:24];
          end // sib - 32bit displc
          5'b00011: if ((indrm[7] == 1) && (to_regf32[3:0] == 4'b0101)) begin
                       {ov, add_src} <= shf_index + in128[55:24];
                     end // sib - 32bit displc only
                     else begin
                       {ov, add_src} <= shf_index + reg_base;
                     end // sib - no displc displc
          5'b00010: begin
            add_src <= reg_base;
          end // no sib - no displc - only base
          default: begin
            add_src <= reg_base;
          end
        endcase
      end else begin
        add_src <= 0;
        ov <= 0;
      end
    end else begin
      if ((mod_dec & indrm[6]) == 1) begin
        seg_src <= 3'b011;
      end else if (mod_dec == 0) begin
        seg_src <= 3'b011;
      end else if (to_regf[7:4] == 4'b0101) begin
        seg_src <= 3'b010;
      end else if (to_regf[7:4] == 4'b0100) begin
        seg_src <= 3'b010;
      end else begin
        seg_src <= 3'b011;
      end
      ov <= 0;
      if (mod_dec) begin
        add_src[15:0] <= reg_base[15:0] + reg_index[15:0] + disp16;
        add_src[31:16] <= 16'b0;
      end else begin
        add_src <= 0;
      end
    end
  end

endmodule

