module mem_controller (
  input clk,
  input rst,
  input [7:0] addr,
  input we,
  input [7:0] din,
  output [7:0] dout
);

  // Define memory array with 256 words of 8 bits each
  reg [7:0] memory [0:255];

  // Define internal signals for address and data
  reg [7:0] addr_reg;
  reg [7:0] din_reg;
  wire [7:0] dout_reg;

  // Synchronize address and data inputs with the clock
  always @(posedge clk) begin
    if (rst) begin
      addr_reg <= 8'h00;
      din_reg <= 8'h00;
    end else begin
      addr_reg <= addr;
      if (we) begin
        din_reg <= din;
      end
    end
  end

  // Read or write data from/to memory based on we input
  always @(*) begin
    if (we) begin
      memory[addr_reg] <= din_reg;
    end else begin
      dout_reg <= memory[addr_reg];
    end
  end

  // Synchronize output data with the clock
  always @(posedge clk) begin
    if (rst) begin
      dout <= 8'h00;
    end else begin
      dout <= dout_reg;
    end
  end

endmodule

module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    output reg [3:0] S,
    output reg Cout
);

    wire [3:0] C; // Carry bits
    wire [3:0] S1; // Intermediate sums
    wire C4; // Carry-out from the 4th full adder

    // Instantiate four full adders and connect them together
    sky130_fd_sc_hd__fulladder fa0(.A(A[0]), .B(B[0]), .Cin(1'b0), .S(S1[0]), .Cout(C[0]));
    sky130_fd_sc_hd__fulladder fa1(.A(A[1]), .B(B[1]), .Cin(C[0]), .S(S1[1]), .Cout(C[1]));
    sky130_fd_sc_hd__fulladder fa2(.A(A[2]), .B(B[2]), .Cin(C[1]), .S(S1[2]), .Cout(C[2]));
    sky130_fd_sc_hd__fulladder fa3(.A(A[3]), .B(B[3]), .Cin(C[2]), .S(S1[3]), .Cout(C4));

    // Assign the final sum and carry-out
    assign S = S1;
    assign Cout = C4;

endmodule

module xor_nor(
