module driver_vga_1024x768(clk_vga, hs, vs, hc_visible, vc_visible);
    input clk_vga;
    output hs, vs, hc_visible, vc_visible;

    parameter H_SYNC_WIDTH = 96;
    parameter V_SYNC_WIDTH = 2;
    parameter H_FRONT_PORCH = 24;
    parameter H_BACK_PORCH = 136;
    parameter V_FRONT_PORCH = 16;
    parameter V_BACK_PORCH = 6;
    parameter H_VISIBLE = 1024;
    parameter V_VISIBLE = 768;

    reg [10:0] h_count = 0;
    reg [9:0] v_count = 0;

    always @(posedge clk_vga) begin
        if (h_count == 0) begin
            hc_visible <= 0;
        end else if (h_count < H_FRONT_PORCH + H_SYNC_WIDTH + H_BACK_PORCH) begin
            hc_visible <= 1;
        end else begin
            hc_visible <= 0;
        end

        if (v_count == 0) begin
            vc_visible <= 0;
        end else if (v_count < V_FRONT_PORCH + V_SYNC_WIDTH + V_BACK_PORCH) begin
            vc_visible <= 1;
        end else begin
            vc_visible <= 0;
        end

        if (h_count == H_SYNC_WIDTH) begin
            hs <= 0;
        end else if (h_count == 0) begin
            hs <= 1;
        end

        if (v_count == V_SYNC_WIDTH) begin
            vs <= 0;
        end else if (v_count == 0) begin
            vs <= 1;
        end

        h_count <= h_count + 1;
        if (h_count == H_FRONT_PORCH + H_SYNC_WIDTH + H_BACK_PORCH - 1) begin
            h_count <= 0;
            v_count <= v_count + 1;
            if (v_count == V_FRONT_PORCH + V_SYNC_WIDTH + V_BACK_PORCH + V_VISIBLE - 1) begin
                v_count <= 0;
            end
        end
    end
endmodule

