module digital_clock(
    input clk_1hz,
    output reg [3:0] hours,
    output reg [3:0] minutes,
    output reg [3:0] seconds
);

reg [24:0] count = 0; // 25 bits to count up to 24 hours

always @(posedge clk_1hz) begin
    count <= count + 1;
    if (count == 86400) // reset after 24 hours
        count <= 0;
end

always @(posedge clk_1hz) begin
    if (count % 60 == 0) begin // increment minutes
        if (minutes == 9) begin
            minutes <= 0;
            if (hours == 23)
                hours <= 0;
            else
                hours <= hours + 1;
        end
        else
            minutes <= minutes + 1;
    end
    if (count % 3600 == 0) begin // increment hours
        if (hours == 9 && minutes == 59)
            hours <= hours + 1;
        else if (hours == 23)
            hours <= 0;
        else
            hours <= hours + 1;
    end
    if (count % 60 == 0) // increment seconds
        if (seconds == 59)
            seconds <= 0;
        else
            seconds <= seconds + 1;
end

assign hours = {4'b0, hours}; // pad with leading 0
assign minutes = {4'b0, minutes}; // pad with leading 0
assign seconds = {4'b0, seconds}; // pad with leading 0

endmodule

