module binary_to_decimal (
    input [7:0] binary_input,
    output reg [7:0] decimal_output
);

reg [7:0] temp;
reg [2:0] i;

always @(*) begin
    temp = 0;
    for (i = 0; i < 8; i = i + 1) begin
        if (binary_input[i] == 1) begin
            case (i)
                0: temp = temp + 1;
                1: temp = temp + 2;
                2: temp = temp + 4;
                3: temp = temp + 8;
                4: temp = temp + 16;
                5: temp = temp + 32;
                6: temp = temp + 64;
                7: temp = temp + 128;
            endcase
        end
    end
    decimal_output = temp;
end

endmodule

