module top_module ( 
    input clk, 
    input reset,      // Synchronous active-high reset
    input [7:0] d,    // 8-bit input for the register
    input select,     // Select input to choose between register and counter
    output [3:0] counter_out, // 4-bit output from the counter
    output [7:0] and_out    // 8-bit output from the functional module
);

    // D flip-flop module
    reg [7:0] reg_out;
    always @(negedge clk) begin
        if (reset) begin
            reg_out <= 8'h34;
        end else begin
            reg_out <= d;
        end
    end

    // Binary counter module
    reg [3:0] count;
    always @(posedge clk) begin
        if (reset || select) begin
            count <= 4'h0;
        end else begin
            count <= count + 1;
        end
    end

    // Functional module
    assign and_out = reg_out & count;

    // Control logic module
    assign counter_out = select ? count : 4'h0;

endmodule

module twos_comp_addsub (
    input signed [15:0] a,
    input signed [15:0] b,
    input sub,
    output reg signed [15:0] result,
    output reg overflow
);

    always @(*) begin
        if (sub) begin
            result = a - b;
            overflow = ((a < 0) & (b > 0) & (result > 0)) | ((a > 0) & (b < 0) & (result < 0));
        end else begin
            result = a + b;
            overflow = ((a > 0) & (b > 0) & (result < 0)) | ((a < 0) & (b < 0) & (result > 0));
        end
    end

endmodule

module fsm_3bit_sequence_detection (
  input clk,
  input reset,
  input data,
  output reg match
);

parameter S0 = 2'b00;
parameter S1 = 2'b01;
parameter S2 = 2'b10;

reg [1:0] state;
reg match_reg;

always @ (posedge clk or posedge reset) begin
  if (reset) begin
    state <= S0;
    match_reg <= 1'b0;
  end
  else begin
    case (state)
      S0: begin
        if (data == 1'b1)
          state <= S1;
        else
          state <= S0;
      end
      S1: begin
        if (data == 1'b0)
          state <= S0;
        else
          state <= S2;
      end
      S2: begin
        if (data == 1'b1)
          match_reg <= 1'b1;
        state <= S0;
      end
      default: state <= S0;
    endcase
  end
end

assign match = match_reg;

endmodule

