    inout [31:0] wb_dat_i;
    output [31:0] wb_dat_o;
    output wb_ack_o;
    output wb_int_o;

    reg [31:0] mem [0:15]; // 16 32-bit memory locations

    assign wb_dat_o = (wb_sel_i[0] == 1'b1) ? mem[wb_adr_i[1:2]][7:0] :
                     (wb_sel_i[1] == 1'b1) ? mem[wb_adr_i[1:2]][15:8] :
                     (wb_sel_i[2] == 1'b1) ? mem[wb_adr_i[1:2]][23:16] :
                     (wb_sel_i[3] == 1'b1) ? mem[wb_adr_i[1:2]][31:24] :
                     32'h00000000;

    always @(*) begin
        if (wb_cyc_i && wb_stb_i) begin
            if (wb_we_i) begin
                if (wb_sel_i[0]) mem[wb_adr_i[1:2]][7:0] <= wb_dat_i[7:0];
                if (wb_sel_i[1]) mem[wb_adr_i[1:2]][15:8] <= wb_dat_i[15:8];
                if (wb_sel_i[2]) mem[wb_adr_i[1:2]][23:16] <= wb_dat_i[23:16];
                if (wb_sel_i[3]) mem[wb_adr_i[1:2]][31:24] <= wb_dat_i[31:24];
                wb_ack_o <= 1'b1;
            end else begin
                wb_dat_i <= (wb_sel_i[0] == 1'b1) ? mem[wb_adr_i[1:2]][7:0] :
                            (wb_sel_i[1] == 1'b1) ? mem[wb_adr_i[1:2]][15:8] :
                            (wb_sel_i[2] == 1'b1) ? mem[wb_adr_i[1:2]][23:16] :
                            (wb_sel_i[3] == 1'b1) ? mem[wb_adr_i[1:2]][31:24] :
                            32'h00000000;
                wb_ack_o <= 1'b1;
            end
        end else begin
            wb_ack_o <= 1'b0;
        end
    end

    assign wb_int_o = 1'b0;

endmodule

module tx_gear #(
                parameter GWIDTH = 20
                ) 
   (
   input wire                clk_125 ,    // 125 Mhz clock.
   input wire                clk_250 ,    // 250 Mhz clock.
   input wire                rst_n ,      // asynchronous system reset.

   input wire                drate_enable,  //Enable for Counters
   input wire [GWIDTH-1:0]   data_in ,    // Data In

   output reg [GWIDTH/2-1:0] data_out     // Data Out
   );
// =============================================================================

reg [1:0]                 wr_pntr;    // Write Pointer
reg [1:0]                 rd_pntr;    // Read Pointer
reg                       rd_en;      // Read Pointer Enable

wire [GWIDTH/2-1:0]       rd_data0;   // Read Data
wire [GWIDTH/2-1:0]       rd_data1;   // Read Data

integer                   i;
integer                   j;

// RAM's : Expected to inferred as distributed ram
reg [GWIDTH/2-1:0]        rf_0[0:3] ;
reg [GWIDTH/2-1:0]        rf_1[0:3] ;

reg                       drate_f0 /* synthesis syn_srlstyle="registers" */;
reg                       drate_f1 /* synthesis syn_srlstyle="registers" */;
reg                       drate_s0;

reg                       rd_enable;
reg[2:0]                  rd_cnt;

//synchronize drate_enable to 250mhz clock
always @(posedge clk_250, negedge rst_n) begin 
   if (!rst_n) begin
      drate_f0 <= 1'b0;
      drate_f1 <= 1'b0;
   end
   else begin
      drate_f0 <= drate_enable;
      drate_f1 <= drate_f0;
   end
end

// delay drate_enable by a 125mhz clock 
// to adjust synchronizer delay
always @(posedge clk_125, negedge rst_n) begin 
   if (!rst_n)
      drate_s0 <= 1'b0;
   else 
      drate_s0 <= drate_enable;
end

// =============================================================================
// Write 8 bits each into different memories out of incomming 
// 16 bits data at 125 Mhz.
// Read 8 bits of data, alternatively from each memory at 250 Mhz.
// =============================================================================

// Write Pointer
always @(posedge clk_125, negedge rst_n) begin 
   if (!rst_n)
      wr_pntr <= 2'b00;
   else if(drate_s0)
      wr_pntr <= wr_pntr + 2'b01;
   else
      wr_pntr <= wr_pntr;
end

// Read Pointer Enable for half-rate 
always @(posedge clk_250, negedge rst_n) begin 
   if (!rst_n)
      rd_en <= 1'b0;
   else if(~drate_f1)
      rd_en <= 1'b0;
   else
      rd_en <= ~rd_en;
end

// Read Pointer
always @(posedge clk_250, negedge rst_n) begin 
   if (!rst_n)
      rd_pntr <= 2'b10;
   else if (rd_en & drate_f1)
      rd_pntr <= rd_pntr + 2'b01;
end

// Output Data Select
always @(posedge clk_250, negedge rst_n) begin 
   if (!rst_n)
      data_out <= 0;
   else begin
      if(rd_enable) 
         data_out <= rd_en ? rd_data0 : rd_data1;
      else
         data_out <= 10'b1000000000; // Bit 9 is TxElecIdle
   end
end

// =============================================================================


always @(posedge clk_125, negedge rst_n) begin 
   if (!rst_n)
      for (i=0;i<=3;i=i+1) 
         rf_0[i] <= 0;
   else 
      rf_0[wr_pntr] <= data_in[GWIDTH/2-1:0] ;
end
assign rd_data0 = rf_0[rd_pntr] ;

always @(posedge clk_125, negedge rst_n) begin 
   if (!rst_n)
      for (j=0;j<=3;j=j+1) 
         rf_1[j] <= 0;
   else 
      rf_1[wr_pntr] <= data_in[GWIDTH-1:GWIDTH/2] ;
end
assign rd_data1 = rf_1[rd_pntr] ;

// =============================================================================
// Avoid RESET data from Dist. Memory
// Take Read data after Writing, until then EI is HIGH
// Wait for 8 (250 Mhz) clks after enable
// =============================================================================
always @(posedge clk_250, negedge rst_n) begin 
   if (!rst_n) begin
      rd_cnt    <= 3'b000;
      rd_enable <= 1'b0;
   end
   else begin
      if(drate_f1)
         rd_cnt <= rd_cnt + 3'b001;
      else
         rd_cnt <= 3'b000;

      if(~drate_f1)
         rd_enable <= 1'b0;
      else if(rd_cnt == 3'b111) 
         rd_enable <= 1'b1;
   end
end

endmodule

module memory (
    input rst,          // reset input
    input ce,           // chip enable
    input [31:0] data_i, // data input
    input [9:0] addr_i,  // address input
    input we,           // write enable
    input [3:0] byte_slct, // byte select
    output [31:0] data_o // data output
);

    reg [31:0] mem [0:1023];
    reg [31:0] data_o;
    integer i;

    always @(posedge ce or posedge rst) begin
        if (rst) begin
            for (i = 0; i < 1024; i = i + 1) begin
                mem[i] = 0;
            end
        end else if (ce) begin
            if (we) begin
                case (byte_slct)
                    4'b0001: mem[addr_i][7:0] = data_i[7:0];
                    4'b0010: mem[addr_i][15:8] = data_i[15:8];
                    4'b0100: mem[addr_i][23:16] = data_i[23:16];
                    4'b1000: mem[addr_i][31:24] = data_i[31:24];
                    4'b0011: mem[addr_i][15:0] = data_i[15:0];
                    4'b1100: mem[addr_i][31:16] = data_i[31:16];
                    default: mem[addr_i] = data_i;
                endcase
            end else begin
                case (byte_slct)
                    4'b0001: data_o = {24'hzz, mem[addr_i][7:0]};
                    4'b0010: data_o = {24'hzz, mem[addr_i][15:8]};
                    4'b0100: data_o = {24'hzz, mem[addr_i][23:16]};
                    4'b1000: data_o = {24'hzz, mem[addr_i][31:24]};
                    4'b0011: data_o = {16'hzz, mem[addr_i][15:0]};
                    4'b1100: data_o = mem[addr_i][31:16];
                    default: data_o = mem[addr_i];
                endcase
            end
        end
    end
endmodule

module top_module(
    input clk,
    input [2047:0] in,
    output reg [5:0] out
);

    reg [3:0] shift_reg;
    reg [5:0] pop_count;

    always @(posedge clk) begin
        shift_reg[0] <= in[2047];
        shift_reg[1] <= shift_reg[0];
        shift_reg[2] <= shift_reg[1];
        shift_reg[3] <= shift_reg[2];

        pop_count = {shift_reg[3], shift_reg[2], shift_reg[1], shift_reg[0]};
        out <= $countones(pop_count);
    end

endmodule

module microphone
(
    input   reset,
    output  ledres,
    input   clk,
    output  mclk,
    output  reg micLRSel,
    input   micData,
    output  ampPWM,
    output  ampSD,
    input   rd, wr,
    output  empty,
    output  full,
    output  reg done
);

    // FIFO buffer
    wire [7:0] dout;
    wire [7:0] dout1;
    reg [7:0] sregt1;
    reg [7:0] sregt;
    reg [7:0] count;

    fifo fi(
        .reset(reset),
        .din(sregt1),
        .dout(dout),
        .clock(done),
        .rd(rd),
        .wr(wr),
        .empty(empty),
        .full(full)
    );

    // PWM module
    pwm pw(
        .ampSD(ampSD),
        .reset(reset),
        .mclk(mclk),
        .ampPWM(ampPWM),
        .clk(clk),
        .dout(dout1)
    );

    // Frequency divider
    reg [10:0] clkDiv = 0;
    reg mclk1 = 0;
    always @(posedge clk) begin
        if (reset) begin
            clkDiv <= 0;
        end else begin
            clkDiv <= clkDiv + 1;
            if (clkDiv == 1999) begin
                clkDiv <= 0;
                mclk1 <= ~mclk1;
            end
        end
    end

    assign mclk = mclk1;

    // Microphone sampling
    initial micLRSel <= 0;
    initial count <= 0;
    initial sregt <= 0;
    initial sregt1 <= 0;

    always @(posedge mclk) begin
        if (reset) begin
            sregt <= 0;
        end else begin
            if (count <= 7) begin
                sregt <= {sregt[7:0], micData};
                count <= count + 1;
                done <= 0;
            end else begin
                count <= 0;
                done <= 1;
                sregt1 <= sregt;
            end
        end
    end

endmodule

