module full_adder(
    input A,
    input B,
    input CIN,
    output SUM,
    output COUT
);

    assign SUM = A ^ B ^ CIN;
    assign COUT = (A & B) | (CIN & (A ^ B));

endmodule

module memory_interface (
    input clk,
    input [31:0] addr,
    input [31:0] din,
    input enable,
    input rw,
    input [1:0] access_size,
    input test_mode,
    input [31:0] int_addr,
    output reg [31:0] dout,
    output reg busy
);

    parameter START_ADDR = 32'h8002_0000;
    parameter MEM_SIZE = 256;
    parameter WORD_SIZE = 4;
    parameter HALF_SIZE = 2;
    parameter BYTE_SIZE = 1;

    reg [7:0] mem [0:MEM_SIZE-1];
    reg [31:0] local_addr;
    reg [31:0] mips_addr;
    reg [31:0] mips_data;
    wire [31:0] mem_data;
    wire [31:0] mem_addr;
    wire busy_mem;

    assign mem_addr = addr - START_ADDR;

    mips_memory2 mem_inst (
        .clk(clk),
        .addr(mips_addr),
        .din(mips_data),
        .dout(mem_data),
        .access_size(access_size),
        .rw(rw),
        .busy(busy_mem),
        .enable(enable)
    );

    always @ (posedge clk) begin
        if (test_mode == 1) begin
            local_addr = int_addr;
            mips_addr = addr;
            mips_data = mem[local_addr];
            dout = mem_data;
            if (busy_mem == 0) begin
                mips_data = dout;
                busy = 1;
                local_addr = local_addr + WORD_SIZE;
                int_addr = int_addr + WORD_SIZE;
                if (local_addr == (MEM_SIZE * WORD_SIZE)) begin
                    local_addr = 0;
                    int_addr = 0;
                    addr = addr + (9 * WORD_SIZE);
                end
            end else begin
                busy = 1;
            end
        end else begin
            if (enable == 1) begin
                if (rw == 1) begin
                    case (access_size)
                        2'b00: mem[mem_addr] = din[7:0];
                        2'b01: mem[mem_addr] = din[15:0];
                        2'b10: mem[mem_addr] = din[31:0];
                    endcase
                end else begin
                    case (access_size)
                        2'b00: dout = mem[mem_addr];
                        2'b01: dout = {mem[mem_addr+1], mem[mem_addr]};
                        2'b10: dout = {mem[mem_addr+3], mem[mem_addr+2], mem[mem_addr+1], mem[mem_addr]};
                    endcase
                end
                local_addr = local_addr + WORD_SIZE;
                if (local_addr == (MEM_SIZE * WORD_SIZE)) begin
                    local_addr = 0;
                    addr = addr + (9 * WORD_SIZE);
                end
            end
        end
    end

endmodule

module bitwise_operations (
  input [31:0] a,
  input [31:0] b,
  input [1:0] operation_select,
  input [4:0] shift_amount,
  output [31:0] result
);

  // Pipeline registers
  reg [31:0] a_reg1, a_reg2, a_reg3;
  reg [31:0] b_reg1, b_reg2, b_reg3;
  reg [1:0] op_reg1, op_reg2, op_reg3;
  reg [4:0] shift_reg1, shift_reg2, shift_reg3;

  // Stage 1
  always @(*) begin
    a_reg1 = a;
    b_reg1 = b;
    op_reg1 = operation_select;
    shift_reg1 = shift_amount;
  end

  // Stage 2
  always @(posedge clk) begin
    a_reg2 = a_reg1;
    b_reg2 = b_reg1;
    op_reg2 = op_reg1;
    shift_reg2 = shift_reg1;
  end

  // Stage 3
  always @(posedge clk) begin
    a_reg3 = a_reg2;
    b_reg3 = b_reg2;
    op_reg3 = op_reg2;
    shift_reg3 = shift_reg2;
  end

  // Stage 4
  always @(posedge clk) begin
    case(op_reg3)
      2'b00: result <= a_reg3 & b_reg3; // AND
      2'b01: result <= a_reg3 | b_reg3; // OR
      2'b10: result <= a_reg3 ^ b_reg3; // XOR
      2'b11: result <= a_reg3 << shift_reg3; // Shift left
    endcase
  end

endmodule

module top_module( 
    input clk,
    input [7:0] reset,      // Asynchronous reset
    input [4:0] in,
    output out_and,
    output out_or,
    output out_nor
);

    // 8 D flip-flops with active high asynchronous reset
    reg [7:0] flip_flops;
    always @(negedge clk) begin
        if (reset[0]) flip_flops[0] <= 1'b0;
        else flip_flops[0] <= in[0];
        if (reset[1]) flip_flops[1] <= 1'b0;
        else flip_flops[1] <= in[1];
        if (reset[2]) flip_flops[2] <= 1'b0;
        else flip_flops[2] <= in[2];
        if (reset[3]) flip_flops[3] <= 1'b0;
        else flip_flops[3] <= in[3];
        if (reset[4]) flip_flops[4] <= 1'b0;
        else flip_flops[4] <= in[4];
        if (reset[5]) flip_flops[5] <= 1'b0;
        else flip_flops[5] <= in[5];
        if (reset[6]) flip_flops[6] <= 1'b0;
        else flip_flops[6] <= in[6];
        if (reset[7]) flip_flops[7] <= 1'b0;
        else flip_flops[7] <= in[7];
    end

    // 2-to-4 decoder with enable
    wire [3:0] decoder_out;
    assign decoder_out = (in[4]) ? 4'b0001 : 4'b0000;

    // 5-input AND, OR, and NOR gate
    wire and_out, or_out, nor_out;
    and_gate and_gate_inst(.in(flip_flops[decoder_out]), .out(and_out));
    or_gate or_gate_inst(.in(flip_flops[decoder_out]), .out(or_out));
    nor_gate nor_gate_inst(.in(flip_flops[decoder_out]), .out(nor_out));

    // Output
    assign out_and = and_out;
    assign out_or = or_out;
    assign out_nor = nor_out;

endmodule

// AND gate module
module and_gate(
    input [3:0] in,
    output out
);
    assign out = &in;
endmodule

// OR gate module
module or_gate(
    input [3:0] in,
    output out
);
    assign out = |in;
endmodule

// NOR gate module
module nor_gate(
    input [3:0] in,
    output out
);
    assign out = ~|in;
endmodule

