   // Inputs
   clk
   );
   parameter PAR = 3;

   m1 #(PAR) m1();
   m3 #(PAR) m3();
   mnooverride #(10) mno();

   input clk;
   integer cyc=1;
   reg [4:0] bitsel;

   always @ (posedge clk) begin
      cyc <= cyc + 1;
      if (cyc==0) begin
         bitsel = 0;
         if (PAR[bitsel]!==1'b1) $stop;
         bitsel = 1;
         if (PAR[bitsel]!==1'b1) $stop;
         bitsel = 2;
         if (PAR[bitsel]!==1'b0) $stop;
      end
      if (cyc==1) begin
         $write("*-* All Finished *-*\n");
         $finish;
      end
   end

endmodule

module Schmitt_trigger (
  input in,
  output reg out
);

  parameter Vt_plus = 1.5; // Upper threshold voltage
  parameter Vt_minus = 0.5; // Lower threshold voltage

  always @(*) begin
    if (in > Vt_plus) // Input voltage is above upper threshold
      out = 1'b1;
    else if (in < Vt_minus) // Input voltage is below lower threshold
      out = 1'b0;
  end

endmodule

module ramp_a_tone(
    input rst,
    input clk,
    output reg [15:0] tone
);
    reg [15:0] ramp = 0;
    always @(posedge clk) begin
        if (rst) begin
            ramp <= 0;
            tone <= 0;
        end else begin
            ramp <= ramp + 1;
            tone <= ramp;
        end
    end
endmodule

// Module 2: sh_encode
module sh_encode(
    input rst,
    input ym_p1,
    input [15:0] data,
    output reg sh,
    output reg so
);
    reg [15:0] data_shifted = 0;
    always @(posedge ym_p1) begin
        if (rst) begin
            data_shifted <= 0;
            sh <= 0;
            so <= 0;
        end else begin
            data_shifted <= {data_shifted[14:0], data[0]};
            sh <= data[15] ^ data_shifted[14];
            so <= sh ^ data[15];
        end
    end
endmodule

// Module 3: ym_linearize
module ym_linearize(
    input rst,
    input sh,
    input ym_so,
    input ym_p1,
    input [15:0] linear
);
    reg [15:0] prev_linear = 0;
    always @(posedge ym_p1) begin
        if (rst) begin
            prev_linear <= 0;
            linear <= 0;
        end else begin
            if (sh) begin
                prev_linear <= linear;
                linear <= ym_so ? -prev_linear : prev_linear;
            end
        end
    end
endmodule

// Module 4: sigma_delta1
module sigma_delta1(
    input rst,
    input clk,
    input [15:0] data,
    output reg onebit
);
    reg [15:0] integrator = 0;
    always @(posedge clk) begin
        if (rst) begin
            integrator <= 0;
            onebit <= 0;
        end else begin
            integrator <= integrator + data - onebit;
            onebit <= integrator[15];
        end
    end
endmodule

// Module 5: fake_tone
module fake_tone(
    input rst,
    input clk,
    input ym_p1,
    output onebit
);
    wire [15:0] tone, linear;
    wire sh, so;

    ramp_a_tone tonegen( .rst(rst), .clk(clk), .tone(tone) );
    sh_encode encoder(   .rst(rst), .ym_p1(ym_p1), .data(tone), .sh(sh), .so(so) );
    ym_linearize linearizer( .rst(rst), .sh(sh), .ym_so(so), .ym_p1(ym_p1), .linear(linear) );
    sigma_delta1 sd1(    .rst(rst), .clk(clk), .data(linear), .onebit(onebit) );    
endmodule

module clk32to40_exdes (
  input CLK_IN1,
  input COUNTER_RESET,
  output reg [1:1] CLK_OUT,
  output wire COUNT
);

  // PLL parameters
  localparam integer N = 4;
  localparam integer M = 400;
  localparam integer FPD = 10;
  localparam integer Kp = 0.5;
  localparam integer Ki = 0.1;
  localparam integer Kd = 0.01;

  // Phase detector and loop filter
  reg [31:0] phase_error;
  reg [31:0] phase_error_integral;
  reg [31:0] phase_error_derivative;
  reg [31:0] loop_filter_output;

  // Counter for dividing output clock signal
  reg [1:0] counter;

  // Generate the divided clock signal
  always @(posedge CLK_IN1) begin
    if (COUNTER_RESET) begin
      counter <= 0;
      CLK_OUT <= 2'b00;
    end else begin
      counter <= counter + 1;
      CLK_OUT <= {counter[0], ~counter[0]};
    end
  end

  // Calculate phase error and adjust output clock signal phase
  always @(posedge CLK_OUT) begin
    phase_error <= (N*(FREQ/2))/FPD - $floor(N*(FREQ/2)/FPD);
    phase_error_integral <= phase_error_integral + phase_error;
    phase_error_derivative <= phase_error - loop_filter_output;
    loop_filter_output <= Kp*phase_error + Ki*phase_error_integral + Kd*phase_error_derivative;
  end

  assign COUNT = counter[1];

