module unsigned_booth_multiplier (
    input clk,
    input rst,
    input [3:0] multiplicand,
    input [3:0] multiplier,
    output reg [7:0] product
);

reg [3:0] A;
reg [3:0] S;
reg [2:0] count;

always @(posedge clk) begin
    if (rst) begin
        product <= 8'b0;
        A <= 4'b0;
        S <= {multiplier, 1'b0};
        count <= 3'b0;
    end else begin
        if (count == 3'b0) begin
            if (S[1:0] == 2'b01) begin
                product <= product + {A, multiplicand};
            end else if (S[1:0] == 2'b10) begin
                product <= product + {~A + 1, multiplicand};
            end
            S <= {S[2], S[3], A[3], S[1:0]};
            A <= 4'b0;
            count <= 3'b1;
        end else begin
            if (S[1:0] == 2'b01) begin
                A <= A + multiplicand;
            end else if (S[1:0] == 2'b10) begin
                A <= A - multiplicand;
            end
            S <= {S[2], S[3], A[3], S[1:0]};
            count <= count + 1;
        end
    end
end

endmodule

module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [2:0] a,    // First 3-bit binary number
    input [2:0] b,    // Second 3-bit binary number
    input select,     // Select input to choose between XOR gate and logical operations module
    output [2:0] q    // 3-bit output from the functional module
);

