module carry_lookahead_adder(
    input [7:0] a,
    input [7:0] b,
    input cin,
    output [7:0] s,
    output cout
);

wire [7:0] g, p;
wire [6:0] c;

assign g = a & b;
assign p = a ^ b;

assign c[0] = cin;
assign c[1] = g[0] | (p[0] & c[0]);
assign c[2] = g[1] | (p[1] & c[1]);
assign c[3] = g[2] | (p[2] & c[2]);
assign c[4] = g[3] | (p[3] & c[3]);
assign c[5] = g[4] | (p[4] & c[4]);
assign c[6] = g[5] | (p[5] & c[5]);
assign cout = g[6] | (p[6] & c[6]);

assign s = a + b + cin;

endmodule

