    .DESKEW_ADJUST         ("SYSTEM_SYNCHRONOUS"),
    .PHASE_SHIFT           (0),
    .STARTUP_WAIT          ("FALSE"))
  dcm_sp_inst
    // Input clock
   (.CLKIN                 (clkin1),
    .CLKFB                 (clkfb),
    // Output clocks
    .CLK0                  (clk0),
    .CLK90                 (),
    .CLK180                (),
    .CLK270                (),
    .CLK2X                 (clk2x),
    .CLK2X180              (),
    .CLKFX                 (clkfx),
    .CLKFX180              (),
    .CLKDV                 (clkdv),
    // Ports for dynamic phase shift
    .PSCLK                 (1'b0),
    .PSEN                  (1'b0),
    .PSINCDEC              (1'b0),
    .PSDONE                (psdone_unused), // Unused output labeled unused
    // Other control and status signals
    .LOCKED                (locked_int),
    .STATUS                (status_int),
    .RST                   (1'b0),
    // Unused pin- tie low
    .DSSEN                 (1'b0));

    assign LOCKED = locked_int;

  // Output buffering
  //-----------------------------------
  BUFG clkf_buf
   (.O (clkfb),
    .I (clk2x));

  BUFG clkout1_buf
   (.O   (CLK_100M),
    .I   (clk2x));


  BUFG clkout2_buf
   (.O   (CLK_50M),
    .I   (clk0));

  BUFG clkout3_buf
   (.O   (CLK_25M),
    .I   (clkdv));

  BUFG clkout4_buf
   (.O   (CLK_10M),
    .I   (clkfx));

  // Ensure that the output signals are generated with the correct frequency
  // as specified in the parameter values of the DCM_SP primitive.
  parameter CLK_PERIOD = 10.0; // Set the clock period in nanoseconds
  assign CLK_100M = clk2x;
  assign CLK_50M = clk0;
  assign CLK_25M = clkdv;
  assign CLK_10M = clkfx;

  // Set the LOCKED signal to 1 when the output clocks are locked to the input clock signal,
  // and 0 otherwise.
  assign locked_int = (status_int[0] == 1'b1);

endmodule

module addsub_32 (
    input signed [31:0] A,
    input signed [31:0] B,
    input C,
    output signed [31:0] S,
    output V
);

    wire [31:0] notB;
    wire [31:0] carryIn;
    wire [31:0] carryOut;
    wire [31:0] sum;
    wire [31:0] notSum;
    wire overflow;

    assign notB = ~B;
    assign carryIn = {32{C}};
    assign {carryOut, sum} = A + notB + carryIn;
    assign notSum = ~sum;
    assign overflow = (A[31] == B[31] && A[31] != sum[31]) ? 1 : 0;

    assign S = (C == 1) ? sum : (notSum + 1);
    assign V = overflow;

endmodule

module binary_adder(
    input [3:0] A,
    input [3:0] B,
    input CIN,
    output [3:0] SUM,
    output COUT
);

    wire [3:0] carry;
    wire [3:0] sum;

    full_adder fa0(A[0], B[0], CIN, sum[0], carry[0]);
    full_adder fa1(A[1], B[1], carry[0], sum[1], carry[1]);
    full_adder fa2(A[2], B[2], carry[1], sum[2], carry[2]);
    full_adder fa3(A[3], B[3], carry[2], sum[3], COUT);

    assign SUM = sum;

endmodule

module full_adder(
    input A,
    input B,
    input CIN,
    output SUM,
    output COUT
);

    assign SUM = A ^ B ^ CIN;
    assign COUT = (A & B) | (A & CIN) | (B & CIN);

endmodule

module dffrl (din, clk, rst_l, q, se, si, so);

parameter SIZE = 1;

input	[SIZE-1:0]	din ;	// data in
input			clk ;	// clk or scan clk
input			rst_l ;	// reset

output	[SIZE-1:0]	q ;	// output

input			se ;	// scan-enable
input	[SIZE-1:0]	si ;	// scan-input
output	[SIZE-1:0]	so ;	// scan-output

reg 	[SIZE-1:0]	q ;

always @ (posedge clk) begin
    if (rst_l == 1'b0) begin
        q <= {SIZE{1'b0}};
    end else begin
        q <= (se == 1'b1) ? si : din;
    end
end

assign so = q;

endmodule

module priority_encoder (
    input [7:0] a, b, c, d,
    output reg [1:0] out
);

always @* begin
    if (a <= b && a <= c && a <= d) out = 2'b00;
    else if (b <= c && b <= d) out = 2'b01;
    else if (c <= d) out = 2'b10;
    else out = 2'b11;
end

endmodule

module mux (
    input [7:0] a, b, c, d,
    input [1:0] sel,
    output reg [7:0] out
);

always @* begin
    case (sel)
        2'b00: out = a;
        2'b01: out = b;
        2'b10: out = c;
        2'b11: out = d;
    endcase
end

endmodule

module comb_logic (
    input [99:0] in,
    output reg out_and,
    output reg out_or,
    output reg out_xor
);

wire [49:0] and_wires;
wire [49:0] or_wires;
wire [49:0] xor_wires;

assign and_wires = {50{1'b1}} & in[49:0];
assign or_wires = {50{1'b0}} | in[49:0];
assign xor_wires = {50{1'b0}} ^ in[49:0];

assign out_and = &and_wires;
assign out_or = |or_wires;
assign out_xor = ^xor_wires;

endmodule

