module freq_synth (
  input clk_ref,
  input [n-1:0] ctrl,
  output reg clk_syn
);

parameter n = 8; // number of bits used to represent the division ratio
parameter f_max = 100; // maximum output frequency that can be generated

reg [n-1:0] count; // binary counter for division ratio
reg [n-1:0] max_count; // maximum count value based on control signal
reg [31:0] divider; // divider to limit maximum output frequency

always @ (posedge clk_ref) begin
  if (count == max_count) begin
    count <= 0;
    clk_syn <= ~clk_syn;
  end else begin
    count <= count + 1;
  end
end

always @ (ctrl) begin
  max_count <= 2**ctrl;
  divider <= f_max * max_count;
end

endmodule

module eight_to_one(
    input [2:0] A1,
    input [2:0] A2,
    input [2:0] B1,
    input [2:0] B2,
    input [2:0] C1,
    input [2:0] C2,
    input [2:0] D1,
    input [2:0] D2,
    output reg [2:0] Y
);

    always @* begin
        // Find the maximum of the A group
        if (A1 > A2) begin
            Y = A1;
        end else begin
            Y = A2;
        end

        // Find the maximum of the B group
        if (B1 > B2 && B1 > Y) begin
            Y = B1;
        end else if (B2 > Y) begin
            Y = B2;
        end

        // Find the maximum of the C group
        if (C1 > C2 && C1 > Y) begin
            Y = C1;
        end else if (C2 > Y) begin
            Y = C2;
        end

        // Find the maximum of the D group
        if (D1 > D2 && D1 > Y) begin
            Y = D1;
        end else if (D2 > Y) begin
            Y = D2;
        end
    end

endmodule

module debounce_counter(
	//Inputs
	signal_in, rst_n, clk,
	//Outputs
	signal_out
	);

	//Inputs
	input wire signal_in, rst_n, clk;

	//Outputs
	output reg [3:0] signal_out;

	localparam target_count = 4'h4;

	localparam state_low = 2'b00;
	localparam state_posedge = 2'b01;
	localparam state_negedge = 2'b10;
	localparam state_high = 2'b11;

	reg [1:0] current_state, next_state;
	reg [3:0] count;
	wire [3:0] next_count;
	reg reset_count;

	always@(posedge clk, negedge rst_n)begin
		if(~rst_n)begin
			current_state <= 2'b00;
			count <= 4'b0000;
			signal_out <= 4'b0000;
		end
		else begin
			current_state <= next_state;
			count <= next_count;
			signal_out <= count;
		end
	end

	assign next_count = (reset_count) ? 4'b0000 : count + 4'b0001;

	always@(current_state, signal_in, count)begin
		next_state = state_low;
		reset_count = 1'b1;

		case(current_state)

			state_low : begin
				if(signal_in)begin
					reset_count = 1'b0;
					next_state = state_posedge;
				end
				else begin
					reset_count = 1'b1;
					next_state = state_low;
				end
			end


			state_posedge : begin
				if(signal_in)begin
					reset_count = 1'b0;
				end
				else begin
					reset_count = 1'b1;
				end

				if(count == target_count && signal_in)begin
					next_state = state_high;
				end
				else if(signal_in)begin
					next_state = state_posedge;
				end
				else begin
					next_state = state_low;
				end
			end


			state_high : begin
				if(~signal_in)begin
					reset_count = 1'b0;
					next_state = state_negedge;
				end
				else begin
					reset_count = 1'b1;
					next_state = state_high;
				end
			end


			state_negedge : begin
				if(~signal_in)begin
					reset_count = 1'b0;
				end
				else begin
					reset_count = 1'b1;
				end

				if(count == 4'h9 && ~signal_in)begin
					next_state = state_low;
				end
				else if(~signal_in)begin
					next_state = state_negedge;
				end
				else begin
					next_state = state_high;
				end
			end


			default : begin
				next_state = state_low;
			end
		endcase
	end

endmodule

module timer_module
(
  input   clk,            // clock
  input   wr,            // write enable
  input   reset,           // reset
  input   tlo,          // timer low byte select
  input   thi,           // timer high byte select
  input   tcr,          // timer control register
  input   [7:0] data_in,      // bus data in
  input   count_en,        // enable or disable the timer count
  input   [15:0] load_val,    // initial value of the timer counter
  output  [7:0] data_out,      // bus data out
  output  tmra_ovf,        // timer A underflow
  output  spmode,          // serial port mode
  output  irq,            // interrupt out
  output  [15:0] count_val    // current count value
);

reg    [15:0] tmr;        // timer
reg    [7:0] tmlh;        // timer latch high byte
reg    [7:0] tmll;        // timer latch low byte
reg    [6:0] tmcr;        // timer control register
reg    forceload;        // force load strobe
wire   oneshot;        // oneshot mode
wire   start;          // timer start (enable)
reg    thi_load;          // load tmr after writing thi in one-shot mode
wire   reload;          // reload timer counter
wire   zero;          // timer counter is zero
wire   underflow;        // timer is going to underflow
wire   count;          // count enable signal

// count enable signal
assign count = count_en;

// writing timer control register
always @(posedge clk)
  if (reset)  // synchronous reset
    tmcr[6:0] <= 7'd0;
  else if (tcr && wr)  // load control register, bit 4(strobe) is always 0
    tmcr[6:0] <= {data_in[6:5],1'b0,data_in[3:0]};
  else if (thi_load && oneshot)  // start timer if thi is written in one-shot mode
    tmcr[0] <= 1'd1;
  else if (underflow && oneshot) // stop timer in one-shot mode
    tmcr[0] <= 1'd0;

always @(posedge clk)
  forceload <= tcr & wr & data_in[4];  // force load strobe

assign oneshot = tmcr[3];    // oneshot alias
assign start = tmcr[0];      // start alias
assign spmode = tmcr[6];    // serial port mode (0-input, 1-output)

// timer A latches for high and low byte
always @(posedge clk)
  if (reset)
    tmll[7:0] <= 8'b1111_1111;
  else if (tlo && wr)
    tmll[7:0] <= data_in[7:0];

always @(posedge clk)
  if (reset)
    tmlh[7:0] <= 8'b1111_1111;
  else if (thi && wr)
    tmlh[7:0] <= data_in[7:0];

// thi is written in one-shot mode so tmr must be reloaded
always @(posedge clk)
  thi_load <= thi & wr & (~start | oneshot);

// timer counter reload signal
assign reload = thi_load | forceload | underflow;

// timer counter
always @(posedge clk)
  if (reset)
    tmr[15:0] <= 16'hFF_FF;
  else if (reload)
    tmr[15:0] <= load_val[15:0];
  else if (start && count)
    tmr[15:0] <= tmr[15:0] - 16'd1;

// timer counter equals zero
assign zero = ~|tmr;

// timer counter is going to underflow
assign underflow = zero & start & count;

// Timer A underflow signal for Timer B
assign tmra_ovf = underflow;

// timer underflow interrupt request
assign irq = underflow;

// data output
assign data_out[7:0] = ({8{~wr&tlo}} & tmr[7:0])
          | ({8{~wr&thi}} & tmr[15:8])
          | ({8{~wr&tcr}} & {1'b0,tmcr[6:0]});

// current count value
assign count_val = tmr;

endmodule

