module RCA_N4_28_tb;

  // Instantiate the module to be tested
  RCA_N4_28 dut (.A(A), .B(B), .Ci(Ci), .S(S), .Co(Co));

  // Declare inputs and outputs
  reg [3:0] A;
  reg [3:0] B;
  reg Ci;
  wire [3:0] S;
  wire Co;

  // Declare variables
  integer i;
  reg [3:0] expected_S;
  reg expected_Co;

  // Generate random inputs and calculate expected output
  initial begin
    $randomseed(time);
    for (i = 0; i < 1000; i = i + 1) begin
      A = $random;
      B = $random;
      Ci = $random % 2;
      expected_S = A + B + Ci;
      expected_Co = (A[3] & B[3]) | (A[3] & Ci) | (B[3] & Ci);
      #1;
      if (S !== expected_S || Co !== expected_Co) begin
        $display("FAIL");
        $finish;
      end
    end
    $display("PASS");
    $finish;
  end

endmodule

module uart_interface (
    input rst,
    input clk,
    input rx,
    output tx,
    input [31:0] baud,
    output rts,
    input cts,
    output dtr,
    input dsr,
    input ri,
    input dcd
);

    parameter BIT_COUNT = 8;
    parameter PARITY = "NONE";
    parameter STOP_BITS = 1;

    reg [BIT_COUNT-1:0] tx_data;
    reg [BIT_COUNT-1:0] rx_data;
    reg [3:0] state;
    reg [3:0] parity;
    reg [3:0] stop_bits;
    reg [31:0] count;
    reg tx_busy;
    reg rx_busy;

    assign rts = tx_busy;
    assign dtr = 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            state <= 4'b0000;
            count <= 0;
            tx_busy <= 0;
            rx_busy <= 0;
        end else begin
            case (state)
                4'b0000: begin // Idle State
                    if (~cts && ~rx) begin
                        state <= 4'b0001;
                        count <= 0;
                        rx_busy <= 1;
                    end else if (tx_busy) begin
                        state <= 4'b0010;
                        count <= 0;
                    end
                end
                4'b0001: begin // Start Bit State
                    if (count == baud) begin
                        state <= 4'b0010;
                        count <= 0;
                    end else begin
                        count <= count + 1;
                    end
                end
                4'b0010: begin // Data Bit State
                    if (count == baud) begin
                        if (PARITY == "EVEN") begin
                            parity <= parity ^ rx;
                        end else if (PARITY == "ODD") begin
                            parity <= ~parity ^ rx;
                        end
                        rx_data <= {rx_data[BIT_COUNT-2:0], rx};
                        if (count == baud * BIT_COUNT) begin
                            state <= 4'b0011;
                            count <= 0;
                        end else begin
                            count <= count + 1;
                        end
                    end else begin
                        count <= count + 1;
                    end
                end
                4'b0011: begin // Parity Bit State
                    if (count == baud) begin
                        if (PARITY == "NONE") begin
                            state <= 4'b0100;
                            count <= 0;
                        end else begin
                            state <= 4'b0101;
                            count <= 0;
                        end
                    end else begin
                        count <= count + 1;
                    end
                end
                4'b0100: begin // Stop Bit State
                    if (count == baud * STOP_BITS) begin
                        rx_busy <= 0;
                        state <= 4'b0000;
                        count <= 0;
                    end else begin
                        count <= count + 1;
                    end
                end
                4'b0101: begin // Odd/Even Parity Bit State
                    if (count == baud) begin
                        if (parity == 1'b0 && PARITY == "EVEN") begin
                            state <= 4'b0100;
                            count <= 0;
                        end else if (parity == 1'b1 && PARITY == "ODD") begin
                            state <= 4'b0100;
                            count <= 0;
                        end else begin
                            state <= 4'b0000;
                            count <= 0;
                            rx_busy <= 0;
                        end
                    end else begin
                        count <= count + 1;
                    end
                end
                4'b0110: begin // Transmit Start Bit State
                    if (count == baud) begin
                        tx <= 1'b0;
                        state <= 4'b0111;
                        count <= 0;
                    end else begin
                        count <= count + 1;
                    end
                end
                4'b0111: begin // Transmit Data Bit State
                    if (count == baud) begin
                        tx <= tx_data[BIT_COUNT-1];
                        tx_data <= {tx_data[BIT_COUNT-2:0], 1'b0};
                        if (count == baud * BIT_COUNT) begin
                            stop_bits <= 4'b0001;
                            state <= 4'b1000;
                            count <= 0;
                        end else begin
                            count <= count + 1;
                        end
                    end else begin
                        count <= count + 1;
                    end
                end
                4'b1000: begin // Transmit Stop Bit State
                    if (count == baud * STOP_BITS) begin
                        tx_busy <= 0;
                        state <= 4'b0000;
                        count <= 0;
                    end else if (count == baud) begin
                        tx <= stop_bits[0];
                        stop_bits <= {stop_bits[2:0], 1'b0};
                        count <= 0;
                    end else begin
                        count <= count + 1;
                    end
                end
            endcase
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            state <= 4'b0000;
            count <= 0;
            tx_busy <= 0;
        end else begin
            case (state)
                4'b0000: begin // Idle State
                    if (tx_busy) begin
                        state <= 4'b0110;
                        count <= 0;
                    end else if (~cts) begin
                        tx_data <= {tx_data[BIT_COUNT-2:0], 1'b1};
                        state <= 4'b0110;
                        tx_busy <= 1;
                        count <= 0;
                    end
                end
                4'b0110: begin // Transmit Start Bit State
                    if (count == baud) begin
                        tx <= 1'b0;
                        state <= 4'b0111;
                        count <= 0;
                    end else begin
                        count <= count + 1;
                    end
                end
                4'b0111: begin // Transmit Data Bit State
                    if (count == baud) begin
                        tx <= tx_data[BIT_COUNT-1];
                        tx_data <= {tx_data[BIT_COUNT-2:0], 1'b0};
                        if (count == baud * BIT_COUNT) begin
                            stop_bits <= 4'b0001;
                            state <= 4'b1000;
                            count <= 0;
                        end else begin
                            count <= count + 1;
                        end
                    end else begin
                        count <= count + 1;
                    end
                end
                4'b1000: begin // Transmit Stop Bit State
                    if (count == baud * STOP_BITS) begin
                        tx_busy <= 0;
                        state <= 4'b0000;
                        count <= 0;
                    end else if (count == baud) begin
                        tx <= stop_bits[0];
                        stop_bits <= {stop_bits[2:0], 1'b0};
                        count <= 0;
                    end else begin
                        count <= count + 1;
                    end
                end
            endcase
        end
    end

endmodule

module clock_wizard (
  input clk_in,
  input resetn,
  output reg clk_out,
  output reg locked
);

  reg [24:0] counter = 0;
  reg locked_tmp = 0;

  always @(posedge clk_in or negedge resetn) begin
    if (~resetn) begin
      counter <= 0;
      clk_out <= 0;
      locked_tmp <= 0;
    end else begin
      if (counter == 0) begin
        clk_out <= ~clk_out;
        counter <= 24'd249999; // divide by 2
      end else begin
        counter <= counter - 1;
      end
      if (counter == 12'd0) begin
        locked_tmp <= 1;
      end else begin
        locked_tmp <= 0;
      end
    end
  end

  always @(posedge clk_in) begin
    locked <= locked_tmp;
  end

endmodule

