module jhash_interface (
  input clk,
  input rst,
  input ce,
  input [63:0] fi,
  input m_last,
  input src_empty,
  input fo_full,
  output reg [31:0] hash_out,
  output reg hash_done,
  output reg m_endn,
  output reg m_src_getn,
  output reg [31:0] stream_data0,
  output reg [31:0] stream_data1,
  output reg [31:0] stream_data2,
  output reg stream_valid,
  input stream_ack,
  input [1:0] stream_left,
  input stream_done
);

  // Internal signals
  reg [31:0] data0, data1, data2;
  reg valid;
  reg done;
  reg [1:0] left;
  reg src_getn;
  reg endn;

  // Instantiate jhash_in and jhash_core modules
  jhash_in jhash_in_inst (
    .m_src_getn(m_src_getn),
    .stream_data0(stream_data0),
    .stream_data1(stream_data1),
    .stream_data2(stream_data2),
    .stream_valid(stream_valid),
    .stream_done(stream_done),
    .stream_left(stream_left),
    .ce(ce),
    .clk(clk),
    .fi(fi),
    .fo_full(fo_full),
    .m_last(m_last),
    .rst(rst),
    .src_empty(src_empty),
    .stream_ack(stream_ack)
  );

  jhash_core jhash_core_inst (
    .stream_ack(stream_ack),
    .hash_out(hash_out),
    .hash_done(hash_done),
    .m_endn(m_endn),
    .clk(clk),
    .rst(rst),
    .ce(ce),
    .stream_data0(data0),
    .stream_data1(data1),
    .stream_data2(data2),
    .stream_valid(valid),
    .stream_done(done),
    .stream_left(left)
  );

  // Assign internal signals
  always @(posedge clk) begin
    if (rst) begin
      data0 <= 0;
      data1 <= 0;
      data2 <= 0;
      valid <= 0;
      done <= 0;
      left <= 0;
      src_getn <= 0;
      endn <= 0;
    end else begin
      if (src_empty) begin
        src_getn <= 1;
      end else if (stream_ack) begin
        src_getn <= 1;
      end else begin
        src_getn <= 0;
      end

      if (stream_valid) begin
        data0 <= stream_data0;
        data1 <= stream_data1;
        data2 <= stream_data2;
        valid <= 1;
        left <= stream_left;
      end else begin
        valid <= 0;
      end

      if (stream_done) begin
        done <= 1;
      end else begin
        done <= 0;
      end

      if (m_last) begin
        endn <= 1;
      end else begin
        endn <= 0;
      end
    end
  end

  // Assign module outputs
  assign m_endn = endn;
  assign m_src_getn = src_getn;
  assign stream_data0 = data0;
  assign stream_data1 = data1;
  assign stream_data2 = data2;
  assign stream_valid = valid;

endmodule

module aalu(
        input           iUAZRO,
        input           iUIMMB,
        input  [7:0]    iIMMBV,
        input  [2:0]    iSAOUT,
        input  [7:0]    iA,
        input  [7:0]    iB,
        output [7:0]    oALOUT,
        output [7:0]    oMULHB
    );

    wire [7:0]     wAOUT[7:0];
    assign oALOUT = wAOUT[iSAOUT];

    wire [7:0]     wA;
    assign wA    = iUAZRO ? 8'h00  : iA;

    wire [7:0]     wB;
    assign wB    = iUIMMB ? iIMMBV : iB;

    assign wAOUT[0] = iIMMBV;
    assign wAOUT[1] = wA & wB;
    assign wAOUT[2] = wA | wB;
    assign wAOUT[3] = wA ^ wB;
    assign wAOUT[4] = ~wA;

    alu_add alu_add (
        .dataa(wA),
        .datab(wB),
        .result(wAOUT[5])
    );

    alu_sub alu_sub (
        .dataa(wA),
        .datab(wB),
        .result(wAOUT[6])
    );

    wire [15:0]       wMUL;
    assign wAOUT[7] = wMUL[7:0];
    assign oMULHB   = wMUL[15:8];
    alu_mul alu_mul (
        .dataa(wA),
        .datab(wB),
        .result(wMUL)
    );
endmodule

