module traffic_light(clk, reset, ped_cross, green, yellow, red, ped_red, ped_green);
  input clk, reset, ped_cross;
  output reg green, yellow, red, ped_red, ped_green;

  parameter GREEN_TIME = 500_000_000; // 10 seconds
  parameter YELLOW_TIME = 100_000_000; // 2 seconds
  parameter RED_TIME = 500_000_000; // 10 seconds

  reg [2:0] state = 3'b001; // initial state

  reg [29:0] green_count = 0; // counter for green light
  reg [29:0] yellow_count = 0; // counter for yellow light
  reg [29:0] red_count = 0; // counter for red light
  reg [29:0] ped_red_count = 0; // counter for pedestrian red light
  reg [29:0] ped_green_count = 0; // counter for pedestrian green light

  always @(posedge clk)
  begin
    if (reset)
      begin
        state <= 3'b001;
        green_count <= 0;
        yellow_count <= 0;
        red_count <= 0;
        ped_red_count <= 0;
        ped_green_count <= 0;
        green <= 1'b1;
        yellow <= 1'b0;
        red <= 1'b0;
        ped_red <= 1'b0;
        ped_green <= 1'b0;
      end
    else
      begin
        case (state)
          3'b001: // green light
            begin
              green_count <= green_count + 1;
              if (green_count == GREEN_TIME)
                begin
                  state <= 3'b010;
                  yellow_count <= 0;
                  green_count <= 0;
                  green <= 1'b0;
                  yellow <= 1'b1;
                end
            end
          3'b010: // yellow light
            begin
              yellow_count <= yellow_count + 1;
              if (yellow_count == YELLOW_TIME)
                begin
                  state <= 3'b011;
                  red_count <= 0;
                  yellow_count <= 0;
                  yellow <= 1'b0;
                  red <= 1'b1;
                end
            end
          3'b011: // red light
            begin
              red_count <= red_count + 1;
              if (ped_cross)
                begin
                  state <= 3'b101;
                  ped_red_count <= 0;
                  red_count <= 0;
                  red <= 1'b0;
                  ped_red <= 1'b1;
                end
              else if (red_count == RED_TIME)
                begin
                  state <= 3'b001;
                  green_count <= 0;
                  red_count <= 0;
                  red <= 1'b0;
                  green <= 1'b1;
                end
            end
          3'b101: // pedestrian red light
            begin
              ped_red_count <= ped_red_count + 1;
              if (ped_red_count == RED_TIME)
                begin
                  state <= 3'b110;
                  ped_red_count <= 0;
                  ped_green_count <= 0;
                  ped_red <= 1'b0;
                  ped_green <= 1'b1;
                end
            end
          3'b110: // pedestrian green light
            begin
              ped_green_count <= ped_green_count + 1;
              if (ped_green_count == GREEN_TIME)
                begin
                  state <= 3'b111;
                  ped_green_count <= 0;
                  ped_green <= 1'b0;
                  ped_red <= 1'b1;
                end
            end
          3'b111: // pedestrian red light
            begin
              ped_red_count <= ped_red_count + 1;
              if (ped_red_count == RED_TIME)
                begin
                  state <= 3'b001;
                  green_count <= 0;
                  ped_red_count <= 0;
                  ped_red <= 1'b0;
                  green <= 1'b1;
                end
            end
        endcase
      end
  end
endmodule

module lfsr_pattern_detector (
    input clk,
    input reset,
    input [63:0] in,
    output [63:0] out
);

parameter LFSR_WIDTH = 64;
parameter DETECT_WIDTH = 8;

reg [LFSR_WIDTH-1:0] lfsr_reg;
reg [DETECT_WIDTH-1:0] detect_reg;
reg [63:0] out_reg;

always @(posedge clk) begin
    if (reset) begin
        lfsr_reg <= 'h1;
        detect_reg <= 'h0;
        out_reg <= 'h0;
    end else begin
        // LFSR feedback
        lfsr_reg[LFSR_WIDTH-1:1] <= lfsr_reg[LFSR_WIDTH-2:0];
        lfsr_reg[0] <= lfsr_reg[LFSR_WIDTH-1] ^ lfsr_reg[LFSR_WIDTH-2] ^ lfsr_reg[LFSR_WIDTH-3] ^ lfsr_reg[LFSR_WIDTH-4];

        // Pattern detection
        detect_reg[DETECT_WIDTH-1:1] <= detect_reg[DETECT_WIDTH-2:0];
        detect_reg[0] <= in[7:0] == detect_reg;
        if (detect_reg == 'hFF) begin
            out_reg <= lfsr_reg;
        end else begin
            out_reg <= 'h0;
        end
    end
end

assign out = out_reg;

endmodule

module fifo
   #(
  	parameter adr_width = 4,
	parameter dat_width = 8
   )
   (
    input  clk, reset,
    input  rd, wr,
    input  [dat_width-1:0] data_in,
    output [dat_width-1:0] data_out,
    output empty, 
    output full
   );

   parameter depth = (1 << adr_width);

   //declaración de registros 

   reg [dat_width-1:0] array_reg [depth-1:0];// register array FIFO

   reg [adr_width-1:0] w_ptr_reg, w_ptr_next;
   reg [adr_width-1:0] r_ptr_reg, r_ptr_next;
   reg full_reg, empty_reg, full_next, empty_next;
   wire wr_en;


   assign data_out = array_reg[r_ptr_reg];
   assign wr_en = wr & ~full_reg;

   assign full = full_reg;
   assign empty = empty_reg;

   always @(posedge clk) begin
      if (wr_en)
         array_reg[w_ptr_reg] <= data_in;
   end

   // fifo control logic
   // register for read and write pointers
   always @(posedge clk, posedge reset) begin
      if (reset)
         begin
            w_ptr_reg <= 0;
            r_ptr_reg <= 0;
            full_reg <= 1'b0;
            empty_reg <= 1'b1;
         end
      else
         begin
            w_ptr_reg <= w_ptr_next;
            r_ptr_reg <= r_ptr_next;
            full_reg <= full_next;
            empty_reg <= empty_next;
         end
   end



   always @(posedge reset, posedge wr, posedge rd)
   begin
      if (reset) begin
	w_ptr_next =  0;
        r_ptr_next =  0;       
      end else begin
	      full_next = full_reg;
	      empty_next = empty_reg;
	      case ({wr, rd})
		 2'b01: // read
		    if (~empty_reg) // not empty
		       begin
		          r_ptr_next = r_ptr_reg + 1;
		          full_next = 1'b0;
		          if (r_ptr_next==w_ptr_reg)
		             empty_next = 1'b1;
		       end
		 2'b10: // write
		    if (~full_reg) // not full
		       begin
		          w_ptr_next = w_ptr_reg + 1;
		          empty_next = 1'b0;
		          if (w_ptr_next==r_ptr_reg)
		             full_next = 1'b1;
		       end
		 2'b11: // write and read
		    begin
		       w_ptr_next =  w_ptr_reg + 1;
		       r_ptr_next = r_ptr_reg + 1;
		    end
	      endcase
	end
   end

endmodule

module top_module (
    input CLK, SHIFT_LEFT, SHIFT_RIGHT,
    input [3:0] DAC_INPUT,
    output reg [3:0] FINAL_OUTPUT
);

reg [3:0] shift_reg;
reg [3:0] dac_output;

// DAC module
always @ (DAC_INPUT) begin
    dac_output = (DAC_INPUT/15.0)*5.0;
end

// Barrel shifter module
always @ (posedge CLK) begin
    if (SHIFT_LEFT) begin
        shift_reg <= {shift_reg[2:0], 1'b0};
    end else if (SHIFT_RIGHT) begin
        shift_reg <= {1'b0, shift_reg[3:1]};
    end
end

// Functional module
always @ (dac_output, shift_reg) begin
    FINAL_OUTPUT = dac_output + shift_reg;
end

endmodule

module cpu_ctl(op, func, equal_result, JR, J, JAL, LW, WREG, WMEM, RDorRT, SE, SA, IR, IorR, BJ, Aluc);

input wire [5:0] op, func;
input wire equal_result;
output wire JR, J, JAL, LW, WREG, WMEM, RDorRT, SE, SA, IR, IorR, BJ;
output wire [4:0] Aluc;

wire r_type, i_jr, i_sll, i_srl, i_sra;
wire i_addi, i_andi, i_ori, i_xori, i_slti, i_lw, i_sw;
wire i_j, i_jal, i_beq, i_bne;
wire i_type, b_type;

/* R-type */
and(r_type, ~op[5], ~op[4], ~op[3], ~op[2], ~op[1], ~op[0]);
and(i_jr, r_type, ~func[5], ~func[4], func[3], ~func[2], ~func[1], ~func[0]); //func:001000
and(i_sll, r_type, ~func[5], ~func[4], ~func[3], ~func[2], ~func[1], ~func[0]); //func:000000
and(i_srl, r_type, ~func[5], ~func[4], ~func[3], ~func[2], func[1], ~func[0]); //func:000010
and(i_sra, r_type, ~func[5], ~func[4], ~func[3], ~func[2], func[1], func[0]); //func:000011

/* I-type */
or(i_type, i_addi, i_andi, i_ori, i_xori, i_slti, b_type, i_lw, i_sw);
and(i_addi, ~op[5], ~op[4], op[3], ~op[2], ~op[1], ~op[0]);
and(i_andi, ~op[5], ~op[4], op[3], op[2], ~op[1], ~op[0]);
and(i_ori, ~op[5], ~op[4], op[3], op[2], ~op[1], op[0]);
and(i_xori, ~op[5], ~op[4], op[3], op[2], op[1], ~op[0]);
and(i_slti, ~op[5], ~op[4], op[3], ~op[2], op[1], ~op[0]);
and(i_lw, op[5], ~op[4], ~op[3], ~op[2], op[1], op[0]);
and(i_sw, op[5], ~op[4], op[3], ~op[2], op[1], op[0]);

/* I-type(B) */
or(b_type, i_beq, i_bne);
and(i_beq, ~op[5], ~op[4], ~op[3], op[2], ~op[1], ~op[0]); //000100
and(i_bne, ~op[5], ~op[4], ~op[3], op[2], ~op[1], op[0]); //000101

/* J-type */
and(i_j, ~op[5], ~op[4], ~op[3], ~op[2], op[1], ~op[0]);
and(i_jal, ~op[5], ~op[4], ~op[3], ~op[2], op[1], op[0]);

/* Control Signals */
assign JR = i_jr;
assign J = i_j;
assign JAL = i_jal;
assign LW = i_lw;
assign WREG = i_jal | IorR | LW;
assign WMEM = i_sw;
assign RDorRT = r_type & ~i_jr;
assign SE = i_addi | i_lw | i_sw;
assign SA = i_sll | i_srl | i_sra;
assign IR = (r_type | i_type) & ~i_jr & ~b_type & ~i_lw & ~i_sw;
assign IorR = i_type & ~b_type;
assign BJ = (i_beq & equal_result) | (i_bne & ~equal_result);

/* ALU Control */
alt_ctl AC(.op(op), .func(func), .aluc(Aluc));

endmodule

module alt_ctl(op, func, aluc);

input wire [5:0] op, func;
output wire [4:0] aluc;

wire r_type, i_type, b_type;

/* R-type */
and(r_type, ~op[5], ~op[4], ~op[3], ~op[2], ~op[1], ~op[0]);
assign aluc[4:0] = r_type ? func[2:0] : i_type ? 2'b00 : b_type ? 2'b01 : 2'b10;

endmodule

