    output [7:0] data_out // 8-bit output from the active shift register
);

wire [7:0] shift_reg1_data_out;
wire [7:0] shift_reg2_data_out;

shift_register shift_reg1 (
    .clk(clk),
    .reset(reset),
    .load(load),
    .data_in(data_in),
    .data_out(shift_reg1_data_out)
);

shift_register shift_reg2 (
    .clk(clk),
    .reset(reset),
    .load(load),
    .data_in(data_in),
    .data_out(shift_reg2_data_out)
);

assign data_out = select ? shift_reg2_data_out : shift_reg1_data_out;

endmodule

