module pll (
  input clk_in,
  output reg clk_out,
  input resetn,
  output reg locked
);

  parameter CLK_MIN = 10_000_000;
  parameter CLK_MAX = 100_000_000;
  parameter LOCK_TIMEOUT = 100_000; // 100 us at 1 MHz clock

  // Integer multipler
  parameter MULT_MIN = 1;
  parameter MULT_MAX = 64;
  reg [5:0] mult = MULT_MIN;

  // Integer dividers
  parameter DIV1_MIN = 1;
  parameter DIV1_MAX = 64;
  reg [5:0] div1 = DIV1_MIN;

  parameter DIV2_MIN = 1;
  parameter DIV2_MAX = 64;
  reg [5:0] div2 = DIV2_MIN;

  // Internal signals
  reg [5:0] count1 = 0;
  reg [5:0] count2 = 0;
  reg locked_int = 0;
  reg [31:0] lock_time = 0;

  always @(posedge clk_in or negedge resetn) begin
    if (!resetn) begin
      count1 <= 0;
      count2 <= 0;
      locked_int <= 0;
      lock_time <= 0;
    end else begin
      count1 <= count1 + 1;
      if (count1 == mult) begin
        count1 <= 0;
        count2 <= count2 + 1;
        if (count2 == div1) begin
          count2 <= 0;
          clk_out <= ~clk_out;
          if (locked_int == 0) begin
            lock_time <= lock_time + 1;
            if (lock_time >= LOCK_TIMEOUT) begin
              locked_int <= 1;
            end
          end
        end
      end
    end
  end

  always @(posedge clk_in or negedge resetn) begin
    if (!resetn) begin
      locked <= 0;
    end else begin
      if (locked_int == 0 && clk_out == 1'b0) begin
        locked <= 1;
      end else begin
        locked <= 0;
      end
    end
  end

  // Parameter control
  always @(posedge clk_in or negedge resetn) begin
    if (!resetn) begin
      mult <= MULT_MIN;
      div1 <= DIV1_MIN;
      div2 <= DIV2_MIN;
    end else begin
      if (locked_int == 0 && clk_out == 1'b0) begin
        lock_time <= lock_time + 1;
        if (lock_time >= LOCK_TIMEOUT) begin
          locked_int <= 1;
        end
      end else begin
        if (mult < MULT_MAX) begin
          mult <= mult + 1;
          div1 <= DIV1_MIN;
          div2 <= DIV2_MIN;
        end else if (div1 < DIV1_MAX) begin
          mult <= MULT_MIN;
          div1 <= div1 + 1;
          div2 <= DIV2_MIN;
        end else if (div2 < DIV2_MAX) begin
          mult <= MULT_MIN;
          div1 <= DIV1_MIN;
          div2 <= div2 + 1;
        end else begin
          mult <= MULT_MIN;
          div1 <= DIV1_MIN;
          div2 <= DIV2_MIN;
        end
        lock_time <= 0;
        locked_int <= 0;
      end
    end
  end

endmodule

module decade_counter (
    input clk,
    input slowena,
    input reset,
    output [3:0] q);

    reg [3:0] johnson;
    reg [3:0] counter;
    wire [1:0] sel;
    assign sel = slowena ? 2'b10 : 2'b01;

    always @(posedge clk) begin
        if (reset) begin
            johnson <= 4'b0001;
            counter <= 4'b0000;
        end else begin
            johnson <= {johnson[2:0], johnson[3]};
            counter <= sel == 2'b10 ? counter : johnson[3:0];
        end
    end

    assign q = counter;

endmodule

