module ripple_carry_adder(A, B, CIN, SUM, COUT);
input [3:0] A, B;
input CIN;
output [3:0] SUM;
output COUT;

wire [3:0] CARRY;
wire [3:0] XOR1;
wire [3:0] XOR2;

FA FA0(A[0], B[0], CIN, SUM[0], CARRY[0]);
FA FA1(A[1], B[1], CARRY[0], SUM[1], CARRY[1]);
FA FA2(A[2], B[2], CARRY[1], SUM[2], CARRY[2]);
FA FA3(A[3], B[3], CARRY[2], SUM[3], COUT);

assign XOR1 = A ^ B;
assign XOR2 = XOR1 ^ CIN;
assign CARRY = A & B;
assign CARRY = CARRY | (XOR1 & CIN);
assign CARRY = CARRY | (XOR2 & (A | B));

endmodule

module FA(A, B, CIN, SUM, COUT);
input A, B, CIN;
output SUM, COUT;

assign SUM = A ^ B ^ CIN;
assign COUT = (A & B) | (A & CIN) | (B & CIN);

endmodule

module booth_multiplier (
    input [3:0] A,
    input [3:0] B,
    output [7:0] product
);

reg [7:0] result;
reg [4:0] multiplier;
reg [4:0] multiplicand;
reg [3:0] count;

assign product = result;

always @(*) begin
    multiplier = {1'b0, A};
    multiplicand = {1'b0, B};
    result = 8'b0;
    count = 4;

    while (count > 0) begin
        if (multiplier[0] == 1 && multiplier[1] == 0) begin
            result = result - multiplicand;
        end
        else if (multiplier[0] == 0 && multiplier[1] == 1) begin
            result = result + multiplicand;
        end

        // Shift right by 1 bit
        multiplier = {multiplier[4], multiplier[3:1]};
        count = count - 1;
    end
end

endmodule

