module prbs_gen #
  (
    parameter PRBS_WIDTH  = 4
   )
  (
   input           clk,
   input           clk_en,
   input           rst,
   output  [PRBS_WIDTH-1:0]  prbs_o
//   output reg [3:0] prbs_shift_value
  );

localparam  PRBS_OFFSET = 0;  

reg [PRBS_WIDTH - 1:0] Next_LFSR_Reg;
reg [PRBS_WIDTH - 1:0] LFSR_Reg;
reg [PRBS_WIDTH - 1:0] prbs_shift_value;
reg Bits_all, Feedback;
integer i;

always @ (posedge clk)
begin
   if (rst )
        LFSR_Reg <=  {{PRBS_WIDTH-1{1'b0}},1'b1};
   else if (clk_en) begin
        if ( PRBS_OFFSET == 0)
         // $display("prbs_value = 0x%h",LFSR_Reg);
        LFSR_Reg <= Next_LFSR_Reg;
        prbs_shift_value <= {prbs_shift_value[PRBS_WIDTH-2:0],LFSR_Reg[PRBS_WIDTH-1]};
        end
end

always @ (LFSR_Reg)
begin :LFSR_Next
   Bits_all = ~| LFSR_Reg[PRBS_WIDTH-2:0];
   Feedback = LFSR_Reg[PRBS_WIDTH-1]^Bits_all; 
   for (i = PRBS_WIDTH - 1; i >= 1 ; i = i-1)
      Next_LFSR_Reg[i] = LFSR_Reg[i-1];

   // Many to one feedback taps for 2^n sequence
   // 4 logic levels required for PRBS_WIDTH = 64
   case (PRBS_WIDTH)
   32'd4:      
      Next_LFSR_Reg[0] = Feedback^LFSR_Reg[2];
   32'd8:      
      Next_LFSR_Reg[0] = Feedback^LFSR_Reg[3]^LFSR_Reg[4]^LFSR_Reg[5];
   32'd10:      
      Next_LFSR_Reg[0] = Feedback^LFSR_Reg[6];
   32'd14:
      Next_LFSR_Reg[0] = Feedback^LFSR_Reg[0]^LFSR_Reg[2]^LFSR_Reg[4];
   32'd24:
      Next_LFSR_Reg[0] = Feedback^LFSR_Reg[16]^LFSR_Reg[21]^LFSR_Reg[22];
   32'd32:
      Next_LFSR_Reg[0] = Feedback^LFSR_Reg[0]^LFSR_Reg[1]^LFSR_Reg[21];
   32'd42:
      Next_LFSR_Reg[0] = Feedback^LFSR_Reg[18]^LFSR_Reg[19]^LFSR_Reg[40];
   32'd56:
      Next_LFSR_Reg[0] = Feedback^LFSR_Reg[33]^LFSR_Reg[34]^LFSR_Reg[54];
   32'd64:
      Next_LFSR_Reg[0] = Feedback^LFSR_Reg[59]^LFSR_Reg[60]^LFSR_Reg[62];
   32'd72:
      Next_LFSR_Reg[0] = Feedback^LFSR_Reg[18]^LFSR_Reg[24]^LFSR_Reg[65];
   default:
      Next_LFSR_Reg[0] = Feedback^LFSR_Reg[59]^LFSR_Reg[60]^LFSR_Reg[62];
   endcase
end

assign prbs_o = LFSR_Reg;

endmodule

module negative_register (
    input clk,
    input en,
    input arst,
    input srst,
    input ld,
    input [width-1:0] d,
    output lz,
    output [width-1:0] z
);

    parameter integer rscid = 1;
    parameter integer width = 8;
    parameter ph_en = 1'b1;
    parameter ph_arst = 1'b1;
    parameter ph_srst = 1'b1;

    reg lz;
    reg [width-1:0] z;

    always @ (posedge clk) begin
        if (arst == 1'b0) begin
            lz <= 1'b0;
            z <= {width{1'b0}};
        end else if (srst == ph_srst) begin
            lz <= 1'b0;
            z <= {width{1'b0}};
        end else if (en == ph_en) begin
            if (ld == 1'b1) begin
                lz <= 1'b0;
                z <= ~d;
            end else begin
                lz <= (z == {width{1'b0}});
                z <= z - d;
            end
        end
    end

endmodule

module hilbert_transform (
  input signed [n-1:0] in,
  output signed [n-1:0] out_real,
  output signed [n-1:0] out_imag
);

parameter n = 8; // number of bits in the input signal

reg signed [n-1:0] delay_line [1:2];
reg signed [n-1:0] delay_line_imag [1:2];
reg signed [n-1:0] out_real_reg;
reg signed [n-1:0] out_imag_reg;

always @(in) begin
  delay_line[1] <= in;
  delay_line[2] <= delay_line[1];
  delay_line_imag[1] <= 0;
  delay_line_imag[2] <= delay_line_imag[1];

  out_real_reg <= (delay_line[1] - delay_line_imag[2]) / 2;
  out_imag_reg <= (delay_line_imag[1] + delay_line[2]) / 2;
end

assign out_real = out_real_reg;
assign out_imag = out_imag_reg;

endmodule

module fifo_buffer
    (AS,
     out,
     wr_clk,
     in0);

    output [0:0] AS;
    output out;
    input wr_clk;
    input [0:0] in0;

    wire [1:0] buffer;
    wire [1:0] next_buffer;
    wire full;

    assign AS = full;
    assign out = buffer[0];

    always @ (posedge wr_clk) begin
        if (!full) begin
            next_buffer[1] <= buffer[0];
            next_buffer[0] <= in0;
        end else begin
            next_buffer <= buffer;
        end
    end

    always @ (buffer, full) begin
        full = (buffer[1] != 1'b0);
    end

    always @ (posedge wr_clk) begin
        buffer <= next_buffer;
    end

endmodule

module pipelined_edge_detect(
  input               clk,
  input               rst_n,
  input               a,
  output reg          rise,
  output reg          down
);

  reg [1:0]           state;
  reg                 a_reg;
  reg                 a_reg_reg;

  parameter           IDLE = 2'b00;
  parameter           RISING_EDGE = 2'b01;
  parameter           FALLING_EDGE = 2'b10;

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      state <= IDLE;
      a_reg <= 1'b0;
      a_reg_reg <= 1'b0;
      rise <= 1'b0;
      down <= 1'b0;
    end
    else begin
      a_reg <= a;
      a_reg_reg <= a_reg;
      case (state)
        IDLE: begin
          if (a_reg && ~a_reg_reg) begin
            rise <= 1'b1;
            down <= 1'b0;
            state <= RISING_EDGE;
          end
          else if (~a_reg && a_reg_reg) begin
            rise <= 1'b0;
            down <= 1'b1;
            state <= FALLING_EDGE;
          end
          else begin
            rise <= 1'b0;
            down <= 1'b0;
            state <= IDLE;
          end
        end
        RISING_EDGE: begin
          rise <= 1'b0;
          down <= 1'b0;
          state <= IDLE;
        end
        FALLING_EDGE: begin
          rise <= 1'b0;
          down <= 1'b0;
          state <= IDLE;
        end
      endcase
    end
  end

endmodule

module mux_priority_encoder (
  input clk,
  input reset,
  input [3:0] data,
  output reg [1:0] out_code
);

  // Edge detection module
  reg [3:0] prev_data;
  reg [3:0] edge_detect;

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      prev_data <= 4'b0000;
      edge_detect <= 4'b0000;
    end else begin
      prev_data <= data;
      edge_detect <= (data ^ prev_data) & data;
    end
  end

  // 4-to-1 mux module
  reg [1:0] select;
  wire [3:0] mux_out;

  mux_2to1 u1 (
    .a(data[0]),
    .b(data[1]),
    .sel(select[0]),
    .out(mux_out[0])
  );

  mux_2to1 u2 (
    .a(data[2]),
    .b(data[3]),
    .sel(select[0]),
    .out(mux_out[1])
  );

  mux_2to1 u3 (
    .a(mux_out[0]),
    .b(mux_out[1]),
    .sel(select[1]),
    .out(mux_out[2])
  );

  // Priority encoder
  always @(*) begin
    case (mux_out)
      4'b0001: out_code = 2'b00;
      4'b0010: out_code = 2'b01;
      4'b0100: out_code = 2'b10;
      4'b1000: out_code = 2'b11;
      default: out_code = 2'b00;
    endcase
  end

  // Synchronous reset
  always @(posedge clk, posedge reset) begin
    if (reset) begin
      select <= 2'b00;
    end else begin
      select <= {edge_detect[3], edge_detect[2]};
    end
  end

endmodule

module axi_data_mover (
  input clk,
  input resetn,

  input [2:0] request_id,
  output [2:0] response_id,
  input sync_id,
  input eot,

  input enable,
  output reg enabled,

  output xfer_req,

  output s_axi_ready,
  input s_axi_valid,
  input [63:0] s_axi_data,

  input m_axi_ready,
  output m_axi_valid,
  output [63:0] m_axi_data,
  output m_axi_last,

  input req_valid,
  output req_ready,
  input [3:0] req_last_burst_length
);

parameter MAX_BEATS_PER_BURST = 16;

reg [3:0] last_burst_length = 0;
reg [3:0] beat_counter = 0;
reg [2:0] id = 0;
reg [2:0] id_next = 0;

reg pending_burst = 0;
reg active = 0;
reg last_eot = 0;
reg last_non_eot = 0;

wire last_load;
wire last;

assign xfer_req = active;

assign response_id = id;

assign last = eot ? last_eot : last_non_eot;

assign s_axi_ready = m_axi_ready & pending_burst & active;
assign m_axi_valid = s_axi_valid & pending_burst & active;
assign m_axi_data = s_axi_data;
assign m_axi_last = last;

assign req_ready = ~active;

always @(posedge clk) begin
  if (resetn == 1'b0) begin
    enabled <= 1'b0;
  end else begin
    if (enable) begin
      enabled <= 1'b1;
    end else begin
      enabled <= 1'b0;
    end
  end
end

always @(posedge clk) begin
  if (req_valid && ~active) begin
    id_next <= id + 1;
    beat_counter <= 1;
    last_burst_length <= req_last_burst_length;
    pending_burst <= 1;
    active <= 1;
  end else if (s_axi_ready && s_axi_valid && active) begin
    beat_counter <= beat_counter + 1;
    if (beat_counter == last_burst_length) begin
      last_eot <= 1;
      last_non_eot <= 0;
    end else if (beat_counter == MAX_BEATS_PER_BURST - 1) begin
      last_eot <= 0;
      last_non_eot <= 1;
    end else begin
      last_eot <= 0;
      last_non_eot <= 0;
    end
  end else if (last_load) begin
    active <= 0;
    pending_burst <= 0;
  end
end

always @(posedge clk) begin
  if (resetn == 1'b0) begin
    id <= 0;
  end else begin
    id <= id_next;
  end
end

endmodule

module control(
    input clk,
    input rst,
    input en,
    input en_mem,
    input mem_wait,
    input should_branch,
    input imm,
    output reg [8:0] control_o,
    output reg [1:0] pc_op
);

    always @(posedge clk) begin
        if (rst) begin
            control_o <= 0;
            pc_op <= 0;
        end else if (en) begin
            // Control signal generation
            control_o[0] <= en_mem;
            control_o[1] <= should_branch;
            control_o[2] <= imm;

            // Opcode signal generation
            if (imm) begin
                pc_op <= 2'b10; // Bitwise AND
            end else begin
                pc_op <= 2'b00; // Add
            end
        end
    end
endmodule

module up_down_counter (
    input clk,
    input rst,
    input up_down,
    output reg [2:0] count
);

    always @(posedge clk) begin
        if (rst) begin
            count <= 3'b000;
        end else if (up_down) begin
            count <= count + 1;
        end else begin
            count <= count - 1;
        end
    end

endmodule

module binary_calculator (
    input clk,
    input reset,        // Synchronous active-high reset
    input [7:0] a,      // First 8-bit input
    input [7:0] b,      // Second 8-bit input
    input add_sub_sel,  // Select input for addition or subtraction
    output [7:0] q      // 8-bit output from the functional module
);

    wire [7:0] add_out;
    wire [7:0] sub_out;
    wire [7:0] or_out;

    // Instantiate the adder module
    binary_adder adder_inst (
        .a(a),
        .b(b),
        .cin(1'b0),
        .sum(add_out),
        .cout()
    );

    // Instantiate the subtractor module
    binary_subtractor sub_inst (
        .a(a),
        .b(b),
        .cin(1'b1),
        .diff(sub_out),
        .bout()
    );

    // Perform the OR operation on the outputs of the adder and subtractor modules
    assign or_out = add_out | sub_out;

    // Select the output based on the add_sub_sel input
    always @ (posedge clk) begin
        if (reset) begin
            q <= 8'b0;
        end else begin
            if (add_sub_sel) begin
                q <= add_out;
            end else begin
                q <= sub_out;
            end
        end
    end

endmodule

module bias_generator (
    din,
    mainclk,
    updateclk,
    capture,
    update,
    dout 
    );

// INPUT PORTS
input  din;
input  mainclk;
input  updateclk;
input  capture;
input  update;

// OUTPUTPUT PORTS
output dout;

parameter TOTAL_REG = 202;

// INTERNAL VARIABLES
reg dout_tmp;
reg generator_reg [TOTAL_REG - 1:0];
reg update_reg [TOTAL_REG - 1:0];
integer i;

initial
begin
    dout_tmp <= 'b0;
    for (i = 0; i < TOTAL_REG; i = i + 1)
    begin
        generator_reg [i] <= 'b0;
        update_reg [i] <= 'b0;
    end
end

// main generator registers
always @(posedge mainclk)
begin
    if ((capture == 'b0) && (update == 'b1)) //update main registers
    begin
        for (i = 0; i < TOTAL_REG; i = i + 1)
        begin
            generator_reg[i] <= update_reg[i];
        end
    end
end

// update registers
always @(posedge updateclk)
begin
    dout_tmp <= update_reg[TOTAL_REG - 1];

    if ((capture == 'b0) && (update == 'b0)) //shift update registers
    begin
        for (i = (TOTAL_REG - 1); i > 0; i = i - 1)
        begin
            update_reg[i] <= update_reg[i - 1];
        end
        update_reg[0] <= din; 
    end
    else if ((capture == 'b1) && (update == 'b0)) //load update registers
    begin
        for (i = 0; i < TOTAL_REG; i = i + 1)
        begin
            update_reg[i] <= generator_reg[i];
        end
    end

end

assign dout = dout_tmp;

endmodule

