module pulse_crossing (
    input        mrst,
    input        mclk,
    input        hclk,
    input        fifo_rd,
    input [4:0]  raddr_r,
    input [3:0]  fifo_do_vld_r,
    input        flushing_mclk,
    input        dout_re,
    output [31:0] dout,
    output       dout_vld,
    output       last_DW
);

    // Synchronize input signals to source clock domain
    reg [4:0] raddr_s;
    reg [3:0] fifo_do_vld_s;
    reg        flushing_s;
    reg        dout_re_s;
    always @(posedge mclk) begin
        if (mrst) begin
            raddr_s       <= 5'b0;
            fifo_do_vld_s <= 4'b0;
            flushing_s    <= 1'b0;
            dout_re_s     <= 1'b0;
        end else begin
            raddr_s       <= raddr_r;
            fifo_do_vld_s <= fifo_do_vld_r;
            flushing_s    <= flushing_mclk;
            dout_re_s     <= dout_re;
        end
    end

    // Pulse-crossing technique
    reg [31:0] dout_s;
    reg        dout_vld_s;
    reg        last_DW_s;
    pulse_cross_clock #(
        .EXTRA_DLY(0)
    ) pulse_cross_i (
        .rst       (mrst),
        .src_clk   (mclk),
        .dst_clk   (hclk),
        .in_pulse  (fifo_do_vld_s[0]),
        .out_pulse (fifo_dav2_w),
        .busy      ()
    );
    reg [3:0] fifo_dav2_s;
    always @(posedge hclk) begin
        fifo_dav2_s <= {fifo_dav2_s[2:0], fifo_dav2_w};
    end
    assign fifo_dav = fifo_dav2_s[0];
    assign fifo_dav2 = fifo_dav2_s[1];

    // Synchronize output signals to destination clock domain
    reg [31:0] dout_d;
    reg        dout_vld_d;
    reg        last_DW_d;
    always @(posedge hclk) begin
        dout_d    <= dout_s;
        dout_vld_d <= dout_vld_s;
        last_DW_d <= last_DW_s;
    end

    // Output transferred data and valid signal
    assign dout    = dout_d;
    assign dout_vld = dout_vld_d;
    assign last_DW = last_DW_d;

    // Output signal indicating that transferred data is last word in burst
    always @(posedge hclk) begin
        if (fifo_dav2_s[3] && !fifo_dav2_s[2]) begin
            last_DW_s <= 1'b1;
        end else if (dout_re_s) begin
            last_DW_s <= 1'b0;
        end
    end

    // Debug signal
    reg [31:0] debug_dma_h2d;
    always @(posedge hclk) begin
        debug_dma_h2d = {14'b0, fifo_rd, raddr_r[4:0], fifo_do_vld_r[3:0], fifo_dav, fifo_dav2_w, fifo_dav2, flushing_mclk, done_flush_mclk, dout_vld, dout_re, last_DW};
    end

    // Flush input FIFO
    pulse_cross_clock #(
        .EXTRA_DLY(0)
    ) done_flush_i (
        .rst       (mrst),
        .src_clk   (mclk),
        .dst_clk   (hclk),
        .in_pulse  (done_flush_mclk),
        .out_pulse (done_flush),
        .busy      ()
    );
    reg done_flush_mclk_s;
    always @(posedge mclk) begin
        done_flush_mclk_s <= done_flush;
    end

    // Input FIFO
    fifo #(
        .DATA_WIDTH(32),
        .ADDR_WIDTH(5),
        .FIFO_DEPTH(32)
    ) fifo_i (
        .clk       (mclk),
        .rst       (mrst),
        .wr_en     (1'b0),
        .wr_data   (32'b0),
        .rd_en     (fifo_rd),
        .rd_addr   (raddr_s),
        .rd_data   (dout_s),
        .rd_data_v (dout_vld_s),
        .empty     (),
        .full      (),
        .dout     (),
        .dout_vld (),
        .dout_re  (),
        .last_DW  ()
    );

endmodule

module shift_register(
    input clk,
    input areset,  // async active-high reset to zero
    input load,
    input ena,
    input [3:0] data,
    output reg [3:0] q);

    reg [3:0] reg_data;

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            reg_data <= 4'b0;
        end else if (load && ena) begin
            reg_data <= data;
        end else if (ena) begin
            reg_data <= {reg_data[2:0], reg_data[3]};
        end
    end

    assign q = reg_data;

endmodule

module bitwise_operations(
    input [0:7] in,
    output B1,
    B2,
    B3,
    B4,
    B5,
    B6,
    B7,
    B8,
    B9,
    B10
);

  assign B1  = in[0] & in[1];
  assign B2  = in[0] | in[1];
  assign B3  = ~(in[0] & in[1]);
  assign B4  = ~(in[0] | in[1]);
  assign B5  = in[0] ^ in[1];
  assign B6  = ~(in[0] ^ in[1]);
  assign B7  = ~in[0];
  assign B8  = in[0];
  assign B9  = (in[0] & in[1]) && (in[2] & in[3]);
  assign B10 = (in[0] & in[1]) || (in[2] & in[3]);

endmodule

module lo_passthru(
    pck0, ck_1356meg, ck_1356megb,
    pwr_lo, pwr_hi, pwr_oe1, pwr_oe2, pwr_oe3, pwr_oe4,
    adc_d, adc_clk,
    ssp_frame, ssp_din, ssp_dout, ssp_clk,
    cross_hi, cross_lo,
    dbg, divisor
);
    input pck0, ck_1356meg, ck_1356megb;
    output pwr_lo, pwr_hi, pwr_oe1, pwr_oe2, pwr_oe3, pwr_oe4;
    input [7:0] adc_d;
    output adc_clk;
    output ssp_frame, ssp_din, ssp_dout, ssp_clk;
    input cross_hi, cross_lo;
    output dbg;
    input [7:0] divisor;

    reg [7:0] pck_divider;
    reg ant_lo;

    // this task runs on the rising edge of pck0 clock (24Mhz) and creates ant_lo
    // which is high for (divisor+1) pck0 cycles and low for the same duration
    // ant_lo is therefore a 50% duty cycle clock signal with a frequency of
    // 12Mhz/(divisor+1) which drives the antenna as well as the ADC clock adc_clk
    always @(posedge pck0)
    begin
        if(pck_divider == divisor[7:0])
        begin
            pck_divider <= 8'd0;
            ant_lo = !ant_lo;
            adc_clk <= ant_lo;
        end
        else
        begin
            pck_divider <= pck_divider + 1;
        end
    end

    // the antenna is modulated when ssp_dout = 1, when 0 the
    // antenna drivers stop modulating and go into listen mode
    assign pwr_oe3 = 1'b0;
    assign pwr_oe1 = ssp_dout;
    assign pwr_oe2 = ssp_dout;
    assign pwr_oe4 = ssp_dout;
    assign pwr_lo = ant_lo && ssp_dout;
    assign pwr_hi = 1'b0;
    assign adc_clk = 1'b0;
    assign ssp_din = cross_lo;
    assign dbg = cross_lo;
    assign ssp_frame = 1'b0;
    assign ssp_clk = 1'b0;

endmodule

module binary_counter (
  input clk,
  input rst,
  input en,
  input load,
  output reg [3:0] q,
  output reg [3:0] q_bar
);

  always @(posedge clk) begin
    if (rst) begin
      q <= 4'b0000;
    end else if (en) begin
      q <= q + 1;
    end else if (load) begin
      q <= {q_bar[3], q_bar[2], q_bar[1], q_bar[0]};
    end
  end

  assign q_bar = ~q;

endmodule

module outputs (
   input			clk,
   input [63:0]	crc,
   output [63:0]	sum,
   output		RBL2,
   input			RWL1,
   input			RWL2
);

   wire			RBL2_internal;
   wire [63:0]	crc_internal;
   wire [63:0]	sum_internal;
   reg [6:0]		cyc;

   // CRC checksum generator
   always @ (posedge clk) begin
      crc_internal <= {crc[62:0], crc[63] ^ crc[2] ^ crc[0]};
   end

   // Sum generator
   always @ (posedge clk) begin
      sum_internal <= {sum_internal[62:0], sum_internal[63] ^ sum_internal[2] ^ sum_internal[0]};
   end

   // Test module instantiation
   Test t (
      .RBL2			(RBL2_internal),
      .RWL1			(RWL1),
      .RWL2			(RWL2)
   );

   // Aggregate outputs into a single result vector
   assign sum = {64'h0, sum_internal};

   // RBL2 output
   assign RBL2 = RBL2_internal;

   // Test loop
   always @ (posedge clk) begin
`ifdef TEST_VERBOSE
      $write("[%0t] cyc==%0d crc=%x sum=%x\n", $time, cyc, crc_internal, sum_internal);
`endif
      cyc <= cyc + 1;
      if (cyc==0) begin
         // Setup
         crc_internal <= 64'h5aef0c8d_d70a4497;
         sum_internal <= 64'h0;
      end
      else if (cyc<10) begin
         sum_internal <= 64'h0;
      end
      else if (cyc<90) begin
         crc_internal <= crc_internal;
         sum_internal <= {sum_internal[62:0], sum_internal[63] ^ sum_internal[2] ^ sum_internal[0]};
      end
      else if (cyc==99) begin
         $write("[%0t] cyc==%0d crc=%x sum=%x\n", $time, cyc, crc_internal, sum_internal);
         if (crc_internal !== 64'hc77bb9b3784ea091) $stop;
         // What checksum will we end up with (above print should match)
`define EXPECTED_SUM 64'hb6d6b86aa20a882a
         if (sum_internal !== `EXPECTED_SUM) $stop;
         $write("*-* All Finished *-*\n");
         $finish;
      end
   end

endmodule

module binary_counter_multiplier (
    input clk, // clock input for binary counter
    input reset, // reset input for binary counter
    input [31:0] a, // 32-bit input for multiplier
    input [31:0] b, // 32-bit input for multiplier
    output reg [31:0] product // 32-bit output from multiplier
    ); 

    reg [3:0] counter; // 4-bit binary counter

    always @(posedge clk, posedge reset) begin
        if (reset) begin
            counter <= 4'b0000; // reset counter to 0000
            product <= a * b; // set initial product to a * b
        end
        else begin
            if (counter == 4'b1111) begin
                counter <= 4'b0000; // reset counter to 0000
            end
            else begin
                counter <= counter + 1; // increment counter
            end

            // select multiplier output based on counter value
            case (counter)
                4'b0000: product <= a * b;
                4'b0001: product <= a * (b << 1);
                4'b0010: product <= (a << 2) * b;
                4'b0011: product <= (a << 3) * (b >> 1);
                4'b0100: product <= a * (b / 3);
                4'b0101: product <= a * (b / 5);
                4'b0110: product <= a * (b / 7);
                4'b0111: product <= a * (b / 9);
            endcase
        end
    end
endmodule

