module GreaterThan(A, B, RESET, RESULT);

   input [7:0] A;           // 8-bit input A
   input [7:0] B;           // 8-bit input B
   input RESET;             // input reset
   output RESULT;           // output result

   reg [7:0] A_reg;         // register for storing value of A
   reg [7:0] B_reg;         // register for storing value of B
   reg RESULT_reg;          // register for storing result

   always @ (posedge RESET or posedge A or posedge B) begin
      if (RESET) begin
         A_reg <= 8'b0;
         B_reg <= 8'b0;
         RESULT_reg <= 1'b0;
      end
      else begin
         A_reg <= A;
         B_reg <= B;
         if (A_reg > B_reg)
            RESULT_reg <= 1'b1;
         else
            RESULT_reg <= 1'b0;
      end
   end

   assign RESULT = RESULT_reg;

endmodule

module Convolutional_Encoder_and_Viterbi_Decoder (
  input [K-1:0] in,
  output [N-1:0] out
);

parameter K = 8; // number of bits in each input data word
parameter N = 12; // number of bits in each output data word
parameter M = 3; // number of delay elements in the encoder

// Define shift register for encoder
reg [M-1:0] shift_reg;

// Define encoder logic
always @ (posedge clk) begin
  // Shift input data into shift register
  shift_reg <= {shift_reg[K-2:0], in};

  // Generate encoded data
  out <= {shift_reg[M-1], shift_reg[M-1] ^ shift_reg[M-2], shift_reg[M-1] ^ shift_reg[M-3], shift_reg[M-2] ^ shift_reg[M-3]};
end

// Define trellis diagram for decoder
reg [1:0] state;
reg [1:0] prev_state;
reg [N-1:0] path_metric [0:3];

// Define decoder logic
always @ (posedge clk) begin
  // Calculate path metrics for each state
  path_metric[0] <= (in == {shift_reg[M-1], shift_reg[M-1] ^ shift_reg[M-2], shift_reg[M-1] ^ shift_reg[M-3], shift_reg[M-2] ^ shift_reg[M-3]}) ? 0 : 1;
  path_metric[1] <= (in == {shift_reg[M-1] ^ 1, shift_reg[M-1] ^ shift_reg[M-2] ^ 1, shift_reg[M-1] ^ shift_reg[M-3] ^ 1, shift_reg[M-2] ^ shift_reg[M-3]}) ? 0 : 1;
  path_metric[2] <= (in == {shift_reg[M-1] ^ shift_reg[M-2], shift_reg[M-1] ^ shift_reg[M-2] ^ shift_reg[M-3], shift_reg[M-1] ^ shift_reg[M-3], shift_reg[M-2] ^ shift_reg[M-3] ^ 1}) ? 0 : 1;
  path_metric[3] <= (in == {shift_reg[M-1] ^ shift_reg[M-3], shift_reg[M-1] ^ shift_reg[M-2] ^ shift_reg[M-3] ^ 1, shift_reg[M-1] ^ shift_reg[M-3] ^ 1, shift_reg[M-2] ^ shift_reg[M-3]}) ? 0 : 1;

  // Calculate branch metrics and update path metrics for each state transition
  if (state == 0) begin
    path_metric[2] <= path_metric[2] + path_metric[0];
    path_metric[3] <= path_metric[3] + path_metric[1];
  end else if (state == 1) begin
    path_metric[0] <= path_metric[0] + path_metric[2];
    path_metric[1] <= path_metric[1] + path_metric[3];
  end else if (state == 2) begin
    path_metric[0] <= path_metric[0] + path_metric[1];
    path_metric[2] <= path_metric[2] + path_metric[3];
  end else begin // state == 3
    path_metric[1] <= path_metric[1] + path_metric[0];
    path_metric[3] <= path_metric[3] + path_metric[2];
  end

  // Determine minimum path metric and update state
  if (path_metric[0] <= path_metric[1] && path_metric[0] <= path_metric[2] && path_metric[0] <= path_metric[3]) begin
    state <= 0;
  end else if (path_metric[1] <= path_metric[0] && path_metric[1] <= path_metric[2] && path_metric[1] <= path_metric[3]) begin
    state <= 1;
  end else if (path_metric[2] <= path_metric[0] && path_metric[2] <= path_metric[1] && path_metric[2] <= path_metric[3]) begin
    state <= 2;
  end else begin // path_metric[3] <= path_metric[0] && path_metric[3] <= path_metric[1] && path_metric[3] <= path_metric[2]
    state <= 3;
  end

  // Determine decoded output based on previous state and current state
  if (prev_state == 0 && state == 0) begin
    out <= {in[K-1], in[K-2], in[K-3], in[K-4], in[K-5], in[K-6], in[K-7], in[K-8], 0, 0, 0, 0};
  end else if (prev_state == 0 && state == 1) begin
    out <= {in[K-1], in[K-2], in[K-3], in[K-4], in[K-5], in[K-6], in[K-7], in[K-8], 0, 0, 0, 1};
  end else if (prev_state == 1 && state == 2) begin
    out <= {in[K-1], in[K-2], in[K-3], in[K-4], in[K-5], in[K-6], in[K-7], in[K-8], 0, 0, 1, 1};
  end else if (prev_state == 1 && state == 3) begin
    out <= {in[K-1], in[K-2], in[K-3], in[K-4], in[K-5], in[K-6], in[K-7], in[K-8], 0, 0, 1, 0};
  end else if (prev_state == 2 && state == 0) begin
    out <= {in[K-1], in[K-2], in[K-3], in[K-4], in[K-5], in[K-6], in[K-7], in[K-8], 0, 1, 1, 0};
  end else if (prev_state == 2 && state == 1) begin
    out <= {in[K-1], in[K-2], in[K-3], in[K-4], in[K-5], in[K-6], in[K-7], in[K-8], 0, 1, 1, 1};
  end else if (prev_state == 3 && state == 2) begin
    out <= {in[K-1], in[K-2], in[K-3], in[K-4], in[K-5], in[K-6], in[K-7], in[K-8], 0, 1, 0, 1};
  end else begin // prev_state == 3 && state == 3
    out <= {in[K-1], in[K-2], in[K-3], in[K-4], in[K-5], in[K-6], in[K-7], in[K-8], 0, 1, 0, 0};
  end

  // Update previous state
  prev_state <= state;
end

endmodule

module vending_machine(
    input clk,
    input reset,
    input coin,
    input bill,
    output item_dispensed,
    output change_dispensed,
    output reg [1:0] display
);

parameter IDLE = 2'b00, QUARTER = 2'b01, HALF = 2'b10, THREE_QUARTERS = 2'b11;
parameter DISPENSE_ITEM = 2'b01, DISPENSE_CHANGE = 2'b10, NO_DISPENSE = 2'b00;

reg [7:0] money_inserted = 8'd0;
reg [7:0] change_amount = 8'd0;
reg [1:0] state = IDLE;

assign item_dispensed = (state == DISPENSE_ITEM);
assign change_dispensed = (state == DISPENSE_CHANGE);

always @(posedge clk) begin
    if (reset) begin
        state <= IDLE;
        money_inserted <= 8'd0;
        change_amount <= 8'd0;
        display <= IDLE;
    end else begin
        case (state)
            IDLE: begin
                if (coin) begin
                    money_inserted <= money_inserted + 8'd25;
                    display <= QUARTER;
                    state <= (money_inserted == 8'd75) ? DISPENSE_ITEM : QUARTER;
                end else if (bill) begin
                    money_inserted <= money_inserted + 8'd100;
                    display <= HALF;
                    state <= (money_inserted == 8'd75) ? DISPENSE_ITEM : HALF;
                end else begin
                    display <= IDLE;
                    state <= IDLE;
                end
            end
            QUARTER: begin
                if (coin) begin
                    money_inserted <= money_inserted + 8'd25;
                    display <= HALF;
                    state <= (money_inserted == 8'd75) ? DISPENSE_ITEM : (money_inserted > 8'd75) ? DISPENSE_CHANGE : HALF;
                end else if (bill) begin
                    money_inserted <= money_inserted + 8'd100;
                    display <= THREE_QUARTERS;
                    state <= (money_inserted == 8'd75) ? DISPENSE_ITEM : THREE_QUARTERS;
                end else begin
                    display <= QUARTER;
                    state <= QUARTER;
                end
            end
            HALF: begin
                if (coin) begin
                    money_inserted <= money_inserted + 8'd25;
                    display <= THREE_QUARTERS;
                    state <= (money_inserted == 8'd75) ? DISPENSE_ITEM : (money_inserted > 8'd75) ? DISPENSE_CHANGE : THREE_QUARTERS;
                end else if (bill) begin
                    money_inserted <= money_inserted + 8'd100;
                    display <= IDLE;
                    state <= (money_inserted == 8'd75) ? DISPENSE_ITEM : IDLE;
                end else begin
                    display <= HALF;
                    state <= HALF;
                end
            end
            THREE_QUARTERS: begin
                if (coin) begin
                    money_inserted <= money_inserted + 8'd25;
                    display <= IDLE;
                    state <= (money_inserted == 8'd75) ? DISPENSE_ITEM : DISPENSE_CHANGE;
                    change_amount <= money_inserted - 8'd75;
                end else if (bill) begin
                    money_inserted <= money_inserted + 8'd100;
                    display <= IDLE;
                    state <= DISPENSE_CHANGE;
                    change_amount <= money_inserted - 8'd75;
                end else begin
                    display <= THREE_QUARTERS;
                    state <= THREE_QUARTERS;
                end
            end
            DISPENSE_ITEM: begin
                money_inserted <= money_inserted - 8'd75;
                display <= IDLE;
                state <= IDLE;
            end
            DISPENSE_CHANGE: begin
                change_amount <= change_amount - (change_amount / 8'd25) * 8'd25;
                display <= IDLE;
                state <= IDLE;
            end
        endcase
    end
end

endmodule

module bcd_to_binary (
    input [15:0] bcd_in,
    output reg [3:0] binary_out
);

reg [3:0] counter [3:0];
reg [3:0] temp [2:0];

always @ (posedge clk) begin
    // Stage 1
    temp[0] <= bcd_in[3:0];
    temp[1] <= bcd_in[7:4];
    temp[2] <= bcd_in[11:8];

    // Stage 2
    counter[0] <= (counter[0] == 4'b1001) ? 4'b0000 : counter[0] + 1'b1;
    counter[1] <= (counter[1] == 4'b1001) ? 4'b0000 : counter[1] + 1'b1;
    counter[2] <= (counter[2] == 4'b1001) ? 4'b0000 : counter[2] + 1'b1;
    counter[3] <= (counter[3] == 4'b1001) ? 4'b0000 : counter[3] + 1'b1;

    // Stage 3
    binary_out[0] <= (temp[0] >= counter[0]) ? 1'b1 : 1'b0;
    binary_out[1] <= (temp[1] >= counter[1]) ? 1'b1 : 1'b0;
    binary_out[2] <= (temp[2] >= counter[2]) ? 1'b1 : 1'b0;
    binary_out[3] <= (bcd_in[15] >= counter[3]) ? 1'b1 : 1'b0;
end

endmodule

module karnaugh_map(
  input wire A, B, C, D,
  output reg F
);

  always @(*) begin
    case ({A,B})
      2'b00: F = C & ~D | ~C & D;
      2'b01: F = A & ~B & ~C | ~A & B & ~C | A & B & C | ~A & ~B & C;
      2'b11: F = C & D | ~C & ~D;
      2'b10: F = A & B & ~C | ~A & ~B & ~C | A & ~B & C | ~A & B & C;
    endcase
  end

endmodule

module nios_system_alu_carry_out (
  // inputs:
  address,
  clk,
  in_port,
  reset_n,

  // outputs:
  readdata
);

  output  [31:0] readdata;
  input   [1:0]  address;
  input          clk;
  input          in_port;
  input          reset_n;

  wire    clk_en;
  wire    data_in;
  wire    read_mux_out;
  reg     [31:0] readdata;
  assign  clk_en = 1;

  //s1, which is an e_avalon_slave
  assign read_mux_out = {1 {(address == 2'b00)}} & (in_port & data_in);
  assign read_mux_out = read_mux_out | {1 {(address == 2'b01)}} & (in_port | data_in);

  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      readdata <= 0;
    end else if (clk_en) begin
      readdata <= {32'b0 | read_mux_out};
    end
  end

  assign data_in = in_port;

endmodule

module signed_adder (
    input signed [3:0] a,
    input signed [3:0] b,
    output signed [3:0] result,
    output overflow
);

reg signed [3:0] temp_result;
reg overflow;

always @(*) begin
    temp_result = a + b;
    if ((a[3] == 1 && b[3] == 1 && temp_result[3] == 0) || (a[3] == 0 && b[3] == 0 && temp_result[3] == 1)) begin
        overflow = 1;
    end else begin
        overflow = 0;
    end
end

assign result = temp_result;

endmodule

module four_bit_adder(
    input [3:0] a,
    input [3:0] b,
    input cin,
    output [3:0] sum,
    output cout
);

    wire c1, c2, c3;

    // Full adder for least significant bit
    full_adder fa0(a[0], b[0], cin, sum[0], c1);

    // Full adder for second least significant bit
    full_adder fa1(a[1], b[1], c1, sum[1], c2);

    // Full adder for third least significant bit
    full_adder fa2(a[2], b[2], c2, sum[2], c3);

    // Full adder for most significant bit
    full_adder fa3(a[3], b[3], c3, sum[3], cout);

endmodule

module full_adder(
    input a,
    input b,
    input cin,
    output sum,
    output cout
);

    wire w1, w2, w3;

    // First XOR gate
    xor x1(a, b, w1);

    // Second XOR gate
    xor x2(w1, cin, sum);

    // AND gate
    and a1(w1, cin, w2);
    and a2(a, b, w3);

    // OR gate
    or o1(w2, w3, cout);

endmodule

