module fixed_point_arithmetic (
  input [n-1:0] a,
  input [n-1:0] b,
  input [1:0] op,
  output [n-1:0] c
);

parameter n = 16; // number of bits for fixed point representation

// define the integer and fractional bits
parameter int_bits = 8;
parameter frac_bits = n - int_bits;

// define scaling factor for fixed-point representation
parameter scaling_factor = 2 ** frac_bits;

// define maximum and minimum values for fixed-point representation
parameter max_value = (2 ** (n - 1)) - 1;
parameter min_value = -max_value;

// define two's complement representation for negative numbers
function [n-1:0] twos_complement;
  input [n-1:0] num;
  begin
    if (num < 0) begin
      twos_complement = ~(-num) + 1;
    end
    else begin
      twos_complement = num;
    end
  end
endfunction

// perform fixed-point arithmetic operations based on control signal (op)
always @(*) begin
  case (op)
    2'b00: c = twos_complement(a) + twos_complement(b);
    2'b01: c = twos_complement(a) - twos_complement(b);
    2'b10: c = twos_complement(a) * twos_complement(b) / scaling_factor;
    2'b11: begin
      if (b == 0) begin
        c = max_value;
      end
      else begin
        c = (twos_complement(a) * scaling_factor) / twos_complement(b);
      end
    end
  endcase
end

endmodule

module hub_mem
(
    input clk,
    input ena,

    input w,
    input [3:0] wb,
    input [13:0] a,
    input [31:0] d,

    output [31:0] q
);

    // 16KB x 32 (64KB) ram with byte-write enables ($0000..$FFFF)
    reg [7:0] ram3 [16*1024-1:0];   // 4 x 16KB
    reg [7:0] ram2 [16*1024-1:0];
    reg [7:0] ram1 [16*1024-1:0];
    reg [7:0] ram0 [16*1024-1:0];

    // pre-load ROM
    initial
    begin
        $readmemh ("ROM_$F000-$FFFF_BYTE_0.spin", ram0, 15*1024);
        $readmemh ("ROM_$F000-$FFFF_BYTE_1.spin", ram1, 15*1024);
        $readmemh ("ROM_$F000-$FFFF_BYTE_2.spin", ram2, 15*1024);
        $readmemh ("ROM_$F000-$FFFF_BYTE_3.spin", ram3, 15*1024);
    end

    reg [7:0] ram_q3;
    reg [7:0] ram_q2;
    reg [7:0] ram_q1;
    reg [7:0] ram_q0;

    always @(posedge clk)
    begin
        if (ena && w && wb[3])
            ram3[a[13:0]] <= d[31:24];
        if (ena)
            ram_q3 <= ram3[a[13:0]];
    end

    always @(posedge clk)
    begin
        if (ena && w && wb[2])
            ram2[a[13:0]] <= d[23:16];
        if (ena)
            ram_q2 <= ram2[a[13:0]];
    end

    always @(posedge clk)
    begin
        if (ena && w && wb[1])
            ram1[a[13:0]] <= d[15:8];
        if (ena)
            ram_q1 <= ram1[a[13:0]];
    end

    always @(posedge clk)
    begin
        if (ena && w && wb[0])
            ram0[a[13:0]] <= d[7:0];
        if (ena)
            ram_q0 <= ram0[a[13:0]];
    end

    assign q = {ram_q3, ram_q2, ram_q1, ram_q0};

endmodule

