module johnson_counter (
    input clk,
    input rst_n,
    output reg [15:0] q
);

reg [15:0] next_q;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        q <= 16'b0000000000000000;
    end else begin
        next_q[0] <= q[15] ^ 1;
        next_q[1] <= q[0];
        next_q[2] <= q[1];
        next_q[3] <= q[2];
        next_q[4] <= q[3];
        next_q[5] <= q[4];
        next_q[6] <= q[5];
        next_q[7] <= q[6];
        next_q[8] <= q[7];
        next_q[9] <= q[8];
        next_q[10] <= q[9];
        next_q[11] <= q[10];
        next_q[12] <= q[11];
