module alu_module (
    input [3:0] A,
    input [3:0] B,
    input [2:0] opcode,
    input carry_in,
    input invert,
    output [3:0] result
);

wire [3:0] alu_out;

assign result = (opcode == 3'b000) ? (A + B) :
                (opcode == 3'b001) ? (A - B) :
                (opcode == 3'b010) ? (A & B) :
                (opcode == 3'b011) ? (A | B) :
                (opcode == 3'b100) ? (A ^ B) :
                (opcode == 3'b101) ? ((carry_in) ? (A + B + 1) : (A + B)) :
                (opcode == 3'b110) ? ((invert) ? (~B) : B) :
                4'b0000;

endmodule

