    input [3:0] data_in,
    input [3:0] shift_amount,
    output [3:0] data_out
);

assign data_out = (shift_amount == 4'b0000) ? data_in :
                  (shift_amount == 4'b0001) ? (data_in << 1) :
                  (shift_amount == 4'b0010) ? (data_in << 2) :
                  (shift_amount == 4'b0011) ? (data_in << 3) :
                  (shift_amount == 4'b0100) ? (data_in << 4) :
                  4'b0000;

endmodule

