module simple_calculator (
    input [31:0] A,
    input [31:0] B,
    input [1:0] Op,
    output [31:0] C
);

    wire [63:0] prod;
    wire [31:0] quotient;
    wire [31:0] remainder;

    always @* begin
        case(Op)
            2'b00: C = A + B;
            2'b01: C = A - B;
            2'b10: begin
                prod = A * B;
                C = prod[31:0];
            end
            2'b11: begin
                if(B == 0) begin
                    C = 32'hffffffff;
                end else begin
                    quotient = A / B;
                    remainder = A % B;
                    C = quotient;
                end
            end
        endcase
    end

endmodule

