module signed_multiplier (
    input signed [15:0] A_input,
    input signed [15:0] B_input,
    output signed [31:0] P_output
);
    reg signed [15:0] A;
    reg signed [15:0] B;
    reg signed [31:0] P;
    reg [1:0] state;

    always @(*) begin
        case(state)
            2'b00: begin
                A <= A_input;
                B <= B_input;
                state <= 2'b01;
            end
            2'b01: begin
                P <= {16'b0, A};
                state <= 2'b10;
            end
            2'b10: begin
                if (B[0] == 1) begin
                    P <= P - A;
                end
                P <= P >> 1;
                B <= B >> 1;
                if (B == 0) begin
                    state <= 2'b11;
                end
            end
            2'b11: begin
                P_output <= P;
                state <= 2'b00;
            end
        endcase
    end

endmodule

module top_module(
    input clk,
    input reset,
    input [1:0] select,
    input load,
    input [1:0] ena,
    input [99:0] data,
    output reg [99:0] q,
    output reg [3:0] jc_q
);

reg [99:0] rot_q;
reg [3:0] jc_q_reg;
wire [99:0] and_out;

// Instantiate the 100-bit register rotation module
register_rotation_module rot_module(
    .clk(clk),
    .reset(reset),
    .load(load),
    .left_right(select[0]),
    .data(data),
    .ena(ena),
    .q(rot_q)
);

// Instantiate the Johnson counter module
johnson_counter_module jc_module(
    .clk(clk),
    .reset(reset),
    .q(jc_q_reg)
);

// Instantiate the AND gate module
and_gate_module and_module(
    .a(rot_q),
    .b(jc_q_reg),
    .out(and_out)
);

// Control logic to select active module
always @ (select or reset) begin
    if (reset) begin
        q <= 0;
        jc_q <= 0;
    end else begin
        case (select)
            2'b00: begin // 100-bit register rotation module is active
                q <= rot_q;
                jc_q <= 0;
            end
            2'b01: begin // Johnson counter module is active
                q <= 0;
                jc_q <= jc_q_reg;
            end
            2'b10: begin // AND gate module is active
                q <= and_out;
                jc_q <= 0;
            end
        endcase
    end
end

endmodule

// 100-bit register rotation module
module register_rotation_module(
    input clk,
    input reset,
    input load,
    input left_right,
    input [99:0] data,
    input [1:0] ena,
    output reg [99:0] q
);

reg [99:0] q_reg;

always @ (posedge clk) begin
    if (reset) begin
        q_reg <= 0;
    end else begin
        if (load) begin
            q_reg <= data;
        end else begin
            if (ena[1] && ena[0]) begin
                q_reg <= {q_reg[0], q_reg[99:1]};
            end else if (ena[1]) begin
                q_reg <= {q_reg[1:0], q_reg[99:2]};
            end else if (ena[0]) begin
                q_reg <= {q_reg[98:0], q_reg[99]};
            end
        end
    end
end

assign q = q_reg;

endmodule

