        Q0 <= D;
    end

    always @(negedge clk)
    begin
        Q1 <= D;
    end

endmodule

module run_length_limiter #(
    parameter LANE_WIDTH  = 64,
    parameter GRANULARITY = 4,
    parameter RUN_LIMIT   = 85
)
(
    input wire              clk,
    input wire              res_n,
    input wire              enable,
    input wire [LANE_WIDTH-1:0] data_in,
    output reg [LANE_WIDTH-1:0] data_out,
    output reg              rf_bit_flip
);

localparam NUM_CHUNKS   = (LANE_WIDTH + GRANULARITY-1)/(GRANULARITY);
localparam REM_BITS     = LANE_WIDTH - (GRANULARITY * (LANE_WIDTH/GRANULARITY));
localparam COUNT_BITS   = $clog2(RUN_LIMIT+1);

wire [NUM_CHUNKS-1:0] is_run;
wire [COUNT_BITS-1:0] count_top;
reg [COUNT_BITS-1:0] count_bottom_d1;
reg [NUM_CHUNKS-1:0] is_run_d1;
reg                  data_in_bottom_d1;

genvar chunk;
generate
    for(chunk=0; chunk<NUM_CHUNKS; chunk=chunk+1) begin : is_run_gen
        assign is_run[chunk] = 
            (chunk == 0) ? 
                &( {data_in[GRANULARITY-1:0],data_in_bottom_d1}) ||
                &(~{data_in[GRANULARITY-1:0],data_in_bottom_d1}) :
            (chunk == NUM_CHUNKS-1) ?
                &( data_in[LANE_WIDTH-1:(NUM_CHUNKS-1)*(GRANULARITY)-1]) ||
                &(~data_in[LANE_WIDTH-1:(NUM_CHUNKS-1)*(GRANULARITY)-1]) :
                &( data_in[(chunk+1)*(GRANULARITY)-1:chunk*(GRANULARITY)-1]) ||
                &(~data_in[(chunk+1)*(GRANULARITY)-1:chunk*(GRANULARITY)-1]);
    end

    // Start at the top and count until a run is broken
    assign count_top[0] = is_run[0];
    for(chunk=1; chunk<NUM_CHUNKS; chunk=chunk+1) begin : count_top_gen
        assign count_top[chunk] = (is_run[chunk] && count_top[chunk-1]) ? count_top[chunk-1] + 1 : 1;
    end

    // Start at the bottom and count until a run is broken
    assign is_run_d1 = {is_run[NUM_CHUNKS-2], is_run_d1[NUM_CHUNKS-2]};
    assign count_bottom_d1 = (is_run_d1[NUM_CHUNKS-1] && count_bottom_d1 != RUN_LIMIT) ? count_bottom_d1 + 1 : 1;

endgenerate

assign rf_bit_flip = (count_top[NUM_CHUNKS-1] > RUN_LIMIT) && enable;

always @(posedge clk or negedge res_n) begin
    if (!res_n) begin
        count_bottom_d1     <= 0;
        is_run_d1           <= {NUM_CHUNKS{1'b0}};
        data_in_bottom_d1   <= 1'b0;
        rf_bit_flip         <= 1'b0;
        data_out            <= {LANE_WIDTH{1'b0}};
    end else begin
        count_bottom_d1     <= count_bottom_d1;
        is_run_d1           <= is_run;
        data_in_bottom_d1   <= data_in[LANE_WIDTH-1];

        if (enable && rf_bit_flip) begin
            data_out        <= {data_in[LANE_WIDTH-1:1], ~data_in[0]};
            rf_bit_flip     <= 1'b0;
        end else begin
            data_out        <= data_in;
        end
    end
end

endmodule

module adapter_ppfifo_2_ppfifo#(
  parameter DATA_WIDTH              = 32
)(
  input                               clk,
  input                               rst,

  input                               i_read_ready,
  output  reg                         o_read_activate,
  input           [23:0]              i_read_size,
  input           [DATA_WIDTH - 1:0]  i_read_data,
  output  reg                         o_read_stb,

  input           [1:0]               i_write_ready,
  output  reg     [1:0]               o_write_activate,
  input           [23:0]              i_write_size,
  output  reg                         o_write_stb,
  output          [DATA_WIDTH - 1:0]  o_write_data

);
//registes/wires
reg [23:0]                            read_count;
reg [23:0]                            write_count;

assign  o_write_data    = i_read_data;

always @ (posedge clk) begin
  o_read_stb                      <=  0;
  o_write_stb                     <=  0;
  if (rst) begin
    o_write_activate              <=  0;
    o_read_activate               <=  0;
    write_count                   <=  0;
    read_count                    <=  0;
  end
  else begin
    if (i_read_ready && !o_read_activate) begin
      read_count                  <=  0;
      o_read_activate             <=  1;
    end
    if ((i_write_ready > 0) && (o_write_activate == 0)) begin
      write_count                   <=  0;
      if (i_write_ready[0]) begin
        o_write_activate[0]         <=  1;
      end
      else begin
        o_write_activate[1]         <=  1;
      end
    end

    //Both FIFOs are available
    if (o_read_activate && (o_write_activate > 0)) begin
      if ((write_count < i_write_size) && (read_count < i_read_size))begin
        o_write_stb                 <=  1;
        o_read_stb                  <=  1;
        write_count                 <=  write_count + 1;
        read_count                  <=  read_count + 1;
      end
      else begin
        if (write_count >= i_write_size) begin
          o_write_activate          <=  0;
        end
        if (read_count >= i_read_size) begin
          //Both FIFOs should be released, this way the output is never blocked on the input
          o_read_activate           <=  0;
          o_write_activate          <=  0;
        end
      end
    end
  end
end

endmodule

