module uart_bus_controller
#(
    parameter BUS_TIMEOUT=(1024*1024*100)
)
(
    input clk_i, rst_i,

    input rx_i,
    output tx_o,

    output rst_o,
    output bus_req_o,
    input bus_ack_i,
    output bus_we_o,
    output [31:0] bus_addr_bo,
    output [3:0] bus_be_bo,
    output [31:0] bus_wdata_bo,

    input bus_resp_i,
    input [31:0] bus_rdata_bi
);

// UART receiver
reg [7:0] rx_buffer [0:15];
reg [3:0] rx_head;
reg [3:0] rx_tail;
reg rx_overflow;
wire rx_done_tick;
wire [7:0] rx_data;

uart_rx #(
    .RTX_EXTERNAL_OVERRIDE("NO")
) uart_rx (
    .clk_i(clk_i),
    .rst_i(rst_i),

    .rx_i(rx_i),
    .rx_done_tick_o(rx_done_tick),
    .dout_bo(rx_data)
);

always @(posedge clk_i) begin
    if (rst_i) begin
        rx_head <= 0;
        rx_tail <= 0;
        rx_overflow <= 0;
    end else if (rx_done_tick) begin
        if (rx_tail == rx_head && rx_overflow == 1) begin
            rx_overflow <= 1;
        end else begin
            rx_buffer[rx_head] <= rx_data;
            rx_head <= (rx_head == 15) ? 0 : rx_head + 1;
            rx_overflow <= 0;
        end
    end
end

// UART transmitter
reg [7:0] tx_buffer [0:15];
reg [3:0] tx_head;
reg [3:0] tx_tail;
wire tx_start;
wire tx_done_tick;
wire locked;
wire [28:0] bitperiod;
reg tx_busy;

uart_tx #(
    .RTX_EXTERNAL_OVERRIDE("NO")
) uart_tx (
    .clk_i(clk_i),
    .rst_i(rst_i),

    .tx_start_i(tx_start),
    .din_bi(tx_buffer[tx_tail]),

    .locked_i(locked),
    .bitperiod_i(bitperiod),

    .tx_done_tick_o(tx_done_tick),
    .tx_o(tx_o)
);

always @(posedge clk_i) begin
    if (rst_i) begin
        tx_head <= 0;
        tx_tail <= 0;
        tx_busy <= 0;
    end else if (tx_done_tick) begin
        tx_tail <= (tx_tail == 15) ? 0 : tx_tail + 1;
        tx_busy <= (tx_head == tx_tail) ? 0 : 1;
    end
end

assign tx_start = (tx_busy == 1) ? 0 : 1;

// Bus controller
reg [31:0] bus_addr;
reg [3:0] bus_be;
reg [31:0] bus_wdata;
reg bus_req;
reg bus_we;
reg [31:0] bus_rdata;
reg bus_resp;
reg [31:0] bus_timeout;
wire locked_bus;
wire [28:0] bitperiod_bus;

udm_controller #(
    .BUS_TIMEOUT(BUS_TIMEOUT)
) udm_controller (
    .clk_i(clk_i),
    .reset_i(rst_i),

    // uart rx
    .rx_done_tick_i(rx_done_tick),
    .rx_din_bi(rx_data),

    // uart tx
    .tx_dout_bo(tx_buffer[tx_head]),
    .tx_start_o(tx_start),
    .tx_done_tick_i(tx_done_tick),

    // bus
    .rst_o(rst_o),
    .bus_req_o(bus_req_o),
    .bus_ack_i(bus_ack_i),
    .bus_we_o(bus_we_o),
    .bus_addr_bo(bus_addr_bo),
    .bus_be_bo(bus_be_bo),
    .bus_wdata_bo(bus_wdata_bo),

    .bus_resp_i(bus_resp_i),
    .bus_rdata_bi(bus_rdata_bi)
);

always @(posedge clk_i) begin
    if (rst_i) begin
        bus_req <= 0;
        bus_we <= 0;
        bus_resp <= 0;
        bus_timeout <= 0;
        bus_addr <= 0;
        bus_be <= 0;
        bus_wdata <= 0;
    end else if (bus_resp_i) begin
        bus_resp <= 1;
        bus_timeout <= 0;
        if (bus_we) begin
            bus_wdata <= 0;
        end else begin
            bus_rdata <= bus_rdata_bi;
        end
    end else if (bus_req && !bus_ack_i) begin
        bus_timeout <= bus_timeout + 1;
        if (bus_timeout == BUS_TIMEOUT) begin
            bus_resp <= 1;
            bus_timeout <= 0;
        end
    end else if (!bus_req && locked_bus) begin
        bus_req <= 1;
        bus_we <= 0;
        bus_addr <= bus_addr_bo;
        bus_be <= bus_be_bo;
    end else if (bus_req && bus_ack_i) begin
        bus_req <= 0;
        bus_we <= 0;
        bus_resp <= 0;
        bus_timeout <= 0;
        if (bus_we) begin
            bus_wdata <= bus_wdata_bo;
        end
    end
end

assign locked_bus = locked && !bus_req;

endmodule

