module bcd_counter (
    input clk,
    input reset,   // Synchronous active-high reset
    output [3:1] ena,
    output [15:0] q);

    reg [3:0] johnson_q;
    reg [3:0] bcd_q [0:3];
    reg [1:0] bcd_carry [0:2];

    assign q = {bcd_q[3], bcd_q[2], bcd_q[1], bcd_q[0]};
    assign ena = {bcd_carry[2], bcd_carry[1], bcd_carry[0]};

    always @(posedge clk) begin
        if (reset) begin
            johnson_q <= 4'b0001;
            bcd_q <= 4'b0000;
            bcd_carry <= 2'b00;
        end else begin
            johnson_q <= {johnson_q[2:0], johnson_q[3]};
            case (johnson_q)
                4'b0001: bcd_q[0] <= bcd_q[0] + 1;
                4'b0010: begin
                    bcd_q[0] <= 0;
                    bcd_carry[0] <= 1;
                end
                4'b0100: begin
                    bcd_q[1] <= bcd_q[1] + 1;
                    bcd_carry[0] <= 0;
                end
                4'b1000: begin
                    bcd_q[1] <= 0;
                    bcd_carry[1] <= 1;
                end
                4'b0001_0000: begin
                    bcd_q[2] <= bcd_q[2] + 1;
                    bcd_carry[1] <= 0;
                end
                4'b0010_0000: begin
                    bcd_q[2] <= 0;
                    bcd_carry[2] <= 1;
                end
                4'b0100_0000: begin
                    bcd_q[3] <= bcd_q[3] + 1;
                    bcd_carry[2] <= 0;
                end
                4'b1000_0000: begin
                    bcd_q[3] <= 0;
                end
            endcase
        end
    end

