module carry_select_adder (
    input [15:0] A,
    input [15:0] B,
    input Cin,
    output reg [15:0] S,
    output reg Cout
);

wire [15:0] P, G;
wire [7:0] C;
wire [7:0] Cn;

genvar i;
generate
    for (i = 0; i < 8; i = i + 1) begin : carry_select_generate
        assign P[i] = A[i] ^ B[i];
        assign G[i] = A[i] & B[i];
        assign C[i] = (i == 0) ? Cin : (G[i-1] | (P[i-1] & C[i-1]));
        assign Cn[i] = (~G[i] & C[i]) | (P[i] & C[i-1]);
    end
endgenerate

assign S = A + B + Cin;
assign Cout = Cn[7];

always @(posedge clk) begin
    S <= A + B + Cin;
    Cout <= Cn[7];
end

endmodule

