module new_system (
    input clk,
    input reset, // Synchronous active-high reset
    input [3:0] in, // 4-bit input for the "combinational_circuit" module
    input [15:0] in_16, // 16-bit input for the new system
    output reg [7:0] final_out, // 8-bit output from the final module
    output reg led, // output for LED control
    output reg buzzer // output for buzzer control
);

    // Split the 16-bit input into two 8-bit outputs
    reg [7:0] upper_byte;
    reg [7:0] lower_byte;
    assign upper_byte = in_16[15:8];
    assign lower_byte = in_16[7:0];

    // Instantiate the combinational circuit module
    combinational_circuit cc_inst (
        .in(in),
        .out_and(out_and),
        .out_or(out_or),
        .out_xor(out_xor)
    );

    // Use the upper byte to control the LED
    always @ (posedge clk) begin
        if (reset) begin
            led <= 0;
        end else begin
            if (upper_byte == 8'hFF) begin
                led <= 1;
            end else begin
                led <= 0;
            end
        end
    end

    // Use the XOR gate output to control the buzzer
    always @ (posedge clk) begin
        if (reset) begin
            buzzer <= 0;
        end else begin
            if (out_xor) begin
                buzzer <= 1;
            end else begin
                buzzer <= 0;
            end
        end
    end

    // Store the final output in an 8-bit register with active high synchronous reset
    always @ (posedge clk) begin
        if (reset) begin
            final_out <= 8'h00;
        end else begin
            final_out <= lower_byte;
        end
    end

endmodule

