module top_module(
    input [31:0] a,
    input [31:0] b,
    output [31:0] sum
);

    wire [15:0] a_low = a[15:0];
    wire [15:0] b_low = b[15:0];
    wire [15:0] a_high = a[31:16];
    wire [15:0] b_high = b[31:16];

    wire [15:0] carry_low;
    wire [15:0] carry_high;
    wire [16:0] carry_intermediate;

    // 16-bit adder for the low bits
    adder16 adder_low(
        .a(a_low),
        .b(b_low),
        .sum(sum[15:0]),
        .carry_out(carry_low)
    );

    // Carry look-ahead adder for the high bits
    carry_lookahead_adder adder_high(
        .a(a_high),
        .b(b_high),
        .carry_out(carry_high),
        .carry_intermediate(carry_intermediate)
    );

    // Combine the carry bits and add the high and low sums
    assign sum = {carry_intermediate[16], carry_high, carry_low} + {16'b0, a_high, a_low} + {16'b0, b_high, b_low};

endmodule

// 16-bit adder module
module adder16(
    input [15:0] a,
    input [15:0] b,
    output [15:0] sum,
