module flip_flop (
  input clk,
  input rst,
  input data,
  output reg q,
  output reg q_bar
);

parameter type = "D"; // flip-flop type (D, JK, T, or SR)

always @(posedge clk) begin
  if (rst) begin
    q <= (type == "JK" || type == "SR") ? 1'b1 : 1'b0;
    q_bar <= (type == "JK" || type == "SR") ? 1'b0 : 1'b1;
  end else begin
    case (type)
      "D": begin
        q <= data;
        q_bar <= ~data;
      end
      "JK": begin
        if (data) begin
          q <= ~q_bar;
          q_bar <= ~q;
        end else begin
          q <= q;
          q_bar <= q_bar;
        end
      end
      "T": begin
        if (data) begin
          q <= ~q;
          q_bar <= ~q_bar;
        end else begin
          q <= q;
          q_bar <= q_bar;
        end
      end
      "SR": begin
        if (data) begin
          q <= (q_bar) ? 1'b0 : 1'b1;
          q_bar <= (q) ? 1'b0 : 1'b1;
        end else begin
          q <= q;
          q_bar <= q_bar;
