module dual_clock_fifo
   (wr_data_count,
    wr_clk,
    wr_rst,
    wr_addr,
    rd_addr,
    rd_count,
    rd_next);

  parameter DATA_WIDTH = 32;
  parameter ADDR_WIDTH = 13;
  parameter DEPTH = 1 << ADDR_WIDTH;
  parameter COUNT_WIDTH = $clog2(DEPTH+1);

  output reg [1:0] wr_data_count;
  input wr_clk, wr_rst;
  input [ADDR_WIDTH-1:0] wr_addr, rd_addr;
  input [COUNT_WIDTH-1:0] rd_count;
  output reg [ADDR_WIDTH-1:0] rd_next;

  reg [DATA_WIDTH-1:0] fifo [0:DEPTH-1];
  reg [COUNT_WIDTH-1:0] wr_count, rd_count_reg;
  reg [ADDR_WIDTH-1:0] wr_ptr, rd_ptr;
  reg [1:0] wr_data_count_reg;

  always @(posedge wr_clk) begin
    if (wr_rst) begin
      wr_ptr <= 0;
      wr_count <= 0;
      rd_ptr <= 0;
      rd_count_reg <= 0;
      wr_data_count_reg <= 0;
    end else begin
      if (wr_count < DEPTH) begin
        fifo[wr_ptr] <= wr_data;
        wr_ptr <= wr_ptr + 1;
        wr_count <= wr_count + 1;
        wr_data_count_reg <= wr_data_count_reg + 1;
      end
    end
  end

  always @(posedge rd_clk) begin
    if (rd_rst) begin
      rd_ptr <= 0;
      rd_count_reg <= 0;
    end else begin
      if (rd_count_reg > 0) begin
        rd_next <= rd_ptr + 1;
        rd_count_reg <= rd_count_reg - 1;
        rd_ptr <= rd_ptr + 1;
      end else begin
        rd_next <= rd_ptr;
      end
    end
  end

  assign wr_data_count = wr_data_count_reg;

endmodule

