module uart(
   input wire clk,
   input wire resetq,
   input wire uart_rx,
   output wire uart_tx,
   input wire uart_wr_i,
   output wire uart_busy,
   output wire [7:0] uart_dat_o
);

   // Internal registers and wires
   reg [3:0] rx_state;
   reg [3:0] tx_state;
   reg [7:0] tx_buffer [0:15];
   reg [7:0] rx_buffer [0:15];
   reg [3:0] tx_head;
   reg [3:0] tx_tail;
   reg [3:0] rx_head;
   reg [3:0] rx_tail;
   reg [3:0] tx_count;
   reg [3:0] rx_count;
   wire uart_rd_i;
   wire uart_dat_i;
   wire uart_valid;

   // Instantiate receive and transmit modules
   buart rx_inst (
      .clk(clk),
      .resetq(resetq),
      .rx(uart_rx),
      .rd(uart_rd_i),
      .valid(uart_valid),
      .rx_data(uart_dat_i)
   );
   buart tx_inst (
      .clk(clk),
      .resetq(resetq),
      .tx(uart_tx),
      .wr(uart_wr_i),
      .busy(uart_busy),
      .tx_data(tx_buffer[tx_tail]),
      .rx_data()
   );

   // Receive state machine
   always @(posedge clk) begin
      if (!resetq) begin
         rx_state <= 4'b0000;
         rx_head <= 4'b0000;
         rx_tail <= 4'b0000;
         rx_count <= 4'b0000;
      end else begin
         case (rx_state)
            4'b0000: begin // Wait for start bit
               if (!uart_valid && rx_count == 0) begin
                  rx_state <= 4'b0001;
               end
            end
            4'b0001: begin // Receive data bits
               rx_buffer[rx_head] <= uart_dat_i;
               rx_head <= (rx_head == 4'b1111) ? 4'b0000 : rx_head + 1;
               rx_count <= rx_count + 1;
               if (rx_count == 8) begin
                  rx_state <= 4'b0010;
               end
            end
            4'b0010: begin // Wait for stop bit
               if (uart_valid) begin
                  rx_state <= 4'b0000;
                  rx_count <= 4'b0000;
                  if (rx_head != rx_tail) begin
                     rx_tail <= (rx_tail == 4'b1111) ? 4'b0000 : rx_tail + 1;
                  end
               end
            end
         endcase
      end
   end

   // Transmit state machine
   always @(posedge clk) begin
      if (!resetq) begin
         tx_state <= 4'b0000;
         tx_head <= 4'b0000;
         tx_tail <= 4'b0000;
         tx_count <= 4'b0000;
      end else begin
         case (tx_state)
            4'b0000: begin // Wait for data in transmit buffer
               if (tx_count > 0) begin
                  tx_state <= 4'b0001;
               end
            end
            4'b0001: begin // Transmit start bit
               tx_buffer[tx_tail] <= 8'b00000001;
               tx_head <= (tx_head == 4'b1111) ? 4'b0000 : tx_head + 1;
               tx_count <= tx_count - 1;
               tx_state <= 4'b0010;
            end
            4'b0010: begin // Transmit data bits
               tx_buffer[tx_tail] <= {1'b0, tx_buffer[tx_tail][7:1]};
               tx_head <= (tx_head == 4'b1111) ? 4'b0000 : tx_head + 1;
               tx_count <= tx_count - 1;
               if (tx_count == 0) begin
                  tx_state <= 4'b0011;
               end
            end
            4'b0011: begin // Transmit stop bit
               tx_buffer[tx_tail] <= 8'b00000010;
               tx_head <= (tx_head == 4'b1111) ? 4'b0000 : tx_head + 1;
               tx_count <= tx_count - 1;
               tx_state <= 4'b0000;
               if (tx_count == 0) begin
                  uart_busy <= 0;
               end
            end
         endcase
      end
   end

   // Transmit buffer logic
   always @(posedge clk) begin
      if (!resetq) begin
         tx_head <= 4'b0000;
         tx_tail <= 4'b0000;
         tx_count <= 4'b0000;
      end else begin
         if (uart_wr_i && tx_count < 16) begin
            tx_buffer[tx_head] <= uart_dat_i;
            tx_head <= (tx_head == 4'b1111) ? 4'b0000 : tx_head + 1;
            tx_count <= tx_count + 1;
            uart_busy <= 1;
         end
      end
   end

   // Receive buffer logic
   always @(posedge clk) begin
      if (!resetq) begin
         rx_head <= 4'b0000;
         rx_tail <= 4'b0000;
         rx_count <= 4'b0000;
      end else begin
         if (uart_rd_i && rx_count > 0) begin
            uart_dat_o <= rx_buffer[rx_tail];
            rx_tail <= (rx_tail == 4'b1111) ? 4'b0000 : rx_tail + 1;
            rx_count <= rx_count - 1;
         end else begin
            uart_dat_o <= 8'b0;
         end
      end
   end

endmodule

