    carry_lookahead_adder_4bit cla17(a[71:68], b[71:68], c67, s71, c71);
    carry_lookahead_adder_4bit cla18(a[75:72], b[75:72], c71, s75, c75);
    carry_lookahead_adder_4bit cla19(a[79:76], b[79:76], c75, s79, c79);
    carry_lookahead_adder_4bit cla20(a[83:80], b[83:80], c79, s83, c83);
    carry_lookahead_adder_4bit cla21(a[87:84], b[87:84], c83, s87, c87);
    carry_lookahead_adder_4bit cla22(a[91:88], b[91:88], c87, s91, c91);
    carry_lookahead_adder_4bit cla23(a[95:92], b[95:92], c91, s95, c95);
    carry_lookahead_adder_4bit cla24(a[99:96], b[99:96], c95, s99, cout);

    // Calculate sum
    assign sum = {s99, s95, s91, s87, s83, s79, s75, s71, s67, s63, s59, s55, s51, s47, s43, s39, s35, s31, s27, s23, s19, s15, s11, s7, s3, a[100], b[100]};

    // Instantiate count module
    ones_count ones(sum, c_count);

endmodule
module carry_lookahead_adder_4bit( 
    input [3:0] a, b,
    input cin,
    output [3:0] sum,
    output cout );

    // Define internal wires and signals
    wire p0, g0, p1, g1, p2, g2, p3, g3;

    // Calculate p and g signals
    assign p0 = a[0] ^ b[0];
    assign g0 = a[0] & b[0];
    assign p1 = a[1] ^ b[1];
    assign g1 = a[1] & b[1];
    assign p2 = a[2] ^ b[2];
    assign g2 = a[2] & b[2];
    assign p3 = a[3] ^ b[3];
    assign g3 = a[3] & b[3];

    // Calculate sum and carry-out
    assign sum = {p3, p2, p1, p0};
    assign cout = (g3 | (g2 & p3) | (g1 & p2 & p3) | (g0 & p1 & p2 & p3) | (cin & p0 & p1 & p2 & p3));

endmodule

module sigma_delta (
  input analog_in,
  input clk,
  output delta_out
);

  reg [Order:0] quant_error;
  reg delta_out_reg;
  wire comparator_out;

  always @(posedge clk) begin
    quant_error <= analog_in - delta_out_reg;
    delta_out_reg <= quant_error[Order];
  end

  assign comparator_out = quant_error[Order-1:0] >= 0;
  assign delta_out = comparator_out;

endmodule

module sigma_delta_demod (
  input digital_in,
  input clk,
  output analog_out
);

  parameter CUTOFF_FREQ = 0.1; // cutoff frequency of the low-pass filter
  parameter VREF = 1; // reference voltage for the DAC

  reg [Order:0] digital_in_reg;
  reg [7:0] dac_out_reg;
  wire [7:0] dac_out;

  assign dac_out = digital_in_reg * VREF / (2**Order);
  assign analog_out = dac_out_reg * VREF / 256;

  always @(posedge clk) begin
    digital_in_reg <= digital_in;
    dac_out_reg <= dac_out;
  end

  // Low-pass filter
  reg [7:0] filter_reg;
  reg [7:0] filter_out_reg;
  wire [7:0] filter_out;

  assign filter_out = filter_reg + digital_in_reg - filter_out_reg;

  always @(posedge clk) begin
    filter_reg <= filter_out * CUTOFF_FREQ / (OSR * 2 * $bitwidth(filter_out));
    filter_out_reg <= filter_out;
  end

endmodule

module UART (
    input Clk_100M,
    input Reset,
    input Rx,
    output Tx,
    output reg [15:0] LEDs
);

    reg [7:0] userData[0:99];
    wire Rx_Ready;
    reg Rx_Ack;
    wire [7:0] Rx_Data;
    reg [7:0] Tx_Data;
    reg Tx_Send;
    wire Tx_Busy;
    reg Tx_Reset;
    reg [7:0] Tx_DataIndex;
    reg Tx_DataIndexLocked;
    reg [7:0] sizeOfDataInByte;
    reg [7:0] charCount;
    reg receivingData;
    reg prevBusyState;
    initial prevBusyState = 1'b0;
    initial sizeOfDataInByte = 1'b0;
    reg doneReceiving;
    //initial doneReceiving = 1'b1;

    // RECEIVE
    always @(posedge Clk_100M) begin
        if (Reset) begin
            Rx_Ack <= 0;
            charCount <= 0;
            doneReceiving <= 0;
        end
        else begin
            if (prevBusyState & Rx_Ready) begin
                // very first byte expected to be # characters in data.
                if (sizeOfDataInByte == 0) begin
                    sizeOfDataInByte <= Rx_Data; // get number of characters in data.
                    receivingData <= 1'b1; // next up start receiving data.
                end
                // actual data starts from byte 2.
                else if (receivingData) begin
                    userData[charCount] <= Rx_Data; // actual data.
                    charCount <= charCount + 1'b1;
                    // if done receiving data, receive key.
                    if (charCount == sizeOfDataInByte - 1) begin
                        receivingData <= 1'b0; // to indicate finish receiving data.
                        doneReceiving <= 1;
                    end
                end
                Rx_Ack <= 1'b1;
            end else if(~Rx_Ready) begin
                Rx_Ack <= 1'b0;
            end
            prevBusyState <= !Rx_Ready;
        end
    end

    // SEND.
    always @(posedge Clk_100M) begin
        if (Reset) begin
            Tx_Data <= 1'b0;
            Tx_Send <= 1'b0;
            Tx_Reset <= 1'b0;
            Tx_DataIndex <= 1'b0;
            Tx_DataIndexLocked <= 1'b1; // used to lock Tx_DataIndex to prevent uncontrolled increments.
        end
        else if (doneReceiving) begin
            if (Tx_Busy == 0 && Tx_DataIndex < sizeOfDataInByte) begin
                Tx_Data <= userData[Tx_DataIndex];
                Tx_Send <= 1'b1;
                Tx_DataIndexLocked <= 1'b0;
            end
            else begin
                if (~Tx_DataIndexLocked) begin
                    Tx_DataIndex <= Tx_DataIndex + 1'b1;
                    Tx_DataIndexLocked <= 1'b1;
                end
                Tx_Send <= 1'b0;
            end
        end
    end

    UART_Sender #(14, 14'd9999) sender(
        Clk_100M,
        //Tx_Reset,
        Reset,
        Tx_Data,
        Tx_Send,
        Tx_Busy,
        Tx
    );

    UART_Receiver #(14, 14'd9999) receiver(
        Clk_100M,
        Reset,
        Rx_Data,
        Rx_Ready,
        Rx_Ack,
        Rx
    );

    always @(*) begin
        // displays characters on the LEDs. Characters are shifted using btn P17 and M17
        // going from left to right and right to left respectively.
        LEDs[15:8] <= Tx_DataIndex;
        LEDs[7:0] <= userData[Tx_DataIndex];
    end

endmodule

module addsub (A, B, sel, C);
   parameter WIDTH = 8;
   input [WIDTH-1:0] A, B;
   input sel;
   output [WIDTH-1:0] C;

   reg [WIDTH-1:0]    C_reg;

   always @(*)
   begin
      if (sel == 0)
         C_reg = A + B;
      else
         C_reg = A - B;
   end

   assign C = C_reg;
endmodule

module register_counter_xor (
    input clk, 
    input reset,
    input [3:0] reg_data_in,
    input reg_load,
    input counter_enable,
    output [7:0] output_data
); 

reg [3:0] register_data;
reg [3:0] counter_data;
wire [7:0] xor_output;

// Register module
always @(posedge clk, negedge reset) begin
    if (!reset) begin
        register_data <= 4'b0;
    end else begin
        if (reg_load) begin
            register_data <= reg_data_in;
        end
    end
end

// Counter module
always @(posedge clk, negedge reset) begin
    if (!reset) begin
        counter_data <= 4'b0;
    end else begin
        if (counter_enable) begin
            counter_data <= counter_data + 1;
        end
    end
end

// XOR module
assign xor_output = {register_data, counter_data} ^ 8'b11111111;

// Output
assign output_data = xor_output;

endmodule

module cpu_mem(
  input rst,
  input clk,
  input cpu_stall,
  input ex_c_rfw,
  input [1:0] ex_c_wbsource,
  input [1:0] ex_c_drw,
  input [31:0] ex_alu_r,
  input [31:0] ex_rfb,
  input [4:0] ex_rf_waddr,
  input [31:0] ex_jalra,
  input [4:0] ex_rt,
  input [31:0] wb_wdata,
  output reg p_c_rfw,
  output reg [1:0] p_c_wbsource,
  output reg [31:0] p_alu_r,
  output [31:0] dmem_data,
  output reg [4:0] p_rf_waddr,
  output reg [31:0] p_jalra,
  output [31:0] dmem_addr,
  output [1:0] dmem_drw,
  input [31:0] dmem_in,
  output reg [31:0] p_dout
);

  assign dmem_addr = ex_alu_r;
  assign dmem_drw = ex_c_drw;

  always @(posedge clk) begin
    if (!cpu_stall) begin
      if (rst) begin
        p_c_rfw <= 0;
        p_c_wbsource <= 0;
        p_alu_r <= 0;
        p_rf_waddr <= 0;
        p_jalra <= 0;
        p_dout <= 0;
      end else begin
        p_c_rfw <= ex_c_rfw;
        p_c_wbsource <= ex_c_wbsource;
        p_alu_r <= ex_alu_r;
        p_rf_waddr <= ex_rf_waddr;
        p_jalra <= ex_jalra;
        p_dout <= dmem_in;
      end
    end
  end

  assign dmem_data = (p_c_rfw && (ex_rt == p_rf_waddr) && (p_rf_waddr != 0)) ? wb_wdata : ex_rfb;

endmodule

module cdc_reset_sync (
    input wire clk_in,
    input wire pulse_in,
    input wire clk_out,
    input wire aq_sync,
    output wire pulse_out
);

reg [1:0] in_pre_sync;
reg in_sync_pulse;

always @(posedge clk_in) begin
    in_pre_sync[0] <= pulse_in;
    in_pre_sync[1] <= in_pre_sync[0];
end

always @(posedge clk_in) begin
    if (in_pre_sync[1])
        in_sync_pulse <= 1;
    else if (aq_sync)
        in_sync_pulse <= 0;
end

reg out_sync_ff_1;
reg out_sync_ff_2;

always @(posedge clk_out) begin
    out_sync_ff_1 <= in_sync_pulse;
    out_sync_ff_2 <= out_sync_ff_1;
end

assign pulse_out = out_sync_ff_2;

endmodule

module can_transmitter (
  input wire data_in,
  input wire tx_en,
  input wire clk,
  output reg can_tx
);

reg [7:0] data_buffer;
reg [3:0] bit_counter;

always @(posedge clk) begin
  if (tx_en) begin
    if (bit_counter == 0) begin
      data_buffer <= data_in;
      bit_counter <= 4'b1000;
    end else begin
      can_tx <= data_buffer[7];
      data_buffer <= {data_buffer[6:0], 1'b0};
      bit_counter <= bit_counter - 1;
    end
  end
end

endmodule

module can_receiver (
  input wire can_rx,
  input wire rx_en,
  input wire clk,
  output reg data_out
);

reg [7:0] data_buffer;
reg [3:0] bit_counter;

always @(posedge clk) begin
  if (rx_en) begin
    if (bit_counter == 0) begin
      data_out <= data_buffer;
      bit_counter <= 4'b1000;
    end else begin
      data_buffer <= {can_rx, data_buffer[7:1]};
      bit_counter <= bit_counter - 1;
    end
  end
end

endmodule

module comparator (
  input [3:0] A,
  input [3:0] B,
  output EQ,
  output GT
);
  wire [3:0] diff;
  wire [3:0] not_diff;

  assign diff = A - B;
  assign not_diff = ~diff;

  assign EQ = &not_diff;
  assign GT = diff[3] & not_diff[3];
endmodule

module fifo_buffer
  (wr_clk, rd_clk, wr_en, rd_en, data_in, data_out, empty, full);

  parameter WIDTH = 5;
  parameter DEPTH = 32;

  input wr_clk;
  input rd_clk;
  input wr_en;
  input rd_en;
  input [WIDTH-1:0] data_in;
  output [WIDTH-1:0] data_out;
  output empty;
  output full;

  reg [WIDTH-1:0] buffer [0:DEPTH-1];
  reg [WIDTH-1:0] data_out_reg;
  reg [DEPTH-1:0] wr_ptr;
  reg [DEPTH-1:0] rd_ptr;
  reg empty_reg;
  reg full_reg;

  always @(posedge wr_clk) begin
    if (wr_en && !full_reg) begin
      buffer[wr_ptr] <= data_in;
      wr_ptr <= wr_ptr + 1;
      if (wr_ptr == DEPTH-1) begin
        wr_ptr <= 0;
      end
      if (wr_ptr == rd_ptr) begin
        full_reg <= 1;
      end
    end
  end

  always @(posedge rd_clk) begin
    if (rd_en && !empty_reg) begin
      data_out_reg <= buffer[rd_ptr];
      rd_ptr <= rd_ptr + 1;
      if (rd_ptr == DEPTH-1) begin
        rd_ptr <= 0;
      end
      if (rd_ptr == wr_ptr) begin
        empty_reg <= 1;
      end
    end
  end

  always @(posedge wr_clk or posedge rd_clk) begin
    empty <= empty_reg;
    full <= full_reg;
    data_out <= data_out_reg;
    if (wr_en && !full_reg) begin
      empty_reg <= 0;
    end
    if (rd_en && !empty_reg) begin
      full_reg <= 0;
    end
  end

endmodule

module dac(
  input clkin,
  input sysclk,
  input we,
  input[10:0] pgm_address,
  input[7:0] pgm_data,
  input play,
  input reset,
  output sdout,
  output lrck,
  output mclk,
  output DAC_STATUS
);

reg[8:0] dac_address_r;
wire[8:0] dac_address = dac_address_r;

wire[31:0] dac_data;
assign DAC_STATUS = dac_address_r[8];
reg[7:0] vol_reg;
reg[7:0] vol_target_reg;
reg[1:0] vol_latch_reg;
reg vol_valid;
reg[2:0] sysclk_sreg;
wire sysclk_rising = (sysclk_sreg[2:1] == 2'b01);

reg [25:0] interpol_count;

always @(posedge clkin) begin
  sysclk_sreg <= {sysclk_sreg[1:0], sysclk};
end

dac_buf snes_dac_buf (
  .clka(clkin),
  .wea(~we), // Bus [0 : 0]
  .addra(pgm_address), // Bus [10 : 0]
  .dina(pgm_data), // Bus [7 : 0]
  .clkb(clkin),
  .addrb(dac_address), // Bus [8 : 0]
  .doutb(dac_data)); // Bus [31 : 0]

reg [8:0] cnt;
reg [15:0] smpcnt;
reg [1:0] samples;
reg [15:0] smpshift;

assign mclk = cnt[2]; // mclk = clk/8
assign lrck = cnt[8]; // lrck = mclk/128
wire sclk = cnt[3];   // sclk = lrck*32

reg [2:0] lrck_sreg;
reg [2:0] sclk_sreg;
wire lrck_rising = ({lrck_sreg[2:1]} == 2'b01);
wire lrck_falling = ({lrck_sreg[2:1]} == 2'b10);

wire sclk_rising = ({sclk_sreg[2:1]} == 2'b01);

reg sdout_reg;
assign sdout = sdout_reg;

reg [1:0] reset_sreg;
wire reset_rising = (reset_sreg[1:0] == 2'b01);

reg play_r;

initial begin
  cnt = 9'h100;
  smpcnt = 16'b0;
  lrck_sreg = 2'b11;
  sclk_sreg = 1'b0;
  dac_address_r = 10'b0;
  vol_valid = 1'b0;
  vol_latch_reg = 1'b0;
  vol_reg = 8'h0;
  vol_target_reg = 8'hff;
  samples <= 2'b00;
end

always @(posedge clkin) begin
  if(reset_rising) begin
    dac_address_r <= 0;
    interpol_count <= 0;
  end else if(sysclk_rising) begin
    if(interpol_count > 59378938) begin
      interpol_count <= interpol_count + 122500 - 59501439;
      dac_address_r <= dac_address_r + play_r;
    end else begin
      interpol_count <= interpol_count + 122500;
    end
  end
end

always @(posedge clkin) begin
  cnt <= cnt + 1;
  lrck_sreg <= {lrck_sreg[1:0], lrck};
  sclk_sreg <= {sclk_sreg[1:0], sclk};
  play_r <= play;
  reset_sreg <= {reset_sreg[0], reset};
end

// ramp volume only every 4 samples
always @(posedge clkin) begin
  if (lrck_rising && &samples[1:0]) begin
    if(vol_reg > vol_target_reg)
      vol_reg <= vol_reg - 1;
    else if(vol_reg < vol_target_reg)
      vol_reg <= vol_reg + 1;
  end
end

always @(posedge clkin) begin
  if (lrck_rising) begin // right channel
    smpshift <= (({16'h0, dac_data[31:16]^16'h8000} * vol_reg) >> 8) ^ 16'h8000;
    samples <= samples + 1;
  end else if (lrck_falling) begin // left channel
    smpshift <= (({16'h0, dac_data[15:0]^16'h8000} * vol_reg) >> 8) ^ 16'h8000;
  end else begin
    if (sclk_rising) begin
      smpcnt <= smpcnt + 1;
      sdout_reg <= smpshift[15];
      smpshift <= {smpshift[14:0], 1'b0};
    end
  end
end

endmodule

module counter (
    input clk,
    input reset,
    input load,
    input [3:0] data,
    output reg [3:0] count
);

reg [3:0] count_reg1, count_reg2;
reg load_reg;

always @(posedge clk) begin
    if(reset) begin
        count_reg1 <= 4'b0;
        count_reg2 <= 4'b0;
        load_reg <= 1'b0;
    end
    else begin
        count_reg1 <= count_reg2;
        count_reg2 <= count;
        load_reg <= load;
    end
end

always @(*) begin
    if(load_reg) begin
        count <= data;
    end
    else begin
        count <= count_reg1 + 4'b1;
    end
end

endmodule

module up_down_counter (
    input clk,
    input reset,
    input up_down,    // Input to change the counting direction
    output reg [3:0] q
);

    reg [3:0] next_q;

    always @(posedge clk, negedge reset) begin
        if (!reset) begin
            q <= 4'b0000;
        end else begin
            if (up_down) begin
                next_q = q + 1;
            end else begin
                next_q = q - 1;
            end

            q <= next_q;
        end
    end

endmodule

module transition_detector (
    input clk,
    input reset,
    input data,
    output reg transition
);

    reg [3:0] prev_data;

    always @(posedge clk, negedge reset) begin
        if (!reset) begin
            prev_data <= 4'b0000;
            transition <= 1'b0;
        end else begin
            if (data > prev_data) begin
                transition <= 1'b0;
            end else if (data < prev_data) begin
                transition <= 1'b1;
            end

            prev_data <= data;
        end
    end

endmodule

module counter_direction (
    input clk,
    input reset,
    input [3:0] counter_output,
    input transition,
    output reg [3:0] q
);

    reg up_down;

    always @(posedge clk, negedge reset) begin
        if (!reset) begin
            up_down <= 1'b1;
            q <= 4'b0000;
        end else begin
            if (transition) begin
                up_down <= ~up_down;
            end

            if (up_down) begin
                q <= counter_output;
            end else begin
                q <= ~counter_output + 1;
            end
        end
    end

endmodule

module crystal_oscillator_interface (
  input crystal_signal,
  input reset,
  output out
);

  parameter CRYSTAL_FREQ = 100000000; // Default crystal frequency of 100 MHz
  parameter OUTPUT_FREQ = 1000000; // Default output frequency of 1 MHz

  reg [31:0] count = 0;
  reg out_reg = 0;
  wire clk;

  assign clk = crystal_signal / 2; // Divide crystal frequency by 2 to get clock frequency

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      count <= 0;
      out_reg <= 0;
    end else begin
      if (count == CRYSTAL_FREQ / (OUTPUT_FREQ * 2) - 1) begin
        count <= 0;
        out_reg <= ~out_reg;
      end else begin
        count <= count + 1;
      end
    end
  end

  assign out = out_reg;

endmodule

module glitch_filter (
  input clk,
  input in,
  output reg out
);

parameter delay_cycles = 10; // number of clock cycles to delay the input signal

// Define the delay element
reg [delay_cycles-1:0] delay_element;
always @(posedge clk)
  delay_element <= {delay_element[delay_cycles-2:0], in};

// Define the D flip-flop
always @(posedge clk)
  out <= delay_element[delay_cycles-1];

endmodule

