module PLL (
  input clk_in,
  input rst,
  input [1:0] freq_sel,
  output reg clk_out,
  output reg locked
);

  parameter DELAY = 10; // delay for the loop filter
  parameter MAX_COUNT = 100000; // maximum count for the lock detection

  reg [31:0] count; // counter for lock detection
  reg [31:0] phase_accumulator; // phase accumulator for the VCO
  reg [31:0] phase_accumulator_prev; // previous value of the phase accumulator
  reg [31:0] phase_difference; // phase difference between the external reference signal and the VCO output
  reg [31:0] phase_difference_filtered; // filtered phase difference
  reg [31:0] phase_difference_filtered_prev; // previous value of the filtered phase difference
  reg [31:0] vco_frequency; // frequency of the VCO
  reg [31:0] vco_frequency_prev; // previous value of the VCO frequency
  reg [31:0] vco_output; // output of the VCO
  reg [31:0] vco_output_divided; // output of the VCO divided by the frequency multiplication factor

  always @(posedge clk_in or posedge rst) begin
    if (rst) begin
      count <= 0;
      phase_accumulator <= 0;
      phase_accumulator_prev <= 0;
      phase_difference <= 0;
      phase_difference_filtered <= 0;
      phase_difference_filtered_prev <= 0;
      vco_frequency <= 0;
      vco_frequency_prev <= 0;
      vco_output <= 0;
      vco_output_divided <= 0;
      clk_out <= 0;
      locked <= 0;
    end else begin
      // calculate the phase difference between the external reference signal and the VCO output
      phase_difference <= phase_accumulator - (vco_frequency * (2 ** 32) / clk_in);

      // filter the phase difference
      phase_difference_filtered <= (phase_difference_filtered_prev * (DELAY - 1) + phase_difference) / DELAY;
      phase_difference_filtered_prev <= phase_difference_filtered;

      // adjust the VCO frequency based on the filtered phase difference
      vco_frequency <= vco_frequency_prev + (phase_difference_filtered * freq_sel);

      // calculate the VCO output
      vco_output <= phase_accumulator[31];

      // divide the VCO output by the frequency multiplication factor
      vco_output_divided <= vco_output / freq_sel;

      // update the phase accumulator
      phase_accumulator_prev <= phase_accumulator;
      phase_accumulator <= phase_accumulator_prev + (vco_frequency * (2 ** 32) / clk_in);

      // generate the output clock signal
      clk_out <= vco_output_divided[31];

      // detect lock
      if (count < MAX_COUNT) begin
        count <= count + 1;
        if (phase_difference_filtered < 100 && phase_difference_filtered > -100) begin
          locked <= 1;
        end else begin
          locked <= 0;
        end
      end else begin
        locked <= 0;
      end

      // update the VCO frequency and output
      vco_frequency_prev <= vco_frequency;
    end
  end

endmodule

