    input [3:0] data2, // Third data input for the multiplexer
    input [3:0] data3, // Fourth data input for the multiplexer
    input [3:0] data4, // Fifth data input for the multiplexer
    input [3:0] data5, // Sixth data input for the multiplexer
    output reg [3:0] mux_out, // Output from the multiplexer
    output reg [15:0] counter_out, // Output from the counter
    output reg [3:0] final_out // Output from the functional module
);

// Priority encoder for the multiplexer
wire [5:0] priority;
priority_encoder pe(sel, priority);

// Decoder for the multiplexer
wire [3:0] decoder_out;
decoder dec(priority, decoder_out);

// Multiplexer
always @ (sel or data0 or data1 or data2 or data3 or data4 or data5) begin
    case (decoder_out)
        0: mux_out <= data0;
        1: mux_out <= data1;
        2: mux_out <= data2;
        3: mux_out <= data3;
        4: mux_out <= data4;
        5: mux_out <= data5;
        default: mux_out <= 4'b0000;
    endcase
end

// Counter state machine
reg [1:0] state;
always @ (posedge clk, posedge reset) begin
    if (reset) begin
        state <= 2'b00;
        counter_out <= 16'b0000000000000000;
    end else begin
        case (state)
            2'b00: begin
                state <= 2'b01;
                counter_out <= counter_out + 1;
            end
            2'b01: begin
                state <= 2'b10;
            end
            2'b10: begin
                state <= 2'b11;
            end
            2'b11: begin
                state <= 2'b00;
            end
        endcase
    end
end

// Functional module
always @ (mux_out or counter_out) begin
    final_out <= mux_out + counter_out[3:0];
end

endmodule

