    always @ (posedge clk) begin
        if (reset) begin
            out <= 2'b00;
        end else begin
            case (priority_enc)
                4'b0001, 4'b0010, 4'b0011, 4'b0100:
                    out <= 2'b01;
                4'b0101, 4'b0110, 4'b0111, 4'b1000:
                    out <= 2'b10;
                4'b1001, 4'b1010, 4'b1011, 4'b1100, 4'b1101, 4'b1110, 4'b1111:
