module top_module (
    input clk,
    input reset,      // Asynchronous active-high reset
    input [7:0] d,
    output [3:0] counter_out,
    output [7:0] shift_reg_out,
    output [7:0] final_output
);

    // Circular shift register
    reg [7:0] shift_reg;
    always @(negedge clk) begin
        shift_reg <= {shift_reg[6:0], d};
    end
    assign shift_reg_out = shift_reg;

    // 4-bit binary counter
    reg [3:0] counter;
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 4'b1000;
        end else begin
            counter <= counter + 1;
        end
    end
    assign counter_out = counter;

    // Functional module to add shift_reg and counter
    reg [7:0] sum;
    always @(*) begin
        sum = shift_reg + counter;
    end
    assign final_output = sum;

endmodule

module booth_multiplier(
  input signed [2:0] x,
  input signed [2:0] y,
  input clk,
  output signed [5:0] z,
  output ready
);

  reg signed [5:0] a;
  reg signed [2:0] m;
  reg signed [2:0] q;
  reg [1:0] state;

  assign z = a;

  always @(posedge clk) begin
    case(state)
      2'b00: begin
        q <= {1'b0, y};
        m <= -x;
        state <= 2'b01;
      end
      2'b01: begin
        if(q[0] == 1) begin
          a <= a + m;
        end
        q <= q >> 1;
        m <= m << 1;
        state <= 2'b10;
      end
      2'b10: begin
        q <= {a[5], q[2:1]};
        if(state == 2'b10 && q == 3'b000) begin
          ready <= 1;
          state <= 2'b11;
        end else begin
          state <= 2'b01;
        end
      end
      2'b11: begin
        ready <= 0;
        state <= 2'b00;
      end
    endcase
  end

endmodule

module ADT7310 (
  input Reset_n_i,
  input Clk_i,
  input Enable_i,
  output CpuIntr_o,
  output ADT7310CS_n_o,
  input [7:0] SPI_Data_i,
  output SPI_Write_o,
  output SPI_ReadNext_o,
  output [7:0] SPI_Data_o,
  input SPI_FIFOFull_i,
  input SPI_FIFOEmpty_i,
  input SPI_Transmission_i,
  input [15:0] SPICounterPresetH_i,
  input [15:0] SPICounterPresetL_i,
  input [15:0] Threshold_i,
  input [15:0] PeriodCounterPreset_i,
  output [15:0] SensorValue_o,
  output SPI_CPOL_o,
  output SPI_CPHA_o,
  output SPI_LSBFE_o
);

  reg [15:0] command;
  reg [15:0] temperature_raw;
  reg [15:0] temperature_signed;
  reg [3:0] state;
  reg [7:0] byte_count;
  reg [7:0] spi_data_out;
  reg [7:0] spi_data_in;
  reg spi_write;
  reg spi_read_next;
  reg spi_busy;

  assign SPI_CPOL_o = 1'b1;
  assign SPI_CPHA_o = 1'b1;
  assign SPI_LSBFE_o = 1'b0;

  /* constant value for dynamic signal */ 
  assign ADT7310CS_n_o = 1'b1;

  always @(posedge Clk_i) begin
    if (Reset_n_i == 1'b0) begin
      state <= 4'b0000;
      byte_count <= 8'b00000000;
      spi_data_out <= 8'b00000000;
      spi_write <= 1'b0;
      spi_read_next <= 1'b0;
      spi_busy <= 1'b0;
      command <= 16'b0000000000000000;
      temperature_raw <= 16'b0000000000000000;
      temperature_signed <= 16'b0000000000000000;
      SensorValue_o <= 16'b0000000000000000;
    end else begin
      case (state)
        4'b0000: begin // idle state
          spi_write <= 1'b1;
          spi_data_out <= 8'b10000000;
          spi_busy <= 1'b1;
          state <= 4'b0001;
        end
        4'b0001: begin // sending command byte 1
          if (spi_busy == 1'b0) begin
            spi_data_out <= 8'b00000000;
            spi_write <= 1'b0;
            spi_busy <= 1'b1;
            state <= 4'b0010;
          end
        end
        4'b0010: begin // sending command byte 2
          if (spi_busy == 1'b0) begin
            spi_data_out <= 8'b00000000;
            spi_write <= 1'b0;
            spi_busy <= 1'b1;
            state <= 4'b0011;
          end
        end
        4'b0011: begin // waiting for temperature data
          if (spi_busy == 1'b0) begin
            spi_read_next <= 1'b1;
            spi_busy <= 1'b1;
            state <= 4'b0100;
          end
        end
        4'b0100: begin // receiving temperature byte 1
          if (spi_busy == 1'b0) begin
            temperature_raw[15:8] <= spi_data_in;
            spi_read_next <= 1'b1;
            spi_busy <= 1'b1;
            state <= 4'b0101;
          end
        end
        4'b0101: begin // receiving temperature byte 2
          if (spi_busy == 1'b0) begin
            temperature_raw[7:0] <= spi_data_in;
            spi_write <= 1'b1;
            spi_data_out <= 8'b00000000;
            spi_busy <= 1'b1;
            state <= 4'b0110;
          end
        end
        4'b0110: begin // converting temperature data
          temperature_signed[15] <= temperature_raw[15];
          temperature_signed[14:0] <= temperature_raw[14:0];
          SensorValue_o <= temperature_signed;
          state <= 4'b0000;
        end
      endcase
    end
  end

  assign SPI_Write_o = spi_write;
  assign SPI_ReadNext_o = spi_read_next;
  assign SPI_Data_o = spi_data_out;

endmodule

