module mem16k_tb;

    // Inputs
    reg clk_i;
    reg rst_i;
    reg [29:0] addr_i;
    reg write_en_i;
    reg [31:0] wdata_i;

    // Outputs
    wire [31:0] rdata_o;

    // Instantiate the Unit Under Test (UUT)
    mem16k uut (
        .clk_i(clk_i), 
        .rst_i(rst_i), 
        .addr_i(addr_i), 
        .write_en_i(write_en_i), 
        .wdata_i(wdata_i), 
        .rdata_o(rdata_o)
    );

    // Initialize Inputs
    initial begin
        clk_i = 0;
        forever #5 clk_i = ~clk_i;
        rst_i = 1;
        addr_i = 0;
        write_en_i = 0;
        wdata_i = 0;
        #20 rst_i = 0;
    end

    // Write data to memory location 0x0000
    initial begin
        addr_i = 0;
        write_en_i = 1;
        wdata_i = 32'hdeadbeef;
        #10;
        write_en_i = 0;
    end

    // Write data to memory location 0x1234
    initial begin
        addr_i = 32'h00001234;
        write_en_i = 1;
        wdata_i = 32'habcdef01;
        #10;
        write_en_i = 0;
    end

    // Write data to memory location 0x7fff
    initial begin
        addr_i = 32'h00007fff;
        write_en_i = 1;
        wdata_i = 32'h87654321;
        #10;
        write_en_i = 0;
    end

    // Read data from memory location 0x0000 and verify that it matches the first data written
    initial begin
        addr_i = 0;
        write_en_i = 0;
        #10;
        if (rdata_o !== 32'hdeadbeef) begin
            $display("Error: Data read from memory location 0x0000 does not match expected value.");
        end
    end

    // Read data from memory location 0x1234 and verify that it matches the second data written
    initial begin
        addr_i = 32'h00001234;
        write_en_i = 0;
        #10;
        if (rdata_o !== 32'habcdef01) begin
            $display("Error: Data read from memory location 0x1234 does not match expected value.");
        end
    end

    // Read data from memory location 0x7fff and verify that it matches the third data written
    initial begin
        addr_i = 32'h00007fff;
        write_en_i = 0;
        #10;
        if (rdata_o !== 32'h87654321) begin
            $display("Error: Data read from memory location 0x7fff does not match expected value.");
        end
    end

endmodule

