            GrayCount_out <= 4'b0000;
        end
        else if (Enable_in) begin
            BinaryCount <= BinaryCount + 1;
            GrayCount_out <= {BinaryCount[3], BinaryCount[3] ^ BinaryCount[2], BinaryCount[2] ^ BinaryCount[1], BinaryCount[1] ^ BinaryCount[0]};
        end
    end
