module mod_operator (
  input [31:0] A, 
  input [31:0] B, 
  output reg [31:0] result
);

  always @(*) begin
    if (B == 0) begin
      result = 0;
    end else if (A < B) begin
      result = A;
    end else begin
      result = A;
      while (result >= B) begin
        result = result - B;
      end
    end
  end

endmodule

module fifo_buffer (
  input clk,
  input rd,
  input reset_n,
  input wr,
  input [61:0] wr_data,
  output almost_empty,
  output almost_full,
  output empty,
  output full,
  output [61:0] rd_data
);

  wire almost_empty;
  wire almost_full;
  wire empty;
  wire full;
  wire [61:0] rd_data;
  reg [1:0] entries;
  reg [61:0] entry_0;
  reg [61:0] entry_1;
  reg rd_address;
  reg wr_address;
  wire [1:0] rdwr;

  assign rdwr = {rd, wr};
  assign full = entries == 2;
  assign empty = entries == 0;
  assign almost_full = entries == 1 || entries == 2;
  assign almost_empty = entries == 0 || entries == 1;

  always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
      entries <= 0;
      rd_address <= 0;
      wr_address <= 0;
    end else begin
      case (rdwr)
        2'b01: begin // read
          if (entries > 0) begin
            entries <= entries - 1;
            rd_address <= ~rd_address;
          end
        end
        2'b10: begin // write
          if (entries < 2) begin
            entries <= entries + 1;
            wr_address <= ~wr_address;
            if (wr_address == 0) begin
              entry_0 <= wr_data;
            end else begin
              entry_1 <= wr_data;
            end
          end
        end
        2'b11: begin // read and write
          if (entries < 2) begin
            entries <= entries + 1;
            wr_address <= ~wr_address;
            if (wr_address == 0) begin
              entry_0 <= wr_data;
            end else begin
              entry_1 <= wr_data;
            end
          end
          if (entries > 0) begin
            entries <= entries - 1;
            rd_address <= ~rd_address;
          end
        end
      endcase
    end
  end

  always @(posedge clk) begin
    if (rd_address == 0) begin
      rd_data <= entry_0;
    end else begin
      rd_data <= entry_1;
    end
  end

endmodule

module shift_register(
    input clk,
    input rst,
    input load,
    input shift,
    input [7:0] din,
    output [7:0] parallel_out,
    output serial_out
);

    reg [7:0] shift_reg;
    reg [7:0] parallel_out_reg;
    reg serial_out_reg;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            shift_reg <= 8'b0;
            parallel_out_reg <= 8'b0;
            serial_out_reg <= 1'b0;
        end
        else begin
            if (load) begin
                shift_reg <= din;
                parallel_out_reg <= din;
            end
            else if (shift) begin
                shift_reg <= {shift_reg[6:0], 1'b0};
                parallel_out_reg <= shift_reg;
                serial_out_reg <= shift_reg[7];
            end
            else begin
                parallel_out_reg <= shift_reg;
                serial_out_reg <= shift_reg[7];
            end
        end
    end

    assign parallel_out = parallel_out_reg;
    assign serial_out = serial_out_reg;

endmodule

module booth_multiplier (
  input signed [3:0] a,
  input signed [3:0] b,
  output signed [7:0] c
);

  wire signed [7:0] p;
  reg signed [7:0] ac;
  reg [3:0] count;
  reg done;

  assign p = {a, 4'b0} + ({~a[3], a[3:0]} << 4) + ({~b[3], b[3:0]} << 8);

  always @(posedge clk) begin
    if (reset) begin
      ac <= 8'b0;
      count <= 4'b0;
      done <= 1'b0;
    end else begin
      if (count == 4'b1000) begin
        done <= 1'b1;
      end else begin
        if (p[0] == 1 && ac[7:0] < 0) begin
          ac <= ac + p;
        end else if (p[0] == 0 && ac[7:0] >= 0) begin
          ac <= ac - p;
        end
        ac <= ac >> 1;
        count <= count + 1;
      end
    end
  end

  assign c = ac;

endmodule

