module addsub_4bit (
    input [3:0] A,
    input [3:0] B,
    input C,
    output reg [3:0] S
);

    wire [3:0] carry;
    wire [3:0] sum;

    // Full adders for each bit
    sky130_fd_sc_hd__fulladder fa0(.a(A[0]), .b(B[0]), .cin(C), .sum(sum[0]), .cout(carry[0]));
    sky130_fd_sc_hd__fulladder fa1(.a(A[1]), .b(B[1]), .cin(carry[0]), .sum(sum[1]), .cout(carry[1]));
    sky130_fd_sc_hd__fulladder fa2(.a(A[2]), .b(B[2]), .cin(carry[1]), .sum(sum[2]), .cout(carry[2]));
    sky130_fd_sc_hd__fulladder fa3(.a(A[3]), .b(B[3]), .cin(carry[2]), .sum(sum[3]), .cout(carry[3]));

    // XOR gate for subtracting
    sky130_fd_sc_hd__xor2 xor0(.A(B), .B(4'hF), .Z(B_sub));
    sky130_fd_sc_hd__inverter inv0(.A(C), .Z(C_inv));

    // Select sum or difference
    always @(*) begin
        if(C_inv) begin
            S = sum;
        end else begin
            S = B_sub;
        end
    end

endmodule

