module memory_module(
    input clk,
    input en,
    input rst,
    input [10:0] addr,
    input [15:0] din,
    input we,
    output [15:0] dout
);

  wire [15:0] douta;
  wire [15:0] doutb;
  wire [10:0] addra = addr;
  wire [10:0] addrb = addr;
  wire clka = clk;
  wire clkb = clk;
  wire [15:0] dina = din;
  wire [15:0] dinb = din;
