    reg [1:0] selection; // selected item
    reg [7:0] cost; // cost of selected item
    reg [7:0] total; // total amount of money inserted
    reg [7:0] change; // amount of change to be returned
    reg [11:0] quarters; // number of quarters inserted
    reg [11:0] dimes; // number of dimes inserted
    reg [11:0] nickels; // number of nickels inserted

    // seven-segment decoder instances
    sevensegdecoder_always S0 (.digit(nickel_counter[3:0]), .drivers(HEX0));
    sevensegdecoder_always S1 (.digit(nickel_counter[7:4]), .drivers(HEX1));
    sevensegdecoder_always S2 (.digit(dime_counter[3:0]), .drivers(HEX2));
    sevensegdecoder_always S3 (.digit(dime_counter[7:4]), .drivers(HEX3));
    sevensegdecoder_always S4 (.digit(quarter_counter[3:0]), .drivers(HEX4));
    sevensegdecoder_always S5 (.digit(quarter_counter[7:4]), .drivers(HEX5));

    // state machine states
    parameter IDLE = 2'b00;
    parameter COIN_INSERTED = 2'b01;
    parameter ITEM_SELECTED = 2'b10;

    always @(posedge clock) begin
        if (reset) begin
            state <= IDLE;
            selection <= 0;
            cost <= 0;
            total <= 0;
            change <= 0;
            quarters <= 0;
            dimes <= 0;
            nickels <= 0;
            quarter_counter <= 0;
            dime_counter <= 0;
            nickel_counter <= 0;
            dimenickelLEDon <= 0;
            dimeLEDon <= 0;
            nickelLEDon <= 0;
            vendLEDon <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (enable) begin
                        state <= COIN_INSERTED;
                    end
                end
                COIN_INSERTED: begin
                    case (coin)
                        2'b00: begin // nickel
                            nickels <= nickels + 1;
                            total <= total + 5;
                            nickelLEDon <= 1;
                        end
                        2'b01: begin // dime
                            dimes <= dimes + 1;
                            total <= total + 10;
                            dimeLEDon <= 1;
                        end
                        2'b10: begin // quarter
                            quarters <= quarters + 1;
                            total <= total + 25;
                            quarter_counter <= quarter_counter + 1;
                        end
                    endcase
                    state <= ITEM_SELECTED;
                end
                ITEM_SELECTED: begin
                    if (mode == 0) begin // selection A
                        selection <= 1;
                        cost <= A_PRICE;
                    end else begin // selection B
                        selection <= 2;
                        cost <= B_PRICE;
                    end
                    if (total >= cost) begin
                        change <= total - cost;
                        vendLEDon <= 1;
                        case (selection)
                            1: begin // dispense selection A
                                // reduce inventory
                            end
                            2: begin // dispense selection B
                                // reduce inventory
                            end
                        endcase
                        // reset counters
                        quarters <= 0;
                        dimes <= 0;
                        nickels <= 0;
                        quarter_counter <= 0;
                        dime_counter <= 0;
                        nickel_counter <= 0;
                        dimenickelLEDon <= 0;
                        dimeLEDon <= 0;
                        nickelLEDon <= 0;
                        // return change
                        total <= 0;
                        state <= IDLE;
                    end else begin
                        state <= COIN_INSERTED;
                    end
                end
            endcase
            // update counters
            quarter_counter <= quarters;
            dime_counter <= dimes;
            nickel_counter <= nickels;
            // update LED outputs
            if (dimes > 0 && nickels > 0) begin
                dimenickelLEDon <= 1;
            end else begin
                dimenickelLEDon <= 0;
            end
            if (dimes > 0) begin
                dimeLEDon <= 1;
            end else begin
                dimeLEDon <= 0;
            end
            if (nickels > 0) begin
                nickelLEDon <= 1;
            end else begin
                nickelLEDon <= 0;
            end
        end
    end

