module spi_state_machine (
  input clk,
  input rst,
  input sdo,
  input csb,
  input sdi,
  output sck,
  output mosi,
  output miso
);

  // Define states
  parameter IDLE = 2'b00;
  parameter TX = 2'b01;
  parameter RX = 2'b10;
  parameter DONE = 2'b11;

  // Define SPI modes
  parameter CPOL0_CPHA0 = 2'b00;
  parameter CPOL0_CPHA1 = 2'b01;
  parameter CPOL1_CPHA0 = 2'b10;
  parameter CPOL1_CPHA1 = 2'b11;

  // Define variables
  reg [1:0] state;
  reg [1:0] spi_mode;
  reg [7:0] tx_data;
  reg [7:0] rx_data;
  reg mosi_out;
  reg sck_out;
  reg miso_out;
  reg [3:0] bit_counter;

  // Initialize variables
  initial begin
    state = IDLE;
    spi_mode = CPOL0_CPHA0;
    tx_data = 8'b0;
    rx_data = 8'b0;
    mosi_out = 1'b0;
    sck_out = 1'b0;
    miso_out = 1'b0;
    bit_counter = 4'b0;
  end

  // State machine
  always @(posedge clk) begin
    if (rst) begin
      state <= IDLE;
      spi_mode <= CPOL0_CPHA0;
      tx_data <= 8'b0;
      rx_data <= 8'b0;
      mosi_out <= 1'b0;
      sck_out <= 1'b0;
      miso_out <= 1'b0;
      bit_counter <= 4'b0;
    end
    else begin
      case (state)
        IDLE: begin
          if (!csb) begin
            state <= TX;
            mosi_out <= tx_data[7];
            sck_out <= spi_mode[0] ? 1'b1 : 1'b0;
            bit_counter <= 4'b1;
          end
          else begin
            sck_out <= 1'b0;
            miso_out <= 1'b0;
          end
        end
        TX: begin
          mosi_out <= tx_data[7-bit_counter];
          sck_out <= ~sck_out;
          bit_counter <= bit_counter + 1;
          if (bit_counter == 4) begin
            state <= RX;
            bit_counter <= 4'b0;
          end
        end
        RX: begin
          miso_out <= sdi;
          sck_out <= ~sck_out;
          rx_data <= {rx_data[6:0], sdi};
          bit_counter <= bit_counter + 1;
          if (bit_counter == 4) begin
            state <= DONE;
            bit_counter <= 4'b0;
          end
        end
        DONE: begin
          sck_out <= spi_mode[0] ? 1'b1 : 1'b0;
          miso_out <= 1'b0;
          if (csb) begin
            state <= IDLE;
            tx_data <= 8'b0;
            rx_data <= {rx_data[6:0], sdi};
          end
        end
      endcase
    end
  end

  // Assign outputs
  assign sck = sck_out;
  assign mosi = mosi_out;
  assign miso = miso_out;

endmodule

