module fifo(
    input clk_i, 
    input rst_i, 
    input [31:0] dat_i, 
    input wr_i, 
    input rd_i, 
    output reg [31:0] dat_o, 
    output reg full_o, 
    output reg empty_o
);

parameter depth = 128; // FIFO depth
parameter dw = 32; // Data width
reg [dw-1:0] mem [depth-1:0]; // Memory array
reg [6:0] wr_ptr = 0; // Write pointer
reg [6:0] rd_ptr = 0; // Read pointer
reg [6:0] count = 0; // Number of entries in FIFO

// Write logic
always @(posedge clk_i) begin
    if (rst_i) begin
        wr_ptr <= 0;
        count <= 0;
        full_o <= 0;
        empty_o <= 1;
    end else if (wr_i && !full_o) begin
        mem[wr_ptr] <= dat_i;
        wr_ptr <= (wr_ptr == depth-1) ? 0 : wr_ptr + 1;
        count <= count + 1;
        if (count == depth) full_o <= 1;
        empty_o <= 0;
    end
end

// Read logic
always @(posedge clk_i) begin
    if (rst_i) begin
        rd_ptr <= 0;
        count <= 0;
        full_o <= 0;
        empty_o <= 1;
    end else if (rd_i && !empty_o) begin
        dat_o <= mem[rd_ptr];
        rd_ptr <= (rd_ptr == depth-1) ? 0 : rd_ptr + 1;
        count <= count - 1;
        if (count == 1) empty_o <= 1;
        full_o <= 0;
    end
end

endmodule

module sync_resettable_latch (
    input [4:0] A,
    input D,
    input CLK,
    input CE,
    output reg Q,
    output reg Q31
);

    parameter [31:0] INIT = 32'h00000000;
    parameter [0:0] IS_CLK_INVERTED = 1'b0;

    reg [31:0] reg_data;

    always @(posedge CLK or negedge CE) begin
        if (!IS_CLK_INVERTED) begin
            if (!CE) begin
                reg_data <= INIT;
            end else begin
                reg_data[A] <= D;
            end
        end else begin
            if (!CE) begin
                reg_data <= INIT;
            end else begin
                reg_data[31-A] <= D;
            end
        end
    end

    assign Q = reg_data[A];
    assign Q31 = reg_data[31];

endmodule

