);

  reg [15:0] shift_reg;
  reg [15:0] output_reg;

  initial begin
    shift_data = 16'h0000;
    serial_data = 16'h0000;
  end

  always @(posedge clk) begin
    if (reset == 1'b1) begin
      shift_reg <= 16'h0000;
      output_reg <= 16'h0000;
    end
    else if (parallel_load == 1'b1) begin
      shift_reg <= data;
      output_reg <= data;
    end
    else begin
      if (direction == 1'b1) begin
        shift_reg <= {shift_reg[14:0], output_reg[15]};
        output_reg <= {output_reg[14:0], shift_reg[15]};
      end
      else begin
        shift_reg <= {output_reg[0], shift_reg[15:1]};
        output_reg <= {shift_reg[0], output_reg[15:1]};
      end
    end
    shift_data <= shift_reg;
    serial_data <= shift_reg[0];
  end

endmodule

