module timer #(
    parameter TIMER_CYCLE_MS = 100, // default cycle time in milliseconds
    parameter CLK_SYS_HZ = 50e6 // default system clock frequency
)(
    input clk_sys, // system clock
    input enable, // enable signal
    input reset, // reset signal
    output reg pulse // output pulse signal
);

    localparam TIMER_COUNT = TIMER_CYCLE_MS * CLK_SYS_HZ / 1000; // number of clock cycles in one timer cycle

    reg [31:0] count; // counter to keep track of clock cycles

    always @(posedge clk_sys) begin
        if (reset) begin
            count <= 0;
            pulse <= 0;
        end else if (enable) begin
            count <= count + 1;
            if (count == TIMER_COUNT - 1) begin
                pulse <= 1;
                count <= 0;
            end else begin
                pulse <= 0;
            end
        end else begin
            pulse <= 0;
        end
    end

endmodule

