module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    output [3:0] S,
    output C_out
);

    wire [3:0] C;
    wire [3:0] P;

    // First stage of the adder
    full_adder FA0 (
        .A(A[0]),
        .B(B[0]),
        .Cin(1'b0),
        .S(S[0]),
        .Cout(C[0])
    );

    // Second stage of the adder
    full_adder FA1 (
        .A(A[1]),
        .B(B[1]),
        .Cin(C[0]),
        .S(S[1]),
        .Cout(C[1])
    );

    // Third stage of the adder
    full_adder FA2 (
        .A(A[2]),
        .B(B[2]),
        .Cin(C[1]),
        .S(S[2]),
        .Cout(C[2])
    );

    // Fourth stage of the adder
    full_adder FA3 (
        .A(A[3]),
        .B(B[3]),
        .Cin(C[2]),
        .S(S[3]),
        .Cout(C_out)
    );

    // Generate the carry-out bit for the final stage
    sky130_fd_sc_ls__nand3_1 NAND (
        .Y(P[0]),
        .A(C[2]),
        .B(C[1]),
        .C(C[0]),
        .VPWR(1'b1),
        .VGND(1'b0),
        .VPB(1'b0),
        .VNB(1'b0)
    );

    // Propagate the carry-out bit through the final stage
    assign P[1] = C[3] & P[0];
    assign P[2] = P[0] & C[2];
    assign P[3] = P[0] & C[1];

    // Generate the final carry-out bit
    assign C_out = P[3] | P[2] | P[1] | (C[3] & C[2] & C[1]);

endmodule

