module AccumulateQueue #(
    parameter A_BITS = 32,
    parameter FIFO_LENGTH = 8,

    /* Number of bits needed to index into the queue */
    parameter INDEX_BITS = $clog2(FIFO_LENGTH)
) (
    input clock,
    input reset,

    input stall,

    input [A_BITS-1:0] a_in,

    output reg [A_BITS-1:0] a_out
);
    /*
    The accumulation queue stores the results of the systolic array and adds
    it to previous partial products.

    In particular, on each cycle we read the previous partial product from
    the end of the fifo and add the value emitted from systolic array.
    Then, on the next cycle we write the value to the front of the queue.

    The way this is actually implemented is that we have two SRAMs - odd and
    even. When the index is even, we write last cycle's partial product to the
    even queue, and read the next partial product from the odd queue.

    This is reversed when the index is odd.
    */
    reg [A_BITS-1:0] fifo_e [0:(FIFO_LENGTH/2)-1];
    reg [A_BITS-1:0] fifo_o [0:(FIFO_LENGTH/2)-1];
    reg [A_BITS-1:0] head;
    reg [INDEX_BITS-1:0] index;

    /* Set the fifo to zero on reset */
    integer i;
    always @(posedge clock) begin
        if (reset) begin
            for (i = 0; i < FIFO_LENGTH; i = i + 1) begin
                fifo_e[i] <= {A_BITS{1'b0}};
                fifo_o[i] <= {A_BITS{1'b0}};
            end

            head  <= {A_BITS{1'b0}};
            index <= {INDEX_BITS{1'b0}};
        end
    end

    /* The next index is just the current index + 1 */
    wire [INDEX_BITS-1:0] index_next = index + 1;

    /* The fifo index is just the top INDEX_BITS-1 bits */
    wire [INDEX_BITS-2:0] fifo_index = index[INDEX_BITS-1:1];
    wire [INDEX_BITS-2:0] fifo_index_next = index_next[INDEX_BITS-1:1];

    /* Index is odd if the last bit is 1 */
    wire odd = index[0];

    always @(posedge clock) begin
        if (!reset && !stall) begin
            if (odd) begin
                /* If odd, write to the odd queue... */
                fifo_o[fifo_index] <= head + a_in;

                /* ...and read from the even queue */
                head <= fifo_e[fifo_index_next];
            end else begin
                /* If even, write to the even queue... */
                fifo_e[fifo_index] <= head + a_in;

                /* ...and read from the odd queue */
                head <= fifo_o[fifo_index_next];
            end

            index <= index_next;
        end
    end

    /* Output is just the head of the queue */
    assign a_out = head;
endmodule

module carry_lookahead_adder (
    input [7:0] a,
    input [7:0] b,
    output [7:0] s,
    output overflow
);

wire [7:0] g;
wire [7:0] p;
wire [7:0] c;

assign g = a & b;
assign p = a ^ b;
assign c[0] = 1'b0;

genvar i;
generate
    for (i = 0; i < 8; i = i + 1) begin
        assign c[i+1] = g[i] | (p[i] & c[i]);
        assign s[i] = p[i] ^ c[i];
    end
endgenerate

assign overflow = ((a[7] == b[7]) && (a[7] != s[7]));

endmodule

module top_module (
    input [7:0] a,
    input [7:0] b,
    output [7:0] s,
    output overflow,
    output result
);

wire [7:0] sum;
wire overflow_signal;

carry_lookahead_adder adder(a, b, sum, overflow_signal);

assign result = ((sum[7] == 1 && overflow_signal == 0) || (sum[7] == 0 && overflow_signal == 1)) ? 1'b0 : 1'b1;

assign s = sum;
assign overflow = overflow_signal;

endmodule

module rx_DS_char(
    input rxClk, rxReset,
    input [1:0] d,
    input dv,
    output reg [7:0] q,
    output reg nchar,
    output reg lchar,
    output reg parityError
);

reg [7:0] dataReg;
reg [7:0] parityReg;
reg [2:0] bitCount;
reg [1:0] lastData;
reg [1:0] lastParity;
reg [1:0] lastBitCount;

parameter IDLE = 2'b00;
parameter DATA = 2'b01;
parameter PARITY = 2'b10;
parameter STOP = 2'b11;

reg [1:0] state = IDLE;

always @(posedge rxClk) begin
    if (rxReset) begin
        state <= IDLE;
        dataReg <= 8'b0;
        parityReg <= 8'b0;
        bitCount <= 3'b0;
        lastData <= 2'b0;
        lastParity <= 2'b0;
        lastBitCount <= 2'b0;
        q <= 8'b0;
        nchar <= 1'b0;
        lchar <= 1'b0;
        parityError <= 1'b0;
    end else begin
        case (state)
            IDLE: begin
                if (dv && d[1]) begin
                    state <= DATA;
                    dataReg <= 8'b0;
                    bitCount <= 3'b0;
                    lastData <= d;
                end
            end
            DATA: begin
                dataReg[bitCount+2] <= d[1];
                bitCount <= bitCount + 1;
                lastData <= d;
                if (bitCount == 3) begin
                    state <= PARITY;
                    parityReg <= {1'b0, d[0], dataReg[7:1]} ^ 8'b11111111;
                    bitCount <= 3'b0;
                end
            end
            PARITY: begin
                parityReg[bitCount+1] <= d[1];
                bitCount <= bitCount + 1;
                lastParity <= d;
                if (bitCount == 3) begin
                    state <= STOP;
                    bitCount <= 3'b0;
                end
            end
            STOP: begin
                if (d[1] && lastData == 2'b11 && lastParity == 2'b11) begin
                    if (parityReg == 8'b0) begin
                        q <= dataReg;
                        nchar <= (dataReg == 8'h00);
                        lchar <= ((dataReg >= 8'h41 && dataReg <= 8'h5A) || (dataReg >= 8'h61 && dataReg <= 8'h7A));
                        parityError <= 1'b0;
                    end else begin
                        parityError <= 1'b1;
                    end
                    state <= IDLE;
                end
                lastBitCount <= bitCount;
            end
        endcase
    end
end

endmodule

module four_to_one(
    input in1,
    input in2,
    input in3,
    input in4,
    output out
);

    wire all_ones = (in1 & in2 & in3 & in4);
    wire all_zeros = (~in1 & ~in2 & ~in3 & ~in4);

    assign out = all_ones | all_zeros;

endmodule

module LED_Segment_Mapper
(
	// Control Signals
	input LED_ENABLE_1,
	input LED_ENABLE_2,

	// LED Data Signals
	input [15:0] LED_DATA_1,
	input [15:0] LED_DATA_2,

	// Output Signals
	output [6:0] HEX0,
	output [6:0] HEX1,
	output [6:0] HEX2,
	output [6:0] HEX3,
	output [6:0] HEX4,
	output [6:0] HEX5,

	// System Signals
	input CLK
);

	//
	// LED Output Registers
	//
	reg [15:0] led_out_reg;

	initial
	begin
		led_out_reg = 16'hFFFF;
	end

	always @(posedge CLK)
	begin
		led_out_reg[ 0] <= ~( (LED_ENABLE_1 & LED_DATA_1[ 0]) | (LED_ENABLE_2 & LED_DATA_2[ 0]) );
		led_out_reg[ 1] <= ~( (LED_ENABLE_1 & LED_DATA_1[ 1]) | (LED_ENABLE_2 & LED_DATA_2[ 1]) );
		led_out_reg[ 2] <= ~( (LED_ENABLE_1 & LED_DATA_1[ 2]) | (LED_ENABLE_2 & LED_DATA_2[ 2]) );
		led_out_reg[ 3] <= ~( (LED_ENABLE_1 & LED_DATA_1[ 3]) | (LED_ENABLE_2 & LED_DATA_2[ 3]) );
		led_out_reg[ 4] <= ~( (LED_ENABLE_1 & LED_DATA_1[ 4]) | (LED_ENABLE_2 & LED_DATA_2[ 4]) );
		led_out_reg[ 5] <= ~( (LED_ENABLE_1 & LED_DATA_1[ 5]) | (LED_ENABLE_2 & LED_DATA_2[ 5]) );
		led_out_reg[ 6] <= ~( (LED_ENABLE_1 & LED_DATA_1[ 6]) | (LED_ENABLE_2 & LED_DATA_2[ 6]) );
		led_out_reg[ 7] <= ~( (LED_ENABLE_1 & LED_DATA_1[ 7]) | (LED_ENABLE_2 & LED_DATA_2[ 7]) );
		led_out_reg[ 8] <= ~( (LED_ENABLE_1 & LED_DATA_1[ 8]) | (LED_ENABLE_2 & LED_DATA_2[ 8]) );
		led_out_reg[ 9] <= ~( (LED_ENABLE_1 & LED_DATA_1[ 9]) | (LED_ENABLE_2 & LED_DATA_2[ 9]) );
		led_out_reg[10] <= ~( (LED_ENABLE_1 & LED_DATA_1[10]) | (LED_ENABLE_2 & LED_DATA_2[10]) );
		led_out_reg[11] <= ~( (LED_ENABLE_1 & LED_DATA_1[11]) | (LED_ENABLE_2 & LED_DATA_2[11]) );
		led_out_reg[12] <= ~( (LED_ENABLE_1 & LED_DATA_1[12]) | (LED_ENABLE_2 & LED_DATA_2[12]) );
		led_out_reg[13] <= ~( (LED_ENABLE_1 & LED_DATA_1[13]) | (LED_ENABLE_2 & LED_DATA_2[13]) );
		led_out_reg[14] <= ~( (LED_ENABLE_1 & LED_DATA_1[14]) | (LED_ENABLE_2 & LED_DATA_2[14]) );
		led_out_reg[15] <= ~( (LED_ENABLE_1 & LED_DATA_1[15]) | (LED_ENABLE_2 & LED_DATA_2[15]) );
	end


	//
	// 7-Segment Display Mapping
	//
	// Map the 16 LED Output Signals to the 
	//  outer LED segments of the 7-Segment Display
	//	
	assign HEX3[0] = led_out_reg[ 0];
	assign HEX4[0] = led_out_reg[ 1];
	assign HEX5[0] = led_out_reg[ 2];
	assign HEX5[5] = led_out_reg[ 3];
	assign HEX5[4] = led_out_reg[ 4];
	assign HEX5[3] = led_out_reg[ 5];
	assign HEX4[3] = led_out_reg[ 6];
	assign HEX3[3] = led_out_reg[ 7];
	assign HEX2[3] = led_out_reg[ 8];
	assign HEX1[3] = led_out_reg[ 9];
	assign HEX0[3] = led_out_reg[10];
	assign HEX0[2] = led_out_reg[11];
	assign HEX0[1] = led_out_reg[12];
	assign HEX0[0] = led_out_reg[13];
	assign HEX1[0] = led_out_reg[14];	
	assign HEX2[0] = led_out_reg[15];


	//
	// Unused Segment Assignments
	//
	// This segment LEDs will not be used to leave turned off.
	// NOTE: The compiler will generate warnings about these signals
	//       begin tied to GND. Those warnings can be ignored.
	//
	assign HEX0[6:4] = ~3'h0;
	assign HEX1[2:1] = ~2'h0;
	assign HEX1[6:4] = ~3'h0;
	assign HEX2[2:1] = ~2'h0;
	assign HEX2[6:4] = ~3'h0;
	assign HEX3[2:1] = ~2'h0;
	assign HEX3[6:4] = ~3'h0;
	assign HEX4[2:1] = ~2'h0;
	assign HEX4[6:4] = ~3'h0;
	assign HEX5[2:1] = ~2'h0;
	assign HEX5[6] = ~1'b0;

endmodule

module alu(
    input [19:0] opcode_inputs,
    input reset_in,
    input clk,
    output reg [7:0] final_output,
    output reg carry_output,
    output reg zero_flag
);

    reg [7:0] a, b;
    reg [3:0] opcode;
    reg [7:0] temp;
    reg [8:0] shift_amount;
    reg [7:0] mask;

    always @(posedge clk) begin
        if (reset_in) begin
            final_output <= 0;
            carry_output <= 0;
            zero_flag <= 0;
            a <= 0;
            b <= 0;
            opcode <= 0;
            temp <= 0;
            shift_amount <= 0;
            mask <= 0;
        end else begin
            opcode <= opcode_inputs[19:16];
            a <= opcode_inputs[15:8];
            b <= opcode_inputs[7:0];

            case (opcode)
                4'b0000: begin // Addition
                    temp <= a + b;
                    carry_output <= (temp > 8'hFF);
                    final_output <= temp;
                    zero_flag <= (temp == 0);
                end
                4'b0001: begin // Subtraction
                    temp <= a - b;
                    carry_output <= (a < b);
                    final_output <= temp;
                    zero_flag <= (temp == 0);
                end
                4'b0010: begin // Bitwise AND
                    final_output <= a & b;
                    carry_output <= 0;
                    zero_flag <= (final_output == 0);
                end
                4'b0011: begin // Bitwise OR
                    final_output <= a | b;
                    carry_output <= 0;
                    zero_flag <= (final_output == 0);
                end
                4'b0100: begin // Bitwise XOR
                    final_output <= a ^ b;
                    carry_output <= 0;
                    zero_flag <= (final_output == 0);
                end
                4'b0101: begin // Left shift A by B bits
                    shift_amount <= b;
                    mask <= {8'd0, {shift_amount}};
                    final_output <= a << shift_amount;
                    carry_output <= (final_output > 8'hFF);
                    final_output <= final_output & 8'hFF;
                    zero_flag <= (final_output == 0);
                end
                4'b0110: begin // Right shift A by B bits
                    shift_amount <= b;
                    mask <= {shift_amount, 8'd0};
                    final_output <= a >> shift_amount;
                    carry_output <= (final_output > 8'hFF);
                    zero_flag <= (final_output == 0);
                end
                4'b0111: begin // Rotate left A by B bits
                    shift_amount <= b;
                    mask <= {8'd0, {shift_amount}};
                    final_output <= {a << shift_amount, a >> (8 - shift_amount)};
                    carry_output <= (final_output > 8'hFF);
                    final_output <= final_output & 8'hFF;
                    zero_flag <= (final_output == 0);
                end
                4'b1000: begin // Rotate right A by B bits
                    shift_amount <= b;
                    mask <= {shift_amount, 8'd0};
                    final_output <= {a >> shift_amount, a << (8 - shift_amount)};
                    carry_output <= (final_output > 8'hFF);
                    final_output <= final_output & 8'hFF;
                    zero_flag <= (final_output == 0);
                end
                4'b1001: begin // Zero test
                    final_output <= 0;
                    carry_output <= 0;
                    zero_flag <= (a == 0);
                end
                4'b1010: begin // Greater than
                    final_output <= 0;
                    carry_output <= 0;
                    zero_flag <= (a > b);
                end
                4'b1011: begin // Equal
                    final_output <= 0;
                    carry_output <= 0;
                    zero_flag <= (a == b);
                end
                default: begin // Invalid opcode
                    final_output <= 0;
                    carry_output <= 0;
                    zero_flag <= 0;
                end
            endcase
        end
    end

endmodule

module edge_detect (
  input signal_in,
  input clock,
  output rising_edge,
  output falling_edge
);

  reg prev_signal_in;

  always @(posedge clock) begin
    if (signal_in && !prev_signal_in) begin
      rising_edge <= 1;
    end else begin
      rising_edge <= 0;
    end

    if (!signal_in && prev_signal_in) begin
      falling_edge <= 1;
    end else begin
      falling_edge <= 0;
    end

    prev_signal_in <= signal_in;
  end

endmodule

module decoder_4to16 (
    input A,
    input B,
    input C,
    input D,
    output reg [15:0] Y
);

reg [3:0] stage1_out;
reg [3:0] stage2_out;
reg [3:0] stage3_out;

always @ (posedge A or posedge B or posedge C or posedge D) begin
    stage1_out <= {A, B, C, D};
end

always @ (posedge A or posedge B or posedge C or posedge D) begin
    stage2_out <= stage1_out;
end

always @ (posedge A or posedge B or posedge C or posedge D) begin
    stage3_out <= stage2_out;
end

always @ (posedge A or posedge B or posedge C or posedge D) begin
    case (stage3_out)
        4'b0000: Y <= 16'b0000000000000001;
        4'b0001: Y <= 16'b0000000000000010;
        4'b0010: Y <= 16'b0000000000000100;
        4'b0011: Y <= 16'b0000000000001000;
        4'b0100: Y <= 16'b0000000000010000;
        4'b0101: Y <= 16'b0000000000100000;
        4'b0110: Y <= 16'b0000000001000000;
        4'b0111: Y <= 16'b0000000010000000;
        4'b1000: Y <= 16'b0000000100000000;
        4'b1001: Y <= 16'b0000001000000000;
        4'b1010: Y <= 16'b0000010000000000;
        4'b1011: Y <= 16'b0000100000000000;
        4'b1100: Y <= 16'b0001000000000000;
        4'b1101: Y <= 16'b0010000000000000;
        4'b1110: Y <= 16'b0100000000000000;
        4'b1111: Y <= 16'b1000000000000000;
    endcase
end

endmodule

module add_sub_shift (
    input [3:0] A,
    input [3:0] B,
    input mode,
    input DIR,
    input [1:0] AMT,
    output reg [3:0] Q
);

reg [3:0] shifted_A;
wire [3:0] shifted_B;

// Barrel shifter module
barrel_shifter bs(
    .A(A),
    .B(B),
    .DIR(DIR),
    .AMT(AMT),
    .Q(shifted_A),
    .fill(shifted_B)
);

// Adder-subtractor module
adder_subtractor as(
    .A(shifted_A),
    .B(shifted_B),
    .mode(mode),
    .Q(Q)
);

endmodule

module barrel_shifter (
    input [3:0] A,
    input [3:0] B,
    input DIR,
    input [1:0] AMT,
    output reg [3:0] Q,
    output reg [3:0] fill
);

reg [3:0] shifted_A;

always @(*) begin
    case (DIR)
        1'b0: shifted_A = {A[AMT[1:0]-1:0], B[3:AMT[1:0]]};
        1'b1: shifted_A = {B[3-AMT[1:0]:0], A[3:AMT[1:0]]};
    endcase
end

assign Q = shifted_A;
assign fill = {B[3:AMT[1:0]], shifted_A[AMT[1:0]-1:0]};

endmodule

module adder_subtractor (
    input [3:0] A,
    input [3:0] B,
    input mode,
    output reg [3:0] Q
);

always @(*) begin
    if (mode == 1'b0) begin
        Q = A + B;
    end else begin
        Q = A - B;
    end
end

endmodule

