module counter_4bit (
    input clk,
    input rst,
    output reg [3:0] Q
);

reg [3:0] Q_reg1, Q_reg2, Q_reg3;

always @(posedge clk) begin
    Q_reg1 <= Q;
    Q_reg2 <= Q_reg1;
    Q_reg3 <= Q_reg2;
    if (rst) begin
        Q_reg1 <= 4'b0;
        Q_reg2 <= 4'b0;
        Q_reg3 <= 4'b0;
    end else begin
        Q_reg1 <= Q_reg1 + 1;
        Q_reg2 <= Q_reg2 + 1;
        Q_reg3 <= Q_reg3 + 1;
    end
end

assign Q = Q_reg3;

endmodule

module SEG7_COUNTER (iCLK, iRST, oSEG);
input iCLK, iRST;
output reg [6:0] oSEG;
reg [3:0] count;

always @(posedge iCLK)
begin
    if (iRST) // reset counter to 0 when iRST is high
        count <= 0;
    else if (count == 9) // reset counter to 0 when it reaches 9
        count <= 0;
    else // increment counter by 1
        count <= count + 1;
end

SEG7_LUT lut(.iDIG(count), .oSEG(oSEG)); // use SEG7_LUT module to display count

endmodule

module mulAddRecF64 (
    input [62:0] control,
    input int_mul,
    input [2:0] op,
    input [64:0] a,
    input [64:0] b,
    input [64:0] c,
    input [2:0] roundingMode,
    output [64:0] out,
    output [4:0] exceptionFlags,
    output [63:0] out_imul
);

    wire [62:0] control_11;
    assign control_11 = {control[62], control};

    wire [63:0] a_11, b_11, c_11;
    assign a_11 = {1'b0, a};
    assign b_11 = {1'b0, b};
    assign c_11 = {1'b0, c};

    wire [64:0] out_mul, out_add, out_sub;
    wire [64:0] out_mul_rounded, out_add_rounded, out_sub_rounded;

    wire [4:0] mul_exceptionFlags, add_exceptionFlags, sub_exceptionFlags;

    wire [63:0] out_imul_mul;
    wire [63:0] out_imul_add;
    wire [63:0] out_imul_sub;

    assign out_imul_mul = int_mul ? a * b : 64'b0;
    assign out_imul_add = int_mul ? a + b : 64'b0;
    assign out_imul_sub = int_mul ? a - b : 64'b0;

    mulAddRecFN#(11, 53) mulAddRecFN_mul(
        control_11,
        1'b0,
        3'b000,
        a_11,
        b_11,
        64'b0,
        roundingMode,
        out_mul,
        mul_exceptionFlags,
        out_imul_mul
    );

    mulAddRecFN#(11, 53) mulAddRecFN_add(
        control_11,
        1'b0,
        3'b001,
        a_11,
        b_11,
        64'b0,
        roundingMode,
        out_add,
        add_exceptionFlags,
        out_imul_add
    );

    mulAddRecFN#(11, 53) mulAddRecFN_sub(
        control_11,
        1'b0,
        3'b010,
        a_11,
        b_11,
        64'b0,
        roundingMode,
        out_sub,
        sub_exceptionFlags,
        out_imul_sub
    );

    always @(*) begin
        case (op)
            3'b000: begin
                out = out_mul + c_11;
                exceptionFlags = mul_exceptionFlags;
                out_imul = out_imul_mul;
            end
            3'b001: begin
                out = out_add + c_11;
                exceptionFlags = add_exceptionFlags;
                out_imul = out_imul_add;
            end
            3'b010: begin
                out = out_sub + c_11;
                exceptionFlags = sub_exceptionFlags;
                out_imul = out_imul_sub;
            end
            default: begin
                out = 64'b0;
                exceptionFlags = 5'b0;
                out_imul = 64'b0;
            end
        endcase
    end

endmodule

