module fourDigitDisplay(
    input clk_i,
    input reset_n,
    output reg [2:0] sel,
    output reg [6:0] segments
    );

    // Internal state machine
    reg [1:0] state;
    reg [1:0] state_next;

    // Internal counter
    reg [3:0] count;

    // 7-segment codes for digits 0-9
    parameter [6:0] SEG_0 = 7'b1000000;
    parameter [6:0] SEG_1 = 7'b1111001;
    parameter [6:0] SEG_2 = 7'b0100100;
    parameter [6:0] SEG_3 = 7'b0110000;
    parameter [6:0] SEG_4 = 7'b0011001;
    parameter [6:0] SEG_5 = 7'b0010010;
    parameter [6:0] SEG_6 = 7'b0000010;
    parameter [6:0] SEG_7 = 7'b1111000;
    parameter [6:0] SEG_8 = 7'b0000000;
    parameter [6:0] SEG_9 = 7'b0010000;

    // State machine
    always @ (posedge clk_i, negedge reset_n) begin
        if (!reset_n) begin
            state <= 2'b00;
            count <= 4'b0000;
        end
        else begin
            state <= state_next;
            count <= count + 1;
        end
    end

    always @ (*) begin
        case (state)
            2'b00: begin
                sel <= 3'b000;
                segments <= SEG_0;
                if (count == 4'b1001) begin
                    state_next <= 2'b01;
                    count <= 4'b0000;
                end
                else begin
                    state_next <= 2'b00;
                end
            end
            2'b01: begin
                sel <= 3'b001;
                segments <= SEG_1;
                if (count == 4'b1001) begin
                    state_next <= 2'b10;
                    count <= 4'b0000;
                end
                else begin
                    state_next <= 2'b01;
                end
            end
            2'b10: begin
                sel <= 3'b010;
                segments <= SEG_2;
                if (count == 4'b1001) begin
                    state_next <= 2'b11;
                    count <= 4'b0000;
                end
                else begin
                    state_next <= 2'b10;
                end
            end
            2'b11: begin
                sel <= 3'b100;
                segments <= SEG_3;
                if (count == 4'b1001) begin
                    state_next <= 2'b00;
                    count <= 4'b0000;
                end
                else begin
                    state_next <= 2'b11;
                end
            end
            default: begin
                sel <= 3'b000;
                segments <= SEG_0;
                state_next <= 2'b00;
                count <= 4'b0000;
            end
        endcase
    end

endmodule

