  input [3:0] ram_loader_sel_i,
  input ram_loader_stb_i,
  input ram_loader_we_i,
  input ram_loader_done_i,
  input [AWIDTH-1:0] if_adr_i,
  output [31:0] if_data_o,
  input [AWIDTH-1:0] dwb_adr_i,
  input [31:0] dwb_dat_i,
  output [31:0] dwb_dat_o,
  input dwb_we_i,
  output dwb_ack_o,
  input dwb_stb_i,
  input [3:0] dwb_sel_i
);

  parameter RAM_SIZE = 16384;
  parameter ICWIDTH = 6;
  parameter DCWIDTH = 6;

  reg [31:0] ram [0:RAM_SIZE/4-1];
  reg [31:0] icache [0:ICWIDTH/4-1];
  reg [31:0] dcache [0:DCWIDTH/4-1];
  reg [31:0] if_data;

  always @(posedge wb_clk_i) begin
    if (ram_loader_done_i) begin
      ram[ram_loader_adr_i[AWIDTH-1:2]] <= ram_loader_dat_i;
    end
  end

  assign if_data_o = if_data;

  always @(posedge wb_clk_i) begin
    if (wb_rst_i) begin
      if_data <= 0;
    end else begin
      if_data <= ram[if_adr_i[AWIDTH-1:2]];
    end
  end

  always @(posedge wb_clk_i) begin
    if (dwb_stb_i) begin
      if (dwb_we_i) begin
        ram[dwb_adr_i[AWIDTH-1:2]] <= dwb_dat_i;
      end else begin
        dwb_dat_o <= ram[dwb_adr_i[AWIDTH-1:2]];
      end
    end
  end

  assign dwb_ack_o = dwb_stb_i;

endmodule

