module edge_detection (
    input a,
    input clk,
    output reg rising_edge,
    output reg falling_edge
);
    parameter IDLE = 2'b00, RISING = 2'b01, FALLING = 2'b10;
    reg [1:0] state, next_state;

    always @(posedge clk) begin
        state <= next_state;
    end

    always @(*) begin
        case (state)
            IDLE: begin
                if (a) begin
                    next_state = RISING;
                end else begin
                    next_state = IDLE;
                end
            end
            RISING: begin
                if (a) begin
                    next_state = RISING;
                end else begin
                    next_state = FALLING;
                end
            end
            FALLING: begin
                if (a) begin
                    next_state = RISING;
                end else begin
                    next_state = FALLING;
                end
            end
        endcase
    end

    always @(posedge clk) begin
        case (state)
            IDLE: begin
                rising_edge <= 1'b0;
                falling_edge <= 1'b0;
            end
            RISING: begin
                rising_edge <= 1'b1;
                falling_edge <= 1'b0;
            end
            FALLING: begin
                rising_edge <= 1'b0;
                falling_edge <= 1'b1;
            end
        endcase
    end
endmodule

module final_module (
    input out_comb_ff,
    input rising_edge,
    input falling_edge,
    output reg [1:0] final_output
);
    always @(*) begin
        if (out_comb_ff && rising_edge) begin
            final_output = 2'b10;
        end else if (out_comb_ff || rising_edge || falling_edge) begin
            final_output = 2'b01;
        end else begin
            final_output = 2'b00;
        end
    end
endmodule

module top_module (
    input clk,
    input rst_n,
    input a,
    input b,
    output reg out_comb_ff,
    output reg [1:0] final_output
);
    xor_module xor_inst (
        .a(a),
        .b(b),
        .clk(clk),
        .out_comb_ff(out_comb_ff)
    );

    edge_detection edge_inst (
        .a(a),
        .clk(clk),
        .rising_edge(rising_edge),
        .falling_edge(falling_edge)
    );

    final_module final_inst (
        .out_comb_ff(out_comb_ff),
        .rising_edge(rising_edge),
        .falling_edge(falling_edge),
        .final_output(final_output)
    );
endmodule

module axis_async_frame_fifo_64 (
    input input_clk,
    input input_rst,
    input [63:0] input_axis_tdata,
    input [7:0] input_axis_tkeep,
    input input_axis_tvalid,
    input input_axis_tlast,
    input input_axis_tuser,
    output input_axis_tready,
    input output_clk,
    input output_rst,
    output [63:0] output_axis_tdata,
    output [7:0] output_axis_tkeep,
    output output_axis_tvalid,
    output output_axis_tlast,
    output output_axis_tready
);

localparam DEPTH = 64;
localparam ADDR_WIDTH = $clog2(DEPTH);
localparam DATA_WIDTH = 64;

reg [DATA_WIDTH-1:0] buffer [DEPTH-1:0];
reg [ADDR_WIDTH-1:0] head = 0;
reg [ADDR_WIDTH-1:0] tail = 0;
reg [ADDR_WIDTH-1:0] count = 0;

reg [ADDR_WIDTH-1:0] next_tail = 0;
reg [ADDR_WIDTH-1:0] next_head = 0;
reg [ADDR_WIDTH-1:0] next_count = 0;

reg [ADDR_WIDTH-1:0] read_addr = 0;
reg [ADDR_WIDTH-1:0] write_addr = 0;

reg [1:0] state = 0;

assign input_axis_tready = (count < DEPTH);

always @(posedge input_clk) begin
    if (input_rst) begin
        state <= 0;
        head <= 0;
        tail <= 0;
        count <= 0;
    end else begin
        case (state)
            0: begin // IDLE
                if (input_axis_tvalid && input_axis_tready) begin
                    state <= 1;
                    next_tail <= tail + 1;
                    write_addr <= tail;
                end
            end
            1: begin // WRITE
                buffer[write_addr] <= input_axis_tdata;
                state <= 2;
            end
            2: begin // WRITE_WAIT
                if (next_tail == head) begin
                    state <= 3;
                end else begin
                    next_tail <= next_tail + 1;
                    write_addr <= write_addr + 1;
                    state <= 1;
                end
            end
            3: begin // READ
                if (output_axis_tready && count > 0) begin
                    state <= 4;
                    next_head <= head + 1;
                    read_addr <= head;
                end
            end
            4: begin // READ_WAIT
                output_axis_tdata <= buffer[read_addr];
                output_axis_tkeep <= input_axis_tkeep;
                output_axis_tvalid <= 1;
                output_axis_tlast <= (count == 1) && input_axis_tlast;
                if (next_head == tail) begin
                    state <= 0;
                    next_count <= count - 1;
                end else begin
                    next_head <= next_head + 1;
                    read_addr <= read_addr + 1;
                    next_count <= count - 1;
                    state <= 3;
                end
            end
        endcase
    end
end

always @(posedge output_clk) begin
    if (output_rst) begin
        output_axis_tdata <= 0;
        output_axis_tkeep <= 0;
        output_axis_tvalid <= 0;
        output_axis_tlast <= 0;
        next_head <= 0;
        next_count <= 0;
    end else begin
        head <= next_head;
        count <= next_count;
        if (state == 0) begin
            output_axis_tdata <= 0;
            output_axis_tkeep <= 0;
            output_axis_tvalid <= 0;
            output_axis_tlast <= 0;
        end else if (state == 4) begin
            if (output_axis_tready) begin
                output_axis_tdata <= 0;
                output_axis_tkeep <= 0;
                output_axis_tvalid <= 0;
                output_axis_tlast <= 0;
            end
        end
    end
end

assign output_axis_tready = (state == 3);

endmodule

module bus_interface (
    input wire          BUS_CLK,
