module full_adder (sum, carry_out, A, B, carry_in);
    output sum, carry_out;
    input A, B, carry_in;

    wire w1, w2, w3;

    xor (w1, A, B);
    xor (sum, w1, carry_in);
    and (w2, A, B);
    and (w3, w1, carry_in);
    or (carry_out, w2, w3);
endmodule

module ripple_carry_adder (S, Cout, A, B, Cin);
    output [3:0] S;
    output Cout;
    input [3:0] A, B;
    input Cin;

    wire [3:0] s;
    wire c1, c2, c3;

    full_adder fa0 (s[0], c1, A[0], B[0], Cin);
    full_adder fa1 (s[1], c2, A[1], B[1], c1);
    full_adder fa2 (s[2], c3, A[2], B[2], c2);
    full_adder fa3 (S[3], Cout, A[3], B[3], c3);

    assign S[2:0] = s[2:0];
endmodule

