module shift_register (
    input clk,
    input reset,
    input [7:0] d,
    output reg [7:0] q
);

    wire [7:0] dff_out [0:7];
    wire [2:0] sel;
    reg [2:0] count = 3'b0;

    my_dff dff_inst_0 (.clk(clk), .reset(reset), .d(d[0]), .q(dff_out[0]));
    my_dff dff_inst_1 (.clk(clk), .reset(reset), .d(dff_out[0]), .q(dff_out[1]));
    my_dff dff_inst_2 (.clk(clk), .reset(reset), .d(dff_out[1]), .q(dff_out[2]));
    my_dff dff_inst_3 (.clk(clk), .reset(reset), .d(dff_out[2]), .q(dff_out[3]));
    my_dff dff_inst_4 (.clk(clk), .reset(reset), .d(dff_out[3]), .q(dff_out[4]));
    my_dff dff_inst_5 (.clk(clk), .reset(reset), .d(dff_out[4]), .q(dff_out[5]));
    my_dff dff_inst_6 (.clk(clk), .reset(reset), .d(dff_out[5]), .q(dff_out[6]));
    my_dff dff_inst_7 (.clk(clk), .reset(reset), .d(dff_out[6]), .q(dff_out[7]));

    always @(posedge clk, negedge reset) begin
        if (!reset) begin
            q <= 8'b0;
        end else begin
            sel <= count;
            q <= dff_out[sel];
            if (count == 3'b111) begin
                count <= 3'b0;
            end else begin
                count <= count + 1;
            end
        end
    end

