module rca110_memory(i_clk, i_rst, mm_adr, mm_we, mm_idat, mm_odat, mm_mode);
   input i_clk;
   input i_rst;


   input      [11:0] mm_adr;
   input 	     mm_we;
   output reg [23:0] mm_idat;
   input      [23:0] mm_odat;
   input      [1:0]  mm_mode;

   reg [24:0] 	     m_memory [4095:0];

   integer 	     i;

   always @(posedge i_clk) begin
      if(i_rst) begin
	 mm_idat <= 0;

	 for(i = 0; i < 4095; i = i + 1)
	   m_memory[i] = 0;

	 m_memory[64] = {9'b011010000, 3'b010, 12'b000000000010}; // STP
	 m_memory[65] = {9'o400, 15'h0};
	 m_memory[66] = {12'b0, 12'b100000000000};

      end
      else begin
         if(mm_mode == 0) begin
            if(mm_we)
               m_memory[mm_adr] <= mm_odat;
            else
               mm_idat <= m_memory[mm_adr];
         end
         else begin
            case(mm_adr)
               4'd0: begin // Input switch 0
                  if(mm_we) m_memory[mm_adr] <= mm_odat;
                  else mm_idat <= 8'b0;
               end
               4'd1: begin // Input switch 1
                  if(mm_we) m_memory[mm_adr] <= mm_odat;
                  else mm_idat <= 8'b0;
               end
               4'd2: begin // Input switch 2
                  if(mm_we) m_memory[mm_adr] <= mm_odat;
                  else mm_idat <= 8'b0;
               end
               4'd3: begin // Input switch 3
                  if(mm_we) m_memory[mm_adr] <= mm_odat;
                  else mm_idat <= 8'b0;
               end
               4'd4: begin // Output LED 0
                  if(mm_we) mm_idat <= 8'b0;
                  else mm_idat <= m_memory[mm_adr];
               end
               4'd5: begin // Output LED 1
                  if(mm_we) mm_idat <= 8'b0;
                  else mm_idat <= m_memory[mm_adr];
               end
               4'd6: begin // Output LED 2
                  if(mm_we) mm_idat <= 8'b0;
                  else mm_idat <= m_memory[mm_adr];
               end
               4'd7: begin // Output LED 3
                  if(mm_we) mm_idat <= 8'b0;
                  else mm_idat <= m_memory[mm_adr];
               end
               default: begin // Other addresses
                  if(mm_we)
                     m_memory[mm_adr] <= mm_odat;
                  else
                     mm_idat <= m_memory[mm_adr];
               end
            endcase
         end
      end
   end

endmodule

module top_module (
    input clk,    // Clocks are used in sequential circuits
    input reset,  // Synchronous active-high reset
    input d,
    output reg q,
    input a,
    input b,
    output out
);

reg j, k;

// D flip-flop using JK flip-flop
always @(posedge clk, posedge reset) begin
    if (reset) begin
        q <= 1'b0;
        j <= 1'b0;
        k <= 1'b0;
    end else begin
        j <= d;
        k <= ~d;
        q <= j ^ (q & k);
    end
end

// XOR gate
always @(*) begin
    if (a == b) begin
        out = 1'b0;
    end else begin
        out = 1'b1;
    end
end

// AND gate
always @(*) begin
    if (out && q) begin
        out = 1'b1;
    end else begin
        out = 1'b0;
    end
end

endmodule

