module vending_machine (
    X,
    A1,
    A2,
    A3,
    A4,
    B1
);

    output X;
    input A1;
    input A2;
    input A3;
    input A4;
    input B1;

    wire [1:0] item_cost;
    assign item_cost[0] = 1'b0; // A1 costs 25 cents
    assign item_cost[1] = 1'b1; // A2 costs 50 cents
    assign item_cost[2] = 2'b01; // A3 costs 75 cents
    assign item_cost[3] = 2'b10; // A4 costs 100 cents

    reg [7:0] current_amount;
    reg [1:0] selected_item;

    always @ (posedge B1) begin
        case ({B1, A1, A2, A3, A4})
            5'b00001: selected_item <= 2'b00; // A1 selected
            5'b00010: selected_item <= 2'b01; // A2 selected
            5'b00100: selected_item <= 2'b10; // A3 selected
            5'b01000: selected_item <= 2'b11; // A4 selected
            default: selected_item <= 2'b11; // No item selected
        endcase
    end

    always @ (posedge B1) begin
        if ({B1, A1, A2, A3, A4} == 5'b00001) // A1 selected
            current_amount <= current_amount + 5'd5;
        else if ({B1, A1, A2, A3, A4} == 5'b00010) // A2 selected
            current_amount <= current_amount + 5'd10;
        else if ({B1, A1, A2, A3, A4} == 5'b00100) // A3 selected
            current_amount <= current_amount + 5'd10;
        else if ({B1, A1, A2, A3, A4} == 5'b01000) // A4 selected
            current_amount <= current_amount + 5'd15;
    end

    always @ (*) begin
        if (current_amount >= item_cost[selected_item])
            X <= 1'b1;
        else
            X <= 1'b0;
    end

endmodule

