module tbm_hub (
  input scl,
  input sda,
  input tbm_rw,
  output rda
);

  reg [4:0] hub     = 20;
  reg [2:0] port    = 1;
  reg tbm_rw        = 0;
  reg [6:0] tbm_reg = 7'h12;
  reg [7:0] tbm_dat = 8'h5a;

  reg gate = 0;
  reg [5:0] count = 0;

  always @(negedge sda) if (scl) gate <= 1;
  always @(posedge sda) if (scl) gate <= 0;

  always @(posedge scl) begin
    if (gate) count <= count + 1;
    else count <= 0;
  end

  reg rd = 1;
  reg data = 1;
  always @(posedge scl) begin
    if (count == 6'd9) begin
      // start
      rd <= 0;
      // data
      rd <= tbm_reg[6];
      rd <= tbm_reg[5];
      rd <= tbm_reg[4];
      rd <= tbm_reg[3];
      rd <= !tbm_reg[3];
      rd <= tbm_reg[2];
      rd <= tbm_reg[1];
      rd <= tbm_reg[0];
      rd <= tbm_rw;
      rd <= !tbm_rw;
      rd <= tbm_dat[7];
      rd <= tbm_dat[6];
      rd <= tbm_dat[5];
      rd <= tbm_dat[4];
      rd <= !tbm_dat[4];
      rd <= tbm_dat[3];
      rd <= tbm_dat[2];
      rd <= tbm_dat[1];
      rd <= tbm_dat[0];
      rd <= !tbm_dat[0];
      // repeated start
      rd <= 0;
      #1;
      rd <= 1;
      #1;
      // hub & port
      rd <= hub[4];
      rd <= hub[3];
      rd <= hub[2];
      rd <= hub[1];
      rd <= hub[0];
      rd <= port[2];
      rd <= port[1];
      rd <= port[0];
      rd <= 1;
      #1;
      // stop
      rd <= 1;
    end
  end

  assign #10 rda = rd;

endmodule

module TDC (
  input signal1,
  input signal2,
  output reg [15:0] digital_value
);

parameter resolution = 1; // smallest time difference that can be measured
parameter range = 1000; // maximum time difference that can be measured

reg [15:0] counter;
reg [15:0] time_diff;

always @(posedge signal1 or posedge signal2) begin
  if (signal1 && !signal2) begin
    counter <= 0;
  end else if (!signal1 && signal2) begin
    counter <= 0;
  end else begin
    counter <= counter + 1;
  end
end

always @(posedge signal1 or posedge signal2) begin
  if (signal1 && !signal2) begin
    time_diff <= 0;
  end else if (!signal1 && signal2) begin
    time_diff <= 0;
  end else begin
    time_diff <= counter * resolution;
  end
end

