    if (!rst) begin
      count = 0;
      count1 = 0;
      clk_4sec = 0;
      clk_5KHz = 0;
    end else begin
      if (count == 200000000) begin
        clk_4sec = ~clk_4sec;
        count = 0;
      end
      if (count1 == 10000) begin
        clk_5KHz = ~clk_5KHz;
        count1 = 0;
      end
      count = count + 1;
      count1 = count1 + 1;
    end
  end
