module add_sub_4bit (A, B, SUB, SUM, CARRY);

input [3:0] A;
input [3:0] B;
input SUB;
output [3:0] SUM;
output CARRY;

reg [3:0] twos_comp;
reg [3:0] temp_sum;
reg carry;

always @(*) begin
    if(SUB == 1) begin
        twos_comp = ~B + 1;
        temp_sum = A + twos_comp;
        carry = (temp_sum[4] == 1) ? 1 : 0;
        SUM = temp_sum[3:0];
    end
    else begin
        temp_sum = A + B;
        carry = (temp_sum[4] == 1) ? 1 : 0;
        SUM = temp_sum[3:0];
    end
end

assign CARRY = carry;

endmodule

