                (pos == 3'b001) ? cout[0] :
                (pos == 3'b010) ? cout[1] :
                (pos == 3'b011) ? cout[2] :
                (pos == 3'b100) ? cout[3] :
                (pos == 3'b101) ? cout[4] :
                (pos == 3'b110) ? cout[5] :
                                  cout[6] ;
endmodule

