module fsm_3bit_sequence_detection (
  input clk,
  input reset,
  input data,
  output reg match
);

  // Define states
  parameter START = 2'b00;
  parameter STATE1 = 2'b01;
  parameter MATCH = 2'b10;

  // Define state register and next state logic
  reg [1:0] state, next_state;
  always @(posedge clk, negedge reset) begin
    if (reset == 0) begin
      state <= START;
    end else begin
      state <= next_state;
    end
  end

  // Define match output logic
  always @(state) begin
    if (state == MATCH) begin
      match <= 1;
    end else begin
      match <= 0;
    end
  end

  // Define next state logic
  always @(state, data) begin
    case (state)
      START: begin
        if (data == 1) begin
          next_state = STATE1;
        end else begin
          next_state = START;
        end
      end
      STATE1: begin
        if (data == 0) begin
          next_state = MATCH;
        end else begin
          next_state = START;
        end
      end
      MATCH: begin
        if (data == 1) begin
          next_state = START;
        end else begin
          next_state = MATCH;
        end
      end
      default: begin
        next_state = START;
      end
    endcase
  end

endmodule

module CDC_synchronizer(
  input wire clk_in,
  input wire rst_in,
  input wire [n-1:0] data_in,
  output reg [n-1:0] data_out
);

parameter n = 8; // number of bits in the data signal
parameter t = 2; // number of clock cycles for synchronization

reg [n-1:0] ff1_out;
reg [n-1:0] ff2_out;

wire enable;

assign enable = ~(&{clk_in, rst_in});

always @(posedge clk_in) begin
  ff1_out <= data_in;
end

integer i;
always @(posedge clk_out) begin
  if (i < t) begin
    i <= i + 1;
  end else begin
    ff2_out <= ff1_out;
    i <= 0;
  end
end

always @(posedge clk_out) begin
  if (enable) begin
    data_out <= ff2_out;
  end
end

endmodule

