    input select,
    input [7:0] write_addr,
    input [3:0] write_data,
    input read_en,
    input [7:0] read_addr,
    output [7:0] q
);

    // Shift register with parallel load
    reg [7:0] shift_reg;
    wire load;
    assign load = select ? 1'b0 : 1'b1; // Inverse logic for select input
    always @(posedge clk) begin
        if (load) begin
            shift_reg <= data_in;
        end else begin
            shift_reg <= {shift_reg[6:0], shift_reg[7]};
        end
    end

    // Dual-port RAM with depth of 8 and bit width of 4 bits
    reg [3:0] ram [0:7];
    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1) begin
            ram[i] = 4'b0000;
        end
    end
    always @(posedge clk) begin
        if (reset) begin
            for (i = 0; i < 8; i = i + 1) begin
                ram[i] <= 4'b0000;
            end
        end else if (select) begin
            if (read_en) begin
                q <= ram[read_addr];
            end
            if (write_addr < 8) begin
                ram[write_addr] <= write_data;
            end
        end
    end

    // Multiplexer and control logic to enable either shift register or RAM
    always @(posedge clk) begin
        if (reset) begin
            q <= 8'b00000000;
        end else if (select) begin
            q <= shift_reg;
        end else begin
            q <= ram[0];
        end
    end

endmodule

