module PLL (
  input clk_in,
  input rst,
  input [m-1:0] freq_set,
  output reg clk_out,
  output reg locked
);

parameter n = 8; // number of bits used to represent the phase accumulator
parameter m = 8; // number of bits used to represent the frequency control word
parameter k = 1; // gain of the phase detector
parameter d = 10; // maximum frequency deviation between the input and output signals

reg [n-1:0] phase_acc; // phase accumulator
reg [m-1:0] freq_ctrl; // frequency control word
reg [m-1:0] freq_ctrl_d; // delayed frequency control word
reg [m-1:0] freq_ctrl_dd; // double delayed frequency control word
reg [m-1:0] freq_ctrl_ddd; // triple delayed frequency control word
reg [m-1:0] freq_ctrl_dddd; // quadruple delayed frequency control word
reg [m-1:0] freq_ctrl_ddddd; // quintuple delayed frequency control word
reg [m-1:0] freq_ctrl_dddddd; // sextuple delayed frequency control word
reg [m-1:0] freq_ctrl_ddddddd; // septuple delayed frequency control word
reg [m-1:0] freq_ctrl_dddddddd; // octuple delayed frequency control word
reg [m-1:0] freq_ctrl_ddddddddd; // nonuple delayed frequency control word
reg [m-1:0] freq_ctrl_dddddddddd; // decuple delayed frequency control word

wire phase_err; // phase error signal
wire [m-1:0] freq_err; // frequency error signal
wire [m-1:0] freq_err_d; // delayed frequency error signal
wire [m-1:0] freq_err_dd; // double delayed frequency error signal
wire [m-1:0] freq_err_ddd; // triple delayed frequency error signal
wire [m-1:0] freq_err_dddd; // quadruple delayed frequency error signal
wire [m-1:0] freq_err_ddddd; // quintuple delayed frequency error signal
wire [m-1:0] freq_err_dddddd; // sextuple delayed frequency error signal
wire [m-1:0] freq_err_ddddddd; // septuple delayed frequency error signal
wire [m-1:0] freq_err_dddddddd; // octuple delayed frequency error signal
wire [m-1:0] freq_err_ddddddddd; // nonuple delayed frequency error signal
wire [m-1:0] freq_err_dddddddddd; // decuple delayed frequency error signal

reg [n-1:0] phase_ref; // phase reference signal
reg [m-1:0] freq_ref; // frequency reference signal

assign phase_err = (phase_ref - phase_acc) >= 0 ? (phase_ref - phase_acc) : (phase_acc - phase_ref); // phase error signal
assign freq_err = freq_ref - freq_ctrl; // frequency error signal

assign freq_err_d = freq_ctrl - freq_ctrl_d; // delayed frequency error signal
assign freq_err_dd = freq_ctrl_d - freq_ctrl_dd; // double delayed frequency error signal
assign freq_err_ddd = freq_ctrl_dd - freq_ctrl_ddd; // triple delayed frequency error signal
assign freq_err_dddd = freq_ctrl_ddd - freq_ctrl_dddd; // quadruple delayed frequency error signal
assign freq_err_ddddd = freq_ctrl_dddd - freq_ctrl_ddddd; // quintuple delayed frequency error signal
assign freq_err_dddddd = freq_ctrl_ddddd - freq_ctrl_dddddd; // sextuple delayed frequency error signal
assign freq_err_ddddddd = freq_ctrl_dddddd - freq_ctrl_ddddddd; // septuple delayed frequency error signal
assign freq_err_dddddddd = freq_ctrl_ddddddd - freq_ctrl_dddddddd; // octuple delayed frequency error signal
assign freq_err_ddddddddd = freq_ctrl_dddddddd - freq_ctrl_ddddddddd; // nonuple delayed frequency error signal
assign freq_err_dddddddddd = freq_ctrl_ddddddddd - freq_ctrl_dddddddddd; // decuple delayed frequency error signal

always @(posedge clk_in or posedge rst) begin
  if (rst) begin
    phase_acc <= 0;
    freq_ctrl <= 0;
    freq_ctrl_d <= 0;
    freq_ctrl_dd <= 0;
    freq_ctrl_ddd <= 0;
    freq_ctrl_dddd <= 0;
    freq_ctrl_ddddd <= 0;
    freq_ctrl_dddddd <= 0;
    freq_ctrl_ddddddd <= 0;
    freq_ctrl_dddddddd <= 0;
    freq_ctrl_ddddddddd <= 0;
    freq_ctrl_dddddddddd <= 0;
    phase_ref <= 0;
    freq_ref <= 0;
    clk_out <= 0;
    locked <= 0;
  end else begin
    phase_acc <= phase_acc + freq_ctrl; // phase accumulator
    freq_ctrl <= freq_ctrl + k * phase_err; // frequency control word
    freq_ctrl_d <= freq_ctrl_dd;
    freq_ctrl_dd <= freq_ctrl_ddd;
    freq_ctrl_ddd <= freq_ctrl_dddd;
    freq_ctrl_dddd <= freq_ctrl_ddddd;
    freq_ctrl_ddddd <= freq_ctrl_dddddd;
    freq_ctrl_dddddd <= freq_ctrl_ddddddd;
    freq_ctrl_ddddddd <= freq_ctrl_dddddddd;
    freq_ctrl_dddddddd <= freq_ctrl_ddddddddd;
    freq_ctrl_ddddddddd <= freq_ctrl_dddddddddd;
    freq_ctrl_dddddddddd <= freq_err + freq_err_d + freq_err_dd + freq_err_ddd + freq_err_dddd + freq_err_ddddd + freq_err_dddddd + freq_err_ddddddd + freq_err_dddddddd + freq_err_ddddddddd; // delayed frequency control word
    phase_ref <= phase_ref + freq_set; // phase reference signal
    freq_ref <= freq_set; // frequency reference signal
    clk_out <= phase_acc[n-1]; // output clock signal
    locked <= phase_err <= d; // lock signal
  end
end

endmodule

