module avalon_st_interconnect (
    input in_clk,
    input in_rst,
    input [31:0] in_data,
    input in_valid,
    output in_ready,
    input out_clk,
    input out_rst,
    output [31:0] out_data,
    output out_valid,
    input out_ready
);

    reg [31:0] data_buffer;
    reg in_ready_reg, out_valid_reg;
    wire out_ready_reg;

    // Input interface
    always @(posedge in_clk) begin
        if (in_rst) begin
            in_ready_reg <= 1'b0;
        end else if (in_valid && out_ready_reg) begin
            data_buffer <= in_data;
            in_ready_reg <= 1'b1;
        end else if (out_valid_reg && out_ready_reg) begin
            in_ready_reg <= 1'b0;
        end
    end

    assign in_ready = in_ready_reg;

    // Output interface
    always @(posedge out_clk) begin
        if (out_rst) begin
            out_valid_reg <= 1'b0;
        end else if (in_ready_reg && out_valid) begin
            out_data <= data_buffer;
            out_valid_reg <= 1'b1;
        end else if (~in_ready_reg && out_valid_reg) begin
            out_valid_reg <= 1'b0;
        end
    end

    assign out_valid = out_valid_reg;
    assign out_ready_reg = out_ready;

