module adler_checksum (
  input clk,
  input rst,
  input [7:0] data_in,
  output reg [31:0] checksum_out,
  output reg error
);

  reg [15:0] s1;
  reg [15:0] s2;

  always @(posedge clk) begin
    if (rst) begin
      s1 <= 16'h1;
      s2 <= 16'h1;
      checksum_out <= 32'h0;
      error <= 1'b0;
    end else begin
      s1 <= (s1 + data_in) % 16'hFFFF;
      s2 <= (s2 + s1) % 16'hFFFF;
      if (s2 == 16'hFFFF) begin
        checksum_out <= (s2 << 16) | s1;
      end
    end
  end

  always @(posedge clk) begin
    if (rst) begin
      error <= 1'b0;
    end else begin
      if (checksum_out != ((s2 << 16) | s1)) begin
        error <= 1'b1;
      end else begin
        error <= 1'b0;
      end
    end
  end

endmodule

module quadrature_decoder(
    CLOCK, 
    RESET,
    A, 
    B, 
    COUNT_ENABLE,
    DIRECTION, 
    SPEED
);
    input CLOCK, RESET, A, B;
    output COUNT_ENABLE;
    output DIRECTION;
    output [3:0] SPEED;

    reg [2:0] A_delayed;
    reg [2:0] B_delayed;
    reg [31:0] total;

    always @(posedge CLOCK or posedge RESET) begin 
        if (RESET) begin 
            A_delayed <= 0;
            B_delayed <= 0;
            total <= 0;
        end else begin
            A_delayed <= {A_delayed[1:0], A};
            B_delayed <= {B_delayed[1:0], B};
        end
    end

    wire count_enable = A_delayed[1] ^ A_delayed[2] ^ B_delayed[1] ^ B_delayed[2];
    wire count_direction = A_delayed[1] ^ B_delayed[2];

    always @(posedge CLOCK or posedge RESET) begin
        if (RESET) begin 
            total <= 0;
        end 
        else if (count_enable) begin
            // only want a final count between 0 & 27 (x4 for the clicks)
            if (count_direction && total < 109) begin 
                total <= total+1; 
            end
            else if (!count_direction && total > 0) begin 
                total <= total-1;
            end
        end
    end

    assign COUNT_ENABLE = count_enable;
    assign DIRECTION =  count_direction;

    always @(*) begin
        if (total <= 27) begin
            SPEED = 4'b0001;
        end
        else if (total <= 54) begin
            SPEED = 4'b0010;
        end
        else if (total <= 81) begin
            SPEED = 4'b0100;
        end
        else begin
            SPEED = 4'b1000;
        end
    end

endmodule

