parameter step_mode = 2'b00; // stepping mode of the stepper motor (full, half, quarter, or eighth) 

reg [1:0] step_count = 0;
reg [31:0] count = 0;

always @(posedge clk) begin
  count <= count + 1;
  if (count == (step_delay * (2 ** step_mode))) begin
    count <= 0;
    step_count <= step_count + 1;
    if (step_count == 2'b00) begin
      stepA <= 4'b1000;
      stepB <= 4'b0001;
      stepC <= 4'b0010;
      stepD <= 4'b0100;
    end
    else if (step_count == 2'b01) begin
      stepA <= 4'b1100;
      stepB <= 4'b1001;
      stepC <= 4'b0011;
      stepD <= 4'b0101;
    end
    else if (step_count == 2'b10) begin
      stepA <= 4'b0100;
      stepB <= 4'b1101;
      stepC <= 4'b1010;
      stepD <= 4'b0111;
    end
    else if (step_count == 2'b11) begin
      stepA <= 4'b0010;
      stepB <= 4'b1011;
      stepC <= 4'b1110;
      stepD <= 4'b1000;
      step_count <= 2'b00;
    end
  end
  else if (step == 1) begin
    count <= 0;
    step_count <= step_count + 1;
    if (step_count == 2'b00) begin
      stepA <= 4'b1000;
      stepB <= 4'b0001;
      stepC <= 4'b0010;
      stepD <= 4'b0100;
    end
    else if (step_count == 2'b01) begin
      stepA <= 4'b1100;
      stepB <= 4'b1001;
      stepC <= 4'b0011;
      stepD <= 4'b0101;
    end
    else if (step_count == 2'b10) begin
