      stepC <= 4'b1010;
      stepD <= 4'b0111;
    end
    else if (step_count == 2'b11) begin
      stepA <= 4'b0010;
      stepB <= 4'b1011;
      stepC <= 4'b1110;
      stepD <= 4'b1000;
      step_count <= 2'b00;
    end
  end
end

