          input_offset <= input_offset + 1;
          input_count <= input_count + 1;
          input_miss <= 0;
        end else begin
          input_done <= 1;
          input_miss <= 0;
        end
      end else begin
        input_miss <= input_miss + 1;
      end
    end
  end

