  always @(posedge clk) begin
    if (reset_n == 0) begin
      mutex_count <= 0;
      mutex_file <= 0;
      mutex_offset <= 0;
      mutex_read <= 0;
      mutex_ready <= 0;
      mutex_done <= 0;
      mutex_miss <= 0;
    end else begin
      if (mutex_done == 0 && mutex_ready == 1 && mutex_file == 1) begin
        if (mutex_count == 0) begin
          $fopen(mutex_file, "r");
          mutex_miss <= 0;
        end
        if (mutex_offset == 0) begin
          $fseek(mutex_file, mutex_offset);
          mutex_miss <= 0;
        end
        if (mutex_count < 4 && mutex_size > mutex_offset) begin
          $fread(mutex_file, mutex_data);
          mutex[mutex_count] <= mutex_data;
          mutex_offset <= mutex_offset + 1;
          mutex_count <= mutex_count + 1;
