      d1_pre <= pre;
      d2_pre <= d1_pre;
      d3_pre <= d2_pre;
      d4_pre <= d3_pre;
      d5_pre <= d4_pre;
      d6_pre <= d5_pre;
      d7_pre <= d6_pre;
      d8_pre <= d7_pre;
      d9_pre <= d8_pre;
      new_rom <= d9_pre;
    end
  end

  // Output the data through the serial port
  assign q = mem_array[address];

  // Update the num_bytes signal
  assign num_bytes = mutex[1];

  // Update the safe signal
  always @(posedge clk) begin
    if (reset_n == 0) begin
