    .in1(rev_input1),
    .in2(rev_input2),
    .out(or_out)
  );

  // Output is a logical 1 only when both input values are logical 1s and their bitwise OR value is also a logical 1
  always @(*) begin
    if (nand_out & or_out) begin
      out <= 1;
    end else begin
      out <= 0;
    end
  end

