module binary_multiplier (
    input [7:0] A, // Input A for binary multiplier
    input [7:0] B, // Input B for binary multiplier
    output reg [15:0] product // Output product from binary multiplier
);

reg [7:0] partial_product [0:7];

integer i, j;

always @(*) begin
    for (i = 0; i < 8; i = i + 1) begin
        for (j = 0; j < 8; j = j + 1) begin
            partial_product[i+j] = partial_product[i+j] + (A[i] & B[j]);
        end
    end
end

always @(*) begin
    product = {partial_product[15], partial_product[14] + partial_product[13], partial_product[12] + partial_product[11], partial_product[10] + partial_product[9], partial_product[8] + partial_product[7], partial_product[6] + partial_product[5], partial_product[4] + partial_product[3], partial_product[2] + partial_product[1], partial_product[0]};
end

endmodule

module ripple_carry_adder (
    input [15:0] A,
    input [15:0] B,
    output reg [15:0] sum
);

reg carry;

always @(A or B) begin
    sum = A + B + carry;
    carry = (A[15] & B[15]) | (A[15] & carry) | (B[15] & carry);
end

endmodule

