    wire [31:0] and_out;
    wire carry_out;
    wire overflow;

    adder_subtractor add_sub(.a(a), .b(b), .sub_select(sub_select), .sum(add_out), .carry_out(carry_out), .overflow(overflow));
    functional_logic func(.in1(add_out), .in2(sub_out), .out(and_out), .carry_in(carry_out), .overflow_in(overflow));
    assign sub_out = add_sub.sub_out;

    assign sum = and_out;

endmodule

module adder_subtractor (
    input [31:0] a,
    input [31:0] b,
    input sub_select,
    output [31:0] sum,
    output carry_out,
    output overflow
);

    wire [31:0] sub_out;
    wire [31:0] add_out;
    wire [31:0] a_inv;
    wire [31:0] b_inv;
    wire [31:0] sub_b_inv;
    wire [31:0] sub_carry_in;
    wire [31:0] add_carry_in;
    wire [31:0] add_overflow;
    wire [31:0] sub_overflow;

    assign a_inv = ~a;
    assign b_inv = ~b;
    assign sub_b_inv = b_inv + 1;
    assign sub_carry_in = sub_select;
    assign add_carry_in = 0;

    adder add(.a(a), .b(b), .carry_in(add_carry_in), .sum(add_out), .carry_out(add_overflow));
    adder sub(.a(a), .b(sub_b_inv), .carry_in(sub_carry_in), .sum(sub_out), .carry_out(carry_out), .overflow(sub_overflow));

    assign sum = sub_select ? sub_out : add_out;
    assign overflow = sub_select ? sub_overflow : add_overflow;

endmodule

