module pipeline_module (
    input wire [3:0] vec,
    output wire [3:0] outv,
    output wire o3,
    output wire o2,
    output wire o1,
    output wire o0
);

reg [3:0] stage1_out;
reg [3:0] stage2_out;

assign o3 = stage1_out[3];
assign o2 = stage1_out[2];
assign o1 = stage1_out[1];
assign o0 = stage1_out[0];

