    stage1_out[3] = vec[3];
    stage1_out[2] = vec[2];
    stage1_out[1] = vec[1];
    stage1_out[0] = vec[0];
end

// Pipeline stage 2
always @(posedge clk) begin
    stage2_out[3] <= stage1_out[3];
    stage2_out[2] <= stage1_out[2];
    stage2_out[1] <= stage1_out[1];
    stage2_out[0] <= stage1_out[0];
end

// AND gate
wire and_out;
assign and_out = vec[2] & vec[1];

// Multiplexer
always @(posedge clk) begin
    if (sel) begin
        outv <= and_out;
    end else begin
        outv <= stage2_out;
    end
end

