module DAC (
  input [n-1:0] b,
  output reg V
);

parameter n = 4; // number of bits in the input binary number
parameter vref = 1.0; // reference voltage or current for the DAC

// Define the weighted resistor network
// The resistor values are calculated as R = vref / (2^n - 1)
// The weight of each bit is calculated as 2^(n-i-1)
// The output voltage is the sum of the weighted voltages across each resistor
wire [n-1:0] weights;
assign weights = {2**(n-1), 2**(n-2), 2**(n-3), 2**(n-4)};
wire [n-1:0] voltages;
assign voltages = weights * b;
wire [n-1:0] resistors;
assign resistors = vref / (2**n - 1);
wire [n-1:0] currents;
assign currents = voltages / resistors;
wire sum_current;
assign sum_current = currents[0] + currents[1] + currents[2] + currents[3];

// Compute the output voltage
// The output voltage is the sum of the weighted voltages across each resistor
always @(*) begin
  V = sum_current;
end

endmodule

