output [2:0] q1;
output [1:0] q2;
output [1:0] q3;

reg [2:0] q1_reg;
reg [1:0] q2_reg;
reg [1:0] q3_reg;

always @(posedge clk) begin
    if (reset) begin
        q1_reg <= 0;
        q2_reg <= 0;
        q3_reg <= 0;
    end else if (enable) begin
        if (q1_reg == 7) begin
            q1_reg <= 0;
            if (q2_reg == 3) begin
                q2_reg <= 0;
                if (q3_reg == 3) begin
                    q3_reg <= 0;
                end else begin
                    q3_reg <= q3_reg + 1;
                end
            end else begin
                q2_reg <= q2_reg + 1;
            end
        end else begin
            q1_reg <= q1_reg + 1;
        end
    end
end

assign q1 = q1_reg;
assign q2 = q2_reg;
assign q3 = q3_reg;

endmodule

module booth_multiplier (
    input [3:0] a,
    input [3:0] b,
    output reg [7:0] product
);

reg [4:0] m;
reg [4:0] a_shift;
reg [4:0] b_shift;
reg [1:0] count;

always @ (a or b) begin
    m = 5'b10001;
    a_shift = {a[3], a};
    b_shift = {b[3], b};
    product = 0;
    count = 2;
    while (count > 0) begin
        if (b_shift[1:0] == 2'b01) begin
            product = product + (a_shift << (count-1));
        end else if (b_shift[1:0] == 2'b10) begin
            product = product + (a_shift >> (count-1));
        end
        if (b_shift[0] == 1) begin
            b_shift = b_shift - m;
        end else if (b_shift[0] == 0) begin
            b_shift = b_shift + m;
        end
        count = count - 1;
    end
end

endmodule

