module barrel_shifter (
    input [3:0] data_in,
    input [1:0] shift_amount,
    input mode,
    output reg [3:0] shifted_data
);

always @(*) begin
    case (mode)
        2'b00: shifted_data = data_in << shift_amount;
        2'b01: shifted_data = data_in >> shift_amount;
        2'b10: shifted_data = {data_in[2:0], data_in[3]};
        2'b11: shifted_data = {data_in[0], data_in[3:1]};
    endcase
end

endmodule

