module final_output (
    input [3:0] shifted_data,
    input [3:0] twos_complement_out,
    output reg [7:0] final_out
);

always @(*) begin
    if (twos_complement_out[3] == 1) begin
        final_out = {8{1'b1}} - shifted_data + 1;
    end else begin
        final_out = shifted_data;
    end
end

endmodule

