module unsigned_multiplier (
    input [3:0] A,
    input [3:0] B,
    output reg [7:0] M,
    output reg V
);

    reg [3:0] A_reg;
    reg [3:0] B_reg;
    reg [7:0] M_reg;
    reg [3:0] partial_product;
    reg [4:0] stage;

    always @(posedge clk) begin
        if (stage == 0) begin
            A_reg <= A;
            B_reg <= B;
            partial_product <= A_reg * B_reg[0];
            M_reg <= {4'b0, partial_product};
            stage <= 1;
        end
        else if (stage == 1) begin
            partial_product <= A_reg * B_reg[1];
            M_reg <= {M_reg[3:0], partial_product[3:0]};
            stage <= 2;
        end
        else if (stage == 2) begin
            partial_product <= A_reg * B_reg[2];
            M_reg <= {M_reg[3:0], partial_product[3:0]};
            stage <= 3;
        end
        else if (stage == 3) begin
            partial_product <= A_reg * B_reg[3];
            M_reg <= {M_reg[3:0], partial_product[3:0]};
            stage <= 4;
        end
        else if (stage == 4) begin
            M <= M_reg;
            if (M_reg[7:4] != 0) begin
                V <= 1;
            end
            else begin
                V <= 0;
            end
            stage <= 0;
        end
    end

endmodule

module instdec (
input	[31:0]	cae_inst,
input	[63:0]	cae_data,
input		cae_inst_vld,

output		inst_val,
output	[4:0]	inst_caep,
output		inst_aeg_wr,
output		inst_aeg_rd,
output	[17:0]	inst_aeg_idx,

output		err_unimpl
);

    reg		c_val, c_aeg_wr, c_aeg_rd, c_unimpl;
    reg [4:0]	c_caep;
    reg [17:0]	c_aeg_idx;

    always @* begin
        c_val = 'b0;
        c_caep = 'b0;
        c_aeg_wr = 'b0;
        c_aeg_rd = 'b0;
        c_aeg_idx = 'b0;
        c_unimpl = 'b0;

        case (cae_inst[28:24])
            // Format 4 instructions
            5'b1101?: begin
                case (cae_inst[24:18])
                    7'h40: begin
                        c_aeg_idx = cae_inst[17:0];
                        c_aeg_wr  = cae_inst_vld;
                    end
                    7'h68: begin
                        c_aeg_idx = cae_data[17:0];
                        c_aeg_rd  = cae_inst_vld;
                    end
                    7'h70: begin
                        c_aeg_idx = {6'b0, cae_inst[17:6]};
                        c_aeg_rd  = cae_inst_vld;
                    end
                    default: c_unimpl = cae_inst_vld;
                endcase
            end
            // Format 5 instructions
            5'b11100: begin
                case (cae_inst[23:18])
                    6'h18, 6'h20: begin
                        c_aeg_idx = {6'b0, cae_inst[17:12], cae_inst[5:0]};
                        c_aeg_wr  = cae_inst_vld;
                    end
                    default: c_unimpl = cae_inst_vld;
                endcase
            end
            // Format 6 instructions
            5'b11101: begin
                case (cae_inst[23:18])
                    6'h1c: begin
                        c_aeg_idx = {6'b0, cae_inst[17:6]};
                        c_aeg_rd  = cae_inst_vld;
                    end
                    default: c_unimpl = cae_inst_vld;
                endcase
            end
            // Format 7 instructions
            5'b11110: begin
                if (cae_inst[23]) begin
                    c_caep   = cae_inst[22:18];
                    c_val    = cae_inst_vld;
                end else begin
                    c_unimpl = cae_inst_vld;
                end
            end
            default: c_unimpl = cae_inst_vld;
        endcase
    end

    assign inst_val = c_val;
    assign inst_caep = c_caep;
    assign inst_aeg_wr = c_aeg_wr;
    assign inst_aeg_rd = c_aeg_rd;
    assign inst_aeg_idx = c_aeg_idx;
    assign err_unimpl = c_unimpl;

endmodule

module EHR_4 (
    CLK,
    RST_N,
    read_0,
    write_0,
    EN_write_0,
    read_1,
    write_1,
    EN_write_1,
    read_2,
    write_2,
    EN_write_2,
    read_3,
    write_3,
    EN_write_3
);
    parameter            DATA_SZ = 1;
    parameter            RESET_VAL = 0;

    input                CLK;
    input                RST_N;
    output [DATA_SZ-1:0] read_0;
    input  [DATA_SZ-1:0] write_0;
    input                EN_write_0;
    output [DATA_SZ-1:0] read_1;
    input  [DATA_SZ-1:0] write_1;
    input                EN_write_1;
    output [DATA_SZ-1:0] read_2;
    input  [DATA_SZ-1:0] write_2;
    input                EN_write_2;
    output [DATA_SZ-1:0] read_3;
    input  [DATA_SZ-1:0] write_3;
    input                EN_write_3;

    reg    [DATA_SZ-1:0] r [0:3];
    wire   [DATA_SZ-1:0] wire_0;
    wire   [DATA_SZ-1:0] wire_1;
    wire   [DATA_SZ-1:0] wire_2;
    wire   [DATA_SZ-1:0] wire_3;
    wire   [DATA_SZ-1:0] wire_4;

    assign wire_0 = r[0];
    assign wire_1 = EN_write_0 ? write_0 : wire_0;
    assign wire_2 = EN_write_1 ? write_1 : wire_1;
    assign wire_3 = EN_write_2 ? write_2 : wire_2;
    assign wire_4 = EN_write_3 ? write_3 : wire_3;

    assign read_0 = wire_0;
    assign read_1 = wire_1;
    assign read_2 = wire_2;
    assign read_3 = wire_3;

    always @(posedge CLK) begin
        if (RST_N == 0) begin
            r[0] <= RESET_VAL;
            r[1] <= RESET_VAL;
            r[2] <= RESET_VAL;
            r[3] <= RESET_VAL;
        end else begin
            if (EN_write_0) r[0] <= write_0;
            if (EN_write_1) r[1] <= write_1;
            if (EN_write_2) r[2] <= write_2;
            if (EN_write_3) r[3] <= write_3;
        end
    end
endmodule

module excess_3_converter (
    input [4:0] bcd,
    input mode,
    output reg [7:0] excess_3
);

reg [3:0] bcd_digit [0:4];
reg [3:0] excess_3_digit [0:4];
reg [1:0] stage;

always @(*) begin
    case (stage)
        0: begin
            bcd_digit[0] = bcd[3:0];
            excess_3_digit[0] = bcd[3:0] + (mode ? 5 : 3);
            stage = 1;
        end
        1: begin
            bcd_digit[1] = bcd[7:4];
            excess_3_digit[1] = bcd[7:4] + (mode ? 5 : 3);
            stage = 2;
        end
        2: begin
            bcd_digit[2] = bcd[11:8];
            excess_3_digit[2] = bcd[11:8] + (mode ? 5 : 3);
            stage = 3;
        end
        3: begin
            bcd_digit[3] = bcd[15:12];
            excess_3_digit[3] = bcd[15:12] + (mode ? 5 : 3);
            stage = 4;
        end
        4: begin
            bcd_digit[4] = bcd[19:16];
            excess_3_digit[4] = bcd[19:16] + (mode ? 5 : 3);
            stage = 0;
        end
    endcase
end

always @(posedge clk) begin
    excess_3 = {excess_3_digit[4], excess_3_digit[3], excess_3_digit[2], excess_3_digit[1], excess_3_digit[0], 2'b11};
end

endmodule

module MUX4x1 (I0, I1, I2, I3, S0, S1, Y);

   input I0, I1, I2, I3, S0, S1;
   output Y;

   wire notS0, notS1;

   NOT XIL_NOT_0 (.I(S0), .O(notS0));
   NOT XIL_NOT_1 (.I(S1), .O(notS1));

   wire and0, and1, and2, and3, and4, and5;

   AND2 XIL_AND2_0 (.I0(I0), .I1(notS0), .O(and0));
   AND2 XIL_AND2_1 (.I0(I1), .I1(S1), .O(and1));
   AND2 XIL_AND2_2 (.I0(I2), .I1(S0), .O(and2));
   AND2 XIL_AND2_3 (.I0(I3), .I1(S0), .O(and3));
   AND2 XIL_AND2_4 (.I0(I3), .I1(S1), .O(and4));
   AND2 XIL_AND2_5 (.I0(I2), .I1(notS0), .O(and5));

   wire or0, or1;

   OR2 XIL_OR2_0 (.I0(and0), .I1(and1), .O(or0));
   OR2 XIL_OR2_1 (.I0(and2), .I1(and3), .O(or1));

   OR2 XIL_OR2_2 (.I0(and4), .I1(and5), .O(Y));

   // End of module
endmodule

module Memory #(
    parameter SIZE = 4096
    ) (
    input wire clock,
    input wire [31:0] Address,
    input wire ReadEnable,
    output wire [31:0] ReadData,
    input wire WriteEnable,
    input wire [31:0] WriteData
    );

    // memory
    //
    // active SIZE words, from 12 address LSBs

    reg [31:0] data[SIZE - 1:0];

    always @(ReadEnable, WriteEnable)
        if (ReadEnable && WriteEnable) begin
            $display ("\nDataMemory ERROR (time %0d):", $time);
            $display ("ReadEnable and WriteEnable both active\n");
        end

    always @(posedge ReadEnable, posedge WriteEnable)
        if (Address[31:12]) begin
            $display("\nDataMemory WARNING (time %0d):", $time);
            $display("unused address MSBs not zero\n");
        end

    assign ReadData = (~WriteEnable && ReadEnable) ? data[Address[11:0]] : 32'bx;

    always @(negedge clock)
        if (~ReadEnable && WriteEnable) begin
            data[Address[11:0]] <= WriteData;

            $display("DataMemory:");
            $display("\twrote data %2d to address %2d at time %3d\n",
                WriteData, Address[11:0], $time);
        end

endmodule

module binary_to_bcd(
    input [7:0] binary,
    output [11:0] bcd
);

reg [3:0] digit1;
reg [3:0] digit2;
reg [3:0] digit3;

always @ (binary) begin
    if (binary >= 100) begin
        digit1 = binary / 100;
        digit2 = (binary % 100) / 10;
        digit3 = binary % 10;
    end else if (binary >= 10) begin
        digit1 = 0;
        digit2 = binary / 10;
        digit3 = binary % 10;
    end else begin
        digit1 = 0;
        digit2 = 0;
        digit3 = binary;
    end
end

assign bcd = {digit1, digit2, digit3};

endmodule

module data_adapter (
