);
    wire [31:0] functional_out;
    wire [31:0] adder_subtractor_out_wire;
    wire anyedge_wire;
    wire carry_out_wire;

    anyedge_detector anyedge_detector_inst (
        .clk(clk),
        .in(in),
        .anyedge(anyedge_wire)
    );

    adder_subtractor adder_subtractor_inst (
        .a(a),
        .b(b),
        .sub(select),
        .result(adder_subtractor_out_wire),
        .carry_out(carry_out_wire)
    );

    functional_module functional_module_inst (
        .anyedge(anyedge_wire),
        .adder_subtractor_out(adder_subtractor_out_wire),
        .final_output(functional_out)
    );

    always @(*) begin
        if (select) begin
            active_module_out = adder_subtractor_out;
        end else begin
            active_module_out = functional_out;
        end
    end
endmodule

module top_module (
    input clk,
    input reset,
    input [7:0] in,
    input [31:0] a,
    input [31:0] b,
    input select,
    output reg [31:0] final_output
);
    wire anyedge;
    wire [31:0] adder_subtractor_out;
    wire carry_out;
    wire [31:0] active_module_out;

    control_logic control_logic_inst (
        .select(select),
        .anyedge(anyedge),
        .carry_out(carry_out),
        .adder_subtractor_out(adder_subtractor_out),
        .active_module_out(active_module_out)
    );

