        if (btnm) begin
            if (~b_state) begin
                b_state = 1;
                case (state)
                    numA: if (code > 9 && code < 15) state = numB;
                    numB: if (code == 15) state = numC;
                    numC: if (code == 16) state = numA;
                    default: state = numA;
                endcase
            end
        end else begin
            b_state = 0;
        end
    end

    always @(state) begin
        case (state)
            numA: new = num_a;
            numB: new = num_b;
            numC: new = result;
            default: new = num_a;
        endcase
        if (new[31]) begin
            for (i = 0; i < 32; i = i + 1) begin
                num_out[i] = ~new[i];
            end
