    assign c[4] = g[4] | (p[4] & carry[4]);
    assign c[3] = g[3] | (p[3] & carry[3]);
    assign c[2] = g[2] | (p[2] & carry[2]);
    assign c[1] = g[1] | (p[1] & carry[1]);
    assign c[0] = g[0] | (p[0] & carry[0]);

    wire [15:0] sum_temp;

    adder_16bit adder1(
        .a(a[15:0]),
        .b(b[15:0]),
        .c_in(c[0]),
        .c_out(carry[1]),
        .sum(sum_temp[15])
    );

    adder_16bit adder2(
        .a(a[31:16]),
        .b(b[31:16]),
        .c_in(carry[1]),
        .c_out(carry[16]),
        .sum(sum_temp[31:16])
    );

    assign sum = reset ? 32'b0 : {sum_temp[31:16], sum_temp[15:0]};

