module adder_16bit(
    input [15:0] a,
    input [15:0] b,
    input c_in,
    output c_out,
    output [15:0] sum
);

    wire [15:0] g;
    wire [15:0] p;

    assign {c_out, g[15], p[15]} = {1'b0, a[15] & b[15], a[15] ^ b[15]};
