    assign {c_out, g[10], p[10]} = {c_out, a[10] & b[10], a[10] ^ b[10]};
    assign {c_out, g[9], p[9]} = {c_out, a[9] & b[9], a[9] ^ b[9]};
    assign {c_out, g[8], p[8]} = {c_out, a[8] & b[8], a[8] ^ b[8]};
