    assign {c_out, g[6], p[6]} = {c_out, a[6] & b[6], a[6] ^ b[6]};
    assign {c_out, g[5], p[5]} = {c_out, a[5] & b[5], a[5] ^ b[5]};
    assign {c_out, g[4], p[4]} = {c_out, a[4] & b[4], a[4] ^ b[4]};
    assign {c_out, g[3], p[3]} = {c_out, a[3] & b[3], a[3] ^ b[3]};
    assign {c_out, g[2], p[2]} = {c_out, a[2] & b[2], a[2] ^ b[2]};
    assign {c_out, g[1], p[1]} = {c_out, a[1] & b[1], a[1] ^ b[1]};
    assign {c_out, g[0], p[0]} = {c_out, a[0] & b[0], a[0] ^ b[0]};

    assign sum = p ^ c_out;

