        case (in)
            2'b00: begin
                out0 = 1;
                out1 = 0;
                out2 = 0;
                out3 = 0;
            end
            2'b01: begin
                out0 = 0;
                out1 = 1;
                out2 = 0;
                out3 = 0;
            end
            2'b10: begin
                out0 = 0;
                out1 = 0;
                out2 = 1;
                out3 = 0;
            end
            2'b11: begin
                out0 = 0;
                out1 = 0;
                out2 = 0;
                out3 = 1;
            end
        endcase
    end

endmodule

