module fifo(Clk, RstN, Data_In, FClrN, FInN, FOutN, F_Data, F_FullN, F_LastN, F_SLastN, F_FirstN, F_EmptyN);

  parameter FWIDTH = 8; // data width
  parameter FDEPTH = 16; // depth of FIFO
  parameter FCWIDTH = $clog2(FDEPTH); // counter width

  input Clk; // clock signal
  input RstN; // active low reset signal
  input [FWIDTH-1:0] Data_In; // data into FIFO
  input FClrN; // active low clear signal to clear FIFO
  input FInN; // active low write signal to write data into FIFO
  input FOutN; // active low read signal to read data from FIFO

  output reg [FWIDTH-1:0] F_Data; // data out from FIFO
  output reg F_FullN; // active low signal indicating if FIFO is full
  output reg F_LastN; // active low signal indicating if FIFO has one data left
  output reg F_SLastN; // active low signal indicating if FIFO has two data left
  output reg F_FirstN; // active low signal indicating if FIFO has only one data
  output reg F_EmptyN; // active low signal indicating if FIFO is empty

  reg [FCWIDTH-1:0] rd_ptr; // current read pointer
  reg [FCWIDTH-1:0] wr_ptr; // current write pointer
  reg [FCWIDTH:0] fcounter; // counter indicates num of data in FIFO

  wire [FWIDTH-1:0] FIFODataOut; // data out from FIFO memory block
  wire [FWIDTH-1:0] FIFODataIn; // data into FIFO memory block
  wire ReadN = FOutN; // read signal
  wire WriteN = FInN; // write signal

  assign F_Data = FIFODataOut;
  assign FIFODataIn = Data_In;

  // FIFO memory block
  FIFO_MEM_BLK memblk(
    .clk(Clk),
    .writeN(WriteN),
    .rd_addr(rd_ptr),
    .wr_addr(wr_ptr),
    .data_in(FIFODataIn),
    .data_out(FIFODataOut)
  );

  // reset signals
  always @(posedge Clk, negedge RstN) begin
    if (!RstN) begin
      F_EmptyN <= 1'b1;
      F_FullN <= 1'b0;
      F_FirstN <= 1'b1;
      F_LastN <= 1'b0;
      F_SLastN <= 1'b0;
      fcounter <= 0;
      rd_ptr <= 0;
      wr_ptr <= 0;
    end
    else begin
      if (!FClrN) begin
        F_EmptyN <= 1'b1;
        F_FullN <= 1'b0;
        F_FirstN <= 1'b1;
        F_LastN <= 1'b0;
        F_SLastN <= 1'b0;
        fcounter <= 0;
        rd_ptr <= 0;
        wr_ptr <= 0;
      end
    end
  end

  // update FIFO status signals
  always @(posedge Clk, negedge RstN) begin
    if (!RstN) begin
      F_EmptyN <= 1'b0;
      F_FullN <= 1'b1;
      F_FirstN <= 1'b1;
      F_LastN <= 1'b0;
      F_SLastN <= 1'b0;
    end
    else begin
      if (FClrN) begin
        if (fcounter == 0) begin
          F_EmptyN <= 1'b1;
          F_FullN <= 1'b0;
          F_FirstN <= 1'b1;
          F_LastN <= 1'b0;
          F_SLastN <= 1'b0;
        end
        else if (fcounter == FDEPTH) begin
          F_EmptyN <= 1'b0;
          F_FullN <= 1'b1;
          F_FirstN <= 1'b0;
          F_LastN <= 1'b1;
          F_SLastN <= 1'b0;
        end
        else if (fcounter == FDEPTH - 1) begin
          F_EmptyN <= 1'b0;
          F_FullN <= 1'b0;
          F_FirstN <= 1'b0;
          F_LastN <= 1'b1;
          F_SLastN <= 1'b0;
        end
        else if (fcounter == FDEPTH - 2) begin
          F_EmptyN <= 1'b0;
          F_FullN <= 1'b0;
          F_FirstN <= 1'b0;
          F_LastN <= 1'b0;
          F_SLastN <= 1'b1;
        end
        else begin
          F_EmptyN <= 1'b0;
          F_FullN <= 1'b0;
          F_FirstN <= 1'b0;
          F_LastN <= 1'b0;
          F_SLastN <= 1'b0;
        end
      end
    end
  end

  // update read and write pointers
  always @(posedge Clk, negedge RstN) begin
    if (!RstN) begin
      rd_ptr <= 0;
      wr_ptr <= 0;
    end
    else begin
      if (FClrN) begin
        if (!ReadN && F_EmptyN) begin
          rd_ptr <= 0;
        end
        else if (!WriteN && F_FullN) begin
          wr_ptr <= 0;
        end
        else if (!WriteN && ReadN && F_FullN) begin
          wr_ptr <= wr_ptr + 1;
        end
        else if (WriteN && !ReadN && F_EmptyN) begin
          rd_ptr <= rd_ptr + 1;
        end
      end
    end
  end

  // update counter
  always @(posedge Clk, negedge RstN) begin
    if (!RstN) begin
      fcounter <= 0;
    end
    else begin
      if (FClrN) begin
        if (!WriteN && ReadN && F_FullN) begin
          fcounter <= fcounter - 1;
        end
        else if (WriteN && !ReadN && F_EmptyN) begin
          fcounter <= fcounter + 1;
        end
      end
    end
  end

endmodule

