module interrupt_controller (
  input [n-1:0] irq,
  output [m-1:0] int
);

  parameter n = 4; // number of interrupt requests
  parameter m = 2; // number of interrupt signals

  reg [n-1:0] irq_priority;
  reg [n-1:0] irq_enable;
  reg [n-1:0] irq_pending;
  reg [n-1:0] irq_ack;
  reg [m-1:0] int_priority;
  reg [m-1:0] int_enable;
  reg [m-1:0] int_pending;
  reg [m-1:0] int_ack;
  reg [m-1:0] int_rr;
  reg [n-1:0] irq_rr;
  reg [m-1:0] int_rr_enable;
  reg [m-1:0] int_rr_pending;

  integer i;

  always @ (posedge clk) begin
    // Set interrupt priority levels
    irq_priority[0] = 3; // highest priority
    irq_priority[1] = 2;
    irq_priority[2] = 1;
    irq_priority[3] = 0; // lowest priority

    // Enable interrupts
    irq_enable = irq;

    // Determine pending interrupts
    irq_pending = irq_enable & ~irq_ack;

    // Determine interrupt priorities
    for (i = 0; i < m; i = i + 1) begin
      int_priority[i] = 0;
      for (j = 0; j < n; j = j + 1) begin
        if (irq_pending[j] && (irq_priority[j] == i)) begin
          int_priority[i] = 1;
        end
      end
    end

    // Enable interrupts based on priority
    int_enable = int_priority & ~int_ack;

    // Determine pending interrupts based on priority
    int_pending = int_enable & ~int_rr_enable;

    // Determine round-robin interrupts
    int_rr = 0;
    for (i = 0; i < m; i = i + 1) begin
      if (int_pending[i]) begin
        int_rr[i] = 1;
        int_rr_enable[i] = 1;
        irq_rr[i] = 0;
        for (j = 0; j < n; j = j + 1) begin
          if (irq_pending[j] && (irq_priority[j] == i)) begin
            irq_rr[j] = 1;
          end
        end
      end
    end

    // Generate interrupt signals
    int = int_priority & int_enable;

    // Generate interrupt acknowledge signals
    irq_ack = irq_rr;
    int_ack = int_rr_enable & int_pending;
  end

endmodule

