module division_and_twos_complement (
    input clk,
    input rst_n,
    input en,
    input [3:0] in,
    output reg [3:0] out
); 

// Inputs for division module
input [3:0] dividend;
input [3:0] divisor;

// Outputs for division module
output reg [3:0] quotient;
output reg [3:0] remainder;

// Outputs for twos complement module
output reg [3:0] twos_complement;

// Instantiate division module
division_module division (
    .clk(clk),
    .rst_n(rst_n),
    .dividend(dividend),
    .divisor(divisor),
    .quotient(quotient),
    .remainder(remainder)
);

// Calculate twos complement of quotient and remainder sum
always @ (posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        twos_complement <= 4'b0000;
    end else begin
        if (en) begin
            twos_complement <= ~(quotient + remainder) + 1;
        end
    end
end

// Output twos complement or 0 based on enable input
always @ (posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        out <= 4'b0000;
    end else begin
        if (en) begin
            out <= twos_complement;
        end else begin
            out <= 4'b0000;
        end
    end
end

endmodule

