    output reg out_always_ff
);
    wire [7:0] dff_outputs;
    wire xor_output;

    xor_module xor_inst (
        .a(a),
        .b(1'b1),
        .clk(clk),
        .out_always_ff(xor_output)
    );

    genvar i;
    generate
        for (i = 0; i < 8; i = i + 1) begin : dff_generate
            dff_module dff_inst (
                .clk(clk),
                .d(d[i]),
                .q(dff_outputs[i])
            );
        end
    endgenerate

    and_module and_inst (
        .dff_outputs(dff_outputs),
        .xor_output(xor_output),
        .out_always_ff(out_always_ff)
    );
