module memory_controller #
(
    parameter WIDTH_D = 256,
    parameter S_WIDTH_A = 26,
    parameter M_WIDTH_A = S_WIDTH_A+$clog2(WIDTH_D/8),
    parameter BURSTCOUNT_WIDTH = 6,
    parameter BYTEENABLE_WIDTH = WIDTH_D,
    parameter MAX_PENDING_READS = 64
)
(
    input clk,
    input resetn,

    // Slave port
    input [S_WIDTH_A-1:0] slave_address,  // Word address
    input [WIDTH_D-1:0] slave_writedata,
    input slave_read,
    input slave_write,
    input [BURSTCOUNT_WIDTH-1:0] slave_burstcount,
    input [BYTEENABLE_WIDTH-1:0] slave_byteenable,
    output slave_waitrequest,
    output [WIDTH_D-1:0] slave_readdata,
    output slave_readdatavalid,

    output [M_WIDTH_A-1:0] master_address,  // Byte address
    output [WIDTH_D-1:0] master_writedata,
    output master_read,
    output master_write,
    output [BURSTCOUNT_WIDTH-1:0] master_burstcount,
    output [BYTEENABLE_WIDTH-1:0] master_byteenable,
    input master_waitrequest,
    input [WIDTH_D-1:0] master_readdata,
    input master_readdatavalid
);

// Internal signals
reg [S_WIDTH_A-1:0] mem_address;
reg [BURSTCOUNT_WIDTH-1:0] mem_burstcount;
reg [WIDTH_D-1:0] mem_readdata;
reg [MAX_PENDING_READS-1:0] read_data_queue [$clog2(MAX_PENDING_READS)-1:0];
reg [MAX_PENDING_READS-1:0] read_valid_queue [$clog2(MAX_PENDING_READS)-1:0];
reg [MAX_PENDING_READS-1:0] read_byteenable_queue [$clog2(MAX_PENDING_READS)-1:0];
reg [MAX_PENDING_READS-1:0] read_pending;
reg [S_WIDTH_A-1:0] read_address_queue [$clog2(MAX_PENDING_READS)-1:0];
reg [BURSTCOUNT_WIDTH-1:0] read_burstcount_queue [$clog2(MAX_PENDING_READS)-1:0];
reg read_queue_empty;
reg read_queue_full;

// Slave port
assign slave_waitrequest = read_queue_full;
assign slave_readdata = mem_readdata;
assign slave_readdatavalid = read_valid_queue[0];

// Master port
assign master_address = {mem_address, {$clog2(WIDTH_D/8){1'b0}}}; // byte address
assign master_writedata = slave_writedata;
assign master_read = read_pending[0];
assign master_write = slave_write;
assign master_burstcount = mem_burstcount;
assign master_byteenable = slave_byteenable;

// Burst operation
always @(posedge clk) begin
    if (!resetn) begin
        mem_address <= 0;
        mem_burstcount <= 0;
        mem_readdata <= 0;
        read_queue_empty <= 1;
        read_queue_full <= 0;
        read_pending <= 0;
        read_data_queue <= 0;
        read_valid_queue <= 0;
        read_byteenable_queue <= 0;
        read_address_queue <= 0;
        read_burstcount_queue <= 0;
    end else begin
        if (slave_read && !read_queue_full) begin
            read_data_queue[0] <= mem_readdata;
            read_valid_queue[0] <= 1;
            read_byteenable_queue[0] <= slave_byteenable;
            read_address_queue[0] <= slave_address;
            read_burstcount_queue[0] <= slave_burstcount;
            read_pending[0] <= 1;
            read_queue_empty <= 0;
            if (read_queue_full) begin
                read_queue_full <= 0;
            end else begin
                read_queue_full <= (read_pending == MAX_PENDING_READS);
            end
        end
        if (read_pending[0] && master_waitrequest) begin
            read_data_queue <= {read_data_queue[1:$clog2(MAX_PENDING_READS)], mem_readdata};
            read_valid_queue <= {read_valid_queue[1:$clog2(MAX_PENDING_READS)], 0};
            read_byteenable_queue <= {read_byteenable_queue[1:$clog2(MAX_PENDING_READS)], 0};
            read_address_queue <= {read_address_queue[1:$clog2(MAX_PENDING_READS)], read_address_queue[0]};
            read_burstcount_queue <= {read_burstcount_queue[1:$clog2(MAX_PENDING_READS)], read_burstcount_queue[0]};
            read_pending <= {read_pending[1:$clog2(MAX_PENDING_READS)], 0};
            read_queue_empty <= (read_pending == 0);
            if (read_queue_full) begin
                read_queue_full <= 0;
            end
        end
        if (slave_write) begin
            mem_address <= slave_address;
            mem_burstcount <= slave_burstcount;
            mem_readdata <= 0;
            read_data_queue <= 0;
            read_valid_queue <= 0;
            read_byteenable_queue <= 0;
            read_address_queue <= 0;
            read_burstcount_queue <= 0;
            read_pending <= 0;
            read_queue_empty <= 1;
            read_queue_full <= 0;
        end
    end
end

// Read operation
always @(posedge clk) begin
    if (!resetn) begin
        mem_address <= 0;
        mem_burstcount <= 0;
        mem_readdata <= 0;
    end else begin
        if (read_pending[0] && !master_waitrequest) begin
            mem_address <= read_address_queue[0];
            mem_burstcount <= read_burstcount_queue[0];
            mem_readdata <= read_data_queue[0];
            read_data_queue <= {read_data_queue[1:$clog2(MAX_PENDING_READS)], 0};
            read_valid_queue <= {read_valid_queue[1:$clog2(MAX_PENDING_READS)], 0};
            read_byteenable_queue <= {read_byteenable_queue[1:$clog2(MAX_PENDING_READS)], 0};
            read_address_queue <= {read_address_queue[1:$clog2(MAX_PENDING_READS)], 0};
            read_burstcount_queue <= {read_burstcount_queue[1:$clog2(MAX_PENDING_READS)], 0};
            read_pending <= {read_pending[1:$clog2(MAX_PENDING_READS)], 0};
            read_queue_empty <= (read_pending == 0);
            if (read_queue_full) begin
                read_queue_full <= 0;
            end
        end
    end
end

// Queue control
always @(posedge clk) begin
    if (!resetn) begin
        read_queue_empty <= 1;
        read_queue_full <= 0;
    end else begin
        if (slave_read && !read_queue_full) begin
            read_queue_full <= (read_pending == MAX_PENDING_READS);
        end
        if (read_pending[0] && master_waitrequest) begin
            read_queue_full <= 0;
        end
    end
end

endmodule

module counter_register (
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] data, // 8-bit input for the register
    input select,     // Select input to choose between register and counter
    output reg [7:0] sum  // 8-bit output from the system
);

    reg [3:0] counter;  // 4-bit binary counter
    reg [7:0] register; // 8-bit register

    always @(posedge clk) begin
        if (reset) begin
            counter <= 4'b0;
            register <= 8'b0;
            sum <= 8'b0;
        end else begin
            if (select) begin
                register <= data;
                sum <= register + counter;
            end else begin
                counter <= counter + 1;
                sum <= register + counter;
            end
        end
    end

endmodule

