module RS_encoder_decoder (
  input [k-1:0] data_in,
  input [n-k-1:0] pad_in,
  input [3:0] num_errors,
  output [n-1:0] encoded_data,
  output [k-1:0] corrected_data
);

parameter n = 255; // length of data block
parameter k = 223; // number of information bits in data block
parameter t = 8; // number of errors that can be corrected
parameter gf_poly = 301; // generator polynomial for Galois field

// Encoder
reg [n-k-1:0] pad = pad_in;
reg [n-1:0] data = {data_in, pad};
reg [n-k-t-1:0] parity;

// Compute generator polynomial for Galois field
reg [n-k-t-1:0] gen_poly;
reg [n-k-t-1:0] alpha_pow;
reg [n-k-t-1:0] temp_poly;
integer i, j;

initial begin
  alpha_pow[0] = 1;
  for (i = 1; i < n-k-t; i = i + 1) begin
    alpha_pow[i] = alpha_pow[i-1] << 1;
    if (alpha_pow[i-1][n-k-t-1] == 1) begin
      alpha_pow[i] = alpha_pow[i] ^ gf_poly;
    end
  end

  gen_poly[0] = 1;
  for (i = 1; i <= t; i = i + 1) begin
    gen_poly[i] = 0;
    for (j = 0; j < n-k-t; j = j + 1) begin
      if (i == 1) begin
        temp_poly[j] = alpha_pow[j];
      end else begin
        temp_poly[j] = gen_poly[j+1];
      end
    end
    gen_poly = temp_poly ^ (alpha_pow[i-1] * gen_poly[t-1]);
  end
end

// Compute parity bits
always @* begin
  for (i = 0; i < n-k-t; i = i + 1) begin
    parity[i] = data[n-k-1];
    for (j = n-k-2; j >= 0; j = j - 1) begin
      parity[i] = parity[i] ^ (data[j] & alpha_pow[i+j+1-n+k+t]);
    end
  end
end

// Output encoded data
assign encoded_data = {data, parity};

// Decoder
reg [n-1:0] received_data;
reg [n-k-t-1:0] syndromes;
reg [n-k-t-1:0] error_locator_poly;
reg [n-k-t-1:0] error_locator_poly_old;
reg [n-k-t-1:0] error_evaluator_poly;
reg [n-k-t-1:0] error_evaluator_poly_old;
reg [k-1:0] error_locations;
reg [n-k-1:0] error_magnitudes;
reg [n-k-1:0] corrected_data_temp;
integer error_count, s, i, j;

// Compute syndromes
always @* begin
  for (s = 0; s < n-k-t; s = s + 1) begin
    syndromes[s] = received_data[n-1];
    for (i = n-2; i >= 0; i = i - 1) begin
      syndromes[s] = syndromes[s] ^ (received_data[i] & alpha_pow[(i+1)*(s+1)-1]);
    end
  end
end

// Compute error locator polynomial
always @* begin
  error_locator_poly = 1;
  error_locator_poly_old = 1;
  error_evaluator_poly = 0;
  error_evaluator_poly_old = 0;
  error_count = 0;
  for (i = 0; i < n-k-t; i = i + 1) begin
    error_evaluator_poly_old = error_evaluator_poly;
    error_locator_poly_old = error_locator_poly;
    error_evaluator_poly = 0;
    error_locator_poly = 0;
    for (j = 0; j <= error_count; j = j + 1) begin
      error_evaluator_poly = error_evaluator_poly ^ (error_locator_poly_old[j] & syndromes[i-j]);
    end
    if (error_evaluator_poly == 0) begin
      error_locator_poly = error_locator_poly_old;
    end else if (error_count == 0) begin
      error_locator_poly[0] = 1;
      error_locator_poly[1] = alpha_pow[i];
      error_count = 1;
    end else begin
      for (j = 0; j <= error_count; j = j + 1) begin
        error_locator_poly[j+1] = error_locator_poly_old[j] ^ (error_evaluator_poly * error_locator_poly_old[error_count-j] * alpha_pow[i]);
      end
      error_count = error_count + 1;
    end
  end
end

// Compute error locations and magnitudes
always @* begin
  error_locations = 0;
  error_magnitudes = 0;
  for (i = 0; i < n-k-t; i = i + 1) begin
    if (error_locator_poly[i] == 1) begin
      error_locations[error_count] = n-k-t-i-1;
      error_magnitudes[error_count] = error_evaluator_poly[i];
      error_count = error_count + 1;
    end
  end
end

// Correct errors
always @* begin
  corrected_data_temp = received_data;
  for (i = 0; i < error_count; i = i + 1) begin
    corrected_data_temp[error_locations[i]] = corrected_data_temp[error_locations[i]] ^ error_magnitudes[i];
  end
  corrected_data = corrected_data_temp[k-1:0];
end

endmodule

module DP_RAM16K (
    input rclk, 
    input wclk,
    input wen,
    input ren,
    input[8:0] waddr,
    input[8:0] raddr,
    input[31:0] d_in,
    input[31:0] wenb,
    output[31:0] d_out );

    reg [31:0] ram [0:16383];
    reg [31:0] d_out;

    always @(posedge wclk) begin
        if (wen) begin
            if (wenb[3:0] == 4'b0000) ram[waddr][31:0] <= d_in[31:0];
            else if (wenb[3:0] == 4'b0001) ram[waddr][7:0] <= d_in[7:0];
            else if (wenb[3:0] == 4'b0010) ram[waddr][15:8] <= d_in[7:0];
            else if (wenb[3:0] == 4'b0100) ram[waddr][23:16] <= d_in[7:0];
            else if (wenb[3:0] == 4'b1000) ram[waddr][31:24] <= d_in[7:0];
            else if (wenb[3:0] == 4'b0011) ram[waddr][15:0] <= d_in[15:0];
            else if (wenb[3:0] == 4'b1100) ram[waddr][31:16] <= d_in[15:0];
            else if (wenb[3:0] == 4'b1111) ram[waddr] <= d_in;
        end
    end

    always @(posedge rclk) begin
        if (!ren) begin
            if (wenb[3:0] == 4'b0000) d_out <= ram[raddr][31:0];
            else if (wenb[3:0] == 4'b0001) d_out <= ram[raddr][7:0];
            else if (wenb[3:0] == 4'b0010) d_out <= ram[raddr][15:8];
            else if (wenb[3:0] == 4'b0100) d_out <= ram[raddr][23:16];
            else if (wenb[3:0] == 4'b1000) d_out <= ram[raddr][31:24];
            else if (wenb[3:0] == 4'b0011) d_out <= ram[raddr][15:0];
            else if (wenb[3:0] == 4'b1100) d_out <= ram[raddr][31:16];
            else if (wenb[3:0] == 4'b1111) d_out <= ram[raddr];
        end
    end

endmodule

module clock_gate(
  input CLK,
  input EN,
  input TE,
  output reg ENCLK
);

  always @(posedge CLK) begin
    if (TE) begin
      // Test enable, always pass through clock signal
      ENCLK <= 1'b1;
    end else begin
      // Normal operation
      if (EN) begin
        // Enable signal is high, pass through clock signal
        ENCLK <= 1'b1;
      end else begin
        // Enable signal is low, hold output low
        ENCLK <= 1'b0;
      end
    end
  end

endmodule

module binary_counter (
