);

  reg [3:0] count;

  always @(posedge CLK) begin
    if (RST) begin
      count <= 4'b0000;
    end else begin
      count <= count + 1;
    end
  end

  assign Q = count;

endmodule

module fifo_buffer (
    input clk,
    input reset,
    input write,
    input read,
    input clear,
    input [31:0] data_in,
    output [31:0] data_out,
    output almost_full,
    output full,
    output almost_empty,
    output empty
);

parameter DEPTH = 8;

reg [31:0] buffer [0:DEPTH-1];
reg [2:0] count;
reg [2:0] read_pointer;
reg [2:0] write_pointer;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        count <= 0;
        read_pointer <= 0;
        write_pointer <= 0;
    end else if (clear) begin
        count <= (read != write);
        read_pointer <= (read) ? 1'b1 : read_pointer;
        write_pointer <= (write) ? 1'b1 : write_pointer;
    end else if (read != write) begin
        count <= (read > write) ? (DEPTH - read + write) : (write - read);
        read_pointer <= (read_pointer == DEPTH-1) ? 0 : read_pointer + 1'b1;
        write_pointer <= (write_pointer == DEPTH-1) ? 0 : write_pointer + 1'b1;
    end
end

assign empty = (count == 0);
assign full = (count == DEPTH);
assign almost_empty = (count <= 1);
assign almost_full = (count >= DEPTH-1);

always @(posedge clk) begin
    if (clear) begin
        data_out <= buffer[0];
    end else if (read != write) begin
        data_out <= buffer[read_pointer];
    end
end

always @(posedge clk) begin
    if (write && !full) begin
        buffer[write_pointer] <= data_in;
    end
end

endmodule

module binary_to_bcd (
    input [2:0] D,
    output reg [3:0] BCD
);

reg [3:0] BCD_reg;
reg [2:0] remainder;

always @(*) begin
    BCD_reg = 0;
    remainder = D;
end

// Pipeline Stage 1
always @(*) begin
    case(remainder)
        3'b000: BCD_reg = 4'b0000;
        3'b001: BCD_reg = 4'b0001;
        3'b010: BCD_reg = 4'b0010;
        3'b011: BCD_reg = 4'b0011;
        3'b100: BCD_reg = 4'b0100;
        3'b101: BCD_reg = 4'b0101;
        3'b110: BCD_reg = 4'b0110;
        3'b111: BCD_reg = 4'b0111;
    endcase
end

// Pipeline Stage 2
always @(posedge clk) begin
    remainder = BCD_reg[3:0];
end

// Pipeline Stage 3
always @(*) begin
    case(remainder)
        3'b000: BCD_reg = BCD_reg;
        3'b001: BCD_reg = BCD_reg + 4'b0011;
        3'b010: BCD_reg = BCD_reg + 4'b0110;
        3'b011: BCD_reg = BCD_reg + 4'b1001;
        3'b100: BCD_reg = BCD_reg + 4'b1100;
        3'b101: BCD_reg = BCD_reg + 4'b1111;
        3'b110: BCD_reg = BCD_reg + 4'b0010;
        3'b111: BCD_reg = BCD_reg + 4'b0101;
    endcase
end

// Pipeline Stage 4
always @(posedge clk) begin
    remainder = BCD_reg[3:0];
end

// Pipeline Stage 5
always @(*) begin
    case(remainder)
        3'b000: BCD_reg = BCD_reg;
        3'b001: BCD_reg = BCD_reg + 4'b0011;
        3'b010: BCD_reg = BCD_reg + 4'b0110;
        3'b011: BCD_reg = BCD_reg + 4'b1001;
        3'b100: BCD_reg = BCD_reg + 4'b1100;
        3'b101: BCD_reg = BCD_reg + 4'b1111;
        3'b110: BCD_reg = BCD_reg + 4'b0010;
        3'b111: BCD_reg = BCD_reg + 4'b0101;
    endcase
end

// Pipeline Stage 6
always @(posedge clk) begin
    remainder = BCD_reg[3:0];
end

// Pipeline Stage 7
always @(*) begin
    case(remainder)
        3'b000: BCD_reg = BCD_reg;
        3'b001: BCD_reg = BCD_reg + 4'b0011;
        3'b010: BCD_reg = BCD_reg + 4'b0110;
        3'b011: BCD_reg = BCD_reg + 4'b1001;
        3'b100: BCD_reg = BCD_reg + 4'b1100;
        3'b101: BCD_reg = BCD_reg + 4'b1111;
        3'b110: BCD_reg = BCD_reg + 4'b0010;
        3'b111: BCD_reg = BCD_reg + 4'b0101;
    endcase
end

// Pipeline Stage 8
always @(posedge clk) begin
    remainder = BCD_reg[3:0];
end

assign BCD = BCD_reg;

endmodule

module SchmittTrigger (
  input in,
  input VTHplus,
  input VTHminus,
  output out
);

  reg out_reg;
  reg prev_out_reg;

  always @ (in or VTHplus or VTHminus or prev_out_reg) begin
    if (in > VTHplus) begin
      out_reg <= 1;
    end else if (in < VTHminus) begin
      out_reg <= 0;
    end else begin
      out_reg <= prev_out_reg;
    end
  end

  assign out = out_reg;

endmodule

module johnson_counter(
  input                clk,
  input                rst_n,
  output reg  [3:0]    johnson_out
);

  reg [6:0] lfsr_out;
  reg [63:0] counter;

  // LFSR implementation
  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      lfsr_out <= 7'b1;
    end else begin
      lfsr_out <= {lfsr_out[5:0], lfsr_out[6]^lfsr_out[0]};
    end
  end

  // 64-bit counter implementation
  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      counter <= 0;
    end else begin
      counter <= counter + 1;
    end
  end

  // Johnson counter implementation
  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      johnson_out <= 4'b0000;
    end else begin
      johnson_out <= {lfsr_out[6], lfsr_out[5], lfsr_out[4], lfsr_out[3]};
    end
  end

endmodule

module johnson_counter_display(
