module binary_counter_with_overflow (
    input clk,
    input reset,   // Synchronous active-high reset
    input [3:1] ena,
    output [15:0] q,
    output [3:0] ov);

    reg [15:0] count = 0;
    reg [3:0] overflow = 0;

    always @(posedge clk) begin
        if (reset) begin
            count <= 0;
            overflow <= 0;
        end else begin
            if (ena[3]) begin
                if (count == 65535) begin
                    count <= 0;
                    overflow <= overflow + 1;
                end else begin
                    count <= count + 1;
                end
            end
            if (ena[2]) begin
                if (count[14:0] == 32767) begin
                    count[14:0] <= 0;
                    if (count[15]) begin
                        overflow <= overflow + 1;
                    end
                    count[15] <= ~count[15];
                end else begin
                    count[14:0] <= count[14:0] + 1;
                end
            end
            if (ena[1]) begin
                if (count[9:0] == 1023) begin
                    count[9:0] <= 0;
                    if (count[14:10] == 31) begin
                        count[14:10] <= 0;
                        if (count[15]) begin
                            overflow <= overflow + 1;
                        end
                        count[15] <= ~count[15];
                    end else begin
                        count[14:10] <= count[14:10] + 1;
                    end
                end else begin
                    count[9:0] <= count[9:0] + 1;
                end
            end
        end
    end

    assign q = count;
    assign ov = overflow;

endmodule

