module top_module (
    input [3:0] a1,
    input [3:0] b1,
    input [3:0] a2,
    input [3:0] b2,
    input ctrl,
    output [3:0] result,
    output overflow,
    output greater_than_10
);

    wire [3:0] add_result;
    wire [3:0] sub_result;
    wire [3:0] max_input;
    wire [3:0] min_input;
    wire cmp_result;
    wire add_overflow;
    wire sub_overflow;

    // Instantiate adder-subtractor module
    adder_subtractor addsub (
        .a(a1),
        .b(b1),
        .ctrl(ctrl),
        .result(add_result),
        .overflow(add_overflow)
    );

    // Instantiate magnitude comparator module
    magnitude_comparator magcomp (
        .a(a2),
        .b(b2),
        .result(cmp_result)
    );

    // Determine max and min inputs for magnitude comparison
    assign max_input = (a2 > b2) ? a2 : b2;
    assign min_input = (a2 < b2) ? a2 : b2;

    // Determine result based on control signal
    assign result = (ctrl) ? sub_result : add_result;

    // Determine overflow based on control signal and overflow from adder-subtractor module
    assign overflow = (ctrl) ? sub_overflow : add_overflow;

    // Determine if magnitude of result is greater than 10
    assign greater_than_10 = (cmp_result && (max_input - min_input > 4'hA));

    // Instantiate adder-subtractor module for subtraction operation
    adder_subtractor sub (
        .a(a2),
        .b(b2),
        .ctrl(~ctrl),
        .result(sub_result),
        .overflow(sub_overflow)
    );

endmodule

