module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out
);

    reg [7:0] shift_reg;
    reg [7:0] adder_reg;
    reg [3:0] count;
    wire [7:0] adder_out;
    wire [7:0] shift_out;

    assign adder_out = adder_reg + data_in;
    assign shift_out = shift_reg << 1;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shift_reg <= 8'b0;
            adder_reg <= 8'b0;
            count <= 4'b0;
            valid_b <= 1'b0;
            data_out <= 10'b0;
        end else begin
            if (valid_a && ready_b) begin
                shift_reg <= {shift_reg[6:0], data_in};
                adder_reg <= adder_out;
                count <= count + 1;
                if (count == 4'b1000) begin
                    data_out <= {shift_out, adder_out};
                    valid_b <= 1'b1;
                    count <= 4'b0;
                end
            end
        end
    end

    assign ready_a = ~valid_b;

endmodule

module AGC (
  input wire [15:0] input_signal,
  input wire [15:0] desired_level,
  output wire [15:0] output_signal
);

parameter k = 10; // gain constant

reg [31:0] gain_factor;
reg [31:0] temp_output_signal;

always @(*) begin
  gain_factor = (desired_level << k) / input_signal;
  temp_output_signal = input_signal * gain_factor;
  if (temp_output_signal > 16'hFFFF) begin
    output_signal <= 16'hFFFF;
  end else begin
    output_signal <= temp_output_signal[31:16];
  end
end

endmodule

