module booth_multiplier (
    input [3:0] A,
    input [3:0] B,
    output reg [7:0] P
);

reg [7:0] A_ext;
reg [3:0] Q;
reg Q_minus1;
integer i;

always @(*) begin
    A_ext = {A, 4'b0};
    Q = B;
    Q_minus1 = 0;
    P = 8'b0;

    for (i = 0; i < 4; i = i + 1) begin
        case ({Q[0], Q_minus1})
            2'b00, 2'b11: begin end
            2'b01: P = P + A_ext;
            2'b10: P = P - A_ext;
        endcase

        A_ext = {A_ext[6:0], A_ext[7]};
        Q_minus1 = Q[0];
        Q = {Q[3], Q[2:0]};
    end
end

endmodule

