module uart( 
    input clk,
    input reset,
    input rx,
    input fsm,
    output [2:0] Led,
    output tx
); 

parameter PERIOD = 8'h1A;

`define TXreg          3'b001 
`define controltx  3'b011
`define RXreg          3'b101
`define controlrx  3'b111
`define NOTREADY        3'b000
`define WAITRX           3'b001
`define TRANS           3'b010
`define PASSTX          3'b011
`define CHECKTX        3'b100
`define PASSTX1        3'b101
`define STOP            3'b111
`define RXREADY     dout[1]

reg wr_tx, rd_tx, wr_rx, rd_rx, rx_sel, tx_sel, finished, dadd, clr;
reg [7:0] data;
wire [7:0] ready, dout_tx;
wire [8:0] dout_rx;
reg [2:0] addr_rx, addr_tx;
reg [2:0] nstate, pstate, dout;
reg [1:0] trans;

assign ready = 8'b00000001;

uart_tx #(.PERIOD(PERIOD)) out(
    .clk        (clk), 
    .reset     (reset), 
    .wren        (wr_tx), 
    .rden        (rd_tx), 
    .din        (data), 
    .dout        (dout_tx), 
    .txout    (tx), 
    .addr        (addr_tx));

uart_rx #(.PERIOD(PERIOD)) in(
    .clk        (clk),
    .reset     (reset),
    .wren        (wr_rx), 
    .rden        (rd_rx), 
    .din        (ready), 
    .dout        (dout_rx), 
    .rxin        (rx), 
    .addr        (addr_rx));


// adder
always @(posedge clk or posedge reset) begin
    if(reset)
        data <= 8'b11111111;
    else begin
        if(rx_sel)
            data <= dout_rx + 1'b1;
    end
end

always @(posedge clk or posedge reset) begin
    if(reset)
        dout = dout_rx[2:0];
    else begin
        if(dadd)
            dout = dout_tx[2:0];
        else
            dout = dout_rx[2:0];
    end
end
assign Led[0] = dout[0];
assign Led[1] = dout[1];
assign Led[2] = data[2];

always @* begin
    addr_rx = `controlrx;
    case(rx_sel)
        1'b1: 
            addr_rx = `RXreg;
    endcase
end

always @* begin
    if(tx_sel)
        addr_tx = `TXreg;
    else
        addr_tx = `controltx;
end

//trans clock
always @(posedge clk or posedge reset) begin
    if(reset)
        trans <= 2'b00;
    else begin
        trans <= trans + 1;
        if(clr)
            trans <= 2'b00;
    end
end

// set state during startup.
always @(posedge clk or posedge reset) begin
     if (reset)
          pstate <= `NOTREADY;
      else
          pstate <= nstate;
end


// fsm
always @* begin
    wr_tx = 0; wr_rx = 0;
    rd_tx = 0; rd_tx = 0;
    rx_sel = 0; tx_sel = 0;
    finished = 0; clr = 0;
    nstate = pstate;
    case (pstate)
        `NOTREADY: begin
            wr_rx = 1;
            nstate = `WAITRX;
        end
        `WAITRX: begin
            rd_rx = 1;
            if(`RXREADY) begin
                nstate = `TRANS;
                clr = 1;
            end
        end
        `TRANS: begin
            if(trans == 2'b11) begin
                rd_rx = 1;
                rx_sel = 1;
                nstate = `PASSTX;
            end
        end
        `PASSTX: begin
            rd_rx = 1;
            rx_sel = 1;
            nstate = `PASSTX1;
        end
        `PASSTX1: begin
            wr_tx = 1;
            tx_sel = 1;
            nstate = `STOP;
        end
        `STOP: begin
            nstate = `STOP;
            end
    endcase         
end

endmodule

module fifo_buffer (
  // These ports are within 'wrClk' domain
  input wrClk,
  input rstSyncToWrClk,
  input [FIFO_WIDTH-1:0] dataIn,
  input fifoWEn,
  input forceEmptySyncToWrClk,
  output fifoFull,

  // These ports are within 'rdClk' domain
  input rdClk,
  input rstSyncToRdClk,
  output [FIFO_WIDTH-1:0] dataOut,
  input fifoREn,
  input forceEmptySyncToRdClk,
  output fifoEmpty,
  output [15:0]numElementsInFifo //note that this implies a max fifo depth of 65536
);

parameter ADDR_WIDTH = $clog2(FIFO_DEPTH);

wire wrClk;
wire rdClk;
wire rstSyncToWrClk;
wire rstSyncToRdClk;
wire [FIFO_WIDTH-1:0] dataIn;
reg [FIFO_WIDTH-1:0] dataOut;
wire fifoWEn;
wire fifoREn;
reg fifoFull;
reg fifoEmpty;
wire forceEmpty;
reg  [15:0]numElementsInFifo;

reg  [ADDR_WIDTH:0]bufferInIndex;
reg  [ADDR_WIDTH:0]bufferInIndexSyncToRdClk;
reg  [ADDR_WIDTH:0]bufferOutIndex;
reg  [ADDR_WIDTH:0]bufferOutIndexSyncToWrClk;
reg  [ADDR_WIDTH-1:0]bufferInIndexToMem;
reg  [ADDR_WIDTH-1:0]bufferOutIndexToMem;
reg  [ADDR_WIDTH:0]bufferCnt;
reg  fifoREnDelayed;
wire [FIFO_WIDTH-1:0] dataFromMem;

always @(posedge wrClk) begin
  bufferOutIndexSyncToWrClk <= bufferOutIndex;
  if (rstSyncToWrClk == 1'b1 || forceEmptySyncToWrClk == 1'b1) begin
    fifoFull <= 1'b0;
    bufferInIndex <= 0;
  end else begin
    if (fifoWEn == 1'b1) begin
      bufferInIndex <= bufferInIndex + 1'b1;
    end 
    if ((bufferOutIndexSyncToWrClk[ADDR_WIDTH-1:0] == bufferInIndex[ADDR_WIDTH-1:0]) &&
        (bufferOutIndexSyncToWrClk[ADDR_WIDTH] != bufferInIndex[ADDR_WIDTH]) )
      fifoFull <= 1'b1;
    else
      fifoFull <= 1'b0;
  end
end

always @(bufferInIndexSyncToRdClk or bufferOutIndex) begin
  bufferCnt <= bufferInIndexSyncToRdClk - bufferOutIndex;
end

always @(posedge rdClk) begin
  numElementsInFifo <= { {16-ADDR_WIDTH+1{1'b0}}, bufferCnt }; //pad bufferCnt with leading zeroes
  bufferInIndexSyncToRdClk <= bufferInIndex;
  if (rstSyncToRdClk == 1'b1 || forceEmptySyncToRdClk == 1'b1) begin
    fifoEmpty <= 1'b1;
    bufferOutIndex <= 0;
    fifoREnDelayed <= 1'b0;
  end else begin
    fifoREnDelayed <= fifoREn;
    if (fifoREn == 1'b1 && fifoREnDelayed == 1'b0) begin
      dataOut <= dataFromMem;
      bufferOutIndex <= bufferOutIndex + 1'b1;
    end
    if (bufferInIndexSyncToRdClk == bufferOutIndex) 
      fifoEmpty <= 1'b1;
    else
      fifoEmpty <= 1'b0;
  end
end

always @(bufferInIndex or bufferOutIndex) begin
  bufferInIndexToMem <= bufferInIndex[ADDR_WIDTH-1:0];
  bufferOutIndexToMem <= bufferOutIndex[ADDR_WIDTH-1:0];
end

dpMem_dc #(FIFO_WIDTH, FIFO_DEPTH, ADDR_WIDTH)  u_dpMem_dc (
  .addrIn(bufferInIndexToMem),
  .addrOut(bufferOutIndexToMem),
  .wrClk(wrClk),
  .rdClk(rdClk),
  .dataIn(dataIn),
  .writeEn(fifoWEn),
  .readEn(fifoREn),
  .dataOut(dataFromMem));

endmodule

