module protocol_converter_with_memory(
    input wire clk,
    input wire reset,
    input wire new_input,
    output wire output_sum
);

reg [15:0] memory_block [0:7];
reg [15:0] sum;

integer i;

always @(posedge clk) begin
    if (reset) begin
        // Reset the memory block and the sum
        for (i = 0; i < 8; i = i + 1) begin
            memory_block[i] <= 0;
        end
        sum <= 0;
    end else begin
        // Shift the memory block and add the new input
        for (i = 7; i > 0; i = i - 1) begin
            memory_block[i] <= memory_block[i - 1];
        end
        memory_block[0] <= new_input;

        // Update the sum
        sum <= 0;
        for (i = 0; i < 8; i = i + 1) begin
            sum <= sum + memory_block[i];
        end
    end
end

assign output_sum = sum;

endmodule

module adc_peripheral(
    input clk_in,
    input cs,
    input wr,
    input rd,
    input din,
    input rst,
    input [3:0] addr,
    output reg [7:0] d_out,
    output clk_div,
    output done
);

// Instantiate the black box ADC module
wire dout;
wire clk_div_bb;
wire done_bb;
adc ad(
    .Din(din),
    .clk_in(clk_in),
    .reset(rst),
    .D0f(dout),
    .clk_div(clk_div_bb),
    .done(done_bb),
    .rd(rd)
);

// Declare internal signals
reg [3:0] s;
reg [7:0] dout_reg;

// Address decoder
always @(*) begin
    case (addr)
        4'h0: s = (cs && rd) ? 3'b001 : 5'b000; // CLK_DIV
        4'h2: s = (cs && rd) ? 3'b010 : 5'b000; // DONE
        4'h4: s = (cs && rd) ? 3'b100 : 5'b000; // D_OUT
        default: s = 3'b000;
    endcase
end

// Output mux
always @(negedge clk_in) begin
    case (s)
        3'b001: begin // CLK_DIV
            clk_div = clk_div_bb;
            d_out[0] = clk_div_bb;
        end
        3'b010: begin // DONE
            done = done_bb;
            d_out[0] = done_bb;
        end
        3'b100: begin // D_OUT
            dout_reg = dout;
            d_out = {8'h00, dout_reg};
        end
        default: begin
            clk_div = 1'b0;
            done = 1'b0;
            d_out = 8'h00;
        end
    endcase
end

endmodule

module NIOS_SYSTEMV3_MENU (
    input [1:0] address,
    input chipselect,
    input clk,
    input in_port,
    input reset_n,
    input write_n,
    input [31:0] writedata,
    output [31:0] readdata
);

    reg [31:0] readdata_reg;
    wire clk_en;
    reg d1_data_in;
    reg d2_data_in;
    wire data_in;
    reg edge_capture;
    wire edge_capture_wr_strobe;
    wire edge_detect;
    wire read_mux_out;

    assign clk_en = 1;

    //s1, which is an e_avalon_slave
    assign read_mux_out = ({1 {(address == 0)}} & data_in) |
        ({1 {(address == 3)}} & edge_capture);

    always @(posedge clk or negedge reset_n) begin
        if (reset_n == 0) begin
            readdata_reg <= 0;
        end else if (clk_en) begin
            readdata_reg <= {32'b0 | read_mux_out};
        end
    end

    assign data_in = in_port;
    assign edge_capture_wr_strobe = chipselect && ~write_n && (address == 3);

    always @(posedge clk or negedge reset_n) begin
        if (reset_n == 0) begin
            edge_capture <= 0;
        end else if (clk_en) begin
            if (edge_capture_wr_strobe) begin
                edge_capture <= 0;
            end else if (edge_detect) begin
                edge_capture <= -1;
            end
        end
    end

    always @(posedge clk or negedge reset_n) begin
        if (reset_n == 0) begin
            d1_data_in <= 0;
            d2_data_in <= 0;
        end else if (clk_en) begin
            d1_data_in <= data_in;
            d2_data_in <= d1_data_in;
        end
    end

    assign edge_detect = d1_data_in & ~d2_data_in;

    assign readdata = readdata_reg;

endmodule

module top_module (
    input clk,
    input d,
    input [31:0] in,
    output reg q,
    output [31:0] out_xor,
    output [31:0] out_and,
    output [31:0] out_final
 );

 // D flip-flop using T flip-flop
 reg t;
 always @(posedge clk) begin
    t <= d;
 end
 always @(posedge clk) begin
    q <= t;
 end

 // Combinational circuit for bit-wise XOR and AND
 assign out_xor = in[31:16] ^ in[15:0];
 assign out_and = in[31:16] & in[15:0];

 // Bit-wise OR operation
 assign out_final = q | (out_xor & out_and);

endmodule

module add_sub (
    input [3:0] a,
    input [3:0] b,
    input sub,
    input cin,
    output reg cout,
    output reg overflow,
    output reg [3:0] sum
);

reg [3:0] a_reg, b_reg, sum_reg;
reg sub_reg, cin_reg;
wire [3:0] add_out, sub_out;

assign add_out = a_reg + b_reg + cin_reg;
assign sub_out = a_reg - b_reg - cin_reg;

always @(posedge clk) begin
    a_reg <= a;
    b_reg <= b;
    sub_reg <= sub;
    cin_reg <= cin;
end

always @(posedge clk) begin
    if (sub_reg) begin
        sum_reg <= sub_out;
    end else begin
        sum_reg <= add_out;
    end
end

always @(posedge clk) begin
    if (sum_reg > 15 || sum_reg < -16) begin
        overflow <= 1;
    end else begin
        overflow <= 0;
    end
end

always @(posedge clk) begin
    if (sum_reg > 15 || sum_reg < -16) begin
        cout <= 1;
    end else begin
        cout <= add_out[4];
    end
end

assign sum = sum_reg;

endmodule

