            shifted_out <= shift_reg[0];
            shift_reg <= {shift_reg[99], shift_reg[0:98]};
        end
    end

    always @(*) begin
        if (ena[0]) begin
            q = {shift_reg[98:0], shifted_out};
        end else if (ena[1]) begin
            q = {shifted_out, shift_reg[99:1]};
        end else begin
            q = shift_reg;
        end
    end

