module top_module(
    input               clk         ,
    input               rst_n       ,
    input       [31:0]  a           ,
    input       [31:0]  b           ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [31:0]  sum         ,
    output  reg [31:0]  final_out
);

// Carry-Lookahead Adder
wire [31:0] add_out;
CLA_adder adder(.a(a), .b(b), .cin(1'b0), .sum(add_out), .cout());

// Accumulation Pipeline
reg [31:0] acc_out;
reg [31:0] acc_in;
reg [2:0]  acc_count;
always @(posedge clk) begin
    if (rst_n == 1'b0) begin
        acc_out <= 32'b0;
        acc_in <= 32'b0;
        acc_count <= 3'b0;
    end else if (valid_a == 1'b1 && ready_a == 1'b1) begin
        acc_in <= acc_in + {24'b0, data_in};
        acc_count <= acc_count + 1'b1;
        if (acc_count == 3'b111) begin
            acc_out <= acc_out + acc_in;
            acc_in <= 32'b0;
            acc_count <= 3'b0;
            valid_b <= 1'b1;
        end
    end
end

// Final Output Module
always @(posedge clk) begin
    if (rst_n == 1'b0) begin
        final_out <= 32'b0;
    end else if (valid_b == 1'b1 && ready_b == 1'b1) begin
        final_out <= add_out + acc_out;
        valid_b <= 1'b0;
    end
end

// Valid-Ready Handshake
assign ready_a = (valid_a == 1'b0) ? 1'b1 : 1'b0;
assign sum = add_out;

endmodule

// Carry-Lookahead Adder
module CLA_adder(
    input       [31:0]  a       ,
    input       [31:0]  b       ,
    input               cin     ,
    output reg  [31:0]  sum     ,
    output reg          cout
);
wire [31:0] p, g, c;
assign p = a ^ b;
assign g = a & b;
assign c[0] = cin;
generate
    genvar i;
    for (i = 0; i < 31; i = i + 1) begin : gen_CLA
        assign c[i+1] = g[i] | (p[i] & c[i]);
        assign sum[i] = p[i] ^ c[i];
    end
endgenerate
assign cout = g[31] | (p[31] & c[31]);

endmodule

module bit_shift (
  input [31:0] in,
  input [4:0] shift,
  input [1:0] op,
  output [31:0] out
);

  reg [31:0] shift_reg;

  always @(*) begin
    case (op)
      2'b00: shift_reg = in << shift;
      2'b01: shift_reg = in >> shift;
      2'b10: shift_reg = $signed(in) >>> shift;
      default: shift_reg = in;
    endcase
  end

  assign out = shift_reg;

endmodule

module FullAdder(A, B, Cin, Sum, Cout);

input A, B, Cin;
output Sum, Cout;

wire w1, w2, w3;

// First XOR gate
xor(w1, A, B);

// Second XOR gate
xor(Sum, w1, Cin);

// First AND gate
and(w2, A, B);

// Second AND gate
and(w3, Cin, w1);

// Third AND gate
and(Cout, w2, w3);

endmodule

module spw_babasu_AUTOSTART (
  // inputs:
  input [1:0] address,
  input chipselect,
  input clk,
  input reset_n,
  input write_n,
