module booth_multiplier (
  input clk,
  input reset,
  input [31:0] multiplicand,
  input [31:0] multiplier,
  output reg [63:0] product,
  output reg done
);

  reg [31:0] A_reg, S_reg;
  reg [1:0] state_reg;
  reg [4:0] count_reg;
  reg [31:0] multiplier_reg;
  reg [63:0] product_reg;

  always @(posedge clk) begin
    if (reset) begin
      A_reg <= 0;
      S_reg <= 0;
      state_reg <= 2'b00;
      count_reg <= 5'b00000;
      multiplier_reg <= multiplier;
      product_reg <= 0;
      done <= 0;
    end
    else begin
      case (state_reg)
        2'b00: begin
          if (count_reg == 5'b00000) begin
            multiplier_reg <= multiplier;
            state_reg <= 2'b01;
          end
          else begin
            count_reg <= count_reg + 1;
          end
        end
        2'b01: begin
          if (multiplier_reg[0] == 1 && S_reg == 0) begin
            S_reg <= ~multiplicand;
            state_reg <= 2'b10;
          end
          else if (multiplier_reg[0] == 0 && S_reg == 0) begin
            state_reg <= 2'b10;
          end
          else if (multiplier_reg[0] == 1 && S_reg == 1) begin
            state_reg <= 2'b10;
          end
          else if (multiplier_reg[0] == 0 && S_reg == 1) begin
            S_reg <= multiplicand;
            state_reg <= 2'b10;
          end
        end
        2'b10: begin
          if (count_reg == 5'b00111) begin
            product_reg <= {S_reg, A_reg};
            A_reg <= 0;
            S_reg <= 0;
            count_reg <= 5'b00000;
            state_reg <= 2'b00;
          end
          else begin
            if (S_reg[0] == 0) begin
              S_reg <= S_reg >> 1;
              A_reg <= A_reg >> 1;
              A_reg[31] <= A_reg[30];
            end
            else begin
              S_reg <= (S_reg >> 1) | 32'b11111111111111111111111111110000;
              A_reg <= A_reg - multiplicand;
              A_reg <= A_reg >> 1;
              A_reg[31] <= A_reg[30];
            end
            count_reg <= count_reg + 1;
          end
        end
      endcase
    end
  end

  assign product = product_reg;
  assign done = (state_reg == 2'b00) && (count_reg == 5'b00000);

endmodule

