module signed_mag_ripple_adder (
    input [3:0] A,
    input [3:0] B,
    input sign,
    output [3:0] sum
);

    wire [3:0] ripple_sum;
    wire [3:0] signed_mag_sum;

    ripple_carry_adder ripple_adder(
        .A(A),
        .B(B),
        .Cin(sign),
        .Sum(ripple_sum)
    );

    signed_magnitude_adder signed_mag_adder(
        .A(A),
        .B(B),
        .Sign(sign),
        .Sum(signed_mag_sum)
    );

    mux2x1 mux(
        .A(ripple_sum),
        .B(signed_mag_sum),
        .Sel(sign),
        .Out(sum)
    );

endmodule

module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Sum
);

    wire [3:0] carry;
    assign carry[0] = Cin;

    genvar i;
    generate
        for (i = 0; i < 4; i = i + 1) begin : ADDER_LOOP
            full_adder adder(
                .A(A[i]),
                .B(B[i]),
                .Cin(carry[i]),
                .Sum(Sum[i]),
                .Cout(carry[i+1])
            );
        end
    endgenerate

endmodule

module signed_magnitude_adder (
    input [3:0] A,
    input [3:0] B,
    input Sign,
    output [3:0] Sum
);

    wire [3:0] inverted_B;
    assign inverted_B = ~B + 1;

    mux2x1 mux(
        .A(A),
        .B(inverted_B),
        .Sel(Sign),
        .Out(Sum)
    );

endmodule

module full_adder (
    input A,
    input B,
    input Cin,
    output Sum,
    output Cout
);

    assign Sum = A ^ B ^ Cin;
    assign Cout = (A & B) | (Cin & (A ^ B));

endmodule

module mux2x1 (
    input [3:0] A,
    input [3:0] B,
    input Sel,
    output [3:0] Out
);

    assign Out = Sel ? B : A;

endmodule

