module MUXF16(
  input [3:0] I,
  input [1:0] S,
  output reg O
);

  wire [1:0] S0, S1;
  wire [1:0] not_S0, not_S1;

  assign {not_S1, not_S0} = ~S;

  MUXF9 M0(.I0(I[0]), .I1(I[1]), .S(S0), .O(O0));
  MUXF9 M1(.I0(I[2]), .I1(I[3]), .S(S0), .O(O1));
  MUXF9 M2(.I0(O0), .I1(O1), .S(S1), .O(O));

  assign S0 = {not_S1, S[0]};
  assign S1 = {not_S0, S[1]};

endmodule

module top_module (
    input a,
    input b,
    input clk,
    input reset,      // Synchronous active-high reset
    output reg out_comb // Output from the functional module that combines the XOR gate and the counter
);

// Internal wires and registers
wire [3:0] counter;
wire even;
wire odd;
wire xor_out;
reg [3:0] next_counter;

// XOR gate implementation
assign xor_out = a ^ b;

// 4-bit binary counter implementation using state machine architecture
always @ (posedge clk, posedge reset) begin
    if (reset) begin
        counter <= 4'b0;
    end else begin
        case (counter)
            4'b0000: next_counter = 4'b0001;
            4'b0001: next_counter = 4'b0010;
            4'b0010: next_counter = 4'b0011;
            4'b0011: next_counter = 4'b0100;
            4'b0100: next_counter = 4'b0101;
            4'b0101: next_counter = 4'b0110;
            4'b0110: next_counter = 4'b0111;
            4'b0111: next_counter = 4'b1000;
            4'b1000: next_counter = 4'b1001;
            4'b1001: next_counter = 4'b1010;
            4'b1010: next_counter = 4'b1011;
            4'b1011: next_counter = 4'b1100;
            4'b1100: next_counter = 4'b1101;
            4'b1101: next_counter = 4'b1110;
            4'b1110: next_counter = 4'b1111;
            4'b1111: next_counter = 4'b0000;
        endcase
        counter <= next_counter;
    end
end

// Determine if the counter value is even or odd
assign even = ~counter[0];
assign odd = counter[0];

// Functional module implementation
always @ (*) begin
    if (even) begin
        out_comb = xor_out;
    end else if (odd) begin
        out_comb = counter;
    end
end

endmodule

module CDR (
  input data,
  input ref_clk,
  output reg clk_out
);

parameter clk_freq = 100000000; // 100 MHz reference clock frequency
parameter data_rate = 1000000; // 1 Mbps data rate

reg phase_error;
reg loop_gain;
reg vco_out;

phase_detector pd_inst (
  .data(data),
  .ref_clk(ref_clk),
  .phase_error(phase_error)
);

loop_filter lf_inst (
  .phase_error(phase_error),
  .loop_gain(loop_gain)
);

vco vco_inst (
  .clk_freq(clk_freq),
  .loop_gain(loop_gain),
  .clk_out(vco_out)
);

always @(posedge ref_clk) begin
  if (data) begin
    phase_error <= 1;
  end else begin
    phase_error <= 0;
  end
end

always @(posedge ref_clk) begin
  if (vco_out) begin
    clk_out <= 1;
  end else begin
    clk_out <= 0;
  end
end

endmodule

module phase_detector (
  input data,
  input ref_clk,
  output reg phase_error
);

always @(posedge ref_clk) begin
  if (data) begin
    phase_error <= 1;
  end else begin
    phase_error <= 0;
  end
end

endmodule

module loop_filter (
  input phase_error,
  output reg loop_gain
);

parameter Kp = 0.1;
parameter Ki = 0.01;

reg [31:0] integral = 0;

always @(posedge phase_error) begin
  integral <= integral + phase_error;
  loop_gain <= Kp * phase_error + Ki * integral;
end

endmodule

module vco (
  input clk_freq,
  input loop_gain,
  output reg clk_out
);

parameter f_min = 0.9 * clk_freq / (2 * data_rate);
parameter f_max = 1.1 * clk_freq / (2 * data_rate);
parameter k_vco = (f_max - f_min) / 2;

reg [31:0] phase_accumulator = 0;
reg [31:0] phase_increment = 0;

always @(posedge clk_out) begin
  phase_accumulator <= phase_accumulator + phase_increment;
end

always @(posedge clk_out) begin
  phase_increment <= round(loop_gain * k_vco);
end

always @(posedge clk_out) begin
  if (phase_accumulator >= 2**31) begin
    phase_accumulator <= phase_accumulator - 2**32;
  end
  if (phase_accumulator < -2**31) begin
    phase_accumulator <= phase_accumulator + 2**32;
  end
  if (phase_accumulator >= 0) begin
    clk_out <= 1;
  end else begin
    clk_out <= 0;
  end
end

endmodule

