module ps2_port (
    input wire clk,  // se recomienda 1 MHz <= clk <= 600 MHz
    input wire enable_rcv,  // habilitar la maquina de estados de recepcion
    input wire ps2clk_ext,
    input wire ps2data_ext,
    output wire kb_interrupt,  // a 1 durante 1 clk para indicar nueva tecla recibida
    output reg [7:0] scancode, // make o breakcode de la tecla
    output wire released,  // soltada=1, pulsada=0
    output wire extended  // extendida=1, no extendida=0
    );

    `define RCVSTART    2'b00
    `define RCVDATA     2'b01 
    `define RCVPARITY   2'b10
    `define RCVSTOP     2'b11

    reg [7:0] key = 8'h00;

    // Fase de sincronizacion de señales externas con el reloj del sistema
    reg [1:0] ps2clk_synchr;
    reg [1:0] ps2dat_synchr;
    wire ps2clk = ps2clk_synchr[1];
    wire ps2data = ps2dat_synchr[1];
    always @(posedge clk) begin
        ps2clk_synchr[0] <= ps2clk_ext;
        ps2clk_synchr[1] <= ps2clk_synchr[0];
        ps2dat_synchr[0] <= ps2data_ext;
        ps2dat_synchr[1] <= ps2dat_synchr[0];
    end

    // De-glitcher. Sólo detecto flanco de bajada
    reg [15:0] negedgedetect = 16'h0000;
    always @(posedge clk) begin
        negedgedetect <= {negedgedetect[14:0], ps2clk};
    end
    wire ps2clkedge = (negedgedetect == 16'hF000)? 1'b1 : 1'b0;

    // Paridad instantánea de los bits recibidos
    wire paritycalculated = ^key;

    // Contador de time-out. Al llegar a 65536 ciclos sin que ocurra
    // un flanco de bajada en PS2CLK, volvemos al estado inicial
    reg [15:0] timeoutcnt = 16'h0000;

    reg [1:0] state = `RCVSTART;
    reg [1:0] regextended = 2'b00;
    reg [1:0] regreleased = 2'b00;
    reg rkb_interrupt = 1'b0;
    assign released = regreleased[1];
    assign extended = regextended[1];
    assign kb_interrupt = rkb_interrupt;

    always @(posedge clk) begin
        if (rkb_interrupt == 1'b1) begin
            rkb_interrupt <= 1'b0;
        end
        if (ps2clkedge && enable_rcv) begin
            timeoutcnt <= 16'h0000;
            if (state == `RCVSTART && ps2data == 1'b0) begin
                state <= `RCVDATA;
                key <= 8'h80;
            end
            else if (state == `RCVDATA) begin
                key <= {ps2data, key[7:1]};
                if (key[0] == 1'b1) begin
                    state <= `RCVPARITY;
                end
            end
            else if (state == `RCVPARITY) begin
                if (ps2data^paritycalculated == 1'b1) begin
                    state <= `RCVSTOP;
                end
                else begin
                    state <= `RCVSTART;
                end
            end
            else if (state == `RCVSTOP) begin
                state <= `RCVSTART;                
                if (ps2data == 1'b1) begin
                   scancode <= key;
                   if (key == 8'hE0) begin
                     regextended <= 2'b01;
                   end
                   else if (key == 8'hF0) begin
                     regreleased <= 2'b01;
                   end
                   else begin
                     regextended <= {regextended[0], 1'b0};
                     regreleased <= {regreleased[0], 1'b0};
                     rkb_interrupt <= 1'b1;
                   end
                end
            end       
        end           
        else begin
            timeoutcnt <= timeoutcnt + 1;
            if (timeoutcnt == 16'hFFFF) begin
                state <= `RCVSTART;
            end
        end
    end
endmodule

module top_module( 
    input [15:0] in1,
    input [15:0] in2,
    input [3:0] sel,
    input select_add_sub,
    input reset,
    output reg [15:0] out );

    reg [15:0] add_out;
    reg [15:0] sub_out;
    reg [3:0] priority;
    reg [15:0] selected_input;

    // Priority Encoder
    always @* begin
        case ({in1, in2})
            16'h0000: priority = 4'b0000;
            16'h0001: priority = 4'b0001;
            16'h0002: priority = 4'b0010;
            16'h0004: priority = 4'b0011;
            16'h0008: priority = 4'b0100;
            16'h0010: priority = 4'b0101;
            16'h0020: priority = 4'b0110;
            16'h0040: priority = 4'b0111;
            16'h0080: priority = 4'b1000;
            16'h0100: priority = 4'b1001;
            16'h0200: priority = 4'b1010;
            16'h0400: priority = 4'b1011;
            16'h0800: priority = 4'b1100;
            16'h1000: priority = 4'b1101;
            16'h2000: priority = 4'b1110;
            16'h4000: priority = 4'b1111;
            default: priority = 4'b0000;
        endcase
    end

    // Priority Decoder
    always @* begin
        case (sel)
            4'b0000: selected_input = in1;
            4'b0001: selected_input = in2;
            4'b0010: selected_input = 16'h0000;
            4'b0011: selected_input = 16'h0001;
            4'b0100: selected_input = 16'h0002;
            4'b0101: selected_input = 16'h0004;
            4'b0110: selected_input = 16'h0008;
            4'b0111: selected_input = 16'h0010;
            4'b1000: selected_input = 16'h0020;
            4'b1001: selected_input = 16'h0040;
            4'b1010: selected_input = 16'h0080;
            4'b1011: selected_input = 16'h0100;
            4'b1100: selected_input = 16'h0200;
            4'b1101: selected_input = 16'h0400;
            4'b1110: selected_input = 16'h0800;
            4'b1111: selected_input = 16'h1000;
            default: selected_input = in1;
        endcase
    end

    // Adder and Subtractor
    always @* begin
        add_out = in1 + in2;
        sub_out = in1 - in2;
    end

    // Output Logic
    always @* begin
        case (select_add_sub)
            1'b0: out = add_out;
            1'b1: out = sub_out;
            default: out = 16'h0000;
        endcase
    end

    // Reset Logic
    always @(posedge reset) begin
        out <= 16'h0000;
    end

endmodule

module top_module (
    input clk,
    input reset,
    input [3:0] in,
    output [3:0] out
);

    // Edge Detector Module
    reg prev_signal;
    reg edge_detected;
    always @(negedge clk) begin
        if (reset) begin
            prev_signal <= 1'b0;
            edge_detected <= 1'b0;
        end else begin
            prev_signal <= in[0];
            if (in[0] != prev_signal) begin
                edge_detected <= 1'b1;
            end else begin
                edge_detected <= 1'b0;
            end
        end
    end

    // Priority Encoder Module
    wire [3:0] gray_code;
    wire [1:0] priority;
    gray_encoder gray_encoder_inst (
        .binary(in),
        .gray(gray_code)
    );
    priority_encoder priority_encoder_inst (
        .gray(gray_code),
        .priority(priority)
    );

    // Functional Module
    always @(posedge clk) begin
        if (reset) begin
            out <= 4'b0000;
        end else begin
            case (priority)
                2'b00: out <= {edge_detected, 2'b00};
                2'b01: out <= {2'b00, priority};
                2'b10: out <= {2'b00, priority};
                2'b11: out <= {edge_detected, priority};
            endcase
        end
    end

endmodule

// Binary-to-Gray Code Converter
module gray_encoder (
    input [3:0] binary,
    output [3:0] gray
);
    assign gray[0] = binary[0];
    assign gray[1] = binary[0] ^ binary[1];
    assign gray[2] = binary[1] ^ binary[2];
    assign gray[3] = binary[2] ^ binary[3];
endmodule

// Gray-to-Binary Code Converter
module gray_decoder (
    input [3:0] gray,
    output [3:0] binary
);
    assign binary[0] = gray[0];
    assign binary[1] = gray[0] ^ gray[1];
    assign binary[2] = gray[1] ^ gray[2];
    assign binary[3] = gray[2] ^ gray[3];
endmodule

// Priority Encoder Module
module priority_encoder (
    input [3:0] gray,
    output [1:0] priority
);
    assign priority = gray[3:2] > gray[2:1] ? 2'b11 : (gray[2:1] > gray[1:0] ? 2'b10 : (gray[1:0] > gray[0] ? 2'b01 : 2'b00));
endmodule

module multiplier_block (
    i_data0,
    o_data0
);

  // Port mode declarations:
  input   [31:0] i_data0;
  output  [31:0] o_data0;

  //Multipliers:
  wire [31:0]
    w1,
    w256,
    w255,
    w2040,
    w2295,
    w2,
    w2297,
    w9188,
    w6891,
    w27564;

  // Assign constants to wires
  assign w1 = 32'h00000001;
  assign w256 = w1 << 8;
  assign w255 = 32'h000000FF;
  assign w2040 = w255 << 3;
  assign w2295 = w255 + w2040;
  assign w2 = w1 << 1;
  assign w2297 = w2295 + w2;
  assign w9188 = w2297 << 2;
  assign w6891 = w9188 - w2297;
  assign w27564 = w6891 << 2;

