module quadrature (
  input in,
  input carrier,
  input select,
  output I_out,
  output Q_out
);

parameter fc = 1000000; // carrier frequency
parameter fs = 8000; // sampling frequency
parameter bw = 4000; // bandwidth of baseband signal

// Define I and Q components as functions of the baseband signal and carrier signal
function [31:0] I_func;
  input [31:0] in;
  input [31:0] carrier;
  begin
    I_func = in * $cos(2 * $pi * fc / fs) + carrier * $sin(2 * $pi * fc / fs);
  end
endfunction

function [31:0] Q_func;
  input [31:0] in;
  input [31:0] carrier;
  begin
    Q_func = in * $sin(2 * $pi * fc / fs) - carrier * $cos(2 * $pi * fc / fs);
  end
endfunction

// Connect inputs to modulators and demodulators using I and Q functions
assign I_out = (select == 0) ? I_func(in, carrier) : (I_func(in, carrier) - Q_func(in, carrier));
assign Q_out = (select == 0) ? Q_func(in, carrier) : (Q_func(in, carrier) + I_func(in, carrier));

endmodule

module uart_state_machine (
  input clk,
  input rst,
  input data_in,
  output reg data_out,
  output reg tx_en,
  output reg rx_en,
  output reg pe,
  output reg fe
);

  // Define the states of the state machine
  parameter IDLE_STATE = 2'b00;
  parameter TRANSMIT_STATE = 2'b01;
  parameter RECEIVE_STATE = 2'b10;
  parameter ERROR_STATE = 2'b11;

  // Define the current state and next state variables
  reg [1:0] current_state;
  reg [1:0] next_state;

  // Define the data and control signal variables
  reg [7:0] data;
  reg start_bit;
  reg parity_bit;
  reg stop_bit;

  // Define the counter for sampling the data_in input
  reg [2:0] sample_counter;

  // Define the counter for transmitting the data_out output
  reg [2:0] transmit_counter;

  // Initialize the state machine
  always @(posedge clk, posedge rst) begin
    if (rst) begin
      current_state <= IDLE_STATE;
      next_state <= IDLE_STATE;
      data <= 8'b0;
      start_bit <= 1'b0;
      parity_bit <= 1'b0;
      stop_bit <= 1'b0;
      sample_counter <= 3'b0;
      transmit_counter <= 3'b0;
      tx_en <= 1'b0;
      rx_en <= 1'b0;
      pe <= 1'b0;
      fe <= 1'b0;
    end
    else begin
      current_state <= next_state;
    end
  end

  // Define the state machine transitions and actions
  always @(*) begin
    case (current_state)
      IDLE_STATE: begin
        if (!data_in) begin
          next_state = RECEIVE_STATE;
          start_bit = 1'b1;
          sample_counter = 3'b0;
          rx_en = 1'b1;
        end
        else begin
          next_state = IDLE_STATE;
          rx_en = 1'b0;
        end
        tx_en = 1'b0;
        pe = 1'b0;
        fe = 1'b0;
      end

      TRANSMIT_STATE: begin
        if (transmit_counter == 3'b000) begin
          data_out = data[0];
          transmit_counter <= 3'b001;
        end
        else if (transmit_counter == 3'b001) begin
          data_out = data[1];
          transmit_counter <= 3'b010;
        end
        else if (transmit_counter == 3'b010) begin
          data_out = data[2];
          transmit_counter <= 3'b011;
        end
        else if (transmit_counter == 3'b011) begin
          data_out = data[3];
          transmit_counter <= 3'b100;
        end
        else if (transmit_counter == 3'b100) begin
          data_out = data[4];
          transmit_counter <= 3'b101;
        end
        else if (transmit_counter == 3'b101) begin
          data_out = data[5];
          transmit_counter <= 3'b110;
        end
        else if (transmit_counter == 3'b110) begin
          data_out = data[6];
          transmit_counter <= 3'b111;
        end
        else if (transmit_counter == 3'b111) begin
          data_out = data[7];
          transmit_counter <= 3'b000;
          next_state = IDLE_STATE;
          tx_en = 1'b0;
          pe = parity_bit ^ data[0] ^ data[1] ^ data[2] ^ data[3] ^ data[4] ^ data[5] ^ data[6] ^ data[7];
          fe = 1'b0;
        end
        rx_en = 1'b0;
      end

      RECEIVE_STATE: begin
        if (sample_counter == 3'b000) begin
          data[0] = data_in;
          sample_counter <= 3'b001;
        end
        else if (sample_counter == 3'b001) begin
          data[1] = data_in;
          sample_counter <= 3'b010;
        end
        else if (sample_counter == 3'b010) begin
          data[2] = data_in;
          sample_counter <= 3'b011;
        end
        else if (sample_counter == 3'b011) begin
          data[3] = data_in;
          sample_counter <= 3'b100;
        end
        else if (sample_counter == 3'b100) begin
          data[4] = data_in;
          sample_counter <= 3'b101;
        end
        else if (sample_counter == 3'b101) begin
          data[5] = data_in;
          sample_counter <= 3'b110;
        end
        else if (sample_counter == 3'b110) begin
          data[6] = data_in;
          sample_counter <= 3'b111;
        end
        else if (sample_counter == 3'b111) begin
          data[7] = data_in;
          sample_counter <= 3'b000;
          stop_bit = data_in;
          next_state = TRANSMIT_STATE;
          tx_en = 1'b1;
          parity_bit = data[0] ^ data[1] ^ data[2] ^ data[3] ^ data[4] ^ data[5] ^ data[6] ^ data[7];
          if (start_bit != 1'b1 || stop_bit != 1'b0 || pe != 1'b0) begin
            next_state = ERROR_STATE;
          end
        end
        rx_en = 1'b1;
        pe = 1'b0;
        fe = 1'b0;
      end

      ERROR_STATE: begin
        if (rst) begin
          next_state = IDLE_STATE;
        end
        tx_en = 1'b0;
        rx_en = 1'b0;
        if (pe == 1'b1) begin
          pe = 1'b0;
          fe = 1'b0;
        end
        else if (fe == 1'b1) begin
          pe = 1'b0;
          fe = 1'b0;
        end
      end
    endcase
  end
endmodule

module MemoryInterface (
