module ConvolutionalEncoderViterbiDecoder (
  input [7:0] in,
  output [15:0] out
);

parameter k = 3; // number of bits in the shift register
parameter n = 2; // number of encoded bits produced for each input bit
parameter m = 4; // number of possible transmitted bit sequences

reg [k-1:0] shift_reg; // shift register for encoding
reg [n-1:0] encoded_bits; // encoded bits produced by encoder
reg [m-1:0] state; // state machine for decoding
reg [1:0] decision; // most likely sequence of transmitted bits

// convolutional encoder
always @(posedge clk) begin
  shift_reg <= {shift_reg[k-2:0], in};
  encoded_bits <= {shift_reg[2]^shift_reg[1], shift_reg[2]^shift_reg[0]};
end

// Viterbi decoder
always @(posedge clk) begin
  case(state)
    0: begin // initial state
      if(encoded_bits == 2'b00) state <= 2'b00;
      else if(encoded_bits == 2'b01) state <= 2'b01;
      else if(encoded_bits == 2'b10) state <= 2'b10;
      else state <= 2'b11;
    end
    1: begin // state 1
      if(encoded_bits == 2'b00) begin
        state <= 2'b00;
        decision <= 2'b00;
      end
      else if(encoded_bits == 2'b01) begin
        state <= 2'b11;
        decision <= 2'b01;
      end
      else if(encoded_bits == 2'b10) begin
        state <= 2'b10;
        decision <= 2'b11;
      end
      else begin
        state <= 2'b01;
        decision <= 2'b10;
      end
    end
    2: begin // state 2
      if(encoded_bits == 2'b00) begin
        state <= 2'b11;
        decision <= 2'b10;
      end
      else if(encoded_bits == 2'b01) begin
        state <= 2'b00;
        decision <= 2'b00;
      end
      else if(encoded_bits == 2'b10) begin
        state <= 2'b01;
        decision <= 2'b01;
      end
      else begin
        state <= 2'b10;
        decision <= 2'b11;
      end
    end
    3: begin // state 3
      if(encoded_bits == 2'b00) begin
        state <= 2'b10;
        decision <= 2'b11;
      end
      else if(encoded_bits == 2'b01) begin
        state <= 2'b01;
        decision <= 2'b10;
      end
      else if(encoded_bits == 2'b10) begin
        state <= 2'b00;
        decision <= 2'b00;
      end
      else begin
        state <= 2'b11;
        decision <= 2'b01;
      end
    end
  endcase
end

assign out = decision;

endmodule

module calculator (
    input [3:0] A,
    input [3:0] B,
    input [1:0] op,
    input reset,
    output [3:0] LED
);

reg [3:0] result;
reg [3:0] error_msg;

always @(*) begin
    case (op)
        2'b00: result = A + B; // addition
        2'b01: result = A - B; // subtraction
        2'b10: result = A * B; // multiplication
        2'b11: begin             // division
            if (B == 4'b0000) begin
                error_msg = 4'b1111; // divide by zero error
                result = 4'b0000;
            end else if (A == 4'b1000 && B == 4'b0001) begin
                error_msg = 4'b1110; // overflow error
                result = 4'b0000;
            end else begin
                error_msg = 4'b0000;
                result = A / B;
            end
        end
    endcase
end

assign LED = (reset) ? 4'b0000 : (error_msg != 4'b0000) ? error_msg : result;

endmodule

