module arbitration_block (
  input [n-1:0] req,
  output grant
);

parameter n = 4; // number of request signals
parameter algorithm = "round-robin"; // arbitration algorithm (round-robin or priority-based)

reg [n-1:0] priority; // priority of each request
reg [n-1:0] round_robin; // round-robin counter

always @(*) begin
  if (algorithm == "round-robin") begin
    round_robin = round_robin + 1;
    if (round_robin >= n) round_robin = 0;
    priority = {req[round_robin+1:n-1], req[0:round_robin]};
  end else if (algorithm == "priority-based") begin
    priority = req;
  end
end

assign grant = priority & ~(priority - 1);

endmodule

