module pulse_width_detect(
  input               clk,
  input               rst_n,
  input               a,
  output reg          pulse,
  output reg          no_pulse
);

  reg [7:0]           counter;
  reg                 count_en;

  parameter           THRESHOLD = 50; // threshold for pulse width detection

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      counter <= 8'b0;
      pulse <= 1'b0;
      no_pulse <= 1'b0;
      count_en <= 1'b0;
    end
    else begin
      if (a) begin
        count_en <= 1'b1;
        if (counter >= THRESHOLD) begin
          pulse <= 1'b1;
          no_pulse <= 1'b0;
        end
        else begin
          pulse <= 1'b0;
          no_pulse <= 1'b1;
        end
      end
      else begin
        count_en <= 1'b0;
        pulse <= 1'b0;
        no_pulse <= 1'b0;
        counter <= 8'b0;
      end

      if (count_en) begin
        counter <= counter + 1;
      end
    end
  end

endmodule

module mux4_1 (
    input A0, A1, A2, A3,
    input [1:0] S,
    output X
);

    // Declare intermediate wires
    wire and0_out, and1_out, and2_out, and3_out;
    wire or0_out, or1_out;

    // Implement AND gates
    sky130_fd_sc_hd__and2 and0 (
        .A(A0),
        .B(~S[1]),
        .Z(and0_out)
    );

    sky130_fd_sc_hd__and2 and1 (
        .A(A1),
        .B(S[1] & ~S[0]),
        .Z(and1_out)
    );

    sky130_fd_sc_hd__and2 and2 (
        .A(A2),
        .B(S[0] & ~S[1]),
        .Z(and2_out)
    );

    sky130_fd_sc_hd__and2 and3 (
        .A(A3),
        .B(S[1] & S[0]),
        .Z(and3_out)
    );

    // Implement OR gates
    sky130_fd_sc_hd__or2 or0 (
        .A(and0_out),
        .B(and1_out),
        .Z(or0_out)
    );

    sky130_fd_sc_hd__or2 or1 (
        .A(and2_out),
        .B(and3_out),
        .Z(or1_out)
    );

    // Assign output
    assign X = or0_out | or1_out;

endmodule

