module up_down_bcd_counter (
    input clk,
    input reset,      // Synchronous active-high reset
    input select,     // Select input to choose between up and down counting
    input [3:0] in,   // Additional input for the functional module
    output reg [3:0] q);  // 4-bit output from the functional module

    reg [3:0] binary_counter = 4'b0000;
    reg [13:0] bcd_counter = 14'd0;
    reg [3:0] bcd_out;

    always @(posedge clk) begin
        if (reset) begin
            binary_counter <= 4'b0000;
            bcd_counter <= 14'd0;
            bcd_out <= 4'b0000;
        end else begin
            if (select) begin
                // Count down
                binary_counter <= binary_counter - 1;
                if (binary_counter < 4'b0000) begin
                    binary_counter <= 4'b1111;
