                        if (S !== {1, (A + B + Cin - 16)}) begin
                            $display("ERROR: S is %b, should be %b", S, {1, (A + B + Cin - 16)});
                            $finish;
                        end
                    end else begin
                        if (S !== (A + B + Cin)) begin
                            $display("ERROR: S is %b, should be %b", S, (A + B + Cin));
                            $finish;
                        end
                    end
                    if (Cout !== ((A & B) | (Cin & A) | (Cin & B))) begin
                        $display("ERROR: Cout is %b, should be %b", Cout, ((A & B) | (Cin & A) | (Cin & B)));
                        $finish;
                    end
                end
            end
        end
        $display("Test passed");
        $finish;
    end

endmodule

