module binary_multiplier (
    input [7:0] a,
    input [7:0] b,
    output reg [15:0] result
);

    integer i, j;

    always @(*) begin
        result = 16'b0;
        for (i = 0; i < 8; i = i + 1) begin
            if (a[i]) begin
                for (j = 0; j < 8; j = j + 1) begin
                    if (b[j]) begin
                        result[i+j] = result[i+j] + 1;
                    end
                end
            end
        end
    end

endmodule

