    mux_256to1 mux_inst(
        .in(in),
        .sel(sel),
        .out(mux_out)
    );

    // Instantiate the parity checker
    parity_checker parity_inst(
        .in(mux_out),
        .out(xor_in)
    );

    // Instantiate the functional module
    functional_module func_inst(
        .in1(xor_out),
        .in2(xor_in),
        .out(out)
    );

    // Generate the 9-bit input for the functional module by adding the parity bit
    assign xor_out = {parity_inst.out[8], mux_out};

endmodule


module mux_256to1(
    input [2047:0] in,
    input [3:0] sel,
    output [8:0] out
);

    wire [7:0] level0 [31:0];
    wire [15:0] level1 [15:0];
    wire [31:0] level2 [7:0];
    wire [63:0] level3 [3:0];
    wire [127:0] level4 [1:0];
    wire [255:0] level5;
    wire [511:0] level6;
    wire [1023:0] level7;

    // First level of multiplexers
    genvar i;
    generate
        for (i = 0; i < 32; i = i + 2) begin : level0_gen
            assign level0[i/2] = {in[i], in[i+1]};
        end
    endgenerate

    // Second level of multiplexers
    generate
        for (i = 0; i < 16; i = i + 2) begin : level1_gen
            mux_2to1 mux_inst(
                .in({level0[i], level0[i+1]}),
                .sel(sel[0]),
                .out(level1[i/2])
            );
        end
    endgenerate

    // Third level of multiplexers
    generate
        for (i = 0; i < 8; i = i + 2) begin : level2_gen
            mux_2to1 mux_inst(
                .in({level1[i], level1[i+1]}),
                .sel(sel[1]),
                .out(level2[i/2])
            );
        end
    endgenerate

    // Fourth level of multiplexers
    generate
        for (i = 0; i < 4; i = i + 2) begin : level3_gen
            mux_2to1 mux_inst(
                .in({level2[i], level2[i+1]}),
                .sel(sel[2]),
                .out(level3[i/2])
            );
        end
    endgenerate

    // Fifth level of multiplexers
    generate
        mux_2to1 mux_inst(
            .in({level3[0], level3[1]}),
            .sel(sel[3]),
            .out(level4[0])
        );
        mux_2to1 mux_inst(
            .in({level3[2], level3[3]}),
            .sel(sel[3]),
            .out(level4[1])
        );
    endgenerate

    // Sixth level of multiplexers
    generate
        mux_2to1 mux_inst(
            .in({level4[0], level4[1]}),
            .sel(sel[3]),
            .out(level5)
        );
    endgenerate

    // Seventh level of multiplexers
    generate
        mux_2to1 mux_inst(
            .in({level5[0:127], level5[128:255]}),
            .sel(sel[3]),
            .out(level6)
        );
    endgenerate

    // Eighth level of multiplexers
    generate
        mux_2to1 mux_inst(
            .in({level6[0:511], level6[512:1023]}),
            .sel(sel[3]),
            .out(level7)
        );
    endgenerate

    // Output the selected 8-bit input
    assign out = level7[sel];

endmodule


