module my_alu(cw, a0, a1, a2, a3, c0, c1);
input wire [7:0] a0, a1, a2, a3;            /* the inputs to the alu */
input wire [9:0] cw;                          /* the control word */
output wire [7:0] c0, c1;                   /* the alu outputs */

/* Temporary results */
wire [15:0] a0sq, a0qu;
wire [15:0] a1sq, a1qu;
wire [15:0] a2sq, a2qu;
wire [15:0] sa2, sa4, sa5, sa7, sa8, sa8_1;
wire [15:0] sc1;
wire [15:0] sd2, sd2_1;

/* Multiplier inputs and output */
wire [15:0] minA, minB, mout;

multiplier mul(minA, minB, mout);
squarer     sq1_p0(a0, a0sq);
squarer     sq_p1(a1, a1sq);
squarer     sq_p2(a2, a2sq);

squarer     sq2_p2(a2sq, a2qu);
squarer     sq2_p1(a1sq, a1qu);
squarer     sq2_p3(a0sq, a0qu);

/* Choose the inputs to the Multiplier */
mux8       muxA(a0,   a0sq, a2, sa7, sd2, a1, a1qu, 8'd0, cw[2:0], minA);
mux8       muxB(a1,   a1sq, sa4, sa8, sd2_1, a3, a2qu,a1qu, cw[5:3], minB);

/* Choose the outputs of the ALU */
mux4       muxC(mout,  sa2, a1sq, sc1, cw[7:6], c0);  
mux4       muxD(sa8_1,  sa5, a1qu, sd2, cw[9:8], c1);  

assign sa2 = mout ^ a2;
assign sa4 = a1sq ^ a2;
assign sa5 = mout ^ a2sq ^ a0;
assign sa7 = a0 ^ a2;
assign sa8 = a1 ^ a3;
assign sa8_1 = mout ^ a0;

assign sc1 = mout ^ a3;

assign sd2 = a0qu ^ a1;
assign sd2_1 = a2sq ^ a3 ^ a1;

endmodule

module multiplier(minA, minB, mout);
input wire [15:0] minA, minB;
output reg [15:0] mout;

always @(*) begin
    case(minA)
        16'd0: mout = 16'd0;
        16'd1: mout = minB;
        16'd2: mout = minB << 1;
        16'd3: mout = (minB << 1) + minB;
        16'd4: mout = minB << 2;
        16'd5: mout = (minB << 2) + minB;
        16'd6: mout = (minB << 2) + (minB << 1);
        16'd7: mout = (minB << 2) + (minB << 1) + minB;
        16'd8: mout = minB << 3;
        default: mout = 16'd0;
    endcase
end

endmodule

