    wire nand3_out;
    wire nand4_out;
    wire nand5_out;
    wire nand6_out;
    wire nand7_out;
    wire nand8_out;

    nand_gate nand1(D, CLK, nand1_out);
    nand_gate nand2(nand1_out, RESET_B, nand2_out);
    nand_gate nand3(nand1_out, nand4_out, nand3_out);
    nand_gate nand4(nand2_out, nand3_out, nand4_out);
    nand_gate nand5(nand4_out, CLK, nand5_out);
    nand_gate nand6(nand4_out, nand7_out, nand6_out);
    nand_gate nand7(nand5_out, nand6_out, nand7_out);
    nand_gate nand8(nand6_out, RESET_B, Q_N);

    assign Q = ~Q_N;
endmodule

