wire [3:0] s1, s2, s3;

// First adder stage
full_adder FA1(A[0], B[0], Cin, s1[0], c1);

// Second adder stage
full_adder FA2(A[1], B[1], c1, s2[1], c2);

// Third adder stage
full_adder FA3(A[2], B[2], c2, s3[2], c3);

// Final adder stage
full_adder FA4(A[3], B[3], c3, Sum[3], Cout);

// Output signals
assign Sum[0] = s1[0];
assign Sum[1] = s2[1];
assign Sum[2] = s3[2];
