module FA_46 ( A, B, Ci, S, Co );
  input A, B, Ci;
  output S, Co;
  wire   n9, n10, n11;

  // Implement S = XNOR(A XOR B, Ci)
  XNOR2_X1 U1 ( .A(A ^ B), .B(Ci), .ZN(S) );

  // Implement Co = NAND(A, B, Ci)
  NAND3_X1 U2 ( .A1(A), .A2(B), .A3(Ci), .ZN(n11) );
  NOT_X1 U3 ( .A(n11), .ZN(Co) );
endmodule

module Ethernet_MAC (
  input [n-1:0] data_in,
  input [47:0] dest_mac,
  input [47:0] src_mac,
  input clk,
  input reset,
  output reg [n-1:0] data_out,
  output reg [47:0] dest_mac_out,
  output reg [47:0] src_mac_out,
  output reg tx_en,
  output reg rx_en
);

parameter n = 8; // number of input signals
parameter m = 8; // number of output signals

reg [7:0] preamble = 8'h55; // Ethernet preamble
reg [31:0] sfd = 32'hD5C5D5C5; // Ethernet Start Frame Delimiter

reg [47:0] dest_mac_reg; // register for storing destination MAC address
reg [47:0] src_mac_reg; // register for storing source MAC address
reg [n-1:0] data_reg; // register for storing data

reg [31:0] frame_cnt; // counter for tracking the number of bits in a frame
reg [3:0] state; // state machine state

parameter IDLE = 4'b0000; // idle state
parameter PREAMBLE = 4'b0001; // preamble state
parameter SFD = 4'b0010; // start frame delimiter state
parameter DEST_MAC = 4'b0011; // destination MAC address state
parameter SRC_MAC = 4'b0100; // source MAC address state
parameter LENGTH = 4'b0101; // length state
parameter DATA = 4'b0110; // data state
parameter FCS = 4'b0111; // frame check sequence state

always @(posedge clk) begin
  if (reset) begin
    state <= IDLE;
    frame_cnt <= 0;
    tx_en <= 0;
    rx_en <= 0;
  end else begin
    case (state)
      IDLE: begin
        tx_en <= 0;
        rx_en <= 1;
        if (data_in != 0) begin
          state <= PREAMBLE;
          frame_cnt <= 0;
          dest_mac_reg <= dest_mac;
          src_mac_reg <= src_mac;
          data_reg <= data_in;
        end
      end
      PREAMBLE: begin
        tx_en <= 1;
        rx_en <= 0;
        if (frame_cnt == 7) begin
          state <= SFD;
          frame_cnt <= 0;
        end else begin
          data_out <= preamble;
          frame_cnt <= frame_cnt + 1;
        end
      end
      SFD: begin
        tx_en <= 1;
        rx_en <= 0;
        if (frame_cnt == 31) begin
          state <= DEST_MAC;
          frame_cnt <= 0;
        end else begin
          data_out <= sfd[frame_cnt];
          frame_cnt <= frame_cnt + 1;
        end
      end
      DEST_MAC: begin
        tx_en <= 1;
        rx_en <= 0;
        if (frame_cnt == 47) begin
          state <= SRC_MAC;
          frame_cnt <= 0;
        end else begin
          data_out <= dest_mac_reg[frame_cnt];
          frame_cnt <= frame_cnt + 1;
        end
      end
      SRC_MAC: begin
        tx_en <= 1;
        rx_en <= 0;
        if (frame_cnt == 95) begin
          state <= LENGTH;
          frame_cnt <= 0;
        end else begin
          data_out <= src_mac_reg[frame_cnt-48];
          frame_cnt <= frame_cnt + 1;
        end
      end
      LENGTH: begin
        tx_en <= 1;
        rx_en <= 0;
        if (frame_cnt == 111) begin
          state <= DATA;
          frame_cnt <= 0;
        end else begin
          data_out <= 0;
          frame_cnt <= frame_cnt + 1;
        end
      end
      DATA: begin
        tx_en <= 1;
        rx_en <= 0;
        if (frame_cnt == (n*8)-1) begin
          state <= FCS;
          frame_cnt <= 0;
        end else begin
          data_out <= data_reg[frame_cnt-112];
          frame_cnt <= frame_cnt + 1;
        end
      end
      FCS: begin
        tx_en <= 1;
        rx_en <= 0;
        if (frame_cnt == 127) begin
          state <= IDLE;
          frame_cnt <= 0;
        end else begin
          data_out <= 0;
          frame_cnt <= frame_cnt + 1;
        end
      end
    endcase
  end
end

endmodule

module binary_op (
  input [3:0] A,
  output [3:0] B
);

  wire is_multiple_of_3 = ((A[1:0] + A[3:2]) % 3) == 0;
  wire add_one = ~is_multiple_of_3;

  assign B = is_multiple_of_3 ? (A >> 2) : (A + 1);

endmodule

module etx_arbiter (/*AUTOARG*/
   // Outputs
   txwr_wait, txrd_wait, txrr_wait, etx_access, etx_packet, etx_rr,
   // Inputs
   clk, reset, txwr_access, txwr_packet, txrd_access, txrd_packet,
   txrr_access, txrr_packet, etx_rd_wait, etx_wr_wait, etx_cfg_wait,
   ctrlmode_bypass, ctrlmode
   );

   parameter PW = 104;
   parameter ID = 0;

   //tx clock and reset
   input          clk;
   input          reset;

   //Write Request (from slave)
   input 	   txwr_access;
   input [PW-1:0]  txwr_packet;
   output          txwr_wait;

   //Read Request (from slave)
   input 	   txrd_access;
   input [PW-1:0]  txrd_packet;
   output          txrd_wait;

   //Read Response (from master)
   input 	   txrr_access;
   input [PW-1:0]  txrr_packet;
   output          txrr_wait;

   //Wait signal inputs
   input           etx_rd_wait;
   input           etx_wr_wait;
   input 	   etx_cfg_wait;

   //ctrlmode for rd/wr transactions
   input 	   ctrlmode_bypass;
   input [3:0] 	   ctrlmode;

   //Transaction for IO protocol
   output          etx_access;
   output [PW-1:0] etx_packet;
   output 	   etx_rr;      //bypass translation on read response

   //regs
   reg 		   etx_access;
   reg [PW-1:0]    etx_packet;
   reg 		   etx_rr;     //bypass translation on read response

   //wires  
   wire [3:0] 	   txrd_ctrlmode;
   wire [3:0] 	   txwr_ctrlmode;
   wire 	   access_in;   
   wire [PW-1:0]   etx_packet_mux;
   wire 	   txrr_grant;
   wire 	   txrd_grant;
   wire 	   txwr_grant;
   wire 	   txrr_arb_wait;
   wire 	   txrd_arb_wait;
   wire 	   txwr_arb_wait;
   wire [PW-1:0]   txrd_data;
   wire [PW-1:0]   txwr_data;
   wire [PW-1:0]   etx_mux;
   wire            write_in;

   //##########################################################################
   //# Insert special control mode
   //##########################################################################
   assign txrd_ctrlmode[3:0] =  ctrlmode_bypass ?  ctrlmode[3:0] : 
				                   txrd_packet[7:4];

   assign txrd_data[PW-1:0] = {txrd_packet[PW-1:8],   
                               txrd_ctrlmode[3:0], 
			       txrd_packet[3:0]};


   assign txwr_ctrlmode[3:0] =  ctrlmode_bypass ?  ctrlmode[3:0] : 
				                   txwr_packet[7:4];

   assign txwr_data[PW-1:0] = {txwr_packet[PW-1:8],   
                               txwr_ctrlmode[3:0], 
			       txwr_packet[3:0]};

   //##########################################################################
   //# Arbiter
   //##########################################################################


   arbiter_priority #(.ARW(3)) arbiter (.grant({txrr_grant,	
						txrd_grant,
						txwr_grant //highest priority
						}),
				        .await({txrr_arb_wait,	
						txrd_arb_wait,
						txwr_arb_wait
						}),	
					.request({txrr_access,	
						  txrd_access,
						  txwr_access
						  })	
				  );
   //Priority Mux
   assign etx_mux[PW-1:0] =({(PW){txwr_grant}} & txwr_data[PW-1:0]) |
			   ({(PW){txrd_grant}} & txrd_data[PW-1:0]) |
			   ({(PW){txrr_grant}} & txrr_packet[PW-1:0]);

   //######################################################################
   //Pushback (stall) Signals
   //######################################################################

   //Write waits on pin wr wait or cfg_wait
   assign txwr_wait = etx_wr_wait | 
		      etx_cfg_wait;

   //Host read request (self throttling, one read at a time)
   assign txrd_wait = etx_rd_wait | 
		      etx_cfg_wait | 
		      txrd_arb_wait;
   //Read response
   assign txrr_wait = etx_wr_wait | 
		      etx_cfg_wait | 
		      txrr_arb_wait;


   //#####################################################################
   //# Pipeline stage (arbiter+mux takes time..)
   //#####################################################################
   assign access_in = (txwr_grant & ~txwr_wait) |
		      (txrd_grant & ~txrd_wait) |
		      (txrr_grant & ~txrr_wait);

   //Pipeline + stall
   assign write_in = etx_mux[1];

   //access
    always @ (posedge clk)
      if (reset)
	begin
	   etx_access        <= 1'b0;   
	   etx_rr            <= 1'b0;	   
	end
      else if (access_in & (write_in & ~etx_wr_wait) | (~write_in & ~etx_rd_wait))
	begin
	   etx_access         <= access_in;
	   etx_rr             <= txrr_grant;
	end	   

   //packet
   always @ (posedge clk)
     if (access_in & (write_in & ~etx_wr_wait) | (~write_in & ~etx_rd_wait))
	  etx_packet[PW-1:0] <= etx_mux[PW-1:0];	 

endmodule

module tb_norm();

    reg clk;
    reg reset_n;
    reg [15:0] in_data;
    reg in_dv;
    reg in_fv;
    wire out_fv;
    wire out_dv;
    wire [15:0] out_data;
    integer fp_out;
    integer fp_norm;
    integer fp_in;

    reg [31:0] counter;
    reg [31:0] toto;

    parameter MAX_CYCLES = 1000;

    initial begin
        $dumpfile("/tmp/tb_norm.vcd");
        $dumpvars;
        fp_out = $fopen("data_out.txt", "w");
        fp_norm = $fopen("data_norm.txt", "w");
        fp_in = $fopen("input.txt", "r");

        clk = 0;
        reset_n = 1;
        in_dv = 0;
        in_data = 0;

        counter = 0;
        toto = 0;

        #1 reset_n = 1'd0;
        #4 reset_n = 1'd1;
    end

    always #1 clk = ~clk;

    always @(posedge clk) begin
        if (reset_n == 0) begin
            in_dv <= 0;
            in_fv <= 0;
            in_data <= 0;
            counter <= 0;
            toto <= 0;
        end else begin
            if (counter < 15 || toto > 1) begin
                in_dv <= $random;
                in_fv <= 1;
            end else begin
                in_dv <= 0;
                in_fv <= 0;
            end

            if (counter < 15 || toto > 1) begin
                dummy = $fscanf(fp_in,"%d\n",in_data);
            end else begin
                in_data <= 0;
            end

            if (counter >= 15) begin
                toto <= toto + 1;
            end

            if (in_dv) begin
                counter <= counter + 1;
            end
        end
    end

    always @(posedge clk) begin
        if (out_fv & out_dv) begin
            $fwrite(fp_out, "%d\n", out_data);
        end
    end

    always @(*) begin
        out_data_s = out_data;
    end

    norm norm_inst(
        .clk_proc(clk),
        .reset_n(reset_n),
        .in_fv(in_fv),
        .in_dv(in_dv),
        .in_data(in_data),
        .out_fv(out_fv),
        .out_dv(out_dv),
        .out_data(out_data),
        .addr_rel_i(),
        .wr_i(),
        .datawr_i(),
        .rd_i(),
        .datard_o()
    );

    integer cycles = 0;
    integer expected_norm;
    integer actual_norm;

    initial begin
        while (cycles < MAX_CYCLES) begin
            #1;
            if (out_fv) begin
                // Read input data
                dummy = $fscanf(fp_in, "%d\n", in_data);
                in_fv <= 1;
            end
            if (out_fv & !out_dv) begin
                // Read expected normalized value
                dummy = $fscanf(fp_norm, "%d\n", expected_norm);
            end
            if (out_fv & out_dv) begin
                // Verify normalized value
                actual_norm = out_data_s;
                if (actual_norm != expected_norm) begin
                    $display("Error: expected %d, actual %d", expected_norm, actual_norm);
                    $finish;
                end
                in_fv <= 0;
            end
            cycles = cycles + 1;
        end
        $display("Testbench completed successfully");
        $finish;
    end
endmodule

