module cic_decim_8_12_20(clk, cken_in, cken_out, decimrate, reset, din, dout);
   input [11:0]    din;
   input [2:0]     decimrate; /* Set to decimrate - 1*/     
   output [19:0]   dout;
   reg [19:0]      dout;
   input           clk, cken_in, reset;
   output          cken_out;
   reg             cken_out;       
   reg [35:0]      i0, i1, i2, i3, i4, i5, i6, i7;
   reg [35:0]      d0, d1, d2, d3, d4, d5, d6, d7;
   reg [2:0]       decimcount; 

   always @(posedge clk)
     if(reset == 1'b1)
       begin
         decimcount <= 0;
         i0 <= 0;
         i1 <= 0;
         i2 <= 0;
         i3 <= 0;
         i4 <= 0;
         i5 <= 0;
         i6 <= 0;
         i7 <= 0;
         d0 <= 0;
         d1 <= 0;
         d2 <= 0;
         d3 <= 0;
         d4 <= 0;
         d5 <= 0;
         d6 <= 0;
         d7 <= 0;
         dout <= 0;
         cken_out <= 0;
       end
     else if(cken_in == 1'b1)
       begin
          /* Integrators */
          i0 = i0 + {{24{din[11]}}, din};
          i1 = i1 + i0;
          i2 = i2 + i1;
          i3 = i3 + i2;
          i4 = i4 + i3;
          i5 = i5 + i4;
          i6 = i6 + i5;
          i7 = i7 + i6;
          /* Decimator */
          if(decimcount == 0)
            begin
               decimcount <= decimrate;
               cken_out <= 1'b1;
               /* Differentiators */
               d0 <= i7 - d0;
               d1 <= d0 - d1;
               d2 <= d1 - d2;
               d3 <= d2 - d3;
               d4 <= d3 - d4;
               d5 <= d4 - d5;
               d6 <= d5 - d6;
               d7 <= d6 - d7;
               /* Bit shifter */
               if(decimrate[2] == 1'b1)
                 dout <= d7[35:16];
               else if(decimrate[1] == 1'b1)
                 dout <= d7[27:8];
               else
                 dout <= d7[19:0];
               /* Reset integrators */
               i0 <= 0;
               i1 <= 0;
               i2 <= 0;
               i3 <= 0;
               i4 <= 0;
               i5 <= 0;
               i6 <= 0;
               i7 <= 0;
            end // if (decimcount == 0)
          else
            begin
               decimcount = decimcount - 1;
               cken_out <= 1'b0;
            end // else: !if(decimcount == 0)
       end // if (cken_in)
endmodule

module arithm2 (
    input clk,
    input ce,
    input [17:0] A,
    input [7:0] B,
    input [11:0] C,
    input [7:0] D,
    input [13:0] E,
    input [18:0] F,
    output reg [36:0] Y
);

    wire [25:0] M1;
    wire [12:0] M2;
    wire [22:0] M3;
    wire [38:0] M4;

    // Multiply A and B
    mult #(.A_WIDTH(18), .B_WIDTH(8), .P_WIDTH(26)) mult1 (
        .clk(clk),
        .ce(ce),
        .a(A),
        .b(B),
        .p(M1)
    );

    // Add C and D
    addsub #(.WIDTH(12), .MODE(1)) addsub1 (
        .clk(clk),
        .ce(ce),
        .a(C),
        .b(D),
        .c(1'b0),
        .y(M2)
    );

    // Divide E by F
    div #(.A_WIDTH(14), .B_WIDTH(19), .Q_WIDTH(23)) div1 (
        .clk(clk),
        .ce(ce),
        .a(E),
        .b(F),
        .q(M3)
    );

    // Multiply M1 and M2
    mult #(.A_WIDTH(26), .B_WIDTH(13), .P_WIDTH(39)) mult2 (
        .clk(clk),
        .ce(ce),
        .a(M1),
        .b(M2),
        .p(M4)
    );

    // Subtract M3 from M4
    addsub #(.WIDTH(39), .MODE(0)) addsub2 (
        .clk(clk),
        .ce(ce),
        .a(M4),
        .b({13'b0, M3}),
        .c(1'b0),
        .y(Y)
    );

endmodule

module fifo_checksum #(
	parameter DATA_W = 1,
	parameter ONECLOCK = 1,
  	parameter EXTERNALLY_OUTPUT_REGISTERED = 0,
	parameter ERROR_SHIFT_BITS = 4
) (
	input wr_reset,
	input rd_reset,

	input wr_clk,
	input wr_en,
	input wr_full,
	input [DATA_W-1:0] wr_data,

	input rd_clk,
	input rd_en,
	input rd_empty,
	input [DATA_W-1:0] rd_data,

	output reg checksum_error
);

// ******************************************
// Generate running checksum on wr_data.
// Only pay attention to the first 8-bits of the data for the checksum.
// ******************************************

localparam CHECKSUM_W = (DATA_W<16) ? (DATA_W+1)/2 : 4;

reg [CHECKSUM_W-1:0] wr_checksum;
always @(posedge wr_clk) begin
	if ((wr_en==1'b1) && (wr_full==1'b0)) begin
		wr_checksum <= wr_checksum ^ wr_data ^ (wr_data >> CHECKSUM_W);
	end
	if (wr_reset ) begin
		wr_checksum <= 'b0;
	end
end

// ******************************************
// Generate running checksum on rd_data.
// ******************************************

reg [CHECKSUM_W-1:0] rd_checksum;
always @(posedge rd_clk) begin
	if ((rd_en==1'b1) && (rd_empty==1'b0)) begin
		rd_checksum <= rd_checksum ^ rd_data ^ (rd_data >> CHECKSUM_W);
	end
	if (rd_reset) begin
		rd_checksum <= 'b0;
	end
end

// ******************************************
// Compare wr_checksum to rd_checksum when the FIFO is really empty.
// ******************************************

reg error_shift;
reg [ERROR_SHIFT_BITS-1:0] error_counter;

always @(posedge rd_clk) begin
	if (
`ifdef USE_SYNC_FIFO_CHECKSUM
`else
			ONECLOCK |
`endif
			EXTERNALLY_OUTPUT_REGISTERED) begin
		// do nothing (i.e. don't create the FFs)
	end else begin
		error_shift <= 1'b0;
		if (rd_empty==1'b1) begin
			if (rd_checksum != wr_checksum) begin
				error_shift <= 1'b1;
			end
		end
		if (error_shift==1'b1)
				error_counter <= error_counter+1'b1;
		else
				error_counter <= 1'b0;

		if (&error_counter) begin
			$display("ERROR: %m fifo checksums don't match: %x != %x\n",wr_checksum, rd_checksum);
			$stop;
			checksum_error <= 1'b1;
		end

		if (rd_reset) begin
			checksum_error <= 1'b0;
			error_shift <= 'b0;
			error_counter <= 'b0;
		end
	end
end

endmodule

module vending_machine (
  input clk,
  input reset,
  input coin,
  output reg [11:0] display,
  output reg dispense
);

  parameter IDLE = 2'b00;
  parameter DISPENSING = 2'b01;
  parameter INVALID_COIN = 2'b10;

  reg [1:0] state;
  reg [2:0] delay_count;

  always @(posedge clk) begin
    if (reset) begin
      state <= IDLE;
      delay_count <= 0;
      display <= 12'h000; // "INSERT COIN"
      dispense <= 0;
    end
    else begin
      case (state)
        IDLE: begin
          if (coin) begin
            state <= DISPENSING;
            display <= 12'h001; // "THANK YOU"
            dispense <= 1;
          end
          else begin
            state <= IDLE;
            display <= 12'h000; // "INSERT COIN"
            dispense <= 0;
          end
        end
        DISPENSING: begin
          delay_count <= 3;
          state <= DISPENSING;
          display <= 12'h001; // "THANK YOU"
          dispense <= 1;
        end
        INVALID_COIN: begin
          delay_count <= 3;
          state <= IDLE;
          display <= 12'h010; // "INVALID COIN"
          dispense <= 0;
        end
      endcase
    end
  end

  always @(posedge clk) begin
    if (delay_count > 0) begin
      delay_count <= delay_count - 1;
    end
    else if (state == DISPENSING) begin
      state <= IDLE;
      display <= 12'h000; // "INSERT COIN"
      dispense <= 0;
    end
  end

endmodule

module booth_multiplier(
    input [3:0] A,
    input [3:0] B,
    output reg [7:0] result
);

reg [3:0] A_reg, B_reg;
reg [2:0] count;
reg [3:0] partial_product;
reg [4:0] multiplier;
reg [1:0] state;

wire shift_left, shift_right;

assign shift_left = (count == 0) ? 1 : 0;
assign shift_right = (count == 3) ? 1 : 0;

always @(*) begin
    A_reg = A;
    B_reg = B;
    multiplier = {B_reg, 2'b00};
    partial_product = {A_reg, 2'b00};
end

always @(posedge clk) begin
    if (reset) begin
        count <= 0;
        state <= 0;
        result <= 0;
    end else begin
        case (state)
            0: begin // Idle state
                if (start) begin
                    state <= 1;
                end
            end
            1: begin // Shift state
                if (shift_left) begin
                    multiplier <= {multiplier[7:1], multiplier[0]};
                    count <= count + 1;
                end else if (shift_right) begin
                    multiplier <= {multiplier[6:0], multiplier[7]};
                    count <= count - 1;
                end
                state <= 2;
            end
            2: begin // Add/Subtract state
                if (multiplier[1:0] == 2'b01) begin
                    result <= result + partial_product;
                end else if (multiplier[1:0] == 2'b10) begin
                    result <= result - partial_product;
                end
                state <= 1;
            end
            default: state <= 0;
        endcase
    end
end

endmodule

