module ripple_carry_adder(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

wire [3:0] sum;
wire [3:0] carry;

// Full adder for the least significant bit
full_adder fa0(A[0], B[0], Cin, sum[0], carry[0]);

// Full adder for the second least significant bit
full_adder fa1(A[1], B[1], carry[0], sum[1], carry[1]);

// Full adder for the third least significant bit
full_adder fa2(A[2], B[2], carry[1], sum[2], carry[2]);

// Full adder for the most significant bit
full_adder fa3(A[3], B[3], carry[2], sum[3], Cout);

assign S = sum;

endmodule

module full_adder(
    input A,
    input B,
    input Cin,
    output S,
    output Cout
);

assign {Cout, S} = A + B + Cin;

endmodule

module prometheus_fx3_ZLP(
    input  rst_n,
    input  clk_100,
    input  zlp_mode_selected,
    input  i_gpif_in_ch0_rdy_d,
    input  i_gpif_out_ch0_rdy_d,
    output o_gpif_we_n_zlp_,
    output o_gpif_pkt_end_n_zlp_,
    output [31:0] data_out_zlp
);

reg [2:0] current_zlp_state;
reg [2:0] next_zlp_state;

//parameters for ZLP mode state machine
parameter [2:0] zlp_idle                          = 3'd0;
parameter [2:0] zlp_wait_flagb                    = 3'd1;
parameter [2:0] zlp_write                         = 3'd2;
parameter [2:0] zlp_write_wr_delay                = 3'd3;
parameter [2:0] zlp_wait                          = 3'd4;

reg [3:0] strob_cnt;
reg strob;
reg [31:0] data_gen_zlp;
reg o_gpif_pkt_end_n_;


assign o_gpif_we_n_zlp_ = ((current_zlp_state == zlp_write) && (i_gpif_out_ch0_rdy_d == 1'b1)) ? 1'b0 : 1'b1;


//counter to generate the strob for ZLP data pkts
always @(posedge clk_100, negedge rst_n) begin
    if (!rst_n) begin
        strob_cnt <= 4'd0;
    end else if (current_zlp_state == zlp_idle) begin
        strob_cnt <= 4'd0;
    end else if (current_zlp_state == zlp_wait) begin
        strob_cnt <= strob_cnt + 1'b1;
    end
end

//Strob logic
always @(posedge clk_100, negedge rst_n) begin
    if (!rst_n) begin
        strob <= 1'b0;
    end else if ((current_zlp_state == zlp_wait) && (strob_cnt == 4'b0111)) begin
        strob <= !strob;
    end
end

always @(*) begin
    if (zlp_mode_selected & (strob_cnt == 4'b0011) & (strob == 1'b1)) begin
        o_gpif_pkt_end_n_ = 1'b0;
    end else begin
        o_gpif_pkt_end_n_ = 1'b1;
    end
end

assign o_gpif_pkt_end_n_zlp_ = o_gpif_pkt_end_n_;


//ZLP mode state machine
always @(posedge clk_100, negedge rst_n) begin
    if (!rst_n) begin
        current_zlp_state <= zlp_idle;
    end else begin
        current_zlp_state <= next_zlp_state;
    end
end

//ZLP mode state machine combo
always @(*) begin
    next_zlp_state = current_zlp_state;
    case (current_zlp_state)
        zlp_idle: begin
            if ((zlp_mode_selected) & (i_gpif_in_ch0_rdy_d == 1'b1)) begin
                next_zlp_state = zlp_wait_flagb;
            end else begin
                next_zlp_state = zlp_idle;
            end
        end
        zlp_wait_flagb: begin
            if ((strob == 1'b1) & (i_gpif_out_ch0_rdy_d == 1'b1)) begin
                next_zlp_state = zlp_wait;
            end else if ((i_gpif_out_ch0_rdy_d == 1'b1) && (strob == 1'b0)) begin
                next_zlp_state = zlp_write;
            end else begin
                next_zlp_state = zlp_wait_flagb;
            end
        end
        zlp_write: begin
            if (i_gpif_out_ch0_rdy_d == 1'b0) begin
                next_zlp_state = zlp_write_wr_delay;
            end else begin
                next_zlp_state = zlp_write;
            end
        end
        zlp_write_wr_delay: begin
            next_zlp_state = zlp_wait;
        end
        zlp_wait: begin
            if (strob_cnt == 4'b1111) begin
                next_zlp_state = zlp_idle;
            end else begin
                next_zlp_state = zlp_wait;
            end
        end
    endcase
end

//data generator counter for zlp mode
always @(posedge clk_100, negedge rst_n) begin
    if (!rst_n) begin
        data_gen_zlp <= 32'd0;
    end else if ((o_gpif_we_n_zlp_ == 1'b0) & (zlp_mode_selected)) begin
        data_gen_zlp <= data_gen_zlp + 1;
    end else if (!zlp_mode_selected) begin
        data_gen_zlp <= 32'd0;
    end
end

assign data_out_zlp = data_gen_zlp;

endmodule

module top_module (
  input                clk,        // Clock input
  input                reset,      // Synchronous active-high reset
  input       [7:0]    d,          // 8-bit input for the accumulator
  input                select,     // Select input to choose between accumulator and counter
  input                valid_a,    // Valid signal for the accumulator
  input                ready_b,    // Ready signal for the additional functional module
  output               ready_a,    // Ready signal for the upstream module
  output  reg          valid_b,    // Valid signal for the downstream module
  output  reg [9:0]    data_out,   // Output of the accumulator
  output  reg [3:0]    q           // Output of the counter
);

  // Instantiate the modified Booth algorithm accumulator module
  booth_accumulator booth_accumulator_inst (
    .clk(clk),
    .reset(reset),
    .d(d),
    .valid(valid_a),
    .ready(ready_a),
    .data_out(data_out)
  );

  // Instantiate the 4-bit binary counter module
  binary_counter binary_counter_inst (
    .clk(clk),
    .reset(reset),
    .q(q)
  );

  always @(posedge clk) begin
    if (reset) begin
      valid_b <= 0;
    end else begin
      if (select) begin
        // Counter mode
        valid_b <= 1;
        data_out <= {6'b0, q};
      end else begin
        // Accumulator mode
        if (valid_a && ready_a) begin
          valid_b <= 1;
          if (data_out[1:0] == 2'b11) begin
            data_out <= data_out + {1'b0, booth_accumulator_inst.data_out};
          end else if (data_out[1:0] == 2'b10) begin
            data_out <= data_out + {1'b0, booth_accumulator_inst.data_out, booth_accumulator_inst.data_out};
          end else if (data_out[1:0] == 2'b01) begin
            data_out <= data_out - {1'b0, booth_accumulator_inst.data_out, booth_accumulator_inst.data_out};
          end else begin
            data_out <= data_out - {1'b0, booth_accumulator_inst.data_out};
          end
        end else begin
          valid_b <= 0;
        end
      end
    end
  end

  assign ready_a = !valid_a || (valid_a && ready_b);

endmodule

