    #5 rst = 1;
    #5 rst = 0;
    #20;
    if (count !== 4'b0001) begin
      $error("Error: count value is %b, expected 0001", count);
    end

    #5;
    if (count !== 4'b0010) begin
      $error("Error: count value is %b, expected 0010", count);
    end

    #5;
    if (count !== 4'b0011) begin
      $error("Error: count value is %b, expected 0011", count);
    end

    // check counter resets to zero
    #5 rst = 1;
    #5 rst = 0;
    #20;
    if (count !== 4'b0000) begin
      $error("Error: count value is %b, expected 0000 after reset", count);
    end

    $display("Counter testbench passed");
    $finish;
  end

  always #5 clk = ~clk;

endmodule

