module fsm_hello_detection (
  input clk,
  input reset,
  input [7:0] data,
  output reg match
);

  parameter IDLE = 2'b00;
  parameter H = 2'b01;
  parameter HE = 2'b10;
  parameter HEL = 2'b11;
  parameter HELLO = 2'b100;

  reg [2:0] state = IDLE;

  always @(posedge clk) begin
    if (reset) begin
      state <= IDLE;
      match <= 0;
    end else begin
      case (state)
        IDLE: begin
          if (data == 8'h68) begin // 'h' character
            state <= H;
          end
        end
        H: begin
          if (data == 8'h65) begin // 'e' character
            state <= HE;
          end else begin
            state <= IDLE;
          end
        end
        HE: begin
          if (data == 8'h6C) begin // 'l' character
            state <= HEL;
          end else if (data != 8'h65) begin // 'e' character
            state <= IDLE;
          end
        end
        HEL: begin
          if (data == 8'h6C) begin // 'l' character
            state <= HELLO;
          end else if (data != 8'h65) begin // 'e' character
            state <= IDLE;
          end else begin
            state <= HE;
          end
        end
        HELLO: begin
          match <= 1;
          state <= IDLE;
        end
      endcase
    end
  end

endmodule

