module fifo_buffer
   (full,
    WEA,
    Q,
    wr_clk,
    out,
    wr_en,
    AR,
    RD_PNTR_WR,
    wr_rst_busy);
  output full;
  output [0:0]WEA;
  output [9:0]Q;
  input wr_clk;
  input out;
  input wr_en;
  input [0:0]AR;
  input [9:0]RD_PNTR_WR;
