        .v1_reg(v1_reg),
        .v1_reg_0(v1_reg_0),
        .wr_clk(wr_clk),
        .wr_en(wr_en),
        .wr_rst_busy(wr_rst_busy));

  fifo_bt_txd_wr_bin_cntr wpntr
       (.AR(AR),
        .E(WEA),
        .Q(Q),
        .RD_PNTR_WR(RD_PNTR_WR),
        .v1_reg(v1_reg),
        .v1_reg_0(v1_reg_0),
        .wr_clk(wr_clk));

  reg [9:0] mem [0:1023];
  reg [9:0] wr_ptr;
  reg [9:0] rd_ptr;
  reg [9:0] count;
  reg full;

  always @(posedge wr_clk) begin
    if (wr_rst_busy) begin
      wr_ptr <= 10'b0;
      rd_ptr <= 10'b0;
      count <= 10'b0;
      full <= 1'b0;
    end else if (wr_en && !full) begin
      mem[wr_ptr] <= out;
      wr_ptr <= (wr_ptr == 10'b1111111111) ? 10'b0 : wr_ptr + 10'b1;
      count <= count + 10'b1;
      if (count == 10'b1111111111) begin
        full <= 1'b1;
      end
