  always @(posedge wr_clk) begin
    if (AR == 1'b1) begin
      rd_ptr <= (rd_ptr == 10'b1111111111) ? 10'b0 : rd_ptr + 10'b1;
      count <= count - 10'b1;
      full <= 1'b0;
