module carry_select_adder (
  input [n-1:0] A,
  input [n-1:0] B,
  input Cin,
  output [n-1:0] S,
  output Cout
);

parameter n = 4; // number of bits in the binary numbers

wire [n-1:0] sum0, sum1;
wire [n:0] carry0, carry1;

// First adder circuit assuming carry-in of 0
adder0 add0 (
  .A(A),
  .B(B),
  .Cin(0),
  .S(sum0),
  .Cout(carry0)
);

// Second adder circuit assuming carry-in of 1
adder1 add1 (
  .A(A),
  .B(B),
  .Cin(1),
  .S(sum1),
  .Cout(carry1)
);

// Carry-select circuit
assign S = (Cin == 0) ? sum0 : sum1;
assign Cout = (Cin == 0) ? carry0[n] : carry1[n];

endmodule

// Adder circuit with carry-in of 0
module adder0 (
  input [n-1:0] A,
  input [n-1:0] B,
  input Cin,
  output [n-1:0] S,
  output [n:0] Cout
);

parameter n = 4; // number of bits in the binary numbers

wire [n-1:0] sum;
wire [n:0] carry;

// Generate the sum and carry bits using a ripple-carry adder
ripple_adder add (
  .A(A),
  .B(B),
  .Cin(Cin),
  .S(sum),
  .Cout(carry)
);

// Assign the outputs
assign S = sum;
assign Cout = carry;

endmodule

// Adder circuit with carry-in of 1
module adder1 (
  input [n-1:0] A,
  input [n-1:0] B,
  input Cin,
  output [n-1:0] S,
  output [n:0] Cout
);

parameter n = 4; // number of bits in the binary numbers

wire [n-1:0] sum;
wire [n:0] carry;

// Generate the sum and carry bits using a ripple-carry adder
ripple_adder add (
  .A(A),
  .B(B),
  .Cin(Cin),
  .S(sum),
  .Cout(carry)
);

// Assign the outputs
assign S = sum;
assign Cout = carry;

endmodule

// Ripple-carry adder
module ripple_adder (
  input [n-1:0] A,
  input [n-1:0] B,
  input Cin,
  output [n-1:0] S,
  output [n:0] Cout
);

parameter n = 4; // number of bits in the binary numbers

wire [n-1:0] sum;
wire [n:0] carry;

// Generate the sum and carry bits for each bit position
genvar i;
generate
  for (i = 0; i < n; i = i + 1) begin : gen_adder
    full_adder add (
      .A(A[i]),
      .B(B[i]),
      .Cin(carry[i]),
      .S(sum[i]),
      .Cout(carry[i+1])
    );
  end
endgenerate

// Assign the outputs
assign S = sum;
assign Cout = carry;

endmodule

// Full-adder
module full_adder (
  input A,
  input B,
  input Cin,
  output S,
  output Cout
);

assign S = A ^ B ^ Cin;
assign Cout = (A & B) | (Cin & (A ^ B));

endmodule

