    assign w3 = ~a & b;

    assign c = w1 | w2 | w3;
endmodule

module pipeline_accumulator(
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid_in,
    output reg [9:0] data_out,
    output reg valid_out,
    output reg ready_in
);
    reg [9:0] accumulator;
    reg [2:0] count;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            accumulator <= 0;
            count <= 0;
            valid_out <= 0;
            ready_in <= 1;
        end
        else begin
            if (valid_in) begin
                accumulator <= accumulator + data_in;
                count <= count + 1;
                ready_in <= 0;

                if (count == 7) begin
                    data_out <= accumulator;
                    valid_out <= 1;
                    accumulator <= 0;
                    count <= 0;
                end
            end
            else begin
                ready_in <= 1;
            end
        end
    end
endmodule

module final_module(
    input a,
    input b,
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid_a,
    input ready_b,
    output ready_a,
    output reg valid_b,
    output reg [9:0] data_out
);
    wire xor_output;
    wire [9:0] accumulator_output;
    wire valid_out;
    wire ready_in;

    xor_gate xor_inst(
        .a(a),
        .b(b),
        .c(xor_output)
    );

    pipeline_accumulator accumulator_inst(
        .clk(clk),
        .rst_n(rst_n),
        .data_in(data_in),
        .valid_in(valid_a),
        .data_out(accumulator_output),
        .valid_out(valid_out),
        .ready_in(ready_in)
    );

    assign ready_a = ready_in & ready_b;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            valid_b <= 0;
            data_out <= 0;
        end
        else begin
            if (valid_out & valid_b) begin
                data_out <= accumulator_output + data_out;
                valid_b <= 0;
            end
            else if (valid_out & ready_a) begin
                data_out <= accumulator_output;
                valid_b <= 1;
            end
        end
    end
endmodule

module priority_encoder (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 4; // number of input signals
parameter m = 2; // number of output signals (binary code)

wire [n-1:0] or_out;
wire [n-1:0] priority;

assign or_out = |in; // OR gates to determine which input signals are active

// Determine the priority of the active input signals
genvar i;
generate
  for (i = 0; i < n; i = i + 1) begin
    assign priority[i] = (in[i] == 1'b1) ? i : n;
    // If input i is active, priority[i] = i, else priority[i] = n
  end
endgenerate

// Determine the highest priority input signal
wire [log2(n)-1:0] highest_priority;
assign highest_priority = priority < priority[in];

// Encode the highest priority input signal as a binary code
genvar j;
generate
  for (j = 0; j < m; j = j + 1) begin
    assign out[j] = (highest_priority == j) ? 1'b1 : 1'b0;
    // If highest_priority = j, out[j] = 1, else out[j] = 0
  end
endgenerate

endmodule

