    output [4:0] out );

    wire [3:0] mux_out;
    wire [4:0] parity_out;
    wire [4:0] xor_out;

    // 4-to-1 Multiplexer
    mux2to1 mux1(
        .in0(in[3:0]),
        .in1(in[7:4]),
        .sel(sel[0]),
        .out(mux_out[0])
    );

    mux2to1 mux2(
        .in0(in[11:8]),
        .in1(in[15:12]),
        .sel(sel[0]),
        .out(mux_out[1])
    );

    mux2to1 mux3(
        .in0(mux_out[0]),
        .in1(mux_out[1]),
        .sel(sel[1]),
        .out(mux_out[2])
    );

    mux2to1 mux4(
        .in0(in[0:3]),
        .in1(mux_out[2]),
        .sel(sel[1]),
        .out(mux_out[3])
    );

    // Parity Generator
    parity_generator parity(
        .in(mux_out[sel]),
        .out(parity_out)
    );

    // Functional Module
    functional_module func(
        .in1(mux_out[sel]),
        .in2({mux_out[0], mux_out[1], mux_out[2], mux_out[3], parity_out}),
        .out(xor_out)
    );

    // Output
    assign out = {xor_out[4], mux_out[sel]};
endmodule

