module motor_controller (
	input clk,
	input rst,
	input [15:0] d_in,
	input cs,
	input [3:0] addr,
	input rd,
	input wr,
	output reg [15:0] d_out,
	output reg [1:0] adelante,
	output reg [1:0] atras
);

	// Registers and wires
	reg [1:0] s;
	reg [1:0] reversa [0:1];

	// Direction module instances
	direccion direccion1 ( .reversa(reversa[0]) , .adelante(adelante[0]) , .atras(atras[0]) ) ;
	direccion direccion2 ( .reversa(reversa[1]) , .adelante(adelante[1]) , .atras(atras[1]) ) ;

	// Selector logic
	always @(*) begin
		case(addr)
			4'h0:	s = (cs && wr) ? 2'b01 : 2'b00; // Address for motor 1
			4'h2:	s = (cs && wr) ? 2'b10 : 2'b00; // Address for motor 2
			default: s = 2'b00; // No address match
		endcase
	end

	// Data input multiplexer
	always @(negedge clk) begin
		case (s)
			2'b01: 	reversa[0][0] = d_in[0]; // Set motor 1 direction
			2'b10: 	reversa[1][0] = d_in[0]; // Set motor 2 direction
			default: begin
				reversa[0][0] = 0;
				reversa[1][0] = 0;
			end
		endcase
	end

	// Direction output logic
	always @(*) begin
		case (reversa[0][0])
			1'b0: begin
				adelante[0] = 2'b00;
				atras[0] = 2'b00;
			end
			1'b1: begin
				adelante[0] = 2'b01;
				atras[0] = 2'b10;
			end
		endcase

		case (reversa[1][0])
			1'b0: begin
				adelante[1] = 2'b00;
				atras[1] = 2'b00;
			end
			1'b1: begin
				adelante[1] = 2'b01;
				atras[1] = 2'b10;
			end
		endcase
	end

