module barrel_shifter (
    input [3:0] data_in,
    input [3:0] shift_amt,
    input [3:0] select,
    output reg [3:0] data_out
);

    always @(*) begin
        case (select)
            4'b0000: data_out = data_in << shift_amt;
            4'b0001: data_out = data_in >> shift_amt;
            4'b0010: data_out = {data_in[2:0], data_in[3]};
            4'b0011: data_out = {data_in[0], data_in[3:1]};
            4'b0100: data_out = {data_in[1:0], data_in[3:2]};
            4'b0101: data_out = {data_in[0], data_in[2:0], data_in[3]};
            4'b0110: data_out = {data_in[1:0], data_in[3:1]};
            4'b0111: data_out = {data_in[0], data_in[2:1], data_in[3]};
            4'b1000: data_out = {data_in[2:0], data_in[3:1]};
            4'b1001: data_out = {data_in[1], data_in[3:0]};
            4'b1010: data_out = {data_in[2], data_in[3:1], data_in[0]};
            4'b1011: data_out = {data_in[1:0], data_in[3:2]};
            4'b1100: data_out = {data_in[0], data_in[3:0]};
            4'b1101: data_out = {data_in[2:1], data_in[3:0]};
            4'b1110: data_out = {data_in[1:0], data_in[3:1], data_in[2]};
            4'b1111: data_out = data_in;
        endcase
    end

endmodule

