module pfpu_fmul(
	input sys_clk,
	input alu_rst,

	input [31:0] a,
	input [31:0] b,
	input valid_i,

	output reg [31:0] r,
	output reg valid_o
);

wire		a_sign = a[31];
wire [7:0]	a_expn = a[30:23];
wire [23:0]	a_mant = {1'b1, a[22:0]};

wire		b_sign = b[31];
wire [7:0]	b_expn = b[30:23];
wire [23:0]	b_mant = {1'b1, b[22:0]};

reg		r_zero;
reg		r_sign;
reg [7:0]	r_expn;
reg [23:0]	r_a_mant;
reg [23:0]	r_b_mant;

reg r_valid;

/* Stage 1 */
always @(posedge sys_clk) begin
	if(alu_rst)
		r_valid <= 1'b0;
	else
		r_valid <= valid_i;
	r_zero <= (a_expn == 8'd0)|(b_expn == 8'd0);
	r_sign <= a_sign ^ b_sign;
	r_expn <= a_expn + b_expn - 8'd127;
	r_a_mant <= a_mant;
	r_b_mant <= b_mant;
end

/* Stage 2 */
reg		r1_zero;
reg		r1_sign;
reg [7:0]	r1_expn;
reg [47:0]	r1_mant;

reg r1_valid;

always @(posedge sys_clk) begin
	if(alu_rst)
		r1_valid <= 1'b0;
	else
		r1_valid <= r_valid;
	r1_zero <= r_zero;
	r1_sign <= r_sign;
	r1_expn <= r_expn;
	r1_mant <= r_a_mant*r_b_mant;
end

/* Stage 3 */
reg		r2_zero;
reg		r2_sign;
reg [7:0]	r2_expn;
reg [47:0]	r2_mant;

reg r2_valid;

always @(posedge sys_clk) begin
	if(alu_rst)
		r2_valid <= 1'b0;
	else
		r2_valid <= r1_valid;
	r2_zero <= r1_zero;
	r2_sign <= r1_sign;
	r2_expn <= r1_expn;
	r2_mant <= r1_mant;
end

/* Stage 4 */
always @(posedge sys_clk) begin
	if(alu_rst)
		valid_o <= 1'b0;
	else
		valid_o <= r2_valid;
	if(r2_zero)
		r <= {1'bx, 8'd0, 23'bx};
	else begin
		if(~r2_mant[47])
			r <= {r2_sign, r2_expn,      r2_mant[45:23]};
		else
			r <= {r2_sign, r2_expn+8'd1, r2_mant[46:24]};
	end
end

endmodule

module i2c_master (
  input clk,
  input rst,
  input sda_i,
  input scl_i,
  output reg sda_o,
  output reg scl_o,
  output reg sda_t,
  output reg scl_t
);

  // I2C states
  parameter IDLE = 2'b00;
  parameter START = 2'b01;
  parameter WRITE = 2'b10;
  parameter READ = 2'b11;

  // I2C parameters
  parameter ACK = 1'b0;
  parameter NACK = 1'b1;

  // I2C variables
  reg [7:0] data;
  reg [2:0] state;
  reg [2:0] bit_counter;
  reg [3:0] ack_counter;
  reg sda_dir;

  // I2C control signals
  reg sda;
  reg scl;

  // I2C operations
  parameter START_BIT = 1'b0;
  parameter STOP_BIT = 1'b1;

  // I2C delay
  parameter DELAY = 50;

  // I2C clock stretching
  parameter STRETCH = 1000;

  always @(posedge clk) begin
    if (rst) begin
      state <= IDLE;
      bit_counter <= 0;
      ack_counter <= 0;
      sda_dir <= 1'b1;
      sda <= 1'b1;
      scl <= 1'b1;
      sda_t <= 1'b1;
      scl_t <= 1'b1;
    end else begin
      case(state)
        IDLE: begin
          sda_t <= 1'b1;
          scl_t <= 1'b1;
          if (!sda_i && !scl_i) begin
            state <= START;
          end
        end
        START: begin
          sda_dir <= 1'b0;
          sda <= START_BIT;
          sda_t <= 1'b0;
          if (scl_i) begin
            state <= WRITE;
          end
        end
        WRITE: begin
          sda_dir <= 1'b0;
          sda <= data[bit_counter];
          sda_t <= 1'b0;
          if (scl_i) begin
            bit_counter <= bit_counter + 1;
            if (bit_counter == 8) begin
              state <= READ;
            end
          end
        end
        READ: begin
          sda_dir <= 1'b1;
          sda_t <= 1'b1;
          if (scl_i) begin
            if (sda_i) begin
              ack_counter <= ack_counter + 1;
              if (ack_counter == 4) begin
                state <= IDLE;
              end
            end else begin
              data <= {sda_i, data[7:1]};
              bit_counter <= bit_counter + 1;
              if (bit_counter == 8) begin
                bit_counter <= 0;
              end
              ack_counter <= 0;
              state <= WRITE;
            end
          end
        end
      endcase
    end
  end

  always @(posedge clk) begin
    if (rst) begin
      scl_o <= 1'b1;
    end else begin
      case(state)
        IDLE: begin
          scl_o <= 1'b1;
        end
        START: begin
          scl_o <= 1'b0;
        end
        WRITE: begin
          scl_o <= 1'b0;
        end
        READ: begin
          scl_o <= 1'b0;
        end
      endcase
    end
  end

  always @(posedge clk) begin
    if (rst) begin
      sda_o <= 1'b1;
    end else begin
      case(state)
        IDLE: begin
          sda_o <= 1'b1;
        end
        START: begin
          sda_o <= 1'b0;
        end
        WRITE: begin
          sda_o <= sda;
        end
        READ: begin
          sda_o <= sda;
        end
      endcase
    end
  end

  always @(posedge clk) begin
    if (rst) begin
      sda_t <= 1'b1;
    end else begin
      case(state)
        IDLE: begin
          sda_t <= 1'b1;
        end
        START: begin
          sda_t <= 1'b0;
        end
        WRITE: begin
          sda_t <= 1'b0;
        end
        READ: begin
          sda_t <= 1'b1;
        end
      endcase
    end
  end

  always @(posedge clk) begin
    if (rst) begin
      scl_t <= 1'b1;
    end else begin
      case(state)
        IDLE: begin
          scl_t <= 1'b1;
        end
        START: begin
          scl_t <= 1'b0;
        end
        WRITE: begin
          scl_t <= 1'b0;
        end
        READ: begin
          scl_t <= 1'b1;
        end
      endcase
    end
  end

  always @(posedge clk) begin
    if (rst) begin
      ack_counter <= 0;
    end else begin
      if (scl_i && !scl_o) begin
        #STRETCH;
        ack_counter <= ack_counter + 1;
      end
    end
  end

endmodule

module top_module (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    input [2:0] OP,
    output [3:0] Sum,
    output Cout,
    output reg [3:0] Y
);

wire [3:0] ripple_carry_adder_out;
wire [3:0] alu_out;

ripple_carry_adder RCA(
    .A(A),
    .B(B),
    .Cin(Cin),
    .Sum(ripple_carry_adder_out),
    .Cout(Cout)
);

alu ALU(
    .A(A),
    .B(B),
    .Cin(Cout),
    .OP(OP),
    .Y(alu_out)
);

assign Sum = alu_out;
assign Y = ripple_carry_adder_out | alu_out;

endmodule

module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout
);

wire [3:0] carry;
assign carry[0] = Cin;

genvar i;
generate
    for (i = 0; i < 4; i = i + 1) begin : full_adder_loop
        full_adder FA(
            .A(A[i]),
            .B(B[i]),
            .Cin(carry[i]),
            .Sum(Sum[i]),
            .Cout(carry[i+1])
        );
    end
endgenerate

assign Cout = carry[4];

endmodule

module full_adder (
    input A,
    input B,
    input Cin,
    output Sum,
    output Cout
);

assign Sum = A ^ B ^ Cin;
assign Cout = (A & B) | (Cin & (A ^ B));

endmodule

module alu (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    input [2:0] OP,
    output reg [3:0] Y
);

always @(*) begin
    case (OP)
        3'b000: Y = A & B;
        3'b001: Y = A | B;
        3'b010: Y = A + B + Cin;
        3'b110: Y = A - B - Cin;
        default: Y = 4'b0;
    endcase
end

endmodule

