module shift_and(
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] data_in,   // 8-bit input for the shift register
    input [7:0] data_and,  // 8-bit input for the AND operation
    input select,     // Select input to choose between shift register and AND module
    input load,       // Parallel load input for the shift register
    output [3:0] and_result  // 4-bit output from the active module
);

    reg [7:0] shift_reg;
    wire [3:0] and_out;

    // Shift register with parallel load
    always @(posedge clk) begin
        if (reset) begin
            shift_reg <= 8'b0;
        end else if (load) begin
            shift_reg <= data_in;
        end else begin
            shift_reg <= {shift_reg[6:0], 1'b0};
        end
    end

    // AND module
    and_module and_inst(
        .a(shift_reg),
        .b(data_and),
        .out(and_out)
    );

    // Control logic to select active module
    always @(*) begin
        if (select) begin
            and_result = and_out;
        end else begin
            and_result = shift_reg[3:0];
        end
    end

endmodule

// AND module
module and_module(
    input [7:0] a,
    input [7:0] b,
    output [3:0] out
);

    assign out = a[3:0] & b[3:0];

endmodule

module cycloneive_scale_cntr   ( clk,
                                reset,
                                cout,
                                high,
                                low,
                                initial_value,
                                mode,
                                ph_tap);

    // INPUT PORTS
    input clk;
    input reset;
    input [31:0] high;
    input [31:0] low;
    input [31:0] initial_value;
    input [8*6:1] mode;
    input [31:0] ph_tap;

    // OUTPUT PORTS
    output cout;

    // INTERNAL VARIABLES AND NETS
    reg tmp_cout;
    reg first_rising_edge;
    reg clk_last_value;
    reg init;
    integer count;
    integer output_shift_count;
    reg cout_tmp;

    initial
    begin
        count = 1;
        first_rising_edge = 0;
        tmp_cout = 0;
        output_shift_count = 1;
    end

    always @(clk or reset)
    begin
        if (init !== 1'b1)
        begin
            clk_last_value = 0;
            init = 1'b1;
        end
        if (reset)
        begin
            count = 1;
            output_shift_count = 1;
            tmp_cout = 0;
            first_rising_edge = 0;
        end
        else if (clk_last_value !== clk)
        begin
            if (mode == "   off")
                tmp_cout = 0;
            else if (mode == "bypass")
            begin
                tmp_cout = clk;
                first_rising_edge = 1;
            end
            else if (first_rising_edge == 0)
            begin
                if (clk == 1)
                begin
                    if (output_shift_count == initial_value)
                    begin
                        tmp_cout = clk;
                        first_rising_edge = 1;
                    end
                    else
                        output_shift_count = output_shift_count + 1;
                end
            end
            else if (output_shift_count < initial_value)
            begin
                if (clk == 1)
                    output_shift_count = output_shift_count + 1;
            end
            else
            begin
                count = count + 1;
                if (mode == "  even" && (count == (high*2) + 1))
                    tmp_cout = 0;
                else if (mode == "   odd" && (count == (high*2)))
                    tmp_cout = 0;
                else if (count == (high + low)*2 + 1)
                begin
                    tmp_cout = 1;
                    count = 1;        // reset count
                end
            end
        end
        clk_last_value = clk;
        cout_tmp <= tmp_cout;
    end

    and (cout, cout_tmp, 1'b1);

endmodule

module traffic_light_controller (
    clk,
    reset_n,
    pedestrian_request,
    car_request,
    timer,
    green_light,
    yellow_light,
    red_light,
    pedestrian_walk,
    pedestrian_wait
);

input clk;
input reset_n;
input pedestrian_request;
input car_request;
input [15:0] timer;
output reg green_light;
output reg yellow_light;
output reg red_light;
output reg pedestrian_walk;
output reg pedestrian_wait;

reg [3:0] state;
reg [3:0] next_state;
reg [3:0] pedestrian_state;
reg [3:0] pedestrian_next_state;
reg [4:0] timer_count;

parameter GREEN_TIME = 20;
parameter YELLOW_TIME = 5;
parameter RED_TIME = 20;
parameter PEDESTRIAN_RED_TIME = 10;
parameter PEDESTRIAN_WAIT_TIME = 5;
parameter CAR_GREEN_TIME = 10;
parameter CAR_RED_TIME = 10;

assign green_light = (state == 0) || (state == 3);
assign yellow_light = (state == 1) || (state == 2);
assign red_light = (state == 4) || (state == 5);

always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
        state <= 0;
        next_state <= 0;
        pedestrian_state <= 0;
        pedestrian_next_state <= 0;
        timer_count <= 0;
        green_light <= 1;
        yellow_light <= 0;
        red_light <= 0;
        pedestrian_walk <= 0;
        pedestrian_wait <= 0;
    end
    else begin
        state <= next_state;
        pedestrian_state <= pedestrian_next_state;
        if (timer_count == 0) begin
            case (state)
                0: next_state = 1;
                1: next_state = 2;
                2: next_state = 4;
                3: next_state = 0;
                4: next_state = 5;
                5: next_state = 0;
            endcase
            case (pedestrian_state)
                0: pedestrian_next_state = 0;
                1: pedestrian_next_state = 2;
                2: pedestrian_next_state = 3;
                3: pedestrian_next_state = 0;
            endcase
            timer_count <= 1;
        end
        else begin
            timer_count <= timer_count + 1;
        end
    end
end

always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
        pedestrian_walk <= 0;
        pedestrian_wait <= 0;
    end
    else begin
        case (pedestrian_state)
            0: begin
                pedestrian_walk <= 0;
                pedestrian_wait <= 0;
            end
            1: begin
                pedestrian_walk <= 0;
                pedestrian_wait <= 1;
            end
            2: begin
                pedestrian_walk <= 1;
                pedestrian_wait <= 0;
            end
            3: begin
                pedestrian_walk <= 0;
                pedestrian_wait <= 0;
            end
        endcase
    end
end

always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
        green_light <= 1;
        yellow_light <= 0;
        red_light <= 0;
    end
    else begin
        case (state)
            0: begin
                green_light <= 1;
                yellow_light <= 0;
                red_light <= 0;
            end
            1: begin
                green_light <= 0;
                yellow_light <= 1;
                red_light <= 0;
            end
            2: begin
                green_light <= 0;
                yellow_light <= 1;
                red_light <= 0;
            end
            3: begin
                green_light <= 1;
                yellow_light <= 0;
                red_light <= 0;
            end
            4: begin
                green_light <= 0;
                yellow_light <= 0;
                red_light <= 1;
            end
            5: begin
                green_light <= 0;
                yellow_light <= 0;
                red_light <= 1;
            end
        endcase
    end
end

always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
        next_state <= 0;
    end
    else begin
        if (pedestrian_request) begin
            next_state <= 1;
            pedestrian_next_state <= 1;
            timer_count <= 0;
        end
        else if (car_request) begin
            next_state <= 3;
            timer_count <= 0;
        end
        else begin
            next_state <= next_state;
        end
    end
end

always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
        timer_count <= 0;
    end
    else begin
        if (car_request) begin
            if (state == 0) begin
                timer_count <= CAR_GREEN_TIME;
            end
            else if (state == 1) begin
                timer_count <= CAR_YELLOW_TIME;
            end
            else if (state == 2) begin
                timer_count <= CAR_YELLOW_TIME;
            end
            else if (state == 4) begin
                timer_count <= CAR_RED_TIME;
            end
            else if (state == 5) begin
                timer_count <= CAR_RED_TIME;
            end
        end
        else begin
            if (state == 0) begin
                timer_count <= GREEN_TIME;
            end
            else if (state == 1) begin
                timer_count <= YELLOW_TIME;
            end
            else if (state == 2) begin
                timer_count <= YELLOW_TIME;
            end
            else if (state == 4) begin
                timer_count <= RED_TIME;
            end
            else if (state == 5) begin
                timer_count <= RED_TIME;
            end
        end
    end
end

endmodule

module control_interface(
    input CLK,
    input RESET_N,
    input [2:0] CMD,
    input [ASIZE-1:0] ADDR,
    input REF_ACK,
    input INIT_ACK,
    input CM_ACK,
    output NOP,
    output READA,
    output WRITEA,
    output REFRESH,
    output PRECHARGE,
    output LOAD_MODE,
    output [ASIZE-1:0] SADDR,
    output REF_REQ,
    output INIT_REQ,
    output CMD_ACK
);

// Define constants
parameter REF_PER = 8192; // Refresh period
parameter INIT_PER = 1000; // Initial period

// Define internal signals
reg NOP, READA, WRITEA, REFRESH, PRECHARGE, LOAD_MODE;
reg [ASIZE-1:0] SADDR;
reg REF_REQ, INIT_REQ, CMD_ACK;
reg [15:0] timer, init_timer;

// Decode command and register address
always @(posedge CLK or negedge RESET_N) begin
    if (RESET_N == 0) begin
        NOP <= 0;
        READA <= 0;
        WRITEA <= 0;
        SADDR <= 0;
    end else begin
        SADDR <= ADDR;
        NOP <= (CMD == 3'b000);
        READA <= (CMD == 3'b001);
        WRITEA <= (CMD == 3'b010);
    end
end

// Generate CMD_ACK
always @(posedge CLK or negedge RESET_N) begin
    if (RESET_N == 0) begin
        CMD_ACK <= 0;
    end else if ((CM_ACK == 1) & (CMD_ACK == 0)) begin
        CMD_ACK <= 1;
    end else begin
        CMD_ACK <= 0;
    end
end

// Generate refresh request
always @(posedge CLK or negedge RESET_N) begin
    if (RESET_N == 0) begin
        timer <= 0;
        REF_REQ <= 0;
    end else begin
        if (REF_ACK == 1) begin
            timer <= REF_PER;
            REF_REQ <= 0;
        end else if (INIT_REQ == 1) begin
            timer <= REF_PER + 200;
            REF_REQ <= 0;
        end else begin
            timer <= timer - 1'b1;
            if (timer == 0) begin
                REF_REQ <= 1;
            end
        end
    end
end

// Generate initial request
always @(posedge CLK or negedge RESET_N) begin
    if (RESET_N == 0) begin
        init_timer <= 0;
        REFRESH <= 0;
        PRECHARGE <= 0;
        LOAD_MODE <= 0;
        INIT_REQ <= 0;
    end else begin
        if (init_timer < INIT_PER + 201) begin
            init_timer <= init_timer + 1;
        end
        if (init_timer < INIT_PER) begin
            REFRESH <= 0;
            PRECHARGE <= 0;
            LOAD_MODE <= 0;
            INIT_REQ <= 1;
        end else if (init_timer == INIT_PER + 20) begin
            REFRESH <= 0;
            PRECHARGE <= 1;
            LOAD_MODE <= 0;
            INIT_REQ <= 0;
        end else if ((init_timer == INIT_PER + 40) ||
                    (init_timer == INIT_PER + 60) ||
                    (init_timer == INIT_PER + 80) ||
                    (init_timer == INIT_PER + 100) ||
                    (init_timer == INIT_PER + 120) ||
                    (init_timer == INIT_PER + 140) ||
                    (init_timer == INIT_PER + 160) ||
                    (init_timer == INIT_PER + 180)) begin
            REFRESH <= 1;
            PRECHARGE <= 0;
            LOAD_MODE <= 0;
            INIT_REQ <= 0;
        end else if (init_timer == INIT_PER + 200) begin
            REFRESH <= 0;
            PRECHARGE <= 0;
            LOAD_MODE <= 1;
            INIT_REQ <= 0;
        end else begin
            REFRESH <= 0;
            PRECHARGE <= 0;
            LOAD_MODE <= 0;
            INIT_REQ <= 0;
        end
    end
end

endmodule

module nios_system_sram_addr (
                               // inputs:
                                address,
                                chipselect,
