module karnaugh_map(
  input wire A, B, C, D,
  output reg F
);

  always @*
  begin
    case ({A,B,C,D})
      4'b0000: F = 1;
      4'b0001: F = 0;
      4'b0011: F = 1;
      4'b0010: F = 1;
      4'b0110: F = 1;
      4'b0101: F = 0;
      4'b0100: F = 1;
      4'b1100: F = 0;
      4'b1110: F = 1;
      4'b1010: F = 0;
      4'b1001: F = 1;
      4'b1000: F = 0;
      default: F = 0;
    endcase
  end

endmodule

module edge_detector (
  input in,
  output rising,
  output falling
);

  reg prev_in;

  always @(posedge in or negedge in) begin
    if (in > prev_in) begin
      rising <= 1;
      falling <= 0;
    end else if (in < prev_in) begin
      rising <= 0;
      falling <= 1;
    end else begin
      rising <= 0;
      falling <= 0;
    end
    prev_in <= in;
  end

endmodule

module comparator(
    input [1:0] A,
    input [1:0] B,
    output reg Z
);

    always @ (*) begin
        if(A[1] > B[1]) begin
            Z = 1;
        end else if(A[1] < B[1]) begin
            Z = -1;
        end else if(A[0] > B[0]) begin
            Z = 1;
        end else if(A[0] < B[0]) begin
            Z = -1;
        end else begin
            Z = 0;
        end
    end

endmodule

module mux_multiply (
    input [3:0] in_0,
    input [3:0] in_1,
    input [1:0] sel,
    output [7:0] out
);

    wire [3:0] selected_input;
    wire [7:0] product;

    // 2-to-1 multiplexer
    mux2to1 mux (
        .in_0(in_0),
        .in_1(in_1),
        .sel(sel),
        .out(selected_input)
    );

    // Arithmetic module for multiplication
    multiplier mult (
        .in_0(selected_input),
        .in_1(selected_input),
        .out(product)
    );

    assign out = product;

endmodule

module mux2to1 (
    input [3:0] in_0,
    input [3:0] in_1,
    input sel,
    output [3:0] out
);

    assign out = (sel == 1'b0) ? in_0 : in_1;

endmodule

module multiplier (
    input [3:0] in_0,
    input [3:0] in_1,
    output [7:0] out
);

    assign out = in_0 * in_1;

endmodule

module bidir_switch_block(
    input [wire_width*wire_width*12-1:0] select,
    inout [wire_width-1:0] left, 
    inout [wire_width-1:0] right, 
    inout [wire_width-1:0] bottom,
    inout [wire_width-1:0] top
    );

    parameter wire_width = 3;

    wire lr[wire_width:0][wire_width:0];
    wire tb[wire_width:0][wire_width:0];

    genvar x, y;
    generate
        for(y = 0; y <= wire_width; y = y + 1) begin
            for (x = 0; x <= wire_width; x = x + 1) begin
                localparam s_base = (x*12)+(y*wire_width*12);
                bidir_switch bs(
                    .select(select[s_base+11:s_base]), 
                    .left( x==0 ? left[y] : lr[y][x-1] ),
                    .right( x == wire_width ? right[y] : lr[y][x] ),
                    .top( y == wire_width ? top[x] : tb[y][x] ),
                    .bottom( y == 0 ? bottom[x] : tb[y-1][x] )
                );
            end
        end
    endgenerate

endmodule

module water_level_controller(
    input wire clk,
    input wire water_in,
    input wire water_out,
    output reg [2:0] water_level,
    output reg water_in_end_sign,
    output reg water_out_end_sign
);

reg [2:0] next_water_level;

always @(posedge clk) begin
    if (water_in && !water_out && water_level != 3'b100) begin
        next_water_level = water_level + 1;
    end
    else if (!water_in && water_out && water_level != 3'b000) begin
        next_water_level = water_level - 1;
    end
    else begin
        next_water_level = water_level;
    end

    if (next_water_level == 3'b100) begin
        water_in_end_sign = 1'b1;
    end
    else begin
        water_in_end_sign = 1'b0;
    end

    if (next_water_level == 3'b000) begin
        water_out_end_sign = 1'b1;
    end
    else begin
        water_out_end_sign = 1'b0;
    end

    water_level <= next_water_level;
end

endmodule

module orangeTSMC180nm__wire_R_26m_750_C_0_025f(a, vout);
  input a;
  output reg signed [31:0] vout;

  parameter R = 26e-3;
  parameter C = 0.025e-15;

  reg signed [31:0] vc;
  reg signed [31:0] ic;

  assign vc = vout;
  assign ic = a / R;

  always @ (posedge a) begin
    vc <= 0;
    vout <= 0;
  end

  always @ (posedge a or posedge vc) begin
    vc <= vc + ic * (1.0 / 50.0e-12);
    vout <= vc;
  end
endmodule

