module memory_generator
  #(parameter C_DATA_WIDTH          = 32,
    parameter C_ADDRB_WIDTH         = 10,
    parameter C_HAS_SOFTECC_OUTPUT_REGS_B= 0,
    parameter C_USE_SOFTECC         = 0,
    parameter FLOP_DELAY            = 100
  )
  (
   input                         CLK,
   input      [C_DATA_WIDTH-1:0] DIN,
   output reg [C_DATA_WIDTH-1:0] DOUT,
   input                         SBITERR_IN,
   input                         DBITERR_IN,
   output reg                    SBITERR,
   output reg                    DBITERR,
   input      [C_ADDRB_WIDTH-1:0]             RDADDRECC_IN,
   output reg [C_ADDRB_WIDTH-1:0]             RDADDRECC
);

  reg [C_DATA_WIDTH-1:0] dout_i = 0;
  reg sbiterr_i = 0;
  reg dbiterr_i = 0;
  reg [C_ADDRB_WIDTH-1:0] rdaddrecc_i = 0;

  // No output registers
  generate if (C_HAS_SOFTECC_OUTPUT_REGS_B == 0) begin : no_output_stage
    always @* begin
      DOUT = DIN;
      RDADDRECC = RDADDRECC_IN;
      SBITERR = SBITERR_IN;
      DBITERR = DBITERR_IN;
    end
  end
  endgenerate

  // With output registers
  generate if (C_HAS_SOFTECC_OUTPUT_REGS_B == 1) begin : has_output_stage
    always @(posedge CLK) begin
      dout_i <= #FLOP_DELAY DIN;
      rdaddrecc_i <= #FLOP_DELAY RDADDRECC_IN;
      sbiterr_i <= #FLOP_DELAY SBITERR_IN;
      dbiterr_i <= #FLOP_DELAY DBITERR_IN;
    end

    always @* begin
      DOUT = dout_i;
      RDADDRECC = rdaddrecc_i;
      SBITERR = sbiterr_i;
      DBITERR = dbiterr_i;
    end
  end
  endgenerate

endmodule

module LUT_4(in_3, in_2, in_1, in_0, out);

   //Truth table parameter represents the default function of the LUT.
   //The most significant bit is the output when all inputs are logic one.
   parameter Truth_table = 16'b0000000000000000; 

   input in_0, in_1, in_2, in_3;
   output reg out;
   integer selected_row;
   wire [3:0] a;

   interconnect inter0(in_0 , a[0]);
   interconnect inter1(in_1 , a[1]);
   interconnect inter2(in_2 , a[2]);
   interconnect inter3(in_3 , a[3]);

   always@(a[0], a[1], a[2], a[3])
     begin
	selected_row = {a[3], a[2], a[1], a[0]};
	out = Truth_table[selected_row];
     end

endmodule

module processor_module(
  input clk,
  input reset,
  input [1:0] MemWrite,
  input [1:0] AddrBus,
  input IsResetInterrupt,
  input State,
  input [7:0] PC,
  input [7:0] AX,
  input [7:0] SP,
  input [1:0] LoadSP,
  input [1:0] LoadT,
  input FlagCtrl,
  input [2:0] FlagsCtrl,
  input [7:0] DIN,
  input [7:0] IR,
  input irq,
  input nmi_active,
  input [7:0] NextIR,
  input NextState,
  output [7:0] dout,
  output mw,
  output mr,
  output [7:0] aout,
  output [7:0] P,
  output [7:0] T,
  output [7:0] SP,
  output JumpTaken,
  output GotInterrupt
);

// always block 1
always @(*) begin
  dout = 8'bX;
  case (MemWrite[1:0])
    'b00: dout = T;
    'b01: dout = AluR;
    'b10: dout = {P[7:6], 1'b1, !GotInterrupt, P[3:0]};
    'b11: dout = State[0] ? PC[7:0] : PC[15:8];
  endcase
  mw = MemWrite[2] && !IsResetInterrupt;
  mr = !mw;
end

// always block 2
always @(*) begin
  case (AddrBus)
    0: aout = PC;
    1: aout = AX;
    2: aout = {8'h01, SP};
    3: aout = {13'b1111_1111_1111_1, !IsNMIInterrupt, !IsResetInterrupt, ~State[0]};
  endcase 
end

// always block 3
always @(posedge clk) begin
  if (reset) begin
    State <= 0;
    IR <= 0;
    GotInterrupt <= 1;
    IsResetInterrupt <= 1;
    P <= 'h24;
    SP <= 0;
    T <= 0;
    JumpTaken <= 0;
  end else if (ce) begin
    case (LoadSP)
      0,2,3: SP <= SP + { {7{LoadSP[0]}}, LoadSP[1] };
      1: SP <= X;
    endcase 

    case (LoadT)
      2: T <= DIN;
      3: T <= AluIntR;
    endcase

    if (FlagCtrl) begin
      case(FlagsCtrl)
        0: P <= P;
        1: {P[0], P[1], P[6], P[7]} <= {CO, ZO, VO, SO};
        2: P[2] <= 1;
        3: P[6] <= 0;
        4: {P[7:6],P[3:0]} <= {DIN[7:6], DIN[3:0]};
        5: P[0] <= IR[5];
        6: P[2] <= IR[5];
        7: P[3] <= IR[5];
      endcase
    end

    case (DIN[7:5])
      0: JumpTaken <= ~P[7];
      1: JumpTaken <=  P[7];
      2: JumpTaken <= ~P[6];
      3: JumpTaken <=  P[6];
      4: JumpTaken <= ~P[0];
      5: JumpTaken <=  P[0];
      6: JumpTaken <= ~P[1];
      7: JumpTaken <=  P[1];
    endcase

    if (StateCtrl == 2'b10) begin
      GotInterrupt <= (irq & ~P[2]) | nmi_active;
      IsResetInterrupt <= 0;
    end

    IR <= NextIR;
    State <= NextState;
  end
end

endmodule

