module adder4(
    input [3:0] A,
    input [3:0] B,
    input cin,
    output [3:0] sum,
    output cout
);

  reg [3:0] tmp_sum;
  wire [3:0] tmp_carry;

  // Full adder
  always @(*)
    begin
      tmp_sum[0] = A[0] ^ B[0] ^ cin;
      tmp_carry[0] = (A[0] & B[0]) | (A[0] & cin) | (B[0] & cin);

      tmp_sum[1] = A[1] ^ B[1] ^ tmp_carry[0];
      tmp_carry[1] = (A[1] & B[1]) | (A[1] & tmp_carry[0]) | (B[1] & tmp_carry[0]);

      tmp_sum[2] = A[2] ^ B[2] ^ tmp_carry[1];
      tmp_carry[2] = (A[2] & B[2]) | (A[2] & tmp_carry[1]) | (B[2] & tmp_carry[1]);

      tmp_sum[3] = A[3] ^ B[3] ^ tmp_carry[2];
      cout = (A[3] & B[3]) | (A[3] & tmp_carry[2]) | (B[3] & tmp_carry[2]);
    end

  assign sum = tmp_sum;

