module sdio_device_stack (

  input               clk,
  input               rst,

  //FPGA Interface
  output              ddr_en,
  input               sdio_clk,
  inout               sdio_cmd,
  inout   [3:0]       sdio_data

);

//local parameters
parameter DATA_WIDTH = 4;

//registes/wires
reg          [3:0]   sdio_state;
reg                  sdio_cmd_in;
reg                  sdio_cmd_out;
reg                  sdio_cmd_dir;

reg          [3:0]   sdio_data_in;
reg          [3:0]   sdio_data_out;
reg                  sdio_data_dir;

//Phy Configuration
wire                  spi_phy;
wire                  sd1_phy;
wire                  sd4_phy;

//Phy Interface
wire                  cmd_phy_idle;
wire                  cmd_stb;
wire                  cmd_crc_good_stb;
wire          [5:0]   cmd;
wire          [31:0]  cmd_arg;

wire          [127:0] rsps;
wire          [7:0]   rsps_len;

wire                  interrupt;
wire                  read_wait;
wire                  chip_select_n;

//Function Level
wire                  func_dat_rdy;

//Submodules
sdio_device_card_cnt #(
  .NUM_FUNCS        (1                      ),/* Number of SDIO Functions available */
  .MEM_PRESENT      (0                      ),/* Not supported yet */
  .UHSII_AVAILABLE  (0                      ),/* UHS Mode Not available yet */
  .IO_OCR           (24'hFFF0               ) /* Operating condition mode (voltage range) */

) card_controller (
  .sdio_clk         (sdio_clk               ),/* Run from the SDIO Clock */
  .rst              (rst                    ),

  .func_dat_rdy     (func_dat_rdy           ),/* DATA LINK -> FUNC: Function Layer can now send data to host */

  .cmd_phy_idle     (cmd_phy_idle           ),/* PHY -> DATA LINK: Command portion of phy layer is IDLE */
  .cmd_stb          (cmd_stb                ),/* PHY -> DATA LINK: Command signal strobe */
  .cmd_crc_good_stb (cmd_crc_good_stb       ),/* PHY -> DATA LINK: CRC is good */
  .cmd              (cmd                    ),/* PHY -> DATA LINK: Command */
  .cmd_arg          (cmd_arg                ),/* PHY -> DATA LINK: Command Arg */

  .chip_select_n    (chip_select_n          ),/* Chip Select used to determine if this is a SPI flavored host */

  .rsps             (rsps                   ),/* Response Generated by this layer*/
  .rsps_len         (rsps_len               ) /* Length of response, this could be a short 40 bit or long 128 bit */
);

//asynchronous logic
assign  sdio_cmd      = sdio_cmd_dir  ? sdio_cmd_out  : sdio_cmd_in;
assign  sdio_data     = sdio_data_dir ? sdio_data_out : sdio_data_in;
assign  chip_select_n = sdio_data[3];

//synchronous logic
always @(posedge clk) begin
  if (rst) begin
    sdio_state <= 0;
    sdio_cmd_dir <= 0;
    sdio_data_dir <= 0;
  end else begin
    case (sdio_state)
      0: begin //idle state
        sdio_cmd_dir <= 1;
        sdio_data_dir <= 1;
        if (sdio_cmd == 1'b0 && sdio_data[0] == 1'b0) begin
          sdio_state <= 1;
        end
      end
      1: begin //command state
        sdio_cmd_out <= sdio_cmd;
        sdio_cmd_dir <= 0;
        if (cmd_stb) begin
          sdio_state <= 2;
        end
      end
      2: begin //response state
        sdio_cmd_dir <= 1;
        if (rsps_len > 0) begin
          sdio_state <= 3;
        end
      end
      3: begin //data state
        sdio_data_dir <= 0;
        if (func_dat_rdy) begin
          sdio_state <= 4;
        end
      end
      4: begin //read wait state
        sdio_data_dir <= 1;
        if (!read_wait) begin
          sdio_state <= 0;
        end
      end
    endcase
  end
end

endmodule

