module message_printer (
    input clk,
    input rst,
    output [7:0] tx_data,
    output reg new_tx_data,
    input tx_busy,
    input [7:0] rx_data,
    input new_rx_data
);

localparam STATE_SIZE = 2;
localparam IDLE = 2'b00,
           PRINT_MESSAGE = 2'b01,
           WAIT_FOR_TX = 2'b10;

localparam MESSAGE_LEN = 14;

reg [STATE_SIZE-1:0] state_d, state_q;

reg [3:0] addr_d, addr_q;

message_rom message_rom (
    .clk(clk),
    .addr(addr_q),
    .data(tx_data)
);

always @(*) begin
    state_d = state_q; // default values
    addr_d = addr_q;   // needed to prevent latches
    new_tx_data = 1'b0;

    case (state_q)
        IDLE: begin
            addr_d = 4'd0;
            if (new_rx_data) begin
                state_d = PRINT_MESSAGE;
            end
        end
        PRINT_MESSAGE: begin
            if (!tx_busy) begin
                new_tx_data = 1'b1;
                addr_d = addr_q + 1'b1;
                if (addr_q == MESSAGE_LEN-1) begin
                    state_d = WAIT_FOR_TX;
                end
            end
        end
        WAIT_FOR_TX: begin
            if (tx_busy == 1'b0) begin
                state_d = IDLE;
            end
        end
        default: state_d = IDLE;
    endcase
end

always @(posedge clk) begin
    if (rst) begin
        state_q <= IDLE;
    end else begin
        state_q <= state_d;
    end

    addr_q <= addr_d;
end

endmodule

module top_module (
    input clk,
