    reg d_ff;
    always @(posedge clk, negedge clk) begin
        if (select == 0) begin
            d_ff <= d;
        end
    end
    assign q = d_ff;

    // Barrel shifter module
    wire [7:0] shifted_in;
    assign shifted_in = (select == 1) ? in : q;
    assign out = {shifted_in[7], shifted_in[6], shifted_in[5], shifted_in[4], shifted_in[3], shifted_in[2], shifted_in[1], shifted_in[0]};

endmodule

module decoder (
    input A,
    input B,
    output [15:0] O
);

    // Implement 4-to-16 decoder using a case statement
    // If A and B are both 0, O0 should be high and all other outputs should be low
    // If A is 0 and B is 1, O1 should be high and all other outputs should be low
    // If A is 1 and B is 0, O2 should be high and all other outputs should be low
    // If A and B are both 1, O3 should be high and all other outputs should be low

    // Use case statement to assign output values
    // Default case is to set all outputs to 0
    always @ (A, B) begin
        case ({A, B})
            2'b00: O = 16'b0000000000000001;
            2'b01: O = 16'b0000000000000010;
            2'b10: O = 16'b0000000000000100;
            2'b11: O = 16'b0000000000001000;
            default: O = 16'b0000000000000000;
        endcase
    end

endmodule

module top_module (
    input [7:0] a,
    input [7:0] b,
    output [7:0] s,
    output overflow
);

    wire [7:0] c;
    wire [7:0] p;
    wire [7:0] g;
    wire [7:0] c_out;

    carry_lookahead_adder adder(
        .a(a),
        .b(b),
        .c_in(1'b0),
        .s(s),
        .c(c_out),
        .p(p),
        .g(g)
    );

    assign overflow = (a[7] == b[7]) && (a[7] != s[7]);

endmodule

module carry_lookahead_adder (
    input [7:0] a,
    input [7:0] b,
    input c_in,
    output [7:0] s,
    output [7:0] c,
    output [7:0] p,
    output [7:0] g
);

    wire [7:0] p0;
    wire [7:0] g0;
    wire [7:0] p1;
    wire [7:0] g1;
    wire [7:0] p2;
    wire [7:0] g2;
    wire [7:0] p3;
    wire [7:0] g3;
    wire [7:0] p4;
    wire [7:0] g4;
    wire [7:0] p5;
    wire [7:0] g5;
    wire [7:0] p6;
    wire [7:0] g6;
    wire [7:0] p7;
    wire [7:0] g7;

    assign p0 = a[0] ^ b[0];
    assign g0 = a[0] & b[0];
    assign p1 = a[1] ^ b[1] ^ g0;
    assign g1 = (a[1] & b[1]) | (g0 & (a[1] ^ b[1]));
    assign p2 = a[2] ^ b[2] ^ g1;
    assign g2 = (a[2] & b[2]) | (g1 & (a[2] ^ b[2]));
    assign p3 = a[3] ^ b[3] ^ g2;
    assign g3 = (a[3] & b[3]) | (g2 & (a[3] ^ b[3]));
    assign p4 = a[4] ^ b[4] ^ g3;
    assign g4 = (a[4] & b[4]) | (g3 & (a[4] ^ b[4]));
    assign p5 = a[5] ^ b[5] ^ g4;
    assign g5 = (a[5] & b[5]) | (g4 & (a[5] ^ b[5]));
    assign p6 = a[6] ^ b[6] ^ g5;
    assign g6 = (a[6] & b[6]) | (g5 & (a[6] ^ b[6]));
    assign p7 = a[7] ^ b[7] ^ g6;
    assign g7 = (a[7] & b[7]) | (g6 & (a[7] ^ b[7]));

    assign s = {p7, p6, p5, p4, p3, p2, p1, p0};
    assign c = {g7, g6, g5, g4, g3, g2, g1, g0};
    assign p = {p7, p6, p5, p4, p3, p2, p1, p0};
    assign g = {g7, g6, g5, g4, g3, g2, g1, g0, c_in};

endmodule

module traffic_light_controller (
  input clk,
  input reset,
  input [1:0] state,
  output reg red,
  output reg green,
  output reg yellow
);

reg [1:0] current_state;
reg [25:0] counter;

parameter RED_TIME = 25'd500000; // 5 seconds
parameter RED_YELLOW_TIME = 25'd125000; // 1.25 seconds
parameter GREEN_TIME = 25'd750000; // 7.5 seconds
parameter YELLOW_TIME = 25'd125000; // 1.25 seconds

always @(posedge clk) begin
  if (reset) begin
    current_state <= 2'b00; // start with red light
    counter <= RED_TIME;
  end else begin
    case (current_state)
      2'b00: begin // red
        if (counter == 0) begin
          current_state <= 2'b01;
          counter <= RED_YELLOW_TIME;
        end else begin
          counter <= counter - 1;
        end
      end
      2'b01: begin // red-yellow
        if (counter == 0) begin
          current_state <= 2'b10;
          counter <= GREEN_TIME;
        end else begin
          counter <= counter - 1;
        end
      end
      2'b10: begin // green
        if (counter == 0) begin
          current_state <= 2'b11;
          counter <= YELLOW_TIME;
        end else begin
          counter <= counter - 1;
        end
      end
      2'b11: begin // yellow
        if (counter == 0) begin
          current_state <= 2'b00;
          counter <= RED_TIME;
        end else begin
          counter <= counter - 1;
        end
      end
    endcase
  end
end

always @(posedge clk) begin
  case (current_state)
    2'b00: begin // red
      red <= 1;
      green <= 0;
      yellow <= 0;
    end
    2'b01: begin // red-yellow
      red <= 1;
      green <= 0;
      yellow <= 1;
    end
    2'b10: begin // green
      red <= 0;
      green <= 1;
      yellow <= 0;
    end
    2'b11: begin // yellow
      red <= 0;
      green <= 0;
      yellow <= 1;
    end
  endcase
end

endmodule

