module pll (
  input CLK_IN1,
  input COUNTER_RESET,
  output reg CLK_OUT,
  output reg LOCKED
);

  // PLL parameters
  parameter M = 13;
  parameter D = 1258291;

  // Internal signals
  reg [19:0] count;
  reg [31:0] phase_accumulator;
  reg [31:0] phase_increment;
  reg [31:0] error_accumulator;
  reg [31:0] error_increment;
  reg [1:0]  charge_pump_output;
  reg [31:0] loop_filter_output;
  reg [31:0] vco_input;
  reg [31:0] vco_output;
  reg [31:0] vco_increment;

  // Constants
  localparam PHASE_ERR_MARGIN = 100; // 100ps
  localparam ONE_NS = 1000;

  // Generate the reference clock
  reg REF_CLK;
  always @(posedge CLK_IN1) begin
    REF_CLK <= ~REF_CLK;
  end

  // Generate the phase increment
  always @(posedge REF_CLK) begin
    if (!COUNTER_RESET) begin
      phase_increment <= D;
    end
  end

  // Generate the charge pump output
  always @(posedge REF_CLK) begin
    if (!COUNTER_RESET) begin
      error_increment <= phase_increment - phase_accumulator;
      error_accumulator <= error_accumulator + error_increment;
      charge_pump_output <= $signed(error_accumulator[31]) - $signed(error_accumulator[30]);
    end
  end

  // Generate the loop filter output
  always @(posedge REF_CLK) begin
    if (!COUNTER_RESET) begin
      loop_filter_output <= loop_filter_output + charge_pump_output;
    end
  end

  // Generate the VCO input
  always @(posedge REF_CLK) begin
    if (!COUNTER_RESET) begin
      vco_input <= loop_filter_output;
    end
  end

  // Generate the VCO output
  always @(posedge REF_CLK) begin
    if (!COUNTER_RESET) begin
      vco_output <= vco_output + vco_increment;
    end
  end

  // Generate the VCO increment
  always @(posedge REF_CLK) begin
    if (!COUNTER_RESET) begin
      vco_increment <= $signed(vco_input[31]) ? -M : M;
    end
  end

  // Generate the output clock
  always @(posedge REF_CLK) begin
    if (!COUNTER_RESET) begin
      CLK_OUT <= vco_output[31];
    end
  end

  // Generate the LOCKED signal
  always @(posedge REF_CLK) begin
    if (count == 0) begin
      LOCKED <= 1;
    end else if (count == 1024) begin
      LOCKED <= 0;
    end
    count <= count + 1;
  end

  // Reset the PLL
  always @(posedge CLK_IN1) begin
    if (COUNTER_RESET) begin
      count <= 0;
      phase_accumulator <= 0;
      error_accumulator <= 0;
      charge_pump_output <= 0;
      loop_filter_output <= 0;
      vco_input <= 0;
      vco_output <= 0;
      vco_increment <= 0;
    end
  end

  // Update the phase accumulator
  always @(posedge CLK_OUT) begin
    phase_accumulator <= phase_accumulator + phase_increment;
  end

endmodule

