module ethernet_fifo(
    input phy_tx_clk,
    input s_axi_aclk,
    input Rst0,
    input E,
    input [7:0]DIA,
    output [7:0]D,
    input txfifo_empty,
    input waitFifoEmpty,
    input STATE14A,
    input fifo_tx_en,
    input axi_phy_tx_en_i_p,
    output out,
    output STATE16A,
    output [31:0]count_reg,
    output D18_out,
    output cdc_to,
    output [3:0]Q
);

localparam ADDR_WIDTH = 4;
localparam DATA_WIDTH = 8;
localparam FIFO_DEPTH = 16;

reg [DATA_WIDTH-1:0] fifo [0:FIFO_DEPTH-1];
reg [ADDR_WIDTH-1:0] head;
reg [ADDR_WIDTH-1:0] tail;
reg [ADDR_WIDTH-1:0] count;
reg [31:0] tx_count;
reg [31:0] tx_packet_count;
reg [1:0] tx_state;

wire txfifo_full = (count == FIFO_DEPTH);
wire txfifo_almost_full = (count >= (FIFO_DEPTH - 2));
wire txfifo_almost_empty = (count <= 2);
wire txfifo_not_empty = (count > 0);

wire tx_packet_done = (tx_count == 0);
wire tx_packet_start = (tx_count == 1);
wire tx_packet_middle = ((tx_count > 1) && (tx_count < tx_packet_count));
wire tx_packet_end = (tx_count == tx_packet_count);

assign Q = fifo[tail];
assign D = fifo[head];
assign txfifo_empty = (count == 0);

// State machine for transmitting packets from the FIFO
always @(posedge s_axi_aclk) begin
    if (Rst0) begin
        tx_count <= 0;
        tx_packet_count <= 0;
        tx_state <= 0;
        count <= 0;
        head <= 0;
        tail <= 0;
    end else begin
        case(tx_state)
            0: begin
                if (fifo_tx_en && txfifo_not_empty) begin
                    tx_count <= 1;
                    tx_packet_count <= fifo[head];
                    tx_state <= 1;
                    head <= head + 1;
                    count <= count - 1;
                end
            end
            1: begin
                if (tx_packet_start) begin
                    axi_phy_tx_en_i_p <= 1;
                    tx_count <= tx_count + 1;
                end
                tx_state <= 2;
            end
            2: begin
                if (tx_packet_middle) begin
                    axi_phy_tx_en_i_p <= 1;
                    tx_count <= tx_count + 1;
                end
                tx_state <= 3;
            end
            3: begin
                if (tx_packet_end) begin
                    axi_phy_tx_en_i_p <= 1;
                    tx_count <= tx_count + 1;
                end
                tx_state <= 4;
            end
            4: begin
                axi_phy_tx_en_i_p <= 0;
                tx_state <= 5;
            end
            5: begin
                if (tx_packet_done) begin
                    tx_state <= 0;
                end
            end
        endcase
    end
end

// State machine for receiving packets into the FIFO
always @(posedge phy_tx_clk) begin
    if (Rst0) begin
        out <= 0;
        STATE16A <= 0;
        count_reg <= 0;
        D18_out <= 0;
        cdc_to <= 0;
    end else begin
        if (E) begin
            if (STATE14A) begin
                out <= 1;
                if (!txfifo_full) begin
                    fifo[head] <= DIA;
                    head <= head + 1;
                    count <= count + 1;
                end
            end else begin
                out <= 0;
            end

            STATE16A <= 1;
            count_reg <= count;
            D18_out <= (count == FIFO_DEPTH);
            cdc_to <= 0;
        end else begin
            STATE16A <= 0;
            count_reg <= 0;
            D18_out <= 0;
            cdc_to <= 0;
        end
    end
end

endmodule

module glitch_filter (
  input in,
  output out
);

parameter glitch_duration = 10; // duration of glitch to be removed (in clock cycles)

reg [glitch_duration-1:0] glitch_counter; // counter to measure duration of glitch
reg out_reg; // register to store output signal

always @(posedge clk) begin
  if (in == 1'b1) begin
    if (glitch_counter < glitch_duration) begin
      glitch_counter <= glitch_counter + 1;
    end else begin
      out_reg <= 1'b1;
      glitch_counter <= 0;
    end
  end else begin
    if (glitch_counter > 0) begin
      glitch_counter <= glitch_counter - 1;
    end else begin
      out_reg <= 1'b0;
    end
  end
end

assign out = out_reg;

endmodule

module inverted_and_gate (
    X,
    A_N,
    B_N,
    C,
    D
);

    // Module ports
    output X;
    input A_N;
    input B_N;
    input C;
    input D;

    // Local signals
    wire nor_out;
    wire and_out;

    // Implementing the NOR of A_N and B_N
    nor nor_gate (nor_out, A_N, B_N);

    // Implementing the AND of C and D
    and and_gate (and_out, C, D);

    // Implementing the inverted AND of the NOR and the AND
    assign X = ~ (nor_out & and_out);

endmodule

module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

    wire C1, C2, C3;
    wire S1, S2, S3, S4;

    // First bit addition
    xor(S1, A[0], B[0]);
    and(C1, A[0], B[0]);
    xor(S[0], S1, Cin);

    // Second bit addition
    xor(S2, A[1], B[1]);
    and(C2, A[1], B[1]);
    xor(S[1], S2, C1);

    // Third bit addition
    xor(S3, A[2], B[2]);
    and(C3, A[2], B[2]);
    xor(S[2], S3, C2);

    // Fourth bit addition
    xor(S4, A[3], B[3]);
    xor(S[3], S4, C3);
    and(Cout, C3, S4);

endmodule

