module top_module (
  input clk,
  input reset,
  input [7:0] instruction,
  input [2:0] stage,
  input [4:0] rs1,
  input [4:0] rs2,
  input [4:0] rd,
  input [31:0] data1,
  input [31:0] data2,
  input enable_mult_div, // control logic module input to enable multiplication and division operations
  output reg [31:0] regfile [7:0], // register file output
  output [31:0] result // output of executed instruction
);

// Pipeline stages
reg [31:0] stage1_out;
reg [31:0] stage2_out;
reg [31:0] stage3_out;

// Register file
reg [31:0] regfile [7:0];

// Control signals
reg [1:0] alu_op;
reg write_enable;

// Multiplication and division signals
reg [31:0] mult_out;
reg [31:0] div_out;
reg [31:0] remainder;

// Stage 1: Instruction Fetch
always @(posedge clk) begin
  if (reset) begin
    stage1_out <= 0;
  end else begin
    stage1_out <= regfile[rs1];
  end
end

// Stage 2: Instruction Decode and Register Read
always @(posedge clk) begin
  if (reset) begin
    stage2_out <= 0;
  end else begin
    case (instruction[7:4])
      4'b0000: begin // ADD
        alu_op <= 2'b00;
        write_enable <= 1;
        stage2_out <= regfile[rs2];
      end
      4'b0001: begin // SUB
        alu_op <= 2'b01;
        write_enable <= 1;
        stage2_out <= regfile[rs2];
      end
      4'b0010: begin // AND
        alu_op <= 2'b10;
        write_enable <= 1;
        stage2_out <= regfile[rs2];
      end
      4'b0011: begin // OR
        alu_op <= 2'b11;
        write_enable <= 1;
        stage2_out <= regfile[rs2];
      end
      default: begin // Invalid instruction
        alu_op <= 2'b00;
        write_enable <= 0;
        stage2_out <= 0;
      end
    endcase
  end
end

// Stage 3: Execute and Write Back
always @(posedge clk) begin
  if (reset) begin
    stage3_out <= 0;
  end else begin
    if (enable_mult_div) begin // Multiplication and division operations
      case (instruction[7:4])
        4'b0100: begin // MUL
          mult_out <= stage1_out * stage2_out;
          stage3_out <= mult_out;
        end
        4'b0101: begin // DIV
          div_out <= stage1_out / stage2_out;
          remainder <= stage1_out % stage2_out;
          stage3_out <= div_out;
        end
        default: begin // Invalid instruction
          stage3_out <= 0;
        end
      endcase
    end else begin // ADD, SUB, AND, OR operations
      case (alu_op)
        2'b00: begin // ADD
          stage3_out <= stage1_out + stage2_out;
        end
        2'b01: begin // SUB
          stage3_out <= stage1_out - stage2_out;
        end
        2'b10: begin // AND
          stage3_out <= stage1_out & stage2_out;
        end
        2'b11: begin // OR
          stage3_out <= stage1_out | stage2_out;
        end
      endcase
    end

    if (write_enable) begin
      regfile[rd] <= stage3_out;
    end
  end
end

// Output result
always @(posedge clk) begin
  if (reset) begin
    result <= 0;
  end else begin
    result <= stage3_out;
  end
end

endmodule

module ST_to_MM_Adapter (
  clk,
  reset,

  enable,
  address,
  start,
  waitrequest,
  stall,
  write_data,

  fifo_data,
  fifo_empty,
  fifo_readack
);

  parameter DATA_WIDTH = 32;
  parameter BYTEENABLE_WIDTH_LOG2 = 2;
  parameter ADDRESS_WIDTH = 32;
  parameter UNALIGNED_ACCESS_ENABLE = 1;
  localparam BYTES_TO_NEXT_BOUNDARY_WIDTH = BYTEENABLE_WIDTH_LOG2 + 1;

  input clk;
  input reset;

  input enable;
  input [ADDRESS_WIDTH-1:0] address;
  input start;
  input waitrequest;
  input stall;
  output wire [DATA_WIDTH-1:0] write_data;

  input [DATA_WIDTH-1:0] fifo_data;
  input fifo_empty;
  output wire fifo_readack;


  wire [BYTES_TO_NEXT_BOUNDARY_WIDTH-1:0] bytes_to_next_boundary;
  wire [DATA_WIDTH-1:0] barrelshifter_A;
  wire [DATA_WIDTH-1:0] barrelshifter_B;
  reg [DATA_WIDTH-1:0] barrelshifter_B_d1;
  wire [DATA_WIDTH-1:0] combined_word;
  wire [BYTES_TO_NEXT_BOUNDARY_WIDTH-2:0] bytes_to_next_boundary_minus_one;
  reg [BYTES_TO_NEXT_BOUNDARY_WIDTH-2:0] bytes_to_next_boundary_minus_one_d1;
  wire [DATA_WIDTH-1:0] barrelshifter_input_A [0:((DATA_WIDTH/8)-1)];
  wire [DATA_WIDTH-1:0] barrelshifter_input_B [0:((DATA_WIDTH/8)-1)];


  always @ (posedge clk or posedge reset)
  begin
    if (reset)
    begin
      bytes_to_next_boundary_minus_one_d1 <= 0;
    end
    else if (start)
    begin
      bytes_to_next_boundary_minus_one_d1 <= bytes_to_next_boundary_minus_one;
    end
  end


  always @ (posedge clk or posedge reset)
  begin
    if (reset)
    begin
      barrelshifter_B_d1 <= 0;
    end
    else
    begin
      if (start == 1)
      begin
        barrelshifter_B_d1 <= 0;
      end
      else if (fifo_readack == 1)
      begin
        barrelshifter_B_d1 <= barrelshifter_B;
      end
    end
  end


  assign bytes_to_next_boundary = (DATA_WIDTH/8) - address[BYTEENABLE_WIDTH_LOG2-1:0];
  assign bytes_to_next_boundary_minus_one = bytes_to_next_boundary - 1;
  assign combined_word = barrelshifter_A | barrelshifter_B_d1;

  generate
  genvar input_offset;
  for(input_offset = 0; input_offset < (DATA_WIDTH/8); input_offset = input_offset + 1)
  begin:  barrel_shifter_inputs
    assign barrelshifter_input_A[input_offset] = fifo_data << (8 * ((DATA_WIDTH/8)-(input_offset+1)));
    assign barrelshifter_input_B[input_offset] = fifo_data >> (8 * (input_offset + 1));
  end
  endgenerate

  assign barrelshifter_A = barrelshifter_input_A[bytes_to_next_boundary_minus_one_d1];
  assign barrelshifter_B = barrelshifter_input_B[bytes_to_next_boundary_minus_one_d1];

  generate
  if (UNALIGNED_ACCESS_ENABLE == 1)
  begin
    assign fifo_readack = (fifo_empty == 0) & (stall == 0) & (waitrequest == 0) & (enable == 1) & (start == 0);
    assign write_data = combined_word;
  end
  else
  begin
    assign fifo_readack = (fifo_empty == 0) & (stall == 0) & (waitrequest == 0) & (enable == 1);
    assign write_data = fifo_data;
  end
  endgenerate

endmodule

