module fifo #(
    parameter MEM_STYLE = "shiftreg",
    parameter DATA_WIDTH = 8,
    parameter ADDR_WIDTH = 2,
    parameter DEPTH = 3
)(
    input clk,
    input reset,
    output if_empty_n,
    input if_read_ce,
    input if_read,
    output [DATA_WIDTH-1:0] if_dout,
    output if_full_n,
    input if_write_ce,
    input [DATA_WIDTH-1:0] if_din,
    input [ADDR_WIDTH-1:0] if_addr
);

// Internal signals
reg [ADDR_WIDTH-1:0] write_ptr, read_ptr;
reg [DATA_WIDTH-1:0] fifo_mem [(1<<ADDR_WIDTH)-1:0];
reg internal_empty_n, internal_full_n;
wire [ADDR_WIDTH-1:0] next_write_ptr, next_read_ptr;
wire [DATA_WIDTH-1:0] read_data;
wire write_enable, read_enable;

// Combinational logic for next read and write pointers
assign next_write_ptr = write_ptr + 1;
assign next_read_ptr = read_ptr + 1;
assign next_write_ptr[ADDR_WIDTH-1:0] = next_write_ptr[ADDR_WIDTH-1:0] & ((1<<ADDR_WIDTH)-1);
assign next_read_ptr[ADDR_WIDTH-1:0] = next_read_ptr[ADDR_WIDTH-1:0] & ((1<<ADDR_WIDTH)-1);

// Combinational logic for write enable
assign write_enable = if_write_ce & internal_full_n;

// Combinational logic for read enable
assign read_enable = if_read_ce & internal_empty_n;

// Combinational logic for read data
assign read_data = fifo_mem[read_ptr];

// Assign outputs
assign if_empty_n = internal_empty_n;
assign if_full_n = internal_full_n;
assign if_dout = read_data;

// Sequential logic
always @(posedge clk) begin
    if (reset) begin
        write_ptr <= 0;
        read_ptr <= 0;
        internal_empty_n <= 0;
        internal_full_n <= 1;
    end else begin
        if (write_enable) begin
            fifo_mem[write_ptr] <= if_din;
            write_ptr <= next_write_ptr;
            if (write_ptr == read_ptr) begin
                internal_full_n <= 0;
            end
            internal_empty_n <= 1;
        end
        if (read_enable) begin
            read_ptr <= next_read_ptr;
            if (read_ptr == write_ptr) begin
                internal_empty_n <= 0;
            end
            internal_full_n <= 1;
        end
    end
end

endmodule

