module random_number_gen (
  input [31:0] seed,
  output reg [7:0] rand1,
  output reg [7:0] rand2,
  output reg [7:0] rand3
);

  reg [31:0] lfsr; // shift register
  reg [7:0] bit; // current bit
  reg [7:0] count; // counter for number of random numbers generated

  always @ (posedge clk) begin
    // generate next bit using feedback function
    bit = lfsr[0] ^ lfsr[1] ^ lfsr[3] ^ lfsr[4];
    // shift register to the left and insert new bit
    lfsr = {lfsr[30:0], bit};
    // increment counter
    count = count + 1;
    // output random number when counter reaches threshold
    if (count == 1) begin
      rand1 = lfsr[7:0];
    end else if (count == 2) begin
      rand2 = lfsr[7:0];
    end else if (count == 3) begin
      rand3 = lfsr[7:0];
    end
  end

  // initialize shift register with seed value
  initial begin
    lfsr = seed;
    count = 0;
  end

endmodule

