    if (reset_n == 0) begin
      internal_counter <= 17'h1869F;
    end else if (counter_is_running || force_reload) begin
      if (counter_is_zero || force_reload) begin
        internal_counter <= counter_load_value;
      end else begin
        internal_counter <= internal_counter - 1;
      end
    end
  end

  assign counter_is_zero = internal_counter == 0;
  assign counter_load_value = 17'h1869F;

  always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
      force_reload <= 0;
    end else if (clk_en) begin
      force_reload <= period_h_wr_strobe || period_l_wr_strobe;
    end
  end

  assign do_start_counter = 1;
  assign do_stop_counter = 0;

  always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
      counter_is_running <= 1'b0;
    end else if (clk_en) begin
      if (do_start_counter) begin
        counter_is_running <= -1;
      end else if (do_stop_counter) begin
        counter_is_running <= 0;
      end
    end
  end

  always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
      delayed_unxcounter_is_zeroxx0 <= 0;
    end else if (clk_en) begin
      delayed_unxcounter_is_zeroxx0 <= counter_is_zero;
