module full_adder (
    input a,
    input b,
    input cin,
    output reg sum,
    output reg cout
);

    // Transmission gates for XOR and AND gates
    assign #1 x = a ^ b;
    assign #1 y = a & b;
    assign #1 z = x & cin;

    // Inverters for NOT gates
    assign #1 not_x = ~x;
    assign #1 not_y = ~y;
    assign #1 not_z = ~z;

    // Transmission gates for final sum and carry-out
    assign #1 sum = not_z & not_y & not_x | z & not_y & x | z & y & not_x | not_z & y & x;
    assign #1 cout = z | y & cin | z & cin | x & cin;

endmodule

