    // Local signals
    wire buf_out;

    // Use buf module to create delay
    buf buf0 (.O(buf_out), .I(A));
    buf buf1 (.O(X), .I(buf_out));

    // Delay input A by delay cycles
    generate
        genvar i;
        for (i = 0; i < 256; i = i + 1) begin : buf_generate
