module alupipe(S, Cin, clk, abus, bbus, dbus);
    input [2:0] S;
    input Cin;
    input clk;
    input [31:0] abus;
    input [31:0] bbus;
    output [31:0] dbus;
    output Cout;
    reg Cout;

    always @(posedge clk) begin
        case(S)
            3'b000: begin
                dbus <= abus & bbus;
            end
            3'b001: begin
                dbus <= abus | bbus;
            end
            3'b010: begin
                dbus <= abus ^ bbus;
            end
            3'b011: begin
                dbus <= ~(abus & bbus);
            end
            3'b100: begin
                dbus <= ~(abus | bbus);
            end
            3'b101: begin
                dbus <= abus << 1;
            end
            3'b110: begin
                dbus <= abus >> 1;
            end
            3'b111: begin
                dbus <= abus;
            end
        endcase
    end

    always @(posedge clk) begin
        if(Cin == 1) begin
            Cout <= (dbus[0] & abus[0]) | (dbus[0] & bbus[0]) | (abus[0] & bbus[0]);
        end
        else begin
            Cout <= (dbus[0] & abus[0]) | (dbus[0] & bbus[0]) | (abus[0] & bbus[0]) | (dbus[0] & Cout) | (abus[0] & Cout) | (bbus[0] & Cout);
        end
    end

    always @(posedge clk) begin
        if(Cin == 1) begin
            abus <= dbus + abus + 1'b0;
        end
        else begin
            abus <= dbus + abus + Cout;
        end
    end
endmodule

