module I2C_state_machine (
  input SCL,
  inout SDA,
  input reset,
  output reg [7:0] data,
  output reg ack
);

  // Define the states of the state machine
  parameter IDLE = 2'b00;
  parameter START_CONDITION = 2'b01;
  parameter DATA_TRANSFER = 2'b10;
  parameter STOP_CONDITION = 2'b11;

  // Define the device address and READ/WRITE bit
  parameter DEVICE_ADDRESS = 8'h50; // Example device address
  parameter READ_BIT = 1'b1; // Example READ bit

  // Define the data transfer direction
  reg is_read;

  // Define the state and next_state variables
  reg [1:0] state, next_state;

  // Define the data and ack variables
  reg [7:0] data_reg;
  reg ack_reg;

  // Define the counter for data transfer
  reg [2:0] data_counter;

  // Define the edge detection variables
  reg SCL_prev, SDA_prev;

  // Initialize the state machine
  always @ (posedge reset) begin
    state <= IDLE;
    next_state <= IDLE;
    data_reg <= 8'h00;
    ack_reg <= 1'b0;
    data_counter <= 3'b000;
    is_read <= 1'b0;
    SCL_prev <= 1'b1;
    SDA_prev <= 1'b1;
  end

  // Define the state machine transitions and behavior
  always @ (posedge SCL) begin
    // Edge detection for SCL and SDA
    if (SCL_prev && !SCL) begin
      // Start condition detected
      if (SDA_prev && !SDA) begin
        next_state <= START_CONDITION;
        data_counter <= 3'b000;
        is_read <= 1'b0;
      end
      // Stop condition detected
      else if (!SDA_prev && SDA) begin
        next_state <= STOP_CONDITION;
        data_counter <= 3'b000;
      end
      // Data transfer
      else begin
        case (state)
          DATA_TRANSFER: begin
            if (data_counter == 3'b000) begin
              // Send or receive device address and READ/WRITE bit
              data_reg <= {DEVICE_ADDRESS, READ_BIT};
              is_read <= (SDA == 1'b1);
              data_counter <= 3'b001;
            end
            else if (data_counter == 3'b001) begin
              // Send or receive data
              if (is_read) begin
                // Receive data
                data_reg <= {data_reg[6:0], SDA};
              end
              else begin
                // Send data
                SDA <= data_reg[7];
              end
              data_counter <= 3'b010;
            end
            else if (data_counter == 3'b010) begin
              // Wait for acknowledge signal
              ack_reg <= !SDA;
              data_counter <= 3'b011;
            end
            else if (data_counter == 3'b011) begin
              // Check acknowledge signal
              if (SDA) begin
                // No acknowledge received, transition to stop condition
                next_state <= STOP_CONDITION;
              end
              else begin
                // Acknowledge received, continue data transfer
                data_reg <= {data_reg[6:0], SDA};
                data_counter <= 3'b001;
              end
            end
          end
          default: begin
            // Invalid state, transition to idle state
            next_state <= IDLE;
          end
        endcase
      end
    end

    // Update the state and output signals
    state <= next_state;
    data <= data_reg;
    ack <= ack_reg;

    // Update the edge detection variables
    SCL_prev <= SCL;
    SDA_prev <= SDA;

    // Output behavior for SDA
    case (state)
      START_CONDITION: begin
        SDA <= 1'b0;
      end
      DATA_TRANSFER: begin
        if (data_counter == 3'b001) begin
          SDA <= is_read ? 1'b1 : data_reg[7];
        end
        else begin
          SDA <= SDA;
        end
      end
      STOP_CONDITION: begin
        SDA <= 1'b1;
      end
      default: begin
        SDA <= SDA;
      end
    endcase

  end

endmodule

