    input load, // Input to load a value into the counter
    input [3:0] load_data, // Input data to be loaded into the counter
    input [7:0] instruction, // Input instruction for the pipeline
    output reg [31:0] regfile [15:0], // Output register file from the pipeline
    output reg [3:0] count, // Output count from the counter
    output reg [31:0] result // Output result from the functional module
);

// Up/Down Counter
always @(posedge clk or negedge reset) begin
    if (!reset) begin
        count <= 4'b0;
    end else if (load) begin
        count <= load_data;
    end else begin
        count <= up_down ? count + 4'b1 : count - 4'b1;
    end
end

// 3-stage Pipeline
reg [31:0] if_reg, id_reg, ex_reg;
reg [7:0] opcode;
reg [4:0] rd, rs, rt;
reg [31:0] rs_data, rt_data;

// Fetch stage
always @(posedge clk or negedge reset) begin
    if (!reset) begin
        if_reg <= 32'b0;
    end else begin
        if_reg <= instruction;
    end
end

// Decode stage
always @(posedge clk or negedge reset) begin
    if (!reset) begin
        id_reg <= 32'b0;
    end else begin
        id_reg <= if_reg;
        opcode <= id_reg[7:0];
        rd <= id_reg[12:8];
        rs <= id_reg[17:13];
        rt <= id_reg[22:18];
        rs_data <= regfile[rs];
        rt_data <= regfile[rt];
    end
end

// Execute stage
always @(posedge clk or negedge reset) begin
    if (!reset) begin
        ex_reg <= 32'b0;
    end else begin
        ex_reg <= id_reg;
        case (opcode)
            8'b0000_0001: regfile[rd] <= rs_data + rt_data;
            8'b0000_0010: regfile[rd] <= rs_data - rt_data;
            8'b0000_0011: regfile[rd] <= rs_data & rt_data;
            8'b0000_0100: regfile[rd] <= ~(rs_data & rt_data);
            default: regfile[rd] <= regfile[rd];
        endcase
    end
end

// Additional Functional Module
always @(posedge clk or negedge reset) begin
    if (!reset) begin
        result <= 32'b0;
    end else begin
        result <= count + regfile[rd];
    end
end

endmodule

