module fifo (
  input clock,
  input reset,
  input enable,
  input enq,
  input [width-1:0] enq_data,
  input deq,
  input [preload_data_width-1:0] preload,
  output [width-1:0] deq_data,
  output full,
  output empty
);

  parameter depth = 2;
  parameter width = 1;
  parameter preload_count = 0;
  parameter enq_latency = 0;
  parameter deq_latency = 0;
  parameter value_check = 1;
  parameter pass_thru = 0;
  parameter registered = 0;

  parameter preload_data_width = (preload_count == 0) ? width : (preload_count*width);

  // Internal signals
  reg [width-1:0] fifo [depth-1:0];
  reg [width-1:0] preload_fifo [preload_count-1:0];
  reg [depth-1:0] full_count;
  reg [depth-1:0] empty_count;
  reg enq_req;
  reg deq_req;
  reg [width-1:0] deq_data_reg;
  reg [depth-1:0] full_count_reg;
  reg [depth-1:0] empty_count_reg;

  // Assign internal signals
  assign full = (full_count == depth);
  assign empty = (empty_count == depth);

  // Preload data
  integer i;
  always @(posedge reset) begin
    if (preload_count > 0) begin
      for (i = 0; i < preload_count; i = i + 1) begin
        preload_fifo[i] <= preload[i*width +: width];
      end
    end
  end

  // Enqueue operation
  always @(posedge clock) begin
    if (reset) begin
      full_count_reg <= 0;
      empty_count_reg <= depth;
      deq_data_reg <= 0;
      if (preload_count > 0) begin
        for (i = 0; i < preload_count; i = i + 1) begin
          fifo[i] <= preload_fifo[i];
        end
        full_count_reg <= preload_count;
        empty_count_reg <= depth - preload_count;
      end
    end
    else if (enable) begin
      if (enq && !full) begin
        enq_req <= 1;
        full_count_reg <= full_count + 1;
        empty_count_reg <= empty_count;
        fifo[full_count] <= enq_data;
      end
      else begin
        enq_req <= 0;
        full_count_reg <= full_count;
        empty_count_reg <= empty_count;
      end
      if (pass_thru && empty) begin
        enq_req <= enq;
      end
    end
  end

  // Dequeue operation
  always @(posedge clock) begin
    if (reset) begin
      deq_data_reg <= 0;
    end
    else if (enable) begin
      if (deq && !empty) begin
        deq_req <= 1;
        full_count_reg <= full_count;
        empty_count_reg <= empty_count - 1;
        deq_data_reg <= fifo[empty_count];
      end
      else begin
        deq_req <= 0;
        full_count_reg <= full_count;
        empty_count_reg <= empty_count;
      end
    end
  end

  // Register signals if necessary
  always @(posedge clock) begin
    if (registered) begin
      deq_req <= deq_req;
      enq_req <= enq_req;
      deq_data_reg <= deq_data_reg;
      full_count <= full_count_reg;
      empty_count <= empty_count_reg;
    end
    else begin
      deq_req <= deq;
      enq_req <= enq;
      deq_data_reg <= deq_data_reg;
      full_count <= full_count_reg;
      empty_count <= empty_count_reg;
    end
  end

  // Check for value mismatch
  always @(posedge clock) begin
    if (reset) begin
      deq_data_reg <= 0;
    end
    else if (enable && deq_req && enq_req && value_check && (deq_data_reg != enq_data)) begin
      $error("Value mismatch in FIFO");
    end
  end

  // Assign output signals
  assign deq_data = deq_data_reg;
endmodule

module port_address_reg
    (
    input  wire clk,                   // System Clock
    input  wire reset_b,               // Active high, asyn reset
    input  wire         mem_en,        // Memory enable
    input  wire         mem_rd_wr,     // Memory read/write
    input  wire [01:00] mem_addr,      // Memory address
    input  wire [07:00] mem_wdata,     // Memory data
    output reg  [07:00] mem_rdata,     // Memory data
    output reg  [07:00] address_port_0,// Port 0 address
    output reg  [07:00] address_port_1,// Port 1 address
    output reg  [07:00] address_port_2,// Port 2 address
    output reg  [07:00] address_port_3 // Port 3 address
    );

    always@*
        case(mem_addr)
            2'd0: mem_rdata <= address_port_0;
            2'd1: mem_rdata <= address_port_1;
            2'd2: mem_rdata <= address_port_2;
            2'd3: mem_rdata <= address_port_3;
        endcase

    always @(posedge clk or negedge reset_b) begin
            if (~reset_b) begin
                    address_port_0 <= 8'h00;
                    address_port_1 <= 8'h01;
                    address_port_2 <= 8'h02;
                    address_port_3 <= 8'h03;
                end
            else if (mem_en && mem_rd_wr) begin
                    case (mem_addr)
                        2'b00: address_port_0 <= mem_wdata;
                        2'b01: address_port_1 <= mem_wdata;
                        2'b10: address_port_2 <= mem_wdata;
                        2'b11: address_port_3 <= mem_wdata;
                    endcase
                end
        end
endmodule

module booth_multiplier (
    input clk,
    input reset,
    input [3:0] A,
    input [3:0] B,
    output [7:0] result
);

reg [3:0] multiplicand_reg;
reg [2:0] multiplier_reg;
reg [7:0] product_reg;

wire [3:0] A_neg;
wire [3:0] B_neg;
wire [7:0] product_neg;

assign A_neg = (~A) + 1;
assign B_neg = (~B) + 1;
assign product_neg = (~product_reg) + 1;

always @(posedge clk) begin
    if (reset) begin
        multiplicand_reg <= 4'b0;
        multiplier_reg <= 3'b0;
        product_reg <= 8'b0;
    end else begin
        multiplicand_reg <= A;
        multiplier_reg <= {B, 1'b0};
        product_reg <= 8'b0;
    end
end

always @(posedge clk) begin
    if (reset) begin
        product_reg <= 8'b0;
    end else begin
        case (multiplier_reg[1:0])
            2'b01: begin
                product_reg <= product_reg + multiplicand_reg;
            end
            2'b10: begin
                product_reg <= product_reg + A_neg;
            end
            2'b11: begin
                product_reg <= product_reg + B_neg;
            end
            default: begin
                // do nothing
            end
        endcase
    end
end

assign result = (product_reg[7] == 1) ? product_neg : product_reg;

endmodule

