    input signed [3:0] a, // 4-bit signed input for multiplier
    input signed [3:0] b, // 4-bit signed input for multiplier
    output reg signed [7:0] out // 8-bit signed output of functional module
);

    // 2-to-4 decoder
    wire [3:0] decoder_out;
    assign decoder_out = (in == 2'b00) ? 4'b0001 :
                         (in == 2'b01) ? 4'b0010 :
                         (in == 2'b10) ? 4'b0100 :
                                         4'b1000 ;

    // 4-bit Booth's algorithm multiplier
    wire signed [7:0] product;
    booth_multiplier multiplier(.a(a), .b(b), .product(product));

    // Functional module
    always @* begin
        case(decoder_out)
            4'b0001: out = product[7:0]; // output of first decoder output
            4'b0010: out = 8'sd0; // output of second decoder output
            4'b0100: out = 8'sd0; // output of third decoder output
            4'b1000: out = product[7:0]; // output of fourth decoder output
        endcase
    end

endmodule

// 4-bit Booth's algorithm multiplier module
module booth_multiplier (
    input signed [3:0] a, // 4-bit signed input
    input signed [3:0] b, // 4-bit signed input
    output reg signed [7:0] product // 8-bit signed output
);

    reg signed [7:0] a_extended;
    reg signed [7:0] b_extended;
    reg signed [7:0] m;
    integer i;

    always @* begin
        a_extended = { {4{a[3]}}, a };
        b_extended = { {4{b[3]}}, b };
        m = {a_extended, 4'b0};
        product = 8'sd0;
        for(i = 0; i < 4; i = i + 1) begin
            if(m[0:3] == 4'b0011 || m[0:3] == 4'b1100) begin
                product = product + b_extended;
            end else if(m[0:3] == 4'b0111 || m[0:3] == 4'b1000) begin
                product = product - b_extended;
            end
            m = m >> 1;
        end
    end

endmodule

module PLL (
  input ref_clk,
  input vco_clk,
  input reset,
  output pll_clk
);

parameter f_ref = 100e6; // frequency of reference clock
parameter f_vco_min = 1e6; // minimum frequency of VCO clock
parameter f_vco_max = 1e9; // maximum frequency of VCO clock
parameter k = 10; // PLL gain constant
parameter n = 10; // PLL feedback divider value
parameter m = 2; // PLL output divider value

reg [31:0] phase_accumulator = 0;
reg [31:0] phase_difference = 0;
reg [31:0] vco_frequency = 0;
reg [31:0] vco_control_voltage = 0;

wire [31:0] feedback_clk;
wire [31:0] output_clk;

// Frequency divider for feedback loop
reg [31:0] feedback_divider = 0;
always @(posedge feedback_clk) begin
  feedback_divider <= feedback_divider + 1;
end

// Phase detector
always @(posedge ref_clk or posedge vco_clk) begin
  if (reset) begin
    phase_difference <= 0;
  end else begin
    phase_difference <= phase_difference + vco_frequency - (f_ref * n / m);
  end
end

// VCO
always @(posedge vco_clk) begin
  vco_frequency <= vco_frequency + vco_control_voltage * k;
end

// Phase accumulator
always @(posedge output_clk) begin
  phase_accumulator <= phase_accumulator + vco_frequency / m;
end

// Output clock divider
reg [31:0] output_divider = 0;
always @(posedge output_clk) begin
  output_divider <= output_divider + 1;
end

// Generate feedback clock
assign feedback_clk = (feedback_divider == 0) ? vco_clk : feedback_clk;

// Generate output clock
assign output_clk = (output_divider == 0) ? feedback_clk : output_clk;

// Generate PLL clock
assign pll_clk = (output_divider == 0) ? 1'b1 : 1'b0;

endmodule

module shiftreg_mux (
    input clk,
    input reset,
    input [255:0] in, // 256-bit input for the shift register
    output [7:0] q // 8-bit output from the functional module
);

    reg [255:0] shift_reg; // 256-bit shift register
    wire [7:0] mux_out; // 8-bit output of the multiplexer
    wire [2:0] select; // select lines for the multiplexer

    assign select = shift_reg[2:0]; // use the first 3 bits of the shift register as select lines

    // 8-to-1 multiplexer
    assign mux_out = {in[31:24] & select[0], in[63:56] & select[1], in[95:88] & select[2], in[127:120] & select[3], in[159:152] & select[4], in[191:184] & select[5], in[223:216] & select[6], in[255:248] & select[7]};

    // bitwise AND of the selected input and the current contents of the shift register
    assign q = mux_out & shift_reg[7:0];

    // bitwise OR of the multiplexer output and the shift register output
    always @(posedge clk) begin
        if (reset) begin
            shift_reg <= 256'h0;
        end else begin
            shift_reg <= {in, shift_reg[255:1]};
        end
    end

endmodule

