module top_module (
    input clk,
    input reset, // asynchronous reset
    input [3:0] a, // first 4-bit input
    input [3:0] b, // second 4-bit input
    output [7:0] product // output of the final functional module
);

    wire [7:0] partial_products [3:0]; // array of partial products
    wire [7:0] sum; // sum of all partial products

    // instantiate four instances of the partial_product module
    partial_product pp0(clk, reset, a[0], b, partial_products[0]);
    partial_product pp1(clk, reset, a[1], b, partial_products[1]);
    partial_product pp2(clk, reset, a[2], b, partial_products[2]);
    partial_product pp3(clk, reset, a[3], b, partial_products[3]);

    // instantiate the final_sum module
    final_sum fs(clk, reset, partial_products, sum);

    // assign the output to the sum
    assign product = sum;

endmodule

// sub-module for calculating the partial product of one bit
module partial_product (
    input clk,
    input reset, // asynchronous reset
    input a_bit, // one bit of the first input
    input [3:0] b, // second 4-bit input
    output [7:0] partial_product // output of the partial product module
);

    reg [7:0] pp_reg; // register for storing the partial product
    reg [3:0] b_reg; // register for storing the second input

    always @(posedge clk) begin
        if (reset) begin
            pp_reg <= 8'b0;
            b_reg <= 4'b0;
        end else begin
            // shift the second input to the left by one bit
            b_reg <= {b[2:0], 1'b0};

            // calculate the partial product of one bit
            pp_reg <= {a_bit, b_reg} << 1;
        end
    end

    assign partial_product = pp_reg;

endmodule

// sub-module for adding all partial products
module final_sum (
    input clk,
    input reset, // asynchronous reset
    input [3:0] partial_products [7:0], // array of partial products
    output [7:0] sum // output of the final sum module
);

    reg [7:0] sum_reg; // register for storing the sum

    always @(posedge clk) begin
        if (reset) begin
            sum_reg <= 8'b0;
        end else begin
            // add all partial products
            sum_reg <= partial_products[0] + partial_products[1] + partial_products[2] + partial_products[3];
        end
    end

    assign sum = sum_reg;

endmodule

