  full_adder FA1(.a(A[1]), .b(B[1]), .cin(c0), .sum(S[1]), .cout(c1));
  full_adder FA2(.a(A[2]), .b(B[2]), .cin(c1), .sum(S[2]), .cout(c2));
  full_adder FA3(.a(A[3]), .b(B[3]), .cin(c2), .sum(S[3]), .cout(1'b0));

