module top_module (
  input clk,
  input reset,
  input [7:0] instruction,
  input [2:0] stage,
  input [4:0] rs1,
  input [4:0] rs2,
  input [4:0] rd,
  input [31:0] data1,
  input [31:0] data2,
  output reg [31:0] regfile [7:0],
  input [7:0] xor_input1,
  input [7:0] xor_input2,
  output reg [7:0] xor_output
);

// XOR LUT
reg [7:0] xor_lut [3:0];
always @(*) begin
  xor_lut[0] = xor_input1 ^ xor_input2;
  xor_lut[1] = xor_input1 ^ xor_input2;
  xor_lut[2] = xor_input1 ^ xor_input2;
  xor_lut[3] = xor_input1 ^ xor_input2;
  xor_output = xor_lut[3];
end

// Pipeline
reg [7:0] decoded_instr;
reg [31:0] execute_output;
reg [4:0] write_back_rd;

always @(posedge clk or posedge reset) begin
  if (reset) begin
    decoded_instr <= 8'b0;
    execute_output <= 32'b0;
    write_back_rd <= 5'b0;
  end else begin
    case (stage)
      3'b001: // Decode stage
        decoded_instr <= instruction;

      3'b010: // Execute stage
        case (decoded_instr)
          8'b0000_0001: // ADD
            execute_output <= data1 + data2;
          8'b0000_0010: // SUB
            execute_output <= data1 - data2;
          8'b0000_0100: // AND
            execute_output <= data1 & data2;
          8'b0000_1000: // NAND
            execute_output <= ~(data1 & data2);
          default:
            execute_output <= 32'b0;
        endcase

      3'b100: // Write-back stage
        begin
          write_back_rd <= rd;
          regfile[write_back_rd] <= execute_output;
        end
    endcase
  end
end

endmodule

module shift_register (
