module rising_edge_capture (
    input clk,      // Clock input
    input reset,    // Synchronous active-high reset
    input [31:0] in, // 32-bit input for the rising edge capture module
    output reg [31:0] out // 32-bit output from the rising edge capture module
);

    reg [31:0] prev_in;

    always @(posedge clk) begin
        if (reset) begin
            out <= 32'b0;
            prev_in <= 32'b0;
        end else begin
            out <= (in ^ prev_in) & in;
            prev_in <= in;
        end
    end

endmodule

module functional_module (
    input [7:0] shift_reg_out, // Output from the shift register
    input [31:0] rising_edge_capture_out, // Output from the rising edge capture module
    output reg [31:0] out // 32-bit output from the functional module
);

