module top_module (
    input clk,      // Clock input
    input reset,    // Synchronous active-high reset
    input [7:0] d,  // 8-bit input for the shift register
    input [31:0] in, // 32-bit input for the rising edge capture module
    output [31:0] out // 32-bit output from the functional module
);

    wire [7:0] shift_reg_out;
    wire [31:0] rising_edge_capture_out;

    shift_register shift_reg (
        .clk(clk),
        .reset(reset),
        .d(d),
        .q(shift_reg_out)
    );

    rising_edge_capture rec (
        .clk(clk),
        .reset(reset),
        .in(in),
        .out(rising_edge_capture_out)
    );

    functional_module func (
        .shift_reg_out(shift_reg_out),
        .rising_edge_capture_out(rising_edge_capture_out),
        .out(out)
    );

endmodule

