module booth_multiplier (
    input clk,
    input rst, // Synchronous reset input
    input [3:0] multiplicand, // 4-bit multiplicand input
    input [3:0] multiplier, // 4-bit multiplier input
    input [1:0] select, // Select input for the 4-to-1 multiplexer
    output reg [7:0] product // 8-bit product output
);

reg [3:0] a_reg, s_reg; // Registers for the Booth's algorithm
reg [2:0] count; // Counter for the Booth's algorithm
wire [3:0] m_input; // Input to the multiplier module
wire [7:0] m_output; // Output from the multiplier module
wire [3:0] m_select; // Select input for the 4-to-1 multiplexer module

// Instantiate the 4-to-1 multiplexer module
mux_4to1 mux (
    .sel(select),
    .in0(multiplicand),
    .in1(multiplier),
    .in2(4'b0),
    .in3(4'b0),
    .out(m_select)
);

// Instantiate the multiplier module
multiplier_4x4 multiplier (
    .a(m_input),
    .b(4'b1),
    .p(m_output)
);

// Booth's algorithm
always @ (posedge clk) begin
    if (rst) begin
        a_reg <= 4'b0;
        s_reg <= {multiplier, 3'b0};
        count <= 3'b0;
    end else begin
        a_reg <= s_reg;
        s_reg <= {s_reg[3], s_reg[3:1] - m_select, s_reg[0]};
        count <= count + 1;
    end
end

// Connect the inputs to the multiplier module
assign m_input = {a_reg, s_reg[3]};

// Connect the output of the multiplier module to the product output
always @ (posedge clk) begin
    if (rst) begin
        product <= 8'b0;
    end else begin
        product <= {m_output, s_reg[3]};
    end
end

endmodule

module binary_adder (
    input wire clk,
    input wire rst,
    input wire [3:0] in,
    output reg [1:0] out
);

