module top_module (
    input [3:0] multiplier, // Input for 4-bit multiplier
    input wire [15:0] multiplicand, // Input for 16-bit multiplicand
    output wire [19:0] product // Output from multiplication
);

wire [1:0] pos;
priority_encoder pe(.in(multiplier), .pos(pos));

wire [15:0] shifted;
barrel_shifter bs(.in(multiplicand), .out(shifted));

multiplication mult(.multiplier(multiplier), .multiplicand(shifted), .pos(pos), .product(product));

endmodule

