module barrel_shifter (
    input wire [15:0] in,
    output wire [15:0] out
);
parameter SHIFT_AMOUNT = 4;
assign out = {in[15-SHIFT_AMOUNT:0], {SHIFT_AMOUNT{1'b0}}};
