    half_subtractor h1(.a(a), .b(borrow_in), .diff(h1_diff), .borrow_out(h1_borrow_out));
    half_subtractor h2(.a(h1_diff), .b(~b), .diff(diff), .borrow_out(h2_borrow_out));
