module top_module (
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [1:0] select,
    output [3:0] out
);

    // Priority Encoder
    priority_encoder pe(
        .in({data0[3], data1[3], data2[3], data3[3]}),
        .out(select)
    );

    // Multiplexer
    mux_6to1 mux(
        .in0(data0),
        .in1(data1),
        .in2(data2),
        .in3(data3),
        .sel(select),
        .out(out)
    );

    // Bitwise OR
    assign out = out | select;

    // Output 0x1 if none of the input bits are high
    assign out = (out == 0) ? 4'b0001 : out;

