module mux_6to1 (
    input [3:0] in0,
    input [3:0] in1,
    input [3:0] in2,
    input [3:0] in3,
    input [1:0] sel,
    output [3:0] out
);

    assign out = (sel == 2'b00) ? in0 :
                 (sel == 2'b01) ? in1 :
                 (sel == 2'b10) ? in2 :
                                  in3;

endmodule

// 4-bit Priority Encoder
module priority_encoder (
    input [3:0] in,
    output reg [1:0] out
);

    always @* begin
        casez(in)
            4'b0001: out = 2'b00;
            4'b0010: out = 2'b01;
            4'b0100: out = 2'b10;
            4'b1000: out = 2'b11;
            default: out = 2'b00;
        endcase
    end

endmodule

module fifo(
    input clk,
    input reset_n,
    input wr,
    input [7:0] wr_data,
    input rd,
    output [7:0] rd_data,
    output empty,
    output full,
    output almost_empty,
    output almost_full
    );

    reg [7:0] memory [1:0];
    reg [1:0] rd_address;
    reg [1:0] wr_address;
    reg [1:0] entries;
    wire full;
    wire empty;
    wire almost_full;
    wire almost_empty;

    assign full = (entries == 2);
    assign empty = (entries == 0);
    assign almost_full = (entries == 1);
    assign almost_empty = (entries == 1);

    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            rd_address <= 2'b0;
            wr_address <= 2'b0;
            entries <= 2'b0;
        end else begin
            if (wr & !full) begin
                memory[wr_address] <= wr_data;
                wr_address <= (wr_address == 2'b1) ? 2'b0 : (wr_address + 1);
                entries <= entries + 1;
            end
            if (rd & !empty) begin
                rd_data <= memory[rd_address];
                rd_address <= (rd_address == 2'b1) ? 2'b0 : (rd_address + 1);
                entries <= entries - 1;
            end
        end
    end

endmodule

