module addsub_4bit (
    input [3:0] A,
    input [3:0] B,
    input SUB,
    output reg [3:0] SUM,
    output reg CARRY
);

reg [3:0] A_reg, B_reg, SUM_reg;
reg SUB_reg;
reg [4:0] CARRY_reg;

always @(posedge clk) begin
    A_reg <= A;
    B_reg <= B;
    SUB_reg <= SUB;
end

always @(posedge clk) begin
    if (SUB_reg == 0) begin
        SUM_reg <= A_reg + B_reg;
        CARRY_reg <= (A_reg[3] & B_reg[3]) | (A_reg[2] & B_reg[2]) | (A_reg[1] & B_reg[1]) | (A_reg[0] & B_reg[0]);
    end else begin
        SUM_reg <= A_reg - B_reg;
        CARRY_reg <= (~B_reg[3] & A_reg[3]) | (~B_reg[2] & A_reg[2] & ~B_reg[3]) | (~B_reg[1] & A_reg[1] & ~B_reg[3] & ~B_reg[2]) | (~B_reg[0] & A_reg[0] & ~B_reg[3] & ~B_reg[2] & ~B_reg[1]);
    end
end

always @(posedge clk) begin
    SUM <= SUM_reg;
    CARRY <= CARRY_reg[4];
end

endmodule

