module top_module (
    input clk,
    input rst,
    input select,
    input [15:0] in0,
    input [15:0] in1,
    output reg [15:0] count,
    output reg [15:0] product
);

reg [15:0] count_reg;
reg [15:0] product_reg;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        count_reg <= 16'h0;
        product_reg <= 16'h0;
    end else begin
        if (select) begin
            product_reg <= shift_and_add(in0, in1);
        end else begin
            count_reg <= count_reg + 16'h1;
        end
    end
end

assign count = count_reg;
assign product = product_reg;

function [15:0] shift_and_add;
    input [15:0] a, b;
    reg [15:0] result;
    reg [15:0] temp;
    integer i;
begin
    result = 16'h0;
    temp = a;
    for (i = 0; i < 16; i = i + 1) begin
        if (b[i]) begin
            result = result + temp;
        end
        temp = temp << 1;
    end
    shift_and_add = result;
end
endfunction

endmodule

module LDPC (
  input [k-1:0] data_in,
  input [n-1:0] code_in,
  output [k-1:0] data_out,
  output [n-1:0] code_out
);

parameter n = 64; // number of code bits
parameter k = 32; // number of data bits
parameter max_iters = 100; // maximum number of iterations for the decoder

// Define the sparse parity-check matrix H
// H is a 64x32 matrix with 6 ones per row
// The ones are placed in a diagonal pattern
reg [k-1:0] H [n-1:0];
integer i, j, ones_count;
initial begin
  for (i = 0; i < n; i = i + 1) begin
    ones_count = 0;
    for (j = 0; j < k; j = j + 1) begin
      if ((i+j) % 7 == 0) begin
        H[i][j] = 1;
        ones_count = ones_count + 1;
      end else begin
        H[i][j] = 0;
      end
    end
    if (ones_count == 0) begin
      H[i][0] = 1;
    end
  end
end

// LDPC encoder function
// Multiplies data_in with H to generate code_out
// Uses matrix multiplication algorithm
// Assumes H is a sparse matrix
function [n-1:0] ldpc_encode;
  input [k-1:0] data_in;
  reg [n-1:0] code_out;
  integer i, j;
  begin
    for (i = 0; i < n; i = i + 1) begin
      code_out[i] = 0;
      for (j = 0; j < k; j = j + 1) begin
        if (H[i][j] == 1) begin
          code_out[i] = code_out[i] ^ data_in[j];
        end
      end
    end
    ldpc_encode = code_out;
  end
endfunction

// LDPC decoder function
// Uses an iterative algorithm to recover data_out from code_in
// Assumes H is a sparse matrix
function [k-1:0] ldpc_decode;
  input [n-1:0] code_in;
  reg [k-1:0] data_out;
  reg [n-1:0] code_out;
  integer i, j, iter_count;
  begin
    iter_count = 0;
    data_out = code_in;
    code_out = ldpc_encode(data_out);
    while (iter_count < max_iters) begin
      for (i = 0; i < n; i = i + 1) begin
        if (code_in[i] != code_out[i]) begin
          for (j = 0; j < k; j = j + 1) begin
            if (H[i][j] == 1) begin
              data_out[j] = data_out[j] ^ (code_in[i] ^ code_out[i]);
            end
          end
        end
      end
      code_out = ldpc_encode(data_out);
      iter_count = iter_count + 1;
    end
    ldpc_decode = data_out;
  end
endfunction

// Connect inputs to encoder and decoder functions
assign code_out = ldpc_encode(data_in);
assign data_out = ldpc_decode(code_in);

endmodule

module addsub_4bit (
    input [3:0] in_a,
    input [3:0] in_b,
    input mode,
    output reg [3:0] out,
    output overflow
);

    reg [4:0] temp_out;
    reg mode_inv;

    always @(*) begin
        mode_inv = ~mode;
        if (mode == 0) begin
            temp_out = in_a + in_b;
        end else begin
            temp_out = in_a - in_b;
        end
    end

    always @(*) begin
        if (temp_out > 7 || temp_out < -8) begin
            overflow = 1;
        end else begin
            overflow = 0;
        end
    end

    always @(posedge clk) begin
        out <= temp_out[3:0];
    end

endmodule

module priority_encoder (
    input [7:0] I,
    output reg EN,
    output reg V,
    output reg [2:0] Q
);

reg [7:0] I_reg;
reg [7:0] I_next;
reg [2:0] Q_reg;
reg [2:0] Q_next;
reg [2:0] Q_next_next;
reg [2:0] Q_next_next_next;

always @(posedge clk) begin
    I_reg <= I;
end

always @(posedge clk) begin
    I_next <= I_reg;
end

always @(posedge clk) begin
    Q_reg <= Q_next_next;
end

always @(posedge clk) begin
    Q_next <= Q_reg;
end

always @(posedge clk) begin
    Q_next_next <= Q_next_next_next;
end

always @(posedge clk) begin
    if (I_next[7] == 1) begin
        Q_next_next_next <= 7'b111;
    end else if (I_next[6] == 1) begin
        Q_next_next_next <= 7'b110;
    end else if (I_next[5] == 1) begin
        Q_next_next_next <= 7'b101;
    end else if (I_next[4] == 1) begin
        Q_next_next_next <= 7'b100;
    end else if (I_next[3] == 1) begin
        Q_next_next_next <= 7'b011;
    end else if (I_next[2] == 1) begin
        Q_next_next_next <= 7'b010;
    end else if (I_next[1] == 1) begin
        Q_next_next_next <= 7'b001;
    end else if (I_next[0] == 1) begin
        Q_next_next_next <= 7'b000;
    end else begin
        Q_next_next_next <= Q_next;
    end
end

always @(posedge clk) begin
    if (I_next != 8'b00000000) begin
        EN <= 1;
    end else begin
        EN <= 0;
    end
end

always @(posedge clk) begin
    if (I_next != 8'b00000000 && V == 0) begin
        V <= 1;
    end else if (I_next != 8'b00000000 && V == 1) begin
        V <= 0;
    end
end

assign Q = Q_reg;

endmodule

