);

reg [7:0] money_inserted = 0;
reg [1:0] candy_dispensed = 0;
reg change_dispensed = 0;

always @(posedge clk) begin
    if (rst) begin
        money_inserted <= 0;
        candy_dispensed <= 0;
        change_dispensed <= 0;
    end else begin
        if (quarter) money_inserted <= money_inserted + 25;
        if (dime) money_inserted <= money_inserted + 10;
        if (nickel) money_inserted <= money_inserted + 5;

        if (money_inserted >= 50) begin
            if (!candy_dispensed) begin
                if (!skittles_dispense) begin
                    skittles_dispense <= 1;
                    candy_dispensed <= 1;
                    money_inserted <= money_inserted - 50;
                end else if (!mms_dispense) begin
                    mms_dispense <= 1;
                    candy_dispensed <= 2;
                    money_inserted <= money_inserted - 50;
                end else if (!reeses_dispense) begin
                    reeses_dispense <= 1;
                    candy_dispensed <= 3;
                    money_inserted <= money_inserted - 50;
                end
            end else if (!change_dispensed) begin
                change_dispensed <= 1;
                money_inserted <= 0;
            end
        end
    end
end

endmodule

module full_adder(A, B, Cin, S, Cout);
    input A, B, Cin;
    output S, Cout;

    assign S = A ^ B ^ Cin;
    assign Cout = (A & B) | (Cin & (A ^ B));
endmodule

module adder4(A, B, S, Cout);
    input [3:0] A, B;
    output [3:0] S;
    output Cout;

    wire C1, C2, C3;
    full_adder FA1(A[0], B[0], 1'b0, S[0], C1);
    full_adder FA2(A[1], B[1], C1, S[1], C2);
    full_adder FA3(A[2], B[2], C2, S[2], C3);
    full_adder FA4(A[3], B[3], C3, S[3], Cout);
endmodule

module top_module (
    input clk,
    input [7:0] in,
    output q
);

    wire [7:0] anyedge;
    wire [7:0] anyedge_posedge;
    wire [7:0] anyedge_negedge;
    wire [7:0] anyedge_bothedge;

    anyedge_module anyedge_inst (
        .clk(clk),
        .in(in),
        .anyedge(anyedge)
    );

    assign anyedge_posedge = anyedge & (anyedge ^ anyedge_delayed);
    assign anyedge_negedge = anyedge_delayed & (anyedge ^ anyedge_posedge);
    assign anyedge_bothedge = anyedge_posedge & anyedge_negedge;

    dual_edge_triggered_flip_flop dual_edge_inst (
        .clk(clk),
        .d(anyedge_bothedge),
        .q(q)
    );

    reg [7:0] anyedge_delayed;

    always @(posedge clk) begin
        anyedge_delayed <= anyedge;
    end

endmodule

module anyedge_module (
    input clk,
    input [7:0] in,
    output [7:0] anyedge
);

    reg [7:0] in_delayed;

    always @(posedge clk) begin
        in_delayed <= in;
    end

    assign anyedge = in & ~in_delayed;

endmodule

module dual_edge_triggered_flip_flop (
    input clk,
    input d,
    output q
);

    reg q_delayed;

    always @(posedge clk) begin
        q_delayed <= q;
        q <= d;
    end

    always @(negedge clk) begin
        q <= q_delayed;
    end

endmodule

module dff_async_reset_set (
    input        clk,
    input        reset_b,
    input        set_b,
    input        vpwr,
    input        vgnd,
    output reg   q
);

    // Register inputs
    reg reset_b_reg;
    reg set_b_reg;

    // Initialize inputs to X
    initial
    begin
        reset_b_reg = 1'bX;
        set_b_reg   = 1'bX;
    end

    // Synchronize inputs to the clock
    always @(posedge clk)
    begin
        reset_b_reg <= reset_b;
        set_b_reg   <= set_b;
    end

    // Set up power and ground connections
    assign vgnd = 0;
    assign vpwr = 1;

    // Implement the flip-flop logic
    always @(posedge clk)
    begin
        if (reset_b_reg == 0)
            q <= 0;
        else if (set_b_reg == 0)
            q <= 1;
        else
            q <= q;
    end

    // Implement asynchronous reset and set behavior
    always @(reset_b_reg, set_b_reg)
    begin
        if (reset_b_reg == 1 && set_b_reg == 0)
            q <= 0;
        else if (reset_b_reg == 0 && set_b_reg == 1)
            q <= 1;
    end

endmodule

module DSP48E_1(
    input signed [20:0] charge_in,
    input signed [14:0] signal_in,
    input delay_en,
    input clk,
    input store_strb,
    output reg [12:0] DSPout,
    input bunch_strb
);

reg signed [47:0] DSPout_temp, DSPout_temp2, DSPout_temp4, DSPout_temp5;
reg signed [47:0] delayed = 48'b0;
reg signed [47:0] delayed_a = 48'b0;
reg signed [47:0] delayed_b = 48'b0;
reg signed [12:0] DSPout_temp6;
reg [3:0] j = 0;

always @ (posedge clk) begin
    if (delay_en == 1 & j < 14) begin
        DSPout_temp <= (charge_in * signal_in);
        DSPout_temp2 <= DSPout_temp;
        DSPout_temp4 <= DSPout_temp2;
        DSPout_temp5 <= DSPout_temp4 + delayed;
        DSPout_temp6 <= DSPout_temp5[24:12];
        DSPout <= DSPout_temp6;
    end
    else begin
        DSPout_temp <= (charge_in * signal_in);
        DSPout_temp2 <= DSPout_temp;
        DSPout_temp4 <= DSPout_temp2;
        DSPout_temp5 <= DSPout_temp4;
        DSPout_temp6 <= DSPout_temp5[24:12];
        DSPout <= DSPout_temp6;
    end
end

always @ (posedge clk) begin
    if (~bunch_strb) begin
        if (j == 14) j <= 0;
        else j <= j + 1;
    end
end

always @ (posedge clk) begin
    delayed <= delayed_a;
    delayed_a <= delayed_b;
    if (~store_strb) begin
        delayed_b <= 0;
    end
    else if (j == 1) begin
        delayed_b <= DSPout_temp5;
    end
    else begin
        delayed_b <= delayed_b;
    end
end

endmodule

module counter_4bit_sync_reset (
  input aclk,
  input areset,
  output reg [3:0] count,
  output reg overflow
);

  always @(posedge aclk) begin
    if (areset) begin
      count <= 4'b0000;
      overflow <= 1'b0;
    end
    else begin
      if (count == 4'b1111) begin
        count <= 4'b0000;
        overflow <= 1'b1;
      end
      else begin
        count <= count + 1;
        overflow <= 1'b0;
      end
    end
  end

endmodule

module top_module(
    input clk,
    input reset,
    input [31:0] a,
    input [31:0] b,
    output [31:0] out
);

// Carry Select Adder Module
wire [31:0] sum1, sum2;
wire [31:0] carry1, carry2;
wire [31:0] select;

ripple_carry_adder adder1(
    .a(a),
    .b(b),
    .sum(sum1),
    .carry(carry1)
);

ripple_carry_adder adder2(
    .a(a),
    .b(~b),
    .sum(sum2),
    .carry(carry2)
);

mux2to1 #(.WIDTH(32)) mux(
    .in0(sum1),
    .in1(sum2),
    .select(select),
    .out(out)
);

assign select = carry1;

// Functional Module
assign out = (reset) ? 32'b0 : ~out;

endmodule

module ripple_carry_adder(
    input [31:0] a,
    input [31:0] b,
    output [31:0] sum,
    output [31:0] carry
);

genvar i;
wire [31:0] c;

assign sum[0] = a[0] ^ b[0];
assign c[0] = a[0] & b[0];

generate
    for (i = 1; i < 32; i = i + 1) begin : adder
        assign sum[i] = a[i] ^ b[i] ^ c[i-1];
        assign c[i] = (a[i] & b[i]) | (a[i] & c[i-1]) | (b[i] & c[i-1]);
    end
endgenerate

assign carry = c;

endmodule

module mux2to1 #(
    parameter WIDTH = 1
)(
    input [WIDTH-1:0] in0,
    input [WIDTH-1:0] in1,
    input select,
    output reg [WIDTH-1:0] out
);

always @(*) begin
    if (select) begin
        out = in1;
    end else begin
        out = in0;
    end
end

endmodule

