module top_module(
    input [3:0] bin_in, // 4-bit binary input for gray code converter
    input [15:0] shift_in, // 16-bit input vector for barrel shifter
    input [3:0] shift_amt, // 4-bit input for specifying number of bits to shift by
    output [3:0] gray_out, // 4-bit gray code output from binary to gray code converter
    output [15:0] shift_out, // 16-bit output vector from barrel shifter
    output [3:0] xor_out // 4-bit output from functional module
);

// Binary to Gray Code Converter
wire [3:0] gray_out_wire;
assign gray_out_wire[0] = bin_in[0];
assign gray_out_wire[1] = bin_in[0] ^ bin_in[1];
assign gray_out_wire[2] = bin_in[1] ^ bin_in[2];
assign gray_out_wire[3] = bin_in[2] ^ bin_in[3];
assign gray_out = gray_out_wire;

// Barrel Shifter
wire [15:0] shift_out_wire;
reg [15:0] shift_reg;
integer i;
always @ (posedge clk) begin
    shift_reg <= shift_in;
    for (i = 0; i < 4; i = i + 1) begin
        if (shift_amt == i) begin
            shift_out_wire = shift_reg;
        end
        shift_reg <= {shift_reg[14:0], 1'b0};
    end
end
assign shift_out = shift_out_wire;

// Functional Module
wire [3:0] xor_out_wire;
assign xor_out_wire = gray_out_wire ^ shift_out_wire[3:0];
assign xor_out = xor_out_wire;

endmodule

module binary_to_gray (
    input [7:0] binary_in,
    input sel_b1,
    input sel_b2,
    output reg [7:0] gray_out);
    // 3-bit position value from priority encoder
    output reg [2:0] pos;

    // Priority encoder to find position of first 1 in binary input
    wire [7:0] not_binary_in = ~binary_in;
    assign pos = not_binary_in > binary_in ? {3'b000, not_binary_in[7:3]} :
                                             not_binary_in > binary_in >> 1 ? {3'b001, not_binary_in[6:2]} :
                                                                             {3'b010, not_binary_in[5:1]};

    // 2-to-1 multiplexer to select between binary input and right shift by 1 bit
    wire [7:0] shift_right = {1'b0, binary_in[7:1]};
    always @(*) begin
        if (sel_b1 && sel_b2) begin
            gray_out = shift_right;
        end else begin
            gray_out = binary_in;
        end
    end

    // Gray code conversion
    always @(posedge gray_out) begin
        gray_out <= binary_in ^ (binary_in >> 1);
    end
endmodule

module fifo_buffer(
    input clk,
    input rst,
    input wr_en,
    input rd_en,
    input [31:0] data_in,
    output [31:0] data_out
);

parameter DEPTH = 16;

reg [31:0] buffer [0:DEPTH-1];
reg [5:0] head = 0;
reg [5:0] tail = 0;
reg [5:0] count = 0;

always @(posedge clk) begin
    if (rst) begin
        head <= 0;
        tail <= 0;
        count <= 0;
    end else begin
        if (wr_en && !rd_en && count < DEPTH) begin
            buffer[head] <= data_in;
            head <= head + 1;
            count <= count + 1;
        end
        if (!wr_en && rd_en && count > 0) begin
            data_out <= buffer[tail];
            tail <= tail + 1;
            count <= count - 1;
        end
    end
end

endmodule

