module traffic_light(
  input clk,
  input rst,
  output reg red,
  output reg yellow,
  output reg green
);

parameter GREEN_TIME = 15_000_000; // 15 seconds at 50MHz
parameter YELLOW_TIME = 3_000_000; // 3 seconds at 50MHz
parameter RED_TIME = 12_000_000; // 12 seconds at 50MHz

reg [23:0] counter; // 24-bit counter for timing

always @(posedge clk) begin
  if (rst) begin
    counter <= 0;
    red <= 1'b0;
    yellow <= 1'b0;
    green <= 1'b1;
  end
  else begin
    counter <= counter + 1;
    if (counter >= GREEN_TIME && counter < GREEN_TIME + YELLOW_TIME) begin
      green <= 1'b0;
      yellow <= 1'b1;
    end
    else if (counter >= GREEN_TIME + YELLOW_TIME && counter < GREEN_TIME + YELLOW_TIME + RED_TIME) begin
      yellow <= 1'b0;
      red <= 1'b1;
    end
    else if (counter >= GREEN_TIME + YELLOW_TIME + RED_TIME) begin
      red <= 1'b0;
      green <= 1'b1;
      counter <= 0;
    end
  end
end

endmodule

module Adders (
  input [N-1:0] A, B, // binary numbers to be added
  output [N:0] S, C // sum and carry-out
);

parameter N = 4; // number of bits in binary numbers

// Half Adder
wire HA_S, HA_C;
assign HA_S = A ^ B;
assign HA_C = A & B;
assign S[0] = HA_S;
assign C[0] = HA_C;

// Full Adder
wire FA_S, FA_C;
assign FA_S = A ^ B ^ C[0];
assign FA_C = (A & B) | (C[0] & (A ^ B));
assign S[1] = FA_S;
assign C[1] = FA_C;

// Ripple-Carry Adder
genvar i;
generate
  for (i = 2; i < N+1; i = i+1) begin : ripple_carry_adder
    wire RCA_S, RCA_C;
    assign RCA_S = A[i-1] ^ B[i-1] ^ C[i-2];
    assign RCA_C = (A[i-1] & B[i-1]) | (C[i-2] & (A[i-1] ^ B[i-1]));
    assign S[i] = RCA_S;
    assign C[i] = RCA_C;
  end
endgenerate

// Carry-Lookahead Adder
wire [N-1:0] P, G, C_in;
assign P = A | B;
assign G = A & B;
assign C_in[0] = 0;
genvar j;
generate
  for (j = 1; j < N; j = j+1) begin : carry_lookahead_adder
    wire CLA_C;
    assign CLA_C = (G[j-1] & C_in[j-1]) | (P[j-1] & G[j-1]) | (P[j-1] & C_in[j-1]);
    assign C_in[j] = CLA_C;
  end
endgenerate
wire CLA_S;
assign CLA_S = A[N-1] ^ B[N-1] ^ C_in[N-1];
assign S[N] = CLA_S;
assign C[N] = C_in[N-1];

// Carry-Select Adder
wire [N-1:0] A1, B1, A2, B2;
assign A1 = A[N-2:0];
assign B1 = B[N-2:0];
assign A2 = {A[N-1], {N-1{1'b0}}};
assign B2 = {B[N-1], {N-1{1'b0}}};
wire CS_C, CS_S1, CS_S2;
carry_select_adder CSA1(.A(A1), .B(B1), .C(C[0]), .S(CS_S1), .C(CS_C));
carry_select_adder CSA2(.A(A2), .B(B2), .C(CS_C), .S(CS_S2), .C(C[N]));
assign S[N-1:0] = {CS_S2, CS_S1};

// Carry-Skip Adder
wire [N-1:0] D, E, F, G, H, K;
assign D = A ^ B;
assign E = A & B;
assign F = E | (D & C[0]);
assign G = D & C[0];
assign H = G | (E & K[0]);
assign S[0] = F;
assign C[0] = H;
genvar k;
generate
  for (k = 1; k < N; k = k+1) begin : carry_skip_adder
    wire CSA_S, CSA_C;
    assign K[k] = (G[k-1] & K[k-1]) | (E[k-1] & C[k-1]);
    assign CSA_S = A[k] ^ B[k] ^ K[k];
    assign CSA_C = (A[k] & B[k]) | (K[k] & (A[k] ^ B[k]));
    assign S[k] = CSA_S;
    assign C[k] = CSA_C;
  end
endgenerate

endmodule

// Carry-Select Adder module
module carry_select_adder (
  input [N-1:0] A, B, C, // binary numbers and carry-in
  output [N-1:0] S, C_out // sum and carry-out
);

parameter N = 4; // number of bits in binary numbers

wire [N-1:0] P, G, C_in;
assign P = A | B;
assign G = A & B;
assign C_in[0] = C;
genvar i;
generate
  for (i = 1; i < N; i = i+1) begin : carry_select_adder
    wire CSA_C;
    assign CSA_C = (G[i-1] & C_in[i-1]) | (P[i-1] & G[i-1]) | (P[i-1] & C_in[i-1]);
    assign C_in[i] = CSA_C;
  end
endgenerate
wire CSA_S;
assign CSA_S = A[N-1] ^ B[N-1] ^ C_in[N-1];
assign S = {C_in[N-1], CSA_S};
assign C_out = C_in[N-1];

endmodule

module top_module (
  input clk,
  input reset,
  input [31:0] data1,
  input [31:0] data2,
  input [7:0] instruction,
  input [2:0] stage,
  input [3:0] rs1,
  input [3:0] rs2,
  input [3:0] rd,
  input [3:0] in,
  output reg [31:0] regfile [15:0],
  output reg [1:0] pos,
  output reg [31:0] final_output
);

  // Pipeline registers
  reg [31:0] data1_reg;
  reg [31:0] data2_reg;
  reg [3:0] rs1_reg;
  reg [3:0] rs2_reg;
  reg [3:0] rd_reg;
  reg [31:0] alu_output_reg;
  reg [31:0] mem_output_reg;
  reg [31:0] wb_data_reg;

  // Priority encoder outputs
  reg [3:0] priority;
  reg [1:0] pos_reg;

  // Register file
  always @(posedge clk) begin
    if (reset) begin
      regfile <= 0;
    end else begin
      casez({stage, instruction})
        // Stage 1: Instruction fetch
        2'b00_00_0000: begin
          data1_reg <= regfile[rs1];
          data2_reg <= regfile[rs2];
        end
        // Stage 2: Instruction decoding and execution
        2'b00_01_0000: begin
          case (instruction[3:0])
            4'b0000: alu_output_reg <= data1_reg + data2_reg;
            4'b0001: alu_output_reg <= data1_reg - data2_reg;
            4'b0010: alu_output_reg <= data1_reg & data2_reg;
            4'b0011: alu_output_reg <= data1_reg | data2_reg;
            4'b0100: alu_output_reg <= data1_reg ^ data2_reg;
            4'b0101: alu_output_reg <= ~data1_reg;
            4'b0110: alu_output_reg <= data1_reg << data2_reg;
            4'b0111: alu_output_reg <= data1_reg >> data2_reg;
            4'b1000: alu_output_reg <= data1_reg >>> data2_reg;
            default: alu_output_reg <= 0;
          endcase
          rd_reg <= rd;
        end
        // Stage 3: Write back to register file
        2'b00_10_0000: begin
          wb_data_reg <= alu_output_reg;
          regfile[rd_reg] <= wb_data_reg;
        end
        // Default: Do nothing
        default: begin
        end
      endcase
    end
  end

  // Priority encoder
  always @* begin
    if (in[3]) begin
      priority = 4'b1110;
    end else if (in[2]) begin
      priority = 4'b1101;
    end else if (in[1]) begin
      priority = 4'b1011;
    end else if (in[0]) begin
      priority = 4'b0111;
    end else begin
      priority = 4'b0000;
    end
    pos_reg[1] <= priority[3];
    pos_reg[0] <= priority[2];
  end

  // Functional module
  always @(posedge clk) begin
    final_output <= regfile[pos_reg];
  end

  // Output assignments
  assign pos = pos_reg;

endmodule

