module log_exp (
  input [31:0] x,
  input [31:0] base,
  input [31:0] power,
  output [31:0] log_out,
  output [31:0] exp_out
);

  reg signed [31:0] log_sum, exp_sum;
  reg signed [31:0] log_term, exp_term;
  reg signed [31:0] log_x, exp_x;
  reg signed [31:0] log_base, exp_power;
  reg signed [31:0] log_n, exp_n;
  reg signed [31:0] log_sign, exp_sign;

  assign log_out = log_sum;
  assign exp_out = exp_sum;

  always @(*) begin
    // Logarithmic function
    log_x = x - 1;
    log_base = base - 1;
    log_sum = 0;
    log_n = 1;
    log_sign = 1;

    while (log_n < 20) begin
      log_term = log_sign * (log_x ** log_n) / log_n;
      log_sum = log_sum + log_term;
      log_n = log_n + 1;
      log_sign = -log_sign;
    end

    log_sum = log_sum / $ln(log_base);

    // Exponential function
    exp_x = x;
    exp_power = power;
    exp_sum = 1;
    exp_n = 1;
    exp_sign = 1;

    while (exp_n < 20) begin
      exp_term = exp_sign * (exp_x ** exp_n) / $fact(exp_n);
      exp_sum = exp_sum + exp_term;
      exp_n = exp_n + 1;
      exp_sign = exp_sign + 1;
    end

    exp_sum = exp_sum ** exp_power;
  end

endmodule

