module eth_mac_tx (
  input clk,
  input reset,
  input [7:0] tx_data,
  input start_of_frame,
  input end_of_frame,
  output tx_en,
  output tx_valid,
  output tx_error
);

  // Define constants for Ethernet frame format
  parameter PREAMBLE = 64'hAAAAAAAAAAAAAAAB;
  parameter SFD = 8'h55;
  parameter DEST_MAC = 48'h001122334455;
  parameter SRC_MAC = 48'h66778899AABB;
  parameter ETH_TYPE = 16'h0800;
  parameter MIN_FRAME_LEN = 64;

  // Define state machine states
  parameter IDLE = 2'b00;
  parameter PREAMBLE_SFD = 2'b01;
  parameter DEST_MAC_ADDR = 2'b10;
  parameter SRC_MAC_ADDR = 2'b11;
  parameter ETH_TYPE_LEN = 2'b100;
  parameter DATA = 2'b101;
  parameter PAD = 2'b110;
  parameter CRC = 2'b111;

  // Define state machine signals
  reg [1:0] state;
  reg [47:0] dest_mac;
  reg [47:0] src_mac;
  reg [15:0] eth_type;
  reg [31:0] data;
  reg [6:0] pad_len;
  reg [31:0] crc;
  reg [63:0] preamble_sfd;
  reg [7:0] frame_byte;
  reg [6:0] frame_count;
  reg [31:0] bit_count;
  reg [31:0] frame_len;
  reg [31:0] crc_count;
  reg tx_en_reg;
  reg tx_valid_reg;
  reg tx_error_reg;

  // Initialize state machine and signals
  always @(posedge clk) begin
    if (reset) begin
      state <= IDLE;
      dest_mac <= DEST_MAC;
      src_mac <= SRC_MAC;
      eth_type <= ETH_TYPE;
      data <= 0;
      pad_len <= 0;
      crc <= 0;
      preamble_sfd <= PREAMBLE;
      frame_byte <= 0;
      frame_count <= 0;
      bit_count <= 0;
      frame_len <= 0;
      crc_count <= 0;
      tx_en_reg <= 0;
      tx_valid_reg <= 0;
      tx_error_reg <= 0;
    end else begin
      case (state)
        IDLE: begin
          if (start_of_frame) begin
            state <= PREAMBLE_SFD;
            frame_len <= 0;
            crc_count <= 0;
          end
        end
        PREAMBLE_SFD: begin
          if (bit_count < 64) begin
            preamble_sfd <= {preamble_sfd[62:0], preamble_sfd[63]};
            frame_byte <= preamble_sfd[63];
            bit_count <= bit_count + 1;
          end else begin
            preamble_sfd <= 0;
            frame_byte <= SFD;
            state <= DEST_MAC_ADDR;
            bit_count <= 0;
          end
        end
        DEST_MAC_ADDR: begin
          if (bit_count < 48) begin
            frame_byte <= dest_mac[47-bit_count];
            bit_count <= bit_count + 1;
          end else begin
            frame_byte <= src_mac[47];
            state <= SRC_MAC_ADDR;
            bit_count <= 0;
          end
        end
        SRC_MAC_ADDR: begin
          if (bit_count < 48) begin
            frame_byte <= src_mac[47-bit_count];
            bit_count <= bit_count + 1;
          end else begin
            frame_byte <= eth_type[15];
            state <= ETH_TYPE_LEN;
            bit_count <= 0;
          end
        end
        ETH_TYPE_LEN: begin
          if (bit_count < 16) begin
            frame_byte <= eth_type[15-bit_count];
            bit_count <= bit_count + 1;
          end else begin
            if (frame_len < MIN_FRAME_LEN) begin
              pad_len <= MIN_FRAME_LEN - frame_len;
              state <= PAD;
            end else begin
              state <= DATA;
            end
            bit_count <= 0;
          end
        end
        DATA: begin
          if (frame_count < frame_len) begin
            frame_byte <= data[31:24];
            data <= {data[23:0], tx_data};
            frame_count <= frame_count + 1;
          end else begin
            crc <= crc + frame_len;
            state <= CRC;
            bit_count <= 0;
          end
        end
        PAD: begin
          if (frame_count < pad_len) begin
            frame_byte <= 8'h00;
            frame_count <= frame_count + 1;
          end else begin
            crc <= crc + pad_len;
            state <= CRC;
            bit_count <= 0;
          end
        end
        CRC: begin
          if (bit_count < 32) begin
            frame_byte <= crc[31-bit_count];
            bit_count <= bit_count + 1;
          end else begin
            tx_en_reg <= 1;
            tx_valid_reg <= 1;
            state <= IDLE;
            bit_count <= 0;
          end
        end
      endcase
    end
  end

  // Output signals
  assign tx_en = tx_en_reg;
  assign tx_valid = tx_valid_reg;
  assign tx_error = tx_error_reg;

endmodule

