module ToneGenerator (
  input clk,
  input [1:0] waveform_select,
  output waveform
);

parameter frequency = 1000;
parameter duty_cycle = 0.5;

// Additional parameters may be added depending on the waveform type

reg [15:0] phase_acc = 0;
reg [7:0] dtmf_counter = 0;
reg [7:0] square_counter = 0;
reg [7:0] sine_index = 0;
reg [7:0] square_threshold = 255 * duty_cycle;

// DTMF waveform generation
always @(posedge clk) begin
  if (waveform_select == 2'b00) begin
    case (dtmf_counter)
      8'h00: waveform <= 8'b00001111; // 697 Hz
      8'h10: waveform <= 8'b00000111; // 770 Hz
      8'h20: waveform <= 8'b00001011; // 852 Hz
      8'h30: waveform <= 8'b00010011; // 941 Hz
      8'h40: waveform <= 8'b00100011; // 1209 Hz
      8'h50: waveform <= 8'b01000011; // 1336 Hz
      8'h60: waveform <= 8'b10000011; // 1477 Hz
      8'h70: waveform <= 8'b00000011; // 1633 Hz
    endcase
    dtmf_counter <= dtmf_counter + 1;
    if (dtmf_counter == 8'h78) dtmf_counter <= 0;
  end
end

// Sine waveform generation
always @(posedge clk) begin
  if (waveform_select == 2'b01) begin
    waveform <= $sin(2 * $pi * frequency * sine_index / 256);
    sine_index <= sine_index + 1;
    if (sine_index == 8'hFF) sine_index <= 0;
  end
end

// Square waveform generation
always @(posedge clk) begin
  if (waveform_select == 2'b10) begin
    if (square_counter < square_threshold) waveform <= 1'b1;
    else waveform <= 1'b0;
    square_counter <= square_counter + 1;
    if (square_counter == 8'hFF) square_counter <= 0;
  end
end

endmodule

