module traffic_light_controller (
  input clk,
  input reset,
  input pedestrian_button,
  output reg green_light,
  output reg yellow_light,
  output reg red_light
);

  localparam GREEN_TIME = 10; // in seconds
  localparam YELLOW_TIME = 2; // in seconds
  localparam RED_TIME = 10; // in seconds
  localparam PEDESTRIAN_RED_TIME = 5; // in seconds

  reg [3:0] state;
  reg [3:0] next_state;
  reg [3:0] counter;

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      state <= 4'b000;
      counter <= 4'b0000;
    end else begin
      state <= next_state;
      counter <= counter + 1;
    end
  end

  always @(*) begin
    case (state)
      4'b000: begin // Green light
        green_light = 1;
        yellow_light = 0;
        red_light = 0;
        if (pedestrian_button) begin
          next_state = 4'b100;
          counter = 0;
        end else if (counter == GREEN_TIME * 2) begin
          next_state = 4'b001;
          counter = 0;
        end else begin
          next_state = 4'b000;
        end
      end
      4'b001: begin // Yellow light
        green_light = 0;
        yellow_light = 1;
        red_light = 0;
        if (counter == YELLOW_TIME * 2) begin
          next_state = 4'b010;
          counter = 0;
        end else begin
          next_state = 4'b001;
        end
      end
      4'b010: begin // Red light
        green_light = 0;
        yellow_light = 0;
        red_light = 1;
        if (counter == RED_TIME * 2) begin
          next_state = 4'b000;
          counter = 0;
        end else begin
          next_state = 4'b010;
        end
      end
      4'b100: begin // Pedestrian Red light
        green_light = 0;
        yellow_light = 0;
        red_light = 1;
        if (counter == PEDESTRIAN_RED_TIME * 2) begin
          next_state = 4'b000;
          counter = 0;
        end else begin
          next_state = 4'b100;
        end
      end
      default: begin
        green_light = 0;
        yellow_light = 0;
        red_light = 0;
        next_state = 4'b000;
      end
    endcase
  end

endmodule

