module binary_search (
    input wire clk,
    input wire [31:0] target,
    input wire [31:0] sorted_array [31:0],
    output reg [4:0] index
);

    reg [4:0] left, right, middle;
    reg found;

    always @(posedge clk) begin
        if (left > right) begin
            index <= -1;
            found <= 0;
        end
        else begin
            middle <= (left + right) / 2;
            if (sorted_array[middle] == target) begin
                index <= middle;
                found <= 1;
            end
            else if (sorted_array[middle] > target)
                right <= middle - 1;
            else
                left <= middle + 1;
        end
    end

    initial begin
        left = 0;
        right = 31;
        found = 0;
    end

endmodule

