module edge_detection (
    input clk,
    input reset,
    input signal,
    output reg rising_edge,
    output reg falling_edge
);

    parameter IDLE = 2'b00;
    parameter RISING = 2'b01;
    parameter FALLING = 2'b10;

    reg [1:0] state;
    reg prev_signal;

    always @(posedge clk, posedge reset) begin
        if(reset) begin
            state <= IDLE;
            prev_signal <= 1'b0;
            rising_edge <= 1'b0;
            falling_edge <= 1'b0;
        end
        else begin
            case(state)
                IDLE: begin
                    if(signal == 1'b1 && prev_signal == 1'b0) begin
                        state <= RISING;
                        rising_edge <= 1'b1;
                    end
                    else if(signal == 1'b0 && prev_signal == 1'b1) begin
                        state <= FALLING;
                        falling_edge <= 1'b1;
                    end
                end
                RISING: begin
                    if(signal == 1'b0) begin
                        state <= IDLE;
                    end
                end
                FALLING: begin
                    if(signal == 1'b1) begin
                        state <= IDLE;
                    end
                end
            endcase
            prev_signal <= signal;
        end
    end

endmodule

