module bitwise_adder(
    input [7:0] a,
    input [7:0] b,
    output [7:0] c
);

wire [7:0] carry;
wire [7:0] sum;

assign carry[0] = a[0] & b[0];
assign sum[0] = a[0] ^ b[0];

genvar i;
generate
    for (i = 1; i < 8; i = i + 1) begin
        assign carry[i] = (a[i] & b[i]) | (a[i - 1] & carry[i - 1]);
        assign sum[i] = a[i] ^ b[i] ^ carry[i - 1];
    end
endgenerate

assign c = sum;

