module mfmDecode (
    input clk, rst, mfmIn, mfmEdge,
    output reg currentRealBit,
    output reg currentRealBitValid
);

reg [1:0] state;
wire mfmInPrev;

assign mfmInPrev = mfmIn;

always @(posedge clk) begin
    if (rst) begin
        state <= 2'b00;
        currentRealBit <= 1'b0;
        currentRealBitValid <= 1'b0;
    end else begin
        case (state)
            2'b00: begin
                if (mfmEdge) begin
                    state <= 2'b01;
                    currentRealBit <= mfmIn;
                    currentRealBitValid <= 1'b0;
                end
            end
            2'b01: begin
                if (mfmEdge) begin
                    state <= 2'b10;
                    currentRealBitValid <= mfmInPrev & ~mfmIn;
                end
            end
            2'b10: begin
                if (mfmEdge) begin
                    state <= 2'b01;
                    currentRealBit <= mfmIn;
                end
            end
        endcase
    end
end

endmodule

module delay_locked_loop (
    input clk,
    input reset,
    input data_in,
    output reg data_out,
    output locked
);

parameter DELAY_LENGTH = 10; // number of delay stages in the delay chain
parameter LOCK_THRESHOLD = 5; // number of cycles before locking

reg [DELAY_LENGTH-1:0] delay_chain; // delay chain
reg [4:0] lock_counter; // lock counter
reg locked_reg; // locked register

always @(posedge clk) begin
    if (reset) begin
        delay_chain <= 0;
        lock_counter <= 0;
        locked_reg <= 0;
        data_out <= 0;
    end else begin
        // shift the delay chain
        delay_chain <= {delay_chain[DELAY_LENGTH-2:0], data_in};

        // increment or reset lock counter
        if (delay_chain == {DELAY_LENGTH{1'b1}} || delay_chain == {DELAY_LENGTH{1'b0}}) begin
            lock_counter <= lock_counter + 1;
        end else begin
            lock_counter <= 0;
        end

        // set locked register
        if (lock_counter >= LOCK_THRESHOLD) begin
            locked_reg <= 1;
        end else begin
            locked_reg <= 0;
        end

        // output delayed data
        data_out <= delay_chain[DELAY_LENGTH-1];
    end
end

assign locked = locked_reg;

endmodule

