module vga_controller (
  input         clk,              // 100 Mhz clock
  input         rst,

  input         enable_crtc,

  // CRTC configuration signals

  input [5:0]   cur_start,
  input [5:0]   cur_end,
  input [4:0]   vcursor,
  input [6:0]   hcursor,

  input [6:0]   horiz_total,
  input [6:0]   end_horiz,
  input [6:0]   st_hor_retr,
  input [4:0]   end_hor_retr,
  input [9:0]   vert_total,
  input [9:0]   end_vert,
  input [9:0]   st_ver_retr,
  input [3:0]   end_ver_retr,

  // CRTC output signals

  output reg [9:0]  h_count,      // Horizontal pipeline delay is 2 cycles
  output reg        horiz_sync_i,

  output reg [9:0]  v_count,      // 0 to VER_SCAN_END
  output reg        vert_sync,

  output reg        video_on_h_i,
  output reg        video_on_v

);

// Registers and nets
wire [9:0] hor_disp_end;
wire [9:0] hor_scan_end;
wire [9:0] ver_disp_end;
wire [9:0] ver_sync_beg;
wire [3:0] ver_sync_end;
wire [9:0] ver_scan_end;

// Continuous assignments
assign hor_scan_end = { horiz_total[6:2] + 1'b1, horiz_total[1:0], 3'h7 };
assign hor_disp_end = { end_horiz, 3'h7 };
assign ver_scan_end = vert_total + 10'd1;
assign ver_disp_end = end_vert + 10'd1;
assign ver_sync_beg = st_ver_retr;
assign ver_sync_end = end_ver_retr + 4'd1;

// Sync generation & timing process
// Generate horizontal and vertical timing signals for video signal
always @(posedge clk)
  if (rst)
    begin
      h_count      <= 10'b0;
      horiz_sync_i <= 1'b1;
      v_count      <= 10'b0;
      vert_sync    <= 1'b1;
      video_on_h_i <= 1'b1;
      video_on_v   <= 1'b1;
    end
  else
    if (enable_crtc)
      begin
        h_count      <= (h_count==hor_scan_end) ? 10'b0 : h_count + 10'b1;
        horiz_sync_i <= horiz_sync_i ? (h_count[9:3]!=st_hor_retr)
                                     : (h_count[7:3]==end_hor_retr);
        v_count      <= (v_count==ver_scan_end && h_count==hor_scan_end) ? 10'b0
                      : ((h_count==hor_scan_end) ? v_count + 10'b1 : v_count);
        vert_sync    <= vert_sync ? (v_count!=ver_sync_beg)
                                  : (v_count[3:0]==ver_sync_end);

        video_on_h_i <= (h_count==hor_scan_end) ? 1'b1
                      : ((h_count==hor_disp_end) ? 1'b0 : video_on_h_i);
        video_on_v   <= (v_count==10'h0) ? 1'b1
                      : ((v_count==ver_disp_end) ? 1'b0 : video_on_v);
      end

endmodule

module ddr3_controller (
  input clock_source,
  input global_reset_n,
  output reg [14:0] mem_addr,
  output reg [2:0] mem_ba,
  output reg mem_cas_n,
  output reg mem_cke,
  output reg mem_clk,
  output reg mem_clk_n,
  output reg mem_cs_n,
  output reg [3:0] mem_dm,
  inout [31:0] mem_dq,
  inout [3:0] mem_dqs,
  inout [3:0] mem_dqsn,
  output reg mem_odt,
  output reg mem_ras_n,
  output reg mem_reset_n,
  output reg mem_we_n,
  output reg pnf,
  output reg [15:0] pnf_per_byte,
  output reg test_complete,
  output reg [7:0] test_status
);

reg [1:0] state;
reg [31:0] count;
reg [31:0] errors;
reg [3:0] dq;
reg [3:0] dqs;
reg [3:0] dqsn;

parameter IDLE = 2'b00;
parameter READ = 2'b01;
parameter WRITE = 2'b10;

assign mem_dq = dq;
assign mem_dqs = dqs;
assign mem_dqsn = dqsn;

always @(posedge clock_source) begin
  if (!global_reset_n) begin
    state <= IDLE;
    count <= 0;
    errors <= 0;
    dq <= 4'b0000;
    dqs <= 4'b0000;
    dqsn <= 4'b0000;
    mem_addr <= 15'b0;
    mem_ba <= 3'b0;
    mem_cas_n <= 1'b1;
    mem_cke <= 1'b0;
    mem_clk <= 1'b0;
    mem_clk_n <= 1'b1;
    mem_cs_n <= 1'b1;
    mem_dm <= 4'b1111;
    mem_odt <= 1'b0;
    mem_ras_n <= 1'b1;
    mem_reset_n <= 1'b1;
    mem_we_n <= 1'b1;
    pnf <= 1'b0;
    pnf_per_byte <= 16'b0;
    test_complete <= 1'b0;
    test_status <= 8'b0;
  end else begin
    case (state)
      IDLE: begin
        mem_cke <= 1'b1;
        mem_cs_n <= 1'b0;
        mem_reset_n <= 1'b0;
        mem_odt <= 1'b1;
        state <= READ;
        count <= 0;
      end
      READ: begin
        mem_addr <= count;
        mem_ba <= 3'b000;
        mem_ras_n <= 1'b0;
        mem_cas_n <= 1'b0;
        mem_we_n <= 1'b1;
        dq <= 4'b0000;
        dqs <= 4'b0000;
        dqsn <= 4'b0000;
        state <= WRITE;
      end
      WRITE: begin
        mem_addr <= count;
        mem_ba <= 3'b000;
        mem_ras_n <= 1'b0;
        mem_cas_n <= 1'b1;
        mem_we_n <= 1'b0;
        dq <= 4'b1111;
        dqs <= 4'b1111;
        dqsn <= 4'b1111;
        if (mem_dq != 32'hffffffff) begin
          errors <= errors + 1;
          if (errors == 1) begin
            pnf <= 1'b1;
            pnf_per_byte <= {16{1}};
          end else begin
            pnf_per_byte <= pnf_per_byte + 16'h0001;
          end
        end
        count <= count + 1;
        if (count == 16'h7fff) begin
          test_complete <= 1'b1;
          if (errors == 0) begin
            test_status <= 8'b00000001;
          end else begin
            test_status <= 8'b00000010;
          end
          state <= IDLE;
        end else begin
          state <= READ;
        end
      end
    endcase
  end
end

endmodule

module byte_reverser_pipeline(
    input [31:0] in,
    output [31:0] out
);

reg [7:0] byte_0, byte_1, byte_2, byte_3;
reg [31:0] stage_1_out, stage_2_out, stage_3_out;

// Stage 1: Extract each byte from the input
assign byte_0 = in[7:0];
assign byte_1 = in[15:8];
assign byte_2 = in[23:16];
assign byte_3 = in[31:24];

// Stage 2: Reverse the order of the bytes
assign stage_1_out = {byte_3, byte_2, byte_1, byte_0};

// Stage 3: Combine the reversed bytes into a 32-bit output
assign stage_2_out = {stage_1_out[7:0], stage_1_out[15:8], stage_1_out[23:16], stage_1_out[31:24]};
assign stage_3_out = stage_2_out;

// Output the final result
assign out = stage_3_out;

endmodule

