module accumulation_buffer (
    input [7:0] data_in,
    input valid_in,
    input clk,
    input rst,
    output reg valid_out,
    output reg [31:0] data_out
);
    reg [7:0] buffer [0:3];
    reg [1:0] count = 0;

    always @(posedge clk) begin
        if (rst) begin
            count <= 0;
            valid_out <= 0;
            data_out <= 0;
            buffer <= 0;
        end else if (valid_in) begin
            buffer[count] <= data_in;
            count <= count + 1;
            if (count == 3) begin
                valid_out <= 1;
                data_out <= {buffer[0], buffer[1], buffer[2], data_in};
                count <= 0;
            end
        end
    end
endmodule

