module calculator(
    input signed [31:0] A,
    input signed [31:0] B,
    input [1:0] ctrl,
    input rst,
    output reg signed [31:0] result,
    output reg flag
);

always @ (ctrl or A or B or rst) begin
    if (rst) begin
        result <= 0;
        flag <= 0;
    end else begin
        case (ctrl)
            2'b00: result <= A + B;
            2'b01: result <= A - B;
            2'b10: result <= A * B;
            2'b11: begin
                if (B == 0) begin
                    flag <= 1;
                    result <= 0;
                end else begin
                    flag <= 0;
                    result <= A / B;
                end
            end
        endcase
    end
end

endmodule

module step_id(inst, ena_, cond_dout,
    rdy_nop_, rdy_cpf_, rdy_cpt_, rdy_ld_, rdy_st_, rdy_clr_, rdy_im_, rdy_tce_, rdy_ts_, rdy_add_, rdy_sub_);
    input [7:0] inst;
    input ena_;
    input cond_dout;
    output rdy_nop_, rdy_cpf_, rdy_cpt_, rdy_ld_, rdy_st_, rdy_clr_, rdy_im_, rdy_tce_, rdy_ts_, rdy_add_, rdy_sub_;

    wire cond_ = inst[7] ^ cond_dout;
    wire [6:0] inst_cond = inst[6:0] & {7{~(cond_ | ena_)}};

    assign rdy_nop_ = inst_cond[6:0] != 7'b0000000 || ena_;
    assign rdy_cpf_ = inst_cond[6:4] != 3'b010 || inst_cond[3:0] == 4'b0000;
    assign rdy_cpt_ = inst_cond[6:4] != 3'b011 || inst_cond[3:0] == 4'b0000;
    assign rdy_ld_  = {inst_cond[6:2], inst_cond[0]} != {5'b10001, 1'b0};
    assign rdy_st_  = {inst_cond[6:2], inst_cond[0]} != {5'b10001, 1'b1};
    assign rdy_clr_ = inst_cond != 7'b1010000;
    assign rdy_im_  = inst_cond[6:5] != 2'b11;
    assign rdy_tce_ = inst_cond != 7'b0001100;
    assign rdy_ts_  = {inst_cond[6], inst_cond[3:0]} != {1'b0, 4'b0000} || inst_cond[5:4] == 2'b00;
    assign rdy_add_ = inst_cond != 7'b1010110;
    assign rdy_sub_ = inst_cond != 7'b1010111;

endmodule

module accumulator_system (
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,
    input               select      , // Select input to choose between accu and top_module
    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out
);

    // Instantiate the accu module
    accu accu_inst (
        .clk(clk),
        .rst_n(rst_n),
        .data_in(data_in),
        .valid_in(valid_a),
        .ready_out(accu_ready),
        .data_out(accu_data_out)
    );

    // Instantiate the top_module
    top_module top_inst (
        .clk(clk),
        .rst_n(rst_n),
        .data_in(data_in),
        .valid_in(valid_a),
        .ready_out(top_ready),
        .data_out(top_data_out)
    );

    // Instantiate the adder module
    adder adder_inst (
        .clk(clk),
        .rst_n(rst_n),
        .data_in_1(accu_data_out),
        .data_in_2(top_data_out),
        .valid_in_1(accu_ready),
        .valid_in_2(top_ready),
        .ready_out(adder_ready),
        .data_out(adder_data_out)
    );

    // Select the output based on the select input
    always @ (posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            valid_b <= 0;
            data_out <= 0;
        end else begin
            if (select) begin
                valid_b <= adder_ready;
                data_out <= adder_data_out;
            end else begin
                valid_b <= accu_ready;
                data_out <= accu_data_out;
            end
        end
    end

    // Implement the valid-ready handshake mechanism
    assign ready_a = (select) ? adder_ready : accu_ready;
    assign top_inst.ready_a = (select) ? adder_ready : 1'b0;
    assign accu_inst.ready_a = (select) ? 1'b0 : accu_ready;
    always @ (posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            valid_b <= 0;
        end else begin
            if (valid_a && ready_b) begin
                valid_b <= 1;
            end
        end
    end

endmodule

// Define the accu module
module accu (
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_in    ,
    output              ready_out   ,
    output reg [9:0]    data_out
);

    // Define the pipeline register
    reg [9:0] accu_reg;

    // Define the valid-ready handshake signals
    reg accu_valid;
    wire accu_ready;

    // Implement the valid-ready handshake mechanism
    assign ready_out = accu_ready;
    always @ (posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            accu_valid <= 0;
        end else begin
            if (valid_in && accu_ready) begin
                accu_valid <= 1;
            end
        end
    end

    // Accumulate data using the pipeline register
    always @ (posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            accu_reg <= 0;
        end else begin
            if (accu_valid) begin
                accu_reg <= accu_reg + data_in;
            end
        end
    end

    // Separate the accumulation and output stages using the pipeline register
    always @ (posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_out <= 0;
        end else begin
            if (accu_ready) begin
                data_out <= accu_reg;
            end
        end
    end

endmodule

// Define the top_module
module top_module (
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_in    ,
    output              ready_a     ,
    output reg [9:0]    data_out
);

    // Define the 8-bit register and 4-bit binary counter
    reg [7:0] top_reg;
    reg [3:0] top_counter;

    // Define the valid-ready handshake signals
    reg top_valid;
    wire top_ready;

    // Implement the valid-ready handshake mechanism
    assign ready_a = top_ready;
    always @ (posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            top_valid <= 0;
        end else begin
            if (valid_in && top_ready) begin
                top_valid <= 1;
            end
        end
    end

    // Load data into the register and increment the counter
    always @ (posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            top_reg <= 0;
            top_counter <= 0;
        end else begin
            if (top_valid) begin
                top_reg <= data_in;
                top_counter <= top_counter + 1;
            end
        end
    end

    // Output the register data and counter value
    always @ (posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_out <= 0;
        end else begin
            if (top_ready) begin
                data_out <= {top_reg, top_counter};
            end
        end
    end

endmodule

// Define the adder module
module adder (
    input               clk         ,   
    input               rst_n       ,
    input       [9:0]   data_in_1   ,
    input       [9:0]   data_in_2   ,
    input               valid_in_1  ,
    input               valid_in_2  ,
    output              ready_out   ,
    output reg [9:0]    data_out
);

    // Define the valid-ready handshake signals
    reg adder_valid;
    wire adder_ready;

    // Implement the valid-ready handshake mechanism
    assign ready_out = adder_ready;
    always @ (posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            adder_valid <= 0;
        end else begin
            if (valid_in_1 && valid_in_2 && adder_ready) begin
                adder_valid <= 1;
            end
        end
    end

    // Add the two input data
    always @ (posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_out <= 0;
        end else begin
            if (adder_valid) begin
                data_out <= data_in_1 + data_in_2;
            end
        end
    end

endmodule

module spi_cell (
  input         A2F_ACK,
  output [ 7:0] A2F_ADDR,
  output [ 7:0] A2F_Control,
  input  [ 7:0] A2F_GP_IN,
  output [ 7:0] A2F_GP_OUT,
  input  [ 7:0] A2F_RD_DATA,
  output        A2F_REQ,
  output        A2F_RWn,
  input  [ 6:0] A2F_Status,
  output [ 7:0] A2F_WR_DATA,

  input         af_spi_cpha,
  input         af_spi_cpol,
  input         af_spi_lsbf,

  input         SPI_CLK,
  input         SPI_CLKS,
  output        SPI_MISO,
  output        SPI_MISOe,
  input         SPI_MOSI,
  input         SPI_SSn
);

  // Define internal registers
  reg [7:0] data_in;
  reg [7:0] data_out;
  reg [7:0] shift_reg;
  reg [2:0] shift_count;
  reg       spi_enabled;
  reg       spi_mode;
  reg       spi_lsb_first;
  reg       spi_clk_polarity;
  reg       spi_clk_phase;
  reg       spi_clk_idle;

  // Initialize internal registers
  initial begin
    data_in        = 8'h00;
    data_out       = 8'h00;
    shift_reg      = 8'h00;
    shift_count    = 3'b0;
    spi_enabled    = 1'b0;
    spi_mode       = 1'b0;
    spi_lsb_first  = 1'b0;
    spi_clk_polarity = 1'b0;
    spi_clk_phase  = 1'b0;
    spi_clk_idle   = 1'b1;
  end

  // Define state machine states
  localparam IDLE = 2'b00;
  localparam READ = 2'b01;
  localparam WRITE = 2'b10;

  // Define state machine signals
  reg [1:0] state;
  reg       shift_out;
  reg       shift_in;

  // Initialize state machine
  initial begin
    state = IDLE;
    shift_out = 1'b0;
    shift_in = 1'b0;
  end

  // Define SPI clock generator
  reg spi_clk;
  always @(posedge SPI_CLKS) begin
    spi_clk <= ~spi_clk;
  end

  // Define SPI clock phase generator
  reg spi_clk_phase_gen;
  always @(posedge spi_clk) begin
    spi_clk_phase_gen <= ~spi_clk_phase_gen;
  end

  // Define SPI clock polarity generator
  reg spi_clk_polarity_gen;
  always @(posedge spi_clk_phase_gen) begin
    spi_clk_polarity_gen <= spi_clk_polarity;
  end

  // Define SPI data generator
  reg spi_data_gen;
  always @(negedge spi_clk_phase_gen) begin
    if (shift_count == 0) begin
      spi_data_gen <= spi_lsb_first ? shift_reg[0] : shift_reg[7];
    end else if (shift_count == 1) begin
      spi_data_gen <= spi_lsb_first ? shift_reg[1] : shift_reg[6];
    end else if (shift_count == 2) begin
      spi_data_gen <= spi_lsb_first ? shift_reg[2] : shift_reg[5];
    end else if (shift_count == 3) begin
      spi_data_gen <= spi_lsb_first ? shift_reg[3] : shift_reg[4];
    end
  end

  // Define SPI data input
  reg spi_data_in;
  always @(posedge spi_clk_phase_gen) begin
    if (spi_enabled && shift_count < 4) begin
      spi_data_in <= SPI_MOSI;
    end
  end

  // Define SPI data output
  assign SPI_MISO = spi_enabled ? spi_data_gen : 1'b1;
  assign SPI_MISOe = spi_enabled;

  // Define state machine
  always @(posedge SPI_CLK) begin
    case (state)
      IDLE: begin
        if (!spi_enabled && !SPI_SSn) begin
          spi_enabled <= 1'b1;
          spi_mode <= af_spi_cpha && af_spi_cpol;
          spi_lsb_first <= af_spi_lsbf;
          spi_clk_polarity <= af_spi_cpol;
          spi_clk_phase <= af_spi_cpha;
          spi_clk_idle <= 1'b0;
          state <= READ;
        end else if (spi_enabled && SPI_SSn) begin
          spi_enabled <= 1'b0;
          spi_clk_idle <= 1'b1;
        end
      end
      READ: begin
        A2F_ADDR <= 8'h00;
        A2F_Control <= 8'h00;
        A2F_GP_OUT <= 8'h00;
        A2F_REQ <= 1'b0;
        A2F_RWn <= 1'b1;
        A2F_WR_DATA <= 8'h00;

        if (spi_enabled && !SPI_SSn) begin
          if (shift_count == 3) begin
            shift_reg <= data_in;
            shift_count <= 0;
            state <= WRITE;
          end else begin
            shift_reg <= {shift_reg[6:0], spi_data_in};
            shift_count <= shift_count + 1;
          end
        end else if (!spi_enabled && !SPI_SSn) begin
          spi_enabled <= 1'b1;
          spi_mode <= af_spi_cpha && af_spi_cpol;
          spi_lsb_first <= af_spi_lsbf;
          spi_clk_polarity <= af_spi_cpol;
          spi_clk_phase <= af_spi_cpha;
          spi_clk_idle <= 1'b0;
        end else if (spi_enabled && SPI_SSn) begin
          spi_enabled <= 1'b0;
          spi_clk_idle <= 1'b1;
          state <= IDLE;
        end
      end
      WRITE: begin
        if (spi_enabled && !SPI_SSn) begin
          if (shift_count == 3) begin
            data_out <= shift_reg;
            shift_count <= 0;
            state <= READ;
          end else begin
            shift_count <= shift_count + 1;
          end
        end else if (!spi_enabled && !SPI_SSn) begin
          spi_enabled <= 1'b1;
          spi_mode <= af_spi_cpha && af_spi_cpol;
          spi_lsb_first <= af_spi_lsbf;
          spi_clk_polarity <= af_spi_cpol;
          spi_clk_phase <= af_spi_cpha;
          spi_clk_idle <= 1'b0;
        end else if (spi_enabled && SPI_SSn) begin
          spi_enabled <= 1'b0;
          spi_clk_idle <= 1'b1;
          state <= IDLE;
        end
      end
    endcase
  end

  // Define output signals
  assign A2F_GP_OUT = data_out;
  assign A2F_REQ = spi_enabled && spi_clk_idle;
  assign A2F_RWn = spi_mode;
  assign A2F_WR_DATA = data_in;

endmodule

module pulse_generator(
  input clk,
  output reg pulse
);

  reg [4:0] counter = 0;

  always @(posedge clk) begin
    if (counter == 4'b10000) begin
      counter <= 0;
      pulse <= 1;
    end else if (counter == 4'b00000) begin
      pulse <= 0;
      counter <= counter + 1;
    end else begin
      pulse <= 0;
      counter <= counter + 1;
    end
  end

endmodule

module fifo_buffer
#(parameter WIDTH = 4, DEPTH = 8)
(
    input clk,
    input rst,
    input en,
    input wr,
    input [WIDTH-1:0] data_in,
    output reg rd,
    output reg [WIDTH-1:0] data_out,
    output reg empty,
    output reg full
);

reg [WIDTH-1:0] buffer [DEPTH-1:0];
reg [WIDTH-1:0] write_pointer, read_pointer;
reg [3:0] count;

always @(posedge clk) begin
    if (rst) begin
        write_pointer <= 0;
        read_pointer <= 0;
        count <= 0;
        rd <= 0;
        data_out <= 0;
        empty <= 1;
        full <= 1;
    end else if (en) begin
        if (wr && !full) begin
            buffer[write_pointer] <= data_in;
            write_pointer <= (write_pointer == DEPTH-1) ? 0 : write_pointer + 1;
            count <= count + 1;
        end else if (rd && !empty) begin
            data_out <= buffer[read_pointer];
            read_pointer <= (read_pointer == DEPTH-1) ? 0 : read_pointer + 1;
            count <= count - 1;
        end
        rd <= (count > 0) ? 1 : 0;
        empty <= (count == 0) ? 1 : 0;
        full <= (count == DEPTH) ? 1 : 0;
    end
end

endmodule

