module calculator (
    input clk,
    input rst,
    input signed [15:0] operand1,
    input signed [15:0] operand2,
    input [1:0] operation,
    output reg signed [15:0] result,
    output reg overflow,
    output reg underflow,
    output reg divide_by_zero
);

    always @(*) begin
        case (operation)
            2'b00: // addition
                result = operand1 + operand2;
            2'b01: // subtraction
                result = operand1 - operand2;
            2'b10: // multiplication
                result = operand1 * operand2;
            2'b11: // division
                if (operand2 == 0) begin
                    result = 16'sd0;
                    divide_by_zero = 1;
                end else begin
                    result = operand1 / operand2;
                    divide_by_zero = 0;
                end
        endcase

        // Check for overflow and underflow
        if ((result[15] == operand1[15]) && (result[15] != operand2[15])) begin
            // operands have same sign, result has different sign
            if (operation == 2'b00 || operation == 2'b01) begin
                // addition or subtraction
                if (result[15] == 1) begin
                    overflow = 1;
                    underflow = 0;
                end else begin
                    overflow = 0;
                    underflow = 1;
                end
            end else begin
                // multiplication or division
                overflow = 1;
                underflow = 0;
            end
        end else if ((result[15] != operand1[15]) && (result[15] == operand2[15])) begin
            // operands have different signs, result has operand2's sign
            if (operation == 2'b00 || operation == 2'b01) begin
                // addition or subtraction
                overflow = 0;
                underflow = 1;
            end else begin
                // multiplication or division
                overflow = 1;
                underflow = 0;
            end
        end else begin
            // no overflow or underflow
            overflow = 0;
            underflow = 0;
        end
    end

endmodule

