module d_ff_async_reset_set (
    Q      ,
    Q_N    ,
    D      ,
    CLK_N  ,
    SET_B  ,
    RESET_B,
    VPWR   ,
    VGND   ,
    VPB    ,
    VNB
);

    // Module ports
    output Q      ;
    output Q_N    ;
    input  D      ;
    input  CLK_N  ;
    input  SET_B  ;
    input  RESET_B;
    input  VPWR   ;
    input  VGND   ;
    input  VPB    ;
    input  VNB    ;

    // Local signals
    wire RESET          ;
    wire SET            ;
    wire CLK            ;
    wire buf_Q          ;
    wire CLK_N_delayed  ;
    wire RESET_B_delayed;
    wire SET_B_delayed  ;
    reg  notifier       ;
    wire D_delayed      ;
    wire awake          ;
    wire cond0          ;
    wire cond1          ;
    wire condb          ;

    // Delayed versions of inputs
    sky130_fd_sc_hd__inv_x1 inv0 (CLK_N_delayed, CLK_N);
    sky130_fd_sc_hd__inv_x1 inv1 (SET_B_delayed, SET_B);
    sky130_fd_sc_hd__inv_x1 inv2 (RESET_B_delayed, RESET_B);
    sky130_fd_sc_hd__inv_x1 inv3 (D_delayed, D);

    // Not gates
    not not0 (RESET, RESET_B_delayed);
    not not1 (SET, SET_B_delayed);
    not not2 (CLK, CLK_N_delayed);
    not not3 (Q_N, buf_Q);

    // D flip-flop
    sky130_fd_sc_ls__udp_dff$NSR_pp$PG$N dff0 (
        .D(D_delayed),
        .CLK(CLK),
        .SET(SET),
        .RESET(RESET),
        .Q(buf_Q),
        .notifier(notifier),
        .VPWR(VPWR),
        .VGND(VGND)
    );

    // Awake condition
    assign awake = (VPWR === 1'b1);

    // Condition for reset
    assign cond0 = (awake && (RESET_B_delayed === 1'b1));

    // Condition for set
    assign cond1 = (awake && (SET_B_delayed === 1'b1));

    // Condition for both set and reset
    assign condb = (cond0 & cond1);

    // Buffer for Q output
    buf buf0 (Q, buf_Q);

endmodule

