module freq_trigger (
    input clk,
    input reset,
    input enable,
    input ddc_out_strobe,
    input [31:0] ddc_out_sample,
    input freq_trigger_enable,
    input [31:0] freq_trigger_threshold,
    output [31:0] bb_sample,
    output bb_strobe,
    output freq_triggered
);

    //leave frontend tied to existing ddc chain
    assign ddc_in_i = frontend_i;
    assign ddc_in_q = frontend_q;

    //ddc enable remains tied to global enable
    assign ddc_out_enable = enable;

    //below we implement a power trigger and a frequency trigger between baseband samples and ddc output...

   reg [8:0] 	  wr_addr;
   wire [8:0] 	  rd_addr;
   reg 		  triggered, triggerable;
   wire 	  power_trigger, freq_trigger;

   wire [31:0] 	  delayed_sample;
   wire [31:0] 	  power_thresh, freq_thresh;

   setting_reg #(.my_addr(BASE+0)) sr_0
     (.clk(clk),.rst(reset),.strobe(set_stb),.addr(set_addr),
      .in(set_data),.out(power_thresh),.changed());

   assign rd_addr = wr_addr + 1; // FIXME adjustable delay

   ram_2port  #(.DWIDTH(32),.AWIDTH(9)) delay_line
     (.clka(clk),.ena(1),.wea(ddc_out_strobe),.addra(wr_addr),.dia(ddc_out_sample),.doa(),
      .clkb(clk),.enb(ddc_out_strobe),.web(1'b0),.addrb(rd_addr),.dib(32'hFFFF),.dob(delayed_sample));

   always @(posedge clock)
     if(reset | ~enable)
       wr_addr <= 0;
     else
       if(ddc_out_strobe)
	 wr_addr <= wr_addr + 1;

   always @(posedge clock)
     if(reset | ~enable)
       triggerable <= 0;
     else if(wr_addr == 9'h1FF)  // Wait till we're nearly full
       triggerable <= 1;


   reg 			      stb_d1, stb_d2;
   always @(posedge clock) stb_d1 <= ddc_out_strobe;
   always @(posedge clock) stb_d2 <= stb_d1;

   assign bb_sample = delayed_sample;
   assign bb_strobe = stb_d1 & (power_trigger | freq_trigger);

   // Compute Mag
   wire [17:0] 		      mult_in = stb_d1 ? { ddc_out_sample[15],ddc_out_sample[15:0], 1'b0 } : 
			      { ddc_out_sample[31], ddc_out_sample[31:16], 1'b0 };
   wire [35:0] 		      prod;
   reg [31:0] 		      sum;

   MULT18X18S mult (.P(prod), .A(mult_in), .B(mult_in), .C(clock), .CE(ddc_out_strobe | stb_d1), .R(reset) );

   always @(posedge clock)
     if(stb_d1)
       sum <= prod[35:4];
     else if(stb_d2)
       sum <= sum + prod[35:4];

   always @(posedge clock)
     if(reset | ~enable | ~triggerable)
       triggered <= 0;
     else if(power_trigger)
       triggered <= 1;

   assign power_trigger = (sum > power_thresh);

   reg [31:0] sign_count;
   reg sign_d1, sign_d2;
   always @(posedge clock)
     if(reset | ~enable)
       sign_count <= 0;
     else if(stb_d1)
       if(sign_d1 ^ sign_d2)
         sign_count <= sign_count + 1;
   always @(posedge clock) sign_d1 <= (ddc_out_sample[31] == 1'b1);
   always @(posedge clock) sign_d2 <= sign_d1;

   assign freq_trigger = (sign_count > freq_trigger_threshold);

   always @(posedge clock)
     if(power_trigger)
       sign_count <= 0;

   assign freq_triggered = freq_trigger;

endmodule

