module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] binary_in, // 8-bit binary input
    input [1:0] select, // Select input to choose between barrel shifter and binary-to-BCD converter
    output reg [3:0] bcd_out1, // 4-bit BCD output 1
    output reg [3:0] bcd_out2, // 4-bit BCD output 2
    output reg [3:0] bcd_out3, // 4-bit BCD output 3
    output reg [3:0] bcd_out4 // 4-bit BCD output 4
);

wire [7:0] barrel_out;
wire [15:0] bcd;

barrel_shifter bs (
    .DATA_IN(binary_in),
    .SHIFT(select),
    .DATA_OUT(barrel_out)
