    if (reset) begin
        bcd_out1 <= 4'b0;
        bcd_out2 <= 4'b0;
        bcd_out3 <= 4'b0;
        bcd_out4 <= 4'b0;
    end else begin
        bcd_out1 <= bcd[3:0];
        bcd_out2 <= bcd[7:4];
        bcd_out3 <= bcd[11:8];
        bcd_out4 <= bcd[15:12];
