module barrel_shifter (
    input [7:0] DATA_IN,
    input [1:0] SHIFT,
    output reg [7:0] DATA_OUT
);

always @(*) begin
    case (SHIFT)
        2'b00: DATA_OUT = DATA_IN;
        2'b01: DATA_OUT = DATA_IN >> 1;
        2'b10: DATA_OUT = DATA_IN << 1;
        2'b11: DATA_OUT = {DATA_IN[0], DATA_IN[7:1]};
        default: DATA_OUT = DATA_IN;
    endcase
end

endmodule

module binary_to_bcd (
    input [7:0] binary_in,
    output reg [15:0] bcd_out
);

integer i;

always @(*) begin
    bcd_out = 16'b0;
    for (i = 0; i < 8; i = i + 1) begin
        if (bcd_out[3:0] >= 5) begin
            bcd_out[3:0] = bcd_out[3:0] + 3;
        end
        if (bcd_out[7:4] >= 5) begin
            bcd_out[7:4] = bcd_out[7:4] + 3;
        end
        if (bcd_out[11:8] >= 5) begin
            bcd_out[11:8] = bcd_out[11:8] + 3;
        end
        if (bcd_out[15:12] >= 5) begin
            bcd_out[15:12] = bcd_out[15:12] + 3;
        end
        bcd_out = bcd_out << 1;
        bcd_out[0] = binary_in[7 - i];
    end
end

endmodule

module FSM (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 4; // number of input signals
parameter m = 2; // number of output signals
parameter s1 = 3; // number of states in the original encoding
parameter s2 = 4; // number of states in the new encoding

reg [s1-1:0] state1; // current state in original encoding
reg [s2-1:0] state2; // current state in new encoding

// Define state encoding mapping table
// Original encoding: 0 1 2
// New encoding:      0 2 1 3
parameter [s1-1:0] state_map = {3'b000, 3'b010, 3'b001};

// Define state transition and output generation functions
always @ (state1 or in) begin
  case (state1)
    0: begin // State 0
      if (in[0] && !in[1]) begin
        state1 <= 1;
        state2 <= state_map[1];
        out <= {1'b1, 1'b0};
      end else if (!in[0] && in[1]) begin
        state1 <= 2;
        state2 <= state_map[2];
        out <= {1'b0, 1'b1};
      end else begin
        state1 <= 0;
        state2 <= state_map[0];
        out <= {1'b0, 1'b0};
      end
    end
    1: begin // State 1
      if (!in[0] && in[1]) begin
        state1 <= 0;
        state2 <= state_map[0];
        out <= {1'b1, 1'b1};
      end else if (in[0] && in[1]) begin
        state1 <= 2;
        state2 <= state_map[2];
        out <= {1'b1, 1'b0};
      end else begin
        state1 <= 1;
        state2 <= state_map[1];
        out <= {1'b0, 1'b0};
      end
    end
    2: begin // State 2
      if (in[0] && !in[1]) begin
        state1 <= 0;
        state2 <= state_map[0];
        out <= {1'b1, 1'b0};
      end else if (in[0] && in[1]) begin
        state1 <= 1;
        state2 <= state_map[1];
        out <= {1'b0, 1'b1};
      end else begin
        state1 <= 2;
        state2 <= state_map[2];
        out <= {1'b0, 1'b0};
      end
    end
  endcase
end

endmodule

module shift_add (
    input [3:0] A,
    input [3:0] B,
    input select,
    input data_in,
    input shift,
    input clk,
    output reg [3:0] q
);

reg [3:0] shift_reg;
wire [3:0] adder_out;

// Instantiate the shift register and the ripple carry adder
shift_register shift_reg_inst (
    .data_in(data_in),
    .shift(shift),
    .clk(clk),
    .q(shift_reg)
);

ripple_carry_adder adder_inst (
    .A(A),
    .B(B),
    .Cin(select),
    .S(adder_out),
    .Cout()
);

// Output either the shift register output or the adder output based on the select input
always @ (posedge clk) begin
    if (select) begin
        q <= adder_out;
    end else begin
        q <= shift_reg;
    end
end

endmodule

