module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output reg [3:0] S,
    output Cout
);

wire [3:0] sum;
wire [3:0] carry;

// Generate the sum and carry signals using full adders
full_adder fa0 (.A(A[0]), .B(B[0]), .Cin(Cin), .S(sum[0]), .Cout(carry[0]));
full_adder fa1 (.A(A[1]), .B(B[1]), .Cin(carry[0]), .S(sum[1]), .Cout(carry[1]));
full_adder fa2 (.A(A[2]), .B(B[2]), .Cin(carry[1]), .S(sum[2]), .Cout(carry[2]));
full_adder fa3 (.A(A[3]), .B(B[3]), .Cin(carry[2]), .S(sum[3]), .Cout(Cout));

assign S = sum;

endmodule

module full_adder (
    input A,
    input B,
    input Cin,
    output reg S,
    output Cout
);

always @ (A or B or Cin) begin
    S = A ^ B ^ Cin;
    Cout = (A & B) | (Cin & (A ^ B));
end

endmodule

module restoring_divider (
    input [3:0] dividend,
    input [3:0] divisor,
    output reg [3:0] quotient,
    output reg [3:0] remainder
);

reg [7:0] dividend_reg;
reg [3:0] divisor_reg;
reg [3:0] quotient_reg;
reg [3:0] remainder_reg;
reg [2:0] state;

always @(*) begin
    case(state)
        0: begin
            dividend_reg = {dividend, 4'b0};
            divisor_reg = {divisor, 2'b0};
            quotient_reg = 4'b0;
            remainder_reg = dividend;
            state = 1;
        end
        1: begin
            if(dividend_reg[7] == 1) begin
                dividend_reg = dividend_reg - divisor_reg;
                quotient_reg = quotient_reg + 1;
            end
            state = 2;
        end
        2: begin
            if(dividend_reg[7] == 1) begin
                dividend_reg = dividend_reg + divisor_reg;
                quotient_reg = quotient_reg - 1;
            end
            state = 3;
        end
        3: begin
            dividend_reg = dividend_reg << 1;
            quotient_reg = quotient_reg << 1;
            remainder_reg = dividend_reg[7:4];
            if(quotient_reg[3:0] == divisor) begin
                quotient = quotient_reg;
                remainder = remainder_reg;
                state = 0;
            end else begin
                state = 1;
            end
        end
    endcase
end

endmodule

