module calculator (
    input clk,
    input reset, // Synchronous active-high reset
    input signed [3:0] A,
    input signed [3:0] B,
    input select, // Select input to choose between adder and multiplier
    output reg [7:0] out
);

    reg signed [7:0] add_out;
    reg signed [7:0] mult_out;
    reg [3:0] cmp_out;
    reg signed [7:0] and_out;
    reg signed [7:0] result;

    // Adder module
    always @ (posedge clk) begin
        if (reset) begin
            add_out <= 0;
        end else begin
            add_out <= A + B;
        end
    end

    // Multiplier module
    always @ (posedge clk) begin
        if (reset) begin
            mult_out <= 0;
        end else begin
            mult_out <= A * B;
        end
    end

    // Control logic module
    always @ (posedge clk) begin
        if (reset) begin
            result <= 0;
        end else begin
            if (select) begin
                result <= mult_out;
            end else begin
                result <= add_out;
            end
        end
    end

    // Comparator module
    always @ (posedge clk) begin
        if (reset) begin
            cmp_out <= 0;
        end else begin
            if (result > 8'h7F) begin
                cmp_out <= 4'b0001; // Greater than
            end else if (result < 8'h7F) begin
                cmp_out <= 4'b0010; // Less than
            end else begin
                cmp_out <= 4'b0100; // Equal to
            end
        end
    end

    // Bitwise AND module
    always @ (posedge clk) begin
        if (reset) begin
            and_out <= 0;
        end else begin
            and_out <= {cmp_out, result[7:0]} & 8'hF0;
        end
    end

    // Output module
    always @ (posedge clk) begin
        if (reset) begin
            out <= 0;
        end else begin
            if (and_out[7]) begin
                out <= {and_out[7], and_out[6], and_out[5], and_out[4], and_out[3], and_out[2], and_out[1], 1'b0};
            end else begin
                out <= {and_out[6], and_out[5], and_out[4], and_out[3], and_out[2], and_out[1], and_out[0], 1'b0};
            end
        end
    end

endmodule

