module register (
  input clk,
  input reset,
  input [15:0] data,
  output reg [15:0] reg_out
);

  always @(posedge clk) begin
    if (reset) begin
      reg_out <= 16'h00;
    end else begin
      reg_out <= data;
    end
  end

endmodule

module edge_detector (
  input clk,
  input reset,
  input [15:0] data,
  output reg [15:0] edge
);

  reg [15:0] prev_data;

  always @(posedge clk) begin
    if (reset) begin
      edge <= 16'h0000;
      prev_data <= 16'h0000;
    end else begin
      edge <= (data & ~prev_data);
      prev_data <= data;
    end
  end

endmodule

module counter (
  input clk,
  input reset,
  input [15:0] data,
  output reg [7:0] count
);

  reg [15:0] prev_data;

  always @(posedge clk) begin
    if (reset) begin
      count <= 8'h00;
      prev_data <= 16'h0000;
    end else begin
      if (data > prev_data) begin
        count <= count + 1;
      end
      prev_data <= data;
    end
  end

endmodule

module functional (
  input clk,
  input reset,
  input [15:0] data,
  output reg [7:0] final_output
);

  wire [15:0] edge;
  wire [7:0] count;

  register reg_inst (
    .clk(clk),
    .reset(reset),
    .data(data),
    .reg_out(edge)
  );

  edge_detector edge_inst (
    .clk(clk),
    .reset(reset),
    .data(data),
    .edge(edge)
  );

  counter count_inst (
    .clk(clk),
    .reset(reset),
    .data(data),
    .count(count)
  );

  always @(posedge clk) begin
    if (reset) begin
      final_output <= 8'h00;
    end else begin
      final_output <= count & edge[15:8];
    end
  end

endmodule

