module etx_arbiter (
   // Outputs
   txwr_wait, txrd_wait, txrr_wait, etx_access, etx_packet, etx_rr,
   // Inputs
   clk, reset, txwr_access, txwr_packet, txrd_access, txrd_packet,
   txrr_access, txrr_packet, etx_rd_wait, etx_wr_wait, etx_cfg_wait,
   ctrlmode_bypass, ctrlmode
   );

   // Parameter definitions
   parameter PW = 104;
   parameter ID = 0;

   // Input definitions
   input clk;
   input reset;
   input txwr_access;
   input [PW-1:0] txwr_packet;
   input txrd_access;
   input [PW-1:0] txrd_packet;
   input txrr_access;
   input [PW-1:0] txrr_packet;
   input etx_rd_wait;
   input etx_wr_wait;
   input etx_cfg_wait;
   input ctrlmode_bypass;
   input [3:0] ctrlmode;

   // Output definitions
   output txwr_wait;
   output txrd_wait;
   output txrr_wait;
   output etx_access;
   output [PW-1:0] etx_packet;
   output etx_rr;

   // Register definitions
   reg etx_access;
   reg [PW-1:0] etx_packet;
   reg etx_rr;

   // Wire definitions
   wire [3:0] txrd_ctrlmode;
   wire [3:0] txwr_ctrlmode;
   wire access_in;   
   wire [PW-1:0] etx_packet_mux;
   wire txrr_grant;
   wire txrd_grant;
   wire txwr_grant;
   wire txrr_arb_wait;
   wire txrd_arb_wait;
   wire txwr_arb_wait;
   wire [PW-1:0] txrd_data;
   wire [PW-1:0] txwr_data;
   wire [PW-1:0] etx_mux;
   wire write_in;

   // Control mode for read/write transactions
   assign txrd_ctrlmode[3:0] = ctrlmode_bypass ? ctrlmode[3:0] : txrd_packet[7:4];
   assign txrd_data[PW-1:0] = {txrd_packet[PW-1:8], txrd_ctrlmode[3:0], txrd_packet[3:0]};

   assign txwr_ctrlmode[3:0] = ctrlmode_bypass ? ctrlmode[3:0] : txwr_packet[7:4];
   assign txwr_data[PW-1:0] = {txwr_packet[PW-1:8], txwr_ctrlmode[3:0], txwr_packet[3:0]};

   // Arbiter
   arbiter_priority #(.ARW(3)) arbiter (
      .grant({txrr_grant, txrd_grant, txwr_grant}),
      .await({txrr_arb_wait, txrd_arb_wait, txwr_arb_wait}),	
      .request({txrr_access, txrd_access, txwr_access})	
   );

   // Priority Mux
   assign etx_mux[PW-1:0] = ({(PW){txwr_grant}} & txwr_data[PW-1:0]) |
                            ({(PW){txrd_grant}} & txrd_data[PW-1:0]) |
                            ({(PW){txrr_grant}} & txrr_packet[PW-1:0]);

   // Pushback (stall) Signals
   assign txwr_wait = etx_wr_wait | etx_cfg_wait;

   assign txrd_wait = etx_rd_wait | etx_cfg_wait | txrd_arb_wait;

   assign txrr_wait = etx_wr_wait | etx_cfg_wait | txrr_arb_wait;

   // Pipeline stage (arbiter+mux takes time..)
   assign access_in = (txwr_grant & ~txwr_wait) |
                      (txrd_grant & ~txrd_wait) |
                      (txrr_grant & ~txrr_wait);

   assign write_in = etx_mux[1];

   // Access
   always @ (posedge clk) begin
      if (reset) begin
         etx_access <= 1'b0;   
         etx_rr <= 1'b0;	   
      end
      else if (access_in & (write_in & ~etx_wr_wait) | (~write_in & ~etx_rd_wait)) begin
         etx_access <= access_in;
         etx_rr <= txrr_grant;
      end	   
   end

   // Packet
   always @ (posedge clk) begin
      if (access_in & (write_in & ~etx_wr_wait) | (~write_in & ~etx_rd_wait)) begin
         etx_packet[PW-1:0] <= etx_mux[PW-1:0];	 
      end
   end

endmodule

