module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

    wire [3:0] sum;
    wire [3:0] carry;

    assign sum = A + B + Cin;
    assign Cout = carry[3];

    assign carry[0] = (A[0] & B[0]) | (Cin & A[0]) | (Cin & B[0]);
    assign carry[1] = (A[1] & B[1]) | (carry[0] & A[1]) | (carry[0] & B[1]);
    assign carry[2] = (A[2] & B[2]) | (carry[1] & A[2]) | (carry[1] & B[2]);
    assign carry[3] = (A[3] & B[3]) | (carry[2] & A[3]) | (carry[2] & B[3]);

    assign S = sum;

endmodule

module up_down_counter (
    input clk,
    input reset,
    input up_down,
    output reg [2:0] count,
    output max_reached
);

    reg [2:0] next_count;

    always @ (posedge clk or posedge reset) begin
        if (reset) begin
            count <= 3'b0;
        end else begin
            if (up_down) begin
                next_count <= count + 1;
            end else begin
                next_count <= count - 1;
            end
            count <= next_count;
        end
    end

    assign max_reached = (count == 3'b111);

endmodule

