module booth_multiplier (
  input clk,
  input reset,
  input start,
  input [15:0] A,
  input [15:0] B,
  output reg [31:0] P,
  output reg done
);

  reg [15:0] A_reg;
  reg [15:0] B_reg;
  reg [1:0] state;
  reg [4:0] count;
  reg [31:0] P_reg;
  wire [15:0] B_comp;
  wire [31:0] P_comp;

  assign B_comp = ~B + 1;
  assign P_comp = { {16{P_reg[31]}} , P_reg } + { {16{B_reg[15]}} , B_comp };

  always @(posedge clk) begin
    if (reset) begin
      state <= 2'b00;
      count <= 5'd0;
      P_reg <= 32'd0;
      done <= 1'b0;
    end else begin
      case (state)
        2'b00: begin // Idle state, waiting for start signal
          if (start) begin
            A_reg <= A;
            B_reg <= B;
            state <= 2'b01;
          end
        end
        2'b01: begin // Booth's algorithm state
          if (count < 5'd16) begin
            if (B_reg[0] == 1 && P_reg[0] == 0) begin
              P_reg <= P_reg + { {16{A_reg[15]}} , A_reg };
            end else if (B_reg[0] == 0 && P_reg[0] == 1) begin
              P_reg <= P_reg - { {16{A_reg[15]}} , A_reg };
            end
            B_reg <= { B_reg[15], B_reg[15:1] };
            count <= count + 1;
          end else begin
            state <= 2'b10;
          end
        end
        2'b10: begin // Output state
          P <= P_comp;
          done <= 1'b1;
          state <= 2'b00;
        end
        default: begin
          state <= 2'b00;
        end
      endcase
    end
  end
endmodule

module float_to_double(
        input_a,
        input_a_stb,
        output_z_ack,
        clk,
        rst,
        output_z,
        output_z_stb,
        input_a_ack);

  input     clk;
  input     rst;

  input     [31:0] input_a;
  input     input_a_stb;
  output    input_a_ack;

  output    [63:0] output_z;
  output    output_z_stb;
  input     output_z_ack;

  reg       s_output_z_stb;
  reg       [63:0] s_output_z;
  reg       s_input_a_ack;

  reg       [1:0] state;
  parameter get_a         = 2'd0,
            convert_0     = 2'd1,
            normalise_0   = 2'd2,
            put_z         = 2'd3;

  reg [63:0] z;
  reg [10:0] z_e;
  reg [52:0] z_m;
  reg [31:0] a;

  always @(posedge clk)
  begin

    case(state)

      get_a:
      begin
        s_input_a_ack <= 1;
        if (s_input_a_ack && input_a_stb) begin
          a <= input_a;
          s_input_a_ack <= 0;
          state <= convert_0;
        end
      end

      convert_0:
      begin
        z[63] <= a[31];
        z[62:52] <= (a[30:23] - 127) + 1023;
        z[51:0] <= {a[22:0], 29'd0};
        if (a[30:23] == 255) begin
            z[62:52] <= 2047;
        end
        state <= put_z;
        if (a[30:23] == 0) begin
            if (a[23:0]) begin
                state <= normalise_0;
                z_e <= 897;
                z_m <= {1'd0, a[22:0], 29'd0};
            end
            z[62:52] <= 0;
        end
      end

      normalise_0:
      begin
        if (z_m[52]) begin
          z[62:52] <= z_e;
          z[51:0] <= z_m[51:0];
          state <= put_z;
        end else begin
          z_m <= {z_m[51:0], 1'd0};
          z_e <= z_e - 1;
        end
      end

      put_z:
      begin
        s_output_z_stb <= 1;
        s_output_z <= z;
        if (s_output_z_stb && output_z_ack) begin
          s_output_z_stb <= 0;
          state <= get_a;
        end
      end

    endcase

    if (rst == 1) begin
      state <= get_a;
      s_input_a_ack <= 0;
      s_output_z_stb <= 0;
    end

  end
  assign input_a_ack = s_input_a_ack;
  assign output_z_stb = s_output_z_stb;
  assign output_z = s_output_z;

endmodule

module counter (
   input       c0,
   input       c1,
   input       reset,
   input       check
   );

   integer p0 = 0;
   integer p1 = 0;
   integer p01 = 0;
   integer n0 = 0;
   integer n1 = 0;
   integer n01 = 0;

   always @ (posedge c0) begin
      p0 = p0 + 1;  // Want blocking, so don't miss clock counts
   end
   always @ (posedge c1) begin
      p1 = p1 + 1;
   end
   always @ (posedge c0 or posedge c1) begin
      p01 = p01 + 1;
   end
   always @ (negedge c0) begin
      n0 = n0 + 1;
   end
   always @ (negedge c1) begin
      n1 = n1 + 1;
   end
   always @ (negedge c0 or negedge c1) begin
      n01 = n01 + 1;
   end

   always @ (posedge reset) begin
      p0 = 0;
      p1 = 0;
      p01 = 0;
      n0 = 0;
      n1 = 0;
      n01 = 0;
   end

   always @ (posedge check) begin
      if (p0!=4) $stop;
      if (p1!=4) $stop;
      if (p01!=6) $stop;
      if (n0!=4) $stop;
      if (n1!=4) $stop;
      if (n01!=6) $stop;
      $write("*-* All Finished *-*\n");
   end

endmodule

