    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [31:0]  data_out
);

reg [7:0] data_reg [3:0];
reg [31:0] acc_reg [2:0];
reg [1:0] stage;

assign ready_a = (stage == 2) ? 1'b1 : 1'b0;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        data_reg <= 0;
        acc_reg <= 0;
        stage <= 0;
        valid_b <= 0;
        data_out <= 0;
    end else begin
        case (stage)
            0: begin
                if (valid_a) begin
                    data_reg[0] <= data_in;
                    stage <= 1;
                end
            end
            1: begin
                if (valid_a) begin
                    data_reg[1] <= data_reg[0];
                    data_reg[0] <= data_in;
                    stage <= 2;
                end
            end
            2: begin
                acc_reg[0] <= acc_reg[0] + {data_reg[1], data_reg[0]};
                stage <= 3;
            end
            3: begin
                acc_reg[1] <= acc_reg[1] + acc_reg[0];
                stage <= 4;
            end
            4: begin
                acc_reg[2] <= acc_reg[2] + acc_reg[1];
                stage <= 0;
                valid_b <= 1;
                data_out <= acc_reg[2];
            end
        endcase
    end
end

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        valid_b <= 0;
    end else begin
        if (valid_b && ready_b) begin
            valid_b <= 0;
        end
    end
end

endmodule

module decalper_eb_ot_sdeen_pot_pi_dehcac_xnilix(clk, srst, din, wr_en, rd_en, dout, full, empty);
  input clk;
  input srst;
  input [63:0]din;
  input wr_en;
  input rd_en;
  output [63:0]dout;
  output full;
  output empty;

  reg [63:0] buffer [0:15];
  reg [3:0] head = 0;
  reg [3:0] tail = 0;
  reg [3:0] count = 0;

  always @(posedge clk) begin
    if (srst) begin
      head <= 0;
      tail <= 0;
      count <= 0;
    end else begin
      if (wr_en && !full) begin
        buffer[head] <= din;
        head <= head + 1;
        count <= count + 1;
      end
      if (rd_en && !empty) begin
        dout <= buffer[tail];
        tail <= tail + 1;
        count <= count - 1;
      end
    end
  end

  assign full = (count == 16);
  assign empty = (count == 0);

endmodule

module adder_4bit(a, b, cin, sum, cout);
  input [3:0] a, b;
  input cin;
  output [3:0] sum;
  output cout;

  wire c1, c2, c3;

  assign c1 = a[0] & b[0];
  assign c2 = a[0] ^ b[0];
  assign sum[0] = c2 ^ cin;
  assign c3 = c1 | (c2 & cin);

  assign c1 = a[1] & b[1];
  assign c2 = a[1] ^ b[1];
  assign sum[1] = c2 ^ c3;
  assign c3 = c1 | (c2 & c3);

  assign c1 = a[2] & b[2];
  assign c2 = a[2] ^ b[2];
  assign sum[2] = c2 ^ c3;
  assign c3 = c1 | (c2 & c3);

  assign c1 = a[3] & b[3];
  assign c2 = a[3] ^ b[3];
  assign sum[3] = c2 ^ c3;
  assign cout = c1 | (c2 & c3);
endmodule

module top_module (
