module downsampler #(
  parameter in0N = 8,
  parameter out1N = 4,
  parameter out0N = 6
)(
  input wire clk,
  input wire rst,
  input wire in0_valid,
  input wire in0_ready,
  input wire [in0N-1:0] in0,
  output wire out0_valid,
  output wire out_valid,
  output wire [out0N-1:0] out0,
  output wire out1,
  output wire out1_valid,
  input wire out0_ready,
  input wire out_ready
);

    reg [out1N-1:0] counter;
    wire [out0N-1:0] downsampled;
    assign downsampled = in0 >> out1N;
    assign out0 = downsampled;
    assign out1 = in0;

    always @(posedge clk, posedge rst) begin
        if (rst) begin
            counter <= 0;
            out0_valid <= 0;
            out1_valid <= 0;
            out_valid <= 0;
        end else begin
            if (in0_valid && out_ready && out0_ready) begin
                counter <= counter + 1;
                if (counter == out1N-1) begin
                    counter <= 0;
                    out1_valid <= 1;
                end else begin
                    out1_valid <= 0;
                end
                out0_valid <= 1;
                out_valid <= 1;
            end else begin
                out0_valid <= 0;
                out1_valid <= 0;
                out_valid <= 0;
            end
        end
    end

    assign in0_ready = out0_ready & out_ready;

endmodule

