                      (address >= 1024 && address <= 2047) ? address :
                      (address >= 2048 && address <= 3071) ? (address & 11'b11111111111) :
                      (address >= 3072 && address <= 4095) ? (address | 12'b100000000000) :
                      12'b0;

always @(posedge clock) begin
    q <= output_value;
