    assign S1 = A1 & ~A2;
    assign S2 = ~A1 & A2;

    // Implement S3 and S4
    assign S3 = ~B1 & C1;
    assign S4 = B1 & C1;

    // Implement S5
    assign S5 = ~S1 & ~S2 & ~S3 & ~S4;

