module nfc_transmitter (
  input data_in,
  input clk,
  input reset,
  output tx_out
);

  reg [7:0] data_reg;
  reg [3:0] bit_counter;
  reg [7:0] tx_reg;
  reg tx_enable;

  assign tx_out = tx_reg[7];

  always @(posedge clk) begin
    if (reset) begin
      data_reg <= 0;
      bit_counter <= 0;
      tx_reg <= 8'b00000000;
      tx_enable <= 0;
    end else begin
      if (bit_counter == 4) begin
        bit_counter <= 0;
        data_reg <= data_in;
        tx_enable <= 1;
      end else begin
        bit_counter <= bit_counter + 1;
        tx_enable <= 0;
      end

      if (tx_enable) begin
        tx_reg <= {1'b1, data_reg[7:6]} ^ tx_reg;
        tx_reg <= {1'b1, data_reg[5:4]} ^ tx_reg;
        tx_reg <= {1'b1, data_reg[3:2]} ^ tx_reg;
        tx_reg <= {1'b1, data_reg[1:0]} ^ tx_reg;
      end
    end
  end

endmodule

module nfc_receiver (
  input rx_in,
  input clk,
  input reset,
  output data_out
);

  reg [7:0] data_reg;
  reg [3:0] bit_counter;
  reg [7:0] rx_reg;
  reg rx_enable;

  assign data_out = data_reg;

  always @(posedge clk) begin
    if (reset) begin
      data_reg <= 0;
      bit_counter <= 0;
      rx_reg <= 8'b00000000;
      rx_enable <= 0;
    end else begin
      if (bit_counter == 4) begin
        bit_counter <= 0;
        data_reg <= rx_reg;
      end else begin
        bit_counter <= bit_counter + 1;
      end

      rx_reg <= {1'b0, rx_in} ^ rx_reg;
      rx_enable <= 1;

      if (rx_enable && (rx_reg == 8'b11110000)) begin
        rx_enable <= 0;
        rx_reg <= 8'b00000000;
      end
    end
  end

endmodule

module edge_detector(
    input clk,
    input [7:0] in,
    output reg [7:0] anyedge
);

reg [7:0] prev_in;
reg [7:0] edge_detected;

always @(posedge clk) begin
    prev_in <= in;
    edge_detected <= in ^ prev_in;
    anyedge <= edge_detected;
end

endmodule

module pll_clk_generator 
 (// Clock in ports
  input         clk_in1,
  // Clock out ports
  output        clk_out1,
  // Status and control signals
  input         reset,
  output        locked
 );

  // Input buffering
  //------------------------------------
  IBUF clkin1_ibufg
   (.O (clk_in1_clk_wiz_0),
    .I (clk_in1));

  // Clocking PRIMITIVE
  //------------------------------------

  // Instantiation of the MMCM PRIMITIVE
  //    * Unused inputs are tied off
  //    * Unused outputs are labeled unused
  wire [15:0] do_unused;
  wire        drdy_unused;
  wire        psdone_unused;
  wire        locked_int;
  wire        clkfbout_clk_wiz_0;
  wire        clkfbout_buf_clk_wiz_0;
