module bitwise_op (
  input [3:0] a,
  input [3:0] b,
  input [1:0] ctrl,
  output reg [3:0] out
);

always @(*) begin
  case (ctrl)
    2'b00: out = a & b;
    2'b01: out = a | b;
    2'b10: out = a ^ b;
    2'b11: out = ~(a & b);
    default: out = 4'b0;
  endcase
end

endmodule

module seq_counter (
  input clk,
  input reset,
  input [9:0] data,
  output reg [3:0] count
);

reg [2:0] state;
reg [2:0] next_state;

always @ (posedge clk) begin
  if (reset) begin
    state <= 3'b000;
    count <= 4'b0000;
  end
  else begin
    state <= next_state;
    count <= (state == 3'b100) ? count + 1 : count;
  end
end

always @ (data) begin
  case (state)
    3'b000: next_state = (data == 3'b101) ? 3'b001 : 3'b000;
    3'b001: next_state = (data[2:1] == 2'b01) ? 3'b010 : 3'b000;
    3'b010: next_state = (data == 3'b101) ? 3'b011 : 3'b000;
    3'b011: next_state = (data[2:1] == 2'b01) ? 3'b100 : 3'b000;
    3'b100: next_state = 3'b000;
    default: next_state = 3'b000;
  endcase
end

endmodule

