module request_counter_manager(
  input wire CLK,
  input wire RST,
  input wire DRIVE,
  input wire [7:0] req,
  input wire [7:0] im_enq,
  input wire [7:0] im_emp,
  output reg [7:0] reqcnt_a,
  output reg [7:0] reqcnt_b,
  output reg [7:0] reqcnt_c,
  output reg [7:0] reqcnt_d,
  output reg [7:0] reqcnt_e,
  output reg [7:0] reqcnt_f,
  output reg [7:0] reqcnt_g,
  output reg [7:0] reqcnt_h
);

  reg [7:0] reqcnt_rst;
  reg [7:0] im_rst;

  always @(posedge CLK) begin
    if (RST) begin
      reqcnt_a <= 0;
      reqcnt_b <= 0;
      reqcnt_c <= 0;
      reqcnt_d <= 0;
      reqcnt_e <= 0;
      reqcnt_f <= 0;
      reqcnt_g <= 0;
      reqcnt_h <= 0;
      reqcnt_rst <= 0;
      im_rst <= 0;
    end else begin
      if (DRIVE) begin
        case (req)
          8'h01: reqcnt_a <= reqcnt_a + 1;
          8'h02: reqcnt_b <= reqcnt_b + 1;
          8'h04: reqcnt_c <= reqcnt_c + 1;
          8'h08: reqcnt_d <= reqcnt_d + 1;
          8'h10: reqcnt_e <= reqcnt_e + 1;
          8'h20: reqcnt_f <= reqcnt_f + 1;
          8'h40: reqcnt_g <= reqcnt_g + 1;
          8'h80: reqcnt_h <= reqcnt_h + 1;
        endcase
      end

      if (|im_enq) begin
        case (im_enq)
          8'h01: im_rst[0] <= 1;
          8'h02: im_rst[1] <= 1;
          8'h04: im_rst[2] <= 1;
          8'h08: im_rst[3] <= 1;
          8'h10: im_rst[4] <= 1;
          8'h20: im_rst[5] <= 1;
          8'h40: im_rst[6] <= 1;
          8'h80: im_rst[7] <= 1;
        endcase
      end

      if (|im_emp) begin
        case (im_emp)
          8'h01: im_rst[0] <= 0;
          8'h02: im_rst[1] <= 0;
          8'h04: im_rst[2] <= 0;
          8'h08: im_rst[3] <= 0;
          8'h10: im_rst[4] <= 0;
          8'h20: im_rst[5] <= 0;
          8'h40: im_rst[6] <= 0;
          8'h80: im_rst[7] <= 0;
        endcase
      end

      if (reqcnt_rst != 8'hFF) begin
        if (reqcnt_rst[0] && ((|req[7:1]) || im_rst[0] || (reqcnt_rst > 1'b0))) reqcnt_a <= 0;
        if (reqcnt_rst[1] && ((|req[7:2]) || im_rst[1] || (reqcnt_rst > 2'b0))) reqcnt_b <= 0;
        if (reqcnt_rst[2] && ((|req[7:3]) || im_rst[2] || (reqcnt_rst > 3'b0))) reqcnt_c <= 0;
        if (reqcnt_rst[3] && ((|req[7:4]) || im_rst[3] || (reqcnt_rst > 4'b0))) reqcnt_d <= 0;
        if (reqcnt_rst[4] && ((|req[7:5]) || im_rst[4] || (reqcnt_rst > 5'b0))) reqcnt_e <= 0;
        if (reqcnt_rst[5] && ((|req[7:6]) || im_rst[5] || (reqcnt_rst > 6'b0))) reqcnt_f <= 0;
        if (reqcnt_rst[6] && ((|req[7]) || im_rst[6] || (reqcnt_rst > 7'b0))) reqcnt_g <= 0;
        if (reqcnt_rst[7] && ((|req[6:0]) || im_rst[7])) reqcnt_h <= 0;
      end

      if (|im_rst) begin
        reqcnt_rst <= im_rst;
      end else begin
        reqcnt_rst <= 8'hFF;
      end
    end
  end

endmodule

module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    input [3:0] Cin,
    input [1:0] Sel,
    output reg [3:0] Sum,
    output reg Cout
);

    always @ (*) begin
        case (Sel)
            2'b00: begin // addition
                Sum = A + B + Cin;
                Cout = (A + B + Cin > 4'b1111) ? 1'b1 : 1'b0;
            end
            2'b01: begin // subtraction
                Sum = A - B - Cin;
                Cout = (A - B - Cin < 4'b0000) ? 1'b1 : 1'b0;
            end
            2'b10: begin // bitwise AND
                Sum = A & B;
                Cout = A & B & Cin;
            end
            2'b11: begin // bitwise OR
                Sum = A | B;
                Cout = A | B | Cin;
            end
            default: begin // invalid Sel value
                Sum = 4'b0000;
                Cout = 1'b0;
            end
        endcase
    end

endmodule

module lcd_controller (
    input CLK_I,
    input RST_I,
    input [2:0] MSEL_I,
    input int_De,
    input int_R,
    input int_G,
    input int_B,
    output reg int_Bklt,
    output reg BKLT_O,
    output reg VDDEN_O,
    output reg DISP_O,
    output reg DE_O,
    output reg R_O,
    output reg G_O,
    output reg B_O,
    output reg CLK_O
);

    // Define states of the state machine
    localparam STATE_OFF = 0;
    localparam STATE_POWER_UP = 1;
    localparam STATE_LED_WARM_UP = 2;
    localparam STATE_ON = 3;
    localparam STATE_LED_COOL_DOWN = 4;
    localparam STATE_POWER_DOWN = 5;

    // Define constants for wait counter
    localparam TPOWERUP_CYCLES = 100;
    localparam TLEDWARMUP_CYCLES = 100;
    localparam TLEDCOOLDOWN_CYCLES = 100;
    localparam TPOWERDOWN_CYCLES = 100;

    // Define variables for state machine
    reg [2:0] state;
    reg [2:0] next_state;
    reg waitCntEn;
    reg [7:0] waitCnt;

    // Define variables for PWM
    Pulse_Width_Modulation #(
        .C_CLK_I_FREQUENCY  (9),
        .C_PWM_FREQUENCY    (25000),
        .C_PWM_RESOLUTION   (3)
    ) pwm (
        .CLK_I              (CLK_I),
        .RST_I              (RST_I),
        .DUTY_FACTOR_I      (MSEL_I[2:0]),
        .PWM_O              (int_Bklt)
    );

    // Define output signals
    assign BKLT_O = (state == STATE_ON) ? int_Bklt : 1'b0;
    assign VDDEN_O = (state == STATE_OFF || state == STATE_POWER_DOWN) ? 1'b0 : 1'b1;
    assign DISP_O = (state == STATE_OFF || state == STATE_POWER_DOWN || state == STATE_POWER_UP) ? 1'b0 : 1'b1;
    assign DE_O = (state == STATE_OFF || state == STATE_POWER_DOWN || state == STATE_POWER_UP) ? 1'b0 : int_De;
    assign R_O = (state == STATE_OFF || state == STATE_POWER_DOWN || state == STATE_POWER_UP) ? 1'b0 : int_R;
    assign G_O = (state == STATE_OFF || state == STATE_POWER_DOWN || state == STATE_POWER_UP) ? 1'b0 : int_G;
    assign B_O = (state == STATE_OFF || state == STATE_POWER_DOWN || state == STATE_POWER_UP) ? 1'b0 : int_B;
    assign CLK_O = CLK_I;

    // Define clock stop signal
    assign clkStop = (state == STATE_OFF || state == STATE_POWER_DOWN || state == STATE_POWER_UP) ? 1'b1 : 1'b0;

    // Define wait counter
    always @(posedge CLK_I) begin
        if (waitCntEn == 1'b0) begin
            waitCnt <= 0;
        end else begin
            waitCnt <= waitCnt + 1;
        end
    end

    // Define state machine
    always @(posedge CLK_I) begin
        state <= next_state;
    end

    always @* begin
        case (state)
            STATE_OFF:
                next_state = (MSEL_I[3] == 1'b1 && RST_I == 1'b0) ? STATE_POWER_UP : STATE_OFF;
            STATE_POWER_UP:
                next_state = (waitCnt == TPOWERUP_CYCLES) ? STATE_LED_WARM_UP : STATE_POWER_UP;
            STATE_LED_WARM_UP:
                next_state = (waitCnt == TLEDWARMUP_CYCLES) ? STATE_ON : STATE_LED_WARM_UP;
            STATE_ON:
                next_state = (MSEL_I[3] == 1'b0 && RST_I == 1'b1) ? STATE_LED_COOL_DOWN : STATE_ON;
            STATE_LED_COOL_DOWN:
                next_state = (waitCnt == TLEDCOOLDOWN_CYCLES) ? STATE_POWER_DOWN : STATE_LED_COOL_DOWN;
            STATE_POWER_DOWN:
                next_state = (waitCnt == TPOWERDOWN_CYCLES) ? STATE_OFF : STATE_POWER_DOWN;
            default:
                next_state = STATE_OFF;
        endcase
    end

    // Define clock forwarding
    ODDR2 #(
        .DDR_ALIGNMENT      ("NONE"),
        .INIT               (1'b0),
        .SRTYPE             ("SYNC")
    ) Inst_ODDR2_MCLK_FORWARD (
        .Q                  (CLK_O),
        .C0                 (CLK_I),
        .C1                 (CLK_180_I),
        .CE                 (1'b1),
        .D0                 (1'b1),
        .D1                 (1'b0),
        .R                  (clkStop),
        .S                  (1'b0)
    );

endmodule

module two_input_gate (A, B, Y);

input A, B;
output Y;

wire not_A, not_B, and_AB, and_notA_notB;

// Invert A and B
not not_A (A);
not not_B (B);

// Compute A AND B and NOT A AND NOT B
and and_AB (A, B);
and and_notA_notB (not_A, not_B);

// Compute Y = (A AND B) OR (NOT A AND NOT B)
or or_Y (and_AB, and_notA_notB, Y);

endmodule

module top_module(
  input clk,
  input reset,
  input [3:0] a,
  input [3:0] b,
  output reg [7:0] product
);

  reg [3:0] a_reg;
  reg [3:0] b_reg;
  reg [3:0] b_index;
  reg [7:0] sum_reg;
  wire [3:0] a_bit;
  wire [3:0] b_bit;
  wire [3:0] carry_in;
  wire [3:0] carry_out;

  full_adder fa[4:0](
    .a(a_bit),
    .b(b_bit),
    .carry_in(carry_in),
    .sum(sum_reg[3:0]),
    .carry_out(carry_out)
  );

  always @ (posedge clk) begin
    if (reset) begin
      a_reg <= 4'b0;
      b_reg <= 4'b0;
      b_index <= 4'b0;
      sum_reg <= 8'b0;
      product <= 8'b0;
    end else begin
      a_reg <= a;
      b_reg <= b;
      b_index <= 4'b0;
      sum_reg <= 8'b0;
      product <= 8'b0;
    end
  end

  always @ (posedge clk) begin
    if (!reset) begin
      a_bit <= a_reg[b_index];
      b_bit <= b_reg[b_index];
      carry_in <= sum_reg[b_index+3];
      b_index <= b_index + 1;
      sum_reg <= {carry_out, sum_reg[7:1]};
      product <= sum_reg;
    end
  end

endmodule

module full_adder(
  input a, 
  input b, 
  input carry_in, 
  output sum, 
  output carry_out
);

  assign {carry_out, sum} = a + b + carry_in;

endmodule

module program_counter (next_pc, cur_pc, rst, clk);
	// Output signals...
	// Incremented value of the program counter
	output reg [0:31] next_pc;

	// ===============================================================
	// Input signals
	// Current value of the program counter
	input [0:31] cur_pc;
	// Clock signal for the program counter
	input clk;
	// Reset signal for the program counter
	input rst;

	// ===============================================================
	// Declare "wire" signals:
	// None

	// ===============================================================
	// Declare "reg" signals: 
	// None

	// ===============================================================
	always @(posedge clk) begin
		// If the reset signal is set to HIGH
		if (rst) begin
			// Set the program counter to 0
			next_pc <= 32'd0;
		end
		else begin
			// Increment the program counter by 4
			next_pc <= cur_pc + 32'd4;
		end
	end
endmodule

module top_module (
    input clk,
    input reset,
    input up_down,
    input enable,
    output [3:0] index
);

    wire [7:0] counter_out;
    wire [3:0] decoder_out;

    up_down_counter counter_inst (
        .clk(clk),
        .reset(reset),
        .up_down(up_down),
        .enable(enable),
        .out(counter_out)
    );

    decoder decoder_inst (
        .in(counter_out),
        .out(decoder_out)
    );

    assign index = decoder_out;

endmodule

module up_down_counter (
    input clk,
    input reset,
    input up_down,
    input enable,
    output reg [7:0] out
);

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            out <= 8'd0;
        end else if (enable) begin
            if (up_down) begin
                out <= out + 1;
            end else begin
                out <= out - 1;
            end
        end
    end

endmodule

module decoder (
    input [7:0] in,
    output reg [3:0] out
);

    always @* begin
        case (in)
            8'd0: out = 4'b0001;
            8'd1: out = 4'b0010;
