      .out_addr0(s2o_addr0),
      .out_addr1(s2o_addr1),
      .out_data0(s2o_data0),
      .out_data1(s2o_data1),
      .out_active(s2o_active),
      .state(s_state),
      .error(error_stage)
    );

  reg writing;

  assign stage_addr0 = (writing)?b2s_addr0:s2o_addr0;
  assign stage_addr1 = b2s_addr1;

  // The logic to inititate the reading and writing.
  always @ (posedge clk)
    if (~rst_n)
      begin
        writing <= 1'b1;
        b2s_start <= 1'b1;
        s2o_start <= 1'b0;
      end
    else
      begin
        //defaults
        b2s_start <= 1'b0;
        s2o_start <= 1'b0;
        if (s_state == STAGE_EMPTY)
          b2s_start <= 1'b1;
        else if (s_state == STAGE_FULL)
          s2o_start <= 1'b1;
      end

  assign error = buffer_error | b2s_error | mbuffer_error | error_stage;

  // Output
  assign out_data = s2o_data0;
  assign out_m = s2o_m;
  assign out_nd = s2o_active;
  assign out_msg = in_msg;
  assign out_msg_nd = in_msg_nd;

  // Delete
  stage_delete #(N, LOG_N) stage_del
    (
      .clk(clk),
      .rst_n(rst_n),
      .in_active(out_nd),
      .in_addr0(s2o_addr0),
      .in_addr1(s2o_addr1),
      .state(s_state)
    );

  // Write
  stage_write #(N, LOG_N, WIDTH, MWIDTH) stage_write
    (
      .clk(clk),
      .rst_n(rst_n),
      .in_nd(in_nd),
      .in_data0(in_data),
      .in_data1(in_m),
      .in_active(s2o_active),
      .in_addr0(stage_addr0),
      .in_addr1(stage_addr1),
      .state(s_state),
      .writing(writing)
    );

  // Update writing flag
  always @ (posedge clk)
    if (~rst_n)
      writing <= 1'b1;
    else if (s_state == STAGE_FULL)
      writing <= 1'b0;

  // Debug message
  always @ (posedge clk)
    if (~rst_n)
      out_msg_nd <= 1'b0;
    else if (in_msg_nd)
      out_msg_nd <= 1'b1;

endmodule

module mag_comp(
  input [3:0] A,
  input [3:0] B,
  output reg [1:0] EQ_GT_LT,
  output reg EQ
);

  wire [3:0] diff;
  wire [3:0] sum;

  assign diff = A - B;
  assign sum = A + B;

  comparator comp(.a(diff), .b(4'b0), .gt(EQ_GT_LT[1]), .eq(EQ_GT_LT[0]), .lt(EQ_GT_LT[1]));
  mux2to1 mux(.a(EQ_GT_LT[1]), .b(EQ_GT_LT[0]), .sel(sum[3]), .y(EQ_GT_LT[1]));

  assign EQ = (diff == 0);

endmodule

