module PLL (
  input ref_clk,
  input fb_clk,
  input reset,
  output out_clk
);

parameter n = 8; // number of bits for phase representation
parameter k = 10; // multiplication factor
parameter m = 2; // division factor

reg [n-1:0] phase; // current phase of the output clock signal
reg [n-1:0] phase_error; // phase error between reference and feedback clock signals
reg [n-1:0] phase_accumulator; // phase accumulator used to generate output clock signal
reg [n-1:0] phase_increment; // phase increment used to update phase accumulator
reg [n-1:0] charge_pump_output; // output of the charge pump
reg [n-1:0] loop_filter_output; // output of the loop filter

wire [n-1:0] fb_clk_divided; // feedback clock signal divided by m
wire [n-1:0] phase_detector_output; // output of the phase detector

// Divide feedback clock signal by m
divider #(.n(n), .m(m)) divider_inst (
  .clk(fb_clk),
  .reset(reset),
  .out(fb_clk_divided)
);

// Phase detector
phase_detector #(.n(n)) phase_detector_inst (
  .ref_clk(ref_clk),
  .fb_clk(fb_clk_divided),
  .out(phase_detector_output)
);

// Charge pump
charge_pump #(.n(n), .k(k)) charge_pump_inst (
  .phase_error(phase_detector_output),
  .out(charge_pump_output)
);

// Loop filter
loop_filter #(.n(n)) loop_filter_inst (
  .charge_pump_output(charge_pump_output),
  .out(loop_filter_output)
);

// Generate output clock signal
always @(posedge ref_clk or posedge reset) begin
  if (reset) begin
    phase <= 0;
    phase_error <= 0;
    phase_accumulator <= 0;
    phase_increment <= 0;
  end else begin
    // Update phase error
    phase_error <= fb_clk_divided - phase_accumulator;

    // Update charge pump output
    charge_pump_output <= phase_error * k;

    // Update loop filter output
    loop_filter_output <= loop_filter_output + charge_pump_output;

    // Update phase accumulator
    phase_increment <= loop_filter_output;
    phase_accumulator <= phase_accumulator + phase_increment;

    // Update output clock signal
    phase <= phase + phase_increment;
    out_clk <= $bit(phase, n-1);
  end
end

endmodule

