module Order(
    input wire CLK, 
    input wire nRST,
    input wire request$say__ENA,
    input wire [31:0]request$say$va,
    output wire request$say__RDY,
    output wire [31:0]outA,
    output wire [31:0]outB
);

    reg [31:0]a, offset, outA, outB;
    reg running;
    assign request$say__RDY = !running;

    always @(posedge CLK) begin
        if(!nRST) begin
            a <= 0;
            offset <= 0;
            outA <= 0;
            outB <= 0;
            running <= 0;
        end
        else begin
            if(request$say__ENA == 0) begin
                if(running == 0) begin
                    a <= 1;
                end
                else begin
                    a <= a + 1;
                end
                outA <= a + offset;
                outB <= a + offset;
                offset <= offset + 1;
            end
            else begin
                a <= request$say$va;
                offset <= 1;
                running <= 1;
            end
        end
    end
endmodule

