module timer(
    input clk,
    input rst,
    input start_timer,
    input [3:0] time_value,
    output expired
);

    reg [3:0] counter = 4'b0000;
    reg expired_reg = 1'b0;
    wire clk_div;

    assign expired = expired_reg;

    clock_divider div(clk, rst, clk_div);

    always @(posedge clk_div or negedge start_timer) begin
        if (~start_timer) begin
            counter <= 4'b0000;
            expired_reg <= 1'b0;
        end else begin
            if (counter == time_value) begin
                expired_reg <= 1'b1;
            end else begin
                counter <= counter + 1;
            end
        end
    end

endmodule

module clock_divider(
    input clk,
    input rst,
    output reg clk_div
);

    reg [23:0] count = 24'd0;

    always @(posedge clk, negedge rst) begin
        if (~rst) begin
            count <= 24'd0;
            clk_div <= 1'b0;
        end else begin
            count <= count + 1;
            if (count == 24'd499999) begin
                count <= 24'd0;
                clk_div <= ~clk_div;
            end
        end
    end

endmodule

