module vga_converter (
  input [23:0] data,
  input blank,
  input hs,
  input vs,
  input clk,
  output reg [7:0] vga_data,
  output reg blank_out,
  output reg hs_out,
  output reg vs_out
);

  reg [1:0] cnt;
  reg [23:0] data_reg;
  reg hs_reg;
  reg hs_reg1;
  reg vs_reg;
  reg blank_reg;

  always @(posedge clk) begin
    hs_reg <= hs;
    hs_reg1 <= hs_reg;
    vs_reg <= vs;
    blank_reg <= blank;
  end

  wire sync_pulse = (hs_reg & !hs_reg1) ? 1 : 0;
  always @(posedge clk) begin
    if (sync_pulse) begin
      cnt <= 2; // sync_pulse is phase ?, 
    end
    else begin
      if (cnt == 2)
        cnt <= 0;
      else    
        cnt <= cnt+1;
    end
  end

  always @(posedge clk) begin
    if (cnt == 2)
      data_reg <= data;
  end

  always @(posedge clk) begin
    case (cnt)
      0: vga_data <= {3'b0, data_reg[7:0]};
      1: vga_data <= {3'b0, data_reg[15:8]};
      default: vga_data <= {2'b0, data_reg[23:16]};
    endcase
  end

  assign blank_out = blank_reg;
  assign hs_out = hs_reg;
  assign vs_out = vs_reg;

endmodule

module top_module (
    input clk,
    input reset,
    input [7:0] a,
    input [7:0] b,
    input [2:0] sel,
    output reg [7:0] out,
    output reg parity,
    output reg overflow
);

    wire [7:0] sum;
    wire add_overflow;
    add_overflow_detection adder(a, b, sum, add_overflow);

    wire [3:0] data0;
    wire [3:0] data1;
    wire [3:0] data2;
    wire [3:0] data3;
    wire [3:0] data4;
    wire [3:0] data5;

    assign data0 = {1'b0, a};
    assign data1 = {1'b0, b};
    assign data2 = {1'b0, sum};
    assign data3 = {1'b0, 8'b0};
    assign data4 = {1'b0, 8'b0};
    assign data5 = {1'b0, 8'b0};

    mux_parity mux(sel, data0, data1, data2, data3, data4, data5, out, parity);

    always @(posedge clk) begin
        if (reset) begin
            out <= 8'b0;
            parity <= 1'b0;
            overflow <= 1'b0;
        end else begin
            case (sel)
                3'b000: begin
                    out <= a;
                end
                3'b001: begin
                    out <= b;
                end
                3'b010: begin
                    out <= sum;
                    overflow <= add_overflow;
                end
                default: begin
                    out <= 8'b0;
                    parity <= 1'b0;
                    overflow <= 1'b0;
                end
            endcase
        end
    end

endmodule

module add_overflow_detection (
    input [7:0] a,
    input [7:0] b,
    output [7:0] s,
    output overflow
);
    assign s = a + b;
    assign overflow = ((a[7] == b[7]) && (s[7] != a[7]));
endmodule

module mux_parity (
    input [2:0] sel,
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output reg [3:0] out,
    output reg parity
);
    always @* begin
        case (sel)
            3'b000: begin
                out = data0[3:0];
                parity = ^data0;
            end
            3'b001: begin
                out = data1[3:0];
                parity = ^data1;
            end
            3'b010: begin
                out = data2[3:0];
                parity = ^data2;
            end
            3'b011: begin
                out = data3[3:0];
                parity = ^data3;
            end
            3'b100: begin
                out = data4[3:0];
                parity = ^data4;
            end
            3'b101: begin
                out = data5[3:0];
                parity = ^data5;
            end
            default: begin
                out = 4'b0;
                parity = 1'b0;
            end
        endcase
    end
endmodule

