module calculator(
    input clk,
    input rst,
    input [1:0] op,
    input [7:0] num1,
    input [7:0] num2,
    output reg [7:0] result,
    output reg valid
);

reg [15:0] temp_result;
reg [3:0] state;

parameter IDLE = 2'b00;
parameter OP1 = 2'b01;
parameter OP2 = 2'b10;
parameter RESULT = 2'b11;

always @(posedge clk) begin
    if (rst) begin
        state <= IDLE;
        temp_result <= 0;
        result <= 0;
        valid <= 0;
    end else begin
        case(state)
            IDLE: begin
                if (op != 2'b00) begin
                    temp_result <= {num1, num2};
                    state <= OP1;
                end
            end
            OP1: begin
                temp_result <= temp_result;
                state <= OP2;
            end
            OP2: begin
                case(op)
                    2'b00: temp_result <= temp_result[7:0] + temp_result[15:8];
                    2'b01: temp_result <= temp_result[7:0] - temp_result[15:8];
                    2'b10: temp_result <= temp_result[7:0] * temp_result[15:8];
                    2'b11: temp_result <= temp_result[7:0] / temp_result[15:8];
                endcase
                state <= RESULT;
            end
            RESULT: begin
                result <= temp_result[7:0];
                valid <= 1;
                state <= IDLE;
            end
        endcase
    end
end

endmodule

module rotator_adder(
    input clk,
    input reset,
    input load,
    input [1:0] ena,
    input [99:0] data,
    output reg [31:0] q
);

reg [99:0] rotated_data;
reg [31:0] adder_out;

always @(posedge clk) begin
    if (reset) begin
        rotated_data <= 0;
        adder_out <= 0;
    end else begin
        if (load) begin
            if (ena == 2'b00) begin
                rotated_data <= data;
            end else if (ena == 2'b01) begin
                rotated_data <= {data[31:0], data[99:32]};
            end else if (ena == 2'b10) begin
                rotated_data <= {data[67:0], data[99:68]};
            end else begin
                rotated_data <= {data[33:0], data[99:34]};
            end
        end

        adder_out <= rotated_data[31:0] + 32'd12345678;
        q <= adder_out;
    end
end

endmodule

module parallel_shift_reg (
  input clk,
  input reset,
  input active,
  input [0:width-1] data_in,
  output [0:width-1] data_out
);

parameter width = 32;
parameter depth = 2;
parameter reset_type = 1; // 1 for async reset, 0 for sync reset

wire [0:(depth+1)*width-1] data;
assign data[0:width-1] = data_in;

genvar level;

generate
  for (level = 0; level < depth; level = level + 1) begin : levels
    wire [0:width-1] data_s, data_q;
    assign data_s = data[level*width:(level+1)*width-1];
    if (reset_type == 1) begin
      c_dff_async #(.width(width)) dataq (
        .clk(clk),
        .reset(reset),
        .active(active),
        .d(data_s),
        .q(data_q)
      );
    end else begin
      c_dff #(.width(width)) dataq (
        .clk(clk),
        .reset(reset),
        .active(active),
        .d(data_s),
        .q(data_q)
      );
    end
    assign data[(level+1)*width:(level+2)*width-1] = data_q;
  end
endgenerate

assign data_out = data[depth*width:(depth+1)*width-1];

endmodule

