module up_down_counter (
    input clk,
    input up,
    input down,
    input load,
    input reset,
    input [7:0] data,
    output reg [2:0] out
);

    reg [7:0] counter_value;

    always @(posedge clk) begin
        if (reset) begin
            counter_value <= 0;
        end else if (load) begin
            counter_value <= data;
        end else if (up) begin
            counter_value <= counter_value + 1;
        end else if (down) begin
            counter_value <= counter_value - 1;
        end
    end

    assign out = {counter_value[7], counter_value[6], counter_value[5]};

endmodule

