module signed_divider (
    input signed [15:0] A,
    input signed [15:0] B,
    input clk,
    input reset,
    output reg signed [15:0] Q,
    output reg overflow_or_divide_by_zero
);

reg signed [15:0] remainder;
reg signed [15:0] divisor;
reg signed [15:0] quotient;
reg [3:0] state;

always @(posedge clk) begin
    if (reset) begin
        state <= 4'b0000;
        remainder <= 0;
        divisor <= 0;
        quotient <= 0;
        overflow_or_divide_by_zero <= 0;
    end
    else begin
        case (state)
            4'b0000: begin // Load A and B
                divisor <= B;
                quotient <= A;
                state <= 4'b0001;
            end
            4'b0001: begin // Check for divide-by-zero
                if (divisor == 0) begin
                    state <= 4'b0100;
                    overflow_or_divide_by_zero <= 1;
                end
                else begin
                    state <= 4'b0010;
                end
            end
            4'b0010: begin // Check for overflow
                if (quotient == -32768 && divisor == -1) begin
                    state <= 4'b0100;
                    overflow_or_divide_by_zero <= 1;
                end
                else begin
                    state <= 4'b0011;
                end
            end
            4'b0011: begin // Perform division
                if (quotient < 0) begin
                    remainder <= -quotient;
                    quotient <= -quotient;
                end
                else begin
                    remainder <= quotient;
                end
                divisor <= divisor << 1;
                state <= 4'b0100;
            end
            4'b0100: begin // Check for end of division
                if (divisor[15] == 1) begin
                    state <= 4'b0101;
                end
                else begin
                    state <= 4'b0011;
                end
            end
            4'b0101: begin // Restore quotient and remainder
                if (remainder >= divisor) begin
                    quotient[0] <= 1;
                    remainder <= remainder - divisor;
                end
                else begin
                    quotient[0] <= 0;
                end
                divisor <= divisor >> 1;
                state <= 4'b0100;
            end
        endcase
    end
end

assign Q = quotient;

endmodule

