module exponent_finder_modified(
	 input clk,
    input [63:0] boundary,
    input input_enable,
    input reset,
    input [8:0] base,
    output reg [7:0] exponent,
	 output reg ready
    );

	 reg [7:0] next_exponent;
	 reg next_ready;
	 reg [10:0] temp_product;
	 reg [10:0] next_temp_product;


	 initial begin
		next_ready = 0;
		next_exponent = 0;
		next_temp_product = 1;
	 end

	 always @(posedge clk) begin
		ready <= next_ready;
		exponent <= next_exponent;
		temp_product <= next_temp_product;
	 end

	 always @(*) begin
			if (reset) begin
				next_ready = 0;
				next_exponent = 0;
				next_temp_product = 1;
			end else if (input_enable) begin
				if (temp_product < boundary) begin
					next_temp_product = temp_product * base;
					next_ready = 0;
					next_exponent = exponent + 1;
				end else begin
					next_temp_product = temp_product;
					next_ready = 1;
					next_exponent = exponent;
				end
			end else begin
				next_temp_product = 1;
				next_ready = 0;
				next_exponent = 0;
			end
	 end

endmodule

module top_module (
    input [3:0] A,
    input [3:0] B,
    input [3:0] C,
    input [3:0] D,
    input [1:0] SEL,
    input [3:0] DATA,
    input [1:0] SHIFT,
    output [7:0] OUT
);

    // 4-to-1 Multiplexer with Priority Encoder
    wire [3:0] mux_priority;
    wire [3:0] mux_out;

    priority_encoder pe(
        .in(mux_priority),
        .out(SEL)
    );

    mux_4to1 mux(
        .in_a(A),
        .in_b(B),
        .in_c(C),
        .in_d(D),
        .sel(SEL),
        .out(mux_out)
    );

    assign mux_priority[0] = D;
    assign mux_priority[1] = C;
    assign mux_priority[2] = B;
    assign mux_priority[3] = A;

    // 4-bit Barrel Shifter
    wire [3:0] shift_out;

    barrel_shifter bs(
        .data(DATA),
        .shift(SHIFT),
        .out(shift_out)
    );

    // Functional Module
    assign OUT = {shift_out, mux_out};

endmodule

module priority_encoder (
    input [3:0] in,
    output reg [1:0] out
);

    always @* begin
        case (in)
            4'b0001: out = 2'b00;
            4'b0010: out = 2'b01;
            4'b0100: out = 2'b10;
            4'b1000: out = 2'b11;
            default: out = 2'b11;
        endcase
    end

endmodule

module mux_4to1 (
    input [3:0] in_a,
    input [3:0] in_b,
    input [3:0] in_c,
    input [3:0] in_d,
    input [1:0] sel,
    output reg [3:0] out
);

    always @* begin
        case (sel)
            2'b00: out = in_a;
            2'b01: out = in_b;
            2'b10: out = in_c;
            2'b11: out = in_d;
            default: out = in_a;
        endcase
    end

endmodule

module barrel_shifter (
    input [3:0] data,
    input [1:0] shift,
    output reg [3:0] out
);

    always @* begin
        case (shift)
            2'b00: out = data;
            2'b01: out = {data[2:0], 1'b0};
            2'b10: out = {data[1:0], 2'b00};
            2'b11: out = {data[0], 3'b000};
            default: out = data;
        endcase
    end

endmodule

module binary_counter (
    input clk,
    input reset,
    input load,
    input [3:0] data_in,
    output reg [3:0] count
);

reg [3:0] count_reg;
reg [3:0] count_next;

always @(posedge clk) begin
    if (reset) begin
        count_reg <= 4'b0;
    end
    else begin
        count_reg <= count_next;
    end
end

always @(*) begin
    if (load) begin
        count_next = data_in;
    end
    else begin
        count_next = count_reg + 4'b1;
    end
end

assign count = count_reg;

endmodule

module mux_4to2 (
    input [3:0] A0,
    input [3:0] A1,
    input [3:0] A2,
    input [3:0] A3,
    input S0,
    input S1,
    output reg [3:0] X
);

always @* begin
    case ({S1, S0})
        2'b00: X = A0;
        2'b01: X = A1;
        2'b10: X = A2;
        2'b11: X = A3;
    endcase
end

endmodule

