module signed_comparator(
    input signed [31:0] A,
    input signed [31:0] B,
    output EQ,
    output GT,
    output LT
);

reg EQ;
reg GT;
reg LT;

always @(*) begin
    if (A == B) begin
        EQ = 1;
        GT = 0;
        LT = 0;
    end else if (A > B) begin
        EQ = 0;
        GT = 1;
        LT = 0;
    end else begin
        EQ = 0;
        GT = 0;
        LT = 1;
    end
end

endmodule

module up_counter (
   input CLK,
   input RST_N,
   output reg [3:0] Q
);

   wire [3:0] Q0, Q1, Q2;

   d_ff ff0 (.D(Q1), .CLK(CLK), .RST_N(RST_N), .Q(Q0[0]));
   d_ff ff1 (.D(Q2), .CLK(CLK), .RST_N(RST_N), .Q(Q0[1]));
   d_ff ff2 (.D(Q3), .CLK(CLK), .RST_N(RST_N), .Q(Q0[2]));
   d_ff ff3 (.D(Q4), .CLK(CLK), .RST_N(RST_N), .Q(Q0[3]));

   assign Q = Q0;

   and gate0 (.A(Q0[0]), .B(CLK), .Y(Q1));
   and gate1 (.A(Q0[1]), .B(Q1), .Y(Q2));
   and gate2 (.A(Q0[2]), .B(Q1), .Y(Q3));
   and gate3 (.A(Q0[3]), .B(Q2), .Y(Q4));

endmodule

module axi_interface (
    input M_ACLK,
    input [0:0]M_ARESETN,
    output [31:0]M_AXI_awaddr,
    output [1:0]M_AXI_awburst,
    output [3:0]M_AXI_awcache,
    output [7:0]M_AXI_awlen,
    output [2:0]M_AXI_awprot,
    input [0:0]M_AXI_awready,
    output [2:0]M_AXI_awsize,
    output [0:0]M_AXI_awvalid,
    output [0:0]M_AXI_bready,
    input [1:0]M_AXI_bresp,
    input [0:0]M_AXI_bvalid,
    output [63:0]M_AXI_wdata,
    output [0:0]M_AXI_wlast,
    input [0:0]M_AXI_wready,
    output [7:0]M_AXI_wstrb,
    output [0:0]M_AXI_wvalid,
    input S_ACLK,
    input [0:0]S_ARESETN,
    input [31:0]S_AXI_awaddr,
    input [1:0]S_AXI_awburst,
    input [3:0]S_AXI_awcache,
    input [7:0]S_AXI_awlen,
    input [2:0]S_AXI_awprot,
    output [0:0]S_AXI_awready,
    input [2:0]S_AXI_awsize,
    input [0:0]S_AXI_awvalid,
    input [0:0]S_AXI_bready,
    output [1:0]S_AXI_bresp,
    output [0:0]S_AXI_bvalid,
    input [63:0]S_AXI_wdata,
    input [0:0]S_AXI_wlast,
    output [0:0]S_AXI_wready,
    input [7:0]S_AXI_wstrb,
    input [0:0]S_AXI_wvalid
);

    // Buffer for storing input data
    reg [63:0] input_buffer;
    // Counter for tracking the number of bytes received
    reg [2:0] byte_count;
    // Flag for indicating whether the current transfer is a write or read
    reg is_write;
    // Flag for indicating whether the current transfer is the last burst in a sequence
    reg is_last_burst;
    // Flag for indicating whether the current transfer is the last transfer in a burst
    reg is_last_transfer;

    // Connect input address and control signals to output
    assign M_AXI_awaddr = S_AXI_awaddr;
    assign M_AXI_awburst = S_AXI_awburst;
    assign M_AXI_awcache = S_AXI_awcache;
    assign M_AXI_awlen = S_AXI_awlen;
    assign M_AXI_awprot = S_AXI_awprot;
    assign M_AXI_awsize = S_AXI_awsize;
    assign M_AXI_awvalid = S_AXI_awvalid;
    assign S_AXI_awready = M_AXI_awready;

    // Connect input response signals to output
    assign S_AXI_bresp = M_AXI_bresp;
    assign S_AXI_bvalid = M_AXI_bvalid;
    assign M_AXI_bready = S_AXI_bready;

    // Connect input data signals to output
    assign M_AXI_wdata = input_buffer;
    assign M_AXI_wlast = is_last_transfer;
    assign M_AXI_wstrb = S_AXI_wstrb;
    assign M_AXI_wvalid = S_AXI_wvalid;
    assign S_AXI_wready = M_AXI_wready;

    // Detect the start of a new transfer
    always @(posedge S_ACLK) begin
        if (!S_ARESETN) begin
            // Reset state
            input_buffer <= 0;
            byte_count <= 0;
            is_write <= 0;
            is_last_burst <= 0;
            is_last_transfer <= 0;
        end else if (S_AXI_awvalid && S_AXI_awready) begin
            // Start of a new transfer
            input_buffer <= 0;
            byte_count <= 0;
            is_write <= (S_AXI_awburst != 2'b01);
            is_last_burst <= (S_AXI_awburst == 2'b10);
            is_last_transfer <= (S_AXI_awlen == 8'h01);
        end
    end

    // Receive data on the input data bus
    always @(posedge S_ACLK) begin
        if (S_AXI_wvalid && S_AXI_wready) begin
            // Store the incoming data in the buffer
            input_buffer <= {input_buffer[(byte_count+1)*8-1:0], S_AXI_wdata};
            byte_count <= byte_count + 1;
            is_last_transfer <= (byte_count == S_AXI_awlen);
        end
    end

    // Send data on the output data bus
    always @(posedge M_ACLK) begin
        if (M_AXI_wvalid && M_AXI_wready) begin
            // Send the next byte of data from the buffer
            M_AXI_wdata <= input_buffer[63-8*byte_count+:8];
            byte_count <= byte_count + 1;
            is_last_transfer <= (byte_count == S_AXI_awlen);
        end
    end

    // Detect the end of a transfer
    always @(posedge M_ACLK) begin
        if (!M_ARESETN) begin
            // Reset state
            input_buffer <= 0;
            byte_count <= 0;
            is_write <= 0;
            is_last_burst <= 0;
            is_last_transfer <= 0;
        end else if (M_AXI_bvalid && M_AXI_bready) begin
            // End of a transfer
            input_buffer <= 0;
            byte_count <= 0;
            is_write <= 0;
            is_last_burst <= 0;
            is_last_transfer <= 0;
        end
    end

endmodule

module top_module (
    input clk,
    input reset,
    input [7:0] in,
    output [7:0] toggled,
    output [7:0] count,
    output [7:0] final_output
);

reg [7:0] toggled_reg;
reg [7:0] count_reg;
reg [7:0] final_output_reg;

wire [7:0] toggled_wire;
wire [7:0] count_wire;

// Toggling circuit
reg [7:0] dff_in;
reg [7:0] dff_out;
wire [7:0] xor_out;

always @(posedge clk) begin
    dff_in <= in;
    dff_out <= dff_in ^ toggled_reg;
end

assign toggled_wire = xor_out;
assign toggled = toggled_reg;

// Population count circuit
wire [3:0] count_0;
wire [3:0] count_1;
wire [3:0] count_2;
wire [3:0] count_3;

assign count_0 = in[0] + in[4];
assign count_1 = in[1] + in[5];
assign count_2 = in[2] + in[6];
assign count_3 = in[3] + in[7];

wire [3:0] count_01;
wire [3:0] count_23;

assign count_01 = count_0 + count_1;
assign count_23 = count_2 + count_3;

assign count_wire = count_01 + count_23;
assign count = count_reg;

// Final functional module
always @(posedge clk) begin
    toggled_reg <= dff_out;
    count_reg <= count_wire;
    final_output_reg <= toggled_reg + count_reg;
end

assign final_output = final_output_reg;

endmodule

module arithmetic_module (
    input wire load_a_i,
    input wire load_b_i,
    input wire load_c_i,
    input wire [EW:0] Data_A_i,
    input wire [EW:0] Data_B_i,
    input wire Add_Subt_i,
    output wire [EW:0] Data_Result_o,
    output wire Overflow_flag_o,
    output wire Underflow_flag_o
);

// Define local parameters for upper limits
localparam integer Upper_limit = (2**(EW-1)-1);

// Define wires for intermediate calculations
wire [EW:0] Data_S;
wire Overflow_A;
wire Overflow_flag_A;
wire underflow_exp_reg;
wire [EW:0] U_Limit;

// Perform exponent calculation
add_sub_carry_out #(.W(EW+1)) exp_add_subt_m(
    .op_mode (Add_Subt_i),
    .Data_A (Data_A_i),
    .Data_B (Data_B_i),
    .Data_S ({Overflow_A,Data_S})
);

// Register exponent result
RegisterMult #(.W(EW+1)) exp_result_m(
    .clk (clk),
    .rst (rst),
    .load (load_c_i),
    .D (Data_S),
    .Q (Data_Result_o)
);

// Check for overflow
RegisterMult#(.W(1)) Oflow_A_m (
    .clk(clk),
    .rst(rst),
    .load(load_b_i),
    .D(Overflow_A),
    .Q(Overflow_flag_A)
);
assign Overflow_flag_o = Overflow_flag_A | Data_Result_o[EW];

// Check for underflow
Comparator_Less #(.W(EW+1)) Exp_unflow_Comparator_m (
    .Data_A(Data_S),
    .Data_B(U_Limit),
    .less(underflow_exp_reg)
);

RegisterMult #(.W(1)) Underflow_m (
    .clk(clk),
    .rst(rst),
    .load(load_a_i),
    .D(underflow_exp_reg),
    .Q(Underflow_flag_o)
);

// Define upper limit based on precision
assign U_Limit = Upper_limit[EW:0];

endmodule

module stratixv_io_obuf (
                      input i,
                      input oe,
                      input dynamicterminationcontrol,      
                      input [15:0] seriesterminationcontrol,
                      input [15:0] parallelterminationcontrol,     
                      input devoe,
                      output o,
                      output obar
                    );

//Parameter Declaration
parameter open_drain_output = 0;
parameter bus_hold = 0;
parameter shift_series_termination_control = 0;  
parameter sim_dynamic_termination_control_is_connected = 0;
parameter lpm_type = "stratixv_io_obuf";

//INTERNAL Signals
reg out_tmp;
reg out_tmp_bar;
reg prev_value;
wire tmp;
wire tmp_bar;
wire tmp1;
wire tmp1_bar;

//Shift seriesterminationcontrol signal if shift_series_termination_control is true
wire [15:0] seriesterminationcontrol_shifted;
assign seriesterminationcontrol_shifted = (shift_series_termination_control) ? {seriesterminationcontrol[14:0], 1'b0} : seriesterminationcontrol;

//Connect dynamicterminationcontrol to simulation model if sim_dynamic_termination_control_is_connected is true
wire dynamicterminationcontrol_connected;
assign dynamicterminationcontrol_connected = (sim_dynamic_termination_control_is_connected) ? dynamicterminationcontrol : 1'b1;

//Output buffer logic
always@(i or oe or bus_hold or prev_value or dynamicterminationcontrol_connected or seriesterminationcontrol_shifted or parallelterminationcontrol or devoe)
    begin
        if(oe == 1'b1)
            begin
                if(open_drain_output == 1'b1)
                    begin
                        if(i == 1'b0)
                             begin
                                 out_tmp = 1'b0;
                                 out_tmp_bar = 1'b1;
                                 prev_value = 1'b0;
                             end
                        else
                             begin
                                 out_tmp = 1'bz;
                                 out_tmp_bar = 1'bz;
                             end
                    end
                else
                    begin
                        if( i == 1'b0)
                            begin
                                out_tmp = 1'b0;
                                out_tmp_bar = 1'b1;
                                prev_value = 1'b0;
                            end
                        else if( i == 1'b1)
                            begin
                                out_tmp = 1'b1;
                                out_tmp_bar = 1'b0;
                                prev_value = 1'b1;
                            end
                        else
                            begin
                                out_tmp = i;
                                out_tmp_bar = i;
                            end
                    end
            end
        else if(oe == 1'b0)
            begin
                if(bus_hold == 1'b1)
                    begin
                        out_tmp = prev_value;
                        out_tmp_bar = ~prev_value;
                    end
                else
                    begin
                        out_tmp = 1'bz;
                        out_tmp_bar = 1'bz;
                    end
            end
        else
            begin
                out_tmp = 1'bx;
                out_tmp_bar = 1'bx;
            end
    end

//Output driver control logic
assign tmp = (bus_hold == 1'b1) ? prev_value : out_tmp;
assign tmp_bar = (bus_hold == 1'b1) ? ~prev_value : out_tmp_bar;
assign tmp1 = ((oe == 1'b1) && (dynamicterminationcontrol_connected == 1'b1)) ? ((devoe == 1'b1) ? tmp : 1'bz) : 1'bx; 
assign tmp1_bar =((oe == 1'b1) && (dynamicterminationcontrol_connected == 1'b1)) ? ((devoe == 1'b1) ? tmp_bar : 1'bz) : 1'bx; 

//Output driver
pmos (o, tmp1, 1'b0);
pmos (obar, tmp1_bar, 1'b0);

endmodule

module top_module (
    input [7:0] a, b, c, d,
    output [7:0] max);

    wire [1:0] priority;
    wire [7:0] max1, max2;

    priority_encoder pe1(a, b, c, d, priority);
    functional_module fm1(a, b, c, d, max1);
    functional_module fm2(a, b, c, d, max2);

    mux8to1 mux(max1, max2, priority, max);

endmodule

module priority_encoder (
    input [7:0] a, b, c, d,
    output [1:0] priority);

    wire [7:0] max;
    assign max = {a, b, c, d};

    assign priority = (max[7] == 1) ? 2 :
                     (max[6] == 1) ? 1 :
                     (max[5] == 1) ? 0 :
                     (max[4] == 1) ? 0 :
                     (max[3] == 1) ? 0 :
                     (max[2] == 1) ? 0 :
                     (max[1] == 1) ? 0 :
                     (max[0] == 1) ? 0 : 0;

endmodule

module functional_module (
    input [7:0] a, b, c, d,
    output [7:0] max);

    wire [7:0] max1, max2, max3;

    assign max1 = (a > b) ? a : b;
    assign max2 = (c > d) ? c : d;
    assign max3 = (max1 > max2) ? max1 : max2;

    assign max = max3;

endmodule

module mux8to1 (
    input [7:0] in1, in2,
    input [1:0] sel,
    output [7:0] out);

    assign out = (sel == 2) ? in1 :
                 (sel == 1) ? in2 :
                 in1;

endmodule

module rotator_and (
    input clk,
    input load,
    input [1:0] ena,
    input [99:0] data,
    input d,
    output reg q
);

reg [99:0] rotated_data;
wire [99:0] and_output;

// Left/right rotator
always @ (posedge clk) begin
    if (load) begin
        rotated_data <= data;
    end else if (ena == 2'b01) begin // Right rotate
        rotated_data <= {rotated_data[0], rotated_data[99:1]};
    end else if (ena == 2'b10) begin // Left rotate
        rotated_data <= {rotated_data[98:0], rotated_data[99]};
    end
end

// D flip-flop
always @ (posedge clk) begin
    if (load) begin
        q <= d;
    end else begin
        q <= rotated_data[99];
    end
end

// Bitwise AND operation
assign and_output = rotated_data & data;

endmodule

module gray_to_bcd (
    input clk,
    input reset,   // Synchronous active-high reset
    input [15:0] gray_code, // Input Gray code
    output [3:0] q, // Output BCD code
    output [3:1] ena // Enable signals for upper digits
);

reg [3:0] q; // BCD output
reg [3:1] ena; // Enable signals for upper digits
reg [15:0] gray_reg; // Gray code register
reg [3:0] bcd_reg; // BCD code register

always @(posedge clk) begin
    if (reset) begin
        q <= 4'b0000;
        ena <= 3'b000;
        gray_reg <= 16'b0000;
        bcd_reg <= 4'b0000;
    end else begin
        gray_reg <= gray_code;
        bcd_reg <= {1'b0, gray_reg[15:12]} ^ {1'b0, bcd_reg[3:0]};
        q <= bcd_reg;
        ena <= {1'b0, bcd_reg[7:4]} > {1'b0, bcd_reg[3:0]};
    end
end

endmodule

module dual_edge_ff (
    input clk,
    input reset,   // Synchronous active-high reset
    input d, // Input data
    output reg q // Output data
);

reg q1;

always @(posedge clk) begin
    if (reset) begin
        q <= 1'b0;
        q1 <= 1'b0;
    end else begin
        q1 <= q;
        q <= d;
    end
end

always @(posedge clk or negedge clk) begin
    if (reset) begin
        q <= 1'b0;
    end else begin
        q <= q1;
    end
end

endmodule

module xor_module (
    input [3:0] a,
    input b,
    output reg q
);

always @(a or b) begin
    q <= a[3] ^ a[2] ^ a[1] ^ a[0] ^ b;
end

endmodule

