module select_output (
    clk,
    reset,
    A,
    B,
    C,
    out
);

    input clk, reset, A, B, C;
    output reg out;

    always @(posedge clk, negedge reset) begin
        if(!reset) begin
            out <= 1'b0;
        end else if(B && C) begin
