module debouncer(clk, signal_in, debounce_time, signal_out);
  input clk;
  input signal_in;
  input [31:0] debounce_time;
  output signal_out;

  reg [31:0] debounce_counter;
  reg signal_out_reg;
  reg signal_in_reg;

  always @(posedge clk) begin
    if (signal_in != signal_in_reg) begin
      debounce_counter <= debounce_time;
      signal_in_reg <= signal_in;
    end else if (debounce_counter > 0) begin
      debounce_counter <= debounce_counter - 1;
    end else begin
      debounce_counter <= debounce_time;
      signal_out_reg <= signal_in;
    end
  end

  assign signal_out = signal_out_reg;

endmodule

module adder4(
    input [3:0] A,
    input [3:0] B,
    input C_in,
    output [3:0] S,
    output C_out
);

    wire [3:0] sum;
    wire carry1, carry2, carry3;

    // Full adder for bit 0
    full_adder fa0(.a(A[0]), .b(B[0]), .c_in(C_in), .sum(sum[0]), .c_out(carry1));

    // Full adder for bit 1
    full_adder fa1(.a(A[1]), .b(B[1]), .c_in(carry1), .sum(sum[1]), .c_out(carry2));

    // Full adder for bit 2
    full_adder fa2(.a(A[2]), .b(B[2]), .c_in(carry2), .sum(sum[2]), .c_out(carry3));

    // Full adder for bit 3
    full_adder fa3(.a(A[3]), .b(B[3]), .c_in(carry3), .sum(sum[3]), .c_out(C_out));

    assign S = sum;

endmodule

