full_adder fa5(a[5], b[5], carry0, sum0[5], carry1);

// Seventh stage of adder
full_adder fa6(a[6], b[6], carry1, sum0[6], carry0);

// Eighth stage of adder
full_adder fa7(a[7], b[7], carry0, sum0[7], carry1);

// Final stage of adder
full_adder fa8(carry1, 1'b0, carry1, sum1[0], cout);

// Selecting the output based on carry
mux2to1 mux0(sum0[0], sum1[0], cout, s[0]);
mux2to1 mux1(sum0[1], sum1[1], cout, s[1]);
mux2to1 mux2(sum0[2], sum1[2], cout, s[2]);
