);

reg [3:0] Q_reg;
reg [3:0] Q_next_reg;

always @(posedge CLK) begin
    if (CLR) begin
        Q_reg <= 4'b0;
        Q_next_reg <= 4'b0;
    end
    else if (LOAD) begin
        Q_reg <= D;
        Q_next_reg <= D;
    end
    else begin
        Q_reg <= Q_next_reg;
        Q_next_reg[0] <= Q_reg[3];
        Q_next_reg[1] <= Q_reg[0];
        Q_next_reg[2] <= Q_reg[1];
        Q_next_reg[3] <= Q_reg[2];
    end
end

assign Q = Q_reg;
assign Q_next = Q_next_reg;

endmodule

module modbus_master (
  input clk,
  input rst,
  input start,
  input [7:0] addr,
  input [7:0] func,
  input [15:0] data_in,
  output done,
  output error,
  output [15:0] data_out
);

  parameter IDLE = 2'b00;
  parameter SEND_COMMAND = 2'b01;
  parameter WAIT_FOR_RESPONSE = 2'b10;

  reg [1:0] state;
  reg [15:0] tx_data;
  reg [15:0] rx_data;
  reg done_reg;
  reg error_reg;
  wire [15:0] data_out_reg;

  assign data_out = data_out_reg;

  always @(posedge clk or negedge rst) begin
    if (!rst) begin
      state <= IDLE;
      tx_data <= 16'h0000;
      rx_data <= 16'h0000;
      done_reg <= 1'b0;
      error_reg <= 1'b0;
    end else begin
      case (state)
        IDLE: begin
          if (start) begin
            state <= SEND_COMMAND;
            tx_data <= {addr, func, data_in};
          end
        end
        SEND_COMMAND: begin
          state <= WAIT_FOR_RESPONSE;
        end
        WAIT_FOR_RESPONSE: begin
          if (done_reg) begin
            state <= IDLE;
          end
        end
      endcase
    end
  end

  modbus_slave slave (
    .clk(clk),
    .rst(rst),
    .addr(addr),
    .func(func),
    .data_in(rx_data),
    .done(done_reg),
    .error(error_reg),
    .data_out(data_out_reg)
  );

endmodule
module modbus_slave (
  input clk,
  input rst,
  input [7:0] addr,
  input [7:0] func,
  input [15:0] data_in,
  output done,
  output error,
  output [15:0] data_out
);

  parameter IDLE = 2'b00;
  parameter WAIT_FOR_COMMAND = 2'b01;
  parameter SEND_RESPONSE = 2'b10;

  reg [1:0] state;
  reg [15:0] tx_data;
  reg [15:0] rx_data;
  reg done_reg;
  reg error_reg;
  wire [15:0] data_out_reg;

  assign data_out = data_out_reg;

  always @(posedge clk or negedge rst) begin
    if (!rst) begin
      state <= IDLE;
      tx_data <= 16'h0000;
      rx_data <= 16'h0000;
      done_reg <= 1'b0;
      error_reg <= 1'b0;
    end else begin
      case (state)
        IDLE: begin
          if (addr == 8'h00) begin
            state <= WAIT_FOR_COMMAND;
          end
        end
        WAIT_FOR_COMMAND: begin
          if (func == 8'h03) begin
            state <= SEND_RESPONSE;
            tx_data <= {data_in[15:8], data_in[7:0]};
          end else begin
            error_reg <= 1'b1;
            state <= IDLE;
          end
        end
        SEND_RESPONSE: begin
          state <= IDLE;
        end
      endcase
    end
  end

  assign done = done_reg;
  assign data_out_reg = tx_data;

endmodule

module rsc_encoder (
  input [k-1:0] in,
  input [m-1:0] parity_in,
  output [n-1:0] out,
  output [m-1:0] parity_out
);

parameter k = 256; // number of input bits
parameter n = 768; // number of output bits
parameter m = 64; // number of parity bits
parameter g1 = 7; // first generator polynomial for the RSC encoder
parameter g2 = 11; // second generator polynomial for the RSC encoder

reg [n-1:0] state;
reg [m-1:0] parity;
wire [k-1:0] in_shifted;
wire [n-1:0] out_shifted;
wire [m-1:0] parity_shifted;

assign in_shifted = {in, parity_in};
assign out_shifted = {out, parity};
assign parity_shifted = {parity_out, parity};

always @(*) begin
  case (state)
    0: begin
      out = {in_shifted, in_shifted};
      parity = {in_shifted, in_shifted};
      parity_out = {in_shifted, in_shifted};
      state = 1;
    end
    1: begin
      out = {in_shifted, in_shifted};
      parity = {in_shifted ^ parity[m-1:1], in_shifted ^ parity[m-2:0]};
      parity_out = {in_shifted ^ parity[m-1:1], in_shifted ^ parity[m-2:0]};
      state = 0;
    end
  endcase
end

endmodule

module turbo_decoder (
  input [n-1:0] rec,
  input [m-1:0] parity,
  output [k-1:0] dec
);

parameter k = 256; // number of decoded bits
parameter n = 768; // number of received bits
parameter m = 64; // number of parity bits
parameter g1 = 7; // first generator polynomial for the RSC encoder
parameter g2 = 11; // second generator polynomial for the RSC encoder

reg [n-1:0] state;
reg [k-1:0] dec_temp;
wire [n-1:0] rec_shifted;
wire [k-1:0] dec_shifted;

assign rec_shifted = {rec[m-1:0], rec};
assign dec_shifted = {dec_temp, dec_temp};

always @(*) begin
  case (state)
    0: begin
      dec_temp = rec_shifted[k-1:0];
      state = 1;
    end
    1: begin
      dec_temp = rec_shifted[k-1:0] ^ dec_shifted[k-1:0];
      state = 2;
    end
    2: begin
      dec_temp = rec_shifted[k-1:0];
      state = 0;
    end
  endcase
end

assign dec = dec_temp;

endmodule

module turbo_code (
  input [k-1:0] in,
  input [m-1:0] parity_in,
  input [n-1:0] rec,
  output [k-1:0] dec,
  output [m-1:0] parity_out,
  output [n-1:0] out
);

parameter k = 256; // number of input bits
parameter n = 768; // number of output bits
parameter m = 64; // number of parity bits
parameter g1 = 7; // first generator polynomial for the RSC encoder
parameter g2 = 11; // second generator polynomial for the RSC encoder

