    input SET,
    input RESET,
    output Q,
    output NOT_Q
);

reg Q;
reg NOT_Q;

always @(posedge CLK, negedge SET, negedge RESET) begin
    if (SET == 0 && RESET == 1) begin
        Q <= 1;
        NOT_Q <= 0;
    end else if (SET == 1 && RESET == 0) begin
        Q <= 0;
        NOT_Q <= 1;
    end else begin
        Q <= D;
        NOT_Q <= ~D;
    end
end

endmodule

