module clock (
    input hourClkRate,
    input minClkRate,
    input clk10hz,
    input setM,
    input setH,
    input setButton,
    output reg [3:0] hourMu,
    output reg [3:0] hourTens,
    output reg [3:0] minMu,
    output reg [3:0] minTens,
    output reg colon
);

reg [4:0] hour = 0;
reg [4:0] minute = 0;
reg [3:0] hourMuTemp = 0;
reg [3:0] hourTensTemp = 0;
reg [3:0] minMuTemp = 0;
reg [3:0] minTensTemp = 0;
reg setMode = 0;
reg setModeM = 0;
reg setModeH = 0;
reg setButtonPrev = 1;
reg blink = 0;

always @(posedge clk10hz) begin
    if (setMode) begin
        if (setModeM) begin
            if (setButton != setButtonPrev) begin
                if (setButton) begin
                    if (minMuTemp == 9) begin
                        minMuTemp = 0;
                    end else begin
                        minMuTemp = minMuTemp + 1;
                    end
                end
            end
            blink = ~blink;
        end else if (setModeH) begin
            if (setButton != setButtonPrev) begin
                if (setButton) begin
                    if (hourMuTemp == 9 && hourTensTemp == 2) begin
                        hourMuTemp = 0;
                        hourTensTemp = 0;
                    end else if (hourMuTemp == 9) begin
                        hourMuTemp = 0;
                        hourTensTemp = hourTensTemp + 1;
                    end else begin
                        hourMuTemp = hourMuTemp + 1;
                    end
                end
            end
            blink = ~blink;
        end
    end else begin
        if (minClkRate) begin
            if (minute == 59) begin
                minute = 0;
                if (hour == 23) begin
                    hour = 0;
                end else begin
                    hour = hour + 1;
                end
            end else begin
                minute = minute + 1;
            end
        end
        if (hourClkRate) begin
            if (hour == 23) begin
                hour = 0;
            end else begin
                hour = hour + 1;
            end
        end
        blink = 1;
    end
    setButtonPrev = setButton;
end

always @(posedge clk10hz) begin
    if (blink) begin
        colon = ~colon;
    end
end

always @(posedge clk10hz) begin
    if (setM) begin
        setMode = 1;
        setModeM = 1;
        setModeH = 0;
        minMuTemp = minute % 10;
        minTensTemp = minute / 10;
    end else if (setH) begin
        setMode = 1;
        setModeH = 1;
        setModeM = 0;
        hourMuTemp = hour % 10;
        hourTensTemp = hour / 10;
    end else begin
        setMode = 0;
    end
end

always @(posedge clk10hz) begin
    if (setMode) begin
        hourMu = hourMuTemp;
        hourTens = hourTensTemp;
        minMu = minMuTemp;
        minTens = minTensTemp;
    end else begin
        hourMu = hour % 10;
        hourTens = hour / 10;
        minMu = minute % 10;
        minTens = minute / 10;
    end
end

endmodule

module bm_if_common(clock, reset_n, a_in, b_in, c_in, d_in, out0, out2, out1);

  parameter BITS = 2; // Define the number of bits for the input and output signals

  // SIGNAL DECLARATIONS
  input clock;
  input reset_n;
  input [BITS-1:0] a_in;
  input [BITS-1:0] b_in;
  input c_in;
  input d_in;
  output [BITS-1:0] out0;
  output [BITS-1:0] out2;
  output out1;

  reg [BITS-1:0] out0_reg;
  reg [BITS-1:0] out2_reg;
  reg out1_reg;

  wire [BITS-1:0] temp_a;
  wire [BITS-1:0] temp_b;
  wire temp_c;
  wire temp_d;

  // Instantiate the module 'a' to compute temp_a
  a top_a(clock, a_in, temp_a);

  // Compute the output signals based on the input signals
  always @(posedge clock)
  begin
    if (reset_n == 1'b0)
    begin
      out0_reg <= 2'b00;
      out1_reg <= 1'b0;
    end
    else if (c_in == 1'b0)
    begin
      out0_reg <= 2'b00;
      out1_reg <= 1'b0;
    end
    else
    begin
      out0_reg <= a_in & b_in;
      out1_reg <= c_in & d_in;
    end
    out2_reg <= temp_a;
  end

  // Assign the output signals to the registered values
  assign out0 = out0_reg;
  assign out2 = out2_reg;
  assign out1 = out1_reg;

endmodule

