module fsm_3bit_sequence_detection (
  input clk,
  input reset,
  input data,
  output reg match
);

  // define states
  parameter IDLE = 2'b00;
  parameter FIRST_BIT = 2'b01;
  parameter SECOND_BIT = 2'b10;

  // define current state and next state
  reg [1:0] state, next_state;

  // define internal signal for storing previous data bit
  reg prev_data;

  // define FSM logic
  always @(posedge clk, posedge reset) begin
    if (reset) begin
      state <= IDLE;
      prev_data <= 1'b0;
      match <= 1'b0;
    end else begin
      state <= next_state;
      prev_data <= data;
      match <= 1'b0;
    end
  end

  // define next state logic
  always @* begin
    case(state)
      IDLE: begin
        if (data == 1'b1) begin
          next_state = FIRST_BIT;
        end else begin
          next_state = IDLE;
        end
      end

      FIRST_BIT: begin
        if (prev_data == 1'b0 && data == 1'b1) begin
          next_state = SECOND_BIT;
        end else begin
          next_state = FIRST_BIT;
        end
      end

      SECOND_BIT: begin
        if (prev_data == 1'b0 && data == 1'b0) begin
          next_state = IDLE;
          match = 1'b1;
        end else begin
          next_state = FIRST_BIT;
        end
      end

      default: next_state = IDLE;
    endcase
  end

endmodule

module sequence_detector (
    input A,
    input B,
    input C,
    input D,
    output reg Y
);

    // define states
    parameter IDLE = 2'b00;
    parameter A_STATE = 2'b01;
    parameter AB_STATE = 2'b10;
    parameter ABC_STATE = 2'b11;

    // state register and next state logic
    reg [1:0] state, next_state;
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: if (A) next_state = A_STATE;
            A_STATE: if (B) next_state = AB_STATE;
            AB_STATE: if (C) next_state = ABC_STATE;
            ABC_STATE: if (D) next_state = IDLE;
        endcase
    end

    // output logic
    always @(*) begin
        Y = (state == ABC_STATE);
    end

    // update state
    always @(posedge clk) begin
        state <= next_state;
    end

endmodule

module butterfly_unit(
  input clk,
  input rst_n,
  input wire [7:0] in0,
  input wire [7:0] in1,
  output reg [15:0] out0,
  output reg [15:0] out1,
  output reg bufferout_switch,
  input wire [31:0] twiddlefactors_addr,
  input wire [31:0] bufferout0_addr,
  input wire [31:0] bufferout1_addr,
  input wire readbuf_switch,
  input wire finished,
  input wire last_stage,
  input wire [31:0] out1_addr,
  input wire z_nd,
  input wire [31:0] tf,
  output wire [15:0] bufferX [0:31],
  output wire [15:0] bufferY [0:31],
  output reg [31:0] updatedX,
  output reg [31:0] updatedY,
  output reg bufferout_full_A
);

  // read from.
  // 1 if read from X.
  // 0 if read from Y.
  wire readbuf_switch_z;
  // Delayed content of readbuf_swith_z;
  reg readbuf_switch_z_last;
  // Delayed content of out1_addr_z_old since we need to use
  // it after it may have changed.
  reg [4:0] out1_addr_z_old;
  // The address to write the currently received BF output.
  wire [4:0] out_addr_z;
  assign out_addr_z = (z_nd)?out0_addr_z:out1_addr_z_old;
  // A delayed z_nd. Tells us when to expect ZB.
  reg z_nd_last;
  // For delaying variables. It takes 2 steps to write the output data
  // to the buffer at which point we decide whether to write the data
  // to bufferout. These registers are needed for that decision.
  reg [1:0] finished_old;
  reg last_stage_old;
  reg [1:0] readbuf_switch_old;
  reg bufferout_switch_last;

  initial
  begin
    bufferout_full_A <= 1'b0;
    z_nd_last <= 1'b0;
  end

  always @ (posedge clk or negedge rst_n)
  begin
    if (!rst_n)
    begin
      bufferout_full_A <= 1'b0;
      z_nd_last <= 1'b0;
    end
    else
    begin
      // Put updated reset here so we drive it from same process.
      if ((finished) & (&(out1_addr)))
      begin
        if (readbuf_switch)
          updatedX <= {32{1'b0}};
        else
          updatedY <= {32{1'b0}};
      end

      // Set all the delays.
      readbuf_switch_z_last <= readbuf_switch_z;
      finished_old[0] <= finished;
      finished_old[1] <= finished_old[0];
      last_stage_old <= last_stage;
      readbuf_switch_old[0] <= readbuf_switch;
      readbuf_switch_old[1] <= readbuf_switch_old[0];
      out1_addr_z_old <= out1_addr_z;
      z_nd_last <= z_nd;

      if (finished_old[1])
      begin
        // We have filled the output buffer
        bufferout_full_A <= ~bufferout_full_A;
      end

      // Write received data to the buffers and set updated flag.
      if (z_nd | z_nd_last)
      begin
        if ((last_stage_old & z_nd)|(last_stage & ~z_nd))
        begin
          if (bufferout_switch_last)
            bufferout0[bufferout0_addr] <= out0;
          else
            bufferout1[bufferout1_addr] <= out1;
        end
        else
        begin
          if ((readbuf_switch_old[0] & z_nd)|(readbuf_switch & ~z_nd))
          begin
            bufferY[out_addr_z] <= in1;
            updatedY[out_addr_z] <= 1'b1;
          end
          else
          begin
            bufferX[out_addr_z] <= in0;
            updatedX[out_addr_z] <= 1'b1;
          end
        end
      end

      // Update readbuf_switch_z.
      if (finished_old[0])
      begin
        readbuf_switch_z <= ~readbuf_switch_z;
      end

      // Update bufferout_switch.
      if (finished_old[1])
      begin
        bufferout_switch_last <= ~bufferout_switch_last;
        bufferout_switch <= bufferout_switch_last;
      end
    end
  end

  /* Instantiate twiddle factor unit. */
  twiddlefactors twiddlefactors_0 (
    .clk (clk),
    .addr (twiddlefactors_addr),
    .tf_out (tf)
  );

  /* Instantiate the generic butterfly unit. */
  butterfly #(
    .M_WDTH (3 + 2*5),
    .X_WDTH (8)
  )
  butterfly_0 (
    .clk (clk),
    .rst_n (rst_n),
    .m_in ({readbuf_switch_old[0], out0_addr, out1_addr, finished_old[0], last_stage_old}),
    .w (tf),
    .xa (in0),
    .xb (in1),
    .x_nd (1'b0),
    .m_out ({readbuf_switch_z, out0_addr_z, out1_addr_z, finished, last_stage}),
    .y ({out0, out1}),
    .y_nd (1'b0)
  );

endmodule

