module moore_state_machine (
  input [n-1:0] in,
  output [m-1:0] out,
  input clk,
  input rst
);

  // Define the states
  parameter S0 = 2'b00;
  parameter S1 = 2'b01;
  parameter S2 = 2'b10;
  parameter S3 = 2'b11;

  // Define the inputs
  parameter I0 = 1'b0;
  parameter I1 = 1'b1;

  // Define the outputs
  parameter O0 = 1'b0;
  parameter O1 = 1'b1;

  // Define the state register and next state logic
  reg [1:0] state, next_state;
  always @(posedge clk, negedge rst) begin
    if (~rst) begin
      state <= S0;
    end else begin
      state <= next_state;
    end
  end

  // Define the output logic
  always @(state) begin
    case (state)
      S0: out = {O0, O0};
      S1: out = {O0, O1};
      S2: out = {O1, O0};
      S3: out = {O1, O1};
    endcase
  end

  // Define the next state logic
  always @(state, in) begin
    case (state)
      S0: if (in == I0) next_state = S1; else next_state = S2;
      S1: if (in == I0) next_state = S0; else next_state = S3;
      S2: if (in == I0) next_state = S3; else next_state = S0;
      S3: if (in == I0) next_state = S2; else next_state = S1;
    endcase
  end

endmodule

