    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output reg [3:0] q
);

reg [3:0] mux_out;
reg [3:0] shift_reg;

always @(*) begin
    case(sel)
        2'b00: mux_out = {data1, data0};
        2'b01: mux_out = {data3, data2};
        2'b10: mux_out = {data5, data4};
        default: mux_out = 4'b0;
    endcase
end

always @(posedge clk or negedge areset_n) begin
    if(!areset_n) begin
        shift_reg <= 4'b0;
    end else if(ena) begin
        shift_reg <= {shift_reg[2:0], mux_out};
    end else if(!ena && en) begin
        shift_reg <= {data3, data2, data1, data0};
    end
end

assign q = shift_reg;

endmodule

module d_flip_flop_with_reset_and_set(
    input D, RESET_B, VPWR, VGND, VPB, VNB, CLK,
    output Q, Q_N
);

