    sky130_fd_sc_hd__nand2 nand1 (.A(VGND), .B(VNB), .ZN(VGND_N));
    sky130_fd_sc_hd__nand2 nand2 (.A(VPB), .B(VNB), .ZN(VNB_N));
    sky130_fd_sc_hd__nand2 nand3 (.A(VPB_N), .B(VPWR), .ZN(VPWR_N));
    sky130_fd_sc_hd__nand2 nand4 (.A(VGND_N), .B(RESET_B), .ZN(RESET_B_N));
