    sky130_fd_sc_hd__and2 and1 (.A(RESET_B_N), .B(D), .ZN(D_N));

    sky130_fd_sc_hd__or2 or1 (.A(RESET_B_N), .B(VGND_N), .ZN(Q_N));

    sky130_fd_sc_hd__and2 and2 (.A(Q), .B(VPWR_N), .ZN(Q_N));

    sky130_fd_sc_hd__or2 or2 (.A(VPWR_N), .B(Q_N), .ZN(Q));

endmodule

