module top_module(
    input clk,
    input reset,
    input [3:0] in,
    input [7:0] sel,
    input [1:0] ena,
    input load,
    input select,
    output [3:0] q);

    wire [3:0] barrel_shift_out;
    wire [3:0] mux_out;
    wire [3:0] or_out;

    barrel_shifter barrel_shift(
        .clk(clk),
        .reset(reset),
        .in(in),
        .shift_sel(sel),
        .out(barrel_shift_out)
    );

    mux_256to1 mux(
        .sel(select ? sel : 8'hFF),
        .in_0(barrel_shift_out),
        .in_1(mux_out),
        .out(mux_out)
    );

    or_gate or_op(
        .in_0(barrel_shift_out),
        .in_1(mux_out),
        .out(or_out)
    );

    reg [3:0] q_reg;

    always @(posedge clk) begin
        if (reset) begin
            q_reg <= 4'b0000;
        end else if (load) begin
            q_reg <= in;
        end else if (ena) begin
            q_reg <= or_out;
        end
    end

    assign q = q_reg;

endmodule

module barrel_shifter(
    input clk,
    input reset,
    input [3:0] in,
    input [7:0] shift_sel,
    output [3:0] out
);

    reg [3:0] out_reg;

    always @(posedge clk) begin
        if (reset) begin
            out_reg <= 4'b0000;
        end else begin
            out_reg <= in << shift_sel[3:0];
        end
    end

    assign out = out_reg;

endmodule

module mux_256to1(
    input [7:0] sel,
    input [3:0] in_0,
    input [3:0] in_1,
    output [3:0] out
);

    reg [3:0] out_reg;

    always @(*) begin
        case (sel)
            8'h00: out_reg = in_0;
            8'h01: out_reg = in_1;
            // Add remaining cases for 254 inputs
            8'hFE: out_reg = in_1;
            8'hFF: out_reg = in_0;
        endcase
    end

    assign out = out_reg;

endmodule

module or_gate(
    input [3:0] in_0,
    input [3:0] in_1,
    output [3:0] out
);

    assign out = in_0 | in_1;

endmodule

module thirty_two_bit_byteenable_FSM (
  clk,
  reset,

  write_in,
  byteenable_in,
  waitrequest_out,

  byteenable_out,
  waitrequest_in
);

  input clk;
  input reset;

  input write_in;
  input [3:0] byteenable_in;
  output wire waitrequest_out;

  output wire [3:0] byteenable_out; 
  input waitrequest_in;

  // internal statemachine signals
  wire partial_lower_half_transfer;
  wire full_lower_half_transfer;
  wire partial_upper_half_transfer;
  wire full_upper_half_transfer;
  wire full_word_transfer;
  reg state_bit;
  wire transfer_done;
  wire advance_to_next_state;
  wire lower_enable;
  wire upper_enable;
  wire lower_stall;
  wire upper_stall;
  wire two_stage_transfer;

  // FSM states
  localparam IDLE_STATE = 1'b0;
  localparam LOWER_HALF_TRANSFER_STATE = 1'b1;
  localparam UPPER_HALF_TRANSFER_STATE = 1'b10;
  localparam FULL_TRANSFER_STATE = 1'b11;

  // FSM state register
  reg [1:0] state_reg;
  always @ (posedge clk or posedge reset) begin
    if (reset) begin
      state_reg <= IDLE_STATE;
    end
    else begin
      case (state_reg)
        IDLE_STATE: begin
          if (transfer_done == 1 && waitrequest_in == 0 && write_in == 1) begin
            if (full_word_transfer == 1) begin
              state_reg <= FULL_TRANSFER_STATE;
            end
            else if (two_stage_transfer == 1) begin
              state_reg <= LOWER_HALF_TRANSFER_STATE;
            end
          end
        end
        LOWER_HALF_TRANSFER_STATE: begin
          if (transfer_done == 1 && waitrequest_in == 0 && write_in == 1) begin
            if (full_upper_half_transfer == 1) begin
              state_reg <= FULL_TRANSFER_STATE;
            end
            else if (partial_upper_half_transfer == 1) begin
              state_reg <= UPPER_HALF_TRANSFER_STATE;
            end
          end
        end
        UPPER_HALF_TRANSFER_STATE: begin
          if (transfer_done == 1 && waitrequest_in == 0 && write_in == 1) begin
            if (full_lower_half_transfer == 1) begin
              state_reg <= FULL_TRANSFER_STATE;
            end
            else if (partial_lower_half_transfer == 1) begin
              state_reg <= LOWER_HALF_TRANSFER_STATE;
            end
          end
        end
        FULL_TRANSFER_STATE: begin
          if (transfer_done == 1 && waitrequest_in == 0 && write_in == 1) begin
            if (two_stage_transfer == 1) begin
              state_reg <= LOWER_HALF_TRANSFER_STATE;
            end
            else begin
              state_reg <= IDLE_STATE;
            end
          end
        end
      endcase
    end
  end

  // FSM outputs
  assign waitrequest_out = (waitrequest_in == 1) | ((transfer_done == 0) & (write_in == 1));
  assign byteenable_out = (state_reg == LOWER_HALF_TRANSFER_STATE) ? byteenable_in[1:0] :
                          (state_reg == UPPER_HALF_TRANSFER_STATE) ? byteenable_in[3:2] :
                          (state_reg == FULL_TRANSFER_STATE) ? 4'hf : 4'b0;

  // FSM state transitions
  assign partial_lower_half_transfer = (byteenable_in[1:0] != 0);
  assign full_lower_half_transfer = (byteenable_in[1:0] == 2'h3);
  assign partial_upper_half_transfer = (byteenable_in[3:2] != 0);
  assign full_upper_half_transfer = (byteenable_in[3:2] == 2'h3);
  assign full_word_transfer = (full_lower_half_transfer == 1) & (full_upper_half_transfer == 1);
  assign two_stage_transfer = (full_word_transfer == 0) & (partial_lower_half_transfer == 1) & (partial_upper_half_transfer == 1);

  assign advance_to_next_state = (two_stage_transfer == 1) & (lower_stall == 0) & (write_in == 1) & (state_reg == IDLE_STATE) & (waitrequest_in == 0);

  assign transfer_done = ((full_word_transfer == 1) & (waitrequest_in == 0) & (write_in == 1)) | // full word transfer complete
                         ((two_stage_transfer == 0) & (lower_stall == 0) & (upper_stall == 0) & (write_in == 1) & (waitrequest_in == 0)) | // partial upper or lower half transfer complete
                         ((two_stage_transfer == 1) & (state_reg == UPPER_HALF_TRANSFER_STATE) & (upper_stall == 0) & (write_in == 1) & (waitrequest_in == 0));  // partial upper and lower half transfers complete

  assign lower_enable = ((write_in == 1) & (full_word_transfer == 1)) |  // full word transfer
                        ((write_in == 1) & (two_stage_transfer == 0) & (partial_lower_half_transfer == 1)) | // only a partial lower half transfer
                        ((write_in == 1) & (two_stage_transfer == 1) & (partial_lower_half_transfer == 1) & (state_reg == IDLE_STATE));  // partial lower half transfer (to be followed by an upper half transfer)

  assign upper_enable = ((write_in == 1) & (full_word_transfer == 1)) |  // full word transfer
                        ((write_in == 1) & (two_stage_transfer == 0) & (partial_upper_half_transfer == 1)) | // only a partial upper half transfer
                        ((write_in == 1) & (two_stage_transfer == 1) & (partial_upper_half_transfer == 1) & (state_reg == UPPER_HALF_TRANSFER_STATE));  // partial upper half transfer (after the lower half transfer)

  sixteen_bit_byteenable_FSM lower_sixteen_bit_byteenable_FSM (
    .write_in (lower_enable),
    .byteenable_in (byteenable_in[1:0]),
    .waitrequest_out (lower_stall),    
    .byteenable_out (byteenable_out[1:0]),
    .waitrequest_in (waitrequest_in)
  );

  sixteen_bit_byteenable_FSM upper_sixteen_bit_byteenable_FSM (
    .write_in (upper_enable),
    .byteenable_in (byteenable_in[3:2]),
    .waitrequest_out (upper_stall),    
    .byteenable_out (byteenable_out[3:2]),
    .waitrequest_in (waitrequest_in)
  );

endmodule

