module top_module (
    input clk,
    input reset,            // Asynchronous reset
    input [3:0] a,
    input [3:0] b,
    input [3:0] a_comp,
    input [3:0] b_comp,
    output [3:0] diff
);

    // Instantiate the subtraction module
    subtractor sub(
        .a(a_comp),
        .b(b),
        .diff(diff_sub)
    );

    // Instantiate the D flip-flop module
    d_flip_flop_4bit dff(
        .clk(clk),
        .reset(reset),
        .data(diff_sub),
        .q(diff_reg)
    );

    // Define the states for the FSM
    parameter IDLE = 2'b00;
    parameter SUBTRACT = 2'b01;
    parameter ABSOLUTE = 2'b10;

    // Define the inputs and outputs for the FSM
    reg [1:0] state;
    wire subtract_done;
    wire [3:0] abs_diff;

    // FSM
    always @ (posedge clk, posedge reset) begin
        if (reset) begin
            state <= IDLE;
        end else begin
            case (state)
                IDLE: begin
                    diff <= 4'b0;
                    if (a != b) begin
                        state <= SUBTRACT;
                    end
                end
                SUBTRACT: begin
                    sub.a <= a;
                    sub.b <= b_comp;
                    state <= ABSOLUTE;
                end
                ABSOLUTE: begin
                    subtract_done <= sub.done;
                    if (subtract_done) begin
                        if (diff_reg[3] == 1) begin
                            abs_diff <= ~diff_reg + 1;
                        end else begin
                            abs_diff <= diff_reg;
                        end
                        diff <= abs_diff;
                        state <= IDLE;
                    end
                end
            endcase
        end
    end

    // Define the signals for the subtraction module
    wire [3:0] diff_sub;

    // Define the signals for the D flip-flop module
    reg [3:0] diff_reg;

    // Instantiate the subtraction module
    subtractor sub(
        .a(a_comp),
        .b(b),
        .diff(diff_sub)
    );

    // Instantiate the D flip-flop module
    d_flip_flop_4bit dff(
        .clk(clk),
        .reset(reset),
        .data(diff_sub),
        .q(diff_reg)
    );

endmodule

// Subtraction module
module subtractor (
    input [3:0] a,
    input [3:0] b,
    output reg [3:0] diff,
    output reg done
);

    // Perform subtraction
    always @ (*) begin
        diff <= a - b;
        done <= 1;
    end

endmodule

// D flip-flop module
module d_flip_flop_4bit (
    input clk,
    input reset,
    input [3:0] data,
    output reg [3:0] q
);

    // Define the D flip-flops
    always @ (posedge clk, posedge reset) begin
        if (reset) begin
            q <= 4'b0;
        end else begin
            q <= data;
        end
    end

endmodule

module I2C (
  input SDA,
  input SCL,
  input rst,
  output [2:0] state,
  output ack
);

  // Define the states
  parameter IDLE = 3'b000;
  parameter START = 3'b001;
  parameter WRITE = 3'b010;
  parameter READ = 3'b011;
  parameter ACK = 3'b100;
  parameter NACK = 3'b101;

  // Define the state register
  reg [2:0] current_state;

  // Define the acknowledge register
  reg ack_reg;

  // Define the slave address and R/W bit
  reg [6:0] slave_address;
  reg rw_bit;

  // Define the data buffer
  reg [7:0] data_buffer;
  reg [2:0] data_index;

  // Define the start condition flag
  reg start_condition;

  // Define the SDA and SCL signals
  reg sda_signal;
  reg scl_signal;

  // Define the SDA and SCL signal delays
  parameter DELAY = 10;
  reg [3:0] delay_counter;

  // Define the state machine
  always @(posedge SCL or posedge rst) begin
    if (rst) begin
      current_state <= IDLE;
      ack_reg <= 1'b0;
      slave_address <= 7'b0000000;
      rw_bit <= 1'b0;
      data_buffer <= 8'b0;
      data_index <= 3'b000;
      start_condition <= 1'b0;
      sda_signal <= 1'b1;
      scl_signal <= 1'b1;
      delay_counter <= 4'b0000;
    end else begin
      case (current_state)
        IDLE: begin
          if (start_condition) begin
            current_state <= START;
          end
        end
        START: begin
          if (delay_counter < DELAY) begin
            delay_counter <= delay_counter + 1;
          end else begin
            delay_counter <= 4'b0000;
            sda_signal <= 1'b0;
            scl_signal <= 1'b0;
            current_state <= WRITE;
          end
        end
        WRITE: begin
          if (delay_counter < DELAY) begin
            delay_counter <= delay_counter + 1;
          end else begin
            delay_counter <= 4'b0000;
            if (data_index == 3'b000) begin
              slave_address <= {1'b0, SDA};
              data_index <= data_index + 1;
            end else if (data_index == 3'b001) begin
              slave_address <= {slave_address[5:0], SDA};
              data_index <= data_index + 1;
            end else if (data_index == 3'b010) begin
              slave_address <= {slave_address[5:0], SDA};
              data_index <= data_index + 1;
            end else if (data_index == 3'b011) begin
              rw_bit <= SDA;
              data_index <= data_index + 1;
            end else if (data_index == 3'b100) begin
              ack_reg <= ~SDA;
              if (ack_reg) begin
                current_state <= ACK;
              end else begin
                current_state <= NACK;
              end
              data_index <= 3'b000;
            end
          end
        end
        READ: begin
          // Not implemented
        end
        ACK: begin
          if (delay_counter < DELAY) begin
            delay_counter <= delay_counter + 1;
          end else begin
            delay_counter <= 4'b0000;
            sda_signal <= 1'b1;
            scl_signal <= 1'b1;
            current_state <= IDLE;
          end
        end
        NACK: begin
          if (delay_counter < DELAY) begin
            delay_counter <= delay_counter + 1;
          end else begin
            delay_counter <= 4'b0000;
            sda_signal <= 1'b1;
            scl_signal <= 1'b1;
            current_state <= IDLE;
          end
        end
      endcase
    end
  end

  // Generate the SDA and SCL signals
  always @(posedge SCL or posedge rst) begin
    if (rst) begin
      sda_signal <= 1'b1;
      scl_signal <= 1'b1;
    end else begin
      case (current_state)
        IDLE: begin
          sda_signal <= 1'b1;
          scl_signal <= 1'b1;
        end
        START: begin
          sda_signal <= sda_signal;
          scl_signal <= scl_signal;
        end
        WRITE: begin
          sda_signal <= data_buffer[data_index];
          scl_signal <= scl_signal;
        end
        READ: begin
          // Not implemented
        end
        ACK: begin
          sda_signal <= sda_signal;
          scl_signal <= scl_signal;
        end
        NACK: begin
          sda_signal <= sda_signal;
          scl_signal <= scl_signal;
        end
      endcase
    end
  end

  // Assign the state and acknowledge signals
  assign state = current_state;
  assign ack = ack_reg;

endmodule

