  full_adder FA2(.A(A[1]), .B(B[1]), .Cin(C1), .S(sum[1]), .Cout(C2));
  full_adder FA3(.A(A[2]), .B(B[2]), .Cin(C2), .S(sum[2]), .Cout(C3));
  full_adder FA4(.A(A[3]), .B(B[3]), .Cin(C3), .S(sum[3]), .Cout(Cout));

