module alu_32bit (
    input [31:0] a,
    input [31:0] b,
    input [3:0] ctrl,
    output [31:0] result
);

reg [31:0] result_reg;

always @(*) begin
    case(ctrl)
        4'b0000: result_reg = a + b;
        4'b0001: result_reg = a - b;
        4'b0010: result_reg = a & b;
        4'b0011: result_reg = a | b;
        4'b0100: result_reg = a ^ b;
        4'b0101: result_reg = a << 1;
        4'b0110: result_reg = a >> 1;
        default: result_reg = 32'b0;
    endcase
end

assign result = result_reg;

endmodule

module adder_subtractor_8bit (
    input [7:0] a,
    input [7:0] b,
    input ctrl,
    output [7:0] result,
    output overflow
);

reg [7:0] result_reg;
reg overflow_reg;

always @(*) begin
    if (ctrl) begin
        result_reg = a - b;
        overflow_reg = (a[7] & ~b[7] & result_reg[7]) | (~a[7] & b[7] & ~result_reg[7]);
    end else begin
        result_reg = a + b;
        overflow_reg = (a[7] & b[7] & ~result_reg[7]) | (~a[7] & ~b[7] & result_reg[7]);
    end
end

assign result = result_reg;
assign overflow = overflow_reg;

endmodule

