module add_sub_pipeline(
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] sum
);

    wire [15:0] a_lsb;
    wire [15:0] b_lsb;
    wire [15:0] a_msb;
    wire [15:0] b_msb;
    wire [15:0] sum_lsb;
    wire [15:0] sum_msb;
    wire cin_msb;
    wire cin_lsb;

    // Split inputs into 16-bit chunks
    assign a_lsb = a[15:0];
    assign b_lsb = b[15:0];
    assign a_msb = a[31:16];
    assign b_msb = b[31:16];

    // Invert b if sub is 1
    assign b_lsb = (sub) ? ~b_lsb : b_lsb;
    assign b_msb = (sub) ? ~b_msb : b_msb;

    // Convert sub to 2's complement and connect to carry-in
    twos_complement twos_comp(.in(sub), .out(cin_msb));

    // Instantiate two 16-bit adder modules
    adder16 adder_lsb(.a(a_lsb), .b(b_lsb), .cin(cin_lsb), .sum(sum_lsb));
    adder16 adder_msb(.a(a_msb), .b(b_msb), .cin(cin_msb), .sum(sum_msb));

    // Combine the results from the two adders
    assign sum = {sum_msb, sum_lsb};

endmodule

