reg [3:0] b_reg;

always @ (A or B) begin
    a_reg = A;
    b_reg = B;

    while (a_reg != b_reg) begin
        if (a_reg > b_reg) begin
            a_reg = a_reg - b_reg;
        end else begin
            b_reg = b_reg - a_reg;
        end
    end

    GCD = a_reg;
end

