module digital_circuit (
  start,
  A,
  B,
  nCVi,
  Ci,
  nCVo,
  Co,
  sum
);
  input start;
  input A;
  input B;
  input nCVi;
  input Ci;
  output nCVo;
  output Co;
  output sum;

  wire ha;
  wire cv;
  wire cvi;
  wire cvi_not;
  wire ncv;
  wire ncv_not;
  wire xor_ab;

  // Calculate the sum of A, B, and Ci
  full_adder fa1 (sum, A, B, Ci);

  // Calculate A XOR B
  xor x1 (xor_ab, A, B);

  // If nCVo is high, output the result of a multiplexer on the Co output.
  // The two inputs to the multiplexer are A and Ci, and the select input is
  // the output of an exclusive OR gate (A XOR B).
  mux2 m1 (Co, A, Ci, ha);
  and a1 (ha, A, B);

  // If nCVi is high, pass the start input through a NOT gate and output the
  // result on the nCVo output. Otherwise, output nCVi on the nCVo output.
  not n1 (cvi_not, start);
  and a2 (cvi, start, nCVi);
  or o1 (ncv, cvi, cvi_not);
  not n2 (ncv_not, ncv);
  and a3 (nCVo, ncv_not, nCVo);
endmodule

module full_adder (
  sum,
  A,
  B,
  Ci
);
  input A;
  input B;
  input Ci;
  output sum;
  wire a_xor_b;
  wire b_xor_cin;
  wire a_xor_b_and_b_xor_cin;

  // Calculate A XOR B
  xor x1 (a_xor_b, A, B);

  // Calculate B XOR Ci
  xor x2 (b_xor_cin, B, Ci);

  // Calculate (A XOR B) AND (B XOR Ci)
  and a1 (a_xor_b_and_b_xor_cin, a_xor_b, b_xor_cin);

  // Calculate the sum
  xor x3 (sum, a_xor_b, Ci);

  // Calculate the carry out
  or o1 (Ci, a_xor_b_and_b_xor_cin);
endmodule

