module glitch_filter (
  input clk,
  input in,
  output out
);

  parameter n = 10; // number of clock cycles to wait

  reg [n-1:0] counter;
  reg input_reg;

  always @(posedge clk) begin
    if (counter == n-1) begin
      out <= input_reg;
    end
    else begin
      out <= 0;
    end

    if (in != input_reg) begin
      counter <= 0;
    end
    else if (counter < n-1) begin
      counter <= counter + 1;
    end

    input_reg <= in;
  end

endmodule

