    input CLK,
    input LOAD,
    input UP,
    input DOWN,
    input [7:0] input_data,
    output reg [15:0] output_data
);

reg [3:0] counter;

always @(posedge CLK) begin
    if (LOAD) begin
        counter <= input_data[3:0];
    end else if (UP) begin
        counter <= counter + 1;
    end else if (DOWN) begin
        counter <= counter - 1;
    end else begin
        counter <= 4'b0;
    end
