module edge_arithmetic (
  input clk,
  input rst_n,
  input [31:0] a,
  input [31:0] b,
  input sub,
  output reg rise,
  output reg [31:0] sum
);

  reg [31:0] a_reg, b_reg;
  reg [31:0] a_dif, b_dif;
  reg [31:0] sum_add, sum_sub;
  wire [31:0] xor_out;
  wire [31:0] carry_out;

  assign xor_out = a_dif ^ b_dif;
  assign carry_out = a_dif & b_dif;

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      a_reg <= 0;
      b_reg <= 0;
      rise <= 0;
      sum <= 0;
    end else begin
      a_reg <= a;
      b_reg <= b;
      a_dif <= a_reg ^ {1'b0, a_reg[31:1]};
      b_dif <= b_reg ^ {1'b0, b_reg[31:1]};
      sum_add <= a_reg + b_reg;
      sum_sub <= a_reg - b_reg;
      if (sub) begin
        sum <= sum_sub;
      end else begin
        sum <= sum_add;
      end
      if (a_dif[0] & b_dif[0]) begin
        rise <= 0;
      end else if (~a_dif[0] & b_dif[0]) begin
        rise <= 1;
      end else if (a_dif[0] & ~b_dif[0]) begin
        rise <= 1;
      end else begin
        rise <= 0;
      end
    end
  end

endmodule

module top_module( 
    input [3:0] a, b, c, d,
    output cout, sum );

    wire [3:0] fa_out;
    wire fa_cout;

    // Full Adder Module
    full_adder fa1(.a(a), .b(b), .cin(1'b0), .sum(fa_out[0]), .cout(fa_cout));
    full_adder fa2(.a(c), .b(fa_out[0]), .cin(fa_cout), .sum(fa_out[1]), .cout(fa_cout));
    full_adder fa3(.a(d), .b(fa_out[1]), .cin(fa_cout), .sum(fa_out[2]), .cout(fa_cout));

    // Ripple-Carry Adder
    ripple_carry_adder rca(.a(fa_out), .b(d), .cout(cout), .sum(sum));

endmodule

module full_adder( 
    input a, b, cin,
    output sum, cout );

    assign sum = a ^ b ^ cin;
    assign cout = (a & b) | (a & cin) | (b & cin);

endmodule

module ripple_carry_adder( 
    input [3:0] a, b,
    output cout, sum );

    wire [3:0] carry;

    assign sum = a + b;

    assign carry[0] = (a[0] & b[0]);
    assign carry[1] = (a[1] & b[1]) | (a[0] & b[0]);
    assign carry[2] = (a[2] & b[2]) | (a[1] & b[1]) | (a[0] & b[0]);
    assign carry[3] = (a[3] & b[3]) | (a[2] & b[2]) | (a[1] & b[1]) | (a[0] & b[0]);

    assign cout = carry[3];

endmodule

module edge_detection_counter (
  input               clk,
  input               rst_n,
  input               a,
  output reg          rise,
  output reg          down,
  output reg [1:0]    count
);

  reg a_prev;
  reg a_curr;

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      a_prev <= 1'b0;
      a_curr <= 1'b0;
      rise <= 1'b0;
      down <= 1'b0;
      count <= 2'b00;
    end else begin
      a_prev <= a_curr;
      a_curr <= a;
      if (a_curr && !a_prev) begin
        rise <= 1'b1;
        down <= 1'b0;
        if (count == 2'b11) begin
          count <= 2'b00;
        end else begin
          count <= count + 1;
        end
      end else if (!a_curr && a_prev) begin
        rise <= 1'b0;
        down <= 1'b1;
      end else begin
        rise <= 1'b0;
        down <= 1'b0;
      end
    end
  end

endmodule

