module diff_output_buffer #(
  parameter [0:0] REFCLK_EN_TX_PATH = 1'b0,
  parameter [4:0] REFCLK_ICNTL_TX = 5'b00000
)(
  output O,
  output OB,
  input CEB,
  input [3:0] I,
  input [1:0] RXRECCLK_SEL
);

  reg I_delay;

  // Parameter encodings and registers
  localparam MODULE_NAME = "diff_output_buffer";
  `ifndef XIL_DR
  localparam [0:0] REFCLK_EN_TX_PATH_REG = REFCLK_EN_TX_PATH;
  localparam [4:0] REFCLK_ICNTL_TX_REG = REFCLK_ICNTL_TX;
  `endif

  wire REFCLK_EN_TX_PATH_BIN;
  wire [4:0] REFCLK_ICNTL_TX_BIN;

  assign REFCLK_EN_TX_PATH_BIN = REFCLK_EN_TX_PATH_REG;
  assign REFCLK_ICNTL_TX_BIN = REFCLK_ICNTL_TX_REG;

  // Error checking
  always @* begin
    if ((REFCLK_EN_TX_PATH_REG !== 1'b0) && (REFCLK_EN_TX_PATH_REG !== 1'b1)) begin
      $display("Error: [Unisim %s-101] REFCLK_EN_TX_PATH attribute is set to %b. Legal values for this attribute are 1'b0 to 1'b1. Instance: %m", MODULE_NAME, REFCLK_EN_TX_PATH_REG);
      $finish;
    end
    if ((REFCLK_ICNTL_TX_REG < 5'b00000) || (REFCLK_ICNTL_TX_REG > 5'b11111)) begin
      $display("Error: [Unisim %s-102] REFCLK_ICNTL_TX attribute is set to %b. Legal values for this attribute are 5'b00000 to 5'b11111. Instance: %m", MODULE_NAME, REFCLK_ICNTL_TX_REG);
      $finish;
    end
  end

  // Generate I_delay
  always @* begin
    case (RXRECCLK_SEL)
      2'b00: I_delay = I[0];
      2'b01: I_delay = I[1];
      2'b10: I_delay = I[2];
      2'b11: I_delay = I[3];
      default: I_delay = I[0];
    endcase
  end

  // Generate differential output
  bufif0 buf (O, I_delay, ~REFCLK_EN_TX_PATH_BIN & CEB);
  notif0 notif (OB, I_delay, ~REFCLK_EN_TX_PATH_BIN & CEB);

endmodule

module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [255:0] in, // 256-bit input for the multiplexer
    input [7:0] sel,  // 8-bit select signal for the multiplexer
    input load,        // Load signal for the rotator
    input [1:0] ena,   // 2-bit enable signal for the rotator
    input [99:0] data, // 100-bit input data for the rotator
    output reg [1:0] q // 2-bit output from the functional module
);

reg [255:0] mux_out;
reg [99:0] rot_out;

// 256-to-1 multiplexer
always @ (sel)
begin
    case (sel)
        8'b00000000: mux_out = in[0];
        8'b00000001: mux_out = in[1];
        // ...
        8'b11111110: mux_out = in[254];
        8'b11111111: mux_out = in[255];
    endcase
end

// 100-bit rotator
always @ (posedge clk)
begin
    if (reset) rot_out <= 0;
    else if (load) rot_out <= data;
    else if (ena == 2'b00) rot_out <= {rot_out[98:0], rot_out[99]};
    else if (ena == 2'b01) rot_out <= {rot_out[99], rot_out[98:0]};
end

// Functional module
always @ (mux_out, rot_out)
begin
    q <= {mux_out, rot_out} + q;
end

endmodule

module top_module(
    input clk,                  // Clock signal
    input [7:0] in,             // 8-bit input vector
    input select,               // Select input to choose between module outputs
    output [7:0] out            // 8-bit final output
);

    reg [7:0] reverse_out;      // Output of shift register that reverses bit order
    reg [7:0] shift_out;        // Output of 3-bit shift register
    reg [2:0] shift_reg;        // 3-bit shift register implemented using D flip-flops
    wire [7:0] and_out;         // Output of bitwise AND operation between shift registers

    // Shift register that reverses bit order
    always @ (posedge clk) begin
        reverse_out <= {in[7], in[6], in[5], in[4], in[3], in[2], in[1], in[0]};
    end

    // 3-bit shift register implemented using D flip-flops and multiplexer
    always @ (posedge clk) begin
        if (select) begin
            shift_out <= reverse_out;
        end else begin
            shift_reg <= {shift_reg[1:0], in[7]};
            shift_out <= {shift_reg[2], shift_reg[1], shift_reg[0], 0, 0, 0, 0, 0};
        end
    end

    // Bitwise AND operation between shift registers
    assign and_out = reverse_out & shift_out;

    // Output selection based on select input
    assign out = select ? reverse_out : and_out;

endmodule

