module traffic_light_controller(clk, rst, walk_btn, car_sensor, car_red, car_green, pedestrian_red, pedestrian_green);
    input clk, rst, walk_btn, car_sensor;
    output reg car_red, car_green, pedestrian_red, pedestrian_green;
    reg [1:0] state = 2'b00; // initial state

    parameter car_green_time = 5; // time for car traffic light to be green
    parameter pedestrian_green_time = 3; // time for pedestrian traffic light to be green

