        if (rst) begin
            car_red <= 1'b1;
            car_green <= 1'b0;
            pedestrian_red <= 1'b1;
            pedestrian_green <= 1'b0;
            state <= 2'b00;
        end
        else begin
            case (state)
                2'b00: begin // car green, pedestrian red
                    car_red <= 1'b0;
                    car_green <= 1'b1;
                    pedestrian_red <= 1'b1;
                    pedestrian_green <= 1'b0;
                    if (walk_btn) begin
                        state <= 2'b01; // pedestrian green, car red
                    end
                    else if (car_sensor) begin
                        state <= 2'b10; // car approaching, pedestrian red
                    end
                end
                2'b01: begin // pedestrian green, car red
                    car_red <= 1'b1;
                    car_green <= 1'b0;
                    pedestrian_red <= 1'b0;
                    pedestrian_green <= 1'b1;
                    if (pedestrian_green_time) begin
                        state <= 2'b10; // car approaching, pedestrian red
                    end
                end
                2'b10: begin // car approaching, pedestrian red
                    car_red <= 1'b0;
                    car_green <= 1'b1;
                    pedestrian_red <= 1'b1;
                    pedestrian_green <= 1'b0;
                    if (walk_btn) begin
                        state <= 2'b11; // pedestrian green, car red
                    end
                    else if (!car_sensor) begin
                        state <= 2'b00; // car gone, pedestrian red
                    end
                end
                2'b11: begin // pedestrian green, car red
                    car_red <= 1'b1;
                    car_green <= 1'b0;
                    pedestrian_red <= 1'b0;
                    pedestrian_green <= 1'b1;
                    if (pedestrian_green_time) begin
                        state <= 2'b00; // car gone, pedestrian red
                    end
                end
            endcase
        end
    end
endmodule

