module PLL (
  input ref_clk,
  input fb_clk,
  output sync_clk
);

parameter N = 10; // frequency multiplication factor
parameter PD = "XOR"; // phase detector type
parameter Kcp = 0.5; // charge pump gain
parameter Kp = 0.1; // proportional gain
parameter Ki = 0.01; // integral gain

reg [31:0] phase_accumulator = 0;
reg [31:0] phase_error = 0;
reg [31:0] charge_pump_output = 0;
reg [31:0] loop_filter_output = 0;
reg [31:0] sync_clk_counter = 0;

wire ref_clk_div = ref_clk / N;
wire fb_clk_div = fb_clk / N;

// Phase Detector
always @(posedge ref_clk_div or posedge fb_clk_div) begin
  if (PD == "XOR") begin
    phase_error <= (fb_clk_div ^ ref_clk_div) ? 32'hFFFFFFFF : 32'h00000000;
  end else begin
    phase_error <= (fb_clk_div - ref_clk_div) << 1;
  end
end

// Charge Pump
always @(posedge ref_clk_div) begin
  if (phase_error > 0) begin
    charge_pump_output <= Kcp * phase_error;
  end else begin
    charge_pump_output <= -Kcp * phase_error;
  end
end

// Loop Filter
always @(posedge ref_clk_div) begin
  loop_filter_output <= loop_filter_output + Kp * charge_pump_output + Ki * phase_accumulator;
  phase_accumulator <= phase_accumulator + loop_filter_output;
end

// Synchronized Clock
always @(posedge ref_clk_div) begin
  sync_clk_counter <= sync_clk_counter + 1;
  if (sync_clk_counter == N) begin
    sync_clk_counter <= 0;
    sync_clk <= ~sync_clk;
  end
end

endmodule

