module uart_tx(
    input clk,
    input rst,
    input s_tick,
    input tx_start,
    input [7:0] data_in,
    output reg tx,
    output reg tx_done,
    output reg baud_rate_clock
);

parameter BAUD_RATE = 9600;
parameter BAUD_TICKS = 50000000 / BAUD_RATE;

reg [3:0] state;
reg [7:0] data;
reg start_bit;
reg [2:0] bit_count;
reg parity_bit;
reg stop_bit;
reg [23:0] baud_count;

assign tx = state == 3;
assign baud_rate_clock = baud_count[23];

always @(posedge clk) begin
    if (rst) begin
        state <= 0;
        data <= 0;
        start_bit <= 0;
        bit_count <= 0;
        parity_bit <= 0;
        stop_bit <= 1;
        baud_count <= 0;
        tx_done <= 0;
    end else begin
        case (state)
            0: begin // idle state
                if (tx_start) begin
                    state <= 1;
                    data <= data_in;
                    start_bit <= 0;
                    bit_count <= 0;
                    parity_bit <= 0;
                    stop_bit <= 1;
                    baud_count <= 0;
                    tx_done <= 0;
                end
            end
            1: begin // start bit
                start_bit <= 1;
                state <= 2;
            end
            2: begin // data bits
                if (bit_count < 8) begin
                    parity_bit <= parity_bit ^ data[bit_count];
                    bit_count <= bit_count + 1;
                end else begin
                    state <= 3;
                end
            end
            3: begin // stop bit
                stop_bit <= 0;
                tx_done <= 1;
                state <= 0;
            end
        endcase
        if (s_tick) begin
            baud_count <= baud_count + 1;
        end
    end
end

endmodule

