module bitwise_logic (
    input [7:0] a,
    input [7:0] b,
    input [1:0] op,
    output reg [7:0] result
);

    always @(*) begin
        case (op)
            2'b00: result = a & b;   // Bitwise AND
            2'b01: result = a | b;   // Bitwise OR
            2'b10: result = a ^ b;   // Bitwise XOR
            2'b11: result = ~a;      // Bitwise NOT (only uses input a)
        endcase
    end

endmodule

