module top_module (
    input clk,
    input reset,
    input [7:0] d1,
    input [7:0] d2,
    output [7:0] q
);

    wire [7:0] result;
    wire [7:0] q1;
    wire [7:0] q2;

    bitwise_logic logic_unit (
        .a(d1),
        .b(d2),
        .op(2'b00),     // Bitwise AND
        .result(result)
    );

    register reg1 (
        .clk(clk),
        .reset(reset),
        .d(result),
        .q(q1)
    );

    bitwise_logic logic_unit2 (
        .a(d1),
        .b(d2),
        .op(2'b01),     // Bitwise OR
        .result(result)
    );

    register reg2 (
        .clk(clk),
        .reset(reset),
        .d(result),
        .q(q2)
    );

    bitwise_logic logic_unit3 (
        .a(q1),
        .b(q2),
        .op(2'b10),     // Bitwise XOR
        .result(q)
    );

endmodule

