module edge_detection (
  input               clk,
  input               reset,
  input               signal,
  output reg          rise,
  output reg          fall
);

  reg prev_signal;

  always @(posedge clk) begin
    if (reset) begin
      rise <= 1'b0;
      fall <= 1'b0;
      prev_signal <= 1'b0;
    end else begin
      if (signal && !prev_signal) begin
        rise <= 1'b1;
      end else begin
        rise <= 1'b0;
      end

      if (!signal && prev_signal) begin
        fall <= 1'b1;
      end else begin
        fall <= 1'b0;
      end

      prev_signal <= signal;
    end
  end

endmodule

