module crc_ccitt (
    input [15:0] data_in,
    output reg [7:0] crc_out
);

reg [15:0] shift_reg;
reg [7:0] crc_reg;

always @(*) begin
    shift_reg[15:0] = {shift_reg[14:0], data_in[15:0]};
end

always @(posedge clk) begin
    crc_reg[7:0] = crc_reg[7:0] ^ (shift_reg[15] ? 8'h00 : 8'h00);
    crc_reg[7:0] = crc_reg[7:0] ^ (shift_reg[14] ? 8'h10 : 8'h00);
    crc_reg[7:0] = crc_reg[7:0] ^ (shift_reg[13] ? 8'h20 : 8'h00);
    crc_reg[7:0] = crc_reg[7:0] ^ (shift_reg[12] ? 8'h30 : 8'h00);
    crc_reg[7:0] = crc_reg[7:0] ^ (shift_reg[11] ? 8'h40 : 8'h00);
    crc_reg[7:0] = crc_reg[7:0] ^ (shift_reg[10] ? 8'h50 : 8'h00);
    crc_reg[7:0] = crc_reg[7:0] ^ (shift_reg[9] ? 8'h60 : 8'h00);
    crc_reg[7:0] = crc_reg[7:0] ^ (shift_reg[8] ? 8'h70 : 8'h00);
    crc_reg[7:0] = crc_reg[7:0] ^ (shift_reg[7] ? 8'h80 : 8'h00);
    crc_reg[7:0] = crc_reg[7:0] ^ (shift_reg[6] ? 8'h90 : 8'h00);
    crc_reg[7:0] = crc_reg[7:0] ^ (shift_reg[5] ? 8'ha0 : 8'h00);
    crc_reg[7:0] = crc_reg[7:0] ^ (shift_reg[4] ? 8'hb0 : 8'h00);
    crc_reg[7:0] = crc_reg[7:0] ^ (shift_reg[3] ? 8'hc0 : 8'h00);
    crc_reg[7:0] = crc_reg[7:0] ^ (shift_reg[2] ? 8'hd0 : 8'h00);
    crc_reg[7:0] = crc_reg[7:0] ^ (shift_reg[1] ? 8'he0 : 8'h00);
    crc_reg[7:0] = crc_reg[7:0] ^ (shift_reg[0] ? 8'hf0 : 8'h00);

    if (crc_reg[7]) begin
        crc_reg[6:0] = (crc_reg[6:0] << 1) ^ 8'h07;
    end else begin
        crc_reg[6:0] = crc_reg[6:0] << 1;
    end
end

assign crc_out = crc_reg[7:0];

endmodule

module top_module (
    input clk,
    input reset,       // Synchronous active-high reset
    input [2:0] sel,   // Select input for the multiplexer
    input [3:0] data0, // 4-bit data inputs for the multiplexer
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output [15:0] q    // 16-bit output from the functional module
);

    // 6-to-1 multiplexer
    wire [2:0] mux_sel;
    wire [3:0] mux_out;
    priority_encoder pe(mux_sel, sel);
    mux_4to1 mux(
        .sel(mux_sel),
        .data0(data0),
        .data1(data1),
        .data2(data2),
        .data3(data3),
        .out(mux_out)
    );

    // BCD counter
    wire [3:0] digit_en;
    priority_encoder pe2(digit_en, q[15:12]);
    bcd_counter counter(
        .clk(clk),
        .reset(reset),
        .digit_en(digit_en),
        .out(q[11:0])
    );

    // Functional module
    wire [15:0] mult_out;
    multiply_modulo65536 mult(
        .a(mux_out),
        .b(q),
        .out(mult_out)
    );

    assign q = mult_out;

endmodule

module priority_encoder (
    input [2:0] in,
    output [2:0] out
);
    assign out = ~{in[2], in[1], in[0]};
endmodule

module mux_4to1 (
    input [2:0] sel,
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    output [3:0] out
);
    assign out = sel[2] ? (sel[1] ? data3 : data2) : (sel[1] ? data1 : data0);
endmodule

module bcd_counter (
    input clk,
    input reset,
    input [3:0] digit_en,
    output reg [11:0] out
);
    always @(posedge clk) begin
        if (reset) begin
            out <= 0;
        end else begin
            if (digit_en[0]) begin
                out[3:0] <= out[3:0] + 1;
            end
            if (digit_en[1]) begin
                out[7:4] <= out[7:4] + 1;
            end
            if (digit_en[2]) begin
                out[11:8] <= out[11:8] + 1;
            end
        end
    end
endmodule

module multiply_modulo65536 (
    input [15:0] a,
    input [15:0] b,
    output reg [15:0] out
);
    always @(*) begin
        out = (a * b) % 65536;
    end
endmodule

module four_bit_adder (
    input [3:0] a,
    input [3:0] b,
    input cin,
    output [3:0] sum,
    output cout
);

    wire [3:0] xor_result;
    wire [3:0] and_result;
    wire [3:0] sum_result;

    assign xor_result = a ^ b;
    assign and_result = a & b;
    assign sum_result = xor_result ^ cin;

    assign sum = sum_result;
    assign cout = (and_result | (xor_result & cin)) ? 1'b1 : 1'b0;

endmodule

