module top_module( 
    input wire [15:0] in,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo );

    // Pipeline registers
    reg [15:0] in_reg;
    reg [7:0] out_hi_reg;
    reg [7:0] out_lo_reg;

    // Barrel shifter
    reg [15:0] shifted_in;
    always @(*) begin
        shifted_in = in_reg >> 8;
    end

    // Multiplexer
    always @(*) begin
        if (in_reg[7:0] == 0) begin
            out_hi_reg = shifted_in[15:8];
        end else begin
            out_hi_reg = in_reg[15:8];
        end
        out_lo_reg = in_reg[7:0];
    end

    // Pipeline stages
    always @(posedge clk) begin
        in_reg <= in;
    end

    always @(posedge clk) begin
        out_hi <= out_hi_reg;
        out_lo <= out_lo_reg;
    end

endmodule

module barrel_shifter_4bit (
    input [3:0] DATA_IN,
    input [1:0] SHIFT,
    output reg [3:0] DATA_OUT
);

    always @(*) begin
        case(SHIFT)
            2'b00: DATA_OUT = DATA_IN;
            2'b01: DATA_OUT = {DATA_IN[2:0], DATA_IN[3]};
            2'b10: DATA_OUT = {DATA_IN[1:3], DATA_IN[0]};
            2'b11: DATA_OUT = {DATA_IN[0], DATA_IN[3:1]};
        endcase
    end

endmodule

module shift_register (
    input clk,
    input load,
    input [3:0] in,
    output reg [3:0] out,
    output reg [3:0] out_next
);

    always @(posedge clk) begin
        if (load) begin
            out <= in;
            out_next <= in;
        end
        else begin
            out <= {out[2:0], out[3]};
            out_next <= {out[1:0], in};
        end
    end

endmodule

