module full_subtractor (
  input A,
  input B,
  input Bin,
  output D,
  output B_out
);

  wire temp_diff;
  wire temp_borrow;

  half_subtractor hs1(.A(A), .B(B), .D(temp_diff), .B_out(temp_borrow));
  half_subtractor hs2(.A(temp_diff), .B(Bin), .D(D), .B_out(B_out));

  assign B_out = (temp_borrow | (Bin & B)) ? 1 : 0;

endmodule

