module ripple_carry_adder (
  input [3:0] A,
  input [3:0] B,
  input Cin,
  output [3:0] S,
  output Cout
);

  wire [3:0] sum;
  wire [3:0] carry;

  // First half adder
  half_adder HA0(.a(A[0]), .b(B[0]), .sum(sum[0]), .carry(carry[0]));

  // Ripple carry adder
  full_adder FA1(.a(A[1]), .b(B[1]), .cin(carry[0]), .sum(sum[1]), .carry(carry[1]));
  full_adder FA2(.a(A[2]), .b(B[2]), .cin(carry[1]), .sum(sum[2]), .carry(carry[2]));
  full_adder FA3(.a(A[3]), .b(B[3]), .cin(carry[2]), .sum(sum[3]), .carry(Cout));

  assign S = sum;

endmodule
module half_adder (
