module full_adder (
  input a,
  input b,
  input cin,
  output sum,
  output carry
);

  wire s1, c1, c2;

  // First half adder
  half_adder HA0(.a(a), .b(b), .sum(s1), .carry(c1));

  // Second half adder
  half_adder HA1(.a(s1), .b(cin), .sum(sum), .carry(c2));

  // Carry out
  assign carry = c1 | c2;

endmodule

