module sqrt (
  input [15:0] in,
  output [15:0] out
);

  reg [15:0] x;
  reg [15:0] y;

  // Initialize x to the input number
  initial begin
    x = in;
    y = 0;
  end

  // Repeat the algorithm until the difference between x and y is less than or equal to 1
  always @(*) begin
    while (x - y > 1) begin
      x = (x >> 2) << 2;
      y = (y << 1) + 1;
      if (y <= x) begin
        x = x - y;
        y = (y >> 1) + 1;
      end else begin
        y = y >> 1;
      end
    end
    out = y;
  end

endmodule

