module shift_register(
    input clk,
    input areset,  // async active-high reset to zero
    input load,
    input ena,
    input [3:0] data,
    output reg [3:0] q);

    reg [3:0] reg1, reg2;
    reg [1:0] counter;
    wire priority;

    // Priority logic
    assign priority = (load == 1'b1) || ((ena == 1'b1) && (load == 1'b0));

    // Pipeline stage 1
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            reg1 <= 4'b0;
        end else if (load) begin
            reg1 <= data;
        end
    end

    // Pipeline stage 2
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            reg2 <= 4'b0;
            counter <= 2'b0;
        end else if (ena) begin
            if (priority) begin
                reg2 <= data;
            end else begin
                reg2 <= {reg2[2:0], reg1[3]};
            end
            counter <= counter + 1;
        end
    end

    // Output
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            q <= 4'b0;
        end else if (counter == 2) begin
            q <= reg2;
        end
    end

endmodule

