module simple_calculator(
  input clk,
  input reset,
  input op,
  input [7:0] num1,
  input [7:0] num2,
  output reg [7:0] result,
  output reg overflow
);

reg [8:0] temp;

always @(posedge clk, posedge reset) begin
  if (reset) begin
    result <= 0;
    overflow <= 0;
  end
  else begin
    if (op == 0) begin // addition
      temp <= num1 + num2;
      if (temp > 255) begin
        overflow <= 1;
        result <= temp[7:0];
      end
      else begin
        overflow <= 0;
        result <= temp[7:0];
      end
    end
    else begin // subtraction
      temp <= num1 - num2;
      if (temp < 0) begin
        overflow <= 1;
        result <= temp[7:0];
      end
      else begin
        overflow <= 0;
        result <= temp[7:0];
      end
    end
  end
end

endmodule

module mux_dff (
    Q  ,
    Q_N,
    CLK,
    D  ,
    SCD,
    SCE
);

    // Module ports
    output Q  ;
    output Q_N;
    input  CLK;
    input  D  ;
    input  SCD;
    input  SCE;

    // Module supplies
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    // Local signals
    wire buf_Q      ;
    wire mux_out    ;
    reg  notifier   ;
    wire D_delayed  ;
    wire SCD_delayed;
    wire SCE_delayed;
    wire CLK_delayed;
    wire awake      ;
    wire cond1      ;
    wire cond2      ;
    wire cond3      ;

    //                                 Name       Output   Other arguments
    sky130_fd_sc_ls__udp_mux_2to1      mux_2to1  (mux_out, D_delayed, SCD_delayed, SCE_delayed       );
    sky130_fd_sc_ls__udp_dff$P_pp$PG$N dff0      (buf_Q  , mux_out, CLK_delayed, notifier, VPWR, VGND);
    assign awake = ( VPWR === 1'b1 );
    assign cond1 = ( ( SCE_delayed === 1'b0 ) && awake );
    assign cond2 = ( ( SCE_delayed === 1'b1 ) && awake );
    assign cond3 = ( ( D_delayed !== SCD_delayed ) && awake );
    buf                                buf0      (Q      , buf_Q                                     );
    not                                not0      (Q_N    , buf_Q                                     );

    // Delay signals by one clock cycle
    sky130_fd_sc_ls__udp_dff$P_pp$PG$N dff1      (D_delayed  , D        , CLK_delayed, notifier, VPWR, VGND);
    sky130_fd_sc_ls__udp_dff$P_pp$PG$N dff2      (SCD_delayed, SCD      , CLK_delayed, notifier, VPWR, VGND);
    sky130_fd_sc_ls__udp_dff$P_pp$PG$N dff3      (SCE_delayed, SCE      , CLK_delayed, notifier, VPWR, VGND);
    sky130_fd_sc_ls__udp_dff$P_pp$PG$N dff4      (CLK_delayed, CLK      , CLK_delayed, notifier, VPWR, VGND);

    // Detect rising edge of SCD and update output accordingly
    always @(posedge CLK) begin
        if (SCD_delayed === 1'b0 && SCD === 1'b1) begin
            buf_Q <= 1'b1;
        end else if (SCD_delayed === 1'b1 && SCD === 1'b0) begin
            buf_Q <= 1'b0;
        end else if (cond3) begin
            buf_Q <= D_delayed;
        end
    end

    // Update delayed signals on rising edge of clock
    always @(posedge CLK) begin
        D_delayed   <= dff1.Q;
        SCD_delayed <= dff2.Q;
        SCE_delayed <= dff3.Q;
        CLK_delayed <= dff4.Q;
    end

endmodule

module mux4_en(input [3:0] in, input en, output out);

