module pipeline (
  input clk,
  input reset,
  input [7:0] instruction,
  input [4:0] rs1,
  input [4:0] rs2,
  input [4:0] rd,
  input [31:0] data1,
  input [31:0] data2,
  output reg [31:0] regfile [7:0],
  output reg [31:0] final_output
);

reg [7:0] instruction_reg;
reg [4:0] rs1_reg;
reg [4:0] rs2_reg;
reg [4:0] rd_reg;
reg [31:0] data1_reg;
reg [31:0] data2_reg;
reg [31:0] alu_output_reg;
reg [31:0] final_output_reg;

wire [2:0] stage;
wire [1:0] op;
wire [4:0] rs1_sel;
wire [4:0] rs2_sel;
wire [4:0] rd_sel;
wire [31:0] data1_sel;
wire [31:0] data2_sel;

assign rs1_sel = (stage == 0) ? rs1 : rs1_reg;
assign rs2_sel = (stage == 0) ? rs2 : rs2_reg;
assign rd_sel = (stage == 2) ? rd : rd_reg;
assign data1_sel = (stage == 0) ? data1 : data1_reg;
assign data2_sel = (stage == 0) ? data2 : data2_reg;

assign op = instruction_reg[7:6];

assign final_output = final_output_reg;

always @(posedge clk) begin
  if (reset) begin
    instruction_reg <= 8'b0;
    rs1_reg <= 5'b0;
    rs2_reg <= 5'b0;
    rd_reg <= 5'b0;
    data1_reg <= 32'b0;
    data2_reg <= 32'b0;
    alu_output_reg <= 32'b0;
    final_output_reg <= 32'b0;
    stage <= 0;
  end else begin
    case (stage)
      0: begin // Instruction Decode
        instruction_reg <= instruction;
        rs1_reg <= rs1;
        rs2_reg <= rs2;
        rd_reg <= rd;
        data1_reg <= data1;
        data2_reg <= data2;
        stage <= 1;
      end
      1: begin // Execution
        case (op)
          2'b00: alu_output_reg <= data1_sel + data2_sel;
          2'b01: alu_output_reg <= data1_sel - data2_sel;
          2'b10: alu_output_reg <= data1_sel & data2_sel;
          2'b11: alu_output_reg <= ~(data1_sel & data2_sel);
        endcase
        stage <= 2;
      end
      2: begin // Functional Module
        final_output_reg <= alu_output_reg;
        regfile[rd_sel] <= final_output_reg;
        stage <= 0;
      end
    endcase
  end
end

endmodule

