  input [15:0] writedata,
  output irq,
  output reg [15:0] readdata
);

  // Control register
  reg [0:0] control_reg;
  reg control_wr_strobe;

  // Load register
  reg [15:0] load_reg;
  reg load_wr_strobe;

  // Start/stop register
  reg start_stop_reg;
  reg start_stop_wr_strobe;

  // Counter
  reg [15:0] counter;
  reg [15:0] counter_load_val;
  reg counter_is_running;
  reg counter_is_zero;
  reg force_reload;

  // Interrupt
  wire interrupt_enable;
  reg interrupt_occurred;

  // Assign interrupt enable
  assign interrupt_enable = control_reg[0];

  // Assign irq
  assign irq = interrupt_occurred && interrupt_enable;

  // Write strobes
  assign control_wr_strobe = chipselect && ~write_n && (address == 0);
  assign load_wr_strobe = chipselect && ~write_n && (address == 1);
  assign start_stop_wr_strobe = chipselect && ~write_n && (address == 2);

  // Read multiplexer
  wire [15:0] read_mux_out;
  assign read_mux_out = ({16 {(address == 0)}} & interrupt_occurred) |
                        ({16 {(address == 1)}} & load_reg) |
                        ({16 {(address == 2)}} & start_stop_reg) |
                        ({16 {(address == 3)}} & {counter_is_running, interrupt_occurred});

  // Assign readdata
  always @ (posedge clk) begin
    if (chipselect && !write_n) begin
      if (control_wr_strobe) begin
        control_reg <= writedata[0];
      end else if (load_wr_strobe) begin
        load_reg <= writedata;
        counter_load_val <= writedata;
      end else if (start_stop_wr_strobe) begin
        start_stop_reg <= writedata[0];
        if (writedata[0]) begin
          counter_is_running <= 1;
        end else begin
          counter_is_running <= 0;
        end
      end
    end
    readdata <= read_mux_out;
  end

  // Counter logic
  always @ (posedge clk) begin
    if (!reset_n) begin
      counter <= 0;
      counter_is_zero <= 0;
      force_reload <= 0;
    end else if (counter_is_running || force_reload) begin
      if (counter_is_zero || force_reload) begin
        counter <= counter_load_val;
        counter_is_zero <= 0;
        interrupt_occurred <= 0;
      end else begin
        counter <= counter - 1;
        if (counter == 0) begin
          counter_is_zero <= 1;
          interrupt_occurred <= 1;
        end
      end
    end
  end

  // Force reload logic
  always @ (posedge clk) begin
    if (!reset_n) begin
      force_reload <= 0;
    end else if (chipselect && !write_n && (address == 3)) begin
      force_reload <= 1;
    end
  end

endmodule

module divider (
  input enable,
  input signed [31:0] dividend,
  input signed [31:0] divisor,
  output reg done,
  output signed [31:0] quotient,
  output signed [31:0] remainder
);

  reg signed [31:0] dividend_reg;
  reg signed [31:0] divisor_reg;
  reg signed [31:0] quotient_reg;
  reg signed [31:0] remainder_reg;
  reg [1:0] state;

  always @(*) begin
    case (state)
      2'b00: begin // Idle state
        if (enable) begin
          dividend_reg <= dividend;
          divisor_reg <= divisor;
          state <= 2'b01; // Start state
        end
      end
      2'b01: begin // Start state
        if (divisor == 0) begin
          quotient_reg <= 0;
          remainder_reg <= 0;
          done <= 1;
          state <= 2'b00; // Idle state
        end else begin
          quotient_reg <= dividend_reg / divisor_reg;
          remainder_reg <= dividend_reg % divisor_reg;
          state <= 2'b10; // Done state
        end
      end
      2'b10: begin // Done state
        done <= 1;
        quotient <= quotient_reg;
        remainder <= remainder_reg;
        state <= 2'b00; // Idle state
      end
      default: begin
        state <= 2'b00; // Idle state
      end
    endcase
  end

endmodule

module PLL (
  input clk,
  input fsel,
  output reg pll_out
);

parameter f0 = 100000000; // center frequency of the spread spectrum clock signal
parameter delta_f = 1000000; // frequency deviation of the spread spectrum clock signal

reg [31:0] phase_accumulator;
reg [31:0] delta_accumulator;
reg [31:0] delta;
reg [31:0] modulated_delta;
reg [31:0] modulated_frequency;
reg [31:0] filtered_frequency;
reg [31:0] triangular_wave;
reg [31:0] frequency;

always @ (posedge clk) begin
  // Phase accumulator
  phase_accumulator <= phase_accumulator + frequency;

  // Delta accumulator
  delta_accumulator <= delta_accumulator + delta;

  // Modulated delta
  modulated_delta <= delta_f * triangular_wave;

  // Modulated frequency
  modulated_frequency <= (fsel) ? (f0 + modulated_delta) : f0;

  // Filtered frequency
  filtered_frequency <= (filtered_frequency + modulated_frequency) >> 1;

  // Triangular wave
  if (triangular_wave == 32'd0) begin
    triangular_wave <= 32'd1;
  end else if (triangular_wave == 32'd255) begin
    triangular_wave <= 32'd0;
  end else if (triangular_wave < 32'd128) begin
    triangular_wave <= triangular_wave + 32'd1;
  end else begin
    triangular_wave <= triangular_wave - 32'd1;
  end

  // Frequency
  frequency <= filtered_frequency;

  // PLL output
  pll_out <= phase_accumulator[31];
end

endmodule

module frequency_modulator (
  input clk,
  input [31:0] frequency_in,
  input [31:0] delta_in,
  output reg [31:0] frequency_out
);

reg [31:0] phase_accumulator;
reg [31:0] delta_accumulator;
reg [31:0] delta;
reg [31:0] modulated_delta;
reg [31:0] modulated_frequency;
reg [31:0] triangular_wave;
reg [31:0] frequency;

always @ (posedge clk) begin
  // Phase accumulator
  phase_accumulator <= phase_accumulator + frequency;

  // Delta accumulator
  delta_accumulator <= delta_accumulator + delta;

  // Modulated delta
  modulated_delta <= delta_in * triangular_wave;

  // Modulated frequency
  modulated_frequency <= frequency_in + modulated_delta;

  // Triangular wave
  if (triangular_wave == 32'd0) begin
    triangular_wave <= 32'd1;
  end else if (triangular_wave == 32'd255) begin
    triangular_wave <= 32'd0;
  end else if (triangular_wave < 32'd128) begin
    triangular_wave <= triangular_wave + 32'd1;
  end else begin
    triangular_wave <= triangular_wave - 32'd1;
  end

  // Frequency
  frequency <= modulated_frequency;

  // Frequency output
  frequency_out <= frequency;
end

endmodule

module filter (
  input clk,
  input [31:0] frequency_in,
  output reg [31:0] frequency_out
);

reg [31:0] filtered_frequency;

always @ (posedge clk) begin
  filtered_frequency <= (filtered_frequency + frequency_in) >> 1;
  frequency_out <= filtered_frequency;
end

endmodule

