module transition_detector (
    input clk,
    input reset,
    input [31:0] in,
    output reg transition
);

reg [31:0] prev_value;

always @(posedge clk, posedge reset) begin
    if (reset) begin
        prev_value <= 0;
        transition <= 0;
    end else begin
        if (in[0] && !prev_value[0]) begin
            transition <= 1;
        end else begin
            transition <= 0;
        end
        prev_value <= in;
    end
end

endmodule

