module barrel_shifter (
  input [n-1:0] in,
  input [1:0] mode,
  output [n-1:0] out
);

parameter n = 8; // number of input and output signals

// Define shift and rotate operations as Boolean functions
function [n-1:0] shift_left;
  input [n-1:0] data;
  input [1:0] shift_amt;
  begin
    shift_left = {data[shift_amt[1:0]], data[0:(n-1)-shift_amt[1:0]]};
  end
endfunction

function [n-1:0] shift_right;
  input [n-1:0] data;
  input [1:0] shift_amt;
  begin
    shift_right = {data[(n-1)-shift_amt[1:0]+1:n-1], data[0:(n-1)-shift_amt[1:0]]};
  end
endfunction

function [n-1:0] rotate_left;
  input [n-1:0] data;
  input [1:0] shift_amt;
  begin
    rotate_left = {data[shift_amt[1:0]:n-1], data[0:shift_amt[1:0]-1]};
  end
endfunction

function [n-1:0] rotate_right;
  input [n-1:0] data;
  input [1:0] shift_amt;
  begin
    rotate_right = {data[(n-1)-shift_amt[1:0]+1:n-1], data[0:(n-1)-shift_amt[1:0]]};
  end
endfunction

// Connect inputs to outputs based on mode
always @(*) begin
  case (mode)
    2'b00: out = in; // no shift
    2'b01: out = shift_left(in, mode[1:0]); // left shift
    2'b10: out = shift_right(in, mode[1:0]); // right shift
    2'b11: begin // rotate
      if (mode[1] == 1) // positive rotation
        out = rotate_left(in, mode[1:0]);
      else // negative rotation
        out = rotate_right(in, mode[1:0]);
    end
  endcase
end

endmodule

module top_module (
    input clk,
    input reset,       // Synchronous active-high reset
    input [3:0] d,     // Input for the shift register
    input select,      // Select input to choose between shift register and counter
    output [7:0] q     // Output from the active module
);

    // Instantiate the 3-bit shift register from problem 1
    reg [2:0] shift_reg;
    always @(posedge clk) begin
        if (reset) begin
            shift_reg <= 3'b0;
        end else begin
            shift_reg <= {shift_reg[1:0], d};
        end
    end

    // Instantiate the 8-bit register from problem 2
    reg [7:0] reg_out;
    always @(posedge clk) begin
        if (reset) begin
            reg_out <= 8'b0;
        end else if (select) begin
            reg_out <= reg_out + 1;
        end else begin
            reg_out <= {shift_reg, 5'b0};
        end
    end

    // Instantiate the functional module that takes in both the shift register and the register itself as inputs
    // and outputs the bitwise OR of the two inputs
    reg [7:0] or_out;
    always @* begin
        or_out = shift_reg | reg_out;
    end

    // Instantiate the control logic module that enables either the shift register or the counter based on a select input
    wire [7:0] active_out;
    always @* begin
        if (select) begin
            active_out = reg_out;
        end else begin
            active_out = or_out;
        end
    end

    // Assign the output to the active module's value
    assign q = active_out;

endmodule

module mux4to1 (
