    output out;

    // Local signals
    reg mux_out;

    // Implement the multiplexer using an always block
    always @ (sel, in0, in1, in2, in3) begin
        case (sel)
            2'b00: mux_out = in0;
            2'b01: mux_out = in1;
            2'b10: mux_out = in2;
            2'b11: mux_out = in3;
        endcase
    end

    // Assign the output signal to the selected input signal
    assign out = mux_out;

endmodule

module jtag__jtagIRControl(capture, phi1_fb, phi1_in, phi2_fb, phi2_in, shift, 
      update, phi1_out, phi2_out, read, write);
  input capture;
  input phi1_fb;
  input phi1_in;
  input phi2_fb;
  input phi2_in;
  input shift;
  input update;
  output phi1_out;
  output phi2_out;
  output read;
  output write;

  reg capture_state;
  reg shift_state;
  reg update_state;
  reg phi1_out_reg;
  reg phi2_out_reg;
  reg read_reg;
  reg write_reg;

  always @(posedge phi1_fb or negedge phi1_in) begin
    if (!capture_state && capture) begin
      capture_state <= 1'b1;
      shift_state <= 1'b0;
      update_state <= 1'b0;
    end else if (!shift_state && shift) begin
      capture_state <= 1'b0;
      shift_state <= 1'b1;
      update_state <= 1'b0;
    end else if (!update_state && update) begin
      capture_state <= 1'b0;
      shift_state <= 1'b0;
      update_state <= 1'b1;
    end else begin
      capture_state <= 1'b0;
      shift_state <= 1'b0;
      update_state <= 1'b0;
    end
  end

  always @(posedge phi2_fb or negedge phi2_in) begin
    if (capture_state) begin
      phi1_out_reg <= phi1_in;
      phi2_out_reg <= phi2_in;
      read_reg <= 1'b1;
      write_reg <= 1'b0;
    end else if (shift_state) begin
      phi1_out_reg <= phi1_in;
      phi2_out_reg <= phi2_in;
      read_reg <= 1'b0;
      write_reg <= 1'b0;
    end else if (update_state) begin
      phi1_out_reg <= phi1_fb;
      phi2_out_reg <= phi2_in;
      read_reg <= 1'b0;
      write_reg <= 1'b1;
    end else begin
      phi1_out_reg <= 1'b0;
      phi2_out_reg <= 1'b0;
      read_reg <= 1'b0;
      write_reg <= 1'b0;
    end
  end

  assign phi1_out = phi1_out_reg;
  assign phi2_out = phi2_out_reg;
  assign read = read_reg;
  assign write = write_reg;

endmodule

module falling_edge_detector (
