always @(posedge clk) begin
    if (reset) begin
        stage1_out <= 0;
        stage2_out <= 0;
        stage3_out <= 0;
        stage4_out <= 0;
    end else begin
        stage1_out <= in;
        stage2_out <= stage1_out;
        stage3_out <= stage2_out;
