    muxalu mux_sub(a, b, 16'h0000, 16'h0000, 16'h0000, 16'h0000, alu_ctrl[1:0], 2'b10, sub_out);
    muxalu mux_shl(a, b, 16'h0000, 16'h0000, 16'h0000, 16'h0000, alu_ctrl[1:0], 2'b01, shl_out);
