module barrel_shifter (
  input [n-1:0] in,
  input signed [n-1:0] shift,
  output [n-1:0] out
);

parameter n = 8; // number of bits in the input and output signals

wire [n-1:0] shifted;

// Perform the shift operation
assign shifted = (shift >= n || shift <= -n) ? {in[shift % n:n-1], in[0:shift % n-1]} :
                (shift > 0) ? {in[shift:n-1], in[0:shift-1]} :
                {in[n+shift:n-1], in[0:n+shift-1]};

// Connect the shifted output to the output ports
assign out = shifted;

endmodule

