   reg [adr_width-1:0] r_ptr_reg, r_ptr_next;
   reg full_reg, empty_reg, full_next, empty_next;
   wire wr_en;
   reg [1:0] orden;

   assign data_out = array_reg[r_ptr_reg];
   assign wr_en = wr & ~full_reg;

   assign full = full_reg;
   assign empty = empty_reg;

   always @(posedge clk) begin
      if (wr_en)
         array_reg[w_ptr_reg] <= data_in;
   end

   // fifo control logic
   // register for read and write pointers
   always @(posedge clk, posedge reset) begin
      if (reset)
         begin
            w_ptr_reg <= 0;
            r_ptr_reg <= 0;
            full_reg <= 1'b0;
            empty_reg <= 1'b1;
         end
      else
         begin
            w_ptr_reg <= w_ptr_next;
            r_ptr_reg <= r_ptr_next;
            full_reg <= full_next;
            empty_reg <= empty_next;
         end
   end

   always @(posedge clk)
   begin
      if(wr&&!rd)
      begin
         orden = 2'b01;
      end
      if(!wr&&rd)
      begin
         orden = 2'b10;
      end
      if(wr&&rd)
      begin
         orden = 2'b11;
      end
   end

   always @(posedge clk)
   begin
      full_next = full_reg;
      empty_next = empty_reg;
      case (orden)
         2'b01: // read
            if (~empty_reg) // not empty
               begin
                  r_ptr_next = r_ptr_reg + 1;
                  full_next = 1'b0;
                  if (r_ptr_next==w_ptr_reg)
                     empty_next = 1'b1;
               end
         2'b10: // write
            if (~full_reg) // not full
               begin
                  w_ptr_next = w_ptr_reg + 1;
                  empty_next = 1'b0;
                  if (w_ptr_next==r_ptr_reg)
                     full_next = 1'b1;
               end
         2'b11: // write and read
            begin
               w_ptr_next =  w_ptr_reg + 1;
               r_ptr_next = r_ptr_reg + 1;
            end
      endcase
   end

   //always @(posedge reset or posedge wr or posedge rd)
   always @(posedge clk)
   begin
      if (reset) begin
         w_ptr_next =  0;
         r_ptr_next =  0;       
      end
   end

endmodule

module KeyScanController(
  input clk, rst, start, load, shift,
  output reg [2:0] currentState,
  output reg startTimer
);

  parameter DIVIDER = 3;
  reg [DIVIDER-1:0] timer;

  always @(posedge clk, posedge rst) begin
    if (rst) begin
      currentState <= 3'b000;
      startTimer <= 0;
      timer <= 0;
    end else begin
      case (currentState)
        3'b000: begin
          if (start) begin
            currentState <= 3'b001;
            startTimer <= 1;
            timer <= 0;
          end
        end
        3'b001: begin
          startTimer <= 0;
          if (timer == DIVIDER-1) begin
            if (load) begin
              currentState <= 3'b010;
              timer <= 0;
            end else if (shift) begin
              currentState <= 3'b100;
              timer <= 0;
            end else begin
              currentState <= 3'b000;
              timer <= 0;
            end
          end else begin
            timer <= timer + 1;
          end
        end
        3'b010: begin
          if (timer == DIVIDER-1) begin
            currentState <= 3'b001;
            timer <= 0;
          end else begin
            timer <= timer + 1;
          end
        end
        3'b100: begin
          if (timer == DIVIDER-1) begin
            currentState <= 3'b001;
            timer <= 0;
          end else begin
            timer <= timer + 1;
          end
        end
      endcase
    end
  end
endmodule

module top_module (
    input clk,      // Clocks are used in sequential circuits
    input reset,    // Synchronous active-high reset
    input [7:0] d,  // Input to the T flip-flop
    input [7:0] in, // 8-bit input for the module to detect changes
    output [7:0] out // Final 8-bit output from the bitwise AND operation of the two modules
);

// Instantiate the T flip-flop
reg t;
always @(posedge clk, posedge reset) begin
    if (reset) begin
        t <= 1'b0;
    end else begin
        t <= d ^ t;
    end
end

// Instantiate the module to detect changes in the 8-bit vector
reg [7:0] prev_in;
reg [7:0] changed_bits;
always @(posedge clk, posedge reset) begin
    if (reset) begin
        prev_in <= 8'b0;
        changed_bits <= 8'b0;
    end else begin
        changed_bits <= in ^ prev_in;
        prev_in <= in;
    end
end

// Instantiate the functional module that performs the bitwise AND operation
assign out = t & changed_bits;

endmodule

module PLL (
    input PACKAGEPIN,
    output PLLOUTCOREA,
    output PLLOUTGLOBALA,
    output PLLOUTCOREB,
    output PLLOUTGLOBALB,
    input [7:0] DYNAMICDELAY,
    output LOCK,
    input BYPASS,
    input RESETB,
    input LATCHINPUTVALUE,
    output SDO,
    input SDI,
    input SCLK
);

    reg [7:0] delay_counter;
    reg [7:0] delay_value;
    reg locked;
    reg [7:0] shift_register;
    reg [7:0] feedback_shift_register;
    reg [3:0] feedback_shift_register_index;
    reg [3:0] shift_register_index;
    reg [3:0] shift_register_divide_index;
    reg [3:0] shift_register_divide_value;
    reg [7:0] filter_value;
    reg [2:0] filter_index;
    reg [7:0] divide_value;

    always @(posedge PACKAGEPIN or posedge RESETB) begin
        if (RESETB == 1'b0) begin
            delay_counter <= 8'd0;
            delay_value <= 8'd0;
            locked <= 1'b0;
            shift_register <= 8'd0;
            feedback_shift_register <= 8'd0;
            feedback_shift_register_index <= 4'd0;
            shift_register_index <= 4'd0;
            shift_register_divide_index <= 4'd0;
            shift_register_divide_value <= 4'd0;
            filter_value <= 8'd0;
            filter_index <= 3'd0;
            divide_value <= 8'd0;
        end else begin
            if (LATCHINPUTVALUE == 1'b1) begin
                delay_value <= DYNAMICDELAY;
            end
            if (delay_counter == delay_value) begin
                shift_register <= {shift_register[6:0], shift_register[7]};
                shift_register_divide_index <= shift_register_divide_index + 1;
                if (shift_register_divide_index == shift_register_divide_value) begin
                    shift_register_divide_index <= 0;
                    shift_register_index <= shift_register_index + 1;
                    if (shift_register_index == 16) begin
                        shift_register_index <= 0;
                    end
                end
                if (BYPASS == 1'b1) begin
                    divide_value <= 8'd1;
                end else begin
                    feedback_shift_register <= {feedback_shift_register[2:0], PACKAGEPIN, feedback_shift_register[3]};
                    feedback_shift_register_index <= feedback_shift_register_index + 1;
                    if (feedback_shift_register_index == 16) begin
                        feedback_shift_register_index <= 0;
                    end
                    if (feedback_shift_register[11:0] == 12'h000) begin
                        divide_value <= 8'd1;
                    end else begin
                        divide_value <= {feedback_shift_register[11:0], 4'b0000} / shift_register;
                    end
                end
                filter_index <= filter_index + 1;
                if (filter_index == 8) begin
                    filter_index <= 0;
                end
                filter_value <= filter_value + divide_value - filter_value[2:0];
                PLLOUTCOREA <= filter_value[2];
                PLLOUTGLOBALA <= filter_value[2];
                PLLOUTCOREB <= filter_value[2];
                PLLOUTGLOBALB <= filter_value[2];
                locked <= (divide_value == 8'd1);
                SDO <= shift_register[7];
            end
            delay_counter <= delay_counter + 1;
        end
    end

    assign LOCK = locked;

endmodule

module binary_counter (
    input            clk,
    input            reset,
    input            enable,
    output reg [3:0] count
  );

  // --------------------------------------------------------------------
  // Internal wires and registers Declarations
  // --------------------------------------------------------------------
  reg [3:0] next_count;

  // --------------------------------------------------------------------
  // Sequential logic
  // --------------------------------------------------------------------
  always @(posedge clk or posedge reset) begin
    if (reset == 1'b1) begin
      count <= 4'h0;
      next_count <= 4'h0;
    end
    else begin
      if (enable == 1'b1) begin
        next_count <= count + 4'h1;
      end
      else begin
        next_count <= count;
      end

      count <= next_count;
    end
  end

endmodule

