module fifo_buffer
  (
    input wire wr_en,
    input wire wr_clk,
    input wire rd_clk,
    input wire [7:0] din,
    input wire rst,
    input wire rd_en,
    output reg wr_rst_busy,
    output reg empty,
    output reg full,
    output reg [7:0] dout
  );

  reg [7:0] mem [15:0];
  reg [3:0] wr_ptr;
  reg [3:0] rd_ptr;
  reg [3:0] count;

  always @(posedge wr_clk) begin
    if (rst) begin
      wr_ptr <= 0;
      rd_ptr <= 0;
      count <= 0;
      wr_rst_busy <= 1;
    end else if (wr_en && ~full) begin
      mem[wr_ptr] <= din;
      wr_ptr <= wr_ptr + 1;
      count <= count + 1;
      wr_rst_busy <= 0;
    end else if (wr_en && full) begin
      mem[wr_ptr] <= din;
      wr_ptr <= wr_ptr + 1;
      rd_ptr <= rd_ptr + 1;
      wr_rst_busy <= 0;
    end else if (~wr_en && wr_rst_busy) begin
      wr_rst_busy <= 0;
    end
  end

  always @(posedge rd_clk) begin
    if (rst) begin
      wr_ptr <= 0;
      rd_ptr <= 0;
      count <= 0;
      empty <= 1;
      full <= 0;
      dout <= 0;
    end else if (rd_en && ~empty) begin
      dout <= mem[rd_ptr];
      rd_ptr <= rd_ptr + 1;
      count <= count - 1;
      empty <= (count == 1);
      full <= 0;
    end else if (rd_en && empty) begin
      dout <= mem[rd_ptr];
      empty <= 1;
      full <= 0;
    end else if (~rd_en && empty) begin
      empty <= 1;
      full <= 0;
    end else if (count == 16) begin
      full <= 1;
      empty <= 0;
    end
  end

endmodule

module fifo
   #(
  	parameter adr_width = 10,
	parameter dat_width = 8
   )
   (
    input  clk, reset,
    input  rd, wr,
    input  [dat_width-1:0] data_in,
    output [dat_width-1:0] data_out,
    output empty, 
    output full
   );


   parameter depth = (1 << adr_width);

   //declaración de registros 

   reg [dat_width-1:0] array_reg [depth-1:0];// register array FIFO

   reg [adr_width-1:0] w_ptr_reg, w_ptr_next;
   reg [adr_width-1:0] r_ptr_reg, r_ptr_next;
   reg full_reg, empty_reg, full_next, empty_next;
   wire wr_en;


   assign data_out = array_reg[r_ptr_reg];
   assign wr_en = wr & ~full_reg;

   assign full = full_reg;
   assign empty = empty_reg;

   always @(posedge clk) begin
      if (wr_en)
         array_reg[w_ptr_reg] <= data_in;
   end

   // fifo control logic
   // register for read and write pointers
   always @(posedge clk, posedge reset) begin
      if (reset)
         begin
            w_ptr_reg <= 0;
            r_ptr_reg <= 0;
            full_reg <= 1'b0;
            empty_reg <= 1'b1;
         end
      else
         begin
            w_ptr_reg <= w_ptr_next;
            r_ptr_reg <= r_ptr_next;
            full_reg <= full_next;
            empty_reg <= empty_next;
         end
   end



   always @(posedge reset, posedge wr, posedge rd)
   begin
      if (reset) begin
	w_ptr_next =  0;
        r_ptr_next =  0;       
      end else begin
	      full_next = full_reg;
	      empty_next = empty_reg;
	      case ({wr, rd})
		 2'b01: // read
		    if (~empty_reg) // not empty
		       begin
		          r_ptr_next = r_ptr_reg + 1;
		          full_next = 1'b0;
		          if (r_ptr_next==w_ptr_reg)
		             empty_next = 1'b1;
		       end
		 2'b10: // write
		    if (~full_reg) // not full
		       begin
		          w_ptr_next = w_ptr_reg + 1;
		          empty_next = 1'b0;
		          if (w_ptr_next==r_ptr_reg)
		             full_next = 1'b1;
		       end
		 2'b11: // write and read
		    begin
		       w_ptr_next =  w_ptr_reg + 1;
		       r_ptr_next = r_ptr_reg + 1;
		    end
	      endcase
	end
   end



endmodule

module assert_win_unchange_assert (clk, reset_n, start_event, end_event, test_expr, window,
                                   xzdetect_test_expr, xzcheck_enable);
       parameter width = 8;
       input clk, reset_n, start_event, end_event, window;
       input [width-1:0] test_expr;
       input xzdetect_test_expr, xzcheck_enable;

       reg [width-1:0] prev_test_expr;
       reg [width-1:0] test_expr_masked;
       reg [width-1:0] window_counter;
       reg [width-1:0] window_length;
       reg [1:0] state;
       wire assert_fail;

       // Mask test_expr if xzcheck_enable is set
       always @(*) begin
           if (xzcheck_enable) begin
               test_expr_masked = test_expr & ~{test_expr};
           end else begin
               test_expr_masked = test_expr;
           end
       end

       // Detect X or Z values in test_expr
       always @(*) begin
           if (xzdetect_test_expr) begin
               if ({test_expr_masked} !== {test_expr}) begin
                   $display("Error: Test expression contains X or Z values");
                   $finish;
               end
           end
       end

       // Initialize values on reset
       always @(posedge clk) begin
           if (!reset_n) begin
               prev_test_expr <= 0;
               window_counter <= 0;
               window_length <= 0;
               state <= 2'b00;
           end else begin
               prev_test_expr <= test_expr_masked;
               window_counter <= 0;
               window_length <= window;
               state <= 2'b01;
           end
       end

       // State machine to check for unchanged value within window
       always @(posedge clk) begin
           case (state)
               2'b00: begin // Idle state
                   if (start_event) begin
                       state <= 2'b01;
                       prev_test_expr <= test_expr_masked;
                       window_counter <= 0;
                       window_length <= window;
                   end
               end
               2'b01: begin // Window open state
                   if (test_expr_masked !== prev_test_expr) begin
                       state <= 2'b10;
                       prev_test_expr <= test_expr_masked;
                       window_counter <= 0;
                       window_length <= window;
                   end else if (window_counter == window_length) begin
                       state <= 2'b11;
                   end else begin
                       prev_test_expr <= test_expr_masked;
                       window_counter <= window_counter + 1;
                   end
               end
               2'b10: begin // Assertion fail state
                   assert_fail <= 1;
                   $display("Error: Value changed within window");
                   state <= 2'b00;
               end
               2'b11: begin // Assertion pass state
                   assert_fail <= 0;
                   state <= 2'b00;
               end
           endcase
       end

endmodule

module scfifo_24in_24out_12kb_wr_status_flags_ss
   (comp0,
    comp1,
    p_1_out,
    full,
    E,
    v1_reg,
    \gc0.count_d1_reg[8] ,
    v1_reg_0,
    ram_full_comb,
    clk,
    rst_full_ff_i,
    wr_en);
  output comp0;
  output comp1;
  output p_1_out;
  output full;
  output [0:0]E;
  input [3:0]v1_reg;
  input [0:0]\gc0.count_d1_reg[8] ;
  input [4:0]v1_reg_0;
  input ram_full_comb;
  input clk;
  input rst_full_ff_i;
  input wr_en;

  wire [0:0]E;
  wire clk;
  wire comp0;
  wire comp1;
  wire full;
  wire [0:0]\gc0.count_d1_reg[8] ;
  wire p_1_out;
  wire ram_full_comb;
  wire rst_full_ff_i;
  wire [3:0]v1_reg;
  wire [4:0]v1_reg_0;
  wire wr_en;

  // Define FIFO depth and width
  parameter DEPTH = 12288;
  parameter WIDTH = 24;

  // Define FIFO memory
  reg [WIDTH-1:0] mem [DEPTH-1:0];

  // Define FIFO read and write pointers
  reg [14:0] read_ptr = 0;
  reg [14:0] write_ptr = 0;

  // Define FIFO status flags
  reg full = 0;
  reg empty = 1;
  reg write_in_progress = 0;

  // Define write enable signal
  wire we = wr_en && !full;

  // Define read and write operations
  always @(posedge clk) begin
    // Read operation
    if (!empty) begin
      p_1_out <= mem[read_ptr][0];
      read_ptr <= read_ptr + 1;
      if (read_ptr == DEPTH) read_ptr <= 0;
      if (write_in_progress) write_in_progress <= 0;
      if (read_ptr == write_ptr) empty <= 1;
      full <= 0;
    end
    // Write operation
    else if (we) begin
      mem[write_ptr] <= {we, v1_reg};
      write_ptr <= write_ptr + 1;
      if (write_ptr == DEPTH) write_ptr <= 0;
      if (!write_in_progress) write_in_progress <= 1;
      if (write_ptr == read_ptr) full <= 1;
      empty <= 0;
    end
  end

  // Define status flag outputs
  assign comp0 = empty;
  assign comp1 = !empty;
  assign full = full;
  assign E = write_in_progress;

  // Define reset operation
  always @(posedge clk) begin
    if (rst_full_ff_i) begin
      read_ptr <= 0;
      write_ptr <= 0;
      full <= 0;
      empty <= 1;
      write_in_progress <= 0;
    end
  end

endmodule

