module bt656cap_colorspace(
    input vid_clk,
    input stb_i,
    input field_i,
    input [31:0] ycc422,
    output reg stb_o,
    output reg field_o,
    output reg [31:0] rgb565
);

// Constants for color conversion
parameter R_FACTOR = 298;
parameter G_FACTOR = 587;
parameter B_FACTOR = 114;

// Internal signals
reg [7:0] y0, y1, cb, cr;
reg [8:0] r, g, b;

// Assign input signals to internal signals
assign {y1, y0, cb, cr} = ycc422;

// Color conversion
always @* begin
    r = (y0 + ((cr - 128) * R_FACTOR >> 8));
    g = (y0 - ((cb - 128) * G_FACTOR >> 8) - ((cr - 128) * G_FACTOR >> 8));
    b = (y0 + ((cb - 128) * B_FACTOR >> 8));
end

// Output synchronization
reg [31:0] rgb565_sync;
always @(posedge vid_clk) begin
    if (stb_i) begin
        rgb565_sync <= {r[7:3], g[7:2], b[7:3]};
        stb_o <= 1;
        field_o <= field_i;
    end else begin
        stb_o <= 0;
    end
end

// Output assignment
assign rgb565 = rgb565_sync;

endmodule

