module vga(
    input clk,
    output reg vtrigger,
    input [15:0] fifo_data,
    input fifo_write,
    output fifo_full,
    input pclk,
    output reg hsync,
    output reg vsync,
    output [15:0] rgb
);

parameter
    VIDEO  = 2'd0,
    FRONT  = 2'd1,
    SYNC   = 2'd2,
    BACK   = 2'd3;

reg [11:0] hcount = 0;
reg [1:0] hnext = SYNC;
wire hcount_done = hcount <= 1;
reg [11:0] htiming[3:0];
reg next_line;
reg hactive = 0;

reg [11:0] vcount = 0;
reg [1:0] vnext = BACK;
wire vcount_done = vcount <= 1;
reg [11:0] vtiming[3:0];
reg vactive = 0;

initial begin
    htiming[VIDEO] = 640;
    htiming[FRONT] = 16;
    htiming[SYNC]  = 96;
    htiming[BACK]  = 48;

    vtiming[VIDEO] = 480;
    vtiming[FRONT] = 10;
    vtiming[SYNC]  = 2;
    vtiming[BACK]  = 33;
end

always @(posedge pclk) begin
    if (fifo_write && !fifo_full) begin
        fifo_data <= fifo_data;
    end
end

async_fifo fifo (
    .clka(clk),
    .in({2'b0, fifo_data}),
    .wr(fifo_write),
    .full(fifo_full),
    .clkb(pclk),
    .out(rgb),
    .rd(hactive && vactive)
);

always @(posedge clk) begin
    if (hcount_done) begin
        hcount <= htiming[hnext];
    end else begin
        hcount <= hcount - 1;
    end
end

always @(posedge pclk) begin
    if (hcount_done) begin
        hnext <= hnext + 1;
    end
end

always @(posedge pclk) begin
    hsync   <= hnext == BACK;
    hactive <= hnext == FRONT;
end

always @(posedge pclk) begin
    next_line <= hcount_done && hsync;
end

always @(posedge pclk) begin
    if (next_line) begin
        if (vcount_done) begin
            vcount <= vtiming[vnext];
        end else begin
            vcount <= vcount - 1;
        end
    end
end

always @(posedge pclk) begin
    if (next_line) begin
        if (vcount_done) begin
            vnext <= vnext + 1;
        end
    end
end

always @(posedge pclk) begin
    vsync   <= vnext == BACK;
    vactive <= vnext == FRONT;
end

reg vsync0;
reg vsync1;
reg vsync2;

always @(posedge clk) begin
    vsync0 <= vsync;
    vsync1 <= vsync0;
    vsync2 <= vsync1;
    vtrigger <= vsync2 && !vsync1;
end

endmodule

