module constant_voltage_driver (
  input clk,
  input rst,
  input ctrl,
  output reg vout
);

parameter voltage_level = 1.8; // desired voltage level of the output signal
parameter rise_time = 10; // time required for the output signal to rise to the desired voltage level
parameter fall_time = 20; // time required for the output signal to fall from the desired voltage level

reg [31:0] rise_counter;
reg [31:0] fall_counter;

always @(posedge clk) begin
  if (rst) begin
    vout <= 0;
    rise_counter <= 0;
    fall_counter <= 0;
  end
  else begin
    if (ctrl) begin
      if (rise_counter < rise_time) begin
        rise_counter <= rise_counter + 1;
        vout <= (rise_counter * voltage_level) / rise_time;
      end
      else begin
        vout <= voltage_level;
      end
      fall_counter <= 0;
    end
    else begin
      if (fall_counter < fall_time) begin
        fall_counter <= fall_counter + 1;
        vout <= voltage_level - ((fall_counter * voltage_level) / fall_time);
      end
      else begin
        vout <= 0;
      end
      rise_counter <= 0;
    end
  end
end

endmodule

module adder_4bit (
  input clk,
  input reset,
  input [3:0] A,
  input [3:0] B,
  input cin,
  output [3:0] S,
  output cout
);

  wire [3:0] sum;
  wire c1, c2, c3;

  assign c1 = A[0] & B[0];
  assign c2 = (A[0] ^ B[0]) & cin;
  assign c3 = A[0] | B[0];

  assign sum[0] = A[0] ^ B[0] ^ cin;

  assign c1 = c1 | (sum[0] & c3);
  assign c2 = c2 | (sum[0] & c3);

  assign c1 = c1 | (A[1] & B[1]);
  assign c2 = c2 | (A[1] & B[1]) | (sum[1] & c3);

  assign sum[1] = A[1] ^ B[1] ^ c1;

  assign c1 = c1 | (A[2] & B[2]);
  assign c2 = c2 | (A[2] & B[2]) | (sum[2] & c3);

  assign sum[2] = A[2] ^ B[2] ^ c1;

  assign c1 = c1 | (A[3] & B[3]);
  assign c2 = c2 | (A[3] & B[3]) | (sum[3] & c3);

  assign sum[3] = A[3] ^ B[3] ^ c1;

  assign cout = c2 | (sum[3] & c3);

  assign S = sum;

endmodule

module fsm_4bit_sequence_detection (
  input clk,
  input reset,
  input [15:0] data,
  input [3:0] sequence,
  output reg match
);

  parameter IDLE = 2'b00;
  parameter MATCHING = 2'b01;
  parameter ERROR = 2'b10;

  reg [1:0] state;
  reg [3:0] count;
  reg [3:0] data_reg;

  always @(posedge clk) begin
    if (reset) begin
      state <= IDLE;
      count <= 4'd0;
      data_reg <= 4'd0;
      match <= 1'b0;
    end
    else begin
      case (state)
        IDLE: begin
          if (data == sequence) begin
            state <= MATCHING;
            count <= 4'd1;
            data_reg <= data[3:0];
          end
        end
        MATCHING: begin
          if (data == sequence) begin
            count <= count + 4'd1;
            data_reg <= data[3:0];
            if (count == 4'd4) begin
              state <= IDLE;
              match <= 1'b1;
            end
          end
          else begin
            state <= ERROR;
          end
        end
        ERROR: begin
          state <= IDLE;
          count <= 4'd0;
          data_reg <= 4'd0;
          match <= 1'b0;
        end
      endcase
    end
  end
endmodule

