module vending_machine (
    input clk,
    input reset,
    input [1:0] coin,
    input [1:0] item,
    output reg dispense,
    output reg [1:0] change,
    output reg item1,
    output reg item2,
    output reg item3
);

reg [3:0] total;
reg [1:0] cost;
reg [1:0] stock;

parameter ITEM1_COST = 2'b01;
parameter ITEM2_COST = 2'b10;
parameter ITEM3_COST = 2'b11;

parameter ITEM1_STOCK = 1;
parameter ITEM2_STOCK = 3;
parameter ITEM3_STOCK = 0;

always @(posedge clk) begin
    if (reset) begin
        total <= 0;
        cost <= 0;
        stock <= {ITEM1_STOCK, ITEM2_STOCK, ITEM3_STOCK};
        dispense <= 0;
        change <= 0;
        item1 <= ITEM1_STOCK;
        item2 <= ITEM2_STOCK;
        item3 <= ITEM3_STOCK;
    end else begin
        case (coin)
            2'b00: total <= total;
            2'b01: total <= total + 5;
            2'b10: total <= total + 10;
            2'b11: total <= total + 25;
        endcase
        case (item)
            2'b00: cost <= 0;
            2'b01: cost <= ITEM1_COST;
            2'b10: cost <= ITEM2_COST;
            2'b11: cost <= ITEM3_COST;
        endcase
        if (item == 2'b01 && cost <= total && stock[0]) begin
            dispense <= 1;
            change <= total - ITEM1_COST;
            total <= 0;
            stock[0] <= stock[0] - 1;
        end else if (item == 2'b10 && cost <= total && stock[1]) begin
            dispense <= 1;
            change <= total - ITEM2_COST;
            total <= 0;
            stock[1] <= stock[1] - 1;
        end else if (item == 2'b11 && cost <= total && stock[2]) begin
            dispense <= 1;
            change <= total - ITEM3_COST;
            total <= 0;
            stock[2] <= stock[2] - 1;
        end else begin
            dispense <= 0;
            change <= total;
            total <= 0;
        end
        item1 <= stock[0];
        item2 <= stock[1];
        item3 <= stock[2];
    end
end

endmodule

module tone_generator (
  input clk,
  input reset,
  input [1:0] mode,
  input [7:0] freq,
  output reg signed [N-1:0] tone
);

parameter fs = 100000; // sampling frequency
parameter N = 8; // number of bits used to represent the amplitude of the tone signal

reg [31:0] phase_acc;
reg [31:0] phase_inc;

always @ (posedge clk) begin
  if (reset) begin
    phase_acc <= 0;
    tone <= 0;
  end else begin
    phase_acc <= phase_acc + phase_inc;
    case (mode)
      2'b00: begin // DTMF
        case (freq)
          8'h11: phase_inc <= 2*3.14159*697/fs*(2**32);
          8'h12: phase_inc <= 2*3.14159*770/fs*(2**32);
          8'h13: phase_inc <= 2*3.14159*852/fs*(2**32);
          8'h14: phase_inc <= 2*3.14159*941/fs*(2**32);
          8'h21: phase_inc <= 2*3.14159*1209/fs*(2**32);
          8'h22: phase_inc <= 2*3.14159*1336/fs*(2**32);
          8'h23: phase_inc <= 2*3.14159*1477/fs*(2**32);
          8'h24: phase_inc <= 2*3.14159*1633/fs*(2**32);
        endcase
        tone <= $signed((N-1)*sin(phase_acc[31:0]));
      end
      2'b01: begin // sine wave
        phase_inc <= 2*3.14159*freq/fs*(2**32);
        tone <= $signed((N-1)*sin(phase_acc[31:0]));
      end
      2'b10: begin // square wave
        phase_inc <= 2*3.14159*freq/fs*(2**32);
        if (phase_acc[31]) begin
          tone <= (N-1);
        end else begin
          tone <= -(N-1);
        end
      end
    endcase
  end
end

endmodule

module add_sub_carry_out
