module array_multiplier (
    input [15:0] A,
    input [15:0] B,
    output reg [31:0] product
);

reg [31:0] partial_products [0:15];

integer i, j;

always @(*) begin
    for (i = 0; i < 16; i = i + 1) begin
        for (j = 0; j < 16; j = j + 1) begin
            if ((i + j) < 16) begin
                partial_products[i + j] = partial_products[i + j] + (A[i] & B[j]);
            end
        end
    end
    for (i = 0; i < 31; i = i + 1) begin
        product[i] = partial_products[i] ^ partial_products[i + 1];
    end
    product[31] = partial_products[15];
end

endmodule
