module sqrt (
  input [31:0] in,
  output [15:0] out
);

  reg [31:0] curr_val;
  reg [15:0] output_val;
  reg [4:0] bit_index;

  initial begin
    curr_val = in;
    output_val = 0;
    bit_index = 15;
  end

  always @(*) begin
    while (curr_val > 1) begin
      curr_val = curr_val >> 1;
      if (curr_val * curr_val > in) begin
        output_val[bit_index] = 1;
        curr_val = curr_val + (in >> (bit_index + 1));
      end
      bit_index = bit_index - 1;
    end
    out = output_val;
  end

endmodule

module PLL (
  input ref_clk,
  input fb_clk,
  output out
);

parameter n = 8; // number of bits of the internal counter
parameter m = 10; // number of cycles of the reference clock in one period of the output signal

reg [n-1:0] counter;
wire phase_detect;
wire charge_pump;

assign phase_detect = (fb_clk == 1'b1) && (ref_clk == 1'b0);
assign charge_pump = phase_detect ? 1'b1 : -1'b1;

always @(posedge ref_clk) begin
  if (counter == m-1) begin
    counter <= 0;
    out <= ~out;
  end else begin
    counter <= counter + 1;
  end
end

always @(posedge fb_clk) begin
  if (charge_pump == 1'b1) begin
    m <= m + 1;
  end else begin
    m <= m - 1;
  end
end

endmodule

module calculator(
    input [1:0] op,
    input [7:0] a,
    input [7:0] b,
    input reset,
    output reg [7:0] result,
    output reg valid
);

    reg [7:0] temp_result;
    reg [7:0] a_reg;
    reg [7:0] b_reg;
    reg [2:0] state;

    // state definitions
    localparam IDLE = 3'b000;
    localparam ADD  = 3'b001;
    localparam SUB  = 3'b010;
    localparam MUL  = 3'b011;
    localparam DIV  = 3'b100;

    always @ (posedge reset) begin
        if (reset) begin
            state <= IDLE;
            temp_result <= 8'b0;
            a_reg <= 8'b0;
            b_reg <= 8'b0;
        end
    end

    always @ (posedge reset or posedge op or posedge valid) begin
        if (reset) begin
            state <= IDLE;
            temp_result <= 8'b0;
            a_reg <= 8'b0;
            b_reg <= 8'b0;
        end
        else if (valid) begin
            temp_result <= result;
            a_reg <= 8'b0;
            b_reg <= 8'b0;
            state <= IDLE;
        end
        else begin
            a_reg <= a;
            b_reg <= b;
            case (op)
                2'b00: state <= ADD;
                2'b01: state <= SUB;
                2'b10: state <= MUL;
                2'b11: state <= DIV;
            endcase
        end
    end

    always @ (posedge reset or posedge state) begin
        case (state)
            IDLE: begin
                result <= 8'b0;
                valid <= 1'b0;
            end
            ADD: begin
                temp_result <= a_reg + b_reg;
                state <= IDLE;
            end
            SUB: begin
                temp_result <= a_reg - b_reg;
                state <= IDLE;
            end
            MUL: begin
                temp_result <= a_reg * b_reg;
                state <= IDLE;
            end
            DIV: begin
                temp_result <= a_reg / b_reg;
                state <= IDLE;
            end
        endcase
    end

    always @ (posedge reset or posedge temp_result) begin
        if (reset) begin
            result <= 8'b0;
            valid <= 1'b0;
        end
        else begin
            result <= temp_result;
            valid <= 1'b1;
        end
    end

endmodule

