module parity_tree (
    input [255:0] in,
    output reg out
);

wire [127:0] parity_0;
wire [127:0] parity_1;
wire [127:0] parity_2;
wire [127:0] parity_3;
wire [63:0] parity_4;
wire [31:0] parity_5;
wire [15:0] parity_6;
wire [7:0] parity_7;
wire [3:0] parity_8;
wire [1:0] parity_9;

// Divide the input vector into sub-vectors
assign parity_0 = in[127:0] ^ in[255:128];
assign parity_1 = in[63:0] ^ in[127:64];
assign parity_2 = in[191:128] ^ in[255:192];
assign parity_3 = in[255:128] ^ in[191:64];
assign parity_4 = {parity_0[63:0], parity_0[127:64], parity_1[31:0], parity_1[63:32], parity_2[15:0], parity_2[31:16], parity_3[7:0], parity_3[15:8]};
assign parity_5 = {parity_4[31:0], parity_4[63:32], parity_4[95:64], parity_4[127:96]};
assign parity_6 = {parity_5[15:0], parity_5[31:16], parity_5[47:32], parity_5[63:48]};
assign parity_7 = {parity_6[7:0], parity_6[15:8], parity_6[23:16], parity_6[31:24]};
assign parity_8 = {parity_7[3:0], parity_7[7:4], parity_7[11:8], parity_7[15:12]};
assign parity_9 = {parity_8[1:0], parity_8[3:2], parity_8[5:4], parity_8[7:6]};

// Combine the sub-vector parities using a tree structure
always @* begin
    case (parity_9)
        2'b00: out = 1'b1;
        2'b01: out = parity_8[0];
        2'b10: out = parity_8[1];
