module dds(
    input aclk,
    input [31:0]freq,
    output m_axis_data_tvalid,
    output [15:0]m_axis_data_tdata,
    output square_out
);

    // Constants
    localparam W = 16;
    localparam PI = 3.14159265358979323846;
    localparam MAX_AMPLITUDE = 32767;

    // Internal signals
    reg [31:0]phase_accumulator;
    reg [W-1:0]sine_out;
    reg square_out_reg;
    wire square_out = square_out_reg;

    // Calculate phase increment
    reg [31:0]phase_increment;
    always @(*) begin
        phase_increment = $unsigned(freq) * 4294967296 / 50000000;
    end

    // Update phase accumulator and generate sine wave
    always @(posedge aclk) begin
        phase_accumulator <= phase_accumulator + phase_increment;
        sine_out <= MAX_AMPLITUDE * $signed($sin(2 * PI * $unsigned(phase_accumulator) / 4294967296));
        square_out_reg <= sine_out > 0 ? 1 : 0;
    end

    // Output sine wave and square wave
    assign m_axis_data_tvalid = 1;
    assign m_axis_data_tdata = {sine_out, sine_out};

endmodule

module top_module (
    input clk,
    input reset, // Synchronous active-high reset
    input [7:0] d, // 8-bit input for the register
    input select, // Select input to choose between register and D flip-flops
    output [7:0] q, // 8-bit output from the active module
    output done // Signal indicating when all D flip-flops have finished loading their initial values
);

    reg [7:0] reg_out; // Output from the register
    reg [7:0] dff_out; // Output from the D flip-flops
    reg [7:0] and_out; // Output from the AND gate
    reg [7:0] init_val = 8'h3F; // Initial value for the D flip-flops
    reg [2:0] count = 3'b0; // Counter to track the number of D flip-flops that have finished loading their initial values

    // Register with active-high asynchronous reset
    always @ (posedge clk or posedge reset) begin
        if (reset) begin
            reg_out <= 8'h3A;
        end else begin
            reg_out <= d;
        end
    end

    // D flip-flops with active-high asynchronous reset
    always @ (posedge clk or posedge reset) begin
        if (reset) begin
            dff_out <= init_val;
        end else begin
            dff_out <= {dff_out[6:0], dff_out[7]};
        end
    end

    // AND gate to generate final output
    always @ (reg_out, dff_out) begin
        and_out = reg_out & dff_out;
    end

    // Control logic to select between register and D flip-flops
    always @ (select, reg_out, dff_out) begin
        if (select) begin
            q = dff_out;
        end else begin
            q = reg_out;
        end
    end

    // D flip-flop triggered by negative edge of the clock to generate done signal
    always @ (negedge clk or posedge reset) begin
        if (reset) begin
            count <= 3'b0;
            done <= 1'b0;
        end else begin
            if (count == 3'b111) begin
                done <= 1'b1;
            end else begin
                done <= 1'b0;
            end
            count <= count + 1;
        end
    end

endmodule

