        3'b100: SEG_pipe1 = 7'b0011001;
        3'b101: SEG_pipe1 = 7'b0010010;
        3'b110: SEG_pipe1 = 7'b0000010;
        3'b111: SEG_pipe1 = 7'b1111000;
    endcase
end

always @(posedge clk) begin
    SEG_pipe2 <= SEG_pipe1;
end

always @(posedge clk) begin
    SEG <= SEG_pipe2;
