module multi_port_buffer(
  input clk,
  input reset,
  input clear,
  input write_done,
  input access_done,
  input read_done,
  output write_ok,
  output write_ptr,
  output access_ok,
  output access_ptr,
  output read_ok,
  output read_ptr
);

  localparam PORT_WAIT = 2'b00;
  localparam PORT_USE = 2'b01;
  localparam BUFF_WRITABLE = 2'b00;
  localparam BUFF_ACCESSIBLE = 2'b01;
  localparam BUFF_READABLE = 2'b10;
  localparam BUFF_ERROR = 2'b11;

  reg [1:0] write_port_state, access_port_state, read_port_state;
  wire [1:0] buff_state[0:1];

  always @(posedge clk) begin
    if(reset | clear) begin
      write_port_state <= PORT_WAIT;
      access_port_state <= PORT_WAIT;
      read_port_state <= PORT_WAIT;
    end
    else begin
      case(write_port_state)
        PORT_WAIT:
          if(buff_state[0] == BUFF_WRITABLE)
            write_port_state <= PORT_USE;
        PORT_USE:
          if(write_done)
            write_port_state <= PORT_WAIT;
      endcase

      case(access_port_state)
        PORT_WAIT:
          if(buff_state[0] == BUFF_ACCESSIBLE)
            access_port_state <= PORT_USE;
        PORT_USE:
          if(access_done)
            access_port_state <= PORT_WAIT;
      endcase

      case(read_port_state)
        PORT_WAIT:
          if(buff_state[0] == BUFF_READABLE)
            read_port_state <= PORT_USE;
        PORT_USE:
          if(read_done)
            read_port_state <= PORT_WAIT;
      endcase
    end
  end

  assign write_ok = (write_port_state == PORT_USE);
  assign write_ptr = (write_port_state == PORT_USE);
  assign access_ok = (access_port_state == PORT_USE);
  assign access_ptr = (access_port_state == PORT_USE);
  assign read_ok = (read_port_state == PORT_USE);
  assign read_ptr = (read_port_state == PORT_USE);

  buff_sm #(.PORT_USE_FLAG(PORT_USE)) buff0_sm
    (.clk(clk), .reset(reset), .clear(clear),
     .write_done(write_done), .access_done(access_done), .read_done(read_done),
     .write_port_state(write_port_state), .access_port_state(access_port_state), .read_port_state(read_port_state),
     .buff_state(buff_state[0]));

  buff_sm #(.PORT_USE_FLAG(PORT_USE)) buff1_sm
    (.clk(clk), .reset(reset), .clear(clear),
     .write_done(write_done), .access_done(access_done), .read_done(read_done),
     .write_port_state(write_port_state), .access_port_state(access_port_state), .read_port_state(read_port_state),
     .buff_state(buff_state[1]));

endmodule

module write_back_mux (
    input clk,
    input rst,
    input [width-1:0] muxin_a,
    input [width-1:0] muxin_b,
    input [width-1:0] muxin_c,
    input [width-1:0] muxin_d,
    input [RFWBOP_WIDTH-1:0] rfwb_op,
    input wb_freeze,
    output [width-1:0] muxout,
    output [width-1:0] muxreg
);

//
// Internal wires and regs
//
reg [width-1:0] muxout;
reg [width-1:0] muxreg;

//
// Write-back multiplexer
//
always @(*) begin
    case(rfwb_op)
        2'b00: muxout = muxin_a;
        2'b01: muxout = muxin_b;
        2'b10: muxout = muxin_c;
        2'b11: muxout = muxin_d;
    endcase
end

//
// Registered output for forwarding
//
always @(posedge clk or posedge rst) begin
    if (rst) begin
        muxreg <= 32'd0;
    end
    else if (!wb_freeze) begin
        muxreg <= muxout;
    end
end

endmodule

module keyboard (
    input clk,
    input circuit_clk,
    input reset,
    input [3:0] COLUMN,
    output reg [3:0] ROW,
    output reg [3:0] KEY_BUFFER,
    output reg PRESS_VALID
);

    reg [3:0] DEBOUNCE_COUNT;
    reg [3:0] SCAN_CODE;
    reg [4:0] KEY_CODE;
    reg PRESS;
    wire PRESS_VALID;

    /* Scanning Code Generator */
    always @(posedge clk or negedge reset) begin
        if (!reset) SCAN_CODE <= 4'h0;
        else if (PRESS) SCAN_CODE <= SCAN_CODE + 1;
    end

    /* Scanning Keyboard */
    always @(SCAN_CODE or COLUMN) begin
        case (SCAN_CODE[3:2])
            2'b00 : ROW = 4'b1110;
            2'b01 : ROW = 4'b1101;
            2'b10 : ROW = 4'b1011;
            2'b11 : ROW = 4'b0111;
        endcase
        case (SCAN_CODE[1:0])
            2'b00 : PRESS = COLUMN[0];
            2'b01 : PRESS = COLUMN[1];
            2'b10 : PRESS = COLUMN[2];
            2'b11 : PRESS = COLUMN[3];
        endcase
    end

    /* Debounce Circuit */
    always @(posedge circuit_clk or negedge reset) begin
        if (!reset) DEBOUNCE_COUNT <= 4'h0;
        else if (PRESS) DEBOUNCE_COUNT <= 4'h0;
        else if (DEBOUNCE_COUNT <= 4'hE) DEBOUNCE_COUNT <= DEBOUNCE_COUNT + 1;
    end
    assign PRESS_VALID = (DEBOUNCE_COUNT == 4'hD) ? 1'b1 : 1'b0;

    /* Fetch Key Code */
    always @(negedge circuit_clk or negedge reset) begin
        if (!reset) KEY_CODE <= 5'b10000;
        else if (PRESS_VALID) KEY_CODE <= {1'b0,SCAN_CODE};
        else KEY_CODE <= 5'b10000;
    end

    /* Convert Key Code Into Number */
    always @(KEY_CODE) begin
        case (KEY_CODE)
            {1'b0,4'hC} : KEY_BUFFER = 4'h0; // 0
            {1'b0,4'hD} : KEY_BUFFER = 4'h1; // 1
            {1'b0,4'h9} : KEY_BUFFER = 4'h2; // 2
            {1'b0,4'h5} : KEY_BUFFER = 4'h3; // 3
            {1'b0,4'hE} : KEY_BUFFER = 4'h4; // 4
            {1'b0,4'hA} : KEY_BUFFER = 4'h5; // 5
            {1'b0,4'h6} : KEY_BUFFER = 4'h6; // 6
            {1'b0,4'hF} : KEY_BUFFER = 4'h7; // 7
            {1'b0,4'hB} : KEY_BUFFER = 4'h8; // 8
            {1'b0,4'h7} : KEY_BUFFER = 4'h9; // 9
            {1'b0,4'h8} : KEY_BUFFER = 4'hA; // A
            {1'b0,4'h4} : KEY_BUFFER = 4'hB; // B
            {1'b0,4'h3} : KEY_BUFFER = 4'hC; // C
            {1'b0,4'h2} : KEY_BUFFER = 4'hD; // D
            {1'b0,4'h1} : KEY_BUFFER = 4'hE; // E
            {1'b0,4'h0} : KEY_BUFFER = 4'hF; // F
            default: KEY_BUFFER = 4'h0;
        endcase
    end

endmodule

module nios_dut_nios2_gen2_0_cpu_nios2_oci_dtrace (
    // inputs:
    clk,
    cpu_d_address,
    cpu_d_read,
    cpu_d_readdata,
    cpu_d_wait,
    cpu_d_write,
    cpu_d_writedata,
    jrst_n,
    trc_ctrl,
    // outputs:
    atm,
    dtm
);

    output  [35:0] atm;
    output  [35:0] dtm;
    input            clk;
    input   [31:0] cpu_d_address;
    input            cpu_d_read;
    input   [31:0] cpu_d_readdata;
    input            cpu_d_wait;
    input            cpu_d_write;
    input   [31:0] cpu_d_writedata;
    input            jrst_n;
    input   [15:0] trc_ctrl;

    reg     [35:0] atm;
    reg     [35:0] dtm;
    wire    [31:0] cpu_d_address_0_padded;
    wire    [31:0] cpu_d_readdata_0_padded;
    wire    [31:0] cpu_d_writedata_0_padded;
    wire            dummy_tie_off;
    wire            record_load_addr;
    wire            record_load_data;
    wire            record_store_addr;
    wire            record_store_data;
    wire    [3:0]  td_mode_trc_ctrl;

    assign cpu_d_writedata_0_padded = {cpu_d_writedata, 32'b0};
    assign cpu_d_readdata_0_padded = {cpu_d_readdata, 32'b0};
    assign cpu_d_address_0_padded = {cpu_d_address, 32'b0};

    // nios_dut_nios2_gen2_0_cpu_nios2_oci_trc_ctrl_td_mode, which is an e_instance
    nios_dut_nios2_gen2_0_cpu_nios2_oci_td_mode nios_dut_nios2_gen2_0_cpu_nios2_oci_trc_ctrl_td_mode (
        .ctrl    (trc_ctrl[8:0]),
        .td_mode (td_mode_trc_ctrl)
    );

    assign {record_load_addr, record_store_addr, record_load_data, record_store_data} = td_mode_trc_ctrl;

    always @(posedge clk or negedge jrst_n) begin
        if (jrst_n == 0) begin
            atm <= 0;
            dtm <= 0;
        end else begin
            if (cpu_d_read) begin
                atm <= cpu_d_address_0_padded;
                dtm <= cpu_d_readdata_0_padded;
            end else if (cpu_d_write) begin
                atm <= cpu_d_address_0_padded;
                dtm <= cpu_d_writedata_0_padded;
            end else begin
                atm <= 0;
                dtm <= 0;
            end
        end
    end

    assign dummy_tie_off = cpu_d_wait | cpu_d_read | cpu_d_write;

