    input phy_gmii_rst,
    input phy_gmii_clk_en,
    input [7:0] phy_gmii_rxd,
    input phy_gmii_rx_dv,
    input phy_gmii_rx_er,
    input phy_int_n,
    input uart_rxd,
    input uart_cts,
    input [7:0] xfcp_mgt_up_tdata,
    input xfcp_mgt_up_tvalid,
    input xfcp_mgt_up_tlast,
    input xfcp_mgt_up_tuser,
    input xfcp_mgt_down_tready,
    output reg [7:0] led,
    output reg i2c_scl_o,
    output reg i2c_scl_t,
    output reg i2c_sda_o,
    output reg i2c_sda_t,
    output reg phy_tx_clk,
    output reg [7:0] phy_gmii_txd,
    output reg phy_gmii_tx_en,
    output reg phy_gmii_tx_er,
    output reg phy_reset_n,
    output reg uart_txd,
    output reg uart_rts,
    output reg [7:0] xfcp_mgt_down_tdata,
    output reg xfcp_mgt_down_tvalid,
    output reg xfcp_mgt_down_tlast,
    output reg xfcp_mgt_down_tuser,
    output reg xfcp_mgt_up_tready
);

always @(posedge clk) begin
    if (rst) begin
        led <= 0;
        i2c_scl_o <= 0;
        i2c_scl_t <= 0;
        i2c_sda_o <= 0;
        i2c_sda_t <= 0;
        phy_tx_clk <= 0;
        phy_gmii_txd <= 0;
        phy_gmii_tx_en <= 0;
        phy_gmii_tx_er <= 0;
        phy_reset_n <= 0;
        uart_txd <= 0;
        uart_rts <= 0;
        xfcp_mgt_down_tdata <= 0;
        xfcp_mgt_down_tvalid <= 0;
        xfcp_mgt_down_tlast <= 0;
        xfcp_mgt_down_tuser <= 0;
        xfcp_mgt_up_tready <= 0;
    end else begin
        // Process button inputs
        if (btnu) begin
            led <= led + 1;
        end
        if (btnl) begin
            led <= led - 1;
        end

        // Process switch inputs
        case (sw)
            4'b0000: begin
                phy_gmii_txd <= 8'b00000000;
            end
            4'b0001: begin
                phy_gmii_txd <= 8'b00000001;
            end
            4'b0010: begin
                phy_gmii_txd <= 8'b00000010;
            end
            4'b0100: begin
                phy_gmii_txd <= 8'b00000100;
            end
            4'b1000: begin
                phy_gmii_txd <= 8'b00001000;
            end
            default: begin
                phy_gmii_txd <= 8'b00000000;
            end
        endcase

        // Process UART inputs
        uart_txd <= uart_rxd;
        uart_rts <= uart_cts;

        // Process XFCP inputs
        xfcp_mgt_down_tdata <= xfcp_mgt_up_tdata;
        xfcp_mgt_down_tvalid <= xfcp_mgt_up_tvalid;
        xfcp_mgt_down_tlast <= xfcp_mgt_up_tlast;
        xfcp_mgt_down_tuser <= xfcp_mgt_up_tuser;
        xfcp_mgt_up_tready <= xfcp_mgt_down_tready;
    end
end

endmodule

module WcaReadDwordReg 
( 
     input   wire         reset,       //Active Hi
     input   wire         clock,       //System clock, should be synchronous with WcaRegbus
     input   wire         enableIn,    //Allows input if specified.
     input   wire  [31:0] in, 

   //Internal Interface.
    input   wire  [11:0] rbusCtrl,  // Address and control lines(12 total) { addr[7:0], readEnable, writeEnable, dataStrobe, clkbus}
    inout   wire  [7:0]  rbusData    // Tri-state I/O data.

);
parameter my_addr = 0;

    wire [7:0] Q0;
    wire [7:0] Q1;
    wire [7:0] Q2;
    wire [7:0] Q3;

    wire addrValid = (my_addr == rbusCtrl[11:4]);
    wire read      = addrValid & rbusCtrl[3];
    wire enable    = enableIn & ~addrValid; //Latch if address is us.

    //Count register for 4 pulse read.
    reg [1:0] select;
    always @(posedge rbusCtrl[0])
    begin
        if( reset | ~addrValid)
            select <= 2'h0;
        else if(rbusCtrl[1] & addrValid) 
            select <= select + 2'h1;
    end

    // Only allow latching when addres is not valid.   If preparing for a read, everything must be stable.
    WcaRegCore8  sr3( .Data(in[31:24]), .Enable( enable ), .Aclr(reset), .Clock(clock), .Q(Q3));
    WcaRegCore8  sr2( .Data(in[23:16]), .Enable( enable ), .Aclr(reset), .Clock(clock), .Q(Q2));
    WcaRegCore8  sr1( .Data(in[15:8]),  .Enable( enable ), .Aclr(reset), .Clock(clock), .Q(Q1));
    WcaRegCore8  sr0( .Data(in[7:0]),   .Enable( enable ), .Aclr(reset), .Clock(clock), .Q(Q0));

    //Place data on the buss if reading.
    assign rbusData = (read & select == 2'h0)  ? Q0 : 8'bz;
    assign rbusData = (read & select == 2'h1)  ? Q1 : rbusData;
    assign rbusData = (read & select == 2'h2)  ? Q2 : rbusData;
    assign rbusData = (read & select == 2'h3)  ? Q3 : rbusData;

endmodule

