    input [99:0] data,
    output reg [7:0] out_hi,
    output reg [7:0] out_lo,
    output reg [7:0] final_output
);

    reg [99:0] rotated_data;
    reg [15:0] split_data;

    rotator rotator_inst (
        .data_in(data),
        .shift(ena == 2'b00 ? 0 : ena == 2'b01 ? 1 : 2),
        .direction(ena[1]),
        .data_out(rotated_data)
    );

    splitter splitter_inst (
        .data_in(rotated_data[15:0]),
        .out_hi(out_hi),
        .out_lo(out_lo)
    );

    bitwise_or bitwise_or_inst (
        .in1(out_hi),
        .in2(out_lo),
        .out(final_output)
    );

    always @(posedge clk) begin
        if (load)
            rotated_data <= data;
    end

endmodule

