module TDC(
  input ref,
  input meas,
  output reg [31:0] code
);

parameter res = 1; // resolution of the TDC in nanoseconds
parameter max_time = 1000; // maximum time interval that can be measured in nanoseconds
parameter clk_freq = 100000000; // frequency of the reference clock signal in Hz

reg [31:0] counter;
reg [31:0] prev_counter;
reg [31:0] time_interval;

always @(posedge ref or posedge meas) begin
  if (ref && !meas) begin
    counter <= 0;
  end else if (!ref && meas) begin
    counter <= counter + 1;
  end
end

always @(posedge ref) begin
  prev_counter <= counter;
  time_interval <= (counter - prev_counter) * res;
  if (time_interval > max_time) begin
    code <= max_time / res;
  end else begin
    code <= time_interval / res;
  end
end

endmodule

module my_d_ff (
    input  wire RESET_B,
    input  wire CLK_N,
    input  wire D,
    output reg  Q,
    input  wire VPWR,
    input  wire VGND
);

    // Define internal wires
    wire        CLK_P;
    wire        RESET_B_N;

    // Invert reset signal
    assign      RESET_B_N = ~RESET_B;

    // Generate positive edge clock signal
    assign      CLK_P = ~CLK_N;

    // D flip-flop with asynchronous reset
    always @(posedge CLK_P or negedge RESET_B_N) begin
        if (!RESET_B_N) begin
            Q <= 0;
        end else begin
            Q <= D;
        end
    end

endmodule

module fifo_queue(clk, rst_l, data_in, wr_en, rd_en, data_out, empty, full);

parameter DEPTH = 64;
parameter WIDTH = 8;

input clk;
input rst_l;
input [WIDTH-1:0] data_in;
input wr_en;
input rd_en;

output [WIDTH-1:0] data_out;
output empty;
output full;

reg [WIDTH-1:0] mem [0:DEPTH-1];
reg [6:0] wr_ptr = 0;
reg [6:0] rd_ptr = 0;
reg [DEPTH-1:0] count = 0;

assign empty = (count == 0);
assign full = (count == DEPTH);

always @(posedge clk or negedge rst_l) begin
    if (~rst_l) begin
        wr_ptr <= 0;
        rd_ptr <= 0;
        count <= 0;
    end else begin
        if (wr_en && ~full) begin
            mem[wr_ptr] <= data_in;
            wr_ptr <= wr_ptr + 1;
            count <= count + 1;
        end
        if (rd_en && ~empty) begin
            data_out <= mem[rd_ptr];
            rd_ptr <= rd_ptr + 1;
            count <= count - 1;
        end
    end
end

endmodule

module top_module (
    input [3:0] A, B,
    input [2:0] OP,
    input [3:0] a, b,
    output [1:0] final_output
);

    wire [3:0] alu_result;
    wire [2:0] comparison_result;

    alu alu_inst (
        .A(A),
        .B(B),
        .OP(OP),
        .P(alu_result)
    );

    mag_comp_priority_encoder mag_comp_inst (
        .a(a),
        .b(b),
        .comparison_result(comparison_result)
    );

    assign final_output = (comparison_result == 3 && alu_result == 0) ? 2'b10 :
                          (comparison_result == 2) ? 2'b01 :
                          (comparison_result == 1) ? 2'b00 :
                          2'b11;

endmodule

module alu (
    input [3:0] A, B,
    input [2:0] OP,
    output reg [3:0] P
);

    always @(*) begin
        case (OP)
            3'b000: P = A & B;
            3'b001: P = A | B;
            3'b010: P = A + B;
            3'b011: P = A - B;
            3'b100: P = A ^ B;
            3'b101: P = ~A;
            3'b110: P = A << 1;
            3'b111: P = A >> 1;
            default: P = 4'bxxxx;
        endcase
    end

endmodule

module mag_comp_priority_encoder (
    input [3:0] a, b,
    output reg [2:0] comparison_result
);

    always @(*) begin
        if (a > b) begin
            comparison_result = 3'b010;
        end else if (a < b) begin
            comparison_result = 3'b001;
        end else begin
            comparison_result = 3'b000;
        end
    end

endmodule

module jk_ff(clk, rst, j, k, q, qbar);
    input clk, rst, j, k;
    output q, qbar;
    reg q, qbar;
    always @(posedge clk or posedge rst)
    begin
        if (rst)
        begin
            q <= 1'b0;
            qbar <= 1'b1;
        end
        else
        begin
            case ({j, k})
                2'b00: begin q <= q; qbar <= qbar; end
                2'b01: begin q <= 1'b0; qbar <= 1'b1; end
                2'b10: begin q <= 1'b1; qbar <= 1'b0; end
                2'b11: begin q <= ~q; qbar <= ~qbar; end
            endcase
        end
    end
endmodule

module top_module (
  input clk,
  input reset,
  output reg [3:0] binary_number
);

  reg [3:0] binary_num_reg;
  reg [2:0] ones_count_reg;

  binary_ones_counter ones_counter(.binary_in(binary_num_reg), .clk(clk), .reset(reset), .ones_count(ones_count_reg));

  always @(posedge clk) begin
    binary_num_reg <= binary_num_reg + 1;
  end

  always @(posedge clk) begin
    if (ones_count_reg > binary_num_reg) begin
      binary_number <= ones_count_reg;
    end else begin
      binary_number <= binary_num_reg;
    end
  end

endmodule

module binary_ones_counter (
  input [3:0] binary_in,
  input clk,
  input reset,
  output reg [2:0] ones_count
);

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      ones_count <= 0;
    end else begin
      case (binary_in)
        4'b0000: ones_count <= 0;
        4'b0001: ones_count <= 1;
        4'b0010: ones_count <= 1;
        4'b0011: ones_count <= 2;
        4'b0100: ones_count <= 1;
        4'b0101: ones_count <= 2;
        4'b0110: ones_count <= 2;
        4'b0111: ones_count <= 3;
        4'b1000: ones_count <= 1;
        4'b1001: ones_count <= 2;
        4'b1010: ones_count <= 2;
        4'b1011: ones_count <= 3;
        4'b1100: ones_count <= 2;
        4'b1101: ones_count <= 3;
        4'b1110: ones_count <= 3;
        4'b1111: ones_count <= 4;
      endcase
    end
  end

endmodule

module vending_machine (
  input clk,
  input reset,
  input coin,
  input [1:0] selection,
  output reg dispense
);

parameter IDLE = 2'b00, COIN_INSERTED = 2'b01, PRODUCT_SELECTED = 2'b10;
parameter PRICE_1 = 2'b00, PRICE_1_5 = 2'b01, PRICE_2 = 2'b10;

reg [1:0] state, price;
reg dispense_temp;

always @(posedge clk) begin
  if (reset) begin
    state <= IDLE;
    price <= PRICE_1;
    dispense_temp <= 1'b0;
  end
  else begin
    case (state)
      IDLE: begin
        if (coin) begin
          state <= COIN_INSERTED;
        end
        else if (selection != 2'b00) begin
          state <= PRODUCT_SELECTED;
          case (selection)
            2'b01: price <= PRICE_1;
            2'b10: price <= PRICE_1_5;
            2'b11: price <= PRICE_2;
          endcase
        end
      end
      COIN_INSERTED: begin
        if (coin) begin
          price <= price + 1;
        end
        else if (price <= PRICE_1_5) begin
          state <= PRODUCT_SELECTED;
        end
      end
      PRODUCT_SELECTED: begin
        if (coin && (price < PRICE_2)) begin
          price <= price + 1;
        end
        else if (coin && (price == PRICE_2)) begin
          dispense_temp <= 1'b1;
          state <= IDLE;
        end
        else if (selection != 2'b00) begin
          case (selection)
            2'b01: begin
              if (price >= PRICE_1) begin
                dispense_temp <= 1'b1;
                state <= IDLE;
              end
            end
            2'b10: begin
              if (price >= PRICE_1_5) begin
                dispense_temp <= 1'b1;
                state <= IDLE;
              end
            end
            2'b11: begin
              if (price >= PRICE_2) begin
                dispense_temp <= 1'b1;
                state <= IDLE;
              end
            end
          endcase
        end
      end
    endcase
  end
end

always @(posedge clk) begin
  if (reset) begin
    dispense <= 1'b0;
  end
  else begin
    dispense <= dispense_temp;
    dispense_temp <= 1'b0;
  end
end

endmodule

module priority_encoder (
    input [7:0] in,
    output reg [2:0] pos
);

reg [7:0] gray;
reg [2:0] binary;

// Binary-to-Gray code converter
always @(*) begin
    gray[0] = in[0];
    gray[1] = in[0] ^ in[1];
    gray[2] = in[1] ^ in[2];
    gray[3] = in[2] ^ in[3];
    gray[4] = in[3] ^ in[4];
    gray[5] = in[4] ^ in[5];
    gray[6] = in[5] ^ in[6];
    gray[7] = in[6] ^ in[7];
end

// Gray-to-binary code converter
always @(*) begin
    binary[2] = gray[7];
    binary[1] = binary[2] ^ gray[6];
    binary[0] = binary[1] ^ gray[5];
end

// Priority encoder
always @(*) begin
    if (binary[2]) pos = 3;
    else if (binary[1]) pos = 2;
    else if (binary[0]) pos = 1;
    else pos = 0;
end

endmodule

module pipeline (
  input clk,
  input reset,
  input in_valid,
  input [7:0] in_data,
  output out_valid,
  output [7:0] out_data
);

parameter SYMBOLS_PER_BEAT = 1;
parameter BITS_PER_SYMBOL = 8;
parameter PIPELINE_READY = 1;
localparam DATA_WIDTH = SYMBOLS_PER_BEAT * BITS_PER_SYMBOL;

reg [DATA_WIDTH-1:0] data0;
reg [DATA_WIDTH-1:0] data1;
reg [1:0] full;

assign out_valid = (full == 2);
assign out_data = (full == 2) ? data1 : 8'h0;

always @(posedge clk, posedge reset) begin
  if (reset) begin
    data0 <= {DATA_WIDTH{1'b0}};
    data1 <= {DATA_WIDTH{1'b0}};
    full <= 2'b00;
  end else begin
    if (PIPELINE_READY) begin
      if (full == 2'b00) begin
        if (in_valid) begin
          data0 <= in_data;
          full <= 2'b01;
        end
      end else if (full == 2'b01) begin
        if (out_valid) begin
          data1 <= data0;
          full <= 2'b10;
        end else if (in_valid) begin
          data1 <= in_data;
          full <= 2'b11;
        end
      end else if (full == 2'b10) begin
        if (out_valid) begin
          full <= 2'b01;
        end
      end else if (full == 2'b11) begin
        if (out_valid) begin
          full <= 2'b10;
        end
      end
    end else begin
      if (full == 2'b00) begin
        if (in_valid && out_valid) begin
          out_data <= in_data;
        end
        if (in_valid) begin
          full <= 2'b01;
        end
      end else if (full == 2'b01) begin
        if (out_valid) begin
          full <= 2'b00;
        end else if (in_valid) begin
          full <= 2'b11;
          data1 <= in_data;
        end
      end else if (full == 2'b11) begin
        if (out_valid) begin
          full <= 2'b01;
        end
      end
    end
  end
end

endmodule

module arithmetic_op(g, p, c_in, g_out, p_out, c_out);
  input [1:0] g, p;
  input c_in;
  output [1:0] g_out, p_out;
  output c_out;
  assign g_out = {{1'b0}, g[1]} | {{1'b0}, {1'b0}} & {g[0], p[1]};
  assign p_out = {p[1], p[0]} & {1'b1, 1'b1};
  assign c_out = {g[0], p[0]} & {c_in, 1'b1} | {{1'b0}, g[1]} & {{1'b0}, {1'b0}} & {c_in, p[1]};
endmodule

module assert_odd_parity_assume (clk, reset_n, test_expr, xzcheck_enable, odd_parity, x_detected, z_detected);
       parameter width = 1;
       input clk, reset_n;
       input [width-1:0] test_expr;
       input xzcheck_enable;
       output odd_parity, x_detected, z_detected;

       reg [width-1:0] odd_parity_reg;
       reg [width-1:0] x_detected_reg;
       reg [width-1:0] z_detected_reg;

       always @(posedge clk) begin
           if (!reset_n) begin
               odd_parity_reg <= 1'b0;
               x_detected_reg <= 1'b0;
               z_detected_reg <= 1'b0;
           end else begin
               odd_parity_reg <= ^test_expr;
               if (xzcheck_enable) begin
                   x_detected_reg <= |test_expr === 1'bx;
                   z_detected_reg <= |test_expr === 1'bz;
               end
           end
       end

       assign odd_parity = odd_parity_reg;
       assign x_detected = x_detected_reg;
       assign z_detected = z_detected_reg;
endmodule

