module PLL (
  input ref_signal,
  input fb_signal,
  output reg out_signal
);

parameter VCO_frequency = 1000; 
parameter N_divider = 10; 
parameter M_divider = 5; 
parameter K_divider = 2;

reg [31:0] phase_accumulator;
reg [31:0] phase_difference;
reg [31:0] control_signal;
reg [31:0] charge_pump_output;
reg [31:0] loop_filter_output;
reg [31:0] VCO_output;
reg [31:0] divided_VCO_frequency;
reg [31:0] reference_frequency;
reg [31:0] phase_difference2;
reg [31:0] K_divider_output;

wire [31:0] VCO_frequency_input;
wire [31:0] reference_frequency_input;

// Phase detector
always @(posedge ref_signal or posedge fb_signal) begin
  if (ref_signal && fb_signal) begin
    phase_difference <= phase_difference + VCO_frequency;
  end else if (ref_signal && !fb_signal) begin
    phase_difference <= phase_difference - VCO_frequency;
  end else if (!ref_signal && fb_signal) begin
    phase_difference <= phase_difference - VCO_frequency;
  end else begin
    phase_difference <= phase_difference + VCO_frequency;
  end
end

// Charge pump
always @(posedge ref_signal or posedge fb_signal) begin
  if (phase_difference > 0) begin
    charge_pump_output <= K_divider;
  end else begin
    charge_pump_output <= -K_divider;
  end
end

// Loop filter
always @(posedge ref_signal or posedge fb_signal) begin
  loop_filter_output <= loop_filter_output + charge_pump_output;
end

// VCO
always @(posedge ref_signal or posedge fb_signal) begin
  VCO_output <= VCO_output + loop_filter_output;
end

// N-divider
always @(posedge ref_signal or posedge fb_signal) begin
  divided_VCO_frequency <= VCO_output / N_divider;
end

// M-divider
always @(posedge ref_signal or posedge fb_signal) begin
  reference_frequency <= divided_VCO_frequency / M_divider;
end

// Phase detector 2
always @(posedge ref_signal or posedge fb_signal) begin
  if (ref_signal && reference_frequency) begin
    phase_difference2 <= phase_difference2 + reference_frequency;
  end else if (ref_signal && !reference_frequency) begin
    phase_difference2 <= phase_difference2 - reference_frequency;
  end else if (!ref_signal && reference_frequency) begin
    phase_difference2 <= phase_difference2 - reference_frequency;
  end else begin
    phase_difference2 <= phase_difference2 + reference_frequency;
  end
end

// K-divider
always @(posedge ref_signal or posedge fb_signal) begin
  K_divider_output <= K_divider_output + phase_difference2;
end

// Output signal
always @(posedge ref_signal or posedge fb_signal) begin
  out_signal <= VCO_output[VCO_frequency-1];
end

assign VCO_frequency_input = VCO_frequency;
assign reference_frequency_input = reference_frequency;

endmodule

module top(input clk, stb, di, output do);
    localparam integer DIN_N = 256;
    localparam integer DOUT_N = 256;

    reg [DIN_N-1:0] din;
    wire [DOUT_N-1:0] dout;

    reg [DIN_N-1:0] din_shr;
    reg [DOUT_N-1:0] dout_shr;

    always @(posedge clk) begin
        din_shr <= {din_shr, di};
        dout_shr <= {dout_shr, din_shr[DIN_N-1]};
        if (stb) begin
            din <= din_shr;
            dout_shr <= dout;
        end
    end

    assign do = dout_shr[DOUT_N-1];

    roi roi (
        .clk(clk),
        .din(din),
        .dout(dout)
    );
endmodule

module booth_multiplier (
    input signed [15:0] A,
    input signed [15:0] B,
    output reg signed [15:0] result
);

reg signed [31:0] product;
reg signed [15:0] multiplier;
reg signed [15:0] multiplicand;
reg [4:0] counter;

always @(*) begin
    multiplier = A;
    multiplicand = B;
    counter = 16;
    product = 0;

    while (counter > 0) begin
        if (multiplier[0] == 1) begin
            product = product + (multiplicand << (counter-1));
        end else if (multiplier[0] == 0 && multiplier[1] == 1) begin
            product = product - (multiplicand << (counter-1));
        end

        multiplier = multiplier >> 1;
        counter = counter - 1;
    end

    result = product[15:0];
end

endmodule

module adder_subtractor(output reg [3:0] SUM, output reg C_OUT, input [3:0] A, input [3:0] B, input SUB);

	reg [3:0] temp;

	always @(*) begin
		if(SUB == 0) begin
			temp = A + B;
			SUM = temp;
			C_OUT = (temp[4] == 1) ? 1 : 0;
		end
		else begin
			temp = A - B;
			SUM = temp;
			C_OUT = (temp[4] == 1) ? 1 : 0;
		end
	end

endmodule

module vga_display_controller (
    input clk,
    input rst,
    input [3:0] attr_plane_enable,
    input x_dotclockdiv2,
    input [9:0] h_count,
    input [9:0] v_count,
    input horiz_sync_i,
    input video_on_h_i,
    output reg [17:1] csr_adr_o,
    input [15:0] csr_dat_i,
    output csr_stb_o,
    output video_on_h_o,
    output horiz_sync_o,
    output reg [3:0] attr,
    output bit0,
    output bit1,
    output bit2,
    output bit3
  );

  // Registers and net
  reg [11:0] row_addr;
  reg [ 5:0] col_addr;
  reg [14:0] word_offset;
  reg [ 1:0] plane_addr0;
  reg [ 1:0] plane_addr;
  reg [15:0] plane0;
  reg [15:0] plane0_tmp;
  reg [15:0] plane1;
  reg [15:0] plane1_tmp;
  reg [15:0] plane2;
  reg [15:0] plane2_tmp;
  reg [15:0] plane3;
  reg [ 7:0] bit_mask0;
  reg [ 7:0] bit_mask1;

  wire [15:0] bit_mask;
  wire        v_count0;

  wire bit3, bit2, bit1, bit0;

  reg [9:0] video_on_h;
  reg [9:0] horiz_sync;
  reg [7:0] pipe;

  // Continous assignments
  assign csr_adr_o = { word_offset, plane_addr };
  assign bit_mask  = { bit_mask1, bit_mask0 };

  assign bit0 = |(bit_mask & plane0);
  assign bit1 = |(bit_mask & plane1);
  assign bit2 = |(bit_mask & plane2);
  assign bit3 = |(bit_mask & plane3);

  assign video_on_h_o = video_on_h[9];
  assign horiz_sync_o = horiz_sync[9];
  assign csr_stb_o    = |pipe[4:1];
  assign v_count0     = x_dotclockdiv2 ? 1'b0 : v_count[0];

  // Behaviour
  // Pipeline count
  always @(posedge clk)
    pipe <= rst ? 8'b0 : { pipe[6:0],
      x_dotclockdiv2 ? (h_count[4:0]==5'h0) : (h_count[3:0]==4'h0) };

  // video_on_h
  always @(posedge clk)
    video_on_h <= rst ? 10'b0 : { video_on_h[8:0], video_on_h_i };

  // horiz_sync
  always @(posedge clk)
    horiz_sync <= rst ? 10'b0 : { horiz_sync[8:0], horiz_sync_i };

  // Address generation
  always @(posedge clk)
    if (rst)
      begin
        row_addr    <= 12'h0;
        col_addr    <= 6'h0;
        plane_addr0 <= 2'b00;
        word_offset <= 15'h0;
        plane_addr  <= 2'b00;
      end
    else
      begin
        // Loading new row_addr and col_addr when h_count[3:0]==4'h0
        // v_count * 40 or 22 (depending on x_dotclockdiv2)
        row_addr <= { v_count[9:1], v_count0, 2'b00 } + { v_count[9:1], v_count0 }
                  + (x_dotclockdiv2 ? v_count[9:1] : 9'h0);
        col_addr <= x_dotclockdiv2 ? h_count[9:5] : h_count[9:4];
        plane_addr0 <= h_count[1:0];

        // Load new word_offset at +1
        word_offset <= (x_dotclockdiv2 ? { row_addr, 1'b0 }
                                       : { row_addr, 3'b000 }) + col_addr;
        plane_addr  <= plane_addr0;
      end

  // Temporary plane data
  always @(posedge clk)
    if (rst)
      begin
        plane0_tmp <= 16'h0;
        plane1_tmp <= 16'h0;
        plane2_tmp <= 16'h0;
      end
    else
      begin
        // Load plane0 when pipe == 4
        plane0_tmp <= pipe[4] ? csr_dat_i : plane0_tmp;
        plane1_tmp <= pipe[5] ? csr_dat_i : plane1_tmp;
        plane2_tmp <= pipe[6] ? csr_dat_i : plane2_tmp;
     end

  // Plane data
  always @(posedge clk)
    if (rst)
      begin
        plane0 <= 16'h0;
        plane1 <= 16'h0;
        plane2 <= 16'h0;
        plane3 <= 16'h0;
      end
    else
      begin
        plane0 <= pipe[7] ? plane0_tmp : plane0;
        plane1 <= pipe[7] ? plane1_tmp : plane1;
        plane2 <= pipe[7] ? plane2_tmp : plane2;
        plane3 <= pipe[7] ? csr_dat_i : plane3;
      end

  // Bit masks
  always @(posedge clk)
    if (rst)
      begin
        bit_mask0 <= 8'h0;
        bit_mask1 <= 8'h0;
      end
    else
      begin
        bit_mask0 <= (h_count[0] & x_dotclockdiv2) ? bit_mask0
                   : { pipe[7], bit_mask0[7:1] };
        bit_mask1 <= (h_count[0] & x_dotclockdiv2) ? bit_mask1
                   : { bit_mask0[0], bit_mask1[7:1] };
      end

  // attr
  always @(posedge clk)
    attr <= rst ? 4'h0 : (attr_plane_enable & { bit3, bit2, bit1, bit0 });

endmodule

module comparator (
