module spi_slave(
    input clk,
    input rst,
    input ss,
    input mosi,
    output miso,
    input sck,
    output done,
    input [7:0] din,
    output [7:0] dout
);

reg mosi_d, mosi_q;
reg ss_d, ss_q;
reg sck_d, sck_q;
reg sck_old_d, sck_old_q;
reg [7:0] data_d, data_q;
reg done_d, done_q;
reg [2:0] bit_ct_d, bit_ct_q;
reg [7:0] dout_d, dout_q;
reg miso_d, miso_q;

assign miso = miso_q;
assign done = done_q;
assign dout = dout_q;

always @(*) begin
    ss_d = ss;
    mosi_d = mosi;
    miso_d = miso_q;
    sck_d = sck;
    sck_old_d = sck_q;
    data_d = data_q;
    done_d = 1'b0;
    bit_ct_d = bit_ct_q;
    dout_d = dout_q;

    if (ss_q) begin
        bit_ct_d = 3'b0;
        data_d = din;
        miso_d = data_q[7];
    end else begin
        if (!sck_old_q && sck_q) begin // rising edge
            data_d = {data_q[6:0], mosi_q};
            bit_ct_d = bit_ct_q + 1'b1;
            if (bit_ct_q == 3'b111) begin
                dout_d = {data_q[6:0], mosi_q};
                done_d = 1'b1;
                data_d = din;
            end
        end else if (sck_old_q && !sck_q) begin // falling edge
            miso_d = data_q[7];
        end
    end
end

always @(posedge clk) begin
    if (rst) begin
        done_q <= 1'b0;
        bit_ct_q <= 3'b0;
        dout_q <= 8'b0;
        miso_q <= 1'b1;
    end else begin
        done_q <= done_d;
        bit_ct_q <= bit_ct_d;
        dout_q <= dout_d;
        miso_q <= miso_d;
    end

    sck_q <= sck_d;
    mosi_q <= mosi_d;
    ss_q <= ss_d;
    data_q <= data_d;
    sck_old_q <= sck_old_d;

end

endmodule

module pipe_mult
#(
  parameter DATA_WIDTH = 32,
  parameter STAGES = 8
)
(
  input wire clk,
  input wire rst,
  input wire en,
  input wire  [DATA_WIDTH-1:0] multiplier_i,
  input wire  [DATA_WIDTH-1:0] multicand_i,
  output wire [DATA_WIDTH-1:0] product_o,
  output wire done_o
);
  wire [STAGES-2:0]   inner_dones;
  wire [DATA_WIDTH*(STAGES-1)-1:0] inner_mpliers, inner_mcands, inner_prods;
  wire [DATA_WIDTH-1:0] final_mcand, final_mplier;

  stage_mult #(DATA_WIDTH, DATA_WIDTH / STAGES) stages [STAGES-1:0]
  (
    .clk(clk), .rst(rst),
    .en({inner_dones, en}),
    .mcand_i({inner_mcands, multicand_i}),
    .mplier_i({inner_mpliers, multiplier_i}),
    .prod_i({inner_prods, {DATA_WIDTH{1'b0}}}),
    .done_o({done_o, inner_dones}),
    .mcand_o({final_mcand, inner_mcands}),
    .mplier_o({final_mplier, inner_mpliers}),
    .prod_o({product_o, inner_prods})
  );

  // Input register
  reg [DATA_WIDTH-1:0] multiplier_reg;
  reg [DATA_WIDTH-1:0] multicand_reg;
  always @(posedge clk) begin
    if (rst) begin
      multiplier_reg <= 0;
      multicand_reg <= 0;
    end
    else if (en) begin
      multiplier_reg <= multiplier_i;
      multicand_reg <= multicand_i;
    end
  end

  // Output register
  reg [DATA_WIDTH-1:0] product_reg;
  always @(posedge clk) begin
    if (rst) begin
      product_reg <= 0;
    end
    else if (done_o) begin
      product_reg <= product_o;
    end
  end

endmodule

