module Processor(
    input clk,
    input Reset,
    input Write_Reg,
    input Mem_Write,
    input [15:0] offset,
    input [2:0] ALU_OP,
    input wire [4:0] W_Addr,
    input wire [4:0] RS,
    input wire [4:0] RT,
    output wire [31:0] A,
    output wire [31:0] Data_Bus,
    output wire [31:0] Result,
    output OF,
    output ZF
);

    wire [31:0] B;

    // Register File
    reg [31:0] Register_File [31:0];
    always @(posedge clk) begin
        if (Reset) begin
            Register_File <= 0;
        end else begin
            if (Write_Reg) begin
                Register_File[W_Addr] <= Data_Bus;
            end
        end
    end

    // ALU
    wire [31:0] A_signed, B_signed;
    assign A_signed = $signed(A);
    assign B_signed = $signed({{16{1'b0}}, offset});
    always @(*) begin
        case (ALU_OP)
            3'b000: Result = A + B_signed;
            3'b001: Result = A - B_signed;
            3'b010: Result = A & B_signed;
            3'b011: Result = A | B_signed;
            3'b100: Result = A ^ B_signed;
            3'b101: Result = A << offset;
            3'b110: Result = A >> offset;
            3'b111: Result = A;
        endcase
    end

    // Memory
    reg [31:0] Memory [1023:0];
    always @(posedge clk) begin
        if (Reset) begin
            Memory <= 0;
        end else begin
            if (Mem_Write) begin
                Memory[Result[7:2]] <= Data_Bus;
            end
        end
    end

    // Output
    assign A = Register_File[RS];
    assign B = Register_File[RT];
    assign Data_Bus = (Mem_Write) ? B : Result;
    assign OF = (Result[31] != Result[30]);
    assign ZF = (Result == 0);

endmodule

module adder (
    input [7:0] a,
    input [7:0] b,
    output [7:0] s,
    output overflow
);

wire [7:0] sum;
wire carry;
wire [7:0] a_inv;
wire [7:0] b_inv;
wire [7:0] sum_inv;

assign a_inv = ~a + 1;
assign b_inv = ~b + 1;
assign sum_inv = ~sum + 1;

assign {carry, sum} = (a_inv[0] & b_inv[0]) ? {1'b1, sum_inv[0]} :
                      (a_inv[0] | b_inv[0]) ? {1'b0, sum[0]} :
                      {1'b0, sum[0]};

generate
    genvar i;
    for (i = 1; i < 8; i = i + 1) begin : carry_select
        assign {carry, sum} = (a_inv[i] & b_inv[i]) ? {carry, sum_inv[i]} :
                              (a_inv[i] | b_inv[i]) ? {carry, sum[i]} :
                              {carry, sum[i]};
    end
endgenerate

assign overflow = (a[7] == b[7]) && (a[7] != s[7]);

endmodule

