module ring_node(
    input clk,
    input rst,
    input [1:0] ctrl_in,
    input [15:0] flit_in,
    input [1:0] dest_fifo_in,
    input en_local_req_in,
    input en_local_rep_in,
    input en_pass_req_in,
    input en_pass_rep_in,
    input [3:0] used_slots_pass_req_in,
    input [3:0] used_slots_pass_rep_in,
    output reg en_local_req,
    output reg en_local_rep,
    output reg en_pass_req,
    output reg en_pass_rep,
    output reg [3:0] used_slots_pass_req,
    output reg [3:0] used_slots_pass_rep,
    output reg [15:0] flit_out,
    output reg [1:0] ctrl_out,
    output reg [1:0] dest_fifo_out
);

// Declare internal signals
reg [1:0] state; // FSM state
reg [15:0] flit; // Current flit being processed
reg [1:0] ctrl; // Current control signal
reg [1:0] dest_fifo; // Current destination FIFO signal
reg [3:0] used_slots_pass_req_local; // Number of used slots in local pass request FIFO
reg [3:0] used_slots_pass_rep_local; // Number of used slots in local pass reply FIFO
wire [3:0] used_slots_pass_req_next; // Number of used slots in next node's pass request FIFO
wire [3:0] used_slots_pass_rep_next; // Number of used slots in next node's pass reply FIFO
wire [3:0] used_slots_pass_req_prev; // Number of used slots in previous node's pass request FIFO
wire [3:0] used_slots_pass_rep_prev; // Number of used slots in previous node's pass reply FIFO

// Declare constants
parameter IDLE = 2'b00; // FSM state for idle
parameter HEAD = 2'b01; // FSM state for processing head flit
parameter BODY = 2'b10; // FSM state for processing body flit
parameter TAIL = 2'b11; // FSM state for processing tail flit

// Initialize internal signals
initial begin
    state <= IDLE;
    flit <= 16'h0;
    ctrl <= 2'b00;
    dest_fifo <= 2'b00;
    used_slots_pass_req_local <= 4'd0;
    used_slots_pass_rep_local <= 4'd0;
end

// FSM for processing flits
always @(posedge clk) begin
    if (rst) begin
        state <= IDLE;
        flit <= 16'h0;
        ctrl <= 2'b00;
        dest_fifo <= 2'b00;
        used_slots_pass_req_local <= 4'd0;
        used_slots_pass_rep_local <= 4'd0;
    end else begin
        case (state)
            IDLE: begin
                if (en_local_req_in && (used_slots_pass_req_local < 4)) begin
                    // Send pass request to previous node
                    en_local_req <= 1;
                    used_slots_pass_req_local <= used_slots_pass_req_local + 1;
                end else if (en_local_rep_in && (used_slots_pass_rep_local < 4)) begin
                    // Send pass reply to previous node
                    en_local_rep <= 1;
                    used_slots_pass_rep_local <= used_slots_pass_rep_local + 1;
                end else if (en_pass_req_in && (used_slots_pass_req_local < 4)) begin
                    // Send pass request to next node
                    en_pass_req <= 1;
                    used_slots_pass_req_local <= used_slots_pass_req_local + 1;
                end else if (en_pass_rep_in && (used_slots_pass_rep_local < 4)) begin
                    // Send pass reply to next node
                    en_pass_rep <= 1;
                    used_slots_pass_rep_local <= used_slots_pass_rep_local + 1;
                end else if (flit_in != 16'h0) begin
                    // Start processing new flit
                    flit <= flit_in;
                    ctrl <= ctrl_in;
                    dest_fifo <= dest_fifo_in;
                    state <= HEAD;
                end
            end
            HEAD: begin
                // Send head flit to next node
                flit_out <= flit;
                ctrl_out <= ctrl;
                dest_fifo_out <= dest_fifo;
                used_slots_pass_req <= used_slots_pass_req_next;
                used_slots_pass_rep <= used_slots_pass_rep_next;
                state <= BODY;
            end
            BODY: begin
                // Send body flit to next node
                flit_out <= flit;
                ctrl_out <= ctrl;
                dest_fifo_out <= dest_fifo;
                used_slots_pass_req <= used_slots_pass_req_next;
                used_slots_pass_rep <= used_slots_pass_rep_next;
                if (flit[15:0] == 16'h0) begin
                    // End of flit
                    state <= TAIL;
                end
            end
            TAIL: begin
                // Send tail flit to next node
                flit_out <= flit;
                ctrl_out <= ctrl;
                dest_fifo_out <= dest_fifo;
                used_slots_pass_req <= used_slots_pass_req_next;
                used_slots_pass_rep <= used_slots_pass_rep_next;
                state <= IDLE;
            end
        endcase
    end
end

// Logic for controlling flow of flits
assign en_local_req = (used_slots_pass_req_prev < 4) && (state == IDLE) && (flit[15:0] != 16'h0);
assign en_local_rep = (used_slots_pass_rep_prev < 4) && (state == TAIL);
assign en_pass_req = (used_slots_pass_req_next < 4) && (state == TAIL);
assign en_pass_rep = (used_slots_pass_rep_next < 4) && (state == IDLE) && (flit[15:0] != 16'h0);

// Logic for updating number of used slots in pass request and reply FIFOs
always @(posedge clk) begin
    if (rst) begin
        used_slots_pass_req_local <= 4'd0;
        used_slots_pass_rep_local <= 4'd0;
    end else begin
        if (en_local_req && (used_slots_pass_req_prev < 4)) begin
            used_slots_pass_req_prev <= used_slots_pass_req_prev + 1;
        end else if (en_local_rep && (used_slots_pass_rep_prev < 4)) begin
            used_slots_pass_rep_prev <= used_slots_pass_rep_prev + 1;
        end else if (en_pass_req && (used_slots_pass_req_next < 4)) begin
            used_slots_pass_req_next <= used_slots_pass_req_next + 1;
        end else if (en_pass_rep && (used_slots_pass_rep_next < 4)) begin
            used_slots_pass_rep_next <= used_slots_pass_rep_next + 1;
        end else if ((state == TAIL) && (used_slots_pass_req_local > 0)) begin
            used_slots_pass_req_local <= used_slots_pass_req_local - 1;
        end else if ((state == IDLE) && (used_slots_pass_rep_local > 0)) begin
            used_slots_pass_rep_local <= used_slots_pass_rep_local - 1;
        end
    end
end

endmodule

