wire [7:0] lower_byte;
wire [7:0] upper_byte;
wire [7:0] xor_output;

barrel_shifter shifter(
    .clk(clk),
    .reset(reset),
    .data_in(data),
    .shift_amt(shift_amt),
    .left_enable(select == 2'b01),
    .right_enable(select == 2'b10),
    .data_out(shifted_data)
);

splitter splitter(
    .data_in(shifted_data),
