module top_module( 
  input                clk,
  input                rst_n,
  input  [3:0]         in,
  output               out_and,
  output               out_or,
  output               out_xor,
  output reg  [63:0]   Q
);

  // 4-input NAND module
  wire nand_out;
  assign nand_out = ~(in[0] & in[1] & in[2] & in[3]);
  assign out_and = nand_out;
  assign out_or = ~(~in[0] & ~in[1] & ~in[2] & ~in[3]);
  assign out_xor = ~(in[0] ^ in[1] ^ in[2] ^ in[3]);

  // Johnson counter
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      Q <= 64'b00000000;
    end else begin
      Q <= {Q[62:0], ~(Q[63] ^ Q[60])};
    end
  end

  // Final NAND operation module
  wire final_nand_out;
  assign final_nand_out = ~(nand_out & Q[63]);
  assign Q[0] = final_nand_out;

endmodule

module bitwise_or_logical_or_not_adder(
    input [2:0] a,
    input [2:0] b,
    output [2:0] out_or_bitwise,
    output out_or_logical,
    output [5:0] out_not,
    output [3:0] out_final
);

    // Bitwise-OR Module
    wire [2:0] bitwise_or;
    assign bitwise_or = a | b;
    assign out_or_bitwise = bitwise_or;

    // Logical-OR Module
    wire logical_or;
    assign logical_or = (a[0] | b[0]) | (a[1] | b[1]) | (a[2] | b[2]);
    assign out_or_logical = logical_or;

    // NOT Module for a and b
    wire [2:0] not_a;
    wire [2:0] not_b;
    assign not_a = ~a;
    assign not_b = ~b;
    assign out_not = {not_b, not_a};

    // Adder Module
    wire [3:0] adder_input;
    assign adder_input = {bitwise_or, logical_or};
    assign out_final = adder_input;

endmodule

module addsub(A, B, subtract, result);

  input [3:0] A;
  input [3:0] B;
  input subtract;
  output [3:0] result;

  wire carry;
  wire [3:0] B_neg;

  assign B_neg = ~B + 1; // Two's complement of B

  assign carry = subtract ? ~(A & B_neg) & (A | B_neg) : (A & B) | (A & carry) | (B & carry);

  assign result = subtract ? A + B_neg + carry : A + B + carry;

endmodule

module MMU(
    input clk,
    input [5:0] reqType,
    input [15:0] ofs,
    input [11:0] lbid,
    output reg [15:0] addr,
    output reg invalid
);

// Constants
localparam CODE_BASE = 16'h0000;
localparam DATA_BASE = 16'h4000;
localparam STACK_BASE = 16'h8000;
localparam BLOCK_SIZE = 16'h4000;
localparam CODE_LBID = 12'h000;
localparam DATA_LBID = 12'h001;
localparam STACK_LBID = 12'h002;
localparam LBTYPE_CODE = 6'h00;
localparam LBTYPE_DATA = 6'h01;
localparam LBTYPE_STACK = 6'h02;

// Internal signals
reg [15:0] base;
reg [15:0] count;
reg [11:0] lbidw;
reg [5:0] lbTypew;
reg [15:0] basew;
reg [15:0] countw;
reg we;

// Set default values for outputs
assign addr = 16'h0000;
assign invalid = 1'b0;

// Set default values for internal signals
initial begin
    base = 16'h0000;
    count = 16'h0000;
end

// Update internal signals on every clock cycle
always @(posedge clk) begin
    case(lbid)
        // CODE block
        CODE_LBID: begin
            base = CODE_BASE;
            count = BLOCK_SIZE;
        end
        // DATA block
        DATA_LBID: begin
            base = DATA_BASE;
            count = BLOCK_SIZE;
        end
        // STACK block
        STACK_LBID: begin
            base = STACK_BASE;
            count = BLOCK_SIZE;
        end
        // Invalid block ID
        default: invalid = 1'b1;
    endcase

    // Check if memory request is valid
    if (invalid == 1'b0) begin
        // Check if offset is within block bounds
        if (ofs >= count) invalid = 1'b1;
        else begin
            // Calculate physical address
            addr = base + ofs;
            // Check if memory request type is valid for block type
            case(lbid)
                CODE_LBID: lbTypew = LBTYPE_CODE;
                DATA_LBID: lbTypew = LBTYPE_DATA;
                STACK_LBID: lbTypew = LBTYPE_STACK;
            endcase
            if (reqType != lbTypew) invalid = 1'b1;
            else begin
                // Write enable is only high for write requests to data and stack blocks
                case(lbid)
                    DATA_LBID, STACK_LBID: we = (reqType == LBTYPE_DATA);
                    default: we = 1'b0;
                endcase
                // Set write parameters for data and stack blocks
                if (we == 1'b1) begin
                    lbidw = lbid;
                    basew = base;
                    countw = count;
                end
            end
        end
    end
end

endmodule

module LED_driver (
  input [15:0] brightness,
  output reg led_control
);

  reg [15:0] counter;
  reg pwm;

  always @ (posedge clk) begin
    if (counter == 65535) begin
      counter <= 0;
      pwm <= (counter < brightness);
    end else begin
      counter <= counter + 1;
      pwm <= (counter < brightness);
    end
  end

  always @ (posedge clk) begin
    if (pwm) begin
      led_control <= 1'b1;
    end else begin
      led_control <= 1'b0;
    end
  end

endmodule

module font_display(
    input [9:0] pix_x,
    input [9:0] pix_y,
    input score_on,
    input logo_on,
    input registration_on,
    input [7:0] font_word,
    output reg [3:0] text_on,
    output reg [6:0] char_addr,
    output reg [3:0] row_addr,
    output reg [2:0] bit_addr,
    output reg [2:0] text_rgb
);

    // FSM states
    parameter IDLE = 2'b00;
    parameter SCORE = 2'b01;
    parameter LOGO = 2'b10;
    parameter REGISTRATION = 2'b11;

    // FSM state and output registers
    reg [1:0] state_reg, state_next;
    reg [6:0] char_addr_reg, char_addr_next;
    reg [3:0] row_addr_reg, row_addr_next;
    reg [2:0] bit_addr_reg, bit_addr_next;
    reg [2:0] text_rgb_reg, text_rgb_next;

    // pixel coordinate registers
    reg [3:0] row_reg, bit_reg;

    // FSM state machine
    always @* begin
        state_next = IDLE;
        char_addr_next = 7'h00;
        row_addr_next = pix_y[5:2];
        bit_addr_next = pix_x[4:2];
        text_rgb_next = 3'b110;
        case(pix_x[8:5])
            4'h5: begin
                state_next = SCORE;
                char_addr_next = 7'h47; // G
                text_rgb_next = 3'b001; // green
            end
            4'h6: begin
                state_next = SCORE;
                char_addr_next = 7'h61; // a
                text_rgb_next = 3'b001; // green
            end
            4'h7: begin
                state_next = SCORE;
                char_addr_next = 7'h6d; // m
                text_rgb_next = 3'b001; // green
            end
            4'h8: begin
                state_next = SCORE;
                char_addr_next = 7'h65; // e
                text_rgb_next = 3'b001; // green
            end
            4'h9: begin
                state_next = LOGO;
                char_addr_next = 7'h00; // blank
                text_rgb_next = 3'b110; // yellow
            end
            4'ha: begin
                state_next = LOGO;
                char_addr_next = 7'h4f; // O
                text_rgb_next = 3'b011; // orange
            end
            4'hb: begin
                state_next = LOGO;
                char_addr_next = 7'h76; // v
                text_rgb_next = 3'b011; // orange
            end
            4'hc: begin
                state_next = LOGO;
                char_addr_next = 7'h65; // e
                text_rgb_next = 3'b011; // orange
            end
            default: begin
                state_next = REGISTRATION;
                char_addr_next = 7'h72; // r
                text_rgb_next = 3'b001; // green
            end
        endcase
    end

    // update state and output registers
    always @(posedge clk) begin
        state_reg <= state_next;
        char_addr_reg <= char_addr_next;
        row_addr_reg <= row_addr_next;
        bit_addr_reg <= bit_addr_next;
        text_rgb_reg <= text_rgb_next;
    end

    // update pixel coordinate registers
    always @(posedge clk) begin
        row_reg <= pix_y[1:0];
        bit_reg <= pix_x[1:0];
    end

    // multiplexer for font ROM addresses and rgb
    always @* begin
        text_on = state_reg;
        case(state_reg)
            IDLE: begin
                char_addr = char_addr_reg;
                row_addr = row_addr_reg;
                bit_addr = bit_addr_reg;
                text_rgb = text_rgb_reg;
            end
            SCORE: begin
                char_addr = char_addr_reg;
                row_addr = row_reg + (char_addr_reg[6:0] << 2);
                bit_addr = bit_reg;
                text_rgb = text_rgb_reg;
            end
            LOGO: begin
                char_addr = char_addr_reg;
                row_addr = row_reg + (char_addr_reg[6:0] << 2);
                bit_addr = bit_reg;
                if (font_word[bit_reg])
                    text_rgb = text_rgb_reg;
                else
                    text_rgb = 3'b110; // yellow
            end
            REGISTRATION: begin
                char_addr = char_addr_reg;
                row_addr = row_addr_reg;
                bit_addr = bit_addr_reg;
                text_rgb = text_rgb_reg;
            end
        endcase
    end

endmodule

module t(
