    input clk,
    input slowena,
    input reset,
    input [3:0] threshold,
    output reg [3:0] count,
    output reg high_if_count_greater_than_threshold,
    output reg [3:0] final_output
);

// Counter module
reg [3:0] counter;
always @(posedge clk) begin
    if (reset) begin
        counter <= 4'b0;
    end else if (slowena) begin
        counter <= counter + 1;
    end
end

// Comparator module
always @(counter, threshold) begin
    if (counter >= threshold) begin
        high_if_count_greater_than_threshold <= 1;
    end else begin
        high_if_count_greater_than_threshold <= 0;
    end
end

// Logical AND gate
always @(posedge clk) begin
    final_output <= counter & high_if_count_greater_than_threshold;
end

endmodule

module OneHotStateMachine(
  input [n-1:0] in,
  output [n-1:0] out
);

parameter n = 4; // number of states

reg [n-1:0] state; // state signals

// Connect inputs to current state signal
always @ (in) begin
  state <= in;
end

// Connect current state signal to output signals
assign out = state;

// Priority encoder to determine which state signal should be high
always @ (state) begin
  case(state)
    1'b0001: state = 1'b0010;
    1'b0010: state = 1'b0100;
    1'b0100: state = 1'b1000;
    1'b1000: state = 1'b0001;
  endcase
end

endmodule

