module i2c_master (
  input clk,
  input rst_n,
  output reg sda_out,
  input sda_in,
  output reg scl_out,
  output reg sda_ack,
  output reg sda_state
);

  parameter IDLE = 2'b00;
  parameter START = 2'b01;
  parameter ADDRESS = 2'b10;
  parameter DATA = 2'b11;

  reg [7:0] device_addr;
  reg [7:0] data_byte;
  reg [1:0] state;
  reg [2:0] bit_counter;
  reg [2:0] byte_counter;
  reg read_mode;
  reg write_mode;
  reg stop_condition;

  assign sda_state = sda_out;

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      sda_out <= 1'b1;
      scl_out <= 1'b1;
      sda_ack <= 1'b0;
      state <= IDLE;
      bit_counter <= 3'b0;
      byte_counter <= 3'b0;
      read_mode <= 1'b0;
      write_mode <= 1'b0;
      stop_condition <= 1'b0;
    end else begin
      case (state)
        IDLE: begin
          sda_out <= 1'b1;
          scl_out <= 1'b1;
          sda_ack <= 1'b0;
          if (!sda_in && !scl_in) begin
            state <= START;
          end
        end
        START: begin
          sda_out <= 1'b0;
          scl_out <= 1'b0;
          sda_ack <= 1'b0;
          if (bit_counter == 3'b001) begin
            state <= ADDRESS;
            bit_counter <= 3'b0;
          end else begin
            bit_counter <= bit_counter + 1;
          end
        end
        ADDRESS: begin
          sda_out <= device_addr[bit_counter];
          scl_out <= 1'b0;
          sda_ack <= 1'b0;
          if (bit_counter == 3'b100) begin
            if (read_mode) begin
              state <= DATA;
              bit_counter <= 3'b0;
              byte_counter <= 3'b0;
            end else if (write_mode) begin
              state <= DATA;
              bit_counter <= 3'b0;
              byte_counter <= 3'b0;
              sda_out <= data_byte[7];
            end else begin
              state <= IDLE;
              bit_counter <= 3'b0;
              sda_out <= 1'b1;
              stop_condition <= 1'b1;
            end
          end else begin
            bit_counter <= bit_counter + 1;
          end
        end
        DATA: begin
          if (read_mode) begin
            sda_out <= sda_in;
            scl_out <= 1'b0;
            sda_ack <= 1'b1;
            if (bit_counter == 3'b100) begin
              byte_counter <= byte_counter + 1;
              if (byte_counter == 3'b111) begin
                state <= IDLE;
                bit_counter <= 3'b0;
                sda_out <= 1'b1;
                stop_condition <= 1'b1;
              end else begin
                state <= ADDRESS;
                bit_counter <= 3'b0;
              end
            end else begin
              bit_counter <= bit_counter + 1;
            end
          end else if (write_mode) begin
            if (bit_counter == 3'b100) begin
              byte_counter <= byte_counter + 1;
              if (byte_counter == 3'b111) begin
                state <= IDLE;
                bit_counter <= 3'b0;
                sda_out <= 1'b1;
                stop_condition <= 1'b1;
              end else begin
                state <= ADDRESS;
                bit_counter <= 3'b0;
              end
            end else begin
              sda_out <= data_byte[bit_counter];
              scl_out <= 1'b0;
              sda_ack <= 1'b0;
              bit_counter <= bit_counter + 1;
            end
          end
        end
      endcase
    end
  end

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      device_addr <= 8'b00000000;
      data_byte <= 8'b00000000;
    end else begin
      if (state == START || state == ADDRESS) begin
        device_addr <= sda_in;
      end else if (state == DATA && write_mode) begin
        data_byte <= sda_in;
      end
    end
  end

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      sda_ack <= 1'b0;
    end else begin
      if (state == ADDRESS && !sda_in && scl_in) begin
        read_mode <= 1'b1;
        write_mode <= 1'b0;
      end else if (state == ADDRESS && sda_in && scl_in) begin
        read_mode <= 1'b0;
        write_mode <= 1'b1;
      end else if (state == DATA && read_mode && !sda_in && scl_in) begin
        sda_ack <= 1'b1;
      end else if (state == DATA && write_mode && sda_in && scl_in) begin
        sda_ack <= 1'b1;
      end else if (stop_condition && scl_in) begin
        stop_condition <= 1'b0;
      end
    end
  end

endmodule

module locked_clock (
  input CLKIN,
  input PWRDWN,
  input RST,
  output reg LOCKED
);

  parameter IS_PWRDWN_INVERTED = 0;
  parameter IS_RST_INVERTED = 0;
  parameter REF_CLK_JITTER_MAX = 100.0;
  parameter ref_clock_input_freq_MHz_min = 400.0;
  parameter ref_clock_input_freq_MHz_max = 1066.0;

  wire CLKIN_INV = ~CLKIN;
  wire PWRDWN_INV = PWRDWN ^ IS_PWRDWN_INVERTED;
  wire RST_INV = RST ^ IS_RST_INVERTED;

  reg [4:0] count_clks = 0;
  reg [31:0] last_period = 0;
  reg [31:0] current_period = 0;
  reg [31:0] last_last_period = 0;
  reg [31:0] current_freq = 0;
  reg [31:0] last_freq = 0;
  reg [31:0] avg_freq = 0;
  reg [31:0] ref_freq_MHz = 0;
  reg [31:0] last_ref_freq_MHz = 0;
  reg [31:0] ref_period = 0;
  reg [31:0] last_ref_period = 0;
  reg [31:0] ref_period_diff = 0;
  reg [31:0] last_ref_period_diff = 0;
  reg [31:0] same_period_count = 0;
  reg [31:0] different_period_count = 0;
  reg [31:0] same_period_count_last = 0;

  always @(posedge CLKIN_INV) begin
    if (PWRDWN_INV || RST_INV) begin
      LOCKED <= 0;
      count_clks <= 0;
      same_period_count <= 0;
      different_period_count <= 0;
      last_period <= 0;
      current_period <= 0;
      last_last_period <= 0;
      current_freq <= 0;
      last_freq <= 0;
      avg_freq <= 0;
      ref_freq_MHz <= 0;
      last_ref_freq_MHz <= 0;
      ref_period <= 0;
      last_ref_period <= 0;
      ref_period_diff <= 0;
      last_ref_period_diff <= 0;
      same_period_count_last <= 0;
    end else begin
      last_last_period <= last_period;
      last_period <= current_period;
      current_period <= $time - ref_period;
      last_freq <= current_freq;
      current_freq <= 1000000000 / current_period;
      last_ref_freq_MHz <= ref_freq_MHz;
      ref_freq_MHz <= 1000000 / ref_period;
      last_ref_period <= ref_period;
      ref_period <= $time - last_ref_period_diff;
      last_ref_period_diff <= ref_period_diff;
      ref_period_diff <= $time - last_period;
      if (last_period - current_period < REF_CLK_JITTER_MAX && current_period - last_period < REF_CLK_JITTER_MAX) begin
        if (same_period_count < 5) begin
          same_period_count <= same_period_count + 1;
        end else begin
          if (different_period_count == 0) begin
            last_ref_period_diff <= last_period;
          end
          different_period_count <= different_period_count + 1;
          same_period_count_last <= same_period_count;
          same_period_count <= 0;
        end
      end else begin
        different_period_count <= 0;
        same_period_count_last <= same_period_count;
        same_period_count <= 1;
      end
      if (different_period_count == 0 && same_period_count_last >= 5 && count_clks < 5) begin
        count_clks <= count_clks + 1;
      end else if (different_period_count > 0 || (same_period_count_last >= 5 && count_clks == 5)) begin
        avg_freq <= (last_ref_freq_MHz + ref_freq_MHz) / 2;
        if (avg_freq >= ref_clock_input_freq_MHz_min && avg_freq <= ref_clock_input_freq_MHz_max) begin
          LOCKED <= 1;
        end else begin
          LOCKED <= 0;
        end
        count_clks <= 0;
      end else begin
        LOCKED <= 0;
        count_clks <= 0;
      end
    end
  end

endmodule

