module comparator (
    input [3:0] a,
    input [3:0] b,
    output reg eq,
    output reg gt_a,
    output reg gt_b
);

    always @(*) begin
        if (a == b) begin
            eq = 1;
            gt_a = 0;
            gt_b = 0;
        end else if (a > b) begin
            eq = 0;
            gt_a = 1;
            gt_b = 0;
        end else begin
            eq = 0;
            gt_a = 0;
            gt_b = 1;
        end
    end

endmodule

module top_module (
    input clk,
    input reset,
    input [7:0] A,
    input [7:0] B,
    input [3:0] a,
    input [3:0] b,
    output reg [15:0] P,
    output reg out
);

    wire eq, gt_a, gt_b;

    sequential_multiplier multiplier(
        .clk(clk),
        .A(A),
        .B(B),
        .P(P)
    );

    comparator comp(
        .a(a),
        .b(b),
        .eq(eq),
        .gt_a(gt_a),
        .gt_b(gt_b)
    );

    always @(posedge clk) begin
        if (reset) begin
            P <= 0;
            out <= 0;
        end else begin
            if (eq) begin
                out <= 1;
                P <= P;
            end else if (gt_a) begin
                out <= 1;
                P <= gt_a;
            end else begin
                out <= 1;
                P <= gt_b;
            end
        end
    end

endmodule

