module DmaController(input clk, input ce, input reset,
                     input odd_cycle,               // Current cycle even or odd?
                     input sprite_trigger,          // Sprite DMA trigger?
                     input dmc_trigger,             // DMC DMA trigger?
                     input cpu_read,                // CPU is in a read cycle?
                     input [7:0] data_from_cpu,     // Data written by CPU?
                     input [7:0] data_from_ram,     // Data read from RAM?
                     input [15:0] dmc_dma_addr,     // DMC DMA Address
                     output [15:0] aout,            // Address to access
                     output aout_enable,            // DMA controller wants bus control
                     output read,                   // 1 = read, 0 = write
                     output [7:0] data_to_ram,      // Value to write to RAM
                     output dmc_ack,                // ACK the DMC DMA
                     output pause_cpu);             // CPU is paused
  reg dmc_state;
  reg [1:0] spr_state;
  reg [7:0] sprite_dma_lastval;
  reg [15:0] sprite_dma_addr;     // sprite dma source addr
  wire [8:0] new_sprite_dma_addr = sprite_dma_addr[7:0] + 8'h01;
  always @(posedge clk) if (reset) begin
    dmc_state <= 0;
    spr_state <= 0;    
    sprite_dma_lastval <= 0;
    sprite_dma_addr <= 0;
  end else if (ce) begin
    if (dmc_state == 0 && dmc_trigger && cpu_read && !odd_cycle) dmc_state <= 1;
    if (dmc_state == 1 && !odd_cycle) dmc_state <= 0;

    if (sprite_trigger) begin sprite_dma_addr <= {data_from_cpu, 8'h00}; spr_state <= 1; end
    if (spr_state == 1 && cpu_read && odd_cycle) spr_state <= 3;
    if (spr_state[1] && !odd_cycle && dmc_state == 1) spr_state <= 1;
    if (spr_state[1] && odd_cycle) sprite_dma_addr[7:0] <= new_sprite_dma_addr[7:0];
    if (spr_state[1] && odd_cycle && new_sprite_dma_addr[8]) spr_state <= 0;
    if (spr_state[1]) sprite_dma_lastval <= data_from_ram;
  end
  assign pause_cpu = (spr_state[0] || dmc_trigger) && cpu_read;
  assign dmc_ack   = (dmc_state == 1 && !odd_cycle);
  assign aout_enable = dmc_ack || spr_state[1];
  assign read = !odd_cycle;
  assign data_to_ram = sprite_dma_lastval;
  assign aout = dmc_ack ? dmc_dma_addr : !odd_cycle ? sprite_dma_addr : 16'h2004;
endmodule

module tone_generator (
  input clk,
  input rst,
  input [1:0] tone_sel,
  input [31:0] dur,
  input [1:0] vol,
  output tone
);

  // Define constants for DTMF frequencies
  parameter integer FREQ_1 = 697;
  parameter integer FREQ_2 = 770;
  parameter integer FREQ_3 = 852;
  parameter integer FREQ_A = 1209;
  parameter integer FREQ_4 = 1209;
  parameter integer FREQ_5 = 1336;
  parameter integer FREQ_6 = 1477;
  parameter integer FREQ_B = 1336;
  parameter integer FREQ_7 = 1477;
  parameter integer FREQ_8 = 1633;
  parameter integer FREQ_9 = 941;
  parameter integer FREQ_C = 1633;
  parameter integer FREQ_STAR = 941;
  parameter integer FREQ_0 = 1336;
  parameter integer FREQ_HASH = 1477;
  parameter integer FREQ_D = 1633;

  // Define constants for sine wave lookup table
  parameter integer SINE_TABLE_SIZE = 256;
  parameter integer SINE_TABLE_WIDTH = 12;
  parameter integer SINE_TABLE_MASK = SINE_TABLE_SIZE - 1;

  // Define constants for square wave counter
  parameter integer SQUARE_WAVE_PERIOD = 200000000 / FREQ_1; // 200 MHz clock frequency

  // Define signals
  reg [SINE_TABLE_WIDTH-1:0] sine_table [0:SINE_TABLE_MASK];
  reg [31:0] tone_counter;
  reg [31:0] duration_counter;
  reg [31:0] volume_counter;
  reg [31:0] sine_index;
  reg [31:0] square_index;
  reg [1:0] tone_type;
  wire [11:0] sine_value;
  wire square_value;

  // Initialize sine table
  initial begin
    for (sine_index = 0; sine_index < SINE_TABLE_SIZE; sine_index = sine_index + 1) begin
      sine_table[sine_index] = $signed(4096 * sin(2 * $pi * sine_index / SINE_TABLE_SIZE));
    end
  end

  // Generate tone based on tone selector input
  always @(posedge clk, negedge rst) begin
    if (~rst) begin
      tone_counter <= 0;
      duration_counter <= 0;
      volume_counter <= 0;
      sine_index <= 0;
      square_index <= 0;
      tone_type <= 0;
      tone <= 0;
    end else begin
      case (tone_sel)
        2'b00: begin // DTMF tone
          case (tone_type)
            2'b00: begin // Frequency 1
              sine_value <= sine_table[sine_index];
              tone <= volume_counter < dur ? sine_value : 0;
              tone_counter <= tone_counter + 1;
              if (tone_counter == 200000000 / FREQ_1) begin
                tone_counter <= 0;
                tone_type <= 2'b01;
                sine_index <= 0;
              end else begin
                sine_index <= sine_index + (SINE_TABLE_SIZE * FREQ_1) / 200000000;
              end
            end
            2'b01: begin // Frequency 2
              sine_value <= sine_table[sine_index];
              tone <= volume_counter < dur ? sine_value : 0;
              tone_counter <= tone_counter + 1;
              if (tone_counter == 200000000 / FREQ_1) begin
                tone_counter <= 0;
                tone_type <= 2'b10;
                sine_index <= 0;
              end else begin
                sine_index <= sine_index + (SINE_TABLE_SIZE * FREQ_2) / 200000000;
              end
            end
            2'b10: begin // Frequency 3
              sine_value <= sine_table[sine_index];
              tone <= volume_counter < dur ? sine_value : 0;
              tone_counter <= tone_counter + 1;
              if (tone_counter == 200000000 / FREQ_1) begin
                tone_counter <= 0;
                tone_type <= 2'b11;
                sine_index <= 0;
              end else begin
                sine_index <= sine_index + (SINE_TABLE_SIZE * FREQ_3) / 200000000;
              end
            end
            2'b11: begin // Frequency 4
              sine_value <= sine_table[sine_index];
              tone <= volume_counter < dur ? sine_value : 0;
              tone_counter <= tone_counter + 1;
              if (tone_counter == 200000000 / FREQ_1) begin
                tone_counter <= 0;
                tone_type <= 2'b00;
                sine_index <= 0;
              end else begin
                sine_index <= sine_index + (SINE_TABLE_SIZE * FREQ_4) / 200000000;
              end
            end
          endcase
        end
        2'b01: begin // Sine wave tone
          sine_value <= sine_table[sine_index];
          tone <= volume_counter < dur ? sine_value : 0;
          tone_counter <= tone_counter + 1;
          if (tone_counter == 200000000 / FREQ_1) begin
            tone_counter <= 0;
            sine_index <= sine_index + (SINE_TABLE_SIZE * FREQ_1) / 200000000;
          end
        end
        2'b10: begin // Square wave tone
          square_value <= square_index < SQUARE_WAVE_PERIOD / 2 ? 1 : 0;
          tone <= volume_counter < dur ? square_value : 0;
          tone_counter <= tone_counter + 1;
          if (tone_counter == 200000000 / FREQ_1) begin
            tone_counter <= 0;
            square_index <= square_index + 1;
          end
        end
      endcase

      // Update duration counter
      duration_counter <= volume_counter < dur ? duration_counter + 1 : 0;

      // Update volume counter
      volume_counter <= volume_counter < (1 << (vol + 1)) - 1 ? volume_counter + 1 : 0;
    end
  end

endmodule

module fifo_301x128 (
    input [300:0] data,
    input rdclk,
    input rdreq,
    input wrclk,
    input wrreq,
    output [300:0] q,
    output rdempty,
    output wrempty,
    output wrfull,
    output [6:0] wrusedw
);

    reg [300:0] mem [0:127];
    reg [6:0] wrptr = 0;
    reg [6:0] rdptr = 0;
    reg [7:0] wrusedbits = 0;
    reg [7:0] rdusedbits = 0;
    reg [6:0] wraddr;
    reg [6:0] rdaddr;
    wire [6:0] next_wrptr;
    wire [6:0] next_rdptr;
    wire [7:0] next_wrusedbits;
    wire [7:0] next_rdusedbits;
    wire wr_en;
    wire rd_en;
    wire empty;
    wire full;
    wire [300:0] q_reg;

    assign next_wrptr = wrptr + 1;
    assign next_rdptr = rdptr + 1;
    assign next_wrusedbits = wrusedbits + 1;
    assign next_rdusedbits = rdusedbits + 1;

    assign wraddr = wrptr[6:0];
    assign rdaddr = rdptr[6:0];

    assign wr_en = wrreq && !wrfull;
    assign rd_en = rdreq && !rdempty;

    assign q = q_reg;
    assign rdempty = (wrptr == rdptr) && (wrusedbits == rdusedbits);
    assign wrempty = (wrptr == rdptr) && (wrusedbits == 0);
    assign wrfull = (wrptr == rdptr) && (wrusedbits == 128);

    always @(posedge wrclk) begin
        if (wr_en) begin
            mem[wrptr][wrusedbits +: 301 - wrusedbits] <= data;
            wrusedbits <= next_wrusedbits;
            if (wrusedbits == 128) begin
                wrptr <= next_wrptr;
                wrusedbits <= 0;
            end
        end
    end

    always @(posedge rdclk) begin
        if (rd_en) begin
            q_reg <= mem[rdptr][rdusedbits +: 301 - rdusedbits];
            rdusedbits <= next_rdusedbits;
            if (rdusedbits == 128) begin
                rdptr <= next_rdptr;
                rdusedbits <= 0;
            end
        end
    end

    assign empty = (wrptr == rdptr) && (wrusedbits == rdusedbits);
    assign full = (wrptr == rdptr) && (wrusedbits == 128);

    always @(posedge wrclk) begin
        if (wr_en && !empty) begin
            wrptr <= next_wrptr;
            wrusedbits <= 0;
        end
    end

    always @(posedge rdclk) begin
        if (rd_en && !full) begin
            rdptr <= next_rdptr;
            rdusedbits <= 0;
        end
    end

    assign wrusedw = wrusedbits;

endmodule

module system_ilmb_bram_if_cntlr_0(
  input LMB_Clk,
  input LMB_Rst,
  input [31:0] LMB_ABus,
  input [31:0] LMB_WriteDBus,
  input LMB_AddrStrobe,
  input LMB_ReadStrobe,
  input LMB_WriteStrobe,
  input [3:0] LMB_BE,
  output reg [31:0] Sl_DBus,
  output reg Sl_Ready,
  output reg Sl_Wait,
  output reg Sl_UE,
  output reg Sl_CE,
  output reg BRAM_Rst_A,
  output reg BRAM_Clk_A,
  output reg [31:0] BRAM_Addr_A,
  output reg BRAM_EN_A,
  output reg [3:0] BRAM_WEN_A,
  output reg [31:0] BRAM_Dout_A,
  input [31:0] BRAM_Din_A
);

  reg [31:0] bram_data [0:65535];
  reg [31:0] addr;
  reg [3:0] be;
  reg [31:0] write_data;
  reg read_data_valid;
  reg [31:0] read_data;

  always @(posedge LMB_Clk) begin
    if (LMB_Rst) begin
      Sl_Ready <= 0;
      Sl_Wait <= 0;
      Sl_UE <= 0;
      Sl_CE <= 0;
      BRAM_Rst_A <= 1;
      BRAM_Clk_A <= 0;
      BRAM_Addr_A <= 0;
      BRAM_EN_A <= 0;
      BRAM_WEN_A <= 0;
      BRAM_Dout_A <= 0;
    end else begin
      if (LMB_AddrStrobe) begin
        addr <= LMB_ABus;
        be <= LMB_BE;
      end
      if (LMB_WriteStrobe) begin
        write_data[be[0] ? 7:0] <= LMB_WriteDBus[7:0];
        write_data[be[1] ? 15:8] <= LMB_WriteDBus[15:8];
        write_data[be[2] ? 23:16] <= LMB_WriteDBus[23:16];
        write_data[be[3] ? 31:24] <= LMB_WriteDBus[31:24];
        Sl_Ready <= 0;
        Sl_Wait <= 1;
        Sl_UE <= 0;
        Sl_CE <= 1;
        BRAM_Rst_A <= 0;
        BRAM_Clk_A <= 0;
        BRAM_Addr_A <= addr;
        BRAM_EN_A <= 1;
        BRAM_WEN_A <= 1;
        BRAM_Dout_A <= 0;
        bram_data[addr] <= write_data;
      end else if (LMB_ReadStrobe) begin
        read_data <= bram_data[addr];
        Sl_Ready <= 1;
        Sl_Wait <= 0;
        Sl_UE <= 1;
        Sl_CE <= 1;
        BRAM_Rst_A <= 0;
        BRAM_Clk_A <= 1;
        BRAM_Addr_A <= addr;
        BRAM_EN_A <= 1;
        BRAM_WEN_A <= 0;
        BRAM_Dout_A <= read_data;
        read_data_valid <= 1;
      end else begin
        Sl_Ready <= 0;
        Sl_Wait <= 0;
        Sl_UE <= 0;
        Sl_CE <= 0;
        BRAM_Rst_A <= 0;
        BRAM_Clk_A <= 0;
        BRAM_Addr_A <= 0;
        BRAM_EN_A <= 0;
        BRAM_WEN_A <= 0;
        BRAM_Dout_A <= 0;
        read_data_valid <= 0;
      end
    end
  end

  always @(posedge BRAM_Clk_A) begin
    if (read_data_valid) begin
      Sl_DBus <= read_data;
      read_data_valid <= 0;
    end else begin
      Sl_DBus <= 0;
    end
  end

endmodule

