module FIFO_image_filter (
    clk,
    data,
    ce,
    a,
    q
);

parameter DATA_WIDTH = 12;
parameter ADDR_WIDTH = 2;
parameter DEPTH = 3;

input clk;
input [DATA_WIDTH-1:0] data;
input ce;
input [ADDR_WIDTH-1:0] a;
output [DATA_WIDTH-1:0] q;

reg [DATA_WIDTH-1:0] buffer [0:DEPTH-1];
integer i;

always @(posedge clk) begin
    if (ce) begin
        for (i = DEPTH-1; i > 0; i = i - 1) begin
            buffer[i] <= buffer[i-1];
        end
        buffer[0] <= data;
    end
end

assign q = buffer[a];

endmodule

module triple_des(desOut, desIn, key1, key2, key3, decrypt, clk);
output [63:0] desOut;
input [63:0] desIn;
input [55:0] key1;
input [55:0] key2;
input [55:0] key3;
input decrypt;
input clk;

wire [63:0] stage1_out, stage2_out;
reg [55:0] key_b_r[16:0];
reg [55:0] key_c_r[33:0];
integer i;

// generate key_b_r and key_c_r
always @(posedge clk) begin
    key_b_r[0] <= key2;
    for (i = 0; i < 16; i = i + 1) begin
        key_b_r[i+1] <= key_b_r[i];
    end
end

always @(posedge clk) begin
    key_c_r[0] <= key3;
    for (i = 0; i < 33; i = i + 1) begin
        key_c_r[i+1] <= key_c_r[i];
    end
end

// instantiate DES modules
des u0(.desOut(stage1_out), .desIn(desIn), .key(decrypt ? key3 : key1), .decrypt(decrypt), .clk(clk));
des u1(.desOut(stage2_out), .desIn(stage1_out), .key(key_b_r[16]), .decrypt(!decrypt), .clk(clk));
des u2(.desOut(desOut), .desIn(stage2_out), .key(key_c_r[33]), .decrypt(decrypt), .clk(clk));

endmodule

module top_module (
    input clk,              // Clock input
    input reset,            // Synchronous active-high reset
    input [7:0] data_in,    // 8-bit input data
    input [2:0] sel,        // 3-bit select input for choosing operation
    output [3:0] q          // 4-bit final output
);

    // Instantiate barrel shifter module
    barrel_shifter bs (
        .clk(clk),
        .reset(reset),
        .data_in(data_in),
        .shift_sel(sel[1:0]),
        .shift_amt({1'b0, sel[2], sel[2]}), // 1, 2, or no shift
        .shift_out(q_shifted)
    );

    // Instantiate decoder with enable module
    decoder_with_enable dwen (
        .data_in(data_in),
        .enable(sel[2]),
        .decode_out(q_decoded)
    );

    // Instantiate bitwise OR module
    bitwise_or bo (
        .a(q_shifted),
        .b(q_decoded),
        .or_out(q)
    );

    // Internal wires
    wire [3:0] q_shifted;
    wire [3:0] q_decoded;

endmodule

// Barrel shifter module
module barrel_shifter (
    input clk,              // Clock input
    input reset,            // Synchronous active-high reset
    input [7:0] data_in,    // 8-bit input data
    input [1:0] shift_sel,  // 2-bit select input for choosing shift direction
    input [2:0] shift_amt,  // 3-bit select input for choosing shift amount
    output [3:0] shift_out  // 4-bit shifted output
);

    reg [7:0] shift_reg;    // Shift register

    always @(posedge clk) begin
        if (reset) begin
            shift_reg <= 8'b0;
        end else begin
            case (shift_sel)
                2'b00: shift_reg <= shift_reg; // No shift
                2'b01: shift_reg <= {shift_reg[6:0], 1'b0}; // Shift left by 1
                2'b10: shift_reg <= {1'b0, shift_reg[7:1]}; // Shift right by 1
                2'b11: begin // Shift right by 2
                    shift_reg <= {2'b00, shift_reg[7:2]};
                end
            endcase

            if (shift_amt == 3'b000) begin
                shift_out <= shift_reg[3:0]; // No shift
            end else if (shift_amt == 3'b001) begin
                shift_out <= shift_reg[4:1]; // Shift left by 1
            end else if (shift_amt == 3'b010) begin
                shift_out <= shift_reg[2:5]; // Shift right by 1
            end else if (shift_amt == 3'b011) begin
                shift_out <= shift_reg[1:4]; // Shift right by 2
            end else begin
                shift_out <= 4'bxxxx; // Invalid shift amount
            end
        end
    end

endmodule

// Decoder with enable module
module decoder_with_enable (
    input [7:0] data_in,    // 8-bit input data
    input enable,            // Enable input
    output reg [3:0] decode_out  // 4-bit decoded output
);

    always @(data_in, enable) begin
        if (enable) begin
            case (data_in[7:6])
                2'b00: decode_out <= 4'b0000;
                2'b01: decode_out <= 4'b0001;
                2'b10: decode_out <= 4'b0010;
                2'b11: decode_out <= 4'b0011;
            endcase
        end else begin
            case (data_in[5:4])
                2'b00: decode_out <= 4'b0100;
                2'b01: decode_out <= 4'b0101;
                2'b10: decode_out <= 4'b0110;
                2'b11: decode_out <= 4'b0111;
            endcase
        end
    end

endmodule

// Bitwise OR module
