module Balsa_booth__mul8 (
  input activate_0r,
  input x_0a,
  output x_0r,
  output reg [7:0] x_0d,
  input y_0a,
  output y_0r,
  output reg [7:0] y_0d,
  output z_0a,
  input z_0r,
  output reg [7:0] z_0d
);

  reg [8:0] y_reg;
  reg [7:0] x_reg;
  reg [7:0] z_reg;
  reg [3:0] counter;

  always @(*) begin
    x_0r = x_0a;
    y_0r = y_0a;
    z_0d = z_reg;
    z_0a = 1;
  end

  always @(posedge z_0r) begin
    if (z_0r) begin
      z_reg <= z_0d;
    end
  end

  always @(posedge z_0r or posedge activate_0r) begin
    if (activate_0r && z_0r) begin
      x_reg <= x_0d;
      y_reg <= {1'b0, y_0d};
      counter <= 4;
    end
  end

  always @(posedge z_0r) begin
    if (counter > 0) begin
      if (y_reg[0] && !y_reg[1]) begin
        z_reg <= z_reg - x_reg;
      end else if (!y_reg[0] && y_reg[1]) begin
        z_reg <= z_reg + x_reg;
      end
      y_reg <= {y_reg[8], y_reg[7:1]};
      counter <= counter - 1;
    end
  end

  always @(posedge z_0r) begin
    if (counter == 0) begin
      z_0d <= z_reg;
    end
  end

endmodule

