module design_1_rst_ps7_0_50M_0_proc_sys_reset
    (slowest_sync_clk,
    ext_reset_in,
    aux_reset_in,
    mb_debug_sys_rst,
    dcm_locked,
    mb_reset,
    bus_struct_reset,
    peripheral_reset,
    interconnect_aresetn,
    peripheral_aresetn);

    input slowest_sync_clk;
    input ext_reset_in;
    input aux_reset_in;
    input mb_debug_sys_rst;
    input dcm_locked;
    output mb_reset;
    output [0:0] bus_struct_reset;
    output [0:0] peripheral_reset;
    output [0:0] interconnect_aresetn;
    output [0:0] peripheral_aresetn;

    wire [3:0] ext_reset_in_delay;
    wire [3:0] mb_debug_sys_rst_delay;
    wire [3:0] aux_reset_in_delay;
    wire [3:0] dcm_locked_delay;

    assign ext_reset_in_delay[3] = ext_reset_in;
    assign mb_debug_sys_rst_delay[3] = mb_debug_sys_rst;
    assign aux_reset_in_delay[3] = ~aux_reset_in;
    assign dcm_locked_delay[3] = dcm_locked;

    // Delay external reset signal
    genvar i;
    generate
        for (i = 2; i >= 0; i = i - 1) begin : ext_reset_in_delay_gen
            assign ext_reset_in_delay[i] = ext_reset_in_delay[i+1];
        end
    endgenerate

    // Delay debug system reset signal
    generate
        for (i = 2; i >= 0; i = i - 1) begin : mb_debug_sys_rst_delay_gen
            assign mb_debug_sys_rst_delay[i] = mb_debug_sys_rst_delay[i+1];
        end
    endgenerate

    // Delay auxiliary reset signal
    generate
        for (i = 2; i >= 0; i = i - 1) begin : aux_reset_in_delay_gen
            assign aux_reset_in_delay[i] = aux_reset_in_delay[i+1];
        end
    endgenerate

    // Delay DCM locked signal
    generate
        for (i = 2; i >= 0; i = i - 1) begin : dcm_locked_delay_gen
            assign dcm_locked_delay[i] = dcm_locked_delay[i+1];
        end
    endgenerate

    // Generate reset signals
    assign mb_reset = (ext_reset_in_delay[3] && mb_debug_sys_rst_delay[3] && dcm_locked_delay[3]);
    assign bus_struct_reset[0] = (ext_reset_in_delay[3] || mb_debug_sys_rst_delay[3] || aux_reset_in_delay[3]);
    assign peripheral_reset[0] = (ext_reset_in_delay[3] || mb_debug_sys_rst_delay[3] || aux_reset_in_delay[3]);
    assign interconnect_aresetn[0] = ~(ext_reset_in_delay[3] || mb_debug_sys_rst_delay[3] || aux_reset_in_delay[3]);
    assign peripheral_aresetn[0] = ~(ext_reset_in_delay[3] || mb_debug_sys_rst_delay[3] || aux_reset_in_delay[3]);

endmodule

module edge_detection (
