    input reset,
    input [7:0] in,
    output reg [7:0] out
);

reg [7:0] prev;
reg [7:0] xor_out;

always @(posedge clk) begin
    if (reset) begin
        prev <= 8'b0;
        out <= 4'b0;
    end else begin
        xor_out <= in ^ prev;
        prev <= in;
        out <= xor_out;
    end
end

