module top_module ( 
    input wire [3:0] vec1,
    input wire [3:0] vec2,
    output wire [3:0] out_xor,
    output wire o4,
    output wire o3,
    output wire o2,
    output wire o1,
    output wire o0  );

    // Pipeline registers
    reg [3:0] stage1_out;
    reg [3:0] stage2_out;
    reg [3:0] stage3_out;
    reg [3:0] stage4_out;

    // Stage 1
    always @ (vec1, vec2) begin
        stage1_out <= vec1 ^ vec2;
    end

    // Stage 2
    always @ (stage1_out) begin
        stage2_out <= stage1_out;
    end

    // Stage 3
    always @ (stage2_out) begin
        stage3_out <= stage2_out;
    end

    // Stage 4
    always @ (stage3_out) begin
        stage4_out <= stage3_out;
    end

    // Output assignments
    assign out_xor = stage4_out;
    assign o4 = stage4_out[3];
    assign o3 = stage4_out[2];
    assign o2 = stage4_out[1];
    assign o1 = stage4_out[0];
    assign o0 = vec1 & vec2;

endmodule

module top_module (
    input [3:0] A,
    input [3:0] B,
    input [3:0] D,
    input SEL,
    input LD,
    input SR,
    input SL,
    output [7:0] P
);

    // 4-bit multiplier using Booth's algorithm
    wire [7:0] product;
    booth_multiplier_4bit multiplier(
        .A(A),
        .B(B),
        .product(product)
    );

    // 4-bit shift register with parallel load
    reg [3:0] Q;
    always @(posedge SR, negedge SL) begin
        if (SR) begin
            Q <= {1'b0, Q[3:1]};
        end else if (SL) begin
            Q <= {Q[2:0], 1'b0};
        end
    end

    // Load Q with D when LD is asserted
    always @(posedge LD) begin
        Q <= D;
    end

    // Output P based on SEL
    always @(*) begin
        if (SEL) begin
            P = {product[6:0], Q[0]};
        end else begin
            P = {Q[3], product[7:1]};
        end
    end

endmodule

module edge_detector (
  input in,
  input clk,
  output re,
  output fe
);

  reg prev_in;

  always @(posedge clk) begin
    if (in && !prev_in) begin
      re <= 1;
    end else begin
      re <= 0;
    end

    if (!in && prev_in) begin
      fe <= 1;
    end else begin
      fe <= 0;
    end

    prev_in <= in;
  end

endmodule

