module uart_wishbone_interface (
    // Inputs
    input clk_sys_i,
    input reset_sys_i,
    input uart_rx,
    input wb_clk_i,
    input wb_rst_i,
    input [31:0] wb_adr_i,
    input [31:0] wb_dat_i,
    input [3:0] wb_sel_i,
    input wb_we_i,
    input wb_stb_i,
    // Outputs
    output reg uart_tx,
    output [31:0] wb_dat_o,
    output wb_ack_o,
    output wb_err_o
);

// System Interface
input clk_sys_i;
input reset_sys_i;

// UART Interface
input uart_rx;
output reg uart_tx;

// Wishbone Interface
input wb_clk_i;
input wb_rst_i;
input [31:0] wb_adr_i;
input [31:0] wb_dat_i;
input [3:0] wb_sel_i;
input wb_we_i;
input wb_stb_i;
output [31:0] wb_dat_o;
output wb_ack_o;
output wb_err_o;

// Internal signals
reg [31:0] sram [32767:0];
reg [31:0] rom [32767:0];
reg [31:0] wb_dat_out;
reg [3:0] uart_state;
reg [31:0] uart_data;
reg uart_data_valid;
reg [31:0] uart_baud_rate;
reg uart_interrupt;

// Constants
localparam UART_IDLE = 4'b0000;
localparam UART_START = 4'b0001;
localparam UART_DATA = 4'b0010;
localparam UART_PARITY = 4'b0011;
localparam UART_STOP = 4'b0100;

// Initialize internal signals
initial begin
    uart_state = UART_IDLE;
    uart_data_valid = 0;
    uart_baud_rate = 115200;
end

// System SRAM
always @(posedge wb_clk_i) begin
    if (wb_rst_i) begin
        sram <= 'hx;
    end else if (wb_stb_i && wb_we_i) begin
        sram[wb_adr_i[14:0]] <= wb_dat_i;
    end
end

// System ROM
always @(posedge wb_clk_i) begin
    if (wb_rst_i) begin
        rom <= 'hx;
    end else if (wb_stb_i && !wb_we_i) begin
        wb_dat_out <= rom[wb_adr_i[14:0]];
    end
end

// UART
always @(posedge clk_sys_i) begin
    if (uart_data_valid) begin
        case (uart_state)
            UART_IDLE: begin
                if (!uart_rx) begin
                    uart_state <= UART_START;
                end
            end
            UART_START: begin
                uart_data <= 0;
                uart_state <= UART_DATA;
            end
            UART_DATA: begin
                uart_data <= {uart_data[30:0], uart_rx};
                if (uart_baud_rate == 115200) begin
                    #8;
                end else if (uart_baud_rate == 57600) begin
                    #16;
                end else if (uart_baud_rate == 38400) begin
                    #24;
                end else if (uart_baud_rate == 19200) begin
                    #48;
                end else if (uart_baud_rate == 9600) begin
                    #96;
                end
                uart_state <= UART_PARITY;
            end
            UART_PARITY: begin
                uart_state <= UART_STOP;
            end
            UART_STOP: begin
                uart_data_valid <= 0;
                uart_state <= UART_IDLE;
                sram[wb_adr_i[14:0]] <= uart_data;
            end
        endcase
    end else begin
        if (uart_rx == 0) begin
            uart_data_valid <= 1;
        end
    end
end

// UART transmit
always @(posedge clk_sys_i) begin
    if (uart_interrupt) begin
        uart_tx <= wb_dat_i[0];
    end else begin
        uart_tx <= 1;
    end
end

// Wishbone
always @(posedge wb_clk_i) begin
    if (wb_rst_i) begin
        wb_dat_out <= 'hx;
        wb_ack_o <= 0;
        wb_err_o <= 0;
    end else if (wb_stb_i && !wb_we_i) begin
        case (wb_adr_i[16:15])
            2'b00: begin // SRAM
                wb_dat_out <= sram[wb_adr_i[14:0]];
            end
            2'b01: begin // ROM
                wb_dat_out <= rom[wb_adr_i[14:0]];
            end
            2'b10: begin // UART
                case (wb_adr_i[4:0])
                    5'h00: begin // Data
                        if (wb_we_i) begin
                            uart_data <= wb_dat_i;
                        end else begin
                            wb_dat_out <= uart_data;
                        end
                    end
                    5'h01: begin // Status
                        wb_dat_out <= {uart_data_valid, 0, 0, 0};
                    end
                    5'h02: begin // Control
                        if (wb_we_i) begin
                            case (wb_dat_i[1:0])
                                2'b00: begin // Baud Rate
                                    uart_baud_rate <= wb_dat_i[31:0];
                                end
                                2'b01: begin // Interrupt Enable
                                    if (wb_dat_i[0]) begin
                                        uart_interrupt <= 1;
                                    end else begin
                                        uart_interrupt <= 0;
                                    end
                                end
                                2'b10: begin // Reset
                                    uart_state <= UART_IDLE;
                                    uart_data_valid <= 0;
                                end
                            endcase
                        end else begin
                            wb_dat_out <= {0, uart_interrupt, 0, 0};
                        end
                    end
                endcase
            end
        endcase
        wb_ack_o <= 1;
    end else if (wb_stb_i && wb_we_i) begin
        case (wb_adr_i[16:15])
            2'b00: begin // SRAM
                sram[wb_adr_i[14:0]] <= wb_dat_i;
            end
            2'b01: begin // ROM
                // ROM is read-only
                wb_err_o <= 1;
            end
            2'b10: begin // UART
                // UART is read-only
                wb_err_o <= 1;
            end
        endcase
        wb_ack_o <= 1;
    end
end

endmodule

module bin2dec (
    A,
    B,
    C,
    D,
    Y0,
    Y1,
    Y2,
    Y3
);

    input [3:0] A, B, C, D;
    output [3:0] Y0, Y1, Y2, Y3;

    wire w1, w2, w3, w4, w5, w6, w7, w8, w9, w10, w11, w12, w13, w14, w15;

    // Implementing the truth table
    assign w1 = ~A & ~B & ~C & ~D;
    assign w2 = ~A & ~B & ~C & D;
    assign w3 = ~A & ~B & C & ~D;
    assign w4 = ~A & ~B & C & D;
    assign w5 = ~A & B & ~C & ~D;
    assign w6 = ~A & B & ~C & D;
    assign w7 = ~A & B & C & ~D;
    assign w8 = ~A & B & C & D;
    assign w9 = A & ~B & ~C & ~D;
    assign w10 = A & ~B & ~C & D;
    assign w11 = A & ~B & C & ~D;
    assign w12 = A & ~B & C & D;
    assign w13 = A & B & ~C & ~D;
    assign w14 = A & B & ~C & D;
    assign w15 = A & B & C & ~D;

    // Assigning outputs
    assign Y0 = w1 | w2 | w3 | w4 | w5 | w6 | w7 | w8;
    assign Y1 = w5 | w6 | w7 | w8 | w9 | w10 | w11 | w12;
    assign Y2 = w3 | w4 | w7 | w8 | w11 | w12 | w13 | w14;
    assign Y3 = w2 | w4 | w6 | w8 | w10 | w12 | w14 | w15;

endmodule

