module binary_op #( 
  parameter in0N = 8, 
  parameter in1N = 8, 
  parameter out0N = 8, 
  parameter opSel = 0
)(
  input [in0N-1:0] in0,
  input [in1N-1:0] in1,
  output [out0N-1:0] out0
);

  always @ (*) begin
    case (opSel)
      0: out0 = in0 & in1;
      1: out0 = in0 | in1;
      2: out0 = in0 ^ in1;
      3: out0 = ~(in0 ^ in1);
      4: out0 = in0 + in1;
      5: out0 = in0 - in1;
      6: out0 = in0 * in1;
      7: out0 = in0 / in1;
      default: out0 = 0;
    endcase
  end

