module communication_system(
    input clk, // clock input
    input sync_reset, // reset input
    input rxd, // input data
    output int_req, // interrupt request output
    output reg[7:0] buffer_reg // output data
);

	reg rxq1;
	reg[8:0] clk_ctr;
	reg[2:0] bit_ctr;
	reg[2:0] ua_state;
	reg[7:0] rx_sr;
	reg int_req;

	wire clk_ctr_equ15, clk_ctr_equ31, bit_ctr_equ7, clk_ctr_enable_state, bit_ctr_enable_state, clk_ctr_equ0;

	// Synchronize input data to the clock
	always @(posedge clk) begin
		rxq1 <= rxd;
	end

	// Count clock cycles using a 9-bit counter
	always @(posedge clk) begin
		if (sync_reset) clk_ctr <= 0;
		else if (clk_ctr_enable_state && clk_ctr_equ31) clk_ctr <= 0;
		else if (clk_ctr_enable_state) clk_ctr <= clk_ctr + 1;
		else clk_ctr <= 0;
	end

	assign clk_ctr_equ15 = (clk_ctr == 15'd5208);
	assign clk_ctr_equ31 = (clk_ctr == 15'd10416);
	assign clk_ctr_equ0 = (clk_ctr == 0);

	// Count bits using a 3-bit counter
	always @(posedge clk) begin
		if (sync_reset) bit_ctr <= 0;
		else if (bit_ctr_enable_state) begin
			if (clk_ctr_equ15) bit_ctr <= bit_ctr + 1;
		end
		else bit_ctr <= 0;
	end

	assign bit_ctr_equ7 = (bit_ctr == 3'd7);

	assign clk_ctr_enable_state = ua_state != 3'b000 && ua_state <= 3'b011;
	assign bit_ctr_enable_state = ua_state == 3'h2;

	// Update the module state based on the input data and clock cycles
	always @(posedge clk) begin
		if (sync_reset) ua_state <= 3'h0;
		else begin
			case (ua_state)
				3'h0: if (rxq1 == 0) ua_state <= 3'h1;
				3'h1: if (clk_ctr_equ15) ua_state <= 3'h2;
				3'h2: if (bit_ctr_equ7 && clk_ctr_equ15) ua_state <= 3'h3;
				3'h3: if (clk_ctr_equ15) ua_state <= 3'h4;
				3'h4: ua_state <= 3'b000;
				default: ua_state <= 3'b000;
			endcase
		end
	end

	// Store received data in an 8-bit shift register
	always @(posedge clk) begin
		if (sync_reset) rx_sr <= 0;
		else if (clk_ctr_equ15) rx_sr <= {rxq1, rx_sr[7:1]};
	end

	// Update the buffer register when data is ready to be transmitted
	always @(posedge clk) begin
		if (sync_reset) buffer_reg <= 8'h00;
		else if (ua_state == 3'h3 && clk_ctr_equ0) buffer_reg <= rx_sr;
	end

	// Set the interrupt request flag when transmission is complete
	always @(posedge clk) begin
		if (sync_reset) int_req <= 1'b0;
