module calculator(
    input [7:0] A,
    input [7:0] B,
    input [1:0] op,
    input start,
    output done,
    output [7:0] result
);

reg [15:0] temp;
reg [7:0] temp_result;
reg [7:0] quotient;
reg [7:0] remainder;
reg [1:0] state;

assign done = (state == 2'b11);

always @(posedge start) begin
    case(op)
        2'b00: begin // addition
            temp = A + B;
            if(temp > 8'hFF) begin
                temp_result = temp - 8'h100;
            end else begin
                temp_result = temp;
            end
            state <= 2'b11;
        end
        2'b01: begin // subtraction
            temp = A - B;
            if(temp < 0) begin
                temp_result = temp + 8'h100;
            end else begin
                temp_result = temp;
            end
            state <= 2'b11;
        end
        2'b10: begin // multiplication
            temp = A * B;
            temp_result = temp[7:0];
            state <= 2'b11;
        end
        2'b11: begin // division
            quotient = 8'h00;
            remainder = A;
            if(B == 8'h00) begin
                temp_result = 8'hFF;
                state <= 2'b00;
            end else begin
                state <= 2'b01;
            end
        end
    endcase
end

always @(posedge start) begin
    case(state)
        2'b00: begin // idle
            result <= 8'h00;
        end
        2'b01: begin // division - subtract
            if(remainder >= B) begin
                remainder = remainder - B;
                quotient = quotient + 1;
            end else begin
                state <= 2'b10;
            end
        end
        2'b10: begin // division - output quotient
            temp_result = quotient;
            state <= 2'b11;
        end
        2'b11: begin // output result
            result <= temp_result;
            state <= 2'b00;
        end
    endcase
end

endmodule

