module MD5 (
  input [n-1:0] in,
  output reg [127:0] hash
);

parameter n = 512; // length of input message in bits

// Define the four rounds of processing and the 16 operations in each round
function [31:0] F; input [31:0] x, y, z; F = ((x & y) | (~x & z)); endfunction
function [31:0] G; input [31:0] x, y, z; G = ((x & z) | (y & ~z)); endfunction
function [31:0] H; input [31:0] x, y, z; H = (x ^ y ^ z); endfunction
function [31:0] I; input [31:0] x, y, z; I = (y ^ (x | ~z)); endfunction

function [31:0] rotate_left; input [31:0] x; input [4:0] n;
  rotate_left = (x << n) | (x >> (32-n));
endfunction

reg [31:0] a, b, c, d, temp;
integer i;

initial begin
  // Initialize variables
  a = 32'h67452301;
  b = 32'hEFCDAB89;
  c = 32'h98BADCFE;
  d = 32'h10325476;

  // Process input message in 512-bit chunks
  for (i = 0; i < n; i = i + 512) begin
    // Define 16 operations for each round
    a = b + rotate_left(a + F(b, c, d) + in[i+ 0],  7);
    d = a + rotate_left(d + F(a, b, c) + in[i+ 1], 12);
    c = d + rotate_left(c + F(d, a, b) + in[i+ 2], 17);
    b = c + rotate_left(b + F(c, d, a) + in[i+ 3], 22);
    // ... repeat for all 64 operations

    // Update hash value
    a = a + a;
    b = b + b;
    c = c + c;
    d = d + d;
  end

  // Combine variables to form 128-bit hash value
  hash = {a, b, c, d};
end

endmodule

