module async_reset_release (
  input reset,
  input clk,
  output rst
);

  reg [3:0] counter;
  reg rst_active;

  always @(posedge clk or negedge reset) begin
    if (!reset) begin
      counter <= 0;
      rst_active <= 1'b1;
    end else begin
      if (counter == 4'd10) begin
        rst_active <= 1'b0;
      end else begin
        counter <= counter + 1;
      end
    end
  end

  assign rst = rst_active;

endmodule

module top_module (
    input A, 
    input B, 
    input C, 
    input EN1, 
    input EN2, 
    input select, 
    output reg [1:0] out
); 

reg [3:0] Y1;
reg [7:0] Y2;

decoder1 decoder1_inst (
    .A(A),
    .B(B),
    .EN(EN1),
    .Y(Y1)
);

decoder2 decoder2_inst (
    .A(A),
    .B(B),
    .C(C),
    .EN(EN2),
    .Y0(Y2[0]),
    .Y1(Y2[1]),
    .Y2(Y2[2]),
    .Y3(Y2[3]),
    .Y4(Y2[4]),
    .Y5(Y2[5]),
    .Y6(Y2[6]),
    .Y7(Y2[7])
);

functional_module functional_module_inst (
    .Y1(Y1),
    .Y2(Y2),
    .select(select),
    .out(out)
);

