module decoder1 (
    input A, 
    input B, 
    input EN, 
    output reg [3:0] Y
); 

always @ (A, B, EN) begin
    if (EN) begin
        case ({A, B})
            2'b00: Y = 4'b0001;
            2'b01: Y = 4'b0010;
            2'b10: Y = 4'b0100;
            2'b11: Y = 4'b1000;
        endcase
    end else begin
        Y = 4'b0000;
    end
end

endmodule

module decoder2 (
    input A, 
    input B, 
    input C, 
    input EN, 
    output reg Y0, Y1, Y2, Y3, Y4, Y5, Y6, Y7
); 

always @ (A, B, C, EN) begin
    if (EN) begin
        case ({A, B, C})
            3'b000: Y0 = 1'b1;
            3'b001: Y1 = 1'b1;
            3'b010: Y2 = 1'b1;
            3'b011: Y3 = 1'b1;
            3'b100: Y4 = 1'b1;
            3'b101: Y5 = 1'b1;
            3'b110: Y6 = 1'b1;
            3'b111: Y7 = 1'b1;
        endcase
    end else begin
        Y0 = 1'b0;
        Y1 = 1'b0;
        Y2 = 1'b0;
        Y3 = 1'b0;
        Y4 = 1'b0;
        Y5 = 1'b0;
        Y6 = 1'b0;
        Y7 = 1'b0;
    end
end

endmodule

module functional_module (
    input [3:0] Y1, 
    input [7:0] Y2, 
    input [1:0] select, 
    output reg [1:0] out
); 

always @ (select, Y1, Y2) begin
    case (select)
        2'b00: out = Y2[0:1];
        2'b01: out = Y2[2:3];
        2'b10: out = Y2[4:5];
        2'b11: out = Y2[6:7];
    endcase
    case (Y1)
        4'b0001: out = 2'b00;
        4'b0010: out = 2'b01;
        4'b0100: out = 2'b10;
        4'b1000: out = 2'b11;
    endcase
end

endmodule

module johnson_counter (
  input clk,
  output [n-1:0] out
);

parameter n = 4; // number of output signals

reg [n-1:0] state;
wire [n-1:0] next_state;

assign out = state;

always @ (posedge clk) begin
  state <= next_state;
end

assign next_state[0] = state[n-1];
generate
  genvar i;
  for (i = 1; i < n; i = i + 1) begin : loop
    assign next_state[i] = state[i-1] ^ state[n-1];
  end
endgenerate

endmodule

module calculator (
    input [7:0] a,
    input [7:0] b,
    input [1:0] op,
    input [3:0] sel,
    output reg [7:0] out,
    output reg overflow
);

reg [7:0] a_mag, b_mag, result;
reg [1:0] op_sel;
wire [7:0] add_result;

// Convert a and b to sign-magnitude format
assign a_mag = (a[7] == 1) ? {1'b0, ~a[7:0] + 1} : a;
assign b_mag = (b[7] == 1) ? {1'b0, ~b[7:0] + 1} : b;

// Select operation based on op input
always @ (op, sel, result) begin
    case (sel)
        2'b00: op_sel = op; // Output result of selected operation
        2'b01: op_sel = 2'b00; // Addition
        2'b10: op_sel = 2'b01; // Subtraction
        2'b11: op_sel = 2'b10; // Multiplication
        default: op_sel = 2'b11; // Division
    endcase
end

// Perform selected operation using 8-bit adder
always @ (a_mag, b_mag, op_sel) begin
    case (op_sel)
        2'b00: add_result = a_mag + b_mag; // Addition
        2'b01: add_result = a_mag - b_mag; // Subtraction
        2'b10: add_result = a_mag * b_mag; // Multiplication
        2'b11: add_result = a_mag / b_mag; // Division
    endcase
end

// Check for signed overflow
always @ (add_result) begin
    if (add_result[7] != add_result[6]) begin
        overflow = 1;
    end else begin
        overflow = 0;
    end
end

// Output result of selected operation or previous operation
always @ (op_sel, add_result) begin
    if (sel < 4) begin
        out = add_result;
        result = add_result;
    end else begin
        out = result;
    end
end

endmodule

module calculator(
  input [7:0] operand1,
  input [7:0] operand2,
  input [3:0] op_code,
  output reg [7:0] result
);

  always @(*) begin
    case(op_code)
      4'b0000: result = operand1 + operand2; // addition
      4'b0001: result = operand1 - operand2; // subtraction
      4'b0010: result = operand1 * operand2; // multiplication
      4'b0011: result = operand1 / operand2; // division
      default: result = 8'd0; // default to 0 if invalid op code
    endcase

    // check if operands are signed or unsigned and adjust result accordingly
    if ($signed(operand1) && $signed(operand2)) begin
      // signed operands
      if (op_code == 4'b0000 || op_code == 4'b0001) begin
        // addition or subtraction
        if (result[7] == 1) begin
          // overflow, set to max negative value
          result = -128;
        end
      end
    end else begin
      // unsigned operands
      if (result[7] == 1) begin
        // overflow, set to max unsigned value
        result = 255;
      end
    end
  end

endmodule

module calculator_tb;

  reg [7:0] operand1;
  reg [7:0] operand2;
  reg [3:0] op_code;
  wire [7:0] result;

  calculator calc(.operand1(operand1), .operand2(operand2), .op_code(op_code), .result(result));

  initial begin
    // test addition with unsigned operands
    operand1 = 8'd10;
    operand2 = 8'd20;
    op_code = 4'b0000;
    #10;
    if (result !== 30) $display("Test failed: 10 + 20 = %d", result);
    else $display("Test passed: 10 + 20 = %d", result);

    // test subtraction with signed operands
    operand1 = -128;
    operand2 = -1;
    op_code = 4'b0001;
    #10;
    if (result !== -127) $display("Test failed: -128 - (-1) = %d", result);
    else $display("Test passed: -128 - (-1) = %d", result);

    // test multiplication with unsigned operands
    operand1 = 8'd5;
    operand2 = 8'd3;
    op_code = 4'b0010;
    #10;
    if (result !== 15) $display("Test failed: 5 * 3 = %d", result);
    else $display("Test passed: 5 * 3 = %d", result);

    // test division with signed operands
    operand1 = -50;
    operand2 = 8'd5;
    op_code = 4'b0011;
    #10;
    if (result !== -10) $display("Test failed: -50 / 5 = %d", result);
    else $display("Test passed: -50 / 5 = %d", result);
  end

endmodule

module top_module( 
    input [15:0] in,
    input [2:0] sel,
    output [7:0] out );

    wire [1:0] mux0_out, mux1_out, mux2_out, mux3_out;
    wire [7:0] adder_out;

    // 2-to-1 multiplexers
    mux2to1 mux0(.in0(in[1:0]), .in1(in[3:2]), .sel(sel[1]), .out(mux0_out));
    mux2to1 mux1(.in0(in[5:4]), .in1(in[7:6]), .sel(sel[1]), .out(mux1_out));
    mux2to1 mux2(.in0(in[9:8]), .in1(in[11:10]), .sel(sel[1]), .out(mux2_out));
    mux2to1 mux3(.in0(in[13:12]), .in1(in[15:14]), .sel(sel[1]), .out(mux3_out));

    // Additive functional module
    adder add(.in0(mux0_out), .in1(mux1_out), .in2(mux2_out), .in3(mux3_out), .out(adder_out));

    // Output
    assign out = adder_out;

endmodule

// 2-to-1 multiplexer module
module mux2to1(
    input [1:0] in0,
    input [1:0] in1,
    input sel,
    output [1:0] out
    );

    assign out = (sel == 0) ? in0 : in1;

endmodule

// Additive functional module
module add(
    input [1:0] in0,
    input [1:0] in1,
    input [1:0] in2,
    input [1:0] in3,
    output [7:0] out
    );

    assign out = {4'b0, in3, in2, in1, in0} + 8'b0;

endmodule

module elevator_controller (
    input [3:0] floor_num,
    input [1:0] direction,
    output reg [2:0] floor_select
);

    // Priority Encoder
    wire [2:0] priority_enc;
    assign priority_enc = ~(floor_num - 1);

    // Binary-to-Gray Code Converter
    wire [2:0] gray_code;
    assign gray_code[2] = priority_enc[2];
    assign gray_code[1] = priority_enc[2] ^ priority_enc[1];
    assign gray_code[0] = priority_enc[1] ^ priority_enc[0];

    // Binary-to-Decimal Decoder
    always @* begin
        case (gray_code)
            3'b000: floor_select = 3'b000;
            3'b001: floor_select = (direction == 2'b00) ? 3'b001 : 3'b000;
            3'b010: floor_select = (direction == 2'b00) ? 3'b010 : 3'b001;
            3'b011: floor_select = (direction == 2'b00) ? 3'b011 : 3'b010;
            3'b100: floor_select = (direction == 2'b10) ? 3'b100 : 3'b011;
            3'b101: floor_select = (direction == 2'b10) ? 3'b101 : 3'b100;
            3'b110: floor_select = (direction == 2'b10) ? 3'b110 : 3'b101;
            3'b111: floor_select = 3'b111;
        endcase
    end

endmodule

module Clock50MHz (
    input CLK_IN1,
    input COUNTER_RESET,
    output reg CLK_OUT,
    output reg LOCKED
);

    // Constants
    localparam PER_IN1 = 10; // 10ns
    localparam PER_OUT = 20; // 20ns
    localparam TCQ = 0.1; // 100ps
    localparam PHASE_ERR_MARGIN = 0.1; // 100ps
    localparam COUNT_PHASE = 1024;

    // Internal signals
    reg [31:0] counter;
    reg [31:0] phase_counter;
    reg [31:0] phase_err_counter;
    reg locked_prev;
    reg locked_curr;
    reg locked_next;

    // Clock generation
    always @(posedge CLK_IN1) begin
        counter <= counter + 1;
        if (COUNTER_RESET) begin
            counter <= 0;
            CLK_OUT <= 0;
            phase_counter <= 0;
            phase_err_counter <= 0;
            locked_prev <= 0;
            locked_curr <= 0;
            locked_next <= 0;
        end else begin
            if (counter == (PER_IN1 / 2) - TCQ) begin
                CLK_OUT <= 1;
            end else if (counter == (PER_IN1 / 2) + TCQ) begin
                CLK_OUT <= 0;
            end
            if (counter == PER_IN1 - 1) begin
                counter <= 0;
            end
        end
    end

    // Lock detection
    always @(posedge CLK_OUT) begin
        phase_counter <= phase_counter + 1;
        if (phase_counter == (PER_OUT / 2)) begin
            phase_err_counter <= 0;
        end else if (phase_counter == PER_OUT) begin
            phase_counter <= 0;
            if (phase_err_counter <= PHASE_ERR_MARGIN) begin
                locked_prev <= locked_curr;
                locked_curr <= locked_next;
                locked_next <= 1;
            end else begin
                locked_prev <= locked_curr;
                locked_curr <= locked_next;
                locked_next <= 0;
            end
        end
        if (locked_prev && locked_curr && locked_next) begin
            LOCKED <= 1;
        end else begin
            LOCKED <= 0;
        end
        if (LOCKED) begin
            phase_err_counter <= phase_err_counter + 1;
        end
    end

endmodule

module RAM_block_with_parity_checking
   (douta,
    clka,
    addra,
    dina,
    wea,
    parity_error);
  output [35:0]douta;
  output parity_error;
  input clka;
  input [9:0]addra;
  input [35:0]dina;
  input wea;

  wire [9:0]addra;
  wire clka;
  wire [35:0]douta;
  wire [35:0]data_with_parity;
  wire parity_error;
  wire [9:0]parity_bits;
  wire [35:0]corrected_data;

  // Calculate parity bits for each 8-bit chunk of the data input
  assign parity_bits[0] = ^(dina[7:0]);
  assign parity_bits[1] = ^(dina[15:8]);
  assign parity_bits[2] = ^(dina[23:16]);
  assign parity_bits[3] = ^(dina[31:24]);
  assign parity_bits[4] = ^(dina[35:32]);
  assign data_with_parity = {dina[35:32], dina[31:24]^parity_bits[3], dina[23:16]^parity_bits[2], dina[15:8]^parity_bits[1], dina[7:0]^parity_bits[0]};

  // Instantiate the RAM block module
  RAM_block
    ram_block_inst
       (.douta(douta),
        .clka(clka),
        .addra(addra),
        .dina(data_with_parity),
        .wea(wea),
        .parity_error(parity_error));

  // Calculate parity bits for each 8-bit chunk of the data output and correct any errors
  assign parity_bits[0] = ^(douta[7:0]);
  assign parity_bits[1] = ^(douta[15:8]);
  assign parity_bits[2] = ^(douta[23:16]);
  assign parity_bits[3] = ^(douta[31:24]);
  assign parity_bits[4] = ^(douta[35:32]);
  assign corrected_data = {douta[35:32], (parity_bits[3] == ^(douta[31:24])) ? douta[31:24] : ~douta[31:24], (parity_bits[2] == ^(douta[23:16])) ? douta[23:16] : ~douta[23:16], (parity_bits[1] == ^(douta[15:8])) ? douta[15:8] : ~douta[15:8], (parity_bits[0] == ^(douta[7:0])) ? douta[7:0] : ~douta[7:0]};

endmodule

module RAM_block
   (douta,
    clka,
    addra,
    dina,
    wea,
    parity_error);
  output [35:0]douta;
  output parity_error;
  input clka;
  input [9:0]addra;
  input [35:0]dina;
  input wea;

  wire [9:0]addra;
  wire clka;
  wire [35:0]douta;
  wire [35:0]ram_array [1023:0];
  wire parity_error;

  // Write to the RAM array
  assign ram_array[addra] = wea ? dina : ram_array[addra];

  // Read from the RAM array
  assign douta = ram_array[addra];

  // Check parity bits for each 8-bit chunk of the data output and set parity_error if there is an error
  assign parity_error = ^(douta[7:0]) ^ ^(douta[15:8]) ^ ^(douta[23:16]) ^ ^(douta[31:24]) ^ ^(douta[35:32]);

endmodule

module clock_generator (
  input clk_enable,
  input [31:0] frequency,
  input [7:0] duty_cycle,
  output reg clk_out
);

  reg [31:0] counter;
  reg [31:0] half_period;
  reg [31:0] toggle_count;
  reg toggle;

  always @ (posedge clk_out or negedge clk_enable) begin
    if (~clk_enable) begin
      clk_out <= 1'b0;
      counter <= 32'd0;
      toggle_count <= 32'd0;
      toggle <= 1'b0;
    end else begin
      if (toggle_count == half_period) begin
        toggle_count <= 32'd0;
        toggle <= ~toggle;
      end else begin
        toggle_count <= toggle_count + 1;
      end
      if (counter == frequency) begin
        counter <= 32'd0;
        clk_out <= toggle;
      end else begin
        counter <= counter + 1;
      end
    end
  end

  always @ (posedge clk_out or posedge frequency or posedge duty_cycle) begin
    half_period <= (frequency * duty_cycle) / 200;
  end

endmodule

module top_module (
    input clk,
    input reset,
    input [1:0] d,
    input [99:0] in,
    output out_and,
    output out_or,
    output out_xor
);

    reg [1:0] shift_reg;
    reg [2:0] mux_sel;
    wire [1:0] shift_reg_out;
    wire [99:0] in_sel;
    wire and_out, or_out, xor_out;

    // Shift register
    always @(posedge clk or negedge reset) begin
        if (reset == 0) begin
            shift_reg <= 2'b0;
        end else begin
            shift_reg <= {shift_reg[0], d};
        end
    end

    // Multiplexers
    always @* begin
        case (mux_sel)
            3'b000: in_sel = in[0];
            3'b001: in_sel = in[1];
            3'b010: in_sel = in[2];
            3'b011: in_sel = in[3];
            3'b100: in_sel = in[4];
            3'b101: in_sel = in[5];
            3'b110: in_sel = in[6];
            3'b111: in_sel = in[7];
        endcase

        and_out = ~(in_sel & shift_reg_out);
        or_out = ~(in_sel | shift_reg_out);
        xor_out = ~(in_sel ^ shift_reg_out);
    end

    // Output selection
    always @(shift_reg_out) begin
        case (shift_reg_out)
            2'b00: mux_sel <= 3'b000;
            2'b01: mux_sel <= 3'b001;
            2'b10: mux_sel <= 3'b010;
            2'b11: mux_sel <= 3'b011;
        endcase
    end

    // Output ports
    assign out_and = and_out;
    assign out_or = or_out;
    assign out_xor = xor_out;

    // Shift register output
    assign shift_reg_out = shift_reg;

endmodule

module adc_dac_interface (
  input       clk,
  input [31:0] adc_input,
  output [31:0] dac_output,
  output      dac_en
);

  reg dac_en_reg;

  always @(*) begin
    if (adc_input <= (2**31 - 1) / 2) begin
      dac_output = 0;
      dac_en_reg = 0;
    end else begin
      dac_output = adc_input;
      dac_en_reg = 1;
    end
  end

  assign dac_en = dac_en_reg;

endmodule

module logicGates (
  input a,
  input b,
  output out
);

parameter gate = "AND"; // type of logic gate to be implemented

  // Implement AND gate
  assign out = (gate == "AND") ? (a & b) :
               // Implement OR gate
               (gate == "OR") ? (a | b) :
               // Implement NOT gate
               (gate == "NOT") ? (!a) :
               // Implement XOR gate
               (gate == "XOR") ? (a ^ b) :
               // Implement XNOR gate
               (gate == "XNOR") ? (!(a ^ b)) :
               // Default to AND gate
               (a & b);

endmodule

module Integrador_theta (
    input [15:0] a,
    input [15:0] dt,
    input enable,
    input rst,
    input clk,
    output reg [31:0] v,
    output reg busy
);

reg [15:0] aprev;
reg [31:0] vprev;
reg [1:0] state;

always @(posedge clk) begin
    if (rst) begin
        v <= 0;
        busy <= 0;
        state <= 0;
    end else begin
        case (state)
            0: begin // wait for enable
                if (enable) begin
                    aprev <= a;
                    vprev <= 0;
                    state <= 1;
                    busy <= 1;
                end
            end
            1: begin // integrate
                v <= vprev + (dt * ((a + aprev) >> 1));
                aprev <= a;
                vprev <= v;
                if (enable) begin
                    state <= 1;
                    busy <= 1;
                end else begin
                    state <= 2;
                end
            end
            2: begin // done
                busy <= 0;
                state <= 0;
            end
        endcase
    end
end

endmodule

module async_memory (
    input CLK,
    input WR_EN,
    input WR_RST,
    input WR_CLK,
    input [C_DEPTH_BITS-1:0] wWrPtr,
    input [C_DEPTH_BITS-1:0] wRdPtr,
    input [C_RAM_WIDTH-1:0] WR_DATA,
    output [C_RAM_WIDTH-1:0] RD_DATA,
    input RD_EN,
    input RD_RST,
    input RD_CLK,
    output reg RD_EMPTY,
    output reg WR_FULL
);

// Internal signals
reg [C_DEPTH_BITS-1:0] wWrPtrP1;
reg [C_DEPTH_BITS-1:0] wRdPtrP1;
reg [C_DEPTH_BITS-1:0] wCmpEmpty;
reg [C_DEPTH_BITS-1:0] wCmpFull;

// RAM module
ram_2clk_1w_1r #(.C_RAM_WIDTH(C_WIDTH), .C_RAM_DEPTH(C_REAL_DEPTH)) mem (
    .CLKA(WR_CLK),
    .ADDRA(wWrPtr),
    .WEA(WR_EN & !WR_FULL),
    .DINA(WR_DATA),
    .CLKB(RD_CLK),
    .ADDRB(wRdPtr),
    .DOUTB(RD_DATA)
);

// Pointer comparison module
async_cmp #(.C_DEPTH_BITS(C_DEPTH_BITS)) asyncCompare (
    .WR_RST(WR_RST),
    .WR_CLK(WR_CLK),
    .RD_RST(RD_RST),
    .RD_CLK(RD_CLK),
    .RD_VALID(RD_EN & !RD_EMPTY),
    .WR_VALID(WR_EN & !WR_FULL),
    .EMPTY(wCmpEmpty), 
    .FULL(wCmpFull),
    .WR_PTR(wWrPtr), 
    .WR_PTR_P1(wWrPtrP1), 
    .RD_PTR(wRdPtr), 
    .RD_PTR_P1(wRdPtrP1)
);

// Empty calculation module
rd_ptr_empty #(.C_DEPTH_BITS(C_DEPTH_BITS)) rdPtrEmpty (
    .RD_EMPTY(RD_EMPTY), 
    .RD_PTR(wRdPtr),
    .RD_PTR_P1(wRdPtrP1),
    .CMP_EMPTY(wCmpEmpty), 
    .RD_EN(RD_EN),
    .RD_CLK(RD_CLK), 
    .RD_RST(RD_RST)
);

// Full calculation module
wr_ptr_full #(.C_DEPTH_BITS(C_DEPTH_BITS)) wrPtrFull (
    .WR_CLK(WR_CLK), 
    .WR_RST(WR_RST),
    .WR_EN(WR_EN),
    .WR_FULL(WR_FULL), 
    .WR_PTR(wWrPtr),
    .WR_PTR_P1(wWrPtrP1),
    .CMP_FULL(wCmpFull)
);

// Next write and read pointers
always @(posedge WR_CLK) begin
    wWrPtrP1 <= wWrPtr + 1;
end

always @(posedge RD_CLK) begin
    wRdPtrP1 <= wRdPtr + 1;
end

// Full and empty flags
always @(*) begin
    if (wCmpFull == C_REAL_DEPTH-1) begin
        WR_FULL <= 1;
    end else begin
        WR_FULL <= 0;
    end

    if (wCmpEmpty == C_DEPTH_BITS-1) begin
        RD_EMPTY <= 1;
    end else begin
        RD_EMPTY <= 0;
    end
end

