module priority_encoder (
  input clk,
  input reset,
  input in0,
  input in1,
  input in2,
  input in3,
  output reg out,
  output reg valid
);

  always @(in0 or in1 or in2 or in3) begin
    if (reset) begin
      out <= 1'b0;
      valid <= 1'b0;
    end else begin
      casez({in3, in2, in1, in0})
        4'b0001: out <= 1'b00;
        4'b0010: out <= 1'b01;
        4'b0100: out <= 1'b10;
        4'b1000: out <= 1'b11;
        default: out <= out;
      endcase
      if (in0 || in1 || in2 || in3) begin
        valid <= 1'b1;
      end else begin
        valid <= 1'b0;
      end
    end
  end

endmodule

