module wb_mux(
    // Clock and reset
    clk, rst,

    // Internal i/f
    wb_freeze, rfwb_op,
    muxin_a, muxin_b, muxin_c, muxin_d,
    muxout, muxreg, muxreg_valid
);

parameter width = 32;

//
// I/O
//

//
// Clock and reset
//
input               clk;
input               rst;

//
// Internal i/f
//
input               wb_freeze;
input   [2:0]       rfwb_op;
input   [width-1:0] muxin_a;
input   [width-1:0] muxin_b;
input   [width-1:0] muxin_c;
input   [width-1:0] muxin_d;
output  [width-1:0] muxout;
output  [width-1:0] muxreg;
output              muxreg_valid;

//
// Internal wires and regs
//
reg [width-1:0] muxout;
reg [width-1:0] muxreg;
reg muxreg_valid;

//
// Registered output from the write-back multiplexer
//
always @(posedge clk or posedge rst) begin
    if (rst) begin
        muxreg <= 32'd0;
        muxreg_valid <= 1'b0;
    end
    else if (!wb_freeze) begin
        muxreg <= muxout;
        muxreg_valid <= rfwb_op[0];
    end
end

//
// Write-back multiplexer
//
always @(*) begin
    case(rfwb_op[2:1])
        2'b00: muxout = muxin_a;
        2'b01: muxout = muxin_b;
        2'b10: muxout = muxin_c;
        2'b11: muxout = muxin_d + 32'h8;
    endcase
end

endmodule

module add(sum, left, right, clk);
  output sum;
  input left, right, clk;
  reg sum;

  always @(posedge clk) begin
    sum <= left + right;
  end
endmodule

module lll(left, a, b, c, d, clk);
  output left;
  input a, b, c, d, clk;
  reg left;

  always @(posedge clk) begin
    left <= a & b | c & d;
  end
endmodule

module llr(right, a, b, c, d, clk);
  output right;
  input a, b, c, d, clk;
  reg right;

  always @(posedge clk) begin
    right <= a ^ b ^ c ^ d;
  end
endmodule

module ll(sum, a, b, c, d, clk);
  output sum;
  input a, b, c, d, clk;
  wire left, right;

  add add(sum, left, right, clk);
  lll lll(left, a, b, c, d, clk);
  llr llr(right, a, b, c, d, clk);
endmodule

module sky130_fd_sc_hvl__xnor2 (
    input A,
    input B,
    input VPWR,
    input VGND,
    inout VPB,
    inout VNB,
    output Y
);

    wire A_inv, B_inv, AB_and, AB_nand, AB_nor, AB_or, AB_xor;

    assign A_inv = ~A;
    assign B_inv = ~B;
    assign AB_and = A & B;
    assign AB_nand = ~(A & B);
    assign AB_nor = ~(A | B);
    assign AB_or = A | B;
    assign AB_xor = A ^ B;

    assign VPB = VGND & AB_nand & AB_nor;
    assign VNB = VPWR & AB_nand & AB_or;

    assign Y = ~(AB_xor & VPB & VNB);

endmodule

module block_memory (
    input clock, reset, enable,
    input [4:0] row1, row2, col1, col2,
    input [1:0] func, stage,
    output reg [2:0] block1, block2,
    output reg busy
);

    reg [2:0] mem [15:0];
    integer i;
    reg [1:0] op;

    always @(posedge clock or negedge reset) begin
        if (~reset) begin
            busy <= 0;
            op <= 0;
        end else begin
            if (enable) begin
                if (stage) begin
                    op <= func;
                end else begin
                    case (op)
                        2'b00: begin // Clear
                            mem[{row1, col1}] <= 3'b0;
                            mem[{row2, col2}] <= 3'b0;
                        end
                        2'b10: begin // Drop
                            mem[{row1, col1}] <= mem[{row2, col2}];
                            mem[{row2, col2}] <= 3'b0;
                        end
                        2'b11: begin // Read
                            block1 <= mem[{row1, col1}];
                            block2 <= mem[{row2, col2}];
                            busy <= 0;
                        end
                    endcase
                    op <= 0;
                end
            end
        end
    end

    always @(posedge clock or negedge reset) begin
        if (~reset) begin
            busy <= 0;
        end else begin
            if (enable && stage) begin
                case (func)
                    2'b01: begin // Load
                        for (i = 0; i < 16; i = i + 1) begin
                            mem[i] <= {row1, col1} == i ? block1 :
                                      {row2, col2} == i ? block2 : mem[i];
                        end
                        busy <= 1;
                    end
                    default: begin
                        busy <= 0;
                    end
                endcase
            end
        end
    end

endmodule

