module fifo #(parameter depth = 8)
(
  input clock,
  input reset,
  input push,
  input pop,
  input [7:0] data_in,
  output [7:0] data_out,
  output full,
  output empty
);

  reg [7:0] buffer [depth-1:0];
  reg [2:0] head = 3'd0;
  reg [2:0] tail = 3'd0;
  reg [2:0] count = 3'd0;

  always @(posedge clock, posedge reset) begin
    if (reset) begin
      head <= 3'd0;
      tail <= 3'd0;
      count <= 3'd0;
      full <= 1'b0;
      empty <= 1'b1;
    end else begin
      if (push && !full) begin
        buffer[head] <= data_in;
        head <= (head == depth-1) ? 3'd0 : head + 1;
        count <= count + 1;
        empty <= 1'b0;
        full <= (count == depth) ? 1'b1 : 1'b0;
      end
      if (pop && !empty) begin
        data_out <= buffer[tail];
        buffer[tail] <= 8'd0;
        tail <= (tail == depth-1) ? 3'd0 : tail + 1;
        count <= count - 1;
        full <= 1'b0;
        empty <= (count == 1) ? 1'b1 : 1'b0;
      end
    end
  end

endmodule

