            end
            4'b0100: begin
                counter_out <= 16'd4;
                state <= 4'b0101;
            end
            4'b0101: begin
                counter_out <= 16'd5;
                state <= 4'b0110;
            end
            4'b0110: begin
                counter_out <= 16'd6;
                state <= 4'b0111;
            end
            4'b0111: begin
                counter_out <= 16'd7;
                state <= 4'b1000;
            end
            4'b1000: begin
                counter_out <= 16'd8;
                state <= 4'b1001;
            end
            4'b1001: begin
                counter_out <= 16'd9;
                state <= 4'b1010;
            end
            4'b1010: begin
                counter_out <= 16'd10;
                state <= 4'b1011;
            end
            4'b1011: begin
                counter_out <= 16'd11;
                state <= 4'b1100;
            end
            4'b1100: begin
                counter_out <= 16'd12;
