always @ (posedge clk) begin
    if (reset) begin
        shift_reg <= 100'd0;
    end else if (load) begin
        shift_reg <= data;
    end else begin
        case (rot_ena)
            2'b00: shift_reg <= {shift_reg[98:0], shift_reg[99]};
            2'b01: shift_reg <= {shift_reg[99], shift_reg[98:0]};
            2'b10: shift_reg <= shift_reg;
            2'b11: shift_reg <= shift_reg;
        endcase
    end
end

assign q = shift_reg;

