);
    always @(shift_out or accum_out or select) begin
        if (select) begin
            out <= {8'b0, accum_out};
        end
        else begin
            out <= {shift_out, 8'b0};
        end
    end
endmodule

module top_module (
    input clk,
    input rst_n,
    input [99:0] in,
    input [5:0] shift_amount,
    input [7:0] data_in,
    input valid_a,
    input ready_b,
    input select,
    output ready_a,
    output reg valid_b,
    output reg [107:0] out
);
    wire [99:0] shift_out;
    wire [7:0] accum_out;

    shift_left_module shift_left_inst (
        .in(in),
        .shift_amount(shift_amount),
        .out(shift_out)
    );

    accumulator accum_inst (
        .data_in(data_in),
        .clk(clk),
        .rst_n(rst_n),
        .accum_out(accum_out),
        .valid_out(valid_b)
    );

    sum_module sum_inst (
        .shift_out(shift_out),
        .accum_out(accum_out),
        .select(select),
        .out(out)
    );

    assign ready_a = ~valid_a | valid_b;
endmodule

module single_clock_fifo (
    input clk,
    input [7:0] fifo_wdata,
    input fifo_wr,
    output fifo_FF,
    output [7:0] r_dat,
    output wfifo_empty,
    output [5:0] wfifo_used
);

    reg [7:0] fifo [0:63]; // 64-word FIFO
    reg [5:0] fifo_head = 0;
    reg [5:0] fifo_tail = 0;
    reg [5:0] fifo_count = 0;

    assign wfifo_used = fifo_count;
    assign fifo_FF = (fifo_count == 64);
    assign wfifo_empty = (fifo_count == 0);

    always @(posedge clk) begin
        if (fifo_wr) begin
            fifo[fifo_tail] <= fifo_wdata;
            fifo_tail <= (fifo_tail == 63) ? 0 : fifo_tail + 1;
            fifo_count <= fifo_count + 1;
        end
        if (fifo_count > 0) begin
            r_dat <= fifo[fifo_head];
            fifo_head <= (fifo_head == 63) ? 0 : fifo_head + 1;
            fifo_count <= fifo_count - 1;
        end
    end

endmodule

module BUF_ZERO (Z);
  output Z;

  buf (Z, 1'b0);

