module clk_generator(
    input wire CLK_IN,
    input wire RESET,
    output reg CLK_OUT1,
    output reg CLK_OUT2,
    output reg LOCKED
);

    // Define constants
    localparam CLK_RATIO = 2;
    localparam CLK_PERIOD = 20; // ns
    localparam CLK_HALF_PERIOD = CLK_PERIOD / 2;
    localparam PHASE_ERR_MARGIN = 1; // ns

    // Define counters
    reg [31:0] count1 = 0;
    reg [31:0] count2 = 0;

    // Define phase error variables
    reg [31:0] phase_err = 0;
    reg [31:0] prev_phase_err = 0;
    reg [31:0] phase_err_accum = 0;

    // Define locked flag
    reg locked_flag = 0;

    // Generate output clocks
    always @(posedge CLK_IN or posedge RESET) begin
        if (RESET) begin
            CLK_OUT1 <= 0;
            CLK_OUT2 <= 0;
            count1 <= 0;
            count2 <= 0;
            phase_err <= 0;
            prev_phase_err <= 0;
            phase_err_accum <= 0;
            locked_flag <= 0;
        end else begin
            count1 <= count1 + 1;
            count2 <= count2 + 1;
            if (count1 == CLK_RATIO * CLK_HALF_PERIOD) begin
                CLK_OUT1 <= ~CLK_OUT1;
                count1 <= 0;
            end
            if (count2 == CLK_HALF_PERIOD) begin
                CLK_OUT2 <= ~CLK_OUT2;
                count2 <= 0;
            end
        end
    end

    // Check phase error and update locked flag
    always @(posedge CLK_OUT1 or posedge CLK_OUT2) begin
        if (CLK_OUT1 != CLK_OUT2) begin
            phase_err <= CLK_HALF_PERIOD - count2;
            if (phase_err > CLK_HALF_PERIOD) begin
                phase_err <= phase_err - CLK_PERIOD;
            end
            phase_err_accum <= phase_err_accum + phase_err - prev_phase_err;
            prev_phase_err <= phase_err;
            if (phase_err_accum > PHASE_ERR_MARGIN || phase_err_accum < -PHASE_ERR_MARGIN) begin
                locked_flag <= 0;
            end else begin
                locked_flag <= 1;
            end
        end
    end

    // Assign locked flag to output
    assign LOCKED = locked_flag;

endmodule

module binary_counter(
    input clk,
    input rst,
    input en,
    output reg [3:0] count,
    output reg [3:0] leds
);

always @(posedge clk) begin
    if (rst) begin
        count <= 4'b0000;
    end else if (en) begin
        count <= count + 1;
    end
end

assign leds = count;

endmodule

module fifo_32in_32out_32kb(
    input rst,
    input wr_clk,
    input rd_clk,
    input [31:0] din,
    input wr_en,
    input rd_en,
    output [31:0] dout,
    output full,
    output empty,
    output reg [2:0] rd_data_count,
    output reg [1:0] wr_data_count
);

    reg [31:0] mem [1023:0];
    reg [9:0] wr_ptr;
    reg [9:0] rd_ptr;
    reg [9:0] rd_ptr_next;
    reg [1:0] wr_count;
    reg [1:0] rd_count;
    wire [1:0] rd_count_next;
    reg [31:0] dout_reg;
    reg full_reg;
    reg empty_reg;

    // Reset the buffer
    always @(posedge wr_clk or negedge rst) begin
        if (~rst) begin
            wr_ptr <= 0;
            rd_ptr <= 0;
            rd_ptr_next <= 0;
            wr_count <= 0;
            rd_count <= 0;
            rd_data_count <= 0;
            wr_data_count <= 3;
            dout_reg <= 0;
            full_reg <= 0;
            empty_reg <= 1;
        end
    end

    // Write data to the buffer
    always @(posedge wr_clk) begin
        if (wr_en && ~full_reg) begin
            mem[wr_ptr] <= din;
            wr_ptr <= wr_ptr + 1;
            wr_count <= wr_count + 1;
            wr_data_count <= wr_data_count - 1;
            empty_reg <= 0;
            if (wr_ptr == 1023) begin
                wr_ptr <= 0;
            end
            if (wr_count == 511) begin
                full_reg <= 1;
            end
        end
    end

    // Read data from the buffer
    always @(posedge rd_clk) begin
        if (rd_en && ~empty_reg) begin
            dout_reg <= mem[rd_ptr];
            rd_ptr_next <= rd_ptr + 1;
            rd_count <= rd_count_next;
            rd_data_count <= rd_count;
            if (rd_ptr == 1023) begin
                rd_ptr <= 0;
            end
            if (rd_count_next == 0) begin
                empty_reg <= 1;
            end
        end
    end

    // Update read count
    always @(*) begin
        rd_count_next = rd_count - rd_en + wr_en;
    end

    assign dout = dout_reg;
    assign full = full_reg;
    assign empty = empty_reg;

endmodule

module video_timing_gen (
  input aclk, rst,
  input axis_tready, axis_tvalid,
  input [23:0] axis_video,
  input axis_eol, axis_sof,
  input [1:0] fid,
  input [11:0] active_pixels,
  input [11:0] active_lines,
  output reg video_clk, ce,
  output [11:0] total_lines,
  output [11:0] vsync_start, vsync_end,
  output [11:0] total_pixels,
  output [11:0] hsync_start, hsync_end,
  output reg vtg_hsync, vtg_vsync, vtg_vblank, vtg_hblank, vtg_act_vid,
  output reg [1:0] vtg_field_id
);

  // Constants
  parameter H_SYNC_WIDTH = 96;
  parameter H_BLANK_WIDTH = 208;
  parameter V_SYNC_WIDTH = 2;
  parameter V_BLANK_WIDTH = 35;

  // Internal signals
  reg [11:0] line_count = 0;
  reg [11:0] pixel_count = 0;
  reg [11:0] vsync_start_time = 0;
  reg [11:0] vsync_end_time = 0;
  reg [11:0] hsync_start_time = 0;
  reg [11:0] hsync_end_time = 0;
  reg [11:0] total_pixels_reg = 0;
  reg [11:0] total_lines_reg = 0;
  reg [1:0] field_id_reg = 0;

  // Video data input
  reg [7:0] r, g, b;

  always @(posedge aclk) begin
    if (rst) begin
      video_clk <= 0;
      ce <= 0;
      line_count <= 0;
      pixel_count <= 0;
      vsync_start_time <= 0;
      vsync_end_time <= 0;
      hsync_start_time <= 0;
      hsync_end_time <= 0;
      total_pixels_reg <= 0;
      total_lines_reg <= 0;
      field_id_reg <= 0;
      vtg_hsync <= 0;
      vtg_vsync <= 0;
      vtg_vblank <= 0;
      vtg_hblank <= 0;
      vtg_act_vid <= 0;
      vtg_field_id <= 0;
    end else begin
      // Video timing generator
      if (line_count < active_lines) begin
        vtg_act_vid <= 1;
      end else begin
        vtg_act_vid <= 0;
      end
      if (line_count < active_lines + V_SYNC_WIDTH) begin
        vtg_vsync <= 0;
      end else if (line_count < active_lines + V_SYNC_WIDTH + V_BLANK_WIDTH) begin
        vtg_vsync <= 1;
        vtg_vblank <= 1;
      end else if (line_count < 2*active_lines + V_SYNC_WIDTH + V_BLANK_WIDTH) begin
        vtg_vsync <= 0;
        vtg_vblank <= 0;
      end else if (line_count < 2*active_lines + 2*V_SYNC_WIDTH + V_BLANK_WIDTH) begin
        vtg_vsync <= 1;
        vtg_vblank <= 1;
      end else begin
        vtg_vsync <= 0;
        vtg_vblank <= 0;
      end
      if (pixel_count < active_pixels) begin
        vtg_hsync <= 1;
        vtg_hblank <= 0;
        vtg_field_id <= field_id_reg;
      end else if (pixel_count < active_pixels + H_SYNC_WIDTH) begin
        vtg_hsync <= 0;
        vtg_hblank <= 0;
      end else if (pixel_count < active_pixels + H_SYNC_WIDTH + H_BLANK_WIDTH) begin
        vtg_hsync <= 0;
        vtg_hblank <= 1;
      end else begin
        vtg_hsync <= 0;
        vtg_hblank <= 0;
        pixel_count <= 0;
        line_count <= line_count + 1;
        if (line_count >= 2*active_lines + 2*V_SYNC_WIDTH + V_BLANK_WIDTH) begin
          line_count <= 0;
          total_lines_reg <= total_lines_reg + 1;
          field_id_reg <= ~field_id_reg;
        end
      end

      // Video clock generator
      if (pixel_count == active_pixels - 1) begin
        video_clk <= 1;
        total_pixels_reg <= total_pixels_reg + active_pixels;
        pixel_count <= 0;
        ce <= 1;
      end else begin
        video_clk <= 0;
        pixel_count <= pixel_count + 1;
        ce <= 0;
      end

      // Video data input
      if (axis_tvalid && axis_tready) begin
        r <= axis_video[23:16];
        g <= axis_video[15:8];
        b <= axis_video[7:0];
      end

      // Vertical sync pulse timing
      if (line_count == active_lines + V_SYNC_WIDTH) begin
        vsync_start_time <= total_pixels_reg + pixel_count;
      end
      if (line_count == active_lines + V_SYNC_WIDTH + V_BLANK_WIDTH) begin
        vsync_end_time <= total_pixels_reg + pixel_count;
      end

      // Horizontal sync pulse timing
      if (pixel_count == active_pixels + H_SYNC_WIDTH) begin
        hsync_start_time <= total_pixels_reg + pixel_count;
      end
      if (pixel_count == active_pixels + H_SYNC_WIDTH + H_BLANK_WIDTH) begin
        hsync_end_time <= total_pixels_reg + pixel_count;
      end
    end
  end

  assign total_pixels = total_pixels_reg;
  assign total_lines = total_lines_reg;
  assign vsync_start = vsync_start_time;
  assign vsync_end = vsync_end_time;
  assign hsync_start = hsync_start_time;
  assign hsync_end = hsync_end_time;

endmodule

module spi_device (
    input reset,
    input clk,
    input [7:0] data_in,
    output reg mosi,
    input miso,
    output reg ready
);

    reg [7:0] buffer;
    reg [2:0] cnt;
    reg [7:0] data;

    always @(posedge clk) begin
        if (reset) begin
            buffer <= 8'h00;
            cnt <= 3'h0;
            data <= 8'h00;
            mosi <= 1'b0;
            ready <= 1'b0;
        end else begin
            if (cnt == 3'h0) begin
                buffer <= data_in;
                mosi <= buffer[7];
                cnt <= 3'h1;
            end else if (cnt == 3'h7) begin
                buffer <= {buffer[6:0], miso};
                cnt <= 3'h0;
                data <= data + 8'h01;
                if (data == 8'hff) begin
                    ready <= 1'b1;
                end
            end else begin
                buffer <= {buffer[6:0], mosi};
                mosi <= buffer[7];
                cnt <= cnt + 3'h1;
            end
        end
    end

endmodule

module sign_extender
  #(
    parameter
    INPUT_WIDTH = 8,
    OUTPUT_WIDTH = 16
    )
  (
   input [INPUT_WIDTH-1:0] original,
   output reg [OUTPUT_WIDTH-1:0] sign_extended_original
   );

  wire [OUTPUT_WIDTH-INPUT_WIDTH-1:0] sign_extend;

  generate
    genvar                           i;
    for (i = 0; i < OUTPUT_WIDTH-INPUT_WIDTH; i = i + 1) begin : gen_sign_extend
      assign sign_extend[i]  = (original[INPUT_WIDTH-1]) ? 1'b1 : 1'b0;
    end
  endgenerate

  always @ * begin
    sign_extended_original  = {sign_extend,original};
  end

endmodule

module memoryaccess(
    input [31:0] writedata, aluresultin, pcbranch1,
    input [4:0] writereg1,
    input branch, memwrite, memtoreg1, regwrite1, zerowire, clk,
    output reg [31:0] readdata, aluresultout, pcbranch2,
    output reg [4:0] writereg2,
    output reg regwrite2, memtoreg2, pcsrc
);

    reg [31:0] dmem [0:1023];
    integer i;

    always @(posedge clk) begin
        if (memwrite) begin
            dmem[aluresultin] <= writedata;
        end else begin
            readdata <= dmem[aluresultin];
        end

        if (memtoreg1) begin
            writereg2 <= writereg1;
            memtoreg2 <= memtoreg1;
            regwrite2 <= regwrite1;
            readdata <= dmem[aluresultin];
        end else if (regwrite1) begin
            writereg2 <= writereg1;
            memtoreg2 <= memtoreg1;
            regwrite2 <= regwrite1;
            readdata <= aluresultin;
        end else begin
            writereg2 <= writereg1;
            memtoreg2 <= memtoreg1;
            regwrite2 <= regwrite1;
        end

        if (branch && !zerowire) begin
            pcbranch2 <= pcbranch1;
        end else if (zerowire && aluresultin == 0) begin
            pcbranch2 <= pcbranch1;
        end else begin
            pcbranch2 <= aluresultin;
        end

        aluresultout <= aluresultin;
        pcsrc <= branch || (zerowire && aluresultin == 0);
    end

endmodule

module addsub_4bit (
    input [3:0] in_a,
    input [3:0] in_b,
    input mode,
    output reg [3:0] out,
    output overflow
);

reg [3:0] a_reg, b_reg, sum_reg;
reg [2:0] stage;
wire [3:0] sum_wire;

assign sum_wire = (mode == 0) ? (a_reg + b_reg) : (a_reg - b_reg);

always @(*) begin
    case(stage)
        0: begin
            a_reg <= in_a;
            b_reg <= in_b;
            stage <= 1;
        end
        1: begin
            sum_reg <= sum_wire;
            stage <= 2;
        end
        2: begin
            out <= sum_reg;
            overflow <= (sum_reg > 7) || (sum_reg < -8);
            stage <= 0;
        end
    endcase
end

endmodule

module calculator(
    input clk,
    input rst,
    input [7:0] num1,
    input [7:0] num2,
    input [1:0] op,
    output reg [15:0] res,
    output reg flag
);

    reg [7:0] a;
    reg [7:0] b;
    reg [15:0] temp_res;

    always @(posedge clk) begin
        if (rst) begin
            res <= 0;
            flag <= 0;
        end else begin
            a <= num1;
            b <= num2;

            case (op)
                2'b00: temp_res <= a + b;
                2'b01: temp_res <= a - b;
                2'b10: temp_res <= a * b;
                2'b11: temp_res <= a / b;
            endcase

            res <= temp_res;
            flag <= (temp_res < 0);
        end
    end

endmodule

module hdmi_interface(
  input clk,
  input clk_x2,
  input clk_100,
  input active,
  input hsync,
  input vsync,
  input [23:0]rgb888,
  output hdmi_clk,
  output hdmi_hsync,
  output hdmi_vsync,
  output [15:0]hdmi_d,
  output hdmi_de,
  output hdmi_scl,
  inout hdmi_sda
);

  // Declare internal signals
  wire pixel_valid;
  reg [23:0]pixel_data;
  reg [3:0]pixel_count;
  reg [3:0]pixel_index;
  reg [3:0]line_count;
  reg [3:0]line_index;
  reg [2:0]frame_count;
  reg [2:0]frame_index;
  reg [1:0]i2c_count;
  reg [1:0]i2c_index;
  reg [7:0]i2c_data;
  reg i2c_start;
  reg i2c_stop;
  reg [1:0]i2c_state;
  reg [3:0]i2c_bit_count;
  reg [7:0]i2c_address;
  reg [7:0]i2c_register;
  reg [7:0]i2c_value;

  // Generate the HDMI clock
  assign hdmi_clk = clk_100;

  // Generate the horizontal and vertical sync signals
  assign hdmi_hsync = hsync;
  assign hdmi_vsync = vsync;

  // Generate the pixel data and valid signal
  always @(posedge clk_x2) begin
    if (active) begin
      if (pixel_count == 0) begin
        pixel_data <= rgb888;
        pixel_valid <= 1;
      end else begin
        pixel_data <= {pixel_data[15:0], rgb888[7:0], rgb888[15:8], rgb888[23:16]};
        pixel_valid <= 0;
      end

      pixel_count <= pixel_count + 1;
      if (pixel_count == 3) begin
        pixel_count <= 0;
      end
    end else begin
      pixel_valid <= 0;
    end
  end

  // Output the pixel data and valid signal
  assign hdmi_d = pixel_data[15:0];
  assign hdmi_de = pixel_valid;

  // Generate the I2C signals
  assign hdmi_scl = 1;
  assign hdmi_sda = (i2c_bit_count == 0) ? 1 : i2c_data[i2c_bit_count];

  // Handle the I2C state machine
  always @(posedge hdmi_clk) begin
    case (i2c_state)
      0: begin // Idle state
        if (!hdmi_sda) begin
          i2c_bit_count <= 0;
          i2c_address <= 0;
          i2c_register <= 0;
          i2c_value <= 0;
          i2c_start <= 1;
          i2c_state <= 1;
        end
      end
      1: begin // Start state
        if (hdmi_sda) begin
          i2c_start <= 0;
          i2c_bit_count <= 0;
          i2c_state <= 2;
        end
      end
      2: begin // Address state
        if (hdmi_sda) begin
          i2c_address <= (i2c_address << 1) | 1;
        end else begin
          i2c_address <= (i2c_address << 1);
        end
        i2c_bit_count <= i2c_bit_count + 1;
        if (i2c_bit_count == 8) begin
          i2c_bit_count <= 0;
          i2c_state <= 3;
        end
      end
      3: begin // Acknowledge state
        if (!hdmi_sda) begin
          i2c_bit_count <= 0;
          i2c_state <= 4;
        end
      end
      4: begin // Register state
        if (hdmi_sda) begin
          i2c_register <= (i2c_register << 1) | 1;
        end else begin
          i2c_register <= (i2c_register << 1);
        end
        i2c_bit_count <= i2c_bit_count + 1;
        if (i2c_bit_count == 8) begin
          i2c_bit_count <= 0;
          i2c_state <= 5;
        end
      end
      5: begin // Acknowledge state
        if (!hdmi_sda) begin
          i2c_bit_count <= 0;
          i2c_state <= 6;
        end
      end
      6: begin // Value state
        if (hdmi_sda) begin
          i2c_value <= (i2c_value << 1) | 1;
        end else begin
          i2c_value <= (i2c_value << 1);
        end
        i2c_bit_count <= i2c_bit_count + 1;
        if (i2c_bit_count == 8) begin
          i2c_bit_count <= 0;
          i2c_state <= 7;
        end
      end
      7: begin // Acknowledge state
        if (!hdmi_sda) begin
          i2c_bit_count <= 0;
          i2c_state <= 8;
        end
      end
      8: begin // Stop state
        if (hdmi_sda) begin
          i2c_stop <= 1;
          i2c_state <= 9;
        end
      end
      9: begin // Idle state
        i2c_stop <= 0;
        i2c_state <= 0;
      end
    endcase
  end

  // Increment the line and frame counters
  always @(posedge hdmi_clk) begin
    if (active) begin
      if (hsync) begin
        line_count <= line_count + 1;
        line_index <= 0;
        if (line_count == 525) begin
          line_count <= 0;
          frame_count <= frame_count + 1;
          frame_index <= 0;
        end
      end else begin
        line_index <= line_index + 1;
        if (line_index == 640) begin
          line_index <= 0;
          frame_index <= frame_index + 1;
        end
      end
    end
  end

  // Increment the I2C index
  always @(posedge hdmi_clk) begin
    if (active) begin
      i2c_index <= i2c_index + 1;
      if (i2c_index == 500) begin
        i2c_index <= 0;
      end
    end
  end

endmodule

module Constant_Current_Driver (
  input [n-1:0] ctrl,
  output [m-1:0] out
);

parameter n = 2; // number of control signals
parameter m = 1; // number of output signals
parameter I = 10; // current magnitude in mA
parameter R = 100; // load resistance in ohms

reg [n-1:0] ctrl_reg;
reg [m-1:0] out_reg;
wire i_wire;
wire v_wire;

assign i_wire = I / R;
assign v_wire = i_wire * {ctrl_reg, 1'b1};

assign out = out_reg;

always @ (ctrl) begin
  ctrl_reg <= ctrl;
  out_reg <= v_wire * R;
end

endmodule

module counter_16bit (
    input clk,
    input reset,
    output reg [15:0] count
);

    always @(posedge clk) begin
        if (reset) begin
            count <= 0;
        end else begin
            count <= count + 1;
        end
    end

endmodule

module ALU_4bit (
    input [3:0] A,
    input [3:0] B,
    input [2:0] control,
    output reg [3:0] ALU_result
);

    always @(*)
    begin
        case(control)
            3'b000: ALU_result = A + B;
            3'b001: ALU_result = A - B;
            3'b010: ALU_result = A & B;
            3'b011: ALU_result = A | B;
            3'b100: ALU_result = A ^ B;
            3'b101: ALU_result = A << 1;
