assign p = a ^ b;
assign g = a & b;
assign c[0] = 1'b0;

genvar i;

generate
    for (i = 1; i < 8; i = i + 1) begin : carry_lookahead
        assign c[i] = g[i-1] | (p[i-1] & c[i-1]);
