  tranif0 pmos_12(net_111, vdd, b);
  tranif0 pmos_13(coutb, net_111, c);
  tranif0 pmos_14(s, vdd, sb);
endmodule

module adder_4bit(
    input [3:0] A,
    input [3:0] B,
    output [3:0] S
);

wire [3:0] C; //carry bits
wire [3:0] X; //sum bits

//full adder for bit 0
xor (X[0], A[0], B[0]);
and (C[0], A[0], B[0]);

//full adder for bit 1
xor (X[1], A[1], B[1], C[0]);
and (C[1], (A[1] & B[1]), (A[1] & C[0]), (B[1] & C[0]));

//full adder for bit 2
xor (X[2], A[2], B[2], C[1]);
and (C[2], (A[2] & B[2]), (A[2] & C[1]), (B[2] & C[1]));

//full adder for bit 3
xor (X[3], A[3], B[3], C[2]);
and (C[3], (A[3] & B[3]), (A[3] & C[2]), (B[3] & C[2]));

assign S = X;
endmodule

module adder_logic (in1, in2, res);
  input [7:0] in1;
  input [7:0] in2;
  output [8:0] res;

  wire [7:0] sum;
  wire [7:0] carry;

  // 8-bit adder with carry-out
  ripple_carry_adder adder(.in1(in1), .in2(in2), .carry_in(1'b0), .sum(sum), .carry_out(carry[7]));

  // most significant bit sum
  assign res[7] = in1[7] ^ in2[7];

  // res[6:1] combinational logic
  assign res[6] = ~(in1[5] & in2[5] & ~in1[6] & ~in2[6]) & (in1[6] | in2[6]);
  assign res[5] = ~(in1[4] & in2[4]) & (in1[5] ^ in2[5]);
  assign res[4] = ~(in1[3] & in2[3]) & (in1[4] ^ in2[4]);
  assign res[3] = ~(in1[2] & in2[2]) & (in1[3] ^ in2[3]);
  assign res[2] = ~(in1[1] & in2[1]) & (in1[2] ^ in2[2]);
  assign res[1] = ~(in1[0] & in2[0] & ~in1[1] & ~in2[1]) & (in1[1] | in2[1]);

  // res[0] combinational logic
  assign res[0] = ~(in1[0] & in2[0]) & (in1[0] | in2[0] | ~(in1[0] | in2[0]));

  // final carry-out bit
  assign res[8] = carry[7];

endmodule

module ripple_carry_adder (in1, in2, carry_in, sum, carry_out);
  input [7:0] in1;
  input [7:0] in2;
  input carry_in;
  output [7:0] sum;
  output carry_out;

  wire [7:0] carry;
  assign carry[0] = carry_in;

  // full adder for each bit
  genvar i;
  generate
    for (i = 0; i < 8; i = i + 1) begin : fa
      full_adder adder(.in1(in1[i]), .in2(in2[i]), .carry_in(carry[i]), .sum(sum[i]), .carry_out(carry[i+1]));
    end
  endgenerate

  // carry-out bit
  assign carry_out = carry[8];

endmodule

module full_adder (in1, in2, carry_in, sum, carry_out);
  input in1;
  input in2;
  input carry_in;
  output sum;
  output carry_out;

  // XOR gate for sum
  assign sum = in1 ^ in2 ^ carry_in;

  // majority gate for carry-out
  assign carry_out = (in1 & in2) | (in1 & carry_in) | (in2 & carry_in);

endmodule

module comparator_4bit (
  input [3:0] A,
