);

  always @(*) begin
    if (A == B) begin
      EQ = 1;
    end else begin
      EQ = 0;
    end
  end

endmodule

module fsm_sequence_detection (
  input clk,
  input reset,
  input data,
  output reg match
);

  parameter A = 2'b00, B = 2'b01, C = 2'b10, D = 2'b11;
  reg [1:0] state, next_state;

  always @(posedge clk) begin
    if (reset) begin
      state <= A;
      match <= 0;
    end
    else begin
      state <= next_state;
      match <= 0;
      case (state)
        A: begin
          if (data == 0) next_state = A;
          else if (data == 1) next_state = B;
          else next_state = A;
        end
        B: begin
          if (data == 0) next_state = C;
          else if (data == 1) next_state = B;
          else next_state = A;
        end
        C: begin
          if (data == 0) next_state = A;
          else if (data == 1) next_state = B;
          else next_state = D;
        end
        D: begin
          if (data == 0) next_state = A;
          else if (data == 1) next_state = B;
          else next_state = A;
          if (state == C) match <= 1;
        end
      endcase
    end
  end

endmodule

module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    input reset,
    input enable,
    output [3:0] S,
    output Cout
);

    wire [3:0] c; //carry
    wire [3:0] s; //sum

    // full adder for bit 0
    full_adder FA0(A[0], B[0], 1'b0, c[0], s[0]);

    // full adder for bit 1 to 3
    genvar i;
    generate
        for (i = 1; i < 4; i = i + 1) begin : adder_loop
            full_adder FA(
                A[i],
                B[i],
                c[i-1],
                c[i],
                s[i]
            );
        end
    endgenerate

    assign Cout = c[3];
    assign S = s;

    // reset and enable logic
    always @ (reset, enable) begin
        if (!reset) begin
            S <= 4'b0000;
            Cout <= 1'b0;
        end else if (!enable) begin
            S <= 4'b0000;
            Cout <= 1'b1;
        end
    end

endmodule

module full_adder(
    input a,
    input b,
    input cin,
    output reg cout,
    output reg s
);

    always @(a, b, cin) begin
        s = a ^ b ^ cin;
        cout = (a & b) | (b & cin) | (a & cin);
    end

endmodule

