module hankel_matrixd_d #(
	parameter ROW 	= 4,
	parameter COL 	= 4,
	parameter WIDTH	= 16,
	parameter ADDR	= 8
)(
	input 				clk,
	input 				start,
	input		[WIDTH-1:0] 	data,
	output reg	[ADDR-1:0] 	addr,
	output reg			rd
);

reg [WIDTH-1:0] mat [0:ROW-1] [0:COL-1];
reg [7:0] r,c,state;
parameter 
	IDLE = 2'b00,
	INIT = 2'b01,
	COPY = 2'b10,
	WRITE= 2'b11;

initial begin
	c <= 0;
	r <= 0;
	addr <=0;
	rd<=0;
	state <= IDLE;
end

always@(posedge clk) begin
	case(state)
		IDLE: begin
			if(start) begin
				state <= INIT;
				rd <=1;				
				r<=0;
				c<=0;
				addr <=0;
			end
		end
		INIT: begin
			if(r==0) begin
				mat[r][c] <= data;
				c <= c+1;
				addr <= addr+1;
				if(c==COL-1) begin	
					c <= 0;
					state <= COPY;					
					r <= r+1;
				end
			end
			else begin
				mat[r][c] <= mat[r-1][c+1];
				c <= c+1;
				if(c==COL-2)begin
					state <= WRITE;
					rd <= 1;	
					addr <= addr+1;
				end
			end
		end
		WRITE: begin			
			mat[r][c]<= data;
			state <= COPY;
			r <= r+1;
			c<=0;
			if(r==ROW-1)
				state <= IDLE;
		end
		COPY: begin
			mat[r][c] <= mat[r-1][c+1];
			c <= c+1;
			if(c==COL-2)begin
				state <= WRITE;
				rd <= 1;	
				addr <= addr+1;
			end
		end
	endcase
end
endmodule

module vending_machine_controller (
  input clk, reset, dispense,
  input [1:0] coin_insert, product_select,
  output reg coin_return, product_dispensed,
  output reg [4:0] display_value
);

  parameter nickel_value = 1;
  parameter dime_value = 2;
  parameter quarter_value = 5;

  reg [3:0] product_price;
  reg [3:0] money_inserted;
  reg [3:0] money_needed;
  reg [3:0] change;

  always @ (reset) begin
    product_price = 4'b0001; // product 1 costs 1 nickel
    money_inserted = 4'b0000; // no money inserted
    money_needed = product_price; // initialize to product 1 price
    change = 4'b0000; // no change
    product_dispensed = 0; // no product dispensed
    coin_return = 0; // no coins to return
    display_value = 5'b00000; // display zero
  end

  always @ (posedge clk) begin
    if (reset) begin
      product_price <= 4'b0001;
      money_inserted <= 4'b0000;
      money_needed <= product_price;
      change <= 4'b0000;
      product_dispensed <= 0;
      coin_return <= 0;
      display_value <= 5'b00000;
    end else begin
      // Update money inserted
      case (coin_insert)
        2'b00: money_inserted <= money_inserted + nickel_value;
        2'b01: money_inserted <= money_inserted + dime_value;
        2'b10: money_inserted <= money_inserted + quarter_value;
      endcase

      // Update money needed
      case (product_select)
        2'b00: money_needed <= product_price;
        2'b01: money_needed <= 4'b0010; // product 2 costs 2 dimes
        2'b10: money_needed <= 4'b0101; // product 3 costs 1 quarter and 1 nickel
        2'b11: money_needed <= 4'b1010; // product 4 costs 2 quarters and 1 dime
      endcase

      // Check if enough money has been inserted
      if (money_inserted >= money_needed) begin
        product_dispensed <= dispense;
        coin_return <= money_inserted - money_needed;
        change <= money_inserted - money_needed;
        money_inserted <= 4'b0000;
        money_needed <= product_price;
      end else begin
        product_dispensed <= 0;
        coin_return <= 0;
        change <= 4'b0000;
      end

      // Update display
      display_value <= money_inserted;
    end
  end

endmodule

