    input wire clk,
    input wire reset,
    input wire [15:0] in,
    input wire select,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo );

reg [3:0] shift;
wire [15:0] shifted_in;
wire shifter_en, mux_en;

barrel_shifter shifter(.in(in), .shift(shift), .out(shifted_in));
mux mux_hi(.in0(shifted_in[15:8]), .in1(shifted_in[7:0]), .sel(select), .out(out_hi));
mux mux_lo(.in0(shifted_in[15:8]), .in1(shifted_in[7:0]), .sel(~select), .out(out_lo));
control_logic ctrl(.select(select), .shifter_en(shifter_en), .mux_en(mux_en));

always @(posedge clk) begin
    if (reset) begin
        shift <= 0;
    end else begin
        if (shifter_en) begin
            shift <= shift + 8;
        end
    end
end

endmodule

