module flow_control_processing(
    input clock,
    input reset,
    input internal_output_is_valid,
    input ena,
    input ready_out,
    output stall,
    output valid_out,
    output [SYMBOLS_PER_BEAT*BITS_PER_SYMBOL-1:0] data_out,
    output eop_out,
    output sop_out
);

