  wire [31:0] ALU_op2;
  wire [31:0] ALUout;
  wire [31:0] C;
  wire [31:0] displacement;
  wire [31:0] distance;
  wire [4:0] RD;
  wire [4:0] RS;
  wire [4:0] Aad;
  wire [4:0] Bad;
  wire [7:0] opcode;
  wire [1:0] mod;
  wire add;
  wire aluop;
  wire btaken;
  wire halt;
  wire jnez;
  wire load;
  wire memory;
  wire move;
  wire store;
  wire sub;
  reg ZF;
  wire [1:0] length;

