    .clk(clk),
    .rst(rst),
    .bus_in(bus_in),
    .bus_A(bus_A),
    .bus_out(bus_out),
    .bus_WE(bus_WE),
    .bus_RE(bus_RE),
    .current_opcode(current_opcode)
  );

