  assign mod = bus_in[15:14];
  assign RD = bus_in[10:8];
  assign RS = bus_in[13:11];
  assign Aad = memory ? 6 : RD;
  assign Bad = RS;
  assign distance = {{24{bus_in[15]}}, bus_in[15:8]};
  assign displacement = {{24{bus_in[23]}}, bus_in[23:16]};
  assign btaken = jnez && !ZF;
  assign length = memory ? 3 : (aluop || move || jnez) ? 2 : 1;

  assign load = opcode == 'h8b && mod == 1;
  assign move = opcode == 'h89 && mod == 3;
  assign store = opcode == 'h89 && mod == 1;
  assign memory = load || store;
  assign add = opcode == 'h01;
  assign sub = opcode == 'h29;
  assign halt = opcode == 'hf4;
  assign aluop = add || sub;
  assign ALU_op2 = memory ? displacement : sub ? ~Bop : Bop;
  assign ALUout = Aop + ALU_op2 + sub;
  assign C = move ? Bop : ALUout;

  always @(posedge clk) begin
    if (rst) begin
      ZF <= 0;
    end else begin
      if (aluop) begin
        ZF <= (ALUout == 0);
      end
    end
