  assign bus_WE = store;
  assign bus_A = memory ? ALUout : bus_A;
  assign bus_RE = memory;

  always @(posedge clk) begin
    if (rst) begin
      Aop <= 0;
      Bop <= 0;
    end else begin
      Aop <= y86_seq_inst.Aop;
      Bop <= y86_seq_inst.Bop;
    end
  end

  always @(posedge clk) begin
    if (rst) begin
      C <= 0;
    end else begin
      C <= C;
    end
  end

  always @(posedge clk) begin
    if (rst) begin
      bus_out <= 0;
    end else begin
      bus_out <= Bop;
    end
  end

