  output almost_empty,
  output almost_full,
  output empty,
  output full,
  output [42:0] rd_data
);

  reg [1:0] entries;
  reg [42:0] entry_0;
  reg [42:0] entry_1;
  reg rd_address;
  wire [1:0] rdwr;
  reg wr_address;
  assign rdwr = {rd, wr};
  assign full = entries == 2;
  assign almost_full = entries >= 1;
  assign empty = entries == 0;
  assign almost_empty = entries <= 1;

  always @(entry_0 or entry_1 or rd_address) begin
    case (rd_address)
      1'b0: rd_data = entry_0;
      1'b1: rd_data = entry_1;
      default: rd_data = 43'h0;
    endcase
  end

  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      wr_address <= 1'b0;
      rd_address <= 1'b0;
      entries <= 2'b00;
    end else begin
      case (rdwr)
        2'b01: begin // write
          if (!full) begin
            entries <= entries + 1;
            wr_address <= ~wr_address;
            if (wr_address) begin
              entry_0 <= wr_data;
            end else begin
              entry_1 <= wr_data;
            end
          end
        end
        2'b10: begin // read
          if (!empty) begin
            entries <= entries - 1;
            rd_address <= ~rd_address;
          end
        end
        2'b11: begin // read and write
          if (!full) begin
            entries <= entries + 1;
            wr_address <= ~wr_address;
            if (wr_address) begin
              entry_0 <= wr_data;
            end else begin
              entry_1 <= wr_data;
            end
            if (!empty) begin
              entries <= entries - 1;
              rd_address <= ~rd_address;
            end
          end
        end
        default: begin
          wr_address <= 1'b0;
          rd_address <= 1'b0;
        end
      endcase
    end
  end

