module mem_protect (
  input [n-1:0] data_in,
  input [m-1:0] addr,
  input [k-1:0] ctrl,
  output [n-1:0] data_out
);

parameter n = 8; // number of data signals
parameter m = 10; // number of address signals
parameter k = 4; // number of control signals

reg [n-1:0] data_out_reg;
reg [n-1:0] data_mem [0:(2**m)-1];
reg [n-1:0] RE_mem [0:(2**m)-1];
reg [n-1:0] WE_mem [0:(2**m)-1];

integer i;

always @ (addr, ctrl, data_in, RE, WE) begin
  for (i = 0; i < n; i = i + 1) begin
    if (RE_mem[addr] == 1'b1) begin
      data_out_reg[i] = data_mem[addr][i];
    end else begin
      data_out_reg[i] = 0;
    end
    if (WE_mem[addr] == 1'b1 && WE == 1'b1) begin
      data_mem[addr][i] = data_in[i];
    end
  end
end

always @ (ctrl) begin
  for (i = 0; i < (2**m); i = i + 1) begin
    if (ctrl[0] == 1'b1) begin
      RE_mem[i] = 1'b1;
    end else begin
      RE_mem[i] = 1'b0;
    end
    if (ctrl[1] == 1'b1) begin
      WE_mem[i] = 1'b1;
    end else begin
      WE_mem[i] = 1'b0;
    end
  end
end

assign data_out = data_out_reg;

endmodule

