module priority_encoder ( // Given module for 4-bit priority encoder
    input [3:0] in,
    output reg [1:0] pos
);
  always @* begin
    case(in)
      4'b0001: pos = 2'b00;
      4'b0010: pos = 2'b01;
      4'b0100: pos = 2'b10;
      4'b1000: pos = 2'b11;
      default: pos = 2'b00;
    endcase
  end
endmodule

module barrel_shifter ( // Given module for 16-bit barrel shifter
    input wire [15:0] in,
    input wire [3:0] shift_num,
    output wire [15:0] out
); 
  assign out = (shift_num == 4'b0000) ? in :
               (shift_num == 4'b0001) ? in >> 1 :
               (shift_num == 4'b0010) ? in >> 2 :
               (shift_num == 4'b0011) ? in >> 3 :
               (shift_num == 4'b0100) ? in >> 4 :
               (shift_num == 4'b0101) ? in >> 5 :
               (shift_num == 4'b0110) ? in >> 6 :
               (shift_num == 4'b0111) ? in >> 7 :
               (shift_num == 4'b1000) ? in >> 8 :
               (shift_num == 4'b1001) ? in >> 9 :
               (shift_num == 4'b1010) ? in >> 10 :
               (shift_num == 4'b1011) ? in >> 11 :
               (shift_num == 4'b1100) ? in >> 12 :
               (shift_num == 4'b1101) ? in >> 13 :
               (shift_num == 4'b1110) ? in >> 14 :
                                       in >> 15 ;
endmodule

module pulse_generator ( // New module for generating pulse of specific length
    input [1:0] pos, // Input from priority encoder
    output wire [3:0] shift_num // Output specifying the number of shifts to be performed on barrel shifter output
);
  always @* begin
    case(pos)
      2'b00: shift_num = 4'b0000;
      2'b01: shift_num = 4'b0001;
      2'b10: shift_num = 4'b0010;
      2'b11: shift_num = 4'b0011;
      default: shift_num = 4'b0000;
    endcase
  end
endmodule

