    if (reset) begin
        state <= 0;
    end else begin
        case (state)
            0: begin
                // wait for valid input
                if (valid_in) begin
                    // parse input data
                    a[0] <= data_in[3:0];
                    a[1] <= data_in[7:4];
                    a[2] <= data_in[11:8];
                    a[3] <= data_in[15:12];
                    state <= 1;
                end
            end
            1: begin
                // wait for valid input
                if (valid_in) begin
                    // parse input data
                    b[0] <= data_in[3:0];
                    b[1] <= data_in[7:4];
                    b[2] <= data_in[11:8];
                    b[3] <= data_in[15:12];
                    state <= 2;
                end
            end
            2: begin
                // compute dot products
                dot_product[0][0] <= a[0] * b[0];
                dot_product[0][1] <= a[0] * b[1];
                dot_product[0][2] <= a[0] * b[2];
                dot_product[0][3] <= a[0] * b[3];
                dot_product[1][0] <= a[1] * b[0];
                dot_product[1][1] <= a[1] * b[1];
                dot_product[1][2] <= a[1] * b[2];
                dot_product[1][3] <= a[1] * b[3];
                dot_product[2][0] <= a[2] * b[0];
                dot_product[2][1] <= a[2] * b[1];
                dot_product[2][2] <= a[2] * b[2];
                dot_product[2][3] <= a[2] * b[3];
                dot_product[3][0] <= a[3] * b[0];
                dot_product[3][1] <= a[3] * b[1];
                dot_product[3][2] <= a[3] * b[2];
                dot_product[3][3] <= a[3] * b[3];
                state <= 3;
            end
            3: begin
                // compute output matrix
                c[0] <= dot_product[0][0] + dot_product[0][1] + dot_product[0][2] + dot_product[0][3];
                c[1] <= dot_product[1][0] + dot_product[1][1] + dot_product[1][2] + dot_product[1][3];
                c[2] <= dot_product[2][0] + dot_product[2][1] + dot_product[2][2] + dot_product[2][3];
