    wire [3:0] counter_out;

    barrel_shifter barrel_inst (
        .shift(shift),
        .data(data),
        .out(barrel_out)
    );

    counter counter_inst (
        .clk(clk),
        .reset(reset),
        .count(counter_out)
    );

    functional_module func_inst (
        .barrel_out(barrel_out),
        .counter_out(counter_out),
        .sum(q)
    );

endmodule

module DCT_IDCT (
  input [n-1:0] in,
  output [n-1:0] out
);

parameter n = 8; // number of input signals

// DCT block
function [n-1:0] DCT;
  input [n-1:0] x;
  integer k, n;
  begin
    for (k = 0; k < n; k = k + 1) begin
      DCT[k] = 0;
      for (n = 0; n < N; n = n + 1) begin
        DCT[k] = DCT[k] + x[n] * cos((pi/2*N) * (n + 0.5) * k);
      end
      DCT[k] = DCT[k] * sqrt(2/N);
    end
  end
endfunction

// IDCT block
function [n-1:0] IDCT;
  input [n-1:0] C;
  integer k, n;
  begin
    for (n = 0; n < N; n = n + 1) begin
      IDCT[n] = 0;
      for (k = 0; k < n; k = k + 1) begin
        IDCT[n] = IDCT[n] + C[k] * cos((pi/2*N) * (n + 0.5) * k);
      end
      IDCT[n] = IDCT[n] * sqrt(2/N);
    end
  end
endfunction

// Compute DCT coefficients
wire [n-1:0] dct_coeffs;
assign dct_coeffs = DCT(in);

// Compute IDCT coefficients
wire [n-1:0] idct_coeffs;
assign idct_coeffs = IDCT(dct_coeffs);

// Compute output signal
assign out = idct_coeffs;

endmodule

module axi_to_spi
(
    input s00_axi_aclk,
    input s00_axi_aresetn,
    input s00_axi_awvalid,
    output s00_axi_awready,
    input s00_axi_wvalid,
    output s00_axi_wready,
    input [3:0] s00_axi_wstrb,
    input [31:0] s00_axi_wdata,
    output s00_axi_bvalid,
    input s00_axi_bready,
    input s00_axi_arvalid,
    output s00_axi_arready,
    output s00_axi_rvalid,
    input s00_axi_rready,
    output [31:0] s00_axi_rdata,
    output m_spi_ss,
    output m_spi_sclk,
    output m_spi_mosi,
    input m_spi_miso
);

    reg [31:0] axi_write_data;
    reg [31:0] axi_read_data;
    reg [1:0] spi_state;
    reg [4:0] axi_write_pos;
    reg [4:0] axi_read_pos;
    reg [7:0] spi_data;
    reg spi_ss;

    assign s00_axi_rdata = axi_read_data;
    assign s00_axi_awready = 1;
    assign s00_axi_arready = 1;

    always @(posedge s00_axi_aclk) begin
        if (!s00_axi_aresetn) begin
            axi_write_data <= 0;
            axi_read_data <= 0;
            spi_state <= 2'b00;
            axi_write_pos <= 0;
            axi_read_pos <= 0;
            spi_data <= 0;
            spi_ss <= 1;
        end else begin
            if (s00_axi_awvalid && s00_axi_awready) begin
                axi_write_data <= s00_axi_wdata;
                axi_write_pos <= 0;
                spi_state <= 2'b01;
            end else if (s00_axi_wvalid && s00_axi_wready) begin
                axi_write_pos <= axi_write_pos + 1;
                if (axi_write_pos == 15) begin
                    spi_data <= {axi_write_data[15:0], axi_write_data[31:16]};
                    spi_ss <= 0;
                    spi_state <= 2'b10;
                end
            end else if (m_spi_miso) begin
                spi_data <= {spi_data[6:0], m_spi_miso};
                if (spi_state == 2'b10) begin
                    axi_read_data <= {axi_read_data[15:0], spi_data[7:0]};
                    spi_ss <= 1;
                    axi_read_pos <= axi_read_pos + 1;
                    if (axi_read_pos == 7) begin
                        spi_state <= 2'b00;
                    end
                end
            end else if (s00_axi_arvalid && s00_axi_arready) begin
                axi_read_pos <= 0;
                spi_ss <= 1;
                spi_state <= 2'b11;
            end else if (s00_axi_rready && s00_axi_rvalid) begin
                axi_read_pos <= axi_read_pos + 1;
                if (axi_read_pos == 7) begin
                    spi_state <= 2'b00;
                end
            end
        end
    end

    assign s00_axi_bvalid = (s00_axi_awvalid && s00_axi_awready && s00_axi_wvalid && s00_axi_wready && (axi_write_pos == 15));

    assign s00_axi_wready = (spi_state == 2'b01);

    assign s00_axi_rvalid = (s00_axi_arvalid && s00_axi_arready && (spi_state == 2'b11));

    assign s00_axi_arready = (spi_state == 2'b00);

    assign m_spi_ss = spi_ss;
    assign m_spi_sclk = spi_state[0];
    assign m_spi_mosi = spi_data[6];

endmodule

