module single_precision_division
  #(parameter QLE_DEPTH = 4)
  (input [26:0] numerator, denominator,
   output reg [26:0] result);

  // Convert numerator and denominator from single-precision floating-point format to fixed-point format
  reg [26:0] numerator_fixed, denominator_fixed;
  assign numerator_fixed = {1'b0, numerator[22:0]} - {127{1'b0}} - 23;
  assign denominator_fixed = {1'b0, denominator[22:0]} - {127{1'b0}} - 23;

  // Perform fixed-point division using CSA
  wire [13:0] lower_result;
  wire upper_carry;
  wire [12:0] upper_result;
  assign upper_carry = (numerator_fixed[26] ^ denominator_fixed[26]);
  assign upper_result = (numerator_fixed[26] == 1'b1) ? numerator_fixed[26:14] - denominator_fixed[26:14] :
                                                      numerator_fixed[26:14] + denominator_fixed[26:14];
  assign lower_result = numerator_fixed[13:0] - denominator_fixed[13:0] + upper_carry;

  // Refine result using QLE
  wire [QLE_DEPTH-1:0] qle_in;
  wire [QLE_DEPTH-1:0] qle_out;
  assign qle_in[0] = upper_carry;
  assign qle_in[1] = upper_result[12];
  assign qle_in[2] = lower_result[13];
  assign qle_in[3] = lower_result[0];
  qle #(QLE_DEPTH) qle_inst(.in(qle_in), .out(qle_out));
  assign result = {1'b0, qle_out[QLE_DEPTH-1], upper_result[11:0], lower_result[12:1]} + {127{1'b0}} + 23;

endmodule

module qle #(parameter DEPTH = 4)
  (input [DEPTH-1:0] in,
   output reg [DEPTH-1:0] out);

  reg [DEPTH-1:0] pipeline[0:DEPTH-1];
  integer i;

  always @(*) begin
    pipeline[0] = in;
    for (i = 0; i < DEPTH-1; i = i + 1) begin
      pipeline[i+1] = pipeline[i];
    end
  end

  always @(posedge pipeline[0][0]) begin
    out <= pipeline[DEPTH-1];
  end

endmodule

module usb_controller
  (
   input         clk,
   input         reset_n,
   input [15:0]  panel_switches_raw,
   input         rxf_n_raw,
   input         txe_n_raw,
   input [7:0]   data_bus_in_raw,
   output [7:0]  data_bus_out,
   output        rd_n,
   output        wr_n,
   output        data_out_enable,
   output [31:0] chunk_data,
   output [3:0]  chunk_addr,
   output        chunk_write_enable,
   output [3:0]  row_addr,
   output [1:0]  panel_addr,
   output [4:0]  state_out,
   output        panel_select_request       
   );

   wire          rxf_n, txe_n;
   wire          command_write_enable, clear_psr;
   wire [15:0]   panel_switches;
   wire [7:0]    data_bus_in;
   wire [15:0]   command_select;

   // Synchronize panel switches input
   synchronizer #(.WIDTH(16)) panel_sw_sync
     (.clk(clk), .in(panel_switches_raw), .out(panel_switches));

   // Synchronize data bus input
   synchronizer #(.WIDTH(8)) data_bus_input_sync
     (.clk(clk), .in(data_bus_in_raw), .out(data_bus_in));

   // Synchronize rxf_n and txe_n inputs
   synchronizer #(.WIDTH(2)) rx_tx_sync
     (.clk(clk), .in({rxf_n_raw, txe_n_raw}), .out({rxf_n, txe_n}));

   // Instantiate USB sequencer
   usb_sequencer seq
     (.clk(clk), 
      .reset_n(reset_n), 
      .rxf_n(rxf_n), 
      .txe_n(txe_n),
      .panel_select_request(panel_select_request),
      .panel_switches(panel_switches),
      .data_out(data_bus_out),
      .rd_n(rd_n),
      .wr_n(wr_n),
      .data_out_enable(data_out_enable),
      .command_write_enable(command_write_enable),
      .clear_psr(clear_psr),
      .state_out(state_out));

   // Instantiate command decoder
   decoder #(.WIDTH(4)) command_decoder
     (.addr(data_bus_in[7:4]), .y(command_select));

   // Instantiate panel select request register
   jk_flipflop panel_select_request_register
     (.clk(clk),
      .reset_n(reset_n),
      .j(command_select[1] & command_write_enable),
      .k(clear_psr),
      .q(panel_select_request));

   // Instantiate panel address command register
   register_with_write_enable #(.WIDTH(2)) panel_addr_command_register
     (.clk(clk),
      .reset_n(reset_n),
      .write_enable(command_select[2] & command_write_enable),
      .d(data_bus_in[1:0]),
      .q(panel_addr));

   // Instantiate row address command register
   register_with_write_enable #(.WIDTH(4)) row_addr_command_register
     (.clk(clk),
      .reset_n(reset_n),
      .write_enable(command_select[3] & command_write_enable),
      .d(data_bus_in[3:0]),
      .q(row_addr));

   // Instantiate chunk address command register
   register_with_write_enable #(.WIDTH(4)) chunk_addr_command_register
     (.clk(clk),
      .reset_n(reset_n),
      .write_enable(command_select[4] & command_write_enable),
      .d(data_bus_in[3:0]),
      .q(chunk_addr));

   // Instantiate nibble registers
   genvar        i;
   generate
      for (i=0; i<8; i=i+1)
        begin : nibble_registers
           register_with_write_enable #(.WIDTH(4)) nibble_register
             (.clk(clk), 
              .reset_n(reset_n), 
              .write_enable(command_select[i+5] & command_write_enable),
              .d(data_bus_in[3:0]),
              .q(chunk_data[4*i+3:4*i]));
        end
   endgenerate

   // Assign chunk write enable
   assign chunk_write_enable = command_select[13] & command_write_enable;

endmodule

module multiplier(
  input [31:0] a,
  input [31:0] b,
  output reg [63:0] product
);

  wire [31:0] a_bits [0:31];
  wire [31:0] b_bits [0:31];
  wire [31:0] partial_products [0:31][0:31];
  wire [31:0] carry [0:31][0:31];
  wire [31:0] sum [0:31][0:31];
  wire [2:0] parity [0:31];
  wire [31:0] reverse [0:31];

  // Split inputs into individual bits
  genvar i;
  generate
    for (i = 0; i < 32; i = i + 1) begin : a_bits_gen
      assign a_bits[i] = a[i];
    end
    for (i = 0; i < 32; i = i + 1) begin : b_bits_gen
      assign b_bits[i] = b[i];
    end
  endgenerate

  // Generate partial products
  genvar j, k;
  generate
    for (j = 0; j < 32; j = j + 1) begin : partial_products_gen
      for (k = 0; k < 32; k = k + 1) begin : partial_products_gen2
        assign partial_products[j][k] = a_bits[j] & b_bits[k];
      end
    end
  endgenerate

  // Generate carry and sum arrays for adder
  genvar m, n;
  generate
    for (m = 0; m < 32; m = m + 1) begin : carry_gen
      for (n = 0; n < 32; n = n + 1) begin : carry_gen2
        if (n == 0) begin
          assign carry[m][n] = 1'b0;
        end else if (n == 1) begin
          assign carry[m][n] = partial_products[m][n-1] | (a_bits[m] & b_bits[n-1]);
        end else begin
          assign carry[m][n] = (partial_products[m][n-1] & carry[m][n-1]) | (a_bits[m] & b_bits[n-1]);
        end
      end
    end
    for (m = 0; m < 32; m = m + 1) begin : sum_gen
      for (n = 0; n < 32; n = n + 1) begin : sum_gen2
        if (n == 0) begin
          assign sum[m][n] = partial_products[m][n] ^ (a_bits[m] & b_bits[n]);
        end else begin
          assign sum[m][n] = partial_products[m][n] ^ carry[m][n];
        end
      end
    end
  endgenerate

  // Generate parity and reverse arrays for reverse and parity module
  genvar p;
  generate
    for (p = 0; p < 32; p = p + 1) begin : parity_gen
      assign parity[p] = {sum[p][0], sum[p][1], sum[p][2]} ^ {sum[p][3], sum[p][4], sum[p][5]} ^ {sum[p][6], sum[p][7], sum[p][8]} ^ {sum[p][9], sum[p][10], sum[p][11]} ^ {sum[p][12], sum[p][13], sum[p][14]} ^ {sum[p][15], sum[p][16], sum[p][17]} ^ {sum[p][18], sum[p][19], sum[p][20]} ^ {sum[p][21], sum[p][22], sum[p][23]} ^ {sum[p][24], sum[p][25], sum[p][26]} ^ {sum[p][27], sum[p][28], sum[p][29]} ^ {sum[p][30], sum[p][31], 1'b0};
      assign reverse[p] = {sum[p][31], sum[p][30], sum[p][29], sum[p][28], sum[p][27], sum[p][26], sum[p][25], sum[p][24], sum[p][23], sum[p][22], sum[p][21], sum[p][20], sum[p][19], sum[p][18], sum[p][17], sum[p][16], sum[p][15], sum[p][14], sum[p][13], sum[p][12], sum[p][11], sum[p][10], sum[p][9], sum[p][8], sum[p][7], sum[p][6], sum[p][5], sum[p][4], sum[p][3], sum[p][2], sum[p][1], sum[p][0]};
    end
  endgenerate

  // Generate final product using adder and reverse and parity modules
  genvar q, r;
  generate
    for (q = 0; q < 32; q = q + 1) begin : product_gen
      for (r = 0; r < 32; r = r + 1) begin : product_gen2
        if (r == 0) begin
          carry_lookahead_adder adder(.a(sum[q][r]), .b(reverse[r]), .carry_in(1'b0), .sum_out(product[q+r]));
        end else begin
          carry_lookahead_adder adder(.a(sum[q][r]), .b(reverse[r]), .carry_in(carry[q][r-1]), .sum_out(product[q+r]));
        end
      end
    end
  endgenerate

endmodule

module pll_system (
    inclk0,
    c1,
    c4,
    locked
);

