    inclk1 <= ~inclk1;
    count1 <= count1 + 1;
    if (count1 == MAX_COUNT1) begin
        inclk2 <= ~inclk2;
        count1 <= 0;
        count2 <= count2 + 1;
    end
    if (count2 == MAX_COUNT2) begin
        inclk3 <= ~inclk3;
        count2 <= 0;
        count3 <= count3 + 1;
    end
    if (count3 == MAX_COUNT3) begin
        locked <= 1;
    end
end

