module uart_echo (
    input wire RX,
    input wire RESET_IN,
    output wire TX
);

reg [7:0] rx_buffer [0:127];
reg [6:0] buffer_head = 0;
reg [6:0] buffer_tail = 0;
reg [6:0] buffer_count = 0;
reg [7:0] data_byte;
reg rx_idle = 1'b1;
reg [3:0] bit_count = 4'b0;
reg [3:0] baud_count = 4'b0;
reg tx_idle = 1'b1;
reg [7:0] tx_byte;
reg [3:0] tx_bit_count = 4'b0;

parameter BAUD_RATE = 115200;
parameter BAUD_COUNT = $floor(50000000/BAUD_RATE);

always @(posedge RESET_IN) begin
    if (RESET_IN) begin
        buffer_head <= 7'b0;
        buffer_tail <= 7'b0;
        buffer_count <= 7'b0;
        rx_idle <= 1'b1;
        bit_count <= 4'b0;
        baud_count <= 4'b0;
        tx_idle <= 1'b1;
        tx_bit_count <= 4'b0;
    end
end

always @(posedge RX) begin
    if (rx_idle && !RX) begin
        data_byte <= 8'b0;
        bit_count <= 4'b0;
        baud_count <= 4'b0;
        rx_idle <= 1'b0;
    end else if (!rx_idle) begin
        baud_count <= baud_count + 1'b1;
        if (baud_count == BAUD_COUNT) begin
            baud_count <= 4'b0;
            data_byte[bit_count] <= RX;
            bit_count <= bit_count + 1'b1;
            if (bit_count == 8) begin
                if (buffer_count < 128) begin
                    rx_buffer[buffer_head] <= data_byte;
                    buffer_head <= buffer_head + 1;
                    if (buffer_head == 128) begin
                        buffer_head <= 7'b0;
                    end
                    buffer_count <= buffer_count + 1;
                end
                rx_idle <= 1'b1;
            end
        end
    end
end

always @(posedge CLK) begin
    if (tx_idle && buffer_count > 0) begin
        tx_byte <= rx_buffer[buffer_tail];
        buffer_tail <= buffer_tail + 1;
        if (buffer_tail == 128) begin
            buffer_tail <= 7'b0;
        end
        buffer_count <= buffer_count - 1;
        tx_bit_count <= 4'b0;
        tx_idle <= 1'b0;
    end else if (!tx_idle) begin
        baud_count <= baud_count + 1'b1;
        if (baud_count == BAUD_COUNT) begin
            baud_count <= 4'b0;
            TX <= tx_byte[tx_bit_count];
