    full_adder fa1(.a(a[0]), .b(b[0]), .c(c), .sum(s[0]), .cout(c1));

    // Second full adder
    full_adder fa2(.a(a[1]), .b(b[1]), .c(c1), .sum(s[1]), .cout(c2));

    // Third full adder
    full_adder fa3(.a(a[2]), .b(b[2]), .c(c2), .sum(s[2]), .cout(c3));

    // Fourth full adder
    full_adder fa4(.a(a[3]), .b(b[3]), .c(c3), .sum(s[3]), .cout(cout));

    assign sum = s;

endmodule

module full_adder (
    input a, b, c, // Binary inputs
    output sum, // Sum output
    output cout // Carry-out
);

