module POR (
  input vdd,
  input rst_n,
  input rst_delay,
  output reg rst
);

parameter t_pulse = 100; // reset pulse duration (ns)
parameter t_delay = 100; // reset delay time (ns)

reg [1:0] state; // state machine variable

// Define voltage threshold
parameter VTHRESH = 1.2;

// State machine states
parameter IDLE = 2'b00;
parameter RESET = 2'b01;
parameter DELAY = 2'b10;

// State machine logic
always @(posedge vdd or negedge rst_n) begin
  if (rst_n == 0) begin
    state <= IDLE;
  end else begin
    case (state)
      IDLE: begin
        if (vdd > VTHRESH) begin
          state <= RESET;
        end
      end
      RESET: begin
        rst <= 0;
        if (rst_n == 0) begin
          state <= IDLE;
        end else begin
          state <= DELAY;
        end
      end
      DELAY: begin
        if (rst_delay == 1) begin
          state <= IDLE;
          rst <= 1;
        end
      end
    endcase
  end
end

// Pulse duration timer
always @(posedge vdd or negedge rst_n) begin
  if (rst_n == 0) begin
    rst <= 1;
  end else begin
    if (state == RESET) begin
      #t_pulse rst <= 1;
    end
  end
end

endmodule

module lvds_transmitter (
    input clk,
    input enable,
    input [channel_width-1:0] datain,
    output dataout,
    output serialfdbkout
);

    parameter bypass_serializer = 0;
    parameter invert_clock = 0;
    parameter use_falling_clock_edge = 0;
    parameter use_serial_data_input = 0;
    parameter use_post_dpa_serial_data_input = 0;
    parameter enable_dpaclk_to_lvdsout = "off";
    parameter preemphasis_setting = 0;
    parameter vod_setting = 0;
    parameter differential_drive = 0;

    input devclrn;
    input devpor;
    input dpaclkin;

    wire [channel_width-1:0] input_data;
    wire [channel_width-1:0] shift_data;
    wire shift_out;
    wire dataout_tmp;
    reg clk_last_value;

    wire bypass_mode;
    wire serial_din_mode;
    wire postdpa_serial_din_mode;
    wire enable_dpaclk_to_lvdsout_signal;

    integer i;

    assign serial_din_mode = (use_serial_data_input == 1) ? 1'b1 : 1'b0;
    assign postdpa_serial_din_mode = (use_post_dpa_serial_data_input == 1) ? 1'b1 : 1'b0;
    assign enable_dpaclk_to_lvdsout_signal = (enable_dpaclk_to_lvdsout == "on") ? 1'b1 : 1'b0;

    buf (clk_in, clk);
    buf datain_buf [channel_width-1:0] (datain_in, datain);

    // Parallel to serial conversion
    always @ (posedge clk_in or negedge devclrn or negedge devpor) begin
        if (~devclrn || ~devpor) begin
            shift_data <= 'b0;
        end else begin
            if (bypass_serializer == 1) begin
                shift_data <= input_data;
            end else begin
                shift_data <= {shift_data[channel_width-2:0], input_data[channel_width-1]};
            end
        end
    end

    // Data input delay
    always @ (posedge clk_in or negedge devclrn or negedge devpor) begin
        if (~devclrn || ~devpor) begin
            input_data <= 'b0;
        end else begin
            input_data <= #1 datain_in;
        end
    end

    // LVDS output
    always @ (posedge clk_in or negedge devclrn or negedge devpor) begin
        if (~devclrn || ~devpor) begin
            dataout_tmp <= 1'b0;
        end else begin
            if (serial_din_mode) begin
                dataout_tmp <= serialdatain;
            end else if (postdpa_serial_din_mode) begin
                dataout_tmp <= postdpaserialdatain;
            end else if (enable_dpaclk_to_lvdsout_signal) begin
                dataout_tmp <= dpaclkin;
            end else begin
                dataout_tmp <= shift_out;
            end
        end
    end

    // Serial feedback output
    always @ (posedge clk_in or negedge devclrn or negedge devpor) begin
        if (~devclrn || ~devpor) begin
            serialfdbkout <= 1'b0;
        end else begin
            serialfdbkout <= dataout_tmp;
        end
    end

    // Output data
    assign dataout = dataout_tmp;

endmodule

