module LoopFilter (
  input control_voltage,
  output reg filtered_voltage
);

integer i;

always @(posedge control_voltage) begin
  for (i = 0; i < 10; i = i + 1) begin
    filtered_voltage <= filtered_voltage + (control_voltage >> i);
  end
end

endmodule

module Divider (
  input clk_in,
  input freq_mult,
  input phase_shift,
  output reg clk_out
);

integer counter;

always @(posedge clk_in) begin
  counter <= counter + 1;
  if (counter >= freq_mult + phase_shift) begin
    clk_out <= ~clk_out;
    counter <= 0;
  end
end

endmodule

