module video_vga(

    input wire clk,
    input wire hsync_start,
    input wire scanin_start,
    input wire [5:0] pix_in,
    input wire scanout_start,
    output reg [5:0] pix_out
);

reg [9:0] ptr_in;  // count up to 720
reg [9:0] ptr_out; //

reg wr_stb;

wire [7:0] data_out;

reg [1:0] page_select;

// calculate the number of pixels per line
parameter NUM_PIXELS_PER_LINE = 800;
parameter NUM_ACTIVE_PIXELS_PER_LINE = 640;
parameter NUM_FRONT_PORCH_PIXELS = 16;
parameter NUM_SYNC_PIXELS = 96;
parameter NUM_BACK_PORCH_PIXELS = 48;

// calculate the number of lines per frame
parameter NUM_LINES_PER_FRAME = 525;
parameter NUM_ACTIVE_LINES_PER_FRAME = 480;
parameter NUM_FRONT_PORCH_LINES = 10;
parameter NUM_SYNC_LINES = 2;
parameter NUM_BACK_PORCH_LINES = 33;

// calculate the number of clock cycles per pixel
parameter NUM_CLOCK_CYCLES_PER_PIXEL = 1;

// calculate the number of clock cycles per line
parameter NUM_CLOCK_CYCLES_PER_LINE = NUM_PIXELS_PER_LINE * NUM_CLOCK_CYCLES_PER_PIXEL;

// calculate the number of clock cycles per frame
parameter NUM_CLOCK_CYCLES_PER_FRAME = NUM_LINES_PER_FRAME * NUM_CLOCK_CYCLES_PER_LINE;

// calculate the number of pixels per page
parameter NUM_PIXELS_PER_PAGE = 1536;

// calculate the number of pages
parameter NUM_PAGES = (NUM_ACTIVE_PIXELS_PER_LINE * NUM_ACTIVE_LINES_PER_FRAME) / NUM_PIXELS_PER_PAGE;

// calculate the number of pixels per row on a page
parameter NUM_PIXELS_PER_ROW = NUM_ACTIVE_PIXELS_PER_LINE / 2;

// calculate the number of rows per page
parameter NUM_ROWS_PER_PAGE = NUM_PIXELS_PER_PAGE / NUM_PIXELS_PER_ROW;

// write ptr and strobe
always @(posedge clk)
begin
    if (scanin_start)
    begin
        ptr_in <= 0;
        page_select <= 0;
    end
    else
    begin
        if (ptr_in < NUM_ACTIVE_PIXELS_PER_LINE)
        begin
            wr_stb <= 1;
            ptr_in <= ptr_in + 1;
        end
        else
        begin
            wr_stb <= 0;
        end

        if (ptr_in == NUM_ACTIVE_PIXELS_PER_LINE + NUM_FRONT_PORCH_PIXELS + NUM_SYNC_PIXELS + NUM_BACK_PORCH_PIXELS - 1)
        begin
            if (page_select == 0)
            begin
                page_select <= 1;
            end
            else
            begin
                page_select <= 0;
            end
        end
    end
end

// read ptr
always @(posedge clk)
begin
    if (scanout_start)
    begin
        ptr_out <= 0;
    end
    else
    begin
        if (ptr_out < NUM_ACTIVE_PIXELS_PER_LINE)
        begin
            ptr_out <= ptr_out + 1;
        end
    end
end

// read data
always @(posedge clk)
begin
    if (ptr_out < NUM_ACTIVE_PIXELS_PER_LINE)
    begin
        pix_out <= data_out[5:0];
    end
    else
    begin
        pix_out <= 0;
    end
end

// memory for storing the pixel data
mem1536 line_buf(
    .clk(clk),
    .wraddr({ptr_in[NUM_ROWS_PER_PAGE-1:0], page_select, ptr_in[NUM_PIXELS_PER_ROW-1:0]}),
    .wrdata({2'b00, pix_in}),
    .wr_stb(wr_stb),
    .rdaddr({ptr_out[NUM_ROWS_PER_PAGE-1:0], ~page_select, ptr_out[NUM_PIXELS_PER_ROW-1:0]}),
    .rddata(data_out)
);

endmodule

