module float_mult (
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] product
);

    reg [31:0] a_mantissa, b_mantissa, product_mantissa;
    reg [7:0] a_exponent, b_exponent, product_exponent;
    reg a_sign, b_sign, product_sign;
    reg [31:0] a_shifted, b_shifted;
    reg [63:0] product_intermediate;

    assign {product_sign, product_exponent, product_mantissa} = {a_sign ^ b_sign, a_exponent + b_exponent - 127, product_intermediate[54:23]};

    always @(*) begin
        a_sign = a[31];
        b_sign = b[31];
        a_exponent = a[30:23];
        b_exponent = b[30:23];
        a_mantissa = a[22:0];
        b_mantissa = b[22:0];

        a_shifted = {1'b1, a_mantissa} << 1;
        b_shifted = {1'b1, b_mantissa} << 1;

        product_intermediate = a_shifted * b_shifted;
        product_mantissa = product_intermediate[53:22];
    end

endmodule

module data_source_manager(
  input clk, reset, busy,
  input [31:0] src1,
  input src1_valid,
  input [31:0] src2,
  input src2_valid,
  input [31:0] ex_rslt1,
  input [4:0] ex_dst1,
  input kill_spec1,
  input [31:0] ex_rslt2,
  input [4:0] ex_dst2,
  input kill_spec2,
  output reg [31:0] src1_out,
  output reg [31:0] src2_out,
  output reg src1_valid_out,
  output reg src2_valid_out,
  output reg speculative
);

  reg [31:0] next_src1_out;
  reg [31:0] next_src2_out;
  reg next_src1_valid_out;
  reg next_src2_valid_out;
  reg next_speculative;

  always @(posedge clk) begin
    if (reset) begin
      src1_out <= 0;
      src2_out <= 0;
      src1_valid_out <= 0;
      src2_valid_out <= 0;
      speculative <= 0;
    end else if (busy) begin
      // check for kill signals
      if (kill_spec1 || kill_spec2) begin
        src1_out <= 0;
        src2_out <= 0;
        src1_valid_out <= 0;
        src2_valid_out <= 0;
      end else begin
        // both sources are valid
        if (src1_valid && src2_valid) begin
          next_src1_out <= src1;
          next_src2_out <= src2;
          next_src1_valid_out <= 1;
          next_src2_valid_out <= 1;
        // only source 1 is valid
        end else if (src1_valid) begin
          next_src1_out <= src1;
          next_src2_out <= 0;
          next_src1_valid_out <= 1;
          next_src2_valid_out <= 0;
        // only source 2 is valid
        end else if (src2_valid) begin
          next_src1_out <= 0;
          next_src2_out <= src2;
          next_src1_valid_out <= 0;
          next_src2_valid_out <= 1;
        // neither source is valid
        end else begin
          next_src1_out <= 0;
          next_src2_out <= 0;
          next_src1_valid_out <= 0;
          next_src2_valid_out <= 0;
        end
        // check if speculative execution is enabled
        if (speculative) begin
          next_speculative <= 1;
        end else begin
          next_speculative <= 0;
        end
      end
    end else begin
      src1_out <= 0;
      src2_out <= 0;
      src1_valid_out <= 0;
      src2_valid_out <= 0;
      speculative <= 0;
    end
  end

  always @(posedge clk) begin
    if (reset) begin
      src1_out <= 0;
      src2_out <= 0;
      src1_valid_out <= 0;
      src2_valid_out <= 0;
      speculative <= 0;
    end else begin
      src1_out <= next_src1_out;
      src2_out <= next_src2_out;
      src1_valid_out <= next_src1_valid_out;
      src2_valid_out <= next_src2_valid_out;
      speculative <= next_speculative;
    end
  end

endmodule

