module mux2to1 (
    input A0,
    input A1,
    input S,
    output Y,
    input VPWR,
    input VGND,
    input VPB,
    input VNB
);
    // Local signals
    wire not_S;
    wire A0_and_not_S;
    wire A1_and_S;
    wire Y_buf;

