module barrel_shifter(
    input [15:0] data_in,
    input [4:0] shift_amt,
    input shift_left,
    input shift_right,
    input load,
    output [15:0] data_out
);

reg [15:0] data_reg;

always @ (posedge shift_left or posedge shift_right or posedge load) begin
    if (load) begin
        data_reg <= data_in;
    end else if (shift_left) begin
        data_reg <= data_reg << shift_amt;
    end else if (shift_right) begin
        data_reg <= data_reg >> shift_amt;
    end
end

assign data_out = data_reg;

endmodule

