    input reset,
    input [15:0] data,
    input [4:0] shift_amt,
    input select,
    output [7:0] q
);

wire [15:0] shifted_data;
wire [7:0] lower_byte;
wire [7:0] upper_byte;
wire [7:0] xor_output;

barrel_shifter barrel_shifter_inst(
    .data_in(data),
    .shift_amt(shift_amt),
    .shift_left(select == 1'b1),
    .shift_right(select == 1'b0),
    .load(select == 2'b10),
    .data_out(shifted_data)
);

splitter splitter_inst(
    .data_in(shifted_data),
    .lower_byte(lower_byte),
    .upper_byte(upper_byte)
);

xor_module xor_inst(
    .a(lower_byte),
    .b(upper_byte),
    .c(xor_output)
);

always @ (posedge clk) begin
    if (reset) begin
        q <= 8'b0;
    end else begin
        case (select)
            2'b00: q <= xor_output;
            2'b01: q <= {upper_byte, lower_byte};
            2'b10: q <= shifted_data;
            default: q <= 8'b0;
        endcase
    end
end

endmodule

module SPI_SLAVE#
    (
    parameter integer m = 15 // Data packet size
    )
    (
    input wire RST,
    input wire GCLK,
    input wire SCLK,
    output wire MISO,
    input wire MOSI,
    input wire SS,
    input wire [m-1:0] DIN,
    output reg [m-1:0] DOUT
    );

    reg [m-1:0] RXSHIFT = 0;
    reg [m-1:0] TXSHIFT = 0;
    reg in_progress = 1'b0;

    assign MISO = TXSHIFT[m-1];

    wire foo;
    assign foo = SCLK | SS;    
    always @(negedge foo) begin
        if (in_progress == 1'b1) begin
            TXSHIFT <= TXSHIFT<<1;
        end
        else begin
            TXSHIFT <= DIN;
        end
    end

    always @(posedge GCLK) begin
        in_progress <= (SS == 1'b1) ? 1'b0 : 1'b1;
    end

    always @(posedge SS) begin
        DOUT <= (RST == 1'b1) ? 0 : RXSHIFT;
    end

    always @(posedge SCLK) begin
        RXSHIFT <= (SS == 1'b1) ? 0 : RXSHIFT<<1 | MOSI;
    end
endmodule

