    wire [15:0] adder2_cout;

    add16 adder1(.a(in1), .b(in2), .cin(1'b0), .sum(adder1_out), .cout(adder1_cout));
    add16 adder2(.a(adder1_out), .b(in2), .cin(adder1_cout), .sum(adder2_out), .cout(adder2_cout));

    always @ (posedge clk) begin
