module tone_generator (
  input clk,
  input ctrl,
  output reg [7:0] tone
);

parameter f = 1000; // frequency of the tone
parameter t = 100; // duration of the tone
parameter type = "sine"; // type of the tone (DTMF, sine wave, square wave, etc.)

reg [31:0] phase_accumulator;
reg [7:0] amplitude;

always @(posedge clk) begin
  if (ctrl) begin
    phase_accumulator <= phase_accumulator + (f << 32) / 50000000;
    case (type)
      "sine": amplitude <= $sin(phase_accumulator[31:24]);
      "square": amplitude <= (phase_accumulator[31]) ? 8'hFF : 8'h00;
      "dtmf": amplitude <= $signed({4'b0001, 4'b0010, 4'b0100, 4'b1000} * $signed({1'b1, 1'b1, 1'b1, ctrl}));
      default: amplitude <= 8'h00;
    endcase
    tone <= amplitude;
  end else begin
    tone <= 8'h00;
  end
end

always @(posedge clk) begin
  if (ctrl && (phase_accumulator >= (f << 32) * t / 1000)) begin
    phase_accumulator <= 0;
  end
end

endmodule

