module clock_generator(
    input clk,
    output reg cen_3p57,
    output reg cen_1p78
);

wire [10:0] step=11'd105;
wire [10:0] lim =11'd1408;
wire [10:0] absmax = lim+step;

reg  [10:0] cencnt=11'd0;
reg  [10:0] next;
reg  [10:0] next2;

reg alt=1'b0;

always @(*) begin
    next  = cencnt+11'd105;
    next2 = next-lim;
end

always @(posedge clk) begin
    cen_3p57 <= 1'b0;
    cen_1p78 <= 1'b0;
    if( cencnt >= absmax ) begin
        cencnt <= 11'd0;
        alt    <= 1'b0;
    end else
    if( next >= lim ) begin
        cencnt <= next2;
        cen_3p57 <= 1'b1;
        alt    <= ~alt;
        if( alt ) cen_1p78 <= 1'b1;
    end else begin
        cencnt <= next;
    end
end

endmodule

module Adler (
  input [n-1:0] in,
  input rst,
  input en,
  output reg [15:0] out
);

parameter n = 8; // number of input signals
parameter m = 1; // number of output signals

// additional parameters for the Adler checksum algorithm
parameter A_INIT = 1;
parameter B_INIT = 0;
parameter MODULO = 65521;
parameter CHUNK_SIZE = 8; 

// internal signals and variables
reg [7:0] data_chunk;
reg [15:0] a_reg, b_reg;
reg [15:0] checksum_reg;
wire valid;

// implementation of Adler checksum generator and checker
always @ (posedge en) begin
  if (rst) begin
    a_reg <= A_INIT;
    b_reg <= B_INIT;
    checksum_reg <= 0;
  end else begin
    data_chunk <= {in};
    a_reg <= (a_reg + data_chunk) % MODULO;
    b_reg <= (b_reg + a_reg) % MODULO;
    checksum_reg <= {a_reg, b_reg};
  end
end

assign valid = (checksum_reg == out);

endmodule

module top_module(
    input clk,
    input reset, // Synchronous active-high reset
    input load,
    input ena,
    input [3:0] data,
    output [7:0] q
);

reg [3:0] counter;
reg [3:0] shift_reg;
reg [3:0] shift_reg_next;

always @(posedge clk) begin
    if (reset) begin
        counter <= 4'b0;
        shift_reg <= 4'b0;
    end else begin
        counter <= counter + 1;
        shift_reg <= ena ? shift_reg_next : shift_reg;
    end
end

always @(*) begin
    case (load)
        1'b0: shift_reg_next = {shift_reg[2:0], data};
        1'b1: shift_reg_next = data;
    endcase
end

assign q = {counter, shift_reg} + 8'b0;

endmodule

