module wb_semaphore 
  #(parameter count=8, DBUS_WIDTH=32)
    (input wb_clk_i,
     input wb_rst_i,
     input [DBUS_WIDTH-1:0] wb_dat_i,
     input [2:0] wb_adr_i,
     input wb_cyc_i,
     input wb_stb_i,
     input wb_we_i,
     output wb_ack_o,
     output [DBUS_WIDTH-1:0] wb_dat_o);

   reg [count-1:0] locked;

   always @(posedge wb_clk_i)
     if(wb_rst_i)
       locked <= {count{1'b0}};
     else if(wb_stb_i)
       if(wb_we_i)
	 locked[wb_adr_i] <= 1'b0;
       else
	 locked[wb_adr_i] <= 1'b1;

   assign 	   wb_dat_o[DBUS_WIDTH-1:1] = {(DBUS_WIDTH-1){1'b0}};
   assign 	   wb_dat_o[0] = locked[wb_adr_i];
   assign 	   wb_ack_o = wb_stb_i && !wb_we_i && (locked[wb_adr_i] || !wb_cyc_i);

endmodule

module top_module (
    input clk,
    input reset,            // Synchronous reset
    input [31:0] in,
    output [31:0] out,
    output [7:0] q,
    output or_out,
    output [31:0] and_out
);

    // Module 1: Detect changes in input vector
    reg [31:0] prev_in;
    reg [31:0] out_reg;
    always @(posedge clk) begin
        if (reset) begin
            prev_in <= 0;
            out_reg <= 0;
        end else begin
            prev_in <= in;
            out_reg <= out_reg | (in & ~prev_in);
        end
    end
    assign out = out_reg;

    // Module 2: 8 D flip-flops with active high asynchronous reset
    reg [7:0] dff;
    always @(negedge clk or posedge reset) begin
        if (reset) begin
            dff <= 0;
        end else begin
            dff <= {dff[6:0], in[0]};
        end
    end
    assign q = dff;

    // 9th DFF that outputs the logical OR of all 8 DFF outputs
    reg or_reg;
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            or_reg <= 0;
        end else begin
            or_reg <= |dff;
        end
    end
    assign or_out = or_reg;

    // Additional functional module that outputs the bitwise AND of the two vectors
    assign and_out = out & {8{or_out}};

endmodule

module fsm_4bit_counter (
  input clk,
  input reset,
  input enable,
  output reg [3:0] count,
  output reg valid
);

  parameter IDLE = 2'b00;
  parameter COUNT_UP = 2'b01;
  parameter COUNT_DOWN = 2'b10;
  parameter DONE = 2'b11;

  reg [1:0] state;

  always @(posedge clk) begin
    if (reset) begin
      state <= IDLE;
      count <= 4'b0000;
      valid <= 0;
    end
    else begin
      case (state)
        IDLE: begin
          count <= 4'b0000;
          valid <= 0;
          if (enable) begin
            if (count == 4'b1111) begin
              state <= DONE;
            end
            else begin
              state <= COUNT_UP;
            end
          end
        end

        COUNT_UP: begin
          count <= count + 1;
          valid <= 0;
          if (count == 4'b1111) begin
            state <= DONE;
          end
          else if (!enable) begin
            state <= IDLE;
          end
        end

        COUNT_DOWN: begin
          count <= count - 1;
          valid <= 0;
          if (count == 4'b0000) begin
            state <= DONE;
          end
          else if (!enable) begin
            state <= IDLE;
          end
        end

        DONE: begin
          valid <= 1;
          if (enable) begin
            if (count == 4'b1111) begin
              state <= COUNT_DOWN;
            end
            else begin
              state <= COUNT_UP;
            end
          end
          else begin
            state <= IDLE;
          end
        end
      endcase
    end
  end

endmodule

module uart_state_machine(
    input clk,
    input reset,
    input start,
    input [7:0] data_in,
    input rx,
    output [7:0] data_out,
    output tx
);

// Define the states of the state machine
parameter IDLE_STATE = 2'b00;
parameter TRANSMIT_STATE = 2'b01;
parameter RECEIVE_STATE = 2'b10;

// Define the serial communication protocol
parameter START_BIT = 1'b0;
parameter STOP_BIT = 1'b1;
parameter DATA_BITS = 8;

// Define the state register and next state logic
reg [1:0] state_reg, state_next;

// Define the data register and data counter
reg [7:0] data_reg;
reg [2:0] data_counter;

// Define the TX and RX registers
reg tx_reg, rx_reg;

// Assign the initial state to the state register
always @(posedge clk, posedge reset) begin
    if (reset) begin
        state_reg <= IDLE_STATE;
        data_reg <= 0;
        data_counter <= 0;
        tx_reg <= 1;
        rx_reg <= 1;
    end else begin
        state_reg <= state_next;
    end
end

// Define the next state logic
always @(*) begin
    case (state_reg)
        IDLE_STATE: begin
            if (start) begin
                state_next = TRANSMIT_STATE;
            end else begin
                state_next = IDLE_STATE;
            end
        end
        TRANSMIT_STATE: begin
            if (data_counter < DATA_BITS) begin
                tx_reg = data_in[data_counter];
                data_counter = data_counter + 1;
                state_next = TRANSMIT_STATE;
            end else begin
                tx_reg = STOP_BIT;
                data_counter = 0;
                state_next = RECEIVE_STATE;
            end
        end
        RECEIVE_STATE: begin
            if (rx_reg == START_BIT) begin
                data_counter = 0;
                state_next = RECEIVE_STATE;
            end else if (data_counter < DATA_BITS) begin
                data_reg[data_counter] = rx_reg;
                data_counter = data_counter + 1;
                state_next = RECEIVE_STATE;
            end else if (rx_reg == STOP_BIT) begin
                data_out = data_reg;
                state_next = IDLE_STATE;
            end else begin
                state_next = RECEIVE_STATE;
            end
        end
        default: begin
            state_next = IDLE_STATE;
        end
    endcase
end

// Define the TX and RX output logic
assign tx = tx_reg;
assign rx_reg = rx;

endmodule

module matrix_multiplier(
    input clk,
    input reset,
    input [15:0] matrix1,
    input [15:0] matrix2,
    output [15:0] result
);

reg [15:0] temp[3:0];

always @(posedge clk) begin
    if (reset) begin
        temp[0] <= 0;
        temp[1] <= 0;
        temp[2] <= 0;
        temp[3] <= 0;
    end else begin
        temp[0] <= matrix1[3:0] * matrix2[0] + matrix1[7:4] * matrix2[4] + matrix1[11:8] * matrix2[8] + matrix1[15:12] * matrix2[12];
        temp[1] <= matrix1[3:0] * matrix2[1] + matrix1[7:4] * matrix2[5] + matrix1[11:8] * matrix2[9] + matrix1[15:12] * matrix2[13];
        temp[2] <= matrix1[3:0] * matrix2[2] + matrix1[7:4] * matrix2[6] + matrix1[11:8] * matrix2[10] + matrix1[15:12] * matrix2[14];
        temp[3] <= matrix1[3:0] * matrix2[3] + matrix1[7:4] * matrix2[7] + matrix1[11:8] * matrix2[11] + matrix1[15:12] * matrix2[15];
    end
end

assign result = {temp[3], temp[2], temp[1], temp[0]};

endmodule

module dual_edge_ff (
    input clk,
    input d,
    output q
);

reg q1, q2;

// First D flip-flop captures data on rising edge of clock
always @(posedge clk) begin
    q1 <= d;
end

// Second D flip-flop captures output of first flip-flop on falling edge of clock
always @(negedge clk) begin
    q2 <= q1;
end

// Output of second flip-flop is the output of the module
assign q = q2;

endmodule

module adder_subtractor (
    input        clk,
    input        clr,
    input  [3:0] A,
    input  [3:0] B,
    input        sub,
    output [3:0] Y
);

    reg [3:0] temp;

    always @(posedge clk)
        if (clr) temp <= 4'b0;
        else if (sub) temp <= A - B;
        else temp <= A + B;

    assign Y = temp;

endmodule

module top_module (
    input clk,
    input reset,       // Synchronous active-high reset
    input [31:0] a, b, // Inputs to the adder
    output [31:0] out  // Output from the functional module
);

    // 32-bit adder
    wire [31:0] adder_out;
    assign adder_out = a + b;

    // Parity checker
    reg [31:0] parity_reg;
    wire parity_check;
    assign parity_check = ^parity_reg;

    always @(posedge clk) begin
        if (reset) begin
            parity_reg <= 0;
        end else begin
            parity_reg <= parity_reg ^ adder_out;
        end
    end

    // Functional module
    assign out = parity_reg - adder_out;

endmodule

