  wire bWriteReq_0n;
  wire nbWriteReq_0n;
  reg data_0;
  reg nWriteReq_0;
  reg bWriteReq_0;
  reg nbWriteReq_0;

  assign read_0a = read_0r;
  assign read_0d = data_0n;

  always @(write_0r or write_0d)
  begin
    if (write_0r)
    begin
      if (nWriteReq_0n)
      begin
        data_0 <= write_0d;
        nWriteReq_0 <= 0;
        bWriteReq_0 <= 1;
        nbWriteReq_0 <= 0;
        write_0a <= 1;
      end
      else
      begin
        bWriteReq_0 <= 1;
        nbWriteReq_0 <= 0;
