module LMS (
  input [n-1:0] x,
  input [m-1:0] d,
  output [m-1:0] y,
  output [n-1:0] w
);

parameter n = 4; // number of input signals
parameter m = 2; // number of desired signals
parameter mu = 0.1; // step size

reg [n-1:0] w_reg; // register for filter coefficients
reg [m-1:0] y_reg; // register for output signals

wire [m-1:0] e; // error signals

assign y = y_reg;
assign w = w_reg;

// initialize filter coefficients to zero
initial begin
  w_reg = 0;
end

// calculate output signals and error signals
always @(*) begin
  y_reg = x * w_reg;
  e = d - y_reg;
end

// adjust filter coefficients using LMS algorithm
always @(posedge clk) begin
  w_reg = w_reg + mu * e * x;
end

endmodule

module video_sys_CPU_nios2_oci_dtrace (
