    input cpu_d_wait,
    input cpu_d_write,
    input [31:0] cpu_d_writedata,
    input jrst_n,
    input [15:0] trc_ctrl,
    output reg [35:0] atm,
    output reg [35:0] dtm
);

    wire [31:0] cpu_d_address_0_padded;
    wire [31:0] cpu_d_readdata_0_padded;
    wire [31:0] cpu_d_writedata_0_padded;
    wire record_load_addr;
    wire record_load_data;
    wire record_store_addr;
    wire record_store_data;
    wire [3:0] td_mode_trc_ctrl;

    assign cpu_d_address_0_padded = {8'b0, cpu_d_address};
    assign cpu_d_readdata_0_padded = {32'b0, cpu_d_readdata[31:0]};
    assign cpu_d_writedata_0_padded = {32'b0, cpu_d_writedata[31:0]};

    video_sys_CPU_nios2_oci_td_mode video_sys_CPU_nios2_oci_trc_ctrl_td_mode (
        .ctrl(trc_ctrl[8:0]),
        .td_mode(td_mode_trc_ctrl)
    );

    always @(posedge clk or negedge jrst_n) begin
        if (~jrst_n) begin
            atm <= 0;
            dtm <= 0;
        end else if (~cpu_d_wait) begin
            if (cpu_d_read && (cpu_d_address_0_padded == td_mode_trc_ctrl) && record_load_addr) begin
                atm <= {4'b0100, cpu_d_address_0_padded[31:0]};
                dtm <= {4'b0110, cpu_d_readdata_0_padded[31:0]};
            end else if (cpu_d_write && (cpu_d_address_0_padded == td_mode_trc_ctrl) && record_store_addr) begin
                atm <= {4'b0101, cpu_d_address_0_padded[31:0]};
                dtm <= {4'b0111, cpu_d_writedata_0_padded[31:0]};
            end else begin
                atm <= {4'b0000, cpu_d_address_0_padded[31:0]};
                dtm <= {4'b0000, cpu_d_readdata_0_padded[31:0]};
            end
        end
    end

    assign {record_load_addr, record_store_addr, record_load_data, record_store_data} = td_mode_trc_ctrl;

endmodule

module store_data_translator(
    input [31:0] write_data,
    input [1:0] d_address,
    input [1:0] store_size,
    output [3:0] d_byteena,
    output [31:0] d_writedataout
);

reg [3:0] d_byteena;
reg [31:0] d_writedataout;

always @*
begin
    case (store_size)
        2'b11:
            case(d_address[1:0])
                2'b00: 
                begin 
                    d_byteena=4'b1000; 
                    d_writedataout={write_data[7:0],24'b0}; 
                end
                2'b01: 
                begin 
                    d_byteena=4'b0100; 
                    d_writedataout={8'b0,write_data[7:0],16'b0}; 
                end
                2'b10: 
                begin 
                    d_byteena=4'b0010; 
                    d_writedataout={16'b0,write_data[7:0],8'b0}; 
                end
                default: 
                begin 
                    d_byteena=4'b0001; 
                    d_writedataout={24'b0,write_data[7:0]}; 
                end
            endcase
        2'b01:
            case(d_address[1])
                1'b0: 
                begin 
                    d_byteena=4'b1100; 
                    d_writedataout={write_data[15:0],16'b0}; 
                end
                default: 
                begin 
                    d_byteena=4'b0011; 
                    d_writedataout={16'b0,write_data[15:0]}; 
                end
            endcase
        default:
        begin
            d_byteena=4'b1111;
            d_writedataout=write_data;
        end
    endcase
end

