    input cin;
    input clk;
    output [3:0] sum;
    output cout;

    reg [3:0] sum_reg;
    reg cout_reg;

    always @(posedge clk) begin
        sum_reg <= a + b + cin;
        cout_reg <= (a[3] & b[3]) | (a[3] & cin) | (b[3] & cin);
    end

