    assign cout = cout_reg;
endmodule

module ripple_carry_adder (
    input [n-1:0] A,
    input [n-1:0] B,
    input Cin,
    output [n-1:0] S,
    output Cout
);

parameter n = 8; // number of bits in A and B

wire [n:0] C; // carry chain

// generate the sum and carry chain
generate
    genvar i;
    for (i = 0; i < n; i = i + 1) begin : adder_loop
        full_adder fa(A[i], B[i], C[i], S[i], C[i+1]);
    end
endgenerate

assign Cout = C[n];

endmodule
module carry_select_block (
    input [n:0] C,
    input [n-1:0] A,
    input [n-1:0] B,
    output [n-1:0] S
);

parameter n = 8; // number of bits in A and B

wire [n-1:0] S0; // sum with Cin = 0
wire [n-1:0] S1; // sum with Cin = 1

// generate the sum with Cin = 0
generate
    genvar i;
    for (i = 0; i < n; i = i + 1) begin : sum0_loop
        full_adder fa0(A[i], B[i], 0, S0[i], 0);
    end
endgenerate

// generate the sum with Cin = 1
generate
    genvar i;
    for (i = 0; i < n; i = i + 1) begin : sum1_loop
        full_adder fa1(A[i], B[i], 1, S1[i], 0);
    end
endgenerate

// select the correct sum based on the carry chain
generate
    genvar i;
    for (i = 0; i < n; i = i + 1) begin : select_loop
        mux2to1 mux(C[i], S1[i], S0[i], S[i]);
    end
endgenerate

endmodule
module carry_select_adder (
    input [n-1:0] A,
    input [n-1:0] B,
    input Cin,
    output [n-1:0] S,
    output Cout
);

parameter n = 8; // number of bits in A and B

wire [n:0] C; // carry chain

ripple_carry_adder rca(A, B, Cin, S, C[n]);

carry_select_block csb(C, A, B, S);

assign Cout = C[n];

endmodule
module full_adder (
    input A,
    input B,
    input Cin,
    output S,
    output Cout
);

assign S = A ^ B ^ Cin;
assign Cout = (A & B) | (Cin & (A ^ B));

endmodule
