module barrel_shifter_32bit (
    input [31:0] data_in,
    input [4:0] shift_amt,
    output reg [31:0] data_out,
    output reg [31:0] xor_out
);

wire [3:0] in_chunk;
wire [3:0] out_chunk;
wire [31:0] xor_in;

// Divide the input into 8-bit chunks and shift each chunk using the 4-bit barrel shifter
barrel_shifter_4bit bs1 (.data_in(data_in[7:0]), .shift_amt(shift_amt[1:0]), .data_out(out_chunk[3:0]));
barrel_shifter_4bit bs2 (.data_in(data_in[15:8]), .shift_amt(shift_amt[1:0]), .data_out(out_chunk[7:4]));
barrel_shifter_4bit bs3 (.data_in(data_in[23:16]), .shift_amt(shift_amt[1:0]), .data_out(out_chunk[11:8]));
barrel_shifter_4bit bs4 (.data_in(data_in[31:24]), .shift_amt(shift_amt[1:0]), .data_out(out_chunk[15:12]));
barrel_shifter_4bit bs5 (.data_in(out_chunk[3:0]), .shift_amt(shift_amt[1:0]), .data_out(in_chunk[3:0]));
barrel_shifter_4bit bs6 (.data_in(out_chunk[7:4]), .shift_amt(shift_amt[1:0]), .data_out(in_chunk[7:4]));
barrel_shifter_4bit bs7 (.data_in(out_chunk[11:8]), .shift_amt(shift_amt[1:0]), .data_out(in_chunk[11:8]));
barrel_shifter_4bit bs8 (.data_in(out_chunk[15:12]), .shift_amt(shift_amt[1:0]), .data_out(in_chunk[15:12]));

// Use a 4-to-1 multiplexer to select the correct output chunk
always @(*) begin
    case (shift_amt[4:2])
        3'b000: data_out = {in_chunk, out_chunk};
        3'b001: data_out = {in_chunk[1:0], out_chunk, in_chunk[3:2]};
        3'b010: data_out = {in_chunk[2:0], out_chunk, in_chunk[3]};
        3'b011: data_out = {in_chunk[3], in_chunk[2:0], out_chunk};
        3'b100: data_out = {out_chunk, in_chunk};
        3'b101: data_out = {in_chunk[1:0], out_chunk, in_chunk[3:2]};
        3'b110: data_out = {in_chunk[2:0], out_chunk, in_chunk[3]};
        3'b111: data_out = {in_chunk[3], in_chunk[2:0], out_chunk};
    endcase
end

// XOR module to calculate the bitwise XOR of the input and output
