module lifo_memory_block (
  input [7:0] din,
  input wr_en,
  input rd_en,
  input rst,
  output [7:0] dout
);

parameter depth = 8; // number of data values that can be stored in the memory block

reg [7:0] mem [0:depth-1]; // register file to store the data values
reg [2:0] count = 0; // counter to keep track of the number of data values that have been stored

// decoder to generate the write and read enable signals for the register file
reg [depth-1:0] wr_en_dec;
reg [depth-1:0] rd_en_dec;

generate
  for (i = 0; i < depth; i = i + 1) begin : dec_gen
    assign wr_en_dec[i] = (i == count) & wr_en;
    assign rd_en_dec[i] = (i == count-1) & rd_en;
  end
endgenerate

// multiplexer to select the most recently stored data value as the output
assign dout = rd_en_dec & mem[count-1];

// Verilog code to implement the LIFO memory block
always @ (posedge clk) begin
  if (rst) begin
    count <= 0;
  end else begin
    if (wr_en) begin
      mem[count] <= din;
      count <= count + 1;
    end else if (rd_en) begin
      count <= count - 1;
    end
  end
end

endmodule

