module SerialTransmitter(
    input        clk_x4,
    input        rst_x,
    input  [7:0] i_data,
    input        i_valid,
    output       o_tx,
    output       o_busy,
    output       o_error
    );

    reg [2:0] state;
    reg [7:0] data_reg;
    reg        busy_reg;
    reg        error_reg;

    assign o_tx = state == 3'b001;
    assign o_busy = busy_reg;
    assign o_error = error_reg;

    always @(posedge clk_x4 or posedge rst) begin
        if(rst) begin
            state <= 3'b000;
            busy_reg <= 1'b0;
            error_reg <= 1'b0;
            data_reg <= 8'h00;
        end else begin
            case(state)
                3'b000: begin //idle
                    if(i_valid) begin
                        data_reg <= i_data;
                        state <= 3'b001; //start bit
                        busy_reg <= 1'b1;
                    end
                end
                3'b001: begin //start bit
                    state <= 3'b010;
                end
                3'b010: begin //data bits
                    state <= 3'b011;
                end
                3'b011: begin //stop bit
                    state <= 3'b100;
                end
                3'b100: begin //idle
                    busy_reg <= 1'b0;
                    state <= 3'b000;
                end
            endcase
        end
    end

endmodule


module SerialReceiver(
    input        clk_x4,
