    assign o_valid = valid_reg;
    assign o_error = error_reg;

    always @(posedge clk_x4 or posedge rst) begin
        if(rst) begin
            state <= 3'b000;
            valid_reg <= 1'b0;
            error_reg <= 1'b0;
            data_reg <= 8'h00;
        end else begin
            case(state)
                3'b000: begin //idle
                    if(!i_rx) begin
                        state <= 3'b001; //start bit
                    end
                end
                3'b001: begin //start bit
                    state <= 3'b010;
                end
                3'b010: begin //data bits
                    data_reg <= {data_reg[6:0], i_rx};
                    state <= 3'b011;
                end
                3'b011: begin //stop bit
                    state <= 3'b100;
                end
                3'b100: begin //idle
                    valid_reg <= 1'b1;
                    state <= 3'b000;
                end
            endcase
        end
    end

endmodule


