  assign match = 1'b0;

  // State transition table
  always @(posedge clk, posedge reset) begin
    if (reset) begin
      state <= A;
    end else begin
      state <= next_state;
    end
  end

  always @(*) begin
    case(state)
      A: begin
        next_state = (data == 3'b101) ? G : (data == 3'b001) ? A : B;
        match = 1'b0;
      end
      B: begin
        next_state = (data == 3'b001) ? B : (data == 3'b010) ? C : A;
        match = 1'b0;
      end
      C: begin
        next_state = (data == 3'b001) ? B : (data == 3'b010) ? D : A;
        match = 1'b0;
      end
