module sequence_detector_fsm(data_out, state, reset, data_in, clk);

output data_out;
output reg [2:0] state;  // Matching progress.

input reset, data_in, clk;

// For data_out.
parameter FOUND =  1'b1,
          NOT_FOUND = 1'b0;

// For state.
parameter S0 = 3'd0,
          S1 = 3'd1,
          S2 = 3'd2,
          S3 = 3'd3,
          S4 = 3'd4,
          S5 = 3'd5,
          S6 = 3'd6;

reg this_data_in;
reg [2:0] next_state;

// Update state.
always @(posedge clk or posedge reset) begin
    if (reset) begin
        state <= S0;
        this_data_in <= 1'b0;
    end else begin
        state <= next_state;
        this_data_in <= data_in;
    end
end

// Calculate data_out.
assign data_out = (state == S6 ? FOUND : NOT_FOUND);

// Calculate next state.
always @(state, this_data_in) begin
    case (state)
        S0: next_state = (this_data_in ? S1 : S0);
        S1: next_state = (this_data_in ? S1 : S2);
        S2: next_state = (this_data_in ? S3 : S0);
        S3: next_state = (this_data_in ? S1 : S4);
        S4: next_state = (this_data_in ? S5 : S0);
        S5: next_state = (this_data_in ? S6 : S4);
        S6: next_state = (this_data_in ? S1 : S2);
        default: next_state = S0;
    endcase
end

endmodule

module rotator(
    input clk,
    input load,
    input [1:0] ena,
    input [99:0] data,
    output reg [99:0] q);

    reg [99:0] shift_reg;
    reg [5:0] shift_amt;
    reg [99:0] shifted_out;

    always @(posedge clk) begin
        if (load) begin
            shift_reg <= data;
        end else if (ena == 2'b00) begin
            shift_reg <= {shift_reg[0], shift_reg[99:1]};
        end else if (ena == 2'b01) begin
            shift_reg <= {shift_reg[1:0], shift_reg[99:2]};
        end else if (ena == 2'b10) begin
            shift_reg <= shift_reg;
        end else if (ena == 2'b11) begin
            shift_reg <= shift_reg;
        end
    end

    always @(*) begin
        if (ena == 2'b00) begin
            shift_amt = 1;
            shifted_out = shift_reg[99];
        end else if (ena == 2'b01) begin
            shift_amt = 99;
            shifted_out = shift_reg[0];
        end else if (ena == 2'b10) begin
            shift_amt = 0;
            shifted_out = 0;
        end else if (ena == 2'b11) begin
            shift_amt = 0;
            shifted_out = 0;
        end
    end

    assign q = (ena == 2'b10 || ena == 2'b11) ? shift_reg : {shift_reg[shift_amt-1:0], shifted_out, shift_reg[99:shift_amt]};
endmodule

