module four_bit_adder (
    input a, // first input bit
    input b, // second input bit
    input cin, // carry-in bit
    output sum, // output sum bit
    output cout // output carry bit
);

    // Declare internal wires
    wire w1, w2, w3;

    // Full adder for bit 0
    full_adder fa1(.a(a), .b(b), .cin(cin), .sum(w1), .cout(cout1));

    // Full adder for bit 1
    full_adder fa2(.a(a), .b(b), .cin(cout1), .sum(w2), .cout(cout2));

    // Full adder for bit 2
    full_adder fa3(.a(a), .b(b), .cin(cout2), .sum(w3), .cout(cout3));

    // Full adder for bit 3
    full_adder fa4(.a(a), .b(b), .cin(cout3), .sum(sum), .cout(cout));

endmodule

// Define the full adder module
module full_adder (
    input a, // first input bit
    input b, // second input bit
    input cin, // carry-in bit
    output sum, // output sum bit
    output cout // output carry bit
);

    // XOR gate for sum
    assign sum = a ^ b ^ cin;

    // AND gate for carry
    assign cout = (a & b) | (a & cin) | (b & cin);

endmodule

