module binary_adder (
    input [3:0] a, // first 4-bit input
    input [3:0] b, // second 4-bit input
    output [3:0] sum // output sum in binary form
);

    // Convert inputs to decimal form
    assign a = a[0]*1 + a[1]*2 + a[2]*4 + a[3]*8;
    assign b = b[0]*1 + b[1]*2 + b[2]*4 + b[3]*8;

    // Add inputs together and convert to binary form
    assign sum = {((a+b)/8)%2, ((a+b)/4)%2, ((a+b)/2)%2, (a+b)%2};

endmodule

