module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out
);

reg [7:0] data_reg [3:0];
reg [9:0] acc_reg [3:0];

integer i;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        for (i = 0; i < 4; i = i + 1) begin
            data_reg[i] <= 8'b0;
            acc_reg[i] <= 10'b0;
        end
        valid_b <= 1'b0;
        data_out <= 10'b0;
    end
    else begin
        for (i = 0; i < 4; i = i + 1) begin
            if (valid_a && ready_b) begin
                data_reg[i] <= data_in;
                acc_reg[i] <= acc_reg[i] + data_in;
            end
        end
        if (valid_a && ready_b) begin
            valid_b <= 1'b1;
        end
        if (valid_b && ready_a) begin
            valid_b <= 1'b0;
            for (i = 0; i < 4; i = i + 1) begin
                data_out[i*10 +: 10] <= acc_reg[i];
            end
        end
    end
end

assign ready_a = ~valid_b;

endmodule

