module INBUF(input wire CLK, input wire RST, input wire full_in, output reg full_out, 
             input wire enq, input wire [`SORTW-1:0] din, output reg [`SORTW-1:0] dout, 
             output reg emp, input wire phase, input wire irst);

    reg [`SORTW-1:0] buf;
    reg full;

    always @(posedge CLK) begin
        if (RST) begin
            buf <= 0;
            full <= 0;
            full_out <= 0;
        end else if (enq && !full) begin
            buf <= din;
            full <= 1;
        end else if (irst && !full) begin
            buf <= buf;
            full <= 1;
        end
    end

    always @(posedge CLK) begin
        if (RST) begin
            dout <= 0;
            emp <= 1;
        end else if (!full && !irst) begin
            dout <= 0;
            emp <= 1;
        end else if (phase == 2'b01) begin
            dout <= buf;
            emp <= 0;
        end else begin
            dout <= 0;
            emp <= 0;
        end
    end

    always @(posedge CLK) begin
        if (RST) begin
            full_out <= 0;
        end else if (full) begin
            full_out <= 1;
        end else begin
            full_out <= full_in;
        end
    end
endmodule

module MRE2(input wire CLK, input wire frst, input wire enq, input wire deq, 
            input wire [31:0] din, output reg [31:0] dot, output reg emp, 
            output reg full, output reg [1:0] cnt);

    reg [31:0] buf;
    reg emp_reg, full_reg;
    reg [1:0] cnt_reg;

    always @(posedge CLK) begin
        if (frst) begin
            buf <= 0;
            emp_reg <= 1;
            full_reg <= 0;
            cnt_reg <= 0;
        end else if (enq && !full_reg) begin
            buf <= din;
            emp_reg <= 0;
            full_reg <= 1;
            cnt_reg <= cnt_reg + 1;
        end else if (deq && !emp_reg) begin
            buf <= 0;
            emp_reg <= 1;
            full_reg <= 0;
            cnt_reg <= cnt_reg - 1;
        end
    end

    always @(posedge CLK) begin
        if (frst) begin
            dot <= 0;
            emp <= 1;
            full <= 0;
            cnt <= 0;
        end else if (!emp_reg) begin
            dot <= buf * din;
            emp <= 0;
            full <= full_reg;
            cnt <= cnt_reg;
        end else begin
            dot <= 0;
            emp <= 1;
            full <= full_reg;
            cnt <= cnt_reg;
        end
    end
endmodule

module SCELL(input wire emp1, input wire emp2, input wire deq1, input wire deq2, 
             input wire [31:0] dot1, input wire [31:0] dot2, input wire full, 
             input wire [31:0] din, input wire enq);

    wire [31:0] min;
    reg [31:0] buf1, buf2;
    reg emp_reg, full_reg;

    always @(emp1 or emp2 or deq1 or deq2 or dot1 or dot2 or full or din or enq) begin
        if (emp1 && emp2) begin
            emp_reg <= 1;
            full_reg <= 0;
        end else if (!emp1 && emp2) begin
            buf1 <= dot1;
            emp_reg <= 0;
            full_reg <= 0;
        end else if (emp1 && !emp2) begin
            buf2 <= dot2;
            emp_reg <= 0;
            full_reg <= 0;
        end else if (!emp1 && !emp2) begin
            if (dot1 < dot2) begin
                min <= dot1;
                buf1 <= 0;
                buf2 <= dot2;
            end else begin
                min <= dot2;
                buf1 <= dot1;
                buf2 <= 0;
            end
            emp_reg <= 0;
            full_reg <= full;
        end
    end

    always @(posedge CLK) begin
        if (RST) begin
            emp_reg <= 1;
            full_reg <= 0;
        end else if (emp_reg) begin
            dout <= 0;
            emp <= 1;
            full <= full_reg;
        end else if (!emp_reg) begin
            dout <= min;
            emp <= 0;
            full <= full_reg;
        end
    end
endmodule

module timecode_memory_interface(
    input clk,
    input reset,
    input [7:0] timecode_data,
    input timecode_valid,
    input [12:0] timecode_address,
    output reg [7:0] data_out,
    output reg write_enable
);

    // Internal signals
    reg [7:0] memory_data;
    reg [12:0] memory_address;
    reg memory_write_enable;

    always @(posedge clk) begin
        if (reset) begin
            // Reset internal signals
            memory_data <= 8'h00;
            memory_address <= 13'h000;
            memory_write_enable <= 1'b0;
            data_out <= 8'h00;
            write_enable <= 1'b0;
        end else begin
            if (timecode_valid) begin
                // Write timecode data to memory
                memory_data <= timecode_data;
                memory_address <= timecode_address;
                memory_write_enable <= 1'b1;
            end else begin
                // Read data from memory
                memory_address <= timecode_address;
                memory_write_enable <= 1'b0;
                data_out <= memory_data;
                write_enable <= memory_write_enable;
            end
        end
    end

endmodule

module program_counter(
    input rst, // synchronous reset
    input clk, // system clock
    output reg [31:0] cur_pc, // current program counter value
    output reg [31:0] next_pc // next program counter value
);

always @(posedge clk) begin
    if(rst) begin
        cur_pc <= 32'd0;
        next_pc <= 32'd0;
    end else begin
        cur_pc <= next_pc;
        next_pc <= cur_pc + 32'd1;
    end
end

endmodule

module lcd_driver (
  input [n-1:0] data,
  input clk,
  input rst,
  output [m-1:0] out
);

parameter n = 8; // number of data signals
parameter m = 16; // number of output signals (for a 16x2 LCD display)

// Define ASCII code for characters and numbers
parameter ASCII_A = 8'h41;
parameter ASCII_0 = 8'h30;

// Define commands for the LCD panel
parameter CMD_CLEAR_DISPLAY = 4'b0001;
parameter CMD_RETURN_HOME = 4'b0010;
parameter CMD_ENTRY_MODE_SET = 4'b0110;
parameter CMD_DISPLAY_ON_OFF_CONTROL = 4'b1000;
parameter CMD_FUNCTION_SET = 4'b0010;

// Define internal signals
reg [3:0] data_bus;
reg [3:0] cmd_bus;
reg [3:0] lcd_state;
reg [3:0] lcd_row;
reg [3:0] lcd_col;

// Define state machine states
parameter STATE_INIT = 4'b0000;
parameter STATE_CLEAR_DISPLAY = 4'b0001;
parameter STATE_RETURN_HOME = 4'b0010;
parameter STATE_ENTRY_MODE_SET = 4'b0011;
parameter STATE_DISPLAY_ON_OFF_CONTROL = 4'b0100;
parameter STATE_FUNCTION_SET = 4'b0101;
parameter STATE_WRITE_DATA = 4'b0110;
parameter STATE_WRITE_COMMAND = 4'b0111;

// Define state machine transitions
always @(posedge clk) begin
  if (rst) begin
    lcd_state <= STATE_INIT;
    lcd_row <= 4'b0000;
    lcd_col <= 4'b0000;
  end else begin
    case (lcd_state)
      STATE_INIT: begin
        cmd_bus <= CMD_FUNCTION_SET;
        lcd_state <= STATE_FUNCTION_SET;
      end
      STATE_CLEAR_DISPLAY: begin
        cmd_bus <= CMD_CLEAR_DISPLAY;
        lcd_state <= STATE_FUNCTION_SET;
      end
      STATE_RETURN_HOME: begin
        cmd_bus <= CMD_RETURN_HOME;
        lcd_state <= STATE_FUNCTION_SET;
      end
      STATE_ENTRY_MODE_SET: begin
        cmd_bus <= CMD_ENTRY_MODE_SET;
        lcd_state <= STATE_FUNCTION_SET;
      end
      STATE_DISPLAY_ON_OFF_CONTROL: begin
        cmd_bus <= CMD_DISPLAY_ON_OFF_CONTROL;
        lcd_state <= STATE_FUNCTION_SET;
      end
      STATE_FUNCTION_SET: begin
        cmd_bus <= CMD_FUNCTION_SET;
        lcd_state <= STATE_WRITE_COMMAND;
      end
      STATE_WRITE_DATA: begin
        data_bus <= data[7:4];
        lcd_state <= STATE_WRITE_COMMAND;
      end
      STATE_WRITE_COMMAND: begin
        out <= {cmd_bus, data_bus};
        lcd_col <= lcd_col + 1;
        if (lcd_col == 4'b0100) begin
          lcd_col <= 4'b0000;
          lcd_row <= lcd_row + 1;
          if (lcd_row == 4'b0010) begin
            lcd_row <= 4'b0000;
          end
        end
        if (lcd_row == 4'b0000 && lcd_col == 4'b0000) begin
          lcd_state <= STATE_CLEAR_DISPLAY;
        end else begin
          lcd_state <= STATE_WRITE_DATA;
        end
      end
    endcase
  end
end

endmodule

module rng(clk, en, resetn, loadseed_i, seed_i, number_o);
input clk;
input resetn;
input en;
input loadseed_i;
input [31:0] seed_i;
output [31:0] number_o;

wire [31:0] number_o;

reg [31:0] sr1, sr2, sr3;
reg [31:0] fb1, fb2, fb3;
reg [31:0] r_s1, r_s2, r_s3;

assign number_o = sr1 ^ sr2 ^ sr3;

always @(loadseed_i or seed_i or r_s1 or r_s2 or r_s3) begin
    if (loadseed_i) begin
        sr1 = 32'b0;
        sr2 = 30'b0;
        sr3 = 28'b0;
        sr1[31:0] = seed_i;
        sr2[29:0] = {seed_i[29:0], 1'b0};
        sr3[27:0] = {seed_i[27:0], 1'b0};
    end else begin
        fb1 = sr1[0] ^ sr1[1] ^ sr1[3] ^ sr1[4] ^ sr1[7] ^ sr1[8] ^ sr1[11] ^ sr1[12] ^ sr1[15] ^ sr1[19] ^ sr1[22] ^ sr1[23] ^ sr1[24] ^ sr1[26] ^ sr1[27] ^ sr1[28] ^ sr1[30] ^ sr1[31];
        fb2 = sr2[0] ^ sr2[1] ^ sr2[2] ^ sr2[3] ^ sr2[4] ^ sr2[7] ^ sr2[8] ^ sr2[10] ^ sr2[11] ^ sr2[13] ^ sr2[14] ^ sr2[17] ^ sr2[18] ^ sr2[19] ^ sr2[20] ^ sr2[21] ^ sr2[22] ^ sr2[24] ^ sr2[25] ^ sr2[26] ^ sr2[27] ^ sr2[28] ^ sr2[29];
        fb3 = sr3[0] ^ sr3[1] ^ sr3[3] ^ sr3[4] ^ sr3[5] ^ sr3[6] ^ sr3[8] ^ sr3[9] ^ sr3[10] ^ sr3[12] ^ sr3[13] ^ sr3[16] ^ sr3[17] ^ sr3[20] ^ sr3[21] ^ sr3[24] ^ sr3[25] ^ sr3[26] ^ sr3[27];
        sr1 = {fb1, sr1[0:30]};
        sr2 = {fb2, sr2[0:28]};
        sr3 = {fb3, sr3[0:26]};
    end
end

always @(posedge clk or negedge resetn) begin
    if (!resetn) begin
        r_s1 <= 32'b0;
        r_s2 <= 30'b0;
        r_s3 <= 28'b0;
    end else if (en) begin
        r_s1 <= sr1;
        r_s2 <= sr2;
        r_s3 <= sr3;
    end
end

endmodule

