module priority_encoder (
    input [7:0] in,
    output reg [2:0] pos
);

    wire [2:0] gray_code;
    wire [2:0] binary_code;

    // Binary-to-Gray code converter
    assign gray_code[2] = in[7] ^ in[6];
    assign gray_code[1] = in[6] ^ in[5];
    assign gray_code[0] = in[5] ^ in[4];

    // Gray-to-binary code converter
    assign binary_code[2] = gray_code[2];
    assign binary_code[1] = gray_code[2] ^ gray_code[1];
    assign binary_code[0] = gray_code[1] ^ gray_code[0];

    always @* begin
        if (in[7] == 1) begin
            pos = 3;
        end else if (binary_code[2] == 1) begin
            pos = 2;
        end else if (binary_code[1] == 1) begin
            pos = 1;
        end else if (binary_code[0] == 1) begin
            pos = 0;
        end else begin
            pos = 0;
        end
    end

endmodule

