module stimulus_gen(
    input clk,
    input rst,
    input req,
    output [INPUT_PORTS-1: 0] stm_value,
    output rsb,
    output gnt
);

parameter INPUT_PORTS = 3;
parameter RESET_PORT = 1; // 0: no reset, 1: has reset
parameter RESET_SENS = 0; // 0: Active Low, 1: Active High

reg rsb;
reg gnt;
reg [INPUT_PORTS-1:0] data;
integer fd;
integer code, dummy;
reg [(INPUT_PORTS)*8-1:0] str;

assign stm_value = data;

initial begin
    rsb = RESET_SENS ? 1'b1 : 1'b0;
    gnt = 1'b0;
    @(posedge clk);
    #100;
    @(posedge clk);
    wait (req == 1'b1);
    @(posedge clk);

    if(RESET_PORT == 1) begin
        rsb = RESET_SENS ? 1'b0 : 1'b1;
        @(posedge clk);
        rsb = RESET_SENS ? 1'b1 : 1'b0;
    end

    // select stimulus input text file
    case(INPUT_PORTS)
        1: fd = $fopen("ncl_stimul_1input.txt","r"); 
        2: fd = $fopen("ncl_stimul_2input.txt","r"); 
        3: fd = $fopen("ncl_stimul_3input.txt","r"); 
        4: fd = $fopen("ncl_stimul_4input.txt","r"); 
        default: $fatal("Invalid INPUT_PORTS value: %0d", INPUT_PORTS);
    endcase

    data = {INPUT_PORTS{1'b0}};
    code = 1;

    while (code) begin
        code = $fgets(str, fd);
        dummy = $sscanf(str, "%b", data);
        code = $fgets(str, fd);
        rsb = 1'b0;
        @(posedge clk);
    end

    // close the file for next file open
    $fclose(fd); 

    if(RESET_PORT == 1) begin
        // select stimulus input text file
        case(INPUT_PORTS)
            1: fd = $fopen("ncl_stimul_1input.txt","r"); 
            2: fd = $fopen("ncl_stimul_2input.txt","r"); 
            3: fd = $fopen("ncl_stimul_3input.txt","r"); 
            4: fd = $fopen("ncl_stimul_4input.txt","r"); 
            default: $fatal("Invalid INPUT_PORTS value: %0d", INPUT_PORTS);
        endcase

        data = {INPUT_PORTS{1'b0}};
        code = 1;

        while (code) begin
            code = $fgets(str, fd);
            dummy = $sscanf(str, "%b", data);
            code = $fgets(str, fd);
            rsb = 1'b1;
            @(posedge clk);
        end

        // close the file for next file open
        $fclose(fd); 
    end

    @(posedge clk);
    gnt = 1'b1;
    @(posedge clk);
    gnt = 1'b0;
    #100;
end

endmodule

module memory_arbiter(
  input [n-1:0] req,
  input [m-1:0] pri,
  output sel
);

parameter n = 4; // number of memory requests

reg [n-1:0] valid_req;
reg [n-1:0] valid_pri;
reg [n-1:0] valid_index;
reg [m-1:0] max_pri;
reg [n-1:0] max_index;

always @(*) begin
  max_pri = 'b0;
  max_index = 'b0;
  for (i = 0; i < n; i = i + 1) begin
    if (req[i] && pri[i] > max_pri[0]) begin
      max_pri = {pri[i], 1'b1};
      max_index = {i, 1'b0};
    end else if (req[i] && pri[i] == max_pri[0] && i < max_index[0]) begin
      max_index = {i, 1'b0};
    end
  end
  valid_req = req & (pri == max_pri[0]);
  valid_pri = pri & (req == max_req[0]);
  valid_index = {valid_req, valid_pri};
end

assign sel = valid_index ^ max_index;

endmodule

module memory_arbiter (
  input [n-1:0] REQ,
  input CLK,
  input RST,
  output GRANT
);

parameter n = 4; // number of request signals

reg [n-1:0] req_priority;
reg [n-1:0] req_grant;

always @ (posedge CLK) begin
  if (RST) begin
    req_priority <= 0;
    req_grant <= 0;
  end else begin
    // Determine highest priority request
    req_priority <= {req_priority[n-2:0], req_priority[n-1]};
    if (REQ != 0) begin
      req_priority[0] <= REQ & ~req_grant;
    end
    // Grant access to highest priority request
    req_grant <= req_priority[0];
  end
end

assign GRANT = req_grant;

endmodule

