);

sasc_brg baud_ (
    .sio_ce(sio_ce),
    .sio_ce_x4(sio_ce_x4),
    .clk(clk),
    .arst_n(arst_n)
);

always @ (posedge clk or negedge arst_n) begin
    if (~arst_n) begin
        state <= 3'b000;
    end else begin
        case (state)
            3'b000: begin
                if (~empty_o) begin
                    state <= 3'b001;
                end
            end
            3'b001: begin
                if (~empty_o) begin
                    state <= 3'b010;
                end
            end
            3'b010: begin
                if (cmdRd) begin
                    state <= 3'b100;
                end else if (~empty_o) begin
                    state <= 3'b011;
                end
            end
            3'b011: begin
                if (cmdRd) begin
                    state <= 3'b101;
                end else if (~empty_o) begin
                    state <= 3'b100;
                end
            end
            3'b100: begin
                if (cmdRd) begin
                    state <= 3'b101;
                end else if (~empty_o) begin
                    state <= 3'b101;
                end else begin
                    state <= 3'b010;
                end
            end
            3'b101: begin
                if (cmdRd) begin
                    state <= 3'b000;
                end else begin
                    state <= 3'b110;
                end
            end
            3'b110: begin
                state <= 3'b000;
            end
        endcase
    end
end

always @ (posedge clk or negedge arst_n) begin
    if (~arst_n) begin
        cmd <= 16'b0;
    end else begin
        if (state == 3'b000) begin
            cmd[15:8] <= dout_o[7:0];
        end else if (state == 3'b001) begin
            cmd[7:0] <= dout_o[7:0];
        end
    end
end

assign cmdRd = ~cmd[15];
assign cmdMem = cmd[14];
assign uart_addr = cmd[13:0];

always @ (posedge clk or negedge arst_n) begin
    if (~arst_n) begin
        uart_dout <= 8'b0;
    end else begin
        if (state == 3'b010 && ~cmdRd) begin
            uart_dout[31:24] <= dout_o[7:0];
        end else if (state == 3'b011 && ~cmdRd) begin
            uart_dout[23:16] <= dout_o[7:0];
        end else if (state == 3'b100 && ~cmdRd) begin
            uart_dout[15:8] <= dout_o[7:0];
        end else if (state == 3'b101 && ~cmdRd) begin
            uart_dout[7:0] <= dout_o[7:0];
        end
    end
end

always @ (cmdRd or empty_o or state) begin
    case (state)
        3'b000: re_i = ~empty_o;
        3'b001: re_i = ~empty_o;
        3'b010: re_i = ~empty_o & ~cmdRd;
        3'b011: re_i = ~empty_o & ~cmdRd;
        3'b100: re_i = ~empty_o & ~cmdRd;
        default: re_i = 1'b0;
    endcase
end

assign uart_mem_we = (state == 3'b110) & cmdMem;
assign reg_we = (state == 3'b110) & ~cmdMem;

always @ (cmdMem or state or uart_mem_i or uart_reg_i) begin
    case (state)
        3'b011: din_i[7:0] = cmdMem ? uart_mem_i[23:16] : uart_reg_i[23:16];
        3'b100: din_i[7:0] = cmdMem ? uart_mem_i[15:8] : uart_reg_i[15:8];
        3'b101: din_i[7:0] = cmdMem ? uart_mem_i[7:0] : uart_reg_i[7:0];
        default: din_i[7:0] = 8'b0;
    endcase
end

always @ (cmdRd or state) begin
    case (state)
