module riscv_ex (
    input                       clk,
    input                       rstn,
    //ID to EX inputs
    input                       id_ex_rdy,
    output                      id_ex_ack,
    input  [31:0]               id_ex_op1,
    input  [31:0]               id_ex_op2,
    input  [5:0]                id_ex_funct,
    //ID to MEM inputs
    input  [31:0]               id_ex_mem_st_data,
    input  [2:0]                id_ex_mem_st_funct,
    input  [2:0]                id_ex_mem_ld_funct,
    //EX to MEM outputs
    output                      ex_mem_rdy,
    input                       ex_mem_ack,
    output                      ex_mem_alu_op,
    output  [31:0]              ex_mem_st_data,
    output  [2:0]               ex_mem_ld_funct,
    output  [2:0]               ex_mem_st_funct,
    output  [31:0]              ex_mem_data
);

reg                             id_ex_ack;

reg                             ex_mem_rdy;
reg  [31:0]                     ex_mem_data;
reg                             ex_mem_alu_op;
reg  [31:0]                     ex_mem_st_data;
reg  [2:0]                      ex_mem_ld_funct;
reg  [2:0]                      ex_mem_st_funct;

wire                            ex_mem_alu_op_n;

wire [31:0]                     neg_op2;
wire [5:0]                      shft_amnt;
reg  [31:0]                     result;

assign neg_op2   = (~id_ex_op2) + 1;
assign shft_amnt = id_ex_op2 & 'h1f;

always @ (*) begin
    case (id_ex_funct) 
        6'b000000 : result = id_ex_op1 + id_ex_op2;
        6'b010000 : result = id_ex_op1 - id_ex_op2;
        6'b001001 : result = id_ex_op1 | id_ex_op2;
        6'b001010 : result = id_ex_op1 ^ id_ex_op2;
        6'b001000 : result = id_ex_op1 & id_ex_op2;
        6'b100000 : result = ($signed(id_ex_op1) < $signed(id_ex_op2)) ?  1'b1 : 1'b0;
        6'b100001 : result = (id_ex_op1 < id_ex_op2) ? 1'b1 : 1'b0;
        6'b000001 : result = id_ex_op1 << shft_amnt;
        6'b000010 : result = id_ex_op1 >> shft_amnt;
        6'b000011 : result = $signed(id_ex_op1) >>> shft_amnt;
        default : result = 32'b0;
    endcase
end

assign ex_mem_alu_op_n = (id_ex_funct == 6'b000000);

always @ (*) begin
    if (ex_mem_rdy && !ex_mem_ack) begin
        id_ex_ack = 1'b0;
    end
    else begin
        id_ex_ack = 1'b1;
    end
end

always @ (posedge clk, negedge rstn) begin
    if (!rstn) begin
        ex_mem_rdy      <= 1'b0;
        ex_mem_data     <= 32'b0;
        ex_mem_alu_op   <= 1'b0;
        ex_mem_st_data  <= 32'b0;
        ex_mem_st_funct <= 3'b000;
        ex_mem_ld_funct <= 3'b000;
    end
    else if (clk) begin
        if (!ex_mem_rdy || ex_mem_ack) begin
            ex_mem_rdy      <= id_ex_rdy;
            ex_mem_data     <= result;
            ex_mem_alu_op   <= ex_mem_alu_op_n;
            ex_mem_st_data  <= id_ex_mem_st_data;
            ex_mem_st_funct <= id_ex_mem_st_funct;
            ex_mem_ld_funct <= id_ex_mem_ld_funct;
        end
    end
end

endmodule

