module top_module( 
    input [1023:0] in,
    input [2:0] sel,
    output [3:0] out );

    // Define internal wires and registers
    wire [3:0] mux_out;
    reg [255:0] stage1_out [0:3];
    reg [63:0] stage2_out [0:3];
    reg [15:0] stage3_out [0:3];
    reg [3:0] stage4_out [0:3];

    // Define binary tree architecture
    // Stage 1
    genvar i;
    generate
        for (i = 0; i < 256; i = i + 2) begin : stage1
            assign mux_out = {in[i*4 + 3], in[i*4 + 2], in[i*4 + 1], in[i*4]};
            priority_encoder pe(mux_out, stage1_out[i/2]);
        end
    endgenerate

    // Stage 2
    generate
        for (i = 0; i < 128; i = i + 2) begin : stage2
            mux4 mux(
                .in0(stage1_out[i*2 + 1]),
                .in1(stage1_out[i*2]),
                .in2(stage1_out[i*2 + 3]),
                .in3(stage1_out[i*2 + 2]),
                .sel(sel[1:0]),
                .out(stage2_out[i/2])
            );
        end
    endgenerate

    // Stage 3
    generate
        for (i = 0; i < 64; i = i + 2) begin : stage3
            mux4 mux(
                .in0(stage2_out[i*2 + 1]),
                .in1(stage2_out[i*2]),
                .in2(stage2_out[i*2 + 3]),
                .in3(stage2_out[i*2 + 2]),
                .sel(sel[1:0]),
                .out(stage3_out[i/2])
            );
        end
    endgenerate

    // Stage 4
    generate
        for (i = 0; i < 32; i = i + 2) begin : stage4
            mux4 mux(
                .in0(stage3_out[i*2 + 1]),
                .in1(stage3_out[i*2]),
                .in2(stage3_out[i*2 + 3]),
                .in3(stage3_out[i*2 + 2]),
                .sel(sel[1:0]),
                .out(stage4_out[i/2])
            );
        end
    endgenerate

    // Output
    assign out = stage4_out[0];

endmodule

