module fsm_4bit_sequence_detection (
  input clk,
  input reset,
  input data,
  output reg match
);

  parameter IDLE = 2'b00;
  parameter S1 = 2'b01;
  parameter S2 = 2'b10;
  parameter S3 = 2'b11;

  reg [1:0] state;
  reg [3:0] shift_reg;

  always @(posedge clk, negedge reset) begin
    if(!reset) begin
      state <= IDLE;
      shift_reg <= 4'b0000;
      match <= 1'b0;
    end else begin
      case(state)
        IDLE: begin
          if(data == 1'b1) begin
            shift_reg <= {shift_reg[2:0], data};
            state <= S1;
          end else begin
            shift_reg <= 4'b0000;
          end
        end
        S1: begin
          if(data == 1'b0) begin
            shift_reg <= {shift_reg[2:0], data};
            state <= IDLE;
          end else begin
            shift_reg <= {shift_reg[2:0], data};
            state <= S2;
          end
        end
        S2: begin
          if(data == 1'b1) begin
            shift_reg <= {shift_reg[2:0], data};
            state <= S3;
          end else begin
            shift_reg <= {shift_reg[2:0], data};
            state <= IDLE;
          end
        end
        S3: begin
          if(data == 1'b1) begin
            shift_reg <= {shift_reg[2:0], data};
            state <= IDLE;
            match <= 1'b1;
          end else begin
            shift_reg <= {shift_reg[2:0], data};
            state <= IDLE;
          end
        end
      endcase
    end
  end
endmodule

module pulse_generator (
  input trigger,
  output pulse
);

parameter time_constant = 10; // time constant of the monostable pulse generator
parameter period = 20; // period of the astable pulse generator
parameter duty_cycle = 0.5; // duty cycle of the astable pulse generator

// Monostable pulse generator
reg [31:0] pulse_duration = 0;
always @(posedge trigger) begin
  pulse_duration <= time_constant;
end
assign pulse = (pulse_duration > 0) ? 1 : 0;
always @(posedge clk) begin
  if (pulse_duration > 0) begin
    #1 pulse_duration = pulse_duration - 1;
  end
end

// Astable pulse generator
reg [31:0] pulse_period = 0;
always @(posedge clk) begin
  if (pulse_period == 0) begin
    pulse_period <= period;
  end else begin
    pulse_period <= pulse_period - 1;
  end
end
assign pulse = (pulse_period < period * duty_cycle) ? 1 : 0;

endmodule

