module nand_or (
    A,
    B,
    C,
    D_N,
    X
);

    input A;
    input B;
    input C;
    input D_N;
    output X;

    wire nand1;
    wire nand2;
    wire or1;

    nand2 nand_gate1 (
        .A(A),
        .B(B),
        .X(nand1)
    );

    nand2 nand_gate2 (
        .A(nand1),
        .B(C),
        .X(nand2)
    );

    or2 or_gate1 (
        .A(A),
        .B(B),
        .X(or1)
    );

    nand2 nand_gate3 (
        .A(or1),
        .B(C),
        .X(X)
    );

    not not_gate1 (
        .A(D_N),
        .X(D)
    );

    assign X = nand_gate3 & D;

endmodule

module counter(CLK, CNT, CMD, TEND);

input CLK;
input [15:0] CNT;
output reg [7:0] CMD;
output reg [1:0] TEND;

always @(posedge CLK) begin
    if (CNT >= 255) begin
        CMD <= 8'hFF;
    end else if (CNT <= 0) begin
        CMD <= 8'h00;
    end else if (CNT[15:8] >= 100 && CNT[7:0] >= 100) begin
        CMD <= 8'h80;
    end else begin
        CMD <= CNT[15:8] + CNT[7:0];
    end
    case(CNT[15:8])
        8'hFF: TEND <= 2'b01;
        default: case(CNT[13:12])
            2'b00: TEND <= 2'b00;
            2'b01: TEND <= 2'b10;
            2'b10: TEND <= 2'b11;
            2'b11: TEND <= 2'b00;
        endcase
    endcase
end

endmodule

module top(CLK, SCL, SDA, CNT1A, CNT1B, CNT2A, CNT2B, CNT3A, CNT3B, CNT4A, CNT4B, CMD, TEND);

input CLK;
input SCL;
inout SDA;
input [15:0] CNT1A;
input [15:0] CNT1B;
input [15:0] CNT2A;
input [15:0] CNT2B;
input [15:0] CNT3A;
input [15:0] CNT3B;
input [15:0] CNT4A;
input [15:0] CNT4B;
output reg [7:0] CMD;
output reg [1:0] TEND;

wire[15:0] CNTR1;
wire[15:0] CNTR2;
wire[15:0] CNTR3;
wire[15:0] CNTR4;

counter counter1(.CLK(CLK), .CNT(CNTR1), .CMD(CMD), .TEND(TEND));
counter counter2(.CLK(CLK), .CNT(CNTR2), .CMD(CMD), .TEND(TEND));
counter counter3(.CLK(CLK), .CNT(CNTR3), .CMD(CMD), .TEND(TEND));
counter counter4(.CLK(CLK), .CNT(CNTR4), .CMD(CMD), .TEND(TEND));

assign CMD = (CNTR1 >= 255 || CNTR2 >= 255 || CNTR3 >= 255 || CNTR4 >= 255) ? 8'hFF :
             (CNTR1 <= 0 || CNTR2 <= 0 || CNTR3 <= 0 || CNTR4 <= 0) ? 8'h00 :
             (CNTR1[15:8] >= 100 && CNTR1[7:0] >= 100 && CNTR2[15:8] >= 100 && CNTR2[7:0] >= 100 &&
              CNTR3[15:8] >= 100 && CNTR3[7:0] >= 100 && CNTR4[15:8] >= 100 && CNTR4[7:0] >= 100) ? 8'h80 :
             CNTR1[15:8] + CNTR1[7:0] + CNTR2[15:8] + CNTR2[7:0] + CNTR3[15:8] + CNTR3[7:0] + CNTR4[15:8] + CNTR4[7:0];

assign TEND = (CNTR1 >= 255) ? 2'b01 :
             (CNTR2 >= 255) ? 2'b10 :
             (CNTR3 >= 255) ? 2'b11 :
             (CNTR4 >= 255) ? 2'b00 :
             2'b00;

I2CSlave(.CLK(CLK), 
         .SCL(SCL), 
         .SDA(SDA),
         .CNT1A(CNT1A),
         .CNT1B(CNT1B),
         .CNT2A(CNT2A),
         .CNT2B(CNT2B),
         .CNT3A(CNT3A),
         .CNT3B(CNT3B),
         .CNT4A(CNT4A),
         .CNT4B(CNT4B));

endmodule

module a25_barrel_shift (

input                       i_clk,
input       [31:0]          i_in,
input                       i_carry_in,
input       [7:0]           i_shift_amount,     // uses 8 LSBs of Rs, or a 5 bit immediate constant
input                       i_shift_imm_zero,   // high when immediate shift value of zero selected
input       [1:0]           i_function,

output      [31:0]          o_out,
output                      o_carry_out,
output                      o_stall

);

wire [31:0] quick_out;
wire        quick_carry_out;
wire [31:0] full_out;
wire        full_carry_out;
reg  [31:0] full_out_r       = 'd0;
reg         full_carry_out_r = 'd0;
reg         use_quick_r      = 1'd1;

assign o_stall      = (|i_shift_amount[7:2]) & use_quick_r;
assign o_out        = use_quick_r ? quick_out : full_out_r;
assign o_carry_out  = use_quick_r ? quick_carry_out : full_carry_out_r;

// Capture the result from the full barrel shifter in case the
// quick shifter gives the wrong value
always @(posedge i_clk)
    begin
    full_out_r       <= full_out;
    full_carry_out_r <= full_carry_out;
    use_quick_r      <= !o_stall;
    end

// Full barrel shifter
a25_shifter #( 
    .FULL_BARREL (1)
    )
u_a25_shifter_full (
    .i_in               ( i_in             ),
    .i_carry_in         ( i_carry_in       ),
    .i_shift_amount     ( i_shift_amount   ),   
    .i_shift_imm_zero   ( i_shift_imm_zero ), 
    .i_function         ( i_function       ),
    .o_out              ( full_out         ),
    .o_carry_out        ( full_carry_out   )
);

// Quick barrel shifter
a25_shifter #( 
    .FULL_BARREL        ( 0                ) 
    )
u_a25_shifter_quick (
    .i_in               ( i_in             ),
    .i_carry_in         ( i_carry_in       ),
    .i_shift_amount     ( i_shift_amount   ),   
    .i_shift_imm_zero   ( i_shift_imm_zero ), 
    .i_function         ( i_function       ),
    .o_out              ( quick_out        ),
    .o_carry_out        ( quick_carry_out  )
);

endmodule

module output_pulse
(
    clk,
    signal_i,
    signal_o
);

//////////// INPUTS & OUTPUTS ////////////
input clk;
input signal_i;
output signal_o;

//////////// PARAMETERS ////////////
parameter COUNT = 15; // with clk of 1.5kHz corresponds to 10ms width
parameter s_idle = 1'b0;
parameter s_out = 1'b1;

//////////// SIGNALS & REGS ////////////
reg [15:0] cnt = 0;
reg state = s_idle;

//////////// LOGIC ////////////
always @(posedge clk) begin
    case(state)
        s_idle:
            begin
                if(signal_i == 1'b1) begin
                    state <= s_out;
                    cnt <= 8'b0;
                end
            end
        s_out:
            begin
                if(cnt >= COUNT) begin
                    state <= s_idle;
                end else begin
                    cnt <= cnt + 8'b1;
                end
            end
    endcase
end

//////////// OUTPUT ASSIGNMENTS ////////////
assign signal_o = (state == s_out);

endmodule

