module YCbCr2RGB (
    input clk,
    input reset,
    input [7:0] y,
    input [7:0] cb,
    input [7:0] cr,
    output reg [9:0] r,
    output reg [9:0] g,
    output reg [9:0] b,
    output reg data_valid
);

// Internal signals
reg signed [9:0] r_temp;
reg signed [9:0] g_temp;
reg signed [9:0] b_temp;

// Constants
parameter signed [9:0] k1 = 1.402 * 256;
parameter signed [9:0] k2 = 0.34414 * 256;
parameter signed [9:0] k3 = 0.71414 * 256;
parameter signed [9:0] k4 = 1.772 * 256;

always @(posedge clk) begin
    if (reset) begin
        r <= 0;
        g <= 0;
        b <= 0;
        data_valid <= 0;
    end else begin
        r_temp <= y + ((cr - 128) * k1 / 256);
        g_temp <= y - ((cb - 128) * k2 / 256) - ((cr - 128) * k3 / 256);
        b_temp <= y + ((cb - 128) * k4 / 256);

        if (r_temp < 0) begin
            r <= 0;
        end else if (r_temp > 1023) begin
            r <= 1023;
        end else begin
            r <= r_temp;
        end

        if (g_temp < 0) begin
            g <= 0;
        end else if (g_temp > 1023) begin
            g <= 1023;
        end else begin
            g <= g_temp;
        end

        if (b_temp < 0) begin
            b <= 0;
        end else if (b_temp > 1023) begin
            b <= 1023;
        end else begin
            b <= b_temp;
        end

        data_valid <= 1;
    end
end

endmodule

module rc4(
  input clk,
  input rst_n,
  input control_in,
  input write,
  input read,
  input [7:0] keylength,
  input [7:0] keydata,
  output control_out,
  output reg [7:0] streamvalue
);

reg [7:0] state [0:255];
reg [7:0] key [0:255];
reg [7:0] i, j;
reg [7:0] keystream [0:255];
reg [7:0] plaintext [0:255];
reg [7:0] ciphertext [0:255];
reg [7:0] count;
reg [7:0] temp;

assign control_out = count == keylength;

always @(posedge clk) begin
  if (!rst_n) begin
    i <= 0;
    j <= 0;
    count <= 0;
    streamvalue <= 0;
  end else begin
    if (write) begin
      key[count] <= keydata;
      count <= count + 1;
    end
    if (control_in) begin
      if (count == keylength) begin
        for (i = 0; i < 256; i = i + 1) begin
          state[i] <= i;
          keystream[i] <= 0;
        end
        j <= 0;
        for (i = 0; i < 256; i = i + 1) begin
          j <= (j + state[i] + key[i % keylength]) & 255;
          temp <= state[i];
          state[i] <= state[j];
          state[j] <= temp;
        end
        i <= 0;
        j <= 0;
        count <= 0;
      end
    end else begin
      if (read) begin
        streamvalue <= keystream[i] ^ plaintext[i];
        i <= i + 1;
      end else begin
        plaintext[i] <= streamvalue;
        keystream[i] <= state[i];
        ciphertext[i] <= keystream[i] ^ plaintext[i];
        i <= i + 1;
        j <= (j + state[i] + key[i % keylength]) & 255;
        temp <= state[i];
        state[i] <= state[j];
        state[j] <= temp;
      end
    end
  end
end

endmodule

module digital_clock(clk, 
                     led_gnd1, led_gnd2, 
                     led6, led7, led8, led9, led10, led12, led13, led15, led16, led17, led18, led19, led20, led21,
                     led_second_tick);

  input wire clk;
  output wire led_gnd1, led_gnd2;
  output wire led6, led7, led8, led9, led10, led12, led13, led15, led16, led17, led18, led19, led20, led21, led_second_tick;

  // Counter for seconds
  reg [5:0] sec_count = 6'b0;
  always @(posedge clk) begin
    sec_count <= sec_count + 1;
  end

  // Counter for minutes
  reg [5:0] min_count = 6'b0;
  always @(posedge clk) begin
    if (sec_count == 60) begin
      min_count <= min_count + 1;
    end
  end

  // Counter for hours
  reg [4:0] hour_count = 5'b0;
  always @(posedge clk) begin
    if (min_count == 60 && sec_count == 60) begin
      hour_count <= hour_count + 1;
    end
  end

  // 7-segment decoder module
  bcd2seg sseg(.sin({hour_count, min_count, sec_count}), .sout({led21, led20, led19, led18, led17, led16, led15, led13, led12, led10, led9, led8, led7, led6}));

  // One second tick indicator
  reg [14:0] tick_count = 15'd0;
  always @(posedge clk) begin
    tick_count <= tick_count + 1;
    led_second_tick <= tick_count[14];
  end

  // Ground connections for 7-segment display
  assign led_gnd1 = 1'b0;
  assign led_gnd2 = 1'b1;

endmodule

