    if (!rstn) begin
      status <= 1'b0;
      c <= {32'h0, 32'h0, 32'h0, 32'h0};
    end else begin
      if (ab == 3'b001) begin
        status <= 1'b1;
        c_temp[0] <= 16'hFFFF;
      end else begin
        status <= 1'b0;
        c_temp[0] <= c[0];
      end
      c_temp[1] <= c[1];
