module four_bit_adder (
    A,
    B,
    Cin,
    S,
    Cout
);

    input [3:0] A, B;
    input Cin;
    output [3:0] S;
    output Cout;

    wire [3:0] C;

    sky130_fd_sc_lp__udp_dlatch$P dlatch0 (
        .Q(C[0]),
        .D(Cin),
        .GATE(1)
    );

    assign S[0] = A[0] ^ B[0] ^ Cin;
    sky130_fd_sc_lp__udp_dlatch$P dlatch1 (
        .Q(C[1]),
        .D(A[0] & B[0]),
        .GATE(1)
    );

    assign S[1] = A[1] ^ B[1] ^ C[0];
    sky130_fd_sc_lp__udp_dlatch$P dlatch2 (
        .Q(C[2]),
        .D(A[1] & B[1]),
        .GATE(1)
    );

    assign S[2] = A[2] ^ B[2] ^ C[1];
    sky130_fd_sc_lp__udp_dlatch$P dlatch3 (
        .Q(C[3]),
        .D(A[2] & B[2]),
        .GATE(1)
    );

    assign S[3] = A[3] ^ B[3] ^ C[2];
    assign Cout = C[3];

endmodule

