module full_adder (
    input A,
    input B,
    input Cin,
    output S,
    output Cout
);

    wire w1;
    wire w2;

    xor x1 (
        .A(A),
        .B(B),
        .Y(w1)
    );

    xor x2 (
        .A(w1),
        .B(Cin),
        .Y(S)
    );

    and a1 (
        .A(A),
        .B(B),
        .Y(w2)
    );

    and a2 (
        .A(w1),
        .B(Cin),
        .Y(Cout)
    );

