module top_module (
    input [15:0] A,
    input [15:0] B,
    input [1:0] format,
    input [2:0] C,
    output [15:0] C_fp,
    output reg [2:0] C_gray
);

    // Declare internal signals
    wire [31:0] A_fp;
    wire [31:0] B_fp;
    wire [31:0] C_fp_32;
    wire [63:0] C_fp_64;
    wire [31:0] C_gray_32;
    wire [63:0] C_gray_64;

    // Convert A and B to floating-point format
    fp_converter fp_A(A_fp, A, format);
    fp_converter fp_B(B_fp, B, format);

    // Add A_fp and B_fp
    fp_adder fp_add(C_fp_32, C_fp_64, A_fp, B_fp, format);

    // Convert C_fp to Gray code
    gray_converter gray_C(C_gray_32, C_gray_64, C_fp_32, C_fp_64);

    // Output C_fp and C_gray
    assign C_fp = (format == 0) ? C_fp_32[15:0] : C_fp_64[31:16];
    always @(*) begin
        if (format == 0) begin
            C_gray = C_gray_32[2:0];
