// Floating-point converter module
module fp_converter (
    output reg [31:0] fp,
    input [15:0] input_num,
    input [1:0] format
);

    // Declare internal signals
    wire [10:0] exp;
    wire [22:0] frac;

    // Convert input_num to exponent and fraction
    assign exp = input_num[15:11] - 15 + 127;
    assign frac = {1'b1, input_num[10:0]};

    // Convert to single-precision or double-precision format
    always @(*) begin
        if (format == 0) begin
            fp = {input_num[15], exp, frac[22:0]};
        end else begin
            fp = {input_num[15], exp[10:0], frac[22:0], {9{1'b0}}};
        end
    end

endmodule

module traffic_light(
    input clk, reset, ped_button, car_sensor,
    output reg car_green, car_yellow, car_red,
    output reg ped_green, ped_yellow, ped_red
);

// Define states
parameter S1 = 2'b00;
parameter S2 = 2'b01;
parameter S3 = 2'b10;
parameter S4 = 2'b11;

// Define state register and initialize to S1
reg [1:0] state = S1;

// Define counter for state transitions
reg [3:0] counter = 0;

// Define car sensor debounce counter
reg [2:0] debounce_counter = 0;

// Define constants for state timings
parameter S1_TIME = 10_000_000; // 10 seconds
parameter S2_TIME = 2_000_000; // 2 seconds
parameter S4_TIME = 5_000_000; // 5 seconds

// Define constants for flashing yellow light
parameter FLASH_PERIOD = 500_000; // 500 ms
parameter FLASH_DUTY_CYCLE = 50; // 50%

always @(posedge clk) begin
    if (reset) begin
        // Initialize all outputs to default state
        car_green <= 1'b1;
        car_yellow <= 1'b0;
        car_red <= 1'b0;
        ped_green <= 1'b0;
        ped_yellow <= 1'b0;
        ped_red <= 1'b1;

        // Reset state and counters
        state <= S1;
        counter <= 0;
        debounce_counter <= 0;
    end else begin
        // Increment debounce counter if car sensor is high
        if (car_sensor) begin
            debounce_counter <= debounce_counter + 1;
        end else begin
            debounce_counter <= 0;
        end

        // State machine logic
        case (state)
            S1: begin
                // Green light for cars, red light for pedestrians
                car_green <= 1'b1;
                car_yellow <= 1'b0;
                car_red <= 1'b0;
                ped_green <= 1'b0;
                ped_yellow <= 1'b0;
                ped_red <= 1'b1;

                // Check for pedestrian button press
                if (ped_button) begin
                    state <= S3;
                    counter <= 0;
                end else if (counter == S1_TIME) begin
                    state <= S2;
                    counter <= 0;
                end else begin
                    counter <= counter + 1;
                end
            end

            S2: begin
                // Yellow light for cars, red light for pedestrians
                car_green <= 1'b0;
                car_yellow <= 1'b1;
                car_red <= 1'b0;
                ped_green <= 1'b0;
                ped_yellow <= 1'b0;
                ped_red <= 1'b1;

                if (counter == S2_TIME) begin
                    state <= S3;
                    counter <= 0;
                end else begin
                    counter <= counter + 1;
                end
            end

            S3: begin
                // Red light for cars, green light for pedestrians
                car_green <= 1'b0;
                car_yellow <= 1'b0;
                car_red <= 1'b1;
                ped_green <= 1'b1;
                ped_yellow <= 1'b0;
                ped_red <= 1'b0;

                if (car_sensor && debounce_counter == 3'b111) begin
                    // Car detected, stay in state 3
                end else begin
                    state <= S4;
                    counter <= 0;
                end
            end

            S4: begin
                // Red light for cars, flashing yellow light for pedestrians
                car_green <= 1'b0;
                car_yellow <= 1'b0;
                car_red <= 1'b1;

                if (counter < FLASH_PERIOD * FLASH_DUTY_CYCLE / 100) begin
                    ped_green <= 1'b0;
                    ped_yellow <= 1'b0;
                    ped_red <= 1'b1;
                end else if (counter < FLASH_PERIOD) begin
                    ped_green <= 1'b0;
                    ped_yellow <= 1'b1;
                    ped_red <= 1'b0;
                end else begin
                    counter <= 0;
                end

                if (counter == S4_TIME) begin
                    state <= S1;
                    counter <= 0;
                end else begin
                    counter <= counter + 1;
                end
            end
        endcase
    end
end

endmodule

module MUX4
(
  A,
  B,
  C,
  D,
  S0,
  S1,
  Z
);

  input A, B, C, D, S0, S1;
  output Z;

  wire not_S0, not_S1;

  assign not_S0 = ~S0;
  assign not_S1 = ~S1;

  assign Z = (A & not_S0 & not_S1) | (B & not_S0 & S1) | (C & S0 & not_S1) | (D & S0 & S1);

endmodule

module data_transfer(
    input input_clk,
    input output_clk,
    input [7:0] input_data,
    output [7:0] output_data,
    output empty,
    output full
);

    // Inputs
    reg [6:0] vector_in;
    reg reset;
    reg clk;

    // Outputs
    wire [3:0] data_out;
    wire empty_flag;
    wire full_flag;

    reg [3:0] data[3:0];
    reg [3:0] count;

    // Instantiate the FIFO module
    fifo fifo (
        .data_out(data_out), 
        .empty_flag(empty_flag), 
        .full_flag(full_flag), 
        .vector_in(vector_in), 
        .reset(reset), 
        .clk(clk)
    );

    // Initialize Inputs
    initial begin
        vector_in = 0;
        clk = 1;
        reset = 1;
        count = 0;
    end

    // Clock generator
    always #1 clk = ~clk;

    // Write data to FIFO buffer
    always @(posedge input_clk) begin
        if (!full_flag) begin
            vector_in = {2'b10, input_data};
            full <= 0;
        end else begin
            full <= 1;
        end
    end

    // Read data from FIFO buffer
    always @(posedge output_clk) begin
        if (!empty_flag) begin
            output_data <= data_out;
            empty <= 0;
        end else begin
            empty <= 1;
        end
    end

    // FIFO control
    always @(posedge clk) begin
        if (full_flag) begin
            vector_in = 7'b00_0000_1;
        end else if (empty_flag) begin
            vector_in = 7'b00_0001_0;
        end else begin
            vector_in = {2'b01, data[count]};
            count <= count + 1;
        end
    end

endmodule

