    wire [2:0] a_pipe, b_pipe, cin_pipe;
    wire [1:0] p_pipe, g_pipe;
    wire [2:0] c1_pipe, c2_pipe;

    assign a_pipe[0] = a;
    assign b_pipe[0] = b;
    assign cin_pipe[0] = cin;

    full_adder_pipeline fa1(.a(a_pipe[0]), .b(b_pipe[0]), .cin(cin_pipe[0]), .cout(c1_pipe[0]), .sum(p_pipe[0]));
    full_adder_pipeline fa2(.a(a_pipe[1]), .b(b_pipe[1]), .cin(c1_pipe[1]), .cout(c2_pipe[0]), .sum(p_pipe[1]));
    full_adder_pipeline fa3(.a(a_pipe[2]), .b(b_pipe[2]), .cin(c1_pipe[2]), .cout(cout), .sum(p_pipe[2]));

    assign g_pipe[0] = cin;
    assign g_pipe[1] = c1_pipe[0];
    assign g_pipe[2] = c2_pipe[0];

    assign c1_pipe[1] = g_pipe[0] & p_pipe[0];
    assign c1_pipe[2] = g_pipe[1] & p_pipe[1];

    assign c2_pipe[1] = g_pipe[0] & c1_pipe[0];
    assign c2_pipe[2] = g_pipe[1] & c1_pipe[1];

    assign sum = p_pipe[2];
    assign cout = g_pipe[2] | c1_pipe[2];

