reg [3:0] B_reg;
reg S_reg;
reg [15:0] P_reg;

always @(posedge clk) begin
    A_reg <= A;
    B_reg <= B;
    S_reg <= S;
end

always @(posedge clk) begin
    if (B_reg != 0) begin
        if (S_reg == 0) begin
            P_reg <= {A_reg[B_reg-1:0], 16'b0};
        end else begin
            P_reg <= {16{A_reg[15]}};
            P_reg <= {P_reg[B_reg-1:0], A_reg[15:B_reg]};
        end
    end else begin
        P_reg <= A_reg;
    end
end

assign P = P_reg;

endmodule

