module up_down_counter (
    input clk,
    input reset,
    input up_down,
    input load,
    output reg [2:0] out
);

    // Define internal wires
    reg [2:0] counter;

    // Counter logic
    always @(posedge clk) begin
        if (reset) begin
            counter <= 3'b000;
        end else if (load) begin
            counter <= 3'b000;
        end else if (up_down) begin
            counter <= counter + 1;
        end else begin
            counter <= counter - 1;
        end
    end

    // Output logic
    assign out = counter;

