module reset_synchronizer (
  input rst_n,
  input clk,
  output reg rst
);

parameter n = 3; // number of stages in the synchronizer

reg [n-1:0] sync_rst;
wire [n-1:0] sync_rst_next;

// First stage
always @(posedge clk or negedge rst_n) begin
  if (~rst_n) begin
    sync_rst[0] <= 1'b0;
  end else begin
    sync_rst[0] <= rst_n;
  end
end

// Intermediate stages
genvar i;
generate
  for (i = 1; i < n; i = i + 1) begin : stage
    always @(posedge clk) begin
      sync_rst[i] <= sync_rst[i-1];
    end
  end
endgenerate

// Last stage
assign sync_rst_next = {sync_rst[n-2:0], sync_rst[n-1]};
always @(posedge clk) begin
  rst <= sync_rst_next[n-1];
end

endmodule

