module parity_encoder (
    input [7:0] data_in, // 8-bit input data
    output reg [8:0] parity_out // 9-bit output with parity bit added
);

    integer i;
    reg [7:0] data_temp;
    reg parity_bit;

    always @(*) begin
        data_temp = data_in;
        parity_bit = 1;
        for (i = 0; i < 8; i = i + 1) begin
            parity_bit = parity_bit ^ data_temp[0];
            data_temp = data_temp >> 1;
        end
        parity_out = {data_in, parity_bit};
    end

endmodule

module priority_encoder (
    input [7:0] in0, in1, in2, in3, // Four 8-bit unsigned numbers
    output reg [7:0] min_out // Minimum value among the four inputs
);

    always @(*) begin
        if (in0 < in1 && in0 < in2 && in0 < in3) begin
            min_out = in0;
        end else if (in1 < in2 && in1 < in3) begin
            min_out = in1;
        end else if (in2 < in3) begin
            min_out = in2;
        end else begin
            min_out = in3;
        end
    end

endmodule

module final_module (
    input [7:0] a, b, c, d, // Four 8-bit unsigned numbers
    input clk, // Clock input
    output reg [8:0] out // Output 9-bit byte with parity bit added
);

    wire [7:0] min_value;
    wire [8:0] parity_value;

    priority_encoder pe(
        .in0(a),
        .in1(b),
        .in2(c),
        .in3(d),
        .min_out(min_value)
    );

    parity_encoder p(
        .data_in(min_value),
        .parity_out(parity_value)
    );

    always @(posedge clk) begin
        out <= parity_value;
    end

endmodule

module twos_complement(
    input [3:0] in,
    output [3:0] out
);

wire [3:0] inv;
wire [3:0] add_one;

// invert all bits of input
assign inv = ~in;

// add 1 to inverted input
assign add_one = inv + 4'b0001;

// assign result to output
assign out = add_one;

endmodule

module pipeline_module(
    input wire [15:0] in,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo
);

reg [15:0] stage1_out;
reg [7:0] stage2_out_hi, stage2_out_lo;

// Stage 1: Barrel Shifter
always @(*) begin
    stage1_out = in >> 8;
end

// Stage 2: Multiplexer
always @(*) begin
    if (in[15:8] == 8'b00000000) begin
        stage2_out_hi = stage1_out[7:0];
        stage2_out_lo = 8'b00000000;
    end else begin
        stage2_out_hi = 8'b00000000;
        stage2_out_lo = stage1_out[15:8];
    end
end

// Output
assign out_hi = stage2_out_hi;
assign out_lo = stage2_out_lo;

endmodule

