module prio_enc #(
  parameter WIDTH_LOG = 4
) (input [WIDTH-1:0] x, output reg [WIDTH_LOG-1:0] msb);

localparam WIDTH = 1 << WIDTH_LOG;
localparam HI = WIDTH - 1;

wire [WIDTH_LOG-1:0] msb_intermediate [WIDTH_LOG-1:0];
reg [HI:0] x_intermediate;

// Split x into WIDTH_LOG subwords
generate
  genvar i;
  for (i = 0; i < WIDTH_LOG; i = i + 1) begin : split
    assign msb_intermediate[i] = x[(i+1)*WIDTH/(WIDTH_LOG+1)-1:i*WIDTH/(WIDTH_LOG+1)];
  end
endgenerate

// Compute the MSB of each subword
generate
  genvar i;
  for (i = 0; i < WIDTH_LOG; i = i + 1) begin : compute_msb
    localparam WIDTH_i = (i == WIDTH_LOG-1) ? (HI - i*WIDTH/(WIDTH_LOG+1) + 1) : (WIDTH/(WIDTH_LOG+1));
    wire [WIDTH_LOG-1:0] msb_i;
    assign msb_i = msb_intermediate[i];
    assign msb_i[0] = |msb_i[0:WIDTH_i-1];
    assign msb_i[1:WIDTH_LOG-1] = msb_intermediate[i][1:WIDTH_LOG-1] | msb_i[0:WIDTH_LOG-2];
    assign msb_intermediate[i] = msb_i;
  end
endgenerate

// Combine the MSBs of the subwords
generate
  genvar i;
  for (i = 0; i < WIDTH_LOG; i = i + 1) begin : combine_msb
    localparam WIDTH_i = (i == WIDTH_LOG-1) ? (HI - i*WIDTH/(WIDTH_LOG+1) + 1) : (WIDTH/(WIDTH_LOG+1));
    assign x_intermediate[(i+1)*WIDTH/(WIDTH_LOG+1)-1:i*WIDTH/(WIDTH_LOG+1)] = msb_intermediate[i][WIDTH_i-1:0] << (WIDTH_i*i);
  end
endgenerate

// Compute the MSB of the combined subwords
always @* begin
  msb = 0;
  for (i = WIDTH_LOG-1; i >= 0; i = i - 1) begin
    if (|(x_intermediate >> (i*WIDTH/(WIDTH_LOG+1))))
      msb[i] = 1;
    x_intermediate = msb[i] ? x_intermediate >> (i*WIDTH/(WIDTH_LOG+1)) : x_intermediate & ((1'd1 << (i*WIDTH/(WIDTH_LOG+1))) - 1'd1);
  end
end

endmodule

