            encoded <= 4'b0000;
        end else begin
            if (data == 16'b0000_0000_0000_0000) begin
                encoded <= 4'b0000;
            end else if (data[7:0] != 8'b0000_0000) begin
                case (data[7:0])
                    8'b1000_0000: encoded <= 4'b0001;
                    8'b0100_0000: encoded <= 4'b0010;
                    8'b0010_0000: encoded <= 4'b0011;
                    8'b0001_0000: encoded <= 4'b0100;
