                    8'b0000_0100: encoded <= 4'b0110;
                    8'b0000_0010: encoded <= 4'b0111;
                    8'b0000_0001: encoded <= 4'b1000;
                endcase
            end else if (data[15:8] != 8'b0000_0000) begin
                case (data[15:8])
                    8'b1000_0000: encoded <= 4'b1011;
                    8'b0100_0000: encoded <= 4'b1010;
                    8'b0010_0000: encoded <= 4'b1001;
                    8'b0001_0000: encoded <= 4'b1000;
                    8'b0000_1000: encoded <= 4'b0111;
                    8'b0000_0100: encoded <= 4'b0110;
                    8'b0000_0010: encoded <= 4'b0101;
                    8'b0000_0001: encoded <= 4'b0100;
                endcase
                if (data[7:0] != 8'b0000_0000 && data[15:8] > data[7:0]) begin
                    encoded <= encoded + 1;
                end
            end else begin
                encoded <= 4'b0000;
            end
