            3'b100: result = {4'b0100, counter};
            3'b101: result = {4'b0101, counter};
            3'b110: result = {4'b0110, counter};
            3'b111: result = {4'b0111, counter};
        endcase
    end

    // Output Y
    always @(*) begin
        case (decoder_out)
            3'b000: Y = 8'b11111110;
            3'b001: Y = 8'b11111101;
            3'b010: Y = 8'b11111011;
            3'b011: Y = 8'b11110111;
            3'b100: Y = 8'b11101111;
            3'b101: Y = 8'b11011111;
            3'b110: Y = 8'b10111111;
            3'b111: Y = 8'b01111111;
        endcase
    end

endmodule

