module uart_transmitter (
  input clk,
  input rst,
  input [7:0] data_in,
  output tx
);

  reg [9:0] shift_reg;
  reg start_bit;
  reg stop_bit;
  reg [3:0] bit_count;

  always @ (posedge clk) begin
    if (rst) begin
      shift_reg <= 10'b0;
      bit_count <= 4'b0;
      start_bit <= 1'b0;
      stop_bit <= 1'b1;
    end else begin
      if (bit_count == 4'b0) begin
        shift_reg <= {start_bit, data_in, stop_bit};
        bit_count <= 4'b1;
      end else if (bit_count < 4'b10) begin
        shift_reg <= {shift_reg[8:0], 1'b0};
        bit_count <= bit_count + 1;
      end else begin
        shift_reg <= {shift_reg[8:0], 1'b1};
        bit_count <= 4'b0;
      end
    end
  end

  assign tx = shift_reg[0];

endmodule

module uart_receiver (
  input clk,
  input rst,
  input rx,
  output reg [7:0] data_out
);

  reg [9:0] shift_reg;
  reg start_bit;
  reg stop_bit;
  reg [3:0] bit_count;

  always @ (posedge clk) begin
    if (rst) begin
      shift_reg <= 10'b0;
      bit_count <= 4'b0;
      start_bit <= 1'b0;
      stop_bit <= 1'b0;
      data_out <= 8'b0;
    end else begin
      if (bit_count == 4'b0) begin
        start_bit <= rx;
        bit_count <= 4'b1;
      end else if (bit_count < 4'b10) begin
        shift_reg <= {shift_reg[8:0], rx};
        bit_count <= bit_count + 1;
      end else begin
        stop_bit <= rx;
        data_out <= shift_reg[8:1];
        bit_count <= 4'b0;
      end
    end
  end

endmodule

module dffr_s (din, clk, rst, q, se, si, so);
// synopsys template

parameter SIZE = 1;

input	[SIZE-1:0]	din ;	// data in
input			clk ;	// clk or scan clk
input			rst ;	// reset

output	[SIZE-1:0]	q ;	// output

input			se ;	// scan-enable
input	[SIZE-1:0]	si ;	// scan-input
output	[SIZE-1:0]	so ;	// scan-output

reg 	[SIZE-1:0]	q ;

`ifdef NO_SCAN
always @ (posedge clk)
	q[SIZE-1:0]  <= ((rst) ? {SIZE{1'b0}}  : din[SIZE-1:0] );
`else

// Scan-Enable dominates
always @ (posedge clk)

	q[SIZE-1:0]  <= se ? si[SIZE-1:0] : ((rst) ? {SIZE{1'b0}}  : din[SIZE-1:0] );

assign so[SIZE-1:0] = q[SIZE-1:0] ;
`endif

endmodule

module dma_controller(
    input clk,
    input rst_n,
    input start,
    input rnw_in,
    input ack,
    input done,
    output reg inprogress,
    output reg req,
    output reg rnw
);

    initial begin
        inprogress = 0;
        req = 0;
        rnw = 1;
    end

    always @(negedge rst_n) begin
        disable main_loop;
        req <= 0;
        rnw <= 1;
        inprogress <= 0;
    end

    always begin : main_loop
        wait(rst_n);
        wait(start);

        begin : dma_loop
            forever begin
                inprogress <= 1;
                rnw <= rnw_in;
                req <= 1;

                @(negedge ack);
                if (!start) disable dma_loop;
            end
        end

        req <= 0;
        wait(done);
        inprogress <= 0;
    end

endmodule

