module compare_fp(
    input [31:0] a,
    input [31:0] b,
    input [1:0] op,
    output reg lt,
    output reg eq,
    output reg gt,
    output reg unordered,
    output reg [4:0] exceptionFlags
);

    // extract sign, exponent, and significand bits from input numbers
    wire [31:0] a_sign = a[31];
    wire [7:0] a_exp = a[30:23];
    wire [22:0] a_sig = a[22:0];
    wire [31:0] b_sign = b[31];
    wire [7:0] b_exp = b[30:23];
    wire [22:0] b_sig = b[22:0];

    // check for special values
    wire a_is_nan = (a_exp == 255) && (a_sig != 0);
    wire b_is_nan = (b_exp == 255) && (b_sig != 0);
    wire a_is_inf = (a_exp == 255) && (a_sig == 0);
    wire b_is_inf = (b_exp == 255) && (b_sig == 0);

    // determine comparison result based on operation code
    always @(*) begin
        case (op)
            0: begin // less than
                if (a_is_nan || b_is_nan) begin
                    lt = 0;
                    eq = 0;
                    gt = 0;
                    unordered = 1;
                    exceptionFlags = 8; // invalid operation
                end else if (a_is_inf && b_is_inf) begin
                    lt = 0;
                    eq = 1;
                    gt = 0;
                    unordered = 0;
                    exceptionFlags = 0;
                end else if (a_sign != b_sign) begin
                    lt = (a_sign == 1);
                    eq = 0;
                    gt = (b_sign == 1);
                    unordered = 0;
                    exceptionFlags = 0;
                end else if (a_exp != b_exp) begin
                    lt = (a_sign == 1) ^ (a_exp > b_exp);
                    eq = 0;
                    gt = (b_sign == 1) ^ (a_exp < b_exp);
                    unordered = 0;
                    exceptionFlags = 0;
                end else if (a_sig != b_sig) begin
                    lt = (a_sign == 1) ^ (a_sig > b_sig);
                    eq = 0;
                    gt = (b_sign == 1) ^ (a_sig < b_sig);
                    unordered = 0;
                    exceptionFlags = 0;
                end else begin // a == b
                    lt = 0;
                    eq = 1;
                    gt = 0;
                    unordered = 0;
                    exceptionFlags = 0;
                end
            end
            1: begin // less than or equal to
                if (a_is_nan || b_is_nan) begin
                    lt = 0;
                    eq = 0;
                    gt = 0;
                    unordered = 1;
                    exceptionFlags = 8; // invalid operation
                end else if (a_is_inf && b_is_inf) begin
                    lt = 1;
                    eq = 1;
                    gt = 1;
                    unordered = 0;
                    exceptionFlags = 0;
                end else if (a_sign != b_sign) begin
                    lt = (a_sign == 1);
                    eq = 0;
                    gt = (b_sign == 1);
                    unordered = 0;
                    exceptionFlags = 0;
                end else if (a_exp != b_exp) begin
                    lt = (a_sign == 1) ^ (a_exp > b_exp);
                    eq = 0;
                    gt = (b_sign == 1) ^ (a_exp < b_exp);
                    unordered = 0;
                    exceptionFlags = 0;
                end else if (a_sig != b_sig) begin
                    lt = (a_sign == 1) ^ (a_sig > b_sig);
                    eq = 0;
                    gt = (b_sign == 1) ^ (a_sig < b_sig);
                    unordered = 0;
                    exceptionFlags = 0;
                end else begin // a == b
                    lt = 1;
                    eq = 1;
                    gt = 1;
                    unordered = 0;
                    exceptionFlags = 0;
                end
            end
            2: begin // equal to
                if (a_is_nan || b_is_nan) begin
                    lt = 0;
                    eq = 0;
                    gt = 0;
                    unordered = 1;
                    exceptionFlags = 8; // invalid operation
                end else if (a_is_inf && b_is_inf) begin
                    lt = 0;
                    eq = 1;
                    gt = 0;
                    unordered = 0;
                    exceptionFlags = 0;
                end else if (a_sign != b_sign) begin
                    lt = 0;
                    eq = 0;
                    gt = 0;
                    unordered = 0;
                    exceptionFlags = 0;
                end else if (a_exp != b_exp) begin
                    lt = 0;
                    eq = 0;
                    gt = 0;
                    unordered = 0;
                    exceptionFlags = 0;
                end else if (a_sig != b_sig) begin
                    lt = 0;
                    eq = 0;
                    gt = 0;
                    unordered = 0;
                    exceptionFlags = 0;
                end else begin // a == b
                    lt = 0;
                    eq = 1;
                    gt = 0;
                    unordered = 0;
                    exceptionFlags = 0;
                end
            end
            default: begin
                lt = 0;
                eq = 0;
                gt = 0;
                unordered = 0;
                exceptionFlags = 1; // unsupported operation
            end
        endcase
    end

endmodule

module VerificadorSentidoMovimiento(
		_clk_,
		FSM_ready_in,
		piso_actual, 
		solicitud_ps,
		solicitud_p1,
		solicitud_p2,
