						if (solicitud_ps == 2'b0x | solicitud_p1 == 2'b0x | solicitud_p2 == 2'b0x)
							begin
							accion <= 2'b11;
							accion <= 2'b10;
							end
					end

				//acciones para el piso 4
				else if (piso_actual == 3'b100)
					begin
						if (solicitud_p4 == 2'b1x) //No realiza accion
							accion <= 2'b00;
						if (solicitud_p4 == 2'b0x)
							begin
