module priority_encoder( 
    input [2:0] in, // 3-bit input for the decoder
    input [3:0] data, // 4-bit input vector for the multiplexer
    input enable, // Active-low enable for the multiplexer
    output [1:0] out // 2-bit final output from the comparator
);

    // 3:4 decoder
    wire [3:0] dec_out;
    assign dec_out = {~in[2], ~in[1], ~in[0], 1'b0};

    // Barrel shifter-based 256-to-1 multiplexer
    wire [7:0] mux_out;
    wire [7:0] shifted_data;
    assign shifted_data = {data, 4'b0};
    assign mux_out = shifted_data >> dec_out;

    // Comparator
    wire [3:0] priority;
    assign priority = mux_out & (enable ? 8'b1111 : 8'b0000);
    assign out = (priority > dec_out[1:0]) ? 2'b10 :
                (priority > dec_out[0]) ? 2'b01 :
                2'b00;

endmodule

