module pulse_width_detection(
    input               clk,
    input               rst_n,
    input               a,
    output reg          pulse,
    output reg          no_pulse
);

parameter THRESHOLD = 10; // Set the threshold for pulse width detection

reg [7:0] counter; // Counter to count the pulse width
reg        detect;  // Flag to indicate whether the pulse width exceeds the threshold

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        counter <= 8'd0;
        detect  <= 1'b0;
    end else begin
        if (a) begin
            counter <= counter + 1;
            if (counter >= THRESHOLD) begin
                detect <= 1'b1;
            end
        end else begin
            counter <= 8'd0;
            detect  <= 1'b0;
        end
    end
end

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        pulse    <= 1'b0;
        no_pulse <= 1'b1;
    end else begin
        if (detect) begin
            pulse    <= 1'b1;
            no_pulse <= 1'b0;
        end else begin
            pulse    <= 1'b0;
            no_pulse <= 1'b1;
        end
    end
end

endmodule

module multiplexer(
    input               [3:0] in [0:255],
    input               [7:0] sel,
    output reg          [3:0] out
);

reg [7:0] sel_decoded [0:255]; // Array to store the decoded select signals

generate
    // Generate the 256 2-to-1 multiplexers
    genvar i;
    for (i = 0; i < 256; i = i + 1) begin : mux
        always @(sel) begin
            if (sel == i) begin
                out <= in[i];
            end
        end
    end

    // Generate the decoder for the select input
    genvar j;
    for (j = 0; j < 256; j = j + 1) begin : decoder
        always @(sel) begin
            if (sel == j) begin
                sel_decoded[j] <= 1'b1;
            end else begin
                sel_decoded[j] <= 1'b0;
            end
        end
    end
endgenerate

endmodule

