module binary_to_bcd (
  input [n-1:0] in,
  output reg [m-1:0] out
);

parameter n = 8; // number of bits in the binary number
parameter m = 4 * (($ceil(log10(2**n)))); // number of bits in the BCD number

integer i;
reg [3:0] bcd_digit;
reg [n-1:0] temp;

always @(*) begin
  temp = in;
  out = 0;

  for (i = 0; i < n; i = i + 1) begin
    // Shift out each BCD digit
    bcd_digit = 0;
    while (temp >= 10) begin
      temp = temp - 10;
      bcd_digit = bcd_digit + 1;
    end

    // Concatenate the BCD digits
    out = (out << 4) | bcd_digit;
    temp = temp << 1;
  end
end

endmodule

