module arb_block (
  input [n-1:0] req,
  output grant
);

parameter n = 4; // number of request signals

wire [n-1:0] req_priority;
wire [n-1:0] req_active;
wire [n-1:0] req_priority_active;

// Define the priority scheme as a Boolean function of the input signals
assign req_priority[0] = req[0];
assign req_priority[1] = req[1] & !req[0];
assign req_priority[2] = req[2] & !req[0] & !req[1];
assign req_priority[3] = req[3] & !req[0] & !req[1] & !req[2];

// Determine which requests are currently active
assign req_active = req & req_priority;

// Determine the highest priority request that is currently active
priority_encoder pe (
  .in(req_active),
  .out(req_priority_active)
);

// Generate the grant signal
assign grant = req_priority_active[0];

endmodule

// Priority encoder module
module priority_encoder (
  input [n-1:0] in,
  output [log2(n)-1:0] out
);

parameter n = 4; // number of input signals

wire [n-1:0] in_active;
wire [n-1:0] in_priority;

// Determine which inputs are currently active
assign in_active = in & ((1 << n) - 1);

// Determine the priority of the active inputs
assign in_priority = $onehot0(in_active);

// Determine the highest priority input
assign out = $priority(in_priority);

endmodule

