module azimuth_signal_generator (
    input EN,
    input TRIG,
    input CLK_PE,
    input SYS_CLK,
    input [3199:0] DATA,
    output wire GEN_SIGNAL
);

    reg [31:0] counter;
    reg [31:0] index;
    reg [31:0] period;
    reg [31:0] data_index;
    reg [31:0] data;
    reg [31:0] state;
    reg [31:0] trig_count;
    reg [31:0] trig_period;
    reg [31:0] us_period;
    reg clk_prev;
    reg trig_prev;
    wire clk_rise;
    wire trig_rise;

    parameter STATE_IDLE = 0;
    parameter STATE_TRIG = 1;
    parameter STATE_GEN = 2;

    assign GEN_SIGNAL = (state == STATE_GEN) ? data[31] : 1'b0;

    always @(posedge SYS_CLK) begin
        if (EN) begin
            if (state == STATE_IDLE) begin
                if (TRIG && !trig_prev) begin
                    state = STATE_TRIG;
                    trig_count = 0;
                end
            end else if (state == STATE_TRIG) begin
                if (trig_count >= trig_period) begin
                    state = STATE_GEN;
                    counter = 0;
                    index = 0;
                    period = 10;
                    data_index = 0;
                    data = DATA[0];
                end else begin
                    trig_count = trig_count + 1;
                end
            end else if (state == STATE_GEN) begin
                if (counter >= period) begin
                    counter = 0;
                    index = index + 1;
                    if (index >= 4) begin
                        index = 0;
                        data_index = data_index + 1;
                        data = DATA[data_index];
                    end
                end else begin
                    counter = counter + 1;
                end
            end
        end else begin
            state = STATE_IDLE;
        end
        trig_prev = TRIG;
    end

    edge_detect ed_clk (
        .async_sig(CLK_PE),
        .clk(SYS_CLK),
        .rise(clk_rise)
    );

    edge_detect ed_trig (
        .async_sig(TRIG),
        .clk(SYS_CLK),
        .rise(trig_rise)
    );

    initial begin
        trig_period = 30000 * period;
        us_period = 10 * period;
        state = STATE_IDLE;
        trig_prev = 1'b0;
        clk_prev = 1'b0;
    end

endmodule

