        hour_count <= hour_count + 6'd1;
        minute_count <= 6'd0;
        second_count <= 6'd0;
      end else if (second_count == 6'd59) begin
        minute_count <= minute_count + 6'd1;
        second_count <= 6'd0;
      end else begin
        second_count <= second_count + 6'd1;
      end
      valid_time <= 1'b1;
    end
    if (hour_count >= 6'd12) begin
      am_pm <= 1'b1;
    end else begin
      am_pm <= 1'b0;
    end
  end

  assign hour = {hour_count[4:5], hour_count[0:3]};
  assign minute = {minute_count[4:5], minute_count[0:3]};
  assign second = {second_count[4:5], second_count[0:3]};
  assign time_valid = valid_time;

endmodule

