  assign Sum = sum;

endmodule

module full_adder (
  input A,
  input B,
  input Cin,
  output Sum,
  output Cout
);

  wire c1;
  wire s1;

  xor x1(s1, A, B);
  xor x2(Sum, s1, Cin);
  and a1(c1, A, B);
  and a2(c2, s1, Cin);
  or o1(Cout, c1, c2);

endmodule

