module max_metric (
    clk     ,   // I, clock
    a       ,   // I, metric a
    b       ,   // I, metric b
    c       ,   // I, metric c
    d       ,   // I, metric d
    sa      ,   // I, state a
    sb      ,   // I, state b
    sc      ,   // I, state c
    sd      ,   // I, state d
    state   ,   // O, state
    max         // O, max metric
    ) ;

parameter   M = 7 ;
parameter   K = 7 ;

input               clk ;
input   [M -1:0]    a ;
input   [M -1:0]    b ;
input   [M -1:0]    c ;
input   [M -1:0]    d ;

input   [K -2:0]    sa ;
input   [K -2:0]    sb ;
input   [K -2:0]    sc ;
input   [K -2:0]    sd ;

output  [K -2:0]    state ;
output  [M -1:0]    max ;

//=====================================
//Internal signal
//=====================================
reg     [K -2:0]    pos0 ; // position of the max metric in the first pair
reg     [K -2:0]    pos1 ; // position of the max metric in the second pair
reg     [M -1:0]    max0 ; // max metric in the first pair
reg     [M -1:0]    max1 ; // max metric in the second pair
reg     [M -1:0]    tmp ;  // temporary variable for comparisons
reg     [K -2:0]    state_i ;   // internal state variable
reg     [M -1:0]    max_i ;     // internal max metric variable
reg     [K -2:0]    state_reg ; // registered state variable
reg     [M -1:0]    max_reg ;   // registered max metric variable

//=====================================
// Main RTL code
//=====================================
always @*
begin  
  tmp = a-b ;
  if(~tmp[M -1])
  begin
    max0 = a ;
    pos0 = sa ;
  end
  else
  begin
    max0 = b ;
    pos0 = sb ;
  end

  tmp = c-d ;
  if(~tmp[M-1])
  begin
    max1 = c ;
    pos1 = sc ;
  end
  else
  begin
    max1 = d ;
    pos1 = sd ;
  end

  tmp = max0 - max1 ;
  if (~tmp[M-1])
  begin
    max_i = max0 ;
    state_i = pos0 ;
  end
  else
  begin
    state_i = pos1 ;
    max_i = max1 ;
  end
end

//=====================================
// Synchronous logic
//=====================================
always @ (posedge clk)
begin
  state_reg <= state_i ;
  max_reg <= max_i ;
end

assign state = state_reg ;
assign max = max_reg ;

endmodule

