    wire [2:0] bitwise_or_out;
    wire logical_or_out;
    wire [2:0] a_not;
    wire [2:0] b_not;

    transition_capture tc (.in(in), .reset(reset), .out(transition_out));
    d_flip_flop df (.d({transition_out[7:0], transition_out[15:8], transition_out[23:16], transition_out[31:24]}), .clk(clk), .reset(reset), .q(d_flip_flop_out));
    assign bitwise_or_out = a | b;
    assign logical_or_out = (a != 0) || (b != 0);
    assign a_not = ~a;
    assign b_not = ~b;
    assign out_or_bitwise = bitwise_or_out;
    assign out_or_logical = logical_or_out;
