module phase_detector (
  input ref_clk,
  input feedback,
  output reg phase_difference
);

always @(posedge ref_clk or posedge feedback) begin
  phase_difference <= phase_difference + $signed(feedback) - $signed(ref_clk);
end

endmodule
module loop_filter (
  input clk,
  input signed control_voltage,
  output reg signed filtered_voltage
);

parameter filter_constant = 0.001;

always @(posedge clk) begin
  filtered_voltage <= filtered_voltage + (filter_constant * (control_voltage - filtered_voltage));
end

endmodule
module vco (
  input clk,
  input signed control_voltage,
  output reg vco_clk
);

parameter vco_gain = 100;

always @(posedge clk) begin
  vco_clk <= vco_clk + ($signed(vco_gain * control_voltage) / clk_freq);
end

endmodule
module PLL (
  input ref_clk,
  input feedback,
  output pll_clk
);

parameter clk_freq = 100000000;
parameter pll_range = 100;

reg [31:0] phase_accumulator;
wire signed phase_difference;
wire signed control_voltage;
reg [31:0] feedback_accumulator;
wire signed feedback_frequency;
wire signed vco_frequency;

phase_detector pd(ref_clk, feedback, phase_difference);
loop_filter lf(clk, control_voltage, filtered_voltage);
vco v(clk, control_voltage, vco_clk);

assign feedback_frequency = feedback_accumulator / pll_range;
assign vco_frequency = (vco_clk * pll_range) / clk_freq;

always @(posedge clk) begin
  phase_accumulator <= phase_accumulator + vco_frequency;
  feedback_accumulator <= feedback_accumulator + phase_difference;
  control_voltage <= filtered_voltage + (pll_range * phase_difference);
  pll_clk <= (phase_accumulator >= 0) ? 1'b1 : 1'b0;
end

endmodule

module shift_register_and_counter (
  input clk, // Clock signal input 
  input rst_n, // Active low synchronous reset input 
  input [7:0] in_data, // 8-bit input data 
  output [7:0] out_data // 8-bit output data 
);

  reg [63:0] shift_reg; // 64-bit shift register 
  reg [2:0] counter; // 3-bit counter 

  // Shift register logic 
  always @(posedge clk) begin
    if (!rst_n) begin
      shift_reg <= 64'b0;
    end else begin
      shift_reg <= {shift_reg[62:0], in_data};
    end
  end

  // Counter logic 
  always @(posedge clk) begin
    if (!rst_n) begin
      counter <= 3'b0;
    end else begin
      counter <= counter + 1;
    end
  end

  // Functional module logic 
  assign out_data = shift_reg[7:0] & counter;

endmodule

