module PLL (
  input reference_clock,
  input feedback_signal,
  input reset,
  output locked_clock,
  output phase_error
);

parameter KVCO = 1;
parameter N = 10;
parameter M = 2;

// Define submodules
phase_detector pd (
  .reference_clock(reference_clock),
  .feedback_signal(feedback_signal),
  .phase_error(phase_error)
);

loop_filter lf (
  .phase_error(phase_error),
  .voltage_control(voltage_control)
);

voltage_controlled_oscillator vco (
  .voltage_control(voltage_control),
  .feedback_signal(feedback_signal),
  .locked_clock(locked_clock),
  .M(M)
);

// Define feedback divider ratio
function integer feedback_divider_ratio;
  input clk;
  input N;
  begin
    feedback_divider_ratio = clk / N;
  end
endfunction

// Define output divider ratio
function integer output_divider_ratio;
  input clk;
  input M;
  begin
    output_divider_ratio = clk / M;
  end
endfunction

endmodule

// Define phase detector submodule
module phase_detector (
  input reference_clock,
  input feedback_signal,
  output phase_error
);
  assign phase_error = reference_clock ^ feedback_signal;
endmodule

// Define loop filter submodule
module loop_filter (
  input phase_error,
  output voltage_control
);
  parameter Kp = 1;
  parameter Ki = 0.1;
  reg [31:0] integral = 0;
  reg [31:0] proportional;
  always @(phase_error) begin
    proportional = Kp * phase_error;
    integral = integral + Ki * phase_error;
    voltage_control = KVCO * (proportional + integral);
  end
endmodule

// Define voltage-controlled oscillator submodule
module voltage_controlled_oscillator (
  input voltage_control,
  input feedback_signal,
  output locked_clock,
  input M
);
  reg [31:0] counter = 0;
  always @(posedge feedback_signal) begin
    if (counter == M - 1) begin
      locked_clock <= ~locked_clock;
      counter <= 0;
    end else begin
      counter <= counter + 1;
    end
  end
endmodule

