module ALU_4bit (
    input [3:0] A,
    input [3:0] B,
    input [2:0] OP,
    output reg [3:0] ALU_output
);
    always @(*) begin
        case (OP)
            3'b000: ALU_output = A + B;
            3'b001: ALU_output = A - B;
            3'b010: ALU_output = A & B;
            3'b011: ALU_output = A | B;
            3'b100: ALU_output = A ^ B;
            3'b101: ALU_output = A << 1;
            default: ALU_output = 4'b0000;
        endcase
    end
endmodule

module Booth_multiplier (
    input [3:0] A,
    input [3:0] B,
    output reg [7:0] product
);
    reg [7:0] P;
    reg [3:0] M;
    integer i;

    always @(*) begin
        P = {4'b0, B};
        M = A;

        for (i = 0; i < 4; i = i + 1) begin
            case (P[1:0])
                2'b01: P = P + {4'b0, M};
                2'b10: P = P - {4'b0, M};
                default: P = P;
            endcase
            P = P >> 1;
        end
        product = P[7:0];
    end
endmodule

module top_module (
    input [3:0] A,
    input [3:0] B,
    input [2:0] OP,
    output reg [3:0] final_output
);
    wire [3:0] ALU_output;
    wire [7:0] product;

    ALU_4bit ALU (
        .A(A),
        .B(B),
        .OP(OP),
        .ALU_output(ALU_output)
    );

    Booth_multiplier multiplier (
        .A(A),
        .B(B),
        .product(product)
    );

    always @(*) begin
        case (OP)
            3'b000: final_output = ALU_output + product;
            3'b001: final_output = ALU_output - product;
            3'b010: final_output = ALU_output & product;
            3'b011: final_output = ALU_output | product;
            3'b100: final_output = ALU_output ^ product;
            3'b101: final_output = ALU_output << 1;
            default: final_output = 4'b0000;
        endcase
    end
endmodule

