module binary_division (
    input [15:0] dividend,
    input [3:0] divisor,
    output reg [3:0] quotient
);

reg [15:0] remainder;
reg [3:0] count;

always @(*) begin
    quotient = 0;
    remainder = dividend;
    count = 0;
    while (remainder >= divisor) begin
        remainder = remainder - divisor;
        count = count + 1;
    end
    quotient = count;
end

endmodule

module barrel_shifter (
    input [3:0] X,
    input [1:0] Shift,
    input Direction,
    output reg [3:0] Y
);

always @(*) begin
    case ({Direction, Shift})
        2'b00: Y = X << Shift;
        2'b01: Y = X >> Shift;
        2'b10: Y = X << Shift;
        2'b11: Y = X >> Shift;
    endcase
end

endmodule

