    wire [7:0] priority_sel;
    wire [15:0] prod;

    // 8-to-1 multiplexer
    mux8to1 mux(
        .in0(in1),
        .in1(in2),
        .sel(priority),
        .out(mux_out)
    );

    // Comparator circuit
    assign priority_sel = (priority == 3'b000) ? in1 :
                          (priority == 3'b001) ? in2 :
                          (priority == 3'b010) ? in1 :
                          (priority == 3'b011) ? in2 :
                          (priority == 3'b100) ? in1 :
                          (priority == 3'b101) ? in2 :
                          (priority == 3'b110) ? in1 :
