module hdmi_in
(
  //hdmi outputs
  output reg hdmi_clk,
  output hdmi_de,
  output hdmi_hs,
  output hdmi_vs,
  //image data
  output [7:0]hdmi_r,
  output [7:0]hdmi_g,
  output [7:0]hdmi_b
); 
//-----------------------------------------------
//for now supports VGA 640x480 60Hz only
  //horizontal
  parameter hr=64; //resolution
  parameter hbp=8; //back porch
  parameter hfp=8; //front porch
  parameter hs=2;  //sync len
  //vertical
  parameter vr=64; //resolution
  parameter vbp=8; //back porch
  parameter vfp=8; //front porch
  parameter vs=4;   //sync len
//-----------------------------------------------
  reg line=1'b0;
  reg vsync=1'b1;
  reg hsync=1'b1;
  reg enab=1'b0;
  reg eenab=1'b0;
  reg h_enable=1'b0;
  reg v_enable=1'b0;
  reg [10:0]hcounter=0;
  reg [10:0]vcounter=64+1;//480+7
//-----------------------------------------------
  reg [7:0]red;
  reg [7:0]green;
  reg [7:0]blue;

  //reg hdmi_clk=1'b0;
//-----------------------------------------------
initial
begin
  while(1)
  begin
    #1 hdmi_clk=1'b0;
     #1 hdmi_clk=1'b1;
  end
end  
//-----------------------------------------------
integer rgbfile,i,v,clo,cle,wl,x;

//-----------------------------------------------
always @(posedge hdmi_clk)
begin
  hcounter<=hcounter+1;

  eenab<=enab;

  if(hcounter==(hr+hbp))
  begin
    hsync<=1'b0;
  end
  if(hcounter==(hr+hbp+hs))
  begin
    hsync<=1'b1;
     line<=1'b0;
  end

  if(hcounter<hr)
      h_enable<=1'b1;
  else
      h_enable<=1'b0;

  if(vcounter<vr)
      v_enable<=1'b1;
  else
      v_enable<=1'b0;

  if((v_enable==1'b1)&&(h_enable==1'b1))
      enab<=1'b1;
  else
      enab<=1'b0;

  if(hcounter==(hr+hbp+hs+hfp))
  begin
    hcounter<=0;
     line<=1'b1;
  end
end
//-----------------------------------------------
//TB only

always @(posedge hdmi_clk)
begin
  if(enab)
  begin
    red=$fgetc(rgbfile);
     green=$fgetc(rgbfile);
     blue=$fgetc(rgbfile);

  end
end
//TB end
//-----------------------------------------------
reg [7:0]vsc=0;

always @(posedge line)
begin
  vcounter<=vcounter+1;
  if(vcounter==(vr+vbp))
  begin  
    vsync<=1'b0;
     //TB only
     vsc=vsc+1;

    rgbfile = $fopen("geirangerfjord_64.ppm","rb");    
     // read header file
     for(i=0;i<13;i=i+1)
    begin
      v=$fgetc(rgbfile); 
    end    
     //TB end
  end
  if(vcounter==(vr+vbp+vs))
  begin
    vsync<=1'b1;
  end
  if(vcounter==(vr+vbp+vs+vfp))
  begin
    vcounter<=0;
  end
end
//-----------------------------------------------

assign hdmi_r=red;
assign hdmi_g=green;
assign hdmi_b=blue;

assign hdmi_de=eenab;
assign hdmi_hs=hsync;
assign hdmi_vs=vsync;
//-----------------------------------------------
endmodule

module small_fifo
    #(parameter WIDTH = 72,
      parameter MAX_DEPTH_BITS = 3,
      parameter PROG_FULL_THRESHOLD = 2**MAX_DEPTH_BITS - 1
      )
    (
     input [WIDTH-1:0] din,     // Data in
     input          wr_en,   // Write enable
     input          rd_en,   // Read the next word 
     output reg [WIDTH-1:0]  dout,    // Data out
     output         full,
     output         nearly_full,
     output         prog_full,
     output         empty,
     input          reset,
     input          clk
     );

    parameter MAX_DEPTH        = 2 ** MAX_DEPTH_BITS;

    reg [WIDTH-1:0] queue [MAX_DEPTH - 1 : 0];
    reg [MAX_DEPTH_BITS - 1 : 0] rd_ptr;
    reg [MAX_DEPTH_BITS - 1 : 0] wr_ptr;
    reg [MAX_DEPTH_BITS : 0] depth;

    // Sample the data
    always @(posedge clk)
    begin
       if (wr_en) 
          queue[wr_ptr] <= din;
       if (rd_en)
          dout <= queue[rd_ptr];
    end

    always @(posedge clk)
    begin
       if (reset) begin
          rd_ptr <= 'h0;
          wr_ptr <= 'h0;
          depth  <= 'h0;
       end
       else begin
          if (wr_en) wr_ptr <= wr_ptr + 'h1;
          if (rd_en) rd_ptr <= rd_ptr + 'h1;
          if (wr_en & ~rd_en) depth <= depth + 'h1;
          else if (~wr_en & rd_en) depth <= depth - 'h1;
       end
    end

    assign full = depth == MAX_DEPTH;
    assign prog_full = (depth >= PROG_FULL_THRESHOLD);
    assign nearly_full = depth >= MAX_DEPTH-1;
    assign empty = depth == 'h0;

    always @(posedge clk)
    begin
       if (wr_en && depth == MAX_DEPTH && !rd_en)
          $display($time, " ERROR: Attempt to write to full FIFO: %m");
       if (rd_en && depth == 'h0)
          $display($time, " ERROR: Attempt to read an empty FIFO: %m");
    end

endmodule

module transmission_parity (input enable, 
                            input wire [7:0] din, 
                            input parity,
                            output busy,
                            output reg done,
                            input wire clk_div, 
                            output reg tx);

parameter count = 9;

initial begin
    tx <= 1'b1;
    done = 0;
end

parameter STATE_IDLE  = 3'd0;
parameter STATE_DATA  = 3'd1;
parameter STATE_PARITY= 3'd2;
parameter STATE_STOP  = 3'd3;

reg [7:0] data = 8'b11111111;
reg [2:0] bitpos = 0;
reg [2:0] state = STATE_IDLE;
reg parity_bit;

always @(posedge clk_div) begin
    case (state)
        STATE_IDLE: begin
            done <= 0;
            tx <= 1'b1;
            if (enable & ~busy) begin
                data <= din;
                bitpos <= 0;
                parity_bit <= parity ? ~^(data) : 1'b0;
                state <= STATE_DATA;
            end
        end
        STATE_DATA: begin
            if (bitpos == count-2) begin
                tx <= parity_bit;
                state <= STATE_PARITY;
            end
            else begin
                tx <= data[bitpos];
                bitpos <= bitpos + 1;
            end
        end
        STATE_PARITY: begin
            tx <= 1'b1;
            state <= STATE_STOP;
        end
        STATE_STOP: begin
            tx <= 1'b1;
            done <= 1;
            state <= STATE_IDLE;
        end
        default: begin
            tx <= 1'b1;
            state <= STATE_IDLE;
        end
    endcase
end

assign busy = (state != STATE_IDLE);

endmodule

