module multiplier_block (
    i_data0,
    o_data0
);

  // Port mode declarations:
  input   [31:0] i_data0;
  output  [31:0] o_data0;

  //Multipliers:

  wire [31:0]
    w1,
    w1024,
    w1023,
    w8,
    w9,
    w144,
    w1167,
    w4668,
    w3501,
    w7002;

  assign w1 = i_data0;
  assign w1024 = i_data0 << 10;
  assign w1023 = w1024 - w1;
  assign w8 = i_data0 << 3;
  assign w9 = i_data0 + w8;
  assign w144 = w9 << 4;
  assign w1167 = w1023 + w144;
  assign w4668 = w1167 << 2;
  assign w3501 = w4668 - w1167;
  assign w7002 = w3501 << 1;

  assign o_data0 = w7002;

  //multiplier_block area estimate = 6795.83517920735;
endmodule

module add_three_numbers (
    input [7:0] in0,
    input [7:0] in1,
    input [7:0] in2,
    output [7:0] out0,
    input in0_valid,
    input in1_valid,
    input in2_valid,
    output out0_valid,
    input in0_ready,
    input in1_ready,
    input in2_ready,
    output out0_ready
);

    reg [7:0] sum;
    reg out0_valid_reg;
    reg in_ready_reg;

    always @ (posedge in0_valid or posedge in1_valid or posedge in2_valid or posedge out0_ready) begin
        if (in0_valid && in1_valid && in2_valid && out0_ready) begin
            sum = in0 + in1 + in2;
            out0_valid_reg = 1;
            in_ready_reg = 1;
        end else begin
            out0_valid_reg = 0;
            in_ready_reg = 0;
        end
    end

    assign out0 = sum;
    assign out0_valid = out0_valid_reg;
    assign in0_ready = in_ready_reg;
    assign in1_ready = in_ready_reg;
    assign in2_ready = in_ready_reg;
    assign out0_ready = 1;

endmodule

