module ham_15_11_decoder(
    input [14:0] cin,
    output [10:0] qout
);

    // Declare signals
    reg [10:0] data;
    reg [3:0] parity;
    wire [3:0] calc_parity;
    wire error;
    reg [1:0] error_bit;

    // Calculate parity bits
    assign calc_parity[0] = (cin[3]^cin[5]^cin[7]^cin[9]^cin[11]^cin[13]^cin[15]);
    assign calc_parity[1] = (cin[3]^cin[6]^cin[7]^cin[10]^cin[11]^cin[14]^cin[15]);
    assign calc_parity[2] = (cin[5]^cin[6]^cin[7]^cin[12]^cin[13]^cin[14]^cin[15]);
    assign calc_parity[3] = (cin[9]^cin[10]^cin[11]^cin[12]^cin[13]^cin[14]^cin[15]);

    // Compare calculated parity with received parity
    assign error = (calc_parity != cin[0:3]);

    // Correct error if detected
    always @(*)
    begin
        if (error)
        begin
            error_bit = {calc_parity^cin[0:3]};
            data = {cin[2], cin[4], cin[5], cin[6], cin[8], cin[9], cin[10], cin[11], cin[13], cin[14], cin[15]};
            data[error_bit] = ~data[error_bit];
        end
        else
        begin
            data = {cin[2], cin[4], cin[5], cin[6], cin[8], cin[9], cin[10], cin[11], cin[13], cin[14], cin[15]};
        end
    end

    // Output decoded data
    assign qout = data;

endmodule

