module fsm_4bit_sequence_detection (
  input clk,
  input reset,
  input data,
  output reg match
);

  parameter S0 = 2'b00;
  parameter S1 = 2'b01;
  parameter S2 = 2'b10;
  parameter S3 = 2'b11;

  reg [1:0] state;
  reg [3:0] shift_reg;

  always @(posedge clk) begin
    if (reset) begin
      state <= S0;
      shift_reg <= 4'b0;
      match <= 1'b0;
    end else begin
      case (state)
        S0: begin
          if (data) begin
            state <= S1;
          end
        end
        S1: begin
          if (!data) begin
            state <= S2;
          end
        end
        S2: begin
          if (data) begin
            state <= S3;
          end
        end
        S3: begin
          if (!data) begin
            state <= S0;
            match <= (shift_reg == 4'b1010);
          end
        end
      endcase

      shift_reg <= {shift_reg[2:0], data};
    end
  end

endmodule

module mod_vga(rst, clk, ie, de, iaddr, daddr, drw, din, iout, dout, rgb, hs, vs, sram_data, sram_addr, sram_read, sram_rdy);
        input rst;
        input clk;
        input ie,de;
        input [31:0] iaddr, daddr;
        input [1:0] drw;
        input [31:0] din;
        output [31:0] iout, dout;
        output [7:0] rgb;
        output hs, vs;
        input [31:0] sram_data;
        output [31:0] sram_addr;
        output sram_read;
        input sram_rdy;

        // by spec, the iout and dout signals must go hiZ when we're not using them
        wire [31:0] idata, ddata;
        assign iout = idata;
        assign dout = ddata;

        // initialize idata to 0
        assign idata = 32'h00000000;

        // instantiate sub-modules
        wire [7:0] eff_rgb;
        wire [10:0] hcount, vcount;
        wire blank;
        reg enable = 0;
        reg [31:0] fb_pointer;

        // instantiate VGA controller
        vga_controller vga(clk, rst, hs, vs, blank, hcount, vcount);

        // instantiate VGA SRAM bypass
        vga_sram_bypass bypass(clk, enable, fb_pointer, hcount, vcount, eff_rgb, sram_data, sram_addr, sram_read, sram_rdy);

        // update framebuffer pointer and enable signal based on input signals
        always @(negedge clk) begin
            if (drw[0] && de && !rst) begin
                if (daddr == 32'h00000000) begin
                    enable <= din[0];
                end else if (daddr == 32'h00000004) begin
                    fb_pointer <= din;
                end
            end else if (rst) begin
                enable <= 0;
                fb_pointer <= 32'h00000000;
            end
        end

        // output data from framebuffer or SRAM based on input signals
        always @(negedge clk) begin
            if (drw[1] && de && !rst && daddr == 32'h00000000) begin
                ddata <= fb_pointer;
            end else if (drw[1] && de && !rst && daddr == 32'h10000000) begin
                ddata <= sram_data;
            end
        end

        // output RGB signal based on input signals
        assign rgb = (blank) ? 0 :
                     (enable) ? eff_rgb : 0;

        // output SRAM address and read signal based on input signals
        assign sram_addr = daddr;
        assign sram_read = (drw[1] && de && !rst && daddr == 32'h10000000) ? 1 : 0;
endmodule

// VGA controller module
module vga_controller(clk, rst, hs, vs, blank, hcount, vcount);
        input clk, rst;
        output hs, vs, blank;
        output reg [10:0] hcount, vcount;

        // initialize hcount and vcount to 0
        initial begin
            hcount = 0;
            vcount = 0;
        end

        // generate VGA signals
        always @(posedge clk) begin
            if (rst) begin
                hcount <= 0;
                vcount <= 0;
                hs <= 1;
                vs <= 1;
                blank <= 1;
            end else begin
                if (hcount == 799) begin
                    hcount <= 0;
                    if (vcount == 524) begin
                        vcount <= 0;
                        hs <= 1;
                        vs <= 1;
                        blank <= 1;
                    end else begin
                        vcount <= vcount + 1;
                        hs <= 0;
                        vs <= 1;
                        blank <= 0;
                    end
                end else begin
                    hcount <= hcount + 1;
                    hs <= 0;
                    vs <= 0;
                    blank <= 0;
                end
            end
        end
endmodule

// VGA SRAM bypass module
module vga_sram_bypass(clk, enable, fb_pointer, hcount, vcount, eff_rgb, sram_data, sram_addr, sram_read, sram_rdy);
        input clk, enable, sram_rdy;
        input [31:0] sram_data, sram_addr;
        output reg [31:0] fb_pointer;
        input [10:0] hcount, vcount;
        output reg [7:0] eff_rgb;
        output reg sram_read;

        // initialize framebuffer pointer to 0
        initial begin
            fb_pointer = 32'h00000000;
        end

        // read data from SRAM when the address matches the framebuffer address
        always @(posedge clk) begin
            if (enable && !sram_read && sram_rdy && sram_addr == fb_pointer) begin
                eff_rgb <= sram_data[23:16];
                fb_pointer <= fb_pointer + 4;
                sram_read <= 1;
            end else begin
                eff_rgb <= 8'h00;
                sram_read <= 0;
            end
        end
endmodule

