module testbench;

  // Inputs
  reg clk;
  reg reset_tb;
  reg go_r_tb;

  // Outputs
  wire go_a_tb;
  wire done_r_tb;
  reg done_a_tb;

  // Instantiate the unit under test (UUT)
  top uut (
    .reset(reset_tb),
    .go_0r(go_r_tb),
    .go_0a(go_a_tb),
    .done_0r(done_r_tb),
    .done_0a(done_a_tb)
  );

  // Generate clock
  always #1 clk = ~clk;

  initial begin
    // Initialize inputs
    clk = 0;
    reset_tb = 1;
    go_r_tb = 0;
    done_a_tb = 0;

    // Wait for 10 time units and de-assert reset
    #10 reset_tb = 0;

    // Wait for 1 time unit
    #1;

    // Assert go_r and wait for go_a to be asserted
    go_r_tb = 1;
    @(posedge clk);
    while (!go_a_tb) @(posedge clk);

    // De-assert go_r and wait for go_a to be de-asserted
    go_r_tb = 0;
    @(negedge clk);
    while (go_a_tb) @(posedge clk);

    // Wait for done_r to be asserted
    @(posedge clk);
    while (!done_r_tb) @(posedge clk);

    // Assert done_a and wait for it to be de-asserted
    done_a_tb = 1;
    @(negedge clk);
    while (done_a_tb) @(posedge clk);

    // End simulation
    $display("Test passed");
    $finish;
  end

endmodule

