module adder (
  // inputs
  input clk,
  input [7:0] A,
  input [7:0] B,
  // outputs
  output reg [7:0] C,
  output reg overflow
);

  always @(posedge clk) begin
    // Calculate sum
    C <= A + B;

    // Check for overflow
    if (C > 255) begin
      C <= C[6:0]; // discard most significant bit
      overflow <= 1;
    end else begin
      overflow <= 0;
    end
  end

endmodule

module data_transmitter(
    input clk,

    input start,
    output reg done,
    input [10:0] count,
    input [7:0] data_in,

    output reg [10:0] address,
    output reg enable,
    output reg [3:0] data_out
);

    reg [10:0] byte_count;
    reg [1:0] state;

    always @(posedge clk) begin
        case(state)
            2'b00: begin // Idle
                if(start) begin
                    state <= 2'b01; // Send LSB
                    byte_count <= 11'd0;
                end
            end
            2'b01: begin // Send LSB
                enable <= 1'b1;
                data_out <= data_in[3:0];
                address <= byte_count;
                byte_count <= byte_count + 11'd1;
                if(byte_count == count) begin
                    state <= 2'b10; // Send MSB
                end
            end
            2'b10: begin // Send MSB
                data_out <= data_in[7:4];
                address <= byte_count;
                byte_count <= byte_count + 11'd1;
                if(byte_count == count) begin
                    state <= 2'b11; // Done
                end else begin
                    state <= 2'b01; // Send LSB
                end
            end
            2'b11: begin // Done
                enable <= 1'b0;
                done <= 1'b1;
                byte_count <= 11'd0;
                if(!start) begin
                    state <= 2'b00; // Idle
                    done <= 1'b0;
                end
            end
        endcase
    end

endmodule

