module rr_mux
  (
   input 	 clock,
   input 	 reset,
   input [3:0] 	 rri_valid,
   output [3:0]  rri_ready,
   input [63:0]  rri_addr_0,
   input [63:0]  rri_addr_1,
   input [63:0]  rri_addr_2,
   input [63:0]  rri_addr_3,
   input [2:0] 	 rri_tag_0,
   input [2:0] 	 rri_tag_1,
   input [2:0] 	 rri_tag_2,
   input [2:0] 	 rri_tag_3,
   output 	 rro_valid,
   input 	 rro_ready,
   output [63:0] rro_addr,
   output [7:0]  rro_tag
   );

   // Internal signals
   reg [1:0] rr_counter;
   reg [1:0] rr_next_counter;
   reg [63:0] rr_next_addr;
   reg [2:0] rr_next_tag;
   reg rro_valid_reg;

   // Assign output ready signals
   assign rri_ready[0] = (rr_counter == 0) ? 1'b1 : rro_ready;
   assign rri_ready[1] = (rr_counter == 1) ? 1'b1 : rro_ready;
   assign rri_ready[2] = (rr_counter == 2) ? 1'b1 : rro_ready;
   assign rri_ready[3] = (rr_counter == 3) ? 1'b1 : rro_ready;

   // Round-robin logic
   always @(posedge clock, posedge reset) begin
      if (reset) begin
         rr_counter <= 2'b0;
         rr_next_counter <= 2'b0;
         rr_next_addr <= rri_addr_0;
         rr_next_tag <= rri_tag_0;
         rro_valid_reg <= 1'b0;
      end else begin
         if (rro_ready && rro_valid_reg) begin
            rr_counter <= rr_next_counter;
            rr_next_counter <= (rr_counter == 2'b11) ? 2'b00 : rr_counter + 1;
            rr_next_addr <= rri_addr_0;
            rr_next_tag <= rri_tag_0;
            rro_valid_reg <= 1'b0;
         end else begin
            rr_next_addr <= (rr_counter == 2'b00) ? rri_addr_0 :
                            (rr_counter == 2'b01) ? rri_addr_1 :
                            (rr_counter == 2'b10) ? rri_addr_2 :
                                                   rri_addr_3;
            rr_next_tag <= (rr_counter == 2'b00) ? rri_tag_0 :
                           (rr_counter == 2'b01) ? rri_tag_1 :
                           (rr_counter == 2'b10) ? rri_tag_2 :
                                                  rri_tag_3;
            rro_valid_reg <= rri_valid[rr_counter];
         end
      end
   end

   // Assign output ports
   assign rro_valid = rro_valid_reg;
   assign rro_addr = rr_next_addr;
   assign rro_tag = {3'b0, rr_next_tag};

endmodule

