module fifo_generator
   (dout,
    empty,
    full,
    wr_en,
    wr_clk,
    rd_clk,
    din,
    rst,
    rd_en);
  output [7:0]dout;
  output empty;
  output full;
  input wr_en;
  input wr_clk;
  input rd_clk;
  input [7:0]din;
  input rst;
  input rd_en;

  reg [7:0] fifo [0:7];
  reg [2:0] write_ptr = 0;
  reg [2:0] read_ptr = 0;
  reg [2:0] count = 0;
  wire [2:0] next_write_ptr;
  wire [2:0] next_read_ptr;
  wire [2:0] next_count;
  wire [7:0] next_dout;
  wire next_empty;
  wire next_full;

  assign dout = next_dout;
  assign empty = next_empty;
  assign full = next_full;

  // Next state logic
  always @ (posedge wr_clk or posedge rd_clk) begin
    if (rst) begin
      write_ptr <= 0;
      read_ptr <= 0;
      count <= 0;
    end else begin
      write_ptr <= next_write_ptr;
      read_ptr <= next_read_ptr;
      count <= next_count;
    end
  end

  // Write logic
  always @ (posedge wr_clk) begin
    if (wr_en && !next_full) begin
      fifo[write_ptr] <= din;
      next_write_ptr <= write_ptr + 1;
      next_count <= count + 1;
    end else begin
      next_write_ptr <= write_ptr;
      next_count <= count;
    end
  end

  // Read logic
  always @ (posedge rd_clk) begin
    if (rd_en && !next_empty) begin
      next_dout <= fifo[read_ptr];
      fifo[read_ptr] <= 0;
      next_read_ptr <= read_ptr + 1;
      next_count <= count - 1;
    end else begin
      next_dout <= dout;
      next_read_ptr <= read_ptr;
      next_count <= count;
    end
  end

  // Empty and full logic
  assign next_empty = (count == 0);
  assign next_full = (count == 8);

endmodule

module calculator(
    input clk,
    input rst,
    input [1:0] op,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] result
);

always @ (posedge clk) begin
    if (rst == 1) begin
        result <= 0;
    end
    else begin
        case (op)
            2'b00: result <= a + b;
            2'b01: result <= a - b;
            2'b10: result <= a * b;
            2'b11: result <= a / b;
        endcase
    end
end

endmodule

