module RAMB18E1 (input clk, input [23:0] din, output [7:0] dout);

    reg [17:0] mem [0:16383]; // 2^14 words of 18-bit memory
    reg [17:0] doutA;
    reg [17:0] doutB;
    reg [1:0] parityA;
    reg [1:0] parityB;

    // Port A
    always @(posedge clk) begin
        if (din[1]) begin // address enable
            if (din[3]) begin // read enable
                if (din[4]) begin // register enable
                    if (din[6]) begin // register set/reset
                        doutA <= {18{din[5]}}; // set/reset
                    end else begin
                        doutA <= mem[din[0]]; // read
                    end
                end else begin
                    doutA <= mem[din[0]]; // read
                end
                parityA <= {2{doutA[0]}} ^ doutA[1:0]; // calculate parity
            end
        end
    end

    // Port B
    always @(posedge clk) begin
        if (din[10]) begin // address enable
            if (din[12]) begin // write enable
                if (din[13]) begin // register enable
                    if (din[15]) begin // register set/reset
                        mem[din[9]] <= {18{din[14]}}; // set/reset
                    end else begin
                        if (din[17] == 4'b1111) begin // write first
                            mem[din[9]] <= din[7:0];
                        end else if (din[17] == 4'b0000) begin // write enable off
                            // do nothing
                        end else if (din[17] == 4'b0001) begin // byte 0 write enable
                            mem[din[9]][7:0] <= din[7:0];
                        end else if (din[17] == 4'b0010) begin // byte 1 write enable
                            mem[din[9]][15:8] <= din[7:0];
                        end else if (din[17] == 4'b0100) begin // byte 2 write enable
                            mem[din[9]][17:16] <= din[8:7];
                            mem[din[9]][23:16] <= din[15:8];
                        end else if (din[17] == 4'b1000) begin // byte 3 write enable
                            mem[din[9]][17:16] <= din[8:7];
                            mem[din[9]][15:0] <= din[17:2];
                        end
                    end
                end else begin
                    if (din[17] == 4'b1111) begin // write first
                        mem[din[9]] <= din[7:0];
                    end else if (din[17] == 4'b0000) begin // write enable off
                        // do nothing
                    end else if (din[17] == 4'b0001) begin // byte 0 write enable
                        mem[din[9]][7:0] <= din[7:0];
                    end else if (din[17] == 4'b0010) begin // byte 1 write enable
                        mem[din[9]][15:8] <= din[7:0];
                    end else if (din[17] == 4'b0100) begin // byte 2 write enable
                        mem[din[9]][17:16] <= din[8:7];
                        mem[din[9]][23:16] <= din[15:8];
                    end else if (din[17] == 4'b1000) begin // byte 3 write enable
                        mem[din[9]][17:16] <= din[8:7];
                        mem[din[9]][15:0] <= din[17:2];
                    end
                end
                doutB <= mem[din[9]]; // read
                parityB <= {2{doutB[0]}} ^ doutB[1:0]; // calculate parity
            end
        end
    end

    assign dout = {doutA, parityA, doutB, parityB};

endmodule

module up_down_counter (
    input UD,
    input RST,
    output reg [3:0] Q,
    output reg OVF
);

always @ (posedge clk or negedge RST) begin
    if (RST == 0) begin
        Q <= 4'b0;
        OVF <= 0;
    end
    else if (UD == 1) begin
        if (Q == 4'hF) begin
            Q <= 4'b0;
            OVF <= 1;
        end
        else begin
            Q <= Q + 1;
            OVF <= 0;
        end
    end
    else begin
        if (Q == 4'b0) begin
            Q <= 4'hF;
            OVF <= 1;
        end
        else begin
            Q <= Q - 1;
            OVF <= 0;
        end
    end
end

endmodule

