module spi_state_machine (
  input rst,
  input clk,
  input ss_in,
  input data_in,
  output ss_out,
  output data_out
);

  // Define the states of the state machine
  parameter IDLE = 2'b00;
  parameter ACTIVE = 2'b01;

  // Define the signals used in the state machine
  reg [1:0] state;
  reg sclk;
  reg mosi;
  reg miso;
  reg [7:0] data;
  reg [2:0] bit_count;

  // Assign the outputs
  assign ss_out = state == ACTIVE ? ss_in : 1'b1;
  assign data_out = state == ACTIVE ? miso : 1'bx;

  // Define the clock generator
  always @(posedge clk) begin
    sclk <= ~sclk;
  end

  // Define the state machine
  always @(posedge clk) begin
    if (rst) begin
      state <= IDLE;
      sclk <= 1'b0;
      mosi <= 1'b0;
      miso <= 1'bx;
      data <= 8'h00;
      bit_count <= 3'b000;
    end else begin
      case (state)
        IDLE: begin
          if (!ss_in) begin
            state <= ACTIVE;
            sclk <= 1'b0;
            mosi <= data_in;
            miso <= 1'bx;
            data <= 8'h00;
            bit_count <= 3'b000;
          end
        end
        ACTIVE: begin
          sclk <= ~sclk;
          if (sclk) begin
            mosi <= data[7];
            miso <= miso | (ss_in & data_in & (1 << bit_count));
            data <= {data[6:0], data_in};
            bit_count <= bit_count + 1;
            if (bit_count == 3'b111) begin
              state <= IDLE;
            end
          end
        end
      endcase
    end
  end

endmodule

module diff_output_buf(
    input in,
    input oe,
    output out,
    output outb
);

wire inv_in = ~in;

// Output enable logic
wire oe_and_inv_in = oe & inv_in;
wire oe_and_in = oe & in;

// Positive output signal logic
wire out_and_inv_oe = out & ~oe;
wire out_and_inv_in = out & inv_in;
wire out_and_oe_and_in = out & oe_and_in;
wire out_mux = oe_and_inv_in | out_and_oe_and_in;
assign out = out_mux | out_and_inv_oe;

// Negative output signal logic
wire outb_and_inv_oe = outb & ~oe;
wire outb_and_in = outb & in;
wire outb_and_oe_and_inv_in = outb & oe_and_inv_in;
wire outb_mux = oe_and_in | outb_and_oe_and_inv_in;
assign outb = outb_mux | outb_and_inv_oe;

endmodule

module add_sub_4bit (
    input [3:0] A, B, // Inputs for the adder/subtractor
    input MODE, // Input mode for the adder/subtractor
    output reg [3:0] S // Output of the adder/subtractor
);

    always @(*) begin
        if (MODE == 1'b0) // Addition mode
            S = A + B;
        else // Subtraction mode
            S = A - B;
    end

endmodule

module twos_complement (
    input [15:0] A, // Input to be converted to two's complement
    output reg [15:0] S // Two's complement output
);

    always @(*) begin
        if (A[15] == 1'b0) // Positive number
            S = A;
        else // Negative number
            S = ~A + 1'b1;
    end

endmodule

module top_module (
    input [3:0] A, B, // Inputs for the adder/subtractor
    input MODE, // Input mode for the adder/subtractor
    output reg [15:0] S // Two's complement output of the adder/subtractor result
);

    wire [3:0] add_sub_result;
    add_sub_4bit add_sub_inst(.A(A), .B(B), .MODE(MODE), .S(add_sub_result));
    twos_complement twos_comp_inst(.A(add_sub_result), .S(S));

endmodule

module RegisterAdder ( clk, rst, load, D, Q );
  input [0:0] D;
  output [0:0] Q;
  input clk, rst, load;
  wire   n1, n2, n3, n4;

  // Inverter for reset signal
  CLKINVX1TS U1 ( .A(rst), .Y(n1) );

  // AND gate to determine when to load data
  OAI2BB2XLTS U2 ( .B0(n1), .B1(load), .A0N(load), .A1N(D[0]), .Y(n2) );

  // XOR gate to increment the register on each clock cycle
  XOR2XLTS U3 ( .A(n3), .B(clk), .Y(n4) );
  DFFRX2TS U4 ( .D(n2), .CK(n4), .RN(n1), .Q(n3), .QN(n2) );

  // Output register value
  DFFRX2TS U5 ( .D(n3), .CK(clk), .RN(n1), .Q(Q[0]), .QN(n1) );
endmodule

