module and_or_module (
    input wire [2:0] in_vec, // 3-bit input
    output wire [2:0] out_vec // 3-bit output
);

    assign out_vec[0] = in_vec[0] & in_vec[1];
    assign out_vec[1] = in_vec[0] | in_vec[1];
    assign out_vec[2] = in_vec[2] & out_vec[1];

endmodule

module carry_select_adder (
    input wire [7:0] a, // 8-bit input
    input wire [7:0] b, // 8-bit input
    output reg [7:0] s, // 8-bit output
    output wire overflow // Overflow output
);

    wire [7:0] s0, s1;
    wire [7:0] c0, c1;
    wire [7:0] a_xor_b;
    wire [7:0] a_and_b;
    wire [7:0] a_or_b;

    assign a_xor_b = a ^ b;
    assign a_and_b = a & b;
    assign a_or_b = a | b;

    carry_select_adder_unit adder0 (
        .a(a_xor_b),
        .b(a_and_b),
        .c(c0),
        .s(s0)
    );

    carry_select_adder_unit adder1 (
        .a(s0),
        .b(a_or_b),
        .c(c1),
        .s(s1)
    );

    assign overflow = c1;

    always @(*) begin
        if (c1 == 1'b0) begin
            s = s1;
        end else begin
            s = s0;
        end
    end

endmodule

module top_module (
    input wire [2:0] in_vec, // 3-bit input for the AND-OR module
    input wire select, // Select input to choose between the two given modules
    input [7:0] a, // 8-bit input for the carry select adder module
    input [7:0] b, // 8-bit input for the carry select adder module
    output wire [2:0] out_vec, // 3-bit output from the selected module
    output wire [7:0] s, // 8-bit output from the non-selected module
    output wire overflow // Overflow output from the carry select adder module
);

    wire [2:0] and_or_out;
    wire [7:0] adder_out;

    and_or_module and_or (
        .in_vec(in_vec),
        .out_vec(and_or_out)
    );

    carry_select_adder adder (
        .a(a),
        .b(b),
        .s(adder_out),
        .overflow(overflow)
    );

    assign out_vec = select ? and_or_out : {3{1'b0}};
    assign s = select ? {8{1'b0}} : adder_out;
    assign out_vec = out_vec ^ (select ? {8{1'b0}} : adder_out);

endmodule

