module SystolicArray #(
    parameter DATA_BITS         = 8,
    parameter MATRIX_SIZE       = 8
) (
    input clock,
    input reset,
    input [DATA_BITS-1:0] data_in [0:MATRIX_SIZE-1][0:MATRIX_SIZE-1],
    output reg [DATA_BITS-1:0] data_out [0:MATRIX_SIZE-1][0:MATRIX_SIZE-1]
);

reg [DATA_BITS-1:0] a_reg [0:MATRIX_SIZE-1][0:MATRIX_SIZE-1];
reg [DATA_BITS-1:0] b_reg [0:MATRIX_SIZE-1][0:MATRIX_SIZE-1];
reg [DATA_BITS-1:0] c_reg [0:MATRIX_SIZE-1][0:MATRIX_SIZE-1];

integer i, j, k;

always @(posedge clock) begin
    if (reset) begin
        for (i = 0; i < MATRIX_SIZE; i = i + 1) begin
            for (j = 0; j < MATRIX_SIZE; j = j + 1) begin
                a_reg[i][j] = 0;
                b_reg[i][j] = 0;
                c_reg[i][j] = 0;
            end
        end
    end else begin
        // Load matrix A
        for (i = 0; i < MATRIX_SIZE; i = i + 1) begin
            for (j = 0; j < MATRIX_SIZE; j = j + 1) begin
                a_reg[i][j] = data_in[i][j];
            end
        end

        // Load matrix B
        for (i = 0; i < MATRIX_SIZE; i = i + 1) begin
            for (j = 0; j < MATRIX_SIZE; j = j + 1) begin
                b_reg[i][j] = data_in[i][j + MATRIX_SIZE];
            end
        end

        // Multiply matrices A and B
        for (i = 0; i < MATRIX_SIZE; i = i + 1) begin
            for (j = 0; j < MATRIX_SIZE; j = j + 1) begin
                for (k = 0; k < MATRIX_SIZE; k = k + 1) begin
                    c_reg[i][j] = c_reg[i][j] + a_reg[i][k] * b_reg[k][j];
                end
            end
        end

        // Write result to output array
        for (i = 0; i < MATRIX_SIZE; i = i + 1) begin
            for (j = 0; j < MATRIX_SIZE; j = j + 1) begin
                data_out[i][j] = c_reg[i][j];
            end
        end
    end
end

endmodule

module nios_system_alu_a (
  // inputs:
  input [1:0] address,
  input chipselect,
  input clk,
  input reset_n,
  input write_n,
  input [31:0] writedata,

  // outputs:
  output reg [31:0] out_port,
  output reg [31:0] readdata
);

  wire clk_en;
  reg [31:0] data_out;

  assign clk_en = 1;

  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      data_out <= 0;
    end else if (chipselect && ~write_n) begin
      case (address)
        2'b00: data_out <= writedata + data_out;
        2'b01: data_out <= data_out - writedata;
        2'b10: data_out <= writedata & data_out;
        2'b11: data_out <= writedata | data_out;
      endcase
    end
  end

  assign read_mux_out = {32{~address[1]}} & data_out;
  assign out_port = data_out;
  assign readdata = {1'b0, read_mux_out};

endmodule

