  reg [31:0] mul_result_2;

  // Multiplication module 1
  mult_1 mult_1_inst (
    .a(a_1),
    .b(b_1),
    .result(mul_result_1)
  );

  // Multiplication module 2
  mult_2 mult_2_inst (
    .a(a_2),
