module top_module( 
    input [99:0] a, b, // 100-bit binary numbers
    input cin, // Carry-in input
    input [7:0] sel_mux, // Selection input for the 256-to-1 multiplexer
    input sel_func, // Selection input for the functional module
    output out // Output of the functional module
);

  // Hierarchical Carry-Select Adder
  wire [100:0] sum;
  wire [100:0] carry;
  wire [99:0] a_neg;
  wire [99:0] b_neg;
  wire [99:0] a_b_neg;

  assign a_neg = ~a + 1;
  assign b_neg = ~b + 1;
  assign a_b_neg = a_neg * b_neg;

  adder_level_0 adder0(
    .a(a[15:0]),
    .b(b[15:0]),
    .cin(cin),
    .sum(sum[15:0]),
    .carry(carry[0])
  );

  adder_level_1 adder1(
    .a(a[31:16]),
    .b(b[31:16]),
    .cin(carry[0]),
    .sum(sum[31:16]),
    .carry(carry[1])
  );

  adder_level_2 adder2(
    .a(a[47:32]),
    .b(b[47:32]),
    .cin(carry[1]),
    .sum(sum[47:32]),
    .carry(carry[2])
  );

  adder_level_3 adder3(
    .a(a[63:48]),
    .b(b[63:48]),
    .cin(carry[2]),
    .sum(sum[63:48]),
    .carry(carry[3])
  );

  adder_level_4 adder4(
    .a(a[79:64]),
    .b(b[79:64]),
    .cin(carry[3]),
    .sum(sum[79:64]),
    .carry(carry[4])
  );

  adder_level_5 adder5(
    .a(a[99:80]),
    .b(b[99:80]),
    .cin(carry[4]),
    .sum(sum[99:80]),
    .carry(carry[5])
  );

  // 256-to-1 Multiplexer
  wire [7:0] sel_mux_inv;
  wire [7:0] sel_mux_inv_neg;
  wire [7:0] sel_mux_inv_b_neg;
  wire [7:0] sel_mux_inv_b_neg_inv;
  wire [7:0] sel_mux_inv_b_neg_inv_a_neg;
  wire [7:0] sel_mux_inv_b_neg_inv_a_neg_b_neg;

  assign sel_mux_inv = ~sel_mux;
  assign sel_mux_inv_neg = sel_mux_inv + 1;
  assign sel_mux_inv_b_neg = sel_mux_inv * b_neg[7:0];
  assign sel_mux_inv_b_neg_inv = sel_mux_inv_neg * b[7:0];
  assign sel_mux_inv_b_neg_inv_a_neg = sel_mux_inv_b_neg * a_neg[7:0];
  assign sel_mux_inv_b_neg_inv_a_neg_b_neg = sel_mux_inv_b_neg_inv * b_neg[7:0];

  wire [99:0] product = a * b;
  wire out_func = product[sel_mux[7:0]] & sel_func;

  // Output
  assign out = out_func;

endmodule

module adder_level_0(
  input [15:0] a,
  input [15:0] b,
  input cin,
  output [15:0] sum,
  output carry
);
  wire [15:0] p;
  wire [15:0] g;

  assign p = a ^ b;
  assign g = a & b;

  assign sum[0] = p[0];
  assign carry = g[0] | (p[0] & cin);

  assign sum[1] = p[1] ^ carry;
  assign carry = g[1] | (p[1] & carry);

  assign sum[2] = p[2] ^ carry;
  assign carry = g[2] | (p[2] & carry);

  assign sum[3] = p[3] ^ carry;
  assign carry = g[3] | (p[3] & carry);

  assign sum[4] = p[4] ^ carry;
  assign carry = g[4] | (p[4] & carry);

  assign sum[5] = p[5] ^ carry;
  assign carry = g[5] | (p[5] & carry);

  assign sum[6] = p[6] ^ carry;
  assign carry = g[6] | (p[6] & carry);

  assign sum[7] = p[7] ^ carry;
  assign carry = g[7] | (p[7] & carry);

  assign sum[8] = p[8] ^ carry;
  assign carry = g[8] | (p[8] & carry);

  assign sum[9] = p[9] ^ carry;
  assign carry = g[9] | (p[9] & carry);

  assign sum[10] = p[10] ^ carry;
  assign carry = g[10] | (p[10] & carry);

  assign sum[11] = p[11] ^ carry;
  assign carry = g[11] | (p[11] & carry);

  assign sum[12] = p[12] ^ carry;
  assign carry = g[12] | (p[12] & carry);

  assign sum[13] = p[13] ^ carry;
  assign carry = g[13] | (p[13] & carry);

  assign sum[14] = p[14] ^ carry;
  assign carry = g[14] | (p[14] & carry);

  assign sum[15] = p[15] ^ carry;
endmodule

