module traffic_light_controller (
  input clk,
  input reset,
  output reg green,
  output reg yellow,
  output reg red
);

  parameter Green = 2'b00;
  parameter Yellow = 2'b01;
  parameter Red = 2'b10;

  reg [1:0] state;
  reg [3:0] count;

  always @(posedge clk) begin
    if (reset) begin
      state <= Green;
      count <= 4'b0;
    end else begin
      case (state)
        Green: begin
          green <= 1'b1;
          yellow <= 1'b0;
          red <= 1'b0;
          if (count == 4'd9) begin
            state <= Yellow;
            count <= 4'b0;
          end else begin
            count <= count + 1;
          end
        end
        Yellow: begin
          green <= 1'b0;
          yellow <= 1'b1;
          red <= 1'b0;
          if (count == 4'd4) begin
            state <= Red;
            count <= 4'b0;
          end else begin
            count <= count + 1;
          end
        end
        Red: begin
          green <= 1'b0;
          yellow <= 1'b0;
          red <= 1'b1;
          if (count == 4'd14) begin
            state <= Green;
            count <= 4'b0;
          end else begin
            count <= count + 1;
          end
        end
      endcase
    end
  end
endmodule

module Latches (
  input [n-1:0] d,
  input [n-1:0] J,
  input [n-1:0] K,
  input [n-1:0] t,
  input [n-1:0] s,
  input [n-1:0] r,
  input clk,
  output [m-1:0] q_D,
  output [m-1:0] q_JK,
  output [m-1:0] q_T,
  output [m-1:0] q_SR
);

parameter n = 1; // number of bits
parameter m = 1; // number of bits in output signals

reg [m-1:0] q_D;
reg [m-1:0] q_JK;
reg [m-1:0] q_T;
reg [m-1:0] q_SR;

always @(posedge clk) begin
  q_D <= d;
end

always @(posedge clk) begin
  if (J & ~K) begin
    q_JK <= ~q_JK;
  end else if (~J & K) begin
    q_JK <= q_JK;
  end
end

always @(posedge clk) begin
  if (t) begin
    q_T <= ~q_T;
  end else begin
    q_T <= q_T;
  end
end

always @(posedge clk) begin
  if (s) begin
    q_SR <= 1'b1;
  end else if (r) begin
    q_SR <= 1'b0;
  end else begin
    q_SR <= q_SR;
  end
end

endmodule

