module top_module (
    input clk,
    input rst,
    input [15:0] in,
    input [2:0] select1,
    input [2:0] select2,
    output [7:0] out
);

    wire [7:0] adder_out;
    wire [7:0] shift_reg_out;

    // Instantiate the 8-bit adder module
    adder_module adder_inst (
        .a(in[7:0]),
        .b(select1 == 0 ? 8'b00000000 : select1 == 1 ? 8'b00000001 : 8'b00000010),
        .sum(adder_out)
    );

    // Instantiate the 3-bit shift register module
    shift_register_module shift_reg_inst (
        .clk(clk),
        .rst(rst),
        .in(in[8:15]),
        .shift_amount(select2),
        .out(shift_reg_out)
    );

    // Perform the bitwise XOR operation on the upper 8 bits and lower 8 bits
    assign out = adder_out ^ shift_reg_out;

endmodule

