    input UD,
    input [3:0] A,
    input [3:0] B,
    input SUB,
    output reg [3:0] SUM,
    output reg [3:0] Q
);

reg [3:0] result;
wire carry;

adder_subtractor add_sub (
    .A(A),
    .B(B),
    .SUB(SUB),
    .SUM(result),
    .CARRY(carry)
);

always @(posedge CLK) begin
    if (UD == 1'b0) begin
        result <= result + 4'b0001;
