module mojo_com_logic #(
    parameter ADDR_SPACE = 64 //addr is last 6 bits
)(
    input clk,
    input rst,
    //SPI addressing interface
    input [ADDR_SPACE-1:0] reg_addr,
    input write,
    input new_req,
    input [7:0] write_value,
    output [7:0] read_value,
    output in_transaction,
    //Interface
    output [8*ADDR_SPACE-1:0] rx_arr,
    output rx_busy,
    output new_rx,
    input [8*ADDR_SPACE-1:0] tx_arr,
    output tx_busy
);

reg [7:0] tx_data;
reg [7:0] rx_data;
reg [ADDR_SPACE-1:0] addr;
reg [1:0] state;

assign in_transaction = (state != 0);

always @(posedge clk) begin
    if (rst) begin
        state <= 0;
        addr <= 0;
        tx_busy <= 0;
        rx_busy <= 0;
        new_rx <= 0;
    end else begin
        case (state)
            0: begin // Idle state
                if (new_req) begin
                    addr <= reg_addr;
                    if (write) begin
                        tx_data <= write_value;
                        state <= 1;
                        tx_busy <= 1;
                    end else begin
                        state <= 2;
                        tx_busy <= 1;
                    end
                end
            end
            1: begin // Write state
                if (!tx_busy) begin
                    state <= 0;
                end
            end
            2: begin // Read state
                tx_data <= 0; // Dummy write
                state <= 3;
                tx_busy <= 1;
            end
            3: begin // Receive state
                if (!tx_busy) begin
                    rx_data <= miso;
                    state <= 4;
                    rx_busy <= 1;
                end
            end
            4: begin // Receive state
                if (rx_busy) begin
                    rx_arr[8*addr +: 8] <= rx_data;
                    addr <= addr + 1;
                    if (addr == ADDR_SPACE-1) begin
                        state <= 0;
                        rx_busy <= 0;
                        new_rx <= 1;
                    end else begin
                        state <= 2;
                        tx_busy <= 1;
                    end
                end
            end
        endcase
    end
end

assign read_value = rx_data;

assign tx_busy = state == 1 || state == 3;

assign miso = tx_data;

assign tx_arr[8*addr +: 8] = tx_data;

endmodule

module top_module (
    input clk,
    input reset,   // Synchronous active-high reset
    output [3:1] ena,
    output [15:0] q);

    wire [15:0] binary_counter;
    wire [3:0] bcd_digit_0, bcd_digit_1, bcd_digit_2, bcd_digit_3;

    binary_counter_16bit binary_counter_inst (
        .clk(clk),
        .reset(reset),
        .q(binary_counter)
    );

    binary_to_bcd binary_to_bcd_inst (
        .bin(binary_counter),
        .bcd_digit_0(bcd_digit_0),
        .bcd_digit_1(bcd_digit_1),
        .bcd_digit_2(bcd_digit_2),
        .bcd_digit_3(bcd_digit_3)
    );

    priority_encoder priority_encoder_inst (
        .bcd_digit_0(bcd_digit_0),
        .bcd_digit_1(bcd_digit_1),
        .bcd_digit_2(bcd_digit_2),
        .bcd_digit_3(bcd_digit_3),
        .ena(ena)
    );

    assign q = {bcd_digit_3, bcd_digit_2, bcd_digit_1, bcd_digit_0};

endmodule

module binary_counter_16bit (
    input clk,
    input reset,
    output reg [15:0] q);

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            q <= 16'd0;
        end else begin
            q <= q + 1;
        end
    end

endmodule

module binary_to_bcd (
    input [15:0] bin,
    output reg [3:0] bcd_digit_0,
    output reg [3:0] bcd_digit_1,
    output reg [3:0] bcd_digit_2,
    output reg [3:0] bcd_digit_3);

    integer i;

    always @(*) begin
        bcd_digit_0 = 4'd0;
        bcd_digit_1 = 4'd0;
        bcd_digit_2 = 4'd0;
        bcd_digit_3 = 4'd0;

        for (i = 0; i < 16; i = i + 1) begin
            if (bcd_digit_0 >= 5) begin
                bcd_digit_0 = bcd_digit_0 + 3;
            end
            if (bcd_digit_1 >= 5) begin
                bcd_digit_1 = bcd_digit_1 + 3;
            end
            if (bcd_digit_2 >= 5) begin
                bcd_digit_2 = bcd_digit_2 + 3;
            end
            if (bcd_digit_3 >= 5) begin
                bcd_digit_3 = bcd_digit_3 + 3;
            end

            {bcd_digit_3, bcd_digit_2, bcd_digit_1, bcd_digit_0} = {bcd_digit_3, bcd_digit_2, bcd_digit_1, bcd_digit_0} << 1;
            bcd_digit_0[0] = bin[15 - i];
        end
    end

endmodule

module priority_encoder (
    input [3:0] bcd_digit_0,
    input [3:0] bcd_digit_1,
    input [3:0] bcd_digit_2,
    input [3:0] bcd_digit_3,
    output reg [3:1] ena);

    always @(*) begin
        if (bcd_digit_3 != 4'd0) begin
            ena = 3'b001;
        end else if (bcd_digit_2 != 4'd0) begin
            ena = 3'b010;
        end else if (bcd_digit_1 != 4'd0) begin
            ena = 3'b100;
        end else begin
            ena = 3'b000;
        end
    end

endmodule

module matrix_mult(
    input clk,
    input rst,
    input inverse,
    input signed [18:0] i_0,
    input signed [18:0] i_1,
    input signed [18:0] i_2,
    input signed [18:0] i_3,
    output reg signed [18+7+2:0] m1_0,
    output reg signed [18+7+2:0] m1_1,
    output reg signed [18+7+2:0] m1_2,
    output reg signed [18+7+2:0] m1_3
);

// Intermediate values
wire signed [18+7:0] w0_0, w0_1, w0_2, w0_3;
wire signed [18+7:0] w1_0, w1_1, w1_2, w1_3;
wire signed [18+7:0] w2_0, w2_1, w2_2, w2_3;
wire signed [18+7:0] w3_0, w3_1, w3_2, w3_3;
wire signed [18+8:0] w00, w01, w10, w11, w20, w21, w30, w31;
wire signed [18+9:0] w0, w1, w2, w3;

// Spiral modules
spiral_4 spiral_40 (.i_data(i_0), .o_data_18(w0_0), .o_data_50(w0_1), .o_data_75(w0_2), .o_data_89(w0_3));
spiral_4 spiral_41 (.i_data(i_1), .o_data_18(w1_0), .o_data_50(w1_1), .o_data_75(w1_2), .o_data_89(w1_3));
spiral_4 spiral_42 (.i_data(i_2), .o_data_18(w2_0), .o_data_50(w2_1), .o_data_75(w2_2), .o_data_89(w2_3));
spiral_4 spiral_43 (.i_data(i_3), .o_data_18(w3_0), .o_data_50(w3_1), .o_data_75(w3_2), .o_data_89(w3_3));

// Combinational logic
assign w00 = w0_0 + w2_2;
assign w01 = inverse ? -w1_1 - w3_3 : w1_1 + w3_3;
assign w10 = inverse ? -(-w0_1 - w2_0) : -(w0_1 + w2_0);
assign w11 = -w1_3 + w3_2;
assign w20 = w0_2 - w2_3;
assign w21 = inverse ? -w1_0 - w3_1 : w1_0 + w3_1;
assign w30 = inverse ? -(-w0_3 - w2_1) : -(w0_3 + w2_1);
assign w31 = w1_2 + w3_0;
assign w0 = w00 + w01;
assign w1 = w10 + w11;
assign w2 = w20 + w21;
assign w3 = w30 + w31;

// Registers
reg signed [18+7+2:0] m10, m11, m12, m13;

// Sequential logic
always @(posedge clk or negedge rst) begin
    if (!rst) begin
        m10 <= 28'b0;
        m11 <= 28'b0;
        m12 <= 28'b0;
        m13 <= 28'b0;
    end
    else begin
        m10 <= w0;
        m11 <= w1;
        m12 <= w2;
        m13 <= w3;
    end
end

always @(posedge clk or negedge rst) begin
    if (!rst) begin
        m1_0 <= 28'b0;
        m1_1 <= 28'b0;
        m1_2 <= 28'b0;
        m1_3 <= 28'b0;
    end
    else begin
        m1_0 <= m10;
        m1_1 <= m11;
        m1_2 <= m12;
        m1_3 <= m13;
    end
end

endmodule

module dff_sr (
    input clk,
    input d,
    input set,
    input reset,
    output reg q,
    output reg q_n
);

always @(posedge clk) begin
    if (reset) begin
        q <= 0;
        q_n <= 1;
    end else if (set) begin
        q <= 1;
        q_n <= 0;
    end else begin
        q <= d;
        q_n <= ~d;
    end
end

endmodule

module ym_timers(
    input CLK,
    input TICK_144,
    input nRESET,
    input [9:0] YMTIMER_TA_LOAD,
    input [7:0] YMTIMER_TB_LOAD,
    input [5:0] YMTIMER_CONFIG,
    input clr_run_A, set_run_A, clr_run_B, set_run_B,
    output FLAG_A, FLAG_B,
    output nIRQ
);

    reg [9:0] timer_A_reg;
    reg [7:0] timer_B_reg;
    reg [1:0] timer_A_state;
    reg [1:0] timer_B_state;
    reg timer_A_run;
    reg timer_B_run;
    reg timer_A_irq;
    reg timer_B_irq;

    wire timer_A_ovf;
    wire timer_B_ovf;

    assign FLAG_A = timer_A_ovf;
    assign FLAG_B = timer_B_ovf;
    assign nIRQ = ~(timer_A_irq & YMTIMER_CONFIG[2] | timer_B_irq & YMTIMER_CONFIG[3]);

    ym_timer #(.mult_width(1), .cnt_width(10)) timer_A (
        .CLK            ( CLK ),
        .TICK_144       ( TICK_144 ),
        .nRESET         ( nRESET ),
        .LOAD_VALUE     ( YMTIMER_TA_LOAD ),
        .LOAD           ( YMTIMER_CONFIG[0] ),
        .CLR_FLAG       ( YMTIMER_CONFIG[4] ),
        .SET_RUN        ( set_run_A ),
        .CLR_RUN        ( clr_run_A ),
        .OVF_FLAG       ( timer_A_ovf ),
        .OVF            ( timer_A_run & timer_A_ovf )
    );

    ym_timer #(.mult_width(4), .cnt_width(8)) timer_B (
        .CLK            ( CLK ),
        .TICK_144       ( TICK_144 ),
        .nRESET         ( nRESET ),
        .LOAD_VALUE     ( YMTIMER_TB_LOAD ),
        .LOAD           ( YMTIMER_CONFIG[1] ),
        .CLR_FLAG       ( YMTIMER_CONFIG[5] ),
        .SET_RUN        ( set_run_B ),
        .CLR_RUN        ( clr_run_B ),
        .OVF_FLAG       ( timer_B_ovf ),
        .OVF            ( timer_B_run & timer_B_ovf )
    );

    always @(posedge CLK) begin
        if (nRESET) begin
            timer_A_reg <= YMTIMER_TA_LOAD;
            timer_B_reg <= YMTIMER_TB_LOAD;
            timer_A_state <= 2'b00;
            timer_B_state <= 2'b00;
            timer_A_run <= 1'b0;
            timer_B_run <= 1'b0;
            timer_A_irq <= 1'b0;
            timer_B_irq <= 1'b0;
        end else begin
            if (YMTIMER_CONFIG[0]) begin
                timer_A_reg <= YMTIMER_TA_LOAD;
            end
            if (YMTIMER_CONFIG[1]) begin
                timer_B_reg <= YMTIMER_TB_LOAD;
            end
            case (timer_A_state)
                2'b00: begin // Idle
                    timer_A_run <= 1'b0;
                    if (set_run_A) begin
                        timer_A_state <= 2'b01;
                    end
                end
                2'b01: begin // Running
                    timer_A_run <= 1'b1;
                    if (clr_run_A) begin
                        timer_A_state <= 2'b00;
                    end else if (timer_A_ovf) begin
                        timer_A_state <= 2'b10;
                    end
                end
                2'b10: begin // Overflow
                    timer_A_irq <= 1'b1;
                    timer_A_state <= 2'b00;
                end
            endcase
            case (timer_B_state)
                2'b00: begin // Idle
                    timer_B_run <= 1'b0;
                    if (set_run_B) begin
                        timer_B_state <= 2'b01;
                    end
                end
                2'b01: begin // Running
                    timer_B_run <= 1'b1;
                    if (clr_run_B) begin
                        timer_B_state <= 2'b00;
                    end else if (timer_B_ovf) begin
                        timer_B_state <= 2'b10;
                    end
                end
                2'b10: begin // Overflow
                    timer_B_irq <= 1'b1;
                    timer_B_state <= 2'b00;
                end
            endcase
            if (timer_A_run) begin
                timer_A_reg <= timer_A_reg - 1;
            end
            if (timer_B_run) begin
                timer_B_reg <= timer_B_reg - 1;
            end
        end
    end

endmodule

module adder_subtractor (
  input [3:0] A,
  input [3:0] B,
  input sub,
  output [3:0] result
);

  wire [3:0] sum;
  wire [3:0] carry_out;

  // Full Adder
  full_adder FA0(.a(A[0]), .b(B[0]), .cin(sub), .sum(sum[0]), .cout(carry_out[0]));
  full_adder FA1(.a(A[1]), .b(B[1]), .cin(carry_out[0]), .sum(sum[1]), .cout(carry_out[1]));
  full_adder FA2(.a(A[2]), .b(B[2]), .cin(carry_out[1]), .sum(sum[2]), .cout(carry_out[2]));
  full_adder FA3(.a(A[3]), .b(B[3]), .cin(carry_out[2]), .sum(sum[3]), .cout(carry_out[3]));

  // Full Subtractor
  full_subtractor FS0(.a(A[0]), .b(B[0]), .bin(sub), .diff(sum[0]), .bout(carry_out[0]));
  full_subtractor FS1(.a(A[1]), .b(B[1]), .bin(carry_out[0]), .diff(sum[1]), .bout(carry_out[1]));
  full_subtractor FS2(.a(A[2]), .b(B[2]), .bin(carry_out[1]), .diff(sum[2]), .bout(carry_out[2]));
  full_subtractor FS3(.a(A[3]), .b(B[3]), .bin(carry_out[2]), .diff(sum[3]), .bout(carry_out[3]));

  // Output result based on sub control input
  assign result = sub ? sum : carry_out;

endmodule
module full_adder (
  input a,
  input b,
  input cin,
  output sum,
  output cout
);

  wire s1;
  wire c1;
  wire c2;

  // Half Adder 1
  half_adder HA1(.a(a), .b(b), .sum(s1), .carry(c1));

  // Half Adder 2
  half_adder HA2(.a(s1), .b(cin), .sum(sum), .carry(c2));

  // Calculate carry_out
  assign cout = c1 | c2;

endmodule
module full_subtractor (
  input a,
  input b,
  input bin,
  output diff,
  output bout
);

  wire d1;
  wire b1;
  wire b2;

  // Half Subtractor 1
  half_subtractor HS1(.a(a), .b(b), .diff(d1), .borrow(b1));

  // Half Subtractor 2
  half_subtractor HS2(.a(d1), .b(bin), .diff(diff), .borrow(b2));

  // Calculate borrow_out
  assign bout = b1 | b2;

endmodule
module half_adder (
  input a,
  input b,
  output sum,
  output carry
);

  assign sum = a ^ b;
  assign carry = a & b;

endmodule
module half_subtractor (
  input a,
  input b,
  output diff,
  output borrow
);

  assign diff = a ^ b;
  assign borrow = ~a & b;

endmodule

