      c4_data.counter = 4'h7;
   end

   always @ (posedge clk) begin
      cyc <= cyc + 1;
      if (cyc<2) begin
	 c1_data.reset <= 1;
	 c2_data.reset <= 1;
	 c3_data.reset <= 1;
	 c4_data.reset <= 1;
      end
      if (cyc==2) begin
	 c1_data.reset <= 0;
	 c2_data.reset <= 0;
	 c3_data.reset <= 0;
	 c4_data.reset <= 0;
      end
      if (cyc==20) begin
	 $write("[%0t] cyc%0d: c1 %0x %0x  c2 %0x %0x  c3 %0x %0x  c4 %0x %0x\n", $time, cyc,
		c1_data.counter, c1_data.reset,
		c2_data.counter, c2_data.reset,
		c3_data.counter, c3_data.reset,
		c4_data.counter, c4_data.reset);
	 if (c1_data.counter != 2) $stop;
	 if (c2_data.counter != 3) $stop;
	 if (c3_data.counter != 4) $stop;
	 if (c4_data.counter != 5) $stop;
	 $write("*-* All Finished *-*\n");
	 $finish;
      end
   end
endmodule

module nor_gate(
