module splitter(
    input wire clk,
    input wire [15:0] in,
    output reg [7:0] out_hi,
    output reg [7:0] out_lo
);

    reg [3:0] count;

    always @(posedge clk) begin
        if(count == 0) begin
            out_hi <= in[15:8];
            count <= 1;
        end else begin
            out_lo <= in[7:0];
            count <= 0;
        end
    end

