    input wire [15:0] in,
    output wire out,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo 
);

    wire nor_out;
    wire [7:0] splitter_out_hi;
    wire [7:0] splitter_out_lo;

    nor_gate nor_inst(
        .a(a),
        .b(b),
        .out(nor_out)
    );

    splitter splitter_inst(
        .clk(1'b1),
        .in(in),
        .out_hi(splitter_out_hi),
        .out_lo(splitter_out_lo)
    );

    or_module or_inst(
        .a(nor_out),
