module top_module (
    input [1:0] sel, // 2-bit select input for the multiplexer
    input [3:0] in, // 4-bit input for the multiplexer
    input enable, // Enable input for the decoder
    input [1:0] select, // 2-bit select input for the decoder
    output [3:0] out // 4-bit output
);

// 4-input multiplexer
wire [3:0] mux_out;
assign mux_out = (sel == 2'b00) ? in[0] :
                 (sel == 2'b01) ? in[1] :
                 (sel == 2'b10) ? in[2] :
                                  in[3];

// 4-to-16 decoder
wire [15:0] decoder_out;
assign decoder_out = (enable) ? {16{select[1], select[0]}} : 16'b0;

// Functional module
assign out = (decoder_out[sel]) ? decoder_out[sel] : mux_out;

endmodule

module top_module (
    input clk,
    input reset,
    input [7:0] in,
    input select,
    output [7:0] out
);

    wire [15:0] sum;
    wire threshold_exceeded;
    wire edge_detected;
    wire [7:0] active_output;
    wire [7:0] and_result;

    // Instantiate the first given module
    sum_module sum_inst (
        .in(in),
        .sum(sum),
        .threshold_exceeded(threshold_exceeded)
    );

    // Instantiate the second given module
    edge_detection_module edge_inst (
        .in(in[7]),
        .edge_detected(edge_detected)
    );

    // Control logic for selecting active module
    assign active_output = select ? edge_detected : threshold_exceeded;

    // Instantiate the functional module for bitwise AND operation
    and_module and_inst (
        .in1(active_output),
        .in2(sum[15:8]),
        .and_result(and_result)
    );

    // Output assignment
    assign out = threshold_exceeded ? edge_detected ? and_result : edge_detected : and_result;

endmodule

// First given module
module sum_module (
    input [31:0] in,
    output [15:0] sum,
    output threshold_exceeded
);

    assign sum = in[31:16] + in[15:0];
    assign threshold_exceeded = (sum > 16'h8000);

endmodule

// Second given module
module edge_detection_module (
    input in,
    output edge_detected
);

    reg prev_state;

    always @ (posedge in) begin
        edge_detected = (in && !prev_state);
        prev_state = in;
    end

endmodule

// Functional module for bitwise AND operation
module and_module (
    input [7:0] in1,
    input [7:0] in2,
    output [7:0] and_result
);

    assign and_result = in1 & in2;

endmodule

module FpuFpD_Add(
    clk,
    enable,
    doSub,
    srca,
    srcb,
    dst
);

input clk;
input enable;
input doSub;
input[63:0] srca;
input[63:0] srcb;
output[63:0] dst;

reg sgna;
reg sgnb;
reg sgnc;

reg[12:0] exa;
reg[12:0] exb;
reg[12:0] exc;
reg[12:0] exm;

reg[63:0] tFracA;
reg[63:0] tFracB;
reg[63:0] tFracC;
reg[63:0] tFracA1;
reg[63:0] tFracB1;
reg[63:0] tFracC1;

reg[63:0] tFracC2;

reg[63:0] tFracC2_A;    //32
reg[63:0] tFracC2_B;    //16
reg[63:0] tFracC2_C;    //8
reg[63:0] tFracC2_D;    //4
reg[63:0] tFracC2_E;    //2

reg[12:0] tExc_A;
reg[12:0] tExc_B;
reg[12:0] tExc_C;
reg[12:0] tExc_D;
reg[12:0] tExc_E;

reg[63:0] tDst;

assign dst = tDst;

always @*
begin
    // Step 1: Extract the sign, exponent, and fraction from srca and srcb.
    sgna = srca[63];
    sgnb = srcb[63];

    exa[10:0] = srca[62:52];
    exb[10:0] = srcb[62:52];
    exa[12:11] = 0;
    exb[12:11] = 0;

    // Step 2: Determine the larger of the two exponents and shift the fraction of the smaller exponent to match the larger exponent.
    exm = (exa >= exb) ? exa : exb;

    if (sgna) begin
        tFracA[63:52] = ~(12'h1);
        tFracA[51:0] = ~(srca[51:0]);
    end else begin
        tFracA[63:52] = 12'h1;
        tFracA[51:0] = srca[51:0];
    end

    if (sgnb ^ doSub) begin
        tFracB[63:52] = ~(12'h1);
        tFracB[51:0] = ~(srcb[51:0]);
    end else begin
        tFracB[63:52] = 12'h1;
        tFracB[51:0] = srcb[51:0];
    end

    tFracA1 = tFracA >>> (exm - exa);
    tFracB1 = tFracB >>> (exm - exb);

    // Step 3: Perform addition or subtraction on the fractions, depending on the value of doSub.
    if (doSub) begin
        tFracC1 = tFracA1 - tFracB1;
    end else begin
        tFracC1 = tFracA1 + tFracB1;
    end

    // Step 4: Normalize the result and round to the nearest representable value.
    if (tFracC1[63]) begin
        sgnc = 1;
        tFracC2 = ~tFracC1;
    end else begin
        sgnc = 0;
        tFracC2 = tFracC1;
    end

    if (tFracC2[52:0] == 0) begin
        sgnc = 0;
        tFracC = 0;
        exc = 0;
    end else if (tFracC2[53:52] == 0) begin
        if (tFracC2[52:21] == 0) begin
            tFracC2_A = tFracC2 << 32;
            tExc_A = exm - 32;
        end else begin
            tFracC2_A = tFracC2;
            tExc_A = exm;
        end

        if (tFracC2_A[52:37] == 0) begin
            tFracC2_B = tFracC2_A << 16;
            tExc_B = tExc_A - 16;
        end else begin
            tFracC2_B = tFracC2_A;
            tExc_B = tExc_A;
        end

        if (tFracC2_B[52:45] == 0) begin
            tFracC2_C = tFracC2_B << 8;
            tExc_C = tExc_B - 8;
        end else begin
            tFracC2_C = tFracC2_B;
            tExc_C = tExc_B;
        end

        if (tFracC2_C[52:49] == 0) begin
            tFracC2_D = tFracC2_C << 4;
            tExc_D = tExc_C - 4;
        end else begin
            tFracC2_D = tFracC2_C;
            tExc_D = tExc_C;
        end

        if (tFracC2_D[52:51] == 0) begin
            tFracC2_E = tFracC2_D << 2;
            tExc_E = tExc_D - 2;
        end else begin
            tFracC2_E = tFracC2_D;
            tExc_E = tExc_D;
        end

        if (tFracC2_E[52] == 0) begin
            tFracC = tFracC2_E << 1;
            exc = tExc_E - 1;
        end else begin
            tFracC = tFracC2_E;
            exc = tExc_E;
        end
    end else begin
        if (tFracC2[53]) begin
            tFracC = tFracC2 >> 1;
            exc = exm + 1;
        end else begin
            tFracC = tFracC2;
            exc = exm;
        end
    end

    // Step 5: Output the result in the form of a 64-bit floating-point number.
    if (exc[12]) begin
        // NaN
        tDst[63:0] = 64'h7FF8_0000_0000_0000;
    end else if (exc[11]) begin
        // Infinity
        tDst[63] = sgnc;
        tDst[62:0] = 63'h7FF0_0000_0000_0000;
    end else begin
        // Normalized number
        tDst[63] = sgnc;
        tDst[62:52] = exc[10:0];
        tDst[51:0] = tFracC[51:0];
    end
end

endmodule

module majority_counter (
    input clk,
    input reset,
    input enable,
    input A, B, C, D,
    output reg [7:0] final_output
);

    wire Y;
    wire [3:0] counter_out;
    wire [1:0] counter_out_even;

    majority_gate majority_gate_inst (
        .A(A),
        .B(B),
        .C(C),
        .D(D),
        .Y(Y)
    );

    counter counter_inst (
        .clk(clk),
        .reset(reset),
        .enable(enable),
        .out(counter_out)
    );

    always @ (posedge clk or posedge reset) begin
        if (reset) begin
            final_output <= 0;
        end else if (enable) begin
            if (counter_out[0] == 1) begin
                final_output <= counter_out;
            end else begin
                final_output <= Y;
            end
        end
    end

    assign counter_out_even = counter_out[0] ? counter_out[1:0] : counter_out[2:1];

endmodule

module majority_gate (
    input A, B, C, D,
