module compare_data (
  input clk,
  input rst,
  input [7:0] data1,
  input [7:0] data2,
  output reg eq,
  output reg done
);

  reg [7:0] data1_reg;
  reg [7:0] data2_reg;
  reg [3:0] byte_cnt;

  always @(posedge clk) begin
    if (rst) begin
      eq <= 0;
      done <= 0;
      byte_cnt <= 0;
      data1_reg <= 0;
      data2_reg <= 0;
    end
    else begin
      if (byte_cnt == 0) begin
        data1_reg <= data1;
        data2_reg <= data2;
        byte_cnt <= 1;
      end
      else if (byte_cnt < 7) begin
        byte_cnt <= byte_cnt + 1;
      end
      else begin
        if (data1_reg == data2_reg) begin
          eq <= 1;
        end
        else begin
          eq <= 0;
        end
        done <= 1;
        byte_cnt <= 0;
      end
    end
  end

endmodule

module add_sub (
    input [3:0] A,
    input [3:0] B,
    input sub,
    output reg [3:0] OUT,
    output ov
);
    reg [4:0] temp;
    always @(*) begin
        if (sub) begin
            temp = A - B;
            OUT = temp[3:0];
            ov = temp[4];
        end else begin
            temp = A + B;
            OUT = temp[3:0];
            ov = temp[4];
        end
    end
endmodule

module multiplier (
    input [3:0] A,
    input [3:0] B,
    output reg [7:0] OUT,
    output ov
);
    reg [7:0] temp;
    always @(*) begin
        temp = {A, 4'b0} * {B, 4'b0};
        OUT = temp[7:0];
        ov = temp[8];
    end
endmodule

module top_module (
    input [3:0] in_0,
    input [3:0] in_1,
    input ctrl,
    input [3:0] A,
    input [3:0] B,
    input select,
    output reg [7:0] OUT,
    output ov
);
    wire [3:0] add_sub_out;
    wire add_sub_ov;
    wire [7:0] multiplier_out;
    wire multiplier_ov;

    add_sub add_sub_inst (
        .A(A),
        .B(B),
        .sub(ctrl),
        .OUT(add_sub_out),
        .ov(add_sub_ov)
    );

    multiplier multiplier_inst (
        .A(in_0),
        .B(in_1),
        .OUT(multiplier_out),
        .ov(multiplier_ov)
    );

    always @(*) begin
        if (select) begin
            OUT = add_sub_out;
            ov = add_sub_ov;
        end else begin
            OUT = multiplier_out;
            ov = multiplier_ov;
        end
    end
endmodule

module mbus_wire_ctrl(
	input RESETn,
	input DOUT_FROM_BUS,
	input CLKOUT_FROM_BUS,
	`ifdef POWER_GATING
	input DIN,
	input CLKIN,
	input RELEASE_ISO_FROM_SLEEP_CTRL,
	input EXTERNAL_INT,
	`endif
	output reg DOUT,
	output reg CLKOUT
);

`ifdef POWER_GATING
always @ *
begin
	if (~RESETn)
		CLKOUT <= `SD 1'b1;
	else if (RELEASE_ISO_FROM_SLEEP_CTRL==`IO_HOLD)
		CLKOUT <= `SD CLKIN;
	else
		CLKOUT <= `SD CLKOUT_FROM_BUS;

	if (~RESETn)
		DOUT <= `SD 1'b1;
	else if (EXTERNAL_INT)
		DOUT <= `SD 0;
	else
	begin
		if (RELEASE_ISO_FROM_SLEEP_CTRL==`IO_HOLD)
			DOUT <= `SD DIN;
		else
			DOUT <= `SD DOUT_FROM_BUS;
	end
end
`else
always @ *
begin
	if (~RESETn)
		CLKOUT <= `SD 1'b1;
	else
		CLKOUT <= `SD CLKOUT_FROM_BUS;

	if (~RESETn)
		DOUT <= `SD 1'b1;
	else
		DOUT <= `SD DOUT_FROM_BUS;
end
`endif

endmodule

module booth_multiplier (
    input clk,
    input reset,
    input signed [31:0] a,
    input signed [31:0] b,
    output signed [63:0] product
);

    wire [3:0] a_reg, b_reg;
    wire [7:0] product_reg;
    wire [4:0] multiplier_out;
    wire [3:0] adder_in0, adder_in1;
    wire adder_carry_in, adder_carry_out;

    multiplier multiplier_inst(
        .a(a_reg),
        .b(b_reg),
        .product(product_reg)
    );

    ripple_carry_adder adder_inst(
        .in0(adder_in0),
