module ps2_data_receiver (
  input clk,
  input reset,
  input wait_for_incoming_data,
  input start_receiving_data,
  input ps2_clk_posedge,
  input ps2_clk_negedge,
  input ps2_data,
  output reg [7:0] received_data,
  output reg received_data_en
);

  // states
  localparam PS2_STATE_0_IDLE          = 3'h0,
             PS2_STATE_1_WAIT_FOR_DATA = 3'h1,
             PS2_STATE_2_DATA_IN       = 3'h2,
             PS2_STATE_3_PARITY_IN     = 3'h3,
             PS2_STATE_4_STOP_IN       = 3'h4;

  // Internal Wires
  reg [3:0] data_count;
  reg [7:0] data_shift_reg;

  // State Machine Registers
  reg [2:0] ns_ps2_receiver;
  reg [2:0] s_ps2_receiver;

  // Defaults
  always @(posedge clk) begin
    if (reset == 1'b1) s_ps2_receiver <= PS2_STATE_0_IDLE;
    else s_ps2_receiver <= ns_ps2_receiver;
  end

  // State machine
  always @(*) begin
    ns_ps2_receiver = PS2_STATE_0_IDLE;
    case (s_ps2_receiver)
      PS2_STATE_0_IDLE: begin
        if (wait_for_incoming_data && !received_data_en) ns_ps2_receiver = PS2_STATE_1_WAIT_FOR_DATA;
        else if (start_receiving_data && !received_data_en) ns_ps2_receiver = PS2_STATE_2_DATA_IN;
        else ns_ps2_receiver = PS2_STATE_0_IDLE;
      end
      PS2_STATE_1_WAIT_FOR_DATA: begin
        if (!ps2_data && ps2_clk_posedge) ns_ps2_receiver = PS2_STATE_2_DATA_IN;
        else if (!wait_for_incoming_data) ns_ps2_receiver = PS2_STATE_0_IDLE;
        else ns_ps2_receiver = PS2_STATE_1_WAIT_FOR_DATA;
      end
      PS2_STATE_2_DATA_IN: begin
        if (data_count == 7 && ps2_clk_posedge) ns_ps2_receiver = PS2_STATE_3_PARITY_IN;
        else ns_ps2_receiver = PS2_STATE_2_DATA_IN;
      end
      PS2_STATE_3_PARITY_IN: begin
        if (ps2_clk_posedge) ns_ps2_receiver = PS2_STATE_4_STOP_IN;
        else ns_ps2_receiver = PS2_STATE_3_PARITY_IN;
      end
      PS2_STATE_4_STOP_IN: begin
        if (ps2_clk_posedge) ns_ps2_receiver = PS2_STATE_0_IDLE;
        else ns_ps2_receiver = PS2_STATE_4_STOP_IN;
      end
      default: begin
        ns_ps2_receiver = PS2_STATE_0_IDLE;
      end
    endcase
  end

  // Data counter
  always @(posedge clk) begin
    if (reset) data_count <= 3'h0;
    else if (s_ps2_receiver == PS2_STATE_2_DATA_IN && ps2_clk_posedge) data_count <= data_count + 3'h1;
    else if (s_ps2_receiver != PS2_STATE_2_DATA_IN) data_count <= 3'h0;
  end

  // Data shift register
  always @(posedge clk) begin
    if (reset) data_shift_reg <= 8'h00;
    else if (s_ps2_receiver == PS2_STATE_2_DATA_IN && ps2_clk_posedge) data_shift_reg <= {ps2_data, data_shift_reg[7:1]};
  end

  // Received data
  always @(posedge clk) begin
    if (reset) received_data <= 8'h00;
    else if (s_ps2_receiver == PS2_STATE_4_STOP_IN) received_data <= data_shift_reg;
  end

  // Received data enable
  always @(posedge clk) begin
    if (reset) received_data_en <= 1'b0;
    else if (s_ps2_receiver == PS2_STATE_4_STOP_IN && ps2_clk_posedge) received_data_en <= 1'b1;
    else received_data_en <= 1'b0;
  end

endmodule

