    input [1:0] iterations,
    output reg valid,
    output reg [7:0] result
);

    wire [3:0] consecutive_zeros;
    wire [7:0] sqrt_consecutive_zeros;

    consecutive_zeros consecutive_zeros_inst (
        .clk(clk),
        .reset(reset),
