module consecutive_zeros (
    input clk,
    input reset,
    input [15:0] in,
    output reg [3:0] consecutive_zeros
);

    reg [3:0] count;
    reg [3:0] max_count;

    always @(posedge clk) begin
        if (reset) begin
            count <= 0;
            max_count <= 0;
        end else if (in == 16'h0000) begin
            count <= count + 1;
            max_count <= count > max_count ? count : max_count;
        end else begin
            count <= 0;
            max_count <= max_count;
        end
    end

    assign consecutive_zeros = max_count;

endmodule

module newton_raphson (
    input clk,
    input reset,
    input [3:0] in,
    input [1:0] iterations,
    output reg [7:0] sqrt_out
);

    reg [7:0] x;
    reg [7:0] x_next;
    reg [7:0] a;

    always @(posedge clk) begin
        if (reset) begin
            x <= 0;
            x_next <= 0;
            a <= in;
        end else if (iterations != 0) begin
            x <= x_next;
            x_next <= (x + (a / x)) >> 1;
            iterations <= iterations - 1;
        end else begin
            sqrt_out <= x_next;
        end
    end

endmodule

module array_multiplier (
    input [15:0] A,
    input [15:0] B,
    output [31:0] out
);

wire [31:0] product [15:0];

genvar i, j;

generate
    for (i = 0; i < 16; i = i + 1) begin : row
        assign product[i] = {16'b0, A[i]} * {16'b0, B};
    end
endgenerate

assign out = product[0];
generate
    for (j = 1; j < 16; j = j + 1) begin : column
        assign out = out + (product[j] << j);
    end
endgenerate

endmodule

module top_module (
