);

    wire signed [3:0] sum;
    wire overflow_adder;
    signed_comparator comp(A, B, eq, gt, lt);
    signed_adder adder(A, B, sum, overflow_adder);

    assign overflow = overflow_adder;

    always @(*) begin
        if (eq) begin
            out = sum;
        end else if (gt) begin
            out = A;
        end else begin
            out = B;
        end
    end

