module signed_adder (
    input signed [3:0] A,
    input signed [3:0] B,
    output signed [3:0] out,
    output overflow
);

    wire [3:0] sum;
    wire carry;

    assign overflow = (A[3] == B[3] && sum[3] != A[3]) ? 1 : 0;

    assign {carry, sum} = A + B;

    assign out = {overflow, sum};

endmodule

module signed_comparator (
    input signed [3:0] A,
    input signed [3:0] B,
    output eq,
    output gt,
    output lt
);

    assign eq = (A == B);

    assign gt = (A > B);

    assign lt = (A < B);

endmodule

