wire [1:0] state_wire;
reg [99:0] add_reg;
wire [199:0] add_wire;

// Booth's algorithm
assign booth_wire = {b_reg[99], b_reg} - {1'b0, b_reg, 1'b0};
assign state_wire = booth_reg[1:0];

