    case(state_wire)
        2'b00: booth_reg = {1'b0, booth_reg[101:1]};
        2'b01: booth_reg = booth_reg + {1'b0, a_reg, 1'b0};
        2'b10: booth_reg = booth_reg + {1'b0, booth_wire[101:1]};
        2'b11: booth_reg = {1'b0, booth_reg[101:1]};
    endcase
end

// Shift and add method
always @(posedge clk) begin
    if(reset) begin
        product_reg <= 0;
        a_reg <= 0;
        b_reg <= 0;
        booth_reg <= 0;
        state_reg <= 2'b00;
        add_reg <= 0;
    end else begin
        case(state_reg)
            2'b00: begin
                a_reg <= a;
                b_reg <= b;
                state_reg <= 2'b01;
            end
            2'b01: begin
                if(booth_reg[0] == 1) begin
                    add_reg <= {add_reg, a_reg};
                end
                state_reg <= 2'b10;
            end
            2'b10: begin
                add_reg <= {add_reg[0], add_reg[199:1]};
                product_reg <= {add_reg, product_reg[199:100]};
                state_reg <= 2'b11;
            end
            2'b11: begin
                product_reg <= {product_reg[0], product_reg[199:1]};
                state_reg <= 2'b00;
            end
        endcase
    end
end

assign product = product_reg;

endmodule

