                     (data0 < data1) ? 1'b0 :
                     (portno0 < portno1) ? 1'b1 : 1'b0;

    assign winner2 = (valid2 && ~valid3) ? 1'b1 :
                     (~valid2 && valid3) ? 1'b0 :
                     (~valid2 && ~valid3) ? 1'b1 : 
                     (data2 > data3) ? 1'b1 :
                     (data2 < data3) ? 1'b0 :
                     (portno2 < portno3) ? 1'b1 : 1'b0;

    assign portno_h = (winner1 == 1'b1) ? portno0 : portno1;
    assign data_h = (winner1 == 1'b1) ? data0 : data1;
    assign valid_h = (winner1 == 1'b1) ? valid0 : valid1;

    assign portno_l = (winner1 == 1'b0) ? portno0 : portno1;
    assign data_l = (winner1 == 1'b0) ? data0 : data1;
    assign valid_l = (winner1 == 1'b0) ? valid0 : valid1;

    assign portno_h = (winner2 == 1'b1 && valid2) ? portno2 : portno_h;
    assign data_h = (winner2 == 1'b1 && valid2) ? data2 : data_h;
    assign valid_h = (winner2 == 1'b1 && valid2) ? valid2 : valid_h;

    assign portno_l = (winner2 == 1'b0 && valid2) ? portno2 : portno_l;
    assign data_l = (winner2 == 1'b0 && valid2) ? data2 : data_l;
    assign valid_l = (winner2 == 1'b0 && valid2) ? valid2 : valid_l;

    assign portno_h = (winner2 == 1'b1 && !valid2 && valid3) ? portno3 : portno_h;
    assign data_h = (winner2 == 1'b1 && !valid2 && valid3) ? data3 : data_h;
    assign valid_h = (winner2 == 1'b1 && !valid2 && valid3) ? valid3 : valid_h;

    assign portno_l = (winner2 == 1'b0 && !valid2 && valid3) ? portno3 : portno_l;
    assign data_l = (winner2 == 1'b0 && !valid2 && valid3) ? data3 : data_l;
    assign valid_l = (winner2 == 1'b0 && !valid2 && valid3) ? valid3 : valid_l;

endmodule

module stack
(
    input clk,
    input [15:0] d,
    input [9:0] a,
    input we,
    output reg [15:0] spo
);

    wire [9:0] ram_a;
    wire [15:0] ram_d;
    wire [15:0] ram_spo;
    wire ram_we;

    assign ram_a = a;
    assign ram_d = d;
    assign ram_we = we;

    ram ram_inst
    (
        .clk(clk),
        .d(ram_d),
        .a(ram_a),
        .we(ram_we),
        .spo(ram_spo)
    );

    reg [9:0] sp;
    reg [15:0] stack [0:1023];

    always @(posedge clk) begin
        if (we) begin
            sp <= sp + 1;
            stack[sp] <= d;
        end else if (sp > 0) begin
            sp <= sp - 1;
        end
    end

    always @(posedge clk) begin
        if (sp > 0) begin
            spo <= stack[sp];
        end else begin
            spo <= 0;
        end
    end

endmodule

module ram
(
    input clk,
    input [15:0] d,
    input [9:0] a,
    input we,
    output reg [15:0] spo
);

