    always @(posedge clk) begin
        if (we) begin
            mem[a] <= d;
        end
        spo <= mem[a];
    end

endmodule

module lcd_driver (
  input [2:0] ctrl,
  input [7:0] data,
  output reg [6:0] lcd_ctrl,
  output reg [7:0] lcd_data
);

  // Define control signal for LCD screen
  parameter INIT = 3'b000;
  parameter CLEAR = 3'b001;
  parameter DISPLAY_CHAR = 3'b010;
  parameter MOVE_CURSOR = 3'b011;

  // Define data signal for LCD screen
  parameter LINE_1 = 3'b000;
  parameter LINE_2 = 3'b001;
  parameter CHAR_1 = 3'b000;
  parameter CHAR_2 = 3'b001;
  parameter CHAR_3 = 3'b010;
  parameter CHAR_4 = 3'b011;
  parameter CHAR_5 = 3'b100;
  parameter CHAR_6 = 3'b101;
  parameter CHAR_7 = 3'b110;
  parameter CHAR_8 = 3'b111;

  // Initialize LCD screen
  always @ (posedge clk) begin
    if (ctrl == INIT) begin
      lcd_ctrl <= 7'b0000000;
      lcd_data <= 8'b00111000;
      #1 lcd_ctrl <= 7'b0000001;
      #1 lcd_ctrl <= 7'b0000000;
      lcd_data <= 8'b00001100;
      #1 lcd_ctrl <= 7'b0000001;
      #1 lcd_ctrl <= 7'b0000000;
      lcd_data <= 8'b00000001;
      #1 lcd_ctrl <= 7'b0000001;
      #1 lcd_ctrl <= 7'b0000000;
      lcd_data <= 8'b00000110;
      #1 lcd_ctrl <= 7'b0000001;
    end
  end

  // Clear LCD screen
  always @ (posedge clk) begin
    if (ctrl == CLEAR) begin
      lcd_ctrl <= 7'b0000000;
      lcd_data <= 8'b00000001;
      #1 lcd_ctrl <= 7'b0000001;
    end
  end

  // Display character on LCD screen
  always @ (posedge clk) begin
    if (ctrl == DISPLAY_CHAR) begin
      lcd_ctrl <= 7'b0000000;
      lcd_data <= data;
      #1 lcd_ctrl <= 7'b0000001;
    end
  end

  // Move cursor to specific position on LCD screen
  always @ (posedge clk) begin
    if (ctrl == MOVE_CURSOR) begin
      lcd_ctrl <= 7'b0000000;
      case (data[7:5])
        LINE_1: lcd_data <= {3'b000, data[4:0]};
        LINE_2: lcd_data <= {3'b010, data[4:0]};
      endcase
      case (data[4:1])
        CHAR_1: lcd_ctrl <= 7'b0000000;
        CHAR_2: lcd_ctrl <= 7'b0000001;
        CHAR_3: lcd_ctrl <= 7'b0000010;
        CHAR_4: lcd_ctrl <= 7'b0000011;
        CHAR_5: lcd_ctrl <= 7'b0000100;
        CHAR_6: lcd_ctrl <= 7'b0000101;
        CHAR_7: lcd_ctrl <= 7'b0000110;
        CHAR_8: lcd_ctrl <= 7'b0000111;
      endcase
    end
  end

endmodule

module booth_multiplier (
  input clk,
  input signed [3:0] a,
  input signed [3:0] b,
  output reg signed [7:0] out,
  output reg done
);

  reg signed [7:0] result;
  reg signed [3:0] ac;
  reg signed [3:0] q;
  reg signed [1:0] q_prev;
  reg signed [3:0] b_neg;

  always @(posedge clk) begin
    // initialize
    if (done == 0) begin
      result <= 0;
      ac <= {a, 4'b0};
      q <= b;
      q_prev <= 2'b00;
      b_neg <= -b;
      done <= 0;
    end
    // Booth's algorithm
    else begin
      case (q[1:0] - q_prev) 
        2'b01: ac <= ac + b_neg;
        2'b10: ac <= ac + b;
      endcase
      q_prev <= q[1:0];
      q[3:1] <= q[2:0];
      q[0] <= ac[0];
      ac[3:1] <= ac[2:0];
      result <= {ac[3], ac[3:0]} + (q[3] ? b_neg : b);
      if (q == 4'b0000) done <= 1;
    end
  end

  assign out = result;

endmodule

