module transition_detector (
    input clk,
    input reset,
    input in,
    output reg [31:0] td_out
);

reg [31:0] prev_in;

always @(posedge clk) begin
    if (reset) begin
        prev_in <= 32'b0;
        td_out <= 32'b0;
    end else begin
        if (in == 1'b0 && prev_in == 1'b1) begin
            td_out <= 32'b1;
        end else begin
            td_out <= td_out;
        end
        prev_in <= in;
    end
end

endmodule

