reg [n-1:0] diff;
reg [n-1:0] A_eq_B;
reg [n-1:0] A_lt_B;
reg [n-1:0] A_gt_B;

assign EQ = &A_eq_B;
assign LT = &A_lt_B;
assign GT = &A_gt_B;

