    wire [7:0] upper_byte;
    wire [7:0] lower_byte;
    byte_splitter bs(
        .in(in),
        .upper_byte(upper_byte),
        .lower_byte(lower_byte)
    );

    // Bitwise AND operation between mux output and upper byte output
    wire [7:0] and_result;
    bitwise_and and_op(
        .a(mux_out[0]),
        .b(upper_byte),
        .out(and_result)
    );

    // Final output as sum of lower byte and AND result
    wire [7:0] sum_result;
    adder add(
        .a(lower_byte),
        .b(and_result),
        .out(sum_result)
    );

    assign out = sum_result;

