module interrupt_controller (
  input [n-1:0] irq,
  input [n-1:0] en,
  output irq
);

parameter n = 4; // number of interrupt request signals

reg [n-1:0] irq_priority; // priority of interrupt requests
reg irq_enable; // whether an interrupt request should be handled or ignored

always @(*) begin
  // set irq_priority based on the priority of the interrupt requests
  if (irq[0] && en[0])
    irq_priority = 0;
  else if (irq[1] && en[1])
    irq_priority = 1;
  else if (irq[2] && en[2])
    irq_priority = 2;
  else if (irq[3] && en[3])
    irq_priority = 3;

  // set irq_enable based on whether an interrupt request should be handled or ignored
  if (irq_priority == 0 && en[0])
    irq_enable = 1;
  else if (irq_priority == 1 && en[1])
    irq_enable = 1;
  else if (irq_priority == 2 && en[2])
    irq_enable = 1;
  else if (irq_priority == 3 && en[3])
    irq_enable = 1;
  else
    irq_enable = 0;
end

assign irq = irq_enable ? irq_priority : 0;

endmodule

module fsm_consecutive_ones (
  input clk,
  input reset,
  input [3:0] data,
  output reg [1:0] count
);

  reg [1:0] state;

  always @(posedge clk or negedge reset) begin
    if (!reset) begin
      state <= 2'b00;
      count <= 2'b00;
    end
    else begin
      case (state)
        2'b00: begin
          if (data == 4'b0001) begin
            state <= 2'b01;
            count <= 2'b01;
          end
          else begin
            state <= 2'b00;
            count <= 2'b00;
          end
        end
        2'b01: begin
          if (data == 4'b0011) begin
            state <= 2'b10;
            count <= 2'b10;
          end
          else if (data == 4'b0001) begin
            state <= 2'b01;
            count <= 2'b01;
          end
          else begin
            state <= 2'b00;
            count <= 2'b00;
          end
        end
        2'b10: begin
          state <= 2'b00;
          count <= 2'b00;
        end
        default: begin
          state <= 2'b00;
          count <= 2'b00;
        end
      endcase
    end
  end

endmodule

module edge_detection (
    input clk,
    input [7:0] in,
    output reg [7:0] out
);

reg [7:0] prev_in;
reg [2:0] count;

always @(posedge clk) begin
    if (in[0] && !prev_in[0]) begin
        count <= 1;
        out <= 8'b00000001;
    end else if (count > 0 && count < 8) begin
        count <= count + 1;
        out <= 8'b00000001;
    end else if (!in[0] && prev_in[0]) begin
        count <= 0;
        out <= 8'b00000000;
    end else begin
        count <= 0;
        out <= 8'b00000000;
    end
    prev_in <= in;
end

endmodule

