module top_module (
    input clk,
    input areset,  // async active-high reset to zero
    input load,
    input ena,
    input [3:0] data,
    input [7:0] in_hi,
    input [7:0] in_lo,
    output reg [15:0] out
);

reg [3:0] shift_reg [0:3];
reg [3:0] shift_reg_next [0:3];
reg [1:0] sel;
wire [7:0] shift_reg_out;
wire [7:0] in1;
wire [7:0] in2;

// Shift register with asynchronous reset, synchronous load, and enable
always @(posedge clk or posedge areset) begin
    if (areset) begin
        shift_reg[0] <= 4'b0;
        shift_reg[1] <= 4'b0;
        shift_reg[2] <= 4'b0;
        shift_reg[3] <= 4'b0;
    end else if (load) begin
        shift_reg[0] <= data;
        shift_reg[1] <= shift_reg[0];
        shift_reg[2] <= shift_reg[1];
        shift_reg[3] <= shift_reg[2];
    end else if (ena) begin
        shift_reg_next[0] = in_lo;
        shift_reg_next[1] = shift_reg[0];
        shift_reg_next[2] = shift_reg[1];
        shift_reg_next[3] = shift_reg[2];
        shift_reg[0] <= shift_reg_next[0];
        shift_reg[1] <= shift_reg_next[1];
        shift_reg[2] <= shift_reg_next[2];
        shift_reg[3] <= shift_reg_next[3];
    end
end

// Mux to select the output of the shift register
always @* begin
    case (sel)
        2'b00: shift_reg_out = shift_reg[0];
        2'b01: shift_reg_out = shift_reg[1];
        2'b10: shift_reg_out = shift_reg[2];
        2'b11: shift_reg_out = shift_reg[3];
    endcase
end

// Combinational circuit to add the two 8-bit inputs
assign in1 = {shift_reg_out, in_hi};
assign in2 = {shift_reg_out, in_lo};
wire [7:0] add_out;
assign add_out = in1 + in2;

// Combinational circuit to perform a bitwise XOR operation on the two 8-bit inputs
wire [7:0] xor_out;
assign xor_out = in1 ^ in2;

// Functional module to combine the two outputs into a 16-bit output
always @* begin
    out = {add_out, xor_out};
end

// Select the output of the shift register based on the enable input
always @* begin
    if (ena) begin
        sel = 2'b11;
    end else begin
        sel = 2'b00;
    end
end

endmodule

module ultrasonido(
    input reset,
    input clk,
    input echo,
    output reg done,
    output reg trigger,
    output reg [15:0] distance
);

    //Parameters
    parameter divH = 100; //1000ns/10ns
    parameter divL = 400; //4000ns/10ns
    parameter maxDist = 400; //Maximum distance in centimeters
    parameter speedOfSound = 340; //Speed of sound in meters per second
    parameter clockPeriod = 10; //Clock period in nanoseconds

    //Counters
    reg [15:0] countTrigger;
    reg [15:0] countEcho;

    //Internal signals
    wire pulse;
    wire [15:0] time;

    //Trigger
    always @(posedge clk) begin
        if (reset) begin
            countTrigger <= 0;
            trigger <= 0;
        end else begin
            if (countTrigger < divH+1) begin
                countTrigger <= countTrigger + 1;
                trigger <= 1;
            end else if (countTrigger < divL+1) begin
                countTrigger <= countTrigger + 1;
                trigger <= 0;
            end else begin
                countTrigger <= 0;
                trigger <= 0;
            end
        end
    end

    //Echo
    always @(posedge clk) begin
        if (echo) begin
            countEcho <= countEcho + 1;
            done <= 0;
        end else if (countEcho != 0) begin
            time <= countEcho * clockPeriod;
            distance <= time * speedOfSound / 20000;
            countEcho <= 0;
            done <= 1;
        end
    end

    //Pulse generator
    assign pulse = (countTrigger >= divH+1) && (countTrigger < divL+1);

    //Distance measurement
    always @(posedge clk) begin
        if (pulse) begin
            countEcho <= 0;
            done <= 0;
        end
    end

    //Distance limit
    always @(posedge clk) begin
        if (distance > maxDist) begin
            distance <= maxDist;
        end
    end

endmodule

