reg signed [15:0] P;

always @(*) begin
    A = (a[7] == 1) ? {8'b11111111, a} : {8'b00000000, a};
    S = (b[7] == 1) ? {8'b11111111, b} : {8'b00000000, b};
    P = A * S;
end

always @(posedge clk) begin
    if (reset) begin
        prod <= 0;
    end else begin
        prod <= P;
    end
end

endmodule

module mux (
    input [15:0] in,
    input [3:0] sel,
    input EN,
    output reg [3:0] out
);

always @ (sel or EN or in) begin
    if (EN == 1'b0) begin
        out <= 4'b0000;
    end else begin
        case (sel)
            4'b0000: out <= in[3:0];
            4'b0001: out <= in[7:4];
            4'b0010: out <= in[11:8];
            4'b0011: out <= in[15:12];
            4'b0100: out <= in[19:16];
            4'b0101: out <= in[23:20];
            4'b0110: out <= in[27:24];
            4'b0111: out <= in[31:28];
            4'b1000: out <= in[35:32];
            4'b1001: out <= in[39:36];
            4'b1010: out <= in[43:40];
            4'b1011: out <= in[47:44];
            4'b1100: out <= in[51:48];
            4'b1101: out <= in[55:52];
            4'b1110: out <= in[59:56];
            4'b1111: out <= in[63:60];
            default: out <= 4'b0000;
        endcase
    end
end

endmodule

module mux_4to1(
    input [3:0] data_in,
    input [1:0] sel,
    output reg data_out
);

    wire [1:0] demux_sel;
    wire a_out, b_out, c_out, d_out;

    // Demultiplex the select lines
    demux_1to2 demux(
        .a(sel[1]),
        .sel(sel[0]),
        .b(demux_sel[0]),
        .c(demux_sel[1])
    );

    // Mux the inputs
    mux_2to1 mux1(
        .a(data_in[0]),
        .b(data_in[1]),
        .sel(demux_sel[1]),
        .y(a_out)
    );

    mux_2to1 mux2(
        .a(data_in[2]),
        .b(data_in[3]),
        .sel(demux_sel[1]),
        .y(b_out)
    );

    mux_2to1 mux3(
        .a(a_out),
        .b(b_out),
        .sel(demux_sel[0]),
        .y(c_out)
    );

    // Output the selected input
    always @ (demux_sel or data_in) begin
        case (demux_sel)
            2'b00: data_out = c_out;
            2'b01: data_out = d_out;
            2'b10: data_out = a_out;
            2'b11: data_out = b_out;
        endcase
    end

endmodule

module switch_module
#(parameter     addr = 4'b0010)
(   
    input       [7:0] port0_i,
    input       [7:0] port1_i,
    input       [7:0] port0_local_i,
    input       [7:0] port1_local_i,
    output      [7:0] port0_o,
    output      [7:0] port1_o,
    output      portl0_ack,
    output      portl1_ack,
    input       clk,
    input       rst
);

    // inputs
    wire [7:0] port0_0, port1_0, port0_local_0, port1_local_0;

    assign port0_0 = (rst) ? 8'd0 : port0_i;
    assign port1_0 = (rst) ? 8'd0 : port1_i;
    assign port0_local_0 = (rst) ? 8'd0 : port0_local_i;
    assign port1_local_0 = (rst) ? 8'd0 : port1_local_i;

    /************* STAGE 1 *************/	

    reg [7:0] port0_0_r, port1_0_r;
    always @(posedge clk) begin
        port0_0_r <= port0_0;
        port1_0_r <= port1_0;
    end

	wire ej_0 = port0_0_r[3:0] == addr && port0_0_r[4];
	wire ej_1 = port1_0_r[3:0] == addr && port1_0_r[4];

    assign port0_o = (ej_0) ? port0_0_r[7:0] : port0_local_0;
    assign port1_o = (ej_1) ? port1_0_r[7:0] : port1_local_0;

    wire valid0 = (ej_0) ? 0 : port0_0_r[4];
    wire valid1 = (ej_1) ? 0 : port1_0_r[4];

    assign portl0_ack = ~valid0 & (ej_0 | (port0_local_0[4] && ~ej_1));
    assign portl1_ack = ~valid1 & (ej_1 | (port1_local_0[4] && ~ej_0));

endmodule

module altpll(
  input [1:0] address,
  input areset,
  input clk,
  input read,
  input reset,
  input write,
  input [31:0] writedata,
  output c0,
  output c1,
  output c2,
  output c3,
  output locked,
  output phasedone,
  output [31:0] readdata
);

  // Internal signals and registers
  reg [4:0] sd1_clk;
  reg sd1_locked;
  reg [31:0] readdata_reg;
  reg [1:0] address_reg;
  reg [1:0] state;
  reg [1:0] next_state;
  reg [31:0] write_reg;
  reg [1:0] write_reg_address;
  reg pfdena_reg;
  reg pfdena_reg_ena;
  reg prev_reset;
  reg w_locked;
  reg w_pfdena;
  reg w_phasedone;
  reg w_pll_areset_in;
  reg w_reset;
  reg w_select_control;
  reg w_select_status;
  reg [31:0] readdata_control;
  reg [31:0] readdata_status;

  // Output assignments
  assign c0 = sd1_clk[0];
  assign c1 = sd1_clk[1];
  assign c2 = sd1_clk[2];
  assign c3 = sd1_clk[3];
  assign locked = sd1_locked;
  assign phasedone = 1'b0;
  assign readdata = (address_reg == 2'b00) ? readdata_control : readdata_status;

  // Instantiate the AltPLL
  niosii_altpll_0_altpll_non2 sd1(
    .areset((w_pll_areset_in | areset)),
    .clk(sd1_clk[0]),
    .inclk({{1{1'b0}}, clk}),
    .locked(sd1_locked)
  );

  // Control state machine
  always @(posedge clk, posedge reset) begin
    if (reset) begin
      state <= 2'b00;
      address_reg <= 2'b00;
      write_reg_address <= 2'b00;
      readdata_control <= 32'b0;
      pfdena_reg <= 1'b1;
    end else begin
      state <= next_state;
      address_reg <= address;
      write_reg_address <= (write & ~address[1] & address[0]) ? writedata[31:30] : write_reg_address;
      pfdena_reg <= (write & ~address[1] & address[0]) ? writedata[1] : pfdena_reg;
    end
  end

  // State machine transitions
  always @(state or address_reg or read or write or pfdena_reg or sd1_locked or phasedone or w_locked or w_pfdena or w_phasedone or w_pll_areset_in or w_reset) begin
    case (state)
      2'b00: begin // Control mode
        next_state = (read) ? 2'b10 : 2'b00;
        readdata_control = {1'b0, pfdena_reg, 1'b0};
        write_reg = writedata;
      end
      2'b01: begin // Status mode
        next_state = (read) ? 2'b11 : 2'b01;
        readdata_status = {1'b0, (address_reg == 2'b00) ? phasedone : w_locked, (address_reg == 2'b00) ? pfdena_reg : locked};
      end
      2'b10: begin // Control read
        next_state = 2'b00;
        readdata_control = {1'b0, pfdena_reg, 1'b0};
      end
      2'b11: begin // Status read
        next_state = 2'b01;
        readdata_status = {1'b0, (address_reg == 2'b00) ? phasedone : w_locked, (address_reg == 2'b00) ? pfdena_reg : locked};
      end
    endcase
  end

  // Phase alignment detection
  niosii_altpll_0_stdsync_sv6 stdsync2(
    .clk(clk),
    .din(sd1_locked),
    .dout(w_locked),
    .reset_n((~reset))
  );

  // PFDENA register
  always @(posedge clk, posedge reset) begin
    if (reset) begin
      pfdena_reg <= 1'b1;
    end else begin
      pfdena_reg <= (pfdena_reg_ena) ? writedata[1] : pfdena_reg;
    end
  end

  // Previous reset detection
  always @(posedge clk, posedge reset) begin
    if (reset) begin
      prev_reset <= 1'b0;
    end else begin
      prev_reset <= w_reset;
    end
  end

  // PFDENA register enable
  assign pfdena_reg_ena = (write & w_select_control);

  // Reset detection for PLL
  assign w_pll_areset_in = prev_reset;

  // Write control register
  always @(posedge clk, posedge reset) begin
    if (reset) begin
      write_reg <= 32'b0;
    end else begin
      write_reg <= (write & ~address[1] & address[0]) ? writedata : write_reg;
    end
  end

  // Select control/status
  assign w_select_control = (~address[1]) & address[0];
  assign w_select_status = (~address[1]) & (~address[0]);

  // Reset detection for control register
  assign w_reset = ((write & w_select_control) & writedata[0]);

  // Phase alignment detection for status register
  assign w_phasedone = 1'b1;

  // Clock output generation
  always @(posedge sd1_clk[0], posedge reset) begin
    if (reset) begin
      sd1_clk <= 5'b0;
    end else begin
      sd1_clk <= {sd1_clk[3:0], ~sd1_clk[4]};
    end
  end

  // Locked detection for status register
  always @(posedge sd1_clk[0], posedge reset) begin
    if (reset) begin
      sd1_locked <= 1'b0;
    end else begin
      sd1_locked <= w_locked;
    end
  end
endmodule

module shift_reg (
    input clk,
    input reset,
    input shift_en,
    input load_en,
    input [3:0] data_in,
    output [3:0] data_out
);

    reg [3:0] reg_out;
    reg [3:0] reg_in;

    always @(posedge clk) begin
        if (reset) begin
            reg_out <= 4'b0000;
        end else if (load_en) begin
            reg_out <= data_in;
        end else if (shift_en) begin
            reg_out <= {reg_out[2:0], reg_in};
        end
    end

    assign data_out = reg_out;

endmodule

module small_fifo(
    input [31:0] data,
    input inclock,
    input outclock,
    input outclocken,
    output [31:0] q,
    input [4:0] rdaddress,
    input [4:0] wraddress,
    input wren
);

    parameter DEPTH = 16;
    parameter WIDTH = 32;

    reg [WIDTH-1:0] mem [DEPTH-1:0];
    reg [4:0] read_ptr, write_ptr;
    reg empty, full;

    always @(posedge inclock) begin
        if (wren && !full) begin
            mem[write_ptr] <= data;
            write_ptr <= (write_ptr == DEPTH-1) ? 0 : write_ptr + 1;
        end
        full <= (write_ptr == read_ptr && wren);
        empty <= (write_ptr == read_ptr && !wren);
    end

    always @(posedge outclock) begin
        if (outclocken && !empty) begin
            q <= mem[read_ptr];
            read_ptr <= (read_ptr == DEPTH-1) ? 0 : read_ptr + 1;
        end
        full <= (write_ptr == read_ptr && wren);
        empty <= (write_ptr == read_ptr && !wren);
    end

endmodule

