module ram_sync_4r1w (
    input clk,
    input [ADDR_WIDTH-1:0] raddr1,
    input [ADDR_WIDTH-1:0] raddr2,
    input [ADDR_WIDTH-1:0] raddr3,
    input [ADDR_WIDTH-1:0] raddr4,
    output reg [DATA_WIDTH-1:0] rdata1,
    output reg [DATA_WIDTH-1:0] rdata2,
    output reg [DATA_WIDTH-1:0] rdata3,
    output reg [DATA_WIDTH-1:0] rdata4,
    input [ADDR_WIDTH-1:0] waddr,
    input [DATA_WIDTH-1:0] wdata,
    input we
);

    parameter ADDR_WIDTH = 5;
    parameter DATA_WIDTH = 16;
    parameter DATA_DEPTH = 32;

    wire [ADDR_WIDTH-1:0] addr_sel1;
    wire [ADDR_WIDTH-1:0] addr_sel2;
    wire [ADDR_WIDTH-1:0] addr_sel3;
    wire [ADDR_WIDTH-1:0] addr_sel4;
    wire [DATA_WIDTH-1:0] data1;
    wire [DATA_WIDTH-1:0] data2;
    wire [DATA_WIDTH-1:0] data3;
    wire [DATA_WIDTH-1:0] data4;

    ram_sync_2r1w #(ADDR_WIDTH, DATA_WIDTH, DATA_DEPTH) mem1 (
        .clk(clk),
        .raddr1(raddr1),
        .raddr2(raddr2),
        .rdata1(data1),
        .rdata2(data2),
        .waddr(waddr),
        .wdata(wdata),
        .we(we)
    );

    ram_sync_2r1w #(ADDR_WIDTH, DATA_WIDTH, DATA_DEPTH) mem2 (
        .clk(clk),
        .raddr1(raddr3),
        .raddr2(raddr4),
        .rdata1(data3),
        .rdata2(data4),
        .waddr(waddr),
        .wdata(wdata),
        .we(we)
    );

    assign addr_sel1 = raddr1;
    assign addr_sel2 = raddr2;
    assign addr_sel3 = raddr3;
    assign addr_sel4 = raddr4;

    always @(posedge clk) begin
        if (we) begin
            mem1.we <= 1;
            mem1.waddr <= waddr;
            mem1.wdata <= wdata;
            mem2.we <= 1;
            mem2.waddr <= waddr;
            mem2.wdata <= wdata;
        end else begin
            mem1.we <= 0;
            mem2.we <= 0;
        end

        rdata1 <= data1;
        rdata2 <= data2;
        rdata3 <= data3;
        rdata4 <= data4;
    end

endmodule

module ram_sync_2r1w (
    input clk,
    input [ADDR_WIDTH-1:0] raddr1,
    input [ADDR_WIDTH-1:0] raddr2,
