module FullAdder(A, B, C_in, S, C_out);
    input A, B, C_in;
    output S, C_out;

    assign S = A ^ B ^ C_in;
    assign C_out = (A & B) | (C_in & (A ^ B));
endmodule

module Adder16(A, B, F);
