    FullAdder FA0(A[0], B[0], 1'b0, F[0], C[0]);
    FullAdder FA1(A[1], B[1], C[0], F[1], C[1]);
    FullAdder FA2(A[2], B[2], C[1], F[2], C[2]);
    FullAdder FA3(A[3], B[3], C[2], F[3], C[3]);
    FullAdder FA4(A[4], B[4], C[3], F[4], C[4]);
    FullAdder FA5(A[5], B[5], C[4], F[5], C[5]);
    FullAdder FA6(A[6], B[6], C[5], F[6], C[6]);
