    FullAdder FA8(A[8], B[8], C[7], F[8], C[8]);
    FullAdder FA9(A[9], B[9], C[8], F[9], C[9]);
    FullAdder FA10(A[10], B[10], C[9], F[10], C[10]);
    FullAdder FA11(A[11], B[11], C[10], F[11], C[11]);
