module rx_module(
	input phy_rx_clk,
	input [1:0] rx_ready,
	output reg [1:0] rx_done,
	output reg [10:0] rx_count_0,
	output reg [10:0] rx_count_1,
	output reg [7:0] rxb0_dat,
	output reg [10:0] rxb0_adr,
	output reg rxb0_we,
	output reg [7:0] rxb1_dat,
	output reg [10:0] rxb1_adr,
	output reg rxb1_we,
	input phy_dv,
	input [3:0] phy_rx_data,
	input phy_rx_er
);

reg [1:0] available_slots;
always @(posedge phy_rx_clk)
	available_slots <= (available_slots | rx_ready) & ~rx_done;
initial available_slots <= 2'd0;

reg [1:0] used_slot;
reg used_slot_update;
always @(posedge phy_rx_clk) begin
	if(used_slot_update) begin
		used_slot[0] <= available_slots[0];
		used_slot[1] <= available_slots[1] & ~available_slots[0];
	end
end

reg rx_done_ctl;
assign rx_done = {2{rx_done_ctl}} & used_slot;

reg rx_count_reset_ctl;
reg rx_count_inc_ctl;
wire [1:0] rx_count_reset = {2{rx_count_reset_ctl}} & used_slot;
wire [1:0] rx_count_inc = {2{rx_count_inc_ctl}} & used_slot;
always @(posedge phy_rx_clk) begin
	if(rx_count_reset[0])
		rx_count_0 <= 11'd0;
	else if(rx_count_inc[0])
		rx_count_0 <= rx_count_0 + 11'd1;
	if(rx_count_reset[1])
		rx_count_1 <= 11'd0;
	else if(rx_count_inc[1])
		rx_count_1 <= rx_count_1 + 11'd1;
end

assign rxb0_adr = rx_count_0;
assign rxb1_adr = rx_count_1;
reg rxb_we_ctl;
assign rxb0_we = rxb_we_ctl & used_slot[0];
assign rxb1_we = rxb_we_ctl & used_slot[1];

reg [3:0] lo;
reg [3:0] hi;
reg [1:0] load_nibble;
always @(posedge phy_rx_clk) begin
	if(load_nibble[0])
		lo <= phy_rx_data;
	if(load_nibble[1])
		hi <= phy_rx_data;
end
assign rxb0_dat = {hi, lo};
assign rxb1_dat = {hi, lo};

reg [1:0] state;
reg [1:0] next_state;

parameter IDLE		= 2'd0;
parameter LOAD_LO	= 2'd1;
parameter LOAD_HI	= 2'd2;
parameter TERMINATE	= 2'd3;

initial state <= IDLE;
always @(posedge phy_rx_clk)
	state <= next_state;

always @(*) begin
	used_slot_update = 1'b0;
	rx_done_ctl = 1'b0;
	rx_count_reset_ctl = 1'b0;
	rx_count_inc_ctl = 1'b0;
	rxb_we_ctl = 1'b0;
	load_nibble = 2'b00;

	next_state = state;
	case(state)
		IDLE: begin
			used_slot_update = 1'b1;
			if(phy_dv) begin
				rx_count_reset_ctl = 1'b1;
				used_slot_update = 1'b0;
				load_nibble = 2'b01;
				next_state = LOAD_HI;
			end
		end
		LOAD_LO: begin
			rxb_we_ctl = 1'b1;
			rx_count_inc_ctl = 1'b1;
			if(phy_dv) begin
				load_nibble = 2'b01;
				next_state = LOAD_HI;
			end else begin
				rx_done_ctl = 1'b1;
				next_state = TERMINATE;
			end
		end
		LOAD_HI: begin
			if(phy_dv) begin
				load_nibble = 2'b10;
				next_state = LOAD_LO;
			end else begin
				rx_done_ctl = 1'b1;
				next_state = TERMINATE;
			end
		end
		TERMINATE: begin
			used_slot_update = 1'b1;
			next_state = IDLE;
		end
	endcase
end

endmodule

module onlyonecycle (trigger, output_xhdl0, globalreset, clk, enable);

    input trigger; 
    output output_xhdl0; 
    input globalreset; 
    input clk; 
    input enable; 

    reg[1:0] state; 
    reg[1:0] next_state; 
    reg count; 
    reg temp_count; 

    always @(posedge clk or posedge globalreset)
    begin
       if (globalreset == 1'b1)
       begin
          state <= 0 ; 
          count <= 0 ; 

       end
       else
       begin
          state <= next_state ; 
		  count <= temp_count;
       end 
    end 

    always @(state or trigger or count or enable)
    begin
       case (state)
          0 :
                   begin
       				  output_xhdl0 = 1'b0 ; 
                      if (trigger == 1'b1 && enable == 1'b1)
                      begin
                         next_state = 1 ; 
                      end
                      else
                      begin
                         next_state = 0 ; 
                      end 
                         temp_count = 1 - 1 ; 
                   end
          1 :
                   begin
                      output_xhdl0 = enable; 
                      if (count == 0)
                      begin
                         next_state = 2 ; 
                      end
                      else

                      begin

                         next_state = 1 ; 
                      end 
                         temp_count = count - 1 ; 
                   end
          2 :
                   begin
       				  output_xhdl0 = 1'b0 ; 
                      if (trigger == 1'b0)
                      begin
                         next_state = 0 ; 
                      end
                      else
                      begin
                         next_state = 2 ; 

                      end 
                   end
       endcase 
    end 
 endmodule

module traffic_light_controller (
  input clk, // clock signal
  input rst, // reset signal
  input [n-1:0] sensor, // sensor signals
  output reg red, yellow, green // traffic light signals
);

parameter n = 4; // number of sensor signals

// Define the states
localparam [2:0] STATE_1 = 3'b001; // Red light on
localparam [2:0] STATE_2 = 3'b010; // Green light on if sensor1 is detected, otherwise red light remains on
localparam [2:0] STATE_3 = 3'b011; // Yellow light on for 3 seconds, then transition to State 4
localparam [2:0] STATE_4 = 3'b100; // Green light on for a fixed amount of time (e.g., 20 seconds), then transition to State 5
localparam [2:0] STATE_5 = 3'b101; // Yellow light on for 3 seconds, then transition to State 1

// Define the state register and initialize to STATE_1
reg [2:0] state_reg = STATE_1;

// Define the timer counter and initialize to 0
reg [4:0] timer_counter = 0;

// Define the output signals
assign red = (state_reg == STATE_1) || (state_reg == STATE_2) || (state_reg == STATE_5);
assign green = (state_reg == STATE_2) || (state_reg == STATE_4);
assign yellow = (state_reg == STATE_3) || (state_reg == STATE_5);

// Define the state machine
always @(posedge clk) begin
  if (rst) begin
    state_reg <= STATE_1;
    timer_counter <= 0;
  end else begin
    case (state_reg)
      STATE_1: begin
        timer_counter <= 0;
        if (sensor[0]) begin
          state_reg <= STATE_2;
        end
      end
      STATE_2: begin
        timer_counter <= 0;
        if (!sensor[0]) begin
          state_reg <= STATE_1;
        end else if (timer_counter >= 20) begin
          state_reg <= STATE_4;
        end
      end
      STATE_3: begin
        if (timer_counter >= 3) begin
          state_reg <= STATE_4;
          timer_counter <= 0;
        end
      end
      STATE_4: begin
        timer_counter <= timer_counter + 1;
        if (timer_counter >= 20) begin
          state_reg <= STATE_5;
          timer_counter <= 0;
        end
      end
      STATE_5: begin
        if (timer_counter >= 3) begin
          state_reg <= STATE_1;
          timer_counter <= 0;
        end
      end
    endcase
  end
end

endmodule

module simple_calculator(
    input clk, rst,
    input [2:0] op,
    input [7:0] num1, num2,
    output reg [7:0] result,
    output reg overflow, zero, valid
);

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            result <= 8'b0;
            overflow <= 1'b0;
            zero <= 1'b0;
            valid <= 1'b1;
        end else begin
            case (op)
                3'b000: begin // Addition
                    result <= num1 + num2;
                    overflow <= (result > 8'b11111111) ? 1'b1 : 1'b0;
                    zero <= (result == 8'b0) ? 1'b1 : 1'b0;
                    valid <= 1'b1;
                end
                3'b001: begin // Subtraction
                    result <= num1 - num2;
                    overflow <= (result < 8'b00000000) ? 1'b1 : 1'b0;
                    zero <= (result == 8'b0) ? 1'b1 : 1'b0;
                    valid <= 1'b1;
                end
                3'b010: begin // Multiplication
                    result <= num1 * num2;
                    overflow <= (result > 8'b11111111) ? 1'b1 : 1'b0;
                    zero <= (result == 8'b0) ? 1'b1 : 1'b0;
                    valid <= 1'b1;
                end
                3'b011: begin // Division
                    if (num2 == 8'b0) begin
                        result <= 8'b0;
                        overflow <= 1'b0;
                        zero <= 1'b0;
                        valid <= 1'b0;
                    end else begin
                        result <= num1 / num2;
                        overflow <= (result > 8'b11111111) ? 1'b1 : 1'b0;
                        zero <= (result == 8'b0) ? 1'b1 : 1'b0;
                        valid <= 1'b1;
                    end
                end
                3'b100: begin // Modulus
                    if (num2 == 8'b0) begin
                        result <= 8'b0;
                        overflow <= 1'b0;
                        zero <= 1'b0;
                        valid <= 1'b0;
                    end else begin
                        result <= num1 % num2;
                        overflow <= (result > 8'b11111111) ? 1'b1 : 1'b0;
                        zero <= (result == 8'b0) ? 1'b1 : 1'b0;
                        valid <= 1'b1;
                    end
                end
                default: begin // Invalid operation
                    result <= 8'b0;
                    overflow <= 1'b0;
                    zero <= 1'b0;
                    valid <= 1'b0;
                end
            endcase
        end
    end

endmodule

