module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

    // Define internal signals
    wire [3:0] sum;
    wire [3:0] carry;

    // Generate the sum and carry signals
    full_adder fa0(A[0], B[0], Cin, sum[0], carry[0]);
    full_adder fa1(A[1], B[1], carry[0], sum[1], carry[1]);
    full_adder fa2(A[2], B[2], carry[1], sum[2], carry[2]);
    full_adder fa3(A[3], B[3], carry[2], sum[3], Cout);

    // Assign the sum signal to the output port
    assign S = sum;

endmodule

module full_adder(
    input A,
    input B,
    input Cin,
    output S,
    output Cout
);

    // Define internal signals
    wire sum;
    wire Cout1;
    wire Cout2;

    // Generate the sum and carry signals
    xor(sum, A, B);
    xor(S, sum, Cin);
    and(Cout1, A, B);
    and(Cout2, sum, Cin);
    or(Cout, Cout1, Cout2);

endmodule

module up_counter (
    input clk,
    input reset,   // Synchronous active-high reset
    input ena,     // Synchronous active-high enable
    output reg [15:0] q);

    // Define states
    parameter IDLE = 2'b00;
    parameter COUNT = 2'b01;
    parameter COUNT_BY_TWO = 2'b10;

    // Define state register and next state logic
    reg [1:0] state, next_state;
    always @ (posedge clk) begin
        if (reset) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Define output register and output logic
    reg [15:0] count_reg;
    always @ (posedge clk) begin
        if (reset) begin
            count_reg <= 16'd0;
        end else if (ena) begin
            case (state)
                IDLE: begin
                    count_reg <= 16'd0;
                end
                COUNT: begin
                    count_reg <= count_reg + 1;
                end
                COUNT_BY_TWO: begin
                    count_reg <= count_reg + 2;
                end
            endcase
        end
    end
    assign q = count_reg;

    // Define next state logic
    always @ (state, ena) begin
        case (state)
            IDLE: begin
                if (ena) begin
                    next_state = COUNT;
                end else begin
                    next_state = IDLE;
                end
            end
            COUNT: begin
                if (ena) begin
                    next_state = COUNT_BY_TWO;
                end else begin
                    next_state = IDLE;
                end
            end
            COUNT_BY_TWO: begin
                if (ena) begin
                    next_state = COUNT;
                end else begin
                    next_state = IDLE;
                end
            end
        endcase
    end

endmodule

module top_module (
    input clk,
