module top_module(
    input clk,
    input reset,
    input [2:0] a,
    input [2:0] b,
    input sel_mux,
    input sel_or,
    input sel_out,
    output reg [2:0] sum,
    output reg carry_out
);

    wire [2:0] mux_out;
    wire [2:0] or_out;

    mux_2to1 mux_inst(
        .sel(sel_mux),
        .in0(a),
        .in1(b),
        .out(mux_out)
    );

    binary_or or_inst(
        .a(a),
        .b(b),
        .out(or_out)
    );

    always @(posedge clk) begin
        if(reset) begin
            sum <= 3'b0;
            carry_out <= 1'b0;
        end else begin
            if(sel_out == 1'b0) begin
                sum <= mux_out + or_out;
            end else begin
                sum <= or_out;
            end

            carry_out <= (mux_out[2] & or_out[2]) | (mux_out[1] & or_out[2]) | (mux_out[2] & or_out[1]);
        end
    end

endmodule

