module motor_control(
    input clk,
    input [7:0] voltage_input,
    input enable,
    output reg pwm
);

reg [7:0] duty_cycle;
reg [7:0] counter;

always @(posedge clk) begin
    if (enable) begin
        if (voltage_input > 255) begin
            // Safety feature - turn off motor if voltage exceeds 5V
            pwm <= 0;
        end else begin
            // Calculate duty cycle based on voltage input
            duty_cycle <= (voltage_input * 100) / 255;
            // Increment counter
            counter <= counter + 1;
            // Generate PWM signal
            if (counter < duty_cycle) begin
                pwm <= 1;
            end else begin
                pwm <= 0;
            end
            // Reset counter if it reaches 255 (10kHz frequency)
            if (counter == 255) begin
                counter <= 0;
            end
        end
    end else begin
        // Turn off motor if enable signal is low
        pwm <= 0;
        duty_cycle <= 0;
        counter <= 0;
    end
end

endmodule

module shift_module(
    input aclr,
    input clk_en,
    input clock,
    input [54:0] data,
    input [5:0] distance,
    output reg [54:0] result
);

reg [54:0] pipe_wl1c;
reg sel_pipel3d1c, sel_pipel4d1c, sel_pipel5d1c;
wire direction_w;
wire [31:0] pad_w;
wire [384:0] sbit_w;
wire [5:0] sel_w;

initial pipe_wl1c = 0;
initial sel_pipel3d1c = 0;
initial sel_pipel4d1c = 0;
initial sel_pipel5d1c = 0;

always @(posedge clock or posedge aclr) begin
    if (aclr == 1'b1) begin
        pipe_wl1c <= 55'b0;
        sel_pipel3d1c <= 1'b0;
        sel_pipel4d1c <= 1'b0;
        sel_pipel5d1c <= 1'b0;
