module dffsr (
    input clk,
    input d,
    input set,
    input reset,
    input preset,
    output reg q,
    output reg q_bar
    );

    always @(posedge clk) begin
        if (reset) begin
            q <= 1'b0;
            q_bar <= 1'b1;
        end else if (set) begin
            q <= 1'b1;
            q_bar <= 1'b0;
        end else if (preset) begin
            q <= 1'b1;
            q_bar <= 1'b0;
        end else begin
            q <= d;
            q_bar <= ~d;
        end
    end

endmodule

module wb_slave (
    input sys_rst,

    input             wbs_clk_i,	    // Wishbone slave interface
    input      [19:1] wbs_adr_i,
    input      [15:0] wbs_dat_i,
    output reg [15:0] wbs_dat_o,
    input      [ 1:0] wbs_sel_i,
    input             wbs_tga_i,
    input             wbs_stb_i,
    input             wbs_cyc_i,
    input             wbs_we_i,
    output            wbs_ack_o
  );

  reg [15:0] mem [0:1023];
  reg [15:0] data_out;

  assign wbs_ack_o = wbs_stb_i & wbs_cyc_i;

  always @(posedge wbs_clk_i) begin
    if (sys_rst) begin
      wbs_dat_o <= 16'b0;
    end else if (wbs_stb_i & wbs_cyc_i) begin
      if (wbs_we_i) begin
        mem[wbs_adr_i[19:2]][wbs_adr_i[1:0]] <= wbs_dat_i;
      end else begin
        data_out <= mem[wbs_adr_i[19:2]][wbs_adr_i[1:0]];
      end
    end
  end

  always @(posedge wbs_clk_i) begin
    if (sys_rst) begin
      wbs_dat_o <= 16'b0;
    end else if (wbs_stb_i & wbs_cyc_i & ~wbs_we_i) begin
      wbs_dat_o <= data_out;
    end
  end
endmodule

module wb_master (
    input sys_rst,

    input             wbs_clk_i,	    // Wishbone slave interface
    input      [19:1] wbs_adr_i,
    input      [15:0] wbs_dat_i,
    output reg [15:0] wbs_dat_o,
    input      [ 1:0] wbs_sel_i,
    input             wbs_tga_i,
    input             wbs_stb_i,
    input             wbs_cyc_i,
    input             wbs_we_i,
    output            wbs_ack_o,

    input             wbm_clk_i,	    // Wishbone master interface
    output reg [19:1] wbm_adr_o,
    output reg [15:0] wbm_dat_o,
    input      [15:0] wbm_dat_i,
    output reg [ 1:0] wbm_sel_o,
    output reg        wbm_tga_o,
    output            wbm_stb_o,
    output            wbm_cyc_o,
    output reg        wbm_we_o,
    input             wbm_ack_i
  );

  wire       wbs_stb;
  wire       init_tr;
  reg        wbm_stb;
  reg  [2:0] sync_stb;
  reg  [2:0] sync_ack;
  reg        ft_stb;
  reg        ft_ack;
  reg        stb_r;
  reg        ack_r;

  reg [19:1] wbm_adr_o_r;
  reg [15:0] wbm_dat_o_r;
  reg [ 1:0] wbm_sel_o_r;
  reg        wbs_tga_i_r;
  reg        wbm_tga_o_r;
  reg        wbs_we_i_r;
  reg        wbm_we_o_r;
  reg [15:0] wbs_dat_o_r;
  reg [15:0] wbm_dat_i_r;

  assign wbs_stb = wbs_stb_i & wbs_cyc_i;

  // recreate the flag from the level change
  assign wbs_ack_o = (sync_ack[2] ^ sync_ack[1]);
  assign wbm_stb_o = wbm_stb;
  assign wbm_cyc_o = wbm_stb;

  // new wishbone transaction is issued:
  //   -  by changing stb from 0 to 1
  //   - by continue asserting stb after ack is received
  assign init_tr = ~stb_r & wbs_stb | ack_r & ~wbs_ack_o & wbs_stb;

  always @(posedge wbm_clk_i)
    wbm_stb <= sys_rst ? 1'b0 : (wbm_stb ? ~wbm_ack_i : sync_stb[2] ^ sync_stb[1]);

  // old stb and ack state
  always @(posedge wbs_clk_i) stb_r <= wbs_stb;
  always @(posedge wbs_clk_i) ack_r <= wbs_ack_o;

  always @(posedge wbs_clk_i)
    ft_stb <= sys_rst ? 1'b0 : (init_tr ? ~ft_stb : ft_stb);

  // synchronize the last level change
  always @(posedge wbm_clk_i)
    sync_stb <= sys_rst ? 3'h0 : {sync_stb[1:0], ft_stb};

  // this changes level when a flag is seen
  always @(posedge wbm_clk_i)
    ft_ack <= sys_rst ? 1'b0 : (wbm_ack_i ? ~ft_ack : ft_ack);

  // which can then be synched to wbs_clk_i
  always @(posedge wbs_clk_i)
    sync_ack <= sys_rst ? 3'h0 : {sync_ack[1:0], ft_ack};

  // rest of the wishbone signals
  always @(posedge wbm_clk_i)
    {wbm_adr_o, wbm_adr_o_r} <= {wbm_adr_o_r, wbs_adr_i};

  always @(posedge wbm_clk_i)
    {wbm_dat_o, wbm_dat_o_r} <= {wbm_dat_o_r, wbs_dat_i};

  always @(posedge wbm_clk_i)
    {wbm_sel_o, wbm_sel_o_r} <= {wbm_sel_o_r, wbs_sel_i};

  always @(posedge wbs_clk_i) wbs_we_i_r <= wbs_we_i;
  always @(posedge wbm_clk_i)
    {wbm_we_o, wbm_we_o_r} <= {wbm_we_o_r, wbs_we_i_r};

  always @(posedge wbs_clk_i) wbs_tga_i_r <= wbs_tga_i;
  always @(posedge wbm_clk_i)
    {wbm_tga_o, wbm_tga_o_r} <= {wbm_tga_o_r, wbs_tga_i_r};

  // Register input coming from the slave as that can change
  // after the ack is received
  always @(posedge wbm_clk_i)
    wbm_dat_i_r <= wbm_ack_i ? wbm_dat_i : wbm_dat_i_r;

  always @(posedge wbs_clk_i)
    {wbs_dat_o, wbs_dat_o_r} <= {wbs_dat_o_r, wbm_dat_i_r};

endmodule

module data_comp_decomp (
  input [data_width-1:0] data_in,
  input start,
  input mode,
  output [data_width-1:0] data_out,
  output done
);

parameter data_width = 8; // width of the input and output data

reg [data_width-1:0] compressed_data;
reg [data_width-1:0] decompressed_data;
reg [data_width-1:0] current_data;
reg [data_width-1:0] next_data;
reg [data_width-1:0] temp_data;
reg [data_width-1:0] temp_compressed_data;
reg [data_width-1:0] temp_decompressed_data;
reg [data_width-1:0] compressed_index;
reg [data_width-1:0] decompressed_index;
reg [data_width-1:0] compressed_size;
reg [data_width-1:0] decompressed_size;
reg [data_width-1:0] compression_ratio;
reg [data_width-1:0] compression_error;
reg [data_width-1:0] decompression_error;
reg [data_width-1:0] compression_done;
reg [data_width-1:0] decompression_done;
reg [data_width-1:0] compression_started;
reg [data_width-1:0] decompression_started;

always @(*) begin
  if (start) begin
    if (mode) begin // compression mode
      current_data = data_in;
      compressed_index = 0;
      compressed_size = 0;
      compression_ratio = 0;
      compression_error = 0;
      compression_done = 0;
      compression_started = 1;
    end else begin // decompression mode
      compressed_data = data_in;
      decompressed_index = 0;
      decompressed_size = 0;
      decompression_error = 0;
      decompression_done = 0;
      decompression_started = 1;
    end
  end else begin
    if (mode) begin // compression mode
      if (compression_started) begin
        next_data = data_in;
        if (current_data != next_data) begin
          temp_compressed_data = {temp_compressed_data, current_data};
          compressed_index = compressed_index + data_width;
          compressed_size = compressed_size + 1;
          compression_ratio = compressed_size * 100 / (compressed_size + compression_error);
          current_data = next_data;
        end
        if (compressed_index >= data_width) begin
          compressed_data = {compressed_data, temp_compressed_data};
          temp_compressed_data = 0;
          compressed_index = 0;
        end
        if (compression_ratio < 50) begin
          compression_error = compression_error + 1;
        end
        if (current_data == 0) begin
          temp_compressed_data = {temp_compressed_data, current_data};
          compressed_index = compressed_index + data_width;
          compressed_size = compressed_size + 1;
          compression_ratio = compressed_size * 100 / (compressed_size + compression_error);
          compression_done = 1;
        end
      end
    end else begin // decompression mode
      if (decompression_started) begin
        temp_data = compressed_data[decompressed_index:data_width-1];
        if (temp_data == 0) begin
          decompressed_data = {decompressed_data, temp_data};
          decompressed_index = decompressed_index + data_width;
          decompressed_size = decompressed_size + 1;
          decompression_done = 1;
        end else begin
          decompressed_data = {decompressed_data, temp_data};
          decompressed_index = decompressed_index + data_width;
          decompressed_size = decompressed_size + 1;
        end
      end
    end
  end
end

assign data_out = (mode) ? compressed_data : decompressed_data;
assign done = (mode) ? compression_done : decompression_done;

endmodule

module top_module (
    input [7:0] in0,
    input [7:0] in1,
    input [7:0] in2,
    input [7:0] in3,
    input [1:0] sel,
    output [15:0] out_not,
    output [7:0] out_and_bitwise,
    output [7:0] out_xor_bitwise,
    output [7:0] out_nor_bitwise
);

    // 4-to-1 Multiplexer
    wire [7:0] mux_out;
    assign mux_out = (sel == 2'b00) ? in0 :
                     (sel == 2'b01) ? in1 :
                     (sel == 2'b10) ? in2 :
                                      in3;

    // Bitwise Operations
    wire [7:0] and_out;
    wire [7:0] xor_out;
    wire [7:0] nor_out;
    assign and_out = in0 & in1;
    assign xor_out = in2 ^ in3;
    assign nor_out = ~(in0 | in1);

    // NOT Inverse
    wire [7:0] inv1;
    wire [7:0] inv2;
    assign inv1 = ~mux_out;
    assign inv2 = ~{in3, in2};

    // Output
    assign out_not = {inv2, inv1};
    assign out_and_bitwise = and_out;
    assign out_xor_bitwise = xor_out;
    assign out_nor_bitwise = nor_out;

endmodule

