module mux4ds (dout, in0, in1, in2, in3, sel0, sel1, sel2, sel3) ;
// synopsys template

parameter SIZE = 1;

output 	[SIZE-1:0] 	dout;
input	[SIZE-1:0]	in0;
input	[SIZE-1:0]	in1;
input	[SIZE-1:0]	in2;
input	[SIZE-1:0]	in3;
input			sel0;
input			sel1;
input			sel2;
input			sel3;

// reg declaration does not imply state being maintained
// across cycles. Used to construct case statement and
// always updated by inputs every cycle.
reg	[SIZE-1:0]	dout ;

wire [3:0] sel = {sel3,sel2,sel1,sel0}; // 0in one_hot

// priority encoding takes care of mutex'ing selects.
always @ (sel0 or sel1 or sel2 or sel3 or in0 or in1 or in2 or in3)

	case ({sel3,sel2,sel1,sel0}) 
		4'b0001 : dout = in0 ;
		4'b0010 : dout = in1 ;
		4'b0100 : dout = in2 ;
		4'b1000 : dout = in3 ;
		4'b0000, 4'b0011, 4'b0101, 4'b0110, 4'b0111, 4'b1001, 4'b1010, 4'b1011, 4'b1100, 4'b1101, 4'b1110, 4'b1111 : dout = {SIZE{1'bx}} ;
			// two state vs four state modelling will be added.
	endcase

endmodule

module state_machine(
  input SEN, SADDR, DRDY, DO, CLK,
  input [15:0] ROM,
  output reg DI, DWE, DEN, RST_MMCM,
  output reg [7:0] next_rom_addr,
  output reg [4:0] next_state,
  output reg next_rst_mmcm, next_srdy,
  output reg [7:0] next_daddr, next_state_count
);

  // Constants
  localparam STATE_COUNT_CONST = 8'h7F;

  // Registers
  reg [7:0] rom_addr;
  reg [15:0] rom_do;
  reg [4:0] state;
  reg rst_mmcm, srdy;
  reg [7:0] daddr;
  reg [7:0] rom_addr_next;
  reg [4:0] state_next;
  reg rst_mmcm_next, srdy_next;
  reg [7:0] daddr_next;
  reg [7:0] state_count;
  reg [7:0] state_count_next;
  reg [15:0] di;
  reg dwe, den;

  // Assign next state values
  always @(*) begin
    next_rom_addr     = rom_addr_next;
    next_state        = state_next;
    next_rst_mmcm     = rst_mmcm_next;
    next_srdy         = srdy_next;
    next_daddr        = daddr_next;
    next_state_count  = state_count_next;
  end

  // State machine
  always @(posedge CLK) begin
    rom_addr     <= rom_addr_next;
    state        <= state_next;
    rst_mmcm     <= rst_mmcm_next;
    srdy         <= srdy_next;
    daddr        <= daddr_next;
    state_count  <= state_count_next;
    di           <= rom_do[15:0] | di;
    dwe          <= 1'b0;
    den          <= 1'b0;

    case(state)
      RESTART: begin
        rom_addr_next     = 8'h00;
        state_next        = WAIT_LOCK;
        rst_mmcm_next     = 1'b1;
        srdy_next         = 1'b1;
        daddr_next        = 8'h00;
        state_count_next  = STATE_COUNT_CONST;
        di                = 16'h0000;
      end

      WAIT_LOCK: begin
        if (LOCKED) begin
          state_next = WAIT_SEN;
        end else begin
          state_next = WAIT_LOCK;
        end
      end

      WAIT_SEN: begin
        case(SADDR)
          2'b00: rom_addr_next = 8'h00;
          2'b01: rom_addr_next = STATE_COUNT_CONST;
          2'b10: rom_addr_next = 2*STATE_COUNT_CONST;
          2'b11: rom_addr_next = 3*STATE_COUNT_CONST;
        endcase

        if (SEN) begin
          state_next = ADDRESS;
        end else begin
          state_next = WAIT_SEN;
        end
      end

      ADDRESS: begin
        rst_mmcm_next     = 1'b1;
        den               = 1'b1;
        daddr_next        = rom_do[38:32];
        state_next        = WAIT_A_DRDY;
      end

      WAIT_A_DRDY: begin
        if (DRDY) begin
          state_next = BITMASK;
        end else begin
          state_next = WAIT_A_DRDY;
        end
      end

      BITMASK: begin
        di           = rom_do[31:16] & DO;
        state_next   = BITSET;
      end

      BITSET: begin
        dwe          = 1'b1;
        den          = 1'b1;
        rom_addr_next = rom_addr + 1'b1;
        state_count_next = state_count - 1'b1;
        if (state_count_next == 8'h00) begin
          state_next = WAIT_LOCK;
        end else begin
          state_next = ADDRESS;
        end
      end

      default: begin
        state_next = RESTART;
      end
    endcase
  end

  // ROM
  always @(rom_addr) begin
    rom_do = ROM[rom_addr];
  end

endmodule

