        button_temp <= button;
        SW_temp <= SW;
        if (button_temp != button || SW_temp != SW) begin
            counter <= 0;
            pulse <= 0;
        end else if (counter < 100000) begin
            counter <= counter + 1;
        end else begin
            button_out <= button;
            if (button_temp == 0 && pulse == 1) begin
                button_pulse <= button_temp;
                pulse <= 0;
            end else if (button_temp == 1) begin
                pulse <= 1;
            end
            SW_OK <= SW_temp;
        end
    end

endmodule

