        .Cin(carry_out),
        .SUM(add_out[1]),
        .Cout(CARRY)
    );

    // Inverter for subtraction operation
    assign sub_out[0] = B[0] ^ SUB;
    assign sub_out[1] = B[1] ^ SUB;

    full_adder adder3 (
        .A(A[0]),
        .B(sub_out[0]),
