  if (write_en) begin
    memory[mem_addr] <= data_in;
  end
  ecc_data_in <= {data_in, computed_ecc};
end

always @(mem_addr or ecc_data_in) begin
  data_out = memory[mem_addr];
  received_ecc = ecc_data_in[{data_width-1+ecc_width, ecc_width}];
  error_detected = ^(computed_ecc ^ received_ecc);
  if (error_detected) begin
    data_out[{data_width-1, 0}] = data_out[{data_width-1, 0}] ^ computed_ecc;
  end
end

