module pipelined_full_adder(
    input a, b, cin,
    output sum, cout
);

    wire s1, c1, s2, c2;

    // Stage 1
    xor #(.N(1)) x1(s1, a, b);
    and #(.N(1)) a1(c1, a, b);
    xor #(.N(1)) x2(sum, s1, cin);
    and #(.N(1)) a2(c2, s1, cin);

