module fsm_101_sequence_detection (
  input clk,
  input reset,
  input data,
  output reg match
);

  parameter S0 = 2'b00;
  parameter S1 = 2'b01;
  parameter S2 = 2'b10;
  parameter S3 = 2'b11;

  reg [1:0] state;
  reg [2:0] shift_reg;

  always @(posedge clk, negedge reset) begin
    if (reset == 0) begin
      state <= S0;
      shift_reg <= 0;
      match <= 0;
    end else begin
      case (state)
        S0: begin
          if (data == 1) begin
            shift_reg <= {shift_reg[1:0], data};
            state <= S1;
          end else begin
            shift_reg <= 0;
            state <= S0;
          end
        end
        S1: begin
          if (data == 0) begin
            shift_reg <= {shift_reg[1:0], data};
            state <= S2;
          end else begin
            shift_reg <= 0;
            state <= S0;
          end
        end
        S2: begin
          if (data == 1) begin
            shift_reg <= {shift_reg[1:0], data};
            state <= S3;
          end else begin
            shift_reg <= 0;
            state <= S0;
          end
        end
        S3: begin
          shift_reg <= {shift_reg[1:0], data};
          if (shift_reg == 3'b101) begin
            match <= 1;
          end else begin
            match <= 0;
          end
          state <= S1;
        end
      endcase
    end
  end
endmodule

