module signed_multiplier (
    input signed [15:0] A,
    input signed [15:0] B,
    output signed [31:0] P
);

reg signed [31:0] P_reg;
reg [4:0] counter;
reg [15:0] A_reg;
wire [15:0] B_reg;
wire [15:0] B_neg;
wire [15:0] B_shifted;
wire [15:0] B_shifted_neg;
wire [31:0] P_add;
wire [31:0] P_sub;

assign B_reg = (B[15] == 1) ? ~B + 1 : B;
assign B_neg = ~B_reg + 1;
assign B_shifted = {B_reg[14:0], 1'b0};
assign B_shifted_neg = {B_neg[14:0], 1'b0};

always @(*) begin
    A_reg = (A[15] == 1) ? ~A + 1 : A;
    P_reg = {16'b0, A_reg};
    counter = 16;

    while (counter != 0) begin
        if (P_reg[0] == 1 && P_reg[1] == 0) begin
            P_reg = P_reg + {B_shifted_neg, 1'b0};
        end else if (P_reg[0] == 0 && P_reg[1] == 1) begin
            P_reg = P_reg + {B_shifted, 1'b0};
        end
        P_reg = {P_reg[31:1], P_reg[0]};
        counter = counter - 1;
    end

    P_add = {16'b0, A_reg} + {16'b0, B_reg};
    P_sub = {16'b0, A_reg} + {16'b0, B_neg};

    if (P_reg[31] == 1) begin
        P = (P_add[31] == 1) ? {32'b1, 16'b0} : {32'b0, P_add[31:16]};
    end else begin
        P = (P_sub[31] == 1) ? {32'b1, 16'b0} : {32'b0, P_add[31:16]};
    end
end

endmodule

module atr_controller
