module sia_rxq (
    input clk_i,
    input reset_i,
    input [11:0] rxd_i,
    input rxc_i,
    input rxq_pop_i,
    input rxq_oe_i,
    output reg [11:0] rxq_dat_o,
    output reg rxq_full_o,
    output reg rxq_not_empty_o
);

    parameter SHIFT_REG_WIDTH = 12;
    parameter BAUD_RATE_WIDTH = 32;
    parameter DEPTH_BITS = 2;
    parameter DATA_BITS = 12;

    reg [SHIFT_REG_WIDTH-1:0] shift_reg;
    reg [DEPTH_BITS-1:0] head_ptr;
    reg [DEPTH_BITS-1:0] tail_ptr;
    reg [DATA_BITS-1:0] data_out;
    reg [DATA_BITS-1:0] data_in;
    reg [7:0] bit_cnt;
    reg [BAUD_RATE_WIDTH-1:0] baud_cnt;
    reg rx_bit;
    reg rx_done;
    reg [DEPTH_BITS-1:0] depth;

    always @(posedge clk_i) begin
        if (reset_i) begin
            shift_reg <= 0;
            head_ptr <= 0;
            tail_ptr <= 0;
            bit_cnt <= 0;
            baud_cnt <= 0;
            rx_bit <= 1;
            rx_done <= 0;
            depth <= 0;
            rxq_dat_o <= 0;
            rxq_full_o <= 0;
            rxq_not_empty_o <= 0;
        end else begin
            if (baud_cnt == 0) begin
                if (bit_cnt == 0) begin
                    if (rxq_pop_i && rxq_not_empty_o) begin
                        tail_ptr <= tail_ptr + 1;
                        depth <= depth - 1;
                        if (tail_ptr == (1 << DEPTH_BITS)) begin
                            tail_ptr <= 0;
                        end
                    end
                    if (rxq_oe_i && rxq_not_empty_o) begin
                        rxq_dat_o <= shift_reg[tail_ptr*DATA_BITS +: DATA_BITS];
                    end
                    if (depth == 0) begin
                        rxq_not_empty_o <= 0;
                    end
                    if (depth == (1 << DEPTH_BITS) - 1) begin
                        rxq_full_o <= 1;
                    end else begin
                        rxq_full_o <= 0;
                    end
                    rx_bit <= rxd_i;
                    bit_cnt <= 8;
                    rx_done <= 0;
                end else begin
                    shift_reg <= {shift_reg[SHIFT_REG_WIDTH-2:0], rx_bit};
                    bit_cnt <= bit_cnt - 1;
                    rx_bit <= shift_reg[SHIFT_REG_WIDTH-1];
                    if (bit_cnt == 1) begin
                        rx_done <= 1;
                        data_in <= shift_reg[DATA_BITS-1:0];
                    end
                end
                baud_cnt <= (1 << BAUD_RATE_WIDTH) / 1000000;
            end else begin
                baud_cnt <= baud_cnt - 1;
            end
            if (rx_done) begin
                if (depth < (1 << DEPTH_BITS)) begin
                    shift_reg[head_ptr*DATA_BITS +: DATA_BITS] <= data_in;
                    head_ptr <= head_ptr + 1;
                    depth <= depth + 1;
                    if (head_ptr == (1 << DEPTH_BITS)) begin
                        head_ptr <= 0;
                    end
                    rxq_not_empty_o <= 1;
                end
            end
        end
    end

endmodule

