module timer
  #(parameter
    TIMEOUT = 100)
   (input       clk,
    input       rst,

    input       up_req,
    output      up_grant,
    input       up_ack,

    output      down_req,
    input       down_grant,
    output      down_ack,
    output reg  timeout
);


    /**
     * Local parameters
     */

`ifdef VERBOSE
    initial $display("Bus timer with timeout %d", TIMEOUT);
`endif


    /**
     * Internal signals
     */

    reg  [31:0] counter;


    /**
     * Implementation
     */

    assign up_grant = down_grant;

    assign down_ack = up_ack;

    assign timeout = (TIMEOUT == counter);

    assign down_req = up_req & ~timeout;


    always @(posedge clk)
        if (rst) begin
            counter <= 'b0;
            timeout <= 0;
        end
        else begin
            counter <= counter + (down_grant & ~timeout);
            timeout <= timeout | (TIMEOUT == counter);
        end


endmodule

