module top_module (
    input signed [15:0] a,
    input signed [15:0] b,
    output reg [15:0] sum_abs
);

    wire [15:0] abs_a;
    wire [15:0] abs_b;

    absolute_value abs_a_inst (
        .in(a),
        .out(abs_a)
    );

    absolute_value abs_b_inst (
        .in(b),
        .out(abs_b)
    );

    adder sum_inst (
        .a(abs_a),
        .b(abs_b),
        .sum(sum_abs)
    );

    always @(*) begin
        if (a < 0) begin
            sum_abs = abs_b - abs_a;
        end else if (b < 0) begin
            sum_abs = abs_a - abs_b;
        end else begin
            sum_abs = abs_a + abs_b;
        end
    end

endmodule

