module small_fifo (
  input clock,
  input [31:0] data,
  input rdreq,
  input sclr,
  input wrreq,
  output empty,
  output full,
  output [31:0] q,
  output [4:0] usedw
);

  reg [31:0] mem [0:31];
  reg [4:0] head = 0;
  reg [4:0] tail = 0;
  reg [4:0] count = 0;
  reg empty = 1;
  reg full = 0;
  reg [4:0] usedw = 0;
  reg [31:0] q = 0;

  always @(posedge clock) begin
    if (sclr) begin
      head <= 0;
      tail <= 0;
      count <= 0;
      empty <= 1;
      full <= 0;
      usedw <= 0;
      q <= 0;
    end else begin
      if (wrreq && !full) begin
        mem[head] <= data;
        head <= (head + 1) % 32;
        count <= count + 1;
        empty <= 0;
        if (count == 32) full <= 1;
      end
      if (rdreq && !empty) begin
        q <= mem[tail];
        tail <= (tail + 1) % 32;
        count <= count - 1;
        full <= 0;
        if (count == 1) empty <= 1;
      end
      usedw <= count;
    end
  end

endmodule

