module JtagUserIdentifier #(
    parameter IDCODE_VID = 24'h000000,
    parameter IDCODE_PID = 8'h00
) (
    input wire tck,
    input wire tms,
    input wire tdi,
    output wire tdo
);

    reg[31:0] tap_shreg = 0;
    reg[31:0] shift_reg = 0;
    reg[2:0] state = 3'b100;

    //The TAP interface
    assign tdo = tap_shreg[0];

    always @(posedge tck) begin
        if (state == 3'b000) begin //RESET
            state <= 3'b100;
        end
        else if (state == 3'b100) begin //RUN-TEST/IDLE
            if (tms) begin
                state <= 3'b010;
            end
        end
        else if (state == 3'b010) begin //SELECT-DR-SCAN
            if (tms) begin
                state <= 3'b001;
            end
        end
        else if (state == 3'b001) begin //CAPTURE-DR-SHIFT-EXIT1-UPDATE-DR-EXIT2
            if (tms) begin
                state <= 3'b010;
            end
            else begin
                if (tap_shreg[31]) begin //Update DR
                    tap_shreg <= {1'b0, shift_reg[31:1]};
                end
                else begin //Capture-DR-Shift-Exit1
                    shift_reg <= {tdi, shift_reg[31:1]};
                    tap_shreg <= {1'b1, tap_shreg[31:1]};
                end
            end
        end
    end

    always @(posedge tck) begin
        if (state == 3'b001) begin //CAPTURE-DR-SHIFT-EXIT1-UPDATE-DR-EXIT2
            if (!tms && !tap_shreg[31]) begin //Shift-DR
                shift_reg <= {tdi, shift_reg[31:1]};
            end
        end
    end

    always @(posedge tck) begin
        if (state == 3'b100) begin //RUN-TEST/IDLE
            tap_shreg <= {IDCODE_VID, IDCODE_PID};
        end
    end

endmodule

