    input [7:0] b,
    output [3:0] out,
    output [7:0] result
);

    wire [2:0] comp_out;
    wire [3:0] enc_out;
    wire [7:0] and_or_out;

    comparator comp(.a(a), .b(b), .out(comp_out));
    encoder enc(.in(comp_out), .out(enc_out));
    control_logic ctrl(.sel(out), .comp(comp_out), .enc(enc_out));
    and_or and_or_gate(.a(a), .b(b), .enc(enc_out), .out(and_or_out));

    assign result = (out >= 4) ? and_or_out & 8'hFF : and_or_out | 8'h00;

    always @(posedge clk) begin
        if (reset) begin
            out <= 4'b0000;
        end else begin
            out <= enc_out;
        end
    end

endmodule

