module lf_edge_detect(
    input clk,
    input [7:0] adc_in,
    input [7:0] threshold,
    output [7:0] max,
    output [7:0] min,
    output [7:0] high_threshold,
    output [7:0] highz_threshold,
    output [7:0] lowz_threshold,
    output [7:0] low_threshold,
    output edge_state,
    output edge_toggle
);

reg [7:0] max_reg;
reg [7:0] min_reg;
reg [7:0] threshold_reg;
reg [7:0] adc_filtered;
reg [7:0] high_threshold_reg;
reg [7:0] highz_threshold_reg;
reg [7:0] lowz_threshold_reg;
reg [7:0] low_threshold_reg;
reg edge_state_reg;
reg edge_toggle_reg;

always @(posedge clk) begin
    adc_filtered <= adc_in;
    threshold_reg <= threshold;
    if (adc_filtered > max_reg) begin
        max_reg <= adc_filtered;
    end
    if (adc_filtered < min_reg) begin
        min_reg <= adc_filtered;
    end
    high_threshold_reg <= max_reg - threshold_reg;
    highz_threshold_reg <= max_reg - (threshold_reg >> 1);
    lowz_threshold_reg <= min_reg + (threshold_reg >> 1);
    low_threshold_reg <= min_reg + threshold_reg;
    if (adc_filtered > high_threshold_reg) begin
        edge_state_reg <= 1'b1;
    end else if (adc_filtered < low_threshold_reg) begin
        edge_state_reg <= 1'b0;
    end
end

always @(posedge clk) begin
    if (edge_state_reg != edge_state) begin
        edge_toggle_reg <= ~edge_toggle_reg;
    end
    edge_state <= edge_state_reg;
    edge_toggle <= edge_toggle_reg;
    max <= max_reg;
    min <= min_reg;
    high_threshold <= high_threshold_reg;
    highz_threshold <= highz_threshold_reg;
    lowz_threshold <= lowz_threshold_reg;
    low_threshold <= low_threshold_reg;
end

endmodule

module lo_edge_detect(
    input pck0, input pck_divclk,
    output pwr_lo, output pwr_hi,
    output pwr_oe1, output pwr_oe2, output pwr_oe3, output pwr_oe4,
    input [7:0] adc_d, output adc_clk,
    output ssp_frame, input ssp_dout, output ssp_clk,
    input cross_lo,
    output dbg,
    input lf_field,
    input lf_ed_toggle_mode, input [7:0] lf_ed_threshold
);

wire tag_modulation = ssp_dout & !lf_field;
wire reader_modulation = !ssp_dout & lf_field & pck_divclk;

// No logic, straight through.
assign pwr_oe1 = 1'b0; // not used in LF mode
assign pwr_oe2 = tag_modulation;
assign pwr_oe3 = tag_modulation;
assign pwr_oe4 = tag_modulation;
assign ssp_clk = cross_lo;
assign pwr_lo = reader_modulation;
assign pwr_hi = 1'b0;

// filter the ADC values
wire data_rdy;
wire [7:0] adc_filtered;
assign adc_clk = pck0;
lp20khz_1MSa_iir_filter adc_filter(pck0, adc_d, data_rdy, adc_filtered);

// detect edges
wire [7:0] high_threshold, highz_threshold, lowz_threshold, low_threshold;
wire [7:0] max, min;
wire edge_state, edge_toggle;
lf_edge_detect lf_ed(pck0, adc_filtered, lf_ed_threshold,
	max, min,
	high_threshold, highz_threshold, lowz_threshold, low_threshold,
	edge_state, edge_toggle);

assign dbg = lf_ed_toggle_mode ? edge_toggle : edge_state;

assign ssp_frame = lf_ed_toggle_mode ? edge_toggle : edge_state;

endmodule

