always @(posedge clk) begin
    data_reg <= data_in;
    data_reg1 <= data_reg;
    data_reg2 <= data_reg1;
    data_reg3 <= data_reg2;
    data_out <= (data_reg + (data_reg1 << 1) + (data_reg2 << 1) + data_reg3) >> 3;
end

