);

reg [2:0] counter;

always @(posedge clk or negedge areset) begin
    if (!areset) begin
        q <= 4'h0;
        counter <= 3'h0;
    end else begin
        if (load) begin
            q <= d;
            counter <= 3'h0;
        end else if (ena) begin
            if (counter == 3'h7) begin
                q <= {q[2:0], 1'b0};
                counter <= 3'h0;
            end else begin
                q <= {q[2:0], q[3]};
                counter <= counter + 1;
            end
        end
    end
end

