module Floating_Point_Arithmetic (
  input [31:0] operand1,
  input [31:0] operand2,
  input [1:0] operation,
  output reg [31:0] result
);

parameter mantissa_width = 23; // width of the mantissa in bits
parameter exponent_width = 8; // width of the exponent in bits
parameter bias = 127; // bias of the exponent field

reg [31:0] add_result, sub_result, mul_result, div_result;
reg [31:0] operand2_neg;

// Negate operand2 for subtraction
always @(*) begin
  operand2_neg = {operand2[31], operand2[30:0]};
end

// Floating-point addition
always @(*) begin
  add_result = $fadd(operand1, operand2);
end

// Floating-point subtraction
always @(*) begin
  sub_result = $fadd(operand1, operand2_neg);
end

// Floating-point multiplication
always @(*) begin
  mul_result = $fmul(operand1, operand2);
end

// Floating-point division
always @(*) begin
  div_result = $fdiv(operand1, operand2);
end

// Select the result based on the operation
always @(*) begin
  case (operation)
    2'b00: result = add_result;
    2'b01: result = sub_result;
    2'b10: result = mul_result;
    2'b11: result = div_result;
    default: result = 32'b0;
  endcase
end

endmodule

module fifo_buffer (
  input clk,
  input rst_n,
  input fifo_rd,
  input fifo_wr,
  input [7:0] fifo_data_in,
  output fifo_empty,
  output fifo_full,
  output [7:0] fifo_data_out,
  output reg [3:0] fifo_count
);

  parameter FIFO_SIZE = 16;

  reg [7:0] fifo_buffer [0:FIFO_SIZE-1];
  reg [3:0] read_ptr = 4'b0;
  reg [3:0] write_ptr = 4'b0;
  reg [3:0] next_write_ptr;
  reg [3:0] next_read_ptr;

  assign fifo_empty = (fifo_count == 0);
  assign fifo_full = (fifo_count == FIFO_SIZE);

  always @(posedge clk) begin
    if (rst_n == 0) begin
      fifo_count <= 0;
      read_ptr <= 0;
      write_ptr <= 0;
    end else begin
      if (fifo_wr && !fifo_full) begin
        fifo_buffer[write_ptr] <= fifo_data_in;
        next_write_ptr <= write_ptr + 1;
        if (next_write_ptr == FIFO_SIZE) begin
          next_write_ptr <= 0;
        end
      end else begin
        next_write_ptr <= write_ptr;
      end
      if (fifo_rd && !fifo_empty) begin
        fifo_data_out <= fifo_buffer[read_ptr];
        next_read_ptr <= read_ptr + 1;
        if (next_read_ptr == FIFO_SIZE) begin
          next_read_ptr <= 0;
        end
      end else begin
        next_read_ptr <= read_ptr;
      end
      if (fifo_wr != fifo_rd) begin
        fifo_count <= fifo_count + (fifo_wr ? 1 : -1);
      end
      write_ptr <= next_write_ptr;
      read_ptr <= next_read_ptr;
    end
  end

endmodule

module fifo_buffer (
  input clk,
  input fifo_rd,
  input rst_n,
  output fifo_EF,
  output reg [7:0] fifo_rdata,
  output rfifo_full,
  output reg [5:0] rfifo_used
);

  // Define FIFO buffer parameters
  parameter DEPTH = 64;
  parameter WIDTH = 8;

  // Define FIFO buffer memory
  reg [WIDTH-1:0] fifo_mem [0:DEPTH-1];
  reg [6:0] write_ptr;
  reg [6:0] read_ptr;
  reg [6:0] used_entries;
  wire fifo_empty = (used_entries == 0);
  wire fifo_full = (used_entries == DEPTH);

  // Define FIFO buffer read logic
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      read_ptr <= 7'b0;
      fifo_rdata <= 8'b0;
      rfifo_used <= 6'b0;
    end
    else if (fifo_rd && !fifo_empty) begin
      fifo_rdata <= fifo_mem[read_ptr];
      read_ptr <= read_ptr + 1;
      rfifo_used <= used_entries - 1;
    end
  end

  // Define FIFO buffer write logic
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      write_ptr <= 7'b0;
      used_entries <= 6'b0;
    end
    else if (!fifo_full) begin
      fifo_mem[write_ptr] <= fifo_rdata;
      write_ptr <= write_ptr + 1;
      used_entries <= used_entries + 1;
    end
  end

  // Define FIFO buffer status outputs
  assign fifo_EF = fifo_empty;
  assign rfifo_full = fifo_full;

endmodule

module Comparator (
  input [n-1:0] in1,
  input [n-1:0] in2,
  output greater,
  output less,
  output equal
);

parameter n = 8; // number of bits in the input signals

// Define the module inputs and outputs
// input [n-1:0] in1, in2;
// output greater, less, equal;

// Define the module parameters
// parameter n = 8;

// Perform bit-wise comparison for unsigned numbers
assign greater = (in1 > in2) ? 1'b1 : 1'b0;
assign less = (in1 < in2) ? 1'b1 : 1'b0;
assign equal = (in1 == in2) ? 1'b1 : 1'b0;

// Take into account the sign bit for signed numbers
always @(*) begin
  if (in1[n-1] == 1'b0 && in2[n-1] == 1'b1) begin
    greater = 1'b1;
    less = 1'b0;
    equal = 1'b0;
  end else if (in1[n-1] == 1'b1 && in2[n-1] == 1'b0) begin
    greater = 1'b0;
    less = 1'b1;
    equal = 1'b0;
  end else if (in1[n-1] == 1'b1 && in2[n-1] == 1'b1) begin
    greater = (in1 > in2) ? 1'b0 : 1'b1;
    less = (in1 < in2) ? 1'b0 : 1'b1;
    equal = (in1 == in2) ? 1'b1 : 1'b0;
  end
end

endmodule

module crc (
   input clk,
   input [31:0] in,
   output reg [63:0] crc
);

   // ROM module containing precomputed table of 256 64-bit values
   rom rom_inst(.addr(in[7:0]), .data(rom_data));

   // Initial value of CRC checksum
   initial crc = 64'h5aef0c8d_d70a4497;

   // Update CRC value for each input data value
   always @(posedge clk) begin
      crc = rom_data[(crc >> 56) ^ in[31:24]] ^ (crc << 8);
      crc = rom_data[(crc >> 56) ^ in[23:16]] ^ (crc << 8);
      crc = rom_data[(crc >> 56) ^ in[15:8]] ^ (crc << 8);
      crc = rom_data[(crc >> 56) ^ in[7:0]] ^ (crc << 8);
   end

endmodule

// ROM module containing precomputed table of 256 64-bit values
module rom (
   input [7:0] addr,
   output reg [63:0] data
);

   always @* begin
      case (addr)
         8'h00: data = 64'h0000000000000000;
         8'h01: data = 64'h7f6ff7f6f7f6f7f;
         8'h02: data = 64'hfeb1fe4f1fe4f1fe;
         // ...
         8'hfd: data = 64'hf9f6f9f6f9f6f9f6;
         8'hfe: data = 64'h7e6f7e6f7e6f7e6f;
         8'hff: data = 64'h0000000000000000;
      endcase
   end

endmodule

