module qlal3_oscillator_cell (
  input         osc_en,
  input         osc_fsel,
  input  [ 2:0] osc_sel,
  output        fast_clk_out
);

  // Parameter definitions
  parameter CLK_PERIOD_1MHZ = 1000;
  parameter CLK_PERIOD_2MHZ = 500;
  parameter CLK_PERIOD_4MHZ = 250;
  parameter CLK_PERIOD_8MHZ = 125;
  parameter CLK_PERIOD_16MHZ = 62.5;
  parameter CLK_PERIOD_32MHZ = 31.25;
  parameter CLK_PERIOD_64MHZ = 15.625;
  parameter CLK_PERIOD_128MHZ = 7.8125;

  // Local variable definitions
  reg [31:0] counter;
  reg        clk_out;

  // Clock period selection
  always @* begin
    case (osc_sel)
      3'b000: counter = CLK_PERIOD_1MHZ;
      3'b001: counter = CLK_PERIOD_2MHZ;
      3'b010: counter = CLK_PERIOD_4MHZ;
      3'b011: counter = CLK_PERIOD_8MHZ;
      3'b100: counter = CLK_PERIOD_16MHZ;
      3'b101: counter = CLK_PERIOD_32MHZ;
      3'b110: counter = CLK_PERIOD_64MHZ;
      3'b111: counter = CLK_PERIOD_128MHZ;
      default: counter = CLK_PERIOD_1MHZ;
    endcase
  end

  // Clock output generation
  always @(posedge osc_en) begin
    if (!osc_fsel) begin
      clk_out <= 1'b0;
    end
  end

  always @(posedge osc_en or negedge clk_out) begin
    if (!osc_fsel) begin
      counter <= counter - 1;
      if (counter == 0) begin
        clk_out <= ~clk_out;
        counter <= counter + counter;
      end
    end
  end

  assign fast_clk_out = clk_out;

endmodule

