module Moore_Chart
(
  clk,
  rst_n,
  enb,
  a,
  b
);

input clk;
input rst_n;
input enb;
output [63:0] a;
output [63:0] b;

parameter IN_FINAL = 3'd0, IN_IDLE = 3'd1, IN_INITIAL = 3'd2, IN_SEQ1 = 3'd3, IN_SEQ2 = 3'd4;

reg [2:0] is_Moore_Chart;
real a_1;
real b_1;
real a_reg;
real b_reg;
reg [2:0] is_Moore_Chart_next;
real a_reg_next;
real b_reg_next;

always @(posedge clk or negedge rst_n) begin
  if (!rst_n) begin
    is_Moore_Chart <= IN_INITIAL;
    a_reg <= 0.0;
    b_reg <= 0.0;
  end
  else begin
    if (enb) begin
      is_Moore_Chart <= is_Moore_Chart_next;
      a_reg <= a_reg_next;
      b_reg <= b_reg_next;
    end
  end
end

always @* begin
  is_Moore_Chart_next = is_Moore_Chart;
  a_reg_next = a_reg;
  b_reg_next = b_reg;

  case (is_Moore_Chart)
    IN_FINAL: begin
      // No output
    end
    IN_IDLE: begin
      a_reg_next = 0.0;
      b_reg_next = b_reg;
    end
    IN_INITIAL: begin
      a_reg_next = 0.0;
      b_reg_next = 0.0;
    end
    IN_SEQ1: begin
      a_reg_next = 1.0;
      b_reg_next = b_reg + 1.0;
    end
    IN_SEQ2: begin
      a_reg_next = 2.0;
      b_reg_next = b_reg + 2.0;
    end
  endcase

  case (is_Moore_Chart)
    IN_FINAL: begin
      is_Moore_Chart_next = IN_IDLE;
    end
    IN_IDLE: begin
      is_Moore_Chart_next = IN_SEQ1;
    end
    IN_INITIAL: begin
      is_Moore_Chart_next = IN_IDLE;
    end
    IN_SEQ1: begin
      is_Moore_Chart_next = IN_SEQ2;
    end
    default: begin
      is_Moore_Chart_next = IN_FINAL;
    end
  endcase
end

always @* begin
  a_1 = a_reg_next;
  b_1 = b_reg_next;
end

assign a = $realtobits(a_1);
assign b = $realtobits(b_1);

