module LZW (
  input clk,
  input rst,
  input [7:0] in_byte,
  output reg [15:0] out_code,
  output reg [7:0] out_byte
);

  // Define constants
  parameter MAX_DICT_SIZE = 4096;
  parameter MAX_CODE_WIDTH = 12;
  parameter MIN_CODE_WIDTH = 9;
  parameter CLEAR_CODE = 256;
  parameter END_CODE = 257;

  // Define variables
  reg [15:0] dict [0:MAX_DICT_SIZE-1];
  reg [11:0] next_code;
  reg [11:0] code_width;
  reg [11:0] old_code;
  reg [11:0] new_code;
  reg [11:0] prefix [0:MAX_DICT_SIZE-1];
  reg [7:0] suffix [0:MAX_DICT_SIZE-1];
  reg [11:0] clear_code;
  reg [11:0] end_code;
  reg [11:0] max_code;
  reg [11:0] bit_buffer;
  reg [3:0] bit_count;
  reg [11:0] i;
  reg [11:0] j;

  // Initialize variables
  initial begin
    clear_code = CLEAR_CODE;
    end_code = END_CODE;
    max_code = (1 << MIN_CODE_WIDTH) - 1;
    next_code = end_code + 1;
    code_width = MIN_CODE_WIDTH;
    bit_buffer = 0;
    bit_count = 0;
    for (i = 0; i < clear_code; i = i + 1) begin
      dict[i] = i;
      prefix[i] = 0;
      suffix[i] = i;
    end
  end

  // Compress input data stream
  always @(posedge clk) begin
    if (rst) begin
      next_code <= end_code + 1;
      code_width <= MIN_CODE_WIDTH;
      bit_buffer <= 0;
      bit_count <= 0;
      out_code <= 0;
    end else begin
      // Check if dictionary is full
      if (next_code > max_code) begin
        code_width <= code_width + 1;
        max_code <= (1 << code_width) - 1;
      end
      // Find longest prefix in dictionary
      new_code <= in_byte;
      if (old_code == 0) begin
        out_code <= new_code;
        old_code <= new_code;
      end else begin
        if (dict[old_code] != 0) begin
          prefix[next_code] <= old_code;
          suffix[next_code] <= new_code;
          out_code <= old_code;
          next_code <= next_code + 1;
          old_code <= new_code;
        end else begin
          out_code <= new_code;
          old_code <= new_code;
        end
      end
    end
  end

  // Decompress compressed data stream
  always @(posedge clk) begin
    if (rst) begin
      next_code <= end_code + 1;
      code_width <= MIN_CODE_WIDTH;
      bit_buffer <= 0;
      bit_count <= 0;
      out_byte <= 0;
    end else begin
      // Check if dictionary is full
      if (next_code > max_code) begin
        code_width <= code_width + 1;
        max_code <= (1 << code_width) - 1;
      end
      // Read in compressed code
      bit_buffer <= bit_buffer | (in_byte << bit_count);
      bit_count <= bit_count + code_width;
      if (bit_count >= 8) begin
        out_byte <= bit_buffer[7:0];
        bit_buffer <= bit_buffer >> 8;
        bit_count <= bit_count - 8;
      end
    end
  end

endmodule

