reg [2:0] state; // state machine to keep track of received bits
parameter IDLE = 3'b000, BIT0 = 3'b001, BIT1 = 3'b010, BIT2 = 3'b011,
          BIT3 = 3'b100, BIT4 = 3'b101, BIT5 = 3'b110, BIT6 = 3'b111;

always @(posedge clk) begin
  if(!rst_n) begin
    miso <= 1'b1;
    state <= IDLE;
    data_in <= 8'b0;
    recived_status <= 1'b0;
  end
  else begin
    case(state)
      IDLE:
        if(!ssel) begin
          state <= BIT0;
        end
      BIT0:
        begin
          data_in[0] <= mosi;
          state <= BIT1;
        end
      BIT1:
        begin
          data_in[1] <= mosi;
          state <= BIT2;
        end
      BIT2:
        begin
          data_in[2] <= mosi;
          state <= BIT3;
        end
      BIT3:
        begin
          data_in[3] <= mosi;
          state <= BIT4;
        end
      BIT4:
        begin
          data_in[4] <= mosi;
          state <= BIT5;
        end
      BIT5:
        begin
          data_in[5] <= mosi;
          state <= BIT6;
        end
      BIT6:
        begin
          data_in[6] <= mosi;
          state <= IDLE;
          recived_status <= 1'b1;
        end
    endcase
  end
end

endmodule

