module alu (
    input  [31:0] x,
    input  [15:0] y,
    output [31:0] out,
    input  [ 2:0] t,
    input  [ 2:0] func,
    input  [15:0] iflags,
    output [ 8:0] oflags,
    input         word_op,
    input  [15:0] seg,
    input  [15:0] off,
    input         clk,
    output        div_exc
  );

  // Net declarations
  wire [15:0] add, log, shi, rot;
  wire  [8:0] othflags;
  wire [19:0] oth;
  wire [31:0] cnv, mul;
  wire af_add, af_cnv;
  wire cf_cnv, cf_add, cf_mul, cf_log, cf_shi, cf_rot;
  wire of_cnv, of_add, of_mul, of_log, of_shi, of_rot;
  wire ofi, sfi, zfi, afi, pfi, cfi;
  wire ofo, sfo, zfo, afo, pfo, cfo;
  wire flags_unchanged;
  wire dexc;

  // Module instances
  addsub add1 (x[15:0], y, add, func, word_op, cfi, cf_add, af_add, of_add);

  conv cnv2 (
    .x      (x[15:0]),
    .func   (func),
    .out    (cnv),
    .iflags ({afi, cfi}),
    .oflags ({af_cnv, of_cnv, cf_cnv})
  );

  muldiv mul3 (
    .x       (x),
    .y       (y),
    .o       (mul),
    .f       (func),
    .word_op (word_op),
    .cfo     (cf_mul),
    .ofo     (of_mul),
    .clk     (clk),
    .exc     (dexc)
  );

  bitlog log4 (x[15:0], y, log, func, cf_log, of_log);
  shifts shi5 (x[15:0], y[4:0], shi, func[1:0], word_op, cfi, ofi, cf_shi, of_shi);
  rotate rot6 (x[15:0], y[4:0], func[1:0], cfi, word_op, rot, cf_rot, ofi, of_rot);
  othop  oth7 (x[15:0], y, seg, off, iflags, func, word_op, oth, othflags);

  mux8_16 m0(t, {8'd0, y[7:0]}, add, cnv[15:0],
             mul[15:0], log, shi, rot, oth[15:0], out[15:0]);
  mux8_16 m1(t, 16'd0, 16'd0, cnv[31:16], mul[31:16],
             16'd0, 16'd0, 16'd0, {12'b0,oth[19:16]}, out[31:16]);
  mux8_1  a1(t, 1'b0, cf_add, cf_cnv, cf_mul, cf_log, cf_shi, cf_rot, 1'b0, cfo);
  mux8_1  a2(t, 1'b0, af_add, af_cnv, 1'b0, 1'b0, 1'b0, afi, 1'b0, afo);
  mux8_1  a3(t, 1'b0, of_add, of_cnv, of_mul, of_log, of_shi, of_rot, 1'b0, ofo);

  // Flags
  assign pfo = flags_unchanged ? pfi : ^~ out[7:0];
  assign zfo = flags_unchanged ? zfi
             : ((word_op && (t!=3'd2)) ? ~|out[15:0] : ~|out[7:0]);
  assign sfo = flags_unchanged ? sfi
             : ((word_op && (t!=3'd2)) ? out[15] : out[7]);

  assign oflags = (t == 3'd7) ? othflags 
                 : { ofo, iflags[10:8], sfo, zfo, afo, pfo, cfo };

  assign ofi = iflags[11];
  assign sfi = iflags[7];
  assign zfi = iflags[6];
  assign afi = iflags[4];
  assign pfi = iflags[2];
  assign cfi = iflags[0];

  assign flags_unchanged = (t == 3'd4 && func == 3'd2
                         || t == 3'd5 && y[4:0] == 5'h0
                         || t == 3'd6);

  assign div_exc = func[1] && (t==3'd3) && dexc;

endmodule

module my_module(
    input A,
    input B,
    input C,
    input D,
    input E,
    input F,
    input G,
    input H,
    output Y
);

    wire and1_out, and2_out, and3_out, and4_out, and5_out, and6_out, and7_out, and8_out, or1_out, or2_out;

    and and1(and1_out, A, B);
    and and2(and2_out, and1_out, C);
    not not1(D_bar, D);
    not not2(E_bar, E);
    and and3(and3_out, D_bar, E_bar);
    or or1(or1_out, F, G);
    not not3(H_bar, H);
    and and4(and4_out, and3_out, or1_out);
    and and5(and5_out, H_bar, and4_out);
    not not4(Y_bar, and5_out);
    or or2(Y, Y_bar, 1'b0);

endmodule

module alu(zero, aluRes, input1, input2, aluCtr);
    output zero;
    output [31:0] aluRes;
    input [31:0] input1;
    input [31:0] input2;
    input [3:0] aluCtr;

    reg zero;
    reg [31:0] aluRes;

    always @ (input1 or input2 or aluCtr)
    begin
        case (aluCtr)
            4'b0010: // Addition
                begin
                    aluRes = input1 + input2;
                    zero = (aluRes == 0) ? 1 : 0;
                end
            4'b0110: // Subtraction
                begin
                    aluRes = input1 - input2;
                    zero = (aluRes == 0) ? 1 : 0;
                end
            4'b0000: // Bitwise AND
                begin
                    aluRes = input1 & input2;
                    zero = (aluRes == 0) ? 1 : 0;
                end
            4'b0001: // Bitwise OR
                begin
                    aluRes = input1 | input2;
                    zero = (aluRes == 0) ? 1 : 0;
                end
            4'b0111: // Set Less Than
                begin
                    aluRes = (input1 < input2) ? 1 : 0;
                    zero = (aluRes == 0) ? 1 : 0;
                end
            4'b1100: // Bitwise NOR
                begin
                    aluRes = ~(input1 | input2);
                    zero = (aluRes == 0) ? 1 : 0;
                end
            default:
                begin
                    aluRes = 0;
                    zero = 1;
                end
        endcase
    end

endmodule

module multi_channel_mutex (
    input [10:0] Data_In,
    input [3:0] Mutex_Addr_I_reg,
    input [31:23] Mutex_Wr_Data_I_reg,
    input Write_Strobe,
    input [1:0] Q,
    input S0_AXI_ACLK,
    output reg [8:0] D
);

reg [1:0] current_channel;
reg [10:0] ram [0:9];
wire [3:0] carry_out;

assign carry_out[0] = 1'b0;
assign carry_out[1] = 1'b0;
assign carry_out[2] = 1'b0;
assign carry_out[3] = 1'b0;

CARRY4 carry_chain (
    .CI(1'b0),
    .CO(carry_out),
    .CYINIT(1'b1),
    .DI({1'b0, 1'b0, 1'b0, 1'b0}),
    .O(carry_out[3:0]),
    .S({Mutex_Addr_I_reg[0], current_channel}));

always @(posedge S0_AXI_ACLK) begin
    case(Q)
        2'b00: current_channel <= 2'b00;
        2'b01: current_channel <= 2'b01;
        2'b10: current_channel <= 2'b10;
        2'b11: current_channel <= 2'b11;
    endcase

    if (Write_Strobe && (Mutex_Addr_I_reg[0] == current_channel)) begin
        ram[current_channel] <= Data_In;
    end

    D <= ram[current_channel][8:0];
end

endmodule

