  output Q
);

  reg Q_reg;
  wire Q_next;

  // Implement the flip-flop with active-low reset and set
  always @(posedge CK or negedge RN or negedge SN) begin
    if (!RN) begin
      Q_reg <= 0;
    end else if (!SN) begin
      Q_reg <= 1;
    end else if (!TE) begin
      // Do nothing
    end else begin
      Q_reg <= D;
    end
  end

  // Implement the TI control signal
  assign Q_next = (TI) ? D : Q_reg;

  // Implement the output Q
  assign Q = Q_next;

endmodule

module rem_onestate
	(
		clk,
		rst,

		is_sticky,

		delay_valid,
		delay_cycles,

		pred_valid,
		pred_match,
		pred_index,

		act_input,
		act_output,
		act_index
	);

	input clk;
	input rst;

	input is_sticky;

	input pred_valid;
	input pred_match;
	input [15:0] pred_index;

	input delay_valid;
	input [3:0] delay_cycles;

	input act_input;
	output reg act_output;
	output reg [15:0] act_index;

	reg activated;

	reg [3:0] delay_cycles_reg;

	reg [2+15:0] delay_shift;

	always @(posedge clk ) begin

		if (delay_valid==1) delay_cycles_reg <= delay_cycles;

		if (rst) begin
			act_output <= 0;					
			activated <= 0;
		end			
		else 
		begin 

			delay_shift <= {delay_shift[14:2],act_input,2'b00};

			activated <= (delay_cycles_reg>1) ? delay_shift[delay_cycles_reg] : act_input;

			if (pred_valid) begin

				if ((delay_cycles_reg==0 && act_input==1) || (delay_cycles_reg!=0 && activated==1) && pred_match==1) begin			
					act_output <= pred_match;	

					if (act_output==0) act_index <= pred_index;
				end
				else begin
					if (is_sticky) begin
						act_output <= act_output;
					end else begin
						act_output <= 0;
					end
				end
			end
			else begin
				if (is_sticky) begin
					act_output <= act_output;
				end else begin
					act_output <= 0;
				end
			end

		end
	end

endmodule

module system_controller (
    input wire clk_in,
    input wire reset_in,
    output reg clk_sys,
    output reg reset_sys,
    output reg locked
);

    // Input buffer to ensure XCLK signal is routed onto low skew clock lines
    wire xclk_buf;
    IBUFG xclk_ibufg (.I(clk_in), .O(xclk_buf));

    // Reset counter
    reg [4:0] reset_count = 0;
    always @(posedge clk_in or posedge reset_in) begin
        if (reset_in) begin
            reset_count <= 0;
            reset_sys <= 1;
            locked <= 0;
        end else if (reset_count < 10) begin
            reset_count <= reset_count + 1;
            reset_sys <= 1;
            locked <= 0;
        end else begin
            reset_count <= 10;
            reset_sys <= 0;
            locked <= 1;
        end
    end

    // Clock buffer to ensure clock going out to hardware is on low skew line
    wire clk_buf;
    BUFG clk_bug (.O(clk_buf), .I(CLKFBOUT));
    clk_wiz_0 lab9_clocks (
        .clk_in1(xclk_buf),
        .clk_out1(CLKFBOUT),
        .reset(reset_in),
        .locked(locked)
    );

    // System clock
    always @(posedge clk_buf or posedge reset_in) begin
        if (reset_in) begin
            clk_sys <= 0;
        end else begin
            clk_sys <= ~clk_sys;
        end
    end

endmodule

