module uart (
    input [15:0] din,
    output [15:0] dout,
    input a0,
    input rnw,
    input clk,
    input reset_b,
    input cs_b,
    input rxd,
    output txd
);

    // CLKSPEED is the main clock speed
    parameter CLKSPEED = 32000000;

    // BAUD is the desired serial baud rate
    parameter BAUD = 115200;

    // DIVISOR is the number of clk cycles per bit time
    parameter DIVISOR = CLKSPEED / BAUD;

    // Registers
    reg [15:0] rx_bit_cnt = 0;
    reg [15:0] tx_bit_cnt = 0;
    reg [10:0] tx_shift_reg = 11'b1;
    reg [9:0] rx_shift_reg = 10'b1111111111;
    reg rxd1 = 1'b0;
    reg rxd2 = 1'b0;
    reg rx_full = 1'b0;
    reg [7:0] rx_data = 8'h00;
    wire rx_busy;
    wire tx_busy;

    // Assignments
    assign rx_busy = rx_shift_reg != 10'b1111111111;
    assign tx_busy = tx_shift_reg != 11'b1;
    assign txd = tx_shift_reg[0];
    assign dout = a0 ? {8'h00, rx_data} : {tx_busy, rx_full, 14'b0};

    // UART Receiver
    always @(posedge clk) begin
        rxd1 <= rxd;
        rxd2 <= rxd1;
        if (!cs_b && rnw && a0) begin
            rx_full <= 1'b0;
        end
        if (!reset_b) begin
            rx_shift_reg <= 10'b1111111111;
        end else if (!rx_shift_reg[0]) begin
            rx_shift_reg <= 10'b1111111111;
            rx_data <= rx_shift_reg[9:2];
            rx_full <= 1;
        end else if (rx_busy) begin
            if (rx_bit_cnt == 0) begin
                rx_bit_cnt <= DIVISOR;
                rx_shift_reg <= {rxd1, rx_shift_reg[9:1]};
            end else begin
                rx_bit_cnt <= rx_bit_cnt - 1;
            end
        end else if (!rxd1 && rxd2) begin
            rx_shift_reg <= 10'b0111111111;
            rx_bit_cnt <= DIVISOR >> 1;
        end
    end

    // UART Transmitter
    always @(posedge clk) begin
        if (!reset_b) begin
            tx_shift_reg <= 11'b1;
        end else if (tx_busy) begin
            if (tx_bit_cnt == 0) begin
                tx_shift_reg <= {1'b0, tx_shift_reg[10:1]};
                tx_bit_cnt <= DIVISOR - 1;
            end else begin
                tx_bit_cnt <= tx_bit_cnt - 1;
            end
        end else if (!cs_b && !rnw && !a0) begin
            tx_shift_reg <= {2'b11, din[7:0], 1'b0};
            tx_bit_cnt <= DIVISOR - 1;
        end
    end

endmodule

module fsm_vending_machine (
  input clk,
  input reset,
  input coin_inserted,
  input [1:0] item_selected,
  input item_dispensed,
  output reg dispense_item,
  output reg return_coin
);

  // Define the states
  parameter IDLE = 2'b00;
  parameter ITEM_SELECTED = 2'b01;
  parameter ITEM_DISPENSED = 2'b10;

  // Define the current state
  reg [1:0] state;

  // Define the next state
  reg [1:0] next_state;

  // Define the state transition logic
  always @ (posedge clk, posedge reset) begin
    if (reset) begin
      state <= IDLE;
    end else begin
      state <= next_state;
    end
  end

  // Define the state output logic
  always @ (state, coin_inserted, item_selected, item_dispensed) begin
    case (state)
      IDLE: begin
        dispense_item <= 0;
        return_coin <= 0;
        if (coin_inserted && item_selected != 2'b00) begin
          next_state <= ITEM_SELECTED;
        end else begin
          next_state <= IDLE;
        end
      end
      ITEM_SELECTED: begin
        dispense_item <= 1;
        return_coin <= 0;
        if (item_dispensed) begin
          next_state <= ITEM_DISPENSED;
        end else begin
          next_state <= ITEM_SELECTED;
        end
      end
      ITEM_DISPENSED: begin
        dispense_item <= 0;
        return_coin <= 1;
        next_state <= IDLE;
      end
      default: begin
        dispense_item <= 0;
        return_coin <= 0;
        next_state <= IDLE;
      end
    endcase
  end

endmodule

module async_to_sync_synchronizer (
