module four_input_gate (
    input A1,
    input A2,
    input B1,
    input B2,
    output Y
);

    wire AB1, AB2, AB1B2;

    // AND gate for A1 and B1
    and AB1_gate (
        .Y(AB1),
        .A(A1),
        .B(B1)
    );

    // AND gate for A2 and B2
    and AB2_gate (
        .Y(AB2),
        .A(A2),
        .B(B2)
    );

    // AND gate for AB1 and B2
    and AB1B2_gate (
        .Y(AB1B2),
        .A(AB1),
        .B(B2)
    );

    // OR gate for B1 and B2
    or B1B2_gate (
        .Y(Y),
        .A(B1),
        .B(B2)
    );

    // MUX for selecting output
    assign Y = (A1 & ~A2) ? B1 : // A1 high, A2 low
               (A2 & ~A1) ? B2 : // A2 high, A1 low
               (A1 & A2) ? AB1B2 : // A1 and A2 high
               B1B2; // A1 and A2 low

endmodule

