        .A1(A1),
        .A2(A2),
        .B1(B1)
    );

    assign X = (A1) ? temp : ((B1) ? ~A2 : 1'b1);

endmodule

module counter_3bit_sync_reset (
  input clk,
  input reset,
  input ena,
  output reg [2:0] count,
  output reg flag
);

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      count <= 3'b0;
      flag <= 1'b0;
    end
    else if (ena) begin
      if (count == 3'b111) begin
        count <= 3'b0;
        flag <= 1'b1;
      end
      else begin
        count <= count + 1;
        flag <= 1'b0;
      end
    end
  end

endmodule

module mips_cop0 (
    input clk,
    input rst,

    input [4:0] rd_addr,
    output reg [31:0] rd_data,
    output reg [31:0] rd_epc,
    output reg rd_int,
    output reg rd_status_exl,

    input [4:0] wr_addr,
    input wr_en,
    input [31:0] wr_data,
    input wr_status_exl_reset,
    input wr_status_exl_set,
    input wr_cause_en,
    input wr_cause_bd,
    input [5:0] wr_cause_int,
    input [3:0] wr_cause_excode,
    input wr_badvaddr_en,
    input [31:0] wr_badvaddr_data
);

    reg [31:0] epc;
    reg [31:0] badvaddr;

    reg cause_bd;
    reg [5:0] cause_ip;
    reg [3:0] cause_excode;

    reg [5:0] status_im;
    reg status_exl;
    reg status_ie;

    assign rd_epc = epc;
    assign rd_status_exl = status_exl;

    always @(posedge clk) begin
        if (rst) begin
            epc <= 32'd0;
            cause_bd <= 1'b0;
            cause_ip <= 6'd0;
            cause_excode <= 4'd0;
            status_im <= 6'd0;
            status_exl <= 1'b1;
            status_ie <= 1'b0;
            badvaddr <= 32'd0;
        end else begin
            epc <= wr_en & wr_addr == 5'd14 ? wr_data : epc;

            cause_bd <= wr_cause_en ? wr_cause_bd : cause_bd;
            cause_ip <= wr_cause_int;
            cause_excode <= wr_cause_en ? wr_cause_excode : cause_excode;

            status_im <= wr_en & wr_addr == 5'd12 ? wr_data[15:10] : status_im;
            status_exl <= wr_status_exl_reset ? 1'b0 : wr_status_exl_set ? 1'b1 : wr_en & wr_addr == 5'd12 ? wr_data[1] : status_exl;
            status_ie <= wr_en & wr_addr == 5'd12 ? wr_data[0] : status_ie;

            badvaddr <= wr_badvaddr_en ? wr_badvaddr_data : badvaddr;
        end
    end

    always @(*) begin
        rd_data = (rd_addr == 5'd14) ? epc :
                  (rd_addr == 5'd13) ? {cause_bd, 15'd0, cause_ip, 4'd0, cause_excode, 2'd0} :
                  (rd_addr == 5'd8) ? badvaddr :
                                      {16'd0, status_im, 8'd0, status_exl, status_ie};
        rd_int = |(cause_ip & status_im) & status_ie & !status_exl;
    end

endmodule

module shift_register (
  input clk,
  input reset,
  input load,
  input data_in,
  output reg [7:0] data_out
);

  reg [7:0] shift_reg;

  always @(posedge clk) begin
    if (reset) begin
      shift_reg <= 8'b0;
    end else if (load) begin
      shift_reg <= data_in;
    end else begin
      shift_reg <= {shift_reg[6:0], shift_reg[7]};
    end
  end

  assign data_out = shift_reg[7];

endmodule

module led_7seg_controller(
      input       CLK100MHZ,
      input       KEY0,
      input       KEY1,
      output      [7:0]  LED,
      output      [12:1] IO
);

    // wires & inputs
    wire          clk;
    wire          clkIn     =  CLK100MHZ;
    wire          rst_n     =  KEY0;
    wire          clkEnable =  ~KEY1;
    wire [31:0]   regData;

    //cores
    sm_top sm_top(
        .clkIn      ( clkIn     ),
        .rst_n      ( rst_n     ),
        .clkDevide  ( 4'b1000   ),
        .clkEnable  ( clkEnable ),
        .clk        ( clk       ),
        .regAddr    ( 4'b0010   ),
        .regData    ( regData   )
    );

    //outputs
    assign LED[0]   = clk;
    assign LED[7:1] = regData[6:0];

    wire [11:0] seven_segments;
    assign IO[12:1] = seven_segments;

    sm_hex_display_digit sm_hex_display_digit(
        .digit1 (digit1),
        .digit2 (digit2),
        .digit3 (digit3),
        .clkIn  (clkIn),
        .seven_segments (seven_segments)
    );

    wire [6:0] digit3;
    wire [6:0] digit2;
    wire [6:0] digit1;

    sm_hex_display digit_02 (regData [3:0], digit3 [6:0]);
    sm_hex_display digit_01 (regData [7:4], digit2 [6:0]);
    sm_hex_display digit_00 (regData [11:8], digit1 [6:0]);

endmodule

module sm_top(
    input           clkIn,
    input           rst_n,
    input  [3:0]    clkDevide,
    input           clkEnable,
    output          clk,
    input  [3:0]    regAddr,
    inout  [31:0]   regData
);

    wire clkDivided;
    assign clkDivided = (clk == clkDevide) ? 1'b1 : 1'b0;

    always @(posedge clkDivided or negedge rst_n) begin
        if (~rst_n) begin
            clk <= 1'b0;
        end else if (clkEnable) begin
            clk <= ~clk;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            regData <= 0;
        end else begin
            case(regAddr)
                4'b0000: regData[7:0]    <= regData[15:8];
                4'b0001: regData[15:8]   <= regData[23:16];
                4'b0010: regData[23:16]  <= regData[31:24];
                default: regData <= regData;
            endcase
        end
    end

endmodule

module sm_hex_display(
    input  [3:0]    data,
    output [6:0]    segments
);

    assign segments = (data == 4'h0)    ? 7'b1000000 :
                      (data == 4'h1)    ? 7'b1111001 :
                      (data == 4'h2)    ? 7'b0100100 :
                      (data == 4'h3)    ? 7'b0110000 :
                      (data == 4'h4)    ? 7'b0011001 :
                      (data == 4'h5)    ? 7'b0010010 :
                      (data == 4'h6)    ? 7'b0000010 :
                      (data == 4'h7)    ? 7'b1111000 :
                      (data == 4'h8)    ? 7'b0000000 :
                      (data == 4'h9)    ? 7'b0011000 :
                      (data == 4'ha)    ? 7'b0001000 :
                      (data == 4'hb)    ? 7'b0000011 :
                      (data == 4'hc)    ? 7'b0100111 :
                      (data == 4'hd)    ? 7'b0100001 :
                      (data == 4'he)    ? 7'b0000110 :
                      (data == 4'hf)    ? 7'b0001110 :
                      7'b1111111;

endmodule

module sm_hex_display_digit(
    input  [6:0]    digit1,
    input  [6:0]    digit2,
    input  [6:0]    digit3,
    input           clkIn,
    output [11:0]   seven_segments
);

    reg [1:0] digitSelector;

    sm_hex_display sm_hex_display_1(
        .data     (digit1),
        .segments (seven_segments[3:0])
    );

    sm_hex_display sm_hex_display_2(
        .data     (digit2),
        .segments (seven_segments[7:4])
    );

    sm_hex_display sm_hex_display_3(
        .data     (digit3),
        .segments (seven_segments[11:8])
    );

    always @(posedge clkIn) begin
        digitSelector <= (digitSelector == 2'b11) ? 2'b00 :
                         digitSelector + 2'b01;
    end

    assign seven_segments = (digitSelector == 2'b00) ? seven_segments :
                            (digitSelector == 2'b01) ? {7'b0000000, seven_segments[11:4]} :
                            (digitSelector == 2'b10) ? {7'b0000000, seven_segments[7:0]} :
                            seven_segments;

endmodule

module sky130_fd_sc_hd__nor3 (input A, input B, input C, input VPWR, input VGND, input VPB, input VNB, output Y);
    wire nand1, nand2, nand3;

    // Implement NOR3 using NAND gates
    sky130_fd_sc_hd__nand2 n1 (.A(A), .B(A), .Y(nand1));
    sky130_fd_sc_hd__nand2 n2 (.A(B), .B(B), .Y(nand2));
    sky130_fd_sc_hd__nand2 n3 (.A(C), .B(C), .Y(nand3));
    sky130_fd_sc_hd__nand2 n4 (.A(nand1), .B(nand2), .Y(Y));
    sky130_fd_sc_hd__nand2 n5 (.A(nand3), .B(Y), .Y(Y));
    sky130_fd_sc_hd__nand2 n6 (.A(VPWR), .B(VGND), .Y(Y));
    sky130_fd_sc_hd__nand2 n7 (.A(VPB), .B(VNB), .Y(Y));

    // Assign output to x if any input is x
    assign Y = (A == 1'b0 && B == 1'b0 && C == 1'b0) ? 1'b1 :
              (A == 1'bx || B == 1'bx || C == 1'bx || VPWR == 1'bx || VGND == 1'bx || VPB == 1'bx || VNB == 1'bx) ? 1'bx :
              Y;

endmodule

module UART_fifo_interface #(parameter bits_depth=4)(
    input write_flag,
    input read_next,
    input [7:0] data_in,
    input clock,
    input reset,
    output reg [7:0] data_out,
    output reg empty_flag,
    output reg full_flag
);

    localparam depth = 1 << bits_depth;
    reg [7:0] FIFO [depth-1:0];
    reg [bits_depth-1:0] read_pointer, write_pointer;
    reg [bits_depth:0] free_space;

    always @* begin
        full_flag = (free_space == 0);
        empty_flag = (free_space == depth);
        data_out <= FIFO[read_pointer];
    end

    always @(posedge clock, posedge reset) begin
        if (reset) begin
            write_pointer <= 0;
            read_pointer <= 0;
            free_space <= depth;
        end
        else begin
            if (read_next) begin
                if (!empty_flag) begin
                    read_pointer <= read_pointer + 1;
                    free_space <= free_space + 1;
                end
            end
            if (write_flag) begin
                FIFO[write_pointer] <= data_in;
                write_pointer <= write_pointer + 1;
                if (!full_flag) begin
                    free_space <= free_space - 1;
                end
                else if (!empty_flag) begin
                    read_pointer <= read_pointer + 1;
                end
            end
        end
    end

endmodule

module and_gate_with_enable (
    in1,
    in2,
    in3,
    in4,
    en,
    out
);

  input [3:0] in1, in2, in3, in4;
  input en;
  output reg out;

  always @ (*) begin
    if (en) begin
      out = (in1 & in2 & in3 & in4);
    end else begin
      out = 1'b0;
    end
  end

endmodule

module bitwise_mux ( 
    input [2:0] sel, 
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output [11:0] out   
);

    reg [3:0] mux_out;
    reg [3:0] bitwise_out;
    reg [3:0] and_out;
    reg [3:0] or_out;
    reg [3:0] xor_out;

    always @(*) begin
        case (sel)
            3'b000: mux_out = data0;
            3'b001: mux_out = data1;
            3'b010: mux_out = data2;
            3'b011: mux_out = data3;
            3'b100: mux_out = data4;
            3'b101: mux_out = data5;
            default: mux_out = 4'b0000;
        endcase

        if (sel % 2 == 0) begin
            and_out = mux_out & 4'b1111;
            or_out = 4'b1111;
        end else begin
            and_out = 4'b1111;
            or_out = mux_out | 4'b11110000;
        end

        case (sel)
            3'b000: begin
                xor_out = and_out ^ or_out;
            end
            3'b001: begin
                xor_out = and_out & or_out;
            end
            3'b010: begin
                xor_out = and_out | or_out;
            end
            default: begin
                xor_out = 4'b0000;
            end
        endcase

        bitwise_out = {and_out, or_out, xor_out};
    end

    assign out = bitwise_out;

endmodule

module shift_register (
    input clk,
    input [15:0] serial_in,
    input shift_direction,
    output [15:0] serial_out
);

    reg [15:0] register;

    always @(posedge clk) begin
        if (shift_direction) begin
            register <= {register[14:0], serial_in};
        end else begin
            register <= {serial_in, register[15:1]};
        end
    end

    assign serial_out = register;

endmodule

module hcsr04 #(
	parameter TRIGGER_DURATION = 500,
	parameter MAX_COUNT = 3000000
)(
	input rst,
	input clk,
	input tclk,
	input measure,
	input echo,

	output reg [15:0] ticks,
	output reg valid,
	output reg trigger
);

localparam STATE_SIZE = 3,
	CTR_SIZE = 16;
localparam STATE_RESET = 3'd0,
	STATE_IDLE = 3'd1,
	STATE_TRIGGER = 3'd2,
	STATE_COUNT = 3'd3,
	STATE_COOLDOWN = 3'd4;

reg [CTR_SIZE-1:0] ctr_d, ctr_q;
reg [STATE_SIZE-1:0] state_d, state_q;
reg [15:0] ticks_d;
reg trigger_d, valid_d;
reg echo_old;

reg echo_chg, echo_pos, echo_neg;

always @(*) begin
	echo_chg = echo_old ^ echo;
	echo_pos = echo_chg & echo;
	echo_neg = echo_chg & (~echo);
	ctr_d = ctr_q;
	state_d = state_q;
	trigger_d = 0;
	valid_d = valid;
	ticks_d = ticks;

	case (state_q)
		STATE_RESET: begin
			ctr_d = 0;
			valid_d = 0;
			ticks_d = 0;
			state_d = STATE_IDLE;
		end
		STATE_IDLE: begin
			ctr_d = 0;
			if(measure) begin
				state_d = STATE_TRIGGER;
			end else begin
				state_d = STATE_IDLE;
			end
		end
		STATE_TRIGGER: begin
			if(tclk) begin
				ctr_d = ctr_q + 1;
			end
			trigger_d = 1'b1;
			if(ctr_q == TRIGGER_DURATION) begin
				state_d = STATE_COUNT;
			end
		end
		STATE_COUNT: begin
			if(tclk) begin
				ctr_d = ctr_q + 1;
			end
			if(ctr_q == MAX_COUNT) begin
				ticks_d = MAX_COUNT;
				state_d = STATE_IDLE;
			end else if(echo_neg) begin
				ticks_d = ctr_q;
				valid_d = 1'b1;
				state_d = STATE_IDLE;
			end else if(echo_pos) begin
				ctr_d = 0;
			end
		end
	endcase
end

always @(posedge clk) begin
	if (rst) begin
		state_q <= STATE_RESET;
		ctr_q   <= 0;
		ticks   <= 0;
		valid   <= 0;
		trigger <= 0;
		echo_old <= 0;
	end else begin
		state_q <= state_d;
		ctr_q   <= ctr_d;
		ticks   <= ticks_d;
		valid   <= valid_d;
		trigger <= trigger_d;
		echo_old <= echo;
	end
end 

endmodule

module vending_machine(
    input [1:0] coin,
    input reset,
    output dispense,
    output reg [1:0] change
);

reg [5:0] total_amount;

always @(*) begin
    if(reset) begin
        total_amount <= 0;
        change <= 0;
        dispense <= 0;
    end else begin
        total_amount <= total_amount + {1'b0, coin};
        if(total_amount >= 6'b1010) begin
            dispense <= 1;
            change <= total_amount - 6'b1010;
            total_amount <= 0;
        end else begin
            dispense <= 0;
        end
    end
end

endmodule

module TDC (
  input pulse1,
  input pulse2,
  output reg [7:0] tdc_out
);

parameter fs = 100000000; // sampling frequency of the circuit
parameter dt = 10; // conversion time of the TDC in nanoseconds

reg [31:0] timer;
reg pulse1_detected;
reg pulse2_detected;

always @(posedge pulse1) begin
  pulse1_detected <= 1;
  timer <= 0;
end

always @(posedge pulse2) begin
  pulse2_detected <= 1;
  tdc_out <= timer / (fs*dt);
end

always @(posedge clk) begin
  if (pulse1_detected) begin
    timer <= timer + 1;
  end
  if (pulse2_detected) begin
    pulse1_detected <= 0;
    pulse2_detected <= 0;
  end
end

endmodule

module LOGIC (QST, QDS, TBS, TAB, TSL, TA1, TA2, TB1, TB2, BAB, BSL, BA1, BA2, BB1, BB2, QDI, QEN, QCK, QRT, F1, F2, FS, TZ, CZ, QZ, FZ, FAKE_CONST);
    input wire QST;
    input wire QDS;
    input wire TBS;
    input wire TAB;
    input wire TSL;
    input wire TA1;
    input wire TA2;
    input wire TB1;
    input wire TB2;
    input wire BAB;
    input wire BSL;
    input wire BA1;
    input wire BA2;
    input wire BB1;
    input wire BB2;
    input wire QDI;
    input wire QEN;
    input wire QCK;
    input wire QRT;
    input wire F1;
    input wire F2;
    input wire FS;
    output wire TZ;
    output wire CZ;
    output wire QZ;
    output wire FZ;

    // This is a synthetic pin that can be connected to the global const
    // network bypassing the switchbox.
    input wire FAKE_CONST;

    parameter MODE = "MACRO";

    // LOGIC macro
    generate if (MODE == "MACRO") begin

        (* FASM_PREFIX="LOGIC.LOGIC" *)
        LOGIC_MACRO logic_macro (
        .TBS(TBS),
        .TAB(TAB),
        .TSL(TSL),
        .TA1(TA1),
        .TA2(TA2),
        .TB1(TB1),
        .TB2(TB2),
        .BAB(BAB),
        .BSL(BSL),
        .BA1(BA1),
        .BA2(BA2),
        .BB1(BB1),
        .BB2(BB2),
        .TZ (TZ),
        .CZ (CZ),

        .QCK(QCK),
        .QST(QST),
        .QRT(QRT),
        .QEN(QEN),
        .QDI(QDI),
        .QDS(QDS),
        .QZ (QZ),

        .F1 (F1),
        .F2 (F2),
        .FS (FS),
        .FZ (FZ)
        );

    // LOGIC split into fragments
    end else if (MODE == "FRAGS") begin

        // The C-Frag (with modes)
        (* FASM_PREFIX="LOGIC.LOGIC" *)
        C_FRAG_MODES c_frag_modes (
        .TBS(TBS),
        .TAB(TAB),
        .TSL(TSL),
        .TA1(TA1),
        .TA2(TA2),
        .TB1(TB1),
        .TB2(TB2),
        .BAB(BAB),
        .BSL(BSL),
        .BA1(BA1),
        .BA2(BA2),
        .BB1(BB1),
        .BB2(BB2),
        .TZ (TZ),
        .CZ (CZ)
        );

        // The Q-Frag (with modes)
        (* FASM_PREFIX="LOGIC.LOGIC" *)
        Q_FRAG_MODES q_frag_modes (
        .QCK(QCK),
        .QST(QST),
        .QRT(QRT),
        .QEN(QEN),
        .QDI(QDI),
        .QDS(QDS),
        .CZI(CZ),
        .QZ (QZ),

        .FAKE_CONST (FAKE_CONST)
        );

        // The F-Frag
        F_FRAG f_frag (
        .F1 (F1),
        .F2 (F2),
        .FS (FS),
        .FZ (FZ)
        );

    end endgenerate

endmodule

module nfc_transmitter (
  input [n-1:0] data,
  output carrier
);

parameter n = 8; // number of data bits
wire clk;
reg [n-1:0] encoded_data;
integer i;

// Clock generation
always begin
  #5 clk = ~clk;
end

// ASK modulation
always @(posedge clk) begin
  for (i = 0; i < n; i = i + 1) begin
    encoded_data[i] <= data[i] ? ~clk : clk;
  end
end

assign carrier = encoded_data[n-1];

endmodule

module nfc_receiver (
  input carrier,
  output [n-1:0] data
);

parameter n = 8; // number of data bits
wire clk;
reg [n-1:0] decoded_data;
integer i;

// Clock recovery
always @(carrier) begin
  if (carrier) begin
    #5 clk = ~clk;
  end
end

// ASK demodulation
always @(posedge clk) begin
  for (i = 0; i < n; i = i + 1) begin
    decoded_data[i] <= (carrier == ~clk) ? 1 : 0;
  end
end

assign data = decoded_data;

endmodule

module mux4x1 (
    input [1:0] sel,
    input [3:0] din,
    output reg dout
);

always @(*) begin
    case(sel)
        2'b00: dout = din[0];
        2'b01: dout = din[1];
        2'b10: dout = din[2];
        2'b11: dout = din[3];
    endcase
end

endmodule

module FSM (
  input clk,
  input rst,
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 4; // number of input signals
parameter m = 2; // number of output signals
parameter ns = 4; // number of states in the original FSM
parameter ne = 8; // number of states in the converted FSM

reg [ns-1:0] state_orig; // current state of the original FSM
reg [ne-1:0] state_conv; // current state of the converted FSM
reg [ne-1:0] next_state; // next state of the converted FSM

// State encoding converter
always @(*) begin
  case(state_orig)
    0: state_conv = 0;
    1: state_conv = 1;
    2: state_conv = 3;
    3: state_conv = 2;
    default: state_conv = 0;
  endcase
end

// State transition table
always @(posedge clk, posedge rst) begin
  if (rst) begin
    state_orig <= 0;
    next_state <= 0;
  end else begin
    state_orig <= next_state[1:0];
    case(state_conv)
      0: next_state <= {in[0], in[1]};
      1: next_state <= {in[2], in[3]};
      2: next_state <= {in[1], in[2]};
      3: next_state <= {in[0], in[3]};
      4: next_state <= {in[0], in[1]};
      5: next_state <= {in[2], in[3]};
      6: next_state <= {in[1], in[2]};
      7: next_state <= {in[0], in[3]};
      default: next_state <= 0;
    endcase
  end
end

// Output table
always @(*) begin
  case(state_conv)
    0: out <= {1'b0, 1'b0};
    1: out <= {1'b0, 1'b1};
    2: out <= {1'b1, 1'b0};
    3: out <= {1'b1, 1'b1};
    4: out <= {1'b0, 1'b0};
    5: out <= {1'b0, 1'b1};
    6: out <= {1'b1, 1'b0};
    7: out <= {1'b1, 1'b1};
    default: out <= {1'b0, 1'b0};
  endcase
end

endmodule

