module top_module( 
    input [1023:0] in,
    input [7:0] sel,
    output [3:0] out );

    // Define internal wires and signals
    wire [127:0] mux_out [7:0];
    wire [2:0] sel_decoded [7:0];
    wire [3:0] out_mux;

    // Instantiate 8-to-1 multiplexers
    mux_8to1 mux_0(.in(in[127:0]), .sel(sel_decoded[0]), .out(mux_out[0]));
    mux_8to1 mux_1(.in(in[255:128]), .sel(sel_decoded[1]), .out(mux_out[1]));
    mux_8to1 mux_2(.in(in[383:256]), .sel(sel_decoded[2]), .out(mux_out[2]));
    mux_8to1 mux_3(.in(in[511:384]), .sel(sel_decoded[3]), .out(mux_out[3]));
    mux_8to1 mux_4(.in(in[639:512]), .sel(sel_decoded[4]), .out(mux_out[4]));
    mux_8to1 mux_5(.in(in[767:640]), .sel(sel_decoded[5]), .out(mux_out[5]));
    mux_8to1 mux_6(.in(in[895:768]), .sel(sel_decoded[6]), .out(mux_out[6]));
    mux_8to1 mux_7(.in(in[1023:896]), .sel(sel_decoded[7]), .out(mux_out[7]));

    // Instantiate binary decoder
    binary_decoder decoder(.in(sel), .out(sel_decoded));

    // Combine outputs of 8-to-1 multiplexers
    assign out_mux = {mux_out[7], mux_out[6], mux_out[5], mux_out[4], mux_out[3], mux_out[2], mux_out[1], mux_out[0]};

    // Output final 4-bit value
    assign out = out_mux[3:0];

endmodule

