module top_module (
    input clk,
    input reset,   // Synchronous active-high reset
    input load,    // Load value into counter when asserted
    input up_down, // Count up or down based on value
    input [31:0] in, // Input vector for the transition detector
    output [7:0] q // 8-bit output from the functional module
);

    // Counter module with parallel load and up/down counting
    reg [15:0] count;
    always @(posedge clk) begin
        if (reset) begin
            count <= 0;
        end else if (load) begin
            count <= {in[15:12], in[23:20], in[31:28], in[27:24]};
        end else if (up_down) begin
            count <= count + 1;
        end else begin
            count <= count - 1;
        end
    end

    // Transition detector module using FSM architecture
    reg [31:0] prev_in;
    reg [31:0] transition;
    parameter IDLE = 2'b00;
    parameter DETECT = 2'b01;
    parameter OUTPUT = 2'b10;
    reg [1:0] state;
    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            prev_in <= 0;
            transition <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (in != prev_in) begin
                        state <= DETECT;
                        prev_in <= in;
                    end
                end
                DETECT: begin
                    if (in == prev_in) begin
                        state <= IDLE;
                        transition <= transition | prev_in;
                    end else begin
                        prev_in <= in;
                    end
                end
                OUTPUT: begin
                    state <= IDLE;
                    prev_in <= in;
                end
            endcase
        end
    end

    // Functional module to combine counter and transition detector outputs
    assign q = {count[3:0], count[7:4], count[11:8], count[15:12], transition[31:24], transition[23:16], transition[15:8], transition[7:0]};

endmodule

module dff_negedge_async_set_reset(CLK, D, RST, Q);
    input CLK;
    input D;
    input RST;
    output Q;

    reg Q_next;

    always @(negedge CLK) begin
        if (RST == 1'b0) begin
            Q_next <= 1'b0;
        end else begin
            Q_next <= D;
        end
    end

    assign Q = Q_next;

endmodule

module circular_buffer (
    input CLK,
    input RESET,
    input WRITE_EN,
    input READ_EN,
    input [7:0] DATA_IN,
    output [7:0] DATA_OUT,
    output EMPTY,
    output FULL
);

    parameter DEPTH = 64;

    reg [7:0] buffer [0:DEPTH-1];
    reg [5:0] read_ptr;
    reg [5:0] write_ptr;
    reg [5:0] count;

    assign EMPTY = (count == 0);
    assign FULL = (count == DEPTH);

    always @(posedge CLK) begin
        if (RESET) begin
            read_ptr <= 0;
            write_ptr <= 0;
            count <= 0;
        end
        else begin
            if (WRITE_EN && !FULL) begin
                buffer[write_ptr] <= DATA_IN;
                write_ptr <= write_ptr + 1;
                count <= count + 1;
                if (write_ptr == DEPTH) begin
                    write_ptr <= 0;
                end
            end

            if (READ_EN && !EMPTY) begin
                DATA_OUT <= buffer[read_ptr];
                read_ptr <= read_ptr + 1;
                count <= count - 1;
                if (read_ptr == DEPTH) begin
                    read_ptr <= 0;
                end
            end
        end
    end

endmodule

module calculator(
    input [7:0] num1,
    input [7:0] num2,
    input [1:0] op,
    output reg [7:0] result,
    output reg overflow
);

reg [8:0] temp;

always @* begin
    case (op)
        2'b00: temp = num1 + num2;
        2'b01: temp = num1 - num2;
        2'b10: temp = num1 * num2;
        2'b11: temp = num1 / num2;
    endcase

    if (op == 2'b00 || op == 2'b10) begin
        if (temp > 255) begin
            overflow = 1;
            result = 255;
        end else begin
            overflow = 0;
            result = temp[7:0];
        end
    end else begin
        if (temp[8] == 1) begin
            overflow = 1;
            result = 0;
        end else begin
            overflow = 0;
            result = temp[7:0];
        end
    end
end

endmodule

module uparc_fwdu(
    rs,
    rs_data,
    rt,
    rt_data,
    rd_p2,
    rd_data_p2,
    pend_mem_load_p2,
    rd_p3,
    rd_data_p3,
    rs_data_p1,
    rt_data_p1
);
/* rs and rt read at decode stage */
input wire [`UPARC_REGNO_WIDTH-1:0] rs;
input wire [`UPARC_REG_WIDTH-1:0] rs_data;
input wire [`UPARC_REGNO_WIDTH-1:0] rt;
input wire [`UPARC_REG_WIDTH-1:0] rt_data;
/* Destination at execute stage */
input wire [`UPARC_REGNO_WIDTH-1:0] rd_p2;
input wire [`UPARC_REG_WIDTH-1:0] rd_data_p2;
/* Pending memory load */
input wire pend_mem_load_p2;
/* Destination at memory stage */
input wire [`UPARC_REGNO_WIDTH-1:0] rd_p3;
input wire [`UPARC_REG_WIDTH-1:0] rd_data_p3;
/* Forwarded values of rs and rt */
output reg [`UPARC_REG_WIDTH-1:0] rs_data_p1;
output reg [`UPARC_REG_WIDTH-1:0] rt_data_p1;

always @(*) begin
    if (rs == rd_p2) begin
        rs_data_p1 = rd_data_p2;
    end else if (rs == rd_p3) begin
        rs_data_p1 = rd_data_p3;
    end else begin
        rs_data_p1 = rs_data;
    end
end

always @(*) begin
    if (rt == rd_p2 && !pend_mem_load_p2) begin
        rt_data_p1 = rd_data_p2;
    end else if (rt == rd_p3) begin
        rt_data_p1 = rd_data_p3;
    end else begin
        rt_data_p1 = rt_data;
    end
end

endmodule

module UART_Receiver #(
    parameter N    = 5,
    parameter Full = 5'd29 // Clk / BAUD - 1
)(
    input Clk,
    input Reset,
    output reg [7:0]Data,
    output reg Ready,
    input Ack,
    input Rx
);

reg tRx;
reg tAck;
reg [7:0]Temp;
reg [N-1:0]Count;
reg [2:0]BitCount;
reg NewData;

reg [1:0]State;
localparam Idle      = 2'b00;
localparam StartBit  = 2'b01;
localparam Receiving = 2'b11;
localparam Done      = 2'b10;

reg tReset;

always @(posedge Clk) begin
    tRx    <= Rx;
    tAck   <= Ack;
    tReset <= Reset;

    if (tReset | tAck) begin
        Data    <= 0;
        Ready   <= 0;
        NewData <= 0;
        Count   <= 0;
        State   <= Idle;
    end else begin
        if (Ready & tAck) Ready <= 1'b0;

        case (State)
            Idle: begin
                if (~tRx) begin
                    Count <= {1'b0, Full[N-1:1]};
                    State <= StartBit;
                end

                if (NewData & ~tAck && ~Ready) begin
                    Data    <= Temp;
                    Ready   <= 1'b1;
                    NewData <= 1'b0;
                    Count   <= 1'b0;
                end
            end

            Done: begin
                if (tRx) State <= Idle;
            end

            default:;
        endcase

        if (~|Count) begin
            case (State)
                StartBit: begin
                    if (Rx) begin
                        State <= Idle;
                    end else begin
                        BitCount <= 0;
                        Count    <= Full;
                        State    <= Receiving;
                    end
                end

                Receiving: begin
                    Temp  <= {tRx, Temp[7:1]};
                    Count <= Full;

                    if (&BitCount) begin
                        NewData <= 1'b1;
                        State   <= Done;
                    end

                    BitCount <= BitCount + 1'b1;
                end

                default:;
            endcase
        end else begin
            Count <= Count - 1'b1;
        end
    end
end

endmodule

module ADCInterface(
    input clk,
    input resetn,
    input CPOL,
    input CPHA,
    input ss,
    input [15:0] dataIn,
    output [13:0] dataOut,
    output finishedCycling,
    output loadedData
);

    wire [5:0] counter;
    wire Des_en, Ser_en;
    wire inboxLineInA, inboxLineInB, outboxLineOut;
    wire [15:0] outboxQ;
    wire registerSignal;

    assign loadedData = (outboxQ == dataIn) ? 1'b1 : 1'b0;

    Six_Bit_Counter_Enable_Async PocketWatch(
        .clk(clk),
        .resetn(resetn & ~ss),
        .enable(~ss & ~(counter[5] & ~counter[4] & ~counter[3] & ~counter[2] & ~counter[1] & counter[0])),
        .q(counter)
    );

    SCLKMaker TimeLord(
        .Clk(clk),
        .S(ss),
        .CPOL(CPOL),
        .SCLK(SCLK)
    );

    SPIRSMaker Level(
        .CPHA(CPHA),
        .CPOL(CPOL),
        .RS(registerSignal)
    );

    Shift_Register_16_Enable_Async_Muxed OutBox(
        .clk(~(clk ^ registerSignal)),
        .resetn(resetn),
        .enable(Ser_en),
        .select(counter[0]),
        .d(dataIn),
        .q(outboxQ)
    );

    Shift_Register_14_Enable_Async InBoxA(
        .clk(~(clk ^ registerSignal)),
        .resetn(resetn),
        .enable(Des_en),
        .d(inboxLineInA),
        .q(dataOut[13:0])
    );

    Shift_Register_14_Enable_Async InBoxB(
        .clk(~(clk ^ registerSignal)),
        .resetn(resetn),
        .enable(Des_en),
        .d(inboxLineInB),
        .q(dataOut[13:0])
    );

    TriStateBuffer_2_1bit BorderGuardOut(
        .In(outboxLineOut),
        .Select(Ser_en),
        .Out(MOSI)
    );

    TriStateBuffer_2_1bit BorderGuardInA(
        .In(MISOA),
        .Select(Des_en),
        .Out(inboxLineInA)
    );

    TriStateBuffer_2_1bit BorderGuardInB(
        .In(MISOB),
        .Select(Des_en),
        .Out(inboxLineInB)
    );

    assign finishedCycling = counter[5];

    assign Ser_en = ~counter[5] & ~counter[4];
    assign Des_en = (~counter[5] & counter[4] & (counter[3] | counter[2] | counter[1] & counter[0])) | (counter[5] & ~counter[4] & ~counter[3] & ~counter[2] & ~counter[1] & ~counter[0]);

    assign outboxLineOut = outboxQ[15];

endmodule

