module rotator (
    input clk,
    input reset,
    input [7:0] d,
    input load,
    input [1:0] ena,
    output reg [7:0] q
);

    reg [7:0] shift_reg;

    always @(posedge clk, posedge reset) begin
        if (reset) begin
            shift_reg <= 8'b0;
        end else begin
            if (load) begin
                shift_reg <= d;
            end else begin
                if (ena == 2'b01) begin
                    shift_reg <= {shift_reg[6:0], shift_reg[7]};
                end else if (ena == 2'b10) begin
                    shift_reg <= {shift_reg[0], shift_reg[7:1]};
                end
            end
        end
    end

    assign q = shift_reg;

endmodule

