module vending_machine (
    input clk,
    input reset,
    input coin,
    input product_75,
    input product_100,
    output dispense,
    output [3:0] change
);

// Define states
parameter [2:0] IDLE = 3'b000;
parameter [2:0] ACCEPTING_5 = 3'b001;
parameter [2:0] ACCEPTING_10 = 3'b010;
parameter [2:0] ACCEPTING_25 = 3'b011;
parameter [2:0] ACCEPTING_100 = 3'b100;
parameter [2:0] DISPENSING_75 = 3'b101;
parameter [2:0] DISPENSING_100 = 3'b110;

// Define inputs
reg coin_input;
reg product_75_input;
reg product_100_input;

// Define outputs
reg dispense_output;
reg [3:0] change_output;

// Define state register and next state logic
reg [2:0] state;
always @(posedge clk, posedge reset) begin
    if (reset) begin
        state <= IDLE;
    end else begin
        case (state)
            IDLE: begin
                if (product_75_input) begin
                    state <= ACCEPTING_75;
                end else if (product_100_input) begin
                    state <= ACCEPTING_100;
                end else if (coin_input) begin
                    state <= ACCEPTING_5;
                end
            end
            ACCEPTING_5: begin
                if (coin_input) begin
                    state <= ACCEPTING_10;
                end
            end
            ACCEPTING_10: begin
                if (coin_input) begin
                    state <= ACCEPTING_25;
                end
            end
            ACCEPTING_25: begin
                if (coin_input) begin
                    state <= ACCEPTING_100;
                end
            end
            ACCEPTING_100: begin
                if (coin_input) begin
                    state <= ACCEPTING_100;
                end else if (product_75_input) begin
                    state <= DISPENSING_75;
                end else if (product_100_input) begin
                    state <= DISPENSING_100;
                end
            end
            DISPENSING_75: begin
                state <= IDLE;
            end
            DISPENSING_100: begin
                state <= IDLE;
            end
        endcase
    end
end

// Define state output logic
always @(state) begin
    case (state)
        IDLE: begin
            dispense_output = 0;
        end
        ACCEPTING_5, ACCEPTING_10, ACCEPTING_25, ACCEPTING_100: begin
            dispense_output = 0;
        end
        DISPENSING_75, DISPENSING_100: begin
            dispense_output = 1;
        end
    endcase
end

// Define change output logic
always @(state) begin
    case (state)
        IDLE, ACCEPTING_5, ACCEPTING_10, ACCEPTING_25: begin
            change_output = 0;
        end
        ACCEPTING_100: begin
            if (product_75_input) begin
                change_output = 25;
            end else if (product_100_input) begin
                change_output = 0;
            end else begin
                change_output = 0;
            end
        end
        DISPENSING_75: begin
            change_output = 0;
        end
        DISPENSING_100: begin
            change_output = 0;
        end
    endcase
end

// Define input assignments
assign coin_input = coin;
assign product_75_input = product_75;
assign product_100_input = product_100;

// Define output assignments
assign dispense = dispense_output;
assign change = change_output;

endmodule

