module sequence_detector(
    input wire [9:0] is_requested,
    input wire [9:0] request_clear,
    input wire [9:0] switches,
    input wire clock,
    output reg [2:0] leds,
    output reg [3:0] request_floor,
    output reg up
);

    reg [2:0] current_floor = 0;
    reg [9:0] sequence_detected = 0;

    always @(posedge clock) begin
        if (request_clear == 1) begin
            sequence_detected <= 0;
        end
        else begin
            if (is_requested != 0) begin
                if (is_requested[0] == 1) begin
                    leds[0] <= 1;
                    request_floor <= 0;
                    if (current_floor > 0) begin
                        up <= 0;
                    end
                end
                else begin
                    leds[0] <= 0;
                end

                if (is_requested[1] == 1) begin
                    leds[1] <= 1;
                    request_floor <= 1;
                    if (current_floor > 1) begin
                        up <= 0;
                    end
                    else begin
                        up <= 1;
                    end
                end
                else begin
                    leds[1] <= 0;
                end

                if (is_requested[2] == 1) begin
                    leds[2] <= 1;
                    request_floor <= 2;
                    if (current_floor > 2) begin
                        up <= 0;
                    end
                    else begin
                        up <= 1;
                    end
                end
                else begin
                    leds[2] <= 0;
                end

                if (is_requested[3] == 1 && sequence_detected[0] == 1) begin
                    sequence_detected <= sequence_detected >> 1;
                    sequence_detected[3] <= 1;
                end
                else begin
                    sequence_detected <= 0;
                end

                if (is_requested[4] == 1 && sequence_detected[1] == 1) begin
                    sequence_detected <= sequence_detected >> 1;
                    sequence_detected[3] <= 1;
                end
                else begin
                    sequence_detected <= 0;
                end

                if (is_requested[5] == 1 && sequence_detected[2] == 1) begin
                    sequence_detected <= sequence_detected >> 1;
                    sequence_detected[3] <= 1;
                end
                else begin
                    sequence_detected <= 0;
                end

                if (is_requested[6] == 1 && sequence_detected[3] == 1) begin
                    leds[3] <= 1;
                end
                else begin
                    leds[3] <= 0;
                end

                if (is_requested[7] == 1) begin
                    leds[4] <= 1;
                end
                else begin
                    leds[4] <= 0;
                end

                if (is_requested[8] == 1) begin
                    leds[5] <= 1;
                end
                else begin
                    leds[5] <= 0;
                end

                if (is_requested[9] == 1) begin
                    leds[6] <= 1;
                end
                else begin
                    leds[6] <= 0;
                end

                current_floor <= switches[2:0];
            end
            else begin
                if (current_floor < 5) begin
                    request_floor <= 0;
                    up <= 0;
                end
                else begin
                    request_floor <= 9;
                    up <= 1;
                end
            end
        end
    end

endmodule

module uart_fifo (
  clk,
  rst,

  size,

  write_strobe,
  write_available,
  write_data,

  read_strobe,
  read_count,
  read_data,

  overflow,
  underflow,

  full,
  empty
);

//parameters
parameter           FIFO_SIZE       = 10;


input                           clk;
input                           rst;

output  wire  [31:0]            size;

input                           write_strobe;
output  wire  [31:0]            write_available;
input         [7:0]             write_data;

input                           read_strobe;
output  reg   [31:0]            read_count;
output  wire  [7:0]             read_data;

output  reg                     overflow;
output  reg                     underflow;

output                          full;
output                          empty;


//Wires, Registers
reg         [FIFO_SIZE - 1: 0]  in_pointer;
reg         [FIFO_SIZE - 1: 0]  out_pointer;


dual_port_bram #(
  .DATA_WIDTH(8),
  .ADDR_WIDTH(FIFO_SIZE),
  .MEM_FILE("NOTHING"),
  .MEM_FILE_LENGTH(0)
) mem (
  .a_clk(clk),
  .a_wr(write_strobe),
  .a_addr(in_pointer),
  .a_din(write_data),

  .b_clk(clk),
  .b_wr(1'b0),
  .b_addr(out_pointer),
  .b_din(8'h0),
  .b_dout(read_data)
);

//synthesis attribute ram_style of mem is block
wire        [FIFO_SIZE - 1: 0]  last;

//Asynchronous Logic
assign                          size            =  1 << FIFO_SIZE;
assign                          last            = (out_pointer - 1);
assign                          full            = (in_pointer == last);
assign                          empty           = (read_count == 0);
assign                          write_available = size - read_count;

integer                         i;

//Synchronous Logic
always @ (posedge clk) begin
  if (rst) begin
    read_count        <=  0;
    in_pointer        <=  0;
    out_pointer       <=  0;

    overflow          <=  0;
    underflow         <=  0;

  end
  else begin
    overflow          <=  0;
    underflow         <=  0;

    if (write_strobe) begin
      if (full && !read_strobe) begin
        //overflow
        $display ("UART CONTROLLER: Overflow condition");
        out_pointer         <=  out_pointer + 1;
        overflow            <=  1;
      end
      else begin
        //not overflow
        if (!read_strobe) begin
          read_count          <=  read_count + 1;
        end
      end
      in_pointer            <=  in_pointer + 1;
    end

    if (read_strobe) begin
      if (empty) begin
        //empty
        underflow           <=  1;
      end
      else begin
        if (full && write_strobe) begin
          //check for that very rare condition where the write strobe and the read strobe is begin used at the same time
          //and the FIFO is full
          overflow          <=  0;
        end
        else begin
          if (!write_strobe) begin
            read_count        <=  read_count - 1;
          end
          out_pointer       <=  out_pointer + 1;
        end
      end
    end
  end
end

endmodule

