module SRL_FIFO (
  input CLK,
  input RST_N,
  input CLR,
  input ENQ,
  input DEQ,
  input [127:0] D_IN,
  output reg FULL_N,
  output reg EMPTY_N,
  output reg [127:0] D_OUT
);

  parameter depth = 32;

  reg [127:0] data [depth-1:0];
  reg [4:0] head;
  reg [4:0] tail;

  assign FULL_N = (head == tail) ? ~ENQ : 1'b0;
  assign EMPTY_N = (head == tail) ? 1'b1 : 1'b0;

  always @(posedge CLK) begin
    if (!RST_N || CLR) begin
      head <= 5'd0;
      tail <= 5'd0;
      FULL_N <= 1'b0;
      EMPTY_N <= 1'b1;
    end else begin
      if (ENQ && !FULL_N) begin
        data[head] <= D_IN;
        head <= head + 1;
        if (head == tail) begin
          FULL_N <= 1'b1;
        end
        EMPTY_N <= 1'b0;
      end
      if (DEQ && !EMPTY_N) begin
        D_OUT <= data[tail];
        tail <= tail + 1;
        if (tail == head) begin
          EMPTY_N <= 1'b1;
        end
        FULL_N <= 1'b0;
      end
    end
  end

endmodule

