module gpio_interrupt (
  output  reg         o_wbs_int,
  input       [31:0]  gpio_in
);

  localparam			GPIO			            =	32'h00000000;
  localparam			GPIO_OUTPUT_ENABLE		=	32'h00000001;
  localparam			INTERRUPTS		        =	32'h00000002;
  localparam			INTERRUPT_ENABLE	    =	32'h00000003;
  localparam			INTERRUPT_EDGE        =	32'h00000004;

  //gpio registers
  reg			[31:0]	gpio_direction;
  wire    [31:0]  gpio;

  //interrupt registers
  reg			[31:0]	interrupts;
  reg			[31:0]	interrupt_mask;
  reg			[31:0]	interrupt_edge;
  reg					    clear_interrupts;

  assign gpio = interrupts & interrupt_mask;

  always @ (posedge gpio_in) begin
    if (gpio_direction[gpio_in]) begin
      interrupts <= interrupts | gpio_in;
      o_wbs_int <= 1;
    end
  end

  always @ (posedge clear_interrupts) begin
    interrupts <= interrupts & ~interrupt_mask;
    o_wbs_int <= 0;
  end

  always @ (posedge interrupt_edge, posedge interrupt_mask) begin
    interrupts <= (gpio & interrupt_mask) ^ (interrupt_edge & gpio & interrupt_mask);
    o_wbs_int <= interrupts != 0;
  end

  always @ (posedge GPIO_OUTPUT_ENABLE) begin
    gpio_direction <= GPIO_OUTPUT_ENABLE;
  end

  always @ (posedge GPIO) begin
    gpio_direction <= ~GPIO_OUTPUT_ENABLE;
  end

  always @ (posedge INTERRUPT_ENABLE) begin
    interrupt_mask <= INTERRUPT_ENABLE;
  end

  always @ (posedge INTERRUPT_EDGE) begin
    interrupt_edge <= INTERRUPT_EDGE;
  end

endmodule

