module HDMI_transmitter (
  input [23:0] pixel_data,
  input blanking,
  input h_sync,
  input v_sync,
  output [23:0] hdmi_data,
  output hdmi_clk
);

  // Define constants for HDMI timing
  parameter H_SYNC_WIDTH = 44;
  parameter H_BACK_PORCH = 148;
  parameter H_ACTIVE = 1920;
  parameter H_FRONT_PORCH = 88;
  parameter V_SYNC_WIDTH = 5;
  parameter V_BACK_PORCH = 36;
  parameter V_ACTIVE = 1080;
  parameter V_FRONT_PORCH = 4;

  // Define counters for tracking timing
  reg [9:0] h_counter = 0;
  reg [9:0] v_counter = 0;

  // Define state variables for tracking synchronization
  reg [1:0] sync_state = 0;
  reg [1:0] sync_next_state = 0;

  // Define variables for tracking pixel data
  reg [23:0] current_pixel = 0;
  reg [23:0] next_pixel = 0;
  reg [1:0] pixel_state = 0;
  reg [1:0] pixel_next_state = 0;

  // Generate HDMI clock signal
  always @(posedge clk) begin
    hdmi_clk <= ~hdmi_clk;
  end

  // Generate HDMI data stream
  always @(posedge hdmi_clk) begin
    // Update counters
    if (h_counter == H_SYNC_WIDTH + H_BACK_PORCH + H_ACTIVE + H_FRONT_PORCH - 1) begin
      h_counter <= 0;
      v_counter <= v_counter + 1;
    end else begin
      h_counter <= h_counter + 1;
    end

    // Update synchronization state
    sync_state <= sync_next_state;
    case (sync_state)
      0: begin // Vertical sync
        if (v_counter == V_SYNC_WIDTH - 1) begin
          sync_next_state <= 1;
        end else begin
          sync_next_state <= 0;
        end
      end
      1: begin // Vertical back porch
        if (v_counter == V_SYNC_WIDTH + V_BACK_PORCH - 1) begin
          sync_next_state <= 2;
        end else begin
          sync_next_state <= 1;
        end
      end
      2: begin // Vertical active
        if (v_counter == V_SYNC_WIDTH + V_BACK_PORCH + V_ACTIVE - 1) begin
          sync_next_state <= 3;
        end else begin
          sync_next_state <= 2;
        end
      end
      3: begin // Vertical front porch
        if (v_counter == V_SYNC_WIDTH + V_BACK_PORCH + V_ACTIVE + V_FRONT_PORCH - 1) begin
          sync_next_state <= 0;
        end else begin
          sync_next_state <= 3;
        end
      end
    endcase

    // Update pixel data state
    pixel_state <= pixel_next_state;
    case (pixel_state)
      0: begin // Blank
        if (blanking) begin
          pixel_next_state <= 0;
        end else begin
          pixel_next_state <= 1;
          current_pixel <= pixel_data;
        end
      end
      1: begin // Active
        if (h_counter == H_SYNC_WIDTH + H_BACK_PORCH + H_ACTIVE - 1) begin
          pixel_next_state <= 2;
          next_pixel <= pixel_data;
        end else begin
          pixel_next_state <= 1;
        end
      end
      2: begin // Front porch
        if (h_counter == H_SYNC_WIDTH + H_BACK_PORCH + H_ACTIVE + H_FRONT_PORCH - 1) begin
          pixel_next_state <= 1;
          current_pixel <= next_pixel;
        end else begin
          pixel_next_state <= 2;
        end
      end
    endcase

    // Generate HDMI data stream
    case (sync_state)
      0: begin // Vertical sync
        hdmi_data <= 24'h000000;
      end
      1: begin // Vertical back porch
        hdmi_data <= 24'h000000;
      end
      2: begin // Vertical active
        case (pixel_state)
          0: begin // Blank
            hdmi_data <= 24'h000000;
          end
          1: begin // Active
            hdmi_data <= current_pixel;
          end
          2: begin // Front porch
            hdmi_data <= current_pixel;
          end
        endcase
      end
      3: begin // Vertical front porch
        hdmi_data <= 24'h000000;
      end
    endcase
  end

endmodule

module tx (
    clk,
    reset_,
    baud,
    txdata,
    tx_enable,
    tx_ready,	   
    tx);

   input       clk;
   input       reset_;    
   input       baud;       // Baud enable
   input [7:0] txdata;     // Parallel data to transmit
   input       tx_enable;  // When asserted, txdata is sampled for transmission
   output      tx_ready;   // Asserted when transmit complete (ready for next byte)
   output      tx;         // Serial transmit data

   reg 	       tx;
   reg [1:0]   state;
   reg [7:0]   txdata_sampled;
   reg [2:0]   txpos;   

   // Transmitter states
   parameter ST_IDLE    = 2'd0;
   parameter ST_TXSTART = 2'd1;
   parameter ST_TXDATA  = 2'd2;
   parameter ST_TXSTOP  = 2'd3;

   assign tx_ready = state == ST_IDLE;   

   // State machine
   always@ (posedge clk or negedge reset_)
     if (!reset_)
       state <= ST_IDLE;
     else if (state == ST_IDLE && tx_enable)
       state <= ST_TXSTART;
     else if (state == ST_TXSTART && baud)
       state <= ST_TXDATA;
     else if (state == ST_TXDATA && baud && txpos == 3'd7)
       state <= ST_TXSTOP;
     else if (state == ST_TXSTOP && baud)
       state <= ST_IDLE;

   // Serial transmit data
   always@ (posedge clk or negedge reset_)
     if (!reset_)
       tx <= 1'b1;
     else if (state == ST_TXSTART && baud)
       tx <= 1'b0;
     else if (state == ST_TXDATA && baud)
       tx <= txdata_sampled[txpos];
     else if (state == ST_TXSTOP && baud)
       tx <= 1'b1;

   // Transmit position (bit of txdata being sent)
   always@ (posedge clk or negedge reset_)
     if (!reset_)
       txpos <= 3'd0;
     else if (state == ST_IDLE)
       txpos <= 3'd0;     
     else if (state == ST_TXDATA && baud)
       txpos <= txpos + 3'd1;

   // Local copy of txdata
   always@ (posedge clk or negedge reset_)
     if (!reset_)
       txdata_sampled <= 8'h0;
     else if (tx_enable && tx_ready)
       txdata_sampled <= txdata;

endmodule

