module adder8 (
    input [7:0] A,
    input [7:0] B,
    output [7:0] S,
    output C
);

    wire [7:0] sum;
    wire [7:0] carry;

    assign sum[0] = A[0] ^ B[0];
    assign carry[0] = A[0] & B[0];

    genvar i;
    generate
        for (i = 1; i < 8; i = i + 1) begin : adder_loop
            assign sum[i] = A[i] ^ B[i] ^ carry[i-1];
            assign carry[i] = (A[i] & B[i]) | (A[i] & carry[i-1]) | (B[i] & carry[i-1]);
        end
    endgenerate

    assign S = sum;
    assign C = carry[7];

endmodule

module clock_splitter (
    input clk_in,
    input latch_edge,
    output reg clk_out
    );
    reg [1:0] counter;
    reg prev_latch_edge;

    always @(posedge clk_in) begin
        if (prev_latch_edge == 1'b0 && latch_edge == 1'b1) begin
            counter <= 2'b11;
        end else begin
            counter <= counter - 1;
        end
        prev_latch_edge <= latch_edge;
    end

    always @(posedge clk_in) begin
        if (counter == 2'b01) begin
            clk_out <= 1'b0;
        end else if (counter == 2'b10) begin
            clk_out <= 1'b1;
        end
    end
endmodule

