reg [31:0] diff = 0;
reg [31:0] freq = 0;

always @(posedge clk_in) begin
  count <= count + 1;
end

always @(posedge clk_in) begin
  if (count == 0) begin
    diff <= count - prev_count;
    prev_count <= count;
    freq <= diff;
  end
end

always @(posedge clk_in) begin
  if (count == 100000000) begin
    freq_out <= freq;
    freq <= 0;
    count <= 0;
  end
end

endmodule

