module accumulator(
    input logic clk, //clock input
    input logic rst_n, //reset input
    input logic [31:0] x, //input value
    output logic [31:0] accum_out, //accumulator output
    output logic [31:0] accum_bypass_out //bypass output
);

    logic [31:0] accum_in; //internal accumulator input
    logic [31:0] accum_bypass; //internal bypass flag
    logic [31:0] accum_out_expect; //expected accumulator output
    logic [31:0] accum_bypass_out_expect; //expected bypass output
    logic [31:0] cyc; //cycle counter
    logic [31:0] last_cyc; //last cycle counter

    assign accum_bypass_out = accum_bypass ? accum_in : accum_out_expect; //bypass output

    always_ff @(posedge clk, negedge rst_n) begin
        if(!rst_n) begin //reset
            accum_in <= 0;
            accum_bypass <= 0;
            accum_out_expect <= 0;
            accum_out <= 0;
            cyc <= 0;
            last_cyc <= 0;
        end else begin //accumulator circuit
            if(cyc == 0) begin //first cycle
                accum_in <= x*100;
                accum_bypass <= 0;
            end else if(cyc > 0) begin //subsequent cycles
                if(accum_bypass) begin //bypass flag is set
                    accum_out_expect <= 0;
                end else begin //bypass flag is not set
                    accum_out_expect <= accum_in + accum_out_expect + 7;
                end
                if(cyc == 5) begin //set bypass flag
                    accum_bypass <= 1;
                end
                accum_out <= accum_out_expect; //set accumulator output
            end
            if(x == 0 && cyc == last_cyc) begin //final cycle
                $display("final cycle = %0d", cyc);
                $write("*-* All Finished *-*\n");
                $finish;
            end
            cyc <= cyc + 1; //increment cycle counter
            last_cyc <= (x == 0) ? cyc : last_cyc; //update last cycle counter
        end
    end

endmodule

