    input reset, // Synchronous active-high reset
    input [7:0] in, // 8-bit input vector
    input select, // Select input to choose between modules
    output reg [7:0] anyedge, // Output from the active module
    output reg [7:0] combined_out // Combined output from the first module and the input vector
);

reg [7:0] prev_in; // Previous value of each input bit
reg [7:0] curr_in; // Current value of each input bit
reg [7:0] prev_out; // Previous value of the shift register
reg [7:0] curr_out; // Current value of the shift register

// Rising edge detection module for the input vector
always @(posedge clk) begin
    if (reset) begin
        prev_in <= 8'b0;
        anyedge <= 8'b0;
    end else begin
        prev_in <= curr_in;
        curr_in <= in;
        anyedge <= (curr_in & ~prev_in);
    end
end

// Combined rising edge detection module
always @(posedge clk) begin
    if (reset) begin
        prev_out <= 8'b0;
        combined_out <= 8'b0;
    end else begin
        prev_out <= curr_out;
        curr_out <= {anyedge, in};
        combined_out <= (curr_out & ~prev_out);
    end
end

// Bitwise OR module to combine the outputs
always @(*) begin
    if (select) begin
        anyedge <= 8'b0;
    end else begin
        combined_out <= 8'b0;
    end
end

endmodule

module fsm_ADC
(
	// User Interface
	input 			       clk,
	input 			       rst,
	input 			       rd,
	input 			       wr,
	input	       [6:0]   addr,
	input          [15:0]  data_in,
	output	reg    [15:0]  data_out,
	output	reg		       valid,
	// XADC ports
    input                  jtaglocked,
	input 			       busy,
	input 			       drdy,
	input 			       eoc,
	input                  eos,
	input          [4:0]   channel,
	input          [15:0]  dout,
	output 	reg            dwe,
	output 	reg            den,
	output 	reg    [6:0]   daddr,
	output 	reg    [15:0]  din
);

parameter [1:0]
	IDLE 	= 2'b00,
	WRITE 	= 2'b01,
	READ 	= 2'b10;

reg [1:0] state;

initial begin
	state <= IDLE;
	din <= 16'h0000;
	daddr <= 7'h00;
	den <= 1'b0;
	dwe <= 1'b0;
	valid <= 1'b0;
	data_out <= 16'h0000;
end

always@(posedge clk or posedge rst) begin
	if(rst)
		state <= IDLE;

	else begin
		case(state)
			IDLE: begin
				din <= 16'h0000;
				daddr <= 7'h00;
				den <= 1'b0;
				dwe <= 1'b0;
				valid <= 1'b0;
				data_out <= 16'h0000;
				if(!busy) begin
					if(eoc || eos) begin
						if(rd && !wr) begin
							den <= 1'b1;
							dwe <= 1'b0;
							daddr <= 7'h03;
							state <= READ;
						end
						else if(wr && !rd) begin
							den <= 1'b1;
							dwe <= 1'b1;
							din <= data_in;
							daddr <= addr;
							state <= WRITE;
						end
					end
				end
			end

			WRITE: begin
				den <= 1'b0;
				dwe <= 1'b0;
				if(drdy) begin
					valid <= 1'b1;
					state <= IDLE;
				end
			end

			READ: begin
				den <= 1'b0;
				dwe <= 1'b0;
				if(drdy) begin
					data_out <= dout;
					valid <= 1'b1;
					state <= IDLE;
				end
			end
		endcase
	end
end

endmodule

module predictor_2_1 ( clock, reset, enable, taken_i, prediction_o );
