// Define PLL module
module PLL (
  input clk_ref,
  output reg clk_out,
  output reg locked,
  output [31:0] fb
);

parameter N = 100; // PLL divider value
parameter Kp = 0.1; // Proportional gain
parameter Ki = 0.01; // Integral gain
parameter Kd = 0.001; // Derivative gain
parameter T = 1.0/f_clk; // PLL loop time constant

reg [31:0] phase;
reg [31:0] phase_prev;
reg [31:0] error;
reg [31:0] error_prev;
reg [31:0] integral;
reg [31:0] derivative;

always @(posedge clk_ref) begin
  phase <= phase + fb;
end

always @(posedge clk_ref) begin
  phase_prev <= phase;
  error_prev <= error;
end

always @(posedge clk_ref) begin
  error <= (N*phase - phase_prev) - f_clk;
  integral <= integral + error_prev*T;
  derivative <= (error - error_prev)/T;
  fb <= Kp*error + Ki*integral + Kd*derivative;
end

always @(posedge clk_ref) begin
  if (fb > 0 && fb < f_clk) begin
    clk_out <= ~clk_out;
  end
end

always @(posedge clk_ref) begin
  if (fb > 0 && fb < f_clk) begin
    locked <= 1;
  end else begin
    locked <= 0;
  end
end

endmodule

// Define frequency modulator module
module FM (
  input clk_in,
  input [31:0] f_mod,
  input [7:0] d_mod,
  output reg clk_out
);

parameter N = 100; // PLL divider value
parameter T = 1.0/f_clk; // PLL loop time constant

reg [31:0] phase;
reg [31:0] phase_prev;
reg [31:0] error;
reg [31:0] error_prev;
reg [31:0] integral;
reg [31:0] derivative;

always @(posedge clk_in) begin
  phase <= phase + (f_clk + d_mod*sin(2*3.14159*f_mod*phase*T));
end

always @(posedge clk_in) begin
  phase_prev <= phase;
  error_prev <= error;
end

always @(posedge clk_in) begin
  error <= (N*phase - phase_prev) - f_clk;
  integral <= integral + error_prev*T;
  derivative <= (error - error_prev)/T;
  clk_out <= ~clk_out;
end

endmodule

