module slowclk_gen (
   // Inputs
   fastclk,
   reset_l,
   enable,
   // Outputs
   slowclk
   );

   input fastclk;
   input reset_l;
   input enable;
   output slowclk;

   reg [24:0] counter;
   reg slowclk_reg;

   always @(posedge fastclk or negedge reset_l or negedge enable) begin
      if (~reset_l) begin
         counter <= 0;
         slowclk_reg <= 0;
      end else if (~enable) begin
         slowclk_reg <= 0;
      end else begin
         if (counter == 24999999) begin
            counter <= 0;
            slowclk_reg <= ~slowclk_reg;
         end else begin
            counter <= counter + 1;
         end
      end
   end

   assign slowclk = slowclk_reg;

