      current_tag <= i_pc[AW-1:4];

      // Handle cache invalidation requests
      if (i_clear_cache) begin
        cache_valid <= 0;
        cache_dirty <= 0;
      end

      // Check if the requested data is in the cache
      if (cache_valid[current_index]) begin
        if (current_tag == cache_mem[current_index][AW-1:4]) begin
          o_v <= 1;
          o_i <= cache_mem[current_index][DW-1:0];
        end else begin
          o_v <= 0;
        end
      end else begin
        o_v <= 0;
      end

      // Handle memory read and write requests
      if (o_wb_cyc) begin
        // Wait for the memory to acknowledge the previous request
        if (i_wb_ack) begin
          // Handle memory read requests
          if (~o_wb_we) begin
            read_data <= i_wb_data;
            o_i <= read_data;
            cache_mem[current_index] <= {current_tag, read_data};
            cache_valid[current_index] <= 1;
          end
          // Handle memory write requests
          else begin
            cache_mem[current_index] <= {current_tag, write_data};
            cache_valid[current_index] <= 1;
            cache_dirty[current_index] <= 1;
          end
          // Clear the memory request signals
          o_wb_cyc <= 0;
          o_wb_stb <= 0;
        end else if (~i_wb_stall) begin
          // Resend the previous request if it was not acknowledged
          o_wb_stb <= 1;
        end
      end else if (i_stall_n && ~o_v) begin
        // Send a memory read request if the requested data is not in the cache
        o_wb_cyc <= 1;
        o_wb_stb <= 1;
        o_wb_we <= 0;
        o_wb_addr <= i_pc;
      end else if (i_new_pc) begin
        // Update the program counter and clear the cache if necessary
        o_pc <= i_pc;
        if (cache_dirty[current_index]) begin
          o_wb_cyc <= 1;
          o_wb_stb <= 1;
          o_wb_we <= 1;
          o_wb_addr <= {current_tag, current_index};
          o_wb_data <= cache_mem[current_index];
          cache_dirty[current_index] <= 0;
        end
      end
    end
  end

  always @(posedge i_clk) begin
    // Handle memory write requests
    if (o_wb_cyc && o_wb_we) begin
      write_addr <= o_wb_addr;
      write_data <= o_wb_data;
    end
  end

  always @(posedge i_clk) begin
    // Handle illegal operations
    if (i_wb_err || (o_wb_cyc && ~i_wb_stall && ~i_wb_ack)) begin
      o_illegal <= 1;
    end else if (i_new_pc || i_clear_cache) begin
      o_illegal <= 0;
    end
  end

endmodule

