module four_bit_adder (
    A,
    B,
    Cin,
    Sum,
    Cout
);

    input [3:0] A;
    input [3:0] B;
    input Cin;
    output [3:0] Sum;
    output Cout;

    wire [3:0] Xor1;
    wire [3:0] Xor2;
    wire [3:0] And1;
    wire [3:0] And2;
    wire [3:0] Or1;
    wire [3:0] Or2;
    wire [3:0] Or3;
    wire [3:0] Not1;
    wire [3:0] Not2;

    assign Xor1 = A ^ B;
    assign And1 = A & B;
    assign Xor2 = Xor1 ^ Cin;
    assign And2 = Xor1 & Cin;
    assign Sum = Xor2;
    assign Cout = And1 | And2;

    always @(*) begin
        case ({Cin, A, B})
            4'b0000: begin
                Or1 = 4'b0000;
                Not1 = 4'b1111;
                Or2 = 4'b0000;
                Not2 = 4'b1111;
                Or3 = 4'b0001;
            end
            4'b0001: begin
                Or1 = 4'b0000;
                Not1 = 4'b1111;
                Or2 = 4'b0001;
                Not2 = 4'b1110;
                Or3 = 4'b0010;
            end
            4'b0010: begin
                Or1 = 4'b0001;
                Not1 = 4'b1110;
                Or2 = 4'b0000;
                Not2 = 4'b1111;
                Or3 = 4'b0010;
            end
            4'b0011: begin
                Or1 = 4'b0001;
                Not1 = 4'b1110;
                Or2 = 4'b0001;
                Not2 = 4'b1110;
                Or3 = 4'b0011;
            end
            4'b0100: begin
                Or1 = 4'b0010;
                Not1 = 4'b1101;
                Or2 = 4'b0000;
                Not2 = 4'b1111;
                Or3 = 4'b0010;
            end
            4'b0101: begin
                Or1 = 4'b0010;
                Not1 = 4'b1101;
                Or2 = 4'b0001;
                Not2 = 4'b1110;
                Or3 = 4'b0011;
            end
            4'b0110: begin
                Or1 = 4'b0011;
                Not1 = 4'b1100;
                Or2 = 4'b0000;
                Not2 = 4'b1111;
                Or3 = 4'b0010;
            end
            4'b0111: begin
                Or1 = 4'b0011;
                Not1 = 4'b1100;
                Or2 = 4'b0001;
                Not2 = 4'b1110;
                Or3 = 4'b0011;
            end
            4'b1000: begin
                Or1 = 4'b0100;
                Not1 = 4'b1011;
                Or2 = 4'b0000;
                Not2 = 4'b1111;
                Or3 = 4'b0010;
            end
            4'b1001: begin
                Or1 = 4'b0100;
                Not1 = 4'b1011;
                Or2 = 4'b0001;
                Not2 = 4'b1110;
                Or3 = 4'b0011;
            end
            4'b1010: begin
                Or1 = 4'b0101;
                Not1 = 4'b1010;
                Or2 = 4'b0000;
                Not2 = 4'b1111;
                Or3 = 4'b0011;
            end
            4'b1011: begin
                Or1 = 4'b0101;
                Not1 = 4'b1010;
                Or2 = 4'b0001;
                Not2 = 4'b1110;
                Or3 = 4'b0100;
            end
            4'b1100: begin
                Or1 = 4'b0110;
                Not1 = 4'b1001;
                Or2 = 4'b0000;
                Not2 = 4'b1111;
                Or3 = 4'b0011;
            end
            4'b1101: begin
                Or1 = 4'b0110;
                Not1 = 4'b1001;
                Or2 = 4'b0001;
                Not2 = 4'b1110;
                Or3 = 4'b0100;
            end
            4'b1110: begin
                Or1 = 4'b0111;
                Not1 = 4'b1000;
                Or2 = 4'b0000;
                Not2 = 4'b1111;
                Or3 = 4'b0011;
            end
            4'b1111: begin
                Or1 = 4'b0111;
                Not1 = 4'b1000;
                Or2 = 4'b0001;
                Not2 = 4'b1110;
                Or3 = 4'b0100;
            end
        endcase
    end

endmodule

module decoder (
    input [1:0] SEL,
    input EN,
    output reg [15:0] Q
);

reg [3:0] temp_Q1, temp_Q2;

always @(SEL, EN) begin
    if (EN == 1'b0) begin
        Q <= 16'b0;
    end
    else begin
        case (SEL)
            2'b00: temp_Q1 = 4'b0001;
            2'b01: temp_Q1 = 4'b0010;
            2'b10: temp_Q1 = 4'b0100;
            2'b11: temp_Q1 = 4'b1000;
        endcase

        case (temp_Q1)
            4'b0001: temp_Q2 = 16'b0000000000000001;
            4'b0010: temp_Q2 = 16'b0000000000000010;
            4'b0100: temp_Q2 = 16'b0000000000000100;
            4'b1000: temp_Q2 = 16'b0000000000001000;
        endcase

        Q <= temp_Q2;
    end
end

endmodule

module top_module (
    input clk,
    input rst_n,
    input [255:0] in,
    input [7:0] sel,
    output [63:0] q
);

    // 256-to-1 multiplexer using barrel shifter and 4-to-1 multiplexer
    wire [255:0] shifted_in;
    wire [3:0] sel_4;
    wire [63:0] mux_out;
    barrel_shifter bs (
        .in(in),
        .sel(sel),
        .out(shifted_in)
    );
    mux_4to1 mux (
        .in0(shifted_in[3:0]),
        .in1(shifted_in[7:4]),
        .in2(shifted_in[11:8]),
        .in3(shifted_in[15:12]),
        .sel(sel_4),
        .out(mux_out)
    );
    assign sel_4 = sel[3:0];

    // 64-bit Johnson counter
    wire [63:0] johnson_out;
    johnson_counter jc (
        .clk(clk),
        .rst_n(rst_n),
        .out(johnson_out)
    );

    // Bitwise AND module
    wire [63:0] and_out;
    bitwise_and and_gate (
        .in1(mux_out),
        .in2(johnson_out),
        .out(and_out)
    );

    assign q = and_out;

endmodule

