// 64-bit Johnson counter module
module johnson_counter (
    input clk,
    input rst_n,
    output reg [63:0] out
);
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            out <= 64'h0000000000000000;
        end else begin
            case (out)
                64'h0000000000000000: out <= 64'h8000000000000000;
                64'h8000000000000000: out <= 64'hC000000000000000;
                64'hC000000000000000: out <= 64'hE000000000000000;
                64'hE000000000000000: out <= 64'hF000000000000000;
                64'hF000000000000000: out <= 64'hF800000000000000;
                64'hF800000000000000: out <= 64'hFC00000000000000;
                64'hFC00000000000000: out <= 64'hFE00000000000000;
                64'hFE00000000000000: out <= 64'hFF00000000000000;
                64'hFF00000000000000: out <= 64'h7F00000000000000;
                64'h7F00000000000000: out <= 64'h3F00000000000000;
                64'h3F00000000000000: out <= 64'h1F00000000000000;
                64'h1F00000000000000: out <= 64'h0F00000000000000;
                64'h0F00000000000000: out <= 64'h0700000000000000;
                64'h0700000000000000: out <= 64'h0300000000000000;
                64'h0300000000000000: out <= 64'h0100000000000000;
                64'h0100000000000000: out <= 64'h0000000000000000;
            endcase
        end
    end
endmodule

