module consecutive_ones_counter (
  input clk,
  input reset,
  input [3:0] data,
  output reg [2:0] count
);

reg [2:0] count_reg;
reg [2:0] count_next;

always @(posedge clk) begin
  if (reset) begin
    count_reg <= 0;
  end else begin
    count_reg <= count_next;
  end
end

always @(*) begin
  count_next = 0;
  if (data[0] == 1) begin
    count_next = 1;
    if (data[1] == 1) begin
      count_next = 2;
      if (data[2] == 1) begin
        count_next = 3;
      end
    end
  end
end

assign count = count_reg;

endmodule

module adder_subtractor (
    input [3:0] A,
    input [3:0] B,
    input M,
    output [3:0] Y
);

    wire [3:0] B_comp;
    wire [3:0] temp_sum;
    wire [3:0] temp_diff;

    // Complement B if M is 1
    assign B_comp = M ? ~B + 1 : B;

    // Calculate the sum and difference
    assign temp_sum = A + B_comp;
    assign temp_diff = A - B_comp;

    // Select output based on M
    assign Y = M ? temp_diff : temp_sum;

endmodule

module fifo_buffer (
  input clk_i,
  input rst_i,
  input wr_en_i,
  input [7:0] wr_data_i,
  input rd_en_i,
  input rd_data_req_i,
  input rd_data_ack_i,
  output reg wr_full_o,
  output reg wr_empty_o,
  output reg rd_full_o,
  output reg rd_empty_o,
  output reg [7:0] rd_data_o
);

  parameter FIFO_DEPTH = 32;
  parameter DATA_WIDTH = 8;
  parameter ADDR_WIDTH = $clog2(FIFO_DEPTH);

  reg [DATA_WIDTH-1:0] fifo[FIFO_DEPTH-1:0];
  reg [ADDR_WIDTH-1:0] wr_ptr = 0;
  reg [ADDR_WIDTH-1:0] rd_ptr = 0;
  reg [ADDR_WIDTH-1:0] count = 0;

  always @(posedge clk_i) begin
    if (rst_i) begin
      wr_full_o <= 1'b0;
      wr_empty_o <= 1'b1;
      rd_full_o <= 1'b0;
      rd_empty_o <= 1'b1;
      rd_data_o <= 8'h00;
      wr_ptr <= 0;
      rd_ptr <= 0;
      count <= 0;
    end else begin
      // Write operation
      if (wr_en_i && !wr_full_o) begin
        fifo[wr_ptr] <= wr_data_i;
        wr_ptr <= wr_ptr + 1;
        if (wr_ptr == FIFO_DEPTH) begin
          wr_ptr <= 0;
        end
        count <= count + 1;
      end
      // Read operation
      if (rd_en_i && rd_data_req_i && !rd_empty_o) begin
        rd_data_o <= fifo[rd_ptr];
        rd_ptr <= rd_ptr + 1;
        if (rd_ptr == FIFO_DEPTH) begin
          rd_ptr <= 0;
        end
        count <= count - 1;
        rd_full_o <= 1'b0;
        if (count == 1) begin
          rd_empty_o <= 1'b1;
        end
      end
      // Acknowledge read operation
      if (rd_data_ack_i && !rd_empty_o) begin
        rd_ptr <= rd_ptr + 1;
        if (rd_ptr == FIFO_DEPTH) begin
          rd_ptr <= 0;
        end
        count <= count - 1;
        rd_full_o <= 1'b0;
        if (count == 1) begin
          rd_empty_o <= 1'b1;
        end
      end
      // Update FIFO status
      if (count == FIFO_DEPTH) begin
        wr_full_o <= 1'b1;
        wr_empty_o <= 1'b0;
      end else if (count == 0) begin
        rd_full_o <= 1'b0;
        rd_empty_o <= 1'b1;
      end else begin
        wr_full_o <= 1'b0;
        wr_empty_o <= 1'b0;
        rd_full_o <= 1'b0;
        rd_empty_o <= 1'b0;
      end
    end
  end

endmodule

