module encryption_module (
    input clk,
    input [7:0] key,
    input [7:0] plaintext,
    output [7:0] ciphertext
);

    reg [7:0] shift_reg;
    wire [7:0] shifted_plaintext;
    wire [7:0] encrypted_output;

    // 8-bit shift register using D flip-flops
    always @(posedge clk) begin
        shift_reg[0] <= plaintext[0];
        shift_reg[1] <= shift_reg[0];
        shift_reg[2] <= shift_reg[1];
        shift_reg[3] <= shift_reg[2];
        shift_reg[4] <= shift_reg[3];
        shift_reg[5] <= shift_reg[4];
        shift_reg[6] <= shift_reg[5];
        shift_reg[7] <= shift_reg[6];
    end

    // Shifted plaintext output
    assign shifted_plaintext = shift_reg;

    // XOR gate for encryption
    assign encrypted_output = shifted_plaintext ^ key;

    // Output ciphertext
    assign ciphertext = encrypted_output;

endmodule

module calculator(
	input [7:0] A,
	input [7:0] B,
	input [1:0] op,
	output [7:0] S,
	output [7:0] D,
	output [7:0] P,
	output [7:0] Q
);

	reg [8:0] temp_result;

	always @(*) begin
		case(op)
			2'b00: temp_result = A + B;
			2'b01: temp_result = A - B;
			2'b10: temp_result = A * B;
			2'b11: temp_result = A / B;
		endcase
	end

	assign S = (temp_result > 8'hFF) ? 8'hFF : temp_result;
	assign D = (temp_result < 0) ? 0 : temp_result;
	assign P = (temp_result > 8'hFF) ? 8'hFF : temp_result;
	assign Q = (B == 0) ? 8'hFF : A / B;

endmodule

module gray_to_binary (
    input clk,
    input rst,
    input ena,
    input [3:0] gray,
    output reg [3:0] binary
);

    always @(posedge clk) begin
        if (rst) begin
            binary <= 4'b0000;
        end else if (ena) begin
            binary[3] <= gray[3];
            binary[2] <= binary[3] ^ gray[2];
            binary[1] <= binary[2] ^ gray[1];
            binary[0] <= binary[1] ^ gray[0];
        end
    end

endmodule

