module top_module (
    input clk,
    input [2:0] sel, 
    input [2:0] data0,
    input [2:0] data1,
    input [2:0] data2,
    input [2:0] data3,
    input [2:0] data4,
    input [2:0] data5,
    output reg [2:0] out
);

reg [2:0] mux_out;
reg [2:0] shift_reg_out;
reg [2:0] and_out;

wire [2:0] shift_reg_in;

// 6-to-1 Multiplexer
always @ (sel or data0 or data1 or data2 or data3 or data4 or data5) begin
    case (sel)
        3'b000: mux_out = data0;
        3'b001: mux_out = data1;
        3'b010: mux_out = data2;
        3'b011: mux_out = data3;
        3'b100: mux_out = data4;
        3'b101: mux_out = data5;
        default: mux_out = 3'b000;
    endcase
end

// Shift Register
shift_register sr(clk, shift_reg_in[2], shift_reg_out);

always @ (posedge clk) begin
    shift_reg_in[0] = mux_out[0];
    shift_reg_in[1] = shift_reg_out[0];
    shift_reg_in[2] = shift_reg_out[1];
end

// Output Mux
always @ (shift_reg_out or mux_out) begin
    case (sel)
        3'b000: out = {shift_reg_out[0], mux_out[1:0]};
        3'b001: out = {shift_reg_out[0:1], mux_out[2]};
        3'b010: out = {shift_reg_out[0:2], mux_out[2]};
        3'b011: out = {shift_reg_out[1:0], mux_out[2]};
        3'b100: out = {shift_reg_out[2], mux_out[1:0]};
        3'b101: out = {shift_reg_out[2:1], mux_out[2]};
        default: out = 3'b000;
    endcase
end

// AND Gate
and_gate and1(shift_reg_out, mux_out, and_out);

endmodule

