module watchdog_timer (
  input clk,
  input reset,
  output reg wd
);

parameter initial_value = 100000000; // initial value of the watchdog timer (e.g., 1 second)
parameter timeout_value = 200000000; // timeout value (e.g., 2 seconds)

reg [31:0] counter;

always @(posedge clk) begin
  if (reset) begin
    counter <= initial_value;
    wd <= 1'b0;
  end else if (counter == 0) begin
    counter <= initial_value;
    wd <= 1'b1;
  end else begin
    counter <= counter - 1;
    wd <= 1'b0;
  end
end

always @(posedge clk) begin
  if (wd) begin
    if (counter == timeout_value) begin
      counter <= initial_value;
      wd <= 1'b0;
      reset <= 1'b1;
    end else begin
      counter <= counter + 1;
    end
  end else if (reset) begin
    counter <= initial_value;
  end
end

endmodule

module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    input C_in,
    output [3:0] S,
    output C_out
);

    wire [3:0] c1, c2, c3;

    // First column
    and_gate g1 (.a(A[0]), .b(B[0]), .y(c1[0]));
    xor (S[0], A[0], B[0], C_in);

    // Second column
    xor (c1[1], A[1], B[1]);
    and (c2[1], c1[0], c1[1]);
    xor (S[1], A[1], B[1], C_in);
    xor (C_out, c1[0], c1[1], C_in);

    // Third column
    xor (c1[2], A[2], B[2]);
    and (c2[2], c1[1], c1[2]);
    xor (c3[2], c2[1], c2[2]);
    xor (S[2], A[2], B[2], C_in);
    xor (C_out, c1[1], c1[2], C_in);

    // Fourth column
    xor (c1[3], A[3], B[3]);
    and (c2[3], c1[2], c1[3]);
    xor (c3[3], c2[2], c2[3]);
    xor (S[3], A[3], B[3], C_in);
    xor (C_out, c1[2], c1[3], C_in);

endmodule

