module fsm_3bit_sequence_detection (
  input clk,
  input reset,
  input x,
  output reg z
);

  parameter S0 = 2'b00, S1 = 2'b01, S2 = 2'b10;
  reg [1:0] state, next_state;

  always @(posedge clk, negedge reset) begin
    if (reset == 0) begin
      state <= S0;
    end else begin
      state <= next_state;
    end
  end

  always @(*) begin
    case (state)
      S0: begin
        if (x == 0) begin
          next_state = S0;
          z = 0;
        end else if (x == 1) begin
          next_state = S1;
          z = 0;
        end
      end
      S1: begin
        if (x == 0) begin
          next_state = S0;
          z = 0;
        end else if (x == 1) begin
          next_state = S2;
          z = 0;
        end
      end
      S2: begin
        if (x == 0) begin
          next_state = S0;
          z = 1;
        end else if (x == 1) begin
          next_state = S1;
          z = 0;
        end
      end
      default: begin
        next_state = S0;
        z = 0;
      end
    endcase
  end

endmodule

