module crc_module (
  input clk,
  input [63:0] data_in,
  output reg [63:0] checksum
);

  integer cyc = 0;
  reg [63:0] crc;
  logic [1:0] o [13:10];

  Test test (
    .o (o),
    .i (crc[1:0])
  );

  always @ (posedge clk) begin
    cyc <= cyc + 1;
    crc <= {crc[62:0], crc[63] ^ crc[2] ^ crc[0]};
    if (cyc == 0) begin
      crc <= 64'h5aef0c8d_d70a4497;
    end
    else if (cyc >= 90) begin
      checksum <= {32'h0, 6'h0, o[13], 6'h0, o[12], 6'h0, o[11], 6'h0, o[10]};
    end
  end

endmodule

