    input wire sel_b2,
    input wire [15:0] in,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo,
    output wire [7:0] out_xor
);

    // 4-to-1 multiplexer
    wire [7:0] mux_out;
    assign mux_out = (sel_b1 == 0 && sel_b2 == 0) ? input1 :
                     (sel_b1 == 0 && sel_b2 == 1) ? input2 :
                     (sel_b1 == 1 && sel_b2 == 0) ? input3 :
                                                  input4;

    // Barrel shifter
    wire [7:0] in_hi = in[15:8];
    wire [7:0] in_lo = in[7:0];
    wire [7:0] shifted_hi;
    wire [7:0] shifted_lo;
    assign shifted_hi = in_hi >> 1;
    assign shifted_lo = in_lo << 1;

    // XOR module
    wire [7:0] xor_out;
    assign xor_out = mux_out ^ {shifted_hi, shifted_lo};

    // Output assignments
    assign out_hi = shifted_hi;
    assign out_lo = shifted_lo;
    assign out_xor = xor_out;

endmodule

module rotator(
    input clk,
    input load,
    input [1:0] ena,
    input [99:0] data,
    output reg [99:0] q);

    reg [99:0] shift_reg;
    reg [6:0] shift_amt;
    reg [99:0] shifted_out;

    always @(posedge clk) begin
        if (load) begin
            shift_reg <= data;
        end else begin
            if (ena == 2'b00) begin // no shift
                shift_reg <= shift_reg;
            end else if (ena == 2'b01) begin // left shift
                shift_amt <= shift_amt + 1;
                shifted_out <= shift_reg[99];
                shift_reg <= {shift_reg[98:0], 1'b0};
            end else if (ena == 2'b10) begin // right shift
                shift_amt <= shift_amt - 1;
                shifted_out <= shift_reg[0];
                shift_reg <= {1'b0, shift_reg[99:1]};
            end else begin // ena == 2'b11, load and rotate
                shift_reg <= data;
            end
        end
    end

    always @(shift_amt or shifted_out) begin
        if (shift_amt == 7) begin
            q <= {shifted_out, shift_reg[99:1]};
        end else if (shift_amt == -7) begin
            q <= {shift_reg[98:0], shifted_out};
        end else begin
            q <= shift_reg;
        end
    end

endmodule

