module GlitchFreeMux (
  input [n-1:0] clk_in,
  input [log2(n)-1:0] sel,
  output reg clk_out
);

parameter n = 4; // number of input clock signals

reg [n-1:0] ff_out;
integer i;

// Flip-flops for input clock signals
always @(*) begin
  for (i = 0; i < n; i = i + 1) begin
    if (i == sel) begin
      ff_out[i] <= clk_in[i];
    end else begin
      ff_out[i] <= ff_out[i];
    end
  end
end

// Multiplexer for selecting the appropriate flip-flop output
always @(sel or ff_out) begin
  clk_out <= ff_out[sel];
end

endmodule

