module mealy_state_machine (
  input clk,
  input reset,
  input x,
  input y,
  output reg z
);

  // Define the state variable and its possible values
  reg [1:0] state, next_state;
  parameter IDLE = 2'b00, WAIT = 2'b01, OUTPUT = 2'b10;

  // Define the state transition logic
  always @ (posedge clk, posedge reset) begin
    if (reset) begin
      state <= IDLE;
    end else begin
      state <= next_state;
    end
  end

  // Define the next state logic
  always @ (*) begin
    case (state)
      IDLE: begin
        if (x) begin
          next_state = WAIT;
          z = 0;
        end else begin
          next_state = IDLE;
          z = 0;
        end
      end
      WAIT: begin
        if (y) begin
          next_state = OUTPUT;
          z = 1;
        end else begin
          next_state = WAIT;
          z = 0;
        end
      end
      OUTPUT: begin
        if (!x || y) begin
          next_state = IDLE;
          z = 0;
        end else begin
          next_state = OUTPUT;
          z = 1;
        end
      end
    endcase
  end

endmodule

module DataArbiter (
    input [7:0] in1_ctrl,
    input [7:0] in1_data,
    input in1_req,
    input [7:0] in2_ctrl,
    input [7:0] in2_data,
    input in2_req,
    input [7:0] in3_ctrl,
    input [7:0] in3_data,
    input in3_req,
    input clk,
    input rst,
    output [7:0] out_ctrl,
    output [7:0] out_data,
    output out_req
);

reg [1:0] priority;
reg [7:0] ctrl;
reg [7:0] data;
reg req;

always @ (posedge clk) begin
    if (rst) begin
        priority <= 2'b00;
        ctrl <= 8'h00;
        data <= 8'h00;
        req <= 1'b0;
    end else begin
        if (in1_req) begin
            priority <= 2'b00;
            ctrl <= in1_ctrl;
            data <= in1_data;
            req <= 1'b1;
        end else if (in2_req) begin
            priority <= 2'b01;
            ctrl <= in2_ctrl;
            data <= in2_data;
            req <= 1'b1;
        end else if (in3_req) begin
            priority <= 2'b10;
            ctrl <= in3_ctrl;
            data <= in3_data;
            req <= 1'b1;
        end else begin
            priority <= 2'b00;
            ctrl <= 8'h00;
            data <= 8'h00;
            req <= 1'b0;
        end
    end
end

assign out_ctrl = (priority == 2'b00) ? ctrl : (priority == 2'b01) ? in2_ctrl : in3_ctrl;
assign out_data = (priority == 2'b00) ? data : (priority == 2'b01) ? in2_data : in3_data;
assign out_req = req;

endmodule

module JNOR3C(A1, A2, A3, A4, O);
input   A1;
input   A2;
input   A3;
input   A4;
output  O;

wire    M1;
wire    M2;
wire    M3;
wire    N1;
wire    N2;

// Implement majority gate using standard gates
assign M1 = A1 & A2;
assign M2 = A2 & A3;
assign M3 = A1 & A3;
assign N1 = ~(M1 | M2);
assign N2 = ~(M1 | M3);
assign O = ~(N1 | N2 | (A1 & A2 & A3 & A4));

endmodule

