    assign g0 = a & b;
    assign g1 = a & ~b;
    assign g2 = ~a & b;
    assign g3 = ~a & ~b;

    assign p0_int = g0 | g1;
    assign p1_int = g2 | g3;
    assign p2_int = g1 | g3;
    assign p3_int = g0 | g2;

    assign p0 = {p0_int[7], p0_int[6], p0_int[5], p0_int[4], p0_int[3], p0_int[2], p0_int[1], p0_int[0]};
