    assign p3 = {p3_int[7], p3_int[6], p3_int[5], p3_int[4], p3_int[3], p3_int[2], p3_int[1], p3_int[0]};

    assign s = p0 + (p1 << 1) + (p2 << 2) + (p3 << 3);
