module two_hundred_fifty_six_bit_byteenable_FSM (
  clk,
  reset,

  write_in,
  byteenable_in,
  waitrequest_out,

  byteenable_out,
  waitrequest_in
);

  input clk;
  input reset;

  input write_in;
  input [31:0] byteenable_in;
  output wire waitrequest_out;

  output wire [31:0] byteenable_out; 
  input waitrequest_in;

  // internal state machine signals
  reg [1:0] state;
  wire [15:0] lower_byteenable;
  wire [15:0] upper_byteenable;
  wire lower_done;
  wire upper_done;
  wire transfer_done;
  wire lower_enable;
  wire upper_enable;

  // assign lower and upper byte enables
  assign lower_byteenable = byteenable_in[15:0];
  assign upper_byteenable = byteenable_in[31:16];

  // assign lower and upper enable signals
  assign lower_enable = (write_in == 1) && ((lower_byteenable != 0) || (upper_byteenable == 16'hFFFF));
  assign upper_enable = (write_in == 1) && ((upper_byteenable != 0) || (lower_byteenable == 16'hFFFF));

  // FSM logic
  always @ (posedge clk or posedge reset) begin
    if (reset) begin
      state <= 2'b00;
    end else if (waitrequest_in == 1) begin
      // stall in current state if wait request is high
    end else if (state == 2'b00) begin
      if (lower_byteenable == 16'hFFFF) begin
        byteenable_out <= byteenable_in;
        state <= 2'b00;
        transfer_done <= 1;
      end else if (lower_byteenable != 0) begin
        byteenable_out <= byteenable_in;
        state <= 2'b01;
      end else if (upper_byteenable != 0) begin
        byteenable_out <= {16'h0000, upper_byteenable};
        state <= 2'b10;
      end
    end else if (state == 2'b01) begin
      if (upper_byteenable == 16'hFFFF) begin
        byteenable_out <= {16'hFFFF, lower_byteenable};
        state <= 2'b00;
        transfer_done <= 1;
      end else if (upper_byteenable != 0) begin
        byteenable_out <= {16'hFFFF, lower_byteenable};
        state <= 2'b10;
      end else if (lower_byteenable == 16'hFFFF) begin
        byteenable_out <= byteenable_in;
        state <= 2'b00;
        transfer_done <= 1;
      end else if (lower_byteenable != 0) begin
        byteenable_out <= byteenable_in;
        state <= 2'b01;
      end
    end else if (state == 2'b10) begin
      if (lower_byteenable == 16'hFFFF) begin
        byteenable_out <= byteenable_in;
        state <= 2'b00;
        transfer_done <= 1;
      end else if (lower_byteenable != 0) begin
        byteenable_out <= {lower_byteenable, 16'h0000};
        state <= 2'b01;
      end else if (upper_byteenable == 16'hFFFF) begin
        byteenable_out <= {16'h0000, upper_byteenable};
        state <= 2'b00;
        transfer_done <= 1;
      end else if (upper_byteenable != 0) begin
        byteenable_out <= {16'h0000, upper_byteenable};
        state <= 2'b10;
      end
    end
  end

  // assign transfer done signal
  assign waitrequest_out = (waitrequest_in == 1) || ((write_in == 1) && (transfer_done == 0));

endmodule

module TX_control
#(
    parameter INTER_BYTE_DELAY = 1000000, // ciclos de reloj de espera entre el envio de 2 bytes consecutivos
    parameter WAIT_FOR_REGISTER_DELAY = 100 // tiempo de espera para iniciar la transmision luego de registrar el dato a enviar
)(
    input clock,
    input reset,
    input PB, // Push Button
    input send16, // Indica si se deben enviar 8 o 16 bits
    input [15:0] dataIn16, // Dato que se desea transmitir de 16 bits
    output reg [7:0] tx_data, // Datos entregados al driver UART para transmision
    output reg tx_start, // Pulso para iniciar transmision por la UART
    output reg busy // Indica si hay una transmision en proceso
);

    reg [2:0] next_state, state;
    reg [15:0] tx_data16;
    reg [31:0] hold_state_timer;

    //state encoding
    localparam IDLE = 3'd0; // Modo espera
    localparam REGISTER_DATAIN16 = 3'd1; // Cuando se presiona boton, registrar 16 bits a enviar
    localparam SEND_BYTE_0 = 3'd2; // Enviar el primer byte
    localparam DELAY_BYTE_0 = 3'd3; // Esperar un tiempo suficiente para que la transmision anterior termine
    localparam SEND_BYTE_1 = 3'd4; // Si es necesario, enviar el segundo byte
    localparam DELAY_BYTE_1 = 3'd5; // Esperar a que la transmision anterior termine

    // combo logic of FSM
    always @(*) begin
        //default assignments
        next_state = state;
        busy = 1'b1;
        tx_start = 1'b0;
        tx_data = tx_data16[7:0];

        case (state)
            IDLE: begin
                busy = 1'b0;
                if (PB) begin
                    next_state = REGISTER_DATAIN16;
                end
            end

            REGISTER_DATAIN16: begin
                if (hold_state_timer >= WAIT_FOR_REGISTER_DELAY)
                    next_state = SEND_BYTE_0;
            end

            SEND_BYTE_0: begin
                next_state = DELAY_BYTE_0;
                tx_start = 1'b1;
            end

            DELAY_BYTE_0: begin
                if (hold_state_timer >= INTER_BYTE_DELAY) begin
                    if (send16)
                        next_state = SEND_BYTE_1;
                    else
                        next_state = IDLE;
                end
            end

            SEND_BYTE_1: begin
                tx_data = tx_data16[15:8];
                next_state = DELAY_BYTE_1;
                tx_start = 1'b1;
            end

            DELAY_BYTE_1: begin
                if (hold_state_timer >= INTER_BYTE_DELAY)
                    next_state = IDLE;
            end
        endcase
    end

    //when clock ticks, update the state
    always @(posedge clock) begin
        if (reset)
            state <= IDLE;
        else
            state <= next_state;
    end

    // registra los datos a enviar
    always @(posedge clock) begin
        if (state == REGISTER_DATAIN16)
            tx_data16 <= dataIn16;
    end

    //activa timer para retener un estado por cierto numero de ciclos de reloj
    always @(posedge clock) begin
        if (state == DELAY_BYTE_0 || state == DELAY_BYTE_1 || state == REGISTER_DATAIN16) begin
            hold_state_timer <= hold_state_timer + 1;
        end else begin
            hold_state_timer <= 0;
        end
    end

endmodule

