module fifo (
    aclr,
    data,
    rdclk,
    rdreq,
    wrclk,
    wrreq,
    q,
    rdempty,
    wrfull
);

    parameter DEPTH = 32;
    parameter WIDTH = 32;

    input aclr;
    input [WIDTH-1:0] data;
    input rdclk;
    input rdreq;
    input wrclk;
    input wrreq;
    output [WIDTH-1:0] q;
    output rdempty;
    output wrfull;

    reg [WIDTH-1:0] fifo [0:DEPTH-1];
    reg [5:0] wr_ptr;
    reg [5:0] rd_ptr;
    wire [5:0] next_wr_ptr;
    wire [5:0] next_rd_ptr;
    wire full;
    wire empty;

    assign wrfull = full;
    assign rdempty = empty;
    assign q = fifo[rd_ptr];

    always @(posedge wrclk or negedge aclr) begin
        if (~aclr) begin
            wr_ptr <= 0;
        end else if (wrreq && ~full) begin
            fifo[wr_ptr] <= data;
            wr_ptr <= next_wr_ptr;
        end
    end

    always @(posedge rdclk or negedge aclr) begin
        if (~aclr) begin
            rd_ptr <= 0;
        end else if (rdreq && ~empty) begin
            rd_ptr <= next_rd_ptr;
        end
    end

    assign full = (wr_ptr == next_rd_ptr);
    assign empty = (wr_ptr == rd_ptr);

    assign next_wr_ptr = {wr_ptr[4:0], wr_ptr[5]} + 1'b1;
    assign next_rd_ptr = {rd_ptr[4:0], rd_ptr[5]} + 1'b1;

endmodule

module fifo_buffer
  (D,
   clk,
   tmp_ram_rd_en,
   E,
   Q,
   count_d1_reg,
   din);
  output [23:0]D;
  input clk;
  input tmp_ram_rd_en;
  input [0:0]E;
  input [0:0]Q;
  input [8:0]count_d1_reg;
  input [23:0]din;

  wire [23:0]D;
  wire [0:0]E;
  wire [0:0]Q;
  wire clk;
  wire [23:0]din;
  wire [8:0]count_d1_reg;
  wire tmp_ram_rd_en;

  scfifo_24in_24out_12kb_blk_mem_gen_generic_cstr fifo_inst 
       (.D(D),
        .E(E),
        .Q(Q),
        .clk(clk),
        .din(din),
        .count_d1_reg(count_d1_reg),
        .tmp_ram_rd_en(tmp_ram_rd_en));

  reg [23:0] input_buffer [0:4095];
  reg [23:0] output_buffer [0:4095];
  reg [11:0] input_head = 0;
  reg [11:0] input_tail = 0;
  reg [11:0] output_head = 0;
  reg [11:0] output_tail = 0;
  reg [8:0] count = 0;

  always @(posedge clk) begin
    if (E) begin
      input_buffer[input_head] = din;
      input_head <= input_head + 1;
      count <= count + 1;
    end
    if (tmp_ram_rd_en && count > 0) begin
      output_buffer[output_tail] = fifo_inst.D;
      output_tail <= output_tail + 1;
      count <= count - 1;
    end
  end

  assign fifo_inst.E = (count < 4096) ? 1 : 0;
  assign fifo_inst.Q = (count > 0) ? 1 : 0;
  assign fifo_inst.din = input_buffer[input_tail];
  assign count_d1_reg = count;

  always @(posedge clk) begin
    if (Q && count > 0) begin
      D <= output_buffer[output_head];
      output_head <= output_head + 1;
    end
  end
endmodule

module decoder (
    input A, B, EN,
    output reg Y0, Y1, Y2, Y3
);

    always @ (A, B, EN) begin
        if (EN == 1'b0) begin
            Y0 <= 1'b0;
            Y1 <= 1'b0;
            Y2 <= 1'b0;
            Y3 <= 1'b0;
        end
        else begin
            case ({A, B})
                2'b00: begin
                    Y0 <= 1'b1;
                    Y1 <= 1'b0;
                    Y2 <= 1'b0;
                    Y3 <= 1'b0;
                end
                2'b01: begin
                    Y0 <= 1'b0;
                    Y1 <= 1'b1;
                    Y2 <= 1'b0;
                    Y3 <= 1'b0;
                end
                2'b10: begin
                    Y0 <= 1'b0;
                    Y1 <= 1'b0;
                    Y2 <= 1'b1;
                    Y3 <= 1'b0;
                end
                2'b11: begin
                    Y0 <= 1'b0;
                    Y1 <= 1'b0;
                    Y2 <= 1'b0;
                    Y3 <= 1'b1;
                end
                default: begin
                    Y0 <= 1'b0;
                    Y1 <= 1'b0;
                    Y2 <= 1'b0;
                    Y3 <= 1'b0;
                end
            endcase
        end
    end

endmodule

