module mem_compress_decompress (
  input [n-1:0] in,
  input reset,
  input comp_en,
  input decomp_en,
  output [m-1:0] out,
  output [n-1:0] out_decomp
);

parameter n = 1024; // size of original memory array
parameter m = 512; // size of compressed memory array
parameter k = 64; // block size
parameter l = 4; // repeating pattern length

reg [n-1:0] dict [0:2**l-1]; // dictionary to store repeating patterns
reg [m-1:0] compressed_mem [0:m-1]; // compressed memory array
reg [n-1:0] decompressed_mem [0:n-1]; // decompressed memory array

integer i, j, block_idx, pattern_idx, dict_idx;
reg [k-1:0] block [0:n/k-1]; // original memory array divided into blocks
reg [k-1:0] compressed_block [0:n/k-1]; // compressed memory array divided into blocks

// Compression algorithm
always @ (posedge comp_en or posedge reset) begin
  if (reset) begin
    // Reset dictionary and compressed memory array
    for (i = 0; i < 2**l; i = i + 1) begin
      dict[i] = 0;
    end
    for (i = 0; i < m; i = i + 1) begin
      compressed_mem[i] = 0;
    end
  end else if (comp_en) begin
    // Divide original memory array into blocks
    for (i = 0; i < n/k; i = i + 1) begin
      block[i] = in[i*k +: k];
    end
    // Compress each block
    for (block_idx = 0; block_idx < n/k; block_idx = block_idx + 1) begin
      // Check for repeating patterns in block
      for (i = 0; i < k-l+1; i = i + 1) begin
        pattern_idx = 0;
        for (j = i; j < i+l; j = j + 1) begin
          pattern_idx = pattern_idx << 1;
          pattern_idx = pattern_idx | block[block_idx][j];
        end
        // Check if pattern is in dictionary
        dict_idx = 0;
        while (dict_idx < 2**l && dict[dict_idx] != pattern_idx) begin
          dict_idx = dict_idx + 1;
        end
        // If pattern is not in dictionary, add it and output pattern
        if (dict_idx == 2**l) begin
          dict[dict_idx] = pattern_idx;
          compressed_block[block_idx][i:l-1+i] = pattern_idx;
        // If pattern is in dictionary, output dictionary index
        end else begin
          compressed_block[block_idx][i:l-1+i] = dict_idx;
        end
      end
    end
    // Store compressed memory array
    for (i = 0; i < m/k; i = i + 1) begin
      compressed_mem[i] = {compressed_block[i*2], compressed_block[i*2+1]};
    end
  end
end

// Decompression algorithm
always @ (posedge decomp_en or posedge reset) begin
  if (reset) begin
    // Reset dictionary and decompressed memory array
    for (i = 0; i < 2**l; i = i + 1) begin
      dict[i] = 0;
    end
    for (i = 0; i < n; i = i + 1) begin
      decompressed_mem[i] = 0;
    end
  end else if (decomp_en) begin
    // Read compressed memory array
    for (i = 0; i < m/k; i = i + 1) begin
      compressed_block[i*2] = compressed_mem[i][k-1:0];
      compressed_block[i*2+1] = compressed_mem[i][2*k-1:k];
    end
    // Decompress each block
    for (block_idx = 0; block_idx < n/k; block_idx = block_idx + 1) begin
      // Replace dictionary indices with repeating patterns
      for (i = 0; i < k-l+1; i = i + 1) begin
        dict_idx = compressed_block[block_idx][i:l-1+i];
        if (dict_idx == 0) begin
          decompressed_mem[block_idx*k+i:k-1+block_idx*k+i] = 0;
        end else begin
          decompressed_mem[block_idx*k+i:k-1+block_idx*k+i] = dict[dict_idx];
        end
      end
    end
    // Output decompressed memory array
    out_decomp = decompressed_mem;
  end
end

// Output compressed memory array
assign out = compressed_mem;

endmodule

