module seq_sum(
    input signed [31:0] off,
    input [2:0] n,
    output reg signed [31:0] sum
);

    integer i;
    reg signed [31:0] prev1, prev2;

    always @(*) begin
        prev1 = off;
        prev2 = 0;
        sum = off;
        for(i = 3; i <= n; i = i + 1) begin
            sum = sum + prev1 + prev2;
            prev2 = prev1;
            prev1 = sum - prev2;
        end
    end

endmodule

module parity_generator (
    input [7:0] in,
    output parity);

    wire [3:0] sum;
    wire carry;

    // Full adder implementation
    full_adder fa0 (.a(in[0]), .b(in[1]), .c(1'b0), .sum(sum[0]), .carry(carry));
    full_adder fa1 (.a(in[2]), .b(in[3]), .c(1'b0), .sum(sum[1]), .carry(carry));
    full_adder fa2 (.a(in[4]), .b(in[5]), .c(1'b0), .sum(sum[2]), .carry(carry));
    full_adder fa3 (.a(in[6]), .b(in[7]), .c(1'b0), .sum(sum[3]), .carry(carry));

    // Multiplexer implementation
    assign parity = (sum[0] ^ sum[1] ^ sum[2] ^ sum[3]) ? 1'b0 : 1'b1;

endmodule

