module shift_mult(
    input [7:0] in1,
    input [7:0] in2,
    input clk,
    input reset,
    output reg out_reg
);

reg [15:0] shift_reg;
reg [7:0] shifted_in2;
wire [15:0] mult_out;

// Shift register
always @(posedge clk) begin
    if (reset) begin
        shift_reg <= 16'b0;
    end else begin
        shift_reg <= {shift_reg[14:0], in1};
    end
end

// Shift and multiply circuit
always @(posedge clk) begin
    if (reset) begin
        shifted_in2 <= 8'b0;
    end else begin
        shifted_in2 <= {in2[7:4], 4'b0};
    end
end

assign mult_out = shifted_in2 * in1;

// Control logic
always @(posedge clk) begin
    if (reset) begin
        out_reg <= 1'b0;
    end else begin
        if (shift_reg[15]) begin
            out_reg <= mult_out[15:8];
        end else begin
            out_reg <= 1'b0;
        end
    end
end

endmodule

