module psd_counter (
  input clk,
  input s_axis_tvalid,
  input [31:0] s_axis_tdata,
  output reg m_axis_tvalid,
  output reg [31:0] m_axis_tdata,
  output reg [PERIOD_WIDTH+1:0] addr,
  output reg [N_CYCLES_WIDTH-1:0] cycle_index,
  output reg first_cycle,
  output reg last_cycle
);

  parameter integer PERIOD = 64;
  parameter integer PERIOD_WIDTH = 6;
  parameter integer N_CYCLES = 8;
  parameter integer N_CYCLES_WIDTH = 3;

  reg [PERIOD_WIDTH-1:0] count;
  reg [N_CYCLES_WIDTH-1:0] cycle_count;

  always @(posedge clk) begin
    if (s_axis_tvalid) begin
      count <= s_axis_tdata[PERIOD_WIDTH-1:0];
      cycle_count <= s_axis_tdata[N_CYCLES_WIDTH+PERIOD_WIDTH-1:N_CYCLES_WIDTH];
    end
    else begin
      count <= count + 1;
      if (count == PERIOD-1) begin
        count <= 0;
        cycle_count <= cycle_count + 1;
        if (cycle_count == N_CYCLES) begin
          cycle_count <= 0;
        end
      end
    end
  end

  assign addr = {cycle_count, count};
  assign cycle_index = cycle_count;
  assign first_cycle = (cycle_count == 0);
  assign last_cycle = (cycle_count == N_CYCLES-1);

  always @(posedge clk) begin
    if (count == PERIOD-1 && cycle_count != N_CYCLES-1) begin
      m_axis_tvalid <= 1;
      m_axis_tdata <= s_axis_tdata;
    end
    else begin
      m_axis_tvalid <= 0;
    end
  end

endmodule

module top_module(
    input wire clk,
    input wire areset,  // async active-high reset to zero
    input wire load,
    input wire ena,
    input wire [31:0] in,
    output wire [31:0] out_xor,
    output wire [31:0] out_and,
    output wire [3:0] q,
    output wire [3:0] out_or);

    wire [31:0] xor_out;
    wire [31:0] and_out;
    wire [3:0] shift_out;
    wire [31:0] or_in;

    // Instantiate XOR and AND gates
    xor_gate xor_inst(.in(in), .out(xor_out));
    and_gate and_inst(.in(in), .out(and_out));

    // Instantiate shift register
    shift_register shift_inst(.clk(clk), .areset(areset), .load(load), .ena(ena), .in(xor_out), .q(q), .out(shift_out));

    // Instantiate OR gate
    or_gate or_inst(.in1(xor_out), .in2(and_out), .out(or_in));

    // Output signals
    assign out_xor = xor_out;
    assign out_and = and_out;
    assign out_or = or_in;

endmodule

// XOR gate
module xor_gate(
    input wire [31:0] in,
    output wire [31:0] out);

    assign out = in[31:16] ^ in[15:0];

endmodule

// AND gate
module and_gate(
    input wire [31:0] in,
    output wire [31:0] out);

    assign out = in[31:16] & in[15:0];

endmodule

// Shift register
module shift_register(
    input wire clk,
    input wire areset,
    input wire load,
    input wire ena,
    input wire [31:0] in,
    output wire [3:0] q,
    output wire [31:0] out);

    reg [3:0] q_reg;
    reg [31:0] out_reg;

    always @(posedge clk or negedge areset) begin
        if (areset == 0) begin
            q_reg <= 4'b0;
            out_reg <= 32'b0;
        end else if (load == 1 && ena == 1) begin
            q_reg <= in[3:0];
            out_reg <= in;
        end else if (ena == 1) begin
            q_reg <= {q_reg[2:0], in[0]};
            out_reg <= {q_reg, in[31:4]};
        end
    end

    assign q = q_reg;
    assign out = out_reg;

endmodule

// OR gate
module or_gate(
    input wire [31:0] in1,
    input wire [31:0] in2,
    output wire [31:0] out);

    assign out = in1 | in2;

endmodule

module shift_reg_bcd_counter (
    input clk,
    input reset,
    input [7:0] d,
    input enable_3,
    input enable_2,
    input enable_1,
    output [6:0] seg,
    output reg dp
);

reg [3:0] bcd_counter [0:3];
reg [7:0] shift_reg;
reg [2:0] digit_select;

always @(posedge clk) begin
    if (reset) begin
        shift_reg <= 8'b0;
        bcd_counter <= 4'd0;
        digit_select <= 3'b0;
    end else begin
        // Shift register
        shift_reg <= {shift_reg[6:0], d[7]};

        // BCD counter
        if (enable_1) begin
            bcd_counter[0] <= bcd_counter[0] + 1;
            if (bcd_counter[0] == 10) begin
                bcd_counter[0] <= 4'd0;
                bcd_counter[1] <= bcd_counter[1] + 1;
            end
        end
        if (enable_2) begin
            bcd_counter[2] <= bcd_counter[2] + 1;
            if (bcd_counter[2] == 10) begin
                bcd_counter[2] <= 4'd0;
                bcd_counter[3] <= bcd_counter[3] + 1;
            end
        end
        if (enable_3) begin
            bcd_counter[3] <= bcd_counter[3] + 1;
            if (bcd_counter[3] == 10) begin
                bcd_counter[3] <= 4'd0;
            end
        end

        // Digit select
        digit_select <= digit_select + 1;
        if (digit_select == 3'b100) begin
            digit_select <= 3'b000;
        end
    end
end

// Output
always @(digit_select or bcd_counter or shift_reg) begin
    case (digit_select)
        3'b000: seg = {1'b0, bcd_counter[3][3:0]};
        3'b001: seg = {1'b0, bcd_counter[2][3:0]};
        3'b010: seg = {1'b0, bcd_counter[1][3:0]};
        3'b011: seg = {1'b0, bcd_counter[0][3:0]};
        3'b100: seg = {1'b0, shift_reg[6:4]};
    endcase

    dp = (digit_select == 3'b011) ? 1'b1 : 1'b0;
end

endmodule

