module axi_bram_controller
   (s_axi_aclk,
    s_axi_aresetn,
    s_axi_awvalid,
    s_axi_awready,
    s_axi_awaddr,
    s_axi_awlen,
    s_axi_awburst,
    s_axi_awid,
    s_axi_wdata,
    s_axi_wstrb,
    s_axi_wlast,
    s_axi_wvalid,
    s_axi_wready,
    s_axi_bready,
    s_axi_bvalid,
    s_axi_bid,
    s_axi_arvalid,
    s_axi_arready,
    s_axi_araddr,
    s_axi_arlen,
    s_axi_arburst,
    s_axi_arid,
    s_axi_rready,
    s_axi_rvalid,
    s_axi_rdata,
    s_axi_rid,
    s_axi_rlast);

  parameter ADDR_WIDTH = 11;
  parameter DATA_WIDTH = 32;

  localparam STATE_IDLE = 2'b00;
  localparam STATE_WRITE_ADDR = 2'b01;
  localparam STATE_WRITE_DATA = 2'b10;
  localparam STATE_READ_ADDR = 2'b11;

  reg [2:0] state;
  reg [DATA_WIDTH-1:0] mem [0:(1<<ADDR_WIDTH)-1];
  reg [ADDR_WIDTH-1:0] write_addr;
  reg [ADDR_WIDTH-1:0] read_addr;
  reg [DATA_WIDTH-1:0] write_data;
  reg [DATA_WIDTH-1:0] read_data;
  reg [ADDR_WIDTH-1:0] read_addr_next;
  reg [ADDR_WIDTH-1:0] write_addr_next;
  reg [DATA_WIDTH-1:0] write_data_next;
  reg [ADDR_WIDTH-1:0] read_addr_next;
  reg [ADDR_WIDTH-1:0] write_addr_next;
  reg [DATA_WIDTH-1:0] write_data_next;

  always @(posedge s_axi_aclk) begin
    if (!s_axi_aresetn) begin
      state <= STATE_IDLE;
      write_addr <= 0;
      read_addr <= 0;
      write_data <= 0;
      read_data <= 0;
    end else begin
      case (state)
        STATE_IDLE: begin
          if (s_axi_awvalid && s_axi_awready) begin
            write_addr_next <= s_axi_awaddr;
            state <= STATE_WRITE_ADDR;
          end else if (s_axi_arvalid && s_axi_arready) begin
            read_addr_next <= s_axi_araddr;
            state <= STATE_READ_ADDR;
          end
        end
        STATE_WRITE_ADDR: begin
          if (s_axi_wvalid && s_axi_wready) begin
            write_data_next <= s_axi_wdata;
            state <= STATE_WRITE_DATA;
          end
        end
        STATE_WRITE_DATA: begin
          if (s_axi_bvalid && s_axi_bready) begin
            write_addr <= write_addr_next;
            write_data <= write_data_next;
            state <= STATE_IDLE;
          end
        end
        STATE_READ_ADDR: begin
          if (s_axi_rvalid && s_axi_rready) begin
            read_data <= mem[read_addr_next];
            read_addr <= read_addr_next;
            state <= STATE_IDLE;
          end
        end
      endcase
    end
  end

  assign s_axi_awready = (state == STATE_IDLE);
  assign s_axi_wready = (state == STATE_WRITE_DATA);
  assign s_axi_bvalid = (state == STATE_WRITE_DATA);
  assign s_axi_bresp = 2'b00;
  assign s_axi_arready = (state == STATE_IDLE);
  assign s_axi_rvalid = (state == STATE_IDLE);
  assign s_axi_rdata = read_data;
  assign s_axi_rid = s_axi_arid;
  assign s_axi_rlast = 1'b1;

  always @(posedge s_axi_aclk) begin
    if (!s_axi_aresetn) begin
      mem <= 0;
    end else begin
      if (s_axi_wvalid && s_axi_wready) begin
        mem[s_axi_awaddr] <= s_axi_wdata;
      end
    end
  end

  assign s_axi_bid = s_axi_awid;
  assign s_axi_bready = 1'b1;

endmodule

