module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [3:0] BIN,  // Input for the binary-to-BCD converter
    input select,     // Select input to choose between counter and converter output
    output [7:0] sum  // Output from the functional module
);

    // Instantiate the binary-to-BCD converter module
    binary_to_bcd_converter bcd_converter(
        .bin(BIN),
        .bcd0(bcd0),
        .bcd1(bcd1)
    );

    // Instantiate the binary counter module
    binary_counter counter(
        .clk(clk),
        .reset(reset),
        .count(count)
    );

    // Functional module to calculate the sum of BCD and count
    always @ (posedge clk) begin
        if (reset) begin
            sum <= 0;
        end else begin
            if (select) begin
                sum <= count + {4'b0, bcd1, bcd0};
            end else begin
                sum <= {4'b0, bcd1, bcd0};
            end
        end
    end

    // Declare internal wires
    wire [3:0] bcd0;
    wire [3:0] bcd1;
    wire [7:0] count;

endmodule

