module decoder (
    input A, B, C, EN,
    output reg Y0, Y1, Y2, Y3, Y4, Y5, Y6, Y7
);

reg [2:0] A_reg, B_reg, C_reg;
reg [7:0] Y_reg;

always @(posedge EN) begin
    A_reg <= A;
    B_reg <= B;
    C_reg <= C;
    Y_reg <= 8'b0;
end

always @(posedge EN) begin
    case ({A_reg, B_reg, C_reg})
        3'b000: Y_reg[0] <= 1'b1;
        3'b001: Y_reg[1] <= 1'b1;
        3'b010: Y_reg[2] <= 1'b1;
        3'b011: Y_reg[3] <= 1'b1;
        3'b100: Y_reg[4] <= 1'b1;
        3'b101: Y_reg[5] <= 1'b1;
        3'b110: Y_reg[6] <= 1'b1;
        3'b111: Y_reg[7] <= 1'b1;
    endcase
end

assign Y0 = Y_reg[0];
assign Y1 = Y_reg[1];
assign Y2 = Y_reg[2];
assign Y3 = Y_reg[3];
assign Y4 = Y_reg[4];
assign Y5 = Y_reg[5];
assign Y6 = Y_reg[6];
assign Y7 = Y_reg[7];

endmodule

module ram_32x32_dp_be (
	data_a,
	wren_a,
	address_a,
	data_b,
	address_b,
	wren_b,
	byteena_a,
	clock_a,
	clock_b,
	q_a,
	q_b);

	input	[31:0]  data_a;
	input	  wren_a;
	input	[4:0]  address_a;
	input	[31:0]  data_b;
	input	[4:0]  address_b;
	input	  wren_b;
	input	[3:0]  byteena_a;
	input	  clock_a;
	input	  clock_b;
	output	[31:0]  q_a;
	output	[31:0]  q_b;

	reg [31:0] memory [31:0];

	// Port A
	always @(posedge clock_a) begin
		if (wren_a) begin
			if (byteena_a[0]) memory[address_a][7:0] <= data_a[7:0];
			if (byteena_a[1]) memory[address_a][15:8] <= data_a[15:8];
			if (byteena_a[2]) memory[address_a][23:16] <= data_a[23:16];
			if (byteena_a[3]) memory[address_a][31:24] <= data_a[31:24];
		end
		q_a <= memory[address_a];
	end

	// Port B
	always @(posedge clock_b) begin
		if (wren_b) begin
			memory[address_b] <= data_b;
		end
		q_b <= memory[address_b];
	end

endmodule

