module RLE (
  input [n-1:0] in,
  input select,
  output [m-1:0] out
);

parameter n = 8; // number of input signals
parameter m = 8; // number of output signals

reg [n-1:0] in_reg;
reg [m-1:0] out_reg;
reg [n-1:0] symbol;
reg [n-1:0] count;
reg [n-1:0] index;
reg [n-1:0] i;

always @ (posedge select) begin
  if (select) begin // Encoding mode
    index <= 0;
    i <= 0;
    symbol <= in[0];
    count <= 1;
    for (i = 1; i < n; i = i + 1) begin
      if (in[i] == symbol) begin
        count <= count + 1;
      end else begin
        out_reg[index] <= count;
        out_reg[index+1] <= symbol;
        index <= index + 2;
        symbol <= in[i];
        count <= 1;
      end
    end
    out_reg[index] <= count;
    out_reg[index+1] <= symbol;
    out <= out_reg;
  end else begin // Decoding mode
    index <= 0;
    i <= 0;
    while (index < m) begin
      count <= out[index];
      symbol <= out[index+1];
      for (i = 0; i < count; i = i + 1) begin
        in_reg[index+i] <= symbol;
      end
      index <= index + 2;
    end
    out <= in_reg;
  end
end

endmodule

