module cpu_write_controller(
  input         ff_wr_pend,
  input         hreset_n,
  input         cpu_wr_gnt,
  input         crt_req,
  input         svga_ack,
  input         mem_clk,
  output reg    cpu_wr_req,
  output        cpu_wr_svga_req,
  output        enwr_cpu_ad_da_pl,
  output        cpu_fifo_read,
  output reg    int_cpu_fifo_rd,
  output        cpu_mem_wr,
  output reg    cpu_arb_wr
);

  reg [2:0] current_state;
  reg [2:0] next_state;
  reg en_cpu_fifo_read;
  reg wen;
  reg int_cpu_wr_svga_req;

  wire t32;
  wire t34;

  parameter cpuwr_state0 = 3'b000,
             cpuwr_state1 = 3'b001,
             cpuwr_state2 = 3'b011,
             cpuwr_state3 = 3'b111,
             cpuwr_state4 = 3'b110;

  assign t32 = (ff_wr_pend & (~crt_req));
  assign t34 = ((~ff_wr_pend) | crt_req);

  assign cpu_fifo_read = ff_wr_pend & en_cpu_fifo_read;  
  assign enwr_cpu_ad_da_pl = ff_wr_pend & en_cpu_fifo_read;
  assign cpu_wr_svga_req  = int_cpu_wr_svga_req & ff_wr_pend;

  assign cpu_mem_wr = cpu_wr_req;

  always @ (posedge mem_clk or negedge hreset_n) begin
    if (hreset_n == 0) current_state = cpuwr_state0;
    else current_state = next_state;
  end

  always @* begin
    cpu_wr_req          = 1'b0;
    int_cpu_wr_svga_req = 1'b0;
    int_cpu_fifo_rd     = 1'b0;
    en_cpu_fifo_read    = 1'b0;
    cpu_arb_wr          = 1'b0;

    case(current_state)
      cpuwr_state0: next_state = (ff_wr_pend) ? cpuwr_state1 : cpuwr_state0;
      cpuwr_state1: begin
        cpu_wr_req = 1'b1;
        next_state = (cpu_wr_gnt) ? cpuwr_state2 : cpuwr_state1;
      end
      cpuwr_state2: begin
        cpu_arb_wr = 1'b1;
        cpu_wr_req = 1'b1;
        int_cpu_wr_svga_req = 1'b1;
        int_cpu_fifo_rd = 1'b1;
        if (svga_ack) next_state = cpuwr_state3;
        else next_state = cpuwr_state2;
      end
      cpuwr_state3: begin
        cpu_wr_req = 1'b1;
        cpu_arb_wr = 1'b1;
        en_cpu_fifo_read = 1'b1;
        next_state = cpuwr_state4;
      end
      cpuwr_state4: begin
        cpu_wr_req = 1'b1;
        cpu_arb_wr = 1'b1;
        if (t34) next_state = cpuwr_state0;
        else if (t32) next_state = cpuwr_state2;
        else next_state = cpuwr_state4;
      end
    endcase
  end   

endmodule

module mbus_int_ctrl
  (
    input	CLKIN,
    input	RESETn,
    input	MBC_ISOLATE,
    input	SC_CLR_BUSY,
    input	MBUS_CLR_BUSY,
    input	REQ_INT, 
    input	MBC_SLEEP,
    input	LRC_SLEEP,
    output reg	EXTERNAL_INT_TO_WIRE, 
    output reg	EXTERNAL_INT_TO_BUS, 
    input	CLR_EXT_INT
   );

   reg 		clr_busy_temp;
   reg 		BUS_BUSYn;
   wire RESETn_BUSY = ((~clr_busy_temp) & (~SC_CLR_BUSY));

   // Use SRFF to set BUS_BUSYn signal
   always @ (negedge CLKIN or negedge RESETn or negedge RESETn_BUSY) begin
      // set port
      if (~RESETn)
	BUS_BUSYn <= 1;
      // reset port
      else if (~CLKIN)
	BUS_BUSYn <= 0;
      // clk port
      else
	BUS_BUSYn <= 1;
   end

   // Set clr_busy_temp signal based on MBC_ISOLATE and MBUS_CLR_BUSY inputs
   always @ * begin
      if (MBC_ISOLATE == 1'b1)
	clr_busy_temp = 1'b0;
      else
	clr_busy_temp = MBUS_CLR_BUSY;
   end

   // Set EXTERNAL_INT_TO_WIRE signal
   always @ (posedge REQ_INT or negedge RESETn) begin
      if (~RESETn) begin
        EXTERNAL_INT_TO_WIRE <= 1'b0;
      end else begin
        case ({MBC_SLEEP, LRC_SLEEP})
          // Both in sleep
          {1'b1, 1'b1}: begin
            EXTERNAL_INT_TO_WIRE <= 1'b1;
          end
          // Both in sleep, BC is on, LC is off, only interrupt when the bus is not busy
          {1'b0, 1'b1}: begin
            if (BUS_BUSYn) begin
              EXTERNAL_INT_TO_WIRE <= 1'b1;
            end else begin
              EXTERNAL_INT_TO_WIRE <= 1'b0;
            end
          end
          // If both is on, doing nothing, BC is off, LC is on is a non-exist state
          default: begin
            EXTERNAL_INT_TO_WIRE <= 1'b0;
          end
        endcase
      end
   end

   // Set EXTERNAL_INT_TO_BUS signal
   always @ (posedge REQ_INT or negedge RESETn or negedge CLR_EXT_INT) begin
      if (~RESETn) begin
        EXTERNAL_INT_TO_BUS <= 1'b0;
      end else begin
        case ({MBC_SLEEP, LRC_SLEEP})
          // Both in sleep
          {1'b1, 1'b1}: begin
            EXTERNAL_INT_TO_BUS <= 1'b1;
          end
          // Both in sleep, BC is on, LC is off, only interrupt when the bus is not busy
          {1'b0, 1'b1}: begin
            if (BUS_BUSYn) begin
              EXTERNAL_INT_TO_BUS <= 1'b1;
            end else begin
              EXTERNAL_INT_TO_BUS <= 1'b0;
            end
          end
          // If both is on, doing nothing, BC is off, LC is on is a non-exist state
          default: begin
            EXTERNAL_INT_TO_BUS <= 1'b0;
          end
        endcase
      end
   end

endmodule

module counter_4bit (clk, rst, ctrl, out);

    input clk, rst, ctrl;
    output reg [3:0] out;

    always @(posedge clk) begin
        if (rst) begin
            out <= 4'b0000;
        end else begin
            if (ctrl) begin
                if (out == 4'b1111) begin
                    out <= 4'b0000;
                end else begin
                    out <= out + 1;
                end
            end else begin
                if (out == 4'b0000) begin
                    out <= 4'b1111;
                end else begin
                    out <= out - 1;
                end
            end
        end
    end

endmodule

module adder (
  input [3:0] A,
  input [3:0] B,
  input C,
  output reg [3:0] S
);

  always @(*) begin
    if (C == 0) begin
      S = A + B;
    end else begin
      S = A - B;
    end
  end

endmodule

module testbench;

  reg [3:0] A;
  reg [3:0] B;
  reg C;
  wire [3:0] S;

  adder dut (
    .A(A),
    .B(B),
    .C(C),
    .S(S)
  );

  initial begin
    A = 4'b0101;
    B = 4'b0011;
    C = 0;
    #10;
    if (S !== 4'b1000) $fatal("Error: Addition of two positive numbers failed");

    A = 4'b0101;
    B = 4'b0011;
    C = 1;
    #10;
    if (S !== 4'b0010) $fatal("Error: Subtraction of two positive numbers failed");

    A = 4'b0101;
    B = 4'b1100;
    C = 0;
    #10;
    if (S !== 4'b0001) $fatal("Error: Addition of a positive and a negative number failed");

    A = 4'b0101;
    B = 4'b1100;
    C = 1;
    #10;
    if (S !== 4'b1001) $fatal("Error: Subtraction of a positive and a negative number failed");

    $display("All tests passed");
