module LED_controller
(
    input s00_axi_aclk,
    input s00_axi_aresetn,
    input s00_axi_arvalid,
    input [1:0]s00_axi_araddr,
    input s00_axi_rready,
    input s00_axi_awvalid,
    input [1:0]s00_axi_awaddr,
    input s00_axi_wvalid,
    input [31:0]s00_axi_wdata,
    input [3:0]s00_axi_wstrb,
    input s00_axi_bready,
    output s00_axi_rvalid,
    output [31:0]s00_axi_rdata,
    output s00_axi_bvalid,
    output S_AXI_ARREADY,
    output S_AXI_AWREADY,
    output S_AXI_WREADY,
    output [7:0]LEDs_out
);

    reg [7:0] LED_values;
    wire [7:0] LEDs_out;
    reg [31:0] rdata;
    reg rvalid;
    reg bvalid;
    reg [1:0] awaddr;
    reg [31:0] wdata;
    reg [3:0] wstrb;
    reg [7:0] LED_write_enable;

    parameter LED_WIDTH = 1;
    parameter NUM_LEDS = 8;

    // Read address decoder
    assign S_AXI_ARREADY = 1;
    always @(posedge s00_axi_aclk) begin
        if (s00_axi_aresetn == 0) begin
            rvalid <= 0;
            rdata <= 0;
        end
        else if (s00_axi_arvalid && s00_axi_rready) begin
            case (s00_axi_araddr)
                2'b00: begin
                    rvalid <= 1;
                    rdata <= LED_values[0];
                end
                2'b01: begin
                    rvalid <= 1;
                    rdata <= LED_values[1];
                end
                2'b10: begin
                    rvalid <= 1;
                    rdata <= LED_values[2];
                end
                2'b11: begin
                    rvalid <= 1;
                    rdata <= LED_values[3];
                end
            endcase
        end
    end

    // Write address decoder
    assign S_AXI_AWREADY = 1;
    always @(posedge s00_axi_aclk) begin
        if (s00_axi_aresetn == 0) begin
            bvalid <= 0;
            awaddr <= 0;
            wdata <= 0;
            wstrb <= 0;
        end
        else if (s00_axi_awvalid && s00_axi_wvalid && s00_axi_wready) begin
            case (s00_axi_awaddr)
                2'b00: begin
                    awaddr <= 2'b00;
                    wdata <= s00_axi_wdata[0];
                    wstrb <= s00_axi_wstrb[0];
                end
                2'b01: begin
                    awaddr <= 2'b01;
                    wdata <= s00_axi_wdata[0];
                    wstrb <= s00_axi_wstrb[0];
                end
                2'b10: begin
                    awaddr <= 2'b10;
                    wdata <= s00_axi_wdata[0];
                    wstrb <= s00_axi_wstrb[0];
                end
                2'b11: begin
                    awaddr <= 2'b11;
                    wdata <= s00_axi_wdata[0];
                    wstrb <= s00_axi_wstrb[0];
                end
            endcase
        end
    end

    // Write data
    assign S_AXI_WREADY = 1;
    always @(posedge s00_axi_aclk) begin
        if (s00_axi_aresetn == 0) begin
            LED_write_enable <= 0;
        end
        else if (s00_axi_awvalid && s00_axi_wvalid && s00_axi_wready) begin
            if (wstrb[0] == 1) begin
                LED_write_enable[0] <= s00_axi_wdata[0];
            end
            if (wstrb[1] == 1) begin
                LED_write_enable[1] <= s00_axi_wdata[1];
            end
            if (wstrb[2] == 1) begin
                LED_write_enable[2] <= s00_axi_wdata[2];
            end
            if (wstrb[3] == 1) begin
                LED_write_enable[3] <= s00_axi_wdata[3];
            end
        end
    end

    // Output LEDs
    assign LEDs_out = LED_values;
    always @(posedge s00_axi_aclk) begin
        if (s00_axi_aresetn == 0) begin
            LED_values <= 0;
        end
        else begin
            if (LED_write_enable[0] == 1) begin
                LED_values[0] <= 1;
            end
            if (LED_write_enable[1] == 1) begin
                LED_values[1] <= 1;
            end
            if (LED_write_enable[2] == 1) begin
                LED_values[2] <= 1;
            end
            if (LED_write_enable[3] == 1) begin
                LED_values[3] <= 1;
            end
        end
    end

    // Write response
    always @(posedge s00_axi_aclk) begin
        if (s00_axi_aresetn == 0) begin
            bvalid <= 0;
        end
        else if (s00_axi_awvalid && s00_axi_wvalid && s00_axi_wready) begin
            bvalid <= 1;
        end
    end
    assign s00_axi_bvalid = bvalid;

    // Read response
    assign s00_axi_rdata = rdata;
    assign s00_axi_rvalid = rvalid;

    // Output LEDs
    assign LEDs_out = LED_values;
endmodule

module tff_mux (
    input clk,    // Clocks are used in sequential circuits
    input d,      // Data input
    input [2:0] sel, // Select input to choose between 6 data inputs
    input [3:0] data0, // Six 4-bit data inputs
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output reg [3:0] q // 4-bit output from the selected data input stored in a T flip-flop
);

// Priority encoder to select the appropriate data input
wire [2:0] encoded_sel;
priority_encoder pe(sel, encoded_sel);

// Combinational logic to select the appropriate 4-bit data input
wire [3:0] selected_data;
assign selected_data = (encoded_sel == 0) ? data0 :
                       (encoded_sel == 1) ? data1 :
                       (encoded_sel == 2) ? data2 :
                       (encoded_sel == 3) ? data3 :
                       (encoded_sel == 4) ? data4 :
                       (encoded_sel == 5) ? data5 :
                       4'b1111; // Output 1 if sel is outside the range of 0 to 5

// Combinational circuit to generate the appropriate T input for the flip-flop
wire t = (d == 1) ? ~q : q;

// T flip-flop to store the selected 4-bit data input
always @(posedge clk) begin
    if (t == 1) q <= ~q;
end

endmodule

