module usb_rx_nrzi(
    input c_48,
    input vp,
    input vm,
    input oe,
    output d,
    output dv,
    output eop
);

localparam J   = 2'b10;
localparam K   = 2'b01;
localparam SE0 = 2'b00;

wire [1:0] rx;
sync #(2) input_sync(.in({vp, vm}), .clk(c_48), .out(rx));

localparam ST_IDLE = 4'd0;
localparam ST_INIT = 4'd1;
localparam ST_K    = 4'd2;
localparam ST_J    = 4'd3;
localparam ST_SE0  = 4'd4;
localparam ST_EOP  = 4'd5;
localparam ST_DONE = 4'd6;
localparam ST_ERROR = 4'd7;

localparam SW=4, CW=5;
reg [CW+SW-1:0] ctrl;
wire [SW-1:0] state;
wire [SW-1:0] next_state = ctrl[SW+CW-1:CW];
r #(SW) state_r
(.c(c_48), .rst(oe), .en(1'b1), .d(next_state), .q(state));

wire [1:0] cnt;
wire cnt_rst;
r #(2) cnt_r
(.c(c_48), .en(1'b1), .rst(cnt_rst), .d(cnt+1'b1), .q(cnt));

wire sample = cnt == 2'd1;

wire num_ones_en, num_ones_rst;
wire [2:0] num_ones;
r #(3) num_ones_r
(.c(c_48), .en(num_ones_en), .rst(state == ST_IDLE | (num_ones_rst & sample)), 
 .d(num_ones+1'b1), .q(num_ones));

always @* begin
    case (state)
        ST_IDLE:
            if (~oe & rx == K)      ctrl = { ST_INIT , 5'b00100 };
            else                    ctrl = { ST_IDLE , 5'b00000 };
        ST_INIT:
            if (sample)
                if (rx == K)          ctrl = { ST_K    , 5'b00001 };
                else                  ctrl = { ST_ERROR, 5'b00000 };
            else                    ctrl = { ST_INIT , 5'b00000 };
        ST_K:                     
            if (sample) begin
                if (rx == SE0)        ctrl = { ST_SE0  , 5'b00000 };
                else if (rx == K)     ctrl = { ST_K    , 5'b01011 };
                else if (rx == J)     ctrl = { ST_J    , 5'b10001 };
                else                  ctrl = { ST_ERROR, 5'b00000 };
            end else                ctrl = { ST_K    , 5'b00000 };
        ST_J:
            if (sample) begin
                if (rx == SE0)        ctrl = { ST_SE0  , 5'b00000 };
                else if (rx == J)     ctrl = { ST_J    , 5'b01011 };
                else if (rx == K)     ctrl = { ST_K    , 5'b10001 };
                else                  ctrl = { ST_ERROR, 5'b00000 };
            end else                ctrl = { ST_J    , 5'b00000 };
        ST_SE0:
            if (sample & rx == J)   ctrl = { ST_EOP  , 5'b00000 };
            else                    ctrl = { ST_SE0  , 5'b00000 };
        ST_EOP:
            if (sample)             ctrl = { ST_DONE , 5'b00000 };
            else                    ctrl = { ST_EOP  , 5'b00000 };
        ST_DONE:                  ctrl = { ST_IDLE , 5'b00000 };
        ST_ERROR:                 ctrl = { ST_ERROR, 5'b00000 };
        default:                  ctrl = { ST_IDLE , 5'b00000 };
    endcase
end

assign cnt_rst = ctrl[2];
assign dv = ctrl[0] & num_ones != 3'd6;
assign d  = ctrl[1];
assign num_ones_en = ctrl[3];
assign num_ones_rst = ctrl[4] | num_ones == 3'd6;
assign eop = state == ST_SE0;

endmodule

module arithmetic_module (
    input clk, reset,
    input [3:0] a, b,
    input [1:0] op,
    output reg [3:0] result
);

always @(posedge clk) begin
    if (reset) begin
        result <= 4'b0;
    end else begin
        case (op)
            2'b00: result <= a + b;
            2'b01: result <= a - b;
            2'b10: result <= a & b;
            default: result <= 4'b0;
        endcase
    end
end

endmodule

module d_ff_with_async_reset_set (
    Q    ,
    CLK  ,
    D    ,
    SCD  ,
    SCE  ,
    SET_B
);

    output Q    ;
    input  CLK  ;
    input  D    ;
    input  SCD  ;
    input  SCE  ;
    input  SET_B;

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    reg Q;

    always @(posedge CLK or negedge SCD or negedge SCE or negedge SET_B) begin
        if (SCD == 0) begin
            Q <= 0;
        end else if (SCE == 0) begin
            Q <= 1;
        end else if (SET_B == 0) begin
            Q <= 1;
        end else begin
            Q <= D;
        end
    end

endmodule

module divider(
  input [7:0] dividend,
  input [7:0] divisor,
  output reg [7:0] quotient,
  output reg [7:0] remainder
);

  integer i;

  always @(*) begin
    quotient = 8'b0;
    remainder = dividend;
    for (i = 0; i < 8; i = i + 1) begin
      remainder = remainder << 1;
      quotient = quotient << 1;
      quotient[0] = remainder[7];
      if (remainder >= divisor) begin
        remainder = remainder - divisor;
        quotient[0] = 1'b1;
      end
    end
  end

endmodule

module three_ff_module(/*AUTOARG*/
   // Outputs
   jbi_sctag_req_d1, scbuf_jbi_data_d1, jbi_scbuf_ecc_d1, 
   jbi_sctag_req_vld_d1, scbuf_jbi_ctag_vld_d1, scbuf_jbi_ue_err_d1, 
   sctag_jbi_iq_dequeue_d1, sctag_jbi_wib_dequeue_d1, 
   sctag_jbi_por_req_d1, so, 
   // Inputs
   jbi_sctag_req, scbuf_jbi_data, jbi_scbuf_ecc, jbi_sctag_req_vld, 
   scbuf_jbi_ctag_vld, scbuf_jbi_ue_err, sctag_jbi_iq_dequeue, 
   sctag_jbi_wib_dequeue, sctag_jbi_por_req, rclk, si, se
   );

   output [31:0]        jbi_sctag_req_d1;         
   output [31:0]        scbuf_jbi_data_d1;        
   output [6:0]         jbi_scbuf_ecc_d1;         
   output               jbi_sctag_req_vld_d1;     
   output               scbuf_jbi_ctag_vld_d1;
   output               scbuf_jbi_ue_err_d1;      
   output		sctag_jbi_iq_dequeue_d1;
   output		sctag_jbi_wib_dequeue_d1;
   output		sctag_jbi_por_req_d1;

   input [31:0]        jbi_sctag_req;         
   input [31:0]        scbuf_jbi_data;        
   input [6:0]         jbi_scbuf_ecc;         
   input               jbi_sctag_req_vld;     
   input               scbuf_jbi_ctag_vld;
   input               scbuf_jbi_ue_err;      
   input	       sctag_jbi_iq_dequeue;
   input	       sctag_jbi_wib_dequeue;
   input	       sctag_jbi_por_req;

   input		rclk;
   input		si, se;

   output		so;

   wire	int_scanout;

   // connect scanout of the last flop to int_scanout.
   // The output of the lockup latch is
   // the scanout of this dbb (so)

   bw_u1_scanlg_2x so_lockup(.so(so), .sd(int_scanout), .ck(rclk), .se(se));



   dff_s	#(32)	ff_flop_row0	(.q(jbi_sctag_req_d1[31:0]),
				 .din(jbi_sctag_req[31:0]),
				 .clk(rclk), .se(1'b0), .si(), .so() );

   dff_s	#(32)	ff_flop_row1	(.q(scbuf_jbi_data_d1[31:0]),
				 .din(scbuf_jbi_data[31:0]),
				 .clk(rclk), .se(1'b0), .si(), .so() );

   dff_s	#(13)	ff_flop_row2	(.q({  	jbi_scbuf_ecc_d1[6:0],
					jbi_sctag_req_vld_d1, 
					scbuf_jbi_ctag_vld_d1,
					scbuf_jbi_ue_err_d1,
					sctag_jbi_iq_dequeue_d1,
					sctag_jbi_wib_dequeue_d1,
					sctag_jbi_por_req_d1}),
				 .din({ jbi_scbuf_ecc[6:0],
					jbi_sctag_req_vld, 
					scbuf_jbi_ctag_vld,
					scbuf_jbi_ue_err,
					sctag_jbi_iq_dequeue,
					sctag_jbi_wib_dequeue,
					sctag_jbi_por_req}),
				 .clk(rclk), .se(1'b0), .si(), .so() );

endmodule

module maint_conflict_checker(
  input clk,
  input rst,
  input io_config_rd,
  input io_config_wr,
  input maint_idle_lcl,
  input maint_hit_busies_ns,
  output reg maint_rdy,
  output wire io_config_rd_delayed
);

  reg io_config_rd_r;
  reg io_config_rd_r1;

  always @(posedge clk) begin
    io_config_rd_r  <= io_config_rd;
    io_config_rd_r1 <= io_config_rd_r;
  end

  assign io_config_rd_delayed = (CWL >= 7) ? io_config_rd_r1 : io_config_rd_r;

  always @(posedge clk) begin
    if (rst) begin
      maint_rdy <= 1'b0;
    end else begin
      if (io_config_wr || maint_hit_busies_ns) begin
        maint_rdy <= 1'b0;
      end else if (!maint_idle_lcl) begin
        maint_rdy <= 1'b0;
      end else if (io_config_rd && io_config_rd_delayed) begin
        maint_rdy <= 1'b1;
      end
    end
  end

endmodule

module full_subtractor(input A, B, Bin, output R, Bout);

    wire not_B;
    wire temp1, temp2;

    assign not_B = ~B;
    assign temp1 = A ^ B;
    assign R = temp1 ^ Bin;
    assign temp2 = not_B & (temp1 ^ Bin);
    assign Bout = temp2 | (A & not_B);

endmodule


