module relational_module (
  input [(8 - 1):0] a,
  input [(8 - 1):0] b,
  output [(1 - 1):0] op,
  input clk,
  input ce,
  input clr
);

  // Declare internal wires and registers
  wire [(8 - 1):0] a_internal;
  wire [(8 - 1):0] b_internal;
  reg [(1 - 1):0] op_internal;

  // Assign inputs to internal wires
  assign a_internal = a;
  assign b_internal = b;

  // Reset output when clear signal is high
  always @(posedge clr) begin
    op_internal <= 1'b0;
  end

  // Compare inputs and update output when enable signal is high
  always @(posedge clk) begin
    if (ce) begin
      if (a_internal == b_internal) begin
        op_internal <= 1'b1;
      end else begin
        op_internal <= 1'b0;
      end
    end
  end

  // Assign internal output to module output
  assign op = op_internal;

endmodule

module top_module( 
    input [31:0] in,
    output [31:0] out ); 

    wire [15:0] reverse_out;
    wire [15:0] swap_out;

    byte_reverse reverse(.in(in), .out(reverse_out));
    byte_swap swap(.in(in), .out(swap_out));
    concat concat(.in1(reverse_out), .in2(swap_out), .out(out));

endmodule

module byte_reverse(
    input [31:0] in,
    output [31:0] out );

    wire [7:0] byte0;
    wire [7:0] byte1;
    wire [7:0] byte2;
    wire [7:0] byte3;

    assign byte0 = in[7:0];
    assign byte1 = in[15:8];
    assign byte2 = in[23:16];
    assign byte3 = in[31:24];

    wire [7:0] rev_byte0;
    wire [7:0] rev_byte1;
    wire [7:0] rev_byte2;
    wire [7:0] rev_byte3;

    assign rev_byte0 = byte3;
    assign rev_byte1 = byte2;
    assign rev_byte2 = byte1;
    assign rev_byte3 = byte0;

    wire [31:0] temp1;
    wire [31:0] temp2;

    assign temp1 = {rev_byte0, rev_byte1};
    assign temp2 = {rev_byte2, rev_byte3};

    wire [31:0] out_temp;

    assign out_temp = (in[31:16] == 16'h0) ? temp1 : temp2;

    assign out = out_temp;

endmodule

module byte_swap(
    input [31:0] in,
    output [31:0] out );

    wire [7:0] byte0;
    wire [7:0] byte1;
    wire [7:0] byte2;
    wire [7:0] byte3;

    assign byte0 = in[7:0];
    assign byte1 = in[15:8];
    assign byte2 = in[23:16];
    assign byte3 = in[31:24];

    wire [31:0] temp;

    assign temp = {byte3, byte1, byte2, byte0};

    assign out = temp;

endmodule

module concat(
    input [15:0] in1,
    input [15:0] in2,
    output [31:0] out );

    assign out = {in1, in2};

endmodule

module tlm_rx_data_snk_pwr_mgmt
  (
   input                 clk_i,
   input                 reset_i,

   // Power management signals for CMM
   output reg            pm_as_nak_l1_o,    // Pkt detected, implies src_rdy
   output reg            pm_turn_off_o,     // Pkt detected, implies src_rdy
   output reg            pm_set_slot_pwr_o, // Pkt detected, implies src_rdy
   output reg [9:0]      pm_set_slot_pwr_data_o, // value of field
   output reg            pm_msg_detect_o,   // grabbed a pm signal

   input                 ismsg_i,           // Packet data type
   input [7:0]           msgcode_i,         // message code
   input [9:0]           pwr_data_i,        // set slot value
   input                 eval_pwr_mgmt_i,   // grab the sideband fields
   input                 eval_pwr_mgmt_data_i, // get the data, if it exists
   input                 act_pwr_mgmt_i     // transmit the sideband fields
   );

  //-----------------------------------------------------------------------------
  // PCI Express constants
  //-----------------------------------------------------------------------------
  // Message code
  localparam             PM_ACTIVE_STATE_NAK       = 8'b0001_0100;
  localparam             PME_TURN_OFF              = 8'b0001_1001;
  localparam             SET_SLOT_POWER_LIMIT      = 8'b0101_0000;

  reg                    cur_pm_as_nak_l1;
  reg                    cur_pm_turn_off;
  reg                    cur_pm_set_slot_pwr;

  reg                    eval_pwr_mgmt_q1;
  reg                    eval_pwr_mgmt_data_q1;
  reg                    act_pwr_mgmt_q1;

  reg [9:0]              pm_set_slot_pwr_data_d1;

  // grab the fields at the beginning of the packet when known
  //----------------------------------------------------------
  always @(posedge clk_i) begin
    if (reset_i) begin
      cur_pm_as_nak_l1           <= #1 0;
      cur_pm_turn_off            <= #1 0;
      cur_pm_set_slot_pwr        <= #1 0;
    end else if (eval_pwr_mgmt_i) begin
      // ismsg is ANY message - malformed will are another modules
      // problem
      if (ismsg_i) begin
        cur_pm_as_nak_l1         <= #1 (msgcode_i == PM_ACTIVE_STATE_NAK);
        cur_pm_turn_off          <= #1 (msgcode_i == PME_TURN_OFF);
        cur_pm_set_slot_pwr      <= #1 (msgcode_i == SET_SLOT_POWER_LIMIT);

      // if we aren't a mesg, these can't be true
      end else begin
        cur_pm_as_nak_l1         <= #1 0;
        cur_pm_turn_off          <= #1 0;
        cur_pm_set_slot_pwr      <= #1 0;
      end
    end
  end

  // We need to know which packets we're dropping because we're
  //   already signalling them sideband
  // pipelined due to timing
  //------------------------------------------------------
  always @(posedge clk_i) begin
    if (reset_i) begin
      pm_msg_detect_o            <= #1 0;
    end else if (eval_pwr_mgmt_q1) begin
      pm_msg_detect_o            <= #1 cur_pm_as_nak_l1 ||
                                          cur_pm_turn_off  ||
                                          cur_pm_set_slot_pwr;
    end
  end


  // Data comes two cycles after the header fields, so we can't
  //   share the input latching fields
  // Furthermore, it will not go away until after eof_q2, so we
  //   can cheat on registers
  // Lastly, it does not imply activation, so we can always grab
  //   the field
  //-----------------------------------------------------------
  always @(posedge clk_i) begin
    if (eval_pwr_mgmt_data_i) begin
      pm_set_slot_pwr_data_d1 <= #1 pwr_data_i;
    end
    if (eval_pwr_mgmt_data_q1) begin
      pm_set_slot_pwr_data_o  <= #1 pm_set_slot_pwr_data_d1;
    end
  end

  // transmit sidebands when we know they are good for
  //   one cycle only
  always @(posedge clk_i) begin
    if (reset_i) begin
      pm_as_nak_l1_o         <= #1 0;
      pm_turn_off_o          <= #1 0;
      pm_set_slot_pwr_o      <= #1 0;
    // at this point, we know the packet is valid
    end else if (act_pwr_mgmt_i) begin
      pm_as_nak_l1_o         <= #1 cur_pm_as_nak_l1;
      pm_turn_off_o          <= #1 cur_pm_turn_off;
      pm_set_slot_pwr_o      <= #1 cur_pm_set_slot_pwr;
    // implies src_rdy, return to zero
    end else if (act_pwr_mgmt_q1) begin
      pm_as_nak_l1_o         <= #1 0;
      pm_turn_off_o          <= #1 0;
      pm_set_slot_pwr_o      <= #1 0;
    end
  end

  // Also need delayed version
  always @(posedge clk_i) begin
    if (reset_i) begin
      eval_pwr_mgmt_q1           <= #1 0;
      eval_pwr_mgmt_data_q1      <= #1 0;
      act_pwr_mgmt_q1            <= #1 0;
    end else begin
      eval_pwr_mgmt_q1           <= #1 eval_pwr_mgmt_i;
      eval_pwr_mgmt_data_q1      <= #1 eval_pwr_mgmt_data_i;
      act_pwr_mgmt_q1            <= #1 act_pwr_mgmt_i;
    end
  end

endmodule

