module uart_tx (
                 // inputs:
                  baud_divisor,
                  begintransfer,
                  clk,
                  clk_en,
                  do_force_break,
                  reset_n,
                  status_wr_strobe,
                  tx_data,
                  tx_wr_strobe,

                 // outputs:
                  tx_overrun,
                  tx_ready,
                  tx_shift_empty,
                  txd
               )
;

  output           tx_overrun;
  output           tx_ready;
  output           tx_shift_empty;
  output           txd;
  input   [  8: 0] baud_divisor;
  input            begintransfer;
  input            clk;
  input            clk_en;
  input            do_force_break;
  input            reset_n;
  input            status_wr_strobe;
  input   [  7: 0] tx_data;
  input            tx_wr_strobe;

  reg              baud_clk_en;
  reg     [  8: 0] baud_rate_counter;
  wire             baud_rate_counter_is_zero;
  reg              do_load_shifter;
  wire             do_shift;
  reg              pre_txd;
  wire             shift_done;
  wire    [  9: 0] tx_load_val;
  reg              tx_overrun;
  reg              tx_ready;
  reg              tx_shift_empty;
  wire             tx_shift_reg_out;
  wire    [  9: 0] tx_shift_register_contents;
  wire             tx_wr_strobe_onset;
  reg              txd;
  wire    [  9: 0] unxshiftxtx_shift_register_contentsxtx_shift_reg_outxx5_in;
  reg     [  9: 0] unxshiftxtx_shift_register_contentsxtx_shift_reg_outxx5_out;
  assign tx_wr_strobe_onset = tx_wr_strobe && begintransfer;
  assign tx_load_val = {{1 {1'b1}},
    tx_data,
    1'b0};

  assign shift_done = ~(|tx_shift_register_contents);
  always @(posedge clk or negedge reset_n)
    begin
      if (reset_n == 0)
          do_load_shifter <= 0;
      else if (clk_en)
          do_load_shifter <= (~tx_ready) && shift_done;
    end


  always @(posedge clk or negedge reset_n)
    begin
      if (reset_n == 0)
          tx_ready <= 1'b1;
      else if (clk_en)
          if (tx_wr_strobe_onset)
              tx_ready <= 0;
          else if (do_load_shifter)
              tx_ready <= -1;
    end


  always @(posedge clk or negedge reset_n)
    begin
      if (reset_n == 0)
          tx_overrun <= 0;
      else if (clk_en)
          if (status_wr_strobe)
              tx_overrun <= 0;
          else if (~tx_ready && tx_wr_strobe_onset)
              tx_overrun <= -1;
    end


  always @(posedge clk or negedge reset_n)
    begin
      if (reset_n == 0)
          tx_shift_empty <= 1'b1;
      else if (clk_en)
          tx_shift_empty <= tx_ready && shift_done;
    end


  always @(posedge clk or negedge reset_n)
    begin
      if (reset_n == 0)
          baud_rate_counter <= 0;
      else if (clk_en)
          if (baud_rate_counter_is_zero || do_load_shifter)
              baud_rate_counter <= baud_divisor;
          else 
            baud_rate_counter <= baud_rate_counter - 1;
    end


  assign baud_rate_counter_is_zero = baud_rate_counter == 0;
  always @(posedge clk or negedge reset_n)
    begin
      if (reset_n == 0)
          baud_clk_en <= 0;
      else if (clk_en)
          baud_clk_en <= baud_rate_counter_is_zero;
    end


  assign do_shift = baud_clk_en  && 
    (~shift_done) && 
    (~do_load_shifter);

  always @(posedge clk or negedge reset_n)
    begin
      if (reset_n == 0)
          pre_txd <= 1;
      else if (~shift_done)
          pre_txd <= tx_shift_reg_out;
    end


  always @(posedge clk or negedge reset_n)
    begin
      if (reset_n == 0)
          txd <= 1;
      else if (clk_en)
          txd <= pre_txd & ~do_force_break;
    end


  //_reg, which is an e_register
  always @(posedge clk or negedge reset_n)
    begin
      if (reset_n == 0)
          unxshiftxtx_shift_register_contentsxtx_shift_reg_outxx5_out <= 0;
      else if (clk_en)
          unxshiftxtx_shift_register_contentsxtx_shift_reg_outxx5_out <= unxshiftxtx_shift_register_contentsxtx_shift_reg_outxx5_in;
    end


  assign unxshiftxtx_shift_register_contentsxtx_shift_reg_outxx5_in = (do_load_shifter)? tx_load_val :
    (do_shift)? {1'b0,
    unxshiftxtx_shift_register_contentsxtx_shift_reg_outxx5_out[9 : 1]} :
    unxshiftxtx_shift_register_contentsxtx_shift_reg_outxx5_out;

  assign tx_shift_register_contents = unxshiftxtx_shift_register_contentsxtx_shift_reg_outxx5_out;
  assign tx_shift_reg_out = unxshiftxtx_shift_register_contentsxtx_shift_reg_outxx5_out[0];

endmodule

module dma_sequencer(
    input clk,
    input rst_n,
    input dma_req,
    input dma_rnw,
    input dma_ack,
    input dma_end,
    input [20:0] dma_addr,
    input [7:0] dma_wd,
    output [7:0] dma_rd,
    output reg [DEVNUM-1:0] req,
    output reg [DEVNUM-1:0] rnw,
    output reg [DEVNUM-1:0] done,
    output reg [DEVNUM-1:0] ack
);

parameter DEVNUM = 4;
parameter IDLE = 2'b00;
parameter READ = 2'b01;
parameter WRITE = 2'b10;
parameter COMPLETE = 2'b11;

reg [1:0] state;
reg [1:0] next_state;
reg [3:0] device_num;
reg [1:0] transfer_dir;
reg [20:0] transfer_addr;
reg [7:0] transfer_data;
reg [DEVNUM-1:0] in_progress;
reg [DEVNUM-1:0] completed;
reg [DEVNUM-1:0] last_ack;

assign dma_rd = (transfer_dir == READ) ? transfer_data : 8'hzz;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        device_num <= 0;
        transfer_dir <= 0;
        transfer_addr <= 0;
        transfer_data <= 0;
        in_progress <= 0;
        completed <= 0;
        last_ack <= 0;
    end else begin
        state <= next_state;
        device_num <= (next_state == IDLE) ? 0 : ((next_state == COMPLETE) ? device_num + 1 : device_num);
        transfer_dir <= (next_state == READ) ? 1 : ((next_state == WRITE) ? 2 : transfer_dir);
        transfer_addr <= (next_state == READ || next_state == WRITE) ? dma_addr : transfer_addr;
        transfer_data <= (next_state == WRITE) ? dma_wd : transfer_data;
        in_progress <= (next_state == READ || next_state == WRITE) ? in_progress | (1 << device_num) : in_progress;
        completed <= (next_state == COMPLETE) ? completed | (1 << device_num) : completed;
        last_ack <= (next_state == IDLE) ? 0 : ((next_state == COMPLETE) ? ack[device_num] : last_ack);
    end
end

always @(*) begin
    case (state)
        IDLE: begin
            next_state = (dma_req && !in_progress) ? READ : IDLE;
        end
        READ: begin
            next_state = (dma_end || !dma_req) ? ((transfer_dir == WRITE) ? WRITE : COMPLETE) : READ;
        end
        WRITE: begin
            next_state = (dma_end || !dma_req) ? COMPLETE : WRITE;
        end
        COMPLETE: begin
            next_state = (completed == ((1 << DEVNUM) - 1)) ? IDLE : COMPLETE;
        end
    endcase
end

assign req = (state == READ || state == WRITE) ? (1 << device_num) : 0;
assign rnw = (transfer_dir == READ) ? (1 << device_num) : ((transfer_dir == WRITE) ? ((1 << device_num) | last_ack) : 0);
assign done = (state == COMPLETE) ? (1 << device_num) : 0;
assign ack = (state == COMPLETE) ? 0 : ((state == READ || state == WRITE) ? ((1 << device_num) & in_progress) : 0);

endmodule

module top_module( 
    input [254:0] in,
    output [7:0] out );

    reg [7:0] count;
    reg [254:0] shift_reg;
    integer i;

    always @ (in) begin
        shift_reg <= in;
        count <= 8'b0;
        for (i = 0; i < 255; i = i + 1) begin
            if (shift_reg[0] == 1'b1) begin
                count <= count + 1;
            end
            shift_reg <= {shift_reg[253:0], 1'b0};
        end
    end

    assign out = count;

endmodule

module multiply_and_min (
    input clk,
    input reset,
    input [7:0] in1,
    input [7:0] in2,
    input [7:0] a, b, c, d,
    output [15:0] out,
    output [7:0] out_lo,
    output [7:0] final_out
);

    // Multiplication module
    reg [15:0] mult_result;
    reg [7:0] mult_lo;
    reg [3:0] i;
    always @ (posedge clk) begin
        if (reset) begin
            mult_result <= 16'b0;
            mult_lo <= 8'b0;
            i <= 4'b0;
        end else begin
            mult_result <= {8'b0, in1} * {8'b0, in2};
            for (i = 0; i < 8; i = i + 1) begin
                mult_result <= mult_result + (mult_lo << 8);
                mult_lo <= mult_result[7:0];
            end
        end
    end
    assign out = mult_result;
    assign out_lo = mult_lo;

    // Minimum value module
    reg [7:0] min_val;
    always @ (a or b or c or d) begin
        if (a <= b && a <= c && a <= d) begin
            min_val <= a;
        end else if (b <= c && b <= d) begin
            min_val <= b;
        end else if (c <= d) begin
            min_val <= c;
        end else begin
            min_val <= d;
        end
    end
    assign final_out = min_val + out_lo;

endmodule

module top_module (
    input clk,
    input reset,       // Synchronous active-high reset
    input [7:0] a,     // Input A for adder
    input [7:0] b,     // Input B for adder
    input [3:0] c,     // Input C for subtractor
    input [3:0] d,     // Input D for subtractor
    input select,      // Select input to choose between adder and subtractor
    output [7:0] out   // Output for the functional module
);

    // Instantiate the adder and subtractor modules
    adder_module adder_inst(.a(a), .b(b), .sum(sum_adder));
    subtractor_module subtractor_inst(.c(c), .d(d), .diff(diff_subtractor));

    // Control logic to select between adder and subtractor
    always @ (posedge clk) begin
        if (reset) begin
            adder_sel <= 1'b0;
        end else begin
            adder_sel <= select;
        end
    end

    // Functional module to produce final output
    always @ (posedge clk) begin
        if (reset) begin
            out <= 8'b0;
        end else begin
            if (adder_sel) begin
                out <= diff_subtractor;
            end else begin
                out <= sum_adder;
            end
        end
    end

endmodule

module serial_tx (
  input clk,
  input reset,
  input dtr,
  output reg tx
);

  parameter BAUD = 115200;

  localparam BITRATE = BAUD * 2;
  localparam FRAME = BITRATE * 11;
  localparam FRAME_WAIT = BITRATE * 4;

  reg [7:0] data;
  reg [3:0] state;
  reg [15:0] counter;

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      tx <= 0;
      state <= 0;
      counter <= 0;
    end else begin
      case (state)
        0: begin // idle
          if (dtr) begin
            state <= 1;
            counter <= FRAME_WAIT;
          end
        end
        1: begin // start bit
          tx <= 0;
          state <= 2;
          counter <= BITRATE;
        end
        2: begin // data bits
          tx <= data[0];
          data <= {data[6:0], dtr};
          state <= state + 1;
          counter <= BITRATE;
        end
        9: begin // stop bit
          tx <= 1;
          state <= 0;
          counter <= BITRATE;
        end
        default: begin // wait for next bit
          tx <= 1;
          state <= state + 1;
          counter <= BITRATE;
        end
      endcase
    end
  end

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      data <= 8'b0;
    end
  end

endmodule

module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,
    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out
); 

reg [7:0] input_reg [0:3];
reg [9:0] acc_reg [0:3];

integer i;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        for (i = 0; i < 4; i = i + 1) begin
            input_reg[i] <= 8'b0;
            acc_reg[i] <= 10'b0;
        end
        valid_b <= 1'b0;
        data_out <= 10'b0;
    end
    else begin
        for (i = 0; i < 4; i = i + 1) begin
            if (valid_a && ready_b) begin
                input_reg[i] <= data_in;
                acc_reg[i] <= acc_reg[i] + data_in;
            end
        end
        if (valid_a && ready_b) begin
            valid_b <= 1'b1;
        end
        if (valid_b && ready_a) begin
            for (i = 0; i < 4; i = i + 1) begin
                data_out[(i+1)*8-1:i*8] <= acc_reg[i][7:0];
                acc_reg[i] <= 10'b0;
                input_reg[i] <= 8'b0;
            end
            valid_b <= 1'b0;
        end
    end
end

assign ready_a = ~valid_b;

endmodule

module comparator (
