module PLL_Freq_Synth (
  input ref_clk,
  input [31:0] out_freq,
  input reset,
  output out_clk
);

parameter N = 10; // PLL multiplication factor
parameter M = 5; // PLL division factor
parameter C = 10; // Number of cycles for PLL to lock

reg [31:0] phase_accumulator;
reg [31:0] feedback_divider;
reg [31:0] locked_frequency;

integer counter;

always @(posedge ref_clk or posedge reset) begin
  if (reset) begin
    phase_accumulator <= 0;
    feedback_divider <= 0;
    locked_frequency <= 0;
    counter <= 0;
  end else begin
    feedback_divider <= phase_accumulator >> (N - M);
    phase_accumulator <= phase_accumulator + feedback_divider;
    counter <= counter + 1;
    if (counter >= C) begin
      locked_frequency <= ref_clk * N / M;
    end
  end
end

assign out_clk = locked_frequency;

endmodule

// DDS-Based Frequency Synthesizer
module DDS_Freq_Synth (
  input ref_clk,
  input [31:0] out_freq,
  input reset,
  output out_clk
);

parameter N = 12; // Number of bits in the phase accumulator
parameter M = 8; // Number of bits in the frequency tuning word

reg [N-1:0] phase_accumulator;
reg [M-1:0] frequency_tuning_word;
reg [31:0] sine_wave;

always @(posedge ref_clk or posedge reset) begin
  if (reset) begin
    phase_accumulator <= 0;
    frequency_tuning_word <= 0;
    sine_wave <= 0;
  end else begin
    frequency_tuning_word <= out_freq * (1 << M) / ref_clk;
    phase_accumulator <= phase_accumulator + frequency_tuning_word;
    sine_wave <= $sin(phase_accumulator);
  end
end

assign out_clk = ref_clk;
assign out_clk = sine_wave;

endmodule

