module carry_select_adder (
    input [7:0] a,
    input [7:0] b,
    output [7:0] sum,
    output carry_out
);

    wire [7:0] p;
    wire [7:0] g;
    wire [7:0] c;

    assign p = a ^ b;
    assign g = a & b;
    assign c[0] = 0;

    genvar i;
    generate
        for (i = 0; i < 8; i = i + 1) begin
            assign c[i+1] = (g[i] == 1) ? c[i] : (c[i] + p[i]);
        end
    endgenerate

    assign sum = p + c;
    assign carry_out = c[8];

endmodule

