module fsm_3bit_sequence_detection (
  input clk,
  input reset,
  input data,
  output reg match
);

  parameter S0 = 2'b00, S1 = 2'b01, S2 = 2'b10, S3 = 2'b11;
  reg [1:0] state, next_state;

  always @ (posedge clk, negedge reset) begin
    if (reset == 0) begin
      state <= S0;
      match <= 0;
    end
    else begin
      state <= next_state;
      match <= 0;
      case (state)
        S0: if (data == 1'b1) next_state <= S1; else next_state <= S0;
        S1: if (data == 1'b0) next_state <= S2; else if (data == 1'b1) next_state <= S1; else next_state <= S0;
        S2: if (data == 1'b1) next_state <= S3; else next_state <= S0;
        S3: begin
          next_state <= S0;
          match <= 1;
        end
      endcase
    end
  end

endmodule

