module uart_tx(
    input rst_n,
    input baud_clk,
    input tx_start,
    input [7:0] tx_data,
    output tx_enable,
    output tx_complete,
    output uart_tx
);

    // Internal state variables
    reg [3:0] tx_count;
    reg [7:0] tx_data_reg;
    reg tx_enable_reg;
    reg tx_complete_reg;
    reg uart_tx_reg;

    // Transmit enable logic
    always @ (negedge tx_start or negedge tx_complete_reg or negedge rst_n) begin
        if (!rst_n) begin
            tx_enable_reg <= 1'b0;
        end else if (!tx_complete_reg) begin
            tx_enable_reg <= 1'b0;
        end else if (!tx_start) begin
            tx_enable_reg <= 1'b1;
        end
    end
    assign tx_enable = tx_enable_reg;

    // Transmit completion logic
    always @ (negedge baud_clk or negedge tx_enable_reg or negedge rst_n) begin
        if (!rst_n) begin
            tx_complete_reg <= 1'b1;
        end else if (!tx_enable_reg) begin
            tx_complete_reg <= 1'b1;
        end else if (!baud_clk) begin
            if (!tx_count) begin
                tx_complete_reg <= 1'b0;
            end
        end
    end
    assign tx_complete = tx_complete_reg;

    // Transmit count logic
    always @ (posedge baud_clk or negedge rst_n) begin
        if (!rst_n) begin
            tx_count <= 4'd0;
        end else if (baud_clk) begin
            tx_count <= tx_count + 1;
        end
    end

    // Transmit data logic
    always @ (negedge baud_clk or negedge rst_n) begin
        if (!rst_n) begin
            uart_tx_reg <= 1'bz;
            tx_data_reg <= 8'dz;
        end else if (!baud_clk) begin
            case (tx_count)
                4'd1: begin
                    uart_tx_reg <= 1'b0;
                    tx_data_reg <= tx_data;
                end
                4'd2: uart_tx_reg <= tx_data_reg[0];
                4'd3: uart_tx_reg <= tx_data_reg[1];
                4'd4: uart_tx_reg <= tx_data_reg[2];
                4'd5: uart_tx_reg <= tx_data_reg[3];
                4'd6: uart_tx_reg <= tx_data_reg[4];
                4'd7: uart_tx_reg <= tx_data_reg[5];
                4'd8: uart_tx_reg <= tx_data_reg[6];
                4'd9: uart_tx_reg <= tx_data_reg[7];
                4'd0: uart_tx_reg <= 1'b1;
            endcase
        end
    end
    assign uart_tx = uart_tx_reg;

endmodule

