module top_module (
    input signed [3:0] A,
    input signed [3:0] B,
    input EN,
    output reg [15:0] Q,
    output reg C
);

    wire [3:0] abs_A, abs_B;
    wire eq, gt, lt;
    wire [1:0] sel;

    signed_mag_comp comp(.A(A), .B(B), .C(eq), .gt(gt), .lt(lt), .abs_A(abs_A), .abs_B(abs_B));
    decoder dec(.SEL(sel), .EN(EN), .Q(Q));

    always @(*) begin
        if (EN) begin
            if (eq) begin
                Q <= 16'b0000000000000001;
                C <= 1'b1;
            end else if (gt) begin
                Q <= {16'b0000000000000000, ~abs_A + 1};
                C <= 1'b0;
            end else if (lt) begin
                Q <= {16'b0000000000000000, abs_B};
                C <= 1'b0;
            end
        end else begin
            Q <= 16'b0000000000000000;
            C <= 1'b0;
        end
    end

    assign sel[1] = eq;
    assign sel[0] = gt;

endmodule


module signed_mag_comp (
    input signed [3:0] A,
    input signed [3:0] B,
    output reg eq,
    output reg gt,
    output reg lt,
    output reg [3:0] abs_A,
    output reg [3:0] abs_B
);

    always @(*) begin
        eq = (A == B);
        gt = (A > B);
        lt = (A < B);
        abs_A = (A < 0) ? (~A + 1) : A;
        abs_B = (B < 0) ? (~B + 1) : B;
    end

endmodule


module decoder (
    input [1:0] SEL,
    input EN,
    output reg [15:0] Q
);

    always @(SEL) begin
        case (SEL)
            2'b00: Q = 16'b0000000000000001;
            2'b01: Q = 16'b0000000000000010;
            2'b10: Q = 16'b0000000000000100;
            2'b11: Q = 16'b0000000000001000;
            default: Q = 16'b0000000000000000;
        endcase
    end

    always @(EN) begin
        if (!EN) begin
            Q <= 16'b0000000000000000;
        end
    end

endmodule

module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

wire [3:0] X;
wire [3:0] Y;
wire [3:0] Z;

assign X = A ^ B;
assign Y = A & B;
assign Z = Cin & X;

assign S = X ^ Cin;
assign Cout = (Y | Z) | (X & Cin);

endmodule

module echo_cancellation (
  input [n-1:0] in,
  input [m-1:0] ref,
  output [n-1:0] out
);

parameter n = 4; // number of input signals
parameter m = 2; // number of reference signals
parameter p = 3; // number of filter taps

reg [p-1:0] in_delay [n-1:0]; // delay elements for input signals
reg [p-1:0] ref_delay [m-1:0]; // delay elements for reference signals

// Delay input signals
always @(posedge clk) begin
  for (i = p-1; i >= 1; i = i - 1) begin
    in_delay[i][n-1:0] = in_delay[i-1][n-1:0];
  end
  in_delay[0][n-1:0] = in;
end

// Delay reference signals
always @(posedge clk) begin
  for (i = p-1; i >= 1; i = i - 1) begin
    ref_delay[i][m-1:0] = ref_delay[i-1][m-1:0];
  end
  ref_delay[0][m-1:0] = ref;
end

// Subtract delayed reference signals from delayed input signals
always @(posedge clk) begin
  for (i = 0; i < n; i = i + 1) begin
    out[i] = in_delay[p-1][i] - ref_delay[p-1][i];
  end
end

endmodule

