module shift_reg(
    input rx,
    output reg[(reg_length-1):0] shifted_bus,
    output reg finished_rx,
    input rst,
    input baud_clk
);

    parameter reg_length = 150;
    parameter IDLE = 2'b00, READING = 2'b01, FINISHED = 2'b10, FINISHED_AND_WAITING = 2'b11;
    parameter FINISHED_LENGTH = 7;

    reg[1:0] current_state, next_state;
    reg [(reg_length-1):0] bitShiftReg = {reg_length{1'b1}};
    reg [FINISHED_LENGTH-1:0] finished_count;

    initial begin
        current_state = IDLE;
        finished_count = 0;
        finished_rx = 0;
    end

    always @(posedge baud_clk or posedge rst) begin
        if(rst) begin
            bitShiftReg <= {reg_length{1'b1}};
            current_state <= IDLE;
            finished_count <= 0;
            finished_rx <= 0;
        end
        else begin
            current_state <= next_state;
            bitShiftReg <= {bitShiftReg[(reg_length-2):0],rx};
        end
    end

    always @(rx or bitShiftReg or current_state) begin
        case(current_state)
            IDLE: begin
                if(rx == 1)
                    next_state <= IDLE;
                else
                    next_state <= READING;
            end
            READING: begin
                if(bitShiftReg[(reg_length-FINISHED_LENGTH):reg_length-1] == {FINISHED_LENGTH{1'b1}})
                    next_state <= FINISHED;
                else
                    next_state <= READING;
            end
            FINISHED: begin
                next_state <= FINISHED_AND_WAITING;
            end
            FINISHED_AND_WAITING: begin
                next_state <= IDLE;
            end
            default: begin
                next_state <= IDLE;
            end
        endcase
    end

    always @ (current_state) begin
        case(current_state)
            IDLE: begin
                finished_count <= 0;
                finished_rx <= 0;
            end
            READING: begin
                finished_count <= 0;
                finished_rx <= 0;
            end
            FINISHED: begin
                finished_count <= 0;
                finished_rx <= 1;
            end
            FINISHED_AND_WAITING: begin
                finished_count <= 0;
                finished_rx <= 0;
            end
            default: begin
                finished_count <= 0;
                finished_rx <= 0;
            end
        endcase
    end

    always @ (posedge finished_rx or posedge rst) begin
        if(rst)
            shifted_bus <= {reg_length{1'b1}};
        else
            shifted_bus <= bitShiftReg;
    end

endmodule

