module aFifo #(parameter DATA_WIDTH=8, ADDRESS_WIDTH=8) (
    input wire ReadEn_in,
    input wire WriteEn_in,
    input wire Clear_in,
    input wire [DATA_WIDTH-1:0] Data_in,
    input wire RClk,
    input wire WClk,
    output reg [DATA_WIDTH-1:0] Data_out,
    output reg Empty_out,
    output reg Full_out
);

reg [ADDRESS_WIDTH-1:0] read_addr;
reg [ADDRESS_WIDTH-1:0] write_addr;
reg [ADDRESS_WIDTH-1:0] count;

reg [DATA_WIDTH-1:0] mem [2**ADDRESS_WIDTH-1:0];

always @(posedge RClk) begin
    if (ReadEn_in) begin
        Data_out <= mem[read_addr];
        Full_out <= 0;
        if (count == 1) begin
            Empty_out <= 1;
        end
        read_addr <= read_addr + 1;
        count <= count - 1;
    end
end

always @(posedge WClk) begin
    if (WriteEn_in) begin
        mem[write_addr] <= Data_in;
        Empty_out <= 0;
        if (count == 2**ADDRESS_WIDTH-2) begin
            Full_out <= 1;
        end
        write_addr <= write_addr + 1;
        count <= count + 1;
    end
end

always @(posedge RClk, posedge Clear_in) begin
    if (Clear_in) begin
        read_addr <= 0;
        write_addr <= 0;
        count <= 0;
        Empty_out <= 1;
        Full_out <= 0;
    end
end

endmodule

module MatrixInput #(parameter DEPTH = 256, ADDRESS_WIDTH =8, WIDTH = 8) ( 
    input wire [WIDTH-1:0] Data_in [DEPTH-1:0],
    output wire [WIDTH-1:0] Data_out [DEPTH-1:0],
    output wire [DEPTH-1:0] Full_out,
    output wire [DEPTH-1:0] Empty_out,
    input wire valid,
    input wire CLK,
    input wire REN,
    input wire WEN,
    input wire RESET
);

reg [DEPTH-1:0] valid_reg;

always @(posedge CLK) begin
    valid_reg [DEPTH-1:0] <= {valid,valid_reg[DEPTH-1:1]};
end

genvar i;

generate
    for (i=DEPTH-1; i>=0; i=i-1) begin : ROWFIFO
        if (i == DEPTH-1) begin : check
            aFifo #(.DATA_WIDTH(WIDTH),.ADDRESS_WIDTH(ADDRESS_WIDTH)) U
                (.Data_out(Data_out[i]), 
                .Empty_out(Empty_out[i]),
                .ReadEn_in(valid),
                .RClk(CLK),        
                .Data_in(Data_in[i]),  
                .Full_out(Full_out[i]),
                .WriteEn_in(WEN),
                .WClk(CLK),
                .Clear_in(RESET));
        end else begin : NonZero
            aFifo #(.DATA_WIDTH(WIDTH),.ADDRESS_WIDTH(ADDRESS_WIDTH)) U
                (.Data_out(Data_out[i]), 
                .Empty_out(Empty_out[i]),
                .ReadEn_in(valid_reg[i+1]),
                .RClk(CLK),        
                .Data_in(Data_out[i+1]),  
                .Full_out(Full_out[i]),
                .WriteEn_in(WEN && Full_out[i+1]),
                .WClk(CLK),
                .Clear_in(RESET));
        end
    end
endgenerate

endmodule

