module clock_lost_detector (
  input clock,
  input reset,
  input enable,
  output lost
);

  reg [63:0] period;
  reg clock_edge;
  reg clock_high;
  reg clock_low;
  reg clock_posedge;
  reg clock_negedge;
  reg lost_r;
  reg lost_f;
  reg lost;

  initial begin
    clock_edge = 0;
    clock_high = 0;
    clock_low = 0;
    lost_r = 0;
    lost_f = 0;
    period = 0;
    clock_posedge = 0;
    clock_negedge = 0;
  end

  always @(posedge clock or posedge reset) begin
    if (reset == 1) begin
      period <= 0;
    end else begin
      clock_edge <= $time;
      if (period != 0 && (($time - clock_edge) <= (1.5 * period))) begin
        period <= $time - clock_edge;
      end else if (period != 0 && (($time - clock_edge) > (1.5 * period))) begin
        period <= 0;
      end else if ((period == 0) && (clock_edge != 0) && clock_posedge == 1) begin
        period <= $time - clock_edge;
      end
    end
  end

  always @(posedge clock or posedge reset) begin
    if (reset) begin
      lost_r <= 0;
    end else if (enable == 1 && clock_posedge == 1) begin
      #1;
      if (period != 0) begin
        lost_r <= 0;
      end
      #((period * 9.1) / 10)
      if ((clock_low != 1'b1) && (clock_posedge != 1'b1) && reset == 0) begin
        lost_r <= 1;
      end
    end
  end

  always @(posedge clock or negedge clock or posedge reset) begin
    if (reset) begin
      clock_posedge <= 0;
      clock_negedge <= 0;
    end else if (clock) begin
      clock_posedge <= 1;
    end else if (~clock) begin
      clock_negedge <= 1;
    end
  end

  always @(negedge clock or posedge reset) begin
    if (reset == 1) begin
      lost_f <= 0;
    end else begin
      if (enable == 1 && clock_negedge == 1) begin
        if (period != 0) begin
          lost_f <= 0;
        end
        #((period * 9.1) / 10)
        if ((clock_high != 1'b1) && (clock_negedge != 1'b1) && reset == 0) begin
          lost_f <= 1;
        end
      end
    end
  end

  always @(lost_r or lost_f or enable) begin
    if (enable == 1) begin
      lost = lost_r | lost_f;
    end else begin
      lost = 0;
    end
  end

  always @(posedge clock or negedge clock or posedge reset) begin
    if (reset == 1) begin
      clock_low <= 1'b0;
      clock_high <= 1'b0;
      clock_posedge <= 1'b0;
      clock_negedge <= 1'b0;
    end else begin
      if (clock == 1) begin
        clock_low <= 1'b0;
        clock_high <= 1'b1;
        clock_posedge <= 1'b0;
        clock_negedge <= 1'b1;
      end else if (clock == 0) begin
        clock_low <= 1'b1;
        clock_high <= 1'b0;
        clock_posedge <= 1'b1;
        clock_negedge <= 1'b0;
      end
    end
  end

  assign lost = enable ? lost : 1'b0;

endmodule

module viterbi_decoder (
  input clk,
  input reset,
  input [n-1:0] in,
  output [k-1:0] out
);

parameter n = 8; // number of data bits in each code word
parameter k = 4; // number of data bits in the original message
parameter m = 3; // number of bits in the convolutional code
parameter t = 1; // number of errors that can be corrected by the code

// Shift register to store received data bits
reg [n-1:0] shift_reg;
always @(posedge clk) begin
  if (reset) begin
    shift_reg <= 0;
  end else begin
    shift_reg <= {shift_reg[(n-m):0], in};
  end
end

// Branch metric unit to compute Hamming distance
reg [1:0] branch_metric [0:(2**m)-1];
integer i, j;
always @(shift_reg) begin
  for (i = 0; i < (2**m); i = i + 1) begin
    branch_metric[i] <= 0;
    for (j = 0; j < m; j = j + 1) begin
      if (shift_reg[j] != ((i >> (m-j-1)) & 1)) begin
        branch_metric[i] <= branch_metric[i] + 1;
      end
    end
  end
end

// Survivor path memory to store most likely sequence
reg [k-1:0] survivor_path [0:(2**(m-1))-1][0:(2**k)-1];
integer state, prev_state, input_bit, min_metric, min_index;
always @(posedge clk) begin
  if (reset) begin
    for (state = 0; state < (2**(m-1)); state = state + 1) begin
      for (input_bit = 0; input_bit < (2**k); input_bit = input_bit + 1) begin
        survivor_path[state][input_bit] <= 0;
      end
    end
  end else begin
    for (state = 0; state < (2**(m-1)); state = state + 1) begin
      min_metric = 999;
      for (prev_state = 0; prev_state < 2; prev_state = prev_state + 1) begin
        for (input_bit = 0; input_bit < (2**k); input_bit = input_bit + 1) begin
          if (prev_state == 0) begin
            if (input_bit == 0) begin
              min_index = 0;
            end else begin
              min_index = 1;
            end
          end else begin
            if (input_bit == 0) begin
              min_index = 2;
            end else begin
              min_index = 3;
            end
          end
          if (branch_metric[min_index] < min_metric) begin
            min_metric = branch_metric[min_index];
            survivor_path[state][input_bit] <= (prev_state << (k-1)) | input_bit;
          end
        end
      end
    end
  end
end

// Traceback unit to determine decoded data bits
reg [k-1:0] traceback [0:(n/m)-1];
integer index, state_index, input_index, decoded_bit;
always @(posedge clk) begin
  if (reset) begin
    for (index = 0; index < (n/m); index = index + 1) begin
      traceback[index] <= 0;
    end
  end else begin
    for (index = 0; index < (n/m); index = index + 1) begin
      state_index = (2**(m-1)) - 1;
      for (input_index = 0; input_index < (2**k); input_index = input_index + 1) begin
        if (survivor_path[state_index][input_index] == 0) begin
          decoded_bit = 0;
        end else begin
          decoded_bit = survivor_path[state_index][input_index] & 1;
        end
        traceback[index] <= (traceback[index] << 1) | decoded_bit;
        state_index = (survivor_path[state_index][input_index] >> 1) & ((2**(m-1)) - 1);
      end
    end
  end
end

// Output decoded data bits
assign out = {traceback[(n/m)-k:(n/m)-1]};

endmodule

