module parity_generator(
    input [7:0] data_in,
    output reg parity_out
);

reg [2:0] highest_priority;
reg [8:0] data_with_parity;

always @* begin
    highest_priority = 3'b000;
    if (data_in[7]) highest_priority = 3'b111;
    else if (data_in[6]) highest_priority = 3'b110;
    else if (data_in[5]) highest_priority = 3'b101;
    else if (data_in[4]) highest_priority = 3'b100;
    else if (data_in[3]) highest_priority = 3'b011;
    else if (data_in[2]) highest_priority = 3'b010;
    else if (data_in[1]) highest_priority = 3'b001;
    else if (data_in[0]) highest_priority = 3'b000;

    data_with_parity = {data_in, ~^data_in[highest_priority]};
    parity_out = data_with_parity[8];
end

endmodule

module multiplexer_256to1(
    input [255:0] data_in,
    input [7:0] sel,
    output reg out
);

reg [7:0] priority_sel;

always @* begin
    casez(sel)
        8'b10000000: priority_sel = 8'b10000000;
        8'b01000000: priority_sel = 8'b01000000;
        8'b00100000: priority_sel = 8'b00100000;
        8'b00010000: priority_sel = 8'b00010000;
        8'b00001000: priority_sel = 8'b00001000;
        8'b00000100: priority_sel = 8'b00000100;
        8'b00000010: priority_sel = 8'b00000010;
        8'b00000001: priority_sel = 8'b00000001;
        default: priority_sel = 8'b00000000;
    endcase

    case (priority_sel)
        8'b10000000: out = data_in[255];
        8'b01000000: out = data_in[254];
        8'b00100000: out = data_in[253];
        8'b00010000: out = data_in[252];
        8'b00001000: out = data_in[251];
        8'b00000100: out = data_in[250];
        8'b00000010: out = data_in[249];
        8'b00000001: out = data_in[248];
        default: out = 1'b0;
    endcase
end

endmodule

