module top_module (
    input clk,
    input reset,
    input data_in,
    input shift_in,
    input [15:0] operand1,
    input [15:0] operand2,
    input carry_in,
    output [15:0] sum,
    output carry_out,
    output reg data_out,
    output [15:0] final_output
);

    // Instantiate the PISO shift register module
    piso_shift_register piso (
        .clk(clk),
        .reset(reset),
        .data_in(data_in),
        .shift_in(shift_in),
        .data_out(data_out)
    );

    // Instantiate the 16-bit adder module
    adder_16bit adder (
        .operand1(operand1),
        .operand2(operand2),
        .carry_in(carry_in),
        .sum(sum),
        .carry_out(carry_out)
    );

    // Define the functional module that performs bitwise AND of data_out and sum
    always @* begin
        final_output = data_out & sum;
