module rotate_mux #(parameter DATA_WIDTH = 26, parameter SEGMENT_SIZE = 5)
  (input [DATA_WIDTH-1:0] Data_i,
   input select_i,
   input [4:0] bit_shift_i,
   output [DATA_WIDTH-1:0] Data_o);

  wire [DATA_WIDTH-1:0] shifted_data;

  // Shift left or right based on select signal
  assign shifted_data = (select_i == 1) ? {Data_i[DATA_WIDTH-1-bit_shift_i:0], Data_i[DATA_WIDTH-1:DATA_WIDTH-bit_shift_i]} : {Data_i[bit_shift_i:DATA_WIDTH-1], Data_i[0:bit_shift_i-1]};

  // Rotate each segment of the input signal by bit_shift
  genvar i;
  generate
    for (i = 0; i < DATA_WIDTH/SEGMENT_SIZE; i = i + 1) begin : segment_loop
      wire [SEGMENT_SIZE-1:0] segment = shifted_data[(i+1)*SEGMENT_SIZE-1:i*SEGMENT_SIZE];
      wire [SEGMENT_SIZE-1:0] rotated_segment;
      assign rotated_segment = (select_i == 1) ? {segment[bit_shift_i-1:0], segment[SEGMENT_SIZE-1:bit_shift_i]} : {segment[1:SEGMENT_SIZE-bit_shift_i], segment[0]};
      assign Data_o[(i+1)*SEGMENT_SIZE-1:i*SEGMENT_SIZE] = (i == DATA_WIDTH/SEGMENT_SIZE-1) ? {rotated_segment[SEGMENT_SIZE-bit_shift_i-1:0], rotated_segment[SEGMENT_SIZE-1:SEGMENT_SIZE-bit_shift_i]} : rotated_segment;
    end
  endgenerate

endmodule

module handshake(error, clk, req, ack, reset);

output reg error;

input clk, req, ack, reset;

reg [2:0] state;

initial
begin
	state = 3'b000;
	error = 1'b0;
end

always @(posedge clk)
begin
	case (state)
		3'b000: 
		begin
			if (~req && ~ack)
				state = 3'b000;
			else if (req && ~ack)
				state = 3'b001;
			else
			begin
				state = 3'b100;
				error = 1'b1;
			end
		end

		3'b001:
		begin
			if (req && ~ack)
				state = 3'b001;
			else if (req && ack)
				state = 3'b010;
			else
			begin
				state = 3'b100;
				error = 1'b1;
			end
		end

		3'b010:
		begin
			if (req && ack)
				state = 3'b010;
			else if (~req && ack)
				state = 3'b011;
			else
			begin
				state = 3'b100;
				error = 1'b1;
			end
		end

		3'b011:
		begin
			if (~req && ack)
				state = 3'b011;
			else if (~req && ~ack)
				state = 3'b000;
			else
			begin
				state = 3'b100;
				error = 1'b1;
			end
		end

		3'b100:
		begin
			if (reset)
			begin
				state = 3'b000;
				error = 1'b0;
			end
		end

		default:
		begin
			state = 3'b100;
			error = 1'b1;
		end
	endcase
end

endmodule

module alu(in1, in2, op, out, zero, carry); 

	output [15:0] out;
	output        zero, carry;
	input  [15:0] in1, in2;
	input         op;
	wire   [15:0] outAdd, outNand;
	wire          carryAdd;

	// Perform addition on the two inputs
	adder16 add1(.in1(in1), .in2(in2), .out(outAdd), .carry(carryAdd));

	// Perform bitwise NAND on the two inputs
	nand16 nand1(.in1(in1), .in2(in2), .out(outNand));

	// Select between the output of the adder and the output of the NAND gate based on the value of op
	mux16x2 m1(outAdd, outNand, op, out);

	// Perform bitwise NOR on the output
	nor n1(zero,out[0],out[1],out[2],out[3],out[4],out[5],out[6],out[7],out[8],out[9],out[10],out[11],out[12],out[13],out[14],out[15]);

	// Set the carry output based on the operation performed
	assign carry = (op==0)?carryAdd:1'b0;

endmodule

