module adder_64bit (
    input clk,      // Clock input
    input reset,    // Synchronous reset input
    input [31:0] a, // 32-bit input A
    input [31:0] b, // 32-bit input B
    input [1:0] select, // Select input to choose between A and B
    output [63:0] sum // 64-bit output
);

    wire [15:0] a_low, b_low, sum_low;
    wire [15:0] a_high, b_high, sum_high;
    wire carry;

    // Instantiate four 16-bit adders
    adder_16bit adder0(.a(a_low), .b(b_low), .sum(sum_low), .carry(carry));
    adder_16bit adder1(.a(a_high), .b(b_high), .sum(sum_high), .carry(carry));
    adder_16bit adder2(.a({16'd0, sum_low}), .b({16'd0, sum_high}), .sum(sum), .carry(carry));

    // Use a 2:1 MUX to select between the inputs based on the select input
    assign a_low = select[0] ? b[15:0] : a[15:0];
    assign b_low = select[0] ? b[15:0] : a[15:0];
    assign a_high = select[0] ? b[31:16] : a[31:16];
    assign b_high = select[0] ? b[31:16] : a[31:16];

    // Use a synchronous reset signal to reset the output to 0
    always @(posedge clk) begin
        if (reset) begin
            sum <= 64'd0;
        end else begin
            sum <= {carry, sum[62:0]};
        end
    end

endmodule

module uart_communication(
  input wire clk,
  input wire resetq,
  input wire uart0_valid,
  input wire [7:0] uart0_data,
  output wire uart0_wr,
  output wire uart0_rd,
  output wire [7:0] uart_w
);

  // Internal signals
  wire io_rd, io_wr;
  wire [15:0] mem_addr;
  wire mem_wr;
  wire [15:0] dout;
  wire [15:0] io_din;
  wire [1:0] io_thread;
  wire [3:0] kill_slot_rq;
  wire [15:0] insn;

  // RAM
  reg [15:0] ram_prog[0:4095];
  always @(posedge clk) begin
    insn <= ram_prog[mem_addr[11:0]];
    if (mem_wr)
      ram_prog[mem_addr[11:1]] <= dout;
  end

  // J4 module
  j4 _j4(
    .clk(clk),
    .resetq(resetq),
    .io_rd(io_rd),
    .io_wr(io_wr),
    .mem_wr(mem_wr),
    .dout(dout),
    .io_din(io_din),
    .mem_addr(mem_addr),
    .insn(insn),
    .io_slot(io_thread),
    .return_top(16'hFFFF),
    .kill_slot_rq(kill_slot_rq)
  );

  // IO signals
  reg io_wr_, io_rd_;
  reg [15:0] dout_;
  reg [1:0] io_thread_;
  reg [15:0] taskexec;
  reg [47:0] taskexecn;
  always @(posedge clk) begin
    {io_rd_, io_wr_, dout_} <= {io_rd, io_wr, dout};
    io_thread_ <= io_thread;
    if (io_rd | io_wr)
      io_addr_ <= mem_addr;
    else
      io_addr_ <= 0;
  end

  // UART signals
  assign uart0_wr = io_wr_ & io_addr_[11];
  assign uart0_rd = io_rd_ & io_addr_[11];
  assign uart_w = dout_[7:0];

  // IO ports
  always @* begin
    case (io_thread_)
      2'b00: taskexec = 16'b0;
      2'b01: taskexec = taskexecn[15:0];
      2'b10: taskexec = taskexecn[31:16];
      2'b11: taskexec = taskexecn[47:32];
    endcase
  end

  assign io_din =
    (io_addr_[11] ? {8'd0, uart0_data} : 16'd0) |
    (io_addr_[12] ? {12'd0, 1'b0, 1'b0, uart0_valid, 1'b1} : 16'd0) |
    (io_addr_[13] ? {taskexec}: 16'd0)|
    (io_addr_[14] ? {14'd0, io_thread_}: 16'd0);

  always@( posedge clk) begin
    if (io_wr_ ) begin
      if (io_addr_[8]) taskexecn[15:0] <= dout_;
      if (io_addr_[9]) taskexecn[31:16] <= dout_;
      if (io_addr_[10]) taskexecn[47:32] <= dout_;
    end

    if (io_addr_[14] == 1'b1) $display("io_thread_ = %d, io_din = %d", io_thread_, io_din);

    case ({io_wr_, io_addr_[13], io_thread_})
      4'b1100: kill_slot_rq <= dout_[3:0];
      4'b1101: kill_slot_rq <= 4'b0010;
      4'b1111: kill_slot_rq <= 4'b1000;
      4'b1110: kill_slot_rq <= 4'b0100;
      default: kill_slot_rq <= 4'b0000;
    endcase
  end

endmodule

module state_splitting_FSM (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 4; // number of input signals
parameter m = 2; // number of output signals
parameter k = 4; // number of original states

// Define input and output signals for each state
reg [1:0] state;
reg [1:0] next_state;
reg [m-1:0] state1_out;
reg [m-1:0] state2_out;
reg [m-1:0] state3_out;
reg [m-1:0] state4_out;

// Use signals to determine next state and output signals
always @ (state or in) begin
  case (state)
    2'b00: begin
      if (in[0] && in[1]) begin
        next_state = 2'b11;
        state1_out = 2'b10;
      end
      else if (in[0]) begin
        next_state = 2'b01;
        state1_out = 2'b01;
      end
      else if (in[1]) begin
        next_state = 2'b10;
        state1_out = 2'b00;
      end
      else begin
        next_state = 2'b00;
        state1_out = 2'b00;
      end
    end
    2'b01: begin
      if (in[2]) begin
        next_state = 2'b10;
        state2_out = 2'b10;
      end
      else begin
        next_state = 2'b01;
        state2_out = 2'b01;
      end
    end
    2'b10: begin
      if (in[3]) begin
        next_state = 2'b01;
        state3_out = 2'b10;
      end
      else begin
        next_state = 2'b10;
        state3_out = 2'b01;
      end
    end
    2'b11: begin
      if (in[2] || in[3]) begin
        next_state = 2'b00;
        state4_out = 2'b11;
      end
      else begin
        next_state = 2'b11;
        state4_out = 2'b00;
      end
    end
  endcase
end

// Compute output signals based on the current state and input signals
always @ (state) begin
  case (state)
    2'b00: out = state1_out;
    2'b01: out = state2_out;
    2'b10: out = state3_out;
    2'b11: out = state4_out;
  endcase
end

endmodule

