    wire btnup_int, btndown_int, btnleft_int, btnright_int, btnrst_int;
    debouncer up(.y(btnup_int), .x(btnup), .clk(clock));
    debouncer down(.y(btndown_int), .x(btndown), .clk(clock));
    debouncer left(.y(btnleft_int), .x(btnleft), .clk(clock));
    debouncer right(.y(btnright_int), .x(btnright), .clk(clock));
    debouncer rst(.y(btnrst_int), .x(btnrst), .clk(clock));

    // Program counter to keep track of current value
