module vending_machine (
  input clk,
  input reset,
  input coin,
  input select_cola,
  input select_sprite,
  output reg dispense_cola,
  output reg dispense_sprite
);

  parameter S_IDLE = 2'b00, S_COIN = 2'b01, S_SELECTION = 2'b10;
  reg [1:0] state, next_state;
  reg [1:0] coins;

  always @(posedge clk) begin
    if (reset) begin
      state <= S_IDLE;
      coins <= 2'b00;
      dispense_cola <= 1'b0;
      dispense_sprite <= 1'b0;
    end
    else begin
      state <= next_state;

      case (state)
        S_IDLE: begin
          if (coin) begin
            coins <= coins + 1;
            next_state <= S_COIN;
          end
          else if (select_cola && coins >= 2) begin
            coins <= coins - 2;
            dispense_cola <= 1'b1;
            next_state <= S_IDLE;
          end
          else if (select_sprite && coins >= 2) begin
            coins <= coins - 2;
            dispense_sprite <= 1'b1;
            next_state <= S_IDLE;
          end
          else begin
            next_state <= S_IDLE;
          end
        end

        S_COIN: begin
          if (coin) begin
            coins <= coins + 1;
            next_state <= S_COIN;
          end
          else if (select_cola && coins >= 2) begin
            coins <= coins - 2;
            dispense_cola <= 1'b1;
            next_state <= S_IDLE;
          end
          else if (select_sprite && coins >= 2) begin
            coins <= coins - 2;
            dispense_sprite <= 1'b1;
            next_state <= S_IDLE;
          end
          else if (coins > 2) begin
            coins <= coins - 2;
            next_state <= S_SELECTION;
          end
          else begin
            next_state <= S_COIN;
          end
        end

        S_SELECTION: begin
          if (select_cola && coins >= 2) begin
            coins <= coins - 2;
            dispense_cola <= 1'b1;
            next_state <= S_IDLE;
          end
          else if (select_sprite && coins >= 2) begin
            coins <= coins - 2;
            dispense_sprite <= 1'b1;
            next_state <= S_IDLE;
          end
          else if (coin) begin
            coins <= coins + 1;
            next_state <= S_SELECTION;
          end
          else begin
            next_state <= S_SELECTION;
          end
        end
      endcase
    end
  end

endmodule

