        if(!rst_n) begin
            sum_reg <= 16'd0;
            Cout_reg <= 1'b0;
        end
        else begin
            sum_reg <= A + B + Cin;
            Cout_reg <= (sum_reg[16] == 1) ? 1'b1 : 1'b0;
        end
    end

    assign Sum = sum_reg;
    assign Cout = Cout_reg;
endmodule

