module eth_rx(
    input c, // must be the 50 MHz RMII reference clock 
    input [1:0] phy_rxd,
    input phy_rxdv,
    output [7:0] d,
    output dv,
    output erx
);

localparam SW = 3, CW = 3;
localparam ST_IDLE       = 3'd0;
localparam ST_PREAMBLE   = 3'd1; 
localparam ST_PAYLOAD    = 3'd2;
localparam ST_STOP       = 3'd3;

wire [1:0] rmii_d;
sync #(2) rmii_d_sync_r
(.in(phy_rxd), .clk(c), .out(rmii_d));

wire rmii_dv;
sync rmii_dv_sync_r
(.in(phy_rxdv), .clk(c), .out(rmii_dv));

wire rmii_dv_d1;
d1 rxdv_d1_r(.d(rmii_dv), .c(c), .q(rmii_dv_d1));

wire [7:0] rxd_shift;
r #(8) rxd_shift_r
(.c(c), .d({rmii_d, rxd_shift[7:2]}), .rst(1'b0), .en(1'b1), .q(rxd_shift));

wire shift_cnt_rst;
wire [1:0] shift_cnt;
r #(2) shift_cnt_r
(.c(c), .d(shift_cnt+1'b1), .en(1'b1), .rst(shift_cnt_rst), .q(shift_cnt));

assign d = rxd_shift;

reg [CW+SW-1:0] ctrl;
wire [SW-1:0] state;
wire [SW-1:0] next_state = ctrl[SW+CW-1:CW];
r #(SW) state_r(.c(c), .rst(1'b0), .en(1'b1), .d(next_state), .q(state));

always @* begin
  case (state)
    ST_IDLE: 
      if (rmii_dv && d == 8'h55)      ctrl = { ST_PREAMBLE, 3'b000 };
      else                            ctrl = { ST_IDLE    , 3'b000 };
    ST_PREAMBLE:                   
      if (rmii_dv && d == 8'h55)      ctrl = { ST_PREAMBLE, 3'b000 };
      else if (rmii_dv && d == 8'hd5) ctrl = { ST_PAYLOAD , 3'b100 };
      else                            ctrl = { ST_IDLE    , 3'b000 };
    ST_PAYLOAD:
      if (rmii_dv | rmii_dv_d1)       ctrl = { ST_PAYLOAD , 3'b001 };
      else                            ctrl = { ST_STOP    , 3'b010 };
    ST_STOP:                          ctrl = { ST_IDLE    , 3'b000 }; // fcs ?
    default:                          ctrl = { ST_IDLE    , 3'b000 };
  endcase
end

assign dv = state == ST_PAYLOAD & &shift_cnt;
assign erx = ctrl[1];
assign shift_cnt_rst = ctrl[2];

endmodule

module altpciexpav_stif_reg_fifo
#(
   parameter FIFO_DEPTH = 5,
   parameter DATA_WIDTH = 304
  )
  (
    // global signals
    input                         clk,
    input                         rstn,
    input                         srst,
    input                         wrreq,
    input                         rdreq,
    input  [DATA_WIDTH-1:0]       data,  
    output [DATA_WIDTH-1:0]       q,
    output reg [3:0]              fifo_count
   );

   reg  [DATA_WIDTH-1:0]          fifo_reg[FIFO_DEPTH-1:0];
   wire [FIFO_DEPTH-1:0]          fifo_wrreq;  

   // fifo word counter
   always @(posedge clk or negedge rstn) begin
      if(~rstn) fifo_count <= 4'h0;
      else if (srst) fifo_count <= 4'h0;
      else if (rdreq & ~wrreq) fifo_count <= fifo_count - 1;
      else if(~rdreq & wrreq) fifo_count <= fifo_count + 1;
   end

   generate
      genvar i;
      for(i=0; i< FIFO_DEPTH -1; i=i+1) begin: register_array
         assign fifo_wrreq[i] = wrreq & (fifo_count == i | (fifo_count == i + 1 & rdreq)) ;
         always @(posedge clk or negedge rstn) begin
            if(~rstn) fifo_reg[i] <= {DATA_WIDTH{1'b0}};
            else if (srst) fifo_reg[i] <= {DATA_WIDTH{1'b0}};
            else if(fifo_wrreq[i]) fifo_reg[i] <= data;
            else if(rdreq) fifo_reg[i] <= fifo_reg[i+1];
         end
      end
   endgenerate

   // the last register
   assign fifo_wrreq[FIFO_DEPTH-1] = wrreq & (fifo_count == FIFO_DEPTH - 1 | (fifo_count == FIFO_DEPTH & rdreq)) ;    
   always @(posedge clk or negedge rstn) begin
      if(~rstn) fifo_reg[FIFO_DEPTH-1] <= {DATA_WIDTH{1'b0}};
      else if (srst) fifo_reg[FIFO_DEPTH-1] <= {DATA_WIDTH{1'b0}};
      else if(fifo_wrreq[FIFO_DEPTH-1]) fifo_reg[FIFO_DEPTH-1] <= data;
   end

   assign q = fifo_reg[0];

endmodule

