module digital_clock(
    input clk,
    input reset,
    output reg [5:0] sec,
    output reg [5:0] min,
    output reg [4:0] hr,
    output reg ampm
);

    // Counters for seconds, minutes, and hours
    reg [5:0] sec_count = 0;
    reg [5:0] min_count = 0;
    reg [4:0] hr_count = 0;

    // Flag to toggle AM/PM
    reg toggle_ampm = 0;

    // Synchronous reset
    always @(posedge clk) begin
        if (reset) begin
            sec_count <= 0;
            min_count <= 0;
            hr_count <= 0;
            toggle_ampm <= 0;
        end else begin
            // Increment second counter every second
            if (sec_count == 49) begin
                sec_count <= 0;
                // Increment minute counter every minute
                if (min_count == 59) begin
                    min_count <= 0;
                    // Increment hour counter every hour
                    if (hr_count == 11 && toggle_ampm == 0) begin
                        hr_count <= 0;
                        toggle_ampm <= 1;
                    end else if (hr_count == 11 && toggle_ampm == 1) begin
                        hr_count <= 0;
                        toggle_ampm <= 0;
                    end else begin
                        hr_count <= hr_count + 1;
                    end
                end else begin
                    min_count <= min_count + 1;
                end
            end else begin
                sec_count <= sec_count + 1;
            end
        end
    end

    // Output values
    assign sec = sec_count;
    assign min = min_count;
    assign ampm = toggle_ampm;
    always @(*) begin
        if (hr_count == 0) begin
            hr = 12;
        end else if (hr_count < 10) begin
            hr = {1'b0, hr_count};
        end else if (hr_count < 12) begin
            hr = hr_count;
        end else if (hr_count == 12) begin
            hr = 0;
        end else if (hr_count < 22) begin
            hr = {1'b1, hr_count - 12};
        end else begin
            hr = hr_count - 12;
        end
    end

endmodule

