module nic_crc_check(
   clk,
   wr_clk,
   reset,

   in_pkt_wrreq,
   in_pkt,
   in_pkt_usedw,
   in_valid_wrreq,
   in_valid,

   port_error,

   out_pkt_wrreq,
   out_pkt,
   out_pkt_usedw,
   out_valid_wrreq,
   out_valid
  );
   input clk;
   input wr_clk;
   input reset;

   input in_pkt_wrreq;
   input [138:0]in_pkt;
   output [7:0]in_pkt_usedw;
   input in_valid_wrreq;
   input in_valid;

   output port_error;

   output out_pkt_wrreq;
   output [138:0]out_pkt;
   input [7:0]out_pkt_usedw;
   output out_valid_wrreq;
   output out_valid;

   reg out_pkt_wrreq;
   reg [138:0]out_pkt;
   reg out_valid_wrreq;
   reg out_valid;
   reg port_error;
   reg [2:0]current_state;
   parameter idle=3'b0,
             transmit=3'b001,
             wait_crcbad=3'b010,
             discard=3'b011;

   always@(posedge clk or negedge reset)
   if(!reset)
     begin
       crc_data_valid<=1'b0;
       crc_empty<=4'b0;
       start_of_pkt<=1'b0;
       end_of_pkt<=1'b0;
       in_pkt_rdreq<=1'b0;
       in_valid_rdreq<=1'b0;
       out_pkt_wrreq<=1'b0;
       out_valid_wrreq<=1'b0;
       port_error <= 1'b0;
       current_state<=idle;
     end
   else
     begin
       case(current_state)
         idle:
           begin
             out_valid_wrreq<=1'b0;
             port_error <= 1'b0;
             if(out_pkt_usedw<8'd161)
               begin
                 if(!in_valid_empty)
                   begin
                     if(in_valid_q==1'b1)
                       begin
                         in_pkt_rdreq<=1'b1;
                         in_valid_rdreq<=1'b1;

                         current_state<=transmit;
                       end
                     else
                       begin
                         in_pkt_rdreq<=1'b1;
                         in_valid_rdreq<=1'b1;

                         current_state<=discard;
                       end
                   end
                 else
                   begin
                     current_state<=idle;
                   end
               end
             else
               begin
                 current_state<=idle;
               end
           end//end idle;
         transmit:
           begin
             in_valid_rdreq<=1'b0;
             if(in_pkt_q[138:136]==3'b101)//header;
               begin
                 in_pkt_rdreq<=1'b1;
                 crc_data_valid<=1'b1;
                 crc_data<=in_pkt_q[127:0];
                 start_of_pkt<=1'b1;
                 out_pkt_wrreq<=1'b1;
                 out_pkt<=in_pkt_q;

                 current_state<=transmit;
               end
             else if(in_pkt_q[138:136]==3'b110)//tail;
               begin
                 in_pkt_rdreq<=1'b0;
                 crc_data_valid<=1'b1;
                 crc_data<=in_pkt_q[127:0];
                 end_of_pkt<=1'b1;
                 crc_empty<=4'b1111-in_pkt_q[135:132];
                 out_pkt_wrreq<=1'b1;
                 out_pkt<=in_pkt_q;

                 current_state<=wait_crcbad;
               end
             else//middle;
               begin
                 in_pkt_rdreq<=1'b1;
                 start_of_pkt<=1'b0;
                 crc_data_valid<=1'b1;
                 crc_data<=in_pkt_q[127:0];
                 out_pkt_wrreq<=1'b1;
                 out_pkt<=in_pkt_q;

                 current_state<=transmit;
               end
           end//end transmit;
         wait_crcbad:
           begin
             end_of_pkt<=1'b0;
             crc_empty<=4'b0;
             crc_data_valid<=1'b0;
             out_pkt_wrreq<=1'b0;
             if(crc_bad_valid==1'b1)
               begin
                 if(crc_bad==1'b1)//error;
                   begin
                     out_valid_wrreq<=1'b1;
                     out_valid<=1'b0;
                     port_error <= 1'b1;
                   end
                 else
                   begin
                     out_valid_wrreq<=1'b1;
                     out_valid<=1'b1;
                   end
                 current_state<=idle;
               end
             else
               begin
                 current_state<=wait_crcbad;
               end
           end//end wait_crcbad;
         discard:
           begin
             in_valid_rdreq<=1'b0;
             in_pkt_rdreq<=1'b1;
             if(in_pkt_q[138:136]==3'b110)//tail;
               begin
                 in_pkt_rdreq<=1'b0;

                 current_state<=idle;
               end
             else if(in_pkt_q[138:136]==3'b111)//tail;
               begin
                 in_pkt_rdreq<=1'b0;

                 current_state<=idle;
               end
             else
               begin
                 current_state<=discard;
               end
           end//end discard;
         default:
           begin
             current_state<=idle;
           end
       endcase
     end

    reg [127:0]crc_data;
    reg crc_data_valid;
    reg [3:0]crc_empty;
    reg start_of_pkt;
    reg end_of_pkt;
    wire crc_bad_valid;
    wire crc_bad;
check_ip check_ip0(
	.clk(clk),
	.data(crc_data),
	.datavalid(crc_data_valid),
	.empty(crc_empty),
	.endofpacket(end_of_pkt),
	.reset_n(reset),
	.startofpacket(start_of_pkt),
	.crcbad(crc_bad),
	.crcvalid(crc_bad_valid)
   ); 
    reg in_pkt_rdreq;
    wire [138:0]in_pkt_q;
    wire [7:0]in_pkt_usedw;
asy_256_139 asy_256_139(
	.aclr(!reset),
	.data(in_pkt),
	.rdclk(clk),
	.rdreq(in_pkt_rdreq),
	.wrclk(wr_clk),
	.wrreq(in_pkt_wrreq),
	.q(in_pkt_q),
	.wrusedw(in_pkt_usedw)
  );
    reg in_valid_rdreq;
    wire in_valid_q;
    wire in_valid_empty;
asy_64_1 asy_64_1(
	.aclr(!reset),
	.data(in_valid),
	.rdclk(clk),
	.rdreq(in_valid_rdreq),
	.wrclk(wr_clk),
	.wrreq(in_valid_wrreq),
	.q(in_valid_q),
	.rdempty(in_valid_empty)
   );  

endmodule

module adler_checksum (
  input [7:0] in,
  input rst,
  input valid,
  output [15:0] adler_out,
  output valid
);

  reg [15:0] s1;
  reg [15:0] s2;

  always @(posedge clk) begin
    if (rst) begin
      s1 <= 16'd1;
      s2 <= 16'd0;
      valid <= 1'b0;
    end else if (valid) begin
      s1 <= (s1 + in) % 16'd65521;
      s2 <= (s2 + s1) % 16'd65521;
    end
  end

  assign adler_out = (s2 << 16) | s1;
  assign valid = ~rst & valid;

endmodule

module alu (
    input [3:0] A,
    input [3:0] B,
    input [2:0] opcode,
    output reg [3:0] out,
    output reg zero
);

reg [3:0] result;
reg [3:0] A_reg;
reg [3:0] B_reg;
reg zero_reg;

always @(*) begin
    A_reg <= A;
    B_reg <= B;
end

always @(*) begin
    case (opcode)
        3'b000: result <= A_reg + B_reg;
        3'b001: result <= A_reg - B_reg;
        3'b010: result <= A_reg & B_reg;
        3'b011: result <= A_reg | B_reg;
        3'b100: result <= A_reg ^ B_reg;
        3'b101: result <= A_reg << 1;
        3'b110: result <= A_reg >> 1;
        3'b111: result <= ~A_reg;
    endcase
end

always @(posedge clk) begin
    out <= result;
    zero_reg <= (result == 0);
end

always @(posedge clk) begin
    zero <= zero_reg;
end

endmodule

module pwm_control(
  output pwm,
  input clock,
  input enable,
  input [7:0] duty_cycle
);

  reg [7:0] counter;
  reg [7:0] threshold;
  reg [7:0] duty_cycle_reg;
  reg enable_reg;

  // Debounce enable signal
  debounce enable_debounced (
    .pb_debounced(enable_reg),
    .pb(enable),
    .clk(clock)
  );

  // Debounce duty cycle signal
  debounce duty_cycle_debounced (
    .pb_debounced(duty_cycle_reg),
    .pb(duty_cycle),
    .clk(clock)
  );

  // Set threshold for duty cycle
  always @(*) begin
    threshold = (duty_cycle_reg * 255) / 100;
  end

  // PWM signal generation
  always @(posedge clock) begin
    if (enable_reg) begin
      if (counter < threshold) begin
        pwm <= 1;
      end else begin
        pwm <= 0;
      end

      counter <= counter + 1;

      if (counter == 255) begin
        counter <= 0;
      end
    end else begin
      counter <= 0;
      pwm <= 0;
    end
  end

endmodule

// Debounce module
module debounce(pb_debounced, pb, clk);

  output pb_debounced;
  input pb;
  input clk;

  reg [3:0] shift_reg;

  always @(posedge clk) begin
    shift_reg[3:1] <= shift_reg[2:0];
    shift_reg[0] <= pb;
  end 

  assign pb_debounced = ((shift_reg == 4'b0000) ? 1'b0 : 1'b1);

endmodule

