subtractor sub(.a(a), .b(b), .diff(diff));

wire [63:0] mux_out1;
wire [63:0] mux_out2;
mux mux_inst(.in1(diff), .in2(a), .in3(b), .in4(64'h1), .select(select), .out1(mux_out1), .out2(mux_out2));

