//Carry select adder module for subtraction
module subtractor (
    input [63:0] a,
    input [63:0] b,
    output reg [63:0] diff
);

wire [63:0] a_inv;
assign a_inv = ~a;

wire [63:0] carry_in;
assign carry_in = 64'h1;

wire [63:0] sum1;
wire [63:0] carry1;
CSA csa1(.a(a_inv), .b(b), .cin(carry_in), .sum(sum1), .cout(carry1));

wire [63:0] sum2;
wire [63:0] carry2;
CSA csa2(.a(sum1), .b(carry_in), .cin(carry1), .sum(sum2), .cout(carry2));

