//Multiplexer module with 4 inputs and 2 outputs
module mux (
    input [63:0] in1,
    input [63:0] in2,
    input [63:0] in3,
    input [63:0] in4,
    input [1:0] select,
    output [63:0] out1,
    output [63:0] out2
);

assign out1 = select[0] ? in3 : in1;
assign out2 = select[0] ? in4 : select[1] ? in2 : in1;

endmodule

//Carry select adder module
module CSA (
    input [63:0] a,
    input [63:0] b,
    input [63:0] cin,
    output [63:0] sum,
    output [63:0] cout
);

wire [63:0] p;
wire [63:0] g;
wire [63:0] c;

assign p = a ^ b;
assign g = a & b;
assign c[0] = cin;

genvar i;
generate
    for (i = 0; i < 64; i = i + 1) begin : gen
        assign c[i+1] = g[i] | (p[i] & c[i]);
        assign sum[i] = a[i] ^ b[i] ^ c[i];
    end
endgenerate

assign cout = c[64];

endmodule

module clk_rst_mngr (
    input clk_in,
    input rst_async_n,
    input en_clk_div8,
    output rst_sync_n,
    output clk_out,
    output clk_div2,
    output clk_div4,
    output clk_div8,
    output clk_div8_proc
  );

  reg [2:0] counter;
  reg synch_rst_reg1_n, synch_rst_reg2_n;
  reg en_clk_div8_reg;

  // clock divider
  always@(posedge clk_in)begin
    if(!rst_async_n)
      counter <= 0;
    else
      counter <= counter + 1;
  end

  assign clk_out = clk_in;
  assign clk_div2 = counter[0];
  assign clk_div4 = counter[1];
  assign clk_div8 = counter[2];

  //change to make one delay to release the processor
  always@(posedge clk_div8, negedge rst_async_n)begin
    if(!rst_async_n)
      en_clk_div8_reg <= 0;
    else
      en_clk_div8_reg <= en_clk_div8;
  end

  //"clock gate"
  assign clk_div8_proc = en_clk_div8_reg ? (counter[2] & rst_async_n) : 1'b0;

  always@(posedge clk_div8, negedge rst_async_n)begin
    if(!rst_async_n)begin
      synch_rst_reg1_n <= 1'b0;
      synch_rst_reg2_n <= 1'b0;
    end
    else begin
      synch_rst_reg1_n <= 1'b1;
      synch_rst_reg2_n <= synch_rst_reg1_n;
    end
  end

  assign rst_sync_n = synch_rst_reg2_n;

endmodule

