module ripple_adder (
    input [3:0] a, b, // 4-bit binary inputs
    output [3:0] sum, // 4-bit binary output
    output carry_out // Carry output
);

wire [3:0] sum_intermediate;
wire [3:0] carry_intermediate;

// First full adder
full_adder fa0(.a(a[0]), .b(b[0]), .carry_in(1'b0), .sum(sum_intermediate[0]), .carry_out(carry_intermediate[0]));

// Second full adder
full_adder fa1(.a(a[1]), .b(b[1]), .carry_in(carry_intermediate[0]), .sum(sum_intermediate[1]), .carry_out(carry_intermediate[1]));

// Third full adder
full_adder fa2(.a(a[2]), .b(b[2]), .carry_in(carry_intermediate[1]), .sum(sum_intermediate[2]), .carry_out(carry_intermediate[2]));

// Fourth full adder
full_adder fa3(.a(a[3]), .b(b[3]), .carry_in(carry_intermediate[2]), .sum(sum_intermediate[3]), .carry_out(carry_out));

assign sum = sum_intermediate;

endmodule

module full_adder (
    input a, b, carry_in,
    output sum, carry_out
);

assign {carry_out, sum} = a + b + carry_in;

endmodule

module xor_mux (
    input [3:0] a, b, // 4-bit binary inputs
    input select, // Select input to choose between a and b
    output [3:0] out // 4-bit binary output
);

assign out = select ? (a ^ b) : a;

endmodule

module top_module (
    input [3:0] a, b, // 4-bit binary input for the adder
    input select, // Select input to choose between adder output and first input
    output [7:0] out // 8-bit output after bitwise AND operation
);

wire [3:0] adder_sum;
wire adder_carry_out;
wire [3:0] mux_out;

ripple_adder adder(.a(a), .b(b), .sum(adder_sum), .carry_out(adder_carry_out));
xor_mux mux(.a(a), .b(adder_sum), .select(select), .out(mux_out));

assign out = {mux_out, adder_sum} & 8'hFF;

endmodule

