module ll8_to_fifo36
  (input clk, input reset, input clear,
   input [7:0] ll_data,
   input ll_sof_n,
   input ll_eof_n,
   input ll_src_rdy_n,
   output ll_dst_rdy_n,

   output [35:0] f36_data,
   output f36_src_rdy_o,
   input f36_dst_rdy_i );

   wire f36_write    = f36_src_rdy_o & f36_dst_rdy_i;

   // Why anybody would use active low in an FPGA is beyond me...
   wire  ll_sof      = ~ll_sof_n;
   wire  ll_eof      = ~ll_eof_n;
   wire  ll_src_rdy  = ~ll_src_rdy_n;
   wire  ll_dst_rdy;
   assign    ll_dst_rdy_n = ~ll_dst_rdy;

   reg 	 f36_sof, f36_eof;
   reg [1:0] f36_occ;


   reg [2:0] state;
   reg [7:0] dat0, dat1, dat2, dat3;

   always @(posedge clk)
     if(ll_src_rdy & ((state==0)|f36_write))
       f36_sof <= ll_sof;

   always @(posedge clk)
     if(ll_src_rdy & ((state !=4)|f36_write))
       f36_eof <= ll_eof;

   always @(posedge clk)
     if(ll_eof)
       f36_occ <= state[1:0] + 1;
     else
       f36_occ <= 0;

   always @(posedge clk)
     if(reset)
       state   <= 0;
     else
       if(ll_src_rdy)
	 case(state)
	   0 : 
	     if(ll_eof)
	       state <= 4;
	     else
	       state <= 1;
	   1 : 
	     if(ll_eof)
	       state <= 4;
	     else
	       state <= 2;
	   2 : 
	     if(ll_eof)
	       state <= 4;
	     else 
	       state <= 3;
	   3 : state <= 4;
	   4 : 
	     if(f36_dst_rdy_i)
	       if(ll_eof)
		 state 	   <= 4;
	       else
		 state 	   <= 1;
	 endcase // case(state)
       else
	 if(f36_write)
	   state 	   <= 0;

   always @(posedge clk)
     if(ll_src_rdy & (state==3))
       dat3 		   <= ll_data;

   always @(posedge clk)
     if(ll_src_rdy & (state==2))
       dat2 		   <= ll_data;

   always @(posedge clk)
     if(ll_src_rdy & (state==1))
       dat1 		   <= ll_data;

   always @(posedge clk)
     if(ll_src_rdy & ((state==0) | f36_write))
       dat0 		   <= ll_data;

   assign    ll_dst_rdy     = f36_dst_rdy_i | (state != 4);
   assign    f36_data 	    = {f36_occ,f36_eof,f36_sof,dat0,dat1,dat2,dat3};  // FIXME endianess
   assign    f36_src_rdy_o  = (state == 4);

endmodule

module LogicProbe(clock, reset, trigger, sample, channels, serial_out);
    input clock;
    input reset;
    input trigger;
    input sample;
    input [127:0] channels;
    output serial_out;

    wire full;
    reg [12:0] rdaddr;
    wire [7:0] data;
    reg write;
    wire ready;
    reg done;
    reg state;

    LogicProbe_sampler
        sampler(clock, reset, trigger, sample, channels, full, rdaddr, data);

    LogicProbe_xmtbuf
        xmtbuf(clock, reset, write, ready, data, serial_out);

    always @(posedge clock) begin
        if (reset == 1) begin
            rdaddr <= 13'd0;
            write <= 0;
            done <= 0;
            state <= 0;
        end else begin
            if (full == 1 && done == 0) begin
                if (state == 0) begin
                    if (ready == 1) begin
                        state <= 1;
                        write <= 1;
                    end
                end else begin
                    if (rdaddr == 13'd8191) begin
                        done <= 1;
                    end
                    state <= 0;
                    write <= 0;
                    rdaddr <= rdaddr + 1;
                end
            end
        end
    end

endmodule

module LogicProbe_sampler(clock, reset, trigger, sample, channels, full, rdaddr, data);
    input clock;
    input reset;
    input trigger;
    input sample;
    input [127:0] channels;
    output full;
    output reg [12:0] rdaddr;
    output reg [7:0] data;

    reg [127:0] sample_buffer;
    wire [127:0] channels_mask;
    reg sample_done;
    reg sample_state;

    assign channels_mask = {128{1'b0}};
    assign channels_mask[channels] = 1;

    always @(posedge clock) begin
        if (reset == 1) begin
            sample_done <= 0;
            sample_state <= 0;
            rdaddr <= 13'd0;
        end else begin
            if (trigger == 1 && sample_done == 0) begin
                if (sample_state == 0) begin
                    sample_buffer <= {128{1'b0}};
                    sample_state <= 1;
                end else begin
                    sample_buffer <= sample_buffer | (channels_mask & {128{1'b0}} | {128{1'b1}}) << rdaddr;
                    rdaddr <= rdaddr + 1;
                    if (rdaddr == 13'd8191) begin
                        sample_done <= 1;
                        sample_state <= 0;
                    end
                end
            end
        end
    end

    assign full = sample_done;
    assign data = sample_buffer[rdaddr];

endmodule

module LogicProbe_xmtbuf(clock, reset, write, ready, data, serial_out);
    input clock;
    input reset;
    input write;
    output reg ready;
    input [7:0] data;
    output serial_out;

    reg [7:0] xmtbuf [0:7];
    reg [2:0] xmtbuf_wr;
    reg [2:0] xmtbuf_rd;
    reg [7:0] shift_reg;
    reg [3:0] shift_cnt;
    reg [7:0] data_reg;
    reg [3:0] data_cnt;
    reg xmt_done;

    always @(posedge clock) begin
        if (reset == 1) begin
            xmtbuf_wr <= 0;
            xmtbuf_rd <= 0;
            shift_reg <= 0;
            shift_cnt <= 0;
            data_reg <= 0;
            data_cnt <= 0;
            xmt_done <= 0;
            ready <= 1;
        end else begin
            if (write == 1) begin
                xmtbuf[xmtbuf_wr] <= data;
                xmtbuf_wr <= xmtbuf_wr + 1;
                if (xmtbuf_wr == 8) begin
                    xmtbuf_wr <= 0;
                end
            end
            if (xmt_done == 0) begin
                if (shift_cnt == 0) begin
                    if (xmtbuf_rd != xmtbuf_wr) begin
                        data_reg <= xmtbuf[xmtbuf_rd];
                        xmtbuf_rd <= xmtbuf_rd + 1;
                        if (xmtbuf_rd == 8) begin
                            xmtbuf_rd <= 0;
                        end
                        data_cnt <= 1;
                    end else begin
                        data_reg <= 0;
                        data_cnt <= 0;
                    end
                    shift_cnt <= 1;
                end else begin
                    if (data_cnt == 0) begin
                        shift_reg <= 0;
                        shift_cnt <= 0;
                        if (xmtbuf_rd == xmtbuf_wr) begin
                            xmt_done <= 1;
                        end
                        ready <= 1;
                    end else begin
                        shift_reg <= data_reg[7];
                        data_reg <= {1'b0, data_reg[7:1]};
                        data_cnt <= data_cnt + 1;
                        shift_cnt <= shift_cnt + 1;
                        ready <= 0;
                    end
                end
            end
        end
    end

    assign serial_out = shift_reg;

endmodule

