module priority_encoder_counter (
    input [3:0] in, // 4-bit input to the priority encoder
    input clk, // Clock input
    input reset, // Active-high synchronous reset input
    output reg [3:0] count // 4-bit output of the counter
);

wire [1:0] enc1_out; // Output of the first 4-to-2 priority encoder
wire [1:0] enc2_out; // Output of the second 4-to-2 priority encoder

// Implementing the first 4-to-2 priority encoder using NAND gates
assign enc1_out[0] = ~(in[0] & in[1]);
assign enc1_out[1] = ~(in[2] & in[3]);

// Implementing the second 4-to-2 priority encoder using NAND gates
assign enc2_out[0] = ~(enc1_out[0] & enc1_out[1]);
assign enc2_out[1] = ~(enc1_out[0] & ~enc1_out[1]);
assign enc2_out[2] = ~(~enc1_out[0] & enc1_out[1]);
assign enc2_out[3] = ~(~enc1_out[0] & ~enc1_out[1]);

always @(posedge clk) begin
    if (reset) begin
        count <= 0;
    end else begin
        case (enc2_out)
            4'b0001: count <= count + 1;
            default: count <= 0;
        endcase
    end
end

endmodule

module mem_ctrl(
	CLK,
	RESETn,
	ADDR,
	DATA_IN,
	MEM_REQ,
	MEM_WRITE,
	DATA_OUT,
	MEM_ACK_OUT
);
	parameter MEM_DEPTH = 65536;
	parameter LC_MEM_DATA_WIDTH = 32;
	parameter LC_MEM_ADDR_WIDTH = 32;

	input 	CLK;
	input	RESETn;
	input	[LC_MEM_ADDR_WIDTH-1:0]	ADDR;
	input	[LC_MEM_DATA_WIDTH-1:0]	DATA_IN;
	input	MEM_REQ;
	input	MEM_WRITE;
	output	reg [LC_MEM_DATA_WIDTH-1:0]	DATA_OUT;
	output	reg	MEM_ACK_OUT;

	reg	 [LC_MEM_DATA_WIDTH-1:0] mem_array [0:MEM_DEPTH-1];
	reg	[1:0] fsm;
	wire	[log2(MEM_DEPTH-1):0] addr_equal = ADDR[log2(MEM_DEPTH-1):0];

	parameter IDLE = 2'b00;
	parameter CLEAR = 2'b01;
	parameter WRITE = 2'b10;
	parameter READ = 2'b11;

	always @ (posedge CLK or negedge RESETn)
	begin
		if (~RESETn)
		begin
			fsm <= IDLE;
			MEM_ACK_OUT <= 0;
			DATA_OUT <= 0;
		end
		else
		begin
			case (fsm)
				IDLE:
				begin
					if ((MEM_REQ) && (ADDR<MEM_DEPTH))
					begin
						if (MEM_WRITE)
							fsm <= WRITE;
						else
							fsm <= READ;
					end
				end

				WRITE:
				begin
					mem_array[addr_equal] <= DATA_IN;
					MEM_ACK_OUT <= 1;
					fsm <= CLEAR;
				end

				READ:
				begin
					DATA_OUT <= mem_array[addr_equal];
					MEM_ACK_OUT <= 1;
					fsm <= CLEAR;
				end

				CLEAR:
				begin
					if (~MEM_REQ)
					begin
						fsm <= IDLE;
						MEM_ACK_OUT <= 0;
					end
				end
			endcase
		end
	end

endmodule

module div_16bit_unsigned (
    input clk,
    input reset,      // Synchronous active-high reset
    input [15:0] D,   // 16-bit dividend input
    input [15:0] V,   // 16-bit divisor input
    output reg [15:0] Q, // 16-bit quotient output
    output reg [15:0] R  // 16-bit remainder output
);

    reg [15:0] dividend_reg;
    reg [15:0] divisor_reg;
    reg [15:0] quotient_reg;
    reg [15:0] remainder_reg;
    reg [3:0] count_reg;

    always @(posedge clk) begin
        if (reset) begin
            dividend_reg <= 0;
            divisor_reg <= 0;
            quotient_reg <= 0;
            remainder_reg <= 0;
            count_reg <= 0;
        end else begin
            if (count_reg < 16) begin
                dividend_reg <= {dividend_reg[14:0], D[count_reg]};
                divisor_reg <= {divisor_reg[14:0], V[count_reg]};
                count_reg <= count_reg + 1;
            end else begin
                count_reg <= 0;
                quotient_reg <= 0;
                remainder_reg <= dividend_reg;
                for (count_reg = 15; count_reg >= 0; count_reg = count_reg - 1) begin
                    quotient_reg <= {quotient_reg[14:0], remainder_reg[15]};
                    remainder_reg <= {remainder_reg[14:0], remainder_reg[15]} - (divisor_reg << 1);
                    if (remainder_reg[15] == 1) begin
                        remainder_reg <= remainder_reg + divisor_reg;
                    end
                end
                Q <= quotient_reg;
                R <= remainder_reg;
            end
        end
    end
endmodule

module sum_of_squares (
    input [15:0] Q, // 16-bit quotient input
    input [15:0] R, // 16-bit remainder input
    output reg [31:0] out // Sum of squares output
);

    always @(*) begin
        out = (Q * Q) + (R * R);
    end
endmodule

module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [15:0] D,   // 16-bit dividend input
    input [15:0] V,   // 16-bit divisor input
    input select,     // Select input to switch between modules
    output reg [15:0] Q, // 16-bit quotient output
    output reg [15:0] R, // 16-bit remainder output
    output reg [31:0] out // Sum of squares output from the functional module
);

    reg [15:0] Q_reg;
    reg [15:0] R_reg;
    reg [31:0] out_reg;

    div_16bit_unsigned div_inst (
        .clk(clk),
        .reset(reset),
        .D(D),
        .V(V),
        .Q(Q_reg),
        .R(R_reg)
    );

    sum_of_squares sum_inst (
        .Q(Q_reg),
        .R(R_reg),
        .out(out_reg)
    );

    always @(posedge clk) begin
        if (reset) begin
            Q_reg <= 0;
            R_reg <= 0;
            out_reg <= 0;
        end else begin
            if (select == 0) begin
                Q_reg <= div_inst.Q;
                R_reg <= div_inst.R;
                out_reg <= 0;
            end else begin
                Q_reg <= 0;
                R_reg <= 0;
                out_reg <= sum_inst.out;
            end
        end
    end

    assign Q = Q_reg;
    assign R = R_reg;
    assign out = out_reg;

endmodule

module adder (
    input [3:0] A,
    input [3:0] B,
    input sel,
    output reg [3:0] C
);

    wire [3:0] sum;
    wire carry;

    assign sum = A + B;
    assign carry = (A[3] & B[3]) | (A[3] & ~sum[3]) | (B[3] & ~sum[3]);

    always @ (*) begin
        if (sel)
            C = ~{carry, sum};
        else
            C = {carry, sum};
    end

endmodule

module tb_adder;

    reg [3:0] A;
