    adder dut (
        .A(A),
        .B(B),
        .sel(sel),
        .C(C)
    );

    initial begin
        $monitor("A=%d, B=%d, sel=%d, C=%d", A, B, sel, C);
        A = 4'b0000; B = 4'b0000; sel = 0; #10;
        A = 4'b0001; B = 4'b0001; sel = 0; #10;
        A = 4'b0010; B = 4'b0100; sel = 0; #10;
        A = 4'b1111; B = 4'b1111; sel = 0; #10;
        A = 4'b0000; B = 4'b0000; sel = 1; #10;
        A = 4'b0001; B = 4'b0001; sel = 1; #10;
        A = 4'b0010; B = 4'b0100; sel = 1; #10;
        A = 4'b1111; B = 4'b1111; sel = 1; #10;
        $finish;
    end

endmodule

module pipelined_ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    input clk,
    output reg [3:0] S,
    output reg C_OUT
);

reg [3:0] P1_S, P2_S, P3_S;
reg P1_C, P2_C, P3_C;

// Pipeline stage 1
always @(posedge clk) begin
    P1_S <= A + B;
    P1_C <= (A[3] & B[3]) | (A[3] & P1_S[3]) | (B[3] & P1_S[3]);
end

// Pipeline stage 2
always @(posedge clk) begin
    P2_S <= P1_S;
    P2_C <= (A[2] & B[2]) | (A[2] & P2_S[2]) | (B[2] & P2_S[2]) | (P1_C & P1_S[3]);
end

// Pipeline stage 3
always @(posedge clk) begin
    P3_S <= P2_S;
    P3_C <= (A[1] & B[1]) | (A[1] & P3_S[1]) | (B[1] & P3_S[1]) | (P2_C & P2_S[2]);
end

// Output stage
always @(posedge clk) begin
    S <= P3_S;
    C_OUT <= (A[0] & B[0]) | (A[0] & S[0]) | (B[0] & S[0]) | (P3_C & P3_S[1]);
end

endmodule

module binary_to_gray_converter (
    input [3:0] B,
    input EN,
    output [3:0] G
);

reg [3:0] gray_reg1, gray_reg2, gray_reg3;

assign G = EN ? gray_reg3 : G;

always @ (posedge EN)
begin
    gray_reg1 <= B;
    gray_reg2 <= gray_reg1 ^ (gray_reg1 >> 1);
    gray_reg3 <= gray_reg2 ^ (gray_reg2 >> 2);
end

endmodule

