module top_module (
    input clk,
    input load,
    input [1:0] ena,
    input [99:0] data,
    input A1, A2, B1, B2, SEL1, SEL2,
    output [99:0] q_rotator,
    output Y1, Y2, Y3,
    output [99:0] q_and
);

    barrel_shifter rotator (
        .clk(clk),
        .load(load),
        .ena(ena),
        .data(data),
        .q_rotator(q_rotator)
    );

    multiplexer mux (
        .A1(A1),
        .A2(A2),
        .B1(B1),
        .B2(B2),
        .SEL1(SEL1),
        .SEL2(SEL2),
        .Y1(Y1),
        .Y2(Y2),
        .Y3(Y3)
    );

    and_gate and (
        .a(q_rotator),
        .b({Y1, Y2, Y3}),
        .q_and(q_and)
    );

endmodule

module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    input C_in,
    output [3:0] S,
    output C_out
);

    wire [3:0] sum;
    wire [4:0] carry;

    // Full adder instances
    full_adder fa0 (.sum(sum[0]), .C_out(carry[1]), .A(A[0]), .B(B[0]), .C_in(C_in));
    full_adder fa1 (.sum(sum[1]), .C_out(carry[2]), .A(A[1]), .B(B[1]), .C_in(carry[1]));
    full_adder fa2 (.sum(sum[2]), .C_out(carry[3]), .A(A[2]), .B(B[2]), .C_in(carry[2]));
    full_adder fa3 (.sum(sum[3]), .C_out(C_out), .A(A[3]), .B(B[3]), .C_in(carry[3]));

    assign S = sum;

endmodule

module full_adder (
    input A,
    input B,
    input C_in,
    output sum,
    output C_out
);

    assign sum = A ^ B ^ C_in;
    assign C_out = (A & B) | (C_in & (A ^ B));

endmodule

module accumulator_system (
    input               clk         ,   
    input               rst_n       ,
