    );

    // Instantiate the adder module
    adder adder_inst (
        .clk(clk),
        .rst_n(rst_n),
        .data_in_1(accu_data_out),
        .data_in_2(top_data_out),
        .valid_a(accu_valid_b & top_valid_b),
        .ready_a(adder_ready_a),
        .valid_b(adder_valid_b),
        .data_out(adder_data_out)
    );

    // Instantiate the LED display module
    led_display led_inst (
        .clk(clk),
        .rst_n(rst_n),
        .data_in(adder_data_out),
        .valid_a(adder_valid_b),
        .ready_a(led_ready_a),
        .led_out(led_out)
    );

    // Pipeline registers
    reg [7:0]   accu_data_out;
    reg         accu_valid_b;
    reg         accu_ready_a;
    reg [7:0]   top_data_out;
    reg         top_valid_b;
    reg         top_ready_a;
    reg [7:0]   adder_data_out;
    reg         adder_valid_b;
    reg         adder_ready_a;
    reg [9:0]   led_out;
    reg         led_ready_a;

    // Valid-ready handshake for accu module
    always @(posedge clk) begin
        if (rst_n == 1'b0) begin
            accu_valid_b <= 1'b0;
            accu_ready_a <= 1'b0;
        end else begin
            if (valid_a && accu_ready_a) begin
                accu_valid_b <= 1'b1;
            end else begin
                accu_valid_b <= 1'b0;
            end

            if (valid_b && accu_valid_b) begin
                accu_ready_a <= 1'b1;
            end else begin
                accu_ready_a <= 1'b0;
            end
        end
    end

    // Valid-ready handshake for top_module
    always @(posedge clk) begin
        if (rst_n == 1'b0) begin
            top_valid_b <= 1'b0;
            top_ready_a <= 1'b0;
        end else begin
            if (valid_a && top_ready_a && !select) begin
                top_valid_b <= 1'b1;
            end else begin
                top_valid_b <= 1'b0;
            end

            if (valid_b && top_valid_b) begin
                top_ready_a <= 1'b1;
            end else begin
                top_ready_a <= 1'b0;
            end
        end
    end

    // Valid-ready handshake for adder module
    always @(posedge clk) begin
        if (rst_n == 1'b0) begin
            adder_valid_b <= 1'b0;
            adder_ready_a <= 1'b0;
        end else begin
            if (accu_valid_b && top_valid_b && adder_ready_a) begin
                adder_valid_b <= 1'b1;
            end else begin
                adder_valid_b <= 1'b0;
            end

            if (adder_valid_b && led_ready_a) begin
                adder_ready_a <= 1'b1;
            end else begin
                adder_ready_a <= 1'b0;
            end
        end
    end

    // Valid-ready handshake for LED display module
    always @(posedge clk) begin
        if (rst_n == 1'b0) begin
            led_ready_a <= 1'b0;
        end else begin
            if (adder_valid_b && !led_ready_a) begin
                led_ready_a <= 1'b1;
            end else begin
                led_ready_a <= 1'b0;
            end
        end
    end

endmodule

// Accu module
module accu (
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [7:0]   data_out
);

    // Pipeline register
    reg [7:0]   accu_reg;

    // Valid-ready handshake
    always @(posedge clk) begin
        if (rst_n == 1'b0) begin
            valid_b <= 1'b0;
            ready_a <= 1'b0;
            accu_reg <= 8'b0;
        end else begin
            if (valid_a && ready_a) begin
                accu_reg <= {accu_reg[6:0], data_in};
            end

            if (accu_reg[7] && valid_a && ready_a) begin
                valid_b <= 1'b1;
            end else begin
                valid_b <= 1'b0;
            end

            if (valid_b && !ready_a) begin
                ready_a <= 1'b1;
            end else begin
                ready_a <= 1'b0;
            end
        end
    end

    // Output the accumulated result
    assign data_out = accu_reg;

endmodule

// Top module
module top_module (
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [7:0]   data_out
);

    // Pipeline register
    reg [7:0]   top_reg;

    // Valid-ready handshake
    always @(posedge clk) begin
        if (rst_n == 1'b0) begin
            valid_b <= 1'b0;
            ready_a <= 1'b0;
            top_reg <= 8'b0;
        end else begin
            if (valid_a && ready_a) begin
                top_reg <= {top_reg[6:0], data_in};
            end

            if (top_reg[7] && valid_a && ready_a) begin
                valid_b <= 1'b1;
            end else begin
                valid_b <= 1'b0;
            end

            if (valid_b && !ready_a) begin
                ready_a <= 1'b1;
            end else begin
                ready_a <= 1'b0;
            end
        end
    end

    // Output the accumulated result
    assign data_out = top_reg;

endmodule

// Adder module
module adder (
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in_1   ,
    input       [7:0]   data_in_2   ,
    input               valid_a     ,
    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [7:0]   data_out
);

    // Valid-ready handshake
    always @(posedge clk) begin
        if (rst_n == 1'b0) begin
            valid_b <= 1'b0;
            ready_a <= 1'b0;
        end else begin
            if (valid_a && ready_a) begin
                data_out <= data_in_1 + data_in_2;
            end

            if (valid_a && ready_a) begin
                valid_b <= 1'b1;
            end else begin
                valid_b <= 1'b0;
            end

            if (valid_b && !ready_a) begin
                ready_a <= 1'b1;
            end else begin
                ready_a <= 1'b0;
            end
        end
    end

endmodule

