module top_module (
    input clk,
    input reset, // Synchronous active-high reset
    output reg [3:0] counter_out, // 4-bit output from the counter
    input [3:0] encoder_in, // 4-bit input for the priority encoder
    output reg [1:0] encoder_out, // 2-bit output from the priority encoder
    output reg [3:0] and_out // 4-bit output from the AND module
);

reg [3:0] counter_reg; // Register to hold the counter value

// Counter module
always @(posedge clk) begin
    if (reset) begin
        counter_reg <= 4'b0000;
    end else begin
        counter_reg <= counter_reg + 1;
    end
end

assign counter_out = counter_reg;

// Priority encoder module
always @* begin
    case(encoder_in)
        4'b0001: encoder_out = 2'b00;
        4'b0010: encoder_out = 2'b01;
        4'b0100: encoder_out = 2'b10;
        4'b1000: encoder_out = 2'b11;
        default: encoder_out = 2'b00;
    endcase
end

// AND module
always @* begin
    and_out = counter_reg & {2'b00, encoder_out};
end

endmodule

module ALU #(parameter N=32)(
    input [3:0] op_code,
    input signed [N-1:0] operand1,
    input signed [N-1:0] operand2,
    input clk,
    output reg signed [N-1:0] result,
    output reg zero,
    output reg overflow
    );

    always @(posedge clk) begin
        case(op_code)
            0: begin //SLL
                result = operand2 << operand1[4:0];
                zero = (result == 0);
                overflow = 0;
            end
            1: begin //SRL
                result = operand2 >> operand1[4:0];
                zero = (result == 0);
                overflow = 0;
            end
            2: begin //SRA
                result = operand2 >>> operand1[4:0];
                zero = (result == 0);
                overflow = 0;
            end
            3: begin //ADD
                result = operand1 + operand2;
                zero = (result == 0);
                overflow = (result[N-1] != operand1[N-1] && result[N-1] != operand2[N-1]);
            end
            4: begin //SUB
                result = operand1 - operand2;
                zero = (result == 0);
                overflow = (result[N-1] != operand1[N-1] && result[N-1] == operand2[N-1]);
            end
            5: begin //AND
                result = operand1 & operand2;
                zero = (result == 0);
                overflow = 0;
            end
            6: begin //OR
                result = operand1 | operand2;
                zero = (result == 0);
                overflow = 0;
            end
            7: begin //XOR
                result = operand1 ^ operand2;
                zero = (result == 0);
                overflow = 0;
            end
            8: begin //NOR
                result = ~(operand1 | operand2);
                zero = (result == 0);
                overflow = 0;
            end
            9: begin //SLT
                result = (operand1 < operand2);
                zero = (result == 0);
                overflow = 0;
            end
            default: begin
                result = 0;
                zero = 0;
                overflow = 0;
            end
        endcase
    end

endmodule

