module cache_controller (
  input enable, clk, rst,
  input [3:0] index,
  input [1:0] word,
  input comp,
  input write,
  input [4:0] tag_in,
  input [15:0] data_in,
  input valid_in,
  output reg hit,
  output reg dirty,
  output reg [4:0] tag_out,
  output reg [15:0] data_out,
  output reg valid
);

  // Internal signals
  reg [4:0] cache_tag;
  reg [15:0] cache_data;
  reg cache_valid;
  reg cache_dirty;
  reg cache_hit;
  reg cache_wr;
  wire [15:0] mem_data;
  reg mem_wr;
  reg [15:0] mem_addr;
  wire mem_ack;

  // Cache module instance
  cache_ctl cache_inst (
    .enable(enable),
    .clk(clk),
    .index(index),
    .word(word),
    .comp(comp),
    .write(write),
    .tag_in(tag_in),
    .data_in(data_in),
    .valid_in(valid_in),
    .rst(rst),
    .hit(cache_hit),
    .dirty(cache_dirty),
    .tag_out(cache_tag),
    .data_out(cache_data),
    .valid(cache_valid)
  );

  // Memory module instance
  mem_ctl mem_inst (
    .clk(clk),
    .addr(mem_addr),
    .data(mem_data),
    .wr(mem_wr),
    .rd(!mem_wr),
    .ack(mem_ack)
  );

  always @ (posedge clk) begin
    if (enable) begin
      // Read operation
      if (comp == 0) begin
        if (cache_hit) begin
          hit <= 1'b1;
          tag_out <= cache_tag;
          data_out <= cache_data[word*16 +: 16];
          valid <= cache_valid;
        end
        else begin
          hit <= 1'b0;
          mem_addr <= {tag_in, index};
          mem_wr <= 1'b0;
          cache_wr <= 1'b1;
          cache_tag <= tag_in;
          cache_data <= mem_data;
          cache_valid <= mem_ack;
          tag_out <= tag_in;
          data_out <= mem_data[word*16 +: 16];
          valid <= mem_ack;
        end
      end

      // Write operation
      else begin
        if (cache_hit) begin
          hit <= 1'b1;
          tag_out <= cache_tag;
          data_out <= cache_data[word*16 +: 16];
          valid <= cache_valid;
          cache_wr <= 1'b1;
          cache_dirty <= 1'b1;
          cache_data[word*16 +: 16] <= data_in;
        end
        else begin
          hit <= 1'b0;
          mem_addr <= {tag_in, index};
          mem_data <= data_in;
          mem_wr <= 1'b1;
          cache_wr <= 1'b1;
          cache_tag <= tag_in;
          cache_data <= data_in;
          cache_valid <= 1'b1;
          tag_out <= tag_in;
          data_out <= data_in;
          valid <= 1'b1;
        end
      end
    end
    else begin
      hit <= 1'b0;
      dirty <= 1'b0;
      tag_out <= 5'b0;
      data_out <= 16'b0;
      valid <= 1'b0;
      cache_wr <= 1'b0;
      cache_dirty <= 1'b0;
    end
  end

  always @ (negedge clk) begin
    cache_wr <= 1'b0;
    cache_dirty <= 1'b0;
  end

endmodule

module Fletcher (
  input [n-1:0] data,
  output [31:0] checksum
);

parameter n = 4; // number of data words

reg [31:0] sum1, sum2;
reg [31:0] data_complement;
integer i;

always @* begin
  sum1 = 0;
  sum2 = 0;
  for (i = 0; i < n; i = i + 1) begin
    data_complement = ~data[i];
    sum1 = sum1 + data[i] + data_complement;
    sum2 = sum2 + sum1;
  end
  checksum = ~(sum1 + sum2);
end

endmodule

