module ram_dual_port_turnos (
    input wire clk,
    input wire whichturn,
    input wire [18:0] vramaddr,
    input wire [18:0] cpuramaddr,
    input wire cpu_we_n,
    input wire [7:0] data_from_cpu,
    output reg [7:0] data_to_asic,
    output reg [7:0] data_to_cpu,
    // Actual interface with SRAM
    output reg [18:0] sram_a,
    output reg sram_we_n,
    inout wire [7:0] sram_d
    );

    // Define internal registers
    reg [7:0] cpu_data;
    reg [7:0] asic_data;

    // Set sram_d to data_from_cpu if CPU is writing to RAM
    assign sram_d = (cpu_we_n == 1'b0 && whichturn == 1'b0)? data_from_cpu : 8'hZZ;    

    // Define combinational logic to set outputs
    always @* begin
        // Set data_to_asic if ASIC is accessing RAM
        if (whichturn == 1'b1) begin
            sram_a = vramaddr;
            sram_we_n = 1'b1;
            data_to_asic = sram_d;
            asic_data = sram_d;
        end
        // Set data_to_cpu if CPU is accessing RAM
        else begin
            sram_a = cpuramaddr;
            sram_we_n = cpu_we_n;
            if (cpu_we_n == 1'b0) begin
                cpu_data = data_from_cpu;
            end
            data_to_cpu = (cpu_we_n == 1'b1)? sram_d : cpu_data;
        end
    end

    // Define sequential logic to synchronize outputs with clock
    always @(posedge clk) begin
        data_to_asic <= asic_data;
    end
endmodule

module audioManager(
  input clock_27mhz, 
  input memReset, 

  // User I/O
  input startSwitch,
  input [3:0] percent_kept,
  input writeSwitch, 
  output reg [15:0] audioOut,
  output reg [15:0] flashOut,
  output reg busyOut,
  output reg [31:24] user2,
  output reg rxf,
  output reg rd,

  // AC97 I/O
  input ready,
  input [15:0] from_ac97_data,
  output [15:0] to_ac97_data,

  // Flash I/O
  inout [15:0] flash_data,
  output reg [15:0] flash_address,
  output reg flash_ce_b,
  output reg flash_oe_b,
  output reg flash_we_b,
  output reg flash_reset_b,
  output reg flash_byte_b,
  input flash_sts,
  output reg busy,

  // USB I/O
  input [31:24] data,
  input rxf_b,
  output rd_b
);

  // Audio processing logic
  reg [15:0] audioIn;
  always @(posedge clock_27mhz) begin
    if (startSwitch) begin
      audioIn <= from_ac97_data;
    end
    if (audioTrigger) begin
      audioOut <= audioIn * percent_kept;
    end
  end

  // Flash memory logic
  reg [15:0] flashDataIn;
  always @(posedge clock_27mhz) begin
    if (flash_ce_b == 0 && flash_oe_b == 0 && flash_we_b == 1) begin
      flashDataIn <= flash_data;
      flash_address <= flash_address + 1;
    end
    if (flash_ce_b == 0 && flash_oe_b == 1 && flash_we_b == 0) begin
      flashOut <= flashDataIn;
    end
  end

  // USB logic
  reg [31:0] usbDataIn;
  always @(posedge clock_27mhz) begin
    if (rxf_b == 0) begin
      usbDataIn <= data;
    end
    if (rd_b == 0) begin
      user2 <= usbDataIn[31:24];
      rxf <= usbDataIn[23];
      rd <= usbDataIn[22];
    end
  end

  // Flash memory busy signal
  always @(posedge clock_27mhz) begin
