      flash_oe_b <= 1;
      flash_we_b <= 0;
      flash_byte_b <= 1;
      flash_reset_b <= 1;
      busyOut <= 1;
    end
    else begin
      flash_ce_b <= 1;
      flash_oe_b <= 1;
      flash_we_b <= 1;
      flash_byte_b <= 1;
      flash_reset_b <= 0;
      busyOut <= busy;
    end
  end

  // AC97 codec logic
  always @(posedge clock_27mhz) begin
    if (ready) begin
      to_ac97_data <= audioOut;
    end
  end

endmodule

