module CPU(
    input clk_i,
    input rst_i,
    input start_i,
    input [31:0] instruction_memory [0:127],
    inout [31:0] data_memory [0:63],
    output reg [31:0] pc_o,
    inout [31:0] register [0:31]
);

reg [31:0] instruction;
reg [31:0] rs;
reg [31:0] rt;
reg [31:0] rd;
reg [31:0] immediate;
reg [31:0] address;
reg [31:0] alu_out;
reg [31:0] data_out;
reg [4:0] opcode;
reg [5:0] rs_addr;
reg [5:0] rt_addr;
reg [5:0] rd_addr;
reg [15:0] imm;
reg [31:0] pc_next;
reg [2:0] alu_op;
reg [1:0] mem_op;
reg [1:0] mem_width;
reg [31:0] mem_addr;

always @(posedge clk_i) begin
    if (rst_i) begin
        pc_o <= 0;
        register <= 0;
    end else begin
        if (start_i) begin
            pc_o <= 0;
            register <= 0;
            pc_next <= 0;
        end else begin
            pc_o <= pc_next;
            register[0] <= 0; // R0 is always 0
            if (opcode == 6'b001000) begin // lw
                mem_op <= 2'b10;
                mem_width <= 2'b01;
                mem_addr <= alu_out;
            end else if (opcode == 6'b101000) begin // sw
                mem_op <= 2'b01;
                mem_width <= 2'b01;
                mem_addr <= alu_out;
                data_out <= rt;
            end else begin
                mem_op <= 2'b00;
            end
            if (mem_op == 2'b10) begin // read from memory
                case (mem_width)
                    2'b00: data_out <= data_memory[mem_addr][7:0];
                    2'b01: data_out <= data_memory[mem_addr];
                    2'b10: data_out <= {data_memory[mem_addr+1], data_memory[mem_addr]};
                endcase
            end else if (mem_op == 2'b01) begin // write to memory
                case (mem_width)
                    2'b00: data_memory[mem_addr][7:0] <= data_out;
                    2'b01: data_memory[mem_addr] <= data_out;
                    2'b10: begin
                        data_memory[mem_addr] <= data_out[31:8];
                        data_memory[mem_addr+1] <= data_out[7:0];
                    end
                endcase
            end else begin // no memory operation
                case (alu_op)
                    3'b000: alu_out <= rs + rt; // add
                    3'b001: alu_out <= rs - rt; // sub
                    3'b010: alu_out <= rs & rt; // and
                    3'b011: alu_out <= rs | rt; // or
                    3'b100: alu_out <= (rs < rt) ? 1 : 0; // slt
                endcase
                if (opcode == 6'b000100) begin // beq
                    pc_next <= (rs == rt) ? (pc_o + (immediate << 2)) : (pc_o + 4);
                end else begin
                    pc_next <= pc_o + 4;
                end
                if (rd_addr != 0) begin
                    register[rd_addr] <= alu_out;
                end
            end
        end
    end
end

always @(posedge clk_i) begin
    if (rst_i) begin
        rs <= 0;
        rt <= 0;
        rd <= 0;
        immediate <= 0;
        address <= 0;
        opcode <= 0;
        rs_addr <= 0;
        rt_addr <= 0;
        rd_addr <= 0;
        imm <= 0;
        alu_op <= 0;
        mem_op <= 0;
        mem_width <= 0;
        mem_addr <= 0;
    end else begin
        if (start_i) begin
            rs <= 0;
            rt <= 0;
            rd <= 0;
            immediate <= 0;
            address <= 0;
            opcode <= 0;
            rs_addr <= 0;
            rt_addr <= 0;
            rd_addr <= 0;
            imm <= 0;
            alu_op <= 0;
            mem_op <= 0;
            mem_width <= 0;
            mem_addr <= 0;
        end else begin
            instruction <= instruction_memory[pc_o >> 2];
            opcode <= instruction[31:26];
            rs_addr <= instruction[25:21];
            rt_addr <= instruction[20:16];
            rd_addr <= instruction[15:11];
            imm <= instruction[15:0];
            address <= instruction[25:0];
            rs <= register[rs_addr];
            rt <= register[rt_addr];
            rd <= register[rd_addr];
            immediate <= imm;
            case (opcode)
                6'b000000: begin // R-type
                    alu_op <= instruction[5:3];
                end
                6'b001000: begin // lw
                    alu_op <= 3'b000;
                end
                6'b101000: begin // sw
                    alu_op <= 3'b000;
                end
                6'b000100: begin // beq
                    alu_op <= 3'b001;
                end
            endcase
        end
    end
end

endmodule

