module binary_adder(
    input [4:0] a,
    input [4:0] b,
    output [4:0] sum,
    output carry
);

    wire c1, c2, c3, c4, c5;
    wire s1, s2, s3, s4, s5;

    // Full Adders
    full_adder fa1(a[0], b[0], 1'b0, s1, c1);
    full_adder fa2(a[1], b[1], c1, s2, c2);
    full_adder fa3(a[2], b[2], c2, s3, c3);
    full_adder fa4(a[3], b[3], c3, s4, c4);
    full_adder fa5(a[4], b[4], c4, s5, c5);

    // Sum output
    assign sum = {s5, s4, s3, s2, s1};

    // Carry output
    assign carry = c5;

endmodule

module full_adder(
    input a,
    input b,
    input cin,
    output sum,
    output cout
);

    wire s1, c1, c2;

    // Half Adder 1
    half_adder ha1(a, b, s1, c1);

    // Half Adder 2
    half_adder ha2(s1, cin, sum, c2);

    // Carry output
    assign cout = c1 | c2;

endmodule

module half_adder(
    input a,
    input b,
    output sum,
    output carry
);

    // Sum output
    assign sum = a ^ b;

    // Carry output
    assign carry = a & b;

endmodule

module RLE (
  input [n-1:0] in,
  output [m-1:0] out,
  input mode
);

parameter n = 8; // number of input signals
parameter m = 8; // number of output signals
parameter k = 4; // maximum number of consecutive repetitions that can be encoded.

reg [n-1:0] input_reg;
reg [m-1:0] output_reg;
reg [k-1:0] count_reg;
reg [n-1:0] value_reg;
reg encoding_mode;

always @(posedge clk) begin
  if (reset) begin
    input_reg <= 0;
    output_reg <= 0;
    count_reg <= 0;
    value_reg <= 0;
    encoding_mode <= 1'b0;
  end else begin
    if (mode) begin // decoding mode
      if (count_reg == 0) begin
        value_reg <= in;
        count_reg <= 1;
      end else if (count_reg == k) begin
        output_reg <= value_reg;
        count_reg <= 0;
      end else if (in == value_reg) begin
        count_reg <= count_reg + 1;
      end else begin
        output_reg <= value_reg;
        value_reg <= in;
        count_reg <= 1;
      end
    end else begin // encoding mode
      if (count_reg == 0) begin
        value_reg <= in;
        count_reg <= 1;
      end else if (count_reg == k) begin
        output_reg <= {value_reg, count_reg};
        count_reg <= 1;
        value_reg <= in;
      end else if (in == value_reg) begin
        count_reg <= count_reg + 1;
      end else begin
        output_reg <= {value_reg, count_reg};
        value_reg <= in;
        count_reg <= 1;
      end
    end
    out <= output_reg;
    input_reg <= in;
    encoding_mode <= mode;
  end
end

