    wire start_barra, start_bola;
    wire [4:0] speed_bola;

    reg [4:0] state;
    reg [9:0] barra_y_reg;
    reg bola_x_reg;
    reg [9:0] bola_y_reg;

    //Definimos los estados
    parameter STATE_0 = 0;
    parameter STATE_1 = 1;
    parameter STATE_2 = 2;
    parameter STATE_3 = 3;
    parameter STATE_4 = 4;
    parameter STATE_5 = 5;
    parameter STATE_6 = 6;

    //Submaquina de estados que controla la barra del juego
    fsm_barra mod_fsm_barra(
        .clk(clk),
        .start_barra(start_barra),
        .bussy_barra(bussy_barra),
        .barra_y(barra_y_reg),
        .speed(speed),
        .up_sync(up_sync),
        .down_sync(down_sync)
    );

    //Submaquina de estados que controla la bola
    fsm_bola mod_fsm_bola(
        .clk(clk),
        .start_bola(start_bola),
        .bussy_bola(bussy_bola),
        .perido(perdio),
        .bola_x(bola_x_reg),
        .bola_y(bola_y_reg),
        .speed(speed_bola),
        .barra_y(barra_y_reg)
    );

    //Se realiza el recorrido estado por estado
    always @(posedge clk) begin
        if (reset_sync) begin
            state <= STATE_0;
            barra_y_reg <= 5'h1F;
            bola_x_reg <= 5'h1E;
            bola_y_reg <= 10'h1FC;
        end
        else begin
            case(state)
                STATE_0: begin
                    if (start_main) begin
                        state <= STATE_1;
                    end
                end

                STATE_1: begin
                    if (v_sync) begin
                        state <= STATE_2;
                    end
                end

                STATE_2: begin
                    start_barra <= 1;
                    state <= STATE_3;
                end

                STATE_3: begin
                    if (!bussy_barra) begin
                        start_barra <= 0;
                        state <= STATE_4;
                    end
                end

                STATE_4: begin
                    speed_bola <= speed;
                    start_bola <= 1;
                    state <= STATE_5;
                end

                STATE_5: begin
                    if (!bussy_bola) begin
                        start_bola <= 0;
                        state <= STATE_6;
                    end
                end

                STATE_6: begin
                    if (perdio) begin
                        state <= STATE_0;
                    end
                    else begin
                        state <= STATE_1;
                    end
                end
            endcase
        end
    end

    assign barra_y = barra_y_reg;
    assign bola_x = bola_x_reg;
    assign bola_y = bola_y_reg;

endmodule

module shift(
    input        clk      ,
    input        rst      ,
    input        vld      ,
    input  [1:0] cmd      ,
    input        cmd_oen  ,
    input  [7:0] din      ,
    output       done     ,

    output       sft_shcp ,
    output       sft_ds   ,
    output       sft_stcp ,
    output       sft_mr_n ,
    output       sft_oe_n 
);

    reg sft_mr_n ;
    reg sft_oe_n ;
    always @ ( posedge clk or posedge rst ) begin
        if( rst )
            sft_mr_n <= 1'b1 ;
        else if( vld && cmd == 2'b00 )
            sft_mr_n <= 1'b0 ;
        else
            sft_mr_n <= 1'b1 ;
    end

    always @ ( posedge clk or posedge rst ) begin
        if( rst )
            sft_oe_n <= 1'b1 ;
        else if( vld && cmd == 2'b11 )
            sft_oe_n <= cmd_oen ;
    end

    //--------------------------------------------------
    // shcp counter
    //--------------------------------------------------
    reg [4:0] shcp_cnt ;
    always @ ( posedge clk ) begin
        if( rst )
            shcp_cnt <= 0 ;
        else if( vld && cmd == 2'b01 )
            shcp_cnt <= 1 ;
        else if( |shcp_cnt )
            shcp_cnt <= shcp_cnt + 1 ;
    end

    assign sft_shcp = shcp_cnt[1] ;

    reg [7:0] data ;
    always @ ( posedge clk ) begin
        if( vld && cmd == 2'b01 )
            data <= din ;
        else if( &shcp_cnt[1:0] )
            data <= data >> 1 ;
    end

    assign sft_ds = (vld&&cmd==2'b01) ? din[0] : data[0] ;


    //--------------------------------------------------
    // sft_stcp
    //--------------------------------------------------
    reg [4:0] stcp_cnt ;
    always @ ( posedge clk ) begin
        if( rst )
            stcp_cnt <= 0 ;
        else if( vld && cmd == 2'b10 )
            stcp_cnt <= 1 ;
        else if( |stcp_cnt )
            stcp_cnt <= stcp_cnt + 1 ;
    end
    assign sft_stcp = stcp_cnt[1] ;

    //--------------------------------------------------
    // done
    //--------------------------------------------------
    assign done = (stcp_cnt == 31) || (shcp_cnt == 31) ;

endmodule

