    reg [6:0] shift_amt;
    wire [99:0] shifted_data;

    always @(*) begin
        case(ena)
            2'b00: shift_amt = 0;
            2'b01: shift_amt = 1;
            2'b10: shift_amt = 99;
            2'b11: shift_amt = 98;
        endcase
    end

    assign shifted_data = {data[shift_amt-1:0], data[99:shift_amt]};

    always @(posedge clk) begin
        if(load) begin
            temp_data <= data;
        end else if(ena == 2'b00 || ena == 2'b10) begin
            temp_data <= shifted_data;
        end else if(ena == 2'b01) begin
            temp_data <= {shifted_data[99], shifted_data[99:1]};
        end else if(ena == 2'b11) begin
            temp_data <= {shifted_data[0], shifted_data[98:0]};
        end
    end

    always @(*) begin
        if(ena == 2'b00 || ena == 2'b10) begin
            q = temp_data;
        end else if(ena == 2'b01) begin
            q = {temp_data[99], temp_data[99:1]};
        end else if(ena == 2'b11) begin
            q = {temp_data[0], temp_data[98:0]};
