module rotator_byte_reverser(
    input clk,
    input load,
    input [1:0] ena,
    input [99:0] data,
    output reg [99:0] q
);

reg [99:0] shift_reg;
reg [31:0] byte_reversed_output;

always @(posedge clk) begin
    if (load) begin
        shift_reg <= data;
    end else begin
        case (ena)
            2'b00: shift_reg <= {shift_reg[98:0], shift_reg[99]};
            2'b01: shift_reg <= {shift_reg[0], shift_reg[99:1]};
            2'b10: shift_reg <= {shift_reg[97:0], shift_reg[99:98]};
            2'b11: shift_reg <= {shift_reg[1:99], shift_reg[0]};
        endcase
    end
end

always @(shift_reg) begin
    byte_reversed_output[7:0] <= shift_reg[31:24];
    byte_reversed_output[15:8] <= shift_reg[23:16];
    byte_reversed_output[23:16] <= shift_reg[15:8];
    byte_reversed_output[31:24] <= shift_reg[7:0];
end

always @(shift_reg or byte_reversed_output) begin
    q[99:32] <= shift_reg[99:68];
    q[31:0] <= byte_reversed_output;
end

endmodule

