module sys_clk_gen_ds (sys_clk_p, sys_clk_n);

output	         sys_clk_p;
output	         sys_clk_n;

parameter        offset = 0;
parameter        halfcycle = 500;

reg              clk_p;
reg              clk_n;

integer          count;

always @(posedge clk_p or negedge clk_n) begin
    count <= count + 1;
end

always @(posedge clk_p or negedge clk_n) begin
    if (count >= offset) begin
        sys_clk_p <= 1;
        sys_clk_n <= 0;
    end else begin
        sys_clk_p <= 0;
        sys_clk_n <= 1;
    end
end

always @(posedge clk_p or negedge clk_n) begin
    if (count >= offset) begin
        if (count % (halfcycle/2) == 0) begin
            sys_clk_p <= ~sys_clk_p;
            sys_clk_n <= ~sys_clk_n;
        end
    end
end

sys_clk_gen #(
    .halfcycle(halfcycle)
) clk_gen (
    .sys_clk(clk_p)
);

assign clk_n = !clk_p;

endmodule

