module unc_decoder (
        clk     ,   // clock
        nrst    ,   // n reset
        hd_a    ,   // hard decision of a
        hd_b    ,   // hard decision of b
        hd_c    ,   // hard decision of c
        hd_d    ,   // hard decision of d
        start   ,   // start decoding pulse
        vin     ,   // valid input
        vout    ,   // valid output
        dout        // byte out
        ) ;

input           clk ;
input           nrst ;
input           hd_a ;
input           hd_b ;
input           hd_c ;
input           hd_d ;
input           start ;
input           vin ;
output          vout ;
output  [7:0]   dout ;        

//==============================
//Internal signal
//==============================
reg     [7:2]   tmpd ;
reg     [1:0]   cnt ;   
wire    [1:0]   data_2b ;

//==============================
// Main RTL code
//==============================        
assign data_2b = {hd_a, hd_b, hd_c, hd_d} ;
always @ (posedge clk or negedge nrst)
  if (~nrst)
    tmpd <= 0 ;
  else if (start)
    tmpd <= 0 ;
  else if (vin)
  begin
    case (cnt)
      3'd0: tmpd [7:6] <= data_2b ;
      3'd1: tmpd [5:4] <= data_2b ;
      3'd2: tmpd [3:2] <= data_2b ;
      3'd3: tmpd [1:0] <= data_2b ;
      default: tmpd <= tmpd ;
    endcase             
  end

always @ (posedge clk or negedge nrst)
  if (~nrst)
    cnt <= 0 ;
  else if (start)
    cnt <= 0 ;
  else if (vin)
    cnt <= cnt +1 ;

assign vout = vin & (cnt == 3) ;
assign dout = tmpd ;  

endmodule

module EtherCAT_slave (
  input [7:0] frame,
  input rst,
  output [n_pdos*n_inputs_pdo-1:0] pdata,
  output [sm_signals-1:0] sm_signals
);

parameter id = 1; // Device ID
parameter n_pdos = 2; // Number of PDOs
parameter n_inputs_pdo = 4; // Number of inputs per PDO
parameter n_outputs_pdo = 4; // Number of outputs per PDO

// State machine definition
localparam IDLE = 2'b00;
localparam PROCESSING = 2'b01;
localparam ERROR = 2'b10;

reg [1:0] state = IDLE;

// Process data handling logic
reg [n_pdos*n_inputs_pdo-1:0] input_data;
reg [n_pdos*n_outputs_pdo-1:0] output_data;

always @ (posedge clk) begin
  if (rst) begin
    state <= IDLE;
    input_data <= 0;
    output_data <= 0;
  end else begin
    case (state)
      IDLE: begin
        // Wait for frame
        if (frame_valid) begin
          state <= PROCESSING;
        end
      end
      PROCESSING: begin
        // Extract process data from frame
        input_data <= frame[7:0];
        output_data <= frame[15:8];

        // Apply process data to inputs and outputs
        // Your code here

        state <= IDLE;
      end
      ERROR: begin
        // Handle error condition
        // Your code here

        state <= IDLE;
      end
    endcase
  end
end

// State machine signals
assign sm_signals[0] = (state == IDLE);
assign sm_signals[1] = (state == PROCESSING);
assign sm_signals[2] = (state == ERROR);

// Your code here

endmodule

