module clk_gen(
    input wire clk100MHz,
    input wire rst,
    output reg clk1MHz,
    output reg clk5KHz,
    output reg clk200Hz
);

integer count;
integer ledmux;
integer highspeed;

always@(posedge clk100MHz or posedge rst)
begin
	if(rst) begin
		count = 0;   
		highspeed = 0;
		ledmux = 0;
		clk1MHz = 0;
		clk5KHz = 0;
		clk200Hz = 0;
	end
	else begin
	  	if(count == 100) begin // 100 cycles @ 100MHz = 1MHz
			clk1MHz = ~clk1MHz;
			count = 0;
		end
	  	if(ledmux == 20000) begin // 20000 cycles @ 100MHz = 5KHz
			clk5KHz = ~clk5KHz;
			ledmux = 0;
		end
	  	if(highspeed == 625) begin // 625 cycles @ 100MHz = 200Hz
			clk200Hz = ~clk200Hz;
			highspeed = 0;
		end
		count = count + 1;
		highspeed = highspeed + 1;
		ledmux = ledmux + 1;  
	end
end 

endmodule

module comparator_8bit (
