reg [2:0] stage;

assign gt = (stage == 3) ? (a_reg > b_reg) : 1'b0;
assign lt = (stage == 3) ? (a_reg < b_reg) : 1'b0;
assign eq = (stage == 3) ? (a_reg == b_reg) : 1'b0;

always @(posedge clk) begin
    case (stage)
        0: begin
            a_reg <= a;
            b_reg <= b;
            stage <= 1;
        end
        1: begin
            a_reg <= a_reg;
            b_reg <= b_reg;
            stage <= 2;
        end
        2: begin
            a_reg <= a_reg;
            b_reg <= b_reg;
            stage <= 3;
        end
        3: begin
            a_reg <= a_reg;
            b_reg <= b_reg;
            stage <= 0;
        end
    endcase
end

endmodule

