module Roulette (
    // Inputs
    input clock,
    input reset,
    input enable,
    input [31:0] x_RouletteMux,
    input [31:0] y_RouletteMux,
    input [31:0] z_RouletteMux,
    input [31:0] ux_RouletteMux,
    input [31:0] uy_RouletteMux,
    input [31:0] uz_RouletteMux,
    input [31:0] sz_RouletteMux,
    input [31:0] sr_RouletteMux,
    input [31:0] sleftz_RouletteMux,
    input [31:0] sleftr_RouletteMux,
    input [2:0] layer_RouletteMux,
    input [31:0] weight_absorber,
    input dead_RouletteMux,
    input [31:0] randnumber,
    // Outputs
    output [31:0] x_Roulette,
    output [31:0] y_Roulette,
    output [31:0] z_Roulette,
    output [31:0] ux_Roulette,
    output [31:0] uy_Roulette,
    output [31:0] uz_Roulette,
    output [31:0] sz_Roulette,
    output [31:0] sr_Roulette,
    output [31:0] sleftz_Roulette,
    output [31:0] sleftr_Roulette,
    output [2:0] layer_Roulette,
    output [31:0] weight_Roulette,
    output dead_Roulette
);

parameter BIT_WIDTH = 32;
parameter LAYER_WIDTH = 3;
parameter LEFTSHIFT = 3;
parameter INTCHANCE = 536870912;
parameter MIN_WEIGHT = 200;

reg dead_roulette;
reg [BIT_WIDTH-1:0] weight_roulette;
reg [31:0] randBits;

reg [BIT_WIDTH-1:0] x_Roulette;
reg [BIT_WIDTH-1:0] y_Roulette;
reg [BIT_WIDTH-1:0] z_Roulette;
reg [BIT_WIDTH-1:0] ux_Roulette;
reg [BIT_WIDTH-1:0] uy_Roulette;
reg [BIT_WIDTH-1:0] uz_Roulette;
reg [BIT_WIDTH-1:0] sz_Roulette;
reg [BIT_WIDTH-1:0] sr_Roulette;
reg [BIT_WIDTH-1:0] sleftz_Roulette;
reg [BIT_WIDTH-1:0] sleftr_Roulette;
reg [LAYER_WIDTH-1:0] layer_Roulette;
reg [BIT_WIDTH-1:0] weight_Roulette;
reg dead_Roulette;

always @ (reset or enable or weight_absorber or randBits or randnumber or dead_RouletteMux) begin
    if (reset) begin
        weight_roulette <= 0;
        dead_roulette <= 0;
        randBits <= 0;
    end else if (enable) begin
        randBits <= randnumber;
        if (weight_absorber < MIN_WEIGHT && !dead_RouletteMux) begin
            if (weight_absorber == {BIT_WIDTH{1'b0}}) begin
                dead_roulette <= 1;
                weight_roulette <= weight_absorber;
            end else if (randBits < INTCHANCE) begin
                dead_roulette <= 0;
                weight_roulette <= weight_absorber << LEFTSHIFT;
            end else begin
                dead_roulette <= 1;
                weight_roulette <= weight_absorber;
            end
        end else begin
            weight_roulette <= weight_absorber;
            dead_roulette <= 0;
        end
    end else begin
        randBits <= randnumber;
        weight_roulette <= weight_absorber;
        dead_roulette <= dead_RouletteMux;
    end
end

always @ (posedge clock) begin
    if (reset) begin
        x_Roulette <= 0;
        y_Roulette <= 0;
        z_Roulette <= 0;
        ux_Roulette <= 0;
        uy_Roulette <= 0;
        uz_Roulette <= 0;
        sz_Roulette <= 0;
        sr_Roulette <= 0;
        sleftz_Roulette <= 0;
        sleftr_Roulette <= 0;
        layer_Roulette <= 0;
        weight_Roulette <= 0;
        dead_Roulette <= 1'b1;
    end else if (enable) begin
        dead_Roulette <= dead_RouletteMux | dead_roulette;
        weight_Roulette <= weight_roulette;
        x_Roulette <= x_RouletteMux;
        y_Roulette <= y_RouletteMux;
        z_Roulette <= z_RouletteMux;
        ux_Roulette <= ux_RouletteMux;
        uy_Roulette <= uy_RouletteMux;
        uz_Roulette <= uz_RouletteMux;
        sz_Roulette <= sz_RouletteMux;
        sr_Roulette <= sr_RouletteMux;
        sleftz_Roulette <= sleftz_RouletteMux;
        sleftr_Roulette <= sleftr_RouletteMux;
        layer_Roulette <= layer_RouletteMux;
    end
end

endmodule

