always @(posedge clk) begin
    if (rst) begin
        counter <= 0;
        red <= 0;
        yellow <= 0;
        green <= 1;
    end else begin
        counter <= counter + 1;
        if (green && counter >= GREEN_TIME) begin
            green <= 0;
            yellow <= 1;
            counter <= 0;
        end else if (yellow && counter >= YELLOW_TIME) begin
            yellow <= 0;
            red <= 1;
            counter <= 0;
