    parameter a = 1664525;
    parameter c = 1013904223;
    parameter m = 2**32;

    // Internal state variables
    reg [31:0] x;
    reg [31:0] next_x;
    reg [31:0] count;

    // Initialization
    always @ (posedge clk) begin
        if (rst) begin
            x <= seed;
            count <= 0;
        end else if (start) begin
            x <= seed;
            count <= 0;
        end else begin
            x <= next_x;
            count <= count + 1;
        end
    end

