    always @ (posedge clk) begin
        if (start && count < 1000) begin
            next_x <= (a * x + c) % m;
            rand_num <= next_x;
        end else begin
            next_x <= x;
            rand_num <= 0;
            done <= 1;
        end
    end

endmodule

