module parity_calculator (
    input [7:0] in,
    output reg parity);

    reg [7:0] shift_reg;
    reg prev_bit;
    integer i;

    always @(*) begin
        shift_reg[0] = in[0];
        for (i = 1; i < 8; i = i + 1) begin
            shift_reg[i] = shift_reg[i-1];
        end
        prev_bit = shift_reg[0];
        parity = 1;
        for (i = 1; i < 8; i = i + 1) begin
            if (shift_reg[i] != prev_bit) begin
                parity = ~parity;
            end
            prev_bit = shift_reg[i];
        end
        if (parity == 1) begin
            parity = 0;
        end
        else begin
            parity = 1;
        end
    end

endmodule

