module booth_multiplier (
    input [15:0] A,
    input [15:0] B,
    input C,
    output reg [31:0] P
);

reg [15:0] a_reg, b_reg, b_neg;
reg [4:0] i;

always @(*) begin
    a_reg = (C == 1 && A[15] == 1) ? ~A + 1 : A;
    b_reg = (C == 1 && B[15] == 1) ? ~B + 1 : B;
    b_neg = ~b_reg + 1;
    P = 0;
    for (i = 0; i < 16; i = i + 1) begin
        if (B[0] == 1 && i == 0) begin
            P = P - a_reg;
        end else if (B[0] == 0 && i == 0) begin
            P = P + a_reg;
        end else begin
            if (B[0] == 1 && B[1] == 0) begin
                P = P - (a_reg << i);
            end else if (B[0] == 0 && B[1] == 1) begin
                P = P + (a_reg << i);
            end
        end
        B = {B[14:0], B[15]};
    end
