module full_adder(A, B, C, S, Cout);
  input A, B, C;
  output S, Cout;

  wire X1, X2, X3;

  //First XOR gate
  xor X1(A, B);

  //Second XOR gate
  xor X2(X1, C);

  //Third AND gate
  and X3(A, B, C);

  //Calculation of sum bit
  assign S = X2;

  //Calculation of carry-out bit
  assign Cout = X3 | (X1 & X2);

endmodule

