module ddr3_s4_amphy_mem_model_ram_module (
  // inputs:
  data,
  rdaddress,
  wraddress,
  wrclock,
  wren,

  // outputs:
  q
);

  parameter ARRAY_DEPTH = 2048;

  output  [ 15: 0] q;
  input   [ 15: 0] data;
  input   [ 24: 0] rdaddress;
  input   [ 24: 0] wraddress;
  input            wrclock;
  input            wren;

  wire    [ 15: 0] aq;
  reg     [ 41: 0] mem_array [2047: 0];
  wire    [ 15: 0] q;
  assign aq = mem_array[0][15:0];

  // Synthesis translate_off
  // Simulation-only contents
  reg [16 - 1:0] out;
  integer i;
  reg found_valid_data;
  reg data_written;

  initial begin
    for (i = 0; i < ARRAY_DEPTH; i = i + 1) begin
      mem_array[i][0] <= 1'b0;
    end
    data_written <= 1'b0;
  end

  always @(rdaddress) begin
    found_valid_data <= 1'b0;
    for (i = 0; i < ARRAY_DEPTH; i = i + 1) begin
      if (rdaddress == mem_array[i][42 - 1:42 - 25] && mem_array[i][0]) begin
        out = mem_array[i][42 - 25 - 1:42 - 25 - 16];
        found_valid_data = 1'b1;
      end
    end
    if (!found_valid_data) begin
      out = 16'dX;
    end
  end

  always @(posedge wrclock) begin
    if (wren) begin
      data_written <= 1'b0;
      for (i = 0; i < ARRAY_DEPTH; i = i + 1) begin
        if (wraddress == mem_array[i][42 - 1:42 - 25] && !data_written) begin
          mem_array[i][42 - 25 - 1:42 - 25 - 16] <= data;
          mem_array[i][0] <= 1'b1;
          data_written = 1'b1;
        end else if (!mem_array[i][0] && !data_written) begin
          mem_array[i] <= {wraddress,data,1'b1};
          data_written = 1'b1;
        end
      end
      if (!data_written) begin
        $write($time);
        $write(" --- Data could not be written, increase array depth or use full memory model --- ");
        $stop;
      end
    end
  end

  assign q = out;
  // Synthesis translate_on

endmodule

module Debounce_Circuit (
    input CLK_IN,
    input reset,
    input enb,
    input In,
    output reg Out
);

    wire [7:0] Debouce_Count_out1;
    wire Count_Up_Down_out1;

    assign Debouce_Count_out1 = 8'd25; // set debounce count to 25

    Count_Up_Down u_Count_Up_Down (
        .CLK_IN(CLK_IN),
        .reset(reset),
        .enb(enb),
        .u(In),
        .count_debounce(Debouce_Count_out1),
        .y(Count_Up_Down_out1)
    );

    always @(posedge CLK_IN) begin
        if (reset) begin
            Out <= 0;
        end else if (enb) begin
            if (Count_Up_Down_out1) begin
                Out <= 1;
            end else begin
                Out <= 0;
            end
        end
    end

endmodule

module signed_adder(
    input clk,
    input reset,
    input signed [3:0] a,
    input signed [3:0] b,
    output signed [3:0] sum,
    output overflow
);

    reg signed [3:0] temp_sum;
    reg temp_overflow;

    always @(posedge clk) begin
        if (reset) begin
            temp_sum <= 4'b0;
            temp_overflow <= 1'b0;
        end else begin
            temp_sum <= a + b;
            if ((a[3] == b[3]) && (a[3] != temp_sum[3]))
                temp_overflow <= 1'b1;
            else
                temp_overflow <= 1'b0;
        end
    end

    assign sum = temp_sum;
    assign overflow = temp_overflow;

endmodule

