module add_three(
    input [3:0] in,
    output [3:0] out
);

    wire [3:0] in_plus_one;
    wire [3:0] in_plus_two;
    wire [3:0] in_plus_three;

    // add 1 to the input
    full_adder fa1(.a(in[0]), .b(1'b1), .cin(1'b0), .sum(in_plus_one[0]), .cout(carry1));
    full_adder fa2(.a(in[1]), .b(carry1), .cin(1'b0), .sum(in_plus_one[1]), .cout(carry2));
    full_adder fa3(.a(in[2]), .b(carry2), .cin(1'b0), .sum(in_plus_one[2]), .cout(carry3));
    full_adder fa4(.a(in[3]), .b(carry3), .cin(1'b0), .sum(in_plus_one[3]), .cout(carry4));

    // add 2 to the input plus one
    full_adder fa5(.a(in_plus_one[0]), .b(1'b0), .cin(1'b1), .sum(in_plus_two[0]), .cout(carry5));
    full_adder fa6(.a(in_plus_one[1]), .b(carry5), .cin(1'b0), .sum(in_plus_two[1]), .cout(carry6));
    full_adder fa7(.a(in_plus_one[2]), .b(carry6), .cin(1'b0), .sum(in_plus_two[2]), .cout(carry7));
    full_adder fa8(.a(in_plus_one[3]), .b(carry7), .cin(1'b0), .sum(in_plus_two[3]), .cout(carry8));

    // add 3 to the input
    full_adder fa9(.a(in[0]), .b(1'b1), .cin(1'b1), .sum(in_plus_three[0]), .cout(carry9));
    full_adder fa10(.a(in[1]), .b(carry9), .cin(1'b0), .sum(in_plus_three[1]), .cout(carry10));
    full_adder fa11(.a(in[2]), .b(carry10), .cin(1'b0), .sum(in_plus_three[2]), .cout(carry11));
    full_adder fa12(.a(in[3]), .b(carry11), .cin(1'b0), .sum(in_plus_three[3]), .cout(carry12));

    // output in plus three
    assign out = in_plus_three;

