module fifo1(
    input clk_i,
    input rst_i,
    input [g_width-1:0] data_i,
    input push_i,
    input pull_i,
    output [g_width-1:0] data_o,
    output full_o,
    output empty_o
);

    parameter g_width = 32;

    reg [g_width-1:0] mem;
    reg full;
    reg empty;

    always @(posedge clk_i, negedge rst_i) begin
        if (!rst_i) begin
            mem <= 0;
            empty <= 1;
            full <= 0;
        end
        else begin
            if (push_i && !full) begin
                mem <= data_i;
                full <= 1;
                empty <= 0;
            end
            else if (pull_i && !empty) begin
                data_o <= mem;
                full <= 0;
                empty <= 1;
            end
        end
    end

    assign data_o = mem;
    assign full_o = full;
    assign empty_o = empty;

endmodule

module video_stream_splitter (
	input clk,
	input reset,
	input sync_ready,
	input [23:0] stream_in_data,
	input stream_in_startofpacket,
	input stream_in_endofpacket,
	input [1:0] stream_in_empty,
	input stream_in_valid,
	input stream_out_ready_0,
	input stream_out_ready_1,
	input stream_select,
	output reg sync_data,
	output reg sync_valid,
	output reg stream_in_ready,
	output reg [23:0] stream_out_data_0,
	output reg stream_out_startofpacket_0,
	output reg stream_out_endofpacket_0,
	output reg [1:0] stream_out_empty_0,
	output reg stream_out_valid_0,
	output reg [23:0] stream_out_data_1,
	output reg stream_out_startofpacket_1,
	output reg stream_out_endofpacket_1,
	output reg [1:0] stream_out_empty_1,
	output reg stream_out_valid_1
);

	// Internal wires and registers
	wire enable_setting_stream_select;
	reg between_frames;
	reg stream_select_reg;

	// Output registers
	always @(posedge clk) begin
		if (reset) begin
			sync_data <= 1'b0;
			sync_valid <= 1'b0;
		end
		else if (enable_setting_stream_select) begin
			sync_data <= stream_select;
			sync_valid <= 1'b1;
		end
		else if (sync_ready) begin
			sync_valid <= 1'b0;
		end
	end

	always @(posedge clk) begin
		if (reset) begin
			stream_out_data_0 <= 'h0;
			stream_out_startofpacket_0 <= 1'b0;
			stream_out_endofpacket_0 <= 1'b0;
			stream_out_empty_0 <= 'h0;
			stream_out_valid_0 <= 1'b0;
		end
		else if (stream_in_ready & ~stream_select_reg) begin
			stream_out_data_0 <= stream_in_data;
			stream_out_startofpacket_0 <= stream_in_startofpacket;
			stream_out_endofpacket_0 <= stream_in_endofpacket;
			stream_out_empty_0 <= stream_in_empty;
			stream_out_valid_0 <= stream_in_valid;
		end
		else if (stream_out_ready_0) begin
			stream_out_valid_0 <= 1'b0;
		end
	end

	always @(posedge clk) begin
		if (reset) begin
			stream_out_data_1 <= 'h0;
			stream_out_startofpacket_1 <= 1'b0;
			stream_out_endofpacket_1 <= 1'b0;
			stream_out_empty_1 <= 'h0;
			stream_out_valid_1 <= 1'b0;
		end
		else if (stream_in_ready & stream_select_reg) begin
			stream_out_data_1 <= stream_in_data;
			stream_out_startofpacket_1 <= stream_in_startofpacket;
			stream_out_endofpacket_1 <= stream_in_endofpacket;
			stream_out_empty_1 <= stream_in_empty;
			stream_out_valid_1 <= stream_in_valid;
		end
		else if (stream_out_ready_1) begin
			stream_out_valid_1 <= 1'b0;
		end
	end

	// Internal registers
	always @(posedge clk) begin
		if (reset) begin
			between_frames <= 1'b1;
		end
		else if (stream_in_ready & stream_in_endofpacket) begin
			between_frames <= 1'b1;
		end
		else if (stream_in_ready & stream_in_startofpacket) begin
			between_frames <= 1'b0;
		end
	end

	always @(posedge clk) begin
		if (reset) begin
			stream_select_reg <= 1'b0;
		end
		else if (enable_setting_stream_select) begin
			stream_select_reg <= stream_select;
		end
	end

	// Output assignments
	assign stream_in_ready = (stream_select_reg) ?
		stream_in_valid & (~stream_out_valid_1 | stream_out_ready_1) :
		stream_in_valid & (~stream_out_valid_0 | stream_out_ready_0);

	// Internal assignments
	assign enable_setting_stream_select =
		(stream_in_ready & stream_in_endofpacket) |
		(~(stream_in_ready & stream_in_startofpacket) & between_frames);

endmodule

module axi_data_fifo_v2_1_7_axic_srl_fifo #
  (
   parameter         C_FAMILY   = "none", // FPGA Family
   parameter integer C_FIFO_WIDTH  = 1, // Width of S_MESG/M_MESG.
   parameter integer C_MAX_CTRL_FANOUT = 33, // Maximum number of mesg bits
                                             // the control logic can be used
                                             // on before the control logic
                                             // needs to be replicated.
   parameter integer C_FIFO_DEPTH_LOG =  2,  // Depth of FIFO is 2**C_FIFO_DEPTH_LOG.  
                                             // The minimum size fifo generated is 4-deep.
   parameter         C_USE_FULL =  1         // Prevent overwrite by throttling S_READY.                                              
   )
  (
   input  wire                        ACLK,    // Clock
   input  wire                        ARESET,  // Reset
   input  wire [C_FIFO_WIDTH-1:0]     S_MESG,  // Input data
   input  wire                        S_VALID, // Input data valid
   output wire                        S_READY, // Input data ready
   output wire [C_FIFO_WIDTH-1:0]     M_MESG,  // Output data
   output wire                        M_VALID, // Output data valid
   input  wire                        M_READY  // Output data ready
   );

  localparam P_FIFO_DEPTH_LOG = (C_FIFO_DEPTH_LOG>1) ? C_FIFO_DEPTH_LOG : 2;
  localparam P_EMPTY       = {P_FIFO_DEPTH_LOG{1'b1}};
  localparam P_ALMOSTEMPTY = {P_FIFO_DEPTH_LOG{1'b0}};
  localparam P_ALMOSTFULL_TEMP  = {P_EMPTY, 1'b0};
  localparam P_ALMOSTFULL  = P_ALMOSTFULL_TEMP[0+:P_FIFO_DEPTH_LOG];
  localparam P_NUM_REPS    = (((C_FIFO_WIDTH+1)%C_MAX_CTRL_FANOUT) == 0) ?
                             (C_FIFO_WIDTH+1)/C_MAX_CTRL_FANOUT :
                             ((C_FIFO_WIDTH+1)/C_MAX_CTRL_FANOUT)+1;

  (* syn_keep = "1" *) reg [P_NUM_REPS*P_FIFO_DEPTH_LOG-1:0]  fifoaddr;
  (* syn_keep = "1" *) wire [P_NUM_REPS*P_FIFO_DEPTH_LOG-1:0] fifoaddr_i;

  genvar i;
  genvar j;

  reg  M_VALID_i;
  reg  S_READY_i;
  wire push;     // FIFO push
  wire pop;      // FIFO pop
  reg  areset_d1; // Reset delay register
  wire [C_FIFO_WIDTH-1:0] m_axi_mesg_i; // Intermediate SRL data

  assign M_VALID = M_VALID_i;
  assign S_READY = C_USE_FULL ? S_READY_i : 1'b1;
  assign M_MESG = m_axi_mesg_i;
  assign push = S_VALID & (C_USE_FULL ? S_READY_i : 1'b1);
  assign pop  = M_VALID_i & M_READY;

  always @(posedge ACLK) begin
    areset_d1 <= ARESET;
  end

  generate
    //---------------------------------------------------------------------------
    // Create count of number of elements in FIFOs
    //---------------------------------------------------------------------------
    for (i=0;i<P_NUM_REPS;i=i+1) begin : gen_rep
      assign fifoaddr_i[P_FIFO_DEPTH_LOG*(i+1)-1:P_FIFO_DEPTH_LOG*i] = 
         push ? fifoaddr[P_FIFO_DEPTH_LOG*(i+1)-1:P_FIFO_DEPTH_LOG*i] + 1 :
                fifoaddr[P_FIFO_DEPTH_LOG*(i+1)-1:P_FIFO_DEPTH_LOG*i] - 1;
      always @(posedge ACLK) begin
        if (ARESET)
          fifoaddr[P_FIFO_DEPTH_LOG*(i+1)-1:P_FIFO_DEPTH_LOG*i] <= 
                {P_FIFO_DEPTH_LOG{1'b1}};
        else if (push ^ pop)
          fifoaddr[P_FIFO_DEPTH_LOG*(i+1)-1:P_FIFO_DEPTH_LOG*i] <= 
                fifoaddr_i[P_FIFO_DEPTH_LOG*(i+1)-1:P_FIFO_DEPTH_LOG*i];
      end
    end

    //---------------------------------------------------------------------------
    // When FIFO is empty, reset master valid bit.  When not empty set valid bit.
    // When FIFO is full,  reset slave  ready bit.  When not full  set ready bit.
    //---------------------------------------------------------------------------

    always @(posedge ACLK) begin
      if (ARESET) begin
        M_VALID_i <= 1'b0;
      end else if ((fifoaddr[P_FIFO_DEPTH_LOG*P_NUM_REPS-1:P_FIFO_DEPTH_LOG*(P_NUM_REPS-1)] == 
                               P_ALMOSTEMPTY) && pop && ~push) begin
        M_VALID_i <= 1'b0;
      end else if (push) begin
        M_VALID_i <= 1'b1;
      end
    end

    always @(posedge ACLK) begin
      if (ARESET) begin
        S_READY_i <= 1'b0;
      end else if (areset_d1) begin
        S_READY_i <= 1'b1;
      end else if (C_USE_FULL && 
        ((fifoaddr[P_FIFO_DEPTH_LOG*P_NUM_REPS-1:P_FIFO_DEPTH_LOG*(P_NUM_REPS-1)] == 
         P_ALMOSTFULL) && push && ~pop)) begin
        S_READY_i <= 1'b0;
      end else if (C_USE_FULL && pop) begin
        S_READY_i <= 1'b1;
      end
    end

    //---------------------------------------------------------------------------
    // Instantiate SRLs
    //---------------------------------------------------------------------------
    for (i=0;i<(C_FIFO_WIDTH/C_MAX_CTRL_FANOUT)+((C_FIFO_WIDTH%C_MAX_CTRL_FANOUT)>0);i=i+1) begin : gen_srls
      for (j=0;((j<C_MAX_CTRL_FANOUT)&&(i*C_MAX_CTRL_FANOUT+j<C_FIFO_WIDTH));j=j+1) begin : gen_rep
        axi_data_fifo_v2_1_7_ndeep_srl #
          (
           .C_FAMILY  (C_FAMILY),
           .C_A_WIDTH (P_FIFO_DEPTH_LOG)
          )
          srl_nx1
          (
           .CLK (ACLK),
           .A   (fifoaddr[P_FIFO_DEPTH_LOG*(i+1)-1:
                          P_FIFO_DEPTH_LOG*(i)]),
           .CE  (push),
           .D   (S_MESG[i*C_MAX_CTRL_FANOUT+j]),
           .Q   (m_axi_mesg_i[i*C_MAX_CTRL_FANOUT+j])
          );
      end
    end      
  endgenerate

endmodule

