module top_module (
    input clk,
    input reset,
    input [31:0] in1,
    input [31:0] in2,
    input [31:0] mux_in1,
    input [31:0] mux_in2,
    input [1:0] select,
    output reg out
);

reg comp1_out;
reg comp2_out;
reg mux_out;

comparator comp1(
    .a(in1),
    .b(in2),
    .out(comp1_out)
);

comparator comp2(
    .a(mux_in1),
    .b(mux_in2),
    .out(comp2_out)
);

mux2to1 mux(
    .a(mux_in1),
    .b(mux_in2),
    .sel(select),
    .out(mux_out)
);

and2 and(
    .a(comp1_out),
    .b(comp2_out),
    .out(out_and)
);

always @(posedge clk) begin
    if (reset) begin
        out <= 0;
    end else begin
        if ((comp1_out != comp2_out && select == 2'b00) || (comp1_out == comp2_out && select == 2'b01)) begin
            out <= 1;
        end else begin
            out <= 0;
        end
    end
end

endmodule

module top_module ( 
    input wire [3:0] in,
    input clk,
    input reset,
    input [7:0] instruction,
    output reg [31:0] regfile1 [15:0],
    output reg [31:0] regfile2 [15:0],
    output wire out );

    // 2's complement module
    wire [3:0] twos_comp;
    assign twos_comp = ~in + 1;

    // 4-to-1 multiplexer
    wire [3:0] mux_out;
    assign mux_out = instruction[7] ? twos_comp : in;

    // Pipeline stages
    reg [7:0] fetched_inst;
    reg [3:0] decoded_op1, decoded_op2;
    reg [31:0] regfile1_temp [15:0], regfile2_temp [15:0];
    reg [31:0] alu_out1, alu_out2;
    reg [31:0] final_out;

    always @(posedge clk) begin
        if (reset) begin
            fetched_inst <= 8'b0;
            decoded_op1 <= 4'b0;
            decoded_op2 <= 4'b0;
            regfile1_temp <= 16'd0;
            regfile2_temp <= 16'd0;
            alu_out1 <= 32'd0;
            alu_out2 <= 32'd0;
            final_out <= 32'd0;
        end else begin
            fetched_inst <= instruction;
            decoded_op1 <= regfile1[fetched_inst[5:1]];
            decoded_op2 <= regfile2[fetched_inst[5:1]];
            regfile1_temp <= regfile1;
            regfile2_temp <= regfile2;
            alu_out1 <= decoded_op1 & mux_out;
            alu_out2 <= decoded_op2 & mux_out;
            final_out <= alu_out1 | alu_out2;
        end
    end

    // Register file write
    always @(posedge clk) begin
        if (reset) begin
            regfile1[0] <= 32'd0;
            regfile2[0] <= 32'd0;
        end else begin
            if (fetched_inst[0]) begin
                regfile1_temp[fetched_inst[4:1]] <= alu_out1;
            end
            if (fetched_inst[0]) begin
                regfile2_temp[fetched_inst[4:1]] <= alu_out2;
            end
            regfile1 <= regfile1_temp;
            regfile2 <= regfile2_temp;
        end
    end

    // Output
    assign out = final_out;

endmodule

module adpcm #(
    parameter dw=16
) (
    input               rst_n,
    input               clk,    // CPU clock
    input               cen,
    input               start,  // strobe
    input      [dw-1:0] a,
    input      [dw-1:0] b,
    output reg [dw-1:0] d,
    output reg [dw-1:0] r,
    output              working
);

reg  [dw-1:0] cycle;
assign working = cycle[0];

wire [dw:0] sub = { r[dw-2:0], d[dw-1] } - b;

always @(posedge clk or negedge rst_n)
    if( !rst_n ) begin
        cycle <= 'd0;
    end else if(cen) begin
        if( start ) begin
            cycle <= ~16'd0;
            r     <=  16'd0;
            d     <= a;
        end else if(cycle[0]) begin
            cycle <= { 1'b0, cycle[dw-1:1] };
            if( sub[dw] == 0 ) begin
                r <= sub[dw-1:0];
                d <= { d[dw-2:0], 1'b1};
            end else begin
                r <= { r[dw-2:0], d[dw-1] };
                d <= { d[dw-2:0], 1'b0 };
            end
        end
    end

endmodule

module mem_encrypt_decrypt (
  input [n-1:0] data_in,
  input [k-1:0] key_in,
  input mode,
  output [n-1:0] data_out
);

parameter n = 16; // number of bits in the data signal
parameter k = 8; // number of bits in the key signal

function [n-1:0] encrypt;
  input [n-1:0] data;
  input [k-1:0] key;
  begin
    encrypt = data ^ key;
  end
endfunction

function [n-1:0] decrypt;
  input [n-1:0] data;
  input [k-1:0] key;
  begin
    decrypt = data ^ key;
  end
endfunction

assign data_out = (mode == 0) ? encrypt(data_in, key_in) : decrypt(data_in, key_in);

endmodule

module fifo(
  rst,
  wr_clk,
  rd_clk,
  din,
  wr_en,
  rd_en,
  dout,
  full,
  almost_full,
  empty,
  almost_empty,
  rd_data_count,
  wr_data_count
);

input rst;
input wr_clk;
input rd_clk;
input [127:0] din;
input wr_en;
input rd_en;
output [127:0] dout;
output full;
output almost_full;
output empty;
output almost_empty;
output [3:0] rd_data_count;
output [3:0] wr_data_count;

reg [127:0] fifo[0:31];
reg [4:0] wr_ptr = 0;
reg [4:0] rd_ptr = 0;
reg [4:0] data_count = 0;

reg full_reg = 0;
reg almost_full_reg = 0;
reg empty_reg = 1;
reg almost_empty_reg = 1;

parameter ALMOST_FULL_THRESH = 28;
parameter ALMOST_EMPTY_THRESH = 4;

always @(posedge wr_clk or posedge rst) begin
  if (rst) begin
    wr_ptr <= 0;
    full_reg <= 0;
    almost_full_reg <= 0;
    empty_reg <= 1;
    almost_empty_reg <= 1;
    data_count <= 0;
  end else if (wr_en && !full_reg) begin
    fifo[wr_ptr] <= din;
    wr_ptr <= (wr_ptr == 31) ? 0 : wr_ptr + 1;
    data_count <= data_count + 1;
  end

  if (data_count == 32) begin
    full_reg <= 1;
    almost_full_reg <= 1;
    empty_reg <= 0;
    almost_empty_reg <= 0;
  end else if (data_count >= ALMOST_FULL_THRESH) begin
    almost_full_reg <= 1;
  end else if (data_count <= ALMOST_EMPTY_THRESH) begin
    almost_empty_reg <= 1;
  end else begin
    full_reg <= 0;
    almost_full_reg <= 0;
    empty_reg <= 0;
    almost_empty_reg <= 0;
  end
end

always @(posedge rd_clk or posedge rst) begin
  if (rst) begin
    rd_ptr <= 0;
  end else if (rd_en && !empty_reg) begin
    dout <= fifo[rd_ptr];
    rd_ptr <= (rd_ptr == 31) ? 0 : rd_ptr + 1;
    data_count <= data_count - 1;
  end

  if (data_count == 0) begin
    full_reg <= 0;
    almost_full_reg <= 0;
    empty_reg <= 1;
    almost_empty_reg <= 1;
  end else if (data_count >= ALMOST_FULL_THRESH) begin
    almost_full_reg <= 1;
  end else if (data_count <= ALMOST_EMPTY_THRESH) begin
    almost_empty_reg <= 1;
  end else begin
    full_reg <= 0;
    almost_full_reg <= 0;
    empty_reg <= 0;
    almost_empty_reg <= 0;
  end
end

assign full = full_reg;
assign almost_full = almost_full_reg;
assign empty = empty_reg;
assign almost_empty = almost_empty_reg;
assign rd_data_count = data_count;
assign wr_data_count = 32 - data_count;

endmodule

module LED_Driver (
  input clk,
  input rst,
  input [1:0] color_sel,
  input [7:0] brightness,
  output [n-1:0] LED
);

parameter n = 8; // number of LEDs
parameter f_clk = 50e6; // clock frequency
parameter f_pwm = 1e3; // PWM frequency

reg [7:0] pwm_count;
reg [7:0] pwm_duty_cycle;

reg [1:0] color;
reg [n-1:0] led_state;

always @(posedge clk) begin
  if (rst) begin
    pwm_count <= 0;
    pwm_duty_cycle <= 0;
    color <= 0;
    led_state <= 0;
  end else begin
    pwm_count <= pwm_count + 1;
    if (pwm_count == 0) begin
      pwm_duty_cycle <= brightness;
    end else if (pwm_count == pwm_duty_cycle) begin
      pwm_duty_cycle <= 0;
    end
  end
end

always @(posedge clk) begin
  if (rst) begin
    color <= 0;
  end else begin
    case (color_sel)
      2'b00: color <= 2'b11; // red
      2'b01: color <= 2'b10; // green
      2'b10: color <= 2'b01; // blue
      2'b11: color <= 2'b00; // white
    endcase
  end
end

always @(posedge clk) begin
  if (rst) begin
    led_state <= 0;
  end else begin
    for (i = 0; i < n; i = i + 1) begin
      if (color[i]) begin
        led_state[i] <= pwm_count < pwm_duty_cycle;
      end else begin
        led_state[i] <= 0;
      end
    end
  end
end

assign LED = led_state;

endmodule

