module Schmitt_trigger (
  input in,
  output reg out
);

parameter VL = 1; // low threshold value
parameter VH = 3; // high threshold value
parameter hysteresis = 1; // hysteresis value

reg prev_out; // previous output state

always @(in) begin
  if (in > VH) begin
    out = 1;
  end else if (in < VL) begin
    out = 0;
  end else if (in > (prev_out + hysteresis)) begin
    out = 1;
  end else if (in < (prev_out - hysteresis)) begin
    out = 0;
  end
  prev_out = out;
end

endmodule

module adder(
  input [7:0] A,
  input [7:0] B,
  output [15:0] sum
);

  wire [8:0] eightbit_sum; // intermediate signal for 8-bit addition
  wire msb_A; // most significant bit of A
  wire lsb_B; // least significant bit of B

  // instantiate components
  eightbit_adder eightbit_adder_inst(.A(A), .B(B), .sum(eightbit_sum));
  msb_extractor msb_A_inst(.in(A), .out(msb_A));
  lsb_extractor lsb_B_inst(.in(B), .out(lsb_B));

  // connect output
  assign sum = {lsb_B, eightbit_sum[7:0], msb_A};

endmodule

module eightbit_adder(
