        input wire [2:0] s00_axi_arprot,
        input wire s00_axi_arvalid,
        output wire s00_axi_arready,
        output wire [C_S00_AXI_DATA_WIDTH-1:0] s00_axi_rdata,
        output wire [1:0] s00_axi_rresp,
        output wire s00_axi_rvalid,
        input wire s00_axi_rready,
        input wire m00_axis_aclk,
        input wire m00_axis_aresetn,
        output wire m00_axis_tvalid,
        output wire [C_M00_AXIS_TDATA_WIDTH-1:0] m00_axis_tdata,
        output wire m00_axis_tlast,
        input wire m00_axis_tready
    );

    reg [C_S00_AXI_DATA_WIDTH-1:0] id_reg = 0;
    reg [C_S00_AXI_DATA_WIDTH-1:0] numOfSlv_reg = 0;
    reg [C_S00_AXI_DATA_WIDTH-1:0] data_reg;
    reg last_reg;
    wire En;
    wire Finish;

    assign En = s00_axi_wvalid;
    assign Finish = last_reg && m00_axis_tready;

    always @(posedge s00_axi_aclk) begin
        if (!s00_axi_aresetn) begin
            id_reg <= 0;
            numOfSlv_reg <= 0;
            last_reg <= 0;
            data_reg <= 0;
        end
        else begin
            if (s00_axi_awvalid && s00_axi_awready) begin
                case (s00_axi_awaddr)
                    0: begin
                        numOfSlv_reg <= s00_axi_wdata;
                    end
                    default: begin
                        // do nothing
                    end
                endcase
            end

            if (s00_axi_wvalid && s00_axi_wready) begin
                data_reg <= s00_axi_wdata;
                last_reg <= s00_axi_wstrb[(C_S00_AXI_DATA_WIDTH/8)-1];
                if (last_reg) begin
                    numOfSlv_reg <= numOfSlv_reg + 1;
                end
            end

            if (m00_axis_tready && En) begin
                m00_axis_tvalid <= 1;
                m00_axis_tdata <= {numOfSlv_reg, id_reg, data_reg};
                m00_axis_tlast <= last_reg;
                id_reg <= id_reg + 1;
            end
            else begin
                m00_axis_tvalid <= 0;
            end
        end
    end

    assign s00_axi_awready = 1;
    assign s00_axi_wready = 1;
    assign s00_axi_bresp = 0;
    assign s00_axi_bvalid = 0;
    assign s00_axi_arready = 1;
    assign s00_axi_rdata = 0;
    assign s00_axi_rresp = 0;
    assign s00_axi_rvalid = 0;

    assign m00_axis_tdata[(C_M00_AXIS_TDATA_WIDTH-1):(C_S00_AXI_DATA_WIDTH+1)] = 0;

