module emesh_rdalign (
   // Outputs
   data_out,
   // Inputs
   addr, datamode, data_in
);

   //Inputs
   input [2:0] addr;
   input [1:0] datamode;
   input [63:0] data_in;

   //Outputs
   output [63:0] data_out;

   //wires
   wire [3:0] byte0_sel;
   wire [31:0] data_mux;
   wire [31:0] data_aligned;
   wire byte1_sel1;
   wire byte1_sel0;
   wire byte2_en;
   wire byte3_en;

   //Shift down high word
   assign data_mux[31:0] = addr[2] ? data_in[63:32] : data_in[31:0];

   //Byte0
   assign byte0_sel[3] = addr[1:0] == 2'b11;
   assign byte0_sel[2] = addr[1:0] == 2'b10;
   assign byte0_sel[1] = addr[1:0] == 2'b01;
   assign byte0_sel[0] = addr[1:0] == 2'b00;

   //Byte1
   assign byte1_sel1 = datamode[1:0] == 2'b01 & addr[1:0] == 2'b10;
   assign byte1_sel0 = (datamode[1:0] == 2'b01 & addr[1:0] == 2'b00) |
                       datamode[1:0] == 2'b10 |
                       datamode[1:0] == 2'b11;

   //Byte2
   assign byte2_en = datamode[1:0] == 2'b10 |
                     datamode[1:0] == 2'b11;

   //Byte3
   assign byte3_en = datamode[1:0] == 2'b10 |
                     datamode[1:0] == 2'b11;

   //B0: 32 NANDs,8 NORS
   assign data_aligned[7:0] = {(8){byte0_sel[3]}} & data_mux[31:24] |
                             {(8){byte0_sel[2]}} & data_mux[23:16] |
                             {(8){byte0_sel[1]}} & data_mux[15:8] |
                             {(8){byte0_sel[0]}} & data_mux[7:0];

   //B1:
   assign data_aligned[15:8] = {(8){byte1_sel1}} & data_mux[31:24] |
                              {(8){byte1_sel0}} & data_mux[15:8];

   //B2: 8 NANDS
   assign data_aligned[23:16] = {(8){byte2_en}} & data_mux[23:16];

   //B3:
   assign data_aligned[31:24] = {(8){byte3_en}} & data_mux[31:24];

   //lower 32 bits
   assign data_out[31:0] = data_aligned[31:0];

   //Upper 32 bits are pass through
   assign data_out[63:32] = data_in[63:32];

endmodule

module uart_state_machine (
  input clk,
  input rst,
  input rx,
  input start,
  input stop,
  output reg tx,
  output reg ready
);

  // Define the states of the state machine
  parameter IDLE = 2'b00;
  parameter START = 2'b01;
  parameter DATA = 2'b10;
  parameter PARITY = 2'b11;
  parameter STOP = 2'b100;

  // Define the current state and next state variables
  reg [2:0] state, next_state;

  // Define the data and parity bit variables
  reg [7:0] data_byte;
  reg parity_bit;

  // Define the count variable for sampling the data bits
  reg [2:0] count;

  // Synchronize the state machine with the system clock
  always @(posedge clk) begin
    if (rst) begin
      state <= IDLE;
      next_state <= IDLE;
      tx <= 1'b1;
      ready <= 1'b0;
      data_byte <= 8'b0;
      parity_bit <= 1'b0;
      count <= 3'b0;
    end else begin
      state <= next_state;
    end
  end

  // Define the state transitions and output signals based on the UART protocol
  always @(*) begin
    case (state)
      IDLE: begin
        if (start) begin
          next_state = START;
          count <= 3'b0;
        end else begin
          next_state = IDLE;
        end
        tx <= 1'b1;
        ready <= 1'b0;
      end
      START: begin
        next_state = DATA;
        tx <= 1'b0;
        ready <= 1'b0;
      end
      DATA: begin
        if (count < 3) begin
          data_byte[count] <= rx;
          count <= count + 1;
          next_state = DATA;
        end else if (parity_bit) begin
          next_state = PARITY;
          count <= 3'b0;
        end else begin
          next_state = STOP;
          count <= 3'b0;
        end
        tx <= 1'b0;
        ready <= 1'b0;
      end
      PARITY: begin
        parity_bit <= rx;
        next_state = STOP;
        count <= 3'b0;
        tx <= 1'b0;
        ready <= 1'b0;
      end
      STOP: begin
        if (rx == stop) begin
          next_state = IDLE;
          tx <= 1'b1;
          ready <= 1'b1;
        end else begin
          next_state = STOP;
          tx <= 1'b0;
          ready <= 1'b0;
        end
      end
      default: begin
        next_state = IDLE;
        tx <= 1'b1;
        ready <= 1'b0;
      end
    endcase
  end

endmodule

module mux_4to1 (
  input [3:0] in,
  input [1:0] sel,
  output reg out
);

always @(*) begin
  case(sel)
    2'b00: out = in[0];
    2'b01: out = in[1];
    2'b10: out = in[2];
    2'b11: out = in[3];
  endcase
end

endmodule

module chatgpt_generate_edge_detect(
  input               clk,
  input               rst_n,
  input               a,
  output reg          rise,
  output reg          down
);

  reg a_d1;
  reg a_d2;

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      a_d1 <= 1'b0;
      a_d2 <= 1'b0;
      rise <= 1'b0;
      down <= 1'b0;
    end
    else begin
      a_d2 <= a_d1;
      a_d1 <= a;
      rise <= (a_d1 ^ a_d2) & a_d1;
      down <= (a_d1 ^ a_d2) & ~a_d1;
    end
  end

endmodule

module binary_to_bcd_converter (
