        16'h0011: begin bcd_output_high = 4'b0000; bcd_output_low = 4'b0011; end
        16'h0100: begin bcd_output_high = 4'b0000; bcd_output_low = 4'b0100; end
        16'h0101: begin bcd_output_high = 4'b0000; bcd_output_low = 4'b0101; end
        16'h0110: begin bcd_output_high = 4'b0000; bcd_output_low = 4'b0110; end
        16'h0111: begin bcd_output_high = 4'b0000; bcd_output_low = 4'b0111; end
        16'h1000: begin bcd_output_high = 4'b0001; bcd_output_low = 4'b0000; end
        16'h1001: begin bcd_output_high = 4'b0001; bcd_output_low = 4'b0001; end
        16'h1010: begin bcd_output_high = 4'b0001; bcd_output_low = 4'b0010; end
        16'h1011: begin bcd_output_high = 4'b0001; bcd_output_low = 4'b0011; end
        16'h1100: begin bcd_output_high = 4'b0001; bcd_output_low = 4'b0100; end
        16'h1101: begin bcd_output_high = 4'b0001; bcd_output_low = 4'b0101; end
        16'h1110: begin bcd_output_high = 4'b0001; bcd_output_low = 4'b0110; end
