        16'h10001: begin bcd_output_high = 4'b0010; bcd_output_low = 4'b0001; end
        16'h10010: begin bcd_output_high = 4'b0010; bcd_output_low = 4'b0010; end
        16'h10011: begin bcd_output_high = 4'b0010; bcd_output_low = 4'b0011; end
        16'h10100: begin bcd_output_high = 4'b0010; bcd_output_low = 4'b0100; end
        16'h10101: begin bcd_output_high = 4'b0010; bcd_output_low = 4'b0101; end
