        16'h10111: begin bcd_output_high = 4'b0010; bcd_output_low = 4'b0111; end
        16'h11000: begin bcd_output_high = 4'b0011; bcd_output_low = 4'b0000; end
        16'h11001: begin bcd_output_high = 4'b0011; bcd_output_low = 4'b0001; end
        16'h11010: begin bcd_output_high = 4'b0011; bcd_output_low = 4'b0010; end
        16'h11011: begin bcd_output_high = 4'b0011; bcd_output_low = 4'b0011; end
        16'h11100: begin bcd_output_high = 4'b0011; bcd_output_low = 4'b0100; end
        16'h11101: begin bcd_output_high = 4'b0011; bcd_output_low = 4'b0101; end
        16'h11110: begin bcd_output_high = 4'b0011; bcd_output_low = 4'b0110; end
        16'h11111: begin bcd_output_high = 4'b0011; bcd_output_low = 4'b0111; end
        default: begin bcd_output_high = 4'b0000; bcd_output_low = 4'b0000; end
