);

always @(*) begin
    case({bcd_input_1, bcd_input_2})
        8'b00000000: bcd_sum = 4'b0000;
        8'b00000001: bcd_sum = 4'b0001;
        8'b00000010: bcd_sum = 4'b0010;
        8'b00000011: bcd_sum = 4'b0011;
        8'b00000100: bcd_sum = 4'b0100;
        8'b00000101: bcd_sum = 4'b0101;
        8'b00000110: bcd_sum = 4'b0110;
        8'b00000111: bcd_sum = 4'b0111;
        8'b00001000: bcd_sum = 4'b1000;
        8'b00001001: bcd_sum = 4'b1001;
        8'b00001010: bcd_sum = 4'b1010;
        8'b00001011: bcd_sum = 4'b1011;
        8'b00001100: bcd_sum = 4'b1100;
        8'b00001101: bcd_sum = 4'b1101;
        8'b00001110: bcd_sum = 4'b1110;
        8'b00001111: bcd_sum = 4'b1111;
        default: bcd_sum = 4'b0000;
    endcase
end

