module top_module (
    input [15:0] A,
    input [3:0] S,
    input C,
    output reg [3:0] B,
    output reg [3:0] C,
    output reg [3:0] BCD_sum
);

reg [15:0] shifted_input;
wire [3:0] bcd_high, bcd_low;

binary_to_bcd_converter bcd_converter(
    .binary_input(shifted_input),
    .bcd_output_high(bcd_high),
    .bcd_output_low(bcd_low)
);

bcd_adder bcd_adder_inst(
    .bcd_input_1(bcd_high),
    .bcd_input_2(bcd_low),
    .bcd_sum(BCD_sum)
);

always @(posedge C) begin
    if(S > 0) begin
        shifted_input <= A << S;
    end else begin
        shifted_input <= A;
    end
end

