assign C = bcd_low;

endmodule

module calculator(a, b, op, sum, difference, product, quotient);

    input [15:0] a, b;
    input [1:0] op;
    output reg [15:0] sum, difference, product, quotient;

    always @ (a or b or op) begin
        case (op)
            2'b00: begin // addition
                sum = a + b;
                difference = 16'b0;
                product = 16'b0;
                quotient = 16'b0;
            end
            2'b01: begin // subtraction
                sum = 16'b0;
                difference = a - b;
                product = 16'b0;
                quotient = 16'b0;
            end
            2'b10: begin // multiplication
                sum = 16'b0;
                difference = 16'b0;
                product = a * b;
                quotient = 16'b0;
            end
            2'b11: begin // division
                sum = 16'b0;
                difference = 16'b0;
                product = 16'b0;
                quotient = a / b;
            end
        endcase
    end

endmodule

module restoring_divider (
    input [7:0] dividend,
    input [7:0] divisor,
    output reg [7:0] quotient
);

reg [7:0] remainder;
reg [7:0] temp_dividend;
reg [7:0] temp_divisor;
reg [3:0] i;

always @(*) begin
    quotient = 8'b0;
    remainder = dividend;
    temp_dividend = dividend;
    temp_divisor = divisor;

    for(i = 0; i < 8; i = i + 1) begin
        if(remainder[7] == 1) begin
            quotient[i] = 0;
            remainder = remainder + temp_divisor;
        end
        else begin
            quotient[i] = 1;
            remainder = remainder - temp_divisor;
        end
        temp_divisor = temp_divisor >> 1;
    end
end

endmodule

module twos_complement (
    input [3:0] bin,
    output reg [3:0] comp
);

always @(*) begin
    comp = ~bin + 4'b1;
end

endmodule

module top_module (
    input [7:0] a,
    input [7:0] b,
    input [3:0] bin,
    output [7:0] out_div,
    output [3:0] out_comp
);

restoring_divider div(a, b, out_div);
twos_complement comp(bin, out_comp);

assign final_output = out_div + out_comp;

endmodule

module sky130_fd_sc_hdll__dlrtp_1 (
