    output reg EN,
    output reg [2:1] OUT1,
    output reg [3:0] OUT2
);

always @(*) begin
    casez(I)
        8'b00000001: begin EN = 1; OUT2 = 4'b0001; OUT1 = 2'b00; end
        8'b00000010: begin EN = 1; OUT2 = 4'b0010; OUT1 = 2'b00; end
        8'b00000100: begin EN = 1; OUT2 = 4'b0100; OUT1 = 2'b00; end
        8'b00001000: begin EN = 1; OUT2 = 4'b1000; OUT1 = 2'b00; end
        8'b00010000: begin EN = 1; OUT2 = 4'b0000; OUT1 = 2'b01; end
        8'b00100000: begin EN = 1; OUT2 = 4'b0000; OUT1 = 2'b10; end
        8'b01000000: begin EN = 1; OUT2 = 4'b0000; OUT1 = 2'b11; end
        8'b10000000: begin EN = 1; OUT2 = 4'b0000; OUT1 = 2'b00; end
