module shift_register (
    input clk,
    input load,
    input [3:0] data,
    output reg [3:0] out
);

always @(posedge clk) begin
    if (load) begin
        out <= data;
    end else begin
        out <= {out[2:0], 1'b0};
    end
end

endmodule

module final_module (
    input clk,
    input reset,
    input [7:0] I,
    input load,
    output reg [11:0] final_output
);

reg [3:0] shift_register_output;
reg [2:1] priority_encoder_output1;
reg [3:0] priority_encoder_output2;
wire EN;
wire [2:1] OUT1;
wire [3:0] OUT2;

priority_encoder pe(
    .I(I),
    .EN(EN),
    .OUT1(OUT1),
    .OUT2(OUT2)
);

shift_register sr(
    .clk(clk),
    .load(load),
    .data(OUT2),
    .out(shift_register_output)
);

always @(posedge clk) begin
    if (reset) begin
        final_output <= 12'b0;
    end else begin
        if (EN) begin
            priority_encoder_output1 <= OUT1;
            priority_encoder_output2 <= OUT2;
        end
        final_output <= {priority_encoder_output2, priority_encoder_output1, shift_register_output};
    end
end

endmodule

module priority_encoder_4bit (
    input [3:0] I,
    output valid,
    output reg [1:0] encoded_value
);

reg [3:0] stage1_I;
reg [2:0] stage2_I;
reg [1:0] stage3_I;

assign valid = |I;

always @ (posedge clk) begin
    stage1_I <= I;
end

always @ (posedge clk) begin
    stage2_I[2] <= stage1_I[3] | stage1_I[2];
    stage2_I[1] <= stage1_I[1] | stage1_I[0];
    stage2_I[0] <= stage1_I[2] | stage1_I[1] | stage1_I[0];
end

always @ (posedge clk) begin
    stage3_I[1] <= stage2_I[2] | stage2_I[1];
    stage3_I[0] <= stage2_I[0];
end

always @ (posedge clk) begin
    if (stage3_I[1]) begin
        encoded_value <= 2'b10;
    end else if (stage3_I[0]) begin
        encoded_value <= 2'b01;
    end else begin
        encoded_value <= 2'b00;
    end
end

endmodule

module my_module (
    Q,
    CLK,
    D,
    SCD,
    SCE,
    RESET_B
);

    output Q;
    input CLK;
    input D;
    input SCD;
    input SCE;
    input RESET_B;

    reg Q;

    always @(posedge CLK) begin
        if (RESET_B == 1'b1) begin
            Q <= 1'b0;
        end else if (SCD == 1'b1) begin
            Q <= D;
        end else if (SCE == 1'b0) begin
            Q <= Q;
        end else begin
            Q <= D;
        end
    end

endmodule

module top_module (
    input clk,
    input rst_n,
    input [255:0] in,
    input [7:0] sel,
    output [15:0] out
);

    reg [63:0] shift_reg;
    reg [7:0] shift_cnt;
    wire [255:0] mux_out;
    wire [7:0] mux_sel;
    wire [15:0] comb_out;

    // 256-to-1 multiplexer using barrel shifter and 4-to-1 multiplexer
    barrel_shifter bs (
        .in(in),
        .out(mux_out),
        .sel(mux_sel)
    );

    mux_4to1 mux (
        .in0(mux_out[63:48]),
        .in1(mux_out[47:32]),
        .in2(mux_out[31:16]),
        .in3(mux_out[15:0]),
        .sel(sel[1:0]),
        .out(comb_out[15:0])
    );

    // 64-bit shift register
    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            shift_reg <= 64'h0000000000000000;
            shift_cnt <= 8'h00;
        end else begin
            shift_cnt <= shift_cnt + 1;
            case (shift_cnt)
                8'h01: shift_reg <= 64'h8000000000000000;
                8'h02: shift_reg <= 64'hC000000000000000;
                8'h03: shift_reg <= 64'hE000000000000000;
                8'h04: shift_reg <= 64'hF000000000000000;
                8'h05: shift_reg <= 64'hF800000000000000;
                8'h06: shift_reg <= 64'hFC00000000000000;
                8'h07: shift_reg <= 64'hFE00000000000000;
                8'h08: shift_reg <= 64'hFF00000000000000;
                8'h09: shift_reg <= 64'hFF80000000000000;
                8'h0A: shift_reg <= 64'h7F80000000000000;
                8'h0B: shift_reg <= 64'h3FC0000000000000;
                8'h0C: shift_reg <= 64'h1FE0000000000000;
                8'h0D: shift_reg <= 64'h0FF0000000000000;
                8'h0E: shift_reg <= 64'h07F8000000000000;
                8'h0F: shift_reg <= 64'h03FC000000000000;
                8'h10: shift_reg <= 64'h01FE000000000000;
                8'h11: shift_reg <= 64'h00FF000000000000;
                8'h12: shift_reg <= 64'h0007F80000000000;
                8'h13: shift_reg <= 64'h0003FC0000000000;
                8'h14: shift_reg <= 64'h0001FE0000000000;
                8'h15: shift_reg <= 64'h0000FF0000000000;
                8'h16: shift_reg <= 64'h00007F8000000000;
                8'h17: shift_reg <= 64'h00003FC000000000;
                8'h18: shift_reg <= 64'h00001FE000000000;
                8'h19: shift_reg <= 64'h00000FF000000000;
                8'h1A: shift_reg <= 64'h000007F800000000;
                8'h1B: shift_reg <= 64'h000003FC00000000;
                8'h1C: shift_reg <= 64'h000001FE00000000;
                8'h1D: shift_reg <= 64'h000000FF00000000;
                8'h1E: shift_reg <= 64'h0000007F80000000;
                8'h1F: shift_reg <= 64'h0000003FC0000000;
                8'h20: shift_reg <= 64'h0000001FE0000000;
                default: shift_reg <= 64'h0000000000000000;
            endcase
        end
    end

    // Combinational logic block
    assign mux_sel = shift_reg[7:0];
    assign out = comb_out ^ shift_reg[15:0];

endmodule

module barrel_shifter (
    input [255:0] in,
    output [255:0] out,
    input [7:0] sel
);

    wire [255:0] shifted;

    // Barrel shifter
    always @(*) begin
        case (sel[3:2])
            2'b00: shifted = in;
            2'b01: shifted = {in[255:1], 1'b0};
            2'b10: shifted = {in[254:0], 2'b00};
            2'b11: shifted = {in[252:0], 3'b000};
        endcase
    end

    // 4-to-1 multiplexer
    mux_4to1 mux (
        .in0(shifted[63:48]),
        .in1(shifted[47:32]),
        .in2(shifted[31:16]),
        .in3(shifted[15:0]),
        .sel(sel[1:0]),
        .out(out[15:0])
    );

endmodule

module mux_4to1 (
    input [15:0] in0,
    input [15:0] in1,
    input [15:0] in2,
    input [15:0] in3,
    input [1:0] sel,
    output [15:0] out
);

    assign out = (sel == 2'b00) ? in0 :
                 (sel == 2'b01) ? in1 :
                 (sel == 2'b10) ? in2 :
                                  in3;

endmodule

module simple_calculator(
    input [7:0] a,
    input [7:0] b,
    input [1:0] op,
    output reg [7:0] out
);

always @(*) begin
    case(op)
        2'b00: out = a + b;
        2'b01: out = a - b;
        2'b10: out = a & b;
        2'b11: out = a | b;
    endcase
end

always @(posedge clk) begin
    out <= out;
end

endmodule

module uart (
  input clk,
  input reset_n,
  input begintransfer,
  input chipselect,
  input read_n,
  input write_n,
  input [7:0] writedata,
  output dataavailable,
  output irq,
  output [7:0] readdata,
  output readyfordata,
  output reg txd
);

  // Baud rate generator
  reg [15:0] baud_divisor;
  always @ (posedge clk or negedge reset_n) begin
    if (!reset_n) begin
      baud_divisor <= 0;
    end else begin
      baud_divisor <= 625;
    end
  end

  // Transmit shift register
  reg [7:0] tx_data;
  reg tx_shift_empty;
  reg tx_ready;
  reg tx_overrun;
  reg tx_wr_strobe;
  always @ (posedge clk or negedge reset_n) begin
    if (!reset_n) begin
      tx_data <= 0;
      tx_shift_empty <= 1;
      tx_ready <= 1;
      tx_overrun <= 0;
      tx_wr_strobe <= 0;
    end else begin
      if (begintransfer && chipselect && write_n) begin
        tx_data <= writedata;
        tx_shift_empty <= 0;
        tx_ready <= 0;
        tx_overrun <= 0;
        tx_wr_strobe <= 1;
      end else if (!tx_shift_empty) begin
        tx_shift_empty <= 1;
        tx_ready <= 1;
      end
    end
  end

  // Receive shift register
  reg [7:0] rx_data;
  reg rx_char_ready;
  reg rx_overrun;
  reg rx_rd_strobe;
  always @ (posedge clk or negedge reset_n) begin
    if (!reset_n) begin
      rx_data <= 0;
      rx_char_ready <= 0;
      rx_overrun <= 0;
      rx_rd_strobe <= 0;
    end else begin
      if (begintransfer && chipselect && read_n) begin
        rx_char_ready <= 0;
        rx_rd_strobe <= 1;
      end else if (rx_char_ready && !rx_rd_strobe) begin
        rx_char_ready <= 0;
        rx_rd_strobe <= 0;
      end
      if (!rx_char_ready && !rx_overrun && rxd) begin
        rx_data <= rxd;
        rx_char_ready <= 1;
        rx_overrun <= 0;
      end else if (rx_char_ready) begin
        rx_overrun <= 1;
      end
    end
  end

  // Control block
  reg do_force_break;
  reg framing_error;
  reg parity_error;
  reg status_wr_strobe;
  reg [1:0] status_reg;
  reg dataavailable;
  reg irq;
  reg readyfordata;
  always @ (posedge clk or negedge reset_n) begin
    if (!reset_n) begin
      do_force_break <= 0;
      framing_error <= 0;
      parity_error <= 0;
      status_wr_strobe <= 0;
      status_reg <= 0;
      dataavailable <= 0;
      irq <= 0;
      readyfordata <= 0;
    end else begin
      if (begintransfer && chipselect && write_n) begin
        case (address)
          2'b00: begin // Control register
            if (writedata[0]) begin
              do_force_break <= 1;
            end else begin
              do_force_break <= 0;
            end
          end
          2'b01: begin // Status register
            status_wr_strobe <= 1;
            status_reg[0] <= 0;
            status_reg[1] <= 0;
            status_reg[2] <= tx_ready;
            status_reg[3] <= rx_char_ready;
            status_reg[4] <= 0;
            status_reg[5] <= 0;
            status_reg[6] <= 0;
            status_reg[7] <= 0;
          end
          2'b10: begin // Baud rate divisor register
            baud_divisor <= writedata;
          end
        endcase
      end
      if (tx_shift_empty && !tx_ready) begin
        tx_ready <= 1;
      end
      if (rx_char_ready) begin
        dataavailable <= 1;
        irq <= 1;
      end
      if (tx_shift_empty && tx_ready && !do_force_break) begin
        txd <= 1;
      end else begin
        txd <= 0;
      end
      if (!tx_shift_empty && tx_ready) begin
        tx_data <= {1'b0, tx_data[7:1]};
        tx_ready <= 0;
      end
      if (dataavailable && !readyfordata) begin
        readyfordata <= 1;
      end else if (!dataavailable && readyfordata) begin
        readyfordata <= 0;
      end
      if (rx_char_ready && rx_rd_strobe) begin
        readdata <= rx_data;
        rx_char_ready <= 0;
        rx_rd_strobe <= 0;
      end
    end
  end

endmodule

module bridge (
    input [7:0] RGA,
    input [0:0] RGB,
    input [7:0] OPT,
    input [1:0] KEY,
    output [7:0] RGZ
);

reg [7:0] shift_reg;
reg [7:0] not_reg;
reg [7:0] zero_reg;

always @ (posedge CLK) begin
    if (RST) begin
        shift_reg <= 8'b0;
        not_reg <= 8'b0;
        zero_reg <= 8'b0;
    end else begin
        if (ENA) begin
            case ({OPT, KEY})
                8'b0000000100: shift_reg <= {RGA[6:0], 1'b0};
                8'b0000000000: shift_reg <= {1'b0, RGA[7:1]};
                8'b0000000101: shift_reg <= {RGA[5:0], 2'b00};
                8'b0000000001: shift_reg <= {2'b00, RGA[7:2]};
                8'b0000000110: not_reg <= ~RGA;
                8'b0000000010: zero_reg <= 8'b0;
                default: shift_reg <= RGA;
            endcase
        end
    end
end

assign RGZ = RGB ? not_reg : (KEY == 2'b10 ? zero_reg : shift_reg);

endmodule

module register_module (
  input clk,
  output reg [3:0] A,
  output reg [3:0] B,
  output reg [3:0] C
);

  initial begin
    A = 0;
    B = 0;
    C = 0;
  end

  always @(posedge clk) begin
    fork
      begin : increment_A
        forever #2 A = A + 1;
      end
      begin : decrement_B
        forever #3 B = B - 1;
      end
    join
  end

  always @(A or B) begin
    C = A + B;
  end

endmodule

module mcu(clk, clr, OP, PCWriteCond, PCWrite, IorD, MemRead, MemWrite, MemtoReg, IRWrite, PCSource, ALUOp, ALUSrcB, ALUSrcA, RegWrite, RegDst);
input clk, clr;
input [5:0] OP;
output PCWriteCond, PCWrite, IorD, MemRead, MemWrite, MemtoReg, IRWrite, ALUSrcA, RegWrite, RegDst;
reg PCWriteCond, PCWrite, IorD, MemRead, MemWrite, MemtoReg, IRWrite, ALUSrcA, RegWrite, RegDst;
output [1:0] PCSource, ALUOp, ALUSrcB;
reg [1:0] PCSource, ALUOp, ALUSrcB;

integer current_state;
integer next_state;

always @(current_state)
begin
	case(current_state)
	0: // Fetch
	begin
		IorD		= 0;
		MemRead		= 1;
		MemWrite	= 0;
		IRWrite		= 1;
		ALUSrcA		= 0;
		ALUSrcB		= 2'b01;
		ALUOp		= 2'b00;
		PCWrite		= 1;
		PCWriteCond	= 0;
		RegWrite	= 0;
		MemtoReg	= 0;
		RegDst		= 0;

		#3;
		PCSource	= 2'b00;

	end

	1: // Decode
		begin	
			ALUSrcA	= 0;
			ALUSrcB	= 2'b11;
			ALUOp	= 2'b00;

			IRWrite	= 0;
			MemRead	= 0;

			PCWrite	= #1 0;
		end

	2: // Execute Load/Store
		begin
			ALUSrcA	= 1;
			ALUSrcB	= 2'b10;
			ALUOp	= 2'b00;
		end

	3: // Memory Read
		begin
			IorD	= 1;
			MemRead	= 1;
		end

	4: // Memory Read Complete
		begin
			MemtoReg	= 1;
			RegDst		= 0;
			RegWrite	= 1;
			MemRead		= 0;
		end

	5: // Memory Write
		begin
			IorD		= 1;
			MemWrite	= 1;
		end

	6: // Execute Branch
	begin
		ALUSrcA	= 1;
		ALUSrcB	= 2'b00;
		ALUOp	= 2'b10;
	end

	7: // Write Register
	begin
		RegDst		= 1;
		RegWrite	= 1;
		MemtoReg	= 0;
	end

	8: // Execute Branch Complete
	begin
		ALUSrcA		= 1;
		ALUSrcB		= 2'b00;
		ALUOp		= 2'b01;
		PCSource	= 2'b01;
		PCWriteCond	= 1;
	end

	9: // Jump
	begin
		PCSource	= 2'b10;
		PCWrite		= 1;
	end

	endcase
end

always @(posedge clk)
begin
	if (clr	== 1'b1)
		current_state	= -1;
	else
		current_state	= next_state;
end

always @(current_state or OP)
begin
	next_state	= -1;
	case (current_state)
	-1: next_state	= 0;

	0: next_state	= 1;

	1:
	begin
	case (OP)
	6'b100011: next_state	= 2; // lw
	6'b101011: next_state	= 2; // sw
	0:			next_state	= 6; // beq
	4:			next_state	= 8; // bne
	2:			next_state	= 9; // j
	endcase
	end

	2:
	begin
	case (OP)
	6'b100011: next_state	= 3; // memory read
	6'b101011: next_state	= 5; // memory write
	endcase
	end

	3: next_state	= 4; // memory read complete
	4: next_state	= 0; // fetch
	5: next_state	= 0; // fetch
	6: next_state	= 7; // write register
	7: next_state	= 0; // fetch
	8: next_state	= 0; // fetch
	9: next_state	= 0; // fetch

	default:
		next_state	= -1;
	endcase

end

endmodule

module add_sub_pipeline(
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] sum
);

    wire [15:0] a_lsb;
    wire [15:0] b_lsb;
    wire [15:0] sum_lsb;
    wire carry_out;

    // Instantiate 16-bit adder module twice
    adder16bit adder1(.a(a[15:0]), .b(b[15:0]), .carry_in(1'b0), .sum(sum_lsb[15:0]), .carry_out(carry_out));
    adder16bit adder2(.a(a[31:16]), .b(b[31:16]), .carry_in(carry_out), .sum(sum_lsb[31:16]), .carry_out());

    // XOR gate to invert b input when sub is 1
    assign b_lsb = sub ? ~b[15:0] : b[15:0];

    // XOR gate to invert b input when sub is 1
    assign b_msb = sub ? ~b[31:16] : b[31:16];

    // Generate 32-bit output that is the result of the addition or subtraction
    assign sum = {sum_lsb, carry_out} + (sub ? {~b_msb, ~b_lsb} + 1'b1 : {b_msb, b_lsb});

endmodule

module adder16bit(
    input [15:0] a,
    input [15:0] b,
    input carry_in,
    output [15:0] sum,
    output carry_out
);

    wire [15:0] sum_temp;

    // Full adder for LSB
    full_adder fa1(.a(a[0]), .b(b[0]), .carry_in(carry_in), .sum(sum_temp[0]), .carry_out(carry_out1));

    // Full adder for bits 1-14
    genvar i;
    generate
        for (i = 1; i < 15; i = i + 1) begin : gen_fa
            full_adder fa(.a(a[i]), .b(b[i]), .carry_in(carry_out[i-1]), .sum(sum_temp[i]), .carry_out(carry_out[i]));
        end
    endgenerate

    // Full adder for MSB
    full_adder fa2(.a(a[15]), .b(b[15]), .carry_in(carry_out[14]), .sum(sum_temp[15]), .carry_out(carry_out));

    assign sum = sum_temp;

endmodule

module full_adder(
    input a,
    input b,
    input carry_in,
    output sum,
    output carry_out
);

    assign {carry_out, sum} = a + b + carry_in;

endmodule

module comparator(
    input [3:0] A,
    input [3:0] B,
    output reg EQ,
    output reg GT,
    output reg LT
);

always @(*) begin
    if(A == B) begin
        EQ = 1;
        GT = 0;
        LT = 0;
    end else if(A > B) begin
        EQ = 0;
        GT = 1;
        LT = 0;
    end else begin
        EQ = 0;
        GT = 0;
        LT = 1;
    end
end

endmodule

