module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    input CIN,
    output reg [3:0] Q,
    output COUT
);

    reg [3:0] sum;
    reg [3:0] carry;

    always @* begin
        sum = A + B + CIN;
        carry = (A[3] & B[3]) | (A[3] & CIN) | (B[3] & CIN);
    end

    assign Q = sum;
    assign COUT = carry;

endmodule

module mux_4to1_enable (
    input [3:0] IN0,
    input [3:0] IN1,
    input [3:0] IN2,
    input [3:0] IN3,
    input [1:0] SEL,
    input EN,
    output reg [3:0] OUT
);

    always @* begin
        case (SEL)
            2'b00: OUT = EN ? IN0 : 4'bZZZZ;
            2'b01: OUT = EN ? IN1 : 4'bZZZZ;
            2'b10: OUT = EN ? IN2 : 4'bZZZZ;
            2'b11: OUT = EN ? IN3 : 4'bZZZZ;
        endcase
    end

endmodule

module functional_module (
    input [3:0] A,
    input [3:0] B,
    input CIN,
    input [3:0] IN,
    input [1:0] SEL,
    input EN,
    output reg [3:0] Q,
    output COUT,
    output reg out
);

    wire [3:0] mux_out;
    wire [3:0] adder_out;
    wire carry_out;

    ripple_carry_adder adder_inst (
        .A(A),
        .B(B),
        .CIN(CIN),
        .Q(adder_out),
        .COUT(carry_out)
    );

    mux_4to1_enable mux_inst (
        .IN0(IN[3:0]),
        .IN1(IN[7:4]),
        .IN2(IN[11:8]),
        .IN3(IN[15:12]),
        .SEL(SEL),
        .EN(EN),
        .OUT(mux_out)
    );

    always @* begin
        if (EN) begin
            Q = adder_out + mux_out;
            out = 1'b0;
        end else begin
            Q = adder_out;
            out = 1'b1;
        end
    end

    assign COUT = carry_out;

endmodule

