module sram_top (
  wb_clk_i, wb_rst_i,

  wb_dat_i, wb_dat_o, wb_adr_i, wb_sel_i, wb_we_i, wb_cyc_i,
  wb_stb_i, wb_ack_o, wb_err_o,

  r_cen, r0_wen, r1_wen, r_oen, r_a, r_d_i, r_d_o, d_oe,
  l_cen, l0_wen, l1_wen, l_oen, l_a, l_d_i, l_d_o
);

//
// Parameters
//
parameter aw = 19;

//
// I/O Ports
//
input wb_clk_i;
input wb_rst_i;

//
// WB slave i/f
//
input [31:0] wb_dat_i;
output [31:0] wb_dat_o;
input [31:0] wb_adr_i;
input [3:0] wb_sel_i;
input wb_we_i;
input wb_cyc_i;
input wb_stb_i;
output wb_ack_o;
output wb_err_o;

//
// Right SRAM bank
//
output r_oen;
output r0_wen;
output r1_wen;
output r_cen;
input [15:0] r_d_i;
output [15:0] r_d_o;
output [aw-1:0] r_a;

//
// Left SRAM bank
//
output l_oen;
output l0_wen;
output l1_wen;
output l_cen;
input [7:0] l_d_i;
output [7:0] l_d_o;
output [aw-1:0] l_a;

//
// Common SRAM signals
//
output d_oe;

//
// Internal wires and regs
//
reg [7:0] mem [2097151:0];
integer i;
wire [31:0] adr;
wire wb_err;

//
// Aliases and simple assignments
//
assign wb_err = wb_cyc_i & wb_stb_i & (wb_adr_i > 20'h1FFFFF);     // If Access to > 2MB
assign adr = {8'h00, wb_adr_i[23:2], 2'b00};

//
// Reading from SRAM model
//
assign wb_dat_o[7:0] = l_d_o;
assign wb_dat_o[15:8] = r_d_o[15:8];
assign wb_dat_o[23:16] = r_d_o[7:0];
assign wb_dat_o[31:24] = mem[adr+0];

//
// Writing to SRAM model
//
always @(posedge wb_rst_i or posedge wb_clk_i)
        if (wb_cyc_i & wb_stb_i & wb_we_i) begin
                if (wb_sel_i[0])
                        mem[adr+0] <= #1 wb_dat_i[7:0];
                if (wb_sel_i[1])
                        r_d_i[15:8] <= #1 wb_dat_i[15:8];
                if (wb_sel_i[2])
                        r_d_i[7:0] <= #1 wb_dat_i[23:16];
                if (wb_sel_i[3])
                        l_d_i <= #1 wb_dat_i[7:0];
        end

//
// SRAM bank write enables
//
assign r0_wen = wb_cyc_i & wb_stb_i & wb_we_i & wb_sel_i[1];
assign r1_wen = wb_cyc_i & wb_stb_i & wb_we_i & wb_sel_i[2];
assign l0_wen = wb_cyc_i & wb_stb_i & wb_we_i & wb_sel_i[0];
assign l1_wen = 1'b0;

//
// SRAM bank output enables
//
assign r_oen = ~wb_cyc_i | ~wb_stb_i;
assign l_oen = ~wb_cyc_i | ~wb_stb_i;

//
// SRAM bank chip enables
//
assign r_cen = wb_cyc_i & wb_stb_i & (wb_adr_i[23] == 1'b0);
assign l_cen = wb_cyc_i & wb_stb_i & (wb_adr_i[23] == 1'b1);

//
// SRAM bank data output
//
always @(*)
        if (wb_cyc_i & wb_stb_i)
                if (wb_adr_i[23] == 1'b0)
                        r_d_o <= {16{r_d_i[15]}};
                else
                        l_d_o <= r_d_i[7:0];

//
// SRAM bank address output
//
assign r_a = wb_adr_i[18:2];
assign l_a = wb_adr_i[18:2];

//
// Common data output enable
//
assign d_oe = wb_cyc_i & wb_stb_i;

//
// WB Acknowledge
//
assign wb_ack_o = wb_cyc_i & wb_stb_i & ~wb_err;

//
// WB Error
//
assign wb_err_o = wb_err;

endmodule

