module fifo #
(
  parameter DATA_WIDTH = 8
)
(
  input clk,
  input rst,
  input enable,
  input flush,
  input [DATA_WIDTH-1:0] data_in,
  input push,
  output [DATA_WIDTH-1:0] data_out,
  output full,
  output empty,
  input pop
);

  // FIFO depth
  parameter DEPTH = 16;

  // FIFO memory
  reg [DATA_WIDTH-1:0] memory [0:DEPTH-1];

  // FIFO pointers
  reg [4:0] write_pointer = 0;
  reg [4:0] read_pointer = 0;

  // Flags
  reg [4:0] count = 0;
  wire [4:0] next_count = count + push - pop;
  wire [4:0] next_write_pointer = write_pointer + push;
  wire [4:0] next_read_pointer = read_pointer + pop;

  // Outputs
  assign full = (count == DEPTH);
  assign empty = (count == 0);
  assign data_out = memory[read_pointer];

  // Write operation
  always @(posedge clk) begin
    if (rst) begin
      write_pointer <= 0;
      count <= 0;
    end else if (enable) begin
      if (flush) begin
        write_pointer <= 0;
        count <= 0;
      end else if (next_count <= DEPTH) begin
        write_pointer <= next_write_pointer;
        memory[write_pointer] <= data_in;
        count <= next_count;
      end
    end
  end

  // Read operation
  always @(posedge clk) begin
    if (rst) begin
      read_pointer <= 0;
    end else if (enable) begin
      if (flush) begin
        read_pointer <= 0;
      end else if (!full && next_count > 0 && !is_transmitting) begin
        read_pointer <= next_read_pointer;
        count <= next_count;
      end
    end
  end

  // Transmit operation
  reg is_transmitting = 0;
  always @(posedge clk) begin
    if (rst) begin
      is_transmitting <= 0;
    end else if (enable) begin
      if (flush) begin
        is_transmitting <= 0;
      end else if (!empty) begin
        is_transmitting <= 1;
      end else begin
        is_transmitting <= 0;
      end
    end
  end

endmodule

