module multiplier (
  input [n-1:0] A,
  input [n-1:0] B,
  input ctrl,
  output reg [2*n-1:0] P
);

parameter n = 4; // number of bits

reg [2*n-1:0] product;
reg signed [n-1:0] signed_A;
reg signed [n-1:0] signed_B;
reg signed [2*n-1:0] signed_product;

always @(*) begin
  if (ctrl == 0) begin // unsigned multiplication
    product = {n{1'b0}}; // initialize product to 0
    for (i = 0; i < n; i = i + 1) begin
      if (B[i] == 1'b1) begin
        product = product + (A << i);
      end
    end
    P = product;
  end
  else begin // signed multiplication
    signed_A = $signed(A);
    signed_B = $signed(B);
    signed_product = signed_A * signed_B;
    P = {signed_product[n-1], signed_product};
  end
end

endmodule

module watchdog_timer (
  input clk,
  input rst,
  input [31:0] timeout,
  output wdt
);

  reg [31:0] counter;
  reg wdt_reg;

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      counter <= 0;
      wdt_reg <= 0;
    end else begin
      counter <= counter + 1;
      if (counter == timeout) begin
        wdt_reg <= 1;
      end else begin
        wdt_reg <= 0;
      end
    end
  end

  assign wdt = wdt_reg;

endmodule

module memory_controller (
    input clk_i,
    input rst_i,
    input enable_i,
    input write_i,
    input [31:0] addr_i,
    output reg ack_o,
    input [255:0] data_i,
    output [255:0] data_o
);

// Memory module instantiation
Data_Memory memory_inst (
    .clk_i(clk_i),
    .rst_i(rst_i),
    .addr_i(addr_i),
    .data_i(data_i),
    .enable_i(enable_i),
    .write_i(write_i),
    .ack_o(ack_o),
    .data_o(data_o)
);

// Controller module logic
reg [1:0] state;
reg [3:0] count;
reg ok;
reg [255:0] data;

parameter STATE_IDLE = 2'b00;
parameter STATE_WAIT = 2'b01;
parameter STATE_ACK = 2'b10;
parameter STATE_FINISH = 2'b11;

always @(posedge clk_i or negedge rst_i) begin
    if (~rst_i) begin
        state <= STATE_IDLE;
        count <= 4'b0;
        ok <= 1'b0;
        ack_o <= 1'b0;
    end
    else begin
        case (state)
            STATE_IDLE: begin
                if (enable_i) begin
                    count <= count + 4'b1;
                    state <= STATE_WAIT;
                end else begin
                    state <= STATE_IDLE;
                end
            end
            STATE_WAIT: begin
                if (count == 4'd6) begin
                    ok <= 1'b1;
                    state <= STATE_ACK;
                end else begin
                    count <= count + 4'b1;
                    state <= STATE_WAIT;
                end
            end
            STATE_ACK: begin
                ack_o <= 1'b1;
                state <= STATE_FINISH;
            end
            STATE_FINISH: begin
                ack_o <= 1'b0;
                ok <= 1'b0;
                state <= STATE_IDLE;
            end
        endcase
    end
end

always @(posedge clk_i) begin
    if (ok && !write_i) begin
        data <= data_o;
    end
end

always @(posedge clk_i) begin
    if (ok && write_i) begin
        data <= data_i;
    end
end

endmodule

module bitwise_sel (A, B, sel, Y);

parameter WIDTH = 8;

input [WIDTH-1:0] A;
input [WIDTH-1:0] B;
input sel;
output [WIDTH-1:0] Y;

genvar i;
generate
    for (i = 0; i < WIDTH; i = i + 1) begin:V
        if (sel == 0) begin
            assign Y[i] = A[i] & B[i];
        end else begin
            assign Y[i] = A[i] | B[i];
        end
    end
endgenerate

endmodule

module div_mod_u (
    input [WIDTH-1:0] A,
    input [WIDTH-1:0] B,
    output [WIDTH-1:0] Y,
    output [WIDTH-1:0] R
);
    (* force_downto *)
    wire [WIDTH*WIDTH-1:0] chaindata;
    assign R = chaindata[WIDTH*WIDTH-1:WIDTH*(WIDTH-1)];

    genvar i;
    generate
        for (i = 0; i < WIDTH; i=i+1) begin:stage
            (* force_downto *)
            wire [WIDTH-1:0] stage_in;

            if (i == 0) begin:cp
                assign stage_in = A;
            end else begin:cp
                assign stage_in = chaindata[i*WIDTH-1:(i-1)*WIDTH];
            end

            assign Y[WIDTH-(i+1)] = stage_in >= {B, {WIDTH-(i+1){1'b0}}};
            assign chaindata[(i+1)*WIDTH-1:i*WIDTH] = Y[WIDTH-(i+1)] ? stage_in - {B, {WIDTH-(i+1){1'b0}}} : stage_in;
        end
    endgenerate
endmodule

module tri_state_buffer(
    input in,
    input enable,
    output out
);

wire out_internal;
assign out = enable ? out_internal : 1'bz;

wire in_not;
assign in_not = ~in;

wire enable_not;
assign enable_not = ~enable;

wire out_internal_1;
assign out_internal_1 = in_not & enable_not;

wire out_internal_2;
assign out_internal_2 = out_internal_1 | out_internal;

assign out_internal = enable ? in : out_internal_2;

endmodule

