module xnor_gate(
    input a,
    input b,
    output out_xnor
);
    wire nand1, nand2, nand3, nand4;
    assign nand1 = ~(a & b);
    assign nand2 = ~(a & nand1);
    assign nand3 = ~(b & nand1);
    assign nand4 = ~(nand2 & nand3);
    assign out_xnor = nand4;
endmodule

module top_module( 
    input [2:0] a,
    input [2:0] b,
    input select,
    output [2:0] out_or_bitwise,
    output out_or_logical,
    output out_xnor,
    output [5:0] out_not
);
    bitwise_or_logical_or bitwise_or_logical_or_inst(
        .a(a),
        .b(b),
        .out_bitwise(out_or_bitwise),
        .out_logical(out_or_logical)
    );

    xnor_gate xnor_gate_inst(
        .a(a[0]),
        .b(b[0]),
        .out_xnor(out_xnor)
    );

    genvar i;
    generate
        for (i = 1; i < 3; i = i + 1) begin : xnor_generate
            xnor_gate xnor_gate_inst(
                .a(a[i]),
                .b(b[i]),
                .out_xnor(out_xnor[i])
            );
        end
    endgenerate

    assign out_not[2:0] = ~a;
    assign out_not[5:3] = ~b;

    always @(*) begin
        if (select == 1'b0) begin
            out_or_bitwise = out_or_bitwise;
            out_or_logical = out_or_logical;
        end else begin
            out_or_bitwise = out_xnor;
            out_or_logical = ~out_xnor;
        end
    end
endmodule

