module fifo (
    input clk,
    input rst,
    input we,
    input din,
    output reg re,
    output reg [31:0] dout
);

    parameter WIDTH = 32;
    parameter DEPTH = 8;

    reg [WIDTH-1:0] mem [0:DEPTH-1];
    reg [2:0] head = 3'b0;
    reg [2:0] tail = 3'b0;
    reg full = 1'b0;
    reg empty = 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            head <= 3'b0;
            tail <= 3'b0;
            full <= 1'b0;
            empty <= 1'b1;
        end else begin
            if (we && !full) begin
                mem[head] <= din;
                head <= head + 1;
                if (head == tail) begin
                    full <= 1'b1;
                end
                empty <= 1'b0;
            end

            if (re && !empty) begin
                dout <= mem[tail];
                tail <= tail + 1;
                if (tail == head) begin
                    empty <= 1'b1;
                end
                full <= 1'b0;
            end
        end
    end

endmodule

module cameraReader
(

    input clk,
    input reset_n,

    output refclk,

    input pclk,
    input [7:0] data,
    input vsync,
    input hsync,

    output reg [15:0] data_out,
    output wire wrreq,
    output wire wrclk

);

reg wrclk1 = 0;

always@(negedge clk)
wrclk1 <= ~wrclk1;

reg [19:0] pixel_counter;
reg [9:0] wait_counter_hs;
reg [19:0] wait_counter_vs;

reg [1:0] state = 0;

assign wrclk = clk;

assign wrreq = state == 2'b01 ? wrclk1 : 1'b0;

assign data_out = {8'd0, data};

always@(posedge wrclk1)
begin
    if(reset_n == 1'b0)
    begin
        pixel_counter <= 0;
        wait_counter_vs <= 0;
        wait_counter_hs <= 0;
    end
    else
    begin
        case(state)
        2'b00:
        begin
            if(vsync == 1'b0 && hsync == 1'b0)
            begin
                wait_counter_vs <= 0;
                state <= 2'b01;
                pixel_counter <= pixel_counter + 1;
            end
            else
                wait_counter_vs <= wait_counter_vs + 1;
        end

        2'b01:
        begin
            if(pixel_counter % 640 == 0)
            begin
                if(pixel_counter == 640*480)
                begin
                    pixel_counter <= 0;
                    state <= 2'b11; //vs wait
                end
                else
                    state <= 2'b10; // hs wait
            end
            else
                pixel_counter <= pixel_counter + 1;

        end

        2'b10:
        begin
            if(hsync == 1'b0)
            begin
                wait_counter_hs <= 0;
                state <= 2'b01;
                pixel_counter <= pixel_counter + 1;
            end
            else
                wait_counter_hs <= wait_counter_hs + 1;
        end

        2'b11:
        begin
            if(vsync == 1'b0)
            begin
                wait_counter_vs <= 0;
                state <= 2'b00;
            end
            else
                wait_counter_vs <= wait_counter_vs + 1;
        end

        endcase

    end
end

always@(posedge pclk)
begin
    if(reset_n == 1'b0)
        data_out <= 16'd0;
    else if(state == 2'b01)
        data_out <= {8'd0, data};
end

assign refclk = pclk;

endmodule

module morse_decoder (
	input clk,
	input [15:0] data,
	output reg [4:0] str
);

	reg [2:0] state = 0;
	reg [3:0] count = 0;
	reg [1:0] char_count = 0;
	reg [15:0] morse_code = 16'h0000;

	always @(posedge clk) begin
		case (state)
			0: begin
				if (data == 16'h0000) begin
					state <= 1;
					count <= 0;
				end
			end
			1: begin
				if (data == 16'h0001) begin
					state <= 2;
					count <= 0;
				end else if (count == 3) begin
					state <= 0;
				end else begin
					count <= count + 1;
				end
			end
			2: begin
				if (data == 16'h0000) begin
					morse_code[char_count*4 +: 4] <= count;
					char_count <= char_count + 1;
					if (char_count == 5) begin
						state <= 3;
						str <= {8'h68, 8'h65, 8'h6C, 8'h6C, 8'h6F};
					end else begin
						state <= 1;
					end
				end else if (count == 3) begin
					state <= 0;
				end else begin
					count <= count + 1;
				end
			end
			3: begin
				if (data == 16'h0000) begin
					state <= 1;
					count <= 0;
					char_count <= 0;
					morse_code <= 16'h0000;
				end
			end
			default: begin
				state <= 0;
			end
		endcase
	end

endmodule

module gost89_cfb(
  input              clk,
  input              reset,
  input              mode,
  input              load_data,
  input      [511:0] sbox,
  input      [255:0] key,
  input      [63:0]  in,
  output reg [63:0]  out,
  output reg         busy
);
  reg  [63:0] gamma;
  reg  [63:0] in_value;
  wire [63:0] out_ecb;
  wire        reset_ecb, load_ecb, busy_ecb;

  assign load_ecb = !reset && load_data;
  assign reset_ecb = load_ecb;

  gost89_ecb_encrypt
    ecb_encrypt(clk, reset_ecb, load_ecb, sbox, key, gamma, out_ecb, busy_ecb);

  always @(posedge clk) begin
    if (reset && !load_data) begin
      gamma <= in;
      busy <= 0;
    end

    if (!reset & load_data) begin
      in_value <= in;
      busy <= 1;
    end

    if (!reset && !load_data && !busy_ecb && busy) begin
      if (mode) gamma <= in;
      else      gamma <= out_ecb ^ in_value;
      out   <= out_ecb ^ gamma;
      busy  <= 0;
    end
  end
endmodule

module pipeline_module (
    input wire [2:0] in_num,
    output wire [2:0] out_num,
    output wire out_bit2,
    output wire out_bit1,
    output wire out_bit0
);

reg [2:0] stage1_num;
reg [2:0] stage2_num;
reg [2:0] stage3_num;

// Pipeline stage 1
always @(posedge clk) begin
    stage1_num <= in_num;
end

// Pipeline stage 2
always @(posedge clk) begin
    stage2_num <= stage1_num;
end

// Pipeline stage 3
always @(posedge clk) begin
    stage3_num <= stage2_num;
end

// Output stage
assign out_num = stage3_num;
assign out_bit2 = stage3_num[2];
assign out_bit1 = stage3_num[1];
assign out_bit0 = stage3_num[0];

endmodule

module RMON_CTRL (
Clk             ,      
Reset           ,      
//RMON_CTRL        
Reg_apply_0     ,      
Reg_addr_0      ,      
Reg_data_0      ,      
Reg_next_0      ,      
Reg_apply_1     ,      
Reg_addr_1      ,      
Reg_data_1      ,      
Reg_next_1      ,      
//dual-port ram
Addra               ,  
Dina                ,  
Douta               ,  
Wea                 ,  
//CPU                  
CPU_rd_addr     ,  
CPU_rd_apply        ,  
CPU_rd_grant        ,
CPU_rd_dout

);
input           Clk             ;
input           Reset           ;
                //RMON_CTRL
input           Reg_apply_0     ;
input   [4:0]   Reg_addr_0      ;
input   [15:0]  Reg_data_0      ;
output          Reg_next_0      ;
input           Reg_apply_1     ;
input   [4:0]   Reg_addr_1      ;
input   [15:0]  Reg_data_1      ;
output          Reg_next_1      ;
                //dual-port ram 
                //port-a for Rmon  
output  [5:0]   Addra               ;
output  [31:0]  Dina                ;
input   [31:0]  Douta               ;
output          Wea                 ;
                //CPU
input   [5:0]   CPU_rd_addr         ;
input           CPU_rd_apply        ;
output          CPU_rd_grant        ;
output  [31:0]  CPU_rd_dout         ;

//******************************************************************************
//internal signals                                                              
//******************************************************************************

parameter       StateMAC0        =4'd00;
parameter       StateMAC1        =4'd01;
parameter       StateCPU         =4'd02;

reg [3:0]       CurrentState     /* synthesys syn_keep=1 */;
reg [3:0]       NextState;
reg [3:0]       CurrentState_reg;

reg [4:0]       StepCounter;
reg [31:0]      DoutaReg;
reg [5:0]       Addra               ;
reg [31:0]      Dina;
reg             Reg_next_0      ;
reg             Reg_next_1      ;
reg             Write;
reg             Read;
reg             Pipeline;
reg [31:0]      CPU_rd_dout         ;
reg             CPU_rd_apply_reg    ;

//******************************************************************************
//State Machine                                                            
//******************************************************************************

always @(posedge Clk or posedge Reset)
    if (Reset)
        CurrentState    <=StateMAC0;
    else
        CurrentState    <=NextState;

always @(posedge Clk or posedge Reset)
    if (Reset)  
        CurrentState_reg    <=StateMAC0;
    else if(CurrentState!=StateCPU)
        CurrentState_reg    <=CurrentState;

always @(CurrentState or CPU_rd_apply_reg or Reg_apply_0 or CurrentState_reg
                                       or Reg_apply_1   
                                       or StepCounter
                                       )
    case(CurrentState)
        StateMAC0:
            if(!Reg_apply_0&&CPU_rd_apply_reg)
                NextState   =StateCPU;
            else if(!Reg_apply_0)
                NextState   =StateMAC1;
            else
                NextState   =CurrentState;
        StateMAC1:
            if(!Reg_apply_1&&CPU_rd_apply_reg)
                NextState   =StateCPU;
            else if(!Reg_apply_1)
                NextState   =StateMAC0;
            else
                NextState   =CurrentState;
        StateCPU:
            if (StepCounter==3)
                case (CurrentState_reg)
                    StateMAC0   :NextState  =StateMAC0 ;
                    StateMAC1   :NextState  =StateMAC1 ;
                    default     :NextState  =StateMAC0;
                endcase
            else
                NextState   =CurrentState;

        default:
                NextState   =StateMAC0;
    endcase



always @(posedge Clk or posedge Reset)
    if (Reset)
        StepCounter     <=0;
    else if(NextState!=CurrentState)
        StepCounter     <=0;
    else if (StepCounter!=4'hf)
        StepCounter     <=StepCounter + 1;

//******************************************************************************
//temp signals                                                            
//******************************************************************************
always @(StepCounter)
    if( StepCounter==1||StepCounter==4||
        StepCounter==7||StepCounter==10)
        Read    =1;
    else
        Read    =0;

always @(StepCounter or CurrentState)
    if( StepCounter==2||StepCounter==5||
        StepCounter==8||StepCounter==11)
        Pipeline    =1;
    else
        Pipeline    =0;

always @(StepCounter or CurrentState)
    if( StepCounter==3||StepCounter==6||
        StepCounter==9||StepCounter==12)
        Write   =1;
    else
        Write   =0;

always @(posedge Clk or posedge Reset)
    if (Reset)
        DoutaReg        <=0;
    else if (Read)
        DoutaReg        <=Douta;


//******************************************************************************
//gen output signals                                                        
//******************************************************************************    
//Addra 
always @(*)
    case(CurrentState)
        StateMAC0 :     Addra={1'd0 ,Reg_addr_0 };
        StateMAC1 :     Addra={1'd1 ,Reg_addr_1 };
        StateCPU:       Addra=CPU_rd_addr;
        default:        Addra=0;
        endcase

//Dina
always @(posedge Clk or posedge Reset)
    if (Reset)
        Dina    <=0;
    else 
        case(CurrentState)
            StateMAC0 :     Dina<=Douta+Reg_data_0 ;
            StateMAC1 :     Dina<=Douta+Reg_data_1 ;
            StateCPU:       Dina<=0;
            default:        Dina<=0;
        endcase

assign  Wea     =Write;
//Reg_next
always @(CurrentState or Pipeline)
    if(CurrentState==StateMAC0)
        Reg_next_0  =Pipeline;
    else
        Reg_next_0  =0;

always @(CurrentState or Pipeline)
    if(CurrentState==StateMAC1)
        Reg_next_1  =Pipeline;
    else
