module ramclock(
    input ref_clock, // Reference clock input
    output fpga_clock, // Output clock to drive FPGA logic
    output ram0_clock, ram1_clock, // Output clocks for each RAM chip
    input clock_feedback_in, // Output to feedback trace
    output clock_feedback_out, // Input from feedback trace
    output locked // Indicates that clock outputs are stable
);

    wire ref_clk, fpga_clk, ram_clk, fb_clk, lock1, lock2, dcm_reset;

    BUFG ref_buf (.O(ref_clk), .I(ref_clock));
    BUFG int_buf (.O(fpga_clock), .I(fpga_clk));
    BUFG ext_buf0 (.O(ram0_clock), .I(ram_clk));
    BUFG ext_buf1 (.O(ram1_clock), .I(ram_clk));
    IBUFG fb_buf (.O(fb_clk), .I(clock_feedback_in));

    DCM int_dcm (
        .CLKFB(fpga_clk),
        .CLKIN(ref_clk),
        .RST(dcm_reset),
        .CLK0(fpga_clk),
        .LOCKED(lock1)
    );

    DCM ext_dcm0 (
        .CLKFB(fb_clk),
        .CLKIN(ref_clk),
        .RST(dcm_reset),
        .CLK0(ram_clk),
        .LOCKED(lock2)
    );

    DCM ext_dcm1 (
        .CLKFB(fb_clk),
        .CLKIN(ref_clk),
        .RST(dcm_reset),
        .CLK0(ram_clk),
        .LOCKED(lock2)
    );

    SRL16 dcm_rst_sr (
        .D(1'b0),
        .CLK(ref_clk),
        .Q(dcm_reset),
        .A0(1'b1),
        .A1(1'b1),
        .A2(1'b1),
        .A3(1'b1)
    );

    OFDDRRSE ddr_reg0 (
        .Q(ram0_clock),
        .C0(ram_clk),
        .C1(~ram_clk),
        .CE(1'b1),
        .D0(1'b1),
        .D1(1'b0),
        .R(1'b0),
        .S(1'b0)
    );

    OFDDRRSE ddr_reg1 (
        .Q(ram1_clock),
        .C0(ram_clk),
        .C1(~ram_clk),
        .CE(1'b1),
        .D0(1'b1),
        .D1(1'b0),
        .R(1'b0),
        .S(1'b0)
    );

    OFDDRRSE ddr_reg2 (
        .Q(clock_feedback_out),
        .C0(ram_clk),
        .C1(~ram_clk),
        .CE(1'b1),
        .D0(1'b1),
        .D1(1'b0),
        .R(1'b0),
        .S(1'b0)
    );

    assign locked = lock1 && lock2;

endmodule

