module communication_module( 
  input logic writeRead,
  input logic newService,
  input logic multiblock,
  input logic timeoutenable,
  input logic reset,
  input logic[3:0] blockSize,
  input logic fifo_full,
  input logic[15:0] timeout,
  input logic SDclock,
  input logic clock,
  input logic[31:0] fromFifo_toPS,
  input logic fromSD_SP,
  output logic complete,
  output logic toSD_PS,
  output logic padState,
  output logic padEnable,
  output logic timeOutFail,
  output logic[31:0] fromSP_toFifo,
  output logic pop,
  output logic push,
  output logic IDLE_out
);

  // Define internal signals
  logic[31:0] data;
  logic[3:0] count;
  logic[15:0] timeout_count;
  logic timeout_flag;
  logic[1:0] state;
  logic[31:0] fifo_data;

  // Define constants
  parameter IDLE = 2'b00;
  parameter READ = 2'b01;
  parameter WRITE = 2'b10;
  parameter COMPLETE = 2'b11;

  // Define state machine
  always_ff @(posedge clock, posedge reset) begin
    if (reset) begin
      state <= IDLE;
      timeout_count <= 0;
      count <= 0;
      timeout_flag <= 0;
      complete <= 0;
      padState <= 0;
      padEnable <= 0;
      fromSP_toFifo <= 0;
      fifo_data <= 0;
      pop <= 0;
      push <= 0;
      IDLE_out <= 1;
    end else begin
      case(state)
        IDLE: begin
          if (newService) begin
            if (writeRead) begin
              state <= WRITE;
              padEnable <= 1;
              IDLE_out <= 0;
            end else begin
              state <= READ;
              padEnable <= 1;
              IDLE_out <= 0;
            end
          end else begin
            state <= IDLE;
            padEnable <= 0;
            IDLE_out <= 1;
          end
        end
        READ: begin
          if (fromSD_SP) begin
            data <= fromFifo_toPS;
            timeout_count <= 0;
            timeout_flag <= 0;
            state <= READ;
            padState <= 1;
            toSD_PS <= 1;
            IDLE_out <= 0;
            if (count == (blockSize - 1)) begin
              complete <= 1;
              state <= COMPLETE;
              padState <= 0;
              toSD_PS <= 0;
              count <= 0;
            end else begin
              count <= count + 1;
            end
          end else begin
            if (timeoutenable) begin
              timeout_count <= timeout_count + 1;
              if (timeout_count == timeout) begin
                timeout_flag <= 1;
                state <= COMPLETE;
                complete <= 1;
                padState <= 0;
                toSD_PS <= 0;
              end
            end
            state <= READ;
            padState <= 0;
            toSD_PS <= 0;
            IDLE_out <= 0;
          end
        end
        WRITE: begin
          if (fifo_full) begin
            state <= WRITE;
            padState <= 0;
            toSD_PS <= 0;
            IDLE_out <= 0;
          end else begin
            fifo_data <= fromSP_toFifo;
            push <= 1;
            state <= WRITE;
            padState <= 1;
            toSD_PS <= 0;
            IDLE_out <= 0;
            if (count == (blockSize - 1)) begin
              complete <= 1;
              state <= COMPLETE;
              padState <= 0;
              pop <= 1;
              count <= 0;
            end else begin
              count <= count + 1;
            end
          end
        end
        COMPLETE: begin
          state <= IDLE;
          timeout_count <= 0;
          timeout_flag <= 0;
          complete <= 0;
          padState <= 0;
          padEnable <= 0;
          fromSP_toFifo <= 0;
          fifo_data <= 0;
          pop <= 0;
          push <= 0;
          IDLE_out <= 1;
        end
      endcase
    end
  end

  // Define FIFO buffer
  fifo #(.WIDTH(32), .DEPTH(16)) fifo_inst (
    .clk(clock),
    .rst(reset),
    .wr_en(push),
    .rd_en(pop),
    .data_in(fifo_data),
    .data_out(fromFifo_toPS),
    .full(fifo_full)
  );

  // Define timeout logic
  always_ff @(posedge clock, posedge reset) begin
    if (reset) begin
      timeout_count <= 0;
      timeout_flag <= 0;
    end else begin
      if (timeoutenable) begin
        timeout_count <= timeout_count + 1;
        if (timeout_count == timeout) begin
          timeout_flag <= 1;
        end else begin
          timeout_flag <= 0;
        end
      end
    end
  end

  // Define output logic
  assign timeOutFail = timeout_flag;

endmodule

