module DCT (
  input [n-1:0] in,
  output [n-1:0] out
);

parameter n = 8; // number of input signals

// Define constants
localparam REAL_PI = 3.141592653589793;

// Define internal signals
wire [n-1:0] cos_term;
wire [n-1:0] dct_coef;

// Compute cosine terms
generate
  genvar u;
  for (u = 0; u < n; u = u + 1) begin : cos_loop
    assign cos_term[u] = cos((2*u+1)*REAL_PI/(2*n));
  end
endgenerate

// Compute DCT coefficients
generate
  genvar u, i;
  for (u = 0; u < n; u = u + 1) begin : dct_loop
    assign dct_coef[u] = (u == 0) ? 1/sqrt(2) : 1;
    assign out[u] = 0;
    for (i = 0; i < n; i = i + 1) begin : sum_loop
      assign out[u] = out[u] + in[i] * cos_term[i] * dct_coef[u];
    end
    assign out[u] = out[u] * sqrt(2/n) * dct_coef[u];
  end
endgenerate

endmodule
module IDCT (
  input [n-1:0] in,
  output [n-1:0] out
);

parameter n = 8; // number of input signals

// Define constants
localparam REAL_PI = 3.141592653589793;

// Define internal signals
wire [n-1:0] cos_term;
wire [n-1:0] idct_coef;

// Compute cosine terms
generate
  genvar u;
  for (u = 0; u < n; u = u + 1) begin : cos_loop
    assign cos_term[u] = cos((2*u+1)*REAL_PI/(2*n));
  end
endgenerate

// Compute IDCT coefficients
generate
  genvar u, i;
  for (i = 0; i < n; i = i + 1) begin : idct_loop
    assign idct_coef[i] = sqrt(2/n) * cos_term[i];
    assign out[i] = 0;
    for (u = 0; u < n; u = u + 1) begin : sum_loop
      assign out[i] = out[i] + in[u] * idct_coef[u];
    end
    assign out[i] = out[i] * ((i == 0) ? 1/sqrt(2) : 1);
  end
endgenerate

endmodule

