// Submodule 6: SPI state machine
module spiseq(
  input [3:0] spiclkcounter, // Counts the number of clock cycles in a transaction
  input spien, // SPI enable (SS)
  input mode, // Current mode of the SPI protocol (either read or write)
  input modet, // Indicates when the mode should be changed from write to read
  output spioe, // MISO 3 state enable
  output [3:0] addr, // Parallel address out
  output rdt, // Indicates a read transaction
  output rdld, // Indicates when data should be loaded into the shift register for a read transaction
  output wrt // Indicates a write transaction
);

  reg [1:0] state;

  always @(posedge spiclkcounter) begin
    if (spien) begin
      case (state)
        2'b00: begin // Idle state
          spioe <= 1'b1;
          addr <= 4'b0;
          rdt <= 1'b0;
          rdld <= 1'b0;
          wrt <= 1'b0;
          if (mode) begin
            state <= 2'b01;
          end
        end
        2'b01: begin // Write state
          spioe <= 1'b0;
          addr <= 4'b0;
          rdt <= 1'b0;
          rdld <= 1'b0;
          wrt <= 1'b1;
          if (modet) begin
            state <= 2'b10;
          end
        end
        2'b10: begin // Read state
          spioe <= 1'b1;
          addr <= 4'b0;
          rdt <= 1'b1;
          rdld <= 1'b1;
          wrt <= 1'b0;
          if (spiclkcounter == 4'b1111) begin
            state <= 2'b00;
          end
        end
      endcase
    end
  end

endmodule

