module sdQuadMagnitude #(
    parameter WIDTH = 16,
    parameter GAIN = 8
)
(
    input clk,   ///< System Clock
    input rst,   ///< Reset, active high & synchronous
    input en,    ///< Enable (use to clock at slower rate)
    input inSin, ///< Sigma-delta input, sine channel
    input inCos, ///< Sigma-delta input, cosine channel
    output wire [WIDTH-1:0] out ///< Magnitude of signal
);

localparam WIDTH_WORD = 16;

reg [WIDTH+GAIN-1:0] acc;
reg [3:0] sinC;
reg [3:0] cosC;
reg [5:0] sums;
reg inCosD1;
reg inSinD1;


always @(posedge clk) begin
    if (rst) begin
        acc     <= 'd0;
        inCosD1 <= 1'b0;
        inSinD1 <= 1'b0;
        sinC    <= 4'b0000;
        cosC    <= 4'b0000;
        sums    <= 6'd0;
    end
    else if (en) begin
        inSinD1 <= inSin;
        inCosD1 <= inCos;
        sums <= {6{sinC[3]&cosC[3]}} | {1'b0, sinC[3]^cosC[3], sinC[2]&cosC[2], sinC[2]^cosC[2], sinC[1]&cosC[1], sinC[1]^cosC[1]};
        sinC <= (inSin ^ inSinD1) ? 4'b0001 : {|sinC[3:1], sinC[0], 1'b0};
        cosC <= (inCos ^ inCosD1) ? 4'b0001 : {|cosC[3:1], cosC[0], 1'b0};
        acc <= acc - (acc >>> GAIN) + {sums[3], {12{sums[5]}}, sums[2], sums[1], {3{sums[5]}}};
    end
end

assign out = (acc >>> GAIN);

endmodule

