module uart_tx (
  clk,        // The external clock
  reset,      // Active high reset
  tx_line,    // The external line between devices driven by this UART
  tx_data,    // The data to be transmitted
  tx_request  // Begin transmission strobe
);
  input   clk;
  input   reset;
  output  tx_line;
  input   [7:0] tx_data;
  input   tx_request;
  reg     [7:0] shift_reg;
  reg           start_bit;
  reg           stop_bit;
  reg           tx_busy;
  reg           tx_enable;
  reg           tx_done;
  reg           tx_error;
  reg           tx_data_valid;
  reg           baud_tick;
  reg           baud_count;
  parameter     BAUD_RATE = 115200;
  parameter     BAUD_TICKS = $floor(50000000/BAUD_RATE);

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      shift_reg <= 8'h00;
      start_bit <= 1'b0;
      stop_bit <= 1'b1;
      tx_busy <= 1'b0;
      tx_enable <= 1'b0;
      tx_done <= 1'b0;
      tx_error <= 1'b0;
      tx_data_valid <= 1'b0;
      baud_tick <= 1'b0;
      baud_count <= 0;
    end else begin
      if (baud_tick) begin
        if (baud_count == BAUD_TICKS - 1) begin
          baud_count <= 0;
          baud_tick <= 1'b0;
          if (tx_enable) begin
            if (start_bit) begin
              tx_line <= 1'b0;
              start_bit <= 1'b0;
              shift_reg <= tx_data;
              tx_data_valid <= 1'b1;
            end else if (tx_data_valid) begin
              tx_line <= shift_reg[0];
              shift_reg <= {shift_reg[6:0], 1'b0};
              if (shift_reg == 8'h00) begin
                tx_data_valid <= 1'b0;
                stop_bit <= 1'b1;
                tx_done <= 1'b1;
                tx_busy <= 1'b0;
              end
            end else if (stop_bit) begin
              tx_line <= 1'b1;
              stop_bit <= 1'b0;
            end
          end
        end else begin
          baud_count <= baud_count + 1;
        end
      end else begin
        baud_tick <= 1'b1;
      end
      if (tx_request && !tx_busy) begin
        tx_busy <= 1'b1;
        tx_enable <= 1'b1;
        start_bit <= 1'b1;
        stop_bit <= 1'b0;
      end
      if (tx_busy && tx_done) begin
        tx_busy <= 1'b0;
        tx_enable <= 1'b0;
        tx_done <= 1'b0;
        tx_error <= 1'b0;
      end
    end
  end
endmodule

