    always @(posedge clk or posedge rst)
    begin
        if (rst)
        begin
            next_count <= 0;
            count <= 0;
            max_count <= 0;
        end
        else if (en)
        begin
            if (next_count == (2**N)-1)
            begin
                next_count <= 0;
                count <= 0;
                max_count <= 1;
            end
            else
            begin
                next_count <= next_count + 1;
                count <= next_count;
                max_count <= 0;
            end
        end
        else
        begin
            next_count <= count;
            max_count <= 0;
        end
    end

