module fft_wb(clk, reset, wb_clk, wb_stb_i, wb_dat_i, wb_adr_i, wb_we_i, wb_cyc_i, wb_sel_i, wb_err_o, wb_rty_o, wb_dat_o);

    input clk;
    input reset;
    input wb_clk;
    input wb_stb_i;
    input [31:0] wb_dat_i;
    input [31:0] wb_adr_i;
    input wb_we_i;
    input wb_cyc_i;
    input [3:0] wb_sel_i;
    output wb_err_o;
    output wb_rty_o;
    output [31:0] wb_dat_o;

    reg [31:0] control_reg;
    reg [31:0] read_reg;
    wire fft_done;
    wire [31:0] fft_out;
    reg [31:0] wb_adr_i_reg;

    bft fft_inst (
        .wbClk(wb_clk),
        .bftClk(wb_clk),
        .reset(reset),
        .wbDataForInput(1'b0),
        .wbInputData(wb_dat_i),
        .wbWriteOut(!wb_we_i),
        .wbDataForOutput(fft_done),
        .wbOutputData(fft_out),
        .error(wb_err_o)
    );

    always @(posedge wb_clk) begin
        wb_adr_i_reg <= {wb_adr_i[31:4], wb_adr_i[3] ^ wb_sel_i[3], wb_adr_i[2] ^ wb_sel_i[2], wb_adr_i[1] ^ wb_sel_i[1], wb_adr_i[0] ^ wb_sel_i[0]};
    end

    always @(posedge wb_clk or posedge reset) begin
        if (reset) begin
            control_reg <= 32'h0;
            read_reg <= 32'h0;
        end else begin
            if (fft_done) begin
                control_reg[0] <= 1'b1;
            end
            if (wb_stb_i && wb_cyc_i && wb_we_i) begin
                case (wb_adr_i_reg)
                    32'h0: control_reg <= wb_dat_i;
                    default: read_reg <= fft_out;
                endcase
            end else if (wb_stb_i && wb_cyc_i && ~wb_we_i) begin
                case (wb_adr_i_reg)
                    32'h0: control_reg[0] <= 1'b0;
                endcase
            end
        end
    end

    assign wb_dat_o = (wb_adr_i_reg == 32'h4) ? read_reg : 32'h0;
    assign wb_rty_o = control_reg[1] ^ control_reg[3] ^ control_reg[4] ^ control_reg[6] ^ control_reg[17] ^ control_reg[19] ^ control_reg[23] ^ control_reg[29] ^ control_reg[31];
    assign fft_inst.wbDataForInput = ~wb_stb_i;

endmodule

