    input debugaccess,
    input monitor_error,
    input monitor_go,
    input monitor_ready,
    input reset_n,
    input write,
    input [31:0] writedata,
    output reg [31:0] oci_ienable,
    output reg [31:0] oci_reg_readdata,
    output reg oci_single_step_mode,
    output reg ocireg_ers,
    output reg ocireg_mrs,
    output reg take_action_ocireg
);

wire oci_reg_00_addressed;
wire oci_reg_01_addressed;
wire [31:0] oci_reg_readdata_temp;
wire ocireg_sstep;
wire take_action_oci_intr_mask_reg;
wire write_strobe;

assign oci_reg_00_addressed = address == 9'h100;
assign oci_reg_01_addressed = address == 9'h101;
assign write_strobe = chipselect & write & debugaccess;
assign take_action_ocireg = write_strobe & oci_reg_00_addressed;
assign take_action_oci_intr_mask_reg = write_strobe & oci_reg_01_addressed;
assign ocireg_ers = writedata[1];
assign ocireg_mrs = writedata[0];
assign ocireg_sstep = writedata[3];
assign oci_reg_readdata_temp = oci_reg_00_addressed ? {28'b0, oci_single_step_mode, monitor_go,
    monitor_ready, monitor_error} : oci_reg_01_addressed ? oci_ienable : 32'b0;

always @(posedge clk or negedge reset_n) begin
