reg [99:0] shift_reg;
reg [7:0] reg_data;

always @(posedge clk) begin
    if (load) begin
        shift_reg <= data;
        reg_data <= d;
    end else begin
        case (ena)
            2'b00: begin // hold
                shift_reg <= shift_reg;
            end
            2'b01: begin // shift left
                shift_reg <= {shift_reg[98:0], shift_reg[99]};
            end
            2'b10: begin // shift right
                shift_reg <= {shift_reg[0], shift_reg[99:1]};
            end
            2'b11: begin // hold
                shift_reg <= shift_reg;
            end
        endcase
        reg_data <= reg_data;
    end
end

assign q = shift_reg;
assign q_reg = reg_data;

assign and_output = q[7:0] & q_reg;

endmodule

module ripple_carry_adder (
  input clk,
  input reset,
  input [3:0] A,
  input [3:0] B,
  input Cin,
  output [3:0] Sum,
  output Cout
);

  reg [3:0] temp_sum;
  reg temp_carry;

  always @(posedge clk) begin
    if (reset) begin
      temp_sum <= 4'b0;
      temp_carry <= 1'b0;
    end
    else begin
      temp_sum <= A + B + Cin;
      temp_carry <= (temp_sum > 4'b1111) ? 1'b1 : 1'b0;
    end
  end

  assign Sum = temp_sum;
  assign Cout = temp_carry;

endmodule

module shift_counter (
    input clk,
    input load,
    input select,
    input [3:0] data_in,
    output [3:0] q
);

    reg [3:0] shift_reg;
    reg [3:0] counter_reg;
    wire [3:0] sum;

    // Shift Register
    always @(posedge clk) begin
        if (load) begin
            shift_reg <= data_in;
        end else begin
            shift_reg <= {shift_reg[2:0], shift_reg[3]};
        end
    end

    // Counter
    always @(posedge clk) begin
        if (select) begin
            counter_reg <= counter_reg + 1;
        end
    end

    // Sum
    assign sum = shift_reg + counter_reg;

    // Output
    assign q = select ? counter_reg : shift_reg;

endmodule

module shiftRegFIFO(X, Y, clk);
   parameter depth=1, width=1;

   output [width-1:0] Y;
   input  [width-1:0] X;
   input              clk;

   reg [width-1:0]    mem [depth-1:0];
   integer            index;

   assign Y = mem[depth-1];

   always @ (posedge clk) begin
      for(index=1;index<depth;index=index+1) begin
         mem[index] <= mem[index-1];
      end
      mem[0]<=X;
   end
endmodule

module dual_edge_triggered_flip_flop (
    input clk, // Clock input
    input reset, // Asynchronous reset input
    input d, // Data input
    output reg q // Output of the flip-flop
);

reg q1, q2;

always @(negedge clk) begin
    q1 <= d;
    q2 <= q1;
end

always @(posedge clk) begin
    q1 <= q2;
    q2 <= d;
end

always @(posedge clk or negedge reset) begin
    if (reset == 0) begin
        q1 <= 0;
        q2 <= 0;
    end
end

assign q = select ? ~q2 : ~q1;

endmodule

