module bt656cap (
    input sys_clk, // system clock
    input sys_rst, // system reset

    input vid_clk, // video clock
    input [7:0] p, // video pixel data

    input [13:0] csr_a, // CSR address
    input csr_we, // CSR write enable
    input [31:0] csr_di, // CSR write data
    output reg [31:0] csr_do, // CSR read data

    output reg irq, // interrupt signal

    output reg [fml_depth-1:0] fml_adr, // frame buffer address
    input fml_stb, // frame buffer strobe
    output reg fml_ack, // frame buffer acknowledge
    input [63:0] fml_do // frame buffer write data
);

parameter fml_depth = 26;

reg [23:0] pixel_count;
reg [1:0] state;
reg [31:0] csr[15:0];
reg [31:0] fml[fml_depth-1:0][720*480/2-1:0];

assign csr_do = csr[csr_a];

always @(posedge sys_clk) begin
    if (sys_rst) begin
        pixel_count <= 0;
        state <= 0;
        csr <= 0;
        fml <= 0;
        irq <= 0;
        fml_ack <= 0;
    end else begin
        case (state)
            0: begin // wait for first sync word
                if (p == 8'hff) begin
                    pixel_count <= 0;
                    state <= 1;
                end
            end
            1: begin // wait for second sync word
                if (p == 8'h00) begin
                    state <= 2;
                end
            end
            2: begin // wait for third sync word
                if (p == 8'hff) begin
                    state <= 3;
                end
            end
            3: begin // wait for fourth sync word
                if (p == 8'h00) begin
                    state <= 4;
                end
            end
            4: begin // capture pixel data
                fml[fml_adr][pixel_count] <= {p, 8'h00};
                pixel_count <= pixel_count + 1;
                if (pixel_count == 720*480/2) begin
                    pixel_count <= 0;
                    state <= 0;
                    irq <= 1;
                end
            end
        endcase

        if (csr_we) begin
            csr[csr_a] <= csr_di;
        end
    end
end

always @(posedge sys_clk) begin
    if (fml_stb) begin
        fml_ack <= 1;
        fml[fml_adr][fml_adr[1:0]*720 + fml_adr[10:2]] <= fml_do[63:48];
        fml[fml_adr][fml_adr[1:0]*720 + fml_adr[10:2]+1] <= fml_do[47:32];
        fml[fml_adr][fml_adr[1:0]*720 + fml_adr[10:2]+2] <= fml_do[31:16];
        fml[fml_adr][fml_adr[1:0]*720 + fml_adr[10:2]+3] <= fml_do[15:0];
    end else begin
        fml_ack <= 0;
    end
end

endmodule

