module proc_unit #(parameter word_sz=8, sel1_sz=3, sel2_sz=2, op_sz=4)
	(	output [word_sz-1:0] instr, 
		output flag_z, 
		output [word_sz-1:0] addr, bus_1,
		input [word_sz-1:0] mem_word, io_word,
		input load_r0, load_r1, load_r2, load_r3, load_pc, inc_pc,
		input [sel1_sz-1:0] bus1_sel_mux,
		input [sel2_sz-1:0] bus2_sel_mux,
		input load_ir, load_add_r, load_reg_y, load_reg_z,
		input clk, rst);


	wire [word_sz-1:0] bus_1, bus_2, out_r0, out_r1, out_r2, out_r3;
	wire [word_sz-1:0] pc_count, y_value, alu_out;

	wire alu_zero_flag;

	wire [op_sz-1:0] opcode = instr[word_sz-1:word_sz-op_sz];

	reg_unit #(word_sz)
		r0 (out_r0, bus_2, load_r0, clk, rst),
		r1 (out_r1, bus_2, load_r1, clk, rst),
		r2 (out_r2, bus_2, load_r2, clk, rst),
		r3 (out_r3, bus_2, load_r3, clk, rst);

	reg_unit #(word_sz) reg_y (y_value, bus_2, load_reg_y, clk, rst);

	reg_unit #(1) reg_z(flag_z, alu_zero_flag, load_reg_z, clk, rst);

	/* address register */
	reg_unit #(word_sz) add_r(addr, bus_2, load_add_r, clk, rst);

	reg_unit #(word_sz) instr_reg(instr, bus_2, load_ir, clk, rst);

	prgm_cnt  pc(pc_count, bus_2, load_pc, inc_pc, clk, rst);

	mux_5ch   mux_1(bus_1, out_r0, out_r1, out_r2, out_r3, pc_count, bus1_sel_mux);
	mux_4ch   mux_2(bus_2, alu_out, bus_1, mem_word, io_word, bus2_sel_mux);

	alu_risc alu(alu_zero_flag, alu_out, y_value, bus_1, opcode);

endmodule

/* Internal Register Unit */
module reg_unit #(parameter word_sz=8)
		(output logic [word_sz-1:0] out,
		input logic [word_sz-1:0] in,
		input logic load,
		input logic clk,
		input logic rst);

	always @(posedge clk or posedge rst) begin
		if (rst) begin
			out <= 0;
		end else if (load) begin
			out <= in;
		end
	end

endmodule

/* Program Counter */
module prgm_cnt #(parameter word_sz=8)
		(output logic [word_sz-1:0] count,
		output logic [word_sz-1:0] out,
		input logic load,
		input logic inc,
		input logic clk,
		input logic rst);

	always @(posedge clk or posedge rst) begin
		if (rst) begin
			count <= 0;
			out <= 0;
		end else if (load) begin
			count <= out;
		end else if (inc) begin
			count <= count + 1;
		end
		out <= count;
	end

endmodule

/* Multiplexer with 5 inputs */
module mux_5ch #(parameter word_sz=8)
		(output logic [word_sz-1:0] out,
		input logic [word_sz-1:0] in0,
		input logic [word_sz-1:0] in1,
		input logic [word_sz-1:0] in2,
		input logic [word_sz-1:0] in3,
		input logic [word_sz-1:0] in4,
		input logic [2:0] sel);

	always @(*) begin
		case (sel)
			3'b000: out = in0;
			3'b001: out = in1;
			3'b010: out = in2;
			3'b011: out = in3;
			3'b100: out = in4;
			default: out = in0;
		endcase
	end

endmodule

/* Multiplexer with 4 inputs */
module mux_4ch #(parameter word_sz=8)
		(output logic [word_sz-1:0] out,
		input logic [word_sz-1:0] in0,
		input logic [word_sz-1:0] in1,
		input logic [word_sz-1:0] in2,
		input logic [word_sz-1:0] in3,
		input logic [1:0] sel);

	always @(*) begin
		case (sel)
			2'b00: out = in0;
			2'b01: out = in1;
			2'b10: out = in2;
			2'b11: out = in3;
			default: out = in0;
		endcase
	end

endmodule

/* ALU */
module alu_risc #(parameter word_sz=8)
		(output logic zero_flag,
		output logic [word_sz-1:0] out,
		input logic [word_sz-1:0] in_a,
		input logic [word_sz-1:0] in_b,
		input logic [op_sz-1:0] opcode);

	logic [word_sz-1:0] temp_out;

	always @(*) begin
		case (opcode)
			4'b0000: temp_out = in_a & in_b;
			4'b0001: temp_out = in_a | in_b;
			4'b0010: temp_out = in_a + in_b;
			4'b0011: temp_out = in_a - in_b;
			4'b0100: temp_out = in_a << in_b;
			4'b0101: temp_out = in_a >> in_b;
			4'b0110: temp_out = in_a ^ in_b;
			4'b0111: temp_out = ~in_a;
			default: temp_out = in_a;
		endcase

		if (temp_out == 0) begin
			zero_flag = 1;
		end else begin
			zero_flag = 0;
		end
		out = temp_out;
	end

endmodule

