    wire [7:0] dec1;
    assign dec1 = {3'b001, 1'b0, 3'b001, 1'b0, 3'b001, 1'b0, 3'b001, 1'b0};
    assign o1 = dec1[vec];

    // Decoder for o2
    wire [7:0] dec2;
    assign dec2 = {3'b010, 1'b0, 3'b010, 1'b0, 3'b010, 1'b0, 3'b010, 1'b0};
    assign o2 = dec2[vec];

    // Output the input vector
    assign outv = vec;

endmodule

