module DisplayModule(clock, reset, pixCellIx, cellData, fontGlyph, fontData, busAddr, busData, busOE, busWR, busOK);

  input clock;
  input reset;

  input [13:0] pixCellIx;
  output [127:0] cellData;

  input [15:0] fontGlyph;
  output [63:0] fontData;

  input [31:0] busAddr;
  inout [31:0] busData;
  input busOE;
  input busWR;
  output [1:0] busOK;

  reg [31:0] scrCell1A [0:4095];
  reg [31:0] scrCell1B [0:4095];
  reg [31:0] scrCell1C [0:4095];
  reg [31:0] scrCell1D [0:4095];

  reg [63:0] fontMem [0:255];
  reg [63:0] fontGfx1Mem [0:127];
  reg [63:0] fontGfx2Mem [0:127];

  reg [31:0] scrRegCtrl [0:7];

  reg [127:0] cell1;
  reg [127:0] nextCell1;

  reg [15:0] fontGlyphIn;
  reg [63:0] fontDataOut1;
  reg [63:0] fontDataOut2;
  reg [63:0] fontDataAsc1;
  reg [63:0] fontDataGfx1;
  reg [63:0] fontDataGfx2;

  reg [13:0] pixCellIxIn;
  reg [13:0] nextPixCellIx;

  reg [1:0] busOKOut;
  reg [31:0] busDataOut;

  wire busCSel;

  assign busOK = busOKOut;
  assign busData = (busOE && busCSel) ? busDataOut : 32'hZZZZ_ZZZZ;
  assign busCSel = (busAddr[31:16] == 16'h0080);

  always @(posedge clock) begin
    if (reset) begin
      nextCell1 <= 0;
      nextPixCellIx <= 0;
      fontGlyphIn <= 0;
      fontDataOut1 <= 0;
      fontDataOut2 <= 0;
      fontDataAsc1 <= 0;
      fontDataGfx1 <= 0;
      fontDataGfx2 <= 0;
      busDataOut <= 0;
      busOKOut <= 0;
    end else begin
      nextPixCellIx <= pixCellIxIn;

      if (busOE && busCSel) begin
        if (busAddr[15:8] == 8'hFF) begin
          busOKOut <= 1;
          case (busAddr[6:2])
            0: busDataOut <= scrRegCtrl[0];
            1: busDataOut <= scrRegCtrl[1];
            2: busDataOut <= scrRegCtrl[2];
            3: busDataOut <= scrRegCtrl[3];
            8: busDataOut <= {18'h0, pixCellIxIn};
          endcase
        end else begin
          busOKOut <= (pixCellIxIn[11:0] == busAddr[15:4]) ? 1 : 0;
          case (busAddr[3:2])
            2'b00: busDataOut <= cell1[31:0];
            2'b01: busDataOut <= cell1[63:32];
            2'b10: busDataOut <= cell1[95:64];
            2'b11: busDataOut <= cell1[127:96];
          endcase
        end
      end

      fontGlyphIn <= fontGlyph;
      fontDataAsc1 <= fontMem[fontGlyphIn[7:0]];
      fontDataGfx1 <= fontGfx1Mem[fontGlyphIn[6:0]];
      fontDataGfx2 <= fontGfx2Mem[fontGlyphIn[6:0]];

      case (fontGlyphIn[9:7])
        3'b000, 3'b001: fontDataOut2 <= fontDataAsc1;
        3'b010: fontDataOut2 <= fontDataGfx2;
        3'b011: fontDataOut2 <= fontDataGfx1;
        default: fontDataOut2 <= fontDataAsc1;
      endcase

      if (busCSel && busWR && !busOE) begin
        if (busAddr[15:8] == 8'hFF) begin
          scrRegCtrl[busAddr[4:2]] <= busData;
        end else begin
          case (busAddr[3:2])
            2'b00: scrCell1A[busAddr[15:4]] <= busData;
            2'b01: scrCell1B[busAddr[15:4]] <= busData;
            2'b10: scrCell1C[busAddr[15:4]] <= busData;
            2'b11: scrCell1D[busAddr[15:4]] <= busData;
          endcase
        end
      end
    end
  end

  always @(posedge clock) begin
    pixCellIxIn <= nextPixCellIx;
    cell1[31:0] <= scrCell1A[pixCellIxIn[11:0]];
    cell1[63:32] <= scrCell1B[pixCellIxIn[11:0]];
    cell1[95:64] <= scrCell1C[pixCellIxIn[11:0]];
    cell1[127:96] <= scrCell1D[pixCellIxIn[11:0]];

    fontDataOut1 <= fontDataOut2;

    if (busCSel && busOE) begin
      pixCellIxIn <= busAddr[15:2];
    end else begin
      pixCellIxIn <= pixCellIx;
    end
  end

  assign cellData = cell1;
  assign fontData = fontDataOut1;

endmodule

module top_module (
    input CLK,
    input LOAD,
    input [2:0] LOAD_VAL,
    input UP_DOWN,
    input CARRY_IN,
    input A, B,
    output reg [3:0] Q,
    output reg [3:0] Y,
    output reg [6:0] out
);

reg [2:0] counter;
reg [1:0] priority;

always @(posedge CLK) begin
    if (LOAD) begin
        counter <= LOAD_VAL;
    end else if (UP_DOWN) begin
        counter <= counter + CARRY_IN;
    end else begin
        counter <= counter - CARRY_IN;
    end

    priority <= {A, B};

    case (priority)
        2'b00: Y <= 4'b0001;
        2'b01: Y <= 4'b0010;
        2'b10: Y <= 4'b0100;
        2'b11: Y <= 4'b1000;
    endcase

    out <= counter + Y;
end

assign Q = counter;

endmodule

