      q2 <= 1'b0;
    end
    else begin
      q1 <= data;
      q2 <= q1;
    end
  end

  always @(negedge clk) begin
    q <= q2;
  end

endmodule

module pattern_detector (
    input wire clk,
    input wire [7:0] in,
    output wire pattern_detected
);

reg [3:0] count;
reg pattern_detected_reg;

always @(posedge clk) begin
    if (in[3:0] == 4'b1101) begin
        count <= count + 1;
    end else begin
        count <= 0;
    end

    if (count == 3) begin
        pattern_detected_reg <= 1;
    end else begin
        pattern_detected_reg <= 0;
    end
end

assign pattern_detected = pattern_detected_reg;

endmodule

module or_module (
    input wire [7:0] in,
