  input clk,
  input rstn,
  input [7:0] in_data,
  input in_valid,
  input in_error,
  output reg out_ready,
  output reg [7:0] out_data,
  output reg out_valid
);

  always @(posedge clk or negedge rstn) begin
    if (!rstn) begin
      out_ready <= 1'b0;
      out_valid <= 1'b0;
    end else begin
      out_ready <= in_valid;
      out_valid <= out_ready;
      out_data <= in_data; // Implement data processing logic here
    end
  end
endmodule

module mult_4bit(A, B, result);
	input [3:0] A;
	input [3:0] B;
	output [7:0] result;

	reg [7:0] temp;
	reg [3:0] i;

	always @* begin
		temp = 0;
		for (i = 0; i < 4; i = i+1) begin
			if (B[i] == 1) begin
				temp = temp + (A << i);
			end
		end
		result = temp;
	end
endmodule

module dff_sr (
    input D,
    input CLK,
    input SET_B,
    input RESET_B,
    output reg Q,
    output reg Q_N
);

always @ (posedge CLK) begin
    if (SET_B == 0) begin
        Q <= 1;
        Q_N <= 0;
    end else if (RESET_B == 0) begin
        Q <= 0;
        Q_N <= 1;
    end else begin
        Q <= D;
        Q_N <= ~D;
    end
end

endmodule

