module vending_machine (
    input wire [1:0] coin,
    input wire [1:0] product,
    input wire reset,
    output reg dispense,
    output reg [1:0] change
);

    parameter A_PRICE = 2'b01;
    parameter B_PRICE = 2'b10;
    parameter C_PRICE = 2'b11;

    reg [3:0] total;
    reg [3:0] price;
    reg [3:0] change_value;
    reg [1:0] change_coin;

    always @(posedge reset) begin
        total <= 0;
        price <= 0;
        change_value <= 0;
        change_coin <= 0;
    end

    always @(*) begin
        case(product)
            2'b00: price = A_PRICE;
            2'b01: price = B_PRICE;
            2'b10: price = C_PRICE;
            default: price = 0;
        endcase
    end

    always @(posedge reset, posedge coin, posedge product) begin
        if(reset) begin
            total <= 0;
            dispense <= 0;
            change <= 0;
            change_value <= 0;
            change_coin <= 0;
        end else begin
            total <= total + coin;
            if(total >= price) begin
                dispense <= 1;
                change_value <= total - price;
                if(change_value >= 2) begin
                    change_coin <= 3;
                    change_value <= change_value - 2;
                end else if(change_value == 1) begin
                    change_coin <= 1;
                    change_value <= change_value - 1;
                end else begin
                    change_coin <= 0;
                end
            end else begin
                dispense <= 0;
                change_value <= 0;
                change_coin <= 0;
            end
        end
    end

    always @(posedge reset, posedge coin, posedge product) begin
        if(reset) begin
            change <= 0;
        end else begin
            if(dispense) begin
                change <= change_coin;
            end else begin
                change <= 0;
            end
        end
    end

endmodule

