module i2c_state_machine (
  input clk,
  input rst,
  input sda_in,
  input sda_en,
  input scl_en,
  output reg sda_out,
  output reg sda_ack,
  output reg sda_busy
);

  // Define the states of the state machine
  parameter IDLE = 2'b00;
  parameter READ = 2'b01;
  parameter WRITE = 2'b10;

  // Define the state register and initialize it to IDLE
  reg [1:0] state_reg = IDLE;

  // Define the data register and initialize it to 0
  reg [7:0] data_reg = 8'b00000000;

  // Define the bit counter and initialize it to 0
  reg [2:0] bit_counter = 3'b000;

  // Define the acknowledge flag and initialize it to 0
  reg ack_flag = 1'b0;

  always @(posedge clk) begin
    if (rst) begin
      // Reset the state machine
      state_reg <= IDLE;
      data_reg <= 8'b00000000;
      bit_counter <= 3'b000;
      ack_flag <= 1'b0;
      sda_out <= 1'b1;
      sda_ack <= 1'b0;
      sda_busy <= 1'b0;
    end else begin
      // Check if the SCL and SDA signals are enabled
      if (scl_en && sda_en) begin
        case (state_reg)
          IDLE: begin
            // Wait for the start condition from the master
            if (!sda_in && sda_en) begin
              state_reg <= READ;
              bit_counter <= 3'b000;
              ack_flag <= 1'b0;
              sda_ack <= 1'b0;
              sda_busy <= 1'b1;
            end else if (sda_in && sda_en) begin
              state_reg <= WRITE;
              bit_counter <= 3'b000;
              ack_flag <= 1'b0;
              sda_ack <= 1'b0;
              sda_busy <= 1'b1;
            end
          end
          READ: begin
            // Read data from the slave device
            if (bit_counter < 3) begin
              sda_out <= 1'b0;
              bit_counter <= bit_counter + 1;
            end else if (bit_counter == 3) begin
              sda_out <= 1'b1;
              bit_counter <= bit_counter + 1;
            end else if (bit_counter < 11) begin
              data_reg[bit_counter-4] <= sda_in;
              sda_out <= 1'b1;
              bit_counter <= bit_counter + 1;
            end else if (bit_counter == 11) begin
              ack_flag <= ~sda_in;
              sda_out <= 1'b0;
              bit_counter <= bit_counter + 1;
            end else if (bit_counter == 12) begin
              sda_out <= 1'b1;
              sda_ack <= ack_flag;
              sda_busy <= 1'b0;
              if (sda_in && sda_en) begin
                state_reg <= IDLE;
              end
            end
          end
          WRITE: begin
            // Write data to the slave device
            if (bit_counter < 8) begin
              sda_out <= data_reg[bit_counter];
              bit_counter <= bit_counter + 1;
            end else if (bit_counter == 8) begin
              ack_flag <= ~sda_in;
              sda_out <= 1'b0;
              bit_counter <= bit_counter + 1;
            end else if (bit_counter == 9) begin
              sda_out <= 1'b1;
              sda_ack <= ack_flag;
              sda_busy <= 1'b0;
              if (sda_in && sda_en) begin
                state_reg <= IDLE;
              end else if (!ack_flag) begin
                bit_counter <= 3'b000;
              end
            end
          end
        endcase
      end else begin
        // If the SCL or SDA signals are not enabled, reset the state machine
        state_reg <= IDLE;
        data_reg <= 8'b00000000;
        bit_counter <= 3'b000;
        ack_flag <= 1'b0;
        sda_out <= 1'b1;
        sda_ack <= 1'b0;
        sda_busy <= 1'b0;
      end
    end
  end

endmodule

module bcd_counter (
    input clk,
    input reset,   // Synchronous active-high reset
    input [2:0] ena,   // Enable signals for upper three digits
    output reg [15:0] q);   // Output BCD counter value

    reg [3:0] ones_digit, tens_digit, hundreds_digit, thousands_digit;

    always @(posedge clk) begin
        if (reset) begin
            ones_digit <= 4'b0000;
            tens_digit <= 4'b0000;
            hundreds_digit <= 4'b0000;
            thousands_digit <= 4'b0000;
        end
        else begin
            // Increment ones digit
            if (ena[0]) begin
                if (ones_digit == 4'b1001) begin
                    ones_digit <= 4'b0000;
                    tens_digit <= tens_digit + 1;
                end
                else begin
                    ones_digit <= ones_digit + 1;
                end
            end

            // Increment tens digit
            if (ena[1]) begin
                if (tens_digit == 4'b1001) begin
                    tens_digit <= 4'b0000;
                    hundreds_digit <= hundreds_digit + 1;
                end
                else begin
                    tens_digit <= tens_digit + 1;
                end
            end

            // Increment hundreds digit
            if (ena[2]) begin
                if (hundreds_digit == 4'b1001) begin
                    hundreds_digit <= 4'b0000;
                    thousands_digit <= thousands_digit + 1;
                end
                else begin
                    hundreds_digit <= hundreds_digit + 1;
                end
            end

            // Increment thousands digit
            if (thousands_digit != 4'b1001 && ena[2]) begin
                thousands_digit <= thousands_digit + 1;
            end
        end
    end

    assign q = {thousands_digit, hundreds_digit, tens_digit, ones_digit};
    assign ena = {ena[2:0]};
endmodule

