module booth_multiplier (
    input [15:0] A,
    input [15:0] B,
    input C,
    output reg [31:0] P
);

reg [31:0] A_ext;
reg [31:0] S;

always @(A or B) begin
    if (C) begin
        A_ext = {{16{A[15]}}, A[15:0]};
    end else begin
        A_ext = {16'b0, A};
    end
    S = {16'b0, B};
end

always @(posedge clk) begin
    if (S[0] == 1'b1) begin
        P <= P + A_ext;
    end
    if (S[1:0] == 2'b10 || S[1:0] == 2'b01) begin
        P <= P + (A_ext << 1);
    end
    if (S[3:0] == 4'b1000 || S[3:0] == 4'b0100) begin
        P <= P + (A_ext << 2);
    end
    if (S[7:0] == 8'b10000000 || S[7:0] == 8'b01000000) begin
        P <= P + (A_ext << 4);
    end
    if (S[15:0] == 16'b1000000000000000 || S[15:0] == 16'b0100000000000000) begin
        P <= P + (A_ext << 8);
    end
end

endmodule

