    wire [99:0] a_sel;
    wire [99:0] b_sel;

    // Control Logic Module
    assign a_sel = (select[1]) ? a : 100'b0;
    assign b_sel = (select[0]) ? b : 100'b0;

    // Carry Select Adder
    CSA_100bit adder(
        .a(a_sel),
        .b(b_sel),
        .cin(cin),
        .cout(cout),
        .sum(adder_out)
    );

    // Output
    assign sum = (select[2]) ? adder_out : 100'b0;

endmodule

module CSA_100bit(
    input [99:0] a, b,
    input cin,
    output cout,
    output [99:0] sum
);

    wire [99:0] p, g;
    wire [98:0] c;

    // Generate P and G signals
    genvar i;
    generate
        for (i = 0; i < 100; i = i + 1) begin : gen
            assign p[i] = a[i] ^ b[i];
            assign g[i] = a[i] & b[i];
        end
    endgenerate

    // Generate Carry Chains
    genvar j;
    generate
        for (j = 0; j < 99; j = j + 2) begin : gen2
            assign c[j] = (j == 0) ? cin : g[j-1] | (p[j-1] & c[j-2]);
            assign c[j+1] = g[j] | (p[j] & c[j-1]);
        end
    endgenerate

    // Generate Sum
    assign sum = p + c;

    // Generate Cout
    assign cout = g[99] | (p[99] & c[98]);

endmodule

