module MUX4 (A, B, C, D, S0, S1, E, Y);
input A, B, C, D, S0, S1, E;
output Y;

wire Y1, Y2, Y3, Y4;

// 4-to-1 multiplexer
assign Y1 = (S1 & ~S0 & ~E) ? A : 1'bx;
assign Y2 = (~S1 & ~S0 & ~E) ? B : 1'bx;
assign Y3 = (S1 & S0 & ~E) ? C : 1'bx;
assign Y4 = (~S1 & S0 & ~E) ? D : 1'bx;

// OR gate
assign Y = (E) ? (A | B | C | D) : ((Y1 & Y2 & Y3 & Y4) ? 1'bx : (Y1 | Y2 | Y3 | Y4));

endmodule

module simple_cpu(
    input clk,
    input reset,
    input [7:0] address,
    input [15:0] data_in,
    output [15:0] data_out
);

reg [15:0] accumulator;
reg [7:0] program_counter;

reg [15:0] memory [255:0];

always @(posedge clk) begin
    if (reset) begin
        accumulator <= 16'b0;
        program_counter <= 8'b0;
    end else begin
        case (memory[program_counter])
            3'h0: accumulator <= accumulator + memory[address];
            3'h1: accumulator <= accumulator - memory[address];
            3'h2: accumulator <= accumulator & memory[address];
            3'h3: accumulator <= accumulator | memory[address];
            3'h4: accumulator <= accumulator ^ memory[address];
            3'h5: accumulator <= memory[address];
            3'h6: memory[address] <= accumulator;
            default: accumulator <= accumulator;
        endcase
        program_counter <= program_counter + 1;
    end
end

assign data_out = accumulator;

endmodule

module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out
);

    parameter BUFFER_DEPTH = 8;
    reg [7:0] buffer [0:BUFFER_DEPTH-1];
    reg [3:0] count = 0;
    reg [9:0] accumulator = 0;
    reg [2:0] index = 0;
    reg [2:0] next_index = 0;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            count <= 0;
            accumulator <= 0;
            index <= 0;
            valid_b <= 0;
        end
        else begin
            if (valid_a && ready_b) begin
                buffer[index] <= data_in;
                count <= count + 1;
                accumulator <= accumulator + data_in;
                next_index <= index + 1;
                if (next_index == BUFFER_DEPTH) begin
                    next_index <= 0;
                end
                index <= next_index;
            end
            if (count == BUFFER_DEPTH) begin
                valid_b <= 1;
                data_out <= accumulator;
                accumulator <= 0;
                count <= 0;
            end
            else begin
                valid_b <= 0;
            end
        end
    end

    assign ready_a = ~valid_b;

endmodule

