module hierarchical_design(
    input [99:0] in_100,
    output [7:0] out_and,
    output [7:0] out_or,
    output [7:0] out_xor
);
    wire [7:0] and_0, and_1, and_2, and_3, and_4, and_5, and_6, and_7, and_8, and_9;
    wire [7:0] or_0, or_1, or_2, or_3, or_4, or_5, or_6, or_7, or_8, or_9;
    wire [7:0] xor_0, xor_1, xor_2, xor_3, xor_4, xor_5, xor_6, xor_7, xor_8, xor_9;

    // Level 1
    assign and_0 = in_100[0] & in_100[1];
    assign or_0 = in_100[0] | in_100[1];
    assign xor_0 = in_100[0] ^ in_100[1];

    assign and_1 = in_100[2] & in_100[3];
    assign or_1 = in_100[2] | in_100[3];
    assign xor_1 = in_100[2] ^ in_100[3];

    assign and_2 = in_100[4] & in_100[5];
    assign or_2 = in_100[4] | in_100[5];
    assign xor_2 = in_100[4] ^ in_100[5];

    assign and_3 = in_100[6] & in_100[7];
    assign or_3 = in_100[6] | in_100[7];
    assign xor_3 = in_100[6] ^ in_100[7];

    assign and_4 = in_100[8] & in_100[9];
    assign or_4 = in_100[8] | in_100[9];
    assign xor_4 = in_100[8] ^ in_100[9];

    // Level 2
    assign and_5 = and_0 & and_1;
    assign or_5 = or_0 | or_1;
    assign xor_5 = xor_0 ^ xor_1;

    assign and_6 = and_2 & and_3;
    assign or_6 = or_2 | or_3;
    assign xor_6 = xor_2 ^ xor_3;

    assign and_7 = and_4 & in_100[10];
    assign or_7 = or_4 | in_100[10];
    assign xor_7 = xor_4 ^ in_100[10];

    // Level 3
    assign and_8 = and_5 & and_6;
    assign or_8 = or_5 | or_6;
    assign xor_8 = xor_5 ^ xor_6;

    // Level 4
    assign and_9 = and_8 & and_7;
    assign or_9 = or_8 | or_7;
    assign xor_9 = xor_8 ^ xor_7;

    // Output
    assign out_and = {and_9[7], and_9[6], and_9[5], and_9[4], and_9[3], and_9[2], and_9[1], and_9[0]};
    assign out_or = {or_9[7], or_9[6], or_9[5], or_9[4], or_9[3], or_9[2], or_9[1], or_9[0]};
    assign out_xor = {xor_9[7], xor_9[6], xor_9[5], xor_9[4], xor_9[3], xor_9[2], xor_9[1], xor_9[0]};
endmodule

