module SendChars(
    input [5:0] NumberOfChars,
    input Clock,
    input Reset,
    input Start,
    input tx_full,
    input uartClock,
    output reg [5:0] RAMAddress,
    output reg Transmitting,
    output reg write_to_uart
);

    localparam RAM_SIZE = 64;
    reg [7:0] RAM [0:RAM_SIZE-1];
    reg [5:0] char_count;
    reg [5:0] current_address;
    reg [5:0] next_address;
    reg [7:0] current_char;
    reg [7:0] next_char;
    reg [4:0] bit_count;
    reg [4:0] uart_bit_count;
    reg [6:0] uart_char;
    reg [4:0] uart_char_count;
    reg [5:0] uart_char_delay;
    reg [5:0] uart_bit_delay;
    reg [5:0] uart_delay_count;
    reg uart_started;
    reg uart_finished;

    always @(posedge Clock) begin
        if (Reset) begin
            RAMAddress <= 0;
            Transmitting <= 0;
            write_to_uart <= 0;
            char_count <= 0;
            current_address <= 0;
            next_address <= 0;
            current_char <= 0;
            next_char <= 0;
            bit_count <= 0;
            uart_bit_count <= 0;
            uart_char <= 0;
            uart_char_count <= 0;
            uart_char_delay <= 0;
            uart_bit_delay <= 0;
            uart_delay_count <= 0;
            uart_started <= 0;
            uart_finished <= 0;
        end else if (Start && !Transmitting && !tx_full && (char_count < NumberOfChars)) begin
            next_address <= current_address + 1;
            next_char <= RAM[current_address];
            char_count <= char_count + 1;
            Transmitting <= 1;
            write_to_uart <= 1;
        end else if (Transmitting) begin
            if (bit_count == 0) begin
                current_char <= next_char;
                current_address <= next_address;
                next_address <= current_address + 1;
                next_char <= RAM[current_address];
                uart_started <= 1;
            end
            if (uart_started) begin
                if (uart_char_delay == 0) begin
                    if (uart_bit_delay == 0) begin
                        if (uart_bit_count == 0) begin
                            uart_char <= current_char;
                            uart_char_count <= 0;
                            uart_bit_count <= 1;
                        end else if (uart_bit_count < 9) begin
                            write_to_uart <= uart_char[uart_bit_count-1];
                            uart_bit_count <= uart_bit_count + 1;
                            uart_bit_delay <= 21;
                        end else if (uart_bit_count == 9) begin
                            write_to_uart <= 1;
                            uart_bit_count <= 10;
                            uart_bit_delay <= 21;
                        end else begin
                            uart_char_count <= uart_char_count + 1;
                            if (uart_char_count == 2) begin
                                uart_started <= 0;
                                uart_finished <= 1;
                                bit_count <= 1;
                                uart_char_delay <= 3;
                            end else begin
                                uart_bit_count <= 0;
                                uart_bit_delay <= 21;
                            end
                        end
                    end else begin
                        uart_bit_delay <= uart_bit_delay - 1;
                    end
                end else begin
                    uart_char_delay <= uart_char_delay - 1;
                end
            end else if (uart_finished) begin
                uart_finished <= 0;
                if (char_count == NumberOfChars) begin
                    Transmitting <= 0;
                end
            end else begin
                bit_count <= bit_count + 1;
                if (bit_count == 16) begin
                    bit_count <= 0;
                    write_to_uart <= 0;
                end
            end
        end
    end

endmodule

