module gray_code (
    input [3:0] in,
    output reg [3:0] out
);
always @(*) begin
    out[3] = in[3];
    out[2] = in[3] ^ in[2];
    out[1] = in[2] ^ in[1];
    out[0] = in[1] ^ in[0];
end
endmodule

module barrel_shifter (
    input [3:0] data,
    input [1:0] shift_amount,
    output reg [3:0] result
);
always @(*) begin
    case (shift_amount)
        2'b00: result = data;
        2'b01: result = {data[2:0], data[3]};
        2'b10: result = {data[1:0], data[3:2]};
        2'b11: result = {data[0], data[3:1]};
    endcase
end
endmodule

