module shift_and_add_multiplier (
    input clk,
    input reset,
    input [3:0] a, b,
    output reg [7:0] product
);

reg [3:0] a_reg, b_reg;
reg [7:0] product_reg;

always @(posedge clk) begin
    if (reset) begin
        product_reg <= 8'b0;
        a_reg <= 4'b0;
        b_reg <= 4'b0;
    end else begin
        a_reg <= a;
        b_reg <= b;
        product_reg <= product_reg + (a_reg & 1'b1 ? b_reg : 0);
        a_reg <= a_reg >> 1;
        b_reg <= b_reg << 1;
    end
end

assign product = product_reg;

endmodule

module top_module (
    input clk,
    input reset,       // Synchronous active-high reset
    input [7:0] d,     // 8-bit input for the register
    input [3:0] a,     // 4-bit input for the first adder input
    input [3:0] b,     // 4-bit input for the second adder input
    output [7:0] q     // 8-bit output from the active module
);

    reg [7:0] q_reg;    // 8-bit register output
    wire [3:0] sum;     // 4-bit output from the adder
    wire select;        // Select input for the control logic

    // Instantiate the adder module
    adder_4bit adder_inst (
        .a(a),
        .b(b),
        .sum(sum)
    );

    // Control logic to select between the adder and register
    assign select = (sum >= 4'b1010);   // Enable register if sum >= 10

    // Instantiate the multiplexer and register modules
    mux_8bit mux_inst (
        .a(sum),
        .b(d),
        .select(select),
        .out(q_reg)
    );

    // Synchronous reset for the register
    always @(posedge clk) begin
        if (reset) begin
            q_reg <= 8'h34;     // Reset to 0x34
        end else begin
            q_reg <= mux_inst.out;
        end
    end

    // Output the final value of q
    assign q = q_reg;

endmodule

