module FSM (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 4; // number of input signals
parameter m = 2; // number of output signals
parameter s = 8; // number of states in the original FSM

// Define the state encoding
parameter [2:0] STATE_0 = 3'b000;
parameter [2:0] STATE_1 = 3'b001;
parameter [2:0] STATE_2 = 3'b010;
parameter [2:0] STATE_3 = 3'b011;
parameter [2:0] STATE_4 = 3'b100;
parameter [2:0] STATE_5 = 3'b101;
parameter [2:0] STATE_6 = 3'b110;
parameter [2:0] STATE_7 = 3'b111;

// Define the transition and output functions
function [2:0] next_state;
  input [n-1:0] in;
  input [2:0] current_state;
  begin
    case (current_state)
      STATE_0: next_state = (in == 4'b0000) ? STATE_0 : STATE_1;
      STATE_1: next_state = (in == 4'b0000) ? STATE_2 : STATE_3;
      STATE_2: next_state = (in == 4'b0001) ? STATE_4 : STATE_5;
      STATE_3: next_state = (in == 4'b0001) ? STATE_6 : STATE_7;
      STATE_4: next_state = STATE_0;
      STATE_5: next_state = STATE_0;
      STATE_6: next_state = STATE_0;
      STATE_7: next_state = STATE_0;
    endcase
  end
endfunction

function [m-1:0] output_signals;
  input [n-1:0] in;
  input [2:0] current_state;
  begin
    case (current_state)
      STATE_0: output_signals = {1'b0, 1'b0};
      STATE_1: output_signals = {1'b0, 1'b1};
      STATE_2: output_signals = {1'b1, 1'b0};
      STATE_3: output_signals = {1'b1, 1'b1};
      STATE_4: output_signals = {1'b0, 1'b0};
      STATE_5: output_signals = {1'b0, 1'b1};
      STATE_6: output_signals = {1'b1, 1'b0};
      STATE_7: output_signals = {1'b1, 1'b1};
    endcase
  end
endfunction

// Define the state register and combinational logic
reg [2:0] current_state, next_state;
always @ (in, current_state)
begin
  next_state = next_state(in, current_state);
end

always @ (next_state)
begin
  current_state = next_state;
end

assign out = output_signals(in, current_state);

endmodule

module COUNTER_MOD(  input [7:0] DATA, input NCCLR, input NCCKEN, input CCK,
                     input NCLOAD, input RCK, input [7:0] CLK_DIVIDER, output [7:0] QDATA);

    parameter CLK_DIVIDER_WIDTH = 8;

    reg [CLK_DIVIDER_WIDTH-1:0] _icounter;
    reg [7:0] _divider_counter;
    reg _count_enable;

    assign QDATA = _icounter;

    initial begin
        _icounter = {(CLK_DIVIDER_WIDTH){1'b0}};
        _divider_counter = {(8){1'b0}};
        _count_enable = 1'b0;
    end

    always @(posedge CCK, negedge NCCKEN, negedge NCCLR) begin
        if (~NCCKEN) begin
            if (~NCCLR) begin
                _icounter = 8'h0;
                _divider_counter = CLK_DIVIDER;
                _count_enable = 1'b0;
            end
            else if (~NCLOAD) begin
                _icounter = DATA;
                _divider_counter = CLK_DIVIDER;
                _count_enable = 1'b0;
            end
            else begin
                if (_count_enable) begin
                    if (_divider_counter == 8'h1) begin
                        _icounter =  _icounter + 1;
                        _divider_counter = CLK_DIVIDER;
                    end
                    else begin
                        _divider_counter = _divider_counter - 1;
                    end
                end
                else begin
                    _divider_counter = CLK_DIVIDER;
                    _count_enable = 1'b1;
                end
            end
        end
    end

endmodule

