module DigitalFilter (
    input clk,
    input rst,
    input en,
    input signed [15:0] dataIn,
    output signed [15:0] dataOut
);

parameter WIDTH = 16;
parameter INT_BITS = 8;
parameter FRAC_BITS = 8;

reg signed [WIDTH-1:0] x1, x2, y1, y2;
reg signed [INT_BITS+FRAC_BITS-1:0] acc0, acc1, acc2;

assign dataOut = acc0 >> FRAC_BITS;

always @(posedge clk) begin
    if (rst) begin
        x1 <= 'd0;
        x2 <= 'd0;
        y1 <= 'd0;
        y2 <= 'd0;
        acc0 <= 'd0;
        acc1 <= 'd0;
        acc2 <= 'd0;
    end
    else if (en) begin
        x2 <= x1;
        x1 <= dataIn;
        y2 <= y1;
        y1 <= dataOut;

        acc0 <= (b0 * x1 + b1 * x2 + b2 * acc1 - a1 * y1 - a2 * y2) << FRAC_BITS;
        acc1 <= acc0;
        acc2 <= acc1;
    end
end

parameter b0 = 256'd128;
parameter b1 = -256'd64;
parameter b2 = 256'd32;
parameter a1 = 256'd128;
parameter a2 = -256'd64;

endmodule

module top_module (
    input clk,
    input [3:0] A,
    input [3:0] B,
    input Cin,
    input rst,
    output [3:0] S,
    output V
);

reg [7:0] mult_out;
wire [3:0] adder_out;
wire adder_overflow;

// Instantiate modules
unsigned_multiplier mult(.clk(clk), .A(A), .B(B), .P(mult_out));
ripple_carry_adder adder(.A(mult_out[3:0]), .B(mult_out[7:4]), .Cin(Cin), .S(adder_out), .V(adder_overflow));
bitwise_xor xor(.A(adder_out), .B(adder_overflow), .S(S));

// Reset logic
always @(posedge clk) begin
    if (rst) begin
        S <= 4'b0;
        V <= 1'b0;
    end else begin
        S <= S;
        V <= V;
    end
end

endmodule

module Filter (
    input wire[31:0] cfg_ar_addr,
    input wire[2:0] cfg_ar_prot,
    output wire cfg_ar_ready,
    input wire cfg_ar_valid,
    input wire[31:0] cfg_aw_addr,
    input wire[2:0] cfg_aw_prot,
    output wire cfg_aw_ready,
    input wire cfg_aw_valid,
    input wire cfg_b_ready,
    output wire[1:0] cfg_b_resp,
    output wire cfg_b_valid,
    output wire[63:0] cfg_r_data,
    input wire cfg_r_ready,
    output wire[1:0] cfg_r_resp,
    output wire cfg_r_valid,
    input wire[63:0] cfg_w_data,
    output wire cfg_w_ready,
    input wire[7:0] cfg_w_strb,
    input wire cfg_w_valid,
    input wire[63:0] din_data,
    input wire din_last,
    output wire din_ready,
    input wire din_valid,
    output wire[63:0] dout_data,
    output wire dout_last,
    input wire dout_ready,
    output wire dout_valid,
    input wire[63:0] headers_data,
    input wire headers_last,
    output wire headers_ready,
    input wire headers_valid,
    input wire[63:0] patternMatch_data,
    input wire patternMatch_last,
    output wire patternMatch_ready,
    input wire patternMatch_valid
);
    reg [63:0] headers_buf;
    reg [63:0] patternMatch_buf;
    reg [63:0] din_buf;
    reg [63:0] dout_buf;
    reg [63:0] cfg_reg;
    reg [2:0] cfg_state;
    reg cfg_write;
    reg cfg_read;
    reg [31:0] cfg_addr;
    reg [63:0] cfg_data;
    reg [7:0] cfg_strb;
    reg cfg_valid;
    reg cfg_ready;

    assign cfg_ar_ready = 1'b1;
    assign cfg_aw_ready = 1'b1;
    assign cfg_b_valid = 1'b0;
    assign cfg_r_valid = 1'b0;
    assign cfg_w_ready = 1'b0;
    assign din_ready = 1'b0;
    assign headers_ready = 1'b0;
    assign patternMatch_ready = 1'b0;

    always @(*) begin
        case(cfg_state)
            3'b000: begin
                cfg_ready = 1'b1;
                cfg_b_resp = 2'b00;
                if(cfg_ar_valid) begin
                    cfg_addr = cfg_ar_addr;
                    cfg_read = 1'b1;
                    cfg_state = 3'b001;
                end else if(cfg_aw_valid) begin
                    cfg_addr = cfg_aw_addr;
                    cfg_data = cfg_w_data;
                    cfg_strb = cfg_w_strb;
                    cfg_write = 1'b1;
                    cfg_state = 3'b010;
                end
            end
            3'b001: begin
                cfg_ready = 1'b0;
                cfg_b_resp = 2'b00;
                if(cfg_r_ready) begin
                    cfg_r_data = cfg_reg;
                    cfg_r_resp = 2'b00;
                    cfg_r_valid = 1'b1;
                    cfg_read = 1'b0;
                    cfg_state = 3'b000;
                end
            end
            3'b010: begin
                cfg_ready = 1'b0;
                cfg_b_resp = 2'b00;
                if(cfg_w_ready) begin
                    cfg_reg[cfg_strb] <= cfg_data[cfg_strb];
                    cfg_write = 1'b0;
                    cfg_state = 3'b000;
                end
            end
        endcase
    end

    always @(posedge clk) begin
        if(reset) begin
            headers_buf <= 64'b0;
            patternMatch_buf <= 64'b0;
            din_buf <= 64'b0;
            dout_buf <= 64'b0;
            cfg_reg <= 64'b0;
            cfg_state <= 3'b000;
            cfg_write <= 1'b0;
            cfg_read <= 1'b0;
            cfg_addr <= 32'b0;
            cfg_data <= 64'b0;
            cfg_strb <= 8'b0;
            cfg_valid <= 1'b0;
            cfg_ready <= 1'b0;
        end else begin
            if(cfg_write) begin
                cfg_reg[cfg_strb] <= cfg_data[cfg_strb];
            end else if(cfg_read) begin
                case(cfg_addr)
                    32'h00000000: cfg_reg <= {32'h00000000, 32'h00000000};
                    32'h00000004: cfg_reg <= {32'h00000001, 32'h00000000};
                    32'h00000008: cfg_reg <= {32'h00000002, 32'h00000000};
                    32'h0000000C: cfg_reg <= {32'h00000003, 32'h00000000};
                    32'h00000010: cfg_reg <= {32'h00000000, 32'h00000001};
                    32'h00000014: cfg_reg <= {32'h00000001, 32'h00000001};
                    32'h00000018: cfg_reg <= {32'h00000002, 32'h00000001};
                    32'h0000001C: cfg_reg <= {32'h00000003, 32'h00000001};
                    default: cfg_reg <= 64'b0;
                endcase
            end

            if(cfg_aw_valid) begin
                case(cfg_aw_addr)
                    32'h00000000: begin
                        cfg_valid <= 1'b1;
                        cfg_state <= 3'b000;
                    end
                    32'h00000004: begin
                        patternMatch_buf <= patternMatch_data;
                        cfg_valid <= 1'b1;
                        cfg_state <= 3'b000;
                    end
                    32'h00000008: begin
                        headers_buf <= headers_data;
                        cfg_valid <= 1'b1;
                        cfg_state <= 3'b000;
                    end
                    32'h0000000C: begin
                        cfg_valid <= 1'b1;
                        cfg_state <= 3'b000;
                    end
                    32'h00000010: begin
                        din_buf <= din_data;
                        cfg_valid <= 1'b1;
                        cfg_state <= 3'b000;
                    end
                    32'h00000014: begin
                        dout_buf <= din_buf;
                        cfg_valid <= 1'b1;
                        cfg_state <= 3'b000;
                    end
                    32'h00000018: begin
                        dout_buf <= headers_buf;
                        cfg_valid <= 1'b1;
                        cfg_state <= 3'b000;
                    end
                    32'h0000001C: begin
                        dout_buf <= patternMatch_buf;
                        cfg_valid <= 1'b1;
                        cfg_state <= 3'b000;
                    end
                endcase
            end else if(din_valid) begin
                if(cfg_reg[0]) begin
                    if(din_data == patternMatch_buf) begin
                        headers_ready <= 1'b1;
                        headers_data <= headers_buf;
                    end
                end else begin
                    dout_valid <= 1'b1;
                    dout_data <= dout_buf;
                    dout_last <= din_last;
                end
            end

            if(cfg_valid && cfg_ready) begin
                cfg_valid <= 1'b0;
                cfg_state <= 3'b000;
                if(cfg_write) begin
                    cfg_w_ready <= 1'b1;
                end else if(cfg_read) begin
                    cfg_r_ready <= 1'b1;
                end
            end

            if(headers_valid && headers_ready) begin
                headers_ready <= 1'b0;
            end

            if(dout_valid && dout_ready) begin
                dout_valid <= 1'b0;
            end
        end
    end
endmodule

