module single_cdc (
    input rst_src,
    input rst_dest,
    input src_clk,
    input dest_clk,
    input src_in,
    output dest_out
);

    (* XPM_CDC = "SINGLE" *) wire [1:0] syncstages_ff;
    wire src_in_sync;
    wire rst_sync_src;
    wire rst_sync_dest;

    assign dest_out = syncstages_ff[1];

    (* ASYNC_REG *)
    (* XPM_CDC = "SINGLE" *)
    FDRE #(.INIT(1'b0)) syncstages_ff_reg_0 (
        .C(dest_clk),
        .CE(1'b1),
        .D(src_in),
        .Q(syncstages_ff[0]),
        .R(rst_sync_dest)
    );

    (* ASYNC_REG *)
    (* XPM_CDC = "SINGLE" *)
    FDRE #(.INIT(1'b0)) syncstages_ff_reg_1 (
        .C(dest_clk),
        .CE(1'b1),
        .D(syncstages_ff[0]),
        .Q(syncstages_ff[1]),
        .R(rst_sync_dest)
    );

    (* ASYNC_REG *)
    (* XPM_CDC = "SINGLE" *)
    FDRE #(.INIT(1'b0)) src_in_sync_reg (
        .C(src_clk),
        .CE(1'b1),
        .D(src_in),
        .Q(src_in_sync),
        .R(rst_sync_src)
    );

    (* ASYNC_REG *)
    (* XPM_CDC = "SINGLE" *)
    FDRE #(.INIT(1'b0)) rst_sync_src_reg (
        .C(src_clk),
        .CE(1'b1),
        .D(rst_src),
        .Q(rst_sync_src),
        .R(1'b0)
    );

    (* ASYNC_REG *)
    (* XPM_CDC = "SINGLE" *)
    FDRE #(.INIT(1'b0)) rst_sync_dest_reg (
        .C(dest_clk),
        .CE(1'b1),
        .D(rst_sync_src),
        .Q(rst_sync_dest),
        .R(1'b0)
    );

    assign rst_sync_src = 1'b0;
    assign rst_sync_dest = 1'b0;

endmodule

module d_ff_rst (
    input CLK,
    input D,
    input RESET_B,
    output Q,
    output Q_N
);
    wire D_N;
    wire Q_next;
    wire Q_N_next;

    // Invert the D input
    assign D_N = ~D;

    // Implement the reset functionality
    assign Q = RESET_B ? 1'b0 : Q_next;
    assign Q_N = RESET_B ? 1'b1 : Q_N_next;

    // Implement the D flip-flop
    nand gate1 (Q_next, CLK, D_N, Q_N_next);
    nand gate2 (Q_N_next, CLK, D, Q_next);

endmodule

