module signed_mult_shift(
    input signed [3:0] A,
    input signed [3:0] B,
    input [3:0] shift,
    input dir,
    output reg [15:0] out
);

    wire signed [7:0] mult_result;
    wire [3:0] shift_amt;

    // Signed multiplication module
    signed_mult mult(
        .A(A),
        .B(B),
        .out(mult_result)
    );

    // Determine shift amount based on direction input
    assign shift_amt = (dir == 1) ? shift : -shift;

    // Barrel shifter module
    barrel_shifter shift_reg(
        .in(mult_result),
        .shift_amt(shift_amt),
        .out(out)
    );

    always @(*) begin
        // Truncate most significant bits if multiplication result is greater than 15 bits
        if (mult_result > 15'h7FFF || mult_result < -15'h8000) begin
            out = (mult_result[7:0] << shift_amt);
        end
    end

endmodule

