module ALU(X, Y, Z, Func, Zero, Sign, Overflow, Carry, ALU_clk, Update, Zsoc, Condition_update);
  input [7:0] X;
  input [7:0] Y;
  output [7:0] Z;
  input [2:0] Func;
  input ALU_clk, Update, Condition_update;
  output Zero, Sign, Overflow, Carry;
  input [7:0] Zsoc;
  reg [7:0] Z;
  reg Sign, Carry;
  wire [8:0] product;
  wire [15:0] quotient;
  wire [8:0] dividend, divisor;
  wire [7:0] remainder;
  wire [7:0] X_neg, Y_neg;
  wire [8:0] X_abs, Y_abs;
  wire [7:0] result;
  wire [8:0] X_plus_Y, X_minus_Y;
  wire [7:0] X_and_Y, X_or_Y, X_xor_Y;
  wire [2:0] shift_amount;
  wire [8:0] shifted_value;

  // Calculate Z based on Func
  always @ (X, Y, Func) begin
    case(Func)
      3'b000: begin // Z = X + Y (with Carry output)
        { Carry, Z } = X + Y;
      end
      3'b001: begin // Z = X - Y (with Carry output)
        { Carry, Z } = X - Y;
      end
      3'b010: begin // Z = X * Y (with Carry output)
        { Carry, product } = X * Y;
        Z = product[7:0];
        Overflow = product[8];
      end
      3'b011: begin // Z = X / Y
        dividend = X;
        divisor = Y;
        if (X[7] == 1) begin // If X is negative, convert to positive
          X_neg = ~X + 1;
          X_abs = X_neg;
        end else begin
          X_abs = X;
        end
        if (Y[7] == 1) begin // If Y is negative, convert to positive
          Y_neg = ~Y + 1;
          Y_abs = Y_neg;
        end else begin
          Y_abs = Y;
        end
        if (Y_abs == 0) begin // Divide by zero
          Z = 8'hFF;
        end else begin
          { quotient, remainder } = X_abs / Y_abs;
          if (X[7] == 1 && Y[7] == 0) begin // If X is negative and Y is positive, convert quotient to negative
            result = ~quotient + 1;
          end else if (X[7] == 0 && Y[7] == 1) begin // If X is positive and Y is negative, convert quotient to negative
            result = ~quotient + 1;
          end else begin
            result = quotient;
          end
          if (X[7] == 1) begin // If X is negative, convert remainder to negative
            remainder = ~remainder + 1;
          end
          Z = result;
          Overflow = 0;
        end
      end
      3'b100: begin // Z = X & Y
        Z = X & Y;
      end
      3'b101: begin // Z = X | Y
        Z = X | Y;
      end
      3'b110: begin // Z = ~Y
        Z = ~Y;
      end
      3'b111: begin // Z = X ^ Y
        Z = X ^ Y;
      end
    endcase
  end

  // Update Zero and Sign flags
  always @(posedge ALU_clk) begin
    if (Update == 1'b1) begin
      if (Z == 8'h00) begin
        Zero = 1;
      end else begin
        Zero = 0;
      end
      Sign = Z[7];
    end
  end

  // Update all flags
  always @(posedge ALU_clk) begin
    if (Condition_update == 1'b1) begin
      Zero = Zsoc[3];
      Sign = Zsoc[2];
      Overflow = Zsoc[1];
      Carry = Zsoc[0];
    end
  end

  // Calculate X + Y (with Carry output)
  assign { Carry, X_plus_Y } = X + Y;

  // Calculate X - Y (with Carry output)
  assign { Carry, X_minus_Y } = X - Y;

  // Calculate X & Y
  assign X_and_Y = X & Y;

  // Calculate X | Y
  assign X_or_Y = X | Y;

  // Calculate X ^ Y
  assign X_xor_Y = X ^ Y;

  // Calculate Z = X * Y (with Carry output)
  assign { Carry, product } = X * Y;
  assign Z = product[7:0];
  assign Overflow = product[8];

  // Calculate Z = X / Y
  assign dividend = X;
  assign divisor = Y;
  assign X_neg = ~X + 1;
  assign Y_neg = ~Y + 1;
  assign X_abs = (X[7] == 1) ? X_neg : X;
  assign Y_abs = (Y[7] == 1) ? Y_neg : Y;
  assign shift_amount = 8'h07 - $clog2(Y_abs);
  assign shifted_value = { Y_abs, { shift_amount{1'b0} } };
  assign { quotient, remainder } = X_abs / shifted_value;
  assign result = (X[7] == 1 && Y[7] == 0) ? ~quotient + 1 : ((X[7] == 0 && Y[7] == 1) ? ~quotient + 1 : quotient);
  assign remainder = (X[7] == 1) ? ~remainder + 1 : remainder;
  assign Z = result;
  assign Overflow = 0;

endmodule

