module top_module (
    input clk,
    input reset,
    input slowena,
    input select, // Select input for the logical operation
    input [31:0] A,
    input [31:0] B,
    output [3:0] q // 4-bit output from the functional module
);

    // 32-bit carry select adder
    wire [15:0] c0, c1, s0, s1;
    wire co;
    csa_16bit csa0(.a(A[15:0]), .b(B[15:0]), .cin(1'b0), .c(c0), .s(s0));
    csa_16bit csa1(.a(A[31:16]), .b(B[31:16]), .cin(c0[15]), .c(c1), .s(s1));
    assign co = c1[15];
    assign q[3] = co;
    mux_2to1 mux(.a(s1), .b(s0), .sel(co), .y(q[2:0]));

    // 4-bit Johnson counter
    reg [3:0] jc;
    always @(posedge clk, negedge reset) begin
        if (!reset) begin
            jc <= 4'b0000;
        end else if (slowena) begin
            jc <= jc + 1;
            if (jc == 4'b1010) begin
                jc <= 4'b0000;
            end
        end
    end

    // Functional module
    reg [3:0] f_out;
    always @(*) begin
        case (select)
            2'b00: f_out = jc & q;
            2'b01: f_out = jc | q;
            2'b10: f_out = jc ^ q;
            2'b11: f_out = ~(jc ^ q);
        endcase
    end

    assign q = f_out;

endmodule

module top_module(
    input clk,
    input reset,
    input [31:0] a,
    input [31:0] b,
    input a_in,
    input b_in,
    output [31:0] sum,
    output nor_out,
    output [31:0] final_out
);

    // NOR gate
    wire nor_in1 = a_in;
    wire nor_in2 = b_in;
    wire nor_out_wire;
    nor nor_gate(nor_out_wire, nor_in1, nor_in2);
    assign nor_out = ~nor_out_wire;

    // 32-bit adder
    wire [7:0] a_chunk [3:0];
    wire [7:0] b_chunk [3:0];
    wire [7:0] sum_chunk [3:0];
    wire [7:0] carry [3:0];

    // Break down 32-bit input into four 8-bit chunks
    assign a_chunk[0] = a[7:0];
    assign a_chunk[1] = a[15:8];
    assign a_chunk[2] = a[23:16];
    assign a_chunk[3] = a[31:24];

    assign b_chunk[0] = b[7:0];
    assign b_chunk[1] = b[15:8];
    assign b_chunk[2] = b[23:16];
    assign b_chunk[3] = b[31:24];

    // Use 8-bit adders to add the corresponding chunks together
    adder_8bit adder0(a_chunk[0], b_chunk[0], sum_chunk[0], carry[0]);
    adder_8bit adder1(a_chunk[1], b_chunk[1], sum_chunk[1], carry[1]);
    adder_8bit adder2(a_chunk[2], b_chunk[2], sum_chunk[2], carry[2]);
    adder_8bit adder3(a_chunk[3], b_chunk[3], sum_chunk[3], carry[3]);

    // Use 2-to-1 multiplexers to select the correct carry bit between each 8-bit addition
    wire [3:0] mux_sel;
    assign mux_sel[0] = 1'b0;
    assign mux_sel[1] = carry[0];
    assign mux_sel[2] = carry[1];
    assign mux_sel[3] = carry[2];

    mux_2to1 mux0(carry[0], carry[1], mux_sel[0], carry[4]);
    mux_2to1 mux1(carry[2], carry[3], mux_sel[1], carry[5]);
    mux_2to1 mux2(carry[4], carry[5], mux_sel[2], carry[6]);

    // Final carry bit
    assign carry[7] = mux_sel[3] ? carry[3] : carry[6];

    // Combine the 8-bit chunks to get the final sum
    assign sum = {carry[7], sum_chunk[3], sum_chunk[2], sum_chunk[1], sum_chunk[0]};

    // Functional module
    wire [31:0] xor_out;
    xor xor_gate(xor_out, nor_out_wire, sum);
    assign final_out = xor_out;

endmodule

// 8-bit adder module
module adder_8bit(
    input [7:0] a,
    input [7:0] b,
    output [7:0] sum,
    output carry_out
);

    wire [7:0] sum_wire;
    wire carry_wire;

    assign sum_wire = a + b;
    assign carry_out = sum_wire[8];
    assign sum = sum_wire[7:0];

endmodule

