module robohand(
    input reset,
    input advance,
    input [9:0] ball_y,
    output reg [9:0] paddle_y
);

    parameter PADDLESIZE = 10;
    parameter SCREENHEIGHT = 480;
    parameter INCREMENT = 1;

    reg paddleDir;
    reg [9:0] ptop;
    reg [9:0] pbot;

    function [9:0] paddlelimiter;
        input [9:0] py;
        begin
            if (py < PADDLESIZE/2) 
                paddlelimiter = PADDLESIZE/2;
            else if (py > SCREENHEIGHT-PADDLESIZE/2)
                paddlelimiter = SCREENHEIGHT-PADDLESIZE/2;
            else
                paddlelimiter = py;
        end
    endfunction

    always @(negedge advance or posedge reset) begin
        if (reset) begin
            paddle_y <= SCREENHEIGHT/2;
        end
        else begin
            if (ball_y < ptop || ball_y > pbot) begin
                if (paddleDir == 1'b0)
                    paddle_y <= paddlelimiter(paddle_y + INCREMENT);
                else
                    paddle_y <= paddlelimiter(paddle_y - INCREMENT);
            end
        end
    end

    always @(posedge advance) begin
        ptop <= paddle_y - PADDLESIZE/2;
        pbot <= paddle_y + PADDLESIZE/2;
        paddleDir <= ball_y < paddle_y;
    end

endmodule

module nand_gate_output();

    // Inputs are registered
    reg A_N;
    reg B_N;
    reg C;
    reg D;
    reg VPWR;
    reg VGND;
    reg VPB;
    reg VNB;

    // Outputs are wires
    wire Y;

    sky130_fd_sc_hd__nand4bb dut (.A_N(A_N), .B_N(B_N), .C(C), .D(D), .VPWR(VPWR), .VGND(VGND), .VPB(VPB), .VNB(VNB), .Y(Y));

    integer count = 0;

    always @(A_N or B_N or C or D or VPWR or VGND or VPB or VNB)
    begin
        if (A_N == 1'bx || B_N == 1'bx || C == 1'bx || D == 1'bx || VPWR == 1'bx || VGND == 1'bx || VPB == 1'bx || VNB == 1'bx)
        begin
            Y = 1'bx;
        end
        else
        begin
            if (count >= 32 && count <= 39)
            begin
                Y = 1'b1;
            end
            else
            begin
                Y = ~(A_N & B_N & C & D);
            end
        end

        if (A_N == 1'b0 && B_N == 1'b0 && C == 1'b0 && D == 1'b0 && VPWR == 1'b0 && VGND == 1'b0 && VPB == 1'b0 && VNB == 1'b0)
        begin
            count = 0;
        end
        else
        begin
            count = count + 1;
        end
    end

