module alu(input wire [31:0] srca, input wire [31:0] srcb, input wire [1:0] alucontrol, output reg [31:0] aluresult, output reg [3:0] aluflags);

  reg [31:0] sum;
  reg cout;
  wire [31:0] srcbc = ~srcb;
  wire xa;

  // Calculate XOR of MSB of srca, srcb, and alucontrol[0]
  xor3 aa(alucontrol[0], srca[31], srcb[31], xa);

  always @(*) begin
    // Perform addition or subtraction based on value of alucontrol[0]
    if (alucontrol[0]) begin
      {cout, sum} = srca + srcbc + 1;
    end else begin
      {cout, sum} = srca + srcb;
    end

    // Set aluresult based on value of alucontrol
    case (alucontrol)
      2'b00: aluresult = sum;
      2'b01: aluresult = sum;
      2'b10: aluresult = srca & srcb;
      2'b11: aluresult = srca | srcb;
    endcase

    // Set aluflags
    aluflags[3:2] = {aluresult[31], aluresult == 0}; // Set n and z flags
    aluflags[1] = cout & ~alucontrol[1]; // Set c flag
    aluflags[0] = xa & (~alucontrol[1] & (aluresult[31] ^ srca[31])); // Set v flag
  end

endmodule

module add_sub_shift(
    input clk,
    input reset, // Synchronous active-high reset
    input [3:0] A, // 4-bit input A for the adder-subtractor
    input [3:0] B, // 4-bit input B for the adder-subtractor
    input SUB, // 1-bit input SUB for the adder-subtractor
    input [2:0] shift_in, // 3-bit input for the shift register
    input load, // Load input for the shift register
    output [2:0] shift_out, // 3-bit output from the shift register
    output [3:0] SUM // 4-bit output from the adder-subtractor
);

reg [3:0] A_reg, B_reg, SUM_reg;
reg SUB_reg;
wire [3:0] A_B;
wire [3:0] A_minus_B;
wire [3:0] shifted_out;
reg [2:0] shift_reg;

// Adder-Subtractor
assign A_B = A + B;
assign A_minus_B = A - B;
always @ (posedge clk) begin
    if (reset) begin
        A_reg <= 4'b0;
        B_reg <= 4'b0;
        SUM_reg <= 4'b0;
        SUB_reg <= 1'b0;
    end else begin
        A_reg <= A;
        B_reg <= B;
        SUB_reg <= SUB;
        if (SUB_reg) begin
            SUM_reg <= A_minus_B;
        end else begin
            SUM_reg <= A_B;
        end
    end
end
assign SUM = SUM_reg;

// Shift Register
always @ (posedge clk) begin
    if (reset) begin
        shift_reg <= 3'b0;
    end else begin
        if (load) begin
            shift_reg <= shift_in;
        end else begin
            shift_reg <= {shift_reg[1:0], 1'b0};
        end
    end
end
assign shift_out = shift_reg;

// Additional Functional Module
assign shifted_out = {shift_reg[1:0], 1'b0};
assign SUM_shifted_OR = SUM_reg | shifted_out;

endmodule

module wb_ram #
(
    parameter DATA_WIDTH = 32,              // width of data bus in bits (8, 16, 32, or 64)
    parameter ADDR_WIDTH = 16,              // width of address bus in bits
    parameter SELECT_WIDTH = (DATA_WIDTH/8) // width of word select bus (1, 2, 4, or 8)
)
(
    input  wire                    clk,

    input  wire [ADDR_WIDTH-1:0]   adr_i,   // ADR_I() address
    input  wire [DATA_WIDTH-1:0]   dat_i,   // DAT_I() data in
    output wire [DATA_WIDTH-1:0]   dat_o,   // DAT_O() data out
    input  wire                    we_i,    // WE_I write enable input
    input  wire [SELECT_WIDTH-1:0] sel_i,   // SEL_I() select input
    input  wire                    stb_i,   // STB_I strobe input
    output wire                    ack_o,   // ACK_O acknowledge output
    input  wire                    cyc_i    // CYC_I cycle input
);

// for interfaces that are more than one word wide, disable address lines
parameter VALID_ADDR_WIDTH = ADDR_WIDTH - $clog2(SELECT_WIDTH);
// width of data port in words (1, 2, 4, or 8)
parameter WORD_WIDTH = SELECT_WIDTH;
// size of words (8, 16, 32, or 64 bits)
parameter WORD_SIZE = DATA_WIDTH/WORD_WIDTH;

reg [DATA_WIDTH-1:0] dat_o_reg = {DATA_WIDTH{1'b0}};
reg ack_o_reg = 1'b0;

// (* RAM_STYLE="BLOCK" *)
reg [DATA_WIDTH-1:0] mem[(2**VALID_ADDR_WIDTH)-1:0];

wire [VALID_ADDR_WIDTH-1:0] adr_i_valid = adr_i >> (ADDR_WIDTH - VALID_ADDR_WIDTH);

assign dat_o = dat_o_reg;
assign ack_o = ack_o_reg;

integer i, j;

initial begin
    // two nested loops for smaller number of iterations per loop
    // workaround for synthesizer complaints about large loop counts
    for (i = 0; i < 2**VALID_ADDR_WIDTH; i = i + 2**(VALID_ADDR_WIDTH/2)) begin
        for (j = i; j < i + 2**(VALID_ADDR_WIDTH/2); j = j + 1) begin
            mem[j] = 0;
        end
    end
end

always @(posedge clk) begin
    ack_o_reg <= 1'b0;
    for (i = 0; i < WORD_WIDTH; i = i + 1) begin
        if (cyc_i & stb_i & ~ack_o) begin
            if (we_i & sel_i[i]) begin
                mem[adr_i_valid][WORD_SIZE*i +: WORD_SIZE] <= dat_i[WORD_SIZE*i +: WORD_SIZE];
            end
            dat_o_reg[WORD_SIZE*i +: WORD_SIZE] <= mem[adr_i_valid][WORD_SIZE*i +: WORD_SIZE];
            ack_o_reg <= 1'b1;
        end
    end
end

endmodule

module digital_circuit(D, VPWR, VGND, VPB, VNB, Q);

    input D, VPWR, VGND, VPB, VNB;
