    assign D_not = ~D;
    assign VPWR_not = ~VPWR;
    assign VGND_not = ~VGND;
    assign VPB_not = ~VPB;
    assign VNB_not = ~VNB;

    assign A = D_not & VPWR_not & VGND_not & VPB_not & VNB_not;
    assign B = D_not & VPWR_not & VGND_not & VPB_not & VNB;
    assign C = D_not & VPWR_not & VGND_not & VPB & VNB_not;

    assign Q = (A | B) & C;

endmodule

module crc_generator (
  input [n-1:0] data_in,
  input reset,
  output [k-1:0] crc_out
);

parameter n = 8; // number of data bits
parameter k = 16; // number of CRC bits
parameter polynomial = 16'h1021; // CRC-CCITT polynomial

reg [k-1:0] crc_reg;
reg [n-1:0] data_reg;

always @(posedge clk) begin
  if (reset) begin
    crc_reg <= 0;
    data_reg <= 0;
  end else begin
    data_reg <= data_in;
    for (i = 0; i < n; i = i + 1) begin
      crc_reg <= crc_reg ^ (data_reg >> (n-1-i));
      if (crc_reg[k-1]) begin
        crc_reg <= crc_reg ^ (polynomial << (k-1));
      end
      crc_reg <= crc_reg << 1;
    end
  end
end

assign crc_out = crc_reg;

endmodule

module crc_checker (
