  input reset,
  output crc_ok
);

parameter n = 8; // number of data bits
parameter k = 16; // number of CRC bits
parameter polynomial = 16'h1021; // CRC-CCITT polynomial

reg [k-1:0] crc_reg;
reg [n-1:0] data_reg;

always @(posedge clk) begin
  if (reset) begin
    crc_reg <= 0;
    data_reg <= 0;
  end else begin
    data_reg <= data_in;
    for (i = 0; i < n; i = i + 1) begin
      crc_reg <= crc_reg ^ (data_reg >> (n-1-i));
      if (crc_reg[k-1]) begin
        crc_reg <= crc_reg ^ (polynomial << (k-1));
      end
      crc_reg <= crc_reg << 1;
    end
    if (crc_reg == crc_in) begin
      crc_ok <= 1;
    end else begin
      crc_ok <= 0;
    end
  end
end

endmodule

