module mux_256to1 (
    input [1023:0] in,
    input [7:0] sel,
    output [3:0] out
);

    wire [255:0] level1_out;
    wire [127:0] level2_out;
    wire [63:0] level3_out;
    wire [31:0] level4_out;
    wire [15:0] level5_out;
    wire [7:0] level6_out;
    wire [3:0] level7_out;

    // Level 1
    genvar i;
    generate
        for (i = 0; i < 256; i = i + 2) begin : level1
            assign level1_out[i/2] = (sel[7] == 0) ? in[i*4+3:i*4] : in[(i+1)*4+3:(i+1)*4];
        end
    endgenerate

    // Level 2
    generate
        for (i = 0; i < 128; i = i + 2) begin : level2
            assign level2_out[i/2] = (sel[6] == 0) ? level1_out[i*2+1:i*2] : level1_out[(i+1)*2+1:(i+1)*2];
        end
    endgenerate

    // Level 3
    generate
        for (i = 0; i < 64; i = i + 2) begin : level3
            assign level3_out[i/2] = (sel[5] == 0) ? level2_out[i*2+1:i*2] : level2_out[(i+1)*2+1:(i+1)*2];
        end
    endgenerate

    // Level 4
    generate
        for (i = 0; i < 32; i = i + 2) begin : level4
            assign level4_out[i/2] = (sel[4] == 0) ? level3_out[i*2+1:i*2] : level3_out[(i+1)*2+1:(i+1)*2];
        end
    endgenerate

    // Level 5
    generate
        for (i = 0; i < 16; i = i + 2) begin : level5
            assign level5_out[i/2] = (sel[3] == 0) ? level4_out[i*2+1:i*2] : level4_out[(i+1)*2+1:(i+1)*2];
        end
    endgenerate

    // Level 6
    generate
        for (i = 0; i < 8; i = i + 2) begin : level6
            assign level6_out[i/2] = (sel[2] == 0) ? level5_out[i*2+1:i*2] : level5_out[(i+1)*2+1:(i+1)*2];
        end
    endgenerate

    // Level 7
    generate
        for (i = 0; i < 4; i = i + 2) begin : level7
            assign level7_out[i/2] = (sel[1] == 0) ? level6_out[i*2+1:i*2] : level6_out[(i+1)*2+1:(i+1)*2];
        end
    endgenerate

    // Level 8
    assign out = (sel[0] == 0) ? level7_out[1:0] : level7_out[3:2];

endmodule

module fp_convert_altpriority_encoder_3v7 (
    input [2:0] data,
    output [1:0] q
);

    wire [0:0] q0;
    wire [0:0] q1;
    wire [0:0] q2;
    wire [0:0] q3;

    assign q0 = ~|data;
    assign q1 = ~|data[2:1];
    assign q2 = ~|data[2:0];
    assign q3 = ~|data[3:1];

    assign q[0] = (~q0 & ~q1 & q2) | (~q0 & q1 & q3) | (q0 & ~q1 & q3) | (q0 & q1 & q2);
    assign q[1] = (~q0 & q1 & q2) | (q0 & ~q1 & q2) | (q0 & q1 & q3) | (q0 & q1 & q2);

endmodule

module fp_convert_altpriority_encoder_3e8 (
    input [2:0] data,
    output [0:0] q,
    output [0:0] zero
);

    wire [1:0] q0;
    wire [1:0] q1;
    wire [1:0] q2;
    wire [1:0] q3;

    fp_convert_altpriority_encoder_3v7 encoder0(
        .data(data),
        .q(q0)
    );

    fp_convert_altpriority_encoder_3v7 encoder1(
        .data({data[1:0], data[2]}),
        .q(q1)
    );

    fp_convert_altpriority_encoder_3v7 encoder2(
        .data({data[0], data[3:1]}),
        .q(q2)
    );

    fp_convert_altpriority_encoder_3v7 encoder3(
        .data(data[2:0]),
        .q(q3)
    );

    assign zero = ~(|data);
    assign q[0] = (~zero & q2[1]) | (zero & q0[1]);
    assign q[1] = (~zero & q1[1]) | (zero & q3[1]);

endmodule

module fp_convert_altpriority_encoder_6v7 (
    input [3:0] data,
    output [1:0] q
);

    wire [0:0] wire_altpriority_encoder21_q;
    wire [0:0] wire_altpriority_encoder22_q;
    wire wire_altpriority_encoder22_zero;

    fp_convert_altpriority_encoder_3v7 altpriority_encoder21(
        .data(data[1:0]),
        .q(wire_altpriority_encoder21_q)
    );

    fp_convert_altpriority_encoder_3e8 altpriority_encoder22(
        .data(data[3:2]),
        .q(wire_altpriority_encoder22_q),
        .zero(wire_altpriority_encoder22_zero)
    );

    assign q = {(~wire_altpriority_encoder22_zero), ((wire_altpriority_encoder22_zero & wire_altpriority_encoder21_q) | ((~wire_altpriority_encoder22_zero) & wire_altpriority_encoder22_q))};

endmodule

