module Rs232Rx(input clk, input UART_RX, output [7:0] data, output send);
  parameter IDLE = 2'b00, START = 2'b01, DATA = 2'b10, STOP = 2'b11;
  reg [8:0] recvbuf;
  reg [5:0] bitcnt = 0;
  reg [1:0] state = IDLE;
  reg data_valid = 0;
  assign data = recvbuf[7:0];
  assign send = data_valid;

  always @(posedge clk) begin
    case(state)
      IDLE: begin
        if(UART_RX == 0) begin
          state <= START;
          bitcnt <= 0;
        end
      end
      START: begin
        if(bitcnt == 0) begin
          if(UART_RX == 0) begin
            bitcnt <= bitcnt + 1;
          end else begin
            state <= IDLE;
          end
        end else begin
          state <= DATA;
          bitcnt <= 0;
        end
      end
      DATA: begin
        if(bitcnt == 8) begin
          state <= STOP;
          bitcnt <= 0;
        end else begin
          recvbuf[bitcnt] <= UART_RX;
          bitcnt <= bitcnt + 1;
        end
      end
      STOP: begin
        if(bitcnt == 0) begin
          if(UART_RX == 1) begin
            state <= IDLE;
            data_valid <= 1;
          end else begin
            state <= IDLE;
          end
        end else begin
          bitcnt <= bitcnt + 1;
        end
      end
    endcase
  end
endmodule

module fifo_async_103x16(
    input rst,
    input wr_clk,
    input rd_clk,
    input [102:0] din,
    input wr_en,
    input rd_en,
    output [102:0] dout,
    output full,
    output empty,
    output prog_full
);

    // Internal FIFO memory
    reg [102:0] mem [0:102];
    // Write and read pointers
    reg [6:0] wr_ptr = 7'b0;
    reg [6:0] rd_ptr = 7'b0;
    // Full and empty flags
    wire is_full = (wr_ptr == (103 - 1)) & (mem[wr_ptr] != 0) & (wr_en == 1);
    wire is_empty = (rd_ptr == wr_ptr) & (mem[rd_ptr] == 0) & (rd_en == 1);
    wire is_prog_full = (wr_ptr == (103 - 4)) & (mem[wr_ptr - 3] != 0) & (wr_en == 1);

    // Write logic
    always @(posedge wr_clk) begin
        if (rst) begin
            wr_ptr <= 7'b0;
        end else if (wr_en) begin
            mem[wr_ptr] <= din;
            wr_ptr <= (wr_ptr == (103 - 1)) ? 7'b0 : wr_ptr + 1'b1;
        end
    end

    // Read logic
    always @(posedge rd_clk) begin
        if (rst) begin
            rd_ptr <= 7'b0;
        end else if (rd_en) begin
            dout <= mem[rd_ptr];
            mem[rd_ptr] <= 0;
            rd_ptr <= (rd_ptr == (103 - 1)) ? 7'b0 : rd_ptr + 1'b1;
        end
    end

    // Output signals
    assign full = is_full;
    assign empty = is_empty;
    assign prog_full = is_prog_full;

endmodule

