module adler_checksum (
  input wire [7:0] byte,
  input wire reset,
  input wire [15:0] expected_checksum,
  output reg [15:0] checksum,
  output wire error
);

  reg [15:0] s1;
  reg [15:0] s2;

  always @ (posedge clk) begin
    if (reset) begin
      s1 <= 16'h0001;
      s2 <= 16'h0001;
      checksum <= 16'h0000;
    end else begin
      s1 <= (s1 + byte) % 16'hFFFF;
      s2 <= (s2 + s1) % 16'hFFFF;
      checksum <= (s2 << 8) | s1;
    end
  end

  assign error = (checksum != expected_checksum);

endmodule

