  wire clk_2mhz;
  GP_RCOSC #(
    .PWRDN_EN(0),
    .AUTO_PWRDN(0),
    .OSC_FREQ("2M"),
    .HARDIP_DIV(1),
    .FABRIC_DIV(1)
  ) rcosc (
    .PWRDN(1'b0),
    .CLKOUT_HARDIP(clk_2mhz),
    .CLKOUT_FABRIC()
  );

  // Buffer the RC oscillator clock
  wire clk_2mhz_buf;
  GP_CLKBUF clkbuf (
    .IN(clk_2mhz),
    .OUT(clk_2mhz_buf)
  );

  // A counter driving the input of the DCMP/PWM
  localparam COUNT_MAX = 255;
  wire [7:0] count_pout;
  GP_COUNT8 #(
    .CLKIN_DIVIDE(1),
    .COUNT_TO(COUNT_MAX),
    .RESET_MODE("RISING")
  ) cnt (
    .CLK(clk_2mhz),
    .RST(1'b0),
    .OUT(count_overflow),
    .POUT(count_pout)
  );

  // Reference inputs to the DCMP
  wire [7:0] ref0;
  wire [7:0] ref1;
  wire [7:0] ref2;
  wire [7:0] ref3;
  GP_DCMPREF #(.REF_VAL(8'h80)) rs0(.OUT(ref0));
  GP_DCMPREF #(.REF_VAL(8'h40)) rs1(.OUT(ref1));
  GP_DCMPREF #(.REF_VAL(8'hc0)) rs2(.OUT(ref2));
  GP_DCMPREF #(.REF_VAL(8'hf0)) rs3(.OUT(ref3));

  // The multiplexer to select between reference values
  wire [7:0] muxouta;
  wire [7:0] muxoutb;
  GP_DCMPMUX mux(
    .SEL(muxsel),
    .OUTA(muxouta),
    .OUTB(muxoutb),
    .IN0(ref0),
    .IN1(ref1),
    .IN2(ref2),
    .IN3(ref3)
  );

  // The DCMP itself
  GP_DCMP #(
    .GREATER_OR_EQUAL(1'b1),
    .CLK_EDGE("RISING"),
    .PWRDN_SYNC(1'b1)
