    assign {c28, s1} = p7 + p8 + {c20, 1'b0};

    assign {c29, s2} = s1 + s2 + {c21, 1'b0};
    assign {c30, s3} = s3 + s4 + {c22, 1'b0};

    assign {c31, s4} = s5 + s6 + {c23, 1'b0};

    assign c32 = c24 + c25 + c26 + c27 + c28 + c29 + c30 + c31;

    assign product = {c32, s7, s8};

    reg [1:0] state;
    reg done;

    always @(posedge clk) begin
        if (reset) begin
            state <= 2'b00;
            done <= 1'b0;
        end else begin
            case (state)
                2'b00: begin
                    done <= 1'b0;
                    state <= 2'b01;
                end
                2'b01: begin
                    done <= 1'b0;
                    state <= 2'b10;
                end
                2'b10: begin
                    done <= 1'b1;
                    state <= 2'b00;
                end
                default: state <= 2'b00;
            endcase
        end
    end

endmodule

