module shift_register (
    input clk, // Clock input
    input reset, // Reset input
    input serial_in, // Serial input
    input shift_in, // Input to shift register
    output reg [3:0] parallel_out // Parallel output
);

    reg [3:0] shift_reg; // 4-bit shift register

    always @(posedge clk) begin
        if (reset) begin
            shift_reg <= 4'b0000;
        end else begin
            shift_reg <= {shift_reg[2:0], serial_in};
        end
    end

    assign parallel_out = shift_in ? shift_reg : 4'b0000;

endmodule

module barrel_shifter (
    input [15:0] data_in, // 16-bit input to be shifted
    input [3:0] shift_amount, // 4-bit shift amount input
    input control, // Control input to choose left or right shift
    output reg [15:0] data_out // 16-bit output from the barrel shifter
);

    always @(data_in or shift_amount or control) begin
        case (control)
            1'b0: data_out <= data_in << shift_amount;
            1'b1: data_out <= data_in >> shift_amount;
        endcase
    end

endmodule

module top_module (
    input serial_in, // 4-bit serial input
    input [3:0] shift_amount, // 4-bit shift amount input
    input control, // Control input to choose left or right shift
    output [3:0] parallel_out // 4-bit output from the shift register
);

    wire [15:0] shifted_data;
    wire [3:0] shift_reg_out;

    barrel_shifter barrel_shifter_inst (
        .data_in(serial_in),
        .shift_amount(shift_amount),
        .control(control),
        .data_out(shifted_data)
    );

    shift_register shift_register_inst (
        .clk(1'b1),
        .reset(1'b0),
        .serial_in(1'b0),
        .shift_in(shifted_data[3:0]),
        .parallel_out(shift_reg_out)
    );

    assign parallel_out = shift_reg_out;

endmodule

