module priority_encoder_gray_counter (
    input clk,
    input rst,
    input ena,
    input [3:0] inputs,
    output reg [3:0] q
);

reg [3:0] gray_q;
reg [3:0] gray_d;
reg [1:0] priority;

always @(posedge clk) begin
    if (rst) begin
        q <= 4'b0000;
        gray_q <= 4'b0000;
        priority <= 2'b00;
    end else begin
        if (ena) begin
            gray_d <= gray_q + 1;
            if (!ena) begin
                gray_d <= gray_q - 1;
            end
            gray_q <= gray_d;
            if (inputs[0]) begin
                q <= 4'b0001;
                priority <= 2'b00;
            end else if (inputs[1]) begin
                q <= 4'b0010;
                priority <= 2'b01;
            end else if (inputs[2]) begin
                q <= 4'b0100;
                priority <= 2'b10;
            end else if (inputs[3]) begin
                q <= 4'b1000;
                priority <= 2'b11;
            end else begin
                case (priority)
                    2'b00: q <= gray_q;
                    2'b01: q <= {gray_q[2], gray_q[1], gray_q[0], 1'b0};
                    2'b10: q <= {gray_q[2], gray_q[0], 1'b0, gray_q[3]};
                    2'b11: q <= {gray_q[1], 1'b0, gray_q[3], gray_q[2]};
                endcase
            end
        end
    end
end

endmodule

