module bcd_counter_adder_subtractor (
    input clk,
    input reset,   // Synchronous active-high reset
    output reg [3:1] ena,
    input [3:0] adder_input, // 4-bit input for the parallel adder
    input [7:0] d2, // 8-bit input for the second given module
    output reg [15:0] q // 4-digit BCD output from the functional module
);

reg [3:0] ones_digit; // The ones digit of the BCD counter
reg [3:0] tens_digit; // The tens digit of the BCD counter
reg [3:0] hundreds_digit; // The hundreds digit of the BCD counter
reg [3:0] thousands_digit; // The thousands digit of the BCD counter
reg [3:0] adder_output; // The output of the parallel adder
reg [7:0] subtractor_input; // The input to the parallel subtractor
reg [7:0] subtractor_output; // The output of the parallel subtractor

// Gray code to BCD conversion for the ones digit
always @ (posedge clk, posedge reset) begin
    if (reset) begin
        ones_digit <= 4'b0000;
    end else begin
        ones_digit <= ones_digit ^ adder_input;
    end
end

// Gray code to BCD conversion for the tens digit
always @ (posedge clk, posedge reset) begin
    if (reset) begin
        tens_digit <= 4'b0000;
    end else begin
        if (ena[1]) begin
            tens_digit <= tens_digit + 1;
        end
    end
end

// Gray code to BCD conversion for the hundreds digit
always @ (posedge clk, posedge reset) begin
    if (reset) begin
        hundreds_digit <= 4'b0000;
    end else begin
        if (ena[2]) begin
            hundreds_digit <= hundreds_digit + 1;
        end
    end
end

// Gray code to BCD conversion for the thousands digit
always @ (posedge clk, posedge reset) begin
    if (reset) begin
        thousands_digit <= 4'b0000;
    end else begin
        if (ena[3]) begin
            thousands_digit <= thousands_digit + 1;
        end
    end
end

// Parallel adder
always @ (posedge clk, posedge reset) begin
    if (reset) begin
        adder_output <= 4'b0000;
    end else begin
        adder_output <= ones_digit + adder_input;
    end
end

// Parallel subtractor
always @ (posedge clk, posedge reset) begin
    if (reset) begin
        subtractor_input <= 8'b00000000;
        subtractor_output <= 8'b00000000;
    end else begin
        subtractor_input <= d2;
        subtractor_output <= ~d2 + 1;
    end
end

// Final output
always @ (posedge clk, posedge reset) begin
    if (reset) begin
        q <= 16'b0000000000000000;
    end else begin
        q <= {thousands_digit, hundreds_digit, tens_digit, ones_digit} + subtractor_output[7:4];
    end
end

endmodule

module up_down_counter(
    input clk, n_rst, up, dn,
    output [3:0] cnt,
    output out1, out2
);

    reg [3:0] cnt_reg;
    wire [3:0] cnt_next;

    assign out1 = ~cnt_reg[0];
    assign out2 = cnt_reg[0];

    always @ (posedge clk, negedge n_rst) begin
        if (~n_rst) begin
            cnt_reg <= 4'b0;
        end else begin
            cnt_reg <= cnt_next;
        end
    end

    always @ (*) begin
        if (up && !dn && cnt_reg < 4'hf) begin
            cnt_next = cnt_reg + 1;
        end else if (dn && !up && cnt_reg > 4'b0) begin
            cnt_next = cnt_reg - 1;
        end else begin
            cnt_next = cnt_reg;
        end
    end

    assign cnt = cnt_reg;

endmodule

module digital_potentiometer (
  input [n-1:0] in,
  input clk,
  input rst,
  input [n-1:0] wiper_pos,
  output reg [n-1:0] resistance
);

parameter n = 8; // number of bits used to represent resistance value
parameter r = 1000; // total resistance value of the resistor ladder network (in ohms)

reg [n-1:0] wiper_pos_reg;
reg [n:0] resistor_ladder;

always @ (posedge clk) begin
  if (rst) begin
    wiper_pos_reg <= 0;
    resistor_ladder <= 0;
    resistance <= 0;
  end else begin
    wiper_pos_reg <= wiper_pos;
    resistor_ladder <= {r/(2**n)} * {2**n{1'b1}};
    resistance <= resistor_ladder[wiper_pos_reg];
  end
end

