module multiplier (
    input [7:0] a,
    input [7:0] b,
    output [15:0] product
);
    wire [7:0] partial1, partial2, partial3, partial4;
    wire [7:0] sum1, sum2, sum3;

    assign partial1 = a[3:0] * b[3:0];
    assign partial2 = a[3:0] * b[7:4];
    assign partial3 = a[7:4] * b[3:0];
    assign partial4 = a[7:4] * b[7:4];

    carry_lookahead_adder adder1 (.a(partial2), .b(partial3), .sum(sum1));
    carry_lookahead_adder adder2 (.a(sum1), .b(partial4), .sum(sum2));
    carry_lookahead_adder adder3 (.a(partial1), .b(sum2), .sum(sum3));

    assign product = {sum3, partial1};
endmodule

