module fifo_64in_out_memory
   (dout,
    wr_clk,
    rd_clk,
    I1,
    tmp_ram_rd_en,
    Q,
    O2,
    O1,
    din);
  output [63:0]dout;
  input wr_clk;
  input rd_clk;
  input I1;
  input tmp_ram_rd_en;
  input [0:0]Q;
  input [11:0]O2;
  input [11:0]O1;
  input [63:0]din;

  reg [63:0] fifo_mem [0:63]; // 64-bit FIFO memory
  reg [5:0] wr_ptr = 0; // write pointer
  reg [5:0] rd_ptr = 0; // read pointer
  reg full = 0; // flag to indicate FIFO full
  wire empty = (wr_ptr == rd_ptr) && !full; // flag to indicate FIFO empty

  // Write operation
  always @(posedge wr_clk) begin
    if (I1 && !full) begin
      fifo_mem[wr_ptr] <= din;
      wr_ptr <= wr_ptr + 1;
      if (wr_ptr == rd_ptr) full <= 1;
    end
  end

  // Read operation
  always @(posedge rd_clk) begin
    if (tmp_ram_rd_en && !empty) begin
      dout <= fifo_mem[rd_ptr];
      rd_ptr <= rd_ptr + 1;
      if (full) full <= 0;
    end
  end

  assign Q = full;

  assign O1 = {12{empty}} ? 0 : rd_ptr[5:0];
  assign O2 = {12{full}} ? 0 : wr_ptr[5:0];

endmodule

module binary_counter (
  input clk,
  input rst,
  input [31:0] max_count,
  output [31:0] count_out,
  output max_reached
);

  reg [31:0] count_reg;
  wire [31:0] count_next;

  assign count_next = count_reg + 1;

  always @(posedge clk or negedge rst) begin
    if (!rst) begin
      count_reg <= 0;
    end else if (count_reg == max_count - 1) begin
      count_reg <= 0;
    end else begin
      count_reg <= count_next;
    end
  end

  assign count_out = count_reg;
  assign max_reached = (count_reg == max_count - 1);

endmodule

module buffer_3input (
