    TE_B
);

    output Z   ;
    input  A   ;
    input  B   ;
    input  C   ;
    input  TE_B;

    wire sel1, sel2;

    assign sel1 = (A & ~B & ~C) | (~A & B & ~C) | (~A & ~B & C);
    assign sel2 = (A & B & ~C) | (A & ~B & C) | (~A & B & C);

    assign Z = TE_B & (sel1 | sel2) & (A | B | C);

endmodule

module LedBank(
  input wire clock,
  input wire reset,
  input wire [11:0] inst,
  input wire inst_en,
  output reg [7:0] leds
);

  // Define LED bank states
  localparam LedBank_State_Reset = 2'b00;
  localparam LedBank_State_Ready = 2'b01;
  localparam LedBank_State_Error = 2'b10;

  // Define LED bank instructions
  localparam LedBank_NOP = 4'b0000;
  localparam LedBank_LDI = 4'b0001;
  localparam LedBank_LD0 = 4'b0010;
  localparam LedBank_LD1 = 4'b0011;
  localparam LedBank_LD2 = 4'b0100;
  localparam LedBank_LD3 = 4'b0101;
  localparam LedBank_LD4 = 4'b0110;
  localparam LedBank_LD5 = 4'b0111;
  localparam LedBank_LD6 = 4'b1000;
  localparam LedBank_LD7 = 4'b1001;

  // Define LED bank variables
  reg [1:0] s_State;
  reg [7:0] s_Leds;
  wire [3:0] w_InstCode;
  wire [7:0] w_InstImm;

  // Assign instruction code and immediate value
  assign w_InstCode = inst[11:8];
  assign w_InstImm = inst[7:0];

  // Define LED bank states
  always @(posedge clock) begin
    if (reset) begin
      s_State <= LedBank_State_Reset;
      s_Leds <= 0;
    end
    else begin
      case (s_State)
        LedBank_State_Reset: begin
          s_State <= LedBank_State_Ready;
          s_Leds <= 0;
        end
        LedBank_State_Ready: begin
          if (inst_en) begin
            case (w_InstCode)
              LedBank_NOP: begin
                s_State <= LedBank_State_Ready;
                s_Leds <= s_Leds;
              end
              LedBank_LDI: begin
                s_State <= LedBank_State_Ready;
                s_Leds <= w_InstImm;
              end
              LedBank_LD0: begin
                s_State <= LedBank_State_Ready;
                s_Leds <= {s_Leds[7:1], w_InstImm[0]};
              end
              LedBank_LD1: begin
                s_State <= LedBank_State_Ready;
                s_Leds <= {s_Leds[7:2], w_InstImm[0], s_Leds[0]};
              end
              LedBank_LD2: begin
                s_State <= LedBank_State_Ready;
                s_Leds <= {s_Leds[7:3], w_InstImm[0], s_Leds[1:0]};
              end
              LedBank_LD3: begin
                s_State <= LedBank_State_Ready;
                s_Leds <= {s_Leds[7:4], w_InstImm[0], s_Leds[2:0]};
              end
              LedBank_LD4: begin
                s_State <= LedBank_State_Ready;
                s_Leds <= {s_Leds[7:5], w_InstImm[0], s_Leds[3:0]};
              end
              LedBank_LD5: begin
                s_State <= LedBank_State_Ready;
                s_Leds <= {s_Leds[7:6], w_InstImm[0], s_Leds[4:0]};
              end
              LedBank_LD6: begin
                s_State <= LedBank_State_Ready;
                s_Leds <= {s_Leds[7:7], w_InstImm[0], s_Leds[5:0]};
              end
              LedBank_LD7: begin
                s_State <= LedBank_State_Ready;
                s_Leds <= {w_InstImm[0], s_Leds[6:0]};
              end
              default: begin
                s_State <= LedBank_State_Error;
                s_Leds <= 0;
              end
            endcase
          end
          else begin
            s_State <= LedBank_State_Ready;
            s_Leds <= s_Leds;
          end
        end
        LedBank_State_Error: begin
          s_State <= LedBank_State_Error;
          s_Leds <= 0;
        end
        default: begin
          s_State <= LedBank_State_Error;
          s_Leds <= 0;
        end
      endcase
    end
  end

  // Assign output
  assign leds = s_Leds;

endmodule

