module ColorImageProcess (
    input Clock,
    input Reset,
    input [size_char-1:0] R,
    input [size_char-1:0] G,
    input [size_char-1:0] B,
    output reg [size_char-1:0] R_out,
    output reg [size_char-1:0] G_out,
    output reg [size_char-1:0] B_out
);

reg [size_char*3-1:0] pixel;
reg [size_char-1:0] R_sum, G_sum, B_sum;
reg [size_char-1:0] R_avg, G_avg, B_avg;

always @ (posedge Clock) begin
    if (Reset) begin
        pixel <= 0;
        R_sum <= 0;
        G_sum <= 0;
        B_sum <= 0;
        R_avg <= 0;
        G_avg <= 0;
        B_avg <= 0;
        R_out <= 0;
        G_out <= 0;
        B_out <= 0;
    end else begin
        pixel <= {B, G, R};
        R_sum <= R_sum + R;
        G_sum <= G_sum + G;
        B_sum <= B_sum + B;
        if ((R_sum + G_sum + B_sum) % 3 == 0) begin
            R_avg <= R_sum / 3;
            G_avg <= G_sum / 3;
            B_avg <= B_sum / 3;
            if ((R_avg + G_avg + B_avg) / 3 >= 128) begin
                R_out <= 255;
                G_out <= 255;
                B_out <= 255;
            end else begin
                R_out <= 0;
                G_out <= 0;
                B_out <= 0;
            end
            R_sum <= 0;
            G_sum <= 0;
            B_sum <= 0;
        end
    end
end

endmodule

module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out
);

reg [7:0] accumulator;
reg [2:0] counter;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        accumulator <= 0;
        counter <= 0;
        valid_b <= 0;
        data_out <= 0;
    end
    else begin
        if (valid_a) begin
            accumulator <= accumulator + data_in;
            counter <= counter + 1;
            if (counter == 7) begin
                data_out <= accumulator;
                valid_b <= 1;
                counter <= 0;
                accumulator <= 0;
            end
        end
        else begin
            valid_b <= 0;
        end
    end
end

assign ready_a = ~valid_b && ready_b;

endmodule

module alu(output [1:0]Z, input [1:0]op, input [1:0]A, B);

    // Implement the AND operation
    assign Z[0] = (op == 2'b00) ? A[0] & B[0] : 1'b0;

    // Implement the OR operation
    assign Z[1] = (op == 2'b01) ? A[1] | B[1] : 1'b0;

    // Implement the ADD and SUBTRACT operations
    always @(*) begin
        case(op)
            2'b10: Z = A + B; // ADD
            2'b11: Z = A - B; // SUBTRACT
            default: Z = 2'b0;
        endcase
    end

endmodule

module RAM(
  input [5:0] i_addr,
  input i_enable_x,
  input i_write_x,
  input [15:0] i_data,
  output reg [15:0] o_data
);

  parameter delay = 5;
  parameter depth = 64;
  parameter width = 16;

  reg [width-1:0] r_ram [0:depth-1];
  reg [5:0] r_addr;
  reg r_enable_x, r_write_x;
  reg [width-1:0] r_data;

  always @(i_addr, i_enable_x, i_write_x, i_data) begin
    r_addr = #delay i_addr;
    r_enable_x = #delay i_enable_x;
    r_write_x = #delay i_write_x;
    r_data = #delay i_data;

    if (r_enable_x) begin
      o_data <= #delay 16'bzzzzzzzzzzzzzzzz;
    end else if (r_write_x) begin
      r_ram[r_addr] <= #delay r_data;
    end else begin
      o_data <= #delay r_ram[r_addr];
    end
  end
endmodule

module FA(A, B, Cin, Sum, Cout);
   input A, B, Cin;
   output Sum, Cout;

   wire w1, w2, w3;
   xor (w1, A, B);
   xor (Sum, w1, Cin);
   and (w2, A, B);
   and (w3, w1, Cin);
   or (Cout, w2, w3);

endmodule

module RCA4(A, B, Cin, S, Cout);
   input [3:0] A, B;
   input Cin;
   output [3:0] S;
   output Cout;

   wire c1, c2, c3;
   FA fa0(A[0], B[0], Cin, S[0], c1);
   FA fa1(A[1], B[1], c1, S[1], c2);
   FA fa2(A[2], B[2], c2, S[2], c3);
   FA fa3(A[3], B[3], c3, S[3], Cout);

endmodule

module AddSub4Bit(A, B, C, S, Cout);
   input [3:0] A, B;
   input C;
   output [3:0] S;
   output Cout;

   wire w1, w2, w3;
   xor (w1, A, B);
   xor (S, w1, C);
   not (w2, C);
   xor (w3, A, w2);
   RCA4 rca(B, w3, w2, S, Cout);

endmodule

module ad9777_spi (
    output reg sdio,
    output reg csb,
    input rst,
    input clk,
    output reg spi_ok
);

    wire [6:0] lut_index = 7'd5;

    function [15:0] lut_data;
        input [5:0] addr;
        begin
            case(addr)
                6'd0: lut_data = 16'b0_00_00000_0000_0100; // 00
                6'd1: lut_data = 16'b0_00_00001_0000_0000; // 01
                6'd2: lut_data = 16'b0_00_00101_0000_0001; // 05
                6'd3: lut_data = 16'b0_00_00110_0000_1111; // 06
                6'd4: lut_data = 16'b0_00_01001_0000_0000; // 09
                6'd5: lut_data = 16'b0_00_01010_0000_1111; // 0A
            endcase
        end
    endfunction

    reg [5:0] addr;
    reg [4:0] state;
    reg [15:0] dout_reg;
    reg [4:0] shift_reg;

    always @ (negedge clk or negedge rst)
    if (!rst) begin
        csb <= 1'b1;
        sdio <= 1'b1;
        state <= 5'd0;
        addr <= 6'd0;
        dout_reg <= 16'd0;
        shift_reg <= 5'd0;
        spi_ok <= 1'b0;
    end else begin
        case(state)
            5'd0: begin
                csb <= 1'b1;
                dout_reg <= lut_data(addr);
                state <= 5'd1;
            end
            5'd1: begin
                if (shift_reg <= 5'd15) begin
                    csb <= 1'b0;
                    sdio <= dout_reg[15];
                    dout_reg <= dout_reg << 1;
                    shift_reg <= shift_reg + 1'b1;
                    state <= 5'd1;
                end else begin
                    shift_reg <= 5'd0;
                    csb <= 1'b1;
                    sdio <= 1'b1;
                    if (addr < lut_index) begin
                        addr <= addr + 1'b1;
                        state <= 5'd0;
                    end else begin
                        addr <= 6'd0;
                        state <= 5'd2;
                    end
                end
            end
            5'd2: begin
                spi_ok <= 1'b1;
                state <= 5'd3;
            end
        endcase
    end
endmodule

module top_module(
    input wire [15:0] in,
    input wire control,
    output wire [7:0] out);

    wire [15:0] shifted_in;
    wire [7:0] upper_byte;
    wire [7:0] lower_byte;

    // Barrel shifter to shift input to the right by 8 bits
    barrel_shifter bs(
        .in(in),
        .shifted_out(shifted_in)
    );

    // Multiplexer to select upper or lower byte based on control signal
    mux_2to1 mux(
        .in0(shifted_in[7:0]),
        .in1(shifted_in[15:8]),
        .control(control),
        .out(upper_byte)
    );

    mux_2to1 mux2(
        .in0(shifted_in[7:0]),
        .in1(shifted_in[15:8]),
        .control(~control),
        .out(lower_byte)
    );

    // Final 8-bit output
    assign out = control ? upper_byte : lower_byte;

endmodule

