module multiplication_accumulator (
    input               clk         ,
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_in    ,
    input               ready_out   ,
    output              ready_in    ,
    output  reg         valid_out   ,
    output  reg [7:0]   data_out
);

// Internal signals
reg [7:0]   input_data [0:5];
reg [7:0]   accumulated_data;
reg [2:0]   counter;

// Instantiate adder and multiplier modules
adder_module adder(.a(accumulated_data), .b(data_in), .sum(accumulated_data));
multiplier_module multiplier(.a(input_data[0]), .b(input_data[1]), .product(input_data[2]));

// Pipeline registers
reg [7:0]   pipeline_reg1;
reg [15:0]  pipeline_reg2;

// Valid-ready handshake
assign ready_in = (counter == 0) ? 1 : 0;
assign valid_out = (counter == 6) ? 1 : 0;

// Input data pipeline
always @(posedge clk) begin
    if (rst_n == 1'b0) begin
        input_data[0] <= 8'h00;
        input_data[1] <= 8'h00;
        input_data[2] <= 16'h0000;
    end else if (valid_in && ready_in) begin
        input_data[0] <= data_in;
        input_data[1] <= input_data[0];
        input_data[2] <= {input_data[0], input_data[1]};
    end
end

// Accumulation pipeline
always @(posedge clk) begin
    if (rst_n == 1'b0) begin
        pipeline_reg1 <= 8'h00;
        pipeline_reg2 <= 16'h0000;
        accumulated_data <= 8'h00;
        counter <= 3'h0;
    end else if (valid_in && ready_in) begin
        pipeline_reg1 <= accumulated_data;
        pipeline_reg2 <= input_data[2];
        accumulated_data <= adder.sum;
        counter <= counter + 1;
    end else if (valid_out && ready_out) begin
        pipeline_reg1 <= 8'h00;
        pipeline_reg2 <= 16'h0000;
        accumulated_data <= 8'h00;
        counter <= 3'h0;
    end
end

// Output data pipeline
always @(posedge clk) begin
    if (rst_n == 1'b0) begin
        data_out <= 8'h00;
    end else if (valid_out && ready_out) begin
        data_out <= pipeline_reg1[7:0] + pipeline_reg2[15:8];
    end
end

endmodule

module adder_4bit(output reg [3:0] S, Cout, input [3:0] A, B, Cin);
	wire [3:0] c;

	// first half adder
	half_adder ha1(.S(c[0]), .Cout(c[1]), .A(A[0]), .B(B[0]));

	// full adders for bits 1-3
	full_adder fa1(.S(S[0]), .Cout(c[2]), .A(A[1]), .B(B[1]), .Cin(c[1]));
	full_adder fa2(.S(S[1]), .Cout(c[3]), .A(A[2]), .B(B[2]), .Cin(c[2]));
	full_adder fa3(.S(S[2]), .Cout(Cout), .A(A[3]), .B(B[3]), .Cin(c[3]));

	// assign carry-in
	assign fa1.Cin = Cin;
endmodule

// half adder module
module half_adder(output S, Cout, input A, B);
