// full adder module
module full_adder(output S, Cout, input A, B, Cin);
	wire c1, c2;

	half_adder ha1(.S(S), .Cout(c1), .A(A), .B(B));
	half_adder ha2(.S(S), .Cout(c2), .A(S), .B(Cin));

	or(Cout, c1, c2);
endmodule

