module traffic_light_controller(
    input reset, left, right, clk,
    output LA, LB, LC, RA, RB, RC
);

parameter ST_IDLE = 3'b000;
parameter ST_L1 = 3'b001;
parameter ST_L2 = 3'b010;
parameter ST_L3 = 3'b011;
parameter ST_R1 = 3'b100;
parameter ST_R2 = 3'b101;
parameter ST_R3 = 3'b110;

reg [2:0] state, next_state;

always @(posedge clk)
    if (reset)
        state <= ST_IDLE;
    else
        state <= next_state;

always @*
begin
    case (state)
        ST_IDLE: begin
            if (left && ~right)
                next_state = ST_L1;
            else if (~left && right)
                next_state = ST_R1;
            else
                next_state = ST_IDLE;
        end
        ST_L1: next_state = ST_L2;
        ST_L2: next_state = ST_L3;
        ST_R1: next_state = ST_R2;
        ST_R2: next_state = ST_R3;
        default: next_state = ST_IDLE;
    endcase
    if (left && right)
        next_state = ST_IDLE;
end

parameter DELAY = 10; // in clock cycles

reg [3:0] timer;

always @(posedge clk)
    if (reset)
        timer <= 0;
    else if (state == ST_L1 || state == ST_L2 || state == ST_R1 || state == ST_R2)
        timer <= timer + 1;
    else
        timer <= 0;

assign LA = state == ST_L1 || state == ST_L2 || state == ST_L3;
assign LB = state == ST_L2 || state == ST_L3;
assign LC = state == ST_L3;
assign RA = state == ST_R1 || state == ST_R2 || state == ST_R3;
assign RB = state == ST_R2 || state == ST_R3;
assign RC = state == ST_R3;

always @*
begin
    case (state)
        ST_L1: begin
            if (timer >= DELAY)
                next_state = ST_L2;
        end
        ST_L2: begin
            if (timer >= DELAY)
                next_state = ST_L3;
        end
        ST_L3: begin
            if (left && ~right)
                next_state = ST_L1;
            else if (~left && right)
                next_state = ST_R1;
            else if (timer >= DELAY)
                next_state = ST_IDLE;
        end
        ST_R1: begin
            if (timer >= DELAY)
                next_state = ST_R2;
        end
        ST_R2: begin
            if (timer >= DELAY)
                next_state = ST_R3;
        end
        ST_R3: begin
            if (~left && right)
                next_state = ST_R1;
            else if (left && ~right)
                next_state = ST_L1;
            else if (timer >= DELAY)
                next_state = ST_IDLE;
        end
        default: begin
            if (left && ~right)
                next_state = ST_L1;
            else if (~left && right)
                next_state = ST_R1;
            else
                next_state = ST_IDLE;
        end
    endcase
    if (left && right)
        next_state = ST_IDLE;
end

endmodule

