// Carry select adder module
module carry_select_adder #(
    parameter N = 16   // Number of bits
) (
    input clk,
    input [N-1:0] a,  // First input
    input [N-1:0] b,  // Second input
    output [N-1:0] sum // Output sum
);

    wire [N-1:0] carry;    // Array of carry bits

    // Generate carry bits using a ripple carry adder
    genvar i;
    generate
        for (i = 0; i < N; i = i + 1) begin : ripple_carry
            ripple_carry_adder #(.N(1)) rca (
                .clk(clk),
                .a(a[i]),
                .b(b[i]),
                .c(i == 0 ? 1'b0 : carry[i-1]),   // Use previous carry bit for all but first bit
                .sum(sum[i]),
                .c_out(carry[i])
            );
