// Ripple carry adder module
module ripple_carry_adder #(
    parameter N = 16   // Number of bits
) (
    input clk,
    input [N-1:0] a,  // First input
    input [N-1:0] b,  // Second input
    output [N-1:0] sum, // Output sum
    output c_out       // Output carry bit
);

    reg [N:0] temp_sum;    // Temporary sum
    reg c;                 // Carry bit

    always @(posedge clk) begin
        temp_sum <= {1'b0, a} + {1'b0, b} + {1'b0, c};   // Add inputs and carry bit
        sum <= temp_sum[N-1:0];                          // Output sum
        c_out <= temp_sum[N];                            // Output carry bit
    end

endmodule

// Final adder module
module final_adder #(
    parameter N = 16   // Number of bits
) (
    input clk,
    input reset,        // Synchronous active-high reset
    input [N-1:0] a,    // First input
    input [N-1:0] b,    // Second input
    output [N-1:0] sum  // Output sum
);

    reg [N:0] temp_sum;    // Temporary sum

    always @(posedge clk) begin
        if (reset) begin
            temp_sum <= {N+1{1'b0}};   // Reset output to zero
        end else begin
            temp_sum <= {1'b0, a} + {1'b0, b};   // Add inputs
        end
        sum <= temp_sum[N-1:0];      // Output sum
    end

endmodule

