module fsm_traffic_light_control (
  input clk,
  input reset,
  input [31:0] timer,
  output reg red,
  output reg yellow,
  output reg green,
  output reg red_p,
  output reg yellow_p,
  output reg green_p
);

  reg [1:0] state, next_state;

  always @ (posedge clk or posedge reset) begin
    if (reset) begin
      state <= 2'b00;
    end else begin
      state <= next_state;
    end
  end

  always @ (*) begin
    case (state)
      2'b00: begin // RED
        if (timer >= 10) begin
          next_state = 2'b10; // GREEN
        end else begin
          next_state = 2'b00; // RED
        end
      end
      2'b01: begin // YELLOW
        if (timer >= 2) begin
          next_state = 2'b00; // RED
        end else begin
          next_state = 2'b01; // YELLOW
        end
      end
      2'b10: begin // GREEN
        if (timer >= 5) begin
          next_state = 2'b01; // YELLOW
        end else begin
          next_state = 2'b10; // GREEN
        end
      end
      default: begin
        next_state = 2'b00; // RED
      end
    endcase
  end

  always @ (posedge clk or posedge reset) begin
    if (reset) begin
      red <= 1'b1;
      yellow <= 1'b0;
      green <= 1'b0;
      red_p <= 1'b1;
      yellow_p <= 1'b0;
      green_p <= 1'b0;
    end else begin
      case (state)
        2'b00: begin // RED
          red <= 1'b1;
          yellow <= 1'b0;
          green <= 1'b0;
        end
        2'b01: begin // YELLOW
          red <= 1'b0;
          yellow <= 1'b1;
          green <= 1'b0;
        end
        2'b10: begin // GREEN
          red <= 1'b0;
          yellow <= 1'b0;
          green <= 1'b1;
        end
        default: begin
          red <= 1'b1;
          yellow <= 1'b0;
          green <= 1'b0;
        end
      endcase

      case (state)
        2'b00: begin // RED
          red_p <= 1'b1;
          yellow_p <= 1'b0;
          green_p <= 1'b0;
        end
        2'b01: begin // YELLOW
          red_p <= 1'b0;
          yellow_p <= 1'b1;
          green_p <= 1'b0;
        end
        2'b10: begin // GREEN
          red_p <= 1'b0;
          yellow_p <= 1'b0;
          green_p <= 1'b1;
        end
        default: begin
          red_p <= 1'b1;
          yellow_p <= 1'b0;
          green_p <= 1'b0;
        end
      endcase
    end
  end

endmodule

