    output reg [31:0] io_out_bits,
    output reg [0:0] io_pcOut_valid,
    output reg [0:0] io_pcOut_bits_request,
    output reg [15:0] io_pcOut_bits_moduleId,
    output reg [7:0] io_pcOut_bits_portId,
    output reg [15:0] io_pcOut_bits_pcValue,
