    reg [0:0] io_out_valid_latch;
    reg [0:0] io_pcOut_valid_latch;
    reg [0:0] io_pcOut_bits_request_latch;
    reg [15:0] io_pcOut_bits_moduleId_latch;
    reg [7:0] io_pcOut_bits_portId_latch;
    reg [15:0] io_pcOut_bits_pcValue_latch;
    reg [3:0] io_pcOut_bits_pcType_latch;

    always @(negedge clk) begin
        if (!reset) begin
            $fscanf('h80000000, "%x %x %x %x %x %x %x %x %x", io_in_valid, io_in_bits, io_pcIn_valid, io_pcIn_bits_request, io_pcIn_bits_moduleId, io_pcIn_bits_portId, io_pcIn_bits_pcValue, io_pcIn_bits_pcType);
            io_in_ready_latch <= 1;
        end
    end

    always @(posedge clk) begin
        if (!reset) begin
            io_in_ready <= io_in_ready_latch;
            io_out_valid <= io_out_valid_latch;
            io_out_bits <= io_out_bits_latch;
            io_pcOut_valid <= io_pcOut_valid_latch;
            io_pcOut_bits_request <= io_pcOut_bits_request_latch;
            io_pcOut_bits_moduleId <= io_pcOut_bits_moduleId_latch;
