        end
    end

    always @(io_out_ready) begin
        if (!reset) begin
            io_out_valid_latch <= io_out_ready;
            io_out_bits_latch <= io_in_bits;
            io_pcOut_valid_latch <= io_pcIn_valid;
            io_pcOut_bits_request_latch <= io_pcIn_bits_request;
            io_pcOut_bits_moduleId_latch <= io_pcIn_bits_moduleId;
