module top_module (
    input clk,
    input reset,   // Synchronous active-high reset
    input [1:0] A, // 2-bit binary number A
    input [1:0] B, // 2-bit binary number B
    output [3:1] ena, // Enable signals for digits 3, 2, and 1
    output reg [15:0] q, // 16-bit output from BCD counter
    output reg [3:0] func_out // 4-bit output from functional module
);

// Instantiate the 2-bit comparator module
comparator_2bit cmp (
    .a(A),
    .b(B),
    .greater(greater),
    .less(less),
    .equal(equal)
);

// Instantiate the 4-digit BCD counter module
bcd_counter_4digit counter (
    .clk(clk),
    .reset(reset),
    .ena(ena),
    .q(q)
);

// Define the functional module logic
always @ (posedge clk) begin
    if (reset) begin
        ena <= 3'b000;
        q <= 16'b0000;
        func_out <= 4'b0000;
    end else begin
        ena[3] <= greater;
        ena[2] <= 1;
        ena[1] <= less;

        if (greater) begin
            func_out <= q[15:12];
        end else if (less) begin
            func_out <= q[3:0];
        end else begin
            func_out <= q[14:12] + q[11:8];
        end
    end
end

