module CDR (
  input data_in,
  input clk_ref,
  output reg clk_out
);

parameter baud_rate = 9600; // baud rate of the serial data stream
parameter freq_tolerance = 0.001; // frequency tolerance of the recovered clock signal

reg data_prev;
reg data_edge;
reg clk_edge;
reg [31:0] baud_count;
reg [31:0] clk_count;
reg [31:0] phase_count;
reg [31:0] phase_diff;
reg [31:0] phase_adjust;
reg [31:0] phase_adjust_count;
reg phase_dir;

always @(posedge clk_ref) begin
  // detect data edge
  data_edge <= (data_in != data_prev);
  data_prev <= data_in;

  // detect clock edge
  clk_edge <= ~clk_edge;

  // increment baud count
  if (baud_count == (baud_rate / 2) - 1) begin
    baud_count <= 0;
  end else begin
    baud_count <= baud_count + 1;
  end

  // increment clock count
  if (clk_count == 0) begin
    clk_count <= (baud_rate / 2) - 1;
  end else begin
    clk_count <= clk_count - 1;
  end

  // calculate phase difference
  phase_diff <= (clk_count * 1000) / baud_rate;

  // adjust phase
  if (phase_adjust_count == 0) begin
    if (phase_diff > freq_tolerance * 1000) begin
      phase_dir <= 1;
    end else if (phase_diff < -freq_tolerance * 1000) begin
      phase_dir <= 0;
    end
    phase_adjust_count <= (baud_rate / 1000) - 1;
  end else begin
    phase_adjust_count <= phase_adjust_count - 1;
  end
  if (phase_dir == 1) begin
    phase_adjust <= phase_adjust + 1;
  end else if (phase_dir == 0) begin
    phase_adjust <= phase_adjust - 1;
  end

  // generate recovered clock
  if (data_edge) begin
    if (clk_edge) begin
      clk_out <= 1;
    end else begin
      clk_out <= 0;
    end
  end else begin
    if (clk_count == phase_adjust) begin
      clk_out <= clk_edge;
    end
  end
end

endmodule

