module SSCG (
  input clk_ref,
  input ctrl,
  output ssc_clk
);

parameter f_ref = 50; // frequency of the reference clock signal (MHz)
parameter f_ssc = 50.5; // frequency of the spread spectrum clock signal (MHz)
parameter spread = 1; // amount of spread for the clock signal (%)

reg [31:0] counter;
reg [31:0] delta_f;
reg [31:0] ssc_counter;
wire [31:0] ssc_delta_f;

assign ssc_delta_f = (f_ssc * spread) / 100;

always @(posedge clk_ref) begin
  if (ctrl) begin
    delta_f <= ssc_delta_f;
  end else begin
    delta_f <= -ssc_delta_f;
  end
end

always @(posedge clk_ref) begin
  counter <= counter + delta_f;
  if (counter >= (f_ref * 1000000)) begin
    counter <= counter - (f_ref * 1000000);
  end
end

always @(posedge clk_ref) begin
  ssc_counter <= ssc_counter + delta_f;
  if (ssc_counter >= (f_ssc * 1000000)) begin
    ssc_counter <= ssc_counter - (f_ssc * 1000000);
  end
end

assign ssc_clk = (ssc_counter < (f_ssc * 1000000) / 2) ? 1'b0 : 1'b1;

endmodule

