    input shift_enable,
    input [3:0] data_in,
    output reg [3:0] data_out
);

always @(posedge clk) begin
    if (load) begin
        data_out <= data_in;
    end else if (shift_enable) begin
        data_out <= {data_out[2:0], 1'b0};
    end
end

endmodule

module barrel_shifter (
