    input [1:0] control,
    output [3:0] data_out
);

assign data_out = (control == 2'b00) ? data_in : 
                  (control == 2'b01) ? {data_in[2:0], data_in[3]} : 
                  (control == 2'b10) ? {data_in[1:0], data_in[3:2]} : 
                  {data_in[0], data_in[3:1]};

endmodule

module adder (
