module counter_26bit (En, Clk, Clr, Q);
  input En, Clk, Clr;
  output [25:0] Q;

  wire [25:0] T, Qs;

  t_flipflop T0 (En, Clk, Clr, Qs[0]);
  assign T[0] = En & Qs[0];

  generate
    genvar i;
    for (i = 1; i < 26; i = i + 1) begin : gen_tflops
      t_flipflop T (T[i-1], Clk, Clr, Qs[i]);
      assign T[i] = T[i-1] & Qs[i];
    end
  endgenerate

  assign Q = Qs;
endmodule

