    else if (En) begin
      Q <= T;
    end
  end
endmodule

module Booth_Multiplier #(
    parameter pN = 4                // Width = 2**pN: multiplicand & multiplier
)(
    input   Rst,                    // Reset
    input   Clk,                    // Clock

    input   Ld,                     // Load Registers and Start Multiplier
    input   [(2**pN - 1):0] M,      // Multiplicand
    input   [(2**pN - 1):0] R,      // Multiplier
    output  reg Valid,              // Product Valid
    output  reg [(2**(pN+1) - 1):0] P   // Product <= M * R
);

///////////////////////////////////////////////////////////////////////////////
//
//  Local Parameters
//

parameter pN1 = pN + 1;
parameter pN2 = pN + 2;

///////////////////////////////////////////////////////////////////////////////
//
//  Declarations
//

reg     [pN2:0] A;      // Multiplicand w/ sign guard bit
reg     [pN:0] Cntr;    // Operation Counter
reg     [pN2:0] S;      // Adder w/ sign guard bit

reg     [(2*pN2 - 1):0] Prod;   // Double length product w/ guard bits

///////////////////////////////////////////////////////////////////////////////
//
//  Implementation
//

always @(posedge Clk) begin
    if(Rst) Cntr <= #1 0;
    else if(Ld) Cntr <= #1 pN+1;
    else if(Cntr != 0) Cntr <= #1 Cntr - 1;
end

// Multiplicand Register
// includes an additional bit to guard sign bit in the event the
// most negative value is provided as the multiplicand.

always @(posedge Clk) begin
    if(Rst) A <= #1 0;
    else if(Ld) A <= #1 {M[pN - 1], M};
end

// Compute Upper Partial Product: (2**pN + 1) bits in width

always @(*) begin
    case(Prod[pN+1: pN])
        2'b01   : S <= Prod[pN2: pN] + A;
        2'b10   : S <= Prod[pN2: pN] - A;
        default : S <= Prod[pN2: pN];
    endcase
end

// Register Partial products and shift rigth arithmetically.
// Product register has guard bits on both ends.

always @(posedge Clk) begin
    if(Rst) Prod <= #1 0;
    else if(Ld) Prod <= #1 {R[pN-1], R, 1'b0};
    else if(Cntr != 0) Prod <= #1 {S[pN2], S, Prod[pN2:1]}; // Arithmetic Shift Right
end

// Assign the product less the two guard bits to the output port

always @(posedge Clk) begin
    if(Rst) P <= #1 0;
    else if(Cntr == 1) P <= #1 {S[pN2], S, Prod[pN2:2]};
end

// Count the number of shifts
// This implementation does not use any optimizations to perform multiple
// bit shifts to skip over runs of 1s or 0s.

always @(posedge Clk) begin
    if(Rst) Valid <= #1 0;
    else Valid <= #1 (Cntr == 1);
end

endmodule

module soc_system_jtag_uart_sim_scfifo_w (
  // inputs:
  clk,
  fifo_wdata,
  fifo_wr,

  // outputs:
  fifo_FF,
  r_dat,
  wfifo_empty,
  wfifo_used
);

  output fifo_FF;
  output [7:0] r_dat;
  output wfifo_empty;
  output [5:0] wfifo_used;
  input clk;
  input [7:0] fifo_wdata;
  input fifo_wr;

  reg [7:0] fifo [63:0];
  reg [5:0] head;
  reg [5:0] tail;
  reg [6:0] count;
  wire full = (count == 64);
  wire empty = (count == 0);

  always @(posedge clk) begin
    if (fifo_wr && !full) begin
      fifo[head] <= fifo_wdata;
      head <= head + 1;
      count <= count + 1;
    end
    if (!empty) begin
      r_dat <= fifo[tail];
      tail <= tail + 1;
      count <= count - 1;
    end
  end

  assign wfifo_used = count;
  assign fifo_FF = full;
  assign wfifo_empty = empty;

endmodule

module fill_pattern (
    input VPWR,
    input VGND,
    input VPB,
    input VNB,
    output reg [1:0] fill
);

    always @(*) begin
        // Create the 2x2 unit cell
        case ({fill[1], fill[0]})
            2'b00: fill = 2'b01;
            2'b01: fill = 2'b10;
            2'b10: fill = 2'b11;
            2'b11: fill = 2'b00;
        endcase

        // Ensure symmetry about the x-axis
        if (VNB > VPB) begin
            fill[1] = ~fill[1];
        end

        // Ensure symmetry about the y-axis
        if (VGND > VPWR) begin
            fill[0] = ~fill[0];
        end

        // Ensure no shorting paths between VPWR and VGND
        if (fill == 2'b00 || fill == 2'b11) begin
            fill = 2'b10;
        end

        // Ensure no shorting paths between VPB and VNB
        if (fill == 2'b01 || fill == 2'b10) begin
            fill = 2'b00;
        end
    end

endmodule

module inv_trig (
  input signed [31:0] sine,
  input signed [31:0] cosine,
  input signed [31:0] tangent,
  input [1:0] select,
  output signed [31:0] angle
);

  // Constants for pi/2
  localparam PI_OVER_2 = 32'h3FC90FDB;

  // Internal signals
  wire signed [31:0] asin_result;
  wire signed [31:0] acos_result;
  wire signed [31:0] atan_result;

  // Instantiate arcsine, arccosine, and arctangent modules
  arcsine asin_inst (.x(sine), .y(asin_result));
  arccosine acos_inst (.x(cosine), .y(acos_result));
  arctangent atan_inst (.x(tangent), .y(atan_result));

  // Mux to select the output based on the select input
  always @(*) begin
