module top_module (
    input               clk         ,
    input               reset       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,
    input       [7:0]   d           ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [7:0]   q           );

    // Accumulator module
    reg [7:0] buffer [0:7];
    reg [2:0] count = 0;
    reg [7:0] acc = 0;
    reg [2:0] acc_count = 0;
    wire acc_ready = (count == 3);
    wire buffer_ready = (count < 3);
    wire acc_valid = (acc_count == 0);
    wire buffer_valid = (acc_count > 0);

    always @(posedge clk) begin
        if (reset) begin
            count <= 0;
            acc_count <= 0;
            acc <= 0;
            buffer <= {8{0}};
        end else begin
            if (valid_a && acc_ready) begin
                buffer[count] <= data_in;
                count <= count + 1;
                if (count == 8) begin
                    count <= 0;
                    acc_count <= 3;
                end
            end

            if (acc_valid) begin
                acc <= acc + buffer[acc_count];
                acc_count <= acc_count + 1;
                if (acc_count == 8) begin
                    acc_count <= 0;
                    valid_b <= 1;
                    q <= acc;
                end
            end

            if (ready_b && buffer_valid) begin
                acc_count <= acc_count - 1;
            end
        end
    end

    // Functional module
    reg [7:0] d_ff [0:7];
    reg [7:0] or_result = 8'h34;
    wire or_ready = (acc_count == 0);
    wire d_ff_ready = (acc_count > 0);
    wire or_valid = (count == 3);
    wire d_ff_valid = (count < 3);

    always @(posedge clk) begin
        if (reset) begin
            d_ff <= {8{8'h34}};
            or_result <= 8'h34;
        end else begin
            if (or_ready && d_ff_ready) begin
                or_result <= acc | d;
            end

            if (or_valid) begin
                d_ff <= {d_ff[1:7], or_result};
            end

            if (d_ff_valid) begin
                q <= d_ff[count];
            end
        end
    end

    assign ready_a = buffer_ready && d_ff_ready;

endmodule

