module populate_candidates (
input wire clock,
input wire [7:0] code,
input wire [7:0] base_candidate_addr,
output reg [7:0] addr_candidates,
input wire [7:0] read_candidates,
input wire [7:0] candidate_len,
input wire [7:0] base_next_cand_addr,
output reg [7:0] addr_next_cand,
output reg [7:0] data_next_cand,
output wire wren_next_cand,
output reg [7:0] next_cand_len,
input wire [3:0] min_dist,
input wire start,
output wire complete
);

wire [3:0] distance;
reg [7:0] ham_in_a, ham_in_b;

hamming_distance hd (
	.clock ( clock),
	.val_a ( ham_in_a ),
	.val_b ( ham_in_b ),
	.distance ( distance )
);

reg done;
assign complete = (done == 1 || state == ST_DONE);
reg write_cand;
assign wren_next_cand = write_cand;
reg [7:0] icand, inext;
reg start_1, start_2;
reg			[5:0]	state;
parameter	[5:0]	ST_RST		= 6'h00,
					ST_IDLE		= 6'h01,
					ST_READ_CAND = 6'h02,
					ST_CALC_DIST = 6'h03,
					ST_WRITE_CAND = 6'h04,
					ST_DONE		= 6'h07;

always @(posedge clock) begin
	{start_2, start_1} <= {start_1, start};

	case(state)
	ST_RST: begin
		done <= 0;
		state <= ST_IDLE;
	end

	ST_IDLE: begin
			if( start_2 ) begin
				ham_in_a <= code;
				icand <= 0;
				inext <= 0;
				state <= ST_READ_CAND;
				done <= 0;
			end

	end

	// Read next candidate
	ST_READ_CAND: begin
		addr_candidates <= base_candidate_addr + icand;
		state <= ST_CALC_DIST;
	end

	// Calculate Hamming distance
	ST_CALC_DIST: begin
		ham_in_b <= read_candidates;
		state <= ST_WRITE_CAND;
	end

	// Write new candidate
	ST_WRITE_CAND: begin
		if ( distance >= min_dist ) begin
			data_next_cand <= read_candidates;
			addr_next_cand <= base_next_cand_addr + inext;
			write_cand <= 1;
		end
		state <= ST_READ_CAND;
		if ( distance >= min_dist ) begin
			inext <= inext + 1;
		end
		icand <= icand + 1;
		if ( icand > candidate_len ) begin
			done <= 1;
			next_cand_len <= inext;
			state <= ST_DONE;
		end
	end

	ST_DONE: begin
		state <= ST_IDLE;
	end
	endcase
end
endmodule

