module single_cycle_mips (
  input clk,
  input reset
);

  // Register file
  reg [31:0] reg_file [0:31];
  initial begin
    reg_file[0] = 32'h0; // $zero
  end

  // Program counter
  reg [31:0] pc = 32'h0;
  initial begin
    pc = 32'h0;
  end

  // Instruction memory
  reg [31:0] inst_mem [0:6];
  initial begin
    inst_mem[0] = 32'h20080005; // addi $t0, $zero, 5
    inst_mem[1] = 32'h2009000A; // addi $t1, $zero, 10
    inst_mem[2] = 32'h01094020; // add $t2, $t0, $t1
    inst_mem[3] = 32'h01094824; // and $t3, $t2, $t1
    inst_mem[4] = 32'h01095025; // or $t4, $t2, $t1
    inst_mem[5] = 32'h01095826; // xor $t5, $t2, $t1
    inst_mem[6] = 32'h01096022; // sub $t6, $t2, $t1
  end

  // ALU control
  reg [2:0] alu_op;
  always @*
    case (inst_mem[pc[5:2]])
      6'b000000_00100_01010_01000_00000_100000: alu_op = 3'b000; // add
      6'b000000_00100_01010_01000_00000_100100: alu_op = 3'b001; // sub
      6'b000000_00100_01010_01000_00000_100100: alu_op = 3'b010; // and
      6'b000000_00100_01010_01000_00000_100101: alu_op = 3'b011; // or
      6'b000000_00100_01010_01000_00000_100110: alu_op = 3'b100; // xor
    endcase

  // ALU
  reg [31:0] alu_out;
  always @*
    case (alu_op)
      3'b000: alu_out = reg_file[inst_mem[pc[5:2]][19:15]] + reg_file[inst_mem[pc[5:2]][24:20]]; // add
      3'b001: alu_out = reg_file[inst_mem[pc[5:2]][19:15]] - reg_file[inst_mem[pc[5:2]][24:20]]; // sub
      3'b010: alu_out = reg_file[inst_mem[pc[5:2]][19:15]] & reg_file[inst_mem[pc[5:2]][24:20]]; // and
      3'b011: alu_out = reg_file[inst_mem[pc[5:2]][19:15]] | reg_file[inst_mem[pc[5:2]][24:20]]; // or
      3'b100: alu_out = reg_file[inst_mem[pc[5:2]][19:15]] ^ reg_file[inst_mem[pc[5:2]][24:20]]; // xor
    endcase

  // Register write
  always @(posedge clk)
    if (reset) begin
      reg_file[0] <= 32'h0;
      reg_file[1] <= 32'h0;
      reg_file[2] <= 32'h0;
      reg_file[3] <= 32'h0;
      reg_file[4] <= 32'h0;
      reg_file[5] <= 32'h0;
      reg_file[6] <= 32'h0;
      reg_file[7] <= 32'h0;
      reg_file[8] <= 32'h0;
      reg_file[9] <= 32'h0;
      reg_file[10] <= 32'h0;
      reg_file[11] <= 32'h0;
      reg_file[12] <= 32'h0;
      reg_file[13] <= 32'h0;
      reg_file[14] <= 32'h0;
      reg_file[15] <= 32'h0;
      reg_file[16] <= 32'h0;
      reg_file[17] <= 32'h0;
      reg_file[18] <= 32'h0;
      reg_file[19] <= 32'h0;
      reg_file[20] <= 32'h0;
      reg_file[21] <= 32'h0;
      reg_file[22] <= 32'h0;
      reg_file[23] <= 32'h0;
      reg_file[24] <= 32'h0;
      reg_file[25] <= 32'h0;
      reg_file[26] <= 32'h0;
      reg_file[27] <= 32'h0;
      reg_file[28] <= 32'h0;
      reg_file[29] <= 32'h0;
      reg_file[30] <= 32'h0;
      reg_file[31] <= 32'h0;
    end else begin
      if (inst_mem[pc[5:2]][15:11] != 5'b00000) begin // if rd != $zero
        reg_file[inst_mem[pc[5:2]][15:11]] <= alu_out;
      end
    end

  // Program counter increment
  always @(posedge clk)
    if (reset) begin
      pc <= 32'h0;
    end else begin
      pc <= pc + 32'h4;
    end

  // Output
  always @(posedge clk)
    if (reset) begin
      $display("t0: %d", reg_file[8]);
      $display("t1: %d", reg_file[9]);
      $display("t2: %d", reg_file[10]);
      $display("t3: %d", reg_file[11]);
      $display("t4: %d", reg_file[12]);
      $display("t5: %d", reg_file[13]);
      $display("t6: %d", reg_file[14]);
    end

endmodule

module uart_transmitter(
    input sys_clk,
    input [7:0] data_in,
    input start,
    input ready,
    output reg tx,
    output reg done
);

    reg [3:0] state;
    reg [7:0] shift_reg;
    reg bit_count;

    parameter IDLE = 2'b00;
    parameter START_BIT = 2'b01;
    parameter DATA_BITS = 2'b10;
    parameter STOP_BIT = 2'b11;

    always @(posedge sys_clk) begin
        case(state)
            IDLE: begin
                if(start && ready) begin
                    shift_reg <= data_in;
                    bit_count <= 0;
                    tx <= 0;
                    done <= 0;
                    state <= START_BIT;
                end
            end
            START_BIT: begin
                tx <= 0;
                if(bit_count == 8) begin
                    bit_count <= 0;
                    state <= STOP_BIT;
                end else begin
                    bit_count <= bit_count + 1;
                    state <= DATA_BITS;
                end
            end
            DATA_BITS: begin
                tx <= shift_reg[0];
                shift_reg <= {shift_reg[6:0], 1'b0};
                if(bit_count == 8) begin
                    bit_count <= 0;
                    state <= STOP_BIT;
                end else begin
                    bit_count <= bit_count + 1;
                end
            end
            STOP_BIT: begin
                tx <= 1;
                done <= 1;
                state <= IDLE;
            end
            default: state <= IDLE;
        endcase
    end

endmodule

