module top_module (
    input clk,
    input d,
    input a,
    input b,
    output q
);

  // Implementing NOR gate using NAND gates
  wire nand1_out;
  wire nand2_out;
  wire nor_out;

  nand nand1(a, a, nand1_out);
  nand nand2(b, b, nand2_out);
  nand nand3(nand1_out, nand2_out, nor_out);

  // Implementing dual-edge triggered flip-flop using D flip-flop and XOR gate
  wire xor_out;
  wire dff_out;

  xor xor1(d, q, xor_out);
  dff dff1(xor_out, clk, dff_out);

  // Implementing functional module that takes in the outputs of the two given modules
  wire func_out;

  and and1(nor_out, dff_out, func_out);

  // Assigning final output
  assign q = func_out;

endmodule

