module wasca_nios2_gen2_0_cpu_nios2_avalon_reg (
    // inputs:
    address,
    clk,
    debugaccess,
    monitor_error,
    monitor_go,
    monitor_ready,
    reset_n,
    write,
    writedata,

    // outputs:
    oci_ienable,
    oci_reg_readdata,
    oci_single_step_mode,
    ocireg_ers,
    ocireg_mrs,
    take_action_ocireg
);

    output  [31:0] oci_ienable;
    output  [31:0] oci_reg_readdata;
    output        oci_single_step_mode;
    output        ocireg_ers;
    output        ocireg_mrs;
    output        take_action_ocireg;
    input   [8:0]  address;
    input          clk;
    input          debugaccess;
    input          monitor_error;
    input          monitor_go;
    input          monitor_ready;
    input          reset_n;
    input          write;
    input   [31:0] writedata;

    reg     [31:0] oci_ienable;
    wire            oci_reg_00_addressed;
    wire            oci_reg_01_addressed;
    wire    [31:0] oci_reg_readdata;
    reg             oci_single_step_mode;
    wire            ocireg_ers;
    wire            ocireg_mrs;
    wire            ocireg_sstep;
    wire            take_action_oci_intr_mask_reg;
    wire            take_action_ocireg;
    wire            write_strobe;

    // Determine if register 00 or 01 is being addressed
    assign oci_reg_00_addressed = address == 9'h100;
    assign oci_reg_01_addressed = address == 9'h101;

    // Determine if we are writing to the register
    assign write_strobe = write & debugaccess;

    // Determine if we need to take action on the registers
    assign take_action_ocireg = write_strobe & oci_reg_00_addressed;
    assign take_action_oci_intr_mask_reg = write_strobe & oci_reg_01_addressed;

    // Set the values of the registers
    assign ocireg_ers = writedata[1];
    assign ocireg_mrs = writedata[0];
    assign ocireg_sstep = writedata[3];

    // Read data from the addressed register
    assign oci_reg_readdata = oci_reg_00_addressed ? {28'b0, oci_single_step_mode, monitor_go,
        monitor_ready, monitor_error} :
        oci_reg_01_addressed ? oci_ienable :
        32'b0;

    // Set the value of the single-step mode register
    always @(posedge clk or negedge reset_n) begin
        if (reset_n == 0) begin
            oci_single_step_mode <= 1'b0;
        end else if (take_action_ocireg) begin
            oci_single_step_mode <= ocireg_sstep;
        end
    end

    // Set the value of the interrupt enable register
    always @(posedge clk or negedge reset_n) begin
        if (reset_n == 0) begin
            oci_ienable <= 32'b00000000000000000000000000001111;
        end else if (take_action_oci_intr_mask_reg) begin
            oci_ienable <= writedata | ~(32'b00000000000000000000000000001111);
        end
    end

endmodule

module binary_adder_4bit_twos_complement (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

    wire [3:0] A_twos_complement;
    wire [3:0] B_twos_complement;
    wire [4:0] sum;

    // Convert A to two's complement
    assign A_twos_complement = (A[3] == 1) ? ~A + 1 : A;

    // Convert B to two's complement
    assign B_twos_complement = (B[3] == 1) ? ~B + 1 : B;

    // Add A_twos_complement, B_twos_complement, and Cin
    ripple_adder_4bit adder (
        .A(A_twos_complement),
        .B(B_twos_complement),
        .Cin(Cin),
        .S(sum)
    );

    // Check if the result is negative
    assign S = (sum[4] == 1) ? ~sum[3:0] + 1 : sum[3:0];
    assign Cout = sum[4];

endmodule

module ripple_adder_4bit (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [4:0] S
);

    wire [3:0] S_internal;
    wire Cout_internal;

    // Add the LSBs and propagate the carry
    full_adder adder0 (
        .A(A[0]),
        .B(B[0]),
        .Cin(Cin),
        .S(S_internal[0]),
        .Cout(Cout_internal)
    );

    // Add the next bit and propagate the carry
    full_adder adder1 (
        .A(A[1]),
        .B(B[1]),
        .Cin(Cout_internal),
        .S(S_internal[1]),
        .Cout(Cout_internal)
    );

    // Add the next bit and propagate the carry
    full_adder adder2 (
        .A(A[2]),
        .B(B[2]),
        .Cin(Cout_internal),
        .S(S_internal[2]),
        .Cout(Cout_internal)
    );

    // Add the MSB and generate the carry-out
    full_adder adder3 (
        .A(A[3]),
        .B(B[3]),
        .Cin(Cout_internal),
        .S(S_internal[3]),
        .Cout(S_internal[4])
    );

    assign S = S_internal;

endmodule

module full_adder (
    input A,
    input B,
    input Cin,
    output S,
    output Cout
);

    assign S = A ^ B ^ Cin;
    assign Cout = (A & B) | (A & Cin) | (B & Cin);

endmodule

module pipeline (
  input clk,
  input reset,
  input [7:0] instruction,
  output reg [31:0] regfile [15:0]
);

  reg [7:0] pc;
  reg [7:0] pc_next;
  reg [31:0] a;
  reg [31:0] b;
  reg [31:0] alu_out;
  reg [3:0] opcode;
  reg [3:0] rs;
  reg [3:0] rt;
  reg [3:0] rd;
  reg [1:0] stage;

  always @(posedge clk) begin
    if (reset) begin
      pc <= 8'h00;
      pc_next <= 8'h01;
      a <= 0;
      b <= 0;
      alu_out <= 0;
      opcode <= 0;
      rs <= 0;
      rt <= 0;
      rd <= 0;
      stage <= 0;
      regfile <= 0;
    end else begin
      case (stage)
        0: begin // Fetch stage
          pc <= pc_next;
          pc_next <= pc + 1;
          opcode <= instruction[7:4];
          rs <= instruction[3:0];
          stage <= 1;
        end
        1: begin // Decode stage
          rt <= instruction[3:0];
          rd <= instruction[7:4];
          a <= regfile[rs];
          b <= regfile[rt];
          stage <= 2;
        end
        2: begin // Execute stage
          case (opcode)
            4'b0000: alu_out <= a + b; // ADD
            4'b0001: alu_out <= a - b; // SUB
            4'b0010: alu_out <= a & b; // AND
            4'b0011: alu_out <= ~(a & b); // NAND
          endcase
          regfile[rd] <= alu_out;
          stage <= 0;
        end
      endcase
    end
  end

endmodule

module vending_machine (
  input clk,
  input rst,
  input [1:0] coin,
  input [1:0] product,
  output reg dispense,
  output reg return,
  output reg [3:0] price,
  output reg [3:0] inserted
);

  // Define constants for product prices
  parameter PRICE_1 = 5;
  parameter PRICE_2 = 10;
  parameter PRICE_3 = 20;

  // Define state variables
  reg [3:0] money;
  reg [3:0] selected_product;
  reg [3:0] selected_price;
  reg [1:0] coin_value;
  reg [1:0] coin_inserted;

  // Define state machine states
  localparam IDLE = 2'b00;
  localparam ACCEPT_COIN = 2'b01;
  localparam SELECT_PRODUCT = 2'b10;
  localparam DISPENSE_PRODUCT = 2'b11;

  // Define state machine current state
  reg [1:0] state;

  // Define combinational logic for selected price
  always @(*) begin
    case (product)
      2'b00: selected_price = PRICE_1;
      2'b01: selected_price = PRICE_2;
      2'b10: selected_price = PRICE_3;
      default: selected_price = 0;
    endcase
  end

  // Define state machine transitions and outputs
  always @(posedge clk) begin
    if (rst) begin
      state <= IDLE;
      money <= 0;
      selected_product <= 0;
      selected_price <= 0;
      coin_value <= 0;
      coin_inserted <= 0;
      dispense <= 0;
      return <= 0;
      price <= 0;
      inserted <= 0;
    end
    else begin
      case (state)
        IDLE: begin
          if (coin == 2'b00 || coin == 2'b01 || coin == 2'b10) begin
            state <= ACCEPT_COIN;
            coin_value <= coin;
          end
          else begin
            state <= IDLE;
          end
        end
        ACCEPT_COIN: begin
          coin_inserted <= coin_inserted + coin_value;
          inserted <= coin_inserted;
          if (coin_inserted >= selected_price) begin
            state <= DISPENSE_PRODUCT;
          end
          else begin
            state <= SELECT_PRODUCT;
          end
        end
        SELECT_PRODUCT: begin
          selected_product <= product;
          selected_price <= selected_price;
          price <= selected_price;
          state <= ACCEPT_COIN;
        end
        DISPENSE_PRODUCT: begin
          money <= money + coin_inserted;
          coin_inserted <= 0;
          inserted <= coin_inserted;
          if (selected_product == 2'b00 && coin_inserted == PRICE_1) begin
            dispense <= 1;
          end
          else if (selected_product == 2'b01 && coin_inserted == PRICE_2) begin
            dispense <= 1;
          end
          else if (selected_product == 2'b10 && coin_inserted == PRICE_3) begin
            dispense <= 1;
          end
          else begin
            return <= 1;
          end
          state <= IDLE;
        end
        default: state <= IDLE;
      endcase
    end
  end

endmodule

module vd0bb30 #(
 parameter v6c5139 = 1
) (
 input [4:0] vd03823,
 output v4642b6,
 output [4:0] vb4c454
);
 localparam p1 = v6c5139;
 wire w0;
 wire [0:4] w2;
 wire [0:4] w3;
 assign v4642b6 = w0;
 assign w2 = vd03823;
 assign vb4c454 = w3;

 // If v6c5139 is 1, output 1 on v4642b6 if vd03823 is greater than or equal to 5
 // Otherwise, output 1 on v4642b6 if vd03823 is less than 5
 always @(*) begin
   if (v6c5139 == 1) begin
     if (vd03823 >= 5) begin
       w0 = 1;
     end else begin
       w0 = 0;
     end
   end else begin
     if (vd03823 < 5) begin
       w0 = 1;
     end else begin
       w0 = 0;
     end
   end
 end

 // If v6c5139 is 1, output vd03823 on vb4c454
 // Otherwise, output the bitwise negation of vd03823 on vb4c454
 always @(*) begin
   if (v6c5139 == 1) begin
     w3 = vd03823;
   end else begin
     w3 = ~vd03823;
   end
 end

endmodule

