module VCO_interface (
  input control_voltage,
  input ref_clock,
  output out_clock
);

  reg [31:0] counter;
  reg [31:0] threshold;

  always @ (posedge ref_clock) begin
    if (counter >= threshold) begin
      counter <= 0;
      out_clock <= ~out_clock;
    end else begin
      counter <= counter + 1;
    end
  end

  always @ (control_voltage) begin
    threshold <= control_voltage * 100;
  end

endmodule

