module top_module (
    input clk,
    input reset,      // Asynchronous active-high reset
    input [7:0] a,
    input [7:0] b,
    input load,       // Active-high parallel load input
    input [3:0] load_value, // 4-bit load value
    output [7:0] s,
    output overflow,
    output [3:0] q,
    output carry_out,
    output led);

    wire [7:0] adder_out;
    wire adder_overflow;

    wire [3:0] counter_out;
    wire counter_carry_out;

    wire enable;
    wire [7:0] mux_out;

    // Instantiate the 8-bit adder module
    adder_module adder_inst (
        .a(a),
        .b(b),
        .s(adder_out),
        .overflow(adder_overflow)
    );

    // Instantiate the 4-bit binary counter module
    binary_counter counter_inst (
        .clk(clk),
        .reset(reset),
        .load(load),
        .load_value(load_value),
        .q(counter_out),
        .carry_out(counter_carry_out)
    );

    // Enable the adder and counter modules when the counter reaches its maximum value
    assign enable = counter_carry_out;

    // Multiplexer to select between the adder output and the counter output
    mux_2to1 mux_inst (
        .a(adder_out),
        .b(counter_out),
        .sel(load),
        .out(mux_out)
    );

    // Output the selected value
    assign s = mux_out;

    // Output overflow signal from the adder module
    assign overflow = adder_overflow;

    // Output the counter value
    assign q = counter_out;

    // Output the carry-out signal from the counter module
    assign carry_out = counter_carry_out;

    // LED indicator for when the counter reaches its maximum value
    assign led = counter_out == 15;

endmodule

// 8-bit adder module using carry-lookahead adder
module adder_module (
    input [7:0] a,
    input [7:0] b,
    output [7:0] s,
    output overflow);

    wire [7:0] p;
    wire [7:0] g;
    wire [7:0] c;

    // Generate the carry signals using the carry-lookahead adder
    generate
        genvar i;
        for (i = 0; i < 8; i = i + 1) begin
            assign p[i] = a[i] ^ b[i];
            assign g[i] = a[i] & b[i];
        end

        assign c[0] = 1'b0;
        for (i = 1; i < 8; i = i + 1) begin
            assign c[i] = g[i-1] | (p[i-1] & c[i-1]);
        end
    endgenerate

    // Calculate the sum and overflow signals
    assign s = a + b + c;
    assign overflow = (a[7] == b[7]) && (s[7] != a[7]);

endmodule

// 4-bit binary counter module
module binary_counter (
    input clk,
    input reset,
    input load,
    input [3:0] load_value,
    output reg [3:0] q,
    output reg carry_out);

    always @(posedge clk or negedge reset) begin
        if (reset == 0) begin
            q <= 4'b0101;   // Reset to 5
            carry_out <= 1'b0;
        end else if (load == 1) begin
            q <= load_value;
            carry_out <= 1'b0;
        end else if (q == 4'b1111) begin
            q <= 4'b0000;
            carry_out <= 1'b1;
        end else begin
            q <= q + 1;
            carry_out <= 1'b0;
        end
    end

endmodule

// 2-to-1 multiplexer module
module mux_2to1 (
    input [7:0] a,
    input [7:0] b,
    input sel,
    output reg [7:0] out);

    always @(a, b, sel) begin
        if (sel == 1) begin
            out <= b;
        end else begin
            out <= a;
        end
    end

endmodule

