module memory_interface (
    input clk_i,
    input rst_i,
    input rd_i,
    input [31:0] pc_i,
    input invalidate_i,
    input [31:0] wbm_dat_i,
    input wbm_stall_i,
    input wbm_ack_i,
    output reg [31:0] instruction_o,
    output reg valid_o,
    output reg [31:0] wbm_addr_o,
    output reg [2:0] wbm_cti_o,
    output reg wbm_cyc_o,
    output reg wbm_stb_o
);

// Registers
reg [31:0] mem [0:1023];
reg [31:0] mem_valid [0:1023];
reg [31:0] wbm_data;
reg [31:0] instruction;
reg [31:0] address;
reg [31:0] pc;
reg [31:0] wbm_addr;
reg [2:0] wbm_cti;
reg wbm_cyc;
reg wbm_stb;
reg wbm_ack;
reg valid;
reg [1:0] state;
reg [1:0] stall_state;

// Constants
localparam STATE_IDLE = 2'b00;
localparam STATE_READ = 2'b01;
localparam STATE_WRITE = 2'b10;
localparam STALL_WAIT = 2'b00;
localparam STALL_ACK = 2'b01;

// Initialize registers
integer i;
initial begin
    for (i = 0; i < 1024; i = i + 1) begin
        mem[i] = 0;
        mem_valid[i] = 0;
    end
    instruction = 0;
    address = 0;
    pc = 0;
    wbm_addr = 0;
    wbm_cti = 0;
    wbm_cyc = 0;
    wbm_stb = 0;
    wbm_ack = 0;
    valid = 0;
    state = STATE_IDLE;
    stall_state = STALL_WAIT;
end

// State machine
always @(posedge clk_i) begin
    if (rst_i) begin
        state <= STATE_IDLE;
        stall_state <= STALL_WAIT;
        wbm_cyc <= 0;
        valid <= 0;
    end else begin
        case (state)
            STATE_IDLE: begin
                if (rd_i) begin
                    address <= pc_i;
                    state <= STATE_READ;
                end else if (invalidate_i) begin
                    for (i = 0; i < 1024; i = i + 1) begin
                        mem_valid[i] <= 0;
                    end
                end else if (wbm_stb_o && !wbm_cyc) begin
                    wbm_addr <= wbm_addr_o;
                    wbm_data <= wbm_dat_i;
                    wbm_cti <= 0;
                    wbm_cyc <= 1;
                    wbm_stb <= 1;
                    stall_state <= STALL_WAIT;
                    state <= STATE_WRITE;
                end
            end
            STATE_READ: begin
                instruction <= mem[address];
                valid <= mem_valid[address];
                state <= STATE_IDLE;
            end
            STATE_WRITE: begin
                if (wbm_ack_i && stall_state == STALL_ACK) begin
                    wbm_cyc <= 0;
                    wbm_stb <= 0;
                    stall_state <= STALL_WAIT;
                    state <= STATE_IDLE;
                    mem[wbm_addr] <= wbm_data;
                    mem_valid[wbm_addr] <= 1;
                end else if (wbm_stall_i) begin
                    stall_state <= STALL_ACK;
                end
            end
        endcase
    end
end

// Output signals
assign instruction_o = instruction;
assign valid_o = valid;
assign wbm_addr_o = wbm_addr;
assign wbm_cti_o = wbm_cti;
assign wbm_cyc_o = wbm_cyc;
assign wbm_stb_o = wbm_stb;

endmodule

