module carry_select_adder (
    input [15:0] A,
    input [15:0] B,
    input Cin,
    output reg [15:0] S,
    output reg Cout
);

reg [15:0] P, G, C1, C2;

assign P = A ^ B;
assign G = A & B;

always @ (posedge clk) begin
    C1 <= {1'b0, Cin};
    C2 <= {1'b1, Cout};
    S <= P ^ Cout;
    Cout <= (G & Cout) | (P & C1) | (P & G & C2);
end

endmodule

module top_module (
