    wire signed [31:0] multiplier_out;

    add_sub_module add_sub_inst (
        .A(A),
        .B(O),
        .C(C),
        .Y(adder_out),
        .Bout(B)
    );

    signed_multiplier_module multiplier_inst (
        .A(adder_out),
        .B(N),
        .P(multiplier_out)
    );

