module add_sub_module (
    input signed [3:0] A,
    input signed [3:0] B,
    input C,
    output reg signed [3:0] Y,
    output reg Bout
);

    always @(*) begin
        if (C == 1'b0) begin
            Y = A + B;
            Bout = (Y < 0);
        end else begin
            Y = A - B;
            Bout = (Y < 0);
        end
    end

endmodule

module signed_multiplier_module (
