module eth_rxstatem (MRxClk, Reset, MRxDV, ByteCntEq0, ByteCntGreat2, Transmitting, MRxDEq5, MRxDEqD, 
                     IFGCounterEq24, ByteCntMaxFrame, StateData, StateIdle, StatePreamble, StateSFD, 
                     StateDrop
                    );

parameter Tp = 1;

input         MRxClk;
input         Reset;
input         MRxDV;
input         ByteCntEq0;
input         ByteCntGreat2;
input         MRxDEq5;
input         Transmitting;
input         MRxDEqD;
input         IFGCounterEq24;
input         ByteCntMaxFrame;

output [1:0]  StateData;
output        StateIdle;
output        StateDrop;
output        StatePreamble;
output        StateSFD;

reg           StateData0;
reg           StateData1;
reg           StateIdle;
reg           StateDrop;
reg           StatePreamble;
reg           StateSFD;

wire          StartIdle;
wire          StartDrop;
wire          StartData0;
wire          StartData1;
wire          StartPreamble;
wire          StartSFD;


// Defining the next state
assign StartIdle = ~MRxDV & (StateDrop | StatePreamble | StateSFD | (|StateData));

assign StartPreamble = MRxDV & ~MRxDEq5 & (StateIdle & ~Transmitting);

assign StartSFD = MRxDV & MRxDEq5 & (StateIdle & ~Transmitting | StatePreamble);

assign StartData0 = MRxDV & (StateSFD & MRxDEqD & IFGCounterEq24 | StateData1);

assign StartData1 = MRxDV & StateData0 & (~ByteCntMaxFrame);

assign StartDrop = MRxDV & (StateIdle & Transmitting | StateSFD & ~IFGCounterEq24 &  
			    MRxDEqD |  StateData0 &  ByteCntMaxFrame);

// Rx State Machine
always @ (posedge MRxClk or posedge Reset)
begin
  if(Reset)
    begin
      StateIdle     <=  1'b0;
      StateDrop     <=  1'b1;
      StatePreamble <=  1'b0;
      StateSFD      <=  1'b0;
      StateData0    <=  1'b0;
      StateData1    <=  1'b0;
    end
  else
    begin
      if(StartPreamble | StartSFD | StartDrop)
        StateIdle <=  1'b0;
      else
      if(StartIdle)
        StateIdle <=  1'b1;

      if(StartIdle)
        StateDrop <=  1'b0;
      else
      if(StartDrop)
        StateDrop <=  1'b1;

      if(StartSFD | StartIdle | StartDrop)
        StatePreamble <=  1'b0;
      else
      if(StartPreamble)
        StatePreamble <=  1'b1;

      if(StartPreamble | StartIdle | StartData0 | StartDrop)
        StateSFD <=  1'b0;
      else
      if(StartSFD)
        StateSFD <=  1'b1;

      if(StartIdle | StartData1 | StartDrop)
        StateData0 <=  1'b0;
      else
      if(StartData0)
        StateData0 <=  1'b1;

      if(StartIdle | StartData0 | StartDrop)
        StateData1 <=  1'b0;
      else
      if(StartData1)
        StateData1 <=  1'b1;
    end
end

assign StateData[1:0] = {StateData1, StateData0};

endmodule

module adder
(
	input                     clk      ,
	input                     rst      ,
	input      [31:0]         ain      ,
	input      [31:0]         bin      ,
	output reg [31:0]         result   ,
	output reg [31:0]         statistic 
);

//-------------------------------------------------------------------
// Signal Declaration
//-------------------------------------------------------------------

	reg [31:0] result_last;

//-------------------------------------------------------------------
// Main Computation
//-------------------------------------------------------------------

	/* the result & result_last register */
	always @(posedge clk or posedge rst) begin
		if (rst) begin
			result      <= 32'h0;
			result_last <= 32'h0;
		end else begin
			result      <= ain + bin;
			result_last <= result;
		end
	end

	/* the statistic register */
	always @(posedge clk or posedge rst) begin
		if (rst) begin
			statistic[31:16] <= 16'hc001;
			statistic[15:0]  <= 16'h0;
		end else begin
			if ( result != result_last ) begin
				statistic[15:0] <= statistic[15:0] + 16'h1;
			end
		end
	end

endmodule

module magnitude_comparator (
    input [3:0] A,
    input [3:0] B,
    output reg GT,
    output reg EQ
);

always @(*) begin
    if (A > B) begin
        GT = 1;
        EQ = 0;
    end
    else if (A == B) begin
        GT = 0;
        EQ = 1;
    end
    else begin
        GT = 0;
        EQ = 0;
    end
end

endmodule

module data_buffer(
    input [31:0] data_in,
    input [6:0] ecc_in,
    input tag_in,
    input valid_in,
    input control_tag_in,
    input error_in,
    input dequeue_in,
    input por_req_in,
    input clk,
    input reset,
    output [31:0] data_out,
    output [6:0] ecc_out,
    output tag_out,
    output valid_out,
    output control_tag_out,
    output error_out,
    output dequeue_out,
    output por_req_out
);

reg [31:0] data_reg;
reg [6:0] ecc_reg;
reg tag_reg;
reg valid_reg;
reg control_tag_reg;
reg error_reg;
reg dequeue_reg;
reg por_req_reg;

always @(posedge clk) begin
    if (reset) begin
        data_reg <= 0;
        ecc_reg <= 0;
        tag_reg <= 0;
        valid_reg <= 0;
        control_tag_reg <= 0;
        error_reg <= 0;
        dequeue_reg <= 0;
        por_req_reg <= 1;
    end else begin
        if (por_req_in) begin
            por_req_reg <= 0;
        end
        if (control_tag_in) begin
            control_tag_reg <= 1;
        end else if (dequeue_in) begin
            control_tag_reg <= 0;
        end
        if (valid_in) begin
            data_reg <= data_in;
            ecc_reg <= ecc_in;
            tag_reg <= tag_in;
            valid_reg <= 1;
        end
        if (dequeue_in) begin
            valid_reg <= 0;
            dequeue_reg <= 1;
        end
        if (error_in) begin
            error_reg <= 1;
        end
    end
end

assign data_out = data_reg;
assign ecc_out = ecc_reg;
assign tag_out = tag_reg;
assign valid_out = valid_reg;
assign control_tag_out = control_tag_reg;
assign error_out = error_reg;
assign dequeue_out = dequeue_reg;
assign por_req_out = por_req_reg;

endmodule

module comparator (
    input [1:0] in_0,
    input [1:0] in_1,
    output reg [1:0] out
);

    always @(*) begin
        if (in_0 > in_1) begin
            out = 2'b01;
        end else if (in_0 == in_1) begin
            out = 2'b10;
        end else begin
            out = 2'b00;
        end
    end

endmodule

module memory(
    input [7:0] addr,
    input [7:0] data_in,
    input write_enable,
    input [15:0] addr16,
    output reg [7:0] data_out1,
    output reg [7:0] data_out2,
    output reg [7:0] data_out3,
    output reg [7:0] data_out4
);

reg [7:0] data1;
reg [7:0] data2;
reg [7:0] data3;
reg [7:0] data4;

always @ (addr) begin
    case (addr)
        8'h11    : data1 = data_in;
        8'h22    : data2 = data_in;
        default : 
            if(write_enable)
                $display("Invalid address");
    endcase
end

always @ (addr) begin
    case (addr)
        8'h11    : data_out1 = data1;
        8'h22    : data_out1 = data2;
        default : data_out1 = 8'h00;
    endcase
end

always @ (addr) begin
    case (addr)
        8'h11    : data_out2 = data1;
        8'h22    : data_out2 = data2;
        default : data_out2 = 8'h00;
    endcase
end

always @ (addr16) begin
    case (addr16)
        16'h0011 : data3 = data_in;
        16'h0022 : data4 = data_in;
        default : 
            if(write_enable)
                $display("Invalid address");
    endcase
end

always @ (addr16) begin
    case (addr16)
        16'h0011 : data_out3 = data3;
        16'h0022 : data_out3 = data4;
        default : data_out3 = 8'h00;
    endcase
end

always @ (addr) begin
    case ({addr[7:0], 1'b0})
        8'h11   : data_out4 = data1;
        8'h22   : data_out4 = data2;
        default : data_out4 = 8'h00;
    endcase
end

endmodule

module spi_master (
  input clk,
  input rst,
  input mosi,
  input cs,
  input sck_div,
  output reg miso
);

reg [7:0] shift_reg;
reg [2:0] bit_counter;
reg sck;
reg cs_n;

always @(posedge clk) begin
  if (rst) begin
    shift_reg <= 8'h00;
    bit_counter <= 3'd0;
    sck <= 1'b0;
    cs_n <= 1'b1;
    miso <= 1'b0;
  end else begin
    if (!cs_n && sck) begin
      shift_reg <= {mosi, shift_reg[7:1]};
      bit_counter <= bit_counter + 1;
      if (bit_counter == 3'd7) begin
        miso <= shift_reg[0];
        bit_counter <= 3'd0;
      end
    end
    sck <= ~sck;
    if (sck) begin
      cs_n <= cs;
    end
  end
end

assign sck = clk / sck_div;

endmodule

module spi_slave (
  input clk,
  input rst,
  input miso,
  input cs,
  input sck_div,
  output reg mosi
);

reg [7:0] shift_reg;
reg [2:0] bit_counter;
reg sck;
reg cs_n;

always @(posedge clk) begin
  if (rst) begin
    shift_reg <= 8'h00;
    bit_counter <= 3'd0;
    sck <= 1'b0;
    cs_n <= 1'b1;
    mosi <= 1'b0;
  end else begin
    sck <= ~sck;
    if (sck) begin
      cs_n <= cs;
      if (!cs_n) begin
        shift_reg <= {shift_reg[6:0], miso};
        bit_counter <= bit_counter + 1;
        if (bit_counter == 3'd7) begin
          mosi <= shift_reg[7];
          bit_counter <= 3'd0;
        end
      end
    end
  end
end

assign sck = clk / sck_div;

endmodule

