module memory_comp_decomp (
  input clk, // clock signal
  input rst, // reset signal
  input [2**N-1:0] in_data, // input memory array of size 2^N
  input enable, // enable signal for the module
  input compress, // select signal for compression mode (if compress=1, then compress mode is selected)
  input decompress, // select signal for decompression mode (if decompress=1, then decompress mode is selected)
  output [2**N-1:0] out_data, // output memory array of size 2^N
  output [N-1:0] compressed_len // length of the compressed data (in number of words)
);

parameter N = 8; // size of the memory array (2^N)

reg [2**N-1:0] compressed_data; // compressed data storage
reg [N-1:0] compressed_words; // number of compressed words

reg [2**N-1:0] decompressed_data; // decompressed data storage

reg [2**N-1:0] prev_data; // previous data value
reg [2**N-1:0] curr_data; // current data value
reg [1:0] count; // count of consecutive values

integer i; // loop index

always @(posedge clk) begin
  if (rst) begin
    compressed_data <= 0;
    compressed_words <= 0;
    decompressed_data <= 0;
    prev_data <= 0;
    curr_data <= 0;
    count <= 0;
  end
  else if (enable) begin
    if (compress) begin
      compressed_words <= 0;
      count <= 0;
      for (i = 0; i < 2**N; i = i + 1) begin
        curr_data <= in_data[i];
        if (curr_data == prev_data) begin
          count <= count + 1;
        end
        else begin
          if (count > 0) begin
            compressed_data[(i-1)*2+1:i*2] <= count;
            compressed_words <= compressed_words + 1;
          end
          compressed_data[i*2**N:(i-1)*2**N+1] <= curr_data;
          count <= 1;
          prev_data <= curr_data;
        end
      end
      if (count > 0) begin
        compressed_data[(2**N-1)*2+1:2**N*2] <= count;
        compressed_words <= compressed_words + 1;
      end
      out_data <= compressed_data;
      compressed_len <= compressed_words;
    end
    else if (decompress) begin
      compressed_words <= compressed_len;
      count <= 0;
      for (i = 0; i < 2**N; i = i + 1) begin
        if (count == 0) begin
          compressed_words <= compressed_words - 1;
          count <= compressed_data[(i*2)+1:i*2];
          decompressed_data[i] <= compressed_data[i*2**N:(i-1)*2**N+1];
        end
        else begin
          count <= count - 1;
          decompressed_data[i] <= decompressed_data[i-1];
        end
      end
      out_data <= decompressed_data;
    end
  end
end

endmodule

module top_module (
    input signed [3:0] A, // 4-bit signed input for Booth multiplier
    input signed [3:0] B, // 4-bit signed input for Booth multiplier
    input [1:0] SEL, // Select input for multiplexer
    output [3:0] Q // 4-bit output from selected input of multiplexer
);

reg signed [3:0] C; // Output of Booth multiplier

booth_multiplier booth_inst (
    .A(A),
    .B(B),
    .C(C)
);

mux_encoder mux_inst (
    .A(A),
    .B(B),
    .C(C),
    .D(4'b0), // Unused input
    .SEL(SEL),
    .Q(Q)
);

endmodule

module booth_multiplier (
    input signed [3:0] A,
    input signed [3:0] B,
    output reg signed [3:0] C
);

reg signed [7:0] P; // Product of A and B
reg [2:0] count; // Counter for Booth's algorithm

always @(*) begin
    P = A * {1'b0, B}; // Pad B with a zero bit
    C = 4'b0; // Initialize C to zero
    count = 3; // Initialize count to 3
    while (count >= 0) begin
        if (P[2*count+1:2*count] == 2'b01) begin
            C = C + (B << count);
        end else if (P[2*count+1:2*count] == 2'b10) begin
            C = C - (B << count);
        end
        count = count - 1;
    end
end

endmodule

module mux_encoder (
    input [3:0] A,
    input [3:0] B,
    input [3:0] C,
    input [3:0] D,
    input [1:0] SEL,
    output [3:0] Q
);

reg [3:0] priority; // Priority of each input

always @(*) begin
    priority[0] = A[3];
    priority[1] = B[3];
    priority[2] = C[3];
    priority[3] = D[3];
    case (SEL)
        2'b00: Q = priority[0] ? A : priority[1] ? B : priority[2] ? C : D;
        2'b01: Q = priority[1] ? B : priority[0] ? A : priority[2] ? C : D;
        2'b10: Q = priority[2] ? C : priority[0] ? A : priority[1] ? B : D;
        2'b11: Q = priority[3] ? D : priority[0] ? A : priority[1] ? B : C;
    endcase
end

endmodule

module mux_4to1_with_and_assign (
  input [7:0] a,
  input [7:0] b,
  input [7:0] c,
  input [7:0] d,
  input [1:0] sel,
  output reg [7:0] out
);

assign out = (sel == 2'b11) ? (a & b) : (sel == 2'b00 ? a : (sel == 2'b01 ? b : (sel == 2'b10 ? c : d)));

endmodule
module mux_4to1_with_and_if (
  input [7:0] a,
  input [7:0] b,
  input [7:0] c,
  input [7:0] d,
  input [1:0] sel,
  output reg [7:0] out
);

always @(*) begin
  if (sel == 2'b11) begin
    out = a & b;
  end else if (sel == 2'b00) begin
    out = a;
  end else if (sel == 2'b01) begin
    out = b;
  end else if (sel == 2'b10) begin
    out = c;
  end else begin
    out = d;
