reg [31:0] stb_count;		// @ 04
reg [31:0] ack_count;		// @ 08
reg [12:0] capture_wadr;	// @ 0c
reg [11:0] capture_radr;	// @ 10
reg [fml_depth:0] capture_do;	// @ 14

