module priority_encoder(
    input [7:0] in,
    output reg [2:0] out
);

always @(*) begin
    case(in)
        8'b00000001, 8'b00000010, 8'b00000100, 8'b00001000, 8'b00010000, 8'b00100000, 8'b01000000, 8'b10000000: out = 0;
        8'b00000011, 8'b00000101, 8'b00001001, 8'b00010001, 8'b00100001, 8'b01000001, 8'b10000001: out = 1;
        8'b00000111, 8'b00001101, 8'b00011001, 8'b00101001, 8'b01001001, 8'b10001001: out = 2;
        8'b00001111, 8'b00011101, 8'b00111001, 8'b01101001, 8'b11001001: out = 3;
        8'b00011111, 8'b00111101, 8'b01111001, 8'b11101001: out = 4;
        8'b00111111, 8'b01111101, 8'b11111001: out = 5;
        8'b01111111, 8'b11111101: out = 6;
        8'b11111111: out = 7;
        default: out = 0;
    endcase
end

