module binary_search (
    input wire clk,
    input wire reset,
    input wire start,
    input wire [31:0] array [0:99],
    input wire [7:0] array_len,
    input wire [31:0] target,
    output wire found,
    output wire [7:0] index
);

reg [31:0] low, high, mid;
reg [7:0] i;
reg done;

always @(posedge clk or negedge reset) begin
    if (!reset) begin
        low <= 0;
        high <= 0;
        mid <= 0;
        i <= 0;
        done <= 0;
        found <= 0;
        index <= -1;
    end else begin
        if (start && !done) begin
            low <= 0;
            high <= array_len - 1;
            found <= 0;
            index <= -1;
            done <= 0;
            i <= 0;
        end else if (i < array_len && !done) begin
            mid <= (low + high) / 2;
            if (array[mid] == target) begin
                found <= 1;
                index <= mid;
                done <= 1;
            end else if (array[mid] > target) begin
                high <= mid - 1;
            end else begin
                low <= mid + 1;
            end
            i <= i + 1;
        end else if (i >= array_len && !done) begin
            found <= 0;
            index <= -1;
            done <= 1;
        end
    end
end

endmodule

module ddr3_sequencer (
  input clk,
  input [18:0] cpu_d_address,
  input cpu_d_read,
  input [31:0] cpu_d_readdata,
  input cpu_d_wait,
  input cpu_d_write,
  input [31:0] cpu_d_writedata,
  input jrst_n,
  input [15:0] trc_ctrl,
  output reg [35:0] atm,
  output reg [35:0] dtm
);

  reg record_load_addr;
  reg record_load_data;
  reg record_store_addr;
  reg record_store_data;

  always @(posedge clk or negedge jrst_n) begin
    if (~jrst_n) begin
      atm <= 0;
      dtm <= 0;
    end else begin
      if (cpu_d_write & ~cpu_d_wait) begin
        if (trc_ctrl[0]) begin
          record_store_addr <= 1;
          atm <= {4'b0101, cpu_d_address};
        end else begin
          record_store_addr <= 0;
          atm <= {4'b0000, cpu_d_address};
