          record_store_data <= 0;
          dtm <= {4'b0000, cpu_d_writedata};
        end
      end else if (cpu_d_read & ~cpu_d_wait) begin
        if (trc_ctrl[2]) begin
          record_load_addr <= 1;
          atm <= {4'b0100, cpu_d_address};
        end else begin
          record_load_addr <= 0;
          atm <= {4'b0000, cpu_d_address};
        end
        if (trc_ctrl[3]) begin
          record_load_data <= 1;
          dtm <= {4'b0110, cpu_d_readdata};
        end else begin
          record_load_data <= 0;
          dtm <= {4'b0000, cpu_d_readdata};
        end
      end else begin
        atm <= 0;
        dtm <= 0;
      end
    end
  end

