module pipelined_processor(
  input clk,
  input rst,
  input [31:0] instr_mem_rd_addr,
  input [31:0] data_mem_rd_addr,
  input [31:0] data_mem_wr_addr,
  input [31:0] data_mem_wr_data,
  input [4:0] reg_file_rd_addr_1,
  input [4:0] reg_file_rd_addr_2,
  input [4:0] reg_file_wr_addr,
  input [31:0] reg_file_wr_data,
  input en_instr_mem_rd,
  input en_data_mem_rd,
  input en_data_mem_wr,
  input en_reg_file_rd_1,
  input en_reg_file_rd_2,
  input en_reg_file_wr,
  output [31:0] instr_mem_rd_data,
  output [31:0] data_mem_rd_data,
  output [31:0] reg_file_rd_data_1,
  output [31:0] reg_file_rd_data_2
);

// Instruction Fetch stage
reg [31:0] pc;
reg [31:0] instr;

always @(posedge clk) begin
  if (rst) begin
    pc <= 0;
  end else begin
    pc <= pc + 4;
  end
end

assign instr_mem_rd_data = (en_instr_mem_rd) ? $readmemh("instr_mem.mem", instr_mem_rd_addr >> 2) : 0;
assign instr = instr_mem_rd_data;

// Instruction Decode stage
reg [4:0] rs1_addr;
reg [4:0] rs2_addr;
reg [4:0] rd_addr;
reg [31:0] imm;

always @(*) begin
  rs1_addr = instr[19:15];
  rs2_addr = instr[24:20];
  rd_addr = instr[11:7];
  imm = {{19{instr[31]}}, instr[31:20]};
end

assign reg_file_rd_data_1 = (en_reg_file_rd_1) ? $readmemh("reg_file.mem", reg_file_rd_addr_1) : 0;
assign reg_file_rd_data_2 = (en_reg_file_rd_2) ? $readmemh("reg_file.mem", reg_file_rd_addr_2) : 0;

// Execute stage
reg [31:0] alu_result;
reg [31:0] mem_addr;

always @(*) begin
  case (instr[6:0])
    7'h33: alu_result = reg_file_rd_data_1 + reg_file_rd_data_2; // add
    7'h3b: alu_result = reg_file_rd_data_1 - reg_file_rd_data_2; // sub
    7'h7: alu_result = reg_file_rd_data_1 & reg_file_rd_data_2; // and
    7'h6: alu_result = reg_file_rd_data_1 | reg_file_rd_data_2; // or
    7'h23: alu_result = reg_file_rd_data_1 + imm; // lw
    7'h2b: mem_addr = reg_file_rd_data_1 + imm; // sw
  endcase
end

// Memory Access stage
reg [31:0] mem_data;

always @(posedge clk) begin
  if (en_data_mem_rd) begin
    mem_data <= $readmemh("data_mem.mem", data_mem_rd_addr >> 2);
  end else if (en_data_mem_wr) begin
    $writememh("data_mem.mem", data_mem_wr_data, data_mem_wr_addr >> 2);
  end
end

// Write Back stage
always @(posedge clk) begin
  if (en_reg_file_wr) begin
    $writememh("reg_file.mem", reg_file_wr_data, reg_file_wr_addr);
  end else begin
    case (instr[6:0])
      7'h33: $writememh("reg_file.mem", alu_result, rd_addr); // add
      7'h3b: $writememh("reg_file.mem", alu_result, rd_addr); // sub
      7'h7: $writememh("reg_file.mem", alu_result, rd_addr); // and
      7'h6: $writememh("reg_file.mem", alu_result, rd_addr); // or
      7'h23: $writememh("reg_file.mem", mem_data, rd_addr); // lw
      default: $writememh("reg_file.mem", 0, rd_addr); // do nothing
    endcase
  end
end

