module uart_tx (
  input clk,
  input rst,
  input [7:0] data,
  input [31:0] baud,
  output reg tx
);

  reg [3:0] count;
  reg [7:0] tx_reg;
  reg start_bit;
  reg [1:0] stop_bits;

  always @(posedge clk) begin
    if (rst) begin
      count <= 0;
      tx_reg <= 0;
      start_bit <= 1;
      stop_bits <= 3'b001;
      tx <= 1;
    end else if (count == 0) begin
      tx_reg <= data;
      start_bit <= 0;
      stop_bits <= 3'b001;
      tx <= 0;
      count <= baud;
    end else if (count == baud/2) begin
      tx <= start_bit;
    end else if (count == baud - baud/8) begin
      tx <= tx_reg[0];
    end else if (count == baud - baud/4) begin
      tx <= tx_reg[1];
    end else if (count == baud - 3*baud/8) begin
      tx <= tx_reg[2];
    end else if (count == baud - baud/2) begin
      tx <= tx_reg[3];
    end else if (count == baud - 5*baud/8) begin
      tx <= tx_reg[4];
    end else if (count == baud - 3*baud/4) begin
      tx <= tx_reg[5];
    end else if (count == baud - 7*baud/8) begin
      tx <= tx_reg[6];
    end else if (count == baud - 1) begin
      tx <= tx_reg[7];
      tx <= stop_bits[0];
      count <= 0;
    end else begin
      tx <= stop_bits[1];
      count <= count - 1;
    end
  end

endmodule

module uart_rx (
  input clk,
  input rst,
  input rx,
  input [31:0] baud,
  output reg [7:0] data
);

  reg [3:0] count;
  reg [7:0] rx_reg;
  reg start_bit;
  reg [1:0] stop_bits;
  reg [2:0] parity_bits;
  reg parity_error;

  always @(posedge clk) begin
    if (rst) begin
      count <= 0;
      rx_reg <= 0;
      start_bit <= 1;
      stop_bits <= 3'b001;
      parity_bits <= 3'b000;
      parity_error <= 0;
    end else if (count == 0) begin
      start_bit <= rx;
      count <= baud - baud/2;
    end else if (count == baud/2) begin
      rx_reg[0] <= rx;
      count <= baud - baud/4;
    end else if (count == baud - baud/4) begin
      rx_reg[1] <= rx;
      count <= baud - 3*baud/8;
    end else if (count == baud - 3*baud/8) begin
      rx_reg[2] <= rx;
      count <= baud - baud/2;
    end else if (count == baud - baud/2) begin
      rx_reg[3] <= rx;
      count <= baud - 5*baud/8;
    end else if (count == baud - 5*baud/8) begin
      rx_reg[4] <= rx;
      count <= baud - 3*baud/4;
    end else if (count == baud - 3*baud/4) begin
      rx_reg[5] <= rx;
      count <= baud - 7*baud/8;
    end else if (count == baud - 7*baud/8) begin
      rx_reg[6] <= rx;
      count <= baud - 1;
    end else if (count == baud - 1) begin
      rx_reg[7] <= rx;
      stop_bits <= {stop_bits[1:0], rx};
      parity_bits <= {parity_bits[1:0], rx};
      count <= 0;
      if (start_bit == 1'b0 && stop_bits == 3'b001) begin
        if (parity_error == 0) begin
          data <= rx_reg;
        end
      end
      start_bit <= 1;
      stop_bits <= 3'b001;
      parity_bits <= 3'b000;
      parity_error <= 0;
    end else begin
      count <= count - 1;
    end
  end

  always @(rx_reg) begin
    parity_error <= (rx_reg[0] ^ rx_reg[1] ^ rx_reg[2] ^ rx_reg[3] ^ rx_reg[4] ^ rx_reg[5] ^ rx_reg[6]) ^ parity_bits[0];
  end

endmodule

module hdmi_transmitter (
  input [7:0] video_in,
  input [1:0] audio_in,
  input clk,
  output reg [11:0] video_out,
  output reg [3:0] audio_out,
  output reg data_ready
);

  // Define constants for timing and synchronization
  parameter H_SYNC_WIDTH = 44;
  parameter H_BACK_PORCH = 148;
  parameter H_ACTIVE = 1920;
  parameter H_FRONT_PORCH = 88;
  parameter V_SYNC_WIDTH = 5;
  parameter V_BACK_PORCH = 36;
  parameter V_ACTIVE = 1080;
  parameter V_FRONT_PORCH = 4;
  parameter AUDIO_SAMPLE_RATE = 44100;

  // Define internal signals for timing and synchronization
  reg [10:0] h_count = 0;
  reg [9:0] v_count = 0;
  reg [1:0] audio_count = 0;
  reg h_sync = 0;
  reg v_sync = 0;

  // Define internal signals for audio encoding
  reg [15:0] audio_data = 0;
  reg [1:0] audio_channel = 0;
  reg audio_valid = 0;

  // Define internal signals for video encoding
  reg [7:0] r = 0;
  reg [7:0] g = 0;
  reg [7:0] b = 0;
  reg [3:0] y = 0;
  reg [3:0] cb = 0;
  reg [3:0] cr = 0;
  reg [1:0] pixel_count = 0;
  reg [1:0] data_count = 0;
  reg video_valid = 0;

  // Define internal signals for data flow control
  reg [1:0] state = 0;
  reg [7:0] data_out = 0;
  reg [3:0] audio_out_reg = 0;

  always @(posedge clk) begin
    // Timing and synchronization logic
    if (h_count == 0) begin
      h_sync <= 1;
    end else if (h_count == H_SYNC_WIDTH) begin
      h_sync <= 0;
    end else if (h_count == H_SYNC_WIDTH + H_BACK_PORCH) begin
      h_sync <= 1;
    end else if (h_count == H_SYNC_WIDTH + H_BACK_PORCH + H_ACTIVE) begin
      h_sync <= 0;
    end else if (h_count == H_SYNC_WIDTH + H_BACK_PORCH + H_ACTIVE + H_FRONT_PORCH) begin
      h_sync <= 1;
    end

    if (v_count == 0) begin
      v_sync <= 1;
    end else if (v_count == V_SYNC_WIDTH) begin
      v_sync <= 0;
    end else if (v_count == V_SYNC_WIDTH + V_BACK_PORCH) begin
      v_sync <= 1;
    end else if (v_count == V_SYNC_WIDTH + V_BACK_PORCH + V_ACTIVE) begin
      v_sync <= 0;
    end else if (v_count == V_SYNC_WIDTH + V_BACK_PORCH + V_ACTIVE + V_FRONT_PORCH) begin
      v_sync <= 1;
    end

    h_count <= h_count + 1;
    if (h_count == H_SYNC_WIDTH + H_BACK_PORCH + H_ACTIVE + H_FRONT_PORCH) begin
      h_count <= 0;
      v_count <= v_count + 1;
    end

    if (v_count == V_SYNC_WIDTH + V_BACK_PORCH + V_ACTIVE + V_FRONT_PORCH) begin
      v_count <= 0;
    end

    // Audio encoding logic
    if (audio_count == 0) begin
      audio_data <= {audio_in, 16'b0};
      audio_channel <= audio_channel + 1;
      if (audio_channel == 2) begin
        audio_channel <= 0;
      end
    end

    audio_count <= audio_count + 1;
    if (audio_count == AUDIO_SAMPLE_RATE / 100) begin
      audio_count <= 0;
    end

    if (audio_channel == 0) begin
      audio_out_reg <= audio_data[15:8];
    end else begin
      audio_out_reg <= audio_data[7:0];
    end

    audio_valid <= 1;

    // Video encoding logic
    if (pixel_count == 0) begin
      r <= video_in[7:0];
      g <= video_in[7:0];
      b <= video_in[7:0];
    end else if (pixel_count == 1) begin
      r <= video_in[7:0];
      g <= video_in[7:0];
      b <= video_in[7:0];
    end else if (pixel_count == 2) begin
      r <= video_in[7:0];
      g <= video_in[7:0];
      b <= video_in[7:0];
    end else if (pixel_count == 3) begin
      r <= video_in[7:0];
      g <= video_in[7:0];
      b <= video_in[7:0];
    end else if (pixel_count == 4) begin
      r <= video_in[7:0];
      g <= video_in[7:0];
      b <= video_in[7:0];
    end else if (pixel_count == 5) begin
      r <= video_in[7:0];
      g <= video_in[7:0];
      b <= video_in[7:0];
    end else if (pixel_count == 6) begin
      r <= video_in[7:0];
      g <= video_in[7:0];
      b <= video_in[7:0];
    end else if (pixel_count == 7) begin
      r <= video_in[7:0];
      g <= video_in[7:0];
      b <= video_in[7:0];
    end else if (pixel_count == 8) begin
      r <= video_in[7:0];
      g <= video_in[7:0];
      b <= video_in[7:0];
    end else if (pixel_count == 9) begin
      r <= video_in[7:0];
      g <= video_in[7:0];
      b <= video_in[7:0];
    end else if (pixel_count == 10) begin
      r <= video_in[7:0];
      g <= video_in[7:0];
      b <= video_in[7:0];
    end else if (pixel_count == 11) begin
      r <= video_in[7:0];
      g <= video_in[7:0];
      b <= video_in[7:0];
    end

    pixel_count <= pixel_count + 1;
    if (pixel_count == 12) begin
      pixel_count <= 0;
      data_count <= data_count + 1;
    end

    if (data_count == 0) begin
      y <= (0.299 * r) + (0.587 * g) + (0.114 * b);
      cb <= (-0.1687 * r) - (0.3313 * g) + (0.5 * b) + 128;
      cr <= (0.5 * r) - (0.4187 * g) - (0.0813 * b) + 128;
    end else if (data_count == 1) begin
      y <= (0.299 * r) + (0.587 * g) + (0.114 * b);
      cb <= (-0.1687 * r) - (0.3313 * g) + (0.5 * b) + 128;
      cr <= (0.5 * r) - (0.4187 * g) - (0.0813 * b) + 128;
    end

    if (data_count == 0) begin
      data_out <= {y[3:0], cb[3:0]};
    end else if (data_count == 1) begin
      data_out <= {y[3:0], cr[3:0]};
    end

    video_valid <= 1;

    // Data flow control logic
    case (state)
      0: begin
        if (h_sync && v_sync) begin
          state <= 1;
        end
      end
      1: begin
        if (video_valid && audio_valid) begin
          video_out <= {h_sync, v_sync, data_out};
          audio_out <= audio_out_reg;
          data_ready <= 1;
          state <= 2;
        end
      end
      2: begin
        if (!h_sync || !v_sync) begin
          data_ready <= 0;
          state <= 0;
        end
      end
    endcase
  end

endmodule

