module sine_modulator (
    input clk,
    input rst,
    input [15:0] amplitude,
    input [15:0] frequency,
    input [15:0] phase,
    output reg signed [15:0] sine_out
);

localparam LUT_SIZE = 4096; // 2^12
localparam LUT_ADDR_WIDTH = 12;
localparam LUT_DATA_WIDTH = 16;

reg [LUT_ADDR_WIDTH-1:0] lut_addr = 0;
reg signed [LUT_DATA_WIDTH-1:0] lut_data = 0;

// Generate the lookup table using Verilog's built-in sin() function
// The lookup table is scaled to 16 bits
reg signed [LUT_DATA_WIDTH-1:0] lut[LUT_SIZE-1:0];
integer i;
initial begin
    for (i = 0; i < LUT_SIZE; i = i + 1) begin
        lut[i] = $signed($sin(2 * $pi * i / LUT_SIZE) * (2 ** (LUT_DATA_WIDTH-1) - 1));
    end
end

// Calculate the phase offset based on the frequency input
reg signed [LUT_ADDR_WIDTH-1:0] phase_offset = 0;
always @(*) begin
    phase_offset = $signed(frequency) * LUT_SIZE / 50000000;
end

// Calculate the amplitude and phase modulated sine wave output
always @(posedge clk) begin
    if (rst) begin
        lut_addr <= 0;
        lut_data <= 0;
        sine_out <= 0;
    end else begin
        lut_addr <= (lut_addr + phase_offset) % LUT_SIZE;
        lut_data <= lut[lut_addr] * $signed(amplitude) / (2 ** (LUT_DATA_WIDTH-1) - 1);
        sine_out <= lut_data + $signed(phase);
    end
end

endmodule

