module proj(
input [3:0] switches,
input [3:0] pushbtns,
input clk,
output [3:0] final_led,
output [6:0] final,
output [3:0] final_enable
);

// Declare all the internal registers and wires
reg [17:0] counter;
reg [3:0] temp_led; 
reg [3:0] temp_enable = 4'b1111;
reg [6:0] temp_ssd=7'b1111111;
reg [6:0] ssd_1=7'b1111111;
reg [6:0] ssd_2=7'b1111111;
reg [6:0] ssd_3=7'b1111111;
reg [6:0] ssd_4=7'b1111111;
reg [6:0] final_ssd=7'b1111111;
reg [3:0] ssd_state = 4'b0000;
reg [3:0] last_pushbtns = 4'b0000;
reg [3:0] last_switches = 4'b0000;
wire [3:0] pushbtns_edge;
wire [3:0] switches_edge;

// Detect rising edge of push buttons and switches
assign pushbtns_edge = pushbtns & ~last_pushbtns;
assign switches_edge = switches & ~last_switches;

// Update last_pushbtns and last_switches
always @ (posedge clk) begin
    last_pushbtns <= pushbtns;
    last_switches <= switches;
end

// Update ssd_state based on push button input
always @ (posedge clk) begin
    if (pushbtns_edge[0]) ssd_state[0] <= ~ssd_state[0];
    if (pushbtns_edge[1]) ssd_state[1] <= ~ssd_state[1];
    if (pushbtns_edge[2]) ssd_state[2] <= ~ssd_state[2];
    if (pushbtns_edge[3]) ssd_state[3] <= ~ssd_state[3];
end

// Update temp_led and temp_ssd based on switches input
always @ (switches) begin
    case (switches)
        4'b0000: begin
            temp_led = 4'b0000;
            temp_ssd = 7'b1000000;
        end
        4'b0001: begin
            temp_led = 4'b0000;
            temp_ssd = 7'b1111001;
        end
        4'b0010: begin
            temp_led = 4'b0000;
            temp_ssd = 7'b0100100;
        end
        4'b0011: begin
            temp_led = 4'b0000;
            temp_ssd = 7'b0110000;
        end
        4'b0100: begin
            temp_led = 4'b0000;
            temp_ssd = 7'b0011001;
        end
        4'b0101: begin
            temp_led = 4'b0000;
            temp_ssd = 7'b0010010;
        end
        4'b0110: begin
            temp_led = 4'b0000;
            temp_ssd = 7'b0000010;
        end
        4'b0111: begin
            temp_led = 4'b0000;
            temp_ssd = 7'b1111000;
        end
        4'b1000: begin
            temp_led = 4'b1111;
            temp_ssd = 7'b0000000;
        end
        4'b1001: begin
            temp_led = 4'b0000;
            temp_ssd = 7'b0010000;
        end
        default: begin
            temp_led = 4'b0000;
            temp_ssd = 7'b1111111;
        end
    endcase
end

// Update final_ssd and temp_enable based on counter
always @ (posedge clk) begin
    case (counter[17:16])
        2'b00: begin
            final_ssd <= ssd_state[0] ? temp_ssd : ssd_1;
            temp_enable <= 4'b0111;
        end
        2'b01: begin
            final_ssd <= ssd_state[1] ? temp_ssd : ssd_2;
            temp_enable <= 4'b1011;
        end
        2'b10: begin
            final_ssd <= ssd_state[2] ? temp_ssd : ssd_3;
            temp_enable <= 4'b1101;
        end
        2'b11: begin
            final_ssd <= ssd_state[3] ? temp_ssd : ssd_4;
            temp_enable <= 4'b1110;
        end
    endcase
end

// Update counter
always @ (posedge clk) begin
    if (counter == 18'd262143) counter <= 0;
    else counter <= counter + 1;
end

// Update final_led, final, and final_enable
assign final_led = temp_led;
assign final = final_ssd;
assign final_enable = temp_enable;

endmodule

