module clk_gen(
    input clk_in1,
    input reset,
    output clk_out1
);

parameter DIVIDER = 4; // Change this to 2, 4, 8, 16 for different clock frequencies
reg [31:0] counter = 0;
reg clk_out1_reg = 0;

always @(posedge clk_in1, posedge reset) begin
    if (reset) begin
        counter <= 0;
        clk_out1_reg <= 0;
    end else begin
        counter <= counter + 1;
        if (counter == (clk_in1 / DIVIDER) - 1) begin
            counter <= 0;
            clk_out1_reg <= ~clk_out1_reg;
        end
    end
end

assign clk_out1 = clk_out1_reg;

endmodule

module counter (
    input CLK,
    input RST,
    output reg [3:0] Q
);

    always @(posedge CLK) begin
        if (RST) begin
            Q <= 4'b0;
        end else begin
            Q <= Q + 1;
        end
    end

endmodule

module sort_module (
    input clk,
    input rst,
    input [31:0] in_array[99:0],
    output [31:0] out_array[99:0]
);

    reg [31:0] temp;
    integer i, j;

    always @(posedge clk, posedge rst) begin
        if (rst) begin
            for (i = 0; i < 100; i = i + 1) begin
                out_array[i] <= 0;
            end
        end else begin
            for (i = 0; i < 100; i = i + 1) begin
                out_array[i] <= in_array[i];
            end

            for (i = 0; i < 99; i = i + 1) begin
                for (j = 0; j < 99 - i; j = j + 1) begin
                    if (out_array[j] > out_array[j+1]) begin
                        temp <= out_array[j];
                        out_array[j] <= out_array[j+1];
                        out_array[j+1] <= temp;
                    end
                end
            end
        end
    end

endmodule

module sequence_edge_detection (
    input clk,
    input reset,
    input [3:0] in,
    output reg [3:0] out
);

reg [3:0] prev_in;

always @(posedge clk) begin
    if (reset) begin
        out <= 4'b0;
        prev_in <= 4'b0;
    end else begin
        if (in != prev_in) begin
            out <= in;
            prev_in <= in;
        end
    end
end

endmodule

module change_detection (
    input clk,
    input reset,
    input [31:0] in,
    output reg [31:0] out
);

reg [31:0] prev_in;

always @(posedge clk) begin
    if (reset) begin
        out <= 32'b0;
        prev_in <= 32'b0;
    end else begin
        out <= (prev_in & ~in);
        prev_in <= in;
    end
end

endmodule

module functional_module (
    input [3:0] seq_out,
    input [31:0] change_out,
    output reg [31:0] final_out
);

always @(*) begin
    final_out = (seq_out | change_out);
end

