module binary_to_gray
(
  input clk,
  input rst_n,
  input [7:0] rst_val,
  input en,
  output reg [7:0] gry_cnt,
  output reg [7:0] gry_cnt_nxt
);

  // Convert reset value to gray code
  reg [7:0] rst_gray;
  always @ (rst_val)
    rst_gray = rst_val ^ {1'b0, rst_val[7:1]};

  // Registers
  reg [7:0] bin_cnt_f;
  reg [7:0] bin_cnt_nxt;
  reg [7:0] gray_cnt_f;
  reg [7:0] gray_cnt_nxt_f;

  // Assign next binary count
  always @ (posedge clk, negedge rst_n) begin
    if (~rst_n) begin
      bin_cnt_f <= rst_val;
      gray_cnt_f <= rst_gray;
    end
    else begin
      bin_cnt_f <= bin_cnt_nxt;
      gray_cnt_f <= gray_cnt_nxt_f;
    end
  end

  assign bin_cnt_nxt = bin_cnt_f + en;
  assign gray_cnt_nxt_f = bin_cnt_nxt ^ {1'b0, bin_cnt_nxt[7:1]};

  // Output
  always @ (posedge clk) begin
    gry_cnt <= gray_cnt_f;
    gry_cnt_nxt <= gray_cnt_nxt_f;
  end

endmodule

module pipelined_decade_counter (
    input clk,
    input slowena,
    input reset,
    output reg [3:0] q
);

reg [3:0] q1, q2, q3, q4;
reg [3:0] bcd_out;

always @(posedge clk) begin
    if (reset) begin
        q1 <= 4'b0000;
        q2 <= 4'b0000;
        q3 <= 4'b0000;
        q4 <= 4'b0000;
    end else if (slowena) begin
        q1 <= q;
        q2 <= q1;
        q3 <= q2;
        q4 <= q3;
    end
end

bcd_converter bcd_inst(
    .binary_in(q4),
    .bcd_out(bcd_out)
);

always @(posedge clk) begin
    if (reset) begin
        q <= 4'b0000;
    end else if (slowena) begin
        q <= q + 1;
    end
end

endmodule

module bcd_converter (
    input [3:0] binary_in,
    output [3:0] bcd_out
);

always @* begin
    case (binary_in)
        4'b0000: bcd_out = 4'b0000;
        4'b0001: bcd_out = 4'b0001;
        4'b0010: bcd_out = 4'b0010;
        4'b0011: bcd_out = 4'b0011;
        4'b0100: bcd_out = 4'b0100;
        4'b0101: bcd_out = 4'b0101;
        4'b0110: bcd_out = 4'b0110;
        4'b0111: bcd_out = 4'b0111;
        4'b1000: bcd_out = 4'b1000;
        4'b1001: bcd_out = 4'b1001;
        default: bcd_out = 4'b0000;
    endcase
end

endmodule

