    wire [3:0] priority;
    wire parity_mux;

    assign inverted_in = ~in;
    assign priority = {$priority(inverted_in)};
    assign parity_mux = priority[0];

    mux2to1 parity_mux (
        .a(in[0]),
        .b(parity_mux),
        .sel(priority[0]),
        .out(parity)
    );

