module calculator(
    input [31:0] A,
    input [31:0] B,
    input [1:0] op,
    output reg [31:0] sum,
    output reg [31:0] difference,
    output reg [31:0] product,
    output reg [31:0] quotient
);

always @(*)
begin
    case(op)
        2'b00: //addition
            begin
                sum = A + B;
                difference = A - B;
                product = A * B;
                quotient = A / B;
            end
        2'b01: //subtraction
            begin
                sum = A - B;
                difference = A + B;
                product = A * B;
                quotient = A / B;
            end
        2'b10: //multiplication
            begin
                sum = A * B;
                difference = A - B;
                product = A * B;
                quotient = A / B;
            end
        2'b11: //division
            begin
                sum = A / B;
                difference = A - B;
                product = A * B;
                quotient = A / B;
            end
        default: //invalid operation
            begin
                sum = 0;
                difference = 0;
                product = 0;
                quotient = 0;
            end
    endcase
end

endmodule

