module barrel_shifter (
  input [n-1:0] in,
  input [log2(n)-1:0] shift_amt,
  input dir,
  output [n-1:0] out,
  output overflow
);

parameter n = 8; // number of bits in the input signal

reg [n-1:0] shifted;
reg overflow;

always @(*) begin
  if (dir == 0) begin // shift left
    if (shift_amt >= n) begin
      shifted = 0;
      overflow = 1;
    end else begin
      shifted = in << shift_amt;
      overflow = (in >> (n - shift_amt)) != 0;
    end
  end else begin // shift right
    if (shift_amt >= n) begin
      shifted = 0;
      overflow = 1;
    end else begin
      shifted = in >> shift_amt;
      overflow = (in << (n - shift_amt)) != 0;
    end
  end
end

assign out = shifted;

endmodule

