module demux_1to256 (
    input [31:0] in,
    input [3:0] sel,
    output [31:0] out
);

    wire [7:0] sel_inv;

    assign sel_inv = ~sel;

    assign out = (sel[0]) ? in : 32'h00000000;
    assign out = (sel[1]) ? {out[31:16], in[15:0]} : out;
    assign out = (sel[2]) ? {out[31:8], in[7:0], out[7:0]} : out;
    assign out = (sel[3]) ? {out[31:4], in[3:0], out[3:0], out[3:0]} : out;
    assign out = (sel_inv[0]) ? out : 32'h00000000;
    assign out = (sel_inv[1]) ? {out[31:16], out[15:0]} : out;
    assign out = (sel_inv[2]) ? {out[31:8], out[7:0], out[7:0]} : out;
