module tone_detection_generation (
  input wire clk,
  input wire reset,
  input wire [15:0] tone_in,
  input wire [15:0] threshold,
  input wire [31:0] sample_rate,
  output wire [15:0] tone_out
);

  reg [31:0] phase_accumulator;
  reg [31:0] phase_step;
  reg [15:0] sine_table [0:255];
  reg [7:0] sine_index;
  wire [15:0] sine_value;

  // Goertzel algorithm
  reg [31:0] s_prev;
  reg [31:0] s_prev2;
  reg [31:0] coeff;
  reg [31:0] target_frequency;
  reg [31:0] power;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      s_prev <= 32'd0;
      s_prev2 <= 32'd0;
      target_frequency <= 32'd0;
      power <= 32'd0;
    end else begin
      s_prev <= (coeff * s_prev) - s_prev2 + tone_in;
      s_prev2 <= s_prev;
      target_frequency <= (sample_rate << 16) / (2 * 32'h3_1415);
      coeff <= (2 * 32'h3_1415 * target_frequency) >> 16;
      power <= (s_prev * s_prev) + (s_prev2 * s_prev2) - ((coeff * s_prev) * s_prev2);
    end
  end

  // Sine wave generation
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      phase_accumulator <= 32'd0;
      phase_step <= 32'd0;
    end else begin
      phase_accumulator <= phase_accumulator + phase_step;
      phase_step <= (power < threshold) ? target_frequency : 32'd0;
    end
  end

  always @(posedge clk) begin
    sine_index <= phase_accumulator[23:16];
    sine_value <= sine_table[sine_index];
  end

  // Sine table initialization
  integer i;
  initial begin
    for (i = 0; i < 256; i = i + 1) begin
      sine_table[i] = 16'h0000 + (16'h7FFF * $rtoi($sin(2 * 3.1415926 * i / 256)));
    end
  end

  assign tone_out = sine_value;

endmodule

module POR (
  input vdd,
  output reg rst
);

  parameter t = 100; // reset time in ns
  reg prev_vdd;
  reg [31:0] counter;

  always @(posedge vdd) begin
    if (prev_vdd == 1'b0) begin
      rst <= 1'b1;
      counter <= 0;
    end else if (counter < t) begin
      counter <= counter + 1;
    end else begin
      rst <= 1'b0;
    end
    prev_vdd <= vdd;
  end

endmodule

module top_module (
    input clk,
    input reset,
    input [15:0] in,
    output reg [7:0] out_sum);

    // Split input into two 8-bit outputs using a barrel shifter
    reg [7:0] upper_out;
    reg [7:0] lower_out;
    always @(*) begin
        upper_out = in >> 8;
        lower_out = in & 8'hFF;
    end

    // 4-bit binary counter
    reg [3:0] counter;
    always @(posedge clk) begin
        if (reset) begin
            counter <= 4'h0;
        end else if (counter == 4'hF) begin
            counter <= 4'h0;
        end else begin
            counter <= counter + 1;
        end
    end

    // Adder to sum the two values
    reg [7:0] sum;
    always @(*) begin
        sum = upper_out + counter + lower_out;
    end

    // Output the sum
    always @(posedge clk) begin
        if (reset) begin
            out_sum <= 8'h0;
        end else begin
            out_sum <= sum;
        end
    end

endmodule

