module tone_detector_generator (
  input in,
  input [15:0] tone_freq,
  output out
);

  // Define the parameters for the bandpass filter
  parameter Fs = 1000000; // Sampling frequency
  parameter Fc = tone_freq; // Center frequency of the bandpass filter
  parameter BW = 2000; // Bandwidth of the bandpass filter

  // Calculate the filter coefficients
  parameter w0 = 2 * $pi * Fc / Fs;
  parameter Q = Fc / BW;
  parameter alpha = sin(w0) / (2 * Q);
  parameter a0 = 1 + alpha;
  parameter a1 = -2 * cos(w0);
  parameter a2 = 1 - alpha;
  parameter b0 = (1 - cos(w0)) / 2;
  parameter b1 = 1 - cos(w0);
  parameter b2 = (1 - cos(w0)) / 2;

  // Define the state variables for the filter
  reg [15:0] x1, x2, y1, y2;

  // Implement the bandpass filter
  always @(posedge in) begin
    x2 <= x1;
    x1 <= in;
    y2 <= y1;
    y1 <= (b0 * x1) + (b1 * x2) + (b2 * x1) - (a1 * y1) - (a2 * y2);
  end

  // Generate the output signal based on the filtered input signal
  always @(posedge in) begin
    if (y1 > 0) begin
      out <= 1;
    end else begin
      out <= 0;
    end
  end

endmodule

