module counter_with_delay(
    input clk,
    input reset,
    input [31:0] modulus,
    input [31:0] time_delay,
    output reg cout
);

    reg [31:0] count;
    reg [31:0] delay_count;
    reg [31:0] last_modulus;
    reg [31:0] last_time_delay;
    reg tmp_cout;
    reg first_rising_edge;
    reg clk_last_value;
    reg clk_last_valid_value;
    reg cout_tmp;

    initial begin
        count = 1;
        delay_count = 0;
        first_rising_edge = 1;
        clk_last_value = 0;
        last_modulus = 0;
        last_time_delay = 0;
    end

    always @(reset or clk) begin
        if (reset) begin
            count = 1;
            delay_count = 0;
            tmp_cout = 0;
            first_rising_edge = 1;
        end else begin
            if ((clk_last_value !== clk) && (clk !== 1'bx)) begin
                if (clk === 1'b1 && first_rising_edge) begin
                    first_rising_edge = 0;
                    tmp_cout = clk;
                end else if ((first_rising_edge == 0) && (clk_last_valid_value !== clk)) begin
                    if (count < modulus)
                        count = count + 1;
                    else begin
                        count = 1;
                        tmp_cout = ~tmp_cout;
                    end
                end
            end
        end
        clk_last_value = clk;
        if (clk !== 1'bx)
            clk_last_valid_value = clk;

        if ((last_modulus !== modulus) || (last_time_delay !== time_delay)) begin
            last_modulus = modulus;
            last_time_delay = time_delay;
            delay_count = 0;
        end else begin
            delay_count = delay_count + 1;
            if (delay_count == time_delay)
                cout_tmp = tmp_cout;
        end
    end

    assign cout = cout_tmp;

endmodule

