module HMAC (
  input [k-1:0] key,
  input [m-1:0] msg,
  input flag,
  output [255:0] hmac,
  output valid
);

parameter k = 128; // length of key in bits
parameter m = 256; // length of message in bits
parameter b = 512; // block size of hash function in bits

wire [255:0] ipad = 256'h3636363636363636363636363636363636363636363636363636363636363636;
wire [255:0] opad = 256'h5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c;

wire [511:0] key_pad = {key, {k,1'b0}} ^ ipad;

wire [511:0] msg_pad = {msg, {m,1'b0}};

wire [511:0] key_hash = SHA256(key_pad);

wire [511:0] msg_hash = SHA256({key_hash, opad} ^ SHA256({key_hash, msg_pad}));

assign hmac = msg_hash[511:256];
assign valid = flag ? (msg_hash[255:0] == hmac) : 1'b0;

endmodule

module tracking_camera_system (
  input clk,
  input incr_addr,
  input reset_n,
  output new_rom,
  output reg [31:0] num_bytes,
  output reg [7:0] q,
  output reg safe
);

  parameter POLL_RATE = 100;

  reg [11:0] address;
  reg d1_pre, d2_pre, d3_pre, d4_pre, d5_pre, d6_pre, d7_pre, d8_pre, d9_pre;
  reg [7:0] mem_array [2047:0];
  reg [31:0] mutex [1:0];
  reg new_rom;
  reg pre;
  reg [31:0] poll_count;
  reg [31:0] mutex_handle;

  assign q = mem_array[address];

  always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
      d1_pre <= 0;
      d2_pre <= 0;
      d3_pre <= 0;
      d4_pre <= 0;
      d5_pre <= 0;
      d6_pre <= 0;
      d7_pre <= 0;
      d8_pre <= 0;
      d9_pre <= 0;
      new_rom <= 0;
    end else begin
      d1_pre <= pre;
      d2_pre <= d1_pre;
      d3_pre <= d2_pre;
      d4_pre <= d3_pre;
      d5_pre <= d4_pre;
      d6_pre <= d5_pre;
      d7_pre <= d6_pre;
      d8_pre <= d7_pre;
      d9_pre <= d8_pre;
      new_rom <= d9_pre;
    end
  end

  assign num_bytes = mutex[1];

  reg safe_delay;
  always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
      safe_delay <= 0;
    end else begin
      safe_delay <= safe;
    end
  end

  always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
      address <= 0;
      mem_array[0] <= 0;
      mutex[0] <= 0;
      mutex[1] <= 0;
      pre <= 0;
    end else begin
      pre <= 0;
      if (incr_addr && safe) begin
        address <= address + 1;
      end
      if (mutex[0] && !safe && safe_delay) begin
        if (interactive) begin
          mutex_handle = $fopen("tracking_camera_system_jtag_uart_0_input_mutex.dat");
          $fdisplay(mutex_handle, "0");
          $fclose(mutex_handle);
        end else begin
          wait (!reset_n);
        end
      end
      if (poll_count < POLL_RATE) begin
        poll_count <= poll_count + 1;
      end else begin
        poll_count <= 0;
        if (mutex_handle) begin
          $readmemh("tracking_camera_system_jtag_uart_0_input_mutex.dat", mutex);
        end
        if (mutex[0] && !safe) begin
          mutex[1] <= mutex[0];
          $readmemb("tracking_camera_system_jtag_uart_0_input_stream.dat", mem_array);
          address <= 0;
          pre <= -1;
        end
      end
    end
  end

endmodule

