    sky130_fd_sc_ms__fa fa3(.A(A[2]), .B(B[2]), .CIN(fa2_cout), .SUM(fa3_sum[2]), .COUT(fa3_cout));
    sky130_fd_sc_ms__fa fa4(.A(A[3]), .B(B[3]), .CIN(fa3_cout), .SUM(SUM[3]), .COUT(COUT));

    sky130_fd_sc_ms__ha ha1(.A(A[0]), .B(B[0]), .SUM(ha1_sum), .COUT(ha1_cout));
    sky130_fd_sc_ms__ha ha2(.A(A[1]), .B(B[1]), .SUM(ha2_sum), .COUT(ha2_cout));
    sky130_fd_sc_ms__ha ha3(.A(A[2]), .B(B[2]), .SUM(ha3_sum), .COUT(ha3_cout));

    assign SUM[0] = ha1_sum;
    assign SUM[1] = ha2_sum ^ ha1_cout;
    assign SUM[2] = ha3_sum ^ ha2_cout ^ ha1_cout;
    assign SUM[3] = fa4_sum ^ fa3_cout ^ fa2_cout ^ fa1_cout;

    assign COUT = fa4_cout;

endmodule

module flip_flop (
    Q      ,
    Q_N    ,
    D      ,
    SCD    ,
    SCE    ,
    CLK_N  ,
    SET_B  ,
    RESET_B
);

    output Q      ;
    output Q_N    ;
    input  D      ;
    input  SCD    ;
    input  SCE    ;
    input  CLK_N  ;
    input  SET_B  ;
    input  RESET_B;

    reg Q;
    reg Q_N;

    always @(posedge CLK_N) begin
        Q <= D;
    end

    always @(negedge SCD) begin
        Q <= 1'b1;
    end

    always @(negedge SCE) begin
        Q_N <= 1'b1;
    end

    always @(negedge RESET_B) begin
        Q <= 1'b0;
    end

    always @(negedge SET_B) begin
        Q_N <= 1'b0;
    end

    assign Q_N = ~Q;

endmodule

