module even_parity (
    input clk,
    input rst,
    input [N-1:0] test_expr,
    input enable,
    output reg even_parity
);

reg [N-1:0] parity;
integer i;

always @(posedge clk) begin
    if (rst) begin
        parity <= 0;
        even_parity <= 0;
    end else if (enable) begin
        parity <= test_expr ^ parity;
        even_parity <= 1;
        for (i = 0; i < N; i = i + 1) begin
            if (parity[i]) begin
                even_parity <= ~even_parity;
            end
        end
    end
end

endmodule

module fifo_buffer
    (
        input wr_clk,
        input wr_en,
        input rst_d2,
        input rst_full_gen_i,
        input [4:0] v1_reg,
        input [3:0] v1_reg_0,
        input [0:0] I1,
        output reg full,
        output reg [0:0] E
    );

    // RAM to store the elements
    reg [15:0] ram [0:15];

    // Write pointer
    reg [3:0] wr_ptr = 0;

    // Read pointer
    reg [3:0] rd_ptr = 0;

    // Flag generator
    always @ (posedge wr_clk) begin
        if (rst_full_gen_i) begin
            full <= 0;
            E <= 1;
        end
        else begin
            if (v1_reg == 15) begin
                full <= 1;
                E <= 0;
            end
            else if (v1_reg == 0) begin
                full <= 0;
                E <= 1;
            end
            else begin
                full <= 0;
                E <= 0;
            end
        end
    end

    // Write operation
    always @ (posedge wr_clk) begin
        if (rst_d2) begin
            wr_ptr <= 0;
        end
        else if (wr_en) begin
            if (v1_reg != 15) begin
                ram[wr_ptr] <= 1'b1;
                wr_ptr <= wr_ptr + 1;
            end
        end
    end

    // Read operation
    always @ (posedge wr_clk) begin
        if (v1_reg_0 != 15) begin
            ram[rd_ptr] <= 1'b0;
            rd_ptr <= rd_ptr + 1;
        end
    end

endmodule

module ramcpld_read(
    input CLK,
    input RESET,
    input AS20,
    input DS20,
    input RW20,
    input [31:0] A,
    output [31:0] D_OUT,
    input [1:0] SIZ,
    output [1:0] DSACK,
    output RAMOE,
    output [1:0] RAS,
    output [3:0] CAS,
    inout [31:0] D
);

wire [31:0] addr = A[23:0];
wire [1:0] byte_sel = A[1:0];

assign D_OUT = {D[31:24], D[23:16], D[15:8], D[7:0]};

assign RAS = {addr[20], addr[19]};
assign CAS = {addr[18], addr[17], addr[16], byte_sel};

assign DSACK = 2'b11;

assign RAMOE = 1'b1;

always @(posedge CLK) begin
    if (RESET) begin
        D <= 32'hzzzzzzzz;
    end else if (AS20 && DS20 && !RW20) begin
        case (SIZ)
            2'b00: D <= {24'hzzzzzz, D_OUT[7:0]};
            2'b01: D <= {16'hzzzz, D_OUT[15:0]};
            2'b10: D <= D_OUT;
            default: D <= 32'hzzzzzzzz;
        endcase
    end
end

endmodule

module binary_to_twos_complement(
    input [3:0] binary,
    output [7:0] twos_complement
);

reg [3:0] inverted_binary;
reg [3:0] one = 1;

assign twos_complement = {4{binary[3]}};
assign inverted_binary = ~binary + 1;

always @(*) begin
    if (binary[3] == 1) begin
        twos_complement = {4{1}} + inverted_binary;
    end else begin
        twos_complement = binary;
    end
end

endmodule

module arithmetic_operation(
  input clk,
  input rst,
  input [7:0] a,
  input [7:0] b,
  input [1:0] ctrl,
  output [7:0] result,
  output valid
);

  reg [7:0] result_reg;
  reg valid_reg;

  always @ (posedge clk) begin
    if (rst) begin
      result_reg <= 0;
      valid_reg <= 0;
    end else begin
      case (ctrl)
        2'b00: result_reg <= a + b;
        2'b01: result_reg <= a - b;
        2'b10: result_reg <= a * b;
        2'b11: begin
          if (b == 0) begin
            result_reg <= 0;
            valid_reg <= 0;
          end else begin
            result_reg <= a / b;
            valid_reg <= 1;
          end
        end
      endcase
    end
  end

  assign result = result_reg;
  assign valid = valid_reg;

endmodule

module uart_core(clk, rxd, txd, in_buffer, out_buffer, data_rdy, clear, cts, send, rst);
    input clk, rxd, clear, rst, send;
    output reg [7:0] in_buffer;
    output reg data_rdy;
    output cts;
    input [7:0] out_buffer;
    output txd;

    wire baud;
    wire baud16;
    uart_baud_generator ubg(clk, baud, baud16, rst);

    /* receive core */
    reg [3:0] rxd_state;
    reg [3:0] baud16_space;
    wire baud16_mark = (baud16_space == 0) ? 1 : 0;

    always @(negedge clk) begin
        if (rst) begin
            data_rdy <= 0;
            rxd_state <= 0;
        end else if (baud16) begin
            if (rxd_state != 0) /* work */
                baud16_space <= baud16_space + 1;
            else
                baud16_space <= 15;

            case (rxd_state)
                0: if (!rxd) rxd_state <= 1; /* start bit */
                1: if (baud16_mark) rxd_state <= 2;
                2: if (baud16_mark) begin rxd_state <= 3; in_buffer[0] <= rxd; end /* data bits */
                3: if (baud16_mark) begin rxd_state <= 4; in_buffer[1] <= rxd; end /* data bits */
                4: if (baud16_mark) begin rxd_state <= 5; in_buffer[2] <= rxd; end /* data bits */
                5: if (baud16_mark) begin rxd_state <= 6; in_buffer[3] <= rxd; end /* data bits */
                6: if (baud16_mark) begin rxd_state <= 7; in_buffer[4] <= rxd; end /* data bits */
                7: if (baud16_mark) begin rxd_state <= 8; in_buffer[5] <= rxd; end /* data bits */
                8: if (baud16_mark) begin rxd_state <= 9; in_buffer[6] <= rxd; end /* data bits */
                9: if (baud16_mark) begin rxd_state <= 10; in_buffer[7] <= rxd; end /* data bits */
                10: if (baud16_mark & rxd) begin rxd_state <= 0; data_rdy <= 1; end
                default: if (baud16_mark) rxd_state <= 0;
            endcase
        end
        if (clear)
            data_rdy <= 0;
    end

    /* transmit core */
    reg [3:0] txd_state;
    assign cts = (txd_state == 0) ? 1 : 0;
    always @(negedge clk) begin
        if (baud) begin
            case (txd_state)
                1: txd_state = 2; /* start bit */
                2: txd_state = 3; /* data bits */
                3: txd_state = 4;
                4: txd_state = 5;
                5: txd_state = 6;
                6: txd_state = 7;
                7: txd_state = 8;
                8: txd_state = 9;
                9: txd_state = 10;
                10: txd_state = 0;
                default: txd_state = 0; /* stop bit and idle */
            endcase
        end
        if (send)
            txd_state = 1;
    end

    assign txd = (txd_state == 0) ? 1 : /* idle / stop */
                     (txd_state == 1) ? 1 : /* idle / stop */
                     (txd_state == 2) ? 0 : /* start bit */
                     (txd_state == 3) ? out_buffer[0] :
                     (txd_state == 4) ? out_buffer[1] :
                     (txd_state == 5) ? out_buffer[2] :
                     (txd_state == 6) ? out_buffer[3] :
                     (txd_state == 7) ? out_buffer[4] :
                     (txd_state == 8) ? out_buffer[5] :
                     (txd_state == 9) ? out_buffer[6] :
                     (txd_state == 10) ? out_buffer[7] : 1;
endmodule

