module decrypt_DES(
    input [63:0] message,
    input [63:0] DESkey,
    input clk,
    input reset,
    input enable,
    input ack,
    output reg [63:0] decrypted,
    output reg done
);

reg [63:0] key;
reg [63:0] plaintext;
reg [63:0] ciphertext;
reg [47:0] subkeys [15:0];
reg [31:0] L [16:0];
reg [31:0] R [16:0];
reg [31:0] f_out;
reg [31:0] expanded_R;
reg [5:0] S_out [7:0];
reg [31:0] P_out;
reg [63:0] IP_out;
reg [63:0] FP_out;
reg [47:0] PC1_out;
reg [55:0] PC2_out;
reg [31:0] E_out;
reg [63:0] key_schedule;
reg [47:0] subkey;
reg [3:0] i;
reg [5:0] j;
reg [5:0] k;
reg [31:0] temp;
reg [31:0] temp_R;
reg [31:0] temp_L;

DES des(
    .plaintext(plaintext),
    .key(key),
    .ciphertext(ciphertext),
    .subkeys(subkeys),
    .L(L),
    .R(R),
    .f_out(f_out),
    .expanded_R(expanded_R),
    .S_out(S_out),
    .P_out(P_out),
    .IP_out(IP_out),
    .FP_out(FP_out),
    .PC1_out(PC1_out),
    .PC2_out(PC2_out),
    .E_out(E_out)
);

always @(posedge clk) begin
    if (reset) begin
        done <= 0;
    end else begin
        if (enable) begin
            if (ack) begin
                key <= DESkey;
                plaintext <= message;
                done <= 0;
                for (i = 0; i < 16; i = i + 1) begin
                    subkey = subkeys[i];
                    for (j = 0; j < 48; j = j + 1) begin
                        key_schedule[i*48+j] <= subkey[j];
                    end
                end
                for (k = 0; k < 16; k = k + 1) begin
                    temp_R = R[k] ^ key_schedule[k*48+0: k*48+47];
                    for (i = 0; i < 8; i = i + 1) begin
                        temp = temp_R[i*6+5: i*6];
                        temp = {temp[0], temp[5], temp[1:4]};
                        S_out[i] <= temp;
                    end
                    P_out = {S_out[0][3:0], S_out[1][3:0], S_out[2][3:0], S_out[3][3:0], S_out[4][3:0], S_out[5][3:0], S_out[6][3:0], S_out[7][3:0]};
                    temp_L = R[k-1];
                    temp_R = P_out ^ L[k-1];
                    L[k] = temp_L;
                    R[k] = temp_R;
                end
                decrypted <= {R[16], L[16]};
                done <= 1;
            end
        end
    end
end

endmodule

module four_bit_adder(A, B, Cin, S, Cout);
  input [3:0] A, B;
  input Cin;
  output [3:0] S;
  output Cout;

  wire [3:0] C;

  // Generate full adders for each bit
  genvar i;
  generate
    for (i = 0; i < 4; i = i + 1) begin
      full_adder adder_inst (.A(A[i]), .B(B[i]), .Cin(C[i]), .S(S[i]), .Cout(Cout_inst[i]));
    end
  endgenerate

  // Connect carry-out signals
  assign Cout = Cout_inst[3];

  // Connect carry chain
  assign C[0] = Cin;
  assign C[1] = Cout_inst[0];
  assign C[2] = Cout_inst[1];
  assign C[3] = Cout_inst[2];

  // Instantiate carry-out chain
  full_adder carry_inst (.A(C[0]), .B(C[1]), .Cin(C[2]), .S(C[3]), .Cout(Cout_inst[3]));
endmodule

module full_adder(A, B, Cin, S, Cout);
  input A, B, Cin;
  output S, Cout;

  assign S = A ^ B ^ Cin;
  assign Cout = (A & B) | (Cin & (A ^ B));
endmodule

