module Cryptographic_Block (
  input [n-1:0] in,
  input [k-1:0] key,
  input [1:0] mode,
  output reg [n-1:0] out
);

parameter n = 128; // number of input signals
parameter k = 256; // number of key signals

// Instantiate the AES encryption module
AES_Encryption aes_enc (
  .plaintext(in),
  .key(key),
  .ciphertext(out)
);

// Instantiate the AES decryption module
AES_Decryption aes_dec (
  .ciphertext(in),
  .key(key),
  .plaintext(out)
);

// Instantiate the SHA-256 hashing module
SHA256_Hash sha256 (
  .input_message(in),
  .hash(out)
);

// Control logic for selecting the operation mode
always @(*) begin
  case (mode)
    2'b00: begin
      aes_enc.enable = 1'b1;
      aes_dec.enable = 1'b0;
      sha256.enable = 1'b0;
    end
    2'b01: begin
      aes_enc.enable = 1'b0;
      aes_dec.enable = 1'b1;
      sha256.enable = 1'b0;
    end
    2'b10: begin
      aes_enc.enable = 1'b0;
      aes_dec.enable = 1'b0;
      sha256.enable = 1'b1;
    end
    default: begin
      aes_enc.enable = 1'b0;
      aes_dec.enable = 1'b0;
      sha256.enable = 1'b0;
    end
  endcase
end

endmodule

module game_logic(
    input clk,
    input reset,
    input [1:0] btn,
    input [9:0] pixel_x,
    input [9:0] ball_x,
    input [9:0] ball_y,
    output reg [9:0] paddle_x,
    output reg game_over
);

// Paddle constants
localparam PADDLE_WIDTH = 80;
localparam PADDLE_SPEED = 2;
localparam PADDLE_START_POS = (640 - PADDLE_WIDTH) / 2;

// Ball constants
localparam BALL_SIZE = 10;
localparam BALL_SPEED = 1;

// Game variables
reg [1:0] lives = 2'b11;
reg [9:0] ball_dx = BALL_SPEED;
reg [9:0] ball_dy = BALL_SPEED;

// Initialize paddle position
always @(posedge clk, posedge reset) begin
    if (reset) begin
        paddle_x <= PADDLE_START_POS;
    end else begin
        paddle_x <= PADDLE_START_POS;
    end
end

// Move paddle based on button input
always @(posedge clk) begin
    if (btn == 2'b11 && paddle_x < 640 - PADDLE_WIDTH - PADDLE_SPEED) begin
        paddle_x <= paddle_x + PADDLE_SPEED;
    end else if (btn != 2'b11 && paddle_x > PADDLE_SPEED - 1) begin
        paddle_x <= paddle_x - PADDLE_SPEED;
    end
end

// Detect ball collision with paddle or bottom of screen
always @(posedge clk) begin
    if (ball_y + BALL_SIZE >= 480) begin
        lives <= lives - 1;
        if (lives == 0) begin
            game_over <= 1;
        end else begin
            ball_dy <= -BALL_SPEED;
            ball_dx <= BALL_SPEED;
        end
    end else if (ball_y <= 0) begin
        ball_dy <= BALL_SPEED;
    end else if (ball_x + BALL_SIZE >= paddle_x && ball_x <= paddle_x + PADDLE_WIDTH && ball_y + BALL_SIZE >= 470 && ball_y + BALL_SIZE <= 480) begin
        ball_dy <= -BALL_SPEED;
        ball_dx <= BALL_SPEED;
    end
end

// Update ball position
always @(posedge clk) begin
    if (ball_x + BALL_SIZE >= 640) begin
        ball_dx <= -BALL_SPEED;
    end else if (ball_x <= 0) begin
        ball_dx <= BALL_SPEED;
    end
    ball_x <= ball_x + ball_dx;
    ball_y <= ball_y + ball_dy;
end

endmodule

