module sigma_delta (
  input analog_in,
  output digital_out,
  input digital_in,
  output analog_out
);

parameter OSR = 64; // oversampling ratio
parameter M = 4; // number of integrators
parameter N = 16; // number of bits

// Modulator
reg [N-1:0] quantized_out;
reg [M-1:0] integrator_out;
reg comb_out;
reg [OSR-1:0] oversampled_in;

always @(posedge clk) begin
  // Oversampling
  oversampled_in <= {oversampled_in[OSR-2:0], analog_in};

  // Integrators
  for (i = 0; i < M; i = i + 1) begin
    if (i == 0) begin
      integrator_out[i] <= oversampled_in[OSR-1] - comb_out;
    end else begin
      integrator_out[i] <= integrator_out[i-1] - comb_out;
    end
  end

  // Comb filter
  comb_out <= integrator_out[M-1] >> (M-1);

  // Quantization
  if (comb_out >= quantized_out) begin
    quantized_out <= quantized_out + 1;
  end else begin
    quantized_out <= quantized_out - 1;
  end
end

assign digital_out = quantized_out;

// Demodulator
reg [N-1:0] reconstructed_out;
reg [M-1:0] integrator_in;
reg [OSR-1:0] oversampled_out;

always @(posedge clk) begin
  // Quantization
  if (digital_in >= reconstructed_out) begin
    reconstructed_out <= reconstructed_out + 1;
  end else begin
    reconstructed_out <= reconstructed_out - 1;
  end

  // Oversampling
  oversampled_out <= {oversampled_out[OSR-2:0], reconstructed_out};

  // Integrators
  for (i = 0; i < M; i = i + 1) begin
    if (i == 0) begin
      integrator_in[i] <= digital_in - oversampled_out[OSR-1];
    end else begin
      integrator_in[i] <= integrator_in[i-1] - oversampled_out[OSR-1];
    end
  end

  // Low-pass filter
  analog_out <= integrator_in[M-1] >> (M-1);
end

endmodule

