module adder_with_overflow (
    input [7:0] a,
    input [7:0] b,
    output [7:0] s,
    output overflow
);

wire [8:0] carry;
wire [8:0] g;
wire [8:0] p;

assign g[0] = a[0] & b[0];
assign p[0] = a[0] ^ b[0];

genvar i;
generate
    for (i = 1; i < 8; i = i + 1) begin : gen
        assign g[i] = a[i] & b[i];
        assign p[i] = a[i] ^ b[i];
        assign carry[i] = g[i-1] | (p[i-1] & carry[i-1]);
    end
endgenerate

assign carry[8] = g[7] | (p[7] & carry[7]);
assign s = a + b + carry[8];
assign overflow = carry[8] ^ carry[7];

endmodule

