module idivmodhw(input clk,
                 input reset,

                 input rq,

                 input [31:0] dividend,
                 input [31:0] divisor,

                 output [31:0] div_out,
                 output [31:0] div_mod,
                 output ack);

   reg [31:0] div_mod;
   reg [31:0] div_out;
   reg ack;
   reg [31:0] dividend_reg;
   reg [31:0] divisor_reg;
   reg [31:0] quotient_reg;
   reg [31:0] remainder_reg;
   reg [31:0] count_reg;
   reg [31:0] zero_reg;

   parameter S_IDLE = 0;
   parameter S_DIVIDE = 1;
   parameter S_COMPLETE = 2;

   always @(posedge clk) begin
      if (reset) begin
         div_mod <= 0;
         div_out <= 0;
         ack <= 0;
         dividend_reg <= 0;
         divisor_reg <= 0;
         quotient_reg <= 0;
         remainder_reg <= 0;
         count_reg <= 0;
         zero_reg <= 0;
      end else begin
         case (count_reg)
            0: zero_reg <= 1;
            default: zero_reg <= 0;
         endcase

         if (rq) begin
            dividend_reg <= dividend;
            divisor_reg <= divisor;
            quotient_reg <= 0;
            remainder_reg <= 0;
            count_reg <= 32;
            ack <= 0;
            div_mod <= 0;
            div_out <= 0;
            state <= S_DIVIDE;
         end

         case (state)
            S_IDLE: begin
               ack <= 0;
               div_mod <= 0;
               div_out <= 0;
            end

            S_DIVIDE: begin
               if (count_reg > 0) begin
                  remainder_reg <= remainder_reg << 1;
                  remainder_reg[0] <= dividend_reg[31];
                  dividend_reg <= dividend_reg << 1;
                  remainder_reg <= remainder_reg - divisor_reg;
                  if (remainder_reg[31] == 0) begin
                     quotient_reg <= quotient_reg << 1;
                     quotient_reg[0] <= 1;
                     remainder_reg[31] <= 1;
                  end else begin
                     quotient_reg <= quotient_reg << 1;
                     remainder_reg[31] <= 0;
                  end
                  count_reg <= count_reg - 1;
               end else begin
                  if (remainder_reg[31] == 0) begin
                     div_out <= quotient_reg;
                     div_mod <= remainder_reg;
                  end else begin
                     div_out <= quotient_reg - 1;
                     div_mod <= divisor_reg - remainder_reg;
                  end
                  ack <= 1;
                  state <= S_COMPLETE;
               end
            end

            S_COMPLETE: begin
               ack <= 0;
               div_mod <= 0;
               div_out <= 0;
            end
         endcase
      end
   end

endmodule

module binary_search (
    input [15:0] array [7:0],
    input [15:0] search_key,
    output reg [2:0] index
);

    reg [2:0] low = 0;
    reg [2:0] high = 7;
    reg [2:0] mid;
    reg found = 0;

    always @(*) begin
        while (low <= high && !found) begin
            mid = (low + high) / 2;
            if (array[mid] == search_key) begin
                index = mid;
                found = 1;
            end else if (array[mid] < search_key) begin
                low = mid + 1;
            end else begin
                high = mid - 1;
            end
        end
        if (!found) begin
            index = -1;
        end
    end

endmodule

