module debouncer (
  input clk,
  input in,
  output reg out
);

parameter clk_freq = 100000; // clock frequency in Hz
parameter debounce_time = 10; // debounce time in ms

reg [1:0] state;
reg [31:0] debounce_count;

localparam STABLE = 2'b00;
localparam UNSTABLE = 2'b01;
localparam DEBOUNCE = 2'b10;

always @(posedge clk) begin
  case(state)
    STABLE: begin
      if(in != out) begin
        state <= UNSTABLE;
        debounce_count <= debounce_time * clk_freq / 1000;
      end
    end
    UNSTABLE: begin
      if(debounce_count == 0) begin
        state <= DEBOUNCE;
        out <= in;
      end else begin
        debounce_count <= debounce_count - 1;
      end
    end
    DEBOUNCE: begin
      if(in != out) begin
        state <= UNSTABLE;
        debounce_count <= debounce_time * clk_freq / 1000;
      end else begin
        state <= STABLE;
      end
    end
  endcase
end

endmodule

module PLL (
    inclk0,
    c0
);

    parameter   integer   DIV_FACTOR = 2;

    input       inclk0;
    output      c0;

    reg         [31:0]   counter;
    reg                   clk_out;

    always @(posedge inclk0) begin
        if (counter == DIV_FACTOR - 1) begin
            counter <= 0;
            clk_out <= ~clk_out;
        end else begin
            counter <= counter + 1;
        end
    end

    assign c0 = clk_out;

endmodule

module counter (
    input clk,
    input reset,      // Synchronous active-high reset
    output reg [3:0] count
);

    // State definitions
    localparam [1:0]
        S0 = 2'b00,
        S1 = 2'b01,
        S2 = 2'b10,
        S3 = 2'b11;

    // State register
    reg [1:0] state;

    always @(posedge clk) begin
        if (reset) begin
            state <= S0;
            count <= 4'b0000;
        end else begin
            case (state)
                S0: begin
                    state <= S1;
                    count <= count + 1;
                end
                S1: begin
                    state <= S2;
                    count <= count + 1;
                end
                S2: begin
                    state <= S3;
                    count <= count + 1;
                end
                S3: begin
                    state <= S0;
                    count <= count + 1;
                end
            endcase
        end
    end

endmodule

