module score_counter
   (
    input wire clk, reset,
    input wire d_inc, d_dec, d_clr,
    output wire [3:0] dig0, dig1
   );

   // signal declaration
   reg [3:0] dig0_reg, dig1_reg, dig0_next, dig1_next;

   // registers
   always @(posedge clk, posedge reset)
      if (reset)
         begin
            dig1_reg <= 0;
            dig0_reg <= 0;
         end
      else
         begin
            dig1_reg <= dig1_next;
            dig0_reg <= dig0_next;
         end

   // next-state logic
   always @*
   begin
      dig0_next = dig0_reg;
      dig1_next = dig1_reg;
      if (d_clr)
         begin
            dig0_next = 0;
            dig1_next = 0;
         end
      else if (d_inc)
         if (dig0_reg==9)
            begin
               dig0_next = 0;
               if (dig1_reg==9)
                  dig1_next = 0;
               else
                  dig1_next = dig1_reg + 1;
             end
         else  // dig0 not 9
            dig0_next = dig0_reg + 1;
      else if (d_dec)
         if((dig1_reg == 0) && (dig0_reg < 2))
            begin
               dig0_next = 0;
               dig1_next = 0;
            end
         else if((dig1_reg > 0) && (dig0_reg == 1))
            begin
               dig1_next = dig1_reg - 1;
               dig0_next = 9;
            end
         else if((dig1_reg > 0) && (dig0_reg == 0))
            begin
               dig1_next = dig1_reg - 1;
               dig0_next = 8;
            end   
         else
            dig0_next = dig0_reg - 2;      
   end

   // output
   assign dig0 = dig0_reg;
   assign dig1 = dig1_reg;

endmodule

module top_module (
    input clk, 
    input [3:0] in, // 4-bit input for the barrel shifter and decoder 
    output reg [15:0] out // 16-bit final output 
);

    // Barrel Shifter
    reg [3:0] shifted_input;
    assign shifted_input = {in[2:0], 1'b0};

    // Decoder
    reg [15:0] decoder_output;
    always @* begin
        case(shifted_input)
            4'b0001: decoder_output = 16'b0000000000000001;
            4'b0010: decoder_output = 16'b0000000000000010;
            4'b0100: decoder_output = 16'b0000000000000100;
            4'b1000: decoder_output = 16'b0000000000001000;
            4'b0011: decoder_output = 16'b0000000000001100;
            4'b0110: decoder_output = 16'b0000000000011000;
            4'b1100: decoder_output = 16'b0000000000110000;
            4'b1111: decoder_output = 16'b0000000001111000;
            default: decoder_output = 16'b0000000000000000;
        endcase
    end

    // XOR Module
    reg [15:0] xor_output;
    always @* begin
        xor_output = in ^ shifted_input;
    end

    // Multiplexer
    always @* begin
        if (in == 4'b0000) begin
            out = decoder_output;
        end else begin
            out = xor_output;
        end
    end

endmodule

