module dual_port_ram_mux
  #(
    parameter mem_size = 256
  )
  (
    output reg [7:0] doutb,
    output reg [23:0] doutb_array,
    input enb,
    input [1:0] addrb,
    input clkb,
    input [23:0] dinb_array
  );

  reg [1:0] sel_pipe;
  reg [1:0] sel_pipe_d1;
  reg [23:0] mem_array [0:mem_size-1];

  always @(posedge clkb) begin
    sel_pipe_d1 <= sel_pipe;
    sel_pipe <= {addrb[1], addrb[0]};
    doutb <= {doutb[6:0], doutb[7]};
  end

  always @(posedge clkb) begin
    if (enb) begin
      doutb_array <= mem_array[sel_pipe];
      mem_array[sel_pipe] <= dinb_array;
    end
  end

  generate
    genvar i;
    for (i = 0; i < mem_size; i = i + 1) begin: mem_block
      assign doutb[i] = mem_array[i][7:0];
      assign doutb_array[8*i +: 8] = mem_array[i][7:0];
    end
  endgenerate

endmodule

module shift_reg_comb (
    input clk,
    input areset,
    input load,
    input ena,
    input [3:0] data,
    input [7:0] in_hi,
    input [7:0] in_lo,
    output reg [15:0] out
);

    reg [3:0] reg_data;
    reg [15:0] shift_reg;
    wire [15:0] comb_out;

    // Shift register
    always @(posedge clk or negedge areset) begin
        if (areset == 0) begin
            shift_reg <= 0;
        end else if (load) begin
            shift_reg <= {reg_data, shift_reg[15:4]};
        end else if (ena) begin
            shift_reg <= {shift_reg[14:0], shift_reg[15]};
        end
    end

    // Combinational circuit
    assign comb_out = {in_hi, in_lo};

    // Functional module
    always @(comb_out or shift_reg) begin
        out <= comb_out + shift_reg;
    end

endmodule

