module dff_mux (
    input clk,
    input reset,            // Synchronous reset (active low)
    input [7:0] d,
    output reg [7:0] q
);

    reg [7:0] q_temp;

    always @(negedge clk) begin
        if (!reset) begin
            q_temp <= 8'b0;
        end
        else begin
            q_temp <= {q_temp[6:0], d[0]};
        end
    end

    always @* begin
        case (q_temp[7])
            1'b0: q[7] = q_temp[6];
            1'b1: q[7] = d[7];
        endcase

        case (q_temp[6])
            1'b0: q[6] = q_temp[5];
            1'b1: q[6] = d[6];
        endcase

        case (q_temp[5])
            1'b0: q[5] = q_temp[4];
            1'b1: q[5] = d[5];
        endcase

        case (q_temp[4])
            1'b0: q[4] = q_temp[3];
            1'b1: q[4] = d[4];
        endcase

        case (q_temp[3])
            1'b0: q[3] = q_temp[2];
            1'b1: q[3] = d[3];
        endcase

        case (q_temp[2])
            1'b0: q[2] = q_temp[1];
            1'b1: q[2] = d[2];
        endcase

        case (q_temp[1])
            1'b0: q[1] = q_temp[0];
            1'b1: q[1] = d[1];
        endcase

        case (q_temp[0])
            1'b0: q[0] = q_temp[7];
            1'b1: q[0] = d[0];
        endcase
    end

endmodule

