module arithmetic_operations (CLK, DS, ED, MPYJ, DR, DI, DOR, DOI);

    parameter total_bits = 32;

    input CLK;
    input DS;
    input ED;
    input MPYJ;
    input [total_bits-1:0] DR;
    input [total_bits-1:0] DI;

    output [total_bits:0] DOR;
    output [total_bits:0] DOI;

    reg signed [total_bits+2:0] dx5;
    reg signed [total_bits-1:0] dx7;
    reg signed [total_bits-1:0] dii;
    reg signed [total_bits:0] dt;
    wire signed [total_bits+3:0] dx5p;
    wire signed [total_bits+3:0] dot;
    reg edd, edd2, edd3;
    reg mpyjd, mpyjd2, mpyjd3;
    reg [total_bits:0] doo;
    reg [total_bits:0] droo;

    assign CLK = CLK;
    assign DS = DS;
    assign ED = ED;
    assign MPYJ = MPYJ;
    assign DR = DR;
    assign DI = DI;

    always @(posedge CLK) begin
        if (ED) begin
            edd <= DS;
            edd2 <= edd;
            edd3 <= edd2;
            mpyjd <= MPYJ;
            mpyjd2 <= mpyjd;
            mpyjd3 <= mpyjd2;
            if (DS) begin
                dx5 <= DR + (DR << 2);
                dx7 <= DR - (DR >>> 3);
                dt <= DR;
                dii <= DI;
            end else begin
                dx5 <= dii + (dii << 2);
                dx7 <= dii - (dii >>> 3);
                dt <= dii;
            end
            dx5p <= (dx5 << 1) + (dx7 >>> 1);
            dot <= dx5p + (dt >>> 6) - (dx5 >>> 13);
            doo <= dot >>> 3;
            droo <= doo;
            if (edd3) begin
                if (mpyjd3) begin
                    DOR <= doo;
                    DOI <= -droo;
                end else begin
                    DOR <= droo;
                    DOI <= doo;
                end
            end
        end
    end

    assign DOR = DOR;
    assign DOI = DOI;

endmodule

module spi_state_machine (
  input clk,
  input rst,
  input mode,
  input [3:0] ssel,
  input [7:0] mosi,
  output [7:0] miso,
  output done,
  output [7:0] data
);

  // Define the states for the state machine
  parameter IDLE = 2'b00;
  parameter SEND = 2'b01;
  parameter RECEIVE = 2'b10;

  // Define the clock polarity and phase parameters
  parameter CPOL_0_CPHA_0 = 2'b00;
  parameter CPOL_0_CPHA_1 = 2'b01;
  parameter CPOL_1_CPHA_0 = 2'b10;
  parameter CPOL_1_CPHA_1 = 2'b11;

  // Define the data width parameter
  parameter DATA_WIDTH = 8;

  // Define the number of slave devices parameter
  parameter NUM_SLAVES = 4;

  // Define the state and output registers
  reg [1:0] state;
  reg [7:0] tx_data;
  reg [7:0] rx_data;
  reg done_reg;

  // Define the clock polarity and phase signals
  wire sclk;
  wire cpol;
  wire cpha;

  // Define the slave select signals
  wire [3:0] ssel_reg;
  wire [3:0] ssel_next;

  // Define the data signals
  wire mosi_reg;
  wire miso_next;

  // Define the counter for the data width
  reg [2:0] data_count;

  // Define the counter for the number of slave devices
  reg [1:0] slave_count;

  // Define the state machine
  always @(posedge clk) begin
    if (rst) begin
      state <= IDLE;
      tx_data <= 0;
      rx_data <= 0;
      done_reg <= 0;
      data_count <= 0;
      slave_count <= 0;
    end else begin
      case (state)
        IDLE: begin
          if (mode) begin
            // Slave mode
            ssel_reg <= ssel;
            mosi_reg <= 0;
            state <= RECEIVE;
          end else begin
            // Master mode
            ssel_reg <= NUM_SLAVES-1;
            mosi_reg <= tx_data[DATA_WIDTH-1];
            state <= SEND;
          end
        end
        SEND: begin
          // Shift out the data
          mosi_reg <= tx_data[DATA_WIDTH-2];
          tx_data <= {tx_data[DATA_WIDTH-2:0], miso_next};
          data_count <= data_count + 1;
          if (data_count == DATA_WIDTH) begin
            data_count <= 0;
            state <= RECEIVE;
          end
        end
        RECEIVE: begin
          // Shift in the data
          miso_next <= 0;
          if (cpol && cpha) begin
            miso_next <= miso_next | miso;
          end
          if (cpol && !cpha) begin
            miso_next <= miso_next | (miso << 1);
          end
          if (!cpol && cpha) begin
            miso_next <= miso_next | (miso >> 1);
          end
          if (!cpol && !cpha) begin
            miso_next <= miso_next | (miso << 7);
          end
          data_count <= data_count + 1;
          if (data_count == DATA_WIDTH) begin
            data_count <= 0;
            rx_data <= miso_next;
            done_reg <= 1;
            if (mode) begin
              // Slave mode
              state <= RECEIVE;
            end else begin
              // Master mode
              tx_data <= {tx_data[DATA_WIDTH-2:0], 0};
              state <= SEND;
            end
          end
        end
      endcase
      if (mode) begin
        // Slave mode
        ssel_next <= ssel;
        miso <= rx_data;
      end else begin
        // Master mode
        ssel_next <= slave_count;
        miso <= miso_next;
      end
      if (done_reg) begin
        done <= 1;
        data <= rx_data;
      end else begin
        done <= 0;
        data <= 0;
      end
      if (mode) begin
        // Slave mode
        if (ssel_reg != ssel_next) begin
          state <= IDLE;
        end
      end else begin
        // Master mode
        if (data_count == 0 && slave_count == NUM_SLAVES-1) begin
          state <= IDLE;
        end else if (data_count == 0) begin
          slave_count <= slave_count + 1;
        end
      end
    end
  end

  // Generate the clock polarity and phase signals
  assign sclk = clk;
  assign cpol = (mode) ? mosi_reg : ssel_reg[0];
  assign cpha = (mode) ? ssel_reg[1] : ssel_reg[slave_count+2];

endmodule

module top_module (
    input clk,
    input reset, // Synchronous active-high reset
    input select, // Select input to choose between minute and second display
    output reg [3:0] min_out, // 4-digit display output for minutes
    output reg [3:0] sec_out // 4-digit display output for seconds
);

    reg [3:0] seconds;
    reg [3:0] minutes;
    wire [6:0] seg_out_min;
    wire [6:0] seg_out_sec;

    // Instantiate the minutes module
    minutes_module minutes_inst (
        .clk(clk),
        .reset(reset),
        .min_out(minutes)
    );

    // Instantiate the seconds module
    seconds_module seconds_inst (
        .clk(clk),
        .reset(reset),
        .sec_out(seconds)
    );

    // Instantiate the 7-segment display module
    display_module display_inst (
        .in(select ? seg_out_sec : seg_out_min),
        .out1(min_out),
        .out2(sec_out)
    );

    // Calculate the time in seconds
    always @ (posedge clk) begin
        if (reset) begin
            seconds <= 0;
            minutes <= 0;
        end
        else begin
            seconds <= seconds + 1;
            if (seconds == 60) begin
                seconds <= 0;
                minutes <= minutes + 1;
            end
        end
    end

    // Convert the minutes and seconds to 7-segment display format
    seven_segment_decoder decoder_inst (
        .in_min(minutes),
        .in_sec(seconds),
        .out_min(seg_out_min),
        .out_sec(seg_out_sec)
    );

endmodule

