module seven_segment_decoder (
    input [3:0] in_min, // Input for minutes
    input [3:0] in_sec, // Input for seconds
    output reg [6:0] out_min, // Output for minutes in 7-segment display format
    output reg [6:0] out_sec // Output for seconds in 7-segment display format
);

    // 7-segment display decoder for digits 0-9
    always @* begin
        case (in_min)
            4'd0: out_min = 7'b1000000;
            4'd1: out_min = 7'b1111001;
            4'd2: out_min = 7'b0100100;
            4'd3: out_min = 7'b0110000;
            4'd4: out_min = 7'b0011001;
            4'd5: out_min = 7'b0010010;
            4'd6: out_min = 7'b0000010;
            4'd7: out_min = 7'b1111000;
            4'd8: out_min = 7'b0000000;
            4'd9: out_min = 7'b0011000;
            default: out_min = 7'b1111111;
        endcase
    end

    always @* begin
        case (in_sec)
            4'd0: out_sec = 7'b1000000;
            4'd1: out_sec = 7'b1111001;
            4'd2: out_sec = 7'b0100100;
            4'd3: out_sec = 7'b0110000;
            4'd4: out_sec = 7'b0011001;
            4'd5: out_sec = 7'b0010010;
            4'd6: out_sec = 7'b0000010;
            4'd7: out_sec = 7'b1111000;
            4'd8: out_sec = 7'b0000000;
            4'd9: out_sec = 7'b0011000;
            default: out_sec = 7'b1111111;
        endcase
    end

endmodule

