module top_module (
    input clk,
    input areset,  // async active-high reset to zero
    input load,
    input ena,
    input select,  // 1 to use adder, 0 to use shifter
    input [31:0] a,  // input for carry select adder
    input [31:0] b,  // input for carry select adder
    input [3:0] data,  // input for barrel shifter
    output reg [31:0] q  // output from selected module
);

    // Define internal signals
    wire [31:0] adder_out;
    wire [3:0] shifter_out;
    reg [3:0] buffer [0:3];
    reg [1:0] buffer_ptr;

    // Define carry select adder
    carry_select_adder adder_inst (
        .a(a),
        .b(b),
        .cin(1'b0),
        .s(adder_out),
        .cout()
    );

    // Define barrel shifter
    always @(posedge clk) begin
        if (areset) begin
            buffer <= 4'b0;
            buffer_ptr <= 2'b0;
        end else begin
            if (load) begin
                buffer[buffer_ptr] <= data;
            end else if (ena) begin
                buffer[buffer_ptr] <= {1'b0, buffer[buffer_ptr][3:1]};
            end
            buffer_ptr <= buffer_ptr + 1'b1;
        end
    end
    assign shifter_out = buffer[buffer_ptr];

    // Select output based on select input
    always @(posedge clk) begin
        if (areset) begin
            q <= 32'b0;
        end else begin
            if (select) begin
                q <= adder_out;
            end else begin
                q <= {28'b0, shifter_out};
            end
        end
    end

endmodule

// Define carry select adder
module carry_select_adder (
    input [31:0] a,
    input [31:0] b,
    input cin,
    output reg [31:0] s,
    output reg cout
);
    reg [31:0] p, g;
    reg [4:0] c;

    always @(*) begin
        p = a + b;
        g = a & b;
        c[0] = cin;
        c[1] = g[0] | (p[0] & cin);
        c[2] = g[1] | (p[1] & c[1]);
        c[3] = g[2] | (p[2] & c[2]);
        c[4] = g[3] | (p[3] & c[3]);
        s = p + (c[4] << 4);
        cout = c[4];
    end

endmodule

module control_DAT(
    input logic writeRead,
    input logic multiblock,
    input logic timeoutenable,
    input logic [15:0] timeout,
    input logic newService,
    input logic clock,
    input logic reset,
    input logic [3:0] blockSize,
    input logic IDLE_in,
    input logic fifo_full,
    input logic recibido,
    input logic transferComplete,
    output logic newService_fisica,
    output logic [15:0] timeout_fisica,
    output logic writeRead_fisica,
    output logic reset_fisica,
    output logic complete,
    output logic IDLE_out
);

    parameter RESET = 6'b000001, IDLE = 6'b000010, checkfifo = 6'b000100, solicitud = 6'b001000, waitResponse = 6'b010000, waitIdle = 6'b100000;
    reg [5:0] state;
    reg [5:0] next_state;
    reg [4:0] blockCount;
    reg [4:0] blockCountFlip;

    // Sequential Logic
    always @(posedge clock) begin
        if (reset == 1'b1) begin
            state <= RESET;
            blockCountFlip <= 5'b00000;
        end else begin
            state <= next_state;
        end
    end

    // Output Logic
    always @(posedge clock) begin
        if (reset == 1'b1) begin
            newService_fisica <= 1'b0;
            timeout_fisica <= 16'b0000000000000000;
            writeRead_fisica <= 1'b0;
            reset_fisica <= 1'b1;
            complete <= 1'b0;
            IDLE_out <= 1'b0;
            blockCountFlip <= 5'b00000;
        end else begin
            case (state)
                RESET: begin
                    newService_fisica <= 1'b0;
                    timeout_fisica <= 16'b0000000000000000;
                    writeRead_fisica <= 1'b0;
                    reset_fisica <= 1'b0;
                    complete <= 1'b0;
                    IDLE_out <= 1'b0;
                    blockCountFlip <= 5'b00000;
                end
                IDLE: begin
                    newService_fisica <= 1'b0;
                    timeout_fisica <= 16'b0000000000000000;
                    writeRead_fisica <= 1'b0;
                    reset_fisica <= 1'b0;
                    complete <= 1'b0;
                    IDLE_out <= 1'b1;
                    blockCountFlip <= 5'b00000;
                end
                checkfifo: begin
                    newService_fisica <= 1'b0;
                    if (timeoutenable == 1'b1) begin
                        timeout_fisica <= timeout;
                    end else begin
                        timeout_fisica <= 16'b0000000000000000;
                    end
                    writeRead_fisica <= writeRead;
                    reset_fisica <= 1'b0;
                    complete <= 1'b0;
                    IDLE_out <= 1'b0;
                    blockCountFlip <= blockCount;
                end
                solicitud: begin
                    newService_fisica <= 1'b1;
                    writeRead_fisica <= writeRead;
                    reset_fisica <= 1'b0;
                    complete <= 1'b0;
                    IDLE_out <= 1'b0;
                    blockCountFlip <= blockCount;
                end
                waitResponse: begin
                    newService_fisica <= 1'b0;
                    writeRead_fisica <= writeRead;
                    reset_fisica <= 1'b0;
                    complete <= 1'b0;
                    IDLE_out <= 1'b0;
                    blockCountFlip <= blockCount;
                end
                waitIdle: begin
                    newService_fisica <= 1'b0;
                    writeRead_fisica <= writeRead;
                    reset_fisica <= 1'b0;
                    complete <= 1'b1;
                    IDLE_out <= 1'b0;
                    if (IDLE_in == 1'b1) begin
                        if ((multiblock == 0) || (blockCountFlip == blockSize)) begin
                            next_state <= IDLE;
                            blockCount <= 5'b00000;
                        end else begin
                            blockCount <= blockCountFlip + 5'b00001;
                            next_state <= checkfifo;
                        end
                    end else begin
                        blockCount <= blockCountFlip;
                        next_state <= waitIdle;
                    end
                end
                default: begin
                    newService_fisica <= 1'b0;
                    timeout_fisica <= 16'b0000000000000000;
                    writeRead_fisica <= 1'b0;
                    reset_fisica <= 1'b0;
                    complete <= 1'b0;
                    IDLE_out <= 1'b0;
                    blockCountFlip <= blockCount;
                end
            endcase
        end
    end

    // Combinational Logic
    always @(*) begin
        next_state = 6'b000000;
        blockCount = blockCountFlip;
        case (state)
            RESET: begin
                if (IDLE_in == 1'b1) begin
                    next_state = IDLE;
                    blockCountFlip = 5'b00000;
                end else begin
                    next_state = RESET;
                    blockCountFlip = 5'b00000;
                end
            end
            IDLE: begin
                if (newService == 1'b1) begin
                    next_state = checkfifo;
                    blockCountFlip = 5'b00000;
                end else begin
                    next_state = IDLE;
                    blockCountFlip = 5'b00000;
                end
            end
            checkfifo: begin
                if (fifo_full == 1'b1) begin
                    next_state = solicitud;
                end else begin
                    next_state = checkfifo;
                end
            end
            solicitud: begin
                if (recibido == 1'b1) begin
                    next_state = waitResponse;
                end else begin
                    next_state = solicitud;
                end
            end
            waitResponse: begin
                if (transferComplete == 1'b1) begin
                    next_state = waitIdle;
                end else begin
                    next_state = waitResponse;
                end
            end
            waitIdle: begin
                if (IDLE_in == 1'b1) begin
                    if ((multiblock == 0) || (blockCountFlip == blockSize)) begin
                        next_state = IDLE;
                        blockCountFlip = 5'b00000;
                    end else begin
                        blockCountFlip = blockCountFlip + 5'b00001;
                        next_state = checkfifo;
                    end
                end else begin
                    blockCountFlip = blockCountFlip;
                    next_state = waitIdle;
                end
            end
            default: begin
                next_state = IDLE;
                blockCountFlip = 5'b00000;
            end
        endcase
    end

endmodule

module mux_4to1_case (
  input a,
  input b,
  input c,
  input d,
  input sel0,
  input sel1,
  output reg out
);

  always @(*) begin
    case ({sel1, sel0})
      2'b00: out = a;
      2'b01: out = b;
      2'b10: out = c;
      2'b11: out = d;
    endcase
  end

endmodule

module channel_equalization (
  input [n-1:0] in,
  input [m-1:0] h,
  output [n+m-2:0] out
);

parameter n = 8; // length of input signal
parameter m = 4; // length of channel impulse response

reg [n+m-2:0] tmp_out;
reg [m-1:0] delay_line [0:n-1];

integer i, j;

always @(*) begin
  tmp_out = 0;
  for (i = 0; i < n; i = i + 1) begin
    delay_line[i][0] = in[i];
    for (j = 1; j < m; j = j + 1) begin
      delay_line[i][j] = delay_line[i][j-1];
    end
    for (j = 0; j < m; j = j + 1) begin
      tmp_out[i+j] = tmp_out[i+j] + delay_line[i][j] * h[j];
    end
  end
  out = tmp_out;
end

endmodule

module top_module (
    input [3:0] I,
    input E,
    output reg [3:0] Q,
    output V,
    output [1:0] D,
    input [3:0] A,
    input [3:0] B,
    input [3:0] C,
    input [3:0] D_in
);

    wire [3:0] mux_input;
    wire [3:0] priority_input;
    wire [1:0] priority_output;
    wire priority_valid;

    // Instantiate 4-to-1 multiplexer with enable module
    mux_enable_4to1 mux (
        .A(A),
        .B(B),
        .C(C),
        .D(D_in),
        .E(E),
        .S(I),
        .Q(mux_input)
    );

    // Instantiate 4-bit priority encoder module
    priority_encoder_4bit priority (
        .I(mux_input),
        .V(priority_valid),
        .D(priority_input)
    );

    // Assign output values
    assign D = priority_output;
    assign V = priority_valid;

    always @(*) begin
        if (E) begin
            Q = priority_input;
        end else begin
            Q = mux_input;
        end
    end

endmodule

// 4-to-1 multiplexer with enable module
module mux_enable_4to1 (
    input [3:0] A,
    input [3:0] B,
    input [3:0] C,
    input [3:0] D,
    input E,
    input [1:0] S,
    output reg [3:0] Q
);

    always @(*) begin
        case (S)
            2'b00: Q = A;
            2'b01: Q = B;
            2'b10: Q = C;
            2'b11: Q = D;
        endcase
    end

    always @(E) begin
        if (!E) begin
            Q = 4'b0000;
        end
    end

endmodule

// 4-bit priority encoder module
module priority_encoder_4bit (
    input [3:0] I,
    output reg [1:0] D,
    output reg V
);

    always @(*) begin
        casez (I)
            4'b0001: D = 2'b00;
            4'b0010: D = 2'b01;
            4'b0100: D = 2'b10;
            4'b1000: D = 2'b11;
            default: D = 2'b00;
        endcase
    end

    always @(*) begin
        if (I != 4'b0000) begin
            V = 1'b1;
        end else begin
            V = 1'b0;
        end
    end

endmodule

