module cpu(
    input clk,
    input resetq,
    input RXD,
    input uart0_valid,
    input [7:0] uart0_data_in,
    input uart0_busy,
    output reg TXD,
    output reg uart0_wr,
    output reg uart0_rd,
    output reg [7:0] uart0_data_out
);

    // Constants
    localparam DATA_WIDTH = 8;
    localparam REG_COUNT = 4;
    localparam MEM_SIZE = 256;
    localparam ADDR_WIDTH = $clog2(MEM_SIZE);

    // Registers
    reg [DATA_WIDTH-1:0] cpuregs [REG_COUNT-1:0];
    reg [ADDR_WIDTH-1:0] pc;
    reg [DATA_WIDTH-1:0] outb;
    reg outf;

    // Memory
    reg [DATA_WIDTH-1:0] memory [MEM_SIZE-1:0];

    // UART interface
    reg [DATA_WIDTH-1:0] uart_rx;
    reg uart_rx_valid;
    reg [DATA_WIDTH-1:0] uart_tx;
    reg uart_tx_valid;
    wire uart_busy;

    // Internal signals
    reg [DATA_WIDTH-1:0] op;
    reg [DATA_WIDTH-1:0] imm8;
    reg [DATA_WIDTH-1:0] mem_addr;
    reg [DATA_WIDTH-1:0] mem_data;

    // States
    localparam S_IDLE     =3'b000,
               S_OP       =3'b001,
               S_IMM8     =3'b010,
               S_UART_WAIT=3'b011,
               S_UART_END =3'b100,
               S_MEM_LOAD =3'b101;

    reg [2:0] state;

    // Combinational logic
    assign uart0_wr = outf;
    assign uart0_rd = (state == S_IDLE);
    assign uart0_data_out = outb;
    assign uart_busy = uart0_busy;

    // UART interface
    always @(posedge clk) begin
        if (!resetq) begin
            uart_rx <= 0;
            uart_rx_valid <= 0;
            uart_tx <= 0;
            uart_tx_valid <= 0;
            TXD <= 1;
        end else begin
            if (uart0_valid && !uart_rx_valid) begin
                uart_rx <= uart0_data_in;
                uart_rx_valid <= 1;
            end

            if (!uart_busy && uart_tx_valid) begin
                TXD <= uart_tx[0];
                uart_tx <= {1'b0, uart_tx[DATA_WIDTH-1:1]};
                uart_tx_valid <= (uart_tx != 0);
            end
        end
    end

    // CPU logic
    always @(posedge clk) begin
        if (!resetq) begin
            pc <= 0;
            cpuregs <= 0;
            memory <= 0;
            outf <= 0;
            state <= S_IDLE;
        end else begin
            case (state)
                S_IDLE: begin
                    if (uart_rx_valid && uart_rx == 8'h61) begin // "a" to start
                        pc <= 0;
                        state <= S_OP;
                    end
                end
                S_OP: begin
                    op <= memory[pc];
                    pc <= pc + 1;
                    casez (op)
                        8'b00000001, // JUMP
                        8'b000001zz, // MOV IMM r0-r3
                        8'b000100zz: begin // JNZ
                            state <= S_IMM8;
                        end
                        8'b000010zz: begin // SEND r0-r3
                            state <= S_UART_WAIT;
                            outb <= cpuregs[op[1:0]];
                        end
                        8'b000011zz: begin // DEC r0-r3
                            cpuregs[op[1:0]] <= cpuregs[op[1:0]] - 1;
                        end
                        8'b000110zz: begin // INC r0-r3
                            cpuregs[op[1:0]] <= cpuregs[op[1:0]] + 1;
                        end
                        8'b1000zzzz: begin // ADD rx, ry
                            cpuregs[op[3:2]] <= cpuregs[op[3:2]] + cpuregs[op[1:0]];
                        end
                        8'b1100zzzz: begin // LD rx,[{ry+1,ry}]
                            state <= S_MEM_LOAD;
                            mem_addr <= cpuregs[op[1:0]] + 1;
                        end
                        default: begin // Invalid instruction, back to IDLE state
                            state <= S_IDLE;
                        end
                    endcase
                end
                S_IMM8: begin
                    imm8 <= memory[pc];
                    pc <= pc + 1;
                    state <= S_OP;
                    casez (op)
                        8'b00000001: begin // JUMP
                            pc <= imm8;
                        end
                        8'b000100zz: begin // JNZ
                            if (cpuregs[op[1:0]] != 0) begin
                                pc <= imm8;
                            end
                        end
                        8'b000001zz: begin // MOV IMM
                            cpuregs[op[1:0]] <= imm8;
                        end
                    endcase
                end
                S_UART_WAIT: begin
                    if (!uart_busy) begin // Send byte when UART ready
                        state <= S_UART_END;
                        outf <= 1;
                        uart_tx <= outb;
                        uart_tx_valid <= 1;
                    end
                end
                S_UART_END: begin // Clear outf flag after sending to UART
                    outf <= 0;
                    state <= S_OP;
                end
                S_MEM_LOAD: begin // Load from memory
                    mem_data <= memory[mem_addr];
                    cpuregs[op[3:2]] <= mem_data;
                    state <= S_OP;
                end
            endcase
        end
    end

    // Memory interface
    always @(posedge clk) begin
        if (!resetq) begin
            memory <= 0;
        end else begin
            if (state == S_OP && op[7:6] == 2'b01) begin // Store
                memory[cpuregs[op[3:2]]] <= cpuregs[op[1:0]];
            end
        end
    end

endmodule

