module input_decoder (
    sys_clk,
    rst_n,
    bab35c,
    qg59ae3,
    bn276ee,
    cm5c637,
    jpe31b9
);

input sys_clk;
input rst_n;
input [7:0] bab35c;
input qg59ae3;
input bn276ee;
output cm5c637;
output [7:0] jpe31b9;

reg [1:0] state;
reg [7:0] output_reg;

always @(posedge sys_clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= 2'b00;
        output_reg <= 8'b0;
    end else begin
        case (state)
            2'b00: begin
                if (bab35c[7] == 1) begin
                    state <= 2'b01;
                    output_reg <= 8'b1000_0000;
                end else if (bab35c[6] == 1) begin
                    state <= 2'b01;
                    output_reg <= 8'b0100_0000;
                end else if (bab35c[5] == 1) begin
                    state <= 2'b01;
                    output_reg <= 8'b0010_0000;
                end else if (bab35c[4] == 1) begin
                    state <= 2'b01;
                    output_reg <= 8'b0001_0000;
                end else if (bab35c[3] == 1) begin
                    state <= 2'b01;
                    output_reg <= 8'b0000_1000;
                end else if (bab35c[2] == 1) begin
                    state <= 2'b01;
                    output_reg <= 8'b0000_0100;
                end else if (bab35c[1] == 1) begin
                    state <= 2'b01;
                    output_reg <= 8'b0000_0010;
                end else if (bab35c[0] == 1) begin
                    state <= 2'b01;
                    output_reg <= 8'b0000_0001;
                end else begin
                    state <= 2'b00;
                    output_reg <= 8'b0;
                end
            end
            2'b01: begin
                state <= 2'b00;
                output_reg <= 8'b0;
            end
        endcase
    end
end

assign jpe31b9 = output_reg;
assign cm5c637 = qg59ae3 & bn276ee;

endmodule

