module top_module (
    input [15:0] data_in0,
    input [15:0] data_in1,
    input [15:0] data_in2,
    input [15:0] data_in3,
    input [3:0] shift_amount,
    input select, // Select input to choose between left or right shift
    output [15:0] data_out
);

    wire [15:0] mux_out;
    wire [15:0] shift_out;

    // Instantiate 4-to-1 multiplexer module
    mux_4to1 mux_inst (
        .data_in0(data_in0),
        .data_in1(data_in1),
        .data_in2(data_in2),
        .data_in3(data_in3),
        .select(shift_amount[1:0]),
        .data_out(mux_out)
    );

    // Instantiate 16-bit barrel shifter module
    barrel_shifter shifter_inst (
        .data_in(data_in2),
        .shift_amount(shift_amount[3:0]),
        .select(select),
        .data_out(shift_out)
    );

    // Combine the outputs of the multiplexer and barrel shifter
    assign data_out = (shift_amount[2]) ? shift_out : mux_out;

endmodule

// 4-to-1 multiplexer module
module mux_4to1 (
    input [15:0] data_in0,
    input [15:0] data_in1,
    input [15:0] data_in2,
    input [15:0] data_in3,
    input [1:0] select,
    output [15:0] data_out
);

    assign data_out = (select == 2'b00) ? data_in0 :
                      (select == 2'b01) ? data_in1 :
                      (select == 2'b10) ? data_in2 :
                      data_in3;

endmodule

// 16-bit barrel shifter module
module barrel_shifter (
    input [15:0] data_in,
    input [3:0] shift_amount,
    input select, // Select input to choose between left or right shift
    output [15:0] data_out
);

    assign data_out = (select) ? (data_in << shift_amount) : (data_in >> shift_amount);

endmodule

