bcd_converter converter(.D({BCD[15], BCD[14], BCD[13], BCD[12]}), .BCD(C_bcd[31:24]));
bcd_converter converter0(.D({BCD[11], BCD[10], BCD[9], BCD[8]}), .BCD(C_bcd[23:16]));
bcd_converter converter1(.D({BCD[7], BCD[6], BCD[5], BCD[4]}), .BCD(C_bcd[15:8]));
bcd_converter converter2(.D({BCD[3], BCD[2], BCD[1], BCD[0]}), .BCD(C_bcd[7:0]));

always @(posedge clk) begin
    if (reset) begin
        for (row = 0; row < 4; row = row + 1) begin
            for (col = 0; col < 4; col = col + 1) begin
                C[row][col] <= 0;
