        for (row = 0; row < 4; row = row + 1) begin
            for (col = 0; col < 4; col = col + 1) begin
                C[row][col] <= multiplier.C[row][col];
            end
        end
    end
end

assign digit_sel = {3'b000, col};

endmodule

