module non_restoring_div_conditional_output (
    input signed [3:0] dividend,
    input signed [3:0] divisor,
    input [3:0] C,
    output reg signed [3:0] out
);

reg signed [3:0] quotient;
reg signed [3:0] remainder;
reg [2:0] state;
reg [3:0] count;

always @(*) begin
    case (state)
        0: begin
            quotient = 4'b0;
            remainder = dividend;
            count = 4'b0;
            state = 3'b001;
        end
        3'b001: begin
            remainder = remainder - divisor;
            if (remainder >= 0) begin
                quotient[count] = 1'b1;
                state = 3'b010;
            end else begin
                quotient[count] = 1'b0;
                state = 3'b011;
            end
            count = count + 1;
        end
        3'b010: begin
            remainder = remainder + divisor;
            count = count + 1;
            if (count == 4) begin
                state = 3'b100;
            end else begin
                state = 3'b001;
            end
        end
        3'b011: begin
            count = count + 1;
            if (count == 4) begin
                state = 3'b100;
            end else begin
                state = 3'b001;
            end
        end
        3'b100: begin
            if (C == 2) begin
                out = quotient ^ remainder;
            end else if (C == 1) begin
                out = remainder;
            end else begin
                out = quotient;
            end
            state = 3'b000;
        end
    endcase
end

endmodule

