wire carry;

// Full adder for the least significant bit (bit 0)
full_adder fa0(A[0], B[0], CIN, sum[0], carry[0]);

// Full adder for bit 1
full_adder fa1(A[1], B[1], carry[0], sum[1], carry[1]);

// Full adder for bit 2
full_adder fa2(A[2], B[2], carry[1], sum[2], carry[2]);

// Full adder for the most significant bit (bit 3)
full_adder fa3(A[3], B[3], carry[2], sum[3], COUT);

assign S = sum;

endmodule

module full_adder(
    input A,
    input B,
    input CIN,
    output SUM,
    output COUT
);

wire s1, s2, s3;

// XOR gates to calculate the sum (SUM)
xor x1(s1, A, B);
xor x2(SUM, s1, CIN);

// AND gates to calculate the carry-out (COUT)
and a1(s2, A, B);
and a2(s3, s1, CIN);
or o1(COUT, s2, s3);

endmodule

