module PLL (
  input in_clk,
  input ref_clk,
  input reset,
  output out_clk,
  output locked
);

parameter n = 8; // number of bits used to represent the phase accumulator
parameter m = 4; // number of bits used to represent the phase comparator output
parameter k = 2; // gain of the loop filter

reg [n-1:0] phase_acc; // phase accumulator
reg [m-1:0] phase_comp_out; // phase comparator output
reg [m-1:0] loop_filter_out; // loop filter output
reg locked_reg; // locked signal register

wire phase_comp_in; // phase comparator input
wire loop_filter_in; // loop filter input
wire [n-1:0] phase_acc_next; // next phase accumulator value
wire [m-1:0] phase_comp_out_next; // next phase comparator output value
wire [m-1:0] loop_filter_out_next; // next loop filter output value
wire locked_next; // next locked signal value

// phase comparator
assign phase_comp_in = in_clk ^ ref_clk;
assign phase_comp_out_next = phase_comp_in >> (m - 1);

// loop filter
assign loop_filter_in = phase_comp_out - (1 << (m - 1));
assign loop_filter_out_next = loop_filter_out + (k * loop_filter_in);

// phase accumulator
assign phase_acc_next = phase_acc + loop_filter_out_next;
assign out_clk = $signed(phase_acc_next[n-1]) ? ~in_clk : in_clk;
assign locked_next = (loop_filter_in == 0);

// locked signal register
always @(posedge in_clk, posedge reset) begin
  if (reset) begin
    locked_reg <= 0;
  end else begin
    locked_reg <= locked_next;
  end
end

// output assignments
assign phase_comp_out = phase_comp_out_next;
assign loop_filter_out = loop_filter_out_next;
assign phase_acc = phase_acc_next;
assign locked = locked_reg;

endmodule

module avlst_n_to_1 #(
    parameter N = 8,
    parameter DATA_W = 16
)(
    input  csi_clk,
    input  rsi_reset,
    output asi_ready,
    input  asi_valid,
    input  [N*DATA_W-1:0] asi_data,
    input  aso_ready,
    output aso_valid,
    output [DATA_W-1:0] aso_data
);

    reg [DATA_W-1:0] buffer [0:N-1];
    reg [N-1:0] valid_slots;
    reg [N-1:0] next_valid_slots;
    reg [2:0] read_index;
    reg [2:0] write_index;
    reg [2:0] next_write_index;
    reg [2:0] next_read_index;
    reg [DATA_W-1:0] data;
    reg ready;

    assign asi_ready = ~{valid_slots};
    assign aso_data = buffer[read_index];
    assign aso_valid = valid_slots != 0;

    always @(posedge csi_clk) begin
        if (rsi_reset) begin
            read_index <= 3'b0;
            write_index <= 3'b0;
            next_read_index <= 3'b0;
            next_write_index <= 3'b0;
            valid_slots <= {N{1'b0}};
            next_valid_slots <= {N{1'b0}};
            data <= {DATA_W{1'b0}};
            ready <= 1'b1;
        end else begin
            read_index <= next_read_index;
            write_index <= next_write_index;
            valid_slots <= next_valid_slots;
            if (asi_valid && ready) begin
                buffer[write_index] <= asi_data;
                next_valid_slots[write_index] <= 1'b1;
                next_write_index <= (write_index + 1) % N;
                ready <= 1'b0;
            end
            if (aso_ready && valid_slots[read_index]) begin
                next_read_index <= (read_index + 1) % N;
                next_valid_slots[read_index] <= 1'b0;
                ready <= 1'b1;
            end
            data <= buffer[read_index];
        end
    end
endmodule

module fp_adder (
    input [15:0] a,
    input [15:0] b,
    input add_sub,
    output reg [15:0] result,
    output isNaN,
    output isInf
);

reg [15:0] a_mantissa, b_mantissa, result_mantissa;
reg [4:0] a_exponent, b_exponent, result_exponent;
reg a_sign, b_sign, result_sign;
reg [3:0] stage;

// Stage 1: Extracting mantissa, exponent and sign of a and b
always @(*) begin
    a_mantissa = {1, a[9:0]};
    b_mantissa = {1, b[9:0]};
    a_exponent = a[14:10];
    b_exponent = b[14:10];
    a_sign = a[15];
    b_sign = b[15];
end

// Stage 2: Normalizing the mantissas and adjusting the exponents
always @(posedge clk) begin
    if (stage == 0) begin
        if (a_mantissa[10] == 0) begin
            a_mantissa = a_mantissa << 1;
            a_exponent = a_exponent - 1;
        end
        if (b_mantissa[10] == 0) begin
            b_mantissa = b_mantissa << 1;
            b_exponent = b_exponent - 1;
        end
        stage <= 1;
    end
end

// Stage 3: Adding or subtracting the mantissas
always @(posedge clk) begin
    if (stage == 1) begin
        if (add_sub == 1) begin
            result_mantissa = a_mantissa + b_mantissa;
        end else begin
            result_mantissa = a_mantissa - b_mantissa;
        end
        stage <= 2;
    end
end

// Stage 4: Normalizing the result mantissa and adjusting the exponent
always @(posedge clk) begin
    if (stage == 2) begin
        if (result_mantissa[11] == 1) begin
            result_mantissa = result_mantissa >> 1;
            result_exponent = result_exponent + 1;
        end
        stage <= 3;
    end
end

// Stage 5: Checking for NaN and infinity and setting the flag outputs
always @(posedge clk) begin
    if (stage == 3) begin
        if (result_exponent == 31 && result_mantissa[10:0] != 0) begin
            isNaN = 1;
            isInf = 0;
        end else if (result_exponent == 31 && result_mantissa[10:0] == 0) begin
            isNaN = 0;
            isInf = 1;
        end else begin
            isNaN = 0;
            isInf = 0;
        end
        stage <= 4;
    end
end

// Stage 6: Rounding the result mantissa and combining the result
always @(posedge clk) begin
    if (stage == 4) begin
        if (result_mantissa[0] == 1) begin
            result_mantissa = result_mantissa + 1;
        end
        result_exponent = result_exponent + 15;
        result_sign = a_sign;
        result = {result_sign, result_exponent, result_mantissa[9:0]};
        stage <= 0;
    end
end

endmodule

