    wire [7:0] p2, g2, c2;

    pipelined_adder adder1(.a(a), .b(b), .s(p1), .overflow(overflow));
    pipelined_adder adder2(.a(p1), .b(8'b0), .s(p2), .overflow(overflow));
    pipelined_adder adder3(.a(p2), .b(8'b0), .s(s), .overflow(overflow));

endmodule

