module PLL_DLL (
  input ref_clk,
  input rst_n,
  input enable,
  input freq_sel, // for PLL only
  input phase_sel, // for DLL only
  output out_clk
);

// Parameters for PLL or DLL block
parameter N = 10; // number of delay elements
parameter M = 4; // frequency multiplication factor (for PLL only)

// Internal signals
reg [N-1:0] delay_line;
wire [N-1:0] delay_line_shifted;
wire [N-1:0] delay_line_shifted_inv;
wire [N-1:0] phase_diff;
wire [N-1:0] phase_diff_filtered;
reg [N-1:0] phase_acc;
wire [N-1:0] phase_acc_filtered;
wire [N-1:0] freq_adj;
reg [N-1:0] freq_acc;

// Generate the delay line
always @ (posedge ref_clk or negedge rst_n) begin
  if (~rst_n) begin
    delay_line <= 'b0;
  end else begin
    delay_line <= {delay_line[N-2:0], ref_clk};
  end
end

// Generate the shifted delay line for phase detection
assign delay_line_shifted = {delay_line[N-2:0], 1'b0};
assign delay_line_shifted_inv = ~delay_line_shifted;

// Generate the phase difference signal
assign phase_diff = delay_line_shifted & delay_line_shifted_inv;

// Generate the filtered phase difference signal
always @ (posedge ref_clk or negedge rst_n) begin
  if (~rst_n) begin
    phase_diff_filtered <= 'b0;
  end else begin
    phase_diff_filtered <= phase_diff_filtered + (phase_diff - phase_diff_filtered) / 16;
  end
end

// Generate the phase accumulator
always @ (posedge ref_clk or negedge rst_n) begin
  if (~rst_n) begin
    phase_acc <= 'b0;
  end else begin
    if (enable) begin
      phase_acc <= phase_acc + (phase_diff_filtered + freq_adj);
    end
  end
end

// Generate the filtered phase accumulator signal
always @ (posedge ref_clk or negedge rst_n) begin
  if (~rst_n) begin
    phase_acc_filtered <= 'b0;
  end else begin
    phase_acc_filtered <= phase_acc_filtered + (phase_acc - phase_acc_filtered) / 16;
  end
end

// Generate the frequency adjustment signal (for PLL only)
always @ (posedge ref_clk or negedge rst_n) begin
  if (~rst_n) begin
    freq_adj <= 'b0;
  end else begin
    if (enable && freq_sel) begin
      freq_adj <= (M-1) * phase_diff_filtered / N;
    end
  end
end

// Generate the frequency accumulator signal (for PLL only)
always @ (posedge ref_clk or negedge rst_n) begin
  if (~rst_n) begin
    freq_acc <= 'b0;
  end else begin
    if (enable && freq_sel) begin
      freq_acc <= freq_acc + freq_adj;
    end
  end
end

// Generate the output clock signal
always @ (posedge ref_clk or negedge rst_n) begin
  if (~rst_n) begin
    out_clk <= 'b0;
  end else begin
    if (enable) begin
      if (freq_sel) begin // PLL block
        out_clk <= delay_line_shifted[N-1] ^ freq_acc[N-1];
      end else if (phase_sel) begin // DLL block
        out_clk <= delay_line_shifted[phase_acc_filtered[N-1]];
      end
    end
  end
end

endmodule

module carry_look_ahead_adder(
    input [3:0] a,
    input [3:0] b,
    input cin,
    output cout,
    output [3:0] s,
    output p,
    output g,
    output c
    );

    wire [3:0] p;
    wire [3:0] g;
    wire [3:0] c;

    assign p = a ^ b;
    assign g = a & b;
    assign c[0] = p[0] & cin | g[0];
    assign c[1] = p[1] &  (p[0] & cin | g[0]) | g[1];
    assign c[2] = p[2] & (p[1] &  (p[0] & cin | g[0]) | g[1]) | g[2];
    assign c[3] = p[3] & (p[2] & (p[1] &  (p[0] & cin | g[0]) |  g[1]) | g[2]) | g[3];
    assign cout = c[3];
    assign s[0] = a[0] + b[0] + cin;
    assign s[1] = a[1] + b[1] + c[0];
    assign s[2] = a[2] + b[2] + c[1];
    assign s[3] = a[3] + b[3] + c[2];

endmodule

module RIJCPU(
    input clk,
    input clk_ram,
    input rst,
    input [31:0] A,
    input [31:0] B,
    input [6:0] MW,
    output [31:0] ALU_F,
    output FR_ZF,
    output FR_OF,
    input [31:0] Mem_R_Data,
    output reg [31:0] PC
);

reg [31:0] mem [0:255];
reg [31:0] IR;
reg [31:0] temp;
reg [1:0] opcode;
reg [31:0] operand;

assign ALU_F = (MW == 2'b00) ? (A + B) : (MW == 2'b01) ? (A - B) : (MW == 2'b10) ? (A & B) : (A | B);

assign FR_ZF = (ALU_F == 0) ? 1 : 0;
assign FR_OF = ((ALU_F[31] == A[31]) && (ALU_F[31] != B[31])) ? 1 : 0;

always @(posedge clk_ram) begin
    IR = mem[PC];
end

always @(posedge clk) begin
    if (rst) begin
        PC <= 0;
    end else begin
        PC <= PC + 1;
    end

    if (MW) begin
        mem[PC] <= B;
    end

    opcode <= IR[31:30];
    operand <= IR[29:0];

    case (opcode)
        2'b00: begin
            temp <= A;
            A <= ALU_F;
            B <= temp;
        end
        2'b01: begin
            A <= ALU_F;
        end
        2'b10: begin
            if (FR_ZF) begin
                PC <= operand;
            end
        end
        2'b11: begin
            if (FR_OF) begin
                PC <= operand;
            end
        end
    endcase
end

initial begin
    $readmemh("memory.txt", mem);
end

endmodule

