module sqrt_calculator (
  input [31:0] num,
  input [31:0] iter,
  output reg [31:0] sqrt
);

  reg [31:0] guess;
  reg [31:0] next_guess;
  reg [31:0] numerator;
  reg [31:0] denominator;
  reg [31:0] two = 32'h2;
  reg [31:0] one = 32'h1;
  reg [31:0] count = 0;

  initial begin
    guess = num >> 1;
    next_guess = 0;
    numerator = num;
    denominator = guess;
  end

  always @(*) begin
    if (count < iter) begin
      next_guess = (guess + (numerator / guess)) >> 1;
      guess = next_guess;
      numerator = num - (guess * guess);
      denominator = two * guess;
      count = count + one;
    end
    else begin
      sqrt = guess;
    end
  end

endmodule

module barrel_shifter (
    input [3:0] data,
    input [2:0] shift,
    output [3:0] out
);

reg [3:0] stage1_out;
reg [3:0] stage2_out;

always @(*) begin
    stage1_out[0] = (shift[0] == 1) ? data[1] : data[0];
    stage1_out[1] = (shift[0] == 1) ? data[2] : data[1];
    stage1_out[2] = (shift[0] == 1) ? data[3] : data[2];
    stage1_out[3] = (shift[0] == 1) ? data[0] : data[3];
end

always @(*) begin
    stage2_out[0] = (shift[1] == 1) ? stage1_out[2] : stage1_out[0];
    stage2_out[1] = (shift[1] == 1) ? stage1_out[3] : stage1_out[1];
    stage2_out[2] = (shift[1] == 1) ? stage1_out[0] : stage1_out[2];
    stage2_out[3] = (shift[1] == 1) ? stage1_out[1] : stage1_out[3];
end

always @(*) begin
    if (shift[2] == 1) begin
        out[0] = stage2_out[1];
        out[1] = stage2_out[2];
        out[2] = stage2_out[3];
        out[3] = stage2_out[0];
    end else begin
        out = stage2_out;
    end
end

endmodule

