module note2dds_3st_gen(CLK, NOTE, ADDER);

input wire CLK;
input wire [6:0] NOTE;
output [31:0] ADDER;

reg [31:0] ADDER_tbl [15:0];
reg [3:0] addr;
reg [3:0] divider;

// note div 12 ( * 0,08333333333333333333333333333333)
//; Add input / 16 to accumulator
//; Add input / 64 to accumulator

initial begin
   addr <= 4'd012;
    divider <= 4'd0;
    ADDER_tbl[ 4'd0] <= 32'd0359575;
    ADDER_tbl[ 4'd1] <= 32'd0380957;
    ADDER_tbl[ 4'd2] <= 32'd0403610;
    ADDER_tbl[ 4'd3] <= 32'd0427610;
    ADDER_tbl[ 4'd4] <= 32'd0453037;
    ADDER_tbl[ 4'd5] <= 32'd0479976;
    ADDER_tbl[ 4'd6] <= 32'd0508516;
    ADDER_tbl[ 4'd7] <= 32'd0538754;
    ADDER_tbl[ 4'd8] <= 32'd0570790;
    ADDER_tbl[ 4'd9] <= 32'd0604731;
    ADDER_tbl[4'd10] <= 32'd0640691;
    ADDER_tbl[4'd11] <= 32'd0678788;
    ADDER_tbl[4'd12] <= 32'd0;
    ADDER_tbl[4'd13] <= 32'd0;
    ADDER_tbl[4'd14] <= 32'd0;
    ADDER_tbl[4'd15] <= 32'd0;
end

assign ADDER = ADDER_tbl[addr] >> divider;


wire [6:0] note_a = (NOTE <  12) ? NOTE :
                         (NOTE <  24) ? NOTE - 7'd012 :
                         (NOTE <  36) ? NOTE - 7'd024 :
                         (NOTE <  48) ? NOTE - 7'd036 :
                         (NOTE <  60) ? NOTE - 7'd048 :
                         (NOTE <  72) ? NOTE - 7'd060 :
                         (NOTE <  84) ? NOTE - 7'd072 :
                         (NOTE <  96) ? NOTE - 7'd084 :
                         (NOTE < 108) ? NOTE - 7'd096 :
                         (NOTE < 120) ? NOTE - 7'd0108 : NOTE - 7'd0120 ;

wire [3:0] div_val = (NOTE <  12) ? 4'd010 :
                         (NOTE <  24) ? 4'd09 :
                         (NOTE <  36) ? 4'd08 :
                         (NOTE <  48) ? 4'd07 :
                         (NOTE <  60) ? 4'd06 :
                         (NOTE <  72) ? 4'd05 :
                         (NOTE <  84) ? 4'd04 :
                         (NOTE <  96) ? 4'd03 :
                         (NOTE < 108) ? 4'd02 :
                         (NOTE < 120) ? 4'd01 : 4'd00 ;

always @ (posedge CLK) begin
    if (NOTE >= 0 && NOTE <= 127) begin
        addr <= note_a[3:0];
        divider <= div_val;
    end else if (NOTE < 0) begin
        addr <= 4'd0;
        divider <= 4'd0;
    end else begin // NOTE > 127
        addr <= 4'd15;
        divider <= 4'd0;
    end
end

endmodule

module Counter_66(
  input   clock,
  input   reset,
  input   io_enable,
  input [39:0] load_val,
  output  io_done,
  output [39:0] count_out
);
  wire  reg$_clock;
  wire  reg$_reset;
  wire [39:0] reg$_io_in;
  wire [39:0] reg$_io_out;
  wire  reg$_io_enable;
  wire [40:0] count;
  wire [41:0] _T_12;
  wire [40:0] newval;
  wire  isMax;
  wire [40:0] next;
  wire  _T_14;
  FF_556 reg$ (
    .clock(reg$_clock),
    .reset(reg$_reset),
    .io_in(reg$_io_in),
    .io_out(reg$_io_out),
    .io_enable(reg$_io_enable)
  );
  assign count = {1'h0,reg$_io_out};
  assign _T_12 = count + 41'h1;
  assign newval = _T_12[40:0];
  assign isMax = newval >= 41'h2cb417800;
  assign next = isMax ? count : newval;
  assign _T_14 = io_enable & isMax;
  assign io_done = _T_14;
  assign reg$_io_in = io_enable ? (load_val >= 41'h2cb417800 ? 40'h0 : load_val) : count[39:0];
  assign reg$_io_enable = io_enable;
  assign reg$_clock = clock;
  assign reg$_reset = reset;
  assign count_out = count[39:0];
endmodule

module pll_hdmi_reconf (
    input clock,
    input [2:0] counter_param,
    input [3:0] counter_type,
    input [8:0] data_in,
    input pll_areset_in,
    input pll_scandataout,
    input pll_scandone,
    input read_param,
    input reconfig,
    input reset,
    input reset_rom_address,
    input rom_data_in,
    input write_from_rom,
    input write_param,
    output busy,
    output [8:0] data_out,
    output pll_areset,
    output pll_configupdate,
    output pll_scanclk,
    output pll_scanclkena,
    output pll_scandata,
    output [7:0] rom_address_out,
    output write_rom_ena
);

    reg [2:0] counter_param_reg;
    reg [3:0] counter_type_reg;
    reg [8:0] data_in_reg;
    reg pll_areset_in_reg;
    reg [8:0] data_out_reg;
    reg [7:0] rom_address_out_reg;
    reg pll_configupdate_reg;
    reg write_rom_ena_reg;
    reg busy_reg;
    reg pll_areset_reg;
    reg pll_scanclkena_reg;
    reg [1:0] state_reg;
    reg [7:0] rom_data_reg;
    wire pll_scandata_wire;
    wire pll_scandone_wire;
    wire pll_scanclk_wire;

    // Synchronous reset
    always @(posedge clock) begin
        if (reset) begin
            counter_param_reg <= 3'b0;
            counter_type_reg <= 4'b0;
            data_in_reg <= 9'b0;
            pll_areset_in_reg <= 1'b0;
            data_out_reg <= 9'b0;
            rom_address_out_reg <= 8'b0;
            pll_configupdate_reg <= 1'b0;
            write_rom_ena_reg <= 1'b0;
            busy_reg <= 1'b0;
            pll_areset_reg <= 1'b0;
            pll_scanclkena_reg <= 1'b0;
            state_reg <= 2'b00;
            rom_data_reg <= 8'b0;
        end else begin
            counter_param_reg <= counter_param;
            counter_type_reg <= counter_type;
            data_in_reg <= data_in;
            pll_areset_in_reg <= pll_areset_in;
            rom_data_reg <= rom_data_in;
            case(state_reg)
                2'b00: begin // Idle state
                    if (read_param) begin
                        data_out_reg <= {counter_param_reg, counter_type_reg};
                        busy_reg <= 1'b0;
                    end else if (reconfig) begin
                        state_reg <= 2'b01;
                        busy_reg <= 1'b1;
                    end else if (reset_rom_address) begin
                        rom_address_out_reg <= 8'b0;
                    end else if (write_from_rom) begin
                        state_reg <= 2'b10;
                        busy_reg <= 1'b1;
                    end else if (write_param) begin
                        counter_param_reg <= data_in_reg[2:0];
                        counter_type_reg <= data_in_reg[6:3];
                        pll_configupdate_reg <= 1'b1;
                    end
                end
                2'b01: begin // Reconfig state
                    pll_areset_reg <= 1'b1;
                    pll_scanclkena_reg <= 1'b0;
                    state_reg <= 2'b10;
                end
                2'b10: begin // Write from ROM state
                    rom_address_out_reg <= rom_address_out_reg + 1'b1;
                    write_rom_ena_reg <= 1'b1;
                    if (pll_scandone_wire) begin
                        write_rom_ena_reg <= 1'b0;
                        state_reg <= 2'b00;
                        busy_reg <= 1'b0;
                    end
                end
            endcase
        end
    end

    // Asynchronous reset
    assign pll_scandata = pll_scandata_wire;
    assign pll_scandone = pll_scandone_wire;
    assign pll_scanclk = pll_scanclk_wire;
    always @(*) begin
        case(state_reg)
            2'b00: begin // Idle state
                pll_areset <= pll_areset_in_reg;
                pll_configupdate <= pll_configupdate_reg;
                pll_scanclkena <= pll_scanclkena_reg;
                data_out <= data_out_reg;
                rom_address_out <= rom_address_out_reg;
                write_rom_ena <= write_rom_ena_reg;
                busy <= busy_reg;
            end
            2'b01: begin // Reconfig state
                pll_areset <= 1'b1;
                pll_configupdate <= 1'b0;
                pll_scanclkena <= 1'b0;
                data_out <= 9'b0;
                rom_address_out <= 8'b0;
                write_rom_ena <= 1'b0;
                busy <= 1'b1;
                pll_scandata_wire <= 1'b0;
                pll_scandone_wire <= 1'b0;
                pll_scanclk_wire <= 1'b0;
            end
            2'b10: begin // Write from ROM state
                pll_areset <= 1'b1;
                pll_configupdate <= 1'b0;
                pll_scanclkena <= 1'b1;
                data_out <= 9'b0;
                rom_address_out <= rom_address_out_reg;
                write_rom_ena <= write_rom_ena_reg;
                busy <= 1'b1;
                pll_scandata_wire <= rom_data_reg[0];
                pll_scandone_wire <= 1'b0;
                pll_scanclk_wire <= 1'b0;
            end
        endcase
    end

endmodule

module dff_sscan (din, clk, q, se, si, so);
// synopsys template

parameter SIZE = 1;

input [SIZE-1:0] din;     // data in
input clk;                // clk or scan clk

output [SIZE-1:0] q;      // output

input se;                 // scan-enable
input [SIZE-1:0] si;      // scan-input
output [SIZE-1:0] so;     // scan-output

reg [SIZE-1:0] q;
reg [SIZE-1:0] scan_q;

always @ (posedge clk) begin
    if (se) begin
        scan_q <= si;
    end else begin
        q <= din;
    end
end

assign so = se ? scan_q : {SIZE{1'b0}};

assign q = se ? scan_q : q;

endmodule

module serial_interface(input CLOCK_50, input [1:0] KEY, input req, output reg [7:0] value_0, output reg [7:0] value_1, output reg [7:0] value_2, output reg value_0_valid, output reg value_1_valid, output reg value_2_valid);

    reg ready;
    reg running;
    reg [7:0] reqCount;
    reg [24:0] timer;
    reg ack;

    initial begin
        value_0 = 8'd0;
        value_1 = 8'd0;
        value_2 = 8'd0;
        value_0_valid = 1'b0;
        value_1_valid = 1'b0;
        value_2_valid = 1'b0;
        running = 1'b0;
        reqCount = 8'd0;
        ack = 1'b0;
    end

    always @(posedge CLOCK_50) begin
        if(KEY[0]) begin
            value_0 = 8'h55;
            value_0_valid = 1'b1;
        end

        if(KEY[1]) begin
            value_1 = 8'hAA;
            value_1_valid = 1'b1;
        end

        if(running) begin
            if(ack & value_2_valid) begin
                reqCount <= 8'd0;
                value_2_valid <= 1'b0;
            end else begin
                if(req && reqCount < 10) begin
                    reqCount <= reqCount + 8'd1;
                end else if(req) begin
                    reqCount <= 8'd0;
                    value_2 <= 8'h00;
                    value_2_valid <= 1'b0;
                end
            end
        end else begin
            reqCount <= 8'd0;
            value_2_valid <= 1'b0;
        end

        timer <= timer + 25'd1;
        if(timer == 25'd0)
            running <= ~running;

        if(timer == 25'd0 && ~running) begin
            value_2_valid <= 1'b0;
        end

        if(value_2_valid && ~ack) begin
            ack <= 1'b1;
        end else if(~value_2_valid) begin
            ack <= 1'b0;
        end
    end
endmodule

module priority_encoder (
    input [3:0] A, B, C, D, // Four 4-bit binary values to be encoded
    input S1, S0, // Select inputs to determine which input to encode
    output reg [1:0] Q // 2-bit output of the priority encoder module
);

always @(*) begin
    if (S1 == 0 && S0 == 0) begin
        if (A > B && A > C && A > D) Q = 0;
        else if (B > C && B > D) Q = 1;
        else if (C > D) Q = 2;
        else Q = 3;
    end
    else if (S1 == 0 && S0 == 1) begin
        if (B > A && B > C && B > D) Q = 0;
        else if (A > C && A > D) Q = 1;
        else if (C > D) Q = 2;
        else Q = 3;
    end
    else if (S1 == 1 && S0 == 0) begin
        if (C > A && C > B && C > D) Q = 0;
        else if (A > B && A > D) Q = 1;
        else if (B > D) Q = 2;
        else Q = 3;
    end
    else if (S1 == 1 && S0 == 1) begin
        if (D > A && D > B && D > C) Q = 0;
        else if (A > B && A > C) Q = 1;
        else if (B > C) Q = 2;
        else Q = 3;
    end
end

endmodule

module adder_subtractor (
    input [3:0] A, B, // Two 4-bit binary values to be added or subtracted
    input Cn, // Carry-in input for the adder
    input Sub, // Subtraction mode select input
    output reg [3:0] S, // 4-bit output of the adder/subtractor module
    output reg Cout // Carry-out output of the adder
);

always @(*) begin
    if (Sub == 1) begin
        S = A - B;
        Cout = ~(A < B);
    end
    else begin
