module fir_filter(
    input clk,
    input [15:0] din,
    input new_data_rdy,
    output [27:0] dout,
    output output_data_ready
);

    parameter WIDTH = 5'b10000;
    parameter COEF0 = -15;
    parameter COEF1 = 25;
    parameter COEF2 = 193;
    parameter COEF3 = 0;
    parameter COEF4 = -193;
    parameter COEF5 = -25;
    parameter COEF6 = 15;

    reg [15:0] n_delay_reg1;
    reg [15:0] n_delay_reg2;
    reg [15:0] n_delay_reg3;
    reg [15:0] n_delay_reg4;
    reg [15:0] n_delay_reg5;
    reg [15:0] n_delay_reg6;
    reg output_data_ready;
    reg [27:0] dout;

    always @(posedge clk) begin
        if (new_data_rdy) begin
            n_delay_reg1 <= din;
            n_delay_reg2 <= n_delay_reg1;
            n_delay_reg3 <= n_delay_reg2;
            n_delay_reg4 <= n_delay_reg3;
            n_delay_reg5 <= n_delay_reg4;
            n_delay_reg6 <= n_delay_reg5;

            output_data_ready <= 1;

            dout <= (din * COEF0) + 
                    (n_delay_reg1 * COEF1) + 
                    (n_delay_reg2 * COEF2) + 
                    (n_delay_reg3 * COEF3) + 
                    (n_delay_reg4 * COEF4) + 
                    (n_delay_reg5 * COEF5) + 
                    (n_delay_reg6 * COEF6);
        end else begin
            output_data_ready <= 0;
        end
    end
endmodule

