  wire [99:0] reversed;
  genvar i;
  generate
    for (i = 0; i < 100; i = i + 4) begin
      assign reversed[i+3:i] = in[i:i+3];
    end
  endgenerate

  // Compute the bitwise XOR of the original and reversed vectors
  assign out = in ^ reversed;

