module inv_trig (
  input signed [31:0] x,
  output reg signed [31:0] y
);

parameter PI = 3.14159265358979323846; // value of pi

// Compute the angle for arcsin(x)
always @(*) begin
  if (x >= 1) begin
    y = PI/2;
  end else if (x <= -1) begin
    y = -PI/2;
  end else begin
    y = atan2(x, sqrt(1 - x*x));
  end
end

// Compute the angle for arccos(x)
always @(*) begin
  if (x >= 1) begin
    y = 0;
  end else if (x <= -1) begin
    y = PI;
  end else begin
    y = atan2(sqrt(1 - x*x), x);
  end
end

// Compute the angle for arctan(x)
always @(*) begin
  y = atan2(x, 1);
end

// Compute the arctangent function using the CORDIC algorithm
function [31:0] atan2;
  input signed [31:0] y;
  input signed [31:0] x;
  reg signed [31:0] angle;
  reg signed [31:0] x_temp;
  reg signed [31:0] y_temp;
  reg signed [31:0] angle_temp;
  reg signed [31:0] scale_factor;
  reg [31:0] i;
  begin
    if (x == 0) begin
      if (y > 0) begin
        angle = PI/2;
      end else if (y < 0) begin
        angle = -PI/2;
      end else begin
        angle = 0;
      end
    end else begin
      angle = 0;
      x_temp = x;
      y_temp = y;
      scale_factor = 1;
      for (i = 0; i < 16; i = i + 1) begin
        if (y_temp > 0) begin
          angle_temp = scale_factor * PI/4;
          x_temp = x_temp + (y_temp >> i);
          y_temp = y_temp - (x_temp >> i);
          angle = angle + angle_temp;
        end else begin
          angle_temp = -scale_factor * PI/4;
          x_temp = x_temp - (y_temp >> i);
          y_temp = y_temp + (x_temp >> i);
          angle = angle + angle_temp;
        end
        scale_factor = scale_factor / 2;
      end
    end
    atan2 = angle;
  end
endfunction

endmodule

