  trn <= #1 tg68_as;
  ack <= #1 trn;
end

// outputs
assign tg68_dat_in = mem_do;
assign tg68_dtack = ack || tg68_as;

endmodule

module nios_system_jtag_uart_0_sim_scfifo_r (
    // inputs:
    clk,
    fifo_rd,
    rst_n,

    // outputs:
    fifo_EF,
    fifo_rdata,
    rfifo_full,
    rfifo_used
);

    output fifo_EF;
    output [7:0] fifo_rdata;
    output rfifo_full;
    output [5:0] rfifo_used;
    input clk;
    input fifo_rd;
    input rst_n;

    reg [31:0] bytes_left;
    wire fifo_EF;
    reg fifo_rd_d;
    wire [7:0] fifo_rdata;
    wire new_rom;
    wire [31:0] num_bytes;
    wire [6:0] rfifo_entries;
    wire rfifo_full;
    wire [5:0] rfifo_used;

    // counter for bytes left in FIFO
    always @(posedge clk or negedge rst_n) begin
        if (rst_n == 0) begin
            bytes_left <= 32'h0;
        end else begin
            if (fifo_rd_d) begin
                // decrement on read
                bytes_left <= bytes_left - 1'b1;
            end

            // catch new contents
            if (new_rom) begin
                bytes_left <= num_bytes;
            end
        end
    end

    // calculate FIFO fullness and usage
    assign fifo_EF = bytes_left == 32'b0;
    assign rfifo_full = bytes_left > 7'h40;
    assign rfifo_entries = (rfifo_full) ? 7'h40 : bytes_left;
    assign rfifo_used = rfifo_entries[5:0];

    // read data from FIFO
    assign fifo_rdata = (bytes_left > 0 && !fifo_EF && fifo_rd_d) ? 8'b1 : 8'b0;

    // reset FIFO on reset signal
    always @(negedge rst_n) begin
        if (rst_n == 0) begin
            fifo_rd_d <= 1'b0;
            bytes_left <= 32'h0;
        end
    end

    // catch new contents
    always @(posedge clk) begin
        if (new_rom) begin
            bytes_left <= num_bytes;
        end
        fifo_rd_d <= fifo_rd;
    end

endmodule

module ripple_adder(a, b, c_in, sum, c_out, P, G);
   input [3:0] a, b;
   input c_in;
   output [3:0] sum;
   output c_out;
   output [3:0] P, G;

   wire [3:0] c;
   wire [4:0] p, g;

   full_adder f0(a[0], b[0], c_in, sum[0], p[0], g[0]);
   full_adder f1(a[1], b[1], c[0], sum[1], p[1], g[1]);
   full_adder f2(a[2], b[2], c[1], sum[2], p[2], g[2]);
   full_adder f3(a[3], b[3], c[2], sum[3], p[3], g[3]);

   lookahead la(c_in, c_out, c, p, g, P, G);
endmodule

module full_adder(a, b, c_in, sum, c_out);
   input a, b, c_in;
   output sum, c_out;

   assign {c_out, sum} = a + b + c_in;
endmodule

module lookahead(c_in, c_out, c, p, g, P, G);
   input c_in;
   output c_out;
   output [2:0] c;
   output [3:0] p, g;

   assign c[0] = p[0] | (g[0] & c_in);
   assign c[1] = p[1] | (g[1] & p[0]);
   assign c[2] = p[2] | (g[2] & p[1]);
   assign c_out = p[3] | (g[3] & p[2]);

   assign P[0] = a[0] & b[0];
   assign P[1] = a[1] & b[1];
   assign P[2] = a[2] & b[2];
   assign P[3] = a[3] & b[3];

   assign G[0] = a[0] | b[0];
   assign G[1] = a[1] | b[1];
   assign G[2] = a[2] | b[2];
   assign G[3] = a[3] | b[3];
endmodule

module test_sram_if (
  input clk,
  input rst,
  input [WIDTH-1:0] RAM_D_pi,
  output [WIDTH-1:0] RAM_D_po,
  output RAM_D_poe,
  output [DEPTH-1:0] RAM_A,
  output RAM_WEn,
  output RAM_CENn,
  output RAM_LDn,
  output RAM_OEn,
  output RAM_CE1n,
  output reg correct
);

  reg [DEPTH-1:0] write_count;
  reg [DEPTH-1:0] read_count;
  reg enable;
  reg write;
  reg write_cycle;
  reg read_cycle;
  reg enable_reads;
  reg [18:0] address;
  reg [WIDTH-1:0] data_out;
  wire [WIDTH-1:0] data_in;
  wire data_in_valid;

  reg [WIDTH-1:0] check_data;
  reg [WIDTH-1:0] check_data_old;
  reg [WIDTH-1:0] check_data_old2;

  always @(posedge clk) begin
    if (rst) begin
      write_count <= 19'h0;
      read_count <= 19'h0;
    end else if (write_cycle) begin
      if (write_count == 19'h7FFFF) begin
        write_count <= 19'h0;
      end else begin
        write_count <= write_count + 1'b1;
      end
    end else if (read_cycle) begin
      if (read_count == 19'h7FFFF) begin
        read_count <= 19'h0;
      end else begin
        read_count <= read_count + 1'b1;
      end
    end
  end

  always @(posedge clk) begin
    if (rst) begin
      enable_reads <= 0;
      read_cycle <= 0;
      write_cycle <= 0;
    end else begin
      write_cycle <= ~write_cycle;
      if (enable_reads) begin
        read_cycle <= write_cycle;
      end
      if (write_count == 15) begin
        enable_reads <= 1;
      end
    end
  end

  always @(posedge clk) begin
    if (rst) begin
      enable <= 0;
    end else if (write_cycle) begin
      address <= write_count;
      data_out <= write_count[WIDTH-1:0];
      enable <= 1;
      write <= 1;
    end else if (read_cycle) begin
      address <= read_count;
      check_data <= read_count[WIDTH-1:0];
      check_data_old <= check_data;
      check_data_old2 <= check_data_old;
      enable <= 1;
      write <= 0;
    end else begin
      enable <= 0;
    end
  end

  always @(posedge clk) begin
    if (data_in_valid) begin
      correct <= (data_in == check_data_old2);
    end
  end

  nobl_if nobl_if_i1 (
    .clk(clk),
    .rst(rst),
    .RAM_D_pi(RAM_D_pi),
    .RAM_D_po(RAM_D_po),
    .RAM_D_poe(RAM_D_poe),
    .RAM_A(RAM_A),
    .RAM_WEn(RAM_WEn),
    .RAM_CENn(RAM_CENn),
    .RAM_LDn(RAM_LDn),
    .RAM_OEn(RAM_OEn),
    .RAM_CE1n(RAM_CE1n),
    .address(address),
    .data_out(data_out),
    .data_in(data_in),
    .data_in_valid(data_in_valid),
    .write(write),
    .enable(enable)
  );

  wire [35:0] CONTROL0;
  reg [7:0] data_in_reg, data_out_reg, address_reg;
  reg data_in_valid_reg, write_reg, enable_reg, correct_reg;

  always @(posedge clk) begin
    data_in_reg <= data_in[7:0];
    data_out_reg <= data_out[7:0];
    data_in_valid_reg <= data_in_valid;
    write_reg <= write;
    enable_reg <= enable;
    correct_reg <= correct;
    address_reg <= address;
  end

  icon icon_i1 (
    .CONTROL0(CONTROL0)
  );

  ila ila_i1 (
    .CLK(clk),
    .CONTROL(CONTROL0),
    .TRIG0(data_in_reg[7:0]),
    .TRIG1(data_out_reg[7:0]),
    .TRIG2(address_reg[7:0]),
    .TRIG3({data_in_valid_reg, write_reg, enable_reg, correct_reg})
  );

endmodule

