always @(posedge clk) begin
    if (load) begin
        shift_reg <= data;
    end else begin
        case (ena)
            2'b01: shift_reg <= {shift_reg[0], shift_reg[99:1]};
            2'b10: shift_reg <= {shift_reg[98:0], shift_reg[99]};
            default: shift_reg <= shift_reg;
        endcase
    end
end

assign out = shift_reg;

endmodule

