module BinaryAdder (
  input [3:0] A,
  input [3:0] B,
  input Cin,
  output reg [4:0] C
);

  always @(A, B, Cin) begin
    // Perform the binary addition operation
    C[0] = A[0] ^ B[0] ^ Cin;
    C[1] = A[1] ^ B[1] ^ ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin));
    C[2] = A[2] ^ B[2] ^ ((A[1] & B[1]) | (A[1] & C[1]) | (B[1] & C[1]));
    C[3] = A[3] ^ B[3] ^ ((A[2] & B[2]) | (A[2] & C[2]) | (B[2] & C[2]));
    C[4] = (A[3] & B[3]) | (A[3] & C[3]) | (B[3] & C[3]);
  end

endmodule

module d_flip_flop(CLK, D, SET, RESET, DELAY, Q, QN);
  input CLK, D, SET, RESET, DELAY;
  output Q, QN;
  reg Q, QN;
  reg Q_next;
  wire NOT_CLK;

  assign NOT_CLK = ~CLK;

  always @(posedge CLK) begin
    if (SET) begin
      Q <= 1'b1;
      QN <= 1'b0;
    end else if (RESET) begin
      Q <= 1'b0;
      QN <= 1'b1;
    end else begin
      Q_next <= D;
    end
  end

  always @(negedge CLK) begin
    if (DELAY) begin
      Q <= Q_next;
      QN <= ~Q_next;
    end
  end

endmodule

