module dsp_module(clk, reset, sel, addr, w, data, out, done);
    input clk, reset;
    input sel;
    input [5:0] addr;
    input w;
    input [197:0] data;
    output [197:0] out;
    output done;

    /* for FSM */
    reg [1:0] state, next_state;
    parameter INIT = 2'b00, WRITE = 2'b01, SELECT = 2'b10, CALCULATE = 2'b11;
    /* for RAM */
    reg [5:0] ram_a_addr, ram_b_addr;
    reg [197:0] ram_b_data_in;
    reg ram_a_w, ram_b_w;
    reg [197:0] ram_a_data_out, ram_b_data_out;
    /* for const */
    reg [197:0] const0_out, const1_out;
    reg const0_effective, const1_effective;
    /* for muxer */
    wire [197:0] muxer0_out, muxer1_out;
    /* for ROM */
    wire [8:0] rom_addr;
    wire [25:0] rom_q;
    /* for PE */
    wire [10:0] pe_ctrl;

    assign out = ram_a_data_out;

    select 
        select0 (sel, addr, ram_a_addr, w, ram_a_addr, ram_a_w);
    rom
        rom0 (clk, rom_addr, rom_q);
    FSM
        fsm0 (clk, reset, rom_addr, rom_q, state, next_state, ram_b_addr, ram_b_w, pe_ctrl, done);
    const
        const0 (clk, ram_a_addr, const0_out, const0_effective),
        const1 (clk, ram_b_addr, const1_out, const1_effective);
    ram
        ram0 (clk, ram_a_w, ram_a_addr, data, ram_a_data_out, ram_b_w, ram_b_addr[5:0], ram_b_data_in, ram_b_data_out);
    muxer
        muxer0 (ram_a_data_out, const0_out, const0_effective, muxer0_out),
        muxer1 (ram_b_data_out, const1_out, const1_effective, muxer1_out);
    PE
        pe0 (clk, reset, pe_ctrl, muxer1_out, muxer0_out[193:0], muxer0_out[193:0], ram_b_data_in[193:0]);

    always @(posedge clk) begin
        if (reset) begin
            state <= INIT;
        end else begin
            state <= next_state;
        end
    end

    always @* begin
        next_state = state;
        case (state)
            INIT: begin
                next_state = WRITE;
                ram_b_addr <= 0;
                ram_b_w <= 1;
                pe_ctrl <= 0;
            end
            WRITE: begin
                next_state = SELECT;
                ram_a_addr <= addr;
                ram_a_w <= w;
                ram_b_w <= 0;
            end
            SELECT: begin
                next_state = CALCULATE;
                if (addr == 0) begin
                    const0_effective <= 1;
                end else begin
                    const0_effective <= 0;
                end
                if (addr == 1) begin
                    const1_effective <= 1;
                end else begin
                    const1_effective <= 0;
                end
            end
            CALCULATE: begin
                next_state = WRITE;
                pe_ctrl <= 1;
                ram_b_addr <= addr;
                ram_b_w <= 1;
            end
        endcase
    end
endmodule

module t_clk (
   // Inputs
   input clk,
   input fastclk,
   input reset_l,
   // Outputs
   output reg [7:0] sig_rst
);

   // surefire lint_off STMINI
   // surefire lint_off CWECSB
   // surefire lint_off NBAJAM
   reg _ranit; 
   initial _ranit=0;
   // surefire lint_off UDDSMX
   reg [7:0] clk_clocks; 
   initial clk_clocks = 0; // surefire lint_off_line WRTWRT
   wire [7:0] clk_clocks_d1r;
   wire [7:0] clk_clocks_d1sr;
   wire [7:0] clk_clocks_cp2_d1r;
   wire [7:0] clk_clocks_cp2_d1sr;
   // verilator lint_off MULTIDRIVEN
   reg [7:0] int_clocks; 
   initial int_clocks = 0;
   // verilator lint_on MULTIDRIVEN
   reg [7:0] int_clocks_copy;

   // verilator lint_off GENCLK
   reg internal_clk; 
   initial internal_clk = 0;
   reg reset_int_;
   // verilator lint_on GENCLK

   always @ (posedge clk) begin
      if (!reset_l) begin
         clk_clocks <= 0;
         int_clocks <= 0;
         internal_clk <= 1'b1;
         reset_int_ <= 0;
      end
      else begin
         internal_clk <= ~internal_clk;
         if (!_ranit) begin
            _ranit <= 1;
            reset_int_ <= 1;
         end
      end
   end

   always @ (posedge clk) begin
      if (!reset_l) begin
         clk_clocks <= 0;
      end
      else begin
         clk_clocks <= clk_clocks + 8'd1;
         if (clk_clocks == 4) begin
            if (sig_rst !== 4) $stop;
            if (clk_clocks_d1r !== 3) $stop;
            if (int_clocks !== 2) $stop;
            if (int_clocks_copy !== 2) $stop;
            if (clk_clocks_d1r !== clk_clocks_cp2_d1r) $stop;
            if (clk_clocks_d1sr !== clk_clocks_cp2_d1sr) $stop;
            $write("*-* All Finished *-*\n");
            $finish;
         end
      end
   end

   always @ (posedge clk or negedge reset_l) begin
      if (!reset_l) begin
         sig_rst <= 0;
      end
      else begin
         sig_rst <= sig_rst + 1;
      end
   end

   always @ (negedge internal_clk) begin
      int_clocks <= int_clocks + 8'd1;
   end

   always @ (int_clocks) begin
      int_clocks_copy = int_clocks;
   end

   t_clk_flop flopa (.clk(clk), .clk2(fastclk), .a(clk_clocks),
                     .q(clk_clocks_d1r), .q2(clk_clocks_d1sr));
   t_clk_flop flopb (.clk(clk), .clk2(fastclk), .a(clk_clocks),
                     .q(clk_clocks_cp2_d1r), .q2(clk_clocks_cp2_d1sr));

endmodule

module apu_envelope_generator
(
  input        clk_in,       // system clock signal
  input        rst_in,       // reset signal
  input        eg_pulse_in,  // 1 clk pulse for every env gen update
  input  [5:0] env_in,       // envelope value (e.g., via $4000)
  input        env_wr_in,    // envelope value write
  input        env_restart,  // envelope restart
  output [3:0] env_out       // output volume
);

reg  [5:0] q_reg;
wire [5:0] d_reg;
reg  [3:0] q_cnt,        d_cnt;
reg        q_start_flag, d_start_flag;

// Register the current envelope value and counter value on each clock cycle
always @(posedge clk_in)
  begin
    if (rst_in)
      begin
        q_reg        <= 6'h00;
        q_cnt        <= 4'h0;
        q_start_flag <= 1'b0;
      end
    else
      begin
        q_reg        <= d_reg;
        q_cnt        <= d_cnt;
        q_start_flag <= d_start_flag;
      end
  end

// Instantiate a divider module that generates a clock signal
reg  divider_pulse_in;
reg  divider_reload;
wire divider_pulse_out;

apu_div #(.PERIOD_BITS(4)) divider(
  .clk_in(clk_in),
  .rst_in(rst_in),
  .pulse_in(divider_pulse_in),
  .reload_in(divider_reload),
  .period_in(q_reg[3:0]),
  .pulse_out(divider_pulse_out)
);

// Update the counter and start flag based on the divider and envelope pulse inputs
always @*
  begin
    d_cnt        = q_cnt;
    d_start_flag = q_start_flag;

    divider_pulse_in = 1'b0;
    divider_reload   = 1'b0;

    if (divider_pulse_out)
      begin
        divider_reload = 1'b1;

        if (q_cnt != 4'h0)
          d_cnt = q_cnt - 4'h1;
        else if (q_reg[5])
          d_cnt = 4'hF;
      end

    if (eg_pulse_in)
      begin
        if (q_start_flag == 1'b0)
          begin
            divider_pulse_in = 1'b1;
          end
        else
          begin
            d_start_flag = 1'b0;
            d_cnt        = 4'hF;
          end
      end

    if (env_restart)
      d_start_flag = 1'b1;
  end

// Update the envelope value based on the envelope write input
assign d_reg = (env_wr_in) ? env_in : q_reg;

// Calculate the envelope output based on the constant volume flag
assign env_out = (q_reg[4]) ? q_reg[3:0] : q_cnt;

endmodule

