);

reg [31:0] read_data;
reg [31:0] write_data;
reg [6:0] address;
reg [1:0] response;
reg read_enable;
reg write_enable;
reg [7:0] write_count;
reg [7:0] read_count;
reg [31:0] dummy_data;
reg [1:0] state;
reg [1:0] next_state;

assign s_axi_rdata = read_data;
assign s_axi_rresp = response;
assign s_axi_rvalid = read_enable;
assign s_axi_wready = !write_enable;
assign s_axi_awready = !read_enable && !write_enable;
assign s_axi_bresp = 0;
assign s_axi_bvalid = write_enable && (write_count == 8);

always @(posedge s_axi_aclk) begin
    if (!s_axi_aresetn) begin
        address <= 0;
        write_data <= 0;
        read_data <= 0;
        response <= 0;
        read_enable <= 0;
        write_enable <= 0;
        write_count <= 0;
        read_count <= 0;
        dummy_data <= 0;
        state <= 0;
        next_state <= 0;
    end else begin
        state <= next_state;
        case (state)
            0: begin // Idle
                if (s_axi_awvalid) begin
                    address <= s_axi_awaddr[6:0];
                    if (s_axi_wstrb[0]) write_data[7:0] <= s_axi_wdata[7:0];
                    if (s_axi_wstrb[1]) write_data[15:8] <= s_axi_wdata[15:8];
                    if (s_axi_wstrb[2]) write_data[23:16] <= s_axi_wdata[23:16];
                    if (s_axi_wstrb[3]) write_data[31:24] <= s_axi_wdata[31:24];
                    write_enable <= s_axi_wvalid;
                    write_count <= 1;
                    next_state <= 1;
                end else if (s_axi_arvalid) begin
                    address <= s_axi_araddr[6:0];
                    read_enable <= 1;
                    read_count <= 1;
                    next_state <= 2;
                end else begin
                    next_state <= 0;
                end
            end
            1: begin // Write
                if (write_enable) begin
                    if (write_count == 8) begin
                        write_enable <= 0;
                        response <= 0;
                        next_state <= 0;
                    end else begin
                        write_count <= write_count + 1;
                        next_state <= 1;
