module clock_generator (
    input clk,
    input reset,
    input enable,
    input [3:0] multiplier,
    input [3:0] divider,
    output reg clk_out,
    output reg locked
);

reg [3:0] counter;
reg [3:0] multiplier_reg;
reg [3:0] divider_reg;
reg locked_reg;

always @(posedge clk, posedge reset) begin
    if (reset) begin
        counter <= 0;
        multiplier_reg <= 0;
        divider_reg <= 0;
        clk_out <= 0;
        locked_reg <= 0;
    end else if (enable) begin
        // Update multiplier and divider registers
        multiplier_reg <= multiplier;
        divider_reg <= divider;

        // Increment counter
        counter <= counter + 1;

        // Check if we need to toggle the clock output
        if (counter == ((multiplier_reg * divider_reg) / 2) - 1) begin
            counter <= 0;
            clk_out <= ~clk_out;
        end

        // Check if the clock is locked
        if (multiplier_reg == divider_reg) begin
            locked_reg <= 1;
        end else begin
            locked_reg <= 0;
        end
    end
end

assign locked = locked_reg;

endmodule

