  lower_threshold = Vref - hysteresis/2;
end

// Compare Vin to the thresholds and generate the output signal
always @(Vin, upper_threshold, lower_threshold) begin
  if (Vin > upper_threshold) begin
    Vout <= 1;
  end else if (Vin < lower_threshold) begin
    Vout <= 0;
  end
end

// Incorporate positive feedback into the circuit to improve stability
always @(posedge Vout) begin
  upper_threshold <= upper_threshold - hysteresis/2;
  lower_threshold <= lower_threshold + hysteresis/2;
end

endmodule

module xor_gate(
    input a,
    input b,
    input c,
    output out
);

wire nand1, nand2, nand3, nand4, nand5;

