module FSM_Game(
	input clock, 
	input reset, 
	input start, 
	input v_sync,
	input perdio,
	output actualizar_bola,
	output actualizar_barra,
	output revisar_bordes_bola,
	output revisar_bordes_barra,
	output reg revisar_estado,
	output reg reset_bola,
	output reg reset_barra);

	/** Indica que la barra esta realizando su logica */
	reg start_barra, start_ball;
	wire busy_barra, busy_ball;

	/** Prueba de la maquina de estados de la barra */
	FSM_Barra fsm_barra(
		.clock(clock),
		.reset(reset),
		.start_barra(start_barra),
		.busy_barra(busy_barra),
		.actualizar_barra(actualizar_barra),
		.revisar_bordes_barra(revisar_bordes_barra)
	);

	/** Prueba de la maquina de estados de la bola */
	FSM_Bola fsm_bola(
		.clock(clock),
		.reset(reset),
		.start_ball(start_ball),
		.busy_ball(busy_ball),
		.actualizar_bola(actualizar_bola),
		.revisar_bordes_bola(revisar_bordes_bola)
	);

	//Definimos los estados de la FSM
	parameter STATE_0 = 0;
	parameter STATE_1 = 1;
	parameter STATE_2 = 2;
	parameter STATE_3 = 3;
	parameter STATE_4 = 4;
	parameter STATE_5 = 5;
	parameter STATE_6 = 6;
	parameter STATE_7 = 7;

	//Estado en que se encuentra actualmente
	reg [2:0] state;

	//display se utiliza para hacer que solo se modifique la posicion una vez
	//por cada vsync
	reg displayed;

	initial
		begin
			state <= STATE_0;
			start_barra <= 1'b0;
			start_ball <= 1'b0;
			displayed <= 0;
			reset_bola <= 1'b0;
			reset_barra <= 1'b0;
			revisar_estado <= 1'b0;
		end

	always@(posedge clock or posedge reset)
		begin
			if(reset)
				begin
					state <= STATE_0;
					start_barra <= 1'b0;
					start_ball <= 1'b0;
					displayed <= 1'b0;
					reset_bola <= 1'b0;
					reset_barra <= 1'b0;
					revisar_estado <= 1'b0;
				end
			else
				begin
					case(state)

						/** Solo espera que se presione start */
						STATE_0:
							begin
								if (start)
									begin
										reset_barra <= 1'b1;
										reset_bola <=1'b1;
										state <= STATE_1;
									end
							end

						STATE_1:
							begin
								reset_barra <= 1'b0;
								reset_bola <=1'b0;
								revisar_estado <= 1'b1;
								state <= STATE_2;
							end

						/** Espera que se realice el chequeo de estado */
						STATE_2: 
							begin
								revisar_estado <= 1'b0;
								state <= STATE_3;
							end

						/** El estado 5 se fija si se perdio el juego*/
						STATE_3:
							begin
								if(perdio)
									begin
										state <= STATE_0;
									end									
								else
									state <= STATE_4;
							end

						/** Activa las maquinas de la barra y la bola */
						STATE_4:
							begin
								if (v_sync)
									begin
										if(!displayed) 
											begin												
												start_barra <= 1'b1;
												start_ball <= 1'b1;
												displayed <= 1'b1;
												state <= STATE_5;
											end
									end
								else
									displayed <= 0;
							end

						/** Se usa para esperar que busy_barra y busy_ball esten estables */
						STATE_5:
							begin
								state <= STATE_6;								
							end

						/** Desactiva las senales de inicio de las maquinas de estado*/
						STATE_6:
							begin
								/** Para que no vuelvan a empezar se hace cero*/
								start_barra <= 1'b0;
								start_ball <= 1'b0;
								state <= STATE_7;
							end

						/** El estado 4 espera que termine de moverse la barra y la bola*/
						STATE_7:
							begin
								/**Espera que hayan terminado las posiciones*/
								if (!busy_barra && !busy_ball)
									begin
										state <= STATE_1;
									end
							end

						default:
							begin
								state <= STATE_0;
							end
					endcase					
				end //end del begin antes del case
		end //end del always
endmodule

module Bit_Shift (
  input [n-1:0] in,
  input [1:0] ctrl,
  output [n-1:0] out
);

parameter n = 8; // number of input signals

// Left shift operation
assign out = (ctrl == 2'b00) ? (in << 1) : out;

// Right shift operation
assign out = (ctrl == 2'b01) ? (in >> 1) : out;

// Arithmetic right shift operation
assign out = (ctrl == 2'b10) ? ((in[n-1] == 1) ? ({n{1'b1}} & (in >> 1)) : (in >> 1)) : out;

endmodule

module top_module(
    input a,
    input b,
    input sel_b1,
    input sel_b2,
    input [99:0] in,
    output out_and,
    output out_or,
    output out_xor
);

    // Control logic module
    wire sel;
    assign sel = (sel_b1) ? 1'b1 : (sel_b2) ? 1'b0 : 1'b1;

    // 2-to-1 multiplexer module
    wire [99:0] mux_out;
    mux_2to1 mux_inst(
        .a(in),
        .b(b),
        .sel(sel),
        .out(mux_out)
    );

    // Functional module
    wire [99:0] and_out;
    wire [99:0] or_out;
    wire [99:0] xor_out;
    logic_100 logic_inst(
        .in(mux_out),
        .and_out(and_out),
        .or_out(or_out),
        .xor_out(xor_out)
    );

    // Output assignments
    assign out_and = &and_out;
    assign out_or = |or_out;
    assign out_xor = ^xor_out;

endmodule

