module VGAVideo(
    input wire [('b1) - ('b1):0] clock,
    input wire [('b1) - ('b1):0] reset,

    output wire [('b1) - ('b1):0] vga_r,
    output wire [('b1) - ('b1):0] vga_g,
    output wire [('b1) - ('b1):0] vga_b,
    output wire [('b1) - ('b1):0] vga_hsync,
    output wire [('b1) - ('b1):0] vga_vsync);

  parameter hack_hcounter_Size = 'b1011;
  parameter hack_vcounter_Size = 'b1010;

  wire [(hack_hcounter_Size) - ('b1):0] hcounter_data_o;
  wire [(hack_vcounter_Size) - ('b1):0] vcounter_data_o;

  // Define the horizontal and vertical sync pulse widths
  parameter H_SYNC_PULSE_WIDTH = 96;
  parameter V_SYNC_PULSE_WIDTH = 2;

  // Define the horizontal and vertical display resolutions
  parameter H_DISPLAY_RES = 640;
  parameter V_DISPLAY_RES = 480;

  // Define the total number of horizontal and vertical lines
  parameter H_TOTAL = 800;
  parameter V_TOTAL = 525;

  // Define the total number of pixels per line
  parameter PIXELS_PER_LINE = 800;

  // Define the active video region
  parameter H_ACTIVE = 640;
  parameter V_ACTIVE = 480;

  // Define the horizontal and vertical front porch
  parameter H_FRONT_PORCH = 16;
  parameter V_FRONT_PORCH = 10;

  // Define the horizontal and vertical back porch
  parameter H_BACK_PORCH = 48;
  parameter V_BACK_PORCH = 33;

  // Define the horizontal and vertical sync polarity
  parameter H_SYNC_POLARITY = 1'b0;
  parameter V_SYNC_POLARITY = 1'b0;

  assign vga_r = 'b1;
  assign vga_g = 'b0;
  assign vga_b = 'b0;

  // Generate the horizontal and vertical sync signals
  assign vga_hsync = (hcounter_data_o[(H_TOTAL - H_SYNC_PULSE_WIDTH - H_BACK_PORCH - 1): (H_TOTAL - H_SYNC_PULSE_WIDTH - H_BACK_PORCH - H_FRONT_PORCH)] == H_SYNC_POLARITY);
  assign vga_vsync = (vcounter_data_o[(V_TOTAL - V_SYNC_PULSE_WIDTH - V_BACK_PORCH - 1): (V_TOTAL - V_SYNC_PULSE_WIDTH - V_BACK_PORCH - V_FRONT_PORCH)] == V_SYNC_POLARITY);

  // Generate the horizontal and vertical counters
  UpCounter #(
      .Size(H_TOTAL - 1))
    hcounter(
      .clock(clock),
      .reset((hcounter_data_o == (H_TOTAL - 1))),
      .count('b1),

      .data_o(hcounter_data_o));
  UpCounter #(
      .Size(V_TOTAL - 1))
    vcounter(
      .clock(clock),
      .reset((vcounter_data_o == (V_TOTAL - 1))),
      .count('b1),

      .data_o(vcounter_data_o));

  // Generate the VGA color signals
  always @ (posedge clock) begin
    if (hcounter_data_o >= (H_TOTAL - H_ACTIVE - H_BACK_PORCH)) begin
      vga_r <= 'b0;
      vga_g <= 'b0;
      vga_b <= 'b0;
    end else begin
      vga_r <= 'b1;
      vga_g <= 'b0;
      vga_b <= 'b0;
    end
  end

endmodule

module Debouncer (
  input in,
  output out
);

parameter debounce_time = 10; // debounce time in clock cycles

reg [debounce_time-1:0] delay_line;
reg stable;
reg [1:0] counter;

always @(posedge clk) begin
  delay_line <= {delay_line[debounce_time-2:0], in};

  if (delay_line == in) begin
    counter <= counter + 1;
  end else begin
    counter <= 0;
  end

  if (counter == debounce_time-1) begin
    stable <= 1;
  end else begin
    stable <= 0;
  end
end

assign out = stable ? delay_line[debounce_time-1:0] : in;

endmodule

module delay_locked_loop (
  input ref_clk,
  input clk_in,
  input enable,
  input reset,
  output reg clk_out
);

parameter delay_bits = 4;
parameter max_delay = 15;

reg [delay_bits-1:0] delay_reg;
reg [delay_bits-1:0] delay_next;
reg [delay_bits-1:0] delay_inc;
reg [delay_bits-1:0] delay_dec;

reg ref_clk_reg;
reg clk_in_reg;
reg [delay_bits-1:0] delay_reg_reg;
reg [delay_bits-1:0] delay_next_reg;
reg [delay_bits-1:0] delay_inc_reg;
reg [delay_bits-1:0] delay_dec_reg;

wire phase_error;
wire phase_error_reg;

assign phase_error = (ref_clk_reg == 1'b1) && (clk_in_reg == 1'b0);
assign phase_error_reg = (ref_clk_reg == 1'b1) && (clk_in_reg == 1'b0);

always @(posedge ref_clk) begin
  ref_clk_reg <= ref_clk;
  clk_in_reg <= clk_in;
  delay_reg_reg <= delay_reg;
  delay_next_reg <= delay_next;
  delay_inc_reg <= delay_inc;
  delay_dec_reg <= delay_dec;
end

always @(posedge clk_in) begin
  if (reset) begin
    delay_reg <= 0;
    delay_next <= 0;
  end else if (enable) begin
    if (phase_error_reg) begin
      if (delay_reg == max_delay) begin
        delay_next <= delay_reg;
      end else begin
        delay_next <= delay_reg + 1;
      end
    end else begin
      if (delay_reg == 0) begin
        delay_next <= delay_reg;
      end else begin
        delay_next <= delay_reg - 1;
      end
    end
  end
end

always @(posedge ref_clk) begin
  if (reset) begin
    delay_reg <= 0;
  end else if (enable) begin
    delay_reg <= delay_next;
  end
end

always @(posedge clk_in) begin
  if (reset) begin
    clk_out <= 0;
  end else if (enable) begin
    clk_out <= #delay_reg_reg clk_in;
  end
end

always @(*) begin
  if (delay_reg == max_delay) begin
    delay_inc = 0;
  end else begin
    delay_inc = delay_reg + 1;
  end
  if (delay_reg == 0) begin
    delay_dec = 0;
  end else begin
    delay_dec = delay_reg - 1;
  end
end

endmodule

