module binary_adder(
    input [1:0] A,
    input [1:0] B,
    input C,
    output reg [2:0] S
);

    // Full Adder 1
    wire w1 = A[0] ^ B[0];
    wire w2 = A[0] & B[0];
    wire w3 = w2 & C;
    reg s1 = w1 ^ C;
    wire c1 = w3 | (w1 & C);

    // Full Adder 2
    wire w4 = A[1] ^ B[1];
    wire w5 = A[1] & B[1];
    wire w6 = w5 & c1;
    reg s2 = w4 ^ c1;
    wire c2 = w6 | (w4 & c1);

    // Output
    assign S = {c2, s2, s1};

endmodule

module top_module (
    input clk, // Clock signal
    input reset, // Synchronous active-high reset
    input [7:0] a, b, c, d, // 8-bit input values
    output reg [7:0] avg // 8-bit output representing the average value
);

    // Instantiate the 8-bit adder module
    wire [7:0] sum1;
    adder_8bit adder1(.a(a), .b(b), .sum(sum1));

    // Instantiate the 8-bit adder module again
    wire [7:0] sum2;
    adder_8bit adder2(.a(c), .b(d), .sum(sum2));

    // Instantiate the 4-bit binary counter module
    reg [3:0] count;
    counter_4bit counter(.clk(clk), .reset(reset), .count(count));

    // Calculate the sum of all four input values
    wire [8:0] sum;
    assign sum = sum1 + sum2;

    // Calculate the average value using the sum and the counter
    always @ (posedge clk, posedge reset) begin
        if (reset) begin
            avg <= 0;
        end else begin
            if (count == 4) begin
                avg <= sum[8:1] >> 2;
            end
        end
    end

endmodule

