module IR_Communication (
  input [n-1:0] data_in,
  input clk,
  output [n-1:0] data_out
);

parameter n = 8; // number of bits in data
parameter baud_rate = 9600; // baud rate in bits per second

reg [n-1:0] tx_data;
reg [n-1:0] rx_data;
reg tx_enable;
reg rx_enable;
reg tx_busy;
reg rx_busy;
reg [7:0] tx_counter;
reg [7:0] rx_counter;
reg tx_bit;
reg rx_bit;
reg [15:0] carrier_counter;
reg carrier_out;

assign data_out = rx_data;

always @(posedge clk) begin
  // Transmitting data
  if (tx_enable) begin
    if (tx_busy) begin
      if (tx_counter == baud_rate/2 - 1) begin
        carrier_counter <= 0;
        tx_bit <= tx_data[tx_counter];
        tx_counter <= 0;
      end else begin
        carrier_counter <= carrier_counter + 1;
        if (carrier_counter == baud_rate/2) begin
          carrier_out <= ~carrier_out;
          tx_counter <= tx_counter + 1;
        end
      end
    end else begin
      if (tx_counter == n - 1) begin
        tx_busy <= 1;
        tx_counter <= 0;
      end else begin
        tx_counter <= tx_counter + 1;
      end
    end
  end else begin
    tx_busy <= 0;
    tx_counter <= 0;
    carrier_out <= 0;
  end

  // Receiving data
  if (rx_enable) begin
    if (rx_busy) begin
      if (rx_counter == baud_rate/2 - 1) begin
        rx_data[rx_counter] <= rx_bit;
        rx_counter <= 0;
      end else begin
        rx_counter <= rx_counter + 1;
      end
    end else begin
      if (carrier_out) begin
        rx_busy <= 1;
        rx_counter <= 0;
      end
    end
  end else begin
    rx_busy <= 0;
    rx_counter <= 0;
  end
end

assign tx_enable = (tx_busy == 0) && (data_in != 0);
assign rx_enable = (rx_busy == 0);

always @(posedge clk) begin
  if (tx_busy) begin
    if (tx_bit) begin
      carrier_out <= ~carrier_out;
    end
  end
end

endmodule

module multiplication_module (
  input clk,
  input reset,
  input [5:0] multiplicand,
  input [5:0] multiplier,
  output reg [10:0] product
);

  reg [5:0] shifted_multiplicand;
  reg [3:0] adder1_out;
  reg [3:0] adder2_out;
  reg [5:0] adder2_in;
  reg [5:0] adder2_in_shifted;
  reg [1:0] iteration_count;
  reg enable;

  always @(posedge clk) begin
    if (reset) begin
      shifted_multiplicand <= 0;
      adder1_out <= 0;
      adder2_out <= 0;
      adder2_in <= 0;
      adder2_in_shifted <= 0;
      iteration_count <= 0;
      enable <= 0;
      product <= 0;
    end else begin
      if (iteration_count == 0) begin
        shifted_multiplicand <= multiplicand;
        adder2_in <= multiplier;
        adder2_in_shifted <= {multiplier, 2'b0};
        enable <= 1;
      end else begin
        shifted_multiplicand <= {shifted_multiplicand[4:0], 1'b0};
        adder2_in <= adder2_out;
        adder2_in_shifted <= {adder2_out, 2'b0};
        enable <= 1;
      end

      if (enable) begin
        adder1_out <= shifted_multiplicand[0] ? adder2_in_shifted + multiplicand : adder2_in_shifted;
        adder2_out <= adder1_out[3:0] + adder1_out[7:4];
        product <= {adder2_out, adder1_out[2:0]};
        iteration_count <= iteration_count + 1;
        enable <= 0;
      end

      if (iteration_count == 6) begin
        iteration_count <= 0;
      end
    end
  end

endmodule

module binary_to_bcd(clk, reset, in, out1, out2, out3, out4, clear);
	input clk, reset, clear;
	input [7:0] in;
	output reg [3:0] out1, out2, out3, out4;

	reg [10:0] temp;

	always @(posedge clk) begin
		if (reset) begin
			temp <= 0;
			out1 <= 0;
			out2 <= 0;
			out3 <= 0;
			out4 <= 0;
		end
		else begin
			if (clear) begin
				out1 <= 0;
				out2 <= 0;
				out3 <= 0;
				out4 <= 0;
				temp <= 0;
			end
			else begin
				temp <= {temp[9:0], in};
				if (temp >= 5'd10000) begin
					temp <= temp + 3'd3;
				end
				if (temp >= 5'd100000) begin
					temp <= temp + 3'd3;
				end
				if (temp >= 5'd1000000) begin
					temp <= temp + 3'd3;
				end
				if (temp >= 5'd10000000) begin
					temp <= temp + 3'd3;
				end
				out1 <= temp[3:0];
				out2 <= temp[7:4];
				out3 <= temp[11:8];
				out4 <= temp[15:12];
			end
		end
	end
endmodule

