always @ (posedge clk) begin
    if (enable_division) begin
        dividend <= a;
        divisor <= b;
        count <= 8;
    end
    if (count == 0) begin
        enable_division <= 0;
        out <= quotient;
    end
end

// Division module
always @ (posedge clk) begin
    if (enable_division) begin
        remainder <= dividend;
        if (remainder >= divisor) begin
            quotient[count-1] <= 1;
            remainder <= remainder - divisor;
        end
        else begin
            quotient[count-1] <= 0;
        end
        count <= count - 1;
        dividend <= remainder << 1;
    end
end

