    input reset,       // Synchronous active-high reset
    input a,           // Input signal to edge detection module
    input select,      // Select input to choose between edge detection module and up-counter
    output [3:0] q     // 4-bit output from the active module
);
    wire [3:0] counter_out;
    wire r_edge, f_edge;

    edge_detection edge_detect(clk, reset, a, r_edge, f_edge);
    up_counter counter(clk, reset, counter_out);

    always @(posedge clk) begin
        if (reset) begin
            q <= 0;
        end else begin
            if (select == 1) begin
                q <= counter_out;
            end else begin
                q <= r_edge | f_edge;
            end
        end
    end
endmodule

