    5: if (in == 4'b0000) next_state = 3'b101;
       else if (in == 4'b0001) next_state = 3'b100;
       else if (in == 4'b0010) next_state = 3'b111;
       else if (in == 4'b0011) next_state = 3'b110;
       else if (in == 4'b0100) next_state = 3'b001;
       else if (in == 4'b0101) next_state = 3'b000;
       else if (in == 4'b0110) next_state = 3'b011;
       else if (in == 4'b0111) next_state = 3'b010;
    6: if (in == 4'b0000) next_state = 3'b110;
       else if (in == 4'b0001) next_state = 3'b111;
       else if (in == 4'b0010) next_state = 3'b100;
       else if (in == 4'b0011) next_state = 3'b101;
       else if (in == 4'b0100) next_state = 3'b010;
       else if (in == 4'b0101) next_state = 3'b011;
       else if (in == 4'b0110) next_state = 3'b000;
       else if (in == 4'b0111) next_state = 3'b001;
    7: if (in == 4'b0000) next_state = 3'b111;
