module emesh_if (/*AUTOARG*/
   // Outputs
   cmesh_ready_out, cmesh_access_out, cmesh_packet_out,
   rmesh_ready_out, rmesh_access_out, rmesh_packet_out,
   xmesh_ready_out, xmesh_access_out, xmesh_packet_out,
   emesh_ready_out, emesh_access_out, emesh_packet_out,
   // Inputs
   cmesh_access_in, cmesh_packet_in, cmesh_ready_in, rmesh_access_in,
   rmesh_packet_in, rmesh_ready_in, xmesh_access_in, xmesh_packet_in,
   xmesh_ready_in, emesh_access_in, emesh_packet_in, emesh_ready_in
   );

   parameter AW   = 32;   
   parameter PW   = 2*AW+40; 

   //##Cmesh##    
   input 	   cmesh_access_in;
   input [PW-1:0]  cmesh_packet_in;
   output 	   cmesh_ready_out;
   output 	   cmesh_access_out;
   output [PW-1:0] cmesh_packet_out;
   input 	   cmesh_ready_in;

   //##Rmesh## 
   input 	   rmesh_access_in;
   input [PW-1:0]  rmesh_packet_in;
   output 	   rmesh_ready_out;
   output 	   rmesh_access_out;
   output [PW-1:0] rmesh_packet_out;
   input 	   rmesh_ready_in;

   //##Xmesh## 
   input 	   xmesh_access_in;
   input [PW-1:0]  xmesh_packet_in;
   output 	   xmesh_ready_out;  
   output 	   xmesh_access_out;
   output [PW-1:0] xmesh_packet_out;
   input 	   xmesh_ready_in;

   //##Emesh##
   input 	   emesh_access_in;
   input [PW-1:0]  emesh_packet_in;
   output 	   emesh_ready_out;

   //core-->io
   output 	   emesh_access_out;
   output [PW-1:0] emesh_packet_out;
   input 	   emesh_ready_in;

   //#####################################################
   //# EMESH-->(RMESH/XMESH/CMESH)
   //#####################################################

   assign cmesh_access_out = emesh_access_in & emesh_packet_in[0];

   assign rmesh_access_out = emesh_access_in & ~emesh_packet_in[0];

   //Don't drive on xmesh for now
   assign xmesh_access_out = 1'b0;

   //Distribute emesh to xmesh,cmesh, rmesh
   assign cmesh_packet_out[PW-1:0] = emesh_packet_in[PW-1:0];	 
   assign rmesh_packet_out[PW-1:0] = emesh_packet_in[PW-1:0];	 
   assign xmesh_packet_out[PW-1:0] = emesh_packet_in[PW-1:0];

   assign emesh_ready_out = cmesh_ready_in &
			    rmesh_ready_in &
			    xmesh_ready_in;

   //#####################################################
   //# (RMESH/XMESH/CMESH)-->EMESH
   //#####################################################

   assign emesh_access_out = cmesh_access_in &
			     rmesh_access_in &
			     xmesh_access_in;

   //Choose the module to send packet to in a round-robin fashion
   reg [1:0] round_robin;
   always @(posedge emesh_ready_in) begin
      if (cmesh_access_in) round_robin <= 2'b01;
      else if (rmesh_access_in) round_robin <= 2'b10;
      else if (xmesh_access_in) round_robin <= 2'b00;
   end

   always @(*) begin
      case (round_robin)
         2'b01: emesh_packet_out[PW-1:0] = cmesh_packet_in[PW-1:0];
         2'b10: emesh_packet_out[PW-1:0] = rmesh_packet_in[PW-1:0];
         2'b00: emesh_packet_out[PW-1:0] = xmesh_packet_in[PW-1:0];
      endcase
   end

   assign cmesh_ready_out = ~(cmesh_access_in & ~emesh_ready_in);

   assign rmesh_ready_out = ~(rmesh_access_in & 
			    (~emesh_ready_in | ~cmesh_ready_in));

   assign xmesh_ready_out = ~(xmesh_access_in & 
			      (~emesh_ready_in | ~cmesh_access_in | ~rmesh_access_in));


endmodule

module ring_counter_shift_register_decoder_mux (
    input clk,
    input d,
    input wire [15:0] in,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo
);

reg [2:0] shift_reg;
wire [1:0] decoder_out;
wire [7:0] mux_out;

// Ring counter shift register
always @(posedge clk) begin
    shift_reg <= {shift_reg[1:0], d};
end

// Decoder
assign decoder_out = shift_reg[2:1];

// Multiplexer
assign mux_out = (decoder_out == 2'b00) ? in[7:0] :
                 (decoder_out == 2'b01) ? in[15:8] :
                 (decoder_out == 2'b10) ? in[7:0] :
                                         in[15:8];

// Output
assign out_hi = (decoder_out == 2'b01) ? mux_out : 8'b0;
assign out_lo = (decoder_out == 2'b10) ? mux_out : 8'b0;

endmodule

module memory_interface (
    input clk,
    input rst,
    input [12:0] mem_addr,
    input [7:0] mem_din,
    input mem_we,
    input mem_re,
    output reg [7:0] mem_dout,
    output reg mem_a,
    output reg [2:0] mem_ba,
    output reg mem_ck,
    output reg mem_ck_n,
    output reg mem_cke,
    output reg mem_cs_n,
    output reg mem_ras_n,
    output reg mem_cas_n,
    output reg mem_we_n,
    output reg mem_reset_n,
    inout [7:0] mem_dq,
    inout mem_dqs,
    inout mem_dqs_n,
    output reg mem_odt,
    output reg mem_dm
);

    always @ (posedge clk or negedge rst) begin
        if(!rst) begin
            mem_a <= 0;
            mem_ba <= 0;
            mem_ck <= 0;
            mem_ck_n <= 1;
            mem_cke <= 0;
            mem_cs_n <= 1;
            mem_ras_n <= 1;
            mem_cas_n <= 1;
            mem_we_n <= 1;
            mem_reset_n <= 1;
            mem_odt <= 0;
            mem_dm <= 0;
        end else begin
            mem_a <= mem_addr;
            mem_ba <= mem_addr[2:0];
            mem_ck <= clk;
            mem_ck_n <= ~clk;
            mem_cke <= 1;
            mem_cs_n <= 0;
            mem_ras_n <= 0;
            mem_cas_n <= 0;
            mem_we_n <= ~mem_we;
            mem_reset_n <= 1;
            mem_odt <= 0;
            mem_dm <= 0;
        end
    end

    assign mem_dq = (mem_re) ? mem_dout : 8'bZZZZZZZZ;
    assign mem_dout = (mem_re) ? mem_dq : 8'bZZZZZZZZ;
    assign mem_dqs = 1'b0;
    assign mem_dqs_n = 1'b1;

endmodule

module digital_clock_alarm (
  input clk,
  input reset,
  input enable,
  input [5:0] set_time,
  input [5:0] set_alarm,
  output [5:0] current_time,
  output alarm_trigger
);

  reg [5:0] hours;
  reg [5:0] minutes;
  reg [5:0] seconds;
  reg alarm_set;
  reg alarm_triggered;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      hours <= 6'b000000;
      minutes <= 6'b000000;
      seconds <= 6'b000000;
      alarm_set <= 1'b0;
      alarm_triggered <= 1'b0;
    end else if (enable) begin
      if (seconds == 6'b011111) begin
        seconds <= 6'b000000;
        if (minutes == 6'b011111) begin
          minutes <= 6'b000000;
          if (hours == 6'b000011) begin
            hours <= 6'b000000;
          end else begin
            hours <= hours + 6'b000001;
          end
        end else begin
          minutes <= minutes + 6'b000001;
        end
      end else begin
        seconds <= seconds + 6'b000001;
      end

      if (set_alarm == {hours, minutes, 6'b000000}) begin
        alarm_triggered <= 1'b1;
      end
    end

    if (set_time != {hours, minutes, 6'b000000} && enable) begin
      hours <= set_time[5:4] == 2'b11 ? 6'b000000 : set_time[5:4] * 6'b000010 + set_time[3:0];
      minutes <= set_time[3:2] * 6'b000010 + set_time[1:0];
      seconds <= 6'b000000;
    end

    if (set_alarm != {hours, minutes, 6'b000000} && enable) begin
      alarm_set <= 1'b1;
    end
  end

  assign current_time = {hours, minutes, seconds};
  assign alarm_trigger = alarm_triggered && alarm_set;

endmodule

