    assign foreground_blue = foreground_pixel[29:20];
    assign foreground_alpha = foreground_pixel[39:30];

    // Extract pixel components from background stream
    assign background_red = background_pixel[9:0];
    assign background_green = background_pixel[19:10];
    assign background_blue = background_pixel[29:20];

    // Combine foreground and background pixels
    assign output_red = (foreground_alpha * foreground_red + (1023 - foreground_alpha) * background_red) / 1023;
    assign output_green = (foreground_alpha * foreground_green + (1023 - foreground_alpha) * background_green) / 1023;
    assign output_blue = (foreground_alpha * foreground_blue + (1023 - foreground_alpha) * background_blue) / 1023;

    // Combine pixel components into output pixel
    assign output_pixel = {output_red, output_green, output_blue};

    // Output assignments
    assign foreground_ready = (state == WAIT_FOREGROUND) && output_ready;
    assign background_ready = (state == WAIT_BACKGROUND) && output_ready;

    assign output_data = output_pixel;
    assign output_empty = output_empty_reg;
    assign output_valid = output_valid_reg;
    assign output_startofpacket = output_startofpacket_reg;
    assign output_endofpacket = output_endofpacket_reg;

    // State machine
    always @ (posedge clk) begin
        if (reset) begin
            state <= IDLE;
            foreground_empty_reg <= 2'b1;
            foreground_valid_reg <= 1'b0;
            background_empty_reg <= 2'b1;
            background_valid_reg <= 1'b0;
            output_empty_reg <= 2'b1;
            output_valid_reg <= 1'b0;
            output_startofpacket_reg <= 1'b0;
            output_endofpacket_reg <= 1'b0;
            foreground_startofpacket_reg <= 1'b0;
            foreground_endofpacket_reg <= 1'b0;
            background_startofpacket_reg <= 1'b0;
            background_endofpacket_reg <= 1'b0;
        end
        else begin
            case (state)
                IDLE: begin
                    if (foreground_valid) begin
                        state <= WAIT_BACKGROUND;
                        foreground_empty_reg <= foreground_empty;
                        foreground_valid_reg <= foreground_valid;
                        foreground_startofpacket_reg <= foreground_startofpacket;
                        foreground_endofpacket_reg <= foreground_endofpacket;
                    end
                    else if (background_valid) begin
                        state <= WAIT_FOREGROUND;
                        background_empty_reg <= background_empty;
                        background_valid_reg <= background_valid;
                        background_startofpacket_reg <= background_startofpacket;
                        background_endofpacket_reg <= background_endofpacket;
                    end
                end
                WAIT_FOREGROUND: begin
                    if (output_ready && foreground_valid) begin
                        state <= BLEND;
                        background_empty_reg <= background_empty;
                        background_valid_reg <= background_valid;
                        background_startofpacket_reg <= background_startofpacket;
                        background_endofpacket_reg <= background_endofpacket;
                    end
                end
                WAIT_BACKGROUND: begin
                    if (output_ready && background_valid) begin
                        state <= BLEND;
                        foreground_empty_reg <= foreground_empty;
                        foreground_valid_reg <= foreground_valid;
                        foreground_startofpacket_reg <= foreground_startofpacket;
                        foreground_endofpacket_reg <= foreground_endofpacket;
                    end
                end
                BLEND: begin
                    if (foreground_valid && background_valid) begin
                        output_empty_reg <= 2'b0;
                        output_valid_reg <= 1'b1;
                        output_startofpacket_reg <= foreground_startofpacket & background_startofpacket;
                        output_endofpacket_reg <= foreground_endofpacket & background_endofpacket;
                        state <= WAIT_FOREGROUND;
                        foreground_empty_reg <= foreground_empty;
                        foreground_valid_reg <= foreground_valid;
                        foreground_startofpacket_reg <= foreground_startofpacket;
                        foreground_endofpacket_reg <= foreground_endofpacket;
                    end
                    else begin
                        output_empty_reg <= 2'b1;
                        output_valid_reg <= 1'b0;
                        output_startofpacket_reg <= 1'b0;
                        output_endofpacket_reg <= 1'b0;
                        state <= IDLE;
                    end
                end
            endcase
        end
    end

    // Assign input streams to internal signals
    always @ (posedge clk) begin
        if (reset) begin
            foreground_pixel <= 30'h0;
            background_pixel <= 30'h0;
        end
        else begin
            if (foreground_valid) begin
                foreground_pixel <= foreground_data;
            end
            if (background_valid) begin
                background_pixel <= background_data;
            end
        end
    end

endmodule

module fsm_consecutive_ones (
  input clk,
  input reset,
  input data,
  output reg done
);

  parameter IDLE = 2'b00;
  parameter COUNTING = 2'b01;
  parameter DONE = 2'b10;

  reg [1:0] state;
  reg [2:0] count;

  always @(posedge clk) begin
    if (reset) begin
      state <= IDLE;
      count <= 0;
      done <= 0;
    end else begin
      case (state)
        IDLE: begin
          if (data) begin
            state <= COUNTING;
            count <= 1;
          end
        end

        COUNTING: begin
          if (data) begin
            count <= count + 1;
            if (count == 5) begin
              state <= DONE;
              done <= 1;
            end
          end else begin
            state <= DONE;
            done <= 1;
          end
        end

        DONE: begin
          if (!data) begin
            state <= IDLE;
            count <= 0;
            done <= 0;
          end
        end
      endcase
    end
  end
endmodule

module parity_check (
  input clk,
  input reset,
  input [7:0] data_in,
  output reg parity_out
);

  reg [7:0] data_reg;
  reg [7:0] data_reg2;
  reg parity_reg;

  always @(posedge clk) begin
    if (reset) begin
      data_reg <= 8'b0;
      data_reg2 <= 8'b0;
      parity_reg <= 1'b0;
      parity_out <= 1'b0;
    end
    else begin
      data_reg <= data_in;
      data_reg2 <= data_reg;
      parity_reg <= ~(^data_reg2);
      parity_out <= parity_reg;
    end
  end

endmodule

module bdd_module (
    input [3:0] in_data,
    input [1:0] op_select,
    output reg [3:0] out_data
);

// BDD-based functional module
always @(*) begin
    case (op_select)
        2'b00: out_data = in_data & 4'b1111; // AND operation
        2'b01: out_data = in_data | 4'b0000; // OR operation
        2'b10: out_data = in_data ^ 4'b1010; // XOR operation
        default: out_data = 4'b0000; // default output
    endcase
end

endmodule

module top_module ( 
    input [2:0] select, 
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    input [2:0] op_select,
    output [3:0] out 
);

wire [3:0] mux_out;
wire [3:0] bdd_out;

// 6-to-1 multiplexer
assign mux_out = (select <= 5) ? 
    ((select == 0) ? data0 :
    (select == 1) ? data1 :
    (select == 2) ? data2 :
    (select == 3) ? data3 :
    (select == 4) ? data4 :
    (select == 5) ? data5 : 4'b0000) : 4'b0000;

// BDD-based functional module instantiation
bdd_module bdd_inst (
    .in_data(mux_out),
    .op_select(op_select),
    .out_data(bdd_out)
);

// Output selection based on select input
assign out = (select <= 5) ? mux_out : bdd_out;

endmodule

module power_controller (
    input clk,
    input rst,
    input enable,
    input [7:0] voltage,
    output reg vdd,
    output reg vss
);

// Constants
localparam MAX_VOLTAGE = 8'd255;
localparam MIN_VOLTAGE = 8'd0;
localparam MAX_LEVEL = 1'b1;
localparam MIN_LEVEL = 1'b0;
localparam MAX_VDD = 8'd127;
localparam MAX_VSS = 8'd128;

// Variables
reg [7:0] vdd_voltage;
reg [7:0] vss_voltage;

// Reset
always @(posedge clk) begin
    if (rst) begin
        vdd <= MIN_LEVEL;
        vss <= MIN_LEVEL;
        vdd_voltage <= MIN_VOLTAGE;
        vss_voltage <= MAX_VOLTAGE;
    end
end

// Voltage control
always @(posedge clk) begin
    if (enable) begin
        // Set VDD voltage level
        if (voltage > MAX_VDD) begin
            vdd_voltage <= MAX_VDD;
        end else begin
            vdd_voltage <= voltage;
        end

        // Set VSS voltage level
        if (~voltage > MAX_VSS) begin
            vss_voltage <= MAX_VSS;
        end else begin
            vss_voltage <= ~voltage;
        end
    end else begin
        vdd_voltage <= MIN_VOLTAGE;
        vss_voltage <= MAX_VOLTAGE;
    end
end

// Voltage supply
always @(posedge clk) begin
    if (vdd_voltage > MAX_VDD) begin
        vdd <= MAX_LEVEL;
    end else if (vdd_voltage < MIN_VOLTAGE) begin
        vdd <= MIN_LEVEL;
    end else begin
        vdd <= vdd_voltage[MAX_VDD-1];
    end

    if (vss_voltage > MAX_VOLTAGE) begin
        vss <= MAX_LEVEL;
    end else if (vss_voltage < MIN_VSS) begin
        vss <= MIN_LEVEL;
    end else begin
        vss <= vss_voltage[MAX_VOLTAGE-1];
    end
end

endmodule

