module gpio_delayed_trigger #
(
  parameter integer GPIO_DATA_WIDTH = 8,
  parameter integer GPIO_INPUT_WIDTH = 4,
  parameter integer GPIO_OUTPUT_WIDTH = 4
)
(
  // System signals
  input  wire                        aclk,
  input  wire                        aresetn,

  inout  wire [GPIO_DATA_WIDTH-1:0]  gpio_data,
  input  wire [GPIO_OUTPUT_WIDTH-1:0]  out_data,


  input  wire                        soft_trig,
  input  wire [31:0]                 delay,
  output wire                        trigger,
  output wire                        instant_trigger,
  output wire                        delay_pulse
);

  reg  [GPIO_DATA_WIDTH-1:0] int_data_reg [1:0];
  reg  triggered, int_trig_reg, int_trig_reg_next,out_trig, out_trig_next;
  reg  [31:0] counter, counter_next;
  wire [GPIO_DATA_WIDTH-1:0] int_data_wire;
  wire int_comp_wire;
  wire [GPIO_OUTPUT_WIDTH-1:0] int_output;

  genvar j;


  // input pins
  generate
    for(j = 0; j < GPIO_INPUT_WIDTH; j = j + 1)
      begin : GPIO
        IOBUF gpio_iobuf (.O(int_data_wire[j]), .IO(gpio_data[j]), .I({(GPIO_INPUT_WIDTH){1'b0}}), .T(1'b1)); 
      end
  endgenerate

  // output pins
  generate
    for(j = GPIO_INPUT_WIDTH; j < GPIO_DATA_WIDTH; j = j + 1)
      begin : GPIO_OUT
        IOBUF gpio_iobuf (.O(int_data_wire[j]), .IO(gpio_data[j]), .I(int_output[j-GPIO_INPUT_WIDTH]), .T(1'b0)); 
      end
  endgenerate

  assign int_comp_wire = counter < delay;
  always @(posedge aclk)
  begin
      int_data_reg[0] <= int_data_wire;
      int_data_reg[1] <= int_data_reg[0];
      if(~aresetn)
         begin
      	int_trig_reg <= 1'b0;
           out_trig <= 1'b0;
           counter <= 32'b0;
         end
      else
         begin
  	    int_trig_reg <= int_trig_reg_next;
            out_trig <= out_trig_next;
            counter <= counter_next;
         end
  end

  always @*
  begin 
      int_trig_reg_next = int_trig_reg;
      out_trig_next = out_trig;
      counter_next = counter;
      if(soft_trig | int_data_reg[1][0:0])
          int_trig_reg_next = 1'b1;
      if ( int_comp_wire & int_trig_reg)
           counter_next=counter  + 1'b1;
      if ( ~int_comp_wire)
          out_trig_next = 1'b1;
      end


  assign trigger  = out_trig;
  assign instant_trigger  = int_trig_reg;
  assign delay_pulse = instant_trigger&~trigger;
  assign int_output = {{(GPIO_OUTPUT_WIDTH-1){1'b0}},delay_pulse};

endmodule

module IMUL2
(
    input wire [15:0] iSourceData0,
    input wire [15:0] iSourceData1,
    output reg [31:0] oResult
);

    wire [31:0] cero, uno, dos, tres;
    wire [31:0] oMux1, oMux2, oMux3, oMux4, oMux5, oMux6, oMux7, oMux8;

    assign cero = 0;
    assign uno = iSourceData0;
    assign dos = iSourceData0 << 1;
    assign tres = (iSourceData0 << 1) + iSourceData0;

    MUX4X1 Mux1(
        .iInput0(cero),
        .iInput1(uno),
        .iInput2(dos),
        .iInput3(tres),
        .iSelect({iSourceData1[1], iSourceData1[0]}),
        .oOutput(oMux1)
    );

    MUX4X1 Mux2(
        .iInput0(cero),
        .iInput1(uno),
        .iInput2(dos),
        .iInput3(tres),
        .iSelect({iSourceData1[3], iSourceData1[2]}),
        .oOutput(oMux2)
    );

    MUX4X1 Mux3(
        .iInput0(cero),
        .iInput1(uno),
        .iInput2(dos),
        .iInput3(tres),
        .iSelect({iSourceData1[5], iSourceData1[4]}),
        .oOutput(oMux3)
    );

    MUX4X1 Mux4(
        .iInput0(cero),
        .iInput1(uno),
        .iInput2(dos),
        .iInput3(tres),
        .iSelect({iSourceData1[7], iSourceData1[6]}),
        .oOutput(oMux4)
    );

    MUX4X1 Mux5(
        .iInput0(cero),
        .iInput1(uno),
        .iInput2(dos),
        .iInput3(tres),
        .iSelect({iSourceData1[9], iSourceData1[8]}),
        .oOutput(oMux5)
    );

    MUX4X1 Mux6(
        .iInput0(cero),
        .iInput1(uno),
        .iInput2(dos),
        .iInput3(tres),
        .iSelect({iSourceData1[11], iSourceData1[10]}),
        .oOutput(oMux6)
    );

    MUX4X1 Mux7(
        .iInput0(cero),
        .iInput1(uno),
        .iInput2(dos),
        .iInput3(tres),
        .iSelect({iSourceData1[13], iSourceData1[12]}),
        .oOutput(oMux7)
    );

    MUX4X1 Mux8(
        .iInput0(cero),
        .iInput1(uno),
        .iInput2(dos),
        .iInput3(tres),
        .iSelect({iSourceData1[15], iSourceData1[14]}),
        .oOutput(oMux8)
    );

    always @(*) begin
        oResult = oMux1 + (oMux2 << 2) + (oMux3 << 4) + (oMux4 << 6) + (oMux5 << 8) + (oMux6 << 10) + (oMux7 << 12) + (oMux8 << 14);
    end

endmodule

