module flip_flop (
  input clk,
  input rst,
  input d,
  input j,
  input k,
  input t,
  input s,
  input r,
  output reg q,
  output reg qn
);

parameter type = "D"; // type of flip-flop (D, JK, T, or SR)

always @(posedge clk, negedge rst) begin
  if (~rst) begin
    q <= 1'b0;
    qn <= 1'b1;
  end else begin
    case (type)
      "D": begin
        q <= d;
        qn <= ~d;
      end
      "JK": begin
        if (j & k) begin
          q <= ~q;
          qn <= ~q;
        end else if (j) begin
          q <= 1'b1;
          qn <= 1'b0;
        end else if (k) begin
          q <= 1'b0;
          qn <= 1'b1;
        end
      end
      "T": begin
        if (t) begin
          q <= ~q;
          qn <= ~q;
        end
      end
      "SR": begin
        if (s & ~r) begin
          q <= 1'b1;
          qn <= 1'b0;
        end else if (~s & r) begin
          q <= 1'b0;
          qn <= 1'b1;
        end
      end
    endcase
  end
end

endmodule

