);

always @(*) begin
    case ({rotate_left, rotate_right, shift_left, shift_right})
        4'b0001: result = {data[2:0], data[3]};
        4'b0010: result = {data[1:0], data[3:2]};
        4'b0100: result = {data[0], data[3:1]};
        4'b1000: result = {data[3], data[2:0]};
        default: result = data;
    endcase
end

endmodule

module majority_decoder (
    input A, B, C, D, // Inputs for majority gate
    output reg [15:0] out // Output from decoder
);

// Majority gate
wire majority = (A & B & C) | (A & B & D) | (A & C & D) | (B & C & D);

// 4-to-16 decoder
wire [3:0] in = {D, C, B, A};
decoder_4to16 decoder(.in(in), .out(out));

// Final output logic
always @(*) begin
    if (majority) begin
        out = ~out;
    end
end

