module motor_control (
  input pwm, // PWM signal
  input clk, // clock signal for PWM
  input [1:0] in, // input signals for H-bridge
  input ctrl, // control signal for H-bridge
  input step, // step signal for stepper motor
  input dir, // direction signal for stepper motor
  output pwm_out, // PWM output signal
  output [1:0] out, // output signals for H-bridge
  output [3:0] stepper_out // output signals for stepper motor
);

parameter n = 200; // number of steps for stepper motor

reg [7:0] pwm_count = 8'd0; // counter for PWM duty cycle
reg [7:0] step_count = 8'd0; // counter for stepper motor steps
reg [1:0] hbridge_out = 2'b00; // output signals for H-bridge
reg [3:0] stepper_pos = 4'b0000; // current position of stepper motor

always @(posedge clk) begin
  // PWM control block
  if (pwm_count < pwm) begin
    pwm_out <= 1'b1;
  end else begin
    pwm_out <= 1'b0;
  end
  pwm_count <= pwm_count + 1;

  // H-bridge control block
  case (ctrl)
    2'b00: hbridge_out <= 2'b00;
    2'b01: hbridge_out <= in;
    2'b10: hbridge_out <= ~in;
    2'b11: hbridge_out <= 2'b00;
  endcase
  out <= hbridge_out;

  // Stepper motor control block
  if (step_count >= n) begin
    step_count <= 8'd0;
    case (dir)
      1'b0: stepper_pos <= stepper_pos + 1;
      1'b1: stepper_pos <= stepper_pos - 1;
    endcase
  end else begin
    step_count <= step_count + 1;
  end
  case (stepper_pos)
    4'b0001: stepper_out <= 4'b0001;
    4'b0010: stepper_out <= 4'b0010;
    4'b0100: stepper_out <= 4'b0100;
    4'b1000: stepper_out <= 4'b1000;
    default: stepper_out <= 4'b0000;
  endcase

end

endmodule

module RAMBuffer(
    input clk,
    input RAMread,
    input [15:0] ramCode,
    input [15:0] ramString,
    input [17:0] ramDicPointer,
    input [15:0] iRAMBuffer,
    input [15:0] RAMZeroData,
    input [15:0] InitRAMCode,
    input [15:0] WriteString,
    output reg [15:0] oRAMBuffer
    );

    reg [15:0] RAMBuffer [0:65535];
    reg [15:0] RAMIndex;
    reg [15:0] RAMData;
    reg [15:0] RAMZeroDataReg;
    reg [15:0] InitRAMCodeReg;
    reg [15:0] WriteStringReg;
    reg [15:0] WriteStringIndex;
    reg [15:0] WriteStringSize;
    reg [15:0] WriteStringData;
    reg [15:0] WriteStringRAMIndex;
    reg [15:0] WriteStringRAMData;
    reg [15:0] WriteStringRAMSize;
    reg [15:0] WriteStringRAMDataIndex;

    always @(posedge clk) begin
        if (RAMread) begin
            oRAMBuffer <= RAMBuffer[RAMIndex];
        end
        if (iRAMBuffer != 0) begin
            RAMBuffer[RAMIndex] <= iRAMBuffer;
        end
        if (RAMIndex == 0) begin
            RAMZeroDataReg <= RAMZeroData;
            InitRAMCodeReg <= InitRAMCode;
            WriteStringReg <= WriteString;
            WriteStringSize <= WriteStringReg[15:0];
            WriteStringIndex <= 0;
            WriteStringRAMIndex <= 0;
            WriteStringRAMSize <= 0;
            WriteStringRAMDataIndex <= 0;
        end
        if (RAMIndex == 1) begin
            RAMData <= InitRAMCodeReg;
        end
        if (RAMIndex == 2) begin
            RAMData <= WriteStringSize;
        end
        if (RAMIndex >= 3 && RAMIndex < 3 + WriteStringSize) begin
            if (WriteStringIndex == 0) begin
                WriteStringData <= WriteStringReg[15:0];
            end
            RAMData <= WriteStringData[WriteStringIndex*16+:16];
            WriteStringIndex <= WriteStringIndex + 1;
        end
        if (RAMIndex == 3 + WriteStringSize) begin
            WriteStringRAMSize <= RAMData;
        end
        if (RAMIndex >= 4 + WriteStringSize && RAMIndex < 4 + WriteStringSize + WriteStringRAMSize) begin
            if (WriteStringRAMDataIndex == 0) begin
                WriteStringRAMData <= RAMData;
            end
            RAMBuffer[WriteStringRAMIndex] <= WriteStringRAMData[WriteStringRAMDataIndex*16+:16];
            WriteStringRAMIndex <= WriteStringRAMIndex + 1;
            WriteStringRAMDataIndex <= WriteStringRAMDataIndex + 1;
        end
    end

    always @(posedge clk) begin
        if (RAMIndex == 0) begin
            RAMData <= RAMZeroDataReg;
        end
        if (RAMIndex == 1) begin
            RAMData <= InitRAMCodeReg;
        end
        if (RAMIndex == 2) begin
            RAMData <= WriteStringSize;
        end
        if (RAMIndex >= 3 && RAMIndex < 3 + WriteStringSize) begin
            if (WriteStringIndex == 0) begin
                WriteStringData <= WriteStringReg[15:0];
            end
            RAMData <= WriteStringData[WriteStringIndex*16+:16];
            WriteStringIndex <= WriteStringIndex + 1;
        end
        if (RAMIndex == 3 + WriteStringSize) begin
            RAMData <= WriteStringRAMSize;
        end
        if (RAMIndex >= 4 + WriteStringSize && RAMIndex < 4 + WriteStringSize + WriteStringRAMSize) begin
            if (WriteStringRAMDataIndex == 0) begin
                WriteStringRAMData <= RAMData;
            end
            RAMData <= WriteStringRAMData[WriteStringRAMDataIndex*16+:16];
            WriteStringRAMDataIndex <= WriteStringRAMDataIndex + 1;
        end
        if (RAMIndex == 4 + WriteStringSize + WriteStringRAMSize) begin
            RAMData <= 0;
        end
        if (ramCode[15:12] == 4'b1100) begin
            RAMIndex <= ramDicPointer;
        end
        else begin
            RAMIndex <= RAMIndex + 1;
        end
    end

endmodule

