    output  reg [9:0]   data_out
);

reg [9:0] acc; // accumulator register
reg [2:0] count; // counter for 8 clock cycles
reg [7:0] buffer; // buffer for incoming data

assign ready_a = ~valid_b; // ready signal for data input

