module PulseEmitter
(
  input         Transmit_CLK,                //100M            
  input         RX_Gate,                    //Transmit Enable
  input   [7:0] EmitDelay,                  //7th bit for Transmit Enable, 6:0 for Delay                   
  input   [6:0] Emit_Width,                 //Emit pulse width
  output  reg   TXP,
  output  reg   TXN
);

  reg  [6:0]  Emit_Counter;
  reg  [6:0]  Delay_Counter;

  always @(posedge Transmit_CLK or negedge RX_Gate) begin
    if(~RX_Gate) begin
      Emit_Counter  <= 7'd0;
      Delay_Counter <= 8'd0;
      TXP           <= 1'b1;
      TXN           <= 1'b1;
    end else begin
      if(Delay_Counter < EmitDelay[6:0]) begin
        Delay_Counter <= Delay_Counter + 1'b1;
        TXP           <= 1'b1;
        TXN           <= 1'b1;
      end else begin
        if(EmitDelay[7]) begin // enable Emit
          if(Emit_Counter < Emit_Width) begin // Positive Pulse
            TXP <= 1'b1;
            TXN <= 1'b0;
            Emit_Counter <= Emit_Counter + 1'b1;
          end else if(Emit_Counter < {Emit_Width,1'b0}) begin // Negative Pulse
            TXP <= 1'b0;
            TXN <= 1'b1;
            Emit_Counter <= Emit_Counter + 1'b1;
          end else if(Emit_Counter < {Emit_Width,2'b0}+Emit_Width) begin // Return to Zero (RTZ)
            TXP <= 1'b0;
            TXN <= 1'b0;
            Emit_Counter <= Emit_Counter + 1'b1;
          end else begin // Reset counters and polarity
            Emit_Counter  <= 7'd0;
            Delay_Counter <= 8'd0;
            TXP           <= 1'b1;
            TXN           <= 1'b1;
          end
        end else begin // disable Emit
          TXP <= 1'b1;
          TXN <= 1'b1;
        end
      end
    end
  end

endmodule

module fifo (
    aclr,
    clock,
    data,
    rdreq,
    wrreq,
    empty,
    full,
    almost_full,
    q,
    usedw
);

    parameter WIDTH = 8;
    parameter DEPTH = 16;

    input aclr, clock, rdreq, wrreq;
    input [WIDTH-1:0] data;

    output empty, full, almost_full;
    output [WIDTH-1:0] q;
    output [3:0] usedw;

    reg [WIDTH-1:0] mem [DEPTH-1:0];
    reg [4:0] head, tail, count;
    wire [4:0] next_head, next_tail, next_count;

    assign empty = (count == 0);
    assign full = (count == DEPTH);
    assign almost_full = (count >= DEPTH*7/8);
    assign q = mem[tail];

    always @(posedge clock) begin
        if (aclr) begin
            head <= 0;
            tail <= 0;
            count <= 0;
        end else begin
            head <= next_head;
            tail <= next_tail;
            count <= next_count;
        end
    end

    always @* begin
        next_head = head;
        next_tail = tail;
        next_count = count;

        if (wrreq && !full) begin
            mem[head] <= data;
            next_head = head + 1;
            if (next_head == DEPTH) next_head = 0;
            next_count = count + 1;
        end

        if (rdreq && !empty) begin
            next_tail = tail + 1;
            if (next_tail == DEPTH) next_tail = 0;
            next_count = count - 1;
        end
    end

    assign usedw = count;

endmodule

