parameter p = 3; // number of product terms
parameter q = 2; // number of sum terms

wire [p-1:0] prod_terms;
wire [q-1:0] sum_terms;

// Define product terms as Boolean functions of input signals
assign prod_terms[0] = in[0] & in[1];
assign prod_terms[1] = in[2] & in[3];
assign prod_terms[2] = in[0] & in[2] & in[3];

// Define sum terms as Boolean functions of product terms
assign sum_terms[0] = prod_terms[0] | prod_terms[1];
assign sum_terms[1] = prod_terms[1] | prod_terms[2];

// Compute output signals as sum of product terms
assign out[0] = sum_terms[0] | sum_terms[1];
assign out[1] = sum_terms[0] & sum_terms[1];

