module fifo(
    input clk,
    input wr,
    input [7:0] din,
    output rd,
    output [7:0] dout
);

reg [7:0] mem [0:7]; // Memory for storing FIFO elements
reg wr_ptr = 0; // Write pointer
reg rd_ptr = 0; // Read pointer
reg empty = 1; // Flag indicating whether FIFO is empty
reg full = 0; // Flag indicating whether FIFO is full

// Write logic
always @(posedge clk) begin
    if (wr && !full) begin
        mem[wr_ptr] <= din;
        wr_ptr <= wr_ptr + 1;
        if (wr_ptr == 8) begin
            wr_ptr <= 0;
        end
        if (wr_ptr == rd_ptr) begin
            full <= 1;
        end
        empty <= 0;
    end
end

// Read logic
always @(posedge clk) begin
    if (rd && !empty) begin
        dout <= mem[rd_ptr];
        rd_ptr <= rd_ptr + 1;
        if (rd_ptr == 8) begin
            rd_ptr <= 0;
        end
        if (rd_ptr == wr_ptr) begin
            empty <= 1;
        end
        full <= 0;
    end
end

// Output logic
assign rd = !empty;
endmodule

