module top_module( 
    input [255:0] in1,
    input [255:0] in2,
    input [7:0] sel,
    input select_mux,
    input reset,
    output [255:0] out );

    wire [7:0] sel1;
    wire [7:0] sel2;
    wire [255:0] out1;
    wire [255:0] out2;

    priority_encoder_8to3 pe1(.in(sel), .out(sel1));
    priority_encoder_8to3 pe2(.in(sel), .out(sel2));

    decoder_3to8 dec1(.in(sel1), .out(out1));
    decoder_3to8 dec2(.in(sel2), .out(out2));

    mux_256to1 mux1(.in(in1), .sel(out1), .out(out1_mux));
    mux_256to1 mux2(.in(in2), .sel(out2), .out(out2_mux));

    or_gate or_gate1(.in1(out1_mux), .in2(out2_mux), .out(out));

    always @(posedge reset) begin
        out <= 0;
    end

    always @(posedge select_mux) begin
        if (select_mux == 0) begin
            out <= out1_mux;
        end else begin
            out <= out2_mux;
        end
    end

endmodule

