module instruction_fetch(
    input clk,
    input nrst,
    input [UPARC_ADDR_WIDTH-1:0] i_pc,
    input [UPARC_ADDR_WIDTH-1:0] i_jump_addr,
    input i_jump_valid,
    input i_except_valid,
    input [UPARC_ADDR_WIDTH-1:0] i_except_haddr,
    input i_exec_stall,
    input i_mem_stall,
    input i_wait_stall,
    input i_nullify,
    input [UPARC_INSTR_WIDTH-1:0] i_instr_dat,
    input i_busy,
    input i_err_align,
    input i_err_bus,
    output reg o_fetch_stall,
    output reg o_bus_error,
    output reg o_addr_error,
    output reg [UPARC_ADDR_WIDTH-1:0] o_addr,
    output reg o_rd_cmd,
    output reg [UPARC_INSTR_WIDTH-1:0] o_instr,
    output reg [UPARC_ADDR_WIDTH-1:0] o_pc
);

localparam [UPARC_INSTR_WIDTH-1:0] NOP = 32'h0000_0000;

reg err_bus_r;
reg err_align_r;
wire [UPARC_ADDR_WIDTH-1:0] new_pc = !i_except_valid ? (!i_jump_valid ? i_pc : i_jump_addr) : i_except_haddr;

wire core_stall = i_exec_stall || i_mem_stall || o_fetch_stall || i_wait_stall;

assign o_fetch_stall = i_busy;
assign o_bus_error = i_err_bus | err_bus_r;
assign o_addr_error = i_err_align | err_align_r;
assign o_instr = (!i_jump_valid && !i_nullify && !i_except_valid ? i_instr_dat : NOP);

always @(posedge clk or negedge nrst) begin
    if (!nrst) begin
        o_addr <= {UPARC_ADDR_WIDTH{1'b0}};
        o_pc <= {UPARC_ADDR_WIDTH{1'b0}};
        o_rd_cmd <= 1'b0;
        err_align_r <= 1'b0;
        err_bus_r <= 1'b0;
    end else begin
        o_rd_cmd <= 1'b0;
        err_bus_r <= err_bus_r | i_err_bus;
        err_align_r <= err_align_r | i_err_align;
        if (!core_stall) begin
            err_align_r <= 1'b0;
            err_bus_r <= 1'b0;
            o_addr <= new_pc;
            o_pc <= new_pc;
            o_rd_cmd <= !i_nullify ? 1'b1 : 1'b0;
        end
    end
end

endmodule

module T3MAPS (
	input SR_IN,
	input DAC_LOAD,
	input STROBE_LOAD, 
	input GLOBAL_CFG_CLK, 
	input PIXEL_CLK,
	output PIXEL_DATA_OUT,
	output GLOBAL_CFG_OUT
); 

reg [63:0] pixel_columns[17:0]; //The 18 64 bit pixel columns
//The global configuration register. 175:144 is pixel cfg.
//149:144 is the column addr
//143:0 is the dac config
reg [175:0] global_cfg; 
reg [31:0] pixel_cfg;
reg [143:0]dac_cfg;

wire [5:0] current_column;
assign current_column = pixel_cfg[5:0];

assign GLOBAL_CFG_OUT = global_cfg[0];
assign PIXEL_DATA_OUT = pixel_columns[current_column][0];

//global config register shifter and shadow register loader
always @ (posedge GLOBAL_CFG_CLK, posedge DAC_LOAD, posedge STROBE_LOAD) 
begin
	global_cfg = global_cfg >> 1;
	global_cfg[175] = SR_IN;
	if (DAC_LOAD) begin
		dac_cfg = global_cfg[143:0];	
	end
	if (STROBE_LOAD) begin
		pixel_cfg = global_cfg[175:144];
	end
end 

//The pixel register shifter, for the selected column
always @ (posedge PIXEL_CLK) 
begin
	pixel_columns[current_column] = pixel_columns[current_column] >> 1;
end

endmodule

module top_module (
    input clk,
    input reset,           // Synchronous active-high reset
    input [3:0] d,
    input enable,
    output [3:0] q,
    output [3:0] sum
);

    wire [3:0] shift_q;
    wire [3:0] adder_sum;

    shift_register shift_reg(
        .clk(clk),
        .reset(reset),
        .d(d),
        .enable(enable),
        .q(shift_q)
    );

    adder sum_calc(
        .a(shift_q),
        .b(4'b0),
        .sum(adder_sum)
    );

    assign q = shift_q;
    assign sum = adder_sum;

endmodule


module shift_register (
    input clk,
    input reset,            // Asynchronous active-low reset
    input [3:0] d,
    input enable,
    output [3:0] q
);

    reg [3:0] q_reg;

    always @(negedge clk) begin
        if (reset == 0) begin
            q_reg <= 4'b0;
        end else if (enable) begin
            q_reg <= {q_reg[2:0], d[0]};
        end
    end

    assign q = q_reg;

endmodule


module adder (
    input [3:0] a,
    input [3:0] b,
    output [3:0] sum
);

    assign sum = a + b;

endmodule

module d_ff_async_rst_set(clk, rst, set, d, q, qn);
input clk, rst, set, d;
output q, qn;
reg q, qn;

always @(posedge clk or posedge rst or posedge set) begin
    if (rst) begin
        q <= 0;
        qn <= 1;
    end
    else if (set) begin
        q <= 1;
        qn <= 0;
    end
    else begin
        q <= d;
        qn <= ~d;
    end
end

endmodule

module population_count_mux(
    input [254:0] in,
    output reg [3:0] out,
    input [2:0] sel,
    output reg [3:0] data0,
    output reg [3:0] data1,
    output reg [3:0] data2,
    output reg [3:0] data3,
    output reg [3:0] data4,
    output reg [3:0] data5);

    // 6-to-1 Multiplexer
    wire [3:0] mux_out0, mux_out1, mux_out2;
    wire [3:0] mux_out3, mux_out4, mux_out5;
    assign mux_out0 = in[3:0];
    assign mux_out1 = in[7:4];
    assign mux_out2 = in[11:8];
    assign mux_out3 = in[15:12];
    assign mux_out4 = in[19:16];
    assign mux_out5 = in[23:20];
    always @*
    begin
        case(sel)
            3'b000: out = data0;
            3'b001: out = data1;
            3'b010: out = data2;
            3'b011: out = data3;
            3'b100: out = data4;
            3'b101: out = data5;
            default: out = 4'b0000;
        endcase
    end

    // Population Count Circuit
    wire [2:0] count0, count1, count2;
    binary_tree_adder bta0(mux_out0, count0);
    binary_tree_adder bta1(mux_out1, count1);
    binary_tree_adder bta2(mux_out2, count2);
    binary_tree_adder bta3(mux_out3, data3);
    binary_tree_adder bta4(mux_out4, data4);
    binary_tree_adder bta5(mux_out5, data5);

    always @*
    begin
        case(sel)
            3'b000: out = count0;
            3'b001: out = count1;
            3'b010: out = count2;
            default: out = 3'b000;
        endcase
    end

endmodule

module binary_tree_adder(
    input [3:0] in,
    output reg [2:0] out);

    always @*
    begin
        out[0] = in[0] ^ in[1];
        out[1] = in[2] ^ in[3];
        out[2] = out[0] ^ out[1];
    end

endmodule

module async_reset_release (
  input rst,
  input clk,
  input enable,
  output reg rst_release
);

parameter delay_count = 10;

reg [7:0] delay_counter;

always @(posedge clk) begin
  if (rst) begin
    rst_release <= 0;
    delay_counter <= 0;
  end else if (enable) begin
    if (delay_counter < delay_count) begin
      delay_counter <= delay_counter + 1;
    end else begin
      rst_release <= 1;
    end
  end
end

endmodule

