module top_module(
    input clk,
    input reset,
    input [99:0] data,
    input [1:0] ena,
    input load,
    input A, B, SEL,
    output reg [99:0] q);

    reg [99:0] reg_data;
    wire [99:0] shifted_data;

    // 2:1 Multiplexer
    assign shifted_data = SEL ? reg_data << ena[1:0] : reg_data >> ena[1:0];
    assign q = SEL ? B : A;

    // Barrel Shifter
    always @(posedge clk) begin
        if (reset) begin
            reg_data <= 0;
        end else if (load) begin
            reg_data <= data;
        end else if (ena != 2'b00 && ena != 2'b11) begin
            reg_data <= shifted_data;
        end
    end

endmodule

module RegisterAdd__parameterized3
   #(parameter INIT_VALUE = 1'b0)
   (Q,
    \Q_reg[0]_0 ,
    D,
    CLK,
    AR);
  output [3:0]Q;
  input [0:0]\Q_reg[0]_0 ;
  input [2:0]D;
  input CLK;
  input [0:0]AR;

  wire [0:0]AR;
  wire CLK;
  wire [2:0]D;
  wire [3:0]Q;
  wire [0:0]\Q_reg[0]_0 ;

  reg [3:0] stored_values = INIT_VALUE; // initialize flip-flops with parameter value

  always @(posedge CLK or negedge \Q_reg[0]_0 or negedge AR) begin
    if (\Q_reg[0]_0 == 0) begin // asynchronous reset
      stored_values <= INIT_VALUE;
    end else if (AR == 0) begin // asynchronous reset
      Q <= 4'b0;
    end else begin // add stored values and output result
      stored_values <= {stored_values[2:0], D}; // shift in new value
      Q <= stored_values + D;
    end
  end
endmodule

module led_controller(
  input clk,
  input rst,
  input [31:0] led_data_in,
  input [31:0] led_mask_in,
  output reg [31:0] led_data_out,
  output reg led_data_changed,
  output reg led_data_masked
);

  always @(posedge clk) begin
    if (rst) begin
      led_data_out <= 32'h00000000;
      led_data_changed <= 1'b0;
      led_data_masked <= 1'b0;
    end else begin
      if (led_mask_in != 32'h00000000) begin
        led_data_out <= (led_data_out & ~led_mask_in) | (led_data_in & led_mask_in);
        led_data_masked <= 1'b1;
      end else if (led_data_in != led_data_out) begin
        led_data_out <= led_data_in;
        led_data_changed <= 1'b1;
      end
    end
  end

endmodule

module sm_alu
(
    input  [31:0] srcA,
    input  [31:0] srcB,
    input  [ 3:0] oper,
    input  [ 4:0] shift,
    output        sign,
    output reg [31:0] result
);
    always @ (*) begin
        case (oper)
            default     : result = srcA + srcB;
            4'h0        : result = srcA + srcB;
            4'h1        : result = srcA | srcB;
            4'h2        : result = srcA & srcB;
            4'h3        : result = (srcB << 16);
            4'h4        : result = srcB >> shift; 
            4'h6        : result = srcB >> srcA;
            4'h7        : result = (srcA < srcB) ? 1 : 0;
            4'h9        : result = srcA - srcB;
            4'hA        : result = ~(srcA | srcB);
            4'hB        : result = (srcB >= 0) ? 1 : 0;
        endcase
    end

    assign sign = (result == 0);
endmodule

