module fir_filter (
    input  [19:0] a_i,
    input  [17:0] b_i,
    input  [ 3:0] acc_fir_i,
    output [37:0] z_o,
    output [17:0] dly_b_o,

    input         clock_i,
    input         reset_i,

    input  [2:0]  feedback_i,
    input         load_acc_i,
    input         unsigned_a_i,
    input         unsigned_b_i,

    input  [2:0]  output_select_i,
    input         saturate_enable_i,
    input  [5:0]  shift_right_i,
    input         round_i,
    input         subtract_i,
    input         register_inputs_i
);

    parameter [19:0] COEFF_0 = 20'd0;
    parameter [19:0] COEFF_1 = 20'd0;
    parameter [19:0] COEFF_2 = 20'd0;
    parameter [19:0] COEFF_3 = 20'd0;

    QL_DSP2 # (
        .COEFF_0            (COEFF_0),
        .COEFF_1            (COEFF_1),
        .COEFF_2            (COEFF_2),
        .COEFF_3            (COEFF_3)
    ) fir_dsp (
        .a                  (a_i),
        .b                  (b_i),
        .acc_fir            (acc_fir_i),
        .z                  (z_o),
        .dly_b              (dly_b_o),

        .clk                (clock_i),
        .reset              (reset_i),

        .feedback           (feedback_i),
        .load_acc           (load_acc_i),
        .unsigned_a         (unsigned_a_i),
        .unsigned_b         (unsigned_b_i),

        .f_mode             (1'b0), // No fracturation
        .output_select      (output_select_i),
        .saturate_enable    (saturate_enable_i),
        .shift_right        (shift_right_i),
        .round              (round_i),
        .subtract           (subtract_i),
        .register_inputs    (register_inputs_i)
    );

    reg [19:0] a_reg [0:2];
    reg [17:0] b_reg [0:2];
    reg [3:0] acc_reg;
    wire [37:0] z_wire;
    wire [17:0] dly_b_wire;

    always @(posedge clock_i) begin
        if (reset_i) begin
            acc_reg <= 4'd0;
            a_reg[0] <= 20'd0;
            a_reg[1] <= 20'd0;
            a_reg[2] <= 20'd0;
            b_reg[0] <= 18'd0;
            b_reg[1] <= 18'd0;
            b_reg[2] <= 18'd0;
        end else begin
            if (register_inputs_i) begin
                a_reg[0] <= a_i;
                a_reg[1] <= a_reg[0];
                a_reg[2] <= a_reg[1];
                b_reg[0] <= b_i;
                b_reg[1] <= b_reg[0];
                b_reg[2] <= b_reg[1];
            end else begin
                a_reg[0] <= a_reg[1];
                a_reg[1] <= a_reg[2];
                a_reg[2] <= a_i;
                b_reg[0] <= b_reg[1];
                b_reg[1] <= b_reg[2];
                b_reg[2] <= b_i;
            end
            if (load_acc_i) begin
                acc_reg <= acc_fir_i;
            end else begin
                acc_reg <= acc_reg + 1;
            end
        end
    end

    assign z_wire = a_reg[0] * b_reg[0] + a_reg[1] * b_reg[1] + a_reg[2] * b_reg[2];
    assign dly_b_wire = b_reg[2];

    QL_DSP2 # (
        .COEFF_0            (COEFF_0),
        .COEFF_1            (COEFF_1),
        .COEFF_2            (COEFF_2),
        .COEFF_3            (COEFF_3)
    ) fir_dsp_delay (
        .a                  (z_wire),
        .b                  (dly_b_wire),
        .acc_fir            (acc_reg),
        .z                  (z_o),
        .dly_b              (dly_b_o),

        .clk                (clock_i),
        .reset              (reset_i),

        .feedback           (feedback_i),
        .load_acc           (load_acc_i),
        .unsigned_a         (unsigned_a_i),
        .unsigned_b         (unsigned_b_i),

        .f_mode             (1'b0), // No fracturation
        .output_select      (output_select_i),
        .saturate_enable    (saturate_enable_i),
        .shift_right        (shift_right_i),
        .round              (round_i),
        .subtract           (subtract_i),
        .register_inputs    (register_inputs_i)
    );

endmodule

module ocxo_clk_pll(clk_in1, clk_out1, resetn, locked);
  input clk_in1;
  output clk_out1;
  input resetn;
  output locked;

  reg locked_reg, clk_out_reg;
  reg [22:0] counter_reg;
  parameter COUNT_MAX = 500000;

  always @(posedge clk_in1 or negedge resetn) begin
    if (~resetn) begin
      locked_reg <= 1'b1;
      clk_out_reg <= 1'b0;
      counter_reg <= 0;
    end
    else begin
      if (counter_reg == COUNT_MAX) begin
        counter_reg <= 0;
        clk_out_reg <= ~clk_out_reg;
      end
      else begin
        counter_reg <= counter_reg + 1;
      end

      if (clk_out_reg == 1'b1) begin
