   wire                sw, sh, sb, mtc0, eret;
   parse_instr parser(instr, ALL_SUPPORT_INSTR);

   // Check if sw, sh, or sb instruction
   assign sw = parser.opcode == 32'h2b;
   assign sh = parser.opcode == 32'h29;
   assign sb = parser.opcode == 32'h28;

   // Set BEExtOp based on instruction type
   assign BEExtOp = (sw) ? 2'b00 :
                    (sh) ? 2'b01 :
                    (sb) ? 2'b10 :
                    2'b11;

   // Set CP0_WE based on instruction type
   assign CP0_WE = parser.mt;

   // Set isERET_m based on instruction type
   assign isERET_m = parser.opcode == 32'h42000018;

endmodule

