module crc (
  input [data_width-1:0] data_in,
  input [crc_width-1:0] crc_in,
  input reset,
  output [data_width+crc_width-1:0] data_out,
  output [crc_width-1:0] crc_out,
  output error
);

parameter data_width = 8; // width of input and output data (in bits)
parameter crc_width = 4; // width of CRC value (in bits)
parameter polynomial = 4'b10011; // generator polynomial

reg [data_width+crc_width-1:0] shift_reg;
reg [crc_width-1:0] crc_reg;
wire [data_width+crc_width-1:0] data_out;
wire [crc_width-1:0] crc_out;
wire error;

assign data_out = {data_in, crc_reg};
assign crc_out = crc_reg;
assign error = (crc_out == crc_in) ? 1'b0 : 1'b1;

always @(posedge reset or posedge data_in) begin
  if (reset) begin
    shift_reg <= {data_in, {crc_width{1'b0}}};
    crc_reg <= {crc_width{1'b0}};
  end else begin
    shift_reg <= {shift_reg[data_width+crc_width-2:1], data_in};
    crc_reg <= crc_reg ^ shift_reg[data_width+crc_width-1] ? polynomial : 0;
    crc_reg <= {crc_reg[crc_width-2:0], shift_reg[data_width+crc_width-1]} ^ crc_reg[crc_width-1] ? polynomial : 0;
  end
end

endmodule

