            if (opcode == 3'b101) begin
                data_out <= data_mem[addr_calc];
            end else if (opcode == 3'b110) begin
                data_mem[addr_calc] <= data_in;
            end
        end
    end

    // Program counter update
    always @ (posedge clk) begin
        if (reset) begin
            pc_out <= 0;
        end else begin
            if (opcode == 3'b111) begin
                pc_out <= addr_calc;
            end else begin
                pc_out <= pc + 1;
            end
        end
    end

endmodule

