module ECC (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 8; // number of input bits
parameter m = 12; // number of output bits (n+p)
parameter p = 4; // number of parity bits

reg [n+p-1:0] codeword;
wire [p-1:0] parity;

// Generate parity bits
genvar i, j;
generate
  for (i = 0; i < p; i = i + 1) begin
    assign parity[i] = codeword[{2**i-1} +: 2**i] ^ codeword[{2**i-1} + 1 +: 2**i-1];
  end
endgenerate

// Append parity bits to input bits
always @* begin
  for (i = 0; i < n; i = i + 1) begin
    codeword[i] = in[i];
  end
  for (j = 0; j < p; j = j + 1) begin
    codeword[n+j] = parity[j];
  end
end

// Output codeword
assign out = codeword;

endmodule

