module KeyPadInterpreter(Clock, ResetButton, KeyRead, RowDataIn, KeyReady, DataOut, ColDataOut, PressCount);

input Clock, ResetButton, KeyRead;
input [3:0] RowDataIn;
output KeyReady;
output [3:0] DataOut, ColDataOut, PressCount;

reg [3:0] colData;
reg [3:0] rowData;
reg [3:0] prevData;
reg [3:0] pressCount;
reg keyReady;

// Initialize all outputs to 0
assign KeyReady = 0;
assign DataOut = 0;
assign ColDataOut = 0;
assign PressCount = 0;

always @(posedge Clock) begin
    // Reset the module if ResetButton is high
    if(ResetButton) begin
        colData <= 4'b0000;
        rowData <= 4'b0000;
        prevData <= 4'b0000;
        pressCount <= 4'b0000;
        keyReady <= 0;
    end
    else begin
        // Update rowData based on RowDataIn
        rowData <= RowDataIn;

        // Read in column data
        if(KeyRead) begin
            colData <= {1'b0, ~prevData[2:0]};
            prevData <= colData;
        end

        // Determine which key is pressed
        case({rowData, colData})
            8'b11101110: begin
                DataOut <= 4'b0001;
                ColDataOut <= 4'b1110;
            end
            8'b11011110: begin
                DataOut <= 4'b0010;
                ColDataOut <= 4'b1110;
            end
            8'b10111110: begin
                DataOut <= 4'b0100;
                ColDataOut <= 4'b1110;
            end
            8'b01111110: begin
                DataOut <= 4'b1000;
                ColDataOut <= 4'b1110;
            end
            8'b11101101: begin
                DataOut <= 4'b0001;
                ColDataOut <= 4'b1101;
            end
            8'b11011101: begin
                DataOut <= 4'b0010;
                ColDataOut <= 4'b1101;
            end
            8'b10111101: begin
                DataOut <= 4'b0100;
                ColDataOut <= 4'b1101;
            end
            8'b01111101: begin
                DataOut <= 4'b1000;
                ColDataOut <= 4'b1101;
            end
            8'b11101011: begin
                DataOut <= 4'b0001;
                ColDataOut <= 4'b1011;
            end
            8'b11011011: begin
                DataOut <= 4'b0010;
                ColDataOut <= 4'b1011;
            end
            8'b10111011: begin
                DataOut <= 4'b0100;
                ColDataOut <= 4'b1011;
            end
            8'b01111011: begin
                DataOut <= 4'b1000;
                ColDataOut <= 4'b1011;
            end
            8'b11100111: begin
                DataOut <= 4'b0001;
                ColDataOut <= 4'b0111;
            end
            8'b11010111: begin
                DataOut <= 4'b0010;
                ColDataOut <= 4'b0111;
            end
            8'b10110111: begin
                DataOut <= 4'b0100;
                ColDataOut <= 4'b0111;
            end
            8'b01110111: begin
                DataOut <= 4'b1000;
                ColDataOut <= 4'b0111;
            end
            default: begin
                DataOut <= 4'b0000;
                ColDataOut <= 4'b0000;
            end
        endcase

        // Update press count and keyReady
        if(KeyRead && {rowData, colData} == prevData) begin
            pressCount <= pressCount + 1;
            keyReady <= 1;
        end
        else begin
            pressCount <= 4'b0000;
            keyReady <= 0;
        end
    end
end

endmodule

module reverse_bits(
    input [31:0] in,
    output [31:0] out
);

reg [7:0] byte0, byte1, byte2, byte3;
reg [31:0] temp;

// Split input into four bytes
assign byte0 = in[7:0];
assign byte1 = in[15:8];
assign byte2 = in[23:16];
assign byte3 = in[31:24];

// Reverse each byte using shift registers and muxes
always @* begin
    temp = {byte0, byte1, byte2, byte3};
    byte0 = temp[7:0];
    byte1 = temp[15:8];
    byte2 = temp[23:16];
    byte3 = temp[31:24];
end

// Combine reversed bytes to form output vector
assign out = {byte3, byte2, byte1, byte0};

endmodule

