module add_sub_module(
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] sum
);

    wire [15:0] a_low, b_low, sum_low;
    wire carry;

    // Split the inputs and outputs into high and low bits
    assign a_low = a[15:0];
    assign b_low = b[15:0];
    assign sum_low = sum[15:0];

    // Invert the b input if sub is 1
    wire [31:0] b_inverted;
    assign b_inverted = (sub) ? ~b : b;

    // Connect the XOR gate to the b input and sub input
    wire [31:0] xor_input;
    assign xor_input = {16'b0, b_inverted};
    assign xor_input[31] = sub;

    // Instantiate the 16-bit ripple carry adder module
    ripple_carry_adder adder(
        .a(a_low),
        .b(xor_input[15:0]),
        .carry_in(sub),
        .sum(sum_low),
        .carry_out(carry)
    );

    // Connect the carry output of the 16-bit adder to the carry input of the high bits adder
    wire [15:0] carry_in_high;
    assign carry_in_high = (carry) ? 16'h1 : 16'h0;

    // Instantiate the 16-bit ripple carry adder module for the high bits
    ripple_carry_adder adder_high(
        .a(a[31:16]),
        .b(xor_input[31:16]),
        .carry_in(carry_in_high),
        .sum(sum[31:16]),
        .carry_out()
    );

endmodule

