    input clk,
    input reset,
    input up_down,
    input load,
    input [3:0] count_in,
    output reg [3:0] count_out
);

always @(posedge clk) begin
    if (reset) begin
        count_out <= 4'b0;
    end else if (load) begin
        count_out <= count_in;
    end else if (up_down) begin
        count_out <= count_out + 4'b1;
    end else begin
        count_out <= count_out - 4'b1;
    end
end

