module glitch_free_clock_mux (
  input [n-1:0] clk,
  output reg clk_out
);

parameter n = 4; // number of input clock signals

reg [n-1:0] sync_clk; // synchronized input clock signals
reg [n-1:0] next_sync_clk; // next synchronized input clock signals
reg [n-1:0] select; // clock signal selection

always @(posedge clk[0] or posedge clk[1] or posedge clk[2] or posedge clk[3]) begin
  // synchronize input clock signals
  sync_clk <= clk;
  // select input clock signal
  select <= {sync_clk[n-1], sync_clk[n-2], sync_clk[n-3], sync_clk[n-4]};
end

always @(posedge select or posedge clk_out) begin
  // synchronize selected clock signal
  next_sync_clk <= {select[n-2:0], select[n-1]};
  // generate glitch-free output clock signal
  clk_out <= next_sync_clk[n-1] & ~sync_clk[n-1] | ~next_sync_clk[n-1] & sync_clk[n-1];
end

endmodule

module traffic_light_controller (
