module mux_4to1 (
    out,
    in0,
    in1,
    in2,
    in3,
    sel
);

    // Module ports
    output out;
    input  in0, in1, in2, in3;
    input  [1:0] sel;

    // Local signals
    wire sel0, sel1, not_sel0, not_sel1;

    // Invert the select signals
    not not_sel0 (not_sel0, sel[0]);
    not not_sel1 (not_sel1, sel[1]);

    // AND the inverted select signals with the input signals
    and sel0 (sel0, in0, not_sel0, not_sel1);
    and sel1 (sel1, in1, sel[0], not_sel1);
    and sel2 (sel2, in2, not_sel0, sel[1]);
    and sel3 (sel3, in3, sel[0], sel[1]);

    // OR the ANDed signals to get the output
    or out_or (out, sel0, sel1, sel2, sel3);

endmodule

module freq_synth (
  input ref_clk,
  input [n-1:0] ctrl_word,
  output reg synth_clk
);

parameter n = 8; // number of bits in the control word
parameter f_ref = 50e6; // frequency of the reference clock
parameter f_out = 1e6; // desired output frequency

reg [31:0] phase_acc; // phase accumulator
reg [31:0] phase_inc; // phase increment
reg [15:0] dac_out; // digital-to-analog converter output
reg [15:0] lp_filter_out; // low-pass filter output

// calculate phase increment based on control word and reference frequency
always @(*) begin
  phase_inc = ((ctrl_word << 16) / (1 << n)) * f_ref;
end

// update phase accumulator on each rising edge of reference clock
always @(posedge ref_clk) begin
  phase_acc <= phase_acc + phase_inc;
end

// generate DAC output based on phase accumulator
always @(*) begin
  dac_out = $signed(phase_acc[31:16]);
end

// implement low-pass filter
always @(posedge ref_clk) begin
  lp_filter_out <= (lp_filter_out + dac_out) / 2;
end

// generate synthesized frequency signal
always @(posedge ref_clk) begin
  if (lp_filter_out >= 32768) begin
    synth_clk <= 1;
  end else begin
    synth_clk <= 0;
  end
end

endmodule

module top_module( 
    input [99:0] a, b,
    output [99:0] cout,
    output [99:0] sum );

    wire [99:0] c;
    wire [99:0] p;
    wire [99:0] g;

    assign p[0] = a[0] ^ b[0];
    assign g[0] = a[0] & b[0];

    genvar i;
    generate
        for (i = 1; i < 100; i = i + 1) begin: adder
            assign p[i] = a[i] ^ b[i] ^ c[i-1];
            assign g[i] = (a[i] & b[i]) | (a[i] & c[i-1]) | (b[i] & c[i-1]);
            carry_lookahead_adder cla(.p(p[i]), .g(g[i]), .c(c[i]), .cout(cout[i-1]), .a(c[i-1]), .b(p[i]), .cin(g[i]));
        end
    endgenerate

    assign sum = p;
    assign cout[0] = g[0];
    assign cout[99] = c[99];

endmodule

module carry_lookahead_adder(
    input p, g, cin, a, b,
    output c, cout);

    assign c = p ^ cin;
    assign cout = g | (p & cin);
    assign a = b ^ c;

endmodule

