module vending_machine(
  input clk,
  input rst,
  input selA,
  input selB,
  input selC,
  input coin_in,
  output dispense,
  output ready,
  output out_of_stock
);

  reg [1:0] item_count; // counter for each item
  reg [4:0] coin_count; // counter for coins inserted
  reg [4:0] item_price; // price of each item
  reg [2:0] item_sel;   // selection of each item
  reg [1:0] change;     // change to be returned
  reg [1:0] coin_return; // coin to be returned
  reg item_dispensed;   // flag indicating if item has been dispensed

  // set initial values
  initial begin
    item_count = 3'b111; // all items in stock
    coin_count = 5'b0;   // no coins inserted
    item_price = 5'b01100; // price of each item is 25 cents
    item_sel = 3'b000;   // no item selected
    change = 2'b00;      // no change to be returned
    coin_return = 2'b00; // no coins to be returned
    item_dispensed = 1'b0; // no item has been dispensed
  end

  // state machine
  always @(posedge clk) begin
    if (rst) begin // reset
      item_count <= 3'b111;
      coin_count <= 5'b0;
      item_sel <= 3'b000;
      change <= 2'b00;
      coin_return <= 2'b00;
      item_dispensed <= 1'b0;
    end else begin
      if (item_count == 3'b000) begin // out of stock
        out_of_stock <= 1'b1;
        ready <= 1'b0;
        item_dispensed <= 1'b0;
        coin_return <= coin_count[1:0]; // return coins inserted
        coin_count <= 5'b0;
      end else if (coin_count >= item_price[item_sel]) begin // item selected and enough coins inserted
        out_of_stock <= 1'b0;
        ready <= 1'b0;
        item_count[item_sel] <= item_count[item_sel] - 1; // decrement item count
        change <= coin_count[item_sel+1:2] - item_price[item_sel]; // calculate change
        coin_return <= coin_count[1:item_sel] - item_price[0:item_sel-1]; // calculate coins to be returned
        item_dispensed <= 1'b1; // item dispensed
        coin_count <= 5'b0; // reset coin count
      end else begin // item not selected or not enough coins inserted
        out_of_stock <= 1'b0;
        ready <= 1'b1;
        item_dispensed <= 1'b0;
        coin_return <= coin_count[1:0]; // return coins inserted
      end
    end
  end

  // update item selection and coin count
  always @(selA or selB or selC or coin_in) begin
    if (selA) begin
      item_sel <= 3'b001;
    end else if (selB) begin
      item_sel <= 3'b010;
    end else if (selC) begin
      item_sel <= 3'b011;
    end
    coin_count <= coin_count + coin_in;
  end

  // output signals
  assign dispense = item_dispensed;

endmodule

module clock_generator(
  input clk_in,
  input resetn,
  output reg clk_out1,
  output reg clk_out2,
  output reg clk_out3,
  output reg clk_out4,
  output reg locked
);

  reg [1:0] counter1 = 2'b0;
  reg [2:0] counter2 = 3'b0;
  reg [3:0] counter3 = 4'b0;
  reg [4:0] counter4 = 5'b0;
  reg [3:0] stable_counter = 4'b0;

  always @(posedge clk_in or negedge resetn) begin
    if (!resetn) begin
      counter1 <= 2'b0;
      counter2 <= 3'b0;
      counter3 <= 4'b0;
      counter4 <= 5'b0;
      stable_counter <= 4'b0;
      clk_out1 <= 1'b0;
      clk_out2 <= 1'b0;
      clk_out3 <= 1'b0;
      clk_out4 <= 1'b0;
      locked <= 1'b0;
    end else begin
      counter1 <= counter1 + 1;
      counter2 <= counter2 + 1;
      counter3 <= counter3 + 1;
      counter4 <= counter4 + 1;
      stable_counter <= stable_counter + 1;
      if (counter1 == 2'b0) begin
        clk_out1 <= ~clk_out1;
      end
      if (counter2 == 3'b0) begin
        clk_out2 <= ~clk_out2;
      end
      if (counter3 == 4'b0) begin
        clk_out3 <= ~clk_out3;
      end
      if (counter4 == 5'b0) begin
        clk_out4 <= ~clk_out4;
      end
      if (stable_counter == 4'b10) begin
        locked <= 1'b1;
      end
    end
  end

endmodule

module BRAM2Load(
