    input wire [DATA_WIDTH-1:0] DIB,
    output wire [DATA_WIDTH-1:0] DOB
);

   parameter FILENAME = "";
   parameter PIPELINED = 0;
   parameter ADDR_WIDTH = 1;
   parameter DATA_WIDTH = 1;
   parameter MEMSIZE = 1;
   parameter BINARY = 0;

