   reg [DATA_WIDTH-1:0] DOB_R2;
   reg [DATA_WIDTH-1:0] DIA_R;
   reg [DATA_WIDTH-1:0] DIB_R;

   integer i;
   initial begin
      if (BINARY)
        $readmemb(FILENAME, RAM, 0, MEMSIZE-1);
      else
        $readmemh(FILENAME, RAM, 0, MEMSIZE-1);
   end

   always @(posedge CLKA) begin
      if (ENA) begin
         DOA_R <= RAM[ADDRA];
