      DOB_R2 <= DOB_R;
   end

   assign DOA = (PIPELINED) ? DOA_R2 : DOA_R;
   assign DOB = (PIPELINED) ? DOB_R2 : DOB_R;

   always @(posedge CLKA) begin
      if (WEA && ENA) begin
         RAM[ADDRA] <= DIA;
