module adder4 (
    A,
    B,
    Cin,
    S,
    Cout
);

    input [3:0] A;
    input [3:0] B;
    input Cin;
    output [3:0] S;
    output Cout;

    wire [3:0] c;
    wire [3:0] s;

    // First bit
    full_adder FA0 (.A(A[0]), .B(B[0]), .Cin(Cin), .S(s[0]), .Cout(c[0]));

