  voltage_resistive <= sensor * R / (R + 1e3);
end

// Capacitive sensor implementation
reg [7:0] charge_time;
always @ (posedge sensor) begin
  if (type) begin // capacitive sensor
    charge_time <= 0;
    while (sensor) begin
      charge_time <= charge_time + 1;
    end
  end
end

// Touch detection
always @ (posedge sensor) begin
  if (type) begin // capacitive sensor
    if (charge_time > threshold) begin
      touched <= 1;
    end else begin
      touched <= 0;
    end
  end else begin // resistive sensor
    if (voltage_resistive > threshold) begin
      touched <= 1;
    end else begin
      touched <= 0;
    end
  end
end

