module top_module (
    input clk,
    input reset,   // Synchronous active-high reset
    input [254:0] in, //input for the '1' counter
    output [3:1] ena, //enable signal for BCD counter
    output reg [15:0] BCD_q, //output from BCD counter
    output reg [7:0] count_out, //output from '1' counter
    output reg [15:0] final_out //final output from functional module
);

// BCD Counter State Machine
reg [3:0] state;
always @(posedge clk) begin
    if (reset) begin
        state <= 4'b0000;
        BCD_q <= 16'd0;
        ena <= 3'b000;
    end else begin
        case (state)
            4'b0000: begin
                state <= 4'b0001;
                ena <= 3'b100;
            end
            4'b0001: begin
                state <= 4'b0010;
                ena <= 3'b010;
            end
            4'b0010: begin
                state <= 4'b0011;
                ena <= 3'b001;
            end
            4'b0011: begin
                state <= 4'b0000;
                ena <= 3'b000;
                if (BCD_q == 16'd9999) begin
                    BCD_q <= 16'd0;
                end else begin
                    BCD_q <= BCD_q + 16'd1;
                end
            end
        endcase
    end
end

// '1' Counter using Parallel Prefix Adder
wire [7:0] count_chunk [31:0];
genvar i;
generate
    for (i = 0; i < 32; i = i + 1) begin : chunk_gen
        assign count_chunk[i] = in[(i*8)+7:(i*8)] == 8'h00 ? 8'd0 : $countones(in[(i*8)+7:(i*8)]);
    end
endgenerate

wire [7:0] count_prefix [5:0];
assign count_prefix[0] = count_chunk[0];
assign count_prefix[1] = count_chunk[1] + count_chunk[0];
assign count_prefix[2] = count_chunk[2] + count_chunk[1] + count_chunk[0];
assign count_prefix[3] = count_chunk[3] + count_chunk[2] + count_chunk[1] + count_chunk[0];
assign count_prefix[4] = count_chunk[4] + count_chunk[3] + count_chunk[2] + count_chunk[1] + count_chunk[0];
assign count_prefix[5] = count_chunk[5] + count_chunk[4] + count_chunk[3] + count_chunk[2] + count_chunk[1] + count_chunk[0];

assign count_out = count_prefix[5];

// Functional Module
always @(posedge clk) begin
    final_out <= BCD_q + count_out;
end

endmodule

