module fifo_64in_out(rst, wr_clk, rd_clk, din, wr_en, rd_en, dout, full, empty, valid, rd_data_count);

  parameter DEPTH = 64; // Depth of the FIFO
  parameter WIDTH = 64; // Width of the data

  input rst;
  input wr_clk;
  input rd_clk;
  input [WIDTH-1:0] din;
  input wr_en;
  input rd_en;
  output [WIDTH-1:0] dout;
  output full;
  output empty;
  output valid;
  output [11:0] rd_data_count;

  reg [WIDTH-1:0] mem [DEPTH-1:0];
  reg [6:0] wr_ptr = 0;
  reg [6:0] rd_ptr = 0;
  reg [11:0] count = 0;
  wire [6:0] next_wr_ptr = wr_ptr + 1;
  wire [6:0] next_rd_ptr = rd_ptr + 1;

  always @(posedge wr_clk, posedge rst) begin
    if (rst) begin
      wr_ptr <= 0;
      rd_ptr <= 0;
      count <= 0;
    end else if (wr_en && !full) begin
      mem[wr_ptr] <= din;
      wr_ptr <= next_wr_ptr;
      count <= count + 1;
    end
  end

  always @(posedge rd_clk, posedge rst) begin
    if (rst) begin
      wr_ptr <= 0;
      rd_ptr <= 0;
      count <= 0;
    end else if (rd_en && !empty) begin
      dout <= mem[rd_ptr];
      rd_ptr <= next_rd_ptr;
      count <= count - 1;
    end
  end

  assign full = (count == DEPTH);
  assign empty = (count == 0);
  assign valid = (!empty);

  assign rd_data_count = count;

endmodule

module top_module (
    input clk,
    input rst_n,
    input write_en,
    input [7:0] write_addr,
    input [3:0] write_data,
    input read_en,
    input [7:0] read_addr,
    output reg [7:0] final_output
);

    // Define the RAM
    reg [3:0] ram [0:7];
    reg [3:0] read_data;

    // Define the D flip-flop
    reg [3:0] d_ff;
    always @(posedge clk) begin
        d_ff <= write_data;
    end

    // Write operation
    always @(posedge clk) begin
        if (write_en) begin
            ram[write_addr] <= write_data;
        end
    end

    // Read operation
    always @(posedge clk) begin
        if (read_en) begin
            read_data <= ram[read_addr];
        end
    end

    // Circular buffer architecture
    always @(posedge clk) begin
        if (write_en) begin
            write_addr <= (write_addr + 1) % 8;
        end
        if (read_en) begin
            read_addr <= (read_addr + 1) % 8;
        end
    end

    // Final output
    always @(posedge clk) begin
        final_output <= {d_ff, read_data};
    end

endmodule

