module top_module (
    input wire [15:0] in,
    input [7:0] select,
    input clk,
    input [7:0] in_edge,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo,
    output [7:0] anyedge_sum
);
    wire [7:0] edge_out;
    wire [7:0] splitter_out_hi;
    wire [7:0] splitter_out_lo;
    wire [7:0] functional_out;

    half_word_splitter splitter(
        .in(in),
        .out_hi(splitter_out_hi),
        .out_lo(splitter_out_lo)
    );

    edge_detector edge(
        .in(in_edge),
        .out(edge_out)
    );

    functional_module functional(
        .in1(splitter_out_hi),
        .in2(edge_out),
        .sum(functional_out)
    );

    always @(posedge clk) begin
        if (select == 1) begin
            out_hi <= splitter_out_hi;
            out_lo <= splitter_out_lo;
            anyedge_sum <= 0;
        end else begin
            out_hi <= 0;
            out_lo <= 0;
            anyedge_sum <= functional_out;
        end
    end
endmodule

