module pll_dll (
  input ref_clk,
  input data_clk,
  input reset,
  output pll_clk,
  output dll_clk
);

parameter pll_mult = 2;
parameter pll_div = 1;
parameter dll_delay = 1;

reg [31:0] pll_counter = 0;
reg [31:0] dll_counter = 0;

always @(posedge ref_clk or posedge reset) begin
  if (reset) begin
    pll_counter <= 0;
  end else begin
    pll_counter <= pll_counter + 1;
  end
end

always @(posedge data_clk or posedge reset) begin
  if (reset) begin
    dll_counter <= 0;
  end else begin
    dll_counter <= dll_counter + 1;
  end
end

assign pll_clk = ref_clk / pll_div * pll_mult;
assign dll_clk = data_clk;

always @(posedge ref_clk or posedge reset) begin
  if (reset) begin
    pll_counter <= 0;
  end else begin
    if (pll_counter >= (pll_mult - 1)) begin
      pll_counter <= 0;
    end else begin
      pll_counter <= pll_counter + 1;
    end
  end
end

always @(posedge data_clk or posedge reset) begin
  if (reset) begin
    dll_counter <= 0;
  end else begin
    if (dll_counter >= dll_delay) begin
      dll_clk <= data_clk;
      dll_counter <= 0;
    end else begin
      dll_counter <= dll_counter + 1;
    end
  end
end

endmodule

