module bcd_counter (
    input clk,          // Clock input
    input [2:0] en,     // Enable input for each digit
    output reg [15:0] q // BCD counter output
);

reg [3:0] johnson;      // Johnson counter
reg [3:0] bcd;          // BCD output

always @(posedge clk) begin
    // Johnson counter
    johnson <= {johnson[2:0], ~johnson[3]};

    // BCD encoding
    case (johnson)
        4'b0000: bcd <= 4'b0000;
        4'b0001: bcd <= 4'b0001;
        4'b0010: bcd <= 4'b0010;
        4'b0011: bcd <= 4'b0011;
        4'b0100: bcd <= 4'b0100;
        4'b0101: bcd <= 4'b0101;
        4'b0110: bcd <= 4'b0110;
        4'b0111: bcd <= 4'b0111;
        4'b1000: bcd <= 4'b1000;
        4'b1001: bcd <= 4'b1001;
        4'b1010: bcd <= 4'b0000;
        default: bcd <= 4'b0000;
    endcase

    // BCD counter
    if (en[0])
        q[3:0] <= bcd;
    if (en[1])
        q[7:4] <= bcd;
    if (en[2])
        q[11:8] <= bcd;
end

endmodule

