module top_module (
    input clk,          // Clock input
    input reset,        // Synchronous active-high reset
    input d,            // Input for the D flip-flop
    input aset,         // Asynchronous set input for the D flip-flop
    input areset,       // Asynchronous reset input for the D flip-flop
    output [15:0] q     // Output for the BCD counter and D flip-flop sum
);

reg [2:0] en;           // Enable input for each digit
wire [15:0] bcd;        // BCD counter output
wire [15:0] sum;        // Sum of BCD counter and D flip-flop output

bcd_counter bcd_counter_inst (
    .clk(clk),
    .en(en),
    .q(bcd)
);

d_flip_flop d_flip_flop_inst (
    .clk(clk),
    .d(d),
    .aset(aset),
    .areset(areset),
    .q(q[0])
);

final_output final_output_inst (
    .bcd(bcd),
    .d(q[0]),
    .q(sum)
);

always @(posedge clk) begin
    if (reset) begin
        en <= 3'b000;
        q <= 16'b0000000000000000;
    end else begin
        // BCD counter enable
        if (q[3:0] == 4'd9)
            en[0] <= 1'b1;
        if (q[7:4] == 4'd9)
            en[1] <= 1'b1;
        if (q[11:8] == 4'd9)
            en[2] <= 1'b1;

        // BCD counter reset
        if (q == 16'd9999)
            q <= 16'd0;
        else
            q <= q + 1;

        // Digit enable reset
        if (en[0] && q[3:0] == 4'd0)
            en[0] <= 1'b0;
        if (en[1] && q[7:4] == 4'd0)
            en[1] <= 1'b0;
        if (en[2] && q[11:8] == 4'd0)
            en[2] <= 1'b0;
    end
end

assign q[15:1] = sum[15:1];

endmodule

module communication_module(
    input RX_SP,
    input ready_r,
    input USER_CLK,
    input RX_NEG,
    input ack_r,
    input count_128d_done_r,
    input polarity_r,
    output reg remote_reset_watchdog_done_r,
    output reg watchdog_done_r,
    output reg sp_polarity_c,
    output reg RX_POLARITY
);

reg [15:0] counter4_r;
reg [15:0] counter5_r;
reg prev_count_128d_done_r;
reg do_watchdog_count_r;
reg rx_polarity_r;

// reset all the lanes if RX_SP is asserted while they are all in the lane ready state
always @(posedge USER_CLK) begin
    if (RX_SP && ready_r) begin
        remote_reset_watchdog_done_r <= 0;
        watchdog_done_r <= 0;
    end
end

// counter4 logic
always @(posedge USER_CLK) begin
    if (RX_SP || !ready_r) begin
        counter4_r <= {ready_r, counter4_r[0:14]};
    end
end

// the counter is done when a 1 reaches the end of the shift register
assign remote_reset_watchdog_done_r = counter4_r[15];

// counter5 logic
always @(posedge USER_CLK) begin
    if (do_watchdog_count_r || !ack_r) begin
        counter5_r <= {ack_r, counter5_r[0:14]};
    end
end

// store the count_128d_done_r result from the previous cycle
always @(posedge USER_CLK) begin
    prev_count_128d_done_r <= count_128d_done_r;
end

// trigger CE only when the previous 128d_done is not the same as the current one, and the current value is high
always @(posedge USER_CLK) begin
    do_watchdog_count_r <= count_128d_done_r & !prev_count_128d_done_r;
end

// the counter is done when bit 15 is high
assign watchdog_done_r = counter5_r[15];

// polarity control
assign sp_polarity_c = !RX_NEG;

// initialize the rx_polarity register for simulation purposes
initial rx_polarity_r = 1'b0;

// update the rx_polarity register based on the received symbols
always @(posedge USER_CLK) begin
    if (polarity_r && !sp_polarity_c) begin
        rx_polarity_r <= ~rx_polarity_r;
    end
end

// drive the rx_polarity register value on the interface
assign RX_POLARITY = rx_polarity_r;

endmodule

