module mux_priority_encoder (
    input [2:0] sel,
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output reg [3:0] out
);

reg [3:0] mux_out [5:0];
reg [2:0] priority;

always @* begin
    priority = 3'b000;
    if (data0 > data1 && data0 > data2 && data0 > data3 && data0 > data4 && data0 > data5) begin
        priority = 3'b000;
        mux_out[0] = data0;
    end
    else if (data1 > data2 && data1 > data3 && data1 > data4 && data1 > data5) begin
        priority = 3'b001;
        mux_out[1] = data1;
    end
    else if (data2 > data3 && data2 > data4 && data2 > data5) begin
        priority = 3'b010;
        mux_out[2] = data2;
    end
    else if (data3 > data4 && data3 > data5) begin
        priority = 3'b011;
        mux_out[3] = data3;
    end
    else if (data4 > data5) begin
        priority = 3'b100;
        mux_out[4] = data4;
    end
    else begin
        priority = 3'b101;
        mux_out[5] = data5;
    end
end

always @* begin
    case (sel)
        3'b000: out = mux_out[priority];
        3'b001: out = mux_out[priority] ^ 4'b1111;
        3'b010: out = mux_out[priority];
        3'b011: out = mux_out[priority] ^ 4'b1111;
        3'b100: out = mux_out[priority];
        3'b101: out = mux_out[priority] ^ 4'b1111;
        default: out = 4'b0000;
    endcase
end

endmodule

