module ui64ToRecF32 (
    input [(`floatControlWidth - 1):0] control,
    input [63:0] in,
    output [32:0] out,
    output [4:0] exceptionFlags
);

    // Constants
    localparam integer EXP_BIAS = 127;
    localparam integer SIG_BITS = 23;
    localparam integer EXP_BITS = 8;
    localparam integer EXP_MASK = { { EXP_BITS { 1'b1 } }, 1'b0 };
    localparam integer SIG_MASK = { { SIG_BITS { 1'b1 } }, 1'b0 };

    // Signals
    wire sign = in[63];
    wire [7:0] exponent;
    wire [22:0] significand;
    wire [23:0] rounded_significand;
    wire [31:0] packed;
    wire overflow;
    wire underflow;
    wire inexact;

    // Determine exponent
    assign exponent = (in == 0) ? 0 : (EXP_BIAS + $countones(in[63:0]) - 1);

    // Determine significand
    assign significand = (in == 0) ? 0 : ((in & SIG_MASK) | (1 << SIG_BITS));

    // Round significand
    iNToRecFN#(24, 8, 1) iNToRecFN(control, 0, { exponent, significand }, 0, rounded_significand, { overflow, underflow, inexact });

    // Pack output
    assign packed = { sign, exponent, rounded_significand[22:0] };

    // Output results
    assign out = packed;
    assign exceptionFlags = { inexact, overflow, underflow, 0, 0 };

endmodule

module top_module (
    input clk,
    input reset, // Synchronous active-high reset
    input [3:0] d, // 4-bit input for the counter
    input load, // Parallel load input
    output [3:0] q // 4-bit output of the final sum
);

    wire [3:0] counter_out;
    wire [3:0] shift_reg_out;
    wire [3:0] sum_out;

    twos_complement #(.WIDTH(4)) tc_reset (.in(reset), .out(reset_tc));
    twos_complement #(.WIDTH(4)) tc_load (.in(load), .out(load_tc));

    counter #(.WIDTH(4)) counter_inst (.clk(clk), .reset(reset_tc), .load(load_tc), .d(d), .q(counter_out));
    shift_register #(.WIDTH(4)) shift_reg_inst (.clk(clk), .load(load), .in(counter_out), .out(shift_reg_out));
    adder #(.WIDTH(4)) adder_inst (.a(counter_out), .b(shift_reg_out), .sum(sum_out));

    assign q = sum_out;

endmodule

