module memory_test (
  input [n-1:0] address,
  input [m-1:0] data,
  output pass
);

parameter n = 8; // number of address signals
parameter m = 16; // number of data signals
parameter depth = 256; // depth of memory module

reg [m-1:0] mem [depth-1:0]; // memory module

integer i, j;
reg [m-1:0] test_pattern;

initial begin
  pass = 1; // initialize pass signal to 1

  for (i = 0; i < depth; i = i + 1) begin
    // generate test pattern for current memory location
    test_pattern = i % (2 ** m);

    // write test pattern to memory location
    mem[i] = test_pattern;

    // read test pattern back from memory location
    for (j = 0; j < m; j = j + 1) begin
      if (mem[i][j] != data[j]) begin
        pass = 0; // set pass signal to 0 if test pattern is not read back correctly
        $display("Memory test failed at address %d", i);
        $finish; // stop testing
      end
    end
  end

  $display("Memory test passed");
  $finish; // stop testing
end

endmodule

module clock_shift(
    input LOCKED,
    input [31:0] desired_shift_1000,
    input clk,
    input rst,
    output reg fail
);

    reg [31:0] clk_shifted;
    reg [31:0] clk_period_1000;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            fail <= 0;
            clk_shifted <= 0;
            clk_period_1000 <= 0;
        end else if (LOCKED) begin
            clk_period_1000 <= clk / 1000;
            if (desired_shift_1000 > 0) begin
                #(((desired_shift_1000 / 1000.0) * ((clk_period_1000 / 1000.0) / 360.0)) - 0.1);
                clk_shifted <= #0 clk << (desired_shift_1000 / 1000);
                if (clk_shifted !== 0) begin
                    fail <= 1;
                end
            end else if (desired_shift_1000 < 0) begin
                #(((clk_period_1000 / 1000.0) + ((desired_shift_1000 / 1000.0) * ((clk_period_1000 / 1000.0) / 360.0))) - 0.1);
                clk_shifted <= #0 clk << ((clk_period_1000 / 1000) + (desired_shift_1000 / 1000));
                if (clk_shifted !== 0) begin
                    fail <= 1;
                end
            end
            #0.2;
            if (clk_shifted !== 1 && desired_shift_1000 !== 0) begin
                fail <= 1;
            end
        end else begin
            fail <= 0;
        end
    end
endmodule

