module priority_encoder_pipeline (
    input [7:0] in,
    output reg [2:0] pos
);

reg [7:0] gray_in;
reg [2:0] gray_out;
reg [2:0] binary_out;

// Binary-to-Gray code converter
always @(*) begin
    gray_in = in ^ (in >> 1);
end

// Gray-to-binary code converter
always @(*) begin
    case (gray_out)
        3'b000: binary_out = 3'b000;
        3'b001: binary_out = 3'b001;
        3'b010: binary_out = 3'b010;
        3'b011: binary_out = 3'b011;
        3'b100: binary_out = 3'b100;
        3'b101: binary_out = 3'b101;
        3'b110: binary_out = 3'b110;
        3'b111: binary_out = 3'b111;
    endcase
end

// Pipeline stages
always @(posedge clk) begin
    gray_out <= {gray_in[2], gray_in[1], gray_in[0]};
end

always @(posedge clk) begin
    if (gray_out[2]) pos <= binary_out[2];
end

always @(posedge clk) begin
    if (gray_out[2] || gray_out[1]) pos <= binary_out[1];
end

always @(posedge clk) begin
    if (gray_out[2] || gray_out[1] || gray_out[0]) pos <= binary_out[0];
end

endmodule

