module ripple_carry_adder (
  input clk,
  input reset,
  input [3:0] a,
  input [3:0] b,
  input select,
  output [3:0] sum
);

  // Instantiate D flip-flops
  reg [3:0] a_reg, b_reg, c_in_reg;
  always @(posedge clk, posedge reset) begin
    if (reset) begin
      a_reg <= 4'b0;
      b_reg <= 4'b0;
      c_in_reg <= 1'b0;
    end else begin
      a_reg <= a;
      b_reg <= b;
      c_in_reg <= sum[3];
    end
  end

  // Instantiate full adder
  wire [3:0] fa_sum;
  wire fa_c_out;
  full_adder fa_inst (
    .a(a_reg),
    .b(b_reg),
    .c_in(c_in_reg),
    .sum(fa_sum),
    .c_out(fa_c_out)
  );

  // Instantiate majority gate
  wire [3:0] majority;
  majority_gate majority_inst (
    .a(a_reg),
    .b(b_reg),
    .c_in(c_in_reg),
    .majority(majority)
  );

  // Control logic for selecting OR or XOR operation
  wire enable;
  assign enable = majority[3] ^ select;

  // Functional module for performing OR or XOR operation
  wire [3:0] or_xor_out;
  or_xor or_xor_inst (
    .a(fa_sum),
    .b(majority),
    .select(select),
    .out(or_xor_out)
  );

  // Synchronous reset for adder output
  always @(posedge clk) begin
    if (reset) begin
      sum <= 4'b0;
    end else begin
      sum <= or_xor_out;
    end
  end

endmodule

module full_adder (
  input [3:0] a,
