  wire [2:0] sum_intermediate;
  assign sum_intermediate = xor_out ^ c_in;

  assign sum = sum_intermediate;

  assign c_out = and_out[2] | (and_out[1] & sum_intermediate[2]) | (and_out[0] & sum_intermediate[1]);

endmodule

