module mem_protect (
  input clk,
  input read_en,
  input write_en,
  input [mem_size-1:0] addr,
  input [mem_size-1:0] data_in,
  output [mem_size-1:0] data_out,
  output error
);

parameter mem_size = 256; // size of the memory block in bits
parameter prot_start = 64; // starting address of the protected segment
parameter prot_end = 191; // ending address of the protected segment

reg [mem_size-1:0] memory; // memory block

// Boolean functions to define the protected and unprotected segments
function [mem_size-1:0] protected;
  input [mem_size-1:0] addr;
  begin
    protected = (addr >= prot_start) && (addr <= prot_end);
  end
endfunction

function [mem_size-1:0] unprotected;
  input [mem_size-1:0] addr;
  begin
    unprotected = (addr < prot_start) || (addr > prot_end);
  end
endfunction

// Read operation
always @(posedge clk) begin
  if (read_en && unprotected(addr)) begin
    data_out <= memory[addr];
    error <= 0;
  end
  else if (read_en && protected(addr)) begin
    data_out <= 'bx;
    error <= 1;
  end
end

// Write operation
always @(posedge clk) begin
  if (write_en && unprotected(addr)) begin
    memory[addr] <= data_in;
    error <= 0;
  end
  else if (write_en && protected(addr)) begin
    error <= 1;
  end
end

endmodule

