module buffer
  #(parameter BUF_SIZE = 9)
  (
   // Control Interface
   input clk,
   input rst,
   input [31:0] ctrl_word,
   input go,
   output reg done,
   output reg error,
   output reg idle,

   // Buffer Interface
   output reg en_o,
   output reg we_o,
   output reg [BUF_SIZE-1:0] addr_o,
   output reg [31:0] dat_to_buf,
   input [31:0] dat_from_buf,

   // Write FIFO Interface
   input [31:0] wr_data_i,
   input [3:0] wr_flags_i,
   input wr_ready_i,
   output reg wr_ready_o,

   // Read FIFO Interface
   output reg [31:0] rd_data_o,
   output reg [3:0] rd_flags_o,
   output reg rd_ready_o,
   input rd_ready_i
  );

   reg [31:0] ctrl_reg;
   reg go_reg;

   always @(posedge clk)
     go_reg <= go;

   always @(posedge clk)
     if(rst)
       ctrl_reg <= 0;
     else
       if(go & (ctrl_word[31:28] == 0))
	 ctrl_reg <= ctrl_word;

   wire [BUF_SIZE-1:0] firstline = ctrl_reg[BUF_SIZE-1:0];
   wire [BUF_SIZE-1:0] lastline = ctrl_reg[2*BUF_SIZE-1:BUF_SIZE];

   wire       read = ctrl_reg[22];
   wire       write = ctrl_reg[23];
   wire       clear = ctrl_reg[24];

   localparam IDLE = 3'd0;
   localparam PRE_READ = 3'd1;
   localparam READING = 3'd2;
   localparam WRITING = 3'd3;
   localparam ERROR = 3'd4;
   localparam DONE = 3'd5;

   reg [2:0]  state;
   reg 	      rd_sop, rd_eop;
   wire       wr_sop, wr_eop, wr_error;
   reg [1:0]  rd_occ;
   wire [1:0] wr_occ;

   always @(posedge clk)
     if(rst)
       begin
	  state <= IDLE;
	  rd_sop <= 0;
	  rd_eop <= 0;
	  rd_occ <= 0;
       end
     else
       if(clear)
	 begin
	    state <= IDLE;
	    rd_sop <= 0;
	    rd_eop <= 0;
	    rd_occ <= 0;
	 end
       else 
	 case(state)
	   IDLE :
	     if(go_reg & read)
	       begin
		  addr_o <= firstline;
		  state <= PRE_READ;
	       end
	     else if(go_reg & write)
	       begin
		  addr_o <= firstline;
		  state <= WRITING;
	       end

	   PRE_READ :
	     begin
		state <= READING;
		addr_o <= addr_o + 1;
		rd_occ <= 2'b00;
		rd_sop <= 1;
		rd_eop <= 0;
	     end

	   READING :
	     if(rd_ready_i)
	       begin
		  rd_sop <= 0;
		  addr_o <= addr_o + 1;
		  if(addr_o == lastline)
		    begin
		       rd_eop <= 1;
		       rd_occ <= 0;
		    end
		  else
		    rd_eop <= 0;
		  if(rd_eop)
		    state <= DONE;
	       end

	   WRITING :
	     begin
		if(wr_ready_i)
		  begin
		     addr_o <= addr_o + 1;
		     if(wr_error)
		       begin
			  state <= ERROR;
		       end
		     else if((addr_o == lastline)||wr_eop)
		       state <= DONE;
		  end
	     end // case: WRITING

	 endcase // case(state)

   assign     dat_to_buf = wr_data_i;
   assign     rd_data_o = dat_from_buf;

   assign     rd_flags_o = { rd_occ[1:0], rd_eop, rd_sop };
   assign     rd_ready_o = (state == READING);

   assign     wr_sop = wr_flags_i[0];
   assign     wr_eop = wr_flags_i[1];
   assign     wr_occ = wr_flags_i[3:2];
   assign     wr_error = wr_sop & wr_eop;
   assign     wr_ready_o = (state == WRITING);

   assign     we_o = (state == WRITING);

   assign     en_o = ~((state==READING)& ~rd_ready_i);

   always @(posedge clk)
     begin
	if(state == DONE)
	  begin
	     done <= 1;
	     rd_occ <= rd_occ + wr_occ;
	     if(rd_occ > 2'b11)
	       begin
		  error <= 1;
		  rd_occ <= 2'b11;
	       end
	     idle <= 1;
	  end
	else
	  begin
	     done <= 0;
	     error <= 0;
	     idle <= 0;
	  end
     end

endmodule

module G711_codec (
  input in,
  output out
);

parameter fs = 8000; // sampling frequency in Hz
parameter bitrate = 64; // bitrate in kbps

// Quantizer function
function [7:0] quantize;
  input [7:0] sample;
  reg [7:0] quantized;
  begin
    if (sample >= 128) begin
      quantized = (sample - 128) >> 4;
    end else begin
      quantized = (128 - sample) >> 4;
    end
  end
endfunction

// Logarithmic encoder function
function [7:0] encode;
  input [7:0] quantized;
  reg [7:0] encoded;
  begin
    if (quantized == 0) begin
      encoded = 0;
    end else begin
      encoded = $clog2(quantized) + 1;
      encoded = (encoded << 4) | quantized;
    end
  end
endfunction

// Byte packing function
function [7:0] pack;
  input [7:0] encoded;
  reg [7:0] packed;
  begin
    packed = encoded >> 1;
  end
endfunction

// Main module functionality
reg [7:0] sample;
reg [7:0] quantized;
reg [7:0] encoded;
reg [7:0] packed;
integer i;

always @(posedge clk) begin
  // Sample the input signal
  sample = in;

  // Quantize the sample
  quantized = quantize(sample);

  // Encode the quantized value
  encoded = encode(quantized);

  // Pack the encoded value into bytes
  packed = pack(encoded);

  // Output the packed byte
  for (i = 0; i < bitrate/8; i = i + 1) begin
    out = packed;
  end
end

endmodule

