module non_restoring_division (
  input [n-1:0] dividend,
  input [n-1:0] divisor,
  output [n-1:0] quotient,
  output [n-1:0] remainder
);

parameter n = 8; // number of bits in the operands

reg [n-1:0] q; // quotient register
reg [n-1:0] r; // remainder register

initial begin
  q = 0;
  r = dividend;
end

genvar i;
generate
  for (i = 0; i < n; i = i + 1) begin : loop
    always @(*) begin
      q = {q[n-2:0], r[n-1]};
      r = {r[n-2:0], 1'b0};
      r = r - divisor;
      if (r < 0) begin
        q[n-1] = 1'b0;
        r = r + divisor;
      end
      else begin
        q[n-1] = 1'b1;
      end
    end
  end
endgenerate

assign quotient = q;
assign remainder = r;

endmodule

