module axi_protocol_converter #
  (
    parameter ADDR_WIDTH = 32,
    parameter DATA_WIDTH = 32,
    parameter FIFO_DEPTH = 16
  )
  (
    input  wire                    clk,
    input  wire                    rst,
    // AXI master read interface
    input  wire                    m_axi_arvalid,
    output reg                     m_axi_arready,
    input  wire [ADDR_WIDTH-1:0]   m_axi_araddr,
    output wire                    m_axi_rvalid,
    input  wire                    m_axi_rready,
    output wire [DATA_WIDTH-1:0]   m_axi_rdata,
    output wire [1:0]              m_axi_rresp,
    // AXI slave write interface
    output wire                    s_axi_awvalid,
    input  wire                    s_axi_awready,
    output wire [ADDR_WIDTH-1:0]   s_axi_awaddr,
    output wire                    s_axi_wvalid,
    input  wire                    s_axi_wready,
    output wire [DATA_WIDTH-1:0]   s_axi_wdata,
    output wire [DATA_WIDTH/8-1:0] s_axi_wstrb,
    input  wire                    s_axi_bvalid,
    output wire                    s_axi_bready,
    input  wire [1:0]              s_axi_bresp
  );

  // FIFO buffer
  reg [DATA_WIDTH-1:0] fifo [FIFO_DEPTH-1:0];
  reg [FIFO_DEPTH-1:0] fifo_count;
  wire fifo_full = (fifo_count == FIFO_DEPTH);
  wire fifo_empty = (fifo_count == 0);

  // read address and data registers
  reg [ADDR_WIDTH-1:0] read_addr_reg;
  reg [DATA_WIDTH-1:0] read_data_reg;
  reg [1:0] read_resp_reg;

  // write address and data registers
  reg [ADDR_WIDTH-1:0] write_addr_reg;
  reg [DATA_WIDTH-1:0] write_data_reg;
  reg [DATA_WIDTH/8-1:0] write_strb_reg;
  reg [1:0] write_resp_reg;

  // read address state machine
  localparam READ_IDLE = 2'b00;
  localparam READ_ADDR = 2'b01;
  localparam READ_DATA = 2'b10;
  reg [1:0] read_state = READ_IDLE;

  // write address state machine
  localparam WRITE_IDLE = 2'b00;
  localparam WRITE_ADDR = 2'b01;
  localparam WRITE_DATA = 2'b10;
  reg [1:0] write_state = WRITE_IDLE;

  // AXI master read address interface
  always @(posedge clk) begin
    if (rst) begin
      m_axi_arready <= 1'b0;
      read_state <= READ_IDLE;
    end
    else begin
      case (read_state)
        READ_IDLE: begin
          if (m_axi_arvalid && !fifo_full) begin
            read_addr_reg <= m_axi_araddr;
            m_axi_arready <= 1'b1;
            read_state <= READ_ADDR;
          end
        end
        READ_ADDR: begin
          if (m_axi_rready) begin
            m_axi_arready <= 1'b0;
            read_state <= READ_DATA;
          end
        end
        READ_DATA: begin
          if (m_axi_rvalid) begin
            read_data_reg <= m_axi_rdata;
            read_resp_reg <= m_axi_rresp;
            read_state <= READ_IDLE;
          end
        end
      endcase
    end
  end

  // AXI slave write address and data interface
  always @(posedge clk) begin
    if (rst) begin
      s_axi_awvalid <= 1'b0;
      write_state <= WRITE_IDLE;
    end
    else begin
      case (write_state)
        WRITE_IDLE: begin
          if (!fifo_empty && s_axi_awready) begin
            write_addr_reg <= fifo[fifo_count-1];
            write_data_reg <= fifo[fifo_count-1];
            write_strb_reg <= {DATA_WIDTH/8{1'b1}};
            s_axi_awvalid <= 1'b1;
            fifo_count <= fifo_count - 1;
            write_state <= WRITE_ADDR;
          end
        end
        WRITE_ADDR: begin
          if (s_axi_wready) begin
            s_axi_awvalid <= 1'b0;
            s_axi_wvalid <= 1'b1;
            write_state <= WRITE_DATA;
          end
        end
        WRITE_DATA: begin
          if (s_axi_wready) begin
            s_axi_wvalid <= 1'b0;
            write_resp_reg <= s_axi_bresp;
            write_state <= WRITE_IDLE;
          end
        end
      endcase
    end
  end

  // FIFO buffer
  always @(posedge clk) begin
    if (rst) begin
      fifo_count <= 0;
    end
    else begin
      if (m_axi_rvalid && !fifo_full) begin
        fifo[fifo_count] <= m_axi_rdata;
        fifo_count <= fifo_count + 1;
      end
    end
  end

  // AXI slave write response interface
  always @(posedge clk) begin
    if (rst) begin
      s_axi_bready <= 1'b0;
    end
    else begin
      if (write_state == WRITE_IDLE) begin
        s_axi_bready <= 1'b1;
      end
      else begin
        s_axi_bready <= 1'b0;
      end
    end
  end

  // AXI master read data and response interface
  always @(posedge clk) begin
    if (rst) begin
      m_axi_rvalid <= 1'b0;
      m_axi_rdata <= 0;
      m_axi_rresp <= 2'b00;
    end
    else begin
      if (read_state == READ_DATA) begin
        m_axi_rvalid <= 1'b1;
        m_axi_rdata <= read_data_reg;
        m_axi_rresp <= read_resp_reg;
      end
      else begin
        m_axi_rvalid <= 1'b0;
        m_axi_rdata <= 0;
        m_axi_rresp <= 2'b00;
      end
    end
  end

endmodule

