reg [n-1:0] in_ff; // flip-flop for input signals
reg [m-1:0] out_ff; // flip-flop for output signals

always @(posedge clk) begin
  if (rst) begin
    in_ff <= 0;
    out_ff <= 0;
  end else begin
    // Asynchronous-to-synchronous synchronizer
