module top_module( 
    input [99:0] data_in,
    input select,
    output out_and,
    output out_or,
    output out_xor 
);

    wire [49:0] data_in_1 = data_in[49:0];
    wire [49:0] data_in_2 = data_in[99:50];

    wire [49:0] and_1;
    wire [49:0] or_1;
    wire [49:0] xor_1;

    wire [49:0] and_2;
    wire [49:0] or_2;
    wire [49:0] xor_2;

    // First register
    nand_gate #(50) and_gate_1(
        .a(data_in_1),
        .b(data_in_1),
        .out(and_1)
    );

    nand_gate #(50) or_gate_1(
        .a(~data_in_1),
        .b(~data_in_1),
        .out(or_1)
    );

    nand_gate #(50) xor_gate_1(
        .a(data_in_1),
        .b(~data_in_1),
        .out(xor_1)
    );

    // Second register
    nand_gate #(50) and_gate_2(
        .a(data_in_2),
        .b(data_in_2),
        .out(and_2)
    );

    nand_gate #(50) or_gate_2(
        .a(~data_in_2),
        .b(~data_in_2),
        .out(or_2)
    );

    nand_gate #(50) xor_gate_2(
        .a(data_in_2),
        .b(~data_in_2),
        .out(xor_2)
    );

    // Output selection
    nand_gate #(2) select_gate_and(
        .a(select),
        .b(select),
        .out(out_and)
    );

    nand_gate #(2) select_gate_or(
        .a(select),
        .b(~select),
        .out(out_or)
    );

    nand_gate #(2) select_gate_xor(
        .a(~select),
        .b(select),
        .out(out_xor)
    );

    // BDD technique for output selection
    assign out_and = and_1 & and_2;
    assign out_or = or_1 | or_2;
    assign out_xor = xor_1 ^ xor_2;

endmodule

