    assign abs_in_1 = (in_1[3] == 1) ? (~in_1 + 1) : in_1;

    add_sub add_sub_inst (
        .in_0(in_0),
        .in_1({ctrl, abs_in_1}),
        .ctrl(ctrl),
        .result(add_sub_result)
    );

    magnitude_comp mag_comp_inst (
