            ov = (add_sub_result[3] == in_0[3] && add_sub_result[3] != add_sub_result[2]) ? 1 : 0;
        end else begin
            result = add_sub_result[2:0];
            ov = (add_sub_result[3:2] == 2'b10 || add_sub_result[3:2] == 2'b01) ? 1 : 0;
        end
    end

