module TDC (
  input clk_ref,
  input sig,
  output reg [31:0] out
);

parameter clk_freq = 1e6; // frequency of the reference clock signal
parameter resolution = 10; // resolution of the TDC in terms of clock cycles

reg [31:0] counter;
reg [31:0] prev_sig;
reg [31:0] curr_sig;
reg [31:0] diff;

always @(posedge clk_ref) begin
  counter <= counter + 1;
  if (counter == resolution) begin
    prev_sig <= curr_sig;
    curr_sig <= sig;
    diff <= curr_sig - prev_sig;
    out <= diff * clk_freq / resolution;
    counter <= 0;
  end
end

endmodule

