  wire sending = |bitcount;

  wire ser_clk;

  wire starting = uart_wr_i & ~uart_busy;
  baudgen #(.CLKFREQ(CLKFREQ)) _baudgen(
    .clk(clk),
    .resetq(resetq),
    .baud(baud),
    .restart(starting),
    .ser_clk(ser_clk));

  always @(posedge ser_clk)
  begin
    if (bitcount == 0) begin
      uart_tx <= 0;
      shifter <= 0;
      bitcount <= 1;
    end else if (bitcount < 10) begin
      uart_tx <= shifter[0];
      shifter <= { shifter[7:0], 1'b0 };
      bitcount <= bitcount + 1;
    end else begin
      uart_tx <= 1;
      bitcount <= 0;
    end
  end

  always @(negedge resetq or posedge clk)
  begin
    if (!resetq) begin
      uart_tx <= 1;
      bitcount <= 0;
      shifter <= 0;
    end else begin
      if (starting) begin
        shifter <= { uart_dat_i[7:0], 1'b0 };
        bitcount <= 1;
      end

      if (sending & ser_clk) begin
        bitcount <= bitcount + 1;
      end
    end
  end

endmodule

module baudgen #(
  parameter CLKFREQ = 1000000
) (
  input clk,
  input resetq,
  input [31:0] baud,
  input restart,
  output reg ser_clk
);
  reg [31:0] counter;
  reg [31:0] compare_value;

  always @(posedge clk or negedge resetq)
  begin
    if (!resetq) begin
      counter <= 0;
      ser_clk <= 0;
    end else begin
      if (restart) begin
        counter <= 0;
      end else begin
        counter <= counter + 1;
      end

      compare_value <= (CLKFREQ / baud) - 1;

      if (counter >= compare_value) begin
        counter <= 0;
        ser_clk <= ~ser_clk;
      end
    end
  end
endmodule

module counter (
    input clk,
    input reset,
    input enable,
    output reg [3:0] count
);

reg [3:0] count_reg1, count_reg2, count_reg3;

always @(posedge clk) begin
    if (reset) begin
        count_reg1 <= 4'b0;
        count_reg2 <= 4'b0;
        count_reg3 <= 4'b0;
    end
    else if (enable) begin
        count_reg1 <= count + 4'b1;
        count_reg2 <= count_reg1;
        count_reg3 <= count_reg2;
    end
end

assign count = enable ? count_reg3 : count;

endmodule

module l1_data_cache_counter(
		input wire iCLOCK,
		input wire inRESET,
		//Hit Information
		input wire iCACHE_VALID,
		input wire iCACHE_HIT,
		//Information
		output wire [6:0] oINFO_COUNT
	);

	reg [99:0] b_counter;
	always@(posedge iCLOCK or negedge inRESET)begin
		if(!inRESET)begin
			b_counter <= 100'h0;
		end
		else begin
			if(iCACHE_VALID)begin
				b_counter <= {b_counter[98:0], iCACHE_HIT};
			end
		end
	end

	reg [3:0] b_buffer0[0:9];	//10*10
	reg [5:0] b_buffer1[0:1];	//50*2
	reg [6:0] b_buffer2;		//100*1
	always@(posedge iCLOCK or negedge inRESET)begin
		if(!inRESET)begin
			b_buffer0[0] <= 4'h0;
			b_buffer0[1] <= 4'h0;
			b_buffer0[2] <= 4'h0;
			b_buffer0[3] <= 4'h0;
			b_buffer0[4] <= 4'h0;
			b_buffer0[5] <= 4'h0;
			b_buffer0[6] <= 4'h0;
			b_buffer0[7] <= 4'h0;
			b_buffer0[8] <= 4'h0;
			b_buffer0[9] <= 4'h0;
			b_buffer1[0] <= 6'h0;
			b_buffer1[1] <= 6'h1;
			b_buffer2 <= 7'h0;
		end
		else begin
			//Buffer0
			b_buffer0[0] <= 4'h0
							+ b_counter[0] + b_counter[1] + b_counter[2] + b_counter[3] + b_counter[4]
							+ b_counter[5] + b_counter[6] + b_counter[7] + b_counter[8] + b_counter[9];
			b_buffer0[1] <= 4'h0
							+ b_counter[10] + b_counter[11] + b_counter[12] + b_counter[13] + b_counter[14]
							+ b_counter[15] + b_counter[16] + b_counter[17] + b_counter[18] + b_counter[19];
			b_buffer0[2] <= 4'h0
							+ b_counter[20] + b_counter[21] + b_counter[22] + b_counter[23] + b_counter[24]
							+ b_counter[25] + b_counter[26] + b_counter[27] + b_counter[28] + b_counter[29];
			b_buffer0[3] <= 4'h0
							+ b_counter[30] + b_counter[31] + b_counter[32] + b_counter[33] + b_counter[34]
							+ b_counter[35] + b_counter[36] + b_counter[37] + b_counter[38] + b_counter[39];
			b_buffer0[4] <= 4'h0
							+ b_counter[40] + b_counter[41] + b_counter[42] + b_counter[43] + b_counter[44]
							+ b_counter[45] + b_counter[46] + b_counter[47] + b_counter[48] + b_counter[49];
			b_buffer0[5] <= 4'h0
							+ b_counter[50] + b_counter[51] + b_counter[52] + b_counter[53] + b_counter[54]
							+ b_counter[55] + b_counter[56] + b_counter[57] + b_counter[58] + b_counter[59];
			b_buffer0[6] <= 4'h0
							+ b_counter[60] + b_counter[61] + b_counter[62] + b_counter[63] + b_counter[64]
							+ b_counter[65] + b_counter[66] + b_counter[67] + b_counter[68] + b_counter[69];
			b_buffer0[7] <= 4'h0
							+ b_counter[70] + b_counter[71] + b_counter[72] + b_counter[73] + b_counter[74]
							+ b_counter[75] + b_counter[76] + b_counter[77] + b_counter[78] + b_counter[79];
			b_buffer0[8] <= 4'h0
							+ b_counter[80] + b_counter[81] + b_counter[82] + b_counter[83] + b_counter[84]
							+ b_counter[85] + b_counter[86] + b_counter[87] + b_counter[88] + b_counter[89];
			b_buffer0[9] <= 4'h0
							+ b_counter[90] + b_counter[91] + b_counter[92] + b_counter[93] + b_counter[94]
							+ b_counter[95] + b_counter[96] + b_counter[97] + b_counter[98] + b_counter[99];
			b_buffer1[0] <= 6'h0 + b_buffer0[0] + b_buffer0[1] + b_buffer0[2] + b_buffer0[3] + b_buffer0[4];
			b_buffer1[1] <= 6'h0 + b_buffer0[5] + b_buffer0[6] + b_buffer0[7] + b_buffer0[8] + b_buffer0[9]; 
			b_buffer2 <= b_buffer1[0] + b_buffer1[1];
		end
	end 

	assign oINFO_COUNT = b_buffer2;

endmodule

module top_module (
    input clk,
    input reset, // Synchronous active-high reset
    input [7:0] a, b, // 8-bit inputs for the adder
    input select, // Select input to choose between adder and counter
    output [7:0] q // 8-bit output of the functional module
);

    wire [7:0] adder_out;
    wire [3:0] counter_out;
    wire [7:0] sum;

    adder adder_inst (
        .a(a),
        .b(b),
        .sum(adder_out)
    );

    counter counter_inst (
        .clk(clk),
        .reset(reset),
        .q(counter_out)
    );

    functional functional_inst (
        .adder_out(adder_out),
        .counter_out(counter_out),
        .sum(sum)
    );

    control control_inst (
        .select(select),
        .adder_out(adder_out),
        .counter_out(counter_out),
        .sum(sum),
        .q(q)
    );

endmodule

module adder (
    input [7:0] a,
    input [7:0] b,
    output reg [7:0] sum
);

    always @(*) begin
        sum = a + b;
    end

endmodule

module counter (
    input clk,
    input reset,
    output reg [3:0] q
);

    parameter PERIOD = 16;

    always @(posedge clk) begin
        if (reset) begin
            q <= 0;
        end else if (q == PERIOD - 1) begin
            q <= 0;
        end else begin
            q <= q + 1;
        end
    end

endmodule

module functional (
    input [7:0] adder_out,
    input [3:0] counter_out,
    output reg [7:0] sum
);

    always @(*) begin
        sum = adder_out + (counter_out << 8);
    end

endmodule

module control (
    input select,
    input [7:0] adder_out,
    input [3:0] counter_out,
    input [7:0] sum,
    output reg [7:0] q
);

    always @(*) begin
        if (select) begin
            q = sum + (counter_out << 8);
        end else begin
            q = sum + adder_out;
        end
    end

endmodule

module matrix_mux (
    input [63:0] A,
    input [63:0] B,
    input [15:0] C,
    input [15:0] D,
    input [15:0] E,
    input [15:0] F,
    input [1:0] SEL,
    output [63:0] Y
);

    wire [15:0] row0, row1, row2, row3;
    wire [15:0] col0, col1, col2, col3;

    // Matrix multiplication
    assign row0 = A[15:0]*B[0] + A[31:16]*B[4] + A[47:32]*B[8] + A[63:48]*B[12];
    assign row1 = A[15:0]*B[1] + A[31:16]*B[5] + A[47:32]*B[9] + A[63:48]*B[13];
    assign row2 = A[15:0]*B[2] + A[31:16]*B[6] + A[47:32]*B[10] + A[63:48]*B[14];
    assign row3 = A[15:0]*B[3] + A[31:16]*B[7] + A[47:32]*B[11] + A[63:48]*B[15];

    // Vector addition
    assign col0 = (SEL == 2'b01) ? C : (SEL == 2'b10) ? D : (SEL == 2'b11) ? E + F : row0[15:0];
    assign col1 = (SEL == 2'b01) ? C : (SEL == 2'b10) ? D : (SEL == 2'b11) ? E + F : row1[15:0];
    assign col2 = (SEL == 2'b01) ? C : (SEL == 2'b10) ? D : (SEL == 2'b11) ? E + F : row2[15:0];
    assign col3 = (SEL == 2'b01) ? C : (SEL == 2'b10) ? D : (SEL == 2'b11) ? E + F : row3[15:0];

    // Output
    assign Y = {col0, col1, col2, col3};

endmodule

module assert_unchange_assume (
    input clk,
    input reset_n,
    input start_event,
    input [width-1:0] test_expr,
    input window,
    input ignore_new_start,
    input reset_on_new_start,
    input error_on_new_start,
    input xzcheck_enable
);

    parameter width = 8;
    parameter num_cks = 2;

    reg [width-1:0] prev_test_expr;
    reg [num_cks-1:0] counter;
    reg in_window;
    reg error;
    reg reset;

    always @(posedge clk or negedge reset_n) begin
        if (~reset_n) begin
            prev_test_expr <= {width{1'b0}};
            counter <= {num_cks{1'b0}};
            in_window <= 1'b0;
            error <= 1'b0;
            reset <= 1'b0;
        end else begin
            if (reset_on_new_start && start_event) begin
                reset <= 1'b1;
            end else begin
                reset <= 1'b0;
            end

            if (reset) begin
                prev_test_expr <= {width{1'b0}};
                counter <= {num_cks{1'b0}};
                in_window <= 1'b0;
                error <= 1'b0;
            end else if (start_event) begin
                prev_test_expr <= test_expr;
                counter <= {num_cks{1'b0}};
                in_window <= 1'b1;
                error <= 1'b0;
            end else if (in_window) begin
                if (counter == window-1) begin
                    in_window <= 1'b0;
                end else begin
                    counter <= counter + 1;
                    if (test_expr !== prev_test_expr) begin
                        error <= 1'b1;
                    end
                end
            end else if (error_on_new_start && start_event) begin
                error <= 1'b1;
            end
        end
    end

    // X/Z checking
    always @(posedge clk or negedge reset_n) begin
        if (~reset_n) begin
            // do nothing
        end else begin
            if (xzcheck_enable) begin
                if (test_expr !== 'bx && test_expr !== 'bz) begin
                    prev_test_expr <= test_expr;
                end else if (prev_test_expr !== 'bx && prev_test_expr !== 'bz) begin
                    error <= 1'b1;
                end
            end
        end
    end

endmodule

module dffsl_ns (din, clk, set_l, q);
// synopsys template
parameter SIZE = 1;

input   [SIZE-1:0]      din ;   // data in
input                   clk ;   // clk or scan clk
input                   set_l ; // set

output  [SIZE-1:0]      q ;     // output

reg     [SIZE-1:0]      q ;

// synopsys sync_set_reset "set_l"
always @ (posedge clk) begin
  if (!set_l) // synchronous set is active
    q[SIZE-1:0] <= din[SIZE-1:0];
  else // synchronous reset is active
    q[SIZE-1:0] <= {SIZE{1'b1}};
end

endmodule

module barrel_shifter (
    input [3:0] A,
    input [1:0] B,
    input C,
    input areset,
    output [3:0] S
);

    reg [3:0] shifted;

    always @(*) begin
        if (areset) begin
            shifted <= 4'b0;
        end else begin
            if (C) begin
                shifted <= {A[B-1:0], 2'b0};
            end else begin
                shifted <= {2'b0, A[3:B]};
            end
        end
    end

    assign S = shifted;

endmodule

module UartDemux(
  input clk, 
  input RESET, 
  input UART_RX, 
  output reg [7:0] data, 
  output reg [7:0] addr, 
  output reg write, 
  output reg checksum_error
);
  wire [7:0] indata;
  wire       insend;
  Rs232Rx uart(clk, UART_RX, indata, insend);

  reg [1:0] state = 0;
  reg [7:0] cksum;
  reg [7:0] count;
  wire [7:0] new_cksum = cksum + indata;

  always @(posedge clk) if (RESET) begin
    write <= 0;
    state <= 0;
    count <= 0;
    cksum <= 0;
    addr <= 0;
    data <= 0;
    checksum_error <= 0;
  end else begin
    write <= 0;
    if (insend) begin
      cksum <= new_cksum;
      count <= count - 8'd1;
      if (state == 0) begin
        state <= 1;
        cksum <= indata;
      end else if (state == 1) begin
        addr <= indata;
        state <= 2;
      end else if (state == 2) begin
        count <= indata;
        state <= 3;
      end else begin
        data <= indata;
        write <= 1;
        if (count == 1) begin
          state <= 0;
          if (new_cksum != 0)
            checksum_error <= 1;
        end
      end
    end
  end
endmodule

module top_module (
    input clk,
    input reset,
    input up_down,
    input [7:0] in_hi,
    input [7:0] in_lo,
    output [15:0] out
);

reg [2:0] count;
wire [15:0] hw;
wire [15:0] final_out;

// Instantiate the 3-bit binary counter module
counter_3bit counter_inst (
    .clk(clk),
    .reset(reset),
    .up_down(up_down),
    .count(count)
);

// Instantiate the combinational circuit module
combinational_circuit comb_inst (
    .in_hi(in_hi),
    .in_lo(in_lo),
    .out(hw)
);

// Instantiate the functional module
functional_module func_inst (
    .hw(hw),
    .count(count),
    .out(final_out)
);

// Assign the final output to the output port
assign out = final_out;

endmodule

module counter_3bit (
    input clk,
    input reset,
    input up_down,
    output reg [2:0] count
);

always @(posedge clk or negedge reset) begin
    if (reset == 0) begin
        count <= 0;
    end else if (up_down == 1) begin
        count <= count + 1;
    end else begin
        count <= count - 1;
    end
end

endmodule

module combinational_circuit (
    input [7:0] in_hi,
    input [7:0] in_lo,
    output reg [15:0] out
);

always @* begin
    out = {in_hi, in_lo};
end

endmodule

module functional_module (
    input [15:0] hw,
    input [2:0] count,
    output reg [15:0] out
);

always @(posedge clk) begin
    out <= hw + count;
end

endmodule

module counter (
    input clk,
    input reset,
    input load,
    input [3:0] data,
    output reg [3:0] count,
    output reg max_reached
);

    always @(posedge clk) begin
        if (reset) begin
            count <= 4'b0000;
            max_reached <= 1'b0;
        end else if (load) begin
            count <= data;
            max_reached <= (count == 4'b1111);
        end else begin
            count <= count + 1;
            max_reached <= (count == 4'b1111);
        end
    end

endmodule

module barrel_shifter (
    input [3:0] input_value,
    input [1:0] shift_amount,
    output [3:0] shifted_value
);

    assign shifted_value = (shift_amount == 2'b00) ? input_value :
                           (shift_amount == 2'b01) ? {input_value[2:0], 1'b0} :
                           (shift_amount == 2'b10) ? {input_value[1:0], 2'b00} :
                                                    {input_value[0], 3'b000};

endmodule

module max_value (
    input [3:0] max_val,
    input [3:0] shifted_val,
    output [3:0] result
);

    assign result = (max_val > shifted_val) ? max_val : shifted_val;

endmodule

module top_module (
    input clk,
    input reset,
    input load,
    input [3:0] data,
    input [1:0] shift_amount,
    output [3:0] count,
    output max_reached,
    output [3:0] shifted_value,
    output [3:0] result
);

    counter counter_inst (
        .clk(clk),
        .reset(reset),
        .load(load),
        .data(data),
        .count(count),
        .max_reached(max_reached)
    );

    barrel_shifter shifter_inst (
        .input_value(count),
        .shift_amount(shift_amount),
        .shifted_value(shifted_value)
    );

    max_value max_inst (
        .max_val(count),
        .shifted_val(shifted_value),
        .result(result)
    );

endmodule

module message_display_system (
    input clk,
    input reset,   // Synchronous active-high reset
    input [7:0] message,   // ASCII message string input
    output [15:0] display  // 16-character display output
);

    // 4:16 decoder
    wire [15:0] decoder_output;
    decoder_4to16 decoder(
        .in({message[3], message[2], message[1], message[0]}),
        .out(decoder_output)
    );

    // 16-bit shift register
    reg [15:0] shift_register;
    always @(posedge clk) begin
        if (reset) begin
            shift_register <= 16'b0;
        end else begin
            shift_register <= {shift_register[14:0], decoder_output[15]};
        end
    end

    // Output display
    assign display = shift_register;

endmodule

// 4:16 decoder module
module decoder_4to16 (
    input [3:0] in,
    output reg [15:0] out
);

    always @* begin
        case (in)
            4'b0000: out = 16'b0000000000000001;
            4'b0001: out = 16'b0000000000000010;
            4'b0010: out = 16'b0000000000000100;
            4'b0011: out = 16'b0000000000001000;
            4'b0100: out = 16'b0000000000010000;
            4'b0101: out = 16'b0000000000100000;
            4'b0110: out = 16'b0000000001000000;
            4'b0111: out = 16'b0000000010000000;
            4'b1000: out = 16'b0000000100000000;
            4'b1001: out = 16'b0000001000000000;
            4'b1010: out = 16'b0000010000000000;
            4'b1011: out = 16'b0000100000000000;
            4'b1100: out = 16'b0001000000000000;
            4'b1101: out = 16'b0010000000000000;
            4'b1110: out = 16'b0100000000000000;
            4'b1111: out = 16'b1000000000000000;
            default: out = 16'b0000000000000000;
        endcase
    end

endmodule

module three_input_gate (
    input a,
    input b,
    input c,
    output y
);

    reg yi;

    always @(*) begin
        if (a | (b & c)) begin
            yi <= 1;
        end else if (a == 0 && b == 0 && c == 0) begin
            yi <= 0;
        end
    end

    assign y = yi;

endmodule

module shift_register_memory_block (
  input [n-1:0] in,
  input clk,
  input reset,
  output [m-1:0] out
);

parameter n = 8; // number of input signals
parameter m = 8; // number of output signals
parameter w = 8; // width of each shift register
parameter k = 4; // number of shift registers in the block

reg [w-1:0] shift_registers [k-1:0];

integer i;

always @(posedge clk or posedge reset) begin
  if (reset) begin
    for (i = 0; i < k; i = i + 1) begin
      shift_registers[i] <= 0;
    end
  end else begin
    shift_registers[0] <= {shift_registers[0][w-2:0], in};
    for (i = 1; i < k; i = i + 1) begin
      shift_registers[i] <= {shift_registers[i][w-2:0], shift_registers[i-1][w-1]};
    end
  end
end

assign out = {shift_registers[0][w-1], shift_registers[1][w-1], shift_registers[2][w-1], shift_registers[3][w-1]};

endmodule

module uart_module (
    input clk,
    input reset,
    input [7:0] port_id,
    input [7:0] data_in,
    input read_strobe,
    input write_strobe,
    input rx_data_present,
    input rx_half_full,
    input rx_full,
    input tx_data_present,
    input tx_half_full,
    input tx_full,
    output reg [7:0] data_out,
    output reg interrupt,
    output reg buffer_write,
    output reg [7:0] uart_data_write,
    output reg buffer_read,
    output reg enable,
    output reg [15:0] uart_clock_divide
);

// Register addresses
parameter BASE_ADDRESS = 8'h00;
parameter DATA_IN_ENABLE_ADDR = BASE_ADDRESS + 0;
parameter DATA_OUT_ENABLE_ADDR = BASE_ADDRESS + 0;
parameter CONTROL_ENABLE_ADDR = BASE_ADDRESS + 1;
parameter STATUS_ENABLE_ADDR = BASE_ADDRESS + 2;
parameter IRQ_MASK_ENABLE_ADDR = BASE_ADDRESS + 3;
parameter IRQ_ENABLE_ADDR = BASE_ADDRESS + 4;
parameter CLOCK_DIVIDE_LOWER_ENABLE_ADDR = BASE_ADDRESS + 5;
parameter CLOCK_DIVIDE_UPPER_ENABLE_ADDR = BASE_ADDRESS + 6;

// Internal registers
reg [7:0] control_reg = 8'h00;
reg [2:0] irq_mask_reg = 3'h0;
reg [2:0] irq_reg = 3'h0;
reg [15:0] clock_divide_reg = 16'h0000;
reg [7:0] tx_buffer [7:0];
reg [7:0] rx_buffer [7:0];
reg [3:0] tx_head = 4'h0;
reg [3:0] tx_tail = 4'h0;
reg [3:0] rx_head = 4'h0;
reg [3:0] rx_tail = 4'h0;
reg tx_full_reg = 1'b0;
reg tx_empty_reg = 1'b1;
reg rx_full_reg = 1'b0;
reg rx_empty_reg = 1'b1;

// Interrupt logic
always @(posedge clk) begin
    if (reset) begin
        interrupt <= 1'b0;
    end else if (rx_data_present && irq_mask_reg[0]) begin
        interrupt <= 1'b1;
    end else begin
        interrupt <= 1'b0;
    end
end

// Transmit buffer write logic
always @(posedge clk) begin
    if (reset) begin
        buffer_write <= 1'b0;
        uart_data_write <= 8'h00;
    end else if (write_strobe && (port_id == DATA_IN_ENABLE_ADDR)) begin
        tx_buffer[tx_head] <= data_in;
        tx_head <= tx_head + 1;
        tx_full_reg <= (tx_head == tx_tail);
        tx_empty_reg <= 0;
        buffer_write <= 1'b1;
    end else begin
        buffer_write <= 1'b0;
    end
end

// Transmit buffer read logic
always @(posedge clk) begin
    if (reset) begin
        enable <= 1'b0;
    end else if (tx_data_present && !tx_full_reg) begin
        uart_data_write <= tx_buffer[tx_tail];
        tx_tail <= tx_tail + 1;
        tx_empty_reg <= (tx_head == tx_tail);
        tx_full_reg <= 0;
        enable <= 1'b1;
    end else begin
        enable <= 1'b0;
    end
end

// Receive buffer write logic
always @(posedge clk) begin
    if (reset) begin
        buffer_read <= 1'b0;
    end else if (rx_data_present && !rx_full_reg) begin
        rx_buffer[rx_head] <= rx_data_present;
        rx_head <= rx_head + 1;
        rx_full_reg <= (rx_head == rx_tail);
        rx_empty_reg <= 0;
        buffer_read <= 1'b1;
    end else begin
        buffer_read <= 1'b0;
    end
end

// Receive buffer read logic
always @(posedge clk) begin
    if (reset) begin
        data_out <= 8'h00;
    end else if (read_strobe && (port_id == DATA_OUT_ENABLE_ADDR)) begin
        data_out <= rx_buffer[rx_tail];
        rx_tail <= rx_tail + 1;
        rx_empty_reg <= (rx_head == rx_tail);
        rx_full_reg <= 0;
    end else begin
        data_out <= 8'h00;
    end
end

// Control register write logic
always @(posedge clk) begin
    if (reset) begin
        control_reg <= 8'h00;
    end else if (write_strobe && (port_id == CONTROL_ENABLE_ADDR)) begin
        control_reg <= data_in;
    end
end

// Status register read logic
always @(posedge clk) begin
    if (reset) begin
        data_out <= 8'h00;
    end else if (read_strobe && (port_id == STATUS_ENABLE_ADDR)) begin
        data_out <= {2'b00, tx_full_reg, tx_empty_reg, tx_data_present, rx_full_reg, rx_empty_reg, rx_data_present};
    end
end

// IRQ mask register write logic
always @(posedge clk) begin
    if (reset) begin
        irq_mask_reg <= 3'h0;
    end else if (write_strobe && (port_id == IRQ_MASK_ENABLE_ADDR)) begin
        irq_mask_reg <= data_in[2:0];
    end
end

// IRQ register write logic
always @(posedge clk) begin
    if (reset) begin
        irq_reg <= 3'h0;
    end else if (write_strobe && (port_id == IRQ_ENABLE_ADDR)) begin
        irq_reg <= data_in[2:0];
    end
end

// Clock divide register write logic
always @(posedge clk) begin
    if (reset) begin
        clock_divide_reg <= 16'h0000;
    end else if (write_strobe && (port_id == CLOCK_DIVIDE_LOWER_ENABLE_ADDR)) begin
        clock_divide_reg[7:0] <= data_in;
    end else if (write_strobe && (port_id == CLOCK_DIVIDE_UPPER_ENABLE_ADDR)) begin
        clock_divide_reg[15:8] <= data_in;
    end
end

// Clock divide output logic
assign uart_clock_divide = clock_divide_reg;

endmodule

module shift_register (
    input clk,
    input reset, // Active-high asynchronous reset
    input [7:0] data_in, // 8-bit input for the shift register
    input [1:0] shift_direction, // Control input for shifting direction
    input load, // Load input for parallel load
    output [7:0] q // 8-bit output from the shift register
);

reg [7:0] shift_reg = 8'h34; // Initial value of shift register

always @(posedge clk or posedge reset) begin
    if (reset) begin
        shift_reg <= 8'h34;
    end else begin
        if (load) begin
            shift_reg <= data_in;
        end else begin
            case (shift_direction)
                2'b00: shift_reg <= {shift_reg[6:0], shift_reg[7]};
                2'b01: shift_reg <= {shift_reg[0], shift_reg[7:1]};
                2'b10: shift_reg <= shift_reg;
                2'b11: shift_reg <= {shift_reg[0], shift_reg[7:1]};
            endcase
        end
    end
end

assign q = shift_reg;

endmodule

module counter (
    input clk,
    input reset, // Synchronous reset
    output reg [3:0] count // 4-bit binary up counter
);

always @(posedge clk) begin
    if (reset) begin
        count <= 4'b0000;
    end else begin
        count <= count + 1;
    end
end

endmodule

module control_logic (
    input select, // Select input to choose between shift register and counter
    input [7:0] shift_reg_out, // Output from the shift register
    input [3:0] count_out, // Output from the counter
    output [7:0] active_out // Output from the active module
);

assign active_out = select ? count_out : shift_reg_out;

endmodule

module top_module (
    input clk,
    input reset, // Active-high asynchronous reset
    input [7:0] data_in, // 8-bit input for the shift register
    input [1:0] shift_direction, // Control input for shifting direction
    input load, // Load input for parallel load
    input select, // Select input to choose between shift register and counter
    output [7:0] q // 8-bit output from the active module
);

wire [7:0] shift_reg_out;
shift_register shift_reg_inst (
    .clk(clk),
    .reset(reset),
    .data_in(data_in),
    .shift_direction(shift_direction),
    .load(load),
    .q(shift_reg_out)
);

wire [3:0] count_out;
counter count_inst (
    .clk(clk),
    .reset(select ? reset : 0),
    .count(count_out)
);

control_logic control_inst (
    .select(select),
    .shift_reg_out(shift_reg_out),
    .count_out(count_out),
    .active_out(q)
);

endmodule

module FSM (
  input [m-1:0] in,
  output [n-1:0] out
);

parameter n = 4; // number of states
parameter m = 2; // number of inputs

reg [n-1:0] state; // current state
reg [n-1:0] next_state; // next state

// Define your state transition and output logic here
always @ (in) begin
  case (state)
    0: if (in[0] && in[1]) next_state = 3; else if (in[0]) next_state = 1; else if (in[1]) next_state = 2; else next_state = 0;
    1: if (in[0] && in[1]) next_state = 3; else if (in[1]) next_state = 2; else next_state = 0;
    2: if (in[0] && in[1]) next_state = 3; else if (in[0]) next_state = 1; else next_state = 0;
    3: if (in[0] && in[1]) next_state = 3; else if (in[0]) next_state = 1; else if (in[1]) next_state = 2; else next_state = 0;
  endcase
end

always @ (state, in) begin
  case (state)
    0: out = {1'b0, 1'b0, 1'b0, 1'b1};
    1: out = {1'b0, 1'b0, 1'b1, 1'b0};
    2: out = {1'b0, 1'b1, 1'b0, 1'b0};
    3: out = {1'b1, 1'b0, 1'b0, 1'b0};
  endcase
end

always @ (posedge clk) begin
  state <= next_state;
end

endmodule

module ToneDetectionGeneration (
  input in,
  output out
);

parameter f1 = 1000; // frequency of input sine wave (in Hz)
parameter f2 = 2000; // frequency of output square wave (in Hz)

// Sine wave generator
reg [15:0] phase = 0;
wire sine = $signed($sin(phase));

always @(posedge clk) begin
  phase <= phase + (2 * $pi * f1 / clk_freq);
end

// Frequency detector
reg [15:0] count = 0;
wire detect = (count >= (clk_freq / (2 * f1)));

always @(posedge clk) begin
  if (in == sine) begin
    count <= count + 1;
  end else begin
    count <= 0;
  end
end

// Square wave generator
reg [15:0] phase2 = 0;
wire square = (phase2 < (clk_freq / (2 * f2)));

always @(posedge clk) begin
  if (detect) begin
    phase2 <= phase2 + (2 * $pi * f2 / clk_freq);
  end else begin
    phase2 <= 0;
  end
end

assign out = square;

endmodule

module mealy_3state_sequence_detection (
  input clk,
  input reset,
  input i,
  output reg out
);

  parameter STATE_A = 2'b00;
  parameter STATE_B = 2'b01;
  parameter STATE_C = 2'b10;

  reg [1:0] state, next_state;

  always @(posedge clk) begin
    if (reset) begin
      state <= STATE_A;
      out <= 1'b0;
    end
    else begin
      state <= next_state;
      out <= (state == STATE_C) ? 1'b1 : 1'b0;
    end
  end

  always @(*) begin
    case (state)
      STATE_A: begin
        if (i) next_state = STATE_B;
        else next_state = STATE_A;
      end
      STATE_B: begin
        if (i) next_state = STATE_C;
        else next_state = STATE_A;
      end
      STATE_C: begin
        if (i) next_state = STATE_B;
        else next_state = STATE_A;
      end
    endcase
  end

endmodule

module bitwise_logical_xor(
    input [2:0] a,
    input [2:0] b,
    output [2:0] out_or_bitwise,
    output out_or_logical,
    output [5:0] out_not,
    output out_xor
);

    assign out_or_bitwise = a | b;
    assign out_or_logical = (a[0] || a[1] || a[2]) || (b[0] || b[1] || b[2]);
    assign out_not = ~{a, b};
    assign out_xor = out_or_bitwise ^ out_or_logical;

endmodule

module and_or_xor(
    input [99:0] in,
    output out_and,
    output out_or,
    output out_xor
);

    assign out_and = &in;
    assign out_or = |in;
    assign out_xor = ^in;

endmodule

module functional_module(
    input [2:0] out_or_bitwise,
    input out_or_logical,
    input [5:0] out_not,
    input out_xor,
    output final_output
);

    wire [1:0] mux_sel;
    wire [5:0] and_out;
    wire [5:0] or_out;
    wire [5:0] xor_out;

    assign mux_sel = {out_or_bitwise[0] ^ out_or_logical, out_xor};

    and_or_xor and_or_xor_inst(
        .in(out_not),
        .out_and(and_out),
        .out_or(or_out),
        .out_xor(xor_out)
    );

    assign final_output = mux_sel[1] ? xor_out[mux_sel[0]] : and_out[mux_sel[0]];

endmodule

module top_module(
    input [2:0] a,
    input [2:0] b,
    input [99:0] in,
    input select,
    input clk,
    input reset,
    output [2:0] out_or_bitwise,
    output out_or_logical,
    output [5:0] out_not,
    output out_and,
    output out_or,
    output out_xor,
    output final_output
);

    reg [2:0] a_reg;
    reg [2:0] b_reg;
    reg [99:0] in_reg;
    reg [1:0] select_reg;
    reg [2:0] out_or_bitwise_reg;
    reg out_or_logical_reg;
    reg [5:0] out_not_reg;
    reg out_and_reg;
    reg out_or_reg;
    reg out_xor_reg;
    reg final_output_reg;

    always @(posedge clk) begin
        if (reset) begin
            a_reg <= 3'b0;
            b_reg <= 3'b0;
            in_reg <= 100'b0;
            select_reg <= 2'b0;
            out_or_bitwise_reg <= 3'b0;
            out_or_logical_reg <= 1'b0;
            out_not_reg <= 6'b0;
            out_and_reg <= 1'b0;
            out_or_reg <= 1'b0;
            out_xor_reg <= 1'b0;
            final_output_reg <= 1'b0;
        end else begin
            a_reg <= a;
            b_reg <= b;
            in_reg <= in;
            select_reg <= select;
            out_or_bitwise_reg <= out_or_bitwise;
            out_or_logical_reg <= out_or_logical;
            out_not_reg <= out_not;
            out_and_reg <= out_and;
            out_or_reg <= out_or;
            out_xor_reg <= out_xor;
            final_output_reg <= final_output;
        end
    end

    bitwise_logical_xor bitwise_logical_xor_inst(
        .a(a_reg),
        .b(b_reg),
        .out_or_bitwise(out_or_bitwise_reg),
        .out_or_logical(out_or_logical_reg),
        .out_not(out_not_reg),
        .out_xor(out_xor_reg)
    );

    and_or_xor and_or_xor_inst(
        .in(in_reg),
        .out_and(out_and_reg),
        .out_or(out_or_reg),
        .out_xor(out_xor_reg)
    );

    functional_module functional_module_inst(
        .out_or_bitwise(out_or_bitwise_reg),
        .out_or_logical(out_or_logical_reg),
        .out_not(out_not_reg),
        .out_xor(out_xor_reg),
        .final_output(final_output_reg)
    );

    always @(posedge clk) begin
        if (reset) begin
            final_output <= 1'b0;
        end else begin
            if (select_reg == 2'b0) begin
                out_or_bitwise <= out_or_bitwise_reg;
                out_or_logical <= out_or_logical_reg;
                out_not <= out_not_reg;
                out_and <= 1'b0;
                out_or <= 1'b0;
                out_xor <= 1'b0;
            end else begin
                out_or_bitwise <= 3'b0;
                out_or_logical <= 1'b0;
                out_not <= 6'b0;
                out_and <= out_and_reg;
                out_or <= out_or_reg;
                out_xor <= out_xor_reg;
            end
            final_output <= functional_module_inst.final_output;
        end
    end

endmodule

module ycbcr_to_rgb (
    y, cb, cr,
    red, green, blue,
    clk
);

input clk;

input [7:0] y, cb, cr;
output reg [7:0] red, green, blue;

// offset the inputs
reg signed [8:0] adj_y, adj_cb, adj_cr;
always @(posedge clk) begin
    adj_y <= y;
    adj_cr <= cr - 8'd128;
    adj_cb <= cb - 8'd128;
end

// scaling constants from standard formulas
// nominal Y is 16 to 235
// nominal C's are 16-240 with 128 at zero
wire signed [8:0] const0 = 9'd128; // 1 * 128
wire signed [8:0] const1 = 9'd179; // 1.402 * 128
wire signed [8:0] const2 = - 9'd91; // 0.714136 * 128 
wire signed [8:0] const3 = - 9'd44; // 0.344136 * 128
wire signed [8:0] const4 = 9'd227; // 1.772 * 128

// multipliers - 9x9 is a natural building block
reg signed [17:0] product_a, product_b, product_c, 
    product_d, product_e;
always @(posedge clk) begin
    product_a <= const0 * adj_y;
    product_b <= const1 * adj_cr;
    product_c <= const2 * adj_cr;
    product_d <= const3 * adj_cb;
    product_e <= const4 * adj_cb;
end

// summation - 17 selected by simulation
reg signed [17:0] sum_red, sum_green, sum_blue;
always @(posedge clk) begin
    sum_red <= product_a + product_b;
    sum_green <= product_a + product_c + product_d;
    sum_blue <= product_a + product_e;
end

// saturation
always @(posedge clk) begin
    if (sum_red[17] == 1) begin
        red <= 8'h0;
    end else if (sum_red[16:15] == 2'b11) begin
        red <= 8'hff;
    end else begin
        red <= sum_red[14:7];
    end

    if (sum_green[17] == 1) begin
        green <= 8'h0;
    end else if (sum_green[16:15] == 2'b11) begin
        green <= 8'hff;
    end else begin
        green <= sum_green[14:7];
    end

    if (sum_blue[17] == 1) begin
        blue <= 8'h0;
    end else if (sum_blue[16:15] == 2'b11) begin
        blue <= 8'hff;
    end else begin
        blue <= sum_blue[14:7];
    end
end

endmodule

