module sprite_shift_register (
    input clk, 
    input reset, 
    input aen, 
    input [1:0] address, 
    input [8:0] hpos, 
    input [15:0] data_in, 
    output [1:0] sprdata, 
    output reg attach
);

parameter POS  = 2'b00;  
parameter CTL  = 2'b01;  
parameter DATA = 2'b10;  
parameter DATB = 2'b11;  

reg [15:0] datla;
reg [15:0] datlb;
reg [15:0] shifta;
reg [15:0] shiftb;
reg [8:0] hstart;
reg armed;
reg load;
reg load_del;

always @(posedge clk) begin
    if (reset) begin
        attach <= 0;
        armed <= 0;
        hstart <= 0;
    end
    else if (aen && address == CTL && data_in == 8'h80) begin
        attach <= 0;
        armed <= 0;
    end
    else if (aen && address == DATA) begin
        datla <= data_in;
        armed <= 1;
    end
end

always @(posedge clk) begin
    if (aen && address == POS) begin
        hstart[8:1] <= data_in[7:0];
    end
end

always @(posedge clk) begin
    if (aen && address == CTL) begin
        {attach, hstart[0]} <= {data_in[7], data_in[0]};
    end
end

always @(posedge clk) begin
    if (aen && address == DATB) begin
        datlb <= data_in;
    end
end

always @(posedge clk) begin
    if (armed && hpos[8:0] == hstart[8:0]) begin
        load <= 1;
    end
    else begin
        load <= 0;
    end
end

always @(posedge clk) begin
    load_del <= load;
end

always @(posedge clk) begin
    if (load_del) begin
        shifta <= datla;
        shiftb <= datlb;
    end
    else begin
        shifta <= {shifta[14:0], 1'b0};
        shiftb <= {shiftb[14:0], 1'b0};
    end
end

assign sprdata[1:0] = {shiftb[15], shifta[15]};

endmodule

module top_module( 
    input [3:0] a,
    input [3:0] b,
    input select,     // Select input to choose between different outputs
    output [3:0] out_xor_bitwise,
    output out_xor_logical,
    output [7:0] out_not
);

    // Generate the inverse of the input numbers
    wire [3:0] a_inv = ~a;
    wire [3:0] b_inv = ~b;

    // Generate the bitwise-XOR output
    wire [3:0] xor_bitwise = a ^ b;

    // Generate the logical-XOR output
    wire xor_logical = !(a & b) && (a | b);

    // Generate the output based on the select input
    assign out_xor_bitwise = select ? xor_bitwise : 4'b0;
    assign out_xor_logical = select ? xor_logical : 1'b0;
    assign out_not = select ? {b_inv, a_inv} : 8'b0;

endmodule

module MiniAlu (
    input Clock,
    input Reset,
    input [7:0] iData,
    output [7:0] oData,
    output oZero
);

    // Registers to hold the input and output data
    reg [7:0] r_iData;
    reg [7:0] r_oData;
    reg r_oZero;

    // Assign the output data and zero flag based on the input data
    always @ (posedge Clock)
    begin
        if (Reset)
        begin
            r_iData <= 8'b0;
            r_oData <= 8'b0;
            r_oZero <= 1'b1;
        end
        else
        begin
            r_iData <= iData;
            case (iData)
                8'b00000000: begin r_oData <= 8'b00000000; r_oZero <= 1'b1; end
                8'b00000001: begin r_oData <= 8'b00000001; r_oZero <= 1'b0; end
                8'b00000010: begin r_oData <= 8'b00000010; r_oZero <= 1'b0; end
                8'b00000011: begin r_oData <= 8'b00000011; r_oZero <= 1'b0; end
                8'b00000100: begin r_oData <= 8'b00000100; r_oZero <= 1'b0; end
                8'b00000101: begin r_oData <= 8'b00000101; r_oZero <= 1'b0; end
                8'b00000110: begin r_oData <= 8'b00000110; r_oZero <= 1'b0; end
                8'b00000111: begin r_oData <= 8'b00000111; r_oZero <= 1'b0; end
                8'b00001000: begin r_oData <= 8'b00001000; r_oZero <= 1'b0; end
                8'b00001001: begin r_oData <= 8'b00001001; r_oZero <= 1'b0; end
                8'b00001010: begin r_oData <= 8'b00001010; r_oZero <= 1'b0; end
                8'b00001011: begin r_oData <= 8'b00001011; r_oZero <= 1'b0; end
                8'b00001100: begin r_oData <= 8'b00001100; r_oZero <= 1'b0; end
                8'b00001101: begin r_oData <= 8'b00001101; r_oZero <= 1'b0; end
                8'b00001110: begin r_oData <= 8'b00001110; r_oZero <= 1'b0; end
                8'b00001111: begin r_oData <= 8'b00001111; r_oZero <= 1'b0; end
                default: begin r_oData <= 8'b0; r_oZero <= 1'b1; end
            endcase
        end
    end

    // Assign the output data and zero flag to the output ports
    assign oData = r_oData;
    assign oZero = r_oZero;

endmodule

