module dcm (
  input CLKIN,
  output CLKFX,
  output LOCKED,
  input RST,
  output reg [7:0] STATUS
);

  reg [5:0] counter;
  reg locked_reg;
  reg [2:0] duty_cycle_correction;

  always @(posedge CLKIN or posedge RST) begin
    if (RST) begin
      counter <= 0;
      STATUS <= 8'b0;
      duty_cycle_correction <= 3'b0;
    end else begin
      counter <= counter + 1;
      if (counter == 5'd11) begin
        counter <= 0;
        duty_cycle_correction <= duty_cycle_correction + 1;
        if (duty_cycle_correction == 3'd6) begin
          duty_cycle_correction <= 3'b0;
        end
      end
    end
  end

  always @(posedge CLKIN or posedge RST) begin
    if (RST) begin
      STATUS <= 8'b0;
      locked_reg <= 1'b0;
    end else begin
      STATUS[0] <= locked_reg;
      STATUS[1] <= CLKFX;
      STATUS[2] <= duty_cycle_correction[0];
