  reg [15:0] data_d = 16'h0000;
  reg valid_2d = 1'b0;
  reg [15:0] data_2d = 16'h0000;
  reg [15:0] dc_offset = 16'h0000;

  // DC offset calculation
  always @(posedge clk) begin
    if (valid == 1'b1) begin
      dc_offset <= (dcfilt_coeff * data + (65535 - dcfilt_coeff) * dc_offset) >> 16;
    end
