  always @(posedge clk) begin
    valid_d <= valid;
    data_d <= data + dcfilt_offset;
    valid_2d <= valid_d;
    data_2d <= data_d - dc_offset;
    if (dcfilt_enb == 1'b1) begin
      valid_out <= valid_2d;
      data_out <= data_2d;
    end else begin
      valid_out <= valid_d;
      data_out <= data_d;
    end
  end
