module log_exp (
  input clk,
  input [31:0] x,
  input [1:0] op,
  output reg [31:0] y
);

  reg [31:0] term, power;
  reg [4:0] count;
  reg [31:0] factorial;
  reg sign;

  always @(posedge clk) begin
    if (op == 0) begin // logarithm
      count <= 0;
      term <= 0;
      power <= x - 1;
      factorial <= 1;
      sign <= 1;
      while (count < 32) begin
        term <= term + (power * sign) / factorial;
        power <= power * (x - 1);
        factorial <= factorial * (count + 1);
        sign <= ~sign;
        count <= count + 1;
      end
      y <= term;
    end else begin // exponentiation
      count <= 0;
      term <= 1;
      power <= x;
      factorial <= 1;
      while (count < 32) begin
        term <= term + (power / factorial);
        power <= power * x;
        factorial <= factorial * (count + 1);
        count <= count + 1;
      end
      y <= term;
    end
  end

endmodule

module fifo_buffer(
    input clk,
    input rst,
    input write_en,
    input [15:0] write_data,
    input read_en,
    output reg full,
    output reg empty,
    output reg [15:0] read_data
);

reg [15:0] buffer [0:15];
reg [3:0] write_ptr;
reg [3:0] read_ptr;

always @(posedge clk or negedge rst) begin
    if(!rst) begin
        write_ptr <= 4'b0000;
        read_ptr <= 4'b0000;
        full <= 1'b0;
        empty <= 1'b1;
    end
    else begin
        if(write_en && !full) begin
            buffer[write_ptr] <= write_data;
            write_ptr <= write_ptr + 1;
            if(write_ptr == 4'b1111) begin
                write_ptr <= 4'b0000;
            end
            if(write_ptr == read_ptr) begin
                full <= 1'b1;
            end
            empty <= 1'b0;
        end
        if(read_en && !empty) begin
            read_data <= buffer[read_ptr];
            read_ptr <= read_ptr + 1;
            if(read_ptr == 4'b1111) begin
                read_ptr <= 4'b0000;
            end
            if(read_ptr == write_ptr) begin
                empty <= 1'b1;
            end
            full <= 1'b0;
        end
    end
end

endmodule

