module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    output reg [3:0] S,
    output reg C_OUT
);

reg [3:0] C;

always @(*) begin
    S = A + B + C;
    C_OUT = (S[3] == 1) ? 1 : 0;
end

// Ripple carry logic
integer i;
always @(*) begin
    C[0] = 0;
    for (i = 1; i < 4; i = i + 1) begin
        C[i] = (A[i-1] & B[i-1]) | (A[i-1] & C[i-1]) | (B[i-1] & C[i-1]);
    end
end

endmodule

module binary_division (
    input [15:0] dividend,
    input [15:0] divisor,
    output reg [15:0] quotient
);

reg [15:0] remainder;
reg [3:0] count;

always @ (posedge clk) begin
    remainder <= dividend;
    quotient <= 0;
    count <= 0;
    while (count < 16) begin
        remainder <= remainder << 1;
        remainder[0] <= 1;
        remainder = remainder - divisor;
        if (remainder[15] == 0) begin
            quotient[count] <= 1;
        end else begin
            remainder = remainder + divisor;
        end
        count <= count + 1;
    end
end

endmodule

