module fft (
    input [7:0] X_real [7:0],
    input [7:0] X_imag [7:0],
    output reg [7:0] Y_real [7:0],
    output reg [7:0] Y_imag [7:0]
);

    // Declare local variables
    reg [7:0] W_real [7:0];
    reg [7:0] W_imag [7:0];
    reg [7:0] temp_real [7:0];
    reg [7:0] temp_imag [7:0];
    reg [7:0] X_real_temp [7:0];
    reg [7:0] X_imag_temp [7:0];
    reg [2:0] stage [2:0];
    reg [2:0] i [2:0];
    reg [2:0] j [2:0];
    reg [2:0] k [2:0];

    // Initialize variables
    initial begin
        W_real[0] = 1;
        W_imag[0] = 0;
        for (i[0] = 1; i[0] < 8; i[0] = i[0] + 1) begin
            W_real[i[0]] = W_real[i[0] - 1] * cos(2 * $pi * i[0] / 8) - W_imag[i[0] - 1] * sin(2 * $pi * i[0] / 8);
            W_imag[i[0]] = W_imag[i[0] - 1] * cos(2 * $pi * i[0] / 8) + W_real[i[0] - 1] * sin(2 * $pi * i[0] / 8);
        end
    end

    // Perform radix-2 FFT
    always @(*) begin
        stage[2:0] = 0;
        for (i[2:0] = 0; i[2:0] < 3; i[2:0] = i[2:0] + 1) begin
            stage[i[2:0]] = i[2:0];
            for (j[i[2:0]] = 0; j[i[2:0]] < 2 ** i[2:0]; j[i[2:0]] = j[i[2:0]] + 1) begin
                for (k[i[2:0]] = 0; k[i[2:0]] < 2 ** (2 - i[2:0]); k[i[2:0]] = k[i[2:0]] + 1) begin
                    X_real_temp[0] = X_real[j[i[2:0]] * 2 ** (2 - i[2:0]) + k[i[2:0]]];
                    X_imag_temp[0] = X_imag[j[i[2:0]] * 2 ** (2 - i[2:0]) + k[i[2:0]]];
                    X_real_temp[1] = X_real[j[i[2:0]] * 2 ** (2 - i[2:0]) + k[i[2:0]] + 2 ** (1 - i[2:0])];
                    X_imag_temp[1] = X_imag[j[i[2:0]] * 2 ** (2 - i[2:0]) + k[i[2:0]] + 2 ** (1 - i[2:0])];
                    temp_real[0] = X_real_temp[0] + X_real_temp[1];
                    temp_imag[0] = X_imag_temp[0] + X_imag_temp[1];
                    temp_real[1] = X_real_temp[0] - X_real_temp[1];
                    temp_imag[1] = X_imag_temp[0] - X_imag_temp[1];
                    Y_real[j[i[2:0]] * 2 ** (2 - i[2:0]) + k[i[2:0]]] = temp_real[0];
                    Y_imag[j[i[2:0]] * 2 ** (2 - i[2:0]) + k[i[2:0]]] = temp_imag[0];
                    Y_real[j[i[2:0]] * 2 ** (2 - i[2:0]) + k[i[2:0]] + 2 ** (1 - i[2:0])] = temp_real[1] * W_real[j[i[2:0]] * 2 ** (2 - i[2:0]) + k[i[2:0]] * 2 ** i[2:0]];
                    Y_imag[j[i[2:0]] * 2 ** (2 - i[2:0]) + k[i[2:0]] + 2 ** (1 - i[2:0])] = temp_imag[1] * W_imag[j[i[2:0]] * 2 ** (2 - i[2:0]) + k[i[2:0]] * 2 ** i[2:0]];
                end
            end
        end
    end

endmodule

