if (!rst_n)
    state <= 2'b0;
else begin
    case (state)
        2'd0 : if (neq) state <= 2'd1;
        2'd1 : if ( eq) state <= 2'd2;
        2'd2 : if ( eq) state <= 2'd3; else state <= 2'd1;
        2'd3 : state <= 2'd0;
    endcase
end

//
