module triangle_wave(
  input clk, reset,
  input [15:0] freq,
  input [7:0] duty,
  input enable,
  input [15:0] sample_clk,
  output reg [9:0] triangle,
  output reg sampled
);

  reg [31:0] counter;
  reg [15:0] sample_counter;
  reg [15:0] half_period;
  reg [15:0] sample_half_period;
  reg [9:0] triangle_half_period;
  reg [9:0] triangle_increment;
  reg [7:0] duty_cycle;
  reg direction;

  always @(posedge clk) begin
    if (reset) begin
      counter <= 0;
      sample_counter <= 0;
      half_period <= 0;
      sample_half_period <= 0;
      triangle_half_period <= 0;
      triangle_increment <= 0;
      duty_cycle <= 0;
      direction <= 0;
      sampled <= 0;
      triangle <= 0;
    end else begin
      if (enable) begin
        // calculate the number of clock cycles per half period
        half_period <= (freq == 0) ? 0 : (50000000 / freq);
        sample_half_period <= (sample_clk == 0) ? 0 : (50000000 / sample_clk);
        triangle_half_period <= half_period >> 1;
        triangle_increment <= 1023 * (half_period / (100.0 * sample_half_period));
        duty_cycle <= (duty * half_period) / 256;
        if (counter == 0) begin
          direction <= ~direction;
          counter <= half_period - 1;
        end else begin
          counter <= counter - 1;
        end
        if (sample_counter == 0) begin
          sampled <= 1;
          sample_counter <= sample_half_period - 1;
        end else begin
          sampled <= 0;
          sample_counter <= sample_counter - 1;
        end
        if (direction) begin
          if (triangle <= 0) begin
            triangle <= 0;
          end else begin
            triangle <= triangle - triangle_increment;
          end
        end else begin
          if (triangle >= 1023) begin
            triangle <= 1023;
          end else begin
            triangle <= triangle + triangle_increment;
          end
        end
      end else begin
        counter <= 0;
        sample_counter <= 0;
        half_period <= 0;
        sample_half_period <= 0;
        triangle_half_period <= 0;
        triangle_increment <= 0;
        duty_cycle <= 0;
        direction <= 0;
        sampled <= 0;
        triangle <= 0;
      end
    end
  end

endmodule

