module interrupt_controller (
  input [n-1:0] int,
  input reset,
  input clk,
  output req,
  output ack,
  output [7:0] vector
);

parameter n = 8; // number of interrupt sources

reg [n-1:0] priority;
reg [n-1:0] pending;
reg [n-1:0] serviced;
reg [7:0] vector_reg;

always @(posedge clk) begin
  if (reset) begin
    priority <= 0;
    pending <= 0;
    serviced <= 0;
    vector_reg <= 0;
  end else begin
    priority <= {priority[n-2:0], priority[n-1]};
    pending <= (int & ~serviced) | (pending & ~int);
    serviced <= (ack & serviced) | (req & ~priority & pending);
    vector_reg <= {vector_reg[6:0], int};
  end
end

assign req = pending != 0;
assign ack = req & ~priority & ~vector_reg[7];
assign vector = vector_reg;

endmodule

