    generate
        for (i = 0; i < 32; i = i + 1) begin : level_0_gen
            assign level_0[i] = {in[4*i+3], in[4*i+2], in[4*i+1], in[4*i]} 
                                ? sel[7:6] == 2'b00 
                                : sel[7:6] == 2'b01 
                                ? {in[4*i+7], in[4*i+6], in[4*i+5], in[4*i+4]} 
                                : sel[7:6] == 2'b10 
                                ? {in[4*i+11], in[4*i+10], in[4*i+9], in[4*i+8]} 
                                : {in[4*i+15], in[4*i+14], in[4*i+13], in[4*i+12]};
        end
    endgenerate

    // Second level of multiplexers
    generate
        for (i = 0; i < 32; i = i + 1) begin : level_1_gen
            assign level_1[i] = {level_0[2*i+1], level_0[2*i]} 
                                ? sel[5] == 1'b0 
                                : {level_0[2*i+3], level_0[2*i+2]};
        end
    endgenerate

    // Third level of multiplexers
    generate
        for (i = 0; i < 32; i = i + 1) begin : level_2_gen
            assign level_2[i] = {level_1[2*i+1], level_1[2*i]} 
                                ? sel[4] == 1'b0 
                                : {level_1[2*i+3], level_1[2*i+2]};
        end
    endgenerate

    // Fourth level of multiplexers
    generate
        for (i = 0; i < 32; i = i + 1) begin : level_3_gen
            assign level_3[i] = {level_2[2*i+1], level_2[2*i]} 
                                ? sel[3] == 1'b0 
                                : {level_2[2*i+3], level_2[2*i+2]};
        end
    endgenerate

    // Fifth level of multiplexers
    generate
        for (i = 0; i < 32; i = i + 1) begin : level_4_gen
            assign level_4[i] = {level_3[2*i+1], level_3[2*i]} 
                                ? sel[2] == 1'b0 
                                : {level_3[2*i+3], level_3[2*i+2]};
        end
    endgenerate

    // Sixth level of multiplexers
    generate
        for (i = 0; i < 32; i = i + 1) begin : level_5_gen
            assign level_5[i] = {level_4[2*i+1], level_4[2*i]} 
                                ? sel[1] == 1'b0 
                                : {level_4[2*i+3], level_4[2*i+2]};
        end
    endgenerate

    // Seventh level of multiplexers
    generate
        for (i = 0; i < 32; i = i + 1) begin : level_6_gen
            assign level_6[i] = {level_5[2*i+1], level_5[2*i]} 
                                ? sel[0] == 1'b0 
                                : {level_5[2*i+3], level_5[2*i+2]};
        end
    endgenerate

    // Final output
    assign out = level_6[0];

endmodule

