module act_led(
       clk,
       reset,
       gmii_rxen,
       gmii_txen,
       r_act_sfp
    );

    input clk;
    input reset;
    input gmii_rxen;
    input gmii_txen;
    output r_act_sfp;

    reg [23:0] count_led;
    reg r_act_sfp;
    reg [1:0] current_state;
    parameter idle = 2'b0,
              first = 2'b01,
              second = 2'b10;

    always@(posedge clk or negedge reset) begin
        if(!reset) begin
            count_led <= 24'b0;
            r_act_sfp <= 1'b1;
            current_state <= idle;
        end else begin
            case(current_state)
                idle:
                    begin
                        count_led <= 24'b0;
                        if(gmii_rxen || gmii_txen) begin
                            r_act_sfp <= 1'b0;
                            current_state <= first;
                        end else begin
                            r_act_sfp <= 1'b1;
                            current_state <= idle;
                        end
                    end
                first:
                    begin
                        count_led <= count_led + 1'b1;
                        if(count_led == 24'd24) begin
                            r_act_sfp <= 1'b1;
                            count_led <= 24'b0;
                            current_state <= second;
                        end else begin
                            r_act_sfp <= 1'b0;
                            current_state <= first;
                        end
                    end
                second:
                    begin
                        count_led <= count_led + 1'b1;
                        if(count_led == 24'd12) begin
                            current_state <= idle;
                        end else begin
                            current_state <= second;
                        end
                    end
                default:
                    begin
                        current_state <= idle;
                    end
            endcase
        end
    end

endmodule

module top_module (
    input CLK,
    input RST,
    input UP,
    input enable,
    output reg [3:0] OUT
);

reg [3:0] counter_out;
wire [1:0] encoder_pos;
wire [3:0] functional_in1;
wire [1:0] functional_in2;

up_down_counter_4bit counter (
    .CLK(CLK),
    .RST(RST),
    .UP(UP),
    .OUT(counter_out)
);

priority_encoder encoder (
    .in(counter_out),
    .enable(enable),
    .pos(encoder_pos)
);

functional_module functional (
    .in1(counter_out),
    .in2(encoder_pos),
    .out(functional_in1)
);

always @(*) begin
    if (enable) begin
        OUT = functional_in1;
    end else begin
        OUT = counter_out;
    end
end

endmodule

module up_down_counter_4bit (
    input CLK,
    input RST,
    input UP,
    output reg [3:0] OUT
);

always @(posedge CLK, negedge RST) begin
    if (!RST) begin
        OUT <= 4'b0000;
    end else if (UP) begin
        OUT <= OUT + 1;
    end else begin
        OUT <= OUT - 1;
    end
end

endmodule

module priority_encoder (
    input [3:0] in,
    input enable,
    output reg [1:0] pos
);

always @(*) begin
    if (!enable) begin
        pos <= 2'b00;
    end else if (in[3]) begin
        pos <= 2'b11;
    end else if (in[2]) begin
        pos <= 2'b10;
    end else if (in[1]) begin
        pos <= 2'b01;
    end else if (in[0]) begin
        pos <= 2'b00;
    end else begin
        pos <= 2'b00;
    end
end

endmodule

