module selector ( pm0, pm1, pm2, pm3, d0, d1 );
  input [3:0] pm0;
  input [3:0] pm1;
  input [3:0] pm2;
  input [3:0] pm3;
  output d0, d1;
  wire   n1, n2, n3, n4, n5, n6, n7, n8, n9, n10, n11, n12, n13, n14, n15, n16,
         n17, n18, n19, n20, n21, n22, n23, n24, n25, n26, n27, n28, n29, n30,
         n31, n32, n33, n34, n35, n36, n37, n38, n39, n40, n41, n42, n43, n44,
         n45, n46, n47, n48, n49, n50, n51;

  // First, implement the logic for d0
  // The AND gate takes as input the output of two NOR gates
  // Each NOR gate takes as input two of the four input bits
  NOR2X1 U1 (.A(pm0[0]), .B(pm0[1]), .Y(n1));
  NOR2X1 U2 (.A(pm0[2]), .B(pm0[3]), .Y(n2));
  NOR2X1 U3 (.A(pm1[0]), .B(pm1[1]), .Y(n3));
  NOR2X1 U4 (.A(pm1[2]), .B(pm1[3]), .Y(n4));
  AND2X1 U5 (.A(n1), .B(n2), .Y(n5));
  AND2X1 U6 (.A(n3), .B(n4), .Y(n6));
  // The output of the AND gate is used as input to the 2-to-1 multiplexer
  MUX2X1 U7 (.A(n5), .B(n6), .S(d1), .Y(n7));
  // The output of the 2-to-1 multiplexer is inverted to produce d0
  INVX1 U8 (.A(n7), .Y(d0));

  // Next, implement the logic for d1
  // The AND gate takes as input the output of two NAND gates
  // Each NAND gate takes as input two of the four input bits
  NAND2X1 U9 (.A(pm2[0]), .B(pm2[1]), .Y(n8));
  NAND2X1 U10 (.A(pm2[2]), .B(pm2[3]), .Y(n9));
  NAND2X1 U11 (.A(pm3[0]), .B(pm3[1]), .Y(n10));
  NAND2X1 U12 (.A(pm3[2]), .B(pm3[3]), .Y(n11));
  AND2X1 U13 (.A(n8), .B(n9), .Y(n12));
  AND2X1 U14 (.A(n10), .B(n11), .Y(n13));
  // The output of the AND gate is used as input to the 2-to-1 multiplexer
  MUX2X1 U15 (.A(n12), .B(n13), .S(d1), .Y(n14));
  // The output of the 2-to-1 multiplexer is used as input to the OR gate
  // The AOI gate takes as input three of the four input bits
  AOI21X1 U16 (.A(pm0[0]), .B(pm1[0]), .C(pm2[0]), .Y(n15));
  AOI21X1 U17 (.A(pm0[1]), .B(pm1[1]), .C(pm2[1]), .Y(n16));
  AOI21X1 U18 (.A(pm0[2]), .B(pm1[2]), .C(pm2[2]), .Y(n17));
  AOI21X1 U19 (.A(pm0[3]), .B(pm1[3]), .C(pm2[3]), .Y(n18));
  OR2X1 U20 (.A(n15), .B(n16), .Y(n19));
  OR2X1 U21 (.A(n17), .B(n18), .Y(n20));
  OR2X1 U22 (.A(n19), .B(n20), .Y(n21));
  // The output of the AOI gate is inverted to produce d1
  INVX1 U23 (.A(n14), .Y(n22));
  OR2X1 U24 (.A(n21), .B(n22), .Y(d1));

  // Note: the remaining gates in the original code snippet are not used in the implementation above

endmodule

module top_module (
    input clk,
    input reset,   // Synchronous active-high reset
    input [31:0] in, // Input for byte ordering reversal module
    output [15:0] q, // Output for BCD counter
    output [31:0] out, // Output for byte ordering reversal module
    output [3:1] ena // Enable signals for digits [3:1]
);

    // BCD Counter
    wire [15:0] binary_out;
    wire [3:1] ena_bcd;
    bcd_counter bcd_counter_inst (
        .clk(clk),
        .reset(reset),
        .binary_out(binary_out),
        .ena(ena_bcd)
    );

    // Byte Ordering Reversal Module
    wire [31:0] out_bor;
    byte_order_reversal byte_order_reversal_inst (
        .in(in),
        .out(out_bor)
    );

    // Enable Signals for Digits [3:1]
    wire [3:1] ena_priority;
    priority_encoder priority_encoder_inst (
        .in(ena_bcd),
        .out(ena_priority)
    );

    // Output Mux
    assign q = ena_bcd ? binary_out[15:0] : 16'b0;
    assign out = ena_priority[2:0] ? out_bor : 32'b0;
    assign ena = ena_priority[2:0];

endmodule

module bcd_counter (
    input clk,
    input reset,   // Synchronous active-high reset
    output reg [15:0] binary_out, // Binary output
    output reg [3:1] ena // Enable signals for digits [3:1]
);

    reg [3:0] bcd_out;
    reg [3:0] bcd_out_next;
    wire [3:0] bcd_in;
    assign bcd_in = binary_out[3:0];

    // Binary to BCD Converter
    bcd_converter bcd_converter_inst (
        .binary_in(bcd_in),
        .bcd_out(bcd_out_next)
    );

    always @(posedge clk) begin
        if (reset) begin
            binary_out <= 16'b0;
            bcd_out <= 4'b0;
            ena <= 3'b0;
        end else begin
            binary_out <= binary_out + 1;
            bcd_out <= bcd_out_next;
            ena <= {3{1'b1}};
        end
    end

endmodule

module bcd_converter (
    input [3:0] binary_in,
    output reg [3:0] bcd_out
);

    always @(*) begin
        case (binary_in)
            4'b0000: bcd_out = 4'b0000;
            4'b0001: bcd_out = 4'b0001;
            4'b0010: bcd_out = 4'b0010;
            4'b0011: bcd_out = 4'b0011;
