module adder_subtractor (
    input [3:0] A,
    input [3:0] B,
    input SUB,
    output reg [3:0] SUM,
    output reg CARRY
);

reg [3:0] A_reg, B_reg, SUM_reg;
reg SUB_reg;

always @(posedge clk) begin
    A_reg <= A;
    B_reg <= B;
    SUB_reg <= SUB;
end

always @(posedge clk) begin
    if (SUB_reg) begin
        SUM_reg <= A_reg - B_reg;
        CARRY <= (A_reg < B_reg);
    end else begin
        SUM_reg <= A_reg + B_reg;
        CARRY <= (SUM_reg < A_reg);
    end
end

always @(posedge clk) begin
    SUM <= SUM_reg;
end

endmodule

