module add_sub (
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] result
);

    wire [31:0] sum;
    wire [31:0] diff;
    wire [31:0] select;

    assign select = sub ? ~b : b;

    carry_select_adder adder (
        .a(a),
        .b(select),
        .sum(sum),
        .cout(),
        .sel()
    );

    assign diff = sub ? ~select : select;

    assign result = sub ? diff : sum;

