module transition_detector (
    input clk,
    input reset,
    input [31:0] in,
    output reg out
);

    reg [31:0] prev;

    always @(posedge clk) begin
        if (reset) begin
            prev <= 0;
            out <= 0;
        end
        else begin
            if (in[0] == 1 && prev[0] == 0) begin
                out <= 1;
            end
            else if (in[0] == 0 && prev[0] == 1) begin
                out <= 0;
            end
            prev <= in;
        end
    end

endmodule

