module carry_select_adder (
    input [7:0] A,
    input [7:0] B,
    input [7:0] CIN,
    output reg [15:0] SUM,
    output reg COUT
);

    wire [7:0] P, G;

    assign P = A ^ B;
    assign G = A & B;

    assign SUM[0] = P[0] ^ CIN;
    assign COUT = G[0] | (P[0] & CIN);

    genvar i;

    generate
        for (i = 1; i < 8; i = i + 1) begin
            assign SUM[i] = P[i] ^ G[i-1] ^ CIN;
            assign COUT = (G[i-1] & P[i]) | (CIN & (G[i-1] | P[i]));
        end
    endgenerate

    assign SUM[8] = P[8] ^ G[7] ^ CIN;

endmodule

module top_module (
