    reg [7:0] CIN;

    binary_multiplier binary_mult(
        .A(A),
        .B(B),
        .product(binary_product)
    );

    carry_select_adder carry_add(
        .A(binary_product),
        .B(binary_product),
        .CIN(CIN),
        .SUM(adder_product),
        .COUT()
    );

