module BallGame(
    input clock,
    input reset,
    input actualizar_posicion,
    input revisar_bordes,
    input choque_barra,
    output reg [9:0] ball_x,
    output reg [8:0] ball_y
);

    reg dir_x_positiva;
    reg dir_y_positiva;

    // Constants
    localparam X_INICIAL_BOLA = 10;
    localparam Y_INICIAL_BOLA = 100;
    localparam VELOCIDAD_BOLA = 2;
    localparam LIMITE_DER_X_BOLA = 500;
    localparam LIMITE_SUP_Y_BOLA = 10;
    localparam LIMITE_INF_Y_BOLA = 240;
    localparam X_INICIAL_BARRA = 10;
    localparam ANCHO_BARRA = 20;

    // Initial values
    initial begin
        dir_x_positiva <= 1'b1;
        dir_y_positiva <= 1'b1;
        ball_x <= X_INICIAL_BOLA;
        ball_y <= Y_INICIAL_BOLA;
    end

    always @(posedge clock or posedge reset) begin
        if (reset) begin
            dir_x_positiva <= 1'b1;
            dir_y_positiva <= 1'b1;
            ball_x <= X_INICIAL_BOLA;
            ball_y <= Y_INICIAL_BOLA;
        end else begin
            if (actualizar_posicion) begin
                if (dir_x_positiva) begin
                    ball_x <= ball_x + VELOCIDAD_BOLA; // Move right
                end else begin
                    ball_x <= ball_x - VELOCIDAD_BOLA; // Move left
                end

                if (dir_y_positiva) begin
                    ball_y <= ball_y + VELOCIDAD_BOLA; // Move down
                end else begin
                    ball_y <= ball_y - VELOCIDAD_BOLA; // Move up
                end
            end

            if (revisar_bordes) begin
                if (ball_x > LIMITE_DER_X_BOLA) begin
                    ball_x <= LIMITE_DER_X_BOLA;
                    dir_x_positiva <= 1'b0; // Bounce left
                end else if (ball_x < X_INICIAL_BARRA + ANCHO_BARRA && ball_y >= 70 && ball_y <= 170 && choque_barra) begin
                    ball_x <= X_INICIAL_BARRA + ANCHO_BARRA;
                    dir_x_positiva <= 1'b1; // Bounce right
                end

                if (ball_y < LIMITE_SUP_Y_BOLA) begin
                    ball_y <= LIMITE_SUP_Y_BOLA;
                    dir_y_positiva <= 1'b1; // Bounce down
                end else if (ball_y > LIMITE_INF_Y_BOLA) begin
                    ball_y <= LIMITE_INF_Y_BOLA;
                    dir_y_positiva <= 1'b0; // Bounce up
                end
            end
        end
    end
endmodule

