      q <= 4'b0000;
    end else if (load) begin
      q <= data;
    end else begin
      case (shift_dir)
        2'b00: q <= q;
        2'b01: q <= {q[2:0], q[3]};
        2'b10: q <= {q[1:3], q[0]};
        2'b11: begin
          q[0] <= q[3];
          q[1] <= q[0];
          q[2] <= q[1];
          q[3] <= q[2];
        end
      endcase
    end
  end

