        input [143:0] hex_initval;
        reg done;
        reg [63:0] temp;
        reg [7:0] char;
        integer i;
        begin
            done = 1'b0;
            temp = 0;
            for (i = 0; i < 16; i = i + 1) begin
                if (!done) begin
                    char = hex_initval[8*i +: 8];
                    if (char == "x") begin
                        done = 1'b1;
