module binary_multiplier (
    input [3:0] A,
    input [3:0] B,
    output reg [7:0] P
);

reg [3:0] A_reg;
reg [3:0] B_reg;
reg [3:0] P_reg1;
reg [3:0] P_reg2;

always @(A, B) begin
    A_reg <= A;
    B_reg <= B;
end

// Pipeline stage 1
always @(posedge clk) begin
    P_reg1 <= A_reg[0] ? B_reg : 4'b0;
end

// Pipeline stage 2
always @(posedge clk) begin
    P_reg2 <= {P_reg1[2:0], 1'b0} + (A_reg[1] ? {B_reg, 2'b0} : 4'b0);
end

// Pipeline stage 3
always @(posedge clk) begin
    P <= {P_reg2[2:0], 1'b0} + (A_reg[2] ? {B_reg, 3'b0} : 4'b0);
end

endmodule

module nor3_module(
    input a,
    input b,
    input c,
    output y
);

    wire not_a, not_b, not_c, and1, and2, or1;

    // Invert inputs
    not(not_a, a);
    not(not_b, b);
    not(not_c, c);

    // AND gates
    and(and1, not_a, not_b);
    and(and2, not_c, and1);

    // OR gate
    or(or1, and2, and2, and2);

    // Invert output
    not(y, or1);

endmodule

