module usb_crossbar(
    input c,
    input [15:0] sel,
    input [39:0] d,
    input [4:0] dv,
    output [31:0] q,
    output [3:0] qv
);

    wire [31:0] dmux_z;
    wire [3:0] dvmux_z;

    // USB data demultiplexing
    gmux #(.DWIDTH(8), .SELWIDTH(3)) dmux0(.d({24'h0, d}), .sel(sel[2:0]), .z(dmux_z[7:0]));
    gmux #(.DWIDTH(8), .SELWIDTH(3)) dmux1(.d({24'h0, d}), .sel(sel[6:4]), .z(dmux_z[15:8]));
    gmux #(.DWIDTH(8), .SELWIDTH(3)) dmux2(.d({24'h0, d}), .sel(sel[10:8]), .z(dmux_z[23:16]));
    gmux #(.DWIDTH(8), .SELWIDTH(3)) dmux3(.d({24'h0, d}), .sel(sel[14:12]), .z(dmux_z[31:24]));

    // USB data-valid demultiplexing
    gmux #(.DWIDTH(1), .SELWIDTH(3)) dvmux0(.d({3'h0, dv}), .sel(sel[2:0]), .z(dvmux_z[0]));
    gmux #(.DWIDTH(1), .SELWIDTH(3)) dvmux1(.d({3'h0, dv}), .sel(sel[6:4]), .z(dvmux_z[1]));
    gmux #(.DWIDTH(1), .SELWIDTH(3)) dvmux2(.d({3'h0, dv}), .sel(sel[10:8]), .z(dvmux_z[2]));
    gmux #(.DWIDTH(1), .SELWIDTH(3)) dvmux3(.d({3'h0, dv}), .sel(sel[14:12]), .z(dvmux_z[3]));

    // Output data to parsers
    d1 #(32) q_d1_r(.c(c), .d(dmux_z), .q(q));

    // Output data-valids to parsers
    d1 #(4) qv_d1_r(.c(c), .d(dvmux_z),. q(qv));

endmodule

module spi_slave(
    input clk,
    input rst,
    input ss,
    input mosi,
    output miso,
    input sck,
    output done,
    input [7:0] din,
    input din_update,
    output [7:0] dout
    );

reg mosi_d, mosi_q;
reg ss_d, ss_q;
reg sck_d, sck_q;
reg sck_old_d, sck_old_q;
reg [7:0] data_d, data_q;
reg done_d, done_q;
reg [2:0] bit_ct_d, bit_ct_q;
reg [7:0] dout_d, dout_q;
reg miso_d, miso_q;

assign miso = miso_q;
assign done = done_q;
assign dout = dout_q;

always @(*) begin
    ss_d = ss;
    mosi_d = mosi;
    miso_d = miso_q;
    sck_d = sck;
    sck_old_d = sck_q;
    data_d = data_q;
    done_d = 1'b0;
    bit_ct_d = bit_ct_q;
    dout_d = dout_q;

    if (ss_q) begin
        bit_ct_d = 3'b0;
        data_d = din;
        miso_d = data_q[7];
    end else begin
        if (!sck_old_q && sck_q) begin // rising edge
            miso_d = data_q[7];
            data_d = {data_q[6:0], mosi_q};
            bit_ct_d = bit_ct_q + 1'b1;
            if (bit_ct_q == 3'b111) begin
                dout_d = {data_q[6:0], mosi_q};
                done_d = 1'b1;
                data_d = din;
            end
        end else if (din_update) begin
            data_d = din;
        end
    end
end

always @(posedge clk) begin
    if (rst) begin
        done_q <= 1'b0;
        bit_ct_q <= 3'b0;
        dout_q <= 8'b0;
        miso_q <= 1'b1;
    end else begin
        done_q <= done_d;
        bit_ct_q <= bit_ct_d;
        dout_q <= dout_d;
        miso_q <= miso_d;
    end

    sck_q <= sck_d;
    mosi_q <= mosi_d;
    ss_q <= ss_d;
    data_q <= data_d;
    sck_old_q <= sck_old_d;

end

endmodule

module keypad_left_shift (
    input clk,
    input [3:0] col,
    output reg [7:0] out
);

    reg [3:0] row;
    reg [3:0] key_pressed;
    reg [3:0] shifted_key_pressed;

    // 4x4 matrix keypad scanner
    always @(posedge clk) begin
        row <= 4'b1110;
        if (col == 4'b1110) key_pressed <= 4'b0001;
        else if (col == 4'b1101) key_pressed <= 4'b0010;
        else if (col == 4'b1011) key_pressed <= 4'b0100;
        else if (col == 4'b0111) key_pressed <= 4'b1000;
        else key_pressed <= 4'b0000;
    end

    // 4-bit binary left shift module
    always @(posedge clk) begin
        shifted_key_pressed[3:1] <= key_pressed[2:0];
        shifted_key_pressed[0] <= key_pressed[3];
    end

    // Concatenate the output from the keypad scanner and the left shift module
    always @(posedge clk) begin
        out <= {shifted_key_pressed, key_pressed};
    end

endmodule

module pipelined_module (
    input clk,
    input rst_n,
    input [7:0] d,
    output reg [7:0] q
);

reg [2:0] counter;
reg [7:0] pipeline_reg [0:7];

always @(posedge clk, negedge rst_n) begin
    if (!rst_n) begin
        counter <= 0;
        pipeline_reg <= 0;
    end else begin
        if (counter == 7) begin
            pipeline_reg <= 0;
            counter <= 0;
        end else begin
            pipeline_reg[counter+1] <= pipeline_reg[counter];
            counter <= counter + 1;
        end
        pipeline_reg[0] <= d;
    end
end

always @(posedge clk, negedge rst_n) begin
    if (!rst_n) begin
        q <= 0;
    end else begin
        q <= pipeline_reg[7];
    end
end

endmodule
