module HMAC (
  input [n-1:0] in,
  input [k-1:0] key,
  input [h-1:0] hmac,
  output auth
);

parameter n = 512; // number of bits in the message
parameter k = 256; // number of bits in the secret key
parameter h = 256; // number of bits in the HMAC
parameter b = 512; // number of bits in each block of the hash function

reg [511:0] padded_message;
reg [511:0] opad;
reg [511:0] ipad;
reg [511:0] key_padded;
reg [511:0] outer_hash_input;
reg [255:0] inner_hash_output;
reg [255:0] outer_hash_output;
reg [255:0] computed_hmac;

// Padding the message
always @* begin
  padded_message = {in, {1'b1, {(n+896)%1024}}};
end

// Padding the key
always @* begin
  if (k > b) begin
    key_padded = SHA256(key);
  end else if (k < b) begin
    key_padded = {key, {1'b0, b-k-1}};
  end else begin
    key_padded = key;
  end
end

// Generating the inner and outer padding
always @* begin
  opad = {256{8'h5c}};
  ipad = {256{8'h36}};
end

// Generating the outer hash input
always @* begin
  outer_hash_input = {opad ^ key_padded, SHA256({ipad ^ key_padded, padded_message})};
end

// Computing the HMAC
always @* begin
  inner_hash_output = SHA256({ipad ^ key_padded, padded_message});
  outer_hash_output = SHA256(outer_hash_input);
  computed_hmac = outer_hash_output;
end

// Checking the HMAC
always @* begin
  if (computed_hmac == hmac) begin
    auth = 1'b1;
  end else begin
    auth = 1'b0;
  end
end

endmodule

