// Carry look-ahead adder module
module gen_carry_lookahead (g, p, c, a, b);
    input [99:0] a, b;
    output [100:0] g, p, c;
    wire [99:0] a_xor_b, a_and_b;
    assign a_xor_b = a ^ b;
    assign a_and_b = a & b;

    // Generate the first carry signal
    assign g[1] = a_xor_b[0];
    assign p[1] = a_and_b[0];
    assign c[1] = g[1] | (p[1] & c[0]);

    // Generate the rest of the carry signals
    gen_carry_lookahead_helper helper(g, p, c, a_xor_b, a_and_b);

endmodule

// Helper module for carry look-ahead adder
module gen_carry_lookahead_helper (g, p, c, a_xor_b, a_and_b);
    input [99:0] a_xor_b, a_and_b;
    output [100:0] g, p, c;
    wire [100:0] g_temp, p_temp, c_temp;
    assign g_temp[0] = 1'b0;
    assign p_temp[0] = 1'b1;
    assign c_temp[0] = 1'b0;

    // Generate the rest of the carry signals
    gen_carry_lookahead_helper_loop loop(g_temp, p_temp, c_temp, a_xor_b, a_and_b);

    // Assign the final values to g, p, and c
    assign g = g_temp;
    assign p = p_temp;
    assign c = c_temp;

endmodule

// Loop module for helper module of carry look-ahead adder
module gen_carry_lookahead_helper_loop (g, p, c, a_xor_b, a_and_b);
    input [99:0] a_xor_b, a_and_b;
    output [100:0] g, p, c;
    wire [100:0] g_temp, p_temp, c_temp;
    assign g_temp[0] = 1'b0;
    assign p_temp[0] = 1'b1;
    assign c_temp[0] = 1'b0;

    // Generate the rest of the carry signals
    gen_carry_lookahead_helper_loop_iter iter(g_temp, p_temp, c_temp, a_xor_b, a_and_b, 2);

    // Assign the final values to g, p, and c
    assign g = g_temp;
    assign p = p_temp;
    assign c = c_temp;

endmodule

// Iteration module for loop module of helper module of carry look-ahead adder
module gen_carry_lookahead_helper_loop_iter (g, p, c, a_xor_b, a_and_b, i);
    input [99:0] a_xor_b, a_and_b;
    output [100:0] g, p, c;
    wire [100:0] g_temp, p_temp, c_temp;
    parameter MAX_ITER = 100;
    assign g_temp[0] = 1'b0;
    assign p_temp[0] = 1'b1;
    assign c_temp[0] = 1'b0;

    // Generate the carry signals for this iteration
    assign g_temp[i] = a_xor_b[i-1] & g[i-1];
    assign p_temp[i] = a_xor_b[i-1] ^ g[i-1];
    assign c_temp[i] = g_temp[i] | (p_temp[i] & c[i-1]);

    // Recursively generate the rest of the carry signals
    gen_carry_lookahead_helper_loop_iter next_iter(g_temp, p_temp, c_temp, a_xor_b, a_and_b, i+1);

    // Assign the final values to g, p, and c
    assign g = g_temp;
    assign p = p_temp;
    assign c = c_temp;

endmodule

module priority_encoder (
    input [7:0] a,
    input [7:0] b,
    input [7:0] c,
    input [7:0] d,
    output reg [1:0] min_index
);

reg [7:0] temp_min;
reg [1:0] temp_index;

always @* begin
    temp_min = 8'hFF;
    temp_index = 2'b00;

    if (a < temp_min) begin
        temp_min = a;
        temp_index = 2'b00;
    end

    if (b < temp_min) begin
        temp_min = b;
        temp_index = 2'b01;
    end

    if (c < temp_min) begin
        temp_min = c;
        temp_index = 2'b10;
    end

    if (d < temp_min) begin
        temp_min = d;
        temp_index = 2'b11;
    end

    min_index = temp_index;
end

endmodule

