module up_down_shift_register_counter (
    input clk,
    input reset, // Synchronous active-high reset
    input [3:0] D, // 4-bit input for parallel loading of register
    input up_down, // Up/down count select input
    input shift, // Shift direction select input
    input select, // Select input to choose between register and counter
    output [3:0] Q // 4-bit output from the active module
);

    reg [3:0] counter; // 4-bit up/down counter
    reg [3:0] register; // 4-bit shift register
    reg active_module; // Register to store the active module
    reg [1:0] shift_count; // Counter to keep track of shift direction and count

    always @(posedge clk) begin
        if (reset) begin
            counter <= 4'b0000;
            register <= 4'b0000;
            active_module <= 1'b0;
            shift_count <= 2'b00;
        end else begin
            // Parallel load
            if (select) begin
                register <= D;
                active_module <= 1'b1;
            end else begin
                counter <= D;
                active_module <= 1'b0;
            end

            // Count up or down
            if (up_down) begin
                counter <= counter + 1;
            end else begin
                counter <= counter - 1;
            end

            // Shift left or right
            if (shift) begin
                if (shift_count == 2'b00) begin
                    register <= {register[2:0], 1'b0};
                end else if (shift_count == 2'b01) begin
                    register <= {register[1:0], counter[3]};
                end else if (shift_count == 2'b10) begin
                    register <= {register[0], counter[3:1]};
                end else begin // shift_count == 2'b11
                    register <= {1'b0, counter[3:2]};
                end
                shift_count <= shift_count + 1;
            end else begin
                if (shift_count == 2'b00) begin
                    register <= {1'b0, register[3:1]};
                end else if (shift_count == 2'b01) begin
                    register <= {counter[0], register[3:1]};
                end else if (shift_count == 2'b10) begin
                    register <= {counter[1:0], register[3]};
                end else begin // shift_count == 2'b11
                    register <= {counter[2:0], register[2]};
                end
                shift_count <= shift_count - 1;
            end

            // Choose active module
            if (select) begin
                Q <= register;
            end else begin
                Q <= counter;
            end
        end
    end

endmodule

