reg [3:0] min_count;
reg [3:0] hr_count;

always @(posedge clk or posedge reset) begin
  if (reset) begin
    sec_count <= 4'b0000;
    min_count <= 4'b0000;
    hr_count <= 4'b0000;
    am_pm <= 1'b0;
  end else if (ena) begin
    sec_count <= sec_count + 1;
    if (sec_count == 10) begin
      sec_count <= 4'b0000;
      min_count <= min_count + 1;
      if (min_count == 10) begin
        min_count <= 4'b0000;
        hr_count <= hr_count + 1;
        if (hr_count == 10) begin
          hr_count <= 4'b0000;
          am_pm <= ~am_pm;
        end else if (hr_count == 8 && am_pm == 1'b0) begin
          hr_count <= 4'b0000;
          am_pm <= 1'b1;
        end else if (hr_count == 2 && am_pm == 1'b1) begin
          hr_count <= 4'b0000;
          am_pm <= 1'b0;
        end
      end
    end
  end
end

