module predictor_2_0 ( clock, reset, enable, taken_i, prediction_o );
  input clock, reset, enable, taken_i;
  output prediction_o;
  wire   N11, N12, n9, n11, n5, n6, n8, n7, n10;
  wire   [1:0] next_STATE;

  // State register 0
  DLH_X1 \next_STATE_reg[0]  ( .G(enable), .D(N11), .Q(next_STATE[0]) );
  DFFR_X1 \STATE_reg[0]  ( .D(n11), .CK(clock), .RN(n10), .Q(n5), .QN(n7) );

  // State register 1
  DLH_X1 \next_STATE_reg[1]  ( .G(enable), .D(N12), .Q(next_STATE[1]) );
  DFFR_X1 \STATE_reg[1]  ( .D(n9), .CK(clock), .RN(n10), .Q(prediction_o) );

  // Multiplexers
  MUX2_X1 U8 ( .A(prediction_o), .B(next_STATE[1]), .S(enable), .Z(n9) );
  MUX2_X1 U9 ( .A(n5), .B(next_STATE[0]), .S(enable), .Z(n11) );

  // Gates
  NOR2_X1 U7 ( .A1(prediction_o), .A2(taken_i), .ZN(n6) );
  NAND2_X1 U6 ( .A1(prediction_o), .A2(taken_i), .ZN(n8) );
  OAI21_X1 U3 ( .B1(n6), .B2(n7), .A(n8), .ZN(N12) );
  OAI21_X1 U5 ( .B1(n5), .B2(n6), .A(n8), .ZN(N11) );
  INV_X1 U2 ( .A(reset), .ZN(n10) );
endmodule

module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout
);

    // Declare local signals
    wire [3:0] FA_sum;
    wire [3:0] FA_carry;

    // Half adder for least significant bit
    xor FA0_xor(Sum[0], A[0], B[0]);
    and FA0_and(Cout, A[0], B[0]);

    // Full adders for remaining bits
    full_adder FA1(.A(A[1]), .B(B[1]), .Cin(Cout), .Sum(FA_sum[1]), .Cout(FA_carry[1]));
    full_adder FA2(.A(A[2]), .B(B[2]), .Cin(FA_carry[1]), .Sum(FA_sum[2]), .Cout(FA_carry[2]));
    full_adder FA3(.A(A[3]), .B(B[3]), .Cin(FA_carry[2]), .Sum(FA_sum[3]), .Cout(FA_carry[3]));

    // Assign final output signals
    assign Sum = FA_sum;
    assign Cout = FA_carry[3];

endmodule

module multiplier_block (
    i_data0,
    o_data0
);

  // Port mode declarations:
  input   [31:0] i_data0;
  output  [31:0]
    o_data0;

  //Multipliers:

  wire [31:0]
    w1,
    w512,
    w511,
    w4,
    w507,
    w4056,
    w4057,
    w32456;

  assign w1 = i_data0;
  assign w512 = w1 << 9;
  assign w511 = w512 - w1;
  assign w4 = w1 << 2;
  assign w507 = w511 - w4;
  assign w4056 = w507 << 3;
  assign w4057 = w1 + w4056;
  assign w32456 = w4057 << 3;

  assign o_data0 = w32456;

  //multiplier_block area estimate = 4833.25917057353;
endmodule

module binary_subtractor(
    input [3:0] a, b,
    output [3:0] diff
);

wire borrow1, borrow2;
wire [2:0] sub1;
wire sub2;

full_subtractor fs1(a[0], b[0], 0, sub1[0], borrow1);
full_subtractor fs2(a[1], b[1], borrow1, sub1[1], borrow2);
full_subtractor fs3(a[2], b[2], borrow2, sub1[2], diff[2]);
mux2to1 mux(sub1[2], ~b[3], borrow2, sub2);
full_subtractor fs4(diff[2], b[3], sub2, diff[3], borrow1);

assign diff[1:0] = sub1[1:0];
assign borrow1 = borrow1;

endmodule

module full_subtractor(
    input a, b, cin,
    output s, bout
);

assign s = ~(a ^ b ^ cin);
assign bout = (~a & b) | (~a & cin) | (b & cin);

endmodule

