module calculator_impl (
  input wire [1:0] op,
  input wire [7:0] a,
  input wire [7:0] b,
  input wire reset,
  output wire [15:0] result
);

  reg [15:0] temp_result;

  always @(posedge reset) begin
    temp_result <= 0;
  end

  always @(*) begin
    case (op)
      2'b00: temp_result = a + b;
      2'b01: temp_result = a - b;
      2'b10: temp_result = a * b;
      2'b11: begin
        if (b == 0) begin
          temp_result = 0;
        end else begin
          temp_result = a / b;
        end
      end
      default: temp_result = 0;
    endcase
  end

  assign result = temp_result;

endmodule

module mux_2to1 (
    A,
    B,
    SEL,
    Y,
    VPWR,
    VGND
);

    input A;
    input B;
    input SEL;
    output Y;
    input VPWR;
    input VGND;

    wire not_sel;
    wire and1_out;
    wire and2_out;

    sky130_fd_sc_lp__not_1 not_gate(
        .A(SEL),
        .X(not_sel),
        .VPWR(VPWR),
        .VGND(VGND)
    );

    sky130_fd_sc_lp__and2_1 and1_gate(
        .A(A),
        .B(not_sel),
        .X(and1_out),
        .VPWR(VPWR),
        .VGND(VGND)
    );

    sky130_fd_sc_lp__and2_1 and2_gate(
        .A(B),
        .B(SEL),
        .X(and2_out),
        .VPWR(VPWR),
        .VGND(VGND)
    );

    assign Y = and1_out | and2_out;

endmodule

module wavelet_transform (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 8; // number of input signals
parameter m = 8; // number of output signals
parameter k = 3; // number of levels of wavelet transform

// Define delay block
reg [n-1:0] delay [0:k-1][0:n-1];

// Define adder and subtractor blocks
reg [n-1:0] add [0:k-1][0:n-1];
reg [n-1:0] sub [0:k-1][0:n-1];

// Connect inputs to delay blocks
assign delay[0] = in;

// Implement wavelet transform
genvar i, j;
generate
  for (i = 0; i < k; i = i + 1) begin
    for (j = 0; j < n/2; j = j + 1) begin
      assign add[i][j] = (delay[i][2*j] + delay[i][2*j+1]) >> 1;
      assign sub[i][j] = (delay[i][2*j] - delay[i][2*j+1]) >> 1;
    end
    assign delay[i+1][0:n/2-1] = add[i][0:n/2-1];
    assign delay[i+1][n/2:n-1] = sub[i][0:n/2-1];
  end
endgenerate

// Connect outputs to final delay block
assign out = delay[k][0:m-1];

endmodule

module spi_slave(
    input clk,
    input rst_n,
    input sck,
    input mosi,
    input ssel,
    output recived_status,
    output reg miso
);

reg [7:0] byte_data_sent;
reg [7:0] next_byte_data_sent;
reg [7:0] bit_cnt;
reg sselr;

wire ssel_active;
wire sck_risingedge;
wire sck_fallingedge;
wire ssel_startmessage;
wire ssel_endmessage;

reg curr, last;
always@(posedge clk)
begin
	if(!rst_n) begin
		curr <= 1'b0;
		last <= 1'b0;
	end
	else begin
    curr <= sck;
    last <= curr;
	end
end

assign sck_risingedge = curr & (~last);
assign sck_fallingedge = ~curr & (last);

always @(posedge clk or negedge rst_n)begin
	if(!rst_n)
		sselr <= 1'h1;
	else
		sselr <= ssel;
end

assign  ssel_active = (~sselr) ? 1'b1 : 1'b0;

always @(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
		byte_data_sent <= 8'h1;
		next_byte_data_sent <= 8'h2;
		bit_cnt <= 8'h0;
	 end
	 else begin
      if(ssel_active && sck_fallingedge) 
		begin
          if(next_byte_data_sent == 8'h41)
               next_byte_data_sent <= 8'h1;
			 if (bit_cnt == 8'h7f)
			   begin
						byte_data_sent <= next_byte_data_sent;
						bit_cnt <= {bit_cnt[6:0], 1'b1};
				 end
			 else
			   byte_data_sent <= {byte_data_sent[6:0], 1'b0};

			 bit_cnt <= {bit_cnt[6:0], 1'b1}; 
		end
		else begin
			if(ssel_active && sck_risingedge) begin
				 /*
				 update the next byte
				 */
				 if(bit_cnt == 8'hff)
				  begin
					 bit_cnt <= 8'h0;
					 next_byte_data_sent <= next_byte_data_sent + 1;
				 end

			end
		end
	end
end

assign miso = byte_data_sent[7];
assign recived_status = (ssel_active && sck_fallingedge) ? 1'b1 : 1'b0;

endmodule

module SHA (
  input [511:0] data_in,
  input start,
  output [511:0] hash_out,
  output done
);

  // Constants and functions used in the SHA algorithm
  parameter WORD_SIZE = 32;
  parameter BLOCK_SIZE = 512;
  parameter HASH_SIZE = 512;
  parameter NUM_ROUNDS = 80;

  function [WORD_SIZE-1:0] ROTR;
    input [WORD_SIZE-1:0] x;
    input [WORD_SIZE-1:0] n;
    begin
      ROTR = {x[n-1:0], x[WORD_SIZE-1:n]};
    end
  endfunction

  function [WORD_SIZE-1:0] CH;
    input [WORD_SIZE-1:0] x;
    input [WORD_SIZE-1:0] y;
    input [WORD_SIZE-1:0] z;
    begin
      CH = (x & y) ^ (~x & z);
    end
  endfunction

  function [WORD_SIZE-1:0] MAJ;
    input [WORD_SIZE-1:0] x;
    input [WORD_SIZE-1:0] y;
    input [WORD_SIZE-1:0] z;
    begin
      MAJ = (x & y) ^ (x & z) ^ (y & z);
    end
  endfunction

  function [WORD_SIZE-1:0] EP0;
    input [WORD_SIZE-1:0] x;
    begin
      EP0 = ROTR(x, 2) ^ ROTR(x, 13) ^ ROTR(x, 22);
    end
  endfunction

  function [WORD_SIZE-1:0] EP1;
    input [WORD_SIZE-1:0] x;
    begin
      EP1 = ROTR(x, 6) ^ ROTR(x, 11) ^ ROTR(x, 25);
    end
  endfunction

  function [WORD_SIZE-1:0] SIG0;
    input [WORD_SIZE-1:0] x;
    begin
      SIG0 = ROTR(x, 7) ^ ROTR(x, 18) ^ (x >> 3);
    end
  endfunction

  function [WORD_SIZE-1:0] SIG1;
    input [WORD_SIZE-1:0] x;
    begin
      SIG1 = ROTR(x, 17) ^ ROTR(x, 19) ^ (x >> 10);
    end
  endfunction

  // Internal signals and variables
  reg [HASH_SIZE-1:0] H[0:7];
  reg [BLOCK_SIZE-1:0] M[0:15];
  reg [WORD_SIZE-1:0] W[0:79];
  reg [WORD_SIZE-1:0] a, b, c, d, e, f, g, h;
  reg [WORD_SIZE-1:0] T1, T2;
  reg [511:0] hash;

  // Message padding
  reg [511:0] padded_data;
  reg [511:0] data_length;
  reg [63:0] data_length_bits;
  reg [7:0] padding_length;

  always @(*) begin
    data_length = $bits(data_in);
    data_length_bits = data_length * 8;
    padding_length = (896 - (data_length_bits + 1)) % 512;
    padded_data = {data_in, 1'b1, {padding_length{1'b0}}, data_length_bits};
  end

  // Message expansion
  always @(*) begin
    for (i = 0; i < 16; i = i + 1) begin
      M[i] = padded_data[i*32 +: 32];
    end

    for (i = 16; i < 80; i = i + 1) begin
      W[i] = SIG1(W[i-2]) + W[i-7] + SIG0(W[i-15]) + W[i-16];
    end
  end

  // Compression
  always @(posedge start) begin
    H[0] = 512'h6a09e667f3bcc908;
    H[1] = 512'hbb67ae8584caa73b;
    H[2] = 512'h3c6ef372fe94f82b;
    H[3] = 512'ha54ff53a5f1d36f1;
    H[4] = 512'h510e527fade682d1;
    H[5] = 512'h9b05688c2b3e6c1f;
    H[6] = 512'h1f83d9abfb41bd6b;
    H[7] = 512'h5be0cd19137e2179;

    for (i = 0; i < 80; i = i + 1) begin
      a = H[0];
      b = H[1];
      c = H[2];
      d = H[3];
      e = H[4];
      f = H[5];
      g = H[6];
      h = H[7];

      T1 = h + EP1(e) + CH(e, f, g) + K[i] + W[i];
      T2 = EP0(a) + MAJ(a, b, c);
      h = g;
      g = f;
      f = e;
      e = d + T1;
      d = c;
      c = b;
      b = a;
      a = T1 + T2;

      H[0] = a;
      H[1] = b;
      H[2] = c;
      H[3] = d;
      H[4] = e;
      H[5] = f;
      H[6] = g;
      H[7] = h;
    end

    hash = {H[0], H[1], H[2], H[3], H[4], H[5], H[6], H[7]};
    hash_out = hash;
    done = 1'b1;
  end

endmodule

