input         clk;
input         clr;
input         ena;
input [6:0]   padder;
input         devpor;
input         devclrn;

output [6:0]  ctrlout;

// internal variables

reg       rin_reg_n;
reg [6:0] counter1;

// pattern detect
reg  pdetect_reg_n;
reg  pdetect_reg_1;
reg  pdetect_reg_2;
wire pdetect_out;

wire pre_adder_reg_n_ena;
reg [6:0]  pre_adder_reg_n;

wire pre_adder_reg_ena;
reg [6:0] pre_adder_reg;

wire [6:0] adder_in;
wire [6:0] adder1; 

// Model
initial
begin
    rin_reg_n = 1'b0;
    counter1 = 7'b1000000;
    pdetect_reg_n = 1'b0;
    pdetect_reg_1 = 1'b0;
    pdetect_reg_2 = 1'b0;
    pre_adder_reg_n = 7'b0100000;
    pre_adder_reg = 7'b0100000;
end

assign ctrlout = padder;

// negative-edge register
always @(negedge clk or posedge clr)
begin
    if (clr == 1'b1)
        rin_reg_n <= 1'b0;
    else
        rin_reg_n <= rin;
end

// counter
always @(posedge clk or posedge clr)
begin
    if (clr == 1'b1)
        counter1 <= 7'b1000000;
    else if (ena == 1'b1)
    begin
        if (rin_reg_n == 1'b0 && counter1 > 7'b000000)
            counter1 <= counter1 - 7'b0000001;
        else if (rin_reg_n == 1'b1 && counter1 < 7'b1111111)
            counter1 <= counter1 + 7'b0000001;       
    end
end

// 01 patter detector
assign pdetect_out = ((pdetect_reg_2 == 1'b0) && (pdetect_reg_1 == 1'b1))? 1'b1 : 1'b0;

always @(negedge clk)
    pdetect_reg_n <= rin_reg_n;

always @(posedge clk)
begin
    pdetect_reg_1 <= rin_reg_n;
    pdetect_reg_2 <= pdetect_reg_1;
end

// pre adder registers
assign pre_adder_reg_n_ena = (ena && pdetect_out);
always @(negedge clk or posedge clr)
begin
    if (clr == 1'b1)
        pre_adder_reg_n <= 7'b0100000;
    else if (pre_adder_reg_n_ena == 1'b1)
        pre_adder_reg_n <= counter1;
end

// adder
assign adder_in = (left_shift == 1'b0) ? pre_adder_reg_n
                  : (pre_adder_reg_n << 1);

// no clock for adder
assign adder1 = adder_in + pull_adder;

endmodule

module memory_matrix
#(
  parameter M = 128,
  parameter W = 7
)
(
  input clk,
  input rst,
  input [31:0] read_adr,
  output reg [W-1:0] read_data,
  input [31:0] write_adr,
  input [W-1:0] write_data,
  input write_en,
  input [31:0] write_adr2,
  input [W-1:0] write_data2,
  input write_en2,
  input [31:0] write_adr3,
  input [W-1:0] write_data3,
  input write_en3
);

  function integer log2;
    input [31:0] value;
    reg [31:0] temp;
  begin
    temp = value - 1;
    for (log2=0; temp>0; log2=log2+1)
      temp = temp>>1;
  end
  endfunction

  localparam logM = log2(M);

  reg [W-1:0] mem_matrix [M-1:0];

  integer i;
  always @(posedge clk or posedge rst) begin
    if (rst) begin
      for(i=0;i<M;i=i+1) begin
        mem_matrix[i] <= 0;
      end
    end else begin
      if (write_en) begin
        mem_matrix[write_adr] <= write_data;
      end
      if (write_en2) begin
        mem_matrix[write_adr2] <= write_data2;
      end
      if (write_en3) begin
        mem_matrix[write_adr3] <= write_data3;
      end
    end
  end

  assign read_data = mem_matrix[read_adr];

endmodule

