module tx(output wire ALERT_TransmitSOP_MessageFailed,
    output wire ALERT_TransmitSuccessful,
    output wire MessageID_mismatch,
    output wire SOP_mismatch,
    output wire MessageID_SOP_match,
    output wire [7:0] TRANSMIT_BYTE_COUNT,
    output wire [7:0] TRANSMIT_HEADER_LOW,
    output wire [7:0] TRANSMIT_HEADER_HIGH,
    output wire [7:0] TRANSMIT_DATA_OBJECTS,
    output wire Start_CRCReceiveTimer,
    output wire Stop_CRCReceiverTimer,
    output wire MessageIDCounter,
    output wire [7:0] MessageID,
    input wire [2:0] TRANSMIT,
    input wire PRL_Rx_Message_Discard,
    input wire Hard_Reset_received,
    input wire Cable_Reset_received,
    input wire [7:0] RetryCounter,
    input wire CRCReceiveTimer_Timeout,
    input wire GoodCRC_Response_from_PHY,
    input wire Message_discarded_bus_Idle,
    input wire [7:0] TX_BUF_HEADER_BYTE_1,
    input wire [7:0] RX_BUF_HEADER_BYTE_1,
    input wire [7:0] RX_BUF_FRAME_TYPE,
    input wire CLK,
    input wire RESET);

    wire RetryCounter_bigger;
    wire RetryCounter_smaller;

    reg [7:0] CurrentState;
    reg [7:0] NextState;
    reg [8:0] CRCReceive_timer;

    localparam Wait_for_Transmit_Request = 8'b00000001;
    localparam Reset_RetryCounter        = 8'b00000010;
    localparam Construct_Message         = 8'b00000100;
    localparam Wait_for_PHY_response     = 8'b00001000;
    localparam Match_MessageID           = 8'b00010000;
    localparam Check_RetryCounter        = 8'b00100000;
    localparam Report_Failure            = 8'b01000000;
    localparam Report_Success            = 8'b10000000;
    localparam nRetryCounter            = 2'b10; //definir el valor maximo

// Logica prox estado
    always@( * )
    begin
        NextState = CurrentState;
    case(CurrentState)
        Wait_for_Transmit_Request:
        begin
        if(PRL_Rx_Message_Discard || Hard_Reset_received || Cable_Reset_received) begin NextState = Reset_RetryCounter; end
        end
        Reset_RetryCounter:
        begin
        RetryCounter <= 0;
        NextState = Construct_Message;
        end
        Construct_Message:
        begin
        MessageIDCounter <= 1;
        MessageID <= MessageID + 1;
        TRANSMIT_BYTE_COUNT <= 8'h00;
        TRANSMIT_HEADER_LOW <= 8'h00;
        TRANSMIT_HEADER_HIGH <= 8'h00;
        TRANSMIT_DATA_OBJECTS <= 8'h00;
        Start_CRCReceiveTimer <= 1;
        NextState = Wait_for_PHY_response;
        end
        Wait_for_PHY_response:
        begin
        if     (GoodCRC_Response_from_PHY)  NextState = Match_MessageID;
        else if(Message_discarded_bus_Idle || CRCReceiveTimer_Timeout) NextState= Check_RetryCounter;
        end
        Match_MessageID:
        begin
        if(MessageID_mismatch || SOP_mismatch) NextState = Check_RetryCounter;
        else if(MessageID_SOP_match) NextState = Report_Success;
        end
        Check_RetryCounter:
        begin
        if(RetryCounter_bigger) NextState = Report_Failure;
        else if(RetryCounter_smaller) NextState = Construct_Message;
        end 
        Report_Success:
        begin
        ALERT_TransmitSuccessful <= 1;
        NextState = Wait_for_Transmit_Request;
        end
        Report_Failure:
        begin
        ALERT_TransmitSOP_MessageFailed <= 1;
        NextState = Wait_for_Transmit_Request;
        end
    endcase
    end

// Logica de salidas
    always@( * )
    begin
        TRANSMIT_BYTE_COUNT = 8'h01;
        TRANSMIT_HEADER_LOW = 8'h00;
        TRANSMIT_HEADER_HIGH = 8'h00;
        TRANSMIT_DATA_OBJECTS = 8'h00;
        Start_CRCReceiveTimer = 0;
        Stop_CRCReceiverTimer = 0;
        MessageIDCounter = 0;
        MessageID_mismatch = (TX_BUF_HEADER_BYTE_1 != RX_BUF_HEADER_BYTE_1) && (CurrentState == Match_MessageID);
        SOP_mismatch = (TRANSMIT[2:0] != RX_BUF_FRAME_TYPE) && (CurrentState == Match_MessageID);
        MessageID_SOP_match = !MessageID_mismatch && !SOP_mismatch;
        RetryCounter_bigger = RetryCounter >= nRetryCounter && CurrentState == Check_RetryCounter;
        RetryCounter_smaller = RetryCounter < nRetryCounter && CurrentState == Check_RetryCounter;
        ALERT_TransmitSOP_MessageFailed = 0;
        ALERT_TransmitSuccessful = 0;
    end

// Cambio de estado    
    always@(posedge CLK)
    begin
        if(RESET) begin CurrentState <= Wait_for_Transmit_Request; end
        else begin CurrentState <= NextState; end
    end
endmodule

module writeback ( from_mem_data, from_alu_data, regfile_addr_in, regwrite_in, 
        link, memtoreg, regwrite_out, regfile_data, regfile_addr_out );
  input [31:0] from_mem_data;
  input [31:0] from_alu_data;
  input [4:0] regfile_addr_in;
  output [31:0] regfile_data;
  output [4:0] regfile_addr_out;
  input regwrite_in, link, memtoreg;
  output regwrite_out;
  wire   regwrite_in;
  assign regwrite_out = regwrite_in;

  // Mux to select data source
  mux21_NBIT32_1 memtoreg_mux21 ( .A(from_mem_data), .B(from_alu_data), .S(
        memtoreg), .Y(regfile_data) );

  // Mux to select register address
  mux21_NBIT5_1 link_mux21 ( .A({1'b1, 1'b1, 1'b1, 1'b1, 1'b1}), .B(
        regfile_addr_in), .S(link), .Y(regfile_addr_out) );

  // Register write control
  always @ (posedge clk) begin
    if (regwrite_in) begin
      if (link) begin
        regfile[1] <= regfile_data;
      end else begin
        regfile[regfile_addr_in] <= regfile_data;
      end
    end
  end

endmodule

