module voltage_control (
    X ,
    A1,
    A2,
    B1,
    C1
);

    output X ;
    input  A1;
    input  A2;
    input  B1;
    input  C1;

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    reg prev_A1;
    reg prev_A2;
    reg prev_B1;
    reg prev_C1;

    always @(A1 or A2 or B1 or C1) begin
        if (A1 == prev_A1 && A2 == prev_A2 && B1 == prev_B1 && C1 == prev_C1) begin
            // input signals have not changed, so do nothing
        end else begin
            // input signals have changed, so update voltage supply signals
            if (A1 == 1 && A2 == 0) begin
                VPWR = 1;
                VGND = 0;
            end else if (A1 == 0 && A2 == 1) begin
                VPWR = 0;
                VGND = 1;
            end else begin
                VPWR = 1;
                VGND = 1;
            end

            if (B1 == 1) begin
                VPB = 1;
                VNB = 0;
            end else begin
                VPB = 0;
                VNB = 1;
            end

            if (C1 == 1) begin
                VPWR = 0;
                VGND = 0;
                VPB = 0;
                VNB = 0;
            end

            prev_A1 = A1;
            prev_A2 = A2;
            prev_B1 = B1;
            prev_C1 = C1;
        end
    end

    assign X = VPWR ^ VGND ^ VPB ^ VNB;

endmodule

