module edge_detector (
  input in,
  output reg rising,
  output reg falling
);

  reg prev_in;

  always @(posedge in or negedge in) begin
    if (in > prev_in) begin
      rising <= 1;
      falling <= 0;
    end
    else if (in < prev_in) begin
      rising <= 0;
      falling <= 1;
    end
    else begin
      rising <= 0;
      falling <= 0;
    end
    prev_in <= in;
  end

endmodule

module DFFE (
    output reg Q,
    input C, E, D
);

    // Initialize flip-flop
    always @ (posedge C) begin
        if (E) begin
            Q <= D;
        end
    end

    // Timing specifications for ICE40_HX
    `ifdef ICE40_HX
    specify
        $setup(D, posedge C &&& E, 470 - 449);
        $setup(E, posedge C, 0);
        if (E) (posedge C => (Q : D)) = 540;
