module spi_slave(
    input clk,
    input rst,
    input ss,
    input mosi,
    output miso,
    input sck,
    output done,
    input [15:0] din,
    output [15:0] dout
    );

reg mosi_d, mosi_q;
reg ss_d, ss_q;
reg sck_d, sck_q;
reg sck_old_d, sck_old_q;
reg [15:0] data_d, data_q;
reg done_d, done_q;
reg [3:0] bit_ct_d, bit_ct_q;
reg [15:0] dout_d, dout_q;
reg miso_d, miso_q;

assign miso = miso_q;
assign done = done_q;
assign dout = dout_q;

//TODO Document that chip select needs to be asserted at least 1/65Mhz before sck due to metastability concerns

always @(*) begin
    ss_d = ss;
    mosi_d = mosi;
    miso_d = miso_q;
    sck_d = sck;
    sck_old_d = sck_q;
    data_d = data_q;
    done_d = 1'b0;
    bit_ct_d = bit_ct_q;
    dout_d = dout_q;

    if (ss_q) begin // waiting for falling edge of ss
        bit_ct_d = 4'b0;
        data_d = 16'b0;
        miso_d = 1'b1;
        if (!ss_d) begin // falling edge of ss, start of data transfer
            data_d = din;
        end
    end else begin // data transfer in progress
        if (!sck_old_q && sck_q) begin // rising edge
            data_d = {data_q[14:0], mosi_q};
            bit_ct_d = bit_ct_q + 1'b1;
            if (bit_ct_q == 4'b1111) begin // last bit of data
                dout_d = {data_q[14:0], mosi_q};
                done_d = 1'b1;
                data_d = 16'b0;
            end
        end else if (sck_old_q && !sck_q) begin // falling edge
            miso_d = data_q[15];
        end
    end
end

always @(posedge clk) begin
    if (rst) begin // asynchronous reset
        done_q <= 1'b0;
        bit_ct_q <= 4'b0;
        dout_q <= 16'b0;
        miso_q <= 1'b1;
    end else begin
        done_q <= done_d;
        bit_ct_q <= bit_ct_d;
        dout_q <= dout_d;
        miso_q <= miso_d;
    end

    sck_q <= sck_d;
    mosi_q <= mosi_d;
    ss_q <= ss_d;
    data_q <= data_d;
    sck_old_q <= sck_old_d;

end

endmodule

