module vending_machine (
  input N,
  input D,
  input Q,
  input button,
  output dispense,
  output change
);

parameter price = 25; // price of the product in cents
parameter max_money = 100; // maximum amount of money that can be inserted in cents

// Define the states
parameter IDLE = 2'b00;
parameter ACCEPT = 2'b01;
parameter DISPENSE_CHANGE = 2'b10;

reg [1:0] state, next_state;

// Define the outputs
reg dispense, change;

// Define the amount of money inserted
reg [7:0] money;

// Define the transitions between states
always @(*) begin
  case (state)
    IDLE: begin
      if (button && money >= price) begin
        dispense = 1;
        change = money - price;
        next_state = DISPENSE_CHANGE;
      end else if (button && money < price) begin
        dispense = 0;
        change = money;
        next_state = DISPENSE_CHANGE;
      end else if (money >= max_money) begin
        dispense = 0;
        change = money;
        next_state = DISPENSE_CHANGE;
      end else begin
        dispense = 0;
        change = 0;
        next_state = ACCEPT;
      end
    end
    ACCEPT: begin
      if (button && money >= price) begin
        dispense = 1;
        change = money - price;
        next_state = DISPENSE_CHANGE;
      end else if (button && money < price) begin
        dispense = 0;
        change = money;
        next_state = DISPENSE_CHANGE;
      end else if (money >= max_money) begin
        dispense = 0;
        change = money;
        next_state = DISPENSE_CHANGE;
      end else if (N || D || Q) begin
        money = money + 5*N + 10*D + 25*Q;
        dispense = 0;
        change = 0;
        next_state = ACCEPT;
      end else begin
        dispense = 0;
        change = 0;
        next_state = IDLE;
      end
    end
    DISPENSE_CHANGE: begin
      if (dispense || change) begin
        money = 0;
        next_state = IDLE;
      end else begin
        next_state = DISPENSE_CHANGE;
      end
    end
  endcase
end

// Assign the next state to the current state
always @(posedge clk) begin
  state <= next_state;
end

endmodule

