module edge_detection (
  input               clk,
  input               reset,
  input               a,
  input               delay,
  output reg          rise,
  output reg          down
);

  reg                 a_delayed;
  reg                 a_last;
  reg                 a_last_delayed;
  reg                 a_delayed_delayed;

  delay_locked_loop   dll (
    .clk              (clk),
    .reset            (reset),
    .data_in          (a),
    .data_out         (a_delayed)
  );

  always @(posedge clk) begin
    a_last_delayed    <= a_delayed_delayed;
    a_delayed_delayed <= a_delayed;
    a_last            <= a_delayed;
  end

  always @(posedge clk) begin
    if (reset) begin
      rise <= 0;
      down <= 0;
    end else begin
      if (a_last_delayed == 0 && a_last == 1) begin
        rise <= 1;
        down <= 0;
      end else if (a_last_delayed == 1 && a_last == 0) begin
        rise <= 0;
        down <= 1;
      end else begin
        rise <= 0;
        down <= 0;
      end
    end
  end

endmodule

