module altddio_in (
    datain,    // required port, DDR input data
    inclock,   // required port, input reference clock to sample data by
    inclocken, // enable data clock
    aset,      // asynchronous set
    aclr,      // asynchronous clear
    sset,      // synchronous set
    sclr,      // synchronous clear
    dataout_h, // data sampled at the rising edge of inclock
    dataout_l  // data sampled at the falling edge of inclock
);

parameter width = 1;
parameter power_up_high = "OFF";
parameter invert_input_clocks = "OFF";
parameter intended_device_family = "Stratix";
parameter lpm_type = "altddio_in";
parameter lpm_hint = "UNUSED";

input [width-1:0] datain;
input inclock;
input inclocken;
input aset;
input aclr;
input sset;
input sclr;

output reg [width-1:0] dataout_h;
output reg [width-1:0] dataout_l;

reg [width-1:0] data_reg;

always @(posedge inclock or negedge inclock) begin
    if (inclocken) begin
        data_reg <= datain;
        dataout_h <= data_reg;
        dataout_l <= data_reg;
    end
end

always @(posedge inclock) begin
    if (sset) begin
        data_reg <= 1'b1;
    end else if (sclr) begin
        data_reg <= 1'b0;
    end
end

always @(data_reg or aset or aclr) begin
    if (aclr) begin
        data_reg <= 1'b0;
    end else if (aset) begin
        data_reg <= 1'b1;
    end
end

initial begin
    if (power_up_high == "ON") begin
        data_reg <= 1'b1;
    end else begin
        data_reg <= 1'b0;
    end
end

endmodule

module memory_decoder(
    input wire [7:0] address,
    input wire [7:0] data_in,
    input wire [7:0] switch_in,
    input wire clk,
    input wire res,
    input wire write_enable,
    output wire [7:0] LED_status,
    output wire [7:0] data_out
);

    wire [7:0] memory_data_out;
    wire [7:0] switch_data_out;
    wire mem_write_enable, LED_write_enable;

    // mask write to address 0xff for LED usage
    assign mem_write_enable = write_enable & (~&address);

    // sram block
    sram sram0 (
        .address(address),
        .data_in(data_in),
        .clk(clk),
        .write_enable(mem_write_enable),
        .data_out(memory_data_out)
    );

    // decode LED address
    assign LED_write_enable = write_enable & (&address);

    // LED output driver flip flop
    ff_d #(.WIDTH(8)) led_driver0 (
        .D(data_in),
        .en(LED_write_enable),
        .clk(clk),
        .res(res),
        .Q(LED_status)
    );

    // switch input driver flip flop
    ff_d #(.WIDTH(8)) switch_driver0 (
        .D(switch_in),
        .en(1'b1),
        .clk(clk),
        .res(res),
        .Q(switch_data_out)
    );

    // decode read address
    assign data_out = (~&address) ? memory_data_out : switch_data_out;

endmodule

