module top_module(
    input wire a, 
    input wire b,
    output reg out,
    input wire [7:0] in_hi,
    input wire [7:0] in_lo,
    output wire [15:0] out_concat
);

    // XOR gate using only XOR gates and inverters
    wire xor1 = ~(a & b);
    wire xor2 = ~(a & xor1);
    wire xor3 = ~(b & xor1);
    wire xor4 = ~(xor2 & xor3);

    // 16-bit concatenation module
    assign out_concat = {in_hi, in_lo};

    // Functional module
    always @(*) begin
        if(out_concat >= 8'h80) begin
            out = xor4;
        end else begin
            out = out_concat[7:0];
        end
    end

endmodule

module or1200_freeze(
    input clk,
    input rst,
    input [OR1200_MULTICYCLE_WIDTH-1:0] multicycle,
    input flushpipe,
    input extend_flush,
    input lsu_stall,
    input if_stall,
    input lsu_unstall,
    input force_dslot_fetch,
    input abort_ex,
    input du_stall,
    input mac_stall,
    output genpc_freeze,
    output if_freeze,
    output id_freeze,
    output ex_freeze,
    output wb_freeze,
    input icpu_ack_i,
    input icpu_err_i
);

wire multicycle_freeze;
reg [OR1200_MULTICYCLE_WIDTH-1:0] multicycle_cnt;
reg flushpipe_r;

assign genpc_freeze = du_stall | flushpipe_r | lsu_stall;
assign if_freeze = id_freeze | extend_flush;
assign id_freeze = (lsu_stall | (~lsu_unstall & if_stall) | multicycle_freeze | force_dslot_fetch) | du_stall | mac_stall;
assign ex_freeze = wb_freeze;
assign wb_freeze = (lsu_stall | (~lsu_unstall & if_stall) | multicycle_freeze) | du_stall | mac_stall | abort_ex;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        multicycle_cnt <= #1 2'b00;
        flushpipe_r <= #1 1'b0;
    end else begin
        if (icpu_ack_i | icpu_err_i) begin
            flushpipe_r <= #1 flushpipe;
        end else if (!flushpipe) begin
            flushpipe_r <= #1 1'b0;
        end
        if (|multicycle_cnt) begin
            multicycle_cnt <= #1 multicycle_cnt - 2'd1;
        end else if (|multicycle & !ex_freeze) begin
            multicycle_cnt <= #1 multicycle;
        end
    end
end

assign multicycle_freeze = |multicycle_cnt;

endmodule

module ping_pong_buffer (
  input clk,
  input reset,
  input [7:0] data_in,
  output reg [7:0] data_out
);

  reg [3:0] write_addr;
  reg [3:0] read_addr;
  reg [7:0] ram [0:15];

  always @(posedge clk) begin
    if (reset) begin
      write_addr <= 0;
      read_addr <= 0;
    end else begin
      if (write_addr == 15) begin
        write_addr <= 0;
      end else begin
        write_addr <= write_addr + 1;
      end

      if (read_addr == 15) begin
        read_addr <= 0;
      end else begin
        read_addr <= read_addr + 1;
      end
    end
  end

  always @(posedge clk) begin
    if (reset) begin
      ram <= 0;
    end else begin
      ram[write_addr] <= data_in;
    end
  end

  always @(posedge clk) begin
    if (reset) begin
      data_out <= 0;
    end else begin
      data_out <= ram[read_addr];
    end
  end

endmodule

module priority_encoder (
    input a,
    input b,
    input c,
    input d,
    output reg highest_priority,
    output reg [1:0] binary_code
);

    // 2-to-1 MUX using NAND gates
    wire nand1, nand2, nand3, nand4, nand5, nand6;
    assign nand1 = ~(a & b);
    assign nand2 = ~(b & c);
    assign nand3 = ~(c & d);
    assign nand4 = ~(nand1 & nand2);
    assign nand5 = ~(nand2 & nand3);
    assign nand6 = ~(nand4 & nand5);

    // 3-to-1 MUX using NAND gates
    wire nand7, nand8, nand9;
    assign nand7 = ~(a & b & c);
    assign nand8 = ~(b & c & d);
    assign nand9 = ~(a & c & d);

    // Output logic
    always @* begin
        if (nand6) begin
            highest_priority = 1;
            binary_code = 2'b00;
        end else if (nand7) begin
            highest_priority = 0;
            binary_code = 2'b01;
        end else if (nand8) begin
            highest_priority = 0;
            binary_code = 2'b10;
        end else if (nand9) begin
            highest_priority = 0;
            binary_code = 2'b11;
        end else begin
            highest_priority = 0;
            binary_code = 2'b00;
        end
    end

endmodule

