  output [31:0] data_out;

  wire comp1;
  wire [31:0] data_out;
  wire [31:0] fifo_data [32767:0];
  reg [14:0] write_ptr;
  reg [14:0] read_ptr;
  wire [14:0] fifo_depth;
  wire fifo_full;

  assign fifo_depth = write_ptr - read_ptr;
  assign fifo_full = (fifo_depth == 32768);

  (* XILINX_LEGACY_PRIM = "(MUXCY,XORCY)" *) 
  (* box_type = "PRIMITIVE" *) 
  CARRY4 carry_write_ptr
       (.CI(1'b0),
        .CO({fifo_full,write_ptr[14]}),
        .CYINIT(1'b0),
        .DI({fifo_full,write_ptr[14:0]}),
        .O(write_ptr[14:0]),
        .S(1'b1));

  (* XILINX_LEGACY_PRIM = "(MUXCY,XORCY)" *) 
  (* box_type = "PRIMITIVE" *) 
  CARRY4 carry_read_ptr
       (.CI(1'b0),
        .CO({fifo_full,read_ptr[14]}),
        .CYINIT(1'b0),
        .DI({fifo_full,read_ptr[14:0]}),
        .O(read_ptr[14:0]),
        .S(1'b1));

  always @(posedge clk) begin
    if (rst) begin
      write_ptr <= 0;
      read_ptr <= 0;
