module mux_256_1 (
    input wire [1023:0] in,
    input wire [7:0] sel,
    output wire [3:0] out);

    wire [3:0] level1 [127:0];
    wire [3:0] level2 [63:0];
    wire [3:0] level3 [31:0];
    wire [3:0] level4 [15:0];
    wire [3:0] level5 [7:0];
    wire [3:0] level6 [3:0];
    wire [3:0] level7 [1:0];

    // Level 1
    genvar i;
    generate
        for (i = 0; i < 128; i = i + 1) begin
            assign level1[i] = in[i*8 +: 4];
        end
    endgenerate

    // Level 2
    generate
        for (i = 0; i < 64; i = i + 1) begin
            assign level2[i] = (sel[6:5] == 2'b00) ? level1[i*2] :
                               (sel[6:5] == 2'b01) ? level1[i*2 + 1] :
                               (sel[6:5] == 2'b10) ? level1[i*2 + 32] :
                                                     level1[i*2 + 33] ;
        end
    endgenerate

    // Level 3
    generate
        for (i = 0; i < 32; i = i + 1) begin
            assign level3[i] = (sel[4:3] == 2'b00) ? level2[i*2] :
                               (sel[4:3] == 2'b01) ? level2[i*2 + 1] :
                               (sel[4:3] == 2'b10) ? level2[i*2 + 16] :
                                                     level2[i*2 + 17] ;
        end
    endgenerate

    // Level 4
    generate
        for (i = 0; i < 16; i = i + 1) begin
            assign level4[i] = (sel[2:1] == 2'b00) ? level3[i*2] :
                               (sel[2:1] == 2'b01) ? level3[i*2 + 1] :
                               (sel[2:1] == 2'b10) ? level3[i*2 + 8] :
                                                     level3[i*2 + 9] ;
        end
    endgenerate

    // Level 5
    generate
        for (i = 0; i < 8; i = i + 1) begin
            assign level5[i] = (sel[0] == 1'b0) ? level4[i*2] :
                                                 level4[i*2 + 1] ;
        end
    endgenerate

    // Level 6
    generate
        assign level6[0] = (sel == 8'b00000000) ? level5[0] :
                           (sel == 8'b00000001) ? level5[1] :
                           (sel == 8'b00000010) ? level5[2] :
                           (sel == 8'b00000011) ? level5[3] :
                           (sel == 8'b00000100) ? level5[4] :
                           (sel == 8'b00000101) ? level5[5] :
                           (sel == 8'b00000110) ? level5[6] :
                                                 level5[7] ;
    endgenerate

    // Level 7
    assign level7[0] = (sel == 8'b00000000) ? level6[0] :
                       level6[1] ;

    // Output
    assign out = level7[0];

endmodule

