            next_state <= A;
            out1 <= 1'b0;
            out2 <= 1'b0;
          end else if (in1 == 1'b1 && in2 == 1'b0) begin
            next_state <= D;
            out1 <= 1'b0;
            out2 <= 1'b1;
          end else begin // in1 == 1'b1 && in2 == 1'b1
