          end else begin // in1 == 1'b1 && in2 == 1'b1
            next_state <= A;
            out1 <= 1'b0;
            out2 <= 1'b1;
          end
        end
        C: begin
          if (in1 == 1'b0 && in2 == 1'b0) begin
            next_state <= A;
            out1 <= 1'b1;
            out2 <= 1'b1;
          end else if (in1 == 1'b0 && in2 == 1'b1) begin
            next_state <= C;
            out1 <= 1'b0;
