    wire [3:0] upper = in[11:8];

    // Create a 3-bit shift register using master-slave flip-flops
    reg [2:0] shift_reg;
    always @(posedge clk) begin
        shift_reg <= {shift_reg[1:0], lower};
    end

    // Perform a left rotation on the lower byte using the shift register
    wire [3:0] rotated_lower = {shift_reg[2], shift_reg[1], shift_reg[0]};

    // Combine the rotated lower byte, middle byte, and upper byte using a barrel shifter
    wire [11:0] shifted_in = {rotated_lower, middle, upper};
    wire [7:0] and_out;

    // Perform a bitwise AND operation between the shifted input and the original input
    and_gate and1(.in1(shifted_in), .in2(in), .out(and_out));

    // Output the result of the AND operation
    assign out = and_out[7:0];

endmodule

// Barrel shifter module
module barrel_shifter (
    input [11:0] in,
    input [1:0] shift,
    output [11:0] out
);

    assign out = (shift[1]) ? ({in[7:0], in[11:8], in[3:0], in[10:4]}) :
                             ({in[3:0], in[7:4], in[11:8], in[10:4] >> shift[0]});

endmodule

// AND gate module
module and_gate (
    input [11:0] in1,
    input [11:0] in2,
    output [11:0] out
);

    assign out = in1 & in2;

endmodule

module packet_padder (
  input clk,
  input reset,
  input set_stb,
  input [7:0] set_addr,
  input [31:0] set_data,
  input [35:0] data_i,
  input src_rdy_i,
  output dst_rdy_o,
  output [35:0] data_o,
  output src_rdy_o,
  input always_flush
);

  // Configuration parameters
  parameter BASE = 0;
  parameter DEFAULT_LINES32 = 4096;
  parameter DEFAULT_IDLE_CYC = 65536;

  // State machine states
  localparam STATE_READ_HDR = 2'b00;
  localparam STATE_WRITE_HDR = 2'b01;
  localparam STATE_FORWARD = 2'b10;
  localparam STATE_WRITE_PAD = 2'b11;

  // State machine signals
  reg [1:0] state;
  reg [31:0] vita_hdr;
  reg has_vita_hdr;
  reg [15:0] line_count;
  reg [17:0] non_rx_cycles;

  // Setting registers
  wire lut_lines_changed;
  wire [15:0] max_lut_lines32;
  setting_reg #(.my_addr(BASE+0),.width(16),.at_reset(DEFAULT_LINES32)) sr_num_lines(
      .clk(clk),.rst(reset),.strobe(set_stb),.addr(set_addr),.in(set_data),
      .out(max_lut_lines32),.changed(lut_lines_changed));

  wire idle_cyc_changed;
  wire [17:0] idle_flush_cycles;
  setting_reg #(.my_addr(BASE+1),.width(18),.at_reset(DEFAULT_IDLE_CYC)) sr_flush_cyc(
      .clk(clk),.rst(reset),.strobe(set_stb),.addr(set_addr),.in(set_data),
      .out(idle_flush_cycles),.changed(idle_cyc_changed));

  // Output signals
  assign dst_rdy_o = (state == STATE_READ_HDR)? 1 : ((state == STATE_FORWARD)? dst_rdy_i : 0);
  assign src_rdy_o = (state == STATE_WRITE_HDR || state == STATE_WRITE_PAD)? 1 : ((state == STATE_FORWARD)? src_rdy_i : 0);
  assign data_o = (state == STATE_WRITE_HDR)? {4'b0001, vita_hdr} : ((state == STATE_FORWARD)? data_i : 0);

  // Count the number of cycles since RX data so we can force a flush
  wire idle_timeout = (non_rx_cycles == idle_flush_cycles);
  always @(posedge clk) begin
    if(reset || state != STATE_READ_HDR || idle_cyc_changed) begin
      non_rx_cycles <= 0;
    end
    else if (~idle_timeout) begin
      non_rx_cycles <= non_rx_cycles + 1;
    end
  end

  // Flush when we have written data to a LUT and either idle or non active DSP
  wire force_flush = (line_count != 0) && ((idle_timeout && (state == STATE_READ_HDR)) || always_flush);

  // Padding state machine
  always @(posedge clk) begin
    if (reset) begin
      state <= STATE_READ_HDR;
      line_count <= max_lut_lines32;
      non_rx_cycles <= 0;
      has_vita_hdr <= 0;
    end else begin
      case(state)
        STATE_READ_HDR: begin
          if (src_rdy_i && dst_rdy_o && data_i[32]) begin
            vita_hdr <= data_i[31:0];
            has_vita_hdr <= 1;
            state <= (data_i[15:0] > line_count)? STATE_WRITE_PAD : STATE_WRITE_HDR;
          end else if (force_flush) begin
            has_vita_hdr <= 0;
            state <= STATE_WRITE_PAD;
          end
        end

        STATE_WRITE_HDR: begin
          if (src_rdy_o && dst_rdy_i) begin
            state <= STATE_FORWARD;
          end
        end

        STATE_FORWARD: begin
          if (src_rdy_i && dst_rdy_o && data_i[33]) begin
            state <= STATE_READ_HDR;
          end
        end

        STATE_WRITE_PAD: begin
          if (src_rdy_o && dst_rdy_i && line_count == 1) begin
            state <= (has_vita_hdr)? STATE_WRITE_HDR : STATE_READ_HDR;
          end
        end
      endcase
      if (src_rdy_o && dst_rdy_i && (state == STATE_WRITE_HDR || state == STATE_WRITE_PAD)) begin
        if (line_count > 0) begin
          line_count <= line_count - 1;
        end
      end
    end
  end

endmodule

module add2bit (
    input [1:0] A,
    input [1:0] B,
    output [1:0] S,
    output C_out
);

    wire [2:0] temp_sum;
    wire C1, C2;

    // Full adder for bit 0
    full_adder FA0 (
        .A(A[0]),
        .B(B[0]),
        .C_in(1'b0),
        .S(temp_sum[0]),
        .C_out(C1)
    );

    // Full adder for bit 1
    full_adder FA1 (
        .A(A[1]),
        .B(B[1]),
        .C_in(C1),
        .S(temp_sum[1]),
        .C_out(C2)
    );

    // Carry out
    assign C_out = C2;

    // Sign extension
    assign temp_sum[2] = temp_sum[1];

    // 2's complement conversion
    assign S = C2 ? {~temp_sum[1], ~temp_sum[0]} + 2'b1 : temp_sum[1:0];

endmodule

module full_adder (
    input A,
    input B,
    input C_in,
    output S,
    output C_out
);

    assign S = A ^ B ^ C_in;
    assign C_out = (A & B) | (C_in & (A ^ B));

endmodule

module barrel_shifter (
    input [3:0] a, b, // 4-bit inputs
    input [1:0] mode, // 2-bit mode input
    output reg [3:0] out // 4-bit output
);

always @(*) begin
    case (mode)
        2'b00: out = a; // no shift
        2'b01: out = {a[2:0], b[3]}; // left shift
        2'b10: out = {a[1:0], b[3:0]}; // right shift
        2'b11: out = b; // no shift
    endcase
end

endmodule
module magnitude_comparator (
    input [2:0] a, b, // 3-bit inputs
    input [1:0] select, // 2-bit select signal
    output reg [2:0] out // 3-bit output
);

always @(*) begin
    case (select)
        2'b00: out = (a > b) ? 3'b001 : 3'b010; // greater than
        2'b01: out = (a >= b) ? 3'b001 : 3'b010; // greater than or equal to
        2'b10: out = (a == b) ? 3'b001 : 3'b010; // equal to
        2'b11: out = (a <= b) ? 3'b001 : 3'b010; // less than or equal to
    endcase
end

endmodule
module priority_encoder (
    input [3:0] in, // 4-bit input
    output reg [1:0] out // 2-bit output
);

always @(*) begin
    casez (in)
        4'b0001: out = 2'b00;
        4'b0010: out = 2'b01;
        4'b0100: out = 2'b10;
        4'b1000: out = 2'b11;
        default: out = 2'b00;
    endcase
end

endmodule
module final_output_generator (
    input [3:0] shifter_out, cmp_out, // 4-bit inputs from barrel shifter and magnitude comparator
    output reg [3:0] out // 4-bit output after bitwise OR operation
);

always @(*) begin
    out = shifter_out | cmp_out;
end

endmodule
module top_module (
    input [3:0] a, b, // 4-bit input for the barrel shifter
    input [1:0] mode, // 2-bit input to select the shift operation
    input [2:0] cmp_a, cmp_b, // 3-bit binary number inputs for the magnitude comparator
    input [1:0] select, // 2-bit select signal for input selector
    output reg [3:0] final_output // 4-bit output after bitwise OR operation
);

wire [3:0] shifter_out;
wire [2:0] cmp_out;
wire [1:0] priority_encoder_out;

barrel_shifter bs (
    .a(a),
    .b(b),
    .mode(mode),
    .out(shifter_out)
);

magnitude_comparator mc (
    .a(cmp_a),
    .b(cmp_b),
    .select(select),
    .out(cmp_out)
);

priority_encoder pe (
    .in({shifter_out[3], cmp_out[2:0]}),
    .out(priority_encoder_out)
);

final_output_generator fog (
    .shifter_out(shifter_out),
    .cmp_out(cmp_out),
    .out(final_output)
);

always @(*) begin
    case (priority_encoder_out)
        2'b00: final_output = shifter_out; // shifter output has priority
        2'b01: final_output = cmp_out; // magnitude comparator output has priority
        2'b10: final_output = 4'b1111; // all bits are 1
        2'b11: final_output = 4'b0000; // all bits are 0
    endcase
end

endmodule

module tmu2_hinterp(
    input sys_clk,
    input sys_rst,

    output busy,

    input pipe_stb_i,
    output pipe_ack_o,
    input signed [11:0] x,
    input signed [11:0] y,
    input signed [17:0] tsx,
    input signed [17:0] tsy,
    input diff_x_positive,
    input [16:0] diff_x_q,
    input [16:0] diff_x_r,
    input diff_y_positive,
    input [16:0] diff_y_q,
    input [16:0] diff_y_r,

    input [10:0] dst_squarew,

    output pipe_stb_o,
    input pipe_ack_i,
    output reg signed [11:0] dx,
    output reg signed [11:0] dy,
    output signed [17:0] tx,
    output signed [17:0] ty
);

reg load;
reg next_point;

/* Interpolators */
tmu2_geninterp18 i_tx(
    .sys_clk(sys_clk),
    .load(load),
    .next_point(next_point),
    .init(tsx),
    .positive(diff_x_positive),
    .q(diff_x_q),
    .r(diff_x_r),
    .divisor({6'd0, dst_squarew}),
    .o(tx)
);
tmu2_geninterp18 i_ty(
    .sys_clk(sys_clk),
    .load(load),
    .next_point(next_point),
    .init(tsy),
    .positive(diff_y_positive),
    .q(diff_y_q),
    .r(diff_y_r),
    .divisor({6'd0, dst_squarew}),
    .o(ty)
);

always @(posedge sys_clk) begin
    if(load) begin
        dx <= x;
        dy <= y;
    end else if(next_point)
        dx <= dx + 12'd1;
end

/* Controller */
reg [10:0] remaining_points;
always @(posedge sys_clk) begin
    if(load)
        remaining_points <= dst_squarew - 11'd1;
    else if(next_point)
        remaining_points <= remaining_points - 11'd1;
end
wire last_point = remaining_points == 11'd0;

reg state;
reg next_state;

parameter IDLE  = 1'b0;
parameter BUSY  = 1'b1;

always @(posedge sys_clk) begin
    if(sys_rst)
        state <= IDLE;
    else
        state <= next_state;
end

assign busy = state;
assign pipe_ack_o = ~state;
assign pipe_stb_o = state;

always @(*) begin
    next_state = state;
    load = 1'b0;
    next_point = 1'b0;

    case(state)
        IDLE: begin
            if(pipe_stb_i) begin
                load = 1'b1;
                next_state = BUSY;
            end
        end
        BUSY: begin
            if(pipe_ack_i) begin
                if(last_point)
                    next_state = IDLE;
                else
                    next_point = 1'b1;
            end
        end
    endcase
end

endmodule

module ram32k(input clk,
              input [14:0] addr,
              input [15:0] data_in,
              output [15:0] data_out,
              input we,
              input re);

  wire [7:0] data_out_low;
  wire [7:0] data_out_high;
  wire we_low;
  wire re_low;
  wire we_high;
  wire re_high;
  wire on_high;

  ram8k r1(.clk(clk),
           .addr(addr[12:0]),
           .data_in(data_in[7:0]),
           .data_out(data_out_low),
           .we(we_low),
           .re(re_low));

  ram8k r2(.clk(clk),
           .addr(addr[12:0]),
           .data_in(data_in[7:0]),
           .data_out(data_out_high),
           .we(we_high),
           .re(re_high));

  assign on_high = addr[14];

  mux16 mux(.a(data_out_low),
            .b(data_out_high),
            .sel(on_high),
            .out(data_out));

  assign we_low = we & ~on_high;
  assign we_high = we & on_high;
  assign re_low = re;
  assign re_high = re;

endmodule

module mux16(input [15:0] a,
             input [15:0] b,
             input sel,
             output reg [15:0] out);

  always @(*) begin
    if (sel) begin
      out = b;
    end else begin
      out = a;
    end
  end

endmodule

module ram8k(input clk,
             input [12:0] addr,
             input [7:0] data_in,
             output [7:0] data_out,
             input we,
             input re);

  reg [7:0] mem [0:4095];

  always @(posedge clk) begin
    if (we) begin
      mem[addr] <= data_in;
    end
  end

  assign data_out = re ? mem[addr] : 8'hzz;

endmodule

module VendingMachine(
		input [2:0] KeyPad,
		input [1:0] Mode,
		input CLK,
		input RESET,
		output reg [7:0] Credit,
		output reg [5:0] Coins);

	initial begin
		Credit = 8'd0;
		Coins = 6'b000000;
	end

	always @(posedge CLK or posedge RESET)
	begin

	if (RESET)
			begin
				Credit = 8'd0;
				Coins = 6'b000000;	
			end
	else
	begin

		case (Mode)
		2'b00: ;
		2'b01: 
		begin
			case (KeyPad)
			3'b000: if ((Credit + 1) <= 255)
						Credit = Credit+1;
			3'b001: if((Credit + 2) <= 255)
						Credit = Credit+2;
			3'b010: if((Credit+5) <= 255)
					Credit = Credit+5;
			3'b011: if((Credit + 10) <= 255)
					Credit = Credit+10;
			3'b100: if((Credit + 20) <= 255)
					Credit = Credit+20;
			3'b101: if((Credit + 50) <= 255)
					Credit = Credit+50;
			3'b110: if((Credit + 100) <= 255)
					Credit = Credit+100;
			3'b111: if((Credit + 200) <= 255)
					Credit = Credit+200;
			endcase
		end

		2'b10: 
		begin
			case (KeyPad)
			3'b000: if (Credit >= 220)
						begin
							Credit = Credit-220;
							Coins = 6'b100000;
						end
			3'b001: if(Credit  >= 120)
						begin
							Credit = Credit-120;
							Coins = 6'b010000;
						end
			3'b010: if(Credit  >= 180)
					begin
						Credit = Credit-180;
						Coins = 6'b001000;
					end
			3'b011: if(Credit  >= 55)
					begin
						Credit = Credit-55;
						Coins = 6'b000100;
					end
			3'b100: if(Credit  >= 13)
					begin
						Credit = Credit-13;
						Coins = 6'b000010;
					end
			3'b101: if(Credit  >= 25)
					begin
						Credit = Credit-25;
						Coins = 6'b000001;
					end
			3'b110: if(Credit  >= 85)
					begin
						Credit = Credit-85;
						Coins = 6'b111111;
					end
			3'b111: if(Credit  >= 75)
					begin
						Credit = Credit-75;
						Coins = 6'b111110;
					end
			endcase
		end

		2'b11:
		begin
			if ( Credit >= 50)
			begin
				Credit = Credit - 50;
				Coins = 6'b100000;
			end

			else if ( Credit >= 20)
			begin
				Credit = Credit - 20;
				Coins = 6'b010000;
			end

			else if ( Credit >= 10)
			begin
				Credit = Credit - 10;
				Coins = 6'b001000;
			end

			else if ( Credit >= 5)
			begin
				Credit = Credit - 5;
				Coins = 6'b000100;
			end

			else if ( Credit >= 2)
			begin
				Credit = Credit - 2;
				Coins = 6'b000010;
			end

			else if ( Credit >= 1)
			begin
				Credit = Credit - 1;
				Coins = 6'b000001;
			end

			else if ( Credit == 0)
				Coins = 6'b000000;

		end

		endcase
	end

	end

endmodule

module even_odd_bit_swap (
