    out_vector[2] = in_vector[3];
    out_vector[3] = in_vector[2];
    out_vector[4] = in_vector[5];
    out_vector[5] = in_vector[4];
    out_vector[6] = in_vector[7];
    out_vector[7] = in_vector[6];
  end

endmodule

module fifo_64in_out_blk_mem_gen
   (dout,
    wr_clk,
    rd_clk,
    I1,
    tmp_ram_rd_en,
    Q,
    O2,
    O1,
    din);
  output [63:0]dout;
  output [0:0]Q;
  output [11:0]O1;
  output [11:0]O2;
  input wr_clk;
  input rd_clk;
  input I1;
  input tmp_ram_rd_en;
  input [63:0]din;

  reg [63:0] mem [0:4095];
  reg [11:0] write_ptr = 0;
  reg [11:0] read_ptr = 0;
  reg [11:0] count = 0;
  reg [0:0] full = 0;

  always @(posedge wr_clk) begin
    if (I1 && !full) begin
      mem[write_ptr] <= din;
      write_ptr <= write_ptr + 1;
      count <= count + 1;
      if (write_ptr == 4096) begin
        write_ptr <= 0;
      end
      if (count == 4096) begin
        full <= 1;
      end
    end
  end

  always @(posedge rd_clk) begin
    if (tmp_ram_rd_en && !full) begin
      dout <= mem[read_ptr];
      read_ptr <= read_ptr + 1;
      count <= count - 1;
      if (read_ptr == 4096) begin
        read_ptr <= 0;
      end
      if (count == 0) begin
        full <= 0;
      end
    end
  end

  assign Q = full;
  assign O1 = count;
  assign O2 = 4096 - count;

endmodule

module Multiplexer_AC__parameterized128
   (ctrl,
    D0,
    D1,
    S);

  parameter WIDTH = 128;

  input ctrl;
  input [WIDTH-1:0] D0;
  input [WIDTH-1:0] D1;
  output [WIDTH-1:0] S;

  wire [WIDTH-1:0] D0_wire;
  wire [WIDTH-1:0] D1_wire;
  wire [WIDTH-1:0] S_wire;
  wire ctrl_wire;

  assign D0_wire = D0;
  assign D1_wire = D1;
  assign ctrl_wire = ctrl;

  LUT3 #(
    .INIT(8'hB8)) 
    \S[0]_INST_0 
       (.I0(D1_wire[0]),
        .I1(ctrl_wire),
        .I2(D0_wire[0]),
        .O(S_wire[0]));

  genvar i;
  generate
    for (i = 1; i < WIDTH; i = i + 1) begin
      LUT3 #(
        .INIT(8'hB8)) 
        \S[i]_INST_0 
           (.I0(D1_wire[i]),
            .I1(ctrl_wire),
            .I2(D0_wire[i]),
            .O(S_wire[i]));
    end
  endgenerate

  assign S = S_wire;

endmodule

