module large_mux(
    input [15:0] sel,
    input [65535:0] in,
    output [15:0] out
);
    wire [15:0] mux0_out, mux1_out, mux2_out, mux3_out, mux4_out, mux5_out, mux6_out, mux7_out;
    wire [15:0] mux8_out, mux9_out, mux10_out, mux11_out, mux12_out, mux13_out, mux14_out, mux15_out;
    small_mux mux0(.sel(sel[3:0]), .in0(in[15:0]), .in1(in[31:16]), .in2(in[47:32]), .in3(in[63:48]), .out(mux0_out));
