module game(I1, I2, I3, I4, enter, reset, win, lose, equal, bigger, smaller, nums);
  input I1, I2, I3, I4, enter, reset;
  output reg win, lose, equal, bigger, smaller;
  output reg [3:0] nums;
  reg [3:0] a_seq, b_seq;
  reg [2:0] b_tries;
  reg a_done, b_done;

  always @(posedge enter or posedge reset) begin
    if (reset) begin
      win = 0;
      lose = 0;
      equal = 0;
      bigger = 0;
      smaller = 0;
      nums = 0;
      a_seq = 0;
      b_seq = 0;
      b_tries = 0;
      a_done = 0;
      b_done = 0;
    end
    else if (enter) begin
      if (!a_done) begin
        if (a_seq[3:0] == 4'b1111) begin
          a_done = 1;
        end
        else begin
          if (I1) begin
            a_seq[0] = 1;
            nums[0] = 1;
          end
          else if (I2) begin
            a_seq[1] = 1;
            nums[1] = 1;
          end
          else if (I3) begin
            a_seq[2] = 1;
            nums[2] = 1;
          end
          else if (I4) begin
            a_seq[3] = 1;
            nums[3] = 1;
          end
        end
      end
      else if (!b_done) begin
        if (b_seq[3:0] == 4'b1111) begin
          b_done = 1;
        end
        else begin
          if (I1) begin
            b_seq[0] = 1;
            nums[0] = 1;
          end
          else if (I2) begin
            b_seq[1] = 1;
            nums[1] = 1;
          end
          else if (I3) begin
            b_seq[2] = 1;
            nums[2] = 1;
          end
          else if (I4) begin
            b_seq[3] = 1;
            nums[3] = 1;
          end
        end
      end
      else begin
        if (a_seq > b_seq) begin
          bigger = 1;
        end
        else if (a_seq < b_seq) begin
          smaller = 1;
        end
        else begin
          equal = 1;
          win = 1;
        end
        if (!win) begin
          b_tries = b_tries + 1;
          if (b_tries == 3) begin
            lose = 1;
          end
          else begin
            b_seq = 0;
            nums = 0;
          end
        end
      end
    end
  end
endmodule

