module Interconnect (
  input             clk_in,
  output            clk_out1,
  output            clk_out2,
  input             reset,
  output reg        locked
);

  reg [3:0]         counter1;
  reg [3:0]         counter2;
  reg               clk_out1_reg;
  reg               clk_out2_reg;

  always @(posedge clk_in or posedge reset) begin
    if (reset) begin
      counter1 <= 4'b0000;
      counter2 <= 4'b0000;
      clk_out1_reg <= 1'b0;
      clk_out2_reg <= 1'b0;
      locked <= 1'b0;
    end else begin
      if (counter1 == 4'b1000) begin
        counter1 <= 4'b0000;
        clk_out1_reg <= ~clk_out1_reg;
      end else begin
        counter1 <= counter1 + 1;
      end

      if (counter2 == 4'b1000) begin
        counter2 <= 4'b0000;
        clk_out2_reg <= ~clk_out2_reg;
      end else begin
        counter2 <= counter2 + 1;
      end

      if (counter1 == 4'b0001 && counter2 == 4'b0000) begin
        locked <= 1'b1;
      end else begin
        locked <= 1'b0;
      end
    end
  end

  assign clk_out1 = clk_out1_reg;
  assign clk_out2 = clk_out2_reg;

endmodule

module top_module( 
