module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [3:0] a1,   // 4-bit input for adder 1
    input [3:0] a2,   // 4-bit input for adder 2
    input select,     // Select input to choose between addition and subtraction
    output [3:0] q    // 4-bit output from the selected operation
);

    wire [3:0] adder1_out;
    wire [3:0] adder2_out;
    wire [3:0] func_out;

    adder adder1(.clk(clk), .reset(reset), .a(a1), .b(a2), .q(adder1_out));
    adder adder2(.clk(clk), .reset(reset), .a(a1), .b(a2), .q(adder2_out));

    assign func_out = (select == 0) ? (adder1_out + adder2_out) : (adder1_out - adder2_out);

    assign q = func_out;

endmodule

module adder (
    input clk,
    input reset,      // Synchronous active-high reset
    input [3:0] a,
    input [3:0] b,
    output [3:0] q
);

    reg [3:0] sum;

    always @(posedge clk) begin
        if (reset) begin
            sum <= 4'b0;
        end else begin
            sum <= a + b;
        end
    end

    assign q = sum;

endmodule

