module binary_counter_calculator_display (
    input clk,
    input reset,      // Synchronous active-high reset
    input [3:0] d,    // 4-bit input for the binary calculator
    output [6:0] seg  // 7-segment display output
);

    // Binary Counter
    reg [3:0] count;
    always @(posedge clk) begin
        if (reset) begin
            count <= 4'b0000;
        end else begin
            count <= count + 1;
        end
    end

    // Binary Calculator
    wire [3:0] a = count;
    wire [3:0] b = d;
    wire [3:0] out_and = a & b;
    wire [3:0] out_or = a | b;
    wire [3:0] out_xor = a ^ b;

    // 7-Segment Display Decoder
    reg [6:0] seg_out;
    always @(count) begin
        case (count)
            4'b0000: seg_out = 7'b1000000; // 0
            4'b0001: seg_out = 7'b1111001; // 1
            4'b0010: seg_out = 7'b0100100; // 2
            4'b0011: seg_out = 7'b0110000; // 3
            4'b0100: seg_out = 7'b0011001; // 4
            4'b0101: seg_out = 7'b0010010; // 5
            4'b0110: seg_out = 7'b0000010; // 6
            4'b0111: seg_out = 7'b1111000; // 7
            4'b1000: seg_out = 7'b0000000; // 8
            4'b1001: seg_out = 7'b0010000; // 9
            4'b1010: seg_out = 7'b0001000; // A
            4'b1011: seg_out = 7'b0000011; // B
            4'b1100: seg_out = 7'b1000110; // C
            4'b1101: seg_out = 7'b0100001; // D
            4'b1110: seg_out = 7'b0000110; // E
            4'b1111: seg_out = 7'b0001110; // F
            default: seg_out = 7'b1111111; // Blank
        endcase
    end

    assign seg = seg_out;

endmodule

module RLE (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 8; // number of input signals
parameter m = 8; // number of output signals

reg [n-1:0] encoded_data;
reg [m-1:0] decoded_data;

integer i, j, k;

always @(*) begin
  // Run-length encoding algorithm
  i = 0;
  j = 0;
  while (i < n) begin
    k = i + 1;
    while ((k < n) && (in[k] == in[i])) begin
      k = k + 1;
    end
    encoded_data[j] = in[i];
    encoded_data[j+1] = k - i;
    j = j + 2;
    i = k;
  end

  // Run-length decoding algorithm
  i = 0;
  j = 0;
  while (i < m) begin
    for (k = 0; k < decoded_data[j+1]; k = k + 1) begin
      decoded_data[i] = encoded_data[j];
      i = i + 1;
    end
    j = j + 2;
  end
end

assign out = decoded_data;

endmodule

