module Adder_Subtractor_4bit (A, B, Sub, Sum, Diff);
input [3:0] A, B;
input Sub;
output [3:0] Sum, Diff;

wire [3:0] A_inv, B_inv, B_neg, Cin, D;
wire [4:0] S;

// Invert A and B
assign A_inv = ~A;
assign B_inv = ~B;

// Create 2's complement of B if Sub is 1
assign B_neg = B_inv + 1;

// Create carry input for subtraction
assign Cin = Sub;

// Perform addition or subtraction
assign S = {Cin, A} + {Sub, B_neg};

// Extract Sum and Diff from S
assign Sum = S[3:0];
assign Diff = S[3:0] + Sub;

// Create overflow flag
assign D = A_inv + B + Cin;

endmodule

module top_module(
    input clk,
    input reset,
    input [7:0] a_in,
    input [7:0] b_in,
    output [7:0] add_out,
    output [3:0] sub_out,
    output [7:0] final_out
);

    // 4-bit ripple carry adder
    wire [3:0] adder_out;
    ripple_carry_adder adder(.a(a_in[3:0]), .b(b_in[3:0]), .sum(adder_out));

    // 4-bit ripple borrow subtractor
    wire [3:0] subtractor_out;
    ripple_borrow_subtractor subtractor(.a(a_in[3:0]), .b(b_in[3:0]), .diff(subtractor_out));

    // 2's complementer for subtractor output
    wire [3:0] twos_comp_out;
    twos_complementer twos_comp(.in(subtractor_out), .out(twos_comp_out));

    // Final output
    wire [7:0] final_out_temp;
    ripple_carry_adder final_adder(.a(adder_out), .b(twos_comp_out), .sum(final_out_temp));

    // Output ports
    assign add_out = {4'b0, adder_out};
    assign sub_out = subtractor_out;
    assign final_out = final_out_temp;

    // Reset
    always @(posedge clk) begin
        if (reset) begin
            adder.reset <= 1;
            subtractor.reset <= 1;
        end else begin
            adder.reset <= 0;
            subtractor.reset <= 0;
        end
    end

endmodule

// 4-bit ripple carry adder
module ripple_carry_adder(
    input [3:0] a,
    input [3:0] b,
    output [3:0] sum
);

    assign sum[0] = a[0] ^ b[0];
    assign sum[1] = a[1] ^ b[1] ^ sum[0];
    assign sum[2] = a[2] ^ b[2] ^ sum[1];
    assign sum[3] = a[3] ^ b[3] ^ sum[2];

endmodule

// 4-bit ripple borrow subtractor
module ripple_borrow_subtractor(
    input [3:0] a,
    input [3:0] b,
    output [3:0] diff
);

    assign diff[0] = a[0] ^ b[0];
    assign diff[1] = a[1] ^ b[1] ^ ~a[0] & b[0];
    assign diff[2] = a[2] ^ b[2] ^ ~a[1] & b[1] ^ ~a[0] & b[0];
    assign diff[3] = a[3] ^ b[3] ^ ~a[2] & b[2] ^ ~a[1] & b[1] ^ ~a[0] & b[0];

endmodule

// 2's complementer
module twos_complementer(
    input [3:0] in,
    output [3:0] out
);

    assign out = ~in + 1;

endmodule

