module priority_encoder (
    input [7:0] in,
    output reg [2:0] pos
);
    wire [7:0] gray;
    wire [2:0] gray_pos;
    wire [2:0] bin_pos;

    assign gray = in ^ (in >> 1);

    binary_to_gray_converter binary_to_gray(
        .binary(in),
        .gray(gray)
    );

    gray_to_binary_converter gray_to_binary(
        .gray(gray_pos),
        .binary(bin_pos)
    );

    assign pos = bin_pos - 1;
