module binary_to_gray_converter (
    input [7:0] binary,
    output reg [7:0] gray
);
    assign gray[0] = binary[0];
    always @* begin
        gray[1] = binary[1] ^ binary[0];
        gray[2] = binary[2] ^ binary[1];
        gray[3] = binary[3] ^ binary[2];
        gray[4] = binary[4] ^ binary[3];
        gray[5] = binary[5] ^ binary[4];
        gray[6] = binary[6] ^ binary[5];
        gray[7] = binary[7] ^ binary[6];
    end
endmodule
module gray_to_binary_converter (
    input [2:0] gray,
    output reg [2:0] binary
);
    always @* begin
        binary[0] = gray[0];
        binary[1] = gray[0] ^ gray[1];
        binary[2] = gray[1] ^ gray[2];
