module top_module( 
    input wire [7:0] in1,
    input wire [7:0] in2,
    output wire [7:0] out_and,
    output wire [7:0] out_or,
    output wire [7:0] out_xor 
);

// BDD circuit for reducing logic gates
wire [7:0] bdd_and;
wire [7:0] bdd_or;
wire [7:0] bdd_xor;

assign bdd_and = in1 & in2;
assign bdd_or = in1 | in2;
assign bdd_xor = in1 ^ in2;

// Adder circuit for splitting 16-bit output into two 8-bit outputs
wire [15:0] adder_out;
wire [7:0] ripple_out;
wire [7:0] carry_select_out;

assign adder_out = {8'b0, bdd_and} + {8'b0, bdd_or};
ripple_carry_adder ripple(.a(adder_out[7:0]), .b(adder_out[15:8]), .cin(1'b0), .s(ripple_out), .cout());
carry_select_adder carry_select(.a(adder_out[7:0]), .b(adder_out[15:8]), .cin(1'b0), .s(carry_select_out));

// Functional module for performing bitwise AND, OR, and XOR operations on two 8-bit outputs
assign out_and = bdd_and;
assign out_or = bdd_or;
assign out_xor = bdd_xor;

endmodule

// Ripple carry adder module
module ripple_carry_adder(
    input wire [7:0] a,
    input wire [7:0] b,
    input wire cin,
    output reg [7:0] s,
    output reg cout
);

always @(*) begin
    s = a + b + cin;
    cout = (s[8] == 1) ? 1 : 0;
end

endmodule

// Carry select adder module
module carry_select_adder(
    input wire [7:0] a,
    input wire [7:0] b,
    input wire cin,
    output reg [7:0] s
);

wire [7:0] p;
wire [7:0] g;
wire [7:0] c;

assign p = a ^ b;
assign g = a & b;
assign c = {1'b0, cin};

always @(*) begin
    if (c[1] == 0) begin
        s = p + c;
    end else begin
        s = g + c;
    end
end

endmodule

module top_module (
    input clk,
    input reset,      // Asynchronous active-high reset
    input load,       // Active-high parallel load input
    input [3:0] load_value, // 4-bit load value
    output [3:0] q,  // 4-bit output from the functional module
    output carry);   // Carry output from the counter

    // Counter module
    reg [3:0] counter;
    wire [3:0] next_counter;
    assign carry = (counter == 9) ? 1'b1 : 1'b0;

    always @ (posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 4'b0;
        end else if (load) begin
            counter <= load_value;
        end else begin
            counter <= next_counter;
        end
    end

    assign next_counter = (counter == 4'b1001) ? 4'b0000 : counter + 1;

    // XOR gate module
    wire xor_output;
    wire and_output1;
    wire and_output2;
    wire not_output;

    assign and_output1 = counter[1] & counter[3];
    assign and_output2 = ~counter[1] & ~counter[3];
    assign not_output = and_output1 | and_output2;
    assign xor_output = ~not_output;

    // Functional module
    reg [3:0] functional_output;

    always @ (posedge clk or posedge reset) begin
        if (reset) begin
            functional_output <= 4'b0;
        end else if (load) begin
            functional_output <= load_value ^ xor_output;
        end else begin
            functional_output <= next_functional_output;
        end
    end

    wire [3:0] next_functional_output;
    assign next_functional_output = (functional_output + xor_output) & 4'hF;

    assign q = functional_output;

endmodule

module decade_counter_mux (
    input clk,
    input slowena,
    input reset,
    input [255:0] in,
    output out
);

    reg [3:0] johnson_counter;
    wire [7:0] mux_select;
    wire [255:0] mux_input;
    wire mux_output;

    // Johnson counter with synchronous reset
    always @(posedge clk, negedge reset) begin
        if (!reset) begin
            johnson_counter <= 4'b0001;
        end else if (slowena) begin
            johnson_counter <= johnson_counter ^ 4'b0010;
        end
    end

    // Multiplexer
    assign mux_select = {johnson_counter[2:0], 3'b000};
    assign mux_input = in;
    assign mux_output = mux_input[mux_select];

    // Output
    assign out = mux_output[0];

endmodule

module lcd_driver (
  input clk,
  input reset,
  input enable,
  input in_cmd,
  input [7:0] in_data,
  output [7:0] lcd_pins,
  output rs,
  output rw,
  output backlight
);

  // Define internal signals
  reg [7:0] lcd_data;
  reg lcd_rs;
  reg lcd_rw;
  reg lcd_backlight;
  reg lcd_enable;

  // Define constants for LCD commands
  parameter LCD_CLEAR_DISPLAY = 8'h01;
  parameter LCD_RETURN_HOME = 8'h02;
  parameter LCD_ENTRY_MODE_SET = 8'h04;
  parameter LCD_DISPLAY_ON_OFF_CONTROL = 8'h08;
  parameter LCD_CURSOR_DISPLAY_SHIFT = 8'h10;
  parameter LCD_FUNCTION_SET = 8'h20;
  parameter LCD_SET_CGRAM_ADDRESS = 8'h40;
  parameter LCD_SET_DDRAM_ADDRESS = 8'h80;

  // Define state variables
  reg [2:0] state;
  parameter STATE_IDLE = 3'b000;
  parameter STATE_WAIT_ENABLE = 3'b001;
  parameter STATE_SEND_COMMAND = 3'b010;
  parameter STATE_SEND_DATA = 3'b011;

  // Initialize internal signals and state variables
  initial begin
    lcd_data <= 8'h00;
    lcd_rs <= 1'b0;
    lcd_rw <= 1'b0;
    lcd_backlight <= 1'b0;
    lcd_enable <= 1'b0;
    state <= STATE_IDLE;
  end

  // Define state machine
  always @(posedge clk) begin
    case (state)
      STATE_IDLE: begin
        if (reset) begin
          state <= STATE_IDLE;
        end else if (enable) begin
          state <= STATE_WAIT_ENABLE;
        end
      end
      STATE_WAIT_ENABLE: begin
        if (reset) begin
          state <= STATE_IDLE;
        end else if (!enable) begin
          state <= STATE_IDLE;
        end else if (in_cmd) begin
          state <= STATE_SEND_COMMAND;
        end else begin
          state <= STATE_SEND_DATA;
        end
      end
      STATE_SEND_COMMAND: begin
        lcd_data <= in_data;
        lcd_rs <= 1'b0;
        lcd_rw <= 1'b0;
        lcd_backlight <= 1'b1;
        lcd_enable <= 1'b1;
        state <= STATE_IDLE;
      end
      STATE_SEND_DATA: begin
        lcd_data <= in_data;
        lcd_rs <= 1'b1;
        lcd_rw <= 1'b0;
        lcd_backlight <= 1'b1;
        lcd_enable <= 1'b1;
        state <= STATE_IDLE;
      end
    endcase
  end

  // Assign outputs
  assign lcd_pins = lcd_data;
  assign rs = lcd_rs;
  assign rw = lcd_rw;
  assign backlight = lcd_backlight;

endmodule

module parallel_load_shift (
  input clk,
  input reset,
  input [7:0] data_in,
  input [2:0] shift_amount,
  output reg [7:0] shift_out
);

  reg [7:0] shift_reg;

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      shift_reg <= 8'b0;
    end else begin
      shift_reg <= {shift_reg[7:shift_amount], data_in};
    end
  end

  assign shift_out = shift_reg;

endmodule

