module top_module (
  input clk,
  input reset,
  input [7:0] data_in,
  input [2:0] shift_amount,
  input [49:0] in,
  input select,
  output [7:0] shift_out,
  output reg out_nand,
  output reg out_nor,
  output reg out_xnor,
  output reg [49:0] final_output
);

  wire [7:0] shift_out_wire;
  wire [49:0] in_wire;

  parallel_load_shift shift_module (
    .clk(clk),
    .reset(reset),
    .data_in(data_in),
    .shift_amount(shift_amount),
    .shift_out(shift_out_wire)
  );

  combinational_circuit comb_module (
    .in(in),
    .out_nand(out_nand),
    .out_nor(out_nor),
    .out_xnor(out_xnor)
  );

  functional_module func_module (
    .shift_out(shift_out_wire),
    .in(in_wire),
    .final_output(final_output)
  );

  assign in_wire = select ? 50'b0 : in;

endmodule

module state_machine (
  input clk,
  input reset,
  input x,
  input [5:0] y,
  output Y2,
  output Y4
);

  reg [5:0] state, next_state;
  reg [5:0] Y;

  parameter A = 6'b000001;
  parameter B = 6'b000010;
  parameter C = 6'b000100;
  parameter D = 6'b001000;
  parameter E = 6'b010000;
  parameter F = 6'b100000;

  // State transition logic
  always @ (posedge clk) begin
    if (reset) begin
      state <= A;
    end else begin
      state <= next_state;
    end
  end

  always @ (state, x) begin
    case (state)
      A: begin
        if (x) begin
          next_state = B;
        end else begin
          next_state = C;
        end
      end

      B: begin
        if (x) begin
          next_state = C;
        end else begin
          next_state = D;
        end
      end

      C: begin
        if (x) begin
          next_state = D;
        end else begin
          next_state = E;
        end
      end

      D: begin
        if (x) begin
          next_state = E;
        end else begin
          next_state = F;
        end
      end

      E: begin
        if (x) begin
          next_state = F;
        end else begin
          next_state = A;
        end
      end

      F: begin
        if (x) begin
          next_state = A;
        end else begin
          next_state = B;
        end
      end
    endcase
  end

  // Output logic
  always @ (state) begin
    case (state)
      A: Y = A;
      B: Y = B;
      C: Y = C;
      D: Y = D;
      E: Y = E;
      F: Y = F;
    endcase
  end

  assign Y2 = Y[2];
  assign Y4 = Y[4];

endmodule

module top_module( 
    input wire [15:0] in,
    input wire select,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo );

    wire [7:0] in_hi;
    wire [7:0] in_lo;

    // Split the input word into two bytes
    assign in_hi = in[15:8];
    assign in_lo = in[7:0];

    // Multiplexer to select between decoder output and input bytes
    wire [7:0] mux_out;
    assign mux_out = select ? in_hi : in_lo;

    // Decoder to select between input bytes
    wire [7:0] dec_out;
    assign dec_out = select ? in_lo : in_hi;

    // Control logic to select between decoder output and multiplexer output
    assign out_hi = select ? mux_out : dec_out;
    assign out_lo = select ? dec_out : mux_out;

endmodule

module inst_cache (
  input clk,
  input rst,
  input v_pc,
  input [31:0] pc,
  input [127:0] inst_4word,
  input v_inst_4word,
  output v_ic_req,
  output local_or_OUT,
  output [47:0] req_msg,
  output v_inst,
  output [31:0] inst
);

  // Define cache parameters
  parameter inst_idle = 2'b00;
  parameter inst_comp_tag = 2'b01;
  parameter inst_gen_req = 2'b10;
  parameter inst_wait_rep = 2'b11;
  parameter local_id = 2'b00;
  parameter instreq_cmd = 5'b00110;

  // Define cache state variables
  reg [1:0] inst_cstate;
  reg [1:0] inst_nstate;
  reg tag_we;
  reg tag_re;
  reg data_we;
  reg data_re;
  reg [5:0] state_tag_in;
  wire [5:0] state_tag_out;
  reg [31:0] seled_addr;
  reg [127:0] data_write;
  wire [127:0] data_read;
  reg [31:0] inst1;
  reg [31:0] inst2;
  reg v_inst;
  reg local_or_OUT;
  reg [47:0] req_msg;
  reg inst1_inst2;
  reg v_ic_req;

  // Instantiate tag and data RAMs
  SP_BRAM_SRd #(32,6,5) tag_ram (
    .clk(clk),
    .we(tag_we),
    .re(tag_re),
    .a(seled_addr[8:4]),
    .di(state_tag_in),
    .dout(state_tag_out)
  );
  SP_BRAM_SRd #(32,128,5) data_ram (
    .clk(clk),
    .we(data_we),
    .re(data_re),
    .a(seled_addr[8:4]),
    .di(data_write),
    .dout(data_read)
  );

  // Define cache FSM
  always @(posedge clk) begin
    if (rst) begin
      inst_cstate <= inst_idle;
    end else begin
      inst_cstate <= inst_nstate;
    end
  end

  always @(*) begin
    // Set default values
    v_inst = 1'b0;
    v_ic_req = 1'b0;
    tag_we = 1'b0;
    tag_re = 1'b0;
    data_we = 1'b0;
    data_re = 1'b0;
    state_tag_in = 5'b00000;
    seled_addr = 32'h0000;
    data_write = 128'h0000;
    local_or_OUT = 1'b0;
    req_msg = 48'h0000;
    inst_nstate = inst_cstate;
    inst1 = data_read[31:0];
    inst2 = inst_4word[31:0];
    inst1_inst2 = 1'b0;

    // Read out correct word (32-bit) from cache (to if_id)
    case (pc[3:2])
      2'b00: inst1 = data_read[31:0];
      2'b01: inst1 = data_read[63:32];
      2'b10: inst1 = data_read[95:64];
      2'b11: inst1 = data_read[127:96];
    endcase

    // Read inst_word directly from inst_4word (to if_id)
    case (pc[3:2])
      2'b00: inst2 = inst_4word[31:0];
      2'b01: inst2 = inst_4word[63:32];
      2'b10: inst2 = inst_4word[95:64];
      2'b11: inst2 = inst_4word[127:96];
    endcase

    // Define cache FSM states
    case (inst_cstate)
      inst_idle:
        begin
          if (v_pc) begin
            inst_nstate = inst_comp_tag;
          end
        end
      inst_comp_tag:
        begin
          tag_re = 1'b1;
          data_re = 1'b1;
          if (pc[12:9] == state_tag_out[3:0]) begin
            // Tag equals
            if (state_tag_out[5:4] == 2'b10) begin
              // Read hit
              v_inst = 1'b1;
              inst1_inst2 = 1'b0;
              inst_nstate = inst_idle;
            end
            /*else if (state_tag_out[5:4] == 2'b01) begin
              // State is inv, so read miss
              if (pc[12:11] == local_id) begin
                req_local_remote = 1'b0;
              end
              nstate = inst_gen_req;
              // oneORmore = 1'b0;
            end*/
          end else begin
            // Gen new tag to tag RAM
            tag_we = 1'b1;
            /* New tag */
            state_tag_in = {2'b01, pc[12:9]};
            inst_nstate = inst_gen_req;
          end
        end
      inst_gen_req:
        begin
          if (pc[12:11] == local_id) begin
            local_or_OUT = 1'b0;
          end
          req_msg = {pc[12:11], 1'b1, local_id, 1'b0, instreq_cmd, 5'b00000, pc};
          v_ic_req = 1'b1;
          inst_nstate = inst_wait_rep;
        end
      inst_wait_rep:
        begin
          if (v_inst_4word) begin
            tag_re = 1'b1;
            data_write = inst_4word;
            data_we = 1'b1;
            inst1_inst2 = 1'b1;
            v_inst = 1'b1;
            // Gen new tag to tag RAM
            tag_we = 1'b1;
            /* New tag */
            state_tag_in = {2'b10, pc[12:9]}; // 10 means valid
          end
        end
    endcase
  end

  assign inst = inst1_inst2 ? inst2 : inst1;

endmodule

module waveform_circuit (
  input clock,
  input a,
  input p,
  output q,
  output r
);

  reg [1:0] state;
  reg q_reg, r_reg;

  always @(posedge clock) begin
    case (state)
      2'b00:
        begin
          q_reg <= 1'b0;
          r_reg <= 1'b0;
          if (a) begin
            state <= 2'b01;
          end
        end
      2'b01:
        begin
          q_reg <= 1'b0;
          r_reg <= 1'b0;
          if (a && p) begin
            state <= 2'b10;
          end
        end
      2'b10:
        begin
          q_reg <= 1'b1;
          r_reg <= 1'b0;
          state <= 2'b11;
        end
      2'b11:
        begin
          q_reg <= 1'b1;
          r_reg <= 1'b1;
          state <= 2'b00;
        end
    endcase
  end

  assign q = q_reg;
  assign r = r_reg;

endmodule

module calculator(
    input [31:0] data,
    input trigger,
    output reg [31:0] result
);

    reg [7:0] operand1;
    reg [7:0] operand2;
    reg [3:0] operator;

    always @(*) begin
        operand1 = data[7:0];
        operand2 = data[15:8];
        operator = data[23:16];
    end

    always @(posedge trigger) begin
        case(operator)
            4'b0000: result <= $signed(operand1) + $signed(operand2);
            4'b0001: result <= $signed(operand1) - $signed(operand2);
            4'b0010: result <= $signed(operand1) * $signed(operand2);
            4'b0011: begin
                        if (operand2 == 0) begin
                            result <= 32'h7FFFFFFF; // Maximum value for signed 32-bit integer
                        end else begin
                            result <= $signed(operand1) / $signed(operand2);
                        end
                     end
            default: result <= 0;
        endcase

        // Clamp result to maximum or minimum value if overflow or underflow occurs
        if (result > 32'h7FFFFFFF) begin
            result <= 32'h7FFFFFFF;
        end else if (result < 32'h80000000) begin
            result <= 32'h80000000;
        end
    end

endmodule

module memory_controller (
  input  [15:0] din,
  input         din_stb,
  input         xclk,
  input         mclk,
  input         rst,
  output [15:0] dout,
  output        dout_stb
);

  reg   [1:0] wa;
  reg   [1:0] wa_mclk;
  reg   [1:0] wa_mclk_d;
  reg         rst_mclk;
  reg   [1:0] ra;
  reg   [1:0] ra_next;
  reg         inc_ra;
  wire [15:0] pre_dout;
  reg  [15:0] dout;
  reg         dout_stb;

  always @ (posedge xclk) begin
    if      (rst)     wa[1:0] <= 2'h0;
    else if (din_stb) wa[1:0] <={wa[0],~wa[1]};
  end

  always @ (posedge mclk) begin
    wa_mclk[1:0]   <= wa[1:0];
    wa_mclk_d[1:0] <= wa_mclk[1:0];
