  output reg [APP_DATA_WIDTH-1:0] app_rd_data,
  output reg [2*nCK_PER_CLK-1:0] app_ecc_multiple_err,
  output reg [DATA_BUF_ADDR_WIDTH-1:0] rd_data_buf_addr_r,
  output reg ram_init_done_r,
  output reg [3:0] ram_init_addr
);

reg [DATA_BUF_ADDR_WIDTH-1:0] wr_data_buf_addr;

generate
  if(DATA_BUF_ADDR_WIDTH > 4) begin
    assign wr_data_buf_addr[DATA_BUF_ADDR_WIDTH-1:4] = 0;
  end
endgenerate

assign app_rdy = 1'b1;
assign use_addr = 1'b1;
assign rank = 0;
assign bank = 0;
assign row = 0;
assign col = 0;
assign size = app_sz;
assign cmd = app_cmd;
assign hi_priority = app_hi_pri;
assign data_buf_addr = app_addr;
assign app_wdf_rdy = 1'b1;

always @(posedge clk) begin
  if(rst) begin
    rd_accepted <= 1'b0;
    wr_accepted <= 1'b0;
    app_rd_data_valid <= 1'b0;
    app_rd_data_end <= 1'b0;
    app_rd_data <= 0;
    app_ecc_multiple_err <= 0;
    rd_data_buf_addr_r <= 0;
    ram_init_done_r <= 1'b0;
    ram_init_addr <= 0;
  end else begin
    if(app_en && accept_ns && app_cmd == 3'b001) begin // read command
      if(!rd_buf_full) begin
        rd_accepted <= 1'b1;
        data_buf_addr <= rd_data_addr;
        rd_data_buf_addr_r <= rd_data_addr;
      end
    end else begin
      rd_accepted <= 1'b0;
    end

    if(app_en && accept_ns && app_cmd == 3'b010) begin // write command
      if(wr_req_16) begin
        wr_accepted <= 1'b1;
        wr_data_buf_addr <= wr_data_offset;
        wr_data_mask <= app_wdf_mask;
        wr_data <= app_wdf_data;
        raw_not_ecc <= app_wdf_data;
      end
    end else begin
      wr_accepted <= 1'b0;
    end

    if(wr_data_en) begin
      app_wdf_rdy <= 1'b0;
      if(app_wdf_wren) begin
        wr_data_buf_addr <= wr_data_buf_addr + 1;
        if(wr_data_buf_addr == wr_data_addr) begin
          app_wdf_rdy <= 1'b1;
        end
      end
    end else begin
      app_wdf_rdy <= 1'b1;
    end

    if(rd_data_en) begin
      if(rd_data_buf_addr_r == rd_data_addr) begin
        app_rd_data_valid <= 1'b1;
        app_rd_data_end <= 1'b1;
        app_rd_data <= 0;
        app_ecc_multiple_err <= 0;
        rd_data_buf_addr_r <= 0;
      end else begin
        app_rd_data_valid <= 1'b0;
        app_rd_data_end <= 1'b0;
        app_rd_data <= 0;
        app_ecc_multiple_err <= 0;
        rd_data_buf_addr_r <= rd_data_buf_addr_r + 1;
      end
    end
  end

  if(app_cmd == 3'b111) begin // RAM initialization
    ram_init_done_r <= 1'b0;
    ram_init_addr <= app_addr[3:0];
  end else begin
    ram_init_done_r <= 1'b1;
  end
end

endmodule

module add_sub_16bit (
  input [15:0] A,
  input [15:0] B,
  input Cin,
  input Sub,
  output [15:0] Sum,
  output Cout
);

  wire [15:0] A_inv;
  wire [15:0] B_inv;
  wire [15:0] Cin_inv;
  wire [15:0] Sub_inv;
  wire [15:0] Sum_inv;
  wire Cout_inv;

  assign A_inv = ~A;
  assign B_inv = ~B;
  assign Cin_inv = ~Cin;
  assign Sub_inv = ~Sub;

  assign Sum_inv = (Sub_inv & (A_inv + B + Cin)) | (~Sub_inv & (A + B + Cin));
  assign Cout_inv = (Sub_inv & (A_inv + B + Cin)) | (~Sub_inv & ((A & B) | (A & Cin) | (B & Cin)));

  assign Sum = ~Sum_inv + 1;
  assign Cout = ~Cout_inv;

endmodule

