        tx <= 1'b1;
    end else begin
        case (state)
            4'b0000: begin // IDLE
                if (tx_data[0] == 1'b0) begin
                    start_bit <= 1'b0;
                    data_reg <= tx_data;
                    count <= 4'b0001;
                    state <= 4'b0001;
                end
            end
