                start_bit <= 1'b1;
                count <= count + 1;
                if (count == CLK_FREQ / BAUD_RATE) begin
                    count <= 4'b0000;
                    state <= 4'b0010;
                end
            end
            4'b0010: begin // DATA
                data_reg <= {data_reg[6:0], 1'b0};
