                    end else begin
                        state <= 4'b0010;
                    end
                end
            end
            4'b0100: begin // STOP
                start_bit <= 1'b1;
                count <= count + 1;
                if (count == CLK_FREQ / BAUD_RATE) begin
                    count <= 4'b0000;
                    state <= 4'b0000;
