module ripple_carry_adder(
  input [3:0] A,
  input [3:0] B,
  input Cin,
  output [3:0] S,
  output Cout
);

  wire [3:0] C;

  assign C[0] = Cin;

  genvar i;
  generate
    for (i = 0; i < 4; i = i + 1) begin
      assign S[i] = A[i] ^ B[i] ^ C[i];
      assign C[i+1] = (A[i] & B[i]) | (A[i] & C[i]) | (B[i] & C[i]);
    end
  endgenerate

  assign Cout = C[4];

endmodule

