module carry_select_adder (
    input [31:0] a,
    input [31:0] b,
    output [31:0] sum
);

wire [31:0] p, g, c;

genvar i;
generate
    for (i = 0; i < 32; i = i + 1) begin : gen
        assign p[i] = a[i] ^ b[i];
        assign g[i] = a[i] & b[i];
        assign c[i] = i == 0 ? 1'b0 : g[i-1] | (p[i-1] & c[i-1]);
    end
endgenerate

assign sum = p | (g & c);

endmodule

