        q <= q;
    end else begin
        q <= D;
    end
end

assign Q = q;
assign Q_N = ~q;

endmodule

module register_adder(
    input [3:0] data_in,
    input [3:0] reg_in,
    input ctrl,
    input clk,
    input reset,
    output reg [3:0] reg_out
);

reg [3:0] temp;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        reg_out <= 4'b0000;
    end else if (ctrl) begin
        temp <= data_in + reg_in;
        reg_out <= temp;
    end else begin
        reg_out <= reg_in;
    end
end

endmodule

module shift_register (
  input [n-1:0] in,
  input shift_dir,
  input shift_mode,
  input clk,
  input reset,
  output [m-1:0] out
);

parameter n = 8; // number of input bits
parameter m = 8; // number of output bits
parameter p = 4; // number of bits to shift
parameter q = 0; // shift mode (0 for serial, 1 for parallel)

reg [n-1:0] shift_reg; // shift register
reg [m-1:0] out_reg; // output register

always @(posedge clk) begin
  if (reset) begin
    shift_reg <= 0;
    out_reg <= 0;
  end else begin
    if (shift_dir) begin
      if (shift_mode) begin // parallel shift
        out_reg <= {in[(n-1):(n-p)], shift_reg[(p-1):0]};
        shift_reg <= in;
      end else begin // serial shift
        out_reg <= {in[n-1], shift_reg[(n-2):0]};
        shift_reg <= {in[(n-2):0], 1'b0};
      end
    end else begin
      if (shift_mode) begin // parallel shift
        out_reg <= {shift_reg[(m-p-1):0], in[(n-p-1):0]};
        shift_reg <= in;
      end else begin // serial shift
        out_reg <= {shift_reg[(n-1)], in[0]};
        shift_reg <= {shift_reg[(n-2):0], in[n-1]};
      end
    end
  end
end

assign out = out_reg;

endmodule

module VgaDriver(
  input clk,
  input [14:0] pixel,
  input sync,
  input border,
  output reg vga_h,
  output reg vga_v,
  output reg [3:0] vga_r,
  output reg [3:0] vga_g,
  output reg [3:0] vga_b,
  output reg [9:0] vga_hcounter,
  output reg [9:0] vga_vcounter,
  output reg [9:0] next_pixel_x
);

  // Horizontal and vertical counters
  reg [9:0] h, v;
  wire hpicture = (h < 512);                    // 512 lines of picture
  wire hsync_on = (h == 512 + 23 + 35);         // HSync ON, 23+35 pixels front porch
  wire hsync_off = (h == 512 + 23 + 35 + 82);   // Hsync off, 82 pixels sync
  wire hend = (h == 681);                       // End of line, 682 pixels.

  wire vpicture = (v < 480);                    // 480 lines of picture
  wire vsync_on  = hsync_on && (v == 480 + 10); // Vsync ON, 10 lines front porch.
  wire vsync_off = hsync_on && (v == 480 + 12); // Vsync OFF, 2 lines sync signal
  wire vend = (v == 523);                       // End of picture, 524 lines. (Should really be 525 according to NTSC spec)
  wire inpicture = hpicture && vpicture;

  assign vga_hcounter = h;
  assign vga_vcounter = v;

  wire [9:0] new_h = (hend || sync) ? 0 : h + 1;
  assign next_pixel_x = {sync ? 1'b0 : hend ? !v[0] : v[0], new_h[8:0]};

  always @(posedge clk) begin
    h <= new_h;
    if (sync) begin
      vga_v <= 1;
      vga_h <= 1;
      v <= 0;
    end else begin
      vga_h <= hsync_on ? 0 : hsync_off ? 1 : vga_h;
      if (hend)
        v <= vend ? 0 : v + 1;
      vga_v <= vsync_on ? 0 : vsync_off ? 1 : vga_v;
      if (border && (h == 0 || h == 511 || v == 0 || v == 479)) begin
        vga_r <= 4'b1111;
        vga_g <= 4'b1111;
        vga_b <= 4'b1111;
      end else if (!inpicture) begin
        vga_r <= 4'b0000;
        vga_g <= 4'b0000;
        vga_b <= 4'b0000;
      end else begin
        vga_r <= pixel[4:1];
        vga_g <= pixel[9:6];
        vga_b <= pixel[14:11];
      end
    end
  end
endmodule

module four_bit_adder(A, B, C_in, S, C_out);
  input [3:0] A;
  input [3:0] B;
  input C_in;
  output [3:0] S;
  output C_out;

  wire c1, c2, c3;

  assign c1 = A[0] & B[0];
  assign c2 = A[0] | B[0];
  assign S[0] = A[0] ^ B[0] ^ C_in;
  assign c3 = A[1] & B[1];
  assign S[1] = A[1] ^ B[1] ^ c1;
  assign c1 = c1 | c3;
  assign c3 = A[2] & B[2];
  assign S[2] = A[2] ^ B[2] ^ c2;
  assign c2 = c2 | c3;
  assign c3 = A[3] & B[3];
  assign S[3] = A[3] ^ B[3] ^ c1;
  assign C_out = c2 | c3;

endmodule

module calculator(
    input clk,
    input [7:0] A,
    input [7:0] B,
    input [1:0] OP,
    output reg [7:0] result
);

    always @(posedge clk) begin
        case (OP)
            2'b00: result <= A + B;
            2'b01: result <= A - B;
            2'b10: result <= A * B;
            2'b11: begin
                if (B == 0) begin
                    result <= 8'b0;
                end else begin
                    result <= A / B;
                end
            end
        endcase
    end

endmodule

module counter(
    input reset,
    input clk,
    output reg [7:0] count
);

always @(posedge clk) begin
    if (reset) begin
        count <= 0;
    end else if (count == 255) begin
        count <= 0;
    end else begin
        count <= count + 1;
    end
end

endmodule

module UART_RX(
    input rst, clk, baud_edge, rx,
    output [7:0] data,
    output data_ready, framing_error
);
    parameter OVERSAMPLE = 8;
    localparam FIND_EDGE = 3'd1, START = 3'd2, DATA = 3'd3, END = 3'd4;

    reg prev_rx;
    reg [7:0] data_reg;
    reg [2:0] data_counter;
    reg [2:0] state = 0;
    reg [$clog2(OVERSAMPLE+OVERSAMPLE/2)-1:0] over_sample_counter = 0;

    reg data_ready_reg = 0;
    reg framing_error_reg = 0;

    assign data = data_reg;
    assign data_ready = data_ready_reg;
    assign framing_error = framing_error_reg;

    always @(posedge clk) begin
        if(rst) begin
            data_reg <= 0;
            prev_rx <= 0;
            data_ready_reg <= 0;
            state <= FIND_EDGE;
            data_counter <= 0;
            over_sample_counter <= 0;
        end else if(baud_edge) begin
            case(state)
                FIND_EDGE: begin
                    prev_rx <= rx;

                    if(prev_rx & !rx) begin
                        state <= START;
                        prev_rx <= 0;
                        over_sample_counter <= 0;
                    end
                end
                START: begin
                    // Align sample edge in the middle of the pulses.
                    if(over_sample_counter == OVERSAMPLE/2-1) begin
                        over_sample_counter <= 0;
                        data_counter <= 0;
                        state <= DATA;
                    end else begin
                        over_sample_counter <= over_sample_counter + 1;
                    end
                end
                DATA: begin
                    if(over_sample_counter == OVERSAMPLE-1) begin
                        over_sample_counter <= 0;
                        data_reg[data_counter] <= rx;
                        if(data_counter == 7) begin
                            state <= END;
                            data_counter <= 0;
                        end else begin
                            data_counter <= data_counter + 1;
                        end
                    end else begin
                        over_sample_counter <= over_sample_counter + 1;
                    end
                end
                END: begin
                    if(over_sample_counter == OVERSAMPLE-1) begin
                        if(rx) begin
                            data_ready_reg <= 1;
                        end else begin
                            framing_error_reg <= 1;
                        end
                        state <= FIND_EDGE;
                    end else begin
                        over_sample_counter <= over_sample_counter + 1;
                    end

                end
                default: begin
                    data_ready_reg <= 0;
                    state <= FIND_EDGE;
                end
            endcase
        end else begin
            data_ready_reg <= 0;
            framing_error_reg <= 0;
        end
    end
endmodule

module ir_comm (
  input data_in,
  input clk,
  input rst,
  output data_out,
  output tx_status
);

parameter bit_rate = 9600; // bits per second
parameter carrier_frequency = 38; // megahertz

// Transmitter circuit
reg [7:0] tx_data;
reg tx_enable;
reg [31:0] tx_counter;
reg [31:0] tx_bit_counter;
reg [31:0] tx_pulse_counter;
reg tx_pulse;
reg tx_done;

// Receiver circuit
reg [7:0] rx_data;
reg rx_enable;
reg [31:0] rx_counter;
reg [31:0] rx_bit_counter;
reg [31:0] rx_pulse_counter;
reg rx_pulse;
reg rx_done;

// Error checking and correction
reg [7:0] crc;
reg [7:0] crc_gen;
reg [7:0] crc_check;
reg [7:0] fec;
reg [7:0] fec_gen;
reg [7:0] fec_check;

// Modulation and demodulation
reg [31:0] tx_mod;
reg [31:0] rx_demod;
reg [31:0] carrier;
reg [31:0] tx_pulse_width;
reg [31:0] rx_pulse_width;
reg [31:0] tx_bit_width;
reg [31:0] rx_bit_width;

// Clock and reset
reg [31:0] clock_counter;
reg [31:0] reset_counter;

// Transmitter state machine
parameter TX_IDLE = 2'b00;
parameter TX_DATA = 2'b01;
parameter TX_CRC = 2'b10;
parameter TX_FEC = 2'b11;
reg [1:0] tx_state;
always @(posedge clk) begin
  if (rst) begin
    tx_state <= TX_IDLE;
    tx_enable <= 0;
    tx_counter <= 0;
    tx_bit_counter <= 0;
    tx_pulse_counter <= 0;
    tx_pulse <= 0;
    tx_done <= 0;
  end else begin
    case (tx_state)
      TX_IDLE: begin
        if (data_in && !tx_enable) begin
          tx_state <= TX_DATA;
          tx_enable <= 1;
          tx_data <= data_in;
          tx_counter <= 0;
          tx_bit_counter <= 0;
          tx_pulse_counter <= 0;
          tx_pulse <= 0;
          tx_done <= 0;
        end
      end
      TX_DATA: begin
        if (tx_counter >= bit_rate) begin
          tx_state <= TX_CRC;
          tx_counter <= 0;
          tx_bit_counter <= 0;
          tx_pulse_counter <= 0;
          tx_pulse <= 0;
          tx_done <= 0;
        end else begin
          if (tx_bit_counter >= 8) begin
            tx_bit_counter <= 0;
            tx_data <= tx_data >> 1;
          end else begin
            tx_bit_width <= (1000000 / bit_rate) / 2;
            if (tx_pulse_counter >= tx_bit_width) begin
              tx_pulse_counter <= 0;
              tx_pulse <= ~tx_pulse;
              tx_bit_counter <= tx_bit_counter + 1;
            end else begin
              tx_pulse_counter <= tx_pulse_counter + 1;
            end
          end
          tx_counter <= tx_counter + 1;
        end
      end
      TX_CRC: begin
        if (tx_counter >= 8) begin
          tx_state <= TX_FEC;
          tx_counter <= 0;
          tx_bit_counter <= 0;
          tx_pulse_counter <= 0;
          tx_pulse <= 0;
          tx_done <= 0;
        end else begin
          crc_gen <= crc ^ tx_data;
          crc <= crc_gen;
          tx_data <= crc_gen;
          tx_counter <= tx_counter + 1;
        end
      end
      TX_FEC: begin
        if (tx_counter >= 8) begin
          tx_state <= TX_IDLE;
          tx_enable <= 0;
          tx_counter <= 0;
          tx_bit_counter <= 0;
          tx_pulse_counter <= 0;
          tx_pulse <= 0;
          tx_done <= 1;
        end else begin
          fec_gen <= fec ^ tx_data;
          fec <= fec_gen;
          tx_data <= fec_gen;
          tx_counter <= tx_counter + 1;
        end
      end
    endcase
  end
end

// Receiver state machine
parameter RX_IDLE = 2'b00;
parameter RX_DATA = 2'b01;
parameter RX_CRC = 2'b10;
parameter RX_FEC = 2'b11;
reg [1:0] rx_state;
always @(posedge clk) begin
  if (rst) begin
    rx_state <= RX_IDLE;
    rx_enable <= 0;
    rx_counter <= 0;
    rx_bit_counter <= 0;
    rx_pulse_counter <= 0;
    rx_pulse <= 0;
    rx_done <= 0;
  end else begin
    case (rx_state)
      RX_IDLE: begin
        if (rx_pulse && !rx_enable) begin
          rx_state <= RX_DATA;
          rx_enable <= 1;
          rx_data <= 0;
          rx_counter <= 0;
          rx_bit_counter <= 0;
          rx_pulse_counter <= 0;
          rx_done <= 0;
        end
      end
      RX_DATA: begin
        if (rx_counter >= bit_rate) begin
          rx_state <= RX_CRC;
          rx_counter <= 0;
          rx_bit_counter <= 0;
          rx_pulse_counter <= 0;
          rx_pulse <= 0;
          rx_done <= 0;
        end else begin
          if (rx_bit_counter >= 8) begin
            rx_bit_counter <= 0;
            rx_data <= rx_data >> 1;
          end else begin
            rx_bit_width <= (1000000 / bit_rate) / 2;
            if (rx_pulse_counter >= rx_bit_width) begin
              rx_pulse_counter <= 0;
              rx_bit_counter <= rx_bit_counter + 1;
              rx_data <= {rx_data[6:0], rx_pulse};
            end else begin
              rx_pulse_counter <= rx_pulse_counter + 1;
            end
          end
          rx_counter <= rx_counter + 1;
        end
      end
      RX_CRC: begin
        if (rx_counter >= 8) begin
          rx_state <= RX_FEC;
          rx_counter <= 0;
          rx_bit_counter <= 0;
          rx_pulse_counter <= 0;
          rx_pulse <= 0;
          rx_done <= 0;
        end else begin
          crc_gen <= crc ^ rx_data;
          crc <= crc_gen;
          rx_data <= crc_gen;
          rx_counter <= rx_counter + 1;
        end
      end
      RX_FEC: begin
        if (rx_counter >= 8) begin
          rx_state <= RX_IDLE;
          rx_enable <= 0;
          rx_counter <= 0;
          rx_bit_counter <= 0;
          rx_pulse_counter <= 0;
          rx_pulse <= 0;
          rx_done <= 1;
        end else begin
          fec_gen <= fec ^ rx_data;
          fec <= fec_gen;
          rx_data <= fec_gen;
          rx_counter <= rx_counter + 1;
        end
      end
    endcase
  end
end

// Modulation and demodulation
always @(posedge clk) begin
  if (rst) begin
    tx_mod <= 0;
    rx_demod <= 0;
    carrier <= 0;
    tx_pulse_width <= 0;
    rx_pulse_width <= 0;
  end else begin
    if (tx_pulse && tx_enable) begin
      tx_mod <= carrier;
    end else begin
      tx_mod <= 0;
    end
    if (rx_pulse && rx_enable) begin
      rx_demod <= tx_mod;
    end else begin
      rx_demod <= 0;
    end
    if (clock_counter >= (1000000 / carrier_frequency) / 2) begin
      clock_counter <= 0;
      carrier <= ~carrier;
    end else begin
      clock_counter <= clock_counter + 1;
    end
    if (tx_pulse) begin
      tx_pulse_width <= tx_pulse_width + 1;
    end else begin
      tx_pulse_width <= 0;
    end
    if (rx_pulse) begin
      rx_pulse_width <= rx_pulse_width + 1;
    end else begin
      rx_pulse_width <= 0;
    end
  end
end

// Clock and reset
always @(posedge clk) begin
  if (rst) begin
    clock_counter <= 0;
    reset_counter <= 0;
  end else begin
    if (reset_counter >= 100) begin
      reset_counter <= 0;
    end else begin
      reset_counter <= reset_counter + 1;
    end
    if (tx_pulse || rx_pulse) begin
      tx_pulse_counter <= tx_pulse_counter + 1;
      rx_pulse_counter <= rx_pulse_counter + 1;
    end else begin
      tx_pulse_counter <= 0;
      rx_pulse_counter <= 0;
    end
    if (tx_done) begin
      tx_status <= 1;
    end else begin
      tx_status <= 0;
    end
  end
end

assign data_out = rx_data;

endmodule

module calculator(
    input [7:0] input1,
    input [7:0] input2,
    input [2:0] opcode,
    output reg [7:0] result
);

always @(*) begin
    case(opcode)
        3'b000: result = input1 + input2;
        3'b001: result = input1 - input2;
        3'b010: result = input1 * input2;
        3'b011: result = input1 / input2;
        3'b100: result = input1 & input2;
        3'b101: result = input1 | input2;
        3'b110: result = input1 ^ input2;
        3'b111: result = ~input1;
        default: result = 8'b0;
    endcase
end

endmodule

module shift_reg (
    input [3:0] data_in,
    input load,
    input clk,
    input rst,
    output reg [3:0] data_out
);

    always @(posedge clk, negedge rst) begin
        if (~rst) begin
            data_out <= 4'b0;
        end else if (load) begin
            data_out <= data_in;
        end else begin
            data_out <= {data_out[2:0], data_out[3]};
        end
    end

endmodule

module mux_4to1 (
    input [7:0] data_in_0,
    input [7:0] data_in_1,
    input [7:0] data_in_2,
    input [7:0] data_in_3,
    input [1:0] sel,
    output reg [7:0] data_out
);

    always @(*) begin
        case (sel)
            2'b00: data_out = data_in_0;
            2'b01: data_out = data_in_1;
            2'b10: data_out = data_in_2;
            2'b11: data_out = data_in_3;
        endcase
    end

endmodule

module adder (
    input [7:0] in_1,
    input [7:0] in_2,
    output reg [7:0] out
);

    always @(in_1, in_2) begin
        out <= in_1 + in_2;
    end

endmodule

module top_module (
    input CLK,
    input RST,
    output reg [7:0] OUT
);

    reg [3:0] shift_reg_out;
    reg [7:0] mux_out;
    reg [7:0] adder_out;

    shift_reg shift_reg_inst (
        .data_in(shift_reg_out),
        .load(1'b0),
        .clk(CLK),
        .rst(RST),
        .data_out(shift_reg_out)
    );

    mux_4to1 mux_inst (
        .data_in_0(shift_reg_out),
        .data_in_1(8'b00000001),
        .data_in_2(8'b00000010),
        .data_in_3(8'b00000011),
        .sel(shift_reg_out[3:2]),
        .data_out(mux_out)
    );

    adder adder_inst (
        .in_1(shift_reg_out),
        .in_2(mux_out),
        .out(adder_out)
    );

    always @(posedge CLK, negedge RST) begin
        if (~RST) begin
            OUT <= 8'b0;
        end else begin
            OUT <= adder_out;
        end
    end

endmodule

module sync_fifo #(
    parameter DEPTH = 3,
    parameter DATA_W = 32,
    parameter ASSERT_OVERFLOW = 1,
    parameter ASSERT_UNDERFLOW = 1,
    parameter ENABLE_BYPASS = 0
)(
    input clk,
    input rstn,
    input [DATA_W-1:0] fifo_data_in,
    input fifo_push,
    output reg [DATA_W-1:0] fifo_data_out,
    input fifo_pop,
    output reg fifo_full,
    output reg fifo_empty,
    input fifo_flush
);

localparam DEPTH_LOG2 = `CLOG2(DEPTH);

reg [DATA_W-1:0] mem [0:DEPTH-1];
reg [DEPTH_LOG2-1:0] head, n_head;
reg [DEPTH_LOG2-1:0] tail, n_tail;
wire empty;
wire full;
reg push_last;

assign fifo_data_out = mem[tail];

assign fifo_full = full;
assign fifo_empty = empty;

always @ (*) begin
    if (head < DEPTH-1) begin
        n_head = head + 1;
    end
    else begin
        n_head = 0;
    end
end

always @ (*) begin
    if (tail < DEPTH-1) begin
        n_tail = tail + 1;
    end
    else begin
        n_tail = 0;
    end
end

generate 
if (ENABLE_BYPASS) begin
    assign full  = (push_last  && (head == tail) && !fifo_pop)  ? 1'b1 : 1'b0;
    assign empty = (!push_last && (head == tail) && !fifo_push) ? 1'b1 : 1'b0;
end
else begin
    assign full  = (push_last  && (head == tail))  ? 1'b1 : 1'b0;
    assign empty = (!push_last && (head == tail))  ? 1'b1 : 1'b0;
end
endgenerate

generate
if (ASSERT_OVERFLOW) begin
    always @ (posedge clk) begin
        if (clk && !fifo_flush && fifo_push && full) begin
            $display("ERROR: FIFO OVERFLOW");
            $finish;
        end
    end
end
if (ASSERT_UNDERFLOW) begin
    always @ (posedge clk) begin
        if (clk && !fifo_flush && fifo_pop && empty) begin
            $display("ERROR: FIFO UNDERFLOW");
            $finish;
        end
    end
end
endgenerate

always @ (posedge clk, negedge rstn) begin
    if (~rstn) begin
        head      <= 0;
        tail      <= 0;
        push_last <= 0;
        fifo_full <= 0;
        fifo_empty <= 1;
    end
    else begin
        if (fifo_flush) begin
            tail      <= 0;
            head      <= 0;
            push_last <= 0;
            fifo_full <= 0;
            fifo_empty <= 1;
        end
        else if (!((full && fifo_push) || (empty && fifo_pop))) begin
            if (fifo_push) begin
                mem[head] <= fifo_data_in;
                head      <= n_head;
            end
            if (fifo_pop) begin
                tail      <= n_tail;
            end
            if (fifo_push && !fifo_pop) begin
                push_last = 1;
            end
            else if (!fifo_push && fifo_pop) begin
                push_last = 0;
            end
            fifo_full  <= (push_last && (head == tail));
            fifo_empty <= (!push_last && (head == tail));
        end
    end
end

endmodule

module jk_ff(
  input clk,
  input rst,
  input set,
  input j,
  input k,
  output reg q,
  output reg qbar
);

  always @(posedge clk, posedge rst)
    if (rst)
      begin
        q <= 1'b0;
        qbar <= 1'b1;
      end
    else
      begin
        if (set)
          begin
            q <= 1'b1;
            qbar <= 1'b0;
          end
        else if (j && k)
          begin
            q <= ~q;
            qbar <= ~qbar;
          end
        else if (j)
          begin
            q <= 1'b1;
            qbar <= 1'b0;
          end
        else if (k)
          begin
            q <= 1'b0;
            qbar <= 1'b1;
          end
      end

endmodule

module custom_or3 (
    input A,
    input B,
    input C_N,
    output X
);

    wire w1, w2, w3, w4, w5, w6, w7, w8;

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    sky130_fd_sc_hd__or3b_2 or1 (
        .X(w1),
        .A(A),
        .B(B),
        .C_N(C_N)
    );

    sky130_fd_sc_hd__or3b_2 or2 (
        .X(w2),
