module tone_detection_generation(
  input audio_in, //audio signal input
  input tone_freq, //tone frequency input
  output audio_out //generated tone output
);

parameter fs = 8000; //sampling frequency

reg signed [15:0] x1, x2, y1, y2; //delay registers
reg signed [15:0] coeff; //filter coefficient
reg [15:0] tone_period; //tone period
reg [15:0] tone_counter; //tone counter
reg tone_detected; //tone detected flag

assign audio_out = tone_detected ? sin(2 * $pi * tone_freq * tone_counter / fs) : 0; //generate tone signal

always @(posedge clk) begin
  //calculate filter coefficient
  coeff = 2 * cos(2 * $pi * tone_freq / fs);

  //update delay registers
  x2 <= x1;
  x1 <= audio_in;
  y2 <= y1;
  y1 <= coeff * x1 - x2 + y2;

  //check if tone is detected
  if (tone_counter == tone_period) begin
    tone_detected <= (y1 * y1 + y2 * y2 - coeff * y1 * y2 > 1000000); //threshold for tone detection
    tone_counter <= 0;
  end else begin
    tone_detected <= 0;
    tone_counter <= tone_counter + 1;
  end
end

endmodule

module top_module (
    input [3:0] DATA_IN,
    input LOAD,
    input CLK,
    input RESET,
    input select,
    output [3:0] COUNT,
    output parity
);

    reg [3:0] count_reg;
    reg parity_reg;
    wire [3:0] parity_gen_out;

    // Counter mode
    always @ (posedge CLK) begin
        if (RESET) begin
            count_reg <= 4'b0;
        end else if (select) begin
            count_reg <= count_reg + 1;
        end
    end

    // Parity mode
    parity_generator parity_gen (
        .data_in(DATA_IN),
        .parity_out(parity_gen_out)
    );

    always @ (posedge CLK) begin
        if (RESET) begin
            parity_reg <= 1'b0;
        end else if (!select) begin
            if (LOAD) begin
                count_reg <= 4'b0;
            end
            parity_reg <= parity_gen_out;
        end
    end

    assign COUNT = (select) ? count_reg : 4'bzzzz;
    assign parity = (!select) ? parity_reg : 1'bz;

endmodule

