module fifo8_256 (
  input  wire       clock,
  input  wire [7:0] data,
  input  wire       rdreq,
  input  wire       sclr,
  input  wire       wrreq,
  output wire       empty,
  output wire       full,
  output wire [7:0] q,
  output wire [8:0] usedw
);

  reg [7:0] mem [0:511];
  reg [8:0] read_ptr = 9'b0;
  reg [8:0] write_ptr = 9'b0;
  reg [8:0] used_words = 9'b0;
  wire [8:0] next_write_ptr = write_ptr + 1'b1;
  wire [8:0] next_read_ptr = read_ptr + 1'b1;

  always @(posedge clock) begin
    if (sclr) begin
      read_ptr <= 9'b0;
      write_ptr <= 9'b0;
      used_words <= 9'b0;
    end else if (wrreq && !full) begin
      mem[write_ptr][7:0] <= data;
      write_ptr <= next_write_ptr;
      used_words <= used_words + 1'b1;
    end
    if (rdreq && !empty) begin
      q <= mem[read_ptr][7:0];
      read_ptr <= next_read_ptr;
      used_words <= used_words - 1'b1;
    end
  end

  assign empty = (used_words == 0);
  assign full = (used_words == 512);

  assign usedw = used_words;

endmodule

