  reg [23:0] serialized_data;
  reg [7:0] data_counter;
  reg [3:0] bit_counter;
  reg [1:0] symbol_counter;
  reg [9:0] symbol;

  always @(*) begin
    if (hsync && vsync) begin
      serialized_data <= video_data;
      data_counter <= 0;
      bit_counter <= 0;
      symbol_counter <= 0;
    end else if (hsync) begin
      serialized_data <= {serialized_data[15:0], serialized_data[23:16]};
      data_counter <= data_counter + 1;
      bit_counter <= 0;
      symbol_counter <= 0;
    end else if (data_counter < 3) begin
      serialized_data <= {serialized_data[15:0], serialized_data[23:16]};
      data_counter <= data_counter + 1;
      bit_counter <= 0;
      symbol_counter <= 0;
    end else if (bit_counter == 0) begin
      symbol <= {serialized_data[23], serialized_data[22]};
      serialized_data <= {serialized_data[21:0], 1'b0};
      bit_counter <= 1;
      symbol_counter <= symbol_counter + 1;
    end else if (bit_counter == 1) begin
      symbol <= {symbol[7:0], serialized_data[23]};
      serialized_data <= {serialized_data[22:0], 1'b0};
