    input [7:0] address;
    input [31:0] count;
    begin
        @(posedge ifclk_in); #1;
        fifoData_wr = 1;
        fifoData_out = address | 8'b10000000;
        gotData_in = 1;
        @(posedge ifclk_in); #1;
        fifoData_out = count[31:24];
        @(posedge ifclk_in); #1;
        fifoData_out = count[23:16];
        @(posedge ifclk_in); #1;
        fifoData_out = count[15:8];
        @(posedge ifclk_in); #1;
        fifoData_out = count[7:0];
        @(posedge ifclk_in); #1;
        fifoData_wr = 0;
        gotData_in = 0;
