module top_module( 
    input [99:0] a, b,
    input cin,
    output cout,
    output [99:0] sum );

    wire [99:0] c1, c2, s1, s2;
    wire [99:0] s_final;
    wire c_select;

    // First half adder
    ripple_carry_adder rca1(
        .a(a[49:0]),
        .b(b[49:0]),
        .cin(cin),
        .cout(c1),
        .sum(s1)
    );

    // Second half adder
    ripple_carry_adder rca2(
        .a(a[99:50]),
        .b(b[99:50]),
        .cin(c1),
        .cout(c2),
        .sum(s2)
    );

    // Carry select adder
    assign c_select = c1[50] ^ c2[0];
    mux2to1 mux(
        .a(s1),
        .b(s2),
        .sel(c_select),
        .out(s_final)
    );

    // Final carry-out
    assign cout = c2[50];

    // Final sum output
    assign sum = {s_final, s2[49:0]};

endmodule

// Ripple carry adder module
module ripple_carry_adder(
    input [99:0] a, b,
    input cin,
    output cout,
    output [99:0] sum );

    genvar i;
    wire [100:0] c;

    assign c[0] = cin;

    // Generate full adders
    generate
        for (i = 0; i < 100; i = i + 1) begin : fa
            full_adder fa_inst(
                .a(a[i]),
                .b(b[i]),
                .cin(c[i]),
                .cout(c[i+1]),
                .sum(sum[i])
            );
        end
    endgenerate

    // Final carry-out
    assign cout = c[100];

endmodule

// Full adder module
module full_adder(
    input a, b, cin,
    output cout,
    output sum );

    assign {cout, sum} = a + b + cin;

endmodule

// 2-to-1 MUX module
module mux2to1(
    input [99:0] a, b,
    input sel,
    output [99:0] out );

    assign out = sel ? b : a;

endmodule

