    binary_to_bcd binary_to_bcd_converter(
        .binary_input(binary_input),
        .bcd_output1(bcd1),
        .bcd_output2(bcd2)
    );

    always @(*) begin
        if (binary_input >= 0 && binary_input <= 9) begin
            bcd_output1 = bcd1;
            bcd_output2 = bcd2;
        end else begin
            bcd_output1 = 4'b0000;
            bcd_output2 = 4'b0000;
        end
