module top;
  reg pass;
  reg [7:0] in;
  reg [3:0] out;

  initial begin
    pass = 1'b1;
    in = 8'b10100101;

    // Part-select operation that selects the least significant bit of the input, and sets all other bits to `x`.
    out = 8'bxxxxxxx1;
    if (in[0] !== out[0]) begin
      $display("FAILED: part select LSB is X, expected 1, got %b", out[0]);
      pass = 1'b0;
    end

    // Part-select operation that selects the most significant bit of the input, and sets all other bits to `x`.
    out = 8'b10000000;
    if (in[7] !== out[7]) begin
      $display("FAILED: part select MSB is X, expected 1, got %b", out[7]);
      pass = 1'b0;
    end

    // Bit-select operation that selects the least significant bit of the input, and sets all other bits to `0`.
    out = 4'b0001;
    if (in[0] !== out[0]) begin
      $display("FAILED: bit select is 0, expected 1, got %b", out[0]);
      pass = 1'b0;
    end

    // Part-select operation that selects the least significant bit of the input, and sets all other bits to `z`.
    out = 8'bzzzzzzz1;
    if (in[0] !== out[0]) begin
      $display("FAILED: part select LSB is Z, expected 1, got %b", out[0]);
      pass = 1'b0;
    end

    // Part-select operation that selects the most significant bit of the input, and sets all other bits to `z`.
    out = 8'b10000000;
    if (in[7] !== out[7]) begin
      $display("FAILED: part select MSB is Z, expected 1, got %b", out[7]);
      pass = 1'b0;
    end

    // Bit-select operation that selects the least significant bit of the input, and sets all other bits to `z`.
    out = 4'bzzzx;
    if (in[0] !== out[0]) begin
      $display("FAILED: bit select is Z, expected 1, got %b", out[0]);
      pass = 1'b0;
    end

    if (pass) $display("PASSED");
  end
endmodule

