module crossclockFIFO(
    input clkA,
    input clkB,
    input rst,
    input wrEnable,
    input rdEnable,
    input [bits-1:0] inputData,
    output [bits-1:0] outputData
);

  parameter bits = 8;
  parameter depth = 8;

  reg [bits-1:0] fifo [depth-1:0];
  reg [bits-1:0] readData;

  localparam EMPTY = 2'b00;
  localparam FULL = 2'b11;

  reg [1:0] fifoState;
  reg [2:0] readPointer;
  reg [2:0] writePointer;

  always @(posedge clkA or posedge clkB or posedge rst) begin
    if (rst) begin
      fifoState <= EMPTY;
      readPointer <= 0;
      writePointer <= 0;
    end else begin
      if (wrEnable && fifoState != FULL) begin
        fifo[writePointer] <= inputData;
        writePointer <= writePointer + 1;
        fifoState <= (writePointer == readPointer) ? FULL : 2'b01;
      end
      if (rdEnable && fifoState != EMPTY) begin
        readData <= fifo[readPointer];
        readPointer <= readPointer + 1;
        fifoState <= (readPointer == writePointer) ? EMPTY : 2'b10;
      end
    end
  end

  always @(posedge clkA or posedge clkB) begin
    if (fifoState == EMPTY) begin
      outputData <= 0;
    end else begin
      outputData <= readData;
    end
  end

endmodule

