module calculator(
    input [7:0] op1,
    input [7:0] op2,
    input [1:0] opcode,
    output [7:0] result
);

wire [7:0] add_out;
wire [7:0] sub_out;
wire [15:0] mul_out;
wire [7:0] div_out;
wire [7:0] zero;

assign zero = 8'b0;

// Adder
assign add_out = op1 + op2;

// Subtractor
assign sub_out = op1 - op2;

// Multiplier
assign mul_out = op1 * op2;

// Divider
assign div_out = op1 / op2;

always @(*) begin
    case(opcode)
        2'b00: result = add_out;
        2'b01: result = sub_out;
        2'b10: result = mul_out[15:8];
        2'b11: begin
            if(op2 != zero)
                result = div_out;
            else
                result = 8'b0;
        end
        default: result = 8'b0;
    endcase
end

endmodule

module sawtooth_pwm(clk, rst, note_on, saw_out, PWM);
  input clk, rst, note_on;
  input [7:0] saw_out;
  output reg PWM;

  reg [31:0] counter;
  reg [7:0] duty_cycle;

  always @(posedge clk) begin
    if (rst) begin
      counter <= 0;
      duty_cycle <= 0;
      PWM <= 0;
    end else begin
      counter <= counter + 1;
      if (counter == 500) begin // 1kHz PWM frequency
        counter <= 0;
        if (note_on) begin
          duty_cycle <= saw_out;
        end else begin
          duty_cycle <= 128; // 50% duty cycle
        end
      end
      if (duty_cycle > counter[7:0]) begin
        PWM <= 1;
      end else begin
        PWM <= 0;
      end
    end
  end
endmodule

