// Synchronize reset signal to clock domain
always @(posedge clk or negedge rst_n) begin
  if (~rst_n) begin
    rst_sync <= 2'b11;
  end else begin
    rst_sync[0] <= rst_sync[1];
    rst_sync[1] <= rst_n;
  end
end

