module calculator(
    input wire clk,
    input wire [7:0] a,
    input wire [7:0] b,
    input wire [1:0] op,
    output wire [7:0] result,
    output wire overflow,
    output wire underflow,
    output wire valid
    );

    reg [7:0] temp_result;
    reg [1:0] state;
    reg [7:0] counter;
    wire [7:0] abs_b;
    wire [7:0] abs_result;
    wire [7:0] temp_a;
    wire [7:0] temp_b;
    wire [7:0] temp_abs_result;
    wire [8:0] temp_overflow;
    wire [8:0] temp_underflow;
    wire [1:0] temp_state;
    wire temp_valid;

    assign abs_b = (b[7] == 1) ? ~b + 1 : b;
    assign abs_result = (temp_result[7] == 1) ? ~temp_result + 1 : temp_result;
    assign temp_abs_result = (temp_result[7] == 1) ? ~temp_result + 1 : temp_result;

    always @(posedge clk) begin
        case (state)
            2'b00: begin // addition
                temp_result <= a + b;
                counter <= 8;
                state <= 2'b01;
            end
            2'b01: begin // check overflow/underflow
                if (temp_result[7] == 1) begin // negative result
                    if (a[7] == 0 && b[7] == 0) begin // no overflow
                        overflow <= 1;
                        valid <= 0;
                        state <= 2'b00;
                    end else begin // overflow
                        overflow <= 0;
                        valid <= 1;
                        state <= 2'b10;
                    end
                end else begin // positive result
                    if (a[7] == 1 && b[7] == 1) begin // no underflow
                        underflow <= 1;
                        valid <= 0;
                        state <= 2'b00;
                    end else begin // underflow
                        underflow <= 0;
                        valid <= 1;
                        state <= 2'b10;
                    end
                end
            end
            2'b10: begin // check for valid result
                if (overflow == 1 || underflow == 1) begin // invalid result
                    result <= 8'h00;
                    state <= 2'b00;
                end else begin // valid result
                    result <= temp_result;
                    state <= 2'b00;
                end
            end
            2'b11: begin // subtraction
                temp_result <= a - b;
                counter <= 8;
                state <= 2'b01;
            end
        endcase
    end

    always @(*) begin
        case (op)
            2'b00: begin // addition
                state <= 2'b00;
            end
            2'b01: begin // subtraction
                state <= 2'b11;
            end
            2'b10: begin // multiplication
                temp_a = (a[7] == 1) ? ~a + 1 : a;
                temp_b = (b[7] == 1) ? ~b + 1 : b;
                temp_result <= temp_a * temp_b;
                counter <= 8;
                state <= 2'b01;
            end
            2'b11: begin // division
                if (b == 8'h00) begin // invalid operation
                    result <= 8'h00;
                    overflow <= 0;
                    underflow <= 0;
                    valid <= 0;
                end else begin // valid operation
                    temp_result <= a / b;
                    counter <= 8;
                    state <= 2'b01;
                end
            end
        endcase
    end

    always @(posedge clk) begin
        if (state == 2'b01) begin
            counter <= counter - 1;
            if (counter == 0) begin
                state <= 2'b10;
            end
        end
    end

    assign temp_overflow = {1'b0, temp_result[7]};
    assign temp_underflow = {1'b0, abs_result[7]};

    always @(*) begin
        if (temp_overflow > 8'h7F) begin // overflow
            overflow <= 0;
            valid <= 1;
            state <= 2'b10;
        end
        if (temp_underflow > 8'h7F) begin // underflow
            underflow <= 0;
            valid <= 1;
            state <= 2'b10;
        end
    end

    assign temp_valid = (overflow == 0 && underflow == 0) ? 1 : 0;

    always @(*) begin
        if (temp_valid == 1 && state == 2'b10) begin // valid result
            result <= temp_result;
        end
    end

endmodule

