module mult8bit(A, B, out);
    input [7:0] A;
    input [7:0] B;
    output [15:0] out;

    wire [7:0] mux_out[7:0];
    wire [7:0] shifted_mux_out[7:0];

    mux16x8 mux_0(.data0(A), .data1(8'b0), .data2(8'b0), .data3(8'b0), .data4(8'b0), .data5(8'b0), .data6(8'b0), .data7(8'b0), .selectInput(B[0:0]), .out(mux_out[0]));
    mux16x8 mux_1(.data0(A), .data1(8'b0), .data2(8'b0), .data3(8'b0), .data4(8'b0), .data5(8'b0), .data6(8'b0), .data7(mux_out[0]), .selectInput(B[1:1]), .out(mux_out[1]));
    mux16x8 mux_2(.data0(A), .data1(8'b0), .data2(8'b0), .data3(8'b0), .data4(8'b0), .data5(8'b0), .data6(mux_out[1]), .data7(mux_out[0]), .selectInput(B[2:2]), .out(mux_out[2]));
    mux16x8 mux_3(.data0(A), .data1(8'b0), .data2(8'b0), .data3(8'b0), .data4(8'b0), .data5(mux_out[2]), .data6(mux_out[1]), .data7(mux_out[0]), .selectInput(B[3:3]), .out(mux_out[3]));
    mux16x8 mux_4(.data0(A), .data1(8'b0), .data2(8'b0), .data3(8'b0), .data4(mux_out[3]), .data5(mux_out[2]), .data6(mux_out[1]), .data7(mux_out[0]), .selectInput(B[4:4]), .out(mux_out[4]));
    mux16x8 mux_5(.data0(A), .data1(8'b0), .data2(8'b0), .data3(mux_out[4]), .data4(mux_out[3]), .data5(mux_out[2]), .data6(mux_out[1]), .data7(mux_out[0]), .selectInput(B[5:5]), .out(mux_out[5]));
    mux16x8 mux_6(.data0(A), .data1(8'b0), .data2(mux_out[5]), .data3(mux_out[4]), .data4(mux_out[3]), .data5(mux_out[2]), .data6(mux_out[1]), .data7(mux_out[0]), .selectInput(B[6:6]), .out(mux_out[6]));
    mux16x8 mux_7(.data0(A), .data1(mux_out[6]), .data2(mux_out[5]), .data3(mux_out[4]), .data4(mux_out[3]), .data5(mux_out[2]), .data6(mux_out[1]), .data7(mux_out[0]), .selectInput(B[7:7]), .out(mux_out[7]));

    assign shifted_mux_out[0] = {8'b0, mux_out[0]};
    assign shifted_mux_out[1] = {7'b0, mux_out[1], 1'b0};
    assign shifted_mux_out[2] = {6'b0, mux_out[2], 2'b0};
