module coprocessor (
  output [1:0] cp_controller_cpstate,
  output cop_out_ready,
  output cop_dut_enable,
  input strobe_reg_cop_in_strobe_reg,
  input IPCORE_CLK,
  input [0:0] AR,
  input write_reg_axi_enable
);

  wire [1:0] cp_controller_cpstate_reg;
  wire [1:0] cp_controller_cpstate_next;
  wire cop_out_ready;
  wire cop_dut_enable;

  assign cp_controller_cpstate = cp_controller_cpstate_reg[1:0];
  assign cop_out_ready = (cp_controller_cpstate[1] == 2'b01) ? 1'b1 : 1'b0;
  assign cop_dut_enable = (cp_controller_cpstate[1] == 2'b10) ? 1'b1 : 1'b0;

  // combinational logic for next state
  assign cp_controller_cpstate_next[1] = 
    ((cp_controller_cpstate[0] == 1'b0) && (write_reg_axi_enable == 1'b1)) ? 1'b1 :
    ((cp_controller_cpstate[0] == 1'b1) && (write_reg_axi_enable == 1'b1)) ? 1'b10 :
    ((cp_controller_cpstate[0] == 1'b10) && (strobe_reg_cop_in_strobe_reg == 1'b1)) ? 1'b01 :
    cp_controller_cpstate[1];
  assign cp_controller_cpstate_next[0] = cp_controller_cpstate[1];

  // sequential logic for current state
  always @(posedge IPCORE_CLK or negedge AR) begin
    if (AR == 0) begin
      cp_controller_cpstate_reg <= 2'b0;
    end
    else begin
      cp_controller_cpstate_reg <= cp_controller_cpstate_next;
    end
  end

endmodule

