// 24000000 / (115200) == 208.3333
`define BAUD_DIV 208

// tx
reg [7:0] txclkdiv;
reg [9:0] txshift;
reg [3:0] txcount;
reg txdone;

always @ (posedge clk)
begin
    if (rst)
    begin
        txdone <= 1;
        txcount <= 0;
        txshift <= 1;
        txclkdiv <= 0;
    end else if (we && txdone) begin
        // start the tx process
        txshift[0] <= 0; // start bit
        txshift[8:1] <= wdata[7:0];
        txshift[9] <= 1; // stop bit
        txcount <= 9;
        // start bit
        txclkdiv <= `BAUD_DIV;
        txdone <= 0;
    end else if (!txdone) begin
        // keep shifting bits out
        if (txclkdiv == 0) begin
            txshift <= txshift >> 1;
            txclkdiv <= `BAUD_DIV;

            if (txcount == 0) begin
                // terminating condition
                txdone <= 1;
            end else begin
                txcount <= txcount - 1;
            end
        end else begin
            txclkdiv <= txclkdiv - 1;
        end
    end
end

always @(posedge clk)
begin
    if (re) begin
        rdata <= txdone;
    end else begin
        rdata <= 32'bzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzz;
    end
end

