module top_module (
    input CLK,
    input UP_DOWN,
    input RESET,
    input [3:0] gray,
    output reg [3:0] OUT
);

reg [3:0] binary;
reg [3:0] counter;
reg [3:0] sum;

gray_to_binary gray_to_binary_inst (
    .gray(gray),
    .binary(binary)
);

up_down_counter up_down_counter_inst (
    .CLK(CLK),
    .UP_DOWN(UP_DOWN),
    .RESET(RESET),
    .OUT(counter)
);

functional_module functional_module_inst (
    .binary(binary),
    .counter(counter),
    .sum(sum)
);

always @ (posedge CLK) begin
    if (RESET) begin
        binary <= 4'b0000;
        counter <= 4'b0000;
        sum <= 4'b0000;
    end else begin
        if (UP_DOWN) begin
            counter <= counter + 4'b0001;
        end else begin
            counter <= counter - 4'b0001;
        end
    end
end

always @ (posedge CLK) begin
    sum <= binary + counter;
    OUT <= sum;
end

endmodule

