module ptrfifo (
  input clk,
  input rstn,
  input loaden,
  input unloaden,
  input [63:0] datain,
  output reg [63:0] dataout,
  output reg empty,
  output reg full,
  output reg [5:0] itemsinfifo
);

  parameter WIDTH = 64;
  parameter DEPTH = 6;

  reg [WIDTH-1:0] memory [0:DEPTH-1];
  reg [5:0] head;
  reg [5:0] tail;
  reg [5:0] count;

  assign empty = (count == 0);
  assign full = (count == DEPTH);

  always @(posedge clk or negedge rstn) begin
    if (~rstn) begin
      head <= 0;
      tail <= 0;
      count <= 0;
    end else begin
      if (loaden && ~full) begin
        memory[head] <= datain;
        head <= head + 1;
        count <= count + 1;
      end
      if (unloaden && ~empty) begin
        dataout <= memory[tail];
        tail <= tail + 1;
        count <= count - 1;
      end
    end
  end

  always @(count) begin
    itemsinfifo <= count;
  end

endmodule

module pwm_generator
  (
   input clk,
   input reset,
   output reg pwm_out
  );

  // Define constants for duty cycle and frequency
  localparam DUTY_CYCLE = 3;
  localparam PERIOD = 100000;

  // Counter for PWM period
  reg [15:0] period_counter = 0;

  // Counter for PWM duty cycle
  reg [2:0] duty_cycle_counter = 0;

  always @ (posedge clk) begin
    if (reset == 0) begin
      // Reset the counters and the output
      period_counter <= 0;
      duty_cycle_counter <= 0;
      pwm_out <= 0;
    end
    else begin
      // Increment the period counter
      period_counter <= period_counter + 1;

      // If the period counter reaches PERIOD, reset it and the duty cycle counter
      if (period_counter == PERIOD) begin
        period_counter <= 0;
        duty_cycle_counter <= 0;
      end

      // Increment the duty cycle counter
      if (duty_cycle_counter < DUTY_CYCLE) begin
        duty_cycle_counter <= duty_cycle_counter + 1;
      end
      else begin
        duty_cycle_counter <= 0;
      end

      // Set the output based on the duty cycle counter
      if (duty_cycle_counter == 0) begin
        pwm_out <= 0;
      end
      else begin
        pwm_out <= 1;
      end
    end
  end

endmodule

module cpu_ctl(op,func,equal_result,JR,J,JAL,LW,WREG,WMEM,RDorRT,SE,SA,IorR,BJ,Aluc);

    input wire [5:0] op, func;
    input wire equal_result;
    output wire JR,J,JAL,LW,WREG,WMEM,RDorRT,SE,SA,IorR,BJ;
    output wire [4:0] Aluc;

    /* R_type */
    wire r_type = ~op[5] & ~op[4] & ~op[3] & ~op[2] & ~op[1] & ~op[0];
    wire i_jr = r_type & ~func[5] & ~func[4] & func[3] & ~func[2] & ~func[1] & ~func[0];    //func:001000
    wire i_sll = r_type & ~func[5] & ~func[4] & ~func[3] & ~func[2] & ~func[1] & ~func[0];   //func:000000
    wire i_srl = r_type & ~func[5] & ~func[4] & ~func[3] & ~func[2] & func[1] & ~func[0];    //func:000010
    wire i_sra = r_type & ~func[5] & ~func[4] & ~func[3] & ~func[2] & func[1] & func[0];     //func:000011

    /* I_type */
    wire i_type = i_addi | i_andi | i_ori | i_xori | i_slti | b_type | i_lw | i_sw ;
    wire i_addi = ~op[5] & ~op[4] & op[3] & ~op[2] & ~op[1] & ~op[0];    //001000
    wire i_addiu = ~op[5] & ~op[4] & op[3] & ~op[2] & ~op[1] & op[0];    //001001
    wire i_andi = ~op[5] & ~op[4] & op[3] & op[2] & ~op[1] & ~op[0];     //001100
    wire i_ori = ~op[5] & ~op[4] & op[3] & op[2] & ~op[1] & op[0];      //001101
    wire i_xori = ~op[5] & ~op[4] & op[3] & op[2] & op[1] & ~op[0];     //001110
    wire i_lui = ~op[5] & ~op[4] & op[3] & op[2] & op[1] & op[0];       //001111
    wire i_lw = op[5] & ~op[4] & ~op[3] & ~op[2] & op[1] & op[0];       //100011
    wire i_sw = op[5] & ~op[4] & op[3] & ~op[2] & op[1] & op[0];        //101011
    wire i_slti = ~op[5] & ~op[4] & op[3] & ~op[2] & op[1] & ~op[0];    //001010
    wire i_sltiu = ~op[5] & ~op[4] & op[3] & ~op[2] & op[1] & op[0];    //001011

    /* I_type(B) */
    wire b_type = i_beq | i_bgez | i_bgtz | i_blez | i_bltz | i_bne;
    wire i_beq = ~op[5] & ~op[4] & ~op[3] & op[2] & ~op[1] & ~op[0];    //000100
    wire i_bne = ~op[5] & ~op[4] & ~op[3] & op[2] & ~op[1] & op[0];     //000101

    /* J_type */
    wire i_j = ~op[5] & ~op[4] & ~op[3] & ~op[2] & op[1] & ~op[0];
    wire i_jal = ~op[5] & ~op[4] & ~op[3] & ~op[2] & op[1] & op[0];

    /* JR,J,JAL,LW,WREG,WMEM,RDorRT,SE,SA,IorR,AluCtl,BJ */
    assign JR = i_jr;
    assign J = i_j;
    assign JAL = i_jal;
    assign LW = i_lw;
    assign WREG = i_jal | (IorR & ~i_sw) | (r_type & ~i_jr);
    assign WMEM = i_sw;
    assign RDorRT = r_type & ~i_jr;
    assign SE = i_addi | i_addiu | i_lw |i_sw | i_slti;//i_andi i_ori zero_extend
    assign SA = i_sll | i_srl | i_sra;
    assign IorR = i_type & ~b_type;
    assign BJ = ( i_beq & equal_result ) | ( i_bne & ~equal_result );
    alt_ctl AC(.op(op),.func(func),.aluc(Aluc));

    always @(*) begin
        /* ALU Control */
        case ({op,func})
            6'b000000: Aluc = func[3:0]; // R-Type
            6'b001000: Aluc = 4'b0010; // ADDI
            6'b001001: Aluc = 4'b0011; // ADDIU
            6'b001100: Aluc = 4'b0000; // ANDI
            6'b001101: Aluc = 4'b0101; // ORI
            6'b001110: Aluc = 4'b0110; // XORI
            6'b001010: Aluc = 4'b0111; // SLTI
            6'b001011: Aluc = 4'b1000; // SLTIU
            6'b100011: Aluc = 4'b0001; // LW
            6'b101011: Aluc = 4'b0001; // SW
            default: Aluc = 4'b0000; // Default to 0
        endcase
    end

endmodule

module clock_generator(
    input clk_in,
    output reg clk_out
);

reg [23:0] counter;

always @(posedge clk_in) begin
    if(counter == 24'd4_999_999) begin
        counter <= 0;
        clk_out <= ~clk_out;
    end else begin
