  (
   input  clk,
   input  reset,
   output io_success);

   wire [24:0] testharness_ext_R0_addr;
   wire        testharness_ext_R0_en;
   wire        testharness_ext_R0_clk;
   wire [127:0] testharness_ext_R0_data;
   wire [24:0]  testharness_ext_W0_addr;
   wire         testharness_ext_W0_en;
   wire         testharness_ext_W0_clk;
   wire [127:0] testharness_ext_W0_data;
   wire [0:0]  testharness_ext_W0_mask;

   reg [127:0] memory [0:31]; // 32 words of 128 bits each

   assign testharness_ext_R0_addr = testharness_ext_W0_addr;
   assign testharness_ext_R0_en = testharness_ext_W0_en;
   assign testharness_ext_R0_clk = testharness_ext_W0_clk;

   always @(posedge testharness_ext_R0_clk) begin
     if (testharness_ext_R0_en) begin
       testharness_ext_R0_data <= memory[testharness_ext_R0_addr[24:2]];
     end
   end

   always @(posedge testharness_ext_W0_clk) begin
     if (testharness_ext_W0_en) begin
       memory[testharness_ext_W0_addr[24:2]] <=
         (testharness_ext_W0_mask & testharness_ext_W0_data) |
         (~testharness_ext_W0_mask & memory[testharness_ext_W0_addr[24:2]]);
     end
   end

   always @(posedge clk) begin
     if (reset) begin
       io_success <= 0;
     end else begin
       // Test case 1
       testharness_ext_W0_addr <= 25'b0;
       testharness_ext_W0_en <= 1'b0;
       testharness_ext_W0_data <= 128'b0;
       testharness_ext_W0_mask <= 1'b0;

       if (testharness_ext_R0_data !== 128'b0) begin
         io_success <= 0;
         $display("Test case 1 failed: expected 0x00000000000000000000000000000000, got %h", testharness_ext_R0_data);
       end else begin
         // Test case 2
         testharness_ext_W0_addr <= 25'b0;
         testharness_ext_W0_en <= 1'b1;
         testharness_ext_W0_data <= 128'hFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF;
         testharness_ext_W0_mask <= 1'b1;

         #1;

         testharness_ext_W0_addr <= 25'b0;
         testharness_ext_W0_en <= 1'b0;
         testharness_ext_W0_data <= 128'b0;
         testharness_ext_W0_mask <= 1'b0;

         if (testharness_ext_R0_data !== 128'hFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFE) begin
           io_success <= 0;
           $display("Test case 2 failed: expected 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFE, got %h", testharness_ext_R0_data);
         end else begin
           // Test case 3
           testharness_ext_W0_addr <= 25'b0;
           testharness_ext_W0_en <= 1'b1;
           testharness_ext_W0_data <= 128'hFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF;
           testharness_ext_W0_mask <= 1'b0;

           #1;

           testharness_ext_W0_addr <= 25'b0;
           testharness_ext_W0_en <= 1'b0;
           testharness_ext_W0_data <= 128'b0;
           testharness_ext_W0_mask <= 1'b0;

           if (testharness_ext_R0_data !== 128'b0) begin
             io_success <= 0;
             $display("Test case 3 failed: expected 0x00000000000000000000000000000000, got %h", testharness_ext_R0_data);
           end else begin
             io_success <= 1;
           end
         end
       end
     end
   end

