module mux_bdd (
    input [2:0] select,
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output reg [3:0] out
);

reg [3:0] mux_out;
reg [3:0] xor_out;
reg [3:0] and_out;

wire bdd_out;

// 6-to-1 multiplexer
always @*
begin
    case (select)
        3'b000: mux_out = data0;
        3'b001: mux_out = data1;
        3'b010: mux_out = data2;
        3'b011: mux_out = data3;
        3'b100: mux_out = data4;
        3'b101: mux_out = data5;
        default: mux_out = 4'b0000;
    endcase
end

// XOR and AND gates
always @*
begin
    if (select <= 3'b010)
        xor_out = mux_out ^ 4'b1010;
    else
        and_out = mux_out & 4'b0101;
end

// BDD-based functional module
function [1:0] bdd_func;
input [3:0] a, b;
begin
    case ({a,b})
        4'b0000, 4'b0010, 4'b0100, 4'b0110, 4'b1000, 4'b1010, 4'b1100: bdd_func = 2'b00;
        4'b0001, 4'b0011, 4'b0101, 4'b0111, 4'b1001, 4'b1011, 4'b1101: bdd_func = 2'b01;
        default: bdd_func = 2'b10;
    endcase
end
endfunction

// Final output
always @*
begin
    if (select <= 3'b010)
        out = bdd_func(xor_out, 4'b1010);
    else
        out = bdd_func(and_out, 4'b0101);
end

endmodule

module uart_rx_stimulus_source_character_source_rom_module (
                                                             // inputs:
                                                              clk,
                                                              incr_addr,
                                                              reset_n,

                                                             // outputs:
                                                              new_rom,
                                                              q,
                                                              safe,
                                                              new_char,
                                                              mem_full,
                                                              char_count
                                                           )
;

  parameter POLL_RATE = 100;


  output           new_rom;
  output  [  7: 0] q;
  output           safe;
  output           new_char;
  output           mem_full;
  output  [  9: 0] char_count;
  input            clk;
  input            incr_addr;
  input            reset_n;

  reg     [ 10: 0] address;
  reg              d1_pre;
  reg              d2_pre;
  reg              d3_pre;
  reg              d4_pre;
  reg              d5_pre;
  reg              d6_pre;
  reg              d7_pre;
  reg              d8_pre;
  reg              d9_pre;
  reg     [ 7: 0]  mem_array [1023: 0];
  reg     [ 31: 0] mutex [  1: 0];
  reg              new_rom;
  reg              pre;
  wire    [  7: 0] q;
  wire             safe;
  wire             new_char;
  wire             mem_full;
  wire    [  9: 0] char_count;

//synthesis translate_off
//////////////// SIMULATION-ONLY CONTENTS
  assign q = mem_array[address];
  always @(posedge clk or negedge reset_n)
    begin
      if (reset_n == 0)
        begin
          d1_pre <= 0;
          d2_pre <= 0;
          d3_pre <= 0;
          d4_pre <= 0;
          d5_pre <= 0;
          d6_pre <= 0;
          d7_pre <= 0;
          d8_pre <= 0;
          d9_pre <= 0;
          new_rom <= 0;
        end
      else 
        begin
          d1_pre <= pre;
          d2_pre <= d1_pre;
          d3_pre <= d2_pre;
          d4_pre <= d3_pre;
          d5_pre <= d4_pre;
          d6_pre <= d5_pre;
          d7_pre <= d6_pre;
          d8_pre <= d7_pre;
          d9_pre <= d8_pre;
          new_rom <= d9_pre;
        end
    end


   reg        safe_delay;
   reg [31:0] poll_count;
   reg [31:0] mutex_handle;
   wire       interactive = 1'b0 ; // '
   assign     safe = (address < mutex[1]);

   initial poll_count = POLL_RATE;

   always @(posedge clk or negedge reset_n) begin
      if (reset_n !== 1) begin
         safe_delay <= 0;
      end else begin
         safe_delay <= safe;
      end
   end // safe_delay

   always @(posedge clk or negedge reset_n) begin
      if (reset_n !== 1) begin  // dont worry about null _stream.dat file
         address <= 0;
         mem_array[0] <= 0;
         mutex[0] <= 0;
         mutex[1] <= 0;
         pre <= 0;
         char_count <= 0;
      end else begin            // deal with the non-reset case
         pre <= 0;
         if (incr_addr && safe) address <= address + 1;
         if (mutex[0] && !safe && safe_delay) begin
            // and blast the mutex after falling edge of safe if interactive
            if (interactive) begin
               mutex_handle = $fopen ("uart_input_data_mutex.dat");
               $fdisplay (mutex_handle, "0");
               $fclose (mutex_handle);
               // $display ($stime, "\t%m:\n\t\tMutex cleared!");
            end else begin
               // sleep until next reset, do not bash mutex.
               wait (!reset_n);
            end
         end // OK to bash mutex.
         if (poll_count < POLL_RATE) begin // wait
            poll_count = poll_count + 1;
         end else begin         // do the interesting stuff.
            poll_count = 0;
            if (mutex_handle) begin
            $readmemh ("uart_input_data_mutex.dat", mutex);
            end
            if (mutex[0] && !safe) begin
            // read stream into mem_array after current characters are gone!
               // save mutex[0] value to compare to address (generates 'safe')
               mutex[1] <= mutex[0];
               // $display ($stime, "\t%m:\n\t\tMutex hit: Trying to read %d bytes...", mutex[0]);
               $readmemh("uart_input_data_stream.dat", mem_array);
               // bash address and send pulse outside to send the char:
               address <= 0;
               pre <= -1;
            end // else mutex miss...
         end // poll_count
      end // reset
   end // posedge clk

   always @(posedge clk or negedge reset_n) begin
      if (reset_n !== 1) begin
         new_char <= 0;
         mem_full <= 0;
      end else begin
         if (pre == -1) begin
            new_char <= 1;
            char_count <= char_count + 1;
            if (char_count == 1024) begin
               mem_full <= 1;
            end
         end
         else begin
            new_char <= 0;
         end
      end
   end

   always @(posedge clk or negedge reset_n) begin
      if (reset_n !== 1) begin
         mem_array <= 0;
      end else begin
         if (pre == -1) begin
            mem_array[address] <= q;
         end
      end
   end

   always @(posedge clk or negedge reset_n) begin
      if (reset_n !== 1) begin
         mutex[0] <= 0;
      end else begin
         if (pre == -1) begin
            if (address == 1023) begin
               mutex[0] <= 1024;
            end else begin
               mutex[0] <= address + 1;
            end
         end
      end
   end

//////////////// END SIMULATION-ONLY CONTENTS

//synthesis translate_on

endmodule

