module ClockGenerator
#(
  parameter CLK_IN_FREQ = 100_000_000,
  parameter CLK_OUT1_FREQ = 48_000_000,
  parameter CLK_OUT2_FREQ = 24_000_000,
  parameter CLK_OUT3_FREQ = 12_000_000,
  parameter CLK_OUT4_FREQ = 6_000_000,
  parameter TCQ = 100
)
(
  input CLK_IN1,
  input COUNTER_RESET,
  output reg [3:0] CLK_OUT,
  output reg [3:0] COUNT,
  output reg LOCKED
);

  // Constants
  localparam CLK_OUT1_PERIOD = CLK_IN_FREQ / CLK_OUT1_FREQ;
  localparam CLK_OUT2_PERIOD = CLK_IN_FREQ / CLK_OUT2_FREQ;
  localparam CLK_OUT3_PERIOD = CLK_IN_FREQ / CLK_OUT3_FREQ;
  localparam CLK_OUT4_PERIOD = CLK_IN_FREQ / CLK_OUT4_FREQ;

  // Counters
  reg [15:0] counter1 = 0;
  reg [15:0] counter2 = 0;
  reg [15:0] counter3 = 0;
  reg [15:0] counter4 = 0;

  // Output clocks
  reg clk_out1 = 0;
  reg clk_out2 = 0;
  reg clk_out3 = 0;
  reg clk_out4 = 0;

  // Lock detection
  reg [1:0] lock_counter = 0;
  reg prev_locked = 0;

  always @(posedge CLK_IN1) begin
    // Reset counters
    if (COUNTER_RESET) begin
      counter1 <= 0;
      counter2 <= 0;
      counter3 <= 0;
      counter4 <= 0;
    end else begin
      // Increment counters
      counter1 <= counter1 + 1;
      counter2 <= counter2 + 1;
      counter3 <= counter3 + 1;
      counter4 <= counter4 + 1;
    end

    // Output clocks
    if (counter1 == CLK_OUT1_PERIOD) begin
      counter1 <= 0;
      clk_out1 <= ~clk_out1;
    end
    if (counter2 == CLK_OUT2_PERIOD) begin
      counter2 <= 0;
      clk_out2 <= ~clk_out2;
    end
    if (counter3 == CLK_OUT3_PERIOD) begin
      counter3 <= 0;
      clk_out3 <= ~clk_out3;
    end
    if (counter4 == CLK_OUT4_PERIOD) begin
      counter4 <= 0;
      clk_out4 <= ~clk_out4;
    end

    // Lock detection
    if (lock_counter == 2) begin
      lock_counter <= 0;
      if (prev_locked == 1 && LOCKED == 1) begin
        LOCKED <= 1;
      end else begin
        LOCKED <= 0;
      end
      prev_locked <= LOCKED;
    end else begin
      lock_counter <= lock_counter + 1;
    end
  end

  // Assign output clocks
  assign CLK_OUT[0] = clk_out1;
  assign CLK_OUT[1] = clk_out2;
  assign CLK_OUT[2] = clk_out3;
  assign CLK_OUT[3] = clk_out4;

  // Assign COUNT
  assign COUNT[0] = counter1[15];
  assign COUNT[1] = counter2[15];
  assign COUNT[2] = counter3[15];
  assign COUNT[3] = counter4[15];

endmodule

