module uart_rx(
		clk,			//Communications Clock
		rx,			//Tx IO Pin
		rx_byte,		//Byte to Transmit
		data_ready,		//Start Transmitting Byte
		busy,			//Tx Busy Flag
		error			//Error Flag
	);

	//Parameters:
	//================================================
	parameter CLOCK = 25000000; 	//Overridden by parent UART core
	parameter BAUD = 9600;			//Overridden by parent UART core
	parameter SAMPLE_POINT = 8;	//Overridden by parent

	//IO Definitions:
	//================================================
	input clk;
	input rx;
	output reg [7:0] rx_byte;
	output reg data_ready;
	output reg busy;
	output reg error;

	//Register/Wire Definitions:
	//================================================
	reg [1:0] rx_sync;
	reg [1:0] rx_counter;
	reg rx_bit;
	reg [3:0] state;
	reg [3:0] bit_spacing;
	reg [4:0] data_gap;
	reg rx_buf1, rx_buf2;
	wire next_bit;
	wire rx_n;

	//BUFG Instatiation:
	//================================================

	//Module Instantiation:
	//================================================
	uart_baudgenerator #(
		.CLOCK(CLOCK),
		.BAUD(BAUD*8),	//Oversampled
		.ROUNDBITS(8)	//Higher frequency requires more rounding
	) BAUDGEN (
		.clk(clk),
		.baudtick(baudtick)
	);

	//Assignments:
	//=================================================
	//Inverted rx for stability:
	assign rx_n = ~rx_buf2;
	//Note: value below for bit_spacing check, defines where data sampling occurs
	assign next_bit = (bit_spacing==SAMPLE_POINT);
	//Gap Detection:
	assign busy = ~data_gap[4];

	//Toplevel Logic:
	//=================================================
	//Double Buffering
	always @(posedge clk)
		begin
			rx_buf1 <= rx;
			rx_buf2 <= rx_buf1;
		end

	//Oversampling & Sync of RX Input to clock
	always @(posedge clk)
		if(baudtick)
			rx_sync <= {rx_sync[0], rx_n};

	//RX Line Noise Filter
	always @(posedge clk)
		if(baudtick)
			begin
				if(rx_sync[1] && rx_counter!=2'b11)
					rx_counter <= rx_counter + 2'h1;
				if(~rx_sync[1] && rx_counter!=2'b00)
					rx_counter <= rx_counter - 2'h1;
				if(rx_counter==2'b00)
					rx_bit <= 1'b0;
				else if(rx_counter==2'b11)
					rx_bit <= 1'b1;
			end

	//RX State Machine
	always @(posedge clk)
		if(baudtick)
			case(state)
				4'b0000: if(rx_bit) state <= 4'b1000; // start bit found?
				4'b1000: if(next_bit) state <= 4'b1001; // bit 0
				4'b1001: if(next_bit) state <= 4'b1010; // bit 1
				4'b1010: if(next_bit) state <= 4'b1011; // bit 2
				4'b1011: if(next_bit) state <= 4'b1100; // bit 3
				4'b1100: if(next_bit) state <= 4'b1101; // bit 4
				4'b1101: if(next_bit) state <= 4'b1110; // bit 5
				4'b1110: if(next_bit) state <= 4'b1111; // bit 6
				4'b1111: if(next_bit) state <= 4'b0001; // bit 7
				4'b0001: if(next_bit) state <= 4'b0000; // stop bit
				default: state <= 4'b0000;
			endcase

	//Bit Spacing Detection
	always @(posedge clk)
		if(state==0)
			bit_spacing <= 4'b0000;
		else if(baudtick)
			bit_spacing <= {bit_spacing[2:0] + 4'b0001} | {bit_spacing[3], 3'b000};

	//Shift Register
	always @(posedge clk)
		if(baudtick && next_bit && state[3]) 
			rx_byte <= {~rx_bit, rx_byte[7:1]};

	//Data Ready & Error Detection
	always @(posedge clk)
		begin
			data_ready <= (baudtick && next_bit && state==4'b0001 && ~rx_bit);  // ready only if the stop bit is received
			error <= (baudtick && next_bit && state==4'b0001 && rx_bit);  // error if no stop bit received
		end

	//Idle Detection
	always @(posedge clk)
		if(state!=0)
			data_gap <= 5'h00;
		else if(baudtick & ~data_gap[4])
			data_gap <= data_gap + 5'h01;

endmodule

module ram_harvard2
  #(parameter AWIDTH=15,
    parameter RAM_SIZE=32768)
   (input wb_clk_i, 
    input ram_clk_i,
    input wb_rst_i,
    // Instruction fetch port.
    input [AWIDTH-1:0] if_adr,
    output reg [31:0] if_data,
    // Data access port.
    input [AWIDTH-1:0] dwb_adr_i,
    input [31:0] dwb_dat_i, 
    output reg [31:0] dwb_dat_o,
    input dwb_we_i,
    output reg dwb_ack_o,
    input dwb_stb_i,
    input [3:0] dwb_sel_i);

   reg 	  ack_d1;
   reg 	  stb_d1;

   assign dwb_ack_o = dwb_stb_i & (dwb_we_i | (stb_d1 & ~ack_d1));

   always @(posedge wb_clk_i) 
     if(wb_rst_i)
       ack_d1 <= 1'b0;
     else 
       ack_d1 <= dwb_ack_o;

   always @(posedge wb_clk_i)
     if(wb_rst_i)
       stb_d1 <= 0;
     else
       stb_d1 <= dwb_stb_i;

   reg [7:0] ram0 [0:(RAM_SIZE/4)-1];
   reg [7:0] ram1 [0:(RAM_SIZE/4)-1];
   reg [7:0] ram2 [0:(RAM_SIZE/4)-1];
   reg [7:0] ram3 [0:(RAM_SIZE/4)-1];

   // Port 1, Read only
   always @(posedge ram_clk_i)
     if_data[31:24] <= ram3[if_adr[AWIDTH-1:2]];
   always @(posedge ram_clk_i)
     if_data[23:16] <= ram2[if_adr[AWIDTH-1:2]];
   always @(posedge ram_clk_i)
     if_data[15:8] <= ram1[if_adr[AWIDTH-1:2]];
   always @(posedge ram_clk_i)
     if_data[7:0] <= ram0[if_adr[AWIDTH-1:2]];

   // Port 2, R/W
   always @(posedge ram_clk_i)
     if(dwb_stb_i) begin
       case (dwb_sel_i)
         4'b0001: dwb_dat_o[7:0] <= ram0[dwb_adr_i[AWIDTH-1:2]];
         4'b0010: dwb_dat_o[15:8] <= ram1[dwb_adr_i[AWIDTH-1:2]];
         4'b0100: dwb_dat_o[23:16] <= ram2[dwb_adr_i[AWIDTH-1:2]];
         4'b1000: dwb_dat_o[31:24] <= ram3[dwb_adr_i[AWIDTH-1:2]];
         4'b0011: dwb_dat_o[15:0] <= {ram1[dwb_adr_i[AWIDTH-1:2]], ram0[dwb_adr_i[AWIDTH-1:2]]};
         4'b1100: dwb_dat_o[31:16] <= {ram3[dwb_adr_i[AWIDTH-1:2]], ram2[dwb_adr_i[AWIDTH-1:2]]};
         default: dwb_dat_o <= 0;
       endcase
     end

   always @(posedge ram_clk_i)
     if(dwb_we_i & dwb_stb_i) begin
       case (dwb_sel_i)
         4'b0001: ram0[dwb_adr_i[AWIDTH-1:2]] <= dwb_dat_i[7:0];
         4'b0010: ram1[dwb_adr_i[AWIDTH-1:2]] <= dwb_dat_i[15:8];
         4'b0100: ram2[dwb_adr_i[AWIDTH-1:2]] <= dwb_dat_i[23:16];
         4'b1000: ram3[dwb_adr_i[AWIDTH-1:2]] <= dwb_dat_i[31:24];
         4'b0011: begin
           ram0[dwb_adr_i[AWIDTH-1:2]] <= dwb_dat_i[7:0];
           ram1[dwb_adr_i[AWIDTH-1:2]] <= dwb_dat_i[15:8];
         end
         4'b1100: begin
           ram2[dwb_adr_i[AWIDTH-1:2]] <= dwb_dat_i[23:16];
           ram3[dwb_adr_i[AWIDTH-1:2]] <= dwb_dat_i[31:24];
         end
         default: begin
           ram0[dwb_adr_i[AWIDTH-1:2]] <= 0;
           ram1[dwb_adr_i[AWIDTH-1:2]] <= 0;
           ram2[dwb_adr_i[AWIDTH-1:2]] <= 0;
           ram3[dwb_adr_i[AWIDTH-1:2]] <= 0;
         end
       endcase
     end

endmodule

