        gm.in <= in_2;
    end

endmodule

module reverse_byte_order(
    input [63:0] in,
    output [63:0] out
);
    genvar i;
    generate
        for (i = 0; i < 8; i = i + 1) begin : byte_loop
            assign out[i*8 +: 8] = in[(i+1)*8 - 1 -: 8];
        end
    endgenerate
endmodule

