module viterbi_decoder (
  input [n-1:0] in,
  input clk,
  input reset,
  output [m-1:0] out
);

parameter n = 100; // number of bits in input sequence
parameter m = 50; // number of bits in output sequence
parameter k = 3; // constraint length of convolutional code

reg [k-1:0] shift_reg [n-1:0]; // shift register to store input sequence
reg [1:0] path_metric [n-1:0][2**k-1:0]; // path metrics for each state
reg [k-1:0] prev_state [n-1:0][2**k-1:0]; // previous state for each state
reg [k-1:0] out_reg [m-1:0]; // output register

integer i, j, l;
reg [1:0] metric0, metric1;

// initialize shift register and path metrics
initial begin
  for (i = 0; i < n; i = i + 1) begin
    shift_reg[i] = 0;
    for (j = 0; j < 2**k; j = j + 1) begin
      path_metric[i][j] = 0;
      prev_state[i][j] = 0;
    end
  end
end

// compute path metrics and most likely sequence of bits
always @(posedge clk) begin
  if (reset) begin
    for (i = 0; i < n; i = i + 1) begin
      shift_reg[i] = 0;
      for (j = 0; j < 2**k; j = j + 1) begin
        path_metric[i][j] = 0;
        prev_state[i][j] = 0;
      end
    end
    for (l = 0; l < m; l = l + 1) begin
      out_reg[l] = 0;
    end
  end else begin
    // shift input bit into shift register
    for (i = n-1; i > 0; i = i - 1) begin
      shift_reg[i] = shift_reg[i-1];
    end
    shift_reg[0] = in;

    // compute path metrics for each state at current time step
    for (j = 0; j < 2**k; j = j + 1) begin
      metric0 = path_metric[n-1][j] + (shift_reg[0] ^ ((j >> (k-1)) & 1));
      metric1 = path_metric[n-1][j + 2**(k-1)] + (shift_reg[0] ^ ((j >> (k-1)) & 1) ^ ((j >> (k-2)) & 1));
      if (metric0 > metric1) begin
        path_metric[n][j] = metric1;
        prev_state[n][j] = j + 2**(k-1);
      end else begin
        path_metric[n][j] = metric0;
        prev_state[n][j] = j;
      end
    end

    // compute path metrics and most likely sequence of bits for each time step
    for (i = n-2; i >= 0; i = i - 1) begin
      for (j = 0; j < 2**k; j = j + 1) begin
        metric0 = path_metric[i][j] + (shift_reg[n-i-1] ^ ((j >> (k-1)) & 1));
        metric1 = path_metric[i][j + 2**(k-1)] + (shift_reg[n-i-1] ^ ((j >> (k-1)) & 1) ^ ((j >> (k-2)) & 1));
        if (metric0 > metric1) begin
          path_metric[i+1][j] = metric1;
          prev_state[i+1][j] = j + 2**(k-1);
        end else begin
          path_metric[i+1][j] = metric0;
          prev_state[i+1][j] = j;
        end
      end
    end

    // compute most likely sequence of bits
    for (l = 0; l < m; l = l + 1) begin
      out_reg[l] = (prev_state[l*(n/m)][out_reg[l]] >> (k-2)) & 1;
    end
  end
end

assign out = out_reg;

endmodule

