module hdmi_transmitter (
  input [23:0] pixel_data,
  input hsync,
  input vsync,
  output clk_p,
  output clk_n,
  output data_p,
  output data_n
);

  reg [9:0] tmds_data;
  reg [1:0] tmds_state;
  reg [2:0] tmds_count;
  reg data_p_out;
  reg data_n_out;
  reg clk_p_out;
  reg clk_n_out;

  always @ (posedge hsync or posedge vsync) begin
    if (vsync) begin
      tmds_state <= 0;
      tmds_count <= 0;
    end else if (hsync) begin
      tmds_count <= 0;
      case (tmds_state)
        0: begin // Start bit
          tmds_data <= {3'b001, pixel_data[7:4]};
          tmds_state <= 1;
        end
        1: begin // Data bits 0-3
          tmds_data <= {1'b0, pixel_data[3], 1'b0, pixel_data[2], 1'b0, pixel_data[1], 1'b0, pixel_data[0]};
          tmds_state <= 2;
        end
        2: begin // Data bits 4-7
          tmds_data <= {1'b0, pixel_data[15], 1'b0, pixel_data[14], 1'b0, pixel_data[13], 1'b0, pixel_data[12]};
          tmds_state <= 3;
        end
        3: begin // Data bits 8-11
          tmds_data <= {1'b0, pixel_data[19], 1'b0, pixel_data[18], 1'b0, pixel_data[17], 1'b0, pixel_data[16]};
          tmds_state <= 4;
        end
        4: begin // Data bits 12-15
          tmds_data <= {1'b0, pixel_data[23], 1'b0, pixel_data[22], 1'b0, pixel_data[21], 1'b0, pixel_data[20]};
          tmds_state <= 5;
        end
        5: begin // Data bits 16-19
          tmds_data <= {1'b0, 1'b0, 1'b0, pixel_data[11], 1'b0, pixel_data[10], 1'b0, pixel_data[9]};
          tmds_state <= 6;
        end
        6: begin // Data bits 20-23
          tmds_data <= {1'b0, 1'b0, 1'b0, pixel_data[3], 1'b0, pixel_data[2], 1'b0, pixel_data[1]};
          tmds_state <= 7;
        end
        7: begin // End bit
          tmds_data <= {3'b000, 3'b000};
          tmds_state <= 0;
        end
      endcase
    end else begin
      case (tmds_count)
        0: begin
          data_p_out <= tmds_data[9];
          data_n_out <= ~tmds_data[9];
          tmds_count <= 1;
        end
        1: begin
          data_p_out <= tmds_data[8];
          data_n_out <= ~tmds_data[8];
          tmds_count <= 2;
        end
        2: begin
          clk_p_out <= 1'b1;
          clk_n_out <= 1'b0;
          data_p_out <= tmds_data[7];
          data_n_out <= ~tmds_data[7];
          tmds_count <= 3;
        end
        3: begin
          clk_p_out <= 1'b0;
          clk_n_out <= 1'b1;
          data_p_out <= tmds_data[6];
          data_n_out <= ~tmds_data[6];
          tmds_count <= 4;
        end
        4: begin
          data_p_out <= tmds_data[5];
          data_n_out <= ~tmds_data[5];
          tmds_count <= 5;
        end
        5: begin
          data_p_out <= tmds_data[4];
          data_n_out <= ~tmds_data[4];
          tmds_count <= 6;
        end
        6: begin
          data_p_out <= tmds_data[3];
          data_n_out <= ~tmds_data[3];
          tmds_count <= 7;
        end
        7: begin
          data_p_out <= tmds_data[2];
          data_n_out <= ~tmds_data[2];
          tmds_count <= 8;
        end
        8: begin
          data_p_out <= tmds_data[1];
          data_n_out <= ~tmds_data[1];
          tmds_count <= 9;
        end
        9: begin
          data_p_out <= tmds_data[0];
          data_n_out <= ~tmds_data[0];
          tmds_count <= 0;
        end
      endcase
    end
  end

  assign clk_p = clk_p_out;
  assign clk_n = clk_n_out;
  assign data_p = data_p_out;
  assign data_n = data_n_out;

endmodule

module vending_machine (
  input clk,
  input reset,
  input coin,
  output reg [1:0] display,
  output reg product_select,
  output reg dispense
);

  // Define the three states
  parameter IDLE = 2'b00;
  parameter SELECTING = 2'b01;
  parameter DISPENSING = 2'b10;

  // Define the state register and initialize to IDLE
  reg [1:0] state_reg = IDLE;

  // Define the next state logic
  always @ (posedge clk, negedge reset) begin
    if (reset == 0) begin
      state_reg <= IDLE;
    end else begin
      case (state_reg)
        IDLE: begin
          if (coin == 1) begin
            state_reg <= SELECTING;
          end
        end
        SELECTING: begin
          if (coin == 0) begin
            state_reg <= DISPENSING;
          end
        end
        DISPENSING: begin
          state_reg <= IDLE;
        end
      endcase
    end
  end

  // Define the output logic
  always @ (state_reg) begin
    case (state_reg)
      IDLE: begin
        display <= 2'b00;
        product_select <= 0;
        dispense <= 0;
      end
      SELECTING: begin
        display <= 2'b01;
        product_select <= 1;
        dispense <= 0;
      end
      DISPENSING: begin
        display <= 2'b10;
        product_select <= 0;
        dispense <= 1;
      end
    endcase
  end

endmodule

