    out[5] = in[2];
    out[4] = in[3];
    out[3] = in[4];
    out[2] = in[5];
    out[1] = in[6];
    out[0] = in[7];
  end

endmodule

module edge_detection(
  input        clk,
  input        rst_n,
  input        a,
  output reg   rise,
  output reg   down
);

  reg a_d1;
  reg a_d2;

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      a_d1 <= 1'b0;
      a_d2 <= 1'b0;
      rise <= 1'b0;
      down <= 1'b0;
    end
    else begin
      a_d2 <= a_d1;
      a_d1 <= a;

      if (a_d1 && !a_d2) begin
        rise <= 1'b1;
        down <= 1'b0;
      end
      else if (!a_d1 && a_d2) begin
        rise <= 1'b0;
        down <= 1'b1;
      end
      else begin
        rise <= 1'b0;
        down <= 1'b0;
      end
    end
  end

endmodule

module top_module(
  input               clk,
  input               rst_n,
