module generic_fifo_sc_a (
    input clk,
    input rst,
    input clr,
    input [59:0] din,
    input we,
    input re,
    output [59:0] dout,
    output full_r,
    output empty_r,
    output full_n_r,
    output empty_n_r
);

reg [59:0] fifo [0:255];
reg [7:0] read_ptr;
reg [7:0] write_ptr;
reg [7:0] count;

wire full = (count == 256);
wire empty = (count == 0);

assign full_r = ~full;
assign empty_r = ~empty;
assign full_n_r = full;
assign empty_n_r = empty;

always @(posedge clk) begin
    if (rst) begin
        read_ptr <= 8'd0;
        write_ptr <= 8'd0;
        count <= 8'd0;
    end else if (we && !full) begin
        fifo[write_ptr] <= din;
        write_ptr <= write_ptr + 1;
        count <= count + 1;
    end else if (re && !empty) begin
        dout <= fifo[read_ptr];
        read_ptr <= read_ptr + 1;
        count <= count - 1;
    end
end

always @(posedge clk or posedge clr) begin
    if (clr) begin
        read_ptr <= 8'd0;
        write_ptr <= 8'd0;
        count <= 8'd0;
    end
end

endmodule

module audio_generator(
