module UART #(
 parameter N    = 5,
 parameter Full = 5'd29 // Clk / BAUD - 1
)(
 input Reset,
 input Clk,

 output [7:0]Rx_Data,
 output      Rx_Ready,
 input       Rx_Ack,

 input  [7:0]Tx_Data,
 input       Tx_Send,
 output      Tx_Busy,

 input       Rx,
 output      Tx
);
//------------------------------------------------------------------------------

reg [7:0] rx_data;
reg        rx_ready;
reg        rx_ack;
wire       rx_done;

UART_Rx #(N, Full) UART_Rx1(
 .Reset(Reset),
 .Clk(Clk),

 .Data(rx_data),
 .Ready(rx_ready),
 .Ack(rx_ack),

 .Rx(Rx),
 .Done(rx_done)
);

reg [7:0] tx_data;
reg        tx_send;
reg        tx_busy;
wire       tx_done;

UART_Tx #(N, Full) UART_Tx1(
 .Reset(Reset),
 .Clk(Clk),

 .Data(tx_data),
 .Send(tx_send),
 .Busy(tx_busy),

 .Tx(Tx),
 .Done(tx_done)
);

assign Rx_Data = rx_data;
assign Rx_Ready = rx_ready;
assign Tx_Busy = tx_busy;

always @(posedge Clk) begin
 if (Reset) begin
  rx_ack <= 0;
  tx_busy <= 0;
 end else begin
  if (rx_done) begin
   rx_ack <= 1;
  end else begin
   rx_ack <= 0;
  end

  if (tx_done) begin
   tx_busy <= 0;
  end else if (tx_send) begin
   tx_busy <= 1;
  end else begin
   tx_busy <= 0;
  end
 end
end

assign UART_Tx1.Data = tx_data;
assign UART_Tx1.Send = tx_send;
assign UART_Rx1.Ack = rx_ack;

endmodule

module UART_Rx #(
 parameter N    = 5,
 parameter Full = 5'd29 // Clk / BAUD - 1
)(
 input Reset,
 input Clk,

 output [7:0]Data,
 output      Ready,
 input       Ack,

 input       Rx,
 output      Done
);
//------------------------------------------------------------------------------

reg [7:0] shift_reg;
reg [3:0] bit_count;
reg        start_bit;
reg        stop_bit;
reg        parity_bit;
reg        data_ready;

wire [3:0] full;
assign full = Full;

wire [7:0] baud_count;
assign baud_count = 0;

assign Done = (bit_count == full + 1);

always @(posedge Clk) begin
 if (Reset) begin
  shift_reg <= 0;
  bit_count <= 0;
  start_bit <= 0;
  stop_bit <= 0;
  parity_bit <= 0;
  data_ready <= 0;
 end else begin
  if (!Rx && !start_bit && !stop_bit && !parity_bit) begin
   start_bit <= 1;
   bit_count <= 0;
  end else if (start_bit && baud_count == full) begin
   start_bit <= 0;
   stop_bit <= 1;
   bit_count <= bit_count + 1;
  end else if (stop_bit && baud_count == full) begin
   stop_bit <= 0;
   bit_count <= bit_count + 1;
   if (bit_count == full + 1) begin
    data_ready <= 1;
   end
  end else if (bit_count < full && baud_count == full) begin
   bit_count <= bit_count + 1;
   shift_reg <= {Rx, shift_reg[N-1:1]};
  end else if (bit_count == full && baud_count == full) begin
   bit_count <= bit_count + 1;
   parity_bit <= Rx;
  end else if (bit_count == full + 1 && baud_count == full) begin
   if (Ack) begin
    data_ready <= 0;
    bit_count <= 0;
   end
  end
 end
end

assign Data = shift_reg;
assign Ready = data_ready;

endmodule

module UART_Tx #(
 parameter N    = 5,
 parameter Full = 5'd29 // Clk / BAUD - 1
)(
 input Reset,
 input Clk,

 input [7:0]Data,
 input      Send,
 output     Busy,

 output     Tx,
 output     Done
);
//------------------------------------------------------------------------------

reg [7:0] shift_reg;
reg [3:0] bit_count;
reg        start_bit;
reg        stop_bit;
reg        parity_bit;
reg        data_sent;

wire [3:0] full;
assign full = Full;

wire [7:0] baud_count;
assign baud_count = 0;

assign Done = (bit_count == full + 2);

always @(posedge Clk) begin
 if (Reset) begin
  shift_reg <= 0;
  bit_count <= 0;
  start_bit <= 0;
  stop_bit <= 0;
  parity_bit <= 0;
  data_sent <= 0;
 end else begin
  if (Send && !start_bit && !stop_bit && !parity_bit && !data_sent) begin
   start_bit <= 1;
   bit_count <= 0;
   shift_reg <= Data;
  end else if (start_bit && baud_count == full) begin
   start_bit <= 0;
   bit_count <= bit_count + 1;
   Tx <= 0;
  end else if (bit_count < full && baud_count == full) begin
   bit_count <= bit_count + 1;
   Tx <= shift_reg[0];
   shift_reg <= {shift_reg[N-1:1], parity_bit};
  end else if (bit_count == full && baud_count == full) begin
   bit_count <= bit_count + 1;
   Tx <= shift_reg[0];
   shift_reg <= {shift_reg[N-1:1], 1};
  end else if (bit_count == full + 1 && baud_count == full) begin
   bit_count <= bit_count + 1;
   Tx <= 1;
   data_sent <= 1;
  end else if (stop_bit && baud_count == full) begin
   stop_bit <= 0;
   bit_count <= 0;
   data_sent <= 0;
  end else if (bit_count == full + 2 && baud_count == full) begin
   if (!Send) begin
    bit_count <= 0;
   end
  end
 end
end

