module state_machine (
   input clk,
   input rst_,
   output reg [2:0] state_r
);

   parameter [2:0] IDLE = 3'b000;
   parameter [2:0] SEND = 3'b001;
   parameter [2:0] WAIT1 = 3'b010;
   parameter [2:0] UPDATE1 = 3'b011;
   parameter [2:0] WAIT2 = 3'b100;
   parameter [2:0] UPDATE2 = 3'b101;

   reg [2:0] state_e1;
   reg [55:0] _stateascii_r;

   always @(*) begin
      case(state_r)
         IDLE: state_e1 = SEND;
         SEND: state_e1 = WAIT1;
         WAIT1: state_e1 = UPDATE1;
         UPDATE1: state_e1 = UPDATE2;
         WAIT2: state_e1 = UPDATE2;
         UPDATE2: state_e1 = IDLE;
         default: state_e1 = state_r;
      endcase
   end

   always @(posedge clk or negedge rst_) begin
      if (~rst_) begin
         state_r <= IDLE;
      end
      else begin
         state_r <= state_e1;
      end
   end

   always @(state_r) begin
      case ({state_r})
         IDLE: _stateascii_r = "idle   ";
         SEND: _stateascii_r = "send   ";
         WAIT1: _stateascii_r = "wait1  ";
         UPDATE1: _stateascii_r = "update1";
         WAIT2: _stateascii_r = "wait2  ";
         UPDATE2: _stateascii_r = "update2";
         default: _stateascii_r = "%Error ";
      endcase
   end

   assign _stateascii_r = _stateascii_r;

endmodule

module uart(
	input clk,
	input reset,
	input rxin,
	output txout
);

`define TXREG 			3'b001 
`define CONTROLTX 	3'b011
`define RXREG 			3'b101
`define CONTROLRX 	3'b111
`define TXR				2'b00
`define CTX				2'b01
`define RXR				2'b10
`define CRX				2'b11
`define START 			3'b000
`define WAITRX			3'b001

wire [7:0] to_tx;
reg [2:0] addr, pstate, nstate;
reg [1:0] addmux;
reg [3:0] din;
reg wr_rx, rd_rx, wr_tx, rd_tx;

uart_rx #(.PERIOD(8'h1A)) RX(
	.clk		(clk), 
	.reset	(reset), 
	.wren		(wr_rx), 
	.rden		(rd_rx), 
	.din		(8'b00000001), 
	.dout		(to_tx), 
	.rxin		(rxin), 
	.addr		(addr)
	);

uart_tx #(.PERIOD(8'h1A)) TX(
	 .clk		(clk), 
	 .reset	(reset), 
	 .wren	(wr_tx), 
	 .rden		(rd_tx), 
	 .din		(to_tx), 
	 .dout	(dout), 
	 .txout	(txout), 
	 .addr	(addr)
	);

always @* begin
	addr = 3'b010;
	case(addmux)
		`TXR:
			addr = `TXREG;
		`CTX:
			addr = `CONTROLTX;
		`RXR:
			addr = `RXREG;
		`CRX:
			addr = `CONTROLRX;
	endcase
end

always @(posedge clk or posedge reset) begin
	if(reset)
		pstate <= `START;
	else begin
		pstate <= nstate;
	end
end

always @* begin
	wr_rx = 0; rd_rx = 0;
	wr_tx = 0; rd_tx = 0;
	nstate = pstate;
	case(pstate)
		`START: begin
			wr_rx = 1;
			addmux = `CRX;
			nstate = `WAITRX;
		end
		`WAITRX: begin
			rd_rx = 1;
			if(to_tx[1]) begin
				addmux = `CTX;
				din = 4'b0000;
				nstate = `START;
			end
			else begin
				addmux = `RXR;
				if(rxin == 1) begin
					din[0] = 1;
				end
				if(to_tx[0] == 1) begin
					din[1:0] = 2'b00;
				end
				if(to_tx[2] == 1) begin
					din[1:0] = 2'b01;
				end
				if(to_tx[3] == 1) begin
					din[1:0] = 2'b10;
				end
				if(to_tx[4] == 1) begin
					din[1:0] = 2'b11;
				end
				if(to_tx[5] == 1) begin
					din[2] = 1;
				end
				if(to_tx[6] == 1) begin
					din[3] = 1;
				end
				if(to_tx[7] == 1) begin
					wr_tx = 1;
				end
			end
		end
	endcase
end

endmodule

