module top_module (
    input clk,
    input reset, // Synchronous active-high reset
    input [3:0] M, // 4-bit multiplicand
    input [3:0] N, // 4-bit multiplier
    input [7:0] code, // 8-bit code for priority encoder
    output reg [7:0] final_output // 8-bit final output
);

    wire [7:0] product;
    wire [2:0] priority;

    // Instantiate the multiplier module
    multiplier_module multiplier(
        .M(M),
        .N(N),
        .P(product)
    );

    // Instantiate the priority encoder module
    priority_encoder_module priority_encoder(
        .code(code),
        .priority(priority)
    );

    // Functional module to produce final output
    always @ (posedge clk) begin
        if (reset) begin
            final_output <= 8'b0;
        end else begin
            case (priority)
                3'b000: final_output <= product;
                3'b001: final_output <= ~product;
                3'b010: final_output <= ~product;
                default: final_output <= product;
            endcase
        end
    end

endmodule

// 4-bit unsigned multiplier module
module multiplier_module (
    input [3:0] M, // 4-bit multiplicand
    input [3:0] N, // 4-bit multiplier
    output reg [7:0] P // 8-bit product
);

    integer i, j;
    reg [7:0] temp;

    always @ (*) begin
        P = 8'b0;
        for (i = 0; i < 4; i = i + 1) begin
            temp = {8'b0, M[i]};
            for (j = 0; j < 4; j = j + 1) begin
                if (N[j]) begin
                    P = P + (temp << j);
                end
            end
        end
    end

endmodule

// 8-bit priority encoder module
module priority_encoder_module (
    input [7:0] code, // 8-bit code
    output reg [2:0] priority // 3-bit priority output
);

    always @ (*) begin
        case (code)
            8'b00000001: priority = 3'b000;
            8'b00000010: priority = 3'b001;
            8'b00000100: priority = 3'b010;
            default: priority = 3'b011;
        endcase
    end

endmodule

