module Booth_Multiplier (
    input signed [3:0] A,
    input signed [3:0] B,
    input enable,
    output reg [7:0] out
);

reg signed [3:0] a_reg;
reg signed [3:0] b_reg;
reg signed [7:0] p_reg;

always @(posedge enable) begin
    a_reg <= A;
    b_reg <= B;
    p_reg <= 8'b0;
end

always @(posedge enable) begin
    if(enable) begin
        case({b_reg[1], b_reg[0]})
            2'b00: p_reg <= {8'b0, a_reg};
            2'b01: p_reg <= {8'b0, a_reg} - {8'b0, a_reg, 8'b0, a_reg};
            2'b10: p_reg <= {8'b0, a_reg, 8'b0};
            2'b11: p_reg <= {8'b0, a_reg, 8'b0} + {8'b0, a_reg};
            default: p_reg <= 8'b0;
        endcase
        b_reg <= {b_reg[2], b_reg[1], b_reg[0], 1'b0};
    end
end

assign out = p_reg;

endmodule

