  wire [11:0]RD_PNTR_WR_reg;
  wire comp1;
  wire comp2;
  wire full_reg;
  wire [11:0]out_reg;
  wire p_0_out;
  wire ram_full_i;
  wire rst_d2;
  wire rst_full_gen_i;
  wire sel_reg;
  wire wr_clk;
  wire wr_en_reg;

  (* ram_style = "distributed" *) 
  reg [11:0] ram [0:1023];
  assign Q_reg = ram[RD_PNTR_WR_reg];
  assign full = full_reg;
  assign sel = sel_reg;
  assign out = out_reg;

  always @(posedge wr_clk) begin
    if (rst_d2) begin
      RD_PNTR_WR_reg <= 0;
      wr_en_reg <= 0;
    end else if (wr_en) begin
      RD_PNTR_WR_reg <= RD_PNTR_WR_reg + 1;
      ram[RD_PNTR_WR_reg] <= Q;
    end
  end

  always @(posedge wr_clk) begin
    if (rst_d2) begin
      full_reg <= 0;
    end else begin
      full_reg <= ram_full_i;
    end
  end

  always @(posedge wr_clk) begin
    if (rst_d2) begin
      sel_reg <= 0;
    end else begin
      sel_reg <= comp1 ? wr_en_reg : comp2;
    end
  end

  always @(posedge wr_clk) begin
    if (rst_d2) begin
      out_reg <= 0;
    end else if (comp2) begin
      out_reg <= Q_reg;
    end
  end

  fifo_64in_out_compare c1
       (.Q(Q_reg),
        .RD_PNTR_WR(RD_PNTR_WR_reg),
        .comp1(comp1));
  fifo_64in_out_compare_0 c2
       (.RD_PNTR_WR(RD_PNTR_WR_reg),
        .comp2(comp2),
        .out(out_reg));
  (* equivalent_register_removal = "no" *) 
  FDPE #(
    .INIT(1'b1)) 
     ram_full_fb_i_reg
       (.C(wr_clk),
        .CE(1'b1),
        .D(ram_full_i),
        .PRE(rst_d2),
        .Q(p_0_out));
  LUT2 #(
    .INIT(4'h2)) 
     \DEVICE_7SERIES.NO_BMM_INFO.SDP.SIMPLE_PRIM36.ram_i_1 
       (.I0(wr_en_reg),
        .I1(p_0_out),
        .O(sel_reg));
  LUT5 #(
    .INIT(32'h55550400)) 
     ram_full_i_i_1
       (.I0(rst_full_gen_i),
        .I1(comp2),
        .I2(p_0_out),
        .I3(wr_en_reg),
        .I4(comp1),
        .O(ram_full_i));
  (* equivalent_register_removal = "no" *) 
  FDPE #(
    .INIT(1'b1)) 
     ram_full_i_reg
       (.C(wr_clk),
        .CE(1'b1),
        .D(ram_full_i),
        .PRE(rst_d2),
        .Q(full_reg));
endmodule

