module fifo_module(
    input clk_i,
    input rst_i,
    input flush_i,

    input stb_i,
    input [15:0] di,

    output can_burst_o,
    output do8_valid,
    output reg [7:0] do8,
    input next_i
);

/*
 * FIFO can hold 8 16-bit words
 * that is 16 8-bit bytes.
 */

reg [15:0] storage[0:7];
reg [2:0] produce; // in 16-bit words
reg [3:0] consume; // in 8-bit bytes
/*
 * 8-bit bytes stored in the FIFO, 0-15 (16 possible values)
 */

reg [3:0] level;

wire [15:0] do16;
assign do16 = storage[consume[3:1]];

always @(*) begin
  case(consume[0])
    1'd0: do8 <= do16[15:8];
    1'd1: do8 <= do16[7:0];
  endcase
end

always @(posedge clk_i) begin
  if(rst_i) begin
    produce = 3'd0;
    consume = 4'd0;
    level = 4'd0;
  end else begin
    if(flush_i) begin
        produce = 3'd0;
        consume = 4'd0;
        level = 4'd0;
    end else begin
        if(stb_i && level < 4'd16) begin
            storage[produce] = di;
            produce = (produce == 3'd7) ? 3'd0 : produce + 3'd1;
            level = level + 4'd2;
        end
        if(next_i && do8_valid) begin /* next should only be asserted when do8_valid = 1 */
            consume = (consume == 4'd15) ? 4'd0 : consume + 4'd1;
            level = level - 4'd1;
        end
    end
  end
end

assign do8_valid = ~(level == 4'd0);
assign can_burst_o = level >= 4'd14;

endmodule

module memory_comp_decomp (
  input [n-1:0] in_data,
  input in_valid,
  output [m-1:0] out_data,
  output out_valid
);

parameter n = 32; // number of bits in input data
parameter m = 16; // number of bits in compressed output data

// Compression algorithm
reg [m-1:0] compressed_data;
always @ (posedge in_valid) begin
  // Implement compression algorithm here
  compressed_data = in_data >> (n-m); // Example compression algorithm: simply shift right by (n-m) bits
  out_data <= compressed_data;
  out_valid <= 1;
end

// Decompression algorithm
reg [n-1:0] decompressed_data;
always @ (posedge in_valid) begin
  // Implement decompression algorithm here
  decompressed_data = {compressed_data, {m{1'b0}}} + in_data; // Example decompression algorithm: concatenate compressed data with (n-m) zeros and add to input data
  out_data <= decompressed_data;
  out_valid <= 1;
end

endmodule

module ripple_carry_adder_4bit (
    input [3:0] A,
    input [3:0] B,
    input carry_in,
    output reg [3:0] sum,
    output reg carry_out
);

reg [3:0] carry;

always @(A, B, carry_in) begin
    sum[0] = A[0] ^ B[0] ^ carry_in;
    carry[0] = (A[0] & B[0]) | (A[0] & carry_in) | (B[0] & carry_in);

    sum[1] = A[1] ^ B[1] ^ carry[0];
    carry[1] = (A[1] & B[1]) | (A[1] & carry[0]) | (B[1] & carry[0]);

    sum[2] = A[2] ^ B[2] ^ carry[1];
    carry[2] = (A[2] & B[2]) | (A[2] & carry[1]) | (B[2] & carry[1]);

    sum[3] = A[3] ^ B[3] ^ carry[2];
    carry_out = (A[3] & B[3]) | (A[3] & carry[2]) | (B[3] & carry[2]);
end

endmodule

