module convolutional_encoder_and_viterbi_decoder (
  input [k-1:0] data_in,
  input reset,
  output [n-1:0] encoded,
  output [k-1:0] data_out
);

parameter n = 8; // length of encoded sequence (in bits)
parameter k = 4; // length of input data sequence (in bits)
parameter g = 3'b101; // generator polynomial for convolutional encoder

reg [n-1:0] encoded_reg;
reg [k-1:0] data_out_reg;
reg [1:0] state_reg;
reg [1:0] next_state_reg;
reg [1:0] prev_state_reg;
reg [1:0] prev_prev_state_reg;
reg [1:0] metric0_reg;
reg [1:0] metric1_reg;
reg [1:0] metric2_reg;
reg [1:0] metric3_reg;

wire [k-1:0] data_in_reg;
assign data_in_reg = (reset) ? 0 : data_in;

wire [1:0] branch0;
wire [1:0] branch1;
wire [1:0] branch2;
wire [1:0] branch3;

assign branch0 = {data_in_reg[0], prev_state_reg[1]};
assign branch1 = {data_in_reg[0], prev_prev_state_reg[1]};
assign branch2 = {data_in_reg[1], prev_state_reg[1]};
assign branch3 = {data_in_reg[1], prev_prev_state_reg[1]};

always @(posedge reset or posedge data_in_reg) begin
  if (reset) begin
    encoded_reg <= 0;
    data_out_reg <= 0;
    state_reg <= 0;
    next_state_reg <= 0;
    prev_state_reg <= 0;
    prev_prev_state_reg <= 0;
    metric0_reg <= 0;
    metric1_reg <= 0;
    metric2_reg <= 0;
    metric3_reg <= 0;
  end else begin
    // Convolutional Encoder
    next_state_reg[1] <= state_reg[0];
    next_state_reg[0] <= branch0[0] ^ branch1[0] ^ state_reg[0];
    encoded_reg[n-1] <= branch0[1] ^ branch1[1] ^ branch2[1] ^ branch3[1] ^ state_reg[0];
    encoded_reg[n-2:0] <= encoded_reg[n-3:0];

    // Viterbi Decoder
    metric0_reg <= metric1_reg + (branch0[1] ^ state_reg[0]);
    metric1_reg <= metric0_reg + (branch1[1] ^ state_reg[0]);
    metric2_reg <= metric3_reg + (branch2[1] ^ state_reg[0]);
    metric3_reg <= metric2_reg + (branch3[1] ^ state_reg[0]);

    if (state_reg == 0) begin
      if (metric0_reg <= metric2_reg) begin
        data_out_reg[0] <= 0;
        prev_prev_state_reg <= 0;
      end else begin
        data_out_reg[0] <= 1;
        prev_prev_state_reg <= 1;
      end
      prev_state_reg <= 0;
      next_state_reg <= 1;
    end else begin
      if (metric1_reg <= metric3_reg) begin
        data_out_reg[1] <= 0;
        prev_prev_state_reg <= 0;
      end else begin
        data_out_reg[1] <= 1;
        prev_prev_state_reg <= 1;
      end
      prev_state_reg <= 1;
      next_state_reg <= 0;
    end

    state_reg <= next_state_reg;
  end
end

assign encoded = encoded_reg;
assign data_out = data_out_reg;

endmodule

module uart_fifo(
    input        clock,
    input        reset,
    input        write,
    input  [7:0] data_in,
    input        read,
    input        RxD,
    output       TxD,
    output [7:0] data_out,
    output       data_ready,
    output [8:0] rx_count
    );

