        .clock          (clock),
        .reset          (reset),
        .enQ            (write),
        .deQ            (tx_fifo_deQ),
        .data_in        (data_in),
        .data_out       (tx_fifo_data_out),
        .empty          (tx_fifo_empty),
        .count          ()
    );

    FIFO_NoFull_Count #(
        .DATA_WIDTH     (DATA_WIDTH),
        .ADDR_WIDTH     (ADDR_WIDTH))
        rx_buffer (
        .clock          (clock),
        .reset          (reset),
        .enQ            (rx_data_ready),
        .deQ            (read),
        .data_in        (rx_data),
        .data_out       (data_out),
        .empty          (rx_fifo_empty),
        .count          (rx_count)
    );

