module barrel_shifter (
    input [3:0] A,
    input [1:0] B,
    output [3:0] Q,
    output COUT
);

reg [3:0] Q_reg;
reg COUT_reg;

always @(*) begin
    case(B)
        2'b00: begin
            Q_reg = A;
            COUT_reg = 1'b0;
        end
        2'b01: begin
            Q_reg = {A[2:0], COUT_reg};
            COUT_reg = A[3];
        end
        2'b10: begin
            Q_reg = {COUT_reg, A[3:1]};
            COUT_reg = A[0];
        end
        2'b11: begin
            Q_reg = {COUT_reg, A[3], A[2]};
            COUT_reg = A[1];
        end
    endcase
end

assign Q = Q_reg;
assign COUT = COUT_reg;

endmodule

module pipelined_module(
    input [3:0] in,
    output out_and,
    output out_or,
    output out_xor
);

reg [3:0] stage1_out;
reg [2:0] stage2_out;

// Stage 1
assign stage1_out[0] = in[0] & in[1];
assign stage1_out[1] = in[2] & in[3];
assign stage1_out[2] = in[1] & in[2];
assign stage1_out[3] = in[0] & in[3];

// Stage 2
assign stage2_out[0] = stage1_out[0] | stage1_out[1];
assign stage2_out[1] = stage1_out[2] | stage1_out[3];
assign stage2_out[2] = stage1_out[0] ^ stage1_out[1] ^ stage1_out[2] ^ stage1_out[3];

// Stage 3
assign out_and = stage2_out[0];
assign out_or = stage2_out[1];
assign out_xor = stage2_out[2];

endmodule

