module axi_to_fifo_converter
    #(
        parameter DATA_WIDTH = 32,
        parameter ADDR_WIDTH = 3,
        parameter BURST_LEN_WIDTH = 8
    )
    (
        input clk,
        input rst,
        input [DATA_WIDTH-1:0] axi_araddr,
        input [2:0] axi_arburst,
        input [ADDR_WIDTH-1:0] axi_arlen,
        input [DATA_WIDTH-1:0] axi_rdata,
        input axi_rlast,
        input axi_rvalid,
        input [DATA_WIDTH-1:0] fifo_data_in,
        input fifo_wr_en,
        output [DATA_WIDTH-1:0] fifo_data_out,
        output fifo_rd_en,
        output reg [ADDR_WIDTH-1:0] skid_buf,
        output reg [1:0] state
    );

    // Constants
    localparam IDLE = 2'b00;
    localparam READ_AXI = 2'b01;
    localparam WRITE_FIFO = 2'b10;

    // Registers
    reg [DATA_WIDTH-1:0] axi_data_reg;
    reg [ADDR_WIDTH-1:0] axi_addr_reg;
    reg [BURST_LEN_WIDTH-1:0] axi_burst_len_reg;
    reg [2:0] axi_burst_type_reg;
    reg [1:0] state_reg;
    reg [DATA_WIDTH-1:0] fifo_data_reg;
    reg fifo_rd_en_reg;
    reg [ADDR_WIDTH-1:0] skid_buf_reg;

    always @(posedge clk) begin
        if (rst) begin
            axi_data_reg <= 0;
            axi_addr_reg <= 0;
            axi_burst_len_reg <= 0;
            axi_burst_type_reg <= 0;
            state_reg <= IDLE;
            fifo_data_reg <= 0;
            fifo_rd_en_reg <= 0;
            skid_buf_reg <= 0;
        end else begin
            case (state_reg)
                IDLE: begin
                    if (axi_rvalid) begin
                        axi_data_reg <= axi_rdata;
                        if (axi_rlast) begin
                            axi_addr_reg <= 0;
                            axi_burst_len_reg <= 0;
                            axi_burst_type_reg <= 0;
                            state_reg <= WRITE_FIFO;
                        end else begin
                            axi_addr_reg <= axi_addr_reg + 1;
                        end
                    end else if (fifo_wr_en) begin
                        fifo_data_reg <= fifo_data_in;
                        fifo_rd_en_reg <= 1;
                        state_reg <= READ_AXI;
                    end
                end
                READ_AXI: begin
                    if (axi_rvalid) begin
                        axi_data_reg <= axi_rdata;
                        if (axi_rlast) begin
                            axi_addr_reg <= 0;
                            axi_burst_len_reg <= 0;
                            axi_burst_type_reg <= 0;
                            state_reg <= WRITE_FIFO;
                        end else begin
                            axi_addr_reg <= axi_addr_reg + 1;
                        end
                    end else begin
                        fifo_rd_en_reg <= 0;
                        state_reg <= IDLE;
                    end
                end
                WRITE_FIFO: begin
                    fifo_data_reg <= axi_data_reg;
                    fifo_rd_en_reg <= 1;
                    if (axi_burst_len_reg == axi_addr_reg) begin
                        axi_burst_len_reg <= 0;
                        axi_burst_type_reg <= 0;
                        axi_addr_reg <= 0;
                        state_reg <= IDLE;
                    end else begin
                        axi_addr_reg <= axi_addr_reg + 1;
                    end
                end
            endcase
            skid_buf_reg <= skid_buf_reg + (fifo_rd_en_reg ? 1 : 0) - (axi_rvalid ? 1 : 0);
        end
    end

    assign fifo_data_out = fifo_data_reg;
    assign fifo_rd_en = fifo_rd_en_reg;
    assign skid_buf = skid_buf_reg;
    assign state = state_reg;

endmodule

module binary_adder(
    input [3:0] A,
    input [3:0] B,
    input C,
    output [3:0] S,
    output C_out
);

    wire [3:0] Xor1, Xor2, And1, And2, And3;
    wire [2:0] Or1, Or2, Or3;

    // Full adder for bit 0
    full_adder FA0(
        .A(A[0]),
        .B(B[0]),
        .C(C),
        .S(S[0]),
        .C_out(And1[0])
    );

    // Full adder for bit 1
    full_adder FA1(
        .A(A[1]),
        .B(B[1]),
        .C(And1[0]),
        .S(S[1]),
        .C_out(And1[1])
    );

    // Full adder for bit 2
    full_adder FA2(
        .A(A[2]),
        .B(B[2]),
        .C(And1[1]),
        .S(S[2]),
        .C_out(And1[2])
    );

    // Full adder for bit 3
    full_adder FA3(
        .A(A[3]),
        .B(B[3]),
        .C(And1[2]),
        .S(S[3]),
        .C_out(C_out)
    );

    // Xor gates for sum bits
    xor X1(
        .A(A[0]),
        .B(B[0]),
        .Y(Xor1[0])
    );
    xor X2(
        .A(A[1]),
        .B(B[1]),
        .Y(Xor1[1])
    );
    xor X3(
        .A(A[2]),
        .B(B[2]),
        .Y(Xor1[2])
    );
    xor X4(
        .A(A[3]),
        .B(B[3]),
        .Y(Xor1[3])
    );

    // Xor gates for carry bits
    xor X5(
        .A(C),
        .B(Xor1[0]),
        .Y(Xor2[0])
    );
    xor X6(
        .A(And1[0]),
        .B(Xor1[1]),
        .Y(Xor2[1])
    );
    xor X7(
        .A(And1[1]),
        .B(Xor1[2]),
        .Y(Xor2[2])
    );
    xor X8(
        .A(And1[2]),
        .B(Xor1[3]),
        .Y(Xor2[3])
    );

    // And gates for carry bits
    and A1(
        .A(Xor1[0]),
        .B(And1[0]),
        .Y(And2[0])
    );
    and A2(
        .A(Xor1[1]),
        .B(And1[1]),
        .Y(And2[1])
    );
    and A3(
        .A(Xor1[2]),
        .B(And1[2]),
        .Y(And2[2])
    );
    and A4(
        .A(Xor1[3]),
        .B(C),
        .Y(And2[3])
    );

    // Or gates for carry bits
    or O1(
        .A(And2[0]),
        .B(Xor2[1]),
        .C(Xor2[2]),
        .Y(Or1[0])
    );
    or O2(
        .A(And2[1]),
        .B(Xor2[2]),
        .C(Xor2[3]),
        .Y(Or1[1])
    );
    or O3(
        .A(And2[2]),
        .B(Xor2[3]),
        .Y(Or1[2])
    );

    // Or gate for carry-out bit
    or O4(
        .A(And2[3]),
        .B(Or1[0]),
        .C(Or1[1]),
        .D(Or1[2]),
        .Y(C_out)
    );

endmodule

module full_adder(
    input A,
    input B,
    input C_in,
    output S,
    output C_out
);

    wire And1, And2, Xor1, Xor2;

    // And gates for carry bits
    and A1(
        .A(A),
        .B(B),
        .Y(And1)
    );
    and A2(
        .A(B),
        .B(C_in),
        .Y(And2)
    );

    // Xor gates for sum and carry-out bits
    xor X1(
        .A(A),
        .B(B),
        .Y(Xor1)
    );
    xor X2(
        .A(Xor1),
        .B(C_in),
        .Y(Xor2)
    );

    assign S = Xor2;
    assign C_out = Or1;

    // Or gate for carry-out bit
    or O1(
        .A(And1),
        .B(And2),
        .Y(Or1)
    );

endmodule

