module top_module (
    input wire [15:0] in,
    input wire [7:0] a,
    input wire [7:0] b,
    output wire [7:0] out
);

    wire [7:0] hi_byte;
    wire [7:0] lo_byte;
    wire [7:0] sum;
    wire overflow;

    byte_splitter splitter(
        .in(in),
        .out_hi(hi_byte),
        .out_lo(lo_byte)
    );

    add_overflow_detection adder(
        .a(a),
        .b(hi_byte),
        .s(sum),
        .overflow(overflow)
    );

    add_overflow_detection adder2(
        .a(b),
        .b(lo_byte),
        .s(sum),
        .overflow(overflow)
    );

    assign out = sum;

endmodule

module byte_splitter (
    input wire [15:0] in,
