module Cache (
  input clk,
  input we,
  input [31:0] addr,
  input [31:0] write_data,
  output [31:0] read_data
);

parameter cache_size = 1024; // number of memory locations in the cache
parameter block_size = 64; // number of bytes stored in each memory location

reg [31:0] cache_mem [cache_size-1:0]; // array of registers to store data in the cache

// read data from the cache
assign read_data = cache_mem[addr % cache_size];

// write data to the cache
always @(posedge clk) begin
  if (we) begin
    cache_mem[addr % cache_size] <= write_data;
  end
end

