module Hyperbolic (
  input x,
  output sineh,
  output cosh,
  output tanh
);

  // Define the exponential function
  function [31:0] exp;
    input [31:0] x;
    begin
      exp = $realtobits($exp(x));
    end
  endfunction

  // Calculate e^x and e^(-x)
  wire [31:0] exp_x = exp(x);
  wire [31:0] exp_neg_x = exp(-x);

  // Calculate sineh(x), cosh(x), and tanh(x)
  assign sineh = (exp_x - exp_neg_x) >> 1;
  assign cosh = (exp_x + exp_neg_x) >> 1;
  assign tanh = sineh / cosh;

endmodule

