    wire valid;
    wire [3:0] shifted_data;
    assign shifted_data = {q2, q1, data_in[2:1]};

    nandgate n1(q1, d1, clk);
    nandgate n2(q2, d2, clk);
    inverter inv1(d1, clk);
    inverter inv2(d2, clk);

    mux2to1 mux1(data_out, shifted_data, load);

    valid_logic valid1(valid, load, data_in, shifted_data);

endmodule

