module priority_encoder (in0, in1, out);
input in0;
input in1;
output reg [1:0] out;

always @ (in0, in1) begin
    if (in0 && !in1) // in0 is high and in1 is low
        out <= 2'b01;
    else if (!in0 && in1) // in0 is low and in1 is high
        out <= 2'b10;
    else if (in0 && in1) // both inputs are high
        out <= 2'b10;
    else // both inputs are low
        out <= 2'b00;
end

endmodule

module multiplier (
    input [3:0] A,
    input [3:0] B,
    output [7:0] OUT
);

reg [7:0] result;
reg [3:0] temp_A;
reg [3:0] temp_B;

integer i;

always @(*) begin
    result = 8'b0;
    temp_A = A;
    temp_B = B;

    for (i = 0; i < 4; i = i + 1) begin
        if (temp_B[0]) begin
            result = result + (temp_A << i);
        end
        temp_B = temp_B >> 1;
    end

    OUT = result;
end

endmodule

