module ALU(input [10:0] OP,
           input [7:0] A,
           input [7:0] B,
           input CI,
           output reg CO,
           output reg VO,
           output reg SO,
           output reg ZO,
           output reg [7:0] Result,
           output reg [7:0] IntR);

  // Declare intermediate wires
  wire [7:0] add_out, sub_out, and_out, or_out, xor_out, inc_out, dec_out, sl_out, sr_out, rl_out, rr_out, slt_out;
  wire [7:0] add_in_b, sub_in_b, sl_in_b, sr_in_b, rl_in_b, rr_in_b;
  wire add_cout, sub_cout, sl_cout, sr_cout;

  // Define intermediate logic
  assign add_in_b = B;
  assign sub_in_b = ~B + 1;
  assign sl_in_b = B << 1;
  assign sr_in_b = B >> 1;
  assign rl_in_b = {B[6:0], B[7]};
  assign rr_in_b = {B[0], B[7:1]};

  MyAdder adder(.A(A), .B(add_in_b), .CI(CI), .S(add_out), .CO(add_cout));
  MyAdder adder_sub(.A(A), .B(sub_in_b), .CI(CI), .S(sub_out), .CO(sub_cout));
  assign and_out = A & B;
  assign or_out = A | B;
  assign xor_out = A ^ B;
  assign inc_out = A + 1;
  assign dec_out = A - 1;
  assign sl_out = sl_in_b;
  MyAdder shifter_r(.A({1'b0, A[7:1]}), .B({1'b0, sr_in_b}), .CI(CI), .S(sr_out), .CO(sr_cout));
  assign rl_out = rl_in_b;
  assign rr_out = rr_in_b;
  assign slt_out = (A < B) ? 1 : 0;

  // Select output based on OP
  always @(*) begin
    case (OP)
      2'b00_00: begin // ADD
        IntR = add_out;
        Result = add_out;
        CO = add_cout;
        VO = (A[7] == B[7] && A[7] != Result[7]) ? 1 : 0;
        SO = Result[7];
        ZO = (Result == 0) ? 1 : 0;
      end
      2'b00_01: begin // SUB
        IntR = sub_out;
        Result = sub_out;
        CO = sub_cout;
        VO = (A[7] != B[7] && A[7] != Result[7]) ? 1 : 0;
        SO = Result[7];
        ZO = (Result == 0) ? 1 : 0;
      end
      2'b00_10: begin // AND
        IntR = and_out;
        Result = and_out;
        CO = 1'b0;
        VO = 1'b0;
        SO = Result[7];
        ZO = (Result == 0) ? 1 : 0;
      end
      2'b00_11: begin // OR
        IntR = or_out;
        Result = or_out;
        CO = 1'b0;
        VO = 1'b0;
        SO = Result[7];
        ZO = (Result == 0) ? 1 : 0;
      end
      2'b01_00: begin // XOR
        IntR = xor_out;
        Result = xor_out;
        CO = 1'b0;
        VO = 1'b0;
        SO = Result[7];
        ZO = (Result == 0) ? 1 : 0;
      end
      2'b01_01: begin // INC
        IntR = inc_out;
        Result = inc_out;
        CO = (A == 8'hFF) ? 1 : 0;
        VO = (A[7] == 1 && Result[7] == 0) ? 1 : 0;
        SO = Result[7];
        ZO = (Result == 0) ? 1 : 0;
      end
      2'b01_10: begin // DEC
        IntR = dec_out;
        Result = dec_out;
        CO = (A == 8'h00) ? 1 : 0;
        VO = (A[7] == 0 && Result[7] == 1) ? 1 : 0;
        SO = Result[7];
        ZO = (Result == 0) ? 1 : 0;
      end
      2'b01_11: begin // SHL
        IntR = sl_out;
        Result = sl_out;
        CO = A[7];
        VO = (A[7] != Result[7]) ? 1 : 0;
        SO = Result[7];
        ZO = (Result == 0) ? 1 : 0;
      end
      2'b10_00: begin // SHR
        IntR = sr_out;
        Result = sr_out;
        CO = A[0];
        VO = 1'b0;
        SO = Result[7];
        ZO = (Result == 0) ? 1 : 0;
      end
      2'b10_01: begin // ROL
        IntR = rl_out;
        Result = rl_out;
        CO = A[7];
        VO = (A[7] != Result[7]) ? 1 : 0;
        SO = Result[7];
        ZO = (Result == 0) ? 1 : 0;
      end
      2'b10_10: begin // ROR
        IntR = rr_out;
        Result = rr_out;
        CO = A[0];
        VO = (A[0] != Result[0]) ? 1 : 0;
        SO = Result[7];
        ZO = (Result == 0) ? 1 : 0;
      end
      2'b10_11: begin // SLT
        IntR = slt_out;
        Result = slt_out;
        CO = 1'b0;
        VO = 1'b0;
        SO = Result[7];
        ZO = (Result == 0) ? 1 : 0;
      end
      default: begin // Invalid OP
        IntR = 8'h00;
        Result = 8'h00;
        CO = 1'b0;
        VO = 1'b0;
        SO = 1'b0;
        ZO = 1'b0;
      end
    endcase
  end
endmodule

module MyAdder(A, B, CI, S, CO);
  input [7:0] A, B;
  input CI;
  output [7:0] S;
  output CO;
  wire [7:0] sum;
  assign sum = A + B + CI;
  assign S = sum;
  assign CO = (sum[8] == 1) ? 1 : 0;
endmodule

module binary_counter(
    input wire clk,
    input wire reset_b,
    input wire enable,
    output reg [3:0] count,
    output reg overflow
);

    always @(posedge clk) begin
        if (reset_b == 1'b0) begin
            count <= 4'b0000;
            overflow <= 1'b0;
        end else if (enable == 1'b1) begin
            if (count == 4'b1111) begin
                count <= 4'b0000;
                overflow <= 1'b1;
            end else begin
                count <= count + 1;
                overflow <= 1'b0;
            end
        end
    end

endmodule

module dlatch_reset (
    input D,
    input RESET_B,
    input GATE,
    input CLK,
    output Q,
    output Q_N
);

    wire AND1_out;
    wire AND2_out;
    wire OR1_out;
    wire NOT1_out;
    wire NOT2_out;

    // AND1 gate for GATE and CLK
    assign AND1_out = GATE & CLK;

    // AND2 gate for NOT GATE and CLK
    assign AND2_out = ~GATE & CLK;

    // OR1 gate for AND1_out and NOT RESET_B
    assign OR1_out = AND1_out | ~RESET_B;

    // NOT1 gate for OR1_out
    assign NOT1_out = ~OR1_out;

    // NOT2 gate for AND2_out
    assign NOT2_out = ~AND2_out;

    // D-latch with reset behavior
    sky130_fd_sc_hd__dlrbp dlatch (
        .Q(Q),
        .Q_N(Q_N),
        .RESET_B(NOT1_out),
        .D(D),
        .GATE(NOT2_out),
        .VPWR(1'b1),
        .VGND(1'b0),
        .VPB(1'b0),
        .VNB(1'b0)
    );

endmodule

module ALU(clk, rst, A, B, CTRL, RES);

input clk, rst;
input [31:0] A, B;
input [4:0] CTRL;
output reg [31:0] RES;

always @(posedge clk or posedge rst) begin
	if(rst) begin
		RES <= 0;
	end else begin
		case(CTRL)
			5'b00000: // addition
				RES <= A + B;
			5'b00001: // subtraction
				RES <= A - B;
			5'b00010: // bitwise AND
				RES <= A & B;
			5'b00011: // bitwise OR
				RES <= A | B;
			5'b00100: // bitwise XOR
				RES <= A ^ B;
			5'b00101: // logical shift left
				RES <= A << B;
			default:
				RES <= 0;
		endcase
	end
end

endmodule

