        if (rst) begin
            data_out <= 2'b00;
        end else if (en) begin
            case (data_in)
                4'b0000: data_out <= 2'b00;
                4'b0001: data_out <= 2'b01;
                4'b0010: data_out <= 2'b01;
                4'b0011: data_out <= 2'b10;
