module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

    wire [3:0] sum;

    full_adder fa0 (
        .A(A[0]),
        .B(B[0]),
        .Cin(Cin),
        .S(sum[0]),
        .Cout(carry0)
    );

    full_adder fa1 (
        .A(A[1]),
        .B(B[1]),
        .Cin(carry0),
        .S(sum[1]),
        .Cout(carry1)
    );

    full_adder fa2 (
        .A(A[2]),
        .B(B[2]),
        .Cin(carry1),
        .S(sum[2]),
        .Cout(carry2)
    );

    full_adder fa3 (
        .A(A[3]),
        .B(B[3]),
        .Cin(carry2),
        .S(sum[3]),
        .Cout(Cout)
    );

    assign S = sum;

