module xor_mux_module(
    input a,
    input b,
    input sel_xor,
    input sel_mux,
    output reg out
); 

    reg xor_out;
    reg mux_out;

    xor_gate xor_inst(
        .a(a),
        .b(b),
        .out(xor_out)
    );

    mux_2to1 mux_inst(
        .a(a),
        .b(b),
        .sel(sel_mux),
        .out(mux_out)
    );

    always @(*) begin
        if(sel_xor) begin
            out = xor_out;
        end
        else if(sel_mux) begin
            out = mux_out;
        end
        else begin
            out = 0;
        end

        if(sel_xor && sel_mux) begin
            out = 1;
        end
        else if(sel_xor || sel_mux) begin
            out = out;
        end
    end

endmodule

