module mux_4to1(
    input [3:0] in0,
    input [3:0] in1,
    input [3:0] in2,
    input [3:0] in3,
    input [1:0] sel,
    output [3:0] out);

    wire [3:0] mux0_out;
    wire [3:0] mux1_out;
    wire [3:0] and0_out;
    wire [3:0] and1_out;

    // 2-to-1 MUXes
    mux2to1 mux0(.in0(in0), .in1(in1), .sel(sel[0]), .out(mux0_out));
    mux2to1 mux1(.in0(in2), .in1(in3), .sel(sel[0]), .out(mux1_out));

    // AND gates
    assign and0_out = mux0_out & ~sel[1];
    assign and1_out = mux1_out & sel[1];

