module barrel_shifter (
    input [3:0] A,
    input [3:0] B,
    output [3:0] C
);

    assign C = (B[3]) ? {A[2:0], 3'b000} : 
                        (B[2]) ? {A[1:0], 2'b00, 2'b00} :
                                (B[1]) ? {A[0], 3'b0000} :
                                        A;

endmodule

module u_zap_tlb (
        input i_clk,
        input i_reset,
        input [31:0] i_address,
        input [31:0] i_address_nxt,
        input i_rd,
        input i_wr,
        input [31:0] i_cpsr,
        input [31:0] i_sr,
        input [31:0] i_dac_reg,
        input [31:0] i_baddr,
        input i_mmu_en,
        input i_tlb_inv,
        output reg [31:0] tlb_phy_addr,
        output reg [7:0] tlb_fsr,
        output reg [31:0] tlb_far,
        output reg tlb_fault,
        output reg tlb_cacheable,
        output reg tlb_busy,
        output reg wb_stb_nxt,
        output reg wb_cyc_nxt,
        output reg [31:0] wb_adr_nxt,
        output reg wb_wen_nxt,
        output reg [3:0] wb_sel_nxt,
        output reg [31:0] wb_dat_nxt,
        input [31:0] i_wb_dat,
        input i_wb_ack
);

    // Parameter Definitions
    parameter S0 = 2'b00;
    parameter S1 = 2'b01;
    parameter S2 = 2'b10;
    parameter CTI_CLASSIC = 2'b00;

    parameter LPAGE_TLB_ENTRIES = 16;
    parameter SPAGE_TLB_ENTRIES = 32;
    parameter SECTION_TLB_ENTRIES = 64;
    parameter FPAGE_TLB_ENTRIES = 128;

    // State Definitions
    reg [1:0] state_ff;
    reg [1:0] state_nxt;

    // Write-Back Definitions
    reg [2:0] wb_stb;
    reg [2:0] wb_cyc;
    reg [31:0] wb_adr;
    reg [2:0] wb_cti;
    reg [3:0] wb_sel;
    reg [31:0] wb_dat;
    reg wb_wen;

    // Sequential Block
    always @ ( posedge i_clk ) begin
        if ( i_reset ) begin
            state_ff <= S0;
            wb_stb <= 3'b0;
            wb_cyc <= 3'b0;
            wb_adr <= 32'b0;
            wb_cti <= CTI_CLASSIC;
            wb_sel <= 4'b0;
            wb_dat <= 32'b0;
            wb_wen <= 1'b0;
        end else begin
            state_ff <= state_nxt;
            wb_stb <= wb_stb_nxt;
            wb_cyc <= wb_cyc_nxt;
            wb_adr <= wb_adr_nxt;
            wb_cti <= wb_cti_nxt;
            wb_sel <= wb_sel_nxt;
            wb_dat <= wb_dat_nxt;
            wb_wen <= wb_wen_nxt;
        end
    end

    // Next state logic.
    always @* begin
        state_nxt = state_ff;

        // Change state only if strobe is inactive or strobe has just completed.
        if ( !wb_stb || (wb_stb && i_wb_ack) ) begin
            casez({wb_cyc[2],wb_cyc[1],wb_cyc[0]})
                3'b1?? : state_nxt = S2; // TLB.
                3'b01? : state_nxt = S1; // Tag.
                3'b001 : state_nxt = S0; // Cache.
                default: state_nxt = state_ff;                                       
            endcase
        end
    end

    // Route ACKs to respective masters.
    always @* begin
        case(state_ff)
            S0: wb_ack[0] = i_wb_ack;
            S1: wb_ack[1] = i_wb_ack;
            S2: wb_ack[2] = i_wb_ack;
        endcase
    end

    // Combo signals for external MUXing.
    always @* begin
        wb_stb_nxt = wb_stb[state_nxt];
        wb_cyc_nxt = wb_cyc[state_nxt];
        wb_adr_nxt = wb_adr[state_nxt];
        wb_dat_nxt = wb_dat[state_nxt];
        wb_cti_nxt = wb_cti[state_nxt];
        wb_sel_nxt = wb_sel[state_nxt];
        wb_wen_nxt = wb_wen[state_nxt];
    end

endmodule

