module mem_program_testbench(

// inputs
input clk,
input we,
input [MEM_WIDTH-1:0] addr,
input [INSTR_WIDTH-1:0] data_in,

// outputs
output [INSTR_WIDTH-1:0] data_out
);

// parameter for the number of tests
parameter N_TESTES = 6;

// parameter for the initial program counter
parameter PC_INITIAL = 0;

// counter for the number of tests
integer testes = 0;

// ROM instance
mem_program mem_inst (
    .clk(clk),
    .we(we),
    .addr(addr),
    .data_in(data_in),
    .data_out(data_out)
);

// initialize inputs
initial begin
    clk  = 0;
    addr = PC_INITIAL - 1;
    we   = 0;
    data_in = 0;
end

// clock generation
always begin
    #4;
    clk = ~clk;
end

// test cases
always @(negedge clk) begin
    case(testes)
        0: begin
            we = 1;
            addr = addr + 1;
            data_in = 32'h0050;
        end
        1: begin
            we = 1;
            addr = addr + 1;
            data_in = 32'h0850;
        end
        2: begin
            we = 1;
            addr = addr + 1;
            data_in = 32'h8152;
        end
        3: begin
            we = 0;
            addr = PC_INITIAL;
            data_in = 32'h1550;
        end
        4: begin
            we = 0;
            addr = addr+1;
            data_in = 32'h2875;
        end
        5: begin
            we = 0;
            addr = addr+1;
            data_in = 32'h1647;
        end
    endcase
    testes = testes + 1;
end

// display results
always @(posedge clk) begin
    if (testes >= 0 && testes <= N_TESTES) begin
        if (testes > 0) begin
            // stable outputs
            $display("\t ------- SAIDAS -------  ");
            $display("\t DATA_OUT (%3d): %h  ", INSTR_WIDTH, data_out);
            $display(" ");
        end
        if (testes < N_TESTES) begin
            // stable inputs
            $display("  Teste # %2d  =>  ", testes);
            $display("\t ------- ENTRADAS -------  ");
            $display("\t WE: %6d  ", we);
            $display("\t ADDR: %6d ", addr);
            $display("\t DATA_IN (%3d): %h  ", INSTR_WIDTH, data_in);
            $display(" ");
        end
    end
end

endmodule

module bitwise_xor
#(parameter WIDTH = 8)
(
  input         clk,
