module top_module (
    input clk,
    input reset,
    input select,
    input [7:0] d1, // 4-bit input for adder 1
    input [7:0] d2, // 4-bit input for adder 2
    output [7:0] q // Final 8-bit output from the functional module
);

    wire [3:0] sum1, sum2, sum_final;
    wire [1:0] select_wire;

    // Instantiate the two 4-bit adders with synchronous reset
    adder4bit adder1(.clk(clk), .reset(reset), .a(d1[3:0]), .b(d1[7:4]), .sum(sum1));
    adder4bit adder2(.clk(clk), .reset(reset), .a(d2[3:0]), .b(d2[7:4]), .sum(sum2));

    // Instantiate the 2-bit selector
    selector2bit selector(.select(select), .a(sum1), .b(sum2), .out(select_wire));

    // Instantiate the functional module that adds the two selected outputs
    adder2bit adder_final(.a(sum1), .b(sum2), .select(select_wire), .sum(sum_final));

    // Assign the final output to the output port
    assign q = {sum_final, 4'b0};

endmodule

