module shift_register_and (
    input clk,
    input reset, // Synchronous active-high reset
    input load,
    input ena,
    input [3:0] data,
    output [7:0] q
);

    reg [3:0] counter;
    reg [3:0] shift_reg [0:3];
    wire [3:0] shift_reg_out;
    reg [1:0] priority_ctrl;

    // Counter
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 4'b0;
        end else begin
            counter <= counter + 1;
        end
    end

    // Shift Register
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            shift_reg <= 4'b0;
        end else if (load) begin
            shift_reg <= {data, shift_reg[3:1]};
        end else if (ena) begin
            shift_reg <= {1'b0, shift_reg[3:1]};
        end
    end

    // Priority Control
    always @* begin
        if (load) begin
            priority_ctrl <= 2'b11;
        end else if (ena) begin
            priority_ctrl <= 2'b10;
        end else begin
            priority_ctrl <= 2'b01;
        end
    end

    // Output
    assign shift_reg_out = {shift_reg[3], shift_reg[2], shift_reg[1], shift_reg[0]};
    assign q = shift_reg_out & 8'hAA; // Bitwise AND with constant value

endmodule

module synchronizer_FF
   (D,
    Q,
    m_aclk,
    rd_rst_reg_reg);
  output [3:0]Q;
  input [3:0]D;
  input m_aclk;
  input rd_rst_reg_reg;

  wire [3:0]Q_reg;
  wire m_aclk;
  wire rd_rst_reg_reg;

  // FDCE flip flops
  FDCE #(
    .INIT(1'b0)) 
    FDCE_0 
       (.C(m_aclk),
        .CE(1'b1),
        .CLR(rd_rst_reg_reg),
        .D(D[0]),
        .Q(Q_reg[0]));
  FDCE #(
    .INIT(1'b0)) 
    FDCE_1 
       (.C(m_aclk),
        .CE(1'b1),
        .CLR(rd_rst_reg_reg),
        .D(D[1]),
        .Q(Q_reg[1]));
  FDCE #(
    .INIT(1'b0)) 
    FDCE_2 
       (.C(m_aclk),
        .CE(1'b1),
        .CLR(rd_rst_reg_reg),
        .D(D[2]),
        .Q(Q_reg[2]));
  FDCE #(
    .INIT(1'b0)) 
    FDCE_3 
       (.C(m_aclk),
        .CE(1'b1),
        .CLR(rd_rst_reg_reg),
        .D(D[3]),
        .Q(Q_reg[3]));

  // Output data
  assign Q[3:0] = Q_reg;
