module dly_module #(
    parameter WIDTH=1
    )(
    input               clk,
    input               rst,
    input         [3:0] dly,
    input   [WIDTH-1:0] din,
    output  [WIDTH-1:0] dout
);

reg [WIDTH-1:0] delay_reg [0:15];
integer i;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        for (i = 0; i < 16; i = i + 1) begin
            delay_reg[i] <= {WIDTH{1'b0}};
        end
    end else begin
        for (i = 15; i > 0; i = i - 1) begin
            delay_reg[i] <= delay_reg[i - 1];
        end
        delay_reg[0] <= din;
    end
end

assign dout = delay_reg[dly];

endmodule

