    output [63:0] quotient,
    output [63:0] remainder
);

    wire [63:0] wire_mgl_prim1_quotient;
    wire [63:0] wire_mgl_prim1_remain;

    lpm_divide mgl_prim1 (
        .denom(divisor),
        .numer(dividend),
        .quotient(wire_mgl_prim1_quotient),
        .remain(wire_mgl_prim1_remain)
    ) ;

    assign quotient = wire_mgl_prim1_quotient;
    assign remainder = wire_mgl_prim1_remain;

    assign quotient = (divisor == 0) ? 0 : quotient;
    assign remainder = (divisor == 0) ? 0 : remainder;

    assign quotient = (dividend == 0) ? 0 : quotient;
    assign remainder = (dividend == 0) ? 0 : dividend;

endmodule

module dram_block ( address, data_write, mem_op, Data_out, unaligned, 
        data_read, read_op, write_op, nibble, write_byte, Address_toRAM, 
        Data_in );
  input [31:0] address;
  input [31:0] data_write;
  input [5:0] mem_op;
  input [31:0] Data_out;
  output [31:0] data_read;
  output [1:0] nibble;
  output [31:0] Address_toRAM;
  output [31:0] Data_in;
  output unaligned, read_op, write_op, write_byte;

  wire [31:0] aligned_address;
  assign aligned_address = address & ~(2'b11);

  wire [29:0] mem_address;
  assign mem_address = {2'b00, aligned_address[31:2]};

  wire [31:0] mem_data;
  assign mem_data = (write_byte) ? {24'b0, data_write[7:0]} : data_write;

  wire [1:0] byte_lanes;
  assign byte_lanes = (unaligned) ? address[1:0] : 2'b00;

  wire read_op_wire, write_op_wire;
  assign read_op_wire = (mem_op == 6'b000001) ? 1'b1 : 1'b0;
  assign write_op_wire = (mem_op == 6'b000010) ? 1'b1 : 1'b0;

  mmu_in_dram mmu_in0 ( .mem_op(mem_op), .aligned_address(aligned_address), .data(
        mem_data), .unaligned(unaligned), .nibble(nibble), .write_op(
        write_op_wire), .read_op(read_op_wire), .mem_address(mem_address), .mem_data(Data_in), 
        .write_byte(write_byte) );

  mmu_out_dram mmu_out0 ( .data_ram(Data_out), .mem_op(mem_op), .nibble(nibble), .unaligned(unaligned), .data_read(data_read) );

  assign Address_toRAM = {2'b00, aligned_address[31:2]};
  assign unaligned = (address[1:0] != 2'b00);
  assign read_op = read_op_wire;
  assign write_op = write_op_wire;
  assign nibble = byte_lanes;
endmodule

module carry_select_ripple_adder (
    input clk,
    input reset,
    input [31:0] a,
    input [31:0] b,
    output [31:0] cs_out,
    output [31:0] rc_out
);

    wire [31:0] cs_carry;
    wire [31:0] cs_sum;
    wire [15:0] rc_carry;
    wire [31:0] rc_sum;

    carry_select_adder cs_adder(
        .clk(clk),
        .reset(reset),
        .a(a),
        .b(b),
        .carry(cs_carry),
        .sum(cs_sum)
    );

    ripple_carry_adder rc_adder(
        .clk(clk),
        .reset(reset),
        .a(a[15:0]),
        .b(b[15:0]),
        .carry(rc_carry),
        .sum(rc_sum)
    );

    assign cs_out = {cs_carry[31], cs_sum};
    assign rc_out = {rc_carry[15], rc_sum[15:0], cs_sum[31:16]};

endmodule


module carry_select_adder (
    input clk,
    input reset,
    input [31:0] a,
    input [31:0] b,
    output [31:0] carry,
    output [31:0] sum
);

    wire [31:0] p;
    wire [31:0] g;
    wire [31:0] c;
    wire [31:0] s;

    assign p = a ^ b;
    assign g = a & b;
    assign c[0] = 1'b0;
    assign s[0] = p[0];

    genvar i;
    generate
        for (i = 1; i < 32; i = i + 1) begin : gen
            assign c[i] = (g[i-1] | (p[i-1] & c[i-1]));
            assign s[i] = p[i] ^ c[i-1];
        end
    endgenerate

    assign carry = c;
    assign sum = s;

endmodule


module ripple_carry_adder (
    input clk,
    input reset,
    input [15:0] a,
    input [15:0] b,
    output [15:0] carry,
    output [31:0] sum
);

    wire [15:0] c;
    wire [31:0] s;

    assign c[0] = 1'b0;
    assign s[0] = a[0] ^ b[0];

    genvar i;
    generate
        for (i = 1; i < 16; i = i + 1) begin : gen
            assign c[i] = (a[i] & b[i]) | (a[i] & c[i-1]) | (b[i] & c[i-1]);
            assign s[i] = a[i] ^ b[i] ^ c[i-1];
        end
    endgenerate

    assign carry = c;
    assign sum = {c[15], s};

endmodule


module top_module (
    input clk,
    input reset,
    input [31:0] a,
    input [31:0] b,
    output [31:0] sum
);

    wire [31:0] cs_out;
    wire [31:0] rc_out;

    carry_select_ripple_adder adder(
        .clk(clk),
        .reset(reset),
        .a(a),
        .b(b),
        .cs_out(cs_out),
        .rc_out(rc_out)
    );

    assign sum = (reset) ? 32'd0 : rc_out;

endmodule

module video_camera_decoder (
    // Inputs
    clk,
    reset,
    PIXEL_DATA,
    LINE_VALID,
    FRAME_VALID,
    ready,

    // Outputs
    data,
    startofpacket,
    endofpacket,
    valid
);

parameter DW = 9;

// Internal registers
reg [DW:0] pixel_data_reg;
reg line_valid_reg;
reg frame_valid_reg;
reg [DW:0] data_reg;
reg startofpacket_reg;
reg endofpacket_reg;
reg valid_reg;

// State machine states
localparam IDLE = 2'b00;
localparam WAIT_FOR_LINE = 2'b01;
localparam WAIT_FOR_FRAME = 2'b10;

// State machine signals
reg [1:0] state;
wire new_frame;
wire end_of_line;
wire end_of_frame;

// Detect new frame
assign new_frame = ~frame_valid_reg & FRAME_VALID;

// Detect end of line
assign end_of_line = line_valid_reg & ~LINE_VALID;

// Detect end of frame
assign end_of_frame = line_valid_reg & frame_valid_reg & ~FRAME_VALID;

// State machine
always @(posedge clk) begin
    if (reset) begin
        state <= IDLE;
    end else begin
        case (state)
            IDLE: begin
                if (ready) begin
                    pixel_data_reg <= PIXEL_DATA;
                    line_valid_reg <= LINE_VALID;
                    frame_valid_reg <= FRAME_VALID;
                    data_reg <= PIXEL_DATA;
                    startofpacket_reg <= new_frame;
                    endofpacket_reg <= end_of_line || end_of_frame;
                    valid_reg <= LINE_VALID & FRAME_VALID;
                    state <= WAIT_FOR_LINE;
                end
            end
            WAIT_FOR_LINE: begin
                if (ready) begin
                    pixel_data_reg <= PIXEL_DATA;
                    line_valid_reg <= LINE_VALID;
                    frame_valid_reg <= FRAME_VALID;
                    data_reg <= PIXEL_DATA;
                    startofpacket_reg <= 0;
                    endofpacket_reg <= end_of_line || end_of_frame;
                    valid_reg <= LINE_VALID & FRAME_VALID;
                    if (end_of_frame) begin
                        state <= WAIT_FOR_FRAME;
                    end
                end else begin
                    state <= IDLE;
                end
            end
            WAIT_FOR_FRAME: begin
                if (ready) begin
                    pixel_data_reg <= PIXEL_DATA;
                    line_valid_reg <= LINE_VALID;
                    frame_valid_reg <= FRAME_VALID;
                    data_reg <= PIXEL_DATA;
                    startofpacket_reg <= new_frame;
                    endofpacket_reg <= end_of_line || end_of_frame;
                    valid_reg <= LINE_VALID & FRAME_VALID;
                    if (new_frame) begin
                        state <= WAIT_FOR_LINE;
                    end else begin
                        state <= IDLE;
                    end
                end else begin
                    state <= WAIT_FOR_FRAME;
                end
            end
        endcase
    end
end

// Output registers
always @(posedge clk) begin
    if (reset) begin
        data <= 0;
        startofpacket <= 0;
        endofpacket <= 0;
        valid <= 0;
    end else begin
        data <= data_reg;
        startofpacket <= startofpacket_reg;
        endofpacket <= endofpacket_reg;
        valid <= valid_reg;
    end
end

endmodule

module calculator(A, B, OpCode, Result, Overflow);
    input [3:0] A, B;
    input [2:0] OpCode;
    output reg [3:0] Result;
    output reg Overflow;

    always @(*) begin
        case(OpCode)
            3'b000: begin // addition
                Result = A + B;
                Overflow = (Result > 4'b1111);
            end
            3'b001: begin // subtraction
                Result = A - B;
                Overflow = (Result < 0);
            end
            3'b010: begin // multiplication
                Result = A * B;
                Overflow = (Result > 4'b1111);
            end
            3'b011: begin // division
                if(B == 4'b0000) begin
                    Result = 4'b0000;
                    Overflow = 1;
                end else begin
                    Result = A / B;
                    Overflow = 0;
                end
            end
            default: begin // invalid opcode
                Result = 4'bxxxx;
                Overflow = 0;
            end
        endcase
    end
endmodule

module calculator_testbench;
    reg [3:0] A, B;
    reg [2:0] OpCode;
    wire [3:0] Result;
    wire Overflow;

    calculator dut(A, B, OpCode, Result, Overflow);

    initial begin
        // addition test
        A = 4'b0101;
        B = 4'b0011;
        OpCode = 3'b000;
        #10;
        if(Result !== 4'b1000 || Overflow !== 1'b0) $error("Addition test failed");

        // subtraction test
        A = 4'b0101;
        B = 4'b0011;
        OpCode = 3'b001;
        #10;
        if(Result !== 4'b0010 || Overflow !== 1'b0) $error("Subtraction test failed");

        // multiplication test
        A = 4'b0101;
        B = 4'b0011;
        OpCode = 3'b010;
        #10;
        if(Result !== 4'b1101 || Overflow !== 1'b0) $error("Multiplication test failed");

        // division test
        A = 4'b1010;
        B = 4'b0000;
        OpCode = 3'b011;
        #10;
        if(Result !== 4'b0000 || Overflow !== 1'b1) $error("Division by zero test failed");

        A = 4'b1010;
        B = 4'b0011;
        OpCode = 3'b011;
        #10;
        if(Result !== 4'b0010 || Overflow !== 1'b0) $error("Division test failed");

        // invalid opcode test
        A = 4'b0101;
        B = 4'b0011;
        OpCode = 3'b111;
        #10;
        if(Result !== 4'bxxxx || Overflow !== 1'b0) $error("Invalid opcode test failed");

        $display("All tests passed");
    end
endmodule

module dual_port_RAM (
    input clk,
    input rst_n,
    input write_en,
    input [7:0] write_addr,
    input [3:0] write_data,
    input read_en,
    input [7:0] read_addr,
    output reg [3:0] read_data
);

reg [3:0] mem [0:7];
reg [3:0] read_data_reg;
reg [7:0] write_addr_reg;
reg [3:0] write_data_reg;
reg [1:0] state;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        state <= 2'b00;
        read_data_reg <= 4'b0;
        write_addr_reg <= 8'b0;
        write_data_reg <= 4'b0;
    end else begin
        case (state)
            2'b00: begin
                if (write_en) begin
                    write_addr_reg <= write_addr;
                    write_data_reg <= write_data;
                    state <= 2'b01;
                end else if (read_en) begin
                    read_data_reg <= mem[read_addr];
                    state <= 2'b10;
                end
            end
            2'b01: begin
                mem[write_addr_reg] <= write_data_reg;
                state <= 2'b00;
            end
            2'b10: begin
                read_data <= read_data_reg;
                state <= 2'b00;
            end
        endcase
    end
end

endmodule

