module wbit1(
    input clk,
    input wrb,
    input reset,
    input enb,
    input din,
    output dout
);

reg [1:0] state;
reg q;

always @(posedge clk) begin
    if (reset) begin
        state <= 2'b00;
        q <= 1'b0;
    end else begin
        case (state)
            2'b00: begin
                if (wrb) begin
                    state <= 2'b01;
                    q <= din;
                end else begin
                    state <= 2'b00;
                end
            end
            2'b01: begin
                state <= 2'b10;
            end
            2'b10: begin
                if (enb) begin
                    state <= 2'b11;
                end else begin
                    state <= 2'b00;
                end
            end
            2'b11: begin
                state <= 2'b00;
            end
        endcase
    end
end

assign dout = q;

endmodule

