module simple_calculator(
    input [1:0] op,
    input [7:0] num1,
    input [7:0] num2,
    output [7:0] result
);

wire [15:0] temp;

assign temp = {op, num1} * {op[0], num2};
assign result = (op == 2'b00) ? num1 + num2 :
                (op == 2'b01) ? num1 - num2 :
                (op == 2'b10) ? temp[15:8] :
                (op == 2'b11) ? (temp[15:8] == 8'h00) ? 8'h00 : temp[15:8] / num2 :
                                8'h00;

endmodule

module counter
	(
		input wire iClock,
		input wire iReset,
		output wire oOut64,
		output wire oOut128,
		output wire oOut256
	);

	reg [16:0] rOscCounter; // log2(4194304/256) = 14. Last bit corresponds to the output.

	always @ (posedge iClock) begin
		if (iReset) begin
			rOscCounter <= 0;
		end
		else begin
			rOscCounter <= rOscCounter+1;
		end
	end

	assign oOut64 = (rOscCounter == 64) ? 1'b1 : 1'b0;
	assign oOut128 = (rOscCounter == 128) ? 1'b1 : 1'b0;
	assign oOut256 = (rOscCounter == 256) ? 1'b1 : 1'b0;

endmodule

module addrdecode(
    input clk,
    input [12:0] addr_in,
    output reg [9:0] bank0_addr,
    output reg [9:0] bank1_addr,
    output reg [9:0] bank2_addr,
    output reg [9:0] bank3_addr,
    output reg [1:0] sel,
    output reg odd
);

reg [9:0] bank0_addr_dly;
reg [9:0] bank1_addr_dly;
reg [9:0] bank2_addr_dly;
reg [9:0] bank3_addr_dly;
reg [1:0] sel_dly;
reg odd_dly;

wire [9:0] addr = addr_in[12:3];
wire [9:0] addr_pone = addr_in[12:3] + 1;

// Delay sel and odd by 2 clock cycles
always @(posedge clk) begin
    sel_dly <= sel;
    odd_dly <= odd;
end

always @(posedge clk) begin
    sel <= sel_dly;
    odd <= odd_dly;
end

// Decode the address
always @(posedge clk) begin
    case (addr_in[2:1])
        2'b00: begin
            bank0_addr_dly <= addr;
            bank1_addr_dly <= addr;
            bank2_addr_dly <= addr;
            bank3_addr_dly <= addr;
        end
        2'b01: begin
            bank0_addr_dly <= addr_pone;
            bank1_addr_dly <= addr;
            bank2_addr_dly <= addr;
            bank3_addr_dly <= addr;
        end
        2'b10: begin
            bank0_addr_dly <= addr_pone;
            bank1_addr_dly <= addr_pone;
            bank2_addr_dly <= addr;
            bank3_addr_dly <= addr;
        end
        2'b11: begin
            bank0_addr_dly <= addr_pone;
            bank1_addr_dly <= addr_pone;
            bank2_addr_dly <= addr_pone;
            bank3_addr_dly <= addr;
        end
    endcase
end

// Output the delayed bank addresses
always @(posedge clk) begin
    bank0_addr <= bank0_addr_dly;
    bank1_addr <= bank1_addr_dly;
    bank2_addr <= bank2_addr_dly;
    bank3_addr <= bank3_addr_dly;
end

endmodule

module Test(
    input clk,
    input reset,
    output reg [1:0] state,
    output reg myevent,
    output reg myevent_pending
);

    reg [1:0] next_state;
    reg [1:0] current_state;

    always @(posedge clk) begin
        if (reset) begin
            current_state <= 2'b00;
            myevent <= 1'b0;
            myevent_pending <= 1'b0;
        end
        else begin
            current_state <= next_state;
            myevent <= 1'b0;
            myevent_pending <= 1'b0;
        end
    end

    always @* begin
        case(current_state)
            2'b00: next_state = 2'b01;
            2'b01: next_state = 2'b10;
            2'b10: next_state = 2'b00;
        endcase
    end

    assign state = current_state;

    always @* begin
        if (current_state == 2'b10) begin
            myevent <= 1'b1;
        end
        else if (current_state == 2'b01) begin
            myevent_pending <= 1'b1;
        end
    end

endmodule

module TLATNTSCAX2TS (E, SE, CK, ECK, Q);
    input E, SE, CK, ECK;
    output Q;
    reg Q;

    always @(posedge ECK) begin
        if (E == 1'b1 && SE == 1'b0) begin
            Q <= CK;
        end
        else if (E == 1'b0) begin
            Q <= Q;
            if (ECK == 1'b1) begin
                Q <= CK;
            end
        end
        else if (SE == 1'b1) begin
            if (ECK == 1'b1) begin
                Q <= 1'b1;
            end
        end
    end
endmodule

module merge_branch_node(
    input clock,
    input resetn,
    input valid_in,
    input stall_in,
    input [31:0] workgroup_size,
    input start,
    output wire merge_node_stall_in,
    output wire stall_out,
    output wire valid_out
);

reg merge_node_valid_out_NO_SHIFT_REG;
reg merge_block_selector_NO_SHIFT_REG;
reg merge_node_valid_in_staging_reg_NO_SHIFT_REG;
reg is_merge_data_to_local_regs_valid_NO_SHIFT_REG;
reg invariant_valid_NO_SHIFT_REG;

wire branch_var__inputs_ready;
wire branch_var__output_regs_ready;

assign branch_var__inputs_ready = merge_node_valid_out_NO_SHIFT_REG;
assign branch_var__output_regs_ready = ~(stall_in);
assign merge_node_stall_in = (~(branch_var__output_regs_ready) | ~(branch_var__inputs_ready));
assign valid_out = branch_var__inputs_ready;

wire _entry;
wire _exit;
reg [31:0] _num_entry_NO_SHIFT_REG;
reg [31:0] _num_exit_NO_SHIFT_REG;
wire [31:0] _num_live;

assign _entry = ((&valid_in) & ~((|stall_out)));
assign _exit = ((&valid_out) & ~((|stall_in)));
assign _num_live = (_num_entry_NO_SHIFT_REG - _num_exit_NO_SHIFT_REG);

always @(posedge clock or negedge resetn)
begin
    if (~(resetn))
    begin
        _num_entry_NO_SHIFT_REG <= 32'h0;
        _num_exit_NO_SHIFT_REG <= 32'h0;
    end
    else
    begin
        if (_entry)
        begin
            _num_entry_NO_SHIFT_REG <= (_num_entry_NO_SHIFT_REG + 2'h1);
        end
        if (_exit)
        begin
            _num_exit_NO_SHIFT_REG <= (_num_exit_NO_SHIFT_REG + 2'h1);
        end
    end
end

always @(*)
begin
    if ((merge_node_valid_in_staging_reg_NO_SHIFT_REG | valid_in))
    begin
        merge_block_selector_NO_SHIFT_REG = 1'b0;
        is_merge_data_to_local_regs_valid_NO_SHIFT_REG = 1'b1;
    end
    else
    begin
        merge_block_selector_NO_SHIFT_REG = 1'b0;
        is_merge_data_to_local_regs_valid_NO_SHIFT_REG = 1'b0;
    end
end

always @(posedge clock or negedge resetn)
begin
    if (~(resetn))
    begin
        merge_node_valid_in_staging_reg_NO_SHIFT_REG <= 1'b0;
    end
    else
    begin
        if (((merge_block_selector_NO_SHIFT_REG != 1'b0) | (~(stall_in) & ~(merge_node_stall_in) & (merge_node_valid_out_NO_SHIFT_REG))))
        begin
            if (~(merge_node_valid_in_staging_reg_NO_SHIFT_REG))
            begin
                merge_node_valid_in_staging_reg_NO_SHIFT_REG <= valid_in;
            end
        end
        else
        begin
            merge_node_valid_in_staging_reg_NO_SHIFT_REG <= 1'b0;
        end
    end
end

always @(posedge clock or negedge resetn)
begin
    if (~(resetn))
    begin
        merge_node_valid_out_NO_SHIFT_REG <= 1'b0;
    end
    else
    begin
        if (~(merge_node_stall_in))
        begin
            merge_node_valid_out_NO_SHIFT_REG <= is_merge_data_to_local_regs_valid_NO_SHIFT_REG;
        end
        else
        begin
            merge_node_valid_out_NO_SHIFT_REG <= 1'b0;
        end
    end
end

always @(posedge clock or negedge resetn)
begin
    if (~(resetn))
    begin
        invariant_valid_NO_SHIFT_REG <= 1'b0;
    end
    else
    begin
        invariant_valid_NO_SHIFT_REG <= (~(start) & (invariant_valid_NO_SHIFT_REG | is_merge_data_to_local_regs_valid_NO_SHIFT_REG));
    end
end

assign stall_out = merge_node_valid_in_staging_reg_NO_SHIFT_REG;

endmodule

module assert_win_change_assume (
    input clk,
    input reset_n,
    input start_event,
    input end_event,
    input [width-1:0] test_expr,
    input [31:0] window,
    input xzdetect_test_expr,
    input xzcheck_enable,
    output change_assert
);

    parameter width = 8;

    reg [width-1:0] test_expr_reg;
    reg [31:0] window_reg;
    reg xzdetect_test_expr_reg;
    reg xzcheck_enable_reg;
    reg change_assert_reg;
    reg [31:0] window_count;

    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            test_expr_reg <= 0;
            window_reg <= 0;
            xzdetect_test_expr_reg <= 0;
            xzcheck_enable_reg <= 0;
            change_assert_reg <= 0;
            window_count <= 0;
        end else begin
            test_expr_reg <= test_expr;
            window_reg <= window;
            xzdetect_test_expr_reg <= xzdetect_test_expr;
            xzcheck_enable_reg <= xzcheck_enable;
            if (start_event) begin
                change_assert_reg <= 0;
                window_count <= 0;
            end else if (end_event) begin
                if (test_expr_reg && !xzcheck_enable_reg) begin
                    change_assert_reg <= 1;
                end else if (xzcheck_enable_reg && xzdetect_test_expr_reg) begin
                    change_assert_reg <= 1;
                end else begin
                    change_assert_reg <= 0;
                end
                window_count <= 0;
            end else begin
                if (test_expr_reg && !xzcheck_enable_reg) begin
                    change_assert_reg <= 1;
                end else if (xzcheck_enable_reg && xzdetect_test_expr_reg) begin
                    change_assert_reg <= 1;
                end else begin
                    change_assert_reg <= change_assert_reg;
                end
                if (window_count >= window_reg) begin
                    window_count <= 0;
                end else begin
                    window_count <= window_count + 1;
                end
            end
        end
    end

    assign change_assert = change_assert_reg;

endmodule

module uart_tx
(
    input wire clk,
    input wire reset,
    input wire tx_start,
    input wire s_tick,
    input wire [7:0] din,
    output reg tx_done_tick,
    output wire tx
);

    parameter DBIT = 8;
    parameter SB_TICK = 16;

    localparam IDLE = 0;
    localparam START = 1;
    localparam DATA = 2;
    localparam STOP = 3;

    reg [1:0] state_reg, state_next;
    reg [3:0] s_reg, s_next;
    reg [2:0] n_reg, n_next;
    reg [7:0] b_reg, b_next;
    reg tx_reg, tx_next;

    always @ (posedge clk, posedge reset) begin
        if (reset) begin
            state_reg <= IDLE;
            s_reg <= 0;
            n_reg <= 0;
            b_reg <= 0;
            tx_reg <= 1;
        end
        else begin
            state_reg <= state_next;
            s_reg <= s_next;
            n_reg <= n_next;
            b_reg <= b_next;
            tx_reg <= tx_next;
        end
    end

    always @ (state_reg, s_reg, n_reg, b_reg, s_tick, tx_start, din) begin
        state_next <= state_reg;
        s_next <= s_reg;
        n_next <= n_reg;
        b_next <= b_reg;
        tx_next <= tx_reg;
        tx_done_tick <= 0;

        case (state_reg)
            IDLE: begin
                tx_next <= 1;
                if (tx_start) begin
                    state_next <= START;
                    s_next <= 0;
                    b_next <= din;
                end
            end

            START: begin
                tx_next <= 0;
                if (s_tick) begin
                    if (s_reg == 15) begin
                        state_next <= DATA;
                        s_next <= 0;
                        n_next <= 0;
                    end
                    else
                        s_next <= s_reg + 1;
                end
            end

            DATA: begin
                tx_next <= b_reg[0];
                if (s_tick) begin
                    if (s_reg == 15) begin
                        s_next <= 0;
                        b_next <= {1'b0, b_reg[7:1]};
                        if (n_reg == DBIT-1)
                            state_next <= STOP;
                        else
                            n_next <= n_reg + 1;
                    end
                    else
                        s_next <= s_reg + 1;
                end
            end

            STOP: begin
                tx_next <= 1;
                if (s_tick) begin
                    if (s_reg == SB_TICK-1) begin
                        state_next <= IDLE;
                        tx_done_tick <= 1;
                    end
                    else
                        s_next <= s_reg + 1;
                end
            end
        endcase
    end

    assign tx = tx_reg;

endmodule

module dff_async_reset_gate_enable (
    Q,
    RESET_B,
    D,
    GATE_N
);

    output Q;
    input RESET_B, D, GATE_N;

    reg Q;

    always @(posedge GATE_N or negedge RESET_B) begin
        if (!RESET_B) begin
            Q <= 1'b0;
        end else if (!GATE_N) begin
            Q <= Q;
        end else begin
            Q <= D;
        end
    end

endmodule

module booth_multiplier (
  input clk,
  input reset,
  input [3:0] a,
  input [3:0] b,
  output reg [7:0] product
);

  reg [4:0] a_reg, b_reg;
  reg [2:0] count;
  reg [7:0] partial_product;
  reg [8:0] product_reg;
  reg [1:0] state;

  always @(posedge clk) begin
    if (reset) begin
      a_reg <= 0;
      b_reg <= 0;
      count <= 0;
      partial_product <= 0;
      product_reg <= 0;
      state <= 0;
    end else begin
      case (state)
        0: begin
          a_reg <= a;
          b_reg <= b;
          count <= 3;
          state <= 1;
        end
        1: begin
          if (count == 0) begin
            state <= 3;
          end else begin
            if ({a_reg[3], a_reg[2]} == 2'b01) begin
              partial_product <= b_reg << 1;
            end else if ({a_reg[3], a_reg[2]} == 2'b10) begin
              partial_product <= ~(b_reg << 1) + 1;
            end else begin
              partial_product <= 0;
            end
            count <= count - 1;
            a_reg <= {a_reg[2:0], a_reg[3]};
            state <= 2;
          end
        end
        2: begin
          partial_product <= partial_product >> 1;
          state <= 1;
        end
        3: begin
          product_reg <= {partial_product[6:0], 1'b0};
          state <= 4;
        end
        4: begin
          product_reg <= product_reg + {partial_product[7], partial_product[6:0], 1'b0};
          state <= 5;
        end
        5: begin
          product_reg <= product_reg + {partial_product[7], partial_product[6:0], 1'b0};
          state <= 6;
        end
        6: begin
          product_reg <= product_reg + {partial_product[7], partial_product[6:0], 1'b0};
          state <= 7;
        end
        7: begin
          product_reg <= product_reg + {partial_product[7], partial_product[6:0], 1'b0};
          product <= product_reg[7:0];
          state <= 0;
        end
      endcase
    end
  end

endmodule

module multiplier(
	input [3:0] A,
	input [3:0] B,
	output reg [7:0] P,
	output reg done
);

	reg [3:0] a_reg;
	reg [2:0] counter;
	reg [3:0] partial_product;

	always @(posedge clk) begin
		if (counter == 0) begin
			a_reg <= A;
			partial_product <= 0;
		end
		if (counter < 4) begin
			if (B[counter] == 1) begin
				partial_product <= partial_product + (a_reg << counter);
			end
			counter <= counter + 1;
		end
		if (counter == 4) begin
			P <= partial_product;
			done <= 1;
			counter <= counter + 1;
		end
	end

endmodule

module full_adder (
  input wire A,
  input wire B,
  input wire C_in,
  input wire clk,
  output reg Sum,
  output reg C_out
);

  // Intermediate wires
  wire wire1;
  wire wire2;
  wire wire3;

  // Register inputs
  sky130_fd_sc_ms__d_ff_posedge dff_A (.D(A), .CLK(clk), .Q(wire1));
  sky130_fd_sc_ms__d_ff_posedge dff_B (.D(B), .CLK(clk), .Q(wire2));
  sky130_fd_sc_ms__d_ff_posedge dff_C_in (.D(C_in), .CLK(clk), .Q(wire3));

  // Intermediate signals
  wire xor1_out;
  wire xor2_out;
  wire and1_out;
  wire and2_out;
  wire or1_out;
  wire or2_out;
  wire inv1_out;
  wire inv2_out;

  // XOR gates
  sky130_fd_sc_ms__xor2 xor1 (.A(wire1), .B(wire2), .O(xor1_out));
  sky130_fd_sc_ms__xor2 xor2 (.A(xor1_out), .B(wire3), .O(xor2_out));

  // AND gates
  sky130_fd_sc_ms__and2 and1 (.A(wire1), .B(wire2), .O(and1_out));
  sky130_fd_sc_ms__and2 and2 (.A(xor1_out), .B(wire3), .O(and2_out));

  // OR gates
  sky130_fd_sc_ms__or2 or1 (.A(and1_out), .B(and2_out), .O(or1_out));
  sky130_fd_sc_ms__or2 or2 (.A(xor2_out), .B(or1_out), .O(or2_out));

  // Inverters
  sky130_fd_sc_ms__inv inv1 (.A(and1_out), .ZN(inv1_out));
  sky130_fd_sc_ms__inv inv2 (.A(and2_out), .ZN(inv2_out));

  // Output registers
  sky130_fd_sc_ms__d_ff_posedge dff_Sum (.D(or2_out), .CLK(clk), .Q(Sum));
  sky130_fd_sc_ms__d_ff_posedge dff_C_out (.D(inv1_out), .CLK(clk), .Q(C_out));

endmodule

module barrel_shifter_priority_encoder (
    input [15:0] A,
    input [15:0] B,
    input [3:0] shift_amount,
    input select,
    output [2:0] Y,
    output EN
);

    wire [15:0] shifted_input;
    wire [1:0] priority_input;
    wire [1:0] highest_input;

    // Barrel Shifter module
    barrel_shifter bs (
        .data_in(select ? B : A),
        .shift_amount(shift_amount),
        .data_out(shifted_input)
    );

    // Priority Encoder module
    priority_encoder pe (
        .data_in(shifted_input),
        .priority_input(priority_input),
        .highest_input(highest_input)
    );

    // Output logic
    assign Y = (highest_input == 2'b00) ? 2'b01 : (highest_input == 2'b01) ? 2'b10 : 2'b11;
    assign EN = (priority_input == 2'b11);

endmodule

module barrel_shifter (
    input [15:0] data_in,
    input [3:0] shift_amount,
    output [15:0] data_out
);

    assign data_out = (shift_amount == 0) ? data_in : (shift_amount < 0) ? {data_in, {-shift_amount}} : (shift_amount > 0) ? {data_in[shift_amount-1:0], {shift_amount{1'b0}}} : data_in;

endmodule

module priority_encoder (
    input [15:0] data_in,
    output [1:0] priority_input,
    output [1:0] highest_input
);

    assign priority_input = (data_in[15] == 1) ? 2'b01 : (data_in[14] == 1) ? 2'b10 : 2'b00;
    assign highest_input = (priority_input == 2'b00) ? (data_in[0] == 1) ? 2'b01 : 2'b00 : (priority_input == 2'b01) ? (data_in[1] == 1) ? 2'b10 : 2'b01 : (data_in[2] == 1) ? 2'b11 : 2'b10;

endmodule

module and_gate(
    input A,
    input B,
    output Y
);

assign Y = A & B;

endmodule

module and_gate_tb;

reg A;
reg B;
wire Y;

and_gate dut(
    .A(A),
    .B(B),
    .Y(Y)
);

initial begin
    // Test case 1: A=0, B=0
    A = 0;
