module mult_16bit_signed (
    input signed [15:0] M,
    input signed [15:0] N,
    output reg signed [31:0] P
);

    always @(*) begin
        P = M * N;
    end

endmodule

module adder_1bit (
    input a,
    input b,
    input carry_in,
    output sum,
    output carry_out
);

    assign sum = a ^ b ^ carry_in;
    assign carry_out = (a & b) | (carry_in & (a ^ b));

endmodule

module functional_module (
    input [1:0] sum1,
    input [1:0] sum2,
    input [1:0] carry1,
    input [1:0] carry2,
    output [1:0] out
);

    assign out[0] = sum1[0] ^ sum2[0] ^ carry1[0] ^ carry2[0];
    assign out[1] = sum1[1] ^ sum2[1] ^ carry1[1] ^ carry2[1];

endmodule

module top_module (
    input clk,
    input reset,    // Synchronous active-high reset
    input [1:0] in1, // 2 1-bit inputs for the first adder
    input [1:0] in2, // 2 1-bit inputs for the second adder
    output [1:0] out // 2-bit output from the functional module
);

    reg [1:0] sum1;
    reg [1:0] sum2;
    reg [1:0] carry1;
    reg [1:0] carry2;

    adder_1bit adder1(.a(in1[0]), .b(in1[1]), .carry_in(1'b0), .sum(sum1[0]), .carry_out(carry1[0]));
    adder_1bit adder2(.a(in2[0]), .b(in2[1]), .carry_in(1'b0), .sum(sum2[0]), .carry_out(carry2[0]));

    always @(posedge clk) begin
        if (reset) begin
            sum1 <= 2'b0;
            sum2 <= 2'b0;
            carry1 <= 2'b0;
            carry2 <= 2'b0;
        end else begin
            sum1 <= {carry1[0], adder1.sum};
            sum2 <= {carry2[0], adder2.sum};
            carry1 <= {carry1[1], adder1.carry_out};
            carry2 <= {carry2[1], adder2.carry_out};
        end
    end

    functional_module func(.sum1(sum1), .sum2(sum2), .carry1(carry1), .carry2(carry2), .out(out));

endmodule

module clock_generator
  ( input       i
  , input       we_i
  , input       async_reset_neg_i
  , input [1:0] sel_i

  , output o
  , output buf_o
  );

  wire [1:0] sel_r;
  wire [1:0] mux_lo;
  wire [3:0] ft;
  wire       i_inv;

  // if wen, capture the select line shortly after a transition
  // from 1 to 0 of the input i

  SC7P5T_CKINVX4_SSC14SL I0 ( .CLK(i)    , .Z(i_inv) );     // decouple load of FDT from previous stage; also makes this inverting
  SC7P5T_CKINVX2_SSC14SL I1 ( .CLK(i_inv), .Z(ft[0]) );
  SC7P5T_CKINVX2_SSC14SL I2 ( .CLK(i_inv), .Z(ft[1]) );
  SC7P5T_CKINVX3_SSC14SL I2_1 ( .CLK(ft[1]), .Z() );
  SC7P5T_CKINVX2_SSC14SL I3 ( .CLK(i_inv), .Z(ft[2]) );
  SC7P5T_CKINVX3_SSC14SL I3_1 ( .CLK(ft[2]), .Z() );
  SC7P5T_CKINVX3_SSC14SL I3_2 ( .CLK(ft[2]), .Z() );
  SC7P5T_CKINVX2_SSC14SL I4 ( .CLK(i_inv), .Z(ft[3]) );
  SC7P5T_CKINVX3_SSC14SL I4_1 ( .CLK(ft[3]), .Z() );
  SC7P5T_CKINVX3_SSC14SL I4_2 ( .CLK(ft[3]), .Z() );
  SC7P5T_CKINVX3_SSC14SL I4_3 ( .CLK(ft[3]), .Z() );

  // synopsys rp_fill (0 0 UX)

  SC7P5T_MUX2X1_SSC14SL X1 ( .D0(sel_r[0]), .D1(sel_i[0]), .S(we_i), .Z(mux_lo[0]) );
  SC7P5T_DFFRQX4_SSC14SL DFFR1 ( .D(mux_lo[0]), .CLK(o), .Q(sel_r[0]), .RESET(async_reset_neg_i) );


  SC7P5T_MUXI4X4_SSC14SL M2 ( .D0(ft[3]), .D1(ft[2]), .D2(ft[1]), .D3(ft[0]), .S0(sel_r[0]), .S1(sel_r[1]), .Z(o) );

  // capture on positive edge
  SC7P5T_DFFRQX4_SSC14SL DFFR2 ( .D(mux_lo[1]), .CLK(o), .Q(sel_r[1]), .RESET(async_reset_neg_i) );

  SC7P5T_MUX2X1_SSC14SL MX2 ( .D0(sel_r [1]), .D1(sel_i[1]), .S(we_i), .Z(mux_lo[1]) );

  // synopsys rp_fill (3 2 UX)

  SC7P5T_CKBUFX8_SSC14SL ICLK ( .CLK(o), .Z(buf_o) );

endmodule

module half_subtractor (
  input A,
  input B,
  output D,
  output Borrow
);

  assign D = A ^ B;
  assign Borrow = B & ~A;

endmodule

module full_subtractor (
  input A,
  input B,
  input C_in,
  output D,
  output Borrow
);

  wire half_sub1_D, half_sub1_B, half_sub2_D, half_sub2_B;

  half_subtractor half_sub1 (
    .A(A),
    .B(B),
    .D(half_sub1_D),
    .Borrow(half_sub1_B)
  );

  half_subtractor half_sub2 (
    .A(half_sub1_D),
    .B(C_in),
    .D(half_sub2_D),
    .Borrow(half_sub2_B)
  );

  assign D = half_sub2_D;
  assign Borrow = half_sub1_B | half_sub2_B;

endmodule

module top_module (
    input [3:0] A,
    input [3:0] B,
    input enable,
    output reg [3:0] q
);

  wire greater_or_equal;
  magnitude_comparator comparator(A, B, greater_or_equal);
  mux mux_inst(A, B, enable, q);

  always @ (greater_or_equal, enable) begin
    if (greater_or_equal && enable) begin
      q <= A;
    end else begin
      q <= B;
    end
  end

endmodule

module magnitude_comparator (
    input [3:0] A,
    input [3:0] B,
    output reg greater_or_equal
);

  always @ (A, B) begin
    if (A >= B) begin
      greater_or_equal <= 1;
    end else begin
      greater_or_equal <= 0;
    end
  end

endmodule

module mux (
    input data_0,
    input data_1,
    input enable,
    output reg out
);

  always @ (data_0, data_1, enable) begin
    if (enable) begin
      out <= data_0;
    end else begin
      out <= data_1;
    end
  end

endmodule

module assert_unchange_assert (
    input clk, reset_n, start_event, xzcheck_enable,
    input [width-1:0] test_expr,
    input window, ignore_new_start, reset_on_new_start, error_on_new_start,
    output reg pass, fail, error
);

    parameter width = 8;
    parameter num_cks = 2;

    reg [width-1:0] prev_test_expr;
    reg [num_cks-1:0] window_counter;
    reg start_detected;
    reg reset_detected;

    always @(posedge clk) begin
        if (!reset_n) begin
            prev_test_expr <= 'bx;
            window_counter <= 0;
            start_detected <= 0;
            reset_detected <= 0;
            pass <= 0;
            fail <= 0;
            error <= 0;
        end else begin
            if (reset_detected) begin
                prev_test_expr <= 'bx;
                window_counter <= 0;
                start_detected <= 0;
                reset_detected <= 0;
                pass <= 0;
                fail <= 0;
                error <= 0;
            end else begin
                if (start_event && !start_detected) begin
                    prev_test_expr <= test_expr;
                    window_counter <= 1;
                    start_detected <= 1;
                    reset_detected <= 0;
                    pass <= 0;
                    fail <= 0;
                    error <= 0;
                end else if (start_event && reset_on_new_start) begin
                    prev_test_expr <= test_expr;
                    window_counter <= 1;
                    start_detected <= 1;
                    reset_detected <= 0;
                    pass <= 0;
                    fail <= 0;
                    error <= error_on_new_start;
                end else if (start_event && error_on_new_start) begin
                    prev_test_expr <= 'bx;
                    window_counter <= 0;
                    start_detected <= 0;
                    reset_detected <= 0;
                    pass <= 0;
                    fail <= 0;
                    error <= 1;
                end else if (start_detected && window_counter < window) begin
                    if (test_expr !== prev_test_expr && xzcheck_enable) begin
                        fail <= 1;
                        error <= 1;
                    end else begin
                        fail <= 0;
                        error <= 0;
                    end
                    prev_test_expr <= test_expr;
                    window_counter <= window_counter + 1;
                    pass <= 0;
                end else if (start_detected && window_counter == window) begin
                    if (test_expr !== prev_test_expr && xzcheck_enable) begin
                        fail <= 1;
                        error <= 1;
                    end else begin
                        fail <= 0;
                        error <= 0;
                    end
                    prev_test_expr <= test_expr;
                    window_counter <= 0;
                    start_detected <= ignore_new_start;
                    reset_detected <= 0;
                    pass <= 1;
                end else if (start_detected && ignore_new_start) begin
                    if (test_expr !== prev_test_expr && xzcheck_enable) begin
                        fail <= 1;
                        error <= 1;
                    end else begin
                        fail <= 0;
                        error <= 0;
                    end
                    prev_test_expr <= test_expr;
                    window_counter <= window_counter + 1;
                    pass <= 0;
                end else if (start_detected && reset_on_new_start) begin
                    prev_test_expr <= test_expr;
                    window_counter <= 1;
                    start_detected <= 1;
                    reset_detected <= 1;
                    pass <= 0;
                    fail <= 0;
                    error <= 0;
                end else if (start_detected && error_on_new_start) begin
                    prev_test_expr <= 'bx;
                    window_counter <= 0;
                    start_detected <= 0;
                    reset_detected <= 0;
                    pass <= 0;
                    fail <= 0;
                    error <= 1;
                end
            end
        end
    end

endmodule

module top_module(
