module shift_reg(
    clock,
    si,
    load,
    data,
    so
);

input clock, si, load;
input [4:0] data;
output so;

wire [4:0] q; // Output of the flip-flop

gl_dff5er dff(
    .clock(clock),
    .data(q),
    .enable(~load),
    .sclr(load),
    .q(q)
);

reg [4:0] shift_reg; // Internal state of the shift register

always @(posedge clock) begin
    if(load) begin
        shift_reg <= data;
