module LIFO (
  input clk,
  input rst,
  input [data_width-1:0] din,
  input wr_en,
  input rd_en,
  output [data_width-1:0] dout
);

  parameter data_width = 8;
  parameter depth = 16;

  reg [data_width-1:0] memory [0:depth-1];
  reg [4:0] top = 0;
  reg [4:0] bottom = 0;
  reg [4:0] count = 0;

  always @(posedge clk) begin
    if (rst) begin
      top <= 0;
      bottom <= 0;
      count <= 0;
    end else begin
      if (wr_en && count < depth) begin
        memory[top] <= din;
        top <= top + 1;
        count <= count + 1;
      end
      if (rd_en && count > 0) begin
        dout <= memory[bottom];
        bottom <= bottom + 1;
        count <= count - 1;
      end
    end
  end

endmodule

module SD_Controller (
  input [5:0] cmd,
  input [31:0] arg,
  input clk,
  input [31:0] dat,
  input [31:0] addr,
  input rd_en,
  input wr_en,
  output [31:0] dat_out,
  output [5:0] rsp
);

  // Define necessary signals for host communication with SD card
  reg [47:0] cmd_arg;
  reg [7:0] crc;
  reg [31:0] dat_resp;
  reg [5:0] rsp_reg;

  // Define necessary signals for device communication with SD card
  reg [31:0] dat_out_reg;
  reg [7:0] status_reg;
  reg [7:0] data_resp_reg;
  reg [7:0] crc_reg;

  // Define necessary constants for SD card communication
  parameter CMD_GO_IDLE_STATE = 6'b000000;
  parameter CMD_SEND_OP_COND = 6'b010000;
  parameter CMD_SEND_IF_COND = 6'b010001;
  parameter CMD_SEND_CSD = 6'b010110;
  parameter CMD_SEND_CID = 6'b010111;
  parameter CMD_READ_SINGLE_BLOCK = 6'b110101;
  parameter CMD_WRITE_SINGLE_BLOCK = 6'b111111;
  parameter RSP_IDLE = 6'b000000;
  parameter RSP_IN_IDLE_STATE = 6'b000001;
  parameter RSP_CRC_ERROR = 6'b000010;
  parameter RSP_ILLEGAL_COMMAND = 6'b000011;
  parameter RSP_DATA_ERROR = 6'b000100;
  parameter RSP_SUCCESS = 6'b001000;

  // Host communication with SD card
  always @(posedge clk) begin
    case(cmd)
      CMD_GO_IDLE_STATE: begin
        cmd_arg = {32'h00000000, 16'h0000};
        crc = 8'h95;
        rsp_reg = RSP_SUCCESS;
      end
      CMD_SEND_OP_COND: begin
        cmd_arg = {arg, 16'h0000};
        crc = 8'h87;
        rsp_reg = RSP_SUCCESS;
      end
      CMD_SEND_IF_COND: begin
        cmd_arg = {arg, 16'h0000};
        crc = 8'h87;
        rsp_reg = RSP_SUCCESS;
      end
      CMD_SEND_CSD: begin
        cmd_arg = {arg, 16'h0000};
        crc = 8'h87;
        rsp_reg = RSP_SUCCESS;
      end
      CMD_SEND_CID: begin
        cmd_arg = {arg, 16'h0000};
        crc = 8'h87;
        rsp_reg = RSP_SUCCESS;
      end
      CMD_READ_SINGLE_BLOCK: begin
        cmd_arg = {addr, 16'h0000};
        crc = 8'h95;
        rsp_reg = RSP_SUCCESS;
      end
      CMD_WRITE_SINGLE_BLOCK: begin
        cmd_arg = {addr, 16'h0000};
        crc = 8'h95;
        rsp_reg = RSP_SUCCESS;
      end
      default: begin
        cmd_arg = {32'h00000000, 16'h0000};
        crc = 8'h00;
        rsp_reg = RSP_ILLEGAL_COMMAND;
      end
    endcase
  end

  // Device communication with SD card
  always @(posedge clk) begin
    if(rd_en) begin
      dat_out_reg <= dat_resp;
      status_reg <= data_resp_reg;
      crc_reg <= crc;
    end
    else if(wr_en) begin
      dat_out_reg <= 32'h00000000;
      status_reg <= 8'h00;
      crc_reg <= crc;
    end
    else begin
      dat_out_reg <= 32'h00000000;
      status_reg <= 8'h00;
      crc_reg <= 8'h00;
    end
  end

  // Output signals
  assign dat_out = dat_out_reg;
  assign rsp = rsp_reg;

  // SD card communication
  always @(posedge clk) begin
    case(rsp_reg)
      RSP_SUCCESS: begin
        case(cmd)
          CMD_GO_IDLE_STATE: begin
            dat_resp <= 32'h00000000;
            data_resp_reg <= 8'h01;
          end
          CMD_SEND_OP_COND: begin
            dat_resp <= 32'h00000000;
            data_resp_reg <= 8'h01;
          end
          CMD_SEND_IF_COND: begin
            dat_resp <= 32'h000001AA;
            data_resp_reg <= 8'h01;
          end
          CMD_SEND_CSD: begin
            dat_resp <= 32'h00000000;
            data_resp_reg <= 8'h01;
          end
          CMD_SEND_CID: begin
            dat_resp <= 32'h00000000;
            data_resp_reg <= 8'h01;
          end
          CMD_READ_SINGLE_BLOCK: begin
            dat_resp <= dat;
            data_resp_reg <= 8'h01;
          end
          CMD_WRITE_SINGLE_BLOCK: begin
            dat_resp <= 32'h00000000;
            data_resp_reg <= 8'h01;
          end
          default: begin
            dat_resp <= 32'h00000000;
            data_resp_reg <= 8'h00;
          end
        endcase
      end
      default: begin
        dat_resp <= 32'h00000000;
        data_resp_reg <= 8'h00;
      end
    endcase
  end

endmodule

