module fsm_4bit_binary_counter (
  input clk,
  input reset,
  input enable,
  output reg [3:0] count
);

  reg [1:0] state;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      state <= 2'b00;
      count <= 4'b0000;
    end else begin
      case (state)
        2'b00: begin
          if (enable) begin
            state <= 2'b01;
            count <= count + 1;
          end
        end
        2'b01: begin
          if (enable) begin
            state <= 2'b10;
            count <= count + 1;
          end else begin
            state <= 2'b00;
          end
        end
        2'b10: begin
          if (enable) begin
            state <= 2'b11;
            count <= count + 1;
          end else begin
            state <= 2'b00;
          end
        end
        2'b11: begin
          if (enable) begin
            state <= 2'b01;
            count <= count + 1;
          end else begin
            state <= 2'b00;
          end
        end
      endcase
    end
  end
endmodule

module SDP (
    input CLKA, CEA, CLKB, CEB,
    input OCE,
    input RESETA, RESETB,
    input WREA, WREB,
    input [13:0] ADA, ADB,
    input [31:0] DI,
    input [2:0] BLKSEL,
    output [31:0] DO
);

parameter READ_MODE = 1'b0;
parameter BIT_WIDTH_0 = 32;
parameter BIT_WIDTH_1 = 32;

reg [31:0] ram [0:63][0:255];
reg [31:0] out_reg_a, out_reg_b;
reg [7:0] blk_sel_a, blk_sel_b;
wire [31:0] data_out_a, data_out_b;
wire [7:0] addr_a, addr_b;

assign DO = (blk_sel_a == BLKSEL) ? data_out_a : data_out_b;

assign addr_a = ADA[7:0];
assign addr_b = ADB[7:0];

assign data_out_a = ram[blk_sel_a][addr_a];
assign data_out_b = ram[blk_sel_b][addr_b];

always @(posedge CLKA) begin
    if (RESETA) begin
        out_reg_a <= 32'h0;
        blk_sel_a <= 8'h0;
    end else begin
        if (WREA) begin
            ram[blk_sel_a][addr_a] <= DI;
        end
        out_reg_a <= (READ_MODE) ? data_out_a : DI;
        blk_sel_a <= BLKSEL;
    end
end

always @(posedge CLKB) begin
    if (RESETB) begin
        out_reg_b <= 32'h0;
        blk_sel_b <= 8'h0;
    end else begin
        if (WREB) begin
            ram[blk_sel_b][addr_b] <= DI;
        end
        out_reg_b <= (READ_MODE) ? data_out_b : DI;
        blk_sel_b <= BLKSEL;
    end
end

assign OCE = 1'b1;

endmodule

