module seq_detector (
  input clk,
  input [n-1:0] in,
  output out
);

parameter n = 4; // length of input sequence
parameter seq = "1010"; // specified sequence to detect

reg [n-1:0] state;
reg out_reg;

always @(posedge clk) begin
  case(state)
    0: if(in == seq[0]) state <= 1;
       else state <= 0;
    1: if(in == seq[1]) state <= 2;
       else if(in == seq[0]) state <= 1;
       else state <= 0;
    2: if(in == seq[2]) state <= 3;
       else if(in == seq[0]) state <= 1;
       else state <= 0;
    3: if(in == seq[3]) begin
         state <= 4;
         out_reg <= 1;
       end
       else if(in == seq[0]) state <= 1;
       else state <= 0;
    4: state <= 4;
  endcase
end

assign out = out_reg;

endmodule

module dvr(
    input clk,
    input reset,
    input start,
    input stop,
    input [15:0] data,
    output reg recording,
    output reg [15:0] data_out
);

reg [15:0] data_reg;
reg [1:0] state;

parameter IDLE = 2'b00, RECORDING = 2'b01, OUTPUTTING = 2'b10;

always @(posedge clk) begin
    if (reset) begin
        state <= IDLE;
        recording <= 0;
        data_out <= 0;
        data_reg <= 0;
    end else begin
        case (state)
            IDLE: begin
                if (start) begin
                    state <= RECORDING;
                    recording <= 1;
                    data_reg <= data;
                end
            end
            RECORDING: begin
                if (stop) begin
                    state <= OUTPUTTING;
                    recording <= 0;
                end else begin
                    data_reg <= data;
                end
            end
            OUTPUTTING: begin
                if (!stop) begin
                    state <= IDLE;
                    data_out <= data_reg;
                end
            end
        endcase
    end
end

endmodule

