module wifi_transmitter (
  input [n-1:0] data,
  input clk,
  input reset,
  input start,
  output [n-1:0] tx_data
);

parameter n = 8; // number of bits in input data signals

reg [n-1:0] tx_reg; // register to hold transmit data
reg tx_enable; // flag to enable transmission
reg tx_done; // flag to indicate completion of transmission

always @(posedge clk) begin
  if (reset) begin
    tx_enable <= 0;
    tx_done <= 0;
    tx_reg <= 0;
  end else begin
    if (start) begin
      tx_enable <= 1;
      tx_done <= 0;
      tx_reg <= data;
    end else if (tx_enable) begin
      tx_enable <= 0;
      tx_done <= 1;
      tx_reg <= 0;
    end
  end
end

assign tx_data = tx_reg;

endmodule
