module FDSE_tb;

  // Inputs
  reg C;
  reg CE;
  reg D;
  reg S;

  // Outputs
  wire Q;

  // Instantiate the Unit Under Test (UUT)
  FDSE uut (
    .C(C),
    .CE(CE),
    .D(D),
    .S(S),
    .Q(Q)
  );

  // Clock period definitions
  parameter PERIOD = 10;

  // Initial variable values
  integer i;
  integer j;
  integer k;
  integer l;
  integer m;
  integer n;

  initial begin
    // Initialize inputs
    C = 0;
    CE = 0;
    D = 0;
    S = 0;

    // Wait 100 ns for global reset to finish
    #100;

    // Toggle clock and check output at each clock edge
    for (i = 0; i < 10; i = i + 1) begin
      // Toggle clock
      C = ~C;

      // Check output at positive clock edge
      if (C == 1) begin
        // Check output after 1 clock cycle
        #PERIOD;
        if (Q !== D) begin
          $display("Error: Q does not match D after 1 clock cycle");
          $finish;
        end

        // Set input
        D = 1;
        #PERIOD;
        if (Q !== 1) begin
          $display("Error: Q does not match expected value after set input");
          $finish;
        end

        // Reset input
        D = 0;
        S = 1;
        #PERIOD;
        if (Q !== 0) begin
          $display("Error: Q does not match expected value after reset input");
          $finish;
        end

        // Clear reset input
        S = 0;
        #PERIOD;
        if (Q !== 0) begin
          $display("Error: Q does not match expected value after clear reset input");
          $finish;
        end

        // Inverted clock input
        `ifdef XIL_TIMING
        FDSE #(
          .INIT(INIT),
          .IS_C_INVERTED(1),
          .IS_D_INVERTED(IS_D_INVERTED),
          .IS_S_INVERTED(IS_S_INVERTED)
        ) uut (
          .C(~C),
          .CE(CE),
          .D(D),
          .S(S),
          .Q(Q)
        );
        #PERIOD;
        if (Q !== 0) begin
          $display("Error: Q does not match expected value with inverted clock input");
          $finish;
        end
        `endif

        // Inverted data input
        `ifdef XIL_TIMING
        FDSE #(
          .INIT(INIT),
          .IS_C_INVERTED(IS_C_INVERTED),
          .IS_D_INVERTED(1),
          .IS_S_INVERTED(IS_S_INVERTED)
        ) uut (
          .C(C),
          .CE(CE),
          .D(~D),
          .S(S),
          .Q(Q)
        );
        #PERIOD;
        if (Q !== 1) begin
          $display("Error: Q does not match expected value with inverted data input");
          $finish;
        end
        `endif

        // Inverted set input
        `ifdef XIL_TIMING
        FDSE #(
          .INIT(INIT),
          .IS_C_INVERTED(IS_C_INVERTED),
          .IS_D_INVERTED(IS_D_INVERTED),
          .IS_S_INVERTED(1)
        ) uut (
          .C(C),
          .CE(CE),
          .D(D),
          .S(~S),
          .Q(Q)
        );
        #PERIOD;
        if (Q !== 1) begin
          $display("Error: Q does not match expected value with inverted set input");
          $finish;
        end
        `endif
      end
    end

    // Done testing
    $display("Testbench completed successfully");
    $finish;
  end

endmodule

