module arithmetic_module (
    input clk,
    input scan_enable,
    input [31:0] in_rs,
    input [15:0] in_rt,
    output reg [31:0] out_rd,
    input udi_ctl_thr_wr,
    input [1:0] udi_ctl_sum_mode,
    input udi_ctl_res_sel
);

    wire [31:0] mult_i_out;
    wire [31:0] mult_q_out;
    wire [31:0] threshold;
    wire [32:0] sum;
    wire [31:0] sum_out;
    wire comp_res;

    localparam CTL_SUM_MODE_NONE = 2'b00;
    localparam CTL_SUM_MODE_SUM = 2'b01;
    localparam CTL_SUM_MODE_SUMSHIFT = 2'b10;
    localparam CTL_SUM_MODE_BYPASS = 2'b11;

    mvp_cregister_wide #(32) _udi_thr_31_0_(
        .Q(threshold),
        .scan_enable(scan_enable),
        .D(in_rs),
        .clk(clk),
        .wr(udi_ctl_thr_wr)
    );

    mult_16_x_16_res_32 mult_16_x_16_res_32_u1(
        .clk(clk),
        .a(in_rs[31:16]),
        .b(in_rt[31:16]),
        .p(mult_i_out)
    );

    mult_16_x_16_res_32 mult_16_x_16_res_32_u2(
        .clk(clk),
        .a(in_rs[15:0]),
        .b(in_rt[15:0]),
        .p(mult_q_out)
    );

    mvp_register #(32) _udi_sum_out_31_0_(
        .Q(sum),
        .clk(clk),
        .D(sum_out)
    );

    always @(posedge clk) begin
        sum_out <= (udi_ctl_sum_mode == CTL_SUM_MODE_SUM) ? sum[31:0] :
                   (udi_ctl_sum_mode == CTL_SUM_MODE_SUMSHIFT) ? sum[32:1] :
                   (udi_ctl_sum_mode == CTL_SUM_MODE_BYPASS) ? mult_i_out : 32'd0;
    end

    always @(posedge clk) begin
        out_rd <= (udi_ctl_res_sel) ? {30'd0, comp_res} : sum_out[31:0];
    end

    assign sum = mult_i_out + mult_q_out;

    always @(posedge clk) begin
        comp_res <= (sum_out > threshold) ? 1'b1 : 1'b0;
    end

endmodule

