module top_module (
    input clk,
    input reset,
    input load,
    input [3:0] min_range,
    input [3:0] max_range,
    input [3:0] num1,
    input [3:0] num2,
    output reg gt,
    output reg eq,
    output reg lt,
    output reg in_range
);

reg [3:0] reference_value;
wire [4:0] sum;
wire [2:0] comparison_result;

// Instantiate the 4-bit ripple carry adder module
ripple_carry_adder adder(
    .clk(clk),
    .reset(reset),
    .a(num1),
    .b(num2),
    .sum(sum)
);

// Instantiate the 3-bit comparator module
comparator comparator(
    .a(sum[3:1]),
    .b(reference_value[3:1]),
    .result(comparison_result[2])
);
comparator comparator1(
    .a(sum[0]),
    .b(reference_value[0]),
    .result(comparison_result[1])
);
comparator comparator2(
    .a(sum[3:0]),
    .b(reference_value[3:0]),
    .result(comparison_result[0])
);

// Output signals based on comparison results
always @ (posedge clk) begin
    if (load) begin
        reference_value <= num1;
    end
    if (comparison_result == 3'b100) begin
        gt <= 1;
        eq <= 0;
        lt <= 0;
    end else if (comparison_result == 3'b010) begin
        gt <= 0;
        eq <= 1;
        lt <= 0;
    end else if (comparison_result == 3'b001) begin
        gt <= 0;
        eq <= 0;
        lt <= 1;
    end else begin
        gt <= 0;
        eq <= 0;
        lt <= 0;
    end
    if (sum >= reference_value - min_range && sum <= reference_value + max_range) begin
        in_range <= 1;
    end else begin
        in_range <= 0;
    end
end

endmodule

