module ripple_carry_adder (
    input clk,
    input reset,
    input [3:0] a,
    input [3:0] b,
    output reg [4:0] sum
);

always @ (posedge clk) begin
    if (reset) begin
        sum <= 0;
    end else begin
        sum <= {1'b0, a} + {1'b0, b};
    end
end

endmodule

// 3-bit comparator module
module comparator (
    input [2:0] a,
    input [2:0] b,
    output reg [2:0] result
);

always @ (*) begin
    if (a > b) begin
        result <= 3'b100;
    end else if (a == b) begin
        result <= 3'b010;
    end else begin
        result <= 3'b001;
    end
end

endmodule

module RLE (
  input [n-1:0] indata,
  output [m-1:0] outdata
);

parameter n = 8; // number of bits in the input data
parameter m = 16; // number of bits in the output data

reg [7:0] count; // counter for run-length encoding
reg [n-1:0] symbol; // current symbol being encoded
reg [m-1:0] compressed_data; // compressed data output
reg [n-1:0] decompressed_data; // decompressed data output

integer i; // loop index

always @(*) begin
  count = 0;
  symbol = indata[0];
  compressed_data = 0;
  decompressed_data = 0;

  for (i = 0; i < n; i = i + 1) begin
    if (indata[i] == symbol) begin
      count = count + 1;
    end else begin
      compressed_data = {compressed_data, count, symbol};
      decompressed_data = {decompressed_data, {count{symbol}}};
      count = 1;
      symbol = indata[i];
    end
  end

  compressed_data = {compressed_data, count, symbol};
  decompressed_data = {decompressed_data, {count{symbol}}};
end

assign outdata = decompressed_data;

endmodule

module addsub(
    input [3:0] A,
    input [3:0] B,
    input SUB,
    input CLK,
    output reg [3:0] SUM,
    output reg OVERFLOW
);

    reg [3:0] temp;
    reg [4:0] temp2;
    reg carry;

    always @(posedge CLK) begin
        if (SUB) begin
            temp = A - B;
            carry = (temp[3] == 1);
        end else begin
            temp = A + B;
            carry = (temp[4] == 1);
        end

        if (carry) begin
            temp2 = {1'b1, temp};
            if (SUB) begin
                SUM = temp2[3:0];
                OVERFLOW = (temp2[4] != temp[3]);
            end else begin
                SUM = temp2[2:0];
                OVERFLOW = (temp2[4] != carry);
            end
        end else begin
            SUM = temp;
            OVERFLOW = 1'b0;
        end
    end

endmodule

