module submodule_generator (
  input wire clk,
  input wire rst,
  input wire [31:0] submodule_count,
  input wire [31:0] submodule_input_width,
  input wire [31:0] submodule_output_width,
  input wire [31:0] submodule_input_offset,
  input wire [31:0] submodule_output_offset,
  input wire [31:0] submodule_instance_offset,
  input wire [31:0] signal_offset,
  output wire [31:0] submodule_instance_count,
  output wire [31:0] signal_count,
  output wire [31:0] signal_list [0:1023],
  output wire [31:0] instance_list [0:1023]
);

  // Define internal signals
  wire [31:0] submodule_index;
  wire [31:0] submodule_input_signal;
  wire [31:0] submodule_output_signal;
  wire [31:0] submodule_instance_signal;
  wire [31:0] signal_index;
  wire [31:0] instance_index;
  wire [31:0] instance_count;

  // Generate signal assignments
  assign submodule_input_signal = signal_offset + submodule_input_offset;
  assign submodule_output_signal = signal_offset + submodule_output_offset;
  assign submodule_instance_signal = signal_offset + submodule_instance_offset;

  // Generate instances and port mappings
  assign instance_count = 0;
  genvar i;
  generate
    for (i = 0; i < submodule_count; i = i + 1) begin : submodule_loop
      // Generate instance name
      assign instance_list[instance_index] = submodule_instance_signal + (instance_count * 32);
      assign instance_count = instance_count + 1;

      // Generate input port mapping
      assign signal_index = submodule_input_signal + (i * submodule_input_width);
