// 100Mhz ÷ 2^2 = 25MHz
assign pix_en = ~q[1] & ~q[0];

// 100Mhz ÷ 2^8 = 390.625KHz
assign display_en = q[14] & ~q[13] & ~q[12] & ~q[11] & ~q[10] & ~q[9] & ~q[8] & ~q[7] & ~q[6] & ~q[5] & ~q[4] & ~q[3]& ~q[2] & ~q[1]& ~q[0];

