module barrel_shifter (
    input [3:0] A,
    input [1:0] shift,
    output reg [3:0] Q
);
    always @(*) begin
        case (shift)
            2'b00: Q = A; // no shift
            2'b01: Q = {A[2:0], 1'b0}; // shift left by 1
            2'b10: Q = {1'b0, A[3:1]}; // shift right by 1
            2'b11: Q = {A[1:0], 2'b00}; // shift right by 2
        endcase
    end
endmodule

// Define the up/down counter module
module up_down_counter (
    input clk,
    input U_D,
    output reg [3:0] Q
);
    always @(posedge clk) begin
        if (U_D == 1'b1) begin
            Q <= Q + 1;
        end else begin
            Q <= Q - 1;
        end
    end
endmodule

// Define the bitwise OR module
module bitwise_or (
    input [3:0] A,
    input [3:0] B,
    output reg [3:0] Q
);
    always @(*) begin
        Q = A | B;
    end
