            3'b001: begin // f = ~b
                f = ~b;
            end
            3'b010: begin // f = a & b
                f = a & b;
            end
            3'b011: begin // f = a | b
                f = a | b;
            end
            3'b100: begin // f = a >>> 1
                f = a >>> 1;
            end
            3'b101: begin // f = a <<< 1
                f = a <<< 1;
            end
            3'b110: begin // zero = a == b
