    output [5:0] out_not
);

    // Shift register to store inverted input values
    reg [5:0] inverted_input_reg;

    // Combinational circuit for bitwise-OR and logical-OR operations
    wire [2:0] or_bitwise = a | b;
    wire or_logical = (a != 0) || (b != 0);

    // 2-to-1 multiplexer to select between bitwise-OR and logical-OR operations
    wire [2:0] selected_output;
    assign selected_output = sel_b1 ? or_logical : or_bitwise;

    // Invert selected output and store in upper half of out_not
    assign out_not[5:3] = ~selected_output;

    // Store non-inverted selected output in lower half of out_not
    assign out_not[2:0] = selected_output;

    // Output selected output to out_or_bitwise
    assign out_or_bitwise = selected_output;

    // Output or_logical to out_or_logical
    assign out_or_logical = or_logical;

    // Shift inverted input values and store new inverted input value
    always @(posedge clk) begin
        inverted_input_reg <= {inverted_input_reg[4:0], ~{a,b}};
    end

endmodule

module des_state(
    input se_clk,
    input se_rstn,
    input go_sup,
    input line_3d_actv_15,
    input ns1_eqz,
    input ns2_eqz,
    input co_linear,
    input det_eqz,
    input cull,
    output reg sup_done,
    output reg abort_cmd,
    output reg [5:0] se_cstate
);

    // Define states
    localparam [5:0]
        STATE_RESET = 6'b000000,
        STATE_GO_SUP = 6'b000001,
        STATE_COLIN = 6'b000010,
        STATE_NL1_NL2 = 6'b000011,
        STATE_NO_AREA = 6'b000100,
        STATE_SETUP_END = 6'b000101;

    // Define state machine outputs
    reg go_sup_1, go_sup_2;

    // Define state machine behavior
    always @(posedge se_clk or negedge se_rstn) begin
        if (!se_rstn) begin
            se_cstate <= STATE_RESET;
            sup_done <= 1'b0;
            abort_cmd <= 1'b0;
            go_sup_1 <= 1'b0;
            go_sup_2 <= 1'b0;
        end
        else begin
            go_sup_2 <= go_sup_1;
            go_sup_1 <= go_sup;
            abort_cmd <= 1'b0;

            case (se_cstate)
                STATE_RESET: begin
                    if (go_sup_2) se_cstate <= STATE_GO_SUP;
                    else se_cstate <= STATE_RESET;
                end
                STATE_GO_SUP: begin
                    if (co_linear && !line_3d_actv_15) begin
                        abort_cmd <= 1'b1;
                        se_cstate <= STATE_RESET;
                    end
                    else if (ns1_eqz && ns2_eqz && !line_3d_actv_15) begin
                        abort_cmd <= 1'b1;
                        se_cstate <= STATE_RESET;
                    end
                    else if ((cull || det_eqz) && !line_3d_actv_15) begin
                        abort_cmd <= 1'b1;
                        se_cstate <= STATE_RESET;
                    end
                    else if (se_cstate == STATE_SETUP_END) begin
                        se_cstate <= STATE_RESET;
                        sup_done <= 1'b1;
                    end
                    else se_cstate <= se_cstate + 6'b000001;
                end
                default: begin
                    se_cstate <= STATE_RESET;
                end
            endcase
        end
    end

endmodule

