module shift_register (
  input data_in,
  input shift,
  input reset,
  output reg [n-1:0] data_out
);

parameter n = 8; // number of bits in the shift register

reg [n-1:0] shift_reg;

always @ (posedge shift) begin
  if (reset) begin
    shift_reg <= 0;
  end else begin
    casez({shift, shift_reg})
      2'b01: shift_reg <= {shift_reg[n-2:0], data_in};
      2'b10: shift_reg <= data_in;
      2'b11: shift_reg <= {shift_reg[n-2:0], 1'b0};
      2'b00: shift_reg <= {1'b0, shift_reg[n-1:1]};
    endcase
  end
end

assign data_out = shift_reg;

endmodule

