module edge_detector (
    input clk,
    input [7:0] in,
    output [7:0] anyedge
);

reg [7:0] current_state;
reg [7:0] previous_state;
wire [7:0] xor_output;
wire [7:0] and_output;

// Store the current state of each input bit
always @(posedge clk) begin
    current_state <= in;
end

// Store the previous state of each input bit
always @(posedge clk) begin
    previous_state <= current_state;
end

// Compare the current state with the previous state to detect rising edges
assign xor_output = current_state ^ previous_state;

// Set the output bit to 1 in the cycle following a rising edge
assign and_output = xor_output & (current_state ^ 8'b11111111);

// Output the anyedge signal
assign anyedge = and_output;

endmodule

module adder(clk, rst, a, b, cin, sum, cout);

  parameter WIDTH = 16;

  input clk, rst;
  input [WIDTH-1:0] a, b;
  input cin;
  output [WIDTH-1:0] sum;
  output cout;

  // Internal wires
  wire [WIDTH:0] carry;
  wire [WIDTH-1:0] carry_in, carry_out;

  // Full Adder
  genvar i;
  generate
    for (i = 0; i < WIDTH; i = i + 1) begin : fa
      full_adder fa(
        .a(a[i]), .b(b[i]), .cin(carry_in[i]),
        .sum(sum[i]), .cout(carry_out[i])
      );
    end
  endgenerate

  // Connect carry chain
  assign carry[0] = cin;
  assign carry[1:WIDTH] = carry_out;

  // Connect carry to carry_in of next full adder
  assign carry_in = carry[0:WIDTH-1];

  // Reset logic
  always @(posedge clk) begin
    if (rst) begin
      sum <= 0;
      cout <= 0;
    end else begin
      sum <= carry_out[0:WIDTH-1];
      cout <= carry_out[WIDTH];
    end
  end

endmodule

