module S4(clk, x, y, z);
    input clk;
    input [15:0] x, y;
    output [31:0] z;

    reg [31:0] a, b, c, d;

    always @ (posedge clk) begin
        a = (x * y) % (2 ** 16);
        b = (x * (y >> 16)) % (2 ** 16);
        c = ((x >> 16) * y) % (2 ** 16);
        d = ((x >> 16) * (y >> 16)) % (2 ** 16);
        z = ((a + d) % (2 ** 16)) << 16 | (b << 1) | c;
    end
endmodule

