  begin
    if(~aresetn)
    begin
      int_cntr_reg <= {(CNTR_WIDTH){1'b0}};
      int_enbl_reg <= 1'b0;
    end
    else
    begin
      int_cntr_reg <= int_cntr_next;
      int_enbl_reg <= int_enbl_next;
    end
  end

  assign int_comp_wire = run_flag & (int_cntr_reg < cfg_data);

  always @*
  begin
    int_cntr_next = int_cntr_reg;
    int_enbl_next = int_enbl_reg;

    if(~int_enbl_reg & int_comp_wire & s_axis_tvalid)
    begin
      int_enbl_next = 1'b1;
    end

    if(int_enbl_reg & int_comp_wire & s_axis_tvalid)
    begin
      int_cntr_next = int_cntr_reg + 1'b1;
    end

    if(int_enbl_reg & ~int_comp_wire & s_axis_tvalid)
    begin
      int_enbl_next = 1'b0;
    end
  end

  assign trg_flag = int_enbl_reg;
  assign sts_data = int_cntr_reg;

  assign s_axis_tready = 1'b1;

endmodule

module stack
#(
  parameter WIDTH = 8,
  parameter DEPTH = 1
)
(
  input clk,
  input reset,
  input [1:0] op,
  input [WIDTH-1:0] data,
  output reg [WIDTH-1:0] tos,
  output reg [1:0] status,
  output reg [1:0] error
);

localparam MAX_STACK = (1 << DEPTH+1) - 1;
reg [WIDTH-1:0] mem [0:MAX_STACK-1];
reg [DEPTH:0] ptr;

always @(posedge clk) begin
  if (reset) begin
    ptr <= 0;
    tos <= 0;
    status <= 2'b10;
    error <= 2'b00;
  end else begin
    case (op)
      2'b00: begin // NONE
        // Do nothing
      end
      2'b01: begin // PUSH
        if (ptr == MAX_STACK) begin
          error <= 2'b01;
        end else begin
          mem[ptr] <= data;
          ptr <= ptr + 1;
          tos <= data;
          if (ptr == MAX_STACK) begin
            status <= 2'b01;
          end else begin
            status <= 2'b00;
          end
          error <= 2'b00;
        end
      end
      2'b10: begin // POP
        if (ptr == 0) begin
          error <= 2'b01;
        end else begin
          ptr <= ptr - 1;
          if (ptr == 0) begin
            status <= 2'b10;
          end else begin
            status <= 2'b00;
          end
          tos <= mem[ptr];
          error <= 2'b00;
        end
      end
      2'b11: begin // REPLACE
        if (ptr == 0) begin
          error <= 2'b01;
        end else begin
          mem[ptr-1] <= data;
          tos <= data;
          error <= 2'b00;
        end
      end
    endcase
  end
end

endmodule

module key_gen(
    clk,
    reset,
    p2k_valid,
    p2k_ingress,
    p2k_rloc_src,
    p2k_eid_dst,
    p2k_metadata,
    mode,
    k2m_metadata_valid,
    k2m_metadata
);

input clk;
input reset;
input p2k_valid;
input [7:0] p2k_ingress;
input [127:0] p2k_rloc_src;
input [127:0] p2k_eid_dst;
input [7:0] p2k_metadata;
input mode;
output k2m_metadata_valid;
output [107:0] k2m_metadata;

reg k2m_metadata_valid;
reg [107:0] k2m_metadata;

always @ (posedge clk or negedge reset) begin
    if (!reset) begin
        k2m_metadata_valid <= 1'b0;
        k2m_metadata <= 108'b0;
    end
    else begin
        if (p2k_valid == 1'b1) begin
            if (mode == 1'b1) begin
                if (p2k_ingress == 8'b0) begin
                    k2m_metadata <= {mode, p2k_ingress, p2k_rloc_src[17:0], 81'b0};
                end
                else begin
                    k2m_metadata <= {mode, p2k_ingress, 18'b0, 81'b0};
                end
                k2m_metadata_valid <= 1'b1;
            end
            else begin
                k2m_metadata_valid <= 1'b1;
                k2m_metadata <= {mode, p2k_ingress, p2k_eid_dst[127:56], 56'b0};
            end
        end
        else begin
            k2m_metadata_valid <= 1'b0;
        end
    end
end

endmodule

module bin2bcd(
  input [3:0] bin_in,
  input clk,
  output reg [3:0] bcd_out1,
  output reg [3:0] bcd_out2
);

  reg [3:0] bcd[1:2];
  integer i;

  always @(posedge clk) begin
    // Convert binary to BCD
    for (i = 1; i <= 2; i = i + 1) begin
      bcd[i] = 0;
    end

    for (i = 0; i <= 3; i = i + 1) begin
      if (bin_in[i] >= 5) begin
        bcd[1][i] = 1;
        bcd[2][i] = bin_in[i] - 5;
      end else begin
        bcd[2][i] = bin_in[i];
      end
    end

    // Output BCD digits
    bcd_out1 <= bcd[1];
    bcd_out2 <= bcd[2];
  end

endmodule

module ABS (
  input signed [31:0] in,
  output reg [31:0] out
);

  // Check the sign bit of the input number
  wire signed [31:0] sign_bit = in[31];

  // If the sign bit is 1, then the input number is negative
  wire signed [31:0] negated = ~in + 1;

  // If the input number is negative, negate the number by taking the two's complement of the number
  always @(*) begin
    if (sign_bit == 1) begin
      out = negated;
    end else begin
      out = in;
    end
  end

endmodule

