module full_adder (
  sum,
  carry_out,
  a,
  b,
  carry_in
);
  output sum;
  output carry_out;
  input a;
  input b;
  input carry_in;
  wire s1;
  wire c1;
  wire c2;
  xor (s1, a, b);
  and (c1, a, b);
  xor (sum, s1, carry_in);
  and (c2, s1, carry_in);
  or (carry_out, c1, c2);
endmodule

