  full_adder f2 (s1[1], c1[1], A[1], B[1], c1[0]);
  full_adder f3 (s1[2], c1[2], A[2], B[2], c1[1]);
  full_adder f4 (s1[3], carry_out, A[3], B[3], c1[2]);
