module xor_rot_add (
  input clk,
  input load,
  input [15:0] a,
  input [15:0] b,
  input [15:0] c,
  input [1:0] ena,
  output reg [15:0] q
);

  reg [15:0] xor_out;
  reg [49:0] rot_out;
  reg [15:0] add_out;

  // XOR operation
  always @ (a, b)
    xor_out = a ^ b;

  // Rotation operation
  always @ (posedge clk)
  begin
    if (load)
      rot_out = {xor_out, {50{1'b0}}};
    else if (ena == 2'b00)
      rot_out = rot_out;
    else if (ena == 2'b01)
      rot_out = {rot_out[48:0], rot_out[49]};
    else if (ena == 2'b10)
      rot_out = {rot_out[1:49], rot_out[0]};
    else
      rot_out = rot_out;
  end

  // Addition operation
  adder adder_inst (
    .a(rot_out[49:34]),
    .b(c),
    .sum(add_out)
  );

  // Output
  always @ (add_out)
    q = add_out;

endmodule

