    wire [31:0] carry_in;
    wire [31:0] carry_out;
    wire [31:0] carry_save_out;
    wire [31:0] final_out;

    ripple_carry_adder rca_inst (
        .a(a),
        .b(b),
        .cin(carry_in),
        .sum(adder_out),
        .cout(carry_out)
    );

    xor_gate xor_inst (
        .a(b),
