        .out(carry_in)
    );

    carry_save_adder csa_inst (
        .a(a),
        .b(b),
        .c(carry_in),
        .sum(carry_save_out),
        .carry(carry_out)
    );

    assign subtractor_out = ~carry_save_out;

    functional_module fm_inst (
        .adder_out(adder_out),
        .subtractor_out(subtractor_out),
        .sub(sub),
        .final_out(final_out)
    );

    assign sum = final_out;

