module carry_save_adder (
    input [31:0] a,
    input [31:0] b,
    input [31:0] c,
    output [31:0] sum,
    output [31:0] carry
);

    genvar i;
    generate
        for (i = 0; i < 32; i = i + 1) begin : csa_bit
            assign sum[i] = a[i] ^ b[i] ^ c[i];
            assign carry[i] = (a[i] & b[i]) | (b[i] & c[i]) | (c[i] & a[i]);
        end
    endgenerate

