module single_port_ram
#(parameter DATA_WIDTH=16, parameter ADDR_WIDTH=4)
(
   input [(DATA_WIDTH-1):0] data,
   input [(ADDR_WIDTH-1):0] addr,
   input we, clk,
   output reg [(DATA_WIDTH-1):0] q
);

   // Declare the RAM variable
   reg [DATA_WIDTH-1:0] ram[2**ADDR_WIDTH-1:0];

   // Variable to hold the registered read address
   reg [ADDR_WIDTH-1:0] addr_reg;

   // Specify the initial contents.  You can also use the $readmemb
   // system task to initialize the RAM variable from a text file.
   // See the $readmemb template page for details.
   initial 
   begin : INIT
      $readmemb("C:/altera/16.0/myProjects/PHYctrl_100Mbps_Slave_max10/ram_init0_and.txt", ram);
   end 

   always @ (posedge clk)
   begin
      // Write
      if (we)
         ram[addr] <= data;

      addr_reg <= addr;
   end

   // Continuous assignment implies read returns NEW data.
   // This is the natural behavior of the TriMatrix memory
   // blocks in Single Port mode.  
   assign q = ram[addr_reg];

endmodule

module calculator (
  input clk,
  input rst_n,
  input op,
  input signed [7:0] a,
  input signed [7:0] b,
  output reg signed [7:0] result,
  output reg overflow
);

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      result <= 0;
      overflow <= 0;
    end else begin
      if (op == 0) begin // addition
        result <= a + b;
        if (((a > 0) && (b > 0) && (result < 0)) || ((a < 0) && (b < 0) && (result > 0))) begin
          overflow <= 1;
        end else begin
          overflow <= 0;
        end
      end else begin // subtraction
        result <= a - b;
        if (((a > 0) && (b < 0) && (result < 0)) || ((a < 0) && (b > 0) && (result > 0))) begin
          overflow <= 1;
        end else begin
          overflow <= 0;
        end
      end
    end
  end

endmodule

module top_module (
    input clk,
    input reset,
    input write_en,
    input [7:0] write_addr,
    input [3:0] write_data,
    input read_en,
    input [7:0] read_addr,
    input [7:0] data_in,
    input [1:0] shift_direction,
    input load,
    output [7:0] data_out
);

reg [3:0] ram [0:7];
reg [7:0] shift_reg;
wire [3:0] read_data;

always @(posedge clk) begin
    if (write_en) begin
        ram[write_addr] <= write_data;
    end
end

assign read_data = (read_en) ? ram[read_addr] : 4'b0;

always @(negedge clk) begin
    if (reset) begin
        shift_reg <= 8'h34;
    end else if (load) begin
        shift_reg <= data_in;
    end else begin
        case (shift_direction)
            2'b00: shift_reg <= shift_reg;
            2'b01: shift_reg <= {shift_reg[6:0], 1'b0};
            2'b10: shift_reg <= {1'b0, shift_reg[7:1]};
            2'b11: shift_reg <= shift_reg;
        endcase
    end
end

assign data_out = read_data ^ shift_reg[3:0];

endmodule

