module top_module(
    input [15:0] a,
    input [15:0] b,
    input enable_mult,
    output reg [31:0] product
);

    wire [31:0] temp_product;
    wire [15:0] a_high, b_high, a_low, b_low;
    wire [31:0] adder_out1, adder_out2;

    // Split inputs into high and low 16-bit parts
    assign a_high = a[15:8];
    assign b_high = b[15:8];
    assign a_low = a[7:0];
    assign b_low = b[7:0];

    // Instantiate adder module twice
    adder adder1(.a(a_low), .b(b_low), .sum(adder_out1));
    adder adder2(.a(a_high), .b(b_high), .sum(adder_out2));

    // AND gate to perform multiplication operation
    assign temp_product = {16'b0, b} & {16'b0, a};

    // Control module to enable or disable multiplication operation
    always @(*) begin
        if(enable_mult) begin
            product <= adder_out1 + adder_out2 + temp_product;
        end else begin
            product <= a * b;
        end
    end

endmodule

