    input [2:0] select,// Select input to choose between 3-to-4 wire connection and functional module
    input a,b,c,       // Inputs for 3-to-4 wire connection
    output [3:0] q     // Final 4-bit digital clock
);

    wire [3:0] counter_output;
    wire [3:0] functional_output;

    decade_counter counter (
        .clk(clk),
        .reset(reset),
        .enable(slowena),
        .count(counter_output)
    );

    functional_module functional (
        .input_value(counter_output),
        .output_value(functional_output)
    );

    three_to_four_wire three_to_four (
        .a(a),
        .b(b),
        .c(c),
        .output_value(q)
    );

    always @(counter_output, functional_output, select) begin
        case (select)
            3'b000: q <= counter_output;
            3'b001: q <= functional_output;
            default: q <= counter_output;
        endcase
    end

