module hash_phase (
   input                      clk,
   input                      rst,
   output                     done,

   input    [63:0]            hash_mask_in,

   output                     afull_out,
   input                      write_en_in,
   input    [63:0]            value_in,

   output                     empty_out,
   input                      read_en_in,
   output   [63:0]            value_out,
   output   [63:0]            hash_out
);

   wire                       function_valid_out_s;
   wire  [63:0]               function_data_out_s;
   hash_function FUNCTION (
      .clk                    (clk),
      .rst                    (rst),
      .valid_in               (write_en_in),
      .data_in                ({32'd0, value_in[63:32]}),
      .valid_out              (function_valid_out_s),
      .data_out               (function_data_out_s)
   );

   wire  [1:0]                fifo_afull_s;
   wire                       fifo_empty_s;
   wire  [63:0]               hash_fifo_data_out_s;

   sync_2_fifo FIFO ( 
      .clk                    (clk),
      .rst                    (rst),
      .afull_out              (fifo_afull_s),
      .write_en_in            ({write_en_in, function_valid_out_s}),
      .data_1_in              (value_in),
      .data_0_in              (function_data_out_s),
      .empty_out              (fifo_empty_s),
      .read_en_in             (read_en_in),
      .data_1_out             (value_out),
      .data_0_out             (hash_fifo_data_out_s)
   );

   assign hash_out   = hash_fifo_data_out_s & hash_mask_in;

   assign afull_out  = (fifo_afull_s != 2'd0);
   assign empty_out  = fifo_empty_s;
   assign done       = fifo_empty_s;

endmodule

module hash_function (
   input                      clk,
   input                      rst,
   input                      valid_in,
   input    [31:0]            data_in,
   output                     valid_out,
   output  [63:0]            data_out
);

   reg                        valid_out_r;
   reg  [63:0]               data_out_r;

   always @(posedge clk) begin
      if (rst) begin
         valid_out_r <= 1'b0;
         data_out_r  <= 64'd0;
      end
      else if (valid_in) begin
         valid_out_r <= 1'b1;
         data_out_r  <= $random;
      end
      else begin
         valid_out_r <= 1'b0;
         data_out_r  <= 64'd0;
      end
   end

   assign valid_out = valid_out_r;
   assign data_out  = data_out_r;

endmodule

module sync_2_fifo (
   input                      clk,
   input                      rst,
   output  [1:0]             afull_out,
   input   [1:0]             write_en_in,
   input    [63:0]           data_1_in,
   input    [63:0]           data_0_in,
   output                     empty_out,
   input                      read_en_in,
   output  [63:0]            data_1_out,
   output  [63:0]            data_0_out
);

   reg  [1:0]                afull_out_r;
   reg                       empty_out_r;
   reg  [63:0]               data_1_out_r;
   reg  [63:0]               data_0_out_r;
   reg  [63:0]               fifo_data [1:0];
   reg  [1:0]                fifo_ptr;

   always @(posedge clk) begin
      if (rst) begin
         afull_out_r   <= 2'd0;
         empty_out_r   <= 1'b1;
         data_1_out_r  <= 64'd0;
         data_0_out_r  <= 64'd0;
         fifo_data[1]  <= 64'd0;
         fifo_data[0]  <= 64'd0;
         fifo_ptr      <= 2'd0;
      end
      else begin
         if (write_en_in[0]) begin
            fifo_data[fifo_ptr[1]][63:0] <= data_0_in;
         end
         if (write_en_in[1]) begin
            fifo_data[fifo_ptr[0]][63:0] <= data_1_in;
         end
         if (read_en_in && ~empty_out_r) begin
            data_1_out_r <= fifo_data[fifo_ptr[1]][63:0];
            data_0_out_r <= fifo_data[fifo_ptr[0]][63:0];
            if (fifo_ptr == 2'd3) begin
               afull_out_r <= 2'd2;
            end
            else begin
               afull_out_r <= 2'd0;
            end
            empty_out_r <= 1'b0;
            fifo_ptr <= fifo_ptr + 1;
         end
         else if (~empty_out_r) begin
            afull_out_r <= 2'd1;
         end
         if (fifo_ptr == 2'd2) begin
            empty_out_r <= 1'b0;
         end
         else begin
            empty_out_r <= 1'b1;
         end
      end
   end

   assign afull_out = afull_out_r;
   assign empty_out = empty_out_r;
   assign data_1_out = data_1_out_r;
   assign data_0_out = data_0_out_r;

endmodule

module shift_register(
    input clk,
    input rst,
    input shift_dir,
    input parallel_load,
    input [3:0] parallel_input,
    input serial_input,
    input clear_input,
    output serial_output,
    output [3:0] parallel_output
);

    reg [3:0] reg_value;
    wire [3:0] reg_value_shifted;
    wire [3:0] reg_value_loaded;
    wire [3:0] reg_value_cleared;

    // Shift the register left or right based on the shift_dir input
    assign reg_value_shifted = shift_dir ? {reg_value[2:0], 1'b0} : {1'b0, reg_value[3:1]};

    // Load the register with the parallel_input value when parallel_load is asserted
    assign reg_value_loaded = parallel_load ? parallel_input : reg_value_shifted;

    // Clear the register to all zeros when clear_input is asserted
    assign reg_value_cleared = clear_input ? 4'h0 : reg_value_loaded;

    // Output the serial_output value as the MSB of the register
    assign serial_output = reg_value[3];

    // Output the parallel_output value as the entire register
    assign parallel_output = reg_value;

    // Register the value of the shift register on the positive edge of the clock
    always @(posedge clk) begin
        if (rst) begin
            reg_value <= 4'h0;
        end else begin
            reg_value <= reg_value_cleared;
        end
    end

endmodule

module binary_counter(clk, reset, count, overflow);
  input clk, reset;
  output reg [3:0] count;
  output reg overflow;

  always @(posedge clk) begin
    if (reset) begin
      count <= 4'b0000;
      overflow <= 1'b0;
    end
    else if (count == 4'b1111) begin
      count <= 4'b0000;
      overflow <= 1'b1;
    end
    else begin
      count <= count + 1;
      overflow <= 1'b0;
    end
  end
endmodule

