    wire [7:0] and_out;
    wire [7:0] rising_edge_out;
    wire [7:0] xor_out;

    dual_edge_ff ff1 (.clk(clk), .reset(reset), .d(in[0]), .q(shift_reg_out[0]));
    dual_edge_ff ff2 (.clk(clk), .reset(reset), .d(shift_reg_out[0]), .q(shift_reg_out[1]));
    dual_edge_ff ff3 (.clk(clk), .reset(reset), .d(shift_reg_out[1]), .q(shift_reg_out[2]));
    dual_edge_ff ff4 (.clk(clk), .reset(reset), .d(shift_reg_out[2]), .q(shift_reg_out[3]));
    dual_edge_ff ff5 (.clk(clk), .reset(reset), .d(shift_reg_out[3]), .q(shift_reg_out[4]));
    dual_edge_ff ff6 (.clk(clk), .reset(reset), .d(shift_reg_out[4]), .q(shift_reg_out[5]));
    dual_edge_ff ff7 (.clk(clk), .reset(reset), .d(shift_reg_out[5]), .q(shift_reg_out[6]));
    dual_edge_ff ff8 (.clk(clk), .reset(reset), .d(shift_reg_out[6]), .q(shift_reg_out[7]));

    rising_edge_detector red (.clk(clk), .reset(reset), .in(shift_reg_out), .out(rising_edge_out));

    and_functional and_func (.in1(shift_reg_out), .in2(in), .out(and_out));

    assign xor_out = rising_edge_out ^ and_out;

    assign out = (select == 2'b00) ? shift_reg_out :
                 (select == 2'b01) ? and_out :
