module Forward(
input [1:0]RegDst,
input[4:0] Rt_From_ID_EX,
input[4:0] Rs_From_ID_EX,
input[4:0] Rd_From_EX_MEM,
input[3:0] RegWrite_From_EX_MEM,
input[4:0] Rd_From_MEM_WB,
input[3:0] RegWrite_From_MEM_WB,
input[4:0] Rt_From_IF_ID,
input[4:0] Rs_From_IF_ID,
input[1:0] RegRead,
output [1:0] Rs_EX_Forward,
output [1:0] Rt_EX_Forward,
output Rs_LoudUse_Forward,
output Rt_LoudUse_Forward
);

// Check if forwarding is needed for Rs in the EX stage
assign Rs_EX_Forward = ((RegDst[1] === 1'b1) && (Rs_From_ID_EX === Rd_From_EX_MEM) && (RegWrite_From_EX_MEM !== 4'b0000)) ? 2'b01 : ((RegDst[1] === 1'b1) && (Rs_From_ID_EX === Rd_From_MEM_WB) && (RegWrite_From_MEM_WB !== 4'b0000)) ? 2'b10 : 2'b00;

// Check if forwarding is needed for Rt in the EX stage
assign Rt_EX_Forward = ((RegDst[0] === 1'b1) && (Rt_From_ID_EX === Rd_From_EX_MEM) && (RegWrite_From_EX_MEM !== 4'b0000)) ? 2'b01 : ((RegDst[0] === 1'b1) && (Rt_From_ID_EX === Rd_From_MEM_WB) && (RegWrite_From_MEM_WB !== 4'b0000)) ? 2'b10 : 2'b00;

// Check if forwarding is needed for Rs in the IF stage
assign Rs_LoudUse_Forward = (RegRead[0] & (Rs_From_IF_ID === Rd_From_MEM_WB) && (RegWrite_From_MEM_WB !== 4'b0000)) ? 1'b1 : 1'b0;

// Check if forwarding is needed for Rt in the IF stage
assign Rt_LoudUse_Forward = (RegRead[1] & (Rt_From_IF_ID === Rd_From_MEM_WB) && (RegWrite_From_MEM_WB !== 4'b0000)) ? 1'b1 : 1'b0;

endmodule

