module modExp(
    input clk,
    input reset,
    input start,
    input [63:0] exponent,
    input [63:0] number,
    input [7:0] logNum,
    output [63:0] result,
    output isDone
);

    reg [63:0] base;
    reg [63:0] exp;
    reg [63:0] mod;
    reg [63:0] temp;
    reg [7:0] i;
    wire [63:0] one;
    assign one = 1;
    reg [63:0] result_reg;
    wire [63:0] result_wire;
    assign result = result_wire;
    reg done;

    // Initialize inputs
    always @(posedge clk) begin
        if (reset) begin
            base <= 0;
            exp <= 0;
            mod <= 0;
            temp <= 0;
            i <= 0;
            result_reg <= 0;
            done <= 0;
        end else begin
            if (start) begin
                base <= number;
                exp <= exponent;
                mod <= (one << logNum) - one;
                temp <= 1;
                i <= 0;
                result_reg <= 0;
                done <= 0;
            end else if (!done) begin
                if (exp[i]) begin
                    temp <= (temp * base) % mod;
                end
                base <= (base * base) % mod;
                i <= i + 1;
                if (i == 63) begin
                    result_reg <= temp;
                    done <= 1;
                end
            end
        end
    end

    // Output result when done
    always @(posedge clk) begin
        if (reset) begin
            result_wire <= 0;
        end else begin
            if (done) begin
                result_wire <= result_reg;
            end else begin
                result_wire <= 0;
            end
        end
    end

    // Output isDone when done
    always @(posedge clk) begin
        if (reset) begin
            isDone <= 0;
        end else begin
            if (done) begin
                isDone <= 1;
            end else begin
                isDone <= 0;
            end
        end
    end

endmodule

