module Counter(
  input Reset_n_i,
  input Clk_i,
  input ResetSig_i,
  input Preset_i,
  input Enable_i,
  input Direction_i,
  input [15:0] PresetVal_i,
  output reg [15:0] D_o,
  output reg Overflow_o,
  output reg Zero_o
);

  reg [15:0] count;

  always @(posedge Clk_i) begin
    if (!Reset_n_i) begin
      count <= 16'd0;
      Overflow_o <= 1'b0;
      Zero_o <= 1'b1;
    end
    else if (ResetSig_i) begin
      count <= 16'd0;
      Overflow_o <= 1'b0;
      Zero_o <= 1'b1;
    end
    else if (Preset_i) begin
      count <= PresetVal_i;
      Overflow_o <= (Direction_i && (PresetVal_i == 16'hFFFF)) || (!Direction_i && (PresetVal_i == 16'h0000));
      Zero_o <= (PresetVal_i == 16'h0000);
    end
    else if (Enable_i) begin
      if (Direction_i) begin
        if (count == 16'hFFFF) begin
          count <= 16'h0000;
          Overflow_o <= 1'b1;
          Zero_o <= 1'b0;
        end
        else begin
          count <= count + 1;
          Overflow_o <= 1'b0;
          Zero_o <= (count == 16'h0000);
        end
      end
      else begin
        if (count == 16'h0000) begin
          count <= 16'hFFFF;
          Overflow_o <= 1'b0;
          Zero_o <= 1'b1;
        end
        else begin
          count <= count - 1;
          Overflow_o <= (count == 16'hFFFF);
          Zero_o <= 1'b0;
        end
      end
    end
    D_o <= count;
  end

endmodule

module delay_gate (
    input in,
    input rst,
    input en,
    output out
);

    reg [3:0] delay_reg;
    wire [3:0] next_delay_reg;

    always @(posedge clk) begin
        if (rst) begin
            delay_reg <= 4'b0000;
        end else if (en) begin
            delay_reg <= next_delay_reg;
        end
    end

    assign next_delay_reg[0] = in;
    assign next_delay_reg[1] = delay_reg[0];
    assign next_delay_reg[2] = delay_reg[1];
    assign next_delay_reg[3] = delay_reg[2];

    assign out = delay_reg[3];

endmodule

module register_module (
    input wire [31:0] interface_from_core_fp,
    input wire mb_reg_rwn,
    input wire [15:0] mb_reg_select,
    output reg [31:0] mb_reg_output
);

    parameter NUMBER_INTERFACE_REGS = 16;
    parameter MB_REG_START = 3;
    parameter CMD_REG_0_ADDR = MB_REG_START;
    parameter CMD_REG_1_ADDR = MB_REG_START+1;
    parameter CMD_REG_2_ADDR = MB_REG_START+2;
    parameter CMD_REG_3_ADDR = MB_REG_START+3;
    parameter CMD_REG_4_ADDR = MB_REG_START+4;
    parameter CMD_REG_5_ADDR = MB_REG_START+5;
    parameter CMD_REG_6_ADDR = MB_REG_START+6;
    parameter CMD_REG_7_ADDR = MB_REG_START+7;
    parameter CMD_REG_8_ADDR = MB_REG_START+8;
    parameter CMD_REG_9_ADDR = MB_REG_START+9;
    parameter CMD_REG_10_ADDR = MB_REG_START+10;
    parameter MODE_REG_0_ADDR = CMD_REG_8_ADDR;
    parameter CMD_REG_14_ADDR = 14;
    parameter CRC_ERROR_REG_ADDR = CMD_REG_14_ADDR;
    parameter VERSION_REG_ADDR = 15;

    reg [NUMBER_INTERFACE_REGS-1:MB_REG_START] mb_reg_wr;
    reg [NUMBER_INTERFACE_REGS-1:MB_REG_START] mb_reg_rd;
    wire [31:0] mb_reg_out_w [NUMBER_INTERFACE_REGS-1:MB_REG_START];

    assign mb_reg_out_w[VERSION_REG_ADDR] = BUILD_VERSION;

    integer mb_loop;
    always @(interface_from_core_fp or mb_reg_rwn or mb_reg_select)
    begin
        mb_reg_wr = 'h0;
        mb_reg_rd = 'h0;
        mb_reg_output = interface_from_core_fp;

        for (mb_loop = MB_REG_START; mb_loop < NUMBER_INTERFACE_REGS; mb_loop = mb_loop + 1)
        begin
            if (mb_reg_select[mb_loop] == 1'b1)
            begin
                mb_reg_rd[mb_loop] = mb_reg_select[mb_loop] & mb_reg_rwn;
                mb_reg_wr[mb_loop] = mb_reg_select[mb_loop] & !mb_reg_rwn;
                if (mb_reg_rwn)
                begin
                    mb_reg_out_w[mb_loop] = interface_from_core_fp;
                end
                else
                begin
                    mb_reg_output = mb_reg_out_w[mb_loop];
                end
            end
        end
    end

endmodule

module sirv_gnrl_cdc_tx
# (
  parameter DW = 32,
  parameter SYNC_DP = 2
) (
  // The regular handshake interface at in-side
  //         Just the regular handshake o_vld & o_rdy like AXI
  input  i_vld, 
  output i_rdy, 
  input  [DW-1:0] i_dat,

  // The 4-phases handshake interface at out-side
  //     There are 4 steps required for a full transaction. 
  //         (1) The i_vld is asserted high 
  //         (2) The i_rdy is asserted high
  //         (3) The i_vld is asserted low 
  //         (4) The i_rdy is asserted low
  output o_vld, 
  input  o_rdy_a, 
  output [DW-1:0] o_dat,

  input  clk,
  input  rst_n 
);

wire o_rdy_sync;

// Sync the async signal first
sirv_gnrl_sync #(
    .DP(SYNC_DP), 
    .DW(1)
) u_o_rdy_sync (
         .clk   (clk),
         .rst_n (rst_n),
         .din_a (o_rdy_a),
         .dout  (o_rdy_sync)
        );

wire vld_r;
wire [DW-1:0] dat_r;

// Valid set when it is handshaked
wire vld_set = i_vld & i_rdy;
// Valid clr when the TX o_rdy is high
wire vld_clr = o_vld & o_rdy_sync;
wire vld_ena = vld_set | vld_clr;
wire vld_nxt = vld_set | (~vld_clr);
sirv_gnrl_dfflr #(1) vld_dfflr(vld_ena, vld_nxt, vld_r, clk, rst_n);
// The data buf is only loaded when the vld is set 
sirv_gnrl_dfflr #(DW) dat_dfflr(vld_set, i_dat, dat_r, clk, rst_n);

// Detect the neg-edge
wire o_rdy_sync_r;
sirv_gnrl_dffr #(1) o_rdy_sync_dffr(o_rdy_sync, o_rdy_sync_r, clk, rst_n);
wire o_rdy_nedge = (~o_rdy_sync) & o_rdy_sync_r;

// Not-ready indication
wire nrdy_r;
// Not-ready is set when the vld_r is set
wire nrdy_set = vld_set;
// Not-ready is clr when the o_rdy neg-edge is detected
wire nrdy_clr = o_rdy_nedge;
wire nrdy_ena = nrdy_set | nrdy_clr;
wire nrdy_nxt = nrdy_set | (~nrdy_clr);
sirv_gnrl_dfflr #(1) buf_nrdy_dfflr(nrdy_ena, nrdy_nxt, nrdy_r, clk, rst_n);

//  The output valid
assign o_vld = vld_r;
//  The output data
assign o_dat = dat_r;

// The input is ready when the  Not-ready indication is low or under clearing
assign i_rdy = (~nrdy_r) | nrdy_clr;

endmodule

