module top_module (
    input a,
    input b,
    input sel_b1,
    input sel_b2,
    input [7:0] in,
    output reg [3:0] final_output
);

    // 2-to-1 multiplexer
    always @(*)
    begin
        case({sel_b2, sel_b1})
            2'b00: final_output[1:0] = a;
            2'b01: final_output[1:0] = a;
            2'b10: final_output[1:0] = b;
            2'b11: final_output[1:0] = b;
        endcase
    end

    // Priority encoder
    always @(*)
    begin
        if (in[0] == 1) final_output[3:2] = 2'b00;
        else if (in[1] == 1) final_output[3:2] = 2'b01;
        else if (in[2] == 1) final_output[3:2] = 2'b10;
        else if (in[3] == 1) final_output[3:2] = 2'b11;
        else if (in[4] == 1) final_output[3:2] = 2'b100;
        else if (in[5] == 1) final_output[3:2] = 2'b101;
        else if (in[6] == 1) final_output[3:2] = 2'b110;
        else if (in[7] == 1) final_output[3:2] = 2'b111;
        else final_output[3:2] = 2'b00;
    end

endmodule

module barrel_shifter (
  input [n-1:0] data,
  input [m-1:0] shift_amount,
  input direction,
  output [n-1:0] shifted_data
);

  reg [n-1:0] shifted_data_reg;
  reg direction_reg;
  reg [m-1:0] shift_amount_reg;

  always @(*) begin
    direction_reg = direction;
    shift_amount_reg = shift_amount;

    if (shift_amount_reg >= n) begin
      shifted_data_reg = 0;
    end else if (direction_reg == 1) begin
      shifted_data_reg = {data[shift_amount_reg-1:0], {shift_amount_reg{1'b0}}};
    end else begin
      shifted_data_reg = {{shift_amount_reg{1'b0}}, data[n-shift_amount_reg-1:0]};
    end
  end

  assign shifted_data = shifted_data_reg;

endmodule

module spi_ctl(
    input            nss,
                     mosi,
                     sck,
    output           miso,
    output reg [6:0] address_bus,
    inout      [7:0] data_bus,
    output reg       read_n,
    output reg       write_n);

    // sample count
    reg [8:0] count;

	reg mosi_sample;

    // drive the data bus for a write, high Z otherwise
    reg [7:0] write_data_bus;
    assign data_bus = (~(write_n | ~read_n)) ? write_data_bus : 8'bz;

	// read register and next read register
	reg [7:0] r_reg;
	wire [7:0] r_next;

	// r_next is the next PROPAGATE value
	assign r_next = {r_reg[6:0], mosi_sample};
    assign miso = r_reg[7];

    // This tedious code is much easier to understand
    // along with timing digrams given in the documentation (doc/).
    // Look for the section titled "Timing diagram of SPI"
    // There are two diagrams, one for the read cycle and one
    // for the write cycle.  This code implements both of these.

    // This acts as a "one shot" used to indicate the start of a transaction
    reg start;
    always @(negedge nss, posedge sck) begin
        if (sck)
            start <= 1'b0;
        else
            start <= 1'b1;
    end

    // SAMPLE
    always @(posedge sck, posedge nss) begin
        // defaults
        count <= 1;

        if (nss) begin
            // end of second byte
            read_n <= 1'b1; // disable
        end else begin
            // SAMPLE
            mosi_sample <= mosi;

            if (start) begin
                count  <= 1;
                read_n <= 1'b1; // disable
            end else begin
                count       <= count + 1;
            end

            if (7 == count) begin
                // end of first byte

                // we got the 7-bit address and rw bit
                address_bus <= {r_reg[5:0], mosi};

                // if (READ)
                if (r_reg[6] == 1'b1)
                    read_n <= 1'b0; // enable
            end else if (15 == count && read_n == 1'b1) begin
                // (WRITE), got the second byte, setup to write it to the bus
                write_data_bus <= {r_reg[6:0], mosi};
                // can't use r_next here because we need mosi
            end
        end
    end

    // PROPAGATE
    always @(negedge sck, posedge nss) begin
        // defaults
        r_reg <= 8'h00;

        if (nss) begin
            // end of second byte

            write_n <= 1'b1; // disable
        end else begin
            r_reg <= r_next;

            if (1 == count) begin
                write_n <= 1'b1; // disable
            end else if (8 == count) begin
                // if (READ), load the data to be sent back
                if (1'b0 == read_n)
                    r_reg <= data_bus;
            end else if (16 == count) begin
                // end of second byte

                // if (WRITE), enable write.
                //  (the enabled device will drive the bus)
                if (read_n == 1'b1)
                    write_n <= 1'b0; // enable
            end
        end
    end

endmodule

