module servo_control (
  input pwm_in,
  input ref_in,
  output ctrl_out
);

parameter min_pulse_width = 100; // minimum pulse width in microseconds
parameter max_pulse_width = 200; // maximum pulse width in microseconds
parameter min_angle = 0; // minimum angle in degrees
parameter max_angle = 180; // maximum angle in degrees

reg [7:0] pwm_width;
reg [7:0] angle;
reg [7:0] error;
reg [7:0] ctrl_signal;

always @ (posedge pwm_in) begin
  pwm_width <= $width(pwm_in);
  angle <= ((pwm_width - min_pulse_width) * (max_angle - min_angle)) / (max_pulse_width - min_pulse_width) + min_angle;
  error <= ref_in - angle;
  ctrl_signal <= error;
end

assign ctrl_out = ctrl_signal;

endmodule

