module data_ram(
  input wire clk,
  input wire ce,
  input wire we,
  input wire[7:0] addr,
  input wire[3:0] sel,
  input wire[31:0] data_i,
  output reg[31:0] data_o,
  output wire[31:0] check
);

  reg [7:0] data_mem0[0:255];
  reg [7:0] data_mem1[0:255];
  reg [7:0] data_mem2[0:255];
  reg [7:0] data_mem3[0:255];

  always @(posedge clk) begin
    if (ce == 1'b0) begin
      data_o <= 32'b0;
    end else if (we == 1'b1) begin
      if (sel[3] == 1'b1) begin
        data_mem3[addr] <= data_i[31:24];
      end
      if (sel[2] == 1'b1) begin
        data_mem2[addr] <= data_i[23:16];
      end
      if (sel[1] == 1'b1) begin
        data_mem1[addr] <= data_i[15:8];
      end
      if (sel[0] == 1'b1) begin
        data_mem0[addr] <= data_i[7:0];
      end
    end
  end

  always @(*) begin
    if (ce == 1'b0) begin
      data_o <= 32'b0;
    end else if (we == 1'b0) begin
      if (sel[3] == 1'b1) begin
        data_o[31:24] <= data_mem3[addr];
      end
      if (sel[2] == 1'b1) begin
        data_o[23:16] <= data_mem2[addr];
      end
      if (sel[1] == 1'b1) begin
        data_o[15:8] <= data_mem1[addr];
      end
      if (sel[0] == 1'b1) begin
        data_o[7:0] <= data_mem0[addr];
      end
    end
  end

  assign check = {data_mem3[0], data_mem2[0], data_mem1[0], data_mem0[0]};
endmodule

module memArray2048_46095(
  input clk, reset, next, inFlip, outFlip,
  input [23:0] x0, x1,
  output [23:0] y0, y1,
  input [9:0] inAddr0, inAddr1, outAddr0, outAddr1
);

  parameter numBanks = 2;
  parameter logBanks = 1;
  parameter depth = 1024;
  parameter logDepth = 10;
  parameter width = 24;

  wire next0;
  nextReg #(depth, logDepth) nextReg0(.X(next), .Y(next0), .reset(reset), .clk(clk));

  wire [1:0] bank0, bank1;
  assign bank0 = inAddr0[logDepth] ^ inFlip;
  assign bank1 = inAddr1[logDepth] ^ inFlip;

  wire [logDepth-1:0] addr0, addr1;
  assign addr0 = inAddr0[logDepth-1:0];
  assign addr1 = inAddr1[logDepth-1:0];

  wire [23:0] data0, data1;
  memMod #(depth, width, logDepth) mem0(.in(x0), .out(data0), .inAddr(addr0), .outAddr(outAddr0), .writeSel(next0 & bank0), .clk(clk));
  memMod #(depth, width, logDepth) mem1(.in(x1), .out(data1), .inAddr(addr1), .outAddr(outAddr1), .writeSel(next0 & bank1), .clk(clk));

  assign y0 = outFlip ? data1 : data0;
  assign y1 = outFlip ? data0 : data1;

