module top_module (
    input clk,
    input reset,     // Synchronous active-high reset
    input [3:0] A,   // 4-bit input A for the adder/subtractor
    input [3:0] B,   // 4-bit input B for the adder/subtractor
    input C,         // Control input for the adder/subtractor
    input select,    // Select input to choose between ring counter and adder/subtractor
    output [3:0] Q   // 4-bit output from the active module
);

reg [3:0] counter_output;
reg [3:0] add_sub_output;
reg [3:0] output_sum;

ring_counter counter (
    .clk(clk),
    .reset(reset),
    .bit_0(counter_output[0]),
    .bit_1(counter_output[1]),
    .bit_2(counter_output[2]),
    .bit_3(counter_output[3])
);

add_sub adder_subtractor (
    .A(A),
    .B(B),
    .C(C),
    .Q(add_sub_output)
);

always @ (posedge clk) begin
    if (reset) begin
        counter_output <= 4'b0000;
        add_sub_output <= 4'b0000;
        output_sum <= 4'b0000;
    end else begin
        if (select) begin
            counter_output <= {counter_output[2:0], counter_output[3]};
            output_sum <= counter_output + add_sub_output;
        end else begin
            output_sum <= add_sub_output;
        end
    end
end

functional_module func (
    .counter_output(counter_output),
    .add_sub_output(add_sub_output),
    .output_sum(output_sum)
);

assign Q = output_sum;

endmodule

module ring_counter (
    input clk,
    input reset,
    output reg [3:0] bit_0,
    output reg [3:0] bit_1,
    output reg [3:0] bit_2,
    output reg [3:0] bit_3
);

always @ (posedge clk) begin
    if (reset) begin
        bit_0 <= 1'b0;
        bit_1 <= 1'b0;
        bit_2 <= 1'b0;
        bit_3 <= 1'b0;
    end else begin
        bit_0 <= bit_1;
        bit_1 <= bit_2;
        bit_2 <= bit_3;
        bit_3 <= bit_0;
    end
end

endmodule

module add_sub (
    input [3:0] A,
    input [3:0] B,
    input C,
    output reg [3:0] Q
);

always @ (*) begin
    if (C) begin
        Q <= A + B;
    end else begin
        Q <= A - B;
    end
end

endmodule

module functional_module (
    input [3:0] counter_output,  // Output from the ring counter
    input [3:0] add_sub_output,  // Output from the adder/subtractor
    output [3:0] output_sum      // Sum of the two outputs
);

assign output_sum = counter_output + add_sub_output;

endmodule

