endmodule

module johnson_counter (
    input clk,
    input rst_n,
    output reg [7:0] out
);

    reg [7:0] state;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            state <= 8'b00000000;
        end else begin
            case (state)
                8'b00000000: state <= 8'b10000000;
                8'b10000000: state <= 8'b11000000;
                8'b11000000: state <= 8'b11100000;
                8'b11100000: state <= 8'b11110000;
                8'b11110000: state <= 8'b11111000;
                8'b11111000: state <= 8'b11111100;
                8'b11111100: state <= 8'b11111110;
                8'b11111110: state <= 8'b11111111;
                8'b11111111: state <= 8'b01111111;
                8'b01111111: state <= 8'b00111111;
                8'b00111111: state <= 8'b00011111;
                8'b00011111: state <= 8'b00001111;
                8'b00001111: state <= 8'b00000111;
                8'b00000111: state <= 8'b00000011;
                8'b00000011: state <= 8'b00000001;
                8'b00000001: state <= 8'b00000000;
            endcase
        end
    end

    assign out = state;

endmodule

module final_module (
    input b0,
    input b1,
    input b2,
    input [7:0] johnson_out,
    output reg [9:0] out
);

    always @(*) begin
        case ({b2, b1, b0, johnson_out[7:0]})
            4'b0000: out = 10'b0000000000;
            4'b0001: out = 10'b0000000001;
            4'b0010: out = 10'b0000000010;
            4'b0011: out = 10'b0000000011;
            4'b0100: out = 10'b0000000100;
            4'b0101: out = 10'b0000000101;
            4'b0110: out = 10'b0000000110;
            4'b0111: out = 10'b0000000111;
            4'b1000: out = 10'b0000001000;
            4'b1001: out = 10'b0000001001;
            4'b1010: out = 10'b0000001010;
            4'b1011: out = 10'b0000001011;
            4'b1100: out = 10'b0000001100;
            4'b1101: out = 10'b0000001101;
            4'b1110: out = 10'b0000001110;
            4'b1111: out = 10'b0000001111;
        endcase
    end

endmodule

module top_module (
    input clk,
    input rst_n,
    input [2:0] vec,
    output [9:0] outv
);

    wire b0, b1, b2;
    wire [7:0] johnson_out;

    binary_encoder encoder(
        .in(vec),
        .out(outv[2:0]),
        .b0(b0),
        .b1(b1),
        .b2(b2)
    );

    johnson_counter counter(
        .clk(clk),
        .rst_n(rst_n),
        .out(johnson_out)
    );

    final_module final(
        .b0(b0),
        .b1(b1),
        .b2(b2),
        .johnson_out(johnson_out),
        .out(outv)
    );

endmodule

module spi_slave_rx
(
  input clk,
  input rst,
  input cs,
  input sclk, 
  input mosi,
  output miso,
  output [7:0] rxd,
  output rxdv,
  output rxe
);

  localparam SW = 3;
  localparam ST_IDLE = 3'd0;
  localparam ST_CS_LO = 3'd1;
  localparam ST_SCLK_LO = 3'd2;
  localparam ST_SCLK_HI = 3'd3;
  localparam ST_CS_HI = 3'd4;

  localparam CW = 4;

  reg [SW+CW-1:0] ctrl;
  wire [SW-1:0] state;
  wire [SW-1:0] next_state = ctrl[SW+CW-1:CW];

  assign miso = 1'b0; // for now, this thing is just an RX machine

  // Synchronize inputs
  wire sclk_sync, mosi_sync, cs_sync;
  sync #(3, 3) in_sync
    (.clk(clk), .in({sclk, mosi, ~cs}), .out({sclk_sync, mosi_sync, cs_sync}));

  // Synchronize CS signal
  wire cs_sync_d1;
  r cs_sync_d1_r(.c(clk), .rst(rst), .en(1'b1), .d(cs_sync), .q(cs_sync_d1));

  // Synchronize SCLK signal
  wire sclk_sync_d1;
  r sclk_sync_d1_r(.c(clk), .rst(rst), .en(1'b1), 
                   .d(sclk_sync), .q(sclk_sync_d1));

  // Synchronize MOSI signal
  wire mosi_sync_d1;
  r mosi_sync_d1_r(.c(clk), .rst(rst), .en(1'b1),
                   .d(mosi_sync), .q(mosi_sync_d1));

  // Bit counter
  wire bit_cnt_rst, bit_cnt_en;
  wire [2:0] bit_cnt;
  r #(3) bit_cnt_r(.c(clk), .rst(bit_cnt_rst), .en(bit_cnt_en), 
                   .d(bit_cnt+1'b1), .q(bit_cnt));

  // Received data
  r #(8) rxd_r(.c(clk), .rst(rst), .en(bit_cnt_en), 
               .d({rxd[6:0], mosi_sync_d1}), .q(rxd));

  // State machine
  r #(SW) state_r(clk, next_state, rst, 1'b1, state);
  always @* begin
    case (state)
      ST_IDLE:
        if (cs_sync == 1'b0) ctrl = { ST_CS_LO, 4'b0001 };
        else ctrl = { ST_IDLE, 4'b0000 };
      ST_CS_LO:
        if (sclk_sync == 1'b0) ctrl = { ST_SCLK_LO, 4'b0000 };
        else ctrl = { ST_CS_LO, 4'b0000 };
      ST_SCLK_LO:
        if (sclk_sync == 1'b1) ctrl = { ST_SCLK_HI, 4'b0010 };
        else ctrl = { ST_SCLK_LO, 4'b0000 };
      ST_SCLK_HI:
        if (cs_sync == 1'b1) ctrl = { ST_CS_HI, 4'b0100 };
        else if (sclk_sync == 1'b0) ctrl = { ST_SCLK_LO, 4'b0100 };
        else ctrl = { ST_SCLK_HI, 4'b0000 };
      ST_CS_HI:
        ctrl = { ST_IDLE, 4'b0000 };
      default:
        ctrl = { ST_IDLE, 4'b0000 };
    endcase
  end

  // Output signals
  assign bit_cnt_rst = ctrl[0];
  assign bit_cnt_en = ctrl[1];
  assign sclk_hi_done = ctrl[2];
  assign rxdv = (bit_cnt == 3'b0) && (state == ST_SCLK_HI);
  assign rxe = (state == ST_CS_HI);

endmodule

module barrel_shifter (
    input [3:0] data,
    input [1:0] shift,
    output reg [3:0] result
);

reg [3:0] stage1_out;
reg [3:0] stage2_out;

always @(*) begin
    case(shift)
        2'b00: stage1_out = data;
        2'b01: stage1_out = {data[2:0], data[3]};
        2'b10: stage1_out = {data[1:3], data[0]};
        2'b11: stage1_out = {data[0], data[3:1]};
    endcase
end

always @(*) begin
    case(shift)
        2'b00: stage2_out = stage1_out;
        2'b01: stage2_out = {stage1_out[1:0], stage1_out[3:2]};
        2'b10: stage2_out = {stage1_out[2:0], stage1_out[3]};
        2'b11: stage2_out = {stage1_out[3], stage1_out[2:0]};
    endcase
end

assign result = stage2_out;

endmodule

module memory_module
  (
    clk_i,
    rst_i,
    we_i,  
    stb_i,
    ack_o,
    dat_i,
    dat_o,
    adr_i,
    a11,
    a12,
    b10,
    b11,
    b12
  );

  input clk_i;
  input rst_i;
  input we_i;
  input stb_i;
  output ack_o;
  input [15:0] dat_i;
  output [15:0] dat_o;
  input [2:0] adr_i;
  output [15:0] a11;
  output [15:0] a12;
  output [15:0] b10;
  output [15:0] b11;
  output [15:0] b12;

  reg [15:0] a11;
  reg [15:0] a12;
  reg [15:0] b10;
  reg [15:0] b11;
  reg [15:0] b12;

  wire ack_o;
  wire sel_a11;
  wire sel_a12;
  wire sel_b10;
  wire sel_b11;
  wire sel_b12;

  assign sel_a11 = (adr_i == 3'b000);
  assign sel_a12 = (adr_i == 3'b001);
  assign sel_b10 = (adr_i == 3'b010);
  assign sel_b11 = (adr_i == 3'b011);
  assign sel_b12 = (adr_i == 3'b100);

  assign ack_o = stb_i;

  always @(posedge clk_i or posedge rst_i)
    if (rst_i) begin
      a11 <= 16'hFF;
      a12 <= 16'h1F;
      b10 <= 16'h7F;
      b11 <= 16'h3;
      b12 <= 16'hFF;
    end
    else begin
      a11 <= (stb_i & we_i & sel_a11) ? dat_i : a11;
      a12 <= (stb_i & we_i & sel_a12) ? dat_i : a12;
      b10 <= (stb_i & we_i & sel_b10) ? dat_i : b10;
      b11 <= (stb_i & we_i & sel_b11) ? dat_i : b11;
      b12 <= (stb_i & we_i & sel_b12) ? dat_i : b12;
    end

  assign dat_o = sel_a11 ? a11 :
    (sel_a12 ? a12 :
    (sel_b10 ? b10 :
    (sel_b11 ? b11 :
    (sel_b12 ? b12 : 16'h0000))));

endmodule

module vending_machine(clk, rst, deposit, select, priceA, priceB, quantityA, quantityB, refund, dispense, change, soldA, soldB, total);

	input clk, rst, refund;
	input [9:0] deposit, priceA, priceB;
	input [1:0] select;
	input [5:0] quantityA, quantityB;
	output reg dispense;
	output reg [9:0] change, total;
	output reg [5:0] soldA, soldB;

	reg [9:0] deposit_reg, price_reg;
	reg [5:0] quantity_reg;
	reg [1:0] select_reg;
	reg [1:0] prev_select_reg;
	reg [9:0] change_reg;
	reg [5:0] soldA_reg, soldB_reg;
	reg [9:0] total_reg;
	reg [1:0] state;

	parameter IDLE = 2'd0;
	parameter DEPOSIT = 2'd1;
	parameter DISPENSE = 2'd2;
	parameter REFUND = 2'd3;

	always @(posedge clk) begin
		if (rst) begin
			deposit_reg <= 0;
			price_reg <= 0;
			quantity_reg <= 0;
			select_reg <= 0;
			prev_select_reg <= 0;
			change_reg <= 0;
			soldA_reg <= 0;
			soldB_reg <= 0;
			total_reg <= 0;
			state <= IDLE;
			dispense <= 0;
			change <= 0;
			soldA <= 0;
			soldB <= 0;
			total <= 0;
		end else begin
			case (state)
				IDLE: begin
					if (deposit > 0 && deposit <= 500) begin
						deposit_reg <= deposit;
						if (select == 1) begin
							price_reg <= priceA;
							quantity_reg <= quantityA;
							select_reg <= select;
							prev_select_reg <= select;
							state <= DISPENSE;
						end else if (select == 2) begin
							price_reg <= priceB;
							quantity_reg <= quantityB;
							select_reg <= select;
							prev_select_reg <= select;
							state <= DISPENSE;
						end else begin
							state <= IDLE;
						end
					end else begin
						state <= REFUND;
					end
				end
				DEPOSIT: begin
					if (deposit > 0 && deposit <= 500) begin
						deposit_reg <= deposit_reg + deposit;
						if (select == 1) begin
							price_reg <= priceA;
							quantity_reg <= quantityA;
							select_reg <= select;
							prev_select_reg <= select;
							state <= DISPENSE;
						end else if (select == 2) begin
							price_reg <= priceB;
							quantity_reg <= quantityB;
							select_reg <= select;
							prev_select_reg <= select;
							state <= DISPENSE;
						end else begin
							state <= DEPOSIT;
						end
					end else begin
						state <= REFUND;
					end
				end
				DISPENSE: begin
					if (prev_select_reg != select_reg) begin
						if (select == 1) begin
							price_reg <= priceA;
							quantity_reg <= quantityA;
							select_reg <= select;
						end else if (select == 2) begin
							price_reg <= priceB;
							quantity_reg <= quantityB;
							select_reg <= select;
						end
					end
					if (deposit_reg >= price_reg && quantity_reg > 0) begin
						dispense <= 1;
						change_reg <= deposit_reg - price_reg;
						total_reg <= total_reg + price_reg;
						if (select_reg == 1) begin
							soldA_reg <= soldA_reg + 1;
							quantity_reg <= quantity_reg - 1;
						end else if (select_reg == 2) begin
							soldB_reg <= soldB_reg + 1;
							quantity_reg <= quantity_reg - 1;
						end
						state <= REFUND;
					end else begin
						dispense <= 0;
						state <= DEPOSIT;
					end
				end
				REFUND: begin
					if (refund) begin
						change <= deposit_reg;
						change_reg <= 0;
						deposit_reg <= 0;
						state <= IDLE;
					end else begin
						change <= change_reg;
						state <= REFUND;
					end
				end
			endcase
			soldA <= soldA_reg;
			soldB <= soldB_reg;
			total <= total_reg;
		end
	end
endmodule

