module wb_reg (
    input clk,
    input rst,
    input [ADDR_WIDTH-1:0] wbm_adr_i,
    input [DATA_WIDTH-1:0] wbm_dat_i,
    output reg [DATA_WIDTH-1:0] wbm_dat_o,
    input wbm_we_i,
    input [SELECT_WIDTH-1:0] wbm_sel_i,
    input wbm_stb_i,
    output reg wbm_ack_o,
    output reg wbm_err_o,
    output reg wbm_rty_o,
    input wbm_cyc_i,
    output reg [ADDR_WIDTH-1:0] wbs_adr_o,
    output reg [DATA_WIDTH-1:0] wbs_dat_o,
    output reg wbs_we_o,
    output reg [SELECT_WIDTH-1:0] wbs_sel_o,
    output reg wbs_stb_o,
    input wbs_ack_i,
    input wbs_err_i,
    input wbs_rty_i,
    output reg wbs_cyc_o
);

// Internal registers
reg [DATA_WIDTH-1:0] reg_data [0:(2**ADDR_WIDTH)-1];

// Combinational logic for address decoding
assign wbs_cyc_o = wbm_cyc_i;
assign wbs_adr_o = wbm_adr_i;
assign wbs_dat_o = reg_data[wbm_adr_i];
assign wbs_we_o = wbm_we_i;
assign wbs_sel_o = wbm_sel_i;
assign wbs_stb_o = wbm_stb_i;

// Synchronous logic for write enable
always @(posedge clk) begin
    if (rst) begin
        wbm_ack_o <= 0;
        wbm_err_o <= 0;
        wbm_rty_o <= 0;
    end else if (wbm_cyc_i && wbm_stb_i) begin
        if (wbm_we_i) begin
            if (wbm_sel_i == 4'b1111) begin
                reg_data[wbm_adr_i] <= wbm_dat_i;
            end else begin
                reg_data[wbm_adr_i][(wbm_sel_i << 3) +: 8] <= wbm_dat_i;
            end
            wbm_ack_o <= 1;
        end else begin
            wbm_err_o <= 1;
        end
    end else begin
        wbm_rty_o <= 1;
    end
end

// Synchronous logic for data output
always @(posedge clk) begin
    if (rst) begin
        wbm_dat_o <= 0;
    end else begin
        if (wbm_cyc_i && wbm_stb_i && !wbm_we_i) begin
            if (wbm_sel_i == 4'b1111) begin
                wbm_dat_o <= reg_data[wbm_adr_i];
            end else begin
                wbm_dat_o <= reg_data[wbm_adr_i][(wbm_sel_i << 3) +: 8];
            end
        end
    end
end

endmodule

