module TEST_CLK_DIV(
	input clk_test, rst,
	output clk_LCD, clk_7seg, clk_1s, clk_500ms, clk_1us,
	output test_passed
);

	reg [31:0] count;
	reg [31:0] count_1s;
	reg [31:0] count_500ms;
	reg [31:0] count_LCD;
	reg [31:0] count_7seg;
	reg [31:0] count_test;
	reg [31:0] count_delay;

	wire next_clk_1s, next_clk_500ms, next_clk_1us;
	wire clk_LCD, clk_7seg;
	reg clk_1s, clk_500ms, clk_1us;

	CLK_DIV dut (
		.clk(clk_test),
		.clk_LCD(clk_LCD),
		.clk_7seg(clk_7seg),
		.clk_1s(clk_1s),
		.clk_500ms(clk_500ms),
		.clk_1us(clk_1us)
	);

	assign next_clk_1s = (count_1s<40000000) ? 1'b0 : 1'b1;
	assign next_clk_500ms = (count_500ms<20000000) ? 1'b0 : 1'b1;
	assign next_clk_1us = (count_test<5) ? 1'b0 : 1'b1;

	always @(posedge clk_test) begin
		if (rst) begin
			count <= 0;
			count_1s <= 0;
			count_500ms <= 0;
			count_LCD <= 0;
			count_7seg <= 0;
			count_test <= 0;
			count_delay <= 0;
			clk_1s <= 0;
			clk_500ms <= 0;
			clk_1us <= 0;
			test_passed <= 0;
		end else begin
			count <= count + 1;
			count_1s <= (next_clk_1s) ? 0 : count_1s + 1;
			count_500ms <= (next_clk_500ms) ? 0 : count_500ms + 1;
			count_LCD <= (count_delay==256) ? 1 : (count_delay==512) ? 0 : count_LCD;
			count_7seg <= (count_delay==65536) ? 1 : (count_delay==131072) ? 0 : count_7seg;
			count_test <= count_test + 1;
			count_delay <= count_delay + 1;

			if (count_1s==40000000) begin
				if (clk_1s==1 && clk_500ms==0) begin
					$display("Test 2 passed");
				end else begin
