module up_down_counter (
    input clk,
    input reset,
    input enable,
    input up_down,
    output reg [1:0] count,
    output reg overflow
);

    always @(posedge clk) begin
        if (!reset) begin
            count <= 2'b00;
            overflow <= 0;
        end else if (enable) begin
            if (up_down) begin
                if (count == 2'b11) begin
                    count <= 2'b00;
                    overflow <= 1;
                end else begin
                    count <= count + 2'b01;
                    overflow <= 0;
                end
            end else begin
                if (count == 2'b00) begin
                    count <= 2'b11;
                    overflow <= 1;
                end else begin
                    count <= count - 2'b01;
                    overflow <= 0;
                end
            end
        end
    end

endmodule

module debounce_xor (
  input clk,
  input reset,
  input in1,
  input in2,
  output reg out
);

reg [1:0] state;
reg [1:0] next_state;

parameter DEBOUNCE_CYCLES = 3;

always @(posedge clk, posedge reset) begin
  if (reset) begin
    state <= 2'b00;
  end else begin
    state <= next_state;
  end
end

always @(*) begin
  case (state)
    2'b00: begin
      if (in1 && in2) begin
        next_state = 2'b01;
      end else begin
        next_state = 2'b00;
      end
    end
    2'b01: begin
      if (in1 && in2) begin
        next_state = 2'b10;
      end else begin
        next_state = 2'b00;
      end
    end
    2'b10: begin
      if (in1 && in2) begin
        next_state = 2'b11;
      end else begin
        next_state = 2'b00;
      end
    end
    2'b11: begin
      if (in1 && in2) begin
        next_state = 2'b11;
      end else begin
        next_state = 2'b00;
      end
    end
  endcase
end

reg [1:0] debounce_counter;

always @(posedge clk) begin
  if (reset) begin
    debounce_counter <= 2'b00;
  end else begin
    debounce_counter <= debounce_counter + 1;
    if (debounce_counter == DEBOUNCE_CYCLES) begin
      debounce_counter <= 2'b00;
      out <= in1 ^ in2;
    end
  end
end

endmodule

module wishbone_mem_interconnect (
  //Control Signals
  input               clk,
  input               rst,

  //Master Signals
  input               i_m_we,
  input               i_m_stb,
  input               i_m_cyc,
  input       [3:0]   i_m_sel,
  input       [31:0]  i_m_adr,
  input       [31:0]  i_m_dat,
  output reg  [31:0]  o_m_dat,
  output reg          o_m_ack,
  output reg          o_m_int,

  //Slave 0
  output              o_s0_we,
  output              o_s0_cyc,
  output              o_s0_stb,
  output    [3:0]     o_s0_sel,
  input               i_s0_ack,
  output    [31:0]    o_s0_dat,
  input     [31:0]    i_s0_dat,
  output    [31:0]    o_s0_adr,
  input               i_s0_int

);

//memory map parameters
parameter MEM_SEL_0 = 0;
parameter MEM_OFFSET_0  =  32'h00000000;
parameter MEM_SIZE_0  =  32'h800000;

//memory select signal
reg [31:0] mem_select;

//logic to select the memory block
always @(rst or i_m_adr or mem_select) begin
  if (rst) begin
    //nothing selected
    mem_select <= 32'hFFFFFFFF;
  end
  else begin
    if ((i_m_adr >= MEM_OFFSET_0) && (i_m_adr < (MEM_OFFSET_0 + MEM_SIZE_0))) begin
      mem_select <= MEM_SEL_0;
    end
    else begin
      mem_select <= 32'hFFFFFFFF;
    end
  end
end

//data in from slave
always @ (mem_select or i_s0_dat) begin
  case (mem_select)
    MEM_SEL_0: begin
      o_m_dat <= i_s0_dat;
    end
    default: begin
      o_m_dat <= 32'h0000;
    end
  endcase
end

//ack in from mem slave
always @ (mem_select or i_s0_ack) begin
  case (mem_select)
    MEM_SEL_0: begin
      o_m_ack <= i_s0_ack;
    end
    default: begin
      o_m_ack <= 1'h0;
    end
  endcase
end

//int in from slave
always @ (mem_select or i_s0_int) begin
  case (mem_select)
    MEM_SEL_0: begin
