    input read_en,
    input [7:0] read_addr,
    output reg [3:0] read_data
);

reg [3:0] ram [0:7];

// Asynchronous read port
always @ (posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        read_data <= 4'b0;
    end else if (read_en) begin
        read_data <= ram[read_addr];
    end
end

// Synchronous write port
always @ (posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        ram <= {8{4'b0}};
    end else if (write_en) begin
        ram[write_addr] <= write_data;
    end
end

endmodule

module top_module (
    input clk,
    input reset,
    input load,
    input up_down,
    input select,
    input [3:0] shift_amount,
    output [15:0] result
);

    reg [2:0] counter;
    reg [15:0] shift_left;
    reg [15:0] shift_right;

    // Counter module
    always @(posedge clk, posedge reset) begin
        if (reset) begin
            counter <= 3'b0;
        end else if (load) begin
            counter <= 3'b0;
        end else if (up_down) begin
            counter <= counter + 1;
        end else begin
            counter <= counter - 1;
        end
    end

    // Barrel shifter module
    always @(*) begin
        case (shift_amount)
            4'b0000: begin
                shift_left = counter << 0;
                shift_right = counter >> 0;
            end
            4'b0001: begin
                shift_left = counter << 1;
                shift_right = counter >> 1;
            end
            4'b0010: begin
                shift_left = counter << 2;
                shift_right = counter >> 2;
            end
            4'b0011: begin
                shift_left = counter << 3;
                shift_right = counter >> 3;
            end
            4'b0100: begin
                shift_left = counter << 4;
                shift_right = counter >> 4;
            end
            4'b0101: begin
                shift_left = counter << 5;
                shift_right = counter >> 5;
            end
            4'b0110: begin
                shift_left = counter << 6;
                shift_right = counter >> 6;
            end
            4'b0111: begin
                shift_left = counter << 7;
                shift_right = counter >> 7;
            end
            4'b1000: begin
                shift_left = counter << 8;
                shift_right = counter >> 8;
            end
            4'b1001: begin
                shift_left = counter << 9;
                shift_right = counter >> 9;
            end
            4'b1010: begin
                shift_left = counter << 10;
                shift_right = counter >> 10;
            end
            4'b1011: begin
                shift_left = counter << 11;
                shift_right = counter >> 11;
            end
            4'b1100: begin
                shift_left = counter << 12;
                shift_right = counter >> 12;
            end
            4'b1101: begin
                shift_left = counter << 13;
                shift_right = counter >> 13;
            end
            4'b1110: begin
                shift_left = counter << 14;
                shift_right = counter >> 14;
            end
            4'b1111: begin
                shift_left = counter << 15;
                shift_right = counter >> 15;
            end
        endcase
    end

    // Output module
    always @(*) begin
        if (select) begin
            result = shift_left;
        end else begin
            result = shift_right;
        end
    end

endmodule

module hpdmc_datactl(
	input sys_clk,
	input sdram_rst,

	input read,
	input write,
	input [3:0] concerned_bank,
	output reg read_safe,
	output reg write_safe,
	output [3:0] precharge_safe,

	output reg direction,
	output direction_r,

	input tim_cas,
	input [1:0] tim_wr
);

/*
 * read_safe: whether it is safe to register a Read command
 * into the SDRAM at the next cycle.
 */

reg [2:0] read_safe_counter;
always @(posedge sys_clk) begin
	if(sdram_rst) begin
		read_safe_counter <= 3'd0;
		read_safe <= 1'b1;
	end else begin
		if(read) begin
			read_safe_counter <= 3'd3;
			read_safe <= 1'b0;
		end else if(write) begin
			/* after a write, read is unsafe for 5 cycles (4 transfers + tWTR=1) */
			read_safe_counter <= 3'd5;
			read_safe <= 1'b0;
		end else begin
			if(read_safe_counter == 3'd1)
				read_safe <= 1'b1;
			if(~read_safe)
				read_safe_counter <= read_safe_counter - 3'd1;
		end
	end
end

/*
 * write_safe: whether it is safe to register a Write command
 * into the SDRAM at the next cycle.
 */

reg [2:0] write_safe_counter;
always @(posedge sys_clk) begin
	if(sdram_rst) begin
		write_safe_counter <= 3'd0;
		write_safe <= 1'b1;
	end else begin
		if(read) begin
			write_safe_counter <= {1'b1, tim_cas, ~tim_cas};
			write_safe <= 1'b0;
		end else if(write) begin
			write_safe_counter <= 3'd4;
			write_safe <= 1'b0;
		end else begin
			if(write_safe_counter == 3'd1)
				write_safe <= 1'b1;
			if(~write_safe)
				write_safe_counter <= write_safe_counter - 3'd1;
		end
	end
end

reg [1:0] counter_writedirection;
always @(posedge sys_clk) begin
	if(sdram_rst) begin
		counter_writedirection <= 2'd0;
	end else begin
		if(write)
			counter_writedirection <= 2'd3;
		else if(|counter_writedirection)
			counter_writedirection <= counter_writedirection - 2'd1;
	end
end

reg direction0;
always @(posedge sys_clk) begin
	direction0 <= ~(write | (|counter_writedirection));
	direction <= direction0;
end

/* Counters that prevent a busy bank from being precharged */
hpdmc_banktimer banktimer0(
	.sys_clk(sys_clk),
	.sdram_rst(sdram_rst),

	.tim_cas(tim_cas),
	.tim_wr(tim_wr),

	.read(read & concerned_bank[0]),
	.write(write & concerned_bank[0]),
	.precharge_safe(precharge_safe[0])
);
hpdmc_banktimer banktimer1(
	.sys_clk(sys_clk),
	.sdram_rst(sdram_rst),

	.tim_cas(tim_cas),
	.tim_wr(tim_wr),

	.read(read & concerned_bank[1]),
	.write(write & concerned_bank[1]),
	.precharge_safe(precharge_safe[1])
);
hpdmc_banktimer banktimer2(
	.sys_clk(sys_clk),
	.sdram_rst(sdram_rst),

	.tim_cas(tim_cas),
	.tim_wr(tim_wr),

	.read(read & concerned_bank[2]),
	.write(write & concerned_bank[2]),
	.precharge_safe(precharge_safe[2])
);
hpdmc_banktimer banktimer3(
	.sys_clk(sys_clk),
	.sdram_rst(sdram_rst),

	.tim_cas(tim_cas),
	.tim_wr(tim_wr),

	.read(read & concerned_bank[3]),
	.write(write & concerned_bank[3]),
	.precharge_safe(precharge_safe[3])
);

endmodule

module hpdmc_banktimer(
	input sys_clk,
	input sdram_rst,

	input read,
	input write,
	output reg precharge_safe,

	input tim_cas,
	input [1:0] tim_wr
);

reg [1:0] counter;
always @(posedge sys_clk) begin
	if(sdram_rst) begin
		counter <= 2'd0;
		precharge_safe <= 1'b1;
	end else begin
		if(read | write) begin
			counter <= {1'b1, tim_cas, ~tim_cas};
			precharge_safe <= 1'b0;
		end else begin
			if(counter == 2'd1)
				precharge_safe <= 1'b1;
			if(~precharge_safe)
				counter <= counter - 2'd1;
		end
	end
end

endmodule

module freq_divider (
  input clk_in,
  output reg clk_out
);

  parameter n = 2; // division factor

  reg [31:0] count;

  always @(posedge clk_in) begin
    if (count == n-1) begin
      clk_out <= ~clk_out;
      count <= 0;
    end else begin
      count <= count + 1;
    end
  end

endmodule

module aluparam_behav
    #( parameter BITSIZE = 16)
    ( output [BITSIZE-1:0] Y,
      output [15:0] flags,
      input [BITSIZE-1:0] A,
      input [BITSIZE-1:0] B,
      input [3:0] sel
    );


     reg [BITSIZE-1:0] outreg;
     reg [15:0] flagreg;

     reg carry;
     reg overflow;
     reg borrow;

     always @(A, B, sel) begin

        flagreg = 0;
        carry = 0;
        borrow = 0;
        overflow = 0;

        case(sel)
            4'b0000: begin
                            outreg = A ^ B;
                        end
            4'b0010: begin
                            outreg = ~(A ^ B);
                        end
            4'b1000: begin
                            outreg = A & B;
                        end
            4'b1010: begin
                            outreg = A | B;
                        end
            4'b0100: begin
                            {carry, outreg} = A + B;
                            overflow = ((A[BITSIZE-1] == B[BITSIZE-1]) && (A[BITSIZE-1] != outreg[BITSIZE-1])) ? 1 : 0;
                        end
            4'b0101: begin
                            {borrow, outreg} = A - B;
                            overflow = ((A[BITSIZE-1] != B[BITSIZE-1]) && (A[BITSIZE-1] != outreg[BITSIZE-1])) ? 1 : 0;
                        end
            4'b0111: begin
                            outreg = ~A;
                        end

            default: begin 
                            outreg = 0; 
                            flagreg = 0;
                        end

        endcase

        flagreg[0] = carry;    // Carry
        flagreg[2] = borrow;   // Borrow
        flagreg[5] = overflow; // Overflow
        flagreg[6] = (outreg == 0); // Zero Flag
        flagreg[7] = outreg[BITSIZE-1]; // Sign Flag
     end

     assign Y = outreg;
     assign flags = flagreg;

endmodule

module simple_cpu (
    input           clk,        // clock
    input           rst_n,      // reset
    input   [ 4:0]  regAddr,    // debug access reg address
    output  [31:0]  regData,    // debug access reg data
    output  [31:0]  imAddr,     // instruction memory address
    input   [31:0]  imData,     // instruction memory data
    input	[31:0]	gpio,		// GPIOs
    output	[31:0]	gpioOut		// GPIO output
);

    // Program counter
    wire [31:0] pc;
    wire [31:0] pcBranch;
    wire [31:0] pcNext  = pc + 1;
    sm_register r_pc(clk, rst_n, pc_new, pc);

    // Instruction memory access
    assign imAddr = pc;
    wire [31:0] instr = imData;

    // Debug register access
    wire [31:0] rd0;
    assign regData = (regAddr != 0) ? rd0 : pc;

    // Register file
    wire [ 4:0] a3  = instr[20:16];
    wire [31:0] rd1;
    wire [31:0] rd2;
    wire [31:0] wd3;
    sm_register_file rf
    (
        .clk        ( clk          ),
        .a0         ( regAddr      ),
        .a1         ( instr[25:21] ),
        .a2         ( instr[20:16] ),
        .a3         ( a3           ),
        .rd0        ( rd0          ),
        .rd1        ( rd1          ),
        .rd2        ( rd2          ),
        .wd3        ( wd3          ),
        .we3        ( instr[31]    )
    );

    // ALU
    wire [31:0] srcB = instr[15:0];
    wire [31:0] aluResult;
    sm_alu alu
    (
        .srcA       ( rd1         ),
        .srcB       ( srcB        ),
        .oper       ( instr[31:26]),
        .shift      ( instr[10:6] ),
        .sign       ( aluResult   )
    );

    // Control
    wire        pcSrc;
    wire        regDst;
    wire        regWrite;
    wire        aluSrc;
    wire        aluZero;
    wire [ 3:0] aluControl;
    wire		exControl;
    sm_control sm_control
    (
        .cmdOper    ( instr[31:26] ),
        .cmdFunk    ( instr[ 5:0 ] ),
        .aluZero    ( aluZero      ),
        .pcSrc      ( pcSrc        ), 
        .regDst     ( regDst       ), 
        .regWrite   ( regWrite     ), 
        .aluSrc     ( aluSrc       ),
        .aluControl ( aluControl   ),
        .exControl	( exControl    )
    );

    // Data memory
    wire [31:0] memAddr = aluResult;
    wire [31:0] memData;
    sm_data_mem dataMem
    (
        .clk        ( clk     ),
        .we         ( instr[30]),
        .addr       ( memAddr ),
        .dataIn     ( wd3     ),
        .dataOut    ( memData )
    );

    // GPIOs
    sm_gpio gpio
    (
        .clk        ( clk     ),
        .dataIn     ( gpio    ),
        .dataOut    ( gpioOut )
    );

    // Sign extension
    wire signExtend;
    wire [31:0] signImm = (exControl) ? {{24 { gpio[7] }}, gpio[7:0] } 
    : (~signExtend) ? { {16 { instr[15] }}, instr[15:0] } : { {16 {1'b0}}, instr[15:0] };
    assign pcBranch = pcNext + signImm;

    // Update PC
    assign pc_new = (pcSrc) ? pcBranch : pcNext;

    // Writeback
    wire [ 4:0] wbReg = (regDst) ? instr[15:11] : instr[20:16];
    wire [31:0] wbData = (aluSrc) ? aluResult : memData;
    sm_register wbRegFile(clk, rst_n, wbData, wbReg, regWrite);

endmodule

