module top_module(
    input clk,
    input rst_n,
    input [7:0] in,
    input valid_a,
    input ready_b,
    output ready_a,
    output reg valid_b,
    output reg [9:0] data_out
);
    reg [3:0] in_hi;
    reg [3:0] in_lo;
    reg [5:0] accumulator;
    reg [5:0] accumulator_next;
    reg [1:0] carry_in;
    wire [5:0] sum;
    reg [5:0] result_reg;
    reg [5:0] result_reg_next;
    reg [5:0] accumulator_reg;
    reg [5:0] accumulator_reg_next;
    wire [5:0] compare_value;
    reg [1:0] state;

    splitter splitter_inst(
        .in(in),
        .out_hi(in_hi),
        .out_lo(in_lo)
    );

    assign sum = {carry_in, in_hi} + {1'b0, in_lo};

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            accumulator <= 6'b0;
            result_reg <= 6'b0;
            accumulator_reg <= 6'b0;
            valid_b <= 1'b0;
            state <= 2'b00;
        end else begin
            case (state)
                2'b00: begin
                    accumulator_next = accumulator + sum;
                    result_reg_next = result_reg;
                    accumulator_reg_next = accumulator_reg;
                    if (accumulator_next >= 6'd64) begin
                        result_reg_next = accumulator_reg + sum;
                        accumulator_reg_next = 6'b0;
                        valid_b <= 1'b1;
                        state <= 2'b01;
                    end else begin
                        state <= 2'b00;
                    end
                end
                2'b01: begin
                    if (ready_b) begin
                        accumulator_next = sum;
                        result_reg_next = 6'b0;
                        accumulator_reg_next = accumulator_reg + sum;
                        valid_b <= 1'b0;
                        state <= 2'b00;
                    end else begin
                        state <= 2'b01;
                    end
                end
            endcase
            accumulator <= accumulator_next;
            result_reg <= result_reg_next;
            accumulator_reg <= accumulator_reg_next;
        end
    end

    assign compare_value = result_reg + accumulator_reg;

    assign ready_a = ~valid_a;
    assign data_out = compare_value;

endmodule

