  reg [23:0] s444_data_d3 = 0;
  reg [7:0] cr = 0;
  reg [7:0] cb = 0;
  reg cr_cb_sel = 0;

  always @(posedge clk) begin
    s444_data_d3 <= s444_data_d2;
    s444_data_d2 <= s444_data_d1;
    s444_data_d1 <= s444_data;
  end

  assign cr = (s444_data_d1[23:16] + s444_data_d2[23:16] + s444_data_d3[23:16] + 1) >> 2;
  assign cb = (s444_data_d1[7:0] + s444_data_d2[7:0] + s444_data_d3[7:0] + 1) >> 2;

  always @(posedge clk) begin
    if (s444_de) begin
      if (Cr_Cb_N) begin
        s422_data <= {cr, s444_data_d2[15:8]};
      end else begin
        s422_data <= {cb, s444_data_d2[15:8]};
      end
    end
    s422_sync <= s444_sync;
    if (s444_de) begin
      cr_cb_sel <= ~cr_cb_sel;
    end
  end

endmodule

module cbc_des(
  input             reset_i,  // async reset
  input             clk_i,    // clock
  input             start_i,  // start cbc
  input             mode_i,   // des-mode: 0 = encrypt, 1 = decrypt
  input  [0:63]     key_i,    // key input
  input  [0:63]     iv_i,     // iv input
  input  [0:63]     data_i,   // data input
  input             valid_i,  // input key/data valid flag
  output reg        ready_o,  // ready to encrypt/decrypt
  output reg [0:63] data_o,   // data output
  output            valid_o   // output data valid flag
);

  reg         mode;
  wire        des_mode;
  reg         start;
  reg  [0:63] key;
  wire [0:63] des_key;
  reg  [0:63] iv;
  reg  [0:63] datain;
  reg  [0:63] datain_d;
  reg  [0:63] des_datain;
  wire        validin;
  wire [0:63] des_dataout;
  reg         reset;
  reg  [0:63] dataout;

  assign des_key  = (start_i) ? key_i  : key;
  assign des_mode = (start_i) ? mode_i : mode;

  assign validin = valid_i & ready_o;

  always @(*) begin
    if (~mode_i && start_i) begin
      des_datain = iv_i ^ data_i;
    end
    else if (~mode && ~start_i) begin
      des_datain = dataout ^ data_i;
    end
    else begin
      des_datain = data_i;
    end
  end

  always @(*) begin
    if (mode && start) begin
      data_o = iv ^ des_dataout;
    end
    else if (mode && ~start) begin
      data_o = datain_d ^ des_dataout;
    end
    else begin
      data_o = des_dataout;
    end
  end

  // input register
  always @(posedge clk_i, negedge reset_i) begin
    if (~reset_i) begin
      reset    <= 0;
      mode     <= 0;
      start    <= 0;
      key      <= 0;
      iv       <= 0;
      datain   <= 0;
      datain_d <= 0;
    end
    else begin
      reset <= reset_i;
      if (valid_i && ready_o) begin
        start    <= start_i;
        datain   <= data_i;
        datain_d <= datain;
      end
      else if (valid_i && ready_o && start_i) begin
        mode <= mode_i;
        key  <= key_i;
        iv   <= iv_i;
      end
    end
  end

  // output register
  always @(posedge clk_i, negedge reset_i) begin
    if (~reset_i) begin
      ready_o <= 0;
      dataout <= 0;
    end
    else begin
      if (valid_i && ready_o) begin
        ready_o <= 0;
      end
      else if (valid_o || (reset_i && ~reset)) begin
        ready_o <= 1;
        dataout <= des_dataout;
      end
    end
  end

  // des instance
  des i_des (
    .reset_i(reset),
    .clk_i(clk_i),
    .mode_i(des_mode),
    .key_i(des_key),
    .data_i(des_datain),
    .valid_i(validin),
    .data_o(des_dataout),
    .valid_o(valid_o)
  );

  always @(posedge clk_i) begin
    if (valid_i && ready_o) begin
      if (start_i) begin
        iv <= dataout;
      end
      else begin
        iv <= datain;
      end
    end
  end

endmodule

module binary_adder(
    input [3:0] A,
    input [3:0] B,
    output [4:0] C
);

    wire [3:0] sum;
    wire carry;

    // First bit
    full_adder FA0(.a(A[0]), .b(B[0]), .cin(1'b0), .sum(sum[0]), .cout(carry));
    // Second bit
    full_adder FA1(.a(A[1]), .b(B[1]), .cin(carry), .sum(sum[1]), .cout(carry));
    // Third bit
    full_adder FA2(.a(A[2]), .b(B[2]), .cin(carry), .sum(sum[2]), .cout(carry));
    // Fourth bit
    full_adder FA3(.a(A[3]), .b(B[3]), .cin(carry), .sum(sum[3]), .cout(C[4]));

    // Concatenate sum and carry bits
    assign C = {carry, sum};

endmodule

// Full adder module
module full_adder(
    input a,
    input b,
    input cin,
    output sum,
    output cout
);

    wire s1, s2, s3;

    // XOR gates
    assign s1 = a ^ b;
    assign sum = s1 ^ cin;
    // AND gates
    assign s2 = a & b;
    assign s3 = s1 & cin;
    // OR gate
    assign cout = s2 | s3;

endmodule

module cic_dec_shifter(rate,signal_in,signal_out);
   parameter bw = 16;
   parameter maxbitgain = 28;

   input [7:0] rate;
   input       wire [bw+maxbitgain-1:0] signal_in;
   output      reg [bw-1:0] signal_out;

   function [4:0] bitgain;
      input [7:0] rate;
      case(rate)
	// Exact Cases -- N*log2(rate)
	8'd1 : bitgain = 0;
	8'd2 : bitgain = 4;
	8'd4 : bitgain = 8;
	8'd8 : bitgain = 12;
	8'd16 : bitgain = 16;
	8'd32 : bitgain = 20;
	8'd64 : bitgain = 24;
	8'd128 : bitgain = 28;

	// Nearest without overflow -- ceil(N*log2(rate))
	8'd3 : bitgain = 7;
	8'd5 : bitgain = 10;
	8'd6 : bitgain = 11;
	8'd7 : bitgain = 12;
	8'd9 : bitgain = 13;
	8'd10,8'd11 : bitgain = 14;
	8'd12,8'd13 : bitgain = 15;
	8'd14,8'd15 : bitgain = 16;
	8'd17,8'd18,8'd19 : bitgain = 17;
