module RegisterAddSub (clk, rst, load, D, Q);
  input clk, rst, load;
  input [0:0] D;
  output [0:0] Q;
  wire n3, n4, n5, n6;

  // D flip-flop with reset and load enable
  DFFRXLTS Q_reg_0_ (
    .D(n3),
    .CK(clk),
    .RN(n4),
    .Q(Q[0])
  );

  // inverter
  INVX2TS U2 (
    .A(rst),
    .Y(n4)
  );

  // OR gate for addition
  OR2X1TS U3 (
    .A(Q[0]),
    .B(load),
    .Y(n5)
  );

  // OR gate for subtraction
  OR2X1TS U4 (
    .A(n5),
    .B(n6),
    .Y(n3)
  );

  // inverter for subtraction
  INVX2TS U5 (
    .A(load),
    .Y(n6)
  );

  always @(posedge clk or negedge rst) begin
    if (!rst) begin
      Q <= 1'b0;
    end else begin
      if (load) begin
        Q <= D;
      end else begin
        if (n5) begin
          Q <= Q + 1'b1;
        end else if (n6) begin
          Q <= Q - 1'b1;
        end
      end
    end
  end

endmodule

