module eth_mac_tx (
  input [n-1:0] data_in,
  input [47:0] src_addr,
  input [47:0] dest_addr,
  input start_transmit,
  output [m-1:0] data_out,
  output tx_en,
  output tx_done
);

parameter n = 64; // number of bits in input data signal
parameter m = 64; // number of bits in output data signal

// Define Ethernet frame format
parameter ETH_PREAMBLE = 64'hAAAAAAAAAAAAAAAB;
parameter ETH_SFD = 8'hAB;
parameter ETH_TYPE = 16'h0800; // IPv4
parameter ETH_CRC_SIZE = 32;

reg [ETH_CRC_SIZE-1:0] crc;
reg [n+ETH_CRC_SIZE-1:0] frame;
reg [7:0] byte_count;
reg [7:0] bit_count;
reg [7:0] preamble_count;
reg [7:0] sfd_count;
reg [7:0] type_count;
reg [7:0] data_count;
reg [1:0] state;

// State machine states
parameter IDLE = 2'b00;
parameter PREAMBLE = 2'b01;
parameter SFD = 2'b10;
parameter TYPE = 2'b11;
parameter DATA = 2'b100;
parameter CRC = 2'b101;
parameter TX = 2'b110;
parameter DONE = 2'b111;

// Calculate CRC checksum
function [ETH_CRC_SIZE-1:0] crc32;
  input [n-1:0] data;
  reg [ETH_CRC_SIZE-1:0] crc;
  reg [31:0] i, j;
  begin
    for (i = 0; i < n; i = i + 8) begin
      crc = crc ^ {data[i+7:i]};
      for (j = 0; j < 8; j = j + 1) begin
        if (crc[ETH_CRC_SIZE-1]) begin
          crc = {crc[ETH_CRC_SIZE-2:0], 1'b0} ^ 32'h04C11DB7;
        end else begin
          crc = crc << 1;
        end
      end
    end
    crc32 = crc;
  end
endfunction

// State machine
always @(*) begin
  case (state)
    IDLE: begin
      if (start_transmit) begin
        state = PREAMBLE;
        byte_count = 0;
        bit_count = 0;
        preamble_count = 0;
        sfd_count = 0;
        type_count = 0;
        data_count = 0;
        crc = crc32(data_in);
      end
    end
    PREAMBLE: begin
      if (preamble_count < 8) begin
        data_out = ETH_PREAMBLE[bit_count];
        bit_count = bit_count + 1;
        if (bit_count == 64) begin
          bit_count = 0;
          preamble_count = preamble_count + 1;
        end
      end else begin
        state = SFD;
        byte_count = 0;
        bit_count = 0;
      end
    end
    SFD: begin
      if (sfd_count < 1) begin
        data_out = ETH_SFD[bit_count];
        bit_count = bit_count + 1;
        if (bit_count == 8) begin
          bit_count = 0;
          sfd_count = sfd_count + 1;
        end
      end else begin
        state = TYPE;
        byte_count = 0;
        bit_count = 0;
      end
    end
    TYPE: begin
      if (type_count < 2) begin
        data_out = ETH_TYPE[bit_count];
        bit_count = bit_count + 1;
        if (bit_count == 16) begin
          bit_count = 0;
          type_count = type_count + 1;
        end
      end else begin
        state = DATA;
        byte_count = 0;
        bit_count = 0;
      end
    end
    DATA: begin
      if (byte_count < n/8) begin
        data_out = data_in[byte_count*8 + bit_count];
        bit_count = bit_count + 1;
        if (bit_count == 8) begin
          bit_count = 0;
          byte_count = byte_count + 1;
        end
      end else begin
        state = CRC;
        byte_count = 0;
        bit_count = 0;
      end
    end
    CRC: begin
      if (byte_count < ETH_CRC_SIZE/8) begin
        data_out = crc[byte_count*8 + bit_count];
        bit_count = bit_count + 1;
        if (bit_count == 8) begin
          bit_count = 0;
          byte_count = byte_count + 1;
        end
      end else begin
        state = TX;
        byte_count = 0;
        bit_count = 0;
      end
    end
    TX: begin
      data_out = 0;
      tx_en = 1;
      if (data_count < n+ETH_CRC_SIZE) begin
        data_count = data_count + 1;
      end else begin
        state = DONE;
        tx_en = 0;
        tx_done = 1;
      end
    end
    DONE: begin
      data_out = 0;
      tx_en = 0;
      tx_done = 0;
      state = IDLE;
    end
  endcase
end

endmodule

module ripple_carry_adder (
    input [31:0] A, // 32-bit input value A 
    input [31:0] B, // 32-bit input value B 
    output reg [32:0] sum // 33-bit output sum 
);

    reg carry = 1'b0; // Initialize carry to 0 

    // Full adder implementation 
    genvar i;
    generate
        for (i = 0; i < 32; i = i + 1) begin : full_adder
            assign sum[i] = A[i] ^ B[i] ^ carry;
            assign carry = (A[i] & B[i]) | (A[i] & carry) | (B[i] & carry);
        end
    endgenerate

    assign sum[32] = carry; // Set the MSB of the sum to the final carry bit 

endmodule

module sum_threshold (
    input [32:0] sum, // 33-bit input sum 
    output reg [15:0] sum_upper_lower, // 16-bit output sum of upper and lower 16-bit halves 
    output reg greater_than_threshold // 1-bit output indicating whether the sum is greater than the threshold 
);

    wire [15:0] upper_half = sum[31:16]; // Extract the upper 16 bits of the sum 
    wire [15:0] lower_half = sum[15:0]; // Extract the lower 16 bits of the sum 

    wire [15:0] sum_upper_lower_wire = upper_half + lower_half; // Add the upper and lower halves of the sum 

    assign sum_upper_lower = sum_upper_lower_wire; // Assign the sum of the upper and lower halves to the output 

    // Compare the sum of the upper and lower halves to the threshold value 
    always @(*) begin
        if (sum_upper_lower_wire > 16'd5000) begin
            greater_than_threshold = 1'b1;
        end else begin
            greater_than_threshold = 1'b0;
        end
    end

endmodule

module functional_module (
    input [32:0] sum, // 33-bit input sum from the ripple carry adder 
    input [15:0] sum_upper_lower, // 16-bit input sum of upper and lower halves from the sum threshold module 
    output reg [15:0] final_output // 16-bit final output 
);

    assign final_output = sum_upper_lower * sum[31:16]; // Multiply the sum of the upper and lower halves by the upper 16 bits of the sum 

endmodule

module top_module (
    input clk,
    input reset, // Synchronous active-high reset 
    input [31:0] A, // 32-bit input value for the ripple carry adder 
    input [31:0] B, // 32-bit input value for the ripple carry adder 
    output reg [15:0] final_output // 16-bit final output from the functional module 
);

    reg [32:0] sum; // 33-bit output sum from the ripple carry adder 
    reg [15:0] sum_upper_lower; // 16-bit output sum of upper and lower halves from the sum threshold module 
    reg greater_than_threshold; // 1-bit output indicating whether the sum is greater than the threshold 

    ripple_carry_adder rca(.A(A), .B(B), .sum(sum)); // Instantiate the ripple carry adder 
    sum_threshold st(.sum(sum), .sum_upper_lower(sum_upper_lower), .greater_than_threshold(greater_than_threshold)); // Instantiate the sum threshold module 
    functional_module fm(.sum(sum), .sum_upper_lower(sum_upper_lower), .final_output(final_output)); // Instantiate the functional module 

    always @(posedge clk) begin
        if (reset) begin
            sum <= 33'b0;
            sum_upper_lower <= 16'b0;
            greater_than_threshold <= 1'b0;
            final_output <= 16'b0;
        end else begin
            sum <= sum;
            sum_upper_lower <= sum_upper_lower;
            greater_than_threshold <= greater_than_threshold;
            final_output <= final_output;
        end
    end

endmodule

module top_module (
    input clk,
    input [15:0] A,
    input [3:0] B,
    input S,
    output [15:0] P
    );

    wire [15:0] logical_out;
    wire [15:0] arithmetic_out;

    logical_barrel_shifter logical_shifter(
        .D(A),
        .S(B),
        .Q(logical_out)
    );

    arithmetic_barrel_shifter arithmetic_shifter(
        .clk(clk),
        .A(A),
        .B(B),
        .P(arithmetic_out)
    );

    assign P = (S == 0) ? logical_out : arithmetic_out;

endmodule

module logical_barrel_shifter (
    input [15:0] D,
    input [3:0] S,
    output [15:0] Q
    );

    assign Q = (S[3] == 0) ? (D << S) : (D >> S);

endmodule

module arithmetic_barrel_shifter (
    input clk,
    input [15:0] A,
    input [3:0] B,
    output reg [15:0] P
    );

    always @(posedge clk) begin
        if (B[3] == 0) begin
            P <= (A << B);
        end else begin
            if (A[15] == 1) begin
                P <= {16{1'b1}} << (16 - B);
                P <= P | (A >> B);
            end else begin
                P <= A >> B;
            end
        end
    end

endmodule

module macc_simple_preacc (
    input  wire        clk,
    input  wire [ 7:0] A,
    input  wire [ 7:0] B,
    output wire [15:0] Z
);

    reg [15:0] acc;

    assign Z = acc + (A * B);

    always @(posedge clk)
        acc <= Z;

endmodule

module led_controller (
    input wire clk,          // clock input
    input wire ena,          // enable input
    output wire [1:0] leds   // LED output
);

    // 1-bit registers
    reg reg0 = 1'b1;
    reg reg1 = 1'b1;

    // update registers on positive edge of clock
    always @(posedge clk) begin
        reg0 <= 1'b1;
        reg1 <= 1'b1;
    end

    // connect registers to 2-bit LED wire
    // control with enable wire
    assign leds[0] = (ena) ? reg0 : 1'bz;
    assign leds[1] = (ena) ? reg1 : 1'bz;

endmodule

module up_down_counter (
    input UD,
    input CLK,
    input RST,
    input LD,
    input [3:0] load_value,
    output reg [3:0] Q
);

    always @(posedge CLK) begin
        if (RST) begin
            Q <= 4'b0000;
        end else if (LD) begin
            Q <= load_value;
        end else if (UD) begin
            Q <= Q + 4'b0001;
        end else begin
            Q <= Q - 4'b0001;
        end
    end

endmodule

module multiplexer_system (
    input [2:0] sel,
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output reg [3:0] out
);

reg [3:0] mux1_out;
reg [3:0] and_out;

// 6-to-1 multiplexer to select data input based on sel
always @*
begin
    case (sel)
        3'b000: mux1_out = data0;
        3'b001: mux1_out = data1;
        3'b010: mux1_out = data2;
        3'b011: mux1_out = data3;
        3'b100: mux1_out = data4;
        3'b101: mux1_out = data5;
        default: mux1_out = 4'b0;
    endcase
end

// Generate bitwise AND of two least significant bits of all data inputs
always @*
begin
    case (sel)
        3'b110: and_out = &{data5[1:0], data4[1:0], data3[1:0], data2[1:0], data1[1:0], data0[1:0]};
        3'b111: and_out = &{data5[1:0], data4[1:0], data3[1:0], data2[1:0], data1[1:0], data0[1:0]};
        default: and_out = 4'b0;
    endcase
end

// 6-to-1 multiplexer to select between mux1_out and and_out
always @*
begin
    case (sel)
        3'b110: out = and_out;
        3'b111: out = and_out;
        default: out = mux1_out;
    endcase
end

endmodule

module binary_multiplier (
    input [3:0] A,
    input [3:0] B,
    output reg [7:0] product
);

reg [3:0] shifted_B;
reg [3:0] i;

always @ (A or B) begin
    product <= 0;
    shifted_B <= B;
    for (i = 0; i < 4; i = i + 1) begin
        if (A[i] == 1) begin
            product <= product + (shifted_B << i);
        end
    end
end

endmodule

module top_module (
    input [1:0] A, B, // 2-bit binary value for the decoder input 
    input EN, // Active-high enable input for the decoder 
    input [3:0] data_in, // 4-bit data input for the barrel shifter 
    input [1:0] shift, // 2-bit shift input for the barrel shifter 
    output [7:0] final_output // 8-bit final output from the functional module 
);

// 4-to-16 Decoder with Active-Low Outputs
wire [15:0] decoder_out;
assign decoder_out = (EN) ? ~(1 << ((A << 1) | B)) : 16'b1111111111111111;
assign Y0 = decoder_out[0];
assign Y1 = decoder_out[1];
assign Y2 = decoder_out[2];
assign Y3 = decoder_out[3];
assign Y4 = decoder_out[4];
assign Y5 = decoder_out[5];
assign Y6 = decoder_out[6];
assign Y7 = decoder_out[7];
assign Y8 = decoder_out[8];
assign Y9 = decoder_out[9];
assign Y10 = decoder_out[10];
assign Y11 = decoder_out[11];
assign Y12 = decoder_out[12];
assign Y13 = decoder_out[13];
assign Y14 = decoder_out[14];
assign Y15 = decoder_out[15];

// 4-bit Barrel Shifter
wire [3:0] shifted_data;
assign shifted_data = (shift == 2'b00) ? data_in :
                      (shift == 2'b01) ? {data_in[2:0], 1'b0} :
                      (shift == 2'b10) ? {1'b0, data_in[3:1]} :
                      {2'b00, data_in[3:2]};

// Functional Module
assign final_output = shifted_data | decoder_out[3:0];

endmodule

module pipelined_module(
    input [49:0] in,
    output out_and,
    output out_or,
    output out_xor,
    output majority_out
);

reg [49:0] stage1_out;
reg [49:0] stage2_out;
reg [49:0] stage3_out;

assign out_and = stage3_out[0];
assign out_or = stage3_out[1];
assign out_xor = stage3_out[2];
assign majority_out = stage3_out[3];

// Pipeline stage 1
always @(*) begin
    stage1_out = in;
end

// Pipeline stage 2
always @(posedge clk) begin
    stage2_out = stage1_out;
end

// Pipeline stage 3
always @(posedge clk) begin
    stage3_out[0] = &stage2_out;
    stage3_out[1] = |stage2_out;
    stage3_out[2] = ^stage2_out;
    stage3_out[3] = (stage2_out[0] & stage2_out[1] & stage2_out[2]) |
                    (stage2_out[0] & stage2_out[1] & stage2_out[3]) |
                    (stage2_out[0] & stage2_out[2] & stage2_out[3]) |
                    (stage2_out[1] & stage2_out[2] & stage2_out[3]);
end

endmodule

module processor_tracer (
  input clk,
  input dbrk_traceoff,
  input dbrk_traceon,
  input [15:0] jdo,
  input jrst_n,
  input take_action_tracectrl,
  input xbrk_traceoff,
  input xbrk_traceon,
  input xbrk_wrap_traceoff,
  output reg [35:0] itm,
  output reg [15:0] trc_ctrl,
  output reg trc_on
);

  reg [10:0] trc_ctrl_reg;

  reg is_cond_dct;
  reg is_dct;
  reg dct_is_taken;
  reg is_idct;
  reg [31:0] retired_pcb;
  reg not_in_debug_mode;
  reg instr_retired;
  reg advanced_exc_occured;
  reg is_exception_no_break;
  reg is_external_interrupt;
  reg is_fast_tlb_miss_exception;
  reg [31:0] curr_pid;
  reg [31:0] exc_addr;
  reg [31:0] eic_addr;

  reg [1:0] dct_code;

  reg sync_timer_reached_zero;
  reg [6:0] sync_timer;
  reg [6:0] sync_timer_next;
  reg record_dct_outcome_in_sync;
  reg record_itrace;
  reg [6:0] sync_interval;
  reg [1:0] sync_code;

  always @(posedge clk or negedge jrst_n) begin
    if (jrst_n == 0) begin
      trc_ctrl_reg <= 11'b0;
    end else if (take_action_tracectrl) begin
      trc_ctrl_reg[0] <= jdo[5];
      trc_ctrl_reg[1] <= jdo[6];
      trc_ctrl_reg[3:2] <= jdo[8:7];
      trc_ctrl_reg[4] <= jdo[9];
      trc_ctrl_reg[9] <= jdo[14];
      trc_ctrl_reg[10] <= jdo[2];
      trc_ctrl_reg[7:5] <= 3'b000;
      trc_ctrl_reg[8] <= 1'b0;
    end else if (xbrk_wrap_traceoff) begin
      trc_ctrl_reg[1] <= 0;
      trc_ctrl_reg[0] <= 0;
    end else if (dbrk_traceoff | xbrk_traceoff) begin
      trc_ctrl_reg[1] <= 0;
    end else if (trc_ctrl_reg[0] & (dbrk_traceon | xbrk_traceon)) begin
      trc_ctrl_reg[1] <= 1;
    end
  end

  assign is_cond_dct = 1'b0;
  assign is_dct = 1'b0;
  assign dct_is_taken = 1'b0;
  assign is_idct = 1'b0;
  assign retired_pcb = 32'b0;
  assign not_in_debug_mode = 1'b0;
  assign instr_retired = 1'b0;
  assign advanced_exc_occured = 1'b0;
  assign is_exception_no_break = 1'b0;
  assign is_external_interrupt = 1'b0;
  assign is_fast_tlb_miss_exception = 1'b0;
  assign curr_pid = 32'b0;
  assign exc_addr = 32'b0;
  assign eic_addr = 32'b0;

  assign dct_code = {is_cond_dct, dct_is_taken};

  assign sync_code = trc_ctrl[3:2];
  assign sync_interval = {sync_code[1] & sync_code[0], 1'b0, sync_code[1] & ~sync_code[0], 1'b0, ~sync_code[1] & sync_code[0], 2'b00};
  assign sync_timer_reached_zero = sync_timer == 0;
  assign record_dct_outcome_in_sync = dct_is_taken & sync_timer_reached_zero;
  assign sync_timer_next = sync_timer_reached_zero ? sync_interval : (sync_timer - 1);
  assign record_itrace = trc_on & trc_ctrl[4];

  assign itm = 36'd0;
  assign trc_ctrl = trc_ctrl_reg;
  assign trc_on = trc_ctrl[1] & (trc_ctrl[9] | not_in_debug_mode);

endmodule

module digital_clock(
  input clk, reset, set_hours, set_minutes,
  output [3:0] hours, minutes
);
  reg [3:0] hours_reg = 4'b0000;
  reg [3:0] minutes_reg = 4'b0000;

  always @(posedge clk) begin
    if (reset) begin
      hours_reg <= 4'b0001;
      minutes_reg <= 4'b0000;
    end else begin
      if (set_hours) begin
        hours_reg <= (hours_reg == 4'b1011) ? 4'b0001 : hours_reg + 1;
      end
      if (set_minutes) begin
        minutes_reg <= (minutes_reg == 4'b1011) ? 4'b0000 : minutes_reg + 1;
      end
    end
  end

  assign hours = {hours_reg[3], hours_reg[2], hours_reg[1], hours_reg[0]};
  assign minutes = {minutes_reg[3], minutes_reg[2], minutes_reg[1], minutes_reg[0]};
endmodule

module shift_register (
