    input reset,            // Synchronous reset
    input [7:0] data_in,
    output [7:0] data_out
);

reg [7:0] shift_reg;

always @(posedge clk) begin
    if (reset) begin
        shift_reg <= 8'b0;
    end else begin
        shift_reg <= {shift_reg[6:0], data_in};
    end
end

assign data_out = shift_reg;

endmodule

module glitch_filter (
  input in,
  output out
);

parameter t = 4; // threshold value
parameter d = 2; // delay value
parameter b = 8; // output buffer size

reg [b-1:0] buffer;
reg [t-1:0] shift_reg;
reg [t-1:0] prev_input;

always @(posedge clk) begin
  shift_reg <= {shift_reg[t-2:0], in};
  prev_input <= shift_reg;

  if (in == prev_input) begin
    buffer <= {buffer[b-2:0], in};
  end else if (prev_input == {t{1'b1}}) begin
    buffer <= {buffer[b-2:0], 1'b1};
  end else if (prev_input == {t{1'b0}}) begin
    buffer <= {buffer[b-2:0], 1'b0};
  end else begin
    buffer <= {buffer[b-2:0], prev_input};
  end

  out <= buffer[d-1];
end

endmodule

module full_adder(
    input a,
    input b,
    input cin,
    output sum,
    output cout
);

    assign sum = a ^ b ^ cin;
    assign cout = (a & b) | (a & cin) | (b & cin);

