module traffic_light_controller(
    input button,
    input sensor,
    output reg red,
    output reg green
);

    localparam CYCLE_COUNT = 10; // Number of clock cycles for green state

    reg [3:0] count; // Counter for green state

    always @(posedge clk) begin
        if (sensor) begin
            // Sensor input is high, immediately transition to red state
            red <= 1;
            green <= 0;
            count <= 0;
        end else if (button) begin
            // Button input is high, transition to green state
            red <= 0;
            green <= 1;
            count <= 0;
        end else if (count < CYCLE_COUNT) begin
            // Continue in green state
            red <= 0;
            green <= 1;
            count <= count + 1;
        end else begin
            // Transition back to red state
            red <= 1;
            green <= 0;
            count <= 0;
        end
    end

endmodule

module top_solution(
	   input	  ice_clk_i,
	   output [7:0]   led_o,
	   output	  vs_o,
	   output	  hs_o,
	   output [3 : 0] red_o,
	   output [3 : 0] blue_o,
	   output [3 : 0] green_o
	   );

   parameter WIDTH = 8;

   wire			clk_25;
   reg [8 : 0]		ctr = 3;
   wire			vs_valid;
   wire			hs_valid;

   assign red_o = hs_valid & vs_valid ? pix[7 : 4] : 0;
   assign blue_o = hs_valid & vs_valid ? pix[3 : 0] : 0;
   assign green_o = hs_valid & vs_valid? 4'b1111 : 0;

   always @(posedge clk_25)
     begin
	ctr <= ctr + 1;
     end

   genvar i;
   generate
      for (i = 0; i < 8; i = i + 1)
	begin
	   assign led_o[i] = ctr[i + 18];
	end
   endgenerate

   clks#(
	 .PLL_EN(1),
	 .GBUFF_EN(1),
	 .DIVR(4'b0000),
	 .DIVF(7'b1000010),
	 .DIVQ(3'b101)
	 ) clks(
		.clk_i(ice_clk_i),
		.clk_o(clk_25)
		);

   vga vga(
	   .clk(clk_25),
	   .vs_o(vs_o),
	   .vs_valid(vs_valid),
