module top_module (
    input clk,
    input reset,     // Synchronous active-high reset
    input [15:0] A,
    input [15:0] B,
    input [3:0] a,
    input [3:0] b,
    output [15:0] SUM_16bit,
    output [7:0] SUM_functional
);

    // Instantiate the 16-bit adder module
    adder_16bit adder_16bit_inst (
        .clk(clk),
        .reset(reset),
        .A(A),
        .B(B),
        .CIN(CIN),
        .SUM(SUM_16bit),
        .COUT(COUT)
    );

    // Instantiate the 4-bit ripple carry adder module
    ripple_carry_adder ripple_carry_adder_inst (
        .clk(clk),
        .reset(reset),
        .a(a),
        .b(b),
        .CIN(CIN_4bit),
        .SUM(SUM_4bit),
        .COUT(COUT_4bit)
    );

    // Instantiate the functional module that adds the two SUM values
    functional_module functional_module_inst (
        .SUM_16bit(SUM_16bit),
        .SUM_4bit(SUM_4bit),
        .SUM_functional(SUM_functional)
    );

    // Connect the carry-out of the 16-bit adder to the carry-in of the 4-bit adder
    assign CIN_4bit = COUT;

    // Inputs to the 16-bit adder
    reg [15:0] A;
    reg [15:0] B;
    reg CIN;

    // Outputs from the 16-bit adder
    wire [15:0] SUM_16bit;
    wire COUT;

    // Inputs to the 4-bit adder
    reg [3:0] a;
    reg [3:0] b;
    reg CIN_4bit;

    // Outputs from the 4-bit adder
    wire [3:0] SUM_4bit;
    wire COUT_4bit;

    // Inputs to the functional module
    wire [15:0] SUM_16bit;
    wire [3:0] SUM_4bit;

    // Output from the functional module
    wire [7:0] SUM_functional;

endmodule

module bus_hold_block (
