  end

  assign out = out_reg;

endmodule

module DCT_block (
  input [N-1:0] in,
  input reset,
  input clk,
  output [N-1:0] out
);

  parameter Q = 16; // Q format notation
  parameter M = 1 << (Q-1); // maximum value of Q format notation

  reg signed [Q-1:0] x [0:N-1];
  reg signed [Q-1:0] c [0:N-1];

  integer i, j;

  always @(posedge clk) begin
    if (reset) begin
      for (i = 0; i < N; i = i + 1) begin
        x[i] <= 0;
        c[i] <= 0;
      end
    end else begin
      for (i = 0; i < N; i = i + 1) begin
        x[i] <= in[i] * M;
        c[i] <= 0;
        for (j = 0; j < N; j = j + 1) begin
          c[i] <= c[i] + x[j] * $cos((j + 0.5) * (i + 0.5) * $pi / N);
        end
        c[i] <= c[i] * $sqrt(2.0 / N);
      end
      for (i = 0; i < N; i = i + 1) begin
        out[i] <= c[i] / M;
      end
    end
  end

endmodule

module IDCT_block (
  input [N-1:0] in,
  input reset,
  input clk,
  output [N-1:0] out
);

  parameter Q = 16; // Q format notation
  parameter M = 1 << (Q-1); // maximum value of Q format notation

  reg signed [Q-1:0] c [0:N-1];
  reg signed [Q-1:0] x [0:N-1];

  integer i, j;

  always @(posedge clk) begin
    if (reset) begin
      for (i = 0; i < N; i = i + 1) begin
        c[i] <= 0;
        x[i] <= 0;
      end
    end else begin
      for (i = 0; i < N; i = i + 1) begin
        c[i] <= in[i] * M;
        x[i] <= 0;
        for (j = 0; j < N; j = j + 1) begin
          x[i] <= x[i] + c[j] * $cos((j + 0.5) * (i + 0.5) * $pi / N);
        end
        x[i] <= x[i] * $sqrt(2.0 / N);
      end
      for (i = 0; i < N; i = i + 1) begin
        out[i] <= x[i] / M;
      end
    end
  end

endmodule

module four_bit_adder (
	input [3:0] A,
	input [3:0] B,
	input Cin,
	output [3:0] S,
	output Cout
);

	wire [3:0] X;
	wire [3:0] Y;
	wire C1, C2, C3;

	NAND2X1 n1(.A(A[0]), .B(B[0]), .Y(X[0]));
	NAND2X1 n2(.A(X[0]), .B(Cin), .Y(Y[0]));
	NAND2X1 n3(.A(B[0]), .B(Cin), .Y(C1));

	NAND2X1 n4(.A(A[1]), .B(B[1]), .Y(X[1]));
	NAND2X1 n5(.A(X[1]), .B(C1), .Y(Y[1]));
	NAND2X1 n6(.A(B[1]), .B(C1), .Y(C2));

	NAND2X1 n7(.A(A[2]), .B(B[2]), .Y(X[2]));
	NAND2X1 n8(.A(X[2]), .B(C2), .Y(Y[2]));
	NAND2X1 n9(.A(B[2]), .B(C2), .Y(C3));

	NAND2X1 n10(.A(A[3]), .B(B[3]), .Y(X[3]));
	NAND2X1 n11(.A(X[3]), .B(C3), .Y(S[3]));
	NAND2X1 n12(.A(B[3]), .B(C3), .Y(Cout));

	assign S[2] = Y[2];
	assign S[1] = Y[1];
	assign S[0] = Y[0];
endmodule

module bidirectional_data_port (
  input clk,
  input reset,
  input [3:0] in,
  input dir,
  output reg [3:0] out,
  output reg [3:0] dout
);

  always @(posedge clk, negedge reset) begin
    if (!reset) begin
      out <= 4'b0;
      dout <= 4'b0;
    end else begin
      if (dir == 1) begin
        out <= {in[3], in[2], in[1], in[0]};
        dout <= {in[0], in[1], in[2], in[3]};
      end else begin
        out <= in;
      end
    end
  end

endmodule

module sample_msg_splitter
  #(
    parameter WDTH = 32
    )
   (
    input wire             clk,
    input wire             rst_n,
    input wire [WDTH-1:0]  in_data,
    input wire             in_nd,
    output wire [WDTH-1:0] out_samples,
    output wire            out_samples_nd,
    output wire [7:0]      out_msg,
    output wire            out_msg_nd,
    output wire            error
    );

   reg [WDTH-1:0]         before_data;
   reg [WDTH-1:0]         after_data;
   reg [WDTH-1:0]         before_samples_shifted;
   reg [WDTH-1:0]         after_samples_shifted;
   reg                    before_nd;
   reg                    after_nd;
   reg [7:0]              before_msg;
   reg                    before_msg_nd;
   reg [7:0]              after_msg;
   reg                    after_msg_nd;
   wire                    splitter_error;

   always @(posedge clk) begin
       if (rst_n == 1'b0) begin
           before_data <= 0;
           after_data <= 0;
           before_samples_shifted <= 0;
           after_samples_shifted <= 0;
           before_nd <= 0;
           after_nd <= 0;
           before_msg <= 0;
           before_msg_nd <= 0;
           after_msg <= 0;
           after_msg_nd <= 0;
           error <= 0;
           out_samples_nd <= 0;
           out_msg_nd <= 0;
       end else begin
           before_data <= in_data;
           before_nd <= in_nd;
           before_msg_nd <= in_nd;
           if (in_nd == 1'b1) begin
               if (in_data[WDTH-1] == 1'b1) begin
                   before_msg <= in_data[WDTH-2:WDTH-9];
                   after_msg_nd <= 1'b1;
                   after_msg <= before_msg;
               end else begin
                   before_samples_shifted <= {before_data[WDTH-3:WDTH/2-1], 1'b0, before_data[WDTH/2-2: 0], 1'b0};
                   after_samples_shifted <= before_samples_shifted;
                   after_nd <= 1'b1;
                   out_samples_nd <= 1'b1;
               end
           end
           if (splitter_error == 1'b1) begin
               error <= 1'b1;
           end
       end
   end

   assign out_samples = after_samples_shifted;
   assign out_msg = after_msg;
   assign out_msg_nd = after_msg_nd;

endmodule

module message_stream_combiner
  #(
    parameter N_INPUTS = 2,
    parameter N_OUTPUTS = 1,
    parameter WDTH = 32,
    parameter BUFFER_LENGTH = 16,
    parameter LOG_BUFFER_LENGTH = 4,
    parameter MAX_PACKET_LENGTH = 256,
    parameter MSG_LENGTH_WIDTH = 8
    )
   (
    input wire             clk,
    input wire             rst_n,
    input wire [N_INPUTS*WDTH-1:0]  in_data,
    input wire             in_nd,
    output wire [N_OUTPUTS*WDTH-1:0] out_data,
    output wire            out_nd,
    output wire            error
    );

   reg [N_INPUTS-1:0]      input_valid;
   reg [N_INPUTS-1:0]      input_done;
   reg [N_INPUTS-1:0]      input_nd;
   reg [N_INPUTS*WDTH-1:0]  input_data;
   reg [N_INPUTS-1:0]      input_data_nd;
   reg [WDTH-1:0]           output_buffer [BUFFER_LENGTH-1:0];
   reg [LOG_BUFFER_LENGTH-1:0] output_buffer_ptr;
   reg [WDTH-1:0]           current_packet [MAX_PACKET_LENGTH-1:0];
   reg [MSG_LENGTH_WIDTH-1:0] current_packet_length;
   reg                     current_packet_nd;
   reg                     output_nd;
   wire [N_INPUTS-1:0]      input_error;
   wire                     combiner_error;

   always @(posedge clk) begin
       if (rst_n == 1'b0) begin
           input_valid <= 0;
           input_done <= 0;
           input_nd <= 0;
           input_data <= 0;
           input_data_nd <= 0;
           output_buffer <= 0;
           output_buffer_ptr <= 0;
           current_packet <= 0;
           current_packet_length <= 0;
           current_packet_nd <= 0;
           output_nd <= 0;
           error <= 0;
           out_nd <= 0;
           for (i = 0; i < N_INPUTS; i = i + 1) begin
               input_error[i] <= 0;
           end
       end else begin
           for (i = 0; i < N_INPUTS; i = i + 1) begin
               if (input_done[i] == 0 && input_valid[i] == 1) begin
                   input_nd[i] <= in_nd;
                   input_data[WDTH*(i+1)-1:WDTH*i] <= in_data[WDTH*(i+1)-1:WDTH*i];
                   input_data_nd[i] <= in_nd;
                   if (in_nd == 1'b1) begin
                       if (input_data[WDTH*(i+1)-1] == 1'b1) begin
                           current_packet_length <= input_data[WDTH*(i+1)-2:WDTH*(i+1)-9];
                           current_packet_nd <= 1'b1;
                       end else begin
                           if (output_buffer_ptr < BUFFER_LENGTH) begin
                               output_buffer[output_buffer_ptr] <= input_data[WDTH*(i+1)-1:WDTH*i];
                               output_buffer_ptr <= output_buffer_ptr + 1;
                           end else begin
                               error <= 1'b1;
                               combiner_error <= 1'b1;
                           end
                       end
                   end
               end
               if (input_nd[i] == 1'b1) begin
                   input_done[i] <= 1'b1;
               end
               if (input_error[i] == 1'b1) begin
                   error <= 1'b1;
                   combiner_error <= 1'b1;
               end
           end
           if (current_packet_nd == 1'b1) begin
               if (current_packet_length > 0) begin
                   current_packet[current_packet_length-1:0] <= input_data[N_INPUTS*WDTH-1:WDTH*(N_INPUTS-1)];
                   current_packet_length <= current_packet_length - 1;
               end else begin
                   current_packet_nd <= 0;
                   if (output_buffer_ptr < BUFFER_LENGTH) begin
                       output_buffer[output_buffer_ptr] <= current_packet;
                       output_buffer_ptr <= output_buffer_ptr + 1;
                   end else begin
                       error <= 1'b1;
                       combiner_error <= 1'b1;
                   end
               end
           end
           if (output_buffer_ptr > 0) begin
               if (output_nd == 0) begin
                   out_nd <= 1'b1;
                   output_nd <= 1'b1;
               end else begin
                   out_nd <= 0;
                   output_nd <= 0;
                   out_data <= output_buffer[0];
                   for (i = 0; i < BUFFER_LENGTH-1; i = i + 1) begin
                       output_buffer[i] <= output_buffer[i+1];
                   end
                   output_buffer[BUFFER_LENGTH-1] <= 0;
                   output_buffer_ptr <= output_buffer_ptr - 1;
               end
           end
           if (combiner_error == 1'b1) begin
               error <= 1'b1;
           end
       end
   end

endmodule

