module jtag_memory_bridge #(
    parameter BASEADDR = 16'h0000,
    parameter HIGHADDR = 16'h0000,
    parameter ABUSWIDTH = 16,
    parameter MEM_BYTES = 2
) (
    input wire          BUS_CLK,
    input wire          BUS_RST,
    input wire  [ABUSWIDTH-1:0]  BUS_ADD,
    inout wire  [7:0]   BUS_DATA,
    input wire          BUS_RD,
    input wire          BUS_WR,

    input wire JTAG_CLK,

    output wire TCK,        // TCK
    input wire TDO,         // TDO
    output wire TDI,        // TDI
    output wire TMS,        // TMS

    output wire SEN,
    output wire SLD
);

reg [ABUSWIDTH-1:0] addr_reg;
reg [7:0] data_reg;
reg [1:0] state_reg;

localparam IDLE = 2'b00;
localparam READ = 2'b01;
localparam WRITE = 2'b10;

assign SLD = BUS_DATA;
assign BUS_DATA = (state_reg == READ) ? data_reg : 8'hzz;

always @(posedge BUS_CLK) begin
    if (BUS_RST) begin
        addr_reg <= 0;
        data_reg <= 0;
        state_reg <= IDLE;
    end else begin
        case (state_reg)
            IDLE: begin
                if (TDO && !TCK) begin
                    addr_reg <= BUS_ADD;
                    state_reg <= {TMS, READ};
                end else if (!TDO && !TCK) begin
                    addr_reg <= BUS_ADD;
                    data_reg <= BUS_DATA;
                    state_reg <= {TMS, WRITE};
                end
            end
            READ: begin
                if (TDO && !TCK) begin
                    data_reg <= IP_DATA_OUT;
                    state_reg <= IDLE;
                end
            end
            WRITE: begin
                if (!TDO && !TCK) begin
                    state_reg <= IDLE;
                end
            end
        endcase
    end
end

endmodule

