module vending_machine (
  input clk,
  input reset,
  input nickel,
  input dime,
  input quarter,
  output reg item_dispensed,
  output reg coin_returned
);

  // Define the states of the FSM
  parameter IDLE = 2'b00;
  parameter ACCEPT_COIN = 2'b01;
  parameter DISPENSE_ITEM = 2'b10;
  parameter RETURN_COIN = 2'b11;

  // Define the inputs and outputs of the FSM
  reg [1:0] state;
  reg [1:0] next_state;
  reg [1:0] change;
  reg [1:0] coins_inserted;

  // Define the constants for the coin values
  parameter NICKEL_VALUE = 2'b01;
  parameter DIME_VALUE = 2'b10;
  parameter QUARTER_VALUE = 2'b11;

  // Define the constants for the item price and coin return values
  parameter ITEM_PRICE = 2'b10;
  parameter NO_CHANGE = 2'b00;

  // Define the initial state of the FSM
  initial begin
    state = IDLE;
    item_dispensed = 1'b0;
    coin_returned = 1'b0;
  end

  // Define the next state logic
  always @ (posedge clk) begin
    if (reset) begin
      state <= IDLE;
      item_dispensed <= 1'b0;
      coin_returned <= 1'b0;
      coins_inserted <= 2'b00;
      change <= NO_CHANGE;
    end
    else begin
      state <= next_state;
      item_dispensed <= 1'b0;
      coin_returned <= 1'b0;
      coins_inserted <= {quarters_inserted, dimes_inserted, nickels_inserted};
      change <= coins_inserted - ITEM_PRICE;
    end
  end

  // Define the state transition logic
  always @ (*) begin
    case(state)
      IDLE: begin
        if (nickel) begin
          next_state = ACCEPT_COIN;
          coin_returned = 1'b0;
        end
        else if (dime) begin
          next_state = ACCEPT_COIN;
          coin_returned = 1'b0;
        end
        else if (quarter) begin
          next_state = ACCEPT_COIN;
          coin_returned = 1'b0;
        end
        else begin
          next_state = IDLE;
          coin_returned = 1'b0;
        end
      end

      ACCEPT_COIN: begin
        if (nickel) begin
          next_state = ACCEPT_COIN;
          coin_returned = 1'b0;
        end
        else if (dime) begin
          next_state = ACCEPT_COIN;
          coin_returned = 1'b0;
        end
        else if (quarter) begin
          next_state = DISPENSE_ITEM;
          item_dispensed = 1'b1;
          coin_returned = 1'b0;
        end
        else begin
          next_state = RETURN_COIN;
          coin_returned = 1'b1;
        end
      end

      DISPENSE_ITEM: begin
        next_state = IDLE;
        coin_returned = 1'b0;
      end

      RETURN_COIN: begin
        next_state = IDLE;
        coin_returned = 1'b1;
      end
    endcase
  end
endmodule

