module bin_to_bcd (
  input [3:0] bin,
  output [3:0] bcd
);

  // Define a lookup table for binary to decimal conversion
  // Each index represents a binary value, and the value at that index is its decimal equivalent
  reg [15:0] bin_to_dec = {4'd0, 4'd1, 4'd2, 4'd3, 4'd4, 4'd5, 4'd6, 4'd7, 4'd8, 4'd9};

  // Define a lookup table for decimal to BCD conversion
  // Each index represents a decimal value, and the value at that index is its BCD equivalent
  reg [15:0] dec_to_bcd = {4'd0, 4'd1, 4'd2, 4'd3, 4'd4, 4'd5, 4'd6, 4'd7, 4'd8, 4'd9, 4'd1, 4'd1, 4'd1, 4'd1, 4'd1, 4'd1};

  // Convert binary to decimal
  reg [3:0] dec;
  always @(*) begin
    dec = bin_to_dec[bin];
  end

  // Convert decimal to BCD
  always @(*) begin
    bcd[3] = dec_to_bcd[dec / 10];
    bcd[2] = dec_to_bcd[dec % 10];
    bcd[1] = 4'd0;
    bcd[0] = 4'd0;
  end

endmodule

