reg [7:0] divisor_reg;
reg [4:0] count;

always @(posedge clk) begin
    dividend_reg <= dividend;
    divisor_reg <= divisor;
    count <= 0;
    quotient <= 0;
    remainder <= 0;
    while (dividend_reg >= divisor_reg) begin
        dividend_reg <= dividend_reg - divisor_reg;
        count <= count + 1;
    end
    quotient <= count;
    remainder <= dividend_reg;
end

endmodule

