module nfc_transmitter (
  input [7:0] data,
  input clk,
  input rst,
  input en,
  output reg out,
  output reg tx_complete
);

  reg [7:0] shift_reg;
  reg [2:0] state;

  always @(posedge clk) begin
    if (rst) begin
      state <= 3'b000;
      shift_reg <= 8'b00000000;
      out <= 1'b0;
      tx_complete <= 1'b0;
    end else begin
      case (state)
        3'b000: begin // Idle state
          if (en) begin
            state <= 3'b001;
            shift_reg <= data;
          end
        end
        3'b001: begin // Transmitting state
          out <= shift_reg[0];
          shift_reg <= {shift_reg[6:0], 1'b0};
          if (shift_reg == 8'b00000000) begin
            state <= 3'b010;
          end
        end
        3'b010: begin // Transmission complete state
          out <= 1'b0;
          tx_complete <= 1'b1;
          state <= 3'b000;
        end
      endcase
    end
  end

endmodule

module nfc_receiver (
  input in,
  input clk,
  input rst,
  input en,
  output reg [7:0] data,
  output reg rx_complete
);

  reg [7:0] shift_reg;
  reg [2:0] state;

  always @(posedge clk) begin
    if (rst) begin
      state <= 3'b000;
      shift_reg <= 8'b00000000;
      data <= 8'b00000000;
      rx_complete <= 1'b0;
    end else begin
      case (state)
        3'b000: begin // Idle state
          if (en && in == 1'b1) begin
            state <= 3'b001;
          end
        end
        3'b001: begin // Receiving state
          shift_reg <= {shift_reg[6:0], in};
          if (shift_reg == 8'b11111111) begin
            state <= 3'b010;
          end
        end
        3'b010: begin // Reception complete state
          data <= shift_reg;
          rx_complete <= 1'b1;
          state <= 3'b000;
        end
      endcase
    end
  end

endmodule

module simple_system (
    input clk,
    output tx,
    input rx,
    input [3:0] sw,
    output [3:0] led
);

  wire clk_bufg;
  BUFG bufg (
      .I(clk),
      .O(clk_bufg)
  );

  reg [5:0] reset_cnt = 0;
  wire resetn = &reset_cnt;

  always @(posedge clk_bufg) begin
    reset_cnt <= reset_cnt + !resetn;
  end

  wire iomem_valid;
  reg iomem_ready;
  wire [3:0] iomem_wstrb;
  wire [31:0] iomem_addr;
  wire [31:0] iomem_wdata;
  reg [31:0] iomem_rdata;

  reg [31:0] gpio;

  assign led = gpio[3:0];

  always @(posedge clk_bufg) begin
    if (!resetn) begin
      gpio <= 0;
    end else begin
      iomem_ready <= 0;
      if (iomem_valid && !iomem_ready && iomem_addr[31:24] == 8'h03) begin
        iomem_ready <= 1;
        iomem_rdata <= {4{sw, gpio[3:0]}};
        if (iomem_wstrb[0]) gpio[7:0] <= iomem_wdata[7:0];
        if (iomem_wstrb[1]) gpio[15:8] <= iomem_wdata[15:8];
        if (iomem_wstrb[2]) gpio[23:16] <= iomem_wdata[23:16];
        if (iomem_wstrb[3]) gpio[31:24] <= iomem_wdata[31:24];
      end
    end
  end

  picosoc_noflash soc (
      .clk   (clk_bufg),
      .resetn(resetn),
      .ser_tx(tx),
      .ser_rx(rx),
      .irq_5(1'b0),
      .irq_6(1'b0),
      .irq_7(1'b0),
      .iomem_valid(iomem_valid),
      .iomem_ready(iomem_ready),
      .iomem_wstrb(iomem_wstrb),
      .iomem_addr (iomem_addr),
      .iomem_wdata(iomem_wdata),
      .iomem_rdata(iomem_rdata)
  );

endmodule

module adder_4bit (S, Cout, A, B, Cin);
    output [3:0] S;
    output Cout;
    input [3:0] A;
    input [3:0] B;
    input Cin;

    wire [3:0] c;

    // First half-adder
    ha ha1(S[0], c[1], A[0], B[0]);

    // Four full-adders
    fa fa1(S[1], c[2], A[1], B[1], c[1]);
    fa fa2(S[2], c[3], A[2], B[2], c[2]);
    fa fa3(S[3], c[4], A[3], B[3], c[3]);
    fa fa4(S[4], Cout, S[3], Cin, c[4]);

endmodule

module ha (S, C, A, B);
    output S;
    output C;
    input A;
    input B;

    assign S = A ^ B;
    assign C = A & B;

endmodule

module fa (S, Cout, A, B, Cin);
    output S;
    output Cout;
    input A;
    input B;
    input Cin;

    wire s1, c1, c2;

    ha h1(s1, c1, A, B);
    ha h2(S, c2, s1, Cin);
    assign Cout = c1 | c2;

endmodule

module omsp_clock_gate (
  input clk,           // Clock
  input enable,        // Clock enable
  input scan_enable,   // Scan enable (active during scan shifting)
  output gclk          // Gated clock
);

  wire enable_in = (enable | scan_enable);

  reg enable_latch;

  always @(posedge clk or posedge enable_in) begin
    if(enable_in) begin
      enable_latch <= enable;
    end
  end

  assign gclk = enable_latch & clk;

endmodule

module pipestage
  #(parameter TAGWIDTH = 1)
   (input clk,
    input reset,
    input stb_in,
    input stb_out,
    output reg valid,
    input [TAGWIDTH-1:0] tag_in,
    output reg [TAGWIDTH-1:0] tag_out);

   always @(posedge clk)
     if(reset)
       begin
	  valid <= 0;
	  tag_out <= 0;
       end
     else if(stb_in)
       begin
	  valid <= 1;
	  tag_out <= tag_in;
       end
     else if(stb_out)
       begin
	  valid <= 0;
	  tag_out <= 0;
       end

endmodule

module clock_management #(
    parameter CLKFX_MULTIPLY = 4,
    parameter CLKFX_DIVIDE = 1,
    parameter CLKDV_DIVIDE = 2,
    parameter CLKIN_PERIOD = 10,
    parameter CLK_FEEDBACK = 0,
    parameter CLKOUT_PHASE_SHIFT = 0,
    parameter CLKIN_DIVIDE_BY_2 = "FALSE",
    parameter DESKEW_ADJUST = "SYSTEM_SYNCHRONOUS",
    parameter DFS_FREQUENCY_MODE = "LOW",
    parameter DLL_FREQUENCY_MODE = "LOW",
    parameter DUTY_CYCLE_CORRECTION = "TRUE",
    parameter FACTORY_JF = 16'hC080,
    parameter PHASE_SHIFT = 0,
    parameter STARTUP_WAIT = "TRUE"
) (
    input wire CLKFB, CLKIN, DSSEN, PSCLK, PSEN, PSINCDEC, RST,
    output wire CLK0, CLK180, CLK270, CLK2X, CLK2X180, CLK90,
    output wire CLKDV, CLKFX, CLKFX180, LOCKED, PSDONE,
    output wire [7:0] STATUS
);

wire resetb = ~RST;
wire clk2x;
wire clk2x180;
wire clkfx;
wire clkfx180;
wire clk90;
wire locked;
wire psdone;

// Clock Divider for CLKDV
clock_divider_sim #(
    .DIVISOR(CLKDV_DIVIDE)
) i_clock_divisor_dv (
    .CLK(CLKIN),
    .CLOCK(CLKDV)
);

// Clock Multiplier for CLK2X
clock_multiplier #(
    .MULTIPLIER(2)
) i_clock_multiplier_two(
    .CLK(CLKIN),
    .CLOCK(clk2x)
);

// Inverted Clock Multiplier for CLK2X180
assign clk2x180 = ~clk2x;

// Clock Divider and Multiplier for CLKFX and CLKFX180
generate
    if (CLKFX_MULTIPLY==2 && CLKFX_DIVIDE==1) begin
        assign CLKFX = clk2x;
        assign CLKFX180 = ~clk2x;
    end else begin
        wire CLKINM;
        clock_multiplier #( .MULTIPLIER(CLKFX_MULTIPLY) ) i_clock_multiplier(.CLK(CLKIN),.CLOCK(CLKINM));
        clock_divider_sim #(.DIVISOR(CLKFX_DIVIDE)) i_clock_divisor_rx (.CLK(CLKINM), .CLOCK(clkfx));
        assign clkfx180 = ~clkfx;
    end
endgenerate

// Clock Inverter for CLK180
assign CLK180 = ~CLKIN;

// Clock Inverter for CLK270
assign CLK270 = ~CLK90;

// Clock Divider for CLK0
clock_divider_sim #(
    .DIVISOR(2)
) i_clock_divisor_0 (
    .CLK(CLKIN),
    .CLOCK(CLK0)
);

// Phase Shift Circuit for CLK90
wire [1:0] cnt_ps;
reg [1:0] cnt_ps_reg;
always @(posedge CLKIN or negedge resetb) begin
    if (!resetb) begin
        cnt_ps_reg <= 2'b0;
        cnt_ps <= 2'b0;
    end else begin
        cnt_ps_reg <= cnt_ps;
        cnt_ps <= cnt_ps + 1;
    end
end

always @(posedge PSCLK or negedge resetb) begin
    if (!resetb) begin
        clk90 <= 1'b0;
    end else begin
        if (PSEN) begin
            if (PSINCDEC) begin
                cnt_ps <= cnt_ps + 1;
            end else begin
                cnt_ps <= cnt_ps - 1;
            end
        end
        if (cnt_ps_reg[0] && !cnt_ps[0]) begin
            clk90 <= ~clk90;
        end
    end
end

assign CLK90 = clk90;

// Status Bits
assign STATUS[0] = locked;
assign STATUS[1] = psdone;
assign STATUS[2] = 1'b0; // Reserved
assign STATUS[3] = 1'b0; // Reserved
assign STATUS[4] = 1'b0; // Reserved
assign STATUS[5] = 1'b0; // Reserved
assign STATUS[6] = 1'b0; // Reserved
assign STATUS[7] = 1'b0; // Reserved

// Locked Signal
assign locked = 1'b1;

// PSDONE Signal
assign psdone = PSEN ? (cnt_ps == PHASE_SHIFT) : 1'b0;

endmodule

