module mux_dff (
    input wire D,
    input wire CLK,
    input wire DE,
    input wire SET,
    input wire RESET,
    output reg Q,
    output reg Q_N
);

    wire mux_out;
    assign mux_out = DE ? D : 1'b0;

    always @(posedge CLK) begin
        if (SET) begin
            Q <= 1'b1;
            Q_N <= 1'b0;
        end else if (RESET) begin
            Q <= 1'b0;
            Q_N <= 1'b1;
        end else begin
            Q <= mux_out;
            Q_N <= ~mux_out;
        end
    end

endmodule

module clock_generator (
    areset,
    inclk0,
    c0,
    c1,
    locked
);

input areset;
input inclk0;
output reg c0;
output reg c1;
output reg locked;

// Internal signals
reg [31:0] counter0 = 0;
reg [31:0] counter1 = 0;
reg locked_internal = 0;

// Divide the input clock to get the desired frequencies
parameter C0_DIVIDER = 5;
parameter C1_DIVIDER = 10;

// Counters to generate the output clocks
always @(posedge inclk0 or posedge areset) begin
    if (areset) begin
        counter0 <= 0;
        counter1 <= 0;
        locked_internal <= 0;
    end else begin
        counter0 <= counter0 + 1;
        counter1 <= counter1 + 1;
        if (counter0 == C0_DIVIDER - 1) begin
            counter0 <= 0;
            c0 <= ~c0;
        end
        if (counter1 == C1_DIVIDER - 1) begin
            counter1 <= 0;
            c1 <= ~c1;
        end
        if (counter0 == 0 && counter1 == 0) begin
            locked_internal <= 1;
        end
    end
end

// Output the locked signal
assign locked = locked_internal;

endmodule

module binary_search (
  input  wire        clk,
  input  wire        rst,
  input  wire  [31:0] arr [0:99],
  input  wire  [31:0] size,
  input  wire  [31:0] target,
  output reg   [31:0] index
);

reg [31:0] low, high, mid;

always @ (posedge clk, posedge rst)
if (rst) begin
  low <= 0;
  high <= size - 1;
  index <= -1;
end else begin
  if (low <= high) begin
    mid <= (low + high) / 2;
    if (arr[mid] == target) begin
      index <= mid;
    end else if (arr[mid] > target) begin
      high <= mid - 1;
    end else begin
      low <= mid + 1;
    end
  end
end

endmodule

