module counter (
    input clk,
    input reset,
    output done
);

    wire [15:0] addr = 16'h0000; // Address of the counter in RAM
    wire [15:0] next_val;
    wire [15:0] current_val;
    reg [15:0] count = 16'h0000;
    reg [1:0] state = 2'b00;

    // Instantiate the RAM module
    ram ram_inst (
        .clka(clk),
        .addra(addr),
        .dina(next_val),
        .wea(1'b1),
        .douta(current_val)
    );

    // State machine for the counter
    always @(posedge clk, posedge reset) begin
        if (reset) begin
            count <= 16'h0000;
            state <= 2'b00;
        end else begin
            case (state)
                2'b00: begin // Load current value from RAM
                    current_val <= 16'h0000;
                    state <= 2'b01;
                end
                2'b01: begin // Increment counter and store next value in RAM
                    next_val <= count + 1;
                    count <= next_val;
                    state <= 2'b10;
                end
                2'b10: begin // Read current value from RAM
                    current_val <= 16'h0000;
                    state <= 2'b11;
                end
                2'b11: begin // Check if counter has reached maximum value
                    if (count == 16'hFFFF) begin
                        count <= 16'h0000;
                        done <= 1'b1;
                        state <= 2'b00;
                    end else begin
                        done <= 1'b0;
                        state <= 2'b00;
                    end
                end
            endcase
        end
    end

endmodule

