module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    input C_in,
    output [3:0] S,
    output C_out
);

wire [3:0] sum;
wire [4:0] carry;

assign sum[0] = A[0] ^ B[0] ^ C_in;
assign carry[1] = (A[0] & B[0]) | (A[0] & C_in) | (B[0] & C_in);
assign sum[1] = A[1] ^ B[1] ^ carry[1];
assign carry[2] = (A[1] & B[1]) | (A[1] & carry[1]) | (B[1] & carry[1]);
assign sum[2] = A[2] ^ B[2] ^ carry[2];
assign carry[3] = (A[2] & B[2]) | (A[2] & carry[2]) | (B[2] & carry[2]);
assign sum[3] = A[3] ^ B[3] ^ carry[3];
assign C_out = carry[4];

assign S = sum;

endmodule

module my_module(
    input A,
    input B,
    input C,
    input D,
    input E,
    output reg X
);

    reg [31:0] T, T2;

    always @(*) begin
        if (A == 0) begin
            X = 0;
        end else begin
            T = B + C;
            if (T >= D) begin
                X = 1;
            end else begin
                T2 = E + T;
                if (T2 >= D) begin
                    X = 1;
                end else begin
                    X = 0;
                end
            end
        end
    end

endmodule

module clock_divider (
  input clk_in,
  input rst,
  input [7:0] divisor,
  output reg clk_out
);

  reg [7:0] counter;

  always @(posedge clk_in or negedge rst) begin
    if (~rst) begin
      clk_out <= 0;
      counter <= 0;
    end
    else begin
      counter <= counter + 1;
      if (counter == divisor) begin
        clk_out <= ~clk_out;
        counter <= 0;
      end
    end
  end

endmodule

module POR (
  input clk,
  input rst_in,
  input power_on,
  output reg rst_out
);

parameter rst_duration = 10; // number of clock cycles for reset duration

reg [3:0] rst_counter; // 4-bit counter for counting clock cycles
reg rst_state; // state of reset signal

always @(posedge clk) begin
  if (rst_in) begin // asynchronous reset
    rst_counter <= 0;
    rst_state <= 0;
  end
  else if (power_on && !clk) begin // power-on reset
    rst_counter <= 0;
    rst_state <= 1;
  end
  else begin // normal operation
    if (rst_counter < rst_duration) begin
      rst_counter <= rst_counter + 1;
      rst_state <= 1;
    end
    else begin
      rst_counter <= 0;
      rst_state <= 0;
    end
  end
end

assign rst_out = rst_state;

endmodule

module binary_counter (
  input clk,
  input reset,
  input enable,
  output [3:0] count
);

  reg [3:0] count_reg;

  always @(posedge clk) begin
    if (reset) begin
      count_reg <= 0;
    end else begin
      if (enable) begin
        if (count_reg == 4'b1111) begin
          count_reg <= 0;
        end else begin
          count_reg <= count_reg + 1;
        end
      end
    end
  end

  assign count = count_reg;

endmodule

module multiplier_block (
    i_data0,
    o_data0
);

  // Port mode declarations:
  input   [31:0] i_data0;
  output  [31:0] o_data0;

  //Multipliers:

  wire [31:0]
    w1,
    w4096,
    w4097,
    w16,
    w4081,
    w17,
    w1088,
    w2993,
    w11972,
    w14965,
    w29930;

  assign w1 = i_data0;
  assign w1088 = w17 << 6;
  assign w11972 = w2993 << 2;
  assign w14965 = w2993 + w11972;
  assign w16 = w1 << 4;
  assign w17 = w1 + w16;
  assign w2993 = w4081 - w1088;
