  wire [3:0] shifted_left;

  assign shifted_right = {data_in[3], data_in[3:1]};
  assign shifted_left = {data_in[2:0], data_in[0]};

  assign shifted_out = (shift_amt == 2'b00) ? data_in :
                      (shift_amt == 2'b01) ? shifted_left :
                      (shift_amt == 2'b10) ? shifted_right :
                      4'bxxxx;

