module VCO_interface (
  input Vin,
  input Range,
  output clk
);

parameter fmin = 1; // minimum frequency of the output clock
parameter fmax = 100; // maximum frequency of the output clock
parameter Vmin = 0; // minimum input voltage that corresponds to fmin
parameter Vmax = 1; // maximum input voltage that corresponds to fmax

reg [31:0] count = 0; // counter for generating the clock signal
reg clk_out = 0; // output clock signal

always @ (posedge clk_out) begin
  count <= count + 1; // increment the counter on each clock cycle
end

always @ (posedge clk_out or posedge Vin or posedge Range) begin
  // calculate the frequency of the output clock based on Vin and Range
  if (Vin < Vmin) begin
    clk_out <= 0;
  end else if (Vin > Vmax) begin
    clk_out <= 0;
  end else if (Range == 0) begin
    clk_out <= 0;
  end else if (Range == 1) begin
    clk_out <= (count == (fmax / Vin) - 1);
  end else if (Range == 2) begin
    clk_out <= (count == (fmax / Vin) / 2 - 1);
  end else if (Range == 3) begin
    clk_out <= (count == (fmax / Vin) / 4 - 1);
  end
end

assign clk = clk_out;

endmodule

module DECODER_testbench;

