module accumulator_shift_left (
  input clk,
  input rst_n,
  input [7:0] data_in,
  input select,
  input valid_a,
  input ready_b,
  output ready_a,
  output reg valid_b,
  output reg [31:0] data_out,
  output reg [7:0] shift_out,
  output reg led
);

  reg [7:0] accumulator;
  reg [99:0] shift_reg;
  reg [5:0] count;

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      accumulator <= 8'b0;
      shift_reg <= 100'b0;
      count <= 6'b0;
      valid_b <= 1'b0;
      data_out <= 32'b0;
      shift_out <= 8'b0;
      led <= 1'b0;
    end else begin
      if (valid_a && ready_b) begin
        if (select) begin
          shift_reg <= {shift_reg[98:0], data_in};
          shift_out <= shift_reg[99:92];
          data_out <= 32'b0;
          valid_b <= 1'b1;
          ready_a <= 1'b0;
          if (count == 6'b111111) begin
            led <= 1'b1;
            count <= 6'b0;
          end else begin
            count <= count + 1;
          end
        end else begin
          accumulator <= accumulator + data_in;
          data_out <= accumulator;
          shift_out <= 8'b0;
          valid_b <= 1'b1;
          ready_a <= 1'b0;
          if (count == 6'b111111) begin
            led <= 1'b1;
            count <= 6'b0;
          end else begin
            count <= count + 1;
          end
        end
      end else begin
        ready_a <= 1'b1;
        valid_b <= 1'b0;
      end
    end
  end

  assign ready_a = ~valid_a || ready_b;

endmodule

module password_checker (
  input [3:0] password,
  input clk,
  input reset,
  output reg out
);

  reg [2:0] shift_reg;
  wire [1:0] encoder_out;

  // 4-to-2 Encoder
  priority_encoder pe(
    .in({password[3], password[2], password[1], password[0]}),
    .out(encoder_out)
  );

  // 3-bit Shift Register
  always @(posedge clk) begin
    if (reset) begin
      shift_reg <= 3'b0;
    end else begin
      shift_reg <= {shift_reg[1:0], password[3]};
    end
  end

  // Password Checker
  always @(*) begin
    case (encoder_out)
      2'b00: out = (shift_reg[2] == 1'b0);
      2'b01: out = (shift_reg[1] == 1'b0);
      2'b10: out = (shift_reg[0] == 1'b0);
      2'b11: out = (password[3] == 1'b0);
    endcase
  end

endmodule

// 4-to-2 Priority Encoder
module priority_encoder (
  input [3:0] in,
  output reg [1:0] out
);

  always @(*) begin
    case (in)
      4'b0001: out = 2'b00;
      4'b0010: out = 2'b01;
      4'b0100: out = 2'b10;
      4'b1000: out = 2'b11;
      default: out = 2'b00;
    endcase
  end

endmodule

