module iq_correction (
  input clk,
  input valid,
  input [15:0] data_i,
  input [15:0] data_q,
  output valid_out,
  output [15:0] data_out,
  input iqcor_enable,
  input [15:0] iqcor_coeff_1,
  input [15:0] iqcor_coeff_2
);

  // select i/q if disabled
  parameter IQSEL = 0;

  // internal registers
  reg p1_valid = 'd0;
  reg [15:0] p1_data_i = 'd0;
  reg [15:0] p1_data_q = 'd0;
  reg p2_valid = 'd0;
  reg p2_sign_i = 'd0;
  reg p2_sign_q = 'd0;
  reg [14:0] p2_magn_i = 'd0;
  reg [14:0] p2_magn_q = 'd0;
  reg p3_valid = 'd0;
  reg [15:0] p3_data_i = 'd0;
  reg [15:0] p3_data_q = 'd0;
  reg p4_valid = 'd0;
  reg [15:0] p4_data = 'd0;
  reg valid_out = 'd0;
  reg [15:0] data_out = 'd0;

  // internal signals
  wire [15:0] p2_data_i_s;
  wire [15:0] p2_data_q_s;
  wire p3_valid_s;
  wire [31:0] p3_magn_i_s;
  wire p3_sign_i_s;
  wire [31:0] p3_magn_q_s;
  wire p3_sign_q_s;
  wire [15:0] p3_data_2s_i_p_s;
  wire [15:0] p3_data_2s_q_p_s;
  wire [15:0] p3_data_2s_i_n_s;
  wire [15:0] p3_data_2s_q_n_s;

  // apply offsets first
  always @(posedge clk) begin
    p1_valid <= valid;
    p1_data_i <= data_i;
    p1_data_q <= data_q;
  end

  // convert to sign-magnitude
  assign p2_data_i_s = ~p1_data_i + 1'b1;
  assign p2_data_q_s = ~p1_data_q + 1'b1;

  always @(posedge clk) begin
    p2_valid <= p1_valid;
    p2_sign_i <= p1_data_i[15] ^ iqcor_coeff_1[15];
    p2_sign_q <= p1_data_q[15] ^ iqcor_coeff_2[15];
    p2_magn_i <= (p1_data_i[15] == 1'b1) ? p2_data_i_s[14:0] : p1_data_i[14:0];
    p2_magn_q <= (p1_data_q[15] == 1'b1) ? p2_data_q_s[14:0] : p1_data_q[14:0];
  end

  // scaling functions - i
  mul_u16 #(.DELAY_DATA_WIDTH(2)) i_mul_u16_i (
    .clk (clk),
    .data_a ({1'b0, p2_magn_i}),
    .data_b ({1'b0, iqcor_coeff_1[14:0]}),
    .data_p (p3_magn_i_s),
    .ddata_in ({p2_valid, p2_sign_i}),
    .ddata_out ({p3_valid_s, p3_sign_i_s}));

  // scaling functions - q
  mul_u16 #(.DELAY_DATA_WIDTH(1)) i_mul_u16_q (
    .clk (clk),
    .data_a ({1'b0, p2_magn_q}),
    .data_b ({1'b0, iqcor_coeff_2[14:0]}),
    .data_p (p3_magn_q_s),
    .ddata_in (p2_sign_q),
    .ddata_out (p3_sign_q_s));

  // convert to 2s-complements
  assign p3_data_2s_i_p_s = {1'b0, p3_magn_i_s[28:14]};
  assign p3_data_2s_q_p_s = {1'b0, p3_magn_q_s[28:14]};
  assign p3_data_2s_i_n_s = ~p3_data_2s_i_p_s + 1'b1;
  assign p3_data_2s_q_n_s = ~p3_data_2s_q_p_s + 1'b1;

  always @(posedge clk) begin
    p3_valid <= p3_valid_s;
    p3_data_i <= (p3_sign_i_s == 1'b1) ? p3_data_2s_i_n_s : p3_data_2s_i_p_s;
    p3_data_q <= (p3_sign_q_s == 1'b1) ? p3_data_2s_q_n_s : p3_data_2s_q_p_s;
  end

  // corrected output is sum of two
  always @(posedge clk) begin
    p4_valid <= p3_valid;
    p4_data <= p3_data_i + p3_data_q;
  end

  // output registers
  always @(posedge clk) begin
    if (iqcor_enable == 1'b1) begin
      valid_out <= p4_valid;
      data_out <= p4_data;
    end else if (IQSEL == 1) begin
      valid_out <= valid;
      data_out <= data_q;
    end else begin
      valid_out <= valid;
      data_out <= data_i;
    end
  end

endmodule

module lvds2lcds (
	// avalon-bus
	input clk,
	input reset,
	input avs_slave_write,
	input avs_slave_read,
	input [7:0] avs_slave_writedata,
	output [7:0] avs_slave_readdata,
	// lvds2lcds
	output reset_n,
	output scl,
	output sdi,
	output sld
);

	// parameters
	parameter divider = 50;

	// regs / wires
	reg [8:0] clk_counter;
	reg div_clk;
	reg scl_en;
	reg [6:0] shift_buffer;
	reg shift_busy;
	reg [2:0] shift_counter;

	// ip
	assign reset_n = !reset;
	assign avs_slave_readdata = shift_busy;
	assign scl = scl_en ? div_clk : 1'b0;
	assign sld = (!scl_en && shift_busy) ? div_clk : 1'b0;
	assign sdi = shift_buffer[6];

	always @(posedge clk or posedge reset) begin
		if (reset) begin
			clk_counter <= 9'd1;
			div_clk <= 1'b0;
			scl_en <= 1'b0;
			shift_busy <= 1'b0;
			shift_counter <= 3'd0;
		end else begin // posedge clk
			if (shift_busy) begin
				if (clk_counter == (divider/2)) begin
					clk_counter <= 9'd1;
					div_clk <= !div_clk;
					if (div_clk) begin
						if (!scl_en) begin
							shift_busy <= 1'b0;
						end else begin
							if (shift_counter == 3'd6) begin
								scl_en <= 1'b0;
							end else begin
								shift_counter <= shift_counter + 3'd1;
								shift_buffer <= shift_buffer << 1;
							end
						end
					end
				end else begin
					clk_counter = clk_counter + 9'd1;
				end
			end else begin
				clk_counter <= 9'd1;
				shift_counter <= 3'd0;
				div_clk <= 1'b0;
				if (avs_slave_write) begin
					shift_buffer <= avs_slave_writedata[6:0];
					shift_busy <= 1'b1;
					scl_en <= 1'b1;
				end
			end
		end
	end

endmodule

