module pulse_generator(
  input wire clk,
  input wire in_trigger,
  input wire in_reset,
  input wire [7:0] pulse_duration,
  output wire out_pulse
);

  reg [7:0] counter;
  reg pulse_on;

  always @(posedge clk) begin
    if (in_reset) begin
      counter <= 0;
      pulse_on <= 0;
      out_pulse <= 0;
    end else begin
      if (in_trigger) begin
        counter <= pulse_duration;
        pulse_on <= 1;
        out_pulse <= 1;
      end else if (counter > 0) begin
        counter <= counter - 1;
        out_pulse <= pulse_on;
      end else begin
        pulse_on <= 0;
        out_pulse <= 0;
      end
    end
  end

endmodule

module edge_detection (
  input clk,
  input reset, // Synchronous active-high reset
  input [15:0] in, // 16-bit input for edge detection
  output reg rise, // Output for rising edge detection
  output reg fall, // Output for falling edge detection
  output reg rise_fall // Output for both edge detection
);

  reg [15:0] prev_in; // Register to store previous input value

  always @(posedge clk) begin
    if (reset) begin
      rise <= 1'b0;
      fall <= 1'b0;
      rise_fall <= 1'b0;
      prev_in <= 16'b0;
    end else begin
      // Rising edge detection
      rise <= (in ^ prev_in) & in;
      // Falling edge detection
      fall <= (~in ^ prev_in) & prev_in;
      // Both edge detection
      rise_fall <= rise & fall;
      prev_in <= in;
    end
  end

endmodule

module signal_state (
  input rise, // Input for rising edge detection
  input fall, // Input for falling edge detection
  input rise_fall, // Input for both edge detection
  output reg [2:0] state // 3-bit output representing signal state
);

  always @(*) begin
    case ({rise, fall, rise_fall})
      3'b000: state = 3'b000; // Low
      3'b001: state = 3'b001; // Rising
      3'b010: state = 3'b010; // Falling
      3'b011: state = 3'b011; // Both rising and falling
      3'b100: state = 3'b100; // Both rising and low
      3'b101: state = 3'b101; // Both falling and low
      3'b110: state = 3'b110; // High
      3'b111: state = 3'b111; // Both rising and falling and high
    endcase
  end

endmodule

module simple_calculator(
    input clk,
    input reset,
    input [3:0] operand1,
    input [3:0] operand2,
    input operation,
    output [3:0] result,
    output overflow
);

    reg [4:0] temp_result; // to detect overflow

    always @(posedge clk) begin
        if (reset) begin
            result <= 4'b0;
            overflow <= 1'b0;
        end else begin
            if (operation == 0) begin
                temp_result <= operand1 + operand2;
            end else begin
                temp_result <= operand1 - operand2;
            end
            if (temp_result > 4'b1111 || temp_result < 4'b0000) begin
                overflow <= 1'b1;
            end else begin
                overflow <= 1'b0;
            end
            result <= temp_result[3:0];
        end
    end

endmodule

module barrel_shifter (
  input clk,
  input reset,
  input [15:0] data,
  input [3:0] shift_amount,
  input mode, // 0 for logical shift, 1 for arithmetic shift
  output [15:0] shifted_output,
  output carry
);

  reg signed [15:0] signed_data;
  reg signed [15:0] signed_shifted_output;
  reg [15:0] logical_shifted_output;
  reg [15:0] arithmetic_shifted_output;
  reg [3:0] shift_counter;
  reg [3:0] shift_amount_abs;
  reg shift_direction;
  reg sign_bit;

  always @(posedge clk) begin
    if (reset) begin
      signed_data <= 16'd0;
      signed_shifted_output <= 16'd0;
      logical_shifted_output <= 16'd0;
      arithmetic_shifted_output <= 16'd0;
      shift_counter <= 4'd0;
      shift_amount_abs <= 4'd0;
      shift_direction <= 1'b0;
      sign_bit <= 1'b0;
      carry <= 1'b0;
    end else begin
      signed_data <= data;
      shift_amount_abs <= shift_amount;
      shift_direction <= shift_amount[3];
      sign_bit <= signed_data[15];

      if (mode == 0) begin // logical shift
        if (shift_direction == 1'b0) begin // shift left
          logical_shifted_output <= data << shift_amount_abs;
          shifted_output <= logical_shifted_output;
          carry <= logical_shifted_output[15];
        end else begin // shift right
          logical_shifted_output <= data >> shift_amount_abs;
          shifted_output <= logical_shifted_output;
          carry <= logical_shifted_output[0];
        end
      end else begin // arithmetic shift
        if (shift_direction == 1'b0) begin // shift left
          arithmetic_shifted_output <= data << shift_amount_abs;
          shifted_output <= arithmetic_shifted_output;
          carry <= arithmetic_shifted_output[15];
        end else begin // shift right
          for (shift_counter = 0; shift_counter < shift_amount_abs; shift_counter = shift_counter + 1) begin
            arithmetic_shifted_output <= {sign_bit, arithmetic_shifted_output[15:1]};
          end
          shifted_output <= arithmetic_shifted_output;
          carry <= arithmetic_shifted_output[0];
        end
      end

      signed_shifted_output <= shifted_output;
    end
  end

endmodule

