module mytop (a, b, clk, z);

   input clk;
   input [7:0] a, b;
   output [7:0] z;

   wire [7:0] xor_result, or_result, and_result;

   assign xor_result = a ^ b;
   assign or_result = a | b;
   assign and_result = a & b;

   reg [2:0] state;
   always @(posedge clk) begin
      case (state)
         0: begin
            a <= 8'h07;
            b <= 8'h20;
            state <= 1;
         end
         1: begin
            a <= 8'h8a;
            b <= 8'h12;
            state <= 2;
         end
         2: begin
            z <= xor_result;
            if (z !== 8'hdf) $stop;
            state <= 3;
         end
         3: begin
            z <= or_result;
            if (z !== 8'hed) $stop;
            state <= 4;
         end
         4: begin
            z <= and_result;
            if (z !== 8'h4d) $stop;
            state <= 5;
         end
         5: begin
            $write("*-* All Finished *-*\n");
            $finish;
         end
      endcase
   end

endmodule

module ripple_carry_adder (
  input [3:0] a, b,
  input cin,
  output [3:0] sum,
  output cout
);

  wire [3:0] c;

  assign c[0] = cin;
  assign c[1] = (a[0] & b[0]) | (a[0] & cin) | (b[0] & cin);
  assign c[2] = (a[1] & b[1]) | (a[1] & c[1]) | (b[1] & c[1]);
  assign c[3] = (a[2] & b[2]) | (a[2] & c[2]) | (b[2] & c[2]);

  assign sum = a + b + cin;
  assign cout = c[3];

endmodule

