module uart_wb(
    input clk,
    input wb_rst_i,
    input [7:0] wb_dat_i,
    output [7:0] wb_dat_o,
    input [3:0] wb_sel_i,
    output reg [31:0] wb_dat32_o,
    input wb_we_i,
    input wb_stb_i,
    input wb_cyc_i,
    output wb_ack_o,
    input [31:0] wb_adr_i,
    output reg [31:0] wb_adr_int,
    output reg we_o,
    output reg re_o,
    output stx_pad_o,
    input srx_pad_i,
    output int_o
);

// UART interface
wire [7:0] uart_data;
wire uart_txe;
wire uart_rxe;
wire uart_int;

uart #(.DATA_BUS_WIDTH(8)) uart_inst(
    .clk(clk),
    .rst(wb_rst_i),
    .data(uart_data),
    .txe(uart_txe),
    .rxe(uart_rxe),
    .int(uart_int)
);

// Wishbone interface
reg [7:0] wb_data_reg;
reg [31:0] wb_addr_reg;

always @(posedge clk) begin
    if (wb_rst_i) begin
        wb_data_reg <= 8'b0;
        wb_addr_reg <= 32'b0;
    end else if (wb_cyc_i && wb_stb_i) begin
        if (wb_we_i) begin
            case (wb_sel_i)
                4'b0001: wb_data_reg[7:0] <= wb_dat_i;
                4'b0010: wb_data_reg[15:8] <= wb_dat_i;
                4'b0100: wb_data_reg[23:16] <= wb_dat_i;
                4'b1000: wb_data_reg[31:24] <= wb_dat_i;
                default: wb_data_reg <= wb_dat_i;
            endcase
            wb_addr_reg <= wb_adr_i;
        end else if (wb_re_i) begin
            case (wb_sel_i)
                4'b0001: wb_dat_o <= wb_data_reg[7:0];
                4'b0010: wb_dat_o <= wb_data_reg[15:8];
                4'b0100: wb_dat_o <= wb_data_reg[23:16];
                4'b1000: wb_dat_o <= wb_data_reg[31:24];
                default: wb_dat_o <= wb_data_reg;
            endcase
            wb_ack_o <= 1'b1;
        end else begin
            wb_ack_o <= 1'b0;
        end
    end
end

// Address decoding for UART control signals
always @(posedge clk) begin
    if (wb_rst_i) begin
        wb_adr_int <= 32'b0;
        we_o <= 1'b0;
        re_o <= 1'b0;
        stx_pad_o <= 1'b0;
        int_o <= 1'b0;
    end else if (wb_cyc_i && wb_stb_i && !wb_we_i) begin
        case (wb_adr_i[7:2])
            6'b000000: begin // UART data register
                wb_dat32_o <= {24'b0, uart_data};
                re_o <= 1'b1;
            end
            6'b000001: begin // UART control register
                wb_dat32_o <= 32'b0;
                case (wb_adr_i[1:0])
                    2'b00: begin // Transmit enable
                        wb_dat32_o[0] <= uart_txe;
                        we_o <= 1'b1;
                        stx_pad_o <= wb_dat_i[0];
                    end
                    2'b01: begin // Receive enable
                        wb_dat32_o[0] <= uart_rxe;
                        we_o <= 1'b1;
                    end
                    2'b10: begin // Interrupt enable
                        wb_dat32_o[0] <= uart_int;
                        we_o <= 1'b1;
                        int_o <= wb_dat_i[0];
                    end
                    default: we_o <= 1'b0;
                endcase
            end
            default: we_o <= 1'b0;
        endcase
        wb_adr_int <= wb_adr_i;
    end
end

endmodule

