endmodule

module rotator(input clk, input load, input [1:0] ena, input [99:0] data, output [99:0] q);
    reg [99:0] reg_data;
    always @(posedge clk) begin
        if (load) begin
            reg_data <= data;
        end else begin
            if (ena == 2'b00) begin
                reg_data <= {reg_data[98:0], reg_data[99]};
            end else if (ena == 2'b01) begin
                reg_data <= {reg_data[99], reg_data[98:0]};
            end
        end
    end
    assign q = reg_data;
endmodule

module control_logic(input [2:0] sel, output [99:0] shift_out, output [99:0] rot_out);
    wire [99:0] shift_reg_out;
    wire [99:0] rotator_out;
    my_dff dff1(.clk(clk), .d(sel[0]), .q(shift_reg_out[0]));
    my_dff dff2(.clk(clk), .d(shift_reg_out[0]), .q(shift_reg_out[1]));
    my_dff dff3(.clk(clk), .d(shift_reg_out[1]), .q(shift_reg_out[2]));
    rotator rot(.clk(clk), .load(load), .ena(ena), .data(data), .q(rotator_out));
    assign shift_out = {shift_reg_out[2], shift_reg_out[1], shift_reg_out[0]};
    assign rot_out = rotator_out;
endmodule

module functional_module(input clk, input [99:0] rot_out, input [99:0] shift_out, input [2:0] sel, output [99:0] q);
    wire [99:0] control_logic_shift_out;
    wire [99:0] control_logic_rot_out;
    control_logic ctrl(.clk(clk), .sel(sel), .shift_out(control_logic_shift_out), .rot_out(control_logic_rot_out));
    assign q = rot_out | (sel == 3'b000 ? control_logic_shift_out : control_logic_rot_out);
endmodule

