module address(
  input CLK,
  input [7:0] featurebits,  // peripheral enable/disable
  input [2:0] MAPPER,       // MCU detected mapper
  input [23:0] SNES_ADDR,   // requested address from SNES
  input [7:0] SNES_PA,      // peripheral address from SNES
  output [23:0] ROM_ADDR,   // Address to request from SRAM0
  output ROM_HIT,           // enable SRAM0
  output IS_SAVERAM,        // address/CS mapped as SRAM?
  output IS_ROM,            // address mapped as ROM?
  output IS_WRITABLE,       // address somehow mapped as writable area?
  input [23:0] SAVERAM_MASK,
  input [23:0] ROM_MASK,
  output msu_enable,
  output r213f_enable,
  output snescmd_enable,
  output nmicmd_enable,
  output return_vector_enable,
  output branch1_enable,
  output branch2_enable,
  output obc1_enable
);

parameter [2:0]
  FEAT_MSU1 = 3,
  FEAT_213F = 4
;

wire [23:0] SRAM_SNES_ADDR;

/* currently supported mappers:
   Index     Mapper
      000      HiROM
      001      LoROM
      010      ExHiROM (48-64Mbit)
*/

/* HiROM:   SRAM @ Bank 0x30-0x3f, 0xb0-0xbf
            Offset 6000-7fff */

assign IS_ROM = ((!SNES_ADDR[22] & SNES_ADDR[15])
                 |(SNES_ADDR[22]));

assign IS_SAVERAM = SAVERAM_MASK[0]
                    &(((MAPPER == 3'b000
                     || MAPPER == 3'b010)
                      ? (!SNES_ADDR[22]
                         & SNES_ADDR[21]
                         & &SNES_ADDR[14:13]
                         & !SNES_ADDR[15]
                        )
/*  LoROM:   SRAM @ Bank 0x70-0x7d, 0xf0-0xfd
 *  Offset 0000-7fff for ROM >= 32 MBit, otherwise 0000-ffff */
                      :(MAPPER == 3'b001)
                      ? (&SNES_ADDR[22:20]
                         & (SNES_ADDR[19:16] < 4'b1110)
                         & (~SNES_ADDR[15] | ~ROM_MASK[21])
                        )
                      : 1'b0));

assign IS_WRITABLE = IS_SAVERAM;

assign SRAM_SNES_ADDR = ((MAPPER == 3'b000)
                          ?(IS_SAVERAM
                            ? 24'hE00000 + ({SNES_ADDR[20:16], SNES_ADDR[12:0]}
                                            & SAVERAM_MASK)
                            : ({1'b0, SNES_ADDR[22:0]} & ROM_MASK))

                        :(MAPPER == 3'b001)
                          ?(IS_SAVERAM
                            ? 24'hE00000 + ({SNES_ADDR[20:16], SNES_ADDR[14:0]}
                                            & SAVERAM_MASK)
                            : ({2'b00, SNES_ADDR[22:16], SNES_ADDR[14:0]}
                               & ROM_MASK))

                        :(MAPPER == 3'b010)
                          ?(IS_SAVERAM
                            ? 24'hE00000 + ({SNES_ADDR[20:16], SNES_ADDR[12:0]}
                                            & SAVERAM_MASK)
                            : ({1'b0, !SNES_ADDR[23], SNES_ADDR[21:0]}
                               & ROM_MASK))
                        : 24'b0);

assign ROM_ADDR = SRAM_SNES_ADDR;

assign ROM_SEL = 1'b0;

assign ROM_HIT = IS_ROM | IS_WRITABLE;

assign msu_enable = featurebits[FEAT_MSU1] & (!SNES_ADDR[22] && ((SNES_ADDR[15:0] & 16'hfff8) == 16'h2000));
assign r213f_enable = featurebits[FEAT_213F] & (SNES_PA == 8'h3f);
assign obc1_enable = (~SNES_ADDR[22]) & (SNES_ADDR[15:11] == 5'b01111);
assign snescmd_enable = ({SNES_ADDR[22], SNES_ADDR[15:9]} == 8'b0_0010101);
assign nmicmd_enable = (SNES_ADDR == 24'h002BF2);
assign return_vector_enable = (SNES_ADDR == 24'h002A5A);
assign branch1_enable = (SNES_ADDR == 24'h002A13);
assign branch2_enable = (SNES_ADDR == 24'h002A4D);
endmodule

module top_module (
    input clk,
    input reset,
    input [7:0] in,
    input [1:0] shift_amount,
    input mode,
    output [7:0] out
);

    wire [2:0] priority_encoder_out;
    wire [3:0] barrel_shifter_out;
    wire [7:0] or_out;

    priority_encoder pe(
        .in7(in[7]),
        .in6(in[6]),
        .in5(in[5]),
        .in4(in[4]),
        .in3(in[3]),
        .in2(in[2]),
        .in1(in[1]),
        .in0(in[0]),
        .out2(priority_encoder_out[2]),
        .out1(priority_encoder_out[1]),
        .out0(priority_encoder_out[0])
    );

    barrel_shifter bs(
        .data(in[3:0]),
        .shift_amount(shift_amount),
        .mode(mode),
        .out(barrel_shifter_out)
    );

    assign or_out = priority_encoder_out | barrel_shifter_out;

    assign out = or_out;

endmodule

module audio_and_video_config (
    // Inputs
    clk,
    reset,

    // Bidirectionals
    I2C_SDAT,
    I2C_SCLK
);

/*************************************************************************
 *                           Parameter Declarations                      *
 *************************************************************************/

parameter I2C_BUS_MODE           = 1'b0;
parameter CFG_TYPE              = 8'h01;

parameter MIN_ROM_ADDRESS       = 6'h00;
parameter MAX_ROM_ADDRESS       = 6'h32;

parameter AUD_LINE_IN_LC        = 9'h01A;
parameter AUD_LINE_IN_RC        = 9'h01A;
parameter AUD_LINE_OUT_LC       = 9'h07B;
parameter AUD_LINE_OUT_RC       = 9'h07B;
parameter AUD_ADC_PATH          = 9'd149;
parameter AUD_DAC_PATH          = 9'h006;
parameter AUD_POWER             = 9'h000;
parameter AUD_DATA_FORMAT       = 9'd73;
parameter AUD_SAMPLE_CTRL       = 9'd0;
parameter AUD_SET_ACTIVE        = 9'h001;

/*************************************************************************
 *                             Port Declarations                        *
 *************************************************************************/
// Inputs
input               clk;
input               reset;

// Bidirectionals
inout               I2C_SDAT;                   //  I2C Data
output              I2C_SCLK;                   //  I2C Clock

/*************************************************************************
 *                           Constant Declarations                       *
 *************************************************************************/

localparam I2C_ADDR_WR    = 7'b1010000;   // I2C write address
localparam I2C_ADDR_RD    = 7'b1010001;   // I2C read address
localparam I2C_ACK        = 1'b0;         // I2C acknowledge bit
localparam I2C_NACK       = 1'b1;         // I2C not-acknowledge bit
localparam I2C_START      = 1'b1;         // I2C start bit
localparam I2C_STOP       = 1'b1;         // I2C stop bit

/*************************************************************************
 *                 Internal wires and registers Declarations             *
 *************************************************************************/

reg [7:0] data_out;
reg [2:0] num_bits_out;
reg [7:0] data_in;
reg [2:0] num_bits_in;
reg [6:0] i2c_addr;
reg       i2c_rw;
reg       i2c_start;
reg       i2c_stop;
reg       i2c_ack;
reg       i2c_busy;
reg       i2c_error;
reg       i2c_complete;

wire      i2c_sclk;
wire      i2c_sdat;

/*************************************************************************
 *                         Finite State Machine(s)                       *
 *************************************************************************/

localparam S_IDLE           = 3'd0;
localparam S_START          = 3'd1;
localparam S_ADDR           = 3'd2;
localparam S_ADDR_ACK       = 3'd3;
localparam S_DATA_OUT       = 3'd4;
localparam S_DATA_OUT_ACK   = 3'd5;
localparam S_RESTART        = 3'd6;
localparam S_DATA_IN        = 3'd7;
localparam S_DATA_IN_ACK    = 3'd8;
localparam S_STOP           = 3'd9;
localparam S_ERROR          = 3'd10;

reg [2:0] state;

always @(posedge clk) begin
    if (reset) begin
        state <= S_IDLE;
        i2c_addr <= 7'b0;
        i2c_rw <= 1'b0;
        i2c_start <= 1'b0;
        i2c_stop <= 1'b0;
        i2c_ack <= 1'b0;
        i2c_busy <= 1'b0;
        i2c_error <= 1'b0;
        i2c_complete <= 1'b0;
        data_out <= 8'h00;
        num_bits_out <= 3'h0;
        data_in <= 8'h00;
        num_bits_in <= 3'h0;
    end else begin
        case (state)
            S_IDLE: begin
                if (i2c_complete) begin
                    state <= S_START;
                end
            end
            S_START: begin
                i2c_start <= 1'b1;
                i2c_addr <= I2C_ADDR_WR;
                state <= S_ADDR;
            end
            S_ADDR: begin
                i2c_sdat <= i2c_addr[6];
                i2c_addr <= {i2c_addr[5:0], i2c_rw};
                state <= S_ADDR_ACK;
            end
            S_ADDR_ACK: begin
                if (i2c_ack) begin
                    state <= S_DATA_OUT;
                end
            end
            S_DATA_OUT: begin
                i2c_sdat <= data_out[num_bits_out];
                num_bits_out <= num_bits_out - 1;
                if (num_bits_out == 3'h0) begin
                    state <= S_DATA_OUT_ACK;
                end
            end
            S_DATA_OUT_ACK: begin
                if (i2c_ack) begin
                    if (num_bits_in > 3'h0) begin
                        state <= S_RESTART;
                    end else begin
                        state <= S_STOP;
                    end
                end
            end
            S_RESTART: begin
                i2c_start <= 1'b1;
                i2c_addr <= I2C_ADDR_RD;
                i2c_rw <= 1'b1;
                state <= S_DATA_IN;
            end
            S_DATA_IN: begin
                i2c_sdat <= 1'b1;
                num_bits_in <= num_bits_in - 1;
                if (num_bits_in == 3'h0) begin
                    state <= S_STOP;
                end
            end
            S_DATA_IN_ACK: begin
                if (i2c_ack) begin
                    if (num_bits_in > 3'h0) begin
                        state <= S_DATA_IN;
                    end else begin
                        state <= S_STOP;
                    end
                end
            end
            S_STOP: begin
                i2c_stop <= 1'b1;
                state <= S_IDLE;
                i2c_complete <= 1'b1;
            end
            S_ERROR: begin
                i2c_error <= 1'b1;
                state <= S_IDLE;
            end
            default: begin
                state <= S_ERROR;
            end
        endcase
    end
end

/*************************************************************************
 *                            Combinational logic                         *
 *************************************************************************/

assign i2c_sclk = clk;
assign I2C_SCLK = i2c_sclk;
assign I2C_SDAT = i2c_sdat;

/*************************************************************************
 *                              Internal Modules                          *
 *************************************************************************/

endmodule

module nios_system_switches (
                              // inputs:
                               address,
                               clk,
                               in_port,
                               reset_n,

                              // outputs:
                               readdata
                            )
;

  output  [ 31: 0] readdata;
  input   [  1: 0] address;
  input            clk;
  input   [  9: 0] in_port;
  input            reset_n;

  wire             clk_en;
  wire    [  9: 0] data_in;
  wire    [  9: 0] read_mux_out;
  reg     [ 31: 0] readdata;
  reg     [  9: 0] reg1;
  reg     [  9: 0] reg2;
  assign clk_en = 1;

  always @(posedge clk or negedge reset_n)
    begin
      if (reset_n == 0)
          begin
            readdata <= 0;
            reg1 <= 0;
            reg2 <= 0;
          end
      else if (clk_en)
          readdata <= {32'b0 | read_mux_out};
    end

  assign data_in = (address == 2'b00) ? in_port :
                   (address == 2'b01) ? reg1 :
                   (address == 2'b10) ? reg2 :
                   (address == 2'b11) ? in_port & reg1 : 10'b0;

  assign read_mux_out = (address == 2'b00) ? data_in :
                        (address == 2'b01) ? reg1 :
                        (address == 2'b10) ? reg2 :
                        (address == 2'b11) ? in_port & reg1 : 10'b0;

  always @(posedge clk)
    begin
      if (reset_n == 0)
          begin
            reg1 <= 0;
            reg2 <= 0;
          end
      else
          begin
            case (address)
              2'b01: reg1 <= in_port;
              2'b10: reg2 <= in_port;
              2'b11: reg1 <= in_port;
            endcase
          end
    end

endmodule

