module arithmetic_module(
    input signed [31:0] a,
    input signed [31:0] b,
    input [1:0] op,
    output signed [31:0] c
);

// Declare internal signals
reg signed [31:0] sum;
reg signed [31:0] diff;
reg signed [31:0] prod;
reg signed [31:0] quotient;

// Perform arithmetic operations
always @* begin
    sum = a + b;
    diff = a - b;
    prod = a * b;
    quotient = a / b;
end

// Select output based on op
always @* begin
    case (op)
        2'b00: c = sum;
        2'b01: c = diff;
        2'b10: c = prod;
        2'b11: c = quotient;
    endcase
end

endmodule

module I2C_State_Machine (
  input SCL,
  input SDA,
  output reg SDA_out
);

  // Define states of the I2C state machine
  parameter IDLE = 0;
  parameter START = 1;
  parameter ADDR = 2;
  parameter READ = 3;
  parameter WRITE = 4;
  parameter STOP = 5;

  // Define state and data variables
  reg [2:0] state = IDLE;
  reg [7:0] data = 0;
  reg [2:0] bit_count = 0;
  reg [7:0] address = 0;
  reg [2:0] address_bit_count = 0;
  reg [2:0] read_bit_count = 0;
  reg [2:0] write_bit_count = 0;
  reg is_master = 0;
  reg is_receiver = 0;
  reg is_transmitter = 0;
  reg is_ack = 0;
  reg is_nack = 0;

  // Define state machine logic
  always @ (posedge SCL or posedge SDA) begin
    case (state)
      IDLE:
        if (SCL == 1 && SDA == 1) begin
          state <= START;
        end
      START:
        if (SCL == 0 && SDA == 1) begin
          state <= ADDR;
          bit_count <= 0;
          address_bit_count <= 0;
          read_bit_count <= 0;
          write_bit_count <= 0;
          is_master <= 1;
          is_receiver <= 0;
          is_transmitter <= 0;
          is_ack <= 0;
          is_nack <= 0;
        end
      ADDR:
        if (SCL == 0 && bit_count < 8) begin
          data[bit_count] <= SDA;
          bit_count <= bit_count + 1;
        end else if (SCL == 0 && bit_count == 8) begin
          address <= data;
          address_bit_count <= 0;
          if (address[0] == 1) begin
            is_receiver <= 1;
            state <= READ;
          end else begin
            is_transmitter <= 1;
            state <= WRITE;
          end
        end
      READ:
        if (SCL == 0 && address_bit_count < 8) begin
          SDA_out <= address[address_bit_count];
          address_bit_count <= address_bit_count + 1;
        end else if (SCL == 0 && address_bit_count == 8) begin
          state <= START;
          is_ack <= 1;
        end
      WRITE:
        if (SCL == 0 && address_bit_count < 8) begin
          SDA_out <= address[address_bit_count];
          address_bit_count <= address_bit_count + 1;
        end else if (SCL == 0 && address_bit_count == 8 && is_ack == 1) begin
          SDA_out <= data[write_bit_count];
          write_bit_count <= write_bit_count + 1;
        end else if (SCL == 0 && address_bit_count == 8 && write_bit_count == 8) begin
          state <= START;
          is_ack <= 1;
        end
    endcase
  end

  // Define logic for receiving data
  always @ (posedge SCL) begin
    if (state == READ && is_receiver == 1) begin
      if (SDA == 1) begin
        data[read_bit_count] <= 1;
      end else begin
        data[read_bit_count] <= 0;
      end
      read_bit_count <= read_bit_count + 1;
      if (read_bit_count == 8) begin
        state <= START;
        is_ack <= 1;
      end
    end
  end

  // Define logic for sending data
  always @ (posedge SCL) begin
    if (state == WRITE && is_transmitter == 1 && is_ack == 1) begin
      if (SDA == 0) begin
        write_bit_count <= write_bit_count + 1;
        if (write_bit_count == 8) begin
          state <= START;
        end
      end else begin
        is_nack <= 1;
        state <= STOP;
      end
    end
  end

  // Define logic for generating ACK or NACK
  always @ (posedge SCL) begin
    if (state == START && is_master == 1) begin
      is_ack <= 0;
      is_nack <= 0;
    end else if (state == STOP) begin
      is_ack <= 0;
      is_nack <= 0;
    end else if (SCL == 0 && state != IDLE && state != START && state != STOP) begin
      if (SDA == 0) begin
        is_ack <= 1;
        is_nack <= 0;
      end else begin
        is_ack <= 0;
        is_nack <= 1;
      end
    end
  end

endmodule

