    xor #(.N(4)) xor_inst_2 (.in(xor_out_1), .out(xor_out_2));
    xor #(.N(2)) xor_inst_3 (.in(xor_out_2), .out(xor_out_3));
    xor #(.N(2)) xor_inst_4 (.in({xor_out_3, 1'b0}), .out(parity));

endmodule

