module shift_register(clk, reset, load, shift_left, shift_right, data_in, data_out);

input clk, reset, load, shift_left, shift_right;
input [3:0] data_in;
output reg [3:0] data_out;

always @(posedge clk) begin
    if (reset) begin
        data_out <= 4'b0000;
    end
    else if (load) begin
        data_out <= data_in;
    end
    else if (shift_left) begin
        data_out <= {data_out[2:0], 1'b0};
    end
    else if (shift_right) begin
        data_out <= {1'b0, data_out[3:1]};
    end
end

endmodule

module mux_6to1_priority_encoder (
    input [2:0] sel,
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output reg [3:0] out
);

reg [2:0] encoded_sel;

always @* begin
    case ({data0, data1, data2, data3, data4, data5})
        6'b000001: encoded_sel = 3'b000;
        6'b000010: encoded_sel = 3'b001;
        6'b000100: encoded_sel = 3'b010;
        6'b001000: encoded_sel = 3'b011;
        6'b010000: encoded_sel = 3'b100;
        6'b100000: encoded_sel = 3'b101;
        default: encoded_sel = 3'b111;
    endcase
end

always @* begin
    case (sel)
        3'b000: out = data0;
        3'b001: out = data1;
        3'b010: out = data2;
        3'b011: out = data3;
        3'b100: out = data4;
        3'b101: out = data5;
        default: out = 4'b0000;
    endcase
end

assign out = (encoded_sel == sel) ? out : 4'b0000;

endmodule

