input wire start_process,
output reg complete
);

parameter n = 5;
parameter MAX_N = 8;
parameter MAX_CAND = 2**MAX_N;

reg [5:0]	state;
parameter	[5:0]	ST_RST		= 6'h00,
					ST_IDLE		= 6'h01;

reg [7:0] count, icand;

reg [7:0] a_len, min_b_len;


reg start_process_1, start_process_2;

// Storage for sets of codes
wire wren_codes;
wire [7:0] read_codes;
wire [10:0] addr_codes;
wire [7:0] data_codes;

icblbc_ram codes (
	.address ( addr_codes ),
	.clock ( clock ),
	.data ( data_codes ),
	.wren ( wren_codes ),
	.q ( read_codes )
);

reg fi_en;

find_iso fi (
	.clock ( clock ),
	.start ( fi_en ),
	.complete ( fi_done )

);

always @(posedge clock) begin
	{start_process_2, start_process_1} <= {start_process_1, start_process};

	case(state)
	ST_RST: begin
		state <= ST_IDLE;
	end

	ST_IDLE: begin
			if( start_process_2 ) begin
				state <= 3;
				a_len <= 1<<(n-1);
				min_b_len <= 2;
			end

	end

	3: begin
		state <= 4;
	end

	4: begin
		state <= 5;
	end

	5: begin
		state <= 10;
	end

	// Wait for find_iso() to finish
	10: begin
		fi_en <= 1;
		state <= 11;
	end

	11: begin
		if( fi_done ) begin
			state <= 12;
		end
	end

	12: begin
		state <= 13;
	end

	13: begin
		state <= ST_IDLE;
	end

	endcase
end
endmodule

