    input  [3:0] B   ;
    input        Cin ;
    output       Cout;
    input  VPWR;
    input  VGND;
    input  VPB ;
    input  VNB ;

    wire [3:0] X;
    wire [3:0] Y;
    wire [3:0] Z;

    // Implementing the first full adder
    sky130_fd_sc_ls__nand4b_1 nand1 (
        .Y(X[0]),
        .A_N(A[0]),
        .B_N(B[0]),
        .Cin(Cin),
        .VPWR(VPWR),
        .VGND(VGND),
        .VPB(VPB),
        .VNB(VNB)
    );
    sky130_fd_sc_ls__nand4b_1 nand2 (
        .Y(Y[0]),
        .A_N(X[0]),
        .B_N(Cin),
        .Cin(A[0]),
        .VPWR(VPWR),
        .VGND(VGND),
        .VPB(VPB),
        .VNB(VNB)
    );
    sky130_fd_sc_ls__nand4b_1 nand3 (
        .Y(Z[0]),
        .A_N(Y[0]),
        .B_N(Cin),
        .Cin(X[0]),
        .VPWR(VPWR),
        .VGND(VGND),
        .VPB(VPB),
        .VNB(VNB)
    );
    assign S[0] = Z[0];
    assign Cout = Y[0];

    // Implementing the remaining full adders using the ripple carry method
    genvar i;
    generate
        for(i = 1; i < 4; i = i + 1) begin : adder_loop
            sky130_fd_sc_ls__nand4b_1 nand4 (
                .Y(X[i]),
                .A_N(A[i]),
                .B_N(B[i]),
                .Cin(Y[i-1]),
                .VPWR(VPWR),
                .VGND(VGND),
                .VPB(VPB),
                .VNB(VNB)
            );
            sky130_fd_sc_ls__nand4b_1 nand5 (
                .Y(Y[i]),
                .A_N(X[i]),
                .B_N(Y[i-1]),
                .Cin(A[i]),
                .VPWR(VPWR),
                .VGND(VGND),
                .VPB(VPB),
                .VNB(VNB)
            );
            sky130_fd_sc_ls__nand4b_1 nand6 (
                .Y(Z[i]),
                .A_N(Y[i]),
                .B_N(Y[i-1]),
                .Cin(X[i]),
                .VPWR(VPWR),
                .VGND(VGND),
                .VPB(VPB),
                .VNB(VNB)
            );
            assign S[i] = Z[i];
        end
    endgenerate

endmodule

module add_subtract
    (clk, rst, load_a_i, load_b_i, add_subt_i, Data_X_i, Data_Y_i, DMP_o, DmP_o, zero_flag_o, real_op_o, sign_final_result_o);

    input clk;
    input rst;
    input load_a_i;
    input load_b_i;
    input add_subt_i;
    input [31:0]Data_X_i;
    input [31:0]Data_Y_i;
    output [30:0]DMP_o;
    output [30:0]DmP_o;
    output zero_flag_o;
    output real_op_o;
    output sign_final_result_o;

    wire [31:0] X;
    wire [31:0] Y;
    wire [31:0] result;
    wire [31:0] twos_complement;
    wire carry;
    wire borrow;
    wire zero_flag;
    wire real_op;
    wire sign_final_result;

    assign DMP_o = result[30:0];
    assign DmP_o = result[29:0];
    assign zero_flag_o = zero_flag;
    assign real_op_o = real_op;
    assign sign_final_result_o = sign_final_result;

    register #(.WIDTH(32)) reg_X (.clk(clk), .rst(rst), .load(load_a_i), .D(Data_X_i), .Q(X));
    register #(.WIDTH(32)) reg_Y (.clk(clk), .rst(rst), .load(load_b_i), .D(Data_Y_i), .Q(Y));

    assign twos_complement = ~Y + 1;

    assign borrow = (add_subt_i == 1) ? (X[0] < Y[0]) : (X[0] > twos_complement[0]);
    assign carry = (add_subt_i == 0) ? (X[0] < Y[0]) : (X[0] > twos_complement[0]);

    assign real_op = add_subt_i;
    assign sign_final_result = (result[31] == 1);

    assign zero_flag = (result == 0);

    assign result = (add_subt_i == 1) ? (X + Y) : (X + twos_complement);

    always @(posedge clk) begin
        if (rst) begin
            X <= 0;
            Y <= 0;
        end else begin
            X <= X;
            Y <= Y;
        end
    end

endmodule

module full_adder (
    input a,
    input b,
    input cin,
    output sum,
    output cout
);

    wire w1, w2, w3;

    assign w1 = a ^ b;
    assign sum = w1 ^ cin;
    assign w2 = a & b;
    assign w3 = w1 & cin;
    assign cout = w2 | w3;

endmodule

module ripple_carry_adder (
