module counter (
    input clk,
    input reset,
    input load,
    input up_down,
    output reg [2:0] count,
    output reg overflow,
    output reg underflow
);

reg [2:0] count_reg1, count_reg2;
reg [2:0] count_next;
wire up_down_sync;

assign up_down_sync = (reset) ? 1'b0 : up_down;

always @(posedge clk) begin
    if (reset) begin
        count_reg1 <= 3'b0;
        count_reg2 <= 3'b0;
    end
    else begin
        count_reg1 <= count_next;
        count_reg2 <= count_reg1;
    end
end

always @(*) begin
    if (load) begin
        count_next = 3'b0;
    end
    else begin
        if (up_down_sync) begin
            if (count_reg1 == 3'b111) begin
                count_next = 3'b000;
                overflow = 1'b1;
            end
            else begin
                count_next = count_reg1 + 1'b1;
                overflow = 1'b0;
            end
            underflow = 1'b0;
        end
        else begin
            if (count_reg1 == 3'b000) begin
                count_next = 3'b111;
                underflow = 1'b1;
            end
            else begin
                count_next = count_reg1 - 1'b1;
                underflow = 1'b0;
            end
            overflow = 1'b0;
        end
    end
end

assign count = count_reg2;

endmodule

module up_down_counter (
    input clk,
    input reset,
    input load,
    input up_down,
    output reg [3:0] count
);

reg [3:0] count_reg;
reg [3:0] count_next;

always @(posedge clk) begin
    if (reset) begin
        count_reg <= 4'b0;
    end else begin
        count_reg <= count_next;
    end
end

always @(*) begin
    if (load) begin
        count_next = count;
    end else if (up_down) begin
        count_next = count_reg + 1;
    end else begin
        count_next = count_reg - 1;
    end
end

assign count = count_reg;

endmodule

module ultrasonic #( parameter N = 16 , CONSTANT = 20'd588 ) ( 
    input clk,
    input signal,
    input rst_n,
    output reg [N-1:0] value , 
    output reg done 
    );

    reg [1:0]	state ;
    reg [N-1:0] count_1 ;

    // El modulo tiene 3 estados, el primero mantiene los valores en cero y se llega a el por medio del rst_n
    // El segundo estado inicia cuando el ultrasónico recibe la señal del modulo fisico y cuenta la duración
    // El tercer estado inicia cuando la señal del físico se apaga, enviando un "Done" al controlador
    // El rst_n devuelve al estado inicia el módulo

    // States assignation 
    parameter S0 = 2'b00 ;
    parameter S1 = 2'b01 ;
    parameter S2 = 2'b10 ;

    // Nextstate logic
    always @ ( negedge clk ) 
        if ( ~rst_n )
            state <= S0 ;
        else
            case ( state ) 
                S0 : 
                    if ( signal )
                        state <= S1 ;
                    else 
                        state <= S0 ;
                S1 :
                    if ( ~signal )
                        state <= S2 ;
                    else
                        state <= S1 ;
            endcase

    // State logic 
    always @( posedge clk )
        case ( state ) 
            S0 : begin
                count_1 <= 0 ;
                value <= 0 ;
                done <= 0 ;
            end S1 : begin
                if ( CONSTANT == count_1 ) begin
                    count_1 <= 1 ;
                    value <= value + 1'b1 ;
                    done <= 0 ; 
                end else begin  
                    count_1 <= count_1 + 1'b1 ;
                    value <= value ;
                    done <= 0 ;
                end
            end S2 : begin
                count_1 <= 0 ;
                value <= value ;
                done <= 1 ;
            end
        endcase

endmodule

module two_to_one_mux (
