    wire c_and_not_sel_b1_and_sel_b2;
    assign c_and_not_sel_b1_and_sel_b2 = c & not_sel_b1 & sel_b2;
    assign out = a_and_not_sel_b1_and_not_sel_b2 | b_and_sel_b1_and_not_sel_b2 | c_and_not_sel_b1_and_sel_b2;
