module manchester_carry_chain_adder( 
    input [99:0] a, b,
    input cin,
    output [99:0] cout,
    output [99:0] sum,
    output [99:0] final_output
);

    wire [99:0] c;
    wire [99:0] p;
    wire [99:0] g;

    assign p[0] = a[0] ^ b[0];
    assign g[0] = a[0] & b[0];

    generate
        genvar i;
        for (i = 1; i < 100; i = i + 1) begin : carry_generation
            assign p[i] = a[i] ^ b[i];
            assign g[i] = a[i] & b[i];
            assign c[i] = g[i-1] | (p[i-1] & c[i-1]);
        end
    endgenerate

    assign cout = c[99];
    assign sum = a + b + cin;
    assign final_output = sum + (cout << 1);

endmodule

module addsub (
  input [3:0] A, B,
  input SUB,
  output [3:0] OUT
);

  wire [3:0] B_INV;
  wire [3:0] CARRY;

  // Invert B when SUB is 1
  assign B_INV = SUB ? ~B + 1 : B;

  // First full adder for the least significant bit
  full_adder FA0(
    .A(A[0]),
    .B(B_INV[0]),
    .CIN(SUB),
    .SUM(OUT[0]),
    .COUT(CARRY[0])
  );

  // Full adders for the remaining bits
  full_adder FA1(
    .A(A[1]),
    .B(B_INV[1]),
    .CIN(CARRY[0]),
    .SUM(OUT[1]),
    .COUT(CARRY[1])
  );

  full_adder FA2(
    .A(A[2]),
    .B(B_INV[2]),
    .CIN(CARRY[1]),
    .SUM(OUT[2]),
    .COUT(CARRY[2])
  );

  full_adder FA3(
    .A(A[3]),
    .B(B_INV[3]),
    .CIN(CARRY[2]),
    .SUM(OUT[3]),
    .COUT(CARRY[3])
  );

endmodule

// Full adder module
module full_adder (
  input A, B, CIN,
  output SUM, COUT
);

  assign SUM = A ^ B ^ CIN;
  assign COUT = (A & B) | (A & CIN) | (B & CIN);

endmodule

module vending_machine_controller(
    input clk,
    input rst,
    input button_A,
    input button_B,
    input button_C,
    input coin,
    output reg dispense_X,
    output reg dispense_Y,
    output reg dispense_Z,
    output reg [23:0] display,
    output reg button_A_enable,
    output reg button_B_enable,
    output reg button_C_enable
);

    // Define constants
    parameter PRICE = 150; // Price of each product in cents
    parameter MAX_STOCK = 5; // Maximum stock of each product

    // Define state variables
    reg [1:0] state;
    reg [2:0] inventory;
    reg [23:0] total_money;

    // Define state machine states
    parameter [1:0] IDLE = 2'b00;
    parameter [1:0] DISPENSING = 2'b01;
    parameter [1:0] COIN_INSERTED = 2'b10;

    // Define state machine transitions and actions
    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            inventory <= {MAX_STOCK, MAX_STOCK, MAX_STOCK};
            total_money <= 0;
            dispense_X <= 0;
            dispense_Y <= 0;
            dispense_Z <= 0;
            button_A_enable <= 1;
            button_B_enable <= 1;
            button_C_enable <= 1;
        end else begin
            case (state)
                IDLE: begin
                    if (button_A && inventory[0] > 0) begin
                        state <= DISPENSING;
                        dispense_X <= 1;
                        inventory[0] <= inventory[0] - 1;
                        total_money <= total_money + PRICE;
                    end else if (button_B && inventory[1] > 0) begin
                        state <= DISPENSING;
                        dispense_Y <= 1;
                        inventory[1] <= inventory[1] - 1;
                        total_money <= total_money + PRICE;
                    end else if (button_C && inventory[2] > 0) begin
                        state <= DISPENSING;
                        dispense_Z <= 1;
                        inventory[2] <= inventory[2] - 1;
                        total_money <= total_money + PRICE;
                    end else if (coin) begin
                        state <= COIN_INSERTED;
                        total_money <= total_money + 100; // Add coin value to total money
                    end
                end
                DISPENSING: begin
                    if (!button_A && !button_B && !button_C) begin
                        state <= IDLE;
                        dispense_X <= 0;
                        dispense_Y <= 0;
                        dispense_Z <= 0;
                    end
                end
                COIN_INSERTED: begin
                    if (button_A && inventory[0] > 0) begin
                        state <= DISPENSING;
                        dispense_X <= 1;
                        inventory[0] <= inventory[0] - 1;
                        total_money <= total_money + PRICE;
                    end else if (button_B && inventory[1] > 0) begin
                        state <= DISPENSING;
                        dispense_Y <= 1;
                        inventory[1] <= inventory[1] - 1;
                        total_money <= total_money + PRICE;
                    end else if (button_C && inventory[2] > 0) begin
                        state <= DISPENSING;
                        dispense_Z <= 1;
                        inventory[2] <= inventory[2] - 1;
                        total_money <= total_money + PRICE;
                    end else if (!coin) begin
                        state <= IDLE;
                    end
                end
            endcase

            // Update button enable signals based on inventory levels
            button_A_enable <= (inventory[0] > 0);
            button_B_enable <= (inventory[1] > 0);
            button_C_enable <= (inventory[2] > 0);

            // Update display output
            display <= {7'b1111110, 7'b1111110, 7'b1111110}; // Default to showing "888"
            if (state == COIN_INSERTED) begin
                display <= {7'b0000110, 7'b0000000, 7'b0000000} + (total_money / 10); // Show total money in dollars
            end else begin
                display[0] <= 7'b1110000 - (inventory[0] * 7); // Show inventory level for product X
                display[1] <= 7'b1110000 - (inventory[1] * 7); // Show inventory level for product Y
                display[2] <= 7'b1110000 - (inventory[2] * 7); // Show inventory level for product Z
            end
        end
    end

endmodule

module top_module (
    input clk,
    input reset,   // Synchronous active-high reset
    output [3:1] ena,
    output [15:0] q,
    output out_and,
    output out_or,
    output out_xor
);

    // 4-digit binary counter with enable signals
    reg [3:0] count;
    reg [3:1] ena_reg;
    wire [3:0] inc_signals;
    wire [3:0] mux_inputs;
    wire [3:0] mux_select;

    // Combinational logic circuit
    wire [15:0] count_wire;
    wire [15:0] and_wire;
    wire [15:0] or_wire;
    wire [15:0] xor_wire;
    wire [1:0] select;

    // Control logic
    always @ (posedge clk, posedge reset) begin
        if (reset) begin
            count <= 0;
            ena_reg <= 0;
        end else begin
            count <= count + inc_signals;
            ena_reg <= ena;
        end
    end

    // Multiplexers for counter
    assign mux_inputs = {count[3:1], count[2:0], count[1:0], count[0]};
    assign mux_select = {3'b000, ena_reg};
    assign inc_signals = {1'b0, ena_reg};
    assign q = {mux_inputs[3:0], mux_inputs[3:0]};

    // Combinational logic circuit
    assign count_wire = {q, q};
    assign and_wire = count_wire & {16{1'b1}};
    assign or_wire = count_wire | {16{1'b0}};
    assign xor_wire = count_wire ^ {16{1'b1}};

    // Multiplexers for logic circuit
    assign out_and = select[0] ? and_wire[15] : and_wire[7];
    assign out_or = select[0] ? or_wire[15] : or_wire[7];
    assign out_xor = select[0] ? xor_wire[15] : xor_wire[7];
    assign select = count[3] ? 2'b10 : (count[2] ? 2'b01 : 2'b00);

endmodule

