module transmitter (
  input [7:0] data,
  input [15:0] frequency,
  output field
);

  // Define constants
  parameter clk_freq = 50_000_000; // Clock frequency in Hz
  parameter carrier_freq = 13_560_000; // Carrier frequency in Hz
  parameter baud_rate = 9600; // Baud rate in bits per second
  parameter bit_time = clk_freq / baud_rate; // Time for one bit in clock cycles

  // Define variables
  reg [15:0] counter = 0; // Counter for carrier frequency
  reg [3:0] bit_counter = 0; // Counter for bits
  reg [7:0] current_bit = 0; // Current bit being transmitted
  reg field_on = 0; // Flag for whether field is on or off

  // Generate carrier wave
  always @(posedge sys_clk) begin
    if (counter >= clk_freq / carrier_freq) begin
      counter <= 0;
      field_on <= ~field_on;
    end else begin
      counter <= counter + 1;
    end
  end

  // Transmit data
  always @(posedge sys_clk) begin
    if (bit_counter == 0) begin
      current_bit <= data;
    end

    if (bit_counter < 8) begin
      field <= field_on;
    end else if (bit_counter == 8) begin
      field <= ~field_on;
    end else if (bit_counter < 16) begin
      field <= current_bit[bit_counter - 8];
    end else if (bit_counter == 16) begin
      field <= ~field_on;
    end

    if (bit_counter >= 16) begin
      bit_counter <= 0;
    end else begin
      bit_counter <= bit_counter + 1;
    end
  end

endmodule

module receiver (
  input field,
  input [15:0] frequency,
  output [7:0] data
);

  // Define constants
  parameter clk_freq = 50_000_000; // Clock frequency in Hz
  parameter carrier_freq = 13_560_000; // Carrier frequency in Hz
  parameter baud_rate = 9600; // Baud rate in bits per second
  parameter bit_time = clk_freq / baud_rate; // Time for one bit in clock cycles

  // Define variables
  reg [15:0] counter = 0; // Counter for carrier frequency
  reg [3:0] bit_counter = 0; // Counter for bits
  reg [7:0] current_byte = 0; // Current byte being received
  reg [7:0] received_data = 0; // Data received from tag
  reg field_on = 0; // Flag for whether field is on or off

  // Detect carrier wave
  always @(posedge sys_clk) begin
    if (counter >= clk_freq / carrier_freq) begin
      counter <= 0;
      field_on <= ~field_on;
    end else begin
      counter <= counter + 1;
    end

    if (field_on && !field) begin
      bit_counter <= 0;
      current_byte <= 0;
    end
  end

  // Receive data
  always @(posedge sys_clk) begin
    if (field_on && field) begin
      if (bit_counter < 8) begin
        current_byte[bit_counter] <= 1;
      end else if (bit_counter == 8) begin
        // Check for start bit
        if (current_byte[0] == 0) begin
          bit_counter <= bit_counter + 1;
        end else begin
          bit_counter <= 0;
          current_byte <= 0;
        end
      end else if (bit_counter < 16) begin
        current_byte[bit_counter - 1] <= field;
      end else if (bit_counter == 16) begin
        // Check for stop bit
        if (field == 1) begin
          received_data <= current_byte;
          bit_counter <= 0;
          current_byte <= 0;
        end else begin
          bit_counter <= 0;
          current_byte <= 0;
        end
      end

      bit_counter <= bit_counter + 1;
    end
  end

  assign data = received_data;

endmodule

