module binary_search (
  input clk,
  input reset,
  input [31:0] search_value,
  input [31:0] array[31:0],
  output reg [4:0] index
);

  reg [31:0] sorted_array[31:0];
  reg [4:0] lower_bound;
  reg [4:0] upper_bound;
  reg [4:0] midpoint;
  reg [31:0] midpoint_value;
  reg [31:0] temp;
  reg [4:0] i;
  reg [4:0] j;
  reg [1:0] compare_result;

  always @(posedge clk) begin
    if (reset) begin
      index <= -1;
      lower_bound <= 0;
      upper_bound <= 31;
      i <= 0;
      j <= 0;
      compare_result <= 2'b0;
    end
    else begin
      if (i < 31) begin
        j <= i + 1;
        if (j < 32) begin
          if (sorted_array[i] > sorted_array[j]) begin
            temp <= sorted_array[i];
            sorted_array[i] <= sorted_array[j];
            sorted_array[j] <= temp;
          end
        end
        else begin
          i <= i + 1;
          j <= i;
        end
      end
      else begin
        midpoint <= (lower_bound + upper_bound) >> 1;
        midpoint_value <= array[midpoint];
        compare_result <= (midpoint_value > search_value) ? 2'b10 : (midpoint_value < search_value) ? 2'b01 : 2'b00;
        case (compare_result)
          2'b10: upper_bound <= midpoint - 1;
          2'b01: lower_bound <= midpoint + 1;
          2'b00: index <= midpoint;
        endcase
      end
    end
  end

  initial begin
    sorted_array <= array;
  end

endmodule

