module relaxation_oscillator (
  output reg clk
);

parameter R = 100; // value of the resistor in ohms
parameter C = 1e-6; // value of the capacitor in farads
parameter Vctrl = 1.5; // voltage threshold of the voltage-controlled switch in volts

reg charge;
reg discharge;
reg [31:0] counter;

always @(posedge charge or posedge discharge) begin
  if (charge) begin
    if (counter >= 100) begin
      charge <= 0;
      discharge <= 1;
      counter <= 0;
    end else begin
      counter <= counter + 1;
    end
  end else if (discharge) begin
    if (counter >= 100) begin
      discharge <= 0;
      charge <= 1;
      counter <= 0;
    end else begin
      counter <= counter + 1;
    end
  end else begin
    if (counter >= 100) begin
      charge <= 1;
      counter <= 0;
    end else begin
      counter <= counter + 1;
    end
  end
end

always @(posedge charge) begin
  clk <= 1;
end

always @(posedge discharge) begin
  clk <= 0;
end

