  wire [3:0] S;

  // Initialize inputs
  initial begin
    A = 4'b0000;
    B = 4'b0000;
    C = 1'b0;
  end

  // Test case 1: Sum
  always @* begin
    A = 4'b0010;
    B = 4'b0110;
    C = 1'b0;
  end

  // Test case 2: Carry
  always @* begin
    A = 4'b1111;
    B = 4'b0001;
    C = 1'b1;
  end

  // Verify output
  always @* begin
    if (S == 4'b1000) begin
      $display("Test 1 (sum) passed");
    end
    if (S == 4'b0001) begin
      $display("Test 2 (carry) passed");
    end
  end

endmodule

