module average_calculator (
    input clk,
    input reset,
    input [7:0] data_in,
    input data_valid,
    output reg [7:0] average_out,
    output reg average_valid
);

reg [15:0] sum;
reg [7:0] count;

always @(posedge clk) begin
    if (reset) begin
        sum <= 0;
        count <= 0;
        average_out <= 0;
        average_valid <= 0;
    end else if (data_valid) begin
        sum <= sum + data_in;
        count <= count + 1;
        average_out <= sum / count;
        average_valid <= 1;
    end else begin
        average_out <= average_out;
        average_valid <= 0;
    end
end

endmodule

module memory_generator
  (dout,
   wr_clk,
   rd_clk,
   E,
   tmp_ram_rd_en,
   out,
   Q,
   din);

  parameter WORD_SIZE = 64;
  parameter ADDR_SIZE = 10;

  input wr_clk;
  input rd_clk;
  input E;
  input tmp_ram_rd_en;
  input out;
  input [ADDR_SIZE-1:0] Q;
  input [WORD_SIZE-1:0] din;

  output [WORD_SIZE-1:0] dout;

  reg [ADDR_SIZE-1:0] addr;
  reg [WORD_SIZE-1:0] mem [0:(1<<ADDR_SIZE)-1];
  reg [WORD_SIZE-1:0] tmp_ram;
  reg tmp_ram_valid;

  always @(posedge wr_clk) begin
    if (E) begin
      mem[addr] <= din;
    end
  end

  always @(posedge rd_clk) begin
    if (E) begin
      case (out)
        0: dout <= mem[addr];
        1: dout <= tmp_ram;
        2: begin
          dout <= mem[addr];
          tmp_ram <= mem[addr];
          tmp_ram_valid <= 1;
        end
        3: begin
          if (tmp_ram_valid) begin
            dout <= tmp_ram;
          end else begin
            dout <= mem[addr];
          end
        end
        default: dout <= 0;
      endcase
    end
  end

  always @(posedge rd_clk) begin
    if (tmp_ram_rd_en) begin
      tmp_ram_valid <= 0;
    end
  end

  always @(posedge wr_clk) begin
    if (E) begin
      addr <= Q;
    end
  end

endmodule

