    input wire [15:0] in,
    output reg [7:0] even_bits,
    output reg [7:0] odd_bits
);

    integer i;

    always @* begin
        for (i = 0; i < 8; i = i + 1) begin
            even_bits[i] = in[i*2];
            odd_bits[i] = in[i*2+1];
