module battery_management_blocks (
  input enable_charge,
  input enable_discharge,
  input [7:0] voltage,
  input [7:0] current,
  output [7:0] charge_current,
  output [7:0] discharge_current,
  output [7:0] battery_voltage,
  output [7:0] state_of_charge
);

// Parameter values can be modified as per requirement
parameter MAX_CAPACITY = 4000; // Maximum capacity of the battery in mAh
parameter VOLTAGE_MIN = 3000; // Minimum voltage of the battery in mV
parameter VOLTAGE_MAX = 4200; // Maximum voltage of the battery in mV
parameter CURRENT_MAX = 2000; // Maximum current of the battery in mA

// Internal signals
reg [7:0] charge_current_reg = 0;
reg [7:0] discharge_current_reg = 0;
reg [7:0] battery_voltage_reg = 0;
reg [7:0] state_of_charge_reg = 0;

// Charging and discharging current functions
function [7:0] charging_current;
  input [7:0] voltage;
  begin
    if (voltage < VOLTAGE_MAX) begin
      charging_current = (MAX_CAPACITY - state_of_charge_reg) * CURRENT_MAX / MAX_CAPACITY;
    end else begin
      charging_current = 0;
    end
  end
endfunction

function [7:0] discharging_current;
  input [7:0] voltage;
  begin
    if (voltage > VOLTAGE_MIN) begin
      discharging_current = current;
    end else begin
      discharging_current = 0;
    end
  end
endfunction

// State of charge calculation
always @(posedge clk) begin
  if (enable_charge) begin
    charge_current_reg = charging_current(voltage);
    state_of_charge_reg = state_of_charge_reg + charge_current_reg / MAX_CAPACITY;
  end else if (enable_discharge) begin
    discharge_current_reg = discharging_current(voltage);
    state_of_charge_reg = state_of_charge_reg - discharge_current_reg / MAX_CAPACITY;
  end
  if (state_of_charge_reg > 100) begin
    state_of_charge_reg = 100;
  end else if (state_of_charge_reg < 0) begin
    state_of_charge_reg = 0;
  end
end

// Output assignments
assign charge_current = charge_current_reg;
assign discharge_current = discharge_current_reg;
assign battery_voltage = voltage;
assign state_of_charge = state_of_charge_reg;

endmodule

module binary_search (
  input wire clk,
  input wire reset,
  input wire start,
  input wire [15:0] search_val,
  input wire [15:0] array [15:0],
  output wire done,
  output wire found,
  output wire [3:0] index
);

  reg [3:0] low;
  reg [3:0] high;
  reg [3:0] mid;
  reg [15:0] mid_val;
  reg [15:0] found_val;
  reg [3:0] found_idx;
  reg done_reg;
  reg found_reg;

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      low <= 4'b0;
      high <= 4'b1111;
      mid <= 4'b0111;
      mid_val <= array[mid];
      found_val <= 16'h0;
      found_idx <= 4'b0000;
      done_reg <= 1'b0;
      found_reg <= 1'b0;
    end else begin
      if (start) begin
        if (mid_val == search_val) begin
          found_reg <= 1'b1;
          found_val <= search_val;
          found_idx <= mid;
        end else if (mid_val > search_val) begin
          high <= mid - 1;
        end else begin
          low <= mid + 1;
        end
        mid <= (low + high) >> 1;
        mid_val <= array[mid];
        if (low > high) begin
          done_reg <= 1'b1;
        end
      end
      done <= done_reg;
      found <= found_reg;
      index <= found_idx;
    end
  end

endmodule

module vga_c4_iface (
    // Wishbone common signals
    input         wb_clk_i,
    input         wb_rst_i,

    // Wishbone slave interface
    input  [16:1] wbs_adr_i,
    input  [ 1:0] wbs_sel_i,
    input         wbs_we_i,
    input  [15:0] wbs_dat_i,
    output [15:0] wbs_dat_o,
    input         wbs_stb_i,
    output        wbs_ack_o,

    // Wishbone master to SRAM
    output     [17:1] wbm_adr_o,
    output     [ 1:0] wbm_sel_o,
    output            wbm_we_o,
    output     [15:0] wbm_dat_o,
    input      [15:0] wbm_dat_i,
    output reg        wbm_stb_o,
    input             wbm_ack_i
  );

  // Registers and nets
  reg        plane_low;
  reg  [7:0] dat_low;
  wire       cont;

  // Continuous assignments
  assign wbs_ack_o = (plane_low & wbm_ack_i);
  assign wbm_adr_o = { 1'b0, wbs_adr_i[15:2], wbs_adr_i[1], plane_low };
  assign wbs_dat_o = { wbm_dat_i[7:0], dat_low };
  assign wbm_sel_o = 2'b01;
  assign wbm_dat_o = { 8'h0, plane_low ? wbs_dat_i[15:8] : wbs_dat_i[7:0] };
  assign wbm_we_o  = wbs_we_i & ((!plane_low & wbs_sel_i[0])
                                | (plane_low & wbs_sel_i[1]));

  assign cont = wbm_ack_i && wbs_stb_i;

  // Behaviour
  // wbm_stb_o
  always @(posedge wb_clk_i)
    wbm_stb_o <= wb_rst_i ? 1'b0 : (wbm_stb_o ? ~wbs_ack_o : wbs_stb_i);

  // plane_low
  always @(posedge wb_clk_i)
    plane_low <= wb_rst_i ? 1'b0 : (cont ? !plane_low : plane_low);

  // dat_low
  always @(posedge wb_clk_i)
    dat_low <= wb_rst_i ? 8'h0
      : ((wbm_ack_i && wbm_stb_o && !plane_low) ? wbm_dat_i[7:0] : dat_low);

endmodule

