module fifo_memory (
    input clk,        // Clock input
    input rst,        // Reset input
    input [7:0] in_data,    // Input data
    input in_valid,        // Input valid signal
    output in_ready,       // Input ready signal
    output [7:0] out_data,  // Output data
    output out_valid,      // Output valid signal
    input out_ready,       // Output ready signal
    output error           // Error signal
);

localparam WIDTH = 8;
localparam DEPTH = 16;

reg [WIDTH-1:0] memory [0:DEPTH-1];
reg [3:0] head = 0;
reg [3:0] tail = 0;
reg [WIDTH-1:0] data_out;
reg [1:0] count = 0;
reg error_flag = 0;

// Input logic
always @(posedge clk, negedge rst) begin
    if (!rst) begin
        in_ready <= 1'b0;
    end else if (in_valid && count < DEPTH) begin
        memory[head] <= in_data;
        head <= head + 1;
        count <= count + 1;
        in_ready <= 1'b1;
    end else begin
        in_ready <= 1'b0;
    end
end

// Output logic
always @(posedge clk, negedge rst) begin
    if (!rst) begin
        out_data <= 8'h00;
        out_valid <= 1'b0;
        error <= 1'b0;
    end else if (out_ready && count > 0) begin
        out_data <= memory[tail];
        tail <= tail + 1;
        count <= count - 1;
        out_valid <= 1'b1;
        if (error_flag) begin
            error <= 1'b0;
            error_flag <= 1'b0;
        end
    end else if (count == 0) begin
        out_data <= 8'h00;
        out_valid <= 1'b0;
        error <= 1'b1;
        error_flag <= 1'b1;
    end else begin
        out_valid <= 1'b0;
        error <= 1'b0;
    end
end

endmodule

module barrel_shifter_4bit (
    input [3:0] A,
    input [1:0] Shift,
    input Direction,
    output reg [3:0] Y
);

always @(*) begin
    case ({Direction, Shift})
        2'b00: Y = A; // no shift
        2'b01: Y = {A[2:0], A[3]}; // shift right by 1
        2'b10: Y = {A[0], A[3:1]}; // shift left by 1
        2'b11: Y = {A[1:0], A[3:2]}; // shift left by 2
    endcase
end

endmodule

module division_module (
    input [7:0] A,
    input [7:0] B,
    output reg [7:0] quotient,
    output reg [7:0] remainder
);

reg [7:0] dividend;
reg [7:0] divisor;
reg [7:0] temp;
reg [7:0] count;

always @(*) begin
    dividend = A;
    divisor = B;
    count = 8'd0;
    quotient = 8'd0;
    remainder = 8'd0;

    while (dividend >= divisor) begin
        temp = divisor;
        count = 8'd0;
        while (dividend >= temp) begin
            temp = temp << 1;
            count = count + 1;
        end
        temp = temp >> 1;
        count = count - 1;
        dividend = dividend - temp;
        quotient = quotient + (1 << count);
    end
    remainder = dividend;
end

endmodule

module functional_module (
    input [7:0] quotient,
    input [7:0] remainder,
    output reg [15:0] output_data
);

always @(*) begin
    output_data = (quotient * 16) + remainder;
end

endmodule

