module AOI22X1 (input IN1, IN2, IN3, IN4, output QN, output QN_bar, input VDD, VSS);
    wire a, b, c, d, e, f;

    // Implement AND gate using AOI22X1
    AOI22X1 u1 (.IN1(IN1), .IN2(IN2), .QN(a), .QN_bar(b), .VDD(VDD), .VSS(VSS));

    // Implement OR gate using AOI22X1
    AOI22X1 u2 (.IN1(IN3), .IN2(IN4), .QN(c), .QN_bar(d), .VDD(VDD), .VSS(VSS));

    // Implement NOT gate using AOI22X1
    AOI22X1 u3 (.IN1(a), .IN2(b), .QN(e), .QN_bar(f), .VDD(VDD), .VSS(VSS));

    // Connect inputs to NOT gate
    assign e = 1'b0;
    assign f = 1'b1;

    // Connect AND and OR gates to NOT gate
    assign QN = c;
    assign QN_bar = d;

endmodule

module BCD_to_Binary (
  input [3:0] bcd,
  output [7:0] bin
);

  // Convert BCD to decimal
  wire [3:0] decimal = bcd[3]*8 + bcd[2]*4 + bcd[1]*2 + bcd[0]*1;

  // Convert decimal to binary
  wire [7:0] binary;
  assign binary = {decimal[2], decimal[1], decimal[0]} << (decimal[3] ? 3 : 0);

  // Output binary code
  assign bin = binary;

endmodule

