module pll_sequencer (
  input clk_sys_i,
  input clk_reconf_i,
  input [31:0] r_pll_ctl0_i,
  input [31:0] r_pll_ctl1_i,
  output [31:0] r_pll_status_o,
  input pll_locked_i,
  output reg pll_rst_o,
  output reg [15:0] pll_di_o,
  input [15:0] pll_do_i,
  input pll_drdy_i,
  output reg [4:0] pll_daddr_o,
  output reg pll_den_o,
  output reg pll_dwe_o,
  output busy_o
);

  // Define states
  localparam [2:0] ST_IDLE = 3'b000;
  localparam [2:0] ST_START_CONFIG = 3'b001;
  localparam [2:0] ST_READ_DRP = 3'b010;
  localparam [2:0] ST_WAIT_READ_DRP = 3'b011;
  localparam [2:0] ST_WRITE_DRP = 3'b100;
  localparam [2:0] ST_WAIT_WRITE_DRP = 3'b101;
  localparam [2:0] ST_READ_ROM = 3'b110;
  localparam [2:0] ST_WAIT_LOCK = 3'b111;

  // Define registers
  reg [2:0] state;
  reg [4:0] index;
  reg [15:0] readback;
  reg [7:0] powerup_delay = 8'hff;
  reg rst_powerup = 1;
  reg trig_d0, trig_d1, trig_d2;

  // Define wires
  wire [4:0] r_cfg_addr = r_pll_ctl0_i[4:0];
  wire [39:0] r_cfg_data = {r_pll_ctl0_i[23:16], r_pll_ctl1_i[31:0]};
  wire r_cfg_we = r_pll_ctl0_i[5];
  wire r_cfg_trigger = r_pll_ctl0_i[6];
  wire [4:0] r_n_regs = r_pll_ctl0_i[11:7];
  wire [39:0] reg_val;

  // Define PLL RAM
  pll_drp_ram ConfRam (
    .clk_a_i(clk_sys_i),
    .wea_i(r_cfg_we),
    .da_i(r_cfg_data),
    .aa_i(r_cfg_addr),
    .clk_b_i(clk_reconf_i),
    .ab_i(index),
    .qb_o(reg_val)
  );

  // Define state machine
  always @(posedge clk_reconf_i) begin
    if (powerup_delay == 0) begin
      rst_powerup <= 0;
    end else begin
      powerup_delay <= powerup_delay - 1;
    end

    if (rst_powerup) begin
      state <= ST_IDLE;
      pll_rst_o <= 0;
      pll_dwe_o <= 0;
      pll_daddr_o <= 0;
      pll_den_o <= 0;
      index <= 0;
    end else begin
      trig_d0 <= r_cfg_trigger;
      trig_d1 <= trig_d0;
      trig_d2 <= trig_d1;
      if (~trig_d2 & trig_d1) begin
        state <= ST_START_CONFIG;
      end else begin
        case (state)
          ST_IDLE: begin
            pll_rst_o <= 0;
            pll_dwe_o <= 0;
            pll_daddr_o <= 0;
            pll_den_o <= 0;
            index <= 0;
          end
          ST_START_CONFIG: begin
            pll_rst_o <= 1;
            index <= 0;
            state <= ST_READ_ROM;
          end
          ST_READ_ROM: begin
            pll_daddr_o <= reg_val[36:32];
            state <= ST_READ_DRP;
          end
          ST_READ_DRP: begin
            pll_den_o <= 1;
            pll_dwe_o <= 0;
            state <= ST_WAIT_READ_DRP;
          end
          ST_WAIT_READ_DRP: begin
            pll_den_o <= 0;
            if (pll_drdy_i) begin
              state <= ST_WRITE_DRP;
              readback <= pll_do_i;
            end
          end
          ST_WRITE_DRP: begin
            pll_di_o <= (readback & reg_val[31:16]) | reg_val[15:0];
            index <= index + 1;
            pll_den_o <= 1;
            pll_dwe_o <= 1;
            state <= ST_WAIT_WRITE_DRP;
          end
          ST_WAIT_WRITE_DRP: begin
            pll_den_o <= 0;
            pll_dwe_o <= 0;
            if (pll_drdy_i) begin
              if (index == r_n_regs) begin
                state <= ST_WAIT_LOCK;
              end else begin
                state <= ST_READ_ROM;
              end
            end
          end
          ST_WAIT_LOCK: begin
            pll_rst_o <= 0;
            if (pll_locked_i) begin
              state <= ST_IDLE;
            end
          end
        endcase
      end
    end
  end

  // Define outputs
  assign r_pll_status_o[18] = pll_locked_i;
  assign busy_o = (state != ST_IDLE);

endmodule

module noise_generator(
    input             rst,
    input             clk,
    input             cen,
    input      [ 4:0] cycles,
    input      [ 4:0] nfrq,
    input      [ 9:0] eg,
    input             op31_no,
    output            out,
    output reg [11:0] mix
);

reg         update, nfrq_met;
reg  [ 4:0] cnt;
reg  [15:0] lfsr;
reg         last_lfsr0;
wire        all1, fb;
wire        mix_sgn;

assign out = lfsr[0];

// period counter
always @(posedge clk, posedge rst) begin
    if( rst ) begin
        cnt  <= 5'b0;
    end else if(cen) begin
        if( &cycles[3:0] ) begin
            cnt <= update ? 5'd0 : (cnt+5'd1);
        end
        update   <= nfrq_met;
        nfrq_met <= ~nfrq == cnt;
    end
end

// LFSR
assign fb   = update ? ~((all1 & ~last_lfsr0) | (lfsr[2]^last_lfsr0))
                     : ~lfsr[0];
assign all1 = &lfsr;
always @(posedge clk, posedge rst) begin
    if( rst ) begin
        lfsr       <= 16'hffff;
        last_lfsr0 <= 1'b0;
    end else if(cen) begin
        lfsr       <= { fb, lfsr[15:1] };
        if(update) last_lfsr0 <= ~lfsr[0];
    end
end

// Noise mix
assign mix_sgn = /*eg!=10'd0 ^*/ ~out;
always @(posedge clk, posedge rst) begin
    if( rst ) begin
        mix <= 12'd0;
    end else if( op31_no && cen ) begin
        mix     <= { mix_sgn, eg[9:2] ^ {8{out}}, {3{mix_sgn}} };
    end
end

endmodule

