module fifo(
    input clk,
    input wr_req,
    input [7:0] wr_data,
    input rd_req,
    output [7:0] rd_data,
    output reg wr_ack
);

reg [7:0] mem [0:7];
reg [2:0] wr_ptr = 0;
reg [2:0] rd_ptr = 0;
reg [2:0] count = 0;

always @(posedge clk) begin
    if (wr_req && (count < 8)) begin
        mem[wr_ptr] <= wr_data;
        wr_ptr <= wr_ptr + 1;
        count <= count + 1;
    end
    wr_ack <= (count < 8) ? 1'b1 : 1'b0;

    if (rd_req && (count > 0)) begin
        rd_data <= mem[rd_ptr];
        rd_ptr <= rd_ptr + 1;
        count <= count - 1;
    end
    else begin
        rd_data <= mem[rd_ptr];
    end
end

endmodule

module matrix_multiplier (
    input clk,
    input reset,
    input [8:0] A[2:0][2:0],
    input [8:0] B[2:0][2:0],
    output reg [8:0] product[2:0][2:0]
);

// Pipeline registers
reg [8:0] A_reg[2:0][2:0];
reg [8:0] B_reg[2:0][2:0];
reg [8:0] P_reg[2:0][2:0];

// Fetch stage
always @(posedge clk or posedge reset) begin
    if (reset) begin
        A_reg <= 0;
        B_reg <= 0;
    end else begin
        A_reg <= A;
        B_reg <= B;
    end
end

// Multiply stage
integer i, j, k;
always @(posedge clk) begin
    for (i = 0; i < 3; i = i + 1) begin
        for (j = 0; j < 3; j = j + 1) begin
            P_reg[i][j] <= 0;
            for (k = 0; k < 3; k = k + 1) begin
                P_reg[i][j] <= P_reg[i][j] + (A_reg[i][k] * B_reg[k][j]);
            end
        end
    end
end

// Write stage
always @(posedge clk or posedge reset) begin
    if (reset) begin
        product <= 0;
    end else begin
        product <= P_reg;
    end
end

endmodule

module nios2_interface (
  // inputs:
  input [31:0] E_st_data,
  input [31:0] av_ld_data_aligned_filtered,
  input clk,
  input [13:0] d_address,
  input d_read,
  input d_waitrequest,
  input d_write,
  input debugack,
  input reset_n,

  // outputs:
  output reg [13:0] cpu_d_address,
  output reg cpu_d_read,
  output reg [31:0] cpu_d_readdata,
  output reg cpu_d_wait,
  output reg cpu_d_write,
  output reg [31:0] cpu_d_writedata,
  output reg dbrk_break,
  output reg dbrk_goto0,
  output reg dbrk_goto1,
  output reg dbrk_traceme,
  output reg dbrk_traceoff,
  output reg dbrk_traceon,
  output reg dbrk_trigout
);

  reg [31:0] dbrk_data;
  reg dbrk_break_pulse;

  always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
      cpu_d_address <= 0;
      cpu_d_read <= 0;
      cpu_d_readdata <= 0;
      cpu_d_wait <= 0;
      cpu_d_write <= 0;
      cpu_d_writedata <= 0;
      dbrk_break <= 0;
      dbrk_goto0 <= 0;
      dbrk_goto1 <= 0;
      dbrk_traceme <= 0;
      dbrk_traceoff <= 0;
      dbrk_traceon <= 0;
      dbrk_trigout <= 0;
    end else begin
      cpu_d_address <= d_address;
      cpu_d_read <= d_read;
      cpu_d_wait <= d_waitrequest;
      cpu_d_write <= d_write;
      cpu_d_writedata <= E_st_data;

      if (d_read) begin
        cpu_d_readdata <= av_ld_data_aligned_filtered;
      end else begin
        cpu_d_readdata <= 0;
      end

      if (d_write) begin
        dbrk_data <= E_st_data;
      end else if (d_read) begin
        dbrk_data <= av_ld_data_aligned_filtered;
      end

      if (dbrk_break_pulse) begin
        dbrk_break <= ~debugack;
      end

      if (dbrk_goto0) begin
        cpu_d_address <= 0;
      end

      if (dbrk_goto1) begin
        cpu_d_address <= 1;
      end

      if (dbrk_traceme) begin
        dbrk_traceon <= 1;
        dbrk_traceoff <= 0;
      end

      if (dbrk_traceoff) begin
        dbrk_traceon <= 0;
        dbrk_traceoff <= 1;
      end

      if (dbrk_trigout) begin
        dbrk_trigout <= 0;
      end

      if (dbrk_data == 32'hdeadbeef) begin
        dbrk_break_pulse <= 1;
      end else begin
        dbrk_break_pulse <= 0;
      end
    end
  end

endmodule

module data_selector(
    input [7:0] data_in,
    input [2:0] select,
    input clk,
    input rst,
    output [7:0] data_out,
    output [2:0] output_sel,
    output reg [7:0] debug
);

reg [7:0] shift_left;
reg [7:0] shift_right;

always @ (posedge clk, posedge rst) begin
    if (rst) begin
        data_out <= 0;
        output_sel <= 0;
        debug <= 0;
    end
    else begin
        case (select)
            3'b000: begin
                data_out <= data_in;
                output_sel <= 3'b000;
            end
            3'b001: begin
                data_out <= ~data_in;
                output_sel <= 3'b001;
            end
            3'b010: begin
                shift_left <= data_in << 1;
                data_out <= shift_left;
                output_sel <= 3'b010;
            end
            3'b011: begin
                shift_right <= data_in >> 1;
                data_out <= shift_right;
                output_sel <= 3'b011;
            end
            3'b100: begin
                data_out <= data_in;
                output_sel <= 3'b100;
                debug <= data_in;
            end
            default: begin
                data_out <= 0;
                output_sel <= 0;
                debug <= 0;
            end
        endcase
    end
end

endmodule

module calculator (
    input signed [3:0] A,
    input signed [3:0] B,
    output [7:0] LEDS
);

    wire signed [7:0] mult_result;
    wire [2:0] decoder_out;
    wire signed [7:0] sum_result;

    mult_4bit_signed mult_module (
        .A(A),
        .B(B),
        .result(mult_result)
    );

    decoder decoder_module (
        .in(mult_result[7]),
        .out(decoder_out)
    );

    assign LEDS = ~{decoder_out, 3'b000};

    assign sum_result = mult_result + {8'b00000000, decoder_out};

endmodule

