module highest_bit_detection (
    input clk,
    input [7:0] in,
    output [7:0] rising_edge,
    output reg [2:0] pos
);

    // Rising edge detector
    reg [7:0] prev_in;
    reg [7:0] count;
    reg [7:0] diff;
    always @(posedge clk) begin
        prev_in <= in;
        diff <= in ^ prev_in;
        if (diff != 0) begin
            count <= 8'b00000001;
        end else begin
            count <= count + 1;
        end
    end
    assign rising_edge = diff & (count == 8'b00000001);

    // Priority encoder
    reg [3:0] gray;
    always @* begin
        gray = {in[7], in[7]^in[6], in[6]^in[5], in[5]^in[4], in[4]^in[3], in[3]^in[2], in[2]^in[1], in[1]^in[0]};
    end
    always @* begin
        case (gray)
            4'b0000: pos = 3'b000;
            4'b0001: pos = 3'b001;
            4'b0011: pos = 3'b010;
            4'b0111: pos = 3'b011;
            4'b1111: pos = 3'b100;
            default: pos = 3'b000;
        endcase
    end

endmodule

module uart_tx(
  input clk, rst, TxD_start,
  input [7:0] TxD_data,
  output TxD, TxD_busy
);

parameter BAUD_RATE = 115200;
parameter DATA_BITS = 8;
parameter STOP_BITS = 2;

parameter REGISTER_INPUT_DATA = 1;

parameter BAUD_GENERATOR_ACC_WIDTH = 16;

reg [BAUD_GENERATOR_ACC_WIDTH:0] baud_generator_acc;
wire [BAUD_GENERATOR_ACC_WIDTH:0] baud_generator_inc;

wire baud_tick;
wire txd_busy;

reg [3:0] state;
reg [7:0] txd_data_reg;
reg muxbit;
reg txd;

assign TxD_busy = txd_busy;

// Baud generator
generate
  if (BAUD_RATE == 115200) begin : baud_115200
    `ifdef FPGA_50MHZ
    assign baud_generator_inc = 17'h00097;
    `endif
    `ifdef FPGA_32MHZ
    assign baud_generator_inc = 17'h000ec;
    `endif
    `ifdef FPGA_64MHZ
    assign baud_generator_inc = 17'h00076;
    `endif
  end
  else if (BAUD_RATE == 9600) begin : baud_9600
    `ifdef FPGA_50MHZ
    assign baud_generator_inc = 17'h0125;
    `endif
    `ifdef FPGA_32MHZ
    assign baud_generator_inc = 17'h01f4;
    `endif
    `ifdef FPGA_64MHZ
    assign baud_generator_inc = 17'h00fa;
    `endif
  end
  else begin : baud_default
    assign baud_generator_inc = 17'h00000;
  end
endgenerate

// State machine
always @(posedge clk or posedge rst) begin
  if (rst) begin
    state <= 4'b0000;
    txd_data_reg <= 8'h00;
    baud_generator_acc <= 16'h0000;
    txd <= 1'b1;
  end
  else begin
    case (state)
      4'b0000: if (TxD_start) state <= 4'b0001;
      4'b0001: if (baud_tick) state <= 4'b0100;
      4'b0100: if (baud_tick) state <= 4'b1000; // start
      4'b1000: if (baud_tick) state <= 4'b1001; // bit 0
      4'b1001: if (baud_tick) state <= 4'b1010; // bit 1
      4'b1010: if (baud_tick) state <= 4'b1011; // bit 2
      4'b1011: if (baud_tick) state <= 4'b1100; // bit 3
      4'b1100: if (baud_tick) state <= 4'b1101; // bit 4
      4'b1101: if (baud_tick) state <= 4'b1110; // bit 5
      4'b1110: if (baud_tick) state <= 4'b1111; // bit 6
      4'b1111: if (baud_tick) state <= 4'b0010; // bit 7
      4'b0010: if (baud_tick) state <= 4'b0011; // stop1
      4'b0011: if (baud_tick) state <= 4'b0000; // stop2
      default: if (baud_tick) state <= 4'b0000;
    endcase
  end
end

// Input data register
always @(posedge clk or posedge rst) begin
  if (rst) begin
    txd_data_reg <= 8'h00;
  end
  else begin
    if (REGISTER_INPUT_DATA) begin
      if (TxD_start) begin
        txd_data_reg <= TxD_data;
      end
    end
    else begin
      txd_data_reg <= TxD_data;
    end
  end
end

// Output mux
always @(*) begin
  case (state[2:0])
    3'd0: muxbit = txd_data_reg[0];
    3'd1: muxbit = txd_data_reg[1];
    3'd2: muxbit = txd_data_reg[2];
    3'd3: muxbit = txd_data_reg[3];
    3'd4: muxbit = txd_data_reg[4];
    3'd5: muxbit = txd_data_reg[5];
    3'd6: muxbit = txd_data_reg[6];
    3'd7: muxbit = txd_data_reg[7];
  endcase
end

// TxD output
always @(posedge clk or posedge rst) begin
  if (rst) begin
    txd <= 1'b1;
  end
  else begin
    if (state < 4) begin
      txd <= 1'b0;
    end
    else begin
      txd <= state[3] & muxbit;
    end
  end
end

// Baud generator
always @(posedge clk or posedge rst) begin
  if (rst) begin
    baud_generator_acc <= 16'h0000;
  end
  else if (txd_busy) begin
    baud_generator_acc <= baud_generator_acc[BAUD_GENERATOR_ACC_WIDTH-1:0] + baud_generator_inc;
  end
end

// Baud tick
assign baud_tick = baud_generator_acc[BAUD_GENERATOR_ACC_WIDTH];

// TxD busy
assign txd_busy = (state != 4'b0000);

// Output
assign TxD = txd;

endmodule

