module comparator (
  input [n-1:0] num1,
  input [n-1:0] num2,
  input cmp_mode,
  output gt,
  output eq,
  output lt
);

parameter n = 8; // number of bits in input numbers

reg signed [n-1:0] signed_num1;
reg signed [n-1:0] signed_num2;
reg [n-1:0] unsigned_num1;
reg [n-1:0] unsigned_num2;

assign gt = (cmp_mode == 0) ? (unsigned_num1 > unsigned_num2) : (signed_num1 > signed_num2);
assign eq = (cmp_mode == 0) ? (unsigned_num1 == unsigned_num2) : (signed_num1 == signed_num2);
assign lt = (cmp_mode == 0) ? (unsigned_num1 < unsigned_num2) : (signed_num1 < signed_num2);

always @(*) begin
  if (cmp_mode == 0) begin // unsigned comparison
    unsigned_num1 = num1;
    unsigned_num2 = num2;
    signed_num1 = {1'b0, num1};
    signed_num2 = {1'b0, num2};
  end else begin // signed comparison
    unsigned_num1 = num1;
    unsigned_num2 = num2;
    signed_num1 = num1;
    signed_num2 = num2;
  end
end

endmodule

module processor #(parameter CONTROL_WIDTH = 4, parameter ADDR_WIDTH = 4, parameter DATA_WIDTH = 8)(
	input wire clk,
	input wire reset_in,
	input wire [CONTROL_WIDTH+ADDR_WIDTH+ADDR_WIDTH-1:0] vector_in,
	input wire bus_grant_in,
	input wire [DATA_WIDTH-1:0] data_in,
	output reg bus_request_out,
	output reg [ADDR_WIDTH-1:0] addr_out,
	output reg [DATA_WIDTH-1:0] alu_out,
	output reg status_out
);

	// Define constants
	parameter LINE_WIDTH = CONTROL_WIDTH+ADDR_WIDTH+ADDR_WIDTH;
	parameter HALT = 1'b0;
	parameter START = 1'b1;
	parameter BUS_GRANTED = 1'b1;
	parameter BUS_NOT_GRANTED = 1'b0;

	// Define internal signals
	reg [CONTROL_WIDTH-1:0] tag;
	reg [ADDR_WIDTH-1:0] addr;
	reg [DATA_WIDTH-1:0] data;
	reg [LINE_WIDTH-1:0] vector;
	reg [LINE_WIDTH-1:0] next_vector;
	reg [DATA_WIDTH-1:0] next_alu_out;
	reg [ADDR_WIDTH-1:0] next_addr_out;
	reg next_status_out;
	reg next_bus_request_out;

	// Define state variables
	reg [LINE_WIDTH-1:0] curr_vector;
	reg [DATA_WIDTH-1:0] curr_alu_out;
	reg [ADDR_WIDTH-1:0] curr_addr_out;
	reg curr_status_out;
	reg curr_bus_request_out;

	// Instantiate submodules
	alu #(.DATA_WIDTH(DATA_WIDTH)) alu_inst(
		.data_in(data),
		.vector_in(vector),
		.alu_out(next_alu_out)
	);

	// Define combinational logic
	assign bus_request_out = next_bus_request_out;
	assign addr_out = next_addr_out;
	assign alu_out = curr_alu_out;
	assign status_out = curr_status_out;

	// Define sequential logic
	always@(posedge clk) begin
		if(reset_in) begin
			curr_vector <= 0;
			curr_alu_out <= 0;
			curr_addr_out <= 0;
			curr_status_out <= HALT;
			curr_bus_request_out <= BUS_NOT_GRANTED;
		end
		else begin
			curr_vector <= next_vector;
			curr_alu_out <= next_alu_out;
			curr_addr_out <= next_addr_out;
			curr_status_out <= next_status_out;
			curr_bus_request_out <= next_bus_request_out;
		end
	end

	always@(curr_vector, curr_status_out, bus_grant_in) begin
		next_vector = curr_vector;
		next_addr_out = curr_addr_out;
		next_alu_out = curr_alu_out;
		next_status_out = curr_status_out;
		next_bus_request_out = curr_bus_request_out;

		tag = curr_vector[LINE_WIDTH-1:LINE_WIDTH-CONTROL_WIDTH];
		addr = curr_vector[ADDR_WIDTH+CONTROL_WIDTH-1:CONTROL_WIDTH];
		data = curr_vector[DATA_WIDTH+ADDR_WIDTH+CONTROL_WIDTH-1:ADDR_WIDTH+CONTROL_WIDTH];

		if(bus_grant_in == BUS_GRANTED) begin
			next_vector = {tag, addr, data};
			next_bus_request_out = BUS_NOT_GRANTED;
		end
		else begin
			case(curr_vector[LINE_WIDTH-1:LINE_WIDTH-CONTROL_WIDTH+1])
				0: begin // No operation
					next_bus_request_out = BUS_NOT_GRANTED;
				end
				1: begin // Start
					next_status_out = START;
					next_bus_request_out = BUS_NOT_GRANTED;
				end
				2: begin // Halt
					next_status_out = HALT;
					next_bus_request_out = BUS_NOT_GRANTED;
				end
				default: begin // Arithmetic or logical operation
					if(curr_status_out == START) begin
						vector = curr_vector;
						next_addr_out = addr;
						next_bus_request_out = BUS_GRANTED;
					end
					else if(curr_status_out == HALT) begin
						next_alu_out = data;
						next_bus_request_out = BUS_NOT_GRANTED;
					end
				end
			endcase
		end
	end

endmodule

module alu #(parameter DATA_WIDTH = 8)(
	input wire [DATA_WIDTH-1:0] data_in,
	input wire [DATA_WIDTH-1:0] vector_in,
	output reg [DATA_WIDTH-1:0] alu_out
);

	always@(data_in, vector_in) begin
		// Define arithmetic and logical operations
		case(vector_in[3:0])
			4'b0000: alu_out <= data_in & vector_in[7:0];
			4'b0001: alu_out <= data_in | vector_in[7:0];
			4'b0010: alu_out <= data_in ^ vector_in[7:0];
			4'b0011: alu_out <= ~data_in;
			4'b0100: alu_out <= data_in + vector_in[7:0];
			4'b0101: alu_out <= data_in - vector_in[7:0];
			4'b0110: alu_out <= data_in << vector_in[3:0];
			4'b0111: alu_out <= data_in >> vector_in[3:0];
			4'b1000: alu_out <= {data_in[0], data_in[7:1]};
			4'b1001: alu_out <= {data_in[6:0], data_in[7]};
			default: alu_out <= 0;
		endcase
	end

endmodule

