module cordic(
    input signed [19:0] realIn,
    input signed [19:0] imagIn,
    input clk,
    output reg signed [21:0] amplitude,
    output reg signed [14:0] angle,
    output reg test1,
    output reg test2
);

    reg signed [19:0] x;
    reg signed [19:0] y;
    reg signed [19:0] z;
    reg signed [14:0] angles [15:0];
    reg signed [21:0] gains [15:0];
    reg signed [14:0] i;
    reg signed [21:0] tmp;

    assign test1 = (i == 15);
    assign test2 = (i == 0);

    initial begin
        angles[0] = 8192;
        gains[0] = 524288;
        for (i = 1; i < 16; i = i + 1) begin
            angles[i] = angles[i-1] / 2;
            gains[i] = gains[i-1] / $sqrt(1 + (gains[i-1] >> (2*i)));
        end
    end

    always @(posedge clk) begin
        if (i < 15) begin
            if (y < 0) begin
                x = x + (y >> i);
                y = y + (x >> i);
                z = z - angles[i];
            end else begin
                x = x - (y >> i);
                y = y + (x >> i);
                z = z + angles[i];
            end
            amplitude = gains[i] * x;
            angle = z;
            i = i + 1;
        end
    end

    assign x = realIn;
    assign y = imagIn;
    assign z = 0;
    assign amplitude = gains[0] * x;
    assign angle = z;

endmodule

module traffic_light_controller(
  input clk,
  input reset,
  input manual_override,
  output reg main_road_lane1,
  output reg main_road_lane2,
  output reg secondary_road_lane1,
  output reg secondary_road_lane2
);

  parameter IDLE = 2'b00;
  parameter MAIN_ROAD_GREEN = 2'b01;
  parameter MAIN_ROAD_YELLOW = 2'b10;
  parameter SECONDARY_ROAD_GREEN = 2'b11;
  parameter SECONDARY_ROAD_YELLOW = 2'b100;

  reg [2:0] state;
  reg [5:0] timer;

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      state <= IDLE;
      timer <= 0;
      main_road_lane1 <= 0;
      main_road_lane2 <= 0;
      secondary_road_lane1 <= 0;
      secondary_road_lane2 <= 0;
    end else begin
      case (state)
        IDLE: begin
          if (manual_override) begin
            main_road_lane1 <= 0;
            main_road_lane2 <= 0;
            secondary_road_lane1 <= 0;
            secondary_road_lane2 <= 0;
          end else begin
            main_road_lane1 <= 0;
            main_road_lane2 <= 0;
            secondary_road_lane1 <= 0;
            secondary_road_lane2 <= 0;
            state <= MAIN_ROAD_GREEN;
            timer <= 20;
          end
        end
        MAIN_ROAD_GREEN: begin
          main_road_lane1 <= 1;
          main_road_lane2 <= 1;
          if (timer == 0) begin
            state <= MAIN_ROAD_YELLOW;
            timer <= 5;
          end else begin
            timer <= timer - 1;
          end
        end
        MAIN_ROAD_YELLOW: begin
          main_road_lane1 <= 0;
          main_road_lane2 <= 0;
          if (timer == 0) begin
            state <= SECONDARY_ROAD_GREEN;
            timer <= 20;
          end else begin
            timer <= timer - 1;
          end
        end
        SECONDARY_ROAD_GREEN: begin
          secondary_road_lane1 <= 1;
          secondary_road_lane2 <= 1;
          if (timer == 0) begin
            state <= SECONDARY_ROAD_YELLOW;
            timer <= 5;
          end else begin
            timer <= timer - 1;
          end
        end
        SECONDARY_ROAD_YELLOW: begin
          secondary_road_lane1 <= 0;
          secondary_road_lane2 <= 0;
          if (timer == 0) begin
            state <= MAIN_ROAD_GREEN;
            timer <= 20;
          end else begin
            timer <= timer - 1;
          end
        end
      endcase
    end
  end

endmodule

module counter_with_gray (
    input CLK,
    input Reset,
    input Up,
    input Down,
    input Load,
    output reg [2:0] counter_out,
    output reg [2:0] gray_out
);

    reg [2:0] counter_reg;
    reg [2:0] gray_reg;

    always @(posedge CLK) begin
        if (Reset) begin
            counter_reg <= 3'b000;
            gray_reg <= 3'b000;
        end
        else begin
            if (Load) begin
                counter_reg <= BIN;
            end
            else begin
                if (Up) begin
                    counter_reg <= counter_reg + 1;
                end
                else if (Down) begin
                    counter_reg <= counter_reg - 1;
                end
            end
            gray_reg <= {counter_reg[2] ^ counter_reg[1], counter_reg[1] ^ counter_reg[0], counter_reg[0]};
        end
    end

    assign counter_out = counter_reg;
    assign gray_out = gray_reg;

endmodule

