    end

endmodule

module fsm_1010_sequence_detection (
  input clk,
  input reset,
  input data,
  output reg match
);

  parameter INIT = 2'b0;
  parameter MATCH = 2'b1;

  reg [1:0] state;
  reg [3:0] shift_reg;

  always @(posedge clk) begin
    if (reset) begin
      state <= INIT;
      shift_reg <= 4'b0;
      match <= 1'b0;
    end
    else begin
      case(state)
        INIT: begin
          if (shift_reg == 4'b1010) begin
            state <= MATCH;
            match <= 1'b1;
          end
          else begin
            shift_reg <= {shift_reg[2:0], data};
          end
        end
        MATCH: begin
          if (reset) begin
            state <= INIT;
            shift_reg <= 4'b0;
            match <= 1'b0;
          end
        end
      endcase
    end
  end

endmodule

module CRC16_D16
  (input [15:0] Data,
   input [15:0] CRC,
   output [15:0] NewCRC);

  reg [15:0] D;
  reg [15:0] C;
  reg [15:0] NewCRC;

  assign NewCRC = nextCRC16_D16(D, C);

  function [15:0] nextCRC16_D16;

    input [15:0] D;
    input [15:0] C;

    reg [31:0] dividend;
    reg [15:0] divisor;
    reg [15:0] remainder;
    reg [15:0] quotient;
    reg [15:0] crc;
    integer i;

    begin
      dividend = {D, 16'h0000};
      divisor = 16'h1021;
      remainder = 16'h0000;
      quotient = 16'h0000;
      crc = C;

      for (i = 0; i < 16; i = i + 1) begin
        remainder = {remainder[14:0], dividend[i]};
        quotient = remainder[15] ? divisor : 16'h0000;
        remainder = remainder ^ (quotient << 1);
      end

      nextCRC16_D16 = remainder ^ crc;
    end

  endfunction

endmodule

module subtraction (
    input [A_WIDTH-1:0] A,
    input [B_WIDTH-1:0] B,
    output [Y_WIDTH-1:0] Y
);

parameter A_SIGNED = 0;
parameter B_SIGNED = 0;
parameter A_WIDTH = 1;
parameter B_WIDTH = 1;
parameter Y_WIDTH = 1;

wire [Y_WIDTH-1:0] A_buf, B_buf;
pos #(.A_SIGNED(A_SIGNED), .A_WIDTH(A_WIDTH), .Y_WIDTH(Y_WIDTH)) A_conv (.A(A), .Y(A_buf));
pos #(.A_SIGNED(B_SIGNED), .A_WIDTH(B_WIDTH), .Y_WIDTH(Y_WIDTH)) B_conv (.A(B), .Y(B_buf));

__alu #(
    .WIDTH(Y_WIDTH)
) alu (
    .A(A_buf),
    .B(~B_buf),
    .Cin(1'b1),
    .Y(Y)
);

endmodule

module Viterbi_Decoder (
  input [n-1:0] in,
  output reg [m-1:0] out
);

parameter n = 16; // number of received bits
parameter m = 8; // number of decoded bits
parameter k = 3; // number of bits in each convolutional code
parameter p = 8; // number of states in the Viterbi decoder

integer i, j, t;
reg [k-1:0] state;
reg [p-1:0] metric;
reg [p-1:0] min_metric;
reg [p-1:0] min_state;

// State transition function
function [k-1:0] next_state;
  input [k-1:0] current_state;
  input in_bit;
  begin
    next_state = {current_state[k-2:0], in_bit};
  end
endfunction

// Output function
function [n-1:0] output_bits;
  input [k-1:0] current_state;
  begin
    output_bits = current_state[k-1] ^ current_state[k-2];
  end
endfunction

// Metric computation
always @(in) begin
  for (i = 0; i < p; i = i + 1) begin
    metric[i] = 0;
    for (j = 0; j < n; j = j + 1) begin
      if (in[j] != output_bits(state)) begin
        metric[i] = metric[i] + 1;
      end
      state = next_state(state, in[j]);
    end
  end
end

// State selection
always @(metric) begin
  min_metric = metric[0];
  min_state = 0;
  for (i = 1; i < p; i = i + 1) begin
    if (metric[i] < min_metric) begin
      min_metric = metric[i];
      min_state = i;
    end
  end
end

// Decoded bits computation
always @(min_state) begin
  state = min_state;
  for (t = 0; t < m; t = t + 1) begin
    out[t] = state[k-1];
    state = next_state(state, in[t]);
  end
end

endmodule

module bidirectional_bus_driver(
    input clk,
    input reset,
    input [7:0] port_id,
    input [7:0] in_dato,
    input write_strobe,
    input read_strobe,
    output reg reg_a_d,
    output reg reg_cs,
    output reg reg_rd,
    output reg reg_wr,
    output reg [7:0] out_dato,
    output reg flag_done,
    inout [7:0] dato
);

// Internal signals
reg en_funcion;
reg [7:0] addr_RAM, dato_escribir;
wire [7:0] dato_leido;
reg [7:0] next_out_dato;
reg [7:0] reg_addr_RAM, reg_dato_escribir, reg_dato_leido;
reg reg_escribir_leer, escribir_leer;
wire direccion_dato;

// Instantiate the RAM module
ram_module ram_instance (
    .clk(clk),
    .reset(reset),
    .addr(addr_RAM),
    .in_dato(dato_escribir),
    .out_dato(dato_leido),
    .wr(reg_wr),
    .rd(reg_rd),
    .cs(reg_cs)
);

// Generate control signals
control_signal_generator control_instance (
    .clk(clk),
    .reset(reset),
    .en_funcion(en_funcion),
    .reg_a_d(reg_a_d),
    .reg_cs(reg_cs),
    .reg_rd(reg_rd),
    .reg_wr(reg_wr),
    .direccion_dato(direccion_dato),
    .flag_done(flag_done)
);

// Sequential logic
always @(negedge clk, posedge reset) begin
    if (reset) begin
        addr_RAM <= 8'h0;
        dato_escribir <= 8'h0;
        escribir_leer <= 1'b0;
        out_dato <= 8'b0;
    end
    else begin
        addr_RAM <= reg_addr_RAM;
        dato_escribir <= reg_dato_escribir;
        escribir_leer <= reg_escribir_leer;
        out_dato <= next_out_dato;
    end
end

// Combinational logic for port_id
always @* begin
    if (~reg_rd) begin
        next_out_dato = dato_leido;
    end
    else begin
        next_out_dato = out_dato;
    end

    if (write_strobe || read_strobe) begin
        // Start read/write sequence
        if (port_id == 8'h0E) begin
            en_funcion = 1'b1;
        end
        else begin
            en_funcion = 1'b0;
        end

        case (port_id)
            8'h00: begin // Update address
                reg_addr_RAM = in_dato;
                reg_dato_escribir = dato_escribir; 
                reg_escribir_leer = escribir_leer;
            end
            8'h01: begin // Update data
                reg_dato_escribir = in_dato;
                reg_addr_RAM = addr_RAM;
                reg_escribir_leer = escribir_leer;
            end
            8'h0E: begin // Start read/write sequence
                reg_addr_RAM = addr_RAM;
                reg_dato_escribir = dato_escribir;
                reg_escribir_leer = in_dato[0];
            end
            default: begin
                reg_addr_RAM = addr_RAM;
                reg_dato_escribir = dato_escribir;
                reg_escribir_leer = escribir_leer;
            end
        endcase	
    end
    else begin
        reg_addr_RAM = addr_RAM;
        reg_dato_escribir = dato_escribir;
        reg_escribir_leer = escribir_leer;
        en_funcion = 1'b0;
    end
end

// Bidirectional bus driver
driver_bus_bidirectional driver_instance (
    .in_flag_escritura(~reg_wr), 
    .in_flag_lectura(~reg_rd), 
    .in_direccion_dato(direccion_dato), 
    .in_dato(dato_escribir), 
    .out_reg_dato(dato_leido),  
    .addr_RAM(addr_RAM), 
    .dato(dato)
);

endmodule

