module pfpu_ctlif #(
	parameter csr_addr = 4'h0
) (
	input sys_clk,
	input sys_rst,

	input [13:0] csr_a,
	input csr_we,
	input [31:0] csr_di,
	output [31:0] csr_do,

	output reg irq,

	output reg start,
	input busy,

	/* Address generator interface */
	output reg [28:0] dma_base,
	output reg [6:0] hmesh_last,
	output reg [6:0] vmesh_last,

	/* Register file interface */
	output [6:0] cr_addr,
	input [31:0] cr_di,
	output [31:0] cr_do,
	output cr_w_en,

	/* Program memory interface */
	output reg [1:0] cp_page,
	output [8:0] cp_offset,
	input [31:0] cp_di,
	output [31:0] cp_do,
	output cp_w_en,

	/* Diagnostic registers */
	input vnext,
	input err_collision,
	input err_stray,
	input [10:0] pc,

	input [31:0] wbm_adr_o,
	input wbm_ack_i
);

reg [31:0] last_dma;
always @(posedge sys_clk)
	if(wbm_ack_i)
		last_dma <= wbm_adr_o;

reg old_busy;
always @(posedge sys_clk) begin
	if(sys_rst)
		old_busy <= 1'b0;
	else
		old_busy <= busy;
end

reg [13:0] vertex_counter;
reg [10:0] collision_counter;
reg [10:0] stray_counter;

wire csr_selected = csr_a[13:10] == csr_addr;

reg [31:0] csr_do_r;
reg csr_do_cont;
reg csr_do_regf;
reg csr_do_prog;

always @(posedge sys_clk) begin
	if(sys_rst) begin
		csr_do_r <= 32'd0;
		csr_do_cont <= 1'b0;
		csr_do_regf <= 1'b0;
		csr_do_prog <= 1'b0;
		irq <= 1'b0;
		start <= 1'b0;

		dma_base <= 29'd0;
		hmesh_last <= 7'd0;
		vmesh_last <= 7'd0;
		cp_page <= 2'd0;

		vertex_counter <= 14'd0;
		collision_counter <= 11'd0;
		stray_counter <= 11'd0;
	end else begin
		irq <= old_busy & ~busy;

		if(vnext) vertex_counter <= vertex_counter + 14'd1;
		if(err_collision) collision_counter <= collision_counter + 11'd1;
		if(err_stray) stray_counter <= stray_counter + 11'd1;

		csr_do_cont <= 1'b0;
		csr_do_prog <= 1'b0;
		csr_do_regf <= 1'b0;

		start <= 1'b0;

		/* Read control registers */
		case(csr_a[3:0])
			4'b0000: csr_do_r <= busy;

			4'b0001: csr_do_r <= {dma_base, 3'b000};
			4'b0010: csr_do_r <= hmesh_last;
			4'b0011: csr_do_r <= vmesh_last;

			4'b0100: csr_do_r <= cp_page;

			4'b0101: csr_do_r <= vertex_counter;
			4'b0110: csr_do_r <= collision_counter;
			4'b0111: csr_do_r <= stray_counter;
			4'b1000: csr_do_r <= last_dma;
			4'b1001: csr_do_r <= pc;

			default: csr_do_r <= 32'bx;
		endcase

		if(csr_selected) begin
			/* Generate enables for the one-hot mux on csr_do */
			csr_do_cont <= ~csr_a[8] & ~csr_a[9];
			csr_do_regf <= csr_a[8];
			csr_do_prog <= csr_a[9];

			/* Write control registers */
			if(
				csr_we		/* if this is a write cycle */
				& ~csr_a[8]	/* which is not for register file */
				& ~csr_a[9]	/* nor for program memory */
				)
			begin
				/* then it is for control registers */
				case(csr_a[2:0])
					3'b000: begin
						start <= csr_di[0];

						vertex_counter <= 14'd0;
						collision_counter <= 11'd0;
						stray_counter <= 11'd0;
					end
					3'b001: dma_base <= csr_di[31:3];
					3'b010: hmesh_last <= csr_di[6:0];
					3'b011: vmesh_last <= csr_di[6:0];
					3'b100: cp_page <= csr_di[1:0];
					default:;
				endcase
			end
		end
	end
end

/*
 * Program memory and register file have synchronous read,
 * so we must use some tricks to move the registers into them.
 */

assign csr_do =
	 ({32{csr_do_cont}} & csr_do_r)
	|({32{csr_do_prog}} & cp_di)
	|({32{csr_do_regf}} & cr_di);

assign cp_offset = csr_a[8:0];
assign cp_w_en = csr_selected & csr_a[9] & csr_we;
assign cp_do = csr_di;

assign cr_addr = csr_a[6:0];
assign cr_w_en = csr_selected & ~csr_a[9] & csr_a[8] & csr_we;
assign cr_do = csr_di;

endmodule

module parity_mux_and (
    input [7:0] in,  // 8-bit input for parity checker
    input [2:0] sel, // Select input for multiplexer
    input [3:0] data0, // 4-bit input for multiplexer
    input [3:0] data1, // 4-bit input for multiplexer
    input [3:0] data2, // 4-bit input for multiplexer
    input [3:0] data3, // 4-bit input for multiplexer
    input [3:0] data4, // 4-bit input for multiplexer
    input [3:0] data5, // 4-bit input for multiplexer
    output reg [3:0] out // 4-bit output from functional module
);

reg [8:0] parity_in; // 9-bit input for parity checker
reg parity_out; // Parity bit output from parity checker

// Parity checker module
always @(*) begin
    parity_in = {in, 1'b0}; // Add a 0 to the end of the input for parity calculation
    parity_out = ^parity_in; // Calculate odd parity
end

// Multiplexer module
always @(*) begin
    case (sel)
        3'b000: out = data0;
        3'b001: out = data1;
        3'b010: out = data2;
        3'b011: out = data3;
        3'b100: out = data4;
        3'b101: out = data5;
        default: out = 4'b0000; // Default output if select input is invalid
    endcase
end

// Functional module
always @(*) begin
    out = {parity_out, out[3:0]} & 4'b1111; // Bitwise AND of parity bit and multiplexer output
end

endmodule

module PWM (
  input clk,
  input [7:0] control,
  output pwm_out
);

parameter width = 256; // width of the PWM output waveform in clock cycles
parameter max_duty_cycle = 75; // maximum duty cycle of the output waveform, expressed as a percentage

reg [7:0] count;
reg [7:0] duty_cycle;
wire pwm;

assign pwm_out = pwm;

always @(posedge clk) begin
  if (count == width - 1) begin
    count <= 0;
  end else begin
    count <= count + 1;
  end

  if (count < (width * duty_cycle / 100)) begin
    pwm <= 1;
  end else begin
    pwm <= 0;
  end
end

always @(control) begin
  duty_cycle <= max_duty_cycle * control / 255;
end

endmodule

module butterfly (
  input signed [n-1:0] in1_real,
  input signed [n-1:0] in1_imag,
  input signed [n-1:0] in2_real,
  input signed [n-1:0] in2_imag,
  output signed [n-1:0] out1_real,
  output signed [n-1:0] out1_imag,
  output signed [n-1:0] out2_real,
  output signed [n-1:0] out2_imag,
  input twiddle_real,
  input twiddle_imag
);

  assign out1_real = in1_real + (twiddle_real * in2_real) - (twiddle_imag * in2_imag);
  assign out1_imag = in1_imag + (twiddle_real * in2_imag) + (twiddle_imag * in2_real);
  assign out2_real = in1_real - (twiddle_real * in2_real) + (twiddle_imag * in2_imag);
  assign out2_imag = in1_imag - (twiddle_real * in2_imag) - (twiddle_imag * in2_real);

endmodule
module FFT (
  input signed [n-1:0] in_real,
  input signed [n-1:0] in_imag,
  output [n-1:0] out_real,
  output [n-1:0] out_imag
);

  parameter n = 16;
  parameter m = 4;

  wire [n-1:0] fft_stage_1_real;
  wire [n-1:0] fft_stage_1_imag;
  wire [n-1:0] fft_stage_2_real;
  wire [n-1:0] fft_stage_2_imag;
  wire [n-1:0] fft_stage_3_real;
  wire [n-1:0] fft_stage_3_imag;
  wire [n-1:0] fft_stage_4_real;
  wire [n-1:0] fft_stage_4_imag;

  // Stage 1
  generate
    genvar i;
    for (i = 0; i < n/2; i = i + 1) begin : stage_1
      butterfly bfly (
        .in1_real(in_real[i]),
        .in1_imag(in_imag[i]),
        .in2_real(in_real[i+n/2]),
        .in2_imag(in_imag[i+n/2]),
        .out1_real(fft_stage_1_real[i]),
        .out1_imag(fft_stage_1_imag[i]),
        .out2_real(fft_stage_1_real[i+n/2]),
        .out2_imag(fft_stage_1_imag[i+n/2]),
        .twiddle_real(cos(2 * $PI * i / n)),
        .twiddle_imag(-sin(2 * $PI * i / n))
      );
    end
  endgenerate

  // Stage 2
  generate
    genvar i;
    for (i = 0; i < n/4; i = i + 1) begin : stage_2
      butterfly bfly (
        .in1_real(fft_stage_1_real[i]),
        .in1_imag(fft_stage_1_imag[i]),
        .in2_real(fft_stage_1_real[i+n/4]),
        .in2_imag(fft_stage_1_imag[i+n/4]),
        .out1_real(fft_stage_2_real[i]),
        .out1_imag(fft_stage_2_imag[i]),
        .out2_real(fft_stage_2_real[i+n/4]),
        .out2_imag(fft_stage_2_imag[i+n/4]),
        .twiddle_real(cos(2 * $PI * i / (n/2))),
        .twiddle_imag(-sin(2 * $PI * i / (n/2)))
      );
    end
  endgenerate

  // Stage 3
  generate
    genvar i;
    for (i = 0; i < n/8; i = i + 1) begin : stage_3
      butterfly bfly (
        .in1_real(fft_stage_2_real[i]),
        .in1_imag(fft_stage_2_imag[i]),
        .in2_real(fft_stage_2_real[i+n/8]),
        .in2_imag(fft_stage_2_imag[i+n/8]),
        .out1_real(fft_stage_3_real[i]),
        .out1_imag(fft_stage_3_imag[i]),
        .out2_real(fft_stage_3_real[i+n/8]),
        .out2_imag(fft_stage_3_imag[i+n/8]),
        .twiddle_real(cos(2 * $PI * i / (n/4))),
        .twiddle_imag(-sin(2 * $PI * i / (n/4)))
      );
    end
  endgenerate

  // Stage 4
  generate
    genvar i;
    for (i = 0; i < n/16; i = i + 1) begin : stage_4
      butterfly bfly (
        .in1_real(fft_stage_3_real[i]),
        .in1_imag(fft_stage_3_imag[i]),
        .in2_real(fft_stage_3_real[i+n/16]),
        .in2_imag(fft_stage_3_imag[i+n/16]),
        .out1_real(fft_stage_4_real[i]),
        .out1_imag(fft_stage_4_imag[i]),
        .out2_real(fft_stage_4_real[i+n/16]),
        .out2_imag(fft_stage_4_imag[i+n/16]),
        .twiddle_real(cos(2 * $PI * i / (n/8))),
        .twiddle_imag(-sin(2 * $PI * i / (n/8)))
      );
    end
  endgenerate

  assign out_real[0] = fft_stage_4_real[0];
  assign out_imag[0] = fft_stage_4_imag[0];

  // Stage 5
  generate
    genvar i;
    for (i = 0; i < n/16; i = i + 1) begin : stage_5
      butterfly bfly (
        .in1_real(fft_stage_4_real[i+n/16]),
        .in1_imag(fft_stage_4_imag[i+n/16]),
        .in2_real(fft_stage_4_real[i]),
        .in2_imag(fft_stage_4_imag[i]),
        .out1_real(out_real[i+1]),
        .out1_imag(out_imag[i+1]),
        .out2_real(out_real[i+(n/16)+1]),
        .out2_imag(out_imag[i+(n/16)+1]),
        .twiddle_real(cos(2 * $PI * i / n)),
        .twiddle_imag(-sin(2 * $PI * i / n))
      );
    end
  endgenerate

endmodule

module NIOS_SYSTEMV3_JTAG_UART_sim_scfifo_r (
    input clk,
    input fifo_rd,
    input rst_n,
    output fifo_EF,
    output [7:0] fifo_rdata,
    output rfifo_full,
    output [5:0] rfifo_used
);

    reg [31:0] bytes_left;
    wire fifo_EF;
    reg fifo_rd_d;
    wire [7:0] fifo_rdata;
    wire new_rom;
    wire [31:0] num_bytes;
    wire [6:0] rfifo_entries;
    wire rfifo_full;
    wire [5:0] rfifo_used;

    // Generate rfifo_entries
    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            bytes_left <= 32'h0;
            fifo_rd_d <= 1'b0;
        end else begin
            fifo_rd_d <= fifo_rd;
            // decrement on read
            if (fifo_rd_d) begin
                bytes_left <= bytes_left - 1'b1;
            end
            // catch new contents
            if (new_rom) begin
                bytes_left <= num_bytes;
            end
        end
    end

    // Calculate FIFO buffer status
    assign fifo_EF = (bytes_left == 32'h0);
    assign rfifo_full = (bytes_left > 7'h40);
    assign rfifo_entries = (rfifo_full) ? 7'h40 : bytes_left;
    assign rfifo_used = rfifo_entries[5:0];

    // Set unused outputs to default values
    assign new_rom = 1'b0;
    assign num_bytes = 32'b0;
    assign fifo_rdata = 8'b0;

endmodule

