module sync_transmitter(
  input clk,
  input TxD_start,
  input [7:0] TxD_data,
  output TxD,
  output TxD_busy
);

  parameter ClkFrequency = 50000000;  // 50 MHz
  parameter Baud = 115200;  // 115.2 kbps

  wire BitTick;

  // Generate a tick signal at the baud rate
  BaudTickGen #(ClkFrequency, Baud) tickgen(.clk(clk), .enable(TxD_busy), .tick(BitTick));

  // State machine for transmitting data
  reg [3:0] TxD_state = 0;
  reg [7:0] TxD_shift = 0;

  always @(posedge clk) begin
    if (TxD_start && (TxD_state == 0)) begin
      // Start a new transmission
      TxD_shift <= TxD_data;
      TxD_state <= 1;
      TxD_busy <= 1;
    end else if (TxD_state[3] && BitTick) begin
      // Shift data out on each tick
      TxD_shift <= TxD_shift >> 1;
      if (TxD_state == 15) begin
        // End of transmission
        TxD_state <= 0;
        TxD_busy <= 0;
      end else begin
        // Advance to the next state
        TxD_state <= TxD_state + 1;
      end
    end
  end

  assign TxD = (TxD_state == 0) ? 1'b1 :
               (TxD_state == 9) ? 1'b0 :
               (TxD_state == 10) ? 1'b0 :
               (TxD_state < 9) ? TxD_shift[7-TxD_state] :
               (TxD_state < 15) ? 1'b1 : 1'b0;

endmodule

