module spectral_subtraction (
  input signed [15:0] in,
  input signed [15:0] noise_ref,
  output signed [15:0] out
);

parameter fft_size = 1024;
parameter alpha = 0.01;

// Define internal signals
reg signed [15:0] in_buf [0:fft_size-1];
reg signed [15:0] noise_ref_buf [0:fft_size-1];
reg signed [31:0] noise_psd [0:fft_size-1];
reg signed [31:0] noisy_psd [0:fft_size-1];
reg signed [31:0] filtered_psd [0:fft_size-1];
reg signed [31:0] filter_taps [0:fft_size-1];
reg signed [31:0] filter_error;
reg signed [31:0] filter_input [0:fft_size-1];
reg signed [31:0] filter_output [0:fft_size-1];
reg signed [31:0] filter_inv [0:fft_size-1];
reg signed [31:0] filter_covar [0:fft_size-1];
reg signed [31:0] filter_gain [0:fft_size-1];
reg signed [31:0] filter_forgetting_factor = 32767; // 0.9999 in Q15 format

// Instantiate FFT module
FFT #(.FFT_SIZE(fft_size), .DATA_WIDTH(16)) fft(
  .in({in_buf, {16'd0}}),
  .out({noisy_psd, {16'd0}})
);

// Instantiate FFT module for noise reference signal
FFT #(.FFT_SIZE(fft_size), .DATA_WIDTH(16)) fft_noise(
  .in({noise_ref_buf, {16'd0}}),
  .out({noise_psd, {16'd0}})
);

// Compute power spectral density of noise
always @ (posedge clk) begin
  noise_ref_buf <= {noise_ref_buf[1:fft_size-1], noise_ref};
end

// Compute power spectral density of noisy signal
always @ (posedge clk) begin
  in_buf <= {in_buf[1:fft_size-1], in};
end

// Subtract noise PSD from noisy PSD to get filtered PSD
always @ (posedge clk) begin
  for (i = 0; i < fft_size; i = i + 1) begin
    filtered_psd[i] <= (noisy_psd[i] - noise_psd[i]) >> 1;
  end
end

// Implement adaptive filter using recursive least squares algorithm
always @ (posedge clk) begin
  filter_error <= in - filter_output[0];
  filter_input <= {filtered_psd, {16'd0}};

  // Update filter taps
  for (i = 0; i < fft_size; i = i + 1) begin
    filter_inv[i] <= filter_inv[i] - (filter_covar[i] * filter_input[i]) / filter_forgetting_factor;
    filter_covar[i] <= filter_covar[i] / filter_forgetting_factor;
    filter_gain[i] <= filter_covar[i] * filter_input[i];
    filter_taps[i] <= filter_taps[i] + (filter_gain[i] * filter_error);
    filter_covar[i] <= filter_covar[i] - (filter_gain[i] * filter_input[i] * filter_covar[i]) / filter_forgetting_factor;
  end

  // Compute filter output
  filter_output <= {filter_taps, {16'd0}};
end

// Output filtered signal
assign out = filter_output[0];

endmodule

