module top_module (
    input [3:0] A, B, // Input for the magnitude comparator
    input [15:0] data_in, // Input for the binary ones counter
    input select, // Select input to choose between comparator and counter
    output [3:0] ones_count, // Output from the binary ones counter
    output [1:0] final_output // Final output based on the rules mentioned above
);

    wire EQ, GT, LT; // Output signals from the magnitude comparator

    // Instantiate the magnitude comparator module
    magnitude_comparator comparator(
        .A(A),
        .B(B),
        .EQ(EQ),
        .GT(GT),
        .LT(LT)
    );

    wire [15:0] ones_count_raw; // Output from the binary ones counter

    // Instantiate the binary ones counter module
    binary_ones_counter counter(
        .data_in(data_in),
        .ones_count_raw(ones_count_raw)
    );

    wire [3:0] ones_count_temp; // Temporary variable for the ones count output

    // Assign the ones count output based on the select input
    assign ones_count_temp = select ? ones_count_raw : 4'bzzzz;

    // Instantiate the control logic module
    control_logic control(
        .EQ(EQ),
        .GT(GT),
        .LT(LT),
        .ones_count_temp(ones_count_temp),
        .final_output(final_output)
    );

    // Assign the ones count output based on the select input
    assign ones_count = select ? ones_count_raw : 4'bzzzz;

endmodule

module magnitude_comparator (
    input [3:0] A, B, // Input signals
    output EQ, GT, LT // Output signals
);

    assign EQ = (A == B);
    assign GT = (A > B);
    assign LT = (A < B);

endmodule

module binary_ones_counter (
    input [15:0] data_in, // Input signal
    output [3:0] ones_count_raw // Output signal
);

    assign ones_count_raw = {4{1'b0}} + data_in;

endmodule

module control_logic (
    input EQ, GT, LT, // Input signals
    input [3:0] ones_count_temp, // Input signal from the binary ones counter
    output [1:0] final_output // Output signal based on the rules mentioned above
);

    always @(*) begin
        if (EQ) begin
            final_output = ones_count_temp;
        end else if (GT) begin
            final_output = ones_count_temp + 1;
        end else begin // LT
            final_output = ones_count_temp - 1;
        end
    end

endmodule

module sky130_fd_sc_hdll__sdfrtp (
    Q      ,
    CLK    ,
    D      ,
    SCD    ,
    SCE    ,
    RESET_B,
    VPWR   ,
    VGND   ,
    VPB    ,
    VNB
);

    output Q      ;
    input  CLK    ;
    input  D      ;
    input  SCD    ;
    input  SCE    ;
    input  RESET_B;
    input  VPWR   ;
    input  VGND   ;
    input  VPB    ;
    input  VNB    ;

    reg Q;
    reg [1:0] count;
    wire [1:0] rate;

    assign rate = {SCD, SCE};

    always @(posedge CLK, negedge RESET_B) begin
        if (!RESET_B) begin
            Q <= 1'b0;
            count <= 2'b00;
        end else if (SCE) begin
            case (rate)
                2'b00: begin
                    if (count == 2'b00) begin
                        Q <= D[0];
                        count <= 2'b01;
                    end else if (count == 2'b01) begin
                        Q <= D[1];
                        count <= 2'b00;
                    end
                end
                2'b01: begin
                    if (count == 2'b00) begin
                        Q <= D[0];
                        count <= 2'b01;
                    end else if (count == 2'b01) begin
                        Q <= D[1];
                        count <= 2'b10;
                    end else if (count == 2'b10) begin
                        Q <= D[2];
                        count <= 2'b11;
                    end else if (count == 2'b11) begin
                        Q <= D[3];
                        count <= 2'b00;
                    end
                end
            endcase
        end
    end
endmodule

