always @(posedge clk) begin
    Q_reg2 <= Q_reg1;
end

always @(posedge clk) begin
    if (load) begin
        Q_reg1 <= input_data;
    end else begin
        if (up_down) begin
            Q_reg1 <= Q_reg2 + 1;
        end else begin
            Q_reg1 <= Q_reg2 - 1;
        end
    end
end

assign Q = Q_reg2;

endmodule

module four_bit_full_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout
);

    wire [3:0] xor_out;
    wire [3:0] and_out;
    wire [3:0] or_out;

    // Calculate the XOR of A and B
    assign xor_out = A ^ B;

    // Calculate the AND of A and B
    assign and_out = A & B;

    // Calculate the OR of the AND of A and B and Cin
    assign or_out = (A & B) | (Cin & A) | (Cin & B);

    // Calculate the sum and carry-out
    assign Sum = xor_out ^ Cin;
    assign Cout = or_out[3];

endmodule

module SoundCtrlMX (
  input wire iClock, // CPU CLOCK, 4194304Hz
  input wire iReset,
  input wire iOsc262k, // OSC2 clock 131072Hz
  input wire [4:0] iOut1, // Channel 1.
  input wire [4:0] iOut2, // Channel 2.
  input wire [4:0] iOut3, // Channel 3.
  input wire [4:0] iOut4, // Channel 4.
  input wire [7:0] iNR50, // Left/Right enable + Left/Right volume.
  input wire [7:0] iNR51, // Enable channel 1/2/3/4 in Left/Right.
  output reg [4:0] oSO1, // Left channel.
  output reg [4:0] oSO2, // Right channel.
  output wire [1:0] oChSel,
  output wire oChClk
);

reg [7:0] rNR50, rNR51;
reg [4:0] rSO1_PRE, rSO2_PRE;
reg rSer_clk; // 8kHz clock, used for serializer.
reg [1:0] rSer_sel; // Indicates which channel data were sent.

//Registers load
always @ (posedge iClock) begin
  if (iReset) begin
    rNR50 <= iNR50;
    rNR51 <= iNR51;
    rSer_sel <= 2'b0;
    rSer_clk <= 1'b0;
    rSO1_PRE <= 5'd15;
    rSO2_PRE <= 5'd15;
  end
end

//Serializer
always @ (posedge iOsc262k) begin
  rSer_clk <= ~rSer_clk;
  rSer_sel <= (~rSer_clk) ? rSer_sel + 1 : rSer_sel;
end

//Volume control
always @ (*) begin
  case (rSer_sel)
    2'd0: begin
      rSO1_PRE = (rNR51[0]) ? iOut1 : 5'd15;
      rSO2_PRE = (rNR51[4]) ? iOut1 : 5'd15;
    end
    2'd1: begin
      rSO1_PRE = (rNR51[1]) ? iOut2 : 5'd15;
      rSO2_PRE = (rNR51[5]) ? iOut2 : 5'd15;
    end
    2'd2: begin
      rSO1_PRE = (rNR51[2]) ? iOut3 : 5'd15;
      rSO2_PRE = (rNR51[6]) ? iOut3 : 5'd15;
    end
    2'd3: begin
      rSO1_PRE = (rNR51[3]) ? iOut4 : 5'd15;
      rSO2_PRE = (rNR51[7]) ? iOut4 : 5'd15;
    end
    default: begin
      rSO1_PRE = 5'dX;
      rSO2_PRE = 5'dX;
    end
  endcase

  oSO1 = rSO1_PRE >> (3'd7-rNR50[2:0]);
  oSO2 = rSO1_PRE >> (3'd7-rNR50[6:4]);
end

assign oChSel = rSer_sel;
assign oChClk = rSer_clk;

endmodule

module t(
	input clk_sys,
	input _0_t,
	input taa,
	input tab,
	input trb,
	input clockta,
	input clocktb,
	input clocktc,
	input t_1_d,
	input [0:39] k,
	input m_1,
	output reg [-1:39] t
);

	always @ (posedge clk_sys, posedge _0_t) begin
		if (_0_t) t[0:15] <= 0;
		else if (clockta) case ({~tab, ~taa})
			2'b00: t[0:15] <= t[0:15];
			2'b01: t[0:15] <= t[-1:14];
			2'b10: t[0:15] <= t[1:16];
			2'b11: t[0:15] <= k[0:15];
		endcase
	end

	always @ (posedge clk_sys, posedge _0_t) begin
		if (_0_t) t[16:31] <= 0;
		else if (clocktb) case ({~trb, ~taa})
			2'b00: t[16:31] <= t[16:31];
			2'b01: t[16:31] <= t[15:30];
			2'b10: t[16:31] <= t[17:32];
			2'b11: t[16:31] <= k[16:31];
		endcase
	end

	always @ (posedge clk_sys, posedge _0_t) begin
		if (_0_t) t[32:39] <= 0;
		else if (clocktc) case ({~trb, ~taa})
			2'b00: t[32:39] <= t[32:39];
			2'b01: t[32:39] <= t[31:38];
			2'b10: t[32:39] <= {t[33:39], m_1};
			2'b11: t[32:39] <= k[32:39];
		endcase
	end

	always @ (posedge clk_sys, posedge _0_t) begin
		if (_0_t) t[-1] <= 1'b0;
		else if (clockta) t[-1] <= t_1_d;
	end

endmodule

