module fifo_99x128 (
    input clock,
    input [98:0] data,
    input rdreq,
    input wrreq,
    output empty,
    output full,
    output [98:0] q,
    output reg [6:0] usedw
);

    reg [98:0] fifo [0:98];
    reg [6:0] read_addr;
    reg [6:0] write_addr;
    reg [6:0] next_write_addr;
    reg [6:0] usedw_reg;
    wire [6:0] usedw_wire;
    reg [98:0] q_reg;
    wire [98:0] q_wire;
    reg empty_reg;
    reg full_reg;
    wire empty_wire;
    wire full_wire;

    assign usedw_wire = usedw_reg;
    assign q_wire = q_reg;
    assign empty_wire = empty_reg;
    assign full_wire = full_reg;

    always @(posedge clock) begin
        if (wrreq && !full_reg) begin
            fifo[write_addr] <= data;
            next_write_addr <= write_addr + 1;
        end else begin
            next_write_addr <= write_addr;
        end

        if (rdreq && !empty_reg) begin
            q_reg <= fifo[read_addr];
            read_addr <= read_addr + 1;
        end

        usedw_reg <= next_write_addr - read_addr;
        write_addr <= next_write_addr;

        empty_reg <= (usedw_reg == 0);
        full_reg <= (usedw_reg == 99);
    end

    assign usedw = usedw_wire;
    assign q = q_wire;
    assign empty = empty_wire;
    assign full = full_wire;

endmodule

module adder16(A, B, Cin, Sum, Cout);
  input [15:0] A;
  input [15:0] B;
  input Cin;
  output [15:0] Sum;
  output Cout;

  wire [15:0] carry;
  wire [15:0] temp_sum;

  assign temp_sum[0] = A[0] ^ B[0] ^ Cin;
  assign carry[0] = (A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin);

  genvar i;
  generate
    for(i = 1; i < 16; i = i + 1) begin : adder_loop
      assign temp_sum[i] = A[i] ^ B[i] ^ carry[i-1];
      assign carry[i] = (A[i] & B[i]) | (A[i] & carry[i-1]) | (B[i] & carry[i-1]);
    end
  endgenerate

  assign Sum = temp_sum;
  assign Cout = carry[15];

endmodule

module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Z,
    output Cout
);

    wire [3:0] sum;
    wire c1, c2, c3;

    // Full adder for bit 0
    xor(sum[0], A[0], B[0], Cin);
    and(c1, A[0], B[0]);
    and(c2, A[0], Cin);
    and(c3, B[0], Cin);
    or(Cout, c1, c2, c3);

    // Full adder for bit 1
    xor(sum[1], A[1], B[1], c1);
    and(c1, A[1], B[1]);
    and(c2, A[1], c1);
    and(c3, B[1], c1);
    or(Cout, Cout, c2, c3);

    // Full adder for bit 2
    xor(sum[2], A[2], B[2], c1);
    and(c1, A[2], B[2]);
    and(c2, A[2], c1);
    and(c3, B[2], c1);
    or(Cout, Cout, c2, c3);

    // Full adder for bit 3
    xor(sum[3], A[3], B[3], c1);
    and(c1, A[3], B[3]);
    and(c2, A[3], c1);
    and(c3, B[3], c1);
    or(Cout, Cout, c2, c3);

    assign Z = sum;

endmodule

module decade_counter (
