    if (reset) begin
        count <= 4'b0;
        q <= 4'b0;
    end else if (pause) begin
        count <= count;
        q <= q;
    end else if (resume) begin
        count <= count;
        q <= q;
    end else begin
        count <= count + 1;
        q <= count;
    end
end

