module top_module (
    input [7:0] anyedge_in, // 8-bit input for the anyedge module
    input [15:0] split_in, // 16-bit input for the split module
    output reg [7:0] sum // 8-bit output for the sum of the two inputs
);

    // Anyedge module
    reg [7:0] anyedge_out;
    always @(*) begin
        anyedge_out = anyedge_in & (~anyedge_in << 1);
    end

    // Split module
    reg [7:0] split_upper;
    reg [7:0] split_lower;
    always @(*) begin
        split_upper = split_in[15:8];
        split_lower = split_in[7:0];
    end

    // Sum module
    always @(*) begin
        sum = anyedge_out + split_upper + split_lower;
    end

endmodule

module mux (
    input [2:0] in,
    input enable,
    output reg out
);

always @ (in or enable) begin
    if (enable) begin
        casez (in)
            3'b000: out = in[0];
            3'b001: out = in[1];
            3'b010: out = in[2];
            3'b011: out = in[0];
            3'b100: out = in[1];
            3'b101: out = in[2];
            default: out = 1'b0;
        endcase
    end else begin
        out = 1'b0;
    end
end

endmodule

module division_module (
    input clk,
    input reset,
    input [15:0] D,
    input [15:0] V,
    output reg [15:0] Q,
    output reg [15:0] R
);

    reg [15:0] dividend;
    reg [15:0] divisor;
    reg [15:0] quotient;
    reg [15:0] remainder;
    reg [3:0] i;

    always @(posedge clk) begin
        if (reset) begin
            quotient <= 0;
            remainder <= 0;
        end else begin
            dividend <= D;
            divisor <= V;
            quotient <= 0;
            remainder <= 0;
            for (i = 15; i >= 0; i = i - 1) begin
                remainder <= remainder << 1;
                remainder[0] <= dividend[i];
                if (remainder >= divisor) begin
                    remainder <= remainder - divisor;
                    quotient[i] <= 1;
                end
            end
        end
    end

    assign Q = quotient;
    assign R = remainder;

endmodule

module up_down_counter (
    input clk,
    input reset,
    input UP,
    input DOWN,
    input EN,
    output reg [2:0] C
);

    reg [2:0] count;

    always @(posedge clk or negedge reset) begin
        if (!reset) begin
            count <= 0;
        end else if (EN) begin
            if (UP) begin
                count <= count + 1;
            end else if (DOWN) begin
                count <= count - 1;
            end
        end
    end

    assign C = count;

endmodule

module control_logic (
    input clk,
