    input [15:0] D,
    input [15:0] V,
    input UP,
    input DOWN,
    input EN,
    input SEL,
    output reg [15:0] O
);

    wire [15:0] quotient;
    wire [15:0] remainder;
    wire [2:0] count;
    wire [15:0] sum;

    division_module div (
        .clk(clk),
        .reset(reset),
        .D(D),
        .V(V),
        .Q(quotient),
        .R(remainder)
    );

    up_down_counter counter (
        .clk(clk),
        .reset(!SEL),
        .UP(UP),
        .DOWN(DOWN),
        .EN(EN),
        .C(count)
    );

    always @(posedge clk) begin
        if (SEL) begin
            sum <= remainder + count;
        end else begin
            sum <= quotient + count;
        end
        O <= sum[7:0];
    end

endmodule

