module three_input_op (
    Y,
    A,
    B,
    C,
    op,
    sel
);

    output Y;
    input A;
    input B;
    input C;
    input [1:0] op;
    input sel;

    wire [2:0] input_signals;
    wire [1:0] selected_signals;
    wire [2:0] and_results;
    wire [2:0] or_results;
    wire [2:0] xor_results;
    wire [2:0] xnor_results;

    // Assign the input signals based on the sel signal
    assign input_signals[0] = (sel == 0) ? A : B;
    assign input_signals[1] = B;
    assign input_signals[2] = (sel == 1) ? C : B;

    // Perform the AND operation on the input signals
    assign and_results[0] = input_signals[0] & input_signals[1];
    assign and_results[1] = input_signals[1] & input_signals[2];
    assign and_results[2] = input_signals[2] & input_signals[0];

    // Perform the OR operation on the input signals
    assign or_results[0] = input_signals[0] | input_signals[1];
    assign or_results[1] = input_signals[1] | input_signals[2];
    assign or_results[2] = input_signals[2] | input_signals[0];

    // Perform the XOR operation on the input signals
    assign xor_results[0] = input_signals[0] ^ input_signals[1];
    assign xor_results[1] = input_signals[1] ^ input_signals[2];
    assign xor_results[2] = input_signals[2] ^ input_signals[0];

    // Perform the XNOR operation on the input signals
    assign xnor_results[0] = ~(input_signals[0] ^ input_signals[1]);
    assign xnor_results[1] = ~(input_signals[1] ^ input_signals[2]);
    assign xnor_results[2] = ~(input_signals[2] ^ input_signals[0]);

    // Determine which two input signals to use based on the sel signal
    assign selected_signals = (sel == 0) ? 2'b00 : 2'b10;

    // Perform the operation based on the op signal
    always @(*) begin
        case (op)
            2'b00: Y = and_results[selected_signals];
            2'b01: Y = or_results[selected_signals];
            2'b10: Y = xor_results[selected_signals];
            2'b11: Y = xnor_results[selected_signals];
            default: Y = 1'b0;
        endcase
    end

endmodule

module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    output [3:0] R,
    output Cout
);

    wire [3:0] sum;
    wire [3:0] carry;

    // Full adder instance
    full_adder FA0(A[0], B[0], 1'b0, sum[0], carry[0]);
    full_adder FA1(A[1], B[1], carry[0], sum[1], carry[1]);
    full_adder FA2(A[2], B[2], carry[1], sum[2], carry[2]);
    full_adder FA3(A[3], B[3], carry[2], sum[3], Cout);

    assign R = sum;

endmodule

// Full adder module
module full_adder (
    input A,
    input B,
    input Cin,
    output S,
    output Cout
);

    assign S = A ^ B ^ Cin;
    assign Cout = (A & B) | (Cin & (A ^ B));

endmodule

module signal_combiner (
    input [7:0] input_signals,
    output output_signal
);

    wire [7:0] input_signals_inverted;
    assign input_signals_inverted = ~input_signals;

    wire [3:0] num_ones;
    assign num_ones = {
        input_signals_inverted[0] & input_signals[1],
        input_signals_inverted[1] & input_signals[2],
        input_signals_inverted[2] & input_signals[3],
        input_signals_inverted[3] & input_signals[4],
        input_signals_inverted[4] & input_signals[5],
        input_signals_inverted[5] & input_signals[6],
        input_signals_inverted[6] & input_signals[7],
        input_signals_inverted[7]
    };

    wire at_least_four_ones;
    assign at_least_four_ones = (num_ones[0] + num_ones[1] + num_ones[2] + num_ones[3] + num_ones[4] + num_ones[5] + num_ones[6] + num_ones[7]) >= 4;

    assign output_signal = at_least_four_ones;

endmodule

module vending_machine(
    input clk,
    input reset,
    input [1:0] coin,
    input [1:0] product,
    input dispense,
    output reg dispensed,
    output reg [5:0] change,
    output reg [1:0] product_dispensed,
    output reg [5:0] amount_inserted
);

// State machine states
parameter IDLE = 2'b00;
parameter COIN_INSERTED = 2'b01;
parameter PRODUCT_SELECTED = 2'b10;
parameter DISPENSING = 2'b11;

// Internal signals
reg [1:0] current_state, next_state;
reg [5:0] total_inserted;
reg [5:0] price_a, price_b, price_c, price_d;
reg [5:0] change_due;
reg [2:0] coins_due;

// Set initial values
initial begin
    current_state = IDLE;
    next_state = IDLE;
    total_inserted = 0;
    price_a = 50;
    price_b = 75;
    price_c = 100;
    price_d = 125;
    change_due = 0;
    coins_due = 0;
end

// State machine
always @(posedge clk) begin
    if (reset) begin
        current_state <= IDLE;
        total_inserted <= 0;
        dispensed <= 0;
        change <= 0;
        product_dispensed <= 0;
        amount_inserted <= 0;
    end else begin
        current_state <= next_state;
        case (current_state)
            IDLE: begin
                if (coin != 2'b00 || product != 2'b00) begin
                    next_state = COIN_INSERTED;
                end else begin
                    next_state = IDLE;
                end
            end
            COIN_INSERTED: begin
                total_inserted <= total_inserted + (coin == 2'b00 ? 5 : (coin == 2'b01 ? 10 : 25));
                amount_inserted <= total_inserted;
                if (product != 2'b00) begin
                    next_state = PRODUCT_SELECTED;
                end else begin
                    next_state = COIN_INSERTED;
                end
            end
            PRODUCT_SELECTED: begin
                case (product)
                    2'b00: begin
                        if (total_inserted >= price_a) begin
                            change_due <= total_inserted - price_a;
                            next_state = DISPENSING;
                            product_dispensed <= 2'b00;
                        end else begin
                            coins_due <= price_a - total_inserted;
                            next_state = COIN_INSERTED;
                        end
                    end
                    2'b01: begin
                        if (total_inserted >= price_b) begin
                            change_due <= total_inserted - price_b;
                            next_state = DISPENSING;
                            product_dispensed <= 2'b01;
                        end else begin
                            coins_due <= price_b - total_inserted;
                            next_state = COIN_INSERTED;
                        end
                    end
                    2'b10: begin
                        if (total_inserted >= price_c) begin
                            change_due <= total_inserted - price_c;
                            next_state = DISPENSING;
                            product_dispensed <= 2'b10;
                        end else begin
                            coins_due <= price_c - total_inserted;
                            next_state = COIN_INSERTED;
                        end
                    end
                    2'b11: begin
                        if (total_inserted >= price_d) begin
                            change_due <= total_inserted - price_d;
                            next_state = DISPENSING;
                            product_dispensed <= 2'b11;
                        end else begin
                            coins_due <= price_d - total_inserted;
                            next_state = COIN_INSERTED;
                        end
                    end
                endcase
            end
            DISPENSING: begin
                dispensed <= dispense;
                if (dispense) begin
                    next_state = IDLE;
                    change <= change_due;
                    total_inserted <= 0;
                end else begin
                    next_state = DISPENSING;
                end
            end
        endcase
    end
end

endmodule

