module profibus_master (
  input clk,
  input reset_n,
  input [7:0] req_data,
  input req_valid,
  output [7:0] resp_data,
  output req_ready,
  output resp_valid,
  input resp_ack
);

  reg [7:0] req_data_reg;
  reg req_valid_reg;
  reg resp_valid_reg;
  reg resp_ack_reg;
  wire req_ready_wire;

  assign req_ready = ~req_valid_reg;
  assign resp_data = req_data_reg;

  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      req_data_reg <= 8'b0;
      req_valid_reg <= 1'b0;
      resp_valid_reg <= 1'b0;
      resp_ack_reg <= 1'b0;
    end else begin
      if (req_valid && ~req_valid_reg && req_ready_wire) begin
        req_data_reg <= req_data;
        req_valid_reg <= 1'b1;
      end else begin
        req_valid_reg <= 1'b0;
      end

      if (resp_ack && resp_valid_reg) begin
        resp_valid_reg <= 1'b0;
        resp_ack_reg <= 1'b0;
      end else if (~resp_valid_reg && req_valid_reg) begin
        resp_valid_reg <= 1'b1;
      end
    end
  end

endmodule

