    if (~reset_n) begin
      resp_data_reg <= 8'b0;
      req_valid_reg <= 1'b0;
      resp_valid_reg <= 1'b0;
      resp_ack_reg <= 1'b0;
    end else begin
      if (req_ready && ~req_valid_reg) begin
        req_valid_reg <= 1'b1;
        req_data_reg <= req_data_wire;
      end else begin
        req_valid_reg <= 1'b0;
      end

      if (resp_valid && ~resp_valid_reg) begin
        resp_data_reg <= resp_data;
        resp_valid_reg <= 1'b1;
        resp_ack_reg <= 1'b1;
      end else begin
        resp_valid_reg <= 1'b0;
        resp_ack_reg <= 1'b0;
      end
    end
  end

endmodule

