module elevator(
    input clk,
    input reset,
    input [7:0] floor_requests,
    input [3:0] current_floor,
    output [3:0] elevator_floor,
    output [1:0] elevator_direction,
    output arrived
    );

    // Internal signals
    reg [3:0] next_floor;
    reg [1:0] direction;
    reg arrived;

    // Elevator state
    reg [3:0] elevator_floor;
    reg [1:0] elevator_direction;

    // Constants
    parameter UP = 2'b01;
    parameter DOWN = 2'b10;
    parameter STATIONARY = 2'b00;

    // Initialize elevator state
    initial begin
        elevator_floor = 4'b0000;
        elevator_direction = STATIONARY;
    end

    always @(posedge clk) begin
        if (reset) begin
            elevator_floor <= 4'b0000;
            elevator_direction <= STATIONARY;
            arrived <= 1'b0;
        end else begin
            // Check if we have arrived at a floor
            if (elevator_floor == next_floor) begin
                arrived <= 1'b1;
                elevator_direction <= STATIONARY;
            end else begin
                arrived <= 1'b0;
            end

            // Determine direction
            if (floor_requests > elevator_floor) begin
                direction = UP;
            end else if (floor_requests < elevator_floor) begin
                direction = DOWN;
            end else begin
                direction = STATIONARY;
            end

            // Determine next floor
            if (direction == UP) begin
                next_floor = $onehot0(floor_requests[elevator_floor+1:7]);
            end else if (direction == DOWN) begin
                next_floor = $onehot0(floor_requests[0:elevator_floor-1]);
            end else begin
                next_floor = elevator_floor;
            end

            // Update elevator state
            elevator_floor <= next_floor;
            elevator_direction <= direction;
        end
    end

endmodule

