module Adder4(
    input [3:0] A,
    input [3:0] B,
    output [4:0] S
);

  wire [0:0] Q1, Q2, Q3, Q4, Q5;
  wire [0:0] ready_add_subt1, ready_add_subt2, ready_add_subt3, ready_add_subt4;

  RegisterAdd__parameterized22 RA1(.Q(Q1), .CLK(CLK), .AR(1'b0), .ready_add_subt(ready_add_subt1));
  RegisterAdd__parameterized22 RA2(.Q(Q2), .CLK(CLK), .AR(1'b0), .ready_add_subt(ready_add_subt2));
  RegisterAdd__parameterized22 RA3(.Q(Q3), .CLK(CLK), .AR(1'b0), .ready_add_subt(ready_add_subt3));
  RegisterAdd__parameterized22 RA4(.Q(Q4), .CLK(CLK), .AR(1'b0), .ready_add_subt(ready_add_subt4));
  RegisterAdd__parameterized22 RA5(.Q(Q5), .CLK(CLK), .AR(1'b0), .ready_add_subt(S[4]));

  assign S[0] = Q1[0];
  assign S[1] = Q2[0];
  assign S[2] = Q3[0];
  assign S[3] = Q4[0];

  assign ready_add_subt1 = 1'b1;
  assign ready_add_subt2 = ready_add_subt1;
  assign ready_add_subt3 = ready_add_subt2;
  assign ready_add_subt4 = ready_add_subt3;

  assign RA1.AR = ~ready_add_subt1;
  assign RA2.AR = ~(ready_add_subt1 & ready_add_subt2);
  assign RA3.AR = ~(ready_add_subt1 & ready_add_subt2 & ready_add_subt3);
  assign RA4.AR = ~(ready_add_subt1 & ready_add_subt2 & ready_add_subt3 & ready_add_subt4);

  assign RA1.Q = A[0] ^ B[0];
  assign RA2.Q = A[1] ^ B[1] ^ Q1[0];
  assign RA3.Q = A[2] ^ B[2] ^ Q2[0];
  assign RA4.Q = A[3] ^ B[3] ^ Q3[0];
  assign RA5.Q = Q4[0];

  assign CLK = 1'b1;

endmodule

