module color_select(
  input wire clk,              // 28MHz clock
  input wire clk7_en,          // 7MHz clock enable
  input wire [9-1:0] reg_address_in,   // register address input
  input wire [12-1:0] data_in,          // bus data input
  input wire [8-1:0] select,           // color select input
  input wire [8-1:0] bplxor,           // CLUT address xor value
  input wire [3-1:0] bank,             // color bank select
  input wire loct,             // 12-bit palette select
  input wire ehb_en,           // EHB enable
  output reg [24-1:0] rgb       // RGB output
);

// Register names and addresses
parameter COLORBASE = 9'h180;         // Color table base address

// Color RAM
wire [8-1:0] wr_adr = {bank[2:0], reg_address_in[5:1]};
wire wr_en = (reg_address_in[8:6] == COLORBASE[8:6]) && clk7_en;
wire [32-1:0] wr_dat = {4'b0, data_in[11:0], 4'b0, data_in[11:0]};
wire [4-1:0] wr_bs = loct ? 4'b0011 : 4'b1111;
wire [8-1:0] rd_adr = ehb_en ? {3'b000, select[4:0]} ^ bplxor : select ^ bplxor;
wire [32-1:0] rd_dat;
reg ehb_sel;

// CLUT
denise_colortable_ram_mf clut(
  .clock(clk),
  .enable(1'b1),
  .wraddress(wr_adr),
  .wren(wr_en),
  .byteena_a(wr_bs),
  .data(wr_dat),
  .rdaddress(rd_adr),
  .q(rd_dat)
);

// Pack color values
wire [12-1:0] color_hi = rd_dat[12-1+16:0+16];
wire [12-1:0] color_lo = rd_dat[12-1+0:0+0];
wire [24-1:0] color = {color_hi[11:8], color_lo[11:8], color_hi[7:4], color_lo[7:4], color_hi[3:0], color_lo[3:0]};

// Extra half-brite mode shifter
always @(*) begin
  if (ehb_sel && ehb_en) // Half-bright, shift every component 1 position to the right
    rgb = {1'b0, color[23:17], 1'b0, color[15:9], 1'b0, color[7:1]};
  else // Normal color select
    rgb = color;
end

// Register half-brite bit
always @(posedge clk) begin
  ehb_sel <= #1 select[5];
end

endmodule

module top_module( 
    input clk,
    input [2:0] a,
    input [2:0] b,
    input d,
    output [2:0] out_or_bitwise,
    output out_or_logical,
    output [5:0] out_not,
    output q
);

// Logical Operations Module
wire [2:0] bitwise_or;
wire logical_or;
wire [2:0] a_not;
wire [2:0] b_not;

assign bitwise_or = a | b;
assign logical_or = (a != 0) || (b != 0);
assign a_not = ~a;
assign b_not = ~b;

assign out_or_bitwise = bitwise_or;
assign out_or_logical = logical_or;
assign out_not = {b_not, a_not};

// Shift Register
reg [2:0] shift_reg [0:2];
wire [2:0] q_reg;

always @(posedge clk) begin
    shift_reg[0] <= d;
    shift_reg[1] <= shift_reg[0];
    shift_reg[2] <= shift_reg[1];
end

assign q_reg = shift_reg[2];

// Functional Module
wire [2:0] final_output;

assign final_output = out_or_bitwise | q_reg;

assign q = final_output;

endmodule

module security_system (
    input [31:0] in, // 32-bit input for byte-reversing module
    input [3:0] priority_in, // 4-bit input for priority encoder
    output reg [1:0] security_lock // 2-bit output of priority encoder
);

// Byte-reversing module
reg [7:0] byte0, byte1, byte2, byte3;
assign byte0 = in[7:0];
assign byte1 = in[15:8];
assign byte2 = in[23:16];
assign byte3 = in[31:24];
reg [31:0] reverse_in;
assign reverse_in = {byte0, byte1, byte2, byte3};

// Priority encoder
reg [3:0] priority;
always @* begin
    case(priority_in)
        4'b0001: priority = 2'b00;
        4'b0010: priority = 2'b01;
        4'b0100: priority = 2'b10;
        4'b1000: priority = 2'b11;
        default: priority = 2'b00;
    endcase
end

// Security lock
always @* begin
    case(priority)
        2'b00: security_lock = 2'b00;
        2'b01: security_lock = 2'b01;
        2'b10: security_lock = 2'b10;
        2'b11: security_lock = 2'b11;
        default: security_lock = 2'b00;
    endcase
end

endmodule

