  reset_reg <= {reset_reg[0], devpor | devclrn}; // Shift reset state into register
  outclk_reg <= outclk; // Shift outclk signal into register
end

// OUTPUT REGISTERS
assign enaout = enaout_reg;
assign outclk = outclk_reg;

