module ram_module (
    input clk,
    input rst,
    input [68:0] rcn_in,
    output [68:0] rcn_out
);

    parameter ADDR_BASE = 24'hF00000; // Address range where RAM is mapped
    parameter RAM_SIZE = 256*1024; // RAM capacity in bytes
    parameter WORD_SIZE = 4; // Size of data word in bytes

    // Slave module interface signals
    wire cs;
    wire wr;
    wire [3:0] mask;
    wire [23:0] addr;
    wire [31:0] wdata;
    wire [31:0] rdata;

    // Slave module instantiation
    rcn_slave #(.ADDR_MASK(24'hFF0000), .ADDR_BASE(ADDR_BASE)) rcn_slave (
        .rst(rst),
        .clk(clk),
        .rcn_in(rcn_in),
        .rcn_out(rcn_out),
        .cs(cs),
        .wr(wr),
        .mask(mask),
        .addr(addr),
        .wdata(wdata),
        .rdata(rdata)
    );

    // RAM memory arrays
    reg [7:0] byte_0[RAM_SIZE/WORD_SIZE-1:0];
    reg [7:0] byte_1[RAM_SIZE/WORD_SIZE-1:0];
    reg [7:0] byte_2[RAM_SIZE/WORD_SIZE-1:0];
    reg [7:0] byte_3[RAM_SIZE/WORD_SIZE-1:0];

    // Data output register
    reg [31:0] data_out;

    // Write operation
    always @ (posedge clk) begin
        if (cs && wr) begin
            if (mask[0])
                byte_0[addr[RAM_SIZE_LOG2-1:2]] <= wdata[7:0];
            if (mask[1])
                byte_1[addr[RAM_SIZE_LOG2-1:2]] <= wdata[15:8];
            if (mask[2])
                byte_2[addr[RAM_SIZE_LOG2-1:2]] <= wdata[23:16];
            if (mask[3])
                byte_3[addr[RAM_SIZE_LOG2-1:2]] <= wdata[31:24];
        end
    end

    // Read operation
    always @ (posedge clk) begin
        if (cs) begin
            data_out <= {byte_3[addr[RAM_SIZE_LOG2-1:2]], byte_2[addr[RAM_SIZE_LOG2-1:2]],
                         byte_1[addr[RAM_SIZE_LOG2-1:2]], byte_0[addr[RAM_SIZE_LOG2-1:2]]};
        end
    end

    // Output register assignment
    assign rdata = data_out;

endmodule

module mux4_to_1_async_reset (
    input [3:0] in0,
    input [3:0] in1,
    input [3:0] in2,
    input [3:0] in3,
    input [1:0] sel,
    input reset,
    output [3:0] out
);

    wire [3:0] mux1_out;
    wire [3:0] mux2_out;
    wire [3:0] mux3_out;
    wire [3:0] mux4_out;
    wire [3:0] reset_out;

    // First stage of the mux
    mux4to1 mux1 (
        .in0(in0),
        .in1(in1),
        .in2(in2),
        .in3(in3),
        .sel(sel[1:1]),
        .out(mux1_out)
    );

    // Second stage of the mux
    mux4to1 mux2 (
        .in0(in0),
        .in1(in1),
        .in2(in2),
        .in3(in3),
        .sel(sel[0:0]),
        .out(mux2_out)
    );

    // Third stage of the mux
    mux2to1 mux3 (
        .in0(mux1_out),
        .in1(mux2_out),
        .sel(sel[1:0]),
        .out(mux3_out)
    );

    // Fourth stage of the mux
    mux2to1 mux4 (
        .in0(mux3_out),
        .in1(reset_out),
        .sel(reset),
        .out(mux4_out)
    );

    // Inverter for reset signal
    not not_reset (
        .in(reset),
        .out(reset_out)
    );

