module add_sub_overflow (
    input [3:0] A,
    input [3:0] B,
    input Cn,
    output reg [3:0] S,
    output reg V
);

reg [3:0] A_reg, B_reg, S_reg;
reg Cn_reg;

always @(posedge clk) begin
    A_reg <= A;
    B_reg <= B;
    Cn_reg <= Cn;
end

always @(posedge clk) begin
    S_reg <= A_reg + (B_reg ^ 4'b1111) + Cn_reg;
end

always @(posedge clk) begin
    S <= S_reg;
    V <= (S[3] ^ A_reg[3]) & (S[3] ^ B_reg[3]);
end

endmodule

module Debouncer(
    input signal,
    output reg debounced_signal
);

parameter debounce_time = 10;
parameter threshold = 5;

reg [1:0] state;
reg [debounce_time-1:0] counter;

always @(posedge signal) begin
    case(state)
        2'b00: begin
            counter <= debounce_time-1;
            state <= 2'b01;
        end
        2'b01: begin
            if(counter == 0) begin
                debounced_signal <= 1;
                counter <= debounce_time-1;
                state <= 2'b10;
            end else begin
                counter <= counter - 1;
            end
        end
        2'b10: begin
            if(signal == 0) begin
                state <= 2'b00;
            end
        end
    endcase
end

always @(posedge debounced_signal) begin
    debounced_signal <= 0;
end

endmodule

