module compareFloats(
    input [(expWidth + sigWidth):0] a,
    input [(expWidth + sigWidth):0] b,
    output out
);

    wire isNaN = ((a[(expWidth + sigWidth)] == 1) && (a[(expWidth + sigWidth - 1):0] != 0)) ||
                  ((b[(expWidth + sigWidth)] == 1) && (b[(expWidth + sigWidth - 1):0] != 0));
    wire isPosInf = (a == {(expWidth + sigWidth + 1){1'b1}}) && (b == {(expWidth + sigWidth + 1){1'b1}});
    wire isNegInf = (a == {(expWidth + sigWidth + 1){1'b0, 1'b1}}) && (b == {(expWidth + sigWidth + 1){1'b0, 1'b1}});
    wire sameSign = (a[(expWidth + sigWidth)] == b[(expWidth + sigWidth)]);
    wire sameExp = (a[(expWidth + sigWidth - 1):(sigWidth)] == b[(expWidth + sigWidth - 1):(sigWidth)]);
    wire sameSig = (a[(sigWidth - 1):0] == b[(sigWidth - 1):0]);

    assign out = (!isNaN && (isPosInf || isNegInf || (sameSign && sameExp && sameSig))) ? 1'b1 : 1'b0;

endmodule

