module MD5 (
  input [511:0] in,
  output [127:0] out
);

parameter m = 16; // number of 32-bit words in input message

reg [31:0] A = 32'h67452301;
reg [31:0] B = 32'hEFCDAB89;
reg [31:0] C = 32'h98BADCFE;
reg [31:0] D = 32'h10325476;

reg [31:0] M[m-1:0];
integer i;

initial begin
  for (i = 0; i < m; i = i + 1) begin
    M[i] = in[i*32 +: 32];
  end
end

reg [31:0] F, G;
integer j;

always @(A, B, C, D, M) begin
  for (j = 0; j < 64; j = j + 1) begin
    if (j < 16) begin
      F = (B & C) | (~B & D);
      G = j;
    end else if (j < 32) begin
      F = (D & B) | (~D & C);
      G = (5 * j + 1) % 16;
    end else if (j < 48) begin
      F = B ^ C ^ D;
      G = (3 * j + 5) % 16;
    end else begin
      F = C ^ (B | ~D);
      G = (7 * j) % 16;
    end

    F = F + A + M[G] + (32'h01234567 >> (j % 4) * 8);
    A = D;
    D = C;
    C = B;
    B = B + (F << (j % 4) * 8 | F >> (32 - (j % 4) * 8));
  end
end

assign out = {A, B, C, D};

endmodule

module top_module (
    input [1:0] decoder_in, // 2-bit input for the decoder
    input [7:0] encoder_in, // 8-bit input for the encoder
    output reg [15:0] decoder_out, // 16-bit output from the decoder
    output reg [2:0] encoder_out, // 3-bit output from the encoder
    output reg [15:0] final_out // 16-bit final output from the functional module
);

// 4-to-16 decoder
wire [15:0] decoder_out_wire;
decoder_4to16 decoder(
    .in(decoder_in),
    .out(decoder_out_wire)
);
assign decoder_out = decoder_out_wire;

// 8-bit priority encoder
wire [2:0] encoder_out_wire;
priority_encoder_8bit encoder(
    .in(encoder_in),
    .out(encoder_out_wire)
);
assign encoder_out = encoder_out_wire;

// Functional module
always @(*) begin
    final_out = decoder_out & {16{encoder_out == 0 ? 1'b0 : 1'b1 << (encoder_out-1)}}; // bitwise AND operation
end

endmodule

// 4-to-16 decoder module
module decoder_4to16 (
    input [1:0] in, // 2-bit input
    output reg [15:0] out // 16-bit output with only one bit set to 1 based on the input
);

always @(*) begin
    case (in)
        2'b00: out = 16'b0000000000000001;
        2'b01: out = 16'b0000000000000010;
        2'b10: out = 16'b0000000000000100;
        2'b11: out = 16'b0000000000001000;
    endcase
end

endmodule

// 8-bit priority encoder module
module priority_encoder_8bit (
    input [7:0] in, // 8-bit input
    output reg [2:0] out // 3-bit output corresponding to the highest priority input that is high
);

always @(*) begin
    casez (in)
        8'b10000000: out = 3'b000;
        8'b01000000: out = 3'b001;
        8'b00100000: out = 3'b010;
        8'b00010000: out = 3'b011;
        8'b00001000: out = 3'b100;
        8'b00000100: out = 3'b101;
        8'b00000010: out = 3'b110;
        8'b00000001: out = 3'b111;
        default: out = 3'b000; // if no input is high, output 0
    endcase
end

endmodule

