module ram8k(input clk,
             input [11:0]  addr,
             input [15:0]  data_in,
             output [15:0] data_out,
             input         we,
             input         re);

   wire [15:0]                  data_out_low;
   wire [15:0]                  data_out_high;
   wire                         we_low;
   wire                         re_low;

   wire                         we_high;
   wire                         re_high;

   // Each block is 2048 words
   ram2k r1(.clk(clk),
            .addr(addr[10:0]),
            .data_in(data_in),
            .data_out(data_out_low),
            .we(we_low),
            .re(re_low));

   ram2k r2(.clk(clk),
            .addr(addr[10:0] - 2048),
            .data_in(data_in),
            .data_out(data_out_high),
            .we(we_high),
            .re(re_high));

   reg                          on_high;
   always @(posedge clk) on_high <= addr[11];

   assign data_out = on_high?data_out_high:data_out_low;
   assign we_high   = addr[11]&we;
   assign we_low    = (~addr[11])&we;

   assign re_low    = 1;
   assign re_high   = 1;

endmodule

module ram2k(input clk,
             input [10:0]  addr,
             input [15:0]  data_in,
             output [15:0] data_out,
             input         we,
             input         re);

   reg [15:0] mem [0:2047];
   integer i;

   always @(posedge clk) begin
      if (we) begin
         mem[addr] <= data_in;
      end
      if (re) begin
         data_out <= mem[addr];
      end
   end

endmodule

module dff_sr (
    input CLK,
    input D,
    input SCD,
    input SCE,
    input RESET_B,
    output reg Q,
    output reg Q_N
);

always @(posedge CLK) begin
    if (RESET_B == 0) begin
        Q <= 0;
        Q_N <= 1;
    end else if (SCD == 1) begin
        Q <= 1;
        Q_N <= 0;
    end else if (SCE == 1) begin
        Q <= 0;
        Q_N <= 1;
    end else begin
        Q <= D;
        Q_N <= ~D;
    end
end

endmodule

module clock_gate (
