module alu_lcd_display(
    input clk,      // 10 MHz clock input
    input resetn,   // Active low reset
    input [1:0] input_sel, // Selects which input to receive: 00 for ALU control, 10 for first operand, 11 for second operand
    output lcd_rst, // LCD reset signal
    output lcd_cs,  // LCD chip select signal
    output lcd_rs,  // LCD register select signal
    output lcd_wr,  // LCD write signal
    output lcd_rd,  // LCD read signal
    inout [15:0] lcd_data_io, // LCD data bus
    output lcd_bl_ctr, // LCD backlight control signal
    inout ct_int,   // I2C interrupt signal
    inout ct_sda,   // I2C data signal
    output ct_scl,  // I2C clock signal
    output ct_rstn, // I2C reset signal
    output reg [5:0] display_number, // Selects which display slot to output the ALU result to
    output reg [39:0] display_name, // Name of the input being displayed
    output reg [31:0] display_value // Value of the input being displayed
);

reg [11:0] alu_control; // ALU control signal
reg [31:0] alu_src1; // First ALU operand
reg [31:0] alu_src2; // Second ALU operand
wire [31:0] alu_result; // ALU result

// Instantiate the ALU module
alu alu_module(
    .alu_control(alu_control),
    .alu_src1(alu_src1),
    .alu_src2(alu_src2),
    .alu_result(alu_result)
);

// Instantiate the LCD module
lcd_module lcd_module(
    .clk(clk),
    .resetn(resetn),
    .display_valid(1'b1),
    .display_name(display_name),
    .display_value(display_value),
    .display_number(display_number),
    .input_valid(1'b1),
    .input_value(alu_result),
    .lcd_rst(lcd_rst),
    .lcd_cs(lcd_cs),
    .lcd_rs(lcd_rs),
    .lcd_wr(lcd_wr),
    .lcd_rd(lcd_rd),
    .lcd_data_io(lcd_data_io),
    .lcd_bl_ctr(lcd_bl_ctr),
    .ct_int(ct_int),
    .ct_sda(ct_sda),
    .ct_scl(ct_scl),
    .ct_rstn(ct_rstn)
);

// Receive inputs and select display slot
always @(posedge clk) begin
    if (!resetn) begin
        alu_control <= 12'd0;
        alu_src1 <= 32'd0;
        alu_src2 <= 32'd0;
        display_number <= 6'd0;
        display_name <= 40'd0;
        display_value <= 32'd0;
    end else begin
        case (input_sel)
            2'b00: alu_control <= alu_result[11:0];
            2'b10: alu_src1 <= alu_result;
            2'b11: alu_src2 <= alu_result;
        endcase
        case (display_number)
            6'd1: begin
                display_name <= "SRC_1";
                display_value <= alu_src1;
            end
            6'd2: begin
                display_name <= "SRC_2";
                display_value <= alu_src2;
            end
            6'd3: begin
                display_name <= "CONTR";
                display_value <= {20'd0, alu_control};
            end
            6'd4: begin
                display_name <= "RESUL";
                display_value <= alu_result;
            end
            default: begin
                display_name <= 40'd0;
                display_value <= 32'd0;
            end
        endcase
    end
end

endmodule

module wb_slave #(
    parameter                              ADDR_WIDTH       = 16,    // The width of the address.
    parameter                              DATA_WIDTH       = 32,    // The width of the both transferred and inputted data.
    parameter                              DATA_COUNT       = 8,    // How many values there are in the register array.
    parameter                              BASE_ADDRESS     = 'h0F00    // The first referred address of the master.
) (
    // Interface: wb_slave
    // The address of the data.
    input          [ADDR_WIDTH-1:0]     adr_i,    // The address of the data.
    input                               cyc_i,    // Asserted by master for transfer.
    input          [DATA_WIDTH-1:0]     dat_i,    // Data from master to slave.
    input                               stb_i,    // Asserted, when this specific slave is selected.
    input                               we_i,    // Write = 1, Read = 0.
    output reg                          ack_o,    // Slave asserts acknowledge.
    output reg     [DATA_WIDTH-1:0]     dat_o,    // Data from slave to master.
    output reg                          err_o,    // Indicates abnormal cycle termination.

    // Interface: wb_system
    // The mandatory clock, as this is synchronous logic.
    input                               clk_i,    // The mandatory clock, as this is synchronous logic.
    input                               rst_i    // The mandatory reset, as this is synchronous logic.
);

    localparam AUB = 8;
    localparam AU_IN_DATA = DATA_WIDTH/AUB;
    localparam MEMORY_SIZE = DATA_COUNT*4;
    reg [AUB-1:0] memory [MEMORY_SIZE-1:0];

    // Used to index AUBs to data io.
    integer index;

    // The state.
    reg [0:0] state;

    // The available states.
    parameter [0:0]
        S_WAIT      = 1'd0, // Waiting for cyc_i & stb_i
        S_DEASSERT  = 1'd1; // Deassert acknowledgement.

    always @(posedge clk_i or posedge rst_i) begin
        if(rst_i == 1'b1) begin
            ack_o <= 0; // Obviously, there is nothing to acknowledge by default.
            dat_o <= 0; // No output by default.
            err_o <= 0; // No error by default.
            state <= S_WAIT; // Wait signals from the masters at reset.
        end
        else begin
            if (state == S_WAIT) begin
                // Wait signal from the master.
                if ( cyc_i == 1 && stb_i == 1 ) begin
                    // Master ok, check the address.
                    if (adr_i < BASE_ADDRESS + MEMORY_SIZE && adr_i >= BASE_ADDRESS) begin
                        // The specified address in accessible -> proceed.
                        ack_o <= 1;

                        if ( we_i == 1 ) begin
                            // Writing: Pick every byte from the input and place them to correct addresses.
                            for (index = 0; index < AU_IN_DATA; index = index + 1) begin
                                memory[adr_i - BASE_ADDRESS + index] <= dat_i[(index*AUB)+:AUB];
                            end
                        end
                        else begin
                            // Reading: Pick every byte from correct addresses and place them to the output.
                            for (index = 0; index < AU_IN_DATA; index = index + 1) begin
                                dat_o[(index*AUB)+:AUB] <= memory[adr_i - BASE_ADDRESS + index];
                            end
                        end
                    end
                    else begin
                        // The specified address out-of-scope -> error!
                        err_o <= 1;
                    end

                    // Next thing is to deassert.
                    state <= S_DEASSERT;
                end
            end
            else if (state == S_DEASSERT) begin
                // Deassert acknowlegement, get ready to receive next one.
                ack_o <= 0;
                err_o <= 0;
                state <= S_WAIT;
            end
            else
                $display("ERROR: Unkown state: %d", state);
        end
    end
endmodule

module operation_module (
    input wire UDI_irvalid_e,
    input wire [31:0] UDI_ir_e,
    input wire UDI_gclk,
    input wire UDI_gscanenable,
    input wire [15:0] UDI_rs_e,
    input wire [15:0] UDI_rt_e,
    output wire [31:0] udi_res,
    output wire [4:0] UDI_wrreg_e
);

    wire [1:0] udi_ctl_sum_mode_d;
    wire udi_ctl_res_sel_d;
    wire udi_ctl_thr_wr;
    wire [1:0] udi_ctl_sum_mode;
    wire udi_ctl_res_sel;

    localparam UDI_MAJ_OP = 6'd28;
    localparam UDI_0 = 6'd16;
    localparam UDI_1 = 6'd17;
    localparam UDI_2 = 6'd18;
    localparam UDI_3 = 6'd19;
    localparam UDI_4 = 6'd20;
    localparam UDI_5 = 6'd21;
    localparam UDI_6 = 6'd22;

    localparam CTL_THR_WR_OFF = 1'b0;
    localparam CTL_THR_WR_ON = 1'b1;
    localparam CTL_SUM_MODE_NONE = 2'b00;
    localparam CTL_SUM_MODE_SUM = 2'b01;
    localparam CTL_SUM_MODE_SUMSHIFT = 2'b10;
    localparam CTL_SUM_MODE_BYPASS = 2'b11;
    localparam CTL_RES_CALC = 1'b0;
    localparam CTL_RES_COMP = 1'b1;

    assign UDI_fromudi[`M14K_UDI_EXT_FROMUDI_WIDTH-1:0] = {`M14K_UDI_EXT_FROMUDI_WIDTH{1'b0}};

    assign udi_ctl_thr_wr = (UDI_irvalid_e && UDI_ir_e[31:26] == UDI_MAJ_OP && UDI_ir_e[5:0] == UDI_3) ? CTL_THR_WR_ON : CTL_THR_WR_OFF;
    assign udi_ctl_sum_mode = (UDI_irvalid_e && UDI_ir_e[31:26] == UDI_MAJ_OP && (UDI_ir_e[5:0] == UDI_0 || UDI_ir_e[5:0] == UDI_4))
        ? CTL_SUM_MODE_SUM : (UDI_irvalid_e && UDI_ir_e[31:26] == UDI_MAJ_OP && (UDI_ir_e[5:0] == UDI_1 || UDI_ir_e[5:0] == UDI_5))
        ? CTL_SUM_MODE_SUMSHIFT : (UDI_irvalid_e && UDI_ir_e[31:26] == UDI_MAJ_OP && (UDI_ir_e[5:0] == UDI_2 || UDI_ir_e[5:0] == UDI_6))
        ? CTL_SUM_MODE_BYPASS : CTL_SUM_MODE_NONE;
    assign udi_ctl_res_sel = (UDI_irvalid_e && UDI_ir_e[31:26] == UDI_MAJ_OP
        && (UDI_ir_e[5:0] == UDI_0 || UDI_ir_e[5:0] == UDI_1 || UDI_ir_e[5:0] == UDI_2 || UDI_ir_e[5:0] == UDI_3))
        ? CTL_RES_CALC : CTL_RES_COMP;

    udi_inst_pow udi_inst_pow_u(
        .gclk(UDI_gclk),
        .gscanenable(UDI_gscanenable),
        .in_rs(UDI_rs_e),
        .in_rt(UDI_rt_e[15:0]),
        .out_rd(udi_res),
        .udi_ctl_thr_wr(udi_ctl_thr_wr),
        .udi_ctl_sum_mode(udi_ctl_sum_mode_d),
        .udi_ctl_res_sel(udi_ctl_res_sel_d)
    );

    mvp_cregister_wide #(2) _udi_ctl_sum_mode_1_0_(udi_ctl_sum_mode_d, UDI_gscanenable, (UDI_irvalid_e && UDI_ir_e[31:26] == UDI_MAJ_OP), UDI_gclk, udi_ctl_sum_mode);
    mvp_cregister_wide #(1) _udi_ctl_res_sel_(udi_ctl_res_sel_d, UDI_gscanenable, (UDI_irvalid_e && UDI_ir_e[31:26] == UDI_MAJ_OP), UDI_gclk, udi_ctl_res_sel);

    always @(UDI_ir_e, UDI_irvalid_e) begin
        if (UDI_irvalid_e && UDI_ir_e[31:26] == UDI_MAJ_OP) begin
            case (UDI_ir_e[5:0])
                UDI_0: udi_res = UDI_rs_e * UDI_rs_e + UDI_rt_e * UDI_rt_e;
                UDI_1: udi_res = (UDI_rs_e * UDI_rs_e + UDI_rt_e * UDI_rt_e) >> 1;
                UDI_2: udi_res = UDI_rs_e * UDI_rs_e;
                UDI_3: stored_threshold = UDI_rs_e;
                UDI_4: udi_res = (UDI_rs_e * UDI_rs_e + UDI_rt_e * UDI_rt_e > stored_threshold) ? 1 : 0;
                UDI_5: udi_res = ((UDI_rs_e * UDI_rs_e + UDI_rt_e * UDI_rt_e) >> 1 > stored_threshold) ? 1 : 0;
                UDI_6: udi_res = (UDI_rs_e * UDI_rs_e > stored_threshold) ? 1 : 0;
                default: udi_res = 0;
            endcase
        end
    end

    assign UDI_wrreg_e = (UDI_ir_e[5:0] == UDI_3) ? 5'd0 : UDI_ir_e[15:11];

endmodule

module top_module(
    input a, b, sub, select,
    output [31:0] result
);

    wire [31:0] half_adder_sum, half_adder_carry_out, add_sub_sum;
    wire [31:0] xor_output;
    wire half_adder_enable, add_sub_enable;

    // Instantiate half-adder and addition/subtraction modules
    half_adder half_adder_inst(
        .a(a),
        .b(b),
        .sum(half_adder_sum),
        .carry_out(half_adder_carry_out)
    );

    add_sub add_sub_inst(
        .a(a),
        .b(b),
        .sub(sub),
        .sum(add_sub_sum)
    );

    // Control logic to enable either half-adder or add/sub module
    assign half_adder_enable = (select == 1'b0);
    assign add_sub_enable = (select == 1'b1);

    // Functional module to perform XOR operation on half-adder and add/sub outputs
    assign xor_output = half_adder_sum ^ add_sub_sum;

    // Output result based on select input
    assign result = (half_adder_enable) ? half_adder_sum :
                   (add_sub_enable) ? add_sub_sum :
                   xor_output;

endmodule

// Half-adder module
module half_adder(
    input a, b,
    output sum, carry_out
);

    assign sum = a ^ b;
    assign carry_out = a & b;

endmodule

// Addition/subtraction module
module add_sub(
    input [31:0] a, b,
    input sub,
    output reg [31:0] sum
);

    always @(*) begin
        if (sub) begin
            sum <= a - b;
        end else begin
            sum <= a + b;
        end
    end

endmodule

module LED_controller (
  input [1:0] address,
  input chipselect,
  input clk,
  input reset_n,
  input write_n,
  input [9:0] writedata,
  output reg [9:0] out_port,
  output reg [31:0] readdata
);

  reg [9:0] data_out;
  wire [9:0] read_mux_out;
  wire clk_en;

  assign clk_en = 1;

  assign read_mux_out = {10{(address == 0)}} & data_out;

  always @(posedge clk or negedge reset_n) begin
    if(~reset_n) begin
      data_out <= 0;
    end else begin
      if(chipselect && ~write_n && (address == 0)) begin
        data_out <= writedata;
      end
    end
  end

  assign out_port = data_out;
  assign readdata = {32'b0, read_mux_out};

endmodule

module LCB (
  input clk,
  input rst,
  input [7:0] ambient_light,
  input [7:0] brightness_level,
  output reg [7:0] brightness
);

parameter max_brightness = 255; // maximum brightness level

reg [7:0] adc_output;
reg [7:0] pwm_counter;
reg [7:0] pwm_duty_cycle;

// ADC functionality
always @ (posedge clk) begin
  adc_output <= ambient_light;
end

// PWM functionality
always @ (posedge clk) begin
  if (pwm_counter < pwm_duty_cycle) begin
    brightness <= max_brightness;
  end else begin
    brightness <= 0;
  end

  if (pwm_counter == 255) begin
    pwm_counter <= 0;
  end else begin
    pwm_counter <= pwm_counter + 1;
  end
end

// Reset functionality
always @ (posedge clk) begin
  if (rst) begin
    brightness <= 0;
    pwm_counter <= 0;
    pwm_duty_cycle <= 0;
  end else begin
    if (adc_output > brightness_level) begin
      pwm_duty_cycle <= brightness_level;
    end else begin
      pwm_duty_cycle <= adc_output;
    end
  end
end

endmodule

