    input RESET,        // Synchronous active-high reset
    input LOAD,         // Load input for the counter
    input [3:0] LOAD_VAL, // Value to load into counter when LOAD is high
    input [3:0] in,     // Input to the decoder
    output [15:0] out,  // Output from the decoder
    output reg [3:0] Q  // Output from the functional module
);

reg [3:0] count;
wire [15:0] decoder_out;

// Instantiate the 4-bit binary counter with synchronous reset and load input
counter_4bit_sync_reset_load counter (
    .CLK(CLK),
    .RESET(RESET),
    .LOAD(LOAD),
    .LOAD_VAL(LOAD_VAL),
    .Q(count)
);

// Instantiate the 4-to-16 decoder
decoder_4to16 decoder (
    .in(count),
    .out(decoder_out)
);

// Perform bitwise AND operation on the counter output and decoder output
assign out = decoder_out;
always @ (count or decoder_out) begin
    Q = count & ~decoder_out;
end

