module generic_fifo (
    input wire clk,
    input wire reset,
    input wire write,
    input wire read,
    input wire [DATA_SIZE-1:0] data_in,

    output wire full,
    output reg empty,

    output reg [DATA_SIZE-1:0] data_out,
    output reg [CLOG2(DEPTH)-1:0] size
);

reg [DATA_SIZE:0] mem [DEPTH-1:0];
reg [CLOG2(DEPTH)-1:0] rd_pointer, wr_pointer;

// Update read pointer
always @(posedge clk) begin
    if (reset) begin
        rd_pointer <= 0;
    end else if (read && !empty) begin
        if (rd_pointer == DEPTH-1) begin
            rd_pointer <= 0;
        end else begin
            rd_pointer <= rd_pointer + 1;
        end
    end
end

// Update write pointer
always @(posedge clk) begin
    if (reset) begin
        wr_pointer <= 0;
    end else if (write && !full) begin
        if (wr_pointer == DEPTH-1) begin
            wr_pointer <= 0;
        end else begin
            wr_pointer <= wr_pointer + 1;
        end
    end
end

// Update empty signal
always @(*) begin
    if (rd_pointer == wr_pointer) begin
        empty <= 1;
    end else begin
        empty <= 0;
    end
end

// Update full signal
assign full = ((wr_pointer+1) % DEPTH == rd_pointer);

// Write data to memory
always @(posedge clk) begin
    if (write && !full) begin
        mem[wr_pointer] <= data_in;
    end
end

// Read data from memory
always @(posedge clk) begin
    if (read && !empty) begin
        data_out <= mem[rd_pointer];
    end
end

// Update size signal
always @(*) begin
    if (wr_pointer >= rd_pointer) begin
        size <= wr_pointer - rd_pointer;
    end else begin
        size <= DEPTH - rd_pointer + wr_pointer;
    end
end

endmodule

module WireDelay #(
  parameter Delay_g = 0,
  parameter Delay_rd = 0,
  parameter ERR_INSERT = "OFF"
)(
  inout A,
  inout B,
  input reset,
  input phy_init_done
);

  reg A_r;
  reg B_r;
  reg B_inv;
  reg line_en;

  reg B_nonX;

  assign A = A_r;
  assign B = B_r;

  always @(*) begin
    if (B === 1'bx)
      B_nonX <= $random;
    else
      B_nonX <= B;
  end

  always @(*) begin
    if ((B_nonX == 'b1) || (B_nonX == 'b0))
      B_inv <= #0 ~B_nonX;
    else
      B_inv <= #0 'bz;
  end

  always @(*) begin
    if (!reset) begin
      A_r <= 1'bz;
      B_r <= 1'bz;
      line_en <= 1'b0;
    end else begin
      if (line_en) begin
        B_r <= 1'bz;
        if ((ERR_INSERT == "ON") & (phy_init_done))
          A_r <= #Delay_rd B_inv;
        else
          A_r <= #Delay_rd B_nonX;
      end else begin
        B_r <= #Delay_g A;
        A_r <= 1'bz;
      end
    end
  end

  always @(A or B) begin
    if (!reset) begin
      line_en <= 1'b0;
    end else if (A !== A_r) begin
      line_en <= 1'b1;
    end else if (B_r !== B) begin
      line_en <= 1'b1;
    end else begin
      line_en <= line_en;
    end
  end

endmodule

