module shift_register #(parameter WIDTH=8,
                        parameter DIV_WIDTH=4,
                        parameter SHIFT_DIRECTION=1,
                        parameter READ_TRIG_SRC=0,
                        parameter READ_DELAY=0)(
  input clk_in,
  input rst,
  input start,
  input [WIDTH-1:0] din,
  input [DIV_WIDTH-1:0] div,
  input data_in_p,
  input data_in_n,
  output reg clk_sr_p,
  output reg clk_sr_n,
  output reg data_out_p,
  output reg data_out_n,
  output reg load_sr_p,
  output reg load_sr_n,
  output reg [WIDTH-1:0] dout,
  output reg clk,
  output reg valid
  );

  reg [DIV_WIDTH-1:0] count;
  reg [WIDTH-1:0] shift_reg;
  reg shift_dir;

  always @(posedge clk_in, posedge rst) begin
    if (rst) begin
      count <= 0;
      shift_reg <= 0;
      shift_dir <= SHIFT_DIRECTION;
      clk_sr_p <= 0;
      clk_sr_n <= 0;
      data_out_p <= 0;
      data_out_n <= 0;
      load_sr_p <= 0;
      load_sr_n <= 0;
      dout <= 0;
      clk <= 0;
      valid <= 0;
    end else begin
      if (start) begin
        count <= count + 1;
        if (count == div) begin
          count <= 0;
          if (shift_dir) begin
            shift_reg <= {shift_reg[WIDTH-2:0], data_in_p};
            data_out_p <= shift_reg[WIDTH-1];
            data_out_n <= shift_reg[0];
          end else begin
            shift_reg <= {data_in_n, shift_reg[WIDTH-1:1]};
            data_out_p <= shift_reg[WIDTH-1];
            data_out_n <= shift_reg[0];
          end
        end
      end
      if (READ_TRIG_SRC == 0) begin
        if (count == READ_DELAY) begin
          dout <= shift_reg;
          valid <= 1;
        end else begin
          dout <= 0;
          valid <= 0;
        end
      end else begin
        dout <= shift_reg;
        if (count == READ_DELAY) begin
          valid <= 1;
        end else begin
          valid <= 0;
        end
      end
      clk_sr_p <= shift_reg[WIDTH-1];
      clk_sr_n <= ~shift_reg[WIDTH-1];
      load_sr_p <= shift_reg[WIDTH-1];
      load_sr_n <= ~shift_reg[WIDTH-1];
      clk <= shift_reg[WIDTH-1];
    end
  end

endmodule

