module async_transmitter
(
  clk,
  TxD_start,
  TxD_data,
  TxD,
  TxD_busy
);

input clk;
input TxD_start;
input [7:0] TxD_data;
output TxD;
output TxD_busy;

parameter s_idle = 0;
parameter s_start_bit = 1;
parameter s_data_bits = 2;
parameter s_stop_bit = 3;

reg [2:0] state = s_idle;
reg TxD_reg = 1'b1;
reg [3:0] bit_count = 4'd0;

wire tx_busy = (state != s_idle);

// generate start pulse
reg TxD_start_reg = 1'b0;
wire tx_start_pulse;
rising_edge_detect tx_detect
(
 .clk(clk),
 .signal(TxD_start_reg),
 .pulse(tx_start_pulse)
);

// state machine to transmit data
always @(posedge clk) begin
  case (state)
    s_idle:
      begin
        TxD_reg <= 1'b1;
        if (TxD_start) begin
          state <= s_start_bit;
          bit_count <= 4'd0;
        end
      end
    s_start_bit:
      begin
        TxD_reg <= 1'b0;
        state <= s_data_bits;
      end
    s_data_bits:
      begin
        TxD_reg <= TxD_data[bit_count];
        bit_count <= bit_count + 4'd1;
        if (bit_count == 4'd8) begin
          state <= s_stop_bit;
          bit_count <= 4'd0;
        end
      end
    s_stop_bit:
      begin
        TxD_reg <= 1'b1;
        state <= s_idle;
      end
  endcase
end

assign TxD = TxD_reg;
assign TxD_busy = tx_busy;

endmodule

module clock_transmitter
(
  clk_fast,
  clk_slow,
  counter,
  header,
  go,
  TxD,
  done
);

input clk_fast;
input clk_slow;
input [31:0] counter;
input [7:0] header;
input go;
output TxD;
output done;

parameter s_idle = 0;
parameter s_transmit_tx = 1;
parameter s_transmit_wait = 2;
parameter s_inc_byte = 3;
parameter s_finish = 4;

reg [3:0] state = s_idle;
reg [7:0] data = 8'd0;
reg [3:0] byte_count = 4'd0;

reg go_reg = 1'b0;
reg go_reg_prev = 1'b0;
reg [7:0] header_reg = 8'd0;
reg [31:0] transmit_buf = 8'd0;
wire tx_start_pulse;
reg tx_start = 1'b0;
wire tx_busy;
wire tx_out;

// need these "one pulses" to ensure
// transmitter is only started once during wait period
rising_edge_detect tx_detect
(
 .clk(clk_fast),
 .signal(tx_start),
 .pulse(tx_start_pulse)
);

// state machine:
// sits at idle until receives 'go'
// starts transmitting, then waits for transmission to complete
// transmits next 8-bits
// continues until 32 bits transmitted
always @(posedge clk_slow) begin
  case(state)
    s_idle:
    begin
      go_reg <= go & !go_reg_prev;
      // hold onto header throughout transmission; reset in s_finish
      if (header_reg == 8'd0) header_reg <= header;
      state <= (go_reg) ? s_transmit_tx : s_idle;
      transmit_buf <= (go_reg) ? counter : 32'd0;
      byte_count <= 4'd0;
      go_reg_prev <= go_reg;
    end

    s_transmit_tx:
    begin
      tx_start <= (byte_count < 4'd5);
      data <= (byte_count == 4'd0) ? header_reg :
              (byte_count == 4'd1) ? transmit_buf[7:0] :
              (byte_count == 4'd2) ? transmit_buf[15:8] :
              (byte_count == 4'd3) ? transmit_buf[23:16] :
              (byte_count == 4'd4) ? transmit_buf[31:24] :
              8'b0;
      state <= (byte_count < 4'd5) ? s_transmit_wait : s_finish;
    end

    s_transmit_wait:
    begin
      state <= (tx_busy) ? s_transmit_wait : s_inc_byte;
      tx_start <= 0;
    end

    s_inc_byte:
    begin
      byte_count <= byte_count + 4'b1;
      state <= s_transmit_tx;
    end

    s_finish:
    begin
      state <= s_idle;
      header_reg <= 8'b0;
    end
  endcase
end

// declare transmitter
async_transmitter tx
(
 .clk(clk_fast),
 .TxD_start(tx_start_pulse),
 .TxD_data(data),
 .TxD(tx_out),
 .TxD_busy(tx_busy)
);

// assign outputs
assign done = (state == s_finish);
reg TxD;
always @(posedge clk_fast)
  TxD <= (tx_busy) ? tx_out : 1'b1;

endmodule

