  always @(*) begin
    dividend = in;
    divisor = 0;
    result = 0;
    next_result = 0;
    adder = 0;
    count = 0;

    while (dividend >= divisor) begin
      divisor = (divisor << 1) | 1;
      count = count + 1;
    end

    for (i = 0; i < count; i = i + 1) begin
      next_result = (result << 1) | 1;
      adder = (divisor >> 1) & ~(next_result << 1);
      if (dividend >= adder) begin
        result = next_result;
        dividend = dividend - adder;
      end
      divisor = divisor >> 1;
    end

    out = result;
  end

endmodule

module up_counter_pipeline (
