module grayfifo #(
    parameter data_width = 8,
    parameter address_width = 4,
    parameter fifo_depth = (1 << address_width)
) (
    /* Read port */
    output reg [data_width-1:0] data_out,
    output reg empty,
    input read_en,
    input clk_read,

    /* Write port */
    input [data_width-1:0] data_in,
    output reg full,
    input write_en,
    input clk_write,

    /* Asynchronous reset */
    input rst
);

reg [data_width-1:0] mem[fifo_depth-1:0];
wire [address_width-1:0] write_index, read_index;
wire equal_addresses;
wire write_en_safe, read_en_safe;
wire set_status, clear_status;
reg status;
wire preset_full, preset_empty;

assign data_out = mem[read_index];

always @(posedge clk_write) begin
    if(write_en & !full)
        mem[write_index] <= data_in;
end

assign write_en_safe = write_en & ~full;
assign read_en_safe = read_en & ~empty;

asfifo_graycounter #(
    .width(address_width)
) counter_write (
    .gray_count(write_index),
    .ce(write_en_safe),
    .rst(rst),
    .clk(clk_write)
);

asfifo_graycounter #(
    .width(address_width)
) counter_read (
    .gray_count(read_index),
    .ce(read_en_safe),
    .rst(rst),
    .clk(clk_read)
);

assign equal_addresses = (write_index == read_index);

assign set_status = (write_index[address_width-2] ~^ read_index[address_width-1]) &
    (write_index[address_width-1] ^ read_index[address_width-2]);

assign clear_status = ((write_index[address_width-2] ^ read_index[address_width-1]) &
    (write_index[address_width-1] ~^ read_index[address_width-2]))
    | rst;

always @(posedge clear_status, posedge set_status) begin
    if(clear_status)
        status <= 1'b0;
    else
        status <= 1'b1;
end

assign preset_full = status & equal_addresses;

always @(posedge clk_write, posedge preset_full) begin
    if(preset_full)
        full <= 1'b1;
    else
        full <= 1'b0;
end

assign preset_empty = ~status & equal_addresses;

always @(posedge clk_read, posedge preset_empty) begin
    if(preset_empty)
        empty <= 1'b1;
    else
        empty <= 1'b0;
end

endmodule

module multiply(
    input clock, reset, start,
    input [7:0] multiplicand, multiplier,
    output [15:0] PR,
    output Ready
);

reg [7:0] mult_reg; // register to hold the current digit of the multiplier being processed
reg [15:0] PR_reg; // register to hold the current partial product
reg [3:0] counter; // counter to keep track of the current digit of the multiplier being processed
reg [1:0] state; // state machine state

assign PR = PR_reg;
assign Ready = (state == 2);

always @(posedge clock) begin
    if (reset) begin
        mult_reg <= 0;
        PR_reg <= 0;
        counter <= 0;
        state <= 0;
    end else begin
        case (state)
            0: begin // idle state, waiting for start signal
                if (start) begin
                    mult_reg <= multiplier;
                    counter <= 0;
                    PR_reg <= 0;
                    state <= 1;
                end
            end
            1: begin // multiplication state, processing each digit of the multiplier
                if (counter == 8) begin
                    state <= 2;
                end else begin
                    PR_reg <= PR_reg + (multiplicand << (counter * 8)) * mult_reg[0];
                    mult_reg <= {mult_reg[6:0], mult_reg[7]};
                    counter <= counter + 1;
                end
            end
            2: begin // multiplication complete, waiting for start signal to begin new operation
                if (!start) begin
                    state <= 0;
                end
            end
        endcase
    end
end

endmodule

