module operation_block (
    i_data0,
    o_data0
);

  // Port mode declarations:
  input   [31:0] i_data0;
  output  [31:0] o_data0;

  // Wires:
  wire [31:0]
    w1,
    w2048,
    w2047,
    w4,
    w2043,
    w32,
    w2011,
    w32176,
    w30165;

  // Operations:
  assign w1 = i_data0 << 11;
  assign w2048 = i_data0 * 2048;
  assign w4 = i_data0 << 2;
  assign w2047 = w2048 - w1;
  assign w2043 = w2047 - w4;
  assign w32 = i_data0 << 5;
  assign w2011 = w2043 - w32;
  assign w32176 = w2011 << 4;
  assign w30165 = w32176 - w2011;

  // Output:
  assign o_data0 = w30165;

endmodule

module traffic_light_controller (
  input clk,
  input areset,
  input pedestrian_button,
  output reg red_light,
  output reg yellow_light,
  output reg green_light,
  output reg walk_signal
);

  // Define the states
  parameter STATE_0 = 2'b00;
  parameter STATE_1 = 2'b01;
  parameter STATE_2 = 2'b10;
  parameter STATE_3 = 2'b11;

  // Define the current state
  reg [1:0] current_state;

  // Define the next state
  reg [1:0] next_state;

  // Default values for the outputs
  assign red_light = 1'b1;
  assign yellow_light = 1'b0;
  assign green_light = 1'b0;
  assign walk_signal = 1'b0;

  // State machine logic
  always @(posedge clk, negedge areset) begin
    if (areset == 1'b0) begin
      current_state <= STATE_0;
    end else begin
      current_state <= next_state;
    end

    case (current_state)
      STATE_0: begin
        red_light <= 1'b1;
        yellow_light <= 1'b0;
        green_light <= 1'b0;
        walk_signal <= 1'b0;
        if (pedestrian_button == 1'b1) begin
          next_state <= STATE_3;
        end else begin
          next_state <= STATE_1;
        end
      end
      STATE_1: begin
        red_light <= 1'b1;
        yellow_light <= 1'b0;
        green_light <= 1'b0;
        walk_signal <= 1'b1;
        if (pedestrian_button == 1'b1) begin
          next_state <= STATE_3;
        end else begin
          next_state <= STATE_2;
        end
      end
      STATE_2: begin
        red_light <= 1'b0;
        yellow_light <= 1'b1;
        green_light <= 1'b0;
        walk_signal <= 1'b0;
        next_state <= STATE_3;
      end
      STATE_3: begin
        red_light <= 1'b0;
        yellow_light <= 1'b0;
        green_light <= 1'b1;
        walk_signal <= 1'b1;
        next_state <= STATE_0;
      end
    endcase
  end

endmodule

module pwm_out(
