reg [31:0] count_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        count_reg <= 0;
    end 
    else if (enable) begin
        if (count_reg < pwmfre) begin
            count_reg <= count_reg + 1;
