        end
    end
end

assign pha = pwm_reg;
assign phb = ~pwm_reg;

endmodule

module top_module (
    input [31:0] a,
    input [31:0] b,
    output [31:0] sum,
    output overflow
);

wire [31:0] carry;
wire [31:0] sum_1;
wire [31:0] sum_2;

adder_1 adder_1_inst (
    .a(a),
    .b(b),
    .sum(sum_1)
);

adder_2 adder_2_inst (
    .a(sum_1),
    .b(carry),
    .sum(sum_2)
);

final_adder final_adder_inst (
    .sum_1(sum_1),
    .sum_2(sum_2),
    .final_sum(sum),
    .overflow(overflow)
);

generate
    gen_carry_lookahead gen_carry_lookahead_inst (
        .a(a),
        .b(b),
        .carry(carry)
    );
endgenerate

endmodule

module adder_1 (
    input [31:0] a,
    input [31:0] b,
    output [31:0] sum
);

genvar i;

generate
    for (i = 0; i < 32; i = i + 1) begin : adder_1_loop
        assign sum[i] = a[i] ^ b[i];
    end
endgenerate

endmodule

module adder_2 (
    input [31:0] a,
    input [31:0] b,
    output [31:0] sum
);

genvar i;

generate
    for (i = 0; i < 32; i = i + 1) begin : adder_2_loop
        assign sum[i] = a[i] ^ b[i];
    end
endgenerate

endmodule

module final_adder (
    input [31:0] sum_1,
    input [31:0] sum_2,
    output [31:0] final_sum,
    output overflow
);

wire [31:0] carry;

genvar i;

generate
    for (i = 0; i < 31; i = i + 1) begin : final_adder_loop
        assign carry[i] = sum_1[i] & sum_2[i];
        assign final_sum[i] = sum_1[i] ^ sum_2[i] ^ carry[i];
    end

    assign carry[31] = sum_1[31] & sum_2[31];
    assign final_sum[31] = sum_1[31] ^ sum_2[31] ^ carry[30];

    assign overflow = (sum_1[31] & sum_2[31] & ~carry[30]) | (~sum_1[31] & ~sum_2[31] & carry[30]);
endgenerate

endmodule

module gen_carry_lookahead (
    input [31:0] a,
    input [31:0] b,
    output [31:0] carry
);

genvar i;

generate
    for (i = 0; i < 31; i = i + 1) begin : gen_carry_lookahead_loop
        assign carry[i] = a[i] & b[i];
    end

    assign carry[31] = a[31] & b[31];
endgenerate

endmodule

