module address(
  input CLK,
  input [7:0] featurebits,
  input [2:0] MAPPER,       // MCU detected mapper
  input [23:0] SNES_ADDR,   // requested address from SNES
  input [7:0] SNES_PA,      // peripheral address from SNES
  output [23:0] ROM_ADDR,   // Address to request from SRAM0
  output ROM_HIT,           // want to access RAM0
  output IS_SAVERAM,        // address/CS mapped as SRAM?
  output IS_ROM,            // address mapped as ROM?
  output IS_WRITABLE,       // address somehow mapped as writable area?
  input [23:0] SAVERAM_MASK,
  input [23:0] ROM_MASK,
  output msu_enable,
  output cx4_enable,
  output cx4_vect_enable,
  output r213f_enable,
  output snescmd_enable
);

parameter [2:0]
  FEAT_MSU1 = 3,
  FEAT_213F = 4
;

wire [23:0] SRAM_SNES_ADDR;

/* Cx4 mapper:
   - LoROM (extended to 00-7d, 80-ff)
   - MMIO @ 6000-7fff
   - SRAM @ 70-7d/80-ff:0000-7fff
 */

// Determine whether the address is mapped as ROM or SRAM
assign IS_ROM = ((!SNES_ADDR[22] & SNES_ADDR[15])
                 |(SNES_ADDR[22]));

assign IS_SAVERAM = |SAVERAM_MASK & (&SNES_ADDR[22:20] & ~SNES_ADDR[15] & (SNES_ADDR[19:16] < 4'b1110));

// Calculate the corresponding address in SRAM0 if the address is mapped as SRAM
assign SRAM_SNES_ADDR = IS_SAVERAM
                        ? (24'hE00000 | ({SNES_ADDR[19:16], SNES_ADDR[14:0]} 
                         & SAVERAM_MASK))
                        : ({2'b00, SNES_ADDR[22:16], SNES_ADDR[14:0]}
                         & ROM_MASK);

// Set the flags based on the mapping of the address
assign ROM_ADDR = SRAM_SNES_ADDR;
assign IS_WRITABLE = IS_SAVERAM;
assign ROM_HIT = IS_ROM | IS_WRITABLE;

// Set the control signals based on the inputs
wire msu_enable_w = featurebits[FEAT_MSU1] & (!SNES_ADDR[22] && ((SNES_ADDR[15:0] & 16'hfff8) == 16'h2000));
assign msu_enable = msu_enable_w;

wire cx4_enable_w = (!SNES_ADDR[22] && (SNES_ADDR[15:13] == 3'b011));
assign cx4_enable = cx4_enable_w;

assign cx4_vect_enable = &SNES_ADDR[15:5];

assign r213f_enable = featurebits[FEAT_213F] & (SNES_PA == 9'h3f);

assign snescmd_enable = ({SNES_ADDR[22], SNES_ADDR[15:9]} == 8'b0_0010101);

endmodule

module serial_to_parallel(
    input wire ser_in,
    input wire ce_16,
    input wire reset,
    output reg [7:0] rx_data,
    output reg new_rx_data
);

reg [1:0] in_sync;
reg [3:0] count16;
reg rx_busy;
reg [3:0] bit_count;
reg [7:0] data_buf;

always @ (posedge clock or posedge reset) begin
    if (reset) 
        in_sync <= 2'b11;
    else 
        in_sync <= {in_sync[0], ser_in};
end 

always @ (posedge clock or posedge reset) begin
    if (reset) 
        count16 <= 4'b0;
    else if (ce_16) begin 
        if (rx_busy | (in_sync[1] == 1'b0))
            count16 <= count16 + 4'b1;
        else 
            count16 <= 4'b0;
    end 
end 

assign ce_1 = (count16 == 4'b1111) & ce_16;
assign ce_1_mid = (count16 == 4'b0111) & ce_16;

always @ (posedge clock or posedge reset) begin 
    if (reset)
        rx_busy <= 1'b0;
    else if (~rx_busy & ce_1_mid)
        rx_busy <= 1'b1;
    else if (rx_busy & (bit_count == 4'h8) & ce_1_mid) 
        rx_busy <= 1'b0;
end 

always @ (posedge clock or posedge reset) begin 
    if (reset)
        bit_count <= 4'h0;
    else if (~rx_busy) 
        bit_count <= 4'h0;
    else if (rx_busy & ce_1_mid)
        bit_count <= bit_count + 4'h1;
end 

always @ (posedge clock or posedge reset) begin 
    if (reset)
        data_buf <= 8'h0;
    else if (rx_busy & ce_1_mid)
        data_buf <= {in_sync[1], data_buf[7:1]};
end 

always @ (posedge clock or posedge reset) begin 
    if (reset) begin 
        rx_data <= 8'h0;
        new_rx_data <= 1'b0;
    end 
    else if (rx_busy & (bit_count == 4'h8) & ce_1) begin 
        rx_data <= data_buf;
        new_rx_data <= 1'b1;
    end 
    else 
        new_rx_data <= 1'b0;
end 

endmodule

module FIR (
  input clk, // clock signal
  input reset, // reset signal
  input signed [n-1:0] in, // input signals
  output signed [m-1:0] out // output signals
);

parameter n = 4; // number of input signals
parameter m = 2; // number of output signals
parameter l = 5; // number of filter taps (coefficients)

reg signed [n-1:0] delay [0:l-1]; // delay line
reg signed [n-1:0] coeffs [0:l-1]; // filter coefficients
reg signed [m-1:0] sum; // sum of products

integer i;

always @(posedge clk) begin
  if (reset) begin
    // reset delay line and sum
    for (i = 0; i < l; i = i + 1) begin
      delay[i] <= 0;
      coeffs[i] <= 0;
    end
    sum <= 0;
  end else begin
    // shift in new input value
    delay[0] <= in;
    // compute sum of products
    sum <= 0;
    for (i = 0; i < l; i = i + 1) begin
      sum <= sum + delay[i] * coeffs[i];
    end
    // shift delay line
    for (i = l-1; i > 0; i = i - 1) begin
      delay[i] <= delay[i-1];
    end
  end
end

// assign output signals
assign out = sum;

endmodule

module edge_detection (
    input clk,
    input reset,      // Synchronous active-high reset
