module priority_arbiter(
    input clk,
    input rst_n,
    input [N-1:0] request,
    input success,
    input [N-1:0] priority,
    output [N-1:0] grant,
    output [N-1:0] state
);

parameter N = 4;

reg [N-1:0] current_request;
reg [N-1:0] current_priority;
reg [N-1:0] next_request;
reg [N-1:0] next_priority;
reg [N-1:0] current_state;
reg [N-1:0] next_state;

assign grant = (current_request == 0) ? {N{1'b0}} : {1'b0, {N-1{current_request[0] && (priority[0] >= priority[i])}}};

always @(posedge clk) begin
    if (!rst_n) begin
        current_request <= {N{1'b0}};
        current_priority <= {N{1'b0}};
        current_state <= {N{1'b0}};
    end else begin
        current_request <= (success) ? next_request : current_request;
        current_priority <= (success) ? next_priority : current_priority;
        current_state <= next_state;
    end
end

always @* begin
    next_request = current_request;
    next_priority = current_priority;
    next_state = current_state;

    if (success) begin
        next_request = {1'b0, current_request[0:N-2]};
        next_priority = {1'b0, current_priority[0:N-2]};
        next_state = {1'b0, current_request[0:N-2]};
    end else begin
        next_state = current_state | current_request;
    end
end

assign state = current_state;

endmodule

module adder_subtractor_module (
  input [3:0] a,
  input [3:0] b,
  input sub,
  output [3:0] result
);

  wire [3:0] adder_out;
  wire [3:0] twos_complement_b;
  wire carry_out;

  // Calculate the twos complement of b if we are performing subtraction
  assign twos_complement_b = sub ? (~b + 1) : b;

  // Calculate the output of the adder
  full_adder fa0(.a(a[0]), .b(twos_complement_b[0]), .c_in(sub), .sum(adder_out[0]), .c_out(carry_out));
  full_adder fa1(.a(a[1]), .b(twos_complement_b[1]), .c_in(carry_out), .sum(adder_out[1]), .c_out(carry_out));
  full_adder fa2(.a(a[2]), .b(twos_complement_b[2]), .c_in(carry_out), .sum(adder_out[2]), .c_out(carry_out));
  full_adder fa3(.a(a[3]), .b(twos_complement_b[3]), .c_in(carry_out), .sum(adder_out[3]), .c_out(carry_out));

  // Set the result to the output of the adder
  assign result = adder_out;

endmodule

