module GrayCodeStateMachine (
  input clk,
  input rst,
  output reg [n-1:0] state
);

parameter n = 3; // number of bits in the Gray code state

// Gray code sequence function
function [n-1:0] grayCode;
  input [n-1:0] binary;
  begin
    grayCode = binary ^ (binary >> 1);
  end
endfunction

// State transition logic
always @(posedge clk, posedge rst) begin
  if (rst) begin
    state <= 0;
  end else begin
    state <= grayCode(state) + 1;
  end
end

endmodule

