    full,
    clk,
    din,
    rst,
    rd_en,
    wr_en);
  output wr_rst_busy;
  output [63:0]dout;
  output empty;
  output full;
  input clk;
  input [63:0]din;
  input rst;
  input rd_en;
  input wr_en;

  wire [3:0] r_ptr;
  wire [3:0] w_ptr;
