  wire [15:0] old_data;
  wire [15:0] next_r_ptr;
  wire [15:0] next_w_ptr;
  wire empty;
  wire full;
  wire rd_en;
  wire wr_en;
  wire wr_rst_busy;

  assign empty = (count == 0);
  assign full = (count == 16);

  assign next_r_ptr = (empty) ? r_ptr : r_ptr + 1;
  assign next_w_ptr = (full) ? w_ptr : w_ptr + 1;

  assign new_data = {fifo_mem[w_ptr], din};
  assign old_data = fifo_mem[r_ptr];

  assign next_count = count + wr_en - rd_en - rst;

  always @(posedge clk) begin
    if (rst) begin
      wr_rst_busy <= 1;
      count <= 0;
      r_ptr <= 0;
      w_ptr <= 0;
      fifo_mem <= {16{16'h0}};
    end else begin
      wr_rst_busy <= (wr_en && full) || (rd_en && empty);
      if (wr_en && !full) begin
