    input up_down, // Select input to switch between up and down counting modes
    output reg [3:0] count // 4-bit binary up-down counter output
);

    reg [3:0] next_count;
    always @(posedge clk) begin
        if (reset) begin
            count <= 4'b0000;
        end else begin
            if (up_down) begin
                next_count = count + 1;
