  parameter RX_DATA = 8'h06;
  parameter RX_CRC = 8'h07;
  parameter RX_DONE = 8'h08;

  // Initialize variables
  assign frame_out = tx_frame;
  assign data_valid = tx_data_valid;
  assign error = tx_error_valid;
  assign ack = tx_ack;

  // Control signal handling
  always @ (posedge start) begin
    start_signal <= 1;
  end

  always @ (posedge stop) begin
    stop_signal <= 1;
  end

  always @ (posedge reset) begin
    reset_signal <= 1;
  end

  always @ (posedge enable) begin
    enable_signal <= enable;
  end

  always @ (posedge data_ready) begin
    data_ready_signal <= data_ready;
  end

  always @ (posedge slave_address) begin
    slave_address_signal <= slave_address;
  end

  // State machine
  always @ (posedge start or posedge stop or posedge reset or posedge enable or posedge data_ready or posedge slave_address or posedge tx_crc_result or posedge rx_crc_result) begin
    case (tx_state)
      IDLE: begin
        if (start_signal == 1) begin
          tx_pointer <= 0;
          tx_length <= 0;
          tx_crc_pointer <= 0;
          tx_crc_length <= 0;
          tx_crc_value <= 0;
          tx_crc_result <= 0;
          tx_error <= NO_ERROR;
          tx_data_valid <= 0;
          tx_error_valid <= 0;
          tx_ack <= 0;
          tx_slave_address <= slave_address_signal;
          tx_frame[0:5] <= DEST_MAC;
          tx_frame[6:11] <= SRC_MAC;
          tx_frame[12:13] <= ETHER_TYPE;
          tx_frame[14:15] <= FRAME_CTRL;
          tx_frame[16:23] <= tx_slave_address;
          tx_frame[24:31] <= tx_length;
          tx_frame[32:FRAME_SIZE-1] <= tx_data;
          tx_state <= TX_WAIT;
        end
      end

      TX_WAIT: begin
        if (enable_signal == 1) begin
          tx_state <= TX_DATA;
        end
      end

      TX_DATA: begin
        if (tx_pointer < tx_length) begin
          tx_frame[32+tx_pointer] <= tx_data[tx_pointer];
          tx_crc_value <= tx_crc_value ^ tx_data[tx_pointer];
          tx_pointer <= tx_pointer + 1;
        end else begin
          tx_crc_pointer <= 0;
          tx_crc_length <= 0;
          tx_crc_result <= 0;
          tx_state <= TX_CRC;
        end
      end

      TX_CRC: begin
        if (tx_crc_pointer < tx_crc_length) begin
          tx_crc_value <= tx_crc_value ^ tx_frame[32+tx_crc_pointer];
          tx_crc_pointer <= tx_crc_pointer + 1;
        end else begin
          tx_crc_result <= tx_crc_value;
          tx_state <= TX_DONE;
        end
      end

      TX_DONE: begin
        if (stop_signal == 1) begin
          tx_data_valid <= 1;
          tx_error_valid <= 0;
          tx_ack <= 0;
          tx_state <= IDLE;
        end
      end
    endcase

    case (rx_state)
      IDLE: begin
        if (data_ready_signal == 1) begin
          rx_pointer <= 0;
          rx_length <= 0;
          rx_crc_pointer <= 0;
          rx_crc_length <= 0;
          rx_crc_value <= 0;
          rx_crc_result <= 0;
          rx_error <= NO_ERROR;
          rx_data_valid <= 0;
          rx_error_valid <= 0;
          rx_ack <= 0;
          rx_slave_address <= frame_in[16:23];
          rx_length <= frame_in[24:31];
          rx_state <= RX_DATA;
        end
      end

      RX_DATA: begin
        if (rx_pointer < rx_length) begin
          rx_data[rx_pointer] <= frame_in[32+rx_pointer];
          rx_crc_value <= rx_crc_value ^ frame_in[32+rx_pointer];
          rx_pointer <= rx_pointer + 1;
        end else begin
          rx_crc_pointer <= 0;
          rx_crc_length <= 0;
          rx_crc_result <= 0;
          rx_state <= RX_CRC;
        end
      end

      RX_CRC: begin
        if (rx_crc_pointer < rx_crc_length) begin
          rx_crc_value <= rx_crc_value ^ frame_in[32+rx_length+rx_crc_pointer];
          rx_crc_pointer <= rx_crc_pointer + 1;
        end else begin
          rx_crc_result <= rx_crc_value;
          rx_state <= RX_DONE;
        end
      end

      RX_DONE: begin
        if (rx_crc_result != frame_in[32+rx_length+rx_crc_length]) begin
          rx_error <= CRC_ERROR;
        end else if (rx_length != rx_pointer) begin
          rx_error <= LENGTH_ERROR;
        end else if (rx_slave_address != slave_address_signal) begin
          rx_error <= FRAME_ERROR;
        end else begin
          rx_data_valid <= 1;
          rx_error_valid <= 0;
          rx_ack <= 1;
        end
        rx_state <= IDLE;
      end
    endcase
  end

endmodule

