module top_module( 
    input [2:0] a,
    input [2:0] b,
    output [2:0] out_xor_bitwise,
    output out_and_logical,
    output [5:0] out_not
);

    // Pipeline registers
    reg [2:0] a_reg1, a_reg2;
    reg [2:0] b_reg1, b_reg2;
    reg [2:0] not_a_reg1, not_a_reg2;
    reg [2:0] not_b_reg1, not_b_reg2;
    reg xor_bitwise_reg1, xor_bitwise_reg2;
    reg and_logical_reg1, and_logical_reg2;

    // Combinational logic
    assign out_xor_bitwise = xor_bitwise_reg2;
    assign out_and_logical = and_logical_reg2;
    assign out_not = {not_a_reg2, not_b_reg2};

    // Pipeline stages
    always @(posedge clk) begin
        a_reg1 <= a;
        b_reg1 <= b;
        not_a_reg1 <= ~a;
        not_b_reg1 <= ~b;
        xor_bitwise_reg1 <= a_reg1 ^ b_reg1;
        and_logical_reg1 <= a_reg1 & b_reg1;
    end

    always @(posedge clk) begin
        a_reg2 <= a_reg1;
        b_reg2 <= b_reg1;
        not_a_reg2 <= not_a_reg1;
        not_b_reg2 <= not_b_reg1;
        xor_bitwise_reg2 <= xor_bitwise_reg1;
        and_logical_reg2 <= and_logical_reg1;
    end

endmodule

module FSM (
  input [n-1:0] in,
  output reg [m-1:0] out
);

parameter n = 4; // number of input signals
parameter m = 2; // number of output signals
parameter s = 8; // number of states

reg [2:0] state; // 3-bit state encoding

// State transition table
always @ (in, state)
begin
  case (state)
    3'b000: if (in == 4'b0000) state <= 3'b000; else state <= 3'b001;
    3'b001: if (in == 4'b0000) state <= 3'b010; else state <= 3'b011;
    3'b010: if (in == 4'b0000) state <= 3'b100; else state <= 3'b101;
    3'b011: if (in == 4'b0000) state <= 3'b110; else state <= 3'b111;
    3'b100: if (in == 4'b0000) state <= 3'b000; else state <= 3'b001;
    3'b101: if (in == 4'b0000) state <= 3'b010; else state <= 3'b011;
    3'b110: if (in == 4'b0000) state <= 3'b100; else state <= 3'b101;
    3'b111: if (in == 4'b0000) state <= 3'b110; else state <= 3'b111;
  endcase
end

// Output function table
always @ (state)
begin
  case (state)
    3'b000: out <= 2'b00;
    3'b001: out <= 2'b01;
    3'b010: out <= 2'b10;
    3'b011: out <= 2'b11;
    3'b100: out <= 2'b00;
    3'b101: out <= 2'b01;
    3'b110: out <= 2'b10;
    3'b111: out <= 2'b11;
  endcase
end

endmodule

