module comparator_pipeline (
    input [3:0] A,
    input [3:0] B,
    output reg out
);

reg [3:0] A_reg;
reg [3:0] B_reg;
reg [3:0] A_next;
reg [3:0] B_next;
reg [2:0] stage;

always @(posedge clk) begin
    case(stage)
        0: begin
            A_reg <= A;
            B_reg <= B;
            A_next <= A_reg;
            B_next <= B_reg;
            stage <= 1;
        end
        1: begin
            A_next <= A_reg;
            B_next <= B_reg;
            stage <= 2;
        end
        2: begin
            A_next <= A;
            B_next <= B;
            stage <= 3;
        end
        3: begin
            A_next <= A;
            B_next <= B;
            stage <= 0;
        end
    endcase
end

always @(posedge clk) begin
    if(stage == 0) begin
        if(A_next < B_next) begin
            out <= 1'b1;
        end
        else if(A_next > B_next) begin
            out <= 1'b0;
        end
        else begin
            out <= 1'b0;
        end
    end
end

endmodule

