module unsigned_divider (
  input [31:0] div,
  input [31:0] dvsr,
  output [31:0] q,
  output [31:0] r
);

  reg [31:0] dividend_reg;
  reg [31:0] divisor_reg;
  reg [31:0] quotient_reg;
  reg [31:0] remainder_reg;
  reg [31:0] count_reg;

  always @(*) begin
    dividend_reg = div;
    divisor_reg = dvsr;
    count_reg = 32;
    quotient_reg = 0;
    remainder_reg = 0;

    if (divisor_reg == 0) begin
      quotient_reg = 0;
      remainder_reg = 0;
    end
    else if (dividend_reg < divisor_reg) begin
      quotient_reg = 0;
      remainder_reg = dividend_reg;
    end
    else begin
      while (count_reg > 0) begin
        if (dividend_reg >= divisor_reg) begin
          dividend_reg = dividend_reg - divisor_reg;
          quotient_reg = quotient_reg + (1 << (count_reg - 1));
        end
        divisor_reg = divisor_reg >> 1;
        count_reg = count_reg - 1;
      end
      remainder_reg = dividend_reg;
    end
  end

  assign q = quotient_reg;
  assign r = remainder_reg;

endmodule

module signed_divider (
