    end
  end

  assign q = quotient_reg;
  assign r = remainder_reg;

endmodule

module Modulo (
  input [31:0] a,
  input [31:0] b,
  output reg [31:0] c
);

  always @(*) begin
    if (b == 0) begin
      c <= 0;
    end else if (a < b) begin
      c <= a;
    end else begin
      c <= a - (a / b) * b;
    end
  end

endmodule

module ac97_interface (
  input wire clock_27mhz,
  input wire reset,
  input wire [4:0] volume,
  output wire [7:0] audio_in_data,
  input wire [7:0] audio_out_data,
  output wire ready,
  output reg audio_reset_b,
  output wire ac97_sdata_out,
  input wire ac97_sdata_in,
  output wire ac97_synch,
  input wire ac97_bit_clock
);

  // AC97 interface signals
  wire [7:0] command_address;
  wire [15:0] command_data;
  wire command_valid;
  wire [19:0] left_in_data, right_in_data;
  wire [19:0] left_out_data, right_out_data;

  // Wait a little before enabling the AC97 codec
  reg [9:0] reset_count;
  always @(posedge clock_27mhz) begin
    if (reset) begin
      audio_reset_b = 1'b0;
      reset_count = 0;
    end else if (reset_count == 1023)
      audio_reset_b = 1'b1;
    else
      reset_count = reset_count+1;
  end

  // Generate repeating sequence of read/writes to AC97 registers
  reg [1:0] ac97_state = 2'b00;
  always @(posedge clock_27mhz) begin
    case (ac97_state)
      2'b00: begin
        command_address = 8'h02;
        command_data = {8'h00, volume};
        command_valid = 1'b1;
        ac97_state = 2'b01;
      end
      2'b01: begin
        command_address = 8'h0c;
        command_data = {8'h00, volume};
        command_valid = 1'b1;
        ac97_state = 2'b10;
      end
      2'b10: begin
        command_address = 8'h0a;
        command_data = 16'h0000;
        command_valid = 1'b1;
        ac97_state = 2'b11;
      end
      2'b11: begin
        command_address = 8'h3e;
        command_data = 16'h0080;
        command_valid = 1'b1;
        ac97_state = 2'b00;
      end
    endcase
  end

  // Ready: one cycle pulse synchronous with clock_27mhz
  reg [2:0] ready_sync;
  always @ (posedge clock_27mhz) ready_sync <= {ready_sync[1:0], ready};
  assign ready = ready_sync[1] & ~ready_sync[2];

  reg [7:0] out_data;
  always @ (posedge clock_27mhz)
    if (ready) out_data <= audio_out_data;
  assign audio_in_data = {left_in_data[19:16], left_in_data[11:4]};
  assign left_out_data = {out_data, 12'b000000000000};
  assign right_out_data = left_out_data;

  // AC97 interface
  ac97 ac97(.ready(ready),
            .command_address(command_address),
            .command_data(command_data),
            .command_valid(command_valid),
            .left_data(left_out_data), .left_valid(1'b1),
            .right_data(right_out_data), .right_valid(1'b1),
            .left_in_data(left_in_data), .right_in_data(right_in_data),
            .ac97_sdata_out(ac97_sdata_out),
            .ac97_sdata_in(ac97_sdata_in),
            .ac97_synch(ac97_synch),
            .ac97_bit_clock(ac97_bit_clock));

endmodule

module profibus_telegram_length (
    input clk,
    input n_reset,
    input [7:0] in_byte,
    input new_byte,
    output reg length_valid,
    output reg [7:0] length,
    output reg error
);

    localparam STATE_START    = 0;
    localparam STATE_LE       = 1;
    localparam STATE_LER      = 2;

    localparam SD1           = 8'h10;
    localparam SD2           = 8'h68;
    localparam SD3           = 8'hA2;
    localparam SD4           = 8'hDC;
    localparam SC            = 8'hE5;

    reg [7:0] byte_le;
    reg [1:0] state;

    initial begin
        length_valid <= 0;
        length <= 0;
        error <= 0;
        byte_le <= 0;
        state <= STATE_START;
    end

    always @(posedge clk) begin
        if (n_reset) begin
            case (state)
                STATE_START: begin
                    if (new_byte) begin
                        if (in_byte == SD1) begin
                            length <= 6;
                            error <= 0;
                            length_valid <= 1;
                        end else if (in_byte == SD2) begin
                            length <= 0;
                            error <= 0;
                            length_valid <= 0;
                            state <= STATE_LE;
                        end else if (in_byte == SD3) begin
                            length <= 14;
                            error <= 0;
                            length_valid <= 1;
                        end else if (in_byte == SD4) begin
                            length <= 3;
                            error <= 0;
                            length_valid <= 1;
                        end else if (in_byte == SC) begin
                            length <= 1;
                            error <= 0;
                            length_valid <= 1;
                        end else begin
                            length <= 0;
                            error <= 1;
                            length_valid <= 0;
                        end
                    end
                end
                STATE_LE: begin
                    if (new_byte) begin
                        byte_le <= {byte_le[7:0], in_byte};
                        state <= STATE_LER;
                    end
                end
                STATE_LER: begin
                    if (new_byte) begin
                        length <= byte_le + 6;
                        error <= 0;
                        length_valid <= 1;
                        state <= STATE_START;
                    end
                end
                default: begin
                    length_valid <= 0;
                    length <= 0;
                    error <= 0;
                    byte_le <= 0;
                    state <= STATE_START;
                end
            endcase
        end else begin
            /* Reset */
            length_valid <= 0;
            length <= 0;
            error <= 0;
            byte_le <= 0;
            state <= STATE_START;
        end
    end
endmodule

module reverse_mux_and(
    input [7:0] in,
    input [3:0] in0,
    input [3:0] in1,
    input [3:0] in2,
    input [3:0] in3,
    input [1:0] sel,
    output [3:0] out
);

    // Reverse the input binary number
    wire [7:0] reversed_in;
    assign reversed_in = {in[7], in[6], in[5], in[4], in[3], in[2], in[1], in[0]};

    // Select one of the four 4-bit inputs using the 4-to-1 multiplexer
    wire [3:0] selected_input;
    assign selected_input = (sel == 2'b00) ? in0 :
                            (sel == 2'b01) ? in1 :
                            (sel == 2'b10) ? in2 :
                                             in3;

    // Perform bitwise AND of the reversed binary number and the selected input
    wire [3:0] and_output;
    assign and_output = reversed_in[7:4] & selected_input;

    // Output the result of the AND operation
    assign out = and_output;

endmodule

