    output [WIDTH-1:0] dout,
    output full,
    output empty
  );

  reg [WIDTH-1:0] buffer [0:15];
  reg [3:0] head;
  reg [3:0] tail;
  wire [3:0] count = head - tail;

  always @(posedge clk) begin
    if (reset) begin
      head <= 0;
      tail <= 0;
    end else begin
      if (wr_en && !full) begin
        buffer[head] <= din;
        head <= head + 1;
      end
      if (rd_en && !empty) begin
        dout <= buffer[tail];
        tail <= tail + 1;
      end
    end
  end

  assign full = (count == 16);
  assign empty = (count == 0);

