module i2c_master (
  input SCL,
  input SDA_out,
  output reg SDA_in,
  input [6:0] slave_addr,
  input read_write,
  input [7:0] data_out,
  output [7:0] data_in
);

  reg [7:0] tx_data;
  reg [7:0] rx_data;
  reg [3:0] state;
  reg [6:0] addr;
  reg ack;
  reg nack;

  assign data_in = rx_data;

  always @(posedge SCL) begin
    case(state)
      0: begin // Start condition
        if(!SDA_out || !SCL) begin
          state <= 0;
        end else begin
          state <= 1;
          SDA_in <= 0;
        end
      end
      1: begin // Send slave address
        if(!SCL) begin
          state <= 1;
        end else begin
          state <= 2;
          addr <= slave_addr;
          ack <= 0;
          nack <= 0;
        end
      end
      2: begin // Send data or read request
        if(!SCL) begin
          state <= 2;
        end else if(read_write) begin // Read from slave
          state <= 3;
          SDA_in <= 1;
        end else begin // Write to slave
          state <= 4;
          tx_data <= data_out;
          SDA_in <= tx_data[7];
        end
      end
      3: begin // Receive data from slave
        if(!SCL) begin
          state <= 3;
        end else begin
          state <= 5;
          rx_data <= rx_data << 1;
          rx_data[0] <= SDA_out;
          SDA_in <= ack;
        end
      end
      4: begin // Send data to slave
        if(!SCL) begin
          state <= 4;
        end else if(tx_data == 0) begin
          state <= 5;
          SDA_in <= ack;
        end else begin
          state <= 4;
          tx_data <= tx_data << 1;
          SDA_in <= tx_data[7];
        end
      end
      5: begin // Stop condition
        if(!SCL) begin
          state <= 5;
        end else begin
          state <= 0;
          SDA_in <= 1;
        end
      end
      default: begin
        state <= 0;
      end
    endcase
  end

  always @(negedge SCL) begin
    if(state == 2 && !read_write) begin // Write to slave
      SDA_in <= tx_data[6:0];
      tx_data <= tx_data << 1;
    end else if(state == 3) begin // Acknowledge or not acknowledge
      if(SDA_out) begin
        ack <= 1;
        nack <= 0;
      end else begin
        ack <= 0;
        nack <= 1;
      end
    end
  end

endmodule

module i2c_slave (
  input SCL,
  inout SDA,
  input [6:0] own_addr,
  output [7:0] data_out,
  inout [7:0] data_in
);

  reg [7:0] tx_data;
  reg [7:0] rx_data;
  reg [3:0] state;
  reg [6:0] addr;
  reg ack;
  reg nack;

  assign data_out = tx_data;

  always @(posedge SCL) begin
    case(state)
      0: begin // Idle state
        if(SDA) begin
          state <= 1;
          addr <= 0;
          ack <= 0;
          nack <= 0;
        end else begin
          state <= 0;
        end
      end
      1: begin // Receive slave address
        if(!SCL) begin
          state <= 1;
        end else begin
          state <= 2;
          addr[6:0] <= SDA;
          ack <= 1;
          nack <= 0;
        end
      end
      2: begin // Receive data or read request
        if(!SCL) begin
          state <= 2;
        end else if(addr == own_addr && !SDA) begin // Read request
          state <= 3;
          tx_data <= data_in;
          SDA <= 1;
        end else if(addr == own_addr && SDA) begin // Write request
          state <= 4;
          rx_data <= 0;
          SDA <= 1;
        end else begin // Address does not match
          state <= 0;
          ack <= 0;
          nack <= 0;
        end
      end
      3: begin // Send data to master
        if(!SCL) begin
          state <= 3;
        end else if(tx_data == 0) begin
          state <= 5;
          SDA <= 0;
        end else begin
          state <= 3;
          tx_data <= tx_data << 1;
          SDA <= tx_data[7];
        end
      end
      4: begin // Receive data from master
        if(!SCL) begin
          state <= 4;
        end else if(SDA) begin
          state <= 4;
          rx_data <= rx_data << 1;
          rx_data[0] <= 1;
        end else begin
          state <= 4;
          rx_data <= rx_data << 1;
          rx_data[0] <= 0;
        end
      end
      5: begin // Wait for stop condition
        if(!SCL && SDA) begin
          state <= 0;
          ack <= 0;
          nack <= 0;
        end else begin
          state <= 5;
        end
      end
      default: begin
        state <= 0;
      end
    endcase
  end

  always @(negedge SCL) begin
    if(state == 2 && addr == own_addr && SDA) begin // Not acknowledge
      ack <= 0;
      nack <= 1;
    end else if(state == 3) begin // Acknowledge or not acknowledge
      if(SDA) begin
        ack <= 0;
        nack <= 1;
      end else begin
        ack <= 1;
        nack <= 0;
      end
    end
  end

endmodule

module bitwise_logical_rotation(
    input [2:0] a,
    input [2:0] b,
    input clk,
    input reset,
    input load,
    input [1:0] ena,
    input [99:0] data,
    output [2:0] out_or_bitwise,
    output out_or_logical,
    output [5:0] out_not,
    output [99:0] final_output
);

// Bitwise-OR and Logical-OR circuit
wire [2:0] bitwise_or;
wire logical_or;

assign bitwise_or = a | b;
assign logical_or = (a != 0) || (b != 0);

// NOT circuit
wire [2:0] not_b;
wire [2:0] not_a;

assign not_b = ~b;
assign not_a = ~a;

// Rotation circuit
reg [99:0] shift_reg;

always @(posedge clk) begin
    if (reset) begin
        shift_reg <= 0;
    end else if (load) begin
        shift_reg <= data;
    end else if (ena == 2'b01) begin
        shift_reg <= {shift_reg[0], shift_reg[99:1]};
    end else if (ena == 2'b10) begin
        shift_reg <= {shift_reg[98:0], shift_reg[99]};
    end
end

// Final output circuit
wire [99:0] rotated_output;

assign rotated_output = (ena == 2'b00 || ena == 2'b11) ? shift_reg : ((ena == 2'b01) ? {shift_reg[0], shift_reg[99:1]} : {shift_reg[98:0], shift_reg[99]});

assign final_output = {rotated_output[99:1], bitwise_or[2], rotated_output[98:0], bitwise_or[1:0], logical_or};

assign out_or_bitwise = bitwise_or;
assign out_or_logical = logical_or;
assign out_not = {not_b[2:0], not_a[2:0]};

endmodule

module wb_bus_writer(
   input [15:0] rom_addr,
   input [47:0] rom_data,
   input [15:0] wb_adr_o,
   input        wb_cyc_o,
   input [3:0]  wb_sel_o,
   input        wb_stb_o,
   input        wb_we_o,
   input        start,
   output       done,
   output [31:0] wb_dat_o,
   input        wb_clk_i,
   input        wb_rst_i,
   output       wb_ack_i
);

   wire [31:0] wb_data;
   reg [3:0] byte_index;
   reg [31:0] count;

   assign wb_dat_o = wb_data;

   always @(posedge wb_clk_i or posedge wb_rst_i) begin
      if (wb_rst_i) begin
         byte_index <= 4'h0;
         count <= 32'h0;
         wb_data <= 32'h0;
      end else begin
         if (start) begin
            if (count == 32'h0) begin
               count <= 32'h4;
            end else if (count == 32'h4) begin
               if (wb_cyc_o && wb_stb_o) begin
                  wb_data[8*(byte_index+wb_sel_o)+:8] <= rom_data[8*byte_index+:8];
                  byte_index <= byte_index + 1;
                  if (byte_index == 4'h4) begin
                     count <= 32'h0;
                     wb_we_o <= 1'b1;
                  end
               end
            end
         end else begin
            count <= 32'h0;
            wb_we_o <= 1'b0;
         end
      end
   end

   assign done = (count == 32'h0) && (byte_index == 4'h4);

   assign wb_ack_i = (wb_cyc_o && wb_stb_o && wb_we_o);

endmodule

