module adder (
    input [7:0] a,
    input [7:0] b,
    output [7:0] s,
    output overflow
);

wire [7:0] c;
wire [7:0] p;
wire [7:0] g;

generate
    genvar i;
    for (i = 0; i < 8; i = i + 1) begin : carry_lookahead
        assign p[i] = a[i] ^ b[i];
        assign g[i] = a[i] & b[i];
        if (i == 0) begin
            assign c[i] = g[i];
        end else begin
            assign c[i] = g[i] | (p[i] & c[i-1]);
        end
    end
endgenerate

wire [7:0] sum;
wire overflow_carry;
assign overflow_carry = c[7] & p[7];
assign s = sum;
assign overflow = overflow_carry ^ (sum[7] & a[7] & b[7]);

generate
    genvar i;
    for (i = 0; i < 8; i = i + 1) begin : full_adder
        wire carry_in;
        if (i == 0) begin
            assign carry_in = g[i];
        end else begin
            assign carry_in = c[i-1];
        end
        assign sum[i] = a[i] ^ b[i] ^ carry_in;
    end
endgenerate

endmodule

