module axi_fifo (
   // Outputs
   rxwr_access, rxwr_packet, rxrd_access, rxrd_packet, rxrr_access,
   rxrr_packet, rxrd_fifo_wait, rxrr_fifo_wait, rxwr_fifo_wait,
   // Inputs
   sys_clk, rx_lclk_div4, erx_nreset, rxwr_wait, rxrd_wait, rxrr_wait,
   rxrd_fifo_access, rxrd_fifo_packet, rxrr_fifo_access,
   rxrr_fifo_packet, rxwr_fifo_access, rxwr_fifo_packet
   );

   parameter AW      = 32;
   parameter DW      = 32;
   parameter PW      = 104;
   parameter RFAW    = 6;
   parameter TARGET  = "GENERIC";

   //reset & clocks
   input        sys_clk;
   input        rx_lclk_div4;
   input        erx_nreset;     //keep in reset longer

   //WR to AXI master
   output       rxwr_access;    
   output [PW-1:0] rxwr_packet;
   input        rxwr_wait;

   //RD to AXI master
   output       rxrd_access;    
   output [PW-1:0] rxrd_packet;
   input        rxrd_wait;

   //RR to AXI slave
   output       rxrr_access;    
   output [PW-1:0] rxrr_packet;
   input        rxrr_wait;

   //RD from IO
   input        rxrd_fifo_access;  // To rxrd_fifo of fifo_cdc.v
   input [PW-1:0] rxrd_fifo_packet;  // To rxrd_fifo of fifo_cdc.v
   output       rxrd_fifo_wait;     // From rxrd_fifo of fifo_cdc.v

   //RR from IO
   input        rxrr_fifo_access;  // To rxrr_fifo of fifo_cdc.v
   input [PW-1:0] rxrr_fifo_packet;  // To rxrr_fifo of fifo_cdc.v
   output       rxrr_fifo_wait;     // From rxrr_fifo of fifo_cdc.v

   //WR from IO
   input        rxwr_fifo_access;  // To rxwr_fifo of fifo_cdc.v
   input [PW-1:0] rxwr_fifo_packet;  // To rxwr_fifo of fifo_cdc.v
   output       rxwr_fifo_wait;     // From rxwr_fifo of fifo_cdc.v

   wire [PW-1:0] fifo_out;
   wire fifo_empty;
   wire fifo_full;

   fifo #(.AW(AW), .DW(DW), .PW(PW), .RFAW(RFAW))
   fifo_inst (
      // Inputs
      .clk(sys_clk),
      .reset(erx_nreset),
      .wr_en(rxwr_wait),
      .wr_data(rxwr_fifo_packet),
      .rd_en(rxrd_wait),
      .rd_data(fifo_out),
      // Outputs
      .empty(fifo_empty),
      .full(fifo_full)
   );

   assign rxwr_access = rxwr_wait & !fifo_full;
   assign rxwr_packet = fifo_out;
   assign rxrd_access = rxrd_wait & !fifo_empty;
   assign rxrd_packet = fifo_out;
   assign rxrr_access = rxrr_wait & !fifo_empty;
   assign rxrr_packet = fifo_out;
   assign rxrd_fifo_wait = fifo_empty;
   assign rxrr_fifo_wait = fifo_empty;
   assign rxwr_fifo_wait = fifo_full;

endmodule

module fifo #(
   parameter AW = 16,  // Address width
   parameter DW = 8,   // Data width
   parameter PW = 32,  // Packet width
   parameter RFAW = 4  // Read Fifo Address Width
) (
   // Inputs
   input clk,
   input reset,
   input wr_en,
   input [PW-1:0] wr_data,
   input rd_en,
   // Outputs
   output reg [PW-1:0] rd_data,
   output empty,
   output full
);

   parameter ADDR_WIDTH = $clog2(PW/DW);
   parameter ADDR_BITS = AW - ADDR_WIDTH;
   parameter DEPTH = 1 << ADDR_BITS;
   parameter RF_DEPTH = 1 << RFAW;

   reg [ADDR_WIDTH-1:0] wr_ptr;
   reg [ADDR_WIDTH-1:0] rd_ptr;
   reg [ADDR_WIDTH-1:0] rd_fifo_ptr;
   reg [ADDR_WIDTH-1:0] rd_fifo_ptr_next;
   reg [ADDR_WIDTH-1:0] wr_fifo_ptr;
   reg [ADDR_WIDTH-1:0] wr_fifo_ptr_next;
   reg [ADDR_WIDTH-1:0] count;
   reg [ADDR_WIDTH-1:0] rf_count;

   reg [DW-1:0] mem [0:DEPTH-1];
   reg [DW-1:0] rf_mem [0:RF_DEPTH-1];

   always @(posedge clk or negedge reset) begin
      if (!reset) begin
         wr_ptr <= 0;
         rd_ptr <= 0;
         rd_fifo_ptr <= 0;
         rd_fifo_ptr_next <= 0;
         wr_fifo_ptr <= 0;
         wr_fifo_ptr_next <= 0;
         count <= 0;
         rf_count <= 0;
      end else begin
         if (wr_en && !full) begin
            mem[wr_ptr] <= wr_data[(DW*wr_ptr)+:DW];
            wr_ptr <= wr_ptr + 1;
            count <= count + 1;
         end
         if (rd_en && !empty) begin
            rd_data <= {mem[rd_ptr], {(DW-1){1'b0}}};
            rd_ptr <= rd_ptr + 1;
            count <= count - 1;
         end
         if (rd_fifo_ptr_next != rd_fifo_ptr) begin
            rd_fifo_ptr <= rd_fifo_ptr_next;
            rf_count <= rf_count - 1;
         end
         if (wr_fifo_ptr_next != wr_fifo_ptr) begin
            wr_fifo_ptr <= wr_fifo_ptr_next;
            rf_count <= rf_count + 1;
         end
      end
   end

   always @(posedge clk or negedge reset) begin
      if (!reset) begin
         rd_fifo_ptr_next <= 0;
         wr_fifo_ptr_next <= 0;
      end else begin
         if (rd_en && !empty) begin
            rd_fifo_ptr_next <= (rd_fifo_ptr == RF_DEPTH-1) ? 0 : rd_fifo_ptr + 1;
         end
         if (wr_en && !full) begin
            wr_fifo_ptr_next <= (wr_fifo_ptr == RF_DEPTH-1) ? 0 : wr_fifo_ptr + 1;
         end
      end
   end

   assign empty = (count == 0);
   assign full = (count == DEPTH);

endmodule

