module FSM (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 4; // number of input signals
parameter m = 2; // number of output signals
parameter s = 8; // number of states in the FSM

reg [log2(s)-1:0] state; // register to hold current state
reg [log2(s)-1:0] next_state; // register to hold next state

// state transition table
always @ (state or in) begin
  case (state)
    3'b000: if (in[0]) next_state = 3'b001; else next_state = 3'b010;
    3'b001: if (in[1]) next_state = 3'b011; else next_state = 3'b100;
    3'b010: if (in[2]) next_state = 3'b011; else next_state = 3'b100;
    3'b011: if (in[3]) next_state = 3'b111; else next_state = 3'b100;
    3'b100: if (in[0]) next_state = 3'b101; else next_state = 3'b110;
    3'b101: if (in[1]) next_state = 3'b011; else next_state = 3'b110;
    3'b110: if (in[2]) next_state = 3'b011; else next_state = 3'b100;
    3'b111: if (in[3]) next_state = 3'b111; else next_state = 3'b100;
  endcase
end

// output signals
always @ (state or in) begin
  case (state)
    3'b000: out = {1'b0, 1'b0};
    3'b001: out = {1'b0, 1'b1};
    3'b010: out = {1'b1, 1'b0};
    3'b011: out = {1'b1, 1'b1};
    3'b100: out = {1'b1, 1'b0};
    3'b101: out = {1'b1, 1'b1};
    3'b110: out = {1'b0, 1'b1};
    3'b111: out = {1'b1, 1'b1};
  endcase
end

// state register
always @ (posedge clk) begin
  state <= next_state;
end

endmodule

module top_module (
    input [15:0] in,
    input [3:0] shift,
    input [3:0] A,
    input [15:0] B,
    input sel,
    output [15:0] out
);

    wire [15:0] barrel_out;
    wire [3:0] barrel_shift;
    wire [3:0] shift_abs;
    wire [3:0] shift_sel;
    wire [15:0] A_out;
    wire [15:0] B_out;

    // Calculate absolute value of shift
    assign shift_abs = (shift < 0) ? -shift : shift;

    // Select which barrel shifter to use
    assign shift_sel = (sel == 0) ? shift[3:0] : {shift[2:0], 0};

    // Instantiate barrel shifters
    barrel_shift_4bit barrel_shift_4bit_inst (
        .in(in),
        .shift(shift_sel),
        .out(barrel_out[3:0])
    );

    barrel_shift_16bit barrel_shift_16bit_inst (
        .in(in),
        .shift(shift_sel),
        .out(barrel_out)
    );

    // Connect A and B inputs to output S based on sel
    assign out = (sel == 0) ? A_out : B_out;

    // Instantiate 4-bit barrel shifter for A input
    barrel_shift_4bit barrel_shift_4bit_A_inst (
        .in(A),
        .shift(shift_abs[1:0]),
        .out(A_out[3:0])
    );

    // Instantiate 16-bit barrel shifter for B input
    barrel_shift_16bit barrel_shift_16bit_B_inst (
        .in(B),
        .shift(shift_abs),
        .out(B_out)
    );

endmodule

