);

always @(*) begin
    out[15:12] = in;
    out[11:8] = in << 1;
    out[7:4] = in << 2;
    out[3:0] = in << 3;
end

endmodule

module shd_fifo_wr_logic
   (full,
    O1,
    Q,
    O2,
    I1,
    wr_clk,
    rst_d2,
    wr_en,
    RD_PNTR_WR,
    rst_full_gen_i,
    I2);
  output full;
  output O1;
  output [0:0]Q;
  output [8:0]O2;
  input [0:0]I1;
  input wr_clk;
  input rst_d2;
  input wr_en;
  input [8:0]RD_PNTR_WR;
  input rst_full_gen_i;
  input [0:0]I2;

  reg [31:0] fifo [0:31];
  reg [4:0] write_pointer;
  wire [4:0] read_pointer;
  reg [3:0] counter;
  reg full;
  wire empty;
  wire [0:0]I1;
  wire [0:0]I2;
  wire O1;
  wire [8:0]O2;
  wire [0:0]Q;
  wire [8:0]RD_PNTR_WR;
  wire [4:0]\c1/v1_reg ;
  wire [3:0]\c2/v1_reg ;
  wire wr_clk;
  wire wr_en;

  // Write logic
  always @(posedge wr_clk, posedge rst_d2) begin
    if (rst_d2) begin
      write_pointer <= 0;
      counter <= 0;
      full <= 0;
    end else if (wr_en && !full) begin
      fifo[write_pointer] <= I1;
      write_pointer <= write_pointer + 1;
      counter <= counter + 1;
      if (write_pointer == 31) begin
        full <= 1;
      end
    end
  end

  // Read logic
  assign empty = (write_pointer == read_pointer) && !full;
  always @(posedge wr_clk, posedge rst_full_gen_i) begin
    if (rst_full_gen_i) begin
      read_pointer <= 0;
    end else if (!empty) begin
      Q <= fifo[read_pointer];
      read_pointer <= read_pointer + 1;
      O1 <= 1;
      if (read_pointer == 31) begin
        O1 <= 0;
      end
      if (read_pointer == RD_PNTR_WR) begin
        O1 <= 0;
      end
    end
  end

  // Counter logic
  always @(posedge wr_clk) begin
    O2 <= counter;
  end

endmodule

module BUFGCTRL (
