  parameter [0:0] IS_IGNORE1_INVERTED = 1'b0;
  parameter [0:0] IS_CE0_INVERTED = 1'b0;
  parameter [0:0] IS_CE1_INVERTED = 1'b0;
  parameter [0:0] IS_S0_INVERTED = 1'b0;
  parameter [0:0] IS_S1_INVERTED = 1'b0;

  parameter _TECHMAP_CONSTMSK_IGNORE0_ = 0;
  parameter _TECHMAP_CONSTVAL_IGNORE0_ = 0;
  parameter _TECHMAP_CONSTMSK_IGNORE1_ = 0;
  parameter _TECHMAP_CONSTVAL_IGNORE1_ = 0;
  parameter _TECHMAP_CONSTMSK_CE0_ = 0;
  parameter _TECHMAP_CONSTVAL_CE0_ = 0;
  parameter _TECHMAP_CONSTMSK_CE1_ = 0;
  parameter _TECHMAP_CONSTVAL_CE1_ = 0;
  parameter _TECHMAP_CONSTMSK_S0_ = 0;
  parameter _TECHMAP_CONSTVAL_S0_ = 0;
  parameter _TECHMAP_CONSTMSK_S1_ = 0;
  parameter _TECHMAP_CONSTVAL_S1_ = 0;

  localparam [0:0] INV_IGNORE0 = (
      _TECHMAP_CONSTMSK_IGNORE0_ == 1 &&
      _TECHMAP_CONSTVAL_IGNORE0_ == 0 &&
      IS_IGNORE0_INVERTED == 0);
  localparam [0:0] INV_IGNORE1 = (
      _TECHMAP_CONSTMSK_IGNORE1_ == 1 &&
      _TECHMAP_CONSTVAL_IGNORE1_ == 0 &&
      IS_IGNORE1_INVERTED == 0);
  localparam [0:0] INV_CE0 = (
      _TECHMAP_CONSTMSK_CE0_ == 1 &&
      _TECHMAP_CONSTVAL_CE0_ == 0 &&
      IS_CE0_INVERTED == 0);
  localparam [0:0] INV_CE1 = (
      _TECHMAP_CONSTMSK_CE1_ == 1 &&
      _TECHMAP_CONSTVAL_CE1_ == 0 &&
      IS_CE1_INVERTED == 0);
  localparam [0:0] INV_S0 = (
      _TECHMAP_CONSTMSK_S0_ == 1 &&
      _TECHMAP_CONSTVAL_S0_ == 0 &&
      IS_S0_INVERTED == 0);
  localparam [0:0] INV_S1 = (
      _TECHMAP_CONSTMSK_S1_ == 1 &&
      _TECHMAP_CONSTVAL_S1_ == 0 &&
      IS_S1_INVERTED == 0);

  BUFGCTRL_VPR #(
      .INIT_OUT(INIT_OUT),
      .ZPRESELECT_I0(PRESELECT_I0),
      .ZPRESELECT_I1(PRESELECT_I1),
      .IS_IGNORE0_INVERTED(!IS_IGNORE0_INVERTED ^ INV_IGNORE0),
      .IS_IGNORE1_INVERTED(!IS_IGNORE1_INVERTED ^ INV_IGNORE1),
      .ZINV_CE0(!IS_CE0_INVERTED ^ INV_CE0),
      .ZINV_CE1(!IS_CE1_INVERTED ^ INV_CE1),
      .ZINV_S0(!IS_S0_INVERTED ^ INV_S0),
      .ZINV_S1(!IS_S1_INVERTED ^ INV_S1)
  ) BUFGCTRL_inst (
    .O(O),
    .CE0(CE0 ^ INV_CE0),
    .CE1(CE1 ^ INV_CE1),
    .I0(I0),
    .I1(I1),
    .IGNORE0(IGNORE0 ^ INV_IGNORE0),
    .IGNORE1(IGNORE1 ^ INV_IGNORE1),
    .S0(S0 ^ INV_S0),
    .S1(S1 ^ INV_S1)
  );

endmodule

module fsm_traffic_light (
  input clk,
  input reset,
  input button,
  output reg green,
  output reg yellow,
  output reg red,
  output reg pedestrian
);

  parameter GREEN_DURATION = 10;
  parameter YELLOW_DURATION = 2;
  parameter RED_DURATION = 10;
  parameter PEDESTRIAN_DURATION = 5;

  // define states
  localparam IDLE = 2'b00;
  localparam GREEN = 2'b01;
  localparam YELLOW = 2'b10;
  localparam RED = 2'b11;
  localparam PEDESTRIAN = 2'b100;

  reg [1:0] state;
  reg [3:0] count;

  always @(posedge clk) begin
    if (reset) begin
      state <= RED;
      count <= 0;
    end
    else begin
      case (state)
        GREEN: begin
          if (count == GREEN_DURATION * 2) begin
            state <= YELLOW;
            count <= 0;
          end
          else begin
            count <= count + 1;
          end
        end

        YELLOW: begin
          if (count == YELLOW_DURATION * 2) begin
            if (button) begin
              state <= PEDESTRIAN;
              count <= 0;
            end
            else begin
              state <= RED;
              count <= 0;
            end
          end
          else begin
            count <= count + 1;
          end
        end

        RED: begin
          if (count == RED_DURATION * 2) begin
            state <= GREEN;
            count <= 0;
          end
          else begin
            count <= count + 1;
          end
        end

        PEDESTRIAN: begin
          if (count == PEDESTRIAN_DURATION * 2) begin
            state <= RED;
            count <= 0;
          end
          else begin
            count <= count + 1;
          end
        end

        default: begin
          state <= RED;
          count <= 0;
        end
      endcase
    end
  end

  always @(state) begin
    case (state)
      GREEN: begin
        green <= 1;
        yellow <= 0;
        red <= 0;
        pedestrian <= 0;
      end

      YELLOW: begin
        green <= 0;
        yellow <= 1;
        red <= 0;
        pedestrian <= 0;
      end

      RED: begin
        green <= 0;
        yellow <= 0;
        red <= 1;
        pedestrian <= 0;
      end

      PEDESTRIAN: begin
        green <= 0;
        yellow <= 0;
        red <= 0;
        pedestrian <= 1;
      end

      default: begin
        green <= 0;
        yellow <= 0;
        red <= 1;
        pedestrian <= 0;
      end
    endcase
  end

endmodule

module gray_shift_register (
    input CLK,
    input RST,
    input [7:0] data_in,
    input shift,
    input load,
    output reg [7:0] shift_reg_out,
    output reg [7:0] counter_out,
    output reg [7:0] final_output
);

reg [7:0] gray_counter_out;
reg [7:0] shift_reg [7:0];

always @(posedge CLK) begin
    if (RST) begin
        gray_counter_out <= 8'b00000000;
        shift_reg <= 8'b00000000;
    end else begin
        gray_counter_out <= gray_counter_out + 1;
        if (load) begin
            shift_reg <= data_in;
        end else if (shift) begin
            shift_reg <= {shift_reg[6:0], 1'b0};
        end
    end
end

assign counter_out = gray_counter_out ^ (gray_counter_out >> 1);

assign shift_reg_out = shift_reg ^ (shift_reg >> 1);

always @(*) begin
    if (select) begin
        final_output = shift_reg_out;
    end else begin
        final_output = counter_out;
    end
end

endmodule

