module barrel_shifter_alu (
    input [3:0] A,
    input [3:0] B,
    input dir,
    input [2:0] op,
    output [3:0] S
);

    // Barrel Shifter
    wire [3:0] shifted_value;
    assign shifted_value = (dir) ? {A[2:0], 1'b0} : {1'b0, A[3:1]};

    // ALU
    wire [3:0] alu_result;
    assign alu_result = (op == 3'b000) ? (A + shifted_value) :
                        (op == 3'b001) ? (A - shifted_value) :
                        (op == 3'b010) ? (A & shifted_value) :
                        (op == 3'b011) ? (A | shifted_value) :
                        (op == 3'b100) ? (A ^ shifted_value) :
                        (op == 3'b101) ? (shifted_value << 1) :
                        4'b0;

    // Output
    assign S = alu_result;

endmodule

module dilation_block(
    input clock,
    input resetn,
    input valid_in,
    output stall_out,
    output valid_out,
    input stall_in,
    input [31:0] workgroup_size,
    input start
);

localparam BUFFER_SIZE = 32; // Size of the output buffer

reg [BUFFER_SIZE-1:0] buffer; // Output buffer
reg [31:0] num_buffered; // Number of valid data in the output buffer
reg [31:0] num_input; // Number of valid input data
reg [31:0] num_output; // Number of valid output data

// Merge node
wire merge_stall;
reg merge_valid_in;
wire merge_valid_out;
reg merge_data_to_buffer_valid;
reg merge_data_to_output_valid;

// Branch node
wire branch_inputs_ready;
wire branch_output_regs_ready;
reg branch_stall_in;
reg branch_valid_out;

// Counters
reg [31:0] input_counter;
reg [31:0] output_counter;

// Reset all registers to zero on low resetn
always @(posedge clock or negedge resetn) begin
    if (~resetn) begin
        buffer <= 0;
        num_buffered <= 0;
        num_input <= 0;
        num_output <= 0;
        merge_valid_in <= 0;
        merge_data_to_buffer_valid <= 0;
        merge_data_to_output_valid <= 0;
        branch_valid_out <= 0;
        input_counter <= 0;
        output_counter <= 0;
    end
end

// Count valid input data
always @(posedge clock or negedge resetn) begin
    if (~resetn) begin
        num_input <= 0;
    end else begin
        if (valid_in && ~branch_stall_in && start) begin
            num_input <= num_input + 1;
        end
    end
end

// Count valid output data
always @(posedge clock or negedge resetn) begin
    if (~resetn) begin
        num_output <= 0;
    end else begin
        if (branch_valid_out && ~stall_in) begin
            num_output <= num_output + 1;
        end
    end
end

// Merge node
assign merge_stall = (buffer_size - num_buffered) <= num_input;
assign stall_out = merge_stall;
assign merge_valid_out = merge_data_to_buffer_valid || merge_data_to_output_valid;

always @(*) begin
    if (merge_valid_in || valid_in) begin
        merge_data_to_output_valid = 1;
        merge_data_to_buffer_valid = 0;
    end else begin
        merge_data_to_output_valid = 0;
        merge_data_to_buffer_valid = 0;
    end
end

always @(posedge clock or negedge resetn) begin
    if (~resetn) begin
        merge_valid_in <= 0;
    end else begin
        merge_valid_in <= merge_valid_out && ~merge_stall;
    end
end

// Branch node
assign branch_inputs_ready = merge_valid_out;
assign branch_output_regs_ready = ~stall_in;
assign branch_stall_in = ~branch_output_regs_ready || ~branch_inputs_ready;
assign valid_out = branch_valid_out;

always @(posedge clock or negedge resetn) begin
    if (~resetn) begin
        branch_valid_out <= 0;
    end else begin
        if (branch_inputs_ready && branch_output_regs_ready) begin
            branch_valid_out <= 1;
        end else begin
            branch_valid_out <= 0;
        end
    end
end

// Buffer input data
always @(posedge clock or negedge resetn) begin
    if (~resetn) begin
        buffer <= 0;
        num_buffered <= 0;
    end else begin
        if (merge_data_to_buffer_valid && ~merge_stall) begin
            buffer[num_buffered] <= valid_in;
            num_buffered <= num_buffered + 1;
        end
    end
end

// Output data from buffer
always @(posedge clock or negedge resetn) begin
    if (~resetn) begin
        output_counter <= 0;
    end else begin
        if (branch_valid_out && ~stall_in && num_buffered > 0) begin
            branch_valid_out <= buffer[output_counter];
            output_counter <= output_counter + 1;
            num_buffered <= num_buffered - 1;
        end
    end
end

// Output data directly
always @(posedge clock or negedge resetn) begin
    if (~resetn) begin
        input_counter <= 0;
    end else begin
        if (merge_data_to_output_valid && ~merge_stall) begin
            branch_valid_out <= valid_in;
            input_counter <= input_counter + 1;
        end
    end
end

endmodule

module POR (
  input power,
  input clk,
  output reset
);

parameter rst_time = 10; // length of time the reset signal should be asserted

reg [31:0] rst_counter;
reg reset_reg;

always @(posedge clk) begin
  if (power) begin
    rst_counter <= rst_counter + 1;
    if (rst_counter >= rst_time) begin
      reset_reg <= 1'b1;
      rst_counter <= 0;
    end
  end else begin
    reset_reg <= 1'b0;
    rst_counter <= 0;
  end
end

assign reset = reset_reg;

endmodule

