module BOR (
  input Vin,
  input Reset_en,
  input Threshold,
  output Reset
);

parameter RESET_DURATION = 10; // duration of reset pulse (in clock cycles)

reg [1:0] state; // state machine to control reset pulse generation
reg [7:0] counter; // counter to measure reset pulse duration
reg comparator_out; // output of voltage comparator
reg one_shot_out; // output of one-shot pulse generator

// ADC module to convert analog input Vin to digital signal
// (not shown here)

// Comparator module to compare Threshold with Vin
// (not shown here)

// One-shot pulse generator module to generate reset pulse
// (not shown here)

// State machine to control reset pulse generation
always @ (posedge clk) begin
  if (Reset_en) begin
    case (state)
      2'b00: begin // idle state
        if (comparator_out) begin
          state <= 2'b01; // trigger one-shot pulse generator
          counter <= 0;
        end
      end
      2'b01: begin // reset pulse generation state
        if (counter < RESET_DURATION) begin
          one_shot_out <= 1;
          counter <= counter + 1;
        end else begin
          one_shot_out <= 0;
          state <= 2'b00; // return to idle state
        end
      end
    endcase
  end else begin
    state <= 2'b00; // reset state machine
    counter <= 0;
    one_shot_out <= 0;
  end
end

assign Reset = one_shot_out;

endmodule

module pwm_controller(
    input clk,
    input areset,  // async active-high reset to zero
    input select,
    input [3:0] duty_cycle,
    output reg red_LED,
    output reg green_LED,
    output reg blue_LED
);

reg [3:0] buffer[0:7];
reg [2:0] index;
reg [3:0] counter;

always @(posedge clk or posedge areset) begin
    if (areset) begin
        index <= 0;
        counter <= 0;
        red_LED <= 0;
        green_LED <= 0;
        blue_LED <= 0;
    end else begin
        if (select == 0) begin
            buffer[index] <= duty_cycle;
            index <= (index == 7) ? 0 : index + 1;
        end else begin
            buffer[index] <= buffer[(index == 0) ? 7 : index - 1];
            index <= (index == 7) ? 0 : index + 1;
        end

        if (counter == buffer[0]) begin
            red_LED <= 1;
        end else begin
            red_LED <= 0;
        end

        if (counter == buffer[1]) begin
            green_LED <= 1;
        end else begin
            green_LED <= 0;
        end

        if (counter == buffer[2]) begin
            blue_LED <= 1;
        end else begin
            blue_LED <= 0;
        end

        counter <= (counter == 15) ? 0 : counter + 1;
    end
end

endmodule

