always @(posedge clk or posedge areset) begin
    if (areset) begin
        counter <= 0;
        pwm_out <= 0;
    end else begin
        if (counter < duty_cycle) begin
            pwm_out <= 1;
        end else begin
            pwm_out <= 0;
        end

        counter <= (counter == 15) ? 0 : counter + 1;
    end
end

endmodule

