module glitch_filter (
  input [m-1:0] in,
  output [m-1:0] out
);

parameter n = 4; // number of clock cycles
parameter m = 8; // number of bits in input signal

reg [m-1:0] shift_reg [0:n-1];
reg [m-1:0] prev_signal;
reg [m-1:0] curr_signal;

integer i;

always @(posedge clk) begin
  // shift the input signal into the shift register
  for (i = n-1; i > 0; i = i - 1) begin
    shift_reg[i] <= shift_reg[i-1];
  end
  shift_reg[0] <= in;

  // compare the current signal with the signal from n clock cycles ago
  prev_signal <= shift_reg[n-1];
  curr_signal <= in;
  if (abs(curr_signal - prev_signal) > (prev_signal >> 1)) begin
    // if the input signal has changed by more than 50%, output the signal from n clock cycles ago
    out <= prev_signal;
  end else begin
    // otherwise, output the current signal
    out <= curr_signal;
  end
end

endmodule

