module counter_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input up_down,    // Control input to select count direction
    output reg [3:0] q);

    reg [3:0] initial_count;
    reg [3:0] final_count;

    always @(posedge clk) begin
        if (reset) begin
            q <= 4'b0000;
            initial_count <= 4'b0000;
            final_count <= 4'b0000;
        end else begin
            if (up_down) begin
                if (q == 4'b1010) begin
                    q <= 4'b0000;
                end else begin
                    q <= q + 1;
                end
            end else begin
                if (q == 4'b0000) begin
                    q <= 4'b1010;
                end else begin
                    q <= q - 1;
                end
            end
        end
    end

    always @(posedge clk) begin
        if (reset) begin
            initial_count <= 4'b0000;
        end else begin
            initial_count <= q;
        end
    end

    always @(posedge clk) begin
        if (reset) begin
            final_count <= 4'b0000;
        end else begin
            final_count <= q - initial_count;
        end
    end

endmodule

