priority_encoder pe(.in(in), .pos(pos_wire));
assign pos = pos_wire;

// Rotator
reg [99:0] q_reg;
always @(posedge clk) begin
    if (reset) begin
        q_reg <= 0;
    end else if (load) begin
        q_reg <= data;
    end else if (ena == 2'b10) begin
        q_reg <= {q_reg[98:0], q_reg[99]};
    end else if (ena == 2'b01) begin
        q_reg <= {q_reg[0], q_reg[99:1]};
    end
end
assign q = q_reg;

// Bitwise AND module
reg [1:0] pos_reg;
always @(posedge clk) begin
    if (reset) begin
        pos_reg <= 0;
    end else begin
        pos_reg <= pos;
    end
end
always @(posedge clk) begin
    if (reset) begin
        and_out <= 0;
    end else begin
        if (pos_reg == 2'b00) begin
            and_out <= 0;
        end else if (pos_reg == 2'b01) begin
            and_out <= q & 2'b01;
        end else if (pos_reg == 2'b10) begin
            and_out <= q & 2'b10;
        end else begin
            and_out <= q;
        end
    end
end

