    wire [7:0] in_2 = in[15:8];

    // Priority Encoder
    wire [7:0] priority = ~in_1 & ~in_2;
    wire [2:0] priority_pos;
    assign priority_pos = priority[7:5] ? 2 :
                          priority[4:3] ? 1 :
                          priority[2] ? 0 :
                          3'b111;

    // Additional Functional Module
    reg [7:0] out_reg;
    reg [2:0] position_reg;
    always @(posedge clk) begin
        out_reg <= in_1 | in_2;
        position_reg <= priority_pos;
    end

    // Multiplexer
    always @(*) begin
        if (position_reg == 3'b111) begin
            out = out_reg;
            position = position_reg;
        end else begin
            out = {out_reg[7:position_reg+1], out_reg[position_reg]};
