module ram_dp_sp_sum(
    input clk,
    input rst_n,
    input write_en,
    input [7:0] write_addr,
    input [3:0] write_data,
    input read_en,
    input [7:0] read_addr,
    output reg [3:0] read_data,
    input [15:0] in,
    output reg [7:0] out_hi,
    output reg [7:0] out_lo,
    output reg [15:0] out_sum
);

    // True Dual-Port RAM
    reg [3:0] mem [0:7];
    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1) begin
            mem[i] = 4'b0000;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            read_data <= 4'b0000;
        end
        else begin
            if (read_en) begin
                read_data <= mem[read_addr];
            end
            if (write_en) begin
                mem[write_addr] <= write_data;
            end
        end
    end

    // 16-bit Splitter
    reg [7:0] in_hi;
    reg [7:0] in_lo;
    always @(in) begin
        in_hi = in >> 8;
        in_lo = in & 8'hFF;
        out_hi = in_hi;
        out_lo = in_lo;
    end

    // Additional Functional Module
    reg [15:0] sum;
    always @(in or read_data) begin
        sum = in + read_data;
        out_sum = sum;
    end

endmodule

module shift_register (
  input clk,
  input reset,
  input shift_left,
  input shift_right,
  input [7:0] data_in,
  output [7:0] data_out
);

  reg [7:0] register;
  wire [7:0] and_output;

  dual_edge_ff #(.WIDTH(8)) ff (
    .clk(clk),
    .reset(reset),
    .data_in(data_in),
    .data_out(register)
  );

  assign and_output = register & data_in;

  always @ (posedge clk or negedge reset) begin
    if (!reset) begin
      register <= 8'b0;
    end else begin
      if (shift_left) begin
        register <= {register[6:0], register[7]};
      end else if (shift_right) begin
        register <= {register[0], register[7:1]};
      end
    end
  end

  assign data_out = register;

endmodule

