    );

    full_adder FA2(
        .A(A[2]),
        .B(B[2]),
        .Cin(C_temp[1]),
        .S(S[2]),
        .C(C_temp[2])
    );

    full_adder FA3(
        .A(A[3]),
        .B(B[3]),
        .Cin(C_temp[2]),
        .S(S[3]),
        .C(C[3])
    );

