module top_module( 
    input A,
    input [255:0] in,
    input [7:0] sel,
    input B,
    input C,
    output out );

    // Implementing the 256-to-1 multiplexer using a decoder and a 2-to-1 multiplexer
    wire [255:0] decoder_out;
    wire [1:0] mux_sel;
    decoder dec_256_to_1(.in(sel), .out(decoder_out));
    mux_2to1 mux_256_to_1(.in0(in[decoder_out]), .in1(in[decoder_out+1]), .sel(mux_sel), .out(out_mux));

    // Implementing the AND gate using NAND gates
    wire nand1_out, nand2_out;
    nand nand1(.in1(B), .in2(out_mux), .out(nand1_out));
    nand nand2(.in1(nand1_out), .in2(C), .out(nand2_out));

    // Selecting the output based on the value of A
    assign out = A ? out_mux : nand2_out;

endmodule

// Implementing the decoder for the 256-to-1 multiplexer
module decoder(
    input [7:0] in,
    output [255:0] out
    );

    genvar i;
    generate
        for(i=0; i<256; i=i+1) begin
            assign out[i] = (in == i) ? 1'b1 : 1'b0;
        end
    endgenerate

endmodule

// Implementing the 2-to-1 multiplexer for the 256-to-1 multiplexer
module mux_2to1(
    input in0,
    input in1,
    input sel,
    output out
    );

    assign out = sel ? in1 : in0;

endmodule

// Implementing the NAND gate
module nand(
    input in1,
    input in2,
    output out
    );

    assign out = ~(in1 & in2);

endmodule

module myfifo (
  input rst,
  input wr_clk,
  input rd_clk,
  input [35:0] din,
  input wr_en,
  input rd_en,
  output [71:0] dout,
  output full,
  output empty,
  output prog_full
);

  reg [35:0] fifo_mem [0:1023];
  reg [10:0] wr_ptr = 0;
  reg [10:0] rd_ptr = 0;
  reg [10:0] fifo_count = 0;

  assign empty = (fifo_count == 0);
  assign full = (fifo_count == 1024);

  always @(posedge wr_clk or negedge rst) begin
    if (!rst) begin
      wr_ptr <= 0;
      fifo_count <= 0;
    end else if (wr_en && !full) begin
      fifo_mem[wr_ptr] <= din;
      wr_ptr <= (wr_ptr == 1023) ? 0 : wr_ptr + 1;
      fifo_count <= fifo_count + 1;
    end
  end

  always @(posedge rd_clk or negedge rst) begin
    if (!rst) begin
      rd_ptr <= 0;
    end else if (rd_en && !empty) begin
      dout <= {fifo_mem[rd_ptr], fifo_mem[rd_ptr+1]};
      rd_ptr <= (rd_ptr == 1023) ? 0 : rd_ptr + 1;
      fifo_count <= fifo_count - 1;
    end
  end

  assign prog_full = (fifo_count >= 900);

endmodule

module digital_clock (
    input wire clk,
    input wire reset,
    input wire set,
    output wire [3:0] hours,
    output wire [5:0] minutes,
    output wire [5:0] seconds,
    output wire am_pm
);

reg [3:0] hours_reg;
reg [5:0] minutes_reg;
reg [5:0] seconds_reg;
reg am_pm_reg;

reg [3:0] hours_set;
reg [5:0] minutes_set;
reg [5:0] seconds_set;
reg am_pm_set;

reg [1:0] state;
localparam [1:0] IDLE = 2'b00;
localparam [1:0] SETTING = 2'b01;
localparam [1:0] COUNTING = 2'b10;

always @ (posedge clk) begin
    if (reset) begin
        hours_reg <= 4'b0001;
        minutes_reg <= 6'b000000;
        seconds_reg <= 6'b000000;
        am_pm_reg <= 1'b0;
        state <= IDLE;
    end else begin
        case (state)
            IDLE: begin
                if (set) begin
                    hours_set <= hours_reg;
                    minutes_set <= minutes_reg;
                    seconds_set <= seconds_reg;
                    am_pm_set <= am_pm_reg;
                    state <= SETTING;
                end else begin
                    if (seconds_reg == 6'd59) begin
                        seconds_reg <= 6'd0;
                        if (minutes_reg == 6'd59) begin
                            minutes_reg <= 6'd0;
                            if (hours_reg == 4'd11) begin
                                hours_reg <= 4'd0;
                                am_pm_reg <= ~am_pm_reg;
                            end else if (hours_reg == 4'd9) begin
                                hours_reg <= 4'd10;
                            end else if (hours_reg == 4'd23) begin
                                hours_reg <= 4'd0;
                            end else begin
                                hours_reg <= hours_reg + 1;
                            end
                        end else begin
                            minutes_reg <= minutes_reg + 1;
                        end
                    end else begin
                        seconds_reg <= seconds_reg + 1;
                    end
                    state <= COUNTING;
                end
            end
            SETTING: begin
                if (!set) begin
                    hours_reg <= hours_set;
                    minutes_reg <= minutes_set;
                    seconds_reg <= seconds_set;
                    am_pm_reg <= am_pm_set;
                    state <= IDLE;
                end
            end
            COUNTING: begin
                state <= IDLE;
            end
        endcase
    end
end

assign hours = hours_reg;
assign minutes = minutes_reg;
assign seconds = seconds_reg;
assign am_pm = am_pm_reg;

endmodule

