module FSM_Convert_Float_To_Fixed(

    //INPUTS
    input wire CLK, //system clock
    input wire RST_FF, //system reset 
    input wire Exp_out, // INDICA SI EL VALOR DEL EXPONENTE ES MAYOR QUE 127 
    input wire Begin_FSM_FF, //inicia la maquina de estados 
    input wire [7:0] Exp, //CONTIENE EL EXPONENTE DEL NUMERO EN PUNTO FLOTANTE 
    // OUTPUTS		
    output reg EN_REG1, //ENABLE PARA EL REGISTRO QUE GUARDA EL NUMERO EN PUNTO FLOTANTE 
    output reg LOAD, //SELECCION PARA EL REGISTRO DE DESPLAZAMIENTOS 
    output reg MS_1, // SELECCION DEL MUX 1 (VALOR INICIAL DEL EXPONENTE , VALOR MODIFICADO DEL EXPONENTE)
    output reg ACK_FF, // INDICA QUE LA CONVERSION FUE REALIZADA
    output reg EN_MS_1,
    output reg EN_REG2,
    output reg RST
    );

parameter [3:0]  //se definen los estados que se utilizaran en la maquina
     a = 4'b0000,
     b = 4'b0001,
     c = 4'b0010,
     d = 4'b0011,
     e = 4'b0100,
     f = 4'b0101,
     g = 4'b0110,
     h = 4'b0111,
     i = 4'b1000;

reg [3:0] state_reg, state_next ; //state registers declaration

always @(posedge CLK, posedge RST_FF)

	if (RST_FF) begin
		state_reg <= a;	
	end

	else begin
		state_reg <= state_next;
	end

    always @*
    begin
        state_next = state_reg;    
        EN_REG1 = 1'b0;
        EN_REG2 = 1'b0;
        ACK_FF = 1'b0;
        EN_MS_1=1'b0;
        MS_1=1'b0;
        LOAD = 1'b0;
        RST = 1'b0;

        case(state_reg)
            a: 
            begin  
                if(Begin_FSM_FF) 
                    begin
                    RST = 1'b1;
                    ACK_FF = 1'b0;    
                    state_next = b;
                    end
                else
                    state_next = a;       
            end

            b: 
            begin
                EN_REG1 = 1'b1;    
                state_next = c;
            end

            c:
            begin
                EN_MS_1 = 1'b1;
                if(Exp_out) //if exponent greater than 127
                    MS_1 = 1'b1; //select modified exponent
                else
                    MS_1 = 1'b0; //select initial exponent
                if(Exp == 8'b01111111) //if exponent is all 1's
                    state_next = i; //go to state i
                else
                    state_next = d; //go to state d
            end

            d:
            begin
                EN_MS_1 = 1'b1;
                MS_1 = 1'b1; //select modified exponent
                state_next = e;
            end

            e:
            begin
                state_next = f;
            end 

            f:
            begin
                LOAD = 1'b1;
                state_next = g;
            end

            g:
            begin
                EN_REG2 = 1'b1;
                state_next = h;
            end

            h:
            begin
                ACK_FF = 1'b1;
                if(RST_FF)
                     state_next = a;
                else
                    state_next = h;
            end

            i:
            begin
                state_next = f;
            end

       default:
       state_next=a;
       endcase
    end

endmodule

module spi(
  input clk,
  input SCK,
  input MOSI,
  inout MISO,
  input SSEL,
  output cmd_ready,
  output param_ready,
  output [7:0] cmd_data,
  output [7:0] param_data,
  output endmessage,
  output startmessage,
  input [7:0] input_data,
  output [31:0] byte_cnt,
  output [2:0] bit_cnt
);

// Register for storing the command byte
reg [7:0] cmd_data_r;
// Register for storing the parameter byte
reg [7:0] param_data_r;

// Registers for storing the Slave Select signal and its previous values
reg [2:0] SSELr;
reg [2:0] SSELSCKr;

// Register for storing the bit count for one SPI byte and the byte count for the message
reg [2:0] bitcnt;
// Register for storing the bit count for one SPI byte and the byte count for the message after wrapping around
reg [2:0] bitcnt_wrap_r;
// Register for storing the number of bytes that have been received
reg [31:0] byte_cnt_r;

// Register for storing the received byte
reg [7:0] byte_data_received;
// Register for storing whether a byte has been received
reg byte_received;

// Register for storing the cmd_ready signal delayed by one clock cycle
reg cmd_ready_r;
// Register for storing the param_ready signal delayed by one clock cycle
reg param_ready_r;

// Initialize the bit count to 0
initial bitcnt = 3'b000;

// Update the Slave Select register on every clock cycle
always @(posedge clk) SSELr <= {SSELr[1:0], SSEL};
// Update the SSELSCK register on every SCK edge
always @(posedge SCK) SSELSCKr <= {SSELSCKr[1:0], SSEL};

// Generate signals for the start and end of the SPI message
wire SSEL_inactive = SSELr[1];
wire SSEL_active = ~SSELr[1];
wire SSEL_startmessage = (SSELr[2:1]==2'b10);
wire SSEL_endmessage = (SSELr[2:1]==2'b01);
assign endmessage = SSEL_endmessage;
assign startmessage = SSEL_startmessage;

// Update the bit count for every SCK edge
always @(posedge SCK) begin
  if(SSELSCKr[1]) bitcnt <= 3'b000;
  else bitcnt <= bitcnt + 3'b001;
end

// Update the received byte on every SCK edge
always @(posedge SCK) begin
  if(~SSELSCKr[1])
    byte_data_received <= {byte_data_received[6:0], MOSI};
  if(~SSELSCKr[1] && bitcnt==3'b111)
    byte_received <= 1'b1;
  else byte_received <= 1'b0;
end

// Update the byte count on every clock cycle
always @(posedge clk) begin
  if(SSEL_inactive)
    byte_cnt_r <= 0;
  else if(byte_received && bitcnt_wrap_r[2:1] == 2'b10)
    byte_cnt_r <= byte_cnt_r + 1;
end

// Output the received data on the cmd_data and param_data signals when the cmd_ready and param_ready signals are high, respectively
always @(posedge clk) begin
  if (SSEL_startmessage)
    cmd_data_r <= 8'h00;
  else if(cmd_ready_r && byte_received && bitcnt_wrap_r[2:1] == 2'b10)
    cmd_data_r <= byte_data_received;
  else if(param_ready_r && byte_received && bitcnt_wrap_r[2:1] == 2'b10)
    param_data_r <= byte_data_received;
end

// Delay the cmd_ready and param_ready signals by one clock cycle
always @(posedge clk) begin
  cmd_ready_r <= cmd_ready_r2;
  param_ready_r <= param_ready_r2;
end

// Update the cmd_ready and param_ready signals
always @(posedge clk) begin
  if(SSEL_inactive) begin
    cmd_ready_r2 <= 1'b0;
    param_ready_r2 <= 1'b0;
  end
  else if(byte_received && bitcnt_wrap_r[2:1] == 2'b10) begin
    if(byte_cnt_r == 0)
      cmd_ready_r2 <= 1'b1;
    else
      param_ready_r2 <= 1'b1;
  end
end

// Output the cmd_ready and param_ready signals
assign cmd_ready = cmd_ready_r;
assign param_ready = param_ready_r;

// Output the cmd_data and param_data signals
assign cmd_data = cmd_data_r;
assign param_data = param_data_r;

// Output the byte count and bit count signals
assign byte_cnt = byte_cnt_r;
assign bit_cnt = bitcnt;

// Generate the MISO signal
assign MISO = ~SSEL ? input_data[7-bitcnt] : 1'bZ;

endmodule

module mux4to1 (
    A,
    B,
    C,
    D,
    S0,
    S1,
    Y
);

input A, B, C, D, S0, S1;
output Y;

wire w1, w2, w3;

and #(1) and1(w1, A, ~S0, ~S1);
and #(1) and2(w2, B, S0, ~S1);
and #(1) and3(w3, C, ~S0, S1);

or #(1) or1(Y, w1, w2, w3, D);

endmodule

module max_min_finder (
    input clk,
    input reset,
    input [31:0] in,
    output reg [31:0] max,
    output reg [31:0] min
);

