reg [31:0] current_min;

always @(posedge clk) begin
    if (reset) begin
        current_max <= 32'h80000000;
        current_min <= 32'h7FFFFFFF;
    end else begin
        if (in > current_max) begin
            current_max <= in;
        end
        if (in < current_min) begin
            current_min <= in;
        end
    end
end

assign max = current_max;
assign min = current_min;

endmodule

module booth_multiplier (
    input [3:0] A,
    input [3:0] B,
    output reg [7:0] P
);

reg [7:0] P_reg;
reg [4:0] B_reg;
reg [4:0] A_reg;
reg [2:0] i;

always @(*) begin
    P_reg = 0;
    B_reg = {1'b0, B};
    A_reg = {1'b0, A};
    for (i = 0; i < 4; i = i + 1) begin
        if (B_reg[1:0] == 2'b01) begin
            P_reg = P_reg + (A_reg << (2*i));
        end else if (B_reg[1:0] == 2'b10) begin
            P_reg = P_reg + (A_reg << (2*i+1));
        end
        if (B_reg[0] == 1'b0) begin
            B_reg = B_reg >> 1;
        end else begin
            B_reg = B_reg + 4'b1111;
        end
    end
    P = P_reg;
end

endmodule

module bm_dag1_log_mod(clock, 
                        reset_n, 
