module counter (
  input clk,
  input reset,
  input enable,
  input load,
  input [3:0] data_in,
  output reg [3:0] q,
  output reg overflow
);

  always @(posedge clk) begin
    if (reset) begin
      q <= 4'b0;
      overflow <= 1'b0;
    end else if (load) begin
      q <= data_in;
      overflow <= (data_in == 4'hf);
    end else if (enable) begin
      q <= q + 4'b1;
      overflow <= (q == 4'hf);
    end else begin
      overflow <= (q == 4'hf);
    end
  end

endmodule

module top_module (
    input clk,
    input reset,
    input [2:0] vec,
    input [7:0] in,
    output wire anyedge,
    output wire o2,
    output wire o1,
    output wire o0
);

reg [1:0] vec_reg;
reg anyedge_reg;
wire edge;
wire select;

assign select = vec[0];

assign o2 = vec[2];
assign o1 = vec[1];
assign o0 = select ? vec[1] : vec[2];

always @(negedge clk) begin
    if (reset) begin
        vec_reg <= 0;
        anyedge_reg <= 0;
    end else begin
        vec_reg <= vec;
        anyedge_reg <= edge;
    end
end

assign edge = vec_reg[1] ^ vec_reg[0];

always @(*) begin
    anyedge = anyedge_reg;
    if (edge) begin
        anyedge = 1;
    end
end

endmodule

module memory_controller_monitor #(
   parameter TCQ           = 100,  
   parameter DWIDTH = 32
)
(
   input                            clk_i  ,        
   input                            rst_i ,
   input                            manual_clear_error,
   input                            data_error_i ,  
   input [DWIDTH-1:0]               cmp_data_i,     
   input [DWIDTH-1:0]               rd_data_i ,     
   input [31:0]                     cmp_addr_i ,    
   input [5:0]                      cmp_bl_i ,      
   input                            mcb_cmd_full_i ,
   input                            mcb_wr_full_i,  
   input                            mcb_rd_empty_i, 
   output reg [64 + (2*DWIDTH - 1):0] error_status,   
   output                           error                  
);

reg data_error_r;
reg error_set;
assign  error = error_set;

always @ (posedge clk_i) begin
    data_error_r <= #TCQ  data_error_i;
    if (rst_i || manual_clear_error) begin
        error_status <= #TCQ  'b0;
        error_set    <= #TCQ  1'b0;
    end
    else begin
        if (data_error_i && ~data_error_r && ~error_set ) begin
            error_status[31:0]  <= #TCQ  cmp_addr_i;
            error_status[37:32] <= #TCQ  cmp_bl_i;
            error_status[40]    <= #TCQ  mcb_cmd_full_i;
            error_status[41]    <= #TCQ  mcb_wr_full_i;
            error_status[42]    <= #TCQ  mcb_rd_empty_i;
            error_set           <= #TCQ  1'b1;
            error_status[64 + (DWIDTH - 1)  :64]           <= #TCQ  cmp_data_i;
            error_status[64 + (2*DWIDTH - 1):64 + DWIDTH]  <= #TCQ  rd_data_i;
        end
        error_status[39:38]  <= #TCQ  'b0;    // reserved
        error_status[63:43]  <= #TCQ  'b0;    // reserved
    end
end

endmodule

