module fpoint_qsys_mult_single (
    input aclr, // asynchronous clear signal
    input clk_en, // clock enable signal
    input clock, // clock signal
    input [31:0] dataa, // input operand A
    input [31:0] datab, // input operand B
    output [31:0] result // output result
);

    wire [31:0] mantissa_a, mantissa_b, mantissa_c;
    wire [7:0] exponent_a, exponent_b, exponent_c;
    wire sign_a, sign_b, sign_c;
    wire [1:0] exp_diff;
    wire [63:0] prod;
    wire [31:0] mantissa_prod;
    wire [7:0] exponent_prod;
    wire sign_prod;

    // Convert input operands to binary representation using IEEE 754 standard
    ieee754_to_binary ieee_a(.in(dataa), .mantissa(mantissa_a), .exponent(exponent_a), .sign(sign_a));
    ieee754_to_binary ieee_b(.in(datab), .mantissa(mantissa_b), .exponent(exponent_b), .sign(sign_b));

    // Multiply mantissas
    assign prod = {mantissa_a, 23'b0} * {mantissa_b, 23'b0};
    assign mantissa_prod = prod[46:23];
    assign exponent_prod = exponent_a + exponent_b - 127;

    // Normalize mantissa and adjust exponent
    assign exp_diff = (mantissa_prod[23]) ? exponent_prod + 1 : exponent_prod;
    assign mantissa_c = (mantissa_prod[23]) ? {mantissa_prod[22:0], 1'b0} : mantissa_prod;

    // Convert result mantissa and exponent back to binary format using IEEE 754 standard
    binary_to_ieee754 ieee_c(.mantissa(mantissa_c), .exponent(exp_diff), .sign(sign_c), .out(result));

endmodule


module fpoint_qsys_addsub_single (
    input aclr, // asynchronous clear signal
    input add_sub, // addition/subtraction select signal
    input clk_en, // clock enable signal
    input clock, // clock signal
    input [31:0] dataa, // input operand A
    input [31:0] datab, // input operand B
    output [31:0] result // output result
);

    wire [31:0] mantissa_a, mantissa_b, mantissa_c;
    wire [7:0] exponent_a, exponent_b, exponent_c;
    wire sign_a, sign_b, sign_c;
    wire [1:0] exp_diff;
    wire [31:0] mantissa_diff;
    wire [7:0] exponent_diff;
    wire sign_diff;

    // Convert input operands to binary representation using IEEE 754 standard
    ieee754_to_binary ieee_a(.in(dataa), .mantissa(mantissa_a), .exponent(exponent_a), .sign(sign_a));
    ieee754_to_binary ieee_b(.in(datab), .mantissa(mantissa_b), .exponent(exponent_b), .sign(sign_b));

    // Add or subtract mantissas based on add_sub signal
    assign mantissa_diff = (add_sub) ? mantissa_a - mantissa_b : mantissa_a + mantissa_b;
    assign sign_diff = (add_sub) ? sign_a ^ sign_b : sign_a;

    // Normalize mantissa and adjust exponent
    assign exp_diff = (mantissa_diff[23]) ? exponent_a : exponent_a - 1;
    assign mantissa_c = (mantissa_diff[23]) ? {mantissa_diff[22:0], 1'b0} : mantissa_diff;

    // Convert result mantissa and exponent back to binary format using IEEE 754 standard
    binary_to_ieee754 ieee_c(.mantissa(mantissa_c), .exponent(exp_diff), .sign(sign_diff), .out(result));

endmodule


module ieee754_to_binary (
    input [31:0] in, // input value in IEEE 754 format
    output [31:0] mantissa, // output mantissa in binary format
    output [7:0] exponent, // output exponent in binary format
    output sign // output sign
);

    assign sign = in[31];
    assign exponent = in[30:23] - 127;
    assign mantissa = (exponent == -127) ? {1'b0, in[22:0]} : {1'b1, in[22:0]};

endmodule


module binary_to_ieee754 (
    input [31:0] mantissa, // input mantissa in binary format
    input [7:0] exponent, // input exponent in binary format
    input sign, // input sign
    output reg [31:0] out // output value in IEEE 754 format
);

    always @(*) begin
        if (exponent < -126) begin
            out = {sign, 8'd0, {23{1'b0}}};
        end else if (exponent > 127) begin
            out = {sign, 8'd255, {23{1'b0}}};
        end else begin
            out = {sign, exponent + 127, mantissa[22:0]};
        end
    end

endmodule

module barrel_shifter (
    input [3:0] A,
    input [1:0] Shift,
    input Direction,
    output [3:0] Y
);

    reg [3:0] temp;

    always @(*) begin
        if (Direction == 0) // Left shift
            temp = {A[Shift[1:0]], A[3:Shift[1:0]+1]};
        else // Right shift
            temp = {A[3-Shift[1:0]+1:0], A[3:3-Shift[1:0]+1]};
    end

    assign Y = temp;

endmodule

module addsub(clk, rst, a, b, sub, result);
