module DMem(
    input wire rst_n,
    input wire [`WIDTH - 1:0] add,
    inout wire [`WIDTH - 1:0] data,
    input wire wr,
    input wire rd,
    output reg rd_st,
    input wire [1:0] mode //mode: 0-word, 1-halfword, 2-byte
);

    reg [7:0] mem [0:`WIDTH - 1];
    reg [`WIDTH - 1:0] data_r;

    assign data = (rd == 1)? data_r : 32'bZ;

    always @(posedge wr) begin
        case (mode)
            0: begin // word
                {mem[add], mem[add+1], mem[add+2], mem[add+3]} = data;
            end
            1: begin // half-word
                {mem[add], mem[add+1]} = data[15:0];
            end
            2: begin // byte
                mem[add] = data[7:0];
            end
        endcase
    end

    always @(posedge rd) begin
        rd_st = 0;
        case (mode)
            0: begin // word
                data_r = {mem[add], mem[add+1], mem[add+2], mem[add+3]};
                rd_st = 1;
            end
            1: begin // half-word
                data_r = {16'b0 ,mem[add], mem[add+1]};
                rd_st = 1;
            end
            2: begin // byte
                data_r = {24'b0, mem[add]};
                rd_st = 1;
            end
        endcase
    end

    always @(negedge rst_n) begin
        $readmemh("data.hex", mem, 0, 20);
    end

endmodule

module fifo_generator (
  input [11:0] din,
  input wr_en,
  input rd_en,
  input clk,
  input srst,
  output [11:0] dout,
  output empty,
  output full
);

  parameter DEPTH = 1024;
  parameter WIDTH = 12;

  reg [WIDTH-1:0] ram [0:DEPTH-1];
  reg [WIDTH-1:0] dout_reg;
  reg [WIDTH-1:0] wr_ptr = 0;
  reg [WIDTH-1:0] rd_ptr = 0;
  reg empty_reg;
  reg full_reg;

  always @(posedge clk or negedge srst) begin
    if (~srst) begin
      wr_ptr <= 0;
      rd_ptr <= 0;
      empty_reg <= 1;
      full_reg <= 0;
    end else begin
      if (wr_en && ~full_reg) begin
        ram[wr_ptr] <= din;
        wr_ptr <= wr_ptr + 1;
        if (wr_ptr == DEPTH-1) begin
          wr_ptr <= 0;
        end
        if (wr_ptr == rd_ptr) begin
          full_reg <= 1;
        end
        empty_reg <= 0;
      end
      if (rd_en && ~empty_reg) begin
        dout_reg <= ram[rd_ptr];
        rd_ptr <= rd_ptr + 1;
        if (rd_ptr == DEPTH-1) begin
          rd_ptr <= 0;
        end
        if (rd_ptr == wr_ptr) begin
          empty_reg <= 1;
        end
        full_reg <= 0;
      end
    end
  end

  assign dout = dout_reg;
  assign empty = empty_reg;
  assign full = full_reg;

endmodule

module nfc_transmitter (
  input [7:0] data,
  output tx
);
  reg [7:0] carrier_wave;
  assign tx = carrier_wave;

  always @ (data) begin
    // Modulation scheme: amplitude modulation
    carrier_wave = {8{data}}; // Repeat the data signal 8 times
  end
endmodule
module nfc_receiver (
  input rx,
  output [7:0] data
);
  reg [7:0] received_signal;
  reg [7:0] decoded_data;

  always @ (rx) begin
    // Demodulation scheme: envelope detection
    received_signal = rx;
    if (received_signal > 127) begin
      decoded_data = 1;
    end else begin
      decoded_data = 0;
    end
  end

  always @ (decoded_data) begin
    // Error correction code: none
    data = decoded_data;
  end
endmodule

module my_module (
    input [3:0] a,
    input [3:0] b,
    input [1:0] c,
    input d,
    input e,
    output reg x
);

    reg [4:0] sum;
    reg [1:0] index;
    reg selected_bit;

    always @(*) begin
        sum = a + b;
        case (c)
            2'b00: index = 2'b00;
            2'b01: index = 2'b01;
            2'b10: index = 2'b10;
            2'b11: index = 2'b11;
        endcase
        selected_bit = sum[index];
        if (d == 1) begin
            selected_bit = ~selected_bit;
        end
        if (e == 1) begin
            x = selected_bit;
        end else begin
            x = d;
        end
    end

endmodule

