module priority_encoder(
    input [3:0] in,
    output reg [1:0] out,
    input reset
);

    wire [3:0] gray;
    wire [3:0] binary;

    assign gray[0] = in[0];
    assign gray[1] = in[0] ^ in[1];
    assign gray[2] = in[1] ^ in[2];
    assign gray[3] = in[2] ^ in[3];

    assign binary[0] = gray[0];
    assign binary[1] = gray[0] ^ gray[1];
    assign binary[2] = gray[1] ^ gray[2];
    assign binary[3] = gray[2] ^ gray[3];

    always @ (posedge reset) begin
        out <= 2'b0;
    end

    always @ (*) begin
        case (binary)
            4'b0001: out = 2'b00;
            4'b0010: out = 2'b01;
            4'b0100: out = 2'b10;
            4'b1000: out = 2'b11;
            default: out = 2'b00;
        endcase
    end

endmodule

