    assign temp_sum = {1'b0, a} + {1'b0, b};
    assign s = temp_sum[7:0];
    assign carry = temp_sum[8];

    assign overflow = (a[7] == b[7] && s[7] != a[7]) || (a[7] == 1 && b[7] == 1 && s[7] == 0);

