module adder_subtractor (
    input [7:0] A,
    input [7:0] B,
    input carry_in,
    input sub,
    output reg [7:0] sum,
    output reg borrow_out
);

    always @(*) begin
        if (sub) begin
            sum <= A - B - carry_in;
            if (A < B + carry_in) begin
                borrow_out <= 1;
            end else begin
                borrow_out <= 0;
            end
        end else begin
            sum <= A + B + carry_in;
            if (sum < A | sum < B) begin
                borrow_out <= 1;
            end else begin
                borrow_out <= 0;
            end
        end
