  reg [7:0] tx_data;
  reg start_bit, stop_bit;

  always @(posedge clk) begin
    if (reset) begin
      pulse_count <= 0;
      tx_data <= 0;
      start_bit <= 0;
      stop_bit <= 0;
    end else begin
      if (pulse_count == 0) begin
        if (!start_bit) begin
          start_bit <= 1;
          pulse_count <= 16;
        end else if (tx_data == 0 && !stop_bit) begin
          stop_bit <= 1;
          pulse_count <= 8;
        end else if (tx_data != 0) begin
          pulse_count <= 8;
          tx_out <= 1;
        end
      end else begin
        pulse_count <= pulse_count - 1;
        tx_out <= 0;
        if (pulse_count == 0) begin
          if (tx_data != 0) begin
            tx_data <= tx_data >> 1;
          end
        end
      end
    end
  end

  always @(posedge clk) begin
    if (reset) begin
      pulse_count <= 0;
      tx_data <= 0;
      start_bit <= 0;
      stop_bit <= 0;
    end else begin
      if (pulse_count == 0) begin
        if (!start_bit) begin
          start_bit <= 1;
          pulse_count <= 16;
        end else if (tx_data == 0 && !stop_bit) begin
          stop_bit <= 1;
          pulse_count <= 8;
        end else if (tx_data != 0) begin
          pulse_count <= 8;
          tx_out <= 1;
        end
      end else begin
        pulse_count <= pulse_count - 1;
        tx_out <= 0;
        if (pulse_count == 0) begin
          if (tx_data != 0) begin
            tx_data <= tx_data >> 1;
          end
        end
      end
    end
  end

