module barrel_shifter_4bit (
    input [3:0] in,
    input [1:0] shift,
    output reg [3:0] out
);

reg [3:0] stage1_out;
reg [3:0] stage2_out;

always @(*) begin
    case(shift)
        2'b00: stage1_out = in << 1; // logical left shift
        2'b01: stage1_out = in >> 1; // logical right shift
        2'b10: stage1_out = {in[2], in[3], in[3], in[3]}; // arithmetic left shift
        2'b11: stage1_out = {in[3], in[2], in[1], in[0]}; // arithmetic right shift
    endcase
end

assign out = stage2_out;

always @(posedge clk) begin
    stage2_out <= stage1_out;
end

endmodule

module mux_4to1(
    input a, b, c,
    output w, x, y, z
);

    assign w = a & ~b & ~c | ~a & b & ~c | ~a & ~b & c | a & b & c;
    assign x = a & w | b & ~w & ~c | c & ~w & ~b;
    assign y = ~a & ~w | ~b & w & ~c | ~c & w & ~b;
    assign z = ~a & ~b & ~c | ~a & b & c | a & ~b & c | a & b & ~c;

endmodule

module top_module( 
    input a,b,c,
    output w,x,y,z );

    mux_4to1 mux(a, b, c, w, x, y, z);

endmodule

module shift_register (
