    input SHIFT,
    output reg [3:0] Q
);

reg [3:0] Q_reg1;
reg [3:0] Q_reg2;

always @(posedge CLK) begin
    if (LOAD) begin
        Q_reg1 <= D;
    end else if (SHIFT) begin
        Q_reg1 <= {Q_reg1[2:0], 1'b0};
    end
end

always @(posedge CLK) begin
    Q_reg2 <= Q_reg1;
end

assign Q = Q_reg2;

endmodule

