module mii_seq(
  input wire start,
  input wire mdc,
  input wire mdio,
  output reg tx_en,
  output reg rx_en,
  output reg [3:0] txd,
  output reg [3:0] rxd
);

  // State machine states
  localparam IDLE_STATE = 2'd0;
  localparam TX_STATE = 2'd1;
  localparam RX_STATE = 2'd2;

  // Internal state machine signals
  reg [1:0] state = IDLE_STATE;
  reg [4:0] count = 5'd0;

  // MII interface signals
  assign tx_en = (state == TX_STATE);
  assign rx_en = (state == RX_STATE);

  // Internal signal to hold the data to be transmitted
  reg [3:0] tx_data;

  always @(posedge mdc) begin
    case(state)
      IDLE_STATE: begin
        if(start) begin
          // Transition to the TX_STATE
          state <= TX_STATE;
          count <= 5'd0;
        end
      end

      TX_STATE: begin
        // Transmit the data
        txd <= tx_data;
        rxd <= 4'd0;
        count <= count + 5'd1;

        if(count == 5'd1) begin
          // Deassert the TX_EN signal and transition to the RX_STATE
          tx_en <= 1'b0;
          state <= RX_STATE;
          count <= 5'd0;
        end
      end

      RX_STATE: begin
        // Receive the data
        txd <= 4'd0;
        rxd <= mdio;
        count <= count + 5'd1;

        if(count == 5'd1) begin
          // Deassert the RX_EN signal and transition back to the TX_STATE
          rx_en <= 1'b0;
          state <= TX_STATE;
          count <= 5'd0;
        end
      end
    endcase
  end

  always @(posedge mdc) begin
    if(state == TX_STATE && count == 5'd0) begin
      // Load the data to be transmitted
      tx_data <= {4{count[3]}};
    end
  end

endmodule

module top_module ( 
    input clk,
    input areset,  // async active-high reset to zero
    input load,
    input ena,
    input select, // select input to choose between shift register and barrel shifter
    input [3:0] data, // 4-bit input for the shift register
    input [7:0] barrel_in, // 8-bit input for the barrel shifter
    output reg [7:0] out // 8-bit output from the functional module
);

reg [3:0] shift_reg;
reg [3:0] shifted_data;
reg [3:0] adder_out;
reg [3:0] lower_nibble;
reg [3:0] upper_nibble;

always @(posedge clk or posedge areset) begin
    if (areset) begin
        shift_reg <= 4'b0;
        shifted_data <= 4'b0;
        adder_out <= 4'b0;
        lower_nibble <= 4'b0;
        upper_nibble <= 4'b0;
        out <= 8'b0;
    end else begin
        if (load) begin
            shift_reg <= data;
        end else if (ena) begin
            shift_reg <= {1'b0, shift_reg[3:1]};
        end

        if (select) begin
            lower_nibble <= barrel_in[3:0];
            upper_nibble <= barrel_in[7:4];
            shifted_data <= shift_reg;
        end else begin
            lower_nibble <= shifted_data;
            upper_nibble <= barrel_in[7:4];
            shifted_data <= {1'b0, shifted_data[3:1]};
        end

        adder_out <= shifted_data + lower_nibble;
        out <= {upper_nibble, adder_out};
    end
end

endmodule

