        .binary(count/10),
        .bcd(bcd_count[1])
    );

    binary_to_bcd bcd_converter2 (
        .binary(count/100),
        .bcd(bcd_count[2])
    );

    always @(posedge clk) begin
        if (reset) begin
            count <= 8'd0;
            bcd_count[0] <= 8'd0;
            bcd_count[1] <= 8'd0;
            bcd_count[2] <= 8'd0;
            ena <= 3'b000;
            q <= 16'd0;
