            count <= count + 1;
            if (count == 8'd100) begin
                count <= 8'd0;
            end
            ena <= {digit_select[2], digit_select[1], digit_select[0]};
            q <= {bcd_count[2], bcd_count[1], bcd_count[0], 4'b0000};
        end
    end

