module edge_detection (
    input clk,
    input rst_n,
    input signal,
    output reg rise,
    output reg fall
);

reg prev_signal;

always @(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        rise <= 0;
        fall <= 0;
        prev_signal <= 0;
    end else begin
        if(signal && !prev_signal) begin
            rise <= 1;
        end else begin
            rise <= 0;
        end

        if(!signal && prev_signal) begin
            fall <= 1;
        end else begin
            fall <= 0;
        end

        prev_signal <= signal;
    end
end

