module KEY2INST(
	input clk,
	input[15:0] button,
	input[31:0] inst_a,
	output[31:0] inst_do,
	output clrn
);

	//CMD
	parameter [2:0]
		cmd_add = 3'b000,
		cmd_sub = 3'b001,
		cmd_and = 3'b010,
		cmd_or = 3'b011,
		cmd_xor = 3'b100,
		cmd_sll = 3'b101,
		cmd_srl = 3'b110,
		cmd_sra = 3'b111;

	//Select
	parameter [1:0]
		sl_al = 2'b00,
		sl_ah = 2'b01,
		sl_bl = 2'b10,
		sl_bh = 2'b11;

	//State
	parameter [4:0]
		st_idle = 5'b00001,
		st_load = 5'b00010,
		st_run = 5'b00100,
		st_wrom = 5'b01000,
		st_reset = 5'b10000;

	//func
	parameter [5:0]
	func_add = 6'b100000,
	func_sub = 6'b100010,
	func_and = 6'b100100,
	func_or = 6'b100101,
	func_xor = 6'b100110,
	func_sll = 6'b000000,
	func_srl = 6'b000010,
	func_sra = 6'b000011;

	reg[31:0] inst_rom[31:0];
	wire rst_n;
	wire run;
	wire load;
	wire[2:0] cmd;
	wire[1:0] select;
	wire[7:0] data;
	reg[4:0] st;
	reg r_clrn;

	//ah,al,bh,bl
	reg[7:0] data_now[3:0];
	reg[25:0] cmd_do;

	assign rst_n = button[15];
	assign run = button[14];
	assign load = button[13];
	assign cmd = button[12:10];
	assign select = button[9:8];
	assign data = button[7:0];

	assign clrn = r_clrn;
	assign inst_do = inst_rom[inst_a[6:2]];

	integer i;
	initial begin
		st <= st_idle;
		for(i=0;i<4;i=i+1)
			data_now[i] <= 8'b0;
		for(i=0;i<32;i=i+1)
			inst_rom[i] <= 32'b0;
	end

	//Cmd_do
	always @(*) begin 
		case (cmd)
			cmd_add : cmd_do <= {5'b00001,5'b00010,5'b00011,5'b0,func_add};
			cmd_sub : cmd_do <= {5'b00001,5'b00010,5'b00011,5'b0,func_sub};
			cmd_and : cmd_do <= {5'b00001,5'b00010,5'b00011,5'b0,func_and};
			cmd_or : cmd_do <= {5'b00001,5'b00010,5'b00011,5'b0,func_or};
			cmd_xor : cmd_do <= {5'b00001,5'b00010,5'b00011,5'b0,func_xor};
			cmd_sll : cmd_do <= {5'b0,5'b00001,5'b00011,data_now[3][4:0],func_sll};
			cmd_srl : cmd_do <= {5'b0,5'b00001,5'b00011,data_now[3][4:0],func_srl};
			cmd_sra : cmd_do <= {5'b0,5'b00001,5'b00011,data_now[3][4:0],func_sra};
			default : cmd_do <= 26'b0;
		endcase

	end

	//State machine
	always @(posedge clk or negedge rst_n) begin
		if(~rst_n) st <= st_reset;
		else begin
			case (st)
				st_idle : begin 
					case ({run,load})
						//2'b1x : st <= st_wrom;
						2'b10 : st <= st_wrom;
						2'b11 : st <= st_wrom;
						2'b01 : st <= st_load;
						default : st <= st;
					endcase
				end
				st_wrom : st <= st_run;
				st_run : st <= run ? st : st_idle;
				st_reset : st <= st_idle;
				st_load : st <= st_idle;
				default : st <= st_reset;
			endcase
		end
	end

	//Work
	always @(posedge clk) begin
		case (st)
			st_reset : begin
				r_clrn <= 1'b0;
				for(i=0;i<4;i=i+1)
					data_now[i] <= 8'b0;
			end
			st_load : data_now[select] <= data;
			st_wrom : begin 
				//Clear all regs, set pc to 0;
				r_clrn <= 1'b0;
				//r1 = r0(0) + a;
				inst_rom[0] <= {6'b001000,5'b00000,5'b00001,data_now[0],data_now[1]};
				//r2 = r0(0) + b;
				inst_rom[1] <= {6'b001000,5'b00000,5'b00010,data_now[2],data_now[3]};
				//r3 = r1 (cmd) r2;
				inst_rom[2] <= {6'b0,cmd_do};
				//loop(j 26'd4)
				inst_rom[3] <= {6'b000010,26'd3};
			end
			st_run : r_clrn <= 1'b1;
			default : /* default */;
		endcase
	end

endmodule

module top_module (
  input clk,
  input reset,
  input [1:0] select,
  output reg [15:0] out
);

  reg [63:0] jc_counter;
  reg [1:0] jc_select;
  reg [15:0] decoder_out;

  chatgpt_generate_JC_counter jc_counter_inst (
    .clk(clk),
    .rst_n(reset),
    .Q(jc_counter)
  );

  always @ (posedge clk) begin
    if (!reset) begin
      jc_select <= 2'b00;
    end else begin
      jc_select <= jc_counter[63:62];
    end
  end

  decoder_4to16 decoder_inst (
    .a(jc_select),
    .b(select),
    .out(decoder_out)
  );

  always @ (posedge clk) begin
    if (!reset) begin
      out <= 16'b0;
    end else begin
      out <= decoder_out;
    end
  end

endmodule

module chatgpt_generate_JC_counter(
  input clk,
  input rst_n,
  output reg [63:0] Q
);

  reg [63:0] shift_reg;
  reg [63:0] next_state;

  always @ (posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      shift_reg <= 64'b0;
    end else begin
      shift_reg <= next_state;
    end
  end

  always @ (*) begin
    next_state[0] = shift_reg[63] ^ shift_reg[61];
    next_state[1:63] = shift_reg[0:62];
  end

  assign Q = shift_reg;

endmodule

module decoder_4to16(
  input [1:0] a,
  input [1:0] b,
  output reg [15:0] out
);

  always @ (*) begin
    case ({a,b})
      2'b00: out = 16'b0000000000000001;
      2'b01: out = 16'b0000000000000010;
      2'b10: out = 16'b0000000000000100;
      2'b11: out = 16'b0000000000001000;
      2'b100: out = 16'b0000000000010000;
      2'b101: out = 16'b0000000000100000;
      2'b110: out = 16'b0000000001000000;
      2'b111: out = 16'b0000000010000000;
      2'b1000: out = 16'b0000000100000000;
      2'b1001: out = 16'b0000001000000000;
      2'b1010: out = 16'b0000010000000000;
      2'b1011: out = 16'b0000100000000000;
      2'b1100: out = 16'b0001000000000000;
      2'b1101: out = 16'b0010000000000000;
      2'b1110: out = 16'b0100000000000000;
      2'b1111: out = 16'b1000000000000000;
      default: out = 16'b0;
    endcase
  end

endmodule

module booth_multiplier (
  input clk,
  input resetn,
  input signed [3:0] multiplier,
  input signed [3:0] multiplicand,
  output signed [7:0] product
);

reg signed [7:0] partial_product;
reg signed [3:0] multiplicand_shifted;
reg signed [3:0] multiplier_shifted;
reg signed [3:0] correction_factor;

always @(posedge clk or negedge resetn) begin
  if (!resetn) begin
    partial_product <= 0;
    multiplicand_shifted <= 0;
    multiplier_shifted <= 0;
    correction_factor <= 0;
  end else begin
    // Shift the multiplicand and multiplier
    multiplicand_shifted <= {multiplicand[3], multiplicand[3:1]};
    multiplier_shifted <= {multiplier[0], multiplier[3:1]};

    // Determine the correction factor based on the last two bits of the multiplier
    case (multiplier[1:0])
      2'b00: correction_factor <= 4'b0000;
      2'b01: correction_factor <= 4'b1111;
      2'b10: correction_factor <= {2'b10, multiplicand};
      2'b11: correction_factor <= {2'b10, ~multiplicand + 1};
    endcase

    // Add or subtract the correction factor from the partial product
    if (multiplier[0] == 1) begin
      partial_product <= partial_product - correction_factor;
    end else begin
      partial_product <= partial_product + correction_factor;
    end
  end
end

assign product = partial_product;

endmodule

module barrel_shift_register (
    input [3:0] data_in,
    input load,
    input clk,
    input [1:0] control,
    output [3:0] barrel_shift_result,
    output [3:0] shift_register_result,
    output [7:0] sum_result
);

    // Barrel Shifter module
    barrel_shifter barrel_shifter_inst (
        .data_in(data_in),
        .control(control),
        .barrel_shift_result(barrel_shift_result)
    );

    // Shift Register module
    shift_register shift_register_inst (
        .data_in(data_in),
        .load(load),
        .clk(clk),
        .data_out(shift_register_result)
    );

    // Adder module
    adder adder_inst (
        .a(barrel_shift_result),
        .b(shift_register_result),
        .sum(sum_result)
    );

endmodule

module barrel_shifter (
    input [3:0] data_in,
    input [1:0] control,
    output [3:0] barrel_shift_result
);

    assign barrel_shift_result = (control == 2'b00) ? data_in >> 1 :
                                 (control == 2'b01) ? data_in >> 2 :
                                 (control == 2'b10) ? data_in << 1 :
                                                     data_in << 2;

endmodule

module shift_register (
    input [3:0] data_in,
    input load,
    input clk,
    output [3:0] data_out
);

    reg [3:0] shift_register_data;

    always @(posedge clk) begin
        if (load) begin
            shift_register_data <= data_in;
        end else begin
            shift_register_data <= {shift_register_data[2:0], data_in};
        end
    end

    assign data_out = shift_register_data;

endmodule

module adder (
    input [3:0] a,
    input [3:0] b,
    output reg [7:0] sum
);

    always @(*) begin
        sum = {a, b};
    end

