module vending_machine (
  input clk,
  input reset,
  input [1:0] product_select,
  input [4:0] coin_insert,
  input dispense,
  output [1:0] product_dispense,
  output reg [4:0] change_dispense,
  output reg [6:0] display_price,
  output reg [6:0] display_money_entered
);

  // Define states
  localparam IDLE = 2'b00;
  localparam SELECT_PRODUCT = 2'b01;
  localparam INSERT_COIN = 2'b10;
  localparam DISPENSE_PRODUCT = 2'b11;

  // Define product prices
  localparam SODA_PRICE = 25;
  localparam CHIPS_PRICE = 15;
  localparam CANDY_PRICE = 10;

  // Define coin denominations
  localparam FIVE_CENTS = 5;
  localparam TEN_CENTS = 10;
  localparam TWENTY_FIVE_CENTS = 25;

  // Define state and next state variables
  reg [1:0] state, next_state;

  // Define variables for product selection and price
  reg [1:0] selected_product;
  reg [6:0] selected_product_price;

  // Define variables for coin insertion and money entered
  reg [4:0] inserted_coin;
  reg [6:0] money_entered;

  // Define variable for change
  reg [4:0] change;

  // Define state machine
  always @(posedge clk) begin
    if (reset) begin
      state <= IDLE;
      selected_product <= 2'b00;
      selected_product_price <= 0;
      inserted_coin <= 0;
      money_entered <= 0;
      change <= 0;
      display_price <= 0;
      display_money_entered <= 0;
    end
    else begin
      state <= next_state;
    end
  end

  // Define state actions and next state logic
  always @(*) begin
    case (state)
      IDLE: begin
        next_state = SELECT_PRODUCT;
        product_dispense = 2'b00;
        change_dispense = 0;
        display_price = 0;
        display_money_entered = 0;
      end
      SELECT_PRODUCT: begin
        next_state = INSERT_COIN;
        case (product_select)
          2'b00: begin
            selected_product = 2'b00;
            selected_product_price = CANDY_PRICE;
            display_price = CANDY_PRICE;
          end
          2'b01: begin
            selected_product = 2'b01;
            selected_product_price = CHIPS_PRICE;
            display_price = CHIPS_PRICE;
          end
          2'b10: begin
            selected_product = 2'b10;
            selected_product_price = SODA_PRICE;
            display_price = SODA_PRICE;
          end
        endcase
        product_dispense = 2'b00;
        change_dispense = 0;
        display_money_entered = money_entered;
      end
      INSERT_COIN: begin
        next_state = INSERT_COIN;
        case (coin_insert)
          FIVE_CENTS: begin
            inserted_coin = FIVE_CENTS;
            money_entered = money_entered + FIVE_CENTS;
          end
          TEN_CENTS: begin
            inserted_coin = TEN_CENTS;
            money_entered = money_entered + TEN_CENTS;
          end
          TWENTY_FIVE_CENTS: begin
            inserted_coin = TWENTY_FIVE_CENTS;
            money_entered = money_entered + TWENTY_FIVE_CENTS;
          end
          default: begin
            inserted_coin = 0;
          end
        endcase
        if (money_entered >= selected_product_price) begin
          next_state = DISPENSE_PRODUCT;
        end
        product_dispense = 2'b00;
        change_dispense = 0;
        display_money_entered = money_entered;
      end
      DISPENSE_PRODUCT: begin
        next_state = IDLE;
        product_dispense = selected_product;
        change = money_entered - selected_product_price;
        if (change > 0) begin
          change_dispense = change;
        end
        else begin
          change_dispense = 0;
        end
        money_entered = 0;
        display_money_entered = 0;
      end
    endcase
  end

endmodule

module alu (
    input [31:0] a,
    input [31:0] b,
    input [3:0] ctrl,
    output [31:0] result,
    output carry_out,
    output zero
);

reg [31:0] temp_result;
reg carry_out_reg;
reg zero_reg;

always @(*) begin
    case(ctrl)
        4'b0000: temp_result = a + b; // addition
        4'b0001: temp_result = a - b; // subtraction
        4'b0010: temp_result = a & b; // bitwise AND
        4'b0011: temp_result = a | b; // bitwise OR
        4'b0100: temp_result = a ^ b; // bitwise XOR
        4'b0101: temp_result = a << b[4:0]; // shift left
        4'b0110: temp_result = a >> b[4:0]; // shift right
        default: temp_result = 0; // default to 0
    endcase

    if(ctrl == 4'b0000 || ctrl == 4'b0001) begin
        carry_out_reg = (temp_result[31] == 1);
    end else begin
        carry_out_reg = 0;
    end

    if(temp_result == 0) begin
        zero_reg = 1;
    end else begin
        zero_reg = 0;
    end
end

assign result = temp_result;
assign carry_out = carry_out_reg;
assign zero = zero_reg;

endmodule

