module reset_generator
    ( input     bus_clk
    , input     pll_locked
    , input     cal_success
    , input     init_done
    , input     pcie_perstn
    , input     cpu_resetn
    , input     pcie_ready

    , output    global_reset_n
    , output    mpfe_reset_n
    , output    ctrl_reset_n
    );

    // Constants
    localparam STOP_COUNT = 26'h000000f;

    // Registers
    reg mpfe_reg[1:0];
    reg ctrl_reg[1:0];
    reg [25:0] reset_timer;
    reg pcie_perstn_sync[1:0];
    reg cpu_resetn_sync[1:0];

    // Wires
    wire timer_resetn = cpu_resetn_sync[1] & pcie_perstn_sync[1];

    // Synchronous reset for cpu_resetn
    always @(posedge bus_clk or negedge cpu_resetn) begin
        if (~cpu_resetn) begin
            cpu_resetn_sync[0] <= 0;
            cpu_resetn_sync[1] <= 0;
        end else begin
            cpu_resetn_sync[0] <= 1;
            cpu_resetn_sync[1] <= cpu_resetn_sync[0];
        end
    end

    // Synchronous reset for pcie_perstn
    always @(posedge bus_clk or negedge pcie_perstn) begin
        if (~pcie_perstn) begin
            pcie_perstn_sync[0] <= 0;
            pcie_perstn_sync[1] <= 0;
        end else begin
            pcie_perstn_sync[0] <= 1;
            pcie_perstn_sync[1] <= pcie_perstn_sync[0];
        end
    end

    // Timer for global_reset_n
    always @(posedge bus_clk or negedge timer_resetn) begin
        if (~timer_resetn) begin
            reset_timer <= 0;
        end else if (reset_timer == STOP_COUNT) begin
            reset_timer <= STOP_COUNT;
        end else begin
            reset_timer <= reset_timer + 1'b1;
        end
    end

    assign global_reset_n = reset_timer == STOP_COUNT;

    // mpfe_reset_n and ctrl_reset_n
    wire mpfe_arstn = global_reset_n & pll_locked & cal_success & pcie_ready;
    wire ctrl_arstn = global_reset_n & pll_locked & cal_success & pcie_ready & init_done;

    always @(posedge bus_clk or negedge mpfe_arstn) begin
        if (~mpfe_arstn) begin
            mpfe_reg[0] <= 0;
            mpfe_reg[1] <= 0;
        end else begin
            mpfe_reg[0] <= 1;
            mpfe_reg[1] <= mpfe_reg[0];
        end
    end

    always @(posedge bus_clk or negedge ctrl_arstn) begin
        if (~ctrl_arstn) begin
            ctrl_reg[0] <= 0;
            ctrl_reg[1] <= 0;
        end else begin
            ctrl_reg[0] <= 1;
            ctrl_reg[1] <= ctrl_reg[0];
        end
    end

    assign mpfe_reset_n = mpfe_reg[1];
    assign ctrl_reset_n = ctrl_reg[1];

endmodule

module MAX31855(/*AUTOINST*/
    // Inputs
    input clk,
    input reset,
    input miso,
    input mosi,
    input sck,
    // Outputs
    output signed [13:0] temperature,
    output valid
);

    // Internal signals
    reg [31:0] command;
    reg [31:0] response;
    integer bitcount;
    integer state;
    reg [3:0] shiftreg;
    reg [3:0] shiftout;

    // Constants
    localparam CMD_TEMP = 2'b00;
    localparam CMD_FAULT = 2'b10;

    // Initialize internal signals
    initial begin
        command = 32'h00000000;
        response = 32'h00000000;
        bitcount = 0;
        state = 0;
        shiftreg = 4'h0;
        shiftout = 4'h0;
    end

    // SPI controller
    always @(posedge clk) begin
        if (reset) begin
            command <= 32'h00000000;
            response <= 32'h00000000;
            bitcount <= 0;
            state <= 0;
            shiftreg <= 4'h0;
            shiftout <= 4'h0;
        end else begin
            case (state)
                // Send command word
                0: begin
                    if (bitcount == 0) begin
                        // Start bit
                        mosi <= 1'b0;
                    end else if (bitcount < 3) begin
                        // Type bits
                        mosi <= command[31-bitcount];
                    end else begin
                        // Don't care bits
                        mosi <= 1'bZ;
                    end
                    if (bitcount == 31) begin
                        // End of command word
                        state <= 1;
                        bitcount <= 0;
                    end else begin
                        bitcount <= bitcount + 1;
                    end
                end
                // Receive response word
                1: begin
                    if (bitcount < 2) begin
                        // Don't care bits
                        mosi <= 1'bZ;
                    end else begin
                        // Read response bits
                        miso <= response[31-bitcount];
                        mosi <= 1'b0;
                        if (bitcount == 31) begin
                            // End of response word
                            state <= 0;
                            bitcount <= 0;
                            shiftreg <= response[12:9];
                            shiftout <= response[12:9];
                            temperature <= $signed({response[31], response[30:18]});
                            valid <= response[1:0] == 2'b11;
                        end else begin
                            bitcount <= bitcount + 1;
                        end
                    end
                end
            endcase
        end
    end

    // Shift register for 14-bit temperature conversion
    always @(posedge clk) begin
        if (shiftout[3] == 1'b1) begin
            shiftreg <= {shiftreg[2:0], miso};
            shiftout <= {shiftout[2:0], 4'h0};
        end else begin
            shiftout <= {shiftout[2:0], 1'b1};
        end
    end

    // Temperature conversion
    always @(posedge clk) begin
        if (shiftout[3] == 1'b1) begin
            temperature <= $signed({shiftreg[3], shiftreg[2:0]});
            valid <= 1'b1;
        end
    end

endmodule

module recibo ( input clk,
                input rw,
                input reset,
                input Rx,
                output reg busy, 
                output reg clk_blu, 
                output reg [7:0] dout 
                );

    reg [1:0] estado, estado_sig;
    parameter inactivo = 2'b00;
    parameter inicio = 2'b01;

    reg control;
    reg done = 0;
    reg [8:0] tmp = 9'b000000000;
    reg [3:0] contador = 4'b0000;

    // Divisor_frecuencia module generates a clock signal with a frequency that is half of the input clock frequency
    wire clk_f;
    Divisor_frecuencia div(.clk(clk), .clk_f(clk_f), .reset(reset));

    // State machine
    always @(posedge clk_f, posedge reset) begin
        if (reset) begin
            estado <= inactivo;
        end else begin
            estado <= estado_sig;
        end
    end

    always @(*) begin
        case (estado)
            inactivo: begin
                if (Rx == 1 && done == 0) begin
                    control = 0;
                    estado_sig = inactivo;
                end else if (Rx == 0 && done == 0 && rw == 1) begin
                    control = 1;
                    estado_sig = inicio;
                end else begin
                    control = 0;
                    estado_sig = inactivo;
                end
            end

            inicio: begin
                if (done == 0) begin
                    control = 1;
                    estado_sig = inicio;
                end else begin
                    control = 0;
                    estado_sig = inactivo;
                end
            end

            default: begin
                estado_sig = inactivo;
            end
        endcase
    end

    // Shift register to capture data
    always @(posedge clk_f) begin
        if (control == 1 && done == 0) begin
            tmp <= {Rx, tmp[8:1]};
        end
    end

    // Generate receipt
    always @(posedge clk_f) begin
        if (control) begin
            if (contador >= 10) begin
                contador <= 0;
                done <= 1;
                dout <= tmp[8:1];
            end else begin
                contador <= contador + 1;
                done <= 0;
            end
        end else begin
            done <= 0;
        end
    end

    // Output signals
    assign busy = done;
    always @(posedge clk_f) begin
        clk_blu <= ~clk_blu;
    end

endmodule

