module vending_machine (
  input clk,
  input reset,
  input [7:0] money_inserted,
  input [1:0] button_pressed,
  output reg [1:0] item_dispensed,
  output reg [7:0] change_returned,
  output reg item_dispensing
);

  // Define the states of the state machine
  parameter IDLE = 2'b00;
  parameter ITEM_SELECTED = 2'b01;
  parameter DISPENSING = 2'b10;

  // Define the prices of the items
  parameter ITEM_A_PRICE = 50;
  parameter ITEM_B_PRICE = 75;
  parameter ITEM_C_PRICE = 100;

  // Define the variables for the state machine
  reg [1:0] state;
  reg [7:0] current_money;
  reg [7:0] item_price;

  // Define the outputs for the state machine
  reg [1:0] next_item_dispensed;
  reg [7:0] next_change_returned;
  reg next_item_dispensing;

  // Define the logic for the state machine
  always @(posedge clk) begin
    if (reset) begin
      state <= IDLE;
      current_money <= 0;
      item_price <= 0;
      next_item_dispensed <= 0;
      next_change_returned <= 0;
      next_item_dispensing <= 0;
    end else begin
      case (state)
        IDLE: begin
          // Wait for a button to be pressed
          if (button_pressed != 0) begin
            // Determine the price of the selected item
            case (button_pressed)
              2'b01: item_price <= ITEM_A_PRICE;
              2'b10: item_price <= ITEM_B_PRICE;
              2'b11: item_price <= ITEM_C_PRICE;
            endcase

            // Check if enough money has been inserted
            if (money_inserted >= item_price) begin
              current_money <= money_inserted - item_price;
              next_item_dispensed <= button_pressed;
              next_change_returned <= current_money;
              next_item_dispensing <= 1;
              state <= DISPENSING;
            end else begin
              next_item_dispensed <= 0;
              next_change_returned <= money_inserted;
              next_item_dispensing <= 0;
            end
          end else begin
            next_item_dispensed <= 0;
            next_change_returned <= 0;
            next_item_dispensing <= 0;
          end
        end

        ITEM_SELECTED: begin
          // Wait for the item to finish dispensing
          if (!item_dispensing) begin
            next_item_dispensed <= 0;
            next_change_returned <= current_money;
            next_item_dispensing <= 0;
            state <= IDLE;
          end else begin
            next_item_dispensed <= item_dispensed;
            next_change_returned <= 0;
            next_item_dispensing <= 1;
          end
        end

        DISPENSING: begin
          // Wait for the item to finish dispensing
          if (!item_dispensing) begin
            next_item_dispensed <= item_dispensed;
            next_change_returned <= 0;
            next_item_dispensing <= 1;
            state <= ITEM_SELECTED;
          end else begin
            next_item_dispensed <= 0;
            next_change_returned <= 0;
            next_item_dispensing <= 1;
          end
        end
      endcase
    end
  end

  // Assign the outputs
  assign item_dispensed = next_item_dispensed;
  assign change_returned = next_change_returned;
  assign item_dispensing = next_item_dispensing;

endmodule

