        for(i = 0; i < 4; i = i + 1)
        begin
            if(multiplier_reg[0] == 1)
            begin
                result_reg = result_reg + (multiplicand_reg << i);
            end

            multiplier_reg = multiplier_reg >> 1;
        end

        Y = result_reg;
    end
endmodule
module bitwise_or (
    input [3:0] A,
    input [7:0] B,
    input SEL,
    output reg [7:0] Y
);
    reg [3:0] alu_output;
    reg [7:0] multiplication_output;

    alu alu_inst(
        .A(A),
        .B(B[3:0]),
        .OP(B[7:5]),
        .Y(alu_output)
    );

    multiplication multiplication_inst(
        .MULTIPLICAND(B[3:0]),
        .MULTIPLIER(B[7:4]),
        .Y(multiplication_output)
    );

    always @(*)
    begin
        if(SEL == 1'b0)
        begin
            Y = alu_output;
        end
        else
        begin
            Y = multiplication_output;
        end

        Y = Y | alu_output;
    end
endmodule
module top_module (
    input [3:0] A,
