module top_module (
    input clk,
    input rst_n,
    input a,
    input [4:0] in,
    output out_and,
    output out_or,
    output out_nor,
    output final_output
);

    // Edge detection module
    reg a_prev;
    reg edge_detected;
    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            a_prev <= 1'b0;
            edge_detected <= 1'b0;
        end else begin
            a_prev <= a;
            edge_detected <= (a && ~a_prev) || (~a && a_prev);
        end
    end

    // Combinational circuit module
    assign out_and = &in;
    assign out_or = |in;
    assign out_nor = ~|in;

    // Additional functional module
    reg [1:0] decoder_out;
    decoder_2to4_with_enable decoder_inst (
        .in(a_prev),
        .en(1'b1),
        .out(decoder_out)
    );
    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            final_output <= 1'b0;
        end else begin
            if (edge_detected && (decoder_out == 2 || decoder_out == 3)) begin
                final_output <= 1'b1;
            end else begin
                final_output <= 1'b0;
            end
        end
    end

endmodule

module axis_arb_mux_4 #(
    parameter DATA_WIDTH = 8
)
(
    input clk,
    input rst,

    // AXI inputs
    input [DATA_WIDTH-1:0] input_0_axis_tdata,
    input input_0_axis_tvalid,
    output input_0_axis_tready,
    input input_0_axis_tlast,
    input input_0_axis_tuser,
    input [DATA_WIDTH-1:0] input_1_axis_tdata,
    input input_1_axis_tvalid,
    output input_1_axis_tready,
    input input_1_axis_tlast,
    input input_1_axis_tuser,
    input [DATA_WIDTH-1:0] input_2_axis_tdata,
    input input_2_axis_tvalid,
    output input_2_axis_tready,
    input input_2_axis_tlast,
    input input_2_axis_tuser,
    input [DATA_WIDTH-1:0] input_3_axis_tdata,
    input input_3_axis_tvalid,
    output input_3_axis_tready,
    input input_3_axis_tlast,
    input input_3_axis_tuser,

    // AXI output
    output [DATA_WIDTH-1:0] output_axis_tdata,
    output output_axis_tvalid,
    input output_axis_tready,
    output output_axis_tlast,
    output output_axis_tuser
);

// Round-robin counter
reg [1:0] round_robin_counter = 2'b00;

// Input ready signals
reg [3:0] input_ready = 4'b0000;

// Output valid and last signals
reg output_valid = 0;
reg output_last = 0;

// Output data and user signals
reg [DATA_WIDTH-1:0] output_data = 0;
reg output_user = 0;

// Input selection logic
always @(*) begin
    case (round_robin_counter)
        2'b00: begin
            input_0_axis_tready = (input_ready[0] && output_axis_tready);
            input_1_axis_tready = (input_ready[1] && !input_ready[0] && output_axis_tready);
            input_2_axis_tready = (input_ready[2] && !input_ready[1] && !input_ready[0] && output_axis_tready);
            input_3_axis_tready = (input_ready[3] && !input_ready[2] && !input_ready[1] && !input_ready[0] && output_axis_tready);
        end
        2'b01: begin
            input_0_axis_tready = (input_ready[3] && !input_ready[2] && !input_ready[1] && !input_ready[0] && output_axis_tready);
            input_1_axis_tready = (input_ready[0] && output_axis_tready);
            input_2_axis_tready = (input_ready[1] && !input_ready[0] && output_axis_tready);
            input_3_axis_tready = (input_ready[2] && !input_ready[1] && !input_ready[0] && output_axis_tready);
        end
        2'b10: begin
            input_0_axis_tready = (input_ready[2] && !input_ready[1] && !input_ready[0] && output_axis_tready);
            input_1_axis_tready = (input_ready[3] && !input_ready[2] && !input_ready[1] && !input_ready[0] && output_axis_tready);
            input_2_axis_tready = (input_ready[0] && output_axis_tready);
            input_3_axis_tready = (input_ready[1] && !input_ready[0] && output_axis_tready);
        end
        2'b11: begin
            input_0_axis_tready = (input_ready[1] && !input_ready[0] && output_axis_tready);
            input_1_axis_tready = (input_ready[2] && !input_ready[1] && !input_ready[0] && output_axis_tready);
            input_2_axis_tready = (input_ready[3] && !input_ready[2] && !input_ready[1] && !input_ready[0] && output_axis_tready);
            input_3_axis_tready = (input_ready[0] && output_axis_tready);
        end
    endcase
end

// Input ready logic
always @(posedge clk) begin
    if (rst) begin
        input_ready <= 4'b0000;
    end else begin
        input_ready <= {input_ready[2:0], input_ready[3]};
        input_ready[0] <= (input_0_axis_tvalid && input_0_axis_tready);
        input_ready[1] <= (input_1_axis_tvalid && input_1_axis_tready);
        input_ready[2] <= (input_2_axis_tvalid && input_2_axis_tready);
        input_ready[3] <= (input_3_axis_tvalid && input_3_axis_tready);
    end
end

// Output data and user logic
always @(*) begin
    case (round_robin_counter)
        2'b00: begin
            output_data = input_0_axis_tdata;
            output_user = input_0_axis_tuser;
        end
        2'b01: begin
            output_data = input_1_axis_tdata;
            output_user = input_1_axis_tuser;
        end
        2'b10: begin
            output_data = input_2_axis_tdata;
            output_user = input_2_axis_tuser;
        end
        2'b11: begin
            output_data = input_3_axis_tdata;
            output_user = input_3_axis_tuser;
        end
    endcase
end

// Output valid and last logic
always @(posedge clk) begin
    if (rst) begin
        output_valid <= 0;
        output_last <= 0;
    end else begin
        if (output_axis_tready) begin
            output_valid <= (input_0_axis_tvalid || input_1_axis_tvalid || input_2_axis_tvalid || input_3_axis_tvalid);
            output_last <= (round_robin_counter == 2'b11) ? input_3_axis_tlast :
                           (round_robin_counter == 2'b10) ? input_2_axis_tlast :
                           (round_robin_counter == 2'b01) ? input_1_axis_tlast :
                                                            input_0_axis_tlast;
        end
    end
end

// Round-robin counter logic
always @(posedge clk) begin
    if (rst) begin
        round_robin_counter <= 2'b00;
    end else begin
        if (output_axis_tready) begin
            round_robin_counter <= (round_robin_counter == 2'b11) ? 2'b00 :
                                   (round_robin_counter == 2'b10) ? 2'b11 :
                                   (round_robin_counter == 2'b01) ? 2'b10 :
                                                                    2'b01;
        end
    end
end

// Output signals
assign output_axis_tdata = output_data;
assign output_axis_tvalid = output_valid;
assign output_axis_tlast = output_last;
assign output_axis_tuser = output_user;

endmodule

