module fletcher_checksum_generator (
  input clk,
  input rst,
  input [7:0] data_in,
  input [7:0] len,
  output [15:0] checksum
);

  reg [15:0] sum1;
  reg [15:0] sum2;
  reg [15:0] temp;
  reg [7:0] data;
  reg [7:0] count;
  reg [7:0] i;

  always @(posedge clk) begin
    if (rst) begin
      sum1 <= 16'h0000;
      sum2 <= 16'h0000;
      count <= 8'h00;
    end else begin
      if (count == len) begin
        checksum <= ~((sum2 << 8) + sum1);
      end else begin
        data <= data_in;
        if (count[0] == 0) begin
          sum1 <= sum1 + data;
          if (sum1 > 16'hFFFF) begin
            sum1 <= sum1 - 16'hFFFF;
            sum2 <= sum2 + 16'h0001;
          end
        end else begin
          temp <= sum1 + data;
          if (temp > 16'hFFFF) begin
            temp <= temp - 16'hFFFF;
            sum2 <= sum2 + 16'h0001;
          end
          sum1 <= temp;
        end
        count <= count + 8'h01;
      end
    end
  end

endmodule

module fletcher_checksum_checker (
  input clk,
  input rst,
  input [7:0] data_in,
  input [7:0] len,
  input [15:0] checksum,
  output valid
);

  reg [15:0] sum1;
  reg [15:0] sum2;
  reg [15:0] temp;
  reg [7:0] data;
  reg [7:0] count;
  reg [7:0] i;

  always @(posedge clk) begin
    if (rst) begin
      sum1 <= 16'h0000;
      sum2 <= 16'h0000;
      count <= 8'h00;
      valid <= 1'b0;
    end else begin
      if (count == len) begin
        if (checksum == ~((sum2 << 8) + sum1)) begin
          valid <= 1'b1;
        end else begin
          valid <= 1'b0;
        end
      end else begin
        data <= data_in;
        if (count[0] == 0) begin
          sum1 <= sum1 + data;
          if (sum1 > 16'hFFFF) begin
            sum1 <= sum1 - 16'hFFFF;
            sum2 <= sum2 + 16'h0001;
          end
        end else begin
          temp <= sum1 + data;
          if (temp > 16'hFFFF) begin
            temp <= temp - 16'hFFFF;
            sum2 <= sum2 + 16'h0001;
          end
          sum1 <= temp;
        end
        count <= count + 8'h01;
      end
    end
  end

endmodule

