endmodule

Instruction:
Please act as a professional Verilog designer. Implement a Mealy state machine with three inputs, one output, and five states. The state transition table is as follows:
// state | next state in0, in1, in2 | output
// A | B, A, D | 0
// B | C, A, E | 0
// C | A, D, E | 1
// D | E, E, A | 1
// E | E, E, E | 0

Please include a positive edge triggered asynchronous reset that resets the FSM to state A.

Response:
module mealy_fsm (
  input clk,
  input reset,
  input in0,
  input in1,
  input in2,
  output reg out
);

  parameter A = 3'b000, B = 3'b001, C = 3'b010, D = 3'b011, E = 3'b100;
  reg [2:0] state, next_state;

  always @(posedge clk or negedge reset) begin
    if (reset == 0) begin
      state <= A;
      out <= 0;
    end
    else begin
      state <= next_state;
      case(state)
        A: begin
          if (in0 == 1) next_state = B;
          else if (in1 == 1) next_state = A;
          else if (in2 == 1) next_state = D;
          out <= 0;
        end
        B: begin
          if (in0 == 1) next_state = C;
          else if (in1 == 1) next_state = A;
          else if (in2 == 1) next_state = E;
          out <= 0;
        end
        C: begin
          if (in0 == 1) next_state = A;
          else if (in1 == 1) next_state = D;
          else if (in2 == 1) next_state = E;
          out <= 1;
        end
        D: begin
          if (in0 == 1) next_state = E;
          else if (in1 == 1) next_state = E;
          else if (in2 == 1) next_state = A;
          out <= 1;
        end
        E: begin
          next_state = E;
          out <= 0;
        end
      endcase
    end
  end

endmodule

module ALU #(
    parameter WIDTH = 32
    ) (
    input wire [3:0] op,
    input wire [WIDTH - 1:0] inA,
    input wire [WIDTH - 1:0] inB,
    output reg [WIDTH - 1:0] out,
    output wire zero
    );

    // Arithmetic and Logic Unit
    //
    // opcodes
    // -------
    //  0 : 4'b0000 : bitwise AND      : out = inA & inB
    //  1 : 4'b0001 : bitwise OR       : out = inA | inB
    //  2 : 4'b0010 : addition         : out = inA + inB
    //  6 : 4'b0110 : subtraction      : out = inA - inB
    //  7 : 4'b0111 : set on less than : out = (inA < inB) ? 1 : 0
    // 12 : 4'b1100 : bitwise NOR      : out = ~(inA | inB)

    always @(op, inA, inB) begin
        case(op)
             0 : out = inA & inB;
             1 : out = inA | inB;
             2 : out = inA + inB;
             6 : out = inA - inB;
             7 : out = (inA < inB) ? 1 : 0;
            12 : out = ~(inA | inB);
            default: out = 32'bx;
        endcase
    end  // always

    assign zero = (out == 0);

endmodule

