module one_hot_state_machine (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 4; // number of input signals
parameter m = 2; // number of output signals
parameter s = 8; // number of states in the state machine

reg [s-1:0] state; // register to hold the current state

// Define the flip-flops for each state
reg [s-1:0] state_ff;
always @ (posedge clk) begin
  state_ff <= state;
end

// Determine which flip-flop should be set to high based on current state and input signals
always @ (in or state_ff) begin
  case (state_ff)
    0: state = in[0] ? 1 : 0;
    1: state = in[1] ? 2 : 0;
    2: state = in[2] ? 3 : 0;
    3: state = in[3] ? 4 : 0;
    4: state = in[0] ? 5 : 0;
    5: state = in[1] ? 6 : 0;
    6: state = in[2] ? 7 : 0;
    7: state = in[3] ? 8 : 0;
    default: state = 0;
  endcase
end

// Compute the output signals based on the current state
always @ (state) begin
  case (state)
    0: out = {1'b1, 1'b0};
    1: out = {1'b0, 1'b1};
    2: out = {1'b1, 1'b1};
    3: out = {1'b0, 1'b0};
    4: out = {1'b0, 1'b1};
    5: out = {1'b1, 1'b1};
    6: out = {1'b0, 1'b0};
    7: out = {1'b1, 1'b0};
    8: out = {1'b0, 1'b0};
    default: out = {1'b0, 1'b0};
  endcase
end

endmodule

module simple_spi(
    input clk,
    input reset,
    input [7:0] port_id,
    input [7:0] data_in,
    input read_strobe,
    input write_strobe,
    output reg [15:0] temperature,
    output reg [7:0] data_out,
    output reg wfwe,
    output reg rfre,
    output reg wr_spsr,
    output reg clear_spif,
    output reg clear_wcol,
    output reg [7:0] wfdin,
    output reg ncs_o,
    output reg [7:0] spcr,
    output reg [7:0] sper
);

reg [7:0] spi_control_reg;
reg [7:0] spi_enable_reg;
reg [7:0] spi_status_reg;

reg [7:0] spi_tx_data;
reg [7:0] spi_rx_data;
reg spi_tx_done;
reg spi_rx_done;

reg [3:0] tx_state;
reg [3:0] rx_state;

reg [15:0] temp_counter;
reg [7:0] temp_value;

always @(posedge clk) begin
    if (reset) begin
        temperature <= 0;
        data_out <= 0;
        wfwe <= 0;
        rfre <= 0;
        wr_spsr <= 0;
        clear_spif <= 0;
        clear_wcol <= 0;
        wfdin <= 0;
        ncs_o <= 1;
        spcr <= 0;
        sper <= 0;
        spi_control_reg <= 0;
        spi_enable_reg <= 0;
        spi_status_reg <= 0;
        spi_tx_data <= 0;
        spi_rx_data <= 0;
        spi_tx_done <= 0;
        spi_rx_done <= 0;
        tx_state <= 0;
        rx_state <= 0;
        temp_counter <= 0;
        temp_value <= 0;
    end else begin
        // update temperature every clock cycle
        if (temp_counter == 1000) begin
            temp_counter <= 0;
            temp_value <= temp_value + 1;
            temperature <= {temp_value, 8'b0};
        end else begin
            temp_counter <= temp_counter + 1;
        end

        // update spi control and enable registers based on port_id and temperature
        case (port_id)
            8'h00: begin
                spi_control_reg <= 8'h00;
                spi_enable_reg <= 8'h00;
            end
            8'h01: begin
                spi_control_reg <= 8'h01;
                spi_enable_reg <= 8'h01;
            end
            8'h02: begin
                spi_control_reg <= 8'h02;
                spi_enable_reg <= 8'h02;
            end
            8'h03: begin
                spi_control_reg <= 8'h03;
                spi_enable_reg <= 8'h03;
            end
            8'h04: begin
                spi_control_reg <= 8'h04;
                spi_enable_reg <= 8'h04;
            end
            8'h05: begin
                spi_control_reg <= 8'h05;
                spi_enable_reg <= 8'h05;
            end
            8'h06: begin
                spi_control_reg <= 8'h06;
                spi_enable_reg <= 8'h06;
            end
            8'h07: begin
                spi_control_reg <= 8'h07;
                spi_enable_reg <= 8'h07;
            end
            default: begin
                spi_control_reg <= 8'h00;
                spi_enable_reg <= 8'h00;
            end
        endcase

        // update spcr and sper based on spi_control_reg and spi_enable_reg
        spcr <= spi_control_reg;
        sper <= spi_enable_reg;

        // handle write operation
        if (write_strobe && !spi_tx_done) begin
            case (tx_state)
                0: begin
                    ncs_o <= 0;
                    spi_tx_data <= spi_control_reg;
                    tx_state <= 1;
                end
                1: begin
                    spi_tx_data <= spi_enable_reg;
                    tx_state <= 2;
                end
                2: begin
                    spi_tx_data <= data_in;
                    tx_state <= 3;
                end
                3: begin
                    spi_tx_data <= 0;
                    spi_tx_done <= 1;
                    wfwe <= 0;
                    ncs_o <= 1;
                    tx_state <= 0;
                end
            endcase
        end

        // handle read operation
        if (read_strobe && !spi_rx_done) begin
            case (rx_state)
                0: begin
                    ncs_o <= 0;
                    spi_tx_data <= spi_control_reg;
                    rx_state <= 1;
                end
                1: begin
                    spi_tx_data <= spi_enable_reg;
                    rx_state <= 2;
                end
                2: begin
                    spi_tx_data <= 0;
                    rx_state <= 3;
                end
                3: begin
                    spi_rx_data <= spi_rx_data;
                    spi_rx_done <= 1;
                    rfre <= 0;
                    ncs_o <= 1;
                    rx_state <= 0;
                end
            endcase
        end

        // handle spi communication
        if (!spi_tx_done || !spi_rx_done) begin
            if (!spi_tx_done) begin
                spi_status_reg[0] <= 1;
                wfdin <= spi_tx_data;
            end else begin
                spi_status_reg[0] <= 0;
                wfdin <= 0;
            end

            if (!spi_rx_done) begin
                spi_status_reg[7] <= 1;
                data_out <= spi_rx_data;
            end else begin
                spi_status_reg[7] <= 0;
            end
        end else begin
            spi_status_reg[0] <= 0;
            spi_status_reg[7] <= 0;
        end

        // handle spi status register write
        if (wr_spsr) begin
            spi_status_reg <= 0;
            clear_spif <= 1;
            clear_wcol <= 1;
        end
    end
end

endmodule

