module edge_detector (
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] data_in,
    output reg edge_detected
);

reg [7:0] prev_data;

always @ (posedge clk) begin
    if (reset) begin
        prev_data <= 8'b0;
        edge_detected <= 1'b0;
    end else begin
        if (data_in != prev_data) begin
            edge_detected <= 1'b1;
        end else begin
            edge_detected <= 1'b0;
        end
        prev_data <= data_in;
    end
end

endmodule

module counter_fsm (
    input clk,
    input reset,      // Synchronous active-high reset
    input edge_detected,
    output reg [7:0] count_out
);

parameter IDLE = 2'b00;
parameter COUNTING = 2'b01;
parameter DONE = 2'b10;

reg [1:0] state;

always @ (posedge clk) begin
    if (reset) begin
        state <= IDLE;
        count_out <= 8'b0;
    end else begin
        case (state)
            IDLE: begin
                if (edge_detected) begin
                    state <= COUNTING;
                    count_out <= 8'b1;
                end else begin
                    state <= IDLE;
                    count_out <= 8'b0;
                end
            end
            COUNTING: begin
                if (edge_detected) begin
                    state <= COUNTING;
                    count_out <= count_out + 8'b1;
                end else begin
                    state <= DONE;
                    count_out <= count_out;
                end
            end
            DONE: begin
                state <= IDLE;
                count_out <= count_out;
            end
            default: begin
                state <= IDLE;
                count_out <= 8'b0;
            end
        endcase
    end
end

endmodule

