module crc_16(start, clk, rst, data_in, data_out, done);

	//inputs y outputs

	input start;
	input clk;
	input rst;
	input [31:0] data_in;
	output [15:0] data_out;
	output done;

	//parametros 

	localparam datawidth = 32, crcorder = 16;//tamaño del dato a operar, orden del polinomio crc

	localparam polinomio = 17'b10001000000100001 ; //polinomio para crc

	reg rdone; 				//registro done
	reg [31:0] r_data;		//registro data
	reg [16:0] proceso;		//proceso o resultado temporal de xor
	initial rdone = 1'b0;			//inicializa done en 0

	//estados

	localparam INIT = 3'd0, GET = 3'd1, COMP = 3'd2, XOR = 3'd3, CORRER = 3'd4, SEND = 3'd5; 
	reg[2:0] state;
	initial state = INIT; // se inicializa en el estado init

	reg[6:0] cont; // contador de corrimientos

	assign data_out = proceso; //se asigna la salida de crc
	assign done = rdone; // se asigna done a la salida



	always @(posedge clk or negedge clk) begin

		//reset		

		if(rst)begin
			rdone <= 0;
			cont <= 0;
			proceso <= 0;
			state = INIT;
		end

		else begin 

		//Maquina de Estados

			case(state)

				INIT : begin   				//estado init
					cont <= 6'd0;			//contador en 0
					rdone <= 1'b0; 			//done en 0
					if (start) begin
						r_data <= data_in;	//se coloca en rdata el dato a operar
						state = GET;		//cambio de estado
					end	
				end

				GET : begin								//estado get
					proceso <= r_data[(31):(31)-(crcorder)];	//a proceso entran los 
													//primeros crcorder bits 
					state = COMP;							//cambio de estado
				end

				COMP : begin				//estado comp 

					cont <= cont + 1'b1;		//aumenta el contador 
					if(proceso[crcorder])		//verifia si el primer bit de proceso es 1
						state = XOR;		//si es 1 cambia a estado XOR
					else
						state = CORRER;		//si es 0 cambia a estado correr
				end

				XOR : begin					//estado xor
					proceso <= proceso ^ polinomio;	//xor entre proceso y polinomio de crc
					state = CORRER;				//cambio de estado 	
				end

				CORRER : begin				//estado correr
					r_data <= {proceso[crcorder:0], r_data[(31)-crcorder-1:0], 1'b0}; 
									//se coloca proceso concatenado con el resto de rdata "anterior"
					if (cont == datawidth)
						state = SEND;		//si ya se hicieron datawidh corrimientos cambia a send
					else
						state = GET;		//si no, vuelve a get 
				end

				SEND : begin				//estado send
					rdone <= 1'b1;			//done activo
					state = INIT;			//vuelve a estado inicial
				end

			endcase
		end

	end

endmodule

module INBUF #(
  parameter IBUF_LOW_PWR = 1'b1, // Default is low power mode
  parameter integer SIM_INPUT_BUFFER_OFFSET = 0
)(
  output O,

  input [3:0] OSC,
  input OSC_EN,
  input PAD,
  input VREF
);

  // Constants
  localparam MODULE_NAME = "INBUF";
  localparam IBUF_LOW_PWR_FALSE = 1'b0;
  localparam IBUF_LOW_PWR_TRUE = 1'b1;

  // Registers
  reg [1:0] state = 2'b00; // State machine state
  reg O_OSC_in; // Output when OSC_EN is high
  reg IBUF_LOW_PWR_REG = IBUF_LOW_PWR; // Register for IBUF_LOW_PWR
  integer OSC_int = 0; // Integer representation of OSC

  // Wires
  wire IBUF_LOW_PWR_BIN = (IBUF_LOW_PWR_REG == IBUF_LOW_PWR_TRUE) ? IBUF_LOW_PWR_TRUE : IBUF_LOW_PWR_FALSE;

  // Assignments
  assign O = (OSC_EN == 1'b1) ? O_OSC_in : PAD;

  // State machine
  always @ (posedge OSC_EN) begin
    if (IBUF_LOW_PWR_BIN == IBUF_LOW_PWR_TRUE) begin
      state <= 2'b00; // Low power mode
    end else begin
      case (state)
        2'b00: begin // Initial state
          state <= 2'b01;
        end
        2'b01: begin // Check difference between OSC and SIM_INPUT_BUFFER_OFFSET
          OSC_int = OSC[3] ? -((~OSC[2:0])+1) : OSC[2:0];
          if (OSC_int - SIM_INPUT_BUFFER_OFFSET < 0) begin
            O_OSC_in <= 1'b0;
            state <= 2'b10;
          end else if (OSC_int - SIM_INPUT_BUFFER_OFFSET > 0) begin
            O_OSC_in <= 1'b1;
            state <= 2'b10;
          end else begin
            state <= 2'b11;
          end
        end
        2'b10: begin // Output set, wait for OSC_EN to go low
          if (OSC_EN == 1'b0) begin
            state <= 2'b00;
          end
        end
        2'b11: begin // Output toggles, wait for OSC_EN to go low
          O_OSC_in <= ~O_OSC_in;
          if (OSC_EN == 1'b0) begin
            state <= 2'b00;
          end
        end
      endcase
    end
  end

endmodule

