module top_module( 
    input [3:0] in,
    output out_and,
    output out_or,
    output out_xor
);

    wire and1, and2, and3;
    wire or1, or2, or3;
    wire xor1, xor2;

    and #(4) and_gate1 (and1, in);
    and #(4) and_gate2 (and2, in);
    and #(4) and_gate3 (and3, in);

    or #(4) or_gate1 (or1, in);
    or #(4) or_gate2 (or2, in);
    or #(4) or_gate3 (or3, in);

    xor #(4) xor_gate1 (xor1, in);
    xor #(4) xor_gate2 (xor2, in);

    assign out_and = and1 & and2 & and3;
    assign out_or = or1 | or2 | or3;
    assign out_xor = xor1 ^ xor2;

