module DataMemory 
#(parameter DATA_WIDTH = 32, parameter ADDR_WIDTH = 32)
(
    input [(DATA_WIDTH-1):0] data,
    input [(ADDR_WIDTH-1):0] addr,
    input [3:0] we, 
    input clk,
    output [(DATA_WIDTH-1):0] q
);
    // Declare the RAM variable
    reg [DATA_WIDTH-1:0] ram[2**(ADDR_WIDTH - 22) - 1:0];

    always @ (posedge clk)
    begin
        if (we[0])
            ram[addr[ADDR_WIDTH-1:2]][7:0] <= data[7:0];
        if (we[1])
            ram[addr[ADDR_WIDTH-1:2]][15:8] <= data[15:8];
        if (we[2])
            ram[addr[ADDR_WIDTH-1:2]][15:0] <= data[15:0];
        if (we[3])
            ram[addr[ADDR_WIDTH-1:2]][23:16] <= data[23:16];
        if (we[0] && we[3])
            ram[addr[ADDR_WIDTH-1:2]][7:0] <= data[7:0];
        if (we[3] && we[1])
            ram[addr[ADDR_WIDTH-1:2]][15:8] <= data[15:8];
        if (we[3] && we[2])
            ram[addr[ADDR_WIDTH-1:2]][15:0] <= data[15:0];
        if (we[3] && we[0])
            ram[addr[ADDR_WIDTH-1:2]][23:16] <= data[23:16];
        if (we[0] && we[1] && we[3])
        begin
            ram[addr[ADDR_WIDTH-1:2]][7:0] <= data[7:0];
            ram[addr[ADDR_WIDTH-1:2]][15:8] <= data[15:8];
        end
        if (we[0] && we[2] && we[3])
        begin
            ram[addr[ADDR_WIDTH-1:2]][7:0] <= data[7:0];
            ram[addr[ADDR_WIDTH-1:2]][15:0] <= data[15:0];
        end
        if (we[1] && we[2] && we[3])
        begin
            ram[addr[ADDR_WIDTH-1:2]][15:8] <= data[15:8];
            ram[addr[ADDR_WIDTH-1:2]][15:0] <= data[15:0];
        end
        if (we[0] && we[1] && we[2] && we[3])
        begin
            ram[addr[ADDR_WIDTH-1:2]][7:0] <= data[7:0];
            ram[addr[ADDR_WIDTH-1:2]][15:8] <= data[15:8];
            ram[addr[ADDR_WIDTH-1:2]][15:0] <= data[15:0];
            ram[addr[ADDR_WIDTH-1:2]][23:16] <= data[23:16];
        end
    end

    // Continuous assignment implies read returns NEW data.
    assign q = ram[addr[ADDR_WIDTH-1:2]];

endmodule

