module add_sub_overflow (
    input [7:0] a,
    input [7:0] b,
    input add_sub_ctrl,
    output reg [7:0] result,
    output overflow
);

reg [8:0] temp;

always @*
begin
    if (add_sub_ctrl == 1'b1) // addition
    begin
        temp = {1'b0, a} + {1'b0, b};
        overflow = (temp[8] == 1'b1);
        result = temp[7:0];
    end
    else // subtraction
    begin
        temp = {1'b0, a} - {1'b0, b};
        overflow = (temp[8] == 1'b0);
        result = temp[7:0];
    end
end

endmodule

