    parameter NUMREGS = 32;
    parameter LOG2NUMREGS = 5;

    input clk;
    input resetn;

    input a_en;
    input b_en;
    input [31:0] c_writedatain;
    input c_we;
    input [31:0] a_reg;
    input [31:0] b_reg;
    input [31:0] c_reg;
    output [31:0] a_readdataout;
    output [31:0] b_readdataout;

    wire [31:0] a_readdataout_temp;
    wire [31:0] b_readdataout_temp;

    assign b_readdataout = b_readdataout_temp;
    assign a_readdataout = a_readdataout_temp;

    // Define a dual-port RAM to store the register file
    dual_port_ram regfile (
        .clk(clk),
        .we1(c_we & (|c_reg)),
        .we2(1'b0),
        .data1(c_writedatain),
        .data2(32'b11111111111111111111111111111111),
        .out1(a_readdataout_temp),
        .out2(b_readdataout_temp),
        .addr1(c_reg[LOG2NUMREGS-1:0]),
        .addr2(b_en ? b_reg[LOG2NUMREGS-1:0] : a_reg[LOG2NUMREGS-1:0])
    );

    // Reset the register file on resetn
    always @(posedge clk) begin
        if (!resetn) begin
            for (i = 0; i < NUMREGS; i = i + 1) begin
                regfile.we1 <= 1;
                regfile.data1 <= 0;
                regfile.addr1 <= i;
            end
        end
    end

