module barrel_shifter (
    input [3:0] data,
    input shift_left,
    input shift_right,
    input rotate_right,
    output [3:0] shifted_data
);

    assign shifted_data = (shift_left) ? {data[2:0], 1'b0} :
                          (shift_right) ? {1'b0, data[3:1]} :
                          (rotate_right) ? {data[0], data[3:1]} :
                          data;

endmodule

module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    output [3:0] R,
    output Cout
);

    wire [3:0] sum;
    wire c1, c2, c3;

    assign sum = A + B;
    assign Cout = c3;

    assign c1 = A[0] & B[0];
    assign c2 = sum[0] & c1;
    assign c3 = sum[1] & c2;

    assign R = sum;

endmodule

module final_module (
    input [3:0] shifted_data,
    input [3:0] R,
    output [3:0] result
);

    assign result = shifted_data + R;

endmodule

module top_module (
    input clk,
    input reset,
    input [3:0] A,
    input [3:0] B,
    input [2:0] control,
    output [3:0] R,
    output Cout
);

    wire [3:0] shifted_data;
    wire [3:0] sum;
    wire [3:0] result;

    barrel_shifter shifter (
        .data(A),
        .shift_left(control[0]),
        .shift_right(control[1]),
        .rotate_right(control[2]),
        .shifted_data(shifted_data)
    );

    ripple_carry_adder adder (
        .A(shifted_data),
        .B(B),
        .R(sum),
        .Cout(Cout)
    );

    final_module final (
        .shifted_data(shifted_data),
        .R(sum),
        .result(result)
    );

    assign R = result;

endmodule

