reg                         r_tp_green;
reg                         r_tp_blue;
//submodules
//asynchronous logic
//synchronous logic

always @ (posedge clk) begin
  o_read_stb                <=  0;
  o_pixel_rdy               <=  0;
  if (rst) begin
    o_read_act              <=  0;

    o_red                   <=  0;
    o_green                 <=  0;
    o_blue                  <=  0;

    r_next_red              <=  0;
    r_next_green            <=  0;
    r_next_blue             <=  0;

    o_last                  <=  0;
  end
  else begin

    //If a FIFO is available activate it
    if (i_read_rdy && !o_read_act) begin
      r_read_count              <=  0;
      o_read_act                <=  1;
    end

    if (o_pixel_rdy) begin
      if (i_pixel_stb) begin
        o_pixel_rdy             <=  0;
        o_red                   <=  i_read_data[23:16];
        o_green                 <=  i_read_data[15:8];
        o_blue                  <=  i_read_data[7:0];
        o_last                  <=  i_read_data[24];
      end
    end

    if (o_read_act) begin
      o_pixel_rdy               <=  1;
      if (r_read_count < i_read_size) begin
        if (i_pixel_stb) begin
          r_read_count          <=  r_read_count + 1;
          o_read_stb            <=  1;
        end
      end
      else begin
        o_read_act              <=  0;
      end
    end
  end
end

//Test generator
always @ (posedge clk) begin
  if (rst) begin
    r_tp_green          <=  0;
    r_tp_blue           <=  0;
  end
  else begin
    if (i_pixel_stb) begin
      r_tp_green        <=  i_tp_green;
      r_tp_blue         <=  i_tp_blue;
    end
  end
end

//Test pattern
always @ (posedge clk) begin
  if (rst) begin
    r_next_red          <=  0;
    r_next_green        <=  0;
    r_next_blue         <=  0;
  end
  else begin
    if (o_pixel_rdy) begin
      r_next_red        <=  i_tp_red;
      r_next_green      <=  r_tp_green;
      r_next_blue       <=  r_tp_blue;
    end
  end
end

assign o_red = (r_next_red == 8'hFF) ? i_read_data[23:16] : r_next_red;
assign o_green = (r_next_green == 8'hFF) ? i_read_data[15:8] : r_next_green;
assign o_blue = (r_next_blue == 8'hFF) ? i_read_data[7:0] : r_next_blue;

endmodule

module shift_register(
      input CLK,
      input RESET_N,
      input CLKEN,
      input TDI,
      output TDO,
      output reg [7:0] DATA_OUT,
      input DATA_IN,
      input CAPTURE_DR,
      input UPDATE_DR
   );

  reg [7:0] shift_reg;
  reg tdoInt;

  always @ (negedge CLK or negedge RESET_N)
  begin
      if (RESET_N == 1'b0)
         begin
            tdoInt <= #1 1'b0;
            shift_reg <= #1 8'h00;
         end
      else if (CLK == 1'b0)
         begin
            if (CLKEN == 1'b1)
               begin
                  if (CAPTURE_DR == 1'b0)
                     begin
                        shift_reg <= #1 {shift_reg[6:0], TDI};
                        tdoInt <= #1 TDI;
                     end
                  else
                     begin
                        shift_reg <= #1 {shift_reg[6:0], DATA_IN};
                        tdoInt <= #1 DATA_IN;
                     end
               end
         end
  end

   assign TDO = tdoInt;

  always @ (negedge CLK or negedge RESET_N)
   begin
      if (RESET_N == 1'b0)
         DATA_OUT <= #1 8'h00;
      else if (CLK == 1'b0)
         begin
            if (UPDATE_DR == 1'b1)
               DATA_OUT <= #1 shift_reg;
         end
   end
endmodule

