module data_fifo
    #(parameter WIDTH = 72,
      parameter FIFO_DEPTH = 256,
      parameter PROG_FULL_THRESHOLD = 8
      )
    (

     input [WIDTH-1:0] din,     // Data in
     input          wr_en,   // Write enable

     input          rd_en,   // Read the next word

     output reg [WIDTH-1:0]  dout,    // Data out
     output         full,
     output         nearly_full,
     output         prog_full,
     output         empty,
     output [5:0]      data_count,

     input          reset,
     input          clk
     );




reg [WIDTH-1:0] queue [FIFO_DEPTH+1 : 0];
reg [$clog2(FIFO_DEPTH+1) - 1 : 0] rd_ptr;
reg [$clog2(FIFO_DEPTH+1) - 1 : 0] wr_ptr;
reg [$clog2(FIFO_DEPTH+1) - 1 : 0] depth;

// Sample the data
always @(posedge clk)
begin
   if (wr_en)
      queue[wr_ptr] <= din;
   if (rd_en)
      dout <=
	      // synthesis translate_off
	      #1
	      // synthesis translate_on
	      queue[rd_ptr];
end

always @(posedge clk)
begin
   if (reset) begin
      rd_ptr <= 'h0;
      wr_ptr <= 'h0;
      depth  <= 'h0;
   end
   else begin
      if (wr_en) wr_ptr <= wr_ptr + 'h1;
      if (rd_en) rd_ptr <= rd_ptr + 'h1;
      if (wr_en & ~rd_en) depth <=
				   // synthesis translate_off
				   #1
				   // synthesis translate_on
				   depth + 'h1;
      else if (~wr_en & rd_en) depth <=
				   // synthesis translate_off
				   #1
				   // synthesis translate_on
				   depth - 'h1;
   end
end

//assign dout = queue[rd_ptr];
assign full = depth == FIFO_DEPTH;
assign prog_full = (depth >= PROG_FULL_THRESHOLD);
assign nearly_full = depth >= ((FIFO_DEPTH * 7) / 8);
assign empty = depth == 'h0;
assign data_count = depth;

// synthesis translate_off
always @(posedge clk)
begin
   if (wr_en && depth == FIFO_DEPTH && !rd_en)
      $display($time, " ERROR: Attempt to write to full FIFO: %m");
   if (rd_en && depth == 'h0)
      $display($time, " ERROR: Attempt to read an empty FIFO: %m");
end
// synthesis translate_on

endmodule

