module binary_counter (
    input clk,
    input reset,
    output reg[3:0] count,
    output reg max_count
);

always @(posedge clk) begin
    if (reset) begin
        count <= 4'b0000;
        max_count <= 1'b0;
    end else begin
        if (count == 4'b1111) begin
            count <= 4'b0000;
            max_count <= 1'b1;
        end else begin
            count <= count + 1;
            max_count <= 1'b0;
        end
    end
end

endmodule

module dual_port_ram (
    input clk,
    input [7:0] write_addr,
    input [3:0] write_data,
    input [7:0] read_addr_1,
    input [7:0] read_addr_2,
    output reg [3:0] read_data_1,
    output reg [3:0] read_data_2
);

reg [3:0] ram [0:7];
reg [2:0] write_ptr = 0;
reg [2:0] read_ptr_1 = 0;
reg [2:0] read_ptr_2 = 0;

always @(posedge clk) begin
    if (!rst_n) begin
        write_ptr <= 0;
        read_ptr_1 <= 0;
        read_ptr_2 <= 0;
    end else begin
        // Write operation
        if (write_addr[7:3] == write_ptr) begin
            ram[write_addr[2:0]] <= write_data;
            write_ptr <= write_ptr + 1;
        end

        // Read operation 1
        if (read_addr_1[7:3] == read_ptr_1) begin
            read_data_1 <= ram[read_addr_1[2:0]];
            read_ptr_1 <= read_ptr_1 + 1;
        end

        // Read operation 2
        if (read_addr_2[7:3] == read_ptr_2) begin
            read_data_2 <= ram[read_addr_2[2:0]];
            read_ptr_2 <= read_ptr_2 + 1;
        end
    end
end

endmodule

module bitwise_or (
    input [3:0] a,
    input [3:0] b,
    output reg [3:0] c
);

always @(*) begin
    c = a | b;
end

endmodule

module min_value (
    input [7:0] a,
    input [7:0] b,
    input [7:0] c,
    input [7:0] d,
    output reg [3:0] min
);

always @(*) begin
    if (a <= b && a <= c && a <= d) begin
        min = a[3:0];
    end else if (b <= a && b <= c && b <= d) begin
        min = b[3:0];
    end else if (c <= a && c <= b && c <= d) begin
        min = c[3:0];
    end else begin
        min = d[3:0];
    end
end

endmodule

module top_module (
    input clk,
    input rst_n,
    input [7:0] a, b, c, d,
    input [7:0] write_addr,
    input [3:0] write_data,
    input [7:0] read_addr,
    input select,
    output [3:0] sum
);

wire [3:0] ram_data;
dual_port_ram ram (
    .clk(clk),
    .write_addr(write_addr),
    .write_data(write_data),
    .read_addr_1(read_addr),
    .read_addr_2(read_addr + 1),
    .read_data_1(ram_data),
    .read_data_2(ram_data)
);

wire [3:0] or_output;
bitwise_or or_module (
    .a(ram_data),
    .b(select ? 4'b0000 : a),
    .c(or_output)
);

wire [3:0] min_output;
min_value min_module (
    .a(a),
    .b(b),
    .c(c),
    .d(d),
    .min(min_output)
);

assign sum = or_output + min_output;

endmodule

module full_adder (
    input a,
    input b,
    input cin,
    output reg sum,
    output reg cout
);

always @ (a or b or cin) begin
    sum = a ^ b ^ cin;
    cout = (a & b) | (cin & (a ^ b));
end

endmodule

