module control_o (
    input reset,
    input rxd,
    input StringReady,
    input CharReady,
    input parity,
    output reg ready,
    output reg error,
    output reg WriteChar,
    output reg WriteString,
    output reg PossibleStart,
    input clk_2,
    output reg check
);

    reg [2:0] state;
    reg [7:0] data;

    parameter IDLE = 3'b000;
    parameter START = 3'b001;
    parameter DATA = 3'b010;
    parameter PARITY = 3'b011;
    parameter STOP = 3'b100;

    always @(posedge clk_2, posedge reset) begin
        if (reset) begin
            state <= IDLE;
            data <= 8'b0;
            ready <= 1'b0;
            error <= 1'b0;
            WriteChar <= 1'b0;
            WriteString <= 1'b0;
            PossibleStart <= 1'b0;
            check <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (rxd == 1'b0) begin
                        state <= START;
                        data <= 8'b0;
                        WriteChar <= 1'b0;
                        WriteString <= 1'b0;
                        PossibleStart <= 1'b1;
                        check <= 1'b1;
                    end
                end
                START: begin
                    data <= {rxd, 6'b0};
                    state <= DATA;
                end
                DATA: begin
                    data <= {data[6:0], rxd};
                    if (CharReady && StringReady) begin
                        WriteChar <= 1'b1;
                        WriteString <= 1'b1;
                        state <= PARITY;
                    end else if (CharReady) begin
                        WriteChar <= 1'b1;
                        state <= PARITY;
                    end else if (StringReady) begin
                        WriteString <= 1'b1;
                        state <= PARITY;
                    end
                end
                PARITY: begin
                    if (rxd == parity) begin
                        state <= STOP;
                    end else begin
                        error <= 1'b1;
                        state <= IDLE;
                    end
                end
                STOP: begin
                    if (rxd == 1'b1) begin
                        state <= IDLE;
                        ready <= 1'b1;
                    end else begin
                        error <= 1'b1;
                        state <= IDLE;
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end
endmodule

