module vending_machine(
    input clk,
    input reset,
    input [1:0] product,
    input quarter,
    output reg dispense,
    output reg [1:0] change,
    output reg [1:0] price
);

    // Define states
    parameter IDLE = 2'b00;
    parameter PRICE = 2'b01;
    parameter INSERTED = 2'b10;
    parameter DISPENSE = 2'b11;

    // Define state and next state registers
    reg [1:0] state, next_state;

    // Define output registers
    reg [1:0] dispense_reg, change_reg, price_reg;

    // Define internal counter for counting quarters
    reg [1:0] quarter_count;

    // Define constants for product prices
    parameter COLA_PRICE = 2'b00;
    parameter CHIPS_PRICE = 2'b01;
    parameter CANDY_PRICE = 2'b10;

    // Define constants for change
    parameter NO_CHANGE = 2'b00;
    parameter ONE_QUARTER = 2'b01;
    parameter TWO_QUARTERS = 2'b10;

    // Define state machine
    always @(posedge clk, posedge reset) begin
        if (reset) begin
            state <= IDLE;
            dispense_reg <= 1'b0;
            change_reg <= NO_CHANGE;
            price_reg <= 2'b00;
            quarter_count <= 2'b00;
        end else begin
            state <= next_state;
            dispense_reg <= 1'b0;
            change_reg <= NO_CHANGE;
            price_reg <= 2'b00;
            quarter_count <= quarter_count;
        end
    end

    // Define next state logic
    always @(*) begin
        case (state)
            IDLE: begin
                if (product != 2'b00 && product != 2'b01 && product != 2'b10) begin
                    next_state = IDLE;
                end else begin
                    next_state = PRICE;
                end
            end

            PRICE: begin
                if (quarter) begin
                    quarter_count <= quarter_count + 1;
                end

                case (product)
                    2'b00: begin // Cola
                        price_reg <= COLA_PRICE;
                        if (quarter_count >= COLA_PRICE) begin
                            next_state = DISPENSE;
                        end else begin
                            next_state = INSERTED;
                        end
                    end

                    2'b01: begin // Chips
                        price_reg <= CHIPS_PRICE;
                        if (quarter_count >= CHIPS_PRICE) begin
                            next_state = DISPENSE;
                        end else begin
                            next_state = INSERTED;
                        end
                    end

                    2'b10: begin // Candy
                        price_reg <= CANDY_PRICE;
                        if (quarter_count >= CANDY_PRICE) begin
                            next_state = DISPENSE;
                        end else begin
                            next_state = INSERTED;
                        end
                    end
                endcase
            end

            INSERTED: begin
                if (quarter) begin
                    quarter_count <= quarter_count + 1;
                end

                case (product)
                    2'b00: begin // Cola
                        price_reg <= COLA_PRICE;
                        if (quarter_count >= COLA_PRICE) begin
                            next_state = DISPENSE;
                        end else begin
                            next_state = INSERTED;
                        end
                    end

                    2'b01: begin // Chips
                        price_reg <= CHIPS_PRICE;
                        if (quarter_count >= CHIPS_PRICE) begin
                            next_state = DISPENSE;
                        end else begin
                            next_state = INSERTED;
                        end
                    end

                    2'b10: begin // Candy
                        price_reg <= CANDY_PRICE;
                        if (quarter_count >= CANDY_PRICE) begin
                            next_state = DISPENSE;
                        end else begin
                            next_state = INSERTED;
                        end
                    end
                endcase

                if (product != 2'b00 && product != 2'b01 && product != 2'b10) begin
                    next_state = PRICE;
                end
            end

            DISPENSE: begin
                dispense_reg <= 1'b1;
                change_reg <= quarter_count - price_reg;
                quarter_count <= 2'b00;
                next_state = IDLE;
            end
        endcase
    end

    // Assign outputs
    assign dispense = dispense_reg;
    assign change = change_reg;
    assign price = price_reg;

endmodule

