module control_o (reset, rxd, StringReady, CharReady, parity, ready, error, WriteChar, WriteString, PossibleStart, clk_2, check);

   input rxd;
   input StringReady;
   input CharReady;
   input parity;
   input clk_2;
   input check;
   input reset;

   output reg ready;
   output reg error;
   output reg WriteChar;
   output reg WriteString;
   output reg PossibleStart;

   reg [2:0]  current_state;
   reg [2:0]  next_state;

   // se les ponen nombres a los estados para que en el case se pueda entender y manejar mejor
   parameter IDLE = 3'b000;
   parameter POSSIBLESTART = 3'b001;
   parameter READ = 3'b010;
   parameter ERROR = 3'b011;
   parameter WRITE = 3'b100;
   parameter STOP = 3'b101;

   always @(current_state or rxd or check or CharReady or StringReady or reset or parity) begin
      if (reset==1'b1) begin
	 next_state <= 3'b000;
	 ready =1'b0;
	 error = 1'b0;
	 WriteString = 1'b0;
	 WriteChar = 1'b0;
	 PossibleStart = 1'b0;

      end
      else begin
	 case (current_state)
	   IDLE: begin
	      if (rxd==1)
		next_state<=IDLE;
	      else
		next_state<=POSSIBLESTART;


	      ready=1'b0;
	      error=1'b0;
	      WriteChar=1'b0;
	      WriteString=1'b0;
	      PossibleStart=1'b0;
	   end // case: IDLE

	   POSSIBLESTART: begin
	      if (check == 1) begin
		 if (rxd == 0) begin
		   next_state<=READ;
		end		
		 else
		   next_state<=IDLE;
	      end
	      else
		next_state<=POSSIBLESTART;

	      ready=1'b0;
	      error=1'b0;
	      WriteChar=1'b0;
	      WriteString=1'b0;
	      PossibleStart=1'b1;

	   end // case: POSSIBLESTART

	   READ: begin
	      if (CharReady==0)
		next_state<=READ;
	      else
		next_state<=ERROR;

	      ready=1'b0;
	      error=1'b0;
	      WriteChar=1'b1;
	      WriteString=1'b0;
	      PossibleStart=1'b0;
	   end // case: READ

	   ERROR: begin
	      next_state<=WRITE;
	      if (parity==1)
		error=1'b1;
	      else
		error=1'b0;

	      ready=1'b0;
	      WriteChar=1'b0;
	      WriteString=1'b0;
	      PossibleStart=1'b0;
	   end // case: ERROR

	   WRITE: begin
	      if (StringReady==0)
		next_state<=IDLE;
	      else
		next_state<=STOP;

	      ready=1'b0;
	      error=1'b0;
	      WriteChar=1'b0;
	      WriteString=1'b1;
	      PossibleStart=1'b0;
	   end // case: WRITE

	   STOP: begin
		next_state<=IDLE;

	      ready=1'b1;
	      error=1'b0;
	      WriteChar=1'b0;
	      WriteString=1'b0;
	      PossibleStart=1'b0;
	   end // case: STOP

	   default: begin 
	      next_state<=IDLE;
	      ready=1'b0;
	      error=1'b0;
	      WriteChar=1'b0;
	      WriteString=1'b0;
	      PossibleStart=1'b0;
	   end
	 endcase // case (current_state)
      end // else: !if(reset==1'b1)
   end // always @ (posedge clk_2)

   always @(negedge clk_2 or posedge reset) begin
      if (reset == 1'b1) begin
	current_state<=IDLE;
	end
      else begin
	current_state<=next_state;
	end
   end
endmodule

module LZW (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 8; // number of input signals
parameter m = 8; // number of output signals
parameter maxbits = 12; // maximum number of bits allowed for encoding

// Define dictionary
reg [n-1:0] dict [0:2**maxbits-1];
reg [n-1:0] curr_input;
reg [n-1:0] prev_input;
reg [maxbits-1:0] dict_size;
reg [maxbits-1:0] curr_code;
reg [maxbits-1:0] prev_code;
reg [maxbits-1:0] next_code;
reg [maxbits:0] bit_buffer;
reg [5:0] bits_in_buffer;
reg [maxbits-1:0] mask;
reg [maxbits-1:0] clear_code;
reg [maxbits-1:0] end_code;
reg [maxbits-1:0] code_size;
reg [maxbits-1:0] max_code;

// Initialize dictionary
initial begin
  dict_size = 256;
  curr_code = dict_size + 1;
  prev_input = 0;
  mask = 2**code_size - 1;
  clear_code = dict_size;
  end_code = dict_size + 1;
  code_size = 9;
  max_code = 2**code_size - 1;
  for (i = 0; i < dict_size; i = i + 1) begin
    dict[i] = i;
  end
end

// Compress input data
always @(posedge clk) begin
  if (reset) begin
    curr_input = 0;
    prev_input = 0;
    curr_code = dict_size + 1;
    prev_code = 0;
    next_code = dict_size + 2;
    bit_buffer = 0;
    bits_in_buffer = 0;
    mask = 2**code_size - 1;
    clear_code = dict_size;
    end_code = dict_size + 1;
    code_size = 9;
    max_code = 2**code_size - 1;
    for (i = 0; i < dict_size; i = i + 1) begin
      dict[i] = i;
    end
  end else begin
    curr_input = in;
    if (dict[curr_input] != 0) begin
      prev_input = curr_input;
    end else begin
      dict[curr_input] = curr_code;
      curr_code = curr_code + 1;
      if (curr_code > max_code) begin
        code_size = code_size + 1;
        max_code = 2**code_size - 1;
      end
      if (prev_input != 0) begin
        bit_buffer = bit_buffer | (prev_code << bits_in_buffer);
        bits_in_buffer = bits_in_buffer + code_size;
        if (bits_in_buffer >= 8) begin
          out = bit_buffer[7:0];
          bit_buffer = bit_buffer >> 8;
          bits_in_buffer = bits_in_buffer - 8;
        end
      end else begin
        clear_code = curr_code - 1;
      end
      prev_input = curr_input;
      prev_code = dict[prev_input];
    end
  end
end

// Decompress compressed data
always @(posedge clk) begin
  if (reset) begin
    curr_input = 0;
    prev_input = 0;
    curr_code = dict_size + 1;
    prev_code = 0;
    next_code = dict_size + 2;
    bit_buffer = 0;
    bits_in_buffer = 0;
    mask = 2**code_size - 1;
    clear_code = dict_size;
    end_code = dict_size + 1;
    code_size = 9;
    max_code = 2**code_size - 1;
    for (i = 0; i < dict_size; i = i + 1) begin
      dict[i] = i;
    end
  end else begin
    if (bits_in_buffer < code_size) begin
      bit_buffer = bit_buffer | (in << bits_in_buffer);
      bits_in_buffer = bits_in_buffer + 8;
    end
    curr_code = bit_buffer & mask;
    bit_buffer = bit_buffer >> code_size;
    bits_in_buffer = bits_in_buffer - code_size;
    if (curr_code == clear_code) begin
      code_size = 9;
      max_code = 2**code_size - 1;
      next_code = dict_size + 2;
      curr_code = bit_buffer & mask;
      bit_buffer = bit_buffer >> code_size;
      bits_in_buffer = bits_in_buffer - code_size;
      prev_code = curr_code;
      prev_input = dict[curr_code];
      out = prev_input;
    end else if (curr_code == end_code) begin
      // End of compressed data
    end else begin
      if (curr_code < next_code) begin
        out = dict[curr_code];
        dict[next_code] = dict[prev_code] & ~mask | curr_code;
        next_code = next_code + 1;
        if (next_code > max_code && code_size < maxbits) begin
          code_size = code_size + 1;
          max_code = 2**code_size - 1;
        end
      end else begin
        dict[next_code] = dict[prev_code] & ~mask | prev_code;
        next_code = next_code + 1;
        if (next_code > max_code && code_size < maxbits) begin
          code_size = code_size + 1;
          max_code = 2**code_size - 1;
        end
        prev_code = curr_code;
        prev_input = dict[curr_code];
        out = prev_input;
      end
    end
  end
end

endmodule

module pulse_generator
  #(parameter WIDTH=8)
    ( input clock,
      input reset,
      input enable,
      input [WIDTH-1:0] rate,
      input strobe_fast,
      output reg strobe_slow );

