            if (display_digit == 4'b1110) begin
                display_digit <= 4'b1101;
            end else if (display_digit == 4'b1101) begin
                display_digit <= 4'b1111;
            end else if (display_digit == 4'b1111) begin
                display_digit <= 4'b1100;
            end else if (display_digit == 4'b1100) begin
                display_digit <= 4'b1110;
            end
        end
    end

    always @ (display_digit, lap_time_seconds, lap_time_minutes, stopwatch_seconds, stopwatch_minutes) begin
        case (display_digit)
            4'b1110: display_value[3:0] = lap_time_seconds;
