module stopwatch (
    input clk,
    input reset,
    input start_stop,
    output [3:0] seconds,
    output [3:0] minutes);

    reg [3:0] count_seconds;
    reg [3:0] count_minutes;
    reg running;

    always @ (posedge clk) begin
        if (reset) begin
            count_seconds <= 4'b0000;
            count_minutes <= 4'b0000;
            running <= 1'b0;
        end else begin
            if (start_stop) begin
                running <= ~running;
            end
            if (running) begin
                if (count_seconds == 4'b1001) begin
                    count_seconds <= 4'b0000;
                    if (count_minutes == 4'b1001) begin
                        count_minutes <= 4'b0000;
                    end else begin
                        count_minutes <= count_minutes + 1;
                    end
                end else begin
                    count_seconds <= count_seconds + 1;
                end
            end
        end
    end

    assign seconds = count_seconds;
    assign minutes = count_minutes;

endmodule

module lap_timer (
    input clk,
    input reset,
    input lap_reset,
    input [3:0] seconds,
    input [3:0] minutes,
    output [3:0] lap_seconds,
    output [3:0] lap_minutes);

    reg [3:0] count_lap_seconds;
    reg [3:0] count_lap_minutes;
    reg [3:0] prev_seconds;
    reg [3:0] prev_minutes;
    reg lap_running;

    always @ (posedge clk) begin
        if (reset) begin
            count_lap_seconds <= 4'b0000;
            count_lap_minutes <= 4'b0000;
            lap_running <= 1'b0;
        end else begin
            if (lap_reset) begin
                count_lap_seconds <= 4'b0000;
                count_lap_minutes <= 4'b0000;
            end else if (prev_seconds != seconds || prev_minutes != minutes) begin
                if (lap_running) begin
                    if (count_lap_seconds == 4'b1001) begin
                        count_lap_seconds <= 4'b0000;
                        if (count_lap_minutes == 4'b1001) begin
                            count_lap_minutes <= 4'b0000;
                        end else begin
                            count_lap_minutes <= count_lap_minutes + 1;
                        end
                    end else begin
                        count_lap_seconds <= count_lap_seconds + 1;
                    end
                end
                prev_seconds <= seconds;
                prev_minutes <= minutes;
            end
            if (lap_running && !prev_seconds && !prev_minutes) begin
                lap_running <= 1'b0;
            end else if (!lap_running && (prev_seconds || prev_minutes)) begin
                lap_running <= 1'b1;
            end
        end
    end

    assign lap_seconds = count_lap_seconds;
    assign lap_minutes = count_lap_minutes;

endmodule

module lap_time_calculator (
    input [3:0] seconds,
    input [3:0] minutes,
    input [3:0] lap_seconds,
    input [3:0] lap_minutes,
    output [3:0] lap_time_seconds,
    output [3:0] lap_time_minutes);

    reg [3:0] count_lap_time_seconds;
    reg [3:0] count_lap_time_minutes;
    reg [3:0] prev_lap_seconds;
    reg [3:0] prev_lap_minutes;

    always @ (seconds, minutes, lap_seconds, lap_minutes) begin
        if (lap_seconds != prev_lap_seconds || lap_minutes != prev_lap_minutes) begin
            count_lap_time_seconds <= lap_seconds - prev_lap_seconds;
            if (count_lap_time_seconds < 0) begin
                count_lap_time_seconds <= count_lap_time_seconds + 10;
                count_lap_time_minutes <= lap_minutes - prev_lap_minutes - 1;
            end else begin
                count_lap_time_minutes <= lap_minutes - prev_lap_minutes;
            end
            prev_lap_seconds <= lap_seconds;
            prev_lap_minutes <= lap_minutes;
        end else if (seconds == 4'b0000 && minutes == 4'b0000) begin
            count_lap_time_seconds <= 4'b0000;
            count_lap_time_minutes <= 4'b0000;
            prev_lap_seconds <= 4'b0000;
            prev_lap_minutes <= 4'b0000;
        end
    end

    assign lap_time_seconds = count_lap_time_seconds;
    assign lap_time_minutes = count_lap_time_minutes;

endmodule

