module genetico_tb();

  reg [10:0] conf_les[8:0];
  reg [3:0] conf_outs[1:0];
  reg [2:0] in;
  wire [1:0] out;

  genetico dut(
    .conf_les(conf_les),
    .conf_outs(conf_outs),
    .in(in),
    .out(out)
  );

  integer i, j, k;

  initial begin
    // Test all possible input configurations
    for (i = 0; i < 512; i = i + 1) begin
      in = i[2:0];
      for (j = 0; j < 512; j = j + 1) begin
        for (k = 0; k < 9; k = k + 1) begin
          conf_les[k] = j[(k+1)*11-1:k*11];
        end
        conf_outs[0] = j[10:7];
        conf_outs[1] = j[6:3];
        #1;
        // Verify output
        if (out !== {i[conf_outs[1]], i[conf_outs[0]]}) begin
          $display("Error: Unexpected output for input %b and configuration %b", in, conf_les);
          $stop;
        end
      end
    end
    $display("All tests passed!");
    $finish;
  end

endmodule

