            4'h8: begin s = (cs && rd) ? 6'b010000 : 6'b000000; end //clk_0
            default: begin s = 6'b000000; end
        endcase
    end

    always @(negedge clk) begin
        limit = (s[0]) ? d_in : limit;
        count = (s[1]) ? d_in : count;
        en = (s[2]) ? d_in : en;
    end

    clk_generator c_g (.clk(clk), .rst(rst), .limit(limit), .count(count), .en(en), .clk_0(clk_0), .done(done));

    always @(negedge clk) begin
        case (s[5:3])
            3'b001: d_out[0] = done;
            3'b010: d_out = clk_0;
            default: d_out = 0;
        endcase
    end

endmodule

module clk_generator (clk, rst, limit, count, en, clk_0, done);

    input clk;
    input rst;
    input [31:0] limit;
    input [31:0] count;
    input en;
    output reg clk_0;
    output reg done;

    reg [31:0] cnt;

    always @(posedge clk) begin
        if (rst) begin
            cnt <= 0;
            clk_0 <= 0;
            done <= 1;
        end else begin
            if (en) begin
                if (cnt == limit) begin
                    cnt <= 0;
                    clk_0 <= ~clk_0;
                    done <= 1;
                end else begin
                    cnt <= cnt + 1;
                    done <= 0;
                end
            end else begin
                cnt <= 0;
                clk_0 <= 0;
                done <= 1;
            end
        end
    end

endmodule

module adder(
  input [3:0] A,
  input [3:0] B,
