module serial_receiver (
    input  clk,
    input  rxd,
    input  baud8tick,

    output reg [7:0] rxd_data,
    output reg       rxd_data_ready,
    output reg       rxd_endofpacket,
    output reg       rxd_idle
);

    reg [1:0] rxd_sync_inv;  // we invert rxd, so that the idle becomes "0", to prevent a phantom character to be received at startup
    always @(posedge clk) if(baud8tick) rxd_sync_inv <= {rxd_sync_inv[0], ~rxd};

    reg [1:0] rxd_cnt_inv;
    reg rxd_bit_inv;

    always @(posedge clk)
    if(baud8tick) begin
        if( rxd_sync_inv[1] && rxd_cnt_inv!=2'b11) rxd_cnt_inv <= rxd_cnt_inv + 2'h1;
        else
        if(~rxd_sync_inv[1] && rxd_cnt_inv!=2'b00) rxd_cnt_inv <= rxd_cnt_inv - 2'h1;
        if(rxd_cnt_inv==2'b00) rxd_bit_inv <= 1'b0;
        else
        if(rxd_cnt_inv==2'b11) rxd_bit_inv <= 1'b1;
    end

    reg [3:0] state;
    reg [3:0] bit_spacing;

    // "next_bit" controls when the data sampling occurs depending on how noisy the rxd is, different
    // values might work better with a clean connection, values from 8 to 11 work
    wire next_bit = (bit_spacing==4'd10);

    always @(posedge clk)
    if(state==0)bit_spacing <= 4'b0000;
    else
    if(baud8tick) bit_spacing <= {bit_spacing[2:0] + 4'b0001} | {bit_spacing[3], 3'b000};

    always @(posedge clk)
    if(baud8tick)
    case(state)
        4'b0000: if(rxd_bit_inv)state <= 4'b1000;  // start bit found?
        4'b1000: if(next_bit)  state <= 4'b1001;  // bit 0
        4'b1001: if(next_bit)  state <= 4'b1010;  // bit 1
        4'b1010: if(next_bit)  state <= 4'b1011;  // bit 2
        4'b1011: if(next_bit)  state <= 4'b1100;  // bit 3
        4'b1100: if(next_bit)  state <= 4'b1101;  // bit 4
        4'b1101: if(next_bit)  state <= 4'b1110;  // bit 5
        4'b1110: if(next_bit)  state <= 4'b1111;  // bit 6
        4'b1111: if(next_bit)  state <= 4'b0001;  // bit 7
        4'b0001: if(next_bit)  state <= 4'b0000;  // stop bit
        default:         state <= 4'b0000;
    endcase

    always @(posedge clk)
    if(baud8tick && next_bit && state[3]) rxd_data <= {~rxd_bit_inv, rxd_data[7:1]};

    always @(posedge clk)
    begin
        rxd_data_ready <= (baud8tick && next_bit && state==4'b0001 && ~rxd_bit_inv);  // ready only if the stop bit is received
    end

    reg [4:0] gap_count;
    always @(posedge clk) if (state!=0) gap_count<=5'h00; else if(baud8tick & ~gap_count[4]) gap_count <= gap_count + 5'h01;
    always @(posedge clk) rxd_idle <= gap_count[4];
    always @(posedge clk) rxd_endofpacket <= baud8tick & (gap_count==5'h0F);

endmodule

module fifo_generator (
  input clk,
  input [4:0] din,
  input s_aclk,
  input rst,
  input rd_en,
  input wr_en,
  input s_aresetn,
  output [4:0] dout,
  output empty,
  output full
);

  // Define parameters
  parameter WIDTH = 5;
  parameter DEPTH = 1024;
  parameter ADDR_WIDTH = $clog2(DEPTH);

  // Define registers
  reg [ADDR_WIDTH-1:0] wptr = 0;
  reg [ADDR_WIDTH-1:0] rptr = 0;
  reg [WIDTH-1:0] mem [0:DEPTH-1];

  // Define wires
  wire [ADDR_WIDTH-1:0] next_wptr;
  wire [ADDR_WIDTH-1:0] next_rptr;
  wire [WIDTH-1:0] dout;
  wire empty;
  wire full;

  // Define slower clock domain registers
  reg [31:0] slow_cnt = 0;
  reg [31:0] slow_wr_cnt = 0;
  reg [31:0] slow_rd_cnt = 0;

  // Define slower clock domain wires
  wire slow_wr_en;
  wire slow_rd_en;

  // Synchronize signals to the slower clock domain
  always @(posedge s_aclk or negedge s_aresetn) begin
    if (~s_aresetn) begin
      slow_cnt <= 0;
      slow_wr_cnt <= 0;
      slow_rd_cnt <= 0;
    end else begin
      slow_cnt <= slow_cnt + 1;
      slow_wr_cnt <= slow_wr_cnt + wr_en;
      slow_rd_cnt <= slow_rd_cnt + rd_en;
    end
  end

  // Generate slower clock domain signals
  assign slow_wr_en = (slow_wr_cnt >= (DEPTH/2)) ? 1'b0 : 1'b1;
  assign slow_rd_en = (slow_rd_cnt >= (DEPTH/2)) ? 1'b0 : 1'b1;

  // Synchronize read and write pointers to the slower clock domain
  always @(posedge s_aclk or negedge s_aresetn) begin
    if (~s_aresetn) begin
      next_wptr <= 0;
      next_rptr <= 0;
    end else if (slow_cnt == 0) begin
      next_wptr <= (slow_wr_en && wr_en) ? wptr + 1'b1 : wptr;
      next_rptr <= (slow_rd_en && rd_en) ? rptr + 1'b1 : rptr;
    end else begin
      next_wptr <= wptr;
      next_rptr <= rptr;
    end
  end

  // Update read and write pointers
  always @(posedge clk or negedge rst) begin
    if (~rst) begin
      wptr <= 0;
      rptr <= 0;
    end else begin
      wptr <= next_wptr;
      rptr <= next_rptr;
    end
  end

  // Write data to memory
  always @(posedge clk or negedge rst) begin
    if (~rst && wr_en) begin
      mem[wptr] <= din;
    end
  end

  // Read data from memory
  always @(posedge clk or negedge rst) begin
    if (~rst && rd_en) begin
      dout <= mem[rptr];
    end
  end

  // Check if FIFO is empty or full
  assign empty = (wptr == rptr) ? 1'b1 : 1'b0;
  assign full = ((wptr+1'b1) == rptr) ? 1'b1 : 1'b0;

endmodule

module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    input CIN,
    output reg [3:0] Q,
    output COUT
);

    reg [3:0] sum;
    reg carry;

    always @(*) begin
        sum = A + B + CIN;
        carry = (A[3] & B[3]) | (A[3] & CIN) | (B[3] & CIN);
        Q = sum;
        COUT = carry;
    end

endmodule

module ripple_adder(
    input [7:0] a,b,
    output [7:0] sum,
    output carry_out
);

wire [7:0] c;
wire [7:0] s;

assign c[0] = 1'b0;
genvar i;
generate
    for (i = 0; i < 8; i = i + 1) begin : adder_loop
        full_adder fa(
            .a(a[i]),
            .b(b[i]),
            .c_in(c[i]),
            .s(s[i]),
            .c_out(c[i+1])
        );
    end
endgenerate

assign carry_out = c[8];
assign sum = s;

endmodule

module full_adder(
    input a,b,c_in,
    output s,c_out
);

assign s = a ^ b ^ c_in;
assign c_out = (a & b) | (c_in & (a ^ b));

endmodule

module top_module(
