ripple_adder ra(
    .a(a),
    .b(b),
    .sum(sum),
    .carry_out(carry_out)
);

endmodule

module fletcher (
  input [15:0] block1,
  input [15:0] block2,
  // ...
  input [15:0] blockn,
  input [15:0] checksum_in,
  output reg [15:0] checksum_out,
  output reg match
);

  reg [7:0] sum1, sum2;
  integer i;

  always @(*) begin
    sum1 = 0;
    sum2 = 0;
    for (i = 0; i < n; i = i + 1) begin
      case (i)
        0: sum1 = sum1 + block1;
        1: sum1 = sum1 + block2;
        // ...
        default: sum1 = sum1 + blockn;
      endcase
      sum1 = sum1 % 255;
      sum2 = sum2 + sum1;
      sum2 = sum2 % 255;
    end
    checksum_out = (sum2 << 8) | sum1;
    match = (checksum_in == checksum_out);
  end

endmodule

