module calculator(
    input [7:0] A,
    input [7:0] B,
    input [1:0] op,
    input oe,
    output reg [7:0] Y
);

reg [15:0] product;
reg [15:0] quotient;

always @(*) begin
    case (op)
        2'b00: Y = A + B;
        2'b01: Y = A - B;
        2'b10: begin
            product = A * B;
            Y = product[15:8];
        end
        2'b11: begin
            if (B == 0) Y = 8'h00;
            else begin
                quotient = A / B;
                Y = quotient[15:8];
            end
        end
    endcase
end

endmodule

module parity (
    input [7:0] in,
    output [8:0] out);

    wire [3:0] sum;
    wire xor_out;

    assign sum = in[3:0] + in[7:4];
    assign xor_out = in[0] ^ in[1] ^ in[2] ^ in[3] ^ in[4] ^ in[5] ^ in[6] ^ in[7];

    assign out[8] = xor_out;
    assign out[7:4] = sum;
    assign out[3:0] = in[3:0];

endmodule

