module fifo_over_ufc
  #(
    parameter FIFO_DATA_WIDTH   = 32,
    parameter AURORA_DATA_WIDTH = 64
    )
   (
    input                        RESET,
    input                        AURORA_USER_CLK,
    input                        AURORA_TX_REQ,
    input [7:0]                  AURORA_TX_MS,
    output                       AURORA_TX_TREADY,
    input  [AURORA_DATA_WIDTH-1:0] AURORA_TX_TDATA,
    input                        AURORA_TX_TVALID,
    output [AURORA_DATA_WIDTH-1:0] AURORA_RX_TDATA,
    output                       AURORA_RX_TVALID,
    input                        FIFO_CLK,
    output [FIFO_DATA_WIDTH-1:0]  TX_FIFO_Q,
    output                       TX_FIFO_WREN,
    input                        TX_FIFO_FULL,
    input  [FIFO_DATA_WIDTH-1:0]  RX_FIFO_Q,
    output                       RX_FIFO_RDEN,
    input                        RX_FIFO_EMPTY,
    output                       ERR
    );

   reg [FIFO_DATA_WIDTH-1:0] fifo_mem [0:(2**FIFO_DATA_WIDTH)-1];
   reg [FIFO_DATA_WIDTH-1:0] tx_fifo_q;
   reg [FIFO_DATA_WIDTH-1:0] rx_fifo_q;
   reg [FIFO_DATA_WIDTH-1:0] tx_fifo_q_next;
   reg [FIFO_DATA_WIDTH-1:0] rx_fifo_q_next;
   reg                        tx_fifo_wren;
   reg                        rx_fifo_rden;
   reg                        tx_fifo_full;
   reg                        rx_fifo_empty;
   reg                        err;
   reg                        a_tx_tready;
   reg                        a_rx_tvalid;
   reg [1:0]                  state;
   localparam S0 = 2'h0;
   localparam S1 = 2'h1;
   localparam S2 = 2'h2;
   localparam S3 = 2'h3;
   localparam S4 = 2'h4;

   // FIFO Write Logic
   always @(posedge FIFO_CLK) begin
      if (RESET) begin
         tx_fifo_q <= 0;
         tx_fifo_full <= 0;
         tx_fifo_wren <= 0;
      end
      else if (tx_fifo_wren && !tx_fifo_full) begin
         fifo_mem <= {fifo_mem[0+(2**FIFO_DATA_WIDTH)], tx_fifo_q};
         tx_fifo_full <= (fifo_mem[(2**FIFO_DATA_WIDTH)-1] == 1'b1);
         tx_fifo_q <= tx_fifo_q_next;
         tx_fifo_wren <= 0;
      end
   end

   // FIFO Read Logic
   always @(posedge FIFO_CLK) begin
      if (RESET) begin
         rx_fifo_q <= 0;
         rx_fifo_empty <= 1;
         rx_fifo_rden <= 0;
      end
      else if (rx_fifo_rden && !rx_fifo_empty) begin
         rx_fifo_q <= fifo_mem[0];
         fifo_mem <= {1'b0, fifo_mem[1:(2**FIFO_DATA_WIDTH)-1]};
         rx_fifo_empty <= (fifo_mem[(2**FIFO_DATA_WIDTH)-1] == 1'b0);
         rx_fifo_rden <= 0;
      end
   end

   // Aurora UFC Interface
   always @(posedge AURORA_USER_CLK or posedge RESET) begin
      if (RESET) begin
         state <= S0;
         a_tx_tready <= 1;
         a_rx_tvalid <= 0;
      end
      else begin
         case(state)
            S0: begin
               a_tx_tready <= 1;
               if (AURORA_TX_REQ == 1) begin
                  state <= S1;
                  a_tx_tready <= 0;
               end
            end
            S1: begin
               a_tx_tready <= 0;
               state <= S2;
            end
            S2: begin
               tx_fifo_q_next <= AURORA_TX_TDATA;
               tx_fifo_wren <= AURORA_TX_TVALID;
               state <= S3;
            end
            S3: begin
               a_tx_tready <= 1;
               state <= S4;
            end
            S4: begin
               a_rx_tvalid <= ~RX_FIFO_EMPTY;
               Aurora_RX_TDATA <= rx_fifo_q;
               rx_fifo_rden <= AURORA_RX_TVALID;
               state <= S0;
            end
            default: begin
               state <= S0;
            end
         endcase
      end
   end

   // Error Logic
   always @(posedge FIFO_CLK) begin
      err <= tx_fifo_full && tx_fifo_wren || rx_fifo_empty && rx_fifo_rden;
   end

   // Output Logic
   assign TX_FIFO_Q = tx_fifo_q;
   assign TX_FIFO_WREN = ~tx_fifo_full;
   assign RX_FIFO_RDEN = ~rx_fifo_empty;
   assign RX_FIFO_Q = rx_fifo_q;
   assign TX_FIFO_FULL = tx_fifo_full;
   assign RX_FIFO_EMPTY = rx_fifo_empty;
   assign ERR = err;

endmodule

