module interrupt_controller (
  input [n-1:0] irq,
  input ack,
  output [7:0] vec
);

parameter n = 4; // number of interrupt request signals

reg [n-1:0] irq_priority; // priority of interrupt requests
reg [n-1:0] irq_pending; // pending interrupt requests
reg [n-1:0] irq_clear; // clear interrupt requests

always @(*) begin
  // prioritize interrupt requests based on severity and order
  irq_priority[0] = irq[0];
  irq_priority[1] = irq[1];
  irq_priority[2] = irq[2];
  irq_priority[3] = irq[3];

  // set pending interrupt requests
  irq_pending = irq_priority & ~irq_clear;
end

always @(posedge ack) begin
  // send highest priority interrupt to processor
  if (irq_pending[0]) begin
    vec = 8'h01;
    irq_clear[0] = 1;
  end else if (irq_pending[1]) begin
    vec = 8'h02;
    irq_clear[1] = 1;
  end else if (irq_pending[2]) begin
    vec = 8'h03;
    irq_clear[2] = 1;
  end else if (irq_pending[3]) begin
    vec = 8'h04;
    irq_clear[3] = 1;
  end else begin
    vec = 8'h00;
  end
end

endmodule

module top_module (
    input clk,
    input rst_n,
    input [7:0] a, b, c, d, // input for the minimum value module
    input [7:0] write_addr, // write address for the RAM
    input [3:0] write_data, // write data for the RAM
    input [7:0] read_addr, // read address for the RAM
    input select, // select input to choose between minimum value and RAM read
    output [3:0] sum // 4-bit output representing the sum of minimum value and RAM read
);

// Minimum value module
minimum_value min_val(
    .a(a),
    .b(b),
    .c(c),
    .d(d),
    .min_val_out(min_val_out)
);

// True dual-port RAM
reg [3:0] ram [0:7];
integer i;
initial begin
    for (i = 0; i < 8; i = i + 1) begin
        ram[i] = 0;
    end
end

always @(posedge clk) begin
    if (~rst_n) begin
        for (i = 0; i < 8; i = i + 1) begin
            ram[i] <= 0;
        end
    end else begin
        if (select) begin // RAM read
            sum <= ram[read_addr];
        end else begin // Minimum value
            sum <= min_val_out;
            ram[write_addr] <= write_data;
        end
    end
end

endmodule

