module binary_adder (
    input [7:0] input1,
    input [7:0] input2,
    input carry_in,
    output [7:0] sum,
    output carry_out,
    output overflow_flag
);

reg [7:0] stage1_out;
reg [7:0] stage2_out;
reg [7:0] stage3_out;
reg [7:0] stage4_out;
reg [7:0] stage5_out;
reg [7:0] stage6_out;
reg [7:0] stage7_out;
reg [7:0] stage8_out;
reg [1:0] overflow_check;

assign sum = stage8_out;
assign carry_out = stage8_out[8];

always @(*) begin
    stage1_out = input1 + input2 + carry_in;
end

always @(*) begin
    stage2_out = stage1_out + {1'b0, stage1_out[7:1]};
end

always @(*) begin
    stage3_out = stage2_out + {1'b0, stage2_out[6:0], stage2_out[7]};
end

always @(*) begin
    stage4_out = stage3_out + {1'b0, stage3_out[5:0], stage3_out[6]};
end

always @(*) begin
    stage5_out = stage4_out + {1'b0, stage4_out[4:0], stage4_out[5]};
end

always @(*) begin
    stage6_out = stage5_out + {1'b0, stage5_out[3:0], stage5_out[4]};
end

always @(*) begin
    stage7_out = stage6_out + {1'b0, stage6_out[2:0], stage6_out[3]};
end

always @(*) begin
    stage8_out = stage7_out + {1'b0, stage7_out[1:0], stage7_out[2]};
    overflow_check = stage7_out[8:7] + stage8_out[8:7];
end

assign overflow_flag = (overflow_check == 2'b10);

endmodule

module mealy_3bit_sequence_detection (
  input clk,
  input reset,
  input data,
  output reg match
);

  // Define the two states
  localparam IDLE = 2'b00;
  localparam DETECTED = 2'b01;

  // Define the state register and initialize to IDLE
  reg [1:0] state = IDLE;

  // Define the sequence detection logic
  always @(posedge clk, negedge reset) begin
    if (reset == 1'b0) begin
      state <= IDLE;
      match <= 1'b0;
    end else begin
      case(state)
        IDLE: begin
          if (data == 1'b1) begin
            state <= DETECTED;
          end else begin
            state <= IDLE;
          end
        end
        DETECTED: begin
          if (data == 1'b0) begin
            state <= IDLE;
            match <= 1'b0;
          end else begin
            state <= DETECTED;
            match <= 1'b1;
          end
        end
      endcase
    end
  end

endmodule

module fifo_36x512 (
  clk, rd_en, rst, empty, wr_en, full, prog_empty, prog_full, dout, din
);
  input clk;
  input rd_en;
  input rst;
  output empty;
  input wr_en;
  output full;
  output prog_empty;
  output prog_full;
  output [35 : 0] dout;
  input [35 : 0] din;

  reg [35:0] fifo_mem [0:511];
  reg [8:0] wr_ptr;
  reg [8:0] rd_ptr;
  wire [8:0] fifo_count;
  wire [8:0] fifo_depth = 512;
  wire [8:0] almost_full_threshold = 504;
  wire [8:0] almost_empty_threshold = 8;

  // empty flag
  assign empty = (fifo_count == 0);

  // full flag
  assign full = (fifo_count == fifo_depth);

  // programmable empty flag
  assign prog_empty = (fifo_count <= almost_empty_threshold);

  // programmable full flag
  assign prog_full = (fifo_count >= almost_full_threshold);

  // write operation
  always @(posedge clk) begin
    if (rst) begin
      wr_ptr <= 0;
    end else if (wr_en && !full) begin
      fifo_mem[wr_ptr] <= din;
      wr_ptr <= wr_ptr + 1;
    end
  end

  // read operation
  always @(posedge clk) begin
    if (rst) begin
      rd_ptr <= 0;
    end else if (rd_en && !empty) begin
      dout <= fifo_mem[rd_ptr];
      rd_ptr <= rd_ptr + 1;
    end
  end

  // count operation
  assign fifo_count = (wr_ptr >= rd_ptr) ? (wr_ptr - rd_ptr) : (wr_ptr + fifo_depth - rd_ptr);

endmodule

