module ddr_memory_interface_block (
  input clk,
  input reset,
  input read_en,
  input write_en,
  input [31:0] addr,
  input [31:0] data_in,
  output [31:0] data_out
);

// DDR memory protocol definitions
parameter TCK = 2; // Clock period in ns
parameter T_RCD = 15; // RAS to CAS delay in ns
parameter T_RAS = 42; // Row active time in ns
parameter T_RC = 57; // Row cycle time in ns
parameter T_WTR = 7; // Write to read turnaround time in ns
parameter T_CAS = 15; // CAS latency in ns
parameter T_WR = 15; // Write recovery time in ns
parameter T_RTP = 7; // Read to precharge time in ns
parameter T_RRD = 10; // Row to row delay in ns

// Internal state definitions
reg [31:0] mem[0:1023]; // DDR memory array
reg [31:0] row_addr; // Current row address
reg [31:0] col_addr; // Current column address
reg [1:0] state; // Current state
parameter IDLE = 2'b00; // Idle state
parameter READ = 2'b01; // Read state
parameter WRITE = 2'b10; // Write state

// Timing control signals
reg [3:0] tck_count; // TCK counter
reg [3:0] rcd_count; // RCD counter
reg [3:0] ras_count; // RAS counter
reg [3:0] rc_count; // RC counter
reg [3:0] wtr_count; // WTR counter
reg [3:0] cas_count; // CAS counter
reg [3:0] wr_count; // WR counter
reg [3:0] rtp_count; // RTP counter
reg [3:0] rrd_count; // RRD counter

// Output data register
reg [31:0] data_reg;

// Reset logic
always @(posedge clk) begin
  if (reset) begin
    mem <= 'h0;
    row_addr <= 'h0;
    col_addr <= 'h0;
    state <= IDLE;
    tck_count <= 0;
    rcd_count <= 0;
    ras_count <= 0;
    rc_count <= 0;
    wtr_count <= 0;
    cas_count <= 0;
    wr_count <= 0;
    rtp_count <= 0;
    rrd_count <= 0;
    data_reg <= 'h0;
  end
end

// State machine
always @(posedge clk) begin
  case (state)
    IDLE: begin
      if (read_en) begin
        row_addr <= addr[21:10];
        col_addr <= addr[9:0];
        state <= READ;
        tck_count <= 0;
        rcd_count <= T_RCD/TCK;
        ras_count <= T_RAS/TCK;
        rc_count <= T_RC/TCK;
        wtr_count <= T_WTR/TCK;
        cas_count <= T_CAS/TCK;
        rtp_count <= T_RTP/TCK;
        rrd_count <= T_RRD/TCK;
      end else if (write_en) begin
        row_addr <= addr[21:10];
        col_addr <= addr[9:0];
        mem[addr] <= data_in;
        state <= WRITE;
        tck_count <= 0;
        rcd_count <= T_RCD/TCK;
        ras_count <= T_RAS/TCK;
        rc_count <= T_RC/TCK;
        wtr_count <= T_WTR/TCK;
        cas_count <= T_CAS/TCK;
        wr_count <= T_WR/TCK;
        rtp_count <= T_RTP/TCK;
        rrd_count <= T_RRD/TCK;
      end
    end
    READ: begin
      if (tck_count == 0) begin
        if (rcd_count > 0) begin
          rcd_count <= rcd_count - 1;
        end else if (ras_count > 0) begin
          ras_count <= ras_count - 1;
        end else if (rc_count > 0) begin
          rc_count <= rc_count - 1;
        end else if (cas_count > 0) begin
          cas_count <= cas_count - 1;
        end else if (rrd_count > 0) begin
          rrd_count <= rrd_count - 1;
        end else begin
          data_reg <= mem[(row_addr << 10) | col_addr];
          state <= IDLE;
        end
      end
      tck_count <= (tck_count + 1) % 2;
    end
    WRITE: begin
      if (tck_count == 0) begin
        if (rcd_count > 0) begin
          rcd_count <= rcd_count - 1;
        end else if (ras_count > 0) begin
          ras_count <= ras_count - 1;
        end else if (rc_count > 0) begin
          rc_count <= rc_count - 1;
        end else if (cas_count > 0) begin
          cas_count <= cas_count - 1;
        end else if (wr_count > 0) begin
          wr_count <= wr_count - 1;
        end else if (rrd_count > 0) begin
          rrd_count <= rrd_count - 1;
        end else begin
          state <= IDLE;
        end
      end
      tck_count <= (tck_count + 1) % 2;
    end
  endcase
end

// Output data register logic
always @(posedge clk) begin
  if (read_en) begin
    data_out <= data_reg;
  end
end

// Memory write logic
always @(posedge clk) begin
  if (write_en) begin
    mem[addr] <= data_in;
  end
end

endmodule

module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout
);

wire [3:0] carry;
wire [3:0] xor_sum;

// First bit
full_adder FA0(A[0], B[0], Cin, Sum[0], carry[0]);
xor (xor_sum[0], A[0], B[0]);

// Second bit
full_adder FA1(A[1], B[1], carry[0], Sum[1], carry[1]);
xor (xor_sum[1], A[1], B[1]);

// Third bit
full_adder FA2(A[2], B[2], carry[1], Sum[2], carry[2]);
xor (xor_sum[2], A[2], B[2]);

// Fourth bit
full_adder FA3(A[3], B[3], carry[2], Sum[3], Cout);
xor (xor_sum[3], A[3], B[3]);

xor (Cout, carry[3], xor_sum[3]);

endmodule

module full_adder (
    input A,
    input B,
    input Cin,
    output Sum,
    output Cout
);

wire carry1;
wire carry2;

// First adder
xor (Sum, A, B);
and (carry1, A, B);

// Second adder
xor (Sum, Sum, Cin);
and (carry2, Sum, Cin);

// Carry-out
or (Cout, carry1, carry2);

endmodule

module vga_sync_generator(
  input clk,
  output vga_h_sync,
  output vga_v_sync,
  output inDisplayArea,
  output reg [10:0] CounterX,
  output reg [10:0] CounterY
);

  // VGA display parameters
  parameter WIDTH = 800;
  parameter HEIGHT = 600;
  parameter COUNT_DOTS = 1056;
  parameter COUNT_LINES = 625;

  parameter H_FRONT_PORCH = 16;
  parameter H_SYNC_PULSE = 80;
  parameter H_BACK_PORCH = 160;

  parameter V_FRONT_PORCH = 1;
  parameter V_SYNC_PULSE = 3;
  parameter V_BACK_PORCH = 21;

  // Horizontal and vertical sync signals
  reg vga_HS, vga_VS;

  // Counter max values
  wire CounterXmaxed = (CounterX == COUNT_DOTS);
  wire CounterYmaxed = (CounterY == COUNT_LINES);

  // Increment counters
  always @(posedge clk) begin
    if (CounterXmaxed) begin
      CounterX <= 0;
      if (CounterYmaxed)
        CounterY <= 0;
      else
        CounterY <= CounterY + 1;
    end
    else
      CounterX <= CounterX + 1;
  end

  // Generate sync signals
  always @(posedge clk) begin
    vga_HS <= (CounterX >= (WIDTH + H_FRONT_PORCH) && CounterX < (WIDTH + H_FRONT_PORCH + H_SYNC_PULSE)); 
    vga_VS <= (CounterY >= (HEIGHT + V_FRONT_PORCH) && CounterY < (HEIGHT + V_FRONT_PORCH + V_SYNC_PULSE)); 
  end

  // Determine if in visible area
  assign inDisplayArea = (CounterX < WIDTH && CounterY < HEIGHT) ? 1'b1 : 1'b0;

  // Output sync signals
  assign vga_h_sync = vga_HS;
  assign vga_v_sync = vga_VS;

endmodule

