always @ (posedge shift_en) begin
    stage4 <= stage3;
    stage3 <= stage2;
    stage2 <= stage1;
    stage1 <= data_in;
end

always @ (posedge load_en) begin
    stage4 <= data_in;
    stage3 <= data_in;
    stage2 <= data_in;
    stage1 <= data_in;
end

assign data_out = stage4;

endmodule

