module usb_fifo_interface (
    input clk,
    input rst_n,
    input usb_fifo_rxf_n,
    input [7:0] usb_fifo_data,
    input usb_fifo_out_ack,
    output reg usb_fifo_rd_n,
    output reg usb_fifo_out_req,
    output reg [7:0] usb_fifo_out_data
);

    // Internal signals
    reg usb_fifo_rxf_n_d1;
    reg usb_fifo_rxf_n_d2;
    reg [7:0] usb_fifo_data_d1;
    reg [7:0] usb_fifo_data_d2;
    reg [2:0] fifo_state;

    // Parameter values
    localparam S_wait_for_rxf = 3'b000;
    localparam S_assert_rd = 3'b001;
    localparam S_data_sync_wait_1 = 3'b010;
    localparam S_data_sync_wait_2 = 3'b011;
    localparam S_capture_data = 3'b100;
    localparam S_wait_rxf_sync_flush_1 = 3'b101;
    localparam S_wait_rxf_sync_flush_2 = 3'b110;

    // Synchronize usb_fifo_rxf_n into main clk domain
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            usb_fifo_rxf_n_d1 <= 1'b1;
            usb_fifo_rxf_n_d2 <= 1'b1;
            usb_fifo_data_d1 <= 8'b0;
            usb_fifo_data_d2 <= 8'b0;
        end
        else begin
            usb_fifo_rxf_n_d1 <= usb_fifo_rxf_n;
            usb_fifo_rxf_n_d2 <= usb_fifo_rxf_n_d1;
            usb_fifo_data_d1 <= usb_fifo_data;
            usb_fifo_data_d2 <= usb_fifo_data_d1;
        end
    end

    // Main state machine
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            fifo_state <= S_wait_for_rxf;
        end
        else begin
            case (fifo_state)
                S_wait_for_rxf: begin
                    if (!usb_fifo_rxf_n_d2) begin
                        fifo_state <= S_assert_rd;
                    end
                end
                S_assert_rd: begin
                    fifo_state <= S_data_sync_wait_1;
                end
                S_data_sync_wait_1: begin
                    fifo_state <= S_data_sync_wait_2;
                end
                S_data_sync_wait_2: begin
                    fifo_state <= S_capture_data;
                end
                S_capture_data: begin
                    if (usb_fifo_out_ack) begin
                        fifo_state <= S_wait_rxf_sync_flush_1;
                    end
                end
                S_wait_rxf_sync_flush_1: begin
                    fifo_state <= S_wait_rxf_sync_flush_2;
                end
                S_wait_rxf_sync_flush_2: begin
                    fifo_state <= S_wait_for_rxf;
                end
            endcase
        end
    end

    // Drive usb_fifo_rd_n
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            usb_fifo_rd_n <= 1'b1;
        end
        else begin
            case (fifo_state)
                S_wait_for_rxf: begin
                    if (!usb_fifo_rxf_n_d2) begin
                        usb_fifo_rd_n <= 1'b0;
                    end
                end
                S_capture_data: begin
                    if (usb_fifo_out_ack) begin
                        usb_fifo_rd_n <= 1'b1;
                    end
                end
            endcase
        end
    end

    // Drive usb_fifo_out_req and usb_fifo_out_data
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            usb_fifo_out_req <= 1'b0;
            usb_fifo_out_data <= 8'b0;
        end
        else begin
            case (fifo_state)
                S_capture_data: begin
                    if (usb_fifo_out_ack) begin
                        usb_fifo_out_req <= 1'b1;
                        usb_fifo_out_data <= usb_fifo_data_d2;
                    end
                end
            endcase
        end
    end

endmodule

module add_sub_4bit (
  input [3:0] A,
  input [3:0] B,
  input M,
  input CLK,
  input RST,
