module accumulator_system (
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,
    input               select      , // Select input to choose between accu and top_module
    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [11:0]  data_out
);

    // Instantiate accu module
    accu accu_inst (
        .clk(clk),
        .rst_n(rst_n),
        .data_in(data_in),
        .valid_in(valid_a),
        .ready_out(),
        .valid_out(),
        .data_out()
    );

    // Instantiate top_module module
    top_module top_inst (
        .clk(clk),
        .rst_n(rst_n),
        .count_out(),
        .ready_out(),
        .valid_out(),
        .data_out()
    );

    // Counter logic
    reg [3:0] counter;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            counter <= 4'b0;
        end else begin
            if (counter == 4'b1111) begin
                counter <= 4'b0;
            end else begin
                counter <= counter + 1;
            end
        end
    end

    // Pipeline register for accumulator output
    reg [11:0] accu_out_reg;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            accu_out_reg <= 12'b0;
        end else begin
            if (valid_a && ready_b) begin
                accu_out_reg <= accu_out_reg + data_in;
            end
        end
    end

    // Final output logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            valid_b <= 1'b0;
            data_out <= 12'b0;
        end else begin
            if (select) begin
                if (valid_a && ready_b) begin
                    valid_b <= 1'b1;
                    data_out <= accu_out_reg;
                end else begin
                    valid_b <= 1'b0;
                    data_out <= 12'b0;
                end
            end else begin
                if (top_inst.valid_out && valid_a && ready_b) begin
                    valid_b <= 1'b1;
                    data_out <= accu_out_reg + top_inst.data_out;
                end else begin
                    valid_b <= 1'b0;
                    data_out <= 12'b0;
                end
            end
        end
    end

    // Ready signals
    assign ready_a = (select) ? accu_inst.ready_out : top_inst.ready_out;

endmodule

module top_module (
    input clk,
    input reset,
    input [7:0] in,
    output reg [2:0] pos
);

reg [7:0] in_reg;
reg [7:0] in_reg_prev;
reg [2:0] pos_reg;

// Binary edge detector module
reg [2:0] edge_pos;
reg [2:0] edge_pos_reg;
reg [7:0] edge_count;

always @(posedge clk) begin
    if (reset) begin
        in_reg <= 0;
        in_reg_prev <= 0;
        pos_reg <= 0;
        edge_pos_reg <= 0;
        edge_count <= 0;
    end else begin
        in_reg <= in;
        in_reg_prev <= in_reg;
        pos_reg <= pos;
        edge_pos_reg <= edge_pos;
        edge_count <= (in_reg != in_reg_prev) ? 1 : edge_count + 1;
        if (edge_count == 1) begin
            edge_pos <= 0;
            if (in_reg[7]) edge_pos <= 7;
            if (in_reg[6]) edge_pos <= 6;
            if (in_reg[5]) edge_pos <= 5;
            if (in_reg[4]) edge_pos <= 4;
            if (in_reg[3]) edge_pos <= 3;
            if (in_reg[2]) edge_pos <= 2;
            if (in_reg[1]) edge_pos <= 1;
            if (in_reg[0]) edge_pos <= 0;
        end
    end
end

// Priority encoder module
always @* begin
    case (edge_pos_reg)
        3'b000: pos_reg <= 3'b000;
        3'b001: pos_reg <= 3'b001;
        3'b010: pos_reg <= 3'b010;
        3'b011: pos_reg <= 3'b011;
        3'b100: pos_reg <= 3'b100;
        3'b101: pos_reg <= 3'b101;
        3'b110: pos_reg <= 3'b110;
        3'b111: pos_reg <= 3'b111;
        default: pos_reg <= pos_reg;
    endcase
end

// Final output module
always @(posedge clk) begin
    if (reset) begin
        pos <= 0;
    end else begin
        pos <= pos_reg;
    end
end

endmodule

