reg [9:0] acc_reg;

always @(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        data_reg <= 8'b0;
        acc_reg <= 10'b0;
        valid_b <= 1'b0;
    end
    else begin
        data_reg <= valid_a ? data_in : data_reg;
        acc_reg <= acc_reg + data_reg;
        valid_b <= valid_a;
    end
end

assign ready_a = !valid_b || ready_b;

always @(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        data_out <= 10'b0;
    end
    else if(valid_b && ready_a) begin
        data_out <= acc_reg;
    end
end

