    output [4:0] usedw,
    input wreq
    );

    reg [31:0] mem [15:0];
    reg [4:0] wr_ptr = 0;
    reg [4:0] rd_ptr = 0;
    reg [4:0] wr_cnt = 0;
    reg [4:0] rd_cnt = 0;
    reg [4:0] usedw_reg = 0;
    wire [4:0] wr_ptr_next = wr_ptr + 1;
    wire [4:0] rd_ptr_next = rd_ptr + 1;

