module accumulator(
    input               clk         ,   
    input               reset       ,
    input       [7:0]   data_in     ,
    input               valid_in    ,
    output              ready_out   ,
    output  reg         valid_out   ,
    output  reg [9:0]   data_out
);

    reg [9:0] accumulator = 0;
    reg [2:0] count = 0;
    wire [9:0] multiplied_data;
    multiplier multiplier_inst(
        .in_data(accumulator + data_in),
        .out_data(multiplied_data)
    );

    always @(posedge clk) begin
        if (reset) begin
            accumulator <= 0;
            count <= 0;
            valid_out <= 0;
            data_out <= 0;
        end else begin
            if (valid_in) begin
                accumulator <= accumulator + data_in;
                count <= count + 1;
                if (count == 7) begin
                    data_out <= multiplied_data;
                    valid_out <= 1;
                    count <= 0;
                end
            end
            if (ready_out && valid_out) begin
                valid_out <= 0;
                data_out <= 0;
            end
        end
    end

endmodule

