module ECC_memory_block (
  input wire [w-1:0] data_in,
  input wire write_en,
  input wire reset,
  output reg [w-1:0] data_out,
  output reg [p-1:0] parity
);

parameter p = 2; // number of parity bits

parameter w = 8; // data width

reg [w+p-1:0] memory; // memory block with ECC bits

// compute parity bits using Hamming code
function [p-1:0] hamming_code;
  input [w-1:0] data;
  reg [p-1:0] parity_bits;
  integer i, j, k;
  begin
    for (i = 0; i < p; i = i + 1) begin
      parity_bits[i] = 0;
      k = 1 << i;
      for (j = 0; j < w; j = j + 1) begin
        if ((j+1) & k) begin
          parity_bits[i] = parity_bits[i] ^ data[j];
        end
      end
    end
    hamming_code = parity_bits;
  end
endfunction

// compute syndrome for error correction
function [p-1:0] syndrome;
  input [w+p-1:0] data;
  reg [p-1:0] syndrome_bits;
  integer i, j, k;
  begin
    for (i = 0; i < p; i = i + 1) begin
      syndrome_bits[i] = 0;
      k = 1 << i;
      for (j = 0; j < w+p; j = j + 1) begin
        if ((j+1) & k) begin
          syndrome_bits[i] = syndrome_bits[i] ^ data[j];
        end
      end
    end
    syndrome = syndrome_bits;
  end
endfunction

// write data to memory block with ECC
always @(posedge write_en) begin
  if (reset) begin
    memory <= {w+p{1'b0}};
  end else begin
    memory <= {data_in, hamming_code(data_in)};
  end
end

// read data from memory block with ECC
always @(posedge write_en or posedge reset) begin
  if (reset) begin
    data_out <= {w{1'b0}};
    parity <= {p{1'b0}};
  end else begin
    data_out <= memory[0:w-1];
    parity <= syndrome(memory);
    if (parity != {p{1'b0}}) begin
      // correct single-bit error using syndrome
      memory[parity] <= ~memory[parity];
    end
  end
end

endmodule

