module vending_machine_controller(
  input clk,
  input reset,
  input [1:0] coin,
  input item,
  output reg [5:0] price,
  output reg dispense,
  output reg [5:0] change,
  output reg [3:0] stock_candy,
  output reg [3:0] stock_chips
);

  // Constants
  parameter CANDY_PRICE = 50;
  parameter CHIPS_PRICE = 75;
  parameter MAX_STOCK = 10;

  // Registers
  reg [5:0] total_inserted;
  reg [5:0] amount_due;
  reg [5:0] amount_change;
  reg [3:0] stock_candy_reg;
  reg [3:0] stock_chips_reg;

  // Combinational logic
  assign price = item ? CHIPS_PRICE : CANDY_PRICE;
  assign dispense = (amount_due == 0) && (item ? stock_chips_reg : stock_candy_reg) > 0;
  assign change = amount_change;

  // Sequential logic
  always @(posedge clk) begin
    if (reset) begin
      total_inserted <= 0;
      amount_due <= 0;
      amount_change <= 0;
      stock_candy_reg <= MAX_STOCK;
      stock_chips_reg <= MAX_STOCK;
    end else begin
      // Update total inserted
      case (coin)
        2'b01: total_inserted <= total_inserted + 5;
        2'b10: total_inserted <= total_inserted + 10;
        2'b11: total_inserted <= total_inserted + 25;
      endcase

      // Update amount due
      if (item) begin
        amount_due <= CHIPS_PRICE;
      end else begin
        amount_due <= CANDY_PRICE;
      end

      // Dispense item and calculate change
      if (dispense) begin
        if (total_inserted >= amount_due) begin
          amount_change <= total_inserted - amount_due;
          total_inserted <= 0;
          if (item) begin
            stock_chips_reg <= stock_chips_reg - 1;
          end else begin
            stock_candy_reg <= stock_candy_reg - 1;
          end
        end else begin
          amount_change <= 0;
        end
      end
    end
  end

  // Assign outputs
  assign stock_candy = stock_candy_reg;
  assign stock_chips = stock_chips_reg;

endmodule

module top_module (
    input clk,
    input reset, // Synchronous active-high reset
    input [99:0] a, b, // Inputs for the carry-lookahead adder
    input cin, // Carry-in bit for the carry-lookahead adder
    input select, // Select input to choose between the adder and counter
    output [3:1] ena, // Enable signals for the upper three digits of the counter
    output [15:0] q // 16-bit BCD output from the counter and final output from the functional module
);

    // Define internal wires and registers
    wire [99:0] sum; // Output from the carry-lookahead adder
    wire cout; // Carry-out bit from the carry-lookahead adder
    wire [15:0] bcd_out; // Output from the BCD counter
    reg [15:0] final_out; // Final output from the functional module
    reg [3:1] ena_reg; // Register for the enable signals of the counter

    // Instantiate the carry-lookahead adder
    carry_lookahead_adder adder_inst (
        .a(a),
        .b(b),
        .cin(cin),
        .sum(sum),
        .cout(cout)
    );

    // Instantiate the BCD counter
    bcd_counter counter_inst (
        .clk(clk),
        .reset(reset),
        .bcd_out(bcd_out)
    );

    // Define the control logic for selecting between the adder and counter
    always @ (posedge clk) begin
        if (reset) begin
            ena_reg <= 3'b000;
            final_out <= 16'b0;
        end else begin
            if (select) begin
                ena_reg <= 3'b000;
                final_out <= {12'b0, bcd_out};
            end else begin
                ena_reg <= 3'b111;
                final_out <= {12'b0, sum};
            end
        end
    end

    // Assign the outputs
    assign ena = ena_reg;
    assign q = final_out;

endmodule

// Define the carry-lookahead adder module
module carry_lookahead_adder (
    input [99:0] a, b, // Inputs
    input cin, // Carry-in bit
    output [99:0] sum, // Output sum
    output cout // Carry-out bit
);

    // Define internal wires and registers
    wire [99:0] p, g; // Propagate and generate signals
    wire [99:0] c; // Carry signals
    reg [99:0] sum_reg; // Register for the sum output
    reg cout_reg; // Register for the carry-out bit

    // Generate the propagate and generate signals
    generate
        genvar i;
        for (i = 0; i < 100; i = i + 1) begin
            assign p[i] = a[i] ^ b[i];
            assign g[i] = a[i] & b[i];
        end
    endgenerate

    // Generate the carry signals
    generate
        genvar i;
        assign c[0] = cin;
        for (i = 1; i < 100; i = i + 1) begin
            assign c[i] = g[i-1] | (p[i-1] & c[i-1]);
        end
    endgenerate

    // Generate the sum output and carry-out bit
    always @ (*) begin
        sum_reg = a + b + cin;
        cout_reg = c[99];
    end

    // Assign the outputs
    assign sum = sum_reg;
    assign cout = cout_reg;

endmodule

// Define the BCD counter module
module bcd_counter (
    input clk, // Clock input
    input reset, // Synchronous active-high reset
    output reg [15:0] bcd_out // BCD output
);

    // Define internal wires and registers
    wire [3:0] binary_out; // Output from the binary counter
    reg [3:0] count_reg; // Register for the counter value

    // Define the combinational circuit for encoding binary to BCD
    always @ (*) begin
        case (count_reg)
            4'b0000: bcd_out = 4'b0000;
            4'b0001: bcd_out = 4'b0001;
            4'b0010: bcd_out = 4'b0010;
            4'b0011: bcd_out = 4'b0011;
            4'b0100: bcd_out = 4'b0100;
            4'b0101: bcd_out = 4'b0101;
            4'b0110: bcd_out = 4'b0110;
            4'b0111: bcd_out = 4'b0111;
            4'b1000: bcd_out = 4'b1000;
            4'b1001: bcd_out = 4'b1001;
            4'b1010: bcd_out = 4'b0001;
            4'b1011: bcd_out = 4'b0010;
            4'b1100: bcd_out = 4'b0011;
            4'b1101: bcd_out = 4'b0100;
            4'b1110: bcd_out = 4'b0101;
            4'b1111: bcd_out = 4'b0110;
        endcase
    end

    // Instantiate the binary counter
    binary_counter counter_inst (
        .clk(clk),
        .reset(reset),
        .binary_out(binary_out)
    );

    // Update the counter value based on the binary output
    always @ (posedge clk) begin
        if (reset) begin
            count_reg <= 4'b0000;
        end else begin
            case (binary_out)
                4'b0000: count_reg <= 4'b0001;
                4'b0001: count_reg <= 4'b0010;
                4'b0010: count_reg <= 4'b0011;
                4'b0011: count_reg <= 4'b0100;
                4'b0100: count_reg <= 4'b0101;
                4'b0101: count_reg <= 4'b0110;
                4'b0110: count_reg <= 4'b0111;
                4'b0111: count_reg <= 4'b1000;
                4'b1000: count_reg <= 4'b1001;
                4'b1001: count_reg <= 4'b0000;
            endcase
        end
    end

