// Define the binary counter module
module binary_counter (
    input clk, // Clock input
    input reset, // Synchronous active-high reset
    output reg [3:0] binary_out // Binary output
);

    // Define internal wires and registers
    reg [3:0] count_reg; // Register for the counter value

    // Increment the counter value on each clock cycle
    always @ (posedge clk) begin
        if (reset) begin
            count_reg <= 4'b0000;
        end else begin
            count_reg <= count_reg + 1;
        end
    end

    // Assign the binary output
    assign binary_out = count_reg;

endmodule

module top_module (
    input clk,
    input [31:0] in,
    output reg out
);

    reg [7:0] byte0, byte1, byte2, byte3;
    reg [31:0] reversed;
    reg [7:0] temp;
    reg [7:0] dff_out [0:7];
    wire xor_out;

    // Byte Reverser
    assign byte0 = in[7:0];
    assign byte1 = in[15:8];
    assign byte2 = in[23:16];
    assign byte3 = in[31:24];

    always @(*) begin
        reversed = {byte3, byte2, byte1, byte0};
    end

    // D Flip-Flop Chain
    always @(negedge clk) begin
        dff_out[0] <= in[0];
        dff_out[1] <= dff_out[0];
        dff_out[2] <= dff_out[1];
        dff_out[3] <= dff_out[2];
        dff_out[4] <= dff_out[3];
        dff_out[5] <= dff_out[4];
        dff_out[6] <= dff_out[5];
        dff_out[7] <= dff_out[6];
    end

    // XOR Module
    assign xor_out = dff_out[7] ^ reversed[0];

    // Output
    always @(*) begin
        out = xor_out;
    end

endmodule

