module vending_machine (
    input clk,
    input reset,
    input quarter,
    input dime,
    input nickel,
    input soda_button,
    input chips_button,
    input candy_button,
    output reg dispense,
    output reg soda_dispense,
    output reg chips_dispense,
    output reg candy_dispense,
    output reg change,
    output reg [1:0] quarters_out,
    output reg [1:0] dimes_out,
    output reg [1:0] nickels_out,
    output reg soda_led,
    output reg chips_led,
    output reg candy_led,
    output reg [5:0] price_led
);

// Define states
localparam IDLE = 2'b00;
localparam SODA_SELECTED = 2'b01;
localparam CHIPS_SELECTED = 2'b10;
localparam CANDY_SELECTED = 2'b11;

// Define prices
localparam SODA_PRICE = 6'b011101;
localparam CHIPS_PRICE = 6'b010000;
localparam CANDY_PRICE = 6'b001001;

// Define constants
localparam QUARTER_VALUE = 2'b01;
localparam DIME_VALUE = 2'b10;
localparam NICKEL_VALUE = 2'b11;

// Define registers
reg [1:0] state;
reg [5:0] price;
reg [1:0] quarters_in;
reg [1:0] dimes_in;
reg [1:0] nickels_in;
reg [1:0] change_out;

// Define combinational logic
assign dispense = (soda_dispense || chips_dispense || candy_dispense) || change;
assign quarters_out = change_out[3:2];
assign dimes_out = change_out[1:0];
assign nickels_out = change_out[5:4];

// Define state machine
always @(posedge clk) begin
    if (reset) begin
        state <= IDLE;
        price <= 6'b000000;
        quarters_in <= 2'b00;
        dimes_in <= 2'b00;
        nickels_in <= 2'b00;
        change_out <= 2'b00;
        soda_led <= 1'b0;
        chips_led <= 1'b0;
        candy_led <= 1'b0;
        price_led <= 6'b000000;
    end
    else begin
        case (state)
            IDLE: begin
                if (soda_button) begin
                    state <= SODA_SELECTED;
                    price <= SODA_PRICE;
                    soda_led <= 1'b1;
                    chips_led <= 1'b0;
                    candy_led <= 1'b0;
                    price_led <= SODA_PRICE;
                end
                else if (chips_button) begin
                    state <= CHIPS_SELECTED;
                    price <= CHIPS_PRICE;
                    soda_led <= 1'b0;
                    chips_led <= 1'b1;
                    candy_led <= 1'b0;
                    price_led <= CHIPS_PRICE;
                end
                else if (candy_button) begin
                    state <= CANDY_SELECTED;
                    price <= CANDY_PRICE;
                    soda_led <= 1'b0;
                    chips_led <= 1'b0;
                    candy_led <= 1'b1;
                    price_led <= CANDY_PRICE;
                end
                else begin
                    soda_led <= 1'b0;
                    chips_led <= 1'b0;
                    candy_led <= 1'b0;
                end
            end
            SODA_SELECTED: begin
                if (quarter) quarters_in <= quarters_in + QUARTER_VALUE;
                if (dime) dimes_in <= dimes_in + DIME_VALUE;
                if (nickel) nickels_in <= nickels_in + NICKEL_VALUE;
                if ((quarters_in*25 + dimes_in*10 + nickels_in*5) >= price) begin
                    soda_dispense <= 1'b1;
                    change_out <= (quarters_in*25 + dimes_in*10 + nickels_in*5) - price;
                    quarters_in <= 2'b00;
                    dimes_in <= 2'b00;
                    nickels_in <= 2'b00;
                    state <= IDLE;
                end
            end
            CHIPS_SELECTED: begin
                if (quarter) quarters_in <= quarters_in + QUARTER_VALUE;
                if (dime) dimes_in <= dimes_in + DIME_VALUE;
                if (nickel) nickels_in <= nickels_in + NICKEL_VALUE;
                if ((quarters_in*25 + dimes_in*10 + nickels_in*5) >= price) begin
                    chips_dispense <= 1'b1;
                    change_out <= (quarters_in*25 + dimes_in*10 + nickels_in*5) - price;
                    quarters_in <= 2'b00;
                    dimes_in <= 2'b00;
                    nickels_in <= 2'b00;
                    state <= IDLE;
                end
            end
            CANDY_SELECTED: begin
                if (quarter) quarters_in <= quarters_in + QUARTER_VALUE;
                if (dime) dimes_in <= dimes_in + DIME_VALUE;
                if (nickel) nickels_in <= nickels_in + NICKEL_VALUE;
                if ((quarters_in*25 + dimes_in*10 + nickels_in*5) >= price) begin
                    candy_dispense <= 1'b1;
                    change_out <= (quarters_in*25 + dimes_in*10 + nickels_in*5) - price;
                    quarters_in <= 2'b00;
                    dimes_in <= 2'b00;
                    nickels_in <= 2'b00;
                    state <= IDLE;
                end
            end
        endcase
    end
end

endmodule

