  end else if (counter < delay) begin
    rst_out_reg <= 1;
    counter <= counter + 1;
  end else begin
    rst_out_reg <= rst_in;
    counter <= 0;
  end
end

assign rst_out = rst_out_reg;

endmodule

module bw_r_idct(
