    always @(posedge clk or posedge reset) begin
        if (reset) begin
            r <= 0;
            l <= 0;
        end else begin
            if (in) begin
                r <= 1;
                l <= 1;
            end else if (p) begin
                r <= 0;
                l <= 0;
