module binary_multiplier (
    input [7:0] A,
    input [7:0] B,
    output reg [15:0] product
);

integer i, j;

always @(*) begin
    product = 0;
    for (i = 0; i < 8; i = i + 1) begin
        for (j = 0; j < 8; j = j + 1) begin
            if (i + j < 8) begin
                product[i+j] = product[i+j] + A[i] * B[j];
            end
        end
    end
end

endmodule

module gray_code (
    input [7:0] binary_in,
    output reg [7:0] gray_out
);

always @(*) begin
    gray_out = binary_in ^ (binary_in >> 1);
end

