module top_module (
    input clk,
    input reset, // Synchronous active-high reset
    input [7:0] d, // 8-bit input for the register
    input select, // Select input to choose between register and counter
    output [7:0] q, // 8-bit output from the active module
    output [3:0] counter_q, // 4-bit output from the counter
    output [7:0] xor_out // 8-bit output from the XOR module
);

    reg [7:0] reg_out;
    reg [3:0] counter_out;
    reg [7:0] xor_out_reg;

    // Register module
    always @(posedge clk) begin
        if (reset) begin
            reg_out <= 8'h34;
        end else begin
            reg_out <= d;
        end
    end

    // Counter module
    always @(posedge clk) begin
        if (reset) begin
            counter_out <= 4'b0;
        end else begin
            if (select) begin
                counter_out <= counter_out + 1;
            end
        end
    end

    // Control logic module
    always @(posedge clk) begin
        if (reset) begin
            xor_out_reg <= 8'b0;
        end else begin
            if (select) begin
                xor_out_reg <= {8{counter_out[3]}};
            end else begin
                xor_out_reg <= reg_out;
            end
        end
    end

    // Barrel shifter module for XOR
    always @(*) begin
        case (counter_out)
            4'b0000: xor_out = xor_out_reg;
            4'b0001: xor_out = {xor_out_reg[6:0], xor_out_reg[7]};
            4'b0010: xor_out = {xor_out_reg[5:0], xor_out_reg[7:6]};
            4'b0011: xor_out = {xor_out_reg[4:0], xor_out_reg[7:5]};
            4'b0100: xor_out = {xor_out_reg[3:0], xor_out_reg[7:4]};
            4'b0101: xor_out = {xor_out_reg[2:0], xor_out_reg[7:3]};
            4'b0110: xor_out = {xor_out_reg[1:0], xor_out_reg[7:2]};
            4'b0111: xor_out = {xor_out_reg[0], xor_out_reg[7:1]};
            4'b1000: xor_out = {8{counter_out[3]}};
            default: xor_out = 8'b0;
        endcase
    end

    assign q = select ? counter_out : reg_out;
    assign counter_q = counter_out;

endmodule

module decoder (
    input [3:0] in,
    output [15:0] out
);

