endmodule

module mux4to1_lut (O, I0, I1, I2, I3, S0, S1);

  output O;
  input I0, I1, I2, I3, S0, S1;

  wire w0, w1, w2, w3, w4, w5, w6, w7;

  x_lut4 #(.INIT(16'hF0F0)) lut0 (.O(w0), .I0(I0), .I1(I1), .I2(I2), .I3(I3));
  x_lut2 #(.INIT(4'h6))   lut1 (.O(w1), .I0(S0), .I1(~S0));
  x_lut2 #(.INIT(4'h5))   lut2 (.O(w2), .I0(S1), .I1(~S1));
  and #(.INIT(1'b1))      and0 (.O(w3), .I0(w1), .I1(w2));
  xor #(.INIT(1'b0))      xor0 (.O(w4), .I0(w1), .I1(w2));
  xor #(.INIT(1'b0))      xor1 (.O(w5), .I0(w0), .I1(w4));
  and #(.INIT(1'b1))      and1 (.O(w6), .I0(w0), .I1(w4));
  or  #(.INIT(1'b0))      or0  (.O(O), .I0(w5), .I1(w6));

endmodule

module top_module ( 
    input clk, 
    input reset, // Synchronous active-high reset 
    input [15:0] in, // 16-bit input 
    input select, // Select input to choose between register and counter 
    output reg [7:0] result // 8-bit output from the addition functional module 
);

reg [7:0] upper_byte; // Register for storing the upper byte of the input 
reg [7:0] lower_byte; // Register for storing the lower byte of the input 
reg [3:0] counter; // Counter for adding the upper and lower bytes 

// Register module with active high synchronous reset 
reg_module reg_inst (
    .clk(clk),
    .reset(reset),
    .in(in[15:8]), // Input is the upper byte of the input 
    .out(upper_byte)
);

// Counter module with synchronous reset 
counter_module counter_inst (
    .clk(clk),
    .reset(reset),
    .out(counter)
);

// Multiplexer to select between the register and the counter 
assign result = select ? (upper_byte + lower_byte) : (upper_byte + counter);

// Decoder to select between the upper and lower bytes of the input 
assign lower_byte = in[7:0];
assign upper_byte = in[15:8];

