module test_PLLE4_BASE;

  // Parameters
  localparam CLK_PERIOD = 10; // ns
  localparam TOLERANCE = 0.1; // ns

  // Inputs
  reg clk;
  reg rst;

  // Outputs
  wire locked;
  wire clkfbout;
  wire clkout0;
  wire clkout0b;
  wire clkout1;
  wire clkout1b;
  wire clkoutphy;

  // Instantiate the module
  PLLE4_BASE #(
    .CLKFBOUT_MULT(10),
    .CLKFBOUT_PHASE(0.000),
    .CLKIN_PERIOD(CLK_PERIOD),
    .CLKOUT0_DIVIDE(2),
    .CLKOUT0_DUTY_CYCLE(0.500),
    .CLKOUT0_PHASE(0.000),
    .CLKOUT1_DIVIDE(5),
    .CLKOUT1_DUTY_CYCLE(0.500),
    .CLKOUT1_PHASE(0.000),
    .CLKOUTPHY_MODE("VCO_2X"),
    .DIVCLK_DIVIDE(1),
    .IS_CLKFBIN_INVERTED(1'b0),
    .IS_CLKIN_INVERTED(1'b0),
    .IS_PWRDWN_INVERTED(1'b0),
    .IS_RST_INVERTED(1'b0),
    .REF_JITTER(0.010),
    .STARTUP_WAIT("FALSE")
  ) dut (
    .CLKFBOUT(clkfbout),
    .CLKOUT0(clkout0),
    .CLKOUT0B(clkout0b),
    .CLKOUT1(clkout1),
    .CLKOUT1B(clkout1b),
    .CLKOUTPHY(clkoutphy),
    .LOCKED(locked),
    .CLKFBIN(clkfbout),
    .CLKIN(clk),
    .CLKOUTPHYEN(1'b1),
    .PWRDWN(1'b0),
    .RST(rst)
  );

  // Clock generation
  always #5 clk = ~clk;

  // Reset generation
  initial begin
    rst = 1;
    #10 rst = 0;
  end

  // Check that the PLL locks correctly
  always @(posedge clk) begin
    if (!locked) begin
      $display("Error: PLL did not lock");
      $finish;
    end
  end

  // Check that the output clocks have the expected frequency and phase
  always @(posedge clk) begin
    if (abs($period(clkfbout) - CLK_PERIOD/10) > TOLERANCE) begin
      $display("Error: CLKFBOUT period is %0.3f ns (expected %0.3f ns)", $period(clkfbout), CLK_PERIOD/10);
      $finish;
    end
    if (abs($period(clkout0) - 2*CLK_PERIOD) > TOLERANCE) begin
      $display("Error: CLKOUT0 period is %0.3f ns (expected %0.3f ns)", $period(clkout0), 2*CLK_PERIOD);
      $finish;
    end
    if (abs($period(clkout1) - 5*CLK_PERIOD) > TOLERANCE) begin
      $display("Error: CLKOUT1 period is %0.3f ns (expected %0.3f ns)", $period(clkout1), 5*CLK_PERIOD);
      $finish;
    end
    if (abs($phase(clkout0, clkout1) - 180) > TOLERANCE) begin
      $display("Error: CLKOUT0 and CLKOUT1 are not 180 degrees out of phase");
      $finish;
    end
  end

endmodule

