module calculator (
    clk,
    nrst,
    op_code,
    num1,
    num2,
    result,
    valid
);

input clk;
input nrst;
input [1:0] op_code;
input [7:0] num1;
input [7:0] num2;

output [7:0] result;
output valid;

reg [7:0] result_reg;
reg valid_reg;

always @(posedge clk) begin
    if (nrst == 0) begin
        result_reg <= 0;
        valid_reg <= 0;
    end else begin
        case (op_code)
            2'b00: result_reg <= num1 + num2; // addition
            2'b01: result_reg <= num1 - num2; // subtraction
            2'b10: result_reg <= num1 * num2; // multiplication
            2'b11: begin // division
                if (num2 == 0) begin
                    result_reg <= 0;
                    valid_reg <= 0;
                end else begin
                    result_reg <= num1 / num2;
                    valid_reg <= 1;
                end
            end
        endcase
    end
end

assign result = result_reg;
assign valid = valid_reg;

endmodule

module simple_calculator(
    input [3:0] A,
    input [3:0] B,
    input [2:0] OP,
    output reg [3:0] RESULT
);

    always @(*) begin
        case(OP)
            3'b000: RESULT = A + B; // addition
            3'b001: RESULT = A - B; // subtraction
            3'b010: RESULT = A * B; // multiplication
            3'b011: RESULT = A / B; // division
            default: RESULT = 4'b0000; // default to zero
        endcase
    end

    always @(A, B, OP) begin
        case(OP)
            3'b000: // addition
                if((A[3] & B[3]) | ((A[3] ^ B[3]) & (RESULT[3] == 1))) begin
                    // overflow condition
                    RESULT[3:0] = 4'b1111;
                end else if((A[3] ^ B[3]) & (RESULT[3] == 0)) begin
                    // underflow condition
                    RESULT[3:0] = 4'b0000;
                end
            3'b001: // subtraction
                if((A[3] ^ B[3]) & (RESULT[3] == 1)) begin
                    // overflow condition
                    RESULT[3:0] = 4'b1111;
                end else if((A[3] & B[3]) | ((A[3] ^ B[3]) & (RESULT[3] == 0))) begin
                    // underflow condition
                    RESULT[3:0] = 4'b0000;
                end
            3'b011: // division
                if(B == 4'b0000) begin
                    // division by zero
                    RESULT[3:0] = 4'b0000;
                end else begin
                    RESULT[3:0] = A / B;
                end
        endcase
    end

endmodule

module PmodDA1Interface
   (Pmod_out_pin1,
    Pmod_out_pin2,
    Pmod_out_pin3,
    Pmod_out_pin4,
    Pmod_out_pin7,
    Pmod_out_pin8,
    Pmod_out_pin9,
    Pmod_out_pin10,
    ext_spi_clk,
    s_axi_aclk,
    s_axi_aresetn,
    AXI_LITE_SPI_araddr,
    AXI_LITE_SPI_arvalid,
    AXI_LITE_SPI_awaddr,
    AXI_LITE_SPI_awvalid,
    AXI_LITE_SPI_bready,
    AXI_LITE_SPI_rready,
    AXI_LITE_SPI_wdata,
    AXI_LITE_SPI_wstrb,
    AXI_LITE_SPI_wvalid);

    input ext_spi_clk;
    input s_axi_aclk;
    input s_axi_aresetn;
    input [6:0] AXI_LITE_SPI_araddr;
    input AXI_LITE_SPI_arvalid;
    input [6:0] AXI_LITE_SPI_awaddr;
    input AXI_LITE_SPI_awvalid;
    input AXI_LITE_SPI_bready;
    input AXI_LITE_SPI_rready;
    input [31:0] AXI_LITE_SPI_wdata;
    input [3:0] AXI_LITE_SPI_wstrb;
    input AXI_LITE_SPI_wvalid;
    output reg Pmod_out_pin1;
    output reg Pmod_out_pin2;
    output reg Pmod_out_pin3;
    output reg Pmod_out_pin4;
    output reg Pmod_out_pin7;
    output reg Pmod_out_pin8;
    output reg Pmod_out_pin9;
    output reg Pmod_out_pin10;
    output reg AXI_LITE_SPI_arready;
    output reg AXI_LITE_SPI_awready;
    output reg [1:0] AXI_LITE_SPI_bresp;
    output reg AXI_LITE_SPI_bvalid;
    input [31:0] AXI_LITE_SPI_rdata;
    output reg [1:0] AXI_LITE_SPI_rresp;
    output reg AXI_LITE_SPI_rvalid;
    reg [31:0] data_out;
    reg [31:0] data_in;
    reg [1:0] resp;
    reg [2:0] state;
    wire [31:0] data;

    assign data = (state == 0) ? 32'h00000000 :
                  (state == 1) ? data_out :
                  (state == 2) ? data_in :
                  32'h00000000;

    always @(posedge s_axi_aclk) begin
        if (!s_axi_aresetn) begin
            state <= 0;
            Pmod_out_pin1 <= 0;
            Pmod_out_pin2 <= 0;
            Pmod_out_pin3 <= 0;
            Pmod_out_pin4 <= 0;
            Pmod_out_pin7 <= 0;
            Pmod_out_pin8 <= 0;
            Pmod_out_pin9 <= 0;
            Pmod_out_pin10 <= 0;
            AXI_LITE_SPI_arready <= 0;
            AXI_LITE_SPI_awready <= 0;
            AXI_LITE_SPI_bresp <= 2'b00;
            AXI_LITE_SPI_bvalid <= 0;
            AXI_LITE_SPI_rresp <= 2'b00;
            AXI_LITE_SPI_rvalid <= 0;
        end else begin
            case (state)
                0: begin
                    if (AXI_LITE_SPI_arvalid) begin
                        AXI_LITE_SPI_arready <= 1;
                        state <= 1;
                    end else if (AXI_LITE_SPI_awvalid) begin
                        AXI_LITE_SPI_awready <= 1;
                        state <= 1;
                    end
                end
                1: begin
                    if (AXI_LITE_SPI_wvalid) begin
                        data_out <= AXI_LITE_SPI_wdata;
                        state <= 0;
                        AXI_LITE_SPI_awready <= 0;
                        AXI_LITE_SPI_bresp <= 2'b00;
                        AXI_LITE_SPI_bvalid <= 1;
                    end else begin
                        state <= 2;
                    end
                end
                2: begin
                    if (AXI_LITE_SPI_rready) begin
                        data_in <= AXI_LITE_SPI_rdata;
                        resp <= AXI_LITE_SPI_rresp;
                        state <= 0;
                        AXI_LITE_SPI_arready <= 0;
                        AXI_LITE_SPI_bresp <= resp;
                        AXI_LITE_SPI_bvalid <= 1;
                        if (AXI_LITE_SPI_arvalid && (AXI_LITE_SPI_araddr == 7'h00)) begin
                            Pmod_out_pin1 <= data_in[0];
                            Pmod_out_pin2 <= data_in[1];
                            Pmod_out_pin3 <= data_in[2];
                            Pmod_out_pin4 <= data_in[3];
                            Pmod_out_pin7 <= data_in[6];
                            Pmod_out_pin8 <= data_in[7];
                            Pmod_out_pin9 <= data_in[8];
                            Pmod_out_pin10 <= data_in[9];
                        end
                    end else begin
                        AXI_LITE_SPI_rvalid <= 1;
                        AXI_LITE_SPI_rresp <= 2'b00;
                    end
                end
            endcase
        end
    end

    always @(posedge ext_spi_clk) begin
        if (state == 1) begin
            data_out <= data_out << 1;
            data_out[0] <= data[0];
        end
    end
endmodule

