module gpio_controller (
  output  reg         o_wbs_int,
  output      [34:32] gpio_out,
  input       [31:0]  gpio_in
);

localparam			GPIO			            =	32'h00000000;
localparam			GPIO_OUTPUT_ENABLE		=	32'h00000001;
localparam			INTERRUPTS		        =	32'h00000002;
localparam			INTERRUPT_ENABLE	    =	32'h00000003;
localparam			INTERRUPT_EDGE        =	32'h00000004;

//gpio registers
reg			[31:0]	gpio_direction;
wire    [31:0]  gpio;

//interrupt registers
reg			[31:0]	interrupts;
reg			[31:0]	interrupt_mask;
reg			[31:0]	interrupt_edge;
reg					    clear_interrupts;

//set gpio direction
always @(gpio_direction)
begin
  if(gpio_direction == GPIO_OUTPUT_ENABLE)
    gpio <= gpio_out;
  else
    gpio_out <= gpio;
end

//read gpio input
assign gpio = gpio_direction == GPIO_OUTPUT_ENABLE ? gpio_out : gpio_in;

//set interrupt status
always @(posedge gpio_in)
begin
  interrupts <= interrupts | gpio_in & interrupt_mask;
end

//set interrupt edge
always @(interrupt_edge)
begin
  if(interrupt_edge == INTERRUPT_EDGE)
    o_wbs_int <= interrupts & interrupt_mask;
  else
    o_wbs_int <= 0;
end

//clear interrupts
always @(clear_interrupts)
begin
  if(clear_interrupts)
    interrupts <= 0;
end

//set interrupt enable
always @(interrupt_mask)
begin
  interrupts <= interrupts & interrupt_mask;
end

endmodule

