module spi (
  input         up_rstn,
  input         up_clk,
  input         up_spi_start,
  input         up_spi_devsel,
  input  [23:0] up_spi_wdata,
  input         spi_sd_i,
  output        spi_cs0n,
  output        spi_cs1n,
  output        spi_clk,
  output        spi_sd_en,
  output        spi_sd_o,
  output  [ 7:0] up_spi_rdata,
  output        up_spi_status
);

  reg [23:0] tx_data;
  reg [23:0] rx_data;
  reg        tx_done;
  reg        rx_done;
  reg        clk_en;
  reg        spi_cs0n;
  reg        spi_cs1n;
  reg        spi_clk;
  reg        spi_sd_en;
  reg        spi_sd_o;
  reg [7:0]  up_spi_rdata;
  reg        up_spi_status;

  wire       spi_sd_i_dly;
  wire       spi_sd_i_dly2;

  assign spi_clk = clk_en;
  assign spi_sd_en = 1'b1;
  assign spi_sd_o = tx_data[23];

  assign up_spi_rdata = rx_data[7:0];
  assign up_spi_status = tx_done && rx_done;

  assign spi_cs0n = ~up_spi_devsel;
  assign spi_cs1n = up_spi_devsel;

  always @(posedge up_clk) begin
    if (!up_rstn) begin
      tx_data <= 0;
      rx_data <= 0;
      tx_done <= 0;
      rx_done <= 0;
      clk_en <= 0;
      spi_sd_en <= 1'b0;
      spi_sd_o <= 1'b0;
      up_spi_rdata <= 0;
      up_spi_status <= 0;
    end else begin
      if (up_spi_start && !tx_done) begin
        tx_data <= up_spi_wdata;
        tx_done <= 1'b1;
        clk_en <= 1'b1;
      end else if (rx_done) begin
        tx_done <= 0;
        rx_done <= 0;
        clk_en <= 0;
      end
    end
  end

  always @(posedge up_clk) begin
    if (!up_rstn) begin
      spi_clk <= 0;
    end else begin
      if (clk_en) begin
        spi_clk <= ~spi_clk;
      end
    end
  end

  always @(posedge spi_clk) begin
    if (!up_rstn) begin
      rx_data <= 0;
    end else begin
      if (!rx_done) begin
        rx_data <= {rx_data[15:0], spi_sd_i};
      end
    end
  end

  assign spi_sd_i_dly = spi_sd_i;
  assign spi_sd_i_dly2 = spi_sd_i_dly;

  always @(posedge spi_clk) begin
    if (!up_rstn) begin
      spi_sd_en <= 0;
      spi_sd_o <= 0;
    end else begin
      if (tx_done) begin
        spi_sd_en <= 1'b1;
        spi_sd_o <= tx_data[23];
        tx_data <= {tx_data[22:0], spi_sd_i_dly2};
        if (rx_done) begin
          clk_en <= 0;
        end
      end
      if (!rx_done) begin
        rx_done <= (rx_data[23] && spi_sd_i_dly2);
      end
    end
  end

endmodule

