module top_module (
    input clk,              // Clock signal
    input rst_n,            // Asynchronous active-low reset
    input [3:0] in0,        // 4-bit input to the multiplexer
    input [3:0] in1,        // 4-bit input to the multiplexer
    input [3:0] in2,        // 4-bit input to the multiplexer
    input [3:0] in3,        // 4-bit input to the multiplexer
    input [1:0] sel,        // 2-bit select input to the multiplexer
    output [3:0] mux_out,   // 4-bit output from the multiplexer
    output [3:0] johnson_out, // 4-bit output from the Johnson counter
    output [3:0] sum_out    // 4-bit output from the functional module
);

// 4-to-1 multiplexer with priority encoder
wire [3:0] priority;
assign priority = {in0[3], in1[3], in2[3], in3[3]};
wire [3:0] selected;
assign selected = (sel == 2'b00) ? in0 :
                  (sel == 2'b01) ? in1 :
                  (sel == 2'b10) ? in2 :
                                   in3;
assign mux_out = selected;

// 64-bit Johnson counter
reg [63:0] johnson;
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        johnson <= 64'b0;
    end else begin
        johnson <= {johnson[62:0], ~johnson[63]};
    end
end
assign johnson_out = johnson[3:0];

// Functional module that adds the outputs of the multiplexer and Johnson counter
assign sum_out = mux_out + johnson[3:0];

endmodule

