    if (rst) begin
      counter0_OUT <= 0;
      counter1_OUT <= 0;
      counter2_OUT <= 0;
      counter_out <= 0;
    end else begin
      counter0_OUT <= counter0;
      counter1_OUT <= counter1;
      counter2_OUT <= counter2;
      if (counter_sel == 0) begin
        counter_out <= counter0;
      end else if (counter_sel == 1) begin
        counter_out <= counter1;
      end else begin
        counter_out <= counter2;
      end
    end
  end

  always @ (posedge clk, posedge rst) begin
    if (rst) begin
      counter0 <= 0;
      counter1 <= 0;
      counter2 <= 0;
    end else begin
      if (counter_we) begin
        if (counter_sel == 0) begin
          counter0 <= counter_val;
        end else if (counter_sel == 1) begin
          counter1 <= counter_val;
        end else begin
          counter2 <= counter_val;
        end
      end
    end
  end

endmodule

