module basic_fifo(
  clk_i,
  rst_i,

  data_i,
  enq_i,
  full_o,
  count_o,

  data_o,
  valid_o,
  deq_i
);

parameter fifo_width     = 32;
parameter fifo_bit_depth = 6;

input clk_i, rst_i;

input        [fifo_width-1:0] data_i;
input                         enq_i;
output                        full_o;
output reg [fifo_bit_depth:0] count_o;

output reg [fifo_width-1:0] data_o;
output reg                  valid_o;
input                       deq_i;

reg   [fifo_width-1:0] fifo_data [2**(fifo_bit_depth)-1:0];
reg [fifo_bit_depth:0] fifo_head, fifo_tail;
reg [fifo_bit_depth:0] next_tail;

// accept input
wire next_full = fifo_head[fifo_bit_depth-1:0] == next_tail[fifo_bit_depth-1:0] &&
                 fifo_head[fifo_bit_depth]     != next_tail[fifo_bit_depth];
always @(posedge clk_i or posedge rst_i)
  if (rst_i)
  begin
    fifo_tail <= 1'b0;
    next_tail <= 1'b1;
  end
  else if (!next_full && enq_i)
  begin
     // We can only enqueue when not full
     fifo_data[fifo_tail[fifo_bit_depth-1:0]] <= data_i;
     next_tail <= next_tail + 1'b1;
     fifo_tail <= next_tail;
   end

assign full_o = next_full;

always @(posedge clk_i or posedge rst_i)
  if(rst_i)
    count_o <= 1'b0;
  else if(enq_i & ~deq_i & ~next_full)
    count_o <= count_o + 1'b1;
  else if(~enq_i & deq_i & valid_o)
    count_o <= count_o - 1'b1;

// provide output
wire is_empty = (fifo_head == fifo_tail);
always @(posedge clk_i or posedge rst_i)
  if (rst_i) begin
    valid_o <= 1'b0;
    fifo_head <= 1'b0;
  end 
  else
  begin        
    if (!is_empty)
    begin
      if (!valid_o || deq_i)
        fifo_head <= fifo_head + 1'b1;

      valid_o <= 1'b1;
    end
    else if (deq_i)
      valid_o <= 1'b0;
  end

always @(posedge clk_i)
    // If no valid out or we're dequeueing, we want to grab
    // the next data.  If we're empty, we don't get valid_o,
    // so we don't care if it's garbage.
  if (!valid_o || deq_i)
    data_o <= fifo_data[fifo_head[fifo_bit_depth-1:0]];

endmodule

module trigonometric (
  input signed [width-1:0] in,
  output signed [width-1:0] sin,
  output signed [width-1:0] cos,
  output signed [width-1:0] tan
);

parameter width = 16; // number of bits used to represent input and output signals

reg [width-1:0] x, y, z;
reg [width-1:0] atan_lut [0:width-1];
integer i;

initial begin
  // Initialize the arctangent lookup table
  for (i = 0; i < width; i = i + 1)
    atan_lut[i] = $rtoi(atan(2**(-i)) * 2**width);
end

always @(*) begin
  x = 1 << (width - 1); // Initialize x to the maximum value
  y = 0; // Initialize y to 0
  z = in; // Initialize z to the input angle

  // Perform the CORDIC iterations
  for (i = 0; i < width; i = i + 1) begin
    if (z >= 0) begin
      x = x - (y >>> i);
      y = y + (x >>> i);
      z = z - atan_lut[i];
    end else begin
      x = x + (y >>> i);
      y = y - (x >>> i);
      z = z + atan_lut[i];
    end
  end

  // Compute the sine, cosine, and tangent of the input angle
  sin = y;
  cos = x;
  tan = (y == 0) ? ((1 << width) - 1) : (x / y);
end

endmodule

