module system_controller (
    input clk,
    input reset,
    input [31:0] wb_adr_i,
    input [31:0] wb_dat_i,
    input [3:0] wb_sel_i,
    input wb_we_i,
    input wb_cyc_i,
    input wb_stb_i,
    input [2:0] wb_cti_i,
    input wb_bte_i,
    output reg [31:0] wb_dat_o,
    output reg wb_ack_o,
    output reg wb_err_o,
    output reg wb_rty_o,
    output reg [31:0] wb_adr_o,
    output reg [3:0] wb_sel_o,
    output reg wb_we_o,
    output reg wb_cyc_o,
    output reg wb_stb_o,
    output reg [2:0] wb_cti_o,
    output reg wb_bte_o
);

// Slave 0 address range
localparam SLAVE0_BASE_ADDR = 32'h0000_0000;
localparam SLAVE0_TOP_ADDR = 32'h0000_ffff;

// Slave 1 address range
localparam SLAVE1_BASE_ADDR = 32'h1000_0000;
localparam SLAVE1_TOP_ADDR = 32'h1000_ffff;

reg [31:0] slave0_mem [0:65535];
reg [31:0] slave1_mem [0:65535];

assign wb_dat_o = (wb_cyc_i && wb_stb_i && !wb_we_i) ? 
                  (wb_sel_i[0] ? slave0_mem[wb_adr_i - SLAVE0_BASE_ADDR] : 0) | 
                  (wb_sel_i[1] ? slave1_mem[wb_adr_i - SLAVE1_BASE_ADDR] : 0) : 0;

always @(posedge clk) begin
    if (reset) begin
        wb_ack_o <= 0;
        wb_err_o <= 0;
        wb_rty_o <= 0;
        wb_adr_o <= 0;
        wb_sel_o <= 0;
        wb_we_o <= 0;
        wb_cyc_o <= 0;
        wb_stb_o <= 0;
        wb_cti_o <= 0;
        wb_bte_o <= 0;
    end else begin
        if (wb_cyc_i && wb_stb_i) begin
            if (wb_adr_i >= SLAVE0_BASE_ADDR && wb_adr_i <= SLAVE0_TOP_ADDR) begin
                wb_adr_o <= wb_adr_i - SLAVE0_BASE_ADDR;
                wb_sel_o <= wb_sel_i;
                wb_we_o <= wb_we_i;
                wb_cyc_o <= wb_cyc_i;
                wb_stb_o <= wb_stb_i;
                wb_cti_o <= wb_cti_i;
                wb_bte_o <= wb_bte_i;

                if (wb_we_i) begin
                    slave0_mem[wb_adr_i - SLAVE0_BASE_ADDR] <= wb_dat_i;
                end else begin
                    wb_dat_o <= slave0_mem[wb_adr_i - SLAVE0_BASE_ADDR];
                end

                wb_ack_o <= 1;
                wb_err_o <= 0;
                wb_rty_o <= 0;
            end else if (wb_adr_i >= SLAVE1_BASE_ADDR && wb_adr_i <= SLAVE1_TOP_ADDR) begin
                wb_adr_o <= wb_adr_i - SLAVE1_BASE_ADDR;
                wb_sel_o <= wb_sel_i;
                wb_we_o <= wb_we_i;
                wb_cyc_o <= wb_cyc_i;
                wb_stb_o <= wb_stb_i;
                wb_cti_o <= wb_cti_i;
                wb_bte_o <= wb_bte_i;

                if (wb_we_i) begin
                    slave1_mem[wb_adr_i - SLAVE1_BASE_ADDR] <= wb_dat_i;
                end else begin
                    wb_dat_o <= slave1_mem[wb_adr_i - SLAVE1_BASE_ADDR];
                end

                wb_ack_o <= 1;
                wb_err_o <= 0;
                wb_rty_o <= 0;
            end else begin
                wb_ack_o <= 0;
                wb_err_o <= 1;
                wb_rty_o <= 0;
            end
        end else begin
            wb_ack_o <= 0;
            wb_err_o <= 0;
            wb_rty_o <= 0;
        end
    end
end

endmodule

