module float_arithmetic (
  input [31:0] A,
  input [31:0] B,
  input [1:0] CTRL,
  output reg [31:0] RESULT
);

  // Define constants for IEEE 754 format
  parameter EXPONENT_WIDTH = 8;
  parameter MANTISSA_WIDTH = 23;
  parameter BIAS = 127;

  // Define variables for A and B in IEEE 754 format
  reg [31:0] A_sign, A_exponent, A_mantissa;
  reg [31:0] B_sign, B_exponent, B_mantissa;

  // Define variables for intermediate values
  reg [31:0] product_sign, product_exponent, product_mantissa;
  reg [31:0] quotient_sign, quotient_exponent, quotient_mantissa;

  // Convert A to IEEE 754 format
  assign A_sign = A[31];
  assign A_exponent = A[30:23] - BIAS;
  assign A_mantissa = {1'b1, A[22:0]};

  // Convert B to IEEE 754 format
  assign B_sign = B[31];
  assign B_exponent = B[30:23] - BIAS;
  assign B_mantissa = {1'b1, B[22:0]};

  // Perform arithmetic based on CTRL signal
  always @(*) begin
    case (CTRL)
      2'b00: begin // Addition
        if (A_exponent > B_exponent) begin
          product_exponent = A_exponent;
          B_mantissa = {1'b1, B_mantissa};
          product_mantissa = A_mantissa + B_mantissa >> A_exponent - B_exponent;
        end else begin
          product_exponent = B_exponent;
          A_mantissa = {1'b1, A_mantissa};
          product_mantissa = A_mantissa + B_mantissa >> B_exponent - A_exponent;
        end
        RESULT[31] = product_sign;
        RESULT[30:23] = product_exponent + BIAS;
        RESULT[22:0] = product_mantissa[22:0];
      end
      2'b01: begin // Subtraction
        B_sign = ~B_sign;
        if (A_exponent > B_exponent) begin
          product_exponent = A_exponent;
          B_mantissa = {1'b1, B_mantissa};
          product_mantissa = A_mantissa + B_mantissa >> A_exponent - B_exponent;
        end else begin
          product_exponent = B_exponent;
          A_mantissa = {1'b1, A_mantissa};
          product_mantissa = A_mantissa + B_mantissa >> B_exponent - A_exponent;
        end
        RESULT[31] = product_sign;
        RESULT[30:23] = product_exponent + BIAS;
        RESULT[22:0] = product_mantissa[22:0];
      end
      2'b10: begin // Multiplication
        product_sign = A_sign ^ B_sign;
        product_exponent = A_exponent + B_exponent - BIAS;
        product_mantissa = A_mantissa * B_mantissa;
        if (product_mantissa[MANTISSA_WIDTH + 1]) begin
          product_exponent = product_exponent + 1;
          product_mantissa = product_mantissa >> 1;
        end
        RESULT[31] = product_sign;
        RESULT[30:23] = product_exponent + BIAS;
        RESULT[22:0] = product_mantissa[MANTISSA_WIDTH - 1: MANTISSA_WIDTH - 23];
      end
      2'b11: begin // Division
        quotient_sign = A_sign ^ B_sign;
        quotient_exponent = A_exponent - B_exponent + BIAS;
        quotient_mantissa = A_mantissa / B_mantissa;
        if (quotient_mantissa[MANTISSA_WIDTH]) begin
          quotient_exponent = quotient_exponent + 1;
          quotient_mantissa = quotient_mantissa >> 1;
        end
        RESULT[31] = quotient_sign;
        RESULT[30:23] = quotient_exponent;
        RESULT[22:0] = quotient_mantissa[MANTISSA_WIDTH - 1: MANTISSA_WIDTH - 23];
      end
    endcase
  end

endmodule

