module FSM (
  input clk,
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 4; // number of input signals
parameter m = 2; // number of output signals
parameter s = 8; // number of states in the original FSM

reg [2:0] state; // original FSM state register

// Define the original FSM transitions
always @(posedge clk) begin
  case(state)
    3'b000: if(in == 4'b0000) state <= 3'b000; else state <= 3'b001;
    3'b001: if(in == 4'b0000) state <= 3'b010; else state <= 3'b011;
    3'b010: if(in == 4'b0000) state <= 3'b100; else state <= 3'b101;
    3'b011: if(in == 4'b0000) state <= 3'b110; else state <= 3'b111;
    3'b100: if(in == 4'b0000) state <= 3'b000; else state <= 3'b001;
    3'b101: if(in == 4'b0000) state <= 3'b010; else state <= 3'b011;
    3'b110: if(in == 4'b0000) state <= 3'b100; else state <= 3'b101;
    3'b111: if(in == 4'b0000) state <= 3'b110; else state <= 3'b111;
  endcase
end

// Define the merged FSM transitions
always @(posedge clk) begin
  case(state)
    3'b000: if(in == 4'b0000) state <= 3'b000; else state <= 3'b001;
    3'b001: if(in == 4'b0000) state <= 3'b010; else state <= 3'b011;
    3'b010: if(in == 4'b0000) state <= 3'b100; else state <= 3'b101;
    3'b011: if(in == 4'b0000) state <= 3'b110; else state <= 3'b111;
    3'b100: if(in == 4'b0000) state <= 3'b000; else state <= 3'b001;
    3'b101: if(in == 4'b0000) state <= 3'b010; else state <= 3'b011;
    3'b110: if(in == 4'b0000) state <= 3'b100; else state <= 3'b101;
    3'b111: if(in == 4'b0000) state <= 3'b010; else state <= 3'b111;
  endcase
end

// Define the output signals as a function of the state and input signals
always @(state or in) begin
  case(state)
    3'b000: out <= {m{1'b0}};
    3'b001: out <= {m{in[0]}};
    3'b010: out <= {m{in[1]}};
    3'b011: out <= {m{in[0] ^ in[1]}};
    3'b100: out <= {m{in[2]}};
    3'b101: out <= {m{in[0] ^ in[2]}};
    3'b110: out <= {m{in[1] ^ in[2]}};
    3'b111: out <= {m{in[0] ^ in[1] ^ in[2]}};
  endcase
end

endmodule

module top_module (
    input clk,
    input rst_n,
    input [15:0] data_in,
    input [3:0] shift_amount,
    input mode,
    output reg [1:0] code_out
);

    wire [15:0] shifted_data;
    wire [7:0] max_value;
    wire [3:0] max_index;

    barrel_shifter barrel_shifter_inst (
        .data_in(data_in),
        .shift_amount(shift_amount),
        .shifted_data(shifted_data)
    );

    max_value_and_index max_value_and_index_inst (
        .data_in(shifted_data),
        .max_value(max_value),
        .max_index(max_index)
    );

    assign code_out = (mode == 1) ? 2'b00 :
                      (max_value > 7'd127) ? 2'b00 :
                      (max_value > 7'd64) ? 2'b01 :
                      2'b10;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            code_out <= 2'b00;
        end else begin
            code_out <= (mode == 1) ? 2'b00 :
                        (max_value > 7'd127) ? 2'b00 :
                        (max_value > 7'd64) ? 2'b01 :
                        2'b10;
        end
    end

endmodule

module niosII_system_nios2_qsys_0_nios2_oci_dtrace (
    input clk,
    input [24:0] cpu_d_address,
    input cpu_d_read,
    input [31:0] cpu_d_readdata,
    input cpu_d_wait,
    input cpu_d_write,
    input [31:0] cpu_d_writedata,
    input jrst_n,
    input [15:0] trc_ctrl,
    output reg [35:0] atm,
    output reg [35:0] dtm
);

wire [31:0] cpu_d_address_0_padded;
wire [31:0] cpu_d_readdata_0_padded;
wire [31:0] cpu_d_writedata_0_padded;
wire record_load_addr;
wire record_load_data;
wire record_store_addr;
wire record_store_data;
wire [3:0] td_mode_trc_ctrl;

assign cpu_d_writedata_0_padded = cpu_d_writedata | 32'b0;
assign cpu_d_readdata_0_padded = cpu_d_readdata | 32'b0;
assign cpu_d_address_0_padded = cpu_d_address | 32'b0;

niosII_system_nios2_qsys_0_nios2_oci_td_mode niosII_system_nios2_qsys_0_nios2_oci_trc_ctrl_td_mode (
    .ctrl(trc_ctrl[8:0]),
    .td_mode(td_mode_trc_ctrl)
);

assign {record_load_addr, record_store_addr, record_load_data, record_store_data} = td_mode_trc_ctrl;

always @(posedge clk or negedge jrst_n) begin
    if (jrst_n == 0) begin
        atm <= 0;
        dtm <= 0;
    end else if (cpu_d_wait == 0) begin
        if (cpu_d_write & record_store_addr) begin
            atm <= {4'b0101, cpu_d_address_0_padded};
        end else if (cpu_d_read & record_load_addr) begin
            atm <= {4'b0100, cpu_d_address_0_padded};
        end else begin
            atm <= {4'b0000, cpu_d_address_0_padded};
        end

        if (cpu_d_write & record_store_data) begin
            dtm <= {4'b0111, cpu_d_writedata_0_padded};
        end else if (cpu_d_read & record_load_data) begin
            dtm <= {4'b0110, cpu_d_readdata_0_padded};
        end else begin
            dtm <= {4'b0000, cpu_d_readdata_0_padded};
        end
    end else begin
        atm <= 0;
        dtm <= 0;
    end
end

endmodule

