module clk_gen(
    input areset,
    input [1:0] inclk,
    output reg clk,
    output reg locked
);

    wire [4:0] pll_clk;
    wire pll_locked;

    // Instantiate PLL module
    pll pll_inst(
        .areset(areset),
        .inclk(inclk),
        .clk(pll_clk),
        .locked(pll_locked)
    );

    // Output clock frequency selection
    always @ (posedge pll_clk) begin
        case (inclk)
            2'b00: clk <= pll_clk[0];
            2'b01: clk <= pll_clk[1];
            2'b10: clk <= pll_clk[2];
            2'b11: clk <= pll_clk[3];
        endcase
    end

    // Output lock status of PLL
    always @ (posedge pll_clk, posedge areset) begin
        if (areset) begin
            locked <= 0;
        end else begin
            locked <= pll_locked;
        end
    end

endmodule

module mux4to1_en(
    input [1:0] sel,
