module binary_adder(SUM, A, B, CLK);
  output reg [1:0] SUM;
  input [1:0] A, B;
  input CLK;

  wire [1:0] carry;
  full_adder FA0(SUM[0], A[0], B[0], carry[0], CLK);
  full_adder FA1(SUM[1], A[1], B[1], carry[1], CLK);

  always @(posedge CLK) begin
    SUM <= {carry[1], carry[0]} + A + B;
  end

endmodule

module full_adder(S, A, B, C, CLK);
  output reg S, C;
  input A, B, CLK;

  always @(posedge CLK) begin
    S <= A ^ B ^ C;
    C <= (A & B) | (C & (A ^ B));
  end

endmodule

module register_mult_clock_gate (
  input CLK,
  input EN,
  input TE,
  output ENCLK
);

  reg [1:0] state;
  parameter IDLE = 2'b00, TRIGGERED = 2'b01, ENABLED = 2'b10;

  always @(posedge CLK) begin
    case (state)
      IDLE: begin
        ENCLK <= 1'b0;
        if (EN) begin
          state <= TRIGGERED;
        end
      end
      TRIGGERED: begin
        ENCLK <= 1'b1;
        if (TE) begin
          state <= ENABLED;
        end
      end
      ENABLED: begin
        ENCLK <= 1'b0;
        state <= IDLE;
      end
    endcase
  end

endmodule

module multiplier_block (
