module top_module(
    input [31:0] a,
    input [31:0] b,
    output [31:0] sum
);

    wire [7:0] a0, b0, a1, b1, a2, b2, a3, b3;
    wire [7:0] s0, s1, s2, s3, c1, c2, c3;

    // 8-bit adders
    adder8bit adder0(a[7:0], b[7:0], s0, c1);
    adder8bit adder1(a[15:8], b[15:8], s1, c2);
    adder8bit adder2(a[23:16], b[23:16], s2, c3);
    adder8bit adder3(a[31:24], b[31:24], s3, sum[31]);

    // Final 32-bit output
    assign sum[30:24] = s3;
    assign sum[23:16] = s2;
    assign sum[15:8] = s1;
    assign sum[7:0] = s0;

endmodule

module adder8bit(
    input [7:0] a,
    input [7:0] b,
    output [7:0] sum,
    output carry
);

    assign {carry, sum} = a + b;

endmodule

module binary_adder(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout,
    output Overflow,
    output Zero
);

    wire [3:0] sum;
    wire [3:0] carry;

    // Instantiate 1-bit full adder module
    full_adder fa0(.a(A[0]), .b(B[0]), .cin(Cin), .s(sum[0]), .cout(carry[0]));
    full_adder fa1(.a(A[1]), .b(B[1]), .cin(carry[0]), .s(sum[1]), .cout(carry[1]));
    full_adder fa2(.a(A[2]), .b(B[2]), .cin(carry[1]), .s(sum[2]), .cout(carry[2]));
    full_adder fa3(.a(A[3]), .b(B[3]), .cin(carry[2]), .s(sum[3]), .cout(Cout));

    // Calculate Overflow and Zero signals
    assign Overflow = (A[3] & B[3] & carry[2]) | (~A[3] & ~B[3] & carry[2]) | (A[3] & ~B[3] & ~carry[2]) | (~A[3] & B[3] & ~carry[2]);
    assign Zero = (sum[3:0] == 0);

    // Output sum
    assign S = sum;

endmodule

