    if (wrreq && !wrfull) begin
        mem[wraddr][WIDTH-1:0] <= data;
        wrptr <= wrptr_next;
        wrusedw_reg <= wrusedw_next;
    end
end
assign wrfull = (wrptr_next == rdptr) && wrreq && !rdreq;
assign wrusedw = wrusedw_reg;

// Read pointer logic
