assign rdaddr_next = rdptr_next[5:0];
always @(posedge rdclk) begin
    if (rdreq && !rdempty) begin
        q <= mem[rdaddr][WIDTH-1:0];
        rdptr <= rdptr_next;
        rdusedw_reg <= rdusedw_next;
    end
end
assign rdempty = (rdptr_next == wrptr) && !wrreq && rdreq;
assign rdfull = 0;
assign rdusedw = rdusedw_reg;

