always @(posedge wrclk) begin
    if (aclr) begin
        for (i = 0; i < DEPTH; i = i + 1) begin
            mem[i] <= 0;
        end
        wrptr <= 0;
        rdptr <= 0;
        wrusedw_reg <= 0;
        rdusedw_reg <= 0;
    end
end

