  end
endmodule

module oneShotPulseGenerator (
  input trig,
  input rst,
  output out
);

parameter t = 1; // duration of output pulse in seconds
parameter r = 100; // resistance of resistor in ohms
parameter c = 1e-6; // capacitance of capacitor in farads

reg out_reg; // output pulse register
reg pulse_started; // flag to indicate if pulse has started
real time_constant; // time constant of RC circuit
real pulse_duration; // duration of output pulse

always @(*) begin
  if (rst) begin // reset signal
    out_reg <= 0;
    pulse_started <= 0;
  end else if (trig && !pulse_started) begin // trigger signal
    pulse_duration = t;
    time_constant = r * c;
    out_reg <= 1;
    pulse_started <= 1;
  end else if (pulse_started && pulse_duration > 0) begin // output pulse
    out_reg <= 1;
    pulse_duration = pulse_duration - 1;
  end else begin // end of output pulse
    out_reg <= 0;
    pulse_started <= 0;
  end
end

assign out = out_reg;

endmodule

