module nfc_transmitter (
  input clk,
  input rst,
  input [7:0] data_in,
  output nfc_out
);

  reg [7:0] data_reg;
  reg [7:0] bit_counter;
  reg mod_signal;
  reg [15:0] mod_counter;

  assign nfc_out = mod_signal;

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      data_reg <= 8'b00000000;
      bit_counter <= 8'b00000000;
      mod_signal <= 1'b0;
      mod_counter <= 16'b0000000000000000;
    end else begin
      if (bit_counter == 8'b00000000) begin
        data_reg <= data_in;
        bit_counter <= 8'b00000001;
        mod_signal <= 1'b0;
        mod_counter <= 16'b0000000000000000;
      end else begin
        if (mod_counter == 16'b0000000000000000) begin
          mod_signal <= data_reg[0];
          data_reg <= {data_reg[6:0], 1'b0};
          bit_counter <= bit_counter + 1;
          mod_counter <= 16'b0000000000000001;
        end else begin
          mod_signal <= ~mod_signal;
          mod_counter <= mod_counter + 1;
        end
      end
    end
  end

endmodule

module nfc_receiver (
  input clk,
  input rst,
  input nfc_in,
  output [7:0] data_out
);

  reg [7:0] data_reg;
  reg [7:0] bit_counter;
  reg demod_signal;
  reg [15:0] demod_counter;

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      data_reg <= 8'b00000000;
      bit_counter <= 8'b00000000;
      demod_signal <= 1'b0;
      demod_counter <= 16'b0000000000000000;
    end else begin
      if (demod_counter == 16'b0000000000000000) begin
        data_reg <= {data_reg[6:0], demod_signal};
        bit_counter <= bit_counter + 1;
        demod_counter <= 16'b0000000000000001;
      end else begin
        if (nfc_in > 0) begin
          demod_signal <= 1'b1;
        end else begin
          demod_signal <= 1'b0;
        end
        demod_counter <= demod_counter + 1;
      end
      if (bit_counter == 8'b00001000) begin
        data_out <= data_reg;
        data_reg <= 8'b00000000;
        bit_counter <= 8'b00000000;
      end
    end
  end

endmodule

module digiPot (
  input inc_dec,
  input [n-1:0] step,
  output wiper,
  output [n-1:0] out
);

parameter n = 8; // number of segments
parameter r = 100; // resistance value of each segment (in ohms)

reg [n-1:0] segments; // register to store the state of each segment
reg [n-1:0] resistance; // register to store the resistance value of each segment
reg [n:0] wiper_pos; // register to store the current position of the wiper

// initialize the digital potentiometer
initial begin
  segments = 0;
  resistance = r;
  wiper_pos = 0;
end

// compute the resistance value of each segment
generate
  genvar i;
  for (i = 0; i < n; i = i + 1) begin : seg_gen
    assign out[i] = segments[i] ? resistance[i] : 0;
  end
endgenerate

// compute the current position of the wiper
assign wiper = out * wiper_pos;

// logic for increasing or decreasing the resistance
always @ (posedge inc_dec) begin
  if (inc_dec) begin
    wiper_pos = wiper_pos + step;
    if (wiper_pos > n) begin
      wiper_pos = n;
    end
  end else begin
    wiper_pos = wiper_pos - step;
    if (wiper_pos < 0) begin
      wiper_pos = 0;
    end
  end
end

// logic for switching the segments on and off
always @ (wiper_pos) begin
  segments = {wiper_pos{1'b1}};
end

endmodule

