module FIFOL2(CLK,
              RST,
              D_IN,
              ENQ,
              FULL_N,
              D_OUT,
              DEQ,
              EMPTY_N,
              CLR);

   parameter width = 1;

   input     CLK ;
   input     RST ;
   input [width - 1 : 0] D_IN;
   input                 ENQ;
   input                 DEQ;
   input                 CLR ;

   output                FULL_N;
   output                EMPTY_N;
   output [width - 1 : 0] D_OUT;

   reg                    full_reg;
   reg                    empty_reg;
   reg [width - 1 : 0]    data0_reg;
   reg [width - 1 : 0]    data1_reg;

   assign                 FULL_N = full_reg || DEQ;
   assign                 EMPTY_N = empty_reg ;
   assign                 D_OUT = data0_reg ;


   // Optimize the loading logic since state encoding is not power of 2!
   wire                   d0di = (ENQ && ! empty_reg ) || ( ENQ && DEQ && full_reg ) ;
   wire                   d0d1 = DEQ && ! full_reg ;
   wire                   d0h = ((! DEQ) && (! ENQ )) || (!DEQ && empty_reg ) || ( ! ENQ &&full_reg) ;
   wire                   d1di = ENQ & empty_reg ;

   // Initialize the FIFO buffer
   initial begin
     data0_reg = {((width + 1)/2) {2'b10}} ;
     data1_reg = {((width + 1)/2) {2'b10}} ;
     empty_reg = 1'b0;
     full_reg = 1'b1;
   end

   always@(posedge CLK) begin
     // Reset the FIFO buffer
     if(RST) begin
       data0_reg <= {width{1'b0}};
       data1_reg <= {width{1'b0}};
       empty_reg <= 1'b0;
       full_reg <= 1'b1;
     end
     // Clear the FIFO buffer
     else if(CLR) begin
       data0_reg <= {((width + 1)/2) {2'b10}};
       data1_reg <= {((width + 1)/2) {2'b10}};
       empty_reg <= 1'b0;
       full_reg <= 1'b1;
     end
     // Enqueue data
     else if(ENQ && !full_reg) begin
       if(empty_reg) begin
         data0_reg <= {width{1'b0}};
         data1_reg <= {width{1'b0}};
       end
       data0_reg <= {d0di{D_IN}} & data0_reg |
                    {d0d1{data1_reg}} & data1_reg |
                    {d0h{data0_reg}} & data0_reg;
       data1_reg <= d1di ? D_IN : data1_reg;
       empty_reg <= 1'b0;
       full_reg <= d0di ? 1'b1 : 1'b0;
     end
     // Dequeue data
     else if(DEQ && !empty_reg) begin
       D_OUT <= data0_reg;
       data0_reg <= data1_reg;
       data1_reg <= {width{1'b0}};
       empty_reg <= full_reg ? 1'b0 : 1'b1;
       full_reg <= 1'b0;
     end
   end

endmodule

module I2C_state_machine (
  input SDA,
  input SCL,
  input START,
  input STOP,
  input [7:0] ADDR,
  input [7:0] DATA,
  output ACK,
  output ERROR
);

  // Define the four states
  parameter IDLE = 2'b00;
  parameter START_CONDITION = 2'b01;
  parameter ADDRESS_TRANSMIT = 2'b10;
  parameter DATA_TRANSMIT = 2'b11;

  // Define the state register and initialize it to IDLE
  reg [1:0] state = IDLE;

  // Define the acknowledge register and initialize it to 0
  reg ACK_reg = 1'b0;

  // Define the error register and initialize it to 0
  reg ERROR_reg = 1'b0;

  always @ (posedge SCL) begin
    case (state)
      IDLE: begin
        if (START) begin
          state <= START_CONDITION;
        end
      end

      START_CONDITION: begin
        SDA <= 0;
        if (!SDA && SCL) begin
          state <= ADDRESS_TRANSMIT;
        end
      end

      ADDRESS_TRANSMIT: begin
        for (i = 0; i < 8; i = i + 1) begin
          SDA <= ADDR[i];
          #1 SCL <= 1;
          #1 SCL <= 0;
        end

        // Check for acknowledge
        SDA <= 1;
        #1 SCL <= 1;
        ACK_reg <= !SDA;
        #1 SCL <= 0;

        if (ACK_reg) begin
          state <= DATA_TRANSMIT;
        end else begin
          ERROR_reg <= 1;
        end
      end

      DATA_TRANSMIT: begin
        for (i = 0; i < 8; i = i + 1) begin
          SDA <= DATA[i];
          #1 SCL <= 1;
          #1 SCL <= 0;
        end

        // Check for acknowledge
        SDA <= 1;
        #1 SCL <= 1;
        ACK_reg <= !SDA;
        #1 SCL <= 0;

        if (ACK_reg) begin
          state <= IDLE;
        end else begin
          ERROR_reg <= 1;
        end
      end
    endcase
  end

  // Assign the ACK and ERROR outputs
  assign ACK = ACK_reg;
  assign ERROR = ERROR_reg;

endmodule

