module pulse_generator(
    input clk,
    input reset,
    input [7:0] pulse_width,
    output reg pulse
);

    reg [7:0] counter;

    always @(posedge clk, posedge reset) begin
        if (reset) begin
            counter <= 0;
            pulse <= 0;
