module adder(
    input [3:0] A,
    input [3:0] B,
    input C_in,
    output [3:0] S,
    output C_out
);

    wire [3:0] sum;
    wire C_out1;

    assign sum = A + B + C_in;
    assign S = sum[3:0];
    assign C_out = sum[4] | C_out1;
    assign C_out1 = sum[3] & sum[2] | (sum[3] | sum[2]) & sum[1] | (sum[3] | sum[2] | sum[1]) & sum[0];

endmodule

module top_module (
    input [3:0] in0,
    input [3:0] in1,
    input enable,
    output reg [7:0] out
);

    wire [3:0] cmp_out;
    wire [7:0] dec_out;

    comparator cmp(.in0(in0), .in1(in1), .out(cmp_out));
    decoder dec(.in(cmp_out), .enable(enable), .out(dec_out));

    always @(*) begin
        if (cmp_out == 4'b0000) // in0 = in1
            out = dec_out[0];
        else if (cmp_out > 4'b0000) // in0 > in1
            out = dec_out[1];
        else // in0 < in1
            out = dec_out[2];
    end

endmodule

module comparator (
    input [3:0] in0,
    input [3:0] in1,
    output reg [3:0] out
);

    always @(*) begin
        if (in0 == in1)
            out = 4'b0000;
        else if (in0 > in1)
            out = 4'b0001;
        else
            out = 4'b0010;
    end

endmodule

module decoder (
    input [3:0] in,
    input enable,
    output reg [7:0] out
);

    always @(*) begin
        case (in)
            4'b0000: out = 8'b00000001;
            4'b0001: out = 8'b00000010;
            4'b0010: out = 8'b00000100;
            4'b0011: out = 8'b00001000;
            4'b0100: out = 8'b00010000;
            4'b0101: out = 8'b00100000;
            4'b0110: out = 8'b01000000;
            4'b0111: out = 8'b10000000;
            default: out = 8'b00000000;
        endcase

        if (!enable)
            out = 8'b00000000;
    end

endmodule

module can_receive_pkt(
    input clk,
    input rst_n,
    //inputs
    input [255:0] parser2exe_data,
    input parser2exe_data_wr,
    input [31:0] lookup2exe_rule,
    input lookup2exe_rule_wr,
    //outputs
    output [133:0] exe2disp_data,
    output exe2disp_data_wr,
    output exe2disp_valid_wr,
    //other
    output [7:0] exe_dfifo_usedw
);

//***************************************************
//                  Combinational Logic
//***************************************************

reg [5:0] exe_state;
reg exe_dfifo_rd;
reg rule_fifo_rd;
reg [5:0] polling_cpuid;
reg rule_fifo_rd_dly;

always @(posedge clk or negedge rst_n) begin
    if(rst_n == 1'b0) begin
        exe_state <= IDLE_S;
    end
    else begin
        case(exe_state)
            IDLE_S: begin
                exe_dfifo_rd <= 1'b0;
                rule_fifo_rd <= 1'b0;
            end

            PARSER_S: begin
                exe_dfifo_rd <= 1'b1;
                rule_fifo_rd <= 1'b0;
            end

            LOOKUP_S: begin
                exe_dfifo_rd <= 1'b1;
                rule_fifo_rd <= 1'b1;
            end

            METADATA_S: begin
                rule_fifo_rd <= 1'b0;
                case(rule_fifo_rdata[31:28])
                    4'd1: begin//1 trans to CPU with thread id assignd by user
                        exe2disp_data_wr <= 1'b1;
                        exe2disp_data[133:56] <= exe_dfifo_rdata[133:56];
                        exe2disp_data[55:47] <= {1'b0,rule_fifo_rdata[7:0]};
                        exe2disp_data[46:0] <= exe_dfifo_rdata[46:0];
                        exe_state <= TRANS_S;
                    end

                    4'd2: begin//2 trans to CPU with polling thread id
                        exe2disp_data_wr <= 1'b1;
                        exe2disp_data[133:56] <= exe_dfifo_rdata[133:56];
                        exe2disp_data[55:47] <= {3'b0,polling_cpuid};
                        exe2disp_data[46:0] <= exe_dfifo_rdata[46:0];
                        if((polling_cpuid+6'b1) < sys_max_cpuid) begin
                        //if use sys_max_cpuid -1,maybe underflow
                            polling_cpuid <= polling_cpuid + 6'd1;
                        end
                        else begin
                            polling_cpuid <= 6'b0;
                        end
                        exe_state <= TRANS_S;
                    end

                    4'd3: begin//3 trans to port 
                        exe2disp_data_wr <= 1'b1;
                        //modify by lxj 20161011 start
                        exe2disp_data[133:113] <= exe_dfifo_rdata[133:113];
                        exe2disp_data[109:74] <= exe_dfifo_rdata[109:74];
                        if(rule_fifo_rdata[7:4] == 4'b0) begin//slot0
                            exe2disp_data[112:110] <= 3'b0;
                            exe2disp_data[73:64] <= {6'b0,rule_fifo_rdata[3:0]};
                        end
                        else begin//slot1
                            exe2disp_data[112:110] <= 3'b1;
                            exe2disp_data[73:64] <= {6'b0,rule_fifo_rdata[7:4]};
                        end
                        //modify by lxj 20161011 end
                        //exe2disp_data[73:64] <= {2'b0,rule_fifo_rdata[7:0]};
                        exe2disp_data[63:0] <= exe_dfifo_rdata[63:0];
                        exe_state <= TRANS_S;
                    end

                    default: begin//discard
                        exe2disp_data_wr <= 1'b0;
                        exe_state <= DISCARD_S;
                    end
                endcase
            end

            TRANS_S: begin
                exe2disp_data_wr <= 1'b1;
                exe2disp_data <= exe_dfifo_rdata;
                if(exe_dfifo_rdata[133:132] == 2'b10) begin//end of pkt
                    exe_dfifo_rd <= 1'b0;
                    exe2disp_valid_wr <= 1'b1;
                    exe_state <= IDLE_S;
                end
                else begin
                    exe_dfifo_rd <= 1'b1;
                    exe2disp_valid_wr <= 1'b0;
                    exe_state <= TRANS_S;
                end
            end

            DISCARD_S: begin
                rule_fifo_rd <= 1'b0;
                exe2disp_data_wr <= 1'b0;
                if(exe_dfifo_rdata[133:132] == 2'b10) begin//end of pkt
                    exe_dfifo_rd <= 1'b0;
                    exe_state <= IDLE_S;
                end
                else begin
                    exe_dfifo_rd <= 1'b1;
                    exe_state <= DISCARD_S;
                end
            end

            default: begin
                exe_dfifo_rd <= 1'b0;
                rule_fifo_rd <= 1'b0;
                exe2disp_data_wr <= 1'b0;
                exe2disp_valid_wr <= 1'b0;
                polling_cpuid <= 6'b0;
                exe_state <= IDLE_S;
            end
        endcase
    end
end

always @(posedge clk or negedge rst_n) begin
    if(rst_n == 1'b0) begin
        rule_fifo_rd_dly <= 1'b0;
