module add_sub_ripple_xor_counter (
  input clk,
  input reset,
  input [31:0] a,
  input [31:0] b,
  input sub,
  output [31:0] sum,
  output [3:0] count,
  output [31:0] final_output
);

  // Adder-Subtractor module
  wire [31:0] add_sub_out;
  add_sub add_sub_inst (
    .a(a),
    .b(sub ? ~b : b),
    .sub(sub),
    .out(add_sub_out)
  );

  // Ripple carry adder
  wire [31:0] ripple_carry_out;
  ripple_carry_adder ripple_carry_inst (
    .a(add_sub_out),
    .b({16'd0, count}),
    .cin(sub),
    .out(ripple_carry_out)
  );

  // XOR gate
  wire [31:0] xor_out;
  assign xor_out = sub ? ~b : b;

  // 4-bit binary counter
  reg [3:0] counter;
  always @(posedge clk) begin
    if (reset) begin
      counter <= 4'd0;
    end else begin
      counter <= counter + 1;
    end
  end

  // Functional module
  always @(*) begin
    final_output = add_sub_out & {32{count[3]}};
  end

  // Control logic module
  always @(*) begin
    if (counter == 4'd15) begin
      sum = ripple_carry_out;
      count = counter;
    end else begin
      sum = add_sub_out;
      count = counter;
    end
  end

endmodule

module mgc_pipe (
    input clk,
    input en,
    input arst,
    input srst,
    input ldin,
    output reg vdin,
    output reg [width-1:0] din,
    input ldout,
    output reg vdout,
    output reg [width-1:0] dout,
    output reg [sz_width-1:0] size,
    input req_size
);

    parameter integer rscid   = 0; // resource ID
    parameter integer width   = 8; // fifo width
    parameter integer sz_width = 8; // width of size of elements in fifo
    parameter integer fifo_sz = 8; // fifo depth
    parameter integer log2_sz = 3; // log2(fifo_sz)
    parameter         ph_clk  = 1'b1;  // clock polarity 1=rising edge, 0=falling edge
    parameter         ph_en   = 1'b1;  // clock enable polarity
    parameter         ph_arst = 1'b1;  // async reset polarity
    parameter         ph_srst = 1'b1;  // sync reset polarity
    parameter integer pwropt  = 0; // pwropt

    reg [sz_width-1:0] fifo_size;
    reg [width-1:0] fifo [0: fifo_sz-1];
    reg [log2_sz-1:0] fifo_head;
    reg [log2_sz-1:0] fifo_tail;

    always @(posedge clk or negedge srst) begin
        if (~srst) begin
            fifo_head <= 0;
            fifo_tail <= 0;
            fifo_size <= 0;
            vdin <= 0;
            vdout <= 0;
        end else if (arst) begin
            fifo_head <= 0;
            fifo_tail <= 0;
            fifo_size <= 0;
            vdin <= 0;
            vdout <= 0;
        end else if (en) begin
            if (ldin && (fifo_size < fifo_sz)) begin
                fifo[fifo_head] <= din;
                fifo_head <= (fifo_head + 1) % fifo_sz;
                fifo_size <= fifo_size + 1;
                vdin <= 1;
            end else if (ldin) begin
                vdin <= 0;
            end

            if (ldout && (fifo_size > 0)) begin
                dout <= fifo[fifo_tail];
                fifo_tail <= (fifo_tail + 1) % fifo_sz;
                fifo_size <= fifo_size - 1;
                vdout <= 1;
            end else if (ldout) begin
                vdout <= 0;
            end

            size <= fifo_size;
        end
    end

endmodule

module vending_machine (
    input clk,
    input reset,
    input [1:0] button,
    input [3:0] coin,
    output reg [1:0] dispense,
    output reg [7:0] owed
);

    reg [7:0] price1 = 25;
    reg [7:0] price2 = 50;
    reg [7:0] price3 = 75;
    reg [7:0] price4 = 100;
    reg [7:0] value;

    wire [1:0] dispense_wire;
    assign dispense = dispense_wire;

    wire [7:0] owed_wire;
    assign owed = owed_wire;

    reg [1:0] state, next_state;
    reg [7:0] owed_reg;
    reg [1:0] dispense_reg;
    reg [1:0] button_reg;
    reg [3:0] coin_reg;

    sky130_fd_sc_ls__udp_dff dff0 (.D(reset), .CLK(clk), .Q(state[0]));
    sky130_fd_sc_ls__udp_dff dff1 (.D(state[0]), .CLK(clk), .Q(state[1]));
    sky130_fd_sc_ls__udp_dff dff2 (.D(state[1]), .CLK(clk), .Q(state[2]));
    sky130_fd_sc_ls__udp_dff dff3 (.D(state[2]), .CLK(clk), .Q(state[3]));

    always @(*) begin
        case(state)
            4'b0000: begin
                owed_wire = 8'b0;
                dispense_wire = 2'b00;
                next_state = 4'b0001;
            end
            4'b0001: begin
                owed_reg = 8'b0;
                dispense_reg = 2'b00;
                button_reg = button;
                coin_reg = coin;
                next_state = 4'b0010;
            end
            4'b0010: begin
                value = coin_detector(clk, reset, coin_reg);
                owed_reg = value - price1*button_reg[0] - price2*button_reg[1] - price3*button_reg[0]&button_reg[1] - price4*button_reg[1]&button_reg[0];
                dispense_reg = button_reg;
                if (owed_reg > 0) begin
                    next_state = 4'b0011;
                end
                else begin
                    next_state = 4'b0001;
                end
            end
            4'b0011: begin
                value = coin_detector(clk, reset, coin_reg);
                owed_reg = owed_reg - value;
                if (owed_reg > 0) begin
                    next_state = 4'b0011;
                end
                else begin
                    next_state = 4'b0001;
                end
            end
        endcase
    end

    always @(posedge clk) begin
        if (reset) begin
            state <= 4'b0000;
        end
        else begin
            state <= next_state;
            owed_reg <= owed_reg;
            dispense_reg <= dispense_reg;
            button_reg <= button_reg;
            coin_reg <= coin_reg;
        end
    end

    always @(*) begin
        owed_wire = owed_reg;
        dispense_wire = dispense_reg;
    end

endmodule

module coin_detector (
    input clk,
    input reset,
    input [3:0] coin,
    output reg [7:0] value
);

    reg [7:0] value_reg;

    always @(posedge clk) begin
        if (reset) begin
            value_reg <= 8'b0;
        end
        else begin
            value_reg <= value_reg + 5*coin[0] + 10*coin[1] + 25*coin[2];
        end
    end

    assign value = value_reg;

endmodule

module bus_hold_block (
  input in,
  output out
);

  reg prev_state;

  always @(in) begin
    if (in === 1'b0 || in === 1'b1) begin
      prev_state <= in;
      out <= in;
    end
  end

  always @(*) begin
    if (in === 1'bx) begin
      out <= prev_state;
    end
  end

endmodule

module alu_32bit (
    input [31:0] A,
    input [31:0] B,
    input [2:0] OPCODE,
    input CIN,
    output reg COUT,
    output reg [31:0] Y
);

    always @(*) begin
        case(OPCODE)
            3'b000: Y = A + B + CIN;
            3'b001: Y = A - B - ~CIN;
            3'b010: Y = A & B;
            3'b011: Y = A | B;
            3'b100: Y = A ^ B;
            3'b101: Y = A << B;
            3'b110: Y = A >> B;
            default: Y = 0;
        endcase
        if(OPCODE[1:0] == 2'b00) begin
            COUT = (Y[31] ^ CIN) & (OPCODE[2] ^ Y[30]);
        end else if(OPCODE[1:0] == 2'b01) begin
            COUT = (A[31] ^ B[31] ^ Y[31]) & (A[31] ^ CIN);
        end else begin
            COUT = 0;
        end
    end

endmodule

