  reg [7:0] rx_data;
  reg [2:0] state;
  reg csb_prev;

  always @(posedge clk) begin
    if (rst) begin
      state <= 3'b000;
      csb_prev <= 1'b1;
      miso <= 1'b1;
      tx_data <= 8'h00;
      rx_data <= 8'h00;
    end
    else begin
      case (state)
        3'b000: begin // Idle state
          if (!csb && csb_prev) begin
            state <= 3'b001;
            tx_data <= 8'h00;
          end
        end
        3'b001: begin // Transmit state
          if (sclk) begin
            miso <= tx_data[7];
            tx_data <= {tx_data[6:0], mosi};
          end
          if (!sclk) begin
            if (tx_data == 8'h00) begin
              state <= 3'b010;
            end
          end
        end
        3'b010: begin // Receive state
          if (sclk) begin
            rx_data <= {rx_data[6:0], miso};
          end
          if (!sclk) begin
            if (rx_data == 8'h00) begin
              state <= 3'b000;
            end
          end
        end
      endcase
      csb_prev <= csb;
    end
  end

endmodule

