		buffer[head] <= d_in;
		head <= (head == 2'd3) ? 2'd0 : head + 2'd1;
		empty_cb <= 1'b0;
		full_cb <= (head == tail) ? 1'b1 : 1'b0;
	end else if (!push_cb && pop_cb && !empty_cb) begin
		d_out <= buffer[tail];
		buffer[tail] <= 8'd0;
		tail <= (tail == 2'd3) ? 2'd0 : tail + 2'd1;
		full_cb <= 1'b0;
