    output reg out_input_ack,
    output reg out_input_valid,
    output reg [4:0] out_input_cpuid
);

    // Define states
    localparam idle_s = 2'b00;
    localparam wait_s = 2'b01;

    // Define state register and initialize to idle_s
    reg [1:0] current_state = idle_s;

    // Define CPU ID register
    reg [4:0] cpuid_reg;

    always @(posedge clk, negedge reset_n) begin
        if (~reset_n) begin
            out_input_ack <= 1'b0;
            out_input_cpuid <= 5'b0;
            cpuid_reg <= 5'b0;
            out_input_valid <= 1'b0;
            current_state <= idle_s;
        end
        else begin
            case (current_state)
                idle_s: begin
                    out_input_ack <= 1'b0;
                    out_input_cpuid <= 5'b0;
                    cpuid_reg <= 5'b0;
                    out_input_valid <= 1'b0;
                    if (current_cpuid_valid == 1'b1) begin
                        current_state <= wait_s;
                    end
                end
                wait_s: begin
                    if (in_input_ctl == 1'b1) begin
                        out_input_ack <= 1'b1;
                        current_state <= wait_s;
                    end
                    else begin
                        out_input_ack <= 1'b0;
                        if (current_cpuid_valid == 1'b1) begin
                            cpuid_reg <= in_input_cpuid;
                            out_input_cpuid <= in_input_cpuid;
                            out_input_valid <= 1'b1;
                            current_state <= wait_s;
                        end
                        else begin
                            out_input_valid <= 1'b0;
                            current_state <= idle_s;
                        end
                    end
                end
                default: begin
                    out_input_ack <= 1'b0;
                    out_input_cpuid <= 5'b0;
                    cpuid_reg <= 5'b0;
                    out_input_valid <= 1'b0;
                    current_state <= idle_s;
