module booth_multiplier (
    input signed [3:0] A,
    input signed [3:0] B,
    output signed [7:0] product
);

reg signed [7:0] product_reg;
reg [2:0] count;
reg [3:0] B_reg;
reg [3:0] B_neg;

assign product = product_reg;

always @(*) begin
    product_reg = {4'b0, A};
    B_reg = {1'b0, B};
    B_neg = ~B_reg + 1;
    count = 3'b0;

    while(count < 3) begin
        if(B_reg[0] == 1 && B_reg[1] == 0) begin
            product_reg = product_reg + (B_neg << (count+1));
        end
        else if(B_reg[0] == 0 && B_reg[1] == 1) begin
            product_reg = product_reg + (B_reg << (count+1));
        end
        B_reg = {B_reg[2:0], B_reg[3]};
        count = count + 1;
    end
end

endmodule

