module pipeline_splitter(
    input wire [15:0] in,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo
);

    wire [7:0] hi_pipe1;
    wire [7:0] lo_pipe1;
    wire [7:0] hi_pipe2;
    wire [7:0] lo_pipe2;

    // Stage 1
    barrel_shifter bs1(.in(in), .shift_amt(8), .out_hi(hi_pipe1), .out_lo(lo_pipe1));

    // Stage 2
    barrel_shifter bs2(.in(hi_pipe1), .shift_amt(0), .out_hi(hi_pipe2), .out_lo(out_hi));
    barrel_shifter bs3(.in(lo_pipe1), .shift_amt(0), .out_hi(lo_pipe2), .out_lo(out_lo));

endmodule

