    mux2to1 mux_2to1_n0 (.a(D0), .b(D1), .s(S1), .y(mux_2to1_n0_out));
    mux2to1 mux_2to1_n1 (.a(D2), .b(D3), .s(S1), .y(mux_2to1_n1_out));

    // select the output of the two 2-to-1 multiplexers
    mux2to1 mux_2to1_n2 (.a(mux_2to1_n0_out), .b(mux_2to1_n1_out), .s(S0), .y(Y));

endmodule

