module packet_inserter (
    input clk,
    input reset,
    input [7:0] stream_in_data,
    input stream_in_startofpacket,
    input stream_in_endofpacket,
    input stream_in_empty,
    input stream_in_valid,
    output stream_in_ready,
    output [7:0] stream_out_data,
    output stream_out_startofpacket,
    output stream_out_endofpacket,
    output stream_out_empty,
    output stream_out_valid
);

// Internal registers
reg [7:0] data_reg;
reg startofpacket_reg;
reg endofpacket_reg;
reg empty_reg;
reg valid_reg;
reg [1:0] state_reg;
reg [23:0] pattern_reg;

// Output registers
reg [7:0] stream_out_data_reg;
reg stream_out_startofpacket_reg;
reg stream_out_endofpacket_reg;
reg stream_out_empty_reg;
reg stream_out_valid_reg;

// Constants
parameter IDW = 8; // Incoming frame's data width
parameter ODW = 8; // Outcoming frame's data width
parameter IEW = 0; // Incoming frame's empty width
parameter OEW = 0; // Outcoming frame's empty width

// State machine states
localparam IDLE = 2'd0;
localparam WAIT_FOR_DATA = 2'd1;
localparam OUTPUT_PATTERN = 2'd2;

// Combinational logic
assign stream_in_ready = ~valid_reg | (state_reg == WAIT_FOR_DATA);
assign stream_out_data = stream_out_data_reg;
assign stream_out_startofpacket = stream_out_startofpacket_reg;
assign stream_out_endofpacket = stream_out_endofpacket_reg;
assign stream_out_empty = stream_out_empty_reg;
assign stream_out_valid = stream_out_valid_reg;

// Sequential logic
always @(posedge clk) begin
    if (reset) begin
        data_reg <= 8'h00;
        startofpacket_reg <= 1'b0;
        endofpacket_reg <= 1'b0;
        empty_reg <= 1'b0;
        valid_reg <= 1'b0;
        state_reg <= IDLE;
        pattern_reg <= 24'h008000;
        stream_out_data_reg <= 8'h00;
        stream_out_startofpacket_reg <= 1'b0;
        stream_out_endofpacket_reg <= 1'b0;
        stream_out_empty_reg <= 1'b0;
        stream_out_valid_reg <= 1'b0;
    end else begin
        case (state_reg)
            IDLE: begin
                if (stream_in_valid && !empty_reg) begin
                    state_reg <= WAIT_FOR_DATA;
                    data_reg <= stream_in_data;
                    startofpacket_reg <= stream_in_startofpacket;
                    endofpacket_reg <= stream_in_endofpacket;
                    empty_reg <= stream_in_empty;
                    valid_reg <= stream_in_valid;
                end else begin
                    stream_out_data_reg <= 8'h00;
                    stream_out_startofpacket_reg <= 1'b0;
                    stream_out_endofpacket_reg <= 1'b0;
                    stream_out_empty_reg <= 1'b0;
                    stream_out_valid_reg <= 1'b0;
                end
            end
            WAIT_FOR_DATA: begin
                if (stream_in_ready) begin
                    state_reg <= OUTPUT_PATTERN;
                    stream_out_data_reg <= data_reg;
                    stream_out_startofpacket_reg <= startofpacket_reg;
                    stream_out_endofpacket_reg <= endofpacket_reg;
                    stream_out_empty_reg <= empty_reg;
                    stream_out_valid_reg <= valid_reg;
                end else begin
                    stream_out_data_reg <= 8'h00;
                    stream_out_startofpacket_reg <= 1'b0;
                    stream_out_endofpacket_reg <= 1'b0;
                    stream_out_empty_reg <= 1'b0;
                    stream_out_valid_reg <= 1'b0;
                end
            end
            OUTPUT_PATTERN: begin
                state_reg <= IDLE;
                stream_out_data_reg <= pattern_reg[ODW-1:ODW-8] & data_reg;
                stream_out_startofpacket_reg <= startofpacket_reg;
                stream_out_endofpacket_reg <= endofpacket_reg;
                stream_out_empty_reg <= empty_reg;
                stream_out_valid_reg <= valid_reg;
            end
        endcase
    end
end

endmodule

module pulse_gen(
    input CLK,
    input RST,
    input START,
    input [15:0] DURATION,
    output reg PULSE
);

reg [15:0] count;

always @(posedge CLK) begin
    if (RST) begin
        count <= 0;
        PULSE <= 0;
    end
    else if (START) begin
        if (count < DURATION) begin
            count <= count + 1;
            PULSE <= 1;
        end
        else begin
            count <= 0;
            PULSE <= 0;
        end
    end
    else begin
        count <= 0;
        PULSE <= 0;
    end
end

endmodule

