module priority_encoder (
    input [7:0] in,
    output reg [2:0] pos );

    wire [7:0] gray_code;
    wire [2:0] decimal_code;
    wire [2:0] next_pos;

    // Binary-to-Gray code converter
    gray_code_converter gray_code_inst (
        .bin(in),
        .gray(gray_code)
    );

    // Gray-to-binary decoder
    gray_to_bin_decoder decoder_inst (
        .gray(gray_code),
        .bin(decimal_code)
    );

    // Pipeline registers
    always @(posedge clk) begin
        pos <= next_pos;
    end

    always @(posedge clk) begin
        next_pos <= decimal_code;
    end

endmodule

// Binary-to-Gray code converter
module gray_code_converter (
    input [7:0] bin,
    output reg [7:0] gray );

    always @(*) begin
        gray[0] = bin[0];
        gray[1] = bin[1] ^ bin[0];
        gray[2] = bin[2] ^ bin[1];
        gray[3] = bin[3] ^ bin[2];
        gray[4] = bin[4] ^ bin[3];
        gray[5] = bin[5] ^ bin[4];
        gray[6] = bin[6] ^ bin[5];
        gray[7] = bin[7] ^ bin[6];
    end

endmodule

// Gray-to-binary decoder
module gray_to_bin_decoder (
    input [7:0] gray,
    output reg [2:0] bin );

    always @(*) begin
        case (gray)
            3'b000: bin = 3'b000;
            3'b001: bin = 3'b001;
            3'b011: bin = 3'b010;
            3'b010: bin = 3'b011;
            3'b110: bin = 3'b100;
            3'b111: bin = 3'b101;
            3'b101: bin = 3'b110;
            3'b100: bin = 3'b111;
            default: bin = 3'b000;
        endcase
    end

endmodule

module arriaiigz_lvds_rx_fifo (
                           wclk,
                           rclk,
                           dparst,
                           fiforst,
                           datain,
                           dataout
                          );

    parameter channel_width = 10;

    // INPUT PORTS
    input wclk;
    input rclk;
    input dparst;
    input fiforst;
    input [channel_width-1:0] datain;

    // OUTPUT PORTS
    output [channel_width-1:0] dataout;

    // INTERNAL VARIABLES AND NETS
    reg [channel_width-1:0] dataout_tmp;
    wire [channel_width-1:0] data_out;

    integer i;
    reg [2:0] wrPtr,rdPtr;        // writer pointer, read pointer
    wire [2:0] rdAddr;             // read address
    reg ram_we;

    reg wclk_last_value, rclk_last_value;
    reg write_side_sync_reset;
    reg read_side_sync_reset;

    arriaiigz_lvds_rx_fifo_sync_ram  s_fifo_ram (
                                             .clk(wclk),
                                             .datain(ram_datain),
                                             .write_reset(write_side_sync_reset),
                                             .waddr(wrPtr),
                                             .raddr(rdAddr),
                                             .we(ram_we),
                                             .dataout(ram_dataout)
                                            );

    initial
    begin
        dataout_tmp = 0;
        wrPtr = 3'b000;
        rdPtr = 3'b000;
        write_side_sync_reset = 1'b0;
        read_side_sync_reset = 1'b0;
    end

    assign rdAddr = rdPtr;

    always @(wclk or dparst or fiforst)
    begin
        if (dparst || fiforst)
        begin
            write_side_sync_reset <= 1'b1;
            rdPtr <= 3'b000;
            wrPtr <= 3'b000;
            ram_we <= 1'b0;
            for (i = 0; i < 6; i = i + 1)
                s_fifo_ram.ram[i] <= {channel_width{1'b0}};
        end
        else if (write_side_sync_reset)
            write_side_sync_reset <= 1'b0;

        if (wclk && !write_side_sync_reset && !fiforst && !dparst && (wrPtr != rdPtr || ram_we == 1'b0))
        begin
            s_fifo_ram.ram[wrPtr] <= datain;
            wrPtr <= wrPtr + 1;
            if (wrPtr == 3'b110)
                wrPtr <= 3'b000;
            ram_we <= 1'b1;
        end
    end

    always @(rclk or dparst or fiforst)
    begin
        if (dparst || fiforst)
        begin
            read_side_sync_reset <= 1'b1;
            rdPtr <= 3'b000;
            dataout_tmp <= {channel_width{1'b0}};
        end
        else if (read_side_sync_reset)
            read_side_sync_reset <= 1'b0;

        if (rclk && !read_side_sync_reset && !fiforst && !dparst && (wrPtr != rdPtr || ram_we == 1'b1))
        begin
            dataout_tmp <= s_fifo_ram.ram[rdPtr];
            rdPtr <= rdPtr + 1;
            if (rdPtr == 3'b110)
                rdPtr <= 3'b000;
        end
    end

    assign data_out = dataout_tmp;

    buf (dataout, data_out);

endmodule

module arriaiigz_lvds_rx_fifo_sync_ram (
                                        clk,
                                        datain,
                                        write_reset,
                                        waddr,
                                        raddr,
                                        we,
                                        dataout
                                       );

    parameter channel_width = 10;
    parameter depth = 6;

    input clk;
    input [channel_width-1:0] datain;
    input write_reset;
    input [2:0] waddr;
    input [2:0] raddr;
    input we;
    output [channel_width-1:0] dataout;

    reg [channel_width-1:0] ram [0:depth-1];

    assign dataout = ram[raddr];

    always @(posedge clk)
    begin
        if (write_reset)
            ram[waddr] <= {channel_width{1'b0}};
        else if (we)
            ram[waddr] <= datain;
    end

endmodule

module batt_mng (
  input en,
  input rst,
  input [n-1:0] vbat,
  output chg,
  output dis,
  output [m-1:0] bstat
);

parameter n = 8; // number of bits for battery voltage
parameter m = 4; // number of bits for battery status

reg [n-1:0] charge_threshold = 8'b10000000; // charge threshold
reg [n-1:0] charge_stop = 8'b11111111; // charge stop threshold
reg [n-1:0] discharge_threshold = 8'b01000000; // discharge threshold
reg [n-1:0] discharge_stop = 8'b00000000; // discharge stop threshold
reg [m-1:0] status; // battery status

reg charging; // charging status
reg discharging; // discharging status

reg [n-1:0] charge_timer; // charge timer
reg [n-1:0] discharge_timer; // discharge timer

always @(posedge clk) begin
  if (rst) begin
    charging <= 0;
    discharging <= 0;
    charge_timer <= 0;
    discharge_timer <= 0;
    status <= 0;
  end else if (en) begin
    // Charge management block
    if (vbat < charge_threshold) begin
      charging <= 1;
      if (charge_timer < charge_stop) begin
        charge_timer <= charge_timer + 1;
      end else begin
        charging <= 0;
        charge_timer <= 0;
      end
    end else begin
      charging <= 0;
      charge_timer <= 0;
    end

    // Discharge management block
    if (vbat > discharge_threshold) begin
      discharging <= 1;
      if (discharge_timer < discharge_stop) begin
        discharge_timer <= discharge_timer + 1;
      end else begin
        discharging <= 0;
        discharge_timer <= 0;
      end
    end else begin
      discharging <= 0;
      discharge_timer <= 0;
    end

    // Battery monitoring block
    if (vbat > 8'b11000000) begin
      status <= 4'b1111;
    end else if (vbat > 8'b10000000) begin
      status <= 4'b0111;
    end else if (vbat > 8'b01000000) begin
      status <= 4'b0011;
    end else if (vbat > 8'b00000000) begin
      status <= 4'b0001;
    end else begin
      status <= 4'b0000;
    end
  end else begin
    charging <= 0;
    discharging <= 0;
    charge_timer <= 0;
    discharge_timer <= 0;
    status <= 0;
  end
end

assign chg = charging;
assign dis = discharging;
assign bstat = status;

endmodule

module digital_circuit(
    input D,
    input GATE_N,
    input VPWR,
    input VGND,
    input VPB,
    input VNB,
    input clk,
    output reg Q
);

reg Q_reg;
wire clock_edge;

assign clock_edge = clk & ~Q_reg;

always @(posedge clock_edge) begin
    if (!GATE_N) begin
        Q_reg <= D;
    end
end

always @(GATE_N or VPWR or VGND or VPB or VNB) begin
    if (GATE_N) begin
        Q = 1'b0;
    end else begin
        Q = Q_reg;
    end
end

endmodule

module all_case (
	clk_in, rst, pa, pb, pc, ddd, ddd0, sell,
	clk0, clk1, clk2, clk3,
	rst0, rst1, rst2, rst3,
	p0, p1, p2, p00, p01, p02, ps, pd, ph,
	df, df_0, sel_o
);

	input clk_in, rst, pa, pb, pc, ddd, ddd0;
	input [1:0] sell;
	output clk0, clk1, clk2, clk3;
	output rst0, rst1, rst2, rst3;
	output p0, p1, p2, p00, p01, p02, ps, pd, ph;
	output df, df_0;
	output [1:0] sel_o;

	wire clk_in, rst, pa, pb, pc, ddd, ddd0;
	reg clk0, clk1, clk2, clk3;
	reg rst0, rst1, rst2, rst3;
	reg p0, p1, p2, p00, p01, p02, ps, pd, ph;
	reg df, df_0;

	always @ (sell)
	begin
		case (sell)
			2'b00:
			begin
				clk0 = clk_in;
				rst0 = rst;
				p0 = pa;
				p1 = pb;
				p2 = pc;
				clk1 = 0;
				rst1 = 1;
				p00 = 1;
				p01 = 1;
				p02 = 1;
				clk2 = 0;
				rst2 = 0;
				ps = 1;
				pd = 1;
				ph = 1;
				df = 0;
				df_0 = 0;
				clk3 = 0;
				rst3 = 0;
			end
			2'b01:
			begin
				clk1 = clk_in;
				rst1 = rst;
				p00 = pa;
				p01 = pb;
				p02 = pc;
				clk0 = clk_in;
				rst0 = 1;
				p0 = 1;
				p1 = 1;
				p2 = 1;
				clk2 = 0;
				rst2 = 0;
				ps = 1;
				pd = 1;
				ph = 1;
				df = 0;
				df_0 = 0;
				clk3 = 0;
				rst3 = 0;
			end
			2'b10:
			begin
				clk2 = clk_in;
				rst2 = rst;
				ps = pa;
