module ripple_carry_adder(
    input [31:0] a,
    input [31:0] b,
    input cin,
    output [31:0] sum,
    output cout
);

    wire [31:0] s;
    wire [31:0] c;

    assign s = a + b + cin;
    assign cout = s[31];
    assign sum = s;

endmodule

module carry_save_adder(
    input [31:0] a,
    input [31:0] b,
    input [31:0] c,
    output [31:0] p,
    output [31:0] g
);

    wire [31:0] p0, p1, p2, p3;
    wire [31:0] g0, g1, g2, g3;

    assign p0 = a & b;
    assign g0 = a | b;
    assign p1 = p0 & c;
    assign g1 = p0 | (c & g0);
    assign p2 = p1 & (c ^ g0);
    assign g2 = p1 | (c & g1);
    assign p3 = p2 & (c ^ g1);
    assign g3 = p2 | (c & g2);

    assign p = p3;
    assign g = g3;

endmodule

module final_adder(
    input [31:0] p,
    input [31:0] g,
    input cin,
    output [31:0] sum
);

    wire [31:0] s;
    wire [31:0] c;

    assign s = p + (g << 1) + cin;
    assign c = g | (p & (g << 1));
    assign sum = s ^ (c << 1);

endmodule

module top_module(
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] sum
);

    wire [31:0] s1, s2;
    wire c1, c2;

    ripple_carry_adder rca(
        .a(a),
        .b(sub ? ~b : b),
        .cin(sub),
        .sum(s1),
        .cout(c1)
    );

    carry_save_adder csa(
        .a(a),
        .b(sub ? ~b : b),
        .c(~sub),
        .p(s2),
        .g(c2)
    );

    final_adder fa(
        .p(s2),
        .g(c2),
        .cin(c1),
        .sum(sum)
    );

endmodule

