module unsigned_divider_non_restoring (
  input [n-1:0] dividend,
  input [n-1:0] divisor,
  output [n-1:0] quotient
);

parameter n = 8; // number of bits for dividend, divisor, and quotient. (n >= 2)

reg [n-1:0] remainder;
reg [n-1:0] shifted_divisor;
reg [n:0] quotient_reg;

integer i;

always @(*) begin
  shifted_divisor = divisor << n;
  remainder = dividend;
  quotient_reg = 0;

  for (i = 0; i < n; i = i + 1) begin
    shifted_divisor = shifted_divisor >> 1;
    remainder = remainder << 1;
    remainder[n] = quotient_reg[n];

    if (remainder >= shifted_divisor) begin
      remainder = remainder - shifted_divisor;
      quotient_reg[n-i-1] = 1;
    end else begin
      quotient_reg[n-i-1] = 0;
    end

    if (i == n-1) begin
      quotient = quotient_reg[0:n-1];
    end
  end
end

endmodule

