    input [15:0] D_16, // 16-bit input for the 16-bit shift register
    input LD_16, // Load input for the 16-bit shift register
    input SH_16, // Shift input for the 16-bit shift register
    output reg [19:0] Q // Output concatenation of the two shift registers
);

reg [3:0] shift_reg_4;
reg [15:0] shift_reg_16;

always @ (posedge SH_4 or negedge SH_4) begin
    if (SH_4) begin
        shift_reg_4 <= {shift_reg_4[2:0], D_4};
    end else begin
        shift_reg_4 <= {D_4, shift_reg_4[3]};
    end
end

always @ (posedge SH_16 or negedge SH_16) begin
    if (SH_16) begin
        shift_reg_16 <= {shift_reg_16[14:0], D_16};
    end else begin
        shift_reg_16 <= {D_16, shift_reg_16[15]};
    end
end

always @ (posedge LD_4 or posedge LD_16) begin
    if (LD_4) begin
        shift_reg_4 <= D_4;
    end
    if (LD_16) begin
        shift_reg_16 <= D_16;
    end
end

assign Q = {shift_reg_16, shift_reg_4};

endmodule

module fifo_buffer(
    input clk,
    input reset,
    input [DATA_WIDTH-1:0] data_in,
    input valid_in,
    input ready_out,
    input ready_in,
    output reg [DATA_WIDTH-1:0] data_out,
    output reg valid_out,
    output reg empty,
    output reg full
);

// Internal parameters
parameter ADDR_WIDTH = $clog2(FIFO_DEPTH);
parameter PTR_WIDTH = ADDR_WIDTH + 1;
parameter MAX_COUNT = (1 << ADDR_WIDTH) - 1;

// Internal signals
reg [DATA_WIDTH-1:0] fifo [0:MAX_COUNT];
reg [PTR_WIDTH-1:0] head = 0;
reg [PTR_WIDTH-1:0] tail = 0;
reg [PTR_WIDTH-1:0] count = 0;

// Write logic
always @(posedge clk) begin
    if (reset) begin
        head <= 0;
        tail <= 0;
        count <= 0;
        valid_out <= 0;
        empty <= 1;
        full <= 0;
    end else begin
        if (valid_in && ready_out && count < FIFO_DEPTH) begin
            fifo[head] <= data_in;
            head <= head + 1;
            count <= count + 1;
            empty <= 0;
            if (count == FIFO_DEPTH) begin
                full <= 1;
            end
        end
        valid_out <= (count > 0) && ready_in;
    end
end

// Read logic
always @(posedge clk) begin
    if (reset) begin
        data_out <= 0;
    end else begin
        if (valid_out && ready_in) begin
            data_out <= fifo[tail];
            tail <= tail + 1;
            count <= count - 1;
            full <= 0;
            if (count == 1) begin
                empty <= 1;
            end
        end
    end
end

endmodule

