module uart_tx(
    input reset,
    input tx_access,
    input [7:0] tx_data,
    input tx_valid,
    input clk,
    output reg tx_busy,
    output reg tx_complete,
    output reg [7:0] tx_data_out,
    output reg tx_error
);

    parameter BAUD_RATE = 115200;
    parameter CLK_FREQ = 50000000; // Assume 50 MHz clock

    reg [31:0] counter;
    reg [3:0] bit_counter;
    reg start_bit;
    reg [7:0] data_reg;
    reg tx_in_progress;
    reg tx_error_reg;

    assign tx_data_out = data_reg;

    always @(posedge clk) begin
        if (reset) begin
            counter <= 0;
            bit_counter <= 0;
            start_bit <= 1'b0;
            data_reg <= 0;
            tx_busy <= 1'b0;
            tx_complete <= 1'b0;
            tx_error_reg <= 1'b0;
            tx_error <= 1'b0;
            tx_in_progress <= 1'b0;
        end else begin
            if (tx_valid && tx_access && !tx_in_progress) begin
                tx_busy <= 1'b1;
                tx_in_progress <= 1'b1;
                data_reg <= tx_data;
                start_bit <= 1'b0;
                bit_counter <= 0;
                counter <= CLK_FREQ / BAUD_RATE;
            end

            if (tx_in_progress) begin
                if (counter == 0) begin
                    if (bit_counter == 0) begin
                        start_bit <= 1'b1;
                        tx_error_reg <= 1'b0;
                    end else if (bit_counter <= 8) begin
                        data_reg <= {data_reg[6:0], 1'b0};
                        if (tx_data[bit_counter - 1] == 1'b1) begin
                            data_reg <= {data_reg[6:0], 1'b1};
                        end
                        tx_error_reg <= tx_error_reg | (data_reg[7] ^ tx_data[bit_counter - 1]);
                    end else if (bit_counter == 9) begin
                        data_reg <= {data_reg[6:0], 1'b1};
                    end else if (bit_counter == 10) begin
                        tx_complete <= 1'b1;
                        tx_busy <= 1'b0;
                        tx_in_progress <= 1'b0;
                        tx_error <= tx_error_reg;
                    end
                    bit_counter <= bit_counter + 1;
                    counter <= CLK_FREQ / BAUD_RATE;
                end else begin
                    counter <= counter - 1;
                end
            end
        end
    end

endmodule

module rem_charmatch
    (
    clk,
    rst,
    config_valid,
    config_char,
    config_chained,
    input_valid,
    input_char,
    prev_matched,
    this_matched
    );


  input clk;
  input rst;

  input config_valid;
  input [7:0] config_char;
  input       config_chained;

  input       input_valid;
  input [7:0] input_char;

  input       prev_matched;
  output      this_matched;

  reg         char_match;
  reg [7:0]   char_data;
  reg         is_chained;


  assign this_matched = char_match;

  always @(posedge clk)
  begin

    if(rst) begin
      char_data <= 0;
      char_match <= 0;
    end    
    else begin      

      if (input_valid==1) begin

        if (char_data==input_char)
          char_match <= is_chained ? prev_matched : 1;
        else
          char_match <= 0;               

      end

      if (config_valid==1) begin
        char_data <= config_char;
        is_chained <= config_chained;
        char_match <= 0;
      end


    end              	     
  end

endmodule

