    reg [3:0] Temp;
    reg Carry;

    always @ (A or B or Carry) begin
        Temp = A ^ B ^ Carry;
        Cout = (A & B) | (Carry & (A ^ B));
        Carry = (A & B) | (Carry & (A ^ B));
        Sum = Temp;
    end

endmodule

module binary_adder(
