module Ethernet_MAC (
  input clk,
  input reset,
  // Transmitter inputs
  input tx_frame_valid,
  input [7:0] tx_data,
  input [31:0] tx_frame_length,
  input tx_start_of_frame,
  input tx_end_of_frame,
  // Transmitter outputs
  output tx_frame_ready,
  output tx_busy,
  // Receiver inputs
  input rx_frame_valid,
  input [7:0] rx_data,
  input [31:0] rx_frame_length,
  input rx_start_of_frame,
  input rx_end_of_frame,
  // Receiver outputs
  output rx_frame_ready,
  output rx_busy
);

// Define constants
localparam IDLE = 2'b00;
localparam TRANSMITTING = 2'b01;
localparam RECEIVING = 2'b10;

// Define state variables
reg [1:0] tx_state = IDLE;
reg [1:0] rx_state = IDLE;

// Define data packet variables
reg [31:0] tx_packet_length;
reg [31:0] rx_packet_length;
reg [7:0] tx_packet_data [0:31];
reg [7:0] rx_packet_data [0:31];
reg [4:0] tx_packet_index = 0;
reg [4:0] rx_packet_index = 0;

// Define control signals
reg tx_frame_ready = 1'b1;
reg tx_busy = 1'b0;
reg rx_frame_ready = 1'b1;
reg rx_busy = 1'b0;

// Transmitter block
always @(posedge clk) begin
  if (reset) begin
    tx_state <= IDLE;
    tx_packet_index <= 0;
    tx_frame_ready <= 1'b1;
    tx_busy <= 1'b0;
  end else begin
    case (tx_state)
      IDLE: begin
        if (tx_frame_valid) begin
          tx_packet_length <= tx_frame_length;
          tx_packet_data[0] <= tx_data;
          tx_packet_index <= 1;
          tx_frame_ready <= 1'b0;
          tx_busy <= 1'b1;
          tx_state <= TRANSMITTING;
        end
      end
      TRANSMITTING: begin
        if (tx_packet_index < tx_packet_length) begin
          tx_packet_data[tx_packet_index] <= tx_data;
          tx_packet_index <= tx_packet_index + 1;
        end else begin
          tx_frame_ready <= 1'b1;
          tx_busy <= 1'b0;
          tx_state <= IDLE;
        end
      end
    endcase
  end
end

// Receiver block
always @(posedge clk) begin
  if (reset) begin
    rx_state <= IDLE;
    rx_packet_index <= 0;
    rx_frame_ready <= 1'b1;
    rx_busy <= 1'b0;
  end else begin
    case (rx_state)
      IDLE: begin
        if (rx_frame_valid) begin
          rx_packet_length <= rx_frame_length;
          rx_packet_data[0] <= rx_data;
          rx_packet_index <= 1;
          rx_frame_ready <= 1'b0;
          rx_busy <= 1'b1;
          rx_state <= RECEIVING;
        end
      end
      RECEIVING: begin
        if (rx_packet_index < rx_packet_length) begin
          rx_packet_data[rx_packet_index] <= rx_data;
          rx_packet_index <= rx_packet_index + 1;
        end else begin
          rx_frame_ready <= 1'b1;
          rx_busy <= 1'b0;
          rx_state <= IDLE;
        end
      end
    endcase
  end
end

endmodule

