module ripple_carry_adder (
    A    ,
    B    ,
    C_in ,
    CLK  ,
    S    ,
    C_out
);

    input  [3:0] A;
    input  [3:0] B;
    input  C_in;
    input  CLK;
    output [3:0] S;
    output C_out;

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire [3:0] sum;
    wire carry;

    // Full adder module
    // Inputs: A, B, C_in
    // Outputs: sum, carry
    // sum is the 1-bit sum output
    // carry is the 1-bit carry output
    // This module is instantiated four times to create the 4-bit ripple carry adder
    // The carry output of each full adder is connected to the carry input of the next full adder
    // The carry-in input of the first full adder is connected to the C_in input of the ripple carry adder module
    // The carry-out output of the last full adder is the C_out output of the ripple carry adder module
    // The sum output of each full adder is connected to the corresponding bit of the S output of the ripple carry adder module
    // The inputs A, B, and C_in are connected to the corresponding bits of the A, B, and C_in inputs of the ripple carry adder module
    // The CLK input is not used in this module and is not connected
    full_adder fa0(sum[0], carry, A[0], B[0], C_in);
    full_adder fa1(sum[1], carry, A[1], B[1], carry);
    full_adder fa2(sum[2], carry, A[2], B[2], carry);
    full_adder fa3(sum[3], C_out, A[3], B[3], carry);

    // Connect the sum outputs of the full adders to the S output of the ripple carry adder module
    assign S = sum;

endmodule

// Full adder module
// Inputs: A, B, C_in
// Outputs: sum, carry
// sum is the 1-bit sum output
// carry is the 1-bit carry output
// This module is used to create the 4-bit ripple carry adder
module full_adder (
    sum  ,
    carry,
    A    ,
    B    ,
    C_in
);

    output sum;
    output carry;
    input  A;
    input  B;
    input  C_in;

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    assign sum   = A ^ B ^ C_in;
    assign carry = (A & B) | (A & C_in) | (B & C_in);

endmodule

module byte_order_adder (
    input clk,
    input reset,
    input [31:0] data_in1,
    input [31:0] data_in2,
    output [31:0] sum_out
);

    // Byte-order reversing module
    wire [31:0] reversed_data_in1;
    wire [31:0] reversed_data_in2;

    assign reversed_data_in1 = {data_in1[7:0], data_in1[15:8], data_in1[23:16], data_in1[31:24]};
    assign reversed_data_in2 = {data_in2[7:0], data_in2[15:8], data_in2[23:16], data_in2[31:24]};

    // Full adder module
    reg [31:0] carry;
    reg [31:0] sum;

    always @(posedge clk) begin
        if (reset) begin
            carry <= 0;
            sum <= 0;
        end else begin
            {carry, sum} <= reversed_data_in1 + reversed_data_in2 + carry;
        end
    end

    // Byte-order reversing module for output
    assign sum_out = {sum[7:0], sum[15:8], sum[23:16], sum[31:24]};

endmodule

module clk_delay(
    input clk_in,
    output reg clk_out,
    input delay
);

reg [31:0] counter;
reg delay_reached;

always @(posedge clk_in) begin
    if(delay_reached) begin
        counter <= 0;
        delay_reached <= 0;
        clk_out <= 1;
    end
    else if(counter == delay) begin
        delay_reached <= 1;
        clk_out <= 0;
    end
    else begin
        counter <= counter + 1;
        clk_out <= 1;
    end
end

endmodule

