module Video_System_CPU_nios2_avalon_reg (
  // inputs:
  address,
  chipselect,
  clk,
  debugaccess,
  monitor_error,
  monitor_go,
  monitor_ready,
  reset_n,
  write,
  writedata,

  // outputs:
