module top_module (
    input clk,
    input rst_n,
    input up_down,
    input [3:0] load_data,
    input [3:0] b,
    output [3:0] count,
    output reg [2:0] flags
);

    reg [3:0] count_reg;
    wire [3:0] count_out;
    wire equal, greater, less;

    up_down_counter counter_inst (
        .clk(clk),
        .rst_n(rst_n),
        .up_down(up_down),
        .load_data(load_data),
        .count(count_out)
    );

    comparator comparator_inst (
        .a(count_out),
        .b(b),
        .equal(equal),
        .greater(greater),
        .less(less)
    );

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count_reg <= 4'b0000;
            flags <= 3'b000;
        end else begin
            count_reg <= count_out;
            if (up_down) begin
                if (count_out == 4'b1111) begin
                    count_reg <= 4'b0000;
                end else begin
                    count_reg <= count_out + 1;
                end
            end else begin
                if (count_out == 4'b0000) begin
                    count_reg <= 4'b1111;
                end else begin
                    count_reg <= count_out - 1;
                end
            end
            if (equal) begin
                flags <= 3'b001;
            end else if (greater) begin
                flags <= 3'b010;
            end else if (less) begin
                flags <= 3'b100;
            end else begin
                flags <= 3'b000;
            end
        end
    end

    assign count = count_reg;

endmodule

module up_down_counter (
    input clk,
    input rst_n,
    input up_down,
    input [3:0] load_data,
    output reg [3:0] count
);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count <= 4'b0000;
        end else begin
            if (up_down) begin
                if (count == 4'b1111) begin
                    count <= 4'b0000;
                end else begin
                    count <= count + 1;
                end
            end else begin
                if (count == 4'b0000) begin
                    count <= 4'b1111;
                end else begin
                    count <= count - 1;
                end
            end
            if (load_data != count) begin
                count <= load_data;
            end
        end
    end

endmodule

