module barrel_shifter(
    input clk,
    input load,
    input [1:0] ena,
    input [99:0] data,
    output reg [99:0] q,
    output reg [99:0] q_out);

    always @(posedge clk) begin
        if (load) begin
            q <= data;
        end else if (ena == 2'b01) begin
            q <= {q[6:0], q[7]};
        end else if (ena == 2'b10) begin
            q <= {q[1], q[7:2]};
        end else if (ena == 2'b11) begin
            q <= {q[6:0], q[7], q[7:2]};
        end
    end

    always @(posedge clk) begin
        q_out <= q;
    end

endmodule

