module top_module( 
    input a, 
    input b, 
    input cin,
    output cout, 
    output sum,
    output out );

    // Half Adder
    wire ha_sum, ha_carry;
    xor(ha_sum, a, b);
    and(ha_carry, a, b);

    // XNOR Gate using NAND gates
    wire xnor_out;
    nand(xnor_out, a, b);
    nand(xnor_out, xnor_out, xnor_out);
    nand(xnor_out, xnor_out, xnor_out);

    // Final Output Module
    assign sum = ha_sum;
    assign cout = ha_carry;
    assign out = (ha_carry == 1'b0) ? xnor_out : ha_sum;

endmodule

module hyperbolic_functions (
  input x,
  output sineh_x,
  output cosh_x,
  output tanh_x
);

  reg signed [31:0] exp_x;
  reg signed [31:0] exp_neg_x;
  reg signed [31:0] numerator_sineh;
  reg signed [31:0] numerator_cosh;
  reg signed [31:0] numerator_tanh;
  reg signed [31:0] denominator_tanh;

  assign exp_x = $exp(x);
  assign exp_neg_x = $exp(-x);
  assign numerator_sineh = exp_x - exp_neg_x;
  assign numerator_cosh = exp_x + exp_neg_x;
  assign numerator_tanh = exp_x - exp_neg_x;
  assign denominator_tanh = exp_x + exp_neg_x;

  assign sineh_x = numerator_sineh / 2;
  assign cosh_x = numerator_cosh / 2;
  assign tanh_x = numerator_tanh / denominator_tanh;

endmodule

