module adder4(
  output [3:0] S,
  output COUT,
  input [3:0] A,
  input [3:0] B,
  input CIN
);

  wire [3:0] C; // intermediate carry signals

  // Full adder instances
  dffsc fa0 (.Q(S[0]), .D(A[0] ^ B[0] ^ CIN), .CLK(1'b1), .CLR(1'b0));
  dffsc fa1 (.Q(S[1]), .D(A[1] ^ B[1] ^ C[0]), .CLK(1'b1), .CLR(1'b0));
  dffsc fa2 (.Q(S[2]), .D(A[2] ^ B[2] ^ C[1]), .CLK(1'b1), .CLR(1'b0));
  dffsc fa3 (.Q(S[3]), .D(A[3] ^ B[3] ^ C[2]), .CLK(1'b1), .CLR(1'b0));

  // Generate intermediate carry signals
  assign C[0] = (A[0] & B[0]) | (CIN & (A[0] ^ B[0]));
  assign C[1] = (A[1] & B[1]) | (C[0] & (A[1] ^ B[1])) | (CIN & (A[1] ^ B[1]));
  assign C[2] = (A[2] & B[2]) | (C[1] & (A[2] ^ B[2])) | (CIN & (A[2] ^ B[2]));
  assign COUT = (A[3] & B[3]) | (C[2] & (A[3] ^ B[3])) | (CIN & (A[3] ^ B[3]));

endmodule

