  // Initial block
  initial begin
    // Display start of simulation message
    $display(" << Starting the simulation >>");

    // Open output file for writing
    md_fopen = $fopen("output.txt", "w");

    // Check if file can be opened
    if (md_fopen == 0) begin
      $display("Error: Could not open file for writing.");
      $finish;
    end

    // Generate and write 256 bits to output file
    for(count = 0; count < max_amt_of_data; count = count + 1) begin
      // Generate random data bit
      data = $random;

      // Write data bit to output file
      $fdisplay(md_fopen, data);
    end

    // Generate and write last data bit to output file
    data = $random;
    $fdisplay(md_fopen, data);

    // Close output file
    $fclose(md_fopen);

    // Display end of simulation message
    $display(" << Finishing the simulation >>");
    $finish;
  end

endmodule

module sf_camera_controller (
    input                 clk,
    input                 rst,

    //Physical Interface
    output                o_cam_rst,
    output                o_flash,
    input                 i_flash_strobe,

    output                o_cam_in_clk,

    //Configuration Registers
    input                 i_auto_flash,
    input                 i_manual_flash_on,
    input                 i_enable,
    input                 i_camera_reset,

    output                o_clk_locked,

    //Core Controller
    output                o_enable_dma,
    output                o_enable_reader,
    output                o_enable_interrupt
);

    //Local Parameters
    parameter CLK_FREQUENCY = 20_000_000; //20MHz clock frequency

    //Registers/Wires
    reg    [7:0]  config_reg; //8-bit configuration register
    wire          flash_mode; //flash mode signal

    //Submodules
    sf_camera_clk_gen clk_gen(
        .clk              (clk                ),
        .rst              (rst                ),
        .locked           (o_clk_locked       ),
        .phy_out_clk      (o_cam_in_clk       )
    );

    //Asynchronous Logic
    assign  flash_mode         = (i_auto_flash) ? i_flash_strobe : i_manual_flash_on;
    assign  o_flash            = flash_mode;
    assign  o_cam_rst          = i_camera_reset;

    //Synchronous Logic
    always @(posedge clk) begin
        if (rst) begin
            config_reg <= 8'b0; //reset config register
            o_enable_dma <= 1'b0; //disable DMA
            o_enable_reader <= 1'b0; //disable reader
            o_enable_interrupt <= 1'b0; //disable interrupt
        end else begin
            config_reg <= {i_auto_flash, i_manual_flash_on, i_enable, i_camera_reset}; //update config register
            o_enable_dma <= config_reg[0]; //enable DMA if bit 0 is set
            o_enable_reader <= config_reg[1]; //enable reader if bit 1 is set
            o_enable_interrupt <= config_reg[2]; //enable interrupt if bit 2 is set
        end
    end

endmodule

//20MHz Clock Generator
module sf_camera_clk_gen (
    input                 clk,
    input                 rst,
    output                locked,
    output                phy_out_clk
);

    //Local Parameters
    parameter CLK_FREQUENCY = 20_000_000; //20MHz clock frequency

    //Registers/Wires
    reg    [31:0]  counter; //32-bit counter
    wire           clk_divider; //clock divider signal
    wire           clk_out; //clock output signal

    //Clock Divider
    assign clk_divider = (counter == (CLK_FREQUENCY/2 - 1)); //divide clock by 2
    assign clk_out = clk & clk_divider; //generate output clock

    //Locked Signal
    assign locked = (counter == (CLK_FREQUENCY/2 - 1)); //assert locked signal when counter reaches half period

    //Counter
    always @(posedge clk or negedge rst) begin
        if (!rst) begin
            counter <= 32'd0; //reset counter
        end else begin
            counter <= counter + 1; //increment counter
        end
    end

    //Output Clock
    assign phy_out_clk = clk_out;

endmodule

