module Computer_System_Video_In_Subsystem_Video_In_Scaler (
    // Inputs
    clk,
    reset,

    stream_in_data,
    stream_in_startofpacket,
    stream_in_endofpacket,
    stream_in_empty,
    stream_in_valid,

    stream_out_ready,

    // Outputs
    stream_in_ready,


    stream_out_channel,
    stream_out_data,
    stream_out_startofpacket,
    stream_out_endofpacket,
    stream_out_empty,
    stream_out_valid
);

/*****************************************************************************
 *                           Parameter Declarations                          *
 *****************************************************************************/

parameter CW                    = 0; // Frame's Channel Width
parameter DW                    = 15; // Frame's Data Width
parameter EW                    = 0; // Frame's Empty Width

parameter WIW                   = 9; // Incoming frame's width's address width
parameter HIW                   = 7; // Incoming frame's height's address width
parameter WIDTH_IN             = 640;

parameter WIDTH_DROP_MASK    = 4'b0101;
parameter HEIGHT_DROP_MASK    = 4'b0000;

parameter MH_WW                = 8; // Multiply height's incoming width's address width
parameter MH_WIDTH_IN        = 320; // Multiply height's incoming width
parameter MH_CW                = 0; // Multiply height's counter width

parameter MW_CW                = 0; // Multiply width's counter width

/*****************************************************************************
 *                             Port Declarations                             *
 *****************************************************************************/

// Inputs
input                       clk;
input                       reset;

input           [DW: 0]    stream_in_data;
input                       stream_in_startofpacket;
input                       stream_in_endofpacket;
input           [EW: 0]    stream_in_empty;
input                       stream_in_valid;

input                       stream_out_ready;

// Bidirectional

// Outputs
output                  stream_in_ready;

output      [CW: 0]    stream_out_channel;
output      [DW: 0]    stream_out_data;
output                  stream_out_startofpacket;
output                  stream_out_endofpacket;
output      [EW: 0]    stream_out_empty;
output                  stream_out_valid;

/*****************************************************************************
 *                           Constant Declarations                           *
 *****************************************************************************/


/*****************************************************************************
 *                 Internal Wires and Registers Declarations                 *
 *****************************************************************************/

// Internal Wires
wire            [CW: 0]    internal_channel;
wire            [DW: 0]    internal_data;
wire                        internal_startofpacket;
wire                        internal_endofpacket;
wire                        internal_valid;

wire                        internal_ready;

// Internal Registers
reg             [DW: 0]    pixel_buffer [0: WIDTH_IN-1];
reg             [DW: 0]    pixel_out;
reg             [WIW-1: 0]    width_counter;
reg             [MW_CW-1: 0]    width_multiplier;
reg             [MH_CW-1: 0]    height_multiplier;
reg             [HIW-1: 0]    height_counter;
reg                         start_of_frame;
reg                         end_of_frame;

// State Machine Registers
reg                         state;

// Integers
integer                     width_drop = WIDTH_DROP_MASK[3:0];
integer                     height_drop = HEIGHT_DROP_MASK[3:0];

/*****************************************************************************
 *                         Finite State Machine(s)                           *
 *****************************************************************************/

localparam IDLE = 2'b00;
localparam PROCESS_PIXELS = 2'b01;

always @(posedge clk) begin
    if (reset) begin
        state <= IDLE;
    end else begin
        case (state)
            IDLE: begin
                if (stream_in_valid && stream_out_ready) begin
                    state <= PROCESS_PIXELS;
                    width_counter <= 0;
                    height_counter <= 0;
                    width_multiplier <= 0;
                    height_multiplier <= 0;
                    start_of_frame <= stream_in_startofpacket;
                    end_of_frame <= stream_in_endofpacket;
                end else begin
                    state <= IDLE;
                end
            end
            PROCESS_PIXELS: begin
                if (width_counter == WIDTH_IN - 1) begin
                    width_counter <= 0;
                    height_counter <= height_counter + 1;
                    height_multiplier <= height_counter * MH_WIDTH_IN;
                end else begin
                    width_counter <= width_counter + 1;
                    width_multiplier <= width_counter * width_drop;
                end
                if (height_counter == (WIDTH_IN / width_drop) - 1) begin
                    if (end_of_frame) begin
                        state <= IDLE;
                        internal_valid <= 1;
                        internal_startofpacket <= start_of_frame;
                        internal_endofpacket <= end_of_frame;
                        internal_data <= pixel_out;
                        internal_channel <= 0;
                        pixel_out <= 0;
                        stream_in_ready <= 1;
                    end else begin
                        height_counter <= 0;
                        height_multiplier <= 0;
                    end
                end else begin
                    pixel_buffer[width_counter][DW: 0] <= stream_in_data;
                end
                if (width_counter % width_drop == 0 && height_counter % height_drop == 0) begin
                    pixel_out <= pixel_buffer[width_counter][DW: 0];
                    stream_out_data <= pixel_out;
                    stream_out_startofpacket <= start_of_frame;
                    stream_out_endofpacket <= end_of_frame;
                    stream_out_empty <= 0;
                    stream_out_valid <= 1;
                    if (width_counter == WIDTH_IN - 1) begin
                        stream_out_channel <= internal_channel;
                    end else begin
                        stream_out_channel <= 0;
                    end
                    if (stream_out_ready) begin
                        internal_channel <= internal_channel + 1;
                    end
                end else begin
                    stream_out_empty <= 1;
                    stream_out_valid <= 0;
                end
            end
        endcase
    end
end

/*****************************************************************************
 *                             Sequential Logic                              *
 *****************************************************************************/

// Output Registers

// Internal Registers

/*****************************************************************************
 *                            Combinational Logic                            *
 *****************************************************************************/

// Output Assignments
assign stream_out_empty       = 'h0;

// Internal Assignments
assign internal_ready         = stream_in_ready;

/*****************************************************************************
 *                              Internal Modules                             *
 *****************************************************************************/

endmodule

module PLL_DLL (
  input [n-1:0] ref,
  input [n-1:0] ctrl,
  output reg [m-1:0] out_pll,
  output reg [m-1:0] out_dll
);

parameter n = 8; // number of bits in the reference signal and control signal
parameter m = 8; // number of bits in the output signal
parameter k = 10; // multiplication factor for the PLL
parameter d = 100; // delay for the DLL

// Phase Locked Loop (PLL)
reg [m-1:0] vco_out;
reg [n-1:0] phase_diff;
reg [n-1:0] charge_pump_out;
reg [n-1:0] ctrl_int;
reg [n-1:0] ref_int;

// Delay Locked Loop (DLL)
reg [n-1:0] ref_delayed;
reg [n-1:0] phase_diff_dll;
reg [n-1:0] ctrl_int_dll;

// Phase Detector
always @(posedge ref or posedge vco_out) begin
  phase_diff <= ref - vco_out;
end

// Charge Pump
always @(posedge phase_diff) begin
  if (phase_diff > 0) begin
    charge_pump_out <= charge_pump_out + 1;
  end else if (phase_diff < 0) begin
    charge_pump_out <= charge_pump_out - 1;
  end
end

// Voltage Controlled Oscillator (VCO)
always @(posedge charge_pump_out) begin
  vco_out <= vco_out + k;
end

// Feedback Loop
always @(posedge vco_out) begin
  ctrl_int <= ctrl_int + charge_pump_out;
  ref_int <= ref_int + ref;
  out_pll <= vco_out;
end

// Delay Line
always @(posedge ref) begin
  ref_delayed <= #d ref;
end

// Phase Detector
always @(posedge ref_delayed or posedge out_dll) begin
  phase_diff_dll <= ref_delayed - out_dll;
end

// Feedback Loop
always @(posedge out_dll) begin
  ctrl_int_dll <= ctrl_int_dll + phase_diff_dll;
  out_dll <= out_dll + ctrl_int_dll;
end

endmodule

