module CrYCb2RGB (
  input clk,
  input CrYCb_vs,
  input CrYCb_hs,
  input CrYCb_de,
  input [23:0] CrYCb_data,
  output RGB_vs,
  output RGB_hs,
  output RGB_de,
  output [23:0] RGB_data
);

  reg RGB_vs = 0;
  reg RGB_hs = 0;
  reg RGB_de = 0;
  reg [23:0] RGB_data = 0;

  wire [7:0] Y;
  wire [7:0] Cr;
  wire [7:0] Cb;

  assign Y = CrYCb_data[23:16];
  assign Cr = CrYCb_data[15:8];
  assign Cb = CrYCb_data[7:0];

  wire [7:0] R;
  wire [7:0] G;
  wire [7:0] B;

  assign R = (1.164 * (Y - 16)) + (1.596 * (Cr - 128));
  assign G = (1.164 * (Y - 16)) - (0.813 * (Cr - 128)) - (0.392 * (Cb - 128));
  assign B = (1.164 * (Y - 16)) + (2.017 * (Cb - 128));

  always @(posedge clk) begin
    if (CrYCb_de) begin
      RGB_vs <= CrYCb_vs;
      RGB_hs <= CrYCb_hs;
      RGB_de <= 1;
      RGB_data <= {R,G,B};
    end
    else begin
      RGB_de <= 0;
    end
  end

endmodule

module dual_port_ram (
    clka, cena_i, oena_i, wena_i, addra_i, dataa_i, dataa_o,
    clkb, cenb_i, oenb_i, wenb_i, addrb_i, datab_i, datab_o
);

    parameter Word_Width = 32;
    parameter Addr_Width = 6;

    input clka, clkb;
    input cena_i, oena_i, wena_i;
    input cenb_i, oenb_i, wenb_i;
    input [Addr_Width-1:0] addra_i, addrb_i;
    input [Word_Width-1:0] dataa_i, datab_i;
    output [Word_Width-1:0] dataa_o, datab_o;

    reg [Word_Width-1:0] mem_array[(1<<Addr_Width)-1:0];
    reg [Word_Width-1:0] dataa_r, datab_r;

    always @(posedge clka) begin
        if (!cena_i && !wena_i)
            mem_array[addra_i] <= dataa_i;
    end

    always @(posedge clka) begin
        if (!cena_i && wena_i)
            dataa_r <= mem_array[addra_i];
        else
            dataa_r <= 'bx;
    end

    assign dataa_o = oena_i ? 'bz : dataa_r;

    always @(posedge clkb) begin
        if (!cenb_i && !wenb_i)
            mem_array[addrb_i] <= datab_i;
    end

    always @(posedge clkb) begin
        if (!cenb_i && wenb_i)
            datab_r <= mem_array[addrb_i];
        else
            datab_r <= 'bx;
    end

    assign datab_o = oenb_i ? 'bz : datab_r;

endmodule

