module chatgpt_generate_edge_detect(
  input               clk,
  input               rst_n,
  input               A,
  output reg          rise,
  output reg          down
);

  reg prev_A;

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      prev_A <= 1'b0;
      rise <= 1'b0;
      down <= 1'b0;
    end
    else begin
      if (A != prev_A) begin
        if (A == 1'b1) begin
          rise <= 1'b1;
          down <= 1'b0;
        end
        else begin
          rise <= 1'b0;
          down <= 1'b1;
        end
      end
      else begin
        rise <= 1'b0;
        down <= 1'b0;
      end
      prev_A <= A;
    end
  end

endmodule

module up_down_counter (
    input clk,
    input reset,
    input load,
    input up_down,
    input [3:0] data_in,
    output reg [3:0] count_out
);

reg [3:0] count_reg1, count_reg2;

always @(posedge clk) begin
    if (reset) begin
        count_reg1 <= 4'b0;
        count_reg2 <= 4'b0;
    end
    else if (load) begin
        count_reg1 <= data_in;
        count_reg2 <= count_reg1;
    end
    else begin
        count_reg1 <= up_down ? count_reg2 + 4'b1 : count_reg2 - 4'b1;
        count_reg2 <= count_reg1;
    end
end

assign count_out = count_reg2;

endmodule

module altfp_add_sub0 (
    aclr,
    clock,
    dataa,
    datab,
    result
);

input aclr;
input clock;
input [31:0] dataa;
input [31:0] datab;
output [31:0] result;

reg [31:0] sum;
reg [31:0] diff;

always @(posedge clock or negedge aclr) begin
    if (!aclr) begin
        sum <= 0;
        diff <= 0;
    end else begin
        if (dataa[31] == 1) begin
            sum <= ~(dataa ^ datab) + 1;
            diff <= ~(dataa + datab) + 1;
        end else begin
            sum <= dataa + datab;
            diff <= dataa - datab;
        end
    end
end

assign result = (dataa[31] == datab[31]) ? sum : diff;

endmodule

module fib
#(
  parameter N_IN  = 7,
  parameter N_OUT = 90
)
(
  input  wire             rst_n,
  input  wire             clk,
  input  wire             req,
  input  wire [N_IN-1:0]  n,
  output reg              ack,
  output reg  [N_OUT-1:0] result
);

localparam
  INIT          = 2'b00,
  WAIT_REQ      = 2'b01,
  CALC          = 2'b10,
  WAIT_REQ_FALL = 2'b11;

reg [1:0]       state;
reg [N_IN-1:0]  n_reg;
reg [N_OUT-1:0] n_m1;
reg [N_OUT-1:0] n_m2;
reg [N_IN-1:0]  cnt;

always @(posedge clk or negedge rst_n) begin
  if(~rst_n) begin
    state  <= INIT;
    n_reg  <= 0;
    n_m1   <= 0;
    n_m2   <= 0;
    cnt    <= 0;
    ack    <= 0;
    result <= 0;
  end else begin
    case(state)
      INIT         :begin
        state <= #1 WAIT_REQ;
      end
      WAIT_REQ     :begin
        if( req) begin
          state  <= #1 CALC;
          n_reg  <= #1 n;
          n_m1   <= #1 1;
          n_m2   <= #1 0;
          cnt    <= #1 0;
          ack    <= #1 0;
          result <= #1 0;
        end
      end
      CALC         :begin
        if(cnt == (n_reg-1)) begin
          state  <= #1 WAIT_REQ_FALL;
          result <= #1 n_m1;
        end else begin
          n_m1 <= #1 n_m1 + n_m2;
          n_m2 <= #1 n_m1;
          cnt  <= #1 cnt + 1;
        end
      end
      WAIT_REQ_FALL:begin
        if(~req)
          state <= #1 WAIT_REQ;
        ack <= #1 1;
      end
      default      :begin
        state <= 2'bxx;
      end
    endcase
  end
end

endmodule

