module rotator_module (
    input clk,
    input [7:0] d, // 8-bit input for the rotator module
    input load, // Synchronous load input for the rotator module
    input [1:0] ena, // Synchronous enable input for the rotator module
    output reg [7:0] q // 8-bit output from the rotator module
);

    reg [7:0] shifted_out;
    reg [2:0] shift_amount;
    reg [7:0] shifted_in;

    always @(posedge clk) begin
        if (load) begin
            q <= d;
            shifted_out <= d;
            shift_amount <= 3'b0;
        end else if (ena == 2'b01) begin // Rotate right
            shifted_in[7:3] <= shifted_out[2:0];
            shifted_in[2:0] <= d[7:5];
            shifted_out <= shifted_in;
            shift_amount <= shift_amount + 3'b001;
            if (shift_amount == 3'b111) begin
                shift_amount <= 3'b0;
            end
        end else if (ena == 2'b10) begin // Rotate left
            shifted_in[5:0] <= shifted_out[7:2];
            shifted_in[7:6] <= d[1:0];
            shifted_out <= shifted_in;
            shift_amount <= shift_amount - 3'b001;
            if (shift_amount == 3'b000) begin
                shift_amount <= 3'b111;
            end
        end else begin // No rotation
            q <= d;
            shifted_out <= d;
            shift_amount <= 3'b0;
        end
    end

endmodule

