module hamdec(
        data_in,
        edc_in,
        data_out,
        error);

    // Parameter and wire declarations
    parameter uart_data_width = 8;
    parameter uart_rx_hamming_decoder_edc_width = 4;
    wire [3:0] syndrome;

    // Input and output declarations
    input [uart_data_width-1:0] data_in;
    input [uart_rx_hamming_decoder_edc_width-1:0] edc_in;
    output reg [uart_data_width-1:0] data_out;
    output reg error;

    // Syndrome calculation
    assign syndrome[0] = edc_in[3] ^ data_in[7] ^ data_in[6] ^ data_in[4] ^ data_in[3] ^ data_in[1];
    assign syndrome[1] = edc_in[2] ^ data_in[7] ^ data_in[5] ^ data_in[4] ^ data_in[2] ^ data_in[1];
    assign syndrome[2] = edc_in[1] ^ data_in[6] ^ data_in[5] ^ data_in[4] ^ data_in[0];
    assign syndrome[3] = edc_in[0] ^ data_in[3] ^ data_in[2] ^ data_in[1] ^ data_in[0];

    // Error correction
    always @(*) begin
        data_out = data_in;
        error = 0;
        case (syndrome)
            4'h0: begin // No error
                error = 0;
            end
            4'h1: begin // Single bit error in D7
                data_out[7] = ~data_in[7];
                error = 1;
            end
            4'h2: begin // Single bit error in D6
                data_out[6] = ~data_in[6];
                error = 1;
            end
            4'h3: begin // Single bit error in D7 and D6
                data_out[7] = ~data_in[7];
                data_out[6] = ~data_in[6];
                error = 1;
            end
            4'h4: begin // Single bit error in D5
                data_out[5] = ~data_in[5];
                error = 1;
            end
            4'h5: begin // Single bit error in D7 and D5
                data_out[7] = ~data_in[7];
                data_out[5] = ~data_in[5];
                error = 1;
            end
            4'h6: begin // Single bit error in D6 and D5
                data_out[6] = ~data_in[6];
                data_out[5] = ~data_in[5];
                error = 1;
            end
            4'h7: begin // Single bit error in D7, D6, and D5
                data_out[7] = ~data_in[7];
                data_out[6] = ~data_in[6];
                data_out[5] = ~data_in[5];
                error = 1;
            end
            4'h8: begin // Single bit error in D4
                data_out[4] = ~data_in[4];
                error = 1;
            end
            4'h9: begin // Single bit error in D7 and D4
                data_out[7] = ~data_in[7];
                data_out[4] = ~data_in[4];
                error = 1;
            end
            4'ha: begin // Single bit error in D6 and D4
                data_out[6] = ~data_in[6];
                data_out[4] = ~data_in[4];
                error = 1;
            end
            4'hb: begin // Single bit error in D7, D6, and D4
                data_out[7] = ~data_in[7];
                data_out[6] = ~data_in[6];
                data_out[4] = ~data_in[4];
                error = 1;
            end
            4'hc: begin // Single bit error in D5 and D4
                data_out[5] = ~data_in[5];
                data_out[4] = ~data_in[4];
                error = 1;
            end
            4'hd: begin // Single bit error in D7, D5, and D4
                data_out[7] = ~data_in[7];
                data_out[5] = ~data_in[5];
                data_out[4] = ~data_in[4];
                error = 1;
            end
            4'he: begin // Single bit error in D6, D5, and D4
                data_out[6] = ~data_in[6];
                data_out[5] = ~data_in[5];
                data_out[4] = ~data_in[4];
                error = 1;
            end
            4'hf: begin // Single bit error in D7, D6, D5, and D4
                data_out[7] = ~data_in[7];
                data_out[6] = ~data_in[6];
                data_out[5] = ~data_in[5];
                data_out[4] = ~data_in[4];
                error = 1;
            end
        endcase
    end
endmodule

