module counter_display(
    input CLOCK_50, // 50 MHz FPGA Clock
    input [1:0] KEY, // Pushbutton Keys
    input [5:0] SW, // DIP Switches
    output [6:0] HEX0, HEX1, HEX2, HEX3 // Seven-Segment Displays
);

    wire enable;
    wire [15:0] hexDigits;
    wire [3:0] countValue;

    // Instantiate keypressed module
    keypressed K1 (
        .clock(CLOCK_50),
        .reset(KEY[0]),
        .enable_in(KEY[1]),
        .enable_out(enable)
    );

    // Instantiate counter16bit module
    counter16bit C1 (
        .clock(CLOCK_50),
        .enable(enable),
        .clear(KEY[0]),
        .disp(SW[5]),
        .dir(SW[4]),
        .countValue(countValue),
        .outputValue(hexDigits)
    );

    // Instantiate seven-segment display drivers
    sevensegdecoder_always S0 (
        .digit(hexDigits[3:0]),
        .drivers(HEX0)
    );
    sevensegdecoder_always S1 (
        .digit(hexDigits[7:4]),
        .drivers(HEX1)
    );
    sevensegdecoder_always S2 (
        .digit(hexDigits[11:8]),
        .drivers(HEX2)
    );
    sevensegdecoder_always S3 (
        .digit(hexDigits[15:12]),
        .drivers(HEX3)
    );

    // Counter logic
    always @ (posedge CLOCK_50) begin
        if (KEY[0] == 1) begin // Reset counter
            countValue <= 0;
        end else if (KEY[1] == 1) begin // Enable counter
            if (SW[4] == 1) begin // Counter direction
                countValue <= countValue - 1;
            end else begin
                countValue <= countValue + 1;
            end
        end
    end

endmodule

module up_down_counter (
    input clk,
    input reset,
    input load,
    input up_down,
    output reg [15:0] q
);

    always @(posedge clk) begin
        if (reset) begin
            q <= 16'b0000;
        end else if (load) begin
            q <= {a, b, c, d};
        end else if (up_down) begin
            q <= q + 1;
        end else begin
            q <= q - 1;
        end
    end

endmodule

