module final_module (
    input clk,
    input reset,
    input load,
    input up_down,
    input a,
    input b,
    input select,
    output reg [15:0] q
);

    wire [3:0] xor_output;
    wire [15:0] counter_output;

    up_down_counter counter (
        .clk(clk),
        .reset(reset),
        .load(load),
        .up_down(up_down),
        .q(counter_output)
    );

    xor_module xor (
        .clk(clk),
        .a(a),
        .b(b),
        .c(xor_output[0])
    );

    always @(posedge clk) begin
        if (reset) begin
            q <= 16'b0000;
        end else if (select) begin
            q <= {counter_output[3:0], counter_output[7:4], counter_output[11:8], counter_output[15:12]};
        end else begin
            q <= {4'b0000, xor_output, 4'b0000};
        end
    end

endmodule

module fifo (
    input clk,
    input rst,
    input rd,
    input wr,
    input [7:0] data_in,
    output [7:0] data_out,
    output empty,
    output full
);

parameter DEPTH = 16;

reg [7:0] memory [0:DEPTH-1];
reg [3:0] write_ptr = 0;
reg [3:0] read_ptr = 0;
wire [3:0] next_write_ptr = write_ptr + 1;
wire [3:0] next_read_ptr = read_ptr + 1;
wire [3:0] next_read_ptr_wr = read_ptr;

assign empty = (write_ptr == read_ptr);
assign full = (next_write_ptr == read_ptr);

always @(posedge clk) begin
    if (rst) begin
        write_ptr <= 0;
        read_ptr <= 0;
    end else begin
        if (wr && !full) begin
            memory[write_ptr] <= data_in;
            write_ptr <= next_write_ptr;
        end
        if (rd && !empty) begin
            data_out <= memory[read_ptr];
            read_ptr <= next_read_ptr;
        end
    end
end

endmodule

