module binary_gray_shift (
    input clk,
    input load,
    input shift,
    input [3:0] B,
    input [15:0] D,
    output [3:0] G,
    output [15:0] S
);

    // Binary to Gray Code Converter
    wire [3:0] gray;
    binary_to_gray_converter converter(
        .binary(B),
        .gray(gray)
    );

    // 16-bit Shift Register
    reg [15:0] shift_reg;
    always @(posedge clk) begin
        if (load) begin
            shift_reg <= D;
        end else if (shift) begin
            shift_reg <= {shift_reg[14:0], gray};
        end
    end

    // Output
    assign G = gray;
    assign S = shift_reg;

endmodule

module binary_to_gray_converter (
    input [3:0] binary,
    output [3:0] gray
);

    assign gray[3] = binary[3];
    assign gray[2] = binary[3] ^ binary[2];
    assign gray[1] = binary[2] ^ binary[1];
    assign gray[0] = binary[1] ^ binary[0];

endmodule

module comparator_block #(
  parameter n = 8 // number of bits in input signals
)(
  input [n-1:0] a,
  input [n-1:0] b,
  output gt,
  output lt,
  output eq
);

  wire [n:0] a_ext, b_ext;
  assign a_ext = {1'b0, a};
  assign b_ext = {1'b0, b};

  wire [n:0] a_gt_b, a_lt_b, a_eq_b;
  genvar i;
  generate
    for (i = 0; i <= n; i = i + 1) begin : compare_bits
      assign a_gt_b[i] = a_ext[i] & ~b_ext[i];
      assign a_lt_b[i] = ~a_ext[i] & b_ext[i];
      assign a_eq_b[i] = a_ext[i] == b_ext[i];
    end
  endgenerate

  assign gt = |a_gt_b;
  assign lt = |a_lt_b;
  assign eq = &a_eq_b;

endmodule

module linebuffer(
	input CK,
	input WE,
	input LOAD,
	input CLEARING,
	input [3:0] COLOR_INDEX,
	input PCK2,
	input [7:0] SPR_PAL,
	input [7:0] ADDR_LOAD,
	output [11:0] DATA_OUT
);

	// 192 pixels * 12 bits
	reg [11:0] LB_RAM[0:255];
	reg [7:0] PAL_REG;
	reg [7:0] ADDR_COUNTER;
	reg [7:0] ADDR_LATCH;
	wire [7:0] ADDR_MUX;
	wire [11:0] DATA_IN;
	wire [3:0] COLOR_GATED;

	assign RAM_WE = ~WE;
	assign RAM_RE = ~RAM_WE;

	// Switch between color index or backdrop clear
	assign COLOR_GATED = COLOR_INDEX | {4{CLEARING}};

	// Select color index or test data (unused)
	assign DATA_IN[3:0] = COLOR_GATED;

	// Latch sprite palette from P bus
	always @(posedge PCK2)
		PAL_REG <= SPR_PAL;

	// Switch between sprite palette or backdrop clear
	assign DATA_IN[11:4] = PAL_REG | {8{CLEARING}};

	// Switch between address inc or address reload
	assign ADDR_MUX = LOAD ? (ADDR_COUNTER + 1'b1) : ADDR_LOAD;

	// Address counter update
	always @(posedge CK)
		ADDR_COUNTER <= ADDR_MUX;

	// Address counter latch
	always @(*)
		if (WE) ADDR_LATCH <= ADDR_COUNTER;

	// RAM read
	assign #10 DATA_OUT = RAM_RE ? LB_RAM[ADDR_LATCH] : 12'bzzzzzzzzzzzz;

	// RAM write
	always @(posedge RAM_WE)
		LB_RAM[ADDR_LATCH] <= DATA_IN;

endmodule

