module d_ff_register (
    CLK,
    RST,
    EN,
    D,
    Q
);

    input CLK;
    input RST;
    input EN;
    input [3:0] D;
    output [3:0] Q;

    wire [3:0] q_next;
    assign q_next = Q;

    sky130_fd_sc_ms__dlxtp_1 d_ff (
        .Q(q_next[0]),
        .D(D[0]),
        .GATE(1),
        .VPWR(1),
        .VGND(0),
        .VPB(0),
