module top_module (
  input clk,
  input reset, // Synchronous active-high reset
  input [7:0] a, b, // 8-bit inputs for the given modules
  output [7:0] out // 8-bit output for the functional module
);

  // Instantiate the two given modules
  module_a module_a_inst (
    .clk(clk),
    .reset(reset),
    .in(a),
    .out(a_out)
  );

  module_b module_b_inst (
    .clk(clk),
    .reset(reset),
    .in(b),
    .out(b_out)
  );

  // Declare internal wires for the sum
  wire [8:0] sum;
  wire carry;

  // Add the two outputs from the given modules
  assign {carry, sum} = {1'b0, a_out, b_out} + 1'b0;

  // Assign the output of the functional module
  assign out = sum[7:0];

endmodule

