module digital_clock (
  input  wire areset,
  input  wire inclk0,
  output wire c0,
  output wire c1,
  output wire c2,
  output wire locked
);

// internal wires
wire pll_114;
wire dll_114;
wire dll_28;
reg [1:0] clk_7 = 0;

// pll
DCM #(
  .CLKDV_DIVIDE(2.0),
  .CLKFX_DIVIDE(17),
  .CLKFX_MULTIPLY(29),
  .CLKIN_DIVIDE_BY_2("FALSE"),
  .CLKIN_PERIOD(15.015),
  .CLKOUT_PHASE_SHIFT("NONE"),
  .CLK_FEEDBACK("NONE"),
  .DESKEW_ADJUST("SYSTEM_SYNCHRONOUS"),
  .DFS_FREQUENCY_MODE("LOW"),
  .DLL_FREQUENCY_MODE("LOW"),
  .DUTY_CYCLE_CORRECTION("TRUE"),
  .FACTORY_JF(16'h8080),
  .PHASE_SHIFT(0),
  .STARTUP_WAIT("TRUE")
) pll (
  .CLKIN(inclk0),
  .CLKFX(pll_114)
);

// dll
DCM #(
  .CLKDV_DIVIDE(4.0),
  .CLKFX_DIVIDE(1),
  .CLKFX_MULTIPLY(4),
  .CLKIN_DIVIDE_BY_2("FALSE"),
  .CLKIN_PERIOD(8.802),
  .CLKOUT_PHASE_SHIFT("FIXED"),
  .CLK_FEEDBACK("1X"),
  .DESKEW_ADJUST("SYSTEM_SYNCHRONOUS"),
  .DFS_FREQUENCY_MODE("LOW"),
