module LogicCell(carryout, lcout, carryin, clk, clkb, in0, in1, in2, in3, sr);
  input carryin;
  output carryout;
  input clk;
  input clkb;
  input in0;
  input in1;
  input in2;
  input in3;
  output lcout;
  input sr;

  reg [3:0] inputs;
  reg lcout_reg;
  reg carryout_reg;

  always @(posedge clk, negedge clkb) begin
    if (!clkb) begin
      // Asynchronous reset
      lcout_reg <= 1'b0;
      carryout_reg <= 1'b0;
    end else if (sr) begin
      // Synchronous reset
      lcout_reg <= 1'b0;
      carryout_reg <= 1'b0;
    end else begin
      // Compute outputs
      inputs <= {in3, in2, in1, in0};
      lcout_reg <= |inputs;
      carryout_reg <= &inputs;
    end
  end

  assign carryout = carryin & carryout_reg;
  assign lcout = lcout_reg;

endmodule

module SRAM_256KB (
    input [13:0] ADDRESS,
    input [15:0] DATAIN,
    input [3:0] MASKWREN,
    input WREN, CHIPSELECT, CLOCK, STANDBY, SLEEP, POWEROFF,
    output reg [15:0] DATAOUT
);

    reg [15:0] mem [0:16383]; // 256KB memory
    reg off = SLEEP || !POWEROFF; // flag to indicate if the memory is off
    integer i;

    // Initialize memory to all X's on power off
    always @(negedge POWEROFF) begin
        for (i = 0; i <= 16383; i = i+1)
            mem[i] = 16'bx;
    end

    // Read and write operations
    always @(posedge CLOCK, posedge off) begin
        if (off) begin
            DATAOUT <= 0;
        end else if (STANDBY) begin
            DATAOUT <= 16'bx;
        end else if (CHIPSELECT) begin
            if (!WREN) begin
                DATAOUT <= mem[ADDRESS];
            end else begin
                if (MASKWREN[0]) mem[ADDRESS][ 3: 0] <= DATAIN[ 3: 0];
                if (MASKWREN[1]) mem[ADDRESS][ 7: 4] <= DATAIN[ 7: 4];
                if (MASKWREN[2]) mem[ADDRESS][11: 8] <= DATAIN[11: 8];
                if (MASKWREN[3]) mem[ADDRESS][15:12] <= DATAIN[15:12];
                DATAOUT <= 16'bx;
            end
        end
    end

endmodule

