module add_sub (
    input [3:0] A,
    input [3:0] B,
    input S,
    output [3:0] R,
    output Cout
);

    wire [3:0] sum;
    wire C1, C2;

    assign C2 = ~S;
    assign Cout = (S & C1) | (C2 & C2);

    full_adder FA0(A[0], B[0], C2, sum[0], C1);
    full_adder FA1(A[1], B[1], C1, sum[1], C1);
    full_adder FA2(A[2], B[2], C1, sum[2], C1);
    full_adder FA3(A[3], B[3], C1, sum[3], C1);

    assign R = sum;

endmodule

