module memory(clk, addr, din, dout, enable, rw, access_size, busy);

    parameter BYTE = 8;
    parameter HALFWORD = 16;
    parameter WORD = 32;

    input clk;
    input [31:0] addr;
    input [31:0] din;
    output [31:0] dout;
    input enable;
    input rw;
    input [1:0] access_size;
    output busy;

    reg [31:0] memory[0:1023];
    reg busy;

    always @(posedge clk)
    begin
        if(enable)
        begin
            busy <= 1'b1;
            case(access_size)
                2'b00: begin // byte access
                            if(rw) // read operation
                                dout <= memory[addr][7:0];
                            else // write operation
                                memory[addr][7:0] <= din[7:0];
                        end
                2'b01: begin // halfword access
                            if(rw) // read operation
                                dout <= memory[addr][15:0];
                            else // write operation
                                memory[addr][15:0] <= din[15:0];
                        end
                2'b10: begin // word access
                            if(rw) // read operation
                                dout <= memory[addr];
                            else // write operation
                                memory[addr] <= din;
                        end
                default: begin
                            dout <= 0;
                        end
            endcase
            busy <= 1'b0;
        end
    end
endmodule

