module fsm_3bit_sequence_detection (
  input clk,
  input reset,
  input [11:0] data,
  output reg match
);

  parameter IDLE = 2'b00;
  parameter BIT1 = 2'b01;
  parameter BIT2 = 2'b10;
  parameter MATCH = 2'b11;

  reg [1:0] state;
  reg [2:0] sequence;

  always @(posedge clk) begin
    if (reset) begin
      state <= IDLE;
      sequence <= 3'b000;
      match <= 0;
    end
    else begin
      case (state)
        IDLE: begin
          if (data[2:0] == 3'b001) begin
            state <= BIT1;
            sequence <= 3'b001;
          end
        end
        BIT1: begin
          if (data[2:0] == 3'b010) begin
            state <= BIT2;
            sequence <= 3'b010;
          end
          else if (data[2:0] == 3'b001) begin
            sequence <= 3'b001;
          end
          else begin
            state <= IDLE;
            sequence <= 3'b000;
          end
        end
        BIT2: begin
          if (data[2:0] == 3'b011) begin
            state <= MATCH;
            sequence <= 3'b011;
            match <= 1;
          end
          else if (data[2:0] == 3'b001) begin
            state <= BIT1;
            sequence <= 3'b001;
          end
          else if (data[2:0] == 3'b010) begin
            sequence <= 3'b010;
          end
          else begin
            state <= IDLE;
            sequence <= 3'b000;
          end
        end
        MATCH: begin
          if (data[2:0] != sequence) begin
            state <= DONE;
          end
        end
        DONE: begin
          if (data[2:0] == 3'b001) begin
            state <= BIT1;
            sequence <= 3'b001;
            match <= 0;
          end
          else begin
            state <= IDLE;
            sequence <= 3'b000;
          end
        end
      endcase
    end
  end

endmodule

module spi_emit_data (
  input clock, reset, enable,
  input [127:0] data,
  input [4:0] count,
  input spiclockp, spiclockn, picready,
  output sclk, sdo, done, starting
);

  wire [127:0] latch;
  reg [7:0] left;
  reg ready, transmit_next;
  wire transmitting;

  assign sdo = latch[127];
  assign done = ~ready & (left == 0);
  assign transmitting = ~ready & ~done;

  always @(posedge clock or negedge reset) begin
    if (~reset) begin
      ready <= 1;
      left <= 0;
      starting <= 0;
    end else begin
      if (spiclockn) begin
        sclk <= 0;
        starting <= 0;
        if (~enable) begin
          ready <= 1;
          left <= 0;
        end else if (ready) begin
          latch <= data;
          left <= {count, 3'b0};
          ready <= 0;
        end else if (left > 0 && transmit_next) begin
          latch <= {latch[126:0], 1'b0};
          left <= left - 8'd1;
        end
      end else if (spiclockp & transmitting) begin
        if (left[2:0] != 3'b000 | picready) begin
          sclk <= 1;
          transmit_next <= 1;
          starting <= left[2:0] == 3'b000;
        end else begin
          transmit_next <= 0;
        end
      end
    end
  end

endmodule

module debouncer (
  input clk,
  input in,
  output reg out
);

parameter clk_freq = 100000000;
parameter debounce_time = 50; // in milliseconds

reg [31:0] count;
reg [31:0] debounce_cycles;

always @(posedge clk) begin
  if (in != out) begin
    count <= 0;
    debounce_cycles <= debounce_time * clk_freq / 1000;
  end else if (count < debounce_cycles) begin
    count <= count + 1;
  end else begin
    out <= in;
  end
end

endmodule

