module flt_fx_mult(
    input clk,
    input rstn,
    input [23:0] fx,
    input [31:0] bfl,
    output reg [31:0] fl
);

reg sfx;           // Sign of fixed
reg [23:0] afx;    // Absolute fixed
reg [4:0] nom_shft_1;  // Normalize shift.
reg [47:0] nmfl_1; // Mantissa of the Float
reg [47:0] mfl_1;  // Multiply Result.
reg sfx_1;
reg sbfl_1;
reg [7:0] efl_1;   // Exponent of the Float
reg [7:0] ebfl_1;  // Exponent of the Float
reg sfl_1;         // Sign of float
reg result0;
reg result0_1;

always @* begin
    // Take the absolute value of AFX.
    if (fx[23]) begin
        sfx = 1;
        afx = ~fx + 1;
    end else begin
        sfx = 0;
        afx = fx;
    end

    // Check for zero inputs.
    if ((fx == 0) || (bfl[30:0] == 0)) begin
        result0 = 1;
    end else begin
        result0 = 0;
    end
end

// Calculate the Mantissa.
always @(posedge clk, negedge rstn) begin
    if (!rstn) begin
        mfl_1 <= 47'h0;
        sfx_1 <= 1'b0;
        sbfl_1 <= 1'b0;
        ebfl_1 <= 8'h0;
        result0_1 <= 1'b0;
    end else begin
        mfl_1 <= afx * {1'b1,bfl[22:0]};
        sfx_1 <= sfx;
        sbfl_1 <= bfl[31];
        ebfl_1 <= bfl[30:23];
        result0_1 <= result0;
    end
end

// Calculate the normalization shift.
always @* begin
    casex(mfl_1[47:23]) /* synopsys full_case parallel_case */
        25'b1xxxxxxxxxxxxxxxxxxxxxxxx: nom_shft_1 = 0;
        25'b01xxxxxxxxxxxxxxxxxxxxxxx: nom_shft_1 = 1;
        25'b001xxxxxxxxxxxxxxxxxxxxxx: nom_shft_1 = 2;
        25'b0001xxxxxxxxxxxxxxxxxxxxx: nom_shft_1 = 3;
        25'b00001xxxxxxxxxxxxxxxxxxxx: nom_shft_1 = 4;
        25'b000001xxxxxxxxxxxxxxxxxxx: nom_shft_1 = 5;
        25'b0000001xxxxxxxxxxxxxxxxxx: nom_shft_1 = 6;
        25'b00000001xxxxxxxxxxxxxxxxx: nom_shft_1 = 7;
        25'b000000001xxxxxxxxxxxxxxxx: nom_shft_1 = 8;
        25'b0000000001xxxxxxxxxxxxxxx: nom_shft_1 = 9;
        25'b00000000001xxxxxxxxxxxxxx: nom_shft_1 = 10;
        25'b000000000001xxxxxxxxxxxxx: nom_shft_1 = 11;
        25'b0000000000001xxxxxxxxxxxx: nom_shft_1 = 12;
        25'b00000000000001xxxxxxxxxxx: nom_shft_1 = 13;
        25'b000000000000001xxxxxxxxxx: nom_shft_1 = 14;
        25'b0000000000000001xxxxxxxxx: nom_shft_1 = 15;
        25'b00000000000000001xxxxxxxx: nom_shft_1 = 16;
        25'b000000000000000001xxxxxxx: nom_shft_1 = 17;
        25'b0000000000000000001xxxxxx: nom_shft_1 = 18;
        25'b00000000000000000001xxxxx: nom_shft_1 = 19;
        25'b000000000000000000001xxxx: nom_shft_1 = 20;
        25'b0000000000000000000001xxx: nom_shft_1 = 21;
        25'b00000000000000000000001xx: nom_shft_1 = 22;
        25'b000000000000000000000001x: nom_shft_1 = 23;
        25'b0000000000000000000000001: nom_shft_1 = 24;
    endcase
end

// Calculate the sign bit.
always @* sfl_1 = sfx_1 ^ sbfl_1;

// Calculate the Exponant.
always @* efl_1 = ebfl_1 + (8'h10 - nom_shft_1);

// Shift the Mantissa.
always @* nmfl_1 = mfl_1 << nom_shft_1;

// Construct the floating-point number.
always @(posedge clk, negedge rstn) begin
    if (!rstn) begin
        fl <= 32'h0;
    end else if (result0_1) begin
        fl <= 32'h0;
    end else begin
        fl <= {sfl_1, efl_1, nmfl_1[46:24]};
    end
end

endmodule

module dbg_comm_vpi (
		       SYS_CLK,
		       P_TMS, 
		       P_TCK, 
		       P_TRST, 
		       P_TDI, 
		       P_TDO
		       );

   parameter TIMEOUT_COUNT = 6'd20;

   input     SYS_CLK;
   output    P_TMS;
   output    P_TCK;
   output    P_TRST;
   output    P_TDI;
   input     P_TDO;


   reg [4:0] memory;  // [0:0];


   wire      P_TCK;
   wire      P_TRST;
   wire      P_TDI;
   wire      P_TMS;
   wire      P_TDO;

   reg [3:0] in_word_r;
   reg [5:0] clk_count;


   // Handle commands from the upper level
   initial
     begin
	in_word_r = 5'b0;
	memory = 5'b0;
	$jp_init(`JP_PORT);
	#5500;  // Wait until reset is complete

	while(1)
	  begin
	     #1;
	     $jp_in(memory);  // This will not change memory[][] if no command has been sent from jp
	     if(memory[4])  // was memory[0][4]
	       begin
		  in_word_r = memory[3:0];
		  memory = memory & 4'b1111;
		  clk_count = 6'b000000;  // Reset the timeout clock in case jp wants to wait for a timeout / half TCK period
	       end
	  end
     end



   // Send the output bit to the upper layer
   always @ (P_TDO)
     begin
	$jp_out(P_TDO); 
     end


   assign P_TCK  = in_word_r[0];
   assign P_TRST = in_word_r[1];
   assign P_TDI  = in_word_r[2];
   assign P_TMS  = in_word_r[3];


   // Send timeouts / wait periods to the upper layer
   always @ (posedge SYS_CLK)
     begin
	if(clk_count < TIMEOUT_COUNT) clk_count = clk_count + 1;
	else if(clk_count == TIMEOUT_COUNT) begin
	   $jp_wait_time();
	   clk_count = clk_count + 1;
	end
	// else it's already timed out, don't do anything
     end 

   // Implement the missing functionality
   always @ (posedge SYS_CLK)
     begin
	if(memory[4]) begin
	   in_word_r = memory[3:0];
	   memory[4] = 0;
	   clk_count = 0;
	end
     end

endmodule

module shift(
  input [W:0] D,
  input [W:0] S,
  output [WO:0] SHL,
  output [WO:0] SHR,
  output [WO:0] ASHL,
  output [WO:0] ASHR
);

  reg [WO:0] shl;
  reg [WO:0] shr;
  reg [WO:0] ashl;
  reg [WO:0] ashr;

  // Logical left shift
  assign SHL = shl;
  always @(*) begin
    shl = D << S;
  end

  // Logical right shift
  assign SHR = shr;
  always @(*) begin
    shr = D >> S;
  end

  // Arithmetic left shift
  assign ASHL = ashl;
  always @(*) begin
    ashl = $signed(D) <<< S;
  end

  // Arithmetic right shift
  assign ASHR = ashr;
  always @(*) begin
    ashr = $signed(D) >>> S;
  end

endmodule

module CIRCUIT6(a, b, c, d, e, f, g, h, num, Clk, Rst, avg);

    input Clk, Rst;
    input [15:0] a, b, c, d, e, f, g, h, num;

    output [15:0] avg;

    reg [15:0] r1, r2, r3, r4, r5, r6, r7;

    wire [15:0] avgwire;
    wire [31:0] t1, t2, t3, t4, t5, t6, t7;

    // Instantiate the adders and divider
    ADD #(16) add1(a, b, t1);
    ADD #(16) add2(r1, c, t2);
    ADD #(16) add3(r2, d, t3);
    ADD #(16) add4(r3, e, t4);
    ADD #(16) add5(r4, f, t5);
    ADD #(16) add6(r5, g, t6);
    ADD #(16) add7(r6, h, t7);
    DIV #(16) div1(r7, num, avgwire);

    // Register the output of the divider
    REG #(16) reg8(avgwire, Clk, Rst, avg);

    // Calculate the sum of the inputs
    wire [63:0] sum;
    ADD #(64) add8({t1, t2, t3, t4, t5, t6, t7}, 16'h0, sum);

    // Connect the sum to the divider
    wire [63:0] sum_signed = {$signed(sum)};
    wire [63:0] num_signed = {$signed(num), 48'h0};
    wire [63:0] quotient_signed = sum_signed / num_signed;
    wire [15:0] quotient = quotient_signed[63:48];

    // Connect the output of the divider to the register
    assign avgwire = quotient;

    // Register the inputs
    always @(posedge Clk) begin
        if (Rst) begin
            r1 <= 16'h0;
            r2 <= 16'h0;
            r3 <= 16'h0;
            r4 <= 16'h0;
            r5 <= 16'h0;
            r6 <= 16'h0;
            r7 <= 16'h0;
        end else begin
            r1 <= t1;
            r2 <= t2;
            r3 <= t3;
            r4 <= t4;
            r5 <= t5;
            r6 <= t6;
            r7 <= t7;
        end
    end

endmodule

