module POR (
  input VDD,
  input RESET,
  output REG
);

parameter t = 100; // length of time for reset signal to be asserted after power-on (in ns)

reg delayed_reset;
reg [1:0] state;

// State machine to generate delayed reset signal
always @(posedge VDD or posedge RESET) begin
  if (RESET) begin
    state <= 2'b00; // reset state machine
    delayed_reset <= 1'b0;
  end else begin
    case (state)
      2'b00: begin // initial state
        delayed_reset <= 1'b0;
        state <= 2'b01;
      end
      2'b01: begin // delay state
        delayed_reset <= 1'b0;
        #t delayed_reset <= 1'b1;
        state <= 2'b10;
      end
      2'b10: begin // reset state
        delayed_reset <= 1'b1;
        state <= 2'b11;
      end
      2'b11: begin // idle state
        delayed_reset <= 1'b1;
      end
    endcase
  end
end

// Output register to keep output low until power is reapplied
always @(posedge VDD or posedge RESET) begin
  if (RESET) begin
    REG <= 1'b0;
  end else begin
    REG <= delayed_reset;
  end
end

endmodule

