module seven_segment_display(
  input clk,
  input rst,
  input [31:0] input_signal,
  output [6:0] segment_out_0,
  output [6:0] segment_out_1,
  output [6:0] segment_out_2,
  output [6:0] segment_out_3,
  output [6:0] segment_out_4,
  output [6:0] segment_out_5
);

  reg [5:0] digit_select = 6'b000001; // initial digit select value
  reg [31:0] input_copy = input_signal; // copy of input signal
  reg [6:0] segment_out_copy_0; // copy of segment_out_0
  reg [6:0] segment_out_copy_1; // copy of segment_out_1
  reg [6:0] segment_out_copy_2; // copy of segment_out_2
  reg [6:0] segment_out_copy_3; // copy of segment_out_3
  reg [6:0] segment_out_copy_4; // copy of segment_out_4
  reg [6:0] segment_out_copy_5; // copy of segment_out_5

  always @(posedge clk) begin
    if (rst) begin
      digit_select <= 6'b000001;
      input_copy <= input_signal;
      segment_out_copy_0 <= 7'b0000000;
      segment_out_copy_1 <= 7'b0000000;
      segment_out_copy_2 <= 7'b0000000;
      segment_out_copy_3 <= 7'b0000000;
      segment_out_copy_4 <= 7'b0000000;
      segment_out_copy_5 <= 7'b0000000;
    end else begin
      // update digit select
      if (digit_select == 6'b100000) begin
        digit_select <= 6'b000001;
      end else begin
        digit_select <= digit_select << 1;
      end

      // update input copy
      input_copy <= input_copy >> 7;

      // update segment output copies
      case (digit_select)
        6'b000001: segment_out_copy_0 <= input_copy[6:0];
        6'b000010: segment_out_copy_1 <= input_copy[6:0];
        6'b000100: segment_out_copy_2 <= input_copy[6:0];
        6'b001000: segment_out_copy_3 <= input_copy[6:0];
        6'b010000: segment_out_copy_4 <= input_copy[6:0];
        6'b100000: segment_out_copy_5 <= input_copy[6:0];
      endcase
    end
  end

  assign segment_out_0 = segment_out_copy_0;
  assign segment_out_1 = segment_out_copy_1;
  assign segment_out_2 = segment_out_copy_2;
  assign segment_out_3 = segment_out_copy_3;
  assign segment_out_4 = segment_out_copy_4;
  assign segment_out_5 = segment_out_copy_5;

endmodule

