module PLL (
  input ref_clk,
  input reset,
  input [31:0] freq_set,
  output reg clk_out
);

reg [31:0] phase_accumulator;
reg [31:0] phase_increment;
reg [31:0] multiplier;
reg locked;

always @(posedge ref_clk or posedge reset) begin
  if (reset) begin
    phase_accumulator <= 0;
    multiplier <= 0;
    locked <= 0;
  end else begin
    if (freq_set != multiplier) begin
      multiplier <= freq_set;
      phase_increment <= (multiplier * 2**32) / ref_clk;
    end
    if (locked) begin
      phase_accumulator <= phase_accumulator + phase_increment;
    end else begin
      phase_accumulator <= 0;
    end
    if (phase_accumulator >= 2**31) begin
      locked <= 1;
      phase_accumulator <= phase_accumulator - 2**31;
    end else begin
      locked <= 0;
    end
  end
end

always @(posedge ref_clk or posedge reset) begin
  if (reset) begin
    clk_out <= 0;
  end else begin
    if (locked) begin
      clk_out <= ~clk_out;
    end else begin
      clk_out <= 0;
    end
  end
end

endmodule
