module top_module (
    input clk,
    input reset,
    input [3:0] a,
    input [3:0] b,
    input [1:0] select, // Select input to choose between addition, subtraction, multiplication, or division
    output reg [3:0] result
);

    wire [3:0] add_out;
    wire [3:0] sub_out;
    wire [7:0] mul_out;
    wire [3:0] div_out;

    adder adder_inst (
        .a(a),
        .b(b),
        .clk(clk),
        .reset(reset),
        .sum(add_out)
    );

    subtractor sub_inst (
        .a(a),
        .b(b),
        .clk(clk),
        .reset(reset),
        .diff(sub_out)
    );

    multiplier mul_inst (
        .a(a),
        .b(b),
        .clk(clk),
        .reset(reset),
        .prod(mul_out)
    );

    divider div_inst (
        .a(a),
        .b(b),
        .clk(clk),
        .reset(reset),
        .quotient(div_out)
    );

    always @ (posedge clk) begin
        if (reset) begin
            result <= 4'b0;
        end else begin
            case (select)
                2'b00: result <= add_out;
                2'b01: result <= sub_out;
                2'b10: result <= mul_out[7:4];
                2'b11: result <= div_out;
                default: result <= 4'b0;
            endcase
        end
    end

endmodule

