  wire [MEM_WIDTH-1:0] mem_data_in;
  wire [MEM_WIDTH-1:0] mem_addr;
  wire [MEM_WIDTH-1:0] mem_wen;
  wire [MEM_WIDTH-1:0] mem_ren;
  wire [MEM_WIDTH-1:0] mem_clk;

  assign empty = (mem_ren == mem_wen);
  assign full = ((mem_wen - mem_ren) == MEM_DEPTH);

  assign mem_data_in = din;
  assign mem_data_out = dout;
  assign mem_clk = (wr_clk && rd_clk);

  block_mem_gen_mem #(
    .MEMORY_TYPE("auto"),
    .MEMORY_WIDTH(MEM_WIDTH),
    .MEMORY_DEPTH(MEM_DEPTH),
    .INIT_FILE("")
  ) mem (
    .data_out(mem_data_out),
    .data_in(mem_data_in),
    .addr(mem_addr),
    .wen(mem_wen),
    .ren(mem_ren),
    .clk(mem_clk)
  );

  reg [MEM_WIDTH-1:0] wr_ptr;
  reg [MEM_WIDTH-1:0] rd_ptr;
  reg [MEM_WIDTH-1:0] next_wr_ptr;
  reg [MEM_WIDTH-1:0] next_rd_ptr;
  reg [MEM_WIDTH-1:0] mem_wen_reg;
  reg [MEM_WIDTH-1:0] mem_ren_reg;
  reg [MEM_WIDTH-1:0] wr_clk_reg;
  reg [MEM_WIDTH-1:0] rd_clk_reg;

  always @(posedge wr_clk) begin
    if (reset) begin
      wr_ptr <= 0;
      next_wr_ptr <= 0;
      mem_wen_reg <= 0;
      wr_clk_reg <= 0;
    end else begin
      wr_ptr <= next_wr_ptr;
      mem_wen_reg <= mem_wen;
      wr_clk_reg <= wr_clk;
    end
  end

  always @(posedge rd_clk) begin
    if (reset) begin
      rd_ptr <= 0;
      next_rd_ptr <= 0;
      mem_ren_reg <= 0;
      rd_clk_reg <= 0;
    end else begin
      rd_ptr <= next_rd_ptr;
      mem_ren_reg <= mem_ren;
      rd_clk_reg <= rd_clk;
    end
  end

  always @* begin
    next_wr_ptr = wr_ptr + 1;
    next_rd_ptr = rd_ptr + 1;
    mem_wen = (wr_clk == wr_clk_reg) && (next_wr_ptr != rd_ptr);
    mem_ren = (rd_clk == rd_clk_reg) && (wr_ptr != rd_ptr);
    mem_addr = wr_ptr;
    dout = mem_data_out;
  end

