module multiplier (
    input [3:0] a,
    input [3:0] b,
    output reg [7:0] result
);

    reg [7:0] temp;
    reg [3:0] i, j;

    always @(*) begin
        temp = 8'b0;
        for (i = 0; i < 4; i = i + 1) begin
            for (j = 0; j < 4; j = j + 1) begin
                if ((a[i] == 1) && (b[j] == 1)) begin
                    temp[i+j] = temp[i+j] + 1;
                end
            end
        end

        for (i = 0; i < 7; i = i + 1) begin
            if (temp[i] == 2) begin
                temp[i] = 0;
                temp[i+1] = temp[i+1] + 1;
            end
        end
    end

    assign result = temp;

endmodule

module arithmetic_right_shift (
  input signed [31:0] input_num,
  input [4:0] shift_amt,
  output signed [31:0] output_num
);

  // Shift the input number to the right by the shift amount
  always @(*) begin
    if (shift_amt >= 32) begin
      // If the shift amount is greater than or equal to 32, output 0 or -1 depending on the sign bit
      if (input_num[31] == 1) begin
        output_num = -1;
      end else begin
        output_num = 0;
      end
    end else begin
      // Otherwise, perform the arithmetic right shift
      if (input_num[31] == 1) begin
        // If the input number is negative, shift in 1's to the left
        output_num = {32{input_num[31]}} >> shift_amt;
      end else begin
        // If the input number is positive, shift in 0's to the left
        output_num = input_num >> shift_amt;
      end
    end
  end

endmodule

