module rising_edge_detection (
    input clk,
    input rst_n,
    input [7:0] in,
    output reg [7:0] out
);
    reg [7:0] prev_in;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            out <= 8'b0;
            prev_in <= 8'b0;
        end else begin
            out <= (in > prev_in) ? (in - prev_in) : 8'b0;
            prev_in <= in;
        end
    end
endmodule

module accumulator (
    input clk,
    input rst_n,
    input [7:0] in,
    input valid,
    output reg ready,
    output reg [9:0] out
);
    reg [9:0] sum;
    reg [2:0] count;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sum <= 10'b0;
            count <= 3'b0;
            ready <= 1'b0;
        end else begin
            if (valid) begin
                sum <= sum + {2'b0, in};
                count <= count + 1;
            end

            if (count == 3) begin
                out <= sum;
                ready <= 1'b1;
                sum <= 10'b0;
                count <= 3'b0;
            end else begin
                out <= 10'b0;
                ready <= 1'b0;
            end
        end
    end
endmodule

module control_logic (
    input select,
