    input ready_b,
    output reg valid_b,
    output reg enable_rising_edge_detection,
    output reg enable_accumulator
);
    always @(select or valid_a or ready_b) begin
        if (select) begin
            enable_rising_edge_detection <= 1'b1;
            enable_accumulator <= 1'b0;
            valid_b <= 1'b0;
        end else begin
            enable_rising_edge_detection <= 1'b0;
            enable_accumulator <= 1'b1;
            valid_b <= valid_a && ready_b;
        end
    end
endmodule

module top_module (
    input clk,
    input rst_n,
    input [7:0] in,
    input select,
    input valid_a,
    input ready_b,
    output ready_a,
    output reg valid_b,
    output reg [9:0] out
);
    wire [7:0] red_out;
    wire [9:0] acc_out;
    wire red_ready;
    wire acc_ready;

    rising_edge_detection red (
        .clk(clk),
        .rst_n(rst_n),
        .in(in),
        .out(red_out)
    );

    accumulator acc (
        .clk(clk),
        .rst_n(rst_n),
        .in(in),
        .valid(valid_a),
        .ready(acc_ready),
        .out(acc_out)
    );

    control_logic ctrl (
        .select(select),
        .valid_a(valid_a),
        .ready_b(ready_b),
        .valid_b(valid_b),
        .enable_rising_edge_detection(red_ready),
        .enable_accumulator(acc_ready)
    );

    assign ready_a = (select) ? red_ready : acc_ready;
    assign out = (select) ? red_out : acc_out;
endmodule

