module binary_to_gray (
    input [3:0] binary,
    output reg [3:0] gray
);

    // 8 D flip-flops designed using a shift register architecture
    reg [3:0] shift_reg;
    always @(posedge clk) begin
        shift_reg <= {shift_reg[2:0], binary};
    end

    // 2-input AND gate module that uses only NOR gates
    wire and_out;
    nand2 #(.WIDTH(2)) and_gate (
        .a(shift_reg[0]),
        .b(shift_reg[1]),
        .y(and_out)
    );

    // Feedback loop for binary to Gray code conversion
    always @(posedge clk) begin
        gray <= {and_out, shift_reg[3:1]} ^ shift_reg;
    end

endmodule

