module clock_top(
    input clk,
    input rst,
    input inc_button,
    input dec_button,
    input [1:0] dip_switch,
    output reg [27:0] seg,
    output reg am_pm
);

reg [3:0] hours = 4'b0000;
reg [5:0] minutes = 6'b000000;
reg [5:0] seconds = 6'b000000;
reg [1:0] time_zone_offset = 2'b00;

reg [3:0] digit_sel = 4'b1110;
reg [3:0] seg_data = 7'b0000000;
reg [1:0] am_pm_sel = 2'b00;

reg inc_button_prev = 1'b0;
reg dec_button_prev = 1'b0;

always @(posedge clk) begin
    if (rst) begin
        hours <= 4'b0000;
        minutes <= 6'b000000;
        seconds <= 6'b000000;
        time_zone_offset <= 2'b00;
        digit_sel <= 4'b1110;
        seg_data <= 7'b0000000;
        am_pm_sel <= 2'b00;
    end else begin
        // Update time
        if (seconds == 60) begin
            seconds <= 6'b000000;
            minutes <= minutes + 1;
        end
        if (minutes == 60) begin
            minutes <= 6'b000000;
            hours <= hours + 1;
        end
        if (hours == 12 && minutes == 0 && seconds == 0) begin
            am_pm_sel <= ~am_pm_sel;
        end
        if (hours == 13) begin
            hours <= 4'b0001;
        end else if (hours == 14) begin
            hours <= 4'b0010;
        end else if (hours == 15) begin
            hours <= 4'b0011;
        end else if (hours == 16) begin
            hours <= 4'b0100;
        end else if (hours == 17) begin
            hours <= 4'b0101;
        end else if (hours == 18) begin
            hours <= 4'b0110;
        end else if (hours == 19) begin
            hours <= 4'b0111;
        end else if (hours == 20) begin
            hours <= 4'b1000;
        end else if (hours == 21) begin
            hours <= 4'b1001;
        end else if (hours == 22) begin
            hours <= 4'b1010;
        end else if (hours == 23) begin
            hours <= 4'b1011;
        end else if (hours == 24) begin
            hours <= 4'b0000;
        end
        seconds <= seconds + 1;

        // Update time zone offset
        case (dip_switch)
            2'b00: time_zone_offset <= 2'b00;
            2'b01: time_zone_offset <= 2'b01;
            2'b10: time_zone_offset <= 2'b10;
            2'b11: time_zone_offset <= 2'b11;
        endcase

        // Update display
        case (digit_sel)
            4'b1110: seg_data <= 7'b1111110; // Colon
            4'b1101: seg_data <= 7'b0110000; // Digit 1
            4'b1011: seg_data <= 7'b0110000; // Digit 2
            4'b0111: seg_data <= 7'b0110000; // Digit 3
            4'b1111: seg_data <= 7'b0110000; // Digit 4
        endcase
        case (digit_sel)
            4'b1110: ; // No AM/PM indicator for colon
            4'b1101: ; // No AM/PM indicator for first digit of hours
            4'b1011: begin // Second digit of hours
                if (hours >= 12) begin
                    am_pm_sel <= 2'b10;
                end else begin
                    am_pm_sel <= 2'b01;
                end
            end
            4'b0111: ; // No AM/PM indicator for minutes
            4'b1111: ; // No AM/PM indicator for seconds
        endcase
        case (digit_sel)
            4'b1110: ; // No segment data for colon
            4'b1101: seg_data <= {7'b0000001, am_pm_sel}; // First digit of hours
            4'b1011: seg_data <= {7'b0000001, hours[3:2]}; // Second digit of hours
            4'b0111: seg_data <= {7'b0000001, minutes[5:4]}; // First digit of minutes
            4'b1111: seg_data <= {7'b0000001, seconds[5:4]}; // First digit of seconds
        endcase
        seg <= {seg_data, 7'b1111111}; // Common cathode
        digit_sel <= {digit_sel[2:0], digit_sel[3]};
    end
end

always @(posedge clk) begin
    if (rst) begin
        inc_button_prev <= 1'b0;
        dec_button_prev <= 1'b0;
    end else begin
        // Increment hours
        if (inc_button && !inc_button_prev) begin
            if (hours == 11) begin
                hours <= 4'b0000;
            end else if (hours == 12) begin
                hours <= 4'b0001;
            end else begin
                hours <= hours + 1;
            end
        end
        // Decrement hours
        if (dec_button && !dec_button_prev) begin
            if (hours == 1) begin
                hours <= 4'b0011;
            end else if (hours == 0) begin
                hours <= 4'b0000;
            end else begin
                hours <= hours - 1;
            end
        end
        inc_button_prev <= inc_button;
        dec_button_prev <= dec_button;
    end
end

endmodule

