module clock_divider (
    input clk,
    input phase_invert,
    input master_in,
    output reg clk_out1,
    output reg clk_out2
);

    parameter power_up = "low";
    parameter invert_phase = 0;
    parameter use_master_in = 0;

    always @(posedge clk or posedge master_in) begin
        if (use_master_in) begin
            clk_out1 <= ~clk_out1;
            if (invert_phase) begin
                clk_out2 <= ~master_in;
            end else begin
                clk_out2 <= master_in;
            end
        end else begin
            clk_out1 <= ~clk_out1;
            if (invert_phase) begin
                clk_out2 <= ~clk_out2;
            end else begin
                clk_out2 <= clk_out2;
            end
        end
    end

    initial begin
        if (power_up == "low") begin
            clk_out1 <= 1'b0;
            clk_out2 <= 1'b0;
        end else begin
            clk_out1 <= 1'b1;
            clk_out2 <= 1'b1;
        end
    end

