  reg stream_in_sop;
  reg stream_in_eop;
  reg [1:0] stream_in_empty;
  reg stream_in_valid;
  reg stream_out_ready;
  reg [23:0] stream_out_data;
  reg stream_out_sop;
  reg stream_out_eop;
  reg [1:0] stream_out_empty;
  reg stream_out_valid;

  always @ (posedge clock) begin
    if (!reset) begin
      stream_in_ready <= 0;
      stream_out_data <= 0;
      stream_out_sop <= 0;
      stream_out_eop <= 0;
      stream_out_empty <= 2'b11;
      stream_out_valid <= 0;
    end else begin
      // Stream in
      if (io_S_STREAM_stream_in_valid && !stream_in_valid) begin
        stream_in_data <= io_S_STREAM_stream_in_data;
        stream_in_sop <= io_S_STREAM_stream_in_startofpacket;
        stream_in_eop <= io_S_STREAM_stream_in_endofpacket;
        stream_in_empty <= io_S_STREAM_stream_in_empty;
        stream_in_valid <= 1;
        stream_in_ready <= 0;
      end else if (stream_in_valid && io_S_STREAM_stream_in_ready) begin
        stream_in_valid <= 0;
        stream_in_ready <= 1;
      end

      // Stream out
      if (io_S_STREAM_stream_out_ready && !stream_out_valid) begin
        stream_out_data <= mem[io_S_AVALON_address];
        stream_out_sop <= 0;
        stream_out_eop <= 0;
        stream_out_empty <= 2'b00;
        stream_out_valid <= 1;
        stream_out_ready <= 0;
      end else if (stream_out_valid && io_S_STREAM_stream_out_valid) begin
        stream_out_valid <= 0;
        stream_out_ready <= 1;
      end
    end
  end

  // Read/write logic
  always @ (posedge clock) begin
    if (!reset) begin
      read_data <= 0;
    end else begin
      if (io_wen) begin
        mem[io_waddr] <= io_wdata;
      end

      read_data <= mem[io_raddr];
    end
  end

  // Output logic
  assign io_rdata = read_data;
  assign io_S_STREAM_stream_in_ready = stream_in_ready;
  assign io_S_STREAM_stream_out_data = stream_out_data;
  assign io_S_STREAM_stream_out_startofpacket = stream_out_sop;
  assign io_S_STREAM_stream_out_endofpacket = stream_out_eop;
  assign io_S_STREAM_stream_out_empty = stream_out_empty;
  assign io_S_STREAM_stream_out_valid = stream_out_valid;

endmodule

