module two_bit_comparator (
    input [1:0] A,
    input [1:0] B,
    output EQ
);

    wire eq1, eq2, eq3;

    // Check if A[1] == B[1]
    xor x1(eq1, A[1], B[1]);

    // Check if A[0] == B[0]
    xor x2(eq2, A[0], B[0]);

    // Check if A == B
    and a1(eq3, eq1, eq2);

    // Set output EQ to 1 if A == B, 0 otherwise
    assign EQ = eq3;

endmodule

module serial_to_parallel(
    input Rx,
    input CLKOUT,
    output reg Rx_error,
    output reg [7:0] DATA,
    output reg DONE
);

reg [8:0] regis;
reg [7:0] regis0;
reg [3:0] i;
reg [3:0] j;
reg [1:0] k;
reg init;
reg DoIt;

initial begin
    i = 0;
    j = 0;
    init = 0;
    regis = 0;
    regis0 = 0;
    Rx_error = 0;
    DONE = 0;
    k = 0;
    DoIt = 1;
end

always @(posedge CLKOUT) begin
    if (!Rx && !i) begin
        init <= 1;
    end

    if (init) begin
        regis[i] <= Rx;
        i <= i + 1;
        if (regis[i] && (i < 8)) begin
            j <= j + 1;
        end
    end

    if (DoIt) begin
        k <= k + 1;
    end

    if (k == 3) begin
        DONE <= 0;
        DoIt <= 0;
        Rx_error <= 0;
    end

    if (!DoIt) begin
        k <= 0;
    end

    if (i == 9) begin
        DoIt <= 1;
    end

    if (i == 9) begin
        if ((!(j % 2) && regis[8]) || ((j % 2) && !regis[8])) begin
            Rx_error <= 0;
            regis0 <= {regis[7:0]};
            DATA <= regis0;
            DONE <= 1;
        end
        else begin
            Rx_error <= 1;
            regis0 <= 0;
            DATA <= regis0;
            DONE <= 0;
        end
        j <= 0;
        i <= 0;
        init <= 0;
    end
end

endmodule

module delay_buffer (
    input A,
    input VPWR,
    input VGND,
    input KAPWR,
    input VPB,
    input VNB,
    output reg X
);

    reg [3:0] buffer;
    reg [1:0] state = 0;
    reg [1:0] next_state = 0;

    always @ (posedge VPWR or negedge VGND) begin
        if (KAPWR == 1'b1) begin
            // Power-saving mode
            X <= buffer[3];
        end else begin
            // Normal mode
            case (state)
                2'b00: begin
                    buffer <= {A, buffer[3:1]};
                    next_state <= 2'b01;
                end
                2'b01: begin
                    buffer <= {buffer[3], buffer[2:0]};
                    next_state <= 2'b10;
                end
                2'b10: begin
                    buffer <= {buffer[3:1], VPB};
                    next_state <= 2'b11;
                end
                2'b11: begin
                    buffer <= {buffer[3:1], VNB};
                    next_state <= 2'b00;
                end
                default: begin
                    buffer <= 4'b0;
                    next_state <= 2'b00;
                end
            endcase
            state <= next_state;
            X <= buffer[3];
        end
    end

endmodule

module robsmult(
    input       clk, reset, 
    input [7:0] multiplier, // 8-bit data input to multiplier unit
    input [7:0] multiplicand, // 8-bit data input to multiplier unit
    output reg [15:0] product, // 16-bit data output of multiplier unit
    output reg done // flag to signal multiplication is complete to testbench
    );

    reg [7:0] Q;
    reg [7:0] M;
    reg [15:0] A;
    reg [1:0] q_last;

    always @(posedge clk) begin
        if (reset) begin
            Q <= 0;
            M <= 0;
            A <= 0;
            q_last <= 0;
            product <= 0;
            done <= 0;
        end else begin
            // update Q and A
            q_last <= {Q[0], Q[7]};
            Q <= {q_last, Q[7:1]};
            A <= {A[14:0], 0};

            // update A based on Q
            case(q_last)
                2'b01: A <= A - M;
                2'b10: A <= A + M;
                2'b11: A <= A;
                default: A <= A + {8'b0, M};
            endcase
        end
    end

    always @(posedge clk) begin
        if (reset) begin
            done <= 0;
        end else if (Q == 0) begin
            product <= A;
            done <= 1;
        end else begin
            done <= 0;
        end
    end

    // assign input values to Q and M
    initial begin
        Q <= multiplier;
        M <= multiplicand;
    end
endmodule

module top_module (
    input clk,
    input reset,      // Asynchronous active-high reset
    input enable,     // Asynchronous counter enable
    input [3:0] A,    // 4-bit input for the adder-subtractor circuit
    input [3:0] B,    // 4-bit input for the adder-subtractor circuit
    input sub,        // Selects between addition and subtraction
    input select,     // Selects between counter and adder-subtractor circuit output
    output [3:0] Q    // Final output from the active module
);

    // Counter module with asynchronous reset and enable
    reg [3:0] counter;
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 4'b0000;
        end else if (enable) begin
            counter <= counter + 1;
        end
    end

    // Adder-subtractor module
    wire [3:0] sum;
    assign sum = sub ? A - B : A + B;

    // Functional module to select maximum value
    reg [3:0] max_value;
    always @(*) begin
        if (select) begin
            max_value = counter > sum ? counter : sum;
        end else begin
            max_value = counter;
        end
    end

    // Output
    assign Q = max_value;

endmodule

module shift_add_multiplier (
    input [15:0] a,
    input [15:0] b,
    output [31:0] out
);
    reg [31:0] product;
    reg [15:0] multiplicand;
    reg [15:0] multiplier;
    integer i;

    always @(*) begin
        product = 32'h0;
        multiplicand = a;
        multiplier = b;

        for (i = 0; i < 16; i = i + 1) begin
            if (multiplier[0] == 1) begin
                product = product + (multiplicand << i);
            end
            multiplier = multiplier >> 1;
        end
    end

    assign out = product;
endmodule

