module priority_encoder (
    input [3:0] in,
    output reg [1:0] out
);
always @(*) begin
    case(in)
        4'b0001: out = 2'b00;
        4'b0010: out = 2'b01;
        4'b0100: out = 2'b10;
        4'b1000: out = 2'b11;
        default: out = 2'b11;
    endcase
end
endmodule

module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    output reg [3:0] SUM,
    output reg CARRY
);
integer i;

always @(*) begin
    SUM[0] = A[0] ^ B[0];
    CARRY = A[0] & B[0];

    for(i = 1; i < 4; i = i + 1) begin
        SUM[i] = A[i] ^ B[i] ^ CARRY;
        CARRY = (A[i] & B[i]) | (A[i] & CARRY) | (B[i] & CARRY);
    end
end
endmodule

