module pipelined_multiplier (
  input [n-1:0] a,
  input [n-1:0] b,
  output [n-1:0] c
);

parameter n = 8; // width of input signals

wire [2*n-1:0] prod;
wire [2*n-1:0] sum;
reg [n-1:0] c_reg;

// Stage 1: Generate partial products
genvar i, j;
generate
  for (i = 0; i < n; i = i + 1) begin
    for (j = 0; j < n; j = j + 1) begin
      assign prod[i+j] = a[i] & b[j];
    end
  end
endgenerate

// Stage 2: Generate partial sums
genvar k;
generate
  for (k = 0; k < n; k = k + 1) begin
    assign sum[k] = prod[k];
    for (i = 0; i < k; i = i + 1) begin
      assign sum[k] = sum[k] + prod[i+n+k];
    end
  end
endgenerate

// Stage 3: Generate final sum
always @ (posedge clk) begin
  c_reg <= sum[n-1:0];
end

assign c = c_reg;

endmodule

module mem_protect (
  input clk,
  input reset,
  input [7:0] data_in,
  input [15:0] addr,
  input write_enable,
  input block_protect,
  output [7:0] data_out
);

parameter mem_size = 1024; // size of memory in bytes
parameter block_size = 64; // size of each memory block in bytes
parameter num_blocks = 16; // number of memory blocks

// Memory array
reg [7:0] memory [0:mem_size-1];

// Memory protection block module
mem_protect_block mem_protect_inst (
  .clk(clk),
  .reset(reset),
  .block_protect(block_protect),
  .addr(addr),
  .block_size(block_size),
  .num_blocks(num_blocks),
  .protect_active(protect_active)
);

// Internal signal for memory protection block status
wire protect_active;

// Memory access process
always @(posedge clk or posedge reset) begin
  if (reset) begin
    data_out <= 8'b0;
  end else begin
    if (!protect_active) begin
      if (write_enable) begin
        memory[addr] <= data_in;
      end else begin
        data_out <= memory[addr];
      end
    end
  end
end

endmodule

// Memory protection block module
module mem_protect_block (
  input clk,
  input reset,
  input block_protect,
  input [15:0] addr,
  input block_size,
  input num_blocks,
  output protect_active
);

// State machine states
localparam IDLE = 2'b00, ACTIVE = 2'b01;

// State register
reg [1:0] state;

// Calculate block index
integer block_index;
assign block_index = addr / block_size;

// State machine process
always @(posedge clk or posedge reset) begin
  if (reset) begin
    state <= IDLE;
  end else begin
    case (state)
      IDLE: begin
        if (block_protect) begin
          state <= ACTIVE;
        end
      end

      ACTIVE: begin
        if (!block_protect) begin
          state <= IDLE;
        end
      end
    endcase
  end
end

// Protection active output
assign protect_active = (state == ACTIVE) && (block_index < num_blocks);

endmodule

module alu_risc #(parameter word_sz=8, op_sz=4)
    (output alu_zero_flag, output reg [word_sz-1:0] alu_out,
     input [word_sz-1:0] data_1, data_2, input [op_sz-1:0] sel);

    assign alu_zero_flag = ~|alu_out;
    always @(sel or data_1 or data_2) begin
        case (sel)
            op.NOP: alu_out <= 0;
            op.ADD: alu_out <= data_1 + data_2;
            op.SUB: alu_out <= data_2 - data_1;
            op.AND: alu_out <= data_1 & data_2;
            op.NOT: alu_out <= ~data_2;
            default: alu_out <= 0;
        endcase
    end
endmodule

module rx_descrambler #(
    parameter DWIDTH=16,
    parameter BITSLIP_SHIFT_RIGHT=1
)
(
    input wire              clk,
    input wire              res_n,
    input wire              bit_slip,
    output reg              locked,
    input wire [DWIDTH-1:0] data_in,
    output reg [DWIDTH-1:0] data_out
);

reg  [14:0]       lfsr;                    // LINEAR FEEDBACK SHIFT REGISTER
wire [14:0]       lfsr_slipped;            // Temporary lfsr for bitslip
wire [14:0]       lfsr_steps [DWIDTH-1:0]; // LFSR values for serial time steps
wire [14:0]       calculated_seed;
wire [DWIDTH-1:0] data_out_tmp;

generate
    if(BITSLIP_SHIFT_RIGHT==1) begin
        assign lfsr_slipped = { (lfsr_steps[DWIDTH-1][1] ^ lfsr_steps[DWIDTH-1][0]) , lfsr_steps[DWIDTH-1][14:1] };
    end else begin
        assign lfsr_slipped = { lfsr_steps[DWIDTH-1][13:0], (lfsr_steps[DWIDTH-1][14] ^ lfsr_steps[DWIDTH-1][0])};
    end
endgenerate

// SEQUENTIAL PROCESS
`ifdef ASYNC_RES
always @(posedge clk or negedge res_n)  begin `else
always @(posedge clk)  begin `endif
    if (!res_n) begin
        locked   <= 1'b0;
        lfsr     <= 15'h0;
        data_out <= {DWIDTH {1'b0}};
    end else begin

        data_out <= data_out_tmp;

        if (!locked && |data_in) begin
            lfsr <= calculated_seed;
            // Locked when the calculated seeds match
            if (calculated_seed == lfsr_steps[DWIDTH-1]) begin
                locked <= 1'b1;
            end
        end else begin
            if (bit_slip) begin
                lfsr <= lfsr_slipped;
            end else begin
                lfsr <= lfsr_steps[DWIDTH-1];
            end
        end
    end
end                 // serial shift right with left input

// SCRAMBLE

genvar j;
generate
    localparam OFFSET = DWIDTH-15; // It breaks here if DWIDTH < 15
    assign calculated_seed[14] = 1'b1; // Guess the top bit is 1

    // data_in is the past state of the LFSR, so we can figure out
    // the current value using a loop.

    for(j = 0; j < 14; j = j + 1) begin : seed_calc
        assign calculated_seed[j] = data_in[j+OFFSET] ^ data_in[j+OFFSET+1];
    end

    assign data_out_tmp [0] = data_in[0] ^ lfsr[0]; // single bit scrambled
    assign lfsr_steps[0]    = { (lfsr[1] ^ lfsr[0]) , lfsr[14:1] }; // lfsr at next bit clock
    for(j = 1; j < DWIDTH; j = j + 1) begin : scrambler_gen
        assign data_out_tmp[j] = data_in[j] ^ lfsr_steps[j-1][0];
        assign lfsr_steps[j]   = { (lfsr_steps[j-1][1] ^ lfsr_steps[j-1][0]) , lfsr_steps[j-1][14:1] };
    end
endgenerate

endmodule

module logic_checker (
    A,
    B,
    C,
    D,
    E,
    F
);

    input A;
    input B;
    input C;
    input D;
    input E;
    output F;

    assign F = (A == 1) && (B == 0) && (C == 1) && (D == 0) && (E == 1);

