module top_module( 
    input [2:0] a,
    input [2:0] b,
    input select,
    input clk,
    output [2:0] out_xor_bitwise,
    output out_and_logical,
    output [5:0] out_not
);
    wire [2:0] xor_out;
    wire and_out;
    wire [2:0] a_not;
    wire [2:0] b_not;

    xor_gate xor_inst(.a(a), .b(b), .out_xor(xor_out));
    and_gate and_inst(.a(a), .b(b), .out_and(and_out));
    d_ff d_ff_inst_a(.clk(clk), .d(~a), .q(a_not));
    d_ff d_ff_inst_b(.clk(clk), .d(~b), .q(b_not));

    always @(*) begin
        if (select == 1'b1) begin
            out_xor_bitwise = xor_out;
            out_and_logical = and_out;
            out_not[2:0] = b_not;
            out_not[5:3] = a_not;
        end
        else begin
            out_xor_bitwise = 3'b0;
            out_and_logical = 1'b0;
            out_not = {~a, ~b};
        end
    end
endmodule

