module adder_8bit_cla (
    input [7:0] a,
    input [7:0] b,
    output [7:0] s,
    output overflow
);

wire [7:0] g, p, c;

assign g = a & b;
assign p = a ^ b;
assign c[0] = 1'b0;

genvar i;
generate
    for (i = 1; i < 8; i = i + 1) begin : gen
        assign c[i] = (g[i-1] | (p[i-1] & c[i-1]));
    end
endgenerate

assign s = p + c;

assign overflow = (a[7] == b[7]) && (s[7] != a[7]);

endmodule

module top_module (
    input [7:0] a,
    input [7:0] b,
    output [7:0] s,
    output overflow
);

adder_8bit_cla adder(
    .a(a),
    .b(b),
    .s(s),
    .overflow(overflow)
);

endmodule

module dc_ctrl(input  wire        clk,
               input  wire        rst,

               input  wire `REQ   dc_ctrl_req,
               output wire `RES   dc_ctrl_res);

   parameter       debug = 0;

   wire [31:0]     addr, q;
   reg             r_ = 0;
   always @(posedge clk) r_ <= rst ? 1'b0 : dc_ctrl_req`R;
   assign addr             = dc_ctrl_req`A;
   assign dc_ctrl_res`RD   = r_ ? q : 0;
   assign dc_ctrl_res`HOLD = 0;

   dcache dc(.clock  (clk),
             .clken  (1),
             .address(addr[12:2]),
             .wren   (dc_ctrl_req`W),
             .data   (dc_ctrl_req`WD),
             .byteena(dc_ctrl_req`WBE),
             .q      (q));

   reg [1:0] state = 2'b00;
   reg [31:0] addr_reg;
   reg [31:0] data_reg;
   reg [3:0] byteena_reg;
   wire [31:0] q_reg;
   reg stall = 0;
   always @(posedge clk) begin
      if (rst) begin
         state <= 2'b00;
         addr_reg <= 0;
         data_reg <= 0;
         byteena_reg <= 0;
         stall <= 0;
      end else begin
         case (state)
            2'b00: begin // idle
               if (dc_ctrl_req`REQ) begin
                  addr_reg <= dc_ctrl_req`A;
                  if (dc_ctrl_req`W) begin
                     data_reg <= dc_ctrl_req`WD;
                     byteena_reg <= dc_ctrl_req`WBE;
                     state <= 2'b01; // write request
                  end else begin
                     state <= 2'b10; // read request
                  end
               end
            end
            2'b01: begin // write request
               if (!stall) begin
                  dc_ctrl_res`HOLD <= 0;
                  dc_ctrl_res`RD <= 0;
                  dc_ctrl_req`REQ <= 0;
                  dc_ctrl_req`A <= addr_reg;
                  dc_ctrl_req`W <= 1;
                  dc_ctrl_req`WD <= data_reg;
                  dc_ctrl_req`WBE <= byteena_reg;
                  state <= 2'b00;
               end else begin
                  dc_ctrl_res`HOLD <= 1;
               end
            end
            2'b10: begin // read request
               if (!stall) begin
                  dc_ctrl_res`HOLD <= 0;
                  dc_ctrl_res`RD <= 0;
                  dc_ctrl_req`REQ <= 0;
                  dc_ctrl_req`A <= addr_reg;
                  dc_ctrl_req`W <= 0;
                  dc_ctrl_req`WBE <= 0;
                  q_reg <= q;
                  state <= 2'b11; // read response
               end else begin
                  dc_ctrl_res`HOLD <= 1;
               end
            end
            2'b11: begin // read response
               if (!stall) begin
                  dc_ctrl_res`HOLD <= 0;
                  dc_ctrl_res`RD <= q_reg;
                  state <= 2'b00;
               end else begin
                  dc_ctrl_res`HOLD <= 1;
               end
            end
         endcase
      end
   end

   assign stall = r_ & (dc_ctrl_req`REQ | state[1]);

`ifdef SIMULATE_MAIN
   pipechecker check("dc_ctrl", clk, dc_ctrl_req, dc_ctrl_res);

   // Debugging
   always @(posedge clk) if (debug) begin
      if (dc_ctrl_res`HOLD)
        $display("%5d D$: Stall x_load %d x_store %d m_stall %d opcode %2x",
                 $time, dc_ctrl_req`R, dc_ctrl_req`W);
      else begin
         if (dc_ctrl_req`R)
           $display("%5d D$: load [%x]", $time, dc_ctrl_req`A);

         if (r_)
           $display("%5d D$: load -> %x", $time, dc_ctrl_res`RD);

         if (dc_ctrl_req`W)
           $display("%5d D$: store %x->[%x] (bytena %x)",
                    $time, dc_ctrl_req`WD, addr, dc_ctrl_req`WBE);
      end
   end
`endif
endmodule

