    input [3:0] in3,
    input select, // Select input to choose between in2 and in3
    output [3:0] out_and_bitwise, // Bitwise AND value of in0 and in1
    output [3:0] out_xor_bitwise, // Bitwise XOR value of in2 and in3
    output [3:0] out_sum // Sum of out_xor_bitwise and selected value
);

