        if (~rst_n) begin
            itcm_active_r <= 1'b0;
            dtcm_active_r <= 1'b0;
            clk_itcm <= 1'b0;
            clk_dtcm <= 1'b0;
            itcm_ls <= 1'b1;
            dtcm_ls <= 1'b1;
        end else begin
            itcm_active_r <= itcm_active;
            dtcm_active_r <= dtcm_active;

            if (core_cgstop) begin
                clk_itcm <= 1'b0;
                clk_dtcm <= 1'b0;
                itcm_ls <= 1'b1;
