                    clk_itcm <= 1'b1;
                    itcm_ls <= 1'b0;
                end else begin
                    clk_itcm <= 1'b0;
                    itcm_ls <= 1'b1;
                end

                if (dtcm_active | dtcm_active_r) begin
                    clk_dtcm <= 1'b1;
                    dtcm_ls <= 1'b0;
