assign in_above_vth = (in >= Vt_high);
assign in_below_vtl = (in <= Vt_low);

always @ (in or prev_out_reg) begin
  if (in_above_vth) begin
    out_reg = 1'b1;
    prev_out_reg = 1'b1;
  end else if (in_below_vtl) begin
    out_reg = 1'b0;
    prev_out_reg = 1'b0;
  end else begin
    out_reg = prev_out_reg;
  end
end

assign out = out_reg;

always @ (posedge out_reg or negedge out_reg) begin
  if (out_reg && !prev_out_reg) begin
    out_reg <= 1'b1;
    prev_out_reg <= 1'b1;
  end else if (!out_reg && prev_out_reg) begin
    out_reg <= 1'b0;
    prev_out_reg <= 1'b0;
  end
end

endmodule

