module edge_detector (
    input clk,
    input reset,
    input a,
    input [7:0] delay,
    output reg rise,
    output reg down
);

reg [7:0] delay_counter;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        delay_counter <= 0;
        rise <= 0;
        down <= 0;
    end else begin
        if (a && !delay_counter) begin
            rise <= 1;
        end else begin
            rise <= 0;
        end

        if (!a && !delay_counter) begin
            down <= 1;
        end else begin
            down <= 0;
        end

        if (delay_counter < delay) begin
            delay_counter <= delay_counter + 1;
        end else begin
            delay_counter <= 0;
        end
    end
end

endmodule

