module ctr_encoder
(
    input clk,
    input sync,
    input reset,

    input cal,
    input trg,
    input res_roc,
    input res_tbm,
    input res_req,
    input nmr_req,
    input trg_veto,
    input res_veto,

    output running,
    output [3:0] ctr_out,
    output trg_out,
    output res_out
);

    // maskable reset request SRFF
    reg res_req_ff;
    always @(posedge clk or posedge reset)
    begin
        if (reset) res_req_ff <= 0;
        else if (sync)
        begin
            if      (res_req) res_req_ff <= 1;
            else if (res_out) res_req_ff <= 0;
        end
    end

    // non maskable reset request SRFF
    reg nmr_req_ff;
    always @(posedge clk or posedge reset)
    begin
        if (reset) nmr_req_ff <= 0;
        else if (sync)
        begin
            if      (nmr_req) nmr_req_ff <= 1;
            else if (res_out) nmr_req_ff <= 0;
        end
    end

    wire res  = nmr_req_ff || ((res_roc || res_req_ff) && !res_veto);
    wire rtbm = res_tbm && !res_veto;
    wire trig = trg & !trg_veto;

    // state machine
    reg [6:0] ctrgen;
    localparam SM_IDLE = 7'b000_0000;
    localparam SM_CAL1 = 7'b000_1001;
    localparam SM_CAL2 = 7'b000_0001;
    localparam SM_CAL3 = 7'b001_0001;
    localparam SM_TRG1 = 7'b000_1101;
    localparam SM_TRG2 = 7'b001_1001;
    localparam SM_TRG3 = 7'b010_0001;
    localparam SM_RES1 = 7'b000_1011;
    localparam SM_RES2 = 7'b010_1001;
    localparam SM_RES3 = 7'b011_1001;
    localparam SM_TBM1 = 7'b001_1011;
    localparam SM_TBM2 = 7'b011_0001;
    localparam SM_TBM3 = 7'b100_1001;

    assign {ctr_out, trg_out, res_out, running} = ctrgen[3:0];

    always @(posedge clk or posedge reset)
    begin
        if (reset) ctrgen <= SM_IDLE;
        else if (sync)
        casex ({ctrgen,  res,  rtbm, trig, cal})
            // start (priority decoding)
                 {SM_IDLE, 1'b1, 1'bx, 1'bx, 1'bx}: ctrgen <= SM_RES1;
                 {SM_IDLE, 1'b0, 1'b1, 1'bx, 1'bx}: ctrgen <= SM_TBM1;
                 {SM_IDLE, 1'b0, 1'b0, 1'b1, 1'bx}: ctrgen <= SM_TRG1;
                 {SM_IDLE, 1'b0, 1'b0, 1'b0, 1'b1}: ctrgen <= SM_CAL1;
            // process calibrate
                 {SM_CAL1, 1'bx, 1'bx, 1'bx, 1'bx}: ctrgen <= SM_CAL2;
                 {SM_CAL2, 1'bx, 1'bx, 1'bx, 1'bx}: ctrgen <= SM_CAL3;
                 {SM_CAL3, 1'bx, 1'bx, 1'bx, 1'bx}: ctrgen <= SM_IDLE;
            // process trigger
                 {SM_TRG1, 1'bx, 1'bx, 1'bx, 1'bx}: ctrgen <= SM_TRG2;
                 {SM_TRG2, 1'bx, 1'bx, 1'bx, 1'bx}: ctrgen <= SM_TRG3;
                 {SM_TRG3, 1'bx, 1'bx, 1'bx, 1'bx}: ctrgen <= SM_IDLE;
            // process ROC reset
                 {SM_RES1, 1'bx, 1'bx, 1'bx, 1'bx}: ctrgen <= SM_RES2;
                 {SM_RES2, 1'bx, 1'bx, 1'bx, 1'bx}: ctrgen <= SM_RES3;
                 {SM_RES3, 1'bx, 1'bx, 1'bx, 1'bx}: ctrgen <= SM_IDLE;
            // process TBM reset
                 {SM_TBM1, 1'bx, 1'bx, 1'bx, 1'bx}: ctrgen <= SM_TBM2;
                 {SM_TBM2, 1'bx, 1'bx, 1'bx, 1'bx}: ctrgen <= SM_TBM3;
                 {SM_TBM3, 1'bx, 1'bx, 1'bx, 1'bx}: ctrgen <= SM_IDLE;
        endcase
    end

endmodule

module top_module (
    input [3:0] dividend,
    input [3:0] divisor,
    input A,
    input B,
    input C,
    input D,
    output reg [3:0] quotient,
    output reg [3:0] remainder,
    output reg [3:0] final_output
);

    // 4-to-16 Decoder Module
    wire [15:0] decoder_output;
    decoder_4to16 decoder(
        .in({A,B,C,D}),
        .out(decoder_output)
    );

    // Division Module
    wire [3:0] quotient_wire;
    wire [3:0] remainder_wire;
    division_module division(
        .dividend(dividend),
        .divisor(divisor),
        .quotient(quotient_wire),
        .remainder(remainder_wire)
    );

    // Output Selection
    always @(*) begin
        case (quotient_wire)
            4'b0000: decoder_output[0] = 0; // Set output 0 low
            4'b0001: decoder_output[1] = 0; // Set output 1 low
            4'b0010: decoder_output[2] = 0; // Set output 2 low
            4'b0011: decoder_output[3] = 0; // Set output 3 low
            4'b0100: decoder_output[4] = 0; // Set output 4 low
            4'b0101: decoder_output[5] = 0; // Set output 5 low
            4'b0110: decoder_output[6] = 0; // Set output 6 low
            4'b0111: decoder_output[7] = 0; // Set output 7 low
            4'b1000: decoder_output[8] = 0; // Set output 8 low
            4'b1001: decoder_output[9] = 0; // Set output 9 low
            4'b1010: decoder_output[10] = 0; // Set output 10 low
            4'b1011: decoder_output[11] = 0; // Set output 11 low
            4'b1100: decoder_output[12] = 0; // Set output 12 low
            4'b1101: decoder_output[13] = 0; // Set output 13 low
            4'b1110: decoder_output[14] = 0; // Set output 14 low
            4'b1111: decoder_output[15] = 0; // Set output 15 low
        endcase
    end

    // Final Output Module
    always @(*) begin
        final_output = quotient_wire + remainder_wire;
    end

    // Output Assignments
    assign quotient = quotient_wire;
    assign remainder = remainder_wire;

endmodule

// 4-to-16 Decoder Module
module decoder_4to16 (
    input [3:0] in,
    output reg [15:0] out
);
    always @(*) begin
        case (in)
            4'b0000: out = 16'b0000000000000001;
            4'b0001: out = 16'b0000000000000010;
            4'b0010: out = 16'b0000000000000100;
            4'b0011: out = 16'b0000000000001000;
            4'b0100: out = 16'b0000000000010000;
            4'b0101: out = 16'b0000000000100000;
            4'b0110: out = 16'b0000000001000000;
            4'b0111: out = 16'b0000000010000000;
            4'b1000: out = 16'b0000000100000000;
            4'b1001: out = 16'b0000001000000000;
            4'b1010: out = 16'b0000010000000000;
            4'b1011: out = 16'b0000100000000000;
            4'b1100: out = 16'b0001000000000000;
            4'b1101: out = 16'b0010000000000000;
            4'b1110: out = 16'b0100000000000000;
            4'b1111: out = 16'b1000000000000000;
        endcase
    end
endmodule

// Division Module
module division_module (
    input [3:0] dividend,
    input [3:0] divisor,
    output reg [3:0] quotient,
    output reg [3:0] remainder
);
    reg [3:0] dividend_reg;
    reg [3:0] divisor_reg;
    reg [3:0] quotient_reg;
    reg [3:0] remainder_reg;
    reg [3:0] count;

    always @(*) begin
        dividend_reg = dividend;
        divisor_reg = divisor;
        count = 4'b0000;
        quotient_reg = 4'b0000;
        remainder_reg = 4'b0000;

        while (dividend_reg >= divisor_reg) begin
            dividend_reg = dividend_reg - divisor_reg;
            count = count + 1;
        end

        quotient_reg = count;
        remainder_reg = dividend_reg;
    end

    assign quotient = quotient_reg;
    assign remainder = remainder_reg;

endmodule

