// up_down_counter module
module up_down_counter (
    input clk,
    input reset,
    input [3:0] load,
    input up_down,
    output reg [3:0] out
);

    always @(posedge clk) begin
        if (reset) begin
            out <= 4'b0;
        end else if (up_down) begin
            out <= out + 1;
        end else begin
            out <= out - 1;
