module pipeline_stage_1 (
    input [3:0] A,
    input B,
    output [3:0] Q,
    output COUT
);

reg [3:0] A_reg;
reg B_reg;
reg [3:0] Q_reg;
reg COUT_reg;

always @(*) begin
    A_reg = A;
    B_reg = B;
end

always @(posedge B_reg) begin
    if (B_reg == 1) begin
        Q_reg[0] = A_reg[3];
        Q_reg[1] = A_reg[0];
        Q_reg[2] = A_reg[1];
        Q_reg[3] = A_reg[2];
        COUT_reg = A_reg[3];
    end
    else if (B_reg == 2) begin
        Q_reg[0] = A_reg[1];
        Q_reg[1] = A_reg[2];
        Q_reg[2] = A_reg[3];
        Q_reg[3] = A_reg[0];
        COUT_reg = A_reg[0];
    end
    else if (B_reg == 3) begin
        Q_reg[0] = A_reg[2];
        Q_reg[1] = A_reg[3];
        Q_reg[2] = A_reg[0];
        Q_reg[3] = A_reg[1];
        COUT_reg = A_reg[1:0];
    end
    else begin
        Q_reg = A_reg;
        COUT_reg = 1'b0;
    end
end

assign Q = Q_reg;
assign COUT = COUT_reg;

endmodule

module pipeline_stage_2 (
    input [3:0] A,
    input B,
    output [3:0] Q,
