        Q_reg[2] = COUT_reg;
        Q_reg[3] = A_reg[0];
        COUT_reg = A_reg[3];
    end
    else if (B_reg == 2) begin
        Q_reg[0] = A_reg[1];
        Q_reg[1] = A_reg[2];
        Q_reg[2] = A_reg[3];
        Q_reg[3] = COUT_reg;
        COUT_reg = A_reg[1:0];
    end
    else if (B_reg == 3) begin
        Q_reg[0] = A_reg[0];
        Q_reg[1] = COUT_reg[0];
        Q_reg[2] = COUT_reg[1];
        Q_reg[3] = A_reg[3];
        COUT_reg = A_reg[1:0];
    end
    else begin
        Q_reg = A_reg;
        COUT_reg = 1'b0;
    end
end

assign Q = Q_reg;
