module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out
);

reg [7:0] shift_reg;
reg [9:0] accumulator;

reg [2:0] count;
wire [9:0] sum;

assign sum = accumulator + data_in;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        shift_reg <= 8'b0;
        accumulator <= 10'b0;
        count <= 3'b0;
        valid_b <= 1'b0;
        data_out <= 10'b0;
    end
    else begin
        shift_reg <= {shift_reg[6:0], data_in};
        accumulator <= sum;
        if (count == 3'b111) begin
            valid_b <= 1'b1;
            data_out <= accumulator;
            count <= 3'b0;
        end
        else begin
            valid_b <= 1'b0;
            count <= count + 1'b1;
        end
    end
end

assign ready_a = ~valid_b && ready_b;

endmodule

