module fsm_sequence_detection (
  input clk,
  input reset,
  input data,
  output reg match
);

parameter IDLE = 2'b00, S0 = 2'b01, S1 = 2'b10, S2 = 2'b11;
reg [1:0] state, next_state;

always @ (posedge clk) begin
  if (reset) begin
    state <= IDLE;
    match <= 0;
  end else begin
    state <= next_state;
    if (state == S2) begin
      match <= 1;
    end else begin
      match <= 0;
    end
  end
end

always @(*) begin
  case (state)
    IDLE: begin
      if (data == 1'b1) begin
        next_state = S0;
      end else begin
        next_state = IDLE;
      end
    end
    S0: begin
      if (data == 1'b0) begin
        next_state = IDLE;
      end else begin
        next_state = S1;
      end
    end
    S1: begin
      if (data == 1'b1) begin
        next_state = S2;
      end else begin
        next_state = IDLE;
      end
    end
    S2: begin
      next_state = IDLE;
    end
  endcase
end

endmodule

module I2C (
  input SCL,
  inout SDA,
  input RESET,
  input [7:0] ADDR,
  input [7:0] DATA_IN,
  input DATA_OUT_EN,
  output [7:0] DATA_OUT
);

  // Define states of the I2C state machine
  parameter IDLE = 0;
  parameter START = 1;
  parameter ADDR_WRITE = 2;
  parameter ADDR_READ = 3;
  parameter DATA_WRITE = 4;
  parameter DATA_READ_ACK = 5;
  parameter DATA_READ_NACK = 6;
  parameter STOP = 7;

  // Define internal signals
  reg [7:0] data_reg;
  reg [2:0] state;
  reg [7:0] bit_counter;
  reg [7:0] address;
  reg [7:0] data_out_reg;
  reg ack;

  // Define constants
  localparam ACK = 1'b0;
  localparam NACK = 1'b1;

  // Define output signals
  assign DATA_OUT = data_out_reg;

  // Define state machine
  always @ (posedge SCL or posedge RESET) begin
    if (RESET) begin
      state <= IDLE;
      bit_counter <= 0;
      address <= 0;
      data_reg <= 0;
      ack <= ACK;
    end else begin
      case (state)
        IDLE: begin
          if (!SCL && SDA) begin
            state <= START;
          end
        end
        START: begin
          SDA <= 0;
          state <= ADDR_WRITE;
          bit_counter <= 0;
        end
        ADDR_WRITE: begin
          if (bit_counter < 8) begin
            SDA <= ADDR[7 - bit_counter];
            bit_counter <= bit_counter + 1;
          end else begin
            SDA <= 1;
            state <= DATA_WRITE;
            bit_counter <= 0;
          end
        end
        ADDR_READ: begin
          if (bit_counter < 8) begin
            SDA <= address[7 - bit_counter];
            bit_counter <= bit_counter + 1;
          end else begin
            SDA <= 1;
            state <= DATA_READ_ACK;
            bit_counter <= 0;
          end
        end
        DATA_WRITE: begin
          if (bit_counter < 8) begin
            SDA <= DATA_IN[7 - bit_counter];
            bit_counter <= bit_counter + 1;
          end else begin
            SDA <= 1;
            state <= STOP;
            bit_counter <= 0;
          end
        end
        DATA_READ_ACK: begin
          if (!SCL && SDA) begin
            if (bit_counter < 8) begin
              data_reg[7 - bit_counter] <= SDA;
              bit_counter <= bit_counter + 1;
            end else begin
              ack <= ACK;
              state <= DATA_READ_NACK;
              bit_counter <= 0;
            end
          end
        end
        DATA_READ_NACK: begin
          if (!SCL && SDA) begin
            SDA <= 1;
            state <= STOP;
          end
        end
        STOP: begin
          SDA <= 0;
          state <= IDLE;
          bit_counter <= 0;
          address <= 0;
          data_reg <= 0;
          ack <= ACK;
        end
      endcase
    end
  end

  // Handle incoming data and address
  always @ (posedge SCL or posedge RESET) begin
    if (RESET) begin
      data_out_reg <= 0;
    end else begin
      case (state)
        IDLE: begin
          if (DATA_OUT_EN) begin
            data_out_reg <= 0;
          end
        end
        START, ADDR_WRITE, ADDR_READ, DATA_WRITE, DATA_READ_ACK, DATA_READ_NACK: begin
          if (!SCL && !SDA) begin
            address <= ADDR;
            state <= ADDR_WRITE;
            bit_counter <= 0;
          end
        end
        STOP: begin
          if (DATA_OUT_EN) begin
            data_out_reg <= data_reg;
          end
        end
      endcase
    end
  end

  // Handle bus collisions
  always @ (negedge SCL or posedge RESET) begin
    if (RESET) begin
      ack <= ACK;
    end else begin
      if (!SDA && SCL) begin
        ack <= NACK;
      end
    end
  end

  // Handle acknowledgement
  assign SDA = (state == DATA_READ_ACK && bit_counter == 8) ? ack : SDA;

endmodule

