        if (reset) begin
            sclk_reg <= 1'b0;
            mosi_reg <= 1'b0;
            ss_reg <= 1'b1;
            tx_done <= 1'b0;
            rx_done <= 1'b0;
            bit_counter <= 0;
            shift_out <= 0;
            shift_reg <= 0;
        end else begin
            if (tx_done && rx_done) begin
                // Idle state
                sclk_reg <= 1'b0;
                mosi_reg <= 1'b0;
                ss_reg <= 1'b1;
            end else if (!tx_done) begin
                // Transmitting state
                sclk_reg <= ~sclk_reg;
                if (sclk_reg) begin
                    if (bit_counter == NumberOfDataBits) begin
                        bit_counter <= 0;
                        tx_done <= 1'b1;
                    end else begin
                        mosi_reg <= tx_data[NumberOfDataBits-bit_counter-1];
                        bit_counter <= bit_counter + 1;
                    end
                end
            end else begin
                // Receiving state
                sclk_reg <= ~sclk_reg;
                if (sclk_reg) begin
                    if (bit_counter == NumberOfDataBits) begin
                        bit_counter <= 0;
                        rx_done <= 1'b1;
                    end else begin
                        shift_reg <= {shift_reg[NumberOfDataBits-2:0], miso};
                        bit_counter <= bit_counter + 1;
                    end
                end
            end
        end
    end

    always @(*) begin
        if (BidirectMode) begin
            sdat <= shift_out[NumberOfDataBits-1];
            shift_out <= {sdat, shift_out[NumberOfDataBits-2:0]};
        end else begin
            sdat <= shift_out[0];
            shift_out <= {shift_out[NumberOfDataBits-2:0], 1'b0};
        end
    end

    always @(posedge clock) begin
        if (reset) begin
            tx_data <= 0;
        end else begin
            if (!tx_done) begin
                tx_data <= shift_reg;
            end else if (!rx_done) begin
                rx_data <= shift_reg;
            end
        end
    end

