  output wire [1:0]                s_axi_bresp,   // AXI4-Lite slave: Write response
  output wire                      s_axi_bvalid,  // AXI4-Lite slave: Write response valid
  input  wire                      s_axi_bready,  // AXI4-Lite slave: Write response ready
  input  wire [AXI_ADDR_WIDTH-1:0] s_axi_araddr,  // AXI4-Lite slave: Read address
  input  wire                      s_axi_arvalid, // AXI4-Lite slave: Read address valid
  output wire                      s_axi_arready, // AXI4-Lite slave: Read address ready
  output wire [AXI_DATA_WIDTH-1:0] s_axi_rdata,   // AXI4-Lite slave: Read data
  output wire [1:0]                s_axi_rresp,   // AXI4-Lite slave: Read data response
  output wire                      s_axi_rvalid,  // AXI4-Lite slave: Read data valid
  input  wire                      s_axi_rready,  // AXI4-Lite slave: Read data ready

  // Stream side
  output wire                      s_axis_tready,
  input  wire [AXI_DATA_WIDTH-1:0] s_axis_tdata,
  input  wire                      s_axis_tvalid
);

  reg int_arready_reg, int_arready_next;
  reg [AXI_DATA_WIDTH-1:0] int_rdata_reg, int_rdata_next;
  reg int_rvalid_reg, int_rvalid_next;

  wire int_ardone_wire, int_rdone_wire;

  always @(posedge aclk)
  begin
    if(~aresetn)
    begin
      int_arready_reg <= 1'b1;
      int_rdata_reg <= {(AXI_DATA_WIDTH){1'b0}};
      int_rvalid_reg <= 1'b0;
    end
    else
    begin
      int_arready_reg <= int_arready_next;
      int_rdata_reg <= int_rdata_next;
      int_rvalid_reg <= int_rvalid_next;
    end
  end

  assign int_ardone_wire = ~int_arready_reg | s_axi_arvalid;
  assign int_rdone_wire = ~int_rvalid_reg | s_axi_rready;

  always @*
  begin
    int_arready_next = ~int_ardone_wire | int_rdone_wire;
    int_rdata_next = int_rdata_reg;
    int_rvalid_next = ~int_rdone_wire | int_ardone_wire;

    if(int_ardone_wire & int_rdone_wire)
    begin
      int_rdata_next = s_axis_tvalid ? s_axis_tdata : {(AXI_DATA_WIDTH){1'b0}};
    end
  end

  assign s_axi_awready = 1'b0;
  assign s_axi_wready = 1'b0;
  assign s_axi_bresp = 2'd0;
  assign s_axi_bvalid = 1'b0;
  assign s_axi_arready = int_arready_reg;
  assign s_axi_rdata = int_rdata_reg;
  assign s_axi_rresp = 2'd0;
  assign s_axi_rvalid = int_rvalid_reg;

  assign s_axis_tready = int_ardone_wire & int_rdone_wire;

  always @(posedge aclk)
  begin
    if(~aresetn)
    begin
      s_axi_awready <= 1'b0;
      s_axi_wready <= 1'b0;
      s_axi_bvalid <= 1'b0;
    end
    else
    begin
      if(s_axi_arvalid && int_arready_reg)
      begin
        s_axi_arready <= 1'b0;
        s_axi_rvalid <= 1'b0;
        s_axi_rdata <= {(AXI_DATA_WIDTH){1'b0}};
        s_axi_rresp <= 2'd0;
      end
      else if(int_ardone_wire && s_axi_rready)
      begin
        s_axi_arready <= 1'b1;
        s_axi_rvalid <= 1'b1;
        s_axi_rdata <= int_rdata_reg;
        s_axi_rresp <= 2'd0;
      end
      else if(s_axi_awvalid && s_axi_wvalid && int_arready_reg && int_rdone_wire)
      begin
        s_axi_awready <= 1'b1;
        s_axi_wready <= 1'b1;
        s_axi_bvalid <= 1'b1;
        s_axi_bresp <= 2'd0;
      end
      else if(s_axis_tvalid && int_ardone_wire && int_rdone_wire)
      begin
        s_axi_awready <= 1'b1;
        s_axi_wready <= 1'b1;
        s_axi_bvalid <= 1'b1;
        s_axi_bresp <= 2'd0;
      end
      else
      begin
        s_axi_awready <= 1'b0;
        s_axi_wready <= 1'b0;
        s_axi_bvalid <= 1'b0;
      end
    end
  end

endmodule

module EtherCAT_Slave (
  input [n*8-1:0] in_data,
  input in_data_valid,
  input [3:0] in_data_length,
  input in_data_error,
  input in_data_complete,
  output [n*8-1:0] out_data,
  output out_data_valid,
  output [3:0] out_data_length,
  output out_data_error,
  output out_data_complete
);

parameter n = 16; // number of bytes in the EtherCAT frame data

reg [n*8-1:0] buffer; // buffer to store the received EtherCAT frame data
reg [3:0] buffer_length; // length of the data stored in the buffer
reg buffer_valid; // flag to indicate if the buffer contains valid data
reg buffer_complete; // flag to indicate if the buffer contains a complete EtherCAT frame

reg [n*8-1:0] tx_data; // data to be transmitted over the EtherCAT network
reg tx_data_valid; // flag to indicate if there is data to be transmitted
reg [3:0] tx_data_length; // length of the data to be transmitted
reg tx_data_error; // flag to indicate if there was an error during transmission
reg tx_data_complete; // flag to indicate if the transmission is complete

// Receive data from the EtherCAT network
always @(posedge in_data_valid) begin
  if (in_data_error) begin
    // Error during reception, clear the buffer
    buffer_valid <= 0;
    buffer_complete <= 0;
  end else if (in_data_complete) begin
    // End of frame, store the data in the buffer
    buffer <= in_data;
    buffer_length <= in_data_length;
    buffer_valid <= 1;
    buffer_complete <= 1;
  end else if (buffer_valid) begin
    // Continue storing data in the buffer
    buffer <= {buffer[(n-1)*8-1:0], in_data};
    buffer_length <= buffer_length + 1;
  end
end

// Transmit data over the EtherCAT network
always @(posedge out_data_valid) begin
  if (out_data_error) begin
    // Error during transmission, clear the data to be transmitted
    tx_data_valid <= 0;
    tx_data_length <= 0;
    tx_data_error <= 1;
    tx_data_complete <= 1;
  end else if (tx_data_complete) begin
    // Transmission complete, clear the data to be transmitted
    tx_data_valid <= 0;
    tx_data_length <= 0;
    tx_data_error <= 0;
    tx_data_complete <= 0;
  end else if (tx_data_valid) begin
    // Continue transmitting data
    out_data <= tx_data;
    out_data_valid <= 1;
    out_data_length <= tx_data_length;
    out_data_error <= 0;
    out_data_complete <= 0;
    tx_data <= {tx_data[(n-1)*8-1:0], 0};
    tx_data_length <= tx_data_length - 1;
    if (tx_data_length == 0) begin
      // End of data to be transmitted
      tx_data_valid <= 0;
      tx_data_complete <= 1;
    end
  end else if (buffer_complete) begin
    // Start transmitting data from the buffer
    tx_data <= buffer;
    tx_data_valid <= 1;
    tx_data_length <= buffer_length;
    tx_data_error <= 0;
    tx_data_complete <= 0;
    buffer_valid <= 0;
    buffer_complete <= 0;
  end else begin
    // No data to transmit
    out_data_valid <= 0;
    out_data_length <= 0;
    out_data_error <= 0;
    out_data_complete <= 0;
  end
end

endmodule

