	always @(posedge KEY[2]) begin
		adx = adx - 1'b1;
		LEDR[6:0] = data[6:0];
	end

	always @(posedge KEY[3]) begin
		store = SW[6:0];
		WrEn = 0;
		adx = adx;
	end

	assign clk = clkControl ? slowClk : CLOCK_50;

endmodule

