module top
  (
   input clk,
   input reset_x,
   output TXD
   );

   wire [`ADDR_LEN-1:0] pc;
   wire [4*`INSN_LEN-1:0] idata;
   wire [8:0] 		  imem_addr;
   wire [`DATA_LEN-1:0]   dmem_data;
   wire [`DATA_LEN-1:0]   dmem_wdata;
   wire [`ADDR_LEN-1:0]   dmem_addr;
   wire 		  dmem_we;
   wire [`DATA_LEN-1:0]   dmem_wdata_core;
   wire [`ADDR_LEN-1:0]   dmem_addr_core;
   wire 		  dmem_we_core;

   wire 		  utx_we;
   wire 		  finish_we;
   wire 		  ready_tx;
   wire 		  loaded;

   reg 			  prog_loading;
   wire [4*`INSN_LEN-1:0] prog_loaddata = 0;
   wire [`ADDR_LEN-1:0]   prog_loadaddr = 0;
   wire 		  prog_dmem_we = 0;
   wire 		  prog_imem_we = 0;

   assign utx_we = (dmem_we_core && (dmem_addr_core == 32'h0)) ? 1'b1 : 1'b0;
   assign finish_we = (dmem_we_core && (dmem_addr_core == 32'h8)) ? 1'b1 : 1'b0;

   always @ (posedge clk) begin
      if (!reset_x) begin
	 if (utx_we) begin
	    TXD <= dmem_wdata[7:0];
	 end else begin
	    TXD <= 1'b0;
	 end
      end else if (utx_we) begin
	 TXD <= dmem_wdata[7:0];
      end else if (finish_we) begin
	 TXD <= 1'b1;
      end
   end

   always @ (posedge clk) begin
      if (!reset_x) begin
	 prog_loading <= 1'b1;
      end else begin
	 prog_loading <= 0;
      end
   end

   pipeline pipe
     (
      .clk(clk),
      .reset(~reset_x | prog_loading),
      .pc(pc),
      .idata(idata),
      .dmem_wdata(dmem_wdata_core),
      .dmem_addr(dmem_addr_core),
      .dmem_we(dmem_we_core),
      .dmem_data(dmem_data)
      );

   assign dmem_addr = prog_loading ? prog_loadaddr : dmem_addr_core;
   assign dmem_we = prog_loading ? prog_dmem_we : dmem_we_core;
   assign dmem_wdata = prog_loading ? prog_loaddata[127:96] : dmem_wdata_core;
   dmem datamemory(
		   .clk(clk),
		   .addr({2'b0, dmem_addr[`ADDR_LEN-1:2]}),
		   .wdata(dmem_wdata),
		   .we(dmem_we),
		   .rdata(dmem_data)
		   );

   assign imem_addr = prog_loading ? prog_loadaddr[12:4] : pc[12:4];
   imem_ld instmemory(
		      .clk(~clk),
		      .addr(imem_addr),
		      .rdata(idata),
		      .wdata(prog_loaddata),
		      .we(prog_imem_we)
		      );

   SingleUartTx sutx
     (
      .CLK(clk),
      .RST_X(reset_x),
      .TXD(TXD),
      .ERR(),
      .DT01(dmem_wdata[7:0]),
      .WE01(utx_we)
      );

   PLOADER loader
     (
      .CLK(clk),
      .RST_X(reset_x),
      .RXD(),
      .ADDR(prog_loadaddr),
      .DATA(prog_loaddata),
      .WE_32(prog_dmem_we),
      .WE_128(prog_imem_we),
      .DONE(loaded)
      );

endmodule

module verilog_module (CLK, DS, ED, MPYJ, C383, DR, DI, DOR, DOI);

  parameter total_bits = 32;

  input CLK;
  input DS;
  input ED;
  input MPYJ;
  input C383;
  input [total_bits-1:0] DR;
  input [total_bits-1:0] DI;
  output reg [total_bits-1:0] DOR;
  output reg [total_bits-1:0] DOI;

  // Declare internal wires and registers
  wire CLK_wire = CLK;
  wire DS_wire = DS;
  wire ED_wire = ED;
  wire MPYJ_wire = MPYJ;
  wire C383_wire = C383;
  wire signed [total_bits-1:0] DR_wire = DR;
  wire signed [total_bits-1:0] DI_wire = DI;

  reg signed [total_bits+1:0] dx7;
  reg signed [total_bits:0] dx3;
  reg signed [total_bits-1:0] dii;
  reg signed [total_bits-1:0] dt;
  wire signed [total_bits+1:0] dx5p;
  wire signed [total_bits+1:0] dot;

  reg edd, edd2, edd3;
  reg mpyjd, mpyjd2, mpyjd3;
  reg c3d, c3d2, c3d3;
  reg [total_bits-1:0] doo;
  reg [total_bits-1:0] droo;

  // Combinational logic block
  always @ (posedge CLK_wire) begin
    if (ED_wire) begin
      edd <= DS_wire;
      edd2 <= edd;
      edd3 <= edd2;
      mpyjd <= MPYJ_wire;
      mpyjd2 <= mpyjd;
      mpyjd3 <= mpyjd2;
      c3d <= C383_wire;
      c3d2 <= c3d;
      c3d3 <= c3d2;

      if (DS_wire) begin
        dx7 <= (DR_wire << 2) - (DR_wire >>> 1);
        dx3 <= DR_wire + (DR_wire >>> 1);
        dt <= DR_wire;
        dii <= DI_wire;
      end
      else begin
        dx7 <= (dii << 2) - (dii >>> 1);
        dx3 <= dii + (dii >>> 1);
        dt <= dii;
      end

      if (c3d || c3d2) doo <= dot >>> 2;
      else doo <= dot >>> 2;

      droo <= doo;

      if (edd3) begin
        if (mpyjd3) begin
          DOR <= doo;
          DOI <= -droo;
        end
        else begin
          DOR <= droo;
          DOI <= doo;
        end
      end
    end
  end

  assign dx5p = (c3d || c3d2) ? ((dt >>> 5) + dx3) : (dx7 + (dx3 >>> 3));
  assign dot = (c3d || c3d2) ? dx5p - (dt >>> 11) : (dx5p + ((dt >>> 7) + (dx3 >>> 13)));

endmodule

module my_and4 (
    input A,
    input B,
    input C,
    input D,
    output reg X
);

    wire AB;
    wire CD;
    wire ABCD;

    // AND gate for A and B
    and gate_AB (
        .a(A),
        .b(B),
        .o(AB)
    );

    // AND gate for C and D
    and gate_CD (
        .a(C),
        .b(D),
        .o(CD)
    );

    // AND gate for AB and CD
    and gate_ABCD (
        .a(AB),
        .b(CD),
        .o(ABCD)
    );

    // NOT gate for ABCD
    not gate_X (
        .a(ABCD),
        .o(X)
    );

endmodule

