module signed_divider (
    input [7:0] dividend,
    input [7:0] divisor,
    output reg [7:0] quotient,
    output reg [7:0] remainder
);

reg [7:0] dividend_reg;
reg [7:0] divisor_reg;
reg [7:0] quotient_reg;
reg [7:0] remainder_reg;

reg [3:0] stage;
reg [3:0] count;

wire [3:0] adder_out;
wire [3:0] subtractor_out;
wire [7:0] shifter_out;

assign adder_out = dividend_reg[3:0] + divisor_reg[3:0];
assign subtractor_out = dividend_reg[3:0] - divisor_reg[3:0];
assign shifter_out = {subtractor_out, dividend_reg[7:4]};

always @(posedge clk) begin
    if (reset) begin
        stage <= 0;
        count <= 0;
        dividend_reg <= 0;
        divisor_reg <= 0;
        quotient_reg <= 0;
        remainder_reg <= 0;
    end else begin
        case (stage)
            0: begin
                dividend_reg <= dividend;
                divisor_reg <= divisor;
                stage <= 1;
            end
            1: begin
                dividend_reg <= dividend_reg << 4;
                divisor_reg <= divisor_reg << 4;
                stage <= 2;
            end
            2: begin
                if (count == 0) begin
                    quotient_reg[7] <= dividend_reg[7] ^ divisor_reg[7];
                    stage <= 3;
                end else begin
                    count <= count - 1;
                    stage <= 2;
                end
            end
            3: begin
                if (dividend_reg[7] == 1) begin
                    dividend_reg <= subtractor_out;
                    quotient_reg <= quotient_reg << 1;
                    quotient_reg[0] <= 0;
                    stage <= 4;
                end else begin
                    quotient_reg <= quotient_reg << 1;
                    quotient_reg[0] <= 1;
                    stage <= 4;
                end
            end
            4: begin
                dividend_reg <= shifter_out;
                stage <= 5;
            end
            5: begin
                if (count == 7) begin
                    remainder_reg <= dividend_reg;
                    stage <= 6;
                end else begin
                    count <= count + 1;
                    stage <= 5;
                end
            end
            6: begin
                quotient <= quotient_reg;
                remainder <= remainder_reg;
                stage <= 0;
            end
        endcase
    end
end

endmodule

module top_module (
    input clk,
    input RST,
    input [3:0] a,
    input [3:0] b,
    input sub,
    input cin,
    input select,
    output reg cout,
    output reg overflow,
    output [7:0] q
);

reg [3:0] counter;
reg [3:0] adder_out;
reg [3:0] selected_out;

wire [3:0] adder_in;
assign adder_in = sub ? (a - b - cin) : (a + b + cin);

always @(posedge clk or negedge RST) begin
    if (!RST) begin
        counter <= 4'b0;
        adder_out <= 4'b0;
        selected_out <= 4'b0;
        cout <= 1'b0;
        overflow <= 1'b0;
        q <= 8'b0;
    end else begin
        counter <= counter + 1;
        adder_out <= adder_in;
        selected_out <= select ? adder_out : counter;
        {cout, q} <= selected_out + counter;
        overflow <= (selected_out[3] == counter[3]) && (selected_out[3] != q[3]);
    end
end

endmodule

module bcd_to_binary (
    input [3:0] bcd,
    output reg [3:0] binary
);

always @* begin
    case (bcd)
        4'd0: binary = 4'b0000;
        4'd1: binary = 4'b0001;
        4'd2: binary = 4'b0010;
        4'd3: binary = 4'b0011;
        4'd4: binary = 4'b0100;
        4'd5: binary = 4'b0101;
        4'd6: binary = 4'b0110;
        4'd7: binary = 4'b0111;
        4'd8: binary = 4'b1000;
        4'd9: binary = 4'b1001;
        default: binary = 4'bxxxx;
    endcase
end

endmodule

module top_module (
    input clk,
    input reset,       // Synchronous active-high reset
    input [15:0] in1,  // First input to the multiplexer
    input [15:0] in2,  // Second input to the multiplexer
    input sel,         // Select signal for the multiplexer
    output [3:1] ena,  // Enable signals for the upper three digits of the BCD counter
    output [15:0] q    // 16-bit output of the system
);

reg [15:0] mux_out;
reg [9:0] bcd_count;
wire [3:0] bcd_out;
reg [15:0] binary_out;

bcd_to_binary bcd_converter(
    .bcd(bcd_out),
    .binary(binary_out)
);

always @(posedge clk) begin
    if (reset) begin
        mux_out <= 16'b0;
        bcd_count <= 10'd0;
        ena <= 3'b0;
    end else begin
        mux_out <= sel ? in2 : in1;
        if (bcd_count == 10'd999) begin
            bcd_count <= 10'd0;
            ena <= 3'b0;
        end else begin
            bcd_count <= bcd_count + 1;
            if (bcd_count[9]) ena <= {3'b0, 1'b1, 2'b0};
            else if (bcd_count[8]) ena <= {3'b0, 2'b1, 1'b0};
            else if (bcd_count[7]) ena <= {3'b0, 3'b1};
        end
    end
end

assign bcd_out = {bcd_count[9:8], bcd_count[7:4]};
assign q = {mux_out[15:8], binary_out};

endmodule

module up_down_counter (
    input clk,
    input reset,
    input [3:0] load,
    input [1:0] mode,
    output reg [3:0] count_out
);

    reg [3:0] count_reg;

    always @(posedge clk) begin
        if (reset) begin
            count_reg <= 4'b0;
        end else begin
            case (mode)
                2'b00: count_reg <= count_reg + 1;
                2'b01: count_reg <= count_reg - 1;
                2'b10: count_reg <= load;
                2'b11: begin
                    if (count_reg == compare) begin
                        equal_out <= 1'b1;
                    end else begin
                        equal_out <= 1'b0;
                    end
                end
            endcase
        end
    end

    assign count_out = count_reg;

endmodule

module comparator (
    input [3:0] a,
    input [3:0] b,
    output reg equal_out
);

    always @(a, b) begin
        if (a == b) begin
            equal_out <= 1'b1;
        end else begin
            equal_out <= 1'b0;
        end
    end

endmodule

module top_module (
    input clk,
    input reset,
    input [3:0] load,
    input [3:0] compare,
    input [1:0] mode,
    output [3:0] count_out,
    output reg equal_out
);

    wire [3:0] count_wire;
    wire equal_wire;

    up_down_counter counter_inst (
        .clk(clk),
        .reset(reset),
        .load(load),
        .mode(mode),
        .count_out(count_wire),
        .equal_out(equal_wire)
    );

    comparator comparator_inst (
        .a(count_wire),
        .b(compare),
        .equal_out(equal_wire)
    );

    assign equal_out = equal_wire;

endmodule

module video_timing(
    input [3:0] trs,
    input is_interlaced,
    input is_serial_output,
    input [15:0] is_sample_count_f0,
    input [15:0] is_line_count_f0,
    input [15:0] is_sample_count_f1,
    input [15:0] is_line_count_f1,
    input [15:0] is_h_front_porch,
    input [15:0] is_h_sync_length,
    input [15:0] is_h_blank,
    input [15:0] is_v_front_porch,
    input [15:0] is_v_sync_length,
    input [15:0] is_v_blank,
    input [15:0] is_v1_front_porch,
    input [15:0] is_v1_sync_length,
    input [15:0] is_v1_blank,
    input [15:0] is_ap_line,
    input [15:0] is_v1_rising_edge,
    input [15:0] is_f_rising_edge,
    input [15:0] is_f_falling_edge,
    input [15:0] is_anc_line,
    input [15:0] is_v1_anc_line,

    output reg interlaced_nxt,
    output reg serial_output_nxt,
    output reg [15:0] h_total_minus_one_nxt,
    output reg [15:0] v_total_minus_one_nxt,
    output reg [15:0] ap_line_nxt,
    output reg [15:0] ap_line_end_nxt,
    output reg [15:0] h_blank_nxt,
    output reg [15:0] sav_nxt,
    output reg [15:0] h_sync_start_nxt,
    output reg [15:0] h_sync_end_nxt,
    output reg [15:0] f2_v_start_nxt,
    output reg [15:0] f1_v_start_nxt,
    output reg [15:0] f1_v_end_nxt,
    output reg [15:0] f2_v_sync_start_nxt,
    output reg [15:0] f2_v_sync_end_nxt,
    output reg [15:0] f1_v_sync_start_nxt,
    output reg [15:0] f1_v_sync_end_nxt,
    output reg [15:0] f_rising_edge_nxt,
    output reg [15:0] f_falling_edge_nxt,
    output reg [12:0] total_line_count_f0_nxt,
    output reg [12:0] total_line_count_f1_nxt,
    output reg [15:0] f2_anc_v_start_nxt,
    output reg [15:0] f1_anc_v_start_nxt
);

wire [15:0] v_active_lines;
wire [15:0] v_total;
wire [15:0] v1_rising_edge;
wire [15:0] v2_rising_edge;
wire [15:0] f1_v_sync;
wire [15:0] f2_v_sync;
wire [15:0] total_line_count_f0_nxt_full;
wire [15:0] total_line_count_f1_nxt_full;

assign v_active_lines = (is_interlaced ? is_line_count_f1 : 16'd0) + is_line_count_f0;
assign v_total = v_active_lines + (is_interlaced ? is_v1_blank : 16'd0) + is_v_blank;
assign v1_rising_edge = is_v1_rising_edge - is_ap_line;
assign v2_rising_edge = v_active_lines + (is_interlaced ? is_v1_blank : 16'd0);
assign f1_v_sync = v1_rising_edge + is_v1_front_porch;
assign f2_v_sync = v2_rising_edge + is_v_front_porch;

assign interlaced_nxt = is_interlaced;
assign serial_output_nxt = is_serial_output;

// counter wrapping
always @* begin
    h_total_minus_one_nxt = is_sample_count_f0 + is_h_blank - 16'd1;
    v_total_minus_one_nxt = v_total - 16'd1;
end

// line numbering
always @* begin
    ap_line_nxt = is_ap_line;
    ap_line_end_nxt = v_total - is_ap_line;
end

// horizontal blanking end
always @* begin
    h_blank_nxt = is_h_blank;
    sav_nxt = is_h_blank - trs;
end

// horizontal sync start & end
always @* begin
    h_sync_start_nxt = is_h_front_porch;
    h_sync_end_nxt = is_h_front_porch + is_h_sync_length;
end

// f2 vertical blanking start
always @* begin
    f2_v_start_nxt = v2_rising_edge;
end

// f1 vertical blanking start & end
always @* begin
    f1_v_start_nxt = v1_rising_edge;
    f1_v_end_nxt = v1_rising_edge + is_v1_blank;
end

// f2 vertical sync start & end
always @* begin
    f2_v_sync_start_nxt = f2_v_sync;
    f2_v_sync_end_nxt = f2_v_sync + is_v_sync_length;
end

// f1 vertical sync start and end
always @* begin
    f1_v_sync_start_nxt = f1_v_sync;
    f1_v_sync_end_nxt = f1_v_sync + is_v1_sync_length;
end

// f rising edge
always @* begin
    f_rising_edge_nxt = is_f_rising_edge - is_ap_line;
    f_falling_edge_nxt = v_total - (is_ap_line - is_f_falling_edge);
end

// sync generation
always @* begin
    total_line_count_f0_nxt_full = is_line_count_f0 + (is_v_blank - is_v_front_porch + is_v1_front_porch) - 16'd1;
    total_line_count_f1_nxt_full = is_line_count_f1 + (is_v1_blank - is_v1_front_porch + is_v_front_porch) - 16'd1;
    total_line_count_f0_nxt = total_line_count_f0_nxt_full[12:0];
    total_line_count_f1_nxt = total_line_count_f1_nxt_full[12:0];
end

// ancilliary data position
always @* begin
    f2_anc_v_start_nxt = v_total - (is_ap_line - is_anc_line);
    f1_anc_v_start_nxt = is_v1_anc_line - is_ap_line;
end

endmodule

module tone_detection_generation (
  input clk,
  input reset,
  input in,
  input freq,
  output det,
  output gen
);

  reg [31:0] phase_acc = 0;
  reg [31:0] phase_inc = 0;
  reg [31:0] tone = 0;
  reg [31:0] threshold = 0;
  reg [31:0] sample_count = 0;
  reg [31:0] sample_rate = 48000;
  reg [31:0] sample_period = 0;
  reg [31:0] sample_threshold = 0;
