                            bit_counter <= 0;
                            read_data <= 0;
                            sda_ack <= 1'b0;
                            scl_ack <= 1'b0;
                            sda_out_last <= SDA_HIGH;
                            sda_ack_last <= 1'b0;
                            scl_ack_last <= 1'b0;
                            sda_out_en <= 1'b0;
                            avs_ctrl_readdata <= read_data;
                        end else begin
                            state <= 2'b01;
