module control_logic (
    input select,
    input [2:0] shift_register_3_q,
    input [3:0] shift_register_4_q,
    output [3:0] q
);

    wire [2:0] shift_register_3_out;
    wire [3:0] shift_register_4_out;

    shift_register_3 shift_reg_3 (
        .clk(clk),
        .d(d),
        .q(shift_register_3_out)
    );

    shift_register_4 shift_reg_4 (
        .clk(clk),
        .d(d),
        .q(shift_register_4_out)
    );

    binary_adder adder (
        .a(shift_register_3_out),
        .b(shift_register_4_out),
        .sum(q)
    );

    always @(*) begin
        if (select) begin
            q = shift_register_4_out;
        end else begin
            q = shift_register_3_out;
        end
    end

endmodule

