module signed_add_sub (
    input clk,
    input reset, // Synchronous active-high reset
    input signed [7:0] a, b, // Signed 8-bit inputs
    input sub, // Input to select between addition and subtraction
    output reg [7:0] out, // 8-bit output from the multiplexer
    output reg [15:0] abs_out // 16-bit output from the functional module
);

    wire signed [7:0] add_out;
    wire signed [15:0] ext_out;

    // Instantiate the 8-bit adder module
    eight_bit_adder adder_inst (
        .a(a),
        .b(b),
        .cin(sub),
        .sum(add_out)
    );

    // Use the 4-to-1 multiplexer to select between addition and subtraction
    always @ (posedge clk) begin
        if (reset) begin
            out <= 0;
        end else begin
            case (sub)
                1'b0: out <= add_out;
                1'b1: out <= a - b;
            endcase
        end
    end

    // Functional module to sign-extend the output and output the absolute value
    always @ (posedge clk) begin
        if (reset) begin
            abs_out <= 0;
        end else begin
            if (out[7] == 1) begin
                abs_out <= {8'b11111111, out};
            end else begin
                abs_out <= {8'b00000000, out};
            end
        end
    end

endmodule

// 8-bit adder module
module eight_bit_adder (
    input signed [7:0] a, b, // Signed 8-bit inputs
    input cin, // Carry-in
    output reg signed [7:0] sum // 8-bit sum output
);

    always @ (a, b, cin) begin
        sum = a + b + cin;
    end

endmodule

module soc(
    input inclk,
    input rst_,
    input [31:0] addr,
    inout [7:0] data,
    input cs1_,
    input cs2_,
    input oe_,
    input we_,
    output spi_miso
);

reg [31:0] spi_addr;
reg [1:0] spi_state;
reg [7:0] spi_data;
wire spi_cs;

test_ram_if r1(.clk(inclk), .addr(addr[18:0]), .data(data), .cs_(cs1_), .oe_(oe_), .we_(we_));
test_ram_if r2(.clk(inclk), .addr(addr[18:0]), .data(data), .cs_(cs2_), .oe_(oe_), .we_(we_));

assign spi_cs = ~(cs1_ | cs2_);

always @(posedge inclk) begin
    if (rst_) begin
        spi_data <= 8'h00;
        spi_addr <= 32'h00000000;
        spi_state <= 2'b00;
    end else begin
        case (spi_state)
            2'b00: begin
                if (~spi_cs) begin
                    spi_state <= 2'b01;
                end
            end
            2'b01: begin
                spi_addr <= addr;
                spi_state <= 2'b10;
            end
            2'b10: begin
                if (spi_data[7]) begin // write command
                    if (we_) begin
                        if (~spi_data[6]) begin // write to RAM module 1
                            r1.addr <= spi_addr[18:0];
                            r1.data <= data;
                            r1.we_ <= 1;
                        end else begin // write to RAM module 2
                            r2.addr <= spi_addr[18:0];
                            r2.data <= data;
                            r2.we_ <= 1;
                        end
                        spi_state <= 2'b00;
                    end
                end else begin // read command
                    if (oe_) begin
                        if (~spi_data[6]) begin // read from RAM module 1
                            r1.addr <= spi_addr[18:0];
                            data <= r1.data;
                        end else begin // read from RAM module 2
                            r2.addr <= spi_addr[18:0];
                            data <= r2.data;
                        end
                        spi_state <= 2'b00;
                    end
                end
            end
        endcase
    end
end

assign spi_miso = spi_data[7] ? 1'bz : data;

endmodule

module bitwise_and(
  input [3:0] X,
  input [3:0] Y,
  output reg [3:0] result,
  output reg greater_than_or_equal_to_5
);

  always @* begin
    result = X & Y;

    if (result >= 5) begin
      greater_than_or_equal_to_5 = 1;
    end else begin
      greater_than_or_equal_to_5 = 0;
    end
  end

endmodule

module PWM_controller #
	(
		parameter integer C_PWM_AXI_DATA_WIDTH	= 32,
		parameter integer C_PWM_AXI_ADDR_WIDTH	= 4
	)
	(
		output wire pwm,
		output wire interrupt,
		input wire  pwm_axi_aclk,
		input wire  pwm_axi_aresetn,
		input wire [C_PWM_AXI_ADDR_WIDTH-1 : 0] pwm_axi_awaddr,
		input wire [2 : 0] pwm_axi_awprot,
		input wire  pwm_axi_awvalid,
		output wire  pwm_axi_awready,
		input wire [C_PWM_AXI_DATA_WIDTH-1 : 0] pwm_axi_wdata,
		input wire [(C_PWM_AXI_DATA_WIDTH/8)-1 : 0] pwm_axi_wstrb,
		input wire  pwm_axi_wvalid,
		output wire  pwm_axi_wready,
		output wire [1 : 0] pwm_axi_bresp,
		output wire  pwm_axi_bvalid,
		input wire  pwm_axi_bready,
		input wire [C_PWM_AXI_ADDR_WIDTH-1 : 0] pwm_axi_araddr,
		input wire [2 : 0] pwm_axi_arprot,
		input wire  pwm_axi_arvalid,
		output wire  pwm_axi_arready,
		output wire [C_PWM_AXI_DATA_WIDTH-1 : 0] pwm_axi_rdata,
		output wire [1 : 0] pwm_axi_rresp,
		output wire  pwm_axi_rvalid,
		input wire  pwm_axi_rready
	);

	reg [C_PWM_AXI_DATA_WIDTH-1:0] duty_reg = 0;
	reg [C_PWM_AXI_DATA_WIDTH-1:0] period_reg = 0;
	reg [C_PWM_AXI_DATA_WIDTH-1:0] ctrl_reg = 0;
	reg [C_PWM_AXI_DATA_WIDTH-1:0] status_reg = 0;

	wire [C_PWM_AXI_DATA_WIDTH-1:0] duty_reg_write;
	wire [C_PWM_AXI_DATA_WIDTH-1:0] period_reg_write;
	wire [C_PWM_AXI_DATA_WIDTH-1:0] ctrl_reg_write;

	assign duty_reg_write = pwm_axi_wstrb[3] ? {32'h00000000, pwm_axi_wdata} : {duty_reg[31:0], pwm_axi_wdata};
	assign period_reg_write = pwm_axi_wstrb[3] ? {32'h00000000, pwm_axi_wdata} : {period_reg[31:0], pwm_axi_wdata};
	assign ctrl_reg_write = pwm_axi_wstrb[3] ? {32'h00000000, pwm_axi_wdata} : {ctrl_reg[31:0], pwm_axi_wdata};

	always @(posedge pwm_axi_aclk) begin
		if (!pwm_axi_aresetn) begin
			duty_reg <= 0;
			period_reg <= 0;
			ctrl_reg <= 0;
			status_reg <= 0;
		end else begin
			if (pwm_axi_awvalid && pwm_axi_awready) begin
				case (pwm_axi_awaddr[C_PWM_AXI_ADDR_WIDTH-1:0])
					4'h0: duty_reg <= duty_reg_write;
					4'h4: period_reg <= period_reg_write;
					4'h8: ctrl_reg <= ctrl_reg_write;
				endcase
			end
			if (pwm_axi_arvalid && pwm_axi_arready) begin
				case (pwm_axi_araddr[C_PWM_AXI_ADDR_WIDTH-1:0])
					4'h0: pwm_axi_rdata <= duty_reg;
					4'h4: pwm_axi_rdata <= period_reg;
					4'h8: pwm_axi_rdata <= ctrl_reg;
					4'hC: pwm_axi_rdata <= status_reg;
				endcase
			end
			status_reg[0] <= (ctrl_reg[0] && (duty_reg >= period_reg));
			interrupt <= status_reg[0];
		end
	end

	reg [C_PWM_AXI_DATA_WIDTH-1:0] count = 0;
	reg enable = 0;

	always @(posedge pwm_axi_aclk) begin
		if (ctrl_reg[0]) begin
			enable <= 1;
			if (ctrl_reg[1]) begin
				// Hardware PWM
			end else begin
				// Software PWM
				if (count < period_reg) begin
					count <= count + 1;
				end else begin
					count <= 0;
				end
			end
		end else begin
			enable <= 0;
			count <= 0;
		end
	end

	assign pwm = (count < duty_reg) ? 1'b1 : 1'b0;

endmodule

module half_subtractor (
  input A,
  input B,
  output Diff,
  output Borrow
);
  assign Diff = A ^ B;
  assign Borrow = A & ~B;
endmodule

module full_subtractor (
  input A,
  input B,
  input Borrow,
  output Diff,
  output Borrowout
);
  assign Diff = A ^ B ^ Borrow;
  assign Borrowout = (A & Borrow) | (B & ~A) | (A & ~Borrow);
endmodule

module byte_splitter(
    input wire [15:0] in,
    input wire select,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo
);

    wire [7:0] hi_shifted;
    wire [7:0] lo_shifted;
    wire [7:0] hi_out;
    wire [7:0] lo_out;

    // Barrel shifter for upper byte
    assign hi_shifted[0] = in[8];
    assign hi_shifted[1] = in[9];
    assign hi_shifted[2] = in[10];
    assign hi_shifted[3] = in[11];
    assign hi_shifted[4] = in[12];
    assign hi_shifted[5] = in[13];
    assign hi_shifted[6] = in[14];
    assign hi_shifted[7] = in[15];

    // Barrel shifter for lower byte
    assign lo_shifted[0] = in[1];
    assign lo_shifted[1] = in[2];
    assign lo_shifted[2] = in[3];
    assign lo_shifted[3] = in[4];
    assign lo_shifted[4] = in[5];
    assign lo_shifted[5] = in[6];
    assign lo_shifted[6] = in[7];
    assign lo_shifted[7] = in[0];

    // Complement output based on select input
    assign hi_out = select ? ~hi_shifted : ~lo_shifted;
    assign lo_out = select ? ~lo_shifted : ~hi_shifted;

    // Output to top module
    assign out_hi = hi_out;
    assign out_lo = lo_out;

endmodule

module pipelined_adder (
    input clk,
    input reset,
    input [7:0] a,
    input [7:0] b,
    output [7:0] s,
    output overflow
);

reg [7:0] a_reg, b_reg, s_reg;
reg carry_in_reg, carry_out_reg;
wire [7:0] sum1, sum2;
wire carry1, carry2;

assign s = s_reg;
assign overflow = (a[7] == b[7] && s[7] != a[7]) ? 1 : 0;

// Pipeline stage 1
always @(posedge clk) begin
    if (reset) begin
        a_reg <= 0;
        b_reg <= 0;
        s_reg <= 0;
        carry_in_reg <= 0;
        carry_out_reg <= 0;
    end else begin
        a_reg <= a;
        b_reg <= b;
        carry_in_reg <= carry_out_reg;
    end
end

// Pipeline stage 2
carry_lookahead_adder cla1 (
    .a(a_reg),
    .b(b_reg),
    .carry_in(carry_in_reg),
    .sum(sum1),
    .carry_out(carry1)
);

// Pipeline stage 3
always @(posedge clk) begin
    if (reset) begin
        s_reg <= 0;
        carry_out_reg <= 0;
    end else begin
        s_reg <= sum1;
        carry_out_reg <= carry1;
    end
end

// Pipeline stage 4
carry_lookahead_adder cla2 (
    .a(a_reg),
    .b(b_reg),
    .carry_in(carry_in_reg),
    .sum(sum2),
    .carry_out(carry2)
);

// Pipeline stage 5
always @(posedge clk) begin
    if (reset) begin
        s_reg <= 0;
        carry_out_reg <= 0;
    end else begin
        s_reg <= sum2;
        carry_out_reg <= carry2;
    end
end

endmodule

// Carry-lookahead adder module
module carry_lookahead_adder (
    input [7:0] a,
    input [7:0] b,
    input carry_in,
    output [7:0] sum,
    output carry_out
);

wire [7:0] p, g;
wire [6:0] c;

assign p = a ^ b;
assign g = a & b;
assign c[0] = carry_in;

genvar i;
generate
    for (i = 1; i < 7; i = i + 1) begin : carry_generation
        assign c[i] = g[i-1] | (p[i-1] & c[i-1]);
    end
endgenerate

assign sum = p + (c << 1);
assign carry_out = g[6] | (p[6] & c[6]);

endmodule

module fifo_mux(input  reset,
		input  clear,
		input  clk,
		input  pia_e,
		output reg pia_ca1, pia_cb1,
		input  pia_ca2, pia_cb2,
		output reg [6:0] pia_pa,
		input  [6:0] pia_pb,
		output pia_da,
		input  fifo_rxf, fifo_txe,
		output reg fifo_rd, fifo_wr,
		inout  [7:0] fifo_data);

	localparam STATE_READ_SETUP	   = 3'b000;
	localparam STATE_READ_STROBE_LOW   = 3'b001;
	localparam STATE_READ_STROBE_HIGH  = 3'b010;
	localparam STATE_WRITE_SETUP	   = 3'b100;
	localparam STATE_WRITE_STROBE_LOW  = 3'b101;
	localparam STATE_WRITE_STROBE_HIGH = 3'b110;

	localparam STATE_WRITE_MASK = 1<<2;

	reg [7:0] fifo_data_out;
	reg [2:0] state;

	always @(posedge clk) begin
		if (!reset) begin
			pia_ca1 <= 1'b0;
			pia_cb1 <= 1'b0;
			fifo_rd <= 1'b1;
			fifo_wr <= 1'b1;
			state <= STATE_READ_SETUP;
		end
		else if (!pia_e) begin
			pia_ca1 <= !fifo_rxf;
			pia_cb1 <= !fifo_txe;
			state <= STATE_READ_STROBE_LOW;
		end
		else begin
			case (state)
			STATE_READ_STROBE_LOW: begin
				if (pia_ca2) begin
					fifo_rd <= 1'b0;
				end
				state <= STATE_READ_STROBE_HIGH;
			end

			STATE_READ_STROBE_HIGH: begin
				if (pia_ca2) begin
					pia_pa <= fifo_data[6:0];
					fifo_rd <= 1'b1;
					pia_ca1 <= 1'b0;
				end
				state <= STATE_WRITE_SETUP;
			end

			STATE_WRITE_SETUP: begin
				if (pia_cb2) begin
					fifo_data_out <= {0'b0, pia_pb[6:0]};
				end
				state <= STATE_WRITE_STROBE_LOW;
			end

			STATE_WRITE_STROBE_LOW: begin
				if (pia_cb2) begin
					fifo_wr <= 1'b0;
				end
				state <= STATE_WRITE_STROBE_HIGH;
			end

			STATE_WRITE_STROBE_HIGH: begin
				if (pia_cb2) begin
					fifo_wr <= 1'b1;
					if (pia_cb2) begin
						pia_cb1 <= 1'b0;
					end
				end
				state <= STATE_READ_SETUP;
			end
			endcase
		end
	end

	assign pia_da = !pia_cb2 || fifo_txe;
	assign fifo_data = (state & STATE_WRITE_MASK) ? fifo_data_out : 8'bz;
endmodule

module counter(
    input CP,M,D,C,B,A,LD,CLR,
    output reg Qd,Qc,Qb,Qa,Qcc
    );
    reg [3:0] count;
    always @(posedge CP or negedge CLR or negedge LD)
    begin
        if(CLR == 0)
        begin
            count = 0;
            {Qd,Qc,Qb,Qa} = count;
            Qcc = 1;
        end
        else if(LD == 0)
        begin
            count = {D,C,B,A};
            {Qd,Qc,Qb,Qa} = count;
            Qcc = 1;
        end
        else if(M == 1)
        begin
            if(count == 15)
            begin
                count = 0;
                {Qd,Qc,Qb,Qa} = count;
                Qcc = 0;
            end
            else
            begin
                count  = count + 1;
                {Qd,Qc,Qb,Qa} = count;
                Qcc = 1;
            end
        end
        else
        begin
            if(count == 0)
            begin
                count = 15;
                {Qd,Qc,Qb,Qa} = count;
                Qcc = 0;
            end
            else
            begin
                count =count - 1;
                {Qd,Qc,Qb,Qa} = count;
                Qcc = 1;
            end
        end 
    end
endmodule

