module inv_trig (
  input [1:0] func_type,
  input [31:0] sin_val,
  input [31:0] cos_val,
  input [31:0] tan_val,
  output reg [31:0] angle
);

parameter ARCSINE = 2'b00; // function type: arcsine
parameter ARCCOSINE = 2'b01; // function type: arccosine
parameter ARCTANGENT = 2'b10; // function type: arctangent

always @(*) begin
  case (func_type)
