module greater_of_two(
    input [7:0] A,
    input [7:0] B,
    output reg [7:0] G
);

    assign G = (A > B) ? A : B;

endmodule

module comparator(
    input [7:0] A,
    input [7:0] B,
    output reg [7:0] G
);

    always @(*) begin
        if (A > B) begin
            G = 1;
        end else begin
            G = 0;
        end
    end

endmodule

module final_module(
    input [7:0] A,
    input [7:0] B,
    output reg [7:0] G
);

    wire [7:0] greater_output;
    wire [7:0] comparator_output;

    greater_of_two greater_inst(.A(A), .B(B), .G(greater_output));
    comparator comparator_inst(.A(A), .B(B), .G(comparator_output));

    always @(*) begin
        if (comparator_output == 1) begin
            G = greater_output;
        end else begin
            G = B;
        end
    end

endmodule

module top_module (
    input [7:0] A,
    input [7:0] B,
    output reg [7:0] G
);

    final_module final_inst(.A(A), .B(B), .G(G));

endmodule

module cyclonev_hssi_refclk_divider 
  #(  
      parameter lpm_type                    = "cyclonev_hssi_refclk_divider",
      parameter divide_by                   =  1,
      parameter enabled                     = "false",
