module bcd_counter_with_sum (
    input clk,
    input reset,   // Synchronous active-high reset
    output [3:1] ena,
    output [15:0] q
);

    reg [3:0] count;
    reg [15:0] sum;

    always @(posedge clk) begin
        if (reset) begin
            count <= 4'b0000;
            sum <= 16'b0000000000000000;
        end
        else if (count == 4'b1001) begin
            count <= 4'b0000;
            sum <= sum + 4'b0001 + 4'b0001 + 4'b0001 + 4'b0001;
        end
        else begin
            count <= count + 1;
            sum <= sum + count;
        end
    end

    assign ena = {1'b0, count[3:1]};

    assign q = sum;

endmodule

module can_transmitter (
  input clk,
  input rst,
  input [7:0] data,
  input [10:0] id,
  input [3:0] dlc,
  output tx_en,
  output [7:0] tx_data,
  output [10:0] tx_id,
  output [3:0] tx_dlc
);

  // Define the CAN message format
  parameter SOF = 1'b0; // Start of Frame bit
  parameter RTR = 1'b0; // Remote Transmission Request bit
  parameter IDE = 1'b1; // Identifier Extension bit
  parameter SRR = 1'b1; // Substitute Remote Request bit
  parameter EOF = 7'b1111111; // End of Frame bits

  // Define the bit timing parameters
  parameter TQ = 8; // Time Quanta
  parameter BRP = 4; // Baud Rate Prescaler
  parameter SJW = 1; // Synchronization Jump Width
  parameter PROP = 2; // Propagation Segment
  parameter PHASE1 = 3; // Phase Segment 1
  parameter PHASE2 = 2; // Phase Segment 2

  // Define the internal signals
  reg [7:0] tx_data_reg;
  reg [10:0] tx_id_reg;
  reg [3:0] tx_dlc_reg;
  reg tx_en_reg;
  reg [15:0] bit_counter;
  reg [3:0] state;

  // Initialize the internal signals
  initial begin
    tx_data_reg <= 8'h00;
    tx_id_reg <= 11'h000;
    tx_dlc_reg <= 4'h0;
    tx_en_reg <= 1'b0;
    bit_counter <= 16'h0000;
    state <= 4'h0;
  end

  // Define the state machine
  always @(posedge clk) begin
    if (rst) begin
      tx_data_reg <= 8'h00;
      tx_id_reg <= 11'h000;
      tx_dlc_reg <= 4'h0;
      tx_en_reg <= 1'b0;
      bit_counter <= 16'h0000;
      state <= 4'h0;
    end
    else begin
      case (state)
        4'h0: begin // Idle state
          tx_en_reg <= 1'b0;
          if (id != 11'h000) begin
            tx_id_reg <= id;
            tx_dlc_reg <= dlc;
            tx_data_reg <= data;
            state <= 4'h1;
          end
        end
        4'h1: begin // Arbitration state
          tx_en_reg <= 1'b1;
          tx_id <= {SOF, RTR, IDE, SRR, tx_id_reg};
          tx_dlc <= tx_dlc_reg;
          tx_data <= tx_data_reg;
          bit_counter <= 16'h0001;
          state <= 4'h2;
        end
        4'h2: begin // Data state
          tx_en_reg <= 1'b1;
          tx_id <= {SOF, RTR, IDE, SRR, tx_id_reg};
          tx_dlc <= tx_dlc_reg;
          tx_data <= tx_data_reg;
          if (bit_counter == (TQ * (BRP + 1) * (PROP + PHASE1 + PHASE2))) begin
            bit_counter <= 16'h0001;
            state <= 4'h3;
          end
          else begin
            bit_counter <= bit_counter + 1;
          end
        end
        4'h3: begin // CRC state
          tx_en_reg <= 1'b1;
          tx_id <= {SOF, RTR, IDE, SRR, tx_id_reg};
          tx_dlc <= tx_dlc_reg;
          tx_data <= 8'h00;
          if (bit_counter == (TQ * (BRP + 1))) begin
            bit_counter <= 16'h0001;
            state <= 4'h4;
          end
          else begin
            bit_counter <= bit_counter + 1;
          end
        end
        4'h4: begin // ACK state
          tx_en_reg <= 1'b1;
          tx_id <= {SOF, RTR, IDE, SRR, tx_id_reg};
          tx_dlc <= tx_dlc_reg;
          tx_data <= 8'h00;
          if (bit_counter == (TQ * (BRP + 1))) begin
            bit_counter <= 16'h0001;
            state <= 4'h5;
          end
          else begin
            bit_counter <= bit_counter + 1;
          end
        end
        4'h5: begin // End of Frame state
          tx_en_reg <= 1'b1;
          tx_id <= {SOF, RTR, IDE, SRR, tx_id_reg};
          tx_dlc <= tx_dlc_reg;
          tx_data <= EOF;
          if (bit_counter == (TQ * (BRP + 1))) begin
            tx_en_reg <= 1'b0;
            state <= 4'h0;
          end
          else begin
            bit_counter <= bit_counter + 1;
          end
        end
      endcase
    end
  end

  // Assign the outputs
  assign tx_en = tx_en_reg;
  assign tx_data = tx_data_reg;
  assign tx_id = tx_id_reg;
  assign tx_dlc = tx_dlc_reg;

endmodule

module uartcon_top
  (
   input        rst_n,
   input        clk,
   input        refclk,

   output       txd,
   input        rxd,

   // Tx FIFO
   input        write,
   input [7:0]  wdata,
   output       full,
   output       almost_full,
   output       wempty,

   // Rx FIFO
   input        read,
   output [7:0] rdata,
   output       empty,
   output       almost_empty
   );

   wire         uart_clk;

   wire [7:0]   tx_data;
   wire         tx_empty, tx_almost_empty;
   wire         load;

   wire [7:0]   rx_data;
   wire         rx_full, rx_almost_full;
   wire         save;

   reg			tx_empty_reg;
   reg			tx_empty_d1, tx_empty_d2;

   always @(posedge clk or negedge rst_n) begin
	  if(!rst_n) begin
		 tx_empty_reg <= 1'b1;
		 tx_empty_d1 <= 1'b0;
		 tx_empty_d2 <= 1'b0;
	  end else begin
		 tx_empty_d1 <= tx_empty;
		 tx_empty_d2 <= tx_empty_d1;
		 if((tx_empty_d2 == 1'b0) && (tx_empty_d1 == 1'b1)) begin
			tx_empty_reg <= 1'b1;
		 end else if(write == 1'b1) begin
			tx_empty_reg <= 1'b0;
		 end
	  end
   end
   assign wempty = tx_empty_reg;

   uartcon_clk u_uartcon_clk
     (
      .rst_n      ( rst_n     ),
      .clk        ( refclk    ),
      .out_clk    ( uart_clk  )
      );

   // Tx FIFO
   uartcon_fifo
     #(
       .FIFO_DEPTH(7), // 64depth
       .FIFO_WIDTH(8)  // 8bit
       )
   u_tx_fifo
     (
      .RST_N              ( rst_n             ),
      .FIFO_WR_CLK        ( clk               ),
      .FIFO_WR_ENA        ( write             ),
      .FIFO_WR_LAST       ( 1'b1              ),
      .FIFO_WR_DATA       ( wdata[7:0]        ),
      .FIFO_WR_FULL       ( full              ),
      .FIFO_WR_ALM_FULL   ( almost_full       ),
      .FIFO_WR_ALM_COUNT  ( 7'd1              ),
      .FIFO_RD_CLK        ( uart_clk          ),
      .FIFO_RD_ENA        ( load              ),
      .FIFO_RD_DATA       ( tx_data[7:0]      ),
      .FIFO_RD_EMPTY      ( tx_empty          ),
      .FIFO_RD_ALM_EMPTY  ( tx_almost_empty   ),
      .FIFO_RD_ALM_COUNT  ( 7'd1              )
      );

   // Rx FIFO
   uartcon_fifo
     #(
       .FIFO_DEPTH(7), // 64depth
       .FIFO_WIDTH(8)  // 8bit
       )
   u_rx_fifo
     (
      .RST_N              ( rst_n             ),
      .FIFO_WR_CLK        ( uart_clk          ),
      .FIFO_WR_ENA        ( save              ),
      .FIFO_WR_LAST       ( 1'b1              ),
      .FIFO_WR_DATA       ( rx_data[7:0]      ),
      .FIFO_WR_FULL       ( rx_full           ),
      .FIFO_WR_ALM_FULL   ( rx_almost_full    ),
      .FIFO_WR_ALM_COUNT  ( 7'd1              ),
      .FIFO_RD_CLK        ( clk               ),
      .FIFO_RD_ENA        ( read              ),
      .FIFO_RD_DATA       ( rdata[7:0]        ),
      .FIFO_RD_EMPTY      ( empty             ),
      .FIFO_RD_ALM_EMPTY  ( almost_empty      ),
      .FIFO_RD_ALM_COUNT  ( 7'd1              )
      );

    // UART transmitter
    reg [7:0] tx_reg;
    reg tx_load;
    always @ (posedge uart_clk or negedge rst_n) begin
        if (!rst_n) begin
            tx_reg <= 8'h00;
            tx_load <= 1'b0;
        end else if (tx_load) begin
            tx_reg <= tx_data;
        end else if (tx_reg != 8'h00) begin
            tx_reg <= {1'b0, tx_reg[7:1]};
        end
    end
    assign txd = tx_reg[0];
    assign load = tx_load;
    always @ (posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            tx_load <= 1'b0;
        end else if (write && !full) begin
            tx_load <= 1'b1;
        end else if (tx_almost_empty) begin
            tx_load <= 1'b0;
        end
    end

    // UART receiver
    reg [7:0] rx_reg;
    always @ (posedge uart_clk or negedge rst_n) begin
        if (!rst_n) begin
            rx_reg <= 8'h00;
        end else if (rxd) begin
            rx_reg <= {rx_reg[6:0], rxd};
        end
    end
    always @ (posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            save <= 1'b0;
        end else if (read && !empty) begin
            save <= 1'b1;
        end else if (rx_almost_full) begin
            save <= 1'b0;
        end
    end
    assign rx_data = rx_reg;

endmodule

