module affine_block_ieee754_fp_adder_subtractor_0_1
   (x,
    y,
    ctrl,
    z);
  input [31:0]x;
  input [31:0]y;
  input ctrl;
  output [31:0]z;

  wire [31:0]x;
  wire [31:0]y;
  wire [31:0]z;

  affine_block_ieee754_fp_adder_subtractor_0_1_ieee754_fp_adder_subtractor U0
       (.x(x),
        .y(y),
        .ctrl(ctrl),
        .z(z));

  assign z = (ctrl == 1'b1) ? x - y : x + y;
endmodule

module affine_block_ieee754_fp_adder_subtractor_0_1_ieee754_fp_adder_subtractor
   (x,
    y,
    ctrl,
    z);
  input [31:0]x;
  input [31:0]y;
  input ctrl;
  output [31:0]z;

  wire [31:0]x_exp;
  wire [31:0]y_exp;
  wire [31:0]x_frac;
  wire [31:0]y_frac;
  wire [31:0]x_sign;
  wire [31:0]y_sign;
  wire [31:0]z_exp;
  wire [31:0]z_frac;
  wire [31:0]z_sign;
  wire [31:0]diff;
  wire [31:0]diff_sign;
  wire [31:0]diff_exp;
  wire [31:0]diff_frac;
  wire [31:0]x_larger;
  wire [31:0]y_larger;
  wire [31:0]larger_exp;
  wire [31:0]smaller_exp;
  wire [31:0]shift_amount;

  // Extracting the sign, exponent and fraction of x and y
  assign x_sign = x[31];
  assign y_sign = y[31];
  assign x_exp = x[30:23];
  assign y_exp = y[30:23];
  assign x_frac = x[22:0];
  assign y_frac = y[22:0];

  // Finding out which number has a larger exponent
  assign x_larger = (x_exp >= y_exp) ? 1'b1 : 1'b0;
  assign y_larger = (x_exp >= y_exp) ? 1'b0 : 1'b1;
  assign larger_exp = (x_larger == 1'b1) ? x_exp : y_exp;
  assign smaller_exp = (x_larger == 1'b1) ? y_exp : x_exp;

  // Finding out the shift amount required to align the fractions
  assign shift_amount = larger_exp - smaller_exp;

  // Shifting the smaller fraction to align with the larger fraction
  assign y_frac = (x_larger == 1'b1) ? {1'b0, y_frac} >> shift_amount : y_frac;

  // Adding or subtracting the fractions depending on the control signal
  assign diff = (ctrl == 1'b1) ? x_frac - y_frac : x_frac + y_frac;

  // Handling the case where the difference is negative
  assign diff_sign = (diff[31] == 1'b1) ? 1'b1 : 1'b0;
  assign diff_exp = larger_exp;
  assign diff_frac = (diff_sign == 1'b1) ? ~diff + 1 : diff;

  // Handling the case where the difference is zero
  assign z_exp = (diff == 32'h0) ? larger_exp : diff_exp;
  assign z_frac = (diff == 32'h0) ? 32'h0 : diff_frac;
  assign z_sign = (diff == 32'h0) ? 1'b0 : ((x_larger == 1'b1) ? x_sign : y_sign);

  // Combining the sign, exponent and fraction to get the final result
  assign z = {z_sign, z_exp, z_frac};
endmodule

module memory_arbiter(
    input clk,
    input rst,
    input [31:0] sram_din,
    input [31:0] mdin,
    input [31:0] wdin,
    input sram_re,
    input mwe,
    input mreq,
    input wwe,
    input wreq,
    input [SSRAM_HADR:0] sram_adr,
    input [SSRAM_HADR:0] madr,
    input [SSRAM_HADR:0] wadr,
    output reg [31:0] sram_dout,
    output reg sram_we,
    output reg mdout,
    output reg [31:0] wdout,
    output reg wack
);

parameter SSRAM_HADR = 14;

reg [SSRAM_HADR:0] sram_adr_reg;
reg [31:0] sram_dout_reg;
reg sram_we_reg;
reg mack_reg;
reg mcyc_reg;
reg wack_r_reg;

assign wsel = (wreq | wack) & !mreq;

always @(wsel or wdin or mdin)
    if (wsel) sram_dout_reg = wdin;
    else sram_dout_reg = mdin;

always @(wsel or wadr or madr)
    if (wsel) sram_adr_reg = wadr;
    else sram_adr_reg = madr;

always @(wsel or wwe or wreq or mwe or mcyc_reg)
    if (wsel) sram_we_reg = wreq & wwe;
    else sram_we_reg = mwe & mcyc_reg;

assign sram_dout = sram_dout_reg;
assign sram_adr = sram_adr_reg;
assign sram_we = sram_we_reg;
assign sram_re = 1'b1;

assign mdout = sram_din;
assign mack_reg = mreq;
assign mcyc_reg = mack_reg;

assign wdout = sram_din;
assign wack = wack_r_reg & !mreq;

always @(posedge clk or negedge rst)
    if (rst) wack_r_reg <= 1'b0;
    else wack_r_reg <= wreq & !mreq & !wack;

endmodule

