module FSM_SS (
  input clk,
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 4; // number of input signals
parameter m = 2; // number of output signals
parameter s = 3; // number of state bits before splitting
parameter s1 = 2; // number of state bits in the first split
parameter s2 = 1; // number of state bits in the second split

reg [s-1:0] state; // current state
reg [s1-1:0] state1; // first split of state
reg [s2-1:0] state2; // second split of state

// state transition logic
always @(posedge clk) begin
  case(state)
    0: if(in == 2'b00) state <= 1;
       else state <= 2;
    1: if(in == 2'b00) state <= 0;
       else state <= 3;
    2: if(in == 2'b00) state <= 3;
       else state <= 0;
    3: if(in == 2'b00) state <= 2;
       else state <= 1;
  endcase
end

// output generation logic
always @(state) begin
  case(state1)
    0: out = 2'b00;
    1: out = 2'b01;
    2: out = 2'b10;
    3: out = 2'b11;
  endcase
end

// state splitting logic
assign state1 = state[s-1:s2];
assign state2 = state[s2-1:0];

endmodule

module BusClient
#(
    parameter bus_width=32,
    parameter bus_max_devices=16,
    parameter bus_buffer_size=32,
    parameter device_id=1
)
(
    input clk,
    inout [bus_width-1:0] bus_data,
    inout [bus_max_devices-1:0] bus_receiver,
    inout [bus_max_devices-1:0] bus_write_request,
    inout [bus_max_devices-1:0] bus_buffer_full,
    input [bus_max_devices-1:0] bus_voice,
    output [bus_width-1:0] client_data_in,
    output [bus_max_devices-1:0] client_source_addr,
    input [bus_width-1:0] client_data_out,
    input [bus_max_devices-1:0] client_destination_addr,
    input client_read_next,
    input client_send_next,
    output client_input_buffer_empty,
    output client_input_buffer_full,
    output client_output_buffer_empty,
    output client_output_buffer_full
);

    // Input buffer
    reg [bus_width-1:0] input_buffer [0:bus_buffer_size-1];
    reg [bus_buffer_size-1:0] input_buffer_head = 0;
    reg [bus_buffer_size-1:0] input_buffer_tail = 0;
    reg input_buffer_full = 0;
    reg input_buffer_empty = 1;
    assign client_input_buffer_empty = input_buffer_empty;
    assign client_input_buffer_full = input_buffer_full;

    // Output buffer
    reg [bus_width-1:0] output_buffer [0:bus_buffer_size-1];
    reg [bus_buffer_size-1:0] output_buffer_head = 0;
    reg [bus_buffer_size-1:0] output_buffer_tail = 0;
    reg output_buffer_full = 0;
    reg output_buffer_empty = 1;
    assign client_output_buffer_empty = output_buffer_empty;
    assign client_output_buffer_full = output_buffer_full;

    // Bus writer
    BusWriter #(
        .bus_width(bus_width),
        .bus_max_devices(bus_max_devices),
        .bus_buffer_size(bus_buffer_size),
        .device_id(device_id)
    ) writer (
        .clk(clk),
        .bus_data(bus_data),
        .bus_receiver(bus_receiver),
        .bus_buffer_full(bus_buffer_full),
        .bus_write_request(bus_write_request),
        .bus_voice(bus_voice),
        .client_data_out(client_data_out),
        .client_destination_addr(client_destination_addr),
        .client_send_next(client_send_next),
        .client_output_buffer_empty(output_buffer_empty),
        .client_output_buffer_full(output_buffer_full)
    );

    // Bus reader
    BusReader #(
        .bus_width(bus_width),
        .bus_max_devices(bus_max_devices),
        .bus_buffer_size(bus_buffer_size),
        .device_id(device_id)
    ) reader (
        .clk(clk),
        .bus_data(bus_data),
        .bus_receiver(bus_receiver),
        .bus_buffer_full(bus_buffer_full),
        .bus_voice(bus_voice),
        .client_data_in(client_data_in),
        .client_source_addr(client_source_addr),
        .client_read_next(client_read_next),
        .client_input_buffer_empty(input_buffer_empty),
        .client_input_buffer_full(input_buffer_full)
    );

    // Input buffer logic
    always @ (posedge clk) begin
        if (client_send_next && !input_buffer_full) begin
            input_buffer[input_buffer_head] <= client_data_in;
            input_buffer_head <= (input_buffer_head == bus_buffer_size-1) ? 0 : input_buffer_head + 1;
            input_buffer_full <= (input_buffer_head == input_buffer_tail) ? 1 : 0;
            input_buffer_empty <= 0;
        end
    end

    // Output buffer logic
    always @ (posedge clk) begin
        if (client_read_next && !output_buffer_empty) begin
            output_buffer_tail <= (output_buffer_tail == bus_buffer_size-1) ? 0 : output_buffer_tail + 1;
            output_buffer_full <= 0;
            if (output_buffer_head == output_buffer_tail) begin
                output_buffer_empty <= 1;
            end
        end
    end

    // Bus voice logic
    always @ (posedge clk) begin
        if (bus_voice[device_id] && !output_buffer_empty) begin
            writer.client_data_out <= output_buffer[output_buffer_tail];
            writer.client_destination_addr <= bus_receiver;
            writer.client_send_next <= 1;
            output_buffer_empty <= (output_buffer_head == output_buffer_tail) ? 1 : 0;
            output_buffer_full <= 0;
            output_buffer_tail <= (output_buffer_tail == bus_buffer_size-1) ? 0 : output_buffer_tail + 1;
        end
    end

endmodule

module block_memory_generator (
  output reg [255:0] DOUTB,
  input tmp_ram_rd_en,
  input rd_clk,
  input [0:0] Q,
