        .IO_DIRECTION(8'hff)
    ) i_gpio_rx (
        .BUS_CLK(BUS_CLK),
        .BUS_RST(BUS_RST),
        .BUS_ADD(BUS_ADD),
        .BUS_DATA(BUS_DATA[7:0]),
        .BUS_RD(BUS_RD),
        .BUS_WR(BUS_WR),
        .IO(GPIO)
    );

    reg [31:0] datasource;
    reg fifo_write;
    assign FIFO_WRITE = fifo_write;
    reg [31:0] fifo_data_out;
    assign FIFO_DATA = fifo_data_out;

    always @ (posedge BUS_CLK) begin
        if (RESET_N == 1'b0) begin
            datasource <= 0;
            fifo_write <= 1'b0;
            fifo_data_out <= 0;
        end else begin
            if (FIFO_NEXT) begin
                if (!fifo_full) begin
                    fifo_data_out <= datasource;
                    datasource <= datasource + 1;
                    fifo_write <= 1'b1;
                end else begin
                    fifo_write <= 1'b0;
                end
            end else begin
                fifo_write <= 1'b0;
                datasource <= 0;
            end
        end
    end

endmodule

module axi_slave
  (
   // Reset, Clock
   input            ARESETN,
   input            ACLK,

   // Master Write Address
   input [31:0]     M_AXI_AWADDR,
   input [3:0]      M_AXI_AWCACHE,
   input [2:0]      M_AXI_AWPROT,
   input            M_AXI_AWVALID,
   output reg       M_AXI_AWREADY,

   // Master Write Data
   input [31:0]     M_AXI_WDATA,
   input [3:0]      M_AXI_WSTRB,
   input            M_AXI_WVALID,
   output reg       M_AXI_WREADY,

   // Master Write Response
   output reg [1:0] M_AXI_BRESP,
   output           M_AXI_BVALID,
   input            M_AXI_BREADY,

   // Master Read Address
   input [31:0]     M_AXI_ARADDR,
   input [3:0]      M_AXI_ARCACHE,
   input [2:0]      M_AXI_ARPROT,
   input            M_AXI_ARVALID,
   output reg       M_AXI_ARREADY,

   // Master Read Data
   output [31:0]    M_AXI_RDATA,
   output reg [1:0] M_AXI_RRESP,
   output           M_AXI_RVALID,
   input            M_AXI_RREADY
   );

   reg [31:0] mem[1023:0];
   integer i;

   initial begin
      for (i = 0; i < 1024; i = i + 1) begin
         mem[i] = 0;
      end
      M_AXI_AWREADY  = 1;
      M_AXI_WREADY   = 1;
      M_AXI_BRESP    = 0;
      M_AXI_RRESP    = 0;
      M_AXI_ARREADY  = 1;
   end

   // AXI Write
   reg axi_wena;
   always @(posedge ACLK or negedge ARESETN) begin
      if(!ARESETN) begin
         axi_wena <= 0;
      end else begin
         if(M_AXI_BVALID & M_AXI_BREADY) begin
            axi_wena <= 0;
         end else if(M_AXI_AWVALID & M_AXI_WVALID) begin
            axi_wena <= 1;
         end
      end
   end

   always @(posedge ACLK or negedge ARESETN) begin
      if(!ARESETN) begin
         M_AXI_BVALID <= 0;
         M_AXI_WREADY <= 1;
         M_AXI_AWREADY <= 1;
      end else begin
         if (M_AXI_AWVALID) begin
            M_AXI_AWREADY <= 1;
         end else begin
            M_AXI_AWREADY <= axi_wena;
         end
         if (M_AXI_WVALID) begin
            M_AXI_WREADY <= 1;
         end else begin
            M_AXI_WREADY <= axi_wena;
         end
         if (axi_wena) begin
            mem[M_AXI_AWADDR[9:2]] <= M_AXI_WDATA;
            M_AXI_BVALID <= 1;
            M_AXI_BRESP <= 0;
         end
      end
   end

   // AXI Read
   reg axi_rena;
   always @(posedge ACLK or negedge ARESETN) begin
      if(!ARESETN) begin
         axi_rena <= 0;
      end else begin
         if(M_AXI_RVALID & M_AXI_RREADY) begin
            axi_rena <= 0;
         end else if(M_AXI_ARVALID) begin
            axi_rena <= 1;
         end
      end
   end

   always @(posedge ACLK or negedge ARESETN) begin
      if(!ARESETN) begin
         M_AXI_RVALID <= 0;
      end else begin
         if (M_AXI_ARVALID) begin
            M_AXI_ARREADY <= 1;
         end else begin
            M_AXI_ARREADY <= axi_rena;
         end
         if (axi_rena) begin
            M_AXI_RDATA <= mem[M_AXI_ARADDR[9:2]];
            M_AXI_RVALID <= 1;
            M_AXI_RRESP <= 0;
         end
      end
   end

endmodule

module hysteresis_comparator (
  input vin,
  input vref,
  input reset,
  output vout
);

parameter hysteresis = 0.1;

reg vout_reg;
reg vout_reset;

always @ (vin, vref, reset) begin
  if (reset) begin
    vout_reg <= 0;
    vout_reset <= 1;
  end else if (vin > vref + hysteresis) begin
    vout_reg <= 1;
    vout_reset <= 0;
  end else if (vin < vref - hysteresis) begin
    vout_reg <= 0;
    vout_reset <= 0;
  end else begin
    vout_reset <= 0;
  end
end

assign vout = vout_reset ? 0 : vout_reg;

endmodule

