module fifo_64w_32r_512d(
  input rst,
  input wr_clk,
  input rd_clk,
  input [63 : 0] din,
  input wr_en,
  input rd_en,
  output reg [31 : 0] dout,
  output reg full,
  output reg empty,
  output reg [9 : 0] rd_data_count,
  output reg [8 : 0] wr_data_count
);

reg [63:0] mem [511:0];
reg [8:0] wr_ptr;
reg [9:0] rd_ptr;
reg [9:0] rd_data_count_reg;
reg [8:0] wr_data_count_reg;

// Reset logic
always @(posedge wr_clk, posedge rd_clk) begin
    if (rst) begin
        wr_ptr <= 0;
        rd_ptr <= 0;
        rd_data_count_reg <= 0;
        wr_data_count_reg <= 0;
        full <= 0;
        empty <= 1;
    end
end

// Write logic
always @(posedge wr_clk) begin
    if (wr_en && !full) begin
        mem[wr_ptr] <= din;
        wr_ptr <= (wr_ptr == 511) ? 0 : wr_ptr + 1;
        wr_data_count_reg <= wr_data_count_reg + 1;
        if (wr_data_count_reg == 256) full <= 1;
        empty <= 0;
    end
end

// Read logic
always @(posedge rd_clk) begin
    if (rd_en && !empty) begin
        dout <= mem[rd_ptr][31:0];
        rd_ptr <= (rd_ptr == 511) ? 0 : rd_ptr + 1;
        rd_data_count_reg <= rd_data_count_reg - 1;
        if (rd_data_count_reg == 1) empty <= 1;
        full <= 0;
    end
end

assign rd_data_count = rd_data_count_reg;
assign wr_data_count = wr_data_count_reg;

endmodule

module PLL (
  input clk_in,
  input reset,
  output reg clk_out
);

parameter N = 10; // multiplication factor
parameter M = 4; // division factor
parameter Fout = 10_000_000; // desired output frequency

reg [31:0] error;
reg [31:0] control_voltage;

phase_detector pd (
  .clk_ref(clk_in),
  .clk_out(clk_out),
  .error(error)
);

low_pass_filter lp (
  .error(error),
  .control_voltage(control_voltage)
);

vco v (
  .control_voltage(control_voltage),
  .clk_out(clk_out)
);

always @(posedge clk_in, posedge reset) begin
  if (reset) begin
    clk_out <= 1'b0;
  end else begin
    clk_out <= #1 clk_out + 1'b1;
  end
end

endmodule

module phase_detector (
  input clk_ref,
  input clk_out,
  output reg [31:0] error
);

always @(posedge clk_ref, posedge clk_out) begin
  error <= #1 (clk_out - clk_ref) * 32'b11111111111111111111111111111111 / Fout;
end

endmodule

module low_pass_filter (
  input [31:0] error,
  output reg [31:0] control_voltage
);

parameter Kp = 1;
parameter Ki = 1;

reg [31:0] integral;

always @(posedge error) begin
  integral <= #1 integral + error;
end

always @(posedge error) begin
  control_voltage <= #1 Kp * error + Ki * integral;
end

endmodule

module vco (
  input [31:0] control_voltage,
  output reg clk_out
);

parameter K = 100;

always @(posedge control_voltage) begin
  clk_out <= #1 control_voltage * K;
end

endmodule

module freq_syn (
  input clk_ref,
  input [n-1:0] ctrl,
  output reg clk_syn
);

parameter n = 8; // number of bits in the digital control signal
parameter f_ref = 10e6; // frequency of the reference clock signal (in Hz)
parameter f_min = 1e6; // minimum output frequency of the synthesizer (in Hz)
parameter f_max = 100e6; // maximum output frequency of the synthesizer (in Hz)

reg [n-1:0] ctrl_reg; // register for storing the digital control signal
reg [31:0] phase_accum; // register for storing the phase accumulator value
reg [31:0] phase_inc; // register for storing the phase increment value
reg [31:0] phase_err; // register for storing the phase error value
reg [31:0] phase_err_int; // register for storing the integrated phase error value
reg [31:0] vco_ctrl; // register for storing the VCO control voltage value
reg [31:0] vco_freq; // register for storing the VCO frequency value

wire [31:0] phase_ref; // wire for storing the reference phase value
wire [31:0] phase_syn; // wire for storing the synthesized phase value
wire [31:0] phase_diff; // wire for storing the phase difference value
wire [31:0] phase_err_filt; // wire for storing the filtered phase error value
wire [31:0] phase_err_integ; // wire for storing the integrated phase error value
wire [31:0] vco_ctrl_filt; // wire for storing the filtered VCO control voltage value
wire [31:0] vco_freq_div; // wire for storing the divided VCO frequency value

// generate the reference phase value
assign phase_ref = (f_ref * 2**32) / (2 * f_max);

// generate the phase increment value
always @(*) begin
  phase_inc = (ctrl_reg * (2**32 - phase_ref)) / (2**n);
end

// generate the synthesized phase value
always @(posedge clk_ref) begin
  phase_accum <= phase_accum + phase_inc;
  phase_syn <= phase_accum + phase_err_int;
end

// generate the phase difference value
assign phase_diff = phase_ref - phase_syn;

// generate the filtered phase error value
pll_loop_filter pll_filt (
  .clk(clk_ref),
  .reset(1'b0),
  .in(phase_diff),
  .out(phase_err_filt)
);

// generate the integrated phase error value
always @(posedge clk_ref) begin
  if (phase_err_int >= 0) begin
    phase_err_int <= phase_err_int + phase_err_filt;
  end else begin
    phase_err_int <= phase_err_int - phase_err_filt;
  end
end

// generate the filtered VCO control voltage value
pll_vco_ctrl pll_vco (
  .clk(clk_ref),
  .reset(1'b0),
  .in(phase_err_int),
  .out(vco_ctrl_filt)
);

// generate the divided VCO frequency value
assign vco_freq_div = vco_freq / (2**16);

// generate the synthesized clock signal
always @(posedge clk_ref) begin
  vco_freq <= vco_ctrl_filt;
  clk_syn <= ~clk_syn;
end

// register the digital control signal
always @(posedge clk_ref) begin
  ctrl_reg <= ctrl;
end

endmodule

module DriveTFT18(
  input wire clk,
  input wire rsth,
  output wire SCL,
  output wire WRX,
  output wire RESX,
  output wire CSX,
  inout  wire SDA,
  output wire UART_TX,
  output wire [6:0] LED
);

  // Define state machine states
  localparam IDLE = 2'b00;
  localparam SEND_COMMAND = 2'b01;
  localparam SEND_DATA = 2'b10;

  // Define state machine inputs
  wire [7:0] spi_data;
  wire spi_request;
  wire spi_acknowledge;
  wire wait_acknowledge;

  // Define state machine outputs
  reg spi_enable;
  reg [1:0] state;
  reg [7:0] spi_command;
  reg [7:0] spi_data_out;
  reg [7:0] spi_data_in;
  reg [7:0] uart_data_out;
  reg [7:0] uart_data_in;

  // Define register for reset signal
  reg r_rstn;

  // Define register for UART transmission
  reg [7:0] uart_tx_data;
  reg [3:0] uart_tx_count;
  reg uart_tx_enable;

  // Define register for LED output
  reg [6:0] led_output;

  // Define SPI module
  spi spi (
    .clk(clk),
    .rsth(rsth),
    .mosi(SDA),
    .miso(SDA),
    .sclk(SCL),
    .cs(CSX),
    .data_out(spi_data_out),
    .data_in(spi_data_in),
    .request(spi_request),
    .acknowledge(spi_acknowledge)
  );

  // Define UART module
  uart uart (
    .clk(clk),
    .rsth(rsth),
    .tx(UART_TX),
    .rx(),
    .data_out(uart_data_out),
    .data_in(uart_data_in)
  );

  // Define state machine
  always @(posedge clk) begin
    if (rsth) begin
      state <= IDLE;
      spi_enable <= 0;
      spi_command <= 0;
      spi_data_out <= 0;
      spi_data_in <= 0;
      uart_tx_data <= 0;
      uart_tx_count <= 0;
      uart_tx_enable <= 0;
      led_output <= 0;
      r_rstn <= 0;
    end else begin
      case (state)
        IDLE: begin
          if (spi_enable) begin
            state <= SEND_COMMAND;
            spi_data_out <= spi_command;
            led_output[2] <= 1;
          end else if (uart_tx_enable) begin
            state <= SEND_DATA;
            uart_tx_count <= 0;
            uart_tx_data <= uart_data_out;
            led_output[2] <= 0;
          end else if (wait_acknowledge) begin
            led_output[0] <= 1;
          end else begin
            led_output[2] <= 0;
            led_output[0] <= 0;
          end
        end
        SEND_COMMAND: begin
          if (spi_acknowledge) begin
            state <= SEND_DATA;
            spi_data_out <= spi_data_out[7:0];
            led_output[1] <= 1;
          end else begin
            led_output[1] <= 0;
          end
        end
        SEND_DATA: begin
          if (spi_acknowledge) begin
            if (uart_tx_enable) begin
              uart_tx_count <= uart_tx_count + 1;
              if (uart_tx_count == 3) begin
                state <= IDLE;
                uart_tx_enable <= 0;
                led_output[2] <= 0;
              end else begin
                uart_tx_data <= uart_data_out >> (8 * uart_tx_count);
              end
            end else begin
              state <= IDLE;
              spi_enable <= 0;
              led_output[2] <= 0;
            end
            led_output[1] <= 1;
          end else begin
            led_output[1] <= 0;
          end
        end
      endcase
    end
  end

  // Drive TFT display reset signal
  always @(posedge clk) begin
    if (rsth) begin
      r_rstn <= 0;
    end else begin
      if (spi_enable && spi_command[7:4] == 4'b0011) begin
        r_rstn <= spi_data_out[0];
      end
    end
  end

  // Drive SPI enable signal
  always @(posedge clk) begin
    if (rsth) begin
      spi_enable <= 0;
    end else begin
      if (spi_request) begin
        spi_enable <= 1;
        spi_command <= spi_data[7:0];
        led_output[2] <= 1;
      end
    end
  end

  // Drive UART transmission
  always @(posedge clk) begin
    if (rsth) begin
      uart_tx_enable <= 0;
    end else begin
      if (uart_data_out != 0) begin
        uart_tx_enable <= 1;
      end
    end
  end

  // Drive LED output
  always @(posedge clk) begin
    led_output[6] <= SCL;
    led_output[5] <= WRX;
    led_output[4] <= CSX;
    led_output[3] <= SDA;
    LED <= led_output;
  end

  // Drive module outputs
  assign RESX = r_rstn;

endmodule

module sigma_delta (
  input in,
  output out
);

parameter OSR = 16; // oversampling ratio
parameter N = 2; // order of the digital filter

// Define the transfer function of the low-pass filter for the modulator
function [1:0] H_modulator;
  input [31:0] z;
  reg [1:0] H;
  begin
    case (z)
      2'b00: H = 2'b01;
      2'b01: H = 2'b10;
      2'b10: H = 2'b01;
      2'b11: H = 2'b00;
    endcase
    H_modulator = H;
  end
endfunction

// Define the transfer function of the low-pass filter for the demodulator
function [3:0] H_demodulator;
  input [31:0] z;
  reg [3:0] H;
  begin
    case (z)
      4'b0000: H = 4'b0001;
      4'b0001: H = 4'b0010;
      4'b0010: H = 4'b0100;
      4'b0011: H = 4'b1000;
      4'b0100: H = 4'b0100;
      4'b0101: H = 4'b0010;
      4'b0110: H = 4'b0001;
      4'b0111: H = 4'b0000;
      4'b1000: H = 4'b0000;
      4'b1001: H = 4'b0001;
      4'b1010: H = 4'b0010;
      4'b1011: H = 4'b0100;
      4'b1100: H = 4'b1000;
      4'b1101: H = 4'b0100;
      4'b1110: H = 4'b0010;
      4'b1111: H = 4'b0001;
    endcase
    H_demodulator = H;
  end
endfunction

// Define the sigma-delta modulator
reg [31:0] integrator;
reg [31:0] quantizer;
reg [1:0] feedback;
reg [1:0] filter_output;
reg [31:0] z_modulator;
always @(posedge clk) begin
  z_modulator <= {in, feedback};
  integrator <= integrator + (z_modulator - quantizer);
  filter_output <= H_modulator(integrator >> (OSR - 1));
  quantizer <= {1'b0, filter_output[1]};
  feedback <= filter_output;
end
assign out = quantizer[1];

// Define the sigma-delta demodulator
reg [31:0] integrator_demodulator;
reg [31:0] quantizer_demodulator;
reg [3:0] filter_output_demodulator;
reg [31:0] z_demodulator;
always @(posedge clk) begin
  z_demodulator <= quantizer_demodulator;
  integrator_demodulator <= integrator_demodulator + (z_demodulator - (1 << (N - 1)));
  filter_output_demodulator <= H_demodulator(integrator_demodulator >> (OSR - 1));
  quantizer_demodulator <= filter_output_demodulator[N];
end

endmodule

module SoundCtrlChannel3 # (
  parameter CLK_FREQUENCY = 4194304
) (
  input iClock,
  input iReset,
  input iOsc256,
  input iOsc262k,
  input [7:0] iNR30,
  input [7:0] iNR31,
  input [7:0] iNR32,
  input [7:0] iNR33,
  input [7:0] iNR34,
  output reg [4:0] oOut
);

  reg [7:0] counter;
  reg [7:0] length_counter;
  reg [7:0] volume;
  reg [7:0] waveform;
  reg [7:0] frequency;
  reg [7:0] timer;
  reg [7:0] mode;
  reg [7:0] duty_cycle;
  reg [7:0] waveform_counter;

  always @(posedge iClock) begin
    if (iReset) begin
      counter <= 8'h00;
      length_counter <= 8'h00;
      volume <= 8'h00;
      waveform <= 8'h00;
      frequency <= 8'h00;
      timer <= 8'h00;
      mode <= 8'h00;
      duty_cycle <= 8'h00;
      waveform_counter <= 8'h00;
      oOut <= 5'b00000;
    end else begin
      // update counter
      if (counter == 8'hFF) begin
        counter <= 8'h00;
      end else begin
        counter <= counter + 1;
      end

      // update length counter
      if (iNR31 != 8'h00) begin
        if (length_counter == 8'h00) begin
          oOut <= 5'b00000;
        end else begin
          length_counter <= length_counter - 1;
        end
      end

      // update volume
      volume <= iNR30[6:5];

      // update waveform
      waveform <= iNR32[1:0];

      // update frequency
      frequency <= iNR33;

      // update timer
      if (iNR34[6] == 1'b1) begin
        timer <= iNR34[2:0];
      end

      // update mode
      mode <= iNR34[7:6];

      // update duty cycle
      duty_cycle <= iNR32[2];

      // update waveform counter
      if (waveform_counter == 8'hFF) begin
        waveform_counter <= 8'h00;
      end else begin
        waveform_counter <= waveform_counter + 1;
      end
    end
  end

  always @(posedge iOsc256) begin
    if (iReset) begin
      length_counter <= iNR31;
    end else begin
      // update length counter
      if (iNR31 != 8'h00) begin
        if (length_counter == 8'h00) begin
          oOut <= 5'b00000;
        end else begin
          length_counter <= length_counter - 1;
        end
      end
    end
  end

  always @(posedge iOsc262k) begin
    if (iReset) begin
      counter <= 8'h00;
      length_counter <= iNR31;
      timer <= iNR34[2:0];
      mode <= iNR34[7:6];
      waveform_counter <= 8'h00;
    end else begin
      // update timer
      if (iNR34[6] == 1'b0) begin
        timer <= timer - 1;
        if (timer == 8'h00) begin
          if (mode == 2'b00) begin
            length_counter <= length_counter - 1;
          end
          timer <= iNR34[2:0];
        end
      end

      // update waveform counter
      if (waveform_counter == 8'hFF) begin
        waveform_counter <= 8'h00;
      end else begin
        waveform_counter <= waveform_counter + 1;
      end

      // generate sound output
      if (iNR31 != 8'h00 && length_counter != 8'h00) begin
        case (waveform)
          2'b00: begin // square wave
            if (duty_cycle == 8'h00) begin
              if (waveform_counter < (256/frequency*0.25)) begin
                oOut <= volume;
              end else begin
                oOut <= 5'b00000;
              end
            end else begin
              if (waveform_counter < (256/frequency*0.75)) begin
                oOut <= volume;
              end else begin
                oOut <= 5'b00000;
              end
            end
          end
          2'b01: begin // 50% duty cycle wave
            if (waveform_counter < (256/frequency*0.5)) begin
              oOut <= volume;
            end else begin
              oOut <= 5'b00000;
            end
          end
        endcase
      end
    end
  end

endmodule

module PhotonBlock5(
	//Inputs
	clock,
	reset,
	enable,

	i_x,
	i_y,
	i_z,
	i_ux,
	i_uy,
	i_uz,
	i_sz,
	i_sr,
	i_sleftz,
	i_sleftr,
	i_weight,
	i_layer,
	i_dead,
	i_hit,
	//Outputs
	o_x,
	o_y,
	o_z,
	o_ux,
	o_uy,
	o_uz,
	o_sz,
	o_sr,
	o_sleftz,
	o_sleftr,
	o_weight,
	o_layer,
	o_dead,
	o_hit
	);

parameter BIT_WIDTH=32;
parameter LAYER_WIDTH=3;

input				clock;
