module Modulo (
  input signed [31:0] a,
  input signed [31:0] b,
  output signed [31:0] result
);
  wire signed [31:0] temp_result;

  assign temp_result = (b == 0) ? 0 : a % b;

  always @(*) begin
    if (a < 0 && b > 0) begin
      result = -temp_result;
    end else if (a > 0 && b < 0) begin
      result = -temp_result;
    end else begin
      result = temp_result;
    end
  end

endmodule

module ripple_carry_adder(
    input [31:0] A,
    input [31:0] B,
    output [31:0] C
);

    wire [31:0] sum;
    wire [31:0] carry;

    assign sum[0] = A[0] ^ B[0];
    assign carry[0] = A[0] & B[0];

    generate
        genvar i;
        for (i = 1; i < 32; i = i + 1) begin : loop
            assign sum[i] = A[i] ^ B[i] ^ carry[i-1];
            assign carry[i] = (A[i] & B[i]) | (A[i] & carry[i-1]) | (B[i] & carry[i-1]);
        end
    endgenerate

    assign C = sum;

endmodule

