    input clk,
    input areset,
    input [7:0] I,
    input up_down,
    input count_enable,
    input load,
    output [7:0] final_output
);

    // Priority Encoder
    wire [2:0] priority;
    wire EN;
    wire [1:0] OUT;
    priority_encoder_8to3 pe (
        .I(I),
        .priority(priority),
        .EN(EN),
        .OUT(OUT)
    );

    // Up/Down Counter
    reg [3:0] count;
    always @(posedge clk or negedge areset) begin
        if (!areset) begin
            count <= 4'b0;
        end else if (load) begin
            count <= I;
        end else if (count_enable) begin
            if (up_down) begin
                count <= count + 1;
            end else begin
                count <= count - 1;
            end
        end
    end

    // Final Output Module
    reg [7:0] final;
    always @(posedge clk or negedge areset) begin
        if (!areset) begin
            final <= 8'b0;
        end else begin
            final <= (OUT[1:0] + count) % 256;
        end
    end

    assign final_output = final;

endmodule

