module rotator (
    input clk,
    input reset,      // Synchronous active-high reset
    input load,
    input [1:0] ena,
    input [99:0] data_in,
    output reg [99:0] q
);

reg [99:0] shift_reg;
reg [6:0] shift_amt;

always @ (posedge clk) begin
    if (reset) begin
        shift_reg <= 0;
        shift_amt <= 0;
    end else begin
        if (load) begin
            shift_reg <= data_in;
            shift_amt <= 0;
        end else begin
            case (ena)
                2'b00: shift_amt <= shift_amt - 1;
                2'b01: shift_amt <= shift_amt + 1;
                2'b10: shift_amt <= shift_amt;
                2'b11: shift_amt <= ~shift_amt + 1;
            endcase
            shift_reg <= {shift_reg[shift_amt:99], shift_reg[0:shift_amt-1]};
        end
    end
end

assign q = shift_reg;

endmodule

