adder adder1(a_inv, b_inv, 1'b1, s_inv, c1);

// Select the correct sum output based on the carry output
mux2to1 mux(c1, s_inv, s0, s);

// Detect overflow
overflow_detection overflow_detection(s, a, b, overflow);

endmodule

module adder (
