genvar i;
generate
    for (i = 0; i < 8; i = i + 1) begin : gen_adder
        full_adder fa(a[i], b[i], cin, sum[i], carry[i]);
    end
endgenerate

// Combine sum and carry outputs
assign s = sum;
assign cout = carry[7];

endmodule

module full_adder (
    input a,
    input b,
    input cin,
    output sum,
    output cout
);

assign sum = a ^ b ^ cin;
assign cout = (a & b) | (a & cin) | (b & cin);

endmodule

module mux2to1 (
    input sel,
    input [7:0] in1,
    input [7:0] in2,
    output [7:0] out
);

assign out = sel ? in2 : in1;

endmodule

module overflow_detection (
    input [7:0] s,
    input [7:0] a,
    input [7:0] b,
    output overflow
);

wire [7:0] s_inv;
wire [7:0] a_sign;
wire [7:0] b_sign;
wire [7:0] s_sign;

// Invert s
assign s_inv = ~s + 1;

// Determine sign of a, b, and s
assign a_sign = a[7];
assign b_sign = b[7];
assign s_sign = s[7];

// Overflow occurs if a and b have the same sign, but s has a different sign
assign overflow = (a_sign == b_sign) && (a_sign != s_sign);

endmodule

