    input b,
    output sum,
    output cout
);

reg s1, c1, s2, c2;

assign sum = s2;
assign cout = c2;

// Stage 1
assign s1 = a ^ b;
assign c1 = a & b;

// Stage 2
assign s2 = s1 ^ c1;
assign c2 = c1;

endmodule

