endmodule

module clk_gen_ipll
  (
   input            hb_clk,
   input            hb_resetn,
   input            refclk,
   input [1:0]      bpp,
   input            vga_mode,
   input	    write_param, 	// input
   input [3:0]	    counter_type, 	// input [3:0]
   input [2:0]	    counter_param,	// input[2:0]
   input [8:0]	    data_in,		// input [8:0],
   input 	    reconfig,		// input.
   input 	    pll_areset_in,	// input.

   output	    busy,		// Input busy.
   output           pix_clk,
   output           pix_clk_vga,
   output reg       crt_clk,
   output           pix_locked
   );

// Phase-locked loop (PLL) for generating the pixel clock
pix_pll_rc_top u_pix_pll_rc_top
	(
	.hb_clk			(hb_clk),
	.hb_rstn		(hb_resetn),
	.ref_clk		(refclk),
	.reconfig		(reconfig),
	.write_param		(write_param),
	.counter_param		(counter_param),// Input [2:0]
	.counter_type		(counter_type),	// Input [3:0]
	.data_in		(data_in),	// Input [8:0]
	.pll_areset_in		(pll_areset_in),

	.busy			(busy),		// output.
	.pix_clk		(pix_clk),	// output.
	.pix_locked		(pix_locked)	// output.
	);

// Counter for generating the CRT clock
reg [2:0] 	    crt_counter;
reg [1:0]         crt_divider;

always @*
	begin
		// Configure the counter based on VGA mode and bits per pixel
   		casex({vga_mode, bpp})
   		3'b1_xx: crt_divider = 2'b00;
   		3'b0_01: crt_divider = 2'b10;
   		3'b0_10: crt_divider = 2'b01;
   		default: crt_divider = 2'b00;
	endcase
end

always @(posedge pix_clk or negedge hb_resetn)
	begin
		if(!hb_resetn)
			begin
      				crt_clk <= 1'b1;
    				crt_counter <= 3'b000;
			end
		else begin
    				crt_counter <= crt_counter + 3'h1;
    				case (crt_divider)
      				0: crt_clk <= 1'b1;
      				1: crt_clk <= ~crt_counter[0];
      				2: crt_clk <= ~|crt_counter[1:0];
      				3: crt_clk <= ~|crt_counter[2:0];
    				endcase
		end
  	end

endmodule

module carry_select_adder (
    input [31:0] a,
    input [31:0] b,
    output [31:0] sum,
    output [31:0] carry_out
);

wire [31:0] p, g, c;

genvar i;
generate
    for (i = 0; i < 32; i = i+1) begin : carry_select_adder_loop
        assign p[i] = a[i] ^ b[i];
        assign g[i] = a[i] & b[i];
        assign c[i] = i == 0 ? 1'b0 : g[i-1] | (p[i-1] & c[i-1]);
    end
endgenerate

assign sum = a + b + c;
assign carry_out = c[31];

endmodule

