module adder(
    input [7:0] A,
    input [7:0] B,
    output reg [15:0] result
);

wire [7:0] sum1;
wire carry;

// First full-adder implementation
assign sum1 = A ^ B;
assign carry = A & B;

// Second full-adder implementation
always @(*) begin
    if (carry == 1'b0) begin
        result = {1'b0, sum1};
    end else begin
        result = {1'b1, sum1 + 1'b1};
    end
end

endmodule

module fifo
#(
    parameter WIDTH = 8,
    parameter DEPTH = 4,
    parameter ADDR_W = 2
)
(
    input clk_i,
    input rst_i,
    input [WIDTH-1:0] data_in_i,
    input push_i,
    input pop_i,
    output [WIDTH-1:0] data_out_o,
    output accept_o,
    output valid_o
);

localparam COUNT_W = ADDR_W + 1;

reg [WIDTH-1:0] ram_q[DEPTH-1:0];
reg [ADDR_W-1:0] rd_ptr_q;
reg [ADDR_W-1:0] wr_ptr_q;
reg [COUNT_W-1:0] count_q;

integer i;

always @ (posedge clk_i or posedge rst_i)
begin
    if (rst_i)
    begin
        count_q   <= {(COUNT_W) {1'b0}};
        rd_ptr_q  <= {(ADDR_W) {1'b0}};
        wr_ptr_q  <= {(ADDR_W) {1'b0}};
        for (i=0;i<DEPTH;i=i+1)
        begin
            ram_q[i] <= {(WIDTH) {1'b0}};
        end
    end
    else
    begin
        // Push
        if (push_i & accept_o)
        begin
            ram_q[wr_ptr_q] <= data_in_i;
            wr_ptr_q        <= wr_ptr_q + 1;
        end

        // Pop
        if (pop_i & valid_o)
        begin
            rd_ptr_q <= rd_ptr_q + 1;
        end

        // Count up
        if ((push_i & accept_o) & ~(pop_i & valid_o))
        begin
            count_q <= count_q + 1;
        end
        // Count down
        else if (~(push_i & accept_o) & (pop_i & valid_o))
        begin
            count_q <= count_q - 1;
        end
    end
end

assign valid_o = (count_q != 0);
assign accept_o = (count_q != DEPTH);
assign data_out_o = ram_q[rd_ptr_q];

endmodule

module vending_machine(
    input clk,
    input reset,
    input [1:0] coin,
    input [1:0] dispense,
    output reg dispenser1,
    output reg dispenser2,
    output reg dispenser3,
    output reg dispenser4,
    output reg [1:0] change
);

parameter product_price = 2'b10; // 50 cents
parameter coin_value = {2'b00, 2'b01, 2'b10, 2'b11}; // 5 cents, 10 cents, 25 cents, 1 dollar

reg [1:0] amount_inserted; // total amount of money inserted so far

always @(posedge clk) begin
    if (reset) begin
        amount_inserted <= 0;
        dispenser1 <= 0;
        dispenser2 <= 0;
        dispenser3 <= 0;
        dispenser4 <= 0;
        change <= 2'b00;
    end else begin
        amount_inserted <= amount_inserted + coin_value[coin];
        if (amount_inserted >= product_price) begin
            case (dispense)
                2'b00: dispenser1 <= 1;
                2'b01: dispenser2 <= 1;
                2'b10: dispenser3 <= 1;
                2'b11: dispenser4 <= 1;
            endcase
            change <= amount_inserted - product_price;
            amount_inserted <= 0;
        end else if (amount_inserted > 0) begin
            change <= amount_inserted;
            amount_inserted <= 0;
        end
    end
end

endmodule

