module a(clock,
		a_in,
		out);

input	clock;
input [`BITS-1:0] a_in;
output [`BITS-1:0] out;
reg [`BITS-1:0] out;
reg [`BITS-1:0] out1;
reg [`BITS-1:0] out2;

always @(posedge clock)
begin
	case (a_in)
		2'b00: begin
			out2 <= 2'b11 ;
			out1 <= 2'b11 ;
		end
		2'b01: begin
			out2 <= out1 ;
			out1[0] <= 1 ;
		end
		2'b10: begin
			out2 <= out1 ;
			out1[0] <= 0 ;
		end
		2'b11: begin
			out2 <= out1 ;
			out1 <= 2'b00 ;
		end
	endcase
	out <= out1 & out2;
end

endmodule

