module top_module(
    input wire [3:0] vec,
    input [3:0] a,
    input [3:0] b,
    output wire outp,
    output [7:0] prod
);

    wire [1:0] priority;
    priority_encoder pe(.vec(vec), .outp(priority));
    multiplier mul(.a({priority, vec}), .b({a, b}), .prod(prod));
    assign outp = priority[1];

