// Barrel shifter module
module barrel_shifter (
    input [3:0] in,
    input DIR,
    input [1:0] amt,
    output [3:0] out
);

reg [3:0] shifted;

always @(*) begin
    case (DIR)
        0: shifted = {in[3:amt], {amt{1'b0}}};
        1: shifted = {{amt{1'b0}}, in[amt-1:0]};
    endcase
    out = shifted;
end

endmodule

