    input [3:0] in1,
    input [3:0] in2,
    output reg eq,
    output reg gt,
    output reg lt
);

always @(*) begin
    eq = (in1 == in2);
    gt = (in1 > in2);
    lt = (in1 < in2);
end

endmodule

