module SerialHandler(
    input clk100MHz,
    input rst,
    input ext_clk,
    input ext_flush,
    input serial,
    output reg [10:0] ser_pos
);

reg [7:0] data_in [1:0];
reg [2:0] state;
reg [2:0] bit_count;

always @(posedge clk100MHz or posedge rst) begin
    if (rst) begin
        state <= 0;
        bit_count <= 0;
        ser_pos <= 0;
        data_in[0] <= 0;
        data_in[1] <= 0;
    end else begin
        case(state)
            0: begin
                if (ext_flush) begin
                    state <= 0;
                    bit_count <= 0;
                    ser_pos <= 0;
                    data_in[0] <= 0;
                    data_in[1] <= 0;
                end else begin
                    state <= 1;
                    bit_count <= 0;
                end
            end
            1: begin
                if (bit_count == 8) begin
                    state <= 2;
                    bit_count <= 0;
                end else begin
                    bit_count <= bit_count + 1;
                    data_in[0][bit_count] <= serial;
                end
            end
            2: begin
                if (bit_count == 8) begin
                    state <= 3;
                    bit_count <= 0;
                end else begin
                    bit_count <= bit_count + 1;
                    data_in[1][7-bit_count] <= serial;
                end
            end
            3: begin
                if (bit_count == 8) begin
                    state <= 4;
                    bit_count <= 0;
                end else begin
                    bit_count <= bit_count + 1;
                    data_in[1][bit_count] <= serial;
                end
            end
            default: begin
                state <= 0;
                bit_count <= 0;
                ser_pos <= 0;
                data_in[0] <= 0;
                data_in[1] <= 0;
            end
        endcase
    end
end

always @(posedge ext_clk) begin
    if (state == 1) begin
        ser_pos <= ser_pos + 1;
    end else if (state == 2 || state == 3) begin
        ser_pos <= ser_pos - 1;
    end
end

endmodule

