module fifo #(parameter FIFO_SIZE = 1, parameter FIFO_WIDTH = 32) (
    input wire CLK,
    input wire RST,
    input wire enq,
    input wire deq,
    input wire [FIFO_WIDTH-1:0] din,
    output wire [FIFO_WIDTH-1:0] dot,
    output wire emp,
    output wire full,
    output reg [FIFO_SIZE:0] cnt
);

    reg [FIFO_WIDTH-1:0] mem [(1<<FIFO_SIZE)-1:0];
    reg [FIFO_SIZE-1:0] head, tail;
    wire [FIFO_SIZE-1:0] next_head = head + 1'b1;
    wire [FIFO_SIZE-1:0] next_tail = tail + 1'b1;

    assign emp = (cnt == 0);
    assign full = (cnt == (1 << FIFO_SIZE));

    always @(posedge CLK) begin
        if (RST) begin
            cnt <= 0;
            head <= 0;
            tail <= 0;
        end
        else begin
            if (enq && !deq && !full) begin
                mem[head] <= din;
                head <= next_head;
                cnt <= cnt + 1;
            end
            else if (!enq && deq && !emp) begin
                dot <= mem[tail];
                tail <= next_tail;
                cnt <= cnt - 1;
            end
            else if (enq && deq && !full) begin
                mem[head] <= din;
                head <= next_head;
                dot <= mem[tail];
                tail <= next_tail;
            end
        end
    end

endmodule

