module dual_edge_detect(
  input               clk,
  input               rst_n,
  input               a,
  input               b,
  output reg          rise_a,
  output reg          down_a,
  output reg          rise_b,
  output reg          down_b,
  output reg [1:0]    first_edge
);

  reg a_dff, b_dff;

  // D flip-flop for input a
  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      a_dff <= 1'b0;
    end else begin
      a_dff <= a;
    end
  end

  // D flip-flop for input b
  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      b_dff <= 1'b0;
    end else begin
      b_dff <= b;
    end
  end

  // Edge detection for input a
  always @(posedge clk) begin
    rise_a <= a & ~a_dff;
    down_a <= ~a & a_dff;
  end

  // Edge detection for input b
  always @(posedge clk) begin
    rise_b <= b & ~b_dff;
    down_b <= ~b & b_dff;
  end

  // Determine which edge occurred first
  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      first_edge <= 2'b00;
    end else begin
      if (rise_a & ~rise_b) begin
        first_edge <= 2'b01;
      end else if (~rise_a & rise_b) begin
        first_edge <= 2'b10;
      end else if (down_a & ~down_b) begin
        first_edge <= 2'b01;
      end else if (~down_a & down_b) begin
        first_edge <= 2'b10;
      end else begin
        first_edge <= 2'b00;
      end
    end
  end

endmodule

