module float_arithmetic (
  input [31:0] A,
  input [31:0] B,
  input [1:0] op,
  output [31:0] out
);

  wire [31:0] add_result, sub_result, mul_result, div_result;
  wire [31:0] result;

  // Floating-point adder
  fp_add adder (
    .A(A),
    .B(B),
    .result(add_result)
  );

  // Floating-point subtractor
  fp_sub subtractor (
    .A(A),
    .B(B),
    .result(sub_result)
  );

  // Floating-point multiplier
  fp_mul multiplier (
    .A(A),
    .B(B),
    .result(mul_result)
  );

  // Floating-point divider
  fp_div divider (
    .A(A),
    .B(B),
    .result(div_result)
  );

  // Select the result based on the operation
  always @(*) begin
    case (op)
      2'b00: result = add_result;
      2'b01: result = sub_result;
      2'b10: result = mul_result;
      2'b11: result = div_result;
      default: result = 32'b0;
    endcase
  end

  assign out = result;

endmodule

module ripple_carry_adder (
    input wire a, 
    input wire b, 
    input wire carry_in, 
    output wire sum, 
    output wire carry_out
);

    assign {carry_out, sum} = a + b + carry_in;

endmodule

