module top_module (
    input wire clk,
    input wire reset,          // Synchronous active-high reset
    input wire [3:0] in1,      // 4-bit binary number 1
    input wire [3:0] in2,      // 4-bit binary number 2
    input wire select,         // Select input to choose between addition and subtraction
    output wire [4:0] result   // 5-bit binary output from the active module
);

    wire [3:0] twos_comp_in2;
    wire [3:0] twos_comp_result;
    wire [4:0] add_result;
    wire [4:0] sub_result;
    wire add_sub;

    control_logic control(select, add_sub);

    // Two's complement of in2
    assign twos_comp_in2 = ~in2 + 1;

    // Adder for addition
    ripple_carry_adder adder1(.a(in1), .b(in2), .carry_in(1'b0), .sum(add_result[3:0]), .carry_out(add_result[4]));

    // Adder for subtraction
    ripple_carry_adder adder2(.a(in1), .b(twos_comp_in2), .carry_in(1'b1), .sum(sub_result[3:0]), .carry_out(sub_result[4]));

    // Multiplexer to select between add and sub
    assign result = add_sub ? sub_result : add_result;

    // Two's complement of result for subtraction
    assign twos_comp_result = ~result + 1;

    // Synchronous reset
    always @(posedge clk) begin
        if (reset) begin
            result <= 5'b0;
        end else begin
            result <= add_sub ? twos_comp_result : add_result;
        end
    end

endmodule

module ballcollisions(
	clk,
	reset,
	p1_y,
	p2_y,
	ball_x,
	ball_y,
	dir_x,
	dir_y,
	oob
);

input clk, reset;
input [10:0] p1_y, p2_y, ball_x, ball_y;
output reg dir_x, dir_y, oob;

// Constants
localparam hc = 512;
localparam va = 0;
localparam vc = 480;
localparam batwidth = 10;
localparam batheight = 80;
localparam ballsize = 10;

// Initial values
reg ball_x_reg, ball_y_reg;
reg dir_x_reg, dir_y_reg;
reg oob_reg;
initial begin
	ball_x_reg = hc;
	ball_y_reg = vc/2;
	dir_x_reg = 0;
	dir_y_reg = 1;
	oob_reg = 0;
end

// Logic for direction changes
always @ (posedge clk) begin
	if (reset) begin
		dir_x_reg <= ~dir_x_reg;
		dir_y_reg <= 1;
		oob_reg <= 0;
		ball_x_reg <= hc;
		ball_y_reg <= vc/2;
	end
	else begin
		// out of bounds (i.e. one of the players missed the ball)
		if (ball_x_reg <= 0 || ball_x_reg >= hc) begin
			oob_reg <= 1;
		end
		else begin
			oob_reg <= 0;
		end

		// collision with top & bottom walls
		if (ball_y_reg <= va + ballsize) begin
			dir_y_reg <= 1;
		end
		if (ball_y_reg >= vc - ballsize) begin
			dir_y_reg <= 0;
		end

		// collision with P1 bat
		if (ball_x_reg <= batwidth && ball_y_reg + ballsize >= p1_y && ball_y_reg <= p1_y + batheight) begin
			dir_x_reg <= 1;
			if (ball_y_reg + ballsize <= p1_y + (batheight / 2)) begin
				dir_y_reg <= 0;
			end
			else begin
				dir_y_reg <= 1;
			end
		end
		// collision with P2 bat
		else if (ball_x_reg >= hc - batwidth - ballsize && ball_y_reg + ballsize <= p2_y + batheight && ball_y_reg >= p2_y) begin
			dir_x_reg <= 0;
			if (ball_y_reg + ballsize <= p2_y + (batheight / 2)) begin
				dir_y_reg <= 0;
			end
			else begin
				dir_y_reg <= 1;
			end
		end

		// Move ball based on direction
		if (dir_x_reg) begin
			ball_x_reg <= ball_x_reg + 1;
		end
		else begin
			ball_x_reg <= ball_x_reg - 1;
		end

		if (dir_y_reg) begin
			ball_y_reg <= ball_y_reg + 1;
		end
		else begin
			ball_y_reg <= ball_y_reg - 1;
		end
	end
end

// Assign output signals to registered values
assign dir_x = dir_x_reg;
assign dir_y = dir_y_reg;
assign oob = oob_reg;

endmodule

