        if (!reset_l) begin
            crc <= 64'h5aef0c8dd70a4497;
            sum <= 64'h0;
            cyc <= 0;
        end else if (enable) begin
            crc <= {crc[62:0], crc[63]^crc[2]^crc[0], {q_var6, q_var4, q_var2, q_var0}};
            sum <= sum ^ {sum[62:0], sum[63]^sum[2]^sum[0], {q_var6, q_var4, q_var2, q_var0}};
            cyc <= cyc + 1;
        end
    end

    always @(posedge clk) begin
        if (cyc == 99) begin
            if (crc !== 64'hc77bb9b3784ea091) $stop;
            if (sum !== 64'h58b162c58d6e35ba) $stop;
            q <= crc[2:0];
        end
    end

endmodule

module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

    wire [3:0] sum;

    // Full adder for the least significant bit
    full_adder FA0(
        .a(A[0]),
        .b(B[0]),
        .c(Cin),
        .sum(sum[0]),
        .carry(carry0)
    );

    // Full adder for bits 1-3
    full_adder FA1(
        .a(A[1]),
        .b(B[1]),
        .c(carry0),
        .sum(sum[1]),
        .carry(carry1)
    );

    full_adder FA2(
        .a(A[2]),
        .b(B[2]),
        .c(carry1),
        .sum(sum[2]),
        .carry(carry2)
    );

    full_adder FA3(
        .a(A[3]),
        .b(B[3]),
        .c(carry2),
        .sum(sum[3]),
        .carry(Cout)
    );

    assign S = sum;

endmodule

module full_adder(
    input a,
