module Calculator(a, b, mode, clear, result);

  input [3:0] a;
  input [3:0] b;
  input [1:0] mode;
  input clear;
  output [3:0] result;

  reg [3:0] result_reg;

  always @ (a or b or mode or clear) begin
    case (mode)
      2'b00: result_reg = a + b;
      2'b01: result_reg = a - b;
      2'b10: result_reg = a * b;
      2'b11: result_reg = a / b;
    endcase

    if (clear) begin
      result_reg = 4'd0;
    end
  end

  assign result = result_reg;

endmodule

module pipelined_adder (
    input clk,
    input rst,
    input [7:0] a,
    input [7:0] b,
    output [7:0] s,
    output overflow
);

reg [7:0] a_reg, b_reg, s_reg;
reg carry_in_reg;
wire [7:0] p, g;
wire [7:0] c;
wire carry_out;

assign p = a_reg ^ b_reg;
assign g = a_reg & b_reg;
assign c = {g[6], g[5], g[4], g[3], g[2], g[1], g[0], carry_in_reg};
assign carry_out = c[7] | (c[6] & p[6]) | (c[6] & c[5]) | (c[5] & p[5]) | (c[5] & c[4]) | (c[4] & p[4]) | (c[4] & c[3]) | (c[3] & p[3]) | (c[3] & c[2]) | (c[2] & p[2]) | (c[2] & c[1]) | (c[1] & p[1]) | (c[1] & c[0]) | (c[0] & p[0]);

assign s = s_reg;

assign overflow = (a[7] == b[7] && s[7] != a[7]) ? 1 : 0;

always @(posedge clk) begin
    if (rst) begin
        a_reg <= 0;
        b_reg <= 0;
        s_reg <= 0;
        carry_in_reg <= 0;
    end else begin
        a_reg <= a;
        b_reg <= b;
        s_reg <= s_reg + {carry_in_reg, p};
        carry_in_reg <= carry_out;
    end
end

endmodule

