module SAdder(output reg [31:0] Sum, output carry_out, output overflow, input [31:0] A, input [31:0] B, input carry_in);
	always @(*) begin
		{carry_out, Sum} = A + B + carry_in;
		if((A[31] == B[31]) && (A[31] != Sum[31]))
			overflow = 1;
		else
			overflow = 0;
	end
endmodule

module SSubtractor(output reg [31:0] Difference, output borrow_out, input [31:0] A, input [31:0] B, input borrow_in);
	always @(*) begin
		{borrow_out, Difference} = A - B - borrow_in;
	end
endmodule

module SMultiplier(output reg [63:0] Product, input [31:0] A, input [31:0] B);
