module add_sub (
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] sum_diff
);

    wire [31:0] carry;
    wire [31:0] xor_b;
    wire [31:0] inverted_b;
    wire [31:0] carry_out;
    wire [31:0] sum;
    wire [31:0] diff;

    assign xor_b = b ^ {32{sub}};
    assign inverted_b = ~xor_b;

    cla_adder adder_inst (
        .a(a),
        .b(inverted_b),
        .carry_in(sub),
        .sum(sum),
        .carry_out(carry_out)
    );

    assign diff = {32{sub}} ^ sum ^ inverted_b;

    assign sum_diff = sub ? diff : sum;

endmodule

