module delay_out
(
	// avalon clock interface
	input csi_clock_clk,
	input csi_clock_reset,

	// avalon mm slave: control
	input avs_ctrl_write,
	input [31:0]avs_ctrl_writedata,

	input sync,
	input clk400,

	input sig_in,
	output reg sig_out40,
	output sig_out80
);

	// avalon ctrl interface
	wire clk80 = csi_clock_clk;
	wire reset = csi_clock_reset;
	reg [5:0]delay;

	always @(posedge clk80 or posedge reset)
	begin
		if (reset) delay <= 0;
		else if (avs_ctrl_write) delay <= avs_ctrl_writedata[5:0];
	end


	wire [5:0]delout;

	// 1.25 ns delay step
	delay_ddrin half_stage
	(
		.clk(clk400),
		.reset(reset),
		.select(delay[0]),
		.in(sig_in),
		.out(delout[0])
	);

	// 4 x 2.5 ns delay step
	delay_in_stage d1(clk400, reset, delay[1], delout[0], delout[1]);
	delay_in_stage d2(clk400, reset, delay[2], delout[1], delout[2]);
	delay_in_stage d3(clk400, reset, delay[3], delout[2], delout[3]);
	delay_in_stage d4(clk400, reset, delay[4], delout[3], delout[4]);

	// clock crossing register	
	reg ccreg;
	always @(posedge clk80 or posedge reset)
	begin
		if (reset) ccreg <= 0;
		else ccreg <= delout[4];
	end

	// 12.5 ns delay stage
	delay_in_stage d5(clk80, reset, delay[5], ccreg, delout[5]);

	assign sig_out80 = delout[5];

	always @(posedge clk80 or posedge reset)
	begin
		if (reset) sig_out40 <= 0;
		else if (sync) sig_out40 <= delout[5];
	end

endmodule

// Delay element with input and output registers
module delay_in_stage
(
	input clk,
	input reset,
	input [5:0]delay,
	input in,
	output reg out
);

	wire [5:0]delout;

	// Delay element
	delay_ddrin stage
	(
		.clk(clk),
		.reset(reset),
		.select(delay[0]),
		.in(in),
		.out(delout[0])
	);

	// Cascade delay elements
	delay_ddrin cascade1
	(
		.clk(clk),
		.reset(reset),
		.select(delay[1]),
		.in(delout[0]),
		.out(delout[1])
	);

	delay_ddrin cascade2
	(
		.clk(clk),
		.reset(reset),
		.select(delay[2]),
		.in(delout[1]),
		.out(delout[2])
	);

	delay_ddrin cascade3
	(
		.clk(clk),
		.reset(reset),
		.select(delay[3]),
		.in(delout[2]),
		.out(delout[3])
	);

	delay_ddrin cascade4
	(
		.clk(clk),
		.reset(reset),
		.select(delay[4]),
		.in(delout[3]),
		.out(out)
	);

endmodule

// Delay element with input register only
module delay_ddrin
(
	input clk,
	input reset,
	input select,
	input in,
	output reg out
);

	reg [31:0]delay_reg;
	reg [31:0]in_reg;

	always @(posedge clk or posedge reset)
	begin
		if (reset)
		begin
			delay_reg <= 0;
			in_reg <= 0;
		end
		else
		begin
			delay_reg <= {delay_reg[30:0], select};
			in_reg <= in;
		end
	end

	assign out = in_reg[delay_reg[31:2]];

endmodule

