module ConsecutiveOnes(
    input [3:0] in,
    output [2:0] out
);

reg [2:0] count;
reg prev;

always @(in) begin
    if (in == 4'b0000) begin
        count <= 3'b000;
        prev <= 1'b0;
    end
    else if (in == 4'b1111) begin
        count <= 3'b111;
        prev <= 1'b1;
    end
    else if (in[3] & in[2] & in[1] & in[0]) begin
        count <= 3'b100;
        prev <= 1'b1;
    end
    else if (in[3] & in[2] & in[1] & ~in[0] & prev) begin
        count <= 3'b011;
        prev <= 1'b1;
    end
    else if (in[3] & in[2] & ~in[1] & prev) begin
        count <= 3'b010;
        prev <= 1'b1;
    end
    else if (in[3] & ~in[2] & prev) begin
        count <= 3'b001;
        prev <= 1'b1;
    end
    else begin
        count <= 3'b000;
        prev <= 1'b0;
    end
end

assign out = count;

endmodule

module arbiter(
    input [2:0] pe_request_bundle,
    input [2:0] north_request_bundle,
    input [2:0] east_request_bundle,
    input [1:0] pe_cfg_bundle,
    input [2:0] south_cfg_bundle,
    input [2:0] west_cfg_bundle,
    output reg [1:0] mux_ctrl,
    output reg r2pe_ack
);

    // localparams
    localparam MUX_EAST  = 3'b011;
    localparam MUX_NORTH = 3'b001;
    localparam MUX_PE    = 3'b101;
    localparam MUX_NULL  = 3'b000;

    localparam WEST  = 3'b011;
    localparam SOUTH = 3'b101;
    localparam PE    = 3'b111;
    localparam NULL  = 3'b000;

    // signals
    reg [2:0] req_vec;
    reg [2:0] cfg_vec;
    reg [2:0] priority_vec;
    reg [1:0] priority;
    reg [2:0] hit_vec;
    reg [2:0] granted_vec;
    reg [2:0] granted;
    reg [1:0] mux_ctrl_reg;
    reg r2pe_ack_reg;

    // assign hit_vec
    always @*
    begin
        hit_vec[0] = north_request_bundle[0] | east_request_bundle[1];
        hit_vec[1] = pe_request_bundle[0];
        hit_vec[2] = east_request_bundle[0] | south_cfg_bundle[2] | west_cfg_bundle[2];
    end

    // assign req_vec
    always @*
    begin
        req_vec[0] = north_request_bundle[2];
        req_vec[1] = pe_request_bundle[2];
        req_vec[2] = east_request_bundle[2] | south_cfg_bundle[0] | west_cfg_bundle[0];
    end

    // assign cfg_vec
    always @*
    begin
        cfg_vec[0] = west_cfg_bundle[1];
        cfg_vec[1] = north_request_bundle[1] | east_request_bundle[1] | pe_cfg_bundle[1];
        cfg_vec[2] = north_request_bundle[2] | pe_cfg_bundle[0] | south_cfg_bundle[2] | west_cfg_bundle[2];
    end

    // assign priority_vec
    always @*
    begin
        priority_vec[0] = cfg_vec[0] ? hit_vec[0] : NULL;
        priority_vec[1] = cfg_vec[1] ? hit_vec[1] : NULL;
        priority_vec[2] = cfg_vec[2] ? hit_vec[2] : NULL;
    end

    // assign priority
    always @*
    begin
        priority = 2'b00;
        if (priority_vec[0] > priority_vec[1] && priority_vec[0] > priority_vec[2])
            priority = 2'b01;
        else if (priority_vec[1] > priority_vec[2])
            priority = 2'b10;
        else
            priority = 2'b11;
    end

    // assign granted_vec
    always @*
    begin
        granted_vec[0] = priority == 2'b01 ? hit_vec[0] : NULL;
        granted_vec[1] = priority == 2'b10 ? hit_vec[1] : NULL;
        granted_vec[2] = priority == 2'b11 ? hit_vec[2] : NULL;
    end

    // assign granted
    always @*
    begin
        granted = granted_vec[0] | granted_vec[1] | granted_vec[2];
    end

    // assign mux_ctrl
    always @*
    begin
        mux_ctrl_reg = priority == 2'b01 ? MUX_NORTH :
                       priority == 2'b10 ? MUX_PE :
                                          MUX_EAST;
        mux_ctrl = mux_ctrl_reg;
    end

    // assign r2pe_ack
    always @*
    begin
        r2pe_ack_reg = granted_vec[1];
        r2pe_ack = r2pe_ack_reg;
    end

endmodule

