module byte_reverser(
    input [31:0] in,
    output [31:0] out
);

    wire [7:0] chunk1, chunk2, chunk3, chunk4;
    wire [7:0] shifted_chunk1, shifted_chunk2, shifted_chunk3, shifted_chunk4;

    // Divide input into four 8-bit chunks
    assign chunk1 = in[7:0];
    assign chunk2 = in[15:8];
    assign chunk3 = in[23:16];
    assign chunk4 = in[31:24];

    // Shift each chunk to the correct position
    // Chunk 1 is shifted to position 24
    assign shifted_chunk1 = {chunk1, 8'b0, 8'b0, 8'b0};
    // Chunk 2 is shifted to position 16
    assign shifted_chunk2 = {8'b0, chunk2, 8'b0, 8'b0};
    // Chunk 3 is shifted to position 8
    assign shifted_chunk3 = {8'b0, 8'b0, chunk3, 8'b0};
    // Chunk 4 is shifted to position 0
    assign shifted_chunk4 = {8'b0, 8'b0, 8'b0, chunk4};

    // Combine shifted chunks to form reversed output
    assign out = shifted_chunk1 | shifted_chunk2 | shifted_chunk3 | shifted_chunk4;

endmodule

