module full_adder_2bit(
    input [1:0] a,
    input [1:0] b,
    input carry_in,
    output [1:0] sum,
    output carry_out
);

wire c1, c2, s1, s2;

nand(s1, a[0], b[0]);
nand(s2, s1, carry_in);
nand(c1, s1, carry_in);
nand(s1, a[1], b[1]);
nand(sum[0], s2, s1);
nand(c2, s2, s1);
nand(carry_out, c1, c2);
nand(sum[1], a[0], b[0], carry_in);

endmodule

