module tone_generator (
  input clk,
  input reset,
  input [1:0] tone_sel,
  input [7:0] duration,
  output reg tone_out
);

parameter clk_freq = 50_000_000; // clock frequency
parameter dtmf_freq1 = 697; // frequency for DTMF tone 1
parameter dtmf_freq2 = 1209; // frequency for DTMF tone 2
parameter sine_freq = 1000; // frequency for sine wave tone
parameter square_freq = 500; // frequency for square wave tone

reg [15:0] dtmf_counter1 = 0; // counter for DTMF tone 1
reg [15:0] dtmf_counter2 = 0; // counter for DTMF tone 2
reg [15:0] sine_counter = 0; // counter for sine wave tone
reg [15:0] square_counter = 0; // counter for square wave tone

always @(posedge clk) begin
  if (reset) begin
    tone_out <= 0;
    dtmf_counter1 <= 0;
    dtmf_counter2 <= 0;
    sine_counter <= 0;
    square_counter <= 0;
  end else begin
    case (tone_sel)
      2'b00: begin // DTMF tone
        if (dtmf_counter1 >= clk_freq/(2*dtmf_freq1)) begin
          dtmf_counter1 <= 0;
        end else begin
          dtmf_counter1 <= dtmf_counter1 + 1;
        end
        if (dtmf_counter2 >= clk_freq/(2*dtmf_freq2)) begin
          dtmf_counter2 <= 0;
        end else begin
          dtmf_counter2 <= dtmf_counter2 + 1;
        end
        tone_out <= (dtmf_counter1 < clk_freq/(4*dtmf_freq1)) && (dtmf_counter2 < clk_freq/(4*dtmf_freq2));
      end
      2'b01: begin // sine wave tone
        if (sine_counter >= clk_freq/(2*sine_freq)) begin
          sine_counter <= 0;
        end else begin
          sine_counter <= sine_counter + 1;
        end
        tone_out <= sin(2*3.1415926*sine_counter*1.0/clk_freq);
      end
      2'b10: begin // square wave tone
        if (square_counter >= clk_freq/(2*square_freq)) begin
          square_counter <= 0;
        end else begin
          square_counter <= square_counter + 1;
        end
        tone_out <= (square_counter < clk_freq/(4*square_freq)) ? 1 : 0;
      end
      default: begin // default to no tone
        tone_out <= 0;
      end
    endcase
  end
end

endmodule

module top_module (
