    if (VGND == 0) begin
        X <= 1'bx;
        inputs <= 5'bxxxxx;
    end else if (inputs != old_inputs) begin
        if (inputs[4:0] == 5'b00000) begin
            X <= 1'b0;
        end else if (inputs[4:0] == 5'b11111) begin
            X <= 1'b1;
        end else begin
            X <= 1'bx;
        end
        old_inputs <= inputs;
    end
end

