module matrix_mult (
    input [15:0] A [3:0][3:0],
    input [15:0] B [3:0][3:0],
    output reg [15:0] C [3:0][3:0]
);

reg [15:0] temp [3:0][3:0];
reg [15:0] sum [3:0][3:0];
integer i, j, k;

always @(*) begin
    for (i = 0; i < 4; i = i + 1) begin
        for (j = 0; j < 4; j = j + 1) begin
            temp[i][j] = 0;
            for (k = 0; k < 4; k = k + 1) begin
                temp[i][j] = temp[i][j] + A[i][k] * B[k][j];
            end
        end
    end
end

always @(posedge clk) begin
    for (i = 0; i < 4; i = i + 1) begin
        for (j = 0; j < 4; j = j + 1) begin
            if (j == 0) begin
                sum[i][j] = temp[i][j];
            end else begin
                sum[i][j] = sum[i][j-1] + temp[i][j];
            end
            C[i][j] <= sum[i][j];
        end
    end
end

endmodule

