    if (reset) begin
        shift_reg <= 2'b01;
        control <= 2'b00;
        fib <= 8'b00000001;
    end else begin
        case (control)
            2'b00: begin
                shift_reg <= {shift_reg[6:0], shift_reg[7]};
                control <= 2'b01;
            end
            2'b01: begin
                shift_reg <= {shift_reg[6:0], shift_reg[7]};
                control <= 2'b10;
            end
            2'b10: begin
                shift_reg <= shift_reg + {shift_reg[6:0], shift_reg[7]};
                control <= 2'b00;
                fib <= shift_reg;
            end
        endcase
    end
end

endmodule

module rf_2p (
    clka    ,  
    cena_i  ,
    addra_i ,
    dataa_o ,
    clkb    ,     
    cenb_i  ,   
    wenb_i  ,   
    addrb_i ,  
    datab_i
);

// ********************************************
//                                             
//    Parameter DECLARATION                    
//                                             
// ********************************************
parameter       Word_Width=32;
parameter       Addr_Width=8;

// ********************************************
//                                             
//    Input/Output DECLARATION                    
//                                             
// ********************************************
// A port
input                   clka;      // clock input
input                   cena_i;    // chip enable, low active
input   [Addr_Width-1:0]  addra_i;   // address input
output  [Word_Width-1:0]  dataa_o;   // data output

// B Port
input                   clkb;      // clock input                     
input                   cenb_i;    // chip enable, low active      
input                   wenb_i;    // write enable, low active        
input   [Addr_Width-1:0]  addrb_i;   // address input                   
input   [Word_Width-1:0]  datab_i;   // data input                     

// ********************************************
//                                             
//    Register DECLARATION                  
//                                             
// ********************************************
reg    [Word_Width-1:0]   mem_array[(1<<Addr_Width)-1:0];

// ********************************************
//                                             
//    Wire DECLARATION                  
//                                             
// ********************************************
reg    [Word_Width-1:0]   dataa_r;

// ********************************************
//                                             
//    Logic DECLARATION                  
//                                             
// ********************************************
// -- A Port --//
always @(posedge clka) begin
    if (!cena_i)
        dataa_r <= mem_array[addra_i];
    else
        dataa_r <= 'bx;
end

assign dataa_o = dataa_r;

// -- B Port --//
always @(posedge clkb) begin
    if(!cenb_i) begin
        if(wenb_i) begin
            if(datab_i > mem_array[addrb_i]) begin
                mem_array[addrb_i] <= datab_i;
            end
        end else begin
            mem_array[addrb_i] <= datab_i;
        end
    end
end

endmodule

module ripple_adder_4bit(A, B, Cin, S, Cout);
  input [3:0] A, B;
  input Cin;
  output [3:0] S;
  output Cout;

  wire [3:0] C;
  wire [3:0] sum;

  // First full adder
  full_adder FA0(.a(A[0]), .b(B[0]), .cin(Cin), .sum(sum[0]), .cout(C[0]));

  // Second full adder
  full_adder FA1(.a(A[1]), .b(B[1]), .cin(C[0]), .sum(sum[1]), .cout(C[1]));

  // Third full adder
  full_adder FA2(.a(A[2]), .b(B[2]), .cin(C[1]), .sum(sum[2]), .cout(C[2]));

  // Fourth full adder
  full_adder FA3(.a(A[3]), .b(B[3]), .cin(C[2]), .sum(sum[3]), .cout(Cout));

  // Output wires
  assign S = sum;

endmodule

module full_adder(a, b, cin, sum, cout);
  input a, b, cin;
  output sum, cout;

  // Calculate sum
  xor(sum, a, b, cin);

  // Calculate carry out
  assign cout = (a & b) | (a & cin) | (b & cin);
endmodule

module top_module( 
    input [255:0] in, // 256 inputs packed into 8 32-bit input vectors
    input a, // First input for the NOR gate
    input b, // Second input for the NOR gate
    output out // Output of the selected input from the 256-to-1 multiplexer
);

    // Implement 8 32-to-1 multiplexers
    wire [31:0] mux_out[0:7];
    wire [2:0] decoder_out;
    wire [31:0] selected_input;

    mux_32to1 mux0(.in(in[31:0]), .sel(decoder_out[0]), .out(mux_out[0]));
    mux_32to1 mux1(.in(in[63:32]), .sel(decoder_out[0]), .out(mux_out[1]));
    mux_32to1 mux2(.in(in[95:64]), .sel(decoder_out[0]), .out(mux_out[2]));
    mux_32to1 mux3(.in(in[127:96]), .sel(decoder_out[0]), .out(mux_out[3]));
    mux_32to1 mux4(.in(in[159:128]), .sel(decoder_out[0]), .out(mux_out[4]));
    mux_32to1 mux5(.in(in[191:160]), .sel(decoder_out[0]), .out(mux_out[5]));
    mux_32to1 mux6(.in(in[223:192]), .sel(decoder_out[0]), .out(mux_out[6]));
    mux_32to1 mux7(.in(in[255:224]), .sel(decoder_out[0]), .out(mux_out[7]));

    // Implement 3-to-8 decoder
    decoder_3to8 decoder(.in({a, b}), .out(decoder_out));

    // Implement NOR gate
    wire [7:0] nand_out;
    nand_gate nand0(.a(a), .b(b), .out(nand_out[0]));
    nand_gate nand1(.a(nand_out[0]), .b(nand_out[0]), .out(nand_out[1]));
    nand_gate nand2(.a(nand_out[1]), .b(nand_out[1]), .out(nand_out[2]));
    nand_gate nand3(.a(nand_out[2]), .b(nand_out[2]), .out(nand_out[3]));
    nand_gate nand4(.a(nand_out[3]), .b(nand_out[3]), .out(nand_out[4]));
    nand_gate nand5(.a(nand_out[4]), .b(nand_out[4]), .out(nand_out[5]));
    nand_gate nand6(.a(nand_out[5]), .b(nand_out[5]), .out(nand_out[6]));
    nand_gate nand7(.a(nand_out[6]), .b(nand_out[6]), .out(nand_out[7]));
    inverter inv(.in(nand_out[7]), .out(selected_input));

    // Implement 256-to-1 multiplexer
    mux_32to1 mux_final0(.in(mux_out[0]), .sel(selected_input[4:0]), .out(out));
    mux_32to1 mux_final1(.in(mux_out[1]), .sel(selected_input[4:0]), .out(out));
    mux_32to1 mux_final2(.in(mux_out[2]), .sel(selected_input[4:0]), .out(out));
    mux_32to1 mux_final3(.in(mux_out[3]), .sel(selected_input[4:0]), .out(out));
    mux_32to1 mux_final4(.in(mux_out[4]), .sel(selected_input[4:0]), .out(out));
    mux_32to1 mux_final5(.in(mux_out[5]), .sel(selected_input[4:0]), .out(out));
    mux_32to1 mux_final6(.in(mux_out[6]), .sel(selected_input[4:0]), .out(out));
    mux_32to1 mux_final7(.in(mux_out[7]), .sel(selected_input[4:0]), .out(out));

endmodule

module div_module(
  input clk,
  input reset,
  input [7:0] in1,
  input [7:0] in2,
  output [15:0] out,
  output [7:0] remainder
);

  reg [15:0] quotient;
  reg [7:0] rem;
  reg [7:0] divisor;
  reg [15:0] dividend;
  reg [3:0] count;

  always @(posedge clk) begin
    if (reset) begin
      quotient <= 16'd0;
      rem <= 8'd0;
      divisor <= 8'd0;
      dividend <= 16'd0;
      count <= 4'd0;
    end else begin
      if (in2 == 8'd0) begin
        quotient <= 16'd0;
        rem <= 8'd0;
      end else begin
        divisor <= in2;
        dividend <= {in1, 8'd0};
        count <= 4'd0;
        while (dividend >= divisor) begin
          dividend <= dividend - divisor;
          count <= count + 1;
        end
        quotient <= count;
        rem <= dividend[7:0];
      end
    end
  end

  assign out = quotient;
  assign remainder = rem;

endmodule

module myModule (
    input CLK,
    input ready_downstream,
    output reg ready,
    input reset,
    input [64:0] process_input,
    output reg [64:0] process_output
);

reg too_soon = process_input[64];
reg [31:0] output_count = 0;

always @(posedge CLK) begin
    if (reset) begin
        ready <= 1'b0;
        output_count <= 0;
        process_output <= 0;
    end else if (too_soon) begin
        ready <= 1'b0;
    end else if (ready_downstream && output_count < 76800) begin
        ready <= 1'b1;
        output_count <= output_count + 1;
        process_output <= ~reset;
    end else begin
        ready <= 1'b1;
        output_count <= output_count + 1;
        process_output <= {1'b1, process_input[63:0]};
    end
end

endmodule

