module HDMI_Transmitter (
  input [23:0] pixel_data,
  input clock,
  input control_signals,
  output reg [23:0] hdmi_data
);

  // Define necessary parameters
  parameter H_BLANK = 160;
  parameter H_SYNC = 44;
  parameter H_ACTIVE = 1920;
  parameter V_BLANK = 45;
  parameter V_SYNC = 5;
  parameter V_ACTIVE = 1080;
  parameter PIXEL_CLOCK = 148500000;

  // Define necessary registers
  reg [11:0] h_count = 0;
  reg [10:0] v_count = 0;
  reg [23:0] pixel_out = 0;
  reg [3:0] state = 0;

  // Define necessary wires
  wire h_sync = (h_count >= H_ACTIVE + H_BLANK && h_count < H_ACTIVE + H_BLANK + H_SYNC) ? 1'b0 : 1'b1;
  wire v_sync = (v_count >= V_ACTIVE + V_BLANK && v_count < V_ACTIVE + V_BLANK + V_SYNC) ? 1'b0 : 1'b1;

  // Generate HDMI data signal
  always @(posedge clock) begin
    case(state)
      0: begin
        hdmi_data <= 24'h000000;
        if (h_count >= H_ACTIVE + H_BLANK) begin
          h_count <= 0;
          v_count <= v_count + 1;
          if (v_count >= V_ACTIVE + V_BLANK) begin
            v_count <= 0;
            state <= 1;
          end
        end else begin
          h_count <= h_count + 1;
          pixel_out <= pixel_data;
        end
      end
      1: begin
        hdmi_data <= {h_sync, v_sync, pixel_out};
        if (h_count >= H_ACTIVE + H_BLANK + H_SYNC - 1) begin
          h_count <= 0;
          v_count <= v_count + 1;
          if (v_count >= V_ACTIVE + V_BLANK) begin
            v_count <= 0;
            state <= 0;
          end
        end else begin
          h_count <= h_count + 1;
        end
      end
    endcase
  end

endmodule
module HDMI_Receiver (
  input [23:0] hdmi_data,
  input clock,
  input control_signals,
  output reg [23:0] pixel_data
);

  // Define necessary parameters
  parameter H_BLANK = 160;
  parameter H_SYNC = 44;
  parameter H_ACTIVE = 1920;
  parameter V_BLANK = 45;
  parameter V_SYNC = 5;
  parameter V_ACTIVE = 1080;
  parameter PIXEL_CLOCK = 148500000;

  // Define necessary registers
  reg [11:0] h_count = 0;
  reg [10:0] v_count = 0;
  reg [23:0] pixel_in = 0;
  reg [3:0] state = 0;

  // Extract pixel data from HDMI data signal
  always @(posedge clock) begin
    case(state)
      0: begin
        if (h_count >= H_ACTIVE + H_BLANK) begin
          h_count <= 0;
          v_count <= v_count + 1;
          if (v_count >= V_ACTIVE + V_BLANK) begin
            v_count <= 0;
            state <= 1;
          end
        end else begin
          h_count <= h_count + 1;
        end
      end
      1: begin
        pixel_in <= hdmi_data[23:0];
        if (h_count >= H_ACTIVE + H_BLANK + H_SYNC - 1) begin
          h_count <= 0;
          v_count <= v_count + 1;
          if (v_count >= V_ACTIVE + V_BLANK) begin
            v_count <= 0;
            state <= 0;
          end
        end else begin
          h_count <= h_count + 1;
        end
      end
    endcase
  end

  // Output pixel data
  always @(posedge clock) begin
    pixel_data <= pixel_in;
  end

endmodule

module reg_wo_4burst(
    input wire clk,
    input wire [15:0] bus_ad, // raw mux data
    input wire [18:0] my_a,
    input wire [2:0] bus_a, // high address bits
    input wire adv, // active high, so connect to !EIM_LBA
    input wire rw,  // low = write, high = read, so connect to EIM_RW
    input wire cs,  // active high, so connect to !EIM_CS[1]
    output wire [63:0] reg_d,
    output reg [15:0] rbk_d, // readback tri-state interface
    output wire strobe // pulses one cycle after access is done
);

    reg [63:0] bstate;
    reg [2:0] bcount;
    reg activated;
    reg [15:0] bus_ad_r;
    reg cs_r;
    reg [2:0] bus_a_r;
    reg rw_r;
    reg adv_r;
    reg activated_d;

    always @(posedge clk) begin
        bus_ad_r <= bus_ad;
        bus_a_r <= bus_a;
        cs_r <= cs;
        rw_r <= rw;
        adv_r <= adv;

        if (cs_r && adv_r && {bus_a_r, bus_ad_r} == my_a) begin
            activated <= 1'b1;
            bcount <= 3'b0;
        end else if (!cs_r) begin
            activated <= 1'b0;
            bcount <= 3'b0;
        end else if (bcount <= 3'b111) begin
            bcount <= bcount + 3'b01;
        end
    end

    always @(posedge clk) begin
        if (activated && !rw_r) begin
            case (bcount)
                3'b00: bstate[15:0] <= bus_ad_r;
                3'b01: bstate[31:16] <= bus_ad_r;
                3'b10: bstate[47:32] <= bus_ad_r;
                3'b11: bstate[63:48] <= bus_ad_r;
                default: bstate <= bstate;
            endcase
        end else begin
            bstate <= bstate;
        end
    end

    always @(activated or bcount or rw_r or bstate) begin
        if (activated && rw_r) begin
            case (bcount)
                3'b0001: rbk_d = bstate[15:0];
                3'b010: rbk_d = bstate[31:16];
                3'b011: rbk_d = bstate[47:32];
                3'b100: rbk_d = bstate[63:48];
                default: rbk_d = 16'hZZZZ;
            endcase
        end else begin
            rbk_d = 16'hZZZZ;
        end
    end

    always @(posedge clk) begin
        activated_d <= activated;
    end
    assign strobe = activated_d & !activated;

    assign reg_d = bstate;

endmodule

module min_finder (
    input [7:0] a, b, c, d,
    output [7:0] min);

    wire [7:0] ab_min, cd_min, abcd_min;

    // Compare a and b to find the minimum value
    comparator cmp_ab(a, b, ab_min);

    // Compare c and d to find the minimum value
    comparator cmp_cd(c, d, cd_min);

    // Compare the minimum values of a and b, and c and d to find the overall minimum value
    comparator cmp_abcd(ab_min, cd_min, abcd_min);

    // Output the minimum value
    assign min = abcd_min;

endmodule

module comparator (
