        if (a < b) begin
            min = a;
        end
        else begin
            min = b;
        end
    end

endmodule

module fsm_sequence_detection (
  input clk,
  input reset,
  input data,
  output reg match
);

reg [1:0] state;
reg [4:0] shift_reg;

parameter STATE_0 = 2'b00;
parameter STATE_1 = 2'b01;
parameter STATE_2 = 2'b10;

always @(posedge clk or posedge reset) begin
  if (reset) begin
    state <= STATE_0;
    shift_reg <= 5'b0;
    match <= 0;
  end else begin
    case (state)
      STATE_0: begin
        shift_reg <= {shift_reg[3:0], data};
        if (shift_reg == 5'b10101) begin
          match <= 1;
          state <= STATE_2;
        end else begin
          state <= STATE_1;
        end
      end
      STATE_1: begin
        shift_reg <= {shift_reg[3:0], data};
        if (shift_reg == 5'b10101) begin
          match <= 1;
          state <= STATE_2;
        end else begin
          state <= STATE_0;
        end
      end
      STATE_2: begin
        match <= 1;
        state <= STATE_2;
      end
    endcase
  end
end

endmodule

