module min_max_calculator(
  input [n-1:0] in,
  input signed_or_unsigned,
  output [n-1:0] min_val,
  output [n-1:0] max_val
);

parameter n = 4; // number of input signals

reg [n-1:0] signed_in [2:0]; // 3-dimensional array to store signed/unsigned inputs
reg [n-1:0] unsigned_in [2:0];

integer i;

// separate signed and unsigned inputs
always @(*) begin
  for (i = 0; i < n; i = i + 1) begin
    if (signed_or_unsigned == 1) begin
      signed_in[0][i] = in[i];
      signed_in[1][i] = in[i];
      signed_in[2][i] = in[i];
    end
    else begin
      unsigned_in[0][i] = in[i];
      unsigned_in[1][i] = in[i];
      unsigned_in[2][i] = in[i];
    end
  end
end

// calculate min and max values for signed inputs
always @(*) begin
  if (signed_or_unsigned == 1) begin
    for (i = 0; i < n; i = i + 1) begin
      if (signed_in[0][i] < signed_in[1][i])
        signed_in[1][i] = signed_in[0][i];
      if (signed_in[2][i] > signed_in[1][i])
        signed_in[2][i] = signed_in[1][i];
    end
    min_val = signed_in[1];
    max_val = signed_in[2];
  end
end

// calculate min and max values for unsigned inputs
always @(*) begin
  if (signed_or_unsigned == 0) begin
    for (i = 0; i < n; i = i + 1) begin
      if (unsigned_in[0][i] < unsigned_in[1][i])
        unsigned_in[1][i] = unsigned_in[0][i];
      if (unsigned_in[2][i] > unsigned_in[1][i])
        unsigned_in[2][i] = unsigned_in[1][i];
    end
    min_val = unsigned_in[1];
    max_val = unsigned_in[2];
  end
end

endmodule

module eight_bit_adder (a, b, cin, sum, cout);

