module Permute(state_in, IV_in, state_out, IV_out, clk, rst, en, rdy);

	input		 [263:0]	state_in;
	input	 [15:0]		IV_in;
	input					rst;
	input 				clk;
	input					en;

	output reg[263:0]	state_out;
	output reg	[15:0]	IV_out;
	output reg			rdy;

	reg					wr_en;
	reg	[15:0]		IV_inv;
	reg	[7:0]		byte;
	reg	[31:0]		i;

	always @ (posedge clk or posedge rst) begin

		if (rst) begin
			state_out = 0;
			IV_out = 0;
			rdy = 0;
			wr_en = 1;
			IV_inv = 16'hffff;
			byte = 8'h00;
			i = 0;
		end else if (en) begin

			// initialize byte and i here, if Permute is enabled
			if (byte == 8'h00 && i == 0) begin
				byte = state_in[7:0] ^ IV_in[7:0];
				i = 1;
			end

			// Perform byte swaps and XORs
			if (i <= 31) begin
				if (i % 4 == 1) begin
					state_out[(8*(i-1))+7 : 8*(i-1)] = state_in[(8*i)-1 : 8*(i-1)] ^ IV_in[7:0];
					state_out[(8*(i-1))+15 : 8*i] = state_in[(8*i)-9 : (8*(i-1))+8];
					state_out[(8*i)-1 : 8*(i-1)+8] = byte ^ IV_in[7:0];
					byte = state_out[(8*i)-1 : 8*(i-1)+8];
				end else begin
					state_out[(8*(i-1))+7 : 8*(i-1)] = state_in[(8*i)-1 : 8*(i-1)] ^ IV_in[7:0];
					state_out[(8*(i-1))+15 : 8*i] = state_in[(8*i)-9 : (8*(i-1))+8];
					state_out[(8*i)-1 : 8*(i-1)+8] = byte ^ IV_in[7:0];
					byte = state_out[(8*i)-1 : 8*(i-1)+8];
				end
				i = i + 1;
			end else begin
				IV_out = ~IV_in;
				state_out[263:248] = state_in[15:0] ^ IV_in[15:0];
				state_out[247:0] = state_in[263:16] ^ IV_in[7:0];
				rdy = 1;
			end
		end
	end

endmodule

module top_module (
    input clk,
    input [7:0] reset,      // Asynchronous reset for flip-flop module
    input [7:0] d,
    output [7:0] flip_flop_q, // Output of the flip-flop module
    output reg [3:0] jc_q // Output of the Johnson counter module
);

