    flip_flop_module flip_flops (
        .clk(clk),
        .reset(reset),
        .d(d),
        .q(flip_flop_q)
    );

    // Instantiate Johnson counter module
    johnson_counter jc (
        .clk(clk),
        .rst_n(1),
        .Q(jc_q)
    );

    // Connect flip-flop module output to Johnson counter module input
    assign jc.Q[0] = flip_flop_q[0];
    assign jc.Q[1] = flip_flop_q[1];
    assign jc.Q[2] = flip_flop_q[2];
    assign jc.Q[3] = flip_flop_q[3];

    // Instantiate functional module
