module flip_flop_module (
    input clk,
    input [7:0] reset,      // Asynchronous reset for each flip-flop
    input [7:0] d,
    output reg [7:0] q
);

    always @(negedge clk) begin
        if (reset[0] == 0) q[0] <= 1'b0;
        else q[0] <= d[0];
        if (reset[1] == 0) q[1] <= 1'b0;
        else q[1] <= d[1];
        if (reset[2] == 0) q[2] <= 1'b0;
        else q[2] <= d[2];
        if (reset[3] == 0) q[3] <= 1'b0;
        else q[3] <= d[3];
        if (reset[4] == 0) q[4] <= 1'b0;
        else q[4] <= d[4];
        if (reset[5] == 0) q[5] <= 1'b0;
        else q[5] <= d[5];
        if (reset[6] == 0) q[6] <= 1'b0;
        else q[6] <= d[6];
        if (reset[7] == 0) q[7] <= 1'b0;
        else q[7] <= d[7];
    end

endmodule

module johnson_counter (
    input clk,
    input rst_n,
    output reg [3:0] Q
);

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) Q <= 4'b0000;
        else Q <= {Q[2:0], ~Q[3]};
    end

endmodule

module functional_module (
    input [7:0] a, // Input from flip-flop module
    input [3:0] b, // Input from Johnson counter module
    output reg [7:0] out // Output of the functional module
);

    always @(*) begin
        out = a ^ {b, b, b, b, b, b, b, b};
    end

endmodule

