module calc_res(
    input wire rst_n,
    input wire clk,
    input de,
    input hsync,
    input vsync,
    output reg [15:0] resX,
    output reg [15:0] resY
);

    reg [15:0] resX_q, resY_q, resY_t;
    reg vsync_q, hsync_q, de_q;
    wire hsync_risingedge;
    wire vsync_risingedge;
    wire de_risingedge;
    wire de_fallingedge;

    assign hsync_risingedge = ((hsync_q ^ hsync) & hsync);
    assign vsync_risingedge = ((vsync_q ^ vsync) & vsync);
    assign de_risingedge = ((de_q ^ de) & de);
    assign de_fallingedge = ((de_q ^ de) & ~de);

    always @(posedge clk) begin
        if (~rst_n) begin
            resX <= 0;
            resY <= 0;
            resY_q <= 0;
            resX_q <= 0;
            resY_t <= 0;
        end else begin
            vsync_q <= vsync;
            hsync_q <= hsync;
            de_q <= de;

            if (de) begin
                resX_q <= resX_q + 1;
            end else if (hsync_risingedge) begin
                resX_q <= 0;
                if (resX_q != 0) begin
                    resX <= resX_q;
                end
            end

            if (de_risingedge) begin
                resY_q <= resY_q + 1;
            end else if (de_fallingedge) begin
                resY_t <= resY_q;
            end else if (vsync_risingedge) begin
                resY_q <= 0;
                if (resY_q != 0) begin
                    resY <= resY_t;
                end
            end
        end
    end

endmodule

module Divider (
  input [n-1:0] dividend, divisor,
  output [n-1:0] quotient, remainder
);

parameter n = 8; // number of bits in the numbers
parameter type = "restoring"; // type of the divider circuit (unsigned, signed, restoring, non-restoring, SRT, or pipelined)

reg [n-1:0] dividend_reg, divisor_reg, quotient_reg, remainder_reg;
reg [n:0] divisor_abs_reg;
reg [n:0] remainder_abs_reg;
reg [n:1] quotient_abs_reg;

integer i;

always @(*) begin
  dividend_reg = dividend;
  divisor_reg = divisor;

  case (type)
    "unsigned": begin
      quotient_reg = dividend_reg / divisor_reg;
      remainder_reg = dividend_reg % divisor_reg;
    end
    "signed": begin
      quotient_reg = $signed(dividend_reg) / $signed(divisor_reg);
      remainder_reg = $signed(dividend_reg) % $signed(divisor_reg);
    end
    "restoring": begin
      divisor_abs_reg = {1'b0, divisor_reg};
      remainder_abs_reg = dividend_reg;
      quotient_abs_reg = 0;

      for (i = 0; i < n; i = i + 1) begin
        remainder_abs_reg = remainder_abs_reg - divisor_abs_reg;
        if (remainder_abs_reg < 0) begin
          remainder_abs_reg = remainder_abs_reg + divisor_abs_reg;
          quotient_abs_reg[i+1] = 0;
        end
        else begin
          quotient_abs_reg[i+1] = 1;
        end
      end

      quotient_reg = quotient_abs_reg[1:n];
      remainder_reg = remainder_abs_reg[1:n];
    end
    "non-restoring": begin
      divisor_abs_reg = {1'b0, divisor_reg};
      remainder_abs_reg = dividend_reg;
      quotient_abs_reg = 0;

      for (i = 0; i < n; i = i + 1) begin
        remainder_abs_reg = remainder_abs_reg - divisor_abs_reg;
        if (remainder_abs_reg < 0) begin
          remainder_abs_reg = remainder_abs_reg + divisor_abs_reg;
          quotient_abs_reg[i+1] = 1;
        end
        else begin
          quotient_abs_reg[i+1] = 0;
        end
      end

      quotient_reg = quotient_abs_reg[1:n];
      remainder_reg = remainder_abs_reg[1:n];
    end
    "SRT": begin
      // TODO: implement SRT algorithm
    end
    "pipelined": begin
      // TODO: implement pipelined algorithm
    end
    default: begin
      $display("Error: Invalid type parameter");
    end
  endcase

end

assign quotient = quotient_reg;
assign remainder = remainder_reg;

endmodule

