    input iRST_N
);

parameter REF_CLK = 18432000;
parameter SAMPLE_RATE = 48000;
parameter DATA_WIDTH = 16;
parameter CHANNEL_NUM = 2;

// FIFO Side
wire [DATA_WIDTH-1:0] mDATA;
reg [DATA_WIDTH-1:0] mDATA_RD;
FIFO_16_256 u0 (
    .data(iDATA),
    .wrreq(iWR),
    .rdreq(mDATA_RD),
    .rdclk(iCLK_18_4),
    .wrclk(iWR_CLK),
    .aclr(~iRST_N),
    .q(mDATA),
    .wrfull(oDATA[0])
);

// Audio Side
reg oAUD_BCK;
reg [DATA_WIDTH-1:0] DATA_Out;
reg [DATA_WIDTH-1:0] DATA_Out_Tmp;
reg LRCK_1X;
reg LRCK_2X;

// Control Signals
assign oAUD_XCK = ~iCLK_18_4;

// Internal Registers and Wires
reg [3:0] BCK_DIV;
reg [8:0] LRCK_1X_DIV;
reg [7:0] LRCK_2X_DIV;
reg [3:0] SEL_Cont;

// AUD_BCK Generator
always @ (posedge iCLK_18_4 or negedge iRST_N) begin
    if (!iRST_N) begin
        BCK_DIV <= 0;
        oAUD_BCK <= 0;
    end else begin
        if (BCK_DIV >= REF_CLK/(SAMPLE_RATE*DATA_WIDTH*CHANNEL_NUM*2)-1) begin
            BCK_DIV <= 0;
            oAUD_BCK <= ~oAUD_BCK;
        end else begin
            BCK_DIV <= BCK_DIV + 1;
        end
    end
end

// AUD_LRCK Generator
always @ (posedge iCLK_18_4 or negedge iRST_N) begin
    if (!iRST_N) begin
        LRCK_1X_DIV <= 0;
        LRCK_2X_DIV <= 0;
        LRCK_1X <= 0;
        LRCK_2X <= 0;
    end else begin
        // LRCK 1X
        if (LRCK_1X_DIV >= REF_CLK/(SAMPLE_RATE*2)-1) begin
            LRCK_1X_DIV <= 0;
            LRCK_1X <= ~LRCK_1X;
        end else begin
            LRCK_1X_DIV <= LRCK_1X_DIV + 1;
        end
        // LRCK 2X
        if (LRCK_2X_DIV >= REF_CLK/(SAMPLE_RATE*4)-1) begin
            LRCK_2X_DIV <= 0;
            LRCK_2X <= ~LRCK_2X;
        end else begin
            LRCK_2X_DIV <= LRCK_2X_DIV + 1;
        end
    end
end

// Read Signal Generator
always @ (posedge iCLK_18_4 or negedge iRST_N) begin
    if (!iRST_N) begin
        mDATA_RD <= 0;
    end else begin
        if (LRCK_1X_DIV == REF_CLK/(SAMPLE_RATE*2)-1) begin
            mDATA_RD <= 1;
        end else begin
            mDATA_RD <= 0;
        end
    end
end

// DATA Latch
always @ (posedge iCLK_18_4 or negedge iRST_N) begin
    if (!iRST_N) begin
        DATA_Out_Tmp <= 0;
    end else begin
        if (LRCK_2X_DIV == REF_CLK/(SAMPLE_RATE*4)-1) begin
            DATA_Out_Tmp <= mDATA;
        end
    end
end

always @ (posedge iCLK_18_4 or negedge iRST_N) begin
    if (!iRST_N) begin
        DATA_Out <= 0;
    end else begin
        if (LRCK_2X_DIV == REF_CLK/(SAMPLE_RATE*4)-3) begin
            DATA_Out <= DATA_Out_Tmp;
        end
    end
end

// 16 Bits PISO MSB First
always @ (negedge oAUD_BCK or negedge iRST_N) begin
    if (!iRST_N) begin
        SEL_Cont <= 0;
    end else begin
        SEL_Cont <= SEL_Cont + 1;
    end
end

assign oAUD_DATA = DATA_Out[~SEL_Cont];

