module fifo # (parameter abits = 5, dbits = 1)(
    input  reset, clock,
    input  rd, wr,
    input  [dbits-1:0] din,
    output [dbits-1:0] dout,
    output empty,
    output full
    );

wire db_wr, db_rd;
reg [dbits-1:0] out;
reg [dbits-1:0] regarray[2**abits-1:0];
reg [abits-1:0] wr_reg, wr_next, wr_succ;
reg [abits-1:0] rd_reg, rd_next, rd_succ;
reg full_reg, empty_reg, full_next, empty_next;

assign wr_en = db_wr & ~full;

always @ (posedge clock)
begin
    if (reset) begin
        wr_reg <= 0;
        rd_reg <= 0;
        full_reg <= 1'b0;
        empty_reg <= 1'b1;
    end else begin
        wr_reg <= wr_next;
        rd_reg <= rd_next;
        full_reg <= full_next;
        empty_reg <= empty_next;
    end
end

always @(*)
begin
    wr_succ = wr_reg + 1;
    rd_succ = rd_reg + 1;
    wr_next = wr_reg;
    rd_next = rd_reg;
    full_next = full_reg;
    empty_next = empty_reg;

    case ({db_wr, db_rd})
        2'b01: begin
            if (~empty) begin
                rd_next = rd_succ;
                full_next = 1'b0;
                if (rd_succ == wr_reg) begin
                    empty_next = 1'b1;
                end
            end
        end

        2'b10: begin
            if (~full) begin
                wr_next = wr_succ;
                empty_next = 1'b0;
                if (wr_succ == (2**abits-1)) begin
                    full_next = 1'b1;
                end
            end
        end

        2'b11: begin
            wr_next = wr_succ;
            rd_next = rd_succ;
        end
    endcase
end

always @ (posedge clock)
begin
    if (wr_en) begin
        regarray[wr_reg] <= din;
        out <= regarray[rd_reg];
    end
end

always @ (posedge clock)
begin
    if (db_rd) begin
        out <= regarray[rd_reg];
    end
end

assign full = full_reg;
assign empty = empty_reg;
assign dout = out;

assign db_wr = wr;
assign db_rd = rd;
endmodule

