module fifo # (parameter abits = 7, dbits = 1)(
    input  reset, clock,
    input  rd, wr,
    input  [dbits-1:0] din,
    output [dbits-1:0] dout,
    output empty,
    output full,
    output reg ledres
    );

wire db_wr, db_rd;
reg dffw1, dffw2, dffr1, dffr2;
reg [dbits-1:0] out;
reg [abits-1:0] wr_reg, wr_next, wr_succ; //points to the register that needs to be written to
reg [abits-1:0] rd_reg, rd_next, rd_succ; //points to the register that needs to be read from
reg full_reg, empty_reg, full_next, empty_next;
reg [dbits-1:0] regarray[2**abits-1:0]; //number of words in fifo = 2^(number of address bits)

//initial ledres = 0;

// Monostable multivibrator to detect only one pulse of the button for write enable
always @ (posedge clock) dffw1 <= wr; 
always @ (posedge clock) dffw2 <= dffw1;
assign db_wr = ~dffw1 & dffw2;

// Monostable multivibrator to detect only one pulse of the button for read enable
always @ (posedge clock) dffr1 <= rd;
always @ (posedge clock) dffr2 <= dffr1;
assign db_rd = ~dffr1 & dffr2;

// Write operation
always @ (posedge clock)
begin
    if (wr_en)
    begin
        regarray[wr_reg] <= din;
    end
end

// Read operation
always @ (posedge clock)
begin
    if (db_rd)
    begin
        out <= regarray[rd_reg];
    end
end

// Empty and full flag logic
always @(*)
begin
    if (rd_reg == wr_reg)
    begin
        empty_next = 1'b1;
        full_next = 1'b0;
    end
    else if (wr_succ == rd_reg)
    begin
        empty_next = 1'b0;
        full_next = 1'b1;
    end
    else
    begin
        empty_next = 1'b0;
        full_next = 1'b0;
    end
end

// Write and read pointer logic
always @(*)
begin
    wr_next = wr_reg;
    rd_next = rd_reg;
    if (db_wr && !full)
    begin
        wr_next = wr_succ;
    end
    if (db_rd && !empty)
    begin
        rd_next = rd_succ;
    end
    wr_succ = wr_reg + 1;
    rd_succ = rd_reg + 1;
end

// Full and empty flag and register update
always @ (posedge clock or posedge reset)
begin
    if (reset)
    begin
        wr_reg <= 0;
        rd_reg <= 0;
        full_reg <= 1'b0;
        empty_reg <= 1'b1;
        ledres = 0;
    end
    else
    begin
        wr_reg <= wr_next;
        rd_reg <= rd_next;
        full_reg <= full_next;
        empty_reg <= empty_next;
        ledres = 1;
    end
end

assign full = full_reg;
assign empty = empty_reg;
assign dout = out;

// Write enable condition
assign wr_en = db_wr && !full;

endmodule

module consecutive_zeros (
