reg stage4_out;

always @(posedge clk) begin
    stage1_out <= {stage1_out[2:0], in[0]};
end

always @(posedge clk) begin
    stage2_out <= {stage2_out[1:0], stage1_out[3]};
end

always @(posedge clk) begin
    stage3_out <= {stage3_out[0], stage2_out[2]};
end

always @(posedge clk) begin
    stage4_out <= stage3_out[1] & stage3_out[0];
end

always @(posedge clk) begin
    if (stage4_out == 1'b0) begin
        num_zeros <= 0;
    end else if (stage3_out[1] == 1'b0) begin
        num_zeros <= 1;
    end else if (stage2_out[2] == 1'b0) begin
        num_zeros <= 2;
    end else if (stage1_out[3] == 1'b0) begin
        num_zeros <= 3;
    end else begin
        num_zeros <= 4;
    end
end

endmodule

module byte_reverser (
    input [31:0] in_data, // 32-bit input data to be reversed
    output reg [31:0] out_data // 32-bit output data with reversed byte order
);

reg [7:0] shift_reg [3:0]; // 4 8-bit shift registers
reg [1:0] sel; // 2-bit select signal for multiplexers

always @(*) begin
    // Load input data into shift registers
    shift_reg[0] = in_data[7:0];
    shift_reg[1] = in_data[15:8];
    shift_reg[2] = in_data[23:16];
    shift_reg[3] = in_data[31:24];

    // Reverse byte order using multiplexers
    sel = 2'b00;
    out_data[7:0] = shift_reg[sel];
    sel = 2'b01;
    out_data[15:8] = shift_reg[sel];
    sel = 2'b10;
    out_data[23:16] = shift_reg[sel];
    sel = 2'b11;
    out_data[31:24] = shift_reg[sel];
end

endmodule

