module binary_comparator (
    input clk,
    input reset,        // Synchronous active-high reset
    input [7:0] a,      // First 8-bit input
    input [7:0] b,      // Second 8-bit input
    input add_sub_sel,  // Select input for addition or subtraction
    output reg out      // Output indicating whether inputs are equal
);

// Instantiate the adder and subtractor modules
adder add_inst(.a(a), .b(b), .cin(1'b0), .sum(sum_adder));
subtractor sub_inst(.a(a), .b(b), .cin(1'b1), .diff(diff_subtractor));

// FSM logic to control the select input of the adder and subtractor modules
always @(posedge clk) begin
    if (reset) begin
        add_sub_sel_reg <= 1'b0;
        state <= IDLE;
    end else begin
        case (state)
            IDLE: begin
                add_sub_sel_reg <= add_sub_sel;
                if (add_sub_sel) begin
                    state <= ADD;
                end else begin
                    state <= SUBTRACT;
                end
            end
            ADD: begin
                add_sub_sel_reg <= add_sub_sel;
                if (!add_sub_sel) begin
                    state <= SUBTRACT;
                end
            end
            SUBTRACT: begin
                add_sub_sel_reg <= add_sub_sel;
                if (add_sub_sel) begin
                    state <= ADD;
                end
            end
        endcase
    end
end

// Output indicating whether inputs are equal
always @(posedge clk) begin
    if (reset) begin
        out <= 1'b0;
    end else begin
        if (add_sub_sel_reg) begin
            out <= (a + b == 8'b00000000) ? 1'b1 : 1'b0;
        end else begin
            out <= (a == b) ? 1'b1 : 1'b0;
        end
    end
end

