module priority_encoder (
    input [7:0] in,
    output reg [2:0] pos
);

  wire [7:0] inv_in;
  NOT_gate not_gate_1 (.a(in), .out(inv_in));

  wire [7:0] complement;
  NOT_gate not_gate_2 (.a(inv_in), .out(complement));

  wire [2:0] and_out;
  AND_gate and_gate_1 (.a(inv_in[7:5]), .b(complement[7:5]), .out(and_out[2]));
  AND_gate and_gate_2 (.a(inv_in[4:2]), .b(complement[4:2]), .out(and_out[1]));
  AND_gate and_gate_3 (.a(inv_in[1:0]), .b(complement[1:0]), .out(and_out[0]));

  always @* begin
    if (and_out[2] == 1) begin
      pos = 3'b111;
    end else if (and_out[1] == 1) begin
      pos = 3'b110;
    end else if (and_out[0] == 1) begin
      pos = 3'b101;
    end else if (in[7] == 0) begin
      pos = 3'b100;
    end else if (in[6] == 0) begin
      pos = 3'b011;
    end else if (in[5] == 0) begin
      pos = 3'b010;
    end else if (in[4] == 0) begin
      pos = 3'b001;
    end else begin
      pos = 3'b000;
    end
  end

endmodule

module LCD_Controller (
    input [7:0] iDATA,
    input iRS,
    input iStart,
    input iCLK,
    input iRST_N,
    output reg oDone,
    output [7:0] LCD_DATA,
    output reg LCD_RW,
    output reg LCD_EN,
    output reg LCD_RS
);

parameter CLK_Divide = 16;

reg [4:0] Cont;
reg [1:0] ST;
reg preStart, mStart;

assign LCD_DATA = iDATA;
assign LCD_RW = 1'b0;
assign LCD_RS = iRS;

always @(posedge iCLK or negedge iRST_N) begin
    if (!iRST_N) begin
        oDone <= 1'b0;
        LCD_EN <= 1'b0;
        preStart <= 1'b0;
        mStart <= 1'b0;
        Cont <= 0;
        ST <= 0;
    end else begin
        preStart <= iStart;
        if ({preStart, iStart} == 2'b01) begin
            mStart <= 1'b1;
            oDone <= 1'b0;
        end
        if (mStart) begin
            case (ST)
                0: ST <= 1;
                1: begin
                    LCD_EN <= 1'b1;
                    ST <= 2;
                end
                2: begin
                    if (Cont < CLK_Divide) begin
                        Cont <= Cont + 1;
                    end else begin
                        ST <= 3;
                    end
                end
                3: begin
                    LCD_EN <= 1'b0;
                    mStart <= 1'b0;
                    oDone <= 1'b1;
                    Cont <= 0;
                    ST <= 0;
                end
            endcase
        end
    end
end

endmodule

