            $display("Test case 2 failed.");
            $finish;
        end

        // Test case 3: A = 1, B = 0
        A = 1;
        B = 0;
        #1;
        if (C !== 1) begin
            $display("Test case 3 failed.");
            $finish;
        end

        // Test case 4: A = 1, B = 1
        A = 1;
        B = 1;
        #1;
        if (C !== 0) begin
            $display("Test case 4 failed.");
            $finish;
        end

        $display("All test cases passed.");
        $finish;
    end

endmodule

