    $readmemh ("ROM_$F000-$FFFF_BYTE_1.spin", ram1, 15*1024);
    $readmemh ("ROM_$F000-$FFFF_BYTE_2.spin", ram2, 15*1024);
    $readmemh ("ROM_$F000-$FFFF_BYTE_3.spin", ram3, 15*1024);
end

always @(posedge clk_cog)
begin
    if (ena_bus && w && wb[3])
        ram3[a[13:0]] <= d[31:24];
    if (ena_bus)
        q[31:24] <= ram3[a[13:0]];
end

always @(posedge clk_cog)
begin
    if (ena_bus && w && wb[2])
        ram2[a[13:0]] <= d[23:16];
    if (ena_bus)
        q[23:16] <= ram2[a[13:0]];
end

always @(posedge clk_cog)
begin
    if (ena_bus && w && wb[1])
        ram1[a[13:0]] <= d[15:8];
    if (ena_bus)
        q[15:8] <= ram1[a[13:0]];
end

always @(posedge clk_cog)
begin
    if (ena_bus && w && wb[0])
        ram0[a[13:0]] <= d[7:0];
    if (ena_bus)
        q[7:0] <= ram0[a[13:0]];
end

endmodule

module fsm_3bit_pattern_detection (
  input clk,
  input reset,
  input [5:0] data,
  output reg match
);

  parameter S0 = 2'b00, S1 = 2'b01, S2 = 2'b10, S3 = 2'b11;
  reg [1:0] state, next_state;

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      state <= S0;
      match <= 1'b0;
    end
    else begin
      state <= next_state;
      match <= (state == S3);
    end
  end

  always @(*) begin
    case (state)
      S0: begin
        if (data[2:0] == 3'b001) next_state = S1;
        else next_state = S0;
      end
      S1: begin
        if (data[2:0] == 3'b010) next_state = S2;
        else next_state = S0;
      end
      S2: begin
        if (data[2:0] == 3'b100) next_state = S3;
        else next_state = S0;
      end
      S3: begin
        next_state = S0;
      end
    endcase
  end

endmodule

