module BRAMFIFO
#(
    parameter p1width = 32,
    parameter p2depth = 1024,
    parameter p3cntr_width = 10
)
(
    input CLK,
    input RST_N,
    input [p1width-1:0] D_IN,
    output [p1width-1:0] D_OUT,
    input ENQ,
    input DEQ,
    output EMPTY_N,
    output FULL_N,
    output [p3cntr_width-1:0] COUNT,
    input CLR
);

    // Declare the internal state variables
    reg [p3cntr_width-1:0] wptr, wptr_d, wptr_p1;
    reg [p3cntr_width-1:0] rptr, rptr_d, rptr_p1;
    reg [p3cntr_width-1:0] dcount, dcount_d;
    reg [p1width-1:0] mem [p2depth-1:0];
    reg [p1width-1:0] mem_d;
    reg [p1width-1:0] dout_r;
    reg inhibit, inhibit_d;
    reg mem_wen;
    reg nempty, nempty_d;
    reg nfull, nfull_d;

    // Synchronous reset
    always@(posedge CLK) begin
        if(RST_N && !CLR) begin
            wptr    <= wptr_d;
            rptr    <= rptr_d;
            nfull   <= nfull_d;
            nempty  <= nempty_d;
            inhibit <= inhibit_d;
            dcount  <= dcount_d;
            if(mem_wen) mem[wptr] <= D_IN;
        end
        else begin
            rptr    <= {p3cntr_width{1'b0}};
            wptr    <= {p3cntr_width{1'b0}};
            nfull   <= 1'b1;
            nempty  <= 1'b0;
            inhibit <= 1'b0;
            dcount  <= {p3cntr_width{1'b0}};
        end
    end

    // Combinational logic
    always@(*) begin
        wptr_d    = wptr;
        rptr_d    = rptr;
        nfull_d   = nfull;
        nempty_d  = nempty;
        mem_wen   = 1'b0;
        inhibit_d = 1'b0;
        wptr_p1   = (wptr + 1) % p2depth;
        rptr_p1   = (rptr + 1) % p2depth;
        dcount_d  = dcount;

        if(ENQ) begin
            wptr_d  = wptr_p1;
            mem_wen = 1'b1;
        end

        if(DEQ) begin
            rptr_d = rptr_p1;
        end

        if(ENQ && DEQ) begin
            nfull_d  = nfull;
            nempty_d = nempty;
            if(wptr == rptr) inhibit_d = 1'b1;
        end
        else if(DEQ && !ENQ) begin
            nfull_d  = 1'b1;
            nempty_d = rptr_p1 != wptr;
            dcount_d = dcount-1;
        end
        else if(ENQ && !DEQ) begin
            nfull_d  = wptr_p1 != rptr;
            nempty_d = 1'b1;
            dcount_d = dcount+1;
        end
    end

    // Assign outputs
    assign D_OUT = mem[rptr];
    assign EMPTY_N = nempty && !inhibit;
    assign FULL_N = nfull;
    assign COUNT = dcount;

    // Error checking (Synopsys translate off)
    always@(negedge CLK) begin
        if(RST_N) begin
            if(ENQ && !FULL_N) begin
                $display("ERROR, enqueuing to full BRAMFIFO");
                $finish(0);
            end

            if(DEQ && !EMPTY_N) begin
                $display("ERROR, dequeuing to empty BRAMFIFO");
                $finish(0);
            end
        end
    end
    // Synopsys translate on

endmodule

module Multiplexer_AC__1
   (ctrl,
    D0,
    D1,
    S);
  input ctrl;
  input [7:0]D0;
  input [7:0]D1;
  output [7:0]S;

  wire [7:0]S;

  // Implementing a 3-input LUT using a 2-input LUT
  // Truth table for 3-input LUT:
  // I2, I1, I0 | O
  // 0, 0, 0    | O0
  // 0, 0, 1    | O1
  // 0, 1, 0    | O2
  // 0, 1, 1    | O3
  // 1, 0, 0    | O4
  // 1, 0, 1    | O5
  // 1, 1, 0    | O6
  // 1, 1, 1    | O7

  // Implementing the first bit of the output signal (S[0])
  LUT2 #(.INIT(2'b01)) S0_LUT0 (.I0(D0[0]), .I1(D1[0]), .O(S[0]));
  LUT2 #(.INIT(2'b01)) S0_LUT1 (.I0(ctrl), .I1(ctrl), .O(S[0]));

  // Implementing the remaining bits of the output signal (S[1:7])
  LUT3 #(.INIT(8'hB8)) S_LUT0 (.I0(D1[0]), .I1(ctrl), .I2(D0[1]), .O(S[1]));
  LUT3 #(.INIT(8'hB8)) S_LUT1 (.I0(D1[1]), .I1(ctrl), .I2(D0[2]), .O(S[2]));
  LUT3 #(.INIT(8'hB8)) S_LUT2 (.I0(D1[2]), .I1(ctrl), .I2(D0[3]), .O(S[3]));
  LUT3 #(.INIT(8'hB8)) S_LUT3 (.I0(D1[3]), .I1(ctrl), .I2(D0[4]), .O(S[4]));
  LUT3 #(.INIT(8'hB8)) S_LUT4 (.I0(D1[4]), .I1(ctrl), .I2(D0[5]), .O(S[5]));
  LUT3 #(.INIT(8'hB8)) S_LUT5 (.I0(D1[5]), .I1(ctrl), .I2(D0[6]), .O(S[6]));
  LUT3 #(.INIT(8'hB8)) S_LUT6 (.I0(D1[6]), .I1(ctrl), .I2(D0[7]), .O(S[7]));
  LUT2 #(.INIT(2'b01)) S7_LUT7 (.I0(D1[7]), .I1(D1[7]), .O(S[7]));

endmodule

