module out_ctrl (
    clk     ,   // I, clock
    nrst    ,   // I, async reset
    start   ,   // I, start
    vin     ,   // I, write enable
    din     ,   // I, write data
    vout    ,   // O, read enable
    dout    ,   // O, read data
    idx_out     // O, out index
    ) ;

input           clk ;
input           nrst ;
input           start ;
input           vin ;
input   [7:0]   din ;
output          vout ;
output  [7:0]   dout ;
output  [13:0]  idx_out ;

reg             en ;
wire            ff_empty ;
wire            ff_rd ;
wire    [7:0]   ff_rdata ;
reg     [7:0]   data_lat ;
reg             ff_rd_d ;
reg             ff_rd_dd ;
reg     [13:0]  cnt ;

//============================
// Main RTL Code
//============================
assign vout = ff_rd_d | ff_rd_dd ;
assign dout = data_lat ;
assign idx_out = cnt ;

always @(posedge clk or negedge nrst)
  if(~nrst)
    en <= 1'b1 ;
  else if (start)
    en <= 1'b1 ;
  else
    en <= ~en ;

assign ff_rd = ~ff_empty & en ;

fifo_16x8 fifo_16x8 (
    .clk    (clk        ),
    .nrst   (nrst       ),
    .reset  (start      ),
    .wr     (vin        ),
    .wdata  (din        ),
    .rd     (ff_rd      ),
    .rdata  (ff_rdata   ),
    .empty  (ff_empty   ),
    .full   (           )
    ) ;

always @(posedge clk or negedge nrst)
  if(~nrst)
    data_lat <= 0 ;
  else if (ff_rd)
    data_lat <= ff_rdata ;

always @(posedge clk or negedge nrst)
  if(~nrst)
  begin
    ff_rd_d <= 1'b0 ;
    ff_rd_dd <= 1'b0 ;
  end
  else if (start)
  begin
    ff_rd_dd <= 1'b0 ;
    ff_rd_d <= 1'b0 ;
    cnt <= 0 ;
  end
  else
  begin
    ff_rd_dd <= ff_rd_d ;
    ff_rd_d <= ff_rd ;
    if (ff_rd_dd)
      cnt <= cnt +1 ;
  end

endmodule

module fifo_buffer (
    input clk,
    input reset,
    output reg if_empty_n,
    input if_read_ce,
    input if_read,
    output reg [7:0] if_dout,
    output reg if_full_n,
    input if_write_ce,
    input if_write,
    input [7:0] if_din
);

parameter ADDR_WIDTH = 1;
parameter DEPTH = 2;

reg [ADDR_WIDTH:0] wr_ptr = 0;
reg [ADDR_WIDTH:0] rd_ptr = 0;
reg [7:0] mem [0:DEPTH-1];
reg [ADDR_WIDTH:0] count = 0;

assign if_empty_n = (count > 0);
assign if_full_n = (count < DEPTH);

always @(posedge clk) begin
    if (reset == 1) begin
        wr_ptr <= 0;
        rd_ptr <= 0;
        count <= 0;
        if_empty_n <= 0;
        if_full_n <= 1;
    end else begin
        if (if_write & if_write_ce & if_full_n) begin
            mem[wr_ptr] <= if_din;
            wr_ptr <= wr_ptr + 1;
            count <= count + 1;
            if (wr_ptr == DEPTH) begin
                wr_ptr <= 0;
            end
        end
        if (if_read & if_read_ce & if_empty_n) begin
            if_dout <= mem[rd_ptr];
            rd_ptr <= rd_ptr + 1;
            count <= count - 1;
            if (rd_ptr == DEPTH) begin
                rd_ptr <= 0;
            end
        end
        if_empty_n <= (count > 0);
        if_full_n <= (count < DEPTH);
    end
end

endmodule

module wallace_multiplier (
    input signed [7:0] a,
    input signed [7:0] b,
    input signed_ctrl,
    output signed [15:0] result
);

// Break the inputs into four 4-bit sections
wire signed [3:0] a0 = a[3:0];
wire signed [3:0] a1 = a[7:4];
wire signed [3:0] b0 = b[3:0];
wire signed [3:0] b1 = b[7:4];

// Generate partial products for each section using Wallace tree multiplier algorithm
wire signed [7:0] pp00 = a0 * b0;
wire signed [8:0] pp01 = {a0,1'b0} * {b1,1'b0};
wire signed [8:0] pp10 = {a1,1'b0} * {b0,1'b0};
wire signed [9:0] pp11 = {a1,1'b0,1'b0} * {b1,1'b0,1'b0};

// Functional module to combine partial products and generate final result
wallace_sum sum0(pp00, pp01[7:4], pp10[7:4]);
wallace_sum sum1(pp01[3:0], pp10[3:0], pp11[7:4]);
wallace_sum sum2(pp11[3:0], 4'b0, 4'b0);

// Output result based on signed or unsigned multiplication
assign result = (signed_ctrl) ? {$signed(sum2.sum), sum1.sum, sum0.sum} : (a[7] & b[7]) ? {$signed(sum2.sum), sum1.sum, sum0.sum} : (a[7] | b[7]) ? -{$unsigned(sum2.sum), sum1.sum, sum0.sum} : {$unsigned(sum2.sum), sum1.sum, sum0.sum};

endmodule

// Functional module to generate 5-bit sum and 4-bit carry out
module wallace_sum (
    input signed [3:0] a,
    input signed [3:0] b,
    output signed [4:0] sum
);

wire signed [3:0] p = a * b;
wire signed [4:0] g = {p[7:4], p[6:3], p[5:2], p[4:1], p[3:0]};
wire signed [4:0] h = {g[4], g[3] ^ g[0], g[2] ^ g[1], g[1], g[0]};
assign sum = h[4:0];

endmodule

