module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] d,    // 8-bit input for the XOR circuit
    input select,     // Select input to choose between counter and XOR circuit
    output [3:0] counter_out,    // 4-bit output from the counter
    output [7:0] xor_out         // 8-bit output from the XOR circuit
);

    // Define the state machine states
    parameter S_IDLE = 2'b00;
    parameter S_COUNT = 2'b01;
    parameter S_XOR = 2'b10;

    // Define the counter and XOR circuit output wires
    wire [3:0] counter;
    wire [7:0] xor;

    // Define the state machine signals
    reg [1:0] state;
    reg [3:0] count;

    // Define the control logic to choose between counter and XOR circuit
    assign counter_out = (select) ? counter : 4'b0;
    assign xor_out = (select) ? 8'b0 : xor;

    // Define the counter module
    counter_module counter_inst (
        .clk(clk),
        .reset(reset),
        .count(count),
        .out(counter)
    );

    // Define the XOR circuit module
    xor_module xor_inst (
        .a(counter),
        .b(d),
        .out(xor)
    );

    // Define the state machine
    always @(posedge clk) begin
        if (reset) begin
            state <= S_IDLE;
            count <= 4'b0;
        end else begin
            case (state)
                S_IDLE: begin
                    if (select) begin
                        state <= S_COUNT;
                    end else begin
                        state <= S_XOR;
                    end
                end
                S_COUNT: begin
                    count <= count + 1;
                    if (count == 4'b1111) begin
                        state <= S_IDLE;
                    end
                end
                S_XOR: begin
                    state <= S_IDLE;
                end
            endcase
        end
    end

endmodule

// Define the counter module
module counter_module (
    input clk,
    input reset,      // Synchronous active-high reset
    output reg [3:0] count,    // 4-bit counter output
    output reg [3:0] out       // 4-bit output from the counter
);

    always @(posedge clk) begin
        if (reset) begin
            count <= 4'b0;
            out <= 4'b0;
        end else begin
            count <= count + 1;
            out <= count;
        end
    end

endmodule

// Define the XOR circuit module
module xor_module (
    input [3:0] a,    // 4-bit input for the XOR circuit
    input [7:0] b,    // 8-bit input for the XOR circuit
    output reg [7:0] out   // 8-bit output from the XOR circuit
);

    always @(a, b) begin
        out <= a ^ b;
    end

endmodule

module top_module (
    input clk,
    input reset_shift, // Active high synchronous reset for shift register
    input reset_flipflop, // Active low asynchronous reset for D flip-flop
    input [7:0] in,
    output [7:0] anyedge,
    output reg [3:0] num_edges // 4-bit binary number output from functional module
);

reg [7:0] shift_reg;
reg [7:0] delayed_reg;
reg [7:0] edge_detect;
reg [7:0] edge_detect_delayed;
reg rising_edge_detected;

always @(posedge clk) begin
    if (reset_shift) begin
        shift_reg <= 8'b0;
        delayed_reg <= 8'b0;
        edge_detect <= 8'b0;
        edge_detect_delayed <= 8'b0;
        rising_edge_detected <= 1'b0;
    end else begin
        shift_reg <= {in, shift_reg[7:1]};
        delayed_reg <= shift_reg;
        edge_detect <= shift_reg ^ delayed_reg;
        edge_detect_delayed <= {edge_detect[6:0], 1'b0};
        rising_edge_detected <= edge_detect_delayed[7];
    end
end

reg [7:0] flipflop_input;
reg [7:0] flipflop_output;

always @(posedge clk or negedge reset_flipflop) begin
    if (!reset_flipflop) begin
        flipflop_input <= 8'b0;
        flipflop_output <= 8'b0;
    end else begin
        flipflop_input <= {rising_edge_detected, flipflop_input[7:1]};
        flipflop_output <= flipflop_input;
    end
end

assign anyedge = flipflop_output;

reg [3:0] edge_count;

always @(posedge clk) begin
    if (reset_shift) begin
        edge_count <= 4'b0;
    end else if (rising_edge_detected) begin
        edge_count <= edge_count + 1;
    end
end

always @(posedge clk) begin
    if (reset_shift) begin
        num_edges <= 4'b0;
    end else begin
        num_edges <= edge_count;
    end
end

endmodule

module logic_function (
    input [3:0] A,
    input [3:0] B,
    output reg X,
    output reg Y
);

always @* begin
    if (A[0] & B[0] & A[1] & B[1])
        X = 1;
    else
        X = 0;

    if (A[2] & B[2] & A[3] & B[3])
        Y = 1;
    else
        Y = 0;
end

endmodule

module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    output [3:0] S,
    output C_OUT
);

wire [3:0] C;

assign S = A + B + C;

assign C_OUT = (A[3] & B[3]) | (A[3] & C[2]) | (B[3] & C[2]);

endmodule

module functional_module (
    input [3:0] A,
    input [3:0] B,
    input [3:0] S,
    input C_OUT,
    input X,
    input Y,
    output [3:0] final_output
);

wire [3:0] and_output;

assign and_output = A & B;

always @* begin
    if (X == 1)
        final_output = S + C_OUT;
    else
        final_output = and_output;

    if (Y == 1)
        final_output = final_output + C_OUT;
    else
        final_output = final_output + (A & B);
end

endmodule

