module CDR (
  input data_in,
  input clk_in,
  output data_out
);

  // Define sub-modules
  phase_detector pd(clk_in, data_in, phase_error);
  loop_filter lf(phase_error, correction_signal);
  VCO vco(correction_signal, clk_out);

  // Internal signals
  wire phase_error;
  wire correction_signal;
  wire clk_out;

  // Use recovered clock to sample data
  reg data_sampled;
  always @(posedge clk_in) begin
    data_sampled <= data_in;
  end

  // Use new clock to sample data again
  reg data_sampled2;
  always @(posedge clk_out) begin
    data_sampled2 <= data_in;
  end

  // Connect sub-modules in correct order
  assign data_out = data_sampled2;
  assign vco.clk_out = clk_out;
  assign lf.correction_signal = correction_signal;
  assign pd.phase_error = phase_error;

endmodule

