module TDC (
  input signalA,
  input signalB,
  input clk,
  output reg [resolution-1:0] time_diff
);

parameter resolution = 8; // number of bits in the output code
parameter clock_period = 10; // period of the clock signal in nanoseconds

reg [31:0] phaseA;
reg [31:0] phaseB;
reg [31:0] time_diff_ns;

always @(posedge clk) begin
  phaseA <= phaseA + 1;
  phaseB <= phaseB + 1;

  if (signalA && !signalB) begin
    time_diff_ns <= phaseA - phaseB;
  end else if (!signalA && signalB) begin
    time_diff_ns <= phaseB - phaseA;
  end
end

always @(posedge clk) begin
  time_diff <= $floor((time_diff_ns * 1.0) / (clock_period * 1.0) * (2 ** resolution));
end

endmodule

