module dcfifo_32in_32out_16kb(
  input rst,
  input wr_clk,
  input rd_clk,
  input [31:0]din,
  input wr_en,
  input rd_en,
  output [31:0]dout,
  output full,
  output empty,
  output [0:0]wr_data_count
);

  // Define FIFO parameters
  parameter WIDTH = 32; // Data width
  parameter DEPTH = 512; // Depth of FIFO (in 32-bit words)
  parameter ADDR_WIDTH = $clog2(DEPTH); // Address width
  parameter COUNT_WIDTH = $clog2(DEPTH+1); // Write data count width

  // Define FIFO memory
  reg [WIDTH-1:0] mem [0:DEPTH-1];
  reg [ADDR_WIDTH-1:0] wr_ptr;
  reg [ADDR_WIDTH-1:0] rd_ptr;
  reg [COUNT_WIDTH-1:0] wr_data_count_reg;
  wire [COUNT_WIDTH-1:0] wr_data_count_next;
  reg full_reg;
  wire empty;

  // Combinational logic for write data count
  assign wr_data_count = wr_data_count_reg;

  // Combinational logic for empty
  assign empty = (wr_ptr == rd_ptr) ? 1'b1 : 1'b0;

  // Sequential logic for write data count
  always @(posedge wr_clk) begin
    wr_data_count_reg <= wr_data_count_next;
  end

  // Sequential logic for FIFO write operation
  always @(posedge wr_clk) begin
    if (rst) begin
      wr_ptr <= 0;
      full_reg <= 1'b0;
      wr_data_count_reg <= 0;
    end else if (wr_en && !full_reg) begin
      mem[wr_ptr] <= din;
      wr_ptr <= wr_ptr + 1;
      wr_data_count_next <= wr_data_count_reg + 1;
      if (wr_ptr == rd_ptr) begin
        full_reg <= 1'b1;
      end
    end else begin
      wr_data_count_next <= wr_data_count_reg;
    end
  end

  // Sequential logic for FIFO read operation
  always @(posedge rd_clk) begin
    if (rst) begin
      rd_ptr <= 0;
      full_reg <= 1'b0;
      wr_data_count_reg <= 0;
    end else if (rd_en && !empty) begin
      dout <= mem[rd_ptr];
      rd_ptr <= rd_ptr + 1;
      full_reg <= 1'b0;
    end
  end

  // Output full and empty signals
  assign full = full_reg;

endmodule

module top_module (
    input clk,
    input reset,
    input [3:0] a,
    input [3:0] b,
    output [3:0] d,
    output borrow
);

    wire [3:0] sum;
    wire carry_out;
    wire [3:0] cmp_out;

    adder_module adder_inst(
        .clk(clk),
        .reset(reset),
        .a(a),
        .b(b),
        .sum(sum),
        .carry_out(carry_out)
    );

    comparator_module cmp_inst(
        .a(a),
        .b(b),
        .out(cmp_out)
    );

    difference_module diff_inst(
        .a(a),
        .b(b),
        .sum(sum),
        .borrow(borrow),
        .d(d),
        .cmp_out(cmp_out)
    );

endmodule

module adder_module (
    input clk,
    input reset,
    input [3:0] a,
    input [3:0] b,
    output [3:0] sum,
    output carry_out
);

    reg [3:0] sum_reg;
    reg carry_out_reg;

    always @(posedge clk) begin
        if (reset) begin
            sum_reg <= 4'b0;
            carry_out_reg <= 1'b0;
        end else begin
            {carry_out_reg, sum_reg} <= a + b + carry_out_reg;
        end
    end

    assign sum = sum_reg;
    assign carry_out = carry_out_reg;

endmodule

module comparator_module (
    input [3:0] a,
    input [3:0] b,
    output [3:0] out
);

    assign out = (a > b) ? 4'b0010 : (a < b) ? 4'b0001 : 4'b0000;

endmodule

module difference_module (
    input [3:0] a,
    input [3:0] b,
    input [3:0] sum,
    output borrow,
    output [3:0] d,
    input [3:0] cmp_out
);

    assign borrow = (a[3] >= b[3]) & (d[3] < a[3]);
    assign d = (cmp_out[3] == 1'b1) ? ~sum + 1 : sum;

endmodule

module counter_load_dbus(
  clk, rst, clk_ena,
  load,
  dfload,
  carry,
  count
);
  parameter MOD_COUNT = 7;
  parameter WIDTH = 8;

  input clk, rst, clk_ena, load;
  input [WIDTH-1:0] dfload;
  output carry;
  output [WIDTH-1:0] count;

  reg carry_tmp;
  reg [WIDTH-1:0] count_r;

  assign carry = carry_tmp;
  assign count = count_r;

  always @(posedge clk or posedge rst) begin
    if(rst)
      count_r <= 0;
    else if(clk_ena)
      if(load)
        count_r <= dfload;
      else
        count_r <= count_r+1;
  end

  always @(count_r) begin
    if(count_r == MOD_COUNT-1)
      carry_tmp = 1'b1;
    else 
      carry_tmp = 1'b0;
  end
endmodule

module top_module (
    input [3:0] in, // Input for priority encoder
    input wire [15:0] in_shift, // Input for barrel shifter
    output wire [7:0] out // Output from selected 8 bits
);

    wire [1:0] pos; // Output from priority encoder
    wire [15:0] shift_out; // Output from barrel shifter
    wire [7:0] selected_out; // Output selected based on priority encoder output

    priority_encoder pe(
        .in(in),
        .pos(pos)
    );

    barrel_shifter bs(
        .in(in_shift),
        .out(shift_out)
    );

    select_logic sl(
        .pos(pos),
        .in_shift(shift_out),
        .out(selected_out)
    );

    assign out = selected_out;

endmodule

module priority_encoder (
    input [3:0] in,
    output reg [1:0] pos
);
    always @* begin
        case (in)
            4'b0001: pos = 2'b00;
            4'b0010: pos = 2'b01;
            4'b0100: pos = 2'b10;
            4'b1000: pos = 2'b11;
            default: pos = 2'b00;
        endcase
    end
endmodule

module barrel_shifter (
    input wire [15:0] in,
    output wire [15:0] out
);
    assign out = in << 1; // Example shift operation
endmodule

module select_logic (
    input [1:0] pos,
    input wire [15:0] in_shift,
    output wire [7:0] out
);
    assign out = (pos != 2'b00) ? in_shift[15:8] : in_shift[7:0];
endmodule

