module shift_register (
   input clk,
   input rst,
   input [31:0] data_in,
   input [31:0] shift_amt,
   output [31:0] data_out
);

reg [31:0] shift_reg;

always @(posedge clk) begin
   if (rst) begin
      shift_reg <= 0;
   end else begin
      if (shift_amt > 0) begin
         shift_reg <= {shift_reg[shift_amt-1:0], data_in};
      end else if (shift_amt < 0) begin
         shift_reg <= {data_in, shift_reg[31+shift_amt:0]};
      end else begin
         shift_reg <= data_in;
      end
   end
end

assign data_out = shift_reg;

endmodule

