module axi_gpio(s_axi_aclk, s_axi_aresetn, s_axi_awaddr, s_axi_awvalid, s_axi_wdata, s_axi_wstrb, s_axi_wvalid, s_axi_bready, s_axi_araddr, s_axi_arvalid, s_axi_rready, s_axi_awready, s_axi_wready, s_axi_bresp, s_axi_bvalid, s_axi_arready, s_axi_rdata, s_axi_rresp, s_axi_rvalid, gpio_io_o);
    parameter GPIO_ADDR = 32'h00000000; // Address of the GPIO pins in memory map
    parameter GPIO_SIZE = 8; // Number of GPIO pins

    input s_axi_aclk;
    input s_axi_aresetn;
    input [31:0] s_axi_awaddr;
    input s_axi_awvalid;
    input [31:0] s_axi_wdata;
    input [3:0] s_axi_wstrb;
    input s_axi_wvalid;
    output s_axi_bready;
    input [31:0] s_axi_araddr;
    input s_axi_arvalid;
    output s_axi_rready;
    output s_axi_awready;
    output s_axi_wready;
    output [1:0] s_axi_bresp;
    output s_axi_bvalid;
    output s_axi_arready;
    output [31:0] s_axi_rdata;
    output [1:0] s_axi_rresp;
    output s_axi_rvalid;
    output reg [7:0] gpio_io_o;

    reg [31:0] address;
    reg [31:0] data;
    reg [2:0] state;
    reg [2:0] next_state;

    // State machine states
    localparam IDLE = 3'd0;
    localparam WRITE_ADDR = 3'd1;
    localparam WRITE_DATA = 3'd2;
    localparam READ_ADDR = 3'd3;
    localparam READ_DATA = 3'd4;

    always @(posedge s_axi_aclk) begin
        if (!s_axi_aresetn) begin
            state <= IDLE;
            gpio_io_o <= 8'b0;
            s_axi_awready <= 1'b0;
            s_axi_wready <= 1'b0;
            s_axi_bvalid <= 1'b0;
            s_axi_arready <= 1'b0;
            s_axi_rdata <= 32'h0;
            s_axi_rresp <= 2'b0;
            s_axi_rvalid <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (s_axi_awvalid && s_axi_wvalid) begin
                        address <= s_axi_awaddr;
                        data <= s_axi_wdata;
                        state <= WRITE_ADDR;
                    end else if (s_axi_arvalid) begin
                        address <= s_axi_araddr;
                        state <= READ_ADDR;
                    end
                end
                WRITE_ADDR: begin
                    s_axi_awready <= 1'b1;
                    if (s_axi_awvalid && s_axi_wvalid && s_axi_awready && s_axi_wready) begin
                        state <= WRITE_DATA;
                    end
                end
                WRITE_DATA: begin
                    s_axi_wready <= 1'b1;
                    if (s_axi_awvalid && s_axi_wvalid && s_axi_awready && s_axi_wready) begin
                        case (s_axi_wstrb)
                            4'b0001: gpio_io_o[0] <= data[0];
                            4'b0010: gpio_io_o[1] <= data[0];
                            4'b0100: gpio_io_o[2] <= data[0];
                            4'b1000: gpio_io_o[3] <= data[0];
                            4'b0011: gpio_io_o[1:0] <= data[1:0];
                            4'b0110: gpio_io_o[2:1] <= data[1:0];
                            4'b1100: gpio_io_o[3:2] <= data[1:0];
                            4'b1111: gpio_io_o <= data[3:0];
                        endcase
                        s_axi_bresp <= 2'b0;
                        s_axi_bvalid <= 1'b1;
                        state <= IDLE;
                    end
                end
                READ_ADDR: begin
                    s_axi_arready <= 1'b1;
                    if (s_axi_arvalid && s_axi_arready) begin
                        state <= READ_DATA;
                    end
                end
                READ_DATA: begin
                    s_axi_rdata <= {24'h0, gpio_io_o};
                    s_axi_rresp <= 2'b0;
                    s_axi_rvalid <= 1'b1;
                    if (s_axi_rvalid && s_axi_rready) begin
                        state <= IDLE;
                    end
                end
            endcase
        end
    end
endmodule

module bmutb;
    wire [1:0] bm;
    reg  cx0, cx1;

    bmu bmu1 (cx0, cx1, bm);

