module FSM (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 4; // number of input signals
parameter m = 2; // number of output signals
parameter s_orig = "binary"; // original state encoding
parameter s_new = "one-hot"; // new state encoding

// Define the states using the original state encoding
parameter STATE_A = 2'b00;
parameter STATE_B = 2'b01;
parameter STATE_C = 2'b10;
parameter STATE_D = 2'b11;

// Define the Boolean functions for the state transitions
// based on the input signals
assign next_state = (current_state == STATE_A && in[0]) ? STATE_B :
                    (current_state == STATE_A && !in[0]) ? STATE_C :
                    (current_state == STATE_B && in[1]) ? STATE_D :
                    (current_state == STATE_B && !in[1]) ? STATE_A :
                    (current_state == STATE_C && in[2]) ? STATE_A :
                    (current_state == STATE_C && !in[2]) ? STATE_D :
                    (current_state == STATE_D && in[3]) ? STATE_C :
                    (current_state == STATE_D && !in[3]) ? STATE_B :
                    current_state;

// Define the outputs based on the current state and the new state encoding
always @ (current_state) begin
  case (current_state)
    STATE_A: out = {s_new == "one-hot" ? 1'b1 : 2'b01, s_new == "one-hot" ? 1'b0 : 2'b10};
    STATE_B: out = {s_new == "one-hot" ? 1'b0 : 2'b10, s_new == "one-hot" ? 1'b1 : 2'b01};
    STATE_C: out = {s_new == "one-hot" ? 1'b1 : 2'b10, s_new == "one-hot" ? 1'b1 : 2'b10};
    STATE_D: out = {s_new == "one-hot" ? 1'b0 : 2'b10, s_new == "one-hot" ? 1'b0 : 2'b10};
  endcase
end

// Define the state register and the next state logic
reg [1:0] current_state, next_state;
always @ (posedge clk) begin
  current_state <= next_state;
end

endmodule

module mag_comp_3bit (
  input [2:0] A,
  input [2:0] B,
  input [1:0] sel,
  output reg [1:0] out
);

  reg [2:0] selA;
  reg [2:0] selB;

  always @* begin
    case(sel)
      2'b00: begin
        selA = A[0];
        selB = B[0];
      end
      2'b01: begin
        selA = A[1];
        selB = B[1];
      end
      2'b10: begin
        selA = A[2];
        selB = B[2];
      end
      2'b11: begin
        selA = 3'b0;
        selB = 3'b0;
      end
    endcase

    if(sel == 2'b11) begin
      out = 2'b11;
    end
    else if(selA > selB) begin
      out = 2'b10;
    end
    else if(selA < selB) begin
      out = 2'b01;
    end
    else begin
      out = 2'b00;
    end
  end

endmodule

