    // Signed Magnitude Comparator
    always @* begin
        if (A[3] == 1 && B[3] == 0) begin
            cmp_out = 0;
        end else if (A[3] == 0 && B[3] == 1) begin
            cmp_out = 1;
        end else if (A >= B) begin
            cmp_out = 1;
        end else begin
            cmp_out = 0;
        end
    end

    // 16-bit Counter
    always @(posedge clk) begin
        if (reset) begin
            count <= 0;
        end else if (cmp_out) begin
            count <= count + 1;
        end
    end

