module booth_multiplier (
    input [3:0] A,
    input [3:0] B,
    output reg [7:0] product
);

reg [3:0] A_reg;
reg [3:0] B_reg;
reg [2:0] counter;
reg [1:0] state;

always @(*) begin
    A_reg = A;
    B_reg = B;
    counter = 4'd0;
    state = 2'd0;
    product = 8'd0;
end

always @(posedge clk) begin
    case (state)
        2'd0: begin // State 0
            if (B_reg[0] == 1) begin
                product = product + (A_reg << counter);
            end
            state = 2'd1;
        end
        2'd1: begin // State 1
            if (B_reg[0] == 0 && B_reg[1] == 1) begin
                product = product + (A_reg << counter);
            end
            counter = counter + 1;
            state = 2'd2;
        end
        2'd2: begin // State 2
            if (B_reg[1] == 0 && B_reg[0] == 1) begin
                product = product - (A_reg << counter);
            end
            if (B_reg[1] == 1 && B_reg[0] == 0) begin
                product = product + (A_reg << counter);
            end
            counter = counter + 1;
            state = 2'd3;
        end
        2'd3: begin // State 3
            if (B_reg[1:0] == 2'b10) begin
                product = product - (A_reg << counter);
            end
            state = 2'd0;
            B_reg = {1'b0, B_reg[3:1]};
        end
    endcase
end

endmodule

// Barrel Shifter Module
module barrel_shifter (
    input [7:0] data_in,
    input [1:0] shift_amount,
    input shift_dir,
    output [7:0] data_out
);

reg [7:0] data_reg;

always @(*) begin
    data_reg = data_in;
end

always @(posedge clk) begin
    if (shift_dir == 1'b0) begin // Shift Right
        data_reg = data_in >> shift_amount;
    end else begin // Shift Left
        data_reg = data_in << shift_amount;
    end
end

assign data_out = data_reg;

endmodule

module pulse_height_analyzer #
(
  parameter integer AXIS_TDATA_WIDTH = 16,
  parameter         AXIS_TDATA_SIGNED = "FALSE",
  parameter integer CNTR_WIDTH = 16
)
(
  // System signals
  input  wire                           aclk,
  input  wire                           aresetn,

  input  wire                           bln_flag,
  input  wire [AXIS_TDATA_WIDTH-1:0]    bln_data,
  input  wire [CNTR_WIDTH-1:0]          cfg_data,
  input  wire [AXIS_TDATA_WIDTH-1:0]    min_data,
  input  wire [AXIS_TDATA_WIDTH-1:0]    max_data,

  // Slave side
  output wire                           s_axis_tready,
  input  wire [AXIS_TDATA_WIDTH-1:0]    s_axis_tdata,
  input  wire                           s_axis_tvalid,

  // Master side
  input  wire                           m_axis_tready,
  output wire [AXIS_TDATA_WIDTH-1:0]    m_axis_tdata,
  output wire                           m_axis_tvalid
);
  reg [AXIS_TDATA_WIDTH-1:0] int_data_reg[1:0], int_data_next[1:0];
  reg [AXIS_TDATA_WIDTH-1:0] int_min_reg, int_min_next;
  reg [AXIS_TDATA_WIDTH-1:0] int_tdata_reg, int_tdata_next;
  reg [CNTR_WIDTH-1:0] int_cntr_reg, int_cntr_next;
  reg int_enbl_reg, int_enbl_next;
  reg int_rising_reg, int_rising_next;
  reg int_tvalid_reg, int_tvalid_next;

  wire [AXIS_TDATA_WIDTH-1:0] int_tdata_wire, int_min_wire;
  wire int_mincut_wire, int_maxcut_wire, int_rising_wire, int_delay_wire;

  assign int_delay_wire = int_cntr_reg < cfg_data;
  assign int_min_wire = bln_flag ? int_min_reg : bln_data;

  generate
    if(AXIS_TDATA_SIGNED == "TRUE")
    begin : SIGNED
      assign int_rising_wire = $signed(int_data_reg[1]) < $signed(s_axis_tdata);
      assign int_tdata_wire = $signed(int_data_reg[0]) - $signed(int_min_wire);
      assign int_mincut_wire = $signed(int_tdata_wire) > $signed(min_data);
      assign int_maxcut_wire = $signed(int_data_reg[0]) < $signed(max_data);
    end
    else
    begin : UNSIGNED
      assign int_rising_wire = int_data_reg[1] < s_axis_tdata;
      assign int_tdata_wire = int_data_reg[0] - int_min_wire;
      assign int_mincut_wire = int_tdata_wire > min_data;
      assign int_maxcut_wire = int_data_reg[0] < max_data;
    end
  endgenerate

  always @(posedge aclk)
  begin
    if(~aresetn)
    begin
      int_data_reg[0] <= {(AXIS_TDATA_WIDTH){1'b0}};
      int_data_reg[1] <= {(AXIS_TDATA_WIDTH){1'b0}};
      int_tdata_reg <= {(AXIS_TDATA_WIDTH){1'b0}};
      int_min_reg <= {(AXIS_TDATA_WIDTH){1'b0}};
      int_cntr_reg <= {(CNTR_WIDTH){1'b0}};
      int_enbl_reg <= 1'b0;
      int_rising_reg <= 1'b0;
      int_tvalid_reg <= 1'b0;
    end
    else
    begin
      int_data_reg[0] <= int_data_next[0];
      int_data_reg[1] <= int_data_next[1];
      int_tdata_reg <= int_tdata_next;
      int_min_reg <= int_min_next;
      int_cntr_reg <= int_cntr_next;
      int_enbl_reg <= int_enbl_next;
      int_rising_reg <= int_rising_next;
      int_tvalid_reg <= int_tvalid_next;
    end
  end

  always @*
  begin
    int_data_next[0] = int_data_reg[0];
    int_data_next[1] = int_data_reg[1];
    int_tdata_next = int_tdata_reg;
    int_min_next = int_min_reg;
    int_cntr_next = int_cntr_reg;
    int_enbl_next = int_enbl_reg;
    int_rising_next = int_rising_reg;
    int_tvalid_next = int_tvalid_reg;

    if(s_axis_tvalid)
    begin
      int_data_next[0] = s_axis_tdata;
      int_data_next[1] = int_data_reg[0];
      int_rising_next = int_rising_wire;
    end

    if(s_axis_tvalid & int_delay_wire)
    begin
      int_cntr_next = int_cntr_reg + 1'b1;
    end

    // minimum after delay
    if(s_axis_tvalid & ~int_delay_wire & ~int_rising_reg & int_rising_wire)
    begin
      int_min_next = int_data_reg[1];
      int_enbl_next = 1'b1;
    end

    // maximum after minimum
    if(s_axis_tvalid & int_enbl_reg & int_rising_reg & ~int_rising_wire & int_mincut_wire)
    begin
      int_tdata_next = int_maxcut_wire ? int_tdata_wire : {(AXIS_TDATA_WIDTH){1'b0}};
      int_tvalid_next = int_maxcut_wire;
      int_cntr_next = {(CNTR_WIDTH){1'b0}};
      int_enbl_next = 1'b0;
    end

    if(m_axis_tready & int_tvalid_reg)
    begin
      int_tdata_next = {(AXIS_TDATA_WIDTH){1'b0}};
      int_tvalid_next = 1'b0;
    end
  end

  assign s_axis_tready = 1'b1;
  assign m_axis_tdata = int_tdata_reg;
  assign m_axis_tvalid = int_tvalid_reg;

endmodule

module fsm_timer (
  input clk,
  input reset,
  input data,
  output reg shift_ena,
  output reg counting,
  output reg done,
  input ack,
  input done_counting
);

  // Define states
  parameter IDLE = 2'b00;
  parameter SEARCHING = 2'b01;
  parameter WAITING = 2'b10;
  parameter COUNTING = 2'b11;

  // Define state register and next state logic
  reg [1:0] state, next_state;
  always @ (posedge clk, posedge reset) begin
    if (reset) begin
      state <= IDLE;
    end else begin
      state <= next_state;
    end
  end

  // Define output register and next output logic
  reg shift_ena_out, counting_out, done_out;
  always @ (posedge clk, posedge reset) begin
    if (reset) begin
      shift_ena_out <= 1'b0;
      counting_out <= 1'b0;
      done_out <= 1'b0;
    end else begin
      shift_ena_out <= shift_ena;
      counting_out <= counting;
      done_out <= done;
    end
  end

  // Define counter register and next counter logic
  reg [4:0] counter;
  always @ (posedge clk, posedge reset) begin
    if (reset) begin
      counter <= 5'b0;
    end else if (counting) begin
      counter <= counter + 5'b1;
    end
  end

  // Define pattern detection logic
  reg [3:0] pattern;
  always @ (posedge clk, posedge reset) begin
    if (reset) begin
      pattern <= 4'b0;
    end else begin
      pattern <= {pattern[2:0], data};
    end
  end

  // Define next state and output logic
  always @ (*) begin
    case (state)
      IDLE: begin
        next_state = SEARCHING;
        shift_ena = 1'b1;
        counting = 1'b0;
        done = 1'b0;
      end
      SEARCHING: begin
        if (pattern == 4'b1011) begin
          next_state = WAITING;
          shift_ena = 1'b0;
          counting = 1'b0;
          done = 1'b0;
        end else begin
          next_state = SEARCHING;
          shift_ena = 1'b1;
          counting = 1'b0;
          done = 1'b0;
        end
      end
      WAITING: begin
        next_state = COUNTING;
        shift_ena = 1'b0;
        counting = 1'b1;
        done = 1'b0;
      end
      COUNTING: begin
        if (done_counting) begin
          next_state = IDLE;
          shift_ena = 1'b1;
          counting = 1'b0;
          done = 1'b1;
        end else begin
          next_state = COUNTING;
          shift_ena = 1'b0;
          counting = 1'b1;
          done = 1'b0;
        end
      end
      default: begin
        next_state = IDLE;
        shift_ena = 1'b1;
        counting = 1'b0;
        done = 1'b0;
      end
    endcase
  end

endmodule

