module PLL (
  input CLK_IN,
  input RESET,
  input EN,
  output CLK_OUT
);

parameter F_IN = 10e6; // frequency of the input clock signal
parameter F_OUT = 100e6; // desired frequency of the output clock signal

reg [31:0] phase_accumulator = 0;
reg [31:0] phase_accumulator_prev = 0;
reg [31:0] phase_difference = 0;
reg [31:0] charge_pump_output = 0;
reg [31:0] loop_filter_output = 0;
reg [31:0] vco_input = 0;
reg [31:0] vco_output = 0;
reg lock = 0;

// Phase detector
always @(posedge CLK_IN or posedge RESET) begin
  if(RESET) begin
    phase_accumulator <= 0;
    phase_accumulator_prev <= 0;
  end else begin
    phase_accumulator <= phase_accumulator_prev + (F_OUT/F_IN)*32'b1;
    phase_accumulator_prev <= phase_accumulator;
    phase_difference <= phase_accumulator - phase_accumulator_prev;
  end
end

// Charge pump
always @(posedge CLK_IN or posedge RESET) begin
  if(RESET) begin
    charge_pump_output <= 0;
  end else begin
    if(phase_difference > 0) begin
      charge_pump_output <= 32'b1;
    end else if(phase_difference < 0) begin
      charge_pump_output <= -32'b1;
    end else begin
      charge_pump_output <= 0;
    end
  end
end

// Loop filter
always @(posedge CLK_IN or posedge RESET) begin
  if(RESET) begin
    loop_filter_output <= 0;
  end else begin
    loop_filter_output <= loop_filter_output + charge_pump_output;
  end
end

// Voltage-controlled oscillator (VCO)
always @(posedge CLK_IN or posedge RESET) begin
  if(RESET) begin
    vco_input <= 0;
    vco_output <= 0;
  end else begin
    vco_input <= loop_filter_output;
    vco_output <= vco_output + vco_input;
  end
end

// Frequency divider
always @(posedge CLK_IN or posedge RESET) begin
  if(RESET) begin
    CLK_OUT <= 0;
  end else begin
    if(vco_output >= (F_IN/F_OUT)*32'b1) begin
      CLK_OUT <= ~CLK_OUT;
      vco_output <= 0;
    end
  end
end

// Lock detector
always @(posedge CLK_IN or posedge RESET) begin
  if(RESET) begin
    lock <= 0;
  end else begin
    if(phase_difference == 0) begin
      lock <= 1;
    end else begin
      lock <= 0;
    end
  end
end

endmodule

module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout
);

    wire [3:0] temp_sum;
    wire [3:0] temp_carry;

    // Full Adder
    assign temp_sum[0] = A[0] ^ B[0] ^ Cin;
    assign temp_carry[0] = (A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin);

    assign temp_sum[1] = A[1] ^ B[1] ^ temp_carry[0];
    assign temp_carry[1] = (A[1] & B[1]) | (A[1] & temp_carry[0]) | (B[1] & temp_carry[0]);

    assign temp_sum[2] = A[2] ^ B[2] ^ temp_carry[1];
    assign temp_carry[2] = (A[2] & B[2]) | (A[2] & temp_carry[1]) | (B[2] & temp_carry[1]);

    assign temp_sum[3] = A[3] ^ B[3] ^ temp_carry[2];
    assign Cout = (A[3] & B[3]) | (A[3] & temp_carry[2]) | (B[3] & temp_carry[2]);

    assign Sum = temp_sum;

endmodule

