        .sub(sub),
        .out(add_sub_out)
    );

    always @(posedge clk) begin
        if (reset) begin
            shift_reg[0] <= 0;
            shift_reg[1] <= 0;
            shift_reg[2] <= 0;
            shift_index <= 0;
        end else begin
