	reg [WORD-1:0] mem[0:(1<<LOGWORD)-1];
	reg [LOGWORD-1:0] addr;
	reg [WORD-1:0] data;
	reg [WORD-1:0] hold;

	always @(posedge clk) begin
		if (reset) begin
			addr <= 0;
			data <= 0;
			hold <= 0;
			lighting <= 0;
		end
		else if (enable) begin
			addr <= address[LOGWORDBYTE-1:2];
			case (size)
				2'b00: data <= din;
				2'b01: data <= {din[15:0], din[15:0]};
