module contrast_stretch(
    din0,
    din1,
    din2,
    dout);

parameter ID = 32'd1;
parameter NUM_STAGE = 32'd1;
parameter din0_WIDTH = 32'd1;
parameter din1_WIDTH = 32'd1;
parameter din2_WIDTH = 32'd1;
parameter dout_WIDTH = 32'd1;

input[din0_WIDTH - 1:0] din0;
input[din1_WIDTH - 1:0] din1;
input[din2_WIDTH - 1:0] din2;
output[dout_WIDTH - 1:0] dout;

reg [31:0] min_val;
reg [31:0] max_val;

always @(*) begin
    if (din0 < din1 && din0 < din2) begin
        min_val = din0;
    end else if (din1 < din0 && din1 < din2) begin
        min_val = din1;
    end else begin
        min_val = din2;
    end

    if (din0 > din1 && din0 > din2) begin
        max_val = din0;
    end else if (din1 > din0 && din1 > din2) begin
        max_val = din1;
    end else begin
        max_val = din2;
    end
end

always @(*) begin
    if (max_val - min_val != 0) begin
        dout = ((din0 - min_val) * (2**dout_WIDTH - 1)) / (max_val - min_val);
    end else begin
        dout = 0;
    end
end

endmodule

