// ALU module
module ALUnit(clk,oper, A, B, dataOut,Z,V,C,N);
    input clk;
    input [2:0] oper;
    input [31:0] A;
    input [31:0] B;
    output reg [31:0] dataOut;
    output reg Z,V,C,N;

    always @(posedge clk) begin
        case(oper)
            0: dataOut <= A + B;
            1: dataOut <= A - B;
            2: dataOut <= A & B;
            3: dataOut <= A | B;
            4: dataOut <= A ^ B;
            5: dataOut <= A << B[4:0];
            6: dataOut <= A >> B[4:0];
            7: dataOut <= ~A;
            default: dataOut <= 0;
        endcase

        // set flags
        Z <= (dataOut == 0);
        V <= 0;
        C <= (oper == 5) ? A[31-B[4:0]] : 0;
        N <= dataOut[31];
    end
endmodule

