  reg [MEM_WIDTH-1:0] data_reg;
  reg [3:0] byteenable_reg;
  reg wren, rden;
  reg [31:0] data_out;

  assign rden = chipselect & ~write;
  assign wren = chipselect & write;

  always @(posedge clk) begin
    if (reset) begin
      addr_reg <= 0;
      byteenable_reg <= 0;
      data_reg <= 0;
    end else if (reset_req) begin
      addr_reg <= 0;
      byteenable_reg <= 0;
    end else if (clken) begin
      addr_reg <= address;
      byteenable_reg <= byteenable;
      if (wren) begin
        mem[addr_reg][31:0] <= writedata;
      end
      data_reg <= {data_reg[31:MEM_WIDTH], mem[addr_reg][31:0]};
    end
  end

  always @(posedge clk) begin
    if (reset) begin
      readdata <= 0;
    end else if (reset_req) begin
      readdata <= 0;
    end else if (clken) begin
      if (rden) begin
        data_out <= {mem[addr_reg][31:0], data_out[MEM_WIDTH-1:32]};
        readdata <= data_out & byteenable_reg;
      end else begin
        readdata <= 0;
      end
    end
  end

  initial begin
    $readmemh(INIT_FILE, mem);
  end

endmodule

