module top_module (
    input clk,
    input reset,            // Asynchronous reset
    input [15:0] in,
    input select,           // Select input to choose between input splitter and D flip-flops
    output wire [7:0] q,
    output wire or_out
);

    wire [7:0] splitter_out;
    wire [7:0] dff_out;
    wire [7:0] mux_out;

    input_splitter splitter(.in(in), .out(splitter_out));

    always @ (posedge clk or negedge reset) begin
        if (reset == 0) begin
            dff_out <= 8'b0;
        end else if (select == 0) begin
            dff_out <= splitter_out;
        end else begin
            dff_out <= dff_out;
        end
    end

    dff dff_inst[7:0] (
        .clk(clk),
        .reset(reset),
        .d(mux_out),
        .q(dff_out)
    );

    always @ (posedge clk) begin
        if (select == 1) begin
            mux_out <= splitter_out;
        end else begin
            mux_out <= dff_out;
        end
    end

    assign q = dff_out;
    assign or_out = |dff_out|splitter_out;

