module memory(
  input clka,
  input ena,
  input [1:0] wea,
  input [14:0] addra,
  input [15:0] dina,
  input clkb,
  input [14:0] addrb,
  output reg [15:0] doutb
);

  reg [15:0] mem [32767:0];

  always @(posedge clka, negedge clka) begin
    if (ena) begin
      if (wea[1] == 0 && wea[0] == 0) mem[addra] <= dina;
      else if (wea[1] == 1 && wea[0] == 0) mem[addra] <= dina;
      else if (wea[1] == 0 && wea[0] == 1) mem[addra] <= mem[addra] | dina;
      else mem[addra] <= mem[addra] | dina;
    end
  end

  always @(posedge clkb) begin
    doutb <= mem[addrb];
  end

endmodule

module up_down_counter (
    input CLK,
    input UP_DOWN,
    input RESET,
    output reg [3:0] Q
);

always @(posedge CLK) begin
    if (RESET) begin
        Q <= 4'b0000;
    end else if (UP_DOWN) begin
        Q <= Q + 1;
    end else begin
        Q <= Q - 1;
    end
end

endmodule

module binary_counter (
    input clk,
    input reset,
    input enable,
    output reg [3:0] Q
);

always @(posedge clk) begin
    if (reset) begin
        Q <= 4'b0000;
    end else if (enable) begin
        Q <= Q + 1;
    end
end

endmodule

module functional_module (
    input [3:0] up_down_out,
    input [3:0] binary_out,
    output reg [7:0] SUM_OUT,
    input reset
);

always @(posedge reset) begin
    if (reset) begin
        SUM_OUT <= 8'b00000000;
    end
end

always @(posedge up_down_out or posedge binary_out) begin
    SUM_OUT <= up_down_out + binary_out;
end

endmodule

module control_logic (
    input [7:0] SUM_OUT,
    input [3:0] up_down_out,
    input [3:0] binary_out,
    input select,
    output reg [7:0] output_value
);

always @(posedge select or posedge SUM_OUT or posedge up_down_out or posedge binary_out) begin
    if (select) begin
        output_value <= SUM_OUT;
    end else begin
        output_value <= {4'b0000, up_down_out, binary_out};
    end
end

endmodule

