module largest_of_three (
    A,
    B,
    C,
    X
);

    input A;
    input B;
    input C;
    output X;

    wire AB;
    wire AC;
    wire BC;

    // Find the largest value between A and B
    assign AB = (A > B) ? 1'b1 : 1'b0;

    // Find the largest value between A and C
    assign AC = (A > C) ? 1'b1 : 1'b0;

    // Find the largest value between B and C
    assign BC = (B > C) ? 1'b1 : 1'b0;

    // Output the largest value among A, B, and C
    assign X = (AB & AC) | (AB & BC) | (AC & BC) ? 1'b1 : 1'b0;

endmodule

module counter(
    input clk,
    input reset,
    output reg [7:0] count
);

always @(posedge clk or posedge reset) begin
    if (reset) begin
        count <= 0;
    end else if (count == 255) begin
        count <= 0;
    end else begin
        count <= count + 1;
    end
end

endmodule

module calculator(
  input clk,
  input reset,
  input [7:0] A,
  input [7:0] B,
  input [2:0] op,
  output reg [15:0] out
);

  always @(posedge clk) begin
    if(reset) begin
      out <= 16'h0000;
    end
    else begin
      case(op)
        3'b000: out <= A + B;
        3'b001: out <= A - B;
        3'b010: out <= A * B;
        3'b011: out <= A / B;
        default: out <= 16'h0000;
      endcase
    end
  end
endmodule

