);

    always @(*) begin
        gray[3] = bin[3];
        gray[2] = bin[3] ^ bin[2];
        gray[1] = bin[2] ^ bin[1];
        gray[0] = bin[1] ^ bin[0];
    end

endmodule

module test_fifo;
  reg clk, srst, WEA, tmp_ram_rd_en;
  reg [9:0] Q;
  reg [35:0] din;
  wire [35:0] dout;
  wire pass;

  // Instantiate the FIFO memory module
  fifo_generator_0_blk_mem_gen_prim_wrapper fifo (
    .clk(clk),
    .srst(srst),
    .WEA(WEA),
    .tmp_ram_rd_en(tmp_ram_rd_en),
    .Q(Q),
    .din(din),
    .dout(dout)
  );

  // Reset the FIFO memory
  initial begin
    clk = 0;
    srst = 1;
    WEA = 0;
    tmp_ram_rd_en = 0;
    din = 0;
    #2 srst = 0;
  end

  // Write values to the FIFO memory
  always @(posedge clk) begin
    if ($time == 4) begin
      WEA = 1;
      din = 1;
    end else if ($time == 6) begin
      din = 2;
    end else if ($time == 8) begin
      din = 3;
    end else if ($time == 10) begin
      din = 4;
    end else if ($time == 12) begin
      din = 5;
    end else if ($time == 14) begin
      WEA = 0;
      din = 0;
    end
  end

  // Read values from the FIFO memory
  always @(posedge clk) begin
    if ($time == 16) begin
      tmp_ram_rd_en = 1;
      Q = 1;
    end else if ($time == 18) begin
      Q = 2;
    end else if ($time == 20) begin
      Q = 3;
    end else if ($time == 22) begin
      Q = 4;
    end else if ($time == 24) begin
      Q = 5;
    end else if ($time == 26) begin
      tmp_ram_rd_en = 0;
      Q = 0;
    end
  end

  // Check if the values read from the FIFO memory are correct
  assign pass = (dout[7:0] == 1) && (dout[15:8] == 2) && (dout[23:16] == 3) && (dout[31:24] == 4) && (dout[35:32] == 5);

  // Generate clock
  always #10 clk = ~clk;

  // Output pass/fail result
  initial begin
    $monitor("pass = %b", pass);
  end
endmodule

module binary_counter (clk, reset, ctrl, count, overflow);

   input clk, reset, ctrl;
   output reg [3:0] count;
   output reg overflow;

   always @(posedge clk) begin
      if (reset) begin
         count <= 4'b0;
         overflow <= 1'b0;
      end else begin
         if (ctrl) begin
            if (count == 4'b1111) begin
               count <= 4'b0;
               overflow <= 1'b1;
            end else begin
               count <= count + 1;
               overflow <= 1'b0;
            end
         end else begin
            if (count == 4'b0000) begin
               count <= 4'b1111;
               overflow <= 1'b1;
            end else begin
               count <= count - 1;
               overflow <= 1'b0;
            end
         end
      end
   end

endmodule

