module wishbone_timer
  #(
    parameter CNT_PRESC=24,
    parameter ENA_TMR=1
   )
   (
    // WISHBONE signals
    input        wb_clk_i,  // Clock
    input        wb_rst_i,  // Reset input
    input  [0:0] wb_adr_i,  // Address bus
    output [7:0] wb_dat_o,  // DataOut Bus
    input  [7:0] wb_dat_i,  // DataIn Bus
    input        wb_we_i,   // Write Enable
    input        wb_stb_i,  // Strobe
    output       wb_ack_o,  // Acknowledge
    // Interface
    output reg   irq_req_o,
    input        irq_ack_i
   );

localparam integer CNT_BITS=$clog2(CNT_PRESC);

// Timer counter
reg  [15:0] cnt_r=0;
// Divider value
reg  [15:0] div_r=0;
wire tc; // Terminal count
// Microseconds source
wire ena_cnt;
reg  [CNT_BITS-1:0] pre_cnt_r;

// Microseconds time source
always @(posedge wb_clk_i)
begin : tmr_source
  if (wb_rst_i)
     pre_cnt_r <= 0;
  else
     begin
     pre_cnt_r <= pre_cnt_r+1;
     if (pre_cnt_r==CNT_PRESC-1)
        pre_cnt_r <= 0;
     end
end // tmr_source;
assign ena_cnt=pre_cnt_r==CNT_PRESC-1;

// 16 bits counter
always @(posedge wb_clk_i)
begin : do_count
  if (wb_rst_i || tc || (wb_stb_i && wb_we_i))
     cnt_r <= 0;
  else
     if (ena_cnt)
        cnt_r <= cnt_r+1;
end // do_count
assign tc=cnt_r==div_r-1 && ena_cnt;

// Interrupt logic
always @(posedge wb_clk_i)
begin : do_flag
  if (wb_rst_i)
     irq_req_o <= 0;
  else if (tc && ENA_TMR)
     irq_req_o <= 1;
  else if (irq_ack_i)
     irq_req_o <= 0;
end // do_flag

////////////////////////////////////////////////////////////////////////////
// WISHBONE read
////////////////////////////////////////////////////////////////////////////
assign wb_dat_o=0;
assign wb_ack_o=wb_stb_i;

////////////////////////////////////////////////////////////////////////////
// WISHBONE write
////////////////////////////////////////////////////////////////////////////
always @(posedge wb_clk_i)
begin : do_write_div
  if (wb_rst_i)
     div_r <= 0;
  else if (wb_stb_i && wb_we_i)
     begin
     if (wb_adr_i)
        div_r[15:8] <= wb_dat_i;
     else
        div_r[7:0]  <= wb_dat_i;
     end
end // do_write_div

endmodule

module memory_error_correction (
  input [31:0] i_data,
  input [7:0] i_ecc,
  input i_write_enabled,
  output [31:0] o_data,
  output reg o_error_detected,
  output reg o_uncorrected_error,
  output [7:0] o_ecc_syndrome
);

  // Single-bit error correction
  always @(*) begin
    case (i_ecc)
      8'h00: o_data = i_data; // No error
      8'h01: o_data = i_data ^ 32'h00000001; // Bit 0 error
      8'h02: o_data = i_data ^ 32'h00000002; // Bit 1 error
      8'h04: o_data = i_data ^ 32'h00000004; // Bit 2 error
      8'h08: o_data = i_data ^ 32'h00000008; // Bit 3 error
      8'h10: o_data = i_data ^ 32'h00000010; // Bit 4 error
      8'h20: o_data = i_data ^ 32'h00000020; // Bit 5 error
      8'h40: o_data = i_data ^ 32'h00000040; // Bit 6 error
      8'h80: o_data = i_data ^ 32'h00000080; // Bit 7 error
      default: begin
        o_data = i_data;
        o_error_detected = 1;
      end
    endcase
  end

  // Double-bit error detection
  always @(*) begin
    case (i_ecc)
      8'h03, 8'h05, 8'h06, 8'h09, 8'h0a, 8'h0c, 8'h11, 8'h12, 8'h14, 8'h18, 8'h21, 8'h22, 8'h24, 8'h28, 8'h30, 8'h41, 8'h42, 8'h44, 8'h48, 8'h50, 8'h60, 8'h81, 8'h82, 8'h84, 8'h88, 8'h90, 8'ha0, 8'hc0: begin
        o_error_detected = 1;
        o_uncorrected_error = 1;
      end
      default: o_uncorrected_error = 0;
    endcase
  end

  // ECC generator
  ecc_generator gen (
    .i_data(i_data),
    .o_ecc_syndrome(o_ecc_syndrome)
  );

  // ECC memory write
  always @(posedge clk) begin
    if (i_write_enabled) begin
      ecc_mem[i_addr] <= i_ecc_syndrome;
    end
  end

  // ECC memory read
  assign o_ecc = ecc_mem[i_addr];

endmodule

module parallel_to_serial (
    input clk,
    input [7:0] data_in,
    output reg serial_out
);

    reg [7:0] shift_reg;
    reg [2:0] shift_count;

    always @(posedge clk) begin
        if (shift_count == 3'b0) begin
            shift_reg <= data_in;
            shift_count <= 3'b1;
        end else begin
            shift_reg <= {shift_reg[6:0], shift_reg[7]};
            shift_count <= shift_count + 1;
        end
    end

    assign serial_out = shift_reg[0];

endmodule

module top_module (
    input clk,
    input [7:0] data_in,
    input select,
    output reg serial_out
);

    reg shift_enable;

    always @(posedge clk) begin
        if (select) begin
            shift_enable <= 1'b0;
        end else begin
