module control_module (
    input clk,
    input reset,
    input in,
    input [255:0] mux_in,
    input [7:0] sel,
    output out
);
    wire_inverter wire_inst (
        .wire_in(in),
        .wire_out(out_wire)
    );

    multiplexer mux_inst (
        .mux_in(mux_in),
        .sel(sel),
        .mux_out(out_mux)
    );

    functional_module func_inst (
        .func_in({sel == 8'h00 ? in : mux_out}),
        .func_out(out_func)
    );

    reg out_wire;
    reg out_mux;
    reg out_func;

    always @(posedge clk)
        if (reset) begin
            out_wire <= 1'b0;
            out_mux <= 1'b0;
            out_func <= 1'b0;
        end else begin
            case (sel)
                8'h00: out_wire <= in;
                8'h01: out_mux <= mux_in[1];
