module binary_counter(
  input clk,
  input rst,
  input en,
  output reg [3:0] count,
  output reg overflow
);

  always @(posedge clk) begin
    if (rst) begin
      count <= 4'b0;
      overflow <= 1'b0;
    end else if (en) begin
      if (count == 4'hF) begin
        count <= 4'b0;
        overflow <= 1'b1;
      end else begin
        count <= count + 1;
        overflow <= 1'b0;
      end
    end
  end

endmodule

module signal_converter(
    input [7:0] data_in,
    input [1:0] mode,
    output [7:0] data_out
);

    wire [3:0] conv_data;

    // Binary to gray code conversion
    assign conv_data[0] = data_in[0];
    assign conv_data[1] = data_in[1] ^ data_in[0];
    assign conv_data[2] = data_in[2] ^ data_in[1];
    assign conv_data[3] = data_in[3] ^ data_in[2];
    assign conv_data[4] = data_in[4] ^ data_in[3];
    assign conv_data[5] = data_in[5] ^ data_in[4];
    assign conv_data[6] = data_in[6] ^ data_in[5];
    assign conv_data[7] = data_in[7] ^ data_in[6];

    // Gray code to binary conversion
    assign data_out[0] = conv_data[0];
    assign data_out[1] = conv_data[1] ^ data_out[0];
    assign data_out[2] = conv_data[2] ^ data_out[1];
    assign data_out[3] = conv_data[3] ^ data_out[2];
    assign data_out[4] = conv_data[4] ^ data_out[3];
    assign data_out[5] = conv_data[5] ^ data_out[4];
    assign data_out[6] = conv_data[6] ^ data_out[5];
    assign data_out[7] = conv_data[7] ^ data_out[6];

    // Binary to excess-3 code conversion
    always @(*) begin
        case(data_in)
            8'b00000000: conv_data = 4'b0011;
            8'b00000001: conv_data = 4'b0100;
            8'b00000010: conv_data = 4'b0101;
            8'b00000011: conv_data = 4'b0110;
            8'b00000100: conv_data = 4'b0111;
            8'b00000101: conv_data = 4'b1000;
            8'b00000110: conv_data = 4'b1001;
            8'b00000111: conv_data = 4'b1010;
            8'b00001000: conv_data = 4'b1011;
            8'b00001001: conv_data = 4'b1100;
            8'b00001010: conv_data = 4'b1101;
            8'b00001011: conv_data = 4'b1110;
            8'b00001100: conv_data = 4'b1111;
            8'b00001101: conv_data = 4'b0000;
            8'b00001110: conv_data = 4'b0001;
            8'b00001111: conv_data = 4'b0010;
            default: conv_data = 4'bxxxx;
        endcase
    end

    // Excess-3 to binary code conversion
    always @(*) begin
        case(conv_data)
            4'b0000: data_out = 8'b00001101;
            4'b0001: data_out = 8'b00001110;
            4'b0010: data_out = 8'b00001111;
            4'b0011: data_out = 8'b00000000;
            4'b0100: data_out = 8'b00000001;
            4'b0101: data_out = 8'b00000010;
            4'b0110: data_out = 8'b00000011;
            4'b0111: data_out = 8'b00000100;
            4'b1000: data_out = 8'b00000101;
            4'b1001: data_out = 8'b00000110;
            4'b1010: data_out = 8'b00000111;
            4'b1011: data_out = 8'b00001000;
            4'b1100: data_out = 8'b00001001;
            4'b1101: data_out = 8'b00001010;
            4'b1110: data_out = 8'b00001011;
            4'b1111: data_out = 8'b00001100;
            default: data_out = 8'bxxxx;
        endcase
    end

    // Select conversion mode
    always @(*) begin
        case(mode)
            2'b00: data_out = conv_data;
            2'b01: data_out = data_out;
            2'b10: data_out = conv_data;
            2'b11: data_out = data_out;
            default: data_out = 8'bxxxx;
        endcase
    end

endmodule

module sync_counter_with_load (
