module read_data (
  input [1:0] address,
  input clk,
  input [3:0] in_port,
  input reset_n,
  output reg [31:0] readdata
);

  wire [3:0] data_in;
  wire [3:0] read_mux_out;
  wire clk_en;

  assign data_in = in_port;
  assign read_mux_out = {4{1'b0}} | (data_in & ((address == 2'b00) ? 4'b1111 : ((address == 2'b01) ? {2'b00, data_in[1:0]} : ((address == 2'b10) ? {2'b0, data_in[2:0]} : {1'b0, data_in[3:0]}))));

  assign clk_en = 1'b1;

  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      readdata <= 0;
    end else if (clk_en) begin
      readdata <= {32{1'b0}} | read_mux_out;
    end
  end

endmodule

module assert_handler (
    input clk,
    input rst,
    input assert_fail,
    output reg [255:0] error_msg
);

reg [31:0] assert_count = 0;

always @(posedge clk) begin
    if (rst) begin
        assert_count <= 0;
        error_msg <= 0;
    end else if (assert_fail) begin
        assert_count <= assert_count + 1;
        error_msg <= $sformatf("%s -- %s %d", error_msg, "my_module assertion failed", assert_count);
    end
end

endmodule

module xor_xnor(
    input [3:0] a,
    input [3:0] b,
    input select,
    output reg [3:0] out
);

wire [3:0] xor_out;
wire [3:0] xnor_out;

assign xor_out = {a[3]^b[3], a[2]^b[2], a[1]^b[1], a[0]^b[0]};
assign xnor_out = ~xor_out;

always @(posedge clk) begin
    if (select) begin
        out <= xnor_out;
    end else begin
        out <= xor_out;
    end
end

endmodule

module Calculator(input signed [7:0] a, b, input [1:0] op, output reg [7:0] result, output reg error);

always @(*) begin
    case(op)
        2'b00: result = a + b;
        2'b01: result = a - b;
        2'b10: result = a * b;
        2'b11: begin
            if(b == 0) begin
                error = 1;
                result = 8'h00;
            end
            else begin
                error = 0;
                result = a / b;
            end
        end
        default: result = 8'h00;
    endcase
    // check for overflow in addition and subtraction
    if(op == 2'b00 || op == 2'b01) begin
        if((a[7] == b[7]) && (result[7] != a[7])) begin
            error = 1;
        end
        else begin
            error = 0;
        end
    end
end

endmodule

module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    output [3:0] count_out,
    input select,     // Select input to choose between counter and functional module output
    input [7:0] func_out,  // Output from the functional module
    output [7:0] sum_out  // Output of the sum of counter and functional module output
);

    reg [3:0] count;
    wire [3:0] count_next;
    wire [7:0] func_out_reg;

    counter_module counter_inst (
        .clk(clk),
        .reset(reset),
        .count(count_next)
    );

    functional_module func_inst (
        .in(count),
        .out(func_out_reg)
    );

    always @(posedge clk) begin
        if (reset) begin
            count <= 4'b0;
        end else begin
            count <= count_next;
        end
    end

    assign count_next = (count == 4'b1111) ? 4'b0 : count + 1;
    assign count_out = count;

    always @(*) begin
        if (select) begin
            sum_out = func_out + func_out_reg;
        end else begin
            sum_out = count + func_out_reg;
        end
    end

endmodule

