module data_transfer (
    input clk,
    input reset,
    input [WIDTH-1:0] up_data,
    input up_valid,
    output up_ready,
    output [WIDTH-1:0] down_data,
    output down_valid,
    input down_ready
);

/***************
* Architecture *
***************/
reg [WIDTH-1:0] stored_data;
reg stored_valid;
reg [1:0] state;

assign up_ready = (state == 2'b00 || state == 2'b10) ? 1'b1 : 1'b0;
assign down_valid = (state == 2'b01 || state == 2'b11) ? 1'b1 : 1'b0;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        stored_data <= 'hx;
        stored_valid <= 1'b0;
        state <= 2'b00;
    end else begin
        case (state)
            2'b00: begin
                if (up_valid && down_ready) begin
                    stored_data <= up_data;
                    stored_valid <= 1'b1;
                    state <= 2'b01;
                end
            end
            2'b01: begin
                if (down_valid && up_ready) begin
                    down_data <= stored_data;
                    stored_valid <= 1'b0;
                    state <= 2'b00;
                end
            end
            2'b10: begin
                if (down_valid && up_ready) begin
                    down_data <= stored_data;
                    stored_valid <= 1'b0;
                    state <= 2'b11;
                end
            end
            2'b11: begin
                if (up_valid && down_ready) begin
                    stored_data <= up_data;
                    stored_valid <= 1'b1;
                    state <= 2'b10;
                end
            end
        endcase
    end
end

endmodule

