module signed_multiplier_divider(
    input clk,
    input reset,
    input req_valid,
    output req_ready,
    input req_in_1_signed,
    input req_in_2_signed,
    input [1:0] req_op,
    input [0:0] req_out_sel,
    input signed [31:0] req_in_1,
    input signed [31:0] req_in_2,
    output resp_valid,
    output signed [31:0] resp_result
);

    localparam STATE_IDLE = 2'b00;
    localparam STATE_COMPUTE = 2'b01;
    localparam STATE_SETUP_OUTPUT = 2'b10;
    localparam STATE_DONE = 2'b11;

    reg [1:0] state;
    reg [1:0] next_state;
    reg [31:0] a;
    reg [31:0] b;
    reg [31:0] result;
    reg [4:0] counter;
    reg negate_output;

    wire [31:0] abs_in_1;
    wire sign_in_1;
    wire [31:0] abs_in_2;
    wire sign_in_2;

    wire a_geq;
    wire [31:0] result_muxed;
    wire [31:0] result_muxed_negated;
    wire [31:0] final_result;

    assign req_ready = (state == STATE_IDLE);
    assign resp_valid = (state == STATE_DONE);
    assign resp_result = final_result;

    assign abs_in_1 = (req_in_1_signed && req_in_1[31]) ? -req_in_1 : req_in_1;
    assign sign_in_1 = req_in_1_signed && req_in_1[31];
    assign abs_in_2 = (req_in_2_signed && req_in_2[31]) ? -req_in_2 : req_in_2;
    assign sign_in_2 = req_in_2_signed && req_in_2[31];

    assign a_geq = a >= b;
    assign result_muxed = (req_out_sel == 1'b0) ? a : result;
    assign result_muxed_negated = (negate_output) ? -result_muxed : result_muxed;
    assign final_result = (req_out_sel == 1'b1) ? result_muxed_negated[63:32] : result_muxed_negated[31:0];

    always @(posedge clk) begin
        if (reset) begin
            state <= STATE_IDLE;
        end else begin
            state <= next_state;
        end
    end

    always @(*) begin
        case (state)
            STATE_IDLE: begin
                if (req_valid) begin
                    a <= abs_in_1;
                    b <= abs_in_2;
                    negate_output <= (req_op == 2'b01) ? sign_in_1 ^ sign_in_2 : 0;
                    counter <= 32;
                    next_state <= STATE_COMPUTE;
                end else begin
                    next_state <= STATE_IDLE;
                end
            end
            STATE_COMPUTE: begin
                if (counter == 0) begin
                    next_state <= STATE_SETUP_OUTPUT;
                end else begin
                    if (req_op == 2'b00) begin
                        if (b[0] == 1) begin
                            result <= result + a;
                        end
                    end else begin
                        if (a_geq) begin
                            a <= a - b;
                            result <= result + (1 << (32 - counter));
                        end
                    end
                    b <= b >> 1;
                    counter <= counter - 1;
                    next_state <= STATE_COMPUTE;
                end
            end
            STATE_SETUP_OUTPUT: begin
                next_state <= STATE_DONE;
            end
            STATE_DONE: begin
                next_state <= STATE_IDLE;
            end
            default: begin
                next_state <= STATE_IDLE;
            end
        endcase
    end

endmodule

