module adder4(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout
);

    wire c1, c2, c3;
    wire s1, s2, s3, s4;

    // First bit
    full_adder fa1(A[0], B[0], Cin, s1, c1);

    // Second bit
    full_adder fa2(A[1], B[1], c1, s2, c2);

    // Third bit
    full_adder fa3(A[2], B[2], c2, s3, c3);

    // Fourth bit
    full_adder fa4(A[3], B[3], c3, s4, Cout);

    // Output
    assign Sum = {s4, s3, s2, s1};

endmodule

module full_adder(
    input A,
    input B,
    input Cin,
    output Sum,
    output Cout
);

    wire c1, c2;

    // First XOR gate
    xor x1(A, B, c1);

    // Second XOR gate
    xor x2(c1, Cin, Sum);

    // AND gate
    and a1(c1, Cin, c2);

    // OR gate
    or o1(c1, Cin, Cout);

endmodule

