module robot_arm(
  input clk,
  input rst,
  input [7:0] joint1_cmd,
  input [7:0] joint2_cmd,
  input [7:0] joint3_cmd,
  output reg [7:0] joint1_angle,
  output reg [7:0] joint2_angle,
  output reg [7:0] joint3_angle
);

  // Define constants
  localparam ANGLE_MAX = 8'hFF;
  localparam ANGLE_MIN = 8'h00;

  // Define state variables
  reg [7:0] joint1_current;
  reg [7:0] joint2_current;
  reg [7:0] joint3_current;

  // Reset state on reset
  always @(posedge rst) begin
    joint1_current <= 8'h00;
    joint2_current <= 8'h00;
    joint3_current <= 8'h00;
  end

  // Update joint angles on each clock cycle
  always @(posedge clk) begin
    // Joint 1
    if (joint1_cmd > joint1_current) begin
      joint1_current <= joint1_current + 1;
    end else if (joint1_cmd < joint1_current) begin
      joint1_current <= joint1_current - 1;
    end

    // Joint 2
    if (joint2_cmd > joint2_current) begin
      joint2_current <= joint2_current + 1;
    end else if (joint2_cmd < joint2_current) begin
      joint2_current <= joint2_current - 1;
    end

    // Joint 3
    if (joint3_cmd > joint3_current) begin
      joint3_current <= joint3_current + 1;
    end else if (joint3_cmd < joint3_current) begin
      joint3_current <= joint3_current - 1;
    end
  end

  // Limit range of motion for each joint
  always @(*) begin
    if (joint1_current > ANGLE_MAX) begin
      joint1_current <= ANGLE_MAX;
    end else if (joint1_current < ANGLE_MIN) begin
      joint1_current <= ANGLE_MIN;
    end

    if (joint2_current > ANGLE_MAX) begin
      joint2_current <= ANGLE_MAX;
    end else if (joint2_current < ANGLE_MIN) begin
      joint2_current <= ANGLE_MIN;
    end

    if (joint3_current > ANGLE_MAX) begin
      joint3_current <= ANGLE_MAX;
    end else if (joint3_current < ANGLE_MIN) begin
      joint3_current <= ANGLE_MIN;
    end
  end

  // Output current joint angles
  assign joint1_angle = joint1_current;
  assign joint2_angle = joint2_current;
  assign joint3_angle = joint3_current;

endmodule

