module clk_divider (
  input CLK_IN1,
  input COUNTER_RESET,
  input RESET,
  output reg CLK_OUT,
  output reg COUNT,
  output reg LOCKED
);

  // Parameters for the counters
  localparam C_W = 16;

  // Counter for dividing the clock
  reg [C_W-1:0] counter;

  // Divided clock output
  always @(posedge CLK_IN1 or posedge RESET) begin
    if (RESET) begin
      CLK_OUT <= 1'b0;
    end else begin
      CLK_OUT <= counter[C_W-1];
    end
  end

  // Counter for high bit
  always @(posedge CLK_IN1 or posedge COUNTER_RESET) begin
    if (COUNTER_RESET) begin
      counter <= #1 { C_W { 1'b0 } };
    end else begin
      counter <= #1 counter + 1'b1;
    end
  end

  // Locked output
  always @(posedge CLK_IN1) begin
    if (CLK_OUT == 1'b0 && !RESET) begin
      LOCKED <= 1'b1;
    end else begin
      LOCKED <= 1'b0;
    end
  end

  // High bit output
  assign COUNT = counter[C_W-1];

endmodule

