module binary_to_bcd(clk, data_in, bcd_out);
    input clk;
    input [3:0] data_in;
    output [15:0] bcd_out;

    reg [3:0] temp1, temp2, temp3, temp4;

    always @(posedge clk) begin
        temp1 <= 4'd0;
        temp2 <= 4'd0;
        temp3 <= 4'd0;
        temp4 <= 4'd0;

        for (i = 0; i < 4; i = i+1) begin
            temp1 <= temp1 << 1;
            if (data_in[i] == 1) begin
                temp1 <= temp1 + 1;
            end
            if (temp1 >= 5) begin
                temp1 <= temp1 + 3;
            end
        end

        for (i = 0; i < 4; i = i+1) begin
            temp2 <= temp2 << 1;
            if (temp1[3] == 1) begin
                temp2 <= temp2 + 1;
            end
            if (temp2 >= 5) begin
                temp2 <= temp2 + 3;
            end
            temp1 <= temp1 << 1;
        end

        for (i = 0; i < 4; i = i+1) begin
            temp3 <= temp3 << 1;
            if (temp2[3] == 1) begin
                temp3 <= temp3 + 1;
            end
            if (temp3 >= 5) begin
                temp3 <= temp3 + 3;
            end
            temp2 <= temp2 << 1;
        end

        for (i = 0; i < 4; i = i+1) begin
            temp4 <= temp4 << 1;
            if (temp3[3] == 1) begin
                temp4 <= temp4 + 1;
            end
            if (temp4 >= 5) begin
                temp4 <= temp4 + 3;
            end
            temp3 <= temp3 << 1;
        end

        bcd_out <= {temp4, temp3, temp2, temp1};
    end
endmodule

