module fifo(
  rst,
  wr_clk,
  rd_clk,
  din,
  wr_en,
  rd_en,
  dout,
  full,
  empty,
  prog_full
);

parameter WIDTH = 256;
parameter DEPTH = 512;

input rst;
input wr_clk;
input rd_clk;
input [WIDTH-1 : 0] din;
input wr_en;
input rd_en;
output [WIDTH-1 : 0] dout;
output full;
output empty;
output prog_full;

reg [WIDTH-1 : 0] mem [0 : DEPTH-1];
reg [DEPTH-1 : 0] wr_ptr;
reg [DEPTH-1 : 0] rd_ptr;
wire [DEPTH-1 : 0] count = wr_ptr - rd_ptr;
wire [DEPTH-1 : 0] next_wr_ptr = wr_ptr + 1'b1;
wire [DEPTH-1 : 0] next_rd_ptr = rd_ptr + 1'b1;
wire [DEPTH-1 : 0] almost_full_threshold = DEPTH - 8;

assign full = (count == DEPTH);
assign empty = (count == 0);
assign prog_full = (count >= almost_full_threshold);

always @(posedge wr_clk or negedge rst) begin
  if (!rst) begin
    wr_ptr <= 0;
  end else if (wr_en && !full) begin
    wr_ptr <= next_wr_ptr;
    mem[wr_ptr] <= din;
  end
end

always @(posedge rd_clk or negedge rst) begin
  if (!rst) begin
    rd_ptr <= 0;
  end else if (rd_en && !empty) begin
    rd_ptr <= next_rd_ptr;
  end
end

assign dout = mem[rd_ptr];

endmodule

module CoProcessor0RF(clk, din, wEn, regNum, sel, dout, npc_out, expiaddr, ins);
	input				clk;
	input		[1:0]	wEn;
	input 		[4:0]	regNum;
	input		[2:0]	sel;
	input		[31:0]	din;
	input 		[31:0] 	ins;
	input 		[31:0] 	npc_out;
	output		[31:0]	dout;
	output reg 	[31:0] 	expiaddr;

	reg	[31:0]	coprf	[0:31];

	wire [5:0] op;
	wire [5:0] func;
	wire [4:0] mf_tc0_eret;

	assign op			= ins[31:26];
	assign mf_tc0_eret	= ins[25:21];
	assign func			= ins[5:0];

	// op
	parameter 	R 				= 6'b000000,
				MTC0_MFC0_ERET	= 6'b010000;
	// Function code.
	parameter 	SYSCALL	= 6'b001100;
	// MTC0_MFC0_ERET
	parameter 	MTC0 	= 5'b00100,
				MFC0 	= 5'b00000,
				ERET 	= 5'b10000;

	initial begin
		coprf[12]	= 32'h0000_0000;// Status
		coprf[13]	= 32'h0000_0000;// Cause
		coprf[14]	= 32'h0000_3000;// EPC
	end

	assign dout = coprf[regNum];

	always @ (posedge clk) begin
		if (wEn) begin
			if ((op == R) && (func == SYSCALL)) begin// SYSCALL
				coprf[14] <= npc_out - 3'b100;
				coprf[13][6:2] <= 5'b01000;
				coprf[12][1] <= 1'b1;
				expiaddr <= 32'h0000_3000;
			end else if ((op == MTC0_MFC0_ERET) && (mf_tc0_eret == ERET)) begin// ERET
				coprf[12][1] <= 1'b0;
				expiaddr <= coprf[14][31:0];
			end else begin// MTC0
				coprf[regNum] <= din;
			end
		end
	end

endmodule

