module top_module (
    input [7:0] in1,
    input [7:0] in2,
    input clk,
    input select,
    output reg [8:0] out
);

reg [7:0] xor_output;
wire even_parity;

// XOR operation
always @(posedge clk) begin
    xor_output <= in1 ^ in2;
end

// Parity bit generator
parity_bit_generator pb_gen (
    .data_in(xor_output),
    .parity_out(even_parity)
);

// Control logic
control_logic ctrl (
    .select(select),
    .parity_in(even_parity),
    .out(out[8])
);

// Output assignment
always @(posedge clk) begin
    out[7:0] <= xor_output;
end

endmodule

// Parity bit generator module
module parity_bit_generator (
    input [7:0] data_in,
    output reg parity_out
);

integer i;
reg [7:0] temp;

always @(*) begin
    temp = data_in;
    for (i = 0; i < 7; i = i + 1) begin
        temp[i+1] = temp[i] ^ temp[i+1];
    end
    parity_out = temp[7];
end

endmodule

// Control logic module
module control_logic (
    input select,
    input parity_in,
    output reg out
);

always @(*) begin
    if (select) begin
        out = parity_in;
    end else begin
        out = 1'b0;
    end
end

endmodule

module five_input_gate (in1, in2, in3, in4, in5, out);

input in1, in2, in3, in4, in5;
output out;

wire temp1, temp2;

// AND the first two inputs
and and1(temp1, in1, in2);

// AND the third and fourth inputs
and and2(temp2, in3, in4);

// OR the two temporary outputs and the fifth input
or or1(out, temp1, temp2, in5);

endmodule

module image_display(
    input clk_sdram,
    input clk_lcd,
    input clk_cam,
    input reset_n,
    input cam_ref_clk,
    input vsync,
    input hsync,
    input pixclk,
    input [7:0] data,
    output reg [7:0] R,
    output reg [7:0] G,
    output reg [7:0] B,
    output reg HSYNC,
    output reg VSYNC,
    output reg LCD_CLK,
    output reg DE,
    output reg [25:0] sdram_mm_slave_address,
    output reg [1:0] sdram_mm_slave_byteenable_n,
    output reg sdram_mm_slave_chipselect,
    output reg [15:0] sdram_mm_slave_writedata,
    output reg sdram_mm_slave_read_n,
    output reg sdram_mm_slave_write_n,
    input [15:0] sdram_mm_slave_readdata,
    input sdram_mm_slave_readdatavalid,
    output reg sdram_mm_slave_waitrequest
);

reg [15:0] sdram_mem [307200:0];
reg [25:0] k;
reg [7:0] brightness;

// initialize SDRAM memory to 0
initial begin
    for (k = 0; k < 524287; k = k + 1) begin
        sdram_mem[k] = 0;
    end
end

// set up reset signal
always @(posedge clk_cam) begin
    if (reset_n == 0) begin
        HSYNC <= 0;
        VSYNC <= 0;
        LCD_CLK <= 0;
        DE <= 0;
        sdram_mm_slave_chipselect <= 0;
        sdram_mm_slave_byteenable_n <= 2'b11;
        sdram_mm_slave_read_n <= 1;
        sdram_mm_slave_write_n <= 1;
        brightness <= 0;
    end
end

// handle camera timing signals
always @(posedge cam_ref_clk) begin
    if (reset_n == 1) begin
        if (vsync == 0 && hsync == 0) begin
            // pixel data
            sdram_mm_slave_chipselect <= 1;
            sdram_mm_slave_byteenable_n <= 0;
            sdram_mm_slave_writedata <= data;
            sdram_mm_slave_write_n <= 0;
            DE <= 1;
        end else if (vsync == 1 && hsync == 0) begin
            // start of horizontal sync
            HSYNC <= 0;
            sdram_mm_slave_chipselect <= 0;
            sdram_mm_slave_byteenable_n <= 2'b11;
            sdram_mm_slave_read_n <= 1;
            sdram_mm_slave_write_n <= 1;
            DE <= 0;
        end else if (vsync == 0 && hsync == 1) begin
            // end of horizontal sync
            HSYNC <= 1;
            LCD_CLK <= ~LCD_CLK;
        end else if (vsync == 1 && hsync == 1) begin
            // start of vertical sync
            VSYNC <= 0;
            HSYNC <= 0;
        end
    end
end

// handle LCD timing signals
always @(posedge clk_lcd) begin
    if (reset_n == 1) begin
        if (VSYNC == 0 && HSYNC == 0) begin
            // display pixel data
            R <= sdram_mm_slave_readdata[brightness+7:brightness];
            G <= sdram_mm_slave_readdata[brightness+15:brightness+8];
            B <= sdram_mm_slave_readdata[brightness+23:brightness+16];
        end else if (VSYNC == 1 && HSYNC == 0) begin
            // start of horizontal sync
            DE <= 0;
        end else if (VSYNC == 0 && HSYNC == 1) begin
            // end of horizontal sync
            DE <= 1;
        end else if (VSYNC == 1 && HSYNC == 1) begin
            // start of vertical sync
            VSYNC <= 1;
        end
    end
end

// handle SDRAM read requests
always @(posedge clk_sdram) begin
    if (sdram_mm_slave_read_n == 0) begin
        sdram_mm_slave_readdata <= sdram_mem[sdram_mm_slave_address[18:0]];
    end
end

// handle SDRAM write requests
always @(posedge clk_sdram) begin
    if (sdram_mm_slave_write_n == 0) begin
        sdram_mem[sdram_mm_slave_address[18:0]] <= sdram_mm_slave_writedata;
    end
end

// handle SDRAM wait requests
always @(posedge clk_sdram) begin
    if (sdram_mm_slave_waitrequest == 1) begin
        sdram_mm_slave_waitrequest <= 0;
    end else begin
        sdram_mm_slave_waitrequest <= 1;
    end
end

endmodule

module DisplayPort_Transmitter (
  input [7:0] video_in,
  input [1:0] audio_in,
  output [7:0] DP_data,
  output DP_clk,
  output DP_hsync,
  output DP_vsync
);
  // Define the DisplayPort protocol
  parameter NUM_LANES = 4; // Number of data lanes
  parameter NUM_SYMBOLS_PER_LANE = 10; // Number of symbols per lane
  parameter NUM_CONTROL_SYMBOLS = 4; // Number of control symbols
  parameter NUM_DATA_SYMBOLS = NUM_LANES * NUM_SYMBOLS_PER_LANE; // Number of data symbols

  // Define the symbols used for the DisplayPort protocol
  parameter SYMBOL_IDLE = 8'h00; // Idle symbol
  parameter SYMBOL_START = 8'h12; // Start symbol
  parameter SYMBOL_SYNC = 8'h1D; // Sync symbol
  parameter SYMBOL_DATA = 8'h02; // Data symbol

  // Define the control symbols used for the DisplayPort protocol
  parameter SYMBOL_CONTROL_HSYNC = 8'h14; // Horizontal sync control symbol
  parameter SYMBOL_CONTROL_VSYNC = 8'h15; // Vertical sync control symbol
  parameter SYMBOL_CONTROL_BLANK = 8'h16; // Blank control symbol
  parameter SYMBOL_CONTROL_RESET = 8'h17; // Reset control symbol

  // Define the state machine for the DisplayPort transmitter
  reg [2:0] state = 3'b000;
  reg [3:0] symbol_count = 4'd0;
  reg [3:0] lane_count = 4'd0;
  reg [7:0] current_symbol = SYMBOL_IDLE;
  reg [7:0] current_data_symbol = NUM_DATA_SYMBOLS - 1;
  reg [7:0] current_control_symbol = NUM_CONTROL_SYMBOLS - 1;
  reg [7:0] current_lane_data = 8'h00;

  // Define the conversion functions for the DisplayPort protocol
  function [7:0] convert_data_symbol;
    input [7:0] data;
    input [3:0] lane;
    begin
      case (lane)
        0: convert_data_symbol = {SYMBOL_DATA, data};
        1: convert_data_symbol = {SYMBOL_DATA, data};
        2: convert_data_symbol = {SYMBOL_DATA, data};
        3: convert_data_symbol = {SYMBOL_DATA, data};
        default: convert_data_symbol = SYMBOL_IDLE;
      endcase
    end
  endfunction

  function [7:0] convert_control_symbol;
    input [3:0] control;
    begin
      case (control)
        0: convert_control_symbol = SYMBOL_CONTROL_HSYNC;
        1: convert_control_symbol = SYMBOL_CONTROL_VSYNC;
        2: convert_control_symbol = SYMBOL_CONTROL_BLANK;
        3: convert_control_symbol = SYMBOL_CONTROL_RESET;
        default: convert_control_symbol = SYMBOL_IDLE;
      endcase
    end
  endfunction

  // Define the state machine for the DisplayPort transmitter
  always @ (posedge DP_clk) begin
    case (state)
      3'b000: begin // Idle state
        DP_data <= SYMBOL_IDLE;
        DP_hsync <= 1'b0;
        DP_vsync <= 1'b0;
        DP_clk <= 1'b0;
        if (symbol_count == 4'd0) begin
          state <= 3'b001; // Go to start state
        end
        else begin
          symbol_count <= symbol_count - 1; // Decrement symbol count
        end
      end
      3'b001: begin // Start state
        DP_data <= SYMBOL_START;
        DP_hsync <= 1'b0;
        DP_vsync <= 1'b0;
        DP_clk <= 1'b1;
        state <= 3'b010; // Go to sync state
      end
      3'b010: begin // Sync state
        DP_data <= SYMBOL_SYNC;
        DP_hsync <= 1'b0;
        DP_vsync <= 1'b0;
        DP_clk <= 1'b0;
        if (symbol_count == 4'd0) begin
          state <= 3'b011; // Go to data state
          symbol_count <= NUM_SYMBOLS_PER_LANE - 1; // Reset symbol count
        end
        else begin
          symbol_count <= symbol_count - 1; // Decrement symbol count
        end
      end
      3'b011: begin // Data state
        if (lane_count == NUM_LANES) begin
          lane_count <= 4'd0; // Reset lane count
          if (current_data_symbol == 0) begin
            state <= 3'b100; // Go to control state
            current_control_symbol <= NUM_CONTROL_SYMBOLS - 1; // Reset control symbol count
          end
          else begin
            current_data_symbol <= current_data_symbol - 1; // Decrement data symbol count
          end
        end
        else begin
          current_lane_data <= video_in[(lane_count * 8) +: 8]; // Get data for current lane
          DP_data <= convert_data_symbol(current_lane_data, lane_count); // Convert data symbol for current lane
          DP_hsync <= 1'b0;
          DP_vsync <= 1'b0;
          DP_clk <= 1'b0;
          lane_count <= lane_count + 1; // Increment lane count
        end
        if (symbol_count == 4'd0) begin
          symbol_count <= NUM_SYMBOLS_PER_LANE - 1; // Reset symbol count
        end
        else begin
          symbol_count <= symbol_count - 1; // Decrement symbol count
        end
      end
      3'b100: begin // Control state
        DP_data <= convert_control_symbol(current_control_symbol); // Convert control symbol
        DP_hsync <= 1'b0;
        DP_vsync <= 1'b0;
        DP_clk <= 1'b0;
        if (symbol_count == 4'd0) begin
          symbol_count <= 4'd0; // Reset symbol count
          current_control_symbol <= current_control_symbol - 1; // Decrement control symbol count
          if (current_control_symbol == -1) begin
            state <= 3'b000; // Go to idle state
            symbol_count <= 4'd0; // Reset symbol count
            current_data_symbol <= NUM_DATA_SYMBOLS - 1; // Reset data symbol count
            current_control_symbol <= NUM_CONTROL_SYMBOLS - 1; // Reset control symbol count
          end
        end
        else begin
          symbol_count <= symbol_count - 1; // Decrement symbol count
        end
      end
      default: begin
        state <= 3'b000; // Go to idle state if in an invalid state
      end
    endcase
  end

endmodule

module test_can_tx;

	// Instantiate the Unit Under Test (UUT)
	can_tx uut (
		.tx(tx), 
		.can_bitstuff(can_bitstuff), 
		.txing(txing), 
		.rx(rx), 
		.address(address), 
		.clk(clk), 
		.baud_clk(baud_clk), 
		.rst(rst), 
		.data(data), 
		.send_data(send_data), 
		.bitstuffed_output(bitstuffed_output), 
		.clear_to_tx(clear_to_tx)
	);

	// Inputs
	reg [10:0] address;
	reg clk;
	reg baud_clk;
	reg rst;
	reg [63:0] data;
	reg send_data;
	reg clear_to_tx;

	// Outputs
	wire tx;
	wire can_bitstuff;
	wire txing;
	wire rx;
	wire [63:0] bitstuffed_output;

	initial begin
		// Initialize Inputs
		address = 11'h28;
		clk = 0;
		baud_clk = 0;
		rst = 1;
		data = 43;
		send_data = 0;
		clear_to_tx = 0;

		// Wait 100 ns for global reset to finish
		#100;
        rst = 0;

		// Send data
		send_data = 1;
		clear_to_tx = 1;
		#10;
		data = 43;
		#1000000;
		clear_to_tx = 0;

		// Wait for transmission to finish
		while (txing) begin
			#1;
		end

		// Terminate
		$stop;
	end

	always #1.25 clk=~clk;
	always #1000 baud_clk=~baud_clk;

endmodule

