module peripheral_uart(clk, rst, d_in, cs, addr, rd, wr, d_out, uart_tx, ledout);

  input clk;
  input rst;
  input [15:0] d_in;
  input cs;
  input [3:0] addr; // 4 LSB from j1_io_addr
  input rd;
  input wr;
  output reg [15:0] d_out;

  output uart_tx;
  output reg ledout = 0;

  //------------------------------------ regs and wires-------------------------------

  reg [2:0] s;  //selector mux_4  and demux_4

  reg [7:0] d_in_uart; // data in uart

  wire uart_busy;  // out_uart

  //------------------------------------ regs and wires-------------------------------

  always @(*) begin
    // Address decoding to determine which peripheral register to access based on the `addr` input
    case (addr)
      4'h0: begin s = (cs && rd) ? 3'b001 : 3'b000; end //busy
      4'h2: begin s = (cs && wr) ? 3'b010 : 3'b000; end //data
      4'h4: begin s = (cs && wr) ? 3'b100 : 3'b000; end //ledout
      default: begin s = 3'b000; end
    endcase
  end

  always @(negedge clk) begin
    // Writing to the `d_in_uart` register when the `cs`, `wr`, and `addr` signals indicate that data should be written to the UART
    d_in_uart = (s[1]) ? d_in[7:0] : d_in_uart;
    // Writing to the `ledout` register when the `cs`, `wr`, and `addr` signals indicate that data should be written to the LED output
    ledout = (s[2]) ? d_in[0] : ledout;
  end

  always @(negedge clk) begin
    // Multiplexing the output signals based on the peripheral register being accessed
    case (s)
      3'b001: begin
        // Communicating with the external device via the UART transmit signal
        d_out[0] = uart_busy;
      end
      default: begin
        d_out = 0;
      end
    endcase
  end

  // Communicating with the external device via the UART transmit signal
  uart uart(
    .uart_busy(uart_busy),
    .uart_tx(uart_tx),
    .uart_wr_i(cs && wr && (addr != 4'h4)),
    .uart_dat_i(d_in_uart),
    .sys_clk_i(clk),
    .sys_rst_i(rst)
  );

endmodule

