module Bluetooth (
  input clk,
  input rst,
  input data_in,
  input valid_in,
  output data_out,
  output valid_out
);

  // Define internal signals
  reg [7:0] tx_data;
  reg [7:0] rx_data;
  reg tx_valid;
  reg rx_valid;

  // Transmitter block
  always @(posedge clk, posedge rst) begin
    if (rst) begin
      tx_data <= 8'b0;
      tx_valid <= 1'b0;
    end else if (valid_in) begin
      tx_data <= data_in;
      tx_valid <= 1'b1;
    end else if (tx_valid) begin
      tx_data <= 8'b0;
      tx_valid <= 1'b0;
    end
  end

  // Receiver block
  always @(posedge clk, posedge rst) begin
    if (rst) begin
      rx_data <= 8'b0;
      rx_valid <= 1'b0;
    end else if (rx_valid) begin
      data_out <= rx_data;
      valid_out <= 1'b1;
      rx_valid <= 1'b0;
    end
  end

  // Connect to Bluetooth hardware
  assign tx_data = bluetooth_tx_data;
  assign tx_valid = bluetooth_tx_valid;
  assign bluetooth_rx_data = rx_data;
  assign bluetooth_rx_valid = rx_valid;

endmodule

module TrafficLightController (
    input clk,
    input rst,
    output reg [1:0] state
);

localparam GREEN_TIME = 20;
localparam YELLOW_TIME = 5;
localparam RED_TIME = 15;

reg [5:0] counter;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        counter <= 0;
        state <= 2'b01; // Green state
    end else begin
        counter <= counter + 1;
        case (state)
            2'b01: // Green state
                if (counter >= GREEN_TIME) begin
                    state <= 2'b10; // Yellow state
                    counter <= 0;
                end
            2'b10: // Yellow state
                if (counter >= YELLOW_TIME) begin
                    state <= 2'b11; // Red state
                    counter <= 0;
                end
            2'b11: // Red state
                if (counter >= RED_TIME) begin
                    state <= 2'b01; // Green state
                    counter <= 0;
                end
        endcase
    end
end

endmodule

module dma_prg_reg (
    input clk,
    input rst_n,
    input wr_en,
    input [31:0] wr_data,
    input [3:0] addr,
    output reg [31:0] rd_data,
    output reg [15:0] dt_rc_last,
    output reg dt_rc_last_sync,
    output reg [15:0] dt_size,
    output reg [63:0] dt_base_rc,
    output reg dt_eplast_ena,
    output reg dt_msi,
    output reg dt_3dw_rcadd,
    output reg [4:0] app_msi_num,
    output reg [2:0] app_msi_tc,
    output reg init
);

    reg [31:0] prg_reg_DW0;
    reg [31:0] prg_reg_DW1;
    reg [31:0] prg_reg_DW2;
    reg [31:0] prg_reg_DW3;
    reg soft_dma_reset;

    localparam EP_ADDR_DW0 = 2'b00;
    localparam EP_ADDR_DW1 = 2'b01;
    localparam EP_ADDR_DW2 = 2'b10;
    localparam EP_ADDR_DW3 = 2'b11;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            prg_reg_DW0 <= 32'h0;
            prg_reg_DW1 <= 32'h0;
            prg_reg_DW2 <= 32'h0;
            prg_reg_DW3 <= 32'h0;
            dt_size <= 16'h0;
            dt_msi <= 1'b0;
            dt_eplast_ena <= 1'b0;
            app_msi_num <= 5'h0;
            app_msi_tc <= 3'h0;
            dt_rc_last_sync <= 1'b0;
            dt_base_rc <= 64'h0;
            dt_3dw_rcadd <= 1'b0;
            dt_rc_last <= 16'h0;
            rd_data <= 32'h0;
            soft_dma_reset <= 1'b1;
            init <= 1'b1;
        end else begin
            soft_dma_reset <= 1'b0;
            if (wr_en) begin
                case (addr)
                    EP_ADDR_DW0: prg_reg_DW0 <= wr_data;
                    EP_ADDR_DW1: prg_reg_DW1 <= wr_data;
                    EP_ADDR_DW2: prg_reg_DW2 <= wr_data;
                    EP_ADDR_DW3: begin
                        prg_reg_DW3 <= wr_data;
                        init <= 1'b0;
                    end
                endcase
            end

            case (addr)
                EP_ADDR_DW0: rd_data <= prg_reg_DW0;
                EP_ADDR_DW1: dt_base_rc[63:32] <= prg_reg_DW1;
                EP_ADDR_DW2: begin
                    dt_base_rc[31:0] <= prg_reg_DW2;
                    dt_rc_last[15:0] <= prg_reg_DW2[15:0];
                end
                EP_ADDR_DW3: begin
                    dt_size <= prg_reg_DW0[15:0]-1;
                    dt_msi <= prg_reg_DW0[17];
                    dt_eplast_ena <= prg_reg_DW0[18];
                    app_msi_num <= prg_reg_DW0[24:20];
                    app_msi_tc <= prg_reg_DW0[30:28];
                    dt_rc_last_sync <= prg_reg_DW0[31];
                    dt_3dw_rcadd <= (prg_reg_DW1==32'h0) ? 1'b1 : 1'b0;
                    rd_data <= prg_reg_DW3;
                end
            endcase
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            dt_rc_last <= 16'h0;
        end else begin
            if (prg_reg_DW0[31]) begin
                dt_rc_last <= 16'h0;
            end else begin
                dt_rc_last <= prg_reg_DW3[15:0];
            end
        end
    end

endmodule

module axi_lite_slave
(
 input  wire        s_axi_aclk,
 input  wire        s_axi_aresetn,
 input  wire [8:0]  s_axi_awaddr,
 input  wire        s_axi_awvalid,
 output wire        s_axi_awready,
 input  wire [31:0] s_axi_wdata,
 input  wire [3:0]  s_axi_wstrb,
 input  wire        s_axi_wvalid,
 output wire        s_axi_wready,
 output wire [1:0]  s_axi_bresp,
 output wire        s_axi_bvalid,
 input  wire        s_axi_bready,
 input  wire [8:0]  s_axi_araddr,
 input  wire        s_axi_arvalid,
 output wire        s_axi_arready,
 output wire [31:0] s_axi_rdata,
 output wire [1:0]  s_axi_rresp,
 output wire        s_axi_rvalid,
 input  wire        s_axi_rready
);

    reg [31:0] mem [511:0];
    reg [1:0] bresp;
    reg bvalid, rvalid;
    reg [31:0] rdata;
    reg [1:0] rresp;
    reg [8:0] read_addr;

    always @(posedge s_axi_aclk) begin
        if (!s_axi_aresetn) begin
            s_axi_awready <= 0;
            s_axi_wready <= 0;
            s_axi_bvalid <= 0;
            s_axi_bresp <= 0;
            s_axi_arready <= 0;
            s_axi_rdata <= 0;
            s_axi_rresp <= 0;
            s_axi_rvalid <= 0;
            bvalid <= 0;
            rvalid <= 0;
            rdata <= 0;
            rresp <= 0;
            read_addr <= 0;
        end else begin
            if (s_axi_awvalid && !s_axi_bvalid) begin
                s_axi_awready <= 1;
                if (s_axi_wvalid) begin
                    s_axi_wready <= 1;
                    mem[s_axi_awaddr[8:2]] <= s_axi_wdata;
                    bvalid <= 1;
                    bresp <= 0;
                end
            end else begin
                s_axi_awready <= 0;
                s_axi_wready <= 0;
            end

            if (s_axi_arvalid && !rvalid) begin
                s_axi_arready <= 1;
                read_addr <= s_axi_araddr[8:2];
                rvalid <= 1;
                rresp <= 0;
            end else begin
                s_axi_arready <= 0;
            end

            if (s_axi_bready && bvalid) begin
                s_axi_bvalid <= 0;
            end

            if (s_axi_rready && rvalid) begin
                s_axi_rdata <= mem[read_addr];
                s_axi_rresp <= 0;
                s_axi_rvalid <= 1;
                rvalid <= 0;
            end else begin
                s_axi_rvalid <= 0;
            end
        end
    end

    assign s_axi_bresp = bresp;
    assign s_axi_rresp = rresp;

    assign s_axi_bvalid = bvalid;
    assign s_axi_rdata = rdata;
    assign s_axi_rvalid = rvalid;

endmodule

