module CDR (
  input data_in,
  input clk_ref,
  output clk_out
);

  // Define the PLL components
  reg [31:0] vco_count = 0;
  reg [31:0] phase_error = 0;
  reg [31:0] phase_detector_out = 0;
  reg [31:0] vco_out = 0;
  reg [31:0] vco_frequency = 0;
  reg [31:0] vco_gain = 0;
  reg [31:0] vco_offset = 0;
  reg [31:0] vco_max_frequency = 0;
  reg [31:0] vco_min_frequency = 0;
  reg [31:0] vco_step_size = 0;
  reg [31:0] vco_step_time = 0;
  reg [31:0] vco_step_count = 0;

  // Define the frequency divider
  reg [31:0] divider_count = 0;
  reg [31:0] divider_value = 10; // Fixed integer value for frequency division

  // Define the phase detector
  always @(posedge clk_ref) begin
    phase_detector_out <= data_in;
  end

  always @(posedge clk_ref) begin
    phase_error <= phase_detector_out - vco_out;
  end

  // Define the VCO
  always @(posedge clk_ref) begin
    if (vco_count == 0) begin
      vco_frequency <= vco_frequency + vco_gain * phase_error + vco_offset;

      if (vco_frequency > vco_max_frequency) begin
        vco_frequency <= vco_max_frequency;
      end

      if (vco_frequency < vco_min_frequency) begin
        vco_frequency <= vco_min_frequency;
      end

      vco_step_count <= vco_step_count + 1;

      if (vco_step_count == vco_step_time) begin
        vco_frequency <= vco_frequency + vco_step_size;
        vco_step_count <= 0;
      end

      vco_out <= vco_out + (vco_frequency / 2);

      if (vco_out >= 1) begin
        vco_out <= 0;
      end
    end

    vco_count <= vco_count + 1;

    if (vco_count == divider_value) begin
      vco_count <= 0;
    end
  end

  // Define the frequency divider
  always @(posedge clk_ref) begin
    divider_count <= divider_count + 1;

    if (divider_count == divider_value) begin
      clk_out <= ~clk_out;
      divider_count <= 0;
    end
  end

endmodule

