module sync_bits
(
    input [NUM_OF_BITS-1:0] in,
    input out_resetn,
    input out_clk,
    output [NUM_OF_BITS-1:0] out
);

    // Number of bits to synchronize
    parameter NUM_OF_BITS = 1;
    // Whether input and output clocks are asynchronous, if 0 the synchronizer will
    // be bypassed and the output signal equals the input signal.
    parameter ASYNC_CLK = 1;

    reg [NUM_OF_BITS-1:0] cdc_sync_stage1 = 'h0;
    reg [NUM_OF_BITS-1:0] cdc_sync_stage2 = 'h0;

    always @(posedge out_clk)
    begin
        if (out_resetn == 1'b0) begin
            cdc_sync_stage1 <= 'b0;
            cdc_sync_stage2 <= 'b0;
        end else begin
            cdc_sync_stage1 <= in;
            cdc_sync_stage2 <= cdc_sync_stage1;
        end
    end

    assign out = ASYNC_CLK ? cdc_sync_stage2 : in;

endmodule

module gpio_bridge(
    input s_axi_aclk,
    input s_axi_aresetn,
    input [8:0] s_axi_awaddr,
    input s_axi_awvalid,
    output s_axi_awready,
    input [31:0] s_axi_wdata,
    input [3:0] s_axi_wstrb,
    input s_axi_wvalid,
    output s_axi_wready,
    output [1:0] s_axi_bresp,
    output s_axi_bvalid,
    input s_axi_bready,
    input [8:0] s_axi_araddr,
    input s_axi_arvalid,
    output s_axi_arready,
    output [31:0] s_axi_rdata,
    output [1:0] s_axi_rresp,
    output s_axi_rvalid,
    input s_axi_rready,
    input [3:0] gpio_io_i,
    output [3:0] gpio_io_o,
    inout [3:0] gpio_io_t
);

reg [31:0] gpio_data;

always @(posedge s_axi_aclk) begin
    if (!s_axi_aresetn) begin
        gpio_data <= 0;
    end else if (s_axi_awvalid && s_axi_awready) begin
        case (s_axi_awaddr[8:6])
            3'b000: gpio_data[7:0] <= s_axi_wdata[7:0];
            3'b001: gpio_data[15:8] <= s_axi_wdata[7:0];
            3'b010: gpio_data[23:16] <= s_axi_wdata[7:0];
            3'b011: gpio_data[31:24] <= s_axi_wdata[7:0];
            default: gpio_data <= gpio_data;
        endcase
    end else if (s_axi_wvalid && s_axi_wready) begin
        case (s_axi_awaddr[8:6])
            3'b000: gpio_data[7:0] <= {gpio_data[7:0], s_axi_wdata[7:0]};
            3'b001: gpio_data[15:8] <= {gpio_data[15:8], s_axi_wdata[7:0]};
            3'b010: gpio_data[23:16] <= {gpio_data[23:16], s_axi_wdata[7:0]};
            3'b011: gpio_data[31:24] <= {gpio_data[31:24], s_axi_wdata[7:0]};
            default: gpio_data <= gpio_data;
        endcase
    end else if (s_axi_arvalid && s_axi_arready) begin
        case (s_axi_araddr[8:6])
            3'b000: s_axi_rdata <= gpio_data[7:0];
            3'b001: s_axi_rdata <= gpio_data[15:8];
            3'b010: s_axi_rdata <= gpio_data[23:16];
            3'b011: s_axi_rdata <= gpio_data[31:24];
            default: s_axi_rdata <= 0;
        endcase
    end
end

