	output	  locked;

	reg [31:0] counter;
	reg locked_reg;
	wire [31:0] freq_div;

	assign freq_div = inclk0 * 10; // divide by 10

	always @(posedge inclk0 or negedge areset) begin
		if (~areset) begin
			counter <= 0;
			locked_reg <= 0;
			c0 <= 0;
		end else begin
			counter <= counter + 1;
			if (counter == freq_div) begin
				counter <= 0;
				c0 <= ~c0;
			end
			if (locked_reg) begin
				locked <= 1;
			end else if (c0 == 1 && ~locked_reg) begin
				locked_reg <= 1;
			end
		end
	end

endmodule

