module float_arithmetic (
  input [31:0] num1,
  input [31:0] num2,
  input [1:0] ctrl,
  output [31:0] result,
  output flag
);

  // Define constants for IEEE 754 format
  parameter EXPONENT_SIZE = 8;
  parameter MANTISSA_SIZE = 23;
  parameter BIAS = 127;
  parameter EXPONENT_MASK = {EXPONENT_SIZE{1'b1}};
  parameter MANTISSA_MASK = {MANTISSA_SIZE{1'b1}};

  // Define variables for input numbers
  reg sign1, sign2;
  reg [EXPONENT_SIZE-1:0] exponent1, exponent2;
  reg [MANTISSA_SIZE-1:0] mantissa1, mantissa2;

  // Define variables for intermediate calculations
  reg [EXPONENT_SIZE-1:0] exponent_out;
  reg [MANTISSA_SIZE:0] mantissa_out;
  reg sign_out;

  // Define variables for exception handling
  reg overflow, underflow, divide_by_zero;

  // Convert input numbers to IEEE 754 format
  assign sign1 = num1[31];
  assign sign2 = num2[31];
  assign exponent1 = num1[30:23] - BIAS;
  assign exponent2 = num2[30:23] - BIAS;
  assign mantissa1 = {1'b1, num1[22:0]};
  assign mantissa2 = {1'b1, num2[22:0]};

  // Perform requested operation on input numbers
  always @(*) begin
    case (ctrl)
      2'b00: // Addition
        begin
          if (exponent1 > exponent2) begin
            exponent_out = exponent1;
            mantissa2 = {1'b0, mantissa2};
            mantissa2 = mantissa2 >> (exponent1 - exponent2);
          end else begin
            exponent_out = exponent2;
            mantissa1 = {1'b0, mantissa1};
            mantissa1 = mantissa1 >> (exponent2 - exponent1);
          end
          if (sign1 == sign2) begin
            mantissa_out = mantissa1 + mantissa2;
            sign_out = sign1;
          end else begin
            mantissa_out = mantissa1 - mantissa2;
            sign_out = (mantissa1 > mantissa2) ? sign1 : sign2;
          end
        end
      2'b01: // Subtraction
        begin
          num2[31] = ~num2[31];
          ctrl = 2'b00;
          mantissa_out = {1'b0, num2};
          num2[31] = ~num2[31];
        end
      2'b10: // Multiplication
        begin
          exponent_out = exponent1 + exponent2 - BIAS;
          mantissa_out = mantissa1 * mantissa2;
          sign_out = sign1 ^ sign2;
        end
      2'b11: // Division
        begin
          if (mantissa2 == 0) begin
            divide_by_zero = 1;
            exponent_out = EXPONENT_MASK;
            mantissa_out = MANTISSA_MASK;
            sign_out = 0;
          end else begin
            exponent_out = exponent1 - exponent2 + BIAS;
            mantissa_out = mantissa1 / mantissa2;
            sign_out = sign1 ^ sign2;
          end
        end
      default:
        begin
          exponent_out = EXPONENT_MASK;
          mantissa_out = MANTISSA_MASK;
          sign_out = 0;
        end
    endcase
  end

  // Check for exceptions
  always @(*) begin
    overflow = (exponent_out >= EXPONENT_MASK);
    underflow = (exponent_out <= 0);
  end

  // Convert result back to IEEE 754 format
  always @(*) begin
    if (overflow) begin
      exponent_out = EXPONENT_MASK;
      mantissa_out = MANTISSA_MASK;
      sign_out = 0;
    end else if (underflow) begin
      exponent_out = 0;
      mantissa_out = 0;
      sign_out = 0;
    end else if (divide_by_zero) begin
      // Do nothing
    end else begin
      // Normalize mantissa
      while (mantissa_out[MANTISSA_SIZE+1] == 1'b0) begin
        mantissa_out = {mantissa_out[MANTISSA_SIZE:1], 1'b0};
        exponent_out = exponent_out - 1;
      end
      // Round mantissa
      if (mantissa_out[MANTISSA_SIZE] == 1'b1) begin
        mantissa_out = mantissa_out + {1'b0, MANTISSA_MASK};
        if (mantissa_out[MANTISSA_SIZE+1] == 1'b1) begin
          exponent_out = exponent_out + 1;
          mantissa_out = {mantissa_out[MANTISSA_SIZE:1], 1'b0};
        end
      end
    end
    result[31] = sign_out;
    result[30:23] = exponent_out + BIAS;
    result[22:0] = mantissa_out[MANTISSA_SIZE-1:0];
  end

  // Set flag output if an exception occurred
  assign flag = overflow || underflow || divide_by_zero;

endmodule

module testbench;

    // Parameters
    parameter A_SIGNED = 0;
    parameter B_SIGNED = 0;
    parameter A_WIDTH = 8;
    parameter B_WIDTH = 4;
    parameter Y_WIDTH = 8;

    // Inputs
    reg [A_WIDTH-1:0] A;
    reg [B_WIDTH-1:0] B;

    // Outputs
    wire [Y_WIDTH-1:0] Y;

    // Instantiate the module to be tested
    _90_shift_shiftx dut (
        .A(A),
        .B(B),
        .Y(Y)
    );

    // Clock
    reg clk = 0;
    always #10 clk = ~clk;

    // Stimulus
    initial begin
        A = 8'hFF; // Set A to all ones
        B = 4'b0010; // Shift A two bits to the right
        #100;
        $display("A = %b, B = %b, Y = %b", A, B, Y);
        // Expected output: 8'h3F (111111 >> 2 = 00001111 = 8'h3F)
        B = 4'b1010; // Shift A two bits to the left, with sign extension
        #100;
        $display("A = %b, B = %b, Y = %b", A, B, Y);
        // Expected output: 8'hFC (11111111 << 2 = 11111100 = 8'hFC)
        B = 4'b1001; // Shift A one bit to the left, without sign extension
        #100;
        $display("A = %b, B = %b, Y = %b", A, B, Y);
        // Expected output: 8'hFE (11111111 << 1 = 11111110 = 8'hFE)
        B = 4'b0111; // Shift A three bits to the right, without sign extension
        #100;
        $display("A = %b, B = %b, Y = %b", A, B, Y);
        // Expected output: 8'h1F (11111111 >> 3 = 00011111 = 8'h1F)
        $finish;
    end

endmodule

