module rising_edge_detector (
    input signal,
    output reg edge
);

    reg prev_signal;

    always @ (posedge clk, negedge reset) begin
        if (!reset) begin
            edge <= 0;
            prev_signal <= 0;
        end else begin
            if (signal & !prev_signal) begin
                edge <= 1;
            end else begin
                edge <= 0;
            end
            prev_signal <= signal;
        end
    end

