module top_module (
    input clk,
    input [1:0] reset,
    input [1:0] ce,
    input ctrl,
    output [3:0] count1,
    output [3:0] count2,
    output [3:0] sum
);

    // Instantiate two 4-bit counters with asynchronous reset and clock enable inputs
    reg [3:0] counter1;
    reg [3:0] counter2;

    always @(posedge clk or negedge reset[0]) begin
        if (~reset[0]) begin
            counter1 <= 4'b0000;
        end else if (ce[0]) begin
            counter1 <= counter1 + 1;
        end
    end

    always @(posedge clk or negedge reset[1]) begin
        if (~reset[1]) begin
            counter2 <= 4'b0000;
        end else if (ce[1]) begin
            counter2 <= counter2 + 1;
        end
    end

    // Instantiate a functional module that adds the two counter outputs
    reg [3:0] counter_sum;

    always @(*) begin
        counter_sum = counter1 + counter2;
    end

    // Assign outputs
    assign count1 = counter1;
    assign count2 = counter2;
    assign sum = counter_sum;

endmodule

module Debouncer (
  input sw,
  output deb
);

parameter clk_period = 10; // clock period in ns.

reg [1:0] state;
reg debounced;
reg [31:0] debounce_timer;

always @(posedge clk) begin
  case (state)
    2'b00: begin // waiting for switch to stabilize
      debounce_timer <= debounce_timer + 1;
      if (sw != debounced) begin
        debounce_timer <= 0;
        state <= 2'b01;
      end
    end
    2'b01: begin // waiting for debounce time
      debounce_timer <= debounce_timer + 1;
      if (debounce_timer >= (10 * clk_period)) begin
        debounced <= sw;
        state <= 2'b10;
      end
    end
    2'b10: begin // output debounced signal
      deb <= debounced;
      if (sw != debounced) begin
        debounce_timer <= 0;
        state <= 2'b01;
      end
    end
  endcase
end

endmodule

module div_clk (
    input clk_in,
    input clk_type,
    input reset,
    output reg clk_out
);

reg clock_div2;
reg [2:0] rst_reg;

always @(posedge clk_in) 
    clock_div2 <= ~clock_div2;

always @(posedge clk_in) begin
    rst_reg[0] <= reset;
    rst_reg[1] <= rst_reg[0] & reset;
    rst_reg[2] <= rst_reg[1] & rst_reg[0] & reset;
end

always @(posedge clk_in or posedge rst_reg[2]) begin
    if (reset == 1'b1)
        clk_out <= 1'b0;
    else if (reset == 1'b0) begin
        if (clk_type == 1'b1)
            clk_out <= clock_div2;
        else
            clk_out <= clk_in;
    end
end

endmodule

