module fsm_binary_to_gray (
  input clk,
  input [3:0] binary,
  output reg [3:0] gray
);

  reg [3:0] state;

  always @(posedge clk) begin
    case(state)
      4'b0000: state <= binary;
      4'b0001: state <= binary ^ 4'b0011;
      4'b0010: state <= binary ^ 4'b0010;
      4'b0011: state <= binary ^ 4'b0001;
      4'b0100: state <= binary ^ 4'b0100;
      4'b0101: state <= binary ^ 4'b0110;
      4'b0110: state <= binary ^ 4'b0101;
      4'b0111: state <= binary ^ 4'b0111;
      4'b1000: state <= binary ^ 4'b1000;
      4'b1001: state <= binary ^ 4'b1010;
      4'b1010: state <= binary ^ 4'b1001;
      4'b1011: state <= binary ^ 4'b1011;
      4'b1100: state <= binary ^ 4'b1101;
      4'b1101: state <= binary ^ 4'b1111;
      4'b1110: state <= binary ^ 4'b1100;
      4'b1111: state <= binary;
    endcase
  end

  always @(*) begin
    case(state)
      4'b0000: gray = 4'b0000;
      4'b0001: gray = 4'b0001;
      4'b0010: gray = 4'b0011;
      4'b0011: gray = 4'b0010;
      4'b0100: gray = 4'b0110;
      4'b0101: gray = 4'b0111;
      4'b0110: gray = 4'b0101;
      4'b0111: gray = 4'b0100;
      4'b1000: gray = 4'b1100;
      4'b1001: gray = 4'b1101;
      4'b1010: gray = 4'b1111;
      4'b1011: gray = 4'b1110;
      4'b1100: gray = 4'b1010;
      4'b1101: gray = 4'b1011;
      4'b1110: gray = 4'b1001;
      4'b1111: gray = 4'b1000;
    endcase
  end

endmodule

module sha256(
    input clk,
    input rst_n,
    input [255:0] p_mosi,
    input p_valid,
    output sha_init,
    output sha_next,
    output sha_mode,
    output [511:0] sha_block
);

    reg [1:0] pValidPrev = 2'b11;
    reg [511:0] sha_block_reg;
    reg sha_init_reg;
    reg sha_next_reg;

    assign sha_init = sha_init_reg;
    assign sha_next = sha_next_reg;
    assign sha_mode = 1'b1;
    assign sha_block = sha_block_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pValidPrev <= 2'b11;
            sha_init_reg <= 1'b0;
            sha_next_reg <= 1'b0;
            sha_block_reg <= {256'h0, 1'b1, 255'h80};
        end
        else begin
            pValidPrev[1] <= pValidPrev[0];
            pValidPrev[0] <= p_valid;

            if (p_valid && !pValidPrev[1]) begin
                sha_init_reg <= 1'b1;
            end
            else begin
                sha_init_reg <= 1'b0;
            end

            if (sha_next_reg) begin
                sha_next_reg <= 1'b0;
            end
            else if (sha_block_reg[511] && !sha_next_reg) begin
                sha_next_reg <= 1'b1;
            end

            sha_block_reg <= {p_mosi, 1'b1, 255'h80};
        end
    end

endmodule

