module control_logic(
    input select,
    input [2:0] a,
    input [2:0] b,
    output [2:0] out_or_bitwise,
    output out_or_logical,
    output [5:0] out_not
);

    wire [2:0] bitwise_out;
    wire logical_out;

    bitwise_or_logical_or bitwise_or_logical_or_inst(
        .a(a),
        .b(b),
        .out_bitwise(bitwise_out),
        .out_logical(logical_out)
    );

    inverse inverse_inst(
        .a(a),
        .b(b),
        .out_not(out_not)
    );

    always @(*) begin
        case (select)
            2'b00: begin
                out_or_bitwise = bitwise_out;
                out_or_logical = logical_out;
                out_not = 6'b0;
            end
            2'b01: begin
                out_or_bitwise = 3'b0;
                out_or_logical = 1'b0;
                out_not = ~{a,b};
            end
            2'b10: begin
                out_or_bitwise = a | b;
                out_or_logical = (a != 0) || (b != 0);
                out_not = 6'b0;
            end
            default: begin
                out_or_bitwise = 3'b0;
                out_or_logical = 1'b0;
                out_not = 6'b0;
            end
        endcase
    end

endmodule

