module DisplayPort (
  input [23:0] px_data,
  input hsync,
  input vsync,
  input clk,
  output reg [9:0] dp_data,
  output reg dp_clk
);

  // 8b/10b encoding table
  reg [9:0] encoding_table [255:0];

  // PLL parameters
  parameter integer CLKIN_FREQ = 100; // MHz
  parameter integer CLKOUT_FREQ = 2700; // MHz
  parameter integer CLKFB_DIV = 10;
  parameter integer CLKOUT_DIV = 1;

  // PLL signals
  wire locked;
  wire [31:0] pll_fb;

  // Serializer parameters
  parameter integer SERIAL_RATE = 2700; // Mbps
  parameter integer BIT_RATE = 270; // MHz
  parameter integer SYMBOL_RATE = 135; // MHz
  parameter integer SYMBOLS_PER_CLOCK = 5;

  // Serializer signals
  reg [9:0] serial_data;
  reg [4:0] symbol_count;
  reg [9:0] symbol_data;

  // Control signals
  reg h_active;
  reg v_active;
  reg h_sync;
  reg v_sync;
  reg h_blank;
  reg v_blank;

  // Initialize encoding table
  initial begin
    // TODO: fill in encoding table
  end

  // Generate PLL clock
  wire pll_clk;
  pll #(
    .CLKIN_FREQ(CLKIN_FREQ),
    .CLKOUT_FREQ(CLKOUT_FREQ),
    .CLKFB_DIV(CLKFB_DIV),
    .CLKOUT_DIV(CLKOUT_DIV)
  ) u_pll (
    .CLKIN(clk),
    .CLKFB(pll_fb),
    .CLKOUT(pll_clk),
    .LOCKED(lock)
  );

  // Generate serializer clock
  reg [31:0] serial_count;
  always @(posedge pll_clk) begin
    serial_count <= serial_count + BIT_RATE;
    if (serial_count >= SERIAL_RATE) begin
      serial_count <= serial_count - SERIAL_RATE;
      serial_data <= {px_data, 1'b0}; // add control bit for 8b/10b encoding
      symbol_count <= symbol_count + 1;
      if (symbol_count >= SYMBOLS_PER_CLOCK) begin
        symbol_count <= 0;
        symbol_data <= encoding_table[serial_data[15:8]];
        dp_data <= symbol_data;
      end
    end
  end

  // Generate control signals
  always @(posedge pll_clk) begin
    if (hsync) begin
      h_active <= 1;
      h_blank <= 0;
      h_sync <= 1;
    end else if (h_active) begin
      h_sync <= 0;
      if (symbol_count == 0) begin
        h_active <= 0;
        h_blank <= 1;
      end
    end

    if (vsync) begin
      v_active <= 1;
      v_blank <= 0;
      v_sync <= 1;
    end else if (v_active) begin
      v_sync <= 0;
      if (h_blank && symbol_count == 0) begin
        v_active <= 0;
        v_blank <= 1;
      end
    end
  end

  // Generate DisplayPort clock
