module cla_adder_32bit(
    input [31:0] a,
    input [31:0] b,
    input cin,
    output [31:0] sum,
    output cout
);

wire [31:0] g;
wire [31:0] p;
wire [31:0] c;

assign g = a & b;
assign p = a ^ b;
assign c[0] = cin;

genvar i;
generate
    for (i = 0; i < 31; i = i + 1) begin : gen
        assign c[i+1] = g[i] | (p[i] & c[i]);
        assign sum[i] = p[i] ^ c[i];
    end
endgenerate

assign cout = g[31] | (p[31] & c[31]);

endmodule

module CIC_filter (
  input [R-1:0] in,
  output [L-1:0] out
);

parameter N = 2; // decimation factor
parameter M = 3; // number of stages
parameter R = 16; // number of bits in the input signal
parameter L = 8; // number of bits in the output signal

// Define the integrator stage
reg [R-1:0] integrator_out [0:M-1];
integer i;
always @ (posedge clk) begin
  for (i = 0; i < M; i = i + 1) begin
    integrator_out[i] <= integrator_out[i] + in;
    in <= integrator_out[i];
  end
end

// Define the comb filter stage
reg [R-1:0] comb_out [0:M-1];
integer j;
always @ (posedge clk) begin
  for (j = 0; j < M; j = j + 1) begin
    comb_out[j] <= integrator_out[j] - integrator_out[j+1];
  end
end

// Decimate the input signal
reg [R-1:0] decimated_in;
integer k;
always @ (posedge clk) begin
  for (k = 0; k < N; k = k + 1) begin
    decimated_in <= in;
  end
end

// Cascade the integrator and comb filter stages
reg [R-1:0] cascaded_out;
integer l;
always @ (posedge clk) begin
  cascaded_out <= decimated_in;
  for (l = 0; l < M; l = l + 1) begin
    cascaded_out <= integrator_out[l];
    cascaded_out <= comb_out[l];
  end
end

// Scale and truncate the output signal
reg [L-1:0] scaled_out;
always @ (posedge clk) begin
  scaled_out <= cascaded_out / (2**L);
end

assign out = $round(scaled_out);

endmodule

