module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out
);

reg [9:0] accu_reg;
reg [7:0] data_reg [7:0];
reg [2:0] stage;

assign ready_a = (stage == 0) ? 1'b1 : 1'b0;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        accu_reg <= 10'b0;
        valid_b <= 1'b0;
        stage <= 3'b000;
    end
    else begin
        case (stage)
            3'b000: begin
                if (valid_a && ready_b) begin
                    data_reg[0] <= data_in;
                    stage <= 3'b001;
                end
            end
            3'b001: begin
                if (valid_a && ready_b) begin
                    data_reg[1] <= data_reg[0];
                    data_reg[0] <= data_in;
                    stage <= 3'b010;
                end
            end
            3'b010: begin
                if (valid_a && ready_b) begin
                    data_reg[2] <= data_reg[1];
                    data_reg[1] <= data_reg[0];
                    data_reg[0] <= data_in;
                    stage <= 3'b011;
                end
            end
            3'b011: begin
                if (valid_a && ready_b) begin
                    data_reg[3] <= data_reg[2];
                    data_reg[2] <= data_reg[1];
                    data_reg[1] <= data_reg[0];
                    data_reg[0] <= data_in;
                    stage <= 3'b100;
                end
            end
            3'b100: begin
                if (valid_a && ready_b) begin
                    data_reg[4] <= data_reg[3];
                    data_reg[3] <= data_reg[2];
                    data_reg[2] <= data_reg[1];
                    data_reg[1] <= data_reg[0];
                    data_reg[0] <= data_in;
                    stage <= 3'b101;
                end
            end
            3'b101: begin
                if (valid_a && ready_b) begin
                    data_reg[5] <= data_reg[4];
                    data_reg[4] <= data_reg[3];
                    data_reg[3] <= data_reg[2];
                    data_reg[2] <= data_reg[1];
                    data_reg[1] <= data_reg[0];
                    data_reg[0] <= data_in;
                    stage <= 3'b110;
                end
            end
            3'b110: begin
                if (valid_a && ready_b) begin
                    data_reg[6] <= data_reg[5];
                    data_reg[5] <= data_reg[4];
                    data_reg[4] <= data_reg[3];
                    data_reg[3] <= data_reg[2];
                    data_reg[2] <= data_reg[1];
                    data_reg[1] <= data_reg[0];
                    data_reg[0] <= data_in;
                    stage <= 3'b111;
                end
            end
            3'b111: begin
                if (valid_a && ready_b) begin
                    data_reg[7] <= data_reg[6];
                    data_reg[6] <= data_reg[5];
                    data_reg[5] <= data_reg[4];
                    data_reg[4] <= data_reg[3];
                    data_reg[3] <= data_reg[2];
                    data_reg[2] <= data_reg[1];
                    data_reg[1] <= data_reg[0];
                    data_reg[0] <= data_in;
                    accu_reg <= accu_reg + data_reg[7];
                    valid_b <= 1'b1;
                    stage <= 3'b000;
                end
            end
        endcase
    end
end

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        data_out <= 10'b0;
    end
    else begin
        if (valid_b && ready_a) begin
            data_out <= accu_reg;
            valid_b <= 1'b0;
        end
    end
end

endmodule

