module top_module (
    input clk,
    input reset,
    input [15:0] A,
    input [15:0] B,
    output reg [3:0] count
);

    // Instantiate the 4x4 matrix multiplier module
    matrix_multiplier mm (
        .clk(clk),
        .reset(reset),
        .A(A),
        .B(B),
        .C(C)
    );

    // Instantiate the binary counter module
    binary_counter bc (
        .clk(clk),
        .reset(reset),
        .in(C),
        .count(count)
    );

    // Declare the output matrix C
    reg [15:0] C;

endmodule

// Define the 4x4 matrix multiplier module
module matrix_multiplier (
    input clk,
    input reset,
    input [15:0] A,
    input [15:0] B,
    output reg [15:0] C
);

    // Declare the internal registers
    reg [3:0] i, j, k;
    reg [15:0] temp;

    always @(posedge clk) begin
        if (reset) begin
            // Reset the output matrix C
            C <= 16'h0000;
        end else begin
            // Perform the matrix multiplication
            for (i = 0; i < 4; i = i + 1) begin
                for (j = 0; j < 4; j = j + 1) begin
                    temp <= 16'h0000;
                    for (k = 0; k < 4; k = k + 1) begin
                        temp <= temp + A[i*4+k] * B[k*4+j];
                    end
                    C[i*4+j] <= temp;
                end
            end
        end
    end

endmodule

// Define the binary counter module
module binary_counter (
    input clk,
    input reset,
    input [15:0] in,
    output reg [3:0] count
);

    always @(posedge clk) begin
        if (reset) begin
            // Reset the counter
            count <= 4'b0000;
        end else begin
            // Count the number of non-zero elements in the input matrix
            count <= {in[0], in[1], in[2], in[3]} +
                     {in[4], in[5], in[6], in[7]} +
                     {in[8], in[9], in[10], in[11]} +
                     {in[12], in[13], in[14], in[15]};
        end
    end

endmodule

module counter (
    input clk,
    input rst,
    output reg [3:0] count
);

    always @(posedge clk) begin
        if (rst) begin
            count <= 4'b0;
        end else if (count == 4'b1111) begin
            count <= 4'b0;
        end else begin
            count <= count + 1;
        end
    end

endmodule

