module PLL (
  input ref_clk,
  input fb_clk,
  output out_clk
);

parameter n = 8; // number of bits in the feedback divider counter
parameter m = 8; // number of bits in the phase detector output

reg [n-1:0] feedback_counter;
reg [m-1:0] phase_difference;
reg [n+m-1:0] vco_control_word;

always @(posedge ref_clk or posedge fb_clk) begin
  // Phase detector
  phase_difference <= (fb_clk ^ ref_clk) ? {m{1'b1}} : {m{1'b0}};

  // Feedback divider
  if (feedback_counter == (2**n - 1)) begin
    feedback_counter <= 0;
  end else begin
    feedback_counter <= feedback_counter + 1;
  end

  // VCO control word
  vco_control_word <= {phase_difference, feedback_counter};
end

// Voltage-controlled oscillator
reg vco_output;
always @(posedge ref_clk or posedge vco_output) begin
  vco_output <= vco_output ^ 1'b1;
end

assign out_clk = vco_output;

endmodule

