always @(posedge clk, negedge areset) begin
  if (!areset) begin
    state <= 4'b0000;
    q <= 4'b0000;
  end else if (ena) begin
    case (state)
      4'b0000: begin
        state <= 4'b0001;
        q <= q + 1;
      end
      4'b0001: begin
        state <= 4'b0010;
        q <= q + 1;
      end
      4'b0010: begin
        state <= 4'b0011;
        q <= q + 1;
      end
      4'b0011: begin
        state <= 4'b0100;
