      end
      4'b0111: begin
        state <= 4'b1000;
        q <= q + 1;
      end
      4'b1000: begin
        state <= 4'b1001;
        q <= q + 1;
      end
      4'b1001: begin
        state <= 4'b1010;
        q <= q + 1;
      end
      4'b1010: begin
        state <= 4'b1011;
