module pulse_counter_serial_transmitter (
    input clk,
    output reg [31:0] cycle,
    output RxD,
    output TxD
);

    // Generate pulse every 5 clock cycles
    reg clk_pulse = 1'b0;
    always @(posedge clk) begin
        if (cycle % 5 == 0) begin
            clk_pulse <= ~clk_pulse;
        end
        cycle <= cycle + 1;
    end

    // Serial transmitter
    parameter comm_clk_frequency = 1_000_000;
    parameter baud_rate = 115_200;
    parameter stop_cycle = 7020;

    reg [671:0] data = 672'h000007ff0000318e7e71441b141fe951b2b0c7dfc791d4646240fc2a2d1b80900020a24dc501ef1599fc48ed6cbac920af75575618e7b1e8eaf0b62a90d1942ea64d250357e9a09c063a47827c57b44e01000000;

    reg serial_send = 0;
    wire serial_busy;
    reg [31:0] data_32 = 0;
    reg [31:0] start_cycle = 0;

    serial_transmit #(.comm_clk_frequency(comm_clk_frequency), .baud_rate(baud_rate)) sertx (.clk(clk), .TxD(RxD), .send(serial_send), .busy(serial_busy), .word(data_32));

    always @(posedge clk) begin
        // Send data every time tx goes idle
        if (cycle > 5 && cycle < stop_cycle && !serial_busy && !serial_send) begin
            serial_send <= 1;
            data_32 <= data[671:640];
            data <= { data[639:0], 32'd0 };
            start_cycle <= cycle;
        end
    end

endmodule

module top_module( 
    input wire [15:0] in,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo,
    output wire parity );

    wire [7:0] in_lo = in[7:0];
    wire [7:0] in_hi = in[15:8];
    wire [7:0] out_lo_parity;
    wire [7:0] out_lo_no_parity;

    // Even parity bit calculation
    wire [7:0] parity_bits;
    wire parity_bit;
    wire [7:0] xor_result;

    assign parity_bits = {in_lo, in_hi} ^ 8'hFF;
    assign xor_result = {parity_bits[0], parity_bits[2], parity_bits[4], parity_bits[6], 4'b0000} ^ 5'b10101;
    assign parity_bit = ~^xor_result;

    // Byte splitter circuit
    assign out_lo_parity = {in_lo, parity_bit};
    assign out_lo_no_parity = in_lo;

    // Multiplexer and decoder for output selection
    assign out_lo = out_lo_no_parity;
    assign out_hi = in_hi;

    // Output even parity bit
    assign parity = parity_bit;

endmodule

module full_synchronizer #(
  parameter WIDTH = 1
)(
  input  wire             clk,
  input  wire             reset,
  input  wire [WIDTH-1:0] datain,
  output wire [WIDTH-1:0] dataout
);
  pipeline_stall #(WIDTH,2) sync (clk, reset, datain, dataout);

  reg [1:0] metastable;
  always @(posedge clk) begin
    if (reset) begin
      metastable <= 2'b00;
    end else begin
      metastable <= {metastable[0], dataout[0]};
    end
  end

  assign dataout = metastable[1:0];
endmodule

module ultrasonic_sensor(
    input clk,
    input rst,
    input [15:0] d_in,
    input cs,
    input [3:0] addr,
    input rd,
    input wr,
    output reg [15:0] d_out,
    output reg trigg,
    output reg echo
);

// Define the state machine states
parameter IDLE = 2'b00;
parameter TRIG = 2'b01;
parameter ECHO = 2'b10;

// Define the state machine signals and variables
reg [1:0] state;
reg [20:0] i;
reg trig_sent;
reg echo_received;

// Assign default values to the output signals
assign trigg = 1'b0;
assign echo = 1'b0;
assign d_out = 16'h0000;

// State machine logic
always @(posedge clk) begin
    if (rst) begin
        state <= IDLE;
        i <= 0;
        trig_sent <= 1'b0;
        echo_received <= 1'b0;
    end
    else begin
        case (state)
            IDLE: begin
                trigg <= 1'b0;
                if (cs && wr && addr == 4'h0) begin
                    trig_sent <= 1'b1;
                    state <= TRIG;
                end
            end
            TRIG: begin
                trigg <= 1'b1;
                if (!trig_sent && !cs && rd && addr == 4'h0) begin
                    echo_received <= 1'b1;
                    state <= ECHO;
                end
            end
            ECHO: begin
                trigg <= 1'b0;
                echo <= 1'b1;
                if (echo_received && !cs && rd && addr == 4'h0) begin
                    d_out <= i;
                    i <= 0;
                    echo_received <= 1'b0;
                    state <= IDLE;
                    echo <= 1'b0;
                end
                else begin
                    i <= i + 1;
                end
            end
        endcase
    end
end

endmodule

module MulSelCtl (notMult, Shifted, Pos, Zero, ACI);

input [2:0] notMult;
output Shifted, Zero, Pos, ACI;

/* Feedthrough */
