/* Inverter and AND gate */
ME_INV_A g01 (notMult[2], Negative);
ME_AND2  cz2  (Negative, notSwig, ACI);

/* OR gate */
ME_OR2_B cz1 (notMult[0], notMult[1], notSwig);

/* OR and NAND gates */
ME_OR3_B nzr5 (notMult[2], notMult[0], notMult[1], notPos0);
ME_NAND3 nzr6 (notMult[2], notMult[1], notMult[0], notNeg0);
ME_NAND2_B nzr8 (notNeg0, notPos0, Zero);

/* Connection module */
con1 g00 (notMult[2], Pos);

endmodule

module reset_module(
  input slowest_clk,
  input ext_reset,
  input aux_reset,
  input dcm_locked,
  input debug_sys_rst,
  output reg sys_reset,
  output reg [0:0]bus_struct_reset,
  output reg [0:0]peripheral_reset,
  output reg [0:0]interconnect_reset,
  output reg [0:0]peripheral_aresetn
);

  reg [1:0] reset_state;
  reg [1:0] sync_reset_state;

  always @(posedge slowest_clk) begin
    // Synchronize reset signals to slowest clock
    sync_reset_state <= reset_state;
    if (dcm_locked) begin
      reset_state[0] <= ~ext_reset;
      reset_state[1] <= reset_state[0] & (~aux_reset | sync_reset_state[1]);
    end
  end

  // System reset
  always @(posedge slowest_clk) begin
    if (debug_sys_rst) begin
      sys_reset <= 1'b1;
    end else if (sync_reset_state[1]) begin
      sys_reset <= 1'b1;
    end else begin
      sys_reset <= 1'b0;
    end
  end

  // Bus structure reset
  always @(posedge slowest_clk) begin
    if (sync_reset_state[1]) begin
      bus_struct_reset <= 1'b1;
    end else begin
      bus_struct_reset <= 1'b0;
    end
  end

  // Peripheral reset
  always @(posedge slowest_clk) begin
    if (sync_reset_state[1]) begin
      peripheral_reset <= 1'b1;
    end else begin
      peripheral_reset <= 1'b0;
    end
  end

  // Interconnect reset
  always @(posedge slowest_clk) begin
    if (sync_reset_state[1]) begin
      interconnect_reset <= 1'b1;
    end else begin
      interconnect_reset <= 1'b0;
    end
  end

  // Peripheral active reset
  always @(posedge slowest_clk) begin
    if (sync_reset_state[1]) begin
      peripheral_aresetn <= 1'b0;
    end else begin
      peripheral_aresetn <= 1'b1;
    end
  end

endmodule

module shift_register_OR (
    input clk,
    input reset,            // Asynchronous reset
    input [3:0] d,
    input enable,
    output [3:0] q,
    output [3:0] or_output
);

    reg [3:0] shift_reg;
    reg [3:0] or_result;

    always @(negedge clk) begin
        if (reset) begin
            shift_reg <= 4'b0;
        end else if (enable) begin
            shift_reg <= {d, shift_reg[3:1]};
        end
    end

    assign q = shift_reg;
    assign or_output = or_result;

    always @(shift_reg or d or enable) begin
        or_result = shift_reg | d;
    end

endmodule

