module boot_rom (
    input wire clk,
    input wire rst,
    output wire [31:0] data_out,
    output reg err
);

// Define memory contents
reg [31:0] mem [0:3];
initial begin
    mem[0] = 32'h20000000; // Configure UART
    mem[1] = 32'h30000041; // Send 'A'
    mem[2] = 32'h30000042; // Send 'B'
    mem[3] = 32'h30000043; // Send 'C'
end

// Define ROM address counter
reg [1:0] addr;

// Define UART configuration
reg [31:0] uart_config = 32'h00000000;
initial begin
    uart_config[0] = 1; // Enable UART
    uart_config[1] = 0; // 1 stop bit
    uart_config[2] = 0; // No parity
    uart_config[3] = 3; // 8 data bits
end

// Define UART data buffer
reg [7:0] uart_data;

// Define UART read/write flags
reg uart_write;
reg uart_read;

// Define UART state machine
reg [1:0] uart_state;
localparam UART_IDLE = 2'b00;
localparam UART_WRITE = 2'b01;
localparam UART_READ = 2'b10;
always @(posedge clk) begin
    case (uart_state)
        UART_IDLE: begin
            if (uart_write) begin
                uart_data <= data_out[7:0];
                uart_state <= UART_WRITE;
            end else if (uart_read) begin
                uart_state <= UART_READ;
            end
        end
        UART_WRITE: begin
            uart_data <= {1'b0, uart_data[7:1]};
            if (uart_data[0]) begin
                uart_state <= UART_IDLE;
            end
        end
        UART_READ: begin
            data_out <= {24'h000000, uart_data};
            uart_state <= UART_IDLE;
        end
    endcase
end

// Define boot ROM state machine
reg [1:0] state;
localparam BOOT_INIT = 2'b00;
localparam BOOT_LOAD = 2'b01;
localparam BOOT_RUN = 2'b10;
always @(posedge clk) begin
    case (state)
        BOOT_INIT: begin
            addr <= 2'b00;
            err <= 1'b0;
            state <= BOOT_LOAD;
        end
        BOOT_LOAD: begin
            if (addr == 2'b00) begin
                data_out <= uart_config;
            end else if (addr == 2'b01) begin
                data_out <= mem[0];
            end else if (addr == 2'b10) begin
                data_out <= mem[1];
            end else if (addr == 2'b11) begin
                data_out <= mem[2];
            end
            if (addr == 2'b11) begin
                state <= BOOT_RUN;
            end else begin
                addr <= addr + 1;
            end
        end
        BOOT_RUN: begin
            err <= 1'b0;
        end
    endcase
end

// Define test complete signal
reg test_complete = 1'b0;
initial begin
    @(posedge rst);
    @(negedge rst);
    @(posedge clk);
    state <= BOOT_INIT;
    for (i = 0; i < 4; i = i + 1) begin
        @(posedge clk);
    end
    uart_write <= 1;
    uart_data <= 8'h30;
    for (i = 0; i < 4; i = i + 1) begin
        @(posedge clk);
    end
    uart_write <= 1;
    uart_data <= 8'h31;
    for (i = 0; i < 4; i = i + 1) begin
        @(posedge clk);
    end
    uart_write <= 1;
    uart_data <= 8'h32;
    for (i = 0; i < 4; i = i + 1) begin
        @(posedge clk);
    end
    uart_write <= 1;
    uart_data <= 8'h33;
    for (i = 0; i < 100; i = i + 1) begin
        @(posedge clk);
    end
    uart_write <= 1;
    uart_data <= 8'h41;
    for (i = 0; i < 4; i = i + 1) begin
        @(posedge clk);
    end
    uart_read <= 1;
    for (i = 0; i < 4; i = i + 1) begin
        @(posedge clk);
    end
    uart_write <= 1;
    uart_data <= 8'h42;
    for (i = 0; i < 4; i = i + 1) begin
        @(posedge clk);
    end
    uart_read <= 1;
    for (i = 0; i < 4; i = i + 1) begin
        @(posedge clk);
    end
    uart_write <= 1;
    uart_data <= 8'h43;
    for (i = 0; i < 4; i = i + 1) begin
        @(posedge clk);
    end
    uart_read <= 1;
    for (i = 0; i < 10000; i = i + 1) begin
        @(posedge clk);
    end
    test_complete <= 1'b1;
end

// End of module
endmodule

module MacOverflow #(
