            end
        end
    end

    always @(posedge clk) begin
        if (reset) begin
            seg_count <= 0;
            seg_value <= 7'b1111111;
        end else if (start && !stop) begin
            seg_count <= seg_count + 1;
            if (seg_count == 1) begin
                seg_value <= 7'b0110000; // 0
            end else if (seg_count == 2) begin
                seg_value <= 7'b1111001; // 1
