module adder_4bit (
    aclr,
    clock,
    A,
    B,
    CIN,
    S,
    COUT
);

    input aclr;
    input clock;
    input [3:0] A;
    input [3:0] B;
    input CIN;
    output [3:0] S;
    output COUT;

