    wire [3:0] carry;

    // Instantiate full adders
    full_adder fa0 (
        .A(A[0]),
        .B(B[0]),
        .CIN(CIN),
        .SUM(sum[0]),
        .COUT(carry[0])
    );
    full_adder fa1 (
        .A(A[1]),
        .B(B[1]),
        .CIN(carry[0]),
        .SUM(sum[1]),
        .COUT(carry[1])
    );
    full_adder fa2 (
        .A(A[2]),
        .B(B[2]),
        .CIN(carry[1]),
        .SUM(sum[2]),
        .COUT(carry[2])
    );
    full_adder fa3 (
        .A(A[3]),
        .B(B[3]),
        .CIN(carry[2]),
        .SUM(sum[3]),
        .COUT(COUT)
    );

    // Instantiate registers
    reg [3:0] S_reg;
    always @(posedge clock or negedge aclr) begin
        if (!aclr) begin
            S_reg <= 4'b0;
        end else if (COUT) begin
            S_reg <= sum;
        end
    end

    assign S = S_reg;

