    input [1:0] select,   // 2-bit select input
    input invert,         // Invert output of active module
    input enable,         // Enable input for decoder module
    input [3:0] data_in,  // Input for seven-segment module
    output reg [6:0] seg_out  // 7-segment display output
);

    wire [6:0] decoder_out;
    wire [3:0] seven_seg_out;
    wire active_module_enable;

    // Instantiate decoder module
    decoder decoder_inst (
        .enable(enable),
        .data_in(data_in),
        .data_out(decoder_out)
    );

    // Instantiate seven-segment module
    seven_segment seven_seg_inst (
        .data_in(data_in),
        .data_out(seven_seg_out)
    );

    // Determine active module based on select input
    assign active_module_enable = (select == 2'b00) ? enable : 1'b1;

    always @ (posedge clk) begin
        if (reset) begin
            seg_out <= 7'b0000000;
        end else begin
            if (select == 2'b00) begin
                if (active_module_enable) begin
                    if (invert) begin
                        seg_out <= ~decoder_out;
                    end else begin
                        seg_out <= decoder_out;
                    end
                end else begin
                    seg_out <= 7'b0000000;
                end
            end else begin
                if (invert) begin
                    seg_out <= ~seven_seg_out;
                end else begin
                    seg_out <= seven_seg_out;
                end
            end
        end
    end

endmodule

