// Define the addictive control logic module
module additive_control_logic (
    input wire select,
    input wire [7:0] min_out,
    input wire [15:0] comb_out,
    output wire [15:0] final_out
);

// Choose between the two given modules based on the select input and compute the final output
assign final_out = (select == 1'b0) ? (min_out + comb_out) : (min_out - comb_out);

endmodule

module dp_transmitter (
  input [7:0] vd,
  input clk,
  input rst,
  output reg [7:0] dpd,
  output reg dpc
);

  reg [7:0] encoded_data;
  reg [7:0] fec_data;
  reg [7:0] scrambled_data;
  reg [7:0] dp_data;
  reg [7:0] dp_clock;
  reg [7:0] crc_data;

  // Encoding video data using MLL protocol
  always @ (posedge clk) begin
    if (rst) begin
      encoded_data <= 8'b0;
    end else begin
      encoded_data <= {vd[7], ~vd[7:0]};
    end
  end

  // Implementing Forward Error Correction (FEC)
  always @ (posedge clk) begin
    if (rst) begin
      fec_data <= 8'b0;
    end else begin
      fec_data <= {encoded_data, ~(encoded_data[7:4] ^ encoded_data[3:0])};
    end
  end

  // Scrambling data to ensure DC balance
  always @ (posedge clk) begin
    if (rst) begin
      scrambled_data <= 8'b0;
    end else begin
      scrambled_data <= {fec_data[0], fec_data[7:1] ^ fec_data[6:0]};
    end
  end

  // Generating DisplayPort link data and clock signals
  always @ (posedge clk) begin
    if (rst) begin
      dp_data <= 8'b0;
      dp_clock <= 8'b0;
    end else begin
      dp_data <= scrambled_data;
      dp_clock <= ~dpc;
    end
  end

  // Generating CRC data for error detection
  always @ (posedge clk) begin
    if (rst) begin
      crc_data <= 8'b0;
    end else begin
      crc_data <= {scrambled_data, ~(scrambled_data[7:4] ^ scrambled_data[3:0])};
    end
  end

  // Assigning outputs
  assign dpd = dp_data;
  assign dpc = dp_clock;

endmodule

module dp_receiver (
  input [7:0] dpd,
  input dpc,
  input rst,
  output reg [7:0] vd,
  output reg clk
);

  reg [7:0] descrambled_data;
  reg [7:0] decoded_data;
  reg [7:0] crc_data;
  reg [7:0] corrected_data;

  // Descrambling data to recover original data
  always @ (posedge dpc) begin
    if (rst) begin
      descrambled_data <= 8'b0;
    end else begin
      descrambled_data <= {dpd[0], dpd[7:1] ^ dpd[6:0]};
    end
  end

  // Decoding data using MLL protocol
  always @ (posedge dpc) begin
    if (rst) begin
      decoded_data <= 8'b0;
    end else begin
      decoded_data <= {descrambled_data[7], ~descrambled_data[6:0]};
    end
  end

  // Implementing Forward Error Correction (FEC)
  always @ (posedge dpc) begin
    if (rst) begin
      crc_data <= 8'b0;
      corrected_data <= 8'b0;
    end else begin
      crc_data <= {decoded_data[7:4] ^ decoded_data[3:0]};
      if (crc_data == 8'b0) begin
        corrected_data <= decoded_data[7:1];
      end else begin
        corrected_data <= {decoded_data[7], ~decoded_data[6:0]};
      end
    end
  end

  // Assigning outputs
  always @ (posedge dpc) begin
    if (rst) begin
      vd <= 8'b0;
      clk <= 1'b0;
    end else begin
      vd <= corrected_data;
      clk <= ~dpc;
    end
  end

endmodule

module signed_mult (
    input  wire        clk,
    input  wire [ 7:0] A,
    input  wire [ 7:0] B,
    output reg  [15:0] Z
);

    reg [7:0] A_abs;
    reg [7:0] B_abs;
    reg        A_sign;
    reg        B_sign;

    always @(*) begin
        A_abs = (A < 0) ? (~A + 1) : A;
        B_abs = (B < 0) ? (~B + 1) : B;
        A_sign = (A < 0);
        B_sign = (B < 0);
    end

    reg [15:0] prod;
    reg [23:0] prod_shifted;

    always @(posedge clk) begin
        prod = A_abs * B_abs;
        prod_shifted = {prod, 8'b0};
        if (A_sign ^ B_sign) begin
            Z <= (~prod_shifted) + 1;
        end else begin
            Z <= prod_shifted;
        end
    end

endmodule

