module edge_detect_pipeline (
  input               clk,
  input               rst_n,
  input               a,
  input               delay,
  output reg          rise,
  output reg          down
);

  parameter           PIPELINE_DEPTH = 2;
  reg [PIPELINE_DEPTH-1:0] pipe_a;
  reg [PIPELINE_DEPTH-1:0] pipe_diff;
  reg                 prev_a;
  reg                 prev_diff;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      pipe_a <= {PIPELINE_DEPTH{1'b0}};
      pipe_diff <= {PIPELINE_DEPTH{1'b0}};
      prev_a <= 1'b0;
      prev_diff <= 1'b0;
      rise <= 1'b0;
      down <= 1'b0;
    end else begin
      pipe_a <= {pipe_a[PIPELINE_DEPTH-2:0], a};
      pipe_diff <= {pipe_diff[PIPELINE_DEPTH-2:0], a ^ prev_a};
      prev_a <= a;
      prev_diff <= pipe_diff[PIPELINE_DEPTH-1];
      rise <= (pipe_diff[PIPELINE_DEPTH-1] == 1'b1) && (pipe_a[PIPELINE_DEPTH-1] == 1'b1) && (pipe_a[PIPELINE_DEPTH-1-delay] == 1'b0);
      down <= (pipe_diff[PIPELINE_DEPTH-1] == 1'b1) && (pipe_a[PIPELINE_DEPTH-1] == 1'b0) && (pipe_a[PIPELINE_DEPTH-1-delay] == 1'b1);
    end
  end

endmodule

module uart(
   input wire clk,
   input wire resetq,

   output wire uart_busy,       // High means UART is transmitting
   output reg uart_tx,          // UART transmit wire

   input wire uart_wr_i,        // Raise to transmit byte
   input wire [7:0] uart_dat_i
);
  reg [3:0] bitcount;           // 0 means idle, so this is a 1-based counter
  reg [8:0] shifter;

  assign uart_busy = |bitcount;
  wire sending = |bitcount;

  wire ser_clk;

  baudgen _baudgen(
    .clk(clk),
    .ser_clk(ser_clk));

  always @(negedge resetq or posedge clk)
  begin
    if (!resetq) begin
      uart_tx <= 1;
      bitcount <= 0;
      shifter <= 0;
    end else begin
      if (uart_wr_i) begin
        { shifter, uart_tx } <= { uart_dat_i[7:0], 1'b0, 1'b1 };
        bitcount <= 1 + 8 + 1;    // 1 start, 8 data, 1 stop
      end else if (ser_clk & sending) begin
        { shifter, uart_tx } <= { 1'b1, shifter };
        bitcount <= bitcount - 4'd1;
      end
    end
  end

endmodule

module multiplier (
  input [n-1:0] a,
  input [n-1:0] b,
  output [n-1:0] result
);

parameter n = 8; // number of bits in the input and output signals
parameter signed_mode = 1; // 1 for signed multiplication, 0 for unsigned multiplication.

reg [2*n-1:0] signed_a, signed_b;
wire [2*n-1:0] signed_result;

assign signed_result = signed_a * signed_b;

always @(*) begin
  if (signed_mode == 1) begin
    signed_a = {a[n-1], {n-1{a[n-1]}}, a};
    signed_b = {b[n-1], {n-1{b[n-1]}}, b};
    result = signed_result[n-1:0];
  end else begin
    result = a * b;
  end
end

endmodule

module reset_synchronizer (
    input reset_n,
    input clk,
    output [NUM_RESET_OUTPUT-1:0] reset_n_sync
);

parameter RESET_SYNC_STAGES = 4;
parameter NUM_RESET_OUTPUT = 1;

reg [RESET_SYNC_STAGES+NUM_RESET_OUTPUT-2:0] reset_reg /*synthesis dont_merge */;

generate
genvar i;
    for (i=0; i<RESET_SYNC_STAGES+NUM_RESET_OUTPUT-1; i=i+1) begin: reset_stage
        always @(posedge clk or negedge reset_n) begin
            if (~reset_n) begin
                reset_reg[i] <= 1'b0;
            end else begin
                if (i==0) begin
                    reset_reg[i] <= 1'b1;
                end else if (i < RESET_SYNC_STAGES) begin
                    reset_reg[i] <= reset_reg[i-1];
                end else begin
                    reset_reg[i] <= reset_reg[RESET_SYNC_STAGES-2];
                end
            end
        end
    end
endgenerate

assign reset_n_sync = reset_reg[RESET_SYNC_STAGES+NUM_RESET_OUTPUT-2:RESET_SYNC_STAGES-1];

endmodule

