            sbuf[0] <= SPI_MOSI;
            cnt <= cnt + 1;

            if (cnt == 7) begin
                cmd[7:1] <= sbuf;
                cmd[0] <= SPI_MOSI;
            end

            if (cnt == 8) begin
                if (cmd == 4) begin
                    kbd_mouse_type <= 2'b00;
                end else if (cmd == 5) begin
                    kbd_mouse_type <= 2'b10;
                end else if (cmd == 6) begin
                    kbd_mouse_type <= 2'b11;
                end
            end

            if (cnt == 15) begin
                if (cmd == 1) begin
                    but_sw[3:1] <= sbuf[2:0];
                    but_sw[0] <= SPI_MOSI;
                end else if (cmd == 2) begin
                    joystick0[5:1] <= sbuf[4:0];
                    joystick0[0] <= SPI_MOSI;
                end else if (cmd == 3) begin
                    joystick1[5:1] <= sbuf[4:0];
                    joystick1[0] <= SPI_MOSI;
                end else if (cmd == 4 || cmd == 5 || cmd == 6) begin
                    kbd_mouse_data[7:1] <= sbuf[6:0];
                    kbd_mouse_data[0] <= SPI_MOSI;
                    kbd_mouse_strobe <= 1;
                end
            end

            if (cmd == 4) begin
                if (cnt == 23) begin
                    kbd_mouse_data[7:1] <= sbuf[6:0];
                    kbd_mouse_data[0] <= SPI_MOSI;
                    kbd_mouse_strobe <= 1;
                    kbd_mouse_type <= 2'b01;
                end else if (cnt == 31) begin
                    mouse_buttons[2:1] <= sbuf[1:0];
                    mouse_buttons[0] <= SPI_MOSI;
                end
            end
        end
    end

    always @(joystick0, joystick1, CORE_TYPE) begin
        if (CORE_TYPE == 0) begin
            JOY0 <= ~joystick0;
            JOY1 <= ~joystick1;
        end else if (CORE_TYPE == 1) begin
            JOY0 <= {3'b0, joystick0};
            JOY1 <= {3'b0, joystick1};
        end else if (CORE_TYPE == 2) begin
            JOY0 <= ~joystick0;
            JOY1 <= ~joystick1;
        end
    end

endmodule

