module binary_adder (
    input [3:0] A,
    input [3:0] B,
    input cin,
    input RST,
    output [3:0] S,
    output cout
);

    reg [3:0] S_reg;
    wire [3:0] A_xor_B;
    wire [3:0] A_and_B;
    wire [3:0] A_xor_B_xor_cin;
    wire [3:0] A_and_B_or_cin;
    wire [3:0] carry_out;

    assign A_xor_B = A ^ B;
    assign A_and_B = A & B;
    assign A_xor_B_xor_cin = A_xor_B ^ cin;
    assign A_and_B_or_cin = A_and_B | cin;
    assign S = S_reg;

    // full adder for the least significant bit
    full_adder FA0 (
        .a(A[0]),
        .b(B[0]),
        .cin(cin),
        .sum(S_reg[0]),
        .cout(carry_out[0])
    );

    // full adder for the remaining bits
    genvar i;
    generate
        for (i = 1; i < 4; i = i + 1) begin : gen_full_adder
            full_adder FA (
                .a(A[i]),
                .b(B[i]),
                .cin(carry_out[i-1]),
                .sum(S_reg[i]),
                .cout(carry_out[i])
            );
        end
    endgenerate

    // reset logic
    always @ (posedge RST) begin
        S_reg <= 4'b0;
    end

    // carry-out logic
    assign cout = carry_out[3];

endmodule

module full_adder (
    input a,
    input b,
    input cin,
    output sum,
    output cout
);

    assign sum = a ^ b ^ cin;
    assign cout = (a & b) | (a & cin) | (b & cin);

endmodule

module fifo (
  input clk,
  input reset,
  input write_en,
  input [data_width-1:0] data_in,
  input read_en,
  output [data_width-1:0] data_out
);

parameter depth = 8; // depth of the memory block
parameter data_width = 8; // width of the data

reg [data_width-1:0] mem [0:depth-1]; // data storage array
reg [log2(depth)-1:0] write_ptr = 0; // write pointer
reg [log2(depth)-1:0] read_ptr = 0; // read pointer
reg [log2(depth)-1:0] count = 0; // number of data items in the memory block

always @(posedge clk) begin
  if (reset) begin
    write_ptr <= 0;
    read_ptr <= 0;
    count <= 0;
  end else begin
    if (write_en && count < depth) begin
      mem[write_ptr] <= data_in;
      write_ptr <= write_ptr + 1;
      count <= count + 1;
    end
    if (read_en && count > 0) begin
      data_out <= mem[read_ptr];
      read_ptr <= read_ptr + 1;
      count <= count - 1;
    end
  end
end

endmodule

