module HMAC (
  input [n-1:0] message,
  input [k-1:0] key,
  output [h-1:0] hmac,
  output valid
);

parameter n = 64; // number of bits in the message
parameter k = 128; // number of bits in the secret key
parameter h = 256; // number of bits in the authentication code

// Padding constants
localparam BLOCK_SIZE = 512;
localparam IPAD = 32'h36363636;
localparam OPAD = 32'h5c5c5c5c;

// Padded message and key
reg [BLOCK_SIZE-1:0] padded_message;
reg [BLOCK_SIZE-1:0] padded_key;

// Inner and outer padding
reg [BLOCK_SIZE-1:0] inner_padding;
reg [BLOCK_SIZE-1:0] outer_padding;

// Hash values
reg [h-1:0] hash1;
reg [h-1:0] hash2;

// HMAC computation
always @(*) begin
  // Pad message and key
  padded_message = {message, {BLOCK_SIZE-n{1'b0}}};
  padded_key = {key, {BLOCK_SIZE-k{1'b0}}};

  // Compute inner and outer padding
  inner_padding = padded_key ^ {BLOCK_SIZE{IPAD}};
  outer_padding = padded_key ^ {BLOCK_SIZE{OPAD}};

  // Concatenate inner padding with padded message and hash
  hash1 = sha256_function({inner_padding, padded_message});

  // Concatenate hash1 with outer padding and hash again
  hash2 = sha256_function({outer_padding, hash1});

  // Set HMAC output
  hmac = hash2;
end

// Check if computed HMAC matches the expected HMAC
assign valid = (hmac == expected_hmac);

endmodule

