module adder_shift_or(
    input clk,
    input [99:0] A,
    input [99:0] B,
    input C_in,
    input [5:0] Shift,
    input [99:0] In,
    output reg [99:0] Sum,
    output reg C_out,
    output reg [99:0] Out
);

    // Define internal wires and registers
    wire [99:0] shifted_A;
    wire [99:0] shifted_B;
    reg [99:0] shifted_In;
    reg [99:0] shifted_Sum;
    reg shifted_C_out;
    reg [3:0] ripple_carry_out;
    reg [99:0] or_out;

    // Barrel shifter
    always @ (posedge clk) begin
        case (Shift[1:0])
            2'b00: begin // No shift
                shifted_A = A;
                shifted_B = B;
                shifted_In = In;
                shifted_Sum = Sum;
                shifted_C_out = C_out;
            end
            2'b01: begin // Shift left
                shifted_A = {A[Shift[5:0]], A[99:Shift[5:0]+1]};
                shifted_B = {B[Shift[5:0]], B[99:Shift[5:0]+1]};
                shifted_In = {In[Shift[5:0]], In[99:Shift[5:0]+1]};
                shifted_Sum = {Sum[Shift[5:0]], Sum[99:Shift[5:0]+1]};
                shifted_C_out = Sum[Shift[5:0]-1];
            end
            2'b10: begin // Shift right
                shifted_A = {A[99-Shift[5:0]+1:0], A[99:99-Shift[5:0]+2]};
                shifted_B = {B[99-Shift[5:0]+1:0], B[99:99-Shift[5:0]+2]};
                shifted_In = {In[99-Shift[5:0]+1:0], In[99:99-Shift[5:0]+2]};
                shifted_Sum = {Sum[99-Shift[5:0]+1:0], Sum[99:99-Shift[5:0]+2]};
                shifted_C_out = Sum[Shift[5:0]];
            end
        endcase
    end

    // 4-bit ripple carry adder
    always @ (posedge clk) begin
        ripple_carry_out[0] = C_in;
        for (i = 0; i < 100; i = i + 4) begin
            ripple_carry_out[i/4+1] = (shifted_A[i:i+3] + shifted_B[i:i+3] + ripple_carry_out[i/4]) > 15;
            shifted_Sum[i:i+3] = shifted_A[i:i+3] + shifted_B[i:i+3] + ripple_carry_out[i/4];
        end
        C_out = ripple_carry_out[25];
        Sum = shifted_Sum;
    end

    // Bitwise OR
    always @ (posedge clk) begin
        or_out = Sum | In;
        Out = or_out;
    end

endmodule

