module astable (
  input clock,
  output pulse
);

parameter frequency = 1; // pulse frequency in Hz
parameter duty_cycle = 50; // pulse duty cycle as a percentage

reg [31:0] count;
reg [31:0] high_time;
reg [31:0] low_time;

assign pulse = (count > high_time);

always @(posedge clock) begin
  count <= count + 1;
  if (count >= (high_time + low_time)) begin
    count <= 0;
  end
end

always @(*) begin
  high_time = (duty_cycle * (1.0 / frequency)) / 2;
  low_time = ((1.0 - duty_cycle) * (1.0 / frequency)) / 2;
end

endmodule

