module memory_controller(rst, clk, ie, de, iaddr, daddr, drw, din, iout, dout);
    input rst, clk, ie, de;
    input [31:0] iaddr, daddr, din;
    input [1:0] drw;
    output [31:0] iout, dout;

    reg [31:0] memory[0:1023]; // 1024 32-bit memory locations
    reg [31:0] idata, ddata;

    assign iout = idata;
    assign dout = ddata;

    always @(posedge clk) begin
        if (rst) begin
            // idle state
            idata <= 0;
            ddata <= 0;
        end else if (ie) begin
            // input operation
            idata <= memory[iaddr];
        end else if (de) begin
            // data operation
            case (drw)
                2'b00: begin
                    // read
                    ddata <= memory[daddr];
                end
                2'b01: begin
                    // write
                    memory[daddr] <= din;
                end
                2'b10: begin
                    // increment
                    ddata <= memory[daddr] + 1;
                    memory[daddr] <= ddata;
                end
                2'b11: begin
                    // decrement
                    ddata <= memory[daddr] - 1;
                    memory[daddr] <= ddata;
                end
                default: begin
                    // invalid operation
                    ddata <= 0;
                end
            endcase
        end
    end
endmodule

