    output reg [3:0] OUT
);

reg [3:0] OUT_reg;
reg direction;

always @(posedge CLK) begin
    if (RESET) begin
        OUT_reg <= 4'b0000;
        direction <= 1'b0;
    end else begin
        if (OUT_reg[2] == 1'b1) begin
            direction <= ~direction;
        end
        if (direction == 1'b0) begin
            OUT_reg <= {OUT_reg[2:0], OUT_reg[3]};
        end else begin
            OUT_reg <= {OUT_reg[1:3], OUT_reg[0]};
        end
    end
end

assign OUT = OUT_reg;

endmodule

module ConvolutionalEncoderAndViterbiDecoder (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 4; // number of input bits
parameter m = 8; // number of output bits

// Convolutional Encoder
reg [n:0] shift_reg;
wire [m-1:0] encoded_bits;

assign encoded_bits[0] = shift_reg[0] ^ shift_reg[1] ^ shift_reg[2] ^ shift_reg[3];
assign encoded_bits[1] = shift_reg[0] ^ shift_reg[1] ^ shift_reg[3];
assign encoded_bits[2] = shift_reg[0] ^ shift_reg[2] ^ shift_reg[3];
assign encoded_bits[3] = shift_reg[1] ^ shift_reg[2] ^ shift_reg[3];
assign encoded_bits[4] = shift_reg[0] ^ shift_reg[1] ^ shift_reg[2];
assign encoded_bits[5] = shift_reg[0] ^ shift_reg[2];
assign encoded_bits[6] = shift_reg[1] ^ shift_reg[3];
assign encoded_bits[7] = shift_reg[2] ^ shift_reg[3];

always @(posedge clk) begin
  shift_reg <= {shift_reg[n-1:0], in};
end

// Viterbi Decoder
reg [n-1:0] state;
reg [n-1:0] next_state;
reg [n-1:0] decoded_bits;

always @(posedge clk) begin
  state <= next_state;
  decoded_bits <= state;
end

always @(*) begin
  case (state)
    4'b0000: next_state = {state[2:0], encoded_bits[0]};
    4'b0001: next_state = {state[2:0], encoded_bits[1]};
    4'b0010: next_state = {state[2:0], encoded_bits[2]};
    4'b0011: next_state = {state[2:0], encoded_bits[3]};
    4'b0100: next_state = {state[2:0], encoded_bits[4]};
    4'b0101: next_state = {state[2:0], encoded_bits[5]};
    4'b0110: next_state = {state[2:0], encoded_bits[6]};
    4'b0111: next_state = {state[2:0], encoded_bits[7]};
    default: next_state = state;
  endcase
end

assign out = decoded_bits;

endmodule

module parallel_port(
  input clk_i, rst_i, readstrobe_i, writestrobe_i,
  input [1:0] address_i,
  input [7:0] data_i,
  output [31:0] parport_o,
  output [7:0] data_o,
  output parport_readstrobe_o,
  output parport_writestrobe_o
);

  reg [23:0] inputreg_r;
  reg [23:0] outputreg_r;
  reg [7:0] data_o;
  reg parport_readstrobe_o;
  reg parport_writestrobe_o;
  wire [31:0] parport_i;

  assign parport_o = parport_i;

  always @(*) begin
    data_o = parport_i[7:0];
    case(address_i)
      2'b01: data_o = inputreg_r[7:0];
      2'b10: data_o = inputreg_r[15:8];
      2'b11: data_o = inputreg_r[23:16];
    endcase

    parport_readstrobe_o = 0;
    if((address_i == 2'b00) && readstrobe_i) begin
      parport_readstrobe_o = 1;
    end
  end

  always @(posedge clk_i) begin
    parport_writestrobe_o <= 0;
    if(rst_i) begin
      parport_o <= 0;
      outputreg_r <= 0;
      parport_writestrobe_o <= 0;
    end else if(writestrobe_i) begin
      parport_writestrobe_o <= 0;
      case(address_i)
        2'b00: outputreg_r[7:0] <= data_i;
        2'b01: outputreg_r[15:8] <= data_i;
        2'b10: outputreg_r[23:16] <= data_i;
        2'b11: begin
          parport_o <= {data_i[7:0],outputreg_r[23:0]};
          parport_writestrobe_o <= 1;
        end
      endcase
    end else if(readstrobe_i) begin
      if(address_i == 2'b00) begin
        inputreg_r <= parport_i[31:8];
      end
    end
  end

endmodule

module delay_module (
