    always @(posedge clk) begin
        if (reset) begin
            buffer[0] <= 1'b0;
            buffer[1] <= 1'b0;
            buffer[2] <= 1'b0;
            out_signal <= 1'b0;
        end else begin
            buffer[0] <= in_signal;
            buffer[1] <= buffer[0];
            buffer[2] <= buffer[1];
            out_signal <= buffer[2];
        end
    end

endmodule

module FA (
	input A, B, Cin,
	output S, Cout
);

	assign S = A ^ B ^ Cin;
	assign Cout = (A & B) | (A & Cin) | (B & Cin);

endmodule

module four_bit_adder (
	input [3:0] A,
	input [3:0] B,
	input Cin,
	output [3:0] S,
	output Cout
);

	wire c0, c1, c2;

	FA fa0 (.A(A[0]), .B(B[0]), .Cin(Cin), .S(S[0]), .Cout(c0));
	FA fa1 (.A(A[1]), .B(B[1]), .Cin(c0), .S(S[1]), .Cout(c1));
	FA fa2 (.A(A[2]), .B(B[2]), .Cin(c1), .S(S[2]), .Cout(c2));
	FA fa3 (.A(A[3]), .B(B[3]), .Cin(c2), .S(S[3]), .Cout(Cout));

endmodule

module fb_rxcounters (
   input MRxClk, Reset, MRxDV, RxValid,
   input StateIdle, StateFFS, StatePreamble,
   input [1:0] StateData,
   input StateFrmCrc,
   input MRxDEqDataSoC,
   output TotalRecvNibCntEq0,
   output [15:0] TotalRecvNibCnt,
   output [7:0] RxRamAddr,
   output [3:0] FrmCrcNibCnt,
   output FrmCrcStateEnd
);
   reg [15:0] TotalRecvNibCnt;
   reg [7:0] RxRamAddr;
   reg [3:0] FrmCrcNibCnt;
   wire ResetTotalRecvNibCnt, IncrementTotalRecvNibCnt;
   wire ResetRxRamAddr, IncrementRxRamAddr;
   wire IncrementFrmCrcNibCnt, ResetFrmCrcNibCnt;

   assign ResetTotalRecvNibCnt = StateIdle & ~MRxDV;
   assign IncrementTotalRecvNibCnt = MRxDV;
   always @(posedge MRxClk or posedge Reset) begin
      if (Reset) TotalRecvNibCnt <= 16'd0;
      else if (ResetTotalRecvNibCnt) TotalRecvNibCnt <= 16'd0;
      else if (IncrementTotalRecvNibCnt) TotalRecvNibCnt <= TotalRecvNibCnt + 16'd1;
   end

   assign TotalRecvNibCntEq0 = (TotalRecvNibCnt == 16'd0);

   assign ResetRxRamAddr = StateIdle | StateFFS | StatePreamble;
   assign IncrementRxRamAddr = RxValid;
   always @(posedge MRxClk or posedge Reset) begin
      if (Reset) RxRamAddr <= 8'd0;
      else if (ResetRxRamAddr) RxRamAddr <= 8'd0;
      else if (IncrementRxRamAddr) RxRamAddr <= RxRamAddr + 8'd1;
   end

   assign IncrementFrmCrcNibCnt = StateFrmCrc;
   assign ResetFrmCrcNibCnt = StateIdle;
   assign FrmCrcStateEnd = FrmCrcNibCnt[0];
   always @(posedge MRxClk or posedge Reset) begin
      if (Reset) FrmCrcNibCnt <= 4'd0;
      else if (ResetFrmCrcNibCnt) FrmCrcNibCnt <= 4'd0;
      else if (IncrementFrmCrcNibCnt) FrmCrcNibCnt <= FrmCrcNibCnt + 4'd1;
   end
endmodule

module bcd_counter (
    input clk,
    input reset,   // Synchronous active-high reset
    input up_down, // Control input to choose between counting up or down
    output reg [15:0] q   // Output of the BCD counter
);

    reg [3:0] ones_up;     // Ones digit for up counter
    reg [3:0] ones_down;   // Ones digit for down counter
    reg [3:0] tens_up;     // Tens digit for up counter
    reg [3:0] tens_down;   // Tens digit for down counter
    reg [3:0] hundreds_up; // Hundreds digit for up counter
    reg [3:0] hundreds_down;   // Hundreds digit for down counter

    always @(posedge clk) begin
        if (reset) begin
            ones_up <= 4'b0000;
            tens_up <= 4'b0000;
            hundreds_up <= 4'b0000;
            ones_down <= 4'b0000;
            tens_down <= 4'b0000;
            hundreds_down <= 4'b0000;
        end else begin
            if (up_down) begin
                // Counting up
                if (ones_up == 4'b1001) begin
                    ones_up <= 4'b0000;
                    if (tens_up == 4'b1001) begin
                        tens_up <= 4'b0000;
                        if (hundreds_up == 4'b1001) begin
                            hundreds_up <= 4'b0000;
                        end else begin
                            hundreds_up <= hundreds_up + 1;
                        end
                    end else begin
                        tens_up <= tens_up + 1;
                    end
                end else begin
                    ones_up <= ones_up + 1;
                end
            end else begin
                // Counting down
                if (ones_down == 4'b0000) begin
                    ones_down <= 4'b1001;
                    if (tens_down == 4'b0000) begin
                        tens_down <= 4'b1001;
                        if (hundreds_down == 4'b0000) begin
                            hundreds_down <= 4'b1001;
                        end else begin
                            hundreds_down <= hundreds_down - 1;
                        end
                    end else begin
                        tens_down <= tens_down - 1;
                    end
                end else begin
                    ones_down <= ones_down - 1;
                end
            end
        end
    end

    // Output selection logic
    always @(posedge clk) begin
        if (reset) begin
            q <= 16'b0000000000000000;
        end else begin
            if (control) begin
                q <= {hundreds_down, tens_down, ones_down, 4'b0000};
            end else begin
                q <= {hundreds_up, tens_up, ones_up, 4'b0000};
            end
        end
    end

endmodule

module control_logic (
    input clk,
    input reset,   // Synchronous active-high reset
    input up_down, // Control input to choose between counting up or down
    output reg select // Output to select between up and down counter
);

    always @(posedge clk) begin
        if (reset) begin
            select <= 1'b0;
        end else begin
            if (up_down) begin
                select <= 1'b1;
            end else begin
                select <= 1'b0;
            end
        end
    end

endmodule

module top_module (
    input clk,
    input reset,   // Synchronous active-high reset
    input control, // Select input to choose between up and down counter
    output reg [15:0] q   // Output from the active counter
);

    wire select;
    wire [15:0] up_counter;
    wire [15:0] down_counter;

    bcd_counter up (
        .clk(clk),
        .reset(reset),
        .up_down(1'b1),
        .q(up_counter)
    );

    bcd_counter down (
        .clk(clk),
        .reset(reset),
        .up_down(1'b0),
        .q(down_counter)
    );

    control_logic control (
        .clk(clk),
        .reset(reset),
        .up_down(control),
        .select(select)
    );

    always @(posedge clk) begin
        if (reset) begin
            q <= 16'b0000000000000000;
        end else begin
            if (select) begin
                q <= down_counter;
            end else begin
                q <= up_counter;
            end
        end
    end

endmodule

