module modulo_six_counter (
    input clk,
    input reset,   // Synchronous active-high reset
    input ena, // Enable signal to increment the counter
    output reg [2:0] q  // 3-bit modulo-6 counter output
);

    // Define the states for the FSM
    parameter IDLE = 2'b00;
    parameter COUNT_1 = 2'b01;
    parameter COUNT_2 = 2'b10;

    // Define the current state and next state variables
    reg [1:0] state, next_state;

    // Define the counter variable
    reg [2:0] count;

    // Assign the initial state and counter values
    initial begin
        state = IDLE;
        count = 3'b000;
    end

    // Define the state transition logic
    always @ (posedge clk, posedge reset) begin
        if (reset) begin
            state <= IDLE;
            count <= 3'b000;
        end else begin
            state <= next_state;
            count <= count + 1;
        end
    end

    // Define the next state logic
    always @ (state, ena) begin
        case (state)
            IDLE: begin
                if (ena) begin
                    next_state = COUNT_1;
                end else begin
                    next_state = IDLE;
                end
            end
            COUNT_1: begin
                if (ena) begin
                    next_state = COUNT_2;
                end else begin
                    next_state = IDLE;
                end
            end
            COUNT_2: begin
                if (ena) begin
                    next_state = IDLE;
                end else begin
                    next_state = IDLE;
                end
            end
            default: next_state = IDLE;
        endcase
    end

    // Define the output logic
    always @ (state, count) begin
        case (state)
            IDLE: q = 3'b000;
            COUNT_1: q = count;
            COUNT_2: q = count;
            default: q = 3'b000;
        endcase
    end

endmodule

