rom rom_inst(pc[7:0], rom_out);

always @(posedge clk) begin
    case (rom_out[15:8])
        8'b0111_0000: r1 = r0 + 7;
        8'b1000_0001: r2 = r1 - 2;
        8'b1010_0000: $display("Error: store instruction not supported");
        8'b1001_0000: $display("Error: load instruction not supported");
        8'b0001_0001: r4 = r1 + r2;
