module top_module (
    input [3:0] A,
    input [3:0] B,
    input ctrl,
    output equal,
    output greater_than,
    output less_than
);

    wire [3:0] addsub_result;
    wire equal_addsub_comp, greater_than_addsub_comp, less_than_addsub_comp;

    addsub addsub_inst (
        .A(A),
        .B(B),
        .ctrl(ctrl),
        .result(addsub_result)
    );

    comparator comparator_inst (
        .A(addsub_result),
        .B(B),
        .equal(equal_addsub_comp),
        .greater_than(greater_than_addsub_comp),
        .less_than(less_than_addsub_comp)
    );

    assign equal = (ctrl) ? equal_addsub_comp : (A == B);
    assign greater_than = (ctrl) ? greater_than_addsub_comp : (A > B);
    assign less_than = (ctrl) ? less_than_addsub_comp : (A < B);

endmodule

