module adder_subtractor (
    A,
    B,
    SEL,
    Y
);

    input [15:0] A;
    input [15:0] B;
    input SEL;
    output [15:0] Y;

    wire [15:0] sum;
    wire [15:0] sub;

    // XOR A and B
    wire [15:0] xor_result;
    genvar i;
    generate
        for (i = 0; i < 16; i = i + 1) begin : xor_loop
            sky130_fd_sc_lp__xor2 xor_gate (
                .A(A[i]),
                .B(B[i]),
                .Y(xor_result[i])
            );
        end
    endgenerate

    // Calculate sum of A and B
    genvar j;
    generate
        for (j = 0; j < 16; j = j + 1) begin : sum_loop
            if (j == 0) begin
                sky130_fd_sc_lp__xor2 first_xor (
                    .A(A[j]),
                    .B(B[j]),
                    .Y(sum[j])
                );
            end else begin
                sky130_fd_sc_lp__xor2 xor_gate (
                    .A(A[j]),
                    .B(B[j]),
                    .Y(xor_result[j])
                );
                sky130_fd_sc_lp__xor2 second_xor (
                    .A(xor_result[j]),
                    .B(sum[j-1]),
                    .Y(sum[j])
                );
            end
        end
    endgenerate

    // Calculate difference of A and B
    genvar k;
    generate
        for (k = 0; k < 16; k = k + 1) begin : sub_loop
            if (k == 0) begin
                sky130_fd_sc_lp__mux2 first_mux (
                    .SEL(SEL),
                    .A(A[k]),
                    .B(B[k]),
                    .Y(sub[k])
                );
                sky130_fd_sc_lp__xor2 first_xor (
                    .A(A[k]),
                    .B(B[k]),
                    .Y(xor_result[k])
                );
                sky130_fd_sc_lp__mux2 sel_mux (
                    .SEL(SEL),
                    .A(xor_result[k]),
                    .B(sub[k]),
                    .Y(sub[k])
                );
            end else begin
                sky130_fd_sc_lp__mux2 mux1 (
                    .SEL(SEL),
                    .A(A[k]),
                    .B(B[k]),
                    .Y(xor_result[k])
                );
                sky130_fd_sc_lp__mux2 mux2 (
                    .SEL(SEL),
                    .A(xor_result[k]),
                    .B(sub[k-1]),
                    .Y(sub[k])
                );
            end
        end
    endgenerate

    // Output sum or difference based on SEL value
    sky130_fd_sc_lp__mux2 mux3 (
        .SEL(SEL),
        .A(sum),
        .B(sub),
        .Y(Y)
    );

endmodule

