module decoder(
    input [3:0] sel,
    output reg [15:0] out
);

    always @(*) begin
        case(sel)
            4'b0001: out <= 16'h0001;
            4'b0010: out <= 16'h0002;
            4'b0011: out <= 16'h0004;
            4'b0100: out <= 16'h0008;
            4'b0101: out <= 16'h0010;
            4'b0110: out <= 16'h0020;
