module Debouncer(
  input clk, // clock signal
  input rst_n, // asynchronous reset
  input in, // input signal
  output reg out // output signal
);

parameter COUNT_MAX = 1000; // maximum count value
parameter WAIT_TIME = 10; // wait time in ms

reg [9:0] count; // counter to count up to COUNT_MAX
reg [1:0] state; // state machine to control the debouncing process

always @(posedge clk or negedge rst_n) begin
  if (~rst_n) begin
    count <= 0;
    state <= 2'b00;
    out <= 1'b0;
  end
  else begin
    case (state)
      2'b00: // idle state
        if (in != out) begin
          count <= 0;
          state <= 2'b01;
        end
        else begin
          out <= in;
        end
      2'b01: // waiting state
        if (count >= COUNT_MAX) begin
          out <= in;
          state <= 2'b10;
        end
        else begin
          count <= count + 1;
        end
      2'b10: // debounce state
        if (in != out) begin
          count <= 0;
          state <= 2'b01;
        end
        else begin
          state <= 2'b00;
        end
    endcase
  end
end

endmodule

module PushButton_Debouncer#(parameter COUNTER_WIDTH = 16) (
    input wire clk,
    input wire PB,  // "PB" is the glitchy, asynchronous to clk, active low push-button signal

    // from which we make three outputs, all synchronous to the clock
    output reg PB_state,  // 1 as long as the push-button is active (down)
    output wire PB_down,  // 1 for one clock cycle when the push-button goes down (i.e. just pushed)
    output wire PB_up   // 1 for one clock cycle when the push-button goes up (i.e. just released)
);

reg PB_sync_0;
reg PB_sync_1;
reg [COUNTER_WIDTH-1:0] PB_cnt;

wire PB_idle = (PB_state==PB_sync_1);
wire PB_cnt_max = &PB_cnt;

always @(posedge clk)
begin
    PB_sync_0 <= PB;
    PB_sync_1 <= PB_sync_0;
    if(PB_idle)
        PB_cnt <= 0;
    else
    begin
        PB_cnt <= PB_cnt + 1;
        if(PB_cnt_max)
        begin
            PB_state <= ~PB_state;
            if(PB_state)
                PB_down <= 1;
            else
                PB_up <= 1;
        end
    end
end

always @(posedge clk)
begin
    if(PB_idle)
    begin
        PB_down <= 0;
        PB_up <= 0;
    end
end

endmodule

