module multiplier(
    input clk,
    input reset,       // Synchronous active-high reset
    input [15:0] a,    // 16-bit input a
    input [15:0] b,    // 16-bit input b
    output reg [31:0] result // 32-bit multiplication result output
);

    reg [15:0] a_reg;
    reg [15:0] b_reg;
    reg [3:0] adder_out_reg;
    reg [31:0] result_reg;

    always @(posedge clk) begin
        if (reset) begin
            a_reg <= 0;
            b_reg <= 0;
            adder_out_reg <= 0;
            result_reg <= 0;
        end else begin
            a_reg <= a;
            b_reg <= b;
            adder_out_reg <= adder_out_reg + (a_reg & 4'b1111);
            result_reg <= result_reg + (b_reg & 4'b1111) * adder_out_reg;
            adder_out_reg <= {adder_out_reg[2:0], 1'b0};
        end
    end

    assign result = result_reg;

endmodule

module abs_block(
    input clk,
    input reset,       // Synchronous active-high reset
    input signed [31:0] in_val, // 32-bit input value
    output reg [31:0] abs_val // Absolute value of the input value
);

    always @(posedge clk) begin
        if (reset) begin
            abs_val <= 0;
        end else begin
            if (in_val < 0) begin
                abs_val <= -in_val;
            end else begin
                abs_val <= in_val;
            end
        end
    end

endmodule

