      out[0] <= fsr1[0] ^ fsr2[0];
      out[1] <= fsr1[0] ^ fsr2[1];
      state1 <= 2'b00;
      state2 <= 2'b00;
      state3 <= 2'b00;
      state4 <= 2'b00;
      state5 <= 2'b00;
      state6 <= 2'b00;
      state7 <= 2'b00;
      state8 <= 2'b00;
    end
    2'b01: begin
      out[0] <= fsr1[0] ^ fsr2[0];
      out[1] <= fsr1[0] ^ fsr2[1];
      state1 <= 2'b10;
      state2 <= 2'b11;
      state3 <= 2'b00;
      state4 <= 2'b00;
      state5 <= 2'b00;
      state6 <= 2'b00;
      state7 <= 2'b00;
      state8 <= 2'b00;
    end
    2'b10: begin
      out[0] <= fsr1[0] ^ fsr2[1];
      out[1] <= fsr1[0] ^ fsr2[0];
      state1 <= 2'b01;
      state2 <= 2'b00;
      state3 <= 2'b11;
      state4 <= 2'b10;
      state5 <= 2'b00;
      state6 <= 2'b00;
      state7 <= 2'b00;
      state8 <= 2'b00;
    end
    2'b11: begin
      out[0] <= fsr1[0] ^ fsr2[1];
      out[1] <= fsr1[0] ^ fsr2[0];
      state1 <= 2'b11;
      state2 <= 2'b10;
      state3 <= 2'b01;
      state4 <= 2'b00;
      state5 <= 2'b11;
      state6 <= 2'b10;
      state7 <= 2'b00;
      state8 <= 2'b00;
    end
    2'bxx: begin
      out[0] <= 1'b0;
      out[1] <= 1'b0;
      state1 <= 2'b00;
      state2 <= 2'b00;
      state3 <= 2'b00;
      state4 <= 2'b00;
      state5 <= 2'b00;
      state6 <= 2'b00;
      state7 <= 2'b00;
      state8 <= 2'b00;
    end
  endcase

  // Shift the output into the FSR
  fsr2 <= {out[2*k-2:2], fsr2[k-2:0]};
end

