    input [3:0] B,
    input CIN,
    input SUB,
    input CLK,
    input EN,
    input [1:0] SEL,
    output reg [3:0] OUT
);

    wire [3:0] adder_out;
    wire [3:0] mux_out;
    wire [3:0] xor_out;

    adder_subtractor_4bit add_sub (
        .A(A),
        .B(B),
        .CIN(CIN),
        .SUB(SUB),
        .CLK(CLK),
        .OUT(adder_out)
    );

    mux_3to1_enable mux (
        .A(adder_out),
        .B(B),
        .C(A),
        .EN(EN),
        .SEL(SEL[0]),
        .OUT(mux_out)
    );

    xor_4bit xor (
        .A(adder_out),
        .B(mux_out),
        .OUT(xor_out)
    );

    always @(posedge CLK) begin
        if (EN == 1'b0) begin
            OUT <= 4'bz;
        end else begin
            case (SEL)
                2'b00: OUT <= adder_out;
                2'b01: OUT <= mux_out;
                2'b10: OUT <= xor_out;
                default: OUT <= 4'bz;
            endcase
        end
    end

