module top_module (
    input [7:0] a,
    input [7:0] b,
    output [7:0] s,
    output overflow
);

// Convert 2's complement to sign-magnitude
wire [7:0] a_mag = (a[7] == 1) ? (~a + 1) : a;
wire [7:0] b_mag = (b[7] == 1) ? (~b + 1) : b;

// Ripple carry adder
wire [7:0] sum_rca;
wire [7:0] carry_rca;
ripple_carry_adder rca(.a(a_mag), .b(b_mag), .sum(sum_rca), .carry(carry_rca));

// Carry look-ahead adder
wire [7:0] sum_cla;
wire carry_in = carry_rca[7] ^ a[7] ^ b[7];
carry_lookahead_adder cla(.a(sum_rca), .b(8'b00000001), .sum(sum_cla), .carry_out(overflow), .carry_in(carry_in));

// Convert back to 2's complement if necessary
assign s = (overflow) ? 8'b00000000 : ((sum_cla[7] == 1) ? (~sum_cla + 1) : sum_cla);

endmodule

module ripple_carry_adder (
    input [7:0] a,
    input [7:0] b,
    output [7:0] sum,
    output [7:0] carry
);

genvar i;
wire [7:0] c;
assign c[0] = 1'b0;

generate
    for (i = 0; i < 8; i = i + 1) begin : adder
        full_adder fa(.a(a[i]), .b(b[i]), .c_in(c[i]), .sum(sum[i]), .c_out(c[i+1]));
    end
endgenerate

assign carry = c[8];

endmodule

