module carry_lookahead_adder (
    input [7:0] a,
    input [7:0] b,
    output [7:0] sum,
    output carry_out,
    input carry_in
);

wire [7:0] p;
wire [7:0] g;
wire [7:0] c;
wire [7:0] c_prop;
wire [7:0] c_gen;

assign p = a & b;
assign g = a | b;
assign c_prop[0] = carry_in;
generate
    for (i = 0; i < 7; i = i + 1) begin : carry_propagate
        assign c_prop[i+1] = g[i] & c_prop[i];
    end
endgenerate

generate
    for (i = 0; i < 7; i = i + 1) begin : carry_generate
        assign c_gen[i+1] = p[i] | (g[i] & c_gen[i]);
    end
endgenerate

assign c = c_prop | c_gen;
assign carry_out = c[8];
assign sum = a + b + {c[7:0], 1'b0};

endmodule

