module ddr_des 
#(
    parameter CLKDV = 4
)(
    input wire CLK2X, 
    input wire CLK, 
    input wire WCLK,
    input wire IN,
    output reg [CLKDV*4-1:0] OUT,
    output wire [1:0] OUT_FAST
);

wire [1:0] DDRQ;

// Double Data Rate input sampling using IDDR primitive
IDDR IDDR_inst (
   .Q1(DDRQ[1]), // 1-bit output for positive edge of clock 
   .Q2(DDRQ[0]), // 1-bit output for negative edge of clock
   .C(CLK2X), // 1-bit clock input
   .CE(1'b1), // 1-bit clock enable input
   .D(IN), // 1-bit DDR data input
   .R(1'b0), // 1-bit reset
   .S(1'b0) // 1-bit set
);

assign OUT_FAST = DDRQ;

// Double flip-flop synchronizer for input data
reg [1:0] DDRQ_DLY;
always@(posedge CLK2X)
    DDRQ_DLY[1:0] <= DDRQ[1:0];

// Shift register to synchronize input data to reference clock
reg [3:0] DDRQ_DATA;
always@(posedge CLK2X)
    DDRQ_DATA[3:0] <= {DDRQ_DLY[1:0], DDRQ[1:0]};

reg [3:0] DDRQ_DATA_BUF;
always@(posedge CLK2X)
    DDRQ_DATA_BUF[3:0] <= DDRQ_DATA[3:0];

// Output data register
reg [3:0] DATA_IN;
always@(posedge CLK)
    DATA_IN[3:0] <= DDRQ_DATA_BUF[3:0];

// Shift register for output data
reg [CLKDV*4-1:0] DATA_IN_SR;
always@(posedge CLK)
    DATA_IN_SR <= {DATA_IN_SR[CLKDV*4-5:0],DATA_IN[3:0]};

// Output differential signal
always@(posedge WCLK)
    OUT <= DATA_IN_SR;

endmodule

module elevator_fsm(
    input clk,
    input rst,
    input [1:0] floor_req,
    input [1:0] curr_floor,
    output up,
    output down,
    output stop,
    output floor_reached
);

    // Define states
    parameter IDLE = 2'b00;
    parameter UP = 2'b01;
    parameter DOWN = 2'b10;
    parameter STOP = 2'b11;

    // Define outputs
    reg up;
    reg down;
    reg stop;
    reg floor_reached;

    // Define state and next_state
    reg [1:0] state;
    reg [1:0] next_state;

    // Define constants
    parameter FLOOR0 = 2'b00;
    parameter FLOOR1 = 2'b01;
    parameter FLOOR2 = 2'b10;
    parameter FLOOR3 = 2'b11;

    // Define state transitions and outputs
    always @(posedge clk, posedge rst) begin
        if(rst) begin
            state <= IDLE;
            up <= 0;
            down <= 0;
            stop <= 0;
            floor_reached <= 0;
        end
        else begin
            state <= next_state;
            up <= 0;
            down <= 0;
            stop <= 0;
            floor_reached <= 0;
            case(state)
                IDLE: begin
                    if(floor_req > curr_floor) begin
                        next_state = UP;
                        up <= 1;
                    end
                    else if(floor_req < curr_floor) begin
                        next_state = DOWN;
                        down <= 1;
                    end
                    else begin
                        stop <= 1;
                        floor_reached <= 1;
                    end
                end
                UP: begin
                    if(floor_req > curr_floor) begin
                        next_state = UP;
                        up <= 1;
                    end
                    else if(floor_req < curr_floor) begin
                        next_state = DOWN;
                        down <= 1;
                    end
                    else begin
                        next_state = STOP;
                        stop <= 1;
                        floor_reached <= 1;
                    end
                end
                DOWN: begin
                    if(floor_req < curr_floor) begin
                        next_state = DOWN;
                        down <= 1;
                    end
                    else if(floor_req > curr_floor) begin
                        next_state = UP;
                        up <= 1;
                    end
                    else begin
                        next_state = STOP;
                        stop <= 1;
                        floor_reached <= 1;
                    end
                end
                STOP: begin
                    next_state = IDLE;
                end
            endcase
        end
    end
endmodule

module system_control 
  (input wb_clk_i,
   output reg ram_loader_rst_o,
   output reg wb_rst_o,
   input ram_loader_done_i
   );

   reg 		POR = 1'b1;
   reg [3:0] 	POR_ctr;

   initial POR_ctr = 4'd0;
   always @(posedge wb_clk_i)
     if(POR_ctr == 4'd15)
       POR <= 1'b0;
     else
       POR_ctr <= POR_ctr + 4'd1;

   always @(posedge POR or posedge wb_clk_i)
     if(POR)
       ram_loader_rst_o <= 1'b1;
     else
       ram_loader_rst_o <= #1 1'b0;

   // Main system reset
   reg 		delayed_rst;

   always @(posedge POR or posedge wb_clk_i)
     if(POR)
       begin
	  wb_rst_o <= 1'b1;
	  delayed_rst <= 1'b1;
       end
     else if(ram_loader_done_i)
       begin
	  delayed_rst <= 1'b0;
	  wb_rst_o <= delayed_rst;
       end

endmodule

module priority_encoder (
