module bcd_counter (
    input clk,
    input [1:0] ena,
    output reg [3:0] q
);

always @(posedge clk) begin
    if(ena[0])
        q[0] <= q[0] + 1;
    if(ena[1])
        q[1] <= q[1] + 1;
    if(ena[2])
        q[2] <= q[2] + 1;
    if(q[0] == 10) begin
        q[0] <= 0;
        q[1] <= q[1] + 1;
    end
    if(q[1] == 10) begin
        q[1] <= 0;
        q[2] <= q[2] + 1;
    end
    if(q[2] == 10) begin
        q[2] <= 0;
        q[3] <= q[3] + 1;
    end
end

endmodule

