);

always @(*) begin
    case(pos)
        2'b00: final_out = 16'b0;
        2'b01: final_out = q[3:0];
        2'b10: final_out = q[7:4];
        2'b11: final_out = q[11:8];
        default: final_out = 16'b0;
    endcase
end

