module top_module (
    input clk,
    input reset,
    input [3:0] in,
    output reg [1:0] pos,
    output reg [3:1] ena,
    output reg [15:0] q
);

priority_encoder pe(.in(in), .pos(pos));
bcd_counter bc(.clk(clk), .ena(ena), .q(q));
final_output fo(.pos(pos), .q(q), .final_out(final_out));

always @(posedge clk) begin
    if(reset) begin
        q <= 16'b0;
        ena <= 3'b0;
    end else begin
        ena[0] <= 1;
        if(pos == 2'b01)
            ena[1] <= 1;
        if(pos == 2'b10)
            ena[2] <= 1;
        final_out <= q * (pos != 2'b00);
    end
end

endmodule

