module carry_select_adder (
    input [7:0] a,
    input [7:0] b,
    output reg [7:0] s,
    output reg overflow
);

wire [7:0] p, g;
wire [7:0] c0, c1, c2, c3;
wire [7:0] sum0, sum1, sum2, sum3;

assign p = a ^ b;
assign g = a & b;

assign c0 = p[0] | g[0];
assign c1 = p[1] | (g[1] & c0[0]);
assign c2 = p[2] | (g[2] & c1[1]);
assign c3 = p[3] | (g[3] & c2[2]);

assign sum0 = a[0] ^ b[0] ^ c0[0];
assign sum1 = a[1] ^ b[1] ^ c1[1];
assign sum2 = a[2] ^ b[2] ^ c2[2];
assign sum3 = a[3] ^ b[3] ^ c3[3];

assign s = {c3[3], sum3, sum2, sum1, sum0};

assign overflow = (a[7] == b[7] && s[7] != a[7]);

endmodule

