module calculator (
    input [7:0] A,
    input [7:0] B,
    input [1:0] Op,
    output [7:0] Result,
    output Overflow,
    output Underflow,
    output Zero
);

reg [15:0] temp_result;
reg [7:0] result;
reg overflow;
reg underflow;
reg zero;

always @(*) begin
    case (Op)
        2'b00: begin // Addition
            temp_result = A + B;
            if (temp_result > 255) begin
                overflow = 1;
                underflow = 0;
                zero = 0;
                result = 255;
            end else begin
                overflow = 0;
                underflow = 0;
                zero = (temp_result == 0);
                result = temp_result;
            end
        end
        2'b01: begin // Subtraction
            temp_result = A - B;
            if (temp_result < 0) begin
                overflow = 0;
                underflow = 1;
                zero = 0;
                result = 0;
            end else begin
                overflow = 0;
                underflow = 0;
                zero = (temp_result == 0);
                result = temp_result;
            end
        end
        2'b10: begin // Multiplication
            temp_result = A * B;
            if (temp_result > 255) begin
                overflow = 1;
                underflow = 0;
                zero = 0;
                result = 255;
            end else begin
                overflow = 0;
                underflow = 0;
                zero = (temp_result == 0);
                result = temp_result;
            end
        end
        2'b11: begin // Division
            if (B == 0) begin
                overflow = 0;
                underflow = 0;
                zero = 0;
                result = 0;
            end else begin
                temp_result = A / B;
                if (temp_result > 255) begin
                    overflow = 1;
                    underflow = 0;
                    zero = 0;
                    result = 255;
                end else begin
                    overflow = 0;
                    underflow = 0;
                    zero = (temp_result == 0);
                    result = temp_result;
                end
            end
        end
    endcase
end

assign Result = result;
assign Overflow = overflow;
assign Underflow = underflow;
assign Zero = zero;

endmodule

