module priority_mux (
    input [3:0] A, B, C, D,
    input [1:0] S,
    output reg Y, Z
);
    always @(*) begin
        case (S)
            2'b00: begin
                Y = 1'b0;
                Z = 1'b0;
            end
            2'b01: begin
                Y = A;
                Z = ~A;
            end
            2'b10: begin
                Y = B;
                Z = ~B;
            end
            2'b11: begin
                if (A | B | C | D) begin
                    if (D) begin
                        Y = D;
                        Z = ~D;
                    end else if (C) begin
                        Y = C;
                        Z = ~C;
                    end else if (B) begin
                        Y = B;
                        Z = ~B;
                    end else begin
                        Y = A;
                        Z = ~A;
                    end
                end else begin
                    Y = 1'b0;
                    Z = 1'b0;
                end
            end
        endcase
    end
endmodule

