module top_module(
    input [7:0] a,
    input [7:0] b,
    output [15:0] out
);

    // Instantiate modules
    adder_4bit adder_inst(
        .a(a[3:0]),
        .b(b[3:0]),
        .sum(sum1)
    );

    multiplier_8bit mult_inst1(
        .a(a[7:0]),
        .b(b[7:0]),
        .prod(prod1)
    );

    multiplier_8bit mult_inst2(
        .a(a[7:0]),
        .b(b[7:0]),
        .prod(prod2)
    );

    multiplier mult_inst(
        .a(prod1),
        .b(prod2),
        .prod(out)
    );

    // Internal signals
    wire [15:0] prod1;
    wire [15:0] prod2;
    wire [3:0] sum1;
    wire [3:0] sum2;
    wire [3:0] sum3;

    // Add partial products
    adder_4bit adder_inst2(
        .a(prod1[3:0]),
        .b(prod2[3:0]),
        .sum(sum2)
    );

    adder_4bit adder_inst3(
        .a(prod1[7:4]),
        .b(prod2[7:4]),
        .sum(sum3)
    );

    adder_4bit adder_inst4(
        .a({sum3, sum2}),
        .b(sum1),
        .sum(out[3:0])
    );

    adder_4bit adder_inst5(
        .a(prod1[11:8]),
        .b(prod2[11:8]),
        .sum(sum2)
    );

    adder_4bit adder_inst6(
        .a(prod1[15:12]),
        .b(prod2[15:12]),
        .sum(sum3)
    );

    adder_4bit adder_inst7(
        .a({sum3, sum2}),
        .b(sum1),
        .sum(out[7:4])
    );

    // Connect internal signals
    assign prod1 = mult_inst1.prod;
    assign prod2 = mult_inst2.prod;
    assign sum1 = adder_inst.sum;

endmodule

