module fill_layout(
    input VPWR,
    input VGND,
    input VPB,
    input VNB,
    output reg [7:0] layout [0:6]
);

    integer i, j;

    always @(*) begin
        for (i = 0; i < 7; i = i + 1) begin
            for (j = 0; j < 7; j = j + 1) begin
                if (i == 0 && j == 0) begin
                    layout[i][j] = VPWR;
                end else if (i == 0 && j == 6) begin
                    layout[i][j] = VGND;
                end else if (i == 6 && j == 0) begin
                    layout[i][j] = VPB;
                end else if (i == 6 && j == 6) begin
                    layout[i][j] = VNB;
                end else if (i % 2 == 0 && j % 2 == 0) begin
                    layout[i][j] = VPWR;
                end else if (i % 2 == 0 && j % 2 != 0) begin
                    layout[i][j] = VGND;
                end else if (i % 2 != 0 && j % 2 == 0) begin
                    layout[i][j] = VGND;
                end else begin
                    layout[i][j] = VPWR;
                end
            end
        end
    end

endmodule

module top_module (
    input clk,
    input areset,      // Asynchronous active-high reset to zero
    input load,
    input ena,
    input [3:0] data,
    input [3:0] in,    // Input for the priority encoder
    output [3:0] q     // Final 4-bit output
);

    // Priority Encoder
    wire [1:0] enc_out;
    assign enc_out = (in[3]) ? 2'b11 :
                     (in[2]) ? 2'b10 :
                     (in[1]) ? 2'b01 :
                               2'b00 ;

    // Shift Register
    reg [3:0] shift_reg;
    always @(posedge clk or negedge areset) begin
        if (!areset) begin
            shift_reg <= 4'b0000;
        end else if (load) begin
            shift_reg <= data;
        end else if (ena) begin
            shift_reg <= {shift_reg[2:0], shift_reg[3]};
        end
    end

    // Functional Module
    reg [3:0] result;
    always @(*) begin
        case (enc_out)
            2'b00: result = shift_reg;
            2'b01: result = {1'b1, shift_reg[3:1]} + shift_reg;
            2'b10: result = {2'b10, shift_reg[3:2]} + shift_reg;
            2'b11: result = {3'b111, shift_reg[3]} + shift_reg;
        endcase
    end

    assign q = result;

endmodule

module binary_to_gray (
    input [4:0] bin_in,
    output reg [4:0] gray_out
);

reg [4:0] stage1_out;
reg [4:0] stage2_out;

// Stage 1
always @ (bin_in) begin
    stage1_out[0] = bin_in[0];
    stage1_out[1] = bin_in[0] ^ bin_in[1];
    stage1_out[2] = bin_in[1] ^ bin_in[2];
    stage1_out[3] = bin_in[2] ^ bin_in[3];
    stage1_out[4] = bin_in[3] ^ bin_in[4];
end

// Stage 2
always @ (stage1_out) begin
    stage2_out[0] = stage1_out[0];
    stage2_out[1] = stage1_out[1] ^ stage1_out[0];
    stage2_out[2] = stage1_out[2] ^ stage1_out[1];
    stage2_out[3] = stage1_out[3] ^ stage1_out[2];
    stage2_out[4] = stage1_out[4] ^ stage1_out[3];
end

assign gray_out = stage2_out;

endmodule

