module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out
);

    reg [9:0]   acc;        // 10-bit accumulator
    reg [2:0]   state;      // State machine state
    reg [7:0]   data_reg;   // Input data register

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            acc <= 0;
            state <= 0;
            data_reg <= 0;
            valid_b <= 0;
            data_out <= 0;
        end else begin
            case (state)
                0: begin    // Idle state
                    if (valid_a) begin
                        data_reg <= data_in;
                        valid_b <= 1;
                        state <= 1;
                    end
                end
                1: begin    // Accumulation state
                    if (ready_b) begin
                        acc <= acc + data_reg;
                        valid_b <= 0;
                        state <= 0;
                    end
                end
            endcase
        end
    end

    assign ready_a = ~valid_b;

    assign data_out = acc;

endmodule

module PLL (
  input ref_clk,
  input ctrl,
  input rst,
  output reg clk
);

parameter vco_min_freq = 1.0e9; 
parameter vco_max_freq = 2.0e9;
parameter bandwidth = 100.0e3;
parameter n = 2; 
parameter m = 1;

reg [31:0] phase_accumulator;
reg [31:0] phase_error;
reg [31:0] loop_filter_output;
reg [31:0] vco_frequency;
reg [31:0] vco_control_voltage;

wire [31:0] ref_clk_divided;
wire [31:0] vco_clk_divided;

assign ref_clk_divided = ref_clk / n;
assign vco_clk_divided = vco_frequency / m;

phase_detector pd (
  .ref_clk(ref_clk_divided),
  .vco_clk(vco_clk_divided),
  .phase_error(phase_error)
);

loop_filter lf (
  .ctrl(ctrl),
  .rst(rst),
  .phase_error(phase_error),
  .loop_filter_output(loop_filter_output)
);

vco v (
  .ctrl(ctrl),
  .vco_control_voltage(vco_control_voltage),
  .vco_frequency(vco_frequency)
);

always @(posedge ref_clk) begin
  if (rst) begin
    phase_accumulator <= 0;
    vco_control_voltage <= 0;
    vco_frequency <= vco_min_freq;
  end else begin
    phase_accumulator <= phase_accumulator + vco_frequency;
    vco_control_voltage <= loop_filter_output;
    vco_frequency <= vco_frequency + vco_control_voltage;
    if (vco_frequency > vco_max_freq) begin
      vco_frequency <= vco_min_freq;
    end
  end
end

always @(posedge ref_clk_divided) begin
  clk <= ~clk;
end

endmodule

module phase_detector (
  input [31:0] ref_clk,
  input [31:0] vco_clk,
  output reg [31:0] phase_error
);

always @(posedge ref_clk) begin
  phase_error <= vco_clk - ref_clk;
end

endmodule

module loop_filter (
  input ctrl,
  input rst,
  input [31:0] phase_error,
  output reg [31:0] loop_filter_output
);

parameter kp = 0.1;
parameter ki = 0.01;

reg [31:0] integrator;

always @(posedge ctrl) begin
  if (rst) begin
    integrator <= 0;
    loop_filter_output <= 0;
  end else begin
    integrator <= integrator + phase_error;
    loop_filter_output <= (kp * phase_error) + (ki * integrator);
  end
end

endmodule

module vco (
  input ctrl,
  input [31:0] vco_control_voltage,
  output reg [31:0] vco_frequency
);

parameter vco_gain = 1.0;

always @(posedge ctrl) begin
  vco_frequency <= vco_gain * vco_control_voltage;
end

endmodule

module shift_reg_d_ff (
    input clk,
    input reset,            // Synchronous reset
    input [7:0] d,
    input select,           // Control input to choose between shift register and D flip-flop
    output [7:0] q
);

    reg [7:0] shift_reg;
    reg [7:0] d_ff;

    always @(posedge clk, negedge reset) begin
        if (reset == 1'b0) begin
            shift_reg <= 8'h34;
            d_ff <= 8'h34;
        end else begin
            if (select == 1'b1) begin
                shift_reg <= {shift_reg[6:0], d};
            end else begin
                d_ff <= d;
            end
        end
    end

    assign q = (select == 1'b1) ? shift_reg : d_ff;

endmodule

