    sky130_fd_sc_ls__udp_dff$P_pp$PG$N dff0      (buf_Q  , mux_out, CLK_delayed, notifier, VPWR, VGND);

    // Assignments
    assign awake = ( VPWR === 1'b1 );
    assign cond1 = ( awake && ( SCE_delayed === 1'b0 ) && ( DE_delayed === 1'b1 ) );
    assign cond2 = ( awake && ( SCE_delayed === 1'b1 ) );
    assign cond3 = ( awake && ( DE_delayed === 1'b1 ) && ( D_delayed !== SCD_delayed ) );

    // Reset logic
    always @(posedge VGND, negedge DE)
        if (!DE)
            buf_Q <= 1'b0;

    // Delay logic
    assign D_delayed = dff1.Q;
    assign SCD_delayed = dff2.Q;
    assign SCE_delayed = dff3.Q;
    assign DE_delayed = dff4.Q;
    assign CLK_delayed = dff5.Q;

    // Multiplexer and flip-flop logic
    always @(posedge CLK_delayed)
        if (cond1)
            buf_Q <= 1'b0;
        else if (cond2 || cond3)
            buf_Q <= mux_out;
        else
            buf_Q <= buf_Q;

    // Output buffer
    sky130_fd_sc_ls__buf_1 buf_output (Q, buf_Q, VPB, VNB);

endmodule

module barrel_shifter (
    input [15:0] DATA,
    input [3:0] SHIFT,
    input [1:0] CTRL,
    output reg [15:0] out
);

reg [15:0] stage1_out;
reg [15:0] stage2_out;

always @(*) begin
    case (CTRL)
        2'b00: stage1_out = {DATA[SHIFT[3:0]], DATA[15:SHIFT[3:0]+1]};
        2'b01: stage1_out = {DATA[15:SHIFT[3:0]+1], {SHIFT[3:0]}};
        2'b10: stage1_out = {{DATA[15]}, DATA[15:SHIFT[3:0]+1]};
        2'b11: stage1_out = {DATA[SHIFT[3:0]], DATA[15:SHIFT[3:0]]};
    endcase
end

always @(*) begin
    case (CTRL)
        2'b00: stage2_out = {stage1_out[SHIFT[3:0]], stage1_out[15:SHIFT[3:0]+1]};
        2'b01: stage2_out = {{SHIFT[3:0]}, stage1_out[15:SHIFT[3:0]+1]};
        2'b10: stage2_out = {{16{stage1_out[15]}}, stage1_out[15:SHIFT[3:0]+1]};
        2'b11: stage2_out = {stage1_out[SHIFT[3:0]], stage1_out[15:SHIFT[3:0]]};
    endcase
end

assign out = stage2_out;

endmodule

