module spi (
    input wire [N-1:0] datain,
    input wire en,
    input wire reset,
    input wire clk,
    output reg miso,
    output reg [N-1:0] dataout,
    output reg done,
    output reg mosi,
    output reg cs,
    output reg sclk
);

parameter N=8;
reg [N-1:0] data;
reg [N-1:0] data_temp;
reg [3:0] count;
reg [3:0] index;

assign dataout = data;

always @(posedge clk) begin
    if (reset) begin
        data <= 0;
        count <= 0;
        index <= 0;
        miso <= 0;
        done <= 0;
        mosi <= 0;
        cs <= 0;
        sclk <= 0;
    end else if (en) begin
        if (count == 0) begin
            data_temp <= datain;
            index <= N-1;
            mosi <= data_temp[N-1];
            cs <= 1;
            sclk <= 1;
            count <= count + 1;
        end else if (count == 1) begin
            mosi <= data_temp[N-2];
            sclk <= 0;
            count <= count + 1;
        end else if (count == 2) begin
            miso <= datain;
            sclk <= 1;
            count <= count + 1;
        end else if (count == 3) begin
            data[N-1-index] <= miso;
            index <= index - 1;
            sclk <= 0;
            if (index == 0) begin
                count <= count + 1;
            end else begin
                count <= 1;
            end
        end else if (count == 4) begin
            mosi <= data_temp[N-3];
            sclk <= 1;
            count <= count + 1;
        end else if (count == 5) begin
            miso <= datain;
            sclk <= 0;
            count <= count + 1;
        end else if (count == 6) begin
            data[N-1-index] <= miso;
            index <= index - 1;
            sclk <= 1;
            if (index == 0) begin
                count <= count + 1;
            end else begin
                count <= 4;
            end
        end else if (count == 7) begin
            mosi <= data_temp[N-4];
            sclk <= 0;
            count <= count + 1;
        end else if (count == 8) begin
            miso <= datain;
            sclk <= 1;
            count <= count + 1;
        end else if (count == 9) begin
            data[N-1-index] <= miso;
            index <= index - 1;
            sclk <= 0;
            if (index == 0) begin
                count <= count + 1;
                done <= 1;
                cs <= 0;
            end else begin
                count <= 7;
            end
        end else begin
            count <= 0;
        end
    end else begin
        cs <= 0;
        sclk <= 0;
    end
end

endmodule

module dcr_if(
  // DCR BUS
  clk,           // I
  rst,           // I
  DCR_ABus,      // I [0:9]
  DCR_DBusIn,    // I [0:31]
  DCR_Read,      // I
  DCR_Write,     // I
  DCR_Ack,       // O
  DCR_DBusOut,   // O [0:31]
  // Registers
  tft_base_addr, // O [0:10]    
  tft_dps_reg,   // O
  tft_on_reg     // O
  );

///////////////////////////////////////////////////////////////////////////////
// Port Declarations
/////////////////////////////////////////////////////////////////////////////// 

  input         clk;
  input         rst;
  input  [0:9]  DCR_ABus;
  input  [0:31] DCR_DBusIn;
  input         DCR_Read;
  input         DCR_Write;
  output        DCR_Ack;
  output [0:31] DCR_DBusOut;
  output [0:10] tft_base_addr;
  output        tft_dps_reg;
  output        tft_on_reg;
  wire   [0:31] DCR_DBusOut;
  reg           DCR_Ack;

///////////////////////////////////////////////////////////////////////////////
// Parameter Declarations
///////////////////////////////////////////////////////////////////////////////

  parameter C_DCR_BASE_ADDR = 10'b00_0000_0000;
  parameter C_DEFAULT_TFT_BASE_ADDR = 31'b0000_0000_0000_0000_0000_0000_0000_0000;
  parameter C_DPS_INIT = 1'b1;
  parameter C_ON_INIT = 1'b1;

///////////////////////////////////////////////////////////////////////////////
// Signal Declaration
///////////////////////////////////////////////////////////////////////////////

  wire        dcr_addr_hit;
  wire [0:9]  dcr_base_addr;
  reg         dcr_read_access;
  reg  [0:31] read_data;
  reg  [0:10] tft_base_addr;
  reg         tft_dps_reg;
  reg         tft_on_reg;

///////////////////////////////////////////////////////////////////////////////
// DCR Register Interface 
///////////////////////////////////////////////////////////////////////////////


  assign dcr_base_addr = C_DCR_BASE_ADDR;
  assign dcr_addr_hit  = (DCR_ABus[0:8] == dcr_base_addr[0:8]);

  always @(posedge clk)
  begin
    dcr_read_access <=  DCR_Read              & dcr_addr_hit;
    DCR_Ack         <= (DCR_Read | DCR_Write) & dcr_addr_hit;
  end

  always @(posedge clk)
    if (rst)
      tft_base_addr <= C_DEFAULT_TFT_BASE_ADDR[31:21]; 
    else if (DCR_Write & ~DCR_Ack & dcr_addr_hit & (DCR_ABus[9] == 1'b0))
      tft_base_addr <= DCR_DBusIn[0:10];

  always @(posedge clk)
    if (rst) begin
      tft_dps_reg <= C_DPS_INIT;
      tft_on_reg  <= C_ON_INIT;
    end
    else if (DCR_Write & ~DCR_Ack & dcr_addr_hit & (DCR_ABus[9] == 1'b1)) begin
      tft_dps_reg <= DCR_DBusIn[30];
      tft_on_reg  <= DCR_DBusIn[31];
    end

  always @(posedge clk)
    if (DCR_Read & dcr_addr_hit & ~DCR_Ack)
      read_data <= (DCR_ABus[9] == 1'b0)? {tft_base_addr, 21'b0} :
                                          {30'b0, tft_dps_reg, tft_on_reg};

  assign DCR_DBusOut = (dcr_read_access)? read_data : DCR_DBusIn;

endmodule

module jaxa_receiveFIFODataOut (
    // inputs:
    address,
    clk,
    in_port,
    reset_n,

    // outputs:
    readdata
);

    output  [ 31: 0] readdata;
    input   [  1: 0] address;
    input            clk;
    input   [  8: 0] in_port;
    input            reset_n;

    // FIFO buffers
    reg [8:0] buffer0 [0:31];
    reg [8:0] buffer1 [0:31];
    reg [4:0] head0;
    reg [4:0] tail0;
    reg [4:0] head1;
    reg [4:0] tail1;

    // buffer0 full and empty flags
    reg buffer0_full;
    reg buffer0_empty;

    // buffer1 full and empty flags
    reg buffer1_full;
    reg buffer1_empty;

    // read data
    reg [31:0] readdata;

    // clock enable
    wire clk_en;
    assign clk_en = 1;

    // check if buffer0 is full
    always @*
    begin
        buffer0_full = (head0 + 1) == tail0;
    end

    // check if buffer0 is empty
    always @*
    begin
        buffer0_empty = head0 == tail0;
    end

    // check if buffer1 is full
    always @*
    begin
        buffer1_full = (head1 + 1) == tail1;
    end

    // check if buffer1 is empty
    always @*
    begin
        buffer1_empty = head1 == tail1;
    end

    // select the buffer based on the address input
    always @*
    begin
        if (address == 0)
        begin
            if (!buffer0_full)
            begin
                buffer0[head0] <= in_port;
                head0 <= head0 + 1;
            end
        end
        else
        begin
            if (!buffer1_full)
            begin
                buffer1[head1] <= in_port;
                head1 <= head1 + 1;
            end
        end
    end

    // read data from the buffer based on the address input
    always @(posedge clk or negedge reset_n)
    begin
        if (reset_n == 0)
        begin
            readdata <= 0;
            head0 <= 0;
            tail0 <= 0;
            head1 <= 0;
            tail1 <= 0;
        end
        else if (clk_en)
        begin
            if (address == 0)
            begin
                if (!buffer0_empty)
                begin
                    readdata <= buffer0[tail0];
                    tail0 <= tail0 + 1;
                end
                else
                begin
                    readdata <= 0;
                end
            end
            else
            begin
                if (!buffer1_empty)
                begin
                    readdata <= buffer1[tail1];
                    tail1 <= tail1 + 1;
                end
                else
                begin
                    readdata <= 0;
                end
            end
        end
    end

endmodule

