module bluetooth (
  input wire clk,
  input wire rst,
  input wire start_tx,
  input wire bt_rx,
  input wire start_rx,
  output reg bt_tx,
  output reg [31:0] data_out
);

  // Define packet structure
  parameter PACKET_SIZE = 4;
  reg [7:0] packet [PACKET_SIZE-1:0];
  reg [2:0] packet_index = 0;
  reg packet_started = 0;

  // Define GFSK modulation scheme
  parameter BAUD_RATE = 1000000;
  parameter BIT_RATE = BAUD_RATE / 2;
  parameter MODULATION_INDEX = 0.5;
  reg [31:0] phase_accumulator = 0;
  reg [31:0] bit_accumulator = 0;
  reg [31:0] bit_counter = 0;
  reg [31:0] bit_period = clk / BIT_RATE;
  reg [31:0] symbol_period = clk / BAUD_RATE;
  reg [31:0] symbol_counter = 0;
  reg [31:0] symbol = 0;

  // Transmitter functionality
  always @ (posedge clk) begin
    if (rst) begin
      bt_tx <= 0;
      packet_index <= 0;
      packet_started <= 0;
      phase_accumulator <= 0;
      bit_accumulator <= 0;
      bit_counter <= 0;
      symbol_period <= clk / BAUD_RATE;
      symbol_counter <= 0;
      symbol <= 0;
    end else begin
      if (start_tx) begin
        packet_index <= 0;
        packet_started <= 1;
      end

      if (packet_started) begin
        // Load data into packet
        packet[packet_index] <= data_in;
        packet_index <= packet_index + 1;

        // Check if packet is complete
        if (packet_index == PACKET_SIZE) begin
          packet_index <= 0;
          packet_started <= 0;
        end
      end

      if (!packet_started) begin
        // Modulate data using GFSK
        if (bit_counter == 0) begin
          bit_accumulator <= packet[symbol][bit_counter];
          bit_counter <= bit_counter + 1;
        end else if (bit_counter == 7) begin
          bit_accumulator <= bit_accumulator ^ packet[symbol][bit_counter];
          bit_counter <= 0;
          symbol_counter <= symbol_counter + 1;
          if (symbol_counter == symbol_period) begin
            symbol_counter <= 0;
            symbol <= symbol + 1;
          end
        end else begin
          bit_accumulator <= bit_accumulator ^ packet[symbol][bit_counter];
          bit_counter <= bit_counter + 1;
        end

        phase_accumulator <= phase_accumulator + (bit_accumulator ? MODULATION_INDEX : -MODULATION_INDEX);
        bt_tx <= (phase_accumulator[31] ^ phase_accumulator[30]) ? 1 : 0;
      end
    end
  end

  // Receiver functionality
  always @ (posedge clk) begin
    if (rst) begin
      data_out <= 0;
      packet_index <= 0;
      packet_started <= 0;
      phase_accumulator <= 0;
      bit_accumulator <= 0;
      bit_counter <= 0;
      symbol_period <= clk / BAUD_RATE;
      symbol_counter <= 0;
      symbol <= 0;
    end else begin
      if (start_rx) begin
        packet_index <= 0;
        packet_started <= 1;
      end

      if (bt_rx == 1 && !packet_started) begin
        packet_index <= 0;
        packet_started <= 1;
      end

      if (packet_started) begin
        // Demodulate data using GFSK
        phase_accumulator <= phase_accumulator + (bt_rx ? MODULATION_INDEX : -MODULATION_INDEX);
        bit_accumulator <= bit_accumulator << 1;
        bit_accumulator[0] <= phase_accumulator[31] ^ phase_accumulator[30];
        bit_counter <= bit_counter + 1;
        if (bit_counter == 8) begin
          packet[packet_index] <= bit_accumulator;
          packet_index <= packet_index + 1;
          bit_counter <= 0;
          bit_accumulator <= 0;
        end

        // Check if packet is complete
        if (packet_index == PACKET_SIZE) begin
          packet_index <= 0;
          packet_started <= 0;
          data_out <= {packet[3], packet[2], packet[1], packet[0]};
        end
      end
    end
  end

endmodule

