module barrel_shifter
    (
    input aclr,
    input clk_en,
    input clock,
    input [15:0] data,
    input [3:0] distance,
    output [15:0] result
    );

    reg [31:0] shifted_data;

    always @(posedge clock or posedge aclr) begin
        if (aclr) begin
            shifted_data <= 0;
        end else if (clk_en) begin
            if (distance[3] == 0) begin
                // Fixed-point mode
                if (distance[2] == 0) begin
                    if (distance[1] == 0) begin
                        if (distance[0] == 0) begin
                            // No shift
                            shifted_data <= data;
                        end else if (distance[0] > 0) begin
                            // Shift left
                            if (data[15-distance[0]+1:0] != {16-distance[0]{1'b0}}) begin
                                // Overflow
                                shifted_data <= {16{data[15]}};
                            end else begin
                                shifted_data <= {data[15-distance[0]:0], {distance[0]{1'b0}}};
                            end
                        end else begin
                            // Shift right
                            if (data[15:distance[0]] != {16-distance[0]{1'b0}}) begin
                                // Underflow
                                shifted_data <= {16{data[0]}};
                            end else begin
                                shifted_data <= {{distance[0]{1'b0}}, data[15:distance[0]+1]};
                            end
                        end
                    end else begin
                        // Shift left or right by 1-8 bits
                        if (distance[0] > 0) begin
                            // Shift left
                            if (data[15-distance[1:0]+1:0] != {16-distance[1:0]{1'b0}}) begin
                                // Overflow
                                shifted_data <= {16{data[15]}};
                            end else begin
                                shifted_data <= {data[15-distance[1:0]:0], {distance[1:0]{1'b0}}};
                            end
                        end else begin
                            // Shift right
                            if (data[15:distance[1:0]] != {16-distance[1:0]{1'b0}}) begin
                                // Underflow
                                shifted_data <= {16{data[0]}};
                            end else begin
                                shifted_data <= {{distance[1:0]{1'b0}}, data[15:distance[1:0]+1]};
                            end
                        end
                    end
                end else begin
                    // Shift left or right by 9-16 bits
                    if (distance[1:0] == 0) begin
                        if (distance[2] > 0) begin
                            // Shift left
                            if (data[15-distance[3]+1:0] != {16-distance[3]{1'b0}}) begin
                                // Overflow
                                shifted_data <= {16{data[15]}};
                            end else begin
                                shifted_data <= {data[15-distance[3]:0], {distance[3]{1'b0}}};
                            end
                        end else begin
                            // Shift right
                            if (data[15:distance[3]] != {16-distance[3]{1'b0}}) begin
                                // Underflow
                                shifted_data <= {16{data[0]}};
                            end else begin
                                shifted_data <= {{distance[3]{1'b0}}, data[15:distance[3]+1]};
                            end
                        end
                    end else begin
                        // Invalid distance
                        shifted_data <= {16{1'bx}};
                    end
                end
            end else begin
                // Floating-point mode
                if (distance[2] == 0 && distance[1:0] == 0) begin
                    // Add or subtract from exponent
                    if (distance[3] > 0) begin
                        // Increment exponent
                        if (shifted_data[30:23] == 8'b11111110) begin
                            // Overflow
                            shifted_data <= {1'b0, 8'b11111111, 23'b0};
                        end else begin
                            shifted_data <= {shifted_data[31], shifted_data[30:23]+1, shifted_data[22:0]};
                        end
                    end else if (distance[3] < 0) begin
                        // Decrement exponent
                        if (shifted_data[30:23] == 8'b00000001) begin
                            // Underflow
                            shifted_data <= {1'b0, 8'b00000000, 23'b1};
                        end else begin
                            shifted_data <= {shifted_data[31], shifted_data[30:23]-1, shifted_data[22:0]};
                        end
                    end else begin
                        // No shift
                        shifted_data <= {data[15], data[14], data[13:0], 10'b0};
                    end
                end else begin
                    // Invalid distance
                    shifted_data <= {16{1'bx}};
                end
            end
        end
    end

    assign result = shifted_data[15:0];

endmodule

