module memory_interface(
    input clk,
    input rst,
    input [15:0] data_in,
    input [15:0] addr,
    input write_enable,
    output reg [15:0] data_out
);

reg [15:0] mem_data_in;
reg [15:0] mem_data_out;
reg mem_en;
reg mem_write_enable;
reg mem_byte_select;
reg mem_byte_enable;
reg [15:0] mem_addr;

wire mem_wait;

// Instantiate memory module
mem memory (
    .clk(clk),
    .rst(rst),
    .en(mem_en),
    .write_enable(mem_write_enable),
    .byte_select(mem_byte_select),
    .byte_enable(mem_byte_enable),
    .addr(mem_addr),
    .data_in(mem_data_in),
    .data_out(mem_data_out),
    .mem_wait(mem_wait)
);

// Reset memory on power-up
always @(posedge clk) begin
    if (rst) begin
        mem_en <= 0;
        mem_write_enable <= 0;
        mem_byte_select <= 0;
        mem_byte_enable <= 0;
        mem_addr <= 0;
        mem_data_in <= 0;
        data_out <= 0;
    end
end

// Write to memory
always @(posedge clk) begin
    if (write_enable) begin
        mem_en <= 1;
        mem_write_enable <= 1;
        mem_byte_select <= 0;
        mem_byte_enable <= 1;
        mem_addr <= addr;
        mem_data_in <= data_in;
    end else begin
        mem_en <= 1;
        mem_write_enable <= 0;
        mem_byte_select <= 0;
        mem_byte_enable <= 0;
        mem_addr <= addr;
    end
end

// Read from memory
always @(posedge clk) begin
    if (!write_enable && !mem_wait) begin
        data_out <= mem_data_out;
    end
end

endmodule

module edge_detector (
    input clk,
    input [7:0] in,
    output [7:0] anyedge
);

reg [7:0] prev_in;
reg [7:0] curr_in;
reg [7:0] edge_detected;

parameter IDLE = 2'b00;
parameter DETECT = 2'b01;
parameter OUTPUT = 2'b10;

reg [1:0] state;

always @(posedge clk) begin
    case (state)
        IDLE: begin
            curr_in <= in;
            prev_in <= curr_in;
            edge_detected <= 0;
            state <= DETECT;
        end
        DETECT: begin
            curr_in <= in;
            if (curr_in != prev_in) begin
                edge_detected <= curr_in & ~prev_in;
                state <= OUTPUT;
            end else begin
                state <= IDLE;
            end
            prev_in <= curr_in;
        end
        OUTPUT: begin
            anyedge <= edge_detected;
            state <= IDLE;
        end
    endcase
end

endmodule

