module dpth_alu_top (
  //------------------------------
  // Top level control signals
  //------------------------------
  input  wire        clk,
  input  wire        rst_n,
  //------------------------------
  // Inputs
  //------------------------------
  input  wire [15:0] rx,
  input  wire [15:0] m_data,
  input  wire        ld_ir,
  input  wire        ld_ra,
  input  wire        ld_rz,
  input  wire        ld_rn,
  //------------------------------
  // Outputs
  //------------------------------
  output reg  [15:0] ir,
  output wire [15:0] alu_out,
  output reg         rz,
  output reg         rn
);

  //------------------------------
  // Local registers
  //------------------------------
  reg  [15:0] ra;

  //------------------------------
  // Local wires
  //------------------------------
  wire [15:0] ir_ext;
  wire [15:0] alu_in_a;
  reg  [15:0] alu_in_b;
  wire        alu_z;
  wire        alu_n;

  //------------------------------
  // Local registers assignments
  //------------------------------
  always @(negedge rst_n, posedge clk)
  begin: p_alu_ir_update

    if (rst_n == 1'b0)
      ir <= {16{1'b0}};
    else if (ld_ir == 1'b1)
      ir <= m_data;

  end

  always @(negedge rst_n, posedge clk)
  begin: p_alu_ra_update

    if (rst_n == 1'b0)
      ra <= {16{1'b0}};
    else if (ld_ra == 1'b1)
      ra <= rx;

  end

  always @(negedge rst_n, posedge clk)
  begin: p_alu_rz_update

    if (rst_n == 1'b0)
      rz <= 1'b0;
    else if (ld_rz == 1'b1)
      rz <= alu_z;

  end


  always @(negedge rst_n, posedge clk)
  begin: p_alu_rn_update

    if (rst_n == 1'b0)
      rn <= 1'b0;
    else if (ld_rn == 1'b1)
      rn <= alu_n;

  end

  //------------------------------
  // SELDAT mux
  //------------------------------
  always @(*)
  begin : p_seldat_mux

    if (ir[14] == 1'b0)
      alu_in_b = m_data;
    else if (ir[2] == 1'b0)
      alu_in_b = ir_ext;
    else
      alu_in_b = rx;

  end

  //------------------------------
  // Local wires
  //------------------------------
  assign ir_ext = {{12{ir[7]}}, ir[6:3]};

  //------------------------------
  // ALU
  //------------------------------
  dpth_alu alu (
    // Input operands
    .in_a  ( alu_in_a ),
    .in_b  ( alu_in_b ),
    // Output result
    .out   ( alu_out  ),
    // Input control
    .op    ( ir[1:0]  ),
    .enable( operate  ),
    // Output parameters
    .z     ( alu_z    ),
    .n     ( alu_n    )
  );

  //------------------------------
  // ALU input selection
  //------------------------------
  assign alu_in_a = (ir[15] == 1'b0) ? ra : 16'b0;

  //------------------------------
  // ALU output selection
  //------------------------------
  always @(*)
  begin : p_alu_out_sel

    case (ir[1:0])
      2'b00: alu_in_a = alu_in_a + alu_in_b; // ADD
      2'b01: alu_in_a = alu_in_a - alu_in_b; // SUB
      2'b10: alu_in_a = alu_in_a & alu_in_b; // AND
      2'b11: alu_in_a = alu_in_a | alu_in_b; // OR
    endcase

    if (alu_out == 16'b0)
      rz = 1'b1;
    else
      rz = 1'b0;

    if (alu_out[15] == 1'b1)
      rn = 1'b1;
    else
      rn = 1'b0;

  end

endmodule

