module barrel_shift_3bit_reg_and_gate (
    input clk,
    input [3:0] data_in,
    input [1:0] shift_amount,
    input [2:0] parallel_load,
    input shift,
    input control,
    output [2:0] out
);

    // 4-bit Barrel Shifter
    reg [3:0] shifted_data;
    always @(*) begin
        case(shift_amount)
            2'b00: shifted_data = data_in;
            2'b01: shifted_data = {data_in[3], data_in[0:2]};
            2'b10: shifted_data = {data_in[2:3], data_in[0:1]};
            2'b11: shifted_data = {data_in[1:3], data_in[0]};
            default: shifted_data = 4'b0000;
        endcase
    end

    // 3-bit Shift Register
    reg [2:0] reg_data;
    always @(posedge clk) begin
        if(shift) begin
            if(control) reg_data <= {reg_data[1:0], 1'b0};
            else reg_data <= {1'b0, reg_data[2:1]};
        end
        else if(parallel_load != 3'b111) begin
            reg_data <= parallel_load;
        end
    end

    // AND Gate
    assign out = shifted_data & reg_data;

endmodule

module axis_gen_pulse #(
  parameter DLY = 1,
  parameter INTERLACE = 0,
  parameter DATA_WIDTH = 24
 )
(
    input   wire        aclk,
    input   wire        rst,
    input   wire        axis_tready,
    output  wire        axis_tvalid,
    output  reg  [DATA_WIDTH-1:0] axis_tdata_video,
    output  reg         axis_tlast,
    output  reg         fid,
    output  reg         axis_tuser_sof,
    output  reg         axis_tuser_pulse,
    input   wire [13:0]  active_pixels,
    input   wire  [13:0]  active_lines
 );

// variable declarations

reg [13:0]   pixel_count = 0;
reg [13:0]    line_count = 0;
wire        eol;
wire        sof;        
reg         eol_1;
wire        set_axis_tvalid;
real        duty_cycle_phase_accum;

assign eol = pixel_count == active_pixels - 1;
assign sof = line_count == 0 && pixel_count == 0;
assign axis_tvalid = 1;

// delay eol
always @ (posedge aclk) 
  eol_1 <= eol;

//
// pixel counter
//
// Cleared to 0 on reset and at active pixels - 1.  Otherwise
// increments every clock cycle.
//  
always @ (posedge aclk) begin
    if (axis_tready & axis_tvalid)
    begin
        if (rst || eol)
             pixel_count <= 0;
        else
             pixel_count <= pixel_count + 1;
    end
end
//
// Line counter
//
// Set to line 0 on reset or max lines. Increments coincident with pixel 0.
//
always @ (posedge aclk)
    if (axis_tready)
    begin
        if (rst || ((line_count >= active_lines - 1) && eol) )begin
            line_count <=  0;
	    end
        else if (eol)
            line_count <=  line_count + 1;
    end


// Generate the video outputs.  The video is gengerated procedurally
// according to the line and pixel number.  This makes it so the checking
// side can reconstruct the expected data by the same procedure.

always @ (posedge aclk)	 begin
  if (rst) begin
    axis_tlast     <= 0;
    axis_tuser_sof <= 0;
    axis_tuser_pulse <= 0;
    if (INTERLACE)
      fid <= 1;
    else 
	   fid <= 0;
  end
  else if (axis_tready) begin
    axis_tdata_video <= INTERLACE && ((!fid && sof) || (fid && !sof))?
      {~line_count, ~pixel_count[11:0]}:
      {line_count, pixel_count[11:0]};
	axis_tlast <= eol;
	axis_tuser_sof <= sof;
    // set field ID bit
	if (INTERLACE) begin
	  if (sof)
	    fid <= ~fid;	    
	end
	else begin
	  fid <= 0;	  // always field 0 if not interlaced
	end
    if (eol && !eol_1) begin
      axis_tuser_pulse <= 1;
    end
    else begin
      axis_tuser_pulse <= 0;
    end
  end
end 

endmodule

module CPU (
	input         reset,
	input         clk_neg,
	input         clk_pos,
	input         ce_n,
	input         ce_p,
	output [15:0] cpu_addr,
	output  [7:0] cpu_dout,
	input   [7:0] cpu_din,
	output reg    nMREQ,
	output reg    nIORQ,
	input         nINT,
	output reg    nRD,
	output reg    nWR,
	output reg    nM1,
	output reg    nRFSH
);

reg [2:0] MCycle, MCycles;
reg [2:0] TState, TStates;

reg [15:0] A;

assign cpu_addr = A;

always @(posedge clk_pos, posedge reset) begin
	if (reset) begin
		MCycle <= 5;
		MCycles <= 5;
		TState <= 1;
		TStates <= 4;
		A <= 16'h0000;
		nMREQ <= 1;
		nIORQ <= 1;
		nRD <= 1;
		nWR <= 1;
		nM1 <= 0;
		nRFSH <= 1;
	end else if (ce_p)  begin

		if (TState == TStates) begin
			TState <= 1;
			if (MCycle == MCycles)
				MCycle <= 1;
			else
				MCycle <= MCycle + 1'd1;
		end else begin
			TState <= TState + 1'd1;
		end

		case (MCycle)
		1: // contented M1
			case (TState)
				2: begin {nMREQ, nRD, nM1} <= 3'b111; nRFSH <= 0; A<=16'h6000; end
				4: begin nRFSH <= 1; A<=16'hFFFF; TStates <= 6; end
			default: ;
			endcase

		2:
			case (TState)
			6: begin A<=16'h00FE; TStates <= 4; end
			default: ;
			endcase

		3: // contented IO
			case (TState)
			1: begin nIORQ <= 0; nRD <= 0; end
			4: begin A<=16'hFFFF; TStates <= 5; end
			default: ;
			endcase

		4:
			case (TState)
			5: TStates <= 4;
			default: ;
			endcase

		5:
			case (TState)
				4: begin A<=16'h4000; TStates <= 4; end
			default: ;
			endcase

			default: ;
			endcase

	end
end

// M1 cycle
always @(posedge clk_neg) begin
	if (ce_n) case (MCycle)

	1:
		case (TState)
		1: {nMREQ, nRD} <= 0;
		3: nMREQ <= 0;
		4: nMREQ <= 1;
		default: ;
		endcase

	2: ;

	3:
		case (TState)
		4: {nIORQ, nRD} <= 2'b11;
		default: ;
		endcase

	4: ;
	5: ;
	default: ;
	endcase
end

/* verilator lint_on MULTIDRIVEN */

endmodule

