module register32_3in(
    input clock,
    input clock_debug,
    input reset,
    input WriteEnable,
    input [4:0] read_address_1,
    input [4:0] read_address_2,
    input [4:0] read_address_3,
    input [31:0] write_data_in,
    input [4:0] write_address,
    input [4:0] read_address_debug,
    output [31:0] data_out_1,
    output [31:0] data_out_2,
    output [31:0] data_out_3,
    output [31:0] data_out_debug);
    reg [31:0] i;

    //Array of 32 registers
    reg [31:0] register[0:31];

    assign data_out_1 = ( read_address_1 == 0 ) ? 32'b0 : register[read_address_1]; 
    assign data_out_2 = ( read_address_2 == 0 ) ? 32'b0 : register[read_address_2]; 
    assign data_out_3 = ( read_address_3 == 0 ) ? 32'b0 : register[read_address_3];
    assign data_out_debug = ( read_address_debug == 0 ) ? 32'b0 : register[read_address_debug];

    //Write only on rising edge of clock and WriteEnable is high and reset if reset is high
    always @(posedge clock) begin
        if(WriteEnable &&(write_address != 5'b0))begin
            register[write_address] <= write_data_in;
        end
        if(reset)begin
            for(i=0;i<32;i=i+1)begin
                register[i] = 0;
            end
        end
    end


endmodule

module majority_gate(
    input a, 
    input b,
    input c,
    input reset,
    output wire out_assign,
    output reg out_alwaysblock
);

    // Majority gate using assign statements
    assign out_assign = (a & b) | (a & c) | (b & c);

    // Majority gate using a combinational always block
    always @(*) begin
        if (a & b & c) begin
            out_alwaysblock <= 1'b1;
        end else if (a & b) begin
            out_alwaysblock <= 1'b1;
        end else if (a & c) begin
            out_alwaysblock <= 1'b1;
        end else if (b & c) begin
            out_alwaysblock <= 1'b1;
        end else begin
            out_alwaysblock <= 1'b0;
        end
    end

    // Synchronous reset input
    always @(posedge reset) begin
        out_alwaysblock <= 1'b0;
    end

endmodule

module adder_8bit (
  input clk,
  input reset,
  input [7:0] a,
  input [7:0] b,
  output reg [8:0] sum
);

genvar i;
generate
  for (i = 0; i < 8; i = i + 1) begin : adder
    full_adder adder_inst(
      .a(a[i]),
      .b(b[i]),
      .cin(sum[i]),
      .sum(sum[i+1]),
      .cout(carry_out[i])
    );
  end
endgenerate

assign overflow = carry_out[7] ^ carry_out[6];
assign carry_out[8] = carry_out[7];

endmodule
module full_adder (
  input a,
  input b,
  input cin,
  output reg sum,
  output reg cout
);

always @ (a or b or cin) begin
  sum = a ^ b ^ cin;
  cout = (a & b) | (a & cin) | (b & cin);
end

endmodule

module top_module(
    input clk,
    input areset,   // async active-high reset to zero
    input [7:0] d,
    input sel,
    input load,
    input ena,
    input [3:0] data,
    output reg [7:0] q
);

    // First module with 8 D flip-flops triggered by negative edge of clk
    reg [7:0] dff_q;
    always @(negedge clk or posedge areset) begin
        if (areset) begin
            dff_q <= 8'b0;
        end else begin
            dff_q <= {dff_q[3:0], dff_q[7:4]};
        end
    end

    // Multiplexer to select output of first 4 DFFs or last 4 DFFs based on select input
    wire [3:0] first_half = dff_q[3:0];
    wire [3:0] second_half = dff_q[7:4];
    wire [3:0] mux_out;
    assign mux_out = (sel == 1'b0) ? first_half : second_half;

    // Second module with 4-bit shift register with asynchronous reset, synchronous load, and enable
    reg [3:0] shift_reg;
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            shift_reg <= 4'b0;
        end else if (load) begin
            shift_reg <= data;
        end else if (ena) begin
            shift_reg <= {1'b0, shift_reg[3:1]};
        end
    end

    // XOR module to combine outputs of the two given modules
    wire [7:0] xor_out;
    assign xor_out = shift_reg ^ mux_out;

    // Output of the top module
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            q <= 8'b0;
        end else begin
            q <= xor_out;
        end
    end

endmodule

module audio_ctrl_ip
    #(
        parameter DATA_WIDTH = 32
    )
    (
        input wire aclk,
        input wire aresetn,
        input wire [31:0] awaddr,
        input wire awvalid,
        input wire [31:0] wdata,
        input wire wvalid,
        input wire [31:0] araddr,
        input wire arvalid,
        output wire [31:0] rdata,
        output wire rvalid,
        output wire [1:0] audio_rxd,
        output wire audio_rxd_en,
        input wire [1:0] audio_txd,
        input wire audio_txd_en
    );

    // AXI Lite registers
    reg [31:0] data_reg;
    reg [1:0] rxd_reg;
    reg rxd_en_reg;
    reg wdone_reg;
    reg rvalid_reg;
    reg [1:0] txd_reg;
    reg txd_en_reg;

    // AXI Lite state machine
    localparam IDLE = 2'b00;
    localparam WRITE = 2'b01;
    localparam READ = 2'b10;
    reg [1:0] axi_state_reg;
    reg [31:0] axi_addr_reg;
    reg [31:0] axi_data_reg;

    always @(posedge aclk) begin
        if (!aresetn) begin
            rxd_reg <= 2'b00;
            rxd_en_reg <= 1'b0;
            wdone_reg <= 1'b0;
            rvalid_reg <= 1'b0;
            txd_reg <= 2'b00;
            txd_en_reg <= 1'b0;
            axi_state_reg <= IDLE;
            axi_addr_reg <= 32'h0;
            axi_data_reg <= 32'h0;
            data_reg <= 32'h0;
        end else begin
            case (axi_state_reg)
                IDLE: begin
                    if (awvalid) begin
                        axi_state_reg <= WRITE;
                        axi_addr_reg <= awaddr;
                        axi_data_reg <= wdata;
                    end else if (arvalid) begin
                        axi_state_reg <= READ;
                        axi_addr_reg <= araddr;
                    end
                end
                WRITE: begin
                    if (!awvalid) begin
                        wdone_reg <= 1'b1;
                        axi_state_reg <= IDLE;
                    end
                end
                READ: begin
                    if (rvalid) begin
                        rvalid_reg <= 1'b1;
                        data_reg <= rdata;
                        axi_state_reg <= IDLE;
                    end
                end
            endcase
            if (wvalid && !wdone_reg) begin
                data_reg <= wdata;
            end
            if (rvalid_reg && !rvalid) begin
                rvalid_reg <= 1'b0;
            end
            if (axi_state_reg == WRITE || axi_state_reg == READ) begin
                txd_en_reg <= 1'b1;
                case (rxd_reg)
                    2'b00: begin
                        txd_reg <= 2'b10;
                        audio_rxd_en <= 1'b0;
                    end
                    2'b01: begin
                        txd_reg <= 2'b10;
                        audio_rxd_en <= 1'b1;
                    end
                    2'b10: begin
                        txd_reg <= 2'b01;
                        audio_rxd_en <= 1'b0;
                    end
                    2'b11: begin
                        txd_reg <= 2'b01;
                        audio_rxd_en <= 1'b1;
                    end
                endcase
            end else begin
                txd_en_reg <= 1'b0;
            end
            if (txd_en_reg) begin
                rxd_reg <= txd_reg;
            end
        end
    end

    assign rdata = data_reg;
    assign rvalid = rvalid_reg;
    assign audio_rxd = rxd_reg;
    assign audio_txd = txd_reg;
    assign audio_txd_en = txd_en_reg;

endmodule

