module i2c_master (
  input SDA,
  input SCL,
  input [7:0] slave_addr,
  input [7:0] data_in,
  input read_write,
  output [7:0] data_out
);

  reg [7:0] tx_data;
  reg [7:0] rx_data;
  reg [7:0] bit_counter;
  reg [7:0] addr;
  reg [7:0] i2c_state;
  reg [7:0] ack;

  parameter IDLE = 8'h00;
  parameter START = 8'h01;
  parameter SEND_ADDR = 8'h02;
  parameter SEND_DATA = 8'h03;
  parameter RESTART = 8'h04;
  parameter READ_DATA = 8'h05;
  parameter SEND_ACK = 8'h06;
  parameter SEND_NACK = 8'h07;
  parameter STOP = 8'h08;

  always @ (posedge SCL) begin
    if (i2c_state == IDLE && SDA == 1'b0 && SCL == 1'b1) begin
      i2c_state <= START;
      bit_counter <= 8'h01;
      addr <= slave_addr;
      tx_data <= {addr, read_write};
    end else if (i2c_state == START && SCL == 1'b1) begin
      SDA <= 1'b0;
      i2c_state <= SEND_ADDR;
    end else if (i2c_state == SEND_ADDR && SCL == 1'b1) begin
      if (bit_counter < 8'h09) begin
        SDA <= tx_data[bit_counter];
        bit_counter <= bit_counter + 1;
      end else begin
        SDA <= 1'b1;
        bit_counter <= 8'h01;
        if (read_write == 1'b0) begin
          i2c_state <= SEND_DATA;
          tx_data <= data_in;
        end else begin
          i2c_state <= RESTART;
        end
      end
    end else if (i2c_state == SEND_DATA && SCL == 1'b1) begin
      if (bit_counter < 8'h09) begin
        SDA <= tx_data[bit_counter];
        bit_counter <= bit_counter + 1;
      end else begin
        SDA <= 1'b1;
        bit_counter <= 8'h01;
        i2c_state <= STOP;
      end
    end else if (i2c_state == RESTART && SCL == 1'b1) begin
      SDA <= 1'b0;
      i2c_state <= READ_DATA;
      bit_counter <= 8'h01;
    end else if (i2c_state == READ_DATA && SCL == 1'b1) begin
      if (bit_counter < 8'h09) begin
        rx_data[bit_counter] <= SDA;
        bit_counter <= bit_counter + 1;
      end else begin
        bit_counter <= 8'h01;
        if (ack == 1'b1) begin
          SDA <= 1'b0;
          i2c_state <= SEND_ACK;
        end else begin
          SDA <= 1'b1;
          i2c_state <= STOP;
        end
      end
    end else if (i2c_state == SEND_ACK && SCL == 1'b1) begin
      SDA <= 1'b1;
      i2c_state <= READ_DATA;
      bit_counter <= 8'h01;
    end else if (i2c_state == STOP && SCL == 1'b1) begin
      SDA <= 1'b0;
      i2c_state <= IDLE;
      bit_counter <= 8'h01;
      data_out <= rx_data;
    end
  end

  always @ (posedge SCL) begin
    if (i2c_state == SEND_ADDR && SCL == 1'b0) begin
      ack <= SDA;
    end else if (i2c_state == READ_DATA && SCL == 1'b0) begin
      ack <= 1'b1;
    end
  end

endmodule

module i2c_slave (
  input SDA,
  input SCL,
  input [7:0] own_addr,
  input [7:0] data_in,
  output [7:0] data_out
);

  reg [7:0] rx_data;
  reg [7:0] tx_data;
  reg [7:0] bit_counter;
  reg [7:0] i2c_state;
  reg [7:0] addr;
  reg [7:0] ack;

  parameter IDLE = 8'h00;
  parameter READ_ADDR = 8'h01;
  parameter READ_DATA = 8'h02;
  parameter SEND_DATA = 8'h03;
  parameter SEND_ACK = 8'h04;
  parameter SEND_NACK = 8'h05;

  always @ (posedge SCL) begin
    if (i2c_state == IDLE && SDA == 1'b0 && SCL == 1'b1) begin
      i2c_state <= READ_ADDR;
      bit_counter <= 8'h01;
    end else if (i2c_state == READ_ADDR && SCL == 1'b1) begin
      if (bit_counter < 8'h09) begin
        addr[bit_counter] <= SDA;
        bit_counter <= bit_counter + 1;
      end else begin
        bit_counter <= 8'h01;
        if (addr == own_addr) begin
          i2c_state <= READ_DATA;
        end else begin
          i2c_state <= SEND_NACK;
        end
      end
    end else if (i2c_state == READ_DATA && SCL == 1'b1) begin
      if (bit_counter < 8'h09) begin
        bit_counter <= bit_counter + 1;
        ack <= 1'b0;
      end else begin
        bit_counter <= 8'h01;
        tx_data <= rx_data;
        i2c_state <= SEND_DATA;
      end
    end else if (i2c_state == SEND_DATA && SCL == 1'b1) begin
      if (bit_counter < 8'h09) begin
        SDA <= tx_data[bit_counter];
        bit_counter <= bit_counter + 1;
      end else begin
        SDA <= 1'b1;
        bit_counter <= 8'h01;
        i2c_state <= SEND_ACK;
      end
    end else if (i2c_state == SEND_ACK && SCL == 1'b1) begin
      if (SDA == 1'b0) begin
        rx_data <= data_in;
        i2c_state <= READ_ADDR;
      end else begin
        i2c_state <= IDLE;
      end
      bit_counter <= 8'h01;
    end else if (i2c_state == SEND_NACK && SCL == 1'b1) begin
      SDA <= 1'b1;
      i2c_state <= IDLE;
      bit_counter <= 8'h01;
    end
  end

endmodule

module top_module (
    input clk,
    input reset,
    input [31:0] a,
    input [31:0] b,
    input select,
    output reg [7:0] high_bit_chunk
);

    reg [31:0] sum;
    reg [2:0] high_bit_pos;
    wire [31:0] adder_out;
    wire [4:0] priority_enc_out;

    // Instantiate 32-bit adder module
    adder_32 adder_inst (
        .clk(clk),
        .reset(reset),
        .a(a),
        .b(b),
        .out(adder_out)
    );

    // Instantiate priority encoder module
    priority_encoder priority_enc_inst (
        .in(adder_out),
        .out(priority_enc_out)
    );

    // Control logic to select between adder and priority encoder
    always @ (posedge clk, posedge reset) begin
        if (reset) begin
            high_bit_pos <= 0;
            sum <= 0;
        end else begin
            if (select) begin
                high_bit_pos <= priority_enc_out;
                sum <= adder_out;
            end else begin
                high_bit_pos <= 0;
                sum <= a + b;
            end
        end
    end

    // Functional module to output high bit chunk
    always @ (high_bit_pos, sum) begin
        if (high_bit_pos == 0) begin
            high_bit_chunk <= sum[7:0];
        end else if (high_bit_pos == 1) begin
            high_bit_chunk <= sum[15:8];
        end else if (high_bit_pos == 2) begin
            high_bit_chunk <= sum[23:16];
        end else if (high_bit_pos == 3) begin
            high_bit_chunk <= sum[31:24];
        end
    end

endmodule


module adder_32 (
