module checksum (
  input [n-1:0] data_in,
  input check,
  input [n-1:0] checksum_in,
  output error,
  output [n-1:0] checksum_out
);

parameter n = 8; // number of data signals

reg [n-1:0] sum;
reg [n-1:0] checksum;

// Compute the checksum of the input data signals
always @ (data_in)
begin
  sum = 0;
  for (i = 0; i < n; i = i + 1)
    sum = sum + data_in[i];
  checksum = sum % n;
end

// Output the computed checksum
assign checksum_out = checksum;

// Compare the computed checksum to the input checksum signal
always @ (check, checksum_in, checksum)
begin
  if (check == 1'b0)
    error = 1'b0;
  else if (checksum == checksum_in)
    error = 1'b0;
  else
    error = 1'b1;
end

endmodule

