module uart(
    input clk,
    input rx,
    input [7:0] data_in,
    output tx,
    output [7:0] data_out,
    output rx_valid
);

    reg tx;
    reg [7:0] rdata;
    reg rx_valid_reg;
    wire [7:0] rx_char;
    reg [3:0] state;

    parameter IDLE = 2'b00;
    parameter START_BIT = 2'b01;
    parameter DATA_BITS = 2'b10;
    parameter PARITY_BIT = 2'b11;

    initial begin
        tx <= 1'b1;
        state <= IDLE;
    end

    always @(posedge clk) begin
        case(state)
            IDLE: begin
                tx <= 1'b1;
                if(!rx) begin
                    state <= START_BIT;
                end
            end
            START_BIT: begin
                tx <= 1'b0;
                state <= DATA_BITS;
            end
            DATA_BITS: begin
                tx <= data_in[0];
                rdata[0] <= rx;
                if(rdata[0] != data_in[0]) begin
                    state <= IDLE;
                end else begin
                    rdata[1] <= rx;
                    rdata[2] <= rx;
                    rdata[3] <= rx;
                    rdata[4] <= rx;
                    rdata[5] <= rx;
                    rdata[6] <= rx;
                    rdata[7] <= rx;
                    state <= PARITY_BIT;
                end
            end
            PARITY_BIT: begin
                tx <= 1'b1;
                rdata[8] <= rx;
                if(rdata[8] != (rdata[0]^rdata[1]^rdata[2]^rdata[3]^rdata[4]^rdata[5]^rdata[6]^rdata[7])) begin
                    state <= IDLE;
                end else begin
                    state <= IDLE;
                    rx_valid_reg <= 1;
                end
            end
        endcase
    end

    always @(posedge clk) begin
        if(rx_valid_reg) begin
            rx_valid <= 1;
            data_out <= rx_char;
            rx_valid_reg <= 0;
        end else begin
            rx_valid <= 0;
        end
    end

    // Receive
    always @(posedge clk) begin
        rx_char <= (rx_valid_reg)?rdata:8'd0;
    end

endmodule

