  input rx,
  input tx_valid,
  input [7:0] tx_data,
  output reg tx,
  output reg rx_valid,
  output reg [7:0] rx_data
);

  // Baud rate generator
  reg [15:0] baud_counter;
  reg [3:0] baud_rate_divisor = 16'h3D1; // 115200 baud
  always @(posedge clk) begin
    if (reset) begin
      baud_counter <= 0;
    end else begin
      if (baud_counter == baud_rate_divisor - 1) begin
        baud_counter <= 0;
      end else begin
        baud_counter <= baud_counter + 1;
      end
    end
  end

  // TX state machine
  reg [2:0] tx_state;
  reg [7:0] tx_shift_reg;
  reg tx_bit_count;
  always @(posedge clk) begin
    if (reset) begin
      tx_state <= 3'b000;
      tx_shift_reg <= 8'h00;
      tx_bit_count <= 0;
      tx <= 1;
    end else begin
      case (tx_state)
        3'b000: begin // Idle
          if (tx_valid) begin
            tx_state <= 3'b001;
            tx_shift_reg <= tx_data;
            tx_bit_count <= 8;
            tx <= 0;
          end
        end
        3'b001: begin // Start bit
          tx_state <= 3'b010;
        end
        3'b010: begin // Data bits
          if (baud_counter == baud_rate_divisor - 1) begin
            tx_shift_reg <= {1'b0, tx_shift_reg[7:1]};
            tx_bit_count <= tx_bit_count - 1;
            if (tx_bit_count == 0) begin
              tx_state <= 3'b011;
              tx <= 1;
            end
          end
        end
        3'b011: begin // Stop bit
          tx_state <= 3'b000;
        end
      endcase
    end
  end

  // RX state machine
  reg [2:0] rx_state;
  reg [7:0] rx_shift_reg;
  reg rx_bit_count;
  always @(posedge clk) begin
    if (reset) begin
      rx_state <= 3'b000;
      rx_shift_reg <= 8'h00;
      rx_bit_count <= 0;
      rx_valid <= 0;
      rx_data <= 8'h00;
    end else begin
      case (rx_state)
        3'b000: begin // Idle
          if (!rx) begin
            rx_state <= 3'b001;
            rx_shift_reg <= 8'h00;
            rx_bit_count <= 0;
          end
        end
        3'b001: begin // Start bit
          rx_state <= 3'b010;
        end
        3'b010: begin // Data bits
          if (baud_counter == baud_rate_divisor - 1) begin
            rx_shift_reg <= {rx, rx_shift_reg[7:1]};
            rx_bit_count <= rx_bit_count + 1;
            if (rx_bit_count == 8) begin
              rx_state <= 3'b011;
            end
          end
        end
        3'b011: begin // Stop bit
          rx_state <= 3'b000;
          rx_valid <= 1;
          rx_data <= rx_shift_reg;
        end
      endcase
    end
  end

endmodule

module top_module (
    input [3:0] A,
    input [3:0] B,
    input [3:0] C,
    input [3:0] D,
    input [1:0] SEL,
    input [3:0] data,
    input [3:0] shift_amount,
    input shift_left,
    input select,
    output [3:0] q
);

wire [3:0] mux_output;
wire [3:0] shifter_output;

mux_4to1 mux_inst (
    .A(A),
    .B(B),
    .C(C),
    .D(D),
    .SEL(SEL),
    .Y(mux_output)
);

barrel_shifter bs_inst (
    .data(data),
    .shift_amount(shift_amount),
    .shift_left(shift_left),
    .result(shifter_output)
);

assign q = (select) ? mux_output ^ shifter_output : 4'b0;

endmodule

module mux_4to1 (
    input [3:0] A,
    input [3:0] B,
    input [3:0] C,
    input [3:0] D,
    input [1:0] SEL,
    output [3:0] Y
);

assign Y = (SEL == 2'b00) ? A : (SEL == 2'b01) ? B : (SEL == 2'b10) ? C : D;

endmodule

module barrel_shifter (
    input [3:0] data,
    input [3:0] shift_amount,
    input shift_left,
    output [3:0] result
);

wire [3:0] temp;

assign temp = (shift_left) ? (data << shift_amount) : (data >> shift_amount);
assign result = temp;

endmodule

module LED_DISPLAY(
    input OF,
    input ZF,
    input [2:0] SW,
    input [31:0] ALU_F,
    output reg [7:0] LED
);

always @(*) begin
    case (SW)
        3'b000: LED = ALU_F;
        3'b001: LED = ~ALU_F;
        3'b010: LED = ALU_F << 1;
        3'b011: LED = ALU_F >> 1;
        3'b100: LED = ALU_F + 1;
        3'b101: LED = ALU_F - 1;
        3'b110: LED = ALU_F & 8'h55;
        3'b111: LED = ALU_F | 8'hAA;
    endcase
end

always @(OF, ZF) begin
    if (OF == 1)
        LED[7] = 1;
    else
        LED[7] = 0;

    if (ZF == 1)
        LED = 8'b0000_0000;
end

endmodule

module axi_to_custom_protocol_converter(
    input aclk,
    input areset_d1,
    input s_ready_i_reg,
    input si_rs_rready,
    input m_axi_rvalid,
    input [33:0] in,
    input [11:0] D,
    output m_valid_i_reg,
    output reg [1:0] state_reg,
    output m_axi_rready,
    output [33:0] out,
    output reg [12:0] skid_buffer_reg,
    input [1:0] state_reg_0,
    input r_rlast,
    output reg [12:0] trans_in
);

// Internal signals
reg [11:0] D_reg;
reg [33:0] in_reg;
reg [12:0] skid_buffer_reg_reg;
reg [12:0] trans_in_reg;
reg m_valid_i_reg_reg;
reg m_axi_rready_reg;
reg [33:0] out_reg;
reg [1:0] state_reg_reg;
reg r_push_r_reg;
reg r_rlast_reg;
reg [12:0] trans_in_reg_reg;

// Constants
localparam IDLE_STATE = 2'b00;
localparam READ_AXI_STATE = 2'b01;
localparam WRITE_CUSTOM_STATE = 2'b10;

// Register D on rising edge of clock
always @(posedge aclk) begin
    D_reg <= D;
end

// Register in on rising edge of clock
always @(posedge aclk) begin
    in_reg <= in;
end

// Register skid_buffer_reg on rising edge of clock
always @(posedge aclk) begin
    skid_buffer_reg_reg <= skid_buffer_reg;
end

// Register trans_in on rising edge of clock
always @(posedge aclk) begin
    trans_in_reg_reg <= trans_in_reg;
end

// Register state_reg on rising edge of clock
always @(posedge aclk) begin
    state_reg_reg <= state_reg;
end

// Register r_rlast on rising edge of clock
always @(posedge aclk) begin
    r_rlast_reg <= r_rlast;
end

// Register trans_in on falling edge of clock
always @(negedge aclk) begin
    trans_in_reg <= trans_in_reg_reg;
end

// Register state_reg on falling edge of clock
always @(negedge aclk) begin
    state_reg <= state_reg_reg;
end

// Register m_valid_i_reg on falling edge of clock
always @(negedge aclk) begin
    m_valid_i_reg <= m_valid_i_reg_reg;
end

// Register m_axi_rready on falling edge of clock
always @(negedge aclk) begin
    m_axi_rready <= m_axi_rready_reg;
end

// Register out on falling edge of clock
always @(negedge aclk) begin
    out <= out_reg;
end

// Register skid_buffer_reg on falling edge of clock
always @(negedge aclk) begin
    skid_buffer_reg <= skid_buffer_reg_reg;
end

// Register trans_in on rising edge of clock
always @(posedge aclk) begin
    trans_in_reg <= trans_in;
end

// State machine
always @(*) begin
    case(state_reg)
        IDLE_STATE: begin
            if(si_rs_rready && m_axi_rvalid) begin
                m_axi_rready_reg = 1'b1;
                state_reg_reg = READ_AXI_STATE;
                in_reg = in;
            end else begin
                m_axi_rready_reg = 1'b0;
                state_reg_reg = IDLE_STATE;
            end
        end
        READ_AXI_STATE: begin
            if(s_ready_i_reg) begin
                m_valid_i_reg_reg = 1'b1;
                state_reg_reg = WRITE_CUSTOM_STATE;
                trans_in_reg = {r_rlast_reg, in_reg};
            end else begin
                m_valid_i_reg_reg = 1'b0;
                state_reg_reg = READ_AXI_STATE;
                skid_buffer_reg_reg = {skid_buffer_reg_reg[11:0], in_reg};
            end
        end
        WRITE_CUSTOM_STATE: begin
            if(si_rs_rready) begin
                m_axi_rready_reg = 1'b1;
                state_reg_reg = IDLE_STATE;
            end else begin
                m_axi_rready_reg = 1'b0;
                state_reg_reg = WRITE_CUSTOM_STATE;
            end
            if(trans_in_reg_reg[12] && !r_push_r_reg) begin
                r_push_r_reg = 1'b1;
                out_reg = trans_in_reg_reg[11:0];
            end else begin
                r_push_r_reg = 1'b0;
                out_reg = out_reg;
            end
            if(r_push_r_reg) begin
                trans_in_reg_reg = {trans_in_reg_reg[10:0], 1'b0};
            end else begin
                trans_in_reg_reg = {trans_in_reg_reg[10:0], trans_in_reg_reg[12]};
            end
        end
    endcase
end

endmodule

