    xor_gate x2(.a(w1), .b(Cin), .o(S));
    and_gate a1(.a(A), .b(B), .o(w2));
    and_gate a2(.a(A), .b(Cin), .o(w3));
    and_gate a3(.a(B), .b(Cin), .o(Cout));
    or_gate o1(.a(w2), .b(w3), .o(Cout));
endmodule

