endmodule

module LED_controller(
    input CLK_50,
    input reset,
    input [3:0] switch_input,
    input edge_detector,
    input enable,
    output reg [7:0] LED_output
);

reg [7:0] pattern;
reg [2:0] counter;
reg enable_flag;
reg [1:0] rotation;
reg [2:0] shift;
reg mirror_flag;

wire rising_edge = edge_detector & !reset & (edge_detector ^ LED_output);

always @(posedge CLK_50 or posedge reset) begin
    if (reset) begin
        pattern <= 8'b00000000;
        counter <= 3'b000;
        enable_flag <= 0;
        rotation <= 2'b00;
        shift <= 3'b000;
        mirror_flag <= 0;
    end
    else begin
        case (switch_input)
            4'b0001: shift <= {shift[1:0], 1'b0};
            4'b0010: rotation <= rotation + 1;
            4'b0011: begin
                if (enable_flag) pattern <= pattern + 1;
                enable_flag <= enable;
            end
            4'b0100: mirror_flag <= ~mirror_flag;
            4'b0101: rotation <= rotation - 1;
            4'b0110: shift <= {1'b0, shift[2:1]};
            4'b0111: begin
                if (enable_flag) pattern <= pattern - 1;
                enable_flag <= enable;
            end
            default: begin end
        endcase

        if (rising_edge) begin
            case (switch_input)
                4'b0001: LED_output <= {pattern[7], pattern[7:1]};
                4'b0010: begin
                    case (rotation)
                        2'b00: LED_output <= pattern;
                        2'b01: LED_output <= {pattern[6:0], pattern[7]};
                        2'b10: LED_output <= {pattern[1:7], pattern[0]};
                        2'b11: LED_output <= {pattern[7], pattern[0:6]};
                        default: LED_output <= pattern;
                    endcase
                end
                4'b0011: LED_output <= pattern;
                4'b0100: begin
                    if (mirror_flag) LED_output <= {pattern[3:0], pattern[7:4]};
                    else LED_output <= {pattern[4:7], pattern[0:3]};
                end
                4'b0101: begin
                    case (rotation)
                        2'b00: LED_output <= pattern;
                        2'b01: LED_output <= {pattern[1:7], pattern[0]};
                        2'b10: LED_output <= {pattern[0], pattern[7:1]};
                        2'b11: LED_output <= {pattern[7], pattern[6:0]};
                        default: LED_output <= pattern;
                    endcase
                end
                4'b0110: LED_output <= {pattern[6:0], 1'b0};
                4'b0111: LED_output <= pattern;
                default: LED_output <= pattern;
            endcase
        end
    end
end

endmodule

module adder_subtractor (
    input [3:0] a,
    input [3:0] b,
    input sub,
    output [3:0] sum,
    output overflow
);

    reg [4:0] temp_sum;
    reg temp_overflow;

    always @(*) begin
        if (sub) begin
            temp_sum = a - b;
            temp_overflow = (temp_sum < -8) ? 1 : 0;
        end
        else begin
            temp_sum = a + b;
            temp_overflow = (temp_sum > 7) ? 1 : 0;
        end
    end

    assign sum = temp_sum[3:0];
    assign overflow = temp_overflow;

endmodule

module velocityControlHdl_Clamp (
  input signed [35:0] preIntegrator,
  input signed [35:0] preSat,
  input saturated,
  output Clamp
);

  wire Compare_To_Zero_out1;
  wire Compare_To_Zero1_out1;
  wire Compare_To_Zero_out1_1;
  wire Logical_Operator_out1;

  // Compare preIntegrator to zero
  assign Compare_To_Zero_out1 = (preIntegrator <= 36'sh000000000 ? 1'b1 : 1'b0);

  // Compare preSat to zero
  assign Compare_To_Zero1_out1 = (preSat <= 36'sh000000000 ? 1'b1 : 1'b0);

  // Logical OR of Compare_To_Zero_out1 and Compare_To_Zero1_out1
  assign Compare_To_Zero_out1_1 = ~ (Compare_To_Zero_out1 ^ Compare_To_Zero1_out1);

  // Logical AND of Compare_To_Zero_out1_1 and saturated
