module SSCG (
  input ref_clk,
  input modulation,
  output ssc_clk
);

parameter f_nom = 10000; // nominal frequency of the output clock signal
parameter f_delta = 100; // frequency deviation due to spread spectrum modulation
parameter f_spread = 1000; // modulation frequency of the spread spectrum modulation
parameter clk_div = 10; // clock divider ratio to reduce the frequency of the reference clock signal

reg [31:0] counter;
reg [31:0] mod_counter;
reg [31:0] delta_counter;
reg [31:0] delta;
reg [31:0] ssc_clk_counter;

wire [31:0] mod_signal;
wire [31:0] delta_signal;

assign mod_signal = (mod_counter < (f_spread / 2)) ? mod_counter : (f_spread - mod_counter);
assign delta_signal = delta * mod_signal;

assign ssc_clk = (ssc_clk_counter < (f_nom / 2)) ? 1'b0 : 1'b1;

always @(posedge ref_clk) begin
  if (counter == clk_div - 1) begin
    counter <= 0;
    mod_counter <= mod_counter + 1;
    delta_counter <= delta_counter + 1;
    if (delta_counter == delta_signal) begin
      delta_counter <= 0;
      delta <= delta + f_delta;
    end
    if (mod_counter == f_spread) begin
      mod_counter <= 0;
    end
    ssc_clk_counter <= ssc_clk_counter + 1;
    if (ssc_clk_counter == f_nom) begin
      ssc_clk_counter <= 0;
    end
  end else begin
    counter <= counter + 1;
  end
end

endmodule

module register_writer(
    clk_in,
    RST,
    ctrl_in,
    data,
    addr,
    data_out,
    addr_out,
    en_out
);

parameter CTRL_WIDTH = 4; // width of control signal
parameter DATA_WIDTH = 16; // width of data signal
parameter REG_ADDR_WIDTH = 8; // width of register address

// input / output
input clk_in, RST;
input [CTRL_WIDTH-1:0] ctrl_in;
input signed [DATA_WIDTH-1:0] data;
input [REG_ADDR_WIDTH-1:0] addr;

output reg signed [DATA_WIDTH-1:0] data_out;
output reg [REG_ADDR_WIDTH-1:0] addr_out;
output reg en_out;

// repasse dos enderecos data e addr
always @(posedge clk_in) begin
    data_out <= data;
    addr_out <= addr;
end

// execucao da gravacao nos registradores
always @(posedge clk_in) begin
    if (!RST) begin
        // rotina de reset
        en_out    <= 0;
	end else begin
        // Case para controle de habilitação de escrita no registrador de acordo com o opcode de entrada.
        case (ctrl_in)
        // ------------ Data Trasnfer -----------------
        LW:       en_out <= 1;
        LW_IMM:   en_out <= 1;
        // ------------ Arithmetic -----------------
        ADD:      en_out <= 1;
        SUB:      en_out <= 1;
        MUL:      en_out <= 1;
        DIV:      en_out <= 1;
        // ------------ Lógic -----------------
        AND:      en_out <= 1;
        OR :      en_out <= 1;
        NOT:      en_out <= 1;
        // ------------ Control Transfer -----------------
        // All default
        default:  en_out <= 0;
        endcase
	 end
end


endmodule

module i2c_state_machine (
  input clk, // the clock signal
  input rst, // the reset signal
  input sda_i, // the bidirectional data line for the I2C bus
  input scl_i, // the clock line for the I2C bus
  output reg sda_o, // the bidirectional data line for the I2C bus
  output reg scl_o, // the clock line for the I2C bus
  output reg ack // the acknowledge signal from the peripheral device
);

  // Define the states of the I2C state machine
  parameter IDLE_STATE = 2'b00;
  parameter ADDRESS_STATE = 2'b01;
  parameter DATA_STATE = 2'b10;

  // Define the internal state variable
  reg [1:0] state;

  // Define the internal data and address variables
  reg [7:0] data;
  reg [6:0] address;

  // Define the internal counter variable
  reg [2:0] counter;

  // Define the internal acknowledge variable
  reg internal_ack;

  // Define the internal start and stop conditions
  reg start_condition;
  reg stop_condition;

  // Define the internal clock and data signals
  reg internal_clk;
  reg internal_sda;

  // Define the internal delay counter
  reg [7:0] delay_counter;

  // Define the initial state and output values
  initial begin
    state <= IDLE_STATE;
    sda_o <= 1'b1;
    scl_o <= 1'b1;
    ack <= 1'b0;
  end

  // Define the state machine logic
  always @(posedge clk) begin
    if (rst) begin
      state <= IDLE_STATE;
      sda_o <= 1'b1;
      scl_o <= 1'b1;
      ack <= 1'b0;
    end else begin
      case (state)
        IDLE_STATE: begin
          if (sda_i == 1'b0 && scl_i == 1'b0) begin
            // Start condition detected
            state <= ADDRESS_STATE;
            address <= 7'b0000000;
            counter <= 3'b000;
            internal_clk <= 1'b0;
            internal_sda <= 1'b0;
            start_condition <= 1'b1;
            delay_counter <= 8'd10;
          end
        end
        ADDRESS_STATE: begin
          if (counter < 7) begin
            // Send address bit by bit
            internal_sda <= address[counter];
            counter <= counter + 1;
            internal_clk <= ~internal_clk;
            delay_counter <= 8'd10;
          end else begin
            // Wait for acknowledge signal
            internal_sda <= 1'b1;
            internal_clk <= 1'b1;
            if (sda_i == 1'b0) begin
              // Acknowledge received
              internal_ack <= 1'b1;
              state <= DATA_STATE;
              counter <= 3'b000;
              internal_clk <= 1'b0;
              internal_sda <= 1'b0;
              delay_counter <= 8'd10;
            end
          end
        end
        DATA_STATE: begin
          if (counter < 8) begin
            // Send or receive data bit by bit
            if (sda_i == 1'b0) begin
              // Data received
              data <= {data[6:0], sda_i};
              internal_ack <= 1'b1;
            end
            internal_sda <= data[counter];
            counter <= counter + 1;
            internal_clk <= ~internal_clk;
            delay_counter <= 8'd10;
          end else begin
            // Wait for acknowledge signal
            internal_sda <= 1'b1;
            internal_clk <= 1'b1;
            if (sda_i == 1'b0) begin
              // Acknowledge received
              internal_ack <= 1'b1;
              if (stop_condition) begin
                // Stop condition detected
                state <= IDLE_STATE;
                internal_clk <= 1'b0;
                internal_sda <= 1'b0;
                start_condition <= 1'b0;
                stop_condition <= 1'b0;
              end else begin
                // Continue with next byte
                counter <= 3'b000;
                internal_clk <= 1'b0;
                internal_sda <= 1'b0;
              end
            end
          end
        end
      endcase
    end
  end

  // Define the output logic
  always @(posedge clk) begin
    if (rst) begin
      sda_o <= 1'b1;
      scl_o <= 1'b1;
      ack <= 1'b0;
    end else begin
      case (state)
        IDLE_STATE: begin
          sda_o <= 1'b1;
          scl_o <= 1'b1;
          ack <= 1'b0;
        end
        ADDRESS_STATE: begin
          sda_o <= internal_sda;
          scl_o <= internal_clk;
          ack <= internal_ack;
        end
        DATA_STATE: begin
          sda_o <= internal_sda;
          scl_o <= internal_clk;
          ack <= internal_ack;
          if (start_condition) begin
            // Send start condition
            sda_o <= 1'b0;
            start_condition <= 1'b0;
          end else if (counter == 3 && !stop_condition) begin
            // Send acknowledge signal
            sda_o <= 1'b0;
            internal_ack <= 0;
          end else if (counter == 0 && stop_condition) begin
            // Send stop condition
            sda_o <= 1'b0;
            stop_condition <= 1'b0;
          end
        end
      endcase
    end
  end

  // Define the delay logic
  always @(posedge clk) begin
    if (delay_counter > 0) begin
      delay_counter <= delay_counter - 1;
    end
  end

endmodule

