module memory_interface(
	input CLK,
	input RST,
	input axi_awvalid,
	output axi_awready,
	input [32-1:0] axi_awaddr,
	input [3-1:0] axi_awprot,
	input axi_wvalid,
	output axi_wready,
	input [32-1:0] axi_wdata,
	input [4-1:0] axi_wstrb,
	output axi_bvalid,
	input axi_bready,
	input axi_arvalid,
	output axi_arready,
	input [32-1:0] axi_araddr,
	input [3-1:0] axi_arprot,
	output axi_rvalid,
	input axi_rready,
	output [32-1:0] axi_rdata,
	output reg CEN,
	output reg WEN,
	output reg [9:0] A,
	output [31:0] D
);

reg [31:0] mem [0:1023];
reg [31:0] read_data;

// AXI-4 write address channel
always @(posedge CLK) begin
	if (RST == 1'b1) begin
		axi_awready <= 1'b0;
		CEN <= 1'b0;
		WEN <= 1'b0;
	end else begin
		if (axi_awvalid == 1'b1) begin
			axi_awready <= 1'b1;
			CEN <= 1'b0;
			WEN <= 1'b0;
			A <= axi_awaddr[9:0];
		end
	end
end

// AXI-4 write data channel
always @(posedge CLK) begin
	if (RST == 1'b1) begin
		axi_wready <= 1'b0;
		WEN <= 1'b0;
	end else begin
		if (axi_wvalid == 1'b1) begin
			axi_wready <= 1'b1;
			WEN <= 1'b1;
			D <= axi_wdata;
		end
	end
end

// AXI-4 write response channel
always @(posedge CLK) begin
	if (RST == 1'b1) begin
		axi_bvalid <= 1'b0;
	end else begin
		if (axi_awvalid == 1'b1 && axi_wvalid == 1'b1 && axi_wready == 1'b1) begin
			axi_bvalid <= 1'b1;
		end else begin
			axi_bvalid <= 1'b0;
		end
	end
end

// AXI-4 read address channel
always @(posedge CLK) begin
	if (RST == 1'b1) begin
		axi_arready <= 1'b0;
		CEN <= 1'b0;
	end else begin
		if (axi_arvalid == 1'b1 && axi_rready == 1'b1) begin
			axi_arready <= 1'b1;
			CEN <= 1'b1;
			A <= axi_araddr[9:0];
		end
	end
end

// AXI-4 read data channel
always @(posedge CLK) begin
	if (RST == 1'b1) begin
		axi_rvalid <= 1'b0;
	end else begin
		if (axi_arvalid == 1'b1 && axi_arready == 1'b1 && CEN == 1'b0) begin
			axi_rvalid <= 1'b1;
			read_data <= mem[A];
			axi_rdata <= read_data;
		end else begin
			axi_rvalid <= 1'b0;
		end
	end
end

// Custom memory interface
always @(posedge CLK) begin
	if (RST == 1'b1) begin
		CEN <= 1'b0;
		WEN <= 1'b0;
		A <= 10'b0;
		D <= 32'b0;
	end else begin
		if (CEN == 1'b1) begin
			read_data <= mem[A];
			axi_rdata <= read_data;
		end else if (WEN == 1'b1) begin
			mem[A] <= D;
		end
	end
end

endmodule

