module top_module( 
    input [1023:0] in,
    input [7:0] sel,
    output [12:0] out );

    wire [3:0] mux_out;
    wire [8:0] parity_out;
    wire [255:0] mux_inputs [7:0];

    // Generate the 256 4-bit inputs for the multiplexer
    genvar i;
    generate
        for (i = 0; i < 256; i = i + 1) begin : gen_mux_inputs
            assign mux_inputs[0][i*4 +: 4] = in[i*8 +: 4];
            assign mux_inputs[1][i*2 +: 8] = mux_inputs[0][i*4 +: 8];
            assign mux_inputs[2][i*1 +: 16] = mux_inputs[1][i*2 +: 16];
            assign mux_inputs[3][i*1 +: 32] = mux_inputs[2][i*1 +: 32];
            assign mux_inputs[4][i*1 +: 64] = mux_inputs[3][i*1 +: 64];
            assign mux_inputs[5][i*1 +: 128] = mux_inputs[4][i*1 +: 128];
            assign mux_inputs[6][i*1 +: 256] = mux_inputs[5][i*1 +: 256];
        end
    endgenerate

    // Instantiate the 256-to-1 multiplexer
    mux_256_to_1 mux (
        .in(mux_inputs[7]),
        .sel(sel),
        .out(mux_out)
    );

    // Instantiate the 9-bit parity generator
    parity_generator parity (
        .in(in),
        .out(parity_out)
    );

    // Instantiate the checksum module
    checksum_module checksum (
        .in(mux_out),
        .sel(sel),
        .out(out)
    );

    // Concatenate the parity and multiplexer outputs to form the final output
    assign out = {parity_out[8], mux_out};
endmodule

module mux_256_to_1 (
    input [255:0] in,
    input [7:0] sel,
    output reg [3:0] out
);

    always @(*) begin
        case (sel[7:6])
            2'b00: out = in[sel[5:0]*4 +: 4];
            2'b01: out = in[sel[5:4]*8 + sel[3:0]*4 +: 4];
            2'b10: out = in[sel[5:3]*16 + sel[2:0]*4 +: 4];
            2'b11: out = in[sel[5]*32 + sel[4]*16 + sel[3:0]*4 +: 4];
        endcase
    end

endmodule

module parity_generator (
    input [7:0] in,
    output reg [8:0] out
);

    always @(*) begin
        out[8] = ~(in[0] ^ in[1] ^ in[2] ^ in[3] ^ in[4] ^ in[5] ^ in[6] ^ in[7]);
        out[7:0] = in;
    end

