module sender (
    input clk,
    input rst,
    input send,
    input ack,
    input [DATA_BITS-1:0] data_in,
    output reg [DATA_BITS-1:0] data,
    output reg stb,
    output reg busy
);

    reg stb_next;
    reg [DATA_BITS-1:0] data_next;
    reg busy_next;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            stb_next <= 0;
            data_next <= 0;
            busy_next <= 0;
        end else begin
            stb_next <= send && !busy_next;
            data_next <= data_in;
            busy_next <= stb_next || ack;
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            stb <= 0;
            data <= 0;
            busy <= 0;
        end else begin
            stb <= stb_next;
            data <= data_next;
            busy <= busy_next;
        end
    end

endmodule

