always @ (in0, in1, SUB) begin
    sum1 <= in0 + (SUB ? ~in1 + 1 : in1);
end

always @ (sum1) begin
    sum2 <= sum1;
end

always @ (sum2) begin
    out <= sum2;
end

endmodule

