module hamming_code (
  input [k-1:0] data_in,
  output [n-1:0] hamming_out
);

parameter k = 4; // number of input data bits
parameter n = 7; // number of output Hamming code bits

integer i, j, r;
reg [n-1:0] encoded_data;
reg [n-1:0] syndrome;
reg [k-1:0] corrected_data;

// Calculate the number of redundant bits
always @(k) begin
  r = 0;
  while (2**r < k + r + 1) begin
    r = r + 1;
  end
end

// Hamming code encoder
always @(data_in) begin
  for (i = 0; i < n; i = i + 1) begin
    if (i + 1 == 2**i) begin
      encoded_data[i] = 0;
      for (j = 0; j < k; j = j + 1) begin
        if (j + 1 == (i + 1) ^ (i + 1 + j)) begin
          encoded_data[i] = encoded_data[i] ^ data_in[j];
        end
      end
    end else begin
      encoded_data[i] = data_in[i - i / 2];
    end
  end
end

// Hamming code decoder
always @(encoded_data) begin
  for (i = 0; i < r; i = i + 1) begin
    syndrome[i] = 0;
    for (j = 0; j < n; j = j + 1) begin
      if (j + 1 == (j + 1) ^ (2**i)) begin
        syndrome[i] = syndrome[i] ^ encoded_data[j];
      end
    end
  end

  for (i = 0; i < k; i = i + 1) begin
    corrected_data[i] = data_in[i];
    if (i + 1 == (i + 1) ^ syndrome) begin
      corrected_data[i] = ~corrected_data[i];
    end
  end
end

// Output the corrected data
assign hamming_out = corrected_data;

endmodule

module priority_encoder_8bit_enable (
