module async_reset_release (
  input clk,
  input rst,
  output reg out
);

  // Define the number of clock cycles before reset is released
  parameter release_cycles = 10;

  // Create a counter to count the number of clock cycles
  reg [3:0] count = 0;

  // Synchronize the reset signal with the clock signal
  always @(posedge clk) begin
    if (rst) begin
      count <= 0;
      out <= 0;
    end else if (count < release_cycles) begin
      count <= count + 1;
      out <= 0;
    end else begin
      out <= 1;
    end
  end

endmodule

