module floating_point_arithmetic_block (
  input [31:0] num1,
  input [31:0] num2,
  input [1:0] ctrl,
  output [31:0] result
);

  // Define constants for IEEE 754 format
  parameter EXPONENT_SIZE = 8;
  parameter MANTISSA_SIZE = 23;
  parameter BIAS = 127;
  parameter EXPONENT_MASK = 8'hFF;
  parameter MANTISSA_MASK = 23'h7FFFFF;
  parameter SIGN_MASK = 31'h80000000;
  parameter EXPONENT_BIAS = BIAS - 1;

  // Define variables for input values
  reg [30:0] mantissa1;
  reg [30:0] mantissa2;
  reg [7:0] exponent1;
  reg [7:0] exponent2;
  reg sign1;
  reg sign2;

  // Define variables for intermediate calculations
  reg [30:0] mantissa_result;
  reg [7:0] exponent_result;
  reg sign_result;
  reg [31:0] decimal1;
  reg [31:0] decimal2;
  reg [31:0] decimal_result;

  // Convert num1 to decimal
  assign decimal1 = {sign1, exponent1, mantissa1};
  always @(*) begin
    sign1 = num1[31];
    exponent1 = num1[30:23] - EXPONENT_BIAS;
    mantissa1 = {1'b1, num1[22:0]};
  end

  // Convert num2 to decimal
  assign decimal2 = {sign2, exponent2, mantissa2};
  always @(*) begin
    sign2 = num2[31];
    exponent2 = num2[30:23] - EXPONENT_BIAS;
    mantissa2 = {1'b1, num2[22:0]};
  end

  // Perform arithmetic operation based on ctrl
  always @(*) begin
    case (ctrl)
      2'b00: // Addition
        begin
          if (exponent1 < exponent2) begin
            mantissa1 = mantissa1 >> (exponent2 - exponent1);
            exponent_result = exponent2;
          end else begin
            mantissa2 = mantissa2 >> (exponent1 - exponent2);
            exponent_result = exponent1;
          end
          if (sign1 == sign2) begin
            mantissa_result = mantissa1 + mantissa2;
            sign_result = sign1;
          end else begin
            mantissa_result = mantissa1 - mantissa2;
            if (mantissa1 < mantissa2) begin
              sign_result = !sign1;
              mantissa_result = -mantissa_result;
            end else begin
              sign_result = sign1;
            end
          end
        end
      2'b01: // Subtraction
        begin
          if (exponent1 < exponent2) begin
            mantissa1 = mantissa1 >> (exponent2 - exponent1);
            exponent_result = exponent2;
          end else begin
            mantissa2 = mantissa2 >> (exponent1 - exponent2);
            exponent_result = exponent1;
          end
          if (sign1 != sign2) begin
            mantissa_result = mantissa1 + mantissa2;
            sign_result = sign1;
          end else begin
            mantissa_result = mantissa1 - mantissa2;
            if (mantissa1 < mantissa2) begin
              sign_result = !sign1;
              mantissa_result = -mantissa_result;
            end else begin
              sign_result = sign1;
            end
          end
        end
      2'b10: // Multiplication
        begin
          exponent_result = exponent1 + exponent2 - BIAS;
          mantissa_result = mantissa1 * mantissa2;
          sign_result = sign1 ^ sign2;
        end
      2'b11: // Division
        begin
          exponent_result = exponent1 - exponent2 + BIAS;
          mantissa_result = mantissa1 / mantissa2;
          sign_result = sign1 ^ sign2;
        end
      default:
        begin
          exponent_result = 8'hFF; // NaN
          mantissa_result = 23'h7FFFFF;
          sign_result = 1'b0;
        end
    endcase
  end

  // Convert decimal_result to IEEE 754 format
  always @(*) begin
    if (decimal_result[31:23] == 8'hFF) begin
      // NaN or infinity
      exponent_result = 8'hFF;
      mantissa_result = 23'h7FFFFF;
    end else if (decimal_result[31:23] == 0) begin
      // Zero or denormalized number
      exponent_result = 0;
      mantissa_result = 23'h000000;
    end else begin
      // Normalized number
      exponent_result = decimal_result[30:23] + BIAS;
      mantissa_result = decimal_result[22:0];
    end
    result = {sign_result, exponent_result, mantissa_result};
  end

endmodule

