module audio_shifter(
  input  wire           clk,    //32MHz
  input  wire           nreset,
  input  wire           mix,
  input  wire [ 15-1:0] rdata,
  input  wire [ 15-1:0] ldata,
  input  wire           exchan,
  output wire           aud_bclk,
  output wire           aud_daclrck,
  output wire           aud_dacdat,
  output wire           aud_xck
);

  // L-R mixer
  wire [ 16-1:0] rdata_mix;
  wire [ 16-1:0] ldata_mix;

  assign rdata_mix = {rdata[14], rdata} + {{2{ldata[14]}}, ldata[14:1]};
  assign ldata_mix = {ldata[14], ldata} + {{2{rdata[14]}}, rdata[14:1]};

  // data mux
  reg [16-1:0] rdata_mux;
  reg [16-1:0] ldata_mux;

  always @ (posedge clk) begin
    rdata_mux <= mix ? rdata_mix : {rdata, rdata[13]};
    ldata_mux <= mix ? ldata_mix : {ldata, ldata[13]};
  end

  // audio output shifter
  reg  [  9-1:0] shiftcnt;
  reg  [ 16-1:0] shift;

  always @(posedge clk, negedge nreset) begin
    if(~nreset)
      shiftcnt <= 9'd0;
    else
      shiftcnt <= shiftcnt - 9'd1;
  end

  always @ (posedge clk) begin
    if(~|shiftcnt[2:0]) begin
      if (~|shiftcnt[6:3])
        shift <= {shift[14:0], rdata_mux[0]} ^ (exchan ? 17'b10000000000000000 : 17'b00000000000000000);
      else
        shift <= {shift[14:0], 1'b0};
    end
  end

  // output
  assign aud_daclrck = shiftcnt[7];
  assign aud_bclk    = ~shiftcnt[2];
  assign aud_xck     = shiftcnt[0];
  assign aud_dacdat  = shift[15];

endmodule

module barrel_shifter (
    input [3:0] A,
    input [1:0] shift_amount,
    input shift_dir,
    output [3:0] Y
);

reg [3:0] stage1_out;
reg [3:0] stage2_out;

always @(*) begin
    stage1_out[0] = A[shift_amount[0]];
    stage1_out[1] = A[shift_amount[1]];
    stage1_out[2] = A[shift_amount[0]+2];
    stage1_out[3] = A[shift_amount[1]+2];
end

always @(*) begin
    if (shift_dir) begin
        stage2_out[0] = stage1_out[1];
        stage2_out[1] = stage1_out[2];
        stage2_out[2] = stage1_out[3];
        stage2_out[3] = 0;
    end else begin
        stage2_out[0] = 0;
        stage2_out[1] = stage1_out[0];
        stage2_out[2] = stage1_out[1];
        stage2_out[3] = stage1_out[2];
    end
end

assign Y = stage2_out;

endmodule

