module SRLC16E (
  output Q, Q15,
  input A0, A1, A2, A3,
  input CE, CLK, D
);
  parameter [15:0] INIT = 16'h0000;
  parameter [ 0:0] IS_CLK_INVERTED = 1'b0;

  // Duplicate bits of the init parameter to match the actual INIT data
  // representation.
  function [31:0] duplicate_bits;
    input [15:0] bits;
    integer i;
    begin
      for (i=0; i<16; i=i+1) begin
        duplicate_bits[2*i+0] = bits[i];
        duplicate_bits[2*i+1] = bits[i];
      end
    end
  endfunction

  localparam [31:0] INIT_VPR = duplicate_bits(INIT);

  // Instantiate SRLC16E_VPR module and connect its ports to the corresponding ports of SRLC16E module.
  SRLC16E_VPR #
  (
  .INIT(INIT_VPR)
  )
  srlc16e_vpr
  (
  .CLK(CLK),
  .CE(CE),
  .A0(A0),
  .A1(A1),
  .A2(A2),
  .A3(A3),
  .D(D),
  .Q(Q),
  .Q15(Q15)
  );

endmodule

// SRLC16E_VPR module implementation
module SRLC16E_VPR (
  input [31:0] INIT,
  input CLK, CE, A0, A1, A2, A3, D,
  output Q, Q15
);
  wire [15:0] q_reg;
  wire [15:0] q_next;
  assign Q = q_reg[0];
  assign Q15 = q_reg[15];

  // Implement the SRLC16E_VPR module using behavioral Verilog
  always @(posedge CLK) begin
    if (CE == 1'b0) begin
      q_next <= q_reg;
    end else begin
      q_next[0] <= D;
      q_next[1] <= q_reg[0];
      q_next[2] <= q_reg[1];
      q_next[3] <= q_reg[2];
      q_next[4] <= q_reg[3];
      q_next[5] <= q_reg[4];
      q_next[6] <= q_reg[5];
      q_next[7] <= q_reg[6];
      q_next[8] <= q_reg[7];
      q_next[9] <= q_reg[8];
      q_next[10] <= q_reg[9];
      q_next[11] <= q_reg[10];
      q_next[12] <= q_reg[11];
      q_next[13] <= q_reg[12];
      q_next[14] <= q_reg[13];
      q_next[15] <= q_reg[14];
    end
  end

  // Initialize the q_reg signal with the INIT parameter
  initial begin
    q_reg <= INIT;
  end

endmodule

module jtag_cores (
    input [7:0] reg_d,
    input [2:0] reg_addr_d,
    output reg_update,
    output [7:0] reg_q,
    output [2:0] reg_addr_q,
    output jtck,
    output jrstn
);

wire tck;
wire tdi;
wire tdo;
wire shift;
wire update;
wire reset;

jtag_tap jtag_tap (
    .tck(tck),
    .tdi(tdi),
    .tdo(tdo),
    .shift(shift),
    .update(update),
    .reset(reset)
);

reg [10:0] jtag_shift;
reg [10:0] jtag_latched;

always @(posedge tck or posedge reset)
begin
    if(reset)
        jtag_shift <= 11'b0;
    else begin
        if(shift)
            jtag_shift <= {tdi, jtag_shift[10:1]};
        else
            jtag_shift <= {reg_d, reg_addr_d};
    end
end

assign tdo = jtag_shift[0];

always @(posedge reg_update or posedge reset)
begin
    if(reset)
        jtag_latched <= 11'b0;
    else
        jtag_latched <= jtag_shift;
end

assign reg_update = update;
assign reg_q = jtag_latched[10:3];
assign reg_addr_q = jtag_latched[2:0];
assign jtck = tck;
assign jrstn = ~reset;

endmodule

module channelizer_512 (
  input [32-1:0] data_in,
  input [1-1:0] last_in,
  input [1-1:0] reset_in,
  input [8-1:0] set_addr_in,
  input [32-1:0] set_data_in,
  input [1-1:0] set_stb_in,
  input [1-1:0] valid_in,
  input [1-1:0] ready_out,
  input clk,
  output [1-1:0] ready_in,
  output [32-1:0] data_out,
  output [1-1:0] last_out,
  output [1-1:0] valid_out
);
  reg [8-1:0] channel_addr;
  reg [32-1:0] channel_data [0:511];
  reg [1-1:0] channel_last [0:511];
  reg [1-1:0] channel_valid [0:511];
  reg [1-1:0] channel_ready [0:511];
  reg [1-1:0] config_set;
  reg [1-1:0] reset;
  reg [1-1:0] last;
  reg [1-1:0] valid;
  reg [1-1:0] ready;
  reg [32-1:0] data;
  reg [8-1:0] counter;
  reg [8-1:0] channel;
  reg [1-1:0] done;
  wire [8-1:0] channel_addr_wire;
  wire [32-1:0] channel_data_wire;
  wire [1-1:0] channel_last_wire;
  wire [1-1:0] channel_valid_wire;
  wire [1-1:0] channel_ready_wire;
  wire [1-1:0] config_set_wire;
  wire [1-1:0] reset_wire;
  wire [1-1:0] last_wire;
  wire [1-1:0] valid_wire;
  wire [1-1:0] ready_wire;
  wire [32-1:0] data_wire;
  wire [8-1:0] counter_wire;
  wire [8-1:0] channel_wire;
  wire [1-1:0] done_wire;

  assign channel_addr_wire = set_addr_in;
  assign channel_data_wire = set_data_in;
  assign channel_last_wire = last_in;
  assign channel_valid_wire = valid_in;
  assign channel_ready_wire = ready_out;
  assign config_set_wire = set_stb_in;
  assign reset_wire = reset_in;
  assign last_wire = last;
  assign valid_wire = valid;
  assign ready_wire = ready;
  assign data_wire = data;
  assign counter_wire = counter;
  assign channel_wire = channel;
  assign done_wire = done;

  always @(posedge clk) begin
    if (reset_wire == 1'b1) begin
      config_set <= 1'b0;
      reset <= 1'b1;
      last <= 1'b0;
      valid <= 1'b0;
      ready <= 1'b1;
      data <= data_in;
      counter <= 8'd0;
      channel <= 8'd0;
      done <= 1'b0;
      for (i = 0; i < 512; i = i + 1) begin
        channel_data[i] <= 32'd0;
        channel_last[i] <= 1'b0;
        channel_valid[i] <= 1'b0;
        channel_ready[i] <= 1'b1;
      end
    end else begin
      if (config_set_wire == 1'b1) begin
        case (channel_addr_wire)
          8'd0: begin
            counter <= channel_data_wire[7:0];
          end
          8'd1: begin
            channel <= channel_data_wire[7:0];
          end
          default: begin
            // do nothing
          end
        endcase
        config_set <= 1'b1;
      end else begin
        config_set <= 1'b0;
      end

      if (done_wire == 1'b0) begin
        if (counter == 8'd511) begin
          last <= last_in;
          valid <= valid_in;
          ready <= ready_out;
          data <= data_in;
          counter <= 8'd0;
          channel <= channel + 8'd1;
        end else begin
          last <= 1'b0;
          valid <= 1'b1;
          ready <= channel_ready[channel];
          data <= channel_data[channel];
          counter <= counter + 8'd1;
        end
        if (counter == 8'd510) begin
          channel_last[channel] <= last_in;
          channel_valid[channel] <= valid_in;
        end
        if (counter == 8'd511) begin
          channel_last[channel] <= 1'b1;
          channel_valid[channel] <= 1'b0;
          channel_ready[channel] <= 1'b0;
          if (channel == 8'd511) begin
            done <= 1'b1;
          end
        end
      end
    end
  end

  assign ready_in = ready;
  assign data_out = data;
  assign last_out = last;
  assign valid_out = valid;
endmodule

module add_sub_pipeline(
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] sum
);

    wire [15:0] a_lo, b_lo, sum_lo;
    wire [15:0] a_hi, b_hi, sum_hi;
    wire carry;

    // Instantiate the 16-bit adder module twice
    adder16bit adder_lo(.a(a_lo), .b(b_lo), .carry_in(sub), .sum(sum_lo), .carry_out(carry));
    adder16bit adder_hi(.a(a_hi), .b(b_hi), .carry_in(carry), .sum(sum_hi), .carry_out());

    // Connect the inputs to the 16-bit adders
    assign a_lo = a[15:0];
    assign b_lo = b[15:0] ^ (sub ? 32'hFFFF : 0);
    assign a_hi = a[31:16];
    assign b_hi = b[31:16] ^ (sub ? 32'hFFFF : 0);

    // Connect the outputs of the 16-bit adders to the output of the module
    assign sum = {sum_hi, sum_lo};

endmodule

module adder16bit(
    input [15:0] a,
    input [15:0] b,
    input carry_in,
    output [15:0] sum,
    output carry_out
);

    assign {carry_out, sum} = a + b + carry_in;

endmodule

module TicTacToeAI (
    input [8:0] X_state,
    input [8:0] O_state,
    output reg [8:0] AIMove
);

    // Create rotated versions of the game board
    wire [8:0] rotation1, rotation2, rotation3, rotation4, empty;
    LookupTable rot1 (X_state, O_state, rotation1);
    LookupTable rot2 ({X_state[6], X_state[3], X_state[0], X_state[7], X_state[4], X_state[1], X_state[8], X_state[5], X_state[2]}, 
                      {O_state[6], O_state[3], O_state[0], O_state[7], O_state[4], O_state[1], O_state[8], O_state[5], O_state[2]}, 
                      {rotation2[6], rotation2[3], rotation2[0], rotation2[7], rotation2[4], rotation2[1], rotation2[8], rotation2[5], rotation2[2]});
    LookupTable rot3 ({X_state[2], X_state[5], X_state[8], X_state[1], X_state[4], X_state[7], X_state[0], X_state[3], X_state[6]}, 
                      {O_state[2], O_state[5], O_state[8], O_state[1], O_state[4], O_state[7], O_state[0], O_state[3], O_state[6]}, 
                      {rotation3[2], rotation3[5], rotation3[8], rotation3[1], rotation3[4], rotation3[7], rotation3[0], rotation3[3], rotation3[6]});
    LookupTable rot4 ({X_state[0], X_state[1], X_state[2], X_state[3], X_state[4], X_state[5], X_state[6], X_state[7], X_state[8]}, 
                      {O_state[0], O_state[1], O_state[2], O_state[3], O_state[4], O_state[5], O_state[6], O_state[7], O_state[8]}, 
                      {rotation4[0], rotation4[1], rotation4[2], rotation4[3], rotation4[4], rotation4[5], rotation4[6], rotation4[7], rotation4[8]});

    // Find all empty cells on the game board
    Empty emptyx (~(X_state | O_state), empty); 

    // Select the best move from the five possible game states
    Select5 pick(rotation1, rotation2, rotation3, rotation4, empty, AIMove);

endmodule

