module UART_transmitter(
    input Clock, Reset, DataInValid,
    input [7:0] DataIn,
    output SOut, DataInReady
);

parameter ClockFreq = 50_000_000;
parameter Baud = 9600;
parameter Width = 8;
parameter Parity = 0;
parameter StopBits = 1;

localparam Divisor = ClockFreq / Baud;
localparam BitCount = Width + Parity + StopBits + 1;
localparam Capture = Divisor / 2;
localparam BCWidth = $clog2(BitCount + 1);

reg [BCWidth-1:0] TxBitCount;
reg [DivWidth-1:0] TxDivCount;
reg [BitCount-1:0] TxData;
reg TxShiftEnable, TxRunning, TxStart, TxParity;
reg [7:0] DataInAugmented;

assign DataInReady = ~TxRunning & ~Reset;

assign TxShiftEnable = (TxDivCount == (Divisor - 1));
assign TxRunning = (TxBitCount < BitCount);
assign TxBit = TxRunning & TxShiftEnable;
assign TxStart = DataInValid & DataInReady;

assign DataInAugmented = Parity ? {{StopBits{1'b1}}, TxParity, DataIn, 1'b0} : {{StopBits{1'b1}}, DataIn, 1'b0};

always @(posedge Clock) begin
    if (Reset) begin
        TxDivCount <= 0;
        TxBitCount <= 0;
        TxData <= {BitCount{1'b1}};
        TxShiftEnable <= 0;
        TxRunning <= 0;
        TxStart <= 0;
        TxParity <= 0;
    end
    else begin
        if (TxStart) begin
            TxDivCount <= 0;
            TxBitCount <= 0;
            TxData <= {1'b0, DataInAugmented, 1'b1};
            TxShiftEnable <= 0;
            TxRunning <= 1;
            TxParity <= Parity ? ^DataIn : 1'b0;
        end
        else if (TxBit) begin
            TxDivCount <= 0;
            TxBitCount <= TxBitCount + 1;
            TxData <= {TxData[BitCount-2:0], 1'b0};
            TxShiftEnable <= 1;
            TxRunning <= (TxBitCount != BitCount-1);
        end
        else begin
            TxDivCount <= TxDivCount + 1;
            TxBitCount <= TxBitCount;
            TxData <= TxData;
            TxShiftEnable <= 0;
            TxRunning <= 1;
        end
    end
end

assign SOut = TxData[BitCount-1];

endmodule

module top_module (
    input               clk         ,
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,
    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [10:0]  data_out    ,
    output      [2:0]   q           // 3-bit output from the shift register
);

    // Instantiate the 3-bit shift register module
    reg [2:0] shift_reg;
    module_shift_register shift_reg_inst (
        .clk(clk),
        .rst_n(rst_n),
        .data_in(data_in),
        .shift_in(valid_a),
        .shift_out(q),
        .shift_out_valid(),
        .shift_out_ready()
    );

    // Instantiate the accumulator module
    reg [7:0] accumulator;
    reg [2:0] count;
    module_accumulator accumulator_inst (
        .clk(clk),
        .rst_n(rst_n),
        .data_in(data_in),
        .valid_in(valid_a),
        .ready_out(),
        .data_out(),
        .valid_out(),
        .ready_in(ready_b),
        .accumulator(accumulator),
        .count(count)
    );

    // Instantiate the final output module
    reg [10:0] final_output;
    module_final_output final_output_inst (
        .shift_reg(q),
        .accumulator(accumulator),
        .final_output(final_output)
    );

    // Two-way handshake mechanism
    always @(posedge clk, negedge rst_n) begin
        if (!rst_n) begin
            valid_b <= 0;
            data_out <= 0;
            ready_a <= 0;
        end else begin
            if (valid_a && ready_b) begin
                valid_b <= 1;
                accumulator <= accumulator + data_in;
                count <= count + 1;
                if (count == 8) begin
                    data_out <= final_output;
                    ready_a <= 1;
                    count <= 0;
                end
            end else begin
                valid_b <= 0;
                ready_a <= 0;
            end
        end
    end

endmodule

module top_module (
    input [3:0] A,
    input [3:0] B,
    output [3:0] Sum
);

wire [3:0] Sum_i;
wire [3:0] C_out;

full_adder fa0(.A_i(A[0]), .B_i(B[0]), .C_in_i(1'b0), .Sum_i(Sum_i[0]), .C_out_i(C_out[0]));
full_adder fa1(.A_i(A[1]), .B_i(B[1]), .C_in_i(C_out[0]), .Sum_i(Sum_i[1]), .C_out_i(C_out[1]));
full_adder fa2(.A_i(A[2]), .B_i(B[2]), .C_in_i(C_out[1]), .Sum_i(Sum_i[2]), .C_out_i(C_out[2]));
full_adder fa3(.A_i(A[3]), .B_i(B[3]), .C_in_i(C_out[2]), .Sum_i(Sum_i[3]), .C_out_i(C_out[3]));

assign Sum = Sum_i;
endmodule

