    always @ (a, b, op) begin
        case (op)
            2'b00: begin // addition
                add_out = a + b;
                sub_out = 0;
                mul_out = 0;
                div_out = 0;
            end
            2'b01: begin // subtraction
                add_out = 0;
                sub_out = a - b;
                mul_out = 0;
                div_out = 0;
            end
            2'b10: begin // multiplication
                add_out = 0;
                sub_out = 0;
                mul_out = a * b;
                div_out = 0;
            end
            2'b11: begin // division
                add_out = 0;
                sub_out = 0;
                mul_out = 0;
                div_out = a / b;
            end
        endcase
    end

endmodule

module adder_4bit_carry (
    // Inputs
    input [3:0] a,
    input [3:0] b,
    input cin,
    // Outputs
    output [3:0] sum,
    output cout
);

    wire [3:0] temp_sum;
    wire c1, c2, c3;

    // First bit
    full_adder fa1(.a(a[0]), .b(b[0]), .cin(cin), .sum(temp_sum[0]), .cout(c1));

    // Second bit
    full_adder fa2(.a(a[1]), .b(b[1]), .cin(c1), .sum(temp_sum[1]), .cout(c2));

    // Third bit
    full_adder fa3(.a(a[2]), .b(b[2]), .cin(c2), .sum(temp_sum[2]), .cout(c3));

    // Fourth bit
    full_adder fa4(.a(a[3]), .b(b[3]), .cin(c3), .sum(temp_sum[3]), .cout(cout));

    assign sum = temp_sum;

endmodule


module full_adder (
    input a,
    input b,
    input cin,
    output sum,
    output cout
);

    wire s1, s2, s3;

    // First XOR gate
    xor x1(.a(a), .b(b), .y(s1));

    // Second XOR gate
    xor x2(.a(s1), .b(cin), .y(s2));

    // Third AND gate
    and a1(.a(s1), .b(cin), .y(s3));

    // Final sum output
    assign sum = s2;

    // Final carry output
    assign cout = s3;

endmodule

