    input rst,
    input [15:0] din,
    input wr_en,
    input rd_en,
    output [15:0] dout,
    output empty,
    output full
);

reg [15:0] mem [0:7];
reg wr_ptr = 0;
reg rd_ptr = 0;
reg empty_reg = 1;
reg full_reg = 0;

assign empty = empty_reg;
assign full = full_reg;

always @(posedge clk) begin
    if (rst) begin
        wr_ptr <= 0;
        rd_ptr <= 0;
        empty_reg <= 1;
        full_reg <= 0;
    end else begin
        if (wr_en && !full_reg) begin
            mem[wr_ptr] <= din;
            wr_ptr <= wr_ptr + 1;
            if (wr_ptr == 8) wr_ptr <= 0;
            if (wr_ptr == rd_ptr) full_reg <= 1;
            empty_reg <= 0;
        end
        if (rd_en && !empty_reg) begin
            dout <= mem[rd_ptr];
            rd_ptr <= rd_ptr + 1;
            if (rd_ptr == 8) rd_ptr <= 0;
            if (rd_ptr == wr_ptr) empty_reg <= 1;
            full_reg <= 0;
        end
    end
end

endmodule

