module compression_decompression (
  input clk,
  input rst,
  input mode,
  input [7:0] data_in,
  input [15:0] len_in,
  input valid_in,
  output [7:0] data_out,
  output [15:0] len_out,
  output valid_out
);

  // io definition
  // clk: a clock signal
  // rst: a synchronous reset signal
  // mode: a signal indicating whether the module is in compression mode or decompression mode
  // data_in: the input data to be compressed or the compressed data to be decompressed
  // len_in: the length of the input data
  // valid_in: a signal indicating that new data is available for compression or decompression
  // data_out: the compressed data or the decompressed data
  // len_out: the length of the compressed data or the decompressed data
  // valid_out: a signal indicating that new data is available at the output

  // No parameters are required for this task.

  // internal signals
  reg [7:0] mem [0:255];
  reg [7:0] data_out_reg;
  reg [15:0] len_out_reg;
  reg valid_out_reg;
  reg [15:0] index;
  reg [7:0] data;
  reg [15:0] len;
  reg valid;
  reg [7:0] compressed_data [0:255];
  reg [15:0] compressed_index [0:255];
  reg [7:0] decompressed_data [0:255];
  reg [15:0] decompressed_index [0:255];
  reg [7:0] current_data;
  reg [15:0] current_index;
  reg [15:0] compressed_len;
  reg [15:0] decompressed_len;
  reg [7:0] current_compressed_data;
  reg [15:0] current_compressed_index;
  reg [7:0] current_decompressed_data;
  reg [15:0] current_decompressed_index;
  reg [2:0] state;

  // state machine
  always @(posedge clk) begin
    if (rst) begin
      state <= 0;
      len_out_reg <= 0;
      valid_out_reg <= 0;
    end else begin
      case (state)
        0: begin // idle state
          if (valid_in) begin
            len <= len_in;
            valid <= valid_in;
            state <= 1;
          end
        end
        1: begin // compression or decompression state
          if (mode) begin // compression mode
            if (index < len) begin
              data <= data_in;
              if (index == 0) begin
                compressed_data[0] <= data;
                compressed_index[0] <= 0;
                current_data <= data;
                current_index <= 0;
                compressed_len <= 1;
              end else begin
                if (data == current_data) begin
                  compressed_index[index] <= current_index;
                end else begin
                  compressed_data[compressed_len] <= data;
                  compressed_index[index] <= compressed_len;
                  current_data <= data;
                  current_index <= compressed_len;
                  compressed_len <= compressed_len + 1;
                end
              end
              index <= index + 1;
            end else begin
              len_out_reg <= compressed_len;
              valid_out_reg <= 1;
              state <= 2;
            end
          end else begin // decompression mode
            if (index < len) begin
              if (index == 0) begin
                current_compressed_data <= data_in;
                current_compressed_index <= 0;
                decompressed_data[0] <= current_compressed_data;
                decompressed_index[0] <= 0;
                current_decompressed_data <= current_compressed_data;
                current_decompressed_index <= 0;
                decompressed_len <= 1;
              end else begin
                if (index % 2 == 0) begin
                  current_compressed_data <= data_in;
                  current_compressed_index <= current_compressed_data;
                  current_decompressed_data <= current_compressed_data;
                  decompressed_data[decompressed_len] <= current_compressed_data;
                  decompressed_index[decompressed_len] <= index;
                  decompressed_len <= decompressed_len + 1;
                end else begin
                  current_compressed_index <= data_in;
                  current_decompressed_index <= data_in;
                  decompressed_data[decompressed_len] <= current_decompressed_data;
                  decompressed_index[decompressed_len] <= current_decompressed_index;
                  decompressed_len <= decompressed_len + 1;
                end
              end
              index <= index + 1;
            end else begin
              len_out_reg <= decompressed_len;
              valid_out_reg <= 1;
              state <= 2;
            end
          end
        end
        2: begin // output state
          data_out_reg <= mode ? compressed_data[current_index] : decompressed_data[current_index];
          valid_out_reg <= 1;
          if (current_index == len_out_reg - 1) begin
            state <= 0;
          end else begin
            current_index <= current_index + 1;
          end
        end
      endcase
    end
  end

  // output assignment
  assign data_out = data_out_reg;
  assign len_out = len_out_reg;
  assign valid_out = valid_out_reg;

endmodule

module COUNT
#(
	parameter N=7
)
(
	A,
	S
);

	function integer log2;
		input [31:0] value;
		reg [31:0] temp;
	begin
		temp = value;
		for (log2=0; temp>0; log2=log2+1)
			temp = temp>>1;
	end
	endfunction

	localparam K  = log2(N);
	localparam K2 = log2(N - 2**(K-1));

	input	[N-1:0] 	A;
	output	[K-1:0] 	S;

	wire 	[K-2:0] 	S1;
	wire 	[K-2:0] 	S2pad;
	wire 	[K2-1:0] 	S2;

	generate
		if(K2==0) begin: g1
			assign S2pad = {(K-1){1'b0}};
		end else if (K-K2-1>0) begin: g2
			assign S2pad = {{(K-K2-1){1'b0}}, S2};
		end else begin: g3
			assign S2pad = S2;
		end
	endgenerate

	generate 
	if(N==1) begin: g4
		assign S=A[0];
	end else if(N==2) begin: g5
		ADD
		#(
			.N(1)
		)
		ADD_3
		(
			.A(A[1]),
			.B({1'b0}),
			.CI(A[0]),
			.S(S[0]),
			.CO(S[1])
		);
	end else if(N==3) begin: g6
		ADD
		#(
			.N(1)
		)
		ADD_3
		(
			.A(A[1]),
			.B(A[2]),
			.CI(A[0]),
			.S(S[K-2:0]),
			.CO(S[K-1])
		);
	end else if (N>3) begin: g7
		COUNT
		#(
			.N(2**(K-1)-1)
		)
		COUNT_1
		(
			.A(A[N-1:N-2**(K-1)+1]),
			.S(S1)
		);
		if(N-2**(K-1)>0) begin: g8
			COUNT
			#(
				.N(N-2**(K-1))
			)
			COUNT_2
			(
				.A(A[N-2**(K-1):1]),
				.S(S2)
			);
		end

		ADD
		#(
			.N(K-1)
		)
		ADD_
		(
			.A(S1),
			.B(S2pad),
			.CI(A[0]),
			.S(S[K-2:0]),
			.CO(S[K-1])
		);
	end
	endgenerate
endmodule

module ADD_3
#(
	parameter N=1
)
(
	A,
	B,
	CI,
	S,
	CO
);

	input	A;
	input	B;
	input	CI;
	output	S;
	output	CO;

	assign {CO, S} = A + B + CI;
