module ADD
#(
	parameter N=1
)
(
	A,
	B,
	CI,
	S,
	CO
);

	input	[N-1:0] A;
	input	[N-1:0] B;
	input	CI;
	output	[N-1:0] S;
	output	CO;

	wire [N:0] temp;

	assign temp = {CI, A} + {1'b0, B};
	assign {CO, S} = temp[N:N-1];
endmodule

