module top_module (
    input [7:0] in0,
    input [7:0] in1,
    input [7:0] in2,
    input [7:0] in3,
    input [7:0] in4,
    input [7:0] in5,
    input [7:0] in6,
    input [7:0] in7,
    output reg [3:0] sum_of_smallest, // Sum of the two smallest BCD values
    output reg [3:0] diff_of_largest // Difference between the two largest BCD values
);

reg [7:0] sorted_inputs [0:7];
wire [3:0] bcd_outputs [0:7];
reg [1:0] control_signal;

// Sorting module
sort_module sort (
    .inputs({in0, in1, in2, in3, in4, in5, in6, in7}),
    .outputs({sorted_inputs[0], sorted_inputs[1], sorted_inputs[2], sorted_inputs[3], sorted_inputs[4], sorted_inputs[5], sorted_inputs[6], sorted_inputs[7]})
);

// Binary-to-BCD converter
binary_to_bcd_converter bcd_converter (
    .inputs({sorted_inputs[0], sorted_inputs[1], sorted_inputs[2], sorted_inputs[3], sorted_inputs[4], sorted_inputs[5], sorted_inputs[6], sorted_inputs[7]}),
    .outputs({bcd_outputs[0], bcd_outputs[1], bcd_outputs[2], bcd_outputs[3], bcd_outputs[4], bcd_outputs[5], bcd_outputs[6], bcd_outputs[7]})
);

// Functional module
always @(*) begin
    if (control_signal == 2'b00) begin // Sum of two smallest values
        sum_of_smallest <= bcd_outputs[0] + bcd_outputs[1];
        diff_of_largest <= bcd_outputs[7] - bcd_outputs[6];
    end else if (control_signal == 2'b01) begin // Difference between two largest values
        sum_of_smallest <= bcd_outputs[0] + bcd_outputs[1];
        diff_of_largest <= bcd_outputs[7] - bcd_outputs[6];
    end else if (control_signal == 2'b10) begin // Sum of two middle values
        sum_of_smallest <= bcd_outputs[2] + bcd_outputs[3];
        diff_of_largest <= bcd_outputs[6] - bcd_outputs[5];
    end else begin // Difference between two middle values
        sum_of_smallest <= bcd_outputs[2] + bcd_outputs[3];
        diff_of_largest <= bcd_outputs[6] - bcd_outputs[5];
    end
end

// Control signal generation
always @(*) begin
    if (sorted_inputs[0] == sorted_inputs[1]) begin
        control_signal <= 2'b00; // Sum of two smallest values
    end else if (sorted_inputs[6] == sorted_inputs[7]) begin
        control_signal <= 2'b01; // Difference between two largest values
    end else if (sorted_inputs[2] == sorted_inputs[3]) begin
        control_signal <= 2'b10; // Sum of two middle values
    end else begin
        control_signal <= 2'b11; // Difference between two middle values
    end
end

endmodule

module fifo_buffer
  (wr_clk, wr_en, wr_data, rd_clk, rd_en, rd_data, empty, full);

  parameter WIDTH = 32;
  parameter DEPTH = 2048; // 8KB / 32 bits

  input wr_clk;
  input wr_en;
  input [WIDTH-1:0] wr_data;
  input rd_clk;
  input rd_en;
  output [WIDTH-1:0] rd_data;
  output empty;
  output full;

  reg [WIDTH-1:0] buffer [0:DEPTH-1];
  reg [WIDTH-1:0] rd_data_reg;
  reg [WIDTH-1:0] wr_data_reg;
  reg empty_reg;
  reg full_reg;
  integer wr_ptr_reg = 0;
  integer rd_ptr_reg = 0;

  always @(posedge wr_clk) begin
    if (wr_en && !full_reg) begin
      buffer[wr_ptr_reg] <= wr_data;
      wr_ptr_reg <= (wr_ptr_reg == DEPTH-1) ? 0 : wr_ptr_reg + 1;
      empty_reg <= 0;
      full_reg <= (wr_ptr_reg == rd_ptr_reg) ? 1 : 0;
    end
  end

  always @(posedge rd_clk) begin
    if (rd_en && !empty_reg) begin
      rd_data_reg <= buffer[rd_ptr_reg];
      rd_ptr_reg <= (rd_ptr_reg == DEPTH-1) ? 0 : rd_ptr_reg + 1;
      full_reg <= 0;
      empty_reg <= (rd_ptr_reg == wr_ptr_reg) ? 1 : 0;
    end
  end

  assign rd_data = rd_data_reg;
  assign empty = empty_reg;
  assign full = full_reg;

endmodule

module addsub_4bit (
