    end
end

assign S_wire = sum_reg[3:0];
assign Cout_wire = sum_reg[4];

endmodule

module top_module (
    input [7:0] in,
    output reg [4:0] out
);

    // 8-to-3 encoder
    wire [2:0] enc_out;
    encoder_8to3 enc_8to3(
        .in(in),
        .out(enc_out)
    );

    // 4-to-2 priority encoder
    wire [1:0] pri_enc_out;
    priority_encoder_4to2 pri_enc_4to2(
        .in(in),
        .out(pri_enc_out)
    );

    // Priority selector
    reg [1:0] priority;
    always @* begin
        case(pri_enc_out)
            2'b00: priority = enc_out[0] ? 2'b10 : 2'b01;
            2'b01: priority = 2'b10;
            2'b10: priority = 2'b01;
            2'b11: priority = enc_out[2] ? 2'b10 : 2'b01;
        endcase
    end

    // Output
    always @* begin
        case(priority)
            2'b01: out = {enc_out, 2'b00};
            2'b10: out = {enc_out, 2'b01};
        endcase
    end

endmodule

// 8-to-3 encoder
module encoder_8to3 (
    input [7:0] in,
    output reg [2:0] out
);
    always @* begin
        case(in)
            8'b00000001: out = 3'b001;
            8'b00000010: out = 3'b010;
            8'b00000100: out = 3'b011;
            8'b00001000: out = 3'b100;
            8'b00010000: out = 3'b101;
            8'b00100000: out = 3'b110;
            8'b01000000: out = 3'b111;
            8'b10000000: out = 3'b000;
            default: out = 3'b000;
        endcase
    end
endmodule

// 4-to-2 priority encoder
module priority_encoder_4to2 (
    input [7:0] in,
    output reg [1:0] out
);
    always @* begin
        case(in)
            8'b00000001, 8'b00000010, 8'b00000100, 8'b00001000: out = 2'b00;
            8'b00010000, 8'b00100000: out = 2'b01;
            8'b01000000: out = 2'b10;
            8'b10000000: out = 2'b11;
            default: out = 2'b00;
        endcase
    end
endmodule

