    input [7:0] sel,
    output reg [3:0] out
);

reg [7:0] sel_decoded [0:255];
wire [3:0] mux_output [0:127];

// Decoder
generate
    for (i = 0; i < 256; i = i + 1) begin : decoder
        assign sel_decoded[i] = (sel == i) ? 1'b1 : 1'b0;
    end
endgenerate

// 2-to-1 Muxes
generate
    for (i = 0; i < 128; i = i + 1) begin : mux
        assign mux_output[i] = sel_decoded[i*2] ? in_array[i*2] : in_array[i*2+1];
    end
endgenerate

// Final 2-to-1 Mux
generate
    for (i = 0; i < 64; i = i + 1) begin : final_mux
        assign out = mux_output[i*2] ? mux_output[i*2] : mux_output[i*2+1];
    end
endgenerate

endmodule

