module freq_synth (
  input ref_clk,
  input [n-1:0] ctrl,
  output synth_clk
);

parameter f_ref = 10e6; // frequency of reference clock signal
parameter f_out = 100e6; // desired frequency of synthesized clock signal

// DDS implementation
reg [31:0] phase_accumulator;
reg [31:0] phase_step;
wire [15:0] sine_wave_output;

assign phase_step = (f_out / f_ref) * (2 ** 32);
