reg carry_in, carry_out;
wire [3:0] sum;

always @(*) begin
    A_reg <= A;
    B_reg <= B;
end

// Pipeline stage 1
always @(posedge clk) begin
    if (op == 1'b1) begin // subtraction
        Y_reg <= A_reg - B_reg;
    end else begin // addition
        Y_reg <= A_reg + B_reg;
    end
end

// Pipeline stage 2
