module uart_rx (
  input clk,
  input rstn,
  input rx,
  output reg [data_bits-1:0] data,
  output reg valid,
  output reg stop
);

parameter baud = 9600;
parameter data_bits = 8;
parameter stop_bits = 1;
parameter parity = "none";

reg [2:0] state;
reg [data_bits-1:0] shift_reg;
reg [2:0] bit_count;
reg start_bit_detected;
reg stop_bit_detected;
reg parity_bit_detected;
reg [1:0] stop_bit_count;

localparam IDLE = 3'b000;
localparam START_BIT = 3'b001;
localparam DATA_BITS = 3'b010;
localparam PARITY_BIT = 3'b011;
localparam STOP_BITS = 3'b100;

always @(posedge clk or negedge rstn) begin
  if (~rstn) begin
    state <= IDLE;
    shift_reg <= 0;
    bit_count <= 0;
    start_bit_detected <= 0;
    stop_bit_detected <= 0;
    parity_bit_detected <= 0;
    stop_bit_count <= 0;
    valid <= 0;
    stop <= 0;
    data <= 0;
  end else begin
    case (state)
      IDLE: begin
        if (rx == 0) begin
          start_bit_detected <= 1;
          state <= START_BIT;
        end
      end
      START_BIT: begin
        if (bit_count == 0) begin
          shift_reg <= 0;
        end
        shift_reg <= {shift_reg[data_bits-2:0], rx};
        bit_count <= bit_count + 1;
        if (bit_count == data_bits) begin
          start_bit_detected <= 0;
          bit_count <= 0;
          state <= PARITY_BIT;
        end
      end
      DATA_BITS: begin
        shift_reg <= {shift_reg[data_bits-2:0], rx};
        bit_count <= bit_count + 1;
        if (bit_count == data_bits) begin
          stop_bit_count <= 0;
          state <= STOP_BITS;
        end
      end
      PARITY_BIT: begin
        if (parity == "none") begin
          parity_bit_detected <= 1;
          state <= STOP_BITS;
        end else begin
          // parity bit detection logic here
        end
      end
      STOP_BITS: begin
        if (stop_bit_count == 0) begin
          if (rx == 1) begin
            stop_bit_detected <= 1;
            stop_bit_count <= stop_bit_count + 1;
          end
        end else begin
          if (rx == 0) begin
            stop_bit_detected <= 0;
            valid <= 1;
            stop <= 1;
            data <= shift_reg;
            state <= IDLE;
          end else begin
            stop_bit_count <= stop_bit_count + 1;
            if (stop_bit_count == stop_bits) begin
              stop_bit_detected <= 0;
              valid <= 1;
              stop <= 1;
              data <= shift_reg;
              state <= IDLE;
            end
          end
        end
      end
    endcase
  end
end

endmodule

module ripple_carry_adder (
    input wire [3:0] a,  // 4-bit binary number a
    input wire [3:0] b,  // 4-bit binary number b
    input wire cin,      // Carry-in input
    output wire [3:0] s, // 4-bit binary sum output
    output wire cout     // Carry-out output
);

    wire [3:0] sum;
    wire c1, c2, c3;

    assign c1 = a[0] & b[0];
    assign c2 = a[0] ^ b[0];
    assign c3 = cin & c2;
    assign sum[0] = a[0] ^ b[0] ^ cin;

    assign c1 = c1 | c3;

    assign c2 = a[1] & b[1];
    assign c3 = c1 & c2;
    assign sum[1] = a[1] ^ b[1] ^ c1;

    assign c1 = c1 | c3;

    assign c2 = a[2] & b[2];
    assign c3 = c1 & c2;
    assign sum[2] = a[2] ^ b[2] ^ c1;

    assign c1 = c1 | c3;

    assign c2 = a[3] & b[3];
    assign c3 = c1 & c2;
    assign sum[3] = a[3] ^ b[3] ^ c1;

    assign cout = c3;

    assign s = sum;

endmodule


