module top_module ( 
    input wire clk,
    input wire reset,      // Synchronous active-high reset
    input wire [3:0] in1,  // 4-bit binary number 1
    input wire [3:0] in2,  // 4-bit binary number 2
    input wire select,     // Select input to choose between adder and functional module
    output wire [4:0] sum  // 5-bit binary sum output from the active module
);

    wire [3:0] adder_sum;
    wire adder_cout;
    wire [4:0] functional_sum;

    ripple_carry_adder adder(.a(in1), .b(in2), .cin(1'b0), .s(adder_sum), .cout(adder_cout));
    functional_module functional(.in_sum({adder_cout, adder_sum}), .out_sum(functional_sum));

    always @(posedge clk) begin
        if (reset) begin
            sum <= 5'b0;
        end else begin
            if (select) begin
                sum <= functional_sum;
            end else begin
                sum <= {adder_cout, adder_sum};
            end
        end
    end

endmodule

module uart_interface (
    input wire clk,
    input wire rst,
    input wire btnu,
    input wire btnl,
    input wire btnd,
    input wire btnr,
    input wire btnc,
