    output wire [7:0] led,
    input wire phy_rx_clk,
    input wire [7:0] phy_rxd,
    input wire phy_rx_dv,
    input wire phy_rx_er,
    output wire phy_gtx_clk,
    output wire [7:0] phy_txd,
    output wire phy_tx_en,
    output wire phy_tx_er,
    output wire phy_reset_n,
    input wire uart_rxd,
    output wire uart_txd
);

reg [7:0] uart_tx_data;
reg uart_tx_valid;
wire uart_tx_ready;

wire [7:0] uart_rx_data;
wire uart_rx_valid;
reg uart_rx_ready;

assign led = sw;
assign phy_reset_n = ~rst;

assign phy_gtx_clk = 1'b0;
assign phy_txd = 8'd0;
assign phy_tx_en = 1'b0;
assign phy_tx_er = 1'b0;

uart #(
    .CLK_FREQ(125000000),
    .BAUD_RATE(115200),
    .DATA_BITS(8),
    .STOP_BITS(1),
    .PARITY("NONE")
) uart_inst (
    .clk(clk),
    .rst(rst),
    // AXI input
    .s_axis_tdata(uart_tx_data),
    .s_axis_tvalid(uart_tx_valid),
    .s_axis_tready(uart_tx_ready),
    // AXI output
    .m_axis_tdata(uart_rx_data),
    .m_axis_tvalid(uart_rx_valid),
    .m_axis_tready(uart_rx_ready),
    // uart
    .rxd(uart_rxd),
    .txd(uart_txd),
    // status
    .tx_busy(),
    .rx_busy(),
    .rx_overrun_error(),
    .rx_frame_error(),
    // configuration
    .prescale(125000000/(115200*8))
);

always @(posedge clk or posedge rst) begin
    if (rst) begin
        uart_tx_data <= 0;
        uart_tx_valid <= 0;
        uart_rx_ready <= 0;
    end else begin
        if (uart_tx_valid) begin
            // attempting to transmit a byte
            // so can't receive one at the moment
            uart_rx_ready <= 0;
            // if it has been received, then clear the valid flag
            if (uart_tx_ready) begin
                uart_tx_valid <= 0;
            end
        end else begin
            // ready to receive byte
            uart_rx_ready <= 1;
            if (uart_rx_valid) begin
                // got one, so make sure it gets the correct ready signal
                // (either clear it if it was set or set it if we just got a
                // byte out of waiting for the transmitter to send one)
                uart_rx_ready <= ~uart_rx_ready;
                // send byte back out
                uart_tx_data <= uart_rx_data;
                uart_tx_valid <= 1;
            end
        end
    end
end

assign phy_txd = uart_rx_data;
assign phy_tx_en = uart_rx_valid;
assign uart_tx_ready = phy_rx_dv;
assign uart_rx_valid = phy_tx_en;
assign uart_rx_data = phy_rxd;
assign phy_tx_er = 0;
assign uart_tx_axis_tdata = uart_tx_data;
assign uart_tx_axis_tvalid = uart_tx_valid;
assign uart_rx_axis_tready = uart_rx_ready;

endmodule

module sequence_detector (
  input clk,
  input reset,
  input [7:0] data,
  output reg match
);

  reg [3:0] state;
  reg [3:0] next_state;

  always @ (posedge clk or posedge reset) begin
    if (reset) begin
      state <= 4'b0000;
      match <= 1'b0;
    end else begin
      state <= next_state;
      match <= (state == 4'b0100);
    end
  end

  always @ (state or data) begin
    case (state)
      4'b0000: next_state = (data == 4'b1010) ? 4'b0100 : 4'b0001;
      4'b0001: next_state = (data[6:3] == 4'b1010) ? 4'b0100 : 4'b0010;
      4'b0010: next_state = (data[5:2] == 4'b1010) ? 4'b0100 : 4'b0011;
      4'b0011: next_state = (data[4:1] == 4'b1010) ? 4'b0100 : 4'b0001;
      4'b0100: next_state = 4'b0001;
      default: next_state = 4'b0000;
    endcase
  end

endmodule

