module fifo (
    input clk,
    input rst,
    input wr_en,
    input rd_en,
    input [31:0] data_in,
    output reg [31:0] data_out
);

parameter FIFO_DEPTH = 16;

reg [31:0] fifo_mem [0:FIFO_DEPTH-1];
reg [3:0] wr_ptr;
reg [3:0] rd_ptr;
reg [3:0] fifo_count;

// Write operation
always @(posedge clk) begin
    if (rst) begin
        wr_ptr <= 0;
        rd_ptr <= 0;
        fifo_count <= 0;
        fifo_mem <= 0;
    end
    else if (wr_en && (fifo_count < FIFO_DEPTH)) begin
        fifo_mem[wr_ptr] <= data_in;
        wr_ptr <= wr_ptr + 1;
        fifo_count <= fifo_count + 1;
    end
end

// Read operation
always @(posedge clk) begin
    if (rst) begin
        wr_ptr <= 0;
        rd_ptr <= 0;
        fifo_count <= 0;
        fifo_mem <= 0;
    end
    else if (rd_en && (fifo_count > 0)) begin
        data_out <= fifo_mem[rd_ptr];
        rd_ptr <= rd_ptr + 1;
        fifo_count <= fifo_count - 1;
    end
end

endmodule

module combinational_circuit( 
    input [3:0] in,
    output out_and,
    output out_or,
    output out_xor
);

    wire and1, and2, and3, and4, and5, and6;
    wire or1, or2, or3, or4;
    wire xor1, xor2, xor3;

    assign and1 = in[0] & in[1];
    assign and2 = in[0] & in[2];
    assign and3 = in[0] & in[3];
    assign and4 = in[1] & in[2];
    assign and5 = in[1] & in[3];
    assign and6 = in[2] & in[3];

    assign or1 = in[0] | in[1];
    assign or2 = in[0] | in[2];
    assign or3 = in[0] | in[3];
    assign or4 = in[1] | in[2] | in[3];

    assign xor1 = in[0] ^ in[1];
    assign xor2 = in[0] ^ in[2];
    assign xor3 = in[0] ^ in[3];

    assign out_and = and1 & and2 & and3 & and4 & and5 & and6;
    assign out_or = or1 | or2 | or3 | or4;
    assign out_xor = xor1 ^ xor2 ^ xor3;

endmodule

module ControlUnit(
    input [5:0] op,
    input clk,
    input rst,
    input zero,
    input sign,

    output wire [2:0] state,

    output ExtSel,

    // PC
    output [1:0] PCSrc,
    output PCWre,

    // ALU
    output ALUSrcA,
    output ALUSrcB,
    output reg [2:0] ALUOp,

    // Instruction Memory
    output InsMemRW,
    output IRWre,

    // Data Memory
    output mRD,
    output mWR,
    output DBDataSrc,

    // Register File
    output RegWre,
    output WrRegDSrc,
    output [1:0] RegDst
    );

    // State machine
    reg [2:0] state;
    always @(posedge clk, posedge rst) begin
        if (rst) begin
            state <= 3'b000;
        end else begin
            case (state)
                3'b000: begin
                    state <= 3'b001;
                end
                3'b001: begin
                    state <= 3'b010;
                end
                3'b010: begin
                    state <= 3'b011;
                end
                3'b011: begin
                    if (op == 6'b111111) begin
                        state <= 3'b100;
                    end else begin
                        state <= 3'b000;
                    end
                end
                3'b100: begin
                    state <= 3'b100;
                end
            endcase
        end
    end

    // Control signals
    assign PCWre = (op != 6'b111111 && state == 3'b011 ? 1 : 0);
    assign ALUSrcA = (op == 6'b011000 ? 1 : 0);
    assign ALUSrcB = (op == 6'b000010 || op == 6'b010010 || op == 6'b100111
        || op == 6'b110000 || op == 6'b110001 ? 1 : 0);
    assign DBDataSrc = (op == 6'b110001 ? 1 : 0);
    assign RegWre = (op == 6'b110100 || op == 6'b110110 || op == 6'b111000
        || op == 6'b110000 || op == 6'b111001 || op == 6'b111111 || (state != 3'b011 && op != 6'b111010) ? 0 : 1);
    assign WrRegDSrc = (op != 6'b111010 ? 1 : 0);
    assign InsMemRW = 1;
    assign mRD = (op == 6'b110001 && state == 3'b100 ? 1 : 0);
    assign mWR = (op == 6'b110000 && state == 3'b100 ? 1 : 0);
    assign IRWre = (state == 3'b000 ? 1 : 0);
    assign ExtSel = (op != 6'b010010 && op != 6'b100111 ? 1 : 0);
    assign PCSrc = (op == 6'b111000 || op == 6'b111010 ? 2'b11 :
        (op == 6'b111001 ? 2'b10 :
        ((op == 6'b110100 && zero == 1) || (op == 6'b110110 && (sign == 1 && zero == 0)) ? 2'b01 :
        2'b00)));
    assign RegDst = (op == 6'b111010 ? 2'b00 :
        (op == 6'b000010 || op == 6'b010010 || op == 6'b100111 || op == 6'b110001 ? 2'b01 : 2'b10));

    always@(op or zero or sign) begin
        case (op)
            // add
            6'b000000: ALUOp = 3'b000;
            // sub
            6'b000001: ALUOp = 3'b001;
            // addi
            6'b000010: ALUOp = 3'b000;
            // or
            6'b010000: ALUOp = 3'b101;
            // and
            6'b010001: ALUOp = 3'b110;
            // ori
            6'b010010: ALUOp = 3'b101;
            // sll
            6'b011000: ALUOp = 3'b100;
            // slt
            6'b100110: ALUOp = 3'b011;
            // sltiu
            6'b100111: ALUOp = 3'b010;
            // sw
            6'b110000: ALUOp = 3'b000;
            // lw
            6'b110001: ALUOp = 3'b000;
            // beq
            6'b110100: ALUOp = 3'b001;
            // bltz
            6'b110110: ALUOp = 3'b001;
            // j
            6'b111000: ALUOp = 3'bzzz;
            // jr
            6'b111001: ALUOp = 3'bzzz;
            // jal
            6'b111010: ALUOp = 3'bzzz;
            // halt
            6'b111111: ALUOp = 3'bzzz;
        endcase
    end
endmodule

module multiply(
  input [15:0] a,
  input [15:0] b,
  output reg [31:0] result
);

  reg [31:0] res;
  reg [3:0] i;

  always @(*) begin
    res = 0;
    for (i = 0; i < 16; i = i + 1) begin
      if (b[0] == 1) begin
        res = res + (a << i);
      end
      b = b >> 1;
    end
    result = res;
  end

endmodule

module FSM (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 2; // number of input signals
parameter m = 1; // number of output signals
parameter s = 4; // number of states

// Define the states
parameter S0 = 2'b00;
parameter S1 = 2'b01;
parameter S2 = 2'b10;
parameter S3 = 2'b11;

// Define the inputs
parameter I0 = 2'b00;
parameter I1 = 2'b01;
parameter I2 = 2'b10;
parameter I3 = 2'b11;

// Define the outputs
parameter O0 = 1'b0;
parameter O1 = 1'b1;

// Define the state table
reg [1:0] state;
always @ (state or in) begin
  case (state)
    S0: begin
      if (in == I0) begin
        state <= S1;
        out <= O0;
      end else if (in == I1) begin
        state <= S2;
        out <= O1;
      end else begin
        state <= S0;
        out <= O0;
      end
    end
    S1: begin
      if (in == I0) begin
        state <= S2;
        out <= O0;
      end else if (in == I1) begin
        state <= S3;
        out <= O1;
      end else begin
        state <= S1;
        out <= O0;
      end
    end
    S2: begin
      if (in == I0) begin
        state <= S3;
        out <= O0;
      end else if (in == I1) begin
        state <= S0;
        out <= O1;
      end else begin
        state <= S2;
        out <= O0;
      end
    end
    S3: begin
      if (in == I0) begin
        state <= S0;
        out <= O0;
      end else if (in == I1) begin
        state <= S1;
        out <= O1;
      end else begin
        state <= S3;
        out <= O0;
      end
    end
  endcase
end

// Initialize the state
initial begin
  state <= S0;
end

endmodule

module addsub (
    // ----- Inputs -------
    DataA,
    DataB,
    Cin,
    Add_Sub,
    // ----- Outputs -------
    Result,
    Cout
    );

/////////////////////////////////////////////////////
// Inputs
/////////////////////////////////////////////////////

input [31:0] DataA;
input [31:0] DataB;
input Cin;
input Add_Sub;

/////////////////////////////////////////////////////
// Outputs
/////////////////////////////////////////////////////

output [31:0] Result;
wire   [31:0] Result;
output Cout;
wire   Cout;

/////////////////////////////////////////////////////
// Instantiations
/////////////////////////////////////////////////////

wire [32:0] tmp_addResult = DataA + DataB + Cin;
wire [32:0] tmp_subResult = DataA - DataB - !Cin;

assign  Result = (Add_Sub == 1) ? tmp_addResult[31:0] : tmp_subResult[31:0];
assign  Cout = (Add_Sub == 1) ? tmp_addResult[32] : !tmp_subResult[32];

endmodule

module top_module (
    input [15:0] a,    // First 16-bit input value
    input [15:0] b,    // Second 16-bit input value
    output [3:0] pos,   // 4-bit priority encoder output
    output reg [31:0] result    // Final output
);

wire [31:0] adder_out;
wire [31:0] priority_encoder_out;

// Carry Look-ahead Adder module
cla_adder adder (
    .a(a),
    .b(b),
    .sum(adder_out)
);

// Priority Encoder module
priority_encoder encoder (
    .in(adder_out),
    .out(priority_encoder_out)
);

// Additional functional module
assign pos = priority_encoder_out[3:0];

always @(*) begin
    if (priority_encoder_out[31]) begin
        result = a - b;
    end else begin
        result = a + b;
    end
end

endmodule

// Carry Look-ahead Adder module
module cla_adder (
    input [15:0] a,
    input [15:0] b,
    output [31:0] sum
);

assign sum = {16'b0, a} + {16'b0, b};

endmodule

// Priority Encoder module
module priority_encoder (
    input [31:0] in,
    output [31:0] out
);

wire [31:0] mux_out;
wire [31:0] cmp_out;

// Multiplexer
assign mux_out = (in[31:16] != 0) ? in[31:16] : in[15:0];

// Comparator
assign cmp_out = (in[31:16] != 0) ? 16'b1 : 16'b0;

assign out = {cmp_out, mux_out};

endmodule

module top_module (
    input [1:0] A,
    input [1:0] B,
    input [1:0] SEL,
    output reg [1:0] out
);

reg [1:0] alu_out;
reg [1:0] mux_out;

alu_2bit alu_inst (
    .A(A),
    .B(B),
    .C(SEL[1:0]),
    .out(alu_out)
);

mux4to1 mux_inst (
    .A(A),
    .B(B),
    .C(out),
    .D(alu_out),
    .SEL(SEL),
    .Y(mux_out)
);

always @* begin
    out[0] = alu_out[0] | mux_out[0];
    out[1] = alu_out[1] | mux_out[1];
end

endmodule

module alu_2bit (
    input [1:0] A,
    input [1:0] B,
    input [1:0] C,
    output reg [1:0] out
);

always @* begin
    case (C)
        2'b00: out = A & B;
        2'b01: out = A | B;
        2'b10: out = A + B;
        2'b11: out = A - B;
    endcase
end

endmodule

module mux4to1 (
    input [1:0] A,
    input [1:0] B,
    input [1:0] C,
    input [1:0] D,
    input [1:0] SEL,
    output reg [1:0] Y
);

always @* begin
    case (SEL)
        2'b00: Y = A;
        2'b01: Y = B;
        2'b10: Y = C;
        2'b11: Y = D;
    endcase
end

endmodule

module synchronous_counter(clock, reset, enable, load, data_in, data_out);

   parameter DataSize = 4;

   input wire clock;
   input wire reset;
   input wire enable;
   input wire load;
   input wire [DataSize-1:0] data_in;

   output reg [DataSize-1:0] data_out;

   always @ (posedge clock or negedge reset) begin
      if (reset == 0) begin
         data_out <= 0;
      end
      else if (enable == 1) begin
         if (load == 1) begin
            data_out <= data_in;
         end
         else begin
            data_out <= data_out + 1;
         end
      end
   end // always @ (posedge clock or negedge reset)

endmodule

module up_counter(CK, EN, RST, Q);
input CK, EN, RST;
output reg [3:0] Q;

always @(posedge CK or negedge RST)
begin
    if(!RST) //asynchronous reset
        Q <= 4'b0;
    else if(EN) //check enable signal
        Q <= Q + 1;
end

endmodule

