  output reg rw_status,
  output reg data_valid
);

  reg [31:0] read_data;
  reg [31:0] write_data;
  reg [1:0] burst_type;
  reg [1:0] burst_len;
  reg [3:0] cache_type;
  reg [3:0] qos;
  reg [2:0] prot;
  reg [3:0] region;
  reg [2:0] size;
  reg [1:0] resp;
  reg [3:0] strb;
  reg [3:0] id;

  wire arready;
  wire awready;
  wire rvalid;
  wire bvalid;

  mig_wrap_wrapper mig_wrap_i (
    .ACLK(clk),
    .ARESETN(~reset),
    .DDR3_addr(addr),
    .DDR3_ba(3'b000),
    .DDR3_cas_n(1'b1),
    .DDR3_ck_n(1'b0),
    .DDR3_ck_p(1'b0),
    .DDR3_cke(1'b0),
    .DDR3_cs_n(1'b1),
