    .DDR3_dq(read_data),
    .DDR3_dqs_n(8'b11111111),
    .DDR3_dqs_p(8'b11111111),
    .DDR3_odt(1'b0),
    .DDR3_ras_n(1'b1),
    .DDR3_reset_n(1'b1),
    .DDR3_we_n(1'b1),
    .S00_ARESETN(~reset),
    .S00_AXI_araddr(addr),
    .S00_AXI_arburst(burst_type),
    .S00_AXI_arcache(cache_type),
    .S00_AXI_arid(id),
    .S00_AXI_arlen(burst_len),
    .S00_AXI_arlock(1'b0),
    .S00_AXI_arprot(prot),
    .S00_AXI_arqos(qos),
    .S00_AXI_arready(arready),
    .S00_AXI_arregion(region),
    .S00_AXI_arsize(size),
    .S00_AXI_arvalid(enable),
    .S00_AXI_awaddr(addr),
    .S00_AXI_awburst(burst_type),
    .S00_AXI_awcache(cache_type),
    .S00_AXI_awid(id),
    .S00_AXI_awlen(burst_len),
    .S00_AXI_awlock(1'b0),
    .S00_AXI_awprot(prot),
    .S00_AXI_awqos(qos),
    .S00_AXI_awready(awready),
    .S00_AXI_awregion(region),
    .S00_AXI_awsize(size),
    .S00_AXI_awvalid(enable),
    .S00_AXI_bid(id),
    .S00_AXI_bready(1'b1),
    .S00_AXI_bresp(resp),
    .S00_AXI_bvalid(bvalid),
    .S00_AXI_rdata(read_data),
    .S00_AXI_rid(id),
    .S00_AXI_rlast(1'b1),
    .S00_AXI_rready(1'b1),
    .S00_AXI_rresp(resp),
    .S00_AXI_rvalid(rvalid),
    .S00_AXI_wdata(write_data),
    .S00_AXI_wlast(1'b1),
    .S00_AXI_wready(1'b1),
    .S00_AXI_wstrb(strb),
    .S00_AXI_wvalid(enable),
    .sys_clk_i(clk),
    .sys_rst(reset)
  );

  always @(posedge clk) begin
    if (reset) begin
      data_out <= 0;
      rw_status <= 0;
      data_valid <= 0;
      write_data <= 0;
      burst_type <= 0;
      burst_len <= 0;
      cache_type <= 0;
      qos <= 0;
      prot <= 0;
      region <= 0;
      size <= 0;
      strb <= 0;
      id <= 0;
    end else begin
      if (enable) begin
        if (arready && !rvalid && !bvalid) begin
          rw_status <= 0;
          data_valid <= 0;
          burst_type <= 2'b01;
          burst_len <= 2'b00;
          cache_type <= 4'b1111;
          qos <= 4'b0000;
          prot <= 3'b000;
          region <= 4'b0000;
          size <= 3'b010;
          strb <= 0;
          id <= 4'b0000;
        end else if (awready && !rvalid && !bvalid) begin
          rw_status <= 1;
          data_valid <= 0;
          write_data <= data_in;
          burst_type <= 2'b01;
          burst_len <= 2'b00;
          cache_type <= 4'b1111;
          qos <= 4'b0000;
          prot <= 3'b000;
          region <= 4'b0000;
          size <= 3'b010;
          strb <= 4'b1111;
          id <= 4'b0000;
        end else if (rvalid) begin
          data_out <= read_data;
          rw_status <= 0;
          data_valid <= 1;
        end else if (bvalid) begin
          rw_status <= 0;
          data_valid <= 1;
        end
      end
    end
  end
endmodule

module Clock_Divider (
  // Clock out ports
  output reg clk_out1,
  output reg clk_out2,
  output reg clk_out3,
  // Status and control signals
  input reset,
  output reg locked,
  // Clock in ports
  input clk_in1_p,
  input clk_in1_n
);

  wire clk_in;
  assign clk_in = clk_in1_p ^ clk_in1_n;

  reg [1:0] counter1 = 2'b00; // for clk_out1
  reg [2:0] counter2 = 3'b000; // for clk_out2
  reg [3:0] counter3 = 4'b0000; // for clk_out3

  always @(posedge clk_in or negedge reset) begin
    if(!reset) begin
      counter1 <= 2'b00;
      counter2 <= 3'b000;
      counter3 <= 4'b0000;
      clk_out1 <= 1'b0;
      clk_out2 <= 1'b0;
      clk_out3 <= 1'b0;
      locked <= 1'b0;
    end else begin
      counter1 <= counter1 + 1;
      if(counter1 == 2'b01) begin
        clk_out1 <= ~clk_out1;
      end
      counter2 <= counter2 + 1;
      if(counter2 == 3'b001) begin
        clk_out2 <= ~clk_out2;
      end
      counter3 <= counter3 + 1;
      if(counter3 == 4'b0001) begin
        clk_out3 <= ~clk_out3;
        locked <= 1'b1;
      end
    end
  end

endmodule

