module testbench;

    // Inputs
    reg CLK;
    reg D;
    reg SET_B;
    reg VPWR;
    reg VGND;
    reg VPB;
    reg VNB;

    // Outputs
    wire Q;

    // Instantiate the Unit Under Test (UUT)
    sky130_fd_sc_hdll__dfstp uut (
        .Q(Q),
        .CLK(CLK),
        .D(D),
        .SET_B(SET_B),
        .VPWR(VPWR),
        .VGND(VGND),
        .VPB(VPB),
        .VNB(VNB)
    );

    initial begin
        // Initialize Inputs
        CLK = 0;
        D = 0;
        SET_B = 0;
        VPWR = 0;
        VGND = 0;
        VPB = 0;
        VNB = 0;

        // Wait 100 ns for global reset to finish
        #100;

        // Test SET functionality
        SET_B = 1;
        #10;
        if (Q !== 1) $error("Error: SET functionality failed");

        // Test D functionality
        SET_B = 0;
        D = 0;
        CLK = 0;
        #10;
        if (Q !== 0) $error("Error: D functionality failed");
        D = 1;
        #10;
        if (Q !== 0) $error("Error: D functionality failed");
        CLK = 1;
        #10;
        if (Q !== 1) $error("Error: D functionality failed");
        D = 0;
        #10;
        if (Q !== 1) $error("Error: D functionality failed");

