module dual_edge_triggered_flip_flop (
    input clk,
    input d,
    output q
);

reg q_prev;
reg q_next;

always @(posedge clk or negedge clk)
begin
    if (~clk) // falling edge
    begin
        q_next <= d & q_prev;
        q_prev <= q_next;
    end
    else // rising edge
    begin
        q_next <= d ^ q_prev;
        q_prev <= q_next;
    end
end

assign q = q_next;

endmodule

