module VGA(
    input clk,
    input rst,
    output reg [7:0] red,
    output reg [7:0] green,
    output reg [7:0] blue,
    output reg hs,
    output reg vs,
    input [9:0] x,
    input [8:0] y
);

    // Horizontal timing parameters
    parameter H_SYNC_PULSE = 96;
    parameter H_SYNC_FRONT_PORCH = 16;
    parameter H_SYNC_BACK_PORCH = 48;
    parameter H_PIXELS = 640;

    // Vertical timing parameters
    parameter V_SYNC_PULSE = 2;
    parameter V_SYNC_FRONT_PORCH = 10;
    parameter V_SYNC_BACK_PORCH = 33;
    parameter V_LINES = 480;

    // Counter for horizontal timing
    reg [9:0] h_cnt = 0;

    // Counter for vertical timing
    reg [8:0] v_cnt = 0;

    // Output signals for synchronization pulses
    reg hs_pulse = 0;
    reg vs_pulse = 0;

    // Output signals for color components
    reg [7:0] r_out = 0;
    reg [7:0] g_out = 0;
    reg [7:0] b_out = 0;

    always @(posedge clk) begin
        if (rst) begin
            h_cnt <= 0;
            v_cnt <= 0;
            hs_pulse <= 0;
            vs_pulse <= 0;
            r_out <= 0;
            g_out <= 0;
            b_out <= 0;
        end else begin
            // Horizontal timing
            if (h_cnt >= H_PIXELS) begin
                h_cnt <= 0;
                if (v_cnt >= V_LINES) begin
                    v_cnt <= 0;
                end else begin
                    v_cnt <= v_cnt + 1;
                end
            end else begin
                h_cnt <= h_cnt + 1;
            end

            // Vertical timing
            if (v_cnt < V_SYNC_FRONT_PORCH || v_cnt >= V_LINES + V_SYNC_BACK_PORCH) begin
                vs_pulse <= 0;
            end else begin
                if (v_cnt < V_SYNC_FRONT_PORCH + V_SYNC_PULSE) begin
                    vs_pulse <= 1;
                end else begin
                    vs_pulse <= 0;
                end
            end

            if (h_cnt < H_SYNC_FRONT_PORCH || h_cnt >= H_PIXELS + H_SYNC_BACK_PORCH) begin
                hs_pulse <= 0;
            end else begin
                if (h_cnt < H_SYNC_FRONT_PORCH + H_SYNC_PULSE) begin
                    hs_pulse <= 1;
                end else begin
                    hs_pulse <= 0;
                end
            end

            // Color output
            if (h_cnt >= H_SYNC_FRONT_PORCH && h_cnt < H_PIXELS + H_SYNC_BACK_PORCH && v_cnt >= V_SYNC_FRONT_PORCH && v_cnt < V_LINES + V_SYNC_BACK_PORCH) begin
                r_out <= x[5:0];
                g_out <= y[7:2];
                b_out <= x[9:6];
            end else begin
                r_out <= 0;
                g_out <= 0;
                b_out <= 0;
            end
        end
    end

    assign red = r_out;
    assign green = g_out;
    assign blue = b_out;
    assign hs = hs_pulse;
    assign vs = vs_pulse;

endmodule

module mux_parity (
