  always @(*) begin
    case (select)
      4'b0000: final_output = Y + product[3:0];
      4'b0001: final_output = Y + product[7:4];
      4'b0010: final_output = Y + product[11:8];
      4'b0011: final_output = Y + product[15:12];
      4'b0100: final_output = Y + product[3:0] + product[7:4];
      4'b0101: final_output = Y + product[7:4] + product[11:8];
      4'b0110: final_output = Y + product[11:8] + product[15:12];
      4'b0111: final_output = Y + product[15:12];
      4'b1000: final_output = Y + product[3:0] + product[7:4] + product[11:8];
      4'b1001: final_output = Y + product[7:4] + product[11:8] + product[15:12];
      4'b1010: final_output = Y + product[3:0] + product[11:8] + product[15:12];
      4'b1011: final_output = Y + product[3:0] + product[7:4] + product[15:12];
      4'b1100: final_output = Y + product[3:0] + product[7:4] + product[11:8] + product[15:12];
      default: final_output = 4'b0000;
    endcase
  end

endmodule

module booth_multiplier (
    input signed [15:0] A,
    input signed [15:0] B,
    output reg signed [15:0] product
);

  reg signed [15:0] m;
  reg signed [31:0] a;
  reg signed [31:0] s;
  reg [5:0] i;

  always @(*) begin
    m = B < 0 ? -B : B;
    a = {16'b0, A};
    s = {16'b0, -A};
    product = 0;
    for (i = 0; i < 16; i = i + 1) begin
      if (m[0] == 1 && m[1] == 0) begin
        product = product + a;
      end else if (m[0] == 0 && m[1] == 1) begin
        product = product + s;
      end
      m = {m[14:0], m[15]};
      a = {a[30:0], a[31]};
      s = {s[30:0], s[31]};
    end
  end

endmodule

