module adder_subtractor(
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] sum
);

    wire [15:0] carry_out_1, carry_out_2;
    wire [31:0] add_out_1, add_out_2, sub_out_1, sub_out_2;

    carry_select_adder_16bit adder_1(
        .a(a[15:0]),
        .b(b[15:0]),
        .cin(1'b0),
        .cout(carry_out_1),
        .sum(add_out_1)
    );

    carry_select_adder_16bit adder_2(
        .a(a[31:16]),
        .b(b[31:16]),
        .cin(carry_out_1),
        .cout(carry_out_2),
        .sum(add_out_2)
    );

    assign sub_out_1 = a[15:0] - b[15:0] - ~sub;
    assign sub_out_2 = a[31:16] - b[31:16] - carry_out_1;

    assign sum = {sub, carry_out_2, sub_out_2, sub_out_1, add_out_2, add_out_1};

endmodule

module carry_select_adder_16bit(
    input [15:0] a,
    input [15:0] b,
    input cin,
    output [15:0] cout,
    output [15:0] sum
);

    wire [15:0] p, g;

    assign p = a ^ b;
    assign g = a & b;

    assign sum = cin ? p ^ cin : p;
    assign cout = g | (p & cin);

endmodule

module binary_counter(
