    output reg [3:0] count
);

    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            count <= 4'b0000; // reset to 0
        end else begin
            count <= count + 1; // increment
        end
    end

endmodule

module tb_binary_counter;

    reg clk, rst_n;
    wire [3:0] count;

    binary_counter counter(clk, rst_n, count);

    initial begin
        clk = 0;
        rst_n = 1;

        // wait for a few clock cycles
        #10;
        #10;

        // assert reset
        rst_n = 0;

        // verify reset to 0
        #10;
        if(count !== 4'b0000) begin
            $display("ERROR: Counter did not reset to 0");
            $finish;
        end

        // increment and verify
        rst_n = 1;
        #10;
        if(count !== 4'b0001) begin
            $display("ERROR: Counter did not increment correctly");
            $finish;
        end
        #10;
        if(count !== 4'b0010) begin
            $display("ERROR: Counter did not increment correctly");
            $finish;
        end
        #10;
        if(count !== 4'b0011) begin
            $display("ERROR: Counter did not increment correctly");
            $finish;
        end

        $display("SUCCESS: Counter implemented correctly");
        $finish;
    end

    // clock generation
    always begin
        #(5) clk = ~clk;
    end

endmodule

module fifo_9_4 (
    input clk_wr,
    input clk_rd,
    input rst,
    input wr_en,
    input rd_en,
    input rp_rst,
    input [8:0] data_in,
    output [8:0] data_out,
    output empty,
    output full
);

    reg [8:0] fifo [0:3];
    reg [1:0] wr_ptr;
    reg [1:0] rd_ptr;
    reg empty_reg;
    reg full_reg;

    always @(posedge clk_wr or posedge rst) begin
        if (rst) begin
            wr_ptr <= 2'b00;
            rd_ptr <= 2'b00;
            empty_reg <= 1'b1;
            full_reg <= 1'b0;
            fifo[0] <= 9'b0;
            fifo[1] <= 9'b0;
            fifo[2] <= 9'b0;
            fifo[3] <= 9'b0;
        end else if (wr_en && !full_reg) begin
            fifo[wr_ptr] <= data_in;
            wr_ptr <= wr_ptr + 1;
            if (wr_ptr == 2'b100) begin
                wr_ptr <= 2'b00;
            end
            if (wr_ptr == rd_ptr) begin
                full_reg <= 1'b1;
            end
            empty_reg <= 1'b0;
        end
    end

    always @(posedge clk_rd or posedge rst) begin
        if (rst || rp_rst) begin
            rd_ptr <= 2'b00;
        end else if (rd_en && !empty_reg) begin
            data_out <= fifo[rd_ptr];
            rd_ptr <= rd_ptr + 1;
            if (rd_ptr == 2'b100) begin
                rd_ptr <= 2'b00;
            end
            if (rd_ptr == wr_ptr) begin
                empty_reg <= 1'b1;
            end
            full_reg <= 1'b0;
        end
    end

    assign empty = empty_reg;
    assign full = full_reg;

endmodule

module five_to_one (
