    input  VNB
);

    wire A_high = A1 & A2 & A3;
    wire B_low = ~B1 & ~B2;
    wire B_high = B1 & B2;

    assign X = (A_high & B_low) | (~A_high & B_high);

endmodule

module fifo_bt_txd_blk_mem_gen_generic_cstr
   (D,
    wr_clk,
    rd_clk,
    WEA,
    tmp_ram_rd_en,
    SR,
    Q,
    \gc0.count_d1_reg[9] ,
    din);
  output [7:0]D;
  input wr_clk;
  input rd_clk;
  input [0:0]WEA;
  input tmp_ram_rd_en;
  input [0:0]SR;
  input [9:0]Q;
  input [9:0]\gc0.count_d1_reg[9] ;
  input [7:0]din;

  wire [7:0]D;
  wire [9:0]Q;
  wire [0:0]SR;
  wire [0:0]WEA;
  wire [7:0]din;
  wire [9:0]\gc0.count_d1_reg[9] ;
  wire rd_clk;
  wire tmp_ram_rd_en;
  wire wr_clk;

  // Define the parameters for the block memory generator
  parameter WIDTH = 8;
  parameter DEPTH = 16;

  // Define the memory array
  reg [WIDTH-1:0] mem [0:DEPTH-1];

  // Define the read and write pointers
  reg [log2(DEPTH)-1:0] wr_ptr = 0;
  reg [log2(DEPTH)-1:0] rd_ptr = 0;

  // Define the full and empty flags
  reg full = 0;
  reg empty = 1;

  // Define the write enable signal
  reg we = 0;

  // Define the synchronous reset signal
  reg [log2(DEPTH)-1:0] reset_ptr = 0;

  // Define the temporary read enable signal
  reg tr_en = 0;

  // Define the output signals
  assign D = mem[rd_ptr];
  assign Q = (full) ? DEPTH : (empty) ? 0 : (wr_ptr >= rd_ptr) ? wr_ptr - rd_ptr : DEPTH + wr_ptr - rd_ptr;

  // Define the write clock domain
  always @(posedge wr_clk) begin
    if (SR) begin
      // Synchronous reset
      wr_ptr <= reset_ptr;
      full <= 0;
      empty <= 1;
      we <= 0;
    end else begin
      if (we && !full) begin
        // Write data to memory
        mem[wr_ptr] <= din;

        // Update the write pointer
        wr_ptr <= (wr_ptr == DEPTH-1) ? 0 : wr_ptr + 1;

        // Update the full and empty flags
        full <= (wr_ptr == rd_ptr);
        empty <= 0;
      end
    end
  end

  // Define the read clock domain
  always @(posedge rd_clk) begin
    if (SR) begin
      // Synchronous reset
      rd_ptr <= reset_ptr;
      full <= 0;
      empty <= 1;
      tr_en <= 0;
    end else begin
      if (tr_en && !empty) begin
        // Update the read pointer
        rd_ptr <= (rd_ptr == DEPTH-1) ? 0 : rd_ptr + 1;

        // Update the full and empty flags
        full <= 0;
        empty <= (rd_ptr == wr_ptr);
      end
    end
  end

  // Define the write enable signal
  always @(posedge wr_clk) begin
    if (SR) begin
      we <= 0;
    end else begin
      we <= WEA;
    end
  end

  // Define the temporary read enable signal
  always @(posedge rd_clk) begin
    if (SR) begin
      tr_en <= 0;
    end else begin
      tr_en <= tmp_ram_rd_en;
    end
  end

endmodule

module ledtest_pio_0 (
                       // inputs:
                        address,
                        chipselect,
                        clk,
                        reset_n,
                        write_n,
                        writedata,

                       // outputs:
                        out_port,
                        readdata
                     )
;

  output           out_port;
  output  [ 31: 0] readdata;
  input   [  1: 0] address;
  input            chipselect;
  input            clk;
  input            reset_n;
  input            write_n;
  input   [ 31: 0] writedata;


  wire             clk_en;
  reg              data_out;
  wire             out_port;
  wire             read_mux_out;
  wire    [ 31: 0] readdata;

  // Clock enable signal
  assign clk_en = 1;

  // Mux to select between test interface and register interface
  assign read_mux_out = {1 {(address == 0)}} & data_out;

  // Register to store data
  always @(posedge clk or negedge reset_n)
    begin
      if (reset_n == 0)
          data_out <= 0;
      else if (chipselect && ~write_n && (address == 0))
          data_out <= writedata;
    end

  // Test interface to blink LED
  reg [31:0] test_counter;
  reg        test_enable;
  always @(posedge clk or negedge reset_n)
    begin
      if (reset_n == 0)
        begin
          test_counter <= 0;
          test_enable <= 0;
        end
      else if (chipselect && ~write_n && (address == 1))
        begin
          test_counter <= 0;
          test_enable <= 1;
        end
    end

  always @(posedge clk)
    begin
      if (test_enable)
        begin
          test_counter <= test_counter + 1;
          out_port <= (test_counter[23] ^ test_counter[22]);
        end
    end

  // Output assignments
  assign readdata = {32'b0 | read_mux_out};
  assign out_port = data_out;

endmodule

