module ripple_carry_adder(
    input [99:0] a, b,      // Input binary numbers
    input cin,              // Carry-in
    output cout,            // Carry-out
    output [99:0] sum );    // 100-bit sum output

    wire [99:0] carry;      // Internal carry signals

    // Generate the sum and carry signals
    genvar i;
    generate
        for (i = 0; i < 100; i = i + 1) begin : adder
            full_adder fa(a[i], b[i], cin, sum[i], carry[i]);
            assign cin = carry[i];
        end
    endgenerate

    // Assign the carry-out signal
    assign cout = carry[99];

endmodule

module carry_select_adder(
    input [99:0] a, b,      // Input binary numbers
    input cin,              // Carry-in
    input [7:0] control,    // Control signal
    output cout,            // Carry-out
    output [99:0] sum );    // 100-bit sum output

    wire [99:0] sum1, sum2; // Internal sum signals
    wire cout1, cout2;      // Internal carry-out signals

    // Instantiate the two ripple carry adders
    ripple_carry_adder rca1(a[99:50], b[99:50], cin, cout1, sum1);
    ripple_carry_adder rca2(a[49:0], b[49:0], cin, cout2, sum2);

    // Select the correct sum and carry-out signals based on the control signal
    assign sum = (control == 8'b00000001) ? sum1 : sum2;
    assign cout = (control == 8'b00000001) ? cout1 : cout2;

endmodule

module control_module(
    input [7:0] control,    // Control signal
    output sel );           // Selection signal

    // Generate the selection signal
    assign sel = (control == 8'b00000001) ? 1'b0 : 1'b1;

endmodule

module top_module( 
    input [99:0] a, b,      // Input binary numbers
