    input [7:0] control,    // Control signal
    output cout,            // Carry-out
    output [99:0] sum );    // 100-bit sum output

    wire sel;               // Selection signal

    // Instantiate the control module
    control_module cm(control, sel);

    // Instantiate the carry-select adder module
    carry_select_adder csa(a, b, cin, sel, cout, sum);

endmodule

