module xor_byte_reverse(
    input a,
    input b,
    input [31:0] in,
    output [31:0] out
);

    wire [7:0] byte0, byte1, byte2, byte3;
    wire [31:0] reversed;

    // Divide input into 4 bytes
    assign byte0 = in[7:0];
    assign byte1 = in[15:8];
    assign byte2 = in[23:16];
    assign byte3 = in[31:24];

    // Reverse the byte order
    assign reversed = {byte3, byte2, byte1, byte0};

    // XOR gate
    assign out = a ^ b;

    // Connect XOR output to byte-reversal module
    xor_byte_reverse_module xor_byte_rev(
        .a(out),
        .b(reversed),
        .out(out)
    );

endmodule

module xor_byte_reverse_module(
    input [31:0] a,
    input [31:0] b,
    output [31:0] out
);

    wire [31:0] shifted;

    // Barrel shifter to reverse byte order
    assign shifted = {b[7:0], b[15:8], b[23:16], b[31:24]};

    // Multiplexer to select input
    assign out = (a[31]) ? shifted : b;

endmodule

module lfsr(
    input CLK,
    input RST_N,
    input START,
    input STOP,
    output reg [15:0] DATA_OUT
);

reg [15:0] state;

always @(posedge CLK) begin
    if (RST_N == 0) begin
        state <= 16'h0000;
        DATA_OUT <= 16'h0000;
    end else if (START) begin
        state <= 16'h0000;
        DATA_OUT <= state;
    end else if (STOP) begin
        state <= 16'h0000;
        DATA_OUT <= 16'h0000;
    end else begin
        state <= {state[13:0], state[15]^state[13]};
        DATA_OUT <= state;
    end
end

endmodule

module four_bit_adder(A, B, C, Y, OVF);
input [3:0] A, B;
input C;
output [3:0] Y;
output OVF;

reg [3:0] sum;
reg [3:0] diff;

// Calculate the sum and difference
always @ (A, B, C)
begin
    if (C == 0) // Add
    begin
        sum = A + B;
        diff = 4'b0;
    end
    else // Subtract
    begin
        sum = 4'b0;
        diff = A - B;
    end
end

// Calculate the output and overflow
always @ (sum, diff)
begin
    if (sum > 4'b1111) // Overflow
    begin
        Y = 4'b1111;
        OVF = 1;
    end
    else if (diff < 4'b0000) // Underflow
    begin
        Y = 4'b0000;
        OVF = 1;
    end
    else // Normal output
    begin
        Y = (C == 0) ? sum : diff;
        OVF = 0;
    end
end

endmodule

module ripple_carry_adder (
  input [3:0] A,
  input [3:0] B,
  input Cin,
  output [3:0] S,
  output Cout
);

  wire [3:0] sum;
  wire carry_out;

  // Full adder module
  // Inputs: A, B, Cin
  // Outputs: S, Cout
  // S is the sum of A, B, and Cin
  // Cout is the carry-out from the full adder
  // The full adder is cascaded to create the ripple carry adder
  // The carry-out from each full adder is used as the carry-in to the next full adder
  // The carry-out from the last full adder is the carry-out from the ripple carry adder
  // The sum output is the sum of A, B, and Cin
  // The carry-out output is the carry-out from the ripple carry adder
  // The full adder is implemented using basic logic gates
  // The basic logic gates used are the AND, OR, XOR, and NOT gates

  // Full adder logic
  // A, B, Cin -> XOR gates -> S
  // A, B -> AND gates -> intermediate carry
  // Cin, intermediate carry -> OR gates -> Cout
  // The intermediate carry is the carry-in to the next full adder

  // Full adder module implementation
  // Inputs: A, B, Cin
  // Outputs: S, Cout
  // The full adder is implemented using basic logic gates
  // The basic logic gates used are the AND, OR, XOR, and NOT gates
  // The intermediate carry is the carry-in to the next full adder
  // The carry-out from the full adder is the carry-out from the ripple carry adder
  // The sum output is the sum of A, B, and Cin

  // Full adder logic
  // A, B, Cin -> XOR gates -> S
  // A, B -> AND gates -> intermediate carry
  // Cin, intermediate carry -> OR gates -> Cout

  // Full adder logic implementation
  // XOR gates for S
  assign sum[0] = A[0] ^ B[0] ^ Cin;
  assign sum[1] = A[1] ^ B[1] ^ sum[0];
  assign sum[2] = A[2] ^ B[2] ^ sum[1];
  assign sum[3] = A[3] ^ B[3] ^ sum[2];

  // AND gates for intermediate carry
  wire c1, c2, c3;
  assign c1 = A[0] & B[0];
  assign c2 = A[1] & B[1];
  assign c3 = A[2] & B[2];

  // OR gates for carry-out
  assign Cout = c3 | (c2 & sum[2]) | (c1 & sum[1]) | (Cin & sum[0]);

  // Assign sum output
  assign S = sum;

endmodule

module PLL (
  input ref,
  input vco,
  output out
);

parameter f_ref = 100e6; // frequency of reference signal
parameter f_vco = 50e6; // frequency range of VCO signal
parameter k_vco = 0.1; // VCO gain factor
parameter f_out = 10e6; // desired output frequency

reg [31:0] phase_ref;
reg [31:0] phase_vco;
reg [31:0] phase_diff;
reg [31:0] freq_vco;
reg [31:0] freq_out;

assign out = vco / (f_vco / f_out);

always @(posedge ref) begin
  phase_ref <= phase_ref + (2 * $unsigned(2 * $pi * f_out / f_ref));
end

always @(posedge vco) begin
  phase_vco <= phase_vco + (2 * $unsigned(2 * $pi * freq_vco / f_vco));
  freq_vco <= freq_vco + k_vco * (phase_ref - phase_vco);
end

endmodule

module multiplier (
    input [3:0] a,
    input [3:0] b,
    input enable,
    output reg [7:0] prod
);

reg [3:0] a_reg;
reg [3:0] b_reg;
reg [7:0] prod_reg;

always @(posedge clk) begin
    if (enable) begin
        prod_reg <= a_reg * b_reg;
    end else begin
        prod_reg <= 8'b0;
    end
end

always @(posedge clk) begin
    a_reg <= a;
    b_reg <= b;
end

assign prod = prod_reg;

endmodule

module io_interface #(parameter IOW = 64, parameter TARGET = "GENERIC")
(
    input nreset, // async active low reset
    input io_clk, // clock from divider
    input ddr_mode, // send data as ddr
    input [1:0] iowidth, // iowidth *8,16,32,64  
    input [7:0] io_valid, // per byte valid indicator
    input [IOW-1:0] io_packet, // packet
    output [IOW-1:0] tx_packet, // data for IO
    output reg tx_access, // access signal for IO
    input tx_wait, // IO wait signals
    output io_wait // pushback to serializer in sdr mode   
);

    //local wires
    reg [63:0] shiftreg;
    reg [2:0] tx_state;
    reg [IOW-1:0] tx_packet_sdr;
    reg [7:0] io_valid_reg;
    wire [IOW/2-1:0] tx_packet_ddr;
    wire tx_wait_sync;
    wire transfer_active;
    wire [7:0] io_valid_next;
    wire [IOW/2-1:0] ddr_data_even;
    wire [IOW/2-1:0] ddr_data_odd;
    wire dmode8;
    wire dmode16;
    wire dmode32;
    wire dmode64;
    wire io_nreset;
    wire reload;

    //########################################
    //# STATE MACHINE
    //########################################   

    assign dmode8   = (iowidth[1:0]==2'b00);   
    assign dmode16  = ((iowidth[1:0]==2'b01) & ~ddr_mode) |
                     (iowidth[1:0]==2'b00) & ddr_mode;   
    assign dmode32  = ((iowidth[1:0]==2'b10) & ~ddr_mode) |
                     (iowidth[1:0]==2'b01) & ddr_mode;   
    assign dmode64  = ((iowidth[1:0]==2'b11) & ~ddr_mode) |
                     (iowidth[1:0]==2'b10) & ddr_mode;   

    assign io_valid_next[7:0] = dmode8  ? {1'b0,io_valid_reg[7:1]} :
                                dmode16 ? {2'b0,io_valid_reg[7:2]} :
                                dmode32 ? {4'b0,io_valid_reg[7:4]} :
                                          8'b0;

    assign reload = ~transfer_active | dmode64 | (io_valid_next[7:0]==8'b0);

    always @ (posedge io_clk or negedge io_nreset)
    if(!io_nreset)
        io_valid_reg[7:0] <= 'b0;
    else if(reload)
        io_valid_reg[7:0] <= io_valid[7:0];
    else
        io_valid_reg[7:0] <= io_valid_next[7:0];

    assign transfer_active = |io_valid_reg[7:0];

    //pipeline access signal
    always @ (posedge io_clk or negedge io_nreset)
    if(!io_nreset)
        tx_access <= 1'b0;   
    else
        tx_access <= transfer_active;

    assign io_wait = tx_wait_sync | ~reload;

    //########################################
    //# SHIFT REGISTER  (SHIFT DOWN)
    //########################################

    always @ (posedge io_clk)
    if(reload)
        shiftreg[63:0] <= io_packet[IOW-1:0];
    else if(dmode8)//8 bit
        shiftreg[63:0] <= {8'b0,shiftreg[IOW-1:8]};   
    else if(dmode16)//16 bit
        shiftreg[63:0] <= {16'b0,shiftreg[IOW-1:16]};
    else if(dmode32)//32 bit
        shiftreg[63:0] <= {32'b0,shiftreg[IOW-1:32]};   

    //########################################
    //# DDR OUTPUT
    //########################################

    // pipeline sdr to compensate for ddr
    always @ (posedge io_clk)
        tx_packet_sdr[IOW-1:0] <= shiftreg[IOW-1:0];

    // ddr circuit (one stage pipeline delay!)
    assign ddr_data_even[IOW/2-1:0] = shiftreg[IOW/2-1:0];

    assign ddr_data_odd[IOW/2-1:0] = (iowidth[1:0]==2'b00) ? shiftreg[7:4]   : //byte
                                    (iowidth[1:0]==2'b01) ? shiftreg[15:8]  : //short
                                    (iowidth[1:0]==2'b10) ? shiftreg[31:16] : //word
                                                            shiftreg[63:32];  //double

    oh_oddr#(.DW(IOW/2))
    data_oddr (.out    (tx_packet_ddr[IOW/2-1:0]),
               .clk    (io_clk),
               .din1   (ddr_data_even[IOW/2-1:0]),
               .din2   (ddr_data_odd[IOW/2-1:0]));

    //select between ddr/sdr
    assign tx_packet[IOW-1:0] = ddr_mode ? {{(IOW/2){1'b0}},tx_packet_ddr[IOW/2-1:0]}:
                                                tx_packet_sdr[IOW-1:0];

    //########################################
    //# Synchronizers
    //########################################  

    // synchronize reset to io clock
    oh_rsync sync_reset(.nrst_out (io_nreset),
                       .clk     (io_clk),
                       .nrst_in (nreset));

    //synchronize wait
    oh_dsync sync_wait(.nreset   (io_nreset),
                      .clk      (io_clk),
                      .din      (tx_wait),
                      .dout     (tx_wait_sync));

endmodule

module my_module (
    input [3:0] a,
