module mc_ctrl (
    clk         ,
    rstn        ,
    mc_start_i      ,
    mc_done_o       ,
    mvd_access_o    ,
    chroma_start_o      ,
    chroma_sel_o        ,
    chroma_done_i       ,
    tq_start_o      ,
    tq_sel_o        ,
    tq_done_i       
);

// ********************************************
//
//    INPUT / OUTPUT DECLARATION
//
// ********************************************

input       [1-1:0]     clk          ; // clk signal 
input       [1-1:0]     rstn         ; // asynchronous reset
input       [1-1:0]     mc_start_i      ; // mc start 
output      [1-1:0]     mc_done_o       ; // mc done 
output              mvd_access_o ;
output      [1-1:0]     chroma_start_o   ; // chroma interpolation start 
output      [1-1:0]     chroma_sel_o     ; // chroma interpolation select: 0:cb, 1:cr
input       [1-1:0]     chroma_done_i       ; // chroma interpolation done 
output      [1-1:0]     tq_start_o      ; // tq start 
output      [2-1:0]     tq_sel_o        ; // tq sel: 00:luma, 10:cb, 11:cr
input       [1-1:0]     tq_done_i       ; // tq done 

// ********************************************
//
//    PARAMETER DECLARATION
//
// ********************************************

parameter IDLE         = 3'd0;
parameter TQ_LUMA      = 3'd1;
parameter MC_CB        = 3'd2;
parameter TQ_CB        = 3'd3;
parameter MC_CR        = 3'd4;
parameter TQ_CR        = 3'd5;
parameter DONE         = 3'd6;

// ********************************************
//
//    WIRE / REG DECLARATION
//
// ********************************************
reg      [3-1:0]        current_state, next_state;

// ********************************************
//
//    Combinational Logic
//
// ********************************************
always @(*) begin
                next_state = IDLE;
    case(current_state) 
        IDLE : begin
            if ( mc_start_i)
                next_state = TQ_LUMA;
            else
                next_state = IDLE;
        end
        TQ_LUMA: begin
            if ( tq_done_i)
                next_state = MC_CB;
            else
                next_state = TQ_LUMA;
        end
        MC_CB: begin
            if ( chroma_done_i)
                next_state = TQ_CB;
            else
                next_state = MC_CB;
        end
        TQ_CB: begin
            if ( tq_done_i)
                next_state = MC_CR;
            else
                next_state = TQ_CB;
        end
        MC_CR: begin
            if ( chroma_done_i)
                next_state = TQ_CR;
            else
                next_state = MC_CR;
        end
        TQ_CR: begin
            if ( tq_done_i)
                next_state = DONE;
            else
                next_state = TQ_CR;
        end
        DONE: begin
            next_state = IDLE;
        end
    endcase
end


assign      mc_done_o       = (current_state == DONE); 
assign      chroma_start_o  = (current_state == TQ_LUMA && next_state == MC_CB)  ||
                           (current_state == TQ_CB   && next_state == MC_CR)  ; 
assign      chroma_sel_o    = (current_state == MC_CR) ? 1'b1 : 1'b0; 
assign      tq_start_o      = (current_state == IDLE    && next_state == TQ_LUMA)||
                           (current_state == MC_CB   && next_state == TQ_CB)  || 
                           (current_state == MC_CR   && next_state == TQ_CR)  ; 
assign      tq_sel_o        = (current_state == TQ_LUMA) ? 2'b00 :
                           (current_state == TQ_CB  ) ? 2'b10 :
                           (current_state == TQ_CR  ) ? 2'b11 : 2'b00;

assign mvd_access_o = ( current_state == TQ_LUMA );

// ********************************************
//
//    Sequential Logic
//
// ********************************************

always @ (posedge clk or negedge rstn) begin
    if(~rstn) begin
        current_state <= IDLE;
    end
    else begin
        current_state <= next_state;
    end
end


endmodule

module psd_counter #
(
  parameter integer PERIOD = 256,
  parameter integer PERIOD_WIDTH = 8,
  parameter integer N_CYCLES = 2048,
  parameter integer N_CYCLES_WIDTH = 11
)
(
  input wire clk,
  input wire s_axis_tvalid,
  input wire [32-1:0] s_axis_tdata,
  output wire m_axis_tvalid,
  output wire [32-1:0] m_axis_tdata,
  output reg [PERIOD_WIDTH+1:0] addr,
  output reg [N_CYCLES_WIDTH-1:0] cycle_index,
  output reg first_cycle,
  output reg last_cycle
);

reg [PERIOD_WIDTH-1:0] cnt;
reg [N_CYCLES_WIDTH-1:0] cycle_index_reg;

initial cnt = 0;
initial cycle_index_reg = 0;

always @(posedge clk) begin
  addr <= {{cnt}, {2'b0}};
  cycle_index <= cycle_index_reg;
  first_cycle <= ((cnt < PERIOD) && (cycle_index_reg == 0));
  last_cycle <= ((cnt < PERIOD) && (cycle_index_reg == N_CYCLES - 1));
end

always @(posedge clk) begin
  if (s_axis_tvalid) begin
    if (cnt < PERIOD - 1) begin
      cnt <= cnt + 1;
    end else begin
      cnt <= 0;
      if (cycle_index < N_CYCLES - 1) begin
        cycle_index_reg <= cycle_index_reg + 1;
      end else begin
        cycle_index_reg <= 0;
      end
    end
  end
end

assign m_axis_tvalid = s_axis_tvalid;
assign m_axis_tdata = s_axis_tdata;

endmodule

module sm_control(
  clk, rst, clk_ena,
  // control
