module Comparator_Less
   (Data_A,
    Data_B,
    less);
  input [8:0]Data_A;
  input [8:0]Data_B;
  output less;

  wire [8:0]Data_A;
  wire less;
  wire less_INST_0_i_1_n_0;
  wire less_INST_0_i_1_n_1;
  wire less_INST_0_i_1_n_2;
  wire less_INST_0_i_1_n_3;
  wire less_INST_0_i_2_n_0;
  wire less_INST_0_i_3_n_0;
  wire less_INST_0_i_4_n_0;
