wire [15:0] a_signed;
wire [15:0] b_signed;
wire [15:0] two_complement;
wire carry_in;
wire carry_out;
wire overflow;

assign b_inverted = (sub == 1'b1) ? ~b : b;
assign a_signed = (a[15] == 1'b1) ? {{16{1'b1}}, a} : {{16{1'b0}}, a};
assign b_signed = (b_inverted[15] == 1'b1) ? {{16{1'b1}}, b_inverted} : {{16{1'b0}}, b_inverted};
assign two_complement = (sub == 1'b1) ? (~b_inverted + 1) : 16'h0;
assign carry_in = (sub == 1'b1) ? 1'b1 : 1'b0;

adder adder0 (.a(a_signed), .b(b_signed), .carry_in(carry_in), .sum(result[15:0]), .carry_out(carry_out), .overflow(overflow));
adder adder1 (.a(a_signed[15:0]), .b(b_signed[15:0]), .carry_in(carry_out), .sum(result[31:16]), .carry_out(), .overflow());

assign result = (sub == 1'b1) ? (a_signed + two_complement) : (a_signed + b_signed);

endmodule
