module float_add_sub (
	clk_en,
	clock,
	dataa,
	datab,
	overflow,
	result
);

	input	  clk_en;
	input	  clock;
	input	[31:0]  dataa;
	input	[31:0]  datab;
	output	  overflow;
	output	[31:0]  result;

	reg [30:0] exp_a;
	reg [30:0] exp_b;
	reg [31:0] mant_a;
	reg [31:0] mant_b;
	reg        sign_a;
	reg        sign_b;
	reg        sign_res;
	reg [30:0] exp_res;
	reg [31:0] mant_res;
	reg        overflow_res;

	assign overflow = overflow_res;

	always @(posedge clock) begin
		if (clk_en == 1'b1) begin
			// Extract sign, exponent, and mantissa from dataa and datab
			sign_a = dataa[31];
			sign_b = datab[31];
			exp_a = dataa[30:23];
			exp_b = datab[30:23];
			mant_a = dataa[22:0];
			mant_b = datab[22:0];

			// Calculate the true exponent and mantissa for each input
			if (exp_a == 8'h00) begin
				exp_a = 8'h01;
			end else if (exp_a == 8'hFF) begin
				exp_a = 8'hFE;
			end else begin
				exp_a = exp_a - 8'h7F + 8'h01;
			end
			mant_a = {1'b1, mant_a};

			if (exp_b == 8'h00) begin
				exp_b = 8'h01;
			end else if (exp_b == 8'hFF) begin
				exp_b = 8'hFE;
			end else begin
				exp_b = exp_b - 8'h7F + 8'h01;
			end
			mant_b = {1'b1, mant_b};

			// Perform addition or subtraction
			if (dataa[31] == 1'b0) begin
				// Addition
				if (exp_a > exp_b) begin
					exp_res = exp_a;
					mant_b = mant_b >> (exp_a - exp_b);
				end else begin
					exp_res = exp_b;
					mant_a = mant_a >> (exp_b - exp_a);
				end
				if (sign_a == sign_b) begin
					// Add mantissas
					mant_res = mant_a + mant_b;
					if (mant_res[32] == 1'b1) begin
						// Overflow
						exp_res = exp_res + 8'h01;
						mant_res = mant_res >> 1;
					end
					sign_res = sign_a;
				end else begin
					// Subtract mantissas
					mant_res = mant_a - mant_b;
					if (mant_res[31] == 1'b1) begin
						// Borrow
						exp_res = exp_res - 8'h01;
						mant_res = {1'b1, ~mant_res[30:0]};
					end
					sign_res = (mant_a > mant_b) ? sign_a : sign_b;
				end
			end else begin
				// Subtraction
				if (exp_a > exp_b) begin
					exp_res = exp_a;
					mant_b = mant_b >> (exp_a - exp_b);
				end else begin
					exp_res = exp_b;
					mant_a = mant_a >> (exp_b - exp_a);
				end
				if (sign_a != sign_b) begin
					// Add mantissas
					mant_res = mant_a + mant_b;
					if (mant_res[32] == 1'b1) begin
						// Overflow
						exp_res = exp_res + 8'h01;
						mant_res = mant_res >> 1;
					end
					sign_res = sign_a;
				end else begin
					// Subtract mantissas
					mant_res = mant_a - mant_b;
					if (mant_res[31] == 1'b1) begin
						// Borrow
						exp_res = exp_res - 8'h01;
						mant_res = {1'b1, ~mant_res[30:0]};
					end
					sign_res = (mant_a > mant_b) ? sign_a : sign_b;
				end
			end

			// Check for overflow
			if (exp_res == 8'hFF) begin
				overflow_res = 1'b1;
				exp_res = 8'hFE;
				mant_res = 32'h7FFFFFFF;
			end else if (exp_res == 8'h00) begin
				overflow_res = 1'b1;
				exp_res = 8'h01;
				mant_res = 0;
			end else begin
				overflow_res = 1'b0;
			end

			// Convert back to 32-bit floating-point format
			if (exp_res == 8'h01) begin
				exp_res = 8'h00;
			end else begin
				exp_res = exp_res - 8'h01 + 8'h7F;
			end
			mant_res = mant_res[22:0];

			// Combine sign, exponent, and mantissa into result
			result = {sign_res, exp_res, mant_res};
		end
	end

endmodule

module buffer_copier(
