        else begin
            copy_in_progress <= 0;
            back_vram_rd_low <= 1'bz;
            front_vram_wr_low <= 1;
            counter <= 0;
        end
    end

    assign back_vram_addr = copy_in_progress ? counter : 13'bzzzzzzzzzzzzz;
    assign front_vram_addr = copy_in_progress ? counter : 13'bzzzzzzzzzzzzz;

