module binary_tree_mux (
    input clk,
    input [1023:0] in,
    output [3:0] out,
    input [7:0] select);

    wire [3:0] level1[127:0];
    wire [3:0] level2[63:0];
    wire [3:0] level3[31:0];
    wire [3:0] level4[15:0];
    wire [3:0] level5[7:0];
    wire [3:0] level6[3:0];

    // Level 1
    genvar i;
    generate
        for (i = 0; i < 128; i = i + 2) begin
            binary_tree_mux_2to1 mux (
                .in0(in[i*8 +: 4]),
                .in1(in[(i+1)*8 +: 4]),
                .out(level1[i/2]),
                .select(select[6:5])
            );
        end
    endgenerate

    // Level 2
    generate
        for (i = 0; i < 64; i = i + 2) begin
            binary_tree_mux_2to1 mux (
                .in0(level1[i*2 +: 2]),
                .in1(level1[(i+1)*2 +: 2]),
                .out(level2[i/2]),
                .select(select[4:3])
            );
        end
    endgenerate

    // Level 3
    generate
        for (i = 0; i < 32; i = i + 2) begin
            binary_tree_mux_2to1 mux (
                .in0(level2[i*2 +: 2]),
                .in1(level2[(i+1)*2 +: 2]),
                .out(level3[i/2]),
                .select(select[2:1])
            );
        end
    endgenerate

    // Level 4
    generate
        for (i = 0; i < 16; i = i + 2) begin
            binary_tree_mux_2to1 mux (
                .in0(level3[i*2 +: 2]),
                .in1(level3[(i+1)*2 +: 2]),
                .out(level4[i/2]),
                .select(select[0])
            );
        end
    endgenerate

    // Level 5
    binary_tree_mux_2to1 mux5 (
        .in0(level4[0]),
        .in1(level4[1]),
        .out(level5[0]),
        .select(select[0])
    );
    binary_tree_mux_2to1 mux6 (
        .in0(level4[2]),
        .in1(level4[3]),
        .out(level5[1]),
        .select(select[0])
    );
    binary_tree_mux_2to1 mux7 (
        .in0(level4[4]),
        .in1(level4[5]),
        .out(level5[2]),
        .select(select[0])
    );
    binary_tree_mux_2to1 mux8 (
        .in0(level4[6]),
        .in1(level4[7]),
        .out(level5[3]),
        .select(select[0])
    );

    // Level 6
    binary_tree_mux_2to1 mux9 (
        .in0(level5[0]),
        .in1(level5[1]),
        .out(level6[0]),
        .select(select[0])
    );
    binary_tree_mux_2to1 mux10 (
        .in0(level5[2]),
        .in1(level5[3]),
        .out(level6[1]),
        .select(select[0])
    );

    assign out = level6[select[0]];

endmodule

