module AGC_block (
  input amplifier_output,
  input control_signal,
  output agc_output
);

parameter k = 0.5; // gain constant of the AGC block

reg [31:0] gain_value; // current gain value

// calculate the current gain value based on the control_signal and k parameter
always @ (control_signal) begin
  gain_value = control_signal * k;
end

// multiply the amplifier_output signal by the current gain value to get the agc_output signal
assign agc_output = amplifier_output * gain_value;

// limit the amplitude of the agc_output signal within a certain range, which is determined by the k parameter
always @ (agc_output) begin
  if (agc_output > k) begin
    agc_output = k;
  end
  else if (agc_output < -k) begin
    agc_output = -k;
  end
end

endmodule

module fifo (
   // Outputs
   out0, out1,
   // Inputs
   clk, wr0a, wr0b, wr1a, wr1b, inData
);

   input         clk;
   input         wr0a;
   input         wr0b;
   input         wr1a;
   input         wr1b;
   input [15:0]  inData;

   output [15:0] out0;
   output [15:0] out1;

   reg [15:0]    mem [1:0];
   reg [15:0]    memtemp2 [1:0];
   reg [15:0]    memtemp3 [1:0];

   assign        out0 = {mem[0] ^ memtemp2[0]};
   assign        out1 = {mem[1] ^ memtemp3[1]};

   always @(posedge clk) begin
      // These mem assignments must be done in order after processing
      if (wr0a) begin
         memtemp2[0] <= inData;
         mem[0] <=  inData;
      end
      if (wr0b) begin
         memtemp3[0] <= inData;
         mem[0] <= ~inData;
      end
      if (wr1a) begin
         memtemp3[1] <= inData;
         mem[1] <=  inData;
      end
      if (wr1b) begin
         memtemp2[1] <= inData;
         mem[1] <= ~inData;
      end
   end

endmodule

