module fifo_memory_block_generator
  (
    input wr_clk, rd_clk, WEA, tmp_ram_rd_en, SR,
    input [9:0] Q,
    input [7:0] din,
    output reg [7:0] D,
    output reg [9:0] \gc0.count_d1_reg[9]
  );

  reg [7:0] memory [1023:0];
  reg [9:0] count = 0;
  reg [9:0] read_pointer = 0;
  reg [9:0] write_pointer = 0;
  reg [9:0] next_write_pointer = 0;

  always @(posedge wr_clk) begin
    if (WEA) begin
      memory[write_pointer] <= din;
      next_write_pointer <= write_pointer + 1;
    end
  end

  always @(posedge rd_clk) begin
    if (tmp_ram_rd_en) begin
      D <= memory[read_pointer];
      read_pointer <= read_pointer + 1;
      count <= count - 1;
    end
  end

  always @(posedge wr_clk) begin
    if (next_write_pointer != read_pointer) begin
      write_pointer <= next_write_pointer;
      count <= count + 1;
    end
  end

  always @(posedge SR) begin
    if (SR) begin
      read_pointer <= 0;
      write_pointer <= 0;
      count <= 0;
    end
  end

  assign \gc0.count_d1_reg[9] = count;

endmodule

module TBCTRL_2 (
  input HRESETn,
  input HCLK,
  input HREADYin,
  input HREADYout,
  input HWRITEin,
  input HWRITEout,
  input HSEL,
  input HGRANT,
  output MAPSn,
  output MDPSn,
  output DENn,
  output SDPSn,
  output SRSn
);

reg [1:0] state;
reg [1:0] next_state;
wire [1:0] slave_state;
reg MRWSel;
reg RWSel;
reg SlaveDataPhaseSel;
reg MasterDataPhaseSel;
reg MasterAddrPhaseSel;
reg reg_HGRANT;

assign slave_state = state;

assign MAPSn = (state == 2'b00);
assign SDPSn = (state == 2'b01);
assign MDPSn = (state == 2'b10);
assign SRSn = (state == 2'b01) || (state == 2'b11);
assign DENn = (state == 2'b10) && (slave_state == 2'b10);

always @(posedge HCLK or negedge HRESETn) begin
    if (!HRESETn) begin
        state <= 2'b00;
        MRWSel <= 1'b0;
        RWSel <= 1'b0;
        SlaveDataPhaseSel <= 1'b1;
        MasterDataPhaseSel <= 1'b1;
        MasterAddrPhaseSel <= 1'b0;
        reg_HGRANT <= 1'b0;
    end else begin
        state <= next_state;
        case (state)
            2'b00: begin // Master address phase
                MasterAddrPhaseSel <= reg_HGRANT;
                if (HREADYin) begin
                    next_state <= 2'b01;
                end else begin
                    next_state <= 2'b00;
                end
            end
            2'b01: begin // Slave address phase
                if (HREADYin) begin
                    if (HWRITEin) begin
                        next_state <= 2'b10;
                    end else begin
                        next_state <= 2'b11;
                    end
                end else begin
                    next_state <= 2'b01;
                end
            end
            2'b10: begin // Master write data phase
                MRWSel <= HWRITEout;
                MasterDataPhaseSel <= 1'b0;
                if (HREADYin) begin
                    next_state <= 2'b00;
                end else begin
                    next_state <= 2'b10;
                end
            end
            2'b11: begin // Slave read data phase
                RWSel <= 1'b0;
                SlaveDataPhaseSel <= 1'b0;
                if (HREADYin) begin
                    next_state <= 2'b01;
                end else begin
                    next_state <= 2'b11;
                end
            end
        endcase
    end
end

always @(posedge HCLK or negedge HRESETn) begin
    if (!HRESETn) begin
        reg_HGRANT <= 1'b0;
    end else begin
        reg_HGRANT <= HGRANT;
    end
end

always @(posedge HCLK or negedge HRESETn) begin
    if (!HRESETn) begin
        SlaveDataPhaseSel <= 1'b1;
    end else begin
        if (HREADYin) begin
            SlaveDataPhaseSel <= slave_state[1];
        end
    end
end

always @(posedge HCLK or negedge HRESETn) begin
    if (!HRESETn) begin
        MasterDataPhaseSel <= 1'b1;
    end else begin
        if (HREADYin) begin
            MasterDataPhaseSel <= (MasterAddrPhaseSel && reg_HGRANT);
        end
    end
end

always @(posedge HCLK or negedge HRESETn) begin
    if (!HRESETn) begin
        RWSel <= 1'b0;
    end else begin
        if (HREADYin) begin
            RWSel <= ~HWRITEin;
        end
    end
end

endmodule

