  my_dff dff0(clk, 1'b0, data_in[0], q[0]);
  my_dff dff1(clk, 1'b0, q[0], q[1]);
  my_dff dff2(clk, 1'b0, q[1], q[2]);
  my_dff dff3(clk, 1'b0, q[2], q[3]);
  assign data_out = q;

endmodule

module my_dff (
  input clk,
  input reset,
  input d,
  output q
);

  reg q;
  always @(posedge clk) begin
    if (reset) begin
      q <= 1'b0;
    end else begin
