module mux_dff (
    Q,
    CLK,
    D,
    SCD,
    SCE,
    VPWR,
    VGND
);

    // Module ports
    output Q;
    input CLK;
    input D;
    input SCD;
    input SCE;
    input VPWR;
    input VGND;

    // Local signals
    wire buf_Q;
    wire mux_out;
    reg notifier;
    wire D_delayed;
    wire SCD_delayed;
    wire SCE_delayed;
    wire CLK_delayed;
    wire awake;
    wire cond1;
    wire cond2;
    wire cond3;

    // Delayed signals
    sky130_fd_sc_ms__udp_dff$P_pp$SG$N D_dff (D_delayed, D, CLK, VPWR, VGND);
    sky130_fd_sc_ms__udp_dff$P_pp$SG$N SCD_dff (SCD_delayed, SCD, CLK, VPWR, VGND);
    sky130_fd_sc_ms__udp_dff$P_pp$SG$N SCE_dff (SCE_delayed, SCE, CLK, VPWR, VGND);
    sky130_fd_sc_ms__udp_dff$P_pp$SG$N CLK_dff (CLK_delayed, CLK, CLK, VPWR, VGND);

    // Multiplexer
    sky130_fd_sc_ms__udp_mux_2to1 mux_2to1 (mux_out, D_delayed, SCD_delayed, SCE_delayed);

    // Flip-flop with clear and enable
    sky130_fd_sc_ms__udp_dff$P_pp$PG$N dff0 (buf_Q, mux_out, CLK_delayed, notifier, VPWR, VGND);

    // Buffer
    buf buf0 (Q, buf_Q);

    // Assignments
    assign awake = (VPWR == 1'b1);
    assign cond1 = (SCE_delayed == 1'b0) && awake;
    assign cond2 = (SCE_delayed == 1'b1) && awake;
    assign cond3 = (D_delayed != SCD_delayed) && awake;

    // Delayed signals
    always @(posedge CLK) begin
        D_delayed <= D;
        SCD_delayed <= SCD;
        SCE_delayed <= SCE;
        CLK_delayed <= CLK;
    end

    // Clear notifier
    always @(posedge CLK) begin
        notifier <= 1'b0;
    end

    // Clear
    always @(posedge CLK) begin
        if (SCD_delayed == 1'b1) begin
            buf_Q <= 1'b0;
            notifier <= 1'b1;
        end
    end

    // Enable
    always @(posedge CLK) begin
        if (cond1) begin
            buf_Q <= buf_Q;
        end else if (cond2) begin
            buf_Q <= mux_out;
        end
    end

    // Update
    always @(posedge CLK) begin
        if (cond3) begin
            buf_Q <= mux_out;
        end
    end

endmodule

module niosii_nios2_gen2_0_cpu_nios2_oci_dtrace (
