module byte_reversal(
    input [31:0] in,
    output [31:0] out );

    genvar i;
    wire [15:0] reversed_words[2:0];

    // Reverse byte order in each 2-byte word
    generate
        for (i = 0; i < 16; i = i + 2) begin : REVERSE_WORDS
            assign reversed_words[i/2][15:8] = in[i+7:i];
            assign reversed_words[i/2][7:0] = in[i+15:i+8];
        end
    endgenerate

    // Combine reversed words into 32-bit output
    assign out = {reversed_words[2], reversed_words[1], reversed_words[0]};

endmodule

module nor_using_nand(
    input a, 
    input b, 
    output out );

    wire nand1, nand2, nand3;

    // Implement NOR using only NAND gates
    assign nand1 = ~(a & b);
    assign nand2 = ~(a & nand1);
    assign nand3 = ~(b & nand1);
    assign out = ~(nand2 & nand3);

endmodule

