    reg [31:0] nor_input_reg;
    always @(posedge clk) begin
        nor_input_reg <= reversed;
    end

    nor_using_nand nor_inst(
        .a(nor_input_reg[31]),
        .b(nor_input_reg[30]),
        .out(out)
    );

