module top_module (
    input [31:0] A,
    input [31:0] B,
    output [7:0] out
);

    wire [31:0] sum;
    wire [4:0] ones_count;

    binary_adder adder_inst(
        .A(A),
        .B(B),
        .sum(sum)
    );

    count_ones ones_inst(
        .in(sum),
