module CIC_filter (
  input clk,
  input reset,
  input [word_width-1:0] data_in,
  input decimate_factor,
  input interpolate_factor,
  output [word_width-1:0] data_out
);

parameter word_width = 16;
parameter num_stages = 4;

reg [word_width-1:0] integrator_out;
reg [word_width-1:0] comb_out;
reg [word_width-1:0] data_out_reg;

always @(posedge clk or negedge reset) begin
  if(!reset) begin
    integrator_out <= 0;
    comb_out <= 0;
    data_out_reg <= 0;
  end else begin
    integrator_out <= integrator_out + data_in;
    for (i = 1; i < num_stages; i = i + 1) begin
      integrator_out <= integrator_out + integrator_out[i-1];
    end
    comb_out <= integrator_out;
    for (i = 1; i < num_stages; i = i + 1) begin
      comb_out <= comb_out - comb_out[i-1];
    end
    if (decimate_factor > 1) begin
      if (counter == decimate_factor - 1) begin
        data_out_reg <= comb_out;
        counter <= 0;
      end else begin
        counter <= counter + 1;
      end
    end else if (interpolate_factor > 1) begin
      data_out_reg <= comb_out;
      for (i = 1; i < interpolate_factor; i = i + 1) begin
        data_out_reg <= data_out_reg + comb_out;
      end
    end else begin
      data_out_reg <= comb_out;
    end
  end
end

assign data_out = data_out_reg;

endmodule

