module CIC_filter (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 16; // number of input samples
parameter m = 4; // number of output samples
parameter R = 4; // decimation factor
parameter M = 3; // number of stages
parameter N = 4; // samples per stage

reg [N-1:0] delay_line [0:M-1][0:N-1];
reg [N-1:0] comb_delay_line [0:M-1][0:N-1];

integer i, j;

always @(*) begin
  // Integrator stage
  for (i = 0; i < M; i = i + 1) begin
    delay_line[i][0] = in[i];
    for (j = 1; j < N; j = j + 1) begin
      delay_line[i][j] = delay_line[i][j-1] + delay_line[i-1][j-1];
    end
  end

  // Comb stage
  for (i = 0; i < M; i = i + 1) begin
    comb_delay_line[i][0] = delay_line[i][N-1];
    for (j = 1; j < N; j = j + 1) begin
      comb_delay_line[i][j] = comb_delay_line[i][j-1] - comb_delay_line[i-1][j-1];
    end
  end

  // Decimation stage
  for (i = 0; i < m; i = i + 1) begin
    out[i] = comb_delay_line[M-1][i*R];
  end
end

endmodule

