module priority_encoder(
    input [2:0] a,
    input [2:0] b,
    output reg [1:0] pos
);

// Binary to gray code converter
assign gray_a = {a[2], a[2]^a[1], a[1]^a[0], a[0]};
assign gray_b = {b[2], b[2]^b[1], b[1]^b[0], b[0]};

// Binary to one-hot decoder
always @*
begin
    case (pos)
        2'b00: priority = {1'b1, 1'b0, 1'b0, 1'b0};
        2'b01: priority = {1'b0, 1'b1, 1'b0, 1'b0};
        2'b10: priority = {1'b0, 1'b0, 1'b1, 1'b0};
        2'b11: priority = {1'b0, 1'b0, 1'b0, 1'b1};
    endcase
end

// Priority encoder
always @*
begin
    if (a > b) begin
        pos = priority_encoder(gray_a);
    end else begin
        pos = priority_encoder(gray_b);
    end
end

// Priority encoder implementation
function [1:0] priority_encoder;
    input [3:0] gray;
    begin
        case (gray)
            4'b0000: priority_encoder = 2'b00;
            4'b0001: priority_encoder = 2'b01;
            4'b0011: priority_encoder = 2'b10;
            4'b0111: priority_encoder = 2'b11;
        endcase
    end
endfunction

endmodule

