module InterruptController (
  input [n-1:0] int,
  input [n-1:0] en,
  input [n-1:0] pri,
  output intout,
  output ack
);

parameter n = 4; // number of interrupt signals

reg [n-1:0] int_active; // interrupt signals that are currently active
reg [n-1:0] int_pending; // interrupt signals that are pending
reg [n-1:0] int_enabled; // interrupt signals that are enabled
reg [n-1:0] int_priority; // priority levels for each interrupt signal

reg intout_reg; // register for intout signal
reg ack_reg; // register for ack signal

integer i; // loop index

always @(*) begin
  // clear pending interrupts
  int_pending = 0;

  // check which interrupts are active and pending
  for (i = 0; i < n; i = i + 1) begin
    if (en[i] == 1'b1 && int[i] == 1'b1 && int_active[i] == 1'b0) begin
      int_pending[i] = 1'b1;
    end
    int_active[i] = en[i] & int[i];
  end

  // determine highest priority interrupt
  for (i = 0; i < n; i = i + 1) begin
    if (int_pending[i] == 1'b1 && int_priority[i] > int_priority[intout_reg]) begin
      intout_reg = i;
    end
  end

  // set intout signal
  intout = int_active[intout_reg];
end

always @(posedge ack_reg) begin
  // clear intout signal and acknowledge interrupt
  int_active[intout_reg] = 1'b0;
  int_pending[intout_reg] = 1'b0;
  intout_reg = n;
  ack_reg = 1'b0;
end

always @(posedge intout_reg) begin
  // set acknowledge signal
  ack_reg = 1'b1;
end

// initialize interrupt enable and priority levels
initial begin
  int_enabled = {n{1'b1}};
  int_priority = {n{2'b00}};
end

endmodule

