module address(
  input CLK,
  input [23:0] SNES_ADDR,   // requested address from SNES
  input SNES_CS,            // "CART" pin from SNES (active low)
  output [23:0] ROM_ADDR,   // Address to request from SRAM0
  output ROM_HIT,           // enable SRAM0
  output IS_SAVERAM,        // address/CS mapped as SRAM?
  output IS_ROM,            // address mapped as ROM?
  input [23:0] SAVERAM_MASK,
  input [23:0] ROM_MASK
);

wire [23:0] SRAM_SNES_ADDR;

/* static mapper:
      menu (ROM in upper SRAM)
*/

/* HiROM:   SRAM @ Bank 0x30-0x3f, 0xb0-0xbf
            Offset 6000-7fff */

assign IS_ROM = ((!SNES_ADDR[22] & SNES_ADDR[15])
                 |(SNES_ADDR[22]));

assign IS_SAVERAM = (!SNES_ADDR[22]
                     & &SNES_ADDR[21:20]
                     & &SNES_ADDR[14:13]
                     & !SNES_ADDR[15]
                    );

assign SRAM_SNES_ADDR = (IS_SAVERAM
                             ? 24'hFF0000 + ((SNES_ADDR[14:0] - 15'h6000)
                                             & SAVERAM_MASK)
                             : (({1'b0, SNES_ADDR[22:0]} & ROM_MASK)
                                + 24'hC00000)
                        );

assign ROM_ADDR = SRAM_SNES_ADDR;

assign ROM_HIT = IS_ROM | IS_SAVERAM;

endmodule

module buf_ram_2p_64x208 (
            clk      ,
            a_we        ,
            a_addr    ,
            a_data_i    , 
            b_re    ,
            b_addr    ,
            b_data_o    
);

parameter PIXEL_WIDTH = 8; // change this to adjust the width of each word

// ********************************************
//                                             
//    Input/Output DECLARATION                    
//                                             
// ********************************************
input                   clk        ; 
// PORT A                     
input  [1:0]        a_we    ;     
input  [7:0]        a_addr    ;  
input  [PIXEL_WIDTH-1:0]  a_data_i  ; 
// PORT B              
input            b_re    ;  
input  [7:0]        b_addr    ;
output [PIXEL_WIDTH-1:0]  b_data_o    ;

// ********************************************
//                                             
//    Signals DECLARATION                        
//                                             
// ********************************************
reg   [PIXEL_WIDTH-1:0]  ram_array [63:0]; // 64 words of PIXEL_WIDTH bits each
reg   [PIXEL_WIDTH-1:0]  a_dataw    ;
reg   [7:0]          a_wen    ;

// ********************************************
//                                             
//    Logic DECLARATION                  
//                                             
// ********************************************
always @(*) begin
    case (a_we)
        2'b00: begin a_wen = 8'hff; end // write all 8 bytes of the word
        2'b01: begin a_wen = {4'hf, 4'h0}; end // write the first 4 bytes of the word
        2'b10: begin a_wen = {4'b0, 4'hf}; end // write the last 4 bytes of the word
        2'b11: begin a_wen = 8'h00; end // write no bytes of the word
    endcase
end

// write data to the RAM array
always @(posedge clk) begin
    if (!(|a_we)) begin // if a_we is 2'b11, do not write anything
        ram_array[a_addr] <= {a_wen & a_data_i, ~a_wen & ram_array[a_addr]}; // write only the bytes specified by a_we
    end
end

// read data from the RAM array
assign b_data_o = b_re ? ram_array[b_addr] : 'bz;

endmodule

