module calculator(input [3:0] num1, input [3:0] num2, input [1:0] op, input clk, input rst, output [3:0] result, output [3:0] display);

reg [7:0] temp_result;
reg [3:0] temp_display;
reg [1:0] state;

always @(posedge clk) begin
    if (rst) begin
        temp_result <= 0;
        temp_display <= 0;
        state <= 0;
    end else begin
        case (state)
            0: begin // addition
                temp_result <= num1 + num2;
                state <= 1;
            end
            1: begin // subtraction
                temp_result <= num1 - num2;
                state <= 2;
            end
            2: begin // multiplication
                temp_result <= num1 * num2;
                state <= 3;
            end
            3: begin // division
                temp_result <= num1 / num2;
                state <= 0;
            end
        endcase
    end
end

always @(posedge clk) begin
    if (rst) begin
        temp_display <= 0;
    end else begin
        case (op)
            2'b00: begin // addition
                temp_display <= temp_result[3:0];
            end
            2'b01: begin // subtraction
                temp_display <= temp_result[3:0];
            end
            2'b10: begin // multiplication
                temp_display <= temp_result[3:0];
            end
            2'b11: begin // division
                temp_display <= temp_result[3:0];
            end
        endcase
    end
end

assign result = temp_result[3:0];
assign display = temp_display;

endmodule

module splitter
  #(parameter INIT0 = 64'h0000000008888888,
    parameter INIT1 = 64'h2222222220000000)
  (m_ready_d,
   aresetn_d,
   m_ready_d0,
   s_axi_arready_i_reg,
   aa_grant_rnw,
   m_valid_i,
   aclk);

  output [1:0] m_ready_d;
  output m_ready_d0;
  input aresetn_d;
  input m_valid_i;
  input aa_grant_rnw;
  input s_axi_arready_i_reg;
  input aclk;

  wire [1:0] m_ready_d_int;
  wire [1:0] m_ready_d_reg_int;
  wire [1:0] m_ready_d_reg_next_int;
  wire m_ready_d0_int;
  wire m_ready_d0_reg_int;
  wire m_ready_d0_reg_next_int;

  assign m_ready_d = m_ready_d_int;
  assign m_ready_d0 = m_ready_d0_int;

  // LUT6 for m_ready_d[0]
  LUT6 #(.INIT(INIT0)) lut0 (
    .I0(aresetn_d),
    .I1(m_ready_d0_reg_int),
    .I2(s_axi_arready_i_reg),
    .I3(aa_grant_rnw),
    .I4(m_valid_i),
    .I5(m_ready_d_int[1]),
    .O(m_ready_d_reg_next_int[0])
  );

  // LUT6 for m_ready_d[1]
  LUT6 #(.INIT(INIT1)) lut1 (
    .I0(aresetn_d),
    .I1(m_ready_d0_reg_int),
    .I2(s_axi_arready_i_reg),
    .I3(aa_grant_rnw),
    .I4(m_valid_i),
    .I5(m_ready_d_int[0]),
    .O(m_ready_d_reg_next_int[1])
  );

  // FDRE for m_ready_d[0]
  FDRE fdre0 (
    .C(aclk),
    .CE(1'b1),
    .D(m_ready_d_reg_next_int[0]),
    .Q(m_ready_d_reg_int[0]),
    .R(1'b0)
  );

  // FDRE for m_ready_d[1]
  FDRE fdre1 (
    .C(aclk),
    .CE(1'b1),
    .D(m_ready_d_reg_next_int[1]),
    .Q(m_ready_d_reg_int[1]),
    .R(1'b0)
  );

  // FDRE for m_ready_d0
  FDRE fdre2 (
    .C(aclk),
    .CE(1'b1),
    .D(m_ready_d0_reg_next_int),
    .Q(m_ready_d0_reg_int),
    .R(1'b0)
  );

  // Combinational logic for m_ready_d0
  assign m_ready_d0_int = ~m_ready_d0_reg_int & m_valid_i;

  // Registers for m_ready_d and m_ready_d0
  always @(posedge aclk or negedge aresetn_d) begin
    if (~aresetn_d) begin
      m_ready_d_reg_int <= 2'b0;
      m_ready_d0_reg_int <= 1'b0;
    end else begin
      m_ready_d_reg_int <= m_ready_d_reg_next_int;
      m_ready_d0_reg_int <= m_ready_d0_reg_next_int;
    end
  end

endmodule

module top_module (
    input [3:0] in1,    // First 4-bit input for the multiplexer
    input [3:0] in2,    // Second 4-bit input for the multiplexer
    input sel1,         // First select input for the multiplexer
    input sel2,         // Second select input for the multiplexer
    output [3:0] mux_out,   // 4-bit output from the multiplexer
    input [3:0] comp_in1,   // First 4-bit input for the comparator
    input [3:0] comp_in2,   // Second 4-bit input for the comparator
    output eq_out,      // 1-bit output indicating if the two inputs are equal
    output gt_out,      // 1-bit output indicating if the first input is greater than the second input
    output lt_out       // 1-bit output indicating if the first input is less than the second input
);

    // 2-to-1 multiplexer
    always @(*) begin
        if (sel1 & sel2) begin
            mux_out = in2;
        end else begin
            mux_out = in1;
        end
    end

    // 4-bit binary comparator
    assign eq_out = (comp_in1 == comp_in2);
    assign gt_out = (comp_in1 > comp_in2);
    assign lt_out = (comp_in1 < comp_in2);

endmodule

module top_module (
    input clk,
    input rst,
    input [15:0] a,
    input [15:0] b,
    input [4:0] shift,
    input [3:0] select,
    output reg [7:0] out
);

    reg [15:0] and_out;
    reg [31:0] shift_out;
    reg [15:0] add_out;
    reg [3:0] counter;

    // AND gate module
    always @ (a, b) begin
        case ({a, b})
            16'b11: and_out <= 1;
            default: and_out <= 0;
        endcase
    end

    // Byte-shifting module
    always @ (a, b, shift) begin
        shift_out[31:24] = b[15:8];
        shift_out[23:16] = b[7:0];
        shift_out[15:8] = a[15:8];
        shift_out[7:0] = a[7:0];
        shift_out = shift_out << shift;
    end

    // Functional module (bitwise addition with constant value)
    always @ (shift_out) begin
        add_out = shift_out + 16'h1234;
    end

    // Output selection
    always @ (select, and_out, add_out) begin
        case (select)
            4'b0000: out <= and_out[7:0];
            4'b0001: out <= add_out[15:8];
            default: out <= 0;
        endcase
    end

    // Counter
    always @ (posedge clk, posedge rst) begin
        if (rst) begin
            counter <= 0;
        end else if (counter == shift) begin
            counter <= 0;
        end else begin
            counter <= counter + 1;
        end
    end

endmodule

