module bit_shift_tb;

reg [7:0] var1, var2;
wire [7:0] result;

bit_shift uut(
    .var1(var1),
    .var2(var2),
    .result(result)
);

initial begin
    var1 = 8'h80;
    for(var2 = 8'h0; var2 <= 8'h7; var2 = var2 + 1) begin
        #1;
        if(result !== (var1 >> var2)) begin
            $display("Test failed for var1 = %h, var2 = %h", var1, var2);
            $finish;
        end
    end

    var1 = 8'ha5;
    var2 = 8'h7;
    #1;
    if(result !== 8'h01) begin
        $display("Test failed for var1 = %h, var2 = %h", var1, var2);
        $finish;
    end

    var1 = 8'haa;
    var2 = 8'h1;
    #1;
    if(result !== 8'h55) begin
        $display("Test failed for var1 = %h, var2 = %h", var1, var2);
        $finish;
    end

    $display("All tests passed.");
    $finish;
end

endmodule

