module mux_dff (
    input wire D,
    input wire SCD,
    input wire SCE,
    input wire CLK,
    output reg Q,
    output reg Q_N
);

    reg mux_out;
    reg [1:0] state;

    always @(posedge CLK) begin
        case (state)
            2'b00: begin
                mux_out <= D;
                Q <= mux_out;
                Q_N <= ~mux_out;
                if (SCE && !SCD) begin
                    state <= 2'b01;
                end else if (SCD && !SCE) begin
                    state <= 2'b10;
                end
            end
            2'b01: begin
                mux_out <= 1'b1;
                Q <= mux_out;
                Q_N <= ~mux_out;
                if (!SCE) begin
                    state <= 2'b00;
                end
            end
            2'b10: begin
                mux_out <= 1'b0;
                Q <= mux_out;
                Q_N <= ~mux_out;
                if (!SCD) begin
                    state <= 2'b00;
                end
            end
        endcase
    end

endmodule

module pixel_fifo
#(
    parameter DATA_BITS = 8,
    parameter DEPTH_BITS = 4
)
(
    input wire clk,
    input wire aclr,
    input wire write,
    input wire read,
    input wire [DATA_BITS-1:0] din,
    output wire empty_n,
    output wire full_n,
    output wire [DATA_BITS-1:0] dout
);

localparam DEPTH = 1 << DEPTH_BITS;

reg [DATA_BITS-1:0] mem [0:DEPTH-1];
reg [DEPTH_BITS-1:0] head;
reg [DEPTH_BITS-1:0] tail;
reg empty;
reg full;

assign empty_n = ~empty;
assign full_n = ~full;
assign dout = mem[tail];

always @(posedge clk or posedge aclr) begin
    if (aclr) begin
        empty <= 1'b1;
        full <= 1'b0;
        head <= 0;
        tail <= 0;
    end else begin
        if (write && !full) begin
            mem[head] <= din;
            head <= head + 1;
            if (head == DEPTH) begin
                head <= 0;
            end
            empty <= 0;
            if (head == tail) begin
                full <= 1;
            end
        end
        if (read && !empty) begin
            tail <= tail + 1;
            if (tail == DEPTH) begin
                tail <= 0;
            end
            full <= 0;
            if (tail == head) begin
                empty <= 1;
            end
        end
    end
end

endmodule

