module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] d,    // 8-bit input for the register
    input select,     // Select input to choose between register and counter
    input write_en,   // Write enable signal for the RAM
    input [7:0] write_addr, // Write address for the RAM
    input [3:0] write_data, // Write data for the RAM
    input read_en,    // Read enable signal for the RAM
    input [7:0] read_addr,  // Read address for the RAM
    output reg [7:0] q,   // 8-bit output from the active module
    output reg [3:0] counter_out, // Output from the counter module
    output reg [3:0] ram_out // Output from the RAM module
);

reg [7:0] reg_out;
reg [3:0] counter;

// 8-bit register module
always @(posedge clk or posedge reset) begin
    if (reset) begin
        reg_out <= 8'h34;
    end else begin
        reg_out <= d;
    end
end

// 4-bit counter module
always @(posedge clk or posedge reset) begin
    if (reset) begin
        counter <= 4'b0000;
    end else begin
        counter <= counter + 1;
    end
end

// Control logic module
always @(posedge clk) begin
    if (select) begin
        q <= reg_out;
    end else begin
        q <= counter;
    end
end

// Additional functional module
assign counter_out = counter + reg_out[3:0];

// True dual-port RAM module
reg [3:0] ram [0:7];

always @(posedge clk) begin
    if (write_en) begin
        ram[write_addr[2:0]] <= write_data;
    end
    if (read_en) begin
        ram_out <= ram[read_addr[2:0]];
    end
end

endmodule

module async_transmitter(
    input clk,
    input TxD_start,
    input [7:0] TxD_data,
    output TxD,
    output TxD_busy
);

// Assert TxD_start for (at least) one clock cycle to start transmission of TxD_data
// TxD_data is latched so that it doesn't have to stay valid while it is being sent

parameter ClkFrequency = 50000000;    // 25MHz
parameter Baud = 115200;

generate
    if(ClkFrequency<Baud*8 && (ClkFrequency % Baud!=0)) 
        ASSERTION_ERROR PARAMETER_OUT_OF_RANGE("Frequency incompatible with requested Baud rate");
endgenerate

wire [9:0] baud_rate_counter;
wire [2:0] state;
wire [7:0] data_to_send;
wire bit_tick;

assign TxD_busy = (state != 3'b000);

// Latch TxD_data on TxD_start
reg [7:0] TxD_data_latched;
always @(posedge clk) begin
    if (TxD_start) begin
        TxD_data_latched <= TxD_data;
    end
end

// Generate baud rate clock
baud_rate_generator #(.ClkFrequency(ClkFrequency), .Baud(Baud)) baud_rate_gen(
    .clk(clk),
    .baud_rate_counter(baud_rate_counter)
);

// State machine to send out data
assign data_to_send = {1'b0, TxD_data_latched, 2'b1};
always @(posedge clk) begin
    if (baud_rate_counter == 0) begin
        bit_tick <= 1'b1;
        case (state)
            3'b000: begin  // Idle state
                if (TxD_start) begin
                    state <= 3'b001;
                end
            end
            3'b001: begin  // Start bit
                TxD <= 1'b0;
                state <= 3'b010;
            end
            3'b010: begin  // Data bits
                TxD <= data_to_send[0];
                data_to_send <= {data_to_send[6:0], 1'b0};
                state <= 3'b011;
            end
            3'b011: begin
                TxD <= data_to_send[0];
                data_to_send <= {data_to_send[6:0], 1'b0};
                state <= 3'b100;
            end
            3'b100: begin
                TxD <= data_to_send[0];
                data_to_send <= {data_to_send[6:0], 1'b0};
                state <= 3'b101;
            end
            3'b101: begin
                TxD <= data_to_send[0];
                data_to_send <= {data_to_send[6:0], 1'b0};
                state <= 3'b110;
            end
            3'b110: begin
                TxD <= data_to_send[0];
                data_to_send <= {data_to_send[6:0], 1'b0};
                state <= 3'b111;
            end
            3'b111: begin
                TxD <= data_to_send[0];
                data_to_send <= {data_to_send[6:0], 1'b0};
                state <= 3'b000;
            end
        endcase
    end else begin
        bit_tick <= 1'b0;
    end
end

endmodule

module baud_rate_generator(
    input clk,
    output reg [9:0] baud_rate_counter
);

parameter ClkFrequency = 50000000;
parameter Baud = 115200;

reg [24:0] counter;

always @(posedge clk) begin
    if (counter == ClkFrequency/Baud - 1) begin
        baud_rate_counter <= 10'b0;
        counter <= 25'd0;
    end else begin
        baud_rate_counter <= baud_rate_counter + 10'd1;
        counter <= counter + 25'd1;
    end
end

endmodule

