initial begin
    Q = 1'bx;
end

always @(posedge GATE) begin
    if (NOTIFIER) begin
        Q_next = D;
    end else begin
        Q_next = Q;
    end
end

always @* begin
    if (VPWR) begin
        Q_next = 1'b1;
    end else if (VGND) begin
        Q_next = 1'b0;
    end
end

always @(posedge GATE) begin
    Q <= Q_next;
end

endmodule

