module adder_module (
  input [7:0] A,
  input [7:0] B,
  input [1:0] ADDER_TYPE,
  output reg [8:0] SUM
);

  // Ripple Carry Adder
  generate
    if (ADDER_TYPE == 2'b00) begin
      genvar i;
      wire [8:0] carry [8:0];

      assign carry[0] = 1'b0;
      assign SUM[0] = A[0] ^ B[0] ^ carry[0];

      for (i = 1; i < 8; i = i + 1) begin
        assign carry[i] = (A[i] & B[i]) | (A[i] & carry[i-1]) | (B[i] & carry[i-1]);
        assign SUM[i] = A[i] ^ B[i] ^ carry[i];
      end

      assign SUM[8] = carry[7];
    end
  endgenerate

  // Carry Lookahead Adder
  generate
    if (ADDER_TYPE == 2'b01) begin
      genvar i;
      wire [8:0] carry [8:0];

      assign carry[0] = 1'b0;
      assign SUM[0] = A[0] ^ B[0] ^ carry[0];

      for (i = 1; i < 8; i = i + 1) begin
        assign carry[i] = (A[i] & B[i]);
      end

      assign SUM[1] = A[1] ^ B[1] ^ carry[0];
      assign SUM[2] = A[2] ^ B[2] ^ (A[1] & B[1]);
      assign SUM[3] = A[3] ^ B[3] ^ (A[2] & B[2]) ^ ((A[1] | B[1]) & carry[0]);
      assign SUM[4] = A[4] ^ B[4] ^ (A[3] & B[3]) ^ ((A[2] | B[2]) & (A[1] | B[1]));
      assign SUM[5] = A[5] ^ B[5] ^ (A[4] & B[4]) ^ ((A[3] | B[3]) & (A[2] | B[2])) ^ ((A[1] | B[1]) & carry[0]);
      assign SUM[6] = A[6] ^ B[6] ^ (A[5] & B[5]) ^ ((A[4] | B[4]) & (A[3] | B[3])) ^ ((A[2] | B[2]) & (A[1] | B[1])) ^ carry[0];
      assign SUM[7] = A[7] ^ B[7] ^ (A[6] & B[6]) ^ ((A[5] | B[5]) & (A[4] | B[4])) ^ ((A[3] | B[3]) & (A[2] | B[2])) ^ ((A[1] | B[1]) & carry[0]);
      assign SUM[8] = carry[7];
    end
  endgenerate

  // Carry Select Adder
  generate
    if (ADDER_TYPE == 2'b10) begin
      wire [8:0] carry0 [8:0];
      wire [8:0] carry1 [8:0];

      assign carry0[0] = 1'b0;
      assign carry1[0] = 1'b0;
      assign SUM[0] = A[0] ^ B[0] ^ carry0[0];

      genvar i;
      for (i = 1; i < 8; i = i + 1) begin
        assign carry0[i] = (A[i] & B[i]) | (A[i] & carry0[i-1]) | (B[i] & carry0[i-1]);
        assign carry1[i] = (A[i] & B[i]) | (A[i] & carry0[i-1]) | (B[i] & carry0[i-1]) | (carry0[i-1] & carry1[i-1]);
        assign SUM[i] = A[i] ^ B[i] ^ carry1[i-1];
      end

      assign SUM[8] = carry1[7];
    end
  endgenerate

endmodule

