module adder4bit (
    input [3:0] A,
    input [3:0] B,
    input [3:0] Cin,
    output [3:0] S,
    output Cout
);

    wire [3:0] sum;
    wire [4:0] carry;

    // Full adder
    full_adder fa0 (.A(A[0]), .B(B[0]), .Cin(Cin), .S(sum[0]), .Cout(carry[0]));
    full_adder fa1 (.A(A[1]), .B(B[1]), .Cin(carry[0]), .S(sum[1]), .Cout(carry[1]));
    full_adder fa2 (.A(A[2]), .B(B[2]), .Cin(carry[1]), .S(sum[2]), .Cout(carry[2]));
    full_adder fa3 (.A(A[3]), .B(B[3]), .Cin(carry[2]), .S(sum[3]), .Cout(carry[3]));

    assign S = sum;
    assign Cout = carry[3];

endmodule

module full_adder (
    input A,
    input B,
    input Cin,
    output S,
    output Cout
);

    wire sum1;
    wire Cout1;

    // First XOR gate
    xor x1 (.A(A), .B(B), .Y(sum1));

    // Second XOR gate
    xor x2 (.A(sum1), .B(Cin), .Y(S));

    // AND gate
    and a1 (.A(A), .B(B), .Y(Cout1));

    // OR gate
    or o1 (.A(Cout1), .B(sum1), .Y(Cout));

endmodule

