    input read,
    input [31:0] adcdat,
    input adclrc,
    input clear,
    output empty,
    output [31:0] readdata
);

parameter DATA_WIDTH = 32;
parameter FIFO_DEPTH = 1024;

wire adcfifo_full;
wire adcfifo_empty;

wire [DATA_WIDTH-1:0] adcfifo_data;
reg [DATA_WIDTH-1:0] adcfifo_writedata;
reg adcfifo_write;

wire [DATA_WIDTH-1:0] parallel_data;
reg [DATA_WIDTH-1:0] parallel_data_reg;

reg [9:0] fifo_count;

assign empty = adcfifo_empty;

fifo #(.DATA_WIDTH(DATA_WIDTH), .DEPTH(FIFO_DEPTH)) adcfifo (
    .clk(clk),
    .reset(reset),
    .clear(clear),
    .write(adcfifo_write),
    .data(adcfifo_writedata),
    .full(adcfifo_full),
    .read(read),
    .q(adcfifo_data),
    .empty(adcfifo_empty)
);

assign parallel_data = {adcdat[0], adcdat[2], adcdat[4], adcdat[6], adcdat[8], adcdat[10], adcdat[12], adcdat[14], adcdat[16], adcdat[18], adcdat[20], adcdat[22], adcdat[24], adcdat[26], adcdat[28], adcdat[30]};

always @(posedge clk) begin
    if (reset) begin
        adcfifo_writedata <= 0;
        adcfifo_write <= 0;
        parallel_data_reg <= 0;
        fifo_count <= 0;
    end else begin
        if (adclrc == 1'b1) begin
            parallel_data_reg[31:16] <= parallel_data;
        end else begin
            parallel_data_reg[15:0] <= parallel_data;
        end

        if (fifo_count < FIFO_DEPTH) begin
            adcfifo_writedata <= parallel_data_reg;
            adcfifo_write <= 1'b1;
            fifo_count <= fifo_count + 1;
        end
    end
end

assign readdata = adcfifo_data;

endmodule

module johnson_counter (
  input clock,
  output [n-1:0] out
);

parameter n = 4; // number of output signals

reg [n-1:0] shift_reg;
wire [n-1:0] next_state;

assign next_state[0] = shift_reg[n-1] ^ shift_reg[n-2];
assign next_state[n-1] = shift_reg[n-2] ^ shift_reg[n-3];

genvar i;
generate
  for (i = 1; i < n-1; i = i+1) begin
    assign next_state[i] = shift_reg[i-1] ^ shift_reg[i] ^ shift_reg[i+1];
  end
endgenerate

always @(posedge clock) begin
  shift_reg <= next_state;
end

assign out = shift_reg;

endmodule

module acl_shift_register(
  input clock,
  input resetn,
  input clear,
  input enable,
  input [WIDTH-1:0] D,
  output [WIDTH-1:0] Q
);
  parameter WIDTH = 32;
  parameter STAGES = 1;

  wire [WIDTH-1:0] D;
  reg [WIDTH-1:0] stages [STAGES-1:0];

  generate
  if (STAGES == 0) begin
    assign Q = D;
  end
  else begin
    genvar i;
    for (i = 0; i < STAGES; i = i + 1) begin : stages_loop
      always @(posedge clock or negedge resetn) begin
        if (!resetn) begin
          stages[i] <= {(WIDTH){1'b0}};
        end
        else if (clear) begin
          stages[i] <= {(WIDTH){1'b0}};
        end
        else if (enable) begin
          if (i == 0) begin
            stages[i] <= D;
          end
          else begin
            stages[i] <= stages[i-1];
          end
        end
      end
    end
    assign Q = stages[STAGES-1];
  end
  endgenerate
endmodule

module regfile_16x32b_4rd_2wr(
  input wire clk,
  input wire rst,
  input wire [3:0] rdport1_ctrl_add,
  output wire [31:0] rdport1_data_out,
  input wire [3:0] rdport2_ctrl_add,
  output wire [31:0] rdport2_data_out,
  input wire [3:0] rdport3_ctrl_add,
  output wire [31:0] rdport3_data_out,
  input wire [3:0] rdport4_ctrl_add,
  output wire [31:0] rdport4_data_out,
  input wire [3:0] wrport1_ctrl_add,
  input wire [31:0] wrport1_data_in,
  input wire wrport1_wren,
  input wire [3:0] wrport2_ctrl_add,
  input wire [31:0] wrport2_data_in,
  input wire wrport2_wren
);

  // 16 x 32b register file
  reg [31:0] regFile [15:0];

  // variables
  integer i = 0;

  // Read register file
  assign rdport1_data_out = regFile[rdport1_ctrl_add];
  assign rdport2_data_out = regFile[rdport2_ctrl_add];
  assign rdport3_data_out = regFile[rdport3_ctrl_add];
  assign rdport4_data_out = regFile[rdport4_ctrl_add];

  // Write register file
  always @ (posedge clk) begin
    if (rst) begin
      for (i = 0; i < 16; i = i + 1) begin
        regFile[i] <= 0;
      end
    end else begin
      if (wrport1_wren && wrport2_wren) begin
        if (wrport1_ctrl_add == wrport2_ctrl_add) begin
          // in case of write collision, we ignore write on second port
          regFile[wrport1_ctrl_add] <= wrport1_data_in;
        end else begin
          // there is no write collision and we can safely write to both wr ports
          regFile[wrport1_ctrl_add] <= wrport1_data_in;
          regFile[wrport2_ctrl_add] <= wrport2_data_in;
        end
      end else begin
        if (wrport1_wren) begin
          regFile[wrport1_ctrl_add] <= wrport1_data_in;
        end
        if (wrport2_wren) begin
          regFile[wrport2_ctrl_add] <= wrport2_data_in;
        end
      end
    end
  end
endmodule

