    input [3:0] B,
    input S,
    output [3:0] S,
    output Cout
);

    reg [3:0] temp;
    reg Cout_temp;

    always @(*) begin
        if(S == 1'b0) begin // Addition
            temp = A + B;
            Cout_temp = (temp[4] == 1) ? 1 : 0;
        end
        else begin // Subtraction
            temp = A - B;
            Cout_temp = (temp[4] == 1) ? 0 : 1;
        end
    end

    assign S = temp;
    assign Cout = Cout_temp;

endmodule

