module control_logic (
    input clk,
    input reset,
    output reg shift_enable
);

    reg [1:0] state;

    parameter IDLE = 2'b00;
    parameter ADDING = 2'b01;
    parameter SHIFTING = 2'b10;

    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            shift_enable <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    state <= ADDING;
                    shift_enable <= 1'b0;
                end
                ADDING: begin
                    state <= SHIFTING;
                    shift_enable <= 1'b1;
                end
                SHIFTING: begin
                    state <= IDLE;
                    shift_enable <= 1'b0;
                end
            endcase
        end
    end

endmodule

