module peripheral_spi_master(clk, rst, d_in, cs, addr, rd, wr, d_out, mosi, miso, sck, ss);

  // Inputs and outputs
  input clk, rst, cs, rd, wr, mosi, miso, sck, ss;
  input [3:0] addr;
  input [15:0] d_in;
  output [15:0] d_out;
  output sssd_out;

  // Registers and wires
  reg [6:0] s;
  reg [7:0] data_in = 8'h00;
  reg start = 1'b0;
  reg reset = 1'b0;
  reg sssd_in = 1'b1;
  wire [7:0] data_out;
  wire busy;
  wire new_data;

  // SPI master module
  spi_master spi_m (
    .clk(clk),
    .rst(reset),
    .sssd_in(sssd_in),
    .data_in(data_in),
    .start(start),
    .data_out(data_out),
    .busy(busy),
    .new_data(new_data),
    .miso(miso),
    .mosi(mosi),
    .sck(sck),
    .ss(ss),
    .sssd_out(sssd_out)
  );

  // Address decoder
  always @(*) begin
    case (addr)
      // Write addresses
      4'h0: s = (cs && wr) ? 7'b0000001 : 7'b0000000; // dMOSI
      4'h2: s = (cs && wr) ? 7'b0000010 : 7'b0000000; // start
      4'h4: s = (cs && wr) ? 7'b0000100 : 7'b0000000; // reset
      4'h6: s = (cs && wr) ? 7'b0001000 : 7'b0000000; // sssd_in
      // Read addresses
      4'h8: s = (cs && rd) ? 7'b0010000 : 7'b0000000; // dMISO
      4'hA: s = (cs && rd) ? 7'b0100000 : 7'b0000000; // busy
      4'hC: s = (cs && rd) ? 7'b1000000 : 7'b0000000; // new_data
      default: s = 7'b0000000;
    endcase
  end

  // Write to registers
  always @(negedge clk) begin
    data_in = (s[0]) ? d_in[7:0] : data_in; // dMISO
    start = s[1];
    reset = s[2];
    sssd_in = (s[3]) ? d_in[0] : sssd_in;
  end

  // Multiplex outputs
  always @(negedge clk) begin
    case (s[6:4])
      3'b001: d_out[7:0] = data_out; // dMOSI
      3'b010: d_out[0] = busy;
      3'b100: d_out[0] = new_data; // avail
      default: d_out = 16'h0000;
    endcase
  end

endmodule

module capture_transition (
