    input [3:0] B,
    input clk,
    input rst,
    input en,
    output [3:0] q
);
    wire EQ, GT, LT;
    wire [3:0] count;
    comparator cmp(A, B, EQ, GT, LT);
    counter ctr(rst, en, count);
    functional_module fm(EQ, GT, LT, count, A, B, q);

    always @(posedge clk) begin
        if (select) begin
            q <= q; // Hold output value
        end else begin
            q <= fm.q; // Update output value based on functional module
        end
    end
endmodule

