module uart_transmitter (
  input clk,
  input reset,
  input [7:0] data,
  input start,
  input stop,
  output reg tx
);

  reg [10:0] shift_reg;
  reg [3:0] count;

  always @(posedge clk) begin
    if (reset) begin
      shift_reg <= 11'b0;
      count <= 4'd0;
      tx <= 1'b1;
    end else if (count == 4'd0) begin
      shift_reg <= {1'b0, data, 1'b1};
      count <= 4'd1;
      tx <= start;
    end else if (count < 4'd9) begin
      shift_reg <= {shift_reg[9:0], 1'b0};
      count <= count + 1;
      tx <= shift_reg[0];
    end else begin
      shift_reg <= {shift_reg[9:0], 1'b1};
      count <= 4'd0;
      tx <= stop;
    end
  end

endmodule

module uart_receiver (
  input clk,
  input reset,
  input rx,
  output reg [7:0] data,
  output reg start,
  output reg stop
);

  reg [10:0] shift_reg;
  reg [3:0] count;

  always @(posedge clk) begin
    if (reset) begin
      shift_reg <= 11'b0;
      count <= 4'd0;
      start <= 1'b0;
      stop <= 1'b0;
      data <= 8'd0;
    end else if (count == 4'd0 && rx == 1'b0) begin
      shift_reg <= {shift_reg[9:0], rx};
      count <= 4'd1;
      start <= 1'b1;
    end else if (count < 4'd9) begin
      shift_reg <= {shift_reg[9:0], rx};
      count <= count + 1;
    end else begin
      shift_reg <= {shift_reg[9:0], rx};
      count <= 4'd0;
      stop <= 1'b1;
      data <= shift_reg[8:1];
    end
  end

endmodule

module MUX4X2(in0, in1, in2, in3, sel0, sel1, out);
input in0, in1, in2, in3, sel0, sel1;
output out;

wire w1, w2, w3;

not(nsel0, sel0);
not(nsel1, sel1);

and(a1, in0, nsel0);
and(a2, in1, sel0);
and(a3, in2, nsel1);
and(a4, in3, sel1);

or(o1, a1, a2);
or(o2, a3, a4);

or(out, o1, o2);

endmodule

module adder(
   input [3:0] A,
   input [3:0] B,
   output [3:0] C
   );

   wire [3:0] sum;
   wire carry;

   // Full adder for bit 0
   full_adder fa0(.a(A[0]), .b(B[0]), .c(1'b0), .sum(sum[0]), .carry(carry));

   // Full adder for bit 1 to 3
   genvar i;
   generate
      for (i = 1; i < 4; i = i + 1) begin : adder_loop
         full_adder fa(.a(A[i]), .b(B[i]), .c(carry), .sum(sum[i]), .carry(carry));
      end
   endgenerate

   assign C = sum;

endmodule

module full_adder(
   input a,
   input b,
   input c,
   output sum,
   output carry
   );

   assign sum = a ^ b ^ c;
   assign carry = (a & b) | (c & (a ^ b));

endmodule

module fsm_module (
    input clk, reset, softreset, cyc, we, err,
    output reg [31:0] read_out,
    output reg [31:0] write_out,
    output reg [31:0] err_out
);

localparam STATE_Initial = 3'd0,
           STATE_1 = 3'd1,
           STATE_2 = 3'd2,
           STATE_3 = 3'd3,
           STATE_4 = 3'd4,
           STATE_5 = 3'd5,
           STATE_6 = 3'd6,
           STATE_7 = 3'd7;

reg [2:0] current_state, next_state;
reg [31:0] count_read, count_write, count_error;
reg [31:0] count_read_next, count_write_next, count_error_next;

always @ (posedge clk, posedge reset) begin
    if (reset) begin
        current_state <= STATE_Initial;
        count_read <= 0;
        count_write <= 0;
        count_error <= 0;
        count_read_next <= 0;
        count_write_next <= 0;
        count_error_next <= 0;
    end else begin
        current_state <= next_state;
        count_read <= count_read_next;
        count_write <= count_write_next;
        count_error <= count_error_next;
    end
end

always @ (*) begin
    case (current_state)
        STATE_Initial: begin
            if (cyc) begin
                if (we) begin
                    next_state <= STATE_1;
                end else begin
                    next_state <= STATE_2;
                end
            end else begin
                next_state <= STATE_Initial;
            end

            if (softreset) begin
                count_read_next <= 0;
                count_write_next <= 0;
                count_error_next <= 0;
            end
        end

        STATE_1: begin
            if (err) begin
                next_state <= STATE_Initial;
                if (!softreset) begin
                    count_error_next <= count_error + 1;
                end else begin
                    count_write_next <= 0;
                    count_read_next <= 0;
                    count_error_next <= 1;
                end
            end else begin
                if (!cyc) begin
                    next_state <= STATE_Initial;
                    if (!softreset) begin
                        count_write_next <= count_write + 1;
                    end else begin
                        count_write_next <= 1;
                        count_read_next <= 0;
                        count_error_next <= 0;
                    end
                end
            end
        end

        STATE_2: begin
            if (err) begin
                next_state <= STATE_Initial;
                if (!softreset) begin
                    count_error_next <= count_error + 1;
                end else begin
                    count_write_next <= 0;
                    count_read_next <= 0;
                    count_error_next <= 1;
                end
            end else begin
                if (!cyc) begin
                    next_state <= STATE_Initial;
                    if (!softreset) begin
                        count_read_next <= count_read + 1;
                    end else begin
                        count_write_next <= 0;
                        count_read_next <= 1;
                        count_error_next <= 0;
                    end
                end
            end
        end

        STATE_3: begin
            // Placeholder for additional state
        end

        STATE_4: begin
            // Placeholder for additional state
        end

        STATE_5: begin
            // Placeholder for additional state
        end

        STATE_6: begin
            // Placeholder for additional state
        end

        STATE_7: begin
            // Placeholder for additional state
        end
    endcase
end

assign read_out = count_read;
assign write_out = count_write;
assign err_out = count_error;

endmodule

