module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

wire [3:0] sum;
wire [3:0] carry;

assign sum[0] = A[0] ^ B[0] ^ Cin;
assign carry[0] = (A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin);

assign sum[1] = A[1] ^ B[1] ^ carry[0];
assign carry[1] = (A[1] & B[1]) | (A[1] & carry[0]) | (B[1] & carry[0]);

assign sum[2] = A[2] ^ B[2] ^ carry[1];
assign carry[2] = (A[2] & B[2]) | (A[2] & carry[1]) | (B[2] & carry[1]);

assign sum[3] = A[3] ^ B[3] ^ carry[2];
assign Cout = (A[3] & B[3]) | (A[3] & carry[2]) | (B[3] & carry[2]);

assign S = sum;

endmodule

module Ethernet_MAC (
  input [7:0] tx_data,
  input [47:0] tx_dest_mac,
  input [47:0] tx_src_mac,
  input [15:0] tx_eth_type,
  input tx_sof,
  input tx_eof,
  output tx_en,
  output tx_cd,
  input rx_en,
  input [47:0] rx_mac,
  output [7:0] rx_data,
  output [47:0] rx_src_mac,
  output [47:0] rx_dest_mac,
  output [15:0] rx_eth_type
);

  // Transmitter block
  reg [7:0] tx_preamble = 8'h55; // Preamble for Ethernet frame
  reg [31:0] tx_frame; // Ethernet frame to be transmitted
  reg [31:0] tx_crc; // Cyclic redundancy check for Ethernet frame
  reg [31:0] tx_data_with_crc; // Data with CRC for transmission
  reg [7:0] tx_count = 0; // Counter for transmitting data
  reg tx_en_internal = 0; // Internal transmit enable signal
  reg tx_cd_internal = 0; // Internal collision detection signal

  always @(*) begin
    // Construct Ethernet frame
    tx_frame = {tx_preamble, tx_dest_mac, tx_src_mac, tx_eth_type, tx_data};
    // Calculate CRC
    tx_crc = $crc32(tx_frame);
    // Add CRC to data
    tx_data_with_crc = {tx_frame, tx_crc};
  end

  always @(posedge tx_sof) begin
    // Start of frame detected, enable transmission
    tx_en_internal <= 1;
    tx_count <= 0;
  end

  always @(posedge tx_eof) begin
    // End of frame detected, disable transmission
    tx_en_internal <= 0;
    tx_count <= 0;
  end

  always @(posedge tx_en_internal) begin
    // Transmit data with CRC
    if (tx_count < 64) begin
      // Transmit preamble
      tx_en <= 1;
      tx_cd_internal <= 0;
      tx_data <= 8'h55;
    end else if (tx_count < 72) begin
      // Transmit start of frame delimiter
      tx_en <= 1;
      tx_cd_internal <= 0;
      tx_data <= 8'hD5;
    end else if (tx_count < 152) begin
      // Transmit Ethernet frame
      tx_en <= 1;
      tx_cd_internal <= 0;
      tx_data <= tx_data_with_crc[tx_count-72];
    end else if (tx_count < 160) begin
      // Transmit end of frame delimiter
      tx_en <= 1;
      tx_cd_internal <= 0;
      tx_data <= 8'hD5;
    end else begin
      // Transmission complete
      tx_en <= 0;
      tx_cd_internal <= 0;
    end
    // Check for collision
    if (tx_en_internal & ~tx_en) begin
      tx_cd_internal <= 1;
    end
    // Increment counter
    tx_count <= tx_count + 1;
  end

  assign tx_cd = tx_cd_internal;

  // Receiver block
  reg [7:0] rx_data_internal; // Internal buffer for received data
  reg [47:0] rx_src_mac_internal; // Internal buffer for source MAC address
  reg [47:0] rx_dest_mac_internal; // Internal buffer for destination MAC address
  reg [15:0] rx_eth_type_internal; // Internal buffer for Ethernet type field
  reg rx_en_internal = 0; // Internal receive enable signal

  always @(posedge rx_en) begin
    // Receive enable signal detected, enable reception
    rx_en_internal <= 1;
  end

  always @(posedge rx_en_internal) begin
    // Receive data
    if ($sampled(rx_data) & $sampled(rx_src_mac) & $sampled(rx_dest_mac) & $sampled(rx_eth_type)) begin
      rx_data_internal <= rx_data;
      rx_src_mac_internal <= rx_src_mac;
      rx_dest_mac_internal <= rx_dest_mac;
      rx_eth_type_internal <= rx_eth_type;
    end
    // Check for matching MAC address
    if (rx_en_internal & (rx_dest_mac_internal == rx_mac)) begin
      // Output received data
      rx_data <= rx_data_internal;
      rx_src_mac <= rx_src_mac_internal;
      rx_dest_mac <= rx_dest_mac_internal;
      rx_eth_type <= rx_eth_type_internal;
    end
  end

endmodule

