module top_module (
    input clk,
    input up_down,
    input load,
    input [2:0] D,
    output reg [2:0] Q,
    output reg Q2,
    output reg Q1,
    output reg Q0
);

reg [2:0] counter_value;
reg [2:0] shift_register_value;

up_down_counter counter(clk, counter_value, up_down, 1'b0, Q);

shift_register_3_bit shift_register(D[0], load, clk, Q2, Q1, Q0);

always @(posedge clk) begin
    if (load) begin
        shift_register_value <= {D[2], D[1], D[0]};
        counter_value <= {D[2], D[1], D[0]};
    end else begin
        shift_register_value <= {shift_register_value[1:0], Q2};
        if (up_down) begin
            counter_value <= counter_value + 1;
        end else begin
            counter_value <= counter_value - 1;
        end
    end
end

assign Q = counter_value;

endmodule

