module axis_srl_fifo(
  input clk, rst,
  input [7:0] input_axis_tdata,
  input input_axis_tvalid, input_axis_tlast, input_axis_tuser,
  output input_axis_tready,
  output [7:0] output_axis_tdata,
  output output_axis_tvalid, output_axis_tlast, output_axis_tuser,
  input output_axis_tready,
  output [2:0] count
);

  parameter DEPTH = 4;
  parameter DATA_WIDTH = 8;

  reg [DATA_WIDTH-1:0] fifo [DEPTH-1:0];
  reg [2:0] head = 0;
  reg [2:0] tail = 0;
  reg [2:0] count_reg = 0;

  always @(posedge clk) begin
    if (rst) begin
      head <= 0;
      tail <= 0;
      count_reg <= 0;
    end else begin
      if (input_axis_tvalid && input_axis_tready) begin
        fifo[head] <= input_axis_tdata;
        head <= (head == DEPTH-1) ? 0 : head + 1;
        count_reg <= (count_reg == DEPTH) ? DEPTH : count_reg + 1;
      end
      if (output_axis_tready && count_reg > 0) begin
        output_axis_tdata <= fifo[tail];
        output_axis_tvalid <= 1;
        output_axis_tlast <= (count_reg == 1) && input_axis_tlast;
        output_axis_tuser <= input_axis_tuser;
        tail <= (tail == DEPTH-1) ? 0 : tail + 1;
        count_reg <= count_reg - 1;
      end else begin
        output_axis_tvalid <= 0;
      end
    end
    input_axis_tready <= (count_reg < DEPTH) ? 1 : 0;
    count <= count_reg;
  end

endmodule

module light_control (
  input light_sensor,
  input clk,
  input rst,
  input [7:0] brightness,
  output reg led_out
);

  // Define brightness levels
  parameter [7:0] MAX_BRIGHTNESS = 8'hFF;
  parameter [7:0] MIN_BRIGHTNESS = 8'h00;
  parameter [7:0] AMBIENT_LIGHT_HIGH = 8'h80;
  parameter [7:0] AMBIENT_LIGHT_LOW = 8'h40;

  // Define state machine states
  parameter IDLE = 2'b00;
  parameter BRIGHTEN = 2'b01;
  parameter DIM = 2'b10;

  // Define state machine signals
  reg [1:0] state;
  reg [7:0] current_brightness;

  // Map photoresistor signal to brightness levels
  always @ (posedge clk) begin
    if (light_sensor >= AMBIENT_LIGHT_HIGH) begin
      current_brightness <= MAX_BRIGHTNESS;
    end else if (light_sensor <= AMBIENT_LIGHT_LOW) begin
      current_brightness <= MIN_BRIGHTNESS;
    end else begin
      current_brightness <= brightness;
    end
  end

  // State machine to control brightness of LED
  always @ (posedge clk) begin
    if (rst) begin
      state <= IDLE;
      led_out <= 0;
    end else begin
      case (state)
        IDLE: begin
          led_out <= 0;
          if (light_sensor >= AMBIENT_LIGHT_HIGH) begin
            state <= DIM;
          end else if (light_sensor <= AMBIENT_LIGHT_LOW) begin
            state <= BRIGHTEN;
          end
        end
        BRIGHTEN: begin
          led_out <= 1;
          current_brightness <= current_brightness + 1;
          if (current_brightness >= MAX_BRIGHTNESS) begin
            state <= IDLE;
          end
        end
        DIM: begin
          led_out <= 1;
          current_brightness <= current_brightness - 1;
          if (current_brightness <= MIN_BRIGHTNESS) begin
            state <= IDLE;
          end
        end
      endcase
    end
  end

endmodule

module reset_logic (i_0r0, i_0r1, i_0a, o_0r0, o_0r1, reset);
  input [4:0] i_0r0;
  input [4:0] i_0r1;
  output i_0a;
  output [4:0] o_0r0;
  output [4:0] o_0r1;
  input reset;

  reg [4:0] r_0r0;
  reg [4:0] r_0r1;
  reg r_0a;

  always @(posedge reset or negedge reset) begin
    if (reset) begin
      r_0r0 <= 5'b0;
      r_0r1 <= 5'b0;
      r_0a <= 1'b0;
    end else begin
      r_0r0 <= i_0r0;
      r_0r1 <= i_0r1;
      r_0a <= (|i_0r0) | (|i_0r1);

      if ((i_0r0[4:2] + i_0r1[4:2]) >= (i_0r0[1:0] + i_0r1[1:0])) begin
        if ((i_0r0[4:2] - i_0r0[1:0]) > (i_0r1[4:2] - i_0r1[1:0])) begin
          r_0a <= 1'b1;
        end
      end
    end
  end

  assign o_0r0 = r_0r0;
  assign o_0r1 = r_0r1;
  assign i_0a = r_0a;

endmodule

module tone_detection (
  input audio_in,
  output tone_out
);

parameter freq = 1000; // desired tone frequency

// Define a filter to remove unwanted frequencies
// You can use any filter design method here, such as FIR or IIR
// For simplicity, we will use a low-pass filter with a cutoff frequency of 2*freq
// This will remove any frequencies above the desired tone frequency
// and preserve the frequencies below it
// Note: This filter design is not optimized and may not be suitable for all applications
// You should consult a signal processing expert for more advanced filter design techniques

reg [15:0] filter_out;
reg [15:0] filter_delay1;
reg [15:0] filter_delay2;

always @(posedge clk) begin
  filter_delay2 <= filter_delay1;
  filter_delay1 <= audio_in;
  filter_out <= (filter_delay1 + filter_delay2) >> 1;
end

// Detect the frequency of the filtered signal
// You can use any frequency detection algorithm here, such as FFT or Goertzel
// For simplicity, we will use a zero-crossing algorithm
// This algorithm counts the number of times the filtered signal crosses zero
// in a given time period, and uses this count to estimate the frequency
// Note: This frequency detection algorithm is not optimized and may not be suitable for all applications
// You should consult a signal processing expert for more advanced frequency detection techniques

reg [15:0] zero_crossings;
reg [15:0] zero_crossing_delay;

always @(posedge clk) begin
  zero_crossing_delay <= filter_out;
  if (filter_out >= 0 && zero_crossing_delay < 0) begin
    zero_crossings <= zero_crossings + 1;
  end
end

// Generate a tone signal with the same frequency as the detected frequency
// You can use any tone generation algorithm here, such as a sine wave or a square wave
// For simplicity, we will use a pulse-width modulation (PWM) technique
// This technique generates a square wave with a duty cycle proportional to the desired frequency
// Note: This tone generation algorithm is not optimized and may not be suitable for all applications
// You should consult a signal processing expert for more advanced tone generation techniques

reg [15:0] pwm_counter;
reg [15:0] pwm_threshold;

always @(posedge clk) begin
  pwm_counter <= pwm_counter + 1;
  if (pwm_counter >= pwm_threshold) begin
    tone_out <= 1;
  end else begin
    tone_out <= 0;
  end
end

always @(posedge clk) begin
  pwm_threshold <= (2**16) * freq / sample_rate;
end

endmodule

module LZW (
  input [7:0] data_in,
  input compress,
  output [max_bits-1:0] data_out,
  output [7:0] data_decomp
);

parameter max_bits = 16; // maximum number of bits for compressed data

// Define your module inputs and outputs here.

  // Define the dictionary of codes and their corresponding strings
  parameter CODE_WIDTH = $clog2(256); // 8-bit ASCII codes
  parameter MAX_CODES = 1 << CODE_WIDTH;
  parameter MAX_BITS = $clog2(MAX_CODES);
  reg [CODE_WIDTH-1:0] dictionary [0:MAX_CODES-1];
  integer num_codes = 0;
  integer code_width = 9;
  integer next_code = 256;

  // Define the compression and decompression logic
  reg [7:0] buffer [0:255];
  integer buffer_ptr = 0;
  integer buffer_len = 0;
  reg [MAX_BITS-1:0] compressed_data;
  integer compressed_ptr = 0;
  integer compressed_len = 0;
  reg [CODE_WIDTH-1:0] current_code;
  reg [CODE_WIDTH-1:0] previous_code;
  reg [8:0] current_char;
  integer i;

  always @(*) begin
    if (compress) begin
      // Compress the data_in signal using the LZW algorithm
      if (buffer_len == 0) begin
        // Initialize the dictionary with the 256 ASCII codes
        for (i = 0; i < 256; i = i + 1) begin
          dictionary[i] = i;
        end
        num_codes = 256;
        code_width = 9;
        next_code = 256;

        // Start with the first character of the input data
        current_char = data_in;
        buffer[buffer_ptr] = current_char;
        buffer_len = 1;
        buffer_ptr = buffer_ptr + 1;
      end else begin
        // Add the next character to the buffer
        current_char = data_in;
        buffer[buffer_ptr] = current_char;
        buffer_len = buffer_len + 1;
        buffer_ptr = buffer_ptr + 1;

        // Check if the current string is in the dictionary
        current_code = {previous_code, current_char};
        if (dictionary[current_code] != 0) begin
          // The current string is in the dictionary, so update the previous code
          previous_code = current_code;
        end else begin
          // The current string is not in the dictionary, so output the previous code
          compressed_data[compressed_ptr] = previous_code;
          compressed_ptr = compressed_ptr + 1;
          compressed_len = compressed_len + code_width;

          // Add the current string to the dictionary
          dictionary[current_code] = next_code;
          num_codes = num_codes + 1;
          next_code = next_code + 1;

          // Check if we need to increase the code width
          if (num_codes >= (1 << code_width)) begin
            code_width = code_width + 1;
          end

          // Update the previous code to the current character
          previous_code = current_char;
        end
      end

      // Output the compressed data if the buffer is full
      if (compressed_len >= max_bits) begin
        data_out = compressed_data;
        compressed_ptr = 0;
        compressed_len = 0;
      end
    end else begin
      // Decompress the data_in signal using the LZW algorithm
      if (compressed_len == 0) begin
        // Initialize the dictionary with the 256 ASCII codes
        for (i = 0; i < 256; i = i + 1) begin
          dictionary[i] = i;
        end
        num_codes = 256;
        code_width = 9;
        next_code = 256;

        // Start with the first code in the compressed data
        compressed_data = data_in;
        compressed_len = max_bits;
        compressed_ptr = 0;
        previous_code = compressed_data[compressed_ptr];
        compressed_ptr = compressed_ptr + 1;
        current_char = previous_code;
        data_decomp = current_char;
      end else begin
        // Get the next code from the compressed data
        current_code = compressed_data[compressed_ptr];
        compressed_ptr = compressed_ptr + 1;
        compressed_len = compressed_len - code_width;

        // Check if the current code is in the dictionary
        if (dictionary[current_code] != 0) begin
          // The current code is in the dictionary, so output its corresponding string
          current_char = dictionary[current_code];
          data_decomp = current_char;

          // Add the previous code and current character to the dictionary
          dictionary[next_code] = {previous_code, current_char};
          num_codes = num_codes + 1;
          next_code = next_code + 1;

          // Check if we need to increase the code width
          if (num_codes >= (1 << code_width)) begin
            code_width = code_width + 1;
          end

          // Update the previous code to the current code
          previous_code = current_code;
        end else begin
          // The current code is not in the dictionary, so add the previous code and current character to the dictionary
          current_char = {previous_code, previous_code[7:0]};
          data_decomp = current_char;

          dictionary[next_code] = current_char;
          num_codes = num_codes + 1;
          next_code = next_code + 1;

          // Check if we need to increase the code width
          if (num_codes >= (1 << code_width)) begin
            code_width = code_width + 1;
          end

          // Update the previous code to the current character
          previous_code = current_char[7:0];
        end
      end
    end
  end

endmodule

module uart51_tx (
    input BAUD_CLK,
    input RESET_N,
    output reg TX_DATA,
    input TX_START,
    output reg TX_DONE,
    input TX_STOP,
    input [1:0] TX_WORD,
    input TX_PAR_DIS,
    input [1:0] TX_PARITY,
    input CTS,
    input [7:0] TX_BUFFER
);

    reg [6:0] STATE;
    reg [2:0] BIT;
    wire PARITY;
    reg TX_START0;
    reg TX_START1;

    assign PARITY = (~TX_PARITY[1] & ((TX_BUFFER[0] ^ TX_BUFFER[1]) ^ (TX_BUFFER[2] ^ TX_BUFFER[3])) ^ (TX_BUFFER[4] ^ (TX_BUFFER[5] & (TX_WORD != 2'b00))) ^ ((TX_BUFFER[6] & (TX_WORD[1] == 1'b1)) ^ (TX_BUFFER[7] & (TX_WORD == 2'b11)))) ^ ~TX_PARITY[0];

    always @ (negedge BAUD_CLK or negedge RESET_N) begin
        if (!RESET_N) begin
            STATE <= 7'b0000000;
            TX_DATA <= 1'b1;
            TX_DONE <= 1'b1;
            BIT <= 3'b000;
            TX_START0 <= 1'b0;
            TX_START1 <= 1'b0;
        end else begin
            TX_START0 <= TX_START;
            TX_START1 <= TX_START0;
            case (STATE)
                7'b0000000: begin
                    BIT <= 3'b000;
                    TX_DATA <= 1'b1;
                    if (TX_START1 == 1'b1) begin
                        TX_DONE <= 1'b0;
                        STATE <= 7'b0000001;
                    end
                end
                7'b0000001: begin // Start bit
                    TX_DATA <= 1'b0;
                    STATE <= 7'b0000010;
                end
                7'b0010001: begin
                    TX_DATA <= TX_BUFFER[BIT];
                    STATE <= 7'b0010010;
                end
                7'b0100000: begin
                    BIT <= BIT + 1'b1;
                    if ((TX_WORD == 2'b00) && (BIT != 3'b111)) begin
                        STATE <= 7'b0010001;
                    end else begin
                        if ((TX_WORD == 2'b01) && (BIT != 3'b110)) begin
                            STATE <= 7'b0010001;
                        end else begin
                            if ((TX_WORD == 2'b10) && (BIT != 3'b101)) begin
                                STATE <= 7'b0010001;
                            end else begin
                                if ((TX_WORD == 2'b11) && (BIT != 3'b100)) begin
                                    STATE <= 7'b0010001;
                                end else begin
                                    if (!TX_PAR_DIS) begin
                                        STATE <= 7'b0100001; // do parity
                                    end else begin
                                        STATE <= 7'b0110001; // do stop
                                    end
                                end
                            end
                        end
                    end
                end
                // Start parity bit
                7'b0100001: begin
                    TX_DATA <= PARITY;
                    STATE <= 7'b0100010;
                end
                // start stop
                7'b0110001: begin
                    TX_DONE <= 1'b1;
                    TX_DATA <= 1'b1;
                    STATE <= 7'b0110010;
                end
                // end of first stop bit-1
                7'b0111111: begin
                    if (!TX_STOP) begin
                        STATE <= 7'b1001111; // go check for CTS
                    end else begin
                        STATE <= 7'b1000000;
                    end
                end
                7'b1001111: begin
                    if (!CTS) begin // this is not correct for a 6551
                        STATE <= 7'b0000000;
                    end
                end
                default: STATE <= STATE + 1'b1;
            endcase
        end
    end
endmodule

module top_module (
    input [15:0] A [3:0][3:0],
    input [15:0] B [3:0][3:0],
    input [1:0] shift_amount,
    input direction,
    output [15:0] E [3:0][3:0]
);

    // Matrix multiplier module
    matrix_multiplier mm (
        .A(A),
        .B(B),
        .C(C)
    );

    // Barrel shifter module
    barrel_shifter bs (
        .data_in(C),
        .shift_amount(shift_amount),
        .direction(direction),
        .data_out(D)
    );

    // Functional module
    functional_module fm (
        .C(C),
        .D(D),
        .E(E)
    );

    // Internal signals
    wire [15:0] C [3:0][3:0];
    wire [15:0] D [3:0][3:0];

endmodule

// Matrix multiplier module
module matrix_multiplier (
    input [15:0] A [3:0][3:0],
    input [15:0] B [3:0][3:0],
    output [15:0] C [3:0][3:0]
);

    genvar i, j, k;

    generate
        for (i = 0; i < 4; i = i + 1) begin : row
            for (j = 0; j < 4; j = j + 1) begin : column
                assign C[i][j] = 0;
                for (k = 0; k < 4; k = k + 1) begin : multiply
                    assign C[i][j] = C[i][j] + A[i][k] * B[k][j];
                end
            end
        end
    endgenerate

endmodule

// Barrel shifter module
module barrel_shifter (
    input [15:0] data_in [3:0][3:0],
    input [1:0] shift_amount,
    input direction,
    output [15:0] data_out [3:0][3:0]
);

    genvar i, j;

    generate
        if (direction == 0) begin : left_shift
            for (i = 0; i < 4; i = i + 1) begin : row
                for (j = 0; j < 4; j = j + 1) begin : column
                    assign data_out[i][j] = data_in[i][j] << shift_amount;
                end
            end
        end else begin : right_shift
            for (i = 0; i < 4; i = i + 1) begin : row
                for (j = 0; j < 4; j = j + 1) begin : column
                    assign data_out[i][j] = data_in[i][j] >> shift_amount;
                end
            end
        end
    endgenerate

endmodule

// Functional module
module functional_module (
    input [15:0] C [3:0][3:0],
    input [15:0] D [3:0][3:0],
    output [15:0] E [3:0][3:0]
);

    genvar i, j;

    generate
        for (i = 0; i < 4; i = i + 1) begin : row
            for (j = 0; j < 4; j = j + 1) begin : column
                assign E[i][j] = C[i][j] + D[i][j];
            end
        end
    endgenerate

endmodule

module majority_gate (
    input A, B, C, D,
    output Y
);

wire AB, AC, AD, BC, BD, CD;

assign AB = A & B;
assign AC = A & C;
assign AD = A & D;
assign BC = B & C;
assign BD = B & D;
assign CD = C & D;

assign Y = (AB | AC | AD | BC | BD | CD);

endmodule

module FixedToFloat(
    input wire CLK,
    input wire [31:0] FIXED,
    input wire EN_REG1,
    input wire EN_REGmult,
    input wire LOAD,
    input wire MS_1,
    input wire RST,
    input wire EN_REG2,
    output wire Bandcomp,
    output wire [31:0] FLOATOUT,
    output wire [7:0] Encd
);

    // Declare constants
    parameter P = 32;
    parameter W = 8;
    parameter EXP_BIAS = 127;
    parameter MANT_SIZE = 23;

    // Declare wires
    wire [31:0] fixed;
    wire [31:0] complemento;
    wire [31:0] MUXSIGN;
    wire [31:0] P_RESULT;
    wire [31:0] DESNORM;
    wire [7:0] Encoder;
    wire [31:0] mult;
    wire [31:0] FLOAT;
    wire [7:0] FLOATEXPONENT;
    wire [7:0] MUX1;
    wire [7:0] SUBT_1;
    wire [7:0] SUBT_2;
    wire [7:0] MUXSal8bits;

    // Register to store the fixed-point number
    FF_D #(.P(P)) REG_FIXED_I ( 
        .CLK(CLK), 
        .RST(RST),
        .EN(EN_REG1), 
        .D(FIXED), 
        .Q(fixed)
    );

    // Two's complement of the fixed-point number
    Complement COMPLEMENTO2 (
        .a_i(fixed),     
        .twos_comp(complemento)
    );        

    // Multiplexer to select between the fixed-point number and its two's complement
    Mux_2x1_32Bits  MUX2x1_0_I ( 
        .MS(fixed[31]), 
        .D_0(fixed), 
        .D_1(complemento), 
        .D_out(MUXSIGN)
    );    

    /*DESNORMALIZADOR DESNORMA_I(
        .CLK(CLK),
        .A(MUXSIGN),  //entrada al desnormalizador 
        .Y(DESNORM)   //salida de la desnormalizacion en coma fija, coma en el bit 56
    ); */

    // Register to store the value to be truncated
    FF_D #(.P(P)) REG_FLOAT_mult ( 
        .CLK(CLK), 
        .RST(RST),
        .EN(EN_REGmult), 
        .D(MUXSIGN), 
        .Q(mult)
    );

    // Priority encoder to find the position of the first 1 in the binary sequence
    Priority_Encoder OUTONE ( 
        .d_in(mult), 
        .d_out(Encoder)
    );         

    // Comparison to determine if the exponent is greater than 26
    Comparador_Mayor VALOR26_I(
        .CLK(CLK),
        .A(Encoder),
        .B(8'b00011010),//00011010 -- >26 
        .Out(Bandcomp)
    );

    // Barrel shifter to shift the truncated value
    Barrel_Shifter #(.SWR(32),.EWR(8)) S_REG_I(
        .clk(CLK),
        .rst(RST),
        .load_i(LOAD),
        .Shift_Value_i(MUXSal8bits),
        .Shift_Data_i(mult),
        .Left_Right_i(~Bandcomp),
        .Bit_Shift_i(1'b0),
        .N_mant_o(P_RESULT)
    );

    // Subtractor to calculate the exponent
    S_SUBT #(.P(W),.W(W)) SUBT_EXP_1_I ( 
        .A(Encoder), 
        .B(8'b00011010), 
        .Y(SUBT_1)
    );

    S_SUBT #(.P(W),.W(W)) SUBT_EXP_2_I ( 
        .A(8'b00011010), 
        .B(Encoder), 
        .Y(SUBT_2)
    );

    // Multiplexer to select between the two subtracted values
    Mux_2x1_8Bits  MUX2x1_1_I ( 
        .MS(Bandcomp), 
        .D_0(SUBT_2), 
        .D_1(SUBT_1), 
        .D_out(MUX1)
    );

    // Multiplexer to select between zero and the subtracted value
    Mux_2x1_8Bits  MUX2x1_2_I ( 
        .MS(MS_1), 
        .D_0(8'b00000000), 
        .D_1(MUX1), 
        .D_out(MUXSal8bits)
    );

    // Adder to calculate the exponent bias and encode the exponent
    ADDT_8Bits #(.P(W),.W(W))  ADDT_EXPONENTE_I ( 
        .A(Encd), 
        .B(EXP_BIAS), 
        .Y(FLOATEXPONENT)
    );

    // Assign the sign bit of the floating-point number
    assign FLOAT [31] = fixed [31];

    // Assign the exponent of the floating-point number
    assign FLOAT [30:23] = FLOATEXPONENT [7:0];  

    // Assign the mantissa of the floating-point number
    assign FLOAT [22:0] = P_RESULT[25:3];

    // Register to store the floating-point number
    FF_D #(.P(P)) REG_FLOAT ( 
        .CLK(CLK), 
        .RST(RST),
        .EN(EN_REG2), 
        .D(FLOAT), 
        .Q(FLOATOUT)
    );

endmodule

module booth_multiplier (
  input clk,
  input reset,
  input signed [15:0] a,
  input signed [15:0] b,
  output reg signed [31:0] p
);

  reg signed [15:0] a_reg;
  reg signed [15:0] b_reg;
  reg [4:0] count;
  reg [16:0] ac;
  reg [1:0] q;
  reg signed [31:0] p_reg;
  wire signed [15:0] negate_b;
  wire signed [31:0] negate_p;

  assign negate_b = ~b + 1;
  assign negate_p = ~p_reg + 1;

  always @(posedge clk) begin
    if (reset) begin
      a_reg <= 0;
      b_reg <= 0;
      count <= 0;
      ac <= 0;
      q <= 0;
      p_reg <= 0;
    end else begin
      a_reg <= a;
      b_reg <= b;
      count <= 0;
      ac <= {a_reg, 1'b0};
      q <= 2'b0;
      p_reg <= 0;
    end
  end

  always @(posedge clk) begin
    if (~reset) begin
      case (q)
        2'b01: begin
          ac <= ac + negate_b;
          q <= {ac[0], 1'b1};
        end
        2'b10: begin
          ac <= ac + b_reg;
          q <= {ac[0], 1'b0};
        end
        default: begin end
      endcase

      if (count == 15) begin
        p <= p_reg;
      end else begin
        count <= count + 1;
        {q, ac} <= {ac[0], ac >> 1};
        p_reg <= {p_reg[30:0], q[1]};
      end
    end
  end

endmodule

