module mem_compress_decompress (
  input [N-1:0] mem_in,
  input reset,
  input compress_en,
  input decompress_en,
  output [M-1:0] mem_out,
  output compress_done,
  output decompress_done
);

parameter N = 256; // size of input vector
parameter M = 128; // size of output vector
parameter K = 8; // number of bits per symbol in compressed data

// Define states for the compression and decompression state machines
localparam IDLE = 2'b00;
localparam COMPRESS = 2'b01;
localparam DECOMPRESS = 2'b10;

// Define variables for the state machines
reg [15:0] dict [0:2**K-1]; // dictionary for compression and decompression
reg [K-1:0] next_code; // next code to be added to dictionary
reg [K-1:0] current_code; // current code being processed
reg [K-1:0] previous_code; // previous code processed
reg [K-1:0] symbol; // symbol to be added to dictionary
reg [K-1:0] output_code; // code to be output
reg [15:0] output_buffer; // buffer for output codes
reg [3:0] output_bits; // number of bits in output buffer
reg [15:0] input_buffer; // buffer for input codes
reg [3:0] input_bits; // number of bits in input buffer
reg [15:0] compressed_data [0:M-1]; // compressed data output
reg [N-1:0] decompressed_data [0:M-1]; // decompressed data output
reg [1:0] state; // current state of state machine

// Define compression and decompression state machines
always @(*) begin
  case (state)
    IDLE: begin
      if (reset) begin
        next_code <= 0;
        state <= IDLE;
      end else if (compress_en) begin
        next_code <= 256;
        output_bits <= 0;
        input_bits <= 0;
        state <= COMPRESS;
      end else if (decompress_en) begin
        next_code <= 256;
        output_bits <= 0;
        input_bits <= 0;
        state <= DECOMPRESS;
      end else begin
        state <= IDLE;
      end
    end
    COMPRESS: begin
      if (reset) begin
        next_code <= 0;
        state <= IDLE;
      end else if (compress_en) begin
        if (input_bits < K) begin
          input_buffer <= {input_buffer, mem_in};
          input_bits <= input_bits + N;
        end
        if (input_bits >= K) begin
          current_code <= input_buffer[K-1:0];
          input_buffer <= input_buffer >> K;
          input_bits <= input_bits - K;
          if (previous_code == 0) begin
            symbol <= current_code;
            compressed_data[next_code-256-K] <= symbol;
            next_code <= next_code + 1;
            previous_code <= current_code;
          end else if (dict[previous_code][current_code] != 0) begin
            previous_code <= dict[previous_code][current_code];
          end else begin
            symbol <= dict[previous_code][current_code];
            compressed_data[next_code-256-K] <= symbol;
            next_code <= next_code + 1;
            dict[previous_code][current_code] <= next_code-1;
            previous_code <= current_code;
          end
        end
        if (next_code >= 2**K) begin
          output_code <= 0;
          output_bits <= 0;
          compress_done <= 1;
          state <= IDLE;
        end
      end else begin
        state <= IDLE;
      end
    end
    DECOMPRESS: begin
      if (reset) begin
        next_code <= 0;
        state <= IDLE;
      end else if (decompress_en) begin
        if (output_bits < K) begin
          output_buffer <= {output_buffer, mem_in};
          output_bits <= output_bits + M;
        end
        if (output_bits >= K) begin
          output_code <= output_buffer[K-1:0];
          output_buffer <= output_buffer >> K;
          output_bits <= output_bits - K;
          if (previous_code == 0) begin
            symbol <= output_code;
            decompressed_data[next_code] <= symbol;
            next_code <= next_code + 1;
            previous_code <= output_code;
          end else if (output_code < 256) begin
            symbol <= output_code;
            decompressed_data[next_code] <= symbol;
            next_code <= next_code + 1;
            dict[previous_code][output_code] <= next_code-1;
            previous_code <= output_code;
          end else begin
            symbol <= dict[previous_code][output_code-256];
            decompressed_data[next_code] <= symbol;
            next_code <= next_code + 1;
            dict[previous_code][output_code-256] <= next_code-1;
            previous_code <= output_code-256;
          end
        end
        if (next_code >= M) begin
          decompress_done <= 1;
          state <= IDLE;
        end
      end else begin
        state <= IDLE;
      end
    end
  endcase
end

// Assign output data based on compression or decompression
assign mem_out = (compress_en) ? compressed_data : decompressed_data;

endmodule

