module Viterbi (
  input [n-1:0] received_signal,
  output [m-1:0] decoded_signal
);

parameter k = 3; // constraint length of the convolutional code
parameter g = 3'b101; // generator polynomial of the convolutional code
parameter p = 8; // number of states in the Viterbi decoder

reg [k-1:0] state[p-1:0];
reg [k-1:0] next_state[p-1:0][1:0];
reg [k-1:0] input_bit[p-1:0][1:0];
reg [k-1:0] output_bit[p-1:0][1:0];
reg [k-1:0] path_metric[p-1:0][1:0];
reg [k-1:0] survivor[p-1:0][n-1:0];

integer i, j, l;
integer min_metric, min_index;

// Initialize state transition and output tables
always @* begin
  for (i = 0; i < p; i = i + 1) begin
    for (j = 0; j < 2; j = j + 1) begin
      next_state[i][j] = {state[i][1:k-1], j};
      input_bit[i][j] = j;
      output_bit[i][j] = g[0] ^ g[2] ^ (j & g[1]);
    end
  end
end

// Initialize path metric and survivor tables
always @* begin
  for (i = 0; i < p; i = i + 1) begin
    path_metric[i][0] = 0;
    for (j = 1; j < n; j = j + 1) begin
      path_metric[i][j] = 99999;
      survivor[i][j] = 0;
    end
  end
end

// Compute path metrics and survivors
always @* begin
  for (i = 0; i < p; i = i + 1) begin
    for (j = 0; j < 2; j = j + 1) begin
      for (l = 0; l < k; l = l + 1) begin
        if (input_bit[i][j][l] != received_signal[j*k+l]) begin
          path_metric[next_state[i][j]][j] = path_metric[next_state[i][j]][j] + 1;
        end
      end
      path_metric[next_state[i][j]][j] = path_metric[next_state[i][j]][j] + path_metric[i][0];
      if (path_metric[next_state[i][j]][j] < path_metric[survivor[next_state[i][j]][j]][j]) begin
        survivor[next_state[i][j]][j] = i;
      end
    end
  end
end

// Find the most likely path
always @* begin
  min_metric = 99999;
  for (i = 0; i < p; i = i + 1) begin
    if (path_metric[i][1] < min_metric) begin
      min_metric = path_metric[i][1];
      min_index = i;
    end
  end
  for (i = n-1; i >= 0; i = i - 1) begin
    decoded_signal[i] = output_bit[min_index][survivor[min_index][i+1]][0];
    min_index = survivor[min_index][i+1];
  end
end

// Initialize state register
always @* begin
  state[0] = 0;
  for (i = 1; i < p; i = i + 1) begin
    state[i] = state[i-1] + 1;
    if (state[i][k-1] == 1) begin
      state[i] = state[i] ^ {k{1}};
    end
  end
end

endmodule

