  reg carry_tmp;
  assign carry = carry_tmp;
  reg [WIDTH-1:0] count;
  output [WIDTH-1:0] dout;

  always @(posedge clk or posedge rst) begin
    if(rst)
      count <= 0;
    else if(clk_ena)
      if(load)
        count <= dfload;
      else if(count == MOD_COUNT-1)
        count <= 0;
      else
        count <= count+1;
  end

