module barrel_shifter (
    input [7:0] A,
    input signed [7:0] B,
    output reg [7:0] Y
);

reg [7:0] stage1_out;
reg [7:0] stage2_out;
reg [7:0] stage3_out;

always @(*) begin
    stage1_out = (B[0]) ? {A[6:0], 1'b0} : {1'b0, A[7:1]};
end

always @(*) begin
    stage2_out = (B[1]) ? {stage1_out[5:0], 2'b00} : {2'b00, stage1_out[7:2]};
end

always @(*) begin
    stage3_out = (B[2]) ? {stage2_out[3:0], 4'b0000} : {4'b0000, stage2_out[7:4]};
end

always @(*) begin
    if (B == 0) begin
        Y = A;
    end else if (B > 0 && B <= 8) begin
        Y = stage1_out;
    end else if (B > 8) begin
        Y = {A[(B-1) % 8:0], A[7:(B-1) % 8]};
    end else if (B < 0 && B >= -8) begin
        Y = stage3_out;
    end else if (B < -8) begin
        Y = {A[(-B-1) % 8:0], A[7:(-B-1) % 8]};
    end
end

endmodule

