   assign addr_remap[31:0] = {
      addr_in[29:18], //ID
      (addr_in[17:16] == 2'b00) ? 2'b00 : 2'b01, //SPECIAL GROUP
      addr_in[15:0]
   };

   assign addr_out[31:0] = (remap_en & ~remap_bypass) ? addr_remap[31:0] : addr_in[31:0];

   //stall read/write access appropriately
   always @ (posedge clk) begin
      if ((write_in & ~etx_wr_wait) | (~write_in & ~etx_rd_wait)) begin
         emesh_access_out = emesh_access_in;
         emesh_packet_out[PW-1:0] = {
            emesh_packet_in[PW-1:40],
            addr_out[31:0],
            emesh_packet_in[7:0]
         };
      end
   end

endmodule

