module Mealy (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 4; // number of input signals
parameter m = 2; // number of output signals
parameter s = 3; // number of states

reg [s-1:0] state; // current state
reg [m-1:0] output_reg; // output register

// Define the state transitions
always @ (in, state) begin
  case (state)
    0: if (in[0] && in[1]) state <= 1;
       else state <= 2;
    1: if (in[2]) state <= 0;
       else state <= 1;
    2: if (in[3]) state <= 0;
       else state <= 2;
  endcase
end

// Define the output functions for each state
always @ (state, in) begin
  case (state)
    0: output_reg = {in[0], ~in[1]};
    1: output_reg = {in[2], in[1]};
    2: output_reg = {in[3], in[0]};
  endcase
end

// Assign the output signals
assign out = output_reg;

endmodule

module env_io (/*AUTOARG*/
  // Outputs
  DI, int_n,
  // Inputs
  clk, iorq_n, rd_n, wr_n, addr, DO
  );

  input clk;
  input iorq_n;
  input rd_n;
  input wr_n;
  input [7:0] addr;
  input [7:0] DO;
  inout [7:0] DI;
  output int_n;

  reg [7:0] io_data;

  reg [7:0] str_buf [0:255];
  reg io_cs;
  integer buf_ptr, i;

  reg [7:0] timeout_ctl;
  reg [15:0] cur_timeout;
  reg [15:0] max_timeout;

  reg [7:0] int_countdown;
  reg [7:0] checksum;
  reg [7:0] ior_value;  // increment-on-read value

  assign DI = (!iorq_n & !rd_n & io_cs) ? io_data : {8{1'bz}};
  assign int_n = 1;

  initial
    begin
      io_cs = 0;
      buf_ptr = 0;
      cur_timeout = 0;
      max_timeout = 10000;
      timeout_ctl = 1;
      int_countdown = 0;
    end

  always @*
    begin
      if (!iorq_n & !rd_n)
        begin
          io_cs = (addr[7:5] == 3'b100);

          case (addr)
            8'h82 : timeout_ctl = DO;
	    8'h83 : max_timeout[7:0] = DO;
	    8'h84 : max_timeout[15:8] = DO;

	    8'h90 : int_countdown = DO;
            8'h91 : checksum = DO;
            8'h93 : ior_value = DO;
            8'h94 : begin
                     checksum = $random;
                     io_data = checksum;
                   end
            default : io_data = 8'hzz;
          endcase // case(addr)
        end // if (!iorq_n & !rd_n)
    end // always @ *

  wire wr_stb;
  reg last_iowrite;

  assign wr_stb = (!iorq_n & !wr_n);

  always @(posedge clk)
    begin
      last_iowrite <= #1 wr_stb;
      if (!wr_stb & last_iowrite)
	case (addr)
	  8'h80 :
	    begin
	      case (DO)
		1 : $finish;

		2 : begin
		      $display ("%t: ERROR   : Test failed", $time);
		      $finish;
		    end

		3 : $dumpfile ("dump.vcd");

		4 : $dumpoff;

		default :
		  begin
		    $display ("%t: ERROR   : Unknown I/O command %x", $time, DO);
		  end
	      endcase // case(DO)
	    end // case: :...

	  8'h81 :
	    begin
	      str_buf[buf_ptr] = DO;
	      buf_ptr = buf_ptr + 1;

	      //$display ("%t: DEBUG   : Detected write of character %x", $time, DO);
	      if (DO == 8'h0A)
		begin
		  $write ("%t: PROGRAM : ", $time);

		  for (i=0; i<buf_ptr; i=i+1)
		    $write ("%s", str_buf[i]);

		  buf_ptr = 0;
		end
	    end // case: 8'h81

	  8'h92 : checksum = checksum + DO;
	endcase // case(addr)
    end // always @ (posedge clk)

  always @(posedge clk)
    begin
      if (timeout_ctl[1])
	cur_timeout <= #1 0;
      else if (timeout_ctl[0])
	cur_timeout <= #1 cur_timeout + 1;

      if (cur_timeout >= max_timeout)
	begin
	  $display ("%t: ERROR   : Reached timeout %d cycles", $time, max_timeout);
	  $finish;
	end
    end // always @ (posedge clk)

  always @(posedge clk)
    begin
      if (int_countdown == 1)
	begin
	  int_n <= #1 1'b0;
	  int_countdown <= #1 0;
	end
      else if (int_countdown > 1)
        begin
	  int_countdown <= #1 int_countdown - 1;
	  int_n <= #1 1'b1;
        end
    end

endmodule

module CDR (
  input data_in,
  input clk_ref,
  output clk_out
);

  // Phase detector
  reg phase_det;
  always @(posedge clk_ref) begin
    phase_det <= data_in;
  end

  // Charge pump
  reg [1:0] charge_pump;
  always @(posedge clk_ref) begin
    if (phase_det == 1'b1) begin
      charge_pump <= 2'b01;
    end else begin
      charge_pump <= 2'b10;
    end
  end

  // Loop filter
  reg [7:0] loop_filter;
  always @(posedge clk_ref) begin
    if (charge_pump == 2'b01) begin
      loop_filter <= loop_filter + 8'h01;
    end else if (charge_pump == 2'b10) begin
      loop_filter <= loop_filter - 8'h01;
    end
  end

  // Voltage-controlled oscillator (VCO)
  reg [7:0] vco;
  always @(posedge clk_ref) begin
    vco <= vco + loop_filter;
  end

  // Jitter filter
  reg [7:0] jitter_filter;
  always @(posedge clk_ref) begin
    jitter_filter <= (jitter_filter + vco) >> 1;
  end

  // Output recovered clock
  always @(posedge clk_ref) begin
    clk_out <= jitter_filter[7];
  end

endmodule

