module top_module (
    input clk,    // Clocks are used in sequential circuits
    input reset,  // Synchronous active-high reset
    input d,      // Data input for the D flip-flop
    input [3:0] a, // 4-bit input for the adder
    input [3:0] b, // 4-bit input for the adder
    output reg q,  // Output from the D flip-flop
    output [3:0] sum, // 4-bit output from the adder
    output [3:0] even_count // 4-bit output from the even_count module
);

reg [3:0] counter;
wire even;
wire [3:0] sum_temp;

DFF dff (
    .clk(clk),
    .reset(reset),
    .d(d),
    .q(q)
);

adder_4bit adder (
    .a(a),
    .b(b),
    .sum(sum_temp),
    .carry()
);

assign sum = sum_temp;

assign even = (sum_temp[0] == 0);

and and_gate (
    .a(even),
    .b(reset),
    .y(counter[3])
);

always @(posedge clk) begin
    if (reset) begin
        counter <= 4'b0;
    end else if (even) begin
        counter <= counter + 1;
    end
end

assign even_count = counter;

endmodule

