module adder_4bit(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

wire [3:0] C;
wire [2:0] S1;
wire [3:0] S2;

// Generate the least significant bit of the sum and the corresponding carry-out signal
half_adder HA0(A[0], B[0], S[0], C[0]);

// Generate the remaining bits of the sum and the corresponding carry-out signal
full_adder FA1(A[1], B[1], C[0], S1[0], C[1]);
full_adder FA2(A[2], B[2], C[1], S1[1], C[2]);
full_adder FA3(A[3], B[3], C[2], S1[2], Cout);

// Concatenate the two sets of sum bits
assign S = {S[3:1], S1};

endmodule

