module top_module (
    input [3:0] in0,
    input [3:0] in1,
    input [7:0] in,
    output reg [2:0] out,
    output reg final_out
);

    // 4-bit comparator module
    wire eq, gt;
    comparator_4bit cmp(in0, in1, eq, gt);

    // 8-bit priority encoder module
    wire [2:0] priority;
    priority_encoder_8bit enc(in, priority);

    // Final output module
    always @(*) begin
        if (eq || gt || priority[2] || priority[1] || priority[0]) begin
            final_out = 1;
        end else begin
            final_out = 0;
        end
    end

    // Output assignment
    assign out = priority;

endmodule

// 4-bit comparator module
module comparator_4bit (
    input [3:0] in0,
    input [3:0] in1,
    output reg eq,
    output reg gt
);
    always @(*) begin
        if (in0 == in1) begin
            eq = 1;
            gt = 0;
        end else if (in0 > in1) begin
            eq = 0;
            gt = 1;
        end else begin
            eq = 0;
            gt = 0;
        end
    end
endmodule

// 8-bit priority encoder module
module priority_encoder_8bit (
    input [7:0] in,
    output reg [2:0] out
);
    always @(*) begin
        casez(in)
            8'b0000_0001: out = 3'b000;
            8'b0000_0010: out = 3'b001;
            8'b0000_0100: out = 3'b010;
            8'b0000_1000: out = 3'b011;
            8'b0001_0000: out = 3'b100;
            8'b0010_0000: out = 3'b101;
            8'b0100_0000: out = 3'b110;
            8'b1000_0000: out = 3'b111;
            default: out = 3'b000;
        endcase
    end
endmodule

