module arbiter #(
    parameter PORTS = 32,
    parameter TYPE = "ROUND_ROBIN",
    parameter BLOCK = "REQUEST"
) (
    input clk,
    input rst,
    input [PORTS-1:0] request,
    input [PORTS-1:0] acknowledge,
    output [PORTS-1:0] grant,
    output grant_valid,
    output reg [$clog2(PORTS)-1:0] grant_encoded
);

    reg [PORTS-1:0] granted;
    reg [PORTS-1:0] priority;
    reg [PORTS-1:0] round_robin_counter;
    reg [PORTS-1:0] blocked;
    reg [PORTS-1:0] release;

    assign grant = granted;
    assign grant_valid = |granted;

    always @ (posedge clk) begin
        if (rst) begin
            granted <= {PORTS{1'b0}};
            priority <= {PORTS{1'b0}};
            round_robin_counter <= {PORTS{1'b0}};
            blocked <= {PORTS{1'b0}};
            release <= {PORTS{1'b0}};
            grant_encoded <= {PORTS{1'b0}};
        end else begin
            // Release granted ports
            granted <= granted & ~release;

            // Update priority
            if (TYPE == "PRIORITY") begin
                priority <= request & ~blocked;
            end

            // Update round-robin counter
            if (TYPE == "ROUND_ROBIN") begin
                round_robin_counter <= round_robin_counter + 1;
                round_robin_counter[PORTS-1] <= ~|request;
            end

            // Grant access
            if (BLOCK == "REQUEST") begin
                if (TYPE == "PRIORITY") begin
                    if (|priority) begin
                        granted <= priority;
                        grant_encoded <= $onehot0(priority);
                    end
                end else if (TYPE == "ROUND_ROBIN") begin
                    if (|request) begin
                        granted <= {granted[PORTS-2:0], granted[0]};
                        grant_encoded <= $onehot0(granted);
                    end
                end
                blocked <= ~(granted | request);
            end else if (BLOCK == "GRANT") begin
                if (|acknowledge) begin
                    release <= acknowledge;
                end
                blocked <= ~(granted | release);
                grant_encoded <= $onehot0(granted);
            end
        end
    end

endmodule

module cordic (
   input c,
   input signed [25:0] a,
   output signed [24:0] o_cos,
   output signed [24:0] o_sin
);

   parameter NBD = 25;
   parameter SIN_EN = 1'b1;

   reg [23:0]     a0 = 0;
   reg [23:0]     a1 = 0;
   reg 		  s0 = 0;
   reg 		  s1 = 0;

   // 90 degrees - a, off by one
   wire [25:0] a_sin = (SIN_EN << (24)) + ~a;

   always @ (posedge c) begin
      a0 <= a[24] ? ~ a[23:0] : a[23:0];
      a1 <= a_sin[24] ? ~ a_sin[23:0] : a_sin[23:0];
      s0 <= a[25] ^ a[24];
      s1 <= a_sin[25] ^ a_sin[24];
   end

   wire [34:0] rd0, rd1;
   cosrom cosrom
     (.c(c), .a0(a0[23:14]), .a1(a1[23:14]), .d0(rd0), .d1(rd1));
   cosine_int #(.NBO(NBD)) cos_0
     (.c(c), .a(a0[13:0]), .rom_d(rd0), .s(s0), .o(o_cos));
   cosine_int #(.NBO(NBD)) cos_1
     (.c(c), .a(a1[13:0]), .rom_d(rd1), .s(s1), .o(o_sin));

endmodule

