  vco_output_last <= vco_output;
  vco_output <= vco_output_last + control_signal_last;
end

reg [31:0] clk_div_counter;

always @(posedge clk_in) begin
  if (clk_div_counter == clk_div - 1) begin
    clk_div_counter <= 0;
    clk_out <= ~clk_out;
  end else begin
    clk_div_counter <= clk_div_counter + 1;
  end
end

