module add_sub_edge (
    input clk,
    input [31:0] a,
    input [31:0] b,
    input sub,
    input [7:0] in,
    output [31:0] sum,
    output [7:0] anyedge_result
);

    // Adder-Subtractor Module
    wire [31:0] adder_out;
    wire [31:0] inverted_b = sub ? ~b + 1 : b;
    carry_lookahead_adder adder_inst (
        .a(a),
        .b(inverted_b),
        .cin(sub),
        .sum(adder_out)
    );

    // Edge Detection Module
    reg [7:0] prev_in;
    wire [7:0] anyedge_out;
    always @(posedge clk) begin
        anyedge_out = (in ^ prev_in) & (in ^ anyedge_result);
        prev_in <= in;
    end

    // Output Mux
    assign sum = adder_out;
    assign anyedge_result = anyedge_out ? adder_out[7:0] : 8'b0;

