    dout,
    clk,
    srst,
    din,
    rd_en,
    wr_en);
  output empty;
  output full;
  output [127:0]dout;
  input clk;
  input srst;
  input [127:0]din;
  input rd_en;
  input wr_en;

  reg [9:0] wr_ptr;
  reg [9:0] rd_ptr;
  reg [9:0] count;
  wire [9:0] next_wr_ptr;
  wire [9:0] next_rd_ptr;
  wire [9:0] next_count;
  wire [127:0] fifo [0:1023];

  assign empty = (count == 0);
  assign full = (count == 1024);
  assign dout = fifo[rd_ptr];

  always @(posedge clk) begin
