      wr_ptr <= 0;
      rd_ptr <= 0;
      count <= 0;
    end else begin
      wr_ptr <= next_wr_ptr;
      rd_ptr <= next_rd_ptr;
      count <= next_count;
    end
  end

  assign next_wr_ptr = (wr_en && !full) ? wr_ptr + 1 : wr_ptr;
  assign next_rd_ptr = (rd_en && !empty) ? rd_ptr + 1 : rd_ptr;
  assign next_count = count + (wr_en && !full) - (rd_en && !empty);

  assign fifo[wr_ptr] = din;

