// DCT block
reg [n-1:0] dct_out;
genvar i, j;
generate
  for (i = 0; i < block_size; i = i + 1) begin : dct_rows
    for (j = 0; j < block_size; j = j + 1) begin : dct_cols
      assign dct_out[i] = dct_out[i] + in[j] * cos((2 * i + 1) * j * pi / (2 * block_size));
    end
    assign dct_out[i] = dct_out[i] * sqrt(2.0 / block_size);
    if (i == 0) begin
      assign dct_out[i] = dct_out[i] / sqrt(2);
    end
  end
endgenerate

// IDCT block
reg [m-1:0] idct_out;
genvar k, l;
generate
  for (k = 0; k < block_size; k = k + 1) begin : idct_rows
    for (l = 0; l < block_size; l = l + 1) begin : idct_cols
      assign idct_out[k] = idct_out[k] + dct_out[l] * cos((2 * k + 1) * l * pi / (2 * block_size));
    end
    assign idct_out[k] = idct_out[k] * sqrt(2.0 / block_size);
    if (k == 0) begin
      assign idct_out[k] = idct_out[k] / sqrt(2);
    end
  end
endgenerate

// connect inputs and outputs
assign out = idct_out;
assign dct_out = in;

endmodule

