module rc4(ready, k, clk, rst, keyinput, need);
  // parameters
  parameter keylength = 8;

  // outputs
  output reg ready; // enable when generate prga
  output reg [7:0] k; // value extracts from stream

  // inputs
  input clk;
  input rst;
  input [7:0] keyinput; // one byte of key per cycle
  input need;

  // internal
  reg [7:0] key[0:keylength-1];

  reg [3:0] state;

  reg [7:0] stream[0:255];
  reg [7:0] stream_temp;

  reg [7:0] i;
  reg [7:0] j;

  reg [7:0] tmp;

  initial begin
    ready = 1;

    state = 0;

    i = 8'h00;
    j = 8'h00;
  end

  always @ (posedge clk) begin
    if (rst) begin
      ready = 0;

      state = 0;

      i = 8'h00;
      j = 8'h00;
    end

    case (state)
      // read key every cycle until key length
      0: begin
        if (i == keylength) begin
          state = 1;
          i = 8'h00;
        end else begin
          key[i] = keyinput;
          i = i + 8'h01;
        end
      end

      // KSA 1
      // initialize stream
      1: begin
        stream[i] = i;
        if (i == 8'hff) begin
          state = 2;
          i = 8'h00;
        end else begin
          i = i + 8'h01;
        end
      end

      // KSA 2
      // calculate j for use in next cycle
      2: begin
        state = 3;
        stream_temp = stream[i];
        j = j + stream[i] + key[i % keylength];
      end

      // KSA 3
      // swap values in stream
      3: begin
        stream[i] = stream[j];
        stream[j] = stream_temp;

        if (i == 8'hff) begin
          // ready to use prga
          state = 4;

          i = 8'h01;
          j = stream[1];
        end else begin
          state = 2;
          i = i + 8'h01;
        end
      end

      4: begin
        if (need) state = 5;
      end

      // PRGA 1
      // save data for swap
      5: begin
        ready = 0;
        state = 6;
        stream_temp = stream[i];
      end

      // PRGA 2
      // swap values in stream
      6: begin    
        state = 7;

        stream[i] = stream[j];
        stream[j] = stream_temp;

        tmp = stream[i] + stream[j];
      end

      // PRGA 3
      // take k and then output
      7: begin
        ready = 1;
        k = stream[tmp];

        state = 5;

        if (i == 8'hff) j = j + stream[0];
        else j = j + stream[i + 1];
        i = i + 1;
      end

      default: begin
      end
    endcase
  end
endmodule

