    output [3:0] w,
    output [7:0] x,
    output [7:0] y,
    output [7:0] z,
    output [7:0] final_out
);

    // Control logic for selecting between 4:1 multiplexer and splitter
    wire [1:0] select_decoded;
    assign select_decoded = select ? 2'b01 : 2'b10; // 01 for multiplexer, 10 for splitter

    // Instantiate 4:1 multiplexer module
    wire [3:0] mux_out;
    mux_4to1 mux_inst (
        .a(a),
        .b(b),
        .c(c),
        .sel(select_decoded[0]),
        .w(mux_out)
    );

    // Instantiate splitter module
    wire [7:0] splitter_out_hi;
    wire [7:0] splitter_out_lo;
    splitter_16to8 splitter_inst (
        .in(in),
        .out_hi(splitter_out_hi),
        .out_lo(splitter_out_lo)
    );

    // Instantiate functional module for bitwise OR operation
    wire [7:0] or_out;
    bitwise_or or_inst (
        .a(mux_out),
        .b(splitter_out_lo),
        .out(or_out)
    );

    // Assign outputs
    assign out_hi = splitter_out_hi;
    assign out_lo = splitter_out_lo;
    assign w = mux_out;
    assign x = select_decoded[0] ? 8'b0 : splitter_out_hi;
    assign y = select_decoded[0] ? (select_decoded[1] ? 8'b0 : b) : 8'b0;
    assign z = select_decoded[0] ? (select_decoded[1] ? 8'b0 : c) : 8'b0;
    assign final_out = or_out;

endmodule

