module top_module (
    input clk,
    input reset, // Synchronous active-high reset
    input [3:1] ena, // Asynchronous enable signals for tens, hundreds, and thousands digits
    input [7:0] in, // Input vector for priority encoder
    output reg [10:0] out // 11-bit output combining BCD counter and priority encoder
);

reg [3:0] ones_digit; // Register for ones digit of BCD counter
reg [3:0] tens_digit; // Register for tens digit of BCD counter
reg [3:0] hundreds_digit; // Register for hundreds digit of BCD counter
reg [3:0] thousands_digit; // Register for thousands digit of BCD counter
reg [2:0] priority; // Register for priority encoder output

// BCD counter logic
always @(posedge clk, posedge reset) begin
    if (reset) begin
        ones_digit <= 4'b0000;
        tens_digit <= 4'b0000;
        hundreds_digit <= 4'b0000;
        thousands_digit <= 4'b0000;
    end else begin
        ones_digit <= ones_digit + 1;
        if (ena[0]) begin
            tens_digit <= tens_digit + 1;
        end
        if (ena[1]) begin
            hundreds_digit <= hundreds_digit + 1;
        end
        if (ena[2]) begin
            thousands_digit <= thousands_digit + 1;
        end
    end
end

// Priority encoder logic
always @(in) begin
    casez(in)
        8'b00000001: priority <= 3'b000;
        8'b00000010: priority <= 3'b001;
        8'b00000100: priority <= 3'b010;
        8'b00001000: priority <= 3'b011;
        8'b00010000: priority <= 3'b100;
        8'b00100000: priority <= 3'b101;
        8'b01000000: priority <= 3'b110;
        8'b10000000: priority <= 3'b111;
        default: priority <= 3'b000;
    endcase
end

// Output logic
always @(ones_digit, tens_digit, hundreds_digit, thousands_digit, priority) begin
    out[7:4] = {thousands_digit, hundreds_digit, tens_digit, ones_digit};
    out[10:8] = priority;
    out[0] = 1'b0;
end

endmodule

