  output [22:0] D;
  input [0:0] Q;
  input CLK;
  input [0:0] AR;
  input Overflow_flag_A;

  wire [45:0] Q_reg_next;
  wire [22:0] D;
  wire [0:0] Q;
  wire CLK;
  wire [0:0] AR;
  wire Overflow_flag_A;

  // Implement multiplication using a series of shifts and adds
  wire [45:0] product;
  assign product = {23'b0, D} << Q;

  // Implement overflow detection
  wire overflow;
  assign overflow = product[45] ^ Overflow_flag_A;

  // Implement synchronous reset
  always @(posedge CLK) begin
    if (AR) begin
      Q_reg <= 0;
    end else begin
      Q_reg <= Q_reg_next;
    end
  end

  // Implement combinational logic
  always @(*) begin
    if (overflow) begin
      Q_reg_next[45] = 1;
      Q_reg_next[44:0] = 0;
    end else begin
      Q_reg_next = product;
    end
  end

endmodule

module fifo(
  clk,
  rst,
  din,
  wr_en,
  rd_en,
  dout,
  full,
  empty
);

parameter DEPTH = 16;

input clk;
input rst;
input [7 : 0] din;
input wr_en;
input rd_en;
output [7 : 0] dout;
output full;
output empty;

reg [7:0] mem [0:DEPTH-1];
reg [3:0] wr_ptr = 0;
reg [3:0] rd_ptr = 0;
reg [3:0] count = 0;

assign full = (count == DEPTH);
assign empty = (count == 0);

always @(posedge clk or posedge rst) begin
  if (rst) begin
    wr_ptr <= 0;
    rd_ptr <= 0;
    count <= 0;
  end else begin
    if (wr_en && !full) begin
      mem[wr_ptr] <= din;
      wr_ptr <= wr_ptr + 1;
      count <= count + 1;
    end
    if (rd_en && !empty) begin
      dout <= mem[rd_ptr];
      rd_ptr <= rd_ptr + 1;
      count <= count - 1;
    end
  end
end

endmodule

module binary_to_gray (
  input [3:0] binary,
  output reg [3:0] gray
);

  always @* begin
    gray[3] = binary[3];
    gray[2] = binary[3] ^ binary[2];
    gray[1] = binary[2] ^ binary[1];
    gray[0] = binary[1] ^ binary[0];
  end

endmodule

module barrel_shifter_priority_encoder_or (
    input clk,
    input load,
    input [1:0] ena,
    input [7:0] in,
    input [99:0] data,
    output reg [7:0] out
);

reg [99:0] shifted_data;
reg [7:0] priority_encoded;
reg [2:0] highest_bit_pos;

always @(posedge clk) begin
    if (load) begin
        shifted_data <= data;
    end else begin
        if (ena[0] && ena[1]) begin
            shifted_data <= {data[99], data[98:0]};
        end else if (ena[0]) begin
            shifted_data <= {data[98:0], data[99]};
        end else if (ena[1]) begin
            shifted_data <= {data[0], data[99:1]};
        end
    end
end

always @* begin
    priority_encoded = 8'b00000000;
    if (shifted_data[99]) begin
        priority_encoded = 8'b10000000;
        highest_bit_pos = 3'b111;
    end else if (shifted_data[98]) begin
        priority_encoded = 8'b01000000;
        highest_bit_pos = 3'b110;
    end else if (shifted_data[97]) begin
        priority_encoded = 8'b00100000;
        highest_bit_pos = 3'b101;
    end else if (shifted_data[96]) begin
        priority_encoded = 8'b00010000;
        highest_bit_pos = 3'b100;
    end else if (shifted_data[95]) begin
        priority_encoded = 8'b00001000;
        highest_bit_pos = 3'b011;
    end else if (shifted_data[94]) begin
        priority_encoded = 8'b00000100;
        highest_bit_pos = 3'b010;
    end else if (shifted_data[93]) begin
        priority_encoded = 8'b00000010;
        highest_bit_pos = 3'b001;
    end else if (shifted_data[92]) begin
        priority_encoded = 8'b00000001;
        highest_bit_pos = 3'b000;
    end
end

always @* begin
    out = priority_encoded | in;
end

endmodule

module sd_clock_divider (
           input CLK,
           input [7:0] DIVIDER,
           input RST,
           output reg SD_CLK
       );

reg [7:0] counter;

always @(posedge CLK or posedge RST)
begin
    if (RST) begin
        counter <= 8'b0000_0000;
        SD_CLK <= 0;
    end
    else if (counter == DIVIDER) begin
        counter <= 0;
        SD_CLK <= ~SD_CLK;
    end else begin
        counter <= counter + 8'h1;
    end
end

assign SD_CLK = (counter >= DIVIDER/2) ? 1'b0 : 1'b1;

endmodule

module top_module (
    input [7:0] in,
    output reg [2:0] pos
);

reg [2:0] pos_next;
wire highest_bit_detected;

// Combinational logic for detecting the highest bit
assign highest_bit_detected = (in[7] || in[6] || in[5] || in[4] || in[3] || in[2] || in[1] || in[0]);

always @(*) begin
    if (in[7]) pos_next = 3'b111;
    else if (in[6]) pos_next = 3'b110;
    else if (in[5]) pos_next = 3'b101;
    else if (in[4]) pos_next = 3'b100;
    else if (in[3]) pos_next = 3'b011;
    else if (in[2]) pos_next = 3'b010;
    else if (in[1]) pos_next = 3'b001;
    else if (in[0]) pos_next = 3'b000;
    else pos_next = 3'b000;
end

// Sequential logic for updating the output register
always @(posedge highest_bit_detected) begin
    pos <= pos_next;
end

endmodule

module top_module (
    input [3:0] in0, in1, in2, in3, // Four 4-bit binary inputs
    output reg [7:0] O // 8-bit output of the one-hot code of the selected input
);

    // Priority encoder to select input with highest priority
    wire [3:0] priority;
    priority_encoder_4to2 encoder(
        .in({in3, in2, in1, in0}),
        .out(priority)
    );

    // Multiplexer to select input based on priority
    wire [3:0] selected_input;
    mux4to1_priority mux(
        .in0(in0),
        .in1(in1),
        .in2(in2),
        .in3(in3),
        .sel(priority),
        .out(selected_input)
    );

    // One-hot code converter to convert selected input to one-hot code
    wire [7:0] one_hot_code;
    binary_to_one_hot_converter_4bit_to_8bit converter(
        .in(selected_input),
        .out(one_hot_code)
    );

    // Final output module to output one-hot code of selected input
    always @(*) begin
        O = one_hot_code;
    end

endmodule

// 4-to-2 priority encoder module
module priority_encoder_4to2 (
    input [3:0] in, // Four 4-bit binary inputs
    output reg [1:0] out // 2-bit output of the highest priority input
);
    always @(*) begin
        case(in)
            4'b0001: out = 2'b00;
            4'b0010: out = 2'b01;
            4'b0100: out = 2'b10;
            4'b1000: out = 2'b11;
            default: out = 2'b00;
        endcase
    end
endmodule

// 4-to-1 priority encoder multiplexer module
module mux4to1_priority (
    input [3:0] in0, in1, in2, in3, // Four 4-bit binary inputs
    input [1:0] sel, // 2-bit input to select input based on priority
    output reg [3:0] out // 4-bit output of the selected input
);
    always @(*) begin
        case(sel)
            2'b00: out = in0;
            2'b01: out = in1;
            2'b10: out = in2;
            2'b11: out = in3;
            default: out = in0;
        endcase
    end
endmodule

// 4-bit binary to one-hot code converter module
module binary_to_one_hot_converter_4bit_to_8bit (
    input [3:0] in, // 4-bit binary input
    output reg [7:0] out // 8-bit output of the one-hot code of the input
);
    always @(*) begin
        case(in)
            4'b0001: out = 8'b00000001;
            4'b0010: out = 8'b00000010;
            4'b0100: out = 8'b00000100;
            4'b1000: out = 8'b00001000;
            default: out = 8'b00000000;
        endcase
    end
endmodule

module delay_gen150us (
