    output Q_N,
    input  RESET_B,
    input  CLK,
    input  VPB,
    input  VPWR,
    input  VGND,
    input  VNB
);

    reg Q_reg, Q_N_reg;

    always @(posedge CLK or negedge RESET_B) begin
        if (!RESET_B) begin
            Q_reg <= 0;
            Q_N_reg <= 1;
        end else if (D) begin
            Q_reg <= 1;
