endmodule

module bin2bcd #(parameter IN_BITS = 8,
                 parameter OUT_BITS = 10)
            (input wire [IN_BITS-1:0] bin_number,
             output wire [OUT_BITS-1:0] bcd_number);

    genvar bits_shifted;
    generate
        for (bits_shifted = 3; bits_shifted < IN_BITS; bits_shifted = bits_shifted + 3) begin : gen
            wire [IN_BITS + bits_shifted / 3 - 1 : 0] out_wires;

            if(bits_shifted == 3) begin
                // First adder, shift in the 3 most significant bits
                add3gt4_n #(bits_shifted / 3) add3n(
                    {1'b0, bin_number[IN_BITS - 1 : IN_BITS - 3]},
                    out_wires[IN_BITS : IN_BITS - 3]
                );
                assign out_wires[IN_BITS - 4: 0] = bin_number[IN_BITS - 4:0];
            end else begin
                // Subsequent adders, shift in the next 3 most significant bits
                add3gt4_n #(bits_shifted / 3) add3n(
                    {1'b0, gen[bits_shifted / 3 - 1].out_wires[IN_BITS + bits_shifted / 3 - 1 - 2 : IN_BITS + bits_shifted / 3 - 4]},
                    out_wires[IN_BITS + bits_shifted / 3 - 1 : IN_BITS + bits_shifted / 3 - 4]
                );
                assign out_wires[IN_BITS + bits_shifted / 3 - 4: 0] = gen[bits_shifted / 3 - 1].out_wires[IN_BITS + bits_shifted / 3 - 5 : 0];
            end
        end
    endgenerate

    // Assign the output to the last adder's output wires
    assign bcd_number = gen[IN_BITS / 3 - 1].out_wires[OUT_BITS - 1:0];

endmodule

