module nor_and_gate (
    input A, B, C_N, D_N, VPWR, VGND,
    output Y
);

    // Local signals
    wire nor_out;
    wire and_out;
    wire u_vpwr_vgnd_out;

    // NOR gate
    nor nor_gate (
        .A(A),
        .B(B),
        .Y(nor_out)
    );

    // AND gate
    and and_gate (
        .A(nor_out),
        .B(C_N),
        .C(D_N),
        .Y(and_out)
    );

    // Voltage-power-ground module
    sky130_fd_sc_hs__u_vpwr_vgnd vpwr_gnd (
        .Y(u_vpwr_vgnd_out),
        .VPWR(VPWR),
        .VGND(VGND),
        .A(and_out)
    );

    // Output buffer
    buf buf_gate (
        .A(u_vpwr_vgnd_out),
        .Y(Y)
    );

endmodule

