module gtwizard_ultrascale_v1_7_1_bit_synchronizer # (

  parameter INITIALIZE = 5'b00000,
  parameter FREQUENCY  = 512

)(

  input  wire clk_in,
  input  wire i_in,
  output wire o_out

);

  // Use 5 flip-flops as a single synchronizer, and tag each declaration with the appropriate synthesis attribute to
  // enable clustering. Their GSR default values are provided by the INITIALIZE parameter.

  (* ASYNC_REG = "TRUE" *) reg i_in_meta  = INITIALIZE[0];
  (* ASYNC_REG = "TRUE" *) reg i_in_sync1 = INITIALIZE[1];
  (* ASYNC_REG = "TRUE" *) reg i_in_sync2 = INITIALIZE[2];
  (* ASYNC_REG = "TRUE" *) reg i_in_sync3 = INITIALIZE[3];
                           reg i_in_out   = INITIALIZE[4];

  always @(posedge clk_in) begin
    i_in_meta  <= i_in;
    i_in_sync1 <= i_in_meta;
    i_in_sync2 <= i_in_sync1;
    i_in_sync3 <= i_in_sync2;
    i_in_out   <= i_in_sync3;
  end

  assign o_out = i_in_out;


endmodule

module top_module (
    input [7:0] a,
    input [7:0] b,
    output [7:0] s,
    output overflow
);

    wire [7:0] adder_out;
    wire [7:0] full_adder_out;
    wire carry_out;

    // Instantiate the 8-bit 2's complement adder
    eight_bit_adder adder(
        .a(a),
        .b(b),
        .s(adder_out),
        .carry_out(carry_out)
    );

    // Instantiate the full adder
    full_adder full_adder_inst(
        .a(a[0]),
        .b(b[0]),
        .carry_in(1'b0),
        .sum(full_adder_out[0]),
        .carry_out(carry_out)
    );

    // Generate the carry look-ahead logic
    genvar i;
    generate
        for (i = 1; i < 8; i = i + 1) begin : carry_lookahead
            assign carry_out = (a[i] & b[i]) | (a[i] & carry_out) | (b[i] & carry_out);
        end
    endgenerate

    // Instantiate the control logic module
    control_logic control_inst(
        .a(a),
        .b(b),
        .adder_out(adder_out),
        .full_adder_out(full_adder_out),
        .s(s),
        .overflow(overflow)
    );

endmodule


module eight_bit_adder (
    input [7:0] a,
    input [7:0] b,
    output [7:0] s,
    output carry_out
);

    wire [7:0] sum;
    wire [7:0] carry;

    // Generate the carry look-ahead logic
    genvar i;
    generate
        for (i = 0; i < 8; i = i + 1) begin : carry_lookahead
            assign carry[i] = (a[i] & b[i]) | (a[i] & carry[i-1]) | (b[i] & carry[i-1]);
        end
    endgenerate

    // Generate the full adder logic
    genvar j;
    generate
        for (j = 0; j < 8; j = j + 1) begin : full_adder
            full_adder full_adder_inst(
                .a(a[j]),
                .b(b[j]),
                .carry_in(carry[j]),
                .sum(sum[j]),
                .carry_out(carry[j+1])
            );
        end
    endgenerate

    assign s = sum;
    assign carry_out = carry[8];

endmodule


module full_adder (
    input a,
    input b,
    input carry_in,
    output sum,
    output carry_out
);

    assign sum = a ^ b ^ carry_in;
    assign carry_out = (a & b) | (a & carry_in) | (b & carry_in);

endmodule


module control_logic (
    input [7:0] a,
    input [7:0] b,
    input [7:0] adder_out,
    input [7:0] full_adder_out,
    output [7:0] s,
    output overflow
);

    wire [7:0] twos_complement;
    wire [7:0] neg_b;

    // Calculate the two's complement of b
    assign neg_b = ~b + 1;

    // Select the active output based on the sign of b
    assign s = (b[7] == 1'b0) ? adder_out : full_adder_out;
    assign twos_complement = (b[7] == 1'b0) ? b : neg_b;

    // Detect overflow using the full adder
    full_adder full_adder_inst(
        .a(a[7]),
        .b(twos_complement[7]),
        .carry_in(1'b0),
        .sum(),
        .carry_out(overflow)
    );

endmodule

