module CAM (
  input [n-1:0] data_in,
  input [m-1:0] search_key,
  output match,
  output [n-1:0] data_out
);

parameter n = 8; // number of bits in data
parameter m = 4; // number of bits in search key

reg [n-1:0] stored_data;
