module schmitt_trigger (
  input in,
  input Vt_high,
  input Vt_low,
  input Vdd,
  output out
);

  reg out_reg;
  reg prev_out_reg;

  always @ (in or prev_out_reg)
  begin
    if (prev_out_reg == 1'b0 && in >= Vt_high)
      out_reg = 1'b1;
    else if (prev_out_reg == 1'b1 && in <= Vt_low)
      out_reg = 1'b0;
    else
      out_reg = prev_out_reg;
  end

  assign out = out_reg;

  always @ (posedge Vdd)
  begin
    prev_out_reg <= out_reg;
  end

endmodule

module add_sub_up_down (
    input load,
    input reset,
    input count_up,
    input count_down,
    input [3:0] a,
    input [3:0] b,
    input mode,
    output [3:0] count_out
);

    wire [3:0] add_sub_out;
    wire [3:0] counter_out;

    add_sub add_sub_inst(
        .a(a),
        .b(b),
        .mode(mode),
        .result(add_sub_out)
    );

    up_down_counter up_down_counter_inst(
        .load(load),
        .reset(reset),
        .count_up(count_up),
        .count_down(count_down),
        .count_out(counter_out)
    );

    always @(*) begin
        if (mode == 1'b0) begin
            up_down_counter_inst.count_up = count_up;
            up_down_counter_inst.count_down = count_down;
        end else begin
            up_down_counter_inst.count_up = count_down;
            up_down_counter_inst.count_down = count_up;
        end
    end

    result_module result_inst(
        .add_sub_out(add_sub_out),
        .counter_out(counter_out),
        .count_out(count_out)
    );

endmodule

module add_sub (
    input [3:0] a,
    input [3:0] b,
    input mode,
    output [3:0] result
);

    assign result = (mode == 1'b0) ? a + b : a - b;

endmodule

module up_down_counter (
    input load,
    input reset,
    input count_up,
    input count_down,
    output reg [3:0] count_out
);

    always @(posedge count_up, posedge count_down, posedge load, posedge reset) begin
        if (reset) begin
            count_out <= 4'b0000;
        end else if (load) begin
            count_out <= 4'b0000;
        end else if (count_up) begin
            count_out <= count_out + 1;
        end else if (count_down) begin
            count_out <= count_out - 1;
        end
    end

endmodule

module result_module (
    input [3:0] add_sub_out,
    input [3:0] counter_out,
    output reg [3:0] count_out
);

    always @(*) begin
        count_out = add_sub_out + counter_out;
    end

endmodule

module consecutive_ones (
    in_signal,
    out_signal
);

input [3:0] in_signal;
output [1:0] out_signal;

reg [1:0] count;
reg prev_bit;

always @ (in_signal) begin
    count = 2'b00;
    prev_bit = 1'b0;
    for (i = 0; i < 4; i = i + 1) begin
        if (in_signal[i] == 1'b1 && prev_bit == 1'b1) begin
            count = count + 1;
        end
        prev_bit = in_signal[i];
    end
    out_signal = count;
end

endmodule

