module adder4 (
    input [3:0] A,
    input [3:0] B,
    input C_in,
    output [3:0] S,
    output C_out
);

    wire [3:0] sum;
    wire carry1;
    wire carry2;
    wire carry3;

    // 1's complement of A
    assign A_not = ~A;

    // 1's complement of B
    assign B_not = ~B;

    // 1's complement of carry-in
    assign C_in_not = ~C_in;

    // First stage: add A and B, and invert the result
    full_adder FA1(sum[0], A_not[0], B_not[0], C_in_not);
    full_adder FA2(sum[1], A_not[1], B_not[1], FA1.carry);
    full_adder FA3(sum[2], A_not[2], B_not[2], FA2.carry);
    full_adder FA4(sum[3], A_not[3], B_not[3], FA3.carry);

    // Second stage: add the inverted sum and carry-in, and invert the result
    full_adder FA5(S[0], sum[0], C_in_not, 1'b0);
    full_adder FA6(S[1], sum[1], FA5.carry, 1'b0);
    full_adder FA7(S[2], sum[2], FA6.carry, 1'b0);
    full_adder FA8(S[3], sum[3], FA7.carry, 1'b0);

    // Third stage: calculate the carry-out
    or(C_out, FA4.carry, FA8.carry);

endmodule

module full_adder (
    output sum,
    input A,
    input B,
    input C_in
);

    wire xor1;
    wire xor2;
    wire and1;
    wire and2;

    // XOR gate for the sum
    xor(xor1, A, B);
    xor(sum, xor1, C_in);

    // AND gate for the carry
    and(and1, A, B);
    and(and2, xor1, C_in);
    or(carry, and1, and2);

endmodule

module spi_master #(
    parameter CLK_DIVIDE=3 // divide clk by 2^CLK_DIVIDE to get spi_sclk
) (
    input clk, // 50 MHz system clk
    input reset,

    input spi_start,
    input [7:0] spi_data,
    output spi_fin,

    output spi_csn,
    output spi_sdo,
    output spi_sclk // max 10 MHz clk
);

`define SPI_MASTER_SM_W 2

localparam STATE_IDLE = `SPI_MASTER_SM_W'h0;
localparam STATE_SEND = `SPI_MASTER_SM_W'h1;
localparam STATE_HOLD = `SPI_MASTER_SM_W'h2;
localparam STATE_DONE = `SPI_MASTER_SM_W'h3;

reg [`SPI_MASTER_SM_W-1:0] spi_sm_state;
reg [CLK_DIVIDE-1:0] clk_divider;
reg [7:0] spi_data_shift;
reg [2:0] shift_counter;

assign spi_csn = ((spi_sm_state==STATE_IDLE) && (spi_start==1'b0)) ? 1'b1 : 1'b0;
assign spi_sdo = spi_data_shift[7];
assign spi_sclk = ((spi_sm_state==STATE_SEND) && (clk_divider[CLK_DIVIDE-1]==1'b1)) ? 1'b1 : 1'b0;

assign spi_fin = (spi_sm_state==STATE_DONE) ? 1'b1 : 1'b0;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        spi_sm_state <= STATE_IDLE;  
        spi_data_shift <= 'b0;
        clk_divider <= 'b0;
        shift_counter <= 'b0;
    end else begin
        case (spi_sm_state)
            STATE_IDLE: begin
                if (spi_start==1'b1) begin
                    spi_sm_state <= STATE_SEND;
                    spi_data_shift <= spi_data;
                    clk_divider <= 'b0;
                    shift_counter <= 'b0;
                end
            end
            STATE_SEND: begin
                clk_divider <= clk_divider + 1;
                if (clk_divider == {CLK_DIVIDE{1'b1}}) begin
                    shift_counter <= shift_counter + 1;
                    spi_data_shift <= {spi_data_shift[6:0], 1'b0};
                    if (shift_counter==3'b111) begin
                        spi_sm_state <= STATE_HOLD;
                    end
                end
            end
            STATE_HOLD: begin
                clk_divider <= clk_divider + 1;
                if (clk_divider == {CLK_DIVIDE{1'b1}}) begin
                    spi_sm_state <= STATE_DONE;
                end
            end
            STATE_DONE: begin
                if (spi_start==1'b0) begin
                    spi_sm_state <= STATE_IDLE;
                end
            end
            default:
                spi_sm_state <= STATE_IDLE;

        endcase
    end
end

endmodule

