module sineTable #(
    parameter ANGLE_WIDTH = 12,
    parameter OUT_WIDTH   = 18
) (
    input  wire clk,                        ///< System Clock
    input  wire [ANGLE_WIDTH-1:0] angle,    ///< Angle to take sine of
    output reg signed [OUT_WIDTH-1:0] sine ///< Sine of angle
);

///////////////////////////////////////////////////////////////////////////
// PARAMETER AND SIGNAL DECLARATIONS
///////////////////////////////////////////////////////////////////////////

localparam TABLE_LEN = 2**(ANGLE_WIDTH-2);

wire [ANGLE_WIDTH-3:0] quarterAngle;

reg [OUT_WIDTH-2:0] sineTable [TABLE_LEN-1:0];
reg signBit;
reg [OUT_WIDTH-2:0] halfSine;

integer i;

///////////////////////////////////////////////////////////////////////////
// MAIN CODE
///////////////////////////////////////////////////////////////////////////

assign quarterAngle = (angle[ANGLE_WIDTH-2]) ? ~angle[ANGLE_WIDTH-3:0] : angle[ANGLE_WIDTH-3:0];

initial begin
    signBit  = 1'b0;
    halfSine = 'd0;
    sine     = 'd0;
    for(i=0; i<TABLE_LEN; i=i+1) begin
        sineTable[i] = $rtoi($floor($sin((i+0.5)*3.14159/(TABLE_LEN*2))*(2**(OUT_WIDTH-1)-1)+0.5));
    end
end

always @(posedge clk) begin
    signBit  <= angle[ANGLE_WIDTH-1]; 
    halfSine <= sineTable[quarterAngle];
    sine     <= signBit ? -$signed({1'b0,halfSine}) : $signed({1'b0, halfSine});
end

endmodule

module axi_stream_gpio (
        ap_clk,
        ap_rst_n,
        ap_start,
        ap_done,
        ap_idle,
        ap_ready,
        inputData_V,
        inputData_V_ap_vld,
        outputData_TDATA,
        outputData_TVALID,
        outputData_TREADY,
        ap_return
);

parameter    ap_const_logic_1 = 1'b1;
parameter    ap_const_logic_0 = 1'b0;
parameter    ap_ST_st1_fsm_0 = 1'b1;
parameter    ap_const_lv32_0 = 32'b00000000000000000000000000000000;
parameter    ap_const_lv1_1 = 1'b1;
parameter    ap_true = 1'b1;

input   ap_clk;
input   ap_rst_n;
input   ap_start;
output   ap_done;
output   ap_idle;
output   ap_ready;
input  [0:0] inputData_V;
input   inputData_V_ap_vld;
input  [31:0] outputData_TDATA;
input   outputData_TVALID;
output   outputData_TREADY;
output  [31:0] ap_return;

reg ap_done;
reg ap_idle;
reg ap_ready;
reg    ap_rst_n_inv;
(* fsm_encoding = "none" *) reg   [0:0] ap_CS_fsm = 1'b1;
reg    ap_sig_cseq_ST_st1_fsm_0;
reg   [0:0] ap_NS_fsm;

always @ (posedge ap_clk)
begin : ap_ret_ap_CS_fsm
    if (ap_rst_n_inv == 1'b1) begin
        ap_CS_fsm <= ap_ST_st1_fsm_0;
    end else begin
        ap_CS_fsm <= ap_NS_fsm;
    end
end

always @ (ap_start or ap_sig_cseq_ST_st1_fsm_0)
begin
    if (((ap_const_logic_1 == ap_sig_cseq_ST_st1_fsm_0) & ~(ap_start == ap_const_logic_0))) begin
        ap_done = ap_const_logic_1;
    end else begin
        ap_done = ap_const_logic_0;
    end
end

always @ (ap_start or ap_sig_cseq_ST_st1_fsm_0)
begin
    if ((~(ap_const_logic_1 == ap_start) & (ap_const_logic_1 == ap_sig_cseq_ST_st1_fsm_0))) begin
        ap_idle = ap_const_logic_1;
    end else begin
        ap_idle = ap_const_logic_0;
    end
end

always @ (ap_start or ap_sig_cseq_ST_st1_fsm_0)
begin
    if (((ap_const_logic_1 == ap_sig_cseq_ST_st1_fsm_0) & ~(ap_start == ap_const_logic_0))) begin
        ap_ready = ap_const_logic_1;
    end else begin
        ap_ready = ap_const_logic_0;
    end
end

always @ (ap_sig_bdd_19)
begin
    if (ap_sig_bdd_19) begin
        ap_sig_cseq_ST_st1_fsm_0 = ap_const_logic_1;
    end else begin
        ap_sig_cseq_ST_st1_fsm_0 = ap_const_logic_0;
    end
end

always @ (ap_start or ap_CS_fsm)
begin
    case (ap_CS_fsm)
        ap_ST_st1_fsm_0 : 
        begin
            ap_NS_fsm = ap_ST_st1_fsm_0;
            if (inputData_V_ap_vld) begin
                outputData_TDATA <= inputData_V;
                outputData_TVALID <= ap_const_logic_1;
            end
            if (outputData_TREADY) begin
                outputData_TVALID <= ap_const_logic_0;
            end
            if (inputData_V_ap_vld && outputData_TREADY) begin
                ap_sig_bdd_19 <= ap_const_logic_1;
            end else begin
                ap_sig_bdd_19 <= ap_const_logic_0;
            end
        end
        default : 
        begin
            ap_NS_fsm = 'bx;
        end
    endcase
end

assign ap_return = ap_const_lv32_0;

always @ (ap_rst_n)
begin
    ap_rst_n_inv = ~ap_rst_n;
end

assign outputData_TREADY = ap_const_logic_0;

endmodule

module bin2bcd(
    input clk,
    input rst,
    input [7:0] bin,
    output [15:0] bcd
);

reg [7:0] shift_reg;
reg [3:0] count;

always @ (posedge clk) begin
    if (rst) begin
        shift_reg <= 8'b0;
        count <= 4'b0;
    end else begin
        // Shift in binary input
        shift_reg <= {shift_reg[6:0], bin[7]};

        // Convert to BCD using double dabble algorithm
        if (shift_reg >= 5) begin
            shift_reg <= shift_reg + 3;
        end
        shift_reg <= {shift_reg[6:0], shift_reg[7]};
        count <= count + 1;
    end
end

assign bcd = {4'b0, shift_reg};

endmodule

module audio_dma_engine (
    input clk,
    output dma,
    input [3:0] audio_dmal,
    input [3:0] audio_dmas,
    input [8:0] hpos,
    input [8:1] reg_address_in,
    output reg [8:1] reg_address_out,
    input [15:0] data_in,
    output [20:1] address_out
);

parameter AUD0DAT = 9'h0AA;
parameter AUD1DAT = 9'h0BA;
parameter AUD2DAT = 9'h0CA;
parameter AUD3DAT = 9'h0DA;

wire audlcena;
wire [1:0] audlcsel;
reg [20:16] audlch [3:0];
reg [15:1] audlcl [3:0];
wire [20:1] audlcout;
reg [20:1] audpt [3:0];
wire [20:1] audptout;
reg [1:0] channel;
reg dmal;
reg dmas;

assign audlcena = ~reg_address_in[8] & reg_address_in[7] & (reg_address_in[6]^reg_address_in[5]) & ~reg_address_in[3] & ~reg_address_in[2];
assign audlcsel = {~reg_address_in[5],reg_address_in[4]};

always @(posedge clk) begin
    if (audlcena & ~reg_address_in[1]) // AUDxLCH
        audlch[audlcsel] <= data_in[4:0];
end

always @(posedge clk) begin
    if (audlcena & reg_address_in[1]) // AUDxLCL
        audlcl[audlcsel] <= data_in[15:1];
end

assign audlcout = {audlch[channel],audlcl[channel]};

always @(hpos or audio_dmal) begin
    case (hpos)
        9'b0001_0010_1 : dmal = audio_dmal[0]; //$0E
        9'b0001_0100_1 : dmal = audio_dmal[1]; //$10
        9'b0001_0110_1 : dmal = audio_dmal[2]; //$12
        9'b0001_1000_1 : dmal = audio_dmal[3]; //$14
        default        : dmal = 0;
    endcase
end

assign dma = dmal;

always @(hpos or audio_dmas) begin
    case (hpos)
        9'b0001_0010_1 : dmas = audio_dmas[0]; //$0E
        9'b0001_0100_1 : dmas = audio_dmas[1]; //$10
        9'b0001_0110_1 : dmas = audio_dmas[2]; //$12
        9'b0001_1000_1 : dmas = audio_dmas[3]; //$14
        default        : dmas = 0;
    endcase
end

always @(hpos) begin
    case (hpos[3:2])
        2'b01 : channel = 0; //$0E
        2'b10 : channel = 1; //$10
        2'b11 : channel = 2; //$12
        2'b00 : channel = 3; //$14
    endcase
end

assign address_out[20:1] = audptout[20:1];

always @(posedge clk) begin
    if (dmal)
        audpt[channel] <= dmas ? audlcout[20:1] : audptout[20:1] + 1'b1;
end

assign audptout[20:1] = audpt[channel];

always @(channel) begin
    case (channel)
        0 : reg_address_out[8:1] = AUD0DAT[8:1];
        1 : reg_address_out[8:1] = AUD1DAT[8:1];
        2 : reg_address_out[8:1] = AUD2DAT[8:1];
        3 : reg_address_out[8:1] = AUD3DAT[8:1];
    endcase
end

endmodule

