module logic_analyzer(
  input clk,
  input [15:0] signal_in,
  input [3:0] control_in,
  output reg [3:0] waveform_out
);

  reg [255:0] shift_reg;
  reg [7:0] shift_count;

  always @(posedge clk) begin
    if (control_in == 4'b0000) begin
      shift_reg <= {shift_reg[251:0], signal_in[3:0]};
    end else if (control_in == 4'b0001) begin
      shift_reg <= {shift_reg[251:0], signal_in[7:4]};
    end else if (control_in == 4'b0010) begin
      shift_reg <= {shift_reg[251:0], signal_in[11:8]};
    end else if (control_in == 4'b0011) begin
      shift_reg <= {shift_reg[251:0], signal_in[15:12]};
    end else if (control_in == 4'b0100) begin
      shift_reg <= {shift_reg[251:0], signal_in[19:16]};
    end else if (control_in == 4'b0101) begin
      shift_reg <= {shift_reg[251:0], signal_in[23:20]};
    end else if (control_in == 4'b0110) begin
      shift_reg <= {shift_reg[251:0], signal_in[27:24]};
    end else if (control_in == 4'b0111) begin
      shift_reg <= {shift_reg[251:0], signal_in[31:28]};
    end else begin
      shift_reg <= shift_reg;
    end

    if (shift_count == 8) begin
      shift_count <= 0;
      waveform_out <= shift_reg[7:4];
      shift_reg <= {shift_reg[251:0], 4'b0};
    end else begin
      shift_count <= shift_count + 1;
      waveform_out <= shift_reg[7:4];
      shift_reg <= {shift_reg[251:0], shift_reg[3:0]};
    end
  end

endmodule

module booth_multiplier_16bit (
    input [15:0] multiplicand,
    input [15:0] multiplier,
    output [31:0] product
);

reg [31:0] product_reg;
reg [15:0] a_reg, s_reg;
reg [3:0] count;

always @(*) begin
    product_reg = multiplicand * multiplier;
end

always @(posedge clk) begin
    if (reset) begin
        a_reg <= 16'b0;
        s_reg <= {multiplier, 1'b0};
        count <= 4'b0;
    end else begin
        if (count == 4'b0) begin
            a_reg <= 16'b0;
            s_reg <= {multiplier, 1'b0};
        end else begin
            case (s_reg[1:0])
                2'b01: begin
                    a_reg <= a_reg + multiplicand;
                    s_reg <= {s_reg[15:1], a_reg[0]};
                end
                2'b10: begin
                    a_reg <= a_reg - multiplicand;
                    s_reg <= {s_reg[15:1], a_reg[0]};
                end
                2'b11: begin
                    s_reg <= {s_reg[15:1], s_reg[0]};
                end
                2'b00: begin
                    s_reg <= {s_reg[15:1], s_reg[0]};
                end
            endcase
            count <= count - 1;
        end
    end
end

assign product = product_reg;

endmodule

module CLA_Array(
    input [63:0] a,
    input [63:0] b,
    input cin,
    output [63:0] result,
    output cout
);

    wire [15:0] g;
    wire [15:0] p;
    wire [15:0] c;
    wire [15:0] s;

    assign g[0] = a[0] & b[0];
    assign p[0] = a[0] ^ b[0];
    assign c[0] = g[0] | (p[0] & cin);
    assign s[0] = p[0] ^ cin;

    genvar i;
    generate
        for (i = 1; i < 16; i = i + 1) begin : CLA_block
            wire [3:0] a_i = a[4*i +: 4];
            wire [3:0] b_i = b[4*i +: 4];
            wire c_in = c[i-1];

            wire g_i;
            wire p_i;
            wire c_i;
            wire s_i;

            assign g_i = a_i & b_i;
            assign p_i = a_i ^ b_i;
            assign c_i = g_i | (p_i & c_in);
            assign s_i = p_i ^ c_in;

            assign g[i] = g_i;
            assign p[i] = p_i;
            assign c[i] = c_i;
            assign s[i*4 +: 4] = s_i;
        end

        assign result = {s[63:48], s[47:32], s[31:16], s[15:0]};
        assign cout = c[15];
    endgenerate

endmodule

