module eth_rxcounters (
  input MRxClk,
  input Reset,
  input MRxDV,
  input StateIdle,
  input StateSFD,
  input [1:0] StateData,
  input StateDrop,
  input StatePreamble,
  input MRxDEqD,
  input DlyCrcEn,
  input HugEn,
  input [15:0] MaxFL,
  input r_IFG,
  output IFGCounterEq24,
  output [3:0] DlyCrcCnt,
  output ByteCntEq0,
  output ByteCntEq1,
  output ByteCntEq2,
  output ByteCntEq3,
  output ByteCntEq4,
  output ByteCntEq5,
  output ByteCntEq6,
  output ByteCntEq7,
  output ByteCntGreat2,
  output ByteCntSmall7,
  output ByteCntMaxFrame,
  output [15:0] ByteCntOut
);

  parameter Tp = 1;

  wire ResetByteCounter;
  wire IncrementByteCounter;
  wire ResetIFGCounter;
  wire IncrementIFGCounter;
  wire ByteCntMax;

  reg [15:0] ByteCnt;
  reg [3:0] DlyCrcCnt;
  reg [4:0] IFGCounter;

  wire [15:0] ByteCntDelayed;

  assign ResetByteCounter = MRxDV & (StateSFD & MRxDEqD | StateData[0] & ByteCntMaxFrame);
  assign IncrementByteCounter = ~ResetByteCounter & MRxDV & 
                                (StatePreamble | StateSFD | StateIdle & ~Transmitting |
                                 StateData[1] & ~ByteCntMax & ~(DlyCrcEn & DlyCrcCnt)
                                );
  always @ (posedge MRxClk or posedge Reset) begin
    if (Reset) ByteCnt[15:0] <= #Tp 16'h0;
    else begin
      if (ResetByteCounter) ByteCnt[15:0] <= #Tp 16'h0;
      else if (IncrementByteCounter) ByteCnt[15:0] <= #Tp ByteCnt[15:0] + 1'b1;
    end
  end

  assign ByteCntDelayed = ByteCnt + 3'h4;
  assign ByteCntOut = DlyCrcEn ? ByteCntDelayed : ByteCnt;

  assign ByteCntEq0 = ByteCnt == 16'h0;
  assign ByteCntEq1 = ByteCnt == 16'h1;
  assign ByteCntEq2 = ByteCnt == 16'h2;
  assign ByteCntEq3 = ByteCnt == 16'h3;
  assign ByteCntEq4 = ByteCnt == 16'h4;
  assign ByteCntEq5 = ByteCnt == 16'h5;
  assign ByteCntEq6 = ByteCnt == 16'h6;
  assign ByteCntEq7 = ByteCnt == 16'h7;
  assign ByteCntGreat2 = ByteCnt > 16'h2;
  assign ByteCntSmall7 = ByteCnt < 16'h7;
  assign ByteCntMax = ByteCnt == 16'hffff;
  assign ByteCntMaxFrame = ByteCnt == MaxFL[15:0] & ~HugEn;

  assign ResetIFGCounter = StateSFD & MRxDV & MRxDEqD | StateDrop;
  assign IncrementIFGCounter = ~ResetIFGCounter & (StateDrop | StateIdle | StatePreamble | StateSFD) & ~IFGCounterEq24;
  always @ (posedge MRxClk or posedge Reset) begin
    if (Reset) IFGCounter[4:0] <= #Tp 5'h0;
    else begin
      if (ResetIFGCounter) IFGCounter[4:0] <= #Tp 5'h0;
      else if (IncrementIFGCounter) IFGCounter[4:0] <= #Tp IFGCounter[4:0] + 1'b1;
    end
  end

  assign IFGCounterEq24 = (IFGCounter[4:0] == 5'h18) | r_IFG;

  always @ (posedge MRxClk or posedge Reset) begin
    if (Reset) DlyCrcCnt[3:0] <= #Tp 4'h0;
    else begin
      if (DlyCrcCnt[3:0] == 4'h9) DlyCrcCnt[3:0] <= #Tp 4'h0;
      else if (DlyCrcEn & StateSFD) DlyCrcCnt[3:0] <= #Tp 4'h1;
      else if (DlyCrcEn & (|DlyCrcCnt[3:0])) DlyCrcCnt[3:0] <= #Tp DlyCrcCnt[3:0] + 1'b1;
    end
  end

endmodule

module comparator(
    input [3:0] a,
    input [3:0] b,
    output reg eq,
    output reg ge8,
    output reg lt8
);

reg [3:0] diff;
wire [3:0] abs_diff;

assign abs_diff = (diff < 0) ? -diff : diff;

always @(*) begin
    diff = a - b;
    if (diff == 0) begin
        eq = 1;
        ge8 = 0;
        lt8 = 0;
    end else if (abs_diff >= 8) begin
        eq = 0;
        ge8 = 1;
        lt8 = 0;
    end else begin
        eq = 0;
        ge8 = 0;
        lt8 = 1;
    end
end

endmodule

module mux_adder (
    input [2:0] sel, // 3-bit input for the multiplexer
    input [3:0] data0, // 4-bit input for the multiplexer
    input [3:0] data1, 
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    input [3:0] A, // 4-bit input for the ripple carry adder
    input [3:0] B,
    output [7:0] out // 8-bit final output
);

// 6-to-1 priority encoder-based multiplexer
wire [3:0] mux_out;
assign mux_out = (sel > 5) ? 4'b0000 :
                 (sel == 0) ? data0 :
                 (sel == 1) ? data1 :
                 (sel == 2) ? data2 :
                 (sel == 3) ? data3 :
                 (sel == 4) ? data4 :
                 (sel == 5) ? data5 : 4'b0000;

// 4-bit ripple carry adder
wire [3:0] sum;
wire carry_out;
ripple_adder adder(.A(A), .B(B), .S(sum), .CO(carry_out));

// final output concatenation
assign out = {sum, mux_out};

endmodule

module ripple_adder (
    input [3:0] A,
    input [3:0] B,
    output [3:0] S,
    output CO
);

wire [3:0] sum;
wire [3:0] carry;
assign sum = A + B;
assign carry = {A[3], B[3], sum[3]} & {A[2], B[2], sum[2]} & {A[1], B[1], sum[1]} & {A[0], B[0], sum[0]};
assign CO = carry[3];
assign S = sum;

endmodule

module barrel_shifter(in, shift, out);

input [3:0] in;
input [1:0] shift;
output [3:0] out;

wire [3:0] temp;

// No shift
assign temp = in;

// Shift left by 1 bit
assign temp = {in[2:0], 1'b0};

// Shift right by 1 bit
assign temp = {1'b0, in[3:1]};

// Rotate right by 1 bit
assign temp = {in[0], in[3:1]};

// Select the output based on the shift value
always @(*) begin
    case (shift)
        2'b00: out = temp;
        2'b01: out = {temp[2:0], 1'b0};
        2'b10: out = {1'b0, temp[3:1]};
        2'b11: out = {temp[0], temp[3:1]};
    endcase
end

endmodule

module axi_to_custom_protocol_converter
   (next_pending_r_reg,
    m_axi_awaddr,
    m_payload_i_reg,
    incr_next_pending,
    wrap_next_pending,
    sel_first_reg_0,
    aclk,
    m_axi_awaddr_in,
    m_payload_i_reg_in,
    next,
    incr_next_pending_in,
    wrap_next_pending_in,
    sel_first_i);
  output next_pending_r_reg;
  output [11:0]m_axi_awaddr;
  output [47:0]m_payload_i_reg;
  output incr_next_pending;
  output wrap_next_pending;
  output sel_first_reg_0;
  input aclk;
  input [11:0]m_axi_awaddr_in;
  input [47:0]m_payload_i_reg_in;
  input next;
  input incr_next_pending_in;
  input wrap_next_pending_in;
  input sel_first_i;

  reg [11:0]m_axi_awaddr;
  reg [47:0]m_payload_i_reg;
  reg incr_next_pending;
  reg wrap_next_pending;
  reg sel_first_reg_0;

  always @(posedge aclk) begin
    if (sel_first_i) begin
      m_axi_awaddr <= m_axi_awaddr_in;
      m_payload_i_reg <= m_payload_i_reg_in;
      sel_first_reg_0 <= 1'b1;
    end else if (incr_next_pending_in) begin
      m_axi_awaddr <= m_axi_awaddr + 1;
      m_payload_i_reg <= m_payload_i_reg_in;
      sel_first_reg_0 <= 1'b0;
    end else if (wrap_next_pending_in) begin
      m_axi_awaddr <= m_axi_awaddr_in;
      m_payload_i_reg <= m_payload_i_reg_in;
      wrap_next_pending <= 1'b1;
      sel_first_reg_0 <= 1'b0;
    end else if (next) begin
      next_pending_r_reg <= 1'b0;
    end
  end

  always @(posedge aclk) begin
    if (sel_first_i) begin
      incr_next_pending <= 1'b0;
      wrap_next_pending <= 1'b0;
    end else if (incr_next_pending_in) begin
      incr_next_pending <= 1'b1;
      wrap_next_pending <= 1'b0;
    end else if (wrap_next_pending_in) begin
      incr_next_pending <= 1'b0;
      wrap_next_pending <= 1'b1;
    end else if (next) begin
      incr_next_pending <= 1'b0;
      wrap_next_pending <= 1'b0;
    end
  end
endmodule

module multiplicadorPuntoFijo  #(parameter Width = 24, Magnitud = 4, Precision = 19, Signo = 1)
		(EnableMul,In,Coeff,OutMul,Error);

	 input EnableMul;
	 input signed [Width-1:0] In,Coeff;
	 output reg signed [Width-1:0] OutMul = 0; 
	 output Error;
	 reg signed [2*Width-1:0]  AuxMul = 0; 
	 reg Overflow = 0;
	 reg Underflow = 0;



		always @* begin //Se ejecuta la multiplicación**************************************************
			if (EnableMul) begin
				AuxMul <= In * Coeff; // Se almacena el resultado en un temporal
			end
			else begin
				AuxMul <= 0;
			end
		end

		always @* begin // Detección  de Overflow y underflow****************************************+
			if (~In[Width-1] && ~Coeff[Width-1] && AuxMul[2*Width -1 - Magnitud - Signo]) begin
				Overflow <= 1;
				Underflow <= 0;
			end
			else if(In[Width-1] && Coeff[Width-1] && AuxMul[2*Width -1 - Magnitud - Signo]) begin
				Overflow <= 1;
				Underflow <= 0;
			end
			else if(~In[Width-1] && Coeff[Width-1] && ~AuxMul[2*Width -1 - Magnitud - Signo]) begin
				Overflow <= 0;
				Underflow <= 1;
			end
			else if(In[Width-1] && ~Coeff[Width-1] && ~AuxMul[2*Width -1 - Magnitud - Signo]) begin
				Overflow <= 0;
				Underflow <= 1;
			end
			else begin
				Overflow <= 0;
				Underflow <= 0;
			end
		end

		always @* begin // Se ejecuta la salida ***************************************************************
			if (In == 0 || Coeff==0) begin
					OutMul <= 0;
			end 
			else begin
				if (Overflow) begin
					OutMul <= 2**(Width-1) -1;  // En caso que se multipliquen 2 numeros positivos y de negativo; Significa que hubo overflow 					
				end
				else begin
					if (Underflow) begin
						OutMul <= -2**(Width-1);    // En caso que se multipliquen 1 numero negativo y el otro positivo y el resultado de positivo, sugnifica que hay underflow
					end
					else begin
						OutMul <= AuxMul[2*Width -1 - Magnitud - Signo : Precision];      // Si no hay ni overflow ni underflow Salida es igual a resultado temporal
					end
				end	
			end
		end

		//****************************Errorrrrrrrrr*************************
		assign Error =  Overflow | Underflow;


	 //**********************************************************FIN DE EJECUCION MULTIPLICADOR*********************************************************
endmodule

