module fifo_async_104x16(rst, wr_clk, rd_clk, din, wr_en, rd_en, dout, full, empty, prog_full);
  parameter ADDR_WIDTH = 7;
  parameter DATA_WIDTH = 16;
  parameter FIFO_DEPTH = 104;

  input rst;
  input wr_clk;
  input rd_clk;
  input [DATA_WIDTH-1:0] din;
  input wr_en;
  input rd_en;

  output [DATA_WIDTH-1:0] dout;
  output full;
  output empty;
  output prog_full;

  reg [DATA_WIDTH-1:0] fifo[FIFO_DEPTH-1:0];
  reg [ADDR_WIDTH-1:0] wr_ptr;
  reg [ADDR_WIDTH-1:0] rd_ptr;
  reg [ADDR_WIDTH-1:0] count;
  reg prog_full_reg;

  assign empty = (count == 0);
  assign full = (count == FIFO_DEPTH);
  assign prog_full = prog_full_reg;
  assign dout = fifo[rd_ptr];

  always @(posedge wr_clk or negedge rst) begin
    if (~rst) begin
      wr_ptr <= 0;
      rd_ptr <= 0;
      count <= 0;
      prog_full_reg <= 0;
      for (i = 0; i < FIFO_DEPTH; i = i + 1) begin
        fifo[i] <= 0;
      end
    end else if (wr_en && ~full) begin
      fifo[wr_ptr] <= din;
      wr_ptr <= wr_ptr + 1;
      count <= count + 1;
      if (count == FIFO_DEPTH - 1) begin
        prog_full_reg <= 1;
      end
    end
  end

  always @(posedge rd_clk or negedge rst) begin
    if (~rst) begin
      wr_ptr <= 0;
      rd_ptr <= 0;
      count <= 0;
      prog_full_reg <= 0;
      for (i = 0; i < FIFO_DEPTH; i = i + 1) begin
        fifo[i] <= 0;
      end
    end else if (rd_en && ~empty) begin
      rd_ptr <= rd_ptr + 1;
      count <= count - 1;
      if (count == FIFO_DEPTH) begin
        prog_full_reg <= 0;
      end
    end
  end
endmodule

module memory_unit
(
    input clk,
    input en,
    input w,
    input [3:0] wbe,
    input [13:0] addr,
    input [31:0] data_in,
    output reg [31:0] data_out
);

// 2KB character ROM
reg [31:0] rom_low [2047:0];
(* ram_init_file = "character_rom.hex" *) // initialize ROM with character definitions

// 2KB sin table, log table, booter, and interpreter ROM
reg [31:0] rom_high [2047:0];
(* ram_init_file = "sin_log_booter_interpreter.hex" *) // initialize ROM with sin table, log table, booter, and interpreter

// 4KB RAM
reg [7:0] ram3 [2047:0];
reg [7:0] ram2 [2047:0];
reg [7:0] ram1 [2047:0];
reg [7:0] ram0 [2047:0];

reg [7:0] ram_q3;
reg [7:0] ram_q2;
reg [7:0] ram_q1;
reg [7:0] ram_q0;

always @(posedge clk)
begin
    if (en && !addr[13] && w && wbe[3])
        ram3[addr[12:0]] <= data_in[31:24];
    if (en && !addr[13])
        ram_q3 <= ram3[addr[12:0]];
end

always @(posedge clk)
begin
    if (en && !addr[13] && w && wbe[2])
        ram2[addr[12:0]] <= data_in[23:16];
    if (en && !addr[13])
        ram_q2 <= ram2[addr[12:0]];
end

always @(posedge clk)
begin
    if (en && !addr[13] && w && wbe[1])
        ram1[addr[12:0]] <= data_in[15:8];
    if (en && !addr[13])
        ram_q1 <= ram1[addr[12:0]];
end

always @(posedge clk)
begin
    if (en && !addr[13] && w && wbe[0])
        ram0[addr[12:0]] <= data_in[7:0];
    if (en && !addr[13])
        ram_q0 <= ram0[addr[12:0]];
end

always @(posedge clk)
begin
    if (en && addr[13:12] == 2'b10)
        data_out <= rom_low[addr[11:0]];
end

always @(posedge clk)
begin
    if (en && addr[13:12] == 2'b11)
        data_out <= rom_high[addr[11:0]];
end

always @(posedge clk)
begin
    if (en)
    begin
        case (addr[13:12])
            2'b00: data_out <= {ram_q3, ram_q2, ram_q1, ram_q0};
            2'b10: data_out <= rom_low[addr[11:0]];
            2'b11: data_out <= rom_high[addr[11:0]];
            default: data_out <= 32'hx;
        endcase
    end
end

endmodule

module PWM (
  input analog_in,
  input freq,
  input duty_cycle,
  output pwm_out
);

parameter clock_freq = 50; // the frequency of the system clock in MHz

reg [31:0] counter;
reg pwm_out_reg;

always @(posedge freq) begin
  counter <= counter + 1;
  if (counter >= (clock_freq / freq)) begin
    counter <= 0;
    pwm_out_reg <= (counter < ((clock_freq / freq) * duty_cycle / 100));
  end
end

assign pwm_out = pwm_out_reg;

endmodule

