module gshare_branch_predictor (
  input clk,
  input reset,
  input predict_valid,
  input [5:0] pc,
  input train_valid,
  input [5:0] train_pc,
  input [5:0] train_branch_history,
  input actual_branch_outcome,
  input mispredicted,
  output reg [5:0] branch_history_register,
  output reg predicted_branch_direction
);

  // Define parameters
  parameter INDEX_WIDTH = 6;
  parameter TABLE_SIZE = 64;
  parameter COUNTER_WIDTH = 2;
  parameter HISTORY_WIDTH = 6;

  // Define registers and wires
  reg [HISTORY_WIDTH-1:0] global_history_register;
  reg [INDEX_WIDTH-1:0] index;
  reg [COUNTER_WIDTH-1:0] table [0:TABLE_SIZE-1];
  wire [COUNTER_WIDTH-1:0] counter_out;

  // Define internal signals
  wire [COUNTER_WIDTH-1:0] counter_read;
  wire [INDEX_WIDTH-1:0] index_out;
  wire [HISTORY_WIDTH-1:0] history_out;

  // Define prediction and training interfaces
  assign index_out = {global_history_register[5:0] ^ pc[5:0]};
  assign history_out = {global_history_register[4:0], mispredicted};
  assign counter_read = table[index_out];

  // Make predictions
  always @(posedge clk) begin
    if (reset) begin
      global_history_register <= 0;
      predicted_branch_direction <= 0;
    end else if (predict_valid) begin
      index <= index_out;
      predicted_branch_direction <= (counter_out >= 2);
    end
  end

  // Train the predictor
  always @(posedge clk) begin
    if (reset) begin
      global_history_register <= 0;
    end else if (train_valid) begin
      index <= {global_history_register[5:0] ^ train_pc[5:0]};
      table[index] <= table[index] + actual_branch_outcome;
      global_history_register <= {global_history_register[4:0], actual_branch_outcome};
    end
  end

  // Read from the counter table
  assign counter_out = table[index];

  // Update the global history register
  always @(posedge clk) begin
    if (reset) begin
      global_history_register <= 0;
    end else if (predict_valid || train_valid) begin
      global_history_register <= {global_history_register[4:0], mispredicted};
    end
  end

  // Output the branch history register
  always @(posedge clk) begin
    if (reset) begin
      branch_history_register <= 0;
    end else if (predict_valid || train_valid) begin
      branch_history_register <= global_history_register;
    end
  end

endmodule

module compare_FP (
    input [63:0] a,
    input [63:0] b,
    input signaling,
    output lt,
    output eq,
    output gt,
    output unordered,
    output [4:0] exceptionFlags
);

    // Extract sign, exponent, and mantissa from inputs
    wire a_sign = a[63];
    wire b_sign = b[63];
    wire [10:0] a_exp = a[62:52];
    wire [10:0] b_exp = b[62:52];
    wire [51:0] a_mant = a[51:0];
    wire [51:0] b_mant = b[51:0];

    // Determine if inputs are NaN or infinity
    wire a_inf_nan = (a_exp == 1023);
    wire b_inf_nan = (b_exp == 1023);
    wire a_nan = a_inf_nan & (a_mant != 0);
    wire b_nan = b_inf_nan & (b_mant != 0);

    // Determine if inputs are zero or subnormal
    wire a_zero_sub = (a_exp == 0);
    wire b_zero_sub = (b_exp == 0);
    wire a_sub = a_zero_sub & (a_mant != 0);
    wire b_sub = b_zero_sub & (b_mant != 0);

    // Determine if inputs are normal
    wire a_norm = ~(a_inf_nan | a_zero_sub);
    wire b_norm = ~(b_inf_nan | b_zero_sub);

    // Determine if inputs have the same sign
    wire same_sign = (a_sign == b_sign);

    // Determine if inputs are equal
    wire same_exp = (a_exp == b_exp);
    wire same_mant = (a_mant == b_mant);
    wire equal = same_exp & same_mant;

    // Determine if a is greater than b
    wire greater = ~(same_sign) & ((a_sign & same_exp & (a_mant > b_mant)) | (b_sign & same_exp & (b_mant > a_mant)) | (a_sign & ~same_exp & (a_exp > b_exp)) | (b_sign & ~same_exp & (b_exp > a_exp)));

    // Determine if a is less than b
    wire less = ~(same_sign) & ~(equal | greater);

    // Determine if a and b are unordered
    wire unordered_wire = a_nan | b_nan | (a_zero_sub & b_zero_sub);

    // Determine if exception flags should be set
    wire invalid_op = signaling & (a_nan | b_nan);
    wire div_by_zero = (a_inf_nan & b_zero_sub) | (b_inf_nan & a_zero_sub);
    wire overflow = (a_inf_nan & b_norm) | (b_inf_nan & a_norm);
    wire underflow = (a_zero_sub & b_norm) | (b_zero_sub & a_norm);
    wire inexact = ~(equal | greater | less | unordered_wire);

    // Set output signals and exception flags
    assign lt = less;
    assign eq = equal;
    assign gt = greater;
    assign unordered = unordered_wire;
    assign exceptionFlags = {inexact, underflow, overflow, div_by_zero, invalid_op};

endmodule

module rotator (
    input clk,
    input [99:0] data,
    input load,
    input [1:0] ena,
    output reg [99:0] q
);

reg [99:0] shift_reg;

always @(posedge clk) begin
    if (load) begin
        shift_reg <= data;
    end else begin
        case (ena)
            2'b00: shift_reg <= {shift_reg[98:0], shift_reg[99]};
            2'b01: shift_reg <= {shift_reg[0], shift_reg[99:1]};
            2'b10: shift_reg <= shift_reg;
            2'b11: shift_reg <= {shift_reg[0], shift_reg[98:0]};
        endcase
    end
end

assign q = shift_reg;

endmodule

