module top_module (
    input clk,
    input reset,
    input [1:0] ena,
    input [99:0] data,
    input select,
    output [7:0] q
);

wire [99:0] rotator_output;
wire [2:0] counter_output;
wire [7:0] xor_output;

rotator rotator_inst (
    .clk(clk),
    .data(data),
    .load(ena[1]),
    .ena(ena),
    .q(rotator_output)
);

counter counter_inst (
    .clk(clk),
    .reset(reset),
    .q(counter_output)
);

xor_function xor_inst (
    .rotator_output(rotator_output),
    .counter_output(counter_output),
    .q(xor_output)
);

control_logic control_inst (
    .select(select),
    .ena(ena),
    .rotator_enable(rotator_inst.enable),
    .counter_enable(counter_inst.enable)
);

always @(posedge clk) begin
    if (control_inst.rotator_enable) begin
        q <= xor_output;
    end else if (control_inst.counter_enable) begin
        q <= xor_output;
    end
end

