module twos_comp_adder (
    input [2:0] a,
    input b_in,
    output [2:0] sum,
    output overflow
);

    wire [2:0] b;
    assign b = b_in ? 3'b111 : 3'b000;

    wire [3:0] a_ext, b_ext;
    assign a_ext = {1'b0, a};
    assign b_ext = {1'b0, b};

    wire [3:0] add;
    wire carry_out;
    cla_adder_4bit adder(.a(a_ext), .b(~b_ext), .sum(add), .carry_out(carry_out));

    assign sum = add[2:0];
    assign overflow = carry_out;

endmodule

module fifo_1r1w_small_credit_on_input #( parameter width_p = 8, parameter els_p = 16 ) (
    input clk_i,
    input reset_i,

    input [width_p-1:0] data_i,
    input v_i,
    output logic credit_o,

    output v_o,
    output [width_p-1:0] data_o,
    input yumi_i
);

    // Internal signal for assert
    logic ready;

    // Credit must be asserted at the beginning of a cycle
    always_ff @ (posedge clk_i) begin
        if (reset_i) begin
            credit_o <= 0;
        end else begin
            credit_o <= yumi_i;
        end
    end

    // FIFO used to keep the data values
    bsg_fifo_1r1w_small #(
        .width_p(width_p),
        .els_p(els_p),
        .ready_THEN_valid_p(1)
    ) fifo (
        .clk_i(clk_i),
        .reset_i(reset_i),

        .data_i(data_i),
        .v_i(v_i),
        .ready_o(ready),

        .v_o(v_o),
        .data_o(data_o),
        .yumi_i(yumi_i)
    );

    // Assert error if any data is lost during the write process
    always_ff @ (posedge clk_i) begin
        if (!reset_i && v_i && !ready) begin
            $error("FIFO overflow");
        end
    end

endmodule

module top_module(
    input [31:0] a,
    input [31:0] b,
    output [31:0] sum,
    output [31:0] largest_value
);

    wire [15:0] a_low, b_low, sum_low;
    wire [31:0] carry_out;
    wire [3:0] carry_lookahead;

    // Split inputs and sum into low and high 16-bit parts
    assign a_low = a[15:0];
    assign b_low = b[15:0];
    assign sum_low = sum[15:0];

    // Generate carry lookahead signals
    assign carry_lookahead[0] = a_low[0] & b_low[0];
    assign carry_lookahead[1] = a_low[1] & b_low[1];
    assign carry_lookahead[2] = a_low[2] & b_low[2];
    assign carry_lookahead[3] = a_low[3] & b_low[3];

    // Generate carry out signals from 16-bit adder
    ripple_adder_16bit adder16(
        .a(a_low),
        .b(b_low),
        .sum(sum_low),
        .carry_out(carry_out)
    );

    // Generate final 32-bit sum using carry lookahead adder
    carry_lookahead_adder adder32(
        .a(a),
        .b(b),
        .carry_in(carry_out),
        .sum(sum),
        .carry_lookahead(carry_lookahead)
    );

    // Determine largest value
    assign largest_value = (a > b) ? a : b;
    assign largest_value = (sum > largest_value) ? sum : largest_value;

endmodule

