module PLL_Frequency_Synthesizer (
  input ref_clk,
  input ctrl,
  output out_clk
);

parameter N = 10; // multiplication factor of the PLL
parameter M = 2; // division factor of the PLL

reg [31:0] phase_accumulator = 0;
reg [31:0] phase_increment = 0;
reg [31:0] divider_counter = 0;

always @ (posedge ref_clk) begin
  phase_accumulator <= phase_accumulator + phase_increment;
  if (phase_accumulator >= 2**32/N) begin
    phase_accumulator <= phase_accumulator - 2**32/N;
    divider_counter <= divider_counter + 1;
  end
end

always @ (posedge ctrl) begin
  phase_increment <= ctrl * 2**32/N;
  divider_counter <= 0;
end

assign out_clk = ref_clk * N/M;

endmodule

module handshake(
    input clk,
    input rst,
    input channel_out_en,
    input [31:0] channel_out_data,
    output reg channel_out_ack,
    output reg [31:0] channel_in_data,
    output reg channel_in_en,
    input channel_in_ack
);

    reg [1:0] state;
    parameter IDLE = 2'b00, TRANSMIT = 2'b01, RECEIVE = 2'b10;

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            channel_out_ack <= 0;
            channel_in_data <= 0;
            channel_in_en <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (channel_out_en && !channel_in_ack) begin
                        state <= TRANSMIT;
                    end else if (channel_in_en) begin
                        state <= RECEIVE;
                    end
                end
                TRANSMIT: begin
                    if (channel_in_ack) begin
                        channel_out_ack <= 1;
                        state <= IDLE;
                    end
                end
                RECEIVE: begin
                    if (!channel_out_en) begin
                        channel_in_en <= 0;
                        channel_in_data <= 0;
                        channel_out_ack <= 1;
                        state <= IDLE;
                    end else if (!channel_in_en) begin
                        channel_in_en <= 1;
                        channel_in_data <= channel_out_data;
                        state <= TRANSMIT;
                    end
                end
            endcase
        end
    end

endmodule

module VGA_Control
(
    input clk,
    input rst,
    input [7:0] snake,
    input [7:0] apple_x,
    input [7:0] apple_y,
    output reg [9:0] x_pos,
    output reg [9:0] y_pos,
    output reg hsync,
    output reg vsync,
    output reg [11:0] color_out
);

    reg [19:0] clk_cnt;
    reg [9:0] line_cnt;
    reg clk_25M;

    localparam NONE = 7'b0000_000;
    localparam HEAD = 7'b0000_001;
    localparam BODY = 7'b0000_010;
    localparam WALL = 7'b0000_011;

    localparam HEAD_COLOR = 12'b0000_1111_0000;
    localparam BODY_COLOR = 12'b0000_1111_1111;

    reg [3:0] lox;
    reg [3:0] loy;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            clk_cnt <= 0;
            line_cnt <= 0;
            hsync <= 1;
            vsync <= 1;
        end else begin
            x_pos <= clk_cnt - 144;
            y_pos <= line_cnt - 33;
            if (clk_cnt == 0) begin
                hsync <= 0;
                clk_cnt <= clk_cnt + 1;
            end else if (clk_cnt == 96) begin
                hsync <= 1;
                clk_cnt <= clk_cnt + 1;
            end else if (clk_cnt == 799) begin
                clk_cnt <= 0;
                line_cnt <= line_cnt + 1;
            end else begin
                clk_cnt <= clk_cnt + 1;
            end
            if (line_cnt == 0) begin
                vsync <= 0;
            end else if (line_cnt == 2) begin
                vsync <= 1;
            end else if (line_cnt == 521) begin
                line_cnt <= 0;
                vsync <= 0;
            end
            if (x_pos >= 0 && x_pos < 640 && y_pos >= 0 && y_pos < 480) begin
                lox = x_pos[3:0];
                loy = y_pos[3:0];
                if (x_pos[9:4] == apple_x && y_pos[9:4] == apple_y) begin
                    case ({loy, lox})
                        8'b0000_0000: color_out = 12'b0000_0000_0000;
                        default: color_out = 12'b0000_0000_1111;
                    endcase
                end else if (snake == NONE) begin
                    color_out = 12'b0000_0000_0000;
                end else if (snake == WALL) begin
                    color_out = 3'b101;
                end else if (snake == HEAD | snake == BODY) begin
                    case ({lox, loy})
                        8'b0000_0000: color_out = 12'b0000_0000_0000;
                        default: color_out = (snake == HEAD) ? HEAD_COLOR : BODY_COLOR;
                    endcase
                end
            end else begin
                color_out = 12'b0000_0000_0000;
            end
        end
    end
endmodule

