module adder_subtractor(
    input [15:0] a,
    input [15:0] b,
    input sub,
    output [15:0] out,
    output carry_out
);

    wire [15:0] b_inverted;
    wire [15:0] b_twos_complement;
    wire [15:0] adder1_out;
    wire [15:0] adder2_out;

    xor #(.N(16)) xor_gate(
        .a(b),
        .b({16{sub}}),
        .y(b_inverted)
    );

    twos_complement #(.N(16)) twos_complement_module(
        .in(sub),
        .out(b_twos_complement)
    );

    adder #(.N(16)) adder1(
        .a(a),
        .b(b_inverted),
        .carry_in(b_twos_complement[0]),
        .sum(adder1_out),
        .carry_out(carry_out)
    );

    adder #(.N(16)) adder2(
        .a(adder1_out),
        .b({16{carry_out}}),
        .carry_in(0),
        .sum(adder2_out),
        .carry_out()
    );

    assign out = adder2_out;

endmodule

module top_module(
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] sum
);

    wire [15:0] a_low;
    wire [15:0] a_high;
    wire [15:0] b_low;
    wire [15:0] b_high;
    wire [15:0] adder1_out;
    wire [15:0] adder2_out;
    wire carry_out;

    assign a_low = a[15:0];
    assign a_high = a[31:16];
    assign b_low = b[15:0];
    assign b_high = b[31:16];

    adder_subtractor adder_subtractor1(
        .a(a_low),
        .b(b_low),
        .sub(sub),
        .out(adder1_out),
        .carry_out(carry_out)
    );

    adder_subtractor adder_subtractor2(
        .a(a_high),
        .b(b_high),
        .sub(carry_out),
        .out(adder2_out),
        .carry_out()
    );

    assign sum = {adder2_out, adder1_out};

endmodule

module top_module (
    input clk,
    input rst_n,
    input [15:0] data_in,
    input [1:0] A,
    input [1:0] B,
    output reg [7:0] max_value,
    output reg [3:0] max_index,
    output reg [7:0] selected_value
);

    // 4-to-16 Decoder
    wire [15:0] decoder_out;
    decoder_4to16 decoder_inst (
        .in({A,B}),
        .out(decoder_out)
    );

    // Max Value and Index Finder
    reg [7:0] max_val;
    reg [3:0] max_idx;
    reg [15:0] data_reg;
    integer i;
    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            max_val <= 8'h00;
            max_idx <= 4'h0;
            data_reg <= 16'h0000;
        end else begin
            data_reg <= data_in;
            max_val <= data_reg[0];
            max_idx <= 4'h0;
            for (i = 1; i < 16; i = i + 1) begin
                if (data_reg[i] > max_val) begin
                    max_val <= data_reg[i];
                    max_idx <= i;
                end
            end
        end
    end

    // Value Selector
    wire [7:0] selected_val;
    value_selector selector_inst (
        .data_in(data_in),
        .decoder_out(decoder_out),
        .selected_val(selected_val)
    );

    // Output Assignments
    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            max_value <= 8'h00;
            max_index <= 4'h0;
            selected_value <= 8'h00;
        end else begin
            max_value <= max_val;
            max_index <= max_idx;
            selected_value <= selected_val;
        end
    end

endmodule

module decoder_4to16 (
    input [1:0] in,
    output reg [15:0] out
);

    always @(*) begin
        case (in)
            2'b00: out = 16'hFFFF;
            2'b01: out = 16'hFFFE;
            2'b10: out = 16'hFFFD;
            2'b11: out = 16'hFFFC;
