module value_selector (
    input [15:0] data_in,
    input [15:0] decoder_out,
    output reg [7:0] selected_val
);

    always @(*) begin
        case (decoder_out)
            16'h8000: selected_val = data_in[0];
            16'h4000: selected_val = data_in[1];
            16'h2000: selected_val = data_in[2];
            16'h1000: selected_val = data_in[3];
            16'h0800: selected_val = data_in[4];
            16'h0400: selected_val = data_in[5];
            16'h0200: selected_val = data_in[6];
            16'h0100: selected_val = data_in[7];
            16'h0080: selected_val = data_in[8];
            16'h0040: selected_val = data_in[9];
            16'h0020: selected_val = data_in[10];
            16'h0010: selected_val = data_in[11];
            16'h0008: selected_val = data_in[12];
            16'h0004: selected_val = data_in[13];
