module fetch_block ( branch_target_i, sum_addr_i, A_i, NPC4_i, S_MUX_PC_BUS_i, 
        PC_o, PC4_o, PC_BUS_pre_BTB, stall_i, take_prediction_i, mispredict_i, 
        predicted_PC, clk, rst );
  input [31:0] branch_target_i;
  input [31:0] sum_addr_i;
  input [31:0] A_i;
  input [31:0] NPC4_i;
  input [1:0] S_MUX_PC_BUS_i;
  output [31:0] PC_o;
  output [31:0] PC4_o;
  output [31:0] PC_BUS_pre_BTB;
  input [31:0] predicted_PC;
  input stall_i, take_prediction_i, mispredict_i, clk, rst;
  wire   n5;
  wire   [31:0] PC_BUS;

  // flip-flop to hold the current instruction address
  ff32_en_0 PC ( .D(PC_BUS), .en(n5), .clk(clk), .rst(rst), .Q(PC_o) );

  // add 4 to the current instruction address to get the next instruction address
  add4 PCADD ( .IN1(PC_o), .OUT1(PC4_o) );

  // multiplexer to choose between four possible instruction addresses
  mux41_0 MUXTARGET ( .IN0(NPC4_i), .IN1(A_i), .IN2(sum_addr_i), .IN3(
        branch_target_i), .CTRL(S_MUX_PC_BUS_i), .OUT1(PC_BUS_pre_BTB) );

  // multiplexer to choose between two possible instruction addresses
  mux41_1 MUXPREDICTION ( .IN0(PC4_o), .IN1(predicted_PC), .IN2(PC_BUS_pre_BTB), .IN3(PC_BUS_pre_BTB), .CTRL({mispredict_i, take_prediction_i}), .OUT1(PC_BUS) );

  // inverter to stall the processor if necessary
  INV_X1 U1 ( .A(stall_i), .ZN(n5) );
endmodule

module priority_encoder (
    input [7:0] w, x, y, z, // Inputs from the 4:1 multiplexer module
    output [7:0] min // Output of the minimum value
);

wire [7:0] temp1, temp2, temp3, temp4, temp5, temp6;

assign temp1 = (w < x) ? w : x;
assign temp2 = (y < z) ? y : z;
assign temp3 = (temp1 < temp2) ? temp1 : temp2;
assign temp4 = (temp3 < w) ? temp3 : w;
assign temp5 = (temp4 < x) ? temp4 : x;
assign temp6 = (temp5 < y) ? temp5 : y;

assign min = (temp6 < z) ? temp6 : z;

endmodule

module mux_encoder (
    input [7:0] a, b, c, d, // Inputs for the 4:1 multiplexer module
    output [7:0] w, x, y, z, // Outputs from the 4:1 multiplexer module
    output [7:0] min // Output from the priority encoder module
);

wire [7:0] temp1, temp2, temp3;

mux_4_1 mux (
    .a(a),
    .b(b),
    .c(c),
    .d(d),
    .w(w),
    .x(x),
    .y(y),
    .z(z)
);

priority_encoder encoder (
    .w(w),
    .x(x),
    .y(y),
    .z(z),
    .min(min)
);

assign temp1 = (w < x) ? w : x;
assign temp2 = (y < z) ? y : z;
assign temp3 = (temp1 < temp2) ? temp1 : temp2;

assign out = (select == 1) ? temp3 : min;

endmodule

module mux_4_1 (
    input [7:0] a, b, c, d, // Inputs for the 4:1 multiplexer module
    output [7:0] w, x, y, z, // Outputs from the 4:1 multiplexer module
    input [1:0] select // Select input for the 4:1 multiplexer module
);

assign w = (select == 2'b00) ? a : ((select == 2'b01) ? b : ((select == 2'b10) ? c : d));
assign x = (select == 2'b00) ? b : ((select == 2'b01) ? a : ((select == 2'b10) ? d : c));
assign y = (select == 2'b00) ? c : ((select == 2'b01) ? d : ((select == 2'b10) ? a : b));
assign z = (select == 2'b00) ? d : ((select == 2'b01) ? c : ((select == 2'b10) ? b : a));

endmodule

