    output [7:0] min, // 8-bit output from the priority encoder module
    input select, // Select input to choose between the priority encoder output and the selected input from the 4:1 multiplexer module
    output [7:0] out // 8-bit output from the functional module
);

mux_encoder mux_encoder (
