    output wire jc3,
    input wire jc4
);

    // IOBUF (to be transferred)
    wire io_i;
    wire io_o;
    wire io_t;

    assign io_o = jc2;
    assign jc2 = (io_t == 1'b0) ? io_i : 1'bz;

    // SW0 controls IOBUF.I
    assign io_i = sw[0];
    // SW1 controls IOBUF.T
    assign io_t = sw[1];
    // SW2 controls OBUF.I (JC.3)
    assign jc3 = sw[2];

    // LED0 indicates IOBUF.O
    assign led[0] = io_o;

    // LED1 is connected to JC.1
    assign led[1] = jc1;

