module multiplier (
    input [7:0] A,
    input [7:0] B,
    output reg [15:0] Q
);

reg [7:0] shift_reg;
reg [15:0] add_reg;

always @ (A or B) begin
    shift_reg = B;
    add_reg = 0;
    for (i = 0; i < 8; i = i + 1) begin
        if (A[i] == 1) begin
            add_reg = add_reg + (shift_reg << i);
        end
    end
    Q = add_reg;
end

endmodule

module decoder_4to16_pipeline (
    input A, B,
    output reg [15:0] Y
);

reg [1:0] stage1_A, stage1_B;
reg [3:0] stage2_A, stage2_B;
reg [7:0] stage3_A, stage3_B;

always @(posedge A or posedge B) begin
    stage1_A <= A;
    stage1_B <= B;
end

always @(posedge stage1_A or posedge stage1_B) begin
    stage2_A <= stage1_A;
    stage2_B <= stage1_B;
end

always @(posedge stage2_A or posedge stage2_B) begin
    stage3_A <= stage2_A;
    stage3_B <= stage2_B;
end

always @(posedge stage3_A or posedge stage3_B) begin
    if (stage3_A == 0 && stage3_B == 0) begin
        Y <= 16'b0000000000000001;
    end else if (stage3_A == 0 && stage3_B == 1) begin
        Y <= 16'b0000000000000010;
    end else if (stage3_A == 1 && stage3_B == 0) begin
        Y <= 16'b0000000000000100;
    end else if (stage3_A == 1 && stage3_B == 1) begin
        Y <= 16'b1000000000000000;
    end
end

endmodule

