module shift_and_sum (
    input [3:0] A,
    input [3:0] B,
    input clk,
    input up_down,
    output reg [7:0] out
);
    reg [3:0] shifted_A;
    reg [3:0] shifted_B;
    reg [3:0] counter1_out;
    reg [3:0] counter2_out;
    reg [3:0] binary_adder_out;

    up_down_counter counter1 (.clk(clk), .up_down(up_down), .count(counter1_out));
    up_down_counter counter2 (.clk(clk), .up_down(up_down), .count(counter2_out));

    binary_adder adder (.A(counter1_out), .B(counter2_out), .sum(binary_adder_out));

    always @(posedge clk) begin
        if (B > 3) begin
            shifted_A <= A >> B;
        end else begin
            shifted_A <= A << B;
        end
        shifted_B <= B;
        out <= {binary_adder_out, shifted_A, shifted_B};
    end
endmodule

module debounce_circuit (
    input clk,
    input [7:0] in,
    output reg q
);

reg [7:0] in_reg;
reg edge_detect, edge_detect_reg;
reg [1:0] flip_flop;
reg [3:0] counter;

always @(posedge clk) begin
    in_reg <= in;
    edge_detect_reg <= edge_detect;

    // Edge detector
    if (in_reg != in_reg[7:1]) begin
        edge_detect <= 1;
    end else begin
        edge_detect <= 0;
    end

    // Dual-edge triggered flip-flop
    if (edge_detect_reg == 1 && flip_flop == 0) begin
        flip_flop <= 1;
    end else if (edge_detect_reg == 1 && flip_flop == 1) begin
        flip_flop <= 0;
    end

    // Debounce counter
    if (flip_flop == 1 && counter < 4) begin
        counter <= counter + 1;
    end else if (flip_flop == 0) begin
        counter <= 0;
    end

    // Output
    if (counter == 4) begin
        q <= edge_detect & flip_flop;
    end
end

endmodule

