)(
    input  wire                  clk,
    input  wire                  reset,
    input  wire                  ce,
    input  wire [din0_WIDTH-1:0] din0,
    input  wire [din1_WIDTH-1:0] din1,
    output wire [dout_WIDTH-1:0] dout
);

    wire [31:0] sum [0:NUM_STAGE-1];
    wire [31:0] carry [0:NUM_STAGE-1];
    wire [31:0] din0_pipe [0:NUM_STAGE-1];
    wire [31:0] din1_pipe [0:NUM_STAGE-1];
    wire [31:0] sum_pipe [0:NUM_STAGE-1];
    wire [31:0] carry_pipe [0:NUM_STAGE-1];

    assign din0_pipe[0] = din0==='bx ? 'b0 : din0;
    assign din1_pipe[0] = din1==='bx ? 'b0 : din1;

    generate
        genvar i;
        for (i = 0; i < NUM_STAGE; i = i + 1) begin : stage
            feedforward_ap_fadd_3_full_dsp_32 adder (
                .aclk                 ( clk ),
                .aclken               ( ce ),
                .s_axis_a_tvalid      ( i == 0 ? 1'b1 : sum_pipe[i-1] != 'bx ),
                .s_axis_a_tdata       ( i == 0 ? din0_pipe[i] : sum_pipe[i-1] ),
                .s_axis_b_tvalid      ( i == 0 ? 1'b1 : din1_pipe[i] != 'bx ),
                .s_axis_b_tdata       ( i == 0 ? din1_pipe[i] : din1_pipe[i] ),
                .m_axis_result_tvalid ( sum_pipe[i] != 'bx ),
                .m_axis_result_tdata  ( sum_pipe[i] ),
                .m_axis_carry_tdata   ( carry_pipe[i] )
            );

            assign din0_pipe[i+1] = i == NUM_STAGE-1 ? 'b0 : sum_pipe[i];
            assign din1_pipe[i+1] = i == NUM_STAGE-1 ? 'b0 : carry_pipe[i];
        end
    endgenerate

    assign dout = sum_pipe[NUM_STAGE-1] != 'bx ? sum_pipe[NUM_STAGE-1] : 'b0;

endmodule

module traffic_signal_controller (
  input clk,
  input areset,
  input north_south,
  input east_west,
  input pedestrian_button,
  input emergency_stop,
  output reg north_south_green,
  output reg east_west_green,
  output reg pedestrian_walk,
  output reg emergency_vehicle
);

  // define states
  parameter NORTH_SOUTH_GREEN = 2'b00;
  parameter NORTH_SOUTH_YELLOW = 2'b01;
  parameter EAST_WEST_GREEN = 2'b10;
  parameter EAST_WEST_YELLOW = 2'b11;
  parameter PEDESTRIAN_WALK = 2'b100;

  reg [2:0] state;

  always @(posedge clk) begin
    if (areset) begin
      state <= NORTH_SOUTH_GREEN;
      north_south_green <= 1;
      east_west_green <= 0;
      pedestrian_walk <= 0;
      emergency_vehicle <= 0;
    end else begin
      case (state)
        NORTH_SOUTH_GREEN: begin
          if (pedestrian_button) begin
            state <= PEDESTRIAN_WALK;
            north_south_green <= 0;
            east_west_green <= 0;
            pedestrian_walk <= 1;
            emergency_vehicle <= 0;
          end else if (emergency_stop) begin
            state <= EAST_WEST_GREEN;
            north_south_green <= 0;
            east_west_green <= 1;
            pedestrian_walk <= 0;
            emergency_vehicle <= 1;
          end else if (!north_south && east_west) begin
            state <= EAST_WEST_YELLOW;
            north_south_green <= 0;
            east_west_green <= 1;
            pedestrian_walk <= 0;
            emergency_vehicle <= 0;
          end
        end
        NORTH_SOUTH_YELLOW: begin
          state <= EAST_WEST_GREEN;
          north_south_green <= 0;
          east_west_green <= 1;
          pedestrian_walk <= 0;
          emergency_vehicle <= 0;
        end
        EAST_WEST_GREEN: begin
          if (pedestrian_button) begin
            state <= PEDESTRIAN_WALK;
            north_south_green <= 0;
            east_west_green <= 0;
            pedestrian_walk <= 1;
            emergency_vehicle <= 0;
          end else if (emergency_stop) begin
            state <= NORTH_SOUTH_GREEN;
            north_south_green <= 1;
            east_west_green <= 0;
            pedestrian_walk <= 0;
            emergency_vehicle <= 1;
          end else if (north_south && !east_west) begin
            state <= NORTH_SOUTH_YELLOW;
            north_south_green <= 1;
            east_west_green <= 0;
            pedestrian_walk <= 0;
            emergency_vehicle <= 0;
          end
        end
        EAST_WEST_YELLOW: begin
          state <= NORTH_SOUTH_GREEN;
          north_south_green <= 1;
          east_west_green <= 0;
          pedestrian_walk <= 0;
          emergency_vehicle <= 0;
        end
        PEDESTRIAN_WALK: begin
          state <= NORTH_SOUTH_GREEN;
          north_south_green <= 1;
          east_west_green <= 0;
          pedestrian_walk <= 0;
          emergency_vehicle <= 0;
        end
      endcase
    end
  end

endmodule

module lights_nios2_qsys_0_nios2_oci_im (
    // inputs:
    clk,
    jdo,
    jrst_n,
    reset_n,
    take_action_tracectrl,
    take_action_tracemem_a,
    take_action_tracemem_b,
    take_no_action_tracemem_a,
    trc_ctrl,
    tw,

    // outputs:
    tracemem_on,
    tracemem_trcdata,
    tracemem_tw,
    trc_enb,
    trc_im_addr,
    trc_wrap,
    xbrk_wrap_traceoff
);

    output tracemem_on;
    output [35:0] tracemem_trcdata;
    output tracemem_tw;
    output trc_enb;
    output [6:0] trc_im_addr;
    output trc_wrap;
    output xbrk_wrap_traceoff;
    input clk;
    input [37:0] jdo;
    input jrst_n;
    input reset_n;
    input take_action_tracectrl;
    input take_action_tracemem_a;
    input take_action_tracemem_b;
    input take_no_action_tracemem_a;
    input [15:0] trc_ctrl;
    input [35:0] tw;

    wire tracemem_on;
    wire [35:0] tracemem_trcdata;
    wire tracemem_tw;
    wire trc_enb;
    reg [6:0] trc_im_addr /* synthesis ALTERA_ATTRIBUTE = "SUPPRESS_DA_RULE_INTERNAL=\"D101,D103,R101\""  */;
    wire [35:0] trc_im_data;
    reg [16:0] trc_jtag_addr /* synthesis ALTERA_ATTRIBUTE = "SUPPRESS_DA_RULE_INTERNAL=D101"  */;
    wire trc_on_chip;
    reg trc_wrap /* synthesis ALTERA_ATTRIBUTE = "SUPPRESS_DA_RULE_INTERNAL=\"D101,D103,R101\""  */;
    wire tw_valid;
    wire xbrk_wrap_traceoff;

    assign trc_im_data = tw;

    always @(posedge clk or negedge jrst_n) begin
        if (jrst_n == 0) begin
            trc_im_addr <= 0;
            trc_wrap <= 0;
        end else if (!jrst_n) begin
            trc_im_addr <= 0;
            trc_wrap <= 0;
        end else if (take_action_tracectrl && (jdo[4] | jdo[3])) begin
            if (jdo[4]) trc_im_addr <= 0;
            if (jdo[3]) trc_wrap <= 0;
        end else if (trc_enb & trc_on_chip & tw_valid) begin
            trc_im_addr <= trc_im_addr + 1;
            if (trc_im_addr == 7'd127) trc_wrap <= 1;
            else trc_wrap <= 0;
        end
    end

    always @(posedge clk or negedge reset_n) begin
        if (reset_n == 0) trc_jtag_addr <= 0;
        else if (take_action_tracemem_a || take_no_action_tracemem_a || take_action_tracemem_b) begin
            trc_jtag_addr <= take_action_tracemem_a ? jdo[35:19] : trc_jtag_addr + 1;
        end
    end

    assign trc_enb = trc_ctrl[0];
    assign trc_on_chip = ~trc_ctrl[8];
    assign tw_valid = |trc_im_data[35:32];
    assign xbrk_wrap_traceoff = trc_ctrl[10] & trc_wrap;
    assign tracemem_tw = trc_wrap;
    assign tracemem_on = trc_enb;
    assign tracemem_trcdata = 0;

endmodule

module counter (
  input clk,
  input rst,
  output reg [1:0] count
);

  always @(posedge clk) begin
    if (rst) begin
      count <= 2'b0;
    end else if (count == 2'b11) begin
      count <= 2'b0;
    end else begin
      count <= count + 1;
    end
  end

endmodule

module sync_seq_circuit (
    Q      ,
    CLK_N  ,
    D      ,
    RESET_B
);

    output Q      ;
    input  CLK_N  ;
    input  D      ;
    input  RESET_B;

    reg Q;

    always @ (posedge CLK_N or negedge RESET_B) begin
        if (!RESET_B) begin
            Q <= 0;
        end else begin
            if (D) begin
                Q <= 1;
            end
        end
    end

