module shift_accum_or (
    input clk,
    input reset,
    input [7:0] d,
    input valid_a,
    input ready_b,
    output [7:0] q,
    output valid_b,
    output [9:0] data_out
);

// Shift Register Module
reg [7:0] shift_reg;
always @(posedge clk) begin
    if (reset) begin
        shift_reg <= 8'b0;
    end else begin
        shift_reg <= {d, shift_reg[7:1]};
    end
end

// Accumulator Module
reg [7:0] acc_reg;
reg [2:0] acc_count;
always @(posedge clk) begin
    if (reset) begin
        acc_reg <= 8'b0;
        acc_count <= 3'b0;
    end else begin
        if (valid_a) begin
            acc_reg <= acc_reg + d;
            if (acc_count == 3'b111) begin
                acc_count <= 3'b0;
            end else begin
                acc_count <= acc_count + 1;
            end
        end
    end
end

// OR Module
wire [7:0] or_out;
assign or_out = shift_reg | acc_reg;

// Output Data and Valid Signals
reg [1:0] out_count;
always @(posedge clk) begin
    if (reset) begin
        out_count <= 2'b0;
        valid_b <= 1'b0;
        data_out <= 10'b0;
    end else begin
        if (ready_b && (out_count == 2'b11)) begin
            q <= shift_reg[0];
            valid_b <= 1'b1;
            data_out <= {or_out, valid_b};
            out_count <= 2'b0;
        end else begin
            valid_b <= 1'b0;
            data_out <= {or_out, valid_b};
            out_count <= out_count + 1;
        end
    end
end

endmodule

