module top_module (
    input [2:0] sel, // 3-bit select signal for the multiplexer
    input [3:0] data0, // 4-bit input for data0
    input [3:0] data1, // 4-bit input for data1
    input [3:0] data2, // 4-bit input for data2
    input [3:0] data3, // 4-bit input for data3
    input [3:0] data4, // 4-bit input for data4
    input [3:0] data5, // 4-bit input for data5
    input [31:0] a, // 32-bit input for adder module
    input [31:0] b, // 32-bit input for adder module
    output [7:0] final_output // 8 most significant bits of the output from the functional module
);

// 6-to-1 multiplexer
wire [3:0] mux_output;
assign mux_output = (sel == 3'b000) ? data0 :
                    (sel == 3'b001) ? data1 :
                    (sel == 3'b010) ? data2 :
                    (sel == 3'b011) ? data3 :
                    (sel == 3'b100) ? data4 :
                    (sel == 3'b101) ? data5 :
                    4'b0001;

// 32-bit adder
wire [31:0] adder_output;
CLA_4bit CLA0(a[3:0], b[3:0], 1'b0, adder_output[3:0], adder_output[4]);
CLA_4bit CLA1(a[7:4], b[7:4], CLA0[4], adder_output[7:4], adder_output[8]);
CLA_4bit CLA2(a[11:8], b[11:8], CLA1[4], adder_output[11:8], adder_output[12]);
CLA_4bit CLA3(a[15:12], b[15:12], CLA2[4], adder_output[15:12], adder_output[16]);
CLA_4bit CLA4(a[19:16], b[19:16], CLA3[4], adder_output[19:16], adder_output[20]);
CLA_4bit CLA5(a[23:20], b[23:20], CLA4[4], adder_output[23:20], adder_output[24]);
CLA_4bit CLA6(a[27:24], b[27:24], CLA5[4], adder_output[27:24], adder_output[28]);
CLA_4bit CLA7(a[31:28], b[31:28], CLA6[4], adder_output[31:28], adder_output[32]);

// Functional module
wire [39:0] func_output;
assign func_output = {40'b0, mux_output} + {40'b0, adder_output};
priority_encoder pe(func_output[47:40], final_output);

endmodule

// 4-bit carry-lookahead adder module
module CLA_4bit(a, b, cin, sum, cout);
input [3:0] a, b;
input cin;
output [3:0] sum;
output cout;

assign sum = a ^ b ^ cin;
assign cout = (a & b) | (a & cin) | (b & cin);

endmodule

// Priority encoder module
module priority_encoder(input [7:0] in, output reg [2:0] out);
always @(*) begin
    case(in)
        8'b10000000: out = 3'b000;
        8'b01000000, 8'b00100000, 8'b00010000, 8'b00001000: out = 3'b001;
        8'b00000100, 8'b00000010, 8'b00000001: out = 3'b010;
        default: out = 3'b011;
    endcase
end

endmodule

