assign MusicOffset = Choice[1] ? Music3 : (Choice[0]? Music1 : Music2);

reg [DataLength-1:0] Keys [0:MemorySize-1];
reg [DataLength-1:0] Times [0:MemorySize-1];
//stores key number and its time duration
