		Keys[14]<=3; Times[14]<=2;
		Keys[15]<=1; Times[15]<=1;
		Keys[16]<=2; Times[16]<=1;
		Keys[17]<=1; Times[17]<=1;
		Keys[18]<=3; Times[18]<=4;
