    S_AXI_WREADY,
    S_AXI_BRESP,
    S_AXI_BVALID,
    S_AXI_AWREADY,
    host_interrupt,
    user_clk,
    user_wren,
    user_wstrb,
    user_rden,
    user_rd_data,
    user_wr_data,
    user_addr,
    user_irq
  );
  input S_AXI_ACLK;
  input S_AXI_ARESETN;
  input [31:0] S_AXI_AWADDR;
  input S_AXI_AWVALID;
  input [31:0] S_AXI_WDATA;
  input [3:0] S_AXI_WSTRB;
  input S_AXI_WVALID;
  input S_AXI_BREADY;
  input [31:0] S_AXI_ARADDR;
  input S_AXI_ARVALID;
  input S_AXI_RREADY;
  output S_AXI_ARREADY;
  output [31:0] S_AXI_RDATA;
  output [1:0] S_AXI_RRESP;
  output S_AXI_RVALID;
  output S_AXI_WREADY;
  output [1:0] S_AXI_BRESP;
  output S_AXI_BVALID;
  output S_AXI_AWREADY;
  output host_interrupt;
  output user_clk;
  output user_wren;
  output [3:0] user_wstrb;
  output user_rden;
  input [31:0] user_rd_data;
  output [31:0] user_wr_data;
  output [31:0] user_addr;
  input user_irq;

  reg [31:0] mem [0:1023];
  reg [31:0] read_data;
  reg [31:0] write_data;
  reg [31:0] read_addr;
  reg [31:0] write_addr;
  reg [1:0] read_resp;
  reg [1:0] write_resp;
  reg [3:0] write_strobe;
  reg [1:0] read_valid;
  reg [1:0] write_valid;

  assign S_AXI_ARREADY = 1;
  assign S_AXI_RDATA = read_data;
  assign S_AXI_RRESP = read_resp;
  assign S_AXI_RVALID = read_valid;
  assign S_AXI_WREADY = 1;
  assign S_AXI_BRESP = write_resp;
  assign S_AXI_BVALID = write_valid;
  assign S_AXI_AWREADY = 1;

  always @(posedge S_AXI_ACLK) begin
    if (!S_AXI_ARESETN) begin
      read_data <= 0;
      write_data <= 0;
      read_addr <= 0;
      write_addr <= 0;
      read_resp <= 0;
      write_resp <= 0;
      write_strobe <= 0;
      read_valid <= 0;
      write_valid <= 0;
    end else begin
      if (S_AXI_ARVALID && !read_valid) begin
        read_addr <= S_AXI_ARADDR;
        read_valid <= 1;
        read_resp <= 0;
      end else if (user_rden && read_valid) begin
        read_data <= mem[read_addr];
        read_valid <= 0;
        read_resp <= 0;
      end else if (S_AXI_AWVALID && !write_valid) begin
        write_addr <= S_AXI_AWADDR;
        write_strobe <= S_AXI_WSTRB;
        write_data <= S_AXI_WDATA;
        write_valid <= 1;
        write_resp <= 0;
      end else if (user_wren && write_valid) begin
        mem[write_addr] <= write_data;
        write_valid <= 0;
        write_resp <= 0;
      end else if (S_AXI_BREADY && write_valid) begin
        write_valid <= 0;
        write_resp <= 0;
      end else if (S_AXI_RREADY && read_valid) begin
        read_valid <= 0;
        read_resp <= 0;
      end
    end
  end

  assign user_clk = S_AXI_ACLK;
  assign user_wren = write_valid;
  assign user_wstrb = write_strobe;
  assign user_rden = read_valid;
  assign user_rd_data = read_data;
  assign user_wr_data = write_data;
  assign user_addr = read_addr;

  assign host_interrupt = user_irq;

endmodule

module reverse_byte_order_pipeline (
    input [31:0] in_vec,
    output [31:0] out_vec
);

reg [31:0] stage1_out;
reg [31:0] stage2_out;
reg [31:0] stage3_out;

// Stage 1
always @(*) begin
    stage1_out[7:0] = in_vec[15:8];
    stage1_out[15:8] = in_vec[7:0];
    stage1_out[23:16] = in_vec[31:24];
    stage1_out[31:24] = in_vec[23:16];
end

// Stage 2
always @(*) begin
    stage2_out[7:0] = stage1_out[23:16];
    stage2_out[15:8] = stage1_out[31:24];
    stage2_out[23:16] = stage1_out[7:0];
    stage2_out[31:24] = stage1_out[15:8];
end

// Stage 3
always @(*) begin
    stage3_out[7:0] = stage2_out[15:8];
    stage3_out[15:8] = stage2_out[7:0];
    stage3_out[23:16] = stage2_out[31:24];
    stage3_out[31:24] = stage2_out[23:16];
end

assign out_vec = stage3_out;

endmodule

