module barrel_shifter (
    input [7:0] in,
    input [2:0] shift_amount,
    input shift_direction,
    output [7:0] out
);
    reg [7:0] shifted_value;

    always @(*) begin
        if (shift_direction == 1'b0) begin
            shifted_value = in << shift_amount;
        end else begin
            shifted_value = in >> shift_amount;
        end
    end

    assign out = shifted_value;

endmodule

