        product = in1 * in2;
    end

    assign out = product;

endmodule

module freq_synth (
  input ref_clk,
  input [n-1:0] fcw,
  input rst,
  output synth_clk
);

parameter f_ref = 50e6; // frequency of reference clock signal
parameter f_max = 500e6; // maximum frequency of synthesized clock signal
parameter n = 16; // number of bits in the frequency control word

// specify PLL or DDS architecture using a parameter
// PLL: pll_based = 1, dds_based = 0
// DDS: pll_based = 0, dds_based = 1
parameter pll_based = 1;
parameter dds_based = 0;

reg [31:0] phase_accumulator;
reg [n-1:0] phase_increment;
reg [31:0] dds_output;
reg [31:0] pll_output;
reg [31:0] pll_feedback;
reg [31:0] pll_error;
reg [31:0] pll_accumulator;
reg [31:0] pll_increment;
reg [31:0] pll_divider;
reg [31:0] pll_multiplier;
reg [31:0] pll_max;
reg [31:0] pll_min;
reg [31:0] pll_threshold;
reg [1:0] pll_state;

assign synth_clk = pll_based ? pll_output : dds_output;

always @(posedge ref_clk or posedge rst) begin
  if (rst) begin
    phase_accumulator <= 0;
    dds_output <= 0;
    pll_output <= 0;
    pll_feedback <= 0;
    pll_error <= 0;
    pll_accumulator <= 0;
    pll_increment <= 0;
    pll_divider <= 0;
    pll_multiplier <= 0;
    pll_max <= 0;
    pll_min <= 0;
    pll_threshold <= 0;
    pll_state <= 0;
  end else begin
    if (pll_based) begin
      // PLL-based frequency synthesizer
      case (pll_state)
        0: begin // IDLE
          pll_output <= 0;
          pll_state <= 1;
        end
        1: begin // ACQUIRE
          pll_feedback <= synth_clk;
          pll_error <= fcw - (pll_feedback / pll_divider);
          pll_accumulator <= pll_accumulator + pll_error;
          if (pll_accumulator > pll_threshold) begin
            pll_state <= 2;
          end
        end
        2: begin // LOCKED
          pll_feedback <= synth_clk;
          pll_error <= fcw - (pll_feedback / pll_divider);
          pll_accumulator <= pll_accumulator + pll_error;
          pll_increment <= pll_multiplier * pll_error;
          pll_output <= pll_output + pll_increment;
          if (pll_output > pll_max) begin
            pll_output <= pll_max;
          end else if (pll_output < pll_min) begin
            pll_output <= pll_min;
          end
        end
      endcase
    end else if (dds_based) begin
      // DDS-based frequency synthesizer
      phase_increment <= (fcw * 2^32) / f_ref;
      phase_accumulator <= phase_accumulator + phase_increment;
      dds_output <= $sin(phase_accumulator[31:0]);
    end
  end
end

// PLL parameters
initial begin
  if (pll_based) begin
    pll_divider = 1;
    pll_multiplier = 1;
    pll_max = (f_max * 2^32) / f_ref;
    pll_min = -pll_max;
    pll_threshold = 2^30;
  end
end

endmodule

module pipeline (
  input clk,
  input reset,
  input [31:0] data1,
  input [31:0] data2,
  input [7:0] instruction,
  input [2:0] stage,
  input [3:0] rs1,
  input [3:0] rs2,
  input [3:0] rd,
  output reg [31:0] regfile [15:0]
);

reg [31:0] pc;
reg [31:0] instruction_reg;
reg [31:0] alu_result;
reg [31:0] data2_reg;
reg [4:0] rs1_reg;
reg [4:0] rs2_reg;
reg [4:0] rd_reg;
reg [1:0] stage_reg;

always @(posedge clk) begin
  if (reset) begin
    pc <= 0;
    instruction_reg <= 0;
    alu_result <= 0;
    data2_reg <= 0;
    rs1_reg <= 0;
    rs2_reg <= 0;
    rd_reg <= 0;
    stage_reg <= 0;
  end else begin
    case (stage_reg)
      0: begin // Instruction Fetch
        instruction_reg <= {16'b0, instruction};
        pc <= pc + 1;
        stage_reg <= 1;
      end
      1: begin // Instruction Decode and Execution
        rs1_reg <= rs1;
        rs2_reg <= rs2;
        rd_reg <= rd;
        data2_reg <= data2;
        case (instruction_reg[7:0])
          8'h00: alu_result <= data1 + data2_reg; // ADD
          8'h01: alu_result <= data1 - data2_reg; // SUB
          8'h02: alu_result <= data1 & data2_reg; // AND
          8'h03: alu_result <= data1 | data2_reg; // OR
          8'h04: alu_result <= data1 ^ data2_reg; // XOR
          8'h05: alu_result <= ~data1; // NOT
          8'h06: alu_result <= data1 << data2_reg; // SLL
          8'h07: alu_result <= data1 >> data2_reg; // SRL
          default: alu_result <= 0;
        endcase
        stage_reg <= 2;
      end
      2: begin // Write Back
        regfile[rd_reg] <= alu_result;
        stage_reg <= 0;
      end
      default: stage_reg <= 0;
    endcase
  end
end

endmodule

