module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [2:0] select1,   // Select input for choosing which bit of the decoder's output to use as input 1
    input [2:0] select2,   // Select input for choosing which bit of the decoder's output to use as input 2
    output reg out);   // Output of the functional module

    reg [3:0] counter;
    wire [7:0] decoder_out;
    wire comp_out;
    wire and_out;

    // Instantiate the 4-bit binary counter
    always @(posedge clk, posedge reset) begin
        if (reset) begin
            counter <= 0;
