    // Instantiate the 4-bit binary comparator
    comparator_4bit comparator_inst (
        .in1(counter),
        .in2(decoder_out[select2]),
        .out(comp_out)
    );

    // Instantiate the AND gate
    assign and_out = comp_out & decoder_out[select1];

    // Assign the output of the AND gate to the output of the module
    always @(posedge clk, posedge reset) begin
        if (reset) begin
            out <= 0;
        end else begin
            out <= and_out;
        end
    end

endmodule

