module DDUC (
  input clk,
  input reset_n,
  input signed [15:0] data_in,
  input signed [15:0] freq_in,
  output signed [15:0] data_out,
  output signed [15:0] freq_out,
  output signed [15:0] phase_out
);

parameter N = 1024; // number of samples in the input signal
parameter M = 1024; // number of samples in the output signal
parameter D = 2; // decimation rate for the DDC
parameter U = 2; // upsampling rate for the DUC
parameter F_sample = 100e6; // sampling frequency 
parameter F_in = 10e6; // input frequency
parameter F_out = 1e6; // output frequency

reg signed [15:0] data_in_reg [N-1:0];
reg signed [15:0] data_out_reg [M-1:0];
reg signed [15:0] freq_out_reg [M-1:0];
reg signed [15:0] phase_out_reg [M-1:0];

reg [31:0] phase_acc_reg;
reg [31:0] phase_inc_reg;

reg [31:0] freq_in_reg;
reg [31:0] freq_out_reg;

reg [31:0] freq_ratio_reg;
reg [31:0] phase_offset_reg;

integer i;

always @(posedge clk or negedge reset_n) begin
  if (~reset_n) begin
    // reset registers
    for (i = 0; i < N; i = i + 1) begin
      data_in_reg[i] <= 0;
    end
    for (i = 0; i < M; i = i + 1) begin
      data_out_reg[i] <= 0;
      freq_out_reg[i] <= 0;
      phase_out_reg[i] <= 0;
    end
    phase_acc_reg <= 0;
    phase_inc_reg <= 0;
    freq_in_reg <= 0;
    freq_out_reg <= 0;
    freq_ratio_reg <= 0;
    phase_offset_reg <= 0;
  end else begin
    // shift input data register
    for (i = N-1; i > 0; i = i - 1) begin
      data_in_reg[i] <= data_in_reg[i-1];
    end
    data_in_reg[0] <= data_in;

    // compute frequency ratio and phase offset
    freq_in_reg <= freq_in * (N/U);
    freq_out_reg <= freq_out * (M/D);
    freq_ratio_reg <= freq_in_reg / freq_out_reg;
    phase_offset_reg <= $signed(phase_acc_reg[31:16]) - $signed(phase_acc_reg[15:0]);

    // compute phase increment
    phase_inc_reg <= freq_ratio_reg * (1 << 16);

    // compute output data and phase
    for (i = 0; i < M; i = i + 1) begin
      // compute output frequency
      freq_out_reg[i] <= freq_out;

      // compute output phase
      phase_out_reg[i] <= $signed(phase_acc_reg[31:16]) - phase_offset_reg;

      // compute output data
      data_out_reg[i] <= data_in_reg[i*D/U] * $signed($cos(phase_acc_reg[31:16])) - data_in_reg[i*D/U] * $signed($sin(phase_acc_reg[31:16]));

      // update phase accumulator
      phase_acc_reg <= phase_acc_reg + phase_inc_reg;
    end

    // output data and phase
    data_out <= data_out_reg[M-1];
    freq_out <= freq_out_reg[M-1];
    phase_out <= phase_out_reg[M-1];
  end
end

endmodule

