/*
 * This module implements a timer that prevents a busy bank
 * from being precharged. The counter should prevent a bank
 * from being precharged for a certain amount of time after
 * it has been accessed.
 */

module hpdmc_banktimer(
    input sys_clk,
    input sdram_rst,

    input read,
    input write,
    output reg [3:0] precharge_safe,

    input tim_cas,
    input [1:0] tim_wr
);

reg [2:0] precharge_counter;
always @(posedge sys_clk) begin
    if(sdram_rst) begin
        precharge_counter <= 3'd0;
        precharge_safe <= 4'b1111;
    end else begin
        if(read | write) begin
            precharge_counter <= {1'b1, tim_cas, ~tim_cas};
            precharge_safe <= precharge_safe & ~{1'b0, read, write, read & write};
        end else begin
            if(precharge_counter == 3'd1)
                precharge_safe <= precharge_safe | {1'b0, read, write, read & write};
            if(~precharge_safe[0])
                precharge_counter <= precharge_counter - 3'd1;
        end
    end
end

endmodule

module MMU (
  input [31:0] virtual_address,
  input read_enable,
  input write_enable,
  output [31:0] physical_address,
  output [31:0] memory_data_in,
  input [31:0] memory_data_out
);

  // Define the virtual-to-physical address mapping
  parameter [31:0] PHYSICAL_BASE = 32'h00000000;

  // Calculate the physical address based on the virtual address
  assign physical_address = virtual_address + PHYSICAL_BASE;

  // Control read and write operations on the memory_data_in and memory_data_out signals
  assign memory_data_in = write_enable ? virtual_address : 32'h00000000;
  assign memory_data_out = read_enable ? memory_data_out : 32'h00000000;

endmodule

