module tone_generator (
  input [1:0] tone_type,
  input [11:0] tone_freq,
  input [15:0] tone_dur,
  output tone_waveform
);

  reg [15:0] counter;
  reg [11:0] sine_wave;
  reg [11:0] square_wave;
  reg [3:0] dtmf_wave;
  reg [1:0] dtmf_freq;
  reg [1:0] dtmf_phase;
  reg [3:0] dtmf_counter;
  reg [3:0] dtmf_duration;

  always @ (posedge clk) begin
    if (tone_type == 2'b00) begin // DTMF tone
      if (dtmf_duration < tone_dur) begin
        case (dtmf_freq)
          2'b00: dtmf_wave = 8'h6D; // 697 Hz
          2'b01: dtmf_wave = 8'h7C; // 770 Hz
          2'b10: dtmf_wave = 8'h8B; // 852 Hz
          2'b11: dtmf_wave = 8'h9A; // 941 Hz
        endcase

        if (dtmf_phase == 2'b00) begin
          tone_waveform = dtmf_wave[dtmf_counter];
          dtmf_counter = dtmf_counter + 1;
          if (dtmf_counter == 4) begin
            dtmf_counter = 0;
            dtmf_freq = dtmf_freq + 1;
            if (dtmf_freq == 2'b11) begin
              dtmf_freq = 2'b00;
            end
          end
        end
        else begin
          tone_waveform = 8'h00;
        end

        dtmf_phase = dtmf_phase + 1;
        if (dtmf_phase == 2'b10) begin
          dtmf_phase = 2'b00;
        end

        counter = counter + 1;
        if (counter == tone_freq) begin
          counter = 0;
          dtmf_duration = dtmf_duration + 1;
        end
      end
      else begin
        tone_waveform = 8'h00;
      end
    end
    else if (tone_type == 2'b01) begin // Sine wave
      if (counter < tone_dur * tone_freq / 1000) begin
        sine_wave = $sin(2 * $pi * tone_freq * counter / 100000);
        tone_waveform = {sine_wave[11:4], 4'h0};
        counter = counter + 1;
      end
      else begin
        tone_waveform = 8'h00;
      end
    end
    else if (tone_type == 2'b10) begin // Square wave
      if (counter < tone_dur * tone_freq / 1000) begin
        if (counter < tone_freq / 2) begin
          square_wave = 12'hFFF;
        end
        else begin
          square_wave = 12'h000;
        end
        tone_waveform = {square_wave[11:0], 4'h0};
        counter = counter + 1;
      end
      else begin
        tone_waveform = 8'h00;
      end
    end
    else begin
      tone_waveform = 8'h00;
    end
  end

endmodule

module top_module( 
    input [255:0] in,
    input [7:0] sel,
    output out );

    wire [7:0] priority;
    wire [7:0] priority_inv;
    wire [7:0] sel_tree;
    wire [7:0] sel_inv;
    wire [255:0] in_tree;

    // Priority Encoder
    priority_encoder pe(
        .in(sel),
        .out(priority)
    );

    // Inverter for Priority Encoder Output
    assign priority_inv = ~priority;

    // Binary Tree for Input Vector
    binary_tree bt(
        .in(in),
        .out(in_tree)
    );

    // Binary Tree for Selection Vector
    binary_tree bt_sel(
        .in(priority_inv),
        .out(sel_tree)
    );

    // Inverter for Selection Vector
    assign sel_inv = ~sel_tree;

    // Final Multiplexer
    assign out = sel_inv & in_tree;

endmodule

// Priority Encoder
module priority_encoder(
    input [7:0] in,
    output [7:0] out
);
    assign out = {in[7], in[6], in[5], in[4], in[3], in[2], in[1], in[0]};
endmodule

// Binary Tree
module binary_tree(
    input [255:0] in,
    output [255:0] out
);
    genvar i;
    generate
        for (i = 0; i < 128; i = i + 1) begin : level1
            assign out[2*i] = in[2*i] | in[2*i+1];
        end
        for (i = 0; i < 64; i = i + 1) begin : level2
            assign out[4*i] = out[2*i] | out[2*i+1];
        end
        for (i = 0; i < 32; i = i + 1) begin : level3
            assign out[8*i] = out[4*i] | out[4*i+1];
        end
        for (i = 0; i < 16; i = i + 1) begin : level4
            assign out[16*i] = out[8*i] | out[8*i+1];
        end
        for (i = 0; i < 8; i = i + 1) begin : level5
            assign out[32*i] = out[16*i] | out[16*i+1];
        end
        for (i = 0; i < 4; i = i + 1) begin : level6
            assign out[64*i] = out[32*i] | out[32*i+1];
        end
        for (i = 0; i < 2; i = i + 1) begin : level7
            assign out[128*i] = out[64*i] | out[64*i+1];
        end
        assign out[0] = out[128] | out[129];
    endgenerate
endmodule

