  XOR2_X1 U2 (.A(w1), .B(Ci), .ZN(S));
  AND2_X1 U3 (.A(A), .B(B), .ZN(w2));
  AND2_X1 U4 (.A(w1), .B(Ci), .ZN(w3));
  OR2_X1 U5 (.A(w2), .B(w3), .ZN(Co));
endmodule

module communication_controller (
    input [7:0] interrupt_inputs,
    input [31:0] data_input,
    output reg [35:0] output_data
);

    // Priority Encoder
    wire [7:0] priority;
    assign priority = ~interrupt_inputs;

    reg [2:0] interrupt_number;
    always @* begin
        case(priority)
            8'b00000001: interrupt_number = 3'b000;
            8'b00000010: interrupt_number = 3'b001;
            8'b00000100: interrupt_number = 3'b010;
            8'b00001000: interrupt_number = 3'b011;
            8'b00010000: interrupt_number = 3'b100;
            8'b00100000: interrupt_number = 3'b101;
            8'b01000000: interrupt_number = 3'b110;
            8'b10000000: interrupt_number = 3'b111;
            default: interrupt_number = 3'b000;
        endcase
    end

    // Byte Order Reverser
    wire [7:0] byte0 = data_input[7:0];
    wire [7:0] byte1 = data_input[15:8];
    wire [7:0] byte2 = data_input[23:16];
    wire [7:0] byte3 = data_input[31:24];

    reg [31:0] reversed_data;
    always @* begin
        reversed_data = {byte3, byte2, byte1, byte0};
    end

    // Output Concatenation
    always @* begin
        output_data = {interrupt_number, reversed_data};
    end

endmodule

