module max_finder (
    input [15:0] D,
    output reg [15:0] max
);
    always @(*) begin
        if (D[15] == 1) begin
            max = {16'b0, D[15:0]};
        end else begin
            max = D;
        end
        for (i = 14; i >= 0; i = i - 1) begin
            if (max[i] < max[i+1]) begin
                max[i] = max[i+1];
            end
        end
    end
endmodule

module signed_mag_sqrt (
    input [15:0] D,
    output reg [3:0] sqrt
);
    always @(*) begin
        if (D[15] == 1) begin
            sqrt = 4'b0;
        end else begin
            sqrt = 4'b1;
            for (i = 2; i >= 0; i = i - 1) begin
                sqrt[i] = (sqrt + (1 << (2*i))) <= D[i+12: i+9];
                sqrt = sqrt + (sqrt[i] << i);
            end
        end
    end
endmodule

module functional_module (
    input [15:0] max,
