    end
endmodule

module top_module (
    input clk,
    input reset, // Synchronous active-high reset
    input [15:0] D, // 16-bit input
    output reg [15:0] max, // 16-bit output from max finder module
    output reg [3:0] sqrt, // 4-bit output from signed magnitude square root module
    output reg error, // Error flag output for negative input
    output reg [19:0] sum // 20-bit output from functional module
);
    max_finder max_finder_inst (
        .D(D),
        .max(max)
    );
    signed_mag_sqrt sqrt_inst (
        .D(max),
        .sqrt(sqrt)
    );
    functional_module functional_inst (
        .max(max),
        .sqrt(sqrt),
        .sum(sum)
    );
    always @(posedge clk) begin
        if (reset) begin
            max <= 16'b0;
            sqrt <= 4'b0;
            error <= 1'b0;
            sum <= 20'b0;
        end else begin
            if (D[15] == 1) begin
                error <= 1'b1;
                max <= 16'b0;
                sqrt <= 4'b0;
            end else begin
                error <= 1'b0;
                max <= max;
                sqrt <= sqrt;
            end
            sum <= sum;
        end
    end
endmodule

