module gray_counter (
    input clk,
    input reset,
    output reg [2:0] gray_code
);
    reg [2:0] binary_code;
    wire [2:0] gray_code_next;
    wire shift_register_out;

    binary_to_gray binary_to_gray_inst(
        .binary(binary_code),
        .gray(gray_code_next)
    );

    shift_register shift_register_inst(
        .clk(clk),
        .data(gray_code_next[2]),
        .out(shift_register_out)
    );

    always @(posedge clk) begin
        if (reset) begin
            binary_code <= 3'b000;
            gray_code <= 3'b000;
        end else begin
            binary_code <= binary_code + 1;
            gray_code <= gray_code_next;
        end
    end

    always @* begin
        case (shift_register_out)
            1'b0: gray_code_next <= {gray_code[1:0], ~gray_code[2]};
            1'b1: gray_code_next <= {gray_code[1:0], gray_code[2]};
        endcase
    end
endmodule

