module HMAC (
  input [l-1:0] msg,
  input [k-1:0] key,
  input [h-1:0] hash,
  output [h-1:0] hmac
);

parameter l = 64; // length of message in bits
parameter k = 128; // length of key in bits
parameter h = 256; // length of hash in bits

// constants used in HMAC computation
parameter [7:0] constant1 = 8'h36;
parameter [7:0] constant2 = 8'h5C;

// preprocess the key by XORing it with constant1 and appending it to the message
wire [l+k-1:0] msg_key_preprocessed;
assign msg_key_preprocessed = {msg, key} ^ {constant1, {k{1'b0}}};

// compute the hash of the preprocessed message and key
wire [h-1:0] hash_msg_key;
hash_function hash_inst1(.data(msg_key_preprocessed), .hash(hash_msg_key));

// preprocess the key again by XORing it with constant2 and appending it to the hash value
wire [h+k-1:0] hash_key_preprocessed;
assign hash_key_preprocessed = {hash_msg_key, key} ^ {constant2, {k{1'b0}}};

// compute the final hash value, which is the HMAC value
hash_function hash_inst2(.data(hash_key_preprocessed), .hash(hmac));

endmodule

