module binary_to_7seg(clk, binary_in, seven_seg_out);
  input clk;
  input [31:0]binary_in;
  output [6:0]seven_seg_out;

  reg [3:0] hex_out;

  always @(posedge clk) begin
    if (binary_in > 32'hFFFFFFFF) begin
      hex_out <= 4'b1110; // E
    end else if (binary_in < 0) begin
      hex_out <= 4'b1111; // F
    end else begin
      case (binary_in[31:28])
        4'b0000: hex_out <= 4'b0011; // 0
        4'b0001: hex_out <= 4'b0000; // 1
        4'b0010: hex_out <= 4'b1011; // 2
        4'b0011: hex_out <= 4'b1001; // 3
        4'b0100: hex_out <= 4'b1100; // 4
        4'b0101: hex_out <= 4'b1001; // 5
        4'b0110: hex_out <= 4'b1111; // 6
        4'b0111: hex_out <= 4'b0001; // 7
        4'b1000: hex_out <= 4'b1111; // 8
        4'b1001: hex_out <= 4'b1101; // 9
        4'b1010: hex_out <= 4'b1110; // A
        4'b1011: hex_out <= 4'b0111; // B
        4'b1100: hex_out <= 4'b1110; // C
        4'b1101: hex_out <= 4'b0011; // D
        4'b1110: hex_out <= 4'b1110; // E
        4'b1111: hex_out <= 4'b1100; // F
      endcase
    end
  end

  assign seven_seg_out[0] = ~hex_out[0];
  assign seven_seg_out[1] = ~hex_out[1];
  assign seven_seg_out[2] = ~hex_out[2];
  assign seven_seg_out[3] = ~hex_out[3];
  assign seven_seg_out[4] = 1'b1; // decimal point is not used
  assign seven_seg_out[5] = 1'b1; // decimal point is not used
  assign seven_seg_out[6] = 1'b1; // common anode, so high voltage turns off segment

endmodule

