  output reg [3:0] gray,
  output reg flag
);

  reg [3:0] prev_gray;

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      gray <= 0;
      flag <= 0;
      prev_gray <= 0;
    end else begin
      gray <= binary ^ (binary >> 1);
      flag <= (gray != prev_gray);
      prev_gray <= gray;
    end
  end

endmodule

module mult12_8 (
    clock,
    dataa,
    datab,
    result
);

input   clock;
input   [11:0]  dataa;
input   [7:0]   datab;
output  [19:0]  result;

reg     [19:0]  temp_result;

always @ (posedge clock) begin
    temp_result <= {dataa, 8'b0} * {8'b0, datab};
end

assign result = temp_result;

endmodule

module ast_interface (
    clk,
    reset_n,
    ast_sink_data,
    ast_sink_valid,
    ast_source_ready,
    ast_sink_error,
    ast_source_data,
    ast_sink_ready,
    ast_source_valid,
    ast_source_error
);

    input clk;
    input reset_n;
    input [14:0] ast_sink_data;
    input ast_sink_valid;
    input ast_source_ready;
    input [1:0] ast_sink_error;
    output [30:0] ast_source_data;
    output ast_sink_ready;
    output ast_source_valid;
    output [1:0] ast_source_error;

    reg [14:0] sink_reg;
    reg [1:0] error_reg;
    reg [30:0] source_reg;
    reg source_valid_reg;
    reg sink_ready_reg;
    reg [1:0] source_error_reg;

    always @(posedge clk) begin
        if (!reset_n) begin
            sink_reg <= 15'b0;
            error_reg <= 2'b0;
            sink_ready_reg <= 1'b1;
        end else if (ast_sink_valid) begin
            sink_reg <= ast_sink_data;
            error_reg <= ast_sink_error;
            sink_ready_reg <= 1'b0;
        end else if (ast_source_ready && source_valid_reg) begin
            source_valid_reg <= 1'b0;
            sink_ready_reg <= 1'b1;
        end
    end

    always @(negedge clk) begin
        if (ast_source_ready && source_valid_reg) begin
            source_valid_reg <= 1'b0;
            sink_ready_reg <= 1'b1;
        end else if (source_valid_reg && !ast_source_ready) begin
            source_valid_reg <= 1'b1;
            sink_ready_reg <= 1'b0;
            ast_source_data <= source_reg;
            ast_source_error <= source_error_reg;
        end
    end

    always @* begin
        source_valid_reg = 0;
        source_reg = {16'b0, sink_reg, error_reg};
        source_error_reg = error_reg;

        if (ast_source_ready && sink_ready_reg && ast_sink_valid) begin
            source_valid_reg = 1;
        end
    end

    assign ast_sink_ready = sink_ready_reg;
    assign ast_source_valid = source_valid_reg;

endmodule

