module axi4_lite_to_stream
#(
  parameter DATA_WIDTH = 32,
  parameter ADDR_WIDTH = 32,
  parameter BURST_LENGTH = 16,
  parameter ID_WIDTH = 4
)
(
  input  wire                   ACLK,
  input  wire                   ARESETN,
  input  wire [ADDR_WIDTH-1:0]  S_AXI_AWADDR,
  input  wire [7:0]             S_AXI_AWPROT,
  input  wire                   S_AXI_AWVALID,
  output wire                   S_AXI_AWREADY,
  input  wire [DATA_WIDTH-1:0]  S_AXI_WDATA,
  input  wire [DATA_WIDTH/8-1:0]S_AXI_WSTRB,
  input  wire                   S_AXI_WVALID,
  output wire                   S_AXI_WREADY,
  input  wire [ID_WIDTH-1:0]    S_AXI_BID,
  input  wire [1:0]             S_AXI_BRESP,
  input  wire                   S_AXI_BVALID,
  output wire                   S_AXI_BREADY,
  input  wire [ADDR_WIDTH-1:0]  S_AXI_ARADDR,
  input  wire [7:0]             S_AXI_ARPROT,
  input  wire                   S_AXI_ARVALID,
  output wire                   S_AXI_ARREADY,
  output wire [DATA_WIDTH-1:0]  S_AXI_RDATA,
  output wire [1:0]             S_AXI_RRESP,
  output wire                   S_AXI_RVALID,
  input  wire                   S_AXI_RREADY,
  input  wire                   M_AXIS_ACLK,
  input  wire                   M_AXIS_ARESETN,
  output wire [DATA_WIDTH-1:0]  M_AXIS_TDATA,
  output wire                   M_AXIS_TVALID,
  input  wire                   M_AXIS_TREADY,
  output wire                   M_AXIS_TLAST
);

localparam IDLE = 2'b00, READ = 2'b01, WRITE = 2'b10;
reg [1:0] state = IDLE;
reg [1:0] next_state = IDLE;
reg [31:0] address_reg = 0;
reg [3:0] id_reg = 0;
reg [31:0] count_reg = 0;
reg [31:0] read_data_reg = 0;
reg [31:0] write_data_reg = 0;
reg [31:0] write_count_reg = 0;
reg [31:0] burst_count_reg = 0;
reg [31:0] burst_size_reg = 0;
reg [2:0] burst_state_reg = 0;
reg [31:0] burst_address_reg = 0;
reg [31:0] burst_count_reg = 0;
reg burst_in_progress = 0;

always @(posedge ACLK) begin
  if (!ARESETN) begin
    state <= IDLE;
    address_reg <= 0;
    id_reg <= 0;
    count_reg <= 0;
    read_data_reg <= 0;
    write_data_reg <= 0;
    write_count_reg <= 0;
    burst_count_reg <= 0;
    burst_size_reg <= 0;
    burst_state_reg <= 0;
    burst_address_reg <= 0;
    burst_count_reg <= 0;
    burst_in_progress <= 0;
  end else begin
    state <= next_state;
    case (state)
      IDLE: begin
        if (S_AXI_ARVALID) begin
          address_reg <= S_AXI_ARADDR;
          id_reg <= S_AXI_ARID;
          count_reg <= S_AXI_ARLEN;
          read_data_reg <= 0;
          next_state <= READ;
        end else if (S_AXI_AWVALID) begin
          address_reg <= S_AXI_AWADDR;
          id_reg <= S_AXI_AWID;
          count_reg <= S_AXI_AWLEN;
          write_data_reg <= S_AXI_WDATA;
          write_count_reg <= 0;
          next_state <= WRITE;
          burst_size_reg <= S_AXI_AWSIZE;
          burst_in_progress <= (S_AXI_AWLEN > 1);
          burst_address_reg <= S_AXI_AWADDR;
          burst_count_reg <= S_AXI_AWLEN;
          burst_state_reg <= 0;
        end
      end
      READ: begin
        if (M_AXIS_TREADY && S_AXI_RVALID) begin
          read_data_reg <= S_AXI_RDATA;
          count_reg <= count_reg - 1;
          if (count_reg == 0) begin
            next_state <= IDLE;
          end
        end
      end
      WRITE: begin
        if (M_AXIS_TREADY) begin
          if (write_count_reg == 0) begin
            write_data_reg <= S_AXI_WDATA;
          end
          M_AXIS_TDATA <= write_data_reg;
          M_AXIS_TVALID <= 1;
          write_count_reg <= write_count_reg + 1;
          if (write_count_reg == DATA_WIDTH/8) begin
            write_count_reg <= 0;
            count_reg <= count_reg - 1;
            if (count_reg == 0) begin
              next_state <= IDLE;
            end else begin
              address_reg <= address_reg + 4;
              write_data_reg <= S_AXI_WDATA;
            end
          end
        end
      end
    endcase
  end
end

assign S_AXI_WREADY = (state == WRITE && M_AXIS_TREADY);

always @(posedge M_AXIS_ACLK) begin
  if (!M_AXIS_ARESETN) begin
    M_AXIS_TDATA <= 0;
    M_AXIS_TVALID <= 0;
    M_AXIS_TLAST <= 0;
  end else begin
    case (burst_state_reg)
      0: begin // IDLE
        if (burst_in_progress) begin
          M_AXIS_TDATA <= 0;
          M_AXIS_TVALID <= 0;
          M_AXIS_TLAST <= 0;
          burst_count_reg <= 0;
          burst_state_reg <= 1;
        end
      end
      1: begin // ADDR
        M_AXIS_TDATA <= burst_address_reg;
        M_AXIS_TVALID <= 1;
        M_AXIS_TLAST <= 0;
        burst_count_reg <= burst_count_reg + 1;
        if (burst_count_reg == ADDR_WIDTH/8) begin
          burst_count_reg <= 0;
          burst_state_reg <= 2;
        end
      end
      2: begin // DATA
        M_AXIS_TDATA <= write_data_reg;
        M_AXIS_TVALID <= 1;
        M_AXIS_TLAST <= (burst_count_reg == burst_size_reg);
        burst_count_reg <= burst_count_reg + 1;
        if (burst_count_reg == DATA_WIDTH/8) begin
          burst_count_reg <= 0;
          burst_address_reg <= burst_address_reg + 4;
          write_data_reg <= write_data_reg >> 32;
          burst_state_reg <= 1;
          burst_size_reg <= burst_size_reg + 1;
        end
      end
    endcase
  end
end

assign S_AXI_RDATA = read_data_reg;
assign S_AXI_RRESP = 2'b00;
assign S_AXI_RVALID = (state == READ && M_AXIS_TREADY);
assign S_AXI_ARREADY = (state == IDLE);
assign S_AXI_AWREADY = (state == IDLE);

assign S_AXI_BRESP = 2'b00;
assign S_AXI_BVALID = 0;
assign S_AXI_BID = id_reg;

endmodule

