module counter (
    input clk,
    input reset,
    input rx,
    output reg [7:0] led
);

reg [9:0] shiftdata;
reg [7:0] data;
reg [7:0] count;

integer i;

always @(posedge clk) begin
    if (reset) begin
        count <= 0;
    end else if (rx) begin
        shiftdata <= {shiftdata[8:0], rx};
        if (shiftdata[0] && shiftdata[9]) begin
            data <= shiftdata[8:1];
            if (data >= 32 && data <= 126) begin
                count <= count + 1;
            end
        end
    end
end

always @(posedge clk) begin
    if (reset) begin
        led <= 0;
    end else begin
        led <= count;
    end
end

endmodule

module servo_control (
  input wire [7:0] pos_cmd,
  input wire [7:0] fb,
  output wire pwm_out
);

parameter pwm_period = 0.02; // PWM period in seconds
parameter pos_resolution = 1; // Position resolution in degrees
parameter kp = 0.5; // Proportional gain
parameter ki = 0.1; // Integral gain

reg [7:0] error;
reg [7:0] integral;
reg [7:0] duty_cycle;
reg [7:0] pwm_count;

always @(posedge clk) begin
  // Calculate the error between the position command and the feedback signal
  error <= pos_cmd - fb;

  // Update the integral of the error
  integral <= integral + error;

  // Calculate the duty cycle based on the proportional and integral gains
  duty_cycle <= kp * error + ki * integral;

  // Limit the duty cycle to the range [0, 255]
  if (duty_cycle > 255) begin
    duty_cycle <= 255;
  end else if (duty_cycle < 0) begin
    duty_cycle <= 0;
  end

  // Update the PWM count
  pwm_count <= pwm_count + 1;

  // Generate the PWM signal based on the duty cycle and PWM period
  if (pwm_count < (duty_cycle * pwm_period * 256)) begin
    pwm_out <= 1;
  end else begin
    pwm_out <= 0;
  end

  // Reset the PWM count when it reaches the maximum value
  if (pwm_count == 255) begin
    pwm_count <= 0;
  end
end

endmodule

