   end

endmodule

module SSCG (
  input clk_in, // input clock signal
  input clk_en, // SSCG enable signal
  input sscg_freq, // frequency deviation parameter
  output clk_out // output clock signal
);

  reg [31:0] fm_accumulator;
  reg [31:0] fm_increment;
  reg [31:0] fm_modulation;
  reg [31:0] fm_output;

  always @ (posedge clk_in) begin
    if (clk_en) begin
      fm_accumulator <= fm_accumulator + fm_increment;
      fm_modulation <= sscg_freq * $random;
      fm_output <= $signed($sin(2 * $pi * fm_accumulator + fm_modulation));
    end else begin
      fm_output <= clk_in;
    end
  end

  assign clk_out = fm_output;

  initial begin
    fm_accumulator <= 0;
    fm_increment <= $floor((2**32 / 1000) * 100); // 100 kHz
    fm_modulation <= 0;
    fm_output <= 0;
  end

endmodule

