module pulseLength (
   input  wire        clk,
   input  wire        reset,
   output reg  [30:0] pw_low,
   output reg  [30:0] pw_high,
   output reg  [31:0] pwm_per,
   input  wire        pwm
);

   reg [1:0] ps, ns;
   parameter
   init  = 2'b00,
   first = 2'b01,
   low   = 2'b10,
   high  = 2'b11;

   reg        pwm_prev;
   reg [30:0] count_clk0, count_clk1;
   initial begin
      ps = init;

      pwm_prev   =  1'b1;
      count_clk0 = 31'b0;
      count_clk1 = 31'b0;
      pw_high    = 31'b0;
      pw_low     = 31'b0;
      pwm_per    = 32'b0;
   end

   always @ (*) begin
      case (ps)
         init:  if (pwm_prev ^ pwm)       ns = first;
                else                      ns = init;
         first: if (~pwm_prev & pwm)      ns = high;
                else if (pwm_prev & ~pwm) ns = low;
                else                      ns = first;
         low:   if (pwm)                  ns = high;
                else                      ns = low;
         high:  if (~pwm)                 ns = low;
                else                      ns = high;
      endcase
      pwm_per = pw_low + pw_high;
   end

   always @ (posedge clk) begin
      if (reset) begin
         count_clk0 <= 31'b0;
         count_clk1 <= 31'b0;
         pw_high    <= 31'bX;
         pw_low     <= 31'bX;
         pwm_per    <= 32'bX;
      end else begin
         case (ps)
            first:   begin
                        if (~pwm) count_clk0 <= count_clk0 + 1'b1;
                        else      count_clk1 <= count_clk1 + 1'b1;
                     end
            low:     begin
                        if (count_clk1) begin
                           pw_high    <= count_clk1;
                           count_clk1 <= 31'b0;
                        end
                        count_clk0 <= count_clk0 + 1'b1;
                     end
            high:    begin
                        if (count_clk0) begin
                           pw_low     <= count_clk0;
                           count_clk0 <= 31'b0;
                        end
                        count_clk1 <= count_clk1 + 1'b1;
                     end
            default: begin
                        pw_low     <= 31'bX;
                        pw_high    <= 31'bX;
                        count_clk0 <= 31'b0;
                        count_clk1 <= 31'b0;
                     end
         endcase
      end

      pwm_prev <= pwm;
   end

   always @ (posedge clk) begin
      if (reset) ps <= init;
      else       ps <= ns;
   end
endmodule

module traffic_light_fsm (
  input clk,
  input reset,
  output reg red,
  output reg yellow,
  output reg green
);

  // Define states
  parameter STATE_RED = 2'b00;
  parameter STATE_GREEN = 2'b01;
  parameter STATE_YELLOW = 2'b10;

  // Define state register and next state logic
  reg [1:0] state, next_state;
  always @ (posedge clk, negedge reset) begin
    if (!reset) begin
      state <= STATE_RED;
    end else begin
      state <= next_state;
    end
  end

  // Define state transition logic
  always @ (state) begin
    case (state)
      STATE_RED: begin
        next_state = STATE_GREEN;
      end
      STATE_GREEN: begin
        next_state = STATE_YELLOW;
      end
      STATE_YELLOW: begin
        next_state = STATE_RED;
      end
      default: begin
        next_state = STATE_RED;
      end
    endcase
  end

  // Define output logic
  always @ (state) begin
    case (state)
      STATE_RED: begin
        red = 1'b1;
        yellow = 1'b0;
        green = 1'b0;
      end
      STATE_GREEN: begin
        red = 1'b0;
        yellow = 1'b0;
        green = 1'b1;
      end
      STATE_YELLOW: begin
        red = 1'b0;
        yellow = 1'b1;
        green = 1'b0;
      end
      default: begin
        red = 1'b1;
        yellow = 1'b0;
        green = 1'b0;
      end
    endcase
  end

endmodule

module rotator_and_gate(
    input clk,
    input reset,
    input load,
    input [1:0] ena,
    input [99:0] data,
    input a,
    input b,
    input c,
    output reg [99:0] q,
    output out
);

// 100-bit left/right rotator
reg [99:0] shift_reg;
reg [6:0] shift_amount;
reg [99:0] shifted_out;
wire [99:0] shifted_in;

always @(posedge clk) begin
    if (reset) begin
        shift_reg <= 0;
        shift_amount <= 0;
        shifted_out <= 0;
    end else begin
        if (load) begin
            shift_reg <= data;
            shift_amount <= 0;
            shifted_out <= 0;
        end else begin
            case (ena)
                2'b00: begin // no rotation
                    shift_reg <= shift_reg;
                    shift_amount <= 0;
                    shifted_out <= 0;
                end
                2'b01: begin // right rotation
                    shift_reg <= {shifted_in, shift_reg[99:1]};
                    shift_amount <= shift_amount + 1;
                    shifted_out <= shift_reg[0];
                end
                2'b10: begin // left rotation
                    shift_reg <= {shift_reg[98:0], shifted_in};
                    shift_amount <= shift_amount - 1;
                    shifted_out <= shift_reg[99];
                end
            endcase
        end
    end
end

assign shifted_in = (ena == 2'b01) ? shifted_out : (ena == 2'b10) ? shifted_out : 1'b0;

// 3-input AND gate
wire [2:0] and_inputs;
assign and_inputs = {a, b, c};
wire and_output;
assign and_output = and_inputs[0] & and_inputs[1] | and_inputs[2];

// Control logic
reg [99:0] rotator_output;
always @(*) begin
    if (ena == 2'b00) begin
        rotator_output = shift_reg;
        out = and_output;
    end else begin
        rotator_output = 0;
        out = 0;
    end
end

always @(posedge clk) begin
    if (reset) begin
        q <= 0;
    end else begin
        if (ena == 2'b00) begin
            q <= rotator_output;
        end else begin
            q <= 0;
        end
    end
end

endmodule

