module top_module(
    input [31:0] a,
    input [31:0] b,
    output [31:0] sum
);

    wire [15:0] a_low = a[15:0];
    wire [15:0] a_high = a[31:16];
    wire [15:0] b_low = b[15:0];
    wire [15:0] b_high = b[31:16];

    wire [15:0] adder1_out;
    wire [15:0] adder2_out;
    wire [31:0] carry_select_out;

    adder16 adder1(.a(a_low), .b(b_low), .sum(adder1_out));
    adder16 adder2(.a(a_high), .b(b_high), .sum(adder2_out));
    carry_select_adder csa(.a(adder1_out), .b(adder2_out), .cin(1'b0), .sum(carry_select_out));
    functional_module func(.a(adder1_out), .b(adder2_out), .sum(sum));

endmodule

module adder16(
    input [15:0] a,
    input [15:0] b,
    output [15:0] sum
);
    assign sum = a + b;
endmodule

module carry_select_adder(
    input [15:0] a,
    input [15:0] b,
    input cin,
    output [31:0] sum
);
    wire [15:0] sum1;
    wire [15:0] sum2;
    wire [15:0] carry1;
    wire [15:0] carry2;

    adder16 adder1(.a(a), .b(b), .sum(sum1));
    adder16 adder2(.a(a), .b(~b), .sum(sum2));

    assign carry1 = (cin) ? {16{1'b0}} : {16{1'b1}};
    assign carry2 = (cin) ? {16{1'b1}} : {16{1'b0}};

    mux2x16 mux1(.a(sum1), .b(sum2), .sel(b[15]), .y(sum[15:0]));
    mux2x16 mux2(.a(sum1), .b(sum2), .sel(b[15]), .y(sum[31:16]));

    mux2x16 mux3(.a(carry1), .b(carry2), .sel(b[15]), .y(carry_select_out));
endmodule

