    .out(left_shifted)
);

// Right shifter module
right_shifter rs (
    .in(in),
    .shift_amt(shift_amt),
    .out(right_shifted)
);

// Mux to select output based on direction
assign out = dir ? right_shifted : left_shifted;

endmodule

