module adder_subtractor (
    input [3:0] A,
    input [3:0] B,
    input mode,
    output reg [3:0] Q
);

reg [3:0] A_reg, B_reg, Q_reg;
reg mode_reg;

always @ (posedge clk) begin
    A_reg <= A;
    B_reg <= B;
    mode_reg <= mode;
end

always @ (posedge clk) begin
    if (mode_reg == 0) begin
        Q_reg <= A_reg + B_reg;
    end else begin
        Q_reg <= A_reg - B_reg;
    end
end

assign Q = Q_reg;

endmodule

module xor_4bit (
  input [3:0] a,
  input [3:0] b,
  output reg [3:0] out
);

  always @* begin
    out[0] = ~(a[0] & b[0]) & (a[0] | b[0]);
    out[1] = ~(a[1] & b[1]) & (a[1] | b[1]);
    out[2] = ~(a[2] & b[2]) & (a[2] | b[2]);
    out[3] = ~(a[3] & b[3]) & (a[3] | b[3]);
  end

endmodule

