module csa_generate_adder_32bit (
    input [31:0] A,
    input [31:0] B,
    output [31:0] S,
    output C32
);

    wire [31:0] P, G, C1, C2;
    wire [31:0] C1_bar, C2_bar;
    wire [31:0] S1, S2;
    wire C1_G, C2_G, C1_P, C2_P;

    // First stage of pipeline
    ripple_carry_adder_32bit rca1 (
        .A(A),
        .B(B),
        .Cin(1'b0),
        .S(S1),
        .Cout(C1)
    );

    generate
        genvar i;
        for (i = 0; i < 32; i = i+1) begin : gen1
            assign P[i] = A[i] | B[i];
            assign G[i] = A[i] & B[i];
            assign C1_bar[i] = ~C1[i];
            assign C1_G = G[i] & C1_bar[i];
            assign C1_P = P[i] & C1[i];
        end
    endgenerate

    // Second stage of pipeline
    ripple_carry_adder_32bit rca2 (
        .A(S1),
        .B(P),
        .Cin(C1_G),
        .S(S2),
        .Cout(C2)
    );

    generate
        genvar i;
        for (i = 0; i < 32; i = i+1) begin : gen2
            assign C2_bar[i] = ~C2[i];
            assign C2_G = G[i] & C2_bar[i];
            assign C2_P = P[i] & C2[i];
        end
    endgenerate

    // Final stage of pipeline
    assign S = S2;
    assign C32 = C2_G | (C2_P & C1_G) | (C2_P & C1_P & 1'b1);

endmodule

module ripple_carry_adder_32bit (
    input [31:0] A,
    input [31:0] B,
    input Cin,
    output [31:0] S,
    output Cout
);

    wire [31:0] C;

    assign S = A + B + Cin;
    assign Cout = C[31];

endmodule

module shortfifo
  #(parameter WIDTH=32)
    (input clk, input rst,
     input [WIDTH-1:0] datain,
     output [WIDTH-1:0] dataout,
     input read,
     input write,
     input clear,
     output reg full,
     output reg empty,
     output reg [4:0] space,
     output reg [4:0] occupied);

   reg [3:0] 	  a;
   reg [WIDTH-1:0] fifo [15:0];
   integer i;

   always @(posedge clk)
     if(rst)
       begin
	  a <= 0;
	  empty <= 1;
	  full <= 0;
       end
     else if(clear)
       begin
	  a <= 0;
	  empty <= 1;
	  full<= 0;
       end
     else if(read & ~write)
       begin
	  full <= 0;
	  if(a==0)
	    empty <= 1;
	  else
	    a <= a - 1;
	  dataout <= fifo[occupied];
	  occupied <= occupied + 1;
       end
     else if(write & ~read)
       begin
	  empty <= 0;
	  if(~full)
	    begin
	      fifo[space] <= datain;
	      a <= a + 1;
	      if(a == 15)
		full <= 1;
	      space <= space + 1;
	    end
       end

   // NOTE will fail if you write into a full fifo or read from an empty one

   //////////////////////////////////////////////////////////////
   // space and occupied are used for diagnostics, not 
   // guaranteed correct

   always @(posedge clk)
     if(rst)
       space <= 16;
     else if(clear)
       space <= 16;
     else if(read & ~write)
       space <= space + 1;
     else if(write & ~read)
       space <= space - 1;

   always @(posedge clk)
     if(rst)
       occupied <= 0;
     else if(clear)
       occupied <= 0;
     else if(read & ~write)
       occupied <= occupied + 1;
     else if(write & ~read)
       occupied <= occupied - 1;

endmodule

module adapter_axi_stream_2_ppfifo #(
  parameter                         DATA_WIDTH = 32,
  parameter                         STROBE_WIDTH = DATA_WIDTH / 8,
  parameter                         USE_KEEP = 0
)(
  input                             rst,

  //AXI Stream Input
  input                             i_axi_clk,
  output                            o_axi_ready,
  input       [DATA_WIDTH - 1:0]    i_axi_data,
  input       [STROBE_WIDTH - 1:0]  i_axi_keep,
  input                             i_axi_last,
  input                             i_axi_valid,

  //Ping Pong FIFO Write Controller
  output                            o_ppfifo_clk,
  input       [1:0]                 i_ppfifo_rdy,
  output  reg [1:0]                 o_ppfifo_act,
  input       [23:0]                i_ppfifo_size,
  output  reg                       o_ppfifo_stb,
  output  reg [DATA_WIDTH - 1:0]    o_ppfifo_data
);
//local parameters
localparam      IDLE        = 0;
localparam      READY       = 1;
localparam      RELEASE     = 2;
//registes/wires
wire                        clk;  //Convenience Signal
reg           [3:0]         state;
reg           [23:0]        r_count;
//submodules
//asynchronous logic

//This is a little strange to just connect the output clock with the input clock but if this is done
//Users do not need to figure out how to hook up the clocks
assign  o_ppfifo_clk    = i_axi_clk;
assign  clk             = i_axi_clk;
assign  o_axi_ready     = (o_ppfifo_act > 0) && (r_count < i_ppfifo_size);
//synchronous logic

always @ (posedge clk) begin
  o_ppfifo_stb              <=  0;

  if (rst) begin
    r_count                 <=  0;
    o_ppfifo_act            <=  0;
    o_ppfifo_data           <=  0;
    state                   <=  IDLE;
  end
  else begin
    case (state)
      IDLE: begin
        o_ppfifo_act        <=  0;
        if ((i_ppfifo_rdy > 0) && (o_ppfifo_act == 0)) begin
          r_count           <=  0;
          if (i_ppfifo_rdy[0]) begin
            o_ppfifo_act[0] <=  1;
          end
          else begin
            o_ppfifo_act[1] <=  1;
          end
          state             <=  READY;
        end
      end
      READY: begin
        if (r_count < i_ppfifo_size) begin
          if (i_axi_valid) begin
            o_ppfifo_stb    <=  1;
            o_ppfifo_data   <=  i_axi_data;

            r_count         <=  r_count + 1;
          end
        end
        //Conditions to release the FIFO or stop a transaction
        else begin
          state             <=  RELEASE;
        end
        if (i_axi_last) begin
          state             <=  RELEASE;
        end
      end
      RELEASE: begin
        o_ppfifo_act        <=  0;
        state               <=  IDLE;
      end
      default: begin
      end
    endcase
  end
end

endmodule

module rotator_byte_reorder(
    input clk,
    input load,
    input [1:0] ena,
    input [99:0] data,
    input [31:0] in,
    output [31:0] out);

    // 100-bit left/right rotator
    reg [99:0] rot_data;
    always @(posedge clk) begin
        if (load) rot_data <= data;
        else if (ena[0]) rot_data <= {rot_data[98:0], rot_data[99]};
        else if (ena[1]) rot_data <= {rot_data[0], rot_data[99:1]};
    end

    // Byte reordering module
    reg [7:0] shift_reg [3:0];
    always @(posedge clk) begin
        if (load) begin
            shift_reg[0] <= in[7:0];
            shift_reg[1] <= in[15:8];
            shift_reg[2] <= in[23:16];
            shift_reg[3] <= in[31:24];
        end
        else begin
            shift_reg[0] <= shift_reg[1];
            shift_reg[1] <= shift_reg[2];
            shift_reg[2] <= shift_reg[3];
            shift_reg[3] <= in[31:24];
        end
    end
    assign out = {shift_reg[3], shift_reg[2], shift_reg[1], shift_reg[0]} | rot_data[31:0];

endmodule

module ToneGenerator (
  input [1:0] tone_type,
  input [15:0] frequency,
  input [15:0] duration,
  output [11:0] tone
);

  reg [15:0] counter;
  reg [11:0] dtmf_tone;
  reg [11:0] sine_tone;
  reg [11:0] square_tone;

  always @ (posedge clk) begin
    if (counter < duration) begin
      case (tone_type)
        2'b00: begin // DTMF tone
          case (frequency)
            8'h01: dtmf_tone = 12'h1C2; // 697 Hz
            8'h02: dtmf_tone = 12'h1E0; // 770 Hz
            8'h03: dtmf_tone = 12'h1F5; // 852 Hz
            8'h04: dtmf_tone = 12'h20A; // 941 Hz
            8'h05: dtmf_tone = 12'h21C; // 1209 Hz
            8'h06: dtmf_tone = 12'h22E; // 1336 Hz
            8'h07: dtmf_tone = 12'h23F; // 1477 Hz
            8'h08: dtmf_tone = 12'h24F; // 1633 Hz
            default: dtmf_tone = 0;
          endcase
          tone = dtmf_tone;
        end
        2'b01: begin // Sine wave
          sine_tone = $sin(2 * $pi * frequency * counter / 65536);
          tone = {6'b0, sine_tone[11:6]};
        end
        2'b10: begin // Square wave
          square_tone = $sign($sin(2 * $pi * frequency * counter / 65536));
          tone = {6'b0, square_tone[11:6]};
        end
        default: tone = 0;
      endcase
      counter <= counter + 1;
    end else begin
      tone = 0;
      counter <= 0;
    end
  end

endmodule

module FloatToFixed (
    input wire CLK,
    input wire [31:0] F,
    input wire RST_FF,
    input wire Begin_FSM_FF,
    output wire ACK_FF,
    output wire [31:0] RESULT
);

    // Extract exponent from input floating-point number
    wire [7:0] exp = F[30:23];
    wire [22:0] mantissa = F[22:0];
    wire [31:0] fixed;
    wire [4:0] num_bits;
    wire [31:0] shifted_mantissa;
    wire [31:0] integer_part;
    wire [31:0] fractional_part;
    wire [31:0] final_result;
    wire [31:0] zero = 32'h00000000;
    wire [31:0] one = 32'h00000001;
    wire [31:0] two = 32'h00000002;
    wire [31:0] three = 32'h00000003;
    wire [31:0] four = 32'h00000004;
    wire [31:0] five = 32'h00000005;
    wire [31:0] six = 32'h00000006;
    wire [31:0] seven = 32'h00000007;

    // Determine number of bits required to represent integer portion of F
    assign num_bits = exp - 127 + 1;

    // Convert floating-point number F to fixed-point number with specified number of integer and fractional bits
    always @(posedge CLK) begin
        if (RST_FF == 1'b1) begin
            fixed <= zero;
        end else if (Begin_FSM_FF == 1'b1) begin
            shifted_mantissa <= {mantissa, 8'h00};
            integer_part <= shifted_mantissa >> (23 - num_bits);
            fractional_part <= shifted_mantissa << (num_bits + 1);
            fixed <= integer_part + (fractional_part >> (num_bits + 1));
        end
    end

    // Output resulting fixed-point number and indicate that conversion process is complete
    always @(posedge CLK) begin
        if (RST_FF == 1'b1) begin
            RESULT <= zero;
            ACK_FF <= 1'b0;
        end else if (Begin_FSM_FF == 1'b1) begin
            final_result <= fixed << (31 - num_bits);
            RESULT <= final_result;
            ACK_FF <= 1'b1;
        end else begin
            RESULT <= zero;
            ACK_FF <= 1'b0;
        end
    end

endmodule

module vending_machine(
    input clk, reset, coin, button,
    input [1:0] drink_code,
    output reg [1:0] dispensed_drink,
    output reg [1:0] change
);

reg [1:0] selected_drink;
reg [2:0] balance = 4'b0100;

always @(posedge clk) begin
    if(reset) begin
        balance <= 4'b0100;
        selected_drink <= 2'b00;
        dispensed_drink <= 2'b00;
        change <= 2'b00;
    end else begin
        if(button) begin
            if(coin) begin
                if(balance >= 2'b10) begin
                    balance <= balance - 2'b10;
                    selected_drink <= drink_code;
                    dispensed_drink <= drink_code;
                    change <= balance;
                    balance <= 2'b00;
                end else begin
                    dispensed_drink <= 2'b00;
                    change <= balance;
                    balance <= 2'b00;
                end
            end else begin
                dispensed_drink <= 2'b00;
                change <= balance;
                balance <= 2'b00;
            end
        end else begin
            dispensed_drink <= 2'b00;
            change <= balance;
            balance <= 2'b00;
        end
    end
end

endmodule

module top_module (
    input [3:0] A,
    input [3:0] B,
    input cin,
    input select,
    output reg [3:0] sum,
    output reg cout
);

    wire [3:0] adder_out;
    wire adder_cout;
    wire [3:0] ripple_addsub_out;
    wire ripple_addsub_cout;

    adder adder_inst (
        .A(A),
        .B(B),
        .cin(cin),
        .sum(adder_out),
        .cout(adder_cout)
    );

    ripple_addsub ripple_addsub_inst (
        .A(A),
        .B(B),
        .cin(cin),
        .select(select),
        .sum(ripple_addsub_out),
        .cout(ripple_addsub_cout)
    );

    always @(*) begin
        if (select) begin
            if (adder_cout) begin
                sum <= ripple_addsub_out + 4'b0001;
            end else begin
                sum <= ripple_addsub_out;
            end
        end else begin
            sum <= adder_out;
        end
    end

    always @(*) begin
        if (select) begin
            cout <= ripple_addsub_cout;
        end else begin
            cout <= adder_cout;
        end
    end

endmodule

module sirv_debug_csr 
#(
    parameter PC_SIZE = 32 
)(
    input  [PC_SIZE-1:0] cmt_dpc,
    input  cmt_dpc_ena,
    input  [3-1:0] cmt_dcause,
    input  cmt_dcause_ena,
    input  dbg_irq_r,
    input  wr_dcsr_ena,
    input  wr_dpc_ena,
