module stack (
  input clk,
  input rst,
  input [15:0] pushd,
  input push_en,
  input pop_en,
  output reg [15:0] top
);

  reg [3:0] sp; // stack pointer
  reg [15:0] mem [0:7]; // stack memory

  always @(posedge clk) begin
    if (rst) begin
      sp <= 0;
      top <= 0;
    end else begin
      if (push_en && sp < 8) begin
        mem[sp] <= pushd;
        sp <= sp + 1;
      end else if (pop_en && sp > 0) begin
        sp <= sp - 1;
      end
      top <= sp > 0 ? mem[sp-1] : 0;
    end
  end

endmodule

module mux_4to1 (
    in0,
    in1,
    in2,
    in3,
    sel1,
    sel0,
    out
);

    input in0;
    input in1;
    input in2;
    input in3;
    input sel1;
    input sel0;
    output out;

    wire not_sel1;
    wire not_sel0;
    wire and1;
    wire and2;
    wire and3;
    wire and4;
    wire and5;
    wire and6;
    wire or1;

    // Invert select wires
    not not_sel1(sel1);
    not not_sel0(sel0);

    // AND gates to create all possible combinations
    and1(in0, not_sel1, not_sel0);
    and2(in1, not_sel1, sel0);
    and3(in2, sel1, not_sel0);
    and4(in3, sel1, sel0);

    // OR gates to combine the AND gates
    or1(or1, and1, and2, and3, and4);

    // Output
    assign out = or1;

endmodule

module three_input_gate (
    A,
    B,
    C,
    Y
);

    input A, B, C;
    output Y;

    wire and1, and2, and3;
    wire or1, or2;

    assign and1 = A & B;
    assign and2 = A & C;
    assign and3 = B & C;
    assign or1 = and1 | and2;
    assign or2 = or1 | and3;
    assign Y = or2;

endmodule

module fifo_buffer (
    input        wr_clk,
    input        wr_en,
    input        rd_clk,
    input        rd_en,
    input        rst_n,
    input  [7:0] din,
    output [7:0] dout,
    output       empty,
    output       full
);

reg [7:0] buffer [0:15];
reg        wr_ptr;
reg        rd_ptr;
reg        empty;
reg        full;

always @(posedge wr_clk or negedge rst_n) begin
    if (~rst_n) begin
        wr_ptr <= 0;
        rd_ptr <= 0;
        empty  <= 1;
        full   <= 0;
    end else if (wr_en && ~full) begin
        buffer[wr_ptr] <= din;
        wr_ptr <= wr_ptr + 1;
        if (wr_ptr == 15) full <= 1;
        empty <= 0;
    end
end

always @(posedge rd_clk or negedge rst_n) begin
    if (~rst_n) begin
        wr_ptr <= 0;
        rd_ptr <= 0;
        empty  <= 1;
        full   <= 0;
    end else if (rd_en && ~empty) begin
        dout <= buffer[rd_ptr];
        rd_ptr <= rd_ptr + 1;
        if (rd_ptr == 15) empty <= 1;
        full <= 0;
    end
end

endmodule

module multiplier_block (
    input   [31:0] i_data0,
    output  [31:0] o_data0
);

  //Multipliers:

  wire [31:0]
    w1,
    w4,
    w5,
    w10,
    w2048,
    w2047,
    w640,
    w2687,
    w2677;

  assign w1 = i_data0;
  assign w4 = i_data0 << 2;
  assign w5 = i_data0 + w4;
  assign w10 = w5 << 1;
  assign w2048 = i_data0 << 11;
  assign w2047 = w2048 - w1;
  assign w640 = w5 << 7;
  assign w2687 = w2047 + w640;
  assign w2677 = w2687 - w10;

  assign o_data0 = w2677;

