endmodule

module four_input_expression(res, a, b, c, d, clk, en);
  output res;
  input a, b, c, d, clk, en;
  wire q0, q1, q2, q3;

  flop_gated_latch f0(q0, a, clk, en);
  flop_gated_latch f1(q1, b, clk, en);
  flop_gated_flop f2(q2, c, clk, en);
  flop_gated_flop f3(q3, d, clk, en);

  assign res = (q0 + q1) * (q2 - q3);
endmodule

module cipher_module(
  input clk,
  input rst,
  input [63:0] pdata,
  input pvalid,
  input cready,
  output [63:0] cdata,
  output cvalid,
  output reg pready
);

  parameter READY = 1'b0;
  parameter RUN = 1'b1;

  reg [63:0] a, b;
  reg [1:0] state = READY;
  wire [31:0] sbox = `Sbox(addmod32);
  wire [31:0] shift11 = {sbox[20:0], sbox[31:21]};

  always @(posedge clk) begin
    if (rst) begin
      {b, a} <= {64{1'b0}};
      state <= READY;
    end else begin
      case (state)
        READY: begin
          if (pvalid && pready) begin
            {b, a} <= pdata;
            state <= RUN;
          end
        end
        RUN: begin
          {b, a} <= {a, b ^ shift11};
          if (cready) begin
            pready <= 1'b1;
            state <= READY;
          end
        end
      endcase
    end
  end

  always @(posedge clk) begin
    if (state == READY) begin
      cdata <= {a, b};
      cvalid <= 1'b1;
    end else begin
      cvalid <= 1'b0;
    end
  end

  always @(posedge clk) begin
    if ((state == RUN) || (state == READY)) begin
      pready <= 1'b0;
    end else if (cready) begin
      pready <= 1'b1;
    end
  end

endmodule

module dual_edge_triggered_ff (
