module dp_transmitter (
  input [n-1:0] data_in,
  input dp_clk,
  input dp_hsync,
  input dp_vsync,
  output [m-1:0] dp_out
);

parameter n = 8; // number of data bits
parameter m = 10; // number of transmission symbols

// 8b/10b encoding
always @ (data_in) begin
  case (data_in)
    8'b00000000: dp_out = 10'b0000000000;
    8'b00000001: dp_out = 10'b0000000001;
    8'b00000010: dp_out = 10'b0000000010;
    // more encoding rules
    default: dp_out = 10'bxxxxxxxxxx; // invalid input
  endcase
end

// serialization and transmission
reg [m-1:0] serial_data;
reg serial_data_valid;
reg serial_data_ready;
always @ (posedge dp_clk) begin
  if (dp_hsync && dp_vsync) begin // start of frame
    serial_data <= {2'b01, dp_out}; // header and first symbol
    serial_data_valid <= 1'b1;
    serial_data_ready <= 1'b0;
  end else if (serial_data_valid && serial_data_ready) begin
    serial_data <= {2'b10, serial_data[m-2:0], 1'b0}; // second symbol and padding
    serial_data_valid <= 1'b0;
    serial_data_ready <= 1'b0;
  end else begin
    serial_data <= {1'b0, serial_data[m-1:1]}; // shift out next symbol
    serial_data_valid <= 1'b1;
    serial_data_ready <= 1'b1;
  end
end

// control signals
assign dp_hsync = (serial_data == 10'b0010100001); // HSYNC symbol
assign dp_vsync = (serial_data == 10'b0011000001); // VSYNC symbol

endmodule
module dp_receiver (
  input [m-1:0] dp_in,
  input hsync,
  input vsync,
  output [n-1:0] data_out
);

parameter n = 8; // number of data bits
parameter m = 10; // number of transmission symbols

// deserialization and decoding
reg [m-1:0] deserial_data;
reg deserial_data_valid;
reg deserial_data_ready;
always @ (posedge dp_clk) begin
  if (hsync && vsync) begin // start of frame
    deserial_data <= dp_in[9:0];
    deserial_data_valid <= 1'b1;
    deserial_data_ready <= 1'b0;
  end else if (deserial_data_valid && deserial_data_ready) begin
    data_out <= deserial_data[n-1:0]; // output decoded data
    deserial_data_valid <= 1'b0;
    deserial_data_ready <= 1'b0;
  end else begin
    deserial_data <= {dp_in[9], deserial_data[m-2:0]}; // shift in next symbol
    deserial_data_valid <= 1'b1;
    deserial_data_ready <= 1'b1;
  end
end

// control signals
assign hsync = (deserial_data == 10'b0010100001); // HSYNC symbol
assign vsync = (deserial_data == 10'b0011000001); // VSYNC symbol

endmodule

