module KeyboardController(
  input clk,
  input rst,
  input PS2_CLK,
  inout PS2_DATA,
  output reg [7:0] key_in,
  output reg is_extend,
  output reg is_break,
  output reg valid,
  output reg err,
  output reg is_lock_caps,
  output reg is_lock_num,
  output reg is_lock_scr
);

  // Define constants
  parameter SYSCLK_FREQUENCY_HZ = 100000000;
  parameter RESET = 3'd0;
  parameter SEND_CMD = 3'd1;
  parameter WAIT_ACK = 3'd2;
  parameter WAIT_KEYIN = 3'd3;
  parameter GET_BREAK = 3'd4;
  parameter GET_EXTEND = 3'd5;
  parameter RESET_WAIT_BAT = 3'd6;
  parameter CMD_RESET = 8'hFF;
  parameter CMD_SET_STATUS_LEDS = 8'hED;
  parameter RSP_ACK = 8'hFA;
  parameter RSP_BAT_PASS = 8'hAA;
  parameter BREAK_CODE = 8'hF0;
  parameter EXTEND_CODE = 8'hE0;
  parameter CAPS_LOCK = 8'h58;
  parameter NUM_LOCK = 8'h77;
  parameter SCR_LOCK = 8'h7E;

  // Define internal signals
  wire [7:0] rx_data;
  wire rx_valid;
  wire busy;
  reg [7:0] tx_data;
  reg tx_valid;
  reg [2:0] state;
  reg [2:0] lock_status;

  // Define output signals
  assign PS2_CLK = clk;
  assign err = 0;
  assign is_lock_caps = lock_status[2];
  assign is_lock_num = lock_status[1];
  assign is_lock_scr = lock_status[0];

  // Define input signals
  always @(posedge clk, posedge rst) begin
    if (rst) begin
      key_in <= 0;
      is_extend <= 0;
      is_break <= 1;
      valid <= 0;
      lock_status <= 0;
      tx_data <= 0;
      tx_valid <= 0;
      state <= RESET;
    end else begin
      // Handle state machine
      case (state)
        RESET: begin
          is_extend <= 0;
          is_break <= 1;
          valid <= 0;
          lock_status <= 0;
          tx_data <= CMD_RESET;
          tx_valid <= 0;
          state <= SEND_CMD;
        end
        SEND_CMD: begin
          if (busy == 0) begin
            tx_valid <= 1;
            state <= WAIT_ACK;
          end else begin
            tx_valid <= 0;
            state <= SEND_CMD;
          end
        end
        WAIT_ACK: begin
          if (rx_valid == 1) begin
            if (rx_data == RSP_ACK && tx_data == CMD_RESET) begin
              state <= RESET_WAIT_BAT;
            end else if (rx_data == RSP_ACK && tx_data == CMD_SET_STATUS_LEDS) begin
              tx_data <= {5'b00000, lock_status};
              state <= SEND_CMD;
            end else begin
              state <= WAIT_KEYIN;
            end
          end else if (err == 1) begin
            state <= RESET;
          end else begin
            state <= WAIT_ACK;
          end
        end
        WAIT_KEYIN: begin
          if (rx_valid == 1 && rx_data == BREAK_CODE) begin
            state <= GET_BREAK;
          end else if (rx_valid == 1 && rx_data == EXTEND_CODE) begin
            state <= GET_EXTEND;
          end else if (rx_valid == 1) begin
            state <= WAIT_KEYIN;
            valid <= 1;
          end else if (err == 1) begin
            state <= RESET;
          end else begin
            state <= WAIT_KEYIN;
          end
        end
        GET_BREAK: begin
          is_extend <= is_extend;
          if (rx_valid == 1) begin
            state <= WAIT_KEYIN;
            valid <= 1;
            is_break <= 1;
          end else if (err == 1) begin
            state <= RESET;
          end else begin
            state <= GET_BREAK;
          end
        end
        GET_EXTEND: begin
          if (rx_valid == 1 && rx_data == BREAK_CODE) begin
            state <= GET_BREAK;
            is_extend <= 1;
          end else if (rx_valid == 1) begin
            state <= WAIT_KEYIN;
            valid <= 1;
            is_extend <= 1;
          end else if (err == 1) begin
            state <= RESET;
          end else begin
            state <= GET_EXTEND;
          end
        end
        RESET_WAIT_BAT: begin
          if (rx_valid == 1 && rx_data == RSP_BAT_PASS) begin
            state <= WAIT_KEYIN;
          end else if (rx_valid == 1) begin
            state <= RESET;
          end else if (err == 1) begin
            state <= RESET;
          end else begin
            state <= RESET_WAIT_BAT;
          end
        end
        default: begin
          state <= RESET;
          valid <= 0;
        end
      endcase
    end
  end

  // Define PS/2 interface
  Ps2Interface #(
    .SYSCLK_FREQUENCY_HZ(SYSCLK_FREQUENCY_HZ)
  ) Ps2Interface_i(
    .ps2_clk(PS2_CLK),
    .ps2_data(PS2_DATA),
    .clk(clk),
    .rst(rst),
    .tx_data(tx_data),
    .tx_valid(tx_valid),
    .rx_data(rx_data),
    .rx_valid(rx_valid),
    .busy(busy),
    .err(err)
  );

  // Set status LEDs based on input flags
  always @(posedge clk, posedge rst) begin
    if (rst) begin
      lock_status <= 0;
    end else if (valid == 1 && is_break == 0 && is_extend == 0) begin
      case (key_in)
        CAPS_LOCK: begin
          lock_status[2] <= ~lock_status[2];
        end
        NUM_LOCK: begin
          lock_status[1] <= ~lock_status[1];
        end
        SCR_LOCK: begin
          lock_status[0] <= ~lock_status[0];
        end
        default: begin
          lock_status <= lock_status;
        end
      endcase
    end
  end

endmodule

module parity_xor_and_or (
    input [7:0] in,
    output parity,
    output and_out,
    output or_out,
    output xor_out
);

    assign and_out = in[0] & in[1] & in[2] & in[3];
    assign or_out = in[4] | in[5] | in[6] | in[7];
    assign xor_out = in[0] ^ in[1] ^ in[2] ^ in[3] ^ in[4] ^ in[5] ^ in[6] ^ in[7];
    assign parity = and_out & xor_out;

endmodule

module parity_xor_and_or_sum (
    input [7:0] in,
    output out_and,
    output out_or,
    output out_xor,
    output [7:0] parity_sum
);

    wire parity;
    wire and_out;
    wire or_out;
    wire xor_out;

    parity_xor_and_or parity_xor_and_or_inst (
        .in(in),
        .parity(parity),
        .and_out(and_out),
        .or_out(or_out),
        .xor_out(xor_out)
    );

    assign out_and = and_out;
    assign out_or = or_out;
    assign out_xor = xor_out;

    wire [8:0] sum;
    assign sum = {1'b0, parity, xor_out} + in;

    assign parity_sum = sum[7:0];

