module transition_detector (
    input clk,
    input reset,
    input [31:0] in,
    output [31:0] out
);

reg [31:0] prev_in;
reg [31:0] transition_detected;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        prev_in <= 32'b0;
        transition_detected <= 32'b0;
    end else begin
        prev_in <= in;
        transition_detected <= (prev_in & ~in);
    end
end

always @(posedge clk or posedge reset) begin
    if (reset) begin
        out <= 32'b0;
    end else begin
        out <= transition_detected;
    end
end

endmodule

