module top_module ( 
    input [2:0] sel, 
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output reg [3:0] out );

    reg [3:0] mux_out;
    reg [1:0] and_out;
    reg [3:0] xor_out;

    // 6-to-1 multiplexer
    always @*
    begin
        case (sel)
            3'b000: mux_out = data0;
            3'b001: mux_out = data1;
            3'b010: mux_out = data2;
            3'b011: mux_out = data3;
            3'b100: mux_out = data4;
            3'b101: mux_out = data5;
            default: mux_out = 4'b0;
        endcase
    end

    // Bitwise AND module
    always @*
    begin
        case (sel)
            3'b110, 3'b111: and_out = {data0[1:0], data1[1:0], data2[1:0], data3[1:0], data4[1:0], data5[1:0]} & 2'b11;
            default: and_out = 2'b0;
        endcase
    end

    // XOR module
    always @*
    begin
        xor_out = mux_out ^ {and_out, 2'b0};
    end

    // Output multiplexer
    always @*
    begin
        case (sel)
            3'b110, 3'b111: out = xor_out;
            default: out = mux_out;
        endcase
    end

endmodule

