module IntegerMultiplication(
	input [31:0] A,
	input [31:0] B,
	output reg [63:0] product,
	input start,
	input clk
);

	reg [65:0] accumulator;
	reg [6:0] cnt;
	reg oldStart;
	wire [32:0] B2n,B1n,B1,B2,addend;
	wire [63:0] result;

	// Sign-extend B to 33 bits
	assign B1n[31:0] = -B;
	assign B2n[31:0] = (-B)<<1;
	assign B1[31:0] = B;
	assign B2[31:0] = B<<1;
	assign B1n[32] = ~B[31];
	assign B2n[32] = ~B[31];
	assign B1[32] = B[31];
	assign B2[32] = B[31];

	// Initialize accumulator and counter
	initial begin
		accumulator[65:33] <= 0;
		accumulator[32:1] <= A;
		accumulator[0] <=0;
		cnt <= 32;
	end

	// Adder and Subtractor
	AdderAndSubber64 adder({31'b0,accumulator[65:33]},{31'b0,addend},1'b0,result,SF,CF,OF,PF,ZF);

	// Generate addend based on accumulator value
	assign addend = {33{~accumulator[2]&~accumulator[1]&~accumulator[0]}}&33'b0|
					{33{~accumulator[2]&~accumulator[1]& accumulator[0]}}&B1|
					{33{~accumulator[2]& accumulator[1]&~accumulator[0]}}&B1|
					{33{~accumulator[2]& accumulator[1]& accumulator[0]}}&B2|
					{33{ accumulator[2]&~accumulator[1]&~accumulator[0]}}&B2n|
					{33{ accumulator[2]&~accumulator[1]& accumulator[0]}}&B1n|
					{33{ accumulator[2]& accumulator[1]&~accumulator[0]}}&B1n|
					{33{ accumulator[2]& accumulator[1]& accumulator[0]}}&33'b0
					;

	// Multiplication process
	always @(posedge clk) begin
		if (cnt < 32) begin // accumulating
			if(cnt[0]) begin
				accumulator[63:0] <= accumulator>>>2;
				accumulator[64] <= accumulator[65];
				accumulator[65] <= accumulator[65];
			end
			else begin
				accumulator[65:33] <= result[32:0];
			end
			cnt <= cnt + 1;
		end
		else if ( cnt == 32 && (start != oldStart) ) begin // initial
			accumulator[65:33] <= 0;
			accumulator[32:1] <= A;
			accumulator[0] <=0;
			cnt <= 0;
		end
		else begin
			accumulator <= accumulator;
			cnt <= 6'd32;
		end
		oldStart <= start;
	end

	// Output product
	assign product = accumulator[64:1];

endmodule

module uart
  (
   input                      clk,
   input                      rst,  // Synchronous reset
   input                      rx,   // Data in
   output reg                 busy, // Goes high when receiving data
   output reg [7:0]           data  // Data output
   );

   parameter DATA_BITS = 8;
   parameter BAUD = 19200;
   parameter CLK_RATE = 100000000;
   localparam CLK_DIV = CLK_RATE / BAUD;

   reg [1:0] state = 2'b00;
   reg rx_reg = 1'b1;
   reg [$clog2(CLK_DIV)-1:0] baud_counter = 0;
   reg [$clog2(DATA_BITS)-1:0] rx_counter = 0;

   always @ (posedge clk) begin
      if (rst) begin
         state <= 2'b00;
         busy <= 1'b0;
         data <= 8'b0;
      end else begin
         case (state)
            2'b00: begin // STATE_IDLE
               if (~rx_reg) begin
                  busy <= 1'b1;
                  state <= 2'b01;
                  baud_counter <= 0;
                  rx_counter <= 0;
               end
            end
            2'b01: begin // STATE_WAIT_HALF
               if (baud_counter == (CLK_DIV / 2) - 1) begin
                  state <= 2'b10;
                  baud_counter <= 0;
               end else begin
                  baud_counter <= baud_counter + 1;
               end
            end
            2'b10: begin // STATE_RX
               if (baud_counter == CLK_DIV - 1) begin
                  data <= { rx_reg, data[7:1] }; // Sample the serial input
                  baud_counter <= 0;
                  if (rx_counter == DATA_BITS - 1) begin
                     state <= 2'b11;
                  end else begin
                     rx_counter <= rx_counter + 1;
                  end
               end else begin
                  baud_counter <= baud_counter + 1;
               end
            end
            2'b11: begin // STATE_END
               if (baud_counter == CLK_DIV - 1) begin
                  if (rx_reg) begin
                     busy <= 1'b0;
                     state <= 2'b00;
                  end
                  baud_counter <= 0;
               end else begin
                  baud_counter <= baud_counter + 1;
               end
            end
         endcase
         rx_reg <= rx;
      end
   end

endmodule

