module sine_lut(
    input clk, // clock signal
    input [1:0] Q, // quadrant of the angle
    input [0:0] SR, // half-quadrant of the angle
    input [11:0] sel, // angle in degrees
    output reg [15:0] out // sine value
);

    // instantiate ROM with sine values
    sine_rom rom (
        .address(sel),
        .data(out_rom)
    );

    // adjust output based on quadrant and half-quadrant
    always @(*) begin
        case(Q)
            2'b00: // first quadrant
                if(SR == 0) begin // first half
                    out <= out_rom;
                end else begin // second half
                    out <= ~out_rom + 1;
                end
            2'b01: // second quadrant
                if(SR == 0) begin // first half
                    out <= out_rom;
                end else begin // second half
                    out <= ~out_rom + 1;
                end
            2'b10: // third quadrant
                if(SR == 0) begin // first half
                    out <= ~out_rom + 1;
                end else begin // second half
                    out <= out_rom;
                end
            2'b11: // fourth quadrant
                if(SR == 0) begin // first half
                    out <= ~out_rom + 1;
                end else begin // second half
                    out <= out_rom;
                end
        endcase
    end

    // internal wires
    wire [15:0] out_rom; // output from ROM

    // ROM with sine values
    sine_rom rom (
        .address(sel),
        .data(out_rom)
    );

endmodule

