    always @(*) begin
        case(address)
            // sine values for each degree from 0 to 359
            12'd0: data = 16'h0;
            12'd1: data = 16'h64;
            12'd2: data = 16'hc8;
            // continue with sine values for each degree
            // ...
            12'd358: data = 16'hff3c;
            12'd359: data = 16'hff9f;
        endcase
    end

endmodule

module addsub_4bit(A, B, C, S, Cout);
  input [3:0] A, B;
  input C;
  output [3:0] S;
  output Cout;
  reg [3:0] temp; // temporary storage for subtraction
  wire C1, C2, C3; // carry-out for each bit

  // addition or subtraction
  assign temp = (C == 1) ? (~B + 1) : B;
  assign S = A + temp;

  // carry-out
  assign C1 = (A[0] & B[0]) | (C == 1 & temp[0]);
  assign C2 = (A[1] & B[1]) | (C1 & (A[0] | B[0])) | (C == 1 & temp[1]);
  assign C3 = (A[2] & B[2]) | (C2 & (A[1] | B[1])) | (C == 1 & temp[2]);
  assign Cout = (A[3] & B[3]) | (C3 & (A[2] | B[2])) | (C == 1 & temp[3]);

endmodule

