      5'b01110: shift_out = {data_in[17:0], data_in[31:18]};
      5'b01111: shift_out = {data_in[16:0], data_in[31:17]};
      5'b10000: shift_out = {data_in[15:0], data_in[31:16]};
      5'b10001: shift_out = {data_in[14:0], data_in[31:15]};
      5'b10010: shift_out = {data_in[13:0], data_in[31:14]};
      5'b10011: shift_out = {data_in[12:0], data_in[31:13]};
      5'b10100: shift_out = {data_in[11:0], data_in[31:12]};
      5'b10101: shift_out = {data_in[10:0], data_in[31:11]};
      5'b10110: shift_out = {data_in[9:0], data_in[31:10]};
      5'b10111: shift_out = {data_in[8:0], data_in[31:9]};
