    barrel_shifter shifter(
        .A(B),
        .S(S),
        .Y(shifted_input)
    );

    xor_gate xor(
        .A(gray_code_output),
        .B(shifted_input),
        .G(G)
    );

endmodule

module binary_to_gray_converter (
    input [3:0] B, // 4-bit binary input
    output [3:0] G // 4-bit gray code output
);

    assign G[0] = B[0];
    assign G[1] = B[0] ^ B[1];
    assign G[2] = B[1] ^ B[2];
    assign G[3] = B[2] ^ B[3];

endmodule

module barrel_shifter (
    input [3:0] A, // 4-bit input to shift
    input [3:0] S, // 4-bit shift amount
    output [3:0] Y // 4-bit shifted output
);

    assign Y = (S[3]) ? 4'b0000 : // shift left by 4 bits
                (S[2]) ? {A[1:0], A[3:2]} : // shift left by 2 bits
                (S[1]) ? {A[2:0], A[3]} : // shift right by 2 bits
                (S[0]) ? {A[3:1], A[0]} : // shift right by 1 bit
                         A; // no shift

endmodule

module xor_gate (
    input [3:0] A, // 4-bit input A
    input [3:0] B, // 4-bit input B
    output [3:0] G // 4-bit output
);

    assign G = A ^ B;

endmodule

module mem_enc_dec (
  input [mem_width-1:0] mem_addr,
  input [mem_width-1:0] mem_data,
  input [key_width-1:0] key,
  output [mem_width-1:0] enc_data
);

parameter mem_width = 8; // width of memory data
parameter key_width = 8; // width of encryption or decryption key

// Encryption algorithm
// Here we use a simple XOR operation between the memory data and the key to encrypt or decrypt the data
assign enc_data = mem_data ^ key;

endmodule

