module low_pass_filter(
  input wire slowest_sync_clk,
  input wire dcm_locked,
  input wire ext_reset_in,
  input wire mb_debug_sys_rst,
  input wire aux_reset_in,
  output reg lpf_int
);

  // Synchronize input signals to slowest_sync_clk domain
  reg sync_ext_reset_in, sync_mb_debug_sys_rst, sync_aux_reset_in, sync_dcm_locked;
  always @(posedge slowest_sync_clk) begin
    sync_ext_reset_in <= ext_reset_in;
    sync_mb_debug_sys_rst <= mb_debug_sys_rst;
    sync_aux_reset_in <= aux_reset_in;
    sync_dcm_locked <= dcm_locked;
  end

  // Combine reset signals
  reg sync_reset;
  always @(posedge slowest_sync_clk) begin
    if (sync_ext_reset_in || sync_mb_debug_sys_rst || sync_aux_reset_in) begin
      sync_reset <= 1'b1;
    end else begin
      sync_reset <= 1'b0;
    end
  end

  // Implement low-pass filter
  reg [15:0] shift_reg;
  reg [15:0] sum;
  always @(posedge slowest_sync_clk) begin
    if (sync_reset) begin
      shift_reg <= 16'h0000;
      sum <= 16'h0000;
    end else begin
      shift_reg <= {shift_reg[14:0], sync_dcm_locked};
      sum <= sum + sync_dcm_locked - shift_reg[0];
    end
  end
  assign lpf_int = sum[4:0];

  // Synchronize output signal to original clock domain
  always @(posedge slowest_sync_clk) begin
    lpf_int <= lpf_int;
  end
endmodule

module ad_iqcor_sum #(
  // select i/q if disabled
  parameter   Q_OR_I_N = 0,
  parameter   SCALE_ONLY = 0,
  parameter   DISABLE = 0) (
  // data interface
  input           clk,
  input           valid,
  input   [15:0]  data_in,
  input   [15:0]  data_iq,
  output          valid_out,
  output  [15:0]  data_out,
  output  [15:0]  data_sum,
  // control interface
  input           iqcor_enable,
  input   [15:0]  iqcor_coeff_1,
  input   [15:0]  iqcor_coeff_2);

  // internal registers
  reg             p1_valid = 'd0;
  reg     [33:0]  p1_data_p = 'd0;
  reg             valid_int = 'd0;
  reg     [15:0]  data_int = 'd0;
  reg     [15:0]  iqcor_coeff_1_r = 'd0;
  reg     [15:0]  iqcor_coeff_2_r = 'd0;

  // internal signals
  wire    [15:0]  data_i_s;
  wire    [15:0]  data_q_s;
  wire    [33:0]  p1_data_p_i_s;
  wire            p1_valid_s;
  wire    [15:0]  p1_data_i_s;
  wire    [33:0]  p1_data_p_q_s;
  wire    [15:0]  p1_data_q_s;
  wire    [15:0]  p1_data_i_int;
  wire    [15:0]  p1_data_q_int;

  // data-path disable
  generate
  if (DISABLE == 1) begin
    assign valid_out = valid;
    assign data_out = data_in;
  end else begin
    assign valid_out = valid_int;
    assign data_out = data_int;
  end
  endgenerate

  // swap i & q
  assign data_i_s = (Q_OR_I_N == 1 && SCALE_ONLY == 1'b0) ? data_iq : data_in;
  assign data_q_s = (Q_OR_I_N == 1) ? data_in : data_iq;

  // coefficients are flopped to remove warnings from vivado
  always @(posedge clk) begin
    iqcor_coeff_1_r <= iqcor_coeff_1;
    iqcor_coeff_2_r <= iqcor_coeff_2;
  end

  // scaling functions - i
  ad_mul #(.DELAY_DATA_WIDTH(17)) i_mul_i (
    .clk (clk),
    .data_a ({data_i_s[15], data_i_s}),
    .data_b ({iqcor_coeff_1_r[15], iqcor_coeff_1_r}),
    .data_p (p1_data_p_i_s),
    .ddata_in ({valid, data_i_s}),
    .ddata_out ({p1_valid_s, p1_data_i_s}));

  generate
  if (SCALE_ONLY == 0) begin
    // scaling functions - q
    ad_mul #(.DELAY_DATA_WIDTH(16)) i_mul_q (
      .clk (clk),
      .data_a ({data_q_s[15], data_q_s}),
      .data_b ({iqcor_coeff_2_r[15], iqcor_coeff_2_r}),
      .data_p (p1_data_p_q_s),
      .ddata_in (data_q_s),
      .ddata_out (p1_data_q_s));
    // sum
    ad_add #(.DATA_WIDTH(33)) i_add (
      .clk (clk),
      .data_a (p1_data_p_i_s),
      .data_b (p1_data_p_q_s),
      .data_out (p1_data_p));
  end else begin
    assign p1_data_p_q_s = 34'h0;
    assign p1_data_q_s = 16'h0;
    // sum
    assign p1_data_p = p1_data_p_i_s;
  end
  endgenerate

  generate
  if (Q_OR_I_N == 1 && SCALE_ONLY == 0) begin
    reg [15:0]  p1_data_q = 'd0;
    always @(posedge clk) begin
      p1_data_q <= p1_data_q_s;
    end
    assign p1_data_i_int = 16'h0;
    assign p1_data_q_int = p1_data_q;
  // sum
  end else begin
    reg [15:0]  p1_data_i = 'd0;
    always @(posedge clk) begin
      p1_data_i <= p1_data_i_s;
    end
    assign p1_data_i_int = p1_data_i;
    assign p1_data_q_int = 16'h0;
  end
  endgenerate

  always @(posedge clk) begin
    p1_valid <= p1_valid_s;
    if (SCALE_ONLY == 0) begin
      p1_data_p <= p1_data_p_i_s + p1_data_p_q_s;
    end else begin
      p1_data_p <= p1_data_p_i_s;
    end
  end

  // output registers
  always @(posedge clk) begin
    valid_int <= p1_valid;
    if (iqcor_enable == 1'b1) begin
      data_int <= p1_data_p[29:14];
    end else if (Q_OR_I_N == 1 && SCALE_ONLY == 0) begin
      data_int <= p1_data_q_int;
    end else begin
      data_int <= p1_data_i_int;
    end
    data_sum <= p1_data_p[33:18];
  end
  assign valid_out = valid_int & (iqcor_enable | ~DISABLE);

endmodule

