module top_module (
  input clk,
  input reset,
  input [15:0] in,
  input select,
  output reg [7:0] result
);

  reg [7:0] upper_byte_reg;
  reg [7:0] lower_byte_reg;
  wire [3:0] counter;
  wire [7:0] sum;

  assign sum = upper_byte_reg + lower_byte_reg;

  binary_decoder decoder(
    .in(select),
    .out1(upper_byte_reg),
    .out2(lower_byte_reg)
  );

  mux_2to1 mux(
    .in1(in[15:8]),
    .in2(in[7:0]),
    .select(select),
    .out(upper_byte_reg),
    .out(lower_byte_reg)
  );

  counter_4bit counter_inst(
    .clk(clk),
    .reset(reset),
    .out(counter)
  );

  always @(posedge clk) begin
    if (reset) begin
      upper_byte_reg <= 8'b0;
      lower_byte_reg <= 8'b0;
    end
    else begin
      if (select) begin
        upper_byte_reg <= in[15:8];
        lower_byte_reg <= in[7:0];
      end
      else begin
        upper_byte_reg <= counter;
        lower_byte_reg <= counter;
      end
    end
  end

  always @(posedge clk) begin
    if (reset) begin
      result <= 8'b0;
    end
    else begin
      result <= sum;
    end
  end

endmodule

