module dup_stream #(
  parameter N = 1
)(
  input wire          clk,
  input wire          in_valid,
  output wire         in_ready,
  output wire [N-1:0] out_valid,
  input wire [N-1:0]  out_ready
);
    generate
        if(N == 1) begin
            assign in_ready = out_ready[0];
            assign out_valid[0] = in_valid;
        end
        else begin
            reg [0:N-1] pending_prev;
            assign in_ready = ~| pending_prev;
            assign out_valid = in_valid ? pending_prev : 0;
            wire [0:N-1] pending = pending_prev & ~out_ready;

            always @(posedge clk) begin
                pending_prev <= in_ready ? ~0 : pending;
            end
        end
    endgenerate
endmodule

module mult_4bit_signed (
    input signed [3:0] A,
    input signed [3:0] B,
    output signed [7:0] result
);

    wire [7:0] unsigned_result;
    wire [7:0] signed_result;

    assign unsigned_result = A * B;

    // Check if the result is negative
    assign signed_result = (A[3] ^ B[3]) ? (~unsigned_result + 1) : unsigned_result;

    // Truncate the most significant bits if the result is greater than 8 bits
    assign result = signed_result[7:0];

endmodule

module adder_reg (
    input clk,
    input reset, // Synchronous active-high reset
    input [3:0] a,
    input [3:0] b,
    input select, // Select input to choose between adder and register
    output reg [7:0] q // 8-bit output from the active module
);

reg [3:0] sum;

always @ (posedge clk) begin
    if (reset) begin
        sum <= 4'b0000;
        q <= 8'b00000000;
    end else begin
        if (select) begin
            q <= sum;
        end else begin
            sum <= a + b;
            q <= sum;
        end
    end
end

endmodule

module booth_multiplier (
    input [15:0] multiplicand,
    input [15:0] multiplier,
    output reg [31:0] product
);

reg [17:0] m;
reg [17:0] a;
reg [1:0] count;

always @(*) begin
    m = {multiplier, 2'b0};
    a = {16'b0, multiplicand};
    count = 2'b10;
end

always @(posedge clk) begin
    if (count == 2'b10) begin
        if (m[1:0] == 2'b01) begin
            a = a - m;
        end
        else if (m[1:0] == 2'b10) begin
            a = a + m;
        end
    end
    else if (count == 2'b01) begin
        m = {m[16], m[17], m[17]};
    end
    count <= count - 1;
end

assign product = a;

endmodule

module decoder (
