);

always @(*) begin
    case (in)
        4'b0000: out = 16'b0000000000000001;
        4'b0001: out = 16'b0000000000000010;
        4'b0010: out = 16'b0000000000000100;
        4'b0011: out = 16'b0000000000001000;
        4'b0100: out = 16'b0000000000010000;
        4'b0101: out = 16'b0000000000100000;
        4'b0110: out = 16'b0000000001000000;
        4'b0111: out = 16'b0000000010000000;
        4'b1000: out = 16'b0000000100000000;
        4'b1001: out = 16'b0000001000000000;
        4'b1010: out = 16'b0000010000000000;
        4'b1011: out = 16'b0000100000000000;
        4'b1100: out = 16'b0001000000000000;
        4'b1101: out = 16'b0010000000000000;
        4'b1110: out = 16'b0100000000000000;
        4'b1111: out = 16'b1000000000000000;
    endcase
end

endmodule

module functional_module (
    input [31:0] product,
    input [1:0] product_high,
    input [3:0] decoder_low,
    output reg [7:0] q
);

always @(*) begin
    case ({product_high, decoder_low})
        8'b00000001: q = 8'b00000001;
        8'b00000010: q = 8'b00000010;
        8'b00000100: q = 8'b00000100;
        8'b00001000: q = 8'b00001000;
        8'b00010000: q = 8'b00010000;
        8'b00100000: q = 8'b00100000;
        8'b01000000: q = 8'b01000000;
        8'b10000000: q = 8'b10000000;
        default: q = 8'b00000000;
    endcase
end

endmodule

module top_module (
    input clk,
    input reset,
    input [15:0] multiplicand,
    input [15:0] multiplier,
    input [3:0] decoder_input,
    input select,
    output [7:0] q
);

wire [31:0] product;
wire [1:0] product_high;
wire [3:0] decoder_low;

booth_multiplier multiplier_module (
    .multiplicand(multiplicand),
    .multiplier(multiplier),
    .product(product)
);

decoder decoder_module (
    .in(decoder_input),
    .out(decoder_low)
);

functional_module functional_module (
    .product(product),
    .product_high(product_high),
    .decoder_low(decoder_low),
    .q(q)
);

always @(posedge clk) begin
    if (reset) begin
        q <= 8'b01010101;
    end
    else begin
        if (select) begin
            q <= functional_module.q;
        end
        else begin
            q <= product_high;
        end
    end
end

assign product_high = product[31:30];

endmodule

module debounce (
    input clk,
    input n_reset,
    input button_in,
    output reg DB_out
);

    parameter N = 11; // debounce time = 32 ms

    reg [N-1:0] q_reg;
    reg [N-1:0] q_next;
    reg DFF1, DFF2;
    wire q_add;
    wire q_reset;

    assign q_reset = (DFF1 ^ DFF2);
    assign q_add = ~(q_reg[N-1]);

    always @ (q_reset, q_add, q_reg) begin
        case ({q_reset, q_add})
            2'b00: q_next <= q_reg;
            2'b01: q_next <= q_reg + ({{(N-1){1'b0}}, 1'b1});
            default: q_next <= {N{1'b0}};
        endcase
    end

    always @(posedge clk) begin
        if (n_reset == 1'b0) begin
            DFF1 <= 1'b0;
            DFF2 <= 1'b0;
            q_reg <= {N{1'b0}};
        end else begin
            DFF1 <= button_in;
            DFF2 <= DFF1;
            q_reg <= q_next;
        end
    end

    always @(posedge clk) begin
        if (q_reg[N-1] == 1'b1) begin
