    end

endmodule

module fsm_up_down_counter (
  input clk,
  input reset,
  input up_down,
  output reg [3:0] count
);

  parameter IDLE_STATE = 2'b00;
  parameter UP_COUNT_STATE = 2'b01;
  parameter DOWN_COUNT_STATE = 2'b10;
  parameter RESET_STATE = 2'b11;

  reg [1:0] state;
  reg [3:0] next_count;

  always @(posedge clk) begin
    if (reset) begin
      state <= RESET_STATE;
      next_count <= 4'b0;
    end
    else begin
      case (state)
        IDLE_STATE: begin
          if (up_down) begin
            state <= UP_COUNT_STATE;
            next_count <= count + 1;
          end
          else begin
            state <= DOWN_COUNT_STATE;
            next_count <= count - 1;
          end
        end
        UP_COUNT_STATE: begin
          if (count == 4'b1111) begin
            state <= IDLE_STATE;
            next_count <= count;
          end
          else begin
            next_count <= count + 1;
          end
        end
        DOWN_COUNT_STATE: begin
          if (count == 4'b0000) begin
            state <= IDLE_STATE;
            next_count <= count;
          end
          else begin
            next_count <= count - 1;
          end
        end
        RESET_STATE: begin
          state <= IDLE_STATE;
          next_count <= 4'b0;
        end
      endcase
    end
  end

  assign count = next_count;

endmodule

module top_module(
