module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

    wire [3:0] C; // Internal carry signals
    wire [3:0] X; // Internal sum signals

    // Full adder module instance
    full_adder FA0(.A(A[0]), .B(B[0]), .Cin(Cin), .S(X[0]), .C(C[0]));
    full_adder FA1(.A(A[1]), .B(B[1]), .Cin(C[0]), .S(X[1]), .C(C[1]));
    full_adder FA2(.A(A[2]), .B(B[2]), .Cin(C[1]), .S(X[2]), .C(C[2]));
    full_adder FA3(.A(A[3]), .B(B[3]), .Cin(C[2]), .S(X[3]), .C(C[3]));

    // Output signals
    assign S = X;
    assign Cout = C[3];

endmodule

module full_adder (
    input A,
    input B,
    input Cin,
    output S,
    output C
);

    assign S = A ^ B ^ Cin;
    assign C = (A & B) | (A & Cin) | (B & Cin);

endmodule

module my_module (
    input  A1,
    input  A2,
    input  A3,
    input  A4,
    input  B1,
    output X
);

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    // AND gate implementation
    wire and_out;
    assign and_out = A1 & A2;

    // OR gate implementation
    wire or_out;
    assign or_out = A3 | A4;

    // Output selection based on B1
    assign X = B1 ? and_out : or_out;

endmodule

module Memory (
      input   io_enable,
      input   io_mem_valid,
      input   io_mem_instr,
      input  [3:0] io_mem_wstrb,
      input  [31:0] io_mem_wdata,
      input  [15:0] io_mem_addr,
      output [31:0] io_mem_rdata,
      output  io_mem_ready,
      input   clk,
      input   reset);

  // declare internal wires and registers
  wire [31:0] _zz_1;
  wire [31:0] _zz_2;
  wire [3:0] _zz_3;
  wire  _zz_4;
  reg [31:0] rdata;
  reg  ready;
  wire [13:0] addr;
  reg [7:0] memory_1_symbol0 [0:1024*10];
  reg [7:0] memory_1_symbol1 [0:1024*10];
  reg [7:0] memory_1_symbol2 [0:1024*10];
  reg [7:0] memory_1_symbol3 [0:1024*10];

  // assign inputs to internal wires
  assign _zz_2 = io_mem_wdata;
  assign _zz_3 = io_mem_wstrb;
  assign _zz_4 = (io_enable && io_mem_valid);

  // initialize memory with data from binary files
  initial begin
    $readmemb("Memory.v_toplevel_memory_1_symbol0.bin",memory_1_symbol0);
    $readmemb("Memory.v_toplevel_memory_1_symbol1.bin",memory_1_symbol1);
    $readmemb("Memory.v_toplevel_memory_1_symbol2.bin",memory_1_symbol2);
    $readmemb("Memory.v_toplevel_memory_1_symbol3.bin",memory_1_symbol3);
  end

  // always block for writing to memory
  always @ (posedge clk) begin
    if(_zz_3[0] && _zz_4) begin
      memory_1_symbol0[addr] <= _zz_2[7 : 0];
    end
    if(_zz_3[1] && _zz_4) begin
      memory_1_symbol1[addr] <= _zz_2[15 : 8];
    end
    if(_zz_3[2] && _zz_4) begin
      memory_1_symbol2[addr] <= _zz_2[23 : 16];
    end
    if(_zz_3[3] && _zz_4) begin
      memory_1_symbol3[addr] <= _zz_2[31 : 24];
    end
  end

  // assign memory data to output wire
  assign _zz_1[7 : 0] = memory_1_symbol0[addr];
  assign _zz_1[15 : 8] = memory_1_symbol1[addr];
  assign _zz_1[23 : 16] = memory_1_symbol2[addr];
  assign _zz_1[31 : 24] = memory_1_symbol3[addr];

  // calculate address from input and assign to wire
  assign addr = (io_mem_addr >>> 2);

  // always block for reading from memory
  always @ (*) begin
    if((io_enable && io_mem_valid))begin
      rdata = _zz_1;
      ready = 1'b1;
    end else begin
      rdata = (32'b00000000000000000000000000000000);
      ready = 1'b0;
    end
  end

  // assign outputs to internal wires
  assign io_mem_ready = ready;
  assign io_mem_rdata = rdata;
endmodule

