module fifo_buffer
  #(
    parameter C_WIDTH = 10,
    parameter C_DEPTH = 16
  )
  (
    input RST,
    input CLK,
    input [C_WIDTH-1:0] DIN,
    input WR,
    input RD,
    output reg [C_WIDTH-1:0] DOUT,
    output reg ERROR
  );

  // Internal memory for storing data
  reg [C_WIDTH-1:0] mem [0:C_DEPTH-1];

  // Pointers to front and end of buffer
  reg [5:0] front_ptr = 6'd0;
  reg [5:0] end_ptr = 6'd0;

  // Full and empty flags
  reg full = 1'b0;
  reg empty = 1'b1;

  always @ (posedge CLK) begin
    if (RST) begin
      // Reset pointers and flags
      front_ptr <= 6'd0;
      end_ptr <= 6'd0;
      full <= 1'b0;
      empty <= 1'b1;
      ERROR <= 1'b0;
    end else begin
      // Update pointers and flags based on read and write requests
      if (WR && !RD && !full) begin
        mem[end_ptr] <= DIN;
        end_ptr <= end_ptr + 1;
        if (end_ptr == front_ptr)
          full <= 1'b1;
        empty <= 1'b0;
      end else if (!WR && RD && !empty) begin
        DOUT <= mem[front_ptr];
        front_ptr <= front_ptr + 1;
        if (front_ptr == end_ptr)
          empty <= 1'b1;
        full <= 1'b0;
      end else if (WR && RD) begin
        ERROR <= 1'b1;
      end
    end
  end

endmodule

