module game_text_unit (
   input clk,
   input [9:0] pixel_x,
   input [9:0] pixel_y,
   input [3:0] dig0,
   input [3:0] dig1,
   input [1:0] btn,
   input [3:0] text_on,
   output [2:0] rgb
);

   // FSMD state & data registers
   reg [1:0] state_reg, state_next;
   reg [1:0] ball_reg, ball_next;
   reg [2:0] rgb_reg, rgb_next;

   // pixel tick
   wire pixel_tick = (pixel_x[0] == 1'b0) && (pixel_y[0] == 1'b0);

   // video on
   wire video_on = (pixel_x >= 10) && (pixel_x <= 310) &&
                   (pixel_y >= 10) && (pixel_y <= 230);

   //=======================================================
   // FSMD
   //=======================================================

   // FSMD next-state logic
   always @*
   begin
      state_next = state_reg;
      ball_next = ball_reg;
      // the above two lines
      case (state_reg)
         2'b00: // newgame
            begin
               ball_next = 2'b11; // three balls
               if (btn != 2'b00)  // button pressed
               begin
                  state_next = 2'b01; // play
                  ball_next = ball_reg - 1;
               end
            end
         2'b01: // play
            begin
               if (btn == 2'b11)
               begin
                  state_next = 2'b10; // newball
                  ball_next = ball_reg - 2;
               end
            end
         2'b10: // newball
            if ((btn == 2'b00))
            begin
               state_next = 2'b11; // over
               ball_next = 2'b00;
            end
         2'b11: // over
            begin
               state_next = 2'b00; // newgame
            end
      endcase
   end

   // FSMD state & data registers
   always @(posedge clk, posedge reset)
   begin
      if (reset)
      begin
         state_reg <= 2'b00; // newgame
         ball_reg <= 2'b00; // no balls
         rgb_reg <= 3'b000; // black
      end
      else
      begin
         state_reg <= state_next;
         ball_reg <= ball_next;
         if (pixel_tick)
            rgb_reg <= rgb_next;
      end
   end

   //=======================================================
   // rgb multiplexing circuit
   // without graph, text only
   //=======================================================

   always @*
   begin
      if (~video_on)
         rgb_next = 3'b000; // blank the edge/retrace
      else
      begin
         // display score, rule, or game over
         if (text_on[3] ||
             ((state_reg==2'b00) && text_on[1]) || // rule
             ((state_reg==2'b11) && text_on[0]))
            rgb_next = {3'b000, text_rgb[2:0]}; // black background
         else if (text_on[2]) // display logo
            rgb_next = text_rgb;
         else
            rgb_next = {3'b110, text_rgb[2:0]}; // yellow background
      end
   end

   // output
   assign rgb = rgb_reg;

endmodule

