module booth_multiplier (
    input clk,
    input reset,
    input signed [15:0] A,
    input signed [15:0] B,
    output reg signed [15:0] q
);

    always @(posedge clk) begin
        if (reset) begin
            q <= 0;
        end else begin
            q <= A * B;
        end
    end

endmodule

// Square wave generator module
module square_wave_generator (
    input clk,
    input reset,
    input signed [15:0] q_in,
    output reg signed [15:0] q_out
);

    reg [31:0] counter;

    always @(posedge clk) begin
        if (reset) begin
            counter <= 0;
            q_out <= 0;
        end else begin
            counter <= counter + 1;
            if (counter < 40000) begin
                q_out <= q_in;
            end else if (counter < 60000) begin
                q_out <= 0;
            end else begin
                counter <= 0;
            end
        end
    end

endmodule

