    in_reg1 <= in;
end

always @(posedge clk) begin
    in_reg2 <= in_reg1;
end

always @(posedge clk) begin
    case(state)
        2'b00: begin
            if(in_reg2 != in_reg1) begin
                state <= 2'b01;
                anyedge <= 1'b1;
            end
        end
        2'b01: begin
            state <= 2'b10;
        end
        2'b10: begin
            state <= 2'b00;
            anyedge <= 1'b0;
        end
    endcase
end

endmodule

