  parameter RESET_PORT = 1,
  parameter RESET_SENS = 0
)
(
  input clk,
  input rst,
  output reg req,
  output reg [INPUT_PORTS-1:0] stm_value,
  input rsb,
  input gnt
);

  reg [INPUT_PORTS-1:0] stimulus;

  always @(posedge clk) begin
    if (rst == RESET_SENS) begin
      stimulus <= {INPUT_PORTS{1'b0}};
      stm_value <= {INPUT_PORTS{1'b0}};
      req <= 0;
    end else begin
      if (req == 1 && rsb == 1 && gnt == 1) begin
        stimulus <= {INPUT_PORTS{ $random }};
        stm_value <= stimulus;
        req <= 0;
      end else if (req == 0 && rsb == 0 && gnt == 0) begin
        req <= 1;
      end
    end
  end

endmodule

