module calculator(a, b, op, result);
    input [7:0] a;
    input [7:0] b;
    input [1:0] op;
    output [7:0] result;

    reg [7:0] temp_result;
    reg [7:0] error_code;

    always @(*) begin
        case(op)
            2'b00: temp_result = a + b;
            2'b01: temp_result = a - b;
            2'b10: temp_result = a * b;
            2'b11: begin
                if(b == 0) begin
                    error_code = 8'h00;
                end else begin
                    temp_result = a / b;
                end
            end
        endcase
        if(temp_result > 8'hFF || temp_result < 8'h00) begin
            error_code = 8'hFF;
        end else begin
            result = temp_result;
        end
    end

    assign result = (error_code == 8'h00) ? 8'h00 : result;
endmodule

module async_reset_release (
  input reset,
  input clock,
  output release
);

  reg release_reg;
  reg [3:0] counter;

  always @(posedge clock or negedge reset) begin
    if (reset == 0) begin
      release_reg <= 0;
      counter <= 0;
    end
    else begin
      if (counter < 4) begin
        counter <= counter + 1;
        release_reg <= 0;
      end
      else begin
        release_reg <= 1;
      end
    end
  end

  assign release = release_reg;

endmodule

module nor_gate (
    input a,
    input b,
    output reg out
);

    wire nand1, nand2, inv1, inv2;

    assign nand1 = ~(a & b);
    assign nand2 = ~(a & b);
    assign inv1 = ~nand1;
    assign inv2 = ~nand2;

    always @* begin
        out = inv1 & inv2;
    end

endmodule

module priority_encoder (
    input [7:0] in,
    output reg [2:0] pos
);

    always @* begin
        if (in[0]) pos = 0;
        else if (in[1]) pos = 1;
        else if (in[2]) pos = 2;
        else if (in[3]) pos = 3;
        else if (in[4]) pos = 4;
        else if (in[5]) pos = 5;
        else if (in[6]) pos = 6;
        else if (in[7]) pos = 7;
        else pos = 0;
    end

endmodule

module final_module (
    input a,
    input [2:0] pos,
    output reg out
);

    always @* begin
        if (a % 2 == 1 && pos % 2 == 1) out = 1;
        else out = 0;
    end

endmodule

module top_module (
    input [7:0] in,
    input a,
    input b,
    output reg out,
    output reg [2:0] pos
);

    wire nor_out;

    nor_gate nor_inst (
        .a(a),
        .b(b),
        .out(nor_out)
    );

    priority_encoder priority_inst (
        .in(in),
        .pos(pos)
    );

    final_module final_inst (
        .a(nor_out),
        .pos(pos),
        .out(out)
    );

endmodule

module hyperbolic_functions (
  input signed [15:0] x,
  output signed [15:0] sineh,
  output signed [15:0] cosh,
  output signed [15:0] tanh
);

  // Constants
  localparam PI = 16'h3243; // Approximation of pi in 16-bit fixed-point format
  localparam E = 16'h2B7E;  // Approximation of e in 16-bit fixed-point format
  localparam DEG_TO_RAD = PI / 16'h00B4; // Conversion factor from degrees to radians

  // Internal signals
  wire signed [15:0] x_rad;
  wire signed [15:0] exp_x;
  wire signed [15:0] exp_neg_x;

  // Convert input angle from degrees to radians
  assign x_rad = x * DEG_TO_RAD;

  // Compute e^x and e^-x
  exp_function exp_pos(.x(x_rad), .result(exp_x));
  exp_function exp_neg(.x(-x_rad), .result(exp_neg_x));

  // Compute hyperbolic functions
  assign sineh = (exp_x - exp_neg_x) >> 1;
  assign cosh = (exp_x + exp_neg_x) >> 1;
  assign tanh = (sineh << 16) / cosh;

endmodule

// Exponential function module
module exp_function (
  input signed [15:0] x,
  output signed [15:0] result
);

  // Internal signals
  reg [31:0] fact;
  reg [31:0] power;
  reg [31:0] sum;
  integer i;

  // Compute e^x using Taylor series expansion
  always @(*) begin
    fact = 32'h00010000; // 1 in 16-bit fixed-point format
    power = 32'h00010000; // 1 in 16-bit fixed-point format
    sum = 32'h00010000; // 1 in 16-bit fixed-point format

    for (i = 1; i < 10; i = i + 1) begin
      power = (power * x) >> 16;
      fact = (fact * i) >> 16;
      sum = sum + ((power << 16) / fact);
    end
    result = sum[31:16];
  end

endmodule

