  // System signals
  input  wire                        aclk,
  input  wire                        aresetn,

  output wire [BRAM_ADDR_WIDTH-1:0]  sts_data,

  // Slave side
  output wire                        s_axis_tready,
  input  wire [AXIS_TDATA_WIDTH-1:0] s_axis_tdata,
  input  wire                        s_axis_tvalid,

  // BRAM port
  output wire                        bram_porta_clk,
