    reg a;
    reg b;
    reg sel;

    // Outputs
    wire o;

    // Instantiate the Unit Under Test (UUT)
    mux2to1 uut (
        .o(o), 
        .a(a),
        .b(b),
        .sel(sel)
    );

    initial begin
        // Initialize Inputs
        a = 0;
        b = 0;
        sel = 0;

        // Wait 100 ns for global reset to finish
        #100;

        // Test case 1: sel = 0, a = 0, b = 0
        sel = 0;
        a = 0;
        b = 0;
        #10;
        if (o !== a) $display("Test case 1 failed");

        // Test case 2: sel = 0, a = 0, b = 1
        sel = 0;
        a = 0;
        b = 1;
        #10;
