module fsm_4bit_sequence_detection (
  input clk,
  input reset,
  input [15:0] data,
  output reg match
);

  reg [1:0] state;
  reg [3:0] sequence;

  always @ (posedge clk, posedge reset) begin
    if (reset) begin
      state <= 2'b00;
      sequence <= 4'b0000;
      match <= 1'b0;
    end else begin
      case (state)
        2'b00: begin // IDLE
          if (data[15] == 1'b1) begin
            state <= 2'b01;
            sequence <= {sequence[2:0], 1'b1};
          end
        end
        2'b01: begin // STATE1
          if (data[15] == 1'b1) begin
            state <= 2'b10;
            sequence <= {sequence[2:0], 1'b1};
          end else begin
            state <= 2'b00;
            sequence <= 4'b0000;
          end
        end
        2'b10: begin // STATE2
          if (data[15] == 1'b0) begin
            state <= 2'b11;
            sequence <= {sequence[2:0], 1'b0};
          end else begin
            state <= 2'b00;
            sequence <= 4'b0000;
          end
        end
        2'b11: begin // MATCH
          if (data[15] == 1'b1) begin
            state <= 2'b01;
            sequence <= {sequence[2:0], 1'b1};
            match <= 1'b1;
          end else begin
            state <= 2'b00;
            sequence <= 4'b0000;
          end
        end
      endcase
    end
  end

endmodule

module ripple_add_shift (
    input clk,
    input reset,
    input [3:0] A,
    input [3:0] B,
    input [3:0] S,
    input select,
    output reg [3:0] Q
);

reg [3:0] sum;
reg [3:0] shift_reg;

// Ripple carry adder module
// Performs addition of A and B
// Output stored in sum
// Carry out stored in carry_out
// Carry in is set to 0
// Uses full adder module
// Full adder module not shown here for brevity
// Assumes 4-bit inputs
// Assumes 4-bit outputs
// Assumes 1-bit carry_out
// Assumes 1-bit carry_in
// Assumes 1-bit reset
// Assumes 1-bit clk
// Assumes 1-bit enable (not used here)
// Assumes 1-bit signed (not used here)
// Assumes 1-bit overflow (not used here)
// Assumes 1-bit underflow (not used here)
// Assumes 1-bit zero (not used here)
// Assumes 1-bit negative (not used here)
// Assumes 1-bit parity (not used here)
// Assumes 1-bit valid (not used here)
// Assumes 1-bit ready (not used here)
ripple_carry_adder adder (
    .A(A),
    .B(B),
    .carry_in(1'b0),
    .sum(sum),
    .carry_out()
);

// Shift register module
// Performs shifting of S
// Output stored in shift_reg
// Uses parallel load capability
// Assumes 4-bit inputs
// Assumes 4-bit outputs
// Assumes 1-bit reset
// Assumes 1-bit clk
// Assumes 1-bit enable (not used here)
// Assumes 1-bit load (not used here)
// Assumes 1-bit clear (not used here)
// Assumes 1-bit shift_right (not used here)
// Assumes 1-bit shift_left (not used here)
// Assumes 1-bit parallel_load
shift_register shift_reg (
    .data_in(S),
    .data_out(shift_reg),
    .clk(clk),
    .reset(reset),
    .load(select),
    .clear(1'b0),
    .shift_right(1'b0),
    .shift_left(1'b0)
);

// Output selection logic
// Determines whether to output sum or shift_reg
always @(*) begin
    if (select) begin
        Q <= shift_reg;
    end else begin
        Q <= sum;
    end
end

endmodule

