module dcfifo_32in_32out_32kb_fifo_generator_top
   (dout,
    empty,
    full,
    rd_data_count,
    wr_data_count,
    wr_clk,
    rd_clk,
    din,
    rst,
    rd_en,
    wr_en);
  output [31:0]dout;
  output empty;
  output full;
  output [2:0]rd_data_count;
  output [1:0]wr_data_count;
  input wr_clk;
  input rd_clk;
  input [31:0]din;
  input rst;
  input rd_en;
  input wr_en;

  wire [31:0]fifo_din;
  wire [31:0]fifo_dout;
  wire fifo_empty;
  wire fifo_full;
  wire fifo_rd_clk;
  wire [2:0]fifo_rd_data_count;
  wire fifo_rd_en;
  wire fifo_rst;
  wire fifo_wr_clk;
  wire [1:0]fifo_wr_data_count;
  wire fifo_wr_en;

  dcfifo_32in_32out_32kb_fifo_generator_ramfifo fifo
       (.din(fifo_din),
        .dout(fifo_dout),
        .empty(fifo_empty),
        .full(fifo_full),
        .rd_clk(fifo_rd_clk),
        .rd_data_count(fifo_rd_data_count),
        .rd_en(fifo_rd_en),
        .rst(fifo_rst),
        .wr_clk(fifo_wr_clk),
        .wr_data_count(fifo_wr_data_count),
        .wr_en(fifo_wr_en));

  reg [31:0] wr_ptr = 0;
  reg [31:0] rd_ptr = 0;
  reg [31:0] data_count = 0;

  always @(posedge wr_clk) begin
    if (wr_en && !fifo_full) begin
      fifo_din <= din;
      wr_ptr <= wr_ptr + 1;
      data_count <= data_count + 1;
    end
  end

  always @(posedge rd_clk) begin
    if (rd_en && !fifo_empty) begin
      dout <= fifo_dout;
      rd_ptr <= rd_ptr + 1;
      data_count <= data_count - 1;
    end
  end

  assign empty = (data_count == 0);
  assign full = (data_count == 32768);
  assign rd_data_count = data_count[14:12];
  assign wr_data_count = 3'b111 - data_count[14:12];

  assign fifo_wr_clk = wr_clk;
  assign fifo_rd_clk = rd_clk;
  assign fifo_rst = rst;
  assign fifo_wr_en = wr_en;
  assign fifo_rd_en = rd_en && !fifo_empty;
  assign fifo_dout = dout;
endmodule

