module hamming (
  input [k-1:0] d,
  output [n-1:0] c,
  output [k-1:0] d_corrected
);

parameter k = 4; // number of input data bits
parameter n = 7; // number of output code bits (k+p)

// Determine the number of parity bits required
localparam p = $clog2(k+p+1);

// Generate the parity bits
genvar i;
generate
  for (i = 0; i < p; i = i + 1) begin : parity_bit
    assign c[2**i-1] = ^d[2**i-1+:2**i];
  end
endgenerate

// Generate the code word
assign c[k+p-1:0] = d;
assign d_corrected = d;

// Calculate the syndrome
wire [p-1:0] syndrome;
genvar j;
generate
  for (j = 0; j < p; j = j + 1) begin : syndrome_bit
    assign syndrome[j] = ^{c[2**j-1+:2**j], d_corrected[2**j-1+:2**j]};
  end
endgenerate

// Correct any errors
wire error;
assign error = |syndrome;
wire [k-1:0] error_position;
genvar k;
generate
  for (k = 0; k < k; k = k + 1) begin : error_check
    assign error_position[k] = ^{syndrome, {(k+1){1'b0}}, c[k]};
  end
endgenerate
assign d_corrected[error_position] = ~d_corrected[error_position];

endmodule

