module palindrome_inverter (
    input clk,
    input reset,
    input [15:0] in_num, // 16-bit binary number input
    output reg zero_cnt, // 3-bit count of zeroes in the number
    output reg [15:0] inv_num, // inverted input number
    output reg is_palindrome // 1-bit signal indicating if the number is a palindrome
);

  reg [15:0] in_num_inv; // inverted input number
  reg [15:0] in_num_rev; // reversed input number
  reg [15:0] in_num_temp; // temporary input number
  reg [2:0] zero_cnt_temp; // temporary zero count
  reg [31:0] in_num_temp2; // temporary input number for input signal change detector
  wire [31:0] in_num_changed; // input signal change detector output
  wire [3:0] zero_cnt_temp_wire; // wire for priority encoder input
  wire [2:0] zero_cnt_wire; // wire for priority encoder output

  priority_encoder pe(
    .in(zero_cnt_temp_wire),
    .pos(zero_cnt_wire)
  );

  input_signal_detector isd(
    .clk(clk),
    .reset(reset),
    .in(in_num),
    .out(in_num_changed)
  );

  always @(posedge clk) begin
    if (reset) begin
      zero_cnt <= 0;
      inv_num <= 0;
      is_palindrome <= 0;
      in_num_inv <= 0;
      in_num_rev <= 0;
      in_num_temp <= 0;
      zero_cnt_temp <= 0;
      in_num_temp2 <= 0;
    end else begin
      // Count number of zeroes in the input number
      zero_cnt_temp <= {in_num[15], in_num[14], in_num[13], in_num[12], in_num[11], in_num[10], in_num[9], in_num[8], in_num[7], in_num[6], in_num[5], in_num[4], in_num[3], in_num[2], in_num[1], in_num[0]};
      zero_cnt <= zero_cnt_wire;

      // Invert every bit in the input number
      in_num_inv <= ~in_num;
      inv_num <= in_num_inv;

      // Reverse the input number
      in_num_temp <= in_num;
      in_num_rev[15] <= in_num_temp[0];
      in_num_rev[14] <= in_num_temp[1];
      in_num_rev[13] <= in_num_temp[2];
      in_num_rev[12] <= in_num_temp[3];
      in_num_rev[11] <= in_num_temp[4];
      in_num_rev[10] <= in_num_temp[5];
      in_num_rev[9] <= in_num_temp[6];
      in_num_rev[8] <= in_num_temp[7];
      in_num_rev[7] <= in_num_temp[8];
      in_num_rev[6] <= in_num_temp[9];
      in_num_rev[5] <= in_num_temp[10];
      in_num_rev[4] <= in_num_temp[11];
      in_num_rev[3] <= in_num_temp[12];
      in_num_rev[2] <= in_num_temp[13];
      in_num_rev[1] <= in_num_temp[14];
      in_num_rev[0] <= in_num_temp[15];

      // Check if the input number is a palindrome
      in_num_temp2 <= in_num;
      if (in_num_temp2 != in_num_changed) begin
        is_palindrome <= 0;
      end else if (in_num == in_num_rev) begin
        is_palindrome <= 1;
      end else begin
        is_palindrome <= 0;
      end
    end
  end

endmodule

module binary_counter(
    input [31:0] in,
    output out_odd,
    output out_even
);

wire [31:0] half_adder_out;
wire [15:0] full_adder_out;
wire [7:0] final_adder_out;

// Generate half adders
genvar i;
generate
    for (i = 0; i < 32; i = i + 2) begin : half_adder_gen
        half_adder ha(
            .a(in[i]),
            .b(in[i+1]),
            .sum(half_adder_out[i/2])
        );
    end
endgenerate

// Generate full adders
genvar j;
generate
    for (j = 0; j < 16; j = j + 2) begin : full_adder_gen
        full_adder fa(
            .a(half_adder_out[j]),
            .b(half_adder_out[j+1]),
            .cin(full_adder_out[j]),
            .sum(half_adder_out[j/2])
        );
        full_adder fa2(
            .a(half_adder_out[j+16]),
            .b(half_adder_out[j+17]),
            .cin(full_adder_out[j]),
            .sum(half_adder_out[j/2+8])
        );
        assign full_adder_out[j] = fa.cout;
        assign full_adder_out[j+1] = fa2.cout;
    end
endgenerate

// Generate final adder
genvar k;
generate
    for (k = 0; k < 8; k = k + 2) begin : final_adder_gen
        full_adder fa(
            .a(half_adder_out[k]),
            .b(half_adder_out[k+1]),
            .cin(full_adder_out[k]),
            .sum(final_adder_out[k/2])
        );
        full_adder fa2(
            .a(half_adder_out[k+8]),
            .b(half_adder_out[k+9]),
            .cin(full_adder_out[k]),
            .sum(final_adder_out[k/2+4])
        );
        assign full_adder_out[k] = fa.cout;
        assign full_adder_out[k+1] = fa2.cout;
    end
endgenerate

// Calculate out_odd and out_even
assign out_odd = final_adder_out[0] ^ final_adder_out[1] ^ final_adder_out[2] ^ final_adder_out[3] ^ final_adder_out[4] ^ final_adder_out[5] ^ final_adder_out[6] ^ final_adder_out[7];
assign out_even = ~out_odd;

endmodule

