module clock_generator(
    input rst,
    input clk50,
    input divide_more,
    input clk_dac_sel,
    output reg clk_cpu,
    output locked,
    output reg clk_dac,
    output reg rst_clk4,
    output reg E,
    output reg Q
);

    // divide clk50 to generate clk_base
    wire clk_base;
    clk50div u_clk50div (
        .CLKIN_IN(clk50), 
        .RST_IN(rst), 
        .CLKFX_OUT(clk_base), 
        .LOCKED_OUT(locked)
    );

    // generate clk_cpu by dividing clk_base
    reg [1:0] clk_cpu_cnt;
    always @(posedge clk_base or posedge rst) begin
        if (rst) begin
            clk_cpu_cnt <= 2'b0;
            clk_cpu <= 0;
        end else begin
            clk_cpu_cnt <= clk_cpu_cnt + 1'b1;
            if (divide_more) begin
                if (clk_cpu_cnt[0]) begin
                    clk_cpu <= ~clk_cpu;
                end
            end else begin
                if (clk_cpu_cnt[1]) begin
                    clk_cpu <= ~clk_cpu;
                end
            end
        end
    end

    // generate clk_dac using a counter
    reg clk_dac_sel2, clk_dac_aux;
    always @(negedge clk_base) begin
        clk_dac_sel2 <= clk_dac_sel;
    end

    reg [7:0] dac_cnt;
    always @(posedge clk_base or posedge rst) begin
        if (rst) begin
            dac_cnt <= 8'b0;
        end else begin
            if (clk_dac_sel2) begin
                clk_dac_aux <= ~clk_dac_aux;
            end else begin
                {clk_dac_aux, dac_cnt} <= {clk_dac_aux, dac_cnt} + 1'b1;
            end
        end
    end

    assign clk_dac = clk_dac_aux;

    // generate E and Q using a counter
    reg [1:0] clk4_cnt;
    reg Qr, Er;
    always @(posedge clk_base or posedge rst) begin
        if (rst) begin
            clk4_cnt <= 2'b0;
            Qr <= 1'b0;
            Er <= 1'b0;
        end else begin
            clk4_cnt <= clk4_cnt + 2'b01;
            case (clk4_cnt)
                2'b00: Qr <= 1'b1;  // RISING EDGE OF E
                2'b01: Er <= 1'b1;  // RISING EDGE OF Q
                2'b10: Qr <= 1'b0;  // FALLING EDGE OF E
                2'b11: Er <= 1'b0;  // FALLING EDGE OF Q
            endcase
        end
    end

    BUFG ebuf(.I(Er), .O(E));
    BUFG qbuf(.I(Qr), .O(Q));

    always @(negedge Q) begin
        rst_clk4 <= rst_clk4;
        rst_clk4 <= rst;
    end

endmodule

module serial_reg_iface(
    input reset_i,
    input clk_i,
    input rx_i,
    output tx_o,
    output reg cmdfifo_rxf,
    output cmdfifo_txe,
    input cmdfifo_rd,
    input cmdfifo_wr,
    output [7:0] cmdfifo_din,
    input [7:0] cmdfifo_dout
);

    wire clk;
    wire tx_out;
    wire rx_in;

    assign clk = clk_i;
    assign rx_in = rx_i;
    assign tx_o = tx_out;

    // Receive data from the host device and store it in a register
    reg [7:0] datain;
    wire data_valid;
    async_receiver AR (.clk(clk),
                       .RxD(rx_in),
                       .RxD_idle(),
                       .RxD_data_ready(data_valid),
                       .RxD_data_error(),
                       .RxD_data(datain),
                       .RxD_endofpacket());

    // Transmit data to the host device
    reg [7:0] dataout;
    wire [7:0] data;
    wire data_ready;
    assign cmdfifo_din = dataout;
    async_transmitter AT (.clk(clk),
                          .TxD_start(cmdfifo_wr),
                          .TxD_data(cmdfifo_dout),
                          .TxD(tx_out),
                          .TxD_busy(),
                          .TxD_data_ready(data_ready));

    // Indicate to the peripheral device that data is ready to be read
    always @(posedge clk) begin
        if (data_valid) begin
            cmdfifo_rxf <= 1;
            dataout <= datain;
        end
    end

    // Indicate to the host device that the peripheral device is ready to transmit data
    assign cmdfifo_txe = ~AT.TxD_busy & ~cmdfifo_wr;

    // Store data from the cmdfifo_dout bus in a register
    always @(posedge clk) begin
        if (cmdfifo_rd) begin
            cmdfifo_rxf <= 0;
        end else begin
            if (data_ready) begin
                cmdfifo_rxf <= 1;
                dataout <= data;
            end
        end
    end

endmodule

