module even_odd_counter (
    input [15:0] in,
    output [7:0] out
);

reg [15:0] shift_reg;
reg [3:0] even_count;
reg [3:0] odd_count;
wire [15:0] complement;
wire parity;

assign complement = ~in;
assign parity = (even_count[0] ^ even_count[1] ^ even_count[2] ^ even_count[3]);

always @(posedge clk) begin
    shift_reg <= {shift_reg[14:0], in[0]};
    even_count <= {even_count[2:0], in[0] ^ 1'b1};
    odd_count <= {odd_count[2:0], in[0]};
end

assign out = (parity) ? {8{1'b0}} : ((in & complement) >> 8);

assign out = (parity) ? ((in | complement) >> 8) : {8{1'b0}};

endmodule

