module pfu
#(
    parameter C_BUS_SZX      = 5, // bus width base 2 exponent
    parameter C_FIFO_DEPTH_X = 2, // pfu fifo depth base 2 exponent
    parameter C_RESET_VECTOR = 32'h00000000
)
(
    // global
    input  clk_i,
    input  clk_en_i,
    input  resetb_i,
    // instruction cache interface
    input  ireqready_i,
    output ireqvalid_o,
    output [C_BUS_SZX-1:0] ireqhpl_o,
    output [C_BUS_SZX-1:0] ireqaddr_o,
    input  irspready_o,
    input  irspvalid_i,
    input  irsprerr_i,
    input  [C_BUS_SZX-1:0] irspdata_i,
    // decoder interface
    output ids_dav_o,   // new fetch available
    input  ids_ack_i,   // ack this fetch
    output ids_sofid_o, // first fetch since vectoring
    output [C_BUS_SZX-1:0] ids_ins_o, // instruction fetched
    output ids_ferr_o,  // this instruction fetch resulted in error
    output [C_BUS_SZX-1:0] ids_pc_o,  // address of this instruction
    // vectoring and exception controller interface
    output hvec_pc_ready_o,
    input  hvec_pc_wr_i,
    input  [C_BUS_SZX-1:0] hvec_pc_din_i,
    // pfu stage interface
    input  [1:0] exs_hpl_i
);

// instruction cache interface
reg [C_BUS_SZX-1:0] ireqhpl;
reg [C_BUS_SZX-1:0] ireqaddr;
reg ireqvalid;
wire irspready;
wire irspvalid;
wire irsprerr;
wire [C_BUS_SZX-1:0] irspdata;

// prefetch FIFO
reg [C_BUS_SZX-1:0] fifo [0:(1<<C_FIFO_DEPTH_X)-1];
reg [C_FIFO_DEPTH_X-1:0] fifo_wr_ptr;
reg [C_FIFO_DEPTH_X-1:0] fifo_rd_ptr;
reg [C_FIFO_DEPTH_X-1:0] fifo_cnt;
wire fifo_empty;
wire fifo_full;
wire fifo_wr_en;
wire fifo_rd_en;
wire [C_BUS_SZX-1:0] fifo_dout;

// decoder interface
reg ids_dav;
reg [C_BUS_SZX-1:0] ids_ins;
reg [C_BUS_SZX-1:0] ids_pc;
reg ids_ferr;
reg ids_sofid;

// vectoring and exception controller interface
reg hvec_pc_ready;
reg [C_BUS_SZX-1:0] hvec_pc;

// state machine
localparam ST_IDLE = 2'b00;
localparam ST_FETCH = 2'b01;
localparam ST_WAIT = 2'b10;
reg [1:0] state;
reg [1:0] next_state;

// control signals
reg ireqready;
wire [C_BUS_SZX-1:0] bus_addr;
wire [C_BUS_SZX-1:0] bus_data;

// assign instruction cache signals
assign ireqvalid_o = ireqvalid;
assign ireqhpl_o = ireqhpl;
assign ireqaddr_o = ireqaddr;
assign irspready = ~fifo_full;
assign irspvalid_i = irspvalid;
assign irsprerr_i = irsprerr;
assign irspdata_i = irspdata;

// assign prefetch FIFO signals
assign fifo_empty = (fifo_cnt == 0);
assign fifo_full = (fifo_cnt == (1<<C_FIFO_DEPTH_X));
assign fifo_wr_en = (state == ST_FETCH) & ~fifo_full;
assign fifo_rd_en = (ids_ack_i & (state == ST_WAIT)) | (ids_ferr & (state == ST_FETCH));
assign fifo_dout = fifo[fifo_rd_ptr];

// assign decoder interface signals
assign ids_dav_o = ids_dav;
assign ids_ins_o = ids_ins;
assign ids_pc_o = ids_pc;
assign ids_ferr_o = ids_ferr;
assign ids_sofid_o = ids_sofid;

// assign vectoring and exception controller signals
assign hvec_pc_ready_o = hvec_pc_ready;

// assign control signals
assign bus_addr = ireqaddr;
assign bus_data = irspdata;

// state machine
always @(posedge clk_i or negedge resetb_i)
begin
    if (~resetb_i)
    begin
        state <= ST_IDLE;
        fifo_wr_ptr <= 0;
        fifo_rd_ptr <= 0;
        fifo_cnt <= 0;
        ireqready <= 0;
        ids_dav <= 0;
        ids_ins <= 0;
        ids_pc <= 0;
        ids_ferr <= 0;
        ids_sofid <= 0;
        hvec_pc_ready <= 0;
        hvec_pc <= C_RESET_VECTOR;
    end
    else
    begin
        state <= next_state;
        case (state)
            ST_IDLE:
            begin
                if (ireqready_i)
                begin
                    ireqready <= 1;
                    next_state <= ST_FETCH;
                end
                else
                begin
                    ireqready <= 0;
                    next_state <= ST_IDLE;
                end
            end
            ST_FETCH:
            begin
                if (fifo_wr_en)
                begin
                    fifo[fifo_wr_ptr] <= bus_data;
                    fifo_wr_ptr <= (fifo_wr_ptr + 1) & ((1<<C_FIFO_DEPTH_X)-1);
                    fifo_cnt <= fifo_cnt + 1;
                    if (fifo_cnt == (1<<C_FIFO_DEPTH_X))
                    begin
                        ireqready <= 0;
                        next_state <= ST_WAIT;
                    end
                    else
                    begin
                        ireqready <= 1;
                        next_state <= ST_FETCH;
                    end
                end
                else
                begin
                    ireqready <= 1;
                    next_state <= ST_FETCH;
                end
            end
            ST_WAIT:
            begin
                if (fifo_rd_en)
                begin
                    fifo_rd_ptr <= (fifo_rd_ptr + 1) & ((1<<C_FIFO_DEPTH_X)-1);
                    fifo_cnt <= fifo_cnt - 1;
                    ids_dav <= 1;
                    ids_ins <= fifo[fifo_rd_ptr];
                    ids_pc <= hvec_pc;
                    ids_ferr <= 0;
                    if (fifo_cnt == 0)
                    begin
                        ids_sofid <= 1;
                        next_state <= ST_IDLE;
                    end
                    else
                    begin
                        next_state <= ST_FETCH;
                    end
                end
                else
                begin
                    ids_dav <= 0;
                    ids_ins <= 0;
                    ids_pc <= 0;
                    ids_ferr <= 0;
                    ids_sofid <= 0;
                    next_state <= ST_WAIT;
                end
            end
        endcase
    end
end

// instruction cache
bus
#(
    .C_BUS_SZX(C_BUS_SZX)
)
i_bus
(
    .clk_i(clk_i),
    .clk_en_i(clk_en_i),
    .resetb_i(resetb_i),
    .bus_en_i(ireqvalid),
    .bus_addr_i(bus_addr),
    .bus_we_i(0),
    .bus_data_i(0),
    .bus_data_o(bus_data),
    .bus_ack_o(ireqready),
    .bus_err_o(0)
);

// vectoring and exception controller
always @(posedge clk_i or negedge resetb_i)
begin
    if (~resetb_i)
    begin
        hvec_pc_ready <= 0;
    end
    else
    begin
        if (hvec_pc_wr_i)
        begin
            hvec_pc <= hvec_pc_din_i;
            hvec_pc_ready <= 1;
        end
        else
        begin
            hvec_pc_ready <= 0;
        end
    end
end

endmodule

module clock_divider(input clk, input rst, output reg clk_out);

	//Lleva la cuenta de los ciclos de reloj transcurridos
   reg [25:0] counter;

	initial 
		begin
			counter <= 26'd0;
			clk_out <= 1'b1;
		end

	always @(posedge clk or posedge rst)
	begin
		if(rst)
			begin
				counter <= 26'd0;
				clk_out <= 1'b1; //reset output clock to 1
			end	
		else
			if(counter == 26'd25000000) //convert 50 MHz to 1 Hz
				begin
					counter <= 26'd0;
					clk_out <= ~clk_out; //toggle output clock
				end
			else
				begin
					counter <= counter+1;
				end
	end	
endmodule

