    input EN,
    input [3:0] A_shift,
    input LOAD,
    input CLK,
    output Q,
    output [3:0] Y,
    output AND_output
);

    // 2-to-4 line decoder
    wire [3:0] decoder_out;
    decoder_2to4 decoder_inst (
        .A(A),
        .B(B),
        .EN(EN),
        .Y(decoder_out)
    );

