    shift_register_4bit shift_reg_inst (
        .A(A_shift),
        .LOAD(LOAD),
        .CLK(CLK),
        .Q(shift_reg_out)
    );

    // Functional module for logical AND of all four outputs
    assign AND_output = decoder_out[0] & decoder_out[1] & decoder_out[2] & decoder_out[3] & shift_reg_out;

    // Synchronous active-high reset for decoder and shift register
    wire reset;
    assign reset = ~EN;
    assign decoder_inst.reset = reset;
    assign shift_reg_inst.reset = reset;

    // Output assignments
    assign Y = decoder_out;
