module decoder_2to4 (
    input A,
    input B,
    input EN,
    output [3:0] Y,
    input reset
);

    assign Y[0] = ~(A & B & EN & ~reset);
    assign Y[1] = ~(A & ~B & EN & ~reset);
    assign Y[2] = ~(~A & B & EN & ~reset);
    assign Y[3] = ~(~A & ~B & EN & ~reset);

endmodule

// 4-bit shift register with parallel load module
module shift_register_4bit (
    input [3:0] A,
    input LOAD,
    input CLK,
