module top_module (
    input               clk         ,
    input               rst_n       ,
    input       [7:0]   data_in_1   ,
    input       [7:0]   data_in_2   ,
    input               valid_a     ,
    input               ready_b     ,
    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [8:0]   data_out
);

reg [7:0] sum1;
reg [7:0] sum2;
reg carry;

adder8 adder_inst (
    .a(data_in_1),
    .b(data_in_2),
    .sum(sum1)
);

carry_out carry_inst (
    .a(data_in_1),
    .b(data_in_2),
    .cout(carry)
);

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sum2 <= 0;
        carry <= 0;
        data_out <= 0;
        valid_b <= 0;
    end else begin
        sum2 <= {carry, sum1} + sum2;
        data_out <= {carry, sum1};
        valid_b <= valid_a;
    end
end

assign ready_a = !valid_b || ready_b;

endmodule
