module mux4to1 (
    input A,
    input B,
    input C,
    input D,
    input S0,
    input S1,
    output Y
);

    wire notS0, notS1, and1, and2, and3, and4, or1;

    // Invert the select lines
    not notS0 (S0);
    not notS1 (S1);

    // Create the AND gates
    and and1 (A, notS0, notS1);
    and and2 (B, notS0, S1);
    and and3 (C, S0, notS1);
    and and4 (D, S0, S1);

    // Create the OR gate
    or or1 (Y, and1, and2, and3, and4);

endmodule

module convolutional_encoder(
    input clk,
    input reset,
    input b,
    output reg [1:0] c
);

    // Declare "reg" signals...
    // Output bus that will be assigned values
    reg [1:0] c;
    /*
     * Output of flip-flops in the convolutional encoder
     * D_0 is the output of the first flip-flop
     * D_1 is the output of the second flip-flop
     */
    reg D_0, D_1;


    // Declare "wire" signals...
    // Defining constants: parameter [name_of_constant] = value;
    parameter WIDTH = 2;

    // First flip-flop of the convolutional encoder
    always @ (posedge clk)
    begin
        // If the reset signal is HIGH
        if (reset)
        begin
            // Ground the output signal of the first flip-flop
            D_0 <= 1'b0;
        end
        else
        begin
            // Assign the output of the 1st flip-flop to the signal b
            D_0 <= b;
        end
    end



    // Second flip-flop of the convolutional encoder
    always @ (posedge clk)
    begin
        // If the reset signal is HIGH
        if (reset)
        begin
            // Ground the output signal of the 2nd flip-flop
            D_1 <= 1'b0;
        end
        else
        begin
            // Assign the output of the 2nd flip-flop to the signal b
            D_1 <= D_0;
        end
    end



    always @ (D_0 or D_1 or b)
    begin
        // 3-input XOR gate of the convolutional encoder
        c[0]  <= b^D_0^D_1;
        // 2-input XOR gate of the convolutional encoder
        c[1]  <= b^D_1;
    end // always @ (D_0 or D_1 or b)

endmodule

module priority_mux (
    input [3:0] A,
    input [3:0] B,
    input [3:0] C,
    input [3:0] D,
    input [1:0] S,
    output reg [3:0] out
);

reg [1:0] sel;

always @(*) begin
    if (A > B && A > C && A > D) sel = 2'b00;
    else if (B > C && B > D) sel = 2'b01;
    else if (C > D) sel = 2'b10;
    else sel = 2'b11;
end

always @(sel or A or B or C or D) begin
    case (sel)
        2'b00: out = A;
        2'b01: out = B;
        2'b10: out = C;
        2'b11: out = D;
    endcase
end

endmodule

module Traffic_Light_Controller(
    input clk,
    input reset,
    output reg red,
    output reg yellow,
    output reg green
);

parameter GREEN_TIME = 30; // in seconds
parameter YELLOW_TIME = 5; // in seconds
parameter RED_TIME = 30; // in seconds

reg [4:0] state = 0;
reg [4:0] counter = 0;

always @(posedge clk or posedge reset) begin
    if(reset) begin
        state <= 0;
        counter <= 0;
        red <= 1;
        yellow <= 0;
        green <= 0;
    end else begin
        case(state)
            0: begin // Green light
                green <= 1;
                yellow <= 0;
                red <= 0;
                if(counter == GREEN_TIME * 2) begin // Multiply by 2 because clk is 1 Hz
                    counter <= 0;
                    state <= 1;
                end else begin
                    counter <= counter + 1;
                end
            end
            1: begin // Yellow light
                green <= 0;
                yellow <= 1;
                red <= 0;
                if(counter == YELLOW_TIME * 2) begin
                    counter <= 0;
                    state <= 2;
                end else begin
                    counter <= counter + 1;
                end
            end
            2: begin // Red light
                green <= 0;
                yellow <= 0;
                red <= 1;
                if(counter == RED_TIME * 2) begin
                    counter <= 0;
                    state <= 3;
                end else begin
                    counter <= counter + 1;
                end
            end
            3: begin // Yellow light
                green <= 0;
                yellow <= 1;
                red <= 0;
                if(counter == YELLOW_TIME * 2) begin
                    counter <= 0;
                    state <= 0;
                end else begin
                    counter <= counter + 1;
                end
            end
        endcase
    end
end

endmodule

