module binary_tree_mux (
    input [255:0] in,
    input [7:0] sel,
    output reg out
);

reg [255:0] tree [0:255];

integer i, j;

always @(*) begin
    for (i = 0; i < 256; i = i + 2) begin
        if (sel[6:0] == i) begin
            if (sel[7] == 0) begin
                out = in[i];
            end else begin
                out = in[i+1];
            end
        end
    end
    for (j = 1; j < 8; j = j + 1) begin
        for (i = 0; i < 256; i = i + 2**j) begin
            if (sel[7-j] == 0) begin
                tree[j][i] = tree[j-1][i];
                tree[j][i+2**(j-1)] = tree[j-1][i+2**(j-1)];
            end else begin
                tree[j][i] = tree[j-1][i+2**(j-1)];
                tree[j][i+2**(j-1)] = tree[j-1][i];
            end
        end
    end
    out = tree[7][0];
end

endmodule

