    // Logic for RAM/ROM interface
    reg [7:0] ram [0:65535];
    reg [7:0] rom [0:65535];
    reg [7:0] data_out;

    always @(posedge clk) begin
        if (!rst) begin
            data_out <= 8'hFF;
        end else if (!romcs_n) begin
            data_out <= 8'hFF;
        end else if (!ramcs_n && !ramwr_n) begin
            data_out <= ram[cpuramaddr];
        end else if (!ramcs_n && ramwr_n) begin
            ram[cpuramaddr] <= data_from_ram;
            data_out <= 8'h00;
        end else begin
            data_out <= 8'hFF;
        end
    end

    assign data_from_ram = data_out;

endmodule

