module ALU_4bit_behav (A, B, OP, R, COUT);
  input [3:0] A, B;
  input [1:0] OP;
  output reg [3:0] R;
  output reg COUT;

  always @(*) begin
    case (OP)
      2'b00: begin // addition
        R = A + B;
        COUT = (A[3] & B[3]) | (A[3] & ~R[3]) | (B[3] & ~R[3]);
      end
      2'b01: begin // subtraction
        R = A - B;
        COUT = (A[3] & ~B[3]) | (~R[3] & B[3]);
      end
      2'b10: begin // bitwise AND
        R = A & B;
        COUT = 1'b0;
      end
      2'b11: begin // bitwise OR
        R = A | B;
        COUT = 1'b0;
      end
      default: begin // bitwise XOR
        R = A ^ B;
        COUT = 1'b0;
      end
    endcase
  end

endmodule

module clk_gen (
    input clk_in,
    input reset,
    output reg clk_out,
    output reg locked
);

reg [31:0] counter;
reg [31:0] divisor;

always @(posedge clk_in or posedge reset) begin
    if (reset) begin
        counter <= 0;
        divisor <= 0;
        clk_out <= 0;
        locked <= 0;
    end else begin
        counter <= counter + 1;
        if (counter == divisor) begin
            clk_out <= ~clk_out;
            counter <= 0;
        end
    end
end

always @(posedge clk_in or posedge reset) begin
    if (reset) begin
        locked <= 0;
    end else begin
        if (divisor == 0) begin
            locked <= 0;
        end else if (counter == (divisor - 1)) begin
            locked <= 1;
        end
    end
end

assign divisor = (clk_in == 0) ? 0 : (clk_in / 100_000_000);

endmodule

module calculator(clk, rst, opcode, operand1, operand2, result, valid);

  input clk;
  input rst;
  input [1:0] opcode;
  input signed [7:0] operand1;
  input signed [7:0] operand2;
  output reg signed [7:0] result;
  output reg valid;

  always @(posedge clk) begin
    if (rst) begin
      result <= 0;
      valid <= 0;
    end else begin
      case (opcode)
        2'b00: result <= operand1 + operand2; // addition
        2'b01: result <= operand1 - operand2; // subtraction
        2'b10: result <= operand1 * operand2; // multiplication
        2'b11: result <= operand1 / operand2; // division
      endcase
      valid <= 1;
    end
  end

endmodule

module calculator(
