module delay_buffer (
    input data_in,
    input clk,
    input rst,
    input [2:0] delay,
    input [1:0] bypass,
    input [1:0] mode,
    output reg data_out
);

reg [2:0] delay_counter;

always @(posedge clk) begin
    if (rst) begin
        data_out <= 1'b0;
        delay_counter <= 3'b0;
    end else begin
        case (mode)
            2'b00: begin // bypass mode
                data_out <= data_in;
            end
            2'b01: begin // delay mode
                if (delay_counter == delay) begin
                    data_out <= data_in;
                    delay_counter <= 3'b0;
                end else begin
                    data_out <= 1'b0;
                    delay_counter <= delay_counter + 1;
                end
            end
            2'b10: begin // mixed mode
                case (bypass)
                    2'b00: begin // bypass input
                        data_out <= data_in;
                    end
                    2'b01, 2'b10: begin // delay input
                        if (delay_counter == delay) begin
                            data_out <= data_in;
                            delay_counter <= 3'b0;
                        end else begin
                            data_out <= 1'b0;
                            delay_counter <= delay_counter + 1;
                        end
                    end
                endcase
            end
        endcase
    end
end

endmodule

module magnitude_comparator_4bit (
    input [3:0] A,
    input [3:0] B,
    output EQ,
    output GT,
    output LT
);

reg [3:0] A_reg, B_reg;
reg [2:0] stage;

assign EQ = (A == B);
assign GT = (A > B);
assign LT = (A < B);

always @(posedge clk) begin
    case(stage)
        0: begin
            A_reg <= A;
            B_reg <= B;
            stage <= 1;
        end
        1: begin
            A_reg <= A_reg;
            B_reg <= B_reg;
            stage <= 2;
        end
        2: begin
            A_reg <= A_reg;
            B_reg <= B_reg;
            stage <= 3;
        end
        3: begin
            A_reg <= A_reg;
            B_reg <= B_reg;
            stage <= 0;
        end
    endcase
end

endmodule

