module top_module ( 
    input [99:0] a, b, // 100-bit inputs for binary multiplier
    input [99:0] in, // 100-bit input for bit-shifting module
    output [199:0] product, // 200-bit output for binary multiplier
    output [99:0] out, // 100-bit output from bit-shifting module
    output [299:0] final_output // 300-bit output from functional module
);

    // Binary Multiplier
    wire [199:0] binary_product;
    binary_multiplier binary_mult(a, b, binary_product);

    // Bit-Shifting Module
    wire [99:0] reversed_bits;
    bit_shifter bit_shift(in, reversed_bits);

    // XOR Module
    wire [299:0] xor_output;
    xor_module xor_gate(binary_product, reversed_bits, xor_output);

    // Output Connections
    assign product = binary_product;
    assign out = reversed_bits;
    assign final_output = xor_output;

endmodule

module binary_multiplier (
    input [99:0] a, b,
    output [199:0] product
);

    // Binary Product
    wire [199:0] binary_product;

    // Generate Binary Product
    genvar i, j;
    generate
        for (i = 0; i < 100; i = i + 1) begin
            for (j = 0; j < 100; j = j + 1) begin
                assign binary_product[i+j] = binary_product[i+j] + (a[i] & b[j]);
            end
        end
    endgenerate

    // Output Connection
    assign product = binary_product;

endmodule

