  wire [15:0] counter_out;
  wire [15:0] func_out;

  mux mux_inst (
    .in1(in1),
    .in2(in2),
    .select(select),
    .y(mux_out)
  );

  bcd_counter counter_inst (
    .clk(clk),
    .reset(reset),
    .ena(ena),
    .q(counter_out)
  );

  functional_module func_inst (
    .in1(mux_out),
    .in2(counter_out),
    .in3(in3),
    .y(func_out)
  );

  pwm_generator pwm_inst (
    .clk(clk),
    .duty_cycle(func_out[15:6]),
    .pwm_out(pwm)
  );

  motor_direction dir_inst (
    .pwm_in(pwm),
