module fsm_traffic_light_control (
  input clock,
  input reset,
  output reg green_led,
  output reg yellow_led,
  output reg red_led
);

  parameter GREEN = 2'b00;
  parameter YELLOW = 2'b01;
  parameter RED = 2'b10;

  reg [1:0] state;

  always @(posedge clock) begin
    if (reset) begin
      state <= GREEN;
    end else begin
      case (state)
        GREEN: begin
          green_led <= 1'b1;
          yellow_led <= 1'b0;
          red_led <= 1'b0;
          state <= YELLOW;
        end
        YELLOW: begin
          green_led <= 1'b0;
          yellow_led <= 1'b1;
          red_led <= 1'b0;
          state <= RED;
        end
        RED: begin
          green_led <= 1'b0;
          yellow_led <= 1'b0;
          red_led <= 1'b1;
          state <= GREEN;
        end
      endcase
    end
  end

endmodule

module calculator(input [31:0] inputA, input [31:0] inputB, input [2:0] ALUop, output [31:0] result, output zero);

reg [31:0] result;
reg zero;

always @ (inputA, inputB, ALUop) begin
    case (ALUop)
        3'b010: result = inputA + inputB;
        3'b110: result = inputA - inputB;
        3'b001: result = inputA | inputB;
        3'b000: result = inputA & inputB;
        3'b111: begin
            if (inputA < inputB) begin
                result = 32'h1;
            end else begin
                result = 32'h0;
            end
        end
    endcase

    if (result == 32'h0) begin
        zero = 1'b1;
    end else begin
        zero = 1'b0;
    end
end

endmodule

