always @(posedge clk) begin
    if (Reset) begin
        Q1 <= 3'b0;
        Q2 <= 3'b0;
        Q3 <= 3'b0;
    end
    else begin
        Q1 <= Load ? {B, A, Q[0]} : {Q[1:0], Q[0]};
        Q2 <= Q1;
        Q3 <= Q2;
    end
end

assign Q = Q3;

