module traffic_light_controller(
    input clk,
    input pedestrian_button,
    output reg red_light,
    output reg yellow_light,
    output reg green_light
);

reg [5:0] counter = 0; // 6-bit counter for 1 Hz clock
reg [3:0] pedestrian_counter = 0; // 4-bit counter for pedestrian crossing

always @(posedge clk) begin
    counter <= counter + 1;

    if (pedestrian_button) begin
        // Pedestrian crossing mode
        if (pedestrian_counter < 10) begin
            red_light <= 0;
            yellow_light <= 0;
            green_light <= 0;
            pedestrian_counter <= pedestrian_counter + 1;
        end else begin
            pedestrian_counter <= 0;
        end
    end else begin
        // Standard traffic light pattern
        if (counter < 20) begin
            red_light <= 0;
            yellow_light <= 0;
            green_light <= 1;
        end else if (counter < 25) begin
            red_light <= 0;
            yellow_light <= 1;
            green_light <= 0;
        end else if (counter < 45) begin
            red_light <= 1;
            yellow_light <= 0;
            green_light <= 0;
        end else begin
            counter <= 0;
        end
    end
end

endmodule

module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    input C_in,
    input C_out,
    output reg [3:0] S,
    output reg C
);

    wire [3:0] sum;
    wire [3:0] carry;

    assign sum = A + B + C_in;
    assign carry = (A[3] & B[3]) | (A[3] & C_in) | (B[3] & C_in);

    assign C = C_out ? carry[3] : 0;
    always @(*) begin
        if(C_out) begin
            S = {carry[2:0], sum[3]};
        end else begin
            S = sum;
        end
    end

endmodule

module bin_to_dec_converter(
    input clk,
    input rst,
    input [3:0] bin_in,
    output [3:0] dec_out,
    output valid_out
);

reg [3:0] dec_out_reg;
reg valid_out_reg;

always @(posedge clk) begin
    if (rst) begin
        dec_out_reg <= 0;
        valid_out_reg <= 0;
    end
    else begin
        case (bin_in)
            4'b0000: dec_out_reg <= 4'b0000;
            4'b0001: dec_out_reg <= 4'b0001;
            4'b0010: dec_out_reg <= 4'b0010;
            4'b0011: dec_out_reg <= 4'b0011;
            4'b0100: dec_out_reg <= 4'b0100;
            4'b0101: dec_out_reg <= 4'b0101;
            4'b0110: dec_out_reg <= 4'b0110;
            4'b0111: dec_out_reg <= 4'b0111;
            4'b1000: dec_out_reg <= 4'b1000;
            4'b1001: dec_out_reg <= 4'b1001;
            4'b1010: dec_out_reg <= 4'b1010;
            4'b1011: dec_out_reg <= 4'b1011;
            4'b1100: dec_out_reg <= 4'b1100;
            4'b1101: dec_out_reg <= 4'b1101;
            4'b1110: dec_out_reg <= 4'b1110;
            4'b1111: dec_out_reg <= 4'b1111;
        endcase
        valid_out_reg <= 1;
    end
end

assign dec_out = dec_out_reg;
assign valid_out = valid_out_reg;

endmodule

