module MemoryAdapter (
  input PixelClk2,
  input [24:0] ExtAddr,
  input [31:0] ExtDataWrite,
  input [1:0] ExtDataMask,
  output [31:0] ExtDataRead,
  output [1:0] ExtOP,
  output ExtReq,
  input ExtReady,
  input [24:0] Address,
  input [31:0] DataWrite,
  output [31:0] DataRead,
  input [1:0] DataSize,
  input ReadWrite,
  input Request,
  output Ready,
  output [12:0] SDRAM_ADDR,
  inout [15:0] SDRAM_DATA,
  output reg [8:0] BufferAddr,
  inout [15:0] BufferData,
  output reg BufferWrite
);

  // Internal signals
  reg [31:0] buffer[0:511];
  reg [1:0] buffer_mask;
  reg [31:0] ext_data;
  reg [31:0] ext_data_read;
  reg [1:0] ext_op;
  reg ext_req;
  wire ext_ready;
  reg [31:0] sdram_data;
  reg [12:0] sdram_addr;
  reg [1:0] data_size;
  wire read_write;
  wire request;
  wire [31:0] data_write;
  wire [24:0] address;
  wire ready;

  // Buffer write logic
  always @(posedge PixelClk2) begin
    if (BufferWrite) begin
      case (buffer_mask)
        2'b00: buffer[BufferAddr] <= {16'h0000, DataWrite[15:0]};
        2'b01: buffer[BufferAddr] <= {16'h0000, DataWrite[23:8]};
        2'b10: buffer[BufferAddr] <= {DataWrite[15:0], 16'h0000};
        2'b11: buffer[BufferAddr] <= {DataWrite[23:8], 16'h0000};
        default: buffer[BufferAddr] <= {16'h0000, 16'h0000};
      endcase
    end
  end

  // Buffer read logic
  assign BufferData = buffer[BufferAddr];

  // External memory read/write logic
  always @(posedge PixelClk2) begin
    case (ext_op)
      2'b00: begin // Read
        if (ext_req && ext_ready) begin
          ext_data_read <= $readmemh("external_memory.mem", ext_addr);
        end
      end
      2'b01: begin // Write
        if (ext_req && ext_ready) begin
          $writememh("external_memory.mem", ext_addr, ext_data);
        end
      end
      default: begin // Idle
        ext_data_read <= 32'h00000000;
      end
    endcase
  end

  // External memory interface
  assign ExtDataRead = ext_data_read;
  assign ExtOP = ext_op;
  assign ExtReq = ext_req;
  assign ext_ready = ExtReady;

  // Video generator interface
  assign sdram_addr = Address[12:0];
  assign data_size = DataSize;
  assign read_write = ReadWrite;
  assign request = Request;
  assign data_write = DataWrite;
  assign address = Address;
  assign ready = Ready;

  // SDRAM read/write logic
  SDRAM SDRAM_inst (
    .PixelClk2(PixelClk2),
    .SDRAMCK(sdram_data[0]),
    .CMD({sdram_data[1], sdram_data[2], sdram_data[3], sdram_data[4], sdram_data[5]}),
    .DQM({sdram_data[6], sdram_data[7]}),
    .BANK({sdram_data[8], sdram_data[9]}),
    .ADDR(sdram_addr),
    .DATA(SDRAM_DATA)
  );

  // Video generator read/write logic
  always @(posedge PixelClk2) begin
    if (request && ready) begin
      case (data_size)
        2'b00: begin // Byte
          if (read_write) begin // Read
            DataRead <= {24'h000000, buffer[address[8:0]][7:0]};
          end else begin // Write
            buffer[address[8:0]][7:0] <= data_write[7:0];
          end
        end
        2'b01: begin // Halfword
          if (read_write) begin // Read
            DataRead <= {16'h0000, buffer[address[8:0]][15:0]};
          end else begin // Write
            case (address[0])
              1'b0: buffer[address[8:0]][15:8] <= data_write[15:8];
              1'b1: buffer[address[8:0]][7:0] <= data_write[7:0];
            endcase
          end
        end
        2'b10: begin // Word
          if (read_write) begin // Read
            DataRead <= buffer[address[8:0]];
          end else begin // Write
            buffer[address[8:0]] <= data_write;
          end
        end
        default: begin // Idle
          DataRead <= 32'h00000000;
        end
      endcase
    end
  end

endmodule

