module PLL (
  input ref_clk, // reference frequency signal with frequency f_ref
  input out_clk, // desired output frequency signal with frequency f_out
  output reg out // output signal with desired frequency and phase
);

parameter N = 10; // multiplication factor of the PLL
parameter M = 5; // division factor of the PLL
parameter C = 8; // number of bits used to represent the phase of the output signal

reg [C-1:0] phase; // phase accumulator
reg [C-1:0] phase_diff; // phase difference between ref_clk and out_clk
reg [C-1:0] phase_diff_accum; // accumulated phase difference
reg [C-1:0] control_voltage; // control voltage for VCO
reg [C-1:0] vco_phase; // phase of VCO
reg [C-1:0] vco_freq; // frequency of VCO

// Define PFD
always @(posedge ref_clk or posedge out_clk) begin
  if (ref_clk && !out_clk) begin
    phase_diff <= phase_diff + {1'b0, phase};
  end else if (!ref_clk && out_clk) begin
    phase_diff <= phase_diff - {1'b0, phase};
  end
end

// Define charge pump
always @* begin
  if (phase_diff_accum > 0) begin
    control_voltage <= control_voltage + 1;
    phase_diff_accum <= phase_diff_accum - 1;
  end else if (phase_diff_accum < 0) begin
    control_voltage <= control_voltage - 1;
    phase_diff_accum <= phase_diff_accum + 1;
  end
end

// Define frequency divider
always @(posedge ref_clk) begin
  if (vco_freq == M-1) begin
    vco_freq <= 0;
  end else begin
    vco_freq <= vco_freq + 1;
  end
end

// Define loop filter
always @* begin
  phase_diff_accum <= phase_diff_accum + phase_diff;
  control_voltage <= control_voltage + (phase_diff_accum >> (C-4));
end

// Define VCO
always @(posedge ref_clk) begin
  vco_phase <= vco_phase + {1'b0, (N*vco_freq) >> (C-8)};
end

// Define phase detector
always @(posedge ref_clk) begin
  phase <= phase + {1'b0, (N*vco_freq) >> (C-8)};
  if (phase >= out_clk) begin
    out <= 1;
    phase <= phase - out_clk;
  end else begin
    out <= 0;
  end
end

endmodule

module flipflop_adder (
    input clk,
    input [7:0] reset,      // Synchronous reset
    input [7:0] d,
    output [7:0] q
);

reg [7:0] q_reg;
wire [7:0] sum;

always @(negedge clk) begin
    if (reset[0]) q_reg[0] <= 1'b0;
    else q_reg[0] <= d[0];

    if (reset[1]) q_reg[1] <= 1'b0;
    else q_reg[1] <= d[1];

    if (reset[2]) q_reg[2] <= 1'b0;
    else q_reg[2] <= d[2];

    if (reset[3]) q_reg[3] <= 1'b0;
    else q_reg[3] <= d[3];

    if (reset[4]) q_reg[4] <= 1'b0;
    else q_reg[4] <= d[4];

    if (reset[5]) q_reg[5] <= 1'b0;
    else q_reg[5] <= d[5];

    if (reset[6]) q_reg[6] <= 1'b0;
    else q_reg[6] <= d[6];

    if (reset[7]) q_reg[7] <= 1'b0;
    else q_reg[7] <= d[7];
end

assign sum = q_reg[0] + q_reg[1] + q_reg[2] + q_reg[3] + q_reg[4] + q_reg[5] + q_reg[6] + q_reg[7];

assign q = sum;

endmodule

module MiniAlu (
    input wire Clock,
    input wire Reset,
    input wire [2:0] iSel,
    output reg [7:0] oLed
);

    reg [7:0] a, b;

    always @(posedge Clock, negedge Reset) begin
        if (!Reset) begin
            // Reset to 0
            a <= 8'h00;
            b <= 8'h00;
            oLed <= 8'h00;
        end
        else begin
            // Perform the operation based on iSel
            case (iSel)
                3'b000: oLed <= a + b;
                3'b001: oLed <= a - b;
                3'b010: oLed <= a & b;
                3'b011: oLed <= a | b;
                3'b100: oLed <= a ^ b;
                3'b101: oLed <= a << 1;
                3'b110: oLed <= a >> 1;
                3'b111: oLed <= {a[0], a[7:1]};
            endcase
        end
    end

    always @(posedge Clock) begin
        // Update the input operands
        a <= a;
        b <= b;
    end

endmodule

