    input csi_clock_clk,
    input csi_clock_reset,

    // Avalon MM slave: status/control
    input        avs_ctrl_address,
    input        avs_ctrl_read,
    output [31:0]avs_ctrl_readdata,
    input        avs_ctrl_write,
    input  [31:0]avs_ctrl_writedata,

    // Custom pattern generator interface
    input clkena,
    input trigger,
    output [5:0]pgout
);

    /* Avalon 16-bit register file
    0   w  control register
    0   r  status register
    1   w  period register

    Control register:
    bit 7: enable pattern generator
    bit 2: enable loop
    bit 1: enable external trigger
    bit 0: start single sequence
    */

    // Control register bits
    reg ctrl_ena;
    reg ctrl_ext;
    reg ctrl_loop;
    reg ctrl_start;

    wire start;
    wire enable;
    wire ena_loop;
    wire ena_ext;
    wire set_start;

    wire running;

    reg [15:0] period;
    reg [15:0] loopcnt;

    wire  [7:0] seq_address;
    wire [15:0] seq_command;

    // --- Control register programming ---------------------------------------
    always @(posedge csi_clock_clk or posedge csi_clock_reset)
    begin
        if (csi_clock_reset)
        begin
            { ctrl_ena, ctrl_loop, ctrl_ext, ctrl_start } <= 4'b0000;
            period   <= 0;
        end
        else if (avs_ctrl_write)
        begin
            case (avs_ctrl_address)
                0: { ctrl_ena, ctrl_loop, ctrl_ext, ctrl_start }
                        <= { avs_ctrl_writedata[7], avs_ctrl_writedata[2:0] };
                1: period   <= avs_ctrl_writedata[15:0];
            endcase
        end
        else if (clkena) ctrl_start <= 0;
    end

    assign avs_ctrl_readdata =
        avs_ctrl_address ? { 16'd0, period } : { 31'd0, running };

    assign enable    = ctrl_ena;
    assign ena_ext   = ctrl_ext;
    assign ena_loop  = ctrl_loop;
    assign set_start = ctrl_start;

    // --- Trigger generator --------------------------------------------------
    wire trig_loop = loopcnt == 0;

    always @(posedge csi_clock_clk or posedge csi_clock_reset)
    begin
        if (csi_clock_reset) loopcnt <= 0;
        else if (clkena)
        begin
            if (ena_loop)
            begin
                if (trig_loop) loopcnt <= period;
                else loopcnt <= loopcnt - 1;
            end
            else loopcnt <= 0;
        end
    end

    assign start = set_start || (ena_loop && trig_loop) || (ena_ext && trigger);

    // Internal memory to store pattern sequence
    reg [5:0] pattern_mem [0:63];
    integer i;
    initial
    begin
        for (i = 0; i < 64; i = i + 1)
            pattern_mem[i] = 6'b000000;
    end

    // --- Pattern generator --------------------------------------------------
    wire [5:0] pattern_idx;
    reg [5:0]  pattern_reg;

    assign pattern_idx = running ? pattern_reg : 6'b000000;
    assign pgout = pattern_idx;

    pg_ram ram
    (
        // Avalon port
        .clock     (csi_clock_clk),
        .wren      (avs_ctrl_write && (avs_ctrl_address == 2'h1)),
        .wraddress (avs_ctrl_writedata[7:0]),
        .byteena_a (2'b11),
        .data      (avs_ctrl_writedata[15:0]),

        // Pattern generator port
        .rdaddress (seq_address),
        .q (seq_command)
    );

    always @(posedge csi_clock_clk or posedge csi_clock_reset)
    begin
        if (csi_clock_reset)
        begin
            pattern_reg <= 6'b000000;
            running     <= 0;
        end
        else if (clkena)
        begin
            if (set_start) pattern_reg <= 6'b000000;
            else if (running)
            begin
                if (pattern_reg == 6'h3F) pattern_reg <= 6'b000000;
                else pattern_reg <= pattern_reg + 1;
            end
            else if (enable) running <= 1;
        end
    end

    // Pattern sequencer
    pg_sequencer pg
    (
        .clk(csi_clock_clk),
        .sync(clkena),
        .reset(csi_clock_reset),
        .enable(enable),
        .start(start),
        .running(running),
        .pgout(pgout),

        .ip(seq_address),
        .cmd(seq_command)
    );

endmodule

