                         in_port,
                         reset_n,

                        // outputs:
                         readdata
                      )
;

  output  [ 31: 0] readdata;
  input   [  1: 0] address;
  input            clk;
  input   [ 19: 0] in_port;
  input            reset_n;

  wire             clk_en;
  wire    [ 19: 0] data_in;
  wire    [ 19: 0] read_mux_out;
  reg     [ 31: 0] readdata;
  assign clk_en = 1;
  //s1, which is an e_avalon_slave
  assign read_mux_out = {20 {(address == 2'b00)}} & data_in | {12'b0, in_port[19:0]} & {20 {(address == 2'b01)}};
  always @(posedge clk or negedge reset_n)
    begin
      if (reset_n == 0)
          readdata <= 0;
      else if (clk_en)
          readdata <= {32'b0 | read_mux_out};
    end


  assign data_in = in_port;

endmodule

module updateCRC16 (
    input rstCRC,
    input CRCEn,
    input [7:0] dataIn,
    input clk,
    input rst,
    output [15:0] CRCResult,
    output ready
);

wire rstCRC;
wire CRCEn;
wire [7:0] dataIn;
wire clk;
wire rst;
reg [15:0] CRCResult;
reg ready;

reg [3:0] i;
reg [7:0] data;
reg doUpdateCRC;

assign ready = (doUpdateCRC == 0);

always @(posedge clk) begin
    if (rst == 1'b1 || rstCRC == 1'b1) begin
        doUpdateCRC <= 1'b0;
        i <= 4'h0;
        CRCResult <= 16'hffff;
    end
    else if (doUpdateCRC == 1'b0 && CRCEn == 1'b1) begin
        doUpdateCRC <= 1'b1;
        data <= dataIn;
    end
    else if (doUpdateCRC == 1'b1) begin
        if ((CRCResult[0] ^ data[0]) == 1'b1) begin
            CRCResult <= {1'b0, CRCResult[15:1]} ^ 16'ha001;
        end
        else begin
            CRCResult <= {1'b0, CRCResult[15:1]};
        end
        data <= {1'b0, data[7:1]};
        i <= i + 1;
        if (i == 4'h7) begin
            doUpdateCRC <= 1'b0;
            i <= 4'h0;
        end
    end
end

endmodule

module gray_binary_counter (
