    gray_to_binary_converter gray_converter(
        .G2(G2),
        .G1(G1),
        .G0(G0),
        .binary_out(binary_out)
    );

    synchronous_up_down_counter up_down_counter(
        .clk(clk),
        .reset(reset),
        .up_down(up_down),
        .out(binary_out)
    );

    always @ (posedge clk) begin
        if (reset) begin
            out <= 7'b0;
