module axi_register_slice (
    input clk,
    input resetn,

    input s_axi_valid,
    output s_axi_ready,
    input [DATA_WIDTH-1:0] s_axi_data,

    output m_axi_valid,
    input m_axi_ready,
    output [DATA_WIDTH-1:0] m_axi_data,
    input [DATA_WIDTH-1:0] m_axi_data_in
);

parameter DATA_WIDTH = 32;

parameter FORWARD_REGISTERED = 0;
parameter BACKWARD_REGISTERED = 0;

/*
 s_axi_data  -> bwd_data     -> fwd_data(1)  -> m_axi_data
 s_axi_valid -> bwd_valid    -> fwd_valid(1) -> m_axi_valid
 s_axi_ready <- bwd_ready(2) <- fwd_ready <- m_axi_ready

 (1) FORWARD_REGISTERED inserts a set of FF before m_axi_data and m_axi_valid
 (2) BACKWARD_REGISTERED insters a FF before s_axi_ready
*/

wire [DATA_WIDTH-1:0] bwd_data_s;
wire bwd_valid_s;
wire bwd_ready_s;
wire [DATA_WIDTH-1:0] fwd_data_s;
wire fwd_valid_s;
wire fwd_ready_s;

generate if (FORWARD_REGISTERED == 1) begin

reg fwd_valid = 1'b0;
reg [DATA_WIDTH-1:0] fwd_data = 'h00;

assign fwd_ready_s = ~fwd_valid | m_axi_ready;
assign fwd_valid_s = fwd_valid;
assign fwd_data_s = fwd_data;

always @(posedge clk) begin
    if (~fwd_valid | m_axi_ready)
        fwd_data <= bwd_data_s;
end

always @(posedge clk) begin
    if (resetn == 1'b0) begin
        fwd_valid <= 1'b0;
    end else begin 
        if (bwd_valid_s)
            fwd_valid <= 1'b1;
        else if (m_axi_ready)
            fwd_valid <= 1'b0;
    end
end

end else begin
assign fwd_data_s = bwd_data_s;
assign fwd_valid_s = bwd_valid_s;
assign fwd_ready_s = m_axi_ready;
end
endgenerate

generate if (BACKWARD_REGISTERED == 1) begin

reg bwd_ready = 1'b1;
reg [DATA_WIDTH-1:0] bwd_data = 'h00;

assign bwd_valid_s = ~bwd_ready | s_axi_valid;
assign bwd_data_s = bwd_ready ? s_axi_data : bwd_data;
assign bwd_ready_s = bwd_ready;

always @(posedge clk) begin
    if (bwd_ready)
        bwd_data <= s_axi_data;
end

always @(posedge clk) begin
    if (resetn == 1'b0) begin
        bwd_ready <= 1'b1;
    end else begin
        if (fwd_ready_s)
            bwd_ready <= 1'b1;
        else if (s_axi_valid)
            bwd_ready <= 1'b0;
    end
end

end else begin
assign bwd_valid_s = s_axi_valid;
assign bwd_data_s = s_axi_data;
assign bwd_ready_s = fwd_ready_s;
end endgenerate

assign m_axi_data = fwd_data_s;
assign m_axi_valid = fwd_valid_s;
assign s_axi_ready = bwd_ready_s;

endmodule

module fixed_point_arithmetic (
  input signed [n+m-1:0] x,
  input signed [n+m-1:0] y,
  input [1:0] ctrl,
  output signed [n+m-1:0] z
);

parameter n = 4; // number of bits used to represent the integer part of the fixed-point numbers
parameter m = 8; // number of bits used to represent the fractional part of the fixed-point numbers

// Addition
function [n+m-1:0] add;
  input signed [n+m-1:0] a;
  input signed [n+m-1:0] b;
  begin
    add = a + b;
  end
endfunction

// Subtraction
function [n+m-1:0] sub;
  input signed [n+m-1:0] a;
  input signed [n+m-1:0] b;
  begin
    sub = a - b;
  end
endfunction

// Multiplication
function [n+m-1:0] mul;
  input signed [n+m-1:0] a;
  input signed [n+m-1:0] b;
  begin
    mul = $signed(a * b) >> m;
  end
endfunction

// Division
function [n+m-1:0] div;
  input signed [n+m-1:0] a;
  input signed [n+m-1:0] b;
  begin
    div = $signed(a << m) / b;
  end
endfunction

// Connect inputs to appropriate arithmetic blocks
always @(*) begin
  case(ctrl)
    2'b00: z = add(x, y);
    2'b01: z = sub(x, y);
    2'b10: z = mul(x, y);
    2'b11: z = div(x, y);
  endcase
end

endmodule

module fsm_module(
    input clk,
    input start,
    output reg done
);

    // Define the states
    parameter Idle = 2'b00;
    parameter Running = 2'b01;

    // Define the state register and initialize to Idle
    reg [1:0] state_reg = Idle;

    // Define the counter for the Running state
    reg [8:0] running_counter = 0;

    always @(posedge clk) begin
        // State transition logic
        case(state_reg)
            Idle: begin
                if(start) begin
                    state_reg <= Running;
                    running_counter <= 0;
                end
            end
            Running: begin
                if(running_counter == 499) begin
                    state_reg <= Idle;
                    done <= 0;
                end else begin
                    if(running_counter < 50) begin
                        done <= 0;
                    end else if(running_counter < 100) begin
                        done <= 1;
                    end else begin
                        done <= 0;
                    end
                    running_counter <= running_counter + 1;
                end
            end
        endcase
    end

endmodule

