endmodule

module delay_module (
    input clk,
    input reset,
    input data_in,
    output reg data_out
);

    // Define the delay time in clock cycles
    parameter DELAY_TIME = 5;

    // Define a counter to keep track of the delay time
    reg [31:0] counter = 0;

    // Define a register to hold the delayed input signal
    reg delayed_data;

    always @(posedge clk) begin
        if (reset) begin
            // Reset the counter and delayed_data register
            counter <= 0;
            delayed_data <= 0;
        end else begin
            // Increment the counter
            counter <= counter + 1;

            if (counter == DELAY_TIME) begin
                // Output the delayed input signal
                data_out <= delayed_data;

                // Store the current input signal for the next cycle
                delayed_data <= data_in;

                // Reset the counter
                counter <= 0;
            end
        end
    end

endmodule

module hmac_generator (
  input clk,
  input rst,
  input [n-1:0] key,
  input [m-1:0] message,
  output [s-1:0] hmac,
  output valid
);

parameter n = 128; // length of the key in bits
parameter m = 512; // length of the message in bits
parameter s = 256; // length of the HMAC value in bits
parameter block_size = 512; // block size of the hash function in bits

// Internal signals
reg [n-1:0] ipad;
reg [n-1:0] opad;
reg [block_size-1:0] key_padded;
reg [block_size-1:0] message_padded;
reg [block_size-1:0] inner_hash;
reg [s-1:0] outer_hash;
wire [s-1:0] expected_hmac;
wire valid_hmac;

// Compute the inner hash
sha256 hash_inst (
  .clk(clk),
  .rst(rst),
  .data(key_padded[0:block_size-1]),
  .hash(inner_hash)
);
assign key_padded = {key, {1'b0, block_size-n-1'b1}} ^ {ipad, {1'b0, block_size-n-1'b1}};
assign message_padded = {message, {1'b0, block_size-m-1'b1}} ^ {opad, {1'b0, block_size-n-1'b1}};
assign hash_inst.data = {inner_hash, message_padded};

// Compute the outer hash
sha256 hash_inst2 (
  .clk(clk),
  .rst(rst),
  .data({opad, inner_hash}),
  .hash(outer_hash)
);
assign hash_inst2.data = {outer_hash, inner_hash};

// Compare the generated HMAC with the expected HMAC
assign expected_hmac = outer_hash[0:s-1];
assign valid_hmac = (expected_hmac == hmac);

// Generate the HMAC
assign ipad = {n{1'b00110110}}; // 0x36 repeated n times
assign opad = {n{1'b01011100}}; // 0x5c repeated n times
assign hmac = outer_hash[0:s-1];

endmodule

module fsm_consecutive_ones_count (
  input clk,
  input reset,
  input data,
  output reg [3:0] cnt
);

  // Define the states of the FSM
  parameter IDLE = 2'b00;
  parameter COUNT = 2'b01;
  parameter DONE = 2'b10;

  // Define the current state and next state variables
  reg [1:0] state, next_state;

  // Define the output register for cnt
  reg [3:0] cnt_reg;

  // Define the combinational logic for the next state and cnt
  always @ (posedge clk or negedge reset) begin
    if (reset == 0) begin
      state <= IDLE;
      cnt_reg <= 0;
    end else begin
      state <= next_state;
      cnt_reg <= cnt_reg;
    end
  end

  always @ (*) begin
    case (state)
      IDLE: begin
        next_state = COUNT;
        cnt = 0;
      end
      COUNT: begin
        if (data == 1) begin
          next_state = COUNT;
          cnt = cnt_reg + 1;
        end else begin
          next_state = DONE;
          cnt = cnt_reg;
        end
      end
      DONE: begin
        next_state = IDLE;
        cnt = cnt_reg;
      end
    endcase
  end

endmodule

module relational_verilog (
