  always @(posedge clk) begin
    if (ce) begin
      a_reg <= a;
      b_reg <= b;
      op_reg <= (a == b) ? 1'b1 : 1'b0;
    end
  end

  assign op = op_reg;

  always @(posedge clk) begin
    if (clr) begin
      a_reg <= 2'b0;
      b_reg <= 2'b0;
      op_reg <= 1'b0;
    end
  end

endmodule

