module top_module (
    input [7:0] a,
    input [7:0] b,
    output [15:0] product,
    output overflow,
    output [7:0] sqrt_abs_product
);

    wire [15:0] booth_output;
    wire [7:0] abs_product;
    wire [7:0] sqrt_input;

    booth_multiplier booth(
        .a(a),
        .b(b),
        .booth_output(booth_output)
    );

    overflow_detector overflow_detect(
        .booth_output(booth_output),
        .overflow(overflow)
    );

    absolute_value absolute(
        .booth_output(booth_output),
        .abs_product(abs_product)
    );

    square_root square_root(
        .abs_product(abs_product),
        .overflow(overflow),
        .sqrt_input(sqrt_input),
        .sqrt_abs_product(sqrt_abs_product)
    );

    assign product = booth_output;

endmodule

module booth_multiplier (
    input [7:0] a,
    input [7:0] b,
    output reg [15:0] booth_output
);

    reg [7:0] a_reg;
    reg [7:0] b_reg;
    reg [3:0] counter;
    reg [15:0] product;
    reg [1:0] state;

    always @(*) begin
        case(state)
            2'b00: begin
                a_reg = a;
                b_reg = b;
                counter = 4;
                product = {8'd0, a_reg};
                state = 2'b01;
            end
            2'b01: begin
                if(counter == 0) begin
                    state = 2'b10;
                end else begin
                    if(product[0] == 1) begin
                        product = product + {8'd0, b_reg};
                    end else if(product[7:0] == 8'hFF) begin
                        product = product + {8'd0, ~b_reg + 1};
                    end
                    product = product >> 1;
                    counter = counter - 1;
                end
            end
            2'b10: begin
                booth_output = product;
                state = 2'b00;
            end
        endcase
    end

endmodule

module overflow_detector (
    input [15:0] booth_output,
    output overflow
);

    assign overflow = (booth_output[15] == 1);

endmodule

module absolute_value (
    input [15:0] booth_output,
    output [7:0] abs_product
);

    assign abs_product = (booth_output[15] == 1) ? (~booth_output[7:0] + 1) : booth_output[7:0];

endmodule

