module bcd_counter (
    input clk,
    input reset,   // Synchronous active-high reset
    output [3:1] ena,
    output [15:0] q);

    reg [3:1] count [3:0];  // Array of 4 BCD counters
    wire [3:0] encoded [3:0];  // Array of 4-bit encoded digits

    // Generate enable signals for each digit
    assign ena = {count[3], count[2], count[1]};

    // Generate encoded digits using multiplexers
    assign encoded[3] = {count[3][3], count[3][2], count[3][1], count[3][0]};
    assign encoded[2] = {count[2][3], count[2][2], count[2][1], count[2][0]};
    assign encoded[1] = {count[1][3], count[1][2], count[1][1], count[1][0]};
    assign encoded[0] = {count[0][3], count[0][2], count[0][1], count[0][0]};

    // Generate binary output by concatenating encoded digits
    assign q = {encoded[3], encoded[2], encoded[1], encoded[0]};

    // Increment counters on rising edge of clock
    always @(posedge clk) begin
        if (reset) begin
            count <= 4'b0000;
        end else begin
            count <= {count[3], count[2], count[1], count[0] + 1};
        end
    end

endmodule

