module booth_multiplier(
    input signed [15:0] a,
    input signed [15:0] b,
    output reg [31:0] product_abs
);

reg signed [31:0] product;
reg [16:0] multiplier;
reg [16:0] multiplicand;
reg [1:0] state;

always @(*) begin
    case(state)
        2'b00: begin
            multiplier <= {1'b0, a};
            multiplicand <= {1'b0, b};
            state <= 2'b01;
        end
        2'b01: begin
            if(multiplier[0] == 1'b0 && multiplier[1] == 1'b1) begin
                product <= product + multiplicand;
            end
            else if(multiplier[0] == 1'b1 && multiplier[1] == 1'b0) begin
                product <= product - multiplicand;
            end
            multiplier <= {multiplier[15], multiplier[15:1]};
            state <= 2'b10;
        end
        2'b10: begin
            multiplier <= {product[31], multiplier[15:1]};
            state <= 2'b01;
        end
    endcase
end

always @(posedge clk) begin
    if(reset) begin
        product <= 0;
        multiplier <= 0;
        multiplicand <= 0;
        state <= 2'b00;
    end
    else begin
        product_abs <= (product[31] == 1'b1) ? ~product + 1 : product;
    end
end

endmodule

