module ALU(input clk, rst, input [4:0] fn, input signed [7:0] A, B, output reg signed [7:0] Y, output Zero, Cout);

    reg z, co, enb;
    reg outPutZ, outPutCo;

    assign Zero = outPutZ;
    assign Cout = outPutCo;

    always@(posedge clk, posedge rst) begin
        if(rst) begin
            z = 1'b0;
            co = 1'b0;
        end
        else begin
            outPutZ = z;
            outPutCo = co;
        end
    end

    always@(fn, A, B) begin
        enb = 1;
        case(fn) 
            // Addition and Subtraction
            5'b00000, 5'b00001, 5'b00010, 5'b00011: begin
                case(fn[2:0])
                    3'b000: begin
                        Y = A + B;
                        co = (A[7] ^ B[7]) ? 0 : ((A[7] ^ Y[7]) ? 1 : 0);
                    end
                    3'b001: begin
                        Y = A + B + co;
                        co = (A[7] ^ B[7]) ? 0 : ((A[7] ^ Y[7]) ? 1 : 0);
                    end
                    3'b010: begin
                        Y = A - B;
                        co = (A < B);
                    end
                    3'b011: begin
                        Y = A - B + co;
                        co = ((A + co) < B);
                    end
                    default: enb = 0;
                endcase
                z = (Y == 0);
            end

            // Bitwise AND, OR, XOR, NOT
            5'b00100, 5'b00101, 5'b00110, 5'b00111: begin
                case(fn[2:0])
                    3'b000: Y = A & B;
                    3'b001: Y = A | B;
                    3'b010: Y = A ^ B;
                    3'b011: Y = ~(A & B);
                    default: enb = 0;
                endcase
                z = (Y == 0);
            end

            // Left Shift, Right Shift, Rotate Left, Rotate Right
            5'b11000, 5'b11001, 5'b11010, 5'b11011: begin
                case(fn[1:0])
                    2'b00: begin
                        Y = A << B[4:2];
                        co = A[7] & (B[4:2] != 0);
                    end
                    2'b01: begin
                        Y = A >> B[4:2];
                        co = A[B[4:2] - 1];
                    end
                    2'b10: begin
                        Y = {A[(B[4:2] - 1):0], {1'b0, A[7:B[4:2]]}};
                        co = A[7] & (B[4:2] != 0);
                    end
                    2'b11: begin
                        Y = {{1'b0, A[7:B[4:2]]}, A[(B[4:2] - 1):0]};
                        co = A[0] & (B[4:2] != 0);
                    end
                    default: enb = 0;
                endcase
                z = (Y == 0);
            end

            // Invalid Function Code
            default: enb = 0;
        endcase
    end
endmodule

module Adder4Bit(S, V, A, B, Cin);
    output [3:0] S;
    output V;
    input [3:0] A, B;
    input Cin;

    wire [3:0] sum;
    wire carry_out;

    assign {carry_out, sum} = A + B + Cin;
    assign S = sum;
    assign V = (sum > 4'hF) ? 1 : 0;
endmodule

module full_adder(input a, input b, input cin, output sum, output cout);
    assign sum = a ^ b ^ cin;
    assign cout = (a & b) | (a & cin) | (b & cin);
endmodule

module adder8(input [7:0] a, input [7:0] b, input cin, output [7:0] sum, output cout);
    wire [7:0] s;
    wire c1, c2, c3, c4;
    full_adder fa1(a[0], b[0], cin, s[0], c1);
    full_adder fa2(a[1], b[1], c1, s[1], c2);
    full_adder fa3(a[2], b[2], c2, s[2], c3);
    full_adder fa4(a[3], b[3], c3, s[3], c4);
    full_adder fa5(a[4], b[4], c4, s[4], c1);
    full_adder fa6(a[5], b[5], c1, s[5], c2);
    full_adder fa7(a[6], b[6], c2, s[6], c3);
    full_adder fa8(a[7], b[7], c3, s[7], cout);
    assign sum = s;
endmodule

module my_video_filter_line_buffers_val_1(
    reset,
    clk,
    address0,
    ce0,
    we0,
    d0,
    q0,
    address1,
    ce1,
    we1,
    d1,
    q1);

parameter DataWidth = 32'd8;
parameter AddressRange = 32'd5760;
parameter AddressWidth = 32'd13;
input reset;
input clk;
input[AddressWidth - 1:0] address0;
input ce0;
input we0;
input[DataWidth - 1:0] d0;
output[DataWidth - 1:0] q0;
input[AddressWidth - 1:0] address1;
input ce1;
input we1;
input[DataWidth - 1:0] d1;
output[DataWidth - 1:0] q1;

reg[DataWidth - 1:0] line_buffer0[AddressRange-1:0];
reg[DataWidth - 1:0] line_buffer1[AddressRange-1:0];
reg[DataWidth - 1:0] line_buffer2[AddressRange-1:0];

reg[DataWidth - 1:0] pixel[2:0];
reg[DataWidth - 1:0] new_pixel;
reg[AddressWidth - 1:0] current_address0;
reg[AddressWidth - 1:0] current_address1;
reg[AddressWidth - 1:0] current_address2;

always@(posedge clk) begin
    if(reset) begin
        current_address0 <= 0;
        current_address1 <= 0;
        current_address2 <= 0;
    end else begin
        current_address0 <= current_address0 + 1;
        current_address1 <= current_address1 + 1;
        current_address2 <= current_address2 + 1;
        pixel[0] <= line_buffer0[current_address0+1];
        pixel[1] <= line_buffer0[current_address0];
        pixel[2] <= line_buffer0[current_address0-1];
        pixel[0] <= line_buffer1[current_address1+1];
        pixel[1] <= line_buffer1[current_address1];
        pixel[2] <= line_buffer1[current_address1-1];
        new_pixel <= (pixel[0] + pixel[1] + pixel[2] + line_buffer0[current_address0] + line_buffer1[current_address1] + line_buffer2[current_address2]) / 9;
        line_buffer2[current_address2] <= new_pixel;
    end
end

assign q0 = line_buffer0[address0];
assign q1 = line_buffer1[address1];

always@(posedge clk) begin
    if(we0) begin
        line_buffer0[address0] <= d0;
    end
    if(we1) begin
        line_buffer1[address1] <= d1;
    end
end

endmodule

module trigger_control(
    input clk,
    input sync,
    input reset,
    input roc_tout,
    input ctrl_write,
    input [15:0]ctrl_writedata,
    input [1:0]ctrl_address,
    input trigger_in,
    input evin,
    output roc_ctr,
    output roc_tin,
    output daq_write,
    output [15:0]daq_data
);

    // --- control signals begin --------
    wire sel_async;
    wire sel_sync;
    wire sel_single;
    wire sel_gen;
    wire sel_pg;

    wire sel_dir_async;
    wire sel_dir_sync;
    wire sel_dir_single;
    wire sel_dir_gen;
    wire sel_dir_pg;

    wire sel_chain;
    wire sel_sync_out;

    wire [4:0]send_trig;

    wire gen_sel_random;
    wire [31:0]gen_rate;

    wire [7:0]trg_delay;
    wire [15:0]token_timeout;
    wire enable_tout_delay;
    // --- control signals end ----------

    wire [19:0]dummy20;
    wire [26:0]dummy27;
    wire [30:0]dummy31;
    wire [23:0]dummy24;
    wire [15:0]dummy16;

    trigger_interface port(
        .clk(clk),
        .sync(sync),
        .reset(reset),

        .write(ctrl_write),
        .writedata(ctrl_writedata),
        .address(ctrl_address),

        .reg0({dummy20,
            sel_dir_async, sel_dir_sync, sel_dir_gen,
            sel_async, sel_sync, sel_single, sel_gen, sel_pg,
            sel_dir_single, sel_dir_pg, sel_chain, sel_sync_out}),
        .reg1({dummy27, send_trig}),
        .reg2({dummy31, gen_sel_random}),
        .reg3(gen_rate),
        .reg4({dummy24, trg_delay}),
        .reg5({dummy16, token_timeout}),
        .reg6({dummy31, enable_tout_delay})
    );


    // === sources ====================================================

    wire [4:0]trig_async_in;
    wire [3:0]trig_async_pos;

    trigger_in_async trg_in_async(
        .clk80(clk),
        .clk400(sclk),
        .sync(sync),
        .reset(reset),
        .trigger_in(trigger_in),
        .trigger_out(trig_async_in),
        .trigger_pos(trig_async_pos)
    );


    wire trig_del_sig;
    wire [4:0]trig_del_out;
    wire [4:0]trig_del = trig_del_out & {5{trig_del_sig}};
    wire [3:0]trig_del_pos;

    trigger_delay #(9) trg_del(
        .clk(clk),
        .sync(sync),
        .reset(reset),
        .delay(trg_delay),
        .trg_in(|trig_async_in),
        .data_in({trig_async_pos, trig_async_in}),
        .trg_out(trig_del_sig),
        .data_out({trig_del_pos, trig_del_out})
    );


    wire [4:0]trig_gen;

    trigger_generator trg_gen(
        .clk(clk),
        .sync(sync),
        .reset(reset),
        .sel_random(gen_sel_random),
        .rate(gen_rate),
        .trg(trig_gen)
    );


    wire [4:0]trig_sync_in;
    wire sync_bridge_in;

    trigger_in_sync trg_data_in(
        .clk(clk),
        .sync(sync),
        .reset(reset),
        .din(evin),
        .trigger_out(trig_sync_in),
        .direct_in(sync_bridge_in)
    );


    // === sinks ======================================================

    wire [4:0]trig_sync_out;
    wire sync_bridge_out;

    trigger_out_sync trg_data_out(
        .clk(clk),
        .sync(sync),
        .reset(reset),
        .trigger_in(trig_sync_out),
        .direct_out(sync_bridge_out),
        .dout(evout)
    );


    wire [4:0]trig_tbm;
    wire [3:0]trig_tbm_pos;
    wire [4:0]trig_ctr;
    wire deser_ena_tbm;
    wire roc_tin_tbm;

    assign deser_ena = deser_ena_tbm
        || !(sel_async || sel_sync || sel_single || sel_gen || sel_pg);

    soft_tbm tbm(
        .clk(clk),
        .sync(sync),
        .reset(reset),
        .trg_in_tbm(trig_tbm),
        .trg_in_ctr(trig_ctr),
        .trg_pos(trig_tbm_pos),
        .tin(roc_tin_tbm),
        .tout(roc_tout),
        .deser_ena(deser_ena_tbm),
        .ctr(roc_ctr),
        .daq_write(daq_write),
        .daq_data(daq_data),
        .token_timeout(token_timeout),
        .enable_tout_delay(enable_tout_delay)
    );

    assign roc_tin = roc_tin_tbm || (pg_tin && sel_dir_pg);


    // === switch =====================================================

    trigger_control switch(
        .clk(clk),
        .sync(sync),
        .reset(reset),

        // control
        .sel_async(sel_async),
        .sel_sync(sel_sync),
        .sel_single(sel_single),
        .sel_gen(sel_gen),
        .sel_pg(sel_pg),

        .sel_dir_async(sel_dir_async),
        .sel_dir_sync(sel_dir_sync),
        .sel_dir_single(sel_dir_single),
        .sel_dir_gen(sel_dir_gen),
        .sel_dir_pg(sel_dir_pg),

        .sel_chain(sel_chain),
        .sel_sync_out(sel_sync_out),

        // sources
        .src_async(trig_del),
        .src_async_pos(trig_del_pos),

        .src_sync(trig_sync_in),
        .src_sync_direct(sync_bridge_in),

        .src_single(send_trig),

        .src_gen(trig_gen),

        .src_pg({pg_cal, pg_rst, pg_rsr, pg_trg, 1'b0}),

        // sinks
        .dst_tbm(trig_tbm),
        .dst_tbm_pos(trig_tbm_pos),

        .dst_sync(trig_sync_out),
        .dst_sync_direct(sync_bridge_out),

        .dst_dir(trig_ctr)
    );


endmodule

