module top_module (
    input clk,
    input rst_n,
    input write_en,
    input [3:0] write_addr,
    input [7:0] write_data,
    input read_en,
    input [3:0] read_addr,
    output reg [7:0] read_data,
    input [7:0] mux_input_a,
    input [7:0] mux_input_b,
    input [7:0] mux_input_c,
    input [1:0] mux_ctrl,
    output reg [7:0] mux_output,
    output reg [7:0] bitwise_or_output
);

// True Dual-Port RAM
reg [7:0] ram [0:15];

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        read_data <= 8'b0;
    end else begin
        if (write_en) begin
            ram[write_addr] <= write_data;
        end
        if (read_en) begin
            read_data <= ram[read_addr];
        end
    end
end

// 3-to-4 Multiplexer
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        mux_output <= 8'b0;
    end else begin
        case (mux_ctrl)
            2'b00: mux_output <= mux_input_a;
            2'b01: mux_output <= mux_input_b;
            2'b10: mux_output <= mux_input_c;
            default: mux_output <= 8'b0;
        endcase
    end
end

// Bitwise OR operation
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        bitwise_or_output <= 8'b0;
    end else begin
        bitwise_or_output <= read_data | mux_output;
    end
end

endmodule

module retiming_block (
  input [n-1:0] in,
  output [n-1:0] out
);

parameter n = 4; // number of input and output signals
parameter delay = 2; // initial delay value

reg [n-1:0] delayed_in; // delayed input signals

// Delay element
always @(posedge clk) begin
  delayed_in <= {in[n-1-delay+1:n-1], in[0:n-1-delay]};
end

// Feedback loop
always @(posedge clk) begin
  out <= delayed_in;
end

endmodule

module simul_axi_fifo
#(
  parameter integer WIDTH=  64,         // total number of output bits
  parameter integer LATENCY=0,          // minimal delay between inout and output ( 0 - next cycle)
  parameter integer DEPTH=8,            // maximal number of commands in FIFO
  parameter integer FIFO_DEPTH=LATENCY+DEPTH+1
)(
  input              clk,
  input              reset,
  input  [WIDTH-1:0] data_in,
  input              load,
  output             input_ready,
  output [WIDTH-1:0] data_out,
  output             valid,
  input              ready);

  reg  [WIDTH-1:0]   fifo [0:FIFO_DEPTH-1]; // FIFO buffer
  integer            in_address;             // address of input data
  integer            out_address;            // address of output data
  integer            in_count;               // count of input data
  integer            out_count;              // count of output data
  reg    [LATENCY:0] latency_delay_r;        // register for latency delay

  wire [LATENCY+1:0] latency_delay={latency_delay_r,load}; // wire for latency delay             
  wire               out_inc=latency_delay[LATENCY];         // wire for output increment

  assign data_out=    fifo[out_address];     // assign output data
  assign valid=       out_count!=0;          // assign valid signal
  assign input_ready= in_count<DEPTH;        // assign input ready signal

  // always block for latency delay and address increment
  always @ (posedge clk or posedge reset) begin
    if (reset) latency_delay_r <= 0;
    else       latency_delay_r <= latency_delay[LATENCY:0];

    if    (reset)  in_address <= 0;
    else if (load) in_address <= (in_address==(FIFO_DEPTH-1))?0:in_address+1;

    if    (reset)            out_address <= 0;
    else if (valid && ready) out_address <= (out_address==(FIFO_DEPTH-1))?0:out_address+1;

    if    (reset)                       in_count <= 0;
    else if (!(valid && ready) && load) in_count <= in_count+1;
    else if (valid && ready && !load)   in_count <= in_count-1;

    if    (reset)                          out_count <= 0;
    else if (!(valid && ready) && out_inc) out_count <= out_count+1;
    else if (valid && ready && !out_inc)   out_count <= out_count-1;
  end

  // always block for storing input data in the FIFO buffer
  always @ (posedge clk) begin
    if (load) fifo[in_address] <= data_in;
  end

endmodule

module tx_DS_SE(
    input           TxClk,
    input           TxReset,
    input           Tx1,
    input           Tx0,
    output          D,
    output          S
);
    reg D, S;
    reg nextD;
    reg nextS;

    always @(posedge TxClk) begin
        if(TxReset) begin
            D <= 0;
            S <= 0;
        end
        else if(Tx0 | Tx1) begin
            D <= nextD;
            S <= nextS;
        end
    end

    assign nextD = Tx1;
    assign nextS = (Tx0 & ~(D^S)) | (Tx1 & (D^S));

endmodule

