module top_tb();

    // Inputs are registered
    reg UDP_IN;
    reg VGND;

    // Outputs are wires
    wire UDP_OUT;

    // Clock signal
    reg clk;

    // Instantiate the top module
    top dut (.UDP_IN(UDP_IN), .VGND(VGND), .UDP_OUT(UDP_OUT));

    // Generate clock signal
    always
    begin
        #5 clk = ~clk;
    end

    // Stimulus
    initial
    begin
        // Initial state is x for all inputs.
        UDP_IN = 1'bX;
        VGND   = 1'bX;
        clk    = 1'b0;

        // Wait for a few clock cycles
        #10;

        // Drive UDP_IN to 0
        UDP_IN = 1'b0;
        #20;

        // Drive VGND to 0
        VGND = 1'b0;
        #20;

        // Drive UDP_IN to 1
        UDP_IN = 1'b1;
        #20;

        // Drive VGND to 1
        VGND = 1'b1;
        #20;

        // Drive UDP_IN to 0
        UDP_IN = 1'b0;
        #20;

        // Drive VGND to 0
        VGND = 1'b0;
        #20;

        // Drive VGND to 1
        VGND = 1'b1;
        #20;

        // Drive UDP_IN to 1
        UDP_IN = 1'b1;
        #20;

        // Drive VGND to x
        VGND = 1'bx;
        #20;

        // End simulation
        $finish;
    end

    // Monitor UDP_OUT
    always @(posedge clk)
    begin
        $display("UDP_OUT = %b", UDP_OUT);
