module condff_with_counter (
  input clk,
  input reset,
  input [7:0] check_value,
  output reg [0:0] q1,
  output reg [2:0] q3,
  output reg [7:0] q8
);

  reg [0:0] d1;
  reg [2:0] d3;
  reg [7:0] d8;

  reg ena;
  integer cyc;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      cyc <= 1;
      d1 <= 1'b1;
      d3 <= 3'h1;
      d8 <= 8'h11;
      ena <= 1'b1;
      q1 <= 1'b0;
      q3 <= 3'b0;
      q8 <= 8'b0;
    end else begin
      if (cyc != 0) begin
        cyc <= cyc + 1;
        case (cyc)
          1: begin
            d1 <= 1'b1;
            d3 <= 3'h1;
            d8 <= 8'h11;
            ena <= 1'b1;
          end
          2: begin
            d1 <= 1'b0;
            d3 <= 3'h2;
            d8 <= 8'h33;
            ena <= 1'b0;
          end
          3: begin
            d1 <= 1'b1;
            d3 <= 3'h3;
            d8 <= 8'h44;
            ena <= 1'b1;
            if (q8 != check_value) $stop;
          end
          4: begin
            d1 <= 1'b1;
            d3 <= 3'h4;
            d8 <= 8'h77;
            ena <= 1'b1;
            if (q8 != check_value) $stop;
          end
          5: begin
            d1 <= 1'b1;
            d3 <= 3'h0;
            d8 <= 8'h88;
            ena <= 1'b1;
            if (q8 != 8'h44) $stop;
          end
          6: begin
            if (q8 != 8'h77) $stop;
          end
          7: begin
            if (q8 != 8'h88) $stop;
          end
          20: begin
            $write("*-* All Finished *-*\n");
            $finish;
          end
        endcase
      end
    end
  end

  condff #(12) condff_inst (
    .clk(clk),
    .sen(1'b0),
    .ena(ena),
    .d({d8, d3, d1}),
    .q({q8, q3, q1})
  );
endmodule

