module combinational_circuit (
    input [49:0] in,
    output out_and,
    output out_or,
    output out_xor
);

wire [24:0] and_out;
wire [24:0] or_out;
wire [48:0] xor_out;

genvar i;
generate
    for (i = 0; i < 25; i = i + 1) begin : and_gates
        and_gate and_inst (
            .a(in[2*i]),
            .b(in[2*i+1]),
            .y(and_out[i])
        );
    end

    for (i = 0; i < 25; i = i + 1) begin : or_gates
        or_gate or_inst (
            .a(in[2*i]),
            .b(in[2*i+1]),
            .y(or_out[i])
        );
    end

    for (i = 0; i < 49; i = i + 1) begin : xor_gates
        xor_gate xor_inst (
            .a(in[i]),
            .b(in[i+1]),
            .y(xor_out[i])
        );
    end
endgenerate

assign out_and = and_out[24];
assign out_or = or_out[24];
assign out_xor = xor_out[48];

endmodule


