    output nor_out,
    output [31:0] final_out
);

// Break down 32-bit input into four 8-bit chunks
wire [7:0] a0 = a[7:0];
wire [7:0] a1 = a[15:8];
wire [7:0] a2 = a[23:16];
wire [7:0] a3 = a[31:24];

