module FFT_IFFT (
  input [2*n-1:0] in,
  output [2*n-1:0] out
);

parameter n = 8;

// Define butterfly operation
function [1:0] butterfly;
  input [1:0] a, b;
  input [2:0] w;
  begin
    case (w)
      3'b000: butterfly = {a[0]+b[0], a[1]+b[1]};
      3'b001: butterfly = {a[0]+b[1], a[1]-b[0]};
      3'b010: butterfly = {a[0]-b[0], a[1]-b[1]};
      3'b011: butterfly = {a[0]-b[1], a[1]+b[0]};
      3'b100: butterfly = {a[0]+b[0], a[1]-b[1]};
      3'b101: butterfly = {a[0]-b[1], a[1]-b[0]};
      3'b110: butterfly = {a[0]-b[0], a[1]+b[1]};
      3'b111: butterfly = {a[0]+b[1], a[1]+b[0]};
    endcase
  end
endfunction

// Define twiddle factor calculation
function [1:0] twiddle;
  input [2:0] k, n;
  input [0:1] sign;
  begin
    twiddle = {cos(2*PI*k/n), sign*sin(2*PI*k/n)};
  end
endfunction

// Define FFT block
genvar i, j, k;
generate
  for (i = 0; i < $clog2(n); i = i + 1) begin
    for (j = 0; j < n/2; j = j + 1) begin
      assign {out[2*(i*n+j)], out[2*(i*n+j)+1]} = butterfly({in[2*(i*n+j)], in[2*(i*n+j)+1]}, {in[2*(i*n+j+n/2)], in[2*(i*n+j+n/2)+1]}, twiddle(j, n/2, {1'b0, 1'b0}));
    end
    for (k = 1; k < n/2; k = k*2) begin
      for (j = 0; j < k; j = j + 1) begin
        assign {out[2*(i*n+j+k)], out[2*(i*n+j+k)+1]} = butterfly({out[2*(i*n+j+k)], out[2*(i*n+j+k)+1]}, {out[2*(i*n+j+k+n/2)], out[2*(i*n+j+k+n/2)+1]}, twiddle(j, k*2, {1'b0, 1'b0}));
      end
    end
  end
endgenerate

// Define IFFT block
genvar i, j, k;
generate
  for (i = 0; i < $clog2(n); i = i + 1) begin
    for (j = 0; j < n/2; j = j + 1) begin
      assign {out[2*(i*n+j)], out[2*(i*n+j)+1]} = butterfly({in[2*(i*n+j)], in[2*(i*n+j)+1]}, {in[2*(i*n+j+n/2)], in[2*(i*n+j+n/2)+1]}, twiddle(j, n/2, {1'b0, 1'b1}));
    end
    for (k = 1; k < n/2; k = k*2) begin
      for (j = 0; j < k; j = j + 1) begin
        assign {out[2*(i*n+j+k)], out[2*(i*n+j+k)+1]} = butterfly({out[2*(i*n+j+k)], out[2*(i*n+j+k)+1]}, {out[2*(i*n+j+k+n/2)], out[2*(i*n+j+k+n/2)+1]}, twiddle(j, k*2, {1'b0, 1'b1}));
      end
    end
  end
endgenerate

