module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

    wire [3:0] fa_sum;
    wire [3:0] fa_carry;
    wire [2:0] mux_sel;
    wire [3:0] mux_in0;
    wire [3:0] mux_in1;

    fa fa0 (.a(A[0]), .b(B[0]), .c_in(Cin), .sum(fa_sum[0]), .c_out(fa_carry[0]));
    fa fa1 (.a(A[1]), .b(B[1]), .c_in(fa_carry[0]), .sum(fa_sum[1]), .c_out(fa_carry[1]));
    fa fa2 (.a(A[2]), .b(B[2]), .c_in(fa_carry[1]), .sum(fa_sum[2]), .c_out(fa_carry[2]));
    fa fa3 (.a(A[3]), .b(B[3]), .c_in(fa_carry[2]), .sum(fa_sum[3]), .c_out(Cout));

    assign mux_sel = {fa_carry[2], fa_carry[1], fa_carry[0]};
    assign mux_in0 = {fa_sum[3], fa_sum[2], fa_sum[1], fa_sum[0]};
    assign mux_in1 = {4'b0000, A};

    mux_2to1 mux0 (.sel(mux_sel[1]), .in0(mux_in0[1:0]), .in1(mux_in1[1:0]), .out(S[0]));
    mux_2to1 mux1 (.sel(mux_sel[2]), .in0(mux_in0[2:1]), .in1(mux_in1[2:1]), .out(S[1]));
    mux_2to1 mux2 (.sel(mux_sel[3]), .in0(mux_in0[3:2]), .in1(mux_in1[3:2]), .out(S[2]));
    mux_2to1 mux3 (.sel(mux_sel[0]), .in0(mux_in0[4:3]), .in1(mux_in1[4:3]), .out(S[3]));

endmodule

