reg [3:0] mux_out;

decoder dec(A, B, EN, decoder_out);
priority_mux mux(data_in[3:0], data_in[7:4], data_in[11:8], data_in[15:12], S, mux_out);
functional_module func(decoder_out, mux_out, out);

