// Decoder module
module decoder (
    input A,
    input B,
    input EN,
    output reg [3:0] Y
);
always @ (A, B, EN) begin
    if (EN) begin
        case ({A, B})
            2'b00: Y = 4'b1110;
            2'b01: Y = 4'b1101;
            2'b10: Y = 4'b1011;
            2'b11: Y = 4'b0111;
        endcase
    end else begin
        Y = 4'b1111;
    end
end

endmodule

// Priority Mux module
module priority_mux (
    input [3:0] A,
    input [3:0] B,
    input [3:0] C,
    input [3:0] D,
    input [1:0] S,
    output reg [3:0] out
);
always @ (A, B, C, D, S) begin
    case ({A[S[1]], B[S[1]], C[S[1]], D[S[1]]})
        4'b0001: out = A;
        4'b0010: out = B;
        4'b0100: out = C;
        4'b1000: out = D;
        default: begin
            case ({A[S[0]], B[S[0]], C[S[0]], D[S[0]]})
                4'b0001: out = A;
                4'b0010: out = B;
                4'b0100: out = C;
                4'b1000: out = D;
                default: out = 4'b0000;
            endcase
        end
    endcase
end

endmodule

// Functional module
module functional_module (
    input [3:0] decoder_out,
    input [3:0] mux_out,
    output reg out
);
always @ (decoder_out, mux_out) begin
    out = |(decoder_out | mux_out);
end

endmodule

module DataMem (
    input clk, rst, 
    input MemWrite, MemRead, 
    input rx, 
    input [31:0] addr, wdata, 
    input [7:0] switch, 
    output tx, 
    output reg [31:0] rdata, 
    output reg [7:0] led, 
    output reg [11:0] digi, 
    output irq
);
    parameter RAM_SIZE = 256;
    parameter RAM_BIT  = 8;  // 2^8 = 256
    reg [31:0] DATA[RAM_SIZE-1:0];
    reg [31:0] TH, TL;
    reg [2:0] TCON;
    reg [7:0] UART_RXD, UART_TXD;
    reg [1:0] UART_CON;
    reg enable; // UART enable
    wire rx_s, tx_s; // UART status
    wire [7:0] rx_d; // receive data
    integer i;

    assign irq = TCON[2];

    // read
    always @ (*) begin
        if(MemRead) begin
            case (addr)
                32'h4000_0000: rdata <= TH;
                32'h4000_0004: rdata <= TL;
                32'h4000_0008: rdata <= {29'b0, TCON};
                32'h4000_000c: rdata <= {24'b0, led};
                32'h4000_0010: rdata <= {24'b0, switch};
                32'h4000_0014: rdata <= {20'b0, digi};
                32'h4000_0018: rdata <= {24'b0, UART_TXD};
                32'h4000_001c: rdata <= {24'b0, UART_RXD};
                32'h4000_0020: rdata <= {28'b0, UART_CON, 2'b0};
                default: begin 
                    rdata <= ( (addr[RAM_BIT+1:2]<RAM_SIZE) && ~addr[30] ) ? 
                    DATA[ addr[RAM_BIT+1:2] ] : 32'b0;
                end
            endcase
        end else
            rdata <= 32'b0;
    end

    // write
    always @ (posedge clk or posedge rst) begin
        if (rst) begin                                 // posedge rst
            for(i=0;i<256;i=i+1) DATA[i]<=32'b0;
            TH <= 32'b0;
            TL <= 32'b0;
            TCON <= 3'b0; // all disable
            led <= 8'b0;
            digi <= 12'b0;
        end else begin
            if(TCON[0]) begin // TIM enable
                if(TL==32'hffff_ffff) begin
                    TL <= TH;
                    TCON[2] <= TCON[1] ? 1'b1 : 1'b0;
                end else begin
                    TL <= TL + 1'b1;
                end
            end
            if(MemWrite)
                case (addr)
                    32'h4000_0000: TH <= wdata;
                    32'h4000_0004: TL <= wdata;
                    32'h4000_0008: TCON <= wdata[2:0];
                    32'h4000_000C: led <= wdata[7:0];
                    32'h4000_0014: digi <= wdata[11:0];
                    default: if ( (addr[RAM_BIT+1:2]<RAM_SIZE) && ~addr[30] )
                        DATA[ addr[RAM_BIT+1:2] ] <= wdata;
                endcase
        end
    end

    // UART control
    UART_RX uartrx(
        .clk(clk), .rst(rst), 
        .RX(rx), 
        .DATA(rx_d),
        .STATUS(rx_s)
    );
    UART_TX uarttx(
        .clk(clk), .rst(rst), 
        .DATA(UART_TXD),
        .EN(enable), 
        .TX(tx), 
        .STATUS(), 
        .END(tx_s)
    );
    always @ (posedge clk or posedge rst) begin
        if(rst) begin
            UART_CON <= 2'b0;
            UART_TXD <= 8'b0;
            UART_RXD <= 8'b0;
            enable <= 1'b0;
        end else begin
            if(MemWrite)
                case (addr)
                    32'h4000_0018: begin
                            UART_TXD <= wdata[7:0];
                            enable <= 1'b1;
                        end
                    32'h4000_0020: UART_CON <= wdata[3:2];
                    default: ;
                endcase
            if(MemRead)
                case (addr)
                    32'h4000_0018: UART_CON[0] <= 1'b0;
                    32'h4000_001c: UART_CON[1] <= 1'b0;
                    default: ;
                endcase
            if(rx_s) begin
                UART_RXD <= rx_d;
                UART_CON[1] <= 1'b1;
            end
            if(tx_s) begin
                UART_CON[0] <= 1'b1;
                enable <= 1'b0;
            end
        end
    end
endmodule

module sqrt_calc (
  input [7:0] x,
  output [7:0] y
);

  reg [7:0] y_n; // current estimate of square root
  reg [7:0] y_n1; // next estimate of square root
  reg [7:0] x_int; // integer representation of input
  reg done; // flag to indicate when calculation is complete

  // convert binary input to integer
  assign x_int = $unsigned(x);

  // initialize y(0) to 128
  initial y_n = 128;

  always @(*) begin
    // calculate y(n+1) using Newton-Raphson method
    y_n1 = (y_n + x_int/y_n)/2;

    // check if y(n+1) and y(n) are within 1 of each other
    if (y_n1 >= y_n-1 && y_n1 <= y_n+1) begin
      done = 1; // calculation is complete
    end else begin
      y_n = y_n1; // update current estimate
      done = 0; // calculation is not yet complete
    end
  end

  // convert final estimate of square root back to binary and output it
  assign y = $unsigned(y_n1);

endmodule

module counter #(
    parameter bits = 16,
    parameter max_val = 65535
) (
    input clock, reset, enable, load,
    input [bits-1:0] init,
    output reg [bits-1:0] q
);
    always @(posedge clock, posedge reset)
        if (reset) 
            q <= 0;
        else if (enable) 
            if (load) q <= init;
            else if (q == max_val) q <= 0;
            else q <= q + 1;
endmodule

