module top_module (
    input [7:0] in0,
    input [7:0] in1,
    input [7:0] in2,
    input [7:0] in3,
    input [7:0] in4,
    input [7:0] in5,
    input [7:0] in6,
    input [7:0] in7,
    output reg EN,
    output reg V,
    output reg [2:0] Q
);

    // Sorting module
    wire [7:0] sorted_in;
    sorting_module sort(
        .in({in0, in1, in2, in3, in4, in5, in6, in7}),
        .out(sorted_in)
    );

    // Priority encoder module
    wire [2:0] encoded_index;
    priority_encoder_module priority_encoder(
        .in(sorted_in),
        .out(encoded_index)
    );

    // Output EN
    always @* begin
        if (in0 | in1 | in2 | in3 | in4 | in5 | in6 | in7) begin
            EN = 1;
        end else begin
            EN = 0;
        end
    end

    // Output V
    always @* begin
        if ((in0 & (in1 | in2 | in3 | in4 | in5 | in6 | in7)) |
            (in1 & (in2 | in3 | in4 | in5 | in6 | in7)) |
            (in2 & (in3 | in4 | in5 | in6 | in7)) |
            (in3 & (in4 | in5 | in6 | in7)) |
            (in4 & (in5 | in6 | in7)) |
            (in5 & (in6 | in7)) |
            (in6 & in7)) begin
            V = 1;
        end else begin
            V = 0;
        end
    end

    // Output Q
    assign Q = encoded_index;

endmodule

