module clkgen_mmcm(
    input wire CLK_P,
    input wire CLK_N,
    input wire RST_X_I,
    output wire CLK_O,
    output wire RST_X_O
);

    wire clk_ibuf;
    wire LOCKED;

    // Input buffer
    IBUFGDS ibuf (
        .I (CLK_P),
        .IB(CLK_N),
        .O (clk_ibuf)
    );

    // Clock management IP core (MMCM)
    CLKGEN_MMCM #(
        .CLKFBOUT_MULT_F (5.0),
        .CLKOUT0_DIVIDE_F(10.0),
        .CLKOUT0_PHASE  (0.0),
        .CLKOUT1_DIVIDE_F(20.0),
        .CLKOUT1_PHASE  (0.0),
        .CLKOUT2_DIVIDE_F(40.0),
        .CLKOUT2_PHASE  (0.0),
        .CLKOUT3_DIVIDE_F(80.0),
        .CLKOUT3_PHASE  (0.0)
    ) clkgen (
        .CLKFBIN    (clk_ibuf),
        .CLKFBOUT   (),
        .CLKIN1     (),
        .CLKIN2     (),
        .CLKOUT0    (CLK_O),
        .CLKOUT1    (),
        .CLKOUT2    (),
        .CLKOUT3    (),
        .LOCKED     (LOCKED),
        .PWRDWN     (),
        .RST        ()
    );

    // Synchronous reset generator
    RSTGEN rstgen (
        .CLK    (CLK_O),
        .RST_X_I(RST_X_I & LOCKED),
        .RST_X_O(RST_X_O)
    );

endmodule

module full_adder (
    input A,
    input B,
    input CIN,
    output SUM,
    output COUT
);

    // local signals
    wire xor1_out, xor2_out, and1_out, and2_out, and3_out, or1_out, or2_out;

    // XOR gates
    xor xor1 (xor1_out, A, B);
    xor xor2 (xor2_out, xor1_out, CIN);

    // AND gates
    and and1 (and1_out, A, B);
    and and2 (and2_out, B, CIN);
    and and3 (and3_out, A, CIN);

    // OR gates
    or or1 (or1_out, and1_out, and2_out);
    or or2 (or2_out, or1_out, and3_out);

    // assign outputs
    assign SUM = xor2_out;
    assign COUT = or2_out;

endmodule

