module system_ov7670_controller_1_0
   (clk,
    resend,
    config_finished,
    sioc,
    siod,
    reset,
    pwdn,
    xclk);
  (* x_interface_info = "xilinx.com:signal:clock:1.0 clk CLK" *) input clk;
  input resend;
  output config_finished;
  output sioc;
  inout siod;
  (* x_interface_info = "xilinx.com:signal:reset:1.0 reset RST" *) output reset;
  output pwdn;
  output xclk;

  wire const0;
  wire const1;
  wire clk_2x;
  wire sioc_pulse;
  wire [7:0] config_data;
  reg [7:0] config_data_reg;
  reg [2:0] config_state;
  reg [2:0] config_state_next;
  reg resend_reg;
  reg [7:0] config_crc;
  reg [7:0] config_crc_next;
  reg [1:0] crc_count;
  reg [1:0] crc_count_next;
  reg config_error;
  reg config_error_next;
  reg siod_direction;
  reg siod_direction_next;
  reg siod_data;
  reg siod_data_next;
  reg siod_data_reg;
  reg siod_data_reg_next;
  reg config_finished_reg;
  reg config_finished_reg_next;

  assign pwdn = const0;
  assign reset = const1;
  assign clk_2x = ~clk;
  assign sioc_pulse = (config_state == 3'h2) && (crc_count == 0);

  always @(posedge clk_2x) begin
    config_state <= config_state_next;
    config_data_reg <= config_data;
    config_crc <= config_crc_next;
    crc_count <= crc_count_next;
    config_error <= config_error_next;
    siod_direction <= siod_direction_next;
    siod_data_reg <= siod_data_reg_next;
    config_finished_reg <= config_finished_reg_next;
  end

  always @(posedge clk) begin
    resend_reg <= resend;
  end

  always @(posedge clk_2x) begin
    case (config_state)
      3'h0: begin
        config_state_next = 3'h1;
        config_data = 8'h42;
        crc_count_next = 2'h0;
        config_error_next = 1'b0;
        siod_direction_next = 1'b0;
        siod_data_reg_next = 1'b0;
        config_finished_reg_next = 1'b0;
      end
      3'h1: begin
        config_state_next = 3'h2;
        config_data = 8'h03;
        crc_count_next = 2'h0;
        config_error_next = 1'b0;
        siod_direction_next = 1'b0;
        siod_data_reg_next = 1'b0;
        config_finished_reg_next = 1'b0;
      end
      3'h2: begin
        if (sioc_pulse) begin
          if (siod_direction == 1'b0) begin
            siod_data_next = config_data_reg[7];
            siod_direction_next = 1'b1;
            crc_count_next = crc_count + 1;
            config_crc_next = config_crc + config_data_reg[7:0];
            config_data_next = {config_data_reg[6:0], 1'b0};
          end else begin
            if (siod_data == 1'b1) begin
              config_error_next = 1'b1;
            end
            siod_direction_next = 1'b0;
            if (crc_count == 2'h2) begin
              if (config_crc == config_crc_next) begin
                config_finished_reg_next = 1'b1;
              end else begin
                config_error_next = 1'b1;
              end
              config_state_next = 3'h0;
            end else begin
              crc_count_next = crc_count + 1;
              config_crc_next = config_crc + siod_data;
              config_data_next = {config_data_reg[6:0], resend_reg};
            end
          end
        end else begin
          siod_data_next = siod_data_reg;
        end
      end
    endcase
  end

  assign sioc = sioc_pulse;
  assign siod = siod_data;

  always @(posedge clk) begin
    if (reset == 1'b1) begin
      siod_data_reg_next = 1'b0;
      config_state_next = 3'h0;
      config_error_next = 1'b0;
      crc_count_next = 2'h0;
      config_crc_next = 8'h00;
      config_finished_reg_next = 1'b0;
    end else begin
      siod_data_reg_next = siod_data_next;
      config_error_next = config_error;
      crc_count_next = crc_count;
      config_crc_next = config_crc;
      config_finished_reg_next = config_finished_reg;
    end
  end

  always @(posedge clk_2x) begin
    xclk <= ~clk;
  end

  always @(posedge clk) begin
    if (reset == 1'b1) begin
      config_state <= 3'h0;
      config_error <= 1'b0;
      crc_count <= 2'h0;
      config_crc <= 8'h00;
      config_finished_reg <= 1'b0;
    end
    config_finished <= config_finished_reg;
  end

endmodule

