module binary_search
#(parameter
    N = 8,
    M = 4,
    P = 3
)(
    input wire clk,
    input wire reset,
    input wire ce,
    input wire [N-1:0] array,
    input wire [M-1:0] search_key,
    output wire [P-1:0] index
);

reg [P-1:0] low = 0;
reg [P-1:0] high = N-1;
reg [P-1:0] mid;
reg found = 0;

always @(posedge clk) begin
    if (reset) begin
        low <= 0;
        high <= N-1;
        mid <= 0;
        found <= 0;
    end else if (ce) begin
        if (array[high] < search_key || array[low] > search_key) begin
            // search key is not in the array
            index <= -1;
            found <= 1;
        end else if (array[low] == search_key) begin
            // search key is at the lower bound
            index <= low;
            found <= 1;
        end else if (array[high] == search_key) begin
            // search key is at the upper bound
            index <= high;
            found <= 1;
        end else begin
            // binary search
            mid <= (low + high) >> 1;
            if (array[mid] == search_key) begin
                index <= mid;
                found <= 1;
            end else if (array[mid] < search_key) begin
                low <= mid + 1;
            end else begin
                high <= mid - 1;
            end
        end
    end
end

endmodule

