module fifo_memory
#(
    parameter BASEADDR = 32'h0000,
    parameter HIGHADDR = 32'h0000,
    parameter ABUSWIDTH = 32,
    parameter BASEADDR_DATA = 32'h0000,
    parameter HIGHADDR_DATA = 32'h0000,
    parameter DEPTH = 32'h8000*8,
    parameter FIFO_ALMOST_FULL_THRESHOLD = 95,
    parameter FIFO_ALMOST_EMPTY_THRESHOLD = 5
) (
    input wire BUS_CLK,
    input wire BUS_RST,
    input wire [ABUSWIDTH-1:0] BUS_ADD,
    inout wire [31:0] BUS_DATA,
    input wire BUS_RD,
    input wire BUS_WR,
    output wire FIFO_READ_NEXT_OUT,
    input wire FIFO_EMPTY_IN,
    inout wire [31:0] FIFO_DATA,
    output wire FIFO_NOT_EMPTY,
    output wire FIFO_FULL,
    output wire FIFO_NEAR_FULL,
    output wire FIFO_READ_ERROR
);

reg [31:0] bram_fifo_mem [DEPTH/8-1:0];
reg [31:0] fifo_data_mem [DEPTH/8-1:0];

reg [ABUSWIDTH-1:0] read_ptr;
reg [ABUSWIDTH-1:0] write_ptr;
reg [ABUSWIDTH-1:0] read_ptr_data;
reg [ABUSWIDTH-1:0] write_ptr_data;

reg [31:0] read_data;
reg [31:0] write_data;

reg [31:0] fifo_data_in;
reg [31:0] fifo_data_out;

reg [31:0] almost_full_threshold;
reg [31:0] almost_empty_threshold;

reg fifo_empty;
reg fifo_not_empty;
reg fifo_full;
reg fifo_near_full;
reg fifo_read_error;

reg [31:0] fifo_depth;

reg [31:0] fifo_data_count;
reg [31:0] fifo_data_count_next;

reg [31:0] fifo_almost_full_threshold;
reg [31:0] fifo_almost_empty_threshold;

parameter READ = 1'b1;
parameter WRITE = 1'b0;

assign FIFO_READ_NEXT_OUT = (read_ptr != write_ptr) && !fifo_empty;
assign FIFO_NOT_EMPTY = !fifo_empty;
assign FIFO_FULL = fifo_full;
assign FIFO_NEAR_FULL = fifo_near_full;
assign FIFO_READ_ERROR = fifo_read_error;

always @(posedge BUS_CLK) begin
    if(BUS_RST) begin
        read_ptr <= 'd0;
        write_ptr <= 'd0;
        read_ptr_data <= 'd0;
        write_ptr_data <= 'd0;
        read_data <= 'd0;
        write_data <= 'd0;
        fifo_data_in <= 'd0;
        fifo_data_out <= 'd0;
        almost_full_threshold <= (DEPTH/8) * (FIFO_ALMOST_FULL_THRESHOLD/100);
        almost_empty_threshold <= (DEPTH/8) * (FIFO_ALMOST_EMPTY_THRESHOLD/100);
        fifo_empty <= 1'b1;
        fifo_not_empty <= 1'b0;
        fifo_full <= 1'b0;
        fifo_near_full <= 1'b0;
        fifo_read_error <= 1'b0;
        fifo_depth <= DEPTH/8;
        fifo_data_count <= 'd0;
        fifo_data_count_next <= 'd0;
        fifo_almost_full_threshold <= almost_full_threshold;
        fifo_almost_empty_threshold <= almost_empty_threshold;
    end else begin
        if(BUS_RD) begin
            if(FIFO_READ_NEXT_OUT) begin
                read_data <= bram_fifo_mem[read_ptr];
                read_ptr <= read_ptr + 1'b1;
                fifo_empty <= (read_ptr == write_ptr);
                fifo_full <= 1'b0;
                fifo_not_empty <= 1'b1;
                fifo_data_count <= fifo_data_count - 1'b1;
            end else begin
                fifo_read_error <= 1'b1;
            end
        end else if(BUS_WR) begin
            if(!fifo_full) begin
                write_data <= BUS_DATA;
                bram_fifo_mem[write_ptr] <= write_data;
                write_ptr <= write_ptr + 1'b1;
                fifo_empty <= 1'b0;
                fifo_not_empty <= 1'b1;
                fifo_data_count <= fifo_data_count + 1'b1;
                if(fifo_data_count_next >= fifo_almost_full_threshold) begin
                    fifo_near_full <= 1'b1;
                end else begin
                    fifo_near_full <= 1'b0;
                end
                if(fifo_data_count_next == fifo_depth) begin
                    fifo_full <= 1'b1;
                end else begin
                    fifo_full <= 1'b0;
                end
            end else begin
                fifo_read_error <= 1'b1;
            end
        end
    end
end

always @(posedge BUS_CLK) begin
    if(BUS_RST) begin
        read_ptr_data <= 'd0;
        write_ptr_data <= 'd0;
    end else begin
        if(BUS_RD) begin
            if(!FIFO_EMPTY_IN) begin
                fifo_data_out <= fifo_data_mem[read_ptr_data];
                read_ptr_data <= read_ptr_data + 1'b1;
            end else begin
                fifo_read_error <= 1'b1;
            end
        end else if(BUS_WR) begin
            fifo_data_in <= BUS_DATA;
            fifo_data_mem[write_ptr_data] <= fifo_data_in;
            write_ptr_data <= write_ptr_data + 1'b1;
        end
    end
end

always @(posedge BUS_CLK) begin
    fifo_data_count_next <= fifo_data_count;
end

endmodule

module RegisterAdd #(
  parameter WIDTH = 28
) (
  input [2:0] D,
  input [WIDTH-1:0] Q_reg,
  input CLK,
  input AR,
  output [WIDTH-3:0] Q
);

  wire [WIDTH-1:0] sum;
  wire [WIDTH-1:0] Q_reg_next;

  // Add D to Q_reg
  assign sum = Q_reg + {1'b0, D};

  // Update Q_reg on rising edge of CLK
  always @(posedge CLK) begin
    if (AR) begin
      Q_reg_next <= {WIDTH{1'b0}};
    end else begin
      Q_reg_next <= sum;
    end
  end

  // Output updated register value
  assign Q = Q_reg_next[WIDTH-4:0];

endmodule

