    splitter splitter_inst(
        .in(in),
        .out_hi(out_hi),
        .out_lo(out_lo)
    );

    // Instantiate accumulator module
    accumulator accumulator_inst(
        .clk(clk),
        .rst_n(rst_n),
        .in_lo(out_lo),
        .in_hi(out_hi),
        .valid(valid_a),
        .ready(ready_b),
        .valid_out(valid_b),
        .data_out(data_out)
    );

    // Implement valid-ready handshake
    assign ready_a = ~valid_b;
    assign accumulator_inst.ready = ready_a;

endmodule

module splitter(
    input [15:0] in,
    output [7:0] out_hi,
    output [7:0] out_lo
);

    // Implement ripple carry adder for lower byte
    assign out_lo = in[7:0] + in[15:8];

    // Implement carry select adder for upper byte
    wire [7:0] a = in[7:0];
    wire [7:0] b = in[15:8];
    wire [7:0] cin = 1'b0;
    wire [7:0] sum;
    wire [7:0] cout;
    carry_select_adder adder_inst(
        .a(a),
        .b(b),
        .cin(cin),
        .sum(sum),
        .cout(cout)
    );
    assign out_hi = sum;

endmodule

module carry_select_adder(
    input [7:0] a,
    input [7:0] b,
    input [7:0] cin,
    output [7:0] sum,
    output [7:0] cout
);

    // Implement carry select adder
    wire [7:0] a_xor_b = a ^ b;
    wire [7:0] a_and_b = a & b;
    wire [7:0] a_and_cin = a & cin;
    wire [7:0] b_and_cin = b & cin;
    wire [7:0] a_xor_b_xor_cin = a_xor_b ^ cin;
    wire [7:0] carry_mux_0 = a_and_b | a_and_cin | b_and_cin;
    wire [7:0] carry_mux_1 = a_and_b | a_and_cin | b_and_cin | a_xor_b_xor_cin;
    mux_8to1 mux_inst_0(
        .in({a[0], b[0], carry_mux_0[0], carry_mux_1[0]}),
        .sel({a[1], b[1], cin[1]}),
        .out(carry_0)
    );
    mux_8to1 mux_inst_1(
        .in({a[2], b[2], carry_mux_0[2], carry_mux_1[2]}),
        .sel({a[3], b[3], cin[3]}),
        .out(carry_1)
    );
    mux_8to1 mux_inst_2(
        .in({a[4], b[4], carry_mux_0[4], carry_mux_1[4]}),
        .sel({a[5], b[5], cin[5]}),
        .out(carry_2)
    );
    mux_8to1 mux_inst_3(
        .in({a[6], b[6], carry_mux_0[6], carry_mux_1[6]}),
        .sel({a[7], b[7], cin[7]}),
        .out(carry_3)
    );
    assign sum = a_xor_b_xor_cin;
    assign cout = {carry_3, carry_2, carry_1, carry_0};

endmodule

module mux_8to1(
    input [3:0] sel,
    input [7:0] in,
    output reg out
);

    // Implement 8-to-1 MUX
    always @*
        case (sel)
            4'b0000: out = in[0];
            4'b0001: out = in[1];
            4'b0010: out = in[2];
            4'b0011: out = in[3];
            4'b0100: out = in[4];
            4'b0101: out = in[5];
            4'b0110: out = in[6];
            4'b0111: out = in[7];
            default: out = 1'bx;
        endcase

endmodule

module accumulator(
    input clk,
    input rst_n,
    input [7:0] in_lo,
    input [7:0] in_hi,
    input valid,
    input ready,
    output reg valid_out,
    output reg [9:0] data_out
);

    // Implement pipeline architecture with combinational adder and register
    reg [9:0] sum;
    always @(posedge clk or negedge rst_n)
        if (~rst_n)
            sum <= 10'd0;
        else if (ready && valid)
            sum <= sum + {in_hi, in_lo};
    always @(posedge clk or negedge rst_n)
        if (~rst_n)
            valid_out <= 1'b0;
        else if (ready && valid && (sum[3:0] == 6'd6))
            valid_out <= 1'b1;
    always @(posedge clk or negedge rst_n)
        if (~rst_n)
            data_out <= 10'd0;
        else if (ready && valid && (sum[3:0] == 6'd6)) begin
            data_out <= sum;
            sum <= 10'd0;
        end

endmodule

