module axis_eth_fcs_insert_64 (
    input clk,
    input rst,
    input [63:0] s_axis_tdata,
    input [7:0] s_axis_tkeep,
    input s_axis_tvalid,
    output s_axis_tready,
    input s_axis_tlast,
    input s_axis_tuser,
    output reg [63:0] m_axis_tdata,
    output reg [7:0] m_axis_tkeep,
    output reg m_axis_tvalid,
    output reg m_axis_tlast,
    output reg m_axis_tuser,
    output reg busy
);

parameter ETH_CRC_WIDTH = 32;
parameter MIN_FRAME_LENGTH = 64;
parameter MAX_FRAME_LENGTH = 1518;

// Internal parameters
localparam ETH_FCS_WIDTH = ETH_CRC_WIDTH;
localparam BYTES_PER_WORD = 8;
localparam WORDS_PER_FRAME = (MAX_FRAME_LENGTH/BYTES_PER_WORD)+1;
localparam WORDS_PER_BURST = 8;
localparam BURSTS_PER_FRAME = WORDS_PER_FRAME/WORDS_PER_BURST;
localparam PADDING_BYTES = MIN_FRAME_LENGTH - (ETH_FCS_WIDTH/BYTES_PER_WORD);

// Internal signals
reg [63:0] data_reg [0:WORDS_PER_FRAME-1];
reg [7:0] keep_reg [0:WORDS_PER_FRAME-1];
reg valid_reg [0:WORDS_PER_FRAME-1];
reg last_reg [0:BURSTS_PER_FRAME-1];
reg user_reg [0:WORDS_PER_FRAME-1];
reg [31:0] fcs_reg;
reg [31:0] crc_reg;
reg [31:0] length_reg;
reg [31:0] padding_reg;
reg [31:0] padding_count_reg;
reg [2:0] state_reg;

// Internal state definitions
localparam IDLE = 3'b000;
localparam READ_FRAME = 3'b001;
localparam INSERT_FCS = 3'b010;
localparam INSERT_PADDING = 3'b011;
localparam WRITE_FRAME = 3'b100;

// State machine
always @(posedge clk) begin
    if (rst) begin
        state_reg <= IDLE;
        fcs_reg <= 32'h00000000;
        crc_reg <= 32'hFFFFFFFF;
        length_reg <= 32'h00000000;
        padding_reg <= 32'h00000000;
        padding_count_reg <= 32'h00000000;
        busy <= 0;
    end else begin
        case (state_reg)
            IDLE: begin
                if (s_axis_tvalid) begin
                    state_reg <= READ_FRAME;
                    busy <= 1;
                end else begin
                    state_reg <= IDLE;
                    busy <= 0;
                end
            end
            READ_FRAME: begin
                data_reg[0] <= s_axis_tdata;
                keep_reg[0] <= s_axis_tkeep;
                valid_reg[0] <= 1;
                user_reg[0] <= s_axis_tuser;
                if (s_axis_tlast) begin
                    state_reg <= INSERT_FCS;
                    length_reg <= ((s_axis_tkeep + 1) << 2);
                end else begin
                    state_reg <= READ_FRAME;
                end
            end
            INSERT_FCS: begin
                data_reg[WORDS_PER_FRAME-1] <= fcs_reg;
                keep_reg[WORDS_PER_FRAME-1] <= {ETH_FCS_WIDTH/BYTES_PER_WORD{1'b1}};
                valid_reg[WORDS_PER_FRAME-1] <= 1;
                user_reg[WORDS_PER_FRAME-1] <= 0;
                crc_reg <= ~crc_reg;
                state_reg <= INSERT_PADDING;
            end
            INSERT_PADDING: begin
                if (length_reg < MIN_FRAME_LENGTH) begin
                    padding_count_reg <= padding_count_reg + 1;
                    if (padding_count_reg == PADDING_BYTES) begin
                        padding_reg <= {32{1'b0}};
                        padding_count_reg <= 0;
                        state_reg <= WRITE_FRAME;
                    end else begin
                        padding_reg <= {32{1'b0}};
                        state_reg <= INSERT_PADDING;
                    end
                end else begin
                    state_reg <= WRITE_FRAME;
                end
            end
            WRITE_FRAME: begin
                for (i = 0; i < WORDS_PER_FRAME; i = i + WORDS_PER_BURST) begin
                    m_axis_tdata <= {data_reg[i+7],data_reg[i+6],data_reg[i+5],data_reg[i+4],
                                     data_reg[i+3],data_reg[i+2],data_reg[i+1],data_reg[i]};
                    m_axis_tkeep <= {keep_reg[i+7],keep_reg[i+6],keep_reg[i+5],keep_reg[i+4],
                                     keep_reg[i+3],keep_reg[i+2],keep_reg[i+1],keep_reg[i]};
                    m_axis_tvalid <= valid_reg[i];
                    m_axis_tlast <= (i == WORDS_PER_FRAME - WORDS_PER_BURST);
                    m_axis_tuser <= user_reg[i];
                    if (m_axis_tready) begin
                        for (j = 0; j < WORDS_PER_BURST; j = j + 1) begin
                            valid_reg[i+j] <= 0;
                        end
                    end
                end
                busy <= 0;
                state_reg <= IDLE;
            end
        endcase
    end
end

// CRC32 module
crc32 crc32_inst (
    .clk(clk),
    .rst(rst),
    .data_in({data_reg[length_reg+7],data_reg[length_reg+6],data_reg[length_reg+5],data_reg[length_reg+4],
              data_reg[length_reg+3],data_reg[length_reg+2],data_reg[length_reg+1],data_reg[length_reg]}),
    .crc_in(crc_reg),
    .crc_out(fcs_reg)
);

// Padding module
assign padding_reg[31:24] = 8'h00;
assign padding_reg[23:0] = padding_count_reg[7:0] << 3;

// Output signals
assign s_axis_tready = ~busy;
assign m_axis_tdata[63:0] = 64'h0000000000000000;
assign m_axis_tkeep[7:0] = 8'h00;
assign m_axis_tvalid = 0;
assign m_axis_tlast = 0;
assign m_axis_tuser = 0;

// End of module
endmodule

