module top_module (
    input wire [3:0] in_vec,
    input wire select,
    input wire [1:0] in_mux,
    output wire [3:0] out_vec
);

    wire [1:0] enc_out;
    wire [1:0] mux_out;
    wire [3:0] mux_in;

    // Instantiate the 2-to-1 multiplexer module
    mux_2to1 mux_2to1_inst (
        .in0(in_vec[0]),
        .in1(in_vec[1]),
        .sel(in_mux[0]),
        .out(mux_out[0])
    );

    // Instantiate the 4-to-2 encoder module
    encoder_4to2 encoder_4to2_inst (
        .in(in_vec),
        .out(enc_out)
    );

    // Functional module to select one of the four input vectors
    assign mux_in[0] = enc_out[0] ? in_vec[0] : in_vec[2];
    assign mux_in[1] = enc_out[0] ? in_vec[1] : in_vec[3];
    assign mux_in[2] = enc_out[1] ? in_vec[2] : in_vec[0];
    assign mux_in[3] = enc_out[1] ? in_vec[3] : in_vec[1];

    // Instantiate the 4-to-1 multiplexer module
    mux_4to1 mux_4to1_inst (
        .in(mux_in),
        .sel(mux_out[1]),
        .out(out_vec)
    );

    // Control module to select either the 2-to-1 multiplexer or the 4-to-2 encoder
    always @(*) begin
        if (select)
            out_vec <= {2'b00, mux_out};
        else
            out_vec <= {2'b00, enc_out};
    end

endmodule

