module traffic_light_controller (
  input clk,
  input rst,
  output reg red,
  output reg yellow,
  output reg green
);

  // Define the states
  parameter STATE_1 = 2'b00;
  parameter STATE_2 = 2'b01;
  parameter STATE_3 = 2'b10;
  parameter STATE_4 = 2'b11;

  // Define the state register and initialize to STATE_1
  reg [1:0] state_reg = STATE_1;

  // Define the state transition logic
  always @(posedge clk, posedge rst) begin
    if (rst) begin
      state_reg <= STATE_1;
    end else begin
      case (state_reg)
        STATE_1: state_reg <= STATE_2;
        STATE_2: state_reg <= STATE_3;
        STATE_3: state_reg <= STATE_4;
        STATE_4: state_reg <= STATE_1;
      endcase
    end
  end

  // Define the output logic based on the current state
  always @(*) begin
    case (state_reg)
      STATE_1: begin
        red <= 0;
        yellow <= 0;
        green <= 1;
      end
      STATE_2: begin
        red <= 0;
        yellow <= 1;
        green <= 0;
      end
      STATE_3: begin
        red <= 1;
        yellow <= 0;
        green <= 0;
      end
      STATE_4: begin
        red <= 1;
        yellow <= 1;
        green <= 0;
      end
    endcase
  end

endmodule

module log_exp (
  input [31:0] data_in,
  input [2:0] op_sel,
  output [31:0] data_out
);

  reg [31:0] result;

  // Logarithmic function with base e
  always @(*) begin
    if (op_sel[2] == 0 && op_sel[1:0] == 2'b00) begin
      result = $ln(data_in);
    end
  end

  // Logarithmic function with base 2
  always @(*) begin
    if (op_sel[2] == 0 && op_sel[1:0] == 2'b01) begin
      result = $log2(data_in);
    end
  end

  // Logarithmic function with base 10
  always @(*) begin
    if (op_sel[2] == 0 && op_sel[1:0] == 2'b10) begin
      result = $log10(data_in);
    end
  end

  // Exponential function with base e
  always @(*) begin
    if (op_sel[2] == 1 && op_sel[1:0] == 2'b00) begin
      result = $exp(data_in);
    end
  end

  // Exponential function with base 2
  always @(*) begin
    if (op_sel[2] == 1 && op_sel[1:0] == 2'b01) begin
      result = 2 ** data_in;
    end
  end

  // Exponential function with base 10
  always @(*) begin
    if (op_sel[2] == 1 && op_sel[1:0] == 2'b10) begin
      result = 10 ** data_in;
    end
  end

  assign data_out = result;

endmodule

module priority_encoder (
    input [3:0] in,
    output reg [1:0] pos,
    output reg zero_flag
);

reg [3:0] in_reg;
reg [1:0] pos_reg;

always @(posedge clk) begin
    in_reg <= in;
    pos_reg <= pos_reg;
end

always @(posedge clk) begin
    if (in_reg == 0) begin
        pos_reg <= 2'b00;
        zero_flag <= 1'b1;
    end else begin
        zero_flag <= 1'b0;
        case (in_reg)
            4'b1000: pos_reg <= 2'b11;
            4'b0100: pos_reg <= 2'b10;
            4'b0010: pos_reg <= 2'b01;
            4'b0001: pos_reg <= 2'b00;
            default: pos_reg <= pos_reg;
        endcase
    end
end

assign pos = pos_reg;

endmodule

