module rotator(
    input [31:0] a,
    input [1:0] ena,
    input clk,
    output reg [31:0] q
);

    always @(posedge clk) begin
        if (ena == 2'b00) begin
            q <= a;
        end else if (ena == 2'b01) begin
            q <= {a[30:0], a[31]};
        end else if (ena == 2'b10) begin
            q <= {a[1:31], a[0]};
        end else begin
            q <= a;
        end
    end

endmodule

module and_gate(
