module rising_edge_detector (
    input clk,
    input reset, // Synchronous active-high reset
    input [15:0] in, // 16-bit input vector
    output reg flag // Flag to indicate rising edge detection
);

reg [15:0] prev_in; // Previous value of input vector

always @(posedge clk) begin
    if (reset) begin
        prev_in <= 16'b0;
        flag <= 1'b0;
    end else begin
        // Shift in the current input value
        prev_in <= {prev_in[14:0], in[0]};

        // Compare current input with previous value to detect rising edge
        if (in[0] && !prev_in[0]) begin
            flag <= 1'b1;
        end else begin
            flag <= 1'b0;
        end
    end
end

endmodule

