module top_module (
    input clk,
    input reset, // Synchronous active-high reset
    input [15:0] in, // 16-bit input vector
    input select, // Select input to choose between modules
    output reg [6:0] seg // 7-segment display output
);

reg [3:0] count; // Counter for rising edge detection
wire flag; // Flag for rising edge detection
wire [15:0] and_out; // Output of bitwise AND operation

rising_edge_detector detector (
    .clk(clk),
    .reset(reset),
    .in(in),
    .flag(flag)
);

and_module and (
    .in(in),
    .out(and_out)
);

always @(posedge clk) begin
    if (reset) begin
        count <= 4'b0;
        seg <= 7'b0000000;
    end else begin
        if (select) begin
            // Rising edge detection module is active
            if (flag) begin
                count <= count + 1;
            end
            seg <= count;
        end else begin
            // Bitwise AND module is active
            seg <= and_out;
        end
    end
end

endmodule

