module spi_master
  #(parameter DATA_WIDTH=16,
    NUM_PORTS=1,
    CLK_DIVIDER_WIDTH=8
    )
  (input clk,
   input resetb,
   input CPOL, 
   input CPHA,
   input half_cycle_n,
   input [CLK_DIVIDER_WIDTH-1:0] clk_divider,

   input go,
   input [(NUM_PORTS*DATA_WIDTH)-1:0] datai,
   output [(NUM_PORTS*DATA_WIDTH)-1:0] datao,
   output reg busy,
   output reg done,

   input [NUM_PORTS-1:0] dout,
   output [NUM_PORTS-1:0] din,
   output reg csb,
   output reg sclk
   );

   // Internal registers and wires
   reg [NUM_PORTS-1:0] dout_s;
   reg  [CLK_DIVIDER_WIDTH-1:0]  clk_count;
   wire [CLK_DIVIDER_WIDTH-1:0]  next_clk_count = clk_count + 1;
   wire pulse = next_clk_count == (clk_divider >> 1);
   reg    state;
   reg [LOG2_DATA_WIDTH:0] shift_count;
   wire start = shift_count == 0;
   wire [31:0] stop_detect = ((half_cycle_n)+1)*DATA_WIDTH-1;
   wire stop  = shift_count >= stop_detect;
   localparam IDLE_STATE = 0, RUN_STATE = 1;

   // Instantiate shift register output module
   sro #(.DATA_WIDTH(DATA_WIDTH)) sro[NUM_PORTS-1:0]
     (.clk(clk),
      .resetb(resetb),
      .shift(pulse && !csb && (shift_count[0] == 0)),
      .dout(dout),
      .datao(datao));

   // Instantiate shift register input module
   sri #(.DATA_WIDTH(DATA_WIDTH)) sri[NUM_PORTS-1:0]
     (.clk(clk),
      .resetb(resetb),
      .datai(half_cycle_n ? datai : {datai[DATA_WIDTH/2-1:0], {DATA_WIDTH/2{1'b0}}}),
      .sample(go && (state == IDLE_STATE)),
      .shift(pulse && !csb && (shift_count[0] == 1)),
      .din(din));

   // Clock and reset logic
   always @(posedge clk or negedge resetb) begin
      if(!resetb) begin
         clk_count <= 0;
         shift_count <= 0;
         sclk  <= 1;
         csb   <= 1;
         state <= IDLE_STATE;
         busy  <= 0;
         done  <= 0;
      end else begin
         // generate the pulse train
         if(pulse) begin
            clk_count <= 0;
         end else begin
            clk_count <= next_clk_count;
         end

         // generate csb
         if(state == IDLE_STATE) begin
            csb  <= 1;
            shift_count <= 0;
            done <= 0;
            if(go && !busy) begin
               state  <= RUN_STATE;
               busy   <= 1;
            end else begin
               busy   <= 0;
            end
         end else begin
            if(pulse) begin
               if(stop) begin
                  csb <= 1;
                  state <= IDLE_STATE;
                  done  <= 1;
               end else begin
                  csb <= 0;
                  if(!csb) begin 
                     shift_count <= shift_count + 1;
                  end
               end
            end
         end

         // generate sclk
         if(pulse) begin
            if((CPHA==1 && state==RUN_STATE && !stop) || 
               (CPHA==0 && !csb)) begin
               sclk <= !sclk;
            end else begin
               sclk <= CPOL;
            end
         end
      end
   end
endmodule

module state_machine (
  input clk,
  input reset,
  input A,
  input B,
  output reg C
);

  parameter S0 = 3'b000;
  parameter S1 = 3'b001;
  parameter S2 = 3'b010;
  parameter S3 = 3'b011;
  parameter S4 = 3'b100;
  parameter S5 = 3'b101;
  parameter S6 = 3'b110;
  parameter S7 = 3'b111;

  reg [2:0] state;

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      state <= S0;
      C <= 0;
    end else begin
      case (state)
        S0: begin
          if (A == 0 && B == 0) begin
            state <= S1;
          end
        end
        S1: begin
          if (A == 0 && B == 1) begin
            state <= S2;
          end
        end
        S2: begin
          if (A == 1 && B == 0) begin
            state <= S3;
          end
        end
        S3: begin
          if (A == 1 && B == 1) begin
            state <= S0;
          end
        end
      endcase

      if (state == S1 || state == S2) begin
        C <= 1;
      end else begin
        C <= 0;
      end
    end
  end

endmodule

