module counter(
    input clk,
    input rst,
    input [64:1] dectext,
    input [1:0] updown,
    output reg [6:0] OUT,
    output reg [3:0] EN,
    input select
);

// Declare internal wires and registers
wire [3:0] out0, out1, out2, out3;
wire [6:0] bcd0, bcd1, bcd2, bcd3;
wire [1:0] sel_MUX;
reg [15:0] count;

// Determine the current count based on the updown input
always @(posedge clk, posedge rst) begin
    if (rst) begin
        count <= 0;
    end else begin
        if (updown == 2'b00) begin
            count <= count - 1;
        end else begin
            count <= count + 1;
        end
    end
end

// Split the count into four digits using mod and div operations
assign out0 = count % 10;
assign out1 = (count / 10) % 10;
assign out2 = (count / 100) % 10;
assign out3 = (count / 1000) % 10;

// Convert each digit to 7-segment display format using a BCD7segment module
BCD7segment BCD0(out0, select, bcd0);
BCD7segment BCD1(out1, select, bcd1);
BCD7segment BCD2(out2, select, bcd2);
BCD7segment BCD3(out3, select, bcd3);

// Use a modulo N counter to select which digit of the 7-segment display to enable
moduloNcounter cont(
    .clk(clk),
    .rst(rst),
    .Q(sel_MUX),
    .EN(1),
    .N(4)
);

// Use a binary decoder to enable the appropriate digit of the 7-segment display
always @* begin
    case (sel_MUX)
        0: EN = 4'b0111;
        1: EN = 4'b1011;
        2: EN = 4'b1101;
        3: EN = 4'b1110;
    endcase
end

// Use a MUX to select which digit of the 7-segment display to output
always @* begin
    case (sel_MUX)
        0: OUT = bcd3;
        1: OUT = bcd2;
        2: OUT = bcd1;
        3: OUT = bcd0;
    endcase
end

endmodule

module top_module (
    input clk,
    input reset,
    input [3:0] in,
    input [1:0] select,
    output reg [3:0] out
);

    wire [1:0] priority;
    wire [3:0] shifted_in;

    priority_encoder pe (
        .in(in),
        .out(priority)
    );

    barrel_shifter bs (
        .D(in),
        .S(select),
        .Q(shifted_in)
    );

    always @(posedge clk) begin
        if (reset) begin
            out <= 4'b0000;
        end else begin
            case (priority)
                2'b00: out <= shifted_in;
                2'b01: out <= shifted_in << 1;
                2'b10: out <= shifted_in >> 1;
                2'b11: out <= 4'b0000;
            endcase
        end
    end

endmodule

module priority_encoder (
    input [3:0] in,
    output reg [1:0] out
);

    always @* begin
        casez (in)
            4'b0001: out = 2'b00;
            4'b0010: out = 2'b01;
            4'b0100: out = 2'b10;
            4'b1000: out = 2'b11;
            default: out = 2'b00;
        endcase
    end

endmodule

module barrel_shifter (
    input [3:0] D,
    input [1:0] S,
    output reg [3:0] Q
);

    always @* begin
        case (S)
            2'b00: Q = D;
            2'b01: Q = D << 1;
            2'b10: Q = D >> 1;
            2'b11: Q = 4'b0000;
        endcase
    end

endmodule

module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    output reg [3:0] sum,
    output carry_out
);

    reg [3:0] carry;

    always @(*) begin
        sum = A + B + carry;
        carry_out = (sum[4] == 1) ? 1'b1 : 1'b0;
    end

    always @(posedge carry_out) begin
        carry <= carry_out;
    end

endmodule

module ten_second_clock (
  input reset,
  input enable,
  output reg clk_out
);

  reg [31:0] counter;

  always @(posedge clk_out) begin
    if (reset) begin
      counter <= 0;
      clk_out <= 0;
    end
    else if (enable) begin
      counter <= counter + 1;
      if (counter == 100000000) begin
        counter <= 0;
        clk_out <= ~clk_out;
      end
    end
    else begin
      counter <= 0;
      clk_out <= 0;
    end
  end

endmodule

module uart_transmitter(
  input clk, reset, din, baud_clk,
  output tx
);

reg [7:0] shift_reg;
reg tx_busy;
reg tx;

always @(posedge clk or posedge reset) begin
  if (reset) begin
    shift_reg <= 8'b0;
    tx_busy <= 1'b0;
    tx <= 1'b1;
  end else begin
    if (baud_clk) begin
      if (!tx_busy) begin
        shift_reg <= din;
        tx_busy <= 1'b1;
      end else begin
        shift_reg <= {shift_reg[6:0], 1'b0};
        if (shift_reg == 8'b0) begin
          tx_busy <= 1'b0;
        end
      end
      tx <= shift_reg[7];
    end
  end
end

endmodule

module uart_receiver(
  input clk, reset, rx, baud_clk,
  output dout
);

reg [7:0] shift_reg;
reg rx_busy;
wire dout;

assign dout = shift_reg[7];

always @(posedge clk or posedge reset) begin
  if (reset) begin
    shift_reg <= 8'b0;
    rx_busy <= 1'b0;
  end else begin
    if (baud_clk) begin
      if (!rx_busy) begin
        if (rx == 1'b0) begin
          rx_busy <= 1'b1;
        end
      end else begin
        shift_reg <= {shift_reg[6:0], rx};
        if (shift_reg == 8'b0) begin
          rx_busy <= 1'b0;
        end
      end
    end
  end
end

endmodule

module count_rising_edges (
