module top_module (
    input clk,
    input reset,
    output [7:0] out
);

    reg [3:0] counter;
    wire [15:0] mux_out;

    // 4-bit binary counter with asynchronous reset
    always @(posedge clk or negedge reset) begin
        if (reset == 0) begin
            counter <= 4'b0000;
        end else begin
            counter <= counter + 1;
        end
    end

    // 64-to-1 multiplexer
    mux64to1 mux (
        .sel(counter),
        .in({
            // 64 16-bit inputs
            16'h0000, 16'h0001, 16'h0002, 16'h0003,
            // ...
            16'h003C, 16'h003D, 16'h003E, 16'h003F
        }),
        .out(mux_out)
    );

    // Functional module
    always @(*) begin
        if (counter < 4'd32) begin
            out = mux_out[15:8];
        end else begin
            out = mux_out[7:0];
        end
    end

