module max_module (
    input [7:0] a, b, c, d, // Inputs to find the maximum
    output [7:0] max // Output of the maximum module
);

    wire [7:0] max1, max2, max3; // Intermediate wires to find the maximum

    assign max1 = (a > b) ? a : b;
    assign max2 = (c > d) ? c : d;
    assign max3 = (max1 > max2) ? max1 : max2;

    assign max = max3; // Output the maximum value

endmodule

module add_module (
    input [7:0] x, y, // Inputs to the carry-select adder
    output [7:0] sum, // Output of the carry-select adder
    output overflow // Output indicating overflow
);

    wire [7:0] sum1, sum2; // Intermediate wires to find the sum

    assign sum1 = x + y;
    assign sum2 = x[7] & y[7] ? sum1 + 1 : sum1;

    assign sum = sum2[7:0]; // Output the 8-bit sum

    assign overflow = (sum2[7] != x[7]) & (sum2[7] != y[7]); // Check for overflow

endmodule

module top_module (
    input [7:0] a, b, c, d, // Inputs to the maximum module
    input [7:0] x, y, // Inputs to the addition module
    input select, // Selects which module to use as input to the functional module
    output [7:0] sum, // Output of the functional module
    output overflow // Output of the addition module indicating overflow
);

    wire [7:0] max_val, add_val; // Intermediate wires to hold the output of the modules

    max_module max_inst (
        .a(a),
        .b(b),
        .c(c),
        .d(d),
        .max(max_val)
    );

    add_module add_inst (
        .x(x),
        .y(y),
        .sum(add_val),
        .overflow(overflow)
    );

    assign sum = select ? add_val : max_val; // Output the selected module's output

    assign sum = (overflow && !select) ? add_val : sum; // Check for invalid output and choose the other module's output

endmodule

