module vending_machine (
  input clk,
  input reset,
  input nickel,
  input dime,
  input cola,
  input lemonade,
  output reg dispense_cola,
  output reg dispense_lemonade
);

  parameter S_IDLE = 2'b00;
  parameter S_NICKEL = 2'b01;
  parameter S_DIME = 2'b10;
  parameter S_DISPENSE_COLA = 2'b11;

  parameter S_DISPENSE_LEMONADE = 2'b11;

  reg [1:0] state;
  reg [3:0] total_amount;

  always @(posedge clk) begin
    if (reset) begin
      state <= S_IDLE;
      total_amount <= 0;
      dispense_cola <= 0;
      dispense_lemonade <= 0;
    end else begin
      case (state)
        S_IDLE: begin
          if (nickel) begin
            total_amount <= total_amount + 5;
            state <= S_NICKEL;
          end else if (dime) begin
            total_amount <= total_amount + 10;
            state <= S_DIME;
          end else begin
            state <= S_IDLE;
          end
        end
        S_NICKEL: begin
          if (nickel) begin
            total_amount <= total_amount + 5;
            state <= S_NICKEL;
          end else if (dime) begin
            total_amount <= total_amount + 10;
            state <= S_DIME;
          end else if (total_amount == 5 && cola) begin
            dispense_cola <= 1;
            total_amount <= 0;
            state <= S_DISPENSE_COLA;
          end else if (total_amount == 10 && lemonade) begin
            dispense_lemonade <= 1;
            total_amount <= 0;
            state <= S_DISPENSE_LEMONADE;
          end else begin
            total_amount <= 0;
            state <= S_IDLE;
          end
        end
        S_DIME: begin
          if (nickel) begin
            total_amount <= total_amount + 5;
            state <= S_NICKEL;
          end else if (dime) begin
            total_amount <= total_amount + 10;
            state <= S_DIME;
          end else if (total_amount == 5 && cola) begin
            dispense_cola <= 1;
            total_amount <= 0;
            state <= S_DISPENSE_COLA;
          end else if (total_amount == 10 && lemonade) begin
            dispense_lemonade <= 1;
            total_amount <= 0;
            state <= S_DISPENSE_LEMONADE;
          end else begin
            total_amount <= 0;
            state <= S_IDLE;
          end
        end
        S_DISPENSE_COLA: begin
          dispense_cola <= 0;
          state <= S_IDLE;
        end
        S_DISPENSE_LEMONADE: begin
          dispense_lemonade <= 0;
          state <= S_IDLE;
        end
      endcase
    end
  end
endmodule

module pixel_buffer (
    input clk,
    input reset,

    input [17:0] address,
    input [1:0] byteenable,
    input read,
    input write,
    input [15:0] writedata,

    inout [15:0] SRAM_DQ,

    output reg [15:0] readdata,
    output reg readdatavalid,

    output reg [17:0] SRAM_ADDR,
    output reg SRAM_LB_N,
    output reg SRAM_UB_N,
    output reg SRAM_CE_N,
    output reg SRAM_OE_N,
    output reg SRAM_WE_N
);

reg is_read, is_write;
reg [15:0] writedata_reg;

always @(posedge clk) begin
    if (reset) begin
        is_read <= 1'b0;
        is_write <= 1'b0;
    end else begin
        is_read <= read;
        is_write <= write;
    end
end

always @(posedge clk) begin
    if (reset) begin
        writedata_reg <= 16'h0000;
    end else begin
        writedata_reg <= writedata;
    end
end

assign SRAM_DQ = (is_write) ? writedata_reg : 16'hzzzz;

always @(posedge clk) begin
    if (reset) begin
        SRAM_ADDR <= 18'h00000;
        SRAM_LB_N <= 1'b1;
        SRAM_UB_N <= 1'b1;
        SRAM_CE_N <= 1'b1;
        SRAM_OE_N <= 1'b1;
        SRAM_WE_N <= 1'b1;
        readdata <= 16'h0000;
        readdatavalid <= 1'b0;
    end else begin
        SRAM_ADDR <= address;
        SRAM_LB_N <= ~(byteenable[0] & (read | write));
        SRAM_UB_N <= ~(byteenable[1] & (read | write));
        SRAM_CE_N <= ~(read | write);
        SRAM_OE_N <= ~read;
        SRAM_WE_N <= ~write;
        readdata <= SRAM_DQ;
        readdatavalid <= is_read;
    end
end

endmodule

module top_module(
    input [31:0] a,
    input [31:0] b,
    output [31:0] sum
);

    wire [15:0] a_lsb = a[15:0];
    wire [15:0] b_lsb = b[15:0];
    wire [15:0] lsb_sum = a_lsb + b_lsb;

    wire [15:0] carry_lookahead = ((a_lsb & b_lsb) | (a_lsb & ~lsb_sum) | (b_lsb & ~lsb_sum)) << 1;

    wire [31:0] a_msb = a[31:16];
    wire [31:0] b_msb = b[31:16];
    wire [31:0] msb_sum = a_msb + b_msb + carry_lookahead[15:0];

    // Functional module to calculate final carry
    carry_module carry(
        .a_carry(carry_lookahead[16]),
        .b_carry(msb_sum[15]),
        .final_carry(final_carry)
    );

    assign sum = {msb_sum[15:0], lsb_sum} + (final_carry << 16);

    // 16-bit adder module
    assign lsb_sum = a_lsb + b_lsb;

    // Carry look-ahead adder module
    assign carry_lookahead = ((a_lsb & b_lsb) | (a_lsb & ~lsb_sum) | (b_lsb & ~lsb_sum)) << 1;

endmodule

module carry_module(
    input a_carry,
    input b_carry,
    output final_carry
);
    assign final_carry = a_carry | b_carry;
endmodule

