module square_root (
    input [15:0] num,
    output reg [7:0] sqrt
);

reg [15:0] x;
reg [7:0] y;

always @(num) begin
    x <= num;
    y <= 0;
end

always @(x, y) begin
    if (x == 0) begin
        sqrt <= 0;
    end else begin
        for (i = 0; i < 8; i = i + 1) begin
            y <= (y << 1) | (x[15] >> i);
            x <= (x << 2) >> 1;
            if (y >= sqrt) begin
                y <= y - sqrt;
                sqrt <= (sqrt << 1) | 1;
            end else begin
                sqrt <= sqrt << 1;
            end
        end
    end
end

endmodule

