module uart_transmitter (
  input clk,
  input reset_n,
  input [7:0] data_in,
  input baud_rate,
  output tx,
  output tx_busy
);

  reg [3:0] count = 4'b0000;
  reg [7:0] shift_reg = 8'b00000000;
  reg tx_busy_reg = 1'b0;

  always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
      count <= 4'b0000;
      shift_reg <= 8'b00000000;
      tx_busy_reg <= 1'b0;
    end else begin
      if (count == 4'b0000) begin
        shift_reg <= data_in;
        count <= count + 1;
        tx <= 1'b0;
        tx_busy_reg <= 1'b1;
      end else if (count < baud_rate) begin
        count <= count + 1;
        tx <= shift_reg[0];
        shift_reg <= {shift_reg[6:0], 1'b0};
      end else if (count == baud_rate) begin
        count <= 4'b0000;
        tx <= 1'b1;
        tx_busy_reg <= 1'b0;
      end
    end
  end

  assign tx_busy = tx_busy_reg;

endmodule

module uart_receiver (
  input clk,
  input reset_n,
  input rx,
  input baud_rate,
  output [7:0] data_out,
  output rx_busy
);

  reg [3:0] count = 4'b0000;
  reg [7:0] shift_reg = 8'b00000000;
  reg rx_busy_reg = 1'b0;

  always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
      count <= 4'b0000;
      shift_reg <= 8'b00000000;
      rx_busy_reg <= 1'b0;
    end else begin
      if (count == 4'b0000) begin
        shift_reg <= {shift_reg[6:0], rx};
        count <= count + 1;
        rx_busy_reg <= 1'b1;
      end else if (count < baud_rate) begin
        count <= count + 1;
        shift_reg <= {shift_reg[6:0], rx};
      end else if (count == baud_rate) begin
        count <= 4'b0000;
        data_out <= shift_reg;
        rx_busy_reg <= 1'b0;
      end
    end
  end

  assign rx_busy = rx_busy_reg;

endmodule

