module LogExp (
  input signed [n-1:0] in,
  output signed [m-1:0] exp_out,
  output signed [m-1:0] log_out
);

parameter n = 16; // number of bits used to represent the input signal
parameter m = 16; // number of bits used to represent the output signals.

// Constants
parameter REAL_WIDTH = 32;
parameter EXP_WIDTH = 8;
parameter LOG_WIDTH = 16;
parameter EXP_PRECISION = 1 << EXP_WIDTH;
parameter LOG_PRECISION = 1 << LOG_WIDTH;
parameter LN2 = 0.69314718056;

// Exponential function
function [m-1:0] exp_func;
  input signed [n-1:0] x;
  reg signed [REAL_WIDTH-1:0] result;
  reg signed [REAL_WIDTH-1:0] term;
  reg [EXP_WIDTH:0] i;
  begin
    result = (1 << (EXP_PRECISION-1)) + x;
    term = x;
    for (i = 2; i < EXP_PRECISION; i = i + 1) begin
      term = term * x / i;
      result = result + term;
    end
    exp_func = result[REAL_WIDTH-m-1:REAL_WIDTH-2*m];
  end
endfunction

// Logarithmic function
function [m-1:0] log_func;
  input signed [n-1:0] x;
  reg signed [REAL_WIDTH-1:0] result;
  reg signed [REAL_WIDTH-1:0] term;
  reg [LOG_WIDTH:0] i;
  begin
    result = (x - (1 << (LOG_PRECISION-1))) / (x + (1 << (LOG_PRECISION-1)));
    term = result;
    for (i = 3; i < LOG_PRECISION; i = i + 2) begin
      term = term * result * result;
      result = result + term / i;
    end
    log_func = result / LN2;
  end
endfunction

// Output signals
assign exp_out = exp_func(in);
assign log_out = log_func(in);

endmodule

