module CLA32(
    input [31:0] a,
    input [31:0] b,
    input cin,
    output [31:0] sum,
    output cout
);

wire [3:0] g, p;
wire [4:0] c;

assign g[0] = a[0] & b[0];
assign p[0] = a[0] ^ b[0];
assign c[0] = cin;

genvar i;
generate
    for (i = 1; i < 32; i = i + 1) begin
        assign g[i] = a[i] & b[i];
        assign p[i] = a[i] ^ b[i];
        assign c[i] = g[i-1] | (p[i-1] & c[i-1]);
    end
endgenerate

assign sum = a + b + cin;
assign cout = g[31] | (p[31] & c[31]);

endmodule

module tri_state_detect (
    input clk,
    input rst,
    input in,
    output [31:0] count_h,
    output [31:0] count_l,
    output detected
);

    reg [31:0] ticks;
    reg [31:0] t1;
    reg [31:0] t2;
    reg synced;
    reg [31:0] r_count_h;
    reg [31:0] r_count_l;

    initial begin
        ticks       <= 0;
        t1          <= 0;
        t2          <= 0;
        synced      <= 0;
        r_count_h   <= 0;
        r_count_l   <= 0;
    end

    always @(posedge clk or posedge rst) begin
        if(rst) begin
            ticks <= 0;
        end
        else begin
            ticks <= ticks + 1;
        end
    end

    always @(negedge in or posedge rst) begin
        if(rst) begin
            t2 <= 0;
        end
        else begin
            if(t1 > 0) begin
                t2 <= ticks;
            end
        end
    end

    always @(posedge in or posedge rst) begin
        if(rst) begin
            t1          <= 0;
            r_count_h   <= 0;
            r_count_l   <= 0;
            synced      <= 0;
        end
        else begin
            if(t2 > t1) begin
                r_count_h = t2 - t1;
                r_count_l = ticks - t2;
                synced <= 1;
            end
            else begin
                synced <= 0;
            end
            t1 <= ticks;
        end
    end

    assign count_h  = r_count_h;
    assign count_l  = r_count_l;
    assign detected = (synced & in);

endmodule

