    full_adder fa1(.a(A[1]), .b(B[1]), .c(C[1]), .sum(S[1]), .carry(C[1]));
    full_adder fa2(.a(A[2]), .b(B[2]), .c(C[2]), .sum(S[2]), .carry(C[2]));
    full_adder fa3(.a(A[3]), .b(B[3]), .c(C[3]), .sum(S[3]), .carry(C[3]));

    assign Cout = C[WIDTH];
endmodule

module full_adder(a, b, c, sum, carry);
    input a, b, c;
    output sum, carry;

    assign sum = a ^ b ^ c;
    assign carry = (a & b) | (b & c) | (a & c);
endmodule

