module adler_checksum (
  input wire [8*n-1:0] byte,
  input wire [15:0] checksum,
  output reg match
);

parameter n = 16; // number of bytes in input sequence

reg [15:0] A, B, final_checksum;
integer i;

always @(*) begin
  A = 1;
  B = 0;

  for (i = 0; i < n; i = i + 1) begin
    A = (A + byte[8*i +: 8]) % 65521;
    B = (B + A) % 65521;
  end

  final_checksum = (B << 8) | A;
  match = (final_checksum == checksum);
end

endmodule

