module nco #(
    parameter AW = 6, // AXI address width
    parameter DW = 32 // AXI data width
) (
    input wire ap_clk, // AXI clock
    input wire ap_rst_n, // AXI reset
    input wire [AW-1:0] s_axi_awaddr, // AXI write address
    input wire s_axi_awvalid, // AXI write valid
    output wire s_axi_awready, // AXI write ready
    input wire [DW-1:0] s_axi_wdata, // AXI write data
    input wire [DW/8-1:0] s_axi_wstrb, // AXI write strobe
    input wire s_axi_wvalid, // AXI write valid
    output wire s_axi_wready, // AXI write ready
    output wire [1:0] s_axi_bresp, // AXI write response
    output wire s_axi_bvalid, // AXI write response valid
    input wire s_axi_bready, // AXI write response ready
    input wire [AW-1:0] s_axi_araddr, // AXI read address
    input wire s_axi_arvalid, // AXI read valid
    output wire s_axi_arready, // AXI read ready
    output wire [DW-1:0] s_axi_rdata, // AXI read data
    output wire [1:0] s_axi_rresp, // AXI read response
    output wire s_axi_rvalid, // AXI read response valid
    input wire s_axi_rready // AXI read response ready
);

    parameter PHASE_WIDTH = 16;
    parameter FREQ_WIDTH = 32;
    parameter ACC_WIDTH = PHASE_WIDTH + FREQ_WIDTH;
    parameter SIN_WIDTH = DW;

    localparam AW_BYTES = AW / 8;
    localparam SIN_DEPTH = 1 << PHASE_WIDTH;

    reg [PHASE_WIDTH-1:0] phase_acc;
    reg [FREQ_WIDTH-1:0] freq_acc;
    reg [1:0] status_reg;
    reg [SIN_WIDTH-1:0] sin_table [0:SIN_DEPTH-1];

    assign s_axi_awready = 1;
    assign s_axi_wready = 1;
    assign s_axi_arready = 1;
    assign s_axi_rdata = (status_reg == 3'b000) ? sin_table[phase_acc[PHASE_WIDTH-1:0]] : 0;
    assign s_axi_rresp = 2'b00;
    assign s_axi_rvalid = (status_reg != 3'b000) ? 1 : 0;
    assign s_axi_bresp = 2'b00;
    assign s_axi_bvalid = 0;

    always @(posedge ap_clk) begin
        if (!ap_rst_n) begin
            phase_acc <= 0;
            freq_acc <= 0;
            status_reg <= 0;
            sin_table <= 0;
        end else begin
            // Update frequency accumulator
            freq_acc <= s_axi_wvalid && s_axi_awaddr == 32'h00 ? s_axi_wdata : freq_acc;

            // Update phase accumulator
            if (status_reg[0]) begin // NCO is enabled
                if (status_reg[2]) begin // Frequency accumulator overflow
                    phase_acc <= phase_acc + freq_acc + 1;
                    freq_acc <= 0;
                    status_reg[2] <= 0;
                end else begin
                    phase_acc <= phase_acc + freq_acc;
                end
                if (phase_acc[PHASE_WIDTH-1]) begin // Phase accumulator overflow
                    phase_acc <= phase_acc - SIN_DEPTH;
                    status_reg[1] <= 1;
                end else begin
                    status_reg[1] <= 0;
                end
            end

            // Update sin table
            if (s_axi_wvalid && s_axi_awaddr >= 32'h80 && s_axi_awaddr < 32'h80 + SIN_DEPTH*SIN_WIDTH/AW_BYTES) begin
                sin_table[(s_axi_awaddr - 32'h80)/SIN_WIDTH] <= s_axi_wdata;
            end

            // Update control register
            if (s_axi_wvalid && s_axi_awaddr == 32'h08) begin
                status_reg[0] <= s_axi_wdata[0];
                if (s_axi_wdata[1]) begin // Reset phase accumulator
                    phase_acc <= 0;
                end
                if (s_axi_wdata[2]) begin // Reset frequency accumulator
                    freq_acc <= 0;
                end
            end
        end
    end
endmodule

