module Processor(output reg[2:0] Y, output reg flag, input[2:0] A, B, C, D, input[3:0] opcode, input[15:0] INSTR_in);

parameter WORD_WIDTH = 16;
parameter DR_WIDTH = 3;
parameter SB_WIDTH = DR_WIDTH;
parameter SA_WIDTH = DR_WIDTH;
parameter OPCODE_WIDTH = 7;
parameter INSTR_WIDTH = WORD_WIDTH;

wire[WORD_WIDTH-1:0] INSTR_out;

InstructionMemory instruction_memory(INSTR_out, INSTR_in);

always@(*)
	begin
		case(opcode)
			4'b0000: Y = A + B;
			4'b0001: Y = A - B;
			4'b0010: Y = A & B;
			4'b0011: Y = A | B;
			4'b0100: Y = ~A;
			4'b0101: Y = {A[0], A} << 1;
			4'b0110: Y = A >> 1;
			4'b0111: Y = A ^ B;
			4'b1000: Y = A + B + C;
			4'b1001: Y = A - B - C;
			4'b1010: Y = A & B & C;
			4'b1011: Y = A | B | C;
			4'b1100: Y = ~B;
			4'b1101: Y = A << C;
			4'b1110: Y = A >> C;
			4'b1111: Y = A ^ B ^ C ^ D;
			default: Y = 0;
		endcase

		if(Y[2] == 1)
			flag = 1;
		else
			flag = 0;
	end

endmodule

