module fifo_buffer (
  input        reset,
  input        wr_clk,
  input        rd_clk,
  input  [7:0] wr_data,
  input        wr_en,
  input        rd_en,
  output [7:0] rd_data,
  output       empty,
  output       full
);

  parameter AW = 4; // Number of bits to access all the entries
  parameter DEPTH = 16; // Depth of the FIFO buffer

  //##########
  //# REGISTERS
  //##########
  reg [7:0] buffer [0:DEPTH-1];
  reg [AW:0] wr_ptr;
  reg [AW:0] rd_ptr;
  reg        empty;
  reg        full;

  //##########
  //# WIRES
  //##########
  wire [AW:0] wr_ptr_next;
  wire [AW:0] rd_ptr_next;
  wire        empty_next;
  wire        full_next;

  //################
  //# WRITE POINTER
  //################
  assign wr_ptr_next = wr_ptr + 1'b1;
  always @(posedge wr_clk or posedge reset) begin
    if (reset) begin
      wr_ptr <= 0;
    end else if (wr_en && !full) begin
      wr_ptr <= wr_ptr_next;
    end
  end

  //################
  //# READ POINTER
  //################
  assign rd_ptr_next = rd_ptr + 1'b1;
  always @(posedge rd_clk or posedge reset) begin
    if (reset) begin
      rd_ptr <= 0;
    end else if (rd_en && !empty) begin
      rd_ptr <= rd_ptr_next;
    end
  end

  //############
  //# FIFO LOGIC
  //############
  assign empty_next = (wr_ptr == rd_ptr) && !full;
  assign full_next = (wr_ptr_next == rd_ptr) && !empty;
  always @(posedge wr_clk or posedge rd_clk or posedge reset) begin
    if (reset) begin
      empty <= 1;
      full <= 0;
    end else begin
      empty <= empty_next;
      full <= full_next;
      if (wr_en && !full) begin
        buffer[wr_ptr] <= wr_data;
      end
      if (rd_en && !empty) begin
        rd_data <= buffer[rd_ptr];
      end
    end
  end

endmodule

module axis_bram_writer #
(
  parameter integer AXIS_TDATA_WIDTH = 32,
  parameter integer BRAM_DATA_WIDTH = 32,
  parameter integer BRAM_ADDR_WIDTH = 10
)
(
  // System signals
  input  wire                         aclk,
  input  wire                         aresetn,

  output wire [BRAM_ADDR_WIDTH-1:0]   sts_data,

  // Slave side
  output wire                         s_axis_tready,
  input  wire [AXIS_TDATA_WIDTH-1:0]  s_axis_tdata,
  input  wire                         s_axis_tvalid,

  // BRAM port
  output wire                         bram_porta_clk,
  output wire                         bram_porta_rst,
  output wire [BRAM_ADDR_WIDTH-1:0]   bram_porta_addr,
  output wire [BRAM_DATA_WIDTH-1:0]   bram_porta_wrdata,
  output wire [BRAM_DATA_WIDTH/8-1:0] bram_porta_we
);

  reg [BRAM_ADDR_WIDTH-1:0] int_addr_reg, int_addr_next;
  reg int_enbl_reg, int_enbl_next;

  always @(posedge aclk)
  begin
    if(~aresetn)
    begin
      int_addr_reg <= {(BRAM_ADDR_WIDTH){1'b0}};
      int_enbl_reg <= 1'b0;
    end
    else
    begin
      int_addr_reg <= int_addr_next;
      int_enbl_reg <= int_enbl_next;
    end
  end

  always @*
  begin
    int_addr_next = int_addr_reg;
    int_enbl_next = int_enbl_reg;

    if(~int_enbl_reg)
    begin
      int_enbl_next = s_axis_tvalid;
    end

    if(s_axis_tvalid & int_enbl_reg)
    begin
      int_addr_next = int_addr_reg + 1'b1;
    end
  end

  assign sts_data = int_addr_reg;

  assign s_axis_tready = ~int_enbl_reg;

  assign bram_porta_clk = aclk;
  assign bram_porta_rst = ~aresetn;
  assign bram_porta_addr = int_addr_reg;
  assign bram_porta_wrdata = s_axis_tdata;
  assign bram_porta_we = {(BRAM_DATA_WIDTH/8){s_axis_tvalid & int_enbl_reg}};

endmodule

