module process(inputs, toa, tob);
input [7:0] inputs_validdata;
input inputs_Readtoa, inputs_Readtob, inputs_iWriteEnable;
input [9:0] inputs_iAddress, inputs_iReadAddress;
output [7:0] toa, tob;
reg [7:0] device_memory [0:1023];
integer i;

initial begin
    for (i = 0; i < 1024; i = i + 1) begin
        device_memory[i] = 8'b0;
    end
end

always @(inputs) begin
    if (inputs_Readtoa) begin
        toa = inputs_validdata;
    end
    if (inputs_Readtob) begin
        tob = inputs_validdata;
    end
    if (inputs_iWriteEnable) begin
        device_memory[inputs_iAddress] = inputs_validdata;
    end
    if (!inputs_iWriteEnable && inputs_iReadAddress == inputs_iAddress) begin
        toa = device_memory[inputs_iAddress];
    end
end

endmodule

module calculator (
    input [7:0] a,
    input [7:0] b,
    input [1:0] op,
    input clk,
    output reg [7:0] result,
    output reg overflow
);

    reg [15:0] temp;

    always @(posedge clk) begin
        case (op)
            2'b00: result <= a + b;
            2'b01: result <= a - b;
            2'b10: result <= a * b;
            2'b11: begin
                if (b == 0) begin
                    result <= 8'b0;
                    overflow <= 1;
                end else begin
                    temp <= {a, 8'b0} / b;
                    if (temp > 8'b11111111) begin
                        result <= 8'b0;
                        overflow <= 1;
                    end else begin
                        result <= temp[7:0];
                        overflow <= 0;
                    end
                end
            end
        endcase
    end

endmodule

