  wire [31:0] C1, C2, C3, C4;

  assign P = A ^ B;
  assign G = A & B;

  assign C1 = G << 1;
  assign C2 = P & (G << 1);
  assign C3 = P & (C1 << 1);
  assign C4 = (C2 | C3) << 1;

