module binary_adder(
  input [3:0] A,
  input [3:0] B,
  input Cin,
  output [3:0] Sum,
  output Cout
);

  wire [3:0] xor_out;
  wire [3:0] and_out;
  wire [3:0] or_out;

  // Calculate the XOR of A and B
  assign xor_out = A ^ B;

  // Calculate the AND of A and B
  assign and_out = A & B;

  // Calculate the OR of the AND and the shifted XOR
  assign or_out = {xor_out[3], or_out[2:0]} | and_out;

  // Calculate the sum
  assign Sum = xor_out ^ Cin;

  // Calculate the carry-out
  assign Cout = or_out[3];

endmodule

module pll_clock (
    input areset,
    input inclk0,
    output reg c0,
    output reg locked
);

parameter MULT = 8;
reg [31:0] count;
reg [31:0] phase_accumulator;
wire [31:0] phase_increment;

assign phase_increment = (inclk0 * MULT) / 100_000_000;

always @(posedge inclk0, negedge areset) begin
    if (areset == 0) begin
        phase_accumulator <= 0;
        count <= 0;
        c0 <= 0;
        locked <= 1;
    end else begin
        phase_accumulator <= phase_accumulator + phase_increment;
        if (phase_accumulator >= 2**32) begin
            phase_accumulator <= phase_accumulator - 2**32;
            count <= count + 1;
        end
        if (count >= MULT/2) begin
            count <= 0;
            c0 <= ~c0;
        end
        if (locked == 1 && count == 0) begin
            locked <= 0;
        end
    end
end

endmodule

module Adder_4bit (A, B, Cin, Sum, Cout, clk, rst);
  input [3:0] A, B;
  input Cin, clk, rst;
  output [3:0] Sum;
  output Cout;
  wire [3:0] Xor1, Xor2, Xor3, And1, And2, And3;
  wire Cin_xor1, Cin_xor2, Cin_xor3, Cin_and1, Cin_and2, Cout_xor;

  assign Xor1 = A ^ B;
  assign Xor2 = Xor1 ^ Cin;
  assign Xor3 = Xor1 ^ Cin_xor1;
  assign And1 = Xor1 & Cin;
  assign And2 = A & B;
  assign And3 = Cin_and1 & Xor1;
  assign Cin_xor1 = Cin ^ 1'b1;
  assign Cin_xor2 = Cin_xor1 ^ 1'b1;
  assign Cin_xor3 = Cin_xor2 ^ 1'b1;
  assign Cin_and1 = Cin & 1'b1;
  assign Cin_and2 = Cin_and1 & And1;
  assign Cout_xor = Cin_xor3 & And3;

  DFFX1 Q0 ( .D(Xor2[0]), .CK(clk), .Q(Sum[0]), .RN(rst) );
  DFFX1 Q1 ( .D(Xor2[1]), .CK(clk), .Q(Sum[1]), .RN(rst) );
  DFFX1 Q2 ( .D(Xor2[2]), .CK(clk), .Q(Sum[2]), .RN(rst) );
  DFFX1 Q3 ( .D(Xor2[3]), .CK(clk), .Q(Sum[3]), .RN(rst) );
  DFFX1 Q4 ( .D(Cout_xor), .CK(clk), .Q(Cout), .RN(rst) );

endmodule

