    input  wire        iWR,       //                      .write
    input  wire        iRD,       //                      .read
    input  wire        iCS,       //                      .chipselect
    input  wire        iRST_N     //               reset_n.reset_n
);

    localparam H_RES = 640;
    localparam V_RES = 480;
    localparam H_SYNC_FRONT_PORCH = 16;
    localparam H_SYNC_PULSE_WIDTH = 96;
    localparam H_SYNC_BACK_PORCH = 48;
    localparam V_SYNC_FRONT_PORCH = 10;
    localparam V_SYNC_PULSE_WIDTH = 2;
    localparam V_SYNC_BACK_PORCH = 33;

    reg [9:0] red;
    reg [9:0] green;
    reg [9:0] blue;
    reg h_sync;
    reg v_sync;
    reg v_blank;
    reg [9:0] count_h;
    reg [9:0] count_v;
    reg [17:0] address;

    always @(posedge iCLK) begin
        if (!iRST_N) begin
            red <= 0;
            green <= 0;
            blue <= 0;
            h_sync <= 0;
            v_sync <= 0;
            v_blank <= 1;
            count_h <= 0;
            count_v <= 0;
            address <= 0;
        end else begin
            if (count_h == H_RES + H_SYNC_FRONT_PORCH + H_SYNC_PULSE_WIDTH + H_SYNC_BACK_PORCH - 1) begin
                count_h <= 0;
                h_sync <= 1;
            end else if (count_h == H_RES + H_SYNC_FRONT_PORCH + H_SYNC_PULSE_WIDTH - 1) begin
                count_h <= count_h + 1;
                h_sync <= 0;
            end else if (count_h == H_RES + H_SYNC_FRONT_PORCH - 1) begin
                count_h <= count_h + 1;
            end else if (count_h == H_RES - 1) begin
                count_h <= 0;
                count_v <= count_v + 1;
                v_blank <= 1;
                address <= count_v * H_RES;
            end else begin
                count_h <= count_h + 1;
                v_blank <= 0;
                address <= address + 1;
            end

            if (count_v == V_RES + V_SYNC_FRONT_PORCH + V_SYNC_PULSE_WIDTH + V_SYNC_BACK_PORCH - 1) begin
                count_v <= 0;
                v_sync <= 1;
            end else if (count_v == V_RES + V_SYNC_FRONT_PORCH + V_SYNC_PULSE_WIDTH - 1) begin
                count_v <= count_v + 1;
                v_sync <= 0;
            end else if (count_v == V_RES + V_SYNC_FRONT_PORCH - 1) begin
                count_v <= count_v + 1;
            end else if (count_v == V_RES - 1) begin
                count_v <= 0;
            end else begin
                count_v <= count_v + 1;
            end

            if (iRD && !iWR && iCS) begin
                oDATA <= {8'b0, iDATA};
            end else if (!iRD && iWR && iCS) begin
                $display("Writing to address %d: %x", iADDR, iDATA);
            end else begin
                oDATA <= 16'hffff;
            end
        end
    end

    assign VGA_R = red;
    assign VGA_G = green;
    assign VGA_B = blue;
    assign VGA_HS = h_sync;
    assign VGA_VS = v_sync;
    assign VGA_SYNC = h_sync & v_sync;
    assign VGA_BLANK = v_blank;
    assign VGA_CLK = iCLK_25;

    endmodule

module keypressed(clock, reset, enable_in, enable_out);

	input clock;			// The on-board clock, default 50 MHz
	input	reset;			// Reset is active low. Should be connected to pushbutton 0.
	input enable_in;		// Should be connected to pushbutton 1.
	output enable_out;	// The output is high for one FPGA clock cycle each time pushbutton 1 is pressed and released.

// Variables for keeping track of the state.
	reg [1:0] key_state, next_key_state;
	reg enable_out;

// Set up parameters for "state" of the pushbutton.
// Since there are three states, we are using 2-bits to represent the state in a so-called "dense" assignment.
	parameter [1:0] KEY_FREE = 2'b00, KEY_PRESSED = 2'b01, KEY_RELEASED = 2'b10;

// The following always block represents sequential logic, and therefore uses non-blocking assignments.

// This always block is sensitized to the clock input and the reset input. You should picture this always block as a 2-bit
// register with an active-low asynchronous clear.

	always @(posedge clock or negedge reset) begin

	// If reset = 0, there must have been a negative edge on the reset.
	// Since the effect of the reset occurs in the absence of a clock pulse, the reset is ASYNCHRONOUS.
		if (reset == 1'b0)
			key_state <= KEY_FREE;

	// If reset !=0 but this always block is executing, there must have been a positive clock edge.
	// On each positive clock edge, the next state becomes the present state.
		else
			key_state <= next_key_state;
	end

// The following always block represents combinational logic.  It uses blocking assignments.

// This always block is sensitized to changes in the present state and enable input. You should picture this block as 
// a combinational circuit that feeds the register inputs. It determines the next state based on the current state and
// the enable input.

	always @(key_state, enable_in) begin

	// To be safe, assign values to the next_key_state and enable_out. That way, if none of the paths in the case
	// statement apply, these variables have known values.
		next_key_state = key_state;
		enable_out = 1'b0;

	// Use the present state to determine the next state.
		case (key_state)

		// If the key is free (i.e., is unpressed and was not just released):
			KEY_FREE: begin

			// If the enable input button is down, make the next state KEY_PRESSED.
				if (enable_in == 1'b0)
					next_key_state = KEY_PRESSED;
			end

		// If the key is pressed:
			KEY_PRESSED: begin

			// If the enable button is up, make the next state KEY_RELEASED.
				if (enable_in == 1'b1)
					next_key_state = KEY_RELEASED;
			end

		// If the key is released (i.e., the button has just gone from being pressed to being released):
			KEY_RELEASED: begin

			// Take the output high.
				enable_out = 1'b1;

			// Make the next state KEY_FREE. Note that this state transition always happens and is independent of
			// the input
				next_key_state = KEY_FREE;
			end

		// If none of the above - something that should never happen - make the next state and output unknown.
			default: begin
				next_key_state = 2'bxx;
				enable_out = 1'bx;
			end

		endcase

	end

endmodule

module mux_adder (
    input [7:0] a,
    input [7:0] b,
    input [2:0] sel,
    input [7:0] data0,
    input [7:0] data1,
    input [7:0] data2,
    input [7:0] data3,
    input [7:0] data4,
    input [7:0] data5,
    output [7:0] out,
    output overflow
);

// Convert a and b to sign-magnitude format
wire [7:0] a_mag = (a[7] == 1) ? ~a + 1 : a;
wire [7:0] b_mag = (b[7] == 1) ? ~b + 1 : b;

// Create the 6-to-1 multiplexer
wire [7:0] mux_out;
assign mux_out = (sel == 0) ? data0 :
                 (sel == 1) ? data1 :
                 (sel == 2) ? data2 :
                 (sel == 3) ? data3 :
                 (sel == 4) ? data4 :
                 (sel == 5) ? data5 :
                 a_mag;

// Create the carry-select adder
wire [8:0] add_out;
wire carry_out;
csa csa_inst (
    .a(mux_out),
    .b(b_mag),
    .c(9'b0),
    .s(add_out),
    .co(carry_out)
);

// Check for signed overflow
assign overflow = (add_out[8] == 1) ? 1 : 0;

// Convert the result back to 2's complement format
assign out = (add_out[8] == 1) ? ~add_out[7:0] + 1 : add_out[7:0];

endmodule

