module rgb2hsv (
	input clk,
	input res,
	input read,
	input [15:0] data,
	output [4:0] saturation,
	output [4:0] value,
	output [8:0] hue,
	output reg hue_invalid,
	output reg done
);

parameter DIVLATENCY = 4'h8;
parameter FETCH = 3'h0,
					COMPARE = 3'h1,
					DIVSET = 3'h2,
					DIVIDE = 3'h3,
					HUE = 3'h4;

wire [4:0] r;
wire [4:0] g;
wire [4:0] b;

reg [4:0] rbuf;
reg [4:0] gbuf;
reg [4:0] bbuf;
reg [10:0] huediff;
reg [2:0] multiwait;

reg [4:0] min;
reg [4:0] max;

reg [2:0] state;

reg signed [10:0] numer;

assign {r, g, b} = data [14:0];

reg [2:0] colorcomp;
reg [8:0] colordomain;
assign hue = colordomain;

parameter RED = 3'h1;
parameter BLUE = 3'h2;
parameter GREEN = 3'h4;
parameter WHITE = 3'h0;

function [3:0] maxsel;
	input [3:0] colorcomp;
begin
	casex (colorcomp)
		4'b1x0: maxsel = RED;
		4'bx01: maxsel = BLUE;
		4'b01x: maxsel = GREEN;
		default: maxsel = WHITE;
	endcase
end
endfunction

function [3:0] minsel;
	input [3:0] colorcomp;
begin
	casex (colorcomp)
		4'b0x1: minsel = RED;
		4'bx10: minsel = BLUE;
		4'b10x: minsel = GREEN;
		default: minsel = WHITE;
	endcase
end
endfunction

reg [3:0] clkcount;
wire [16:0] huediff60;
wire [10:0] quot;

divider	div0 (
	.clock ( clkcount[3] ),
	.denom ( saturation ),
	.numer ( numer ),
	.quotient ( quot ),
	.remain ( rem )
);


multi ml0(
	clk,
	huediff,
	huediff60);


assign value = max;
assign saturation = max - min;
reg [3:0] divwait;

always @(posedge clk)
begin
	clkcount <= clkcount + 4'b1;
	if(res) begin
		rbuf <= 5'h00;
		gbuf <= 5'h00;
		bbuf <= 5'h00;
		state <= FETCH;
	end else begin
		if (read && (state == FETCH)) begin
			rbuf <= r;
			gbuf <= g;
			bbuf <= b;
			done <= 0;
			state <= COMPARE;
			clkcount <= 0;
		end else if (state == COMPARE) begin

			colorcomp[2] <= (rbuf >= gbuf);
			colorcomp[1] <= (gbuf >= bbuf);
			colorcomp[0] <= (bbuf >= rbuf);
			divwait <= 4'h0;
			multiwait <= 3'b001;
			state <= DIVSET;

		end else if (state == DIVSET) begin

			divwait <= 4'h0;

			case (maxsel(colorcomp))
				RED: max <= rbuf;
				BLUE: max <= bbuf;
				GREEN: max <= gbuf;
				WHITE: max <= 5'h00;
			endcase

			case (minsel(colorcomp))
				RED: begin
					min <= rbuf;
					numer <= (bbuf - gbuf) << 5;
					state <= DIVIDE;
					colordomain <= 9'd180;
					hue_invalid <= 0;
				end
				BLUE: begin
					min <= bbuf;
					numer <= (gbuf - rbuf) << 5;
					state <= DIVIDE;
					colordomain <= 9'd60;
					hue_invalid <= 0;
				end
				GREEN: begin
					min <= gbuf;
					numer <= (rbuf - bbuf) << 5;
					state <= DIVIDE;
					colordomain <= 9'd300;
					hue_invalid <= 0;
				end
				WHITE: begin
					min <= 5'h00;
					hue_invalid <= 1;
					done <= 1;
					state <= FETCH;
				end
			endcase

		end else if (state == DIVIDE) begin
			if (divwait == DIVLATENCY) begin
				huediff <= quot[10:0];
				state <= HUE;
			end else begin
				divwait <= divwait + 4'h1;
			end
		end else if (state == HUE) begin
			if (multiwait[2] == 1'd1) begin
				colordomain <= (huediff60[13:5] + colordomain);
				done <= 1'b1;
				state <= FETCH;
			end else begin
				multiwait <= multiwait << 1;
			end
		end
	end
end

endmodule

module fifo_generator
   (wr_rst_busy,
    dout,
    empty,
    full,
    rd_en,
    wr_en,
    clk,
    din,
    rst);
  output wr_rst_busy;
  output [63:0]dout;
  output empty;
  output full;
  input rd_en;
  input wr_en;
  input clk;
  input [63:0]din;
  input rst;

  reg [5:0] wr_ptr = 0;
  reg [5:0] rd_ptr = 0;
  reg [11:0] count = 0;
  wire [5:0] next_wr_ptr = wr_ptr + 1;
  wire [5:0] next_rd_ptr = rd_ptr + 1;
  wire [11:0] next_count = count + 1;
  wire [11:0] next_count_rd = count - 1;
  reg [63:0] ram [0:11];
  reg wr_rst_busy;
  wire [63:0]dout = ram[rd_ptr];
  wire empty = (count == 0);
  wire full = (count == 12);

  always @(posedge clk) begin
    if (rst) begin
      wr_ptr <= 0;
      rd_ptr <= 0;
      count <= 0;
      wr_rst_busy <= 1;
    end else if (wr_en && !full) begin
      ram[wr_ptr] <= din;
      wr_ptr <= next_wr_ptr;
      count <= next_count;
      wr_rst_busy <= 1;
    end else if (rd_en && !empty) begin
      rd_ptr <= next_rd_ptr;
      count <= next_count_rd;
      wr_rst_busy <= 1;
    end else begin
      wr_rst_busy <= 0;
    end
  end
endmodule

