    rc rc0(
    .dst                    (dst), 
    .dstList                (dstList),
    .outdir                 (target_outdir_0_plus1),
    .mc                     (mc),
    .preferPortVector       (w_ppv_0)
    );

    rc rc1(
    .dst                    (dst), 
    .dstList                (dstList),
    .outdir                 (target_outdir_1_plus2),
    .mc                     (mc),
    .preferPortVector       (w_ppv_1)
    );

    rc rc2(
    .dst                    (dst), 
    .dstList                (dstList),
    .outdir                 (target_outdir_2_plus3),
    .mc                     (mc),
    .preferPortVector       (w_ppv_2)
    );

    rc rc3(
    .dst                    (dst), 
    .dstList                (dstList),
    .outdir                 (target_outdir_3),
    .mc                     (mc),
    .preferPortVector       (w_ppv_3)
    );

    assign nextPPV = (indir == 2'b10) ? {w_ppv_0, w_ppv_1, w_ppv_2, w_ppv_3} :
                     (indir == 2'b01) ? {w_ppv_0, w_ppv_1, w_ppv_2, 4'h0} :
                     (indir == 2'b00) ? {w_ppv_0, w_ppv_1, 4'h0, w_ppv_3} :
                     {4'h0, w_ppv_1, w_ppv_2, w_ppv_3};

endmodule

module rc(
    dst,
    dstList,
    outdir,
    mc,
    preferPortVector
    );

    input mc;
    input [3:0] dst;
    input [15:0] dstList;
    input [1:0] outdir;
    output [3:0] preferPortVector;

    reg [3:0] lastPort;

    always @(*) begin
        if (mc) begin
            preferPortVector = dst;
        end else begin
            if (dstList == 16'h0000) begin
                preferPortVector = dst;
            end else begin
                if (dstList[3:0] != 4'h0 && lastPort != 2'b00) begin
                    preferPortVector = dstList[3:0];
                    lastPort = 2'b00;
                end else if (dstList[7:4] != 4'h0 && lastPort != 2'b01) begin
                    preferPortVector = dstList[7:4];
                    lastPort = 2'b01;
                end else if (dstList[11:8] != 4'h0 && lastPort != 2'b10) begin
                    preferPortVector = dstList[11:8];
                    lastPort = 2'b10;
                end else if (dstList[15:12] != 4'h0 && lastPort != 2'b11) begin
                    preferPortVector = dstList[15:12];
                    lastPort = 2'b11;
                end else begin
                    preferPortVector = dst;
                end
            end
        end
    end

endmodule

module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [31:0] in,  // Input signal for transition detection
    output [63:0] sr_out, // 64-bit output from the shift register
    output reg td_out // Output from the input transition detector
);

reg [63:0] shift_reg;
reg [31:0] feedback;
reg [31:0] input_reg;

// Feedback polynomial for 64-bit shift register
parameter POLY = 64'hADDEED1D;

// Generate feedback for shift register
always @(*) begin
    feedback[0] = shift_reg[0] ^ shift_reg[1] ^ shift_reg[3] ^ shift_reg[4] ^ shift_reg[56] ^ shift_reg[63];
    feedback[1] = shift_reg[0];
    feedback[2] = shift_reg[1];
    feedback[3] = shift_reg[2];
    feedback[4] = shift_reg[3];
    feedback[5] = shift_reg[4];
    feedback[6] = shift_reg[5];
    feedback[7] = shift_reg[6];
    feedback[8] = shift_reg[7];
    feedback[9] = shift_reg[8];
    feedback[10] = shift_reg[9];
    feedback[11] = shift_reg[10];
    feedback[12] = shift_reg[11];
    feedback[13] = shift_reg[12];
    feedback[14] = shift_reg[13];
    feedback[15] = shift_reg[14];
    feedback[16] = shift_reg[15];
    feedback[17] = shift_reg[16];
    feedback[18] = shift_reg[17];
    feedback[19] = shift_reg[18];
    feedback[20] = shift_reg[19];
    feedback[21] = shift_reg[20];
    feedback[22] = shift_reg[21];
    feedback[23] = shift_reg[22];
    feedback[24] = shift_reg[23];
    feedback[25] = shift_reg[24];
    feedback[26] = shift_reg[25];
    feedback[27] = shift_reg[26];
    feedback[28] = shift_reg[27];
    feedback[29] = shift_reg[28];
    feedback[30] = shift_reg[29];
    feedback[31] = shift_reg[30];
end

// Shift register
always @(posedge clk) begin
    if (reset) begin
        shift_reg <= 0;
    end else begin
        shift_reg <= {shift_reg[62:0], feedback[0]};
    end
end

// Input transition detector
always @(posedge clk) begin
    if (reset) begin
        input_reg <= 0;
        td_out <= 0;
    end else begin
        input_reg <= {input_reg[30:0], in};
        if (input_reg[31] && !input_reg[30]) begin
            td_out <= 1;
        end
    end
end

// AND operation module
and_module and_inst(
    .sr_in(sr_out),
    .td_in(td_out),
    .and_out()
);

// Output assignments
assign sr_out = shift_reg;
assign td_out = td_out;

endmodule

