module accumulation(
    input               clk         ,
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out
);

reg [7:0]   data_reg [3:0];
reg [9:0]   sum_reg;

reg         valid_reg [3:0];
reg         ready_reg [3:0];

integer     i;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        for (i = 0; i < 4; i = i + 1) begin
            data_reg[i] <= 8'b0;
            valid_reg[i] <= 1'b0;
            ready_reg[i] <= 1'b0;
        end
        sum_reg <= 10'b0;
        valid_b <= 1'b0;
    end else begin
        for (i = 3; i > 0; i = i - 1) begin
            data_reg[i] <= data_reg[i-1];
            valid_reg[i] <= valid_reg[i-1];
            ready_reg[i] <= ready_reg[i-1];
        end
        data_reg[0] <= data_in;
        valid_reg[0] <= valid_a;
        ready_reg[0] <= ready_b;

        if (valid_reg[3] && ready_reg[3]) begin
            sum_reg <= sum_reg + {1'b0, data_reg[3]};
            valid_b <= 1'b1;
            data_out <= sum_reg;
        end else begin
            valid_b <= 1'b0;
        end
    end
end

assign ready_a = ~valid_reg[3] || ~ready_reg[3];

endmodule

