module top_module( 
    input [254:0] in,
    output [7:0] out );

    // Define the pipeline stages
    reg [7:0] stage1 [31:0];
    reg [7:0] stage2 [15:0];
    reg [7:0] stage3 [7:0];
    reg [7:0] stage4;

    // Define the parallel prefix adder
    wire [7:0] ppa0 [127:0];
    wire [7:0] ppa1 [63:0];
    wire [7:0] ppa2 [31:0];
    wire [7:0] ppa3 [15:0];
    wire [7:0] ppa4 [7:0];

    // Split the input vector into smaller chunks
    wire [7:0] chunk0 [31:0];
    wire [7:0] chunk1 [15:0];
    wire [7:0] chunk2 [7:0];

    // Generate the '1' counts for each chunk
    genvar i;
    generate
        for (i = 0; i < 32; i = i + 1) begin : gen_chunk0
            assign chunk0[i] = $countones(in[(i*8)+7:(i*8)]);
        end
        for (i = 0; i < 16; i = i + 1) begin : gen_chunk1
            assign chunk1[i] = ppa0[(i*2)+1];
        end
        for (i = 0; i < 8; i = i + 1) begin : gen_chunk2
            assign chunk2[i] = ppa1[(i*2)+1];
        end
    endgenerate

    // Connect the parallel prefix adder
    genvar j;
    generate
        for (j = 0; j < 128; j = j + 1) begin : gen_ppa0
            assign ppa0[j] = stage1[j*2] + stage1[(j*2)+1];
        end
        for (j = 0; j < 64; j = j + 1) begin : gen_ppa1
            assign ppa1[j] = stage2[j*2] + stage2[(j*2)+1];
        end
        for (j = 0; j < 32; j = j + 1) begin : gen_ppa2
            assign ppa2[j] = stage3[j*2] + stage3[(j*2)+1];
        end
        for (j = 0; j < 16; j = j + 1) begin : gen_ppa3
            assign ppa3[j] = stage4[j*2] + stage4[(j*2)+1];
        end
        for (j = 0; j < 8; j = j + 1) begin : gen_ppa4
            assign ppa4[j] = ppa3[j*2] + ppa3[(j*2)+1];
        end
    endgenerate

    // Define the pipeline stages
    always @(posedge clk) begin
        // Stage 1
        stage1[0] <= chunk0[0];
        stage1[1] <= chunk0[1];
        stage1[2] <= chunk0[2];
        stage1[3] <= chunk0[3];
        stage1[4] <= chunk0[4];
        stage1[5] <= chunk0[5];
        stage1[6] <= chunk0[6];
        stage1[7] <= chunk0[7];
        stage1[8] <= chunk0[8];
        stage1[9] <= chunk0[9];
        stage1[10] <= chunk0[10];
        stage1[11] <= chunk0[11];
        stage1[12] <= chunk0[12];
        stage1[13] <= chunk0[13];
        stage1[14] <= chunk0[14];
        stage1[15] <= chunk0[15];
        stage1[16] <= chunk0[16];
        stage1[17] <= chunk0[17];
        stage1[18] <= chunk0[18];
        stage1[19] <= chunk0[19];
        stage1[20] <= chunk0[20];
        stage1[21] <= chunk0[21];
        stage1[22] <= chunk0[22];
        stage1[23] <= chunk0[23];
        stage1[24] <= chunk0[24];
        stage1[25] <= chunk0[25];
        stage1[26] <= chunk0[26];
        stage1[27] <= chunk0[27];
        stage1[28] <= chunk0[28];
        stage1[29] <= chunk0[29];
        stage1[30] <= chunk0[30];
        stage1[31] <= chunk0[31];

        // Stage 2
        stage2[0] <= ppa0[0];
        stage2[1] <= ppa0[1];
        stage2[2] <= ppa0[2];
        stage2[3] <= ppa0[3];
        stage2[4] <= ppa0[4];
        stage2[5] <= ppa0[5];
        stage2[6] <= ppa0[6];
        stage2[7] <= ppa0[7];
        stage2[8] <= ppa0[8];
        stage2[9] <= ppa0[9];
        stage2[10] <= ppa0[10];
        stage2[11] <= ppa0[11];
        stage2[12] <= ppa0[12];
        stage2[13] <= ppa0[13];
        stage2[14] <= ppa0[14];
        stage2[15] <= ppa0[15];

        // Stage 3
        stage3[0] <= ppa1[0];
        stage3[1] <= ppa1[1];
        stage3[2] <= ppa1[2];
        stage3[3] <= ppa1[3];
        stage3[4] <= ppa1[4];
        stage3[5] <= ppa1[5];
        stage3[6] <= ppa1[6];
        stage3[7] <= ppa1[7];

        // Stage 4
        stage4 <= ppa4[0];
    end

    // Output the final count
    assign out = stage4;

endmodule

