    input debugaccess,
    input monitor_error,
    input monitor_go,
    input monitor_ready,
    input reset_n,
    input write,
    input [31:0] writedata,
    output [31:0] oci_ienable,
    output [31:0] oci_reg_readdata,
    output oci_single_step_mode,
    output ocireg_ers,
    output ocireg_mrs,
    output take_action_ocireg
);

    wire oci_reg_00_addressed = (address == 9'h100);
    wire oci_reg_01_addressed = (address == 9'h101);
    wire write_strobe = write & debugaccess;
    wire take_action_ocireg = write_strobe & oci_reg_00_addressed;
    wire take_action_oci_intr_mask_reg = write_strobe & oci_reg_01_addressed;
    wire ocireg_ers = writedata[1];
    wire ocireg_mrs = writedata[0];
    wire ocireg_sstep = writedata[3];
    wire [31:0] oci_reg_readdata = (oci_reg_00_addressed) ? {28'b0, oci_single_step_mode, monitor_go, monitor_ready, monitor_error} : (oci_reg_01_addressed) ? oci_ienable : 32'b0;

    reg [31:0] oci_ienable;
    reg oci_single_step_mode;

    always @(posedge clk or negedge reset_n) begin
        if (~reset_n) begin
            oci_single_step_mode <= 1'b0;
        end else if (take_action_ocireg) begin
            oci_single_step_mode <= ocireg_sstep;
        end
    end

    always @(posedge clk or negedge reset_n) begin
        if (~reset_n) begin
            oci_ienable <= 32'b00000000000000000000000000001001;
        end else if (take_action_oci_intr_mask_reg) begin
            oci_ienable <= writedata | ~(32'b00000000000000000000000000001001);
        end
    end

endmodule

module maximum
(
	input                     clk      ,
	input                     rst      ,
	input      [31:0]         ain      ,
	input      [31:0]         bin      ,
	output reg [31:0]         result   ,
	output reg [31:0]         statistic 
);

//-------------------------------------------------------------------
// Signal Declaration
//-------------------------------------------------------------------

	reg [31:0] result_last;

//-------------------------------------------------------------------
// Main Computation
//-------------------------------------------------------------------

	/* the result & result_last register */
	always @(posedge clk or posedge rst) begin
		if (rst) begin
			result      <= 32'h0;
			result_last <= 32'h0;
		end else begin
			result      <= (ain > bin)? ain: bin;
			result_last <= result;
		end
	end

	/* the statistic register */
	always @(posedge clk or posedge rst) begin
		if (rst) begin
			statistic[31:16] <= 16'hf00d;
			statistic[15:0]  <= 16'h0;
		end else begin
			if ( result != result_last ) begin
				statistic[15:0] <= statistic[15:0] + 16'h1;
			end
		end
	end

endmodule

module sky130_fd_sc_ls__dlrbp (
    input RESET_B,
    input D,
    input VPWR,
    input VGND,
    input VPB,
    input VNB,
    output Q,
    output Q_N,
    input GATE
);

    wire D_N;
    wire Q_PRE;
    wire Q_N_PRE;

    assign D_N = ~D;

    nand2 #(.NAND2_AS_NOR(1)) nand1 (Q_PRE, D_N, RESET_B);
    nand2 #(.NAND2_AS_NOR(1)) nand2 (Q_PRE, Q_PRE, SET_B);
    nand2 #(.NAND2_AS_NOR(1)) nand3 (Q_N_PRE, D, RESET_B);
    nand2 #(.NAND2_AS_NOR(1)) nand4 (Q_N_PRE, Q_N_PRE, SET_B);

    assign Q = Q_PRE;
    assign Q_N = Q_N_PRE;

endmodule

module dma_controller (
    input clk,
    input rst_n,
    input module_select,
    input write_strobe,
    input [1:0] regsel,
    input [7:0] din,
    output reg [20:0] dma_addr,
    output reg [7:0] dma_wd,
    output reg dma_rnw,
    output reg dma_req,
    output reg zxrd,
    output reg zxwr
);

    // signals for DMA controller
    reg [20:0] dma_addr_next;
    reg [7:0] dma_wd_next;
    reg dma_req_next;
    reg dma_rnw_next;

    // signals for DMA read and write indicators
    reg zxrd_next;
    reg zxwr_next;
    reg zxclr;
    reg [2:0] zxrdtgl;
    reg [2:0] zxwrtgl;
    reg zxoldrd;
    reg zxoldwr;

    // DMA control signals
    reg dma_on;
    reg dma_ack;
    reg dma_done;

    // DMA address parameters
    localparam _HAD = 2'b00;
    localparam _MAD = 2'b01;
    localparam _LAD = 2'b10;
    localparam _CST = 2'b11;

    // control dout bus
    always @*
        case (regsel)
            _HAD: dma_wd_next = {3'b000, dma_addr[20:16]};
            _MAD: dma_wd_next = dma_addr[15:8];
            _LAD: dma_wd_next = dma_addr[7:0];
            _CST: dma_wd_next = {dma_on, 7'bXXXXXXX};
        endcase

    // ports.v write access & dma_addr control
    always @(posedge clk, negedge rst_n)
        if (!rst_n) // async reset
            dma_on <= 1'b0;
        else // posedge clk
            begin
                // dma_on control
                if (module_select && write_strobe && (regsel == _CST))
                    dma_on <= din[7];

                // dma_addr control
                if (dma_ack && dma_on)
                    dma_addr <= dma_addr_next;
                else if (module_select && write_strobe)
                    begin
                        dma_addr_next = dma_addr;
                        if (regsel == _HAD)
                            dma_addr_next[20:16] = din[4:0];
                        else if (regsel == _MAD)
                            dma_addr_next[15:8] = din[7:0];
                        else if (regsel == _LAD)
                            dma_addr_next[7:0] = din[7:0];
                    end
            end

    // dma_zx(read|write)_toggle syncing in and zxrd/zxwr strobes
    always @(posedge clk, negedge rst_n)
        if (!rst_n)
            begin
                zxoldrd <= 1'b0;
                zxoldwr <= 1'b0;
            end
        else //posedge clk
            begin
                if (dma_on)
                    begin
                        if (zxrdtgl[2] != zxrdtgl[1])
                            zxoldrd <= 1'b1;
                        else if (zxclr)
                            zxoldrd <= 1'b0;

                        if (zxwrtgl[2] != zxwrtgl[1])
                            zxoldwr <= 1'b1;
                        else if (zxclr)
                            zxoldwr <= 1'b0;
                    end
                else
                    begin
                        zxoldrd <= 1'b0;
                        zxoldwr <= 1'b0;
                    end
            end

    always @(posedge clk)
        begin
            dma_addr <= dma_addr_next;
            dma_wd <= dma_wd_next;
            dma_rnw <= dma_rnw_next;
            dma_req <= dma_req_next;
            zxrd <= zxrd_next;
            zxwr <= zxwr_next;
            zxrdtgl[2:0] <= {zxrdtgl[1:0], dma_rnw};
            zxwrtgl[2:0] <= {zxwrtgl[1:0], dma_rnw};
        end

    always @(posedge clk)
        begin
            dma_rnw_next = 1'b0;
            dma_req_next = 1'b0;
            zxrd_next = 1'b0;
            zxwr_next = 1'b0;
            if (dma_on)
                begin
                    if (dma_ack)
                        begin
                            dma_addr_next <= dma_addr + 21'd1;
                            dma_wd_next <= dma_rd;
                            dma_rnw_next <= 1'b1;
                            dma_req_next <= 1'b1;
                        end
                    else if (module_select && write_strobe)
                        begin
                            dma_wd_next <= din[7:0];
                            dma_rnw_next <= 1'b1;
                            dma_req_next <= 1'b1;
                        end
                    if (zxrdtgl[2] != zxrdtgl[1])
                        zxrd_next <= 1'b1;
                    if (zxwrtgl[2] != zxwrtgl[1])
                        zxwr_next <= 1'b1;
                end
            if (zxrd_next || zxwr_next)
                zxclr <= 1'b1;
            else
                zxclr <= 1'b0;
        end

endmodule

module ROM_reader(
    input [3:0] address,
    input read,
    input clk,
    output reg [7:0] data_out
);

parameter ROM_SIZE = 16;

reg [7:0] rom [0:ROM_SIZE-1];

initial begin
    rom[0] = 8'h01;
    rom[1] = 8'h02;
    rom[2] = 8'h03;
    rom[3] = 8'h04;
    rom[4] = 8'h05;
    rom[5] = 8'h06;
    rom[6] = 8'h07;
    rom[7] = 8'h08;
    rom[8] = 8'h09;
    rom[9] = 8'h0A;
    rom[10] = 8'h0B;
    rom[11] = 8'h0C;
    rom[12] = 8'h0D;
    rom[13] = 8'h0E;
    rom[14] = 8'h0F;
    rom[15] = 8'h10;
end

always @(posedge clk) begin
    if (read && address < ROM_SIZE) begin
        data_out <= rom[address];
    end
end

endmodule

module forward (
    rt_addr_IDEX, 
    rs_addr_IDEX, 
    rd_addr_EXMEM, 
    rd_addr_MEMWB, 
    regwrite_EXMEM, 
    regwrite_MEMWB, 
    forwardA, 
    forwardB
);

    input [4:0] rt_addr_IDEX;
    input [4:0] rs_addr_IDEX;
    input [4:0] rd_addr_EXMEM;
    input [4:0] rd_addr_MEMWB;
    input regwrite_EXMEM;
    input regwrite_MEMWB;
    output [1:0] forwardA;
    output [1:0] forwardB;

    // Check if the current instruction in the EXMEM pipeline stage writes to a register and the destination register matches the source register of the current instruction in the IDEX pipeline stage
    assign forwardA[1] = (regwrite_EXMEM && (rd_addr_EXMEM == rt_addr_IDEX)) ? 1 : 0;

    // Check if the current instruction in the MEMWB pipeline stage writes to a register and the destination register matches the source register of the current instruction in the IDEX pipeline stage
    assign forwardA[0] = (regwrite_MEMWB && (rd_addr_MEMWB == rt_addr_IDEX)) ? 1 : 0;

    // Check if the current instruction in the EXMEM pipeline stage writes to a register and the destination register matches the second source register of the current instruction in the IDEX pipeline stage
    assign forwardB[1] = (regwrite_EXMEM && (rd_addr_EXMEM == rs_addr_IDEX)) ? 1 : 0;

    // Check if the current instruction in the MEMWB pipeline stage writes to a register and the destination register matches the second source register of the current instruction in the IDEX pipeline stage
    assign forwardB[0] = (regwrite_MEMWB && (rd_addr_MEMWB == rs_addr_IDEX)) ? 1 : 0;

    // Set both forwardA and forwardB to 0 if no forwarding is required
    assign {forwardA, forwardB} = (forwardA[1:0] != 2'b00 || forwardB[1:0] != 2'b00) ? {forwardA, forwardB} : 2'b00;

endmodule

