module up_down_counter(
    input wire clk,        // Clock input
    input wire reset,      // Reset input
    input wire up_down,    // Control input for up or down counting
    output wire [3:0] out  // Counter output
);

    reg [3:0] counter;

    always @(posedge clk) begin
        if (reset) begin
            counter <= 4'b0000;
        end else begin
            if (up_down) begin
                counter <= counter + 1;
            end else begin
                counter <= counter - 1;
            end
        end
    end

    assign out = counter;

endmodule

