endmodule

module top_module(
    input wire clk,                // Clock input
    input wire reset,              // Reset input
    input wire up_down,            // Control input for up or down counting
    input wire [3:0] add_value,    // Fixed value to be added to the counter output
    output wire [3:0] out          // Final output, modified counter output
);

    wire [3:0] counter_out;
    wire [3:0] adder_out;

    up_down_counter udc(
        .clk(clk),
        .reset(reset),
        .up_down(up_down),
        .out(counter_out)
    );

    adder add(
        .a(counter_out),
        .b(add_value),
        .sum(adder_out)
    );

    assign out = adder_out;

endmodule

module address_generator (
  input clk, test_mode, rx_access, rx_burst,
  input [103:0] rx_packet,
  output reg erx_access,
  output reg [103:0] erx_packet
);

  parameter ID = 12'h999;

  reg [31:0] addr_reg;
  wire [31:0] next_addr;
  wire [31:0] mux_addr;

  assign mux_addr = rx_burst ? next_addr : addr_reg + 8;
  assign next_addr = addr_reg + 8;

  always @(posedge clk) begin
    if (rx_access && !test_mode) begin
      erx_access <= 1;
      erx_packet[103:40] <= rx_packet[103:40];
      erx_packet[39:8] <= mux_addr;
      erx_packet[7:0] <= 8'b00000001;
    end else begin
      erx_access <= 0;
      erx_packet <= {rx_packet[103:40], mux_addr, 8'b00000001};
    end

    addr_reg <= mux_addr;
  end

endmodule

module up_down_counter (
    input clk,
    input rst,
    input load,
    input up_down,
    input [2:0] data_in,
    output reg [2:0] count
);

reg [2:0] count_reg1, count_reg2;
reg [1:0] stage;

always @(posedge clk) begin
    if (rst) begin
        count_reg1 <= 3'b0;
        count_reg2 <= 3'b0;
        stage <= 2'b00;
    end
    else begin
        case (stage)
            2'b00: begin
                count_reg1 <= count;
                if (load) begin
                    count_reg2 <= data_in;
                    stage <= 2'b01;
                end
                else if (up_down) begin
                    count_reg2 <= count_reg1 + 3'b1;
                    stage <= 2'b10;
                end
                else begin
                    count_reg2 <= count_reg1 - 3'b1;
                    stage <= 2'b10;
                end
            end
            2'b01: begin
                count_reg2 <= count_reg2;
                stage <= 2'b10;
            end
            2'b10: begin
                count_reg1 <= count_reg2;
                stage <= 2'b00;
            end
        endcase
    end
end

assign count = count_reg1;

endmodule

