module fixed_point_negexp(
    input clk,
    input rst,
    input [31:0] new,
    input [31:0] old,
    input [31:0] Tinv,
    input inp_valid,
    output [31:0] out,
    output out_valid
);

reg [31:0] diff_q, diff_d, t_q, t_d;
reg processing_q, processing_d;

wire [31:0] floatval;
wire floatval_valid;
fixed2float f2f(
    .aclk(clk),
    .s_axis_a_tvalid(processing_q),
    .s_axis_a_tdata(diff_q),
    .m_axis_result_tvalid(floatval_valid),
    .m_axis_result_tdata(floatval)
);

wire [31:0] floatval2_data;
wire floatval2_valid;
floating_point_mult m1(
    .aclk(clk),
    .s_axis_a_tvalid(processing_q),
    .s_axis_a_tdata(t_q),
    .s_axis_b_tvalid(floatval_valid),
    .s_axis_b_tdata(floatval),
    .m_axis_result_tvalid(floatval2_valid),
    .m_axis_result_tdata(floatval2_data)
);

wire [31:0] exp_res;
wire [7:0] exp_debug;
wire exp_res_valid;
negexp negexp(
    .clk(clk),
    .rst(rst),
    .inp(floatval2_data),
    .inp_valid(floatval2_valid),
    .out(exp_res),
    .out_valid(exp_res_valid),
    .debug(exp_debug)
);

wire [31:0] recip_data;
wire recip_valid;
floating_point_reciprocal recip(
    .aclk(clk),
    .s_axis_a_tvalid(exp_res_valid),
    .s_axis_a_tdata(exp_res),
    .m_axis_result_tvalid(recip_valid),
    .m_axis_result_tdata(recip_data)
);

assign out = {8'b0,1'b1,recip_data[22:0]};
assign out_valid = recip_valid;

always @(*) begin
    processing_d = processing_q;
    diff_d = diff_q;
    t_d = t_q;
    if (processing_q) begin
        if (recip_valid) begin
            processing_d = 0;
        end
    end else if (inp_valid) begin
        diff_d = new - old;
        t_d = Tinv;
        processing_d = 1;
    end
end

always @(posedge clk) begin
    t_q <= t_d;
    processing_q <= processing_d;
    diff_q <= diff_d;
end

endmodule

module top_module( 
    input [3:0] in,
    input not_in,
    output out
);

    // Instantiate the logical operation module
    logic_op_module logic_op(
        .in1(in[0]),
        .in2(in[1]),
        .in3(in[2]),
        .in4(in[3]),
        .and_out(and_out),
        .or_out(or_out),
        .xor_out(xor_out)
    );

    // Instantiate the NOT gate module
    not_gate_module not_gate(
        .in(not_in),
        .out(not_out)
    );

    // Instantiate the bitwise AND module
    bitwise_and_module bitwise_and(
        .in1(and_out),
        .in2(or_out),
        .in3(xor_out),
        .in4(not_out),
        .out(out)
    );

    // Declare the signals for the logical operation module outputs
    wire and_out;
    wire or_out;
    wire xor_out;

    // Declare the signal for the NOT gate module output
    wire not_out;

    // Instantiate the logical operation module
    logic_op_module logic_op(
        .in1(in[0]),
        .in2(in[1]),
        .in3(in[2]),
        .in4(in[3]),
        .and_out(and_out),
        .or_out(or_out),
        .xor_out(xor_out)
    );

endmodule


// Logical operation module
module logic_op_module(
    input in1,
    input in2,
    input in3,
    input in4,
    output and_out,
    output or_out,
    output xor_out
);

    // Perform the logical operations
    assign and_out = in1 & in2 & in3 & in4;
    assign or_out = in1 | in2 | in3 | in4;
    assign xor_out = in1 ^ in2 ^ in3 ^ in4;

endmodule


// NOT gate module
module not_gate_module(
    input in,
    output out
);

    // Perform the negation
    assign out = ~in;

endmodule


// Bitwise AND module
module bitwise_and_module(
    input in1,
    input in2,
    input in3,
    input in4,
    output out
);

    // Perform the bitwise AND operation
    assign out = in1 & in2 & in3 & in4;

endmodule

module tmu2_adrgen #(
    parameter fml_depth = 26
) (
    input sys_clk,
    input sys_rst,

    output busy,

    input pipe_stb_i,
    output pipe_ack_o,
    input [10:0] dx_c,
    input [10:0] dy_c,
    input [16:0] tx_c,
    input [16:0] ty_c,

    input [fml_depth-1-1:0] dst_fbuf, /* in 16-bit words */
    input [10:0] dst_hres,
    input [fml_depth-1-1:0] tex_fbuf, /* in 16-bit words */
    input [10:0] tex_hres,

    output pipe_stb_o,
    input pipe_ack_i,
    output [fml_depth-1-1:0] dadr, /* in 16-bit words */
    output [fml_depth-1-1:0] tadra,
    output [fml_depth-1-1:0] tadrb,
    output [fml_depth-1-1:0] tadrc,
    output [fml_depth-1-1:0] tadrd,
    output [5:0] x_frac,
    output [5:0] y_frac
);

/* Arithmetic pipeline. Enable signal is shared to ease usage of hard macros. */

wire pipe_en;

reg valid_1;
reg [fml_depth-1-1:0] dadr_1;
reg [fml_depth-1-1:0] tadra_1;
reg [5:0] x_frac_1;
reg [5:0] y_frac_1;

reg valid_2;
reg [fml_depth-1-1:0] dadr_2;
reg [fml_depth-1-1:0] tadra_2;
reg [5:0] x_frac_2;
reg [5:0] y_frac_2;

reg valid_3;
reg [fml_depth-1-1:0] dadr_3;
reg [fml_depth-1-1:0] tadra_3;
reg [fml_depth-1-1:0] tadrb_3;
reg [fml_depth-1-1:0] tadrc_3;
reg [fml_depth-1-1:0] tadrd_3;
reg [5:0] x_frac_3;
reg [5:0] y_frac_3;

always @(posedge sys_clk) begin
    if(sys_rst) begin
        valid_1 <= 1'b0;
        valid_2 <= 1'b0;
        valid_3 <= 1'b0;
    end else if(pipe_en) begin
        valid_1 <= pipe_stb_i;
        dadr_1 <= dst_fbuf + dst_hres*dy_c + dx_c;
        tadra_1 <= tex_fbuf + tex_hres*ty_c[16:6] + tx_c[16:6];
        x_frac_1 <= tx_c[5:0];
        y_frac_1 <= ty_c[5:0];

        valid_2 <= valid_1;
        dadr_2 <= dadr_1;
        tadra_2 <= tadra_1;
        x_frac_2 <= x_frac_1;
        y_frac_2 <= y_frac_1;

        valid_3 <= valid_2;
        dadr_3 <= dadr_2;
        tadra_3 <= tadra_2;
        tadrb_3 <= tadra_2 + 1'd1;
        tadrc_3 <= tadra_2 + tex_hres;
        tadrd_3 <= tadra_2 + tex_hres + 1'd1;
        x_frac_3 <= x_frac_2;
        y_frac_3 <= y_frac_2;
    end
end

/* Glue logic */

assign pipe_stb_o = valid_3;
assign dadr = dadr_3;
assign tadra = tadra_3;
assign tadrb = tadrb_3;
assign tadrc = tadrc_3;
assign tadrd = tadrd_3;
assign x_frac = x_frac_3;
assign y_frac = y_frac_3;

assign pipe_en = ~valid_3 | pipe_ack_i;
assign pipe_ack_o = ~valid_3 | pipe_ack_i;

assign busy = valid_1 | valid_2 | valid_3;

endmodule

module clb_LUT_FF (input clk, input din, output dout);
