module DirectionController (
    input clk,
    input rst,
    input left,
    input right,
    input up,
    input down,
    output reg [7:0] direction
);

    reg [31:0] clk_cnt;
    reg [3:0] button_last;

    always @(posedge clk or negedge rst) begin
        if (!rst) begin
            clk_cnt <= 0;
            direction <= 8'b0;
            button_last <= 4'b0;
        end else begin
            if (clk_cnt == 5_000_000) begin
                clk_cnt <= 0;
                if (left && !button_last[0]) begin
                    direction <= 8'b0000_0001;
                    button_last <= 4'b0001;
                end else if (right && !button_last[1]) begin
                    direction <= 8'b0000_0010;
                    button_last <= 4'b0010;
                end else if (up && !button_last[2]) begin
                    direction <= 8'b0000_0011;
                    button_last <= 4'b0100;
                end else if (down && !button_last[3]) begin
                    direction <= 8'b0000_0100;
                    button_last <= 4'b1000;
                end else begin
                    direction <= 8'b0;
                end
            end else begin
                clk_cnt <= clk_cnt + 1;
            end
        end
    end
endmodule

module fifo_dual_clock (
  input wr_clk, rd_clk, rst_n,
  input wr_en, rd_en,
  input [31:0] wr_data,
  output [31:0] rd_data,
  output full,
  output empty
);

  // Constants
  localparam ADDR_WIDTH = 5;
  localparam ADDR_DEPTH = 32;

  // Registers
  reg [ADDR_WIDTH-1:0] wr_ptr_reg;
  reg [ADDR_WIDTH-1:0] rd_ptr_reg;
  reg [31:0] mem [0:ADDR_DEPTH-1];
  reg [31:0] rd_data_reg;
  reg full_reg;
  reg empty_reg;

  // Writable pointers
  wire [ADDR_WIDTH-1:0] wr_ptr;
  wire [ADDR_WIDTH-1:0] rd_ptr;

  // Pointers
  assign wr_ptr = wr_ptr_reg;
  assign rd_ptr = rd_ptr_reg;

  // Full/empty flags
  assign full = full_reg;
  assign empty = empty_reg;

  // Write pointer logic
  always @(posedge wr_clk or negedge rst_n) begin
    if (!rst_n) begin
      wr_ptr_reg <= 0;
    end else if (wr_en) begin
      wr_ptr_reg <= (wr_ptr_reg == ADDR_DEPTH-1) ? 0 : wr_ptr_reg + 1;
    end
  end

  // Read pointer logic
  always @(posedge rd_clk or negedge rst_n) begin
    if (!rst_n) begin
      rd_ptr_reg <= 0;
    end else if (rd_en) begin
      rd_ptr_reg <= (rd_ptr_reg == ADDR_DEPTH-1) ? 0 : rd_ptr_reg + 1;
    end
  end

  // Memory write logic
  always @(posedge wr_clk or negedge rst_n) begin
    if (!rst_n) begin
      mem <= 0;
    end else if (wr_en) begin
      mem[wr_ptr_reg] <= wr_data;
    end
  end

  // Memory read logic
  always @(posedge rd_clk or negedge rst_n) begin
    if (!rst_n) begin
      rd_data_reg <= 0;
    end else if (rd_en) begin
      rd_data_reg <= mem[rd_ptr_reg];
    end
  end

  // Full/empty logic
  always @(posedge wr_clk, posedge rd_clk or negedge rst_n) begin
    if (!rst_n) begin
      full_reg <= 0;
      empty_reg <= 1;
    end else begin
      full_reg <= (wr_ptr_reg == rd_ptr_reg) ? 1 : 0;
      empty_reg <= (wr_ptr_reg == rd_ptr_reg) ? 1 : 0;
    end
  end

  // Output data
  assign rd_data = rd_data_reg;

endmodule

