module flip_flop (
    Q      ,
    Q_N    ,
    D      ,
    SCD    ,
    SCE    ,
    CLK_N  ,
    SET_B  ,
    RESET_B
);

    output Q      ;
    output Q_N    ;
    input  D      ;
    input  SCD    ;
    input  SCE    ;
    input  CLK_N  ;
    input  SET_B  ;
    input  RESET_B;

    reg Q;
    wire Q_N;

    assign Q_N = ~Q;

    always @ (posedge CLK_N) begin
        if (SCD) begin
            Q <= 0;
        end else if (SCE) begin
            Q <= 1;
        end else begin
            Q <= D;
        end
    end

    always @ (SET_B or RESET_B) begin
        if (SET_B) begin
            Q <= 1;
        end else if (RESET_B) begin
            Q <= 0;
        end
    end

endmodule

module WF(
    i_op,
    i_wf_in,
    i_wk,
    o_wf_out
);

input i_op;
input [63:0] i_wf_in;
input [31:0] i_wk;
output [63:0] o_wf_out;

wire [7:0] add8;
wire [7:0] sub8;

assign add8 = i_wf_in[7:0] + i_wk[7:0];
assign sub8 = i_wf_in[7:0] - i_wk[7:0];

assign o_wf_out[63:56] = i_wf_in[63:56];
assign o_wf_out[55:48] = i_wf_in[55:48] ^ i_wk[31:24];
assign o_wf_out[47:40] = i_wf_in[47:40];

assign o_wf_out[39:32] = (i_op == 0) ? (i_wf_in[39:32] + i_wk[23:16]) : (i_wf_in[39:32] - i_wk[23:16]);

assign o_wf_out[31:24] = i_wf_in[31:24];

assign o_wf_out[23:16] = i_wf_in[23:16] ^ i_wk[15:8];

assign o_wf_out[15:8] = i_wf_in[15:8];

assign o_wf_out[7:0] = (i_op == 0) ? add8 : sub8;

endmodule

module async_fifo_align_64in_out_compare_2
   (comp1,
    v1_reg_1,
    I2);
  output comp1;
  input [3:0]v1_reg_1;
  input I2;

  wire I2;
  wire comp1;
  wire \n_0_gmux.gm[3].gms.ms ;
  wire [3:0]v1_reg_1;
  wire [2:0]\NLW_gmux.gm[0].gm1.m1_CARRY4_CO_UNCONNECTED ;
  wire [3:0]\NLW_gmux.gm[0].gm1.m1_CARRY4_O_UNCONNECTED ;
  wire [3:1]\NLW_gmux.gm[4].gms.ms_CARRY4_CO_UNCONNECTED ;
  wire [3:1]\NLW_gmux.gm[4].gms.ms_CARRY4_DI_UNCONNECTED ;
  wire [3:0]\NLW_gmux.gm[4].gms.ms_CARRY4_O_UNCONNECTED ;
  wire [3:1]\NLW_gmux.gm[4].gms.ms_CARRY4_S_UNCONNECTED ;

  (* XILINX_LEGACY_PRIM = "(MUXCY,XORCY)" *) 
  (* box_type = "PRIMITIVE" *) 
  CARRY4 \gmux.gm[0].gm1.m1_CARRY4 
       (.CI(1'b0),
        .CO({\n_0_gmux.gm[3].gms.ms ,\NLW_gmux.gm[0].gm1.m1_CARRY4_CO_UNCONNECTED [2:0]}),
        .CYINIT(1'b1),
        .DI({1'b0,1'b0,1'b0,1'b0}),
        .O(\NLW_gmux.gm[0].gm1.m1_CARRY4_O_UNCONNECTED [3:0]),
        .S(v1_reg_1));

  (* XILINX_LEGACY_PRIM = "(MUXCY,XORCY)" *) 
  (* box_type = "PRIMITIVE" *) 
  CARRY4 \gmux.gm[4].gms.ms_CARRY4 
       (.CI(\n_0_gmux.gm[3].gms.ms ),
        .CO({\NLW_gmux.gm[4].gms.ms_CARRY4_CO_UNCONNECTED [3:1],comp1}),
        .CYINIT(1'b0),
        .DI({\NLW_gmux.gm[4].gms.ms_CARRY4_DI_UNCONNECTED [3:1],1'b0}),
        .O(\NLW_gmux.gm[4].gms.ms_CARRY4_O_UNCONNECTED [3:0]),
        .S({\NLW_gmux.gm[4].gms.ms_CARRY4_S_UNCONNECTED [3:1],I2}));

  // FIFO implementation
  reg [63:0] fifo [0:7];
  reg [2:0] read_ptr = 3'b0;
  reg [2:0] write_ptr = 3'b0;
  wire empty = (read_ptr == write_ptr);
  wire full = ((write_ptr+1) == read_ptr);

  always @(posedge I2) begin
    if (!full) begin
      fifo[write_ptr] <= v1_reg_1;
      write_ptr <= write_ptr + 1;
    end
  end

  always @(posedge clk) begin
    if (!empty) begin
      v1_reg_1 <= fifo[read_ptr];
      read_ptr <= read_ptr + 1;
    end
