module can_transmitter (
  input clk,
  input [7:0] data_in,
  input tx_en,
  input bit_rate,
  output reg can_out
);

reg [7:0] data;
reg [2:0] bit_counter;
reg tx_busy;

always @(posedge clk) begin
  if (tx_en && !tx_busy) begin
    data <= data_in;
    bit_counter <= 0;
    tx_busy <= 1;
  end
  if (tx_busy) begin
    if (bit_counter == 0) begin
      can_out <= 0;
    end else if (bit_counter == 9) begin
      can_out <= 1;
    end else if (bit_counter >= 1 && bit_counter <= 8) begin
      can_out <= data[bit_counter-1];
    end
    bit_counter <= bit_counter + 1;
    if (bit_counter == 10) begin
      tx_busy <= 0;
    end
  end
end

endmodule
module can_receiver (
  input clk,
  input can_in,
  input bit_rate,
  output reg [7:0] data_out
);

reg [7:0] data;
reg [2:0] bit_counter;
reg rx_busy;

always @(posedge clk) begin
  if (bit_rate == 0) begin
    bit_counter <= 0;
    rx_busy <= 0;
  end else if (rx_busy) begin
    if (bit_counter >= 1 && bit_counter <= 8) begin
      data[bit_counter-1] <= can_in;
    end
    bit_counter <= bit_counter + 1;
    if (bit_counter == 10) begin
      data_out <= data;
      rx_busy <= 0;
    end
  end else if (!rx_busy && !can_in) begin
    bit_counter <= 1;
    rx_busy <= 1;
  end
end

endmodule

