module fifo_compare
  (comp1,
   v1_reg,
   din,
   din_en,
   dout,
   dout_en,
   clk,
   rst);

  parameter DEPTH = 32768;
  parameter WIDTH = 32;

  output comp1;
  input [4:0]v1_reg;
  input [WIDTH-1:0]din;
  input din_en;
  output [WIDTH-1:0]dout;
  output dout_en;
  input clk;
  input rst;

  reg [WIDTH-1:0]mem [0:DEPTH-1];
  reg [14:0]wr_ptr;
  reg [14:0]rd_ptr;
  reg [31:0]count;
  wire [31:0]next_count;
  wire empty;
  wire full;
  wire match;
  wire [WIDTH-1:0]fifo_out;
  wire [WIDTH-1:0]next_fifo_out;
  wire next_dout_en;
  wire [14:0]next_wr_ptr;
  wire [14:0]next_rd_ptr;

  assign comp1 = match;

  // Empty and full flags
  assign empty = (count == 0);
  assign full = (count == DEPTH);

  // FIFO output and output enable
  assign dout = fifo_out;
  assign dout_en = !empty;

  // Next count
  assign next_count = count + (din_en && !full) - (dout_en && !empty);

  // Next read and write pointers
  assign next_wr_ptr = wr_ptr + din_en && !full;
  assign next_rd_ptr = rd_ptr + dout_en && !empty;

  // Next FIFO output and output enable
  assign next_fifo_out = mem[rd_ptr];
  assign next_dout_en = !empty;

  // Match flag
  assign match = (count > 0) && (mem[rd_ptr] == v1_reg);

  // Write to memory
  always @(posedge clk) begin
    if (rst) begin
      wr_ptr <= 0;
      count <= 0;
    end else if (din_en && !full) begin
      mem[wr_ptr] <= din;
      wr_ptr <= next_wr_ptr;
      count <= next_count;
    end
  end

  // Read from memory
  always @(posedge clk) begin
    if (rst) begin
      rd_ptr <= 0;
    end else if (dout_en && !empty) begin
      rd_ptr <= next_rd_ptr;
      fifo_out <= next_fifo_out;
    end
  end

endmodule

module four_bit_multiplier (
  input [3:0] a,
  input [3:0] b,
  output reg [7:0] product
);

reg [3:0] a_shift;
reg [3:0] b_shift;
reg [3:0] a_shift_reg1;
reg [3:0] a_shift_reg2;
reg [3:0] a_shift_reg3;
reg [3:0] b_shift_reg1;
reg [3:0] b_shift_reg2;
reg [3:0] b_shift_reg3;
wire [3:0] adder1_out;
wire [3:0] adder2_out;
wire [3:0] adder3_out;
wire [3:0] adder4_out;

assign adder1_out = a_shift_reg1 + (b_shift_reg3 << 1);
assign adder2_out = a_shift_reg2 + (b_shift_reg2 << 1);
assign adder3_out = a_shift_reg3 + (b_shift_reg1 << 1);
assign adder4_out = a_shift + (b << 1);

always @(a or b) begin
  a_shift = {a[2:0], 0};
  b_shift = {b[2:0], 0};
end

always @(posedge clk) begin
  a_shift_reg1 <= a_shift_reg2;
  a_shift_reg2 <= a_shift_reg3;
  a_shift_reg3 <= a_shift;
  b_shift_reg1 <= b_shift_reg2;
  b_shift_reg2 <= b_shift_reg3;
  b_shift_reg3 <= b_shift;
end

assign product = {adder4_out, adder3_out[3:0]};

endmodule

module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,
    input       [7:0]   data_b      ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out
);

reg [7:0] acc;
reg [1:0] count;

// Input valid-ready handshake
reg valid_a_reg;
assign ready_a = ~valid_a_reg;
always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        valid_a_reg <= 1'b0;
    end else begin
        valid_a_reg <= valid_a;
    end
end

// Output valid-ready handshake
reg ready_b_reg;
assign valid_b = (count == 2'b11);
always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        ready_b_reg <= 1'b0;
    end else begin
        ready_b_reg <= ready_b;
    end
end

// Data accumulation
adder adder_inst(
    .a(acc),
    .b(data_in),
    .sum(acc)
);

// Data output
always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        data_out <= 10'd0;
    end else begin
        if (count == 2'b11) begin
            data_out <= {8'd0, acc};
        end
    end
end

// Pipeline control
always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        acc <= 8'd0;
        count <= 2'b00;
    end else begin
        if (valid_a_reg && ready_b_reg) begin
            count <= count + 1;
            if (count == 2'b11) begin
                acc <= 8'd0;
            end else begin
                acc <= acc + data_in;
            end
        end
    end
end

endmodule

