module ReedSolomon (
  input [k*log2(m)-1:0] in,
  output [n*log2(m)-1:0] out
);

parameter k = 4; // number of input symbols
parameter n = 8; // number of output symbols
parameter m = 2; // number of possible symbol values
parameter t = 2; // number of errors that can be corrected

// Galois field arithmetic operations
function [log2(m)-1:0] gf_add;
  input [log2(m)-1:0] a, b;
  begin
    gf_add = a ^ b;
  end
endfunction

function [log2(m)-1:0] gf_mul;
  input [log2(m)-1:0] a, b;
  reg [2*log2(m)-1:0] p;
  begin
    p = a + b;
    if (p >= m) p = p - m;
    gf_mul = p;
  end
endfunction

function [log2(m)-1:0] gf_div;
  input [log2(m)-1:0] a, b;
  reg [2*log2(m)-1:0] p;
  begin
    p = a - b;
    if (p < 0) p = p + m;
    gf_div = p;
  end
endfunction

// Generator polynomial
parameter [2*t*log2(m)-1:0] gen_poly = {1'b1, 2'b11, 2'b101, 2'b111, 2'b1101, 2'b1001};

// Syndrome calculation
function [2*t*log2(m)-1:0] syndrome;
  input [n*log2(m)-1:0] received;
  reg [2*t*log2(m)-1:0] s;
  reg [log2(m)-1:0] t;
  integer i, j;
  begin
    for (i = 0; i < 2*t; i = i + 1) begin
      s[i] = received[0];
      for (j = 1; j < n; j = j + 1) begin
        t = gf_mul(received[j], gf_add(1'b0, gf_mul(s[i], gen_poly[i])));
        s[i] = gf_add(s[i], t);
      end
      received = received << log2(m);
    end
    syndrome = s;
  end
endfunction

// Encoder
function [n*log2(m)-1:0] encode;
  input [k*log2(m)-1:0] data;
  reg [n*log2(m)-1:0] encoded;
  integer i, j;
  begin
    for (i = 0; i < k; i = i + 1) begin
      encoded[i] = data[i];
    end
    for (i = k; i < n; i = i + 1) begin
      encoded[i] = 0;
      for (j = 0; j < k; j = j + 1) begin
        encoded[i] = gf_add(encoded[i], gf_mul(data[j], gen_poly[i-k+j]));
      end
    end
    encode = encoded;
  end
endfunction

// Decoder
function [k*log2(m)-1:0] decode;
  input [n*log2(m)-1:0] received;
  reg [k*log2(m)-1:0] decoded;
  reg [2*t*log2(m)-1:0] s;
  reg [2*t*log2(m)-1:0] e;
  reg [log2(m)-1:0] t;
  integer i, j, k;
  begin
    s = syndrome(received);
    for (i = 0; i < k; i = i + 1) begin
      decoded[i] = received[i];
    end
    for (i = 0; i < 2*t; i = i + 1) begin
      if (s[i] != 0) begin
        e[i] = gf_div(s[i], received[n-t+i]);
      end else begin
        e[i] = 0;
      end
    end
    for (i = 0; i < t; i = i + 1) begin
      t = 0;
      for (j = 0; j < n; j = j + 1) begin
        t = gf_add(t, gf_mul(e[i], gf_pow(j, i)));
      end
      decoded[n-t+i] = gf_add(decoded[n-t+i], t);
    end
    decode = decoded;
  end
endfunction

// Connect inputs to encoder and decoder, and compute output symbols
assign out = decode(in) ? decode(in) : encode(in);

endmodule

module fir_filter (
    input  [19:0] a_i,
    input  [17:0] b_i,
    input  [ 3:0] acc_fir_i,
    output [37:0] z_o,
    output [17:0] dly_b_o,
    input         clock_i,
    input         reset_i,
    input  [2:0]  feedback_i,
    input         load_acc_i,
    input         unsigned_a_i,
    input         unsigned_b_i,
    input  [2:0]  output_select_i,
    input         saturate_enable_i,
    input  [5:0]  shift_right_i,
    input         round_i,
    input         subtract_i,
    input         register_inputs_i
);

    parameter [19:0] COEFF_0 = 20'd0;
    parameter [19:0] COEFF_1 = 20'd0;
    parameter [19:0] COEFF_2 = 20'd0;
    parameter [19:0] COEFF_3 = 20'd0;

    reg [19:0] acc_fir;
    reg [17:0] dly_b;
    wire [37:0] z;

    assign z_o = z;
    assign dly_b_o = dly_b;

    always @(posedge clock_i) begin
        if (reset_i) begin
            acc_fir <= acc_fir_i;
            dly_b <= b_i;
        end else begin
            acc_fir <= {a_i, acc_fir[37:20]} * COEFF_0 +
                       {dly_b, a_i, acc_fir[37:18]} * COEFF_1 +
                       {dly_b, dly_b, a_i, acc_fir[37:16]} * COEFF_2 +
                       {dly_b, dly_b, dly_b, a_i, acc_fir[37:14]} * COEFF_3;

            if (load_acc_i) begin
                acc_fir <= acc_fir_i;
            end

            if (feedback_i == 3'b000) begin
                dly_b <= dly_b;
            end else if (feedback_i == 3'b001) begin
                dly_b <= acc_fir[19:2];
            end else if (feedback_i == 3'b010) begin
                dly_b <= acc_fir[18:1];
            end else if (feedback_i == 3'b011) begin
                dly_b <= acc_fir[17:0];
            end else if (feedback_i == 3'b100) begin
                dly_b <= dly_b + acc_fir[19:2];
            end else if (feedback_i == 3'b101) begin
                dly_b <= dly_b + acc_fir[18:1];
            end else if (feedback_i == 3'b110) begin
                dly_b <= dly_b + acc_fir[17:0];
            end else if (feedback_i == 3'b111) begin
                dly_b <= acc_fir[19:0];
            end
        end
    end

    QL_DSP2 # (
        .COEFF_0            (COEFF_0),
        .COEFF_1            (COEFF_1),
        .COEFF_2            (COEFF_2),
        .COEFF_3            (COEFF_3)
    ) _TECHMAP_REPLACE_ (
        .a                  (a_i),
        .b                  (dly_b),
        .acc_fir            (acc_fir),
        .z                  (z),

        .clk                (clock_i),
        .reset              (reset_i),

        .feedback           (feedback_i),
        .load_acc           (load_acc_i),
        .unsigned_a         (unsigned_a_i),
        .unsigned_b         (unsigned_b_i),

        .f_mode             (1'b0), // No fracturation
        .output_select      (output_select_i),
        .saturate_enable    (saturate_enable_i),
        .shift_right        (shift_right_i),
        .round              (round_i),
        .subtract           (subtract_i),
        .register_inputs    (register_inputs_i)
    );

endmodule

module I2C_Sensor_Interface (
  input Reset_n_i,
  input Clk_i,
  input Enable_i,
  output CpuIntr_o,
  output I2C_ReceiveSend_n_o,
  output [7:0] I2C_ReadCount_o,
  output I2C_StartProcess_o,
  input I2C_Busy_i,
  output I2C_FIFOReadNext_o,
  output I2C_FIFOWrite_o,
  output [7:0] I2C_Data_o,
  input [7:0] I2C_Data_i,
  input I2C_Error_i,
  input [15:0] PeriodCounterPresetH_i,
  input [15:0] PeriodCounterPresetL_i,
  output [15:0] SensorValueL_o,
  output [15:0] SensorValueR_o
);

  // I2C FSM signals
  wire       I2CFSM_QueryLocal_s;
  wire       I2CFSM_QueryRemote_s;
  wire       I2CFSM_Done_s;
  wire       I2CFSM_Error_s;
  wire [7:0] I2CFSM_Byte0_s;
  wire [7:0] I2CFSM_Byte1_s;

  // I2C FSM instantiation
  I2CFSM I2CFSM_1 (
    .Reset_n_i              (Reset_n_i),
    .Clk_i                  (Clk_i),
    // FSM control
    .QueryLocal_i           (I2CFSM_QueryLocal_s),
    .QueryRemote_i          (I2CFSM_QueryRemote_s),
    .Done_o                 (I2CFSM_Done_s),
    .Error_o                (I2CFSM_Error_s),
    .Byte0_o                (I2CFSM_Byte0_s),
    .Byte1_o                (I2CFSM_Byte1_s),
    // to/from I2C_Master 
    // I2C control
    .I2C_ReceiveSend_n_o    (I2C_ReceiveSend_n_o),
    .I2C_ReadCount_o        (I2C_ReadCount_o),
    .I2C_StartProcess_o     (I2C_StartProcess_o),
    .I2C_Busy_i             (I2C_Busy_i),
    // I2C FIFO
    .I2C_FIFOReadNext_o     (I2C_FIFOReadNext_o),
    .I2C_FIFOWrite_o        (I2C_FIFOWrite_o),
    .I2C_Data_o             (I2C_Data_o),
    .I2C_Data_i             (I2C_Data_i),
    // I2C error
    .I2C_Error_i            (I2C_Error_i)
  );

  // Sensor FSM signals
  reg [15:0] SensorValueL_s;
  reg [15:0] SensorValueR_s;
  wire       MeasureFSM_QueryLocal_o;
  wire       MeasureFSM_QueryRemote_o;
  wire       MeasureFSM_Done_i;
  wire       MeasureFSM_Error_i;
  wire [7:0] MeasureFSM_Byte0_i;
  wire [7:0] MeasureFSM_Byte1_i;

  // Sensor FSM instantiation
  SensorFSM #(
    .DataWidth               (16)
  ) SensorFSM_1 (
    .Reset_n_i               (Reset_n_i),
    .Clk_i                   (Clk_i),
    .Enable_i                (Enable_i),
    .CpuIntr_o               (CpuIntr_o),
    .SensorValueL_o          (SensorValueL_s),
    .SensorValueR_o          (SensorValueR_s),
    .MeasureFSM_QueryLocal_o (MeasureFSM_QueryLocal_o),
    .MeasureFSM_QueryRemote_o(MeasureFSM_QueryRemote_o),
    .MeasureFSM_Done_i       (MeasureFSM_Done_i),
    .MeasureFSM_Error_i      (MeasureFSM_Error_i),
    .MeasureFSM_Byte0_i      (MeasureFSM_Byte0_i),
    .MeasureFSM_Byte1_i      (MeasureFSM_Byte1_i),
    // parameters
    .ParamCounterPresetH_i  (PeriodCounterPresetH_i),
    .ParamCounterPresetL_i  (PeriodCounterPresetL_i)
  );

  // Output SensorValues
  assign SensorValueL_o = SensorValueL_s;
  assign SensorValueR_o = SensorValueR_s;

  // Read SensorValues from I2C bus
  always @(posedge Clk_i) begin
    if (MeasureFSM_Done_i) begin
      SensorValueL_s <= {I2CFSM_Byte0_s, I2CFSM_Byte1_s};
      SensorValueR_s <= {I2CFSM_Byte1_s, I2CFSM_Byte0_s};
    end
  end

  // Write to Sensor via I2C bus
  always @(posedge Clk_i) begin
    if (I2CFSM_Done_s && I2CFSM_QueryRemote_s && !I2CFSM_QueryLocal_s) begin
      I2CFSM_Byte0_s <= 8'h00; // Address of configuration register
      I2CFSM_Byte1_s <= 8'h00; // Configuration value
      I2C_FIFOWrite_o <= 1'b1;
    end
  end

endmodule

