module sync_ram_wf_x32 (/*AUTOARG*/
   // Outputs
   dout,
   // Inputs
   clk, web, enb, addr, din
   );
   parameter ADDR_WIDTH = 10;

   input clk;
   input [3:0]web;
   input [3:0]enb;
   input [ADDR_WIDTH-1:0] addr;
   input [31:0] din;
   output [31:0] dout;
   reg [31:0]    RAM [(2<<ADDR_WIDTH)-1:0];
   reg [31:0]    dout;

   always @(posedge clk)
     begin
        if (enb[0])
          begin
             if (web[0])
               begin
                  RAM[addr][7:0] <= din[7:0];
                  dout[7:0] <= din[7:0];
               end
             else begin
                dout[7:0] <= RAM[addr][7:0];
             end
          end
     end // always @ (posedge clk)
   always @(posedge clk)
     begin
        if (enb[1])
          begin
             if (web[1])
               begin
                  RAM[addr][15:8] <= din[15:8];
                  dout[15:8] <= din[15:8];
               end
             else begin
                dout[15:8] <= RAM[addr][15:8];
             end
          end
     end // always @ (posedge clk)

   always @(posedge clk)
     begin
        if (enb[2])
          begin
             if (web[2])
               begin
                  RAM[addr][23:16] <= din[23:16];
                  dout[23:16] <= din[23:16];
               end
             else begin
                dout[23:16] <= RAM[addr][23:16];
             end
          end
     end

   always @(posedge clk)
     begin
        if (enb[3])
          begin
             if (web[3])
               begin
                  RAM[addr][31:24] <= din[31:24];
                  dout[31:24] <= din[31:24];
               end
             else begin
                dout[31:24] <= RAM[addr][31:24];
             end
          end
     end

endmodule

module temp_humidity_monitor(
    input [5:0] BTN,
    input clk,
    output reg [7:0] LED,
    output reg [7:0] SevenSegment,
    output reg [2:0] SevenSegment_Enable,
    output reg IO_P1_1,
    output reg IO_P1_3,
    inout [0:0] IO_P1_5
);

    // DHT11 sensor inputs
    wire dht11_dat;
    wire [9:0] humid;
    wire [9:0] temp;
    wire [3:0] status;

    // Debounce input buttons
    wire inc_n_debounced;
    wire btn2_n_debounced;
    wire btn6_debounced;

    // Counter for BTN[0]
    reg [3:0] counter;

    // Auto-capture mode
    reg auto_capture;
    reg [3:0] auto_capture_counter;
    reg auto_capture_start;
    reg auto_capture_rst_n;

    // BCD conversion
    wire [3:0] HUNDREDS;
    wire [3:0] TENS;
    wire [3:0] ONES;
    wire [3:0] data0a;
    wire [3:0] data1a;
    wire [3:0] data2a;
    wire [3:0] data0b;
    wire [3:0] data1b;
    wire [3:0] data2b;

    // Clock dividers
    wire clk_div_1Hz;
    wire clk_div_1MHZ;
    wire clk_div_1kHZ;

    // State machine for seven-segment display
    reg [1:0] state_func;
    wire select_onehot;

    // Debounce input buttons
    debounce debounce_inc(clk_div_1kHZ, BTN[0], inc_n_debounced);
    debounce debounce_start(clk_div_1kHZ, BTN[1], btn2_n_debounced);
    debounce debounce_dht11_rst(clk_div_1kHZ, BTN[5], btn6_debounced);

    // Counter for BTN[0]
    new_counter theNewCounter(clk_div_1kHZ, inc_n_debounced, counter);

    // Auto-capture mode
    always @(posedge clk_div_1kHZ or negedge rst_n) begin
        if (~rst_n) begin
            auto_capture_counter <= 4'b0;
            auto_capture_start <= 1'b0;
        end else begin
            auto_capture_counter <= auto_capture_counter + 1;
            if (auto_capture_counter[2:0] == 3'b111) begin
                auto_capture_start <= 1'b1;
            end else begin
                auto_capture_start <= 1'b0;
            end
        end
    end

    // BCD conversion
    BINARY_TO_BCD theBinary2BCDhumid(humid, data2a, data1a, data0a);
    BINARY_TO_BCD theBinary2BCDtemp(temp, data2b, data1b, data0b);
    BINARY_TO_BCD theBinary2BCD(counter, HUNDREDS, TENS, ONES);

    // Clock dividers
    freqdiv freqdiv1(clk, BTN[4], clk_div_1Hz, 2'b01);
    freqdiv freqdiv2(clk, BTN[4], clk_div_1MHZ, 2'b00);
    freqdiv freqdiv3(clk, BTN[4], clk_div_1kHZ, 2'b10);

    // State machine for seven-segment display
    always @(posedge clk or negedge rst_debounced) begin
        if (~rst_debounced) begin
            state_func <= 2'b0;
            auto_capture <= 1'b0;
        end else begin
            if (select_onehot == 1'b1) begin
                state_func <= state_func + 1;
            end
            case (state_func)
                2'b0: begin
                    SevenSegment_Enable <= 3'b111;
                    SevenSegment <= {4'b1111, ONES};
                    LED <= {4'b1111, counter[3:0]};
                    auto_capture <= 1'b0;
                end
                2'b1: begin
                    SevenSegment_Enable <= 3'b110;
                    SevenSegment <= {4'b1111, TENS};
                    LED <= {4'b1111, btn2_n_debounced};
                    auto_capture <= 1'b0;
                end
                2'b10: begin
                    SevenSegment_Enable <= 3'b101;
                    SevenSegment <= {4'b1111, HUNDREDS};
                    LED <= {4'b1111, inc_n_debounced};
                    auto_capture <= 1'b0;
                end
                2'b11: begin
                    SevenSegment_Enable <= 3'b011;
                    SevenSegment <= {data2a, data1a, data0a};
                    LED <= {4'b1111, status};
                    auto_capture <= auto_capture ? auto_capture_start : btn2_n_debounced;
                end
            endcase
        end
    end

    // Blink least significant digit of seven-segment display
    always @(posedge clk_div_1Hz or negedge rst_n) begin
        if (~rst_n) begin
            SevenSegment[0] <= 1'b0;
        end else begin
            SevenSegment[0] <= ~SevenSegment[0];
        end
    end

    // Output temperature and humidity data
    always @(posedge clk_div_1kHZ or negedge rst_n) begin
        if (~rst_n) begin
            IO_P1_1 <= 1'b0;
            IO_P1_3 <= 1'b1;
            IO_P1_5 <= 1'bz;
        end else begin
            IO_P1_1 <= temp[7];
            IO_P1_3 <= humid[7];
            IO_P1_5 <= dht11_dat;
        end
    end

    // Read data from DHT11 sensor
    dht11_driver dht11_driver(clk_div_1MHZ, btn6_debounced, auto_capture_start, dht11_dat, humid[7:0], temp[7:0], status);

endmodule

module math_module(a_in, b_in, c_in, d_in, e_in, f_in, out0, out1, out2, out3, out4);
  parameter BITS = 8;
  parameter B2TS = BITS*2;
  parameter B2TS_MINUS_1 = B2TS-1;
  parameter BITS_MINUS_1 = BITS-1;
  parameter BITS_MINUS_2 = BITS-2;
  parameter BITS_MINUS_3 = BITS-3;

  input [BITS_MINUS_1:0] a_in;
  input [BITS_MINUS_1:0] b_in;
  input [BITS_MINUS_1:0] c_in;
  input [BITS_MINUS_1:0] d_in;
  input [BITS_MINUS_1:0] e_in;
  input [BITS_MINUS_2:0] f_in;

  output [B2TS_MINUS_1:0] out0;
  output [B2TS_MINUS_1:0] out1;
  output [B2TS_MINUS_1:0] out2;
  output [14:0] out3;
  output [14:0] out4;

  assign out1 = c_in * d_in;
  assign out4 = f_in * e_in;

  wire [BITS_MINUS_1:0] temp_a;
  wire [BITS_MINUS_1:0] temp_b;
  wire temp_c;
  wire temp_d;

  assign temp_c = a_in[7] & b_in[7];
  assign temp_d = a_in[6] & b_in[6];

  assign out2 = {temp_d, temp_c} & {a_in[5:0], b_in[5:0]};

  assign out3 = e_in * {{1{1'b0}}, f_in};

  assign out0 = {a_in, b_in} * {{1{1'b0}}, {1'b0, 1'b0, f_in}};

endmodule

