module right_barrel_shifter(
	input [7:0] d_in,
	input [2:0] shift_amount,
	output reg [7:0] d_out
);

always @* begin
	case (shift_amount)
		0 : d_out = d_in;
		1 : d_out = {d_in[0], d_in[7:1]};
		2 : d_out = {d_in[1:0], d_in[7:2]};
		3 : d_out = {d_in[2:0], d_in[7:3]};
		4 : d_out = {d_in[3:0], d_in[7:4]};
		5 : d_out = {d_in[4:0], d_in[7:5]};
		6 : d_out = {d_in[5:0], d_in[7:6]};
		7 : d_out = 0;
	endcase
end 

endmodule

module transition_detector (
    input clk,
    input reset,
    input [31:0] in,
    output [31:0] out
);

reg [31:0] in_reg1, in_reg2, in_reg3, in_reg4;
reg [31:0] out_reg1, out_reg2, out_reg3, out_reg4;

always @(posedge clk or negedge reset) begin
    if (reset == 0) begin
        in_reg1 <= 0;
        in_reg2 <= 0;
        in_reg3 <= 0;
        in_reg4 <= 0;
        out_reg1 <= 0;
        out_reg2 <= 0;
        out_reg3 <= 0;
        out_reg4 <= 0;
    end
    else begin
        in_reg1 <= in;
        in_reg2 <= in_reg1;
        in_reg3 <= in_reg2;
        in_reg4 <= in_reg3;

        if (in_reg4 == 32'hFFFFFFFF) begin
            out_reg1 <= 0;
            out_reg2 <= 0;
            out_reg3 <= 0;
            out_reg4 <= 0;
        end
        else if (in_reg4 == 32'hFFFFFFFE) begin
            out_reg1 <= 1;
            out_reg2 <= 1;
            out_reg3 <= 1;
            out_reg4 <= 1;
        end
        else begin
            out_reg1 <= out_reg2;
            out_reg2 <= out_reg3;
            out_reg3 <= out_reg4;
            out_reg4 <= 0;
        end
    end
end

assign out = out_reg1;

endmodule

