module Adder (
    input [3:0] A,
    input [3:0] B,
    output [3:0] Y
);

    wire [3:0] c;
    wire [3:0] s;

    // First full adder
    full_adder FA0 (
        .a(A[0]),
        .b(B[0]),
        .c_in(1'b0),
        .s(s[0]),
        .c(c[0])
    );

    // Second full adder
    full_adder FA1 (
        .a(A[1]),
        .b(B[1]),
        .c_in(c[0]),
        .s(s[1]),
        .c(c[1])
    );

    // Third full adder
    full_adder FA2 (
        .a(A[2]),
        .b(B[2]),
        .c_in(c[1]),
        .s(s[2]),
        .c(c[2])
    );

    // Fourth full adder
    full_adder FA3 (
        .a(A[3]),
        .b(B[3]),
        .c_in(c[2]),
        .s(s[3]),
        .c(c[3])
    );

    assign Y = s;

endmodule

module full_adder (
    input a,
    input b,
    input c_in,
    output s,
    output c
);

    assign s = a ^ b ^ c_in;
    assign c = (a & b) | (c_in & (a ^ b));

endmodule

module subtract5(
   input [3:0] input_num,
   output [3:0] output_num
);

wire [4:0] five_minus_input;
assign five_minus_input = 5'd5 - {1'b0, input_num};

assign output_num = (five_minus_input[4] == 1) ? 4'b0 : five_minus_input[3:0];

endmodule

