module up_counter (
  input clk,
  input reset,
  output reg [3:0] count
);

  reg [3:0] next_count;

  always @(posedge clk) begin
    if (reset) begin
      next_count <= 4'b0000;
    end
    else begin
      next_count <= count + 1;
    end
  end

  assign count = next_count;

endmodule

module counter (
  input clk,
  input reset,
  input en,
  output reg [3:0] count
);

  always @(posedge clk) begin
    if (reset) count <= 4'b0;
    else if (en) count <= count + 1;
  end

endmodule

