module reduction (
  input [1:0] in,
  output rand,
  output ror,
  output rxor,
  output rnand,
  output rnor,
  output rxnor
);

  wire [1:0] in_inv;
  assign in_inv = ~in;

  assign rand = &in;
  assign ror = |in;
  assign rxor = ^in;
  assign rnand = ~&in;
  assign rnor = ~|in;
  assign rxnor = ~^in;

endmodule

module top;
  reg passed;
  integer lp;
  wire [1:0] in;
  wire rand;
  wire ror;
  wire rxor;
  wire rnand;
  wire rnor;
  wire rxnor;

  reduction reduction_inst (
    .in(in),
    .rand(rand),
    .ror(ror),
    .rxor(rxor),
    .rnand(rnand),
    .rnor(rnor),
    .rxnor(rxnor)
  );

  initial begin
    passed = 1'b1;

    for (lp=0; lp < 4 ; lp = lp + 1) begin
      case (lp)
        0: in = 2'b00;
        1: in = 2'b11;
        2: in = 2'bzx;
        3: in = 2'bxx;
      endcase

      #1;

      // Check the normal reductions.
      if (rand !== &in) begin
        $display("FAILED CA reduction & with input %b, expected %b, got %b",
                 in, &in, rand);
        passed = 1'b0;
      end

      if (ror !== |in) begin
        $display("FAILED CA reduction | with input %b, expected %b, got %b",
                 in, |in, ror);
        passed = 1'b0;
      end

      if (rxor !== ^in) begin
        $display("FAILED CA reduction ^ with input %b, expected %b, got %b",
                 in, ^in, rxor);
        passed = 1'b0;
      end

      // Check the inverted reductions.
      if (rnand !== ~(in[0] & in[1])) begin
        $display("FAILED CA reduction ~& with input %b, expected %b, got %b",
                 in, ~(in[0] & in[1]), rnand);
        passed = 1'b0;
      end

      if (rnor !== ~(in[0] | in[1])) begin
        $display("FAILED CA reduction ~| with input %b, expected %b, got %b",
                 in, ~(in[0] | in[1]), rnor);
        passed = 1'b0;
      end

      if (rxnor !== ~(in[0] ^ in[1])) begin
        $display("FAILED CA reduction ~^ with input %b, expected %b, got %b",
                 in, ~(in[0] ^ in[1]), rxnor);
        passed = 1'b0;
      end
    end

    if (passed) $display("PASSED");
  end
endmodule

module edge_detection (
  input clk,
  input rst_n,
  input data,
  output reg rising_edge,
  output reg falling_edge
);

  reg last_data;

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      rising_edge <= 0;
      falling_edge <= 0;
      last_data <= 0;
    end else begin
      if (data && !last_data) begin
        rising_edge <= 1;
      end else begin
        rising_edge <= 0;
      end

      if (!data && last_data) begin
        falling_edge <= 1;
      end else begin
        falling_edge <= 0;
      end

      last_data <= data;
    end
  end

endmodule

module mux (
  input [2:0] select,
  input [7:0] data0,
  input [7:0] data1,
  input [7:0] data2,
  input [7:0] data3,
  input [7:0] data4,
  input [7:0] data5,
  output reg [7:0] selected_data
);

  always @* begin
    case (select)
      3'b000: selected_data = data0;
      3'b001: selected_data = data1;
      3'b010: selected_data = data2;
      3'b011: selected_data = data3;
      3'b100: selected_data = data4;
      3'b101: selected_data = data5;
      default: selected_data = 8'h00;
    endcase
  end

endmodule

module binary_adder (
  input clk,
  input rst_n,
  input rising_edge,
  input falling_edge,
  input [2:0] select,
  input [7:0] data0,
  input [7:0] data1,
  input [7:0] data2,
  input [7:0] data3,
  input [7:0] data4,
  input [7:0] data5,
  output reg [7:0] result
);

  reg [7:0] selected_data;
  reg [7:0] last_data;
  reg [7:0] sum;

  edge_detection edge_detector (
    .clk(clk),
    .rst_n(rst_n),
    .data(data),
    .rising_edge(rising_edge),
    .falling_edge(falling_edge)
  );

  mux data_mux (
    .select(select),
    .data0(data0),
    .data1(data1),
    .data2(data2),
    .data3(data3),
    .data4(data4),
    .data5(data5),
    .selected_data(selected_data)
  );

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      result <= 8'h00;
      last_data <= 8'h00;
      sum <= 8'h00;
    end else begin
      if (rising_edge || falling_edge) begin
        sum <= selected_data + last_data;
        result <= sum;
      end

      last_data <= selected_data;
    end
  end

endmodule

