module debouncer (
  input in,
  output out
);

parameter debounce_time = 100; // debounce time in clock cycles (change as needed)
parameter clock_period = 10; // clock period in nanoseconds (change as needed)

reg [debounce_time-1:0] debounce_counter;
reg out_reg;
reg in_last;

always @(posedge clk) begin
  if (in_last == 1'b0 && in == 1'b1) begin // detect rising edge
    debounce_counter <= debounce_time;
  end else if (debounce_counter > 0) begin // debounce time
    debounce_counter <= debounce_counter - 1;
  end else if (in == 1'b1) begin // set output
    out_reg <= 1'b1;
  end else begin // reset
    out_reg <= 1'b0;
  end
  in_last <= in;
end

assign out = out_reg;

endmodule

module BCD7segment(
    input [3:0] IN,
    input select,
    output reg [6:0] OUT
);

always @ (IN or select) begin
    if (select) begin
        case (IN)
            0: OUT = 7'b0000001;
            1: OUT = 7'b1001111;
            2: OUT = 7'b0010010;
            3: OUT = 7'b0000110;
            4: OUT = 7'b1001100;
            5: OUT = 7'b0100100;
            6: OUT = 7'b0100000;
            7: OUT = 7'b0001111;
            8: OUT = 7'b0000000;
            9: OUT = 7'b0000100;
            10: OUT = 7'b0001000;
            11: OUT = 7'b0000000;
            12: OUT = 7'b0110001;
            13: OUT = 7'b0000001;
            14: OUT = 7'b0110000;
            15: OUT = 7'b0111000;
            default: OUT = 7'b1111111; // Invalid input
        endcase
    end
    else begin
        OUT = 7'b1111110; // Turn off all segments
    end
end

// 4 enable switches //

endmodule

module two_bit_adder(
    input A, 
    input B, 
    input Cin, 
    output S, 
    output Cout
);

    wire w1, w2, w3;

    assign w1 = A ^ B;
    assign S = w1 ^ Cin;
    assign w2 = A & B;
    assign w3 = Cin & w1;
    assign Cout = w2 | w3;

endmodule

