module top_module (
    input wire clk,
    input wire reset,
    input wire [15:0] in,
    output reg [7:0] final_output
);

reg [7:0] upper_byte;
reg [7:0] lower_byte;
wire [7:0] xor_output;

// Instantiate module 1
module1 module1_inst (
    .clk(clk),
    .reset(reset),
    .in(in),
    .upper_byte(upper_byte),
    .lower_byte(lower_byte)
);

// Instantiate module 2
module2 module2_inst (
    .in1(upper_byte),
    .in2(lower_byte),
    .out(xor_output)
);

// XOR the lower byte of the input with the output of module 2
always @ (posedge clk) begin
    final_output <= xor_output ^ lower_byte;
end

endmodule

// Module 1 - Split 16-bit binary number into upper and lower bytes
module module1 (
    input wire clk,
    input wire reset,
    input wire [15:0] in,
    output reg [7:0] upper_byte,
    output reg [7:0] lower_byte
);

reg [7:0] temp_upper_byte;
reg [7:0] temp_lower_byte;

always @ (posedge clk) begin
    if (reset) begin
        temp_upper_byte <= 8'b0;
        temp_lower_byte <= 8'b0;
    end else begin
        temp_upper_byte <= in[15:8];
        temp_lower_byte <= in[7:0];
    end
end

assign upper_byte = temp_upper_byte;
assign lower_byte = temp_lower_byte;

endmodule

// Module 2 - XOR gate
module module2 (
    input wire [7:0] in1,
    input wire [7:0] in2,
    output reg [7:0] out
);

always @ (in1, in2) begin
    out <= in1 ^ in2;
end

endmodule

