module up_counter_sync (din, clk, rst, load, q);
  parameter SIZE = 4; // counter size

  input clk, rst, load;
  input [SIZE-1:0] din;
  output [SIZE-1:0] q;

  reg [SIZE-1:0] q_next; // next value of counter
  reg [SIZE-1:0] q_reg; // current value of counter

  always @ (posedge clk) begin
    if (rst) begin // reset
      q_reg <= 0;
    end else if (load) begin // load
      q_reg <= din;
    end else begin // increment
      q_reg <= q_next;
    end
  end

  always @ (*) begin
    q_next = q_reg + 1;
  end

  assign q = q_reg;
endmodule

module shift_register(
    input clk,
    input areset,
    input [7:0] d,
    output reg [7:0] s
);

reg [7:0] shift_reg;
reg [2:0] sel;

always @(posedge clk) begin
    if (areset) begin
        shift_reg <= 8'b0;
        sel <= 3'b000;
    end else begin
        shift_reg <= {shift_reg[6:0], d[0]};
        sel <= {sel[1:0], 1'b0};
    end
end

always @(*) begin
    case (sel)
        3'b000: s = shift_reg;
        3'b001: s = {4'b0, shift_reg[7:4]};
        default: s = 8'b0;
    endcase
end

endmodule

