    input [3:0] B,
    input sign,
    output [3:0] sum
);

    wire [3:0] A_mag;
    wire [3:0] B_mag;
    wire carry_in;
    wire carry_out;

    assign A_mag = (sign == 1) ? (~A + 1) : A;
    assign B_mag = (sign == 1) ? (~B + 1) : B;

    assign carry_in = (sign == 1) ? 1 : 0;

    full_adder fa0(A_mag[0], B_mag[0], carry_in, sum[0], carry_out);
    full_adder fa1(A_mag[1], B_mag[1], carry_out, sum[1], carry_out);
    full_adder fa2(A_mag[2], B_mag[2], carry_out, sum[2], carry_out);
