);

    reg [7:0] binary_product;

    binary_multiplier multiplier(.A(A), .B(B), .product(binary_product));
    set_bit_counter counter(.binary_number(binary_product), .set_bits(set_bits));

    always @(posedge clk) begin
        if (reset) begin
            product <= 0;
            set_bits <= 0;
        end else begin
            if (select == 1) begin
                product <= binary_product[3:0];
                set_bits <= set_bits;
            end else begin
                product <= product;
