module carry_select_adder (
    input [31:0] a, // 32-bit input A
    input [31:0] b, // 32-bit input B
    output reg [31:0] sum // 32-bit sum output
);

    wire [31:0] carry_out;
    wire [31:0] carry_in;

    // Generate carry chain
    generate
        genvar i;
        for (i = 0; i < 32; i = i + 4) begin : carry_chain
            carry_select_adder_unit adder_unit (
                .a(a[i+3:i]),
                .b(b[i+3:i]),
                .sum(sum[i+3:i]),
                .carry_out(carry_out[i+3:i]),
                .carry_in(carry_in[i])
            );
        end
    endgenerate

    // Generate final carry select adder
    carry_select_adder_final adder_final (
        .a(a),
        .b(b),
        .sum(sum),
        .carry_out(carry_out),
        .carry_in(carry_in)
    );

endmodule

module carry_select_adder_unit (
    input [3:0] a, // 4-bit input A
    input [3:0] b, // 4-bit input B
    output reg [3:0] sum, // 4-bit sum output
    output reg [3:0] carry_out, // 4-bit carry out output
    input carry_in // 1-bit carry in input
);

    assign carry_out = (a[3] & b[3]) | (a[3] & carry_in) | (b[3] & carry_in);
    assign sum = a + b + carry_in;

endmodule

module carry_select_adder_final (
    input [31:0] a, // 32-bit input A
    input [31:0] b, // 32-bit input B
    output reg [31:0] sum, // 32-bit sum output
    output reg [31:0] carry_out, // 32-bit carry out output
    input [31:0] carry_in // 32-bit carry in input
);

    wire [31:0] carry_out_0;
    wire [31:0] carry_out_1;

    // Generate carry select signals
    assign carry_out_0 = {31{1'b0}} | ((a | b) & ~carry_in);
    assign carry_out_1 = a & b;

    // Generate carry select adder
    assign sum = a + b + carry_in;
    assign carry_out = {carry_out_1[31], carry_out_1[31:1] | carry_out_0[31:1]};

endmodule

