module jtag__stateBit(next, phi1, phi2, rst, master, slave, slaveBar);
  input next;
  input phi1;
  input phi2;
  input rst;
  output master;
  output slave;
  output slaveBar;

  wire [2:0] state;
  wire [2:0] next_state;
  wire [2:0] master_out;

  assign master = master_out[state];
  assign slave = ~slaveBar;
  assign slaveBar = ~slave;

  always @(posedge phi1 or posedge rst) begin
    if (rst) begin
      state <= 3'b000;
    end else begin
      state <= next_state;
    end
  end

  always @(posedge phi2) begin
    master_out <= state;
  end

  always @* begin
    case(state)
      3'b000: next_state = next[0] ? 3'b001 : 3'b000;
      3'b001: next_state = next[1] ? 3'b010 : 3'b000;
      3'b010: next_state = next[2] ? 3'b011 : 3'b000;
      3'b011: next_state = next[0] ? 3'b100 : 3'b000;
      3'b100: next_state = next[1] ? 3'b101 : 3'b000;
      3'b101: next_state = next[2] ? 3'b110 : 3'b000;
      3'b110: next_state = next[0] ? 3'b111 : 3'b000;
      3'b111: next_state = next[0] ? 3'b001 : 3'b000;
      default: next_state = 3'b000;
    endcase
  end
endmodule

module four_to_one (
    input in1,
    input in2,
    input in3,
