// Adder module
module adder_module (
    input [7:0] a,
    input [7:0] b,
    output reg [7:0] s
);

    // Internal wires for the carry look-ahead adder
    wire [7:0] g;
    wire [7:0] p;
    wire [7:0] c;

    // Generate the carry and sum bits using the carry look-ahead adder
    genvar i;
    generate
        for (i = 0; i < 8; i = i + 1) begin : gen
            assign g[i] = a[i] & b[i];
            assign p[i] = a[i] ^ b[i];
            assign c[i] = {i{1'b0}} | (g[i] & {i{1'b1}}) | (p[i] & c[i-1]);
            assign s[i] = a[i] ^ b[i] ^ c[i-1];
        end
    endgenerate

endmodule

