module pipelined_booth_multiplier (
    input [15:0] a,
    input [15:0] b,
    output [31:0] result
);

    wire [15:0] a_reg, b_reg;
    wire [31:0] partial_product1, partial_product2, partial_product3, partial_product4;
    wire [31:0] sum1, sum2, sum3, sum4;
    wire [15:0] booth_encoder_out;
    wire [3:0] booth_decoder_out;

    reg [15:0] a_reg_ff, b_reg_ff;
    reg [31:0] partial_product1_ff, partial_product2_ff, partial_product3_ff, partial_product4_ff;
    reg [31:0] sum1_ff, sum2_ff, sum3_ff, sum4_ff;
    reg [15:0] booth_encoder_out_ff;
    reg [3:0] booth_decoder_out_ff;

    reg [3:0] state;

    reg [15:0] register_file [0:3];

    assign a_reg = (state == 0) ? a : a_reg_ff;
    assign b_reg = (state == 0) ? b : b_reg_ff;

    assign partial_product1 = (state == 1) ? {a_reg, 2'b01} : partial_product1_ff;
    assign partial_product2 = (state == 2) ? {a_reg, 2'b10} : partial_product2_ff;
    assign partial_product3 = (state == 3) ? {a_reg, 2'b00} : partial_product3_ff;
    assign partial_product4 = (state == 4) ? {a_reg, 2'b01} : partial_product4_ff;

    assign booth_encoder_out = (state == 0) ? {a_reg[15], a_reg[14:0], 1'b0} : booth_encoder_out_ff;

    assign booth_decoder_out = (state == 1) ? 4'b1000 :
                               (state == 2) ? 4'b0100 :
                               (state == 3) ? 4'b0010 :
                                              4'b0001 ;

    assign sum1 = (state == 1) ? {partial_product1[31], partial_product1[30:16] + register_file[booth_decoder_out[3]]} : sum1_ff;
    assign sum2 = (state == 2) ? {partial_product2[31], partial_product2[30:16] + register_file[booth_decoder_out[2]]} : sum2_ff;
    assign sum3 = (state == 3) ? {partial_product3[31], partial_product3[30:16] + register_file[booth_decoder_out[1]]} : sum3_ff;
    assign sum4 = (state == 4) ? {partial_product4[31], partial_product4[30:16] + register_file[booth_decoder_out[0]]} : sum4_ff;

    always @(posedge clk) begin
        if (rst) begin
            a_reg_ff <= 16'b0;
            b_reg_ff <= 16'b0;
            partial_product1_ff <= 32'b0;
            partial_product2_ff <= 32'b0;
            partial_product3_ff <= 32'b0;
            partial_product4_ff <= 32'b0;
            sum1_ff <= 32'b0;
            sum2_ff <= 32'b0;
            sum3_ff <= 32'b0;
            sum4_ff <= 32'b0;
            booth_encoder_out_ff <= 16'b0;
            booth_decoder_out_ff <= 4'b0000;
            state <= 0;
            register_file <= {16'b0, 16'b0, 16'b0, 16'b0};
        end else begin
            a_reg_ff <= a_reg;
            b_reg_ff <= b_reg;
            partial_product1_ff <= partial_product1;
            partial_product2_ff <= partial_product2;
            partial_product3_ff <= partial_product3;
            partial_product4_ff <= partial_product4;
            sum1_ff <= sum1;
            sum2_ff <= sum2;
            sum3_ff <= sum3;
            sum4_ff <= sum4;
            booth_encoder_out_ff <= booth_encoder_out;
            booth_decoder_out_ff <= booth_decoder_out;
            case (state)
                0: begin
                       state <= 1;
                   end
                1: begin
                       register_file[booth_decoder_out[3]] <= sum1[15:0];
                       state <= 2;
                   end
                2: begin
                       register_file[booth_decoder_out[2]] <= sum2[15:0];
                       state <= 3;
                   end
                3: begin
                       register_file[booth_decoder_out[1]] <= sum3[15:0];
                       state <= 4;
                   end
                4: begin
                       register_file[booth_decoder_out[0]] <= sum4[15:0];
                       result <= {sum4[31], sum4[30:16]};
                       state <= 0;
                   end
                default: begin
                             state <= 0;
                         end
            endcase
        end
    end
