  assign C_next[4] = A[3] & B[3] | A[2] & B[2] | A[1] & B[1] | A[0] & B[0] | C_reg[3] & (A[3] | B[3] | A[2] | B[2] | A[1] | B[1] | A[0] | B[0]);

