module edge_detect (
  input               clk,
  input               rst_n,
  input               a,
  output reg          rise,
  output reg          down
);

  // Define the states of the state machine
  localparam IDLE = 2'b00;
  localparam RISING = 2'b01;
  localparam FALLING = 2'b10;

  // Define the current state variable
  reg [1:0] state;

  // Define the previous value of the input signal
  reg prev_a;

  // Initialize the state and output signals
  initial begin
    state = IDLE;
    rise = 1'b0;
    down = 1'b0;
  end

  // Detect edges on the rising edge of the clock
  always @(posedge clk) begin
    // Reset the state machine on a low active reset signal
    if (!rst_n) begin
      state <= IDLE;
      rise <= 1'b0;
      down <= 1'b0;
    end
    else begin
      // Check for a rising edge
      if ((a == 1'b1) && (prev_a == 1'b0)) begin
        state <= RISING;
        rise <= 1'b1;
      end
      // Check for a falling edge
      else if ((a == 1'b0) && (prev_a == 1'b1)) begin
        state <= FALLING;
        down <= 1'b1;
      end
      // Stay in the current state otherwise
      else begin
        state <= state;
        rise <= 1'b0;
        down <= 1'b0;
      end
      // Save the current value of the input signal
      prev_a <= a;
    end
  end

endmodule

module up_down_counter_bcd (
    input Up,
    input Down,
    input Clk,
    input reset,
    output reg [3:0] Count,
    output reg [3:0] BCD1,
    output reg [3:0] BCD0,
    output reg [7:0] BCD_output
);

reg [3:0] BCD_count;

// Up/Down Counter
always @(posedge Clk or posedge reset) begin
    if (reset) begin
        Count <= 4'b0000;
    end else if (Up) begin
        Count <= Count + 1;
    end else if (Down) begin
        Count <= Count - 1;
    end
end

// Binary to BCD Converter
always @(Count) begin
    case (Count)
        4'b0000: begin
            BCD_count = 4'b0000;
        end
        4'b0001: begin
            BCD_count = 4'b0001;
        end
        4'b0010: begin
            BCD_count = 4'b0010;
        end
        4'b0011: begin
            BCD_count = 4'b0011;
        end
        4'b0100: begin
            BCD_count = 4'b0100;
        end
        4'b0101: begin
            BCD_count = 4'b0101;
        end
        4'b0110: begin
            BCD_count = 4'b0110;
        end
        4'b0111: begin
            BCD_count = 4'b0111;
        end
        4'b1000: begin
            BCD_count = 4'b1000;
        end
        4'b1001: begin
            BCD_count = 4'b1001;
        end
        4'b1010: begin
            BCD_count = 4'b0001;
            BCD1 = 4'b0001;
        end
        4'b1011: begin
            BCD_count = 4'b0001;
            BCD1 = 4'b0001;
            BCD0 = 4'b0001;
        end
        4'b1100: begin
            BCD_count = 4'b0001;
            BCD0 = 4'b0001;
        end
        4'b1101: begin
            BCD_count = 4'b0010;
        end
        4'b1110: begin
            BCD_count = 4'b0011;
        end
        4'b1111: begin
            BCD_count = 4'b0100;
        end
    endcase
end

// BCD Output
always @(BCD1, BCD0) begin
    BCD_output = {BCD1, BCD0, BCD_count};
end

endmodule

