module VCO_interface (
  input vctrl,
  input clk,
  output reg vco_out
);

parameter freq_min = 1000; // minimum frequency of the output signal
parameter freq_max = 2000; // maximum frequency of the output signal
parameter resolution = 8; // resolution of the output signal
parameter clock_frequency = 100000000; // frequency of the clock signal

reg [resolution-1:0] count;
reg toggle;

assign freq_out = vctrl * (freq_max - freq_min) / (2**resolution) + freq_min;

always @(posedge clk) begin
  count <= count + 1;
  if (count == (clock_frequency / (2 * freq_out))) begin
    toggle <= ~toggle;
    count <= 0;
  end
end

always @(posedge clk) begin
  if (toggle) begin
    vco_out <= 1;
  end else begin
    vco_out <= 0;
  end
end

endmodule

module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    output [3:0] OUT
);

reg [3:0] sum [0:1];
reg [3:0] carry [0:2];

// First stage
assign sum[0] = A + B;
assign carry[0] = A[0] & B[0];

// Second stage
assign sum[1] = sum[0] + carry[0];
assign carry[1] = sum[0][1] & carry[0];

// Third stage
assign OUT = sum[1] + carry[1];
assign carry[2] = sum[1][2] & carry[1];

// Fourth stage
assign OUT = OUT + carry[2];

endmodule

