module zero_counter(
    input clk,
    input reset,
    input [254:0] in,
    output [7:0] out
);

reg [7:0] count;
reg [254:0] shift_reg;
wire [7:0] sum;
wire [7:0] threshold = 8'b01111111;

always @(posedge clk) begin
    if (reset) begin
        count <= 8'b0;
        shift_reg <= {255{1'b0}};
    end else begin
        shift_reg <= {shift_reg[253:0], in[0]};
        sum <= count + (~shift_reg[0] + 1);
        if (sum >= threshold) begin
            count <= threshold - sum;
        end else begin
            count <= sum;
        end
    end
end

assign out = count;

endmodule

