// 32-bit carry look-ahead adder module
module CLA_32bit(
    input [15:0] a,
    input [15:0] b,
    input cin,
    output [31:0] sum,
    output cout
);

    wire [3:0] g;
    wire [3:0] p;
    wire [3:0] c;

    assign g[0] = a[0] & b[0];
    assign p[0] = a[0] ^ b[0];
    assign c[0] = cin;

    genvar i;
    generate
        for (i = 1; i < 16; i = i + 1) begin : gen
            assign g[i] = a[i] & b[i];
            assign p[i] = a[i] ^ b[i];
            assign c[i] = g[i-1] | (p[i-1] & c[i-1]);
        end
    endgenerate

    assign sum = {c[15], c[14], c[13], c[12], c[11], c[10], c[9], c[8], c[7], c[6], c[5], c[4], c[3], c[2], c[1], c[0], p[15], p[14], p[13], p[12], p[11], p[10], p[9], p[8], p[7], p[6], p[5], p[4], p[3], p[2], p[1], p[0]};
    assign cout = g[15] | (p[15] & c[15]);

endmodule

