      3'h5: begin
        data_out_r[31:24] <= data_r[7:0];
        audio_busy_r <= 1'b1;
      end
      3'h6: busy_r <= 1'b1;
      3'h7: begin
        if(!audio_busy_r) begin
          audio_status <= data_r[1:0];
          busy_r <= 1'b1;
        end
      end
      default: error_r <= 1'b1;
    endcase
  end else if(audio_re) begin
    addr_r <= audio_addr;
    data_out_r <= 8'h00;
    case(reg_addr)
      3'h0: data_out_r[1:0] <= status_r[0:1];
      3'h1: data_out_r[3:2] <= status_r[2:3];
      3'h2: data_out_r[7:0] <= data_r[7:0];
      3'h3: begin
        data_out_r[15:8] <= data_r[7:0];
        audio_busy_r <= 1'b1;
      end
      3'h4: data_out_r[23:16] <= data_r[7:0];
      3'h5: begin
        data_out_r[31:24] <= data_r[7:0];
        audio_busy_r <= 1'b1;
      end
      3'h6: data_out_r[7:0] <= busy_r;
      3'h7: data_out_r[1:0] <= audio_status;
      default: error_r <= 1'b1;
    endcase
  end else begin
    addr_r <= 14'h0000;
    data_r <= 8'h00;
    status_r <= 2'h0;
    error_r <= 1'b0;
    data_out_r <= 8'h00;
    busy_r <= 1'b0;
    audio_busy_r <= 1'b0;
    audio_status <= 2'h0;
  end
end

assign audio_data_out = data_out_r;
assign busy = busy_r;
assign audio_busy = audio_busy_r;
assign audio_error = error_r;

always @(posedge clk) begin
  if(audio_we | audio_re) begin
    case(reg_addr)
      3'h0: reg_data_out[1:0] <= status_r[0:1];
      3'h1: reg_data_out[3:2] <= status_r[2:3];
      3'h2: reg_data_out[7:0] <= data_r[7:0];
      3'h3: reg_data_out[15:8] <= data_r[7:0];
      3'h4: reg_data_out[23:16] <= data_r[7:0];
      3'h5: reg_data_out[31:24] <= data_r[7:0];
      3'h6: reg_data_out[7:0] <= busy_r;
      3'h7: reg_data_out[1:0] <= audio_status;
      default: reg_data_out <= 8'h00;
    endcase
  end else begin
    reg_data_out <= 8'h00;
  end
end

endmodule

