module clkgen (
    input sys_clk_pad_i,
    input rst_n_pad_i,
    output async_rst_o,
    output wb_clk_o,
    output wb_rst_o,
    output tx_clk_o,
    output sdram_clk_o,
    output sdram_rst_o,
    input tck_pad_i,
    output dbg_tck_o
);

    // First, deal with the asynchronous reset
    wire async_rst;
    wire async_rst_n;
    assign async_rst_n = rst_n_pad_i;
    assign async_rst = ~async_rst_n;
    assign async_rst_o = ~async_rst_n;

    // Declare synchronous reset wires here
    wire sync_rst_n;
    wire pll_lock;

    // Generate clock signals
    // SDRAM clock
    reg [1:0] sdram_divider;
    always @(posedge sys_clk_pad_i or posedge async_rst)
        if (async_rst)
            sdram_divider <= 2'b11;
        else
            sdram_divider <= sdram_divider + 1;

    assign sdram_clk_o = sdram_divider[1];

    // Wishbone clock
    reg [1:0] wb_divider;
    always @(posedge sys_clk_pad_i or posedge async_rst)
        if (async_rst)
            wb_divider <= 2'b11;
        else
            wb_divider <= wb_divider + 1;

    assign wb_clk_o = wb_divider[1];

    // TX clock
    reg [2:0] tx_divider;
    always @(posedge sys_clk_pad_i or posedge async_rst)
        if (async_rst)
            tx_divider <= 3'b111;
        else
            tx_divider <= tx_divider + 1;

    assign tx_clk_o = tx_divider[2];

    // JTAG clock
    `ifdef SIM
    assign dbg_tck_o = tck_pad_i;
    `endif

    // Generate reset signals
    // Wishbone reset
    reg [15:0] wb_rst_shr;
    always @(posedge wb_clk_o or posedge async_rst)
        if (async_rst)
            wb_rst_shr <= 16'hffff;
        else
            wb_rst_shr <= {wb_rst_shr[14:0], ~(sync_rst_n)};

    assign wb_rst_o = wb_rst_shr[15];

    // SDRAM reset
    reg [15:0] sdram_rst_shr;
    always @(posedge sdram_clk_o or posedge async_rst)
        if (async_rst)
            sdram_rst_shr <= 16'hffff;
        else
            sdram_rst_shr <= {sdram_rst_shr[14:0], ~(sync_rst_n)};

    assign sdram_rst_o = sdram_rst_shr[15];

    // Generate synchronous reset signal
    // Active-low synchronous reset signal (usually a PLL lock signal)
    pll pll0 (
        .areset (async_rst),
        .inclk0 (sys_clk_pad_i),
        .c0 (sdram_clk_o),
        .c1 (wb_clk_o),
        .c2 (tx_clk_o),
        .locked (pll_lock)
    );

    assign sync_rst_n = pll_lock;

endmodule

module data_to_ascii #
(
parameter WIDTH = 24,       // Word length in bits. MUST be a multiply of 4
parameter COUNT = 2,        // Word count
parameter TX_INTERVAL = 4   // Character transmission interval
)
(
// Clock and reset
input  wire CLK,
input  wire RST,

// Data input
input  wire I_STB,
input  wire [(WIDTH*COUNT)-1:0] I_DAT,

// ASCII output
output wire O_STB,
output wire [7:0] O_DAT
);

// ============================================================================

// Total input data word width
localparam TOTAL_WIDTH = WIDTH * COUNT;

// ============================================================================
// FSM states
integer fsm;

localparam FSM_IDLE     = 'h00;
localparam FSM_TX_HEX   = 'h11;
localparam FSM_TX_CR    = 'h21;
localparam FSM_TX_LF    = 'h22;
localparam FSM_TX_SEP   = 'h31;

// ============================================================================
// TX interval counter
reg [24:0]  tx_dly_cnt;
reg         tx_req;
wire        tx_rdy;

always @(posedge CLK)
    if (RST)
        tx_dly_cnt <= -1;
    else if (!tx_rdy)
        tx_dly_cnt <= tx_dly_cnt  - 1;
    else if ( tx_rdy && tx_req)
        tx_dly_cnt <= TX_INTERVAL - 2;

assign tx_rdy = tx_dly_cnt[24];

always @(posedge CLK)
    if (RST)
        tx_req <= 1'b0;
    else case (fsm)

    FSM_TX_HEX: tx_req <= 1'b1;
    FSM_TX_SEP: tx_req <= 1'b1;
    FSM_TX_CR:  tx_req <= 1'b1;
    FSM_TX_LF:  tx_req <= 1'b1;

    default:    tx_req <= 1'b0;

    endcase

// ============================================================================
// Word and char counter
reg  [7:0] char_cnt;
reg  [7:0] word_cnt;

always @(posedge CLK)
    if (fsm == FSM_IDLE || fsm == FSM_TX_SEP)
        char_cnt <= (WIDTH/4) - 1;
    else if (tx_rdy && fsm == FSM_TX_HEX)
        char_cnt <= char_cnt - 1;

always @(posedge CLK)
    if (fsm == FSM_IDLE)
        word_cnt <= COUNT - 1;
    else if (tx_rdy && fsm == FSM_TX_SEP)
        word_cnt <= word_cnt - 1;

// ============================================================================
// Data shift register
reg  [TOTAL_WIDTH-1:0] sr_reg;
wire [3:0] sr_dat;

always @(posedge CLK)
    if (fsm == FSM_IDLE && I_STB)
        sr_reg <= I_DAT;
    else if (fsm == FSM_TX_HEX && tx_rdy)
        sr_reg <= sr_reg << 4;

assign sr_dat = sr_reg[TOTAL_WIDTH-1:TOTAL_WIDTH-4];

// ============================================================================
// Control FSM
always @(posedge CLK)
    if (RST)
        fsm <= FSM_IDLE;
    else case (fsm)

    FSM_IDLE:   if (I_STB) fsm <= FSM_TX_HEX;

    FSM_TX_HEX:
                if (tx_rdy && (char_cnt == 0) && (word_cnt == 0))
                    fsm <= FSM_TX_CR;
                else if (tx_rdy && (char_cnt == 0)) fsm <= FSM_TX_SEP;
                else if (tx_rdy && (char_cnt != 0)) fsm <= FSM_TX_HEX;

    FSM_TX_SEP: if (tx_rdy) fsm <= FSM_TX_HEX;
    FSM_TX_CR:  if (tx_rdy) fsm <= FSM_TX_LF;
    FSM_TX_LF:  if (tx_rdy) fsm <= FSM_IDLE;

    endcase

// ============================================================================
// Data to ASCII converter
reg        o_stb;
reg  [7:0] o_dat;

always @(posedge CLK or posedge RST)
    if (RST)
        o_stb <= 1'd0;
    else
        o_stb <= tx_req & tx_rdy;

always @(posedge CLK)
    if      (fsm == FSM_TX_CR)
        o_dat <= 8'h0D;
    else if (fsm == FSM_TX_LF)
        o_dat <= 8'h0A;
    else if (fsm == FSM_TX_SEP)
        o_dat <= "_";
    else if (fsm == FSM_TX_HEX) case (sr_dat)
        4'h0: o_dat <= "0";
        4'h1: o_dat <= "1";
        4'h2: o_dat <= "2";
        4'h3: o_dat <= "3";
        4'h4: o_dat <= "4";
        4'h5: o_dat <= "5";
        4'h6: o_dat <= "6";
        4'h7: o_dat <= "7";
        4'h8: o_dat <= "8";
        4'h9: o_dat <= "9";
        4'hA: o_dat <= "A";
        4'hB: o_dat <= "B";
        4'hC: o_dat <= "C";
        4'hD: o_dat <= "D";
        4'hE: o_dat <= "E";
        4'hF: o_dat <= "F";
    endcase

assign O_STB = o_stb;
assign O_DAT = o_dat;

endmodule

module fifo_2x2 (
  input clk,
  input reset_n,
  input wr,
  input [31:0] wr_data,
  input rd,
  output [31:0] rd_data,
  output empty,
  output full
);

  reg [31:0] buffer [1:0];
  reg [1:0] wr_ptr = 2'b00;
  reg [1:0] rd_ptr = 2'b00;
  reg [1:0] next_wr_ptr;
  reg [1:0] next_rd_ptr;
  reg full_reg;
  reg empty_reg;

  assign empty = empty_reg;
  assign full = full_reg;
  assign rd_data = buffer[rd_ptr];

  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      wr_ptr <= 2'b00;
      rd_ptr <= 2'b00;
      full_reg <= 1'b0;
      empty_reg <= 1'b1;
    end else begin
      next_wr_ptr = wr_ptr + 2'b01;
      next_rd_ptr = rd_ptr + 2'b01;
      if (wr & !full_reg) begin
        buffer[wr_ptr] <= wr_data;
        wr_ptr <= next_wr_ptr;
        if (next_wr_ptr == rd_ptr) begin
          full_reg <= 1'b1;
        end
        empty_reg <= 1'b0;
      end else if (rd & !empty_reg) begin
        rd_ptr <= next_rd_ptr;
        if (next_rd_ptr == wr_ptr) begin
          empty_reg <= 1'b1;
        end
        full_reg <= 1'b0;
      end
    end
  end

endmodule

module mux_4to1(
    input A, B, C, D,
    input S0, S1,
    output Y
);

wire w1, w2, w3;

// First level of multiplexing
assign w1 = (S0 == 0 && S1 == 0) ? A : B;
assign w2 = (S0 == 1 && S1 == 0) ? C : D;

// Second level of multiplexing
assign w3 = (S1 == 1) ? w2 : w1;

// Output
assign Y = w3;

endmodule

module SHA (
  input [511:0] in,
  output reg [255:0] out
);

  reg [255:0] hash_value;

  // Internal signals for SHA-256 algorithm
  reg [31:0] a, b, c, d, e, f, g, h;
  reg [31:0] k[63:0];
  reg [31:0] w[63:0];
  reg [31:0] t1, t2;
  integer i;

  // Constants for SHA-256 algorithm
  initial begin
    k[0] = 32'h428a2f98; k[1] = 32'h71374491; k[2] = 32'hb5c0fbcf; k[3] = 32'he9b5dba5;
    k[4] = 32'h3956c25b; k[5] = 32'h59f111f1; k[6] = 32'h923f82a4; k[7] = 32'hab1c5ed5;
    k[8] = 32'hd807aa98; k[9] = 32'h12835b01; k[10] = 32'h243185be; k[11] = 32'h550c7dc3;
    k[12] = 32'h72be5d74; k[13] = 32'h80deb1fe; k[14] = 32'h9bdc06a7; k[15] = 32'hc19bf174;
    k[16] = 32'he49b69c1; k[17] = 32'hefbe4786; k[18] = 32'h0fc19dc6; k[19] = 32'h240ca1cc;
    k[20] = 32'h2de92c6f; k[21] = 32'h4a7484aa; k[22] = 32'h5cb0a9dc; k[23] = 32'h76f988da;
    k[24] = 32'h983e5152; k[25] = 32'ha831c66d; k[26] = 32'hb00327c8; k[27] = 32'hbf597fc7;
    k[28] = 32'hc6e00bf3; k[29] = 32'hd5a79147; k[30] = 32'h06ca6351; k[31] = 32'h14292967;
    k[32] = 32'h27b70a85; k[33] = 32'h2e1b2138; k[34] = 32'h4d2c6dfc; k[35] = 32'h53380d13;
    k[36] = 32'h650a7354; k[37] = 32'h766a0abb; k[38] = 32'h81c2c92e; k[39] = 32'h92722c85;
    k[40] = 32'ha2bfe8a1; k[41] = 32'ha81a664b; k[42] = 32'hc24b8b70; k[43] = 32'hc76c51a3;
    k[44] = 32'hd192e819; k[45] = 32'hd6990624; k[46] = 32'hf40e3585; k[47] = 32'h106aa070;
    k[48] = 32'h19a4c116; k[49] = 32'h1e376c08; k[50] = 32'h2748774c; k[51] = 32'h34b0bcb5;
    k[52] = 32'h391c0cb3; k[53] = 32'h4ed8aa4a; k[54] = 32'h5b9cca4f; k[55] = 32'h682e6ff3;
    k[56] = 32'h748f82ee; k[57] = 32'h78a5636f; k[58] = 32'h84c87814; k[59] = 32'h8cc70208;
    k[60] = 32'h90befffa; k[61] = 32'ha4506ceb; k[62] = 32'hbef9a3f7; k[63] = 32'hc67178f2;
  end

  // Functions for SHA-256 algorithm
  function [31:0] Ch;
    input [31:0] x, y, z;
    begin
      Ch = (x & y) ^ (~x & z);
    end
  endfunction

  function [31:0] Maj;
    input [31:0] x, y, z;
    begin
      Maj = (x & y) ^ (x & z) ^ (y & z);
    end
  endfunction

  function [31:0] Sigma0;
    input [31:0] x;
    begin
      Sigma0 = (x >> 2) ^ (x >> 13) ^ (x >> 22);
    end
  endfunction

  function [31:0] Sigma1;
    input [31:0] x;
    begin
      Sigma1 = (x >> 6) ^ (x >> 11) ^ (x >> 25);
    end
  endfunction

  function [31:0] sigma0;
    input [31:0] x;
    begin
      sigma0 = (x >> 7) ^ (x >> 18) ^ (x >>> 3);
    end
  endfunction

  function [31:0] sigma1;
    input [31:0] x;
    begin
      sigma1 = (x >> 17) ^ (x >> 19) ^ (x >>> 10);
    end
  endfunction

  // SHA-256 algorithm
  always @(in) begin
    // Initialize working variables
    a = 32'h6a09e667;
    b = 32'hbb67ae85;
    c = 32'h3c6ef372;
    d = 32'ha54ff53a;
    e = 32'h510e527f;
    f = 32'h9b05688c;
    g = 32'h1f83d9ab;
    h = 32'h5be0cd19;

    // Process input message
    for (i = 0; i < 16; i = i + 1) begin
      w[i] = in[511 - 32 * i -: 32];
    end

    for (i = 16; i < 64; i = i + 1) begin
      w[i] = sigma1(w[i - 2]) + w[i - 7] + sigma0(w[i - 15]) + w[i - 16];
    end

    // Main loop
    for (i = 0; i < 64; i = i + 1) begin
      t1 = h + Sigma1(e) + Ch(e, f, g) + k[i] + w[i];
      t2 = Sigma0(a) + Maj(a, b, c);
      h = g;
      g = f;
      f = e;
      e = d + t1;
      d = c;
      c = b;
      b = a;
      a = t1 + t2;
    end

    // Update hash value
    hash_value[31:0] = a + 32'h6a09e667;
    hash_value[63:32] = b + 32'hbb67ae85;
    hash_value[95:64] = c + 32'h3c6ef372;
    hash_value[127:96] = d + 32'ha54ff53a;
    hash_value[159:128] = e + 32'h510e527f;
    hash_value[191:160] = f + 32'h9b05688c;
    hash_value[223:192] = g + 32'h1f83d9ab;
    hash_value[255:224] = h + 32'h5be0cd19;

    // Output hash value
    out = hash_value;
  end

endmodule

module shift_register (
    input [3:0] data,
    input shift,
    input load,
    output [3:0] shifted_data
);

reg [3:0] register;

always @ (posedge shift or posedge load)
begin
    if (load) // Load input is high
        register <= data;
    else if (shift) // Shift input is high
        register <= {register[2:0], register[3]};
end

assign shifted_data = register;

endmodule

module SoundCtrlChannel2 (
  input wire iClock, // CPU CLOCK, 4194304Hz
  input wire iReset,
  input wire iOsc64, // OSC1 clock 64Hz
  input wire iOsc256, // OSC1 clock 256Hz    
  input wire iOsc262k, // OSC2 clock 131072Hz
  input wire [7:0] iNR21,
  input wire [7:0] iNR22,
  input wire [7:0] iNR23,
  input wire [7:0] iNR24,            
  output reg [4:0] oOut, 
  output wire oOnFlag    
);

  reg [5:0] rLength;
  reg [19:0] rLengthCounter;  
  reg [1:0] rDutyCycle;
  reg rTimedMode;
  reg rLengthComplete; // Channel disable.
  reg rTone;
  reg [10:0] rSoundFrequency;
  reg [10:0] rSoundFrequencyCounter;
  reg [3:0] rStep;
  reg [18:0] rStepTime;
  reg [18:0] rStepCounter;
  reg [3:0] rInitialValue;
  reg rEvelopeMode;
  wire [4:0] up_value, down_value;

  // Register load
  always @(posedge iClock) begin
    if (iReset || iNR24[7]) begin // Register reload and counters restart.
      rLength         <= iNR21[5:0];
      rLengthCounter  <= 64-iNR21[5:0]; // Decrements to zero then load rLength.
      rLengthComplete <= 0;      // Disables channel when is asserted.
      rDutyCycle      <= iNR21[7:6];
      rTimedMode <= iNR24[6];
      rStepTime       <= iNR22[2:0];
      rStepCounter    <= iNR22[2:0]; // Decrements to zero then load rStepTime.
      rEvelopeMode    <= iNR22[3];
      rInitialValue   <= iNR22[7:4];
      rStep           <= iNR22[7:4];
      rTone           <= 0;
      rSoundFrequency[7:0] <= iNR23[7:0];
      rSoundFrequency[10:8] <= iNR24[2:0];
      rSoundFrequencyCounter <= 2048-{iNR24[2:0],iNR23[7:0]}; 
    end
  end

  // Step generator: generates the output amplitude value. 
  always @(posedge iOsc64) begin
    if (rStepTime != 0) begin // Check if channel is enabled.
      if (rStepCounter == 1) begin
        rStepCounter <= rStepTime; // Reset counter.
        if (rEvelopeMode) begin // Envelope mode.
          rStep <= ((rStep == 4'hF) ? rStep : rStep+1); // INCREASES ONLY IF STEP IF LOWER THAN TOP VALUE
        end
        else begin
          rStep <= ((rStep == 4'h0) ? rStep : rStep-1); // DECREASES ONLY IF STEP IF LOWER THAN BOTTOM VALUE
        end
      end
      else begin
        rStepCounter <= rStepCounter-1;
      end   
    end
  end

  // Tone generator: generates the frequency of the output.
  always @(posedge iOsc262k) begin
    if (rSoundFrequencyCounter == 0) begin
      rSoundFrequencyCounter <= 2048-rSoundFrequency;
      rTone <= ~rTone;
    end
    else begin
      rSoundFrequencyCounter <= rSoundFrequencyCounter-1;
    end
  end

  // Timer: enable or disable channel output.
  always @(posedge iOsc256) begin
    if (rLengthCounter == 0) begin
      rLengthCounter <= 64-rLength;
      rLengthComplete <= rTimedMode; // Disable channel only if timer is enabled.
    end
    else begin
      rLengthCounter <= rLengthCounter-1;
    end
  end

  // Re-map mux
  assign up_value = 5'd15 + rStep;
  assign down_value = 5'd15 - rStep;

  // Output
  always @(posedge iClock) begin
    if (rLengthComplete) begin
      oOut[4:0] <= 5'd15;
    end
    else begin
      if (rTone) begin
        oOut[4:0] <= up_value[4:0];
      end
      else begin
        oOut[4:0] <= down_value[4:0];
      end
    end
  end

  assign oOnFlag = rLengthComplete;  
endmodule

module robotic_vehicle_controller(
  input clk,
  input rst_n,
  inout sda,
  input [15:0] speed_control,
  input [15:0] angle_control,
  input uart_rx,
  input key1,
  output scl,
  output reg [7:0] dataLED,
  output wire newControlDataW,
  output wire [15:0] accXdata,
  output MotorPWM,
  output reg MotorA,
  output reg MotorB,
  output ServoPPM,
  output clkOut,
  output uart_tx,
  output wire testICC,
  output reg [15:0] servoDuty,
  output reg [15:0] MotorDuty
);

  wire clk_1MHz;
  ClockDIV #(.N(50)) DIV1MHz (
    .clk_in(clk),
    .clk_out(clk_1MHz),
    .rst_n(rst_n)
  );

  wire clk_1KHz;
  ClockDIV #(.N(50000)) DIV1kHz(
    .clk_in(clk),
    .clk_out(clk_1KHz),
    .rst_n(rst_n)
  );
  assign clkOut = clk_1MHz;

  PWM Motor1(
    .clk(clk),
    .rst_n(rst_n),
    .pwmOut(MotorPWM),
    .period(16'd5000),
    .duty(MotorDuty)
  );

  PWM Servo(
    .clk(clk_1MHz),
    .rst_n(rst_n),
    .pwmOut(ServoPPM),
    .period(16'd20000),
    .duty(servoDuty)
  );

  I2C u1(
    .clk(clk),
    .scl(scl),
    .sda(sda),
    .rst_n(rst_n),
    .LED(testICC),
    .accXdata(accXdata)
  );

  async_receiver #(
    .ClkFrequency(50000000),
    .Baud(9600)
  ) async_receiver (
    .clk(clk),
    .RxD(uart_rx),
    .RxD_data_ready(),
    .RxD_data()
  );

  reg [3:0] dataAssemablingState;
  reg [15:0] steer, throttle;
  reg newControlData;
  reg controlMode;
  assign newControlDataW = controlMode;

  always @ (posedge clk_1KHz or negedge rst_n) begin
    if (!rst_n) begin
      MotorA <= 0;
      MotorB <= 0;
    end else begin
      if (key1) begin
        controlMode <= ~controlMode;
      end
      if (controlMode) begin
        if (async_receiver.RxD_data_ready) begin
          case (dataAssemablingState)
            4'd0: begin
              if (async_receiver.RxD_data == 8'h61) begin
                dataAssemablingState <= 3'd1;
              end
            end
            4'd1: begin
              if (async_receiver.RxD_data == 8'h62) begin
                dataAssemablingState <= 3'd2;
              end else begin
                dataAssemablingState <= 3'd0;
              end
            end
            4'd2: begin
              if (async_receiver.RxD_data == 8'h63) begin
                dataAssemablingState <= 3'd3;
                newControlData <= 1'b0;
              end else if (async_receiver.RxD_data == 8'h6d) begin
                dataAssemablingState <= 4'd8;
              end else begin
                dataAssemablingState <= 3'd0;
              end
            end
            4'd3: begin
              steer[15:8] <= async_receiver.RxD_data;
              dataAssemablingState <= 3'd4;
            end
            4'd4: begin
              steer[7:0] <= async_receiver.RxD_data;
              dataAssemablingState <= 3'd5;
            end
            4'd5: begin
              throttle[15:8] <= async_receiver.RxD_data;
              dataAssemablingState <= 3'd6;
            end
            4'd6: begin
              throttle[7:0] <= async_receiver.RxD_data;
              dataAssemablingState <= 3'd7;
            end
            4'd7: begin
              newControlData <= 1'b1;
              dataAssemablingState <= 3'd0;
            end
            4'd8: begin
              controlMode <= async_receiver.RxD_data[0];
              dataAssemablingState <= 3'd0;
            end
          endcase
        end
      end else begin
        newControlData <= 1'b1;
      end
    end
  end

  always @ (posedge newControlData or posedge clk_1KHz or negedge rst_n) begin
    if (!rst_n) begin
      servoDuty <= 16'd1500;
      MotorDuty <= 0;
    end else begin
      if (newControlData) begin
        if (controlMode) begin
          if (throttle > 512) begin
            MotorA <= 1'b1;
            MotorB <= 1'b0;
            MotorDuty <= {(throttle[12:0] - 13'd512),3'd0};
          end else begin
            MotorA <= 1'b0;
            MotorB <= 1'b1;
            MotorDuty <= {(13'd512 - throttle[12:0]),3'd0};
          end
          servoDuty <= steer + 16'd1000;
        end
      end else begin
        if (!controlMode) begin
          MotorDuty <= speed_control;
          servoDuty <= angle_control;
        end
      end
    end
  end

  assign uart_tx = uart_rx;
endmodule

module modulo_operator (
  input [31:0] A,
  input [31:0] B,
  output reg [31:0] result
);

  // If B is zero, the result should be undefined.
  // If A divided by B has a remainder of r, the result should be set to r.
  // If A is negative, the result should be negative.
  // If A is positive, the result should be positive.
  // If B is negative, the result should be negative.
  // If B is positive, the result should be positive.

  always @(*) begin
    if (B == 0) begin
      result <= 'bx;
    end
    else if (A < 0) begin
      if (B < 0) begin
        result <= -(-A % -B);
      end
      else begin
        result <= -(A % B);
      end
    end
    else begin
      if (B < 0) begin
        result <= A % -B;
      end
      else begin
        result <= A % B;
      end
    end
  end

endmodule

module RisingEdgeDetector(
    input in,
    output out,
    input clk
);

    reg prev_in;

    always @(posedge clk) begin
        if (in && !prev_in) begin
            out <= 1'b1;
        end else begin
            out <= 1'b0;
        end
        prev_in <= in;
    end

endmodule

