module demux_comb(
    input [3:0] a, // Select input to choose which output line of the demultiplexer to use
    input [7:0] sel, // Input for the 256-to-1 demultiplexer
    output [3:0] w,x,y,z // Output from the combinational logic module
);

    wire [7:0] demux_out_b; // Output from the demultiplexer connected to input b
    wire [7:0] demux_out_c; // Output from the demultiplexer connected to input c

    // 256-to-1 demultiplexer
    demux_256to1 demux(
        .sel(a),
        .in(sel),
        .out(demux_out_b)
    );

    // Connect the output of the demultiplexer to the b and c inputs of the combinational logic module
    assign b = demux_out_b;
    assign c = demux_out_c;

    // Combinational logic module
    assign w = a ^ b;
    assign x = b & c;
    assign y = b | c;
    assign z = a & c;

endmodule

// 256-to-1 demultiplexer module
module demux_256to1(
    input [3:0] sel, // Select input to choose which output line to use
    input [255:0] in, // Input to the demultiplexer
    output [7:0] out // Output from the demultiplexer
);

    assign out = in[sel * 8 +: 8]; // Select the appropriate output line based on the select input

endmodule

module address_decoder (
    address_a,
    address_b,
    clock,
    q_a,
    q_b
);

input [8:0] address_a;
input [8:0] address_b;
input clock;
output reg [31:0] q_a;
output reg [31:0] q_b;

reg [31:0] memory [0:63];

integer i;

initial begin
    // Initialize memory with random values
    for (i = 0; i < 64; i = i + 1) begin
        memory[i] = $random;
    end
end

always @(posedge clock) begin
    q_a = 0;
    q_b = 0;
    if (address_a < 64) begin
        if (memory[address_a] % 2 == 0) begin
            q_a = memory[address_a] ** 3;
        end
        else begin
            q_a = memory[address_a] ** 2;
        end
    end
    if (address_b < 64) begin
        if (memory[address_b] % 2 == 0) begin
            q_b = memory[address_b] ** 3;
        end
        else begin
            q_b = memory[address_b] ** 2;
        end
    end
end

endmodule

module master #(
    parameter id = 0,
    parameter nreads = 128,
    parameter nwrites = 128,
    parameter p = 4
) (
    input sys_clk,
    input sys_rst,
    input [31:0] dat_r,
    input ack,
    output reg [31:0] dat_w,
    output reg [31:0] adr,
    output [2:0] cti,
    output reg we,
    output reg [3:0] sel,
    output cyc,
    output stb,
    output reg tend
);

    integer rcounter;
    integer wcounter;
    reg active;

    assign cyc = active;
    assign stb = active;
    assign cti = 0;

    always @(posedge sys_clk) begin
        if(sys_rst) begin
            dat_w = 0;
            adr = 0;
            we = 0;
            sel = 0;
            active = 0;
            rcounter = 0;
            wcounter = 0;
            tend = 0;
        end else begin
            if(ack) begin
                if(~active)
                    $display("[M%d] Spurious ack", id);
                else begin
                    if(we)
                        $display("[M%d] Ack W: %x:%x [%x]", id, adr, dat_w, sel);
                    else
                        $display("[M%d] Ack R: %x:%x [%x]", id, adr, dat_r, sel);
                end
                active = 1'b0;
            end else if(~active) begin
                if(($random % p) == 0 && (rcounter < nreads) && (wcounter < nwrites)) begin
                    adr = $random % 5;
                    adr = (adr << (32-3)) + id;
                    sel = sel + 1;
                    active = 1'b1;
                    if(($random % 2) == 0) begin
                        /* Read */
                        we = 1'b0;
                        rcounter = rcounter + 1;
                    end else begin
                        /* Write */
                        we = 1'b1;
                        dat_w = ($random << 16) + id;
                        wcounter = wcounter + 1;
                    end
                end
            end
            tend = (rcounter >= nreads) && (wcounter >= nwrites);
        end
    end

endmodule

module top_module (
    input [11:0] in,
    output reg [3:0] pos_dec
);

    // Priority Encoder
    wire [11:0] in_inv;
    assign in_inv = ~in;
    wire [3:0] pos_gray;
    priority_encoder pe(
        .in(in_inv),
        .out(pos_gray)
    );

    // Binary-to-Gray Code Converter
    wire [3:0] gray;
    binary_to_gray btg(
        .in(pos_gray),
        .out(gray)
    );

    // Binary-to-Decimal Decoder
    wire [1:0] dec;
    binary_to_decimal btd(
        .in(gray[3:2]),
        .out(dec)
    );

    // Output
    always @(*) begin
        if (in == 0) begin
            pos_dec = 0;
        end else begin
            pos_dec = dec + 1;
        end
    end

endmodule

// Priority Encoder
module priority_encoder (
