        casez(in)
            12'b000000000001: out = 0;
            12'b000000000010: out = 1;
            12'b000000000100: out = 2;
            12'b000000001000: out = 3;
            12'b000000010000: out = 4;
            12'b000000100000: out = 5;
            12'b000001000000: out = 6;
            12'b000010000000: out = 7;
            12'b000100000000: out = 8;
            12'b001000000000: out = 9;
            12'b010000000000: out = 10;
            12'b100000000000: out = 11;
            default: out = 0;
        endcase
    end
endmodule

// Binary-to-Gray Code Converter
module binary_to_gray (
    input [3:0] in,
    output reg [3:0] out
);
    always @(*) begin
        out[3] = in[3];
        out[2] = in[3] ^ in[2];
        out[1] = in[2] ^ in[1];
        out[0] = in[1] ^ in[0];
    end
endmodule

// Binary-to-Decimal Decoder
module binary_to_decimal (
    input [1:0] in,
    output reg [1:0] out
);
    always @(*) begin
        casez(in)
            2'b00: out = 0;
            2'b01: out = 1;
            2'b10: out = 2;
            2'b11: out = 3;
            default: out = 0;
        endcase
    end
endmodule

module barrel_shifter (
    input clk,
    input [15:0] DIN,
    input [3:0] SHIFT,
    output reg [15:0] DOUT
);

reg [15:0] stage1_out, stage2_out, stage3_out;

always @(posedge clk) begin
    stage1_out <= DIN << SHIFT;
end

always @(posedge clk) begin
    stage2_out <= stage1_out << 2;
end

always @(posedge clk) begin
    if (SHIFT[1:0] == 2'b00) begin
        stage3_out <= stage2_out;
    end else if (SHIFT[1:0] == 2'b01) begin
        stage3_out <= {stage2_out[13:0], stage2_out[15:14]};
    end else if (SHIFT[1:0] == 2'b10) begin
        stage3_out <= {stage2_out[14:0], stage2_out[15]};
    end else begin
        stage3_out <= {stage2_out[15], stage2_out[14:1]};
    end
end

always @(posedge clk) begin
    if (SHIFT[3] == 1) begin
        DOUT <= stage3_out >> SHIFT[2:0];
    end else begin
        DOUT <= stage3_out;
    end
end

endmodule

