module cycloneive_m_cntr (clk, reset, cout, initial_value, modulus, time_delay);

    // INPUT PORTS
    input clk;
    input reset;
    input [31:0] initial_value;
    input [31:0] modulus;
    input [31:0] time_delay;

    // OUTPUT PORTS
    output cout;

    // INTERNAL VARIABLES AND NETS
    integer count;
    reg tmp_cout;
    reg first_rising_edge;
    reg clk_last_value;
    reg cout_tmp;

    initial begin
        count = initial_value;
        first_rising_edge = 1;
        clk_last_value = 0;
    end

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= initial_value;
            tmp_cout <= 0;
            first_rising_edge <= 1;
        end else begin
            if (clk_last_value !== clk) begin
                if (clk === 1'b1 && first_rising_edge) begin
                    first_rising_edge <= 0;
                    tmp_cout <= clk;
                    cout_tmp <= #(time_delay) tmp_cout;
                end else if (first_rising_edge == 0) begin
                    if (count < modulus) begin
                        count <= count + 1;
                    end else begin
                        count <= initial_value;
                        tmp_cout <= ~tmp_cout;
                        cout_tmp <= #(time_delay) tmp_cout;
                    end
                end
            end
        end
        clk_last_value <= clk;
    end

    assign cout = cout_tmp;

endmodule

module fifoStatus (
    wr,
    rd,
    fifo_we,
    fifo_rd,
    wptr,
    rptr,
    fifo_full,
    fifo_empty,
    fifo_threshold,
    fifo_overflow,
    fifo_underflow,
    clk,
    rst_n
);

parameter DEPTH = 32;

input wr;
input rd;
input fifo_we;
input fifo_rd;
input [4:0] wptr;
input [4:0] rptr;
output fifo_full;
output fifo_empty;
output fifo_threshold;
output fifo_overflow;
output fifo_underflow;
input clk;
input rst_n;

reg [4:0] fifo_count;
reg [5:0] fifo_depth = DEPTH - 1;
reg [5:0] fifo_threshold_value = DEPTH - 2;

wire fifo_full;
assign fifo_full = ((wptr == rptr) && fifo_we && (fifo_count == fifo_depth));

wire fifo_empty;
assign fifo_empty = ((wptr == rptr) && fifo_rd && (fifo_count == 0));

wire fifo_threshold;
assign fifo_threshold = ((fifo_count <= fifo_threshold_value) && (fifo_count > 0));

wire fifo_overflow;
assign fifo_overflow = (!fifo_rd && fifo_full);

wire fifo_underflow;
assign fifo_underflow = (!fifo_we && fifo_empty);

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        fifo_count <= 0;
    end
    else begin
        if (fifo_we && ~fifo_rd) begin
            fifo_count <= fifo_count + 1;
        end
        else if (~fifo_we && fifo_rd) begin
            fifo_count <= fifo_count - 1;
        end
    end
end

endmodule

