module IR_communication (
  input clk,
  input reset,
  input freq,
  input [len-1:0] data_in,
  output IR_out,
  output [len-1:0] data_out,
  output busy
);

parameter baud = 9600; // baud rate in bps
parameter PW = 100; // pulse width in microseconds
parameter len = 8; // data length in bits

reg [len-1:0] data_tx; // data to be transmitted
reg [len-1:0] data_rx; // received data
reg [2:0] state; // state machine state
reg busy; // busy signal

wire IR_pulse; // IR pulse signal
wire IR_rx; // IR received signal
wire [len-1:0] data_demod; // demodulated data

// state machine states
parameter IDLE = 3'd0;
parameter TX_START = 3'd1;
parameter TX_DATA = 3'd2;
parameter TX_STOP = 3'd3;
parameter RX_START = 3'd4;
parameter RX_DATA = 3'd5;
parameter RX_STOP = 3'd6;

// calculate the number of clock cycles per bit
localparam cycles_per_bit = clk / baud;

// calculate the number of clock cycles per pulse
localparam cycles_per_pulse = PW * clk / 1000000;

// calculate the number of clock cycles per half pulse
localparam cycles_per_half_pulse = cycles_per_pulse / 2;

// calculate the number of clock cycles per carrier frequency cycle
localparam cycles_per_freq_cycle = clk / freq;

// calculate the number of clock cycles per half carrier frequency cycle
localparam cycles_per_half_freq_cycle = cycles_per_freq_cycle / 2;

// generate the carrier frequency signal
reg [cycles_per_half_freq_cycle-1:0] carrier;
always @(posedge clk) begin
  if (carrier == cycles_per_half_freq_cycle-1) begin
    carrier <= 0;
  end else begin
    carrier <= carrier + 1;
  end
end

// generate the IR pulse signal
reg [cycles_per_half_pulse-1:0] pulse;
always @(posedge clk) begin
  if (state == TX_START || state == TX_DATA) begin
    if (pulse == cycles_per_half_pulse-1) begin
      pulse <= 0;
      IR_pulse <= carrier[cycles_per_half_freq_cycle-1];
    end else begin
      pulse <= pulse + 1;
      IR_pulse <= 0;
    end
  end else begin
    pulse <= 0;
    IR_pulse <= 0;
  end
end

// generate the IR output signal
assign IR_out = IR_pulse;

// generate the IR received signal
IR_receiver IR_rx_inst (
  .clk(clk),
  .reset(reset),
  .IR_in(IR_rx)
);

// demodulate the received IR signal
IR_demodulator IR_demod_inst (
  .clk(clk),
  .reset(reset),
  .freq(freq),
  .IR_in(IR_rx),
  .data_out(data_demod)
);

// state machine
always @(posedge clk) begin
  if (reset) begin
    state <= IDLE;
    busy <= 0;
    data_tx <= 0;
    data_rx <= 0;
  end else begin
    case (state)
      IDLE: begin
        if (data_in != 0) begin
          state <= TX_START;
          data_tx <= data_in;
          busy <= 1;
        end else if (data_demod != 0) begin
          state <= RX_START;
          data_rx <= data_demod;
          busy <= 1;
        end else begin
          state <= IDLE;
          busy <= 0;
        end
      end
      TX_START: begin
        if (pulse == cycles_per_half_pulse-1) begin
          state <= TX_DATA;
        end else begin
          state <= TX_START;
        end
      end
      TX_DATA: begin
        if (pulse == cycles_per_half_pulse-1) begin
          data_tx <= data_tx >> 1;
          if (data_tx == 0) begin
            state <= TX_STOP;
          end else begin
            state <= TX_DATA;
          end
        end else begin
          state <= TX_DATA;
        end
      end
      TX_STOP: begin
        if (pulse == cycles_per_half_pulse-1) begin
          state <= IDLE;
          busy <= 0;
        end else begin
          state <= TX_STOP;
        end
      end
      RX_START: begin
        if (data_demod != 0) begin
          state <= RX_DATA;
          data_rx <= data_demod;
        end else begin
          state <= RX_START;
        end
      end
      RX_DATA: begin
        if (data_demod != 0) begin
          data_rx <= data_rx >> 1;
          if (data_rx == 0) begin
            state <= RX_STOP;
          end else begin
            state <= RX_DATA;
          end
        end else begin
          state <= RX_START;
        end
      end
      RX_STOP: begin
        state <= IDLE;
        busy <= 0;
      end
      default: begin
        state <= IDLE;
        busy <= 0;
      end
    endcase
  end
end

// output the received data
assign data_out = data_rx;

endmodule

// IR receiver module
module IR_receiver (
  input clk,
  input reset,
  input IR_in,
  output reg IR_out
);

reg [1:0] state;

parameter IDLE = 2'd0;
parameter START = 2'd1;
parameter DATA = 2'd2;

// state machine
always @(posedge clk) begin
  if (reset) begin
    state <= IDLE;
    IR_out <= 0;
  end else begin
    case (state)
      IDLE: begin
        if (IR_in == 0) begin
          state <= START;
        end else begin
          state <= IDLE;
        end
      end
      START: begin
        if (IR_in == 1) begin
          state <= DATA;
        end else begin
          state <= START;
        end
      end
      DATA: begin
        if (IR_in == 0) begin
          state <= IDLE;
          IR_out <= 1;
        end else begin
          state <= DATA;
        end
      end
      default: begin
        state <= IDLE;
        IR_out <= 0;
      end
    endcase
  end
end

endmodule

module FIFO_image_filter (
    clk,
    data,
    ce,
    a,
    shift,
    q);

parameter DATA_WIDTH = 12;
parameter ADDR_WIDTH = 2;
parameter DEPTH = 3;

input clk;
input [DATA_WIDTH-1:0] data;
input ce;
input [ADDR_WIDTH-1:0] a;
input [ADDR_WIDTH-1:0] shift;
output [DATA_WIDTH-1:0] q;

reg[DATA_WIDTH-1:0] SRL_SIG [0:DEPTH-1];
integer i;

always @ (posedge clk)
    begin
        if (ce)
        begin
            for (i=0;i<DEPTH-1;i=i+1)
                SRL_SIG[i+1] <= SRL_SIG[i];
            SRL_SIG[0] <= data;
        end
        else
        begin
            for (i=DEPTH-2;i>=0;i=i-1)
                SRL_SIG[i] <= SRL_SIG[i+1];
            SRL_SIG[DEPTH-1] <= 0;
        end
    end

assign q = SRL_SIG[a];

endmodule

module decade_counter (
