module alu (A, B, CI, BI, opcode, X, Y, CO);
   parameter A_SIGNED = 0;
   parameter B_SIGNED = 0;
   parameter A_WIDTH  = 1;
   parameter B_WIDTH  = 1;
   parameter Y_WIDTH  = 1;

   input [A_WIDTH-1:0] A;
   input [B_WIDTH-1:0] B;
   input CI, BI;
   input [2:0] opcode;
   output [Y_WIDTH-1:0] X, Y;
   output CO;

   reg [Y_WIDTH-1:0] X_reg, Y_reg;
   reg CO_reg;

   always @(*) begin
      case (opcode)
         3'b000: begin // AND
            X_reg = A & B;
            Y_reg = 0;
            CO_reg = X_reg[Y_WIDTH-1];
         end
         3'b001: begin // OR
            X_reg = A | B;
            Y_reg = 0;
            CO_reg = X_reg[Y_WIDTH-1];
         end
         3'b010: begin // XOR
            X_reg = A ^ B;
            Y_reg = 0;
            CO_reg = X_reg[Y_WIDTH-1];
         end
         3'b011: begin // ADD
            if (A_SIGNED && B_SIGNED) begin
               {CO_reg, X_reg} = $signed(A) + $signed(B) + CI;
            end else if (A_SIGNED) begin
               {CO_reg, X_reg} = $signed(A) + {B_SIGNED{B}} + CI;
            end else if (B_SIGNED) begin
               {CO_reg, X_reg} = A + $signed(B) + CI;
            end else begin
               {CO_reg, X_reg} = A + B + CI;
            end
            Y_reg = 0;
         end
         3'b100: begin // SUBTRACT
            if (A_SIGNED && B_SIGNED) begin
               {CO_reg, X_reg} = $signed(A) - $signed(B) - BI;
            end else if (A_SIGNED) begin
               {CO_reg, X_reg} = $signed(A) - {B_SIGNED{B}} - BI;
            end else if (B_SIGNED) begin
               {CO_reg, X_reg} = A - $signed(B) - BI;
            end else begin
               {CO_reg, X_reg} = A - B - BI;
            end
            Y_reg = 0;
         end
         3'b101: begin // LEFT SHIFT
            X_reg = A << B;
            Y_reg = 0;
            CO_reg = X_reg[Y_WIDTH-1];
         end
         3'b110: begin // RIGHT SHIFT
            X_reg = A >> B;
            Y_reg = 0;
            CO_reg = X_reg[Y_WIDTH-1];
         end
         3'b111: begin // COPY
            X_reg = A;
            Y_reg = B;
            CO_reg = B[B_WIDTH-1];
         end
      endcase
   end

   assign X = X_reg;
   assign Y = Y_reg;
   assign CO = CO_reg;

endmodule

module dbginit_monitor (
  input rst,
  input clk,
  input dbginit,
  input [0:0] actual,
  input [0:0] expected,
  input [10:0] cnt_val,
  input [31:0] mon_num
);

  reg same;
  reg diff;
  reg sig_same;
  reg [31:0] cntr;
  reg check_done;
  reg start_mon;

  initial begin
    same = 0;
    diff = 0;
    cntr = 0;
    check_done = 0;
    sig_same = 0;
    start_mon = 0;
  end

  always @(posedge clk) begin
    if (rst) begin
      same <= 0;
      diff <= 0;
      start_mon <= 1;

      if (actual == expected) begin
        same <= 1;
      end else begin
        diff <= 1;
      end
    end else begin
      same <= 0;
      diff <= 0;
      start_mon <= 0;
    end

    if (start_mon) begin
      cntr <= (!dbginit) ? cntr + 1 : 0;
      if ((cntr == cnt_val) && !check_done) begin
        check_done <= 1;

        if ((actual != expected) && (!sig_same)) begin
          $display("ERROR: Signal value not as expected after dbginit; expected=%h, actual=%h\n", expected, actual);
          $finish;
        end else begin
          if (same) begin
            $display("NOTE: Value did not change before and after dbginit for Monitor#%d\n", mon_num);
          end
        end
      end

      if (same || diff) begin
        if (actual == expected) begin
          sig_same <= 1;
        end
      end else begin
        sig_same <= 0;
      end
    end else begin
      cntr <= 0;
      check_done <= 0;
      sig_same <= 0;
    end
  end

endmodule

