module async_fifo_align_64in_out_blk_mem_gen_generic_cstr #(parameter WIDTH=8)
    (output reg E,
    output reg [8:0] I1,
    output reg [8:0] O3,
    output reg Q,
    input clk,
    input [WIDTH-1:0] din,
    input tmp_ram_rd_en,
    input [WIDTH-1:0] dout);

    reg [WIDTH-1:0] mem [511:0];
    reg [8:0] wr_ptr;
    reg [8:0] rd_ptr;
    reg [8:0] count;

    always @(posedge clk) begin
        if (tmp_ram_rd_en) begin
            dout <= mem[rd_ptr];
            rd_ptr <= rd_ptr + 1;
            count <= count - 1;
            E <= (count == 0);
        end
        if (count < 512) begin
            mem[wr_ptr] <= din;
            wr_ptr <= wr_ptr + 1;
            count <= count + 1;
            Q <= 1;
        end
        if (count == 512) begin
            Q <= 0;
        end
        I1 <= wr_ptr;
        O3 <= rd_ptr;
    end

endmodule

