module edge_detection (
  input clk,
  input reset,
  input a,
  output reg rising_edge,
  output reg falling_edge
);
  reg a_prev;

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      a_prev <= 1'b0;
      rising_edge <= 1'b0;
      falling_edge <= 1'b0;
    end else begin
      if (a && !a_prev) begin
        rising_edge <= 1'b1;
      end else begin
        rising_edge <= 1'b0;
      end

      if (!a && a_prev) begin
        falling_edge <= 1'b1;
      end else begin
        falling_edge <= 1'b0;
      end

      a_prev <= a;
    end
  end
endmodule

