module arb_block (
  input [n-1:0] req,
  output grant
);

parameter n = 4; // number of request signals

reg [n-1:0] priority_select; // priority select signals
wire [n-1:0] encoded_req; // encoded request signals
wire [n-1:0] priority_enc; // priority encoded request signals
wire [n-1:0] priority_enc_inv; // inverted priority encoded request signals
wire [n-1:0] priority_enc_and_inv; // AND of priority encoded and inverted priority encoded request signals

// Priority select signals
assign priority_select[0] = 1'b1;
assign priority_select[1] = 1'b0;
assign priority_select[2] = 1'b1;
assign priority_select[3] = 1'b0;

// Priority encoder
priority_encoder pe(
  .in(encoded_req),
  .out(priority_enc)
);

// Inverted priority encoder
priority_encoder pe_inv(
  .in(~encoded_req),
  .out(priority_enc_inv)
);

// AND of priority encoded and inverted priority encoded request signals
assign priority_enc_and_inv = priority_enc & priority_enc_inv;

// Grant signal
assign grant = encoded_req[priority_enc_and_inv];

// Priority select multiplexer
assign encoded_req = {req, priority_select};

endmodule

module Retiming (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 4; // number of input signals
parameter m = 2; // number of output signals
parameter k = 3; // number of flip-flops

reg [k-1:0] ff; // flip-flop locations

// Define the flip-flops as a sequential circuit
always @(posedge clk) begin
  ff[0] <= in[0];
  ff[1] <= ff[0];
  ff[2] <= ff[1];
end

// Use the retiming technique to move the flip-flops to different locations
always @(*) begin
  case (ff)
    3'b000: begin
      out[0] = in[0];
      out[1] = ff[2];
    end
    3'b001: begin
      out[0] = ff[0];
      out[1] = ff[2];
    end
    3'b010: begin
      out[0] = ff[1];
      out[1] = ff[2];
    end
    3'b011: begin
      out[0] = ff[0];
      out[1] = ff[1];
    end
    3'b100: begin
      out[0] = ff[2];
      out[1] = in[1];
    end
    3'b101: begin
      out[0] = ff[0];
      out[1] = in[1];
    end
    3'b110: begin
      out[0] = ff[1];
      out[1] = in[1];
    end
    3'b111: begin
      out[0] = ff[0];
      out[1] = ff[1];
    end
  endcase
end

endmodule

module calculator(
    input [31:0] a,
    input [31:0] b,
    input [1:0] op,
    input reset,
    output reg [31:0] result
);

always @(posedge reset or posedge op or posedge a or posedge b) begin
    case(op)
        2'b00: result <= a + b;
        2'b01: result <= a - b;
        2'b10: result <= a * b;
        2'b11: begin
            if (b == 0) begin
                result <= 0;
            end else begin
                result <= a / b;
            end
        end
        default: result <= 0;
    endcase
end

endmodule

