module sram(data_a, address_a, wren_a, rden_a, q_a, data_b, address_b, wren_b, rden_b, q_b, clock);

   parameter RAM_DEPTH = 256;
   parameter RAM_WIDTH = 36;
   parameter ADDR_WIDTH = 8;

   reg [RAM_WIDTH-1:0] ram [0:RAM_DEPTH-1];

   input [RAM_WIDTH-1:0] data_a, data_b;
   input [ADDR_WIDTH-1:0] address_a, address_b;
   input wren_a, rden_a, wren_b, rden_b, clock;
   output [RAM_WIDTH-1:0] q_a, q_b;

   always @(posedge clock) begin
      if (wren_a) ram[address_a] <= data_a;
      if (rden_a) q_a <= ram[address_a];
      if (wren_b) ram[address_b] <= data_b;
      if (rden_b) q_b <= ram[address_b];
   end

endmodule

module initiator
  (input  wire        clk,
   input  wire        rst,
   output reg  req,
   input  wire        res);

   reg [31:0] counter;
   reg [31:0] dataExpect;
   reg        dataValid;

   always @(posedge clk)
     if (rst) begin
        counter <= 0;
        req     <= 0;
        dataValid <= 0;
        dataExpect <= 0;
     end else begin
        dataValid <= req & ~res;
        if (dataValid) begin
           if (dataExpect != res)
             $display("%6d Main got %x !!! BAD!", $time, res);
           // else
           //  $display("%6d Main got %x as expected", $time, res);
        end

        if (~res) begin
           req   <= 1;
           req   <= counter;
           dataExpect <= req;
           counter <= counter + 1;

           //$display("%6d Main requests %x", $time, counter);
        end
     end
endmodule

module debug_lsa
(
    input av_clk,
    input av_rst,

    input [9:0] av_address,
    input av_write,
    input av_read,
    input [31:0] av_writedata,
    output reg [31:0] av_readdata,
    output reg av_readdatavalid,

    output reg [7:0] lsa_mode,
    input lsa_clk,
    input lsa_trigger,
    input [31:0] lsa_data
);
    parameter INIT_ARMED = 1;
    parameter INIT_FORCED = 0;
    parameter INIT_MODE = 8'd0;

    //
    // Clock domain crossing
    //

    reg [1:0] sync_av;
    reg [1:0] sync_lsa;
    reg [1:0] sync_lsa_av;

    reg ctrl_arm;
    reg av_arm;
    reg lsa_arm;

    reg ctrl_force;
    reg av_force;
    reg lsa_force;

    reg [7:0] ctrl_mode;
    reg [7:0] av_mode;
    // lsa_mode in port list

    reg sample_done;
    reg av_done;
    reg lsa_done;

    wire sample_running;
    reg av_running;
    reg lsa_running;

    wire [31:0] sample_live = lsa_data;
    reg [31:0] av_live;
    reg [31:0] lsa_live;

    always @ (posedge av_clk or posedge av_rst)
        if (av_rst)
        begin
            sync_lsa_av <= 2'd0;
            sync_av <= 2'd0;
        end
        else
        begin
            sync_lsa_av <= sync_lsa;
            sync_av <= (sync_lsa_av == sync_av) ? sync_av + 2'd1 : sync_av;
        end

    always @ (posedge lsa_clk)
        sync_lsa <= sync_av;

    always @ (posedge av_clk)
        if (sync_av == 2'b01)
            {av_live, av_running, av_done, av_mode, av_force, av_arm} <=
                            {lsa_live, lsa_running, lsa_done, ctrl_mode, ctrl_force, ctrl_arm};

    always @ (posedge lsa_clk)
        if (sync_lsa == 2'b10)
            {lsa_live, lsa_running, lsa_done, lsa_mode, lsa_force, lsa_arm} <=
                            {sample_live, sample_running, sample_done, av_mode, av_force, av_arm};

    //
    // Sample state machine
    //

    reg [10:0] sample_waddr;
    assign sample_running = sample_waddr[10];
    reg [31:0] sample_data[1023:0];

    always @ (posedge lsa_clk)
        sample_done <= lsa_arm && (sample_waddr == 11'h000);

    always @ (posedge lsa_clk)
        if (!lsa_arm)
            sample_waddr <= 11'h001;
        else if (!sample_waddr[10] && |sample_waddr[9:0])
            sample_waddr <= sample_waddr + 11'd1;
        else if (sample_waddr == 11'h400)
            sample_waddr <= (lsa_force || lsa_trigger) ? 11'h401 : 11'h400;
        else if (sample_waddr != 11'h000)
            sample_waddr <= sample_waddr + 10'd1;

    always @ (posedge lsa_clk)
        if (lsa_arm)
            sample_data[sample_waddr[9:0]] <= (sample_waddr[10]) ? lsa_data : 32'd0;

    //
    // Control register
    //

    reg init_cycle;

    always @ (posedge av_clk or posedge av_rst)
        if (av_rst)
        begin
            ctrl_arm <= 1'b0;
            ctrl_force <= 1'b0;
            ctrl_mode <= 8'd0;
            init_cycle <= 1'b0;
        end
        else if (!init_cycle)
        begin
            ctrl_arm <= (INIT_ARMED != 0);
            ctrl_force <= (INIT_FORCED != 0);
            ctrl_mode <= INIT_MODE;
            init_cycle <= 1'b1;
        end
        else if (av_write && (av_address == 10'd0))
        begin
            ctrl_arm <= av_writedata[0];
            ctrl_force <= av_writedata[1];
            ctrl_mode <= av_writedata[15:8];
        end

    always @ (posedge av_clk)
        av_readdatavalid <= av_read;

    always @ (posedge av_clk)
        if (av_address == 10'd0)
            av_readdata <= {16'd0, ctrl_mode, 4'd0, av_running, av_done, ctrl_force, ctrl_arm};
        else if (av_address == 10'd1)
            av_readdata <= av_live;
        else
            av_readdata <= sample_data[av_address];

endmodule

module DelayLoop(Clear, Timeout, CLOCK);
    input Clear, CLOCK;
    output reg Timeout;
    parameter COUNT_MAX = 100; //change this value to change the delay time

    reg [7:0] count;

    always @(posedge CLOCK) begin
        if(Clear) begin
            count <= 0;
            Timeout <= 0;
        end
        else begin
            if(count == COUNT_MAX) begin
                count <= 0;
                Timeout <= 1;
            end
            else begin
                count <= count + 1;
                Timeout <= 0;
            end
        end
    end
endmodule

module square_wave (
    input clk,
    input reset,
    output reg out
);

reg [1:0] state;
always @ (posedge clk) begin
    if (reset) begin
        state <= 2'b00;
        out <= 0;
    end else begin
        case (state)
            2'b00: begin
                out <= 0;
                state <= 2'b01;
            end
            2'b01: begin
                out <= 1;
                state <= 2'b10;
            end
            2'b10: begin
                out <= 1;
                state <= 2'b11;
            end
            2'b11: begin
                out <= 0;
                state <= 2'b00;
            end
        endcase
    end
end

endmodule

module ALU_1bit_overflow
(
// Input
		input								a_in,
		input								b_in,
		input								carry_in,
		input								b_invert,
		input								less,
		input     		[1:0]     	op,

// Output
		output	wire					result,
		output	wire					carry_out,
		output	wire					set,
		output	wire					overflow
    );

// Internal Variables
reg					b_invert_out;
reg					mux_out;
reg					check;

wire					fa_01_out;
wire					and_out;
wire					or_out;

//assign
assign 				set = fa_01_out;
assign				overflow = check;
assign				result   =  mux_out;

//submodule
full_adder fa_01 (
	.x_in				( a_in				),
	.y_in				( b_invert_out 	),
	.c_in				( carry_in 			),
	.s_out			( fa_01_out 		),
	.c_out			( carry_out 		)
); // Full_Adder


// b_Inverter
always @ ( b_invert or b_in )
begin : Binvert
			if ( !b_invert )
				b_invert_out	=   	b_in;				// 	b
			else
				b_invert_out	=		~ b_in;			//		b'
end

// Logical_operation
assign		and_out	=	a_in & b_invert_out;
assign		or_out	=	a_in | b_invert_out;

// op_Selection
always @ ( op or and_out or or_out or less or fa_01_out )
begin : Operation
		if ( op == 0 )
			mux_out	= 	and_out;
			else if ( op == 1)
				mux_out	= 	or_out;
			else if ( op == 2)
				mux_out	= 	fa_01_out;
			else 
				mux_out	= 	less;		
end

//Overflow_detection
always @ ( op or a_in or b_invert_out or fa_01_out or carry_in)
begin : Checker
		if ( op == 0 || op == 1 )
			check = 1'b0;
			else if ( op == 2 && carry_in == 1'b1 && fa_01_out == 1'b1 )
			check = 1'b1;
			else if ( op == 2 && carry_in == 1'b0 && fa_01_out == 1'b0 )
			check = 1'b1;
			else if ( op == 3 && less == 1'b1 && a_in == 1'b0 && b_invert_out == 1'b1 )
			check = 1'b1;
			else if ( op == 3 && less == 1'b0 && a_in == 1'b1 && b_invert_out == 1'b0 )
			check = 1'b1;
			else
			check = 1'b0;
end 

endmodule

