    wire [15:0] carry;
    wire [31:0] b_inv;

    assign a_low = a[15:0];
    assign b_low = b[15:0];
    assign b_inv = sub ? ~b : b;

    xor_gate xor_inst(
        .a(b_inv[15:0]),
        .b(b_inv[31:16]),
        .out(carry)
    );

    adder add_inst(
        .a(a_low),
        .b(b_low),
        .cin(carry),
        .sum(sum[15:0])
    );

    adder add_inst2(
        .a(a[31:16]),
        .b(b_inv[31:16]),
        .cin(add_inst.cout),
        .sum(sum[31:16])
    );

endmodule

