module i2s_out(
    input clock, reset,
    input [15:0] left_data,
    input [15:0] right_data,
    output mclk,
    output lrck,
    output sclk,
    output reg sdin
);

    // Counter values for LRCK and SCLK
    wire [5:0] sclk_counter = 6'd1;
    wire [5:0] lrck_counter = 6'd63;

    // Data position counter
    reg [3:0] data_pos;

    // Generate MCLK
    assign mclk = clock;

    // Generate LRCK
    clock_divider lrck_gen (
        .clock(clock),
        .reset(reset),
        .counter(lrck_counter),
        .clock_out(lrck)
    );

    // Generate SCLK
    clock_divider sclk_gen (
        .clock(clock),
        .reset(reset),
        .counter(sclk_counter),
        .clock_out(sclk)
    );

    always @ (negedge sclk) begin
        if (lrck) begin
            // Output left_data on rising edge of LRCK
            sdin <= left_data[data_pos];
        end else begin
            // Output right_data on falling edge of LRCK
            sdin <= right_data[data_pos];
            // Increment data position counter
            data_pos <= data_pos + 1;
        end
    end

endmodule

