            7'b0000010: result = {data[97:0], data[99:98]};
            7'b0000100: result = {data[95:0], data[99:97]};
            7'b0001000: result = {data[91:0], data[99:92]};
            7'b0010000: result = {data[83:0], data[99:84]};
            7'b0100000: result = {data[67:0], data[99:68]};
            7'b1000000: result = {data[35:0], data[99:36]};
            default: result = data;
        endcase
    end

