module top_module (
    input clk,
    input load,
    input [1:0] ena,
    input [99:0] data,
    input d,
    output reg q,
    output reg led
);

    reg [99:0] rotated_data;
    reg [99:0] xor_result;

    rotator rotator_inst (
        .data(data),
        .shift_amt(ena == 2'b00 ? 7'b0000001 : 7'b1111111),
        .result(rotated_data)
    );

    always @(posedge clk) begin
        if (load) begin
            q <= d;
        end else if (ena == 2'b01) begin
            q <= rotated_data[99];
        end else if (ena == 2'b10) begin
            q <= rotated_data[0];
        end
    end

    always @(*) begin
        xor_result = data ^ rotated_data;
        led = (xor_result == 0);
    end

