module arbiter (
    input wire clk, rst_async_n, r1, r2, datain1, datain2,
    output reg d1, d2, g1, g2,
    output reg [7:0] dataout,
    output wire req1, ack1, req2, ack2
);

reg [1:0] state;
reg [1:0] next_state;

wire [1:0] input_req;
wire [1:0] input_ack;
wire [1:0] output_ack;
wire [1:0] output_req;

assign input_req = {req1, req2};
assign input_ack = {ack1, ack2};
assign output_req = {g1, g2};
assign output_ack = {d1, d2};

always @(posedge clk, negedge rst_async_n) begin
    if (~rst_async_n) begin
        state <= 2'b00;
    end else begin
        state <= next_state;
    end
end

always @(*) begin
    case (state)
        2'b00: begin // idle
            if (r1 && r2) begin
                next_state = 2'b00;
            end else if (r1) begin
                next_state = 2'b01;
            end else if (r2) begin
                next_state = 2'b10;
            end
        end
        2'b01: begin // waiting for ack1
            if (input_ack[0]) begin
                next_state = 2'b11;
            end else begin
                next_state = 2'b01;
            end
        end
        2'b10: begin // waiting for ack2
            if (input_ack[1]) begin
                next_state = 2'b11;
            end else begin
                next_state = 2'b10;
            end
        end
        2'b11: begin // forwarding data
            if (output_ack[0] && output_ack[1]) begin
                next_state = 2'b00;
            end else begin
                next_state = 2'b11;
            end
        end
    endcase
end

always @(posedge clk, negedge rst_async_n) begin
    if (~rst_async_n) begin
        d1 <= 1'b0;
        d2 <= 1'b0;
        g1 <= 1'b0;
        g2 <= 1'b0;
        dataout <= 8'b0;
    end else begin
        case (state)
            2'b00: begin // idle
                d1 <= 1'b0;
                d2 <= 1'b0;
                g1 <= 1'b0;
                g2 <= 1'b0;
                dataout <= 8'b0;
            end
            2'b01: begin // waiting for ack1
                d1 <= 1'b0;
                d2 <= 1'b0;
                g1 <= 1'b1;
                g2 <= 1'b0;
                dataout <= 8'b0;
            end
            2'b10: begin // waiting for ack2
                d1 <= 1'b0;
                d2 <= 1'b0;
                g1 <= 1'b0;
                g2 <= 1'b1;
                dataout <= 8'b0;
            end
            2'b11: begin // forwarding data
                if (output_req[0] && input_req[0]) begin
                    d1 <= 1'b1;
                    d2 <= 1'b0;
                    g1 <= 1'b0;
                    g2 <= 1'b0;
                    dataout <= datain1;
                end else if (output_req[1] && input_req[1]) begin
                    d1 <= 1'b0;
                    d2 <= 1'b1;
                    g1 <= 1'b0;
                    g2 <= 1'b0;
                    dataout <= datain2;
                end else begin
                    d1 <= 1'b0;
                    d2 <= 1'b0;
                    g1 <= 1'b0;
                    g2 <= 1'b0;
                    dataout <= 8'b0;
                end
            end
        endcase
    end
end

