module top_module (
    input wire clk,
    input wire [31:0] A,
    input wire [31:0] B,
    input wire select,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo,
    output wire [31:0] S,
    output wire Cout
);

    wire [31:0] P, G, C1, C2;
    wire [7:0] S_hi, S_lo;
    wire [31:0] S_temp;

    // Split 16-bit input into two 8-bit outputs
    split_16bit split_input(
        .in(A + B),
        .out_hi(S_hi),
        .out_lo(S_lo)
    );

    // Generate P and G signals for carry-select adder
    generate_carry lookahead_adder(
        .A(A),
        .B(B),
        .P(P),
        .G(G)
    );

    // Carry-select adder
    carry_select_adder adder(
        .A(A),
        .B(B),
        .Cin(C1),
        .S(S_temp),
        .Cout(C2),
        .P(P),
        .G(G)
    );

    // Multiplexer and decoder for selecting output
    mux_decoder output_select(
        .in(S_temp),
        .out_hi(S_hi),
        .out_lo(S_lo),
        .select(select)
    );

    // Output signals
    assign S = S_temp;
    assign Cout = C2;
    assign out_hi = S_hi;
    assign out_lo = S_lo;

endmodule

// Split 16-bit input into two 8-bit outputs
module split_16bit (
    input wire [15:0] in,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo
);
    assign out_hi = in[15:8];
    assign out_lo = in[7:0];
endmodule

// Generate P and G signals for carry-select adder
module generate_carry (
    input wire [31:0] A,
    input wire [31:0] B,
    output wire [31:0] P,
    output wire [31:0] G
);
    assign P = A + B;
    assign G = A & B;
endmodule

// Carry-select adder
module carry_select_adder (
    input wire [31:0] A,
    input wire [31:0] B,
    input wire Cin,
    output wire [31:0] S,
    output wire Cout,
    input wire [31:0] P,
    input wire [31:0] G
);
    wire [31:0] S0, S1;
    wire [31:0] C0, C1;

    // First adder
    carry_lookahead_adder adder0(
        .A(A),
        .B(B),
        .Cin(Cin),
        .S(S0),
        .Cout(C0)
    );

    // Second adder
    carry_lookahead_adder adder1(
        .A(P),
        .B(G),
        .Cin(Cin),
        .S(S1),
        .Cout(C1)
    );

    // Multiplexer for selecting output
    mux2x1 mux(
        .in0(S0),
        .in1(S1),
        .out(S),
        .select(Cout)
    );

endmodule

// Carry lookahead adder
module carry_lookahead_adder (
    input wire [31:0] A,
    input wire [31:0] B,
    input wire Cin,
    output wire [31:0] S,
    output wire Cout
);
    wire [31:0] G, P;

    // Generate G and P signals
    assign G = A & B;
    assign P = A ^ B;

    // Generate S and Cout
    assign S = P ^ Cin;
    assign Cout = G | (P & Cin);
endmodule

// Multiplexer and decoder for selecting output
module mux_decoder (
    input wire [31:0] in,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo,
    input wire select
);
    assign out_hi = in[31:24];
    assign out_lo = in[7:0];
    assign in[31:24] = select ? 8'b0 : in[31:24];
    assign in[7:0] = select ? 8'b0 : in[7:0];
endmodule

// 2x1 multiplexer
module mux2x1 (
    input wire [31:0] in0,
    input wire [31:0] in1,
    output wire [31:0] out,
    input wire select
);
    assign out = select ? in1 : in0;
endmodule

module adder (
    input [7:0] a,
    input [7:0] b,
    output reg [7:0] sum,
    input valid,
    output reg ready
);

reg [7:0] reg_a;
reg [7:0] reg_b;
reg [7:0] reg_sum;

always @(posedge clk) begin
    if (rst_n == 1'b0) begin
        reg_a <= 8'b0;
        reg_b <= 8'b0;
        reg_sum <= 8'b0;
        ready <= 1'b0;
    end else begin
        if (valid == 1'b1 && ready == 1'b0) begin
            reg_a <= a;
            reg_b <= b;
            reg_sum <= reg_a + reg_b;
            ready <= 1'b1;
        end else if (ready == 1'b1) begin
            ready <= 1'b0;
        end
    end
end

assign sum = reg_sum;

endmodule

module multiplier (
    input [3:0] a,
    input [3:0] b,
    output reg [7:0] product,
    input valid,
    output reg ready
);

reg [3:0] reg_a;
reg [3:0] reg_b;
reg [7:0] reg_product;

always @(posedge clk) begin
    if (rst_n == 1'b0) begin
        reg_a <= 4'b0;
        reg_b <= 4'b0;
        reg_product <= 8'b0;
        ready <= 1'b0;
    end else begin
        if (valid == 1'b1 && ready == 1'b0) begin
            reg_a <= a;
            reg_b <= b;
            reg_product <= reg_a * reg_b;
            ready <= 1'b1;
        end else if (ready == 1'b1) begin
            ready <= 1'b0;
        end
    end
end

assign product = reg_product;

endmodule

module functional_module (
    input [7:0] adder_out,
    input [7:0] multiplier_out,
    output reg [11:0] out,
    input valid_a,
    input valid_b,
    output reg ready_a,
    output reg ready_b
);

reg [7:0] reg_adder_out;
reg [7:0] reg_multiplier_out;
reg [11:0] reg_out;

always @(posedge clk) begin
    if (rst_n == 1'b0) begin
        reg_adder_out <= 8'b0;
        reg_multiplier_out <= 8'b0;
        reg_out <= 12'b0;
        ready_a <= 1'b0;
        ready_b <= 1'b0;
    end else begin
        if (valid_a == 1'b1 && ready_a == 1'b0) begin
            reg_adder_out <= adder_out;
            ready_a <= 1'b1;
        end else if (ready_a == 1'b1) begin
            ready_a <= 1'b0;
        end

        if (valid_b == 1'b1 && ready_b == 1'b0) begin
            reg_multiplier_out <= multiplier_out;
            ready_b <= 1'b1;
        end else if (ready_b == 1'b1) begin
            ready_b <= 1'b0;
        end

        if (ready_a == 1'b1 && ready_b == 1'b1) begin
            reg_out <= {reg_adder_out, reg_multiplier_out};
        end
    end
end

assign out = reg_out;

endmodule

module top_module (
