module MUX4(input A, input B, input C, input D, input S0, input S1, output Q);

wire notS0, notS1, and1, and2, and3, and4, or1, or2, or3;

assign notS0 = ~S0;
assign notS1 = ~S1;

assign and1 = A & notS0 & notS1;
assign and2 = B & notS0 & S1;
assign and3 = C & S0 & notS1;
assign and4 = D & S0 & S1;

assign or1 = and1 | and2;
assign or2 = and3 | and4;

assign Q = or1 | or2;

endmodule

module shift_register(CLOCKENABLE, INPUTCLK, LATCHINPUTVALUE, PARALLELLOAD, SERIALIN, SERIALOUT, Q);
  parameter WIDTH = 8;
  input CLOCKENABLE;
  input INPUTCLK;
  input LATCHINPUTVALUE;
  input PARALLELLOAD;
  input SERIALIN;
  output SERIALOUT;
  output reg [WIDTH-1:0] Q;
  reg [WIDTH-1:0] shift_reg;

  always @(posedge CLOCKENABLE) begin
    if (LATCHINPUTVALUE) begin
      shift_reg <= {SERIALIN, shift_reg[WIDTH-1:1]};
    end else if (PARALLELLOAD) begin
      shift_reg <= SERIALIN;
    end else begin
      if (Q[0]) begin
        shift_reg <= {shift_reg[WIDTH-2:0], SERIALIN};
      end else begin
        shift_reg <= {SERIALIN, shift_reg[WIDTH-1:1]};
      end
    end
  end

  assign SERIALOUT = shift_reg[0];
  assign Q = shift_reg;

endmodule

module top_module(
    input [3:0] a1,
    input [3:0] a2,
    input [3:0] b1,
    input [3:0] b2,
    input sel1,
    input sel2,
    input select,
    output [3:0] out
);

    // First 2-to-1 multiplexer
    wire [3:0] mux1_out;
    mux2to1 mux1(
        .a(a1),
        .b(b1),
        .sel(sel1),
        .out(mux1_out)
    );

    // Second 2-to-1 multiplexer
    wire [3:0] mux2_out;
    mux2to1 mux2(
        .a(a2),
        .b(b2),
        .sel(sel2),
        .out(mux2_out)
    );

    // Control logic to select active multiplexer
    wire [3:0] active_mux_out;
    assign active_mux_out = select ? mux2_out : mux1_out;

    // Functional module to sum the outputs of the two multiplexers
    wire [7:0] sum;
    adder add(
        .a(active_mux_out),
        .b(mux2_out),
        .sum(sum)
    );

    // Output the sum of the active multiplexer's values
    assign out = sum[3:0];

endmodule

module mux2to1(
