module vending_machine (
  input clk,
  input reset,
  input coin,
  input item1_button,
  input item2_button,
  input item3_button,
  output reg item1_dispense,
  output reg item2_dispense,
  output reg item3_dispense,
  output reg change_dispense
);

// Define the states of the FSM
parameter IDLE_STATE = 2'b00;
parameter ITEM1_STATE = 2'b01;
parameter ITEM2_STATE = 2'b10;
parameter ITEM3_STATE = 2'b11;

// Define the prices of each item
parameter ITEM1_PRICE = 25;
parameter ITEM2_PRICE = 50;
parameter ITEM3_PRICE = 75;

// Define the maximum amount of money that can be inserted
parameter MAX_AMOUNT = 100;

// Define the current state and amount of money inserted
reg [1:0] state = IDLE_STATE;
reg [7:0] amount = 0;

// Define the outputs
reg change_needed = 0;
reg [7:0] change_amount = 0;

// Define the state transition logic
always @(posedge clk) begin
  if (reset) begin
    state <= IDLE_STATE;
    amount <= 0;
    item1_dispense <= 0;
    item2_dispense <= 0;
    item3_dispense <= 0;
    change_dispense <= 0;
    change_needed <= 0;
    change_amount <= 0;
  end else begin
    case (state)
      IDLE_STATE: begin
        if (item1_button) begin
          state <= ITEM1_STATE;
        end else if (item2_button) begin
          state <= ITEM2_STATE;
        end else if (item3_button) begin
          state <= ITEM3_STATE;
        end
        if (coin) begin
          amount <= amount + 25;
        end
      end
      ITEM1_STATE: begin
        if (amount >= ITEM1_PRICE) begin
          item1_dispense <= 1;
          change_needed <= 1;
          change_amount <= amount - ITEM1_PRICE;
          state <= IDLE_STATE;
        end else if (coin) begin
          amount <= amount + 25;
        end
      end
      ITEM2_STATE: begin
        if (amount >= ITEM2_PRICE) begin
          item2_dispense <= 1;
          change_needed <= 1;
          change_amount <= amount - ITEM2_PRICE;
          state <= IDLE_STATE;
        end else if (coin) begin
          amount <= amount + 25;
        end
      end
      ITEM3_STATE: begin
        if (amount >= ITEM3_PRICE) begin
          item3_dispense <= 1;
          change_needed <= 1;
          change_amount <= amount - ITEM3_PRICE;
          state <= IDLE_STATE;
        end else if (coin) begin
          amount <= amount + 25;
        end
      end
    endcase
    if (amount > MAX_AMOUNT) begin
      change_needed <= 1;
      change_amount <= amount - MAX_AMOUNT;
      amount <= MAX_AMOUNT;
      state <= IDLE_STATE;
    end
    if (change_needed) begin
      change_dispense <= 1;
      amount <= amount - change_amount;
      change_needed <= 0;
    end else begin
      change_dispense <= 0;
    end
  end
end

endmodule

module cf_add (
  clk,
  data_1,
  data_2,
  data_3,
  data_4,
  data_p,
  ddata_in,
  ddata_out);

  parameter DELAY_DATA_WIDTH = 16;
  parameter DW = DELAY_DATA_WIDTH - 1;

  input           clk;
  input   [24:0]  data_1;
  input   [24:0]  data_2;
  input   [24:0]  data_3;
  input   [24:0]  data_4;
  output  [ 7:0]  data_p;
  input   [DW:0]  ddata_in;
  output  [DW:0]  ddata_out;

  reg     [DW:0]  p1_ddata = 'd0;
  reg     [24:0]  p1_data_1 = 'd0;
  reg     [24:0]  p1_data_2 = 'd0;
  reg     [24:0]  p1_data_3 = 'd0;
  reg     [24:0]  p1_data_4 = 'd0;
  reg     [DW:0]  p2_ddata = 'd0;
  reg     [24:0]  p2_data_0 = 'd0;
  reg     [24:0]  p2_data_1 = 'd0;
  reg     [DW:0]  p3_ddata = 'd0;
  reg     [24:0]  p3_data = 'd0;
  reg     [DW:0]  ddata_out = 'd0;
  reg     [ 7:0]  data_p = 'd0;

  wire    [24:0]  p1_data_1_p_s;
  wire    [24:0]  p1_data_1_n_s;
  wire    [24:0]  p1_data_1_s;
  wire    [24:0]  p1_data_2_p_s;
  wire    [24:0]  p1_data_2_n_s;
  wire    [24:0]  p1_data_2_s;
  wire    [24:0]  p1_data_3_p_s;
  wire    [24:0]  p1_data_3_n_s;
  wire    [24:0]  p1_data_3_s;
  wire    [24:0]  p1_data_4_p_s;
  wire    [24:0]  p1_data_4_n_s;
  wire    [24:0]  p1_data_4_s;

  assign p1_data_1_p_s = {1'b0, data_1[23:0]};
  assign p1_data_1_n_s = ~p1_data_1_p_s + 1'b1;
  assign p1_data_1_s = (data_1[24] == 1'b1) ? p1_data_1_n_s : p1_data_1_p_s;

  assign p1_data_2_p_s = {1'b0, data_2[23:0]};
  assign p1_data_2_n_s = ~p1_data_2_p_s + 1'b1;
  assign p1_data_2_s = (data_2[24] == 1'b1) ? p1_data_2_n_s : p1_data_2_p_s;

  assign p1_data_3_p_s = {1'b0, data_3[23:0]};
  assign p1_data_3_n_s = ~p1_data_3_p_s + 1'b1;
  assign p1_data_3_s = (data_3[24] == 1'b1) ? p1_data_3_n_s : p1_data_3_p_s;

  assign p1_data_4_p_s = {1'b0, data_4[23:0]};
  assign p1_data_4_n_s = ~p1_data_4_p_s + 1'b1;
  assign p1_data_4_s = (data_4[24] == 1'b1) ? p1_data_4_n_s : p1_data_4_p_s;

  always @(posedge clk) begin
    p1_ddata <= ddata_in;
    p1_data_1 <= p1_data_1_s;
    p1_data_2 <= p1_data_2_s;
    p1_data_3 <= p1_data_3_s;
    p1_data_4 <= p1_data_4_s;
  end

  always @(posedge clk) begin
    p2_ddata <= p1_ddata;
    p2_data_0 <= p1_data_1 + p1_data_2;
    p2_data_1 <= p1_data_3 + p1_data_4;
  end

  always @(posedge clk) begin
    p3_ddata <= p2_ddata;
    p3_data <= p2_data_0 + p2_data_1;
  end

  always @(posedge clk) begin
    ddata_out <= p3_ddata;
    if (p3_data[24] == 1'b1) begin
      data_p <= 8'h00;
    end else if (p3_data[23:20] == 'd0) begin
      data_p <= p3_data[19:12];
    end else begin
      data_p <= 8'hff;
    end
  end

endmodule

module mealy_state_machine (
  input clk,
  input reset,
  input [1:0] input_bits,
  output reg output_bit
);

  reg [1:0] state;

  always @(posedge clk) begin
    if (reset) begin
      state <= 2'b00; // reset state is S0
      output_bit <= 1'b0;
    end else begin
      case (state)
        2'b00: begin // S0 state
          if (input_bits == 2'b00) begin
            state <= 2'b00;
            output_bit <= 1'b0;
          end else if (input_bits == 2'b01) begin
            state <= 2'b01;
            output_bit <= 1'b0;
          end else if (input_bits == 2'b10) begin
            state <= 2'b10;
            output_bit <= 1'b0;
          end else begin // input_bits == 2'b11
            state <= 2'b00;
            output_bit <= 1'b0;
          end
        end
        2'b01: begin // S1 state
          if (input_bits == 2'b00) begin
            state <= 2'b01;
            output_bit <= 1'b1;
          end else if (input_bits == 2'b01) begin
            state <= 2'b10;
            output_bit <= 1'b1;
          end else if (input_bits == 2'b10) begin
            state <= 2'b00;
            output_bit <= 1'b1;
          end else begin // input_bits == 2'b11
            state <= 2'b01;
            output_bit <= 1'b1;
          end
        end
        2'b10: begin // S2 state
          if (input_bits == 2'b00) begin
            state <= 2'b10;
            output_bit <= 1'b0;
          end else if (input_bits == 2'b01) begin
            state <= 2'b00;
            output_bit <= 1'b0;
          end else if (input_bits == 2'b10) begin
            state <= 2'b01;
            output_bit <= 1'b0;
          end else begin // input_bits == 2'b11
            state <= 2'b10;
            output_bit <= 1'b0;
          end
        end
      endcase
    end
  end

endmodule

module MUX41X2 (IN1, IN2, IN3, IN4, S0, S1, Q);

  input IN1, IN2, IN3, IN4, S0, S1;
  output Q;

  wire t1, t2, t3, t4, t5;

  // First 2:1 MUX
  MUX2X1 MUX2X1_1 (.I0(IN1), .I1(IN2), .S(S0), .O(t1));

  // Second 2:1 MUX
  MUX2X1 MUX2X1_2 (.I0(IN3), .I1(IN4), .S(S0), .O(t2));

  // NOT gate for S1
  NOT NOT_1 (.I(S1), .O(t3));

  // AND gate for S1 and t1
  AND AND_1 (.I0(S1), .I1(t1), .O(t4));

  // AND gate for t2 and t3
  AND AND_2 (.I0(t2), .I1(t3), .O(t5));

  // Final output MUX
  MUX2X1 MUX2X1_3 (.I0(t4), .I1(t5), .S(S1), .O(Q));

endmodule

module freq_divider (
  input clk,
  input rst,
  input [3:0] div_factor,
  output reg clk_out
);

// The module has a 4-bit control input, which allows for division factors of up to 16.
// The default division factor is 2.
parameter DEFAULT_DIV_FACTOR = 2;
parameter MAX_DIV_FACTOR = 16;

initial begin
  clk_out <= 0;
end

reg [3:0] count;

always @(posedge clk or negedge rst) begin
  if (~rst) begin
    clk_out <= 0;
    count <= 0;
  end
  else begin
    if (count >= div_factor - 1) begin
      count <= 0;
      clk_out <= ~clk_out;
    end
    else begin
      count <= count + 1;
    end
  end
end

endmodule

