module spi_controller (
  spi_csn,
  spi_clk,
  spi_mosi,
  spi_miso,
  spi_sdio,
  spi_dir
);

  // 4 wire
  input [2:0] spi_csn;
  input spi_clk;
  input spi_mosi;
  output spi_miso;

  // 3 wire
  inout spi_sdio;
  output spi_dir;

  // Internal registers
  reg [5:0] spi_count = 6'b0;
  reg spi_rd_wr_n = 1'b0;
  reg spi_enable = 1'b0;

  // Internal signals
  wire spi_csn_s;
  wire spi_enable_s;

  // Check on rising edge and change on falling edge
  assign spi_csn_s = &spi_csn;
  assign spi_dir = ~spi_enable_s;
  assign spi_enable_s = spi_enable & ~spi_csn_s;

  // 4-wire interface
  always @(posedge spi_clk or posedge spi_csn_s) begin
    if (spi_csn_s == 1'b1) begin
      spi_count <= 6'd0;
      spi_rd_wr_n <= 1'd0;
      spi_miso <= 1'd0;
    end else begin
      spi_count <= spi_count + 1'b1;
      if (spi_count == 6'd0) begin
        spi_rd_wr_n <= spi_mosi;
      end else if (spi_count == 6'd15) begin
        spi_miso <= spi_rd_wr_n;
      end
    end
  end

  // 3-wire interface
  always @(negedge spi_clk or posedge spi_csn_s) begin
    if (spi_csn_s == 1'b1) begin
      spi_enable <= 1'b0;
    end else begin
      if (spi_count == 6'd0) begin
        spi_enable <= 1'b1;
      end else if (spi_count == 6'd7) begin
        spi_enable <= 1'b0;
      end
    end
  end

  // IO buffer
  IOBUF i_iobuf_sdio (
    .T (spi_enable_s),
    .I (spi_mosi),
    .O (spi_miso),
    .IO (spi_sdio)
  );

endmodule

module PWM (
  input clk,
  input ref,
  input [7:0] duty,
  output reg pwm
);

parameter width = 8; // width of PWM output signal
parameter period = 256; // period of PWM output signal

reg [7:0] count;
reg [7:0] threshold;

always @(posedge clk) begin
  count <= count + 1;
  if (count == period - 1) begin
    count <= 0;
  end
end

always @(*) begin
  threshold = (duty * period) / 256;
end

always @(posedge clk) begin
  if (count < threshold) begin
    pwm <= 1;
  end else begin
    pwm <= 0;
  end
end

endmodule

module add4bit (
    input [3:0] A,
    input [3:0] B,
    output reg [3:0] S,
    output reg C_out
);

    wire [3:0] temp_sum;
    wire carry;

    assign temp_sum = A + B;
    assign carry = (temp_sum[4] == 1);

    always @ (A or B) begin
        S <= temp_sum[3:0];
        C_out <= carry;
    end

endmodule

