module priority_encoder (
    input [7:0] I,
    output reg [2:0] O
);

reg [7:0] I_reg [2:0];
reg [2:0] O_reg [2:0];

always @ (posedge clk) begin
    I_reg[0] <= I;
    I_reg[1] <= I_reg[0];
    I_reg[2] <= I_reg[1];

    O_reg[0] <= O;
    O_reg[1] <= O_reg[0];
    O_reg[2] <= O_reg[1];

    if (I_reg[2][7]) O <= 2;
    else if (I_reg[1][7]) O <= 1;
    else if (I_reg[0][7]) O <= 0;
    else if (I_reg[2][6]) O <= 2;
    else if (I_reg[1][6]) O <= 1;
    else if (I_reg[0][6]) O <= 0;
    else if (I_reg[2][5]) O <= 2;
    else if (I_reg[1][5]) O <= 1;
    else if (I_reg[0][5]) O <= 0;
    else if (I_reg[2][4]) O <= 2;
    else if (I_reg[1][4]) O <= 1;
    else if (I_reg[0][4]) O <= 0;
    else if (I_reg[2][3]) O <= 2;
    else if (I_reg[1][3]) O <= 1;
    else if (I_reg[0][3]) O <= 0;
    else if (I_reg[2][2]) O <= 2;
    else if (I_reg[1][2]) O <= 1;
    else if (I_reg[0][2]) O <= 0;
    else if (I_reg[2][1]) O <= 2;
    else if (I_reg[1][1]) O <= 1;
    else if (I_reg[0][1]) O <= 0;
    else if (I_reg[2][0]) O <= 2;
    else if (I_reg[1][0]) O <= 1;
    else if (I_reg[0][0]) O <= 0;
end

