module mux_priority_encoder_decoder (
    input [2:0] sel,
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output reg [3:0] out
);

reg [3:0] mux_out [5:0];
reg [2:0] highest_priority;
reg [2:0] selected_input;

always @(*) begin
    case(sel)
        3'b000: begin
            mux_out[0] = data0;
            mux_out[1] = data1;
            mux_out[2] = data2;
            mux_out[3] = data3;
            mux_out[4] = data4;
            mux_out[5] = data5;
        end
        3'b001: begin
            mux_out[0] = data1;
            mux_out[1] = data0;
            mux_out[2] = data2;
            mux_out[3] = data3;
            mux_out[4] = data4;
            mux_out[5] = data5;
        end
        3'b010: begin
            mux_out[0] = data2;
            mux_out[1] = data0;
            mux_out[2] = data1;
            mux_out[3] = data3;
            mux_out[4] = data4;
            mux_out[5] = data5;
        end
        3'b011: begin
            mux_out[0] = data3;
            mux_out[1] = data0;
            mux_out[2] = data1;
            mux_out[3] = data2;
            mux_out[4] = data4;
            mux_out[5] = data5;
        end
        3'b100: begin
            mux_out[0] = data4;
            mux_out[1] = data0;
            mux_out[2] = data1;
            mux_out[3] = data2;
            mux_out[4] = data3;
            mux_out[5] = data5;
        end
        3'b101: begin
            mux_out[0] = data5;
            mux_out[1] = data0;
            mux_out[2] = data1;
            mux_out[3] = data2;
            mux_out[4] = data3;
            mux_out[5] = data4;
        end
        default: begin
            mux_out[0] = 4'b0000;
            mux_out[1] = 4'b0000;
            mux_out[2] = 4'b0000;
            mux_out[3] = 4'b0000;
            mux_out[4] = 4'b0000;
            mux_out[5] = 4'b0000;
        end
    endcase
end

always @(*) begin
    highest_priority = 3'b000;
    if (mux_out[5] > 4'b0000) begin
        highest_priority = 3'b101;
    end else if (mux_out[4] > 4'b0000) begin
        highest_priority = 3'b100;
    end else if (mux_out[3] > 4'b0000) begin
        highest_priority = 3'b011;
    end else if (mux_out[2] > 4'b0000) begin
        highest_priority = 3'b010;
    end else if (mux_out[1] > 4'b0000) begin
        highest_priority = 3'b001;
    end else if (mux_out[0] > 4'b0000) begin
        highest_priority = 3'b000;
    end
end

always @(*) begin
    case(highest_priority)
        3'b000: begin
            selected_input = 3'b000;
        end
        3'b001: begin
            selected_input = 3'b001;
        end
        3'b010: begin
            selected_input = 3'b010;
        end
        3'b011: begin
            selected_input = 3'b011;
        end
        3'b100: begin
            selected_input = 3'b100;
        end
        3'b101: begin
            selected_input = 3'b101;
        end
        default: begin
            selected_input = 3'b000;
        end
    endcase
end

always @(*) begin
    case(selected_input)
        3'b000: begin
            out = mux_out[0];
        end
        3'b001: begin
            out = mux_out[1];
        end
        3'b010: begin
            out = mux_out[2];
        end
        3'b011: begin
            out = mux_out[3];
        end
        3'b100: begin
            out = mux_out[4];
        end
        3'b101: begin
            out = mux_out[5];
        end
        default: begin
            out = 4'b0000;
        end
    endcase
end

endmodule

module motor_control_block (
  input clk,
  input [7:0] duty,
  input dir,
  input step,
  output reg [1:0] motor_ctrl,
  output reg [3:0] step_ctrl
);

  pwm_controller pwm_inst (
    .clk(clk),
    .duty(duty),
    .pwm_out(motor_ctrl[1])
  );

  h_bridge_driver h_bridge_inst (
    .pwm_in(motor_ctrl[1]),
    .dir_in(dir),
    .motor_ctrl_out(motor_ctrl)
  );

  stepper_motor_controller stepper_inst (
    .motor_ctrl_in(motor_ctrl),
    .step_in(step),
    .step_ctrl_out(step_ctrl)
  );

endmodule

module pwm_controller (
  input clk,
  input [7:0] duty,
  output reg pwm_out
);

  reg [7:0] counter;

  always @(posedge clk) begin
    if (counter < duty) begin
      pwm_out <= 1;
    end else begin
      pwm_out <= 0;
    end

    counter <= counter + 1;
  end

endmodule

module h_bridge_driver (
  input pwm_in,
  input dir_in,
  output reg [1:0] motor_ctrl_out
);

  always @(*) begin
    if (dir_in) begin
      motor_ctrl_out <= 2'b10; // forward
    end else begin
      motor_ctrl_out <= 2'b01; // reverse
    end
  end

endmodule

module stepper_motor_controller (
  input [1:0] motor_ctrl_in,
  input step_in,
  output reg [3:0] step_ctrl_out
);

  reg [3:0] step_counter;

  always @(posedge motor_ctrl_in[0]) begin
    if (motor_ctrl_in[1] == 2'b10) begin // forward
      step_counter <= step_counter + 1;
    end else begin // reverse
      step_counter <= step_counter - 1;
    end
  end

  always @(posedge step_in) begin
    case (step_counter[1:0])
      2'b00: step_ctrl_out <= 4'b0001;
      2'b01: step_ctrl_out <= 4'b0010;
      2'b10: step_ctrl_out <= 4'b0100;
      2'b11: step_ctrl_out <= 4'b1000;
    endcase
  end

endmodule

module newton_raphson (
    input [15:0] a,
    input ready,
    input [1:0] iterations,
    output reg valid,
    output reg [15:0] result
);

reg [15:0] x;
reg [15:0] x_next;
reg [15:0] temp;
reg [1:0] count;

always @ (posedge ready) begin
    x <= a;
    count <= 0;
end

always @ (posedge ready) begin
    if (count < iterations) begin
        temp = x_next;
        x_next = (x + (a / x)) / 2;
        x = temp;
        count = count + 1;
    end
end

always @ (posedge ready) begin
    if (count == iterations) begin
        valid = 1;
        result = x_next;
    end else begin
        valid = 0;
    end
end

endmodule

module top_module (
    input clk,
    input reset, // Synchronous active-high reset
    input [2:0] sel, // Select inputs for the multiplexer
    input [3:0] data, // Data inputs for the multiplexer
    output q, // Output from the flip-flop
    output [3:0] mux_out, // Output from the multiplexer
    output final_output // Output from the additive functional module
);

    // 3-input, 4-output multiplexer
    mux3to4 mux_inst (
        .sel(sel),
        .data_in(data),
        .data_out(mux_out)
    );

    // Dual-edge triggered flip-flop
    reg [1:0] count;
    always @(posedge clk, negedge reset) begin
        if (reset == 0) begin
            count <= 2'b00;
        end else begin
            count <= count + 1;
        end
    end
    assign q = count[1];

    // Additive functional module
    assign final_output = (count >= mux_out) ? 1'b1 : 1'b0;

endmodule

// 3-input, 4-output multiplexer
module mux3to4 (
    input [2:0] sel,
    input [3:0] data_in,
    output reg [3:0] data_out
);
    always @(*) begin
        case (sel)
            3'b000: data_out = data_in[0];
            3'b001: data_out = data_in[1];
            3'b010: data_out = data_in[2];
            3'b011: data_out = data_in[3];
            3'b100: data_out = data_in[0];
            3'b101: data_out = data_in[1];
            3'b110: data_out = data_in[2];
            3'b111: data_out = data_in[3];
        endcase
    end
endmodule

module ALU(
    input [7:0] A,
    input [7:0] B,
    input C_IN,
    input [3:0] Sel,
    output [7:0] SUM,
    output C_FLAG,
    output Z_FLAG
);

wire [7:0] result;
wire [8:0] carry;
wire zero;

assign carry[0] = C_IN;
assign zero = (result == 0);

always @(*) begin
    case (Sel)
        4'b0000: result = A + B;
        4'b0001: result = A - B;
        4'b0010: result = A & B;
        4'b0011: result = A | B;
        4'b0100: result = A ^ B;
        4'b0101: result = {A[6:0], 1'b0};
        4'b0110: result = {1'b0, A[7:1]};
        4'b0111: result = ~(A | B);
        4'b1000: result = ~(A & B);
        4'b1001: result = ~(A ^ B);
        4'b1010: result = A + B + C_IN;
        4'b1011: result = A - B - C_IN;
        4'b1100: result = A | B | C_IN;
        4'b1101: result = A & B & C_IN;
        4'b1110: result = A ^ B ^ C_IN;
        4'b1111: result = A << B[2:0];
    endcase
end

assign SUM = result;
assign C_FLAG = carry[8];
assign Z_FLAG = zero;

endmodule

module mux_adder (
    input [3:0] a,
    input [3:0] b,
    input cin,
    input [3:0] in0,
    input [3:0] in1,
    input [3:0] in2,
    input [3:0] in3,
    input [3:0] in4,
    input [3:0] in5,
    input [3:0] in6,
    input [3:0] in7,
    input [2:0] sel,
    output [3:0] out
);

// 8-to-1 Multiplexer
wire [3:0] mux_out;
assign mux_out = (sel == 3'b000) ? in0 :
                 (sel == 3'b001) ? in1 :
                 (sel == 3'b010) ? in2 :
                 (sel == 3'b011) ? in3 :
                 (sel == 3'b100) ? in4 :
                 (sel == 3'b101) ? in5 :
                 (sel == 3'b110) ? in6 :
                                   in7;

// Ripple Carry Adder
wire [3:0] sum;
wire cout;
ripple_adder adder(a, b, cin, sum, cout);

// Functional Module
wire [7:0] mux_adder_out;
assign mux_adder_out = {mux_out, sum};
assign out = mux_adder_out[sel*4 +: 4];

endmodule

module ripple_adder (
    input [3:0] a,
    input [3:0] b,
    input cin,
    output [3:0] sum,
    output cout
);

wire [3:0] sum_wire;
wire [3:0] carry_out;
assign sum_wire = a + b + cin;
assign sum = sum_wire;
assign cout = carry_out[3];

genvar i;
generate
    for (i = 0; i < 4; i = i + 1) begin : carry_gen
        full_adder adder(
            a[i], b[i], carry_out[i], sum_wire[i], carry_out[i+1]
        );
    end
endgenerate

endmodule

module full_adder (
    input a,
    input b,
    input cin,
    output sum,
    output cout
);

assign sum = a ^ b ^ cin;
assign cout = (a & b) | (a & cin) | (b & cin);

endmodule

