module fric_client_xactor
  (
   clk,
   rst,

   slave_addr,
   slave_wdat,
   slave_wstb,
   slave_rdat,

   master_type,
   master_port,
   master_addr,
   master_wdat,
   master_tstb,
   master_trdy,

   master_rstb,
   master_rdat

   );

   input           clk;
   input 	   rst;
   input [7:0] 	   slave_addr;
   input [15:0]    slave_wdat;
   input 	   slave_wstb;
   output reg [15:0]   slave_rdat;
   output reg [3:0]    master_type;
   output reg [3:0]    master_port;
   output reg [7:0]    master_addr;
   output reg [15:0]   master_wdat;
   output reg 	   master_tstb;
   input 	   master_trdy;
   input 	   master_rstb;
   input [15:0]    master_rdat;

   reg [15:0] 	   slave_rdat_o;
   reg [3:0] 	   master_type_o;
   reg [3:0] 	   master_port_o;
   reg [7:0] 	   master_addr_o;
   reg [15:0] 	   master_wdat_o;
   reg 		   master_tstb_o;

   assign #1 slave_rdat = slave_rdat_o;
   assign #1 master_type = master_type_o;
   assign #1 master_port = master_port_o;
   assign #1 master_addr = master_addr_o;
   assign #1 master_wdat = master_wdat_o;
   assign #1 master_tstb = master_tstb_o;

   always @(posedge clk) begin
      if (rst) begin
         slave_rdat_o <= 0;
         master_type_o <= 0;
         master_port_o <= 0;
         master_addr_o <= 0;
         master_wdat_o <= 0;
         master_tstb_o <= 0;
      end else begin
         if (slave_wstb) begin
            // Perform a write operation to the slave device
            // at the specified address
            $display("Slave write: addr=%h, data=%h", slave_addr, slave_wdat);
         end else begin
            // Perform a read operation from the slave device
            // at the specified address
            $display("Slave read: addr=%h", slave_addr);
            slave_rdat_o <= 16'hAAAA;
         end

         if (master_trdy && master_tstb_o) begin
            // The master device has accepted the write operation
            master_tstb_o <= 0;
            $display("Master write: type=%d, port=%d, addr=%h, data=%h", master_type_o, master_port_o, master_addr_o, master_wdat_o);
         end else if (master_tstb) begin
            // The master device is requesting a write operation
            master_type_o <= master_type;
            master_port_o <= master_port;
            master_addr_o <= master_addr;
            master_wdat_o <= master_wdat;
            master_tstb_o <= 1;
         end else begin
            // The master device is requesting a read operation
            $display("Master read: type=%d, port=%d, addr=%h", master_type, master_port, master_addr);
            master_rdat <= 16'hBBBB;
         end
      end
   end

endmodule

module axi_protocol_converter (
  input wire clk,
  input wire reset,
  input wire s_arvalid,
  input wire [7:0] s_arlen,
  input wire m_arready,
  input wire next_pending,
  input wire data_ready,
  output wire s_arready,
  output wire m_arvalid,
  output wire next,
  output wire a_push,
  output wire r_push
);

localparam SM_IDLE = 2'b00;
localparam SM_CMD_EN = 2'b01;
localparam SM_CMD_ACCEPTED = 2'b10;
localparam SM_DONE = 2'b11;

reg [1:0] state = SM_IDLE;
reg [1:0] state_r1 = SM_IDLE;
reg [1:0] next_state;
reg [7:0] s_arlen_r;

always @(posedge clk) begin
  if (reset) begin
    state <= SM_IDLE;
    state_r1 <= SM_IDLE;
    s_arlen_r <= 0;
  end else begin
    state <= next_state;
    state_r1 <= state;
    s_arlen_r <= s_arlen;
  end
end

always @(*) begin
  next_state = state;
  case (state)
    SM_IDLE:
      if (s_arvalid && data_ready) begin
        next_state = SM_CMD_EN;
      end else begin
        next_state = state;
      end
    SM_CMD_EN:
      if (~data_ready && m_arready && next_pending) begin
        next_state = SM_CMD_ACCEPTED;
      end else if (m_arready && ~next_pending) begin
        next_state = SM_DONE;
      end else if (m_arready && next_pending) begin
        next_state = SM_CMD_EN;
      end else begin
        next_state = state;
      end
    SM_CMD_ACCEPTED:
      if (data_ready) begin
        next_state = SM_CMD_EN;
      end else begin
        next_state = state;
      end
    SM_DONE:
      next_state = SM_IDLE;
    default:
      next_state = SM_IDLE;
  endcase
end

assign m_arvalid = (state == SM_CMD_EN);
assign next = m_arready && (state == SM_CMD_EN);
assign r_push = next;
assign a_push = (state == SM_IDLE);
assign s_arready = ((state == SM_CMD_EN) || (state == SM_DONE)) && (next_state == SM_IDLE);

endmodule

module shift_register (
