    input [2:0] b,
    output [5:0] out_not,
    output [2:0] out_or_bitwise,
    output out_or_logical
);

    assign out_or_bitwise = a | b;
    assign out_or_logical = (a != 0) || (b != 0);
    assign out_not = {~b, ~a};

endmodule

module control_logic (
    input select,
    input [2:0] a,
    input [2:0] b,
    input data,
    output [3:0] shift_out,
    output [2:0] out_or_bitwise,
    output out_or_logical,
    output [5:0] out_not,
    output [3:0] final_output
);

    wire [5:0] not_out;
    wire [2:0] or_bitwise_out;
    wire or_logical_out;

    bitwise_or_logical_or_inverter bitwise_or_logical_or_inverter_inst(
        .a(a),
        .b(b),
        .out_not(not_out),
        .out_or_bitwise(or_bitwise_out),
        .out_or_logical(or_logical_out)
    );

    shift_register shift_register_inst(
        .clk(1'b1),
        .reset(1'b0),
        .data_in(data),
        .data_out(shift_out)
    );

    assign final_output = shift_out & or_bitwise_out;

    always @(select) begin
        if (select == 1'b0) begin
            shift_register_inst.clk = 1'b1;
            shift_register_inst.reset = 1'b0;
            bitwise_or_logical_or_inverter_inst.a = 3'b0;
            bitwise_or_logical_or_inverter_inst.b = 3'b0;
        end else begin
            shift_register_inst.clk = 1'b0;
            shift_register_inst.reset = 1'b1;
            bitwise_or_logical_or_inverter_inst.a = a;
            bitwise_or_logical_or_inverter_inst.b = b;
        end
    end

    assign out_not = not_out;
    assign out_or_bitwise = or_bitwise_out;
    assign out_or_logical = or_logical_out;

endmodule

