module clock_divider (
  input clk,
  input nreset,
  input clkchange,
  input clken,
  input [7:0] clkdiv,
  input [15:0] clkphase0,
  input [15:0] clkphase1,
  output reg clkout0,
  output reg clkrise0,
  output reg clkfall0,
  output reg clkout1,
  output reg clkrise1,
  output reg clkfall1,
  output reg clkstable
);

  // Define registers and wires
  reg [7:0] counter;
  reg [2:0] period;
  reg clkout0_reg;
  reg clkout1_reg;
  reg clkout1_shift;
  wire period_match;
  wire [3:0] clk1_sel;
  wire [3:0] clk1_sel_sh;
  wire [1:0] clk0_sel;
  wire [1:0] clk0_sel_sh;

  // Change detect (count 8 periods)
  always @(posedge clk or negedge nreset) begin
    if (!nreset) begin
      period[2:0] <= 3'b0;
    end else if (clkchange) begin
      period[2:0] <= 3'b0;
    end else if (period_match & ~clkstable) begin
      period[2:0] <= period[2:0] + 1'b1;
    end
  end

  assign clkstable = (period[2:0] == 3'b111);

  // Cycle counter
  always @(posedge clk or negedge nreset) begin
    if (!nreset) begin
      counter[7:0] <= 8'b0;
    end else if (clken) begin
      if (period_match) begin
        counter[7:0] <= 8'b0;
      end else begin
        counter[7:0] <= counter[7:0] + 1'b1;
      end
    end
  end

  assign period_match = (counter[7:0] == clkdiv[7:0]);

  // Rising/falling edge selectors
  assign clkrise0 = (counter[7:0] == clkphase0[7:0]);
  assign clkfall0 = (counter[7:0] == clkphase0[15:8]);
  assign clkrise1 = (counter[7:0] == clkphase1[7:0]);
  assign clkfall1 = (counter[7:0] == clkphase1[15:8]);

  // CLKOUT0
  always @(posedge clk or negedge nreset) begin
    if (!nreset) begin
      clkout0_reg <= 1'b0;
    end else if (clkrise0) begin
      clkout0_reg <= 1'b1;
    end else if (clkfall0) begin
      clkout0_reg <= 1'b0;
    end
  end

  // Clock mux
  assign clk0_sel[1] = (clkdiv[7:0] == 8'd0);
  assign clk0_sel[0] = ~(clkdiv[7:0] == 8'd0);

  oh_lat0 #(.DW(2)) latch_clk0 (
    .out(clk0_sel_sh[1:0]),
    .clk(clk),
    .in(clk0_sel[1:0])
  );

  oh_clockmux #(.N(2)) mux_clk0 (
    .clkout(clkout0),
    .en(clk0_sel[1:0]),
    .clkin({clk, clkout0_reg})
  );

  // CLKOUT1
  always @(posedge clk or negedge nreset) begin
    if (!nreset) begin
      clkout1_reg <= 1'b0;
    end else if (clkrise1) begin
      clkout1_reg <= 1'b1;
    end else if (clkfall1) begin
      clkout1_reg <= 1'b0;
    end
  end

  // Creating divide by 2 shifted clock with negedge
  always @(negedge clk) begin
    clkout1_shift <= clkout1_reg;
  end

  // Clock mux
  assign clk1_sel[3] = 1'b0;
  assign clk1_sel[2] = (clkdiv[7:0] == 8'd0);
  assign clk1_sel[1] = (clkdiv[7:0] == 8'd1);
  assign clk1_sel[0] = |clkdiv[7:1];

  oh_lat0 #(.DW(4)) latch_clk1 (
    .out(clk1_sel_sh[3:0]),
    .clk(clk),
    .in(clk1_sel[3:0])
  );

  oh_clockmux #(.N(4)) mux_clk1 (
    .clkout(clkout1),
    .en(clk1_sel[3:0]),
    .clkin({1'b0, clk, clkout1_shift, clkout1_reg})
  );

endmodule

