module binary_search (
    input clk,
    input rst,
    input [31:0] array [0:255],
    input [7:0] size,
    input [31:0] value,
    output reg [7:0] index
);

    reg [7:0] low = 0;
    reg [7:0] high = size - 1;
    reg [7:0] mid;
    reg [31:0] temp;

    always @(posedge clk) begin
        if (rst) begin
            index <= -1;
            low <= 0;
            high <= size - 1;
        end else begin
            if (low <= high) begin
                mid <= (low + high) / 2;
                temp <= array[mid];
                if (temp == value) begin
                    index <= mid;
                    low <= 0;
                    high <= size - 1;
                end else if (temp > value) begin
                    high <= mid - 1;
                end else begin
                    low <= mid + 1;
                end
            end else begin
                index <= -1;
                low <= 0;
                high <= size - 1;
            end
        end
    end

endmodule

