module top_module (
    input clk,
    input reset,
    output reg [3:0] binary_count,
    output reg [1:0] gray_code_count,
    output reg [5:0] sum
); 

    binary_counter binary_counter_inst (
        .clk(clk),
        .reset(reset),
        .count(binary_count)
    );

    gray_code_counter gray_code_counter_inst (
        .clk(clk),
        .reset(reset),
        .count(gray_code_count)
    );

    always @(posedge clk) begin
        if (reset) begin
            sum <= 6'b000000;
        end else begin
            // Convert gray code to binary
            case (gray_code_count)
                2'b00: sum <= {2'b00, binary_count};
                2'b01: sum <= {2'b01, binary_count};
                2'b10: sum <= {2'b11, binary_count};
                2'b11: sum <= {2'b10, binary_count};
            endcase

            // Add binary counts
            sum <= sum + binary_count;

            // Convert binary to gray code
            case (sum[5:4])
                2'b00: sum[5:4] <= 2'b00;
                2'b01: sum[5:4] <= 2'b01;
                2'b10: sum[5:4] <= 2'b11;
                2'b11: sum[5:4] <= 2'b10;
            endcase
        end
    end
endmodule

