    input reset,
    input Up,
    input Down,
    input Load,
    input [7:0] D,
    output reg [7:0] Q
);

reg [7:0] next_Q;

always @(posedge clk) begin
    if(reset) begin
        Q <= 8'b00000000;
    end else if(Load) begin
        Q <= D;
    end else if(Up) begin
        next_Q = Q + 1;
        Q <= next_Q;
    end else if(Down) begin
        next_Q = Q - 1;
        Q <= next_Q;
    end
end

endmodule

