module pipelined_decade_counter (
    input clk,
    input slowena,
    input reset,
    output reg [3:0] q
);

    // Define states for the finite state machine
    parameter IDLE = 2'b00;
    parameter COUNT = 2'b01;
    parameter HOLD = 2'b10;

    // Define pipeline registers
    reg [3:0] q_reg1;
    reg [3:0] q_reg2;
    reg [1:0] state_reg;

    // Define combinational logic for next state and output
    always @ (posedge clk) begin
        // Update pipeline registers
        q_reg2 <= q_reg1;
        q_reg1 <= q;

        // Update state based on current state and inputs
        case (state_reg)
            IDLE: begin
                if (reset) begin
                    state_reg <= IDLE;
                    q <= 4'b0000;
                end else if (slowena) begin
                    state_reg <= HOLD;
                    q <= q;
                end else begin
                    state_reg <= COUNT;
                    q <= q + 1;
                end
            end
            COUNT: begin
                if (slowena) begin
                    state_reg <= HOLD;
                    q <= q;
                end else if (q == 4'b1001) begin
                    state_reg <= IDLE;
                    q <= 4'b0000;
                end else begin
                    state_reg <= COUNT;
                    q <= q + 1;
                end
            end
            HOLD: begin
                if (reset) begin
                    state_reg <= IDLE;
                    q <= 4'b0000;
                end else if (!slowena) begin
                    state_reg <= COUNT;
                    q <= q_reg2 + 1;
                end else begin
                    state_reg <= HOLD;
                    q <= q;
                end
            end
        endcase
    end

    // Initialize pipeline registers and state
    initial begin
        q_reg1 <= 4'b0000;
        q_reg2 <= 4'b0000;
        state_reg <= IDLE;
    end

endmodule

module top_module (
