module display(
    input clk,
    input [15:0] disp_num,
    output reg [6:0] seg,
    output reg [3:0] anode
);

    reg [26:0] tick;
    reg [1:0] an;
    reg [3:0] num;

    // initialize anode and tick
    initial begin
        an <= 2'b00;
        tick <= 0;
    end

    // increment tick on each clock cycle
    always @(posedge clk) begin
        tick <= tick + 1;
    end

    // increment anode every 1ms
    always @(posedge tick[20]) begin
        an <= an + 1;
    end

    // update anode and segment values based on current anode and input number
    always @* begin
        case(an)
            2'b00: num = disp_num[3:0];
            2'b01: num = disp_num[7:4];
            2'b10: num = disp_num[11:8];
            2'b11: num = disp_num[15:12];
            default:;
        endcase

        case(num)
            4'h0 : seg = 7'b1000000;
            4'h1 : seg = 7'b1111001;
            4'h2 : seg = 7'b0100100;
            4'h3 : seg = 7'b0110000;
            4'h4 : seg = 7'b0011001;
            4'h5 : seg = 7'b0010010;
            4'h6 : seg = 7'b0000010;
            4'h7 : seg = 7'b1111000;
            4'h8 : seg = 7'b0000000;
            4'h9 : seg = 7'b0010000;
            4'hA : seg = 7'b0001000;
            4'hB : seg = 7'b0000011;
            4'hC : seg = 7'b1000110;
            4'hD : seg = 7'b0100001;
            4'hE : seg = 7'b0000110;
            4'hF : seg = 7'b0001110;
            default : seg = 7'bxxxxxxx; // invalid input, display "blank"
        endcase

        anode = ~(4'b1 << an);
    end

endmodule

module axis_keyer #
(
  parameter integer AXIS_TDATA_WIDTH = 32,
  parameter integer BRAM_DATA_WIDTH = 32,
  parameter integer BRAM_ADDR_WIDTH = 10
)
(
  // System signals
  input  wire                        aclk,
  input  wire                        aresetn,

  input  wire [BRAM_ADDR_WIDTH-1:0]  cfg_data,
  input  wire                        key_flag,

  // Master side
  input  wire                        m_axis_tready,
  output wire [AXIS_TDATA_WIDTH-1:0] m_axis_tdata,
  output wire                        m_axis_tvalid,

  // BRAM port
  output wire                        bram_porta_clk,
  output wire                        bram_porta_rst,
  output wire [BRAM_ADDR_WIDTH-1:0]  bram_porta_addr,
  input  wire [BRAM_DATA_WIDTH-1:0]  bram_porta_rddata
);

  reg [BRAM_ADDR_WIDTH-1:0] int_addr_reg, int_addr_next;
  reg [BRAM_ADDR_WIDTH-1:0] int_data_reg;
  reg [1:0] int_case_reg, int_case_next;

  wire [1:0] int_comp_wire;

  always @(posedge aclk)
  begin
    if(~aresetn)
    begin
      int_addr_reg <= {(BRAM_ADDR_WIDTH){1'b0}};
      int_data_reg <= {(BRAM_ADDR_WIDTH){1'b0}};
      int_case_reg <= 2'd0;
    end
    else
    begin
      int_addr_reg <= int_addr_next;
      int_data_reg <= cfg_data;
      int_case_reg <= int_case_next;
    end
  end

  assign int_comp_wire = {|int_addr_reg, int_addr_reg < int_data_reg};

  always @*
  begin
    int_addr_next = int_addr_reg;
    int_case_next = int_case_reg;

    case(int_case_reg)
      2'd0:
      begin
        if(key_flag & int_comp_wire[0])
        begin
          int_case_next = 2'd1;
        end
      end
      2'd1:
      begin
        if(m_axis_tready)
        begin
          if(int_comp_wire[0])
          begin
            int_addr_next = int_addr_reg + 1'b1;
          end
          else
          begin
            int_case_next = 2'd2;
          end
        end
      end
      2'd2:
      begin
        if(~key_flag)
        begin
          int_case_next = 2'd3;
        end
      end
      2'd3:
      begin
        if(m_axis_tready)
        begin
          if(int_comp_wire[1])
          begin
            int_addr_next = int_addr_reg - 1'b1;
          end
          else
          begin
            int_case_next = 2'd0;
          end
        end
      end
    endcase
  end

  assign m_axis_tdata = bram_porta_rddata;
  assign m_axis_tvalid = 1'b1;

  assign bram_porta_clk = aclk;
  assign bram_porta_rst = ~aresetn;
  assign bram_porta_addr = m_axis_tready ? int_addr_next : int_addr_reg;

endmodule

