module top_module( 
    input [254:0] in,
    input [3:0] in1,
    input [3:0] in2,
    input [3:0] in3,
    input [3:0] in4,
    output [7:0] out );

    // Split input vector into smaller chunks
    wire [7:0] count1, count2, count3, count4;
    parallel_prefix_adder p1(.in(in[7:0]), .out(count1));
    parallel_prefix_adder p2(.in(in[15:8]), .out(count2));
    parallel_prefix_adder p3(.in(in[23:16]), .out(count3));
    parallel_prefix_adder p4(.in(in[31:24]), .out(count4));

    // Add '1' counts in parallel
    wire [9:0] sum;
    assign sum = count1 + count2 + count3 + count4;

    // Perform bitwise AND, OR, and XOR on four 4-bit binary numbers
    wire [3:0] and_result, or_result, xor_result;
    bitwise_operations b1(.in1(in1), .in2(in2), .in3(in3), .in4(in4), .and_result(and_result), .or_result(or_result), .xor_result(xor_result));

    // Perform bitwise AND operation on the outputs of the two given modules
    wire [7:0] and_output;
    assign and_output = sum & (and_result << 4);

    // Output the final result
    assign out = and_output;

endmodule

// Parallel prefix adder module
module parallel_prefix_adder(
    input [7:0] in,
    output [7:0] out
);
    wire [7:0] p0, p1, p2, p3, p4, p5, p6, p7;

    assign p0 = in;
    assign p1 = {p0[0], p0[0] ^ p0[1], p0[1] ^ p0[2], p0[2] ^ p0[3], p0[3] ^ p0[4], p0[4] ^ p0[5], p0[5] ^ p0[6], p0[6] ^ p0[7]};
    assign p2 = {p1[0], p1[0] ^ p1[1], p1[1] ^ p1[2], p1[2] ^ p1[3], p1[3] ^ p1[4], p1[4] ^ p1[5], p1[5] ^ p1[6], p1[6] ^ p1[7]};
    assign p3 = {p2[0], p2[0] ^ p2[1], p2[1] ^ p2[2], p2[2] ^ p2[3], p2[3] ^ p2[4], p2[4] ^ p2[5], p2[5] ^ p2[6], p2[6] ^ p2[7]};
    assign p4 = {p3[0], p3[0] ^ p3[1], p3[1] ^ p3[2], p3[2] ^ p3[3], p3[3] ^ p3[4], p3[4] ^ p3[5], p3[5] ^ p3[6], p3[6] ^ p3[7]};
    assign p5 = {p4[0], p4[0] ^ p4[1], p4[1] ^ p4[2], p4[2] ^ p4[3], p4[3] ^ p4[4], p4[4] ^ p4[5], p4[5] ^ p4[6], p4[6] ^ p4[7]};
    assign p6 = {p5[0], p5[0] ^ p5[1], p5[1] ^ p5[2], p5[2] ^ p5[3], p5[3] ^ p5[4], p5[4] ^ p5[5], p5[5] ^ p5[6], p5[6] ^ p5[7]};
    assign p7 = {p6[0], p6[0] ^ p6[1], p6[1] ^ p6[2], p6[2] ^ p6[3], p6[3] ^ p6[4], p6[4] ^ p6[5], p6[5] ^ p6[6], p6[6] ^ p6[7]};

    assign out = p7;

endmodule

// Bitwise operations module
module bitwise_operations(
    input [3:0] in1,
    input [3:0] in2,
    input [3:0] in3,
    input [3:0] in4,
    output [3:0] and_result,
