);

    // Define internal signals
    reg [3:0] count;
    wire [3:0] SUM;
    wire COUT;

    // Instantiate ripple carry adder and binary counter modules
    ripple_carry_adder adder_inst (.A(A), .B(B), .CIN(CIN), .SUM(SUM), .COUT(COUT));
    binary_counter counter_inst (.clk(clk), .reset(reset), .enable(enable), .count(count));

    // Output sum of ripple carry adder and binary counter
    assign output_sum = SUM + count;

endmodule

module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    input CIN,
    output [3:0] SUM,
    output COUT
);

    // Define internal signals
    wire [3:0] sum;
    wire carry;

    // Generate sum and carry signals for each bit
    assign sum[0] = A[0] ^ B[0] ^ CIN;
    assign carry = (A[0] & B[0]) | (A[0] & CIN) | (B[0] & CIN);
    assign sum[1] = A[1] ^ B[1] ^ carry;
    assign carry = (A[1] & B[1]) | (A[1] & carry) | (B[1] & carry);
    assign sum[2] = A[2] ^ B[2] ^ carry;
    assign carry = (A[2] & B[2]) | (A[2] & carry) | (B[2] & carry);
    assign sum[3] = A[3] ^ B[3] ^ carry;
    assign COUT = (A[3] & B[3]) | (A[3] & carry) | (B[3] & carry);

    // Output sum and carry-out
    assign SUM = sum;

endmodule

