module top_module (
    input signed [15:0] multiplier,
    input signed [31:0] multiplicand,
    input [4:0] shift_amount,
    output reg signed [31:0] output_result
);

    // Multiplication module
    wire signed [47:0] multiplication_result;
    multiplier_16bit multiplier_inst(
        .a(multiplier),
        .b(multiplicand),
        .p(multiplication_result)
    );

    // Barrel shifter module
    wire signed [47:0] shifted_result;
    barrel_shifter_48bit barrel_shifter_inst(
        .a(multiplication_result),
        .b(shift_amount),
        .p(shifted_result)
    );

    // Comparator module
    wire is_greater_than_or_equal_to;
    comparator_32bit comparator_inst(
        .a(shifted_result[31:0]),
        .b(multiplicand),
        .p(is_greater_than_or_equal_to)
    );

    // Output result selection
    always @(*) begin
        if (is_greater_than_or_equal_to) begin
            output_result <= shifted_result[31+shift_amount:shift_amount];
        end else begin
            output_result <= shift_amount > 0 ? shift_amount >> 1 : 0;
        end
    end

endmodule

module multiplier_16bit (
    input signed [15:0] a,
    input signed [31:0] b,
    output reg signed [47:0] p
);
