module barrel_shifter_48bit (
    input signed [47:0] a,
    input [4:0] b,
    output reg signed [47:0] p
);
    always @(*) begin
        p <= b == 0 ? a : b > 47 ? 0 : {a[47-b+1:0], {b{1'b0}}};
    end
endmodule

module comparator_32bit (
    input signed [31:0] a,
    input signed [31:0] b,
    output reg is_greater_than_or_equal_to
);
    always @(*) begin
        is_greater_than_or_equal_to <= a >= b;
