module traffic_light(
    input clk,
    input reset,
    input car_sensor_road1_lane1,
    input car_sensor_road1_lane2,
    input car_sensor_road2_lane1,
    input car_sensor_road2_lane2,
    input pedestrian_sensor,
    output reg [3:0] traffic_light_road1,
    output reg [3:0] traffic_light_road2,
    output reg pedestrian_light
);

parameter S0 = 2'b00, S1 = 2'b01, S2 = 2'b10, S3 = 2'b11;
parameter GREEN_TIME = 5, PEDESTRIAN_TIME = 10, YELLOW_TIME = 2;

reg [1:0] state;
reg [3:0] timer;
reg [1:0] current_road1_lane;
reg [1:0] current_road2_lane;

always @(posedge clk) begin
    if (reset) begin
        state <= S0;
        timer <= 0;
        current_road1_lane <= 2'b00;
        current_road2_lane <= 2'b00;
        traffic_light_road1 <= 4'b0100;
        traffic_light_road2 <= 4'b0100;
        pedestrian_light <= 1'b0;
    end else begin
        case (state)
            S0: begin
                if (timer == 0) begin
                    if (pedestrian_sensor) begin
                        state <= S1;
                        timer <= PEDESTRIAN_TIME;
                        pedestrian_light <= 1'b1;
                        traffic_light_road1 <= {2'b10, 2'b01};
                        traffic_light_road2 <= {2'b00, 2'b10};
                    end else if (car_sensor_road1_lane1 || car_sensor_road1_lane2) begin
                        state <= S1;
                        timer <= GREEN_TIME;
                        current_road1_lane <= 2'b01;
                        traffic_light_road1 <= {2'b10, 2'b01};
                        traffic_light_road2 <= {2'b00, 2'b10};
                    end else if (car_sensor_road2_lane1 || car_sensor_road2_lane2) begin
                        state <= S2;
                        timer <= YELLOW_TIME;
                        traffic_light_road1 <= {2'b10, 2'b00};
                        traffic_light_road2 <= {2'b01, 2'b00};
                    end
                end else begin
                    timer <= timer - 1;
                end
            end
            S1: begin
                if (timer == 0) begin
                    state <= S2;
                    timer <= YELLOW_TIME;
                    traffic_light_road1 <= {2'b10, 2'b00};
                    traffic_light_road2 <= {2'b01, 2'b00};
                end else begin
                    timer <= timer - 1;
                end
            end
            S2: begin
                if (timer == 0) begin
                    if (pedestrian_sensor) begin
                        state <= S3;
                        timer <= PEDESTRIAN_TIME;
                        pedestrian_light <= 1'b1;
                        traffic_light_road1 <= {2'b00, 2'b10};
                        traffic_light_road2 <= {2'b10, 2'b01};
                    end else if (car_sensor_road2_lane1 || car_sensor_road2_lane2) begin
                        state <= S3;
                        timer <= GREEN_TIME;
                        current_road2_lane <= 2'b01;
                        traffic_light_road1 <= {2'b00, 2'b10};
                        traffic_light_road2 <= {2'b10, 2'b01};
                    end else if (car_sensor_road1_lane1 || car_sensor_road1_lane2) begin
                        state <= S1;
                        timer <= YELLOW_TIME;
                        traffic_light_road1 <= {2'b10, 2'b01};
                        traffic_light_road2 <= {2'b00, 2'b10};
                    end
                end else begin
                    timer <= timer - 1;
                end
            end
            S3: begin
                if (timer == 0) begin
                    state <= S0;
                    timer <= YELLOW_TIME;
                    traffic_light_road1 <= {2'b01, 2'b00};
                    traffic_light_road2 <= {2'b01, 2'b00};
                    pedestrian_light <= 1'b0;
                end else begin
                    timer <= timer - 1;
                end
            end
        endcase
    end
end

endmodule

module cross_clock_reader
    #(
        parameter WIDTH = 1,
        parameter DEFAULT = 0
    )
    (
        input clk, input rst,
        input [WIDTH-1:0] in,
        output reg [WIDTH-1:0] out
    );

    reg [WIDTH-1:0] shadow0, shadow1;
    reg [2:0] count;

    always @(posedge clk) begin
        if (rst) begin
            out <= DEFAULT;
            shadow0 <= DEFAULT;
            shadow1 <= DEFAULT;
            count <= 0;
        end
        else if (shadow0 == shadow1) count <= count + 1;
        else count <= 0;
        shadow0 <= in;
        shadow1 <= shadow0;
        if (count == 3'b111) out <= shadow1;
    end

endmodule

module add_sub_pipeline(
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] sum
);

    wire [15:0] a_low;
    wire [15:0] b_low;
    wire [15:0] sum_low;
    wire carry;

    // 16-bit adder module
    adder16 adder_inst(
        .a(a_low),
        .b(b_low),
        .carry_in(sub ? ~b[15] : 1'b0),
        .sum(sum_low),
        .carry_out(carry)
    );

    // XOR gate to invert b when sub is 1
    assign b_low = sub ? ~b[15:0] : b[15:0];

    // Pipeline registers
    reg [15:0] a_reg;
    reg [15:0] b_reg;
    reg sub_reg;
    reg [15:0] sum_reg;

    always @(posedge clk) begin
        a_reg <= a[15:0];
        b_reg <= b[15:0];
        sub_reg <= sub;
        sum_reg <= sum_low;
    end

    always @(posedge clk) begin
        a_low <= a_reg;
        b_low <= b_reg;
        sub <= sub_reg;
        sum <= sum_reg;
    end

endmodule

// 16-bit adder module
module adder16(
    input [15:0] a,
    input [15:0] b,
    input carry_in,
    output [15:0] sum,
    output carry_out
);

    wire [15:0] sum_temp;
    wire carry_temp;

    assign sum_temp = a + b + carry_in;
    assign carry_out = sum_temp[16];
    assign sum = sum_temp[15:0];

endmodule

module i2c_master (
  input clk,
  input rst,
  output sda_out,
  output scl_out,
  input [6:0] addr,
  input wr_en,
  input [7:0] data_in,
  output reg [7:0] data_out,
  output sda_in,
  output ack
);

  reg [3:0] state;
  reg [7:0] data_reg;
  reg [6:0] addr_reg;
  reg [2:0] bit_count;
  reg start;
  reg stop;
  reg [7:0] count;
  reg [7:0] ack_count;
  reg [7:0] ack_data;
  wire sda_in_int;

  assign sda_in = sda_in_int;

  assign sda_out = (state == 0) ? 1'b1 :
                   (state == 1) ? 1'b0 :
                   (state == 2) ? data_reg[bit_count] :
                   (state == 3) ? 1'b1 :
                   (state == 4) ? 1'b1 :
                   (state == 5) ? 1'b0 :
                   (state == 6) ? 1'b1 : 1'b1;

  assign scl_out = (state == 0) ? 1'b1 :
                   (state == 1) ? 1'b1 :
                   (state == 2) ? 1'b1 :
                   (state == 3) ? 1'b1 :
                   (state == 4) ? 1'b1 :
                   (state == 5) ? 1'b1 :
                   (state == 6) ? 1'b0 : 1'b1;

  always @(posedge clk) begin
    if (rst) begin
      state <= 0;
      data_reg <= 0;
      addr_reg <= 0;
      bit_count <= 0;
      start <= 0;
      stop <= 0;
      count <= 0;
      ack_count <= 0;
      ack_data <= 0;
    end else begin
      case (state)
        0: begin
          if (wr_en) begin
            start <= 1;
            state <= 1;
            addr_reg <= addr;
            bit_count <= 0;
          end
        end
        1: begin
          if (start) begin
            sda_in_int <= 1'b1;
            state <= 2;
          end
        end
        2: begin
          if (scl_out) begin
            sda_in_int <= addr_reg[6];
            addr_reg <= addr_reg << 1;
            bit_count <= bit_count + 1;
            if (bit_count == 7) begin
              if (wr_en) begin
                sda_in_int <= 1'b0;
                state <= 3;
              end else begin
                sda_in_int <= 1'b1;
                state <= 4;
              end
              bit_count <= 0;
            end
          end
        end
        3: begin
          if (scl_out) begin
            ack_count <= ack_count + 1;
            if (ack_count == 1) begin
              ack_data <= sda_in_int;
              ack <= ~ack_data;
            end else if (ack_count == 2) begin
              ack_count <= 0;
              if (bit_count == 8) begin
                if (stop) begin
                  state <= 0;
                end else begin
                  state <= 1;
                  addr_reg <= addr;
                  bit_count <= 0;
                end
              end else begin
                state <= 2;
              end
            end
          end
        end
        4: begin
          if (scl_out) begin
            ack_count <= ack_count + 1;
            if (ack_count == 1) begin
              ack_data <= sda_in_int;
              ack <= ~ack_data;
            end else if (ack_count == 2) begin
              ack_count <= 0;
              state <= 5;
            end
          end
        end
        5: begin
          if (scl_out) begin
            data_reg <= data_in;
            sda_in_int <= data_reg[bit_count];
            bit_count <= bit_count + 1;
            if (bit_count == 8) begin
              bit_count <= 0;
              ack_count <= 0;
              state <= 6;
            end
          end
        end
        6: begin
          if (scl_out) begin
            ack_count <= ack_count + 1;
            if (ack_count == 1) begin
              ack_data <= sda_in_int;
              ack <= ~ack_data;
            end else if (ack_count == 2) begin
              ack_count <= 0;
              if (stop) begin
                state <= 0;
              end else begin
                state <= 1;
                addr_reg <= addr;
                bit_count <= 0;
              end
            end
          end
        end
      endcase
    end
  end
endmodule

module pipeline_internal_fv (
// INTERFACE BEGIN
	clk,         // clock
	ena,         // clock enable
	clr,         // async clear
	d,           // data in
	piped        // output
);
// INTERFACE END
//// top level parameters ////
parameter data_width = 1;
parameter latency = 1;
//// port declarations ////

// data input ports
input  [data_width - 1 : 0] d;

// control signals
input clk,ena,clr;

// output ports
output [data_width - 1 : 0] piped;

wire [data_width-1 : 0] out;
wire [data_width*(latency-1) : 1] t;
wire [data_width*latency-1 : 0] d_w;

assign piped = out;

//// nets/registers ////

// IMPLEMENTATION BEGIN
generate
if(latency==0) begin
	assign out = d;
end
else if(latency==1) begin
	assign d_w = ena? d : out;
	dff_bus #(data_width) p (.q(out), .clk(clk), .d(d_w), .clr(clr));
end
else begin
	assign d_w = ena? {t,d} : {out,t};
	dff_bus #(data_width) p[1:latency] (.q({out,t}), .clk(clk), .d(d_w), .clr(clr));
end
endgenerate
// IMPLEMENTATION END

endmodule

module dff_bus #(parameter WIDTH=1) (
    output reg [WIDTH-1:0] q,
    input clk,
    input [WIDTH-1:0] d,
    input clr
);

always @(posedge clk, negedge clr) begin
    if(!clr) begin
        q <= {WIDTH{1'b0}};
    end else begin
        q <= d;
    end
end

endmodule

module pipeline_module( 
    input [2:0] a,
    input [2:0] b,
    output [2:0] out_or_bitwise,
    output out_or_logical,
    output [5:0] out_not
);

    wire [2:0] a_inv, b_inv;
    wire [2:0] or_bitwise;
    wire or_logical;

    // Pipeline registers
    reg [2:0] a_reg, b_reg;
    reg [2:0] a_inv_reg, b_inv_reg;
    reg [2:0] or_bitwise_reg;
    reg or_logical_reg;

    // Lookup table for bitwise OR
    assign or_bitwise = {a[0] | b[0], a[1] | b[1], a[2] | b[2]};

    // Logical OR
    assign or_logical = (a | b) != 0;

    // Inverse of a and b
    assign {b_inv[2], b_inv[1], b_inv[0]} = ~b;
    assign {a_inv[2], a_inv[1], a_inv[0]} = ~a;

    // Pipeline stages
    always @(posedge clk) begin
        a_reg <= a;
        b_reg <= b;
        a_inv_reg <= a_inv;
        b_inv_reg <= b_inv;
        or_bitwise_reg <= or_bitwise;
        or_logical_reg <= or_logical;
    end

    // Output stage
    assign out_or_bitwise = or_bitwise_reg;
    assign out_or_logical = or_logical_reg;
    assign {out_not[5], out_not[4], out_not[3]} = b_inv_reg;
    assign {out_not[2], out_not[1], out_not[0]} = a_inv_reg;

endmodule

