module full_adder(
    input a,
    input b,
    input cin,
    output reg sum,
    output reg cout
);

    always @ (a or b or cin) begin
        sum = a ^ b ^ cin;
        cout = (a & b) | (a & cin) | (b & cin);
    end

endmodule

module adder_with_carry_in(
    input [3:0] a,
    input [3:0] b,
    input cin,
    output [4:0] sum
);

    wire c1, c2, c3;

    full_adder fa1(.a(a[0]), .b(b[0]), .cin(cin), .sum(sum[0]), .cout(c1));
    full_adder fa2(.a(a[1]), .b(b[1]), .cin(c1), .sum(sum[1]), .cout(c2));
    full_adder fa3(.a(a[2]), .b(b[2]), .cin(c2), .sum(sum[2]), .cout(c3));
    full_adder fa4(.a(a[3]), .b(b[3]), .cin(c3), .sum(sum[3]), .cout(sum[4]));

endmodule

module top_module(
    input [31:0] in1,
    input [31:0] in2,
    input cin,
    output [31:0] out
);

    wire [31:0] rev_in1, rev_in2;
    wire [4:0] sum;

    reverse_byte_order rbo1(.in(in1), .out(rev_in1));
    reverse_byte_order rbo2(.in(in2), .out(rev_in2));
    adder_with_carry_in awci(.a(rev_in1[3:0]), .b(rev_in2[3:0]), .cin(cin), .sum(sum));
    reverse_byte_order rbo3(.in(sum), .out(out));

endmodule

module min_max (
  input [n-1:0] in,
  output reg [n-1:0] min,
  output reg [n-1:0] max
);

parameter n = 8; // number of input signals

integer i;

always @(*) begin
  min = in[0];
  max = in[0];
  for (i = 1; i < n; i = i + 1) begin
    if (in[i] < min) begin
      min = in[i];
    end
    if (in[i] > max) begin
      max = in[i];
    end
  end
end

endmodule

module fifo_8bit(
    input wr_en,
    input clk,
    input srst,
    input [7:0] din,
    input rd_en,
    output empty,
    output full,
    output [7:0] dout
);

    reg [7:0] fifo[15:0];
    reg [3:0] write_ptr;
    reg [3:0] read_ptr;
    wire [3:0] next_write_ptr;
    wire [3:0] next_read_ptr;

    assign next_write_ptr = write_ptr + 1;
    assign next_read_ptr = read_ptr + 1;

    always @(posedge clk) begin
        if (srst) begin
            write_ptr <= 0;
            read_ptr <= 0;
            fifo <= 16'h0000;
        end else begin
            if (wr_en && !full) begin
                fifo[write_ptr] <= din;
                write_ptr <= next_write_ptr;
            end
            if (rd_en && !empty) begin
                dout <= fifo[read_ptr];
                read_ptr <= next_read_ptr;
            end
        end
    end

    assign empty = (write_ptr == read_ptr);
    assign full = ((next_write_ptr == read_ptr) && (next_read_ptr != write_ptr));

endmodule

