module AN_coder_decoder (
  input [n-1:0] symbol_in,
  input [n-1:0] prob_in,
  input end_flag,
  output reg [31:0] encoded_out,
  input [31:0] encoded_in,
  output reg [n-1:0] symbol_out
);

parameter n = 8; // number of symbols
parameter frac_bits = 16; // number of fractional bits for fixed-point representation

reg [31:0] cum_prob [0:n-1]; // cumulative probabilities
reg [31:0] low, high, range;
integer i;

// Calculate cumulative probabilities
always @ (prob_in) begin
  cum_prob[0] <= prob_in[0];
  for (i = 1; i < n; i = i + 1) begin
    cum_prob[i] <= cum_prob[i-1] + prob_in[i];
  end
end

// AN encoder
always @ (symbol_in or end_flag) begin
  if (!end_flag) begin
    low <= 0;
    high <= (1 << frac_bits) - 1;
    for (i = 0; i < n; i = i + 1) begin
      if (symbol_in == i) begin
        range <= high - low + 1;
        high <= low + ((range * cum_prob[i+1]) >> frac_bits) - 1;
        low <= low + ((range * cum_prob[i]) >> frac_bits);
      end
    end
  end
  encoded_out <= low;
end

// AN decoder
always @ (encoded_in or end_flag) begin
  if (!end_flag) begin
    for (i = 0; i < n; i = i + 1) begin
      if ((encoded_in >= (cum_prob[i] << (32 - frac_bits))) && (encoded_in < (cum_prob[i+1] << (32 - frac_bits)))) begin
        symbol_out <= i;
      end
    end
  end
end

endmodule

module top_module( 
    input [255:0] in,
    input [7:0] sel,
    input clk,
    input reset,
    output reg [6:0] seg,
    output reg [3:0] an ); 

    // 1-bit, 256-to-1 multiplexer
    wire [7:0] sel_decoded;
    wire [255:0] in_selected;
    assign sel_decoded = {8{sel[7]}};
    assign in_selected = in & (sel_decoded ^ sel);

    // 4-bit binary up counter
    reg [3:0] counter;
    always @(posedge clk) begin
        if (reset) begin
            counter <= 4'b0000;
        end else begin
            counter <= counter + 1;
        end
    end

    // Functional module
    wire [11:0] out_func;
    assign out_func = in_selected + counter;

    // 7-segment display controller
    reg [15:0] out_hex;
    always @(posedge clk) begin
        out_hex <= out_func;
    end

    // 7-segment display decoder
    reg [3:0] an_decoder;
    always @(out_hex) begin
        case (an_decoder)
            4'b0000: seg = 7'b1000000; // 0
            4'b0001: seg = 7'b1111001; // 1
            4'b0010: seg = 7'b0100100; // 2
            4'b0011: seg = 7'b0110000; // 3
            4'b0100: seg = 7'b0011001; // 4
            4'b0101: seg = 7'b0010010; // 5
            4'b0110: seg = 7'b0000010; // 6
            4'b0111: seg = 7'b1111000; // 7
            4'b1000: seg = 7'b0000000; // 8
            4'b1001: seg = 7'b0010000; // 9
            4'b1010: seg = 7'b0001000; // A
            4'b1011: seg = 7'b0000011; // B
            4'b1100: seg = 7'b1000110; // C
            4'b1101: seg = 7'b0100001; // D
            4'b1110: seg = 7'b0000110; // E
            4'b1111: seg = 7'b0001110; // F
            default: seg = 7'b1111111; // Blank
        endcase
    end

    // 7-segment display multiplexer
    always @(posedge clk) begin
        if (reset) begin
            an_decoder <= 4'b0000;
            an <= 4'b1111;
        end else begin
            an_decoder <= an_decoder + 1;
            case (an_decoder)
                4'b0000: an <= 4'b1110;
                4'b0001: an <= 4'b1101;
                4'b0010: an <= 4'b1011;
                4'b0011: an <= 4'b0111;
                default: an <= 4'b1111;
            endcase
        end
    end

endmodule

module mux_ff (
    input clk,
    input reset,
    input [2:0] sel1,
    input [5:0] data,
    input [1:0] sel2,
    output reg [7:0] q
);

    reg [7:0] ff_out;
    wire [7:0] mux_out;

    // 6-to-1 multiplexer
    assign mux_out = {data[(sel1+0)*8+7:(sel1+0)*8], data[(sel1+1)*8+7:(sel1+1)*8], data[(sel1+2)*8+7:(sel1+2)*8], data[(sel1+3)*8+7:(sel1+3)*8], data[(sel1+4)*8+7:(sel1+4)*8], data[(sel1+5)*8+7:(sel1+5)*8]};

    // D flip-flop
    always @(negedge clk) begin
        if (reset) begin
            ff_out <= 8'b0;
        end else begin
            ff_out <= mux_out;
        end
    end

    // 3-to-1 multiplexer
    always @(*) begin
        case (sel2)
            2'b00: q = mux_out;
            2'b01: q = ff_out;
            2'b10: q = 8'b0;
            2'b11: q = 8'b1;
        endcase
    end

endmodule

