module rising_edge_detector (
    input clk,
    input [31:0] in32,
    output reg [31:0] out
);
    reg [31:0] prev_in;
    reg [31:0] rising_edge_mask;

    always @(posedge clk) begin
        if (reset) begin
            prev_in <= 0;
            rising_edge_mask <= 0;
            out <= 0;
        end else begin
            prev_in <= in32;
            rising_edge_mask <= (in32 ^ prev_in) & in32;
            out <= out | rising_edge_mask;
        end
    end
endmodule

