    wire [31:0] rising_edge_out;

    barrel_shifter bs (
        .in(in),
        .out(reversed_in)
    );

    rising_edge_detector red (
        .clk(clk),
        .reset(reset),
        .in32(in32),
        .out(rising_edge_out)
    );

    bitwise_or bo (
        .in1(reversed_in),
        .in2(rising_edge_out),
        .out(out)
    );
endmodule

