module top_module( 
    input [255:0] in,
    input [7:0] sel,
    output out );

    wire [1:0] sel_0, sel_1, sel_2, sel_3, sel_4, sel_5, sel_6, sel_7;
    wire [1:0] mux_0_out, mux_1_out, mux_2_out, mux_3_out, mux_4_out, mux_5_out, mux_6_out;
    wire [1:0] mux_7_out, mux_8_out, mux_9_out, mux_10_out, mux_11_out, mux_12_out;
    wire [1:0] mux_13_out, mux_14_out, mux_15_out, mux_16_out, mux_17_out;
    wire [1:0] mux_18_out, mux_19_out, mux_20_out, mux_21_out;
    wire [1:0] mux_22_out, mux_23_out;
    wire [1:0] mux_24_out;

    // First stage of 16 16-to-1 multiplexers
    sixteen_to_one_mux mux_0(.in(in[15:0]), .sel(sel[3:2]), .out(mux_0_out[0]));
    sixteen_to_one_mux mux_1(.in(in[31:16]), .sel(sel[3:2]), .out(mux_1_out[0]));
    sixteen_to_one_mux mux_2(.in(in[47:32]), .sel(sel[3:2]), .out(mux_2_out[0]));
    sixteen_to_one_mux mux_3(.in(in[63:48]), .sel(sel[3:2]), .out(mux_3_out[0]));
    sixteen_to_one_mux mux_4(.in(in[79:64]), .sel(sel[3:2]), .out(mux_4_out[0]));
    sixteen_to_one_mux mux_5(.in(in[95:80]), .sel(sel[3:2]), .out(mux_5_out[0]));
    sixteen_to_one_mux mux_6(.in(in[111:96]), .sel(sel[3:2]), .out(mux_6_out[0]));
    sixteen_to_one_mux mux_7(.in(in[127:112]), .sel(sel[3:2]), .out(mux_7_out[0]));
    sixteen_to_one_mux mux_8(.in(in[143:128]), .sel(sel[3:2]), .out(mux_8_out[0]));
    sixteen_to_one_mux mux_9(.in(in[159:144]), .sel(sel[3:2]), .out(mux_9_out[0]));
    sixteen_to_one_mux mux_10(.in(in[175:160]), .sel(sel[3:2]), .out(mux_10_out[0]));
    sixteen_to_one_mux mux_11(.in(in[191:176]), .sel(sel[3:2]), .out(mux_11_out[0]));
    sixteen_to_one_mux mux_12(.in(in[207:192]), .sel(sel[3:2]), .out(mux_12_out[0]));
    sixteen_to_one_mux mux_13(.in(in[223:208]), .sel(sel[3:2]), .out(mux_13_out[0]));
    sixteen_to_one_mux mux_14(.in(in[239:224]), .sel(sel[3:2]), .out(mux_14_out[0]));
    sixteen_to_one_mux mux_15(.in(in[255:240]), .sel(sel[3:2]), .out(mux_15_out[0]));

    // Second stage of 8 32-to-1 multiplexers
    thirty_two_to_one_mux mux_16(.in({mux_0_out, mux_1_out}), .sel(sel[5:4]), .out(mux_16_out[0]));
    thirty_two_to_one_mux mux_17(.in({mux_2_out, mux_3_out}), .sel(sel[5:4]), .out(mux_17_out[0]));
    thirty_two_to_one_mux mux_18(.in({mux_4_out, mux_5_out}), .sel(sel[5:4]), .out(mux_18_out[0]));
    thirty_two_to_one_mux mux_19(.in({mux_6_out, mux_7_out}), .sel(sel[5:4]), .out(mux_19_out[0]));
    thirty_two_to_one_mux mux_20(.in({mux_8_out, mux_9_out}), .sel(sel[5:4]), .out(mux_20_out[0]));
    thirty_two_to_one_mux mux_21(.in({mux_10_out, mux_11_out}), .sel(sel[5:4]), .out(mux_21_out[0]));
    thirty_two_to_one_mux mux_22(.in({mux_12_out, mux_13_out}), .sel(sel[5:4]), .out(mux_22_out[0]));
    thirty_two_to_one_mux mux_23(.in({mux_14_out, mux_15_out}), .sel(sel[5:4]), .out(mux_23_out[0]));

    // Third stage of 4 64-to-1 multiplexers
    sixty_four_to_one_mux mux_24(.in({mux_16_out, mux_17_out, mux_18_out, mux_19_out, mux_20_out, mux_21_out, mux_22_out, mux_23_out}), .sel(sel[7:6]), .out(mux_24_out[0]));

    assign out = mux_24_out[0];

