// 16-to-1 multiplexer module
module sixteen_to_one_mux(
    input [15:0] in,
    input [1:0] sel,
    output reg out
);

    always @(*) begin
        case (sel)
            2'b00: out = in[0];
            2'b01: out = in[1];
            2'b10: out = in[2];
            2'b11: out = in[3];
        endcase
    end

endmodule

// 32-to-1 multiplexer module
module thirty_two_to_one_mux(
    input [1:0] sel,
    input [1:0] in [1:0][1:0],
    output reg out
);

    always @(*) begin
        case (sel)
            2'b00: out = in[0][0];
            2'b01: out = in[0][1];
            2'b10: out = in[1][0];
            2'b11: out = in[1][1];
        endcase
    end

endmodule

// 64-to-1 multiplexer module
module sixty_four_to_one_mux(
    input [2:0] sel,
    input [1:0] in [3:0][1:0],
    output reg out
);

    always @(*) begin
        case (sel)
            3'b000: out = in[0][0];
            3'b001: out = in[0][1];
            3'b010: out = in[1][0];
            3'b011: out = in[1][1];
            3'b100: out = in[2][0];
