module ConvolutionalEncoderViterbiDecoder (
  input [k-1:0] in,
  output [n-1:0] out
);

parameter k = 4; // number of input signals
parameter n = 8; // number of output signals
parameter m = 3; // number of memory elements in the convolutional encoder
parameter g1 = 3'b101; // generator polynomial for the convolutional encoder
parameter g2 = 3'b111; // generator polynomial for the convolutional encoder

reg [m-1:0] shift_reg;
wire [n-1:0] encoded_bits;

// Convolutional encoder
always @(posedge clk) begin
  shift_reg <= {shift_reg[m-2:0], in};
end

assign encoded_bits[0] = shift_reg[0] ^ shift_reg[2];
assign encoded_bits[1] = shift_reg[0] ^ shift_reg[1] ^ shift_reg[2];

// Viterbi decoder
integer i, j, min_dist, min_idx;
reg [m-1:0] state;
reg [m-1:0] next_state;
reg [m-1:0] path_memory [0:2**m-1];
reg [31:0] path_metric [0:2**m-1];
reg [31:0] new_path_metric [0:2**m-1];

always @(posedge clk) begin
  // Update path metrics and path memory
  for (i = 0; i < 2**m; i = i + 1) begin
    next_state = {state[m-2:0], 1'b0};
    new_path_metric[i] = path_metric[next_state] + (encoded_bits[0] ^ shift_reg[0] ^ shift_reg[2]) + (encoded_bits[1] ^ shift_reg[0] ^ shift_reg[1] ^ shift_reg[2]);

    next_state = {state[m-2:0], 1'b1};
    if (path_metric[next_state] + (encoded_bits[0] ^ shift_reg[0] ^ shift_reg[2]) + (encoded_bits[1] ^ shift_reg[0] ^ shift_reg[1] ^ shift_reg[2]) < new_path_metric[i]) begin
      new_path_metric[i] = path_metric[next_state] + (encoded_bits[0] ^ shift_reg[0] ^ shift_reg[2]) + (encoded_bits[1] ^ shift_reg[0] ^ shift_reg[1] ^ shift_reg[2]);
      path_memory[i] = next_state;
    end else begin
      path_memory[i] = state;
    end
  end

  // Update state and path metrics
  for (i = 0; i < 2**m; i = i + 1) begin
    state[i] <= path_memory[i];
    path_metric[i] <= new_path_metric[i];
  end

  // Find minimum path metric
  min_dist = path_metric[0];
  min_idx = 0;
  for (i = 1; i < 2**m; i = i + 1) begin
    if (path_metric[i] < min_dist) begin
      min_dist = path_metric[i];
      min_idx = i;
    end
  end

  // Output decoded bits
  out <= state[min_idx][m-1];
end

endmodule

module db_controller(
    input clk,
    input rst_n,
    input start_i,
    output reg done_o,
    output reg [8:0] cnt_r,
    output reg [2:0] state
);

parameter IDLE = 3'b000, LOAD = 3'b001, YVER = 3'b011, YHOR = 3'b010;
parameter CVER = 3'b110, CHOR = 3'b111, OUTLT = 3'b101, OUT = 3'b100;

reg [2:0] next;
reg [8:0] cycles;
reg isluma;
reg isver;

always @* begin
    case(state)
        LOAD: cycles = 'd384;
        YVER: cycles = 'd132;
        YHOR: cycles = 'd140;
        CVER: cycles = 'd68;
        CHOR: cycles = 'd76;
        OUTLT: cycles = 'd67;
        OUT: cycles = 'd384;
        default: cycles = 'd0;
    endcase
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt_r <= 8'd0;
    end else if (!state) begin
        cnt_r <= 8'd0;
    end else if (cnt_r == cycles) begin
        cnt_r <= 8'd0;
    end else begin
        cnt_r <= cnt_r + 1'b1;
    end
end

always @* begin
    case(state)
        IDLE: begin
            if (start_i) begin
                next = LOAD;
            end else begin
                next = IDLE;
            end
        end
        LOAD: begin
            if (cnt_r == cycles) begin
                next = YVER;
            end else begin
                next = LOAD;
            end
        end
        YVER: begin
            if (cnt_r == cycles) begin
                next = YHOR;
            end else begin
                next = YVER;
            end
        end
        YHOR: begin
            if (cnt_r == cycles) begin
                next = CVER;
            end else begin
                next = YHOR;
            end
        end
        CVER: begin
            if (cnt_r == cycles) begin
                next = CHOR;
            end else begin
                next = CVER;
            end
        end
        CHOR: begin
            if (cnt_r == cycles) begin
                next = OUTLT;
            end else begin
                next = CHOR;
            end
        end
        OUTLT: begin
            if (cnt_r == cycles) begin
                next = OUT;
            end else begin
                next = OUTLT;
            end
        end
        OUT: begin
            if (cnt_r == cycles) begin
                next = IDLE;
            end else begin
                next = OUT;
            end
        end
    endcase
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
    end else begin
        state <= next;
    end
end

wire done_w = (state == OUT) ? 1'b1 : 1'b0;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        done_o <= 1'b0;
    end else if (next == IDLE) begin
        done_o <= done_w;
    end else begin
        done_o <= 1'b0;
    end
end

always @* begin
    case(state)
        YVER, YHOR: isluma = 1'b1;
        default: isluma = 1'b0;
    endcase
end

always @* begin
    case(state)
        YVER, CVER: isver = 1'b1;
        default: isver = 1'b0;
    endcase
end

endmodule

module flag_register
   (IN_FLAG,
    LD,
    SET,
    CLR,
    CLK,
    OUT_FLAG);
  input IN_FLAG;
  input LD;
  input SET;
  input CLR;
  input CLK;
  output OUT_FLAG;

  reg flag;

  always @(posedge CLK) begin
    if (LD) begin
      flag <= IN_FLAG;
    end else if (SET) begin
      flag <= 1;
    end else if (CLR) begin
      flag <= 0;
    end
  end

  assign OUT_FLAG = flag;

endmodule

