module niosII_system_jtag_uart_0_drom_module (
    // inputs:
    clk,
    incr_addr,
    reset_n,

    // outputs:
    new_rom,
    num_bytes,
    q,
    safe
);

parameter POLL_RATE = 100;

output new_rom;
output [31:0] num_bytes;
output [7:0] q;
output safe;
input clk;
input incr_addr;
input reset_n;

reg [11:0] address;
reg d1_pre;
reg d2_pre;
reg d3_pre;
reg d4_pre;
reg d5_pre;
reg d6_pre;
reg d7_pre;
reg d8_pre;
reg d9_pre;
reg [7:0] mem_array[2047:0];
reg [31:0] mutex[1:0];
reg new_rom;
wire [31:0] num_bytes;
reg pre;
wire [7:0] q;
wire safe;

//synthesis translate_off
//////////////// SIMULATION-ONLY CONTENTS
assign q = mem_array[address];
always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
        d1_pre <= 0;
        d2_pre <= 0;
        d3_pre <= 0;
        d4_pre <= 0;
        d5_pre <= 0;
        d6_pre <= 0;
        d7_pre <= 0;
        d8_pre <= 0;
        d9_pre <= 0;
        new_rom <= 0;
    end else begin
        d1_pre <= pre;
        d2_pre <= d1_pre;
        d3_pre <= d2_pre;
        d4_pre <= d3_pre;
        d5_pre <= d4_pre;
        d6_pre <= d5_pre;
        d7_pre <= d6_pre;
        d8_pre <= d7_pre;
        d9_pre <= d8_pre;
        new_rom <= d9_pre;
    end
end

assign num_bytes = mutex[1];
reg safe_delay;
reg [31:0] poll_count;
reg [31:0] mutex_handle;
wire interactive = 1'b1;
assign safe = (address < mutex[1]);

initial poll_count = POLL_RATE;

always @(posedge clk or negedge reset_n) begin
    if (reset_n !== 1) begin
        safe_delay <= 0;
    end else begin
        safe_delay <= safe;
    end
end // safe_delay

always @(posedge clk or negedge reset_n) begin
    if (reset_n !== 1) begin
        address <= 0;
        mem_array[0] <= 0;
        mutex[0] <= 0;
        mutex[1] <= 0;
        pre <= 0;
    end else begin
        pre <= 0;
        if (incr_addr && safe) begin
            address <= address + 1;
        end
        if (mutex[0] && !safe && safe_delay) begin
            if (interactive) begin
                mutex_handle = $fopen("niosII_system_jtag_uart_0_input_mutex.dat");
                $fdisplay(mutex_handle, "0");
                $fclose(mutex_handle);
            end else begin
                wait(!reset_n);
            end
        end
        if (poll_count < POLL_RATE) begin
            poll_count = poll_count + 1;
        end else begin
            poll_count = 0;
            if (mutex_handle) begin
                $readmemh("niosII_system_jtag_uart_0_input_mutex.dat", mutex);
            end
            if (mutex[0] && !safe) begin
                mutex[1] <= mutex[0];
                $readmemb("niosII_system_jtag_uart_0_input_stream.dat", mem_array);
                address <= 0;
                pre <= -1;
            end
        end
    end
end

//////////////// END SIMULATION-ONLY CONTENTS

endmodule

module hysteresis_comparator (
  input in,
  input Vthp,
  input Vthn,
  output out
);

  reg prev_out;

  always @(in or Vthp or Vthn or prev_out) begin
    if (in > Vthp) begin
      prev_out <= 1;
    end else if (in < Vthn) begin
      prev_out <= 0;
    end
  end

  assign out = prev_out;

endmodule

module Schmitt_trigger (
  input in,
  output out
);

parameter vth = 50; // threshold voltage level (% of vdd)
parameter vdd = 3.3; // supply voltage level (V)

reg out_reg;
wire rising_threshold;
wire falling_threshold;

assign rising_threshold = vdd * vth / 100;
assign falling_threshold = vdd * (100 - vth) / 100;

always @(in) begin
  if (in > rising_threshold) begin
    out_reg <= 1'b1;
  end else if (in < falling_threshold) begin
    out_reg <= 1'b0;
  end
end

assign out = out_reg;

endmodule

module snes_interface(
  input CLK,
  input [15:0] featurebits, // peripheral enable/disable
  input [2:0] MAPPER,       // MCU detected mapper
  input [23:0] SNES_ADDR,   // requested address from SNES
  input [7:0] SNES_PA,      // peripheral address from SNES
  input SNES_ROMSEL,        // ROMSEL from SNES
  output [23:0] ROM_ADDR,   // Address to request from SRAM0
  output ROM_HIT,           // enable SRAM0
  output IS_SAVERAM,        // address/CS mapped as SRAM?
  output IS_ROM,            // address mapped as ROM?
  output IS_WRITABLE,       // address somehow mapped as writable area?
  input [23:0] SAVERAM_MASK,
  input [23:0] ROM_MASK,
  output msu_enable,
  output r213f_enable,
  output r2100_hit,
  output snescmd_enable,
  output nmicmd_enable,
  output return_vector_enable,
  output branch1_enable,
  output branch2_enable,
  output gsu_enable
);

  wire [23:0] SRAM_SNES_ADDR;

  assign IS_ROM = ( (~SNES_ADDR[22] & SNES_ADDR[15])
                | (SNES_ADDR[22]  & ~SNES_ROMSEL))
                ;

  assign IS_SAVERAM = SAVERAM_MASK[0]
                    & ( // 60-7D/E0-FF:0000-FFFF
                        ( &SNES_ADDR[22:21]
                        & ~SNES_ROMSEL
                        )
                        // 00-3F/80-BF:6000-7FFF
                      | ( ~SNES_ADDR[22]
                        & ~SNES_ADDR[15]
                        & &SNES_ADDR[14:13]
                        )
                      );

  assign IS_WRITABLE = IS_SAVERAM;

  // GSU has a weird hybrid of Lo and Hi ROM formats.
  assign SRAM_SNES_ADDR = (IS_SAVERAM
                         // 60-7D/E0-FF:0000-FFFF or 00-3F/80-BF:6000-7FFF (first 8K mirror)
                         ? (24'hE00000 + ((SNES_ADDR[22] ? SNES_ADDR[16:0] : SNES_ADDR[12:0]) & SAVERAM_MASK))
                         // 40-5F/C0-DF:0000-FFFF or 00-3F/80-BF:8000-FFFF
                         : ((SNES_ADDR[22] ? {2'b00, SNES_ADDR[21:0]} : {2'b00, SNES_ADDR[22:16], SNES_ADDR[14:0]}) & ROM_MASK)
                         );

  assign ROM_ADDR = SRAM_SNES_ADDR;

  assign ROM_HIT = IS_ROM | IS_WRITABLE;

  assign msu_enable = featurebits[3] & (!SNES_ADDR[22] && ((SNES_ADDR[15:0] & 16'hfff8) == 16'h2000));
  assign r213f_enable = featurebits[4] & (SNES_PA == 8'h3f);
  assign r2100_hit = (SNES_PA == 8'h00);
  assign snescmd_enable = ({SNES_ADDR[22], SNES_ADDR[15:9]} == 8'b0_0010101);
  assign nmicmd_enable = (SNES_ADDR == 24'h002BF2);
  assign return_vector_enable = (SNES_ADDR == 24'h002A5A);
  assign branch1_enable = (SNES_ADDR == 24'h002A13);
  assign branch2_enable = (SNES_ADDR == 24'h002A4D);
  // 00-3F/80-BF:3000-32FF gsu registers.  TODO: some emulators go to $34FF???
  assign gsu_enable = (!SNES_ADDR[22] && ({SNES_ADDR[15:10],2'h0} == 8'h30)) && (SNES_ADDR[9:8] != 2'h3);

endmodule

