module RegisterAdder(clk, rst, load, D1, D2, Q);
  input clk, rst, load;
  input [1:0] D1, D2;
  output [1:0] Q;
  wire [1:0] sum;
  wire [1:0] carry;

  // First D flip-flop
  DFFRX4TS Q_reg_0_ (
    .D(sum[0]), .CK(clk), .RN(rst),
    .Q(Q[0]), .QN()
  );

  // Second D flip-flop
  DFFRX4TS Q_reg_1_ (
    .D(sum[1]), .CK(clk), .RN(rst),
    .Q(Q[1]), .QN()
  );

  // Calculate the sum
  XOR2X1 U1 (
    .A(D1[0]), .B(D2[0]),
    .Y(sum[0])
  );
  XOR2X1 U2 (
    .A(D1[1]), .B(D2[1]),
    .Y(sum[1])
  );

  // Calculate the carry
  NOR2X1 U3 (
    .A(sum[0]), .B(sum[1]),
    .Y(carry[0])
  );
  NOR2X1 U4 (
    .A(D1[0]), .B(D2[0]),
    .Y(carry[1])
  );
  NOR2X1 U5 (
    .A(D1[1]), .B(D2[1]),
    .Y(carry[2])
  );
  NOR2X1 U6 (
    .A(carry[0]), .B(carry[1]),
    .Y(carry[3])
  );
  NOR2X1 U7 (
    .A(carry[2]), .B(carry[3]),
    .Y(carry[4])
  );

  // Connect the carry to the flip-flop inputs
  AND2X1 U8 (
    .A(carry[4]), .B(load),
    .Y(Q_reg_0_.D)
  );
  AND2X1 U9 (
    .A(carry[4]), .B(load),
    .Y(Q_reg_1_.D)
  );

  // Connect the sum to the flip-flop inputs
  AND2X1 U10 (
    .A(sum[0]), .B(load),
    .Y(Q_reg_0_.D)
  );
  AND2X1 U11 (
    .A(sum[1]), .B(load),
    .Y(Q_reg_1_.D)
  );
endmodule

module shift_register(CLK, EN, TE, DATA_IN, ENCLK, DATA_OUT);

  input CLK, EN, TE;
  input [6:0] DATA_IN;
  output ENCLK;
  output reg [6:0] DATA_OUT;

  TLATNTSCAX2TS latch ( .E(EN), .SE(TE), .CK(CLK), .ECK(ENCLK) );

  always @(posedge CLK) begin
    if (EN) begin
      if (TE) begin
        DATA_OUT <= {DATA_OUT[5:0], DATA_IN[0]};
      end
      else begin
        DATA_OUT[0] <= ENCLK;
        DATA_OUT <= {DATA_OUT[6:1], DATA_IN[0]};
      end
    end
    else begin
      if (TE) begin
        DATA_OUT <= {7{1'b0}};
      end
      else begin
        DATA_OUT[0] <= ENCLK;
        DATA_OUT <= {7{1'b0}};
      end
    end
  end

endmodule

module ripple_carry_addsub (
    input [3:0] a,
    input [3:0] b,
    input mode,
    output reg [3:0] out,
    output reg overflow
);

reg [3:0] sum;
reg carry_in;
reg [3:0] diff;

always @(*) begin
    if (mode == 0) begin
        sum[0] = a[0] ^ b[0] ^ carry_in;
        carry_in = (a[0] & b[0]) | (a[0] & carry_in) | (b[0] & carry_in);
        sum[1] = a[1] ^ b[1] ^ carry_in;
        carry_in = (a[1] & b[1]) | (a[1] & carry_in) | (b[1] & carry_in);
        sum[2] = a[2] ^ b[2] ^ carry_in;
        carry_in = (a[2] & b[2]) | (a[2] & carry_in) | (b[2] & carry_in);
        sum[3] = a[3] ^ b[3] ^ carry_in;
        overflow = carry_in;
        out = sum;
    end else begin
        diff[0] = a[0] ^ b[0] ^ carry_in;
        carry_in = (~a[0] & b[0]) | ((~a[0] | b[0]) & carry_in);
        diff[1] = a[1] ^ b[1] ^ carry_in;
        carry_in = (~a[1] & b[1]) | ((~a[1] | b[1]) & carry_in);
        diff[2] = a[2] ^ b[2] ^ carry_in;
        carry_in = (~a[2] & b[2]) | ((~a[2] | b[2]) & carry_in);
        diff[3] = a[3] ^ b[3] ^ carry_in;
        overflow = carry_in;
        out = diff;
    end
end

endmodule

