module synchronous_ram (
    address,
    byteena,
    clken,
    clock,
    data,
    wren,
    q
);

input [9:0] address;
input [1:0] byteena;
input clken;
input clock;
input [15:0] data;
input wren;
output [15:0] q;

wire [15:0] sub_wire0;
wire [15:0] q = sub_wire0[15:0];

altsyncram altsyncram_component (
    .address_a(address),
    .byteena_a(byteena),
    .clock0(clock),
    .clocken0(clken),
    .data_a(data),
    .q_a(sub_wire0),
    .wren_a(wren),
    .aclr0(1'b0),
    .aclr1(1'b0),
    .address_b(1'b1),
    .addressstall_a(1'b0),
    .addressstall_b(1'b0),
    .byteena_b(1'b1),
    .clock1(1'b1),
    .clocken1(1'b1),
    .clocken2(1'b1),
    .clocken3(1'b1),
    .data_b(1'b1),
    .eccstatus(),
    .q_b(),
    .rden_a(1'b1),
    .rden_b(1'b1),
    .wren_b(1'b0)
);

parameter RAM_DEPTH = 1024;
parameter RAM_WIDTH = 16;
parameter RAM_ADDR_WIDTH = 10;

localparam RAM_SIZE = RAM_DEPTH * RAM_WIDTH;
reg [RAM_WIDTH-1:0] ram [0:RAM_DEPTH-1];

integer addr;

always @(posedge clock) begin
    if(clken) begin
        if(wren) begin
            for(addr = 0; addr < RAM_DEPTH; addr = addr + 1) begin
                if(byteena[0]) begin
                    ram[address][7:0] <= data[7:0];
                end
                if(byteena[1]) begin
                    ram[address][15:8] <= data[15:8];
                end
            end
        end
        q <= ram[address];
    end
end

endmodule

module Traffic_Light_Controller (
  input clk,
  input rst,
  output reg red,
  output reg yellow,
  output reg green
);

  // Define the states
  parameter Red = 2'b00;
  parameter Red_Yellow = 2'b01;
  parameter Green = 2'b10;
  parameter Yellow = 2'b11;

  // Define the state register and initialize to Red
  reg [1:0] state = Red;

  // Define the state machine
  always @(posedge clk, posedge rst) begin
    if (rst) begin
      state <= Red;
    end else begin
      case (state)
        Red: begin
          red <= 1;
          yellow <= 0;
          green <= 0;
          if (count == 5) begin
            state <= Red_Yellow;
            count <= 0;
          end else begin
            count <= count + 1;
          end
        end
        Red_Yellow: begin
          red <= 1;
          yellow <= 1;
          green <= 0;
          if (count == 2) begin
            state <= Green;
            count <= 0;
          end else begin
            count <= count + 1;
          end
        end
        Green: begin
          red <= 0;
          yellow <= 0;
          green <= 1;
          if (count == 5) begin
            state <= Yellow;
            count <= 0;
          end else begin
            count <= count + 1;
          end
        end
        Yellow: begin
          red <= 0;
          yellow <= 1;
          green <= 0;
          if (count == 2) begin
            state <= Red;
            count <= 0;
          end else begin
            count <= count + 1;
          end
        end
      endcase
    end
  end

  // Define the count register and initialize to 0
  reg [2:0] count = 0;

endmodule

module fifo_generator_rx_inst_rd_status_flags_ss
   (out,
    empty,
    \gc0.count_d1_reg[11] ,
    \gcc0.gc0.count_d1_reg[0] ,
    \gcc0.gc0.count_d1_reg[2] ,
    \gcc0.gc0.count_d1_reg[4] ,
    \gcc0.gc0.count_d1_reg[6] ,
    \gcc0.gc0.count_d1_reg[8] ,
    \gcc0.gc0.count_d1_reg[10] ,
    v1_reg,
    clk,
    \ngwrdrst.grst.g7serrst.rd_rst_reg_reg[2] ,
    rd_en,
    wr_en,
    ram_full_fb_i_reg);
  output out;
  output empty;
  output \gc0.count_d1_reg[11] ;
  input \gcc0.gc0.count_d1_reg[0] ;
  input \gcc0.gc0.count_d1_reg[2] ;
  input \gcc0.gc0.count_d1_reg[4] ;
  input \gcc0.gc0.count_d1_reg[6] ;
  input \gcc0.gc0.count_d1_reg[8] ;
  input \gcc0.gc0.count_d1_reg[10] ;
  input [5:0]v1_reg;
  input clk;
  input [0:0]\ngwrdrst.grst.g7serrst.rd_rst_reg_reg[2] ;
  input rd_en;
  input wr_en;
  input ram_full_fb_i_reg;

  wire c1_n_0;
  wire clk;
  wire comp1;
  wire \gc0.count_d1_reg[11] ;
  wire \gcc0.gc0.count_d1_reg[0] ;
  wire \gcc0.gc0.count_d1_reg[10] ;
  wire \gcc0.gc0.count_d1_reg[2] ;
  wire \gcc0.gc0.count_d1_reg[4] ;
  wire \gcc0.gc0.count_d1_reg[6] ;
  wire \gcc0.gc0.count_d1_reg[8] ;
  wire [0:0]\ngwrdrst.grst.g7serrst.rd_rst_reg_reg[2] ;
  (* DONT_TOUCH *) wire ram_empty_fb_i;
  (* DONT_TOUCH *) wire ram_empty_i;
  wire ram_full_fb_i_reg;
  wire rd_en;
  wire [5:0]v1_reg;
  wire wr_en;

  assign empty = ram_empty_i;
  assign out = ram_empty_fb_i;

  // Comparator module to check read status flags against maximum value
  fifo_generator_rx_inst_compare_4 c1
       (.comp1(comp1),
        .\gcc0.gc0.count_d1_reg[0] (\gcc0.gc0.count_d1_reg[0] ),
        .\gcc0.gc0.count_d1_reg[10] (\gcc0.gc0.count_d1_reg[10] ),
        .\gcc0.gc0.count_d1_reg[2] (\gcc0.gc0.count_d1_reg[2] ),
        .\gcc0.gc0.count_d1_reg[4] (\gcc0.gc0.count_d1_reg[4] ),
        .\gcc0.gc0.count_d1_reg[6] (\gcc0.gc0.count_d1_reg[6] ),
        .\gcc0.gc0.count_d1_reg[8] (\gcc0.gc0.count_d1_reg[8] ),
        .out(ram_empty_fb_i),
        .ram_empty_i_reg(c1_n_0),
        .ram_full_fb_i_reg(ram_full_fb_i_reg),
        .rd_en(rd_en),
        .wr_en(wr_en));

  // Comparator module to compare input signal to FIFO
  fifo_generator_rx_inst_compare_5 c2
       (.comp1(comp1),
        .v1_reg(v1_reg));

  // LUT module to set read status flag when FIFO is full
  LUT2 #(
    .INIT(4'h2)) 
    \gc0.count_d1[11]_i_1 
       (.I0(rd_en),
        .I1(ram_empty_fb_i),
        .O(\gc0.count_d1_reg[11] ));

  // Register module for feedback signal indicating if FIFO is empty
  (* DONT_TOUCH *) 
  (* KEEP = "yes" *) 
  (* equivalent_register_removal = "no" *) 
  FDPE #(
    .INIT(1'b1)) 
    ram_empty_fb_i_reg
       (.C(clk),
        .CE(1'b1),
        .D(c1_n_0),
        .PRE(\ngwrdrst.grst.g7serrst.rd_rst_reg_reg[2] ),
        .Q(ram_empty_fb_i));

  // Register module for signal indicating if FIFO is empty
  (* DONT_TOUCH *) 
  (* KEEP = "yes" *) 
  (* equivalent_register_removal = "no" *) 
  FDPE #(
    .INIT(1'b1)) 
    ram_empty_i_reg
       (.C(clk),
        .CE(1'b1),
        .D(c1_n_0),
        .PRE(\ngwrdrst.grst.g7serrst.rd_rst_reg_reg[2] ),
        .Q(ram_empty_i));

endmodule

