module top_module (
    input clk,
    input signed [31:0] a,
    input signed [31:0] b,
    input [7:0] input1,
    input [7:0] input2,
    input control,
    output [1:0] result,
    output signed [31:0] product
);

    wire signed [15:0] mul_output;
    wire [1:0] xor_nor_output;

    mul8 mul_inst (
        .a(input1),
        .b(input2),
        .product(mul_output)
    );

    xor_nor_gate xor_nor_inst (
        .a(input1),
        .b(input2),
        .control(control),
        .result(xor_nor_output)
    );

    assign product = a * b * mul_output;
    assign result = xor_nor_output;

endmodule

module mul8 (
    input signed [7:0] a,
    input signed [7:0] b,
    output signed [15:0] product
);

    assign product = a * b;

endmodule

module xor_nor_gate (
    input [7:0] a,
    input [7:0] b,
    input control,
    output reg [1:0] result
);

    always @(*) begin
        if (control == 0) begin
            result[0] = a[0] ^ b[0];
            result[1] = a[1] ^ b[1];
            result[2] = a[2] ^ b[2];
            result[3] = a[3] ^ b[3];
            result[4] = a[4] ^ b[4];
            result[5] = a[5] ^ b[5];
            result[6] = a[6] ^ b[6];
            result[7] = a[7] ^ b[7];
        end else begin
            result[0] = ~(a[0] | b[0]);
            result[1] = ~(a[1] | b[1]);
            result[2] = ~(a[2] | b[2]);
            result[3] = ~(a[3] | b[3]);
            result[4] = ~(a[4] | b[4]);
            result[5] = ~(a[5] | b[5]);
            result[6] = ~(a[6] | b[6]);
            result[7] = ~(a[7] | b[7]);
        end
    end

endmodule

