module uart_module (
    input i_clk, // input clock signal
    input i_rst, // input reset signal
    input i_wb_stb, // Wishbone strobe signal
    input [31:0] i_wb_addr, // Wishbone address signal
    inout [31:0] i_wb_data, // Wishbone data signal
    output o_wb_ack, // Wishbone acknowledge signal
    input o_uart_rx, // UART receive data signal
    output i_uart_tx // UART transmit data signal
);

parameter BAUD_RATE = 9600; // baud rate for the UART module (9600 by default)
parameter DATA_BITS = 8; // number of data bits for the UART module (8 by default)
parameter STOP_BITS = 1; // number of stop bits for the UART module (1 by default)
parameter PARITY = "none"; // parity setting for the UART module (none by default)

reg [DATA_BITS-1:0] rx_data; // register to store received data
reg [DATA_BITS-1:0] tx_data; // register to store transmitted data
reg [3:0] bit_count; // register to count number of bits received or transmitted
reg [3:0] stop_count; // register to count number of stop bits transmitted
reg [1:0] parity_count; // register to count number of parity bits received
reg parity_error; // register to store parity error flag
reg [31:0] wb_data_reg; // register to store Wishbone data

// initialize registers
initial begin
    rx_data = 0;
    tx_data = 0;
    bit_count = 0;
    stop_count = 0;
    parity_count = 0;
    parity_error = 0;
    wb_data_reg = 0;
end

// receive data from microcontroller using Wishbone bus interface
always @(posedge i_clk) begin
    if (i_rst) begin
        wb_data_reg <= 0;
        o_wb_ack <= 0;
    end else if (i_wb_stb && (i_wb_addr == 0)) begin
        wb_data_reg <= i_wb_data;
        o_wb_ack <= 1;
    end else begin
        o_wb_ack <= 0;
    end
end

// transmit data to microcontroller using Wishbone bus interface
always @(posedge i_clk) begin
    if (i_rst) begin
        o_uart_tx <= 1;
    end else if (i_wb_stb && (i_wb_addr == 4)) begin
        tx_data <= i_wb_data[DATA_BITS-1:0];
        o_uart_tx <= 0;
        bit_count <= 0;
        stop_count <= 0;
        parity_count <= 0;
        parity_error <= 0;
    end else begin
        if (bit_count == DATA_BITS) begin
            if ((PARITY == "even" && (parity_count % 2 == 0)) ||
                (PARITY == "odd" && (parity_count % 2 == 1)) ||
                (PARITY == "none")) begin
                if (stop_count == STOP_BITS) begin
                    o_uart_tx <= 1;
                end else begin
                    o_uart_tx <= 0;
                    stop_count <= stop_count + 1;
                end
            end else begin
                parity_error <= 1;
                o_uart_tx <= 1;
            end
        end else begin
            o_uart_tx <= tx_data[bit_count];
            bit_count <= bit_count + 1;
        end
    end
end

// receive data asynchronously from UART receive data signal
always @(posedge i_clk) begin
    if (i_rst) begin
        rx_data <= 0;
        bit_count <= 0;
        stop_count <= 0;
        parity_count <= 0;
        parity_error <= 0;
    end else if (!o_uart_rx) begin
        if (bit_count == DATA_BITS) begin
            if ((PARITY == "even" && (parity_count % 2 == 0)) ||
                (PARITY == "odd" && (parity_count % 2 == 1)) ||
                (PARITY == "none")) begin
                if (stop_count == STOP_BITS) begin
                    rx_data <= rx_data;
                end else begin
                    stop_count <= stop_count + 1;
                end
            end else begin
                parity_error <= 1;
            end
            bit_count <= 0;
            parity_count <= 0;
        end else begin
            rx_data[bit_count] <= i_uart_rx;
            bit_count <= bit_count + 1;
            parity_count <= parity_count + i_uart_rx;
        end
    end
end

// store received data in Wishbone data register
always @(posedge i_clk) begin
    if (i_rst) begin
        wb_data_reg <= 0;
    end else if (bit_count == DATA_BITS) begin
        wb_data_reg <= rx_data;
    end
end

// implement parity error flag
always @(posedge i_clk) begin
    if (i_rst) begin
        parity_error <= 0;
    end else if (bit_count == DATA_BITS) begin
        if ((PARITY == "even" && (parity_count % 2 == 1)) ||
            (PARITY == "odd" && (parity_count % 2 == 0))) begin
            parity_error <= 1;
        end else begin
            parity_error <= 0;
        end
    end
end

// interface with Wishbone bus
assign i_wb_data = wb_data_reg;
assign o_wb_ack = 0;

// end of module
endmodule

