  parameter STATE0 = 2'b00;
  parameter STATE1 = 2'b01;

  // Define the next state logic
  OAI21_X1 U3 ( .B1(n14), .B2(n10), .A(n13), .ZN(N12) );
  OAI21_X1 U5 ( .B1(n5), .B2(n14), .A(n13), .ZN(N11) );
  DLH_X1 \next_STATE_reg[0]  ( .G(enable), .D(N11), .Q(next_STATE[0]) );
  DLH_X1 \next_STATE_reg[1]  ( .G(enable), .D(N12), .Q(next_STATE[1]) );

  // Define the state machine
  DFFR_X1 \STATE_reg[0]  ( .D(n6), .CK(clock), .RN(n12), .Q(n5), .QN(n10) );
  DFFR_X1 \STATE_reg[1]  ( .D(n8), .CK(clock), .RN(n12), .Q(prediction_o) );
  MUX2_X1 U8 ( .A(prediction_o), .B(next_STATE[1]), .S(enable), .Z(n8) );
  MUX2_X1 U9 ( .A(n5), .B(next_STATE[0]), .S(enable), .Z(n6) );

  // Define the state machine logic
  NOR2_X1 U7 ( .A1(prediction_o), .A2(taken_i), .ZN(n14) );
  NAND2_X1 U6 ( .A1(prediction_o), .A2(taken_i), .ZN(n13) );
  INV_X1 U2 ( .A(reset), .ZN(n12) );

  // Define the state machine transitions
  always @ (posedge clock) begin
    if (reset) begin
      next_STATE <= STATE0;
    end else begin
      case (next_STATE)
        STATE0: begin
          if (taken_i == 0) begin
            next_STATE <= STATE1;
          end else begin
            next_STATE <= STATE0;
          end
        end
        STATE1: begin
          if (taken_i == 0) begin
            next_STATE <= STATE1;
          end else begin
            next_STATE <= STATE0;
          end
        end
      endcase
    end
  end
endmodule

module RLE (
  input [7:0] in,
  input ctrl,
  output [7:0] out
);

parameter n = 8; // number of input signals
parameter m = 8; // number of output signals

reg [7:0] compressed_data [0:255]; // array to store compressed data
reg [7:0] decompressed_data [0:255]; // array to store decompressed data
reg [7:0] current_byte; // variable to store current byte being processed
reg [7:0] current_count; // variable to store current count of the byte being processed
reg [7:0] output_byte; // variable to store current output byte
reg [7:0] output_index; // variable to store current output index
reg [7:0] compressed_index; // variable to store current compressed index
reg [7:0] decompressed_index; // variable to store current decompressed index
reg [7:0] i; // variable for loop counter

// Compression algorithm
always @ (posedge ctrl) begin
  if (ctrl) begin
    current_byte = in;
    if (current_byte == compressed_data[compressed_index] && current_count < 255) begin
      current_count = current_count + 1;
    end
    else begin
      compressed_data[compressed_index] = current_byte;
      compressed_data[compressed_index+1] = current_count;
      compressed_index = compressed_index + 2;
      current_count = 1;
    end
  end
end

// Decompression algorithm
always @ (negedge ctrl) begin
  if (!ctrl) begin
    current_byte = in;
    if (decompressed_index % 2 == 0) begin
      output_byte = current_byte;
      current_count = compressed_data[decompressed_index+1];
    end
    if (current_count > 0) begin
      decompressed_data[decompressed_index] = output_byte;
      decompressed_index = decompressed_index + 1;
      current_count = current_count - 1;
    end
    if (current_count == 0 && decompressed_index % 2 == 0) begin
      decompressed_index = decompressed_index + 1;
    end
  end
end

// Output compressed or decompressed data
always @ (compressed_data, decompressed_data, output_index, decompressed_index) begin
  if (ctrl) begin
    for (i = 0; i < compressed_index; i = i + 2) begin
      out[output_index] = compressed_data[i];
      output_index = output_index + 1;
      out[output_index] = compressed_data[i+1];
      output_index = output_index + 1;
    end
  end
  else begin
    for (i = 0; i < decompressed_index; i = i + 1) begin
      out[output_index] = decompressed_data[i];
      output_index = output_index + 1;
    end
  end
end

endmodule

module top_module (
    input clk,
    input reset,   // Synchronous active-high reset
    input [7:0] d1, // 8-bit input for the first register
    input [7:0] d2, // 8-bit input for the second register
    input select, // Select input to choose between the two registers and the counter
    output [7:0] q_active, // 8-bit output from the active module
    output [15:0] result // 16-bit output from the functional module
