module gcd_calculator (
    input [3:0] A,
    input [3:0] B,
    output reg [3:0] gcd
);

reg [3:0] tmp_A, tmp_B;

always @(*) begin
    tmp_A = A;
    tmp_B = B;

    while (tmp_B != 0) begin
        if (tmp_A > tmp_B) begin
            tmp_A = tmp_A - tmp_B;
        end else begin
            tmp_B = tmp_B - tmp_A;
        end
    end

    gcd = tmp_A;
end

endmodule

