module relaxation_oscillator (
  input clk,
  input reset,
  output out
);

  parameter R = 100; // Resistance value in ohms
  parameter C = 1e-6; // Capacitance value in farads
  reg [31:0] count; // Counter to keep track of time
  reg [31:0] voltage; // Voltage across the capacitor
  reg [31:0] charge_time; // Time taken to charge the capacitor
  reg [31:0] discharge_time; // Time taken to discharge the capacitor
  reg [1:0] state; // State variable to keep track of charging/discharging

  always @(posedge clk) begin
    if (reset) begin
      count <= 0;
      voltage <= 0;
      charge_time <= 0;
      discharge_time <= 0;
      state <= 2'b0;
      out <= 0;
    end else begin
      count <= count + 1;
      case (state)
        2'b00: begin // Charging
          voltage <= (count * 5) / (R * C); // V = IR
          if (voltage >= 5) begin
            charge_time <= count;
            state <= 2'b01;
          end
        end
        2'b01: begin // Discharging
          voltage <= 5 - ((count - charge_time) * 5) / (R * C); // V = IR
          if (voltage <= 0) begin
            discharge_time <= count;
            state <= 2'b00;
          end
        end
      endcase
      if (state == 2'b00) begin
        out <= 1;
      end else begin
        out <= 0;
      end
    end
  end

endmodule

