module shift_reg (
    input CLK,
    input D,
    input SR,
    input SE,
    output reg Q
);

    reg [7:0] reg_data;
    reg [2:0] state;

    always @(posedge CLK) begin
        case (state)
            3'b000: begin  // idle
                if (!SR) begin
                    reg_data <= 8'b0;
                end else if (SE) begin
                    reg_data <= {D, reg_data[7:1]};
                end
                Q <= reg_data[0];
                state <= SE ? 3'b001 : 3'b000;
            end
            3'b001: begin  // wait for SE to deassert
                if (!SE) begin
                    state <= 3'b010;
                end
            end
            3'b010: begin  // wait for CLK to go low
                if (!CLK) begin
                    state <= 3'b011;
                end
            end
            3'b011: begin  // shift data
                reg_data <= {D, reg_data[7:1]};
                Q <= reg_data[0];
                state <= 3'b010;
            end
        endcase
    end

endmodule

