        genvar i;
        for (i = 0; i < 32; i = i + 1) begin : carry_lookahead_adder
            assign G[i] = A[i] & B[i];
            assign P[i] = A[i] ^ B[i];
            assign C[i+1] = (G[i] == 1) ? (C[i] << 1) + 1 : (C[i] << 1) + P[i];
