    input [99:0] in,
    output out_and,
    output out_or,
    output out_xor
);

wire [49:0] and_out;
wire [49:0] or_out;
wire [98:0] xor_out;

// AND gates
genvar i;
generate
    for (i = 0; i < 50; i = i + 1) begin : and_gates
        and gate (
            .a(in[2*i]),
            .b(in[2*i+1]),
            .y(and_out[i])
        );
    end
endgenerate

// OR gates
generate
    for (i = 0; i < 50; i = i + 1) begin : or_gates
        or gate (
            .a(in[2*i]),
            .b(in[2*i+1]),
            .y(or_out[i])
        );
    end
endgenerate

// XOR gates
generate
    for (i = 0; i < 99; i = i + 1) begin : xor_gates
        xor gate (
            .a(in[i]),
            .b(in[i+1]),
            .y(xor_out[i])
        );
    end
endgenerate

// AND of all inputs
and and_all (
    .a(and_out),
    .y(out_and)
);

// OR of all inputs
or or_all (
    .a(or_out),
    .y(out_or)
);

// XOR of all inputs
assign out_xor = xor_out[0];
generate
    for (i = 1; i < 99; i = i + 1) begin : xor_reduce
        xor gate (
            .a(out_xor),
            .b(xor_out[i]),
            .y(out_xor)
        );
    end
endgenerate

endmodule

