module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] a,
    input [7:0] b,
    input select,     // Select input to choose between max_value and adder_subtractor
    output [7:0] max_value_out, // Output from max_value module
    output equal_flag, // Flag indicating whether the two inputs are equal
    output [7:0] adder_subtractor_out, // Output from adder_subtractor module
    output [7:0] sum // Addictive functional module output
);

reg [7:0] max_value;
reg equal_flag;
reg [7:0] adder_subtractor_out_reg;
reg [7:0] sum_reg;
reg [1:0] select_reg;

max_value max_value_inst (
    .a(a),
    .b(b),
    .max(max_value),
    .equal_flag(equal_flag)
);

adder_subtractor adder_subtractor_inst (
    .A(max_value),
    .B(adder_subtractor_out_reg),
    .carry_in(1'b0),
    .sub(1'b0),
    .sum(sum_reg),
    .borrow_out()
);

always @ (posedge clk) begin
    if (reset) begin
        max_value_out <= 8'b0;
        equal_flag <= 1'b0;
        adder_subtractor_out <= 8'b0;
        sum <= 8'b0;
        select_reg <= 2'b0;
    end else begin
        case (select_reg)
            2'b00: begin // max_value
                max_value_out <= max_value;
                equal_flag <= equal_flag;
                adder_subtractor_out <= adder_subtractor_out;
                sum <= sum;
            end
            2'b01: begin // adder_subtractor
                max_value_out <= max_value_out;
                equal_flag <= equal_flag;
                adder_subtractor_out <= adder_subtractor_out_reg;
                sum <= sum;
            end
            2'b10: begin // sum
                max_value_out <= max_value_out;
                equal_flag <= equal_flag;
                adder_subtractor_out <= adder_subtractor_out;
                sum <= sum_reg;
            end
        endcase
        select_reg <= select;
    end
end

always @ (posedge clk) begin
    if (reset) begin
        adder_subtractor_out_reg <= 8'b0;
        sum_reg <= 8'b0;
    end else begin
        adder_subtractor_out_reg <= max_value == a ? b : a;
        sum_reg <= max_value + adder_subtractor_out_reg;
    end
end

endmodule

module max_value (
    input [7:0] a,
    input [7:0] b,
    output reg [7:0] max,
    output equal_flag
);

always @ (*) begin
    if (a > b) begin
        max = a;
        equal_flag = 1'b0;
    end else if (a < b) begin
        max = b;
        equal_flag = 1'b0;
    end else begin
        max = a;
        equal_flag = 1'b1;
    end
end

endmodule

module adder_subtractor (
    input [7:0] A,
    input [7:0] B,
    input carry_in,
    input sub,
    output reg [7:0] sum,
    output reg borrow_out
);

always @ (*) begin
    if (sub) begin
        sum = A - B - carry_in;
        borrow_out = sum[8];
    end else begin
        sum = A + B + carry_in;
        borrow_out = sum[8];
    end
end

endmodule

