  output rising_edge,
  output falling_edge
);

  reg prev_in;

  always @ (posedge in or negedge in) begin
    if (in && !prev_in) begin
      rising_edge <= 1;
    end else begin
      rising_edge <= 0;
    end

    if (!in && prev_in) begin
      falling_edge <= 1;
