module ssdCtrl(
    input CLK,
    input RST,
    input [9:0] DIN,
    output [3:0] AN,
    output [6:0] SEG,
    output DOT,
    output wire [15:0] bcdData
);

// 1 kHz Clock Divider
parameter [15:0] cntEndVal = 16'hC350;
reg [15:0] clkCount;
reg DCLK;

// Binary Data to BCD "g" value format x.xx
wire [15:0] bcdOut;
assign bcdData = bcdOut;

// 2 Bit Counter
reg [1:0] CNT;

// Output Data Mux
reg [3:0] muxData;

// Decimal point signal
assign DOT = (CNT == 2'b11) ? 1'b0 : 1'b1;

// Format Data
Format_Data FDATA(
    .CLK(CLK),
    .DCLK(DCLK),
    .RST(RST),
    .DIN(DIN),
    .BCDOUT(bcdOut)
);

// Output Data Mux
always @(CNT[1] or CNT[0] or bcdOut or RST)
    if (RST == 1'b1)
        muxData <= 4'b0000;
    else
        case (CNT)
            2'b00 : muxData <= bcdOut[3:0];
            2'b01 : muxData <= bcdOut[7:4];
            2'b10 : muxData <= bcdOut[11:8];
            2'b11 : muxData <= bcdOut[15:12];
            default : muxData <= 4'b0000;
        endcase

// Segment Decoder
always @(posedge DCLK or posedge RST)
    if (RST == 1'b1)
        SEG <= 7'b1000000;
    else 
        case (muxData)
            4'h0 : SEG <= 7'b1000000;   // 0
            4'h1 : SEG <= 7'b1111001;   // 1
            4'h2 : SEG <= 7'b0100100;   // 2
            4'h3 : SEG <= 7'b0110000;   // 3
            4'h4 : SEG <= 7'b0011001;   // 4
            4'h5 : SEG <= 7'b0010010;   // 5
            4'h6 : SEG <= 7'b0000010;   // 6
            4'h7 : SEG <= 7'b1111000;   // 7
            4'h8 : SEG <= 7'b0000000;   // 8
            4'h9 : SEG <= 7'b0010000;   // 9
            4'hA : SEG <= 7'b0111111;   // Minus
            4'hF : SEG <= 7'b1111111;   // Off
            default : SEG <= 7'b1111111;
        endcase

// Anode Decoder
always @(posedge DCLK or posedge RST)
    if (RST == 1'b1)
        AN <= 4'b1111;
    else 
        case (CNT)
            2'b00 : AN <= 4'b1110;   // 0
            2'b01 : AN <= 4'b1101;   // 1
            2'b10 : AN <= 4'b1011;   // 2
            2'b11 : AN <= 4'b0111;   // 3
            default : AN <= 4'b1111; // All off
        endcase

// 2 Bit Counter
always @(posedge DCLK) begin
    CNT <= CNT + 1'b1;
end

// 1kHz Clock Divider
always @(posedge CLK) begin
    if (clkCount == cntEndVal) begin
        DCLK <= 1'b1;
        clkCount <= 16'h0000;
    end
    else begin
        DCLK <= 1'b0;
        clkCount <= clkCount + 1'b1;
    end
end

endmodule

module restoring_divider (
    input clk,
    input rst,
    input [15:0] dividend,
    input [15:0] divisor,
    output reg [15:0] quotient
);

reg [15:0] remainder;
reg [3:0] count;

always @(posedge clk) begin
    if (rst) begin
        quotient <= 0;
        remainder <= 0;
        count <= 0;
    end else begin
        if (count == 0) begin
            remainder <= dividend;
            count <= 16;
        end else begin
            remainder <= {remainder, 1'b0};
            count <= count - 1;
            if (remainder >= divisor) begin
                remainder <= remainder - divisor;
                quotient[count - 1] <= 1'b1;
            end else begin
                quotient[count - 1] <= 1'b0;
            end
        end
    end
end

endmodule

module barrel_shifter (
    input [15:0] DATA,
    input [3:0] SHIFT,
    input [1:0] CTRL,
    output reg [15:0] out
);

reg [15:0] shift_reg1, shift_reg2, shift_reg3;

always @(*) begin
    shift_reg1 = DATA;
    shift_reg2 = (CTRL == 2'b00) ? {DATA[14:0], 1'b0} :
                 (CTRL == 2'b01) ? {1'b0, DATA[15:1]} :
                 (CTRL == 2'b10) ? {{DATA[15], DATA[15:1]}, DATA[15]} :
                                   {DATA[0], DATA[15:1]};
    shift_reg3 = (SHIFT[3] == 1'b1) ? shift_reg2 :
                 (SHIFT[2] == 1'b1) ? shift_reg2 >> 2 :
                 (SHIFT[1] == 1'b1) ? shift_reg2 >> 4 :
                                      shift_reg2 >> 8;
    out = (SHIFT[0] == 1'b1) ? shift_reg3 :
          (SHIFT[1:0] == 2'b01) ? {shift_reg3[0], shift_reg3[15:1]} :
          (SHIFT[1:0] == 2'b10) ? {{shift_reg3[15], shift_reg3[15:1]}, shift_reg3[15]} :
                                   {shift_reg3[14:0], shift_reg3[0]};
end

endmodule

module top_module (
    input [3:0] A,
    input [3:0] B,
    input [2:0] OP,
    output eq, 
    output gt, 
    output [3:0] Y
);

    // 4-bit magnitude comparator module
    wire eq;
    wire gt;
    comparator_4bit cmp4(
        .A(A),
        .B(B),
        .eq(eq),
        .gt(gt)
    );

    // 4-bit ALU module
    wire [3:0] alu_out;
    alu_4bit alu4(
        .A(A),
        .B(B),
        .OP(OP),
        .Y(alu_out)
    );

    // Final output module
    wire [3:0] final_out;
    assign final_out = (eq | gt) ? 4'b1 : alu_out;

    // Assign outputs
    assign eq = cmp4.eq;
    assign gt = cmp4.gt;
    assign Y = final_out;

endmodule

// 4-bit magnitude comparator module
module comparator_4bit (
    input [3:0] A,
    input [3:0] B,
    output eq, 
    output gt
);

    assign eq = (A == B);
    assign gt = (A > B);

endmodule

// 4-bit ALU module
module alu_4bit (
    input [3:0] A,
    input [3:0] B,
    input [2:0] OP,
    output [3:0] Y
);

    always @(*) begin
        case (OP)
            3'b000: Y = A & B;
            3'b001: Y = A | B;
            3'b010: Y = A + B;
            3'b011: Y = A - B;
            3'b100: Y = A ^ B;
            3'b101: Y = ~A;
            3'b110: Y = A << 1;
            3'b111: Y = A >> 1;
        endcase
    end

endmodule

module fifo_buffer
  #(
    parameter width = 8,
    parameter els = 4
  )
  (
    input clk,
    input reset,
    input [width-1:0] data_i,
    input v_i,
    output ready_o,
    output [width-1:0] data_o,
    output v_o,
    input yumi_i
  );

  localparam ptr_width = $clog2(els+1);

  reg [width-1:0] buffer [0:els-1];
  reg [ptr_width-1:0] head = 0;
  reg [ptr_width-1:0] tail = 0;
  reg [ptr_width-1:0] count = 0;

  assign ready_o = (count != els);
  assign v_o = (count != 0);

  always @(posedge clk) begin
    if (reset) begin
      head <= 0;
      tail <= 0;
      count <= 0;
    end else begin
      if (v_i && ready_o) begin
        buffer[head] <= data_i;
        head <= head + 1;
        count <= count + 1;
      end
      if (yumi_i && v_o) begin
        tail <= tail + 1;
        count <= count - 1;
      end
    end
  end

  always @(posedge clk) begin
    if (reset) begin
      data_o <= 0;
    end else begin
      if (v_o) begin
        data_o <= buffer[tail];
      end
    end
  end

endmodule

module shift_register(clk, reset, load, data_in, shift, data_out);
  input clk, reset, load, shift;
  input [3:0] data_in;
  output [3:0] data_out;
  reg [3:0] register;

  always @(posedge clk, negedge reset) begin
    if (reset == 1) begin
      register <= 4'b0000;
    end else if (load == 1) begin
      register <= data_in;
    end else if (shift == 1) begin
      register <= {register[2:0], 1'b0};
    end
  end

  assign data_out = register;

endmodule

module altera_mem_if_ddr3_phy_0001_fr_cycle_shifter(
    clk,
    reset_n,
    shift_by,
    datain,
    dataout
);

// ******************************************************************************************************************************** 
// BEGIN PARAMETER SECTION
// All parameters default to "" will have their values passed in from higher level wrapper with the controller and driver 

parameter DATA_WIDTH = ""; 
parameter REG_POST_RESET_HIGH = "false";

localparam RATE_MULT = 2;
localparam FULL_DATA_WIDTH = DATA_WIDTH*RATE_MULT;

// END PARAMETER SECTION
// ******************************************************************************************************************************** 

input   clk;
input   reset_n;
input   [1:0] shift_by; 
input   [FULL_DATA_WIDTH-1:0] datain;
output  [FULL_DATA_WIDTH-1:0] dataout;


reg [FULL_DATA_WIDTH-1:0] datain_r;
always @(posedge clk or negedge reset_n)
begin
    if (~reset_n) begin
        if (REG_POST_RESET_HIGH == "true")
            datain_r <= {FULL_DATA_WIDTH{1'b1}};
        else
            datain_r <= {FULL_DATA_WIDTH{1'b0}};
    end else begin
        datain_r <= datain;
    end
end


wire [DATA_WIDTH-1:0] datain_t0 = datain[(DATA_WIDTH*1)-1:(DATA_WIDTH*0)];
wire [DATA_WIDTH-1:0] datain_t1 = datain[(DATA_WIDTH*2)-1:(DATA_WIDTH*1)];
wire [DATA_WIDTH-1:0] datain_r_t1 = datain_r[(DATA_WIDTH*2)-1:(DATA_WIDTH*1)];

wire [DATA_WIDTH-1:0] shifted_data_t1;

// Shift left by one bit
assign shifted_data_t1[DATA_WIDTH-2:0] = datain_t1[DATA_WIDTH-3:0];
assign shifted_data_t1[DATA_WIDTH-1] = 1'b0;

// Shift left by two bits
wire [DATA_WIDTH-1:0] shifted_data_t1_2;
assign shifted_data_t1_2[DATA_WIDTH-3:0] = datain_t1[DATA_WIDTH-4:0];
assign shifted_data_t1_2[DATA_WIDTH-2:0] = shifted_data_t1[DATA_WIDTH-3:1];
assign shifted_data_t1_2[DATA_WIDTH-1:0] = 2'b00;

// Shift right by one bit
assign shifted_data_t0[DATA_WIDTH-1:1] = datain_t0[DATA_WIDTH-2:0];
assign shifted_data_t0[0] = 1'b0;

// Concatenate shifted data
assign dataout = (shift_by == 2'b00) ? {datain_t0, datain_t1} :
                (shift_by == 2'b01) ? {shifted_data_t1, datain_t0} :
                (shift_by == 2'b10) ? {datain_t1, shifted_data_t0} :
                {shifted_data_t1_2, datain_t0};

endmodule

