module fifo_buffer (
    input clk,
    input fifo_clear,
    input [7:0] fifo_wdata,
    input fifo_wr,
    input rd_wfifo,
    output fifo_FF,
    output [7:0] r_dat,
    output wfifo_empty,
    output [5:0] wfifo_used
);

reg [7:0] fifo [63:0];
reg [5:0] wfifo_used_reg;
wire [5:0] wfifo_used_wire;
reg fifo_FF_reg;
wire fifo_FF_wire;

// FIFO write logic
always @(posedge clk) begin
    if (fifo_clear) begin
        fifo <= 0;
        wfifo_used_reg <= 0;
        fifo_FF_reg <= 0;
    end else if (fifo_wr && !fifo_FF_reg) begin
        fifo[wfifo_used_reg +: 1] <= fifo_wdata;
        wfifo_used_reg <= wfifo_used_reg + 1;
        fifo_FF_reg <= (wfifo_used_reg == 64);
    end
end

// FIFO read logic
assign r_dat = fifo[0];
assign wfifo_empty = (wfifo_used_reg == 0);
assign wfifo_used_wire = wfifo_used_reg;
assign fifo_FF_wire = fifo_FF_reg;

always @(posedge clk) begin
    if (fifo_clear) begin
        fifo <= 0;
        wfifo_used_reg <= 0;
        fifo_FF_reg <= 0;
    end else if (rd_wfifo && !wfifo_empty) begin
        fifo[0] <= fifo[1];
        fifo[1:wfifo_used_reg-1] <= fifo[0:wfifo_used_reg-2];
        wfifo_used_reg <= wfifo_used_reg - 1;
        fifo_FF_reg <= 0;
    end
end

assign fifo_FF = fifo_FF_wire;
assign wfifo_used = wfifo_used_wire;

endmodule

module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    input CIN,
    output reg [3:0] SUM,
    output reg COUT
);

reg [3:0] A_reg, B_reg, CIN_reg;
wire [3:0] SUM1, SUM2, SUM3;
wire COUT1, COUT2, COUT3;

full_adder FA1(A_reg[0], B_reg[0], CIN_reg, SUM[0], COUT1);
full_adder FA2(A_reg[1], B_reg[1], COUT1, SUM1[1], COUT2);
full_adder FA3(A_reg[2], B_reg[2], COUT2, SUM2[2], COUT3);
full_adder FA4(A_reg[3], B_reg[3], COUT3, SUM3[3], COUT);

always @(posedge clk) begin
    A_reg <= A;
    B_reg <= B;
    CIN_reg <= CIN;
end

assign SUM = {SUM3, SUM2, SUM1, FA1.SUM};
assign COUT = FA4.COUT;

endmodule

module full_adder (
    input A,
    input B,
    input CIN,
    output reg SUM,
    output reg COUT
);

always @(A or B or CIN) begin
    SUM <= A ^ B ^ CIN;
    COUT <= (A & B) | (A & CIN) | (B & CIN);
end

endmodule

