module xor_multiplexer_module(
    input clk,
    input a_0,
    input a_1,
    input b_0,
    input b_1,
    input select,
    output reg [15:0] out_xor_multiplexer
);

    wire [7:0] a_upper_byte, a_lower_byte, b_upper_byte, b_lower_byte;
    wire [15:0] xor_output_1, xor_output_2;
    wire xor_enable;

    // Multiplexers to divide the 16-bit inputs into their upper and lower bytes
    mux_8bit mux_a_upper_byte(
        .sel(select),
        .in(a_0),
        .in(a_1),
        .out(a_upper_byte)
    );
    mux_8bit mux_a_lower_byte(
        .sel(select),
        .in(a_0),
        .in(a_1),
        .out(a_lower_byte)
    );
    mux_8bit mux_b_upper_byte(
        .sel(select),
        .in(b_0),
        .in(b_1),
        .out(b_upper_byte)
    );
    mux_8bit mux_b_lower_byte(
        .sel(select),
        .in(b_0),
        .in(b_1),
        .out(b_lower_byte)
    );

    // XOR gate implemented using AND, OR gates and a clocked always block
    xor_gate xor1(
        .a(a_upper_byte[0]),
        .b(b_upper_byte[0]),
        .out(xor_output_1[0])
    );
    xor_gate xor2(
        .a(a_upper_byte[1]),
        .b(b_upper_byte[1]),
        .out(xor_output_1[1])
    );
    xor_gate xor3(
        .a(a_upper_byte[2]),
        .b(b_upper_byte[2]),
        .out(xor_output_1[2])
    );
    xor_gate xor4(
        .a(a_upper_byte[3]),
        .b(b_upper_byte[3]),
        .out(xor_output_1[3])
    );
    xor_gate xor5(
        .a(a_upper_byte[4]),
        .b(b_upper_byte[4]),
        .out(xor_output_1[4])
    );
    xor_gate xor6(
        .a(a_upper_byte[5]),
        .b(b_upper_byte[5]),
        .out(xor_output_1[5])
    );
    xor_gate xor7(
        .a(a_upper_byte[6]),
        .b(b_upper_byte[6]),
        .out(xor_output_1[6])
    );
    xor_gate xor8(
        .a(a_upper_byte[7]),
        .b(b_upper_byte[7]),
        .out(xor_output_1[7])
    );
    xor_gate xor9(
        .a(a_lower_byte[0]),
        .b(b_lower_byte[0]),
        .out(xor_output_2[0])
    );
    xor_gate xor10(
        .a(a_lower_byte[1]),
        .b(b_lower_byte[1]),
        .out(xor_output_2[1])
    );
    xor_gate xor11(
        .a(a_lower_byte[2]),
        .b(b_lower_byte[2]),
        .out(xor_output_2[2])
    );
    xor_gate xor12(
        .a(a_lower_byte[3]),
        .b(b_lower_byte[3]),
        .out(xor_output_2[3])
    );
    xor_gate xor13(
        .a(a_lower_byte[4]),
        .b(b_lower_byte[4]),
        .out(xor_output_2[4])
    );
    xor_gate xor14(
        .a(a_lower_byte[5]),
        .b(b_lower_byte[5]),
        .out(xor_output_2[5])
    );
    xor_gate xor15(
        .a(a_lower_byte[6]),
        .b(b_lower_byte[6]),
        .out(xor_output_2[6])
    );
    xor_gate xor16(
        .a(a_lower_byte[7]),
        .b(b_lower_byte[7]),
        .out(xor_output_2[7])
    );

    // Control logic to enable one of the XOR gate modules or the functional module based on the select input value
    assign xor_enable = (select == 1'b0) ? 1'b1 : 1'b0;

    always @(posedge clk) begin
        if (xor_enable) begin
            out_xor_multiplexer <= xor_output_1 ^ xor_output_2;
        end else begin
            out_xor_multiplexer <= a_0 ^ b_0;
        end
    end

endmodule

