module mux_8bit(
    input sel,
    input [7:0] in_0,
    input [7:0] in_1,
    output reg [7:0] out
);

    always @(*) begin
        if (sel == 1'b0) begin
            out = in_0;
        end else begin
            out = in_1;
        end
    end

endmodule

// XOR gate implemented using AND, OR gates
module xor_gate(
    input a,
    input b,
    output reg out
);

    wire and1, and2, or1;

    assign and1 = a & ~b;
    assign and2 = ~a & b;
    assign or1 = and1 | and2;

    always @(*) begin
        out = or1;
    end

endmodule

module commutation(
  input wire clk,
  input wire enable_i,
  input wire reset_i,
  input wire advance_i,
  input wire direction_i,
  input wire break_i,
  input wire align_i, 
  output wire [3:0] state_o
);

reg [2:0] state_number;
reg [3:0] state_table [7:0];

always @(posedge clk) begin
  if (reset_i) begin
    state_number <= 3'b000;
    state_table[0] <= 4'b0110;
    state_table[1] <= 4'b0100;
    state_table[2] <= 4'b1100;
    state_table[3] <= 4'b1000;
    state_table[4] <= 4'b1010;
    state_table[5] <= 4'b0010;
    state_table[6] <= 4'b0000;
    state_table[7] <= 4'b1110;
  end else if (enable_i) begin
    if (advance_i && direction_i) begin
      if (state_number == 3'b101) begin
        state_number <= 3'b000;
      end else begin
        state_number <= state_number + 1;
      end
    end else if (advance_i && !direction_i) begin
      if (state_number == 3'b000) begin
        state_number <= 3'b101;
      end else begin
        state_number <= state_number - 1;
      end
    end else if (break_i) begin
      state_number <= 3'b110;
    end else if (align_i) begin
      state_number <= 3'b111;
    end
  end
end

assign state_o = state_table[state_number];

endmodule

module top_module (
    input clk,
    input reset,
    input [7:0] d,
    input [2:0] select,
    input [2:0] vec,
    output [7:0] q
);

    // Problem 1: Shift Register Module
    reg [7:0] shift_reg;
    always @(posedge clk) begin
        if (reset) begin
            shift_reg <= 8'b0;
        end else begin
            shift_reg <= {shift_reg[6:0], d};
        end
    end

    // Problem 2: Multiplexer Module
    reg [7:0] output_vec;
    always @(vec) begin
        case (vec)
            3'b000: output_vec <= 8'b00000001;
            3'b001: output_vec <= 8'b00000010;
            3'b010: output_vec <= 8'b00000100;
            3'b011: output_vec <= 8'b00001000;
            3'b100: output_vec <= 8'b00010000;
            3'b101: output_vec <= 8'b00100000;
            3'b110: output_vec <= 8'b01000000;
            3'b111: output_vec <= 8'b10000000;
        endcase
    end

    // Additional Functional Module
    reg [7:0] final_output;
    always @(shift_reg, output_vec) begin
        final_output <= shift_reg | output_vec;
    end

    // Additional Control Logic Module
    reg [1:0] active_module;
    always @(select) begin
        case (select)
            3'b000: active_module <= 2'b01; // Shift Register Active
            3'b001: active_module <= 2'b10; // Multiplexer Active
            default: active_module <= 2'b00; // Both Inactive
        endcase
    end

    // Output
    assign q = (active_module == 2'b01) ? shift_reg : final_output;

endmodule

