    input                           i_write_enable,
    input      [ADDRESS_WIDTH-1:0]  i_address,
    input      [DATA_WIDTH/8-1:0]   i_byte_enable,
    output reg [DATA_WIDTH-1:0]     o_read_data
);

    reg [DATA_WIDTH-1:0]   mem  [0:2**ADDRESS_WIDTH-1];
