module SmallBsf (
    input clk,        ///< System clock
    input rst,        ///< Reset, active high and synchronous
    input en,         ///< Filter enable
    input signed [WIDTH-1:0] dataIn,  ///< [WIDTH-1:0] Filter input
    output reg signed [WIDTH-1:0] dataOut ///< [WIDTH-1:0] Filter output
);

parameter K0_SHIFT = 6; ///< K0 filter term = 2^-K0_SHIFT
parameter K1_SHIFT = 6; ///< K1 filter term = 2^-K1_SHIFT
parameter WIDTH = 16;   ///< Width of data path
parameter CLAMP = 1;    ///< Set to 1 to clamp the accumulators

reg signed [WIDTH-1:0] acc0;
reg signed [WIDTH-1:0] acc1;
reg signed [WIDTH-1:0] acc2;

integer i;

always @(posedge clk) begin
    if (rst) begin
        acc0 <= 'd0;
        acc1 <= 'd0;
        acc2 <= 'd0;
        dataOut <= 'd0;
    end else if (en) begin
        acc0 <= dataIn + (acc0 >> K0_SHIFT);
        acc1 <= acc0 + (acc1 >> K1_SHIFT);
        acc2 <= acc1 + (acc2 >> K1_SHIFT);
        if (CLAMP && acc2 > ((2**WIDTH-1)>>1)) begin
            dataOut <= (2**WIDTH-1)>>1;
        end else if (CLAMP && acc2 < -((2**WIDTH-1)>>1)) begin
            dataOut <= -((2**WIDTH-1)>>1);
        end else begin
            dataOut <= acc2;
        end
    end
end

endmodule

module top_module (
    input clk,
    input reset,
    input [99:0] a, b, // 100-bit inputs for the adder
    input cin, // Carry-in for the adder
    input load, // Load input for the rotator
    input [1:0] ena, // Enable input for the rotator
    output cout, // Carry-out from the adder
    output [99:0] sum, // 100-bit sum from the adder
    output reg [99:0] q // Rotated output from the rotator
);

// Instantiate the adder module
carry_select_adder adder_inst(
    .a(a),
    .b(b),
    .cin(cin),
    .sum(sum),
    .cout(cout)
);

// Instantiate the rotator module
barrel_shifter rotator_inst(
    .in(sum),
    .load(load),
    .ena(ena),
    .out(q)
);

// Control logic to select between adder and rotator
always @(posedge clk, posedge reset) begin
    if (reset) begin
        q <= 0;
    end else begin
        if (ena == 2'b00) begin // Adder selected
            sum <= a + b + cin;
        end else begin // Rotator selected
            sum <= sum;
        end
    end
end

// Final output is bitwise AND of adder output and rotator output
assign q = sum & q;

endmodule

module rrp_arbiter #(
    parameter WIDTH = 4
) (
    input wire RST,
    input wire CLK,

    input wire [WIDTH-1:0] WRITE_REQ,
    input wire [WIDTH-1:0] HOLD_REQ,
    input wire [WIDTH*32-1:0] DATA_IN,
    output wire[WIDTH-1:0] READ_GRANT,

    input wire READY_OUT,
    output wire WRITE_OUT,
    output wire [31:0] DATA_OUT
);

integer m;
reg [WIDTH-1:0] prev_select;
reg [WIDTH-1:0] select;
reg hold;

wire WRITE_REQ_OR, HOLD_REQ_OR;
assign WRITE_REQ_OR = |WRITE_REQ;
assign HOLD_REQ_OR = |HOLD_REQ;

assign WRITE_OUT = |(WRITE_REQ & select & READ_GRANT);

always @(*) begin
    select = prev_select;
    if(HOLD_REQ_OR && !hold) begin
        m = 0;
        select = 1;
        while(!(HOLD_REQ & select) && (m < WIDTH)) begin
            m = m + 1;
            select = 1 << m;
        end
    end
    else if(WRITE_REQ_OR && !hold) begin
        m = 0;
        select = prev_select << 1;
        if(select == 0)
            select = 1;
        while(!(WRITE_REQ & select) && (m < WIDTH)) begin
            m = m + 1;
            select = select << 1;
            if(select == 0)
                select = 1;
        end
    end
end

always @(posedge CLK) begin
    if(RST)
        prev_select <= (1 << (WIDTH - 1));
    else if (WRITE_REQ_OR & !hold)
        prev_select <= select;
end

always @(posedge CLK) begin
    if(RST)
        hold <= 0;
    else if(READY_OUT)
        hold <= 0;
    else if (WRITE_OUT)
        hold <= 1;
end

wire [WIDTH-1:0] DATA_A [31:0];

genvar i, j;
generate
    for (i = 0; i < 32; i = i + 1) begin: gen
        for (j = 0; j < WIDTH; j = j + 1) begin: gen2
            assign DATA_A[i][j] = DATA_IN[j*32+i];
        end
    end
endgenerate

generate
    for (i = 0; i < 32; i = i + 1) begin: gen3
        assign DATA_OUT[i] = |(DATA_A[i] & select);
    end
endgenerate

assign READ_GRANT = select & {WIDTH{READY_OUT}} & WRITE_REQ;

endmodule

module DLL (
  input ref_clk,
  input fb_clk,
  output sync_clk
);

parameter delay = 10; // amount of delay to be added to the feedback clock signal
parameter tolerance = 5; // allowable difference between the reference clock signal and the synchronized clock signal

reg delayed_fb_clk;
reg [31:0] phase_diff;
reg [31:0] prev_phase_diff;
reg [31:0] delay_value;

always @(posedge ref_clk) begin
  // Delay the feedback clock signal
  #delay delayed_fb_clk <= fb_clk;

  // Calculate the phase difference between the reference clock signal and the delayed feedback clock signal
  phase_diff <= $signed($time - $realtime(delayed_fb_clk));

  // Adjust the delay of the feedback clock signal to minimize the phase difference
  if (phase_diff > tolerance) begin
    delay_value <= delay_value + 1;
  end else if (phase_diff < -tolerance) begin
    delay_value <= delay_value - 1;
  end

  // Output the synchronized clock signal
  sync_clk <= delayed_fb_clk;
end

endmodule

module my_module(
  input reset, 
  input sysclk, 
  input ival,
  output reg [2:0] baz,
  output reg [5:3] out_i,
  output reg [8:0] input_status
);

reg [13:0] foo;
reg [22:0] bam;

wire enable, debug, aux, outy, dv, value;

// drive input status
assign input_status = {foo[9:4],((baz[3:0] & foo[3:0] | (( ~baz[3:0] & bam[3:0]))))};

// drive based on foo
assign out_i = ((enable & ((aux ^ outy)))) | ((debug & dv &  ~enable)) | (( ~debug &  ~enable & value));

// not drive
always @(negedge reset or negedge sysclk) begin
  if((reset != 1'b0)) begin
    foo <= {14{1'b0}};
  end else begin
    foo[3 * ((2 - 1))] <= (4 * ((1 + 2)));
    bam[13:0] <= foo;
  end
end

// derive baz
always @(*) begin
  baz[2:0] = (bam[3:0] & foo[3:0]) | (~bam[3:0] & foo[3:0]);
end

endmodule

module sum_module(
  input wire clk,
  input wire reset,
  input wire [1:0] ctrl,
  input wire [3:0] in,
  output reg [2:0] out
);

  parameter const_val = 3;

  always @(posedge clk) begin
    if (reset) begin
      out <= 0;
    end else begin
      if (ctrl == 2'b00) begin
        out <= in;
      end else begin
        if (in + const_val >= 7) begin
          out <= 7;
        end else if (in + const_val <= 0) begin
          out <= 0;
        end else begin
          out <= in + const_val;
        end
      end
    end
  end

endmodule

