module spi_master (
  input clk,
  input cs,
  input [7:0] tx_data,
  output [7:0] rx_data,
  output tx_done,
  input rx_done
);

  reg [7:0] tx_reg;
  reg [7:0] rx_reg;
  reg tx_en;
  reg rx_en;
  reg [2:0] state;

  assign tx_done = (state == 3) ? 1'b1 : 1'b0;
  assign rx_data = rx_reg;

  always @(posedge clk) begin
    if (cs == 1'b0) begin
      case (state)
        0: begin
          tx_reg <= tx_data;
          tx_en <= 1'b1;
          state <= 1;
        end
        1: begin
          tx_en <= 1'b0;
          rx_en <= 1'b1;
          state <= 2;
        end
        2: begin
          rx_reg <= rx_data;
          rx_en <= 1'b0;
          state <= 3;
        end
        default: begin
          tx_en <= 1'b0;
          rx_en <= 1'b0;
          state <= 0;
        end
      endcase
    end else begin
      tx_en <= 1'b0;
      rx_en <= 1'b0;
      state <= 0;
    end
  end

endmodule

