          rx_en <= 1'b1;
          state <= 1;
        end
        1: begin
          tx_reg <= rx_data;
          tx_en <= 1'b1;
          rx_en <= 1'b0;
          state <= 2;
        end
        2: begin
          tx_en <= 1'b0;
          rx_en <= 1'b1;
          state <= 3;
        end
        default: begin
          tx_en <= 1'b0;
          rx_en <= 1'b0;
          state <= 0;
        end
      endcase
    end else begin
      tx_en <= 1'b0;
      rx_en <= 1'b0;
      state <= 0;
    end
  end

endmodule

