module divider (
  input signed [31:0] dividend,
  input signed [31:0] divisor,
  output signed [31:0] quotient,
  output signed [31:0] remainder
);

  reg signed [31:0] rem;
  reg signed [31:0] quot;
  reg signed [31:0] pos_dividend;
  reg signed [31:0] pos_divisor;
  reg signed [31:0] pos_quot;

  always @(*) begin
    pos_dividend = (dividend < 0) ? -dividend : dividend;
    pos_divisor = (divisor < 0) ? -divisor : divisor;

    if (dividend < 0 && divisor < 0) begin
      pos_quot = pos_dividend / pos_divisor;
      quot = pos_quot;
      remainder = pos_dividend % pos_divisor;
    end
    else if (dividend < 0) begin
      pos_quot = pos_dividend / pos_divisor;
      quot = -pos_quot;
      remainder = pos_dividend % pos_divisor;
    end
    else if (divisor < 0) begin
      pos_quot = pos_dividend / pos_divisor;
      quot = -pos_quot;
      remainder = pos_dividend % pos_divisor;
    end
    else begin
      pos_quot = pos_dividend / pos_divisor;
      quot = pos_quot;
      remainder = pos_dividend % pos_divisor;
    end
  end

endmodule

module top_module (
    input clk,
    input reset,
    input [3:0] a,
    input [3:0] b,
    input select,
    output [4:0] sum
);

    // Instantiate two 4-bit adders with active high synchronous reset
    reg [3:0] adder1_out, adder2_out;
    always @(posedge clk) begin
        if (reset) begin
            adder1_out <= 4'b0;
            adder2_out <= 4'b0;
        end else begin
            adder1_out <= a + b;
            adder2_out <= a + b;
        end
    end

    // Instantiate a functional module that adds the two inputs together to produce a 5-bit output
    reg [4:0] func_out;
    always @(*) begin
        func_out = {1'b0, a + b};
    end

    // Instantiate a multiplexer that selects between the outputs of the two adders or the output of the functional module based on the select input
    always @(*) begin
        case (select)
            2'b00: sum = adder1_out;
            2'b01: sum = adder2_out;
            2'b10: sum = func_out;
            2'b11: sum = func_out;
        endcase
    end

endmodule

module JK_FF (input J, K, C, R, E, output Q, Qn);
    reg Q, Qn;
    always @(posedge C) begin
        if (E == 1'b0) begin
            Q <= 1'b0;
            Qn <= 1'b1;
        end else if (R == 1'b0) begin
            Q <= 1'b0;
            Qn <= 1'b1;
        end else if (J == 1'b1 && K == 1'b1) begin
            Q <= ~Q;
            Qn <= ~Qn;
        end else if (J == 1'b1 && K == 1'b0) begin
            Q <= 1'b1;
            Qn <= 1'b0;
        end else if (J == 1'b0 && K == 1'b1) begin
            Q <= 1'b0;
            Qn <= 1'b1;
        end
    end
endmodule

module alu (
    input clk,
    input [7:0] d,
    input a,
    input [7:0] b,
    output reg [7:0] q
);

    reg [7:0] sum;
    reg [7:0] shift_reg;

    always @ (posedge clk) begin
        // 8-bit adder
        sum <= d + b;

        // 8-bit shift register
        shift_reg <= {shift_reg[6:0], d[0]};
    end

    // 2-to-1 MUX
    always @ (*) begin
        if (a == 1'b1) begin
            q <= shift_reg;
        end else begin
            q <= sum;
        end
    end

endmodule

module fifo (
   // Outputs
   outData,
   // Inputs
   clk, inData, wrEn, rdEn
   );

   parameter fifoDepthLog2 = 2; // depth of 4 elements
   parameter fifoDepth   = 1<<fifoDepthLog2;

   input clk;
   input [15:0] inData;
   input wrEn, rdEn;

   output [15:0] outData;

   reg [15:0] fifo[0:fifoDepth-1];
   reg [1:0] wrPtr = 2'b0; // write pointer initialized to 0
   reg [1:0] rdPtr = 2'b0; // read pointer initialized to 0
   reg [1:0] nextWrPtr;
   reg [1:0] nextRdPtr;

   always @(posedge clk) begin
      // Write operation
      if (wrEn) begin
         fifo[wrPtr] <= inData;
         nextWrPtr = wrPtr + 1;
         if (nextWrPtr == fifoDepth) begin
            nextWrPtr = 0;
         end
      end

      // Read operation
      if (rdEn) begin
         outData <= fifo[rdPtr];
         nextRdPtr = rdPtr + 1;
         if (nextRdPtr == fifoDepth) begin
            nextRdPtr = 0;
         end
      end

      wrPtr <= nextWrPtr;
      rdPtr <= nextRdPtr;
   end

endmodule

module top_module( 
    input clk,
    input reset,
    input [2:0] a,
    input [2:0] b,
    output reg [5:0] out
); 

    reg [3:0] counter_out1;
    reg [3:0] counter_out2;
    reg [5:0] adder_out;

    mux_module mux1(.a(a[0]), .b(b[0]), .c(a[1]), .d(b[1]), .select(a[2]), .x(counter_out1[0]), .y(counter_out1[1]), .z(counter_out1[2]));
    mux_module mux2(.a(a[0]), .b(b[0]), .c(a[1]), .d(b[1]), .select(a[2]), .x(counter_out2[0]), .y(counter_out2[1]), .z(counter_out2[2]));
    counter_module counter1(.clk(clk), .reset(reset), .q(counter_out1));
    counter_module counter2(.clk(clk), .reset(reset), .q(counter_out2));
    adder_module adder(.input1(counter_out1), .input2(counter_out2), .out(adder_out));

    always @(posedge clk) begin
        if (reset) begin
            counter_out1 <= 0;
            counter_out2 <= 0;
            adder_out <= 0;
        end else begin
            counter_out1 <= counter1.q;
            counter_out2 <= counter2.q;
            adder_out <= adder.out;
        end
    end

    assign out = adder_out;

endmodule

module mux_module (
    input a, b, c, d, select,
    output reg x, y, z
);

    always @(*) begin
        case (select)
            2'b00: begin
                x = a;
                y = b;
                z = c;
            end
            2'b01: begin
                x = a;
                y = b;
                z = d;
            end
            2'b10: begin
                x = a;
                y = c;
                z = b;
            end
            2'b11: begin
                x = a;
                y = c;
                z = d;
            end
        endcase
    end

endmodule

module counter_module (
    input clk, reset,
    output reg [3:0] q
);

    always @(posedge clk) begin
        if (reset) begin
            q <= 0;
        end else begin
            q <= q + 1;
        end
    end

endmodule

module adder_module (
    input [3:0] input1,
    input [3:0] input2,
    output reg [5:0] out
);

    always @(*) begin
        out = {2'b00, input1} + {2'b00, input2};
    end

endmodule

