);

localparam DATA_WIDTH = C_AXI_DATA_WIDTH;
localparam BURST_SIZE = DATA_WIDTH / 8;
localparam MC_DATA_WIDTH = DATA_WIDTH * BURST_SIZE;

reg [C_ID_WIDTH-1:0] s_arid_r;
reg [C_AXI_ADDR_WIDTH-1:0] araddr;
