reg [BURST_SIZE-1:0] data_byte_r;
reg [BURST_SIZE-1:0] byte_count;
reg [BURST_SIZE-1:0] byte_count_r;
reg [C_ID_WIDTH-1:0] mc_id;
reg [C_ID_WIDTH-1:0] mc_id_r;
reg [7:0] mc_len;
reg [7:0] mc_len_r;
reg [2:0] mc_size;
reg [2:0] mc_size_r;
reg [1:0] mc_burst;
reg [1:0] mc_burst_r;
reg mc_valid_r;
reg [C_ID_WIDTH-1:0] next_id;
reg [7:0] next_len;
reg [2:0] next_size;
reg [1:0] next_burst;
reg next_valid;
reg next_pending;
reg [C_ID_WIDTH-1:0] next_id_r;
reg [7:0] next_len_r;
reg [2:0] next_size_r;
reg [1:0] next_burst_r;
reg next_valid_r;
reg next_pending_r;
reg [C_ID_WIDTH-1:0] next_id_rr;
reg [7:0] next_len_rr;
reg [2:0] next_size_rr;
reg [1:0] next_burst_rr;
reg next_valid_rr;
reg next_pending_rr;

always @(posedge clk) begin
  if (reset) begin
    s_arid_r <= 0;
    araddr_r <= 0;
    arlen_r <= 0;
    arsize_r <= 0;
    arburst_r <= 0;
    arvalid_r <= 0;
    data_r <= 0;
    data_word_r <= 0;
    data_byte_r <= 0;
