    mc_valid_r <= 0;
    next_id_r <= 0;
    next_len_r <= 0;
    next_size_r <= 0;
    next_burst_r <= 0;
    next_valid_r <= 0;
    next_pending_r <= 0;
    next_id_rr <= 0;
    next_len_rr <= 0;
    next_size_rr <= 0;
    next_burst_rr <= 0;
    next_valid_rr <= 0;
    next_pending_rr <= 0;
  end else begin
    s_arid_r <= s_arid;
    araddr_r <= s_araddr;
    arlen_r <= s_arlen;
    arsize_r <= s_arsize;
    arburst_r <= s_arburst;
    arvalid_r <= s_arvalid;
    data_r <= {data_r[(DATA_WIDTH-1):0], s_axi_rdata};
    data_word_r <= s_axi_rdata;
    data_byte_r <= s_axi_rdata[(8*byte_count_r+7):8*byte_count_r];
    byte_count_r <= byte_count_r + 1;
    mc_id_r <= next_id_r;
    mc_len_r <= next_len_r;
    mc_size_r <= next_size_r;
    mc_burst_r <= next_burst_r;
    mc_valid_r <= next_valid_r;
    next_id_r <= next_id_rr;
    next_len_r <= next_len_rr;
    next_size_r <= next_size_rr;
    next_burst_r <= next_burst_rr;
    next_valid_r <= next_valid_rr;
    next_pending_r <= next_pending_rr;
    if (r_push) begin
      next_id_rr <= s_arid_r;
      next_len_rr <= s_arlen;
      next_size_rr <= s_arsize;
      next_burst_rr <= s_arburst;
      next_valid_rr <= s_arvalid;
      next_pending_rr <= 1;
    end else begin
      next_pending_rr <= next_pending_r;
    end
  end
end

