module FFSDQSRHD2X (CK, D, RN, SN, TE, TI, Q);
input  CK ;
input  D ;
input  RN ;
input  SN ;
input  TE ;
input  TI ;
output Q ;
reg NOTIFIER ;
reg [1:0] Q_reg;
reg [1:0] Q_next;

always @(posedge CK) begin
    if (RN) begin
        Q_reg <= 0;
    end else if (SN) begin
        Q_reg <= 1;
    end else if (TE) begin
        Q_reg <= Q_next;
    end else begin
        Q_reg <= D;
    end
end

always @(posedge CK) begin
    Q_next <= Q_reg;
end

assign Q = Q_reg[0];

endmodule

module vending_machine(clk, rst, deposit, deposited, select, selected, price, cancel, maintenance,
			refund, refundall, depositall, product, change, state);
	input 	clk, rst;
	input	[9:0] deposit, price;
	input	[4:0] select;
	input	deposited, selected, cancel, maintenance;
	output	refund, refundall, depositall;
	output	[4:0] product;
	output	[9:0] change;
	output	[2:0] state;
	reg 	[9:0] curr_deposit;
	reg 	[4:0] curr_product;
	reg 	[9:0] curr_change;
	reg 	[2:0] curr_state;
	wire	[9:0] purchase_price;
	wire	[9:0] change_amount;
	wire	[4:0] valid_product;
	wire	[9:0] deposit_amount;
	wire	[1:0] next_state;

	// Calculate the purchase price
	assign purchase_price = (selected == 1) ? 100 :
	                        (selected == 2) ? 200 :
	                        (selected == 3) ? 300 :
	                        (selected == 4) ? 400 :
	                        (selected == 5) ? 500 :
	                        0;

	// Calculate the change amount
	assign change_amount = curr_deposit - purchase_price;

	// Determine the valid products
	assign valid_product = (deposit >= 100) ? 1 :
	                        (deposit >= 200) ? 2 :
	                        (deposit >= 300) ? 3 :
	                        (deposit >= 400) ? 4 :
	                        (deposit >= 500) ? 5 :
	                        0;

	// Determine the deposit amount
	assign deposit_amount = (maintenance) ? curr_deposit :
	                         (cancel) ? 0 :
	                         (deposited) ? curr_deposit + deposit :
	                         curr_deposit;

	// Determine the next state
	always @(posedge clk) begin
		case (curr_state)
			0: if (valid_product) curr_state <= 1;
			   else curr_state <= 0;
			1: if (selected && (selected == valid_product)) curr_state <= 2;
			   else if (cancel) curr_state <= 0;
			   else curr_state <= 1;
			2: curr_state <= 3;
			3: curr_state <= 4;
			4: curr_state <= 0;
			default: curr_state <= 0;
		endcase
	end

	// Update the current state and outputs
	always @(posedge clk) begin
		case (curr_state)
			0: begin
				   curr_deposit <= deposit_amount;
				   curr_product <= 0;
				   curr_change <= 0;
				   refundall <= 0;
				   depositall <= 0;
				   refund <= 0;
				   product <= 0;
				   change <= 0;
			   end
			1: begin
				   curr_deposit <= deposit_amount;
				   curr_product <= selected;
				   curr_change <= 0;
				   refundall <= 0;
				   depositall <= 0;
				   refund <= 0;
				   product <= 0;
				   change <= 0;
			   end
			2: begin
				   curr_deposit <= 0;
				   curr_product <= 0;
				   curr_change <= change_amount;
				   refundall <= 0;
				   depositall <= 0;
				   refund <= 0;
				   product <= selected;
				   change <= change_amount;
			   end
			3: begin
				   curr_deposit <= 0;
				   curr_product <= 0;
				   curr_change <= 0;
				   refundall <= 0;
				   depositall <= 0;
				   refund <= 0;
				   product <= selected;
				   change <= 0;
			   end
			4: begin
				   curr_deposit <= 0;
				   curr_product <= 0;
				   curr_change <= 0;
				   refundall <= 0;
				   depositall <= 0;
				   refund <= 0;
				   product <= 0;
				   change <= 0;
			   end
			default: begin
				   curr_deposit <= 0;
				   curr_product <= 0;
				   curr_change <= 0;
				   refundall <= 0;
				   depositall <= 0;
				   refund <= 0;
				   product <= 0;
				   change <= 0;
			   end
		endcase
	end

	// Update the refund and depositall outputs
	always @(posedge clk) begin
		if (cancel || (maintenance && !deposit)) begin
			refundall <= 1;
			depositall <= 0;
		end else if (maintenance) begin
			refundall <= 0;
			depositall <= 1;
		end else begin
			refundall <= 0;
			depositall <= 0;
		end
	end

	// Update the refund output
	always @(posedge clk) begin
		if (curr_state == 1 && valid_product != selected) begin
			refund <= 1;
		end else begin
			refund <= 0;
		end
	end

	// Update the product output
	always @(posedge clk) begin
		product <= curr_product;
	end

	// Update the change output
	always @(posedge clk) begin
		change <= curr_change;
	end

	// Update the state output
	always @(posedge clk) begin
		state <= curr_state;
	end
endmodule

module shift_register_ring_counter (
    input clk,
    input d,
    input enable,
    output reg q
);

parameter WIDTH = 4; // Set the width of the shift register and ring counter

reg [WIDTH-1:0] shift_reg; // Declare the shift register
reg [WIDTH-1:0] ring_counter; // Declare the ring counter

always @(posedge clk) begin
    if (enable) begin
        // Shift the values in the shift register to the left
        shift_reg <= {shift_reg[WIDTH-2:0], d};

        // Increment the ring counter
        ring_counter <= ring_counter + 1;

        // Output the value in the final stage of the shift register
        q <= shift_reg[WIDTH-1];
    end
end

endmodule

module dma_controller (
    input clk,
    input rst,
    input start,
    input [31:0] src_addr,
    input [31:0] dest_addr,
    input [9:0] length,
    output busy,
    output error,
    output done
);

reg [31:0] src_reg;
reg [31:0] dest_reg;
reg [9:0] length_reg;
reg [31:0] count_reg;
reg busy_reg;
reg error_reg;
reg done_reg;

always @(posedge clk) begin
    if (rst) begin
        src_reg <= 0;
        dest_reg <= 0;
        length_reg <= 0;
        count_reg <= 0;
        busy_reg <= 0;
        error_reg <= 0;
        done_reg <= 0;
    end else begin
        if (start) begin
            src_reg <= src_addr;
            dest_reg <= dest_addr;
            length_reg <= length;
            count_reg <= 0;
            busy_reg <= 1;
            error_reg <= 0;
            done_reg <= 0;
        end else if (busy_reg) begin
            if (count_reg == length_reg - 1) begin
                busy_reg <= 0;
                done_reg <= 1;
            end else begin
                count_reg <= count_reg + 1;
                src_reg <= src_reg + 4;
                dest_reg <= dest_reg + 4;
            end
        end
    end
end

assign busy = busy_reg;
assign error = error_reg;
assign done = done_reg;

endmodule

module d_ff_nand (
