    assign nand1_out = ~(d & clk);
    assign nand2_out = ~(q_delayed & clk);
    assign inv1_out = ~(clk);

    always @(posedge clk) begin
        q <= nand1_out & q_delayed;
        q_delayed <= nand2_out & d;
    end

