    output reg [2:0] shift_reg_out,
    output reg [2:0] sum_out
);

    wire d_ff_q_delayed;
    wire [2:0] d_ff_out;

    d_ff_nand d_ff_inst (
        .clk(clk),
        .d(d),
        .q(d_ff_q),
