always @(posedge clk, posedge reset) begin
    if (reset) begin
        prev_data <= 8'b0;
        anyedge <= 1'b0;
    end else begin
        if (data_in != prev_data) begin
            anyedge <= 1'b1;
        end else begin
            anyedge <= 1'b0;
        end
        prev_data <= data_in;
    end
end

