module top_module (
    input [3:0] D,
    input [2:0] select,
    input enable,
    input LOAD,
    input SHIFT,
    output [15:0] q
);

    wire [15:0] decoder_output;
    wire [3:0] shift_input;
    wire [15:0] shift_output;
    wire [15:0] final_output;

    decoder_4to16 decoder(
        .in(select),
        .out(decoder_output)
    );

    assign shift_input = D;

    shift_register_4bit shift_reg(
        .in(shift_input),
        .load(LOAD),
        .shift(SHIFT),
        .out(shift_output)
    );

    adder_16bit adder(
