module xor_adder_flipflop (
    input clk,
    input [3:0] a, b,
    input cin, d,
    output reg cout,
    output reg [4:0] sum,
    output reg q,
    output reg final_out
);

    reg [3:0] adder_out;
    reg [4:0] sum_temp;
    reg q_temp;

    // Full Adder
    full_adder FA (
        .a(a),
        .b(b),
        .cin(cin),
        .cout(cout),
        .sum(adder_out)
    );

    // Dual-edge Triggered Flip-flop
    always @(posedge clk or negedge clk) begin
        if (d) begin
            q_temp <= ~q_temp;
        end
    end

    // XOR Operation
    always @(*) begin
        sum_temp = adder_out + {1'b0, q_temp};
        final_out = sum_temp ^ q_temp;
    end

    // Output Assignments
    assign sum = sum_temp;
    assign q = q_temp;

endmodule

