    input [7:0] d,
    output [7:0] q
);

reg [7:0] q_reg;
reg [7:0] d_reg;

always @(posedge clk) begin
    d_reg <= d;
    q_reg <= q_reg & ~(d_reg ^ q_reg);
end

assign q = q_reg;

