module top_module (
    input clk,
    input reset,
    input [7:0] d,
    input [7:0] in,
    output [7:0] q,
    output [7:0] rising_edge,
    output [7:0] sum_output
);

wire [7:0] rising_edge_detection_output;
wire [7:0] random_number;

