module flag_gen(clk, rst, full, emptyp, wr_en, rd_en);
  input clk, rst, wr_en, rd_en;
  output full, emptyp;
  reg full, emptyp;
  reg [4:0] count;
  parameter max_count=5'b01111;

  always @ (posedge clk or negedge rst) begin
    if(!rst) count <= 0;
    else begin
      case({wr_en, rd_en})
        2'b00: count <= count;
        2'b01: if(count !== 5'b00000) count <= count - 1;
        2'b10: if(count !== max_count) count <= count + 1;
        2'b11: count <= count;
      endcase
    end
  end

  always @ (count) begin
    if(count == 5'b00000) emptyp <= 1;
    else emptyp <= 0;
  end

  always @ (count) begin
    if(count == max_count) full <= 1;
    else full <= 0;
  end
endmodule

module four_bit_adder (A, B, Cin, Sum, Cout);
  input [3:0] A, B;
  input Cin;
  output [3:0] Sum;
  output Cout;

  wire [3:0] temp_sum;
  wire temp_cout;

  // First bit
  assign temp_sum[0] = A[0] ^ B[0] ^ Cin;
  assign temp_cout = (A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin);

  // Second bit
  assign temp_sum[1] = A[1] ^ B[1] ^ temp_cout;
  assign temp_cout = (A[1] & B[1]) | (A[1] & temp_cout) | (B[1] & temp_cout);

  // Third bit
  assign temp_sum[2] = A[2] ^ B[2] ^ temp_cout;
  assign temp_cout = (A[2] & B[2]) | (A[2] & temp_cout) | (B[2] & temp_cout);

  // Fourth bit
  assign temp_sum[3] = A[3] ^ B[3] ^ temp_cout;
  assign Cout = temp_cout;

  assign Sum = temp_sum;

endmodule

module fsm_3bit_sequence_detection (
  input clk,
  input reset,
  input in1,
  output reg out
);

  // Define the three states
  parameter IDLE = 2'd0;
  parameter FIRST_HIGH = 2'd1;
  parameter SECOND_HIGH = 2'd2;

  // Define the current state and next state variables
  reg [1:0] state, next_state;

  // Define the count variable to keep track of the number of high signals detected
  reg [1:0] count;

  // Define the output signal
  reg out_reg;

  // Assign the initial state and next state
  always @ (posedge clk, posedge reset) begin
    if (reset) begin
      state <= IDLE;
      next_state <= IDLE;
      count <= 2'd0;
      out_reg <= 1'b0;
    end
    else begin
      state <= next_state;
    end
  end

  // Define the state transition logic
  always @ (state, in1) begin
    case (state)
      IDLE: begin
        if (in1 == 1'b1) begin
          next_state <= FIRST_HIGH;
          count <= 2'd1;
        end
        else begin
          next_state <= IDLE;
          count <= 2'd0;
        end
      end
      FIRST_HIGH: begin
        if (in1 == 1'b1) begin
          next_state <= SECOND_HIGH;
          count <= 2'd2;
        end
        else begin
          next_state <= IDLE;
          count <= 2'd0;
        end
      end
      SECOND_HIGH: begin
        if (in1 == 1'b1) begin
          next_state <= IDLE;
          count <= 2'd0;
          out_reg <= 1'b1;
        end
        else begin
          next_state <= IDLE;
          count <= 2'd0;
        end
      end
      default: next_state <= IDLE;
    endcase
  end

  // Assign the output signal
  always @ (posedge clk, posedge reset) begin
    if (reset) begin
      out <= 1'b0;
    end
    else begin
      out <= out_reg;
    end
  end

endmodule

module STRUCT_NEURAL(
    input [16:1] inputA,
    input [16:1] inputB,
    input [16:1] c111,
    input [16:1] c112,
    input [16:1] c121,
    input [16:1] c122,
    input [16:1] c211,
    input [16:1] c212,
    input [16:1] c221,
    input [16:1] c222,
    input [16:1] b11,
    input [16:1] b12,
    input [16:1] b21,
    input [16:1] b22,
    output reg [16:1] out1,
    output reg [16:1] out2
);

reg [16:1] n1, n2, n3, n4;

function [16:1] sigmoid;
    input [16:1] x;
    begin
        sigmoid = 1 / (1 + exp(-x));
    end
endfunction

always @(*) begin
    n1 = sigmoid(inputA * c111 + inputB * c121 + b11);
    n2 = sigmoid(inputA * c112 + inputB * c122 + b12);
    n3 = sigmoid(n1 * c211 + n2 * c221 + b21);
    n4 = sigmoid(n1 * c212 + n2 * c222 + b22);
    out1 = n3;
    out2 = n4;
end

endmodule

