    input select,  // Select input to choose between shift register and functional module
    input [3:0] data, // 4-bit input for loading the shift register
    output [7:0] q  // 8-bit output from the active module
);

    reg [3:0] counter;
    reg [7:0] shift_reg;
    wire [7:0] xor_output;
    wire load_shift_reg;

    assign load_shift_reg = (reset || select) ? 1'b1 : 1'b0;

    xor_module xor_inst (
        .a(shift_reg),
        .b(counter),
        .y(xor_output)
    );

    always @(posedge clk) begin
        if (reset) begin
            shift_reg <= 8'b0;
            counter <= 4'b0;
        end else if (load_shift_reg) begin
            shift_reg <= {4'b0011, data};
        end else begin
            shift_reg <= {shift_reg[6:0], shift_reg[7]};
            counter <= counter + 1;
        end
    end

    assign q = (select) ? xor_output : shift_reg;

endmodule

