module priority_encoder (
    output reg [3:0] encoded,
    input [7:0] inputs);

    always @* begin
        if (inputs[0] <= inputs[1] && inputs[0] <= inputs[2] && inputs[0] <= inputs[3])
            encoded = 4'b0001;
        else if (inputs[1] <= inputs[2] && inputs[1] <= inputs[3])
            encoded = 4'b0010;
        else if (inputs[2] <= inputs[3])
            encoded = 4'b0100;
        else
            encoded = 4'b1000;
    end

endmodule

module decoder (
    output reg [7:0] decoded,
    input [3:0] encoded);

    always @* begin
        case (encoded)
            4'b0001: decoded = inputs[0];
            4'b0010: decoded = inputs[1];
            4'b0100: decoded = inputs[2];
            4'b1000: decoded = inputs[3];
            default: decoded = 8'h00;
        endcase
    end

endmodule

module axi_fifo (
    input m_axis_aclk,
    input m_axis_aresetn,
    input m_axis_ready,
    output m_axis_valid,
    output [C_DATA_WIDTH-1:0] m_axis_data,

    input s_axis_aclk,
    input s_axis_aresetn,
    output s_axis_ready,
    input s_axis_valid,
    input [C_DATA_WIDTH-1:0] s_axis_data,
    output s_axis_empty
);

parameter C_DATA_WIDTH = 64;
parameter C_CLKS_ASYNC = 1;
parameter C_ADDRESS_WIDTH = 4;

// Generate the FIFO memory based on the address width parameter
generate if (C_ADDRESS_WIDTH == 0) begin
    // Single-entry buffer
    reg [C_DATA_WIDTH-1:0] ram;
    reg s_axis_waddr = 1'b0;
    reg m_axis_raddr = 1'b0;

    // Synchronize write address from stream clock domain to AXI clock domain
    sync_bits #(
        .NUM_BITS(1),
        .CLK_ASYNC(C_CLKS_ASYNC)
    ) i_waddr_sync (
        .out_clk(m_axis_aclk),
        .out_resetn(s_axis_aresetn),
        .in(s_axis_waddr),
        .out(m_axis_waddr)
    );

    // Synchronize read address from AXI clock domain to stream clock domain
    sync_bits #(
        .NUM_BITS(1),
        .CLK_ASYNC(C_CLKS_ASYNC)
    ) i_raddr_sync (
        .out_clk(s_axis_aclk),
        .out_resetn(m_axis_aresetn),
        .in(m_axis_raddr),
        .out(s_axis_raddr)
    );

    // Set m_axis_valid high when there is data available to read
    assign m_axis_valid = m_axis_raddr != m_axis_waddr;

    // Set s_axis_ready high when there is space available to write
    assign s_axis_ready = s_axis_raddr == s_axis_waddr;

    // Set s_axis_empty high when there is no data available to read
    assign s_axis_empty = s_axis_raddr == s_axis_waddr;

    // Write data to the buffer on the stream clock domain
    always @(posedge s_axis_aclk) begin
        if (s_axis_aresetn == 1'b0) begin
            s_axis_waddr <= 1'b0;
        end else begin
            if (s_axis_ready & s_axis_valid) begin
                s_axis_waddr <= s_axis_waddr + 1'b1;
                ram <= s_axis_data;
            end
        end
    end

    // Read data from the buffer on the AXI clock domain
    always @(posedge m_axis_aclk) begin
        if (m_axis_aresetn == 1'b0) begin
            m_axis_raddr <= 1'b0;
        end else begin
            if (m_axis_valid & m_axis_ready)
                m_axis_raddr <= m_axis_raddr + 1'b1;
        end
    end

    // Output the data from the buffer
    assign m_axis_data = ram;

end else begin
    // Multi-entry buffer
    reg [C_DATA_WIDTH-1:0] ram[0:2**C_ADDRESS_WIDTH-1];

    wire [C_ADDRESS_WIDTH-1:0] s_axis_waddr;
    wire [C_ADDRESS_WIDTH-1:0] m_axis_raddr_next;

    if (C_CLKS_ASYNC == 1) begin
        // Synchronize write and read addresses using gray code
        fifo_address_gray_pipelined #(
            .C_ADDRESS_WIDTH(C_ADDRESS_WIDTH)
        ) i_address_gray (
            .m_axis_aclk(m_axis_aclk),
            .m_axis_aresetn(m_axis_aresetn),
            .m_axis_ready(m_axis_ready),
            .m_axis_valid(m_axis_valid),
            .m_axis_raddr_next(m_axis_raddr_next),

            .s_axis_aclk(s_axis_aclk),
            .s_axis_aresetn(s_axis_aresetn),
            .s_axis_ready(s_axis_ready),
            .s_axis_valid(s_axis_valid),
            .s_axis_empty(s_axis_empty),
            .s_axis_waddr(s_axis_waddr)
        );
    end else begin
        // Synchronize write and read addresses using a register
        reg [C_ADDRESS_WIDTH-1:0] s_axis_waddr_d1;
        assign s_axis_raddr = m_axis_raddr_next;
        assign m_axis_waddr = s_axis_waddr_d1;

        always @(posedge s_axis_aclk) begin
            if (s_axis_aresetn == 1'b0) begin
                s_axis_waddr_d1 <= 'h00;
            end else begin
                s_axis_waddr_d1 <= s_axis_waddr;
            end
        end
    end

    // Write data to the buffer on the stream clock domain
    always @(posedge s_axis_aclk) begin
        if (s_axis_ready)
            ram[s_axis_waddr] <= s_axis_data;
    end

    // Read data from the buffer on the AXI clock domain
    always @(posedge m_axis_aclk) begin
        m_axis_raddr <= m_axis_raddr_next;
    end

    // Output the data from the buffer
    assign m_axis_data = ram[m_axis_raddr_next];

end endgenerate

endmodule

module velocityControlHdl_Dynamic_Saturation_block1
          (
           up,
           u,
           lo,
           y,
           sat_mode
          );


  input   signed [17:0] up;  // sfix18_En15
  input   signed [35:0] u;  // sfix36_En22
  input   signed [17:0] lo;  // sfix18_En15
  output  signed [35:0] y;  // sfix36_En22
  output  sat_mode;


  wire signed [35:0] LowerRelop1_1_cast;  // sfix36_En22
  wire LowerRelop1_relop1;
  wire signed [35:0] UpperRelop_1_cast;  // sfix36_En22
  wire UpperRelop_relop1;
  wire signed [35:0] lo_dtc;  // sfix36_En22
  wire signed [35:0] Switch_out1;  // sfix36_En22
  wire signed [35:0] up_dtc;  // sfix36_En22
  wire signed [35:0] Switch2_out1;  // sfix36_En22
  wire LowerRelop1_out1;


  // <S33>/LowerRelop1
  assign LowerRelop1_1_cast = {{11{up[17]}}, {up, 7'b0000000}};
  assign LowerRelop1_relop1 = (u > LowerRelop1_1_cast ? 1'b1 :
              1'b0);



  // <S33>/UpperRelop
  assign UpperRelop_1_cast = {{11{lo[17]}}, {lo, 7'b0000000}};
  assign UpperRelop_relop1 = (u < UpperRelop_1_cast ? 1'b1 :
              1'b0);



  assign lo_dtc = {{11{lo[17]}}, {lo, 7'b0000000}};



  // <S33>/Switch
  assign Switch_out1 = (UpperRelop_relop1 == 1'b0 ? u :
              lo_dtc);



  assign up_dtc = {{11{up[17]}}, {up, 7'b0000000}};



  // <S33>/Switch2
  assign Switch2_out1 = (LowerRelop1_relop1 == 1'b0 ? Switch_out1 :
              up_dtc);



  assign y = Switch2_out1;

  // <S33>/Logical Operator
  assign LowerRelop1_out1 = LowerRelop1_relop1 | UpperRelop_relop1;



  assign sat_mode = LowerRelop1_out1;

endmodule

