  parameter SHIFT_IR = 3'b001;
  parameter SHIFT_DR = 3'b010;
  parameter UPDATE_DR = 3'b011;
  parameter UPDATE_IR = 3'b100;

  always @(posedge clk) begin
    if (reset_n == 1'b0) begin
      state <= IDLE;
      ir <= 2'b0;
      dr <= 8'b0;
      dr_out <= 8'b0;
    end else begin
      case (state)
        IDLE: begin
          tck <= 1'b0;
          tdi <= 1'b1;
          if (debugack == 1'b1) begin
            state <= SHIFT_IR;
          end
        end
        SHIFT_IR: begin
          tck <= 1'b1;
          tdi <= ir[0];
          ir <= {ir[0], ir[1]};
          if (ir == 2'b11) begin
            state <= SHIFT_DR;
          end
        end
        SHIFT_DR: begin
          tck <= 1'b1;
          tdi <= dr[0];
          dr <= {dr[0], dr[1], dr[2], dr[3], dr[4], dr[5], dr[6], dr[7]};
          if (dr == 8'b11111111) begin
            state <= UPDATE_DR;
          end
        end
        UPDATE_DR: begin
          tck <= 1'b1;
          tdi <= 1'b0;
          if (debugack == 1'b1) begin
            dr_out <= dr_in;
            state <= IDLE;
          end
        end
      endcase
    end
  end

  always @(posedge clk) begin
    if (reset_n == 1'b0) begin
      dr_in <= 8'b0;
    end else begin
      dr_in <= {break_readreg[0], dbrk_hit0_latch, dbrk_hit1_latch, dbrk_hit2_latch, dbrk_hit3_latch, monitor_ready, monitor_error, tracemem_on};
    end
  end

  always @(posedge clk) begin
    if (reset_n == 1'b0) begin
      tdo <= 1'b0;
    end else begin
      case (state)
        IDLE: begin
          tdo <= 1'b0;
        end
        SHIFT_IR: begin
          tdo <= 1'b0;
        end
        SHIFT_DR: begin
          tdo <= dr_out[7];
        end
        UPDATE_DR: begin
          tdo <= 1'b0;
        end
      endcase
    end
  end

endmodule

module top_module ( 
