module top_module(
    input [15:0] a,
    input [15:0] b,
    input sub,
    input control,
    output [15:0] out
);

    wire [15:0] add_out;
    wire [15:0] sub_out;
    wire carry_out;

    ripple_carry_adder adder(
        .a(a),
        .b(b),
        .carry_in(sub),
        .sum(add_out),
        .carry_out(carry_out)
    );

    xor_gate xor(
        .a(b),
        .b({16{sub}}),
        .out(sub_out)
    );

