module counter_mux (
    input clk,
    input reset,
    input up_down, // control input for counter to count up or down
    input select, // select input for multiplexer to choose between counter output and 0x0F
    input valid_in, // valid input for input data
    input ready_out, // ready input for output
    output reg valid_out, // valid output for output
    output [7:0] q // 8-bit output from the chosen module or the final output
);

reg [3:0] counter;
reg [3:0] next_counter;
wire [3:0] max_value = 4'b1111;
wire [3:0] min_value = 4'b0000;
wire [3:0] zero_value = 4'b0000;
wire [3:0] mux_out;

assign mux_out = select ? zero_value : counter;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        counter <= 4'b0000;
        valid_out <= 1'b0;
    end else begin
        if (valid_in && ready_out) begin
            valid_out <= 1'b1;
            next_counter <= up_down ? counter + 1 : counter - 1;
            if (next_counter == max_value || next_counter == min_value) begin
                counter <= 4'b0000;
            end else begin
                counter <= next_counter;
            end
        end else begin
            valid_out <= 1'b0;
        end
    end
end

add_three adder(.a(mux_out), .b(8'h03), .sum(q));

endmodule

