module axis_async_fifo_64 (
    input input_clk,
    input input_rst,
    input [63:0] input_axis_tdata,
    input [7:0] input_axis_tkeep,
    input input_axis_tvalid,
    input input_axis_tlast,
    input input_axis_tuser,
    output input_axis_tready,
    input output_clk,
    input output_rst,
    output [63:0] output_axis_tdata,
    output [7:0] output_axis_tkeep,
    output output_axis_tvalid,
    output output_axis_tlast,
    output output_axis_tuser,
    input output_axis_tready
);

parameter ADDR_WIDTH = 2;
parameter DATA_WIDTH = 64;

reg [DATA_WIDTH-1:0] mem [(1<<ADDR_WIDTH)-1:0];
reg [ADDR_WIDTH-1:0] wr_ptr = 0;
reg [ADDR_WIDTH-1:0] rd_ptr = 0;
reg [ADDR_WIDTH-1:0] count = 0;
reg [ADDR_WIDTH-1:0] next_wr_ptr;
reg [ADDR_WIDTH-1:0] next_rd_ptr;
reg [ADDR_WIDTH-1:0] next_count;
reg [ADDR_WIDTH-1:0] wr_ptr_ff;
reg [ADDR_WIDTH-1:0] rd_ptr_ff;
reg [ADDR_WIDTH-1:0] count_ff;
reg [ADDR_WIDTH-1:0] wr_ptr_ff_next;
reg [ADDR_WIDTH-1:0] rd_ptr_ff_next;
reg [ADDR_WIDTH-1:0] count_ff_next;
reg [DATA_WIDTH-1:0] out_data_ff;
reg [7:0] out_keep_ff;
reg out_valid_ff;
reg out_last_ff;
reg out_user_ff;
reg in_ready_ff;
reg out_ready_ff;
reg [7:0] byte_count = 0;
reg [7:0] byte_count_ff = 0;
reg [7:0] byte_count_ff_next = 0;

always @(posedge input_clk or negedge input_rst) begin
    if (~input_rst) begin
        wr_ptr <= 0;
        rd_ptr <= 0;
        count <= 0;
        byte_count <= 0;
        wr_ptr_ff <= 0;
        rd_ptr_ff <= 0;
        count_ff <= 0;
        byte_count_ff <= 0;
        in_ready_ff <= 1;
        out_ready_ff <= 1;
    end else begin
        wr_ptr <= next_wr_ptr;
        rd_ptr <= next_rd_ptr;
        count <= next_count;
        byte_count <= byte_count_ff_next;
        wr_ptr_ff <= wr_ptr;
        rd_ptr_ff <= rd_ptr;
        count_ff <= count;
        byte_count_ff <= byte_count_ff_next;
        in_ready_ff <= input_axis_tready;
        out_ready_ff <= output_axis_tready;
    end
end

always @(posedge output_clk or negedge output_rst) begin
    if (~output_rst) begin
        out_data_ff <= 0;
        out_keep_ff <= 0;
        out_valid_ff <= 0;
        out_last_ff <= 0;
        out_user_ff <= 0;
    end else begin
        out_data_ff <= mem[rd_ptr_ff];
        out_keep_ff <= {byte_count_ff[7:0], 8'h0};
        out_valid_ff <= count_ff > 0 ? 1 : 0;
        out_last_ff <= count_ff == 1 ? 1 : 0;
        out_user_ff <= 0;
    end
end

always @(*) begin
    next_wr_ptr = wr_ptr;
    next_rd_ptr = rd_ptr;
    next_count = count;
    byte_count_ff_next = byte_count_ff;
    wr_ptr_ff_next = wr_ptr_ff;
    rd_ptr_ff_next = rd_ptr_ff;
    count_ff_next = count_ff;

    if (input_axis_tvalid && in_ready_ff) begin
        mem[wr_ptr] <= input_axis_tdata;
        byte_count_ff_next = byte_count_ff + $countones(input_axis_tkeep);
        if (byte_count_ff_next >= 8) begin
            next_wr_ptr = wr_ptr + 1;
            byte_count_ff_next = byte_count_ff_next - 8;
        end
        wr_ptr_ff_next = next_wr_ptr;
        count_ff_next = count_ff + 1;
        next_count = count_ff_next;
    end

    if (out_ready_ff && count_ff > 0) begin
        out_valid_ff = 1;
        if (count_ff == 1) begin
            out_last_ff = 1;
        end
        rd_ptr_ff_next = rd_ptr_ff + 1;
        count_ff_next = count_ff_next - 1;
        next_count = count_ff_next;
    end
end

assign output_axis_tdata = out_data_ff;
assign output_axis_tkeep = out_keep_ff;
assign output_axis_tvalid = out_valid_ff;
assign output_axis_tlast = out_last_ff;
assign output_axis_tuser = out_user_ff;
assign input_axis_tready = count_ff < (1 << ADDR_WIDTH) && in_ready_ff;

endmodule

