module c_prio_sel
  (port_prios, max_ports);

   // number of input ports
   parameter num_ports = 32;

   // width of priority fields
   parameter prio_width = 4;

   // priority values
   input [0:num_ports*prio_width-1] port_prios;

   // vector representing maximum priority ports
   output [0:num_ports-1] max_ports;
   wire [0:num_ports-1] max_ports;

   // for each priority bit, list all ports that have this bit set
   wire [0:prio_width*num_ports-1] prio_ports;
   c_interleaver
     #(.width(num_ports*prio_width),
       .num_blocks(num_ports))
   prio_ports_intl
     (.data_in(port_prios),
      .data_out(prio_ports));

   // OR operation on priority bit vectors
   wire [0:prio_width-1] 	   prio_some_set;
   c_or_nto1
     #(.num_ports(num_ports),
       .width(prio_width))
   prio_some_set_or
     (.data_in(prio_ports),
      .data_out(prio_some_set));

   // NAND operation on priority bit vectors
   wire [0:prio_width-1] 	   prio_some_unset;
   c_nand_nto1
     #(.num_ports(num_ports),
       .width(prio_width))
   prio_some_unset_nand
     (.data_in(prio_ports),
      .data_out(prio_some_unset));

   // find bit positions that are not identical for all ports
   wire [0:prio_width-1] 	   prio_diffs;
   assign prio_diffs = prio_some_set & prio_some_unset;

   // first-priority arbitration on bit positions
   wire [0:prio_width-1] 	   first_prio_diff;
   c_fp_arbiter
     #(.num_ports(prio_width))
   first_prio_diff_arb
     (.req(prio_diffs),
      .gnt(first_prio_diff));

   // select ports with maximum priority
   c_select_1ofn
     #(.num_ports(prio_width+1),
       .width(num_ports))
   max_ports_sel
     (.select({first_prio_diff, ~|prio_diffs}),
      .data_in({prio_ports, {num_ports{1'b1}}}),
      .data_out(max_ports));

   // assign 1 to ports with maximum priority
   assign max_ports = max_ports_sel[0:num_ports];

endmodule

// Interleaves input data into blocks of a specified size
module c_interleaver
  #(parameter width = 32,
    parameter num_blocks = 8)
  (data_in, data_out);

   input [0:width*num_blocks-1] data_in;
   output [0:width*num_blocks-1] data_out;

   genvar i, j;
   generate
     for (i = 0; i < num_blocks; i = i + 1) begin
       for (j = 0; j < width; j = j + 1) begin
         assign data_out[i*width+j] = data_in[j*num_blocks+i];
       end
     end
   endgenerate

endmodule

// Performs an OR operation on a set of input vectors and outputs a single vector
module c_or_nto1
  #(parameter num_ports = 8,
    parameter width = 32)
  (data_in, data_out);

   input [0:width*num_ports-1] data_in;
   output [0:width-1] data_out;

   genvar i;
   wire [0:width-1] or_result;

   generate
     for (i = 0; i < num_ports; i = i + 1) begin
       assign or_result = or_result | data_in[i*width +: width];
     end
   endgenerate

   assign data_out = or_result;

endmodule

// Performs a NAND operation on a set of input vectors and outputs a single vector
module c_nand_nto1
  #(parameter num_ports = 8,
    parameter width = 32)
  (data_in, data_out);

   input [0:width*num_ports-1] data_in;
   output [0:width-1] data_out;

   genvar i;
   wire [0:width-1] nand_result;

   generate
     for (i = 0; i < num_ports; i = i + 1) begin
       assign nand_result = nand_result & data_in[i*width +: width];
     end
   endgenerate

   assign data_out = ~nand_result;

endmodule

// Performs first-priority arbitration on a set of input requests and outputs a single grant
module c_fp_arbiter
  #(parameter num_ports = 8)
  (req, gnt);

   input [0:num_ports-1] req;
   output [0:num_ports-1] gnt;

   wire [0:num_ports-1] req_latch;
   assign req_latch = req;

   genvar i;
   wire [0:num_ports-1] gnt_result;

   generate
     for (i = 0; i < num_ports; i = i + 1) begin
       assign gnt_result[i] = req_latch[i] & ~|req_latch[0:i];
     end
   endgenerate

   assign gnt = gnt_result;

endmodule

// Selects one of N input vectors based on a select signal
module c_select_1ofn
  #(parameter num_ports = 2,
    parameter width = 32)
  (select, data_in, data_out);

   input [0:num_ports-1] select;
   input [0:(num_ports-1)*width-1] data_in;
   output [0:width-1] data_out;

   genvar i;
   wire [0:width-1] select_result;

   generate
     for (i = 0; i < num_ports; i = i + 1) begin
       assign select_result = select[i] ? data_in[i*width +: width] : select_result;
     end
   endgenerate

   assign data_out = select_result;

endmodule

module ALU(clk,rst,fn,A,B,Y,Zero,Cout);
    input clk, rst;
    input [4:0] fn;
    input [7:0] A,B;
    output reg [7:0] Y;
    output reg Zero, Cout;
    always @(posedge clk) begin
        if(rst) begin
            Y <= 8'b0;
            Zero <= 1'b0;
            Cout <= 1'b0;
        end
        else begin
            case(fn)
                5'b00000: Y <= A + B; //addition
                5'b00001: Y <= A - B; //subtraction
                5'b00010: Y <= A & B; //bitwise AND
                5'b00011: Y <= A | B; //bitwise OR
                5'b00100: Y <= A ^ B; //bitwise XOR
                5'b00101: Y <= {A[6:0], B[7]}; //shift left
                5'b00110: Y <= {A[0], A[7:1]}; //shift right
                5'b00111: Y <= {A[0], B[7:1]}; //shift right
                5'b11000: Y <= A + B + Cout; //addition with carry
                5'b11001: Y <= A - B - ~Cout; //subtraction with borrow
                5'b11010: Y <= {A[(B[1:0]+5):0], A[(7-B[1:0]+5):B[1:0]+6]}; //rotate left
                5'b11011: Y <= {A[(7-B[1:0]+5):0], A[(7+5-B[1:0]+6):7]}; //rotate right
                default: Y <= 8'b0;
            endcase
            Zero <= (Y == 8'b0);
            Cout <= ((fn == 5'b11000) && ((A[7] & B[7]) | (A[7] & ~Y[7]) | (B[7] & ~Y[7])));
        end
    end
endmodule

module johnson_counter (
  input clk,
  output reg [n-1:0] out
);

parameter n = 4; // number of flip-flops

reg [n-1:0] state;

always @(posedge clk) begin
  state <= {state[n-2:0], ~state[n-1]};
  out <= state;
end

endmodule

module latches (
  input clk, // clock signal
  input rst, // reset signal
  input data, // data signal
  input en, // enable signal
  input j, // J input for JK latch
  input k, // K input for JK latch
  input t, // T input for T latch
  input s, // S input for SR latch
  input r, // R input for SR latch
  output reg d_out, // output of D latch
  output reg jk_out, // output of JK latch
  output reg t_out, // output of T latch
  output reg sr_out // output of SR latch
);

parameter n = 4; // number of latches

reg d, jk, t, sr; // flip-flops for storing the latch values

always @(posedge clk) begin
  if (rst == 1) begin
    d <= 0;
    jk <= 0;
    t <= 0;
    sr <= 0;
  end else if (en == 1) begin
    // D latch
    d <= data;

    // JK latch
    if (j == 1 && k == 1) begin
      jk <= ~jk;
    end else if (j == 1) begin
      jk <= 1;
    end else if (k == 1) begin
      jk <= 0;
    end

    // T latch
    if (t == 1) begin
      t <= ~t;
    end else if (t == 0 && data == 1) begin
      t <= 1;
    end

    // SR latch
    if (s == 1 && r == 0) begin
      sr <= 1;
    end else if (s == 0 && r == 1) begin
      sr <= 0;
    end
  end
end

// output the latch values
assign d_out = d;
assign jk_out = jk;
assign t_out = t;
assign sr_out = sr;

endmodule

