module uart(
   // Outputs
   uart_busy,   // High means UART is transmitting
   uart_tx,     // UART transmit wire
   // Inputs
   uart_wr_i,   // Raise to transmit byte
   uart_dat_i,  // 8-bit data
   sys_clk_i,   // System clock, 68 MHz
   sys_rst_i    // System reset
);

  input uart_wr_i;
  input [7:0] uart_dat_i;
  input sys_clk_i;
  input sys_rst_i;

  output uart_busy;
  output uart_tx;

  reg [3:0] bitcount;
  reg [8:0] shifter;
  reg uart_tx;

  wire uart_busy = |bitcount[3:1];
  wire sending = |bitcount;

  // sys_clk_i is 68MHz.  We want a 115200Hz clock

  reg [28:0] d;
  wire [28:0] dInc = d[28] ? (115200) : (115200 - 100000000);
  wire [28:0] dNxt = d + dInc;
  wire ser_clk = ~d[28];
  always @(posedge sys_clk_i)
    if (sys_rst_i) begin
       d = 0;
    end else begin
      d = dNxt;
    end

  always @(posedge sys_clk_i)
  begin
    if (sys_rst_i) begin
      uart_tx <= 1;
      bitcount <= 0;
      shifter <= 0;
    end else begin
      // just got a new byte
      if (uart_wr_i & ~uart_busy) begin
        shifter <= { uart_dat_i[7:0], 1'h0 };
        bitcount <= (1 + 8 + 2);
      end

      if (sending & ser_clk) begin
        { shifter, uart_tx } <= { 1'h1, shifter };
        bitcount <= bitcount - 1;
      end
    end
  end

endmodule

module AN_encoder_decoder (
  input [n-1:0] in,
  input [n-1:0] probs,
  output [31:0] encoded_fraction
);

parameter n = 8; // number of input symbols and probabilities

// Generate cumulative probability table
reg [31:0] cum_prob_table [n-1:0];
reg [31:0] temp_prob = 0;
integer i;
always @* begin
  for (i = 0; i < n; i = i + 1) begin
    cum_prob_table[i] = temp_prob + (probs[i] * ((1 << 30) - n + 2));
    temp_prob = cum_prob_table[i];
  end
end

// Encode input data stream
reg [31:0] low = 0;
reg [31:0] high = (1 << 30) - 1;
reg [31:0] range = high - low + 1;
integer j;
always @* begin
  for (j = 0; j < n; j = j + 1) begin
    high = low + (range * cum_prob_table[in[j]] / ((1 << 30) - n + 2)) - 1;
    low = low + (range * cum_prob_table[in[j]-1] / ((1 << 30) - n + 2));
    range = high - low + 1;
  end
end

// Output encoded fraction
assign encoded_fraction = low;

// Decode encoded fraction
reg [31:0] decoded_value = 0;
reg [31:0] decoded_low = 0;
reg [31:0] decoded_high = (1 << 30) - 1;
reg [31:0] decoded_range = decoded_high - decoded_low + 1;
integer k;
always @* begin
  for (k = 0; k < 32; k = k + 1) begin
    decoded_value = decoded_value << 1;
    if (((decoded_low + decoded_range / ((1 << 30) - n + 2)) > encoded_fraction) && ((decoded_high - decoded_range / ((1 << 30) - n + 2)) < encoded_fraction)) begin
      decoded_value = decoded_value | 1;
      decoded_low = decoded_low + decoded_range / ((1 << 30) - n + 2);
      decoded_high = decoded_high - decoded_range / ((1 << 30) - n + 2);
      decoded_range = decoded_high - decoded_low + 1;
    end else if ((decoded_low + decoded_range / ((1 << 30) - n + 2)) <= encoded_fraction) begin
      decoded_low = decoded_low + decoded_range / ((1 << 30) - n + 2);
      decoded_range = decoded_high - decoded_low + 1;
    end else if ((decoded_high - decoded_range / ((1 << 30) - n + 2)) >= encoded_fraction) begin
      decoded_high = decoded_high - decoded_range / ((1 << 30) - n + 2);
      decoded_range = decoded_high - decoded_low + 1;
    end
  end
end

// Output decoded data stream
reg [n-1:0] decoded_data;
integer l;
always @* begin
  for (l = 0; l < n; l = l + 1) begin
    if (decoded_value >= cum_prob_table[l]) begin
      decoded_data[l] = l;
      decoded_value = decoded_value - cum_prob_table[l];
    end
  end
end

endmodule

module hdmi_embedded_sync_insertion (
  input hdmi_clk,
  input hdmi_hs_de,
  input hdmi_vs_de,
  input [(DATA_WIDTH-1):0] hdmi_data_de,
  output [(DATA_WIDTH-1):0] hdmi_data
);

  // parameters
  parameter DATA_WIDTH = 32;
  localparam BYTE_WIDTH = DATA_WIDTH/8;

  // internal registers
  reg hdmi_hs_de_d = 'd0;
  reg [(DATA_WIDTH-1):0] hdmi_data_d = 'd0;
  reg hdmi_hs_de_2d = 'd0;
  reg [(DATA_WIDTH-1):0] hdmi_data_2d = 'd0;
  reg hdmi_hs_de_3d = 'd0;
  reg [(DATA_WIDTH-1):0] hdmi_data_3d = 'd0;
  reg hdmi_hs_de_4d = 'd0;
  reg [(DATA_WIDTH-1):0] hdmi_data_4d = 'd0;
  reg hdmi_hs_de_5d = 'd0;
  reg [(DATA_WIDTH-1):0] hdmi_data_5d = 'd0;

  // internal wires
  wire [(DATA_WIDTH-1):0] hdmi_sav_s;
  wire [(DATA_WIDTH-1):0] hdmi_eav_s;
  wire [(DATA_WIDTH-1):0] hdmi_sof_s;
  wire [(DATA_WIDTH-1):0] hdmi_eof_s;

  // hdmi embedded sync insertion
  assign hdmi_sav_s = (hdmi_vs_de == 1) ? {BYTE_WIDTH{8'h80}} : {BYTE_WIDTH{8'hab}};
  assign hdmi_eav_s = (hdmi_vs_de == 1) ? {BYTE_WIDTH{8'h9d}} : {BYTE_WIDTH{8'hb6}};
  assign hdmi_sof_s = (hdmi_vs_de == 1 && hdmi_hs_de == 0) ? {BYTE_WIDTH{8'h00}} : {BYTE_WIDTH{8'hab}};
  assign hdmi_eof_s = (hdmi_vs_de == 1 && hdmi_hs_de == 1) ? {BYTE_WIDTH{8'h00}} : {BYTE_WIDTH{8'hb6}};

  always @(posedge hdmi_clk) begin
    hdmi_hs_de_d <= hdmi_hs_de;
    case ({hdmi_hs_de_4d, hdmi_hs_de_3d, hdmi_hs_de_2d,
      hdmi_hs_de_d, hdmi_hs_de})
      5'b11000: hdmi_data_d <= hdmi_eav_s;
      5'b11100: hdmi_data_d <= hdmi_eof_s;
      5'b11110: hdmi_data_d <= {BYTE_WIDTH{8'hff}};
      5'b10000: hdmi_data_d <= hdmi_sof_s;
      default: hdmi_data_d <= hdmi_data_de;
    endcase
    hdmi_hs_de_2d <= hdmi_hs_de_d;
    hdmi_data_2d <= hdmi_data_d;
    hdmi_hs_de_3d <= hdmi_hs_de_2d;
    hdmi_data_3d <= hdmi_data_2d;
    hdmi_hs_de_4d <= hdmi_hs_de_3d;
    hdmi_data_4d <= hdmi_data_3d;
    hdmi_hs_de_5d <= hdmi_hs_de_4d;
    hdmi_data_5d <= hdmi_data_4d;
    case ({hdmi_hs_de_5d, hdmi_hs_de_4d, hdmi_hs_de_3d,
      hdmi_hs_de_2d, hdmi_hs_de_d})
      5'b00111: hdmi_data <= hdmi_sav_s;
      5'b00011: hdmi_data <= hdmi_sav_s;
      5'b00001: hdmi_data <= hdmi_sof_s;
      5'b01111: hdmi_data <= {BYTE_WIDTH{8'h00}};
      default: hdmi_data <= hdmi_data_5d;
    endcase
  end

endmodule

