module fifo
   #(
  	parameter adr_width = 4,
	parameter dat_width = 8
   )
   (
    input  clk, reset,
    input  rd, wr,
    input  [dat_width-1:0] data_in,
    output [dat_width-1:0] data_out,
    output empty, 
    output full
   );


   parameter depth = (1 << adr_width);

   //declaración de registros 

   reg [dat_width-1:0] array_reg [depth-1:0];// register array FIFO

   reg [adr_width-1:0] w_ptr_reg, w_ptr_next;
   reg [adr_width-1:0] r_ptr_reg, r_ptr_next;
   reg full_reg, empty_reg, full_next, empty_next;
   wire wr_en;
	reg	[1:0]	orden;


   assign data_out = array_reg[r_ptr_reg];
   assign wr_en = wr & ~full_reg;

   assign full = full_reg;
   assign empty = empty_reg;

   always @(posedge clk) begin
      if (wr_en)
         array_reg[w_ptr_reg] <= data_in;
   end

   // fifo control logic
   // register for read and write pointers
   always @(posedge clk, posedge reset) begin
      if (reset)
         begin
            w_ptr_reg <= 0;
            r_ptr_reg <= 0;
            full_reg <= 1'b0;
            empty_reg <= 1'b1;
         end
      else
         begin
            w_ptr_reg <= w_ptr_next;
            r_ptr_reg <= r_ptr_next;
            full_reg <= full_next;
            empty_reg <= empty_next;
         end
   end

	always @(posedge clk)
	begin
		if(wr&&!rd)
		begin
			orden = 2'b01;
		end
		if(!wr&&rd)
		begin
			orden = 2'b10;
		end
		if(wr&&rd)
		begin
			orden = 2'b11;
		end
	end


   //always @(posedge reset or posedge wr or posedge rd)
	always @(posedge clk)
   begin
      if (reset) begin
	w_ptr_next =  0;
        r_ptr_next =  0;       
      end else begin
	      full_next = full_reg;
	      empty_next = empty_reg;
	      case (orden)
		 2'b01: // read
		    if (~empty_reg) // not empty
		       begin
		          r_ptr_next = r_ptr_reg + 1;
		          full_next = 1'b0;
		          if (r_ptr_next==w_ptr_reg)
		             empty_next = 1'b1;
		       end
		 2'b10: // write
		    if (~full_reg) // not full
		       begin
		          w_ptr_next = w_ptr_reg + 1;
		          empty_next = 1'b0;
		          if (w_ptr_next==r_ptr_reg)
		             full_next = 1'b1;
		       end
		 2'b11: // write and read
		    begin
		       w_ptr_next =  w_ptr_reg + 1;
		       r_ptr_next = r_ptr_reg + 1;
		    end
	      endcase
	end
   end



endmodule

module ConvolutionalEncoderViterbiDecoder (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter k = 3; // constraint length of the convolutional encoder
parameter n = 100; // number of input bits
parameter m = 200; // number of output bits

// Convolutional Encoder
reg [k-1:0] shift_reg;
always @(posedge clk) begin
  shift_reg[k-1:1] <= shift_reg[k-2:0];
  shift_reg[0] <= in;
end

wire [m-1:0] encoded_out;
assign encoded_out = {in, shift_reg[2], shift_reg[1]};

// Viterbi Decoder
reg [k-1:0] state_reg;
reg [k-1:0] prev_state_reg;
reg [m-1:0] path_metric_reg;
reg [m-1:0] prev_path_metric_reg;
reg [1:0] traceback_reg;
reg [1:0] prev_traceback_reg;

initial begin
  state_reg = 0;
  prev_state_reg = 0;
  path_metric_reg = 0;
  prev_path_metric_reg = 0;
  traceback_reg = 0;
  prev_traceback_reg = 0;
end

always @(posedge clk) begin
  // Update state and path metric registers
  prev_state_reg <= state_reg;
  prev_path_metric_reg <= path_metric_reg;
  state_reg <= {state_reg[k-2:0], encoded_out};
  path_metric_reg <= prev_path_metric_reg + $countones(state_reg ^ encoded_out);

  // Update traceback register
  prev_traceback_reg <= traceback_reg;
  if (prev_path_metric_reg + $countones(prev_state_reg ^ encoded_out) <= path_metric_reg + $countones(state_reg ^ encoded_out))
    traceback_reg <= prev_traceback_reg;
  else
    traceback_reg <= {prev_traceback_reg[0], prev_traceback_reg[1] ^ 1};

  // Output decoded bit
  if (traceback_reg == 0)
    out <= prev_state_reg[k-1];
end

endmodule

