module barrel_shift_up_down_counter (
    input clk,
    input reset,
    input select,
    input [3:0] data_in,
    input [1:0] shift,
    input shift_right,
    input shift_left,
    input rotate_right,
    input rotate_left,
    output reg [3:0] count
);

reg [3:0] shifted_data;

always @ (posedge clk) begin
    if (reset) begin
        count <= 0;
        shifted_data <= 0;
    end else begin
        if (select) begin
            count <= 0;
        end else begin
            count <= data_in;
        end

        case (shift)
            2'b00: shifted_data <= shift_right ? {shifted_data[2:0], shifted_data[3]} : {shifted_data[0], shifted_data[3:1]};
            2'b01: shifted_data <= shift_left ? {shifted_data[1:3], shifted_data[0]} : {shifted_data[3], shifted_data[2:0]};
            2'b10: shifted_data <= rotate_right ? {shifted_data[3], shifted_data[2:0]} : {shifted_data[1:0], shifted_data[3:2]};
            2'b11: shifted_data <= rotate_left ? {shifted_data[1:3], shifted_data[0]} : {shifted_data[2:3], shifted_data[0:1]};
        endcase

        count <= shifted_data;
    end
end

endmodule

module traffic_light_controller (
  input clk,
  output reg red,
  output reg yellow,
  output reg green
);

  // Define the states of the traffic light controller
  parameter RED = 2'b00;
  parameter GREEN = 2'b01;
  parameter YELLOW = 2'b10;

  // Define the current state and next state variables
  reg [1:0] current_state;
  reg [1:0] next_state;

  // Define the state transition logic
  always @ (posedge clk) begin
    current_state <= next_state;
    case (current_state)
      RED: next_state <= GREEN;
      GREEN: next_state <= YELLOW;
      YELLOW: next_state <= RED;
      default: next_state <= RED;
    endcase
  end

  // Define the output logic based on the current state
  always @ (current_state) begin
    case (current_state)
      RED: begin
        red <= 1;
        yellow <= 0;
        green <= 0;
        #30; // Wait for 30 seconds
      end
      GREEN: begin
        red <= 0;
        yellow <= 0;
        green <= 1;
        #30; // Wait for 30 seconds
      end
      YELLOW: begin
        red <= 0;
        yellow <= 1;
        green <= 0;
        #5; // Wait for 5 seconds
      end
      default: begin
        red <= 1;
        yellow <= 0;
        green <= 0;
        #30; // Wait for 30 seconds
      end
    endcase
  end

endmodule

