module int_to_fp_altbarrel_shift_mvf(
  input aclr,
  input clk_en,
  input clock,
  input [31:0] data,
  input [4:0] distance,
  output [31:0] result
);

  reg [31:0] pipe_wl1c;
  reg [31:0] pipe_wl2c;
  reg sel_pipel3d1c;
  reg sel_pipel4d1c;
  wire direction_w;
  wire [15:0] pad_w;
  wire [191:0] sbit_w;
  wire [4:0] sel_w;

  // Initialize registers on reset
  initial begin
    pipe_wl1c = 0;
    pipe_wl2c = 0;
    sel_pipel3d1c = 0;
    sel_pipel4d1c = 0;
  end

  // Assign sel_w based on distance and sel_pipel3d1c
  always @ (posedge clock or posedge aclr) begin
    if (aclr == 1'b1) sel_pipel3d1c <= 1'b0;
    else if (clk_en == 1'b1) sel_pipel3d1c <= distance[3];
  end

  always @ (posedge clock or posedge aclr) begin
    if (aclr == 1'b1) sel_pipel4d1c <= 1'b0;
    else if (clk_en == 1'b1) sel_pipel4d1c <= distance[4];
  end

  // Calculate sbit_w based on pipe_wl1c, pipe_wl2c, sel_w, direction_w, and pad_w
  always @ (posedge clock or posedge aclr) begin
    if (aclr == 1'b1) pipe_wl1c <= 32'b0;
    else if (clk_en == 1'b1) begin
      pipe_wl1c <= ((({32{(sel_w[2] & (~ direction_w))}} & {sbit_w[91:64], pad_w[3:0]}) | ({32{(sel_w[2] & direction_w)}} & {pad_w[3:0], sbit_w[95:68]})) | ({32{(~ sel_w[2])}} & sbit_w[95:64]));
      pipe_wl2c <= ((({32{(sel_w[4] & (~ direction_w))}} & {sbit_w[143:128], pad_w[15:0]}) | ({32{(sel_w[4] & direction_w)}} & {pad_w[15:0], sbit_w[159:144]})) | ({32{(~ sel_w[4])}} & sbit_w[159:128]));
      sbit_w <= {pipe_wl2c, ((({32{(sel_w[3] & (~ direction_w))}} & {sbit_w[119:96], pad_w[7:0]}) | ({32{(sel_w[3] & direction_w)}} & {pad_w[7:0], sbit_w[127:104]})) | ({32{(~ sel_w[3])}} & sbit_w[127:96])), pipe_wl1c, ((({32{(sel_w[1] & (~ direction_w))}} & {sbit_w[61:32], pad_w[1:0]}) | ({32{(sel_w[1] & direction_w)}} & {pad_w[1:0], sbit_w[63:34]})) | ({32{(~ sel_w[1])}} & sbit_w[63:32])), ((({32{(sel_w[0] & (~ direction_w))}} & {sbit_w[30:0], pad_w[0]}) | ({32{(sel_w[0] & direction_w)}} & {pad_w[0], sbit_w[31:1]})) | ({32{(~ sel_w[0])}} & sbit_w[31:0])), data};
    end
  end

  // Assign result to the 32 most significant bits of sbit_w
  assign result = sbit_w[191:160];

endmodule

module vending_machine(
  input clk,
  input reset,
  input [1:0] product_id,
  input [5:0] money_inserted,
  output reg dispense,
  output reg [5:0] change,
  output reg [1:0] product_dispensed
);

  // Define the prices of each product
  parameter PRICE_00 = 50;
  parameter PRICE_01 = 75;
  parameter PRICE_10 = 100;
  parameter PRICE_11 = 125;

  // Define the state machine states
  parameter IDLE = 2'b00;
  parameter WAIT_FOR_MONEY = 2'b01;
  parameter DISPENSE_PRODUCT = 2'b10;

  // Define the state machine signals
  reg [1:0] state;
  reg [5:0] current_money;
  reg [5:0] product_price;

  // Initialize the state machine
  always @(posedge clk, posedge reset) begin
    if (reset) begin
      state <= IDLE;
      current_money <= 0;
      product_price <= 0;
      dispense <= 0;
      change <= 0;
      product_dispensed <= 0;
    end else begin
      case(state)
        IDLE: begin
          // Wait for the user to select a product
          product_dispensed <= 0;
          product_price <= 0;
          if (product_id != 0) begin
            // Set the price of the selected product
            case(product_id)
              1: product_price <= PRICE_01;
              2: product_price <= PRICE_10;
              3: product_price <= PRICE_11;
            endcase
            state <= WAIT_FOR_MONEY;
          end
        end
        WAIT_FOR_MONEY: begin
          // Wait for the user to insert enough money
          if (money_inserted >= product_price) begin
            current_money <= money_inserted;
            state <= DISPENSE_PRODUCT;
          end
        end
        DISPENSE_PRODUCT: begin
          // Dispense the product and return change
          dispense <= 1;
          product_dispensed <= product_id;
          change <= current_money - product_price;
          current_money <= 0;
          state <= IDLE;
        end
      endcase
    end
  end

endmodule

