module RPCv3EchoNode #(
	parameter NOC_WIDTH = 32,
	parameter NOC_ADDR = 16'h0000
) (
	input wire clk,

	output wire rpc_tx_en,
	output wire[NOC_WIDTH-1:0] rpc_tx_data,
	input wire rpc_tx_ready,

	input wire rpc_rx_en,
	input wire[NOC_WIDTH-1:0] rpc_rx_data,
	output wire rpc_rx_ready);

	// Registers to store the incoming data
	reg [NOC_WIDTH-1:0] rx_data_reg;
	reg rx_data_valid;

	// Assign outputs
	assign rpc_tx_en = rx_data_valid;
	assign rpc_tx_data = rx_data_reg;
	assign rpc_rx_ready = ~rx_data_valid;

	// Process incoming data
	always @(posedge clk) begin
		if (rpc_rx_en && rpc_tx_ready) begin
			rx_data_reg <= rpc_rx_data;
			rx_data_valid <= 1;
		end
	end

	// Loopback
	always @(posedge clk) begin
		if (rx_data_valid && rpc_tx_ready) begin
			rpc_tx_en <= 1;
			rpc_tx_data <= rx_data_reg;
			rx_data_valid <= 0;
		end
		else begin
			rpc_tx_en <= 0;
			rpc_tx_data <= 0;
		end
	end

endmodule

