    input clk,
    input reset,      // Synchronous active-high reset
    input signed_mag, // 4-bit input for the signed magnitude converter
    input select,     // Select input to choose between counter and converter
    output [7:0] q    // 8-bit output from the functional module
);

    // Instantiate the binary counter module
    binary_counter counter (
        .clk(clk),
        .reset(reset),
        .count(counter_out)
    );

    // Instantiate the signed magnitude to 2's complement converter module
    signed_mag_to_twos_comp converter (
        .signed_mag(signed_mag),
        .twos_comp(converter_out)
    );

    // Define the output signals from the two modules
    reg [3:0] counter_out;
    reg [3:0] converter_out;

    // Define the output signal from the functional module
    reg [7:0] functional_out;

    // Define the enabling control logic
    always @ (posedge clk) begin
        if (reset) begin
            functional_out <= 8'b0;
        end else begin
            if (select) begin
                functional_out <= {4'b0, counter_out};
            end else begin
                functional_out <= {4'b0, converter_out};
            end
        end
    end

    // Assign the output signal
    assign q = functional_out;

endmodule

// Define the binary counter module
module binary_counter (
    input clk,
    input reset,
    output reg [3:0] count
);
    always @ (posedge clk) begin
        if (reset) begin
            count <= 4'b0;
        end else begin
            count <= count + 1;
        end
    end
endmodule

// Define the signed magnitude to 2's complement converter module
module signed_mag_to_twos_comp (
    input [3:0] signed_mag,
    output reg [3:0] twos_comp
);
    always @ (signed_mag) begin
        if (signed_mag[3]) begin
            twos_comp <= ~(signed_mag - 1);
        end else begin
            twos_comp <= signed_mag;
        end
    end
endmodule

module alu(in1, in2, op, shop, shift, out, zero, positive, negative);

output [15:0] out;
input [15:0] in1, in2;
input [1:0] op, shop;
input [3:0] shift;
output zero, positive, negative;

wire [15:0] outAdd, outAnd, outXor, outLshf, outRshfl, outRshfa;

adder16 add1(in1, in2, outAdd);
and16 and1(in1, in2, outAnd);
xor16 xor1(in1, in2, outXor);
left_shift lshf1(in1, outLshf, shift);
right_shift_logical rshfl1(in1, outRshfl, shift);
right_shift_arithmetic rshfa1(in1, outRshfa, shift);

muxalu m1(outAdd, outAnd, outXor, outLshf, outRshfl, outRshfa, op, shop, out);

nor n1(zero, out[0], out[1], out[2], out[3], out[4], out[5], out[6], out[7], out[8], out[9], out[10], out[11], out[12], out[13], out[14], out[15]);
assign positive = (~out[15]) & (~zero);
assign negative = out[15];

endmodule

module NIOS_SYSTEMV3_NIOS_CPU_nios2_oci_pib (
    // inputs:
    clk,
    clkx2,
    jrst_n,
    tw,

    // outputs:
    tr_clk,
    tr_data
);

    output tr_clk;
    output [17:0] tr_data;
    input clk;
    input clkx2;
    input jrst_n;
    input [35:0] tw;

    wire phase;
    wire tr_clk;
    reg tr_clk_reg /* synthesis ALTERA_ATTRIBUTE = "SUPPRESS_DA_RULE_INTERNAL=R101" */;
    wire [17:0] tr_data;
    reg [17:0] tr_data_reg /* synthesis ALTERA_ATTRIBUTE = "SUPPRESS_DA_RULE_INTERNAL=R101" */;
    reg x1 /* synthesis ALTERA_ATTRIBUTE = "SUPPRESS_DA_RULE_INTERNAL=R101" */;
    reg x2 /* synthesis ALTERA_ATTRIBUTE = "SUPPRESS_DA_RULE_INTERNAL=R101" */;
    assign phase = x1 ^ x2;

    always @(posedge clk or negedge jrst_n) begin
        if (jrst_n == 0) begin
            x1 <= 0;
        end else begin
            x1 <= ~x1;
        end
    end

    always @(posedge clkx2 or negedge jrst_n) begin
        if (jrst_n == 0) begin
            x2 <= 0;
            tr_clk_reg <= 0;
            tr_data_reg <= 0;
        end else begin
            x2 <= x1;
            tr_clk_reg <= ~phase;
            tr_data_reg <= phase ? tw[17:0] : tw[35:18];
        end
    end

    assign tr_clk = tr_clk_reg;
    assign tr_data = tr_data_reg;

endmodule

