);

wire in0_not, in1_not, in2_not;

not U1(in0_not, in[0]);
not U2(in1_not, in[1]);
not U3(in2_not, in[2]);

and U4(out[0], in0_not, in1_not, in2_not);
and U5(out[1], in0_not, in1_not, in[2]);
and U6(out[2], in0_not, in[1], in2_not);
and U7(out[3], in0_not, in[1], in[2]);
and U8(out[4], in[0], in1_not, in2_not);
and U9(out[5], in[0], in1_not, in[2]);
and U10(out[6], in[0], in[1], in2_not);
and U11(out[7], in[0], in[1], in[2]);

or U12(out[0], out[1], out[2], out[3], out[4], out[5], out[6], out[7]);

