module top_module (
    input clk,         // Clock input
    input reset,       // Synchronous reset input
    input [31:0] a,    // 32-bit input A
    input [31:0] b,    // 32-bit input B
    input [1:0] select,// Select input to choose between A and B
    output reg [31:0] diff // 32-bit difference output
);

    wire [15:0] a_low = a[15:0];
    wire [15:0] b_low = b[15:0];
    wire [15:0] a_high = a[31:16];
    wire [15:0] b_high = b[31:16];

    subtractor_16bit sub_low (
        .a(a_low),
        .b(b_low),
        .diff(diff[15:0])
    );

    subtractor_16bit sub_high (
        .a(a_high),
        .b(b_high),
        .diff(diff[31:16])
    );

    always @(posedge clk) begin
        if (reset) begin
            diff <= 0;
        end else begin
            case (select)
                2'b00: diff <= a - b;
                2'b01: diff <= {a_high, a_low} - b;
                2'b10: diff <= a - {b_high, b_low};
                2'b11: diff <= a_high - b_high;
            endcase
        end
    end

endmodule

