module avalon_mm_master_interface (
    input clock,
    input reset,

    // Avalon-MM master interface
    input av_clock,
    input av_reset,
    output [15:0] av_address,
    output [5:0] av_burstcount,
    output [15:0] av_writedata,
    input [15:0] av_readdata,
    output av_write,
    output av_read,
    input av_readdatavalid,
    input av_waitrequest,

    // user algorithm interface
    input [15:0] addr,
    input command,
    input is_burst,
    input is_write_not_read,
    input [10:0] burst_length,
    input [15:0] writedata,
    input write,
    output [15:0] readdata,
    input read,
    output stall
);

    // internal signals
    wire [15:0] address_reg;
    wire [5:0] burstcount_reg;
    wire [15:0] writedata_reg;
    wire [15:0] readdata_reg;
    wire write_reg;
    wire read_reg;
    wire [10:0] burst_length_reg;
    wire is_burst_reg;
    wire is_write_not_read_reg;
    wire command_reg;
    wire av_write_reg;
    wire av_read_reg;
    wire av_waitrequest_reg;
    wire av_readdatavalid_reg;
    wire [15:0] av_readdata_reg;

    // register inputs
    assign address_reg = addr;
    assign burstcount_reg = is_burst ? burst_length : 6'h1;
    assign writedata_reg = writedata;
    assign is_burst_reg = is_burst;
    assign is_write_not_read_reg = is_write_not_read;
    assign command_reg = command;
    assign av_waitrequest_reg = av_waitrequest;
    assign av_readdatavalid_reg = av_readdatavalid;
    assign av_readdata_reg = av_readdata;

    // register outputs
    assign readdata = readdata_reg;
    assign stall = av_waitrequest_reg;

    // write control
    assign av_write = av_write_reg;
    assign write_reg = write & !stall;

    always @(posedge clock) begin
        if (reset) begin
            av_write_reg <= 1'b0;
            av_read_reg <= 1'b0;
            burst_length_reg <= 11'h0;
            is_burst_reg <= 1'b0;
            is_write_not_read_reg <= 1'b0;
            command_reg <= 1'b0;
            av_address <= 16'h0000;
            av_burstcount <= 6'h00;
            av_writedata <= 16'h0000;
            readdata_reg <= 16'h0000;
            av_readdata_reg <= 16'h0000;
        end else begin
            // handle write
            if (write_reg) begin
                av_write_reg <= 1'b1;
                av_address <= address_reg;
                av_burstcount <= burstcount_reg;
                av_writedata <= writedata_reg;
                is_write_not_read_reg <= 1'b1;
                command_reg <= 1'b1;
                readdata_reg <= readdata_reg;
            end else if (av_waitrequest_reg) begin
                av_write_reg <= 1'b0;
                av_address <= av_address;
                av_burstcount <= av_burstcount;
                av_writedata <= av_writedata;
                is_write_not_read_reg <= is_write_not_read_reg;
                command_reg <= command_reg;
                readdata_reg <= readdata_reg;
            end else begin
                av_write_reg <= 1'b0;
                av_address <= av_address;
                av_burstcount <= av_burstcount;
                av_writedata <= av_writedata;
                is_write_not_read_reg <= is_write_not_read_reg;
                command_reg <= 1'b0;
                readdata_reg <= readdata_reg;
            end

            // handle read
            if (read) begin
                av_read_reg <= 1'b1;
                av_address <= address_reg;
                av_burstcount <= burstcount_reg;
                av_writedata <= av_writedata;
                is_write_not_read_reg <= 1'b0;
                command_reg <= 1'b1;
            end else if (av_waitrequest_reg) begin
                av_read_reg <= 1'b0;
                av_address <= av_address;
                av_burstcount <= av_burstcount;
                av_writedata <= av_writedata;
                is_write_not_read_reg <= is_write_not_read_reg;
                command_reg <= command_reg;
            end else begin
                av_read_reg <= 1'b0;
                av_address <= av_address;
                av_burstcount <= av_burstcount;
                av_writedata <= av_writedata;
                is_write_not_read_reg <= is_write_not_read_reg;
                command_reg <= 1'b0;
            end

            // handle read data
            if (av_readdatavalid_reg) begin
                readdata_reg <= av_readdata_reg;
            end
        end
    end

endmodule

module ripple_carry_adder(
  input wire [3:0] A,
  input wire [3:0] B,
  input wire Cin,
  input wire enable,
  output reg [3:0] S,
  output reg Cout
);

  always @(*) begin
    if (enable) begin
      S = A + B + Cin;
      Cout = (A[3] & B[3]) | (A[3] & Cin) | (B[3] & Cin);
    end
    else begin
      S = 4'b0;
      Cout = 1'b0;
    end
  end

endmodule

module ripple_carry_adder_tb;

  reg [3:0] A;
  reg [3:0] B;
  reg Cin;
  reg enable;
  wire [3:0] S;
  wire Cout;

  ripple_carry_adder dut(A, B, Cin, enable, S, Cout);

  initial begin
    // Scenario 1: Enable signal is low, all inputs are 0
    A = 4'b0;
    B = 4'b0;
    Cin = 1'b0;
    enable = 1'b0;
    #10;
    if (S !== 4'b0 || Cout !== 1'b0) $display("Scenario 1 failed");

    // Scenario 2: Enable signal is low, all inputs are 1
    A = 4'b1;
    B = 4'b1;
    Cin = 1'b1;
    enable = 1'b0;
    #10;
    if (S !== 4'b0 || Cout !== 1'b0) $display("Scenario 2 failed");

    // Scenario 3: Enable signal is high, A and B are both 0
    A = 4'b0;
    B = 4'b0;
    Cin = 1'b0;
    enable = 1'b1;
    #10;
    if (S !== 4'b0 || Cout !== 1'b0) $display("Scenario 3 failed");

    // Scenario 4: Enable signal is high, A and B are both 1
    A = 4'b1;
    B = 4'b1;
    Cin = 1'b0;
    enable = 1'b1;
    #10;
    if (S !== 4'b10 || Cout !== 1'b0) $display("Scenario 4 failed");

    // Scenario 5: Enable signal is high, A is 0 and B is 1
    A = 4'b0;
    B = 4'b1;
    Cin = 1'b0;
    enable = 1'b1;
    #10;
    if (S !== 4'b1 || Cout !== 1'b0) $display("Scenario 5 failed");

    // Scenario 6: Enable signal is high, A is 1 and B is 0
    A = 4'b1;
    B = 4'b0;
    Cin = 1'b0;
    enable = 1'b1;
    #10;
    if (S !== 4'b1 || Cout !== 1'b0) $display("Scenario 6 failed");

    // Scenario 7: Enable signal is high, A is 1, B is 1, and Cin is 1
    A = 4'b1;
    B = 4'b1;
    Cin = 1'b1;
    enable = 1'b1;
    #10;
    if (S !== 4'b11 || Cout !== 1'b1) $display("Scenario 7 failed");

    // Display pass/fail message
    $display("Testbench complete");
  end

endmodule

