module fifo_buffer(
    input clk,
    input reset_n,
    input [WIDTH-1:0] din,
    output [WIDTH-1:0] dout
);

parameter WIDTH = 8;
parameter DEPTH = 16;

reg [WIDTH-1:0] buffer [0:DEPTH-1];
reg [DEPTH-1:0] write_ptr = 0;
reg [DEPTH-1:0] read_ptr = 0;
reg empty = 1;
reg full = 0;

always @(posedge clk) begin
    if (!reset_n) begin
        write_ptr <= 0;
        read_ptr <= 0;
        empty <= 1;
        full <= 0;
    end else begin
        if (!full) begin
            buffer[write_ptr] <= din;
            write_ptr <= write_ptr + 1;
            if (write_ptr == DEPTH) begin
                write_ptr <= 0;
            end
            empty <= 0;
            if (write_ptr == read_ptr) begin
                full <= 1;
            end
        end
    end
end

always @(posedge clk) begin
    if (!reset_n) begin
        dout <= 0;
    end else begin
        if (!empty) begin
            dout <= buffer[read_ptr];
            read_ptr <= read_ptr + 1;
            if (read_ptr == DEPTH) begin
                read_ptr <= 0;
            end
            full <= 0;
            if (read_ptr == write_ptr) begin
                empty <= 1;
            end
        end
    end
end

endmodule

module adder_4bit_cin_cout (
  input [3:0] a,
  input [3:0] b,
  input cin,
  output [3:0] sum,
  output cout
);

  wire [3:0] carry_lookahead;
  wire [3:0] sum_intermediate;

  // Generate carry lookahead signals
  assign carry_lookahead[0] = cin;
  assign carry_lookahead[1] = a[0] & b[0] | cin & a[0] | cin & b[0];
  assign carry_lookahead[2] = a[1] & b[1] | carry_lookahead[1] & a[1] | carry_lookahead[1] & b[1];
  assign carry_lookahead[3] = a[2] & b[2] | carry_lookahead[2] & a[2] | carry_lookahead[2] & b[2];

  // Generate intermediate sum
  full_adder fa0(a[0], b[0], cin, sum_intermediate[0], carry_lookahead[1]);
  full_adder fa1(a[1], b[1], carry_lookahead[1], sum_intermediate[1], carry_lookahead[2]);
  full_adder fa2(a[2], b[2], carry_lookahead[2], sum_intermediate[2], carry_lookahead[3]);
  full_adder fa3(a[3], b[3], carry_lookahead[3], sum_intermediate[3], cout);

  // Assign outputs
  assign sum = sum_intermediate;

endmodule

module full_adder (
  input a,
  input b,
  input cin,
  output sum,
  output cout
);

  assign sum = a ^ b ^ cin;
  assign cout = (a & b) | (a & cin) | (b & cin);

endmodule

module booth_multiplier (
    input signed [31:0] a,
    input signed [31:0] b,
    output signed [63:0] product
);

reg signed [63:0] product_reg;
reg signed [31:0] a_reg;
reg signed [31:0] b_reg;
reg signed [31:0] m_reg;
reg signed [31:0] ac_reg;
reg signed [1:0] count_reg;

always @(*) begin
    product_reg = a_reg * b_reg;
    a_reg = a;
    b_reg = b;
    m_reg = {b_reg[31], b_reg};
    ac_reg = 0;
    count_reg = 32;
end

always @(posedge clk) begin
    if (count_reg > 0) begin
        if (ac_reg[0] == 0 && ac_reg[1] == 0) begin
            // Shift right
            ac_reg = {ac_reg[30:0], m_reg[31]};
        end else if (ac_reg[0] == 1 && ac_reg[1] == 0) begin
            // Subtract
            ac_reg = ac_reg + (~m_reg + 1);
        end else if (ac_reg[0] == 0 && ac_reg[1] == 1) begin
            // Add
            ac_reg = ac_reg + m_reg;
        end
        count_reg = count_reg - 1;
    end else begin
        product = product_reg;
    end
end

endmodule

