module binary_multiplier (
    input [3:0] a,
    input [3:0] b,
    output [7:0] product
);

reg [7:0] temp_product = 8'b0;

integer i;

always @(*) begin
    temp_product = 8'b0;
    for (i = 0; i < 4; i = i + 1) begin
        if (b[i]) begin
            temp_product = temp_product + (a << i);
        end
    end
end

assign product = temp_product;

endmodule

module binary_to_bcd (
    input [7:0] binary_input,
    output [11:0] bcd_output
);

reg [11:0] bcd_temp = 12'b0;

integer j;

always @(*) begin
    bcd_temp = 12'b0;
    for (j = 0; j < 8; j = j + 1) begin
        bcd_temp = bcd_temp + ((binary_input[j] ? 1 : 0) << j);
        if (bcd_temp[3:0] > 4'b1001) bcd_temp[3:0] = bcd_temp[3:0] + 4'b0011;
        if (bcd_temp[7:4] > 4'b1001) bcd_temp[7:4] = bcd_temp[7:4] + 4'b0011;
        if (bcd_temp[11:8] > 4'b1001) bcd_temp[11:8] = bcd_temp[11:8] + 4'b0011;
    end
end

assign bcd_output = bcd_temp;

endmodule

