module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,
    input               select      , //Select input to choose between register and counter
    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out
);

    reg [7:0] reg_data;
    reg [3:0] counter;
    reg [9:0] accumulator;
    reg [1:0] state;

    parameter IDLE = 2'b00;
    parameter REG  = 2'b01;
    parameter CNT  = 2'b10;
    parameter ACC  = 2'b11;

    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            reg_data <= 8'h34;
            counter <= 4'b0;
            accumulator <= 10'b0;
            state <= IDLE;
            valid_b <= 1'b0;
            data_out <= 10'b0;
        end else begin
            case(state)
                IDLE: begin
                    if(valid_a) begin
                        reg_data <= data_in;
                        state <= REG;
                    end
                end
                REG: begin
                    if(counter == 4'b1111) begin
                        counter <= 4'b0;
                        state <= CNT;
                    end else begin
                        reg_data <= {reg_data[6:0], data_in};
                        counter <= counter + 1;
                    end
                end
                CNT: begin
                    if(select) begin
                        accumulator <= accumulator + reg_data;
                    end else begin
                        accumulator <= accumulator + counter;
                    end
                    if(counter == 4'b1111) begin
                        counter <= 4'b0;
                        state <= ACC;
                    end else begin
                        counter <= counter + 1;
                    end
                end
                ACC: begin
                    data_out <= accumulator;
                    valid_b <= 1'b1;
                    state <= IDLE;
                end
            endcase
        end
    end

    assign ready_a = (state == IDLE) ? 1'b1 : 1'b0;

endmodule

