module ex_mem(
    input clk,
    input [1:0] ctlwb_out,
    input [2:0] ctlm_out,
    input [31:0] adder_out,
    input aluzero,
    input [31:0] aluout,
    input [31:0] readdat2,
    input [3:0] muxout,
    output reg wb_ctlout,
    output reg m_ctlout,
    output reg [31:0] add_result,
    output reg zero,
    output reg [31:0] alu_result,
    output reg [31:0] rdata2out,
    output reg [4:0] five_bit_muxout
);

always @(*) begin
    // Set wb_ctlout and m_ctlout based on ctlwb_out
    case (ctlwb_out)
        2'b01: begin
            wb_ctlout = 1;
            m_ctlout = 0;
        end
        2'b10: begin
            wb_ctlout = 0;
            m_ctlout = 1;
        end
        default: begin
            wb_ctlout = 0;
            m_ctlout = 0;
        end
    endcase

    // Set muxout based on ctlm_out
    case (ctlm_out)
        3'b001: muxout = 4'b0011;
        3'b101: muxout = 4'b0101;
        default: muxout = 4'b0000;
    endcase

    // Set zero based on aluzero
    zero = aluzero;

    // Perform addition operation if adder_out is not zero
    if (adder_out != 0) begin
        add_result = adder_out + 32'h00000000;
        aluzero = 0;
    end else begin
        add_result = 32'h00000000;
        aluzero = 1;
    end

    // Perform ALU operation if aluout is not zero
    if (aluout != 0) begin
        alu_result = aluout & 32'hFFFFFFFF;
        aluzero = 0;
    end else begin
        alu_result = 32'h00000000;
        aluzero = 1;
    end

    // Set rdata2out based on readdat2
    if (readdat2 != 0) begin
        rdata2out = readdat2;
    end else begin
        rdata2out = 32'h00000000;
    end

    // Set five_bit_muxout based on ctlwb_out
    case (ctlwb_out)
        2'b01: five_bit_muxout = 5'b10101;
        2'b10: five_bit_muxout = 5'b00011;
        default: five_bit_muxout = 5'b00000;
    endcase
end

always @(posedge clk) begin
    // Toggle clock
    clk <= ~clk;
end

endmodule

module LEDWorm (clk1, clk2, clk3, SSLED, LEDSEL, inClk, buttonA, buttonB, reset);

	input inClk, buttonA, buttonB, reset;
	output clk1, clk2, clk3;
	output [3:0] LEDSEL;
	output [6:0] SSLED;

	reg [2:0] clockSelect;
	wire rotClk, I1, I2, I3;

	clockGen_50MHz_to_3Hz prescale_1 (clk1, inClk);				// clk1 --> 3Hz
	clockGen_divBy2 prescale_2 (clk2, clk1);						// clk2 --> 3Hz / 2 = 1.5Hz
	clockGen_divBy4 prescale_3 (clk3, clk1);						// clk3 --> 3Hz / 4 = 0.75Hz

	LEDRotator L1 (SSLED, LEDSEL, rotClk, reset);				// Keeps rotating SSLED @rotClk

	// Clock Selection Logic
	and sel_1 (I1, clk1, clockSelect[2]);				
	and sel_2 (I2, clk2, clockSelect[1]);
	and sel_3 (I3, clk3, clockSelect[0]);
	or sel_4 (rotClk, I1, I2, I3);

	// Input Signal Handling Logic
	always @(posedge buttonA or posedge buttonB or posedge reset) begin
		if (reset) begin
			clockSelect = 3'b100;						// Choose 3Hz Clock on Reset
		end else
		if (buttonA) begin
			// Shift clockwise in set {clk1, clk2, clk3}
			case (clockSelect)
				3'b100: clockSelect = 3'b010;			// clk1 --> clk2
				3'b010: clockSelect = 3'b001;			// clk2 --> clk3
				3'b001: clockSelect = 3'b100;			// clk3 --> clk1
				default: clockSelect = 3'b100;		// Any arbitrary selection goes to a valid selection
			endcase
		end
		else begin
			// Shift counter-clockwise in set {clk1, clk2, clk3}
			case (clockSelect)
				3'b100: clockSelect = 3'b001;			// clk1 --> clk3
				3'b001: clockSelect = 3'b010;			// clk3 --> clk2
				3'b010: clockSelect = 3'b100;			// clk2 --> clk1
				default: clockSelect = 3'b100;		// Any arbitrary selection goes to a valid selection
			endcase
		end
	end

endmodule

