module axi_to_b2s_converter(
    input aclk,
    input areset,
    input [31:0] m_axi_araddr,
    input m_axi_arready,
    input m_axi_rvalid,
    input [31:0] m_axi_rdata,
    input [1:0] m_axi_rresp,
    output s_axi_arready,
    output s_axi_rvalid,
    output [31:0] s_axi_rdata,
    output [1:0] s_axi_rresp
);

    // Registers to store the current state of the converter
    reg [31:0] addr_reg;
    reg [1:0] resp_reg;
    reg [31:0] data_reg;
    reg [1:0] state;

    // Constants to define the state machine
    localparam IDLE = 2'b00;
    localparam READ_AXI = 2'b01;
    localparam OUTPUT_B2S = 2'b10;

    // Set initial state
    always @(posedge aclk, negedge areset) begin
        if (~areset) begin
            state <= IDLE;
            addr_reg <= 0;
            resp_reg <= 0;
            data_reg <= 0;
        end else begin
            state <= IDLE;
        end
    end

    // State machine to control the converter
    always @(posedge aclk) begin
        case (state)
            IDLE: begin
                if (m_axi_arready && s_axi_arready) begin
                    state <= READ_AXI;
                    addr_reg <= m_axi_araddr;
                end
            end
            READ_AXI: begin
                if (m_axi_rvalid) begin
                    state <= OUTPUT_B2S;
                    data_reg <= m_axi_rdata;
                    resp_reg <= m_axi_rresp;
                end
            end
            OUTPUT_B2S: begin
                state <= IDLE;
            end
        endcase
    end

    // Output signals
    assign s_axi_arready = state == IDLE;
    assign s_axi_rvalid = state == OUTPUT_B2S;
    assign s_axi_rdata = data_reg;
    assign s_axi_rresp = resp_reg;

endmodule

module and3(
    input A,
    input B,
    input C,
    output X
);

    wire and0_out;
    wire and1_out;

    // Instantiate the sky130_fd_sc_hd__and2 gate twice
    sky130_fd_sc_hd__and2 and0(.A(A), .B(B), .Z(and0_out));
    sky130_fd_sc_hd__and2 and1(.A(C), .B(and0_out), .Z(and1_out));

    // Output of and3 is the output of the second sky130_fd_sc_hd__and2 gate
    assign X = and1_out;

endmodule

module rotator(
    input clk,
    input load,
    input [1:0] ena,
    input [99:0] data,
    output reg [99:0] q);

    reg [99:0] shift_reg;
    reg [6:0] shift_amt;
    reg [1:0] direction;

    always @(posedge clk) begin
        if (load) begin
            shift_reg <= data;
            shift_amt <= 0;
            direction <= 2'b00;
        end else begin
            case (ena)
                2'b01: begin
                    shift_amt <= shift_amt - 1;
                    direction <= 2'b01;
                end
                2'b10: begin
                    shift_amt <= shift_amt + 1;
                    direction <= 2'b10;
                end
                default: begin
                    shift_amt <= shift_amt;
                    direction <= 2'b00;
                end
            endcase

            if (shift_amt[6]) begin
                shift_reg <= {shift_reg[shift_amt[5:0]], shift_reg[99:shift_amt[5]+1], shift_reg[shift_amt[5]-1:0]};
            end else begin
                shift_reg <= {shift_reg[99-shift_amt[5]:0], shift_reg[99:99-shift_amt[5]+1], shift_reg[99-shift_amt[5]-1:0]};
            end
        end
    end

    always @* begin
        case (direction)
            2'b01: q = {shift_reg[0], shift_reg[99:1]};
            2'b10: q = {shift_reg[99], shift_reg[98:0]};
            default: q = shift_reg;
        endcase
    end

endmodule

