module vending_machine(
  input clk, //clock
  input rst, //reset button
  input coin_5, //5 cents coin
  input coin_10, //10 cents coin
  input coin_25, //25 cents coin
  input coin_100, //1 dollar coin
  input item_50, //button for item worth 50 cents
  input item_100, //button for item worth 1 dollar
  input coin_return, //coin return button
  output reg [7:0] amount, //current amount in the vending machine
  output reg [1:0] item_dispensed, //item dispensed (00: no item, 01: item worth 50 cents, 10: item worth 1 dollar)
  output reg [7:0] message //message displayed on the vending machine
);

//internal variables
reg [7:0] total_amount; //total amount inserted by the customer
reg [7:0] item_price; //price of the selected item
reg [7:0] amount_required; //amount required for the selected item
reg [1:0] selected_item; //item selected by the customer (00: no item, 01: item worth 50 cents, 10: item worth 1 dollar)
reg [7:0] amount_returned; //amount returned to the customer

//state machine states
parameter IDLE = 2'b00;
parameter COIN_INSERTED = 2'b01;
parameter ITEM_SELECTED = 2'b10;
parameter COIN_RETURNED = 2'b11;

//state machine current state
reg [1:0] state;

//state machine next state logic
always @(posedge clk) begin
  if(rst) begin
    state <= IDLE;
  end
  else begin
    case(state)
      IDLE: begin
        if(coin_5) begin
          total_amount <= total_amount + 5;
          state <= COIN_INSERTED;
        end
        else if(coin_10) begin
          total_amount <= total_amount + 10;
          state <= COIN_INSERTED;
        end
        else if(coin_25) begin
          total_amount <= total_amount + 25;
          state <= COIN_INSERTED;
        end
        else if(coin_100) begin
          total_amount <= total_amount + 100;
          state <= COIN_INSERTED;
        end
        else if(item_50) begin
          if(total_amount >= 50) begin
            item_price <= 50;
            amount_required <= 0;
            selected_item <= 1;
            state <= ITEM_SELECTED;
          end
          else begin
            amount_required <= 50 - total_amount;
            selected_item <= 0;
            state <= COIN_INSERTED;
          end
        end
        else if(item_100) begin
          if(total_amount >= 100) begin
            item_price <= 100;
            amount_required <= 0;
            selected_item <= 2;
            state <= ITEM_SELECTED;
          end
          else begin
            amount_required <= 100 - total_amount;
            selected_item <= 0;
            state <= COIN_INSERTED;
          end
        end
        else if(coin_return) begin
          amount_returned <= total_amount;
          total_amount <= 0;
          state <= COIN_RETURNED;
        end
        else begin
          state <= IDLE;
        end
      end
      COIN_INSERTED: begin
        if(coin_5) begin
          total_amount <= total_amount + 5;
        end
        else if(coin_10) begin
          total_amount <= total_amount + 10;
        end
        else if(coin_25) begin
          total_amount <= total_amount + 25;
        end
        else if(coin_100) begin
          total_amount <= total_amount + 100;
        end
        else if(item_50) begin
          if(total_amount >= 50) begin
            item_price <= 50;
            amount_required <= 0;
            selected_item <= 1;
            state <= ITEM_SELECTED;
          end
          else begin
            amount_required <= 50 - total_amount;
            selected_item <= 0;
            state <= COIN_INSERTED;
          end
        end
        else if(item_100) begin
          if(total_amount >= 100) begin
            item_price <= 100;
            amount_required <= 0;
            selected_item <= 2;
            state <= ITEM_SELECTED;
          end
          else begin
            amount_required <= 100 - total_amount;
            selected_item <= 0;
            state <= COIN_INSERTED;
          end
        end
        else if(coin_return) begin
          amount_returned <= total_amount;
          total_amount <= 0;
          state <= COIN_RETURNED;
        end
        else begin
          state <= COIN_INSERTED;
        end
      end
      ITEM_SELECTED: begin
        if(item_dispensed) begin
          if(total_amount >= item_price) begin
            item_dispensed <= selected_item;
            total_amount <= total_amount - item_price;
            amount_required <= 0;
            selected_item <= 0;
            state <= IDLE;
          end
          else begin
            amount_required <= item_price - total_amount;
            selected_item <= 0;
            state <= COIN_INSERTED;
          end
        end
        else if(coin_return) begin
          amount_returned <= total_amount;
          total_amount <= 0;
          state <= COIN_RETURNED;
        end
        else begin
          state <= ITEM_SELECTED;
        end
      end
      COIN_RETURNED: begin
        if(!coin_return) begin
          message <= amount_returned;
          amount_returned <= 0;
          state <= IDLE;
        end
        else begin
          state <= COIN_RETURNED;
        end
      end
    endcase
  end
end

//output logic
always @(state or total_amount or amount_required or selected_item or amount_returned) begin
  case(state)
    IDLE: begin
      amount <= total_amount;
      item_dispensed <= 0;
      if(amount_required > 0) begin
        message <= amount_required;
      end
      else begin
        message <= 0;
      end
    end
    COIN_INSERTED: begin
      amount <= total_amount;
      item_dispensed <= 0;
      if(amount_required > 0) begin
        message <= amount_required;
      end
      else begin
        message <= 0;
      end
    end
    ITEM_SELECTED: begin
      amount <= total_amount;
      item_dispensed <= 0;
      if(amount_required > 0) begin
        message <= amount_required;
      end
      else begin
        message <= 0;
      end
    end
    COIN_RETURNED: begin
      amount <= 0;
      item_dispensed <= 0;
      message <= amount_returned;
    end
  endcase
end

endmodule

module VGA_Animation(
    input clk,
    input rst_n,
    output reg [9:0] oRed,
    output reg [9:0] oGreen,
    output reg [9:0] oBlue,
    input [18:0] iVGA_ADDR,
    input iVGA_CLK,
    input [9:0] iON_R,
    input [9:0] iON_G,
    input [9:0] iON_B,
    input [9:0] iOFF_R,
    input [9:0] iOFF_G,
    input [9:0] iOFF_B,
    input [9:0] rect_color
);

reg [10:0] x_pos;
reg [10:0] y_pos;
reg [10:0] rect_width;
reg [10:0] rect_height;
reg [1:0] x_dir;
reg [1:0] y_dir;
reg [1:0] color_dir;
reg [9:0] color;

VGA_OSD_RAM vga_osd_ram (
    .oRed(oRed),
    .oGreen(oGreen),
    .oBlue(oBlue),
    .iVGA_ADDR(iVGA_ADDR),
    .iVGA_CLK(iVGA_CLK),
    .iON_R(iON_R),
    .iON_G(iON_G),
    .iON_B(iON_B),
    .iOFF_R(iOFF_R),
    .iOFF_G(iOFF_G),
    .iOFF_B(iOFF_B),
    .iRST_N(rst_n)
);

always @(posedge clk, negedge rst_n) begin
    if (!rst_n) begin
        x_pos <= 0;
        y_pos <= 0;
        rect_width <= 100;
        rect_height <= 50;
        x_dir <= 2'b01;
        y_dir <= 2'b01;
        color_dir <= 2'b01;
        color <= rect_color;
    end else begin
        if (x_dir == 2'b01 && x_pos >= 900) begin
            x_dir <= 2'b10;
            color_dir <= ~color_dir;
            if (color_dir == 2'b01) begin
                color <= color + 1;
            end else begin
                color <= color - 1;
            end
        end else if (x_dir == 2'b10 && x_pos <= 0) begin
            x_dir <= 2'b01;
            color_dir <= ~color_dir;
            if (color_dir == 2'b01) begin
                color <= color + 1;
            end else begin
                color <= color - 1;
            end
        end else begin
            if (x_dir == 2'b01) begin
                x_pos <= x_pos + 1;
            end else begin
                x_pos <= x_pos - 1;
            end
        end
    end
end

assign oRed = (iVGA_CLK) ? ((x_pos >= 0 && x_pos <= rect_width && y_pos >= 0 && y_pos <= rect_height) ? color : iOFF_R) : 10'b0;
assign oGreen = (iVGA_CLK) ? ((x_pos >= 0 && x_pos <= rect_width && y_pos >= 0 && y_pos <= rect_height) ? color : iOFF_G) : 10'b0;
assign oBlue = (iVGA_CLK) ? ((x_pos >= 0 && x_pos <= rect_width && y_pos >= 0 && y_pos <= rect_height) ? color : iOFF_B) : 10'b0;

endmodule

module pipelined_rotator(
    input clk,
    input load,
    input [1:0] ena,
    input [99:0] data,
    output reg [99:0] q
);

reg [99:0] shift_reg;
reg [4:0] shift_amt;
wire [99:0] rotated_out;

always @(posedge clk) begin
    if (load) begin
        shift_reg <= data;
        shift_amt <= 0;
    end else if (ena[0]) begin
        shift_reg <= {shift_reg[98:0], shift_reg[99]};
        shift_amt <= shift_amt + 1;
    end else if (ena[1]) begin
        shift_reg <= {shift_reg[1:99], shift_reg[0]};
        shift_amt <= shift_amt - 1;
    end
end

assign rotated_out = (shift_amt[4]) ? shift_reg[0] : shift_reg[99];

always @(posedge clk) begin
    if (load) begin
        q <= data;
    end else if (ena[0] || ena[1]) begin
        q <= rotated_out;
    end
end

endmodule

module binary_multiplier (
  input [3:0] a,
  input [3:0] b,
  output [7:0] p,
  output sign
);

  wire [7:0] temp_p;
  wire a_sign, b_sign, p_sign;

  assign a_sign = a[3];
  assign b_sign = b[3];

  assign temp_p[0] = a[0] & b;
  assign temp_p[1] = a[1] & b;
  assign temp_p[2] = a[2] & b;
  assign temp_p[3] = a[3] & b;
  assign temp_p[4] = 4'b0;
  assign temp_p[5] = 4'b0;
  assign temp_p[6] = 4'b0;
  assign temp_p[7] = 4'b0;

  assign p_sign = a_sign ^ b_sign;

  assign sign = p_sign;

  assign p = (p_sign) ? (~temp_p + 1) : temp_p;

endmodule

module sum2bits (
    input [3:0] in,
    output reg [1:0] out
);

    always @(*) begin
        if (in[3:2] + in[1:0] >= 2) begin
            out = 2;
        end else begin
            out = in[3:2] + in[1:0];
        end
    end

endmodule

module shift_add (
  input clk,
  input reset,
  input shift_dir,
  input [3:0] data_in,
  output [3:0] data_out
);

  reg [7:0] shift_reg = 8'b00000000;

  wire [3:0] shift_reg_out;
  wire [3:0] adder_out;

  // Instantiate the shift register
  shift_register shift_reg_inst (
    .clk(clk),
    .reset(reset),
    .shift_dir(shift_dir),
    .data_in(data_in),
    .data_out(shift_reg_out)
  );

  // Instantiate the adder
  adder adder_inst (
    .a(shift_reg_out),
    .b(data_in),
    .sum(adder_out)
  );

  // Assign the output of the adder to the shift register input
  always @ (posedge clk) begin
    if (reset) begin
      shift_reg <= 8'b00000000;
    end else begin
      shift_reg <= {shift_dir, adder_out};
    end
  end

  // Assign the output of the shift register to the module output
  assign data_out = shift_reg_out;

endmodule

// Shift register module
module shift_register (
  input clk,
  input reset,
  input shift_dir,
  input [3:0] data_in,
  output [3:0] data_out
);

  reg [7:0] shift_reg = 8'b00000000;

  always @ (posedge clk) begin
    if (reset) begin
      shift_reg <= 8'b00000000;
    end else begin
      if (shift_dir) begin
        shift_reg <= {shift_reg[6:0], data_in};
      end else begin
        shift_reg <= {data_in, shift_reg[7:1]};
      end
    end
  end

  assign data_out = shift_reg[3:0];

endmodule

// Adder module
module adder (
  input [3:0] a,
  input [3:0] b,
  output [3:0] sum
);

  assign sum = a + b;

endmodule

module clock_generator (
    input SCE,
    input GATE,
    input CLK,
    input VPWR,
    input VGND,
    input VPB,
    input VNB,
    output reg GCLK
);

    reg [1:0] state;
    parameter IDLE = 2'b00;
    parameter RISE = 2'b01;
    parameter FALL = 2'b10;
    parameter HIGH = 2'b11;

    always @ (posedge CLK) begin
        if (SCE) begin
            case (state)
                IDLE: begin
                    if (GATE) begin
                        state <= RISE;
                        GCLK <= 1'b0;
                    end else begin
                        GCLK <= 1'b0;
                    end
                end
                RISE: begin
                    state <= HIGH;
                    GCLK <= 1'b1;
                end
                HIGH: begin
                    if (!GATE) begin
                        state <= FALL;
                        GCLK <= 1'b1;
                    end else begin
                        GCLK <= 1'b1;
                    end
                end
                FALL: begin
                    state <= IDLE;
                    GCLK <= 1'b0;
                end
            endcase
        end else begin
            state <= IDLE;
            GCLK <= 1'b0;
        end
    end
endmodule

module delay_module (
   input clk,
   input reset,
   input data_in,
   output reg data_out,
   output reg valid_out
   );

   reg data_in_delayed;

   always @(posedge clk) begin
      if (reset) begin
         data_out <= 1'b0;
         valid_out <= 1'b0;
         data_in_delayed <= 1'b0;
      end
      else begin
         data_out <= data_in_delayed;
         valid_out <= (data_out != data_in_delayed);
         data_in_delayed <= data_in;
      end
   end

endmodule

