module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] d,    // 8-bit input for the register
    output [7:0] q    // 8-bit output from the functional module
);

    reg [7:0] reg_q;    // 8-bit register output
    reg [7:0] shift_q;  // 8-bit shift register output
    reg [7:0] sum_q;    // 8-bit sum output

    // T flip-flops for the register
    reg t1, t2, t3, t4, t5, t6, t7, t8;

    // Combinational logic for the shift register
    wire [7:0] shift_d = {shift_q[6:0], reg_q[0]}; // Shift in data on positive edge
    wire [7:0] shift_qn = {shift_q[7], shift_q[7:1]}; // Shift out data on negative edge

    // Register with synchronous reset
    always @(posedge clk) begin
        if (reset) begin
            t1 <= 1'b0;
            t2 <= 1'b0;
            t3 <= 1'b1;
            t4 <= 1'b1;
            t5 <= 1'b0;
            t6 <= 1'b1;
            t7 <= 1'b0;
            t8 <= 1'b0;
            reg_q <= 8'h34; // Reset to 0x34
        end else begin
            t1 <= d[0] ^ t2;
            t2 <= t1 ^ t3;
            t3 <= t2 ^ t4;
            t4 <= t3 ^ t5;
            t5 <= t4 ^ t6;
            t6 <= t5 ^ t7;
            t7 <= t6 ^ t8;
            t8 <= t7 ^ d[7];
            reg_q <= {t8, t7, t6, t5, t4, t3, t2, t1};
        end
    end

    // Shift register
    always @(posedge clk or negedge reset) begin
        if (reset) begin
            shift_q <= 8'h00;
        end else begin
            shift_q <= shift_qn;
        end
    end

    // Functional module that outputs the sum of the register and shift register
    always @(*) begin
        sum_q = reg_q + shift_q;
    end

    assign q = sum_q; // Output the sum

endmodule

module top_module(
    input [7:0] a,
    input [7:0] b,
    input sub,
    output [7:0] result
);

    wire [7:0] add_result;
    wire [7:0] sub_result;
    wire [7:0] inverted_b;
    wire borrow;

    ripple_carry_adder adder(
        .a(a),
        .b(b),
        .cin(1'b0),
        .sum(add_result),
        .cout()
    );

    full_subtractor subtractor(
        .a(a),
        .b(b),
        .borrow(borrow),
        .diff(sub_result)
    );

    assign inverted_b = sub ? ~b : b;

    assign result = sub ? sub_result : add_result;

endmodule

module ripple_carry_adder(
    input [7:0] a,
    input [7:0] b,
    input cin,
    output [7:0] sum,
    output cout
);

    wire [7:0] carry;
    assign carry[0] = cin;

    genvar i;
    generate
        for (i = 0; i < 8; i = i + 1) begin : adder_loop
            full_adder adder(
                .a(a[i]),
                .b(b[i]),
                .cin(carry[i]),
                .sum(sum[i]),
                .cout(carry[i+1])
            );
        end
    endgenerate

    assign cout = carry[8];

endmodule

module full_adder(
    input a,
    input b,
    input cin,
    output sum,
    output cout
);

    assign {cout, sum} = a + b + cin;

endmodule

module full_subtractor(
    input [7:0] a,
    input [7:0] b,
    input borrow,
    output [7:0] diff
);

    wire [7:0] inverted_b;
    assign inverted_b = ~b;

    wire [7:0] borrow_inverted_b;
    assign borrow_inverted_b = borrow ? inverted_b + 1 : inverted_b;

    ripple_carry_adder subtractor(
        .a(a),
        .b(borrow_inverted_b),
        .cin(borrow),
        .sum(diff),
        .cout()
    );

endmodule

