module prbs_gen (
    input clk_i,
    input clk_en_i,
    input rst_i,
    input [63:0] prbs_seed_i,
    input phy_if_empty,
    input prbs_rdlvl_start,
    output reg [63:0] prbs_o
);

    // Define LFSR polynomial
    parameter LFSR_POLY = 64'hAD6F7036CCBFE794;

    // Define PRBS sequence length in cycles
    parameter PRBS_SEQ_LEN_CYCLES = 128;

    // Define PRBS sequence length in bits
    parameter PRBS_SEQ_LEN_BITS = $clog2(PRBS_SEQ_LEN_CYCLES);

    // Define PRBS reset signal length in cycles
    parameter PRBS_RESET_CYCLES = 2;

    // Define PRBS reset signal length in bits
    parameter PRBS_RESET_BITS = $clog2(PRBS_RESET_CYCLES);

    // Define PRBS reset signal counter
    reg [PRBS_RESET_BITS-1:0] prbs_reset_cnt;

    // Define PRBS sequence length counter
    reg [PRBS_SEQ_LEN_BITS-1:0] prbs_seq_cnt;

    // Define LFSR shift register
    reg [63:0] lfsr;

    // Define PRBS sequence output enable
    reg prbs_output_enable;

    // Reset LFSR and counters on reset or when FIFO is empty
    always @(posedge clk_i) begin
        if (rst_i || phy_if_empty) begin
            lfsr <= prbs_seed_i;
            prbs_reset_cnt <= 0;
            prbs_seq_cnt <= 0;
            prbs_output_enable <= 1'b0;
        end
    end

    // Generate PRBS reset signal to ensure sequence repeats after 2^64 samples
    always @(posedge clk_i) begin
        if (rst_i || ~clk_en_i) begin
            prbs_reset_cnt <= 0;
        end else if (clk_en_i && (~phy_if_empty || ~prbs_rdlvl_start)) begin
            if (prbs_reset_cnt == PRBS_RESET_CYCLES-1) begin
                lfsr <= prbs_seed_i;
                prbs_seq_cnt <= 0;
                prbs_output_enable <= 1'b0;
            end else if (prbs_seq_cnt == PRBS_SEQ_LEN_CYCLES-1) begin
                prbs_reset_cnt <= prbs_reset_cnt + 1;
            end
        end
    end

    // Generate PRBS sequence
    always @(posedge clk_i) begin
        if (rst_i || ~clk_en_i) begin
            prbs_o <= 0;
        end else if (clk_en_i && (~phy_if_empty || ~prbs_rdlvl_start)) begin
            if (prbs_seq_cnt == PRBS_SEQ_LEN_CYCLES-1) begin
                prbs_seq_cnt <= 0;
                prbs_output_enable <= 1'b1;
            end else begin
                prbs_seq_cnt <= prbs_seq_cnt + 1;
                prbs_output_enable <= 1'b0;
            end

            if (prbs_output_enable) begin
                prbs_o <= lfsr[63];
            end

            lfsr <= {lfsr[62:0], lfsr[0] ^ lfsr[3] ^ lfsr[7] ^ lfsr[10] ^ lfsr[11] ^ lfsr[13] ^ lfsr[14] ^ lfsr[15] ^ lfsr[16] ^ lfsr[17] ^ lfsr[21] ^ lfsr[22] ^ lfsr[23] ^ lfsr[26] ^ lfsr[28] ^ lfsr[31] ^ lfsr[32] ^ lfsr[33] ^ lfsr[34] ^ lfsr[35] ^ lfsr[36] ^ lfsr[40] ^ lfsr[41] ^ lfsr[42] ^ lfsr[45] ^ lfsr[46] ^ lfsr[52] ^ lfsr[53] ^ lfsr[54] ^ lfsr[56] ^ lfsr[58] ^ lfsr[59] ^ lfsr[63]};
        end
    end

endmodule

module clock_gate_d_ff_en (
  input logic CLK,
  input logic EN,
  input logic TE,
  output logic ENCLK
);

  logic gated_clk;
  logic d;

  // D flip-flop
  always_ff @(posedge CLK) begin
    if (EN) begin
      d <= CLK;
    end
  end

  // Clock gate
  assign gated_clk = EN ? CLK : 1'b0;

  // Toggle enable
  always_ff @(posedge CLK) begin
    if (TE) begin
      ENCLK <= ~ENCLK;
    end else begin
      ENCLK <= gated_clk;
    end
  end

endmodule

