module receiver(CLK, reset, Start, iRX_BUF_FRAME_TYPE, iALERT, iRECEIVE_DETECT, iRECEIVE_BYTE_COUNT, Data_In, oALERT, oRECEIVE_BYTE_COUNT, oGoodCRC_to_PHY, oDIR_WRITE, oDATA_to_Buffer);

	//inputs declaration
	input wire CLK;
	input wire reset;
	input wire Start;
	input wire [7:0] iRX_BUF_FRAME_TYPE;
	input wire [15:0] iALERT;
	input wire [7:0] iRECEIVE_DETECT;
	input wire [7:0] iRECEIVE_BYTE_COUNT;
	input wire [7:0] Data_In;

	//outputs declaration
	output reg [15:0] oALERT;
	output reg [7:0] oRECEIVE_BYTE_COUNT;
	output reg oGoodCRC_to_PHY;
	output reg [7:0] oDIR_WRITE;
	output reg [7:0] oDATA_to_Buffer;

	//internal signals
	reg [7:0] byte_count;
	reg [7:0] crc;
	reg [7:0] crc_calc;
	reg [7:0] state;
	reg [7:0] next_state;
	reg [7:0] frame[255:0];
	reg [7:0] byte_index;
	reg [7:0] byte_count_index;
	reg [7:0] data_index;

	//constants
	localparam IDLE = 8'h00;
	localparam WAIT_FOR_DETECT = 8'h01;
	localparam WAIT_FOR_FRAME = 8'h02;
	localparam CRC_CHECK = 8'h03;
	localparam SEND_TO_BUFFER = 8'h04;

	//CRC polynomial
	localparam POLY = 8'h07;

	//initial state
	always @(posedge CLK) begin
		if (reset) begin
			state <= IDLE;
			byte_count <= 0;
			crc <= 0;
			crc_calc <= 0;
			byte_index <= 0;
			byte_count_index <= 0;
			data_index <= 0;
			oALERT <= 16'b0;
			oRECEIVE_BYTE_COUNT <= 8'b0;
			oGoodCRC_to_PHY <= 0;
			oDIR_WRITE <= 8'b0;
			oDATA_to_Buffer <= 8'b0;
		end else begin
			state <= next_state;
		end
	end

	//state machine
	always @(posedge CLK) begin
		case (state)
			IDLE: begin
				if (Start) begin
					next_state <= WAIT_FOR_DETECT;
				end else begin
					next_state <= IDLE;
				end
			end

			WAIT_FOR_DETECT: begin
				if (iRECEIVE_DETECT) begin
					next_state <= WAIT_FOR_FRAME;
				end else begin
					next_state <= WAIT_FOR_DETECT;
				end
			end

			WAIT_FOR_FRAME: begin
				if (byte_index == 0) begin
					frame[byte_index] <= Data_In;
					byte_index <= byte_index + 1;
					byte_count <= iRECEIVE_BYTE_COUNT;
				end else if (byte_index > byte_count) begin
					next_state <= CRC_CHECK;
				end else begin
					frame[byte_index] <= Data_In;
					byte_index <= byte_index + 1;
				end
			end

			CRC_CHECK: begin
				for (byte_count_index = 0; byte_count_index < byte_count; byte_count_index = byte_count_index + 1) begin
					crc_calc <= frame[byte_count_index] ^ crc;
					for (data_index = 0; data_index < 8; data_index = data_index + 1) begin
						if (crc_calc[7]) begin
							crc_calc <= crc_calc << 1 ^ POLY;
						end else begin
							crc_calc <= crc_calc << 1;
						end
					end
					crc <= crc_calc;
				end

				if (crc == 0) begin
					oGoodCRC_to_PHY <= 1;
					oALERT <= 16'b0000000000000001;
				end else begin
					oGoodCRC_to_PHY <= 0;
					oALERT <= 16'b0000000000000010;
				end

				oRECEIVE_BYTE_COUNT <= byte_count;
				next_state <= SEND_TO_BUFFER;
			end

			SEND_TO_BUFFER: begin
				oDIR_WRITE <= 8'b1;
				oDATA_to_Buffer <= frame[byte_index];
				byte_index <= byte_index + 1;

				if (byte_index > byte_count) begin
					next_state <= IDLE;
				end else begin
					next_state <= SEND_TO_BUFFER;
				end
			end
		endcase
	end
endmodule

