                                reset_col=1'b0;
                                add_ascci=1'b0;
                                reset_ascci=1'b0;
                                leer_rom=1'b1;
                                init=0;

                        next_state<=state_4;
                    end

            state_4:    begin       //pasa a sigiente columna
                                add_dirram=1'b1;
                                reset_dirram=1'b0;
                                add_col=1'b1;
                                reset_col=1'b0;
                                add_ascci=1'b0;
                                reset_ascci=1'b0;
                                leer_rom=1'b1;
                                init=0;
                        if (top_col == 1'b1) next_state<=state_5;
                        else next_state<=state_3;

                    end

            state_5:    begin       // pasa a sigiente ascci
                                add_dirram=1'b1;
                                reset_dirram=1'b0;
                                add_col=1'b0;
                                reset_col=1'b1;
                                add_ascci=1'b1;
                                reset_ascci=1'b0;
                                leer_rom=1'b0;
                                init=0;
                        if (top_ascci==1'b1)next_state<=start;
                        else next_state<=state_1;

                    end

            default:
                    begin
                                add_dirram=1'b0;
                                reset_dirram=1'b0;
                                add_col=1'b0;
                                reset_col=1'b0;
                                add_ascci=1'b0;
                                reset_ascci=1'b0;
                                leer_rom=1'b0;
                                init=0;
                        next_state<=start;
                    end
        endcase
    end    

    always @(negedge clk) begin
        current_state<=next_state;  
    end
endmodule

module d_ff_asr (
    input D,
    input CLK_N,
    input SET_B,
    input RESET_B,
    output Q,
    output Q_N
);

    reg q;
    reg q_n;

    always @ (posedge CLK_N or negedge SET_B or negedge RESET_B) begin
        if (!SET_B) begin
            q <= 1'b1;
            q_n <= 1'b0;
        end else if (!RESET_B) begin
            q <= 1'b0;
            q_n <= 1'b1;
        end else if (CLK_N) begin
            q <= D;
            q_n <= ~D;
        end
    end

    assign Q = q;
    assign Q_N = q_n;

endmodule

