module shd_pe_fifo_rd_logic
   (empty,
    O1,
    tmp_ram_rd_en,
    E,
    rd_clk,
    Q,
    WR_PNTR_RD,
    rd_en);
  output empty;
  output [11:0]O1;
  output tmp_ram_rd_en;
  output [0:0]E;
  input rd_clk;
  input [1:0]Q;
  input [11:0]WR_PNTR_RD;
  input rd_en;

  wire [0:0]E;
  wire [11:0]O1;
  wire [1:0]Q;
  wire [11:0]WR_PNTR_RD;
  wire [0:0]curr_fwft_state;
  wire empty;
  wire n_2_gr1_rfwt;
  wire p_14_out;
  wire p_18_out;
  wire rd_clk;
  wire rd_en;
  wire [11:0]rd_pntr_plus1;
  wire tmp_ram_rd_en;

  shd_pe_fifo_rd_fwft gr1_rfwt
       (.E(E),
        .O1({n_2_gr1_rfwt, curr_fwft_state}),
        .Q(Q),
        .empty(empty),
        .p_18_out(p_18_out),
        .rd_clk(rd_clk),
        .rd_en(rd_en),
        .sel(p_14_out),
        .tmp_ram_rd_en(tmp_ram_rd_en));

  shd_pe_fifo_rd_status_flags_as gras_rsts
       (.I1({n_2_gr1_rfwt, curr_fwft_state}),
        .O1(O1),
        .Q(Q[1]),
        .WR_PNTR_RD(WR_PNTR_RD),
        .out(rd_pntr_plus1),
        .p_18_out(p_18_out),
        .rd_clk(rd_clk),
        .rd_en(rd_en));

  shd_pe_fifo_rd_bin_cntr rpntr
       (.O1(O1),
        .Q(Q[1]),
        .out(rd_pntr_plus1),
        .rd_clk(rd_clk),
        .sel(p_14_out));

  assign empty = (WR_PNTR_RD[11:0] == rd_pntr_plus1[11:0]) && (WR_PNTR_RD[0] == rd_pntr_plus1[0] ^ Q[0]);
  assign n_2_gr1_rfwt = ~Q[0] & ~Q[1];
  assign p_14_out = Q[0] & ~Q[1];
  assign p_18_out = (WR_PNTR_RD[11:0] == rd_pntr_plus1[11:0]) && (WR_PNTR_RD[0] ^ rd_pntr_plus1[0] ^ Q[0]);
  assign tmp_ram_rd_en = Q[1] & ~Q[0];

endmodule

module shd_pe_fifo_rd_fwft
       (E, O1, Q, empty, p_18_out, rd_clk, rd_en, sel, tmp_ram_rd_en);
  output [0:0] E;
  output [11:0] O1;
  output [1:0] Q;
  output empty;
  output p_18_out;
  output tmp_ram_rd_en;
  input rd_clk;
  input rd_en;
  input sel;

  reg [0:0] E;
  reg [11:0] O1;
  reg [1:0] Q;
  reg empty;
  reg p_18_out;
  reg tmp_ram_rd_en;

  parameter IDLE = 2'b00;
  parameter READ = 2'b01;
  parameter END = 2'b10;

  always @(posedge rd_clk) begin
    case (Q)
      IDLE: begin
        if (rd_en && sel) begin
          Q <= READ;
          empty <= 1'b0;
          tmp_ram_rd_en <= 1'b1;
        end
      end
      READ: begin
        if (E) begin
          Q <= END;
          empty <= 1'b1;
          tmp_ram_rd_en <= 1'b0;
        end else begin
          Q <= IDLE;
          empty <= 1'b0;
          tmp_ram_rd_en <= 1'b0;
        end
      end
      END: begin
        Q <= IDLE;
        empty <= 1'b0;
        tmp_ram_rd_en <= 1'b0;
      end
    endcase
  end

  assign E = (Q == END);
  assign O1 = {12{~tmp_ram_rd_en}} & {tmp_ram_rd_en, 12'b0};
endmodule

module shd_pe_fifo_rd_status_flags_as
       (I1, O1, Q, WR_PNTR_RD, out, p_18_out, rd_clk, rd_en);
  input [12:0] I1;
  output [11:0] O1;
  output [1:0] Q;
  input [11:0] WR_PNTR_RD;
  output [11:0] out;
  output p_18_out;
  input rd_clk;
  input rd_en;

  reg [11:0] O1;
  reg [1:0] Q;
  reg [11:0] out;
  reg p_18_out;

  always @(posedge rd_clk) begin
    if (rd_en) begin
      O1 <= I1[12:1];
      Q <= I1[1:0];
      out <= WR_PNTR_RD + 1'b1;
      p_18_out <= I1[0] ^ Q[1] ^ out[0];
    end
  end
endmodule

module shd_pe_fifo_rd_bin_cntr
       (O1, Q, out, rd_clk, sel);
  output [11:0] O1;
  output [1:0] Q;
  output [11:0] out;
  input rd_clk;
  input sel;

  reg [11:0] O1;
  reg [1:0] Q;
  reg [11:0] out;

  always @(posedge rd_clk) begin
    if (sel) begin
      out <= O1 + 1'b1;
      Q[1] <= (out == 12'h1000);
      Q[0] <= ~Q[0];
    end
  end

  assign O1 = out;
endmodule

module top_module (
