    input [3:0] in1,  // 4-bit binary input 1
    input [3:0] in2,  // 4-bit binary input 2
    input [7:0] sel,  // Select input to choose between multiplexer and AND gate
    output [3:0] out  // Final 4-bit binary output after addition
);

wire [3:0] mux_out;
wire [3:0] and_out;
wire [3:0] add_out;

mux_256to1 mux_inst (
