  wire g_out_BAR_wire;
  assign g_out_BAR_wire = ~(g_prec & p | g);
  assign g_out_BAR = g_out_BAR_wire;

  // AND2 gate
  wire p_out_wire;
  assign p_out_wire = p_prec & p;
  assign p_out = p_out_wire;

endmodule

module clk_gen (
  // Clock in ports
  input         clk_in,
  // Clock out ports
  output        clk_out,
  // Status and control signals
  input         reset
);

  // Input buffering
  //------------------------------------
  IBUF clkin_ibuf
   (.O (clk_in_buf),
    .I (clk_in));

  // Clocking PRIMITIVE
  //------------------------------------
  // Instantiation of the MMCM PRIMITIVE
  //    * Unused inputs are tied off
  //    * Unused outputs are labeled unused
  wire [15:0] do_unused;
  wire        drdy_unused;
  wire        psdone_unused;
  wire        locked;
  wire        clkfbout;
  wire        clkfbout_buf;
  wire        clkfboutb_unused;
  wire        clkout0b_unused;
  wire        clkout1_unused;
  wire        clkout1b_unused;
  wire        clkout2_unused;
  wire        clkout2b_unused;
  wire        clkout3_unused;
  wire        clkout3b_unused;
  wire        clkout4_unused;
  wire        clkout5_unused;
  wire        clkout6_unused;
  wire        clkfbstopped_unused;
  wire        clkinstopped_unused;
  wire        reset_high;

  MMCME2_ADV
  #(.BANDWIDTH            ("OPTIMIZED"),
    .CLKOUT4_CASCADE      ("FALSE"),
    .COMPENSATION         ("ZHOLD"),
    .STARTUP_WAIT         ("FALSE"),
    .DIVCLK_DIVIDE        (1),
    .CLKFBOUT_MULT_F      (10.000),
    .CLKFBOUT_PHASE       (0.000),
    .CLKFBOUT_USE_FINE_PS ("FALSE"),
    .CLKOUT0_DIVIDE_F     (2.000),
    .CLKOUT0_PHASE        (0.000),
    .CLKOUT0_DUTY_CYCLE   (0.500),
    .CLKOUT0_USE_FINE_PS  ("FALSE"),
    .CLKIN1_PERIOD        (10.0))
  mmcm_inst
    // Output clocks
   (
    .CLKFBOUT            (clkfbout),
    .CLKFBOUTB           (clkfboutb_unused),
    .CLKOUT0             (clk_out_buf),
    .CLKOUT0B            (clkout0b_unused),
    .CLKOUT1             (clkout1_unused),
    .CLKOUT1B            (clkout1b_unused),
    .CLKOUT2             (clkout2_unused),
    .CLKOUT2B            (clkout2b_unused),
    .CLKOUT3             (clkout3_unused),
    .CLKOUT3B            (clkout3b_unused),
    .CLKOUT4             (clkout4_unused),
    .CLKOUT5             (clkout5_unused),
    .CLKOUT6             (clkout6_unused),
     // Input clock control
    .CLKFBIN             (clkfbout_buf),
    .CLKIN1              (clk_in_buf),
    .CLKIN2              (1'b0),
     // Tied to always select the primary input clock
    .CLKINSEL            (1'b1),
    // Ports for dynamic reconfiguration
    .DADDR               (7'h0),
    .DCLK                (1'b0),
    .DEN                 (1'b0),
    .DI                  (16'h0),
    .DO                  (do_unused),
    .DRDY                (drdy_unused),
    .DWE                 (1'b0),
    // Ports for dynamic phase shift
    .PSCLK               (1'b0),
    .PSEN                (1'b0),
    .PSINCDEC            (1'b0),
    .PSDONE              (psdone_unused),
    // Other control and status signals
    .LOCKED              (locked),
    .CLKINSTOPPED        (clkinstopped_unused),
    .CLKFBSTOPPED        (clkfbstopped_unused),
    .PWRDWN              (1'b0),
    .RST                 (reset_high));

  assign reset_high = reset;

  // Output buffering
  //-----------------------------------

  BUFG clk_out_bufg
   (.O (clk_out),
    .I (clk_out_buf));

  // Synchronization
  //-----------------------------------

  reg clk_out_synced;
  always @(posedge clk_out_bufg or posedge reset) begin
    if (reset) begin
      clk_out_synced <= 1'b0;
    end else begin
      clk_out_synced <= 1'b1;
    end
  end

endmodule

module fifo_module(
  s_aclk,
  s_aresetn,
  s_axis_tvalid,
  s_axis_tready,
  s_axis_tdata,
  m_axis_tvalid,
  m_axis_tready,
  m_axis_tdata
);

input s_aclk;
input s_aresetn;
input s_axis_tvalid;
output s_axis_tready;
input [511 : 0] s_axis_tdata;
output m_axis_tvalid;
input m_axis_tready;
output [511 : 0] m_axis_tdata;

reg [511:0] fifo_mem [0:1023]; // FIFO memory
reg [9:0] wr_ptr = 0; // write pointer
reg [9:0] rd_ptr = 0; // read pointer
reg [9:0] fifo_count = 0; // count of elements in FIFO

// Combinational logic to check if FIFO is full or empty
assign fifo_full = (fifo_count == 1024);
assign fifo_empty = (fifo_count == 0);

// Logic to increment/decrement FIFO pointers and count
always @(posedge s_aclk) begin
    if (s_aresetn == 0) begin
        wr_ptr <= 0;
        rd_ptr <= 0;
        fifo_count <= 0;
    end else begin
        if (s_axis_tvalid && !fifo_full) begin
            fifo_mem[wr_ptr] <= s_axis_tdata;
            wr_ptr <= (wr_ptr == 1023) ? 0 : wr_ptr + 1;
            fifo_count <= fifo_count + 1;
        end
        if (m_axis_tready && !fifo_empty) begin
            m_axis_tdata <= fifo_mem[rd_ptr];
            rd_ptr <= (rd_ptr == 1023) ? 0 : rd_ptr + 1;
            fifo_count <= fifo_count - 1;
        end
    end
end

// Logic to control the ready signals
assign s_axis_tready = !fifo_full;
assign m_axis_tvalid = !fifo_empty;

endmodule

module full_adder (
    input a, b, cin,
    output reg sum, carry_out
);

    assign {sum, carry_out} = (a + b + cin) == 3'b000 ? 2'b00 :
                               (a + b + cin) == 3'b001 ? 2'b01 :
                               (a + b + cin) == 3'b010 ? 2'b01 :
                               (a + b + cin) == 3'b011 ? 2'b10 :
                               (a + b + cin) == 3'b100 ? 2'b01 :
                               (a + b + cin) == 3'b101 ? 2'b10 :
                               (a + b + cin) == 3'b110 ? 2'b10 :
                               (a + b + cin) == 3'b111 ? 2'b11 : 2'b00;

endmodule

module rotator (
    input clk,
    input reset,
    input [99:0] data,
    input load,
    input [1:0] ena,
    output reg [99:0] q
);

    always @(posedge clk, posedge reset) begin
        if (reset) begin
            q <= 100'b0;
        end else if (load) begin
            q <= data;
        end else if (ena == 2'b00) begin
            q <= {q[98:0], q[99]};
        end else if (ena == 2'b01) begin
            q <= {q[97:0], q[99:98]};
        end else if (ena == 2'b10) begin
            q <= {q[0], q[99:1]};
        end else if (ena == 2'b11) begin
            q <= {q[1:0], q[99:2]};
        end
    end

endmodule

module functional_module (
    input [99:0] full_adder_out,
    input [99:0] rotator_out,
    output reg [99:0] q
);

    always @(*) begin
        q = full_adder_out ^ rotator_out;
    end

endmodule

module top_module (
    input clk,
    input reset,
    input a, b, cin,
    input load,
    input [1:0] ena,
    input [99:0] data,
    input select,
    output reg [99:0] q
);

    wire [99:0] full_adder_out;
    wire [99:0] rotator_out;

    full_adder fa_inst (.a(a), .b(b), .cin(cin), .sum(full_adder_out[0]), .carry_out(full_adder_out[1]));
    rotator rot_inst (.clk(clk), .reset(reset), .data(data), .load(load), .ena(ena), .q(rotator_out));
    functional_module fm_inst (.full_adder_out(full_adder_out), .rotator_out(rotator_out), .q(q));

    always @(posedge clk, posedge reset) begin
        if (reset) begin
            q <= 100'b0;
        end else if (select) begin
            q <= full_adder_out;
        end else begin
            q <= rotator_out;
        end
    end

endmodule

module fallthrough_small_fifo
#(
    parameter WIDTH = 32,
    parameter MAX_DEPTH_BITS = 3,
    parameter PROG_FULL_THRESHOLD = 4
)
(
    input clk,
    input reset,
    input wr_en,
    input rd_en,
    input [WIDTH-1:0] din,
    output [WIDTH-1:0] dout,
    output full,
    output nearly_full,
    output prog_full,
    output empty
);

localparam MAX_DEPTH = 1 << MAX_DEPTH_BITS;

reg [WIDTH-1:0] mem [0:MAX_DEPTH-1];
reg [MAX_DEPTH_BITS-1:0] wr_ptr = 0;
reg [MAX_DEPTH_BITS-1:0] rd_ptr = 0;
reg [MAX_DEPTH_BITS-1:0] depth = 0;

assign full = (depth == MAX_DEPTH);
assign empty = (depth == 0);
assign nearly_full = (depth >= PROG_FULL_THRESHOLD);
assign prog_full = (depth == PROG_FULL_THRESHOLD);

always @(posedge clk) begin
    if (reset) begin
        wr_ptr <= 0;
        rd_ptr <= 0;
        depth <= 0;
    end else begin
        if (wr_en && !full) begin
            mem[wr_ptr] <= din;
            wr_ptr <= wr_ptr + 1;
            depth <= depth + 1;
            if (wr_ptr == MAX_DEPTH) begin
                wr_ptr <= 0;
            end
        end
        if (rd_en && !empty) begin
            dout <= mem[rd_ptr];
            rd_ptr <= rd_ptr + 1;
            depth <= depth - 1;
            if (rd_ptr == MAX_DEPTH) begin
                rd_ptr <= 0;
            end
        end
    end
end

endmodule

module clock_phase_shifter (
  input clk_in,
  input [7:0] delay,
  output clk_out
);

  reg [7:0] delay_count;
  reg delayed_clk;

  always @(posedge clk_in) begin
    if (delay_count == delay) begin
      delayed_clk <= 1'b1;
      delay_count <= 0;
    end else begin
      delayed_clk <= 1'b0;
      delay_count <= delay_count + 1;
    end
  end

  always @(posedge delayed_clk) begin
    clk_out <= 1'b1;
  end

endmodule

module parity_generator (
    input [7:0] in,
    output [8:0] out);

    wire p1, p2, p4, p8;

