module packet_transmitter (
    input clk,
    input reset,
    input in_wr,
    input in_ctrl,
    input tx_queue_en,
    input m_tx_axis_aclk,
    input reset_txclk,
    output reg tx_fifo_wr_en,
    output reg tx_fifo_rd_en,
    output reg m_tx_axis_tvalid,
    output reg m_tx_axis_tlast,
    output reg [3:0] m_tx_axis_tkeep,
    output reg txf_pkts_avail
);

    // input state machine states
    parameter [1:0]
        INPUT_IDLE = 2'b00,
        INPUT_PKTS = 2'b01;
    reg [1:0] tx_input_state, tx_input_state_nxt;

    // output state machine states
    parameter [1:0]
        IDLE = 2'b00,
        WAIT_FOR_READY = 2'b01,
        WAIT_FOR_EOP = 2'b10;
    reg [1:0] tx_mac_state, tx_mac_state_nxt;

    // pulse synchronizers
    wire pkt_stored_txclk, pkt_sent_txclk;
    pulse_synchronizer tx_pkt_stored_sync (
        .pulse_in_clkA(tx_pkt_stored),
        .clkA(clk),
        .pulse_out_clkB(pkt_stored_txclk),
        .clkB(m_tx_axis_aclk),
        .reset_clkA(reset),
        .reset_clkB(reset_txclk)
    );
    pulse_synchronizer tx_pkt_sent_sync (
        .pulse_in_clkA(pkt_sent_txclk),
        .clkA(m_tx_axis_aclk),
        .pulse_out_clkB(tx_pkt_sent),
        .clkB(clk),
        .reset_clkA(reset_txclk),
        .reset_clkB(reset)
    );

    // stats
    reg [7:0] txf_num_pkts_waiting;
    always @(posedge m_tx_axis_aclk) begin
        if (reset_txclk) begin
            txf_num_pkts_waiting <= 'h0;
        end
        else begin
            case ({pkt_sent_txclk, pkt_stored_txclk})
                2'b01 : txf_num_pkts_waiting <= txf_num_pkts_waiting + 1;
                2'b10 : txf_num_pkts_waiting <= txf_num_pkts_waiting - 1;
                default: begin end
            endcase
        end
    end

    // input state machine
    always @* begin
        tx_fifo_wr_en = 1'b0;
        tx_input_state_nxt = tx_input_state;
        case (tx_input_state)
            INPUT_IDLE: begin
                if (in_wr) begin
                    tx_fifo_wr_en = 1'b1;
                    tx_input_state_nxt = INPUT_PKTS;
                end
            end
            INPUT_PKTS: begin
                if (in_wr) begin
                    tx_fifo_wr_en = 1'b1;
                    if (|in_ctrl) begin
                        tx_pkt_stored = 1'b1;
                        tx_input_state_nxt = INPUT_IDLE;
                    end
                end
            end
        endcase
    end

    // output state machine
    always @* begin
        tx_mac_state_nxt = tx_mac_state;
        tx_fifo_rd_en = 1'b0;
        m_tx_axis_tvalid_nxt = 1'b0;
        m_tx_axis_tlast = 1'b0;
        m_tx_axis_tkeep = 4'b1111;
        case (tx_mac_state)
            IDLE: if (txf_pkts_avail & !tx_fifo_empty & tx_queue_en ) begin
                tx_fifo_rd_en = 1;
                m_tx_axis_tvalid_nxt = 1;
                tx_mac_state_nxt = WAIT_FOR_READY;
            end
            WAIT_FOR_READY: begin
                m_tx_axis_tvalid_nxt = 1;
                if (m_tx_axis_tready) begin
                    tx_fifo_rd_en = 1;
                    tx_mac_state_nxt = WAIT_FOR_EOP;
                end
            end
            WAIT_FOR_EOP: begin
                m_tx_axis_tvalid_nxt = 1;
                if (|tx_fifo_out_ctrl) begin
                    m_tx_axis_tvalid_nxt = 0;
                    tx_mac_state_nxt = IDLE;
                    if (need_clear_padding) begin
                        tx_fifo_rd_en = 1;
                    end
                    else tx_fifo_rd_en = 0;
                end
                else if (m_tx_axis_tready) begin
                    tx_fifo_rd_en = 1;
                end
            end
        endcase
    end

    // output state machine keep/last
    always @* begin
        if (tx_mac_state == WAIT_FOR_READY || tx_mac_state == WAIT_FOR_EOP) begin
            case (tx_fifo_out_ctrl)
                4'b1000: begin 
                    m_tx_axis_tkeep = 4'b0001;
                    m_tx_axis_tlast = 1'b1;
                end
                4'b0100: begin
                    m_tx_axis_tkeep = 4'b0011;
                    m_tx_axis_tlast = 1'b1;
                end
                4'b0010: begin 
                    m_tx_axis_tkeep = 4'b0111;
                    m_tx_axis_tlast = 1'b1;
                end
                4'b0001: begin 
                    m_tx_axis_tkeep = 4'b1111;
                    m_tx_axis_tlast = 1'b1;
                end
                default: begin
                    m_tx_axis_tlast = 1'b0;
                    m_tx_axis_tkeep = 4'b1111;
                end
            endcase
        end
        else begin
            m_tx_axis_tkeep = 1'b0;
            m_tx_axis_tlast = 1'b0;
        end
    end

    // update sequential elements
    always @(posedge m_tx_axis_aclk) begin
        if (reset_txclk) begin
            tx_mac_state <= IDLE;
            m_tx_axis_tvalid <= 0;
            need_clear_padding <= 0;
        end
        else begin
            tx_mac_state <= tx_mac_state_nxt;
            m_tx_axis_tvalid <= m_tx_axis_tvalid_nxt;
            if (tx_fifo_rd_en) need_clear_padding <= !need_clear_padding;
        end
    end

    // check for available packets in the FIFO
    assign txf_pkts_avail = (txf_num_pkts_waiting != 'h0);

endmodule

