module HMAC (
  input [n-1:0] message,
  input [k-1:0] key,
  input hash_func,
  input op,
  output [h-1:0] hmac,
  output valid
);

parameter n = 64; // length of message
parameter k = 128; // length of key
parameter h = 256; // length of hash function output

// Define constants for padding
parameter constant_0x36 = 64'h3636363636363636;
parameter constant_0x5c = 64'h5c5c5c5c5c5c5c5c;

// Define variables for intermediate results
reg [h-1:0] inner_pad;
reg [h-1:0] outer_pad;
reg [h-1:0] inner_hash;
reg [h-1:0] outer_hash;

// Define signals for key padding
wire [k-1:0] padded_key;
wire [h-1:0] key_hash;

// Define signals for message padding
wire [n-1:0] padded_message;
wire [h-1:0] message_hash;

// Define signal for final HMAC
wire [h-1:0] final_hmac;

// Compute the hash of the key
hash_func key_hash_func(.data(key), .hash(key_hash));

// Pad the key if necessary
assign padded_key = (k > h) ? key_hash : {key, {k-h{1'b0}}};

// Compute the inner padding
assign inner_pad = padded_key ^ constant_0x36;

// Compute the outer padding
assign outer_pad = padded_key ^ constant_0x5c;

// Concatenate the inner padding with the message and compute the hash
assign padded_message = {message, {n-((n+k) % n){1'b0}}, k};
hash_func inner_hash_func(.data({inner_pad, padded_message}), .hash(inner_hash));

// Concatenate the outer padding with the inner hash and compute the hash
assign padded_outer = {outer_pad, inner_hash};
hash_func outer_hash_func(.data(padded_outer), .hash(outer_hash));

// Set the final HMAC
assign final_hmac = outer_hash;

// Generate or check the HMAC based on the op signal
always @(*) begin
  if (op == 0) begin
    hmac = final_hmac;
    valid = 1;
  end else begin
    if (final_hmac == hmac) begin
      valid = 1;
    end else begin
      valid = 0;
    end
  end
end

endmodule

