module clock_2 (
    clk,
    fast_clk,
    rst,
    en,
    sec,
    pm,
    io_seg,
    io_sel
);

input clk;
input fast_clk;
input rst;
input en;
output [7:0] sec;
reg [7:0] sec;
output [17:0] pm;
reg [17:0] pm;
output [7:0] io_seg;
wire [7:0] io_seg;
output [3:0] io_sel; // Digit select on IO Shield
wire [3:0] io_sel;

reg [3:0] count [0:6-1];
reg [1:0] i, j;

// CLOCK_DECODER
assign io_seg[0] = (((count[i+2][0] && (!count[i+2][1]) && (!count[i+2][2]) && (!count[i+2][3])) || ((!count[i+2][0]) && (!count[i+2][1]) && count[i+2][2]) || (count[i+2][1] && count[i+2][3])) != 0);
assign io_seg[1] = (((count[i+2][0] && (!count[i+2][1]) && count[i+2][2]) || ((!count[i+2][0]) && count[i+2][1] && count[i+2][2]) || (count[i+2][1] && count[i+2][3])) != 0);
assign io_seg[2] = ((((!count[i+2][0]) && count[i+2][1] && (!count[i+2][2])) || (count[i+2][2] && count[i+2][3])) != 0);
assign io_seg[3] = (((count[i+2][0] && (!count[i+2][1]) && (!count[i+2][2]) && (!count[i+2][3])) || (count[i+2][0] && count[i+2][1] && count[i+2][2]) || ((!count[i+2][0]) && (!count[i+2][1]) && count[i+2][2])) != 0);
assign io_seg[4] = ((count[i+2][0] || ((!count[i+2][1]) && count[i+2][2])) != 0);
assign io_seg[5] = (((count[i+2][0] && (!count[i+2][2]) && (!count[i+2][3])) || (count[i+2][0] && count[i+2][1]) || (count[i+2][1] && (!count[i+2][2]))) != 0);
assign io_seg[6] = (((count[i+2][0] && count[i+2][1] && count[i+2][2]) || ((!count[i+2][1]) && (!count[i+2][2]) && (!count[i+2][3]))) != 0);
assign io_seg[7] = 1'b1 && ~(~i[0] && i[1]);

// Select 7-segment display to show digit
assign io_sel[0] = ~(~i[0] && ~i[1]);
assign io_sel[1] = ~(i[0] && ~i[1]);
assign io_sel[2] = ~(~i[0] && i[1]);
assign io_sel[3] = ~(i[0] && i[1]) || (count[5] == 0);

always @(i) begin
    j = i + 1'b1;
end

always @(posedge fast_clk, negedge fast_clk) begin
    if (rst) begin
        i <= 1'b0;
    end else begin
        i <= j;
    end
end

always @(posedge clk, posedge rst) begin: CLOCK_COUNTER
    if (rst) begin
        count[0] <= 0;
        count[1] <= 0;
        count[2] <= 0;
        count[3] <= 0;
        count[4] <= 0;
    end else if (en) begin
        count[0] <= ((count[0] + 1) % 10);
        count[1] <= ((count[1] + (count[0] == 9)) % 6);
        count[2] <= ((count[2] + ((count[0] == 9) && (count[1] == 5))) % 10);
        count[3] <= ((count[3] + ((count[0] == 9) && (count[1] == 5) && (count[2] == 9))) % 6);
        count[4] <= (((count[4] + ((count[0] == 9) && (count[1] == 5) && (count[2] == 9) && (count[3] == 5))) % (10 - (7 * count[5]))) + ((count[0] == 9) && (count[1] == 5) && (count[2] == 9) && (count[3] == 5) && (count[4] == 2) && (count[5] != 0)));
    end
end

always @(posedge clk, posedge rst) begin: CLOCK_TFF
    if (rst) begin
        count[5] <= 0;
        pm <= 18'b0;
        sec <= 8'b0;
    end else if (en) begin
        count[5] <= ((count[5] != 0) ^ (((count[0] == 9) && (count[1] == 5) && (count[2] == 9) && (count[3] == 5) && (count[4] == 9)) || ((count[0] == 9) && (count[1] == 5) && (count[2] == 9) && (count[3] == 5) && (count[4] == 2) && (count[5] != 0))));
        pm <= {18{(pm[0] ^ ((count[0] == 9) && (count[1] == 5) && (count[2] == 9) && (count[3] == 5) && (count[4] == 1) && (count[5] != 0)))}};
        sec <= (count[0]+10*count[1]+1) % 60;
    end
end

endmodule

module ADT7310(Reset_n_i, Clk_i, Enable_i, CpuIntr_o, ADT7310CS_n_o, SPI_Data_i, SPI_Write_o, SPI_ReadNext_o, SPI_Data_o, SPI_FIFOFull_i, SPI_FIFOEmpty_i, SPI_Transmission_i, SPICounterPresetH_i, SPICounterPresetL_i, Threshold_i, PeriodCounterPreset_i, SensorValue_o, SPI_CPOL_o, SPI_CPHA_o, SPI_LSBFE_o);

  parameter PERIOD = 100; // clock period in ns

  input Reset_n_i;
  input Clk_i;
  input Enable_i;
  input [7:0] SPI_Data_i;
  input SPI_FIFOFull_i;
  input SPI_FIFOEmpty_i;
  input SPI_Transmission_i;
  input [15:0] SPICounterPresetH_i;
  input [15:0] SPICounterPresetL_i;
  input [15:0] Threshold_i;
  input [15:0] PeriodCounterPreset_i;

  output ADT7310CS_n_o;
  output CpuIntr_o;
  output [7:0] SPI_Data_o;
  output SPI_ReadNext_o;
  output [15:0] SensorValue_o;
  output SPI_CPOL_o;
  output SPI_CPHA_o;
  output SPI_LSBFE_o;

  wire [7:0] SPIFSM_Byte0_s;
  wire [7:0] SPIFSM_Byte1_s;
  wire SPIFSM_Done_s;
  wire SPIFSM_Start_s;

  assign ADT7310CS_n_o = 1'b1; // chip select is active low
  assign SPI_CPOL_o = 1'b1;
  assign SPI_CPHA_o = 1'b1; // mode 3
  assign SPI_LSBFE_o = 1'b0; // MSB first

  reg [7:0] SPI_Data_reg;
  reg [7:0] SPI_Data_out_reg;
  reg SPI_ReadNext_reg;
  reg [15:0] SensorValue_reg;
  reg [15:0] Threshold_reg;
  reg [15:0] PeriodCounter_reg;
  reg [15:0] SPICounterPreset_reg;
  reg [15:0] PeriodCounterPreset_reg;
  reg [15:0] SPICounter_reg;
  reg [15:0] MeasureFSM_Byte0_reg;
  reg [15:0] MeasureFSM_Byte1_reg;
  reg MeasureFSM_Done_reg;
  reg MeasureFSM_Start_reg;

  always @(posedge Clk_i) begin
    if (!Reset_n_i) begin
      SPI_Data_reg <= 8'h00;
      SPI_Data_out_reg <= 8'h00;
      SPI_ReadNext_reg <= 1'b0;
      SensorValue_reg <= 16'h0000;
      Threshold_reg <= Threshold_i;
      PeriodCounter_reg <= 16'h0000;
      SPICounterPreset_reg <= {SPICounterPresetH_i, SPICounterPresetL_i};
      PeriodCounterPreset_reg <= PeriodCounterPreset_i;
      SPICounter_reg <= 16'h0000;
      MeasureFSM_Byte0_reg <= 16'h0000;
      MeasureFSM_Byte1_reg <= 16'h0000;
      MeasureFSM_Done_reg <= 1'b0;
      MeasureFSM_Start_reg <= 1'b0;
    end else begin
      SPI_Data_reg <= SPI_Data_i;
      SPI_Data_out_reg <= SPI_Data_reg;
      SPI_ReadNext_reg <= SPI_Transmission_i;
      if (SPI_ReadNext_i) begin
        SPI_Data_out_reg <= 8'h00;
      end
      if (SPI_Transmission_i) begin
        if (!SPI_FIFOEmpty_i) begin
          SPI_Data_out_reg <= SPI_Data_reg;
        end
      end
      SensorValue_reg <= SensorValue_o;
      Threshold_reg <= Threshold_i;
      PeriodCounter_reg <= PeriodCounter_reg + 1;
      SPICounterPreset_reg <= {SPICounterPresetH_i, SPICounterPresetL_i};
      PeriodCounterPreset_reg <= PeriodCounterPreset_i;
      SPICounter_reg <= SPICounter_reg + 1;
      MeasureFSM_Byte0_reg <= SPIFSM_Byte0_s;
      MeasureFSM_Byte1_reg <= SPIFSM_Byte1_s;
      MeasureFSM_Done_reg <= SPIFSM_Done_s;
      MeasureFSM_Start_reg <= SPIFSM_Start_s;
    end
  end

  assign SPI_Data_o = SPI_Data_out_reg;
  assign SPI_ReadNext_o = SPI_ReadNext_reg;

  // SPI FSM
  SPIFSM #(.SPPRWidth(4), .SPRWidth(4), .DataWidth(8)) SPIFSM_1 (
    .ADT7310CS_n_o(ADT7310CS_n_o),
    .Byte0_o(SPIFSM_Byte0_s),
    .Byte1_o(SPIFSM_Byte1_s),
    .Clk_i(Clk_i),
    .Done_o(SPIFSM_Done_s),
    .ParamCounterPreset_i(SPICounterPreset_reg),
    .Reset_n_i(Reset_n_i),
    .SPI_Data_i(SPI_Data_i),
    .SPI_Data_o(SPI_Data_out_reg),
    .SPI_FIFOEmpty_i(SPI_FIFOEmpty_i),
    .SPI_FIFOFull_i(SPI_FIFOFull_i),
    .SPI_ReadNext_o(SPI_ReadNext_reg),
    .SPI_Transmission_i(SPI_Transmission_i),
    .SPI_Write_o(SPI_Write_o),
    .Start_i(SPIFSM_Start_s)
  );

  // Sensor FSM
  SensorFSM SensorFSM_1 (
    .Clk_i(Clk_i),
    .CpuIntr_o(CpuIntr_o),
    .Enable_i(Enable_i),
    .MeasureFSM_Byte0_i(MeasureFSM_Byte0_reg),
    .MeasureFSM_Byte1_i(MeasureFSM_Byte1_reg),
    .MeasureFSM_Done_i(MeasureFSM_Done_reg),
    .MeasureFSM_Start_o(MeasureFSM_Start_reg),
    .ParamCounterPreset_i(PeriodCounterPreset_reg),
    .ParamThreshold_i(Threshold_reg),
    .Reset_n_i(Reset_n_i),
    .SensorValue_o(SensorValue_o)
  );

  // Period counter
  always @(posedge Clk_i) begin
    if (!Reset_n_i) begin
      PeriodCounter_reg <= 16'h0000;
    end else begin
      if (PeriodCounter_reg == PeriodCounterPreset_reg) begin
        PeriodCounter_reg <= 16'h0000;
      end else begin
        PeriodCounter_reg <= PeriodCounter_reg + 1;
      end
    end
  end

endmodule

module bw_io_ddr_pad_txrx(
