module register_interface
      (tx_timeout, reg_req, reg_rd_wr_L, reg_addr, reg_wr_data, reg_rd_data, reg_ack, reset, clk);

   // -------------- Inputs -------------------
   input  tx_timeout;
   input  reg_req;
   input  reg_rd_wr_L;
   input  [4:0] reg_addr;
   input  [31:0] reg_wr_data;
   input  reset;
   input  clk;

   // -------------- Outputs ------------------
   output [31:0] reg_rd_data;
   output reg_ack;

   // -------------- Registers ----------------
   reg [31:0] register_file [31:0];
   reg [31:0] reg_rd_data_int;
   reg [31:0] timeout_counter;
   reg [1:0] state;
   reg [1:0] reg_op;

   // -------------- Constants ----------------
   localparam IDLE = 2'b00;
   localparam READ = 2'b01;
   localparam WRITE = 2'b10;

   // -------------- Logic --------------------
   always @(posedge clk or posedge reset) begin
      if (reset == 1'b1) begin
         state <= IDLE;
         reg_op <= READ;
         timeout_counter <= 0;
         reg_ack <= 1'b0;
         reg_rd_data_int <= 0;
      end
      else begin
         case (state)
            IDLE: begin
               if (reg_req == 1'b1) begin
                  if (reg_rd_wr_L == 1'b0) begin
                     state <= READ;
                  end
                  else begin
                     state <= WRITE;
                     register_file[reg_addr] <= reg_wr_data;
                  end
                  reg_op <= reg_rd_wr_L;
                  timeout_counter <= 0;
               end
            end
            READ: begin
               if (timeout_counter >= 10) begin
                  state <= IDLE;
                  reg_op <= READ;
                  timeout_counter <= 0;
                  reg_rd_data_int <= 0;
                  tx_timeout <= 1'b1;
                  reg_ack <= 1'b0;
               end
               else begin
                  if (reg_ack == 1'b1) begin
                     state <= IDLE;
                     reg_op <= READ;
                     timeout_counter <= 0;
                     reg_rd_data_int <= register_file[reg_addr];
                     tx_timeout <= 1'b0;
                     reg_ack <= 1'b0;
                  end
                  else begin
                     timeout_counter <= timeout_counter + 1;
                     reg_ack <= 1'b0;
                  end
               end
            end
            WRITE: begin
               if (timeout_counter >= 10) begin
                  state <= IDLE;
                  reg_op <= READ;
                  timeout_counter <= 0;
                  reg_rd_data_int <= 0;
                  tx_timeout <= 1'b1;
                  reg_ack <= 1'b0;
               end
               else begin
                  if (reg_ack == 1'b1) begin
                     state <= IDLE;
                     reg_op <= READ;
                     timeout_counter <= 0;
                     reg_rd_data_int <= 0;
                     tx_timeout <= 1'b0;
                     reg_ack <= 1'b0;
                  end
                  else begin
                     timeout_counter <= timeout_counter + 1;
                     reg_ack <= 1'b0;
                  end
               end
            end
         endcase
      end
   end

   assign reg_rd_data = reg_rd_data_int;

endmodule

