  output wire [3:0] m_axis_tkeep,
  output wire m_axis_tlast,
  output wire [31:0] axis_data_count,
  output wire [31:0] axis_wr_data_count,
  output wire [31:0] axis_rd_data_count
);

  localparam DEPTH = 256;
  localparam WIDTH = 32;
  localparam KEEP_WIDTH = 4;
  localparam ADDR_WIDTH = $clog2(DEPTH);

  reg [WIDTH-1:0] mem [DEPTH-1:0];
  reg [ADDR_WIDTH-1:0] wr_ptr;
  reg [ADDR_WIDTH-1:0] rd_ptr;
  reg [ADDR_WIDTH-1:0] data_count;
  reg [ADDR_WIDTH-1:0] wr_data_count;
  reg [ADDR_WIDTH-1:0] rd_data_count;

  reg [WIDTH-1:0] wr_data;
  reg [KEEP_WIDTH-1:0] wr_keep;
  reg wr_last;
  reg wr_valid;
  reg [WIDTH-1:0] rd_data;
  reg [KEEP_WIDTH-1:0] rd_keep;
  reg rd_last;
  reg rd_valid;

  reg [ADDR_WIDTH-1:0] next_wr_ptr;
  reg [ADDR_WIDTH-1:0] next_rd_ptr;
  reg [ADDR_WIDTH-1:0] next_data_count;
  reg [ADDR_WIDTH-1:0] next_wr_data_count;
  reg [ADDR_WIDTH-1:0] next_rd_data_count;

  assign s_axis_tready = (data_count < DEPTH);

  always @(posedge s_axis_aclk) begin
    if (~s_axis_aresetn) begin
      wr_ptr <= 0;
      rd_ptr <= 0;
      data_count <= 0;
      wr_data_count <= 0;
      rd_data_count <= 0;
      wr_valid <= 0;
      rd_valid <= 0;
    end else begin
      wr_ptr <= next_wr_ptr;
      rd_ptr <= next_rd_ptr;
      data_count <= next_data_count;
      wr_data_count <= next_wr_data_count;
      rd_data_count <= next_rd_data_count;
      wr_valid <= s_axis_tvalid & s_axis_tready;
      rd_valid <= m_axis_tvalid & m_axis_tready;
    end
  end

  always @(*) begin
    next_wr_ptr = wr_ptr;
    next_rd_ptr = rd_ptr;
    next_data_count = data_count;
    next_wr_data_count = wr_data_count;
    next_rd_data_count = rd_data_count;

    if (wr_valid) begin
      next_wr_ptr = wr_ptr + 1;
      if (wr_ptr == DEPTH-1) begin
        next_wr_ptr = 0;
      end
      next_data_count = data_count + 1;
      next_wr_data_count = wr_data_count + 1;
      mem[wr_ptr] <= {wr_data, wr_keep};
      wr_last <= s_axis_tlast;
    end

    if (rd_valid) begin
      next_rd_ptr = rd_ptr + 1;
      if (rd_ptr == DEPTH-1) begin
        next_rd_ptr = 0;
      end
      next_data_count = data_count - 1;
      next_rd_data_count = rd_data_count + 1;
      {rd_data, rd_keep} <= mem[rd_ptr];
      rd_last <= (data_count == 1) & wr_last;
    end
  end

  assign m_axis_tdata = rd_data;
  assign m_axis_tkeep = rd_keep;
  assign m_axis_tlast = rd_last;
  assign m_axis_tvalid = rd_valid;
  assign axis_data_count = data_count;
  assign axis_wr_data_count = wr_data_count;
  assign axis_rd_data_count = rd_data_count;

endmodule

module analinput(clk, pay, pby, miso, mosi, cs, sck);
parameter PADDLESIZE = 0;
parameter SCREENHEIGHT = 0;
input clk;
output reg[9:0] pay;
output reg[9:0] pby;
input miso;
output reg mosi;
output reg cs;
output sck;

parameter state0 = 0, state1 = 1, state2 = 2, state3 = 3;

reg [1:0] state;

reg [4:0] sckcount;
reg [11:0] datain;

reg ab;

assign sck = clk;

always @(posedge sck) begin
	case(state)
	state0:
		begin
			ab <= 1;
			state <= state1;
		end
	state1: 
		begin
			ab <= !ab;
			cs <= 0;
			mosi <= !ab;
			sckcount <= 15;
			state <= state2;
		end
	state2:
		begin
			if (sckcount != 0) 
				sckcount <= sckcount - 1'b1;
			else 
				state <= state3;
		end
	state3:
		begin
			cs <= 1;
			mosi <= 0;
			if (ab == 0) begin
				pay <= paddlelimiter(datain[7:0], PADDLESIZE, SCREENHEIGHT);
			end else begin
				pby <= paddlelimiter(datain[10:8], PADDLESIZE, SCREENHEIGHT);
			end
			state <= state1;
		end
	default:
		state <= state0;
	endcase
end

always @(negedge sck) begin
	if (state == state2)
		datain <= (datain << 1) | miso; 
	else if (state == state1)
		datain <= 0;
end


