module vending_machine (
  input clk,
  input reset,
  input [1:0] button, // 2-bit input for product selection
  input [3:0] coin, // 4-bit input for coin insertion (5, 10, or 25 cents)
  output reg dispense, // 1-bit output to dispense the product
  output reg [3:0] return_coin, // 4-bit output to return the remaining money
  output reg [3:0] remaining_money // 4-bit output to display the remaining money
);

  reg [3:0] product_price; // 4-bit register to store the price of each product
  reg [3:0] total_money; // 4-bit register to store the total amount of money inserted
  reg [1:0] selected_product; // 2-bit register to store the selected product
  reg [3:0] remaining_change; // 4-bit register to store the remaining change

  parameter [3:0] PRICE_1 = 10; // Price of product 1
  parameter [3:0] PRICE_2 = 15; // Price of product 2
  parameter [3:0] PRICE_3 = 20; // Price of product 3
  parameter [3:0] PRICE_4 = 25; // Price of product 4

  // Assign product prices based on the selected product
  always @ (button) begin
    case (button)
      2'b00: product_price = PRICE_1;
      2'b01: product_price = PRICE_2;
      2'b10: product_price = PRICE_3;
      2'b11: product_price = PRICE_4;
    endcase
    selected_product = button;
  end

  // Calculate the total amount of money inserted
  always @ (coin) begin
    case (coin)
      4'b0001: total_money = total_money + 5;
      4'b0010: total_money = total_money + 10;
      4'b0100: total_money = total_money + 25;
      4'b0111: total_money = total_money + 10; // For testing purposes only
      default: total_money = total_money;
    endcase
  end

  // Dispense the product and calculate the remaining change
  always @ (posedge clk, posedge reset) begin
    if (reset) begin
      dispense <= 0;
      return_coin <= 0;
      remaining_money <= 0;
      total_money <= 0;
      remaining_change <= 0;
    end else begin
      if (total_money >= product_price) begin
        dispense <= 1;
        remaining_change <= total_money - product_price;
        remaining_money <= 0;
        case (selected_product)
          2'b00: return_coin <= remaining_change;
          2'b01: return_coin <= remaining_change;
          2'b10: return_coin <= remaining_change;
          2'b11: return_coin <= remaining_change;
        endcase
      end else begin
        dispense <= 0;
        remaining_change <= total_money;
        remaining_money <= product_price - total_money;
        return_coin <= 0;
      end
    end
  end

endmodule

module ClockMerger(
    input wire Clock1,
    input wire Clock2,
    input wire Clock3,
    input wire Reset,
    output reg ClockOut
);

reg [1:0] currentClock;
reg [1:0] nextClock;

always @(posedge Clock1 or posedge Clock2 or posedge Clock3) begin
    if (Reset) begin
        currentClock <= 2'b00;
        nextClock <= 2'b00;
        ClockOut <= 1'b0;
    end else begin
        currentClock <= nextClock;
        if (Clock1) nextClock[0] <= 1'b1;
        if (Clock2) nextClock[1] <= 1'b1;
        if (Clock3) nextClock <= 2'b11;
        if (nextClock == 2'b00) ClockOut <= Clock1;
        else if (nextClock == 2'b01) ClockOut <= Clock2;
        else if (nextClock == 2'b10 || nextClock == 2'b11) ClockOut <= Clock3;
    end
end

endmodule

