module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               ctrl        ,
    input               valid_a     ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out
);

// Define the states of the state machine
parameter IDLE = 2'b00;
parameter ACCUMULATE = 2'b01;

// Define the signals used in the state machine
reg [1:0] state, next_state;
reg [9:0] accum;

// Define the valid-ready handshake signals
reg valid_b_int, ready_a_int;
wire valid_a_int, ready_b_int;

// Instantiate the valid-ready handshake module
valid_ready_handshake vrs(
    .clk(clk),
    .rst_n(rst_n),
    .valid_in(valid_a),
    .ready_out(ready_a_int),
    .valid_out(valid_b_int),
    .ready_in(ready_b_int)
);

// Define the state machine
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        accum <= 0;
    end else begin
        state <= next_state;
        case (state)
            IDLE: begin
                if (valid_a_int && ready_b_int && ctrl) begin
                    next_state <= ACCUMULATE;
                end else begin
                    next_state <= IDLE;
                end
            end
            ACCUMULATE: begin
                if (valid_a_int && ready_b_int && ctrl) begin
                    next_state <= ACCUMULATE;
                    accum <= accum + data_in;
                end else begin
                    next_state <= IDLE;
                end
            end
        endcase
    end
end

// Define the output data and valid signals
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        valid_b <= 0;
        data_out <= 0;
    end else begin
        valid_b <= valid_b_int;
        data_out <= accum;
    end
end

// Define the output ready signal
assign ready_a = ready_a_int;

endmodule

// Define the valid-ready handshake module
module valid_ready_handshake(
    input               clk         ,
    input               rst_n       ,
    input               valid_in    ,
    output  reg         ready_out   ,
    output  reg         valid_out   ,
    input               ready_in
);

// Define the state machine
reg [1:0] state, next_state;

// Define the signals used in the state machine
reg ready_out_int;
wire ready_in_int;

// Instantiate the D flip-flops
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= 2'b00;
        ready_out_int <= 1'b0;
    end else begin
        state <= next_state;
        case (state)
            2'b00: begin
                if (valid_in) begin
                    next_state <= 2'b01;
                    ready_out_int <= 1'b1;
                end else begin
                    next_state <= 2'b00;
                    ready_out_int <= 1'b0;
                end
            end
            2'b01: begin
                if (ready_in_int) begin
                    next_state <= 2'b00;
                    ready_out_int <= 1'b0;
                end else begin
                    next_state <= 2'b01;
                    ready_out_int <= 1'b1;
                end
            end
        endcase
    end
end

// Define the output signals
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        valid_out <= 0;
        ready_out <= 0;
    end else begin
        valid_out <= valid_in;
        ready_out <= ready_out_int;
    end
end

// Define the input signals
assign ready_in_int = ready_in;

endmodule

