module barrel_shifter (
    input [3:0] data_in,
    input [1:0] shift_amount,
    input mode,
    output reg [3:0] data_out
);

reg [3:0] shift_reg1, shift_reg2, shift_reg3;

always @(*) begin
    shift_reg1 = data_in;
    shift_reg2 = shift_reg1 >> shift_amount;
    shift_reg3 = shift_reg1 << shift_amount;
end

always @(posedge mode) begin
    if (mode == 1'b0) begin
        data_out <= shift_reg2;
    end else begin
        data_out <= shift_reg3;
    end
end

endmodule

module fifo(
    input aclr,
    input [39:0] data,
    input rdclk,
    input rdreq,
    input wrclk,
    input wrreq,
    output [39:0] q,
    output rdempty,
    output [4:0] rdusedw,
    output wrfull,
    output [4:0] wrusedw
    );

    parameter WIDTH = 40;
    parameter DEPTH = 32;
    parameter ADDR_WIDTH = 5;

    reg [WIDTH-1:0] mem [0:DEPTH-1];
    reg [ADDR_WIDTH-1:0] wr_ptr;
    reg [ADDR_WIDTH-1:0] rd_ptr;
    reg [ADDR_WIDTH-1:0] usedw;
    wire full = (usedw == DEPTH);
    wire empty = (usedw == 0);

    assign wrfull = full;
    assign rdempty = empty;
    assign wrusedw = usedw;
    assign rdusedw = usedw;

    always @(posedge wrclk or negedge aclr) begin
        if (~aclr) begin
            wr_ptr <= 0;
            usedw <= 0;
        end else if (wrreq && ~full) begin
            mem[wr_ptr] <= data;
            wr_ptr <= wr_ptr + 1;
            usedw <= usedw + 1;
        end
    end

    always @(posedge rdclk or negedge aclr) begin
        if (~aclr) begin
            rd_ptr <= 0;
            usedw <= 0;
        end else if (rdreq && ~empty) begin
            q <= mem[rd_ptr];
            rd_ptr <= rd_ptr + 1;
            usedw <= usedw - 1;
        end
    end
endmodule

