module ripple_carry_adder (
    a,
    b,
    en,
    sum,
    carry
);

    input [3:0] a;
    input [3:0] b;
    input en;
    output [3:0] sum;
    output carry;

    wire [3:0] temp_sum;
    wire [3:0] temp_carry;

    assign temp_sum = a + b;
    assign temp_carry = {a[3], b[3], temp_sum[3]} & 3'b100;

    assign sum = en ? temp_sum : 4'b0000;
    assign carry = en ? temp_carry[2] : 1'b0;

endmodule

module main ;

reg [3:0] value1,value2,value3;

initial begin
    #0;
    value3 = 0;
    #3 ;					// t=3
    value1 = 4'b0000 ;	// Picked up at time 4
    #5 ;				    // check at time 8
    if(value2 != 4'b0) begin
        $display("FAILED - always3.1.6A - case 0 at %t",$time);
        value3 = 1;
    end
    #1 ;					// Picked up at time 10
    value1 = 4'b0001 ;	// Set at time 9.

    #5 ;					// Check at time 14
    if(value2 != 4'b0001) begin
        $display("FAILED - always3.1.6A - case 1 at %t",$time);
        value3 = 1;
    end
    #1;					// Picked up at time 16
    value1 = 4'b0010;	// Changed at time 15.

    #5;					// Check at time 20...
    if(value2 != 4'b0010) begin
        $display("FAILED - always3.1.6A - case 2 at %t",$time);
        value3 = 1;
    end

    #3;                    // Picked up at time 23
    if(value1 == 4'b0011) begin
        #3;
        value2 = 4'b1010;
        #3;
    end

    #5;					// Check at time 26...
    if(value2 != 4'b1010) begin
        $display("FAILED - case 3 at %t",$time);
        value3 = 1;
    end

    #10;
    if(value3 == 0) begin
        $display("PASSED");
    end
    $finish;
end

always case (value1)
    4'b0000: begin
        #3 ;
        value2 = 4'b0000 ;
        #3 ;
    end
    4'b0001: begin
        #3 ;
        value2 = 4'b0001 ;
        #3 ;
    end
    4'b0010: begin
        #3 ;
        value2 = 4'b0010 ;
