module control_logic (
    input [1:0] select,
    input [31:0] a,
    input [31:0] b,
    output [31:0] result
);

    wire [31:0] sum;
    wire [31:0] diff;

    adder add_inst (
        .a(a),
        .b(b),
        .sum(sum)
    );

    subtractor sub_inst (
        .a(a),
        .b(b),
        .diff(diff)
    );

    always @(*) begin
        case (select)
            2'b00: result = sum;
            2'b01: result = diff;
            2'b10: result = a1 + b1;
            2'b11: result = a2 - b2;
        endcase
    end

endmodule

