module barrel_shifter (
    input [3:0] DIN,
    input [1:0] SHIFT,
    output reg [3:0] DOUT
);

reg [3:0] stage1_out;
reg [3:0] stage2_out;
reg [3:0] stage3_out;

always @(*) begin
    stage1_out = DIN;
end

always @(posedge clk) begin
    stage2_out <= stage1_out << 1;
end

always @(posedge clk) begin
    stage3_out <= stage2_out << 1;
end

always @(posedge clk) begin
    case(SHIFT)
        2'b00: DOUT <= stage1_out;
        2'b01: DOUT <= stage2_out;
        2'b10: DOUT <= stage3_out;
        2'b11: DOUT <= {stage3_out[1:0], stage1_out[3:2]};
    endcase
end

endmodule

