reg [7:0] b_reg;

always @(posedge clk) begin
    if (rst) begin
        a_reg <= 8'h00;
        b_reg <= 8'h00;
        result <= 16'h0000;
    end else begin
        a_reg <= a;
        b_reg <= b;
        result <= {8'h00, a_reg} * {8'h00, b_reg};
    end
end

endmodule

module counter(CLK, RSTN, UP_ENABLE, UP_ENABLE2, CLEAR, now);
  input CLK, RSTN, UP_ENABLE, UP_ENABLE2, CLEAR;
  output reg now;

  reg [2:0] up_cnt;
  wire is_cnt_four = up_cnt == 4;

  always @(posedge CLK or negedge RSTN) begin
    if(!RSTN) begin
      up_cnt <= 0;
    end else if(up_cnt >= 3'd5) begin
      up_cnt <= 0;
    end else if(CLEAR) begin
      up_cnt <= 0;
    end else if(UP_ENABLE) begin
      up_cnt <= up_cnt + 3'd1;
    end else if(UP_ENABLE2) begin
      up_cnt <= up_cnt + 3'd1;
    end else begin
      up_cnt <= up_cnt;
    end
  end

  reg [2:0] up_cnt2;
  always @(posedge CLK or negedge RSTN) begin
    if(!RSTN) begin
      up_cnt2 <= 0;
    end else if(up_cnt2 != 3'd5 && up_cnt == 3'd5) begin
      up_cnt2 <= up_cnt2 + 3'd1;
    end else begin
      up_cnt2 <= 0;
    end
  end

  reg [2:0] down_cnt;
  always @(posedge CLK or negedge RSTN) begin
    if(!RSTN) begin
      down_cnt <= 0;
    end else if(down_cnt != 3'd0) begin
      down_cnt <= down_cnt - 3'd1;
    end else begin
      down_cnt <= 3'd5;
    end
  end

  always @(posedge CLK or negedge RSTN) begin
    if(!RSTN) begin
      now <= 0;
    end else if(up_cnt == 3'd4) begin
      now <= 0;
    end else if(up_cnt == 3'd2) begin
      now <= 1;
    end else if((up_cnt == 2) && (up_cnt2 == 2)) begin
      now <= 1;
    end
  end

endmodule

module bit_counter (
    input CLK,
    input RST,
    input [31:0] data_in,
    output reg [4:0] count_set_bits
);

    reg [31:0] shift_reg;
    integer i;

    always @(posedge CLK or negedge RST) begin
        if (RST == 0) begin
            shift_reg <= 0;
            count_set_bits <= 0;
        end
        else begin
            shift_reg <= data_in;
            count_set_bits <= 0;
            for (i = 0; i < 32; i = i + 1) begin
                if (shift_reg[i] == 1) begin
                    count_set_bits <= count_set_bits + 1;
                end
            end
        end
    end

endmodule

module comparator (
    input [3:0] A,
    input [3:0] B,
    output EQ,
    output GT,
    output LT
);

reg [3:0] A_reg;
reg [3:0] B_reg;
reg [1:0] stage;

assign EQ = (A_reg == B_reg);
assign GT = (A_reg > B_reg);
assign LT = (A_reg < B_reg);

always @(*) begin
    case(stage)
        0: begin
            A_reg = A;
            B_reg = B;
        end
        1: begin
            A_reg = A_reg;
            B_reg = B_reg;
        end
    endcase
end

always @(posedge clk) begin
    if (stage == 1) begin
