module manchester (
  input clk,
  input in,
  input th,
  output out_m,
  output out_d
);

// Parameters
parameter CLK_PERIOD = 10; // Clock period in ns
parameter THRESHOLD = 0.5; // Threshold voltage

// Internal signals
reg prev_clk = 0;
reg encoded_bit = 0;
reg decoded_bit = 0;
reg prev_in = 0;

// Manchester encoding
always @(posedge clk) begin
  if (prev_clk == 0) begin
    if (in > THRESHOLD) begin
      encoded_bit <= 1;
    end else begin
      encoded_bit <= 0;
    end
  end else begin
    if (in > THRESHOLD) begin
      encoded_bit <= 0;
    end else begin
      encoded_bit <= 1;
    end
  end
  prev_clk <= clk;
end

// Manchester decoding
always @(posedge clk) begin
  if (prev_clk == 0) begin
    if (encoded_bit == 1) begin
      decoded_bit <= ~prev_in;
    end else begin
      decoded_bit <= prev_in;
    end
  end else begin
    if (encoded_bit == 0) begin
      decoded_bit <= ~prev_in;
    end else begin
      decoded_bit <= prev_in;
    end
  end
  prev_in <= decoded_bit;
  prev_clk <= clk;
end

// Output signals
assign out_m = encoded_bit;
assign out_d = decoded_bit;

endmodule

