module IR_comm_block (
  input clk,
  input data_in,
  input control,
  output reg data_out
);

parameter n = 8; // number of bits in the data signal

// Transmitter circuit
reg [n-1:0] data_out_reg; // register to store the data to be transmitted
reg tx_enable; // enable signal for the transmitter
reg tx_state; // state of the transmitter state machine
reg tx_bit_count; // counter for the number of bits transmitted
reg tx_pulse_count; // counter for the number of clock cycles in a pulse
reg tx_pulse_width; // width of the pulse in clock cycles
reg tx_data_bit; // current bit being transmitted

assign data_out = data_out_reg;

always @(posedge clk) begin
  if (control) begin // transmitting mode
    if (tx_enable) begin // transmitter is enabled
      case (tx_state)
        0: begin // idle state
          tx_pulse_count <= 0;
          tx_bit_count <= 0;
          tx_state <= 1;
        end
        1: begin // start bit
          tx_pulse_count <= tx_pulse_count + 1;
          if (tx_pulse_count == 1) begin
            tx_data_bit <= 0;
            tx_pulse_width <= 4; // start bit pulse width
          end else if (tx_pulse_count == tx_pulse_width) begin
            tx_pulse_count <= 0;
            tx_state <= 2;
          end
        end
        2: begin // data bits
          tx_pulse_count <= tx_pulse_count + 1;
          if (tx_pulse_count == 1) begin
            tx_data_bit <= data_out_reg[tx_bit_count];
            tx_pulse_width <= 2; // data bit pulse width
          end else if (tx_pulse_count == tx_pulse_width) begin
            tx_pulse_count <= 0;
            tx_bit_count <= tx_bit_count + 1;
            if (tx_bit_count == n) begin
              tx_state <= 3;
            end else begin
              tx_state <= 2;
            end
          end
        end
        3: begin // stop bit
          tx_pulse_count <= tx_pulse_count + 1;
          if (tx_pulse_count == 1) begin
            tx_data_bit <= 1;
            tx_pulse_width <= 4; // stop bit pulse width
          end else if (tx_pulse_count == tx_pulse_width) begin
            tx_pulse_count <= 0;
            tx_state <= 0;
            tx_enable <= 0;
          end
        end
      endcase
    end else begin // transmitter is disabled
      tx_state <= 0;
    end
  end else begin // receiving mode
    tx_state <= 0;
  end
end

// Receiver circuit
reg rx_enable; // enable signal for the receiver
reg rx_state; // state of the receiver state machine
reg rx_pulse_count; // counter for the number of clock cycles in a pulse
reg rx_pulse_width; // width of the pulse in clock cycles
reg [n-1:0] rx_data_reg; // register to store the received data
reg [n-1:0] rx_data_bit; // current bit being received
reg rx_bit_count; // counter for the number of bits received

always @(posedge clk) begin
  if (!control) begin // receiving mode
    if (rx_enable) begin // receiver is enabled
      case (rx_state)
        0: begin // idle state
          rx_pulse_count <= 0;
          rx_bit_count <= 0;
          rx_state <= 1;
        end
        1: begin // start bit
          rx_pulse_count <= rx_pulse_count + 1;
          if (rx_pulse_count == 1) begin
            rx_data_bit <= 0;
            rx_pulse_width <= 4; // start bit pulse width
          end else if (rx_pulse_count == rx_pulse_width) begin
            rx_pulse_count <= 0;
            rx_state <= 2;
          end
        end
        2: begin // data bits
          rx_pulse_count <= rx_pulse_count + 1;
          if (rx_pulse_count == 1) begin
            rx_data_bit <= data_in;
            rx_pulse_width <= 2; // data bit pulse width
          end else if (rx_pulse_count == rx_pulse_width) begin
            rx_pulse_count <= 0;
            rx_data_reg[rx_bit_count] <= rx_data_bit;
            rx_bit_count <= rx_bit_count + 1;
            if (rx_bit_count == n) begin
              rx_state <= 3;
            end else begin
              rx_state <= 2;
            end
          end
        end
        3: begin // stop bit
          rx_pulse_count <= rx_pulse_count + 1;
          if (rx_pulse_count == 1) begin
            rx_data_bit <= data_in;
            rx_pulse_width <= 4; // stop bit pulse width
          end else if (rx_pulse_count == rx_pulse_width) begin
            rx_pulse_count <= 0;
            rx_state <= 0;
            rx_enable <= 0;
            data_out_reg <= rx_data_reg;
          end
        end
      endcase
    end else begin // receiver is disabled
      rx_state <= 0;
    end
  end else begin // transmitting mode
    rx_state <= 0;
  end
end

// Control logic
always @(posedge clk) begin
  if (control) begin // transmitting mode
    rx_enable <= 0;
    if (!tx_enable) begin // start transmitting
      tx_enable <= 1;
      tx_state <= 0;
      tx_bit_count <= 0;
      tx_pulse_count <= 0;
      data_out_reg <= data_in;
    end
  end else begin // receiving mode
    tx_enable <= 0;
    if (!rx_enable) begin // start receiving
      rx_enable <= 1;
      rx_state <= 0;
      rx_bit_count <= 0;
      rx_pulse_count <= 0;
    end
  end
end

endmodule

