module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    output [3:0] Y
);

    wire [3:0] sum;
    wire carry;

    // Full adder
    // Takes three inputs (a, b, and carry_in) and returns two outputs (sum and carry_out)
    // Implements the following logic:
    // sum = a ^ b ^ carry_in
    // carry_out = (a & b) | (a & carry_in) | (b & carry_in)
    // where ^ is the XOR operator and & is the AND operator
    // This is a basic verilog construct
    // The full adder is used to add the four bits of A and B to produce the four bits of Y
    // The carry output of each full adder is fed as the carry_in input to the next full adder
    // The carry output of the last full adder is the final carry output of the module
    // The sum output of each full adder is one of the four bits of the output Y
    // The four bits of Y are concatenated to form the final output
    // This is also a basic verilog construct
    // The following code implements the four-bit adder using four full adders
    // The full adders are instantiated using the module instance syntax

    full_adder fa0(.a(A[0]), .b(B[0]), .carry_in(1'b0), .sum(sum[0]), .carry(carry0));
    full_adder fa1(.a(A[1]), .b(B[1]), .carry_in(carry0), .sum(sum[1]), .carry(carry1));
    full_adder fa2(.a(A[2]), .b(B[2]), .carry_in(carry1), .sum(sum[2]), .carry(carry2));
    full_adder fa3(.a(A[3]), .b(B[3]), .carry_in(carry2), .sum(sum[3]), .carry(carry));

    assign Y = {sum[3], sum[2], sum[1], sum[0]};

endmodule

module full_adder(
    input a,
    input b,
    input carry_in,
    output sum,
    output carry_out
);

    assign sum = a ^ b ^ carry_in;
    assign carry_out = (a & b) | (a & carry_in) | (b & carry_in);

endmodule

module binary_splitter_and_multiplexer (
    input wire [15:0] in,
    input wire [2:0] select,
    output wire [7:0] final_output,
    output wire [2:0] outv,
    output wire o2,
    output wire o1,
    output wire o0,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo
);

    // Binary splitter
    assign out_hi = in[15:8];
    assign out_lo = in[7:0];

    // Barrel shifter
    reg [7:0] shifted_out;
    always @(*) begin
        case (select)
            3'b000: shifted_out = out_hi;
            3'b001: shifted_out = out_hi >> 1;
            3'b010: shifted_out = out_hi >> 2;
            3'b011: shifted_out = out_hi >> 3;
            3'b100: shifted_out = out_hi >> 4;
            3'b101: shifted_out = out_hi >> 5;
            3'b110: shifted_out = out_hi >> 6;
            3'b111: shifted_out = out_hi >> 7;
        endcase
    end

    // Multiplexer
    assign outv = select;
    assign o2 = select[2];
    assign o1 = select[1];
    assign o0 = select[0];

    // Final output
    assign final_output = {shifted_out, select};

endmodule

