module shift_register (in0, in1, in2, in3, d0, d1, d2, d3, load, clk, reset, out0, out1, out2, out3);

    input in0, in1, in2, in3, d0, d1, d2, d3, clk, reset, load;
    output out0, out1, out2, out3;

    wire out0205, out1211, out2217, out3223, n1, n2, n3, n4;

    // 4 D Flip-Flops
    DFFPOSX1 out3_reg (.D(out3223), .CLK(clk), .Q(out3));
    DFFPOSX1 out2_reg (.D(out2217), .CLK(clk), .Q(out2));
    DFFPOSX1 out1_reg (.D(out1211), .CLK(clk), .Q(out1));
    DFFPOSX1 out0_reg (.D(out0205), .CLK(clk), .Q(out0));

    // NOR gates and MUXes
    NOR2X1 U37 (.A(reset), .B(n1), .Y(out3223));
    MUX2X1 U38 (.B(in2), .A(in3), .S(load), .Y(n1));
    NOR2X1 U39 (.A(reset), .B(n2), .Y(out2217));
    MUX2X1 U40 (.B(in0), .A(in1), .S(load), .Y(n2));
    NOR2X1 U41 (.A(reset), .B(n3), .Y(out1211));
    MUX2X1 U42 (.B(in2), .A(in3), .S(load), .Y(n3));
    NOR2X1 U43 (.A(reset), .B(n4), .Y(out0205));
    MUX2X1 U44 (.B(in0), .A(in1), .S(load), .Y(n4));

    // Connect D Flip-Flops
    assign out3223 = n1;
    assign out2217 = n2;
    assign out1211 = n3;
    assign out0205 = n4;

    // Output
    assign out0 = out0_reg;
    assign out1 = out1_reg;
    assign out2 = out2_reg;
    assign out3 = out3_reg;

endmodule

module multiplier(
  input wire [7:0] a,
  input wire [7:0] b,
  output wire [15:0] p
);

  reg [15:0] A;
  reg [2:0] q0;
  reg [7:0] a_shifted;
  integer i;

  always @(*) begin
    A = 0;
    q0 = b[0:2];
    a_shifted = {a,1'b0};
    for (i = 0; i < 8; i = i + 1) begin
      case(q0)
        3'b001: A = A + a_shifted;
        3'b010: A = A - a_shifted;
        3'b011: A = A + (a_shifted << 1);
        3'b100: A = A - (a_shifted << 1);
      endcase
      A = A >> 1;
      q0 = {A[0],q0[2:1]};
    end
    p = A[15:0];
  end

endmodule

module Bit_Shifting_Operators (
  input [31:0] in,
