module memory_arbiter_block (
  input clk,
  input reset,
  input [3:0] mem_req,
  input [1:0] dev_id,
  input [7:0] mem_addr,
  output [3:0] mem_ack,
  output mem_grant,
  output [1:0] mem_sel
);

  // Internal signals
  reg [3:0] req_queue [0:3];
  reg [3:0] req_queue_head;
  reg [3:0] req_queue_tail;
  reg [1:0] grant_dev_id;
  reg [3:0] grant_req_id;
  reg [1:0] round_robin_counter;
  reg [1:0] last_grant_dev_id;
  reg [3:0] last_grant_req_id;
  reg [1:0] last_round_robin_counter;
  reg [1:0] mem_sel_reg;
  reg mem_grant_reg;

  // Initialize internal signals
  initial begin
    req_queue_head = 0;
    req_queue_tail = 0;
    grant_dev_id = 0;
    grant_req_id = 0;
    round_robin_counter = 0;
    last_grant_dev_id = 0;
    last_grant_req_id = 0;
    last_round_robin_counter = 0;
    mem_sel_reg = 0;
    mem_grant_reg = 0;
  end

  // Handle memory requests
  always @(posedge clk) begin
    if (reset) begin
      req_queue_head <= 0;
      req_queue_tail <= 0;
      grant_dev_id <= 0;
      grant_req_id <= 0;
      round_robin_counter <= 0;
      last_grant_dev_id <= 0;
      last_grant_req_id <= 0;
      last_round_robin_counter <= 0;
      mem_sel_reg <= 0;
      mem_grant_reg <= 0;
    end else begin
      // Check if memory is currently being accessed
      if (grant_dev_id != 0 && grant_req_id != 0) begin
        // Queue the request
        req_queue[req_queue_tail] <= mem_req;
        req_queue_tail <= (req_queue_tail + 1) % 4;
      end else begin
        // Grant access to the next device in the queue
        req_queue_head <= (req_queue_head + 1) % 4;
        grant_dev_id <= dev_id;
        grant_req_id <= req_queue[req_queue_head];
        last_grant_dev_id <= grant_dev_id;
        last_grant_req_id <= grant_req_id;
        last_round_robin_counter <= round_robin_counter;
        round_robin_counter <= (round_robin_counter + 1) % 4;
      end
    end
  end

  // Generate output signals
  always @(posedge clk) begin
    if (reset) begin
      mem_ack <= 0;
      mem_sel <= 0;
      mem_grant <= 0;
    end else begin
      // Update memory select signal
      mem_sel_reg <= (mem_sel_reg + 1) % 4;
      mem_sel <= mem_sel_reg;

      // Update memory acknowledge signals
      if (last_grant_dev_id != 0 && last_grant_req_id != 0) begin
        mem_ack[last_round_robin_counter] <= 0;
      end
      if (grant_dev_id != 0 && grant_req_id != 0) begin
        mem_ack[round_robin_counter] <= 1;
      end

      // Update memory grant signal
      if (grant_dev_id == dev_id && grant_req_id == mem_req) begin
        mem_grant_reg <= 1;
      end else begin
        mem_grant_reg <= 0;
      end
      mem_grant <= mem_grant_reg;
    end
  end

endmodule

