module pulse_generator (
  input clk, // clock signal
  input trig, // trigger signal
  output pulse // pulse signal
);

parameter t = 10; // duration of pulse for monostable pulse generator
parameter f = 1; // frequency of pulse train for astable pulse generator
parameter d = 0.5; // duty cycle of pulse train for astable pulse generator

// Monostable pulse generator
reg [31:0] counter;
reg pulse_reg;
wire pulse;
assign pulse = pulse_reg;

always @(posedge clk) begin
  if (trig) begin
    pulse_reg <= 1'b1;
    counter <= 0;
  end else if (counter < t) begin
    pulse_reg <= 1'b1;
    counter <= counter + 1;
  end else begin
    pulse_reg <= 1'b0;
  end
end

// Astable pulse generator
reg [31:0] counter_astable;
reg pulse_reg_astable;
wire pulse_astable;
assign pulse_astable = pulse_reg_astable;

always @(posedge clk) begin
  if (counter_astable < (f * 2) - 1) begin
    counter_astable <= counter_astable + 1;
  end else begin
    counter_astable <= 0;
  end

  if (counter_astable < (f * d * 2)) begin
    pulse_reg_astable <= 1'b1;
  end else begin
    pulse_reg_astable <= 1'b0;
  end
end

endmodule

module adder_4bit (
