module dummy_rx
  (input clk, input rst,
   input set_stb, input [7:0] set_addr, input [31:0] set_data,

   input [13:0] adc_a, input adc_ovf_a,
   input [13:0] adc_b, input adc_ovf_b,

   output [31:0] sample,
   input run,
   output strobe
   );

   wire [15:0] scale_i, scale_q;
   wire [31:0] phase_inc;
   reg [31:0]  phase;

   wire [23:0] i_decim, q_decim;
   wire [7:0]  decim_rate;

   setting_reg #(.my_addr(`DSP_CORE_RX_BASE+0)) sr_0
     (.clk(clk),.rst(rst),.strobe(set_stb),.addr(set_addr),
      .in(set_data),.out(phase_inc),.changed());

   setting_reg #(.my_addr(`DSP_CORE_RX_BASE+1)) sr_1
     (.clk(clk),.rst(rst),.strobe(set_stb),.addr(set_addr),
      .in(set_data),.out({scale_i,scale_q}),.changed());

   setting_reg #(.my_addr(`DSP_CORE_RX_BASE+2)) sr_2
     (.clk(clk),.rst(rst),.strobe(set_stb),.addr(set_addr),
      .in(set_data),.out(decim_rate),.changed());

   strobe_gen strobe_gen(.clock(clk),.reset(rst),.enable(run),.rate(decim_rate),
			 .strobe_in(1),.strobe(strobe) );

   reg [15:0] i_out, q_out;
   assign      sample = {i_out,q_out};

   always @(posedge clk)
     if(rst)
       i_out <= 0;
     else if(~run)
       i_out <= 0;
     else if(strobe)
       i_out <= i_out + 1;

   reg 	       run_d1;
   always @(posedge clk)
     if(rst)
       run_d1 <= 0;
     else
       run_d1 <= run;

   always @(posedge clk)
     if(rst)
       q_out <= 0;
     else if (run & ~run_d1)
       q_out <= q_out + 1;

   always @(posedge clk)
     if(rst)
       phase <= 0;
     else if(run)
       phase <= phase + phase_inc;

   wire [15:0] i_adc, q_adc;
   assign i_adc = adc_ovf_a ? 14'h3fff : adc_a;
   assign q_adc = adc_ovf_b ? 14'h3fff : adc_b;

   wire [31:0] i_scaled, q_scaled;
   assign i_scaled = i_adc * scale_i;
   assign q_scaled = q_adc * scale_q;

   wire [31:0] i_phase, q_phase;
   assign i_phase = i_scaled + phase;
   assign q_phase = q_scaled + phase + 16'h4000;

   assign i_decim = i_phase[23:0];
   assign q_decim = q_phase[23:0];

   assign i_out = i_decim[15:0];
   assign q_out = q_decim[15:0] - 16'h4000;

endmodule

module setting_reg
  #(parameter my_addr = 0)
  (input clk, input rst, input strobe, input [7:0] addr, input [31:0] in,
   output reg [31:0] out, output reg changed);

   reg [31:0] reg_file;

   always @(posedge clk)
     if(rst)
       reg_file <= 0;
     else if(strobe & (addr == my_addr))
       begin
         reg_file <= in;
         changed <= 1;
       end
     else
       changed <= 0;

   assign out = reg_file;

endmodule

module strobe_gen
  (input clock, input reset, input enable, input [7:0] rate,
   input strobe_in, output reg strobe);

   reg [7:0] counter;

   always @(posedge clock)
     if(reset)
       counter <= 0;
     else if(enable)
       begin
         if(counter == rate - 1)
           begin
             strobe <= strobe_in;
             counter <= 0;
           end
         else
           counter <= counter + 1;
       end
     else
       counter <= 0;

endmodule

module bus_fsm (
	output reg gnt,
	output reg [1:0] state,
	input dly,
	input done,
	input req,
	input clk,
	input rst_n
);

	// Define the states of the FSM
	parameter [1:0] IDLE = 2'b00,
					BBUSY = 2'b01,
					BWAIT = 2'b10,
					BFREE = 2'b11;

	// Declare the state and next state variables
	reg [1:0] state;
	reg [1:0] next;

	// Initialize the state and next state variables
	initial begin
		state <= IDLE;
		next <= IDLE;
	end

	// Assign the next state to the current state on the positive clock edge
	always @(posedge clk or negedge rst_n) begin
		if (!rst_n) begin
			state <= IDLE;
			next <= IDLE;
		end
		else begin
			state <= next;
		end
	end

	// Implement the FSM logic using a case statement
	always @* begin
		next = 2'bx;
		gnt = 1'b0;

		case (state)
			IDLE: begin
				if (req) begin
					next = BBUSY;
				end
				else begin
					next = IDLE;
				end
			end
			BBUSY: begin
				gnt = 1'b1;
				if (!done) begin
					next = BBUSY;
				end
				else begin
					if (dly) begin
						next = BWAIT;
					end
					else begin
						next = BFREE;
					end
				end
			end
			BWAIT: begin
				gnt = 1'b1;
				if (!dly) begin
					next = BFREE;
				end
				else begin
					next = BWAIT;
				end
			end
			BFREE: begin
				if (req) begin
					next = BBUSY;
				end
				else begin
					next = IDLE;
				end
			end
			default: begin
				next = IDLE;
			end
		endcase
	end

	// Initialize the outputs to avoid latches
	assign gnt = gnt;
	assign state = state;

endmodule

module up_counter_and_mux(
