  // TLATNTSCAX2TS latch
  TLATNTSCAX2TS latch ( .E(EN), .SE(TE), .CK(CLK), .ECK(ENCLK) );

  always @(posedge CLK) begin
    if (EN) begin
      // Shift register
      shift_reg[6] <= TE;
