module red_pitaya_pfd_block
#(
    parameter ISR = 0
)
(   input rstn_i,
    input clk_i, 

    input s1, //signal 1
    input s2, //signal 2

    output [14-1:0] integral_o
    );

reg l1; //s1 from last cycle
reg l2; //s2 from last cycle

wire e1;
wire e2;

reg [14+ISR-1:0] integral;

assign e1 = ( {s1,l1} == 2'b10 ) ? 1'b1 : 1'b0;
assign e2 = ( {s2,l2} == 2'b10 ) ? 1'b1 : 1'b0;

assign integral_o = integral[14+ISR-1:ISR];

always @(posedge clk_i) begin
    if (rstn_i == 1'b0) begin
        l1 <= 1'b0;
        l2 <= 1'b0;
        integral <= {(14+ISR){1'b0}};
    end
    else begin
        l1 <= s1;
        l2 <= s2;
        if (integral == {1'b0,{14+ISR-1{1'b1}}})  //auto-reset or positive saturation
            integral <= {INTBITS{1'b0}};
        else if (integral == {1'b1,{14+ISR-1{1'b0}}}) //auto-reset or negative saturation
            integral <= {INTBITS{1'b1}};
        //output signal is proportional to frequency difference of s1-s2
        else if ({e1,e2}==2'b10)
            integral <= integral + {{14+ISR-1{1'b0}},1'b1};
        else if ({e1,e2}==2'b01)  
            integral <= integral + {14+ISR{1'b1}};
    end   
end

endmodule

module WireDelay # (
  parameter Delay_g = 0,
  parameter Delay_rd = 0,
  parameter ERR_INSERT = "OFF"
)
(
  inout A,
  inout B,
  input reset,
  input phy_init_done
);

  reg A_r;
  reg B_r;
  reg B_inv ;
  reg line_en;

  reg B_nonX;

  assign A = A_r;
  assign B = B_r;

  always @ (*)
  begin
    if (B === 1'bx)
      B_nonX <= $random;
    else
      B_nonX <= B;
   end

  always@(*)
  begin
    if((B_nonX == 'b1) || (B_nonX == 'b0))
      B_inv <= #0 ~B_nonX ;
    else
      B_inv <= #0 'bz ;
   end

  always @(*) begin
    if (!reset) begin
      A_r <= 1'bz;
      B_r <= 1'bz;
      line_en <= 1'b0;
    end else begin
      if (line_en) begin
	B_r <= 1'bz;
	  if ((ERR_INSERT == "ON") & (phy_init_done))
            A_r <= #Delay_rd B_inv;
	  else
            A_r <= #Delay_rd B_nonX;
      end else begin
        B_r <= #Delay_g A;
	A_r <= 1'bz;
      end
    end
  end

  always @(A or B) begin
    if (!reset) begin
      line_en <= 1'b0;
    end else if (A !== A_r) begin
      line_en <= 1'b0;
    end else if (B_r !== B) begin
      line_en <= 1'b1;
    end else begin
      line_en <= line_en;
    end
  end
endmodule

module clk_generator (
  input clk_in,
  input [31:0] freq,
  input [31:0] duty_cycle,
  output reg clk_out
);

  reg [31:0] cycle_count;
  reg [31:0] half_cycle_count;
  reg [31:0] toggle_count;
  reg toggle;

  always @(posedge clk_in) begin
    cycle_count <= cycle_count + 1;
    if (cycle_count >= half_cycle_count) begin
      toggle <= ~toggle;
      toggle_count <= toggle_count + 1;
      if (toggle_count >= duty_cycle) begin
        toggle_count <= 0;
        toggle <= 1'b0;
      end
      else if (toggle_count >= half_cycle_count) begin
        toggle <= 1'b1;
      end
    end
  end

  always @(posedge clk_in) begin
    if (cycle_count >= half_cycle_count) begin
      cycle_count <= 0;
    end
  end

  always @(posedge clk_in) begin
    if (freq != 0) begin
      half_cycle_count <= clk_in / (2 * freq);
    end
  end

  always @(posedge clk_in) begin
    if (duty_cycle == 0) begin
      clk_out <= 1'b0;
    end
    else if (duty_cycle == 4294967295) begin
      clk_out <= 1'b1;
    end
    else begin
      clk_out <= toggle;
    end
  end

endmodule

module CDC_synchronizer (
  input data_in,
  input clk_in,
  output reg data_out,
  output reg clk_out
);

parameter N = 2; // frequency division factor

reg [N-1:0] counter;
reg clk_out_div;

always @(posedge clk_in) begin
  // implement two-stage synchronizer here
  data_out <= #1 data_in;
  data_out <= #1 data_out;
end

always @(posedge clk_in) begin
  // implement frequency divider here
  if (counter == N-1) begin
    counter <= 0;
    clk_out_div <= ~clk_out_div;
  end else begin
    counter <= counter + 1;
  end
end

assign clk_out = clk_out_div;

endmodule

module rotator_shift_register (
    input clk,                 // Clock for the rotator
    input load,                // Synchronous load for the rotator
    input [1:0] ena,           // Enable for the rotator
    input [99:0] data,         // Input data for the rotator
    input d,                   // Serial input for the shift register
    output reg [2:0] q         // Output from the functional module
);

    // Rotator module
    reg [99:0] rotator_out;
    always @(posedge clk) begin
        if (load) rotator_out <= data;
        else if (ena[1]) rotator_out <= {rotator_out[0], rotator_out[99:1]};
        else if (ena[0]) rotator_out <= {rotator_out[98:0], rotator_out[99]};
    end

    // Shift register module
    reg [2:0] shift_reg_out;
    reg [2:0] shift_reg_in;
    always @(posedge clk) begin
        shift_reg_in <= {shift_reg_in[1:0], d};
        shift_reg_out <= {shift_reg_out[1:0], shift_reg_in[2]};
    end

    // Functional module
    always @* begin
        q[0] = rotator_out[0] | shift_reg_out[0];
        q[1] = rotator_out[50] | shift_reg_out[1];
        q[2] = rotator_out[99] | shift_reg_out[2];
    end

endmodule

