module comparator (
  input [n-1:0] num1,
  input [n-1:0] num2,
  output greater,
  output equal,
  output less
);

parameter n = 8; // number of bits in each binary number

reg [n-1:0] diff;
wire [n-1:0] diff_abs;
wire [n-1:0] num1_abs;
wire [n-1:0] num2_abs;

assign diff_abs = (diff < 0) ? -diff : diff;
assign num1_abs = (num1 < 0) ? -num1 : num1;
assign num2_abs = (num2 < 0) ? -num2 : num2;

always @(*) begin
  diff = num1 - num2;
  if (diff == 0) begin
    greater = 0;
    equal = 1;
    less = 0;
  end else if (diff > 0) begin
    greater = 1;
    equal = 0;
    less = 0;
  end else begin
    greater = 0;
    equal = 0;
    less = 1;
  end
end

endmodule

module fifo_256x8(
  input wire clk,
  input wire rst,
  //Reading port
  output reg [7:0] data_out,
  output reg empty_out,
  input wire read_en,
  input wire rclk,
  //Writing port
  input wire [7:0] data_in,
  output reg full_out,
  input wire write_en,
  input wire wclk,
  //Clear
  input wire clear
);

  //Parameters
  parameter DATA_WIDTH = 8;
  parameter ADDRESS_WIDTH = 8;
  parameter FIFO_DEPTH = 256;

  //Addresses
  reg [ADDRESS_WIDTH-1:0] read_addr;
  reg [ADDRESS_WIDTH-1:0] write_addr;
  wire [ADDRESS_WIDTH-1:0] next_read_addr;
  wire [ADDRESS_WIDTH-1:0] next_write_addr;

  //Data
  reg [DATA_WIDTH-1:0] mem [0:FIFO_DEPTH-1];
  reg [DATA_WIDTH-1:0] data_out_reg;

  //Status
  reg full_reg;
  reg empty_reg;

  //Logic
  assign next_read_addr = read_en & ~empty_reg ? read_addr + 1 : read_addr;
  assign next_write_addr = write_en & ~full_reg ? write_addr + 1 : write_addr;

  //Gray counters
  gray_counter #(ADDRESS_WIDTH) gray_counter_read (.gray_count(next_read_addr), .enable(read_en), .clear(rst), .clk(rclk));
  gray_counter #(ADDRESS_WIDTH) gray_counter_write (.gray_count(next_write_addr), .enable(write_en), .clear(rst), .clk(wclk));

  //Reading port
  always @(posedge rclk) begin
    if (read_en && !empty_reg) begin
      data_out_reg <= mem[read_addr];
      read_addr <= next_read_addr;
    end
  end

  //Writing port
  always @(posedge wclk) begin
    if (write_en && !full_reg) begin
      mem[write_addr] <= data_in;
      write_addr <= next_write_addr;
    end
  end

  //Status
  always @(posedge clk) begin
    full_reg <= write_addr == next_read_addr;
    empty_reg <= write_addr == read_addr;
  end

  //Output
  always @(posedge clk) begin
    if (rst) begin
      data_out <= 0;
      empty_out <= 1;
      full_out <= 0;
      read_addr <= 0;
      write_addr <= 0;
      full_reg <= 0;
      empty_reg <= 1;
    end else begin
      data_out <= data_out_reg;
      empty_out <= empty_reg;
      full_out <= full_reg;
    end
  end

  //Clear
  always @(posedge clk) begin
    if (clear) begin
      read_addr <= 0;
      write_addr <= 0;
      full_reg <= 0;
      empty_reg <= 1;
    end
  end

endmodule

//Gray counter module
module gray_counter #(parameter WIDTH = 8) (
  output reg [WIDTH-1:0] gray_count,
  input wire enable,
  input wire clear,
  input wire clk
);

  //Registers
  reg [WIDTH-1:0] binary_count;
  reg [WIDTH-1:0] gray_count_reg;

  //Logic
  always @(posedge clk) begin
    if (clear) begin
      binary_count <= 0;
      gray_count_reg <= 0;
    end else if (enable) begin
      binary_count <= binary_count + 1;
      gray_count_reg <= binary_count ^ (binary_count >> 1);
    end
  end

  //Output
  assign gray_count = gray_count_reg;

endmodule

