module power_mgmt(
    input pck0, ck_1356meg, ck_1356megb,
    output pwr_lo, pwr_hi, pwr_oe1, pwr_oe2, pwr_oe3, pwr_oe4,
    input [7:0] adc_d,
    output adc_clk,
    input ssp_dout,
    output ssp_frame, ssp_din, ssp_clk,
    input cross_hi, cross_lo,
    output dbg,
    input [7:0] divisor
);

    // No logic, straight through.
    assign pwr_oe3 = 1'b0;
    assign pwr_oe1 = ssp_dout;
    assign pwr_oe2 = ssp_dout;
    assign pwr_oe4 = ssp_dout;
    assign ssp_clk = cross_lo;
    assign pwr_lo = 1'b0;
    assign pwr_hi = 1'b0;
    assign dbg = ssp_frame;

    // Divide the clock to be used for the ADC
    reg [7:0] pck_divider;
    reg clk_state;

    always @(posedge pck0) begin
        if (pck_divider == divisor[7:0]) begin
            pck_divider <= 8'd0;
            clk_state <= ~clk_state;
        end else begin
            pck_divider <= pck_divider + 1;
        end
    end

    assign adc_clk = ~clk_state;

    // Toggle the output with hysteresis
    //  Set to high if the ADC value is above 200
    //  Set to low if the ADC value is below 64
    reg is_high;
    reg is_low;
    reg output_state;

    always @(posedge pck0) begin
        if ((pck_divider == 8'd7) && !clk_state) begin
            is_high <= (adc_d >= 8'd191);
            is_low <= (adc_d <= 8'd64);
        end
    end

    always @(posedge is_high or posedge is_low) begin
        if (is_high) begin
            output_state <= 1'd1;
        end else if (is_low) begin
            output_state <= 1'd0;
        end
    end

    assign ssp_frame = output_state;

endmodule

module fifo_32in_32out_8kb
    (dout, empty, full, wr_data_count, rd_en, wr_en, rd_clk, wr_clk, din, rst);

    parameter WIDTH = 32;
    parameter DEPTH = 256;
    parameter ADDR_BITS = $clog2(DEPTH);
    parameter DATA_BITS = WIDTH;
    parameter ADDR_MASK = DEPTH-1;

    input rd_en, wr_en, rd_clk, wr_clk, rst;
    input [DATA_BITS-1:0] din;
    output [DATA_BITS-1:0] dout;
    output empty, full;
    output reg [1:0] wr_data_count;

    reg [ADDR_BITS-1:0] wr_ptr;
    reg [ADDR_BITS-1:0] rd_ptr;
    reg [DATA_BITS-1:0] mem [0:DEPTH-1];
    reg [1:0] data_count;
    wire [1:0] next_data_count;
    wire [1:0] next_wr_data_count;
    wire [1:0] next_rd_data_count;

    assign dout = mem[rd_ptr];
    assign empty = (data_count == 0);
    assign full = (data_count == DEPTH);

    always @(posedge wr_clk or posedge rst) begin
        if (rst) begin
            wr_ptr <= 0;
            wr_data_count <= 0;
        end
        else if (wr_en) begin
            mem[wr_ptr] <= din;
            wr_ptr <= wr_ptr + 1;
            wr_data_count <= next_wr_data_count;
        end
    end

    always @(posedge rd_clk or posedge rst) begin
        if (rst) begin
            rd_ptr <= 0;
            data_count <= 0;
        end
        else if (rd_en) begin
            rd_ptr <= rd_ptr + 1;
            data_count <= next_data_count;
        end
    end

    always @(*) begin
        next_data_count = data_count - rd_en + wr_en;
        next_wr_data_count = wr_data_count + wr_en - rd_en;
    end

    always @(posedge wr_clk or posedge rst) begin
        if (rst) begin
            data_count <= 0;
        end
        else if (wr_en) begin
            data_count <= next_rd_data_count;
        end
    end

endmodule

module calculator (
