module VAD (
  input signed [n-1:0] audio_in,
  output reg speech_detected
);

parameter n = 16; // number of audio samples per frame
parameter fs = 16000; // sampling frequency of the audio signal
parameter frame_len = 20; // frame length in milliseconds
parameter frame_shift = 10; // frame shift in milliseconds
parameter threshold = 1000; // threshold for speech detection

// Calculate the number of samples per frame
localparam samples_per_frame = (frame_len * fs) / 1000;

// Calculate the number of samples to shift between frames
localparam samples_per_shift = (frame_shift * fs) / 1000;

// Define a register to hold the STE value
reg signed [31:0] ste;

// Define a register to hold the sum of squared audio samples
reg signed [31:0] sum_squares;

// Define a counter to keep track of the number of samples in the current frame
reg [31:0] sample_count;

// Define a counter to keep track of the number of samples shifted
reg [31:0] shift_count;

// Define a flag to indicate whether speech has been detected in the current frame
reg speech_detected_frame;

// Define a flag to indicate whether speech has been detected in any frame
reg speech_detected_total;

// Define a state machine to control the frame segmentation and STE calculation
localparam IDLE = 2'b00;
localparam CALC_STE = 2'b01;
localparam DETECT_SPEECH = 2'b10;
reg [1:0] state = IDLE;

always @(posedge clk) begin
  case (state)
    IDLE: begin
      // Reset the counters and flags
      sample_count <= 0;
      shift_count <= 0;
      sum_squares <= 0;
      ste <= 0;
      speech_detected_frame <= 0;
      speech_detected_total <= 0;

      // Move to the next state
      state <= CALC_STE;
    end

    CALC_STE: begin
      // Add the squared value of the current sample to the sum of squares
      sum_squares <= sum_squares + (audio_in * audio_in);

      // Increment the sample count
      sample_count <= sample_count + 1;

      // If we have processed all the samples in the frame, calculate the STE and move to the next state
      if (sample_count == samples_per_frame) begin
        ste <= sum_squares / samples_per_frame;
        state <= DETECT_SPEECH;
      end

      // If we have processed enough samples to shift to the next frame, reset the counters and move to the next state
      else if (shift_count == samples_per_shift) begin
        sample_count <= 0;
        shift_count <= 0;
        sum_squares <= 0;
        state <= CALC_STE;
      end

      // Otherwise, increment the shift count and stay in the current state
      else begin
        shift_count <= shift_count + 1;
        state <= CALC_STE;
      end
    end

    DETECT_SPEECH: begin
      // If the STE is above the threshold, set the speech_detected_frame flag
      if (ste > threshold) begin
        speech_detected_frame <= 1;
      end

      // If speech has been detected in any frame, set the speech_detected_total flag
      if (speech_detected_frame == 1) begin
        speech_detected_total <= 1;
      end

      // Reset the speech_detected_frame flag and move to the next state
      speech_detected_frame <= 0;
      state <= IDLE;
    end
  endcase
end

// Set the speech_detected output to the speech_detected_total flag
assign speech_detected = speech_detected_total;

endmodule

