  in_port,
  reset_n,
  write_n,
  writedata,

  // outputs:
  irq,
  readdata
);

  output irq;
  output [31:0] readdata;
  input [1:0] address;
  input chipselect;
  input clk;
  input [3:0] in_port;
  input reset_n;
  input write_n;
  input [31:0] writedata;

  reg [3:0] edge_capture;
  reg [3:0] irq_mask;
  reg [3:0] d1_data_in;
  reg [3:0] d2_data_in;
  wire [3:0] data_in;
  wire [3:0] edge_detect;
  wire [3:0] read_mux_out;
  wire edge_capture_wr_strobe;

  assign read_mux_out = ({4{(address == 0)}} & data_in) |
                        ({4{(address == 2)}} & irq_mask) |
                        ({4{(address == 3)}} & edge_capture);

  always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
      readdata <= 0;
    end else if (chipselect) begin
      if (write_n) begin
        readdata <= read_mux_out;
      end else begin
        readdata <= 0;
      end
    end
  end

  assign data_in = in_port;
  always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
      irq_mask <= 0;
    end else if (chipselect && ~write_n && (address == 2)) begin
      irq_mask <= writedata[3:0];
    end
  end

  assign irq = |(edge_capture & irq_mask);
  assign edge_capture_wr_strobe = chipselect && ~write_n && (address == 3);
  always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
      edge_capture <= 0;
    end else if (edge_capture_wr_strobe && writedata[0]) begin
      edge_capture[0] <= 0;
    end else if (edge_detect[0]) begin
      edge_capture[0] <= -1;
    end
  end

  always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
      edge_capture <= 0;
    end else if (edge_capture_wr_strobe && writedata[1]) begin
      edge_capture[1] <= 0;
    end else if (edge_detect[1]) begin
      edge_capture[1] <= -1;
    end
  end

  always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
      edge_capture <= 0;
    end else if (edge_capture_wr_strobe && writedata[2]) begin
      edge_capture[2] <= 0;
    end else if (edge_detect[2]) begin
      edge_capture[2] <= -1;
    end
  end

  always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
      edge_capture <= 0;
    end else if (edge_capture_wr_strobe && writedata[3]) begin
      edge_capture[3] <= 0;
    end else if (edge_detect[3]) begin
      edge_capture[3] <= -1;
    end
  end

  always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
      d1_data_in <= 0;
      d2_data_in <= 0;
    end else begin
      d1_data_in <= data_in;
      d2_data_in <= d1_data_in;
    end
  end

  assign edge_detect = d1_data_in & ~d2_data_in;

endmodule

module mux_with_register (
    Q      ,
    Q_N    ,
    D      ,
    SCD    ,
    SCE    ,
    CLK    ,
    SET_B  ,
    RESET_B
);

    // Module ports
    output Q      ;
    output Q_N    ;
    input  D      ;
    input  SCD    ;
    input  SCE    ;
    input  CLK    ;
    input  SET_B  ;
    input  RESET_B;

    // Module supplies
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    // Local signals
    wire RESET          ;
    wire SET            ;
    wire buf_Q          ;
    reg  notifier       ;
    wire D_delayed      ;
    wire SCD_delayed    ;
    wire SCE_delayed    ;
    wire CLK_delayed    ;
    wire SET_B_delayed  ;
    wire RESET_B_delayed;
    wire mux_out        ;
    wire awake          ;
    wire cond0          ;
    wire cond1          ;
    wire condb          ;
    wire cond_D         ;
    wire cond_SCD       ;
    wire cond_SCE       ;

    //                                   Name       Output   Other arguments
    not                                  not0      (RESET  , RESET_B_delayed                                       );
    not                                  not1      (SET    , SET_B_delayed                                         );
    sky130_fd_sc_ls__udp_mux_2to1        mux_2to10 (mux_out, D_delayed, SCD_delayed, SCE_delayed                   );
    sky130_fd_sc_ls__udp_dff$NSR_pp$PG$N dff0      (buf_Q  , SET, RESET, CLK_delayed, mux_out, notifier, VPWR, VGND);
    assign awake = ( VPWR === 1'b1 );
    assign cond0 = ( awake && ( RESET_B_delayed === 1'b1 ) );
    assign cond1 = ( awake && ( SET_B_delayed === 1'b1 ) );
    assign condb = ( cond0 & cond1 );
    assign cond_D = ( ( SCE_delayed === 1'b0 ) && condb );
    assign cond_SCD = ( ( SCE_delayed === 1'b1 ) && condb );
    assign cond_SCE = ( ( D_delayed !== SCD_delayed ) && condb );
    buf                                  buf0      (Q      , buf_Q                                                 );
    not                                  not2      (Q_N    , buf_Q                                                 );

    // Delayed signals
    always @(posedge CLK) begin
        RESET_B_delayed <= RESET_B;
        SET_B_delayed <= SET_B;
        D_delayed <= D;
        SCD_delayed <= SCD;
        SCE_delayed <= SCE;
        CLK_delayed <= CLK;
    end

    // Delayed set and reset signals
    always @(posedge CLK) begin
        if (RESET_B_delayed == 1'b0) begin
            RESET <= 1'b1;
        end else if (cond0) begin
            RESET <= 1'b1;
        end else begin
            RESET <= 1'b0;
        end
        if (SET_B_delayed == 1'b0) begin
            SET <= 1'b1;
        end else if (cond1) begin
            SET <= 1'b1;
        end else begin
            SET <= 1'b0;
        end
    end

    // Delayed data select control
    always @(posedge CLK) begin
        if (cond_SCD) begin
            SCD_delayed <= SCD;
        end else begin
            SCD_delayed <= SCD_delayed;
        end
    end

    // Delayed select control for exclusive OR of input data and delayed data
    always @(posedge CLK) begin
        if (cond_SCE) begin
            SCE_delayed <= SCE;
        end else begin
            SCE_delayed <= SCE_delayed;
        end
    end

    // Delayed input data
    always @(posedge CLK) begin
        if (cond_D) begin
            D_delayed <= D;
        end else begin
            D_delayed <= D_delayed;
        end
    end

    // Delayed output data
    always @(posedge CLK) begin
        if (notifier == 1'b1) begin
            buf_Q <= mux_out;
        end else begin
            buf_Q <= buf_Q;
        end
    end

    // Notifier for delayed output data
    always @(posedge CLK) begin
        if (notifier == 1'b1) begin
            notifier <= 1'b0;
        end else begin
            notifier <= 1'b1;
        end
    end

    // 2-to-1 multiplexer
    always @(*) begin
        if (SCD_delayed == 1'b0) begin
            mux_out = D_delayed;
        end else begin
            mux_out = SCE_delayed ^ D_delayed;
        end
    end

    // Clock delay
    always @(posedge VPWR) begin
        CLK_delayed <= CLK;
    end

endmodule

