    );

    reg [WIDTH - 1:0] state;

    always @(posedge clk) begin
        if (rst) begin
            state <= 0;
        end
        else if (ce) begin
            state <= in;
        end
    end

    assign out = state;

endmodule

module top_module (
    input a, b, c, // Inputs to the 3-to-4 multiplexer 
    input [3:0] in, // Input to the 4-bit priority encoder
    input [1:0] ctrl, // Control signal for selecting inputs
    output w, x, y, z, // Outputs from the 3-to-4 multiplexer
    output reg pos1, pos0 // Binary output from the priority encoder split into two 1-bit outputs
);

wire [3:0] priority; // Output from the priority encoder

priority_encoder_4bit pe(in, priority); // Instantiate the 4-bit priority encoder

wire mux_out; // Output from the 3-to-4 multiplexer

mux_3to4 mux(a, b, c, mux_out); // Instantiate the 3-to-4 multiplexer

always @(*) begin
    case(ctrl)
        2'b00: begin // Select input a
            w = mux_out;
            x = 1'b0;
            y = 1'b0;
            z = 1'b0;
        end
        2'b01: begin // Select input b
            w = 1'b0;
            x = mux_out;
            y = 1'b0;
            z = 1'b0;
        end
        2'b10: begin // Select input c
            w = 1'b0;
            x = 1'b0;
            y = mux_out;
            z = 1'b0;
        end
        2'b11: begin // Select highest priority input from priority encoder
            case(priority)
                2'b00: begin // Select input a
                    w = mux_out;
                    x = 1'b0;
                    y = 1'b0;
                    z = 1'b0;
                end
                2'b01: begin // Select input b
                    w = 1'b0;
                    x = mux_out;
                    y = 1'b0;
                    z = 1'b0;
                end
                2'b10: begin // Select input c
                    w = 1'b0;
                    x = 1'b0;
                    y = mux_out;
                    z = 1'b0;
                end
                2'b11: begin // Select input in
                    w = 1'b0;
                    x = 1'b0;
                    y = 1'b0;
                    z = mux_out;
                end
            endcase
        end
    endcase
end

always @(priority) begin // Split the 2-bit binary output from the priority encoder into two 1-bit outputs
    case(priority)
        2'b00: begin
            pos1 = 1'b0;
            pos0 = 1'b0;
        end
        2'b01: begin
            pos1 = 1'b0;
            pos0 = 1'b1;
        end
        2'b10: begin
            pos1 = 1'b1;
            pos0 = 1'b0;
        end
        2'b11: begin
            pos1 = 1'b1;
            pos0 = 1'b1;
        end
    endcase
end

endmodule

