    if (reset) begin
        load <= 1'b0;
    end else begin
        load <= select ? 1'b0 : data_in[3];
    end
end

endmodule

module count_a;

reg [7:0] curr_char;
integer fd;
integer count;

initial begin
    fd = $fopen("data.txt", "r");
    if (fd == 0) begin
        $display("Error: could not open file");
        $finish;
    end
    count = 0;
    while (!$feof(fd)) begin
        curr_char = $fgetc(fd);
        if (curr_char == 97) begin // "a" in ASCII
            count = count + 1;
        end
    end
    $fclose(fd);
    $display("Total count of 'a's in the file: %d", count);
end

endmodule

