module byte_splitter (
    input [15:0] in,   // 16-bit input data
    input valid,       // Valid input signal
    output [7:0] out_hi,   // Upper byte output
    output [7:0] out_lo,   // Lower byte output
    output reg ready      // Ready output signal
);

    assign out_hi = in[15:8];
    assign out_lo = in[7:0];

    reg [1:0] state;
    always @(posedge valid) begin
        case (state)
            2'b00: begin
                state <= 2'b01;
                ready <= 1'b0;
            end
            2'b01: begin
                state <= 2'b10;
                ready <= 1'b1;
            end
            2'b10: begin
                state <= 2'b00;
                ready <= 1'b0;
            end
        endcase
    end

endmodule

module serial_accumulator (
    input [15:0] in,   // 16-bit input data
    input valid,       // Valid input signal
    input pause,       // Pause input signal
    output reg valid_out,  // Valid output signal
    output reg [9:0] data_out  // 10-bit accumulation result
);

    reg [3:0] count;
    reg [9:0] sum;

    always @(posedge valid) begin
        if (!pause) begin
            sum <= sum + in;
            count <= count + 1;
        end
    end

    always @(posedge valid) begin
        if (count == 4) begin
            data_out <= sum;
            sum <= 0;
            count <= 0;
            valid_out <= 1;
        end else begin
            valid_out <= 0;
        end
    end

endmodule

