    input select,          // Select input to choose between byte splitter and accumulator
    output [7:0] out_hi,   // Upper byte output from byte splitter
    output [7:0] out_lo,   // Lower byte output from byte splitter
    output reg valid_b,    // Valid output signal from accumulator
    output reg ready_a,    // Ready output signal for byte splitter
    output reg ready_b,    // Ready output signal for accumulator
    output [9:0] data_out  // 10-bit accumulation result from accumulator
);

    wire [7:0] byte_hi, byte_lo;
    wire [9:0] acc_data;
    wire acc_valid;

    byte_splitter splitter (.in(in), .valid(valid_a), .out_hi(byte_hi), .out_lo(byte_lo), .ready(ready_a));
    serial_accumulator accumulator (.in(in), .valid(valid_a), .pause(!ready_b), .valid_out(acc_valid), .data_out(acc_data));

    always @(posedge clk) begin
        if (reset) begin
            valid_b <= 0;
            ready_a <= 0;
            ready_b <= 0;
            data_out <= 0;
        end else begin
            case (select)
                1'b0: begin
                    out_hi <= byte_hi;
                    out_lo <= byte_lo;
                    ready_a <= 1;
                    ready_b <= 0;
                    valid_b <= 0;
                end
                1'b1: begin
                    out_hi <= 0;
                    out_lo <= 0;
                    ready_a <= 0;
                    ready_b <= !acc_valid;
                    valid_b <= acc_valid;
                    data_out <= acc_data;
                end
            endcase
        end
    end

endmodule

