module vending_machine(
  input clk,
  input rst,
  input [1:0] coin,
  input dispense,
  output reg product,
  output reg [1:0] change
);

  reg [5:0] total_amount;

  always @(posedge clk) begin
    if (rst == 1) begin
      total_amount <= 0;
      product <= 0;
      change <= 0;
    end else begin
      if (dispense == 1) begin
        total_amount <= total_amount + {1'b0, coin};
        if (total_amount >= 50) begin
          product <= 1;
          case (total_amount - 50)
            0: change <= 0;
            1: change <= 1;
            5: change <= 2;
            15: change <= 3;
          endcase
          total_amount <= total_amount - 50;
        end
      end
    end
  end

endmodule

module delay_module (
    input in,
    input [3:0] delay,
    output reg out
);

reg [3:0] counter;
reg [3:0] shift_reg;

always @(posedge clk) begin
    if (counter == delay) begin
        shift_reg <= {in, shift_reg[3:1]};
        out <= shift_reg[0];
    end
    else begin
        shift_reg <= {1'b0, shift_reg[3:1]};
        out <= 1'b0;
    end
    counter <= counter + 1;
end

endmodule

module small_fifo
    #(parameter WIDTH = 72,
      parameter MAX_DEPTH_BITS = 3,
      parameter PROG_FULL_THRESHOLD = 2**MAX_DEPTH_BITS - 1
      )
    (

     input [WIDTH-1:0] din,     // Data in
     input          wr_en,   // Write enable

     input          rd_en,   // Read the next word

     output reg [WIDTH-1:0]  dout,    // Data out
     output         full,
     output         nearly_full,
     output         prog_full,
     output         empty,

     input          reset,
     input          clk
     );


localparam MAX_DEPTH        = 2 ** MAX_DEPTH_BITS;

reg [WIDTH-1:0] queue [MAX_DEPTH - 1 : 0];
reg [MAX_DEPTH_BITS - 1 : 0] rd_ptr;
reg [MAX_DEPTH_BITS - 1 : 0] wr_ptr;
reg [MAX_DEPTH_BITS : 0] depth;

// Sample the data
always @(posedge clk)
   if (wr_en)
      queue[wr_ptr] <= din;

always@(posedge clk)
    if(reset)
        dout<=0;
    else if (rd_en)
        dout <=queue[rd_ptr];

always @(posedge clk)
begin
   if (reset) begin
      rd_ptr <= 'h0;
      wr_ptr <= 'h0;
      depth  <= 'h0;
   end
   else begin
      if (wr_en) wr_ptr <= wr_ptr + 'h1;
      if (rd_en) rd_ptr <= rd_ptr + 'h1;
      if (wr_en & ~rd_en) depth <= depth + 'h1;
      else if (~wr_en & rd_en) depth <=depth - 'h1;
   end
end

//assign dout = queue[rd_ptr];
assign full = depth == MAX_DEPTH;
assign prog_full = (depth >= PROG_FULL_THRESHOLD);
assign nearly_full = depth >= MAX_DEPTH-1;
assign empty = depth == 'h0;

// synthesis translate_off
always @(posedge clk)
begin
   if (wr_en && depth == MAX_DEPTH && !rd_en)
      $display($time, " ERROR: Attempt to write to full FIFO: %m");
   if (rd_en && depth == 'h0)
      $display($time, " ERROR: Attempt to read an empty FIFO: %m");
end
// synthesis translate_on

endmodule

