module aes_key_expand_128(clk, kld, key, wo_0, wo_1, wo_2, wo_3);
input		clk;
input		kld;
input	[127:0]	key;
output	[31:0]	wo_0, wo_1, wo_2, wo_3;

reg	[31:0]	w[3:0];
wire	[31:0]	tmp_w;
wire	[31:0]	subword;
wire	[31:0]	rcon;

assign wo_0 = w[0];
assign wo_1 = w[1];
assign wo_2 = w[2];
assign wo_3 = w[3];

// Key expansion
always @(posedge clk) begin
	if (kld) begin
		w[0] <= key[127:96];
		w[1] <= key[95:64];
		w[2] <= key[63:32];
		w[3] <= key[31:0];
	end else begin
		w[0] <= w[0]^subword^rcon;
		w[1] <= w[0]^w[1]^subword^rcon;
		w[2] <= w[0]^w[2]^w[1]^subword^rcon;
		w[3] <= w[0]^w[3]^w[2]^w[1]^subword^rcon;
	end
end

// Substitution using s-box
aes_sbox u0(	.a(tmp_w[23:16]), .d(subword[31:24]));
aes_sbox u1(	.a(tmp_w[15:8]), .d(subword[23:16]));
aes_sbox u2(	.a(tmp_w[7:0]), .d(subword[15:8]));
aes_sbox u3(	.a(tmp_w[31:24]), .d(subword[7:0]));

// Rcon calculation
aes_rcon r0(	.clk(clk), .kld(kld), .out(rcon));

endmodule

module fsm_module(
  input div_clock,
  input reset,
  output enable_cuenta,
  output write_enable,
  output write_value_reg_en,
  output read_value_reg_en,
  output led_write,
  output led_read,
  output [3:0] estado
);

  // Define the states of the FSM
  parameter STATE_0 = 0;
  parameter STATE_1 = 1;
  parameter STATE_2 = 2;
  parameter STATE_3 = 3;
  parameter STATE_4 = 4;

  // Define the current state of the FSM
  reg [3:0] state;

  // Set the initial state of the FSM
  initial begin
    state <= -1;
  end

  // Advance the FSM on the rising edge of div_clock or reset
  always @(posedge div_clock or posedge reset) begin
    if (reset) begin
      state <= -1;
    end else begin
      case (state)
        STATE_0: begin
          state <= STATE_1;
        end
        STATE_1: begin
          state <= STATE_2;
        end
        STATE_2: begin
          state <= STATE_3;
        end
        STATE_3: begin
          state <= STATE_4;
        end
        STATE_4: begin
          state <= STATE_0;
        end
        default: begin
          state <= STATE_0;
        end
      endcase
    end
  end

  // Define the outputs of the FSM
  assign estado = state;
  assign enable_cuenta = (state == STATE_4);
  assign write_enable = ~(state == STATE_1);
  assign write_value_reg_en = (state == STATE_1);
  assign read_value_reg_en = (state == STATE_3);
  assign led_write = (state == STATE_0) || (state == STATE_1) || (state == STATE_2);
  assign led_read = (state == STATE_3) || (state == STATE_4);

endmodule

