module vending_machine (
  input clk,
  input reset,
  input nickel,
  input dime,
  input quarter,
  output reg product_dispensed
);

  // Define state variables
  parameter IDLE = 2'b00;
  parameter WAITING = 2'b01;
  parameter DISPENSING = 2'b10;

  reg [1:0] state;
  reg [1:0] next_state;

  // Define input variables
  reg nickel_input;
  reg dime_input;
  reg quarter_input;

  // Define output variables
  reg dispense_product;
  reg return_change;

  // Define constants
  parameter PRICE = 2'b10;
  parameter NICKEL = 2'b01;
  parameter DIME = 2'b10;
  parameter QUARTER = 2'b11;

  // Define state transitions
  always @(posedge clk) begin
    if (reset) begin
      state <= IDLE;
    end else begin
      state <= next_state;
    end
  end

  // Define next state and output logic
  always @(*) begin
    // Default values
    next_state = state;
    dispense_product = 0;
    return_change = 0;

    case (state)
      IDLE: begin
        if (nickel) begin
          nickel_input = 1;
          next_state = WAITING;
        end else if (dime) begin
          dime_input = 1;
          next_state = WAITING;
        end else if (quarter) begin
          quarter_input = 1;
          next_state = WAITING;
        end
      end
      WAITING: begin
        if (nickel) begin
          nickel_input = 1;
        end else if (dime) begin
          dime_input = 1;
        end else if (quarter) begin
          quarter_input = 1;
        end

        if (nickel_input & dime_input & quarter_input) begin
          if (nickel_input + dime_input*2 + quarter_input*5 >= PRICE) begin
            dispense_product = 1;
            return_change = 1;
            next_state = DISPENSING;
          end else begin
            next_state = WAITING;
          end
        end
      end
      DISPENSING: begin
        dispense_product = 1;
        return_change = 1;
        next_state = IDLE;
      end
    endcase
  end

  // Assign output values
  always @(posedge clk) begin
    if (reset) begin
      product_dispensed <= 0;
    end else begin
      if (dispense_product) begin
        product_dispensed <= 1;
      end else begin
        product_dispensed <= 0;
      end
    end
  end

endmodule

