        P = P_reg;
    end

    always @(posedge clk) begin
        if (reset) begin
            P_reg <= 0;
            A_reg <= 0;
            B_reg <= 0;
            state <= 3'b000;
        end else begin
            case (state)
                3'b000: begin
                    if (B[0] == 1) begin
                        P_reg <= -A;
                    end else begin
                        P_reg <= A;
                    end
                    A_reg <= A;
                    B_reg <= B;
                    state <= 3'b001;
                end
                3'b001: begin
                    if (B[0] == 1 && B[1] == 0) begin
                        P_reg <= P_reg - (A_reg << 1);
                    end else if (B[0] == 0 && B[1] == 1) begin
                        P_reg <= P_reg + (A_reg << 1);
                    end
                    A_reg <= A_reg << 1;
                    B_reg <= B >> 1;
                    state <= 3'b010;
                end
                3'b010: begin
                    if (B[0] == 1) begin
                        P_reg <= P_reg - B_reg;
                    end else if (B[0] == 0) begin
                        P_reg <= P_reg + B_reg;
                    end
                    A_reg <= A_reg;
                    B_reg <= B_reg >> 1;
                    state <= 3'b011;
                end
                3'b011: begin
                    state <= 3'b000;
                end
            endcase
        end
    end

