module byte_transfer_FSM (
  clk,
  reset,

  write_in,
  byteenable_in,
  waitrequest_out,

  byteenable_out,
  waitrequest_in
);

  input clk;
  input reset;

  input write_in;
  input [127:0] byteenable_in;
  output wire waitrequest_out;

  output wire [127:0] byteenable_out; 
  input waitrequest_in;

  parameter Idle = 2'b00;
  parameter PartialLower = 2'b01;
  parameter FullLower = 2'b10;
  parameter PartialUpper = 2'b11;
  parameter FullUpper = 2'b100;
  parameter Wait = 2'b101;

  reg [2:0] state;
  wire partial_lower_half_transfer;
  wire full_lower_half_transfer;
  wire partial_upper_half_transfer;
  wire full_upper_half_transfer;
  wire full_word_transfer;
  wire advance_to_next_state;
  wire lower_enable;
  wire upper_enable;
  wire lower_stall;
  wire upper_stall;
  wire two_stage_transfer;

  always @ (posedge clk or posedge reset) begin
    if (reset) begin
      state <= Idle;
    end else begin
      case (state)
        Idle: begin
          if (partial_lower_half_transfer) begin
            state <= PartialLower;
          end
        end
        PartialLower: begin
          if (full_lower_half_transfer) begin
            state <= FullLower;
          end else if (partial_upper_half_transfer) begin
            state <= PartialUpper;
          end else if (waitrequest_in) begin
            state <= Wait;
          end
        end
        FullLower: begin
          if (partial_upper_half_transfer) begin
            state <= PartialUpper;
          end else if (waitrequest_in) begin
            state <= Wait;
          end else begin
            state <= Idle;
          end
        end
        PartialUpper: begin
          if (full_upper_half_transfer) begin
            state <= FullUpper;
          end else if (waitrequest_in) begin
            state <= Wait;
          end
        end
        FullUpper: begin
          state <= Idle;
        end
        Wait: begin
          if (!waitrequest_in) begin
            if (full_word_transfer) begin
              state <= Idle;
            end else if (two_stage_transfer) begin
              state <= PartialUpper;
            end else begin
              state <= PartialLower;
            end
          end
        end
      endcase
    end
  end

  assign partial_lower_half_transfer = (byteenable_in[63:0] != 0);
  assign full_lower_half_transfer = (byteenable_in[63:0] == 64'hFFFFFFFFFFFFFFFF);
  assign partial_upper_half_transfer = (byteenable_in[127:64] != 0);
  assign full_upper_half_transfer = (byteenable_in[127:64] == 64'hFFFFFFFFFFFFFFFF);
  assign full_word_transfer = (full_lower_half_transfer == 1) & (full_upper_half_transfer == 1);
  assign two_stage_transfer = (full_word_transfer == 0) & (partial_lower_half_transfer == 1) & (partial_upper_half_transfer == 1);

  assign advance_to_next_state = (two_stage_transfer == 1) & (lower_stall == 0) & (write_in == 1) & (state == PartialLower) & (waitrequest_in == 0);

  assign lower_enable = ((write_in == 1) & (full_word_transfer == 1)) |  
                        ((write_in == 1) & (two_stage_transfer == 0) & (partial_lower_half_transfer == 1)) | 
                        ((write_in == 1) & (two_stage_transfer == 1) & (partial_lower_half_transfer == 1) & (state == Idle));

  assign upper_enable = ((write_in == 1) & (full_word_transfer == 1)) |  
                        ((write_in == 1) & (two_stage_transfer == 0) & (partial_upper_half_transfer == 1)) | 
                        ((write_in == 1) & (two_stage_transfer == 1) & (partial_upper_half_transfer == 1) & (state == PartialLower));

  five_hundred_twelve_bit_byteenable_FSM lower_five_hundred_twelve_bit_byteenable_FSM (
    .clk (clk),
    .reset (reset),
    .write_in (lower_enable),
    .byteenable_in (byteenable_in[63:0]),
    .waitrequest_out (lower_stall),    
    .byteenable_out (byteenable_out[63:0]),
    .waitrequest_in (waitrequest_in)
  );

  five_hundred_twelve_bit_byteenable_FSM upper_five_hundred_twelve_bit_byteenable_FSM (
    .clk (clk),
    .reset (reset),
    .write_in (upper_enable),
    .byteenable_in (byteenable_in[127:64]),
    .waitrequest_out (upper_stall),    
    .byteenable_out (byteenable_out[127:64]),
    .waitrequest_in (waitrequest_in)
  );

  assign waitrequest_out = (waitrequest_in == 1) | ((state != Idle) & (write_in == 1));

endmodule

