module priority_encoder (
    input [7:0] a, b, c, d, // Four 8-bit unsigned numbers
    output reg [1:0] max_index // Two-bit index of the maximum value
);

always @(*) begin
    if (a >= b && a >= c && a >= d) begin
        max_index = 2'b00;
    end else if (b >= a && b >= c && b >= d) begin
        max_index = 2'b01;
    end else if (c >= a && c >= b && c >= d) begin
        max_index = 2'b10;
    end else begin
        max_index = 2'b11;
    end
end

endmodule

module parity_generator (
    input [8:0] in, // Input byte without parity bit
    output reg [8:0] out // Output byte with even parity bit added
);

integer i;
reg parity;

always @(*) begin
    parity = 1'b0;
    for (i = 0; i < 8; i = i + 1) begin
        parity = parity ^ in[i];
    end
    out = {in, ~parity};
end

endmodule

