    input [7:0] a, b, c, d, // Four 8-bit unsigned numbers
    output reg [8:0] out // Output 9-bit byte with parity bit added
);

wire [7:0] max_value;

assign max_value = (max_index == 2'b00) ? a :
                   (max_index == 2'b01) ? b :
                   (max_index == 2'b10) ? c :
                   d;

parity_generator parity_gen (
    .in(max_value),
    .out(out)
);

endmodule

