module shift_mux_array__parameterized3
   #(parameter W = 26, parameter N = 1)
   (input [W-1:0] Data_i,
    input [N-1:0] select_i,
    input [W-1:0] bit_shift_i,
    output [W-1:0] Data_o);

  wire [W-1:0] shifted_data_i;
  wire [W-1:0] mux_outputs [0:(2**N)-1];

  // Shift the input data by the bit_shift_i value
  assign shifted_data_i = {Data_i[W-1:bit_shift_i], {bit_shift_i{1'b0}}};

  // Instantiate the Multiplexer modules
  genvar i;
  generate
    for (i = 0; i < 2**N; i = i + 1) begin : mux_gen
      Multiplexer_AC__parameterized105 #(W) mux_inst (
        .D0(shifted_data_i[i]),
        .D1(bit_shift_i),
        .S(mux_outputs[i]),
        .ctrl(select_i)
      );
    end
  endgenerate

  // Concatenate the outputs of the Multiplexer modules to form the output data
  assign Data_o = {mux_outputs};

endmodule

module xbar2x2(
    input clk,
    input [31:0] addr1,
    input [31:0] addr2,
    input [31:0] req1,
    input [31:0] req2,
    input [31:0] res1,
    input [31:0] res2,
    output [31:0] reqA,
    output [31:0] reqB,
    output [31:0] resA,
    output [31:0] resB
);

reg [31:0] reqA_reg, reqB_reg, resA_reg, resB_reg;

always @(posedge clk) begin
    // Route req1 and res1 to reqA/resA if addr1[2] is 0
    if (addr1[2] == 0) begin
        reqA_reg <= req1;
        resA_reg <= res1;
    end else begin
        reqB_reg <= req1;
        resB_reg <= res1;
    end

    // Route req2 and res2 to reqA/resA if addr2[2] is 0
    if (addr2[2] == 0) begin
        reqA_reg <= req2;
        resA_reg <= res2;
    end else begin
        reqB_reg <= req2;
        resB_reg <= res2;
    end
end

assign reqA = (addr1[2] == 0) ? req1 : req2;
assign reqB = (addr1[2] == 0) ? req2 : req1;
assign resA = (addr1[2] == 0) ? res1 : res2;
assign resB = (addr1[2] == 0) ? res2 : res1;
assign reqA = (resA_reg[31] == 1) ? resA_reg : 32'h80000000;
assign reqB = (resB_reg[31] == 1) ? resB_reg : 32'h80000000;
assign resA = (resA_reg[31] == 1) ? 32'h80000000 : resA_reg;
assign resB = (resB_reg[31] == 1) ? 32'h80000000 : resB_reg;

endmodule

