module MMU (
  input [31:0] v_addr,
  input [31:0] pt_base,
  input [31:0] pt_entry_size,
  input [31:0] pg_size,
  output [31:0] p_addr
);

  // Calculate the number of bits needed for the offset
  localparam OFFSET_BITS = $clog2(pg_size);

  // Calculate the number of bits needed for the page table index
  localparam PTI_BITS = $clog2((pt_entry_size/8));

  // Calculate the number of bits needed for the page directory index
  localparam PDI_BITS = 32 - OFFSET_BITS - PTI_BITS;

  // Calculate the number of entries in the page table
  localparam PT_ENTRIES = pg_size / pt_entry_size;

  // Calculate the number of entries in the page directory
  localparam PD_ENTRIES = 1 << PDI_BITS;

  // Calculate the number of bits needed for the physical page frame number
  localparam PFN_BITS = 32 - OFFSET_BITS;

  // Calculate the page directory index
  wire [PDI_BITS-1:0] pdi = v_addr >> (OFFSET_BITS + PTI_BITS);

  // Calculate the page table index
  wire [PTI_BITS-1:0] pti = (v_addr >> OFFSET_BITS) & ((1 << PTI_BITS) - 1);

  // Calculate the offset within the page
  wire [OFFSET_BITS-1:0] offset = v_addr & ((1 << OFFSET_BITS) - 1);

  // Calculate the base address of the page table
  wire [31:0] pt_addr = pt_base + (pdi * pt_entry_size);

  // Read the page table entry
  wire [31:0] pte = {pt_addr[31:12], pti} << 2;

  // Extract the physical page frame number from the page table entry
  wire [PFN_BITS-1:0] pfn = pte[31:12];

  // Concatenate the physical page frame number with the offset to form the physical address
  assign p_addr = {pfn, offset};

endmodule

