    reg [7:0] q_combined;       // Output from the combined functional module
    reg [7:0] q_counter_reg;    // Register to store the output of the 4-digit binary counter
    reg d_ff;                   // D flip-flop output
    wire or_output;             // Output from the bitwise OR module

    // D flip-flop
    always @(posedge clk, posedge reset) begin
        if (reset) begin
            d_ff <= 1'b0;
        end else begin
            d_ff <= d;
        end
    end

    // 4-digit binary counter
    always @(posedge clk, posedge reset) begin
        if (reset) begin
            counter <= 4'b0000;
        end else begin
            if (enable) begin
                if (counter[3] == 1'b1) begin
                    counter[3:0] <= 4'b0000;
                end else if (counter[2] == 1'b1) begin
                    counter[3:2] <= 2'b00;
                    counter[1:0] <= counter[1:0] + 1;
                end else if (counter[1] == 1'b1) begin
                    counter[3:1] <= 3'b000;
                    counter[0] <= counter[0] + 1;
                end else begin
                    counter <= counter + 1;
                end
            end
        end
    end

    // Bitwise OR module
    or_module or_inst (
        .a(q_combined),
        .b(q_counter_reg),
        .y(or_output)
    );

    // Combined functional module
    always @(*) begin
        if (select) begin
            q_combined = or_output;
        end else begin
            q_combined = {counter[3], counter[2], counter[1], counter[0], d_ff};
        end
    end

    // Register for the output of the 4-digit binary counter
    always @(posedge clk, posedge reset) begin
        if (reset) begin
            q_counter_reg <= 16'b0;
        end else begin
            q_counter_reg <= {counter[3], counter[2], counter[1], counter[0]};
        end
    end

    assign q = q_combined;
    assign q_counter = {counter[3], counter[2], counter[1], counter[0]};

endmodule

