module updateCRC5 (
  input rstCRC,
  input CRCEn,
  input CRC5_8BitIn,
  input [7:0] dataIn,
  input clk,
  input rst,
  output reg [4:0] CRCResult,
  output reg ready
);

  wire   rstCRC;
  wire   CRCEn;
  wire   CRC5_8BitIn;
  wire   [7:0] dataIn;
  wire   clk;
  wire   rst;
  reg    [4:0] CRCResult;
  reg ready;

  reg doUpdateCRC;
  reg [7:0] data;
  reg [3:0] loopEnd;
  reg [3:0] i;

  always @(posedge clk) begin
    if (rst == 1'b1 || rstCRC == 1'b1) begin
      doUpdateCRC <= 1'b0;
      i <= 4'h0;
      CRCResult <= 5'h1f;
      ready <= 1'b1;
    end
    else begin
      if (doUpdateCRC == 1'b0) begin
        if (CRCEn == 1'b1) begin
          ready <= 1'b0;
          doUpdateCRC <= 1'b1;
          data <= dataIn;
          if (CRC5_8BitIn == 1'b1) begin
            loopEnd <= 4'h7; 
          end
          else begin
            loopEnd <= 4'h2;
          end
        end
      end
      else begin
        i <= i + 1'b1;
        if ((CRCResult[0] ^ data[7]) == 1'b1) begin
          CRCResult <= {1'b0, CRCResult[4:1]} ^ 5'h14;
        end
        else begin
          CRCResult <= {1'b0, CRCResult[4:1]};
        end
        data <= {data[6:0], 1'b0};
        if (i == loopEnd) begin
          doUpdateCRC <= 1'b0; 
          i <= 4'h0;
          ready <= 1'b1;
        end
      end
    end
  end
endmodule

module subtraction (
    input [7:0] a,
    input [7:0] b,
    output [7:0] s,
    output underflow
);

wire [7:0] a_inv;
assign a_inv = ~a + 1;

wire [7:0] b_inv;
assign b_inv = ~b + 1;

wire [7:0] sum1;
wire [7:0] sum2;
wire [7:0] diff;
wire [1:0] carry_select;

assign {carry_select[1], carry_select[0]} = (a_inv[7] & b[7]) | (~a_inv[7] & ~b[7]);
assign sum1 = a_inv + b;
assign sum2 = a + b_inv;
assign diff = carry_select[1] ? sum2 : sum1;

assign s = diff;
assign underflow = carry_select[0] & ~carry_select[1];

endmodule

module final_module (
    input [7:0] a,
    input [7:0] b,
    output [7:0] result
);

wire [7:0] s;
wire underflow;

subtraction sub (
    .a(a),
    .b(b),
    .s(s),
    .underflow(underflow)
);

assign result = underflow ? {8{s[7]}} : s;

endmodule

module vram_display(reset,clk,hcount,vcount,vr_pixel,
                    vram_addr,vram_read_data);

   input reset, clk;
   input [10:0] hcount;
   input [9:0]  vcount;
   output [7:0] vr_pixel;
   output [18:0] vram_addr;
   input [35:0]  vram_read_data;

   wire [10:0] hcount_f = (hcount >= 1048) ? (hcount - 1048) : (hcount + 8);
   wire [9:0] vcount_f = (hcount >= 1048) ? ((vcount == 805) ? 0 : vcount + 1) : vcount;

   wire [18:0]  vram_addr = {1'b0, vcount_f, hcount_f[9:2]};

   wire [1:0]   hc4 = hcount[1:0];
   reg [7:0]    vr_pixel;
   reg [35:0]   vr_data_latched;
   reg [35:0]   last_vr_data;

   always @(posedge clk)
     last_vr_data <= (hc4==2'd3) ? vr_data_latched : last_vr_data;

   always @(posedge clk)
     vr_data_latched <= (hc4==2'd1) ? vram_read_data : vr_data_latched;

   always @(*)
     case (hc4)
       2'd3: vr_pixel = last_vr_data[7:0];
       2'd2: vr_pixel = last_vr_data[7+8:0+8];
       2'd1: vr_pixel = last_vr_data[7+16:0+16];
       2'd0: vr_pixel = last_vr_data[7+24:0+24];
     endcase

endmodule

