module booth_multiplier (
    input signed [3:0] a,
    input signed [3:0] b,
    output reg signed [7:0] out
);

reg signed [3:0] a_reg;
reg signed [3:0] b_reg;
reg signed [7:0] product_reg;

always @(posedge clk) begin
    a_reg <= a;
    b_reg <= b;
end

always @(posedge clk) begin
    product_reg <= {4'b0, a_reg} * {4'b0, b_reg};
end

always @(posedge clk) begin
    case(product_reg[4:0])
        5'b00001: product_reg <= product_reg + {8'b0, ~b_reg + 1};
        5'b00010: product_reg <= product_reg + {8'b0, ~b_reg + 2};
        5'b00100: product_reg <= product_reg + {8'b0, ~b_reg + 4};
        5'b01000: product_reg <= product_reg + {8'b0, ~b_reg + 8};
        5'b10000: product_reg <= product_reg + {8'b0, b_reg};
        5'b11111: product_reg <= product_reg + {8'b0, ~b_reg + 1};
        default: product_reg <= product_reg;
    endcase
end

always @(posedge clk) begin
    out <= product_reg[7:0];
end

endmodule

module adder_4bit(
    input [3:0] a,
    input [3:0] b,
    input carry_in,
    output [3:0] sum,
    output carry_out
);

reg [3:0] sum_reg;
reg carry_out_reg;

always @(*) begin
    sum_reg[0] = a[0] ^ b[0] ^ carry_in;
    sum_reg[1] = a[1] ^ b[1] ^ sum_reg[0];
    sum_reg[2] = a[2] ^ b[2] ^ sum_reg[1];
    sum_reg[3] = a[3] ^ b[3] ^ sum_reg[2];

    carry_out_reg = (a[3] & b[3]) | (a[3] & carry_in) | (b[3] & carry_in);
end

assign sum = sum_reg;
assign carry_out = carry_out_reg;

endmodule

module top_module(
    input wire clk,
    input wire [7:0] in,
    output wire [6:0] out);

    wire [2:0] pos;
    wire [15:0] shifted_in;
    wire [7:0] mux_out;
    wire [3:0] hex_out;

    priority_encoder pe(.in(in), .pos(pos));
    barrel_shifter bs(.in({in, 8'b0}), .out(shifted_in));
    mux mx(.in1(shifted_in[15:8]), .in2(shifted_in[7:0]), .sel(pos), .out(mux_out));
    selector sel(.in(mux_out), .out(hex_out));
    display disp(.in(hex_out), .out(out));

endmodule

module priority_encoder (
