module wallace_multiplier (
    input clk,
    input [3:0] A,
    input [3:0] B,
    output reg [7:0] P
);

reg [3:0] a_partial [2:0];
reg [3:0] b_partial [2:0];
reg [7:0] p_partial [2:0];
reg [3:0] a_final [3:0];
reg [3:0] b_final [3:0];
reg [7:0] p_final [3:0];

always @ (posedge clk) begin
    // Partial products
    a_partial[0] = A[0:1];
    a_partial[1] = A[2:3];
    a_partial[2] = 4'b0;
    b_partial[0] = B[0:1];
    b_partial[1] = B[2:3];
    b_partial[2] = 4'b0;
    p_partial[0] = a_partial[0] * b_partial[0];
    p_partial[1] = a_partial[1] * b_partial[1];
    p_partial[2] = a_partial[2] * b_partial[2];

    // Final products
    a_final[0] = A[0];
    a_final[1] = A[1];
    a_final[2] = A[2];
    a_final[3] = A[3];
    b_final[0] = B[0];
    b_final[1] = B[1];
    b_final[2] = B[2];
    b_final[3] = B[3];
    p_final[0] = p_partial[0];
    p_final[1] = p_partial[1] + (p_partial[0] >> 2);
    p_final[2] = p_partial[2] + (p_partial[1] >> 2) + (p_partial[0] >> 4);
    p_final[3] = (p_partial[2] >> 2) + (p_partial[1] >> 4) + (p_partial[0] >> 6);

    // Final product
    P = {p_final[3], p_final[2][1:0], p_final[1][2:0], p_final[0][3:0]};
end

endmodule

module ModTxtMemW(
  input clock,
  input reset,
  input [13:0] pixCellIx,
  output [127:0] cellData,
  input [15:0] fontGlyph,
  output [63:0] fontData,
  input [31:0] busAddr,
  inout [31:0] busData,
  input busOE,
  input busWR,
  output [1:0] busOK
);

  reg [31:0] scrCell1A [0:1023];
  reg [31:0] scrCell1B [0:1023];
  reg [31:0] scrCell1C [0:1023];
  reg [31:0] scrCell1D [0:1023];
  reg [63:0] fontMem [0:255];
  reg [63:0] fontGfx1Mem [0:127];
  reg [63:0] fontGfx2Mem [0:127];
  reg [31:0] scrRegCtrl [0:7];
  reg [127:0] tCell1;
  reg [127:0] tNextCell1;
  reg [15:0] tFontGlyph;
  reg [63:0] tFontData1;
  reg [63:0] tFontData2;
  reg [63:0] tFontDataAsc1;
  reg [63:0] tFontDataGfx1;
  reg [63:0] tFontDataGfx2;
  reg [13:0] tPixCellIx;
  reg [1:0] tBusOK;
  reg [31:0] tBusData;
  wire tBusCSel;

  assign busOK = (busOE && tBusCSel) ? tBusOK : 2'bZ;
  assign busData = (busOE && tBusCSel) ? tBusData : 32'hZZZZ_ZZZZ;
  assign tBusCSel = (busAddr[31:16] == 16'h0080);

  always @(posedge clock) begin
    tPixCellIx <= busOE && tBusCSel ? busAddr[15:2] : pixCellIx;
    tBusOK <= 0;
    tBusData <= 0;
    if (busOE && tBusCSel) begin
      if (busAddr[15:8] == 8'hFF) begin
        tBusOK <= 1;
        case (busAddr[6:2])
          3'b000: tBusData <= scrRegCtrl[0];
          3'b001: tBusData <= scrRegCtrl[1];
          3'b010: tBusData <= scrRegCtrl[2];
          3'b011: tBusData <= scrRegCtrl[3];
          3'b100: tBusData <= {18'h0, pixCellIx};
        endcase
      end else begin
        tBusOK <= tPixCellIx[11:0] == busAddr[15:4];
        case (busAddr[3:2])
          2'b00: tBusData <= tCell1[31:0];
          2'b01: tBusData <= tCell1[63:32];
          2'b10: tBusData <= tCell1[95:64];
          2'b11: tBusData <= tCell1[127:96];
        endcase
      end
    end
    tFontDataAsc1 <= fontMem[tFontGlyph[7:0]];
    tFontDataGfx1 <= fontGfx1Mem[tFontGlyph[6:0]];
    tFontDataGfx2 <= fontGfx2Mem[tFontGlyph[6:0]];
    case (tFontGlyph[9:7])
      3'b000, 3'b001: tFontData2 <= tFontDataAsc1;
      3'b010: tFontData2 <= tFontDataGfx2;
      3'b011: tFontData2 <= tFontDataGfx1;
      default: tFontData2 <= tFontDataAsc1;
    endcase
  end

  always @(posedge clock) begin
    tCell1[31:0] <= scrCell1A[tPixCellIx[9:0]];
    tCell1[63:32] <= scrCell1B[tPixCellIx[9:0]];
    tCell1[95:64] <= scrCell1C[tPixCellIx[9:0]];
    tCell1[127:96] <= scrCell1D[tPixCellIx[9:0]];
    tFontGlyph <= fontGlyph;
    tFontData1 <= tFontData2;
    if (tBusCSel && busOE) begin
      tPixCellIx <= busAddr[15:2];
    end else begin
      tPixCellIx <= pixCellIx;
    end
    if (tBusCSel && busWR && !busOE) begin
      case (busAddr[3:2])
        2'b00: scrCell1A[busAddr[13:4]] <= busData;
        2'b01: scrCell1B[busAddr[13:4]] <= busData;
        2'b10: scrCell1C[busAddr[13:4]] <= busData;
        2'b11: scrCell1D[busAddr[13:4]] <= busData;
      endcase
    end
  end

  initial begin
    $readmemh("fontmem.txt", fontMem);
    $readmemh("gfxfont0.txt", fontGfx1Mem);
    $readmemh("gfxfont1.txt", fontGfx2Mem);
    $readmemh("scrmem_1a.txt", scrCell1A);
    $readmemh("scrmem_1b.txt", scrCell1B);
    $readmemh("scrmem_1c.txt", scrCell1C);
    $readmemh("scrmem_1d.txt", scrCell1D);
  end

  assign cellData = tCell1;
  assign fontData = tFontData1;

endmodule

