module priority_encoder (
    input [7:0] in,
    output reg [2:0] pos
);

    always @(*) begin
        case(in)
            8'b00000001: pos = 3'b000;
            8'b00000011: pos = 3'b001;
            8'b00000111: pos = 3'b010;
            8'b00001111: pos = 3'b011;
            8'b00011111: pos = 3'b100;
            8'b00111111: pos = 3'b101;
            8'b01111111: pos = 3'b110;
            8'b11111111: pos = 3'b111;
            default: pos = 3'b000;
        endcase
    end

endmodule

module bitwise_and (
    input a,
    input [2:0] b,
    output reg out
);

    always @(a, b) begin
        case(b)
            3'b000: out = 1'b0;
            3'b001: out = a & (1 << 7);
            3'b010: out = a & (1 << 6);
            3'b011: out = a & (1 << 5);
            3'b100: out = a & (1 << 4);
            3'b101: out = a & (1 << 3);
            3'b110: out = a & (1 << 2);
            3'b111: out = a & (1 << 1);
            default: out = 1'b0;
        endcase
    end

endmodule

