module uart_tx(
	input clk,
	input send,
	input [7:0] data,
	output tx,
	output ready
);
	reg [7:0] bit_count;
	reg [10:0] msg;

	reg r_tx; 
	reg r_ready; 

	initial begin
		bit_count 	<= 0;
		msg 		<= 0;
		r_tx 		<= 0;
		r_ready 	<= 0;
	end

	always @(posedge clk) begin
		if(send && !msg) begin
			// add start bit and stop bit + pause
			msg <= {2'b11, data, 1'b0}; 
			bit_count <= 10;
		end
		if(msg && bit_count > 0) begin
			r_tx <= msg[0];
			msg  <= msg >> 1;
			bit_count <= bit_count - 1;
		end
		if(bit_count == 0) begin
			r_tx <= 1;
			r_ready <= 1;
		end
		if(!send) begin
			msg <= 0;
			bit_count <= 0;
			r_ready <= 0;
		end
	end

	assign tx = r_tx;
	assign ready = r_ready;

endmodule

module add_sub_8bit (
    input [7:0] a,
    input [7:0] b,
    input mode,
    output reg [7:0] result
);

reg [7:0] sum_reg;
reg [7:0] diff_reg;
reg [1:0] stage;

always @(*) begin
    case(stage)
        2'b00: begin
            sum_reg = a + b;
            diff_reg = a - b;
        end
        2'b01: begin
            if (mode == 0)
                result = sum_reg;
            else
                result = diff_reg;
        end
        2'b10: begin
            result = 0;
        end
    endcase
end

always @(posedge clk) begin
    if (stage == 2'b10)
        stage <= 2'b00;
    else
        stage <= stage + 1;
end

endmodule

