module fifo (
  input clk,
  input reset_n,
  input write_en,
  input read_en,
  input [31:0] data_in,
  output [31:0] data_out,
  output empty,
  output full
);

  parameter DEPTH = 8;

  reg [31:0] mem [0:DEPTH-1];
  reg [2:0] write_ptr = 0;
  reg [2:0] read_ptr = 0;
  reg [2:0] count = 0;

  assign empty = (count == 0);
  assign full = (count == DEPTH);

  always @(posedge clk) begin
    if (!reset_n) begin
      write_ptr <= 0;
      read_ptr <= 0;
      count <= 0;
    end else begin
      if (write_en && !full) begin
        mem[write_ptr] <= data_in;
        write_ptr <= write_ptr + 1;
        count <= count + 1;
      end
      if (read_en && !empty) begin
        data_out <= mem[read_ptr];
        read_ptr <= read_ptr + 1;
        count <= count - 1;
      end
    end
  end

endmodule

module channel_equalization (
  input signed [n-1:0] x,
  input signed [m-1:0] h,
  output signed [n-1:0] y
);

parameter n = 8; // number of samples in the transmitted signal
parameter m = 4; // number of coefficients in the channel impulse response

integer i, j;
reg signed [n-1:0] conv_result;
reg signed [n-1:0] norm_result;

// Convolution operation
always @(*) begin
  for (i = 0; i < n; i = i + 1) begin
    conv_result[i] = 0;
    for (j = 0; j < m; j = j + 1) begin
      if ((i - j) >= 0) begin
        conv_result[i] = conv_result[i] + (x[i - j] * h[j]);
      end
    end
  end
end

// Normalization step
always @(*) begin
  for (i = 0; i < n; i = i + 1) begin
    norm_result[i] = (conv_result[i] * x[i]) / conv_result[i];
  end
end

// Assign equalized signal
assign y = norm_result;

endmodule

