module mult_8bit_unsigned_booth (
    input [7:0] M,
    input [7:0] N,
    output reg [15:0] P
);

reg [7:0] A;
reg [7:0] S;
reg [3:0] count;

always @(*) begin
    A = {M, 1'b0};
    S = {~M + 1, 1'b0};
    P = 16'b0;
    count = 4'd0;

    while(count < 4'd8) begin
        case({N[1], N[0]})
            2'b00: begin
                // do nothing
            end

            2'b01: begin
                P = P + {S, 1'b0} << (count * 2);
            end

            2'b10: begin
                P = P + {A, 1'b0} << (count * 2);
            end

            2'b11: begin
                // do nothing
            end
        endcase

        N = {N[6:0], N[7]};
        count = count + 1;
    end
end

endmodule

module sin_taylor_series
#(
    parameter WIDTH = 64
)
(
    input  wire                  clk,
    input  wire                  reset,
    input  wire                  ce,
    input  wire [WIDTH-1:0]      din0,
    input  wire [WIDTH-1:0]      din1,
    output wire [WIDTH-1:0]      dout
);

reg  [WIDTH-1:0] x;
reg  [WIDTH-1:0] x_pow;
reg  [WIDTH-1:0] sum;
reg  [WIDTH-1:0] term;
reg  [WIDTH-1:0] fact;
reg  [WIDTH-1:0] sign;
reg  [WIDTH-1:0] count;

always @(posedge clk) begin
    if (reset) begin
        x      <= 0;
        x_pow  <= 1;
        sum    <= 0;
        term   <= 0;
        fact   <= 1;
        sign   <= 1;
        count  <= 1;
    end else if (ce) begin
        x      <= din0;
        x_pow  <= din0;
        sum    <= din0;
        term   <= din0;
        fact   <= 1;
        sign   <= 1;
        count  <= 1;

        while (count < din1) begin
            x_pow  <= x_pow * x * x;
            fact   <= fact * (count + 1) * (count + 2);
            sign   <= -sign;
            term   <= x_pow / fact * sign;
            sum    <= sum + term;
            count  <= count + 2;
        end

        dout <= sum;
    end
end

endmodule

