module four_way_minimum(
    input [7:0] a, b, c, d, // 8-bit inputs
    input select,           // Select input
    output reg [7:0] min_out // 8-bit minimum output
);

  reg [7:0] ab_min, cd_min, ac_min, bd_min, ad_min, bc_min;
  // Intermediate variables to find minimum values

  always @* begin
    if (select == 1'b0) begin
      // Find minimum of a, b, c, and d
      ab_min = (a < b) ? a : b;
      cd_min = (c < d) ? c : d;
      ac_min = (a < c) ? a : c;
      bd_min = (b < d) ? b : d;
      ad_min = (a < d) ? a : d;
      bc_min = (b < c) ? b : c;
      min_out = (ab_min < cd_min) ? ab_min : cd_min;
      min_out = (ac_min < min_out) ? ac_min : min_out;
      min_out = (bd_min < min_out) ? bd_min : min_out;
      min_out = (ad_min < min_out) ? ad_min : min_out;
      min_out = (bc_min < min_out) ? bc_min : min_out;
    end
    else begin
      // Set minimum output to 0 when select is 1
      min_out = 8'b0;
    end
  end
endmodule
