  reg [31:0] product;

  // Check for errors
  always @(*) begin
    if (divisor == 0) begin
      $display("Error: divisor cannot be zero");
      rem = 0;
    end
    else if (div < 0) begin
      $display("Error: dividend cannot be negative");
      rem = 0;
