// Adder module with carry-lookahead architecture
module adder_module (
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] sum
);

    wire [31:0] g, p, c;

    // Generate carry and propagate signals
    generate
        genvar i;
        for (i = 0; i < 32; i = i + 1) begin
            assign g[i] = a[i] & b[i];
            assign p[i] = a[i] ^ b[i];
        end
    endgenerate

    // Generate carry signals using carry-lookahead
    generate
        genvar i;
        for (i = 0; i < 31; i = i + 1) begin
            assign c[i+1] = g[i] | (p[i] & c[i]);
        end
        assign c[0] = g[31] | (p[31] & c[30]);
    endgenerate

    // Generate sum using carry signals
    always @ (g or p or c) begin
        sum = {g[31], p[31:0]} + c;
    end

endmodule

// Priority encoder module
module priority_encoder_module (
    input [7:0] in,
    output reg [2:0] pos
);

    always @ (in) begin
        casez (in)
            8'b00000001: pos = 0;
            8'b00000010: pos = 1;
            8'b00000100: pos = 2;
            8'b00001000: pos = 3;
            8'b00010000: pos = 4;
            8'b00100000: pos = 5;
            8'b01000000: pos = 6;
            8'b10000000: pos = 7;
            default: pos = 0;
        endcase
    end

endmodule

