module fixed_point_adder(
    input clk,
    input signed [N+M-1:0] op1,
    input signed [P+Q-1:0] op2,
    output reg signed [R+S-1:0] result
);

    // Determine the number of integer and fraction bits in the result
    parameter R = max(N,P);
    parameter S = max(M,Q);

    // Determine the number of bits to shift op1 and op2 to align their decimal points
    parameter shift = abs(M-Q);

    // Shift op1 and op2 to align their decimal points
    reg signed [R+S-1:0] aligned_op1;
    reg signed [R+S-1:0] aligned_op2;
    always @* begin
        if (M > Q) begin
            aligned_op1 = op1 << shift;
            aligned_op2 = op2;
        end else begin
            aligned_op1 = op1;
            aligned_op2 = op2 << shift;
        end
    end

    // Add the aligned numbers together
    reg signed [R+S-1:0] sum;
    always @* begin
        sum = aligned_op1 + aligned_op2;
    end

    // Round the result to the nearest representable fixed-point number with S fraction bits
    reg signed [R+S-1:0] rounded_sum;
    always @* begin
        if (sum[S] == 0) begin
            rounded_sum = sum >> 1;
        end else begin
            rounded_sum = (sum >> 1) + 1;
        end
    end

    // Saturate the result if it overflows or underflows the representable range
    always @(posedge clk) begin
        if (rounded_sum >= (1 << (R+S-1))) begin
            result <= (1 << (R+S-1)) - 1;
        end else if (rounded_sum <= -(1 << (R+S-1))) begin
            result <= -(1 << (R+S-1));
        end else begin
            result <= rounded_sum;
        end
    end

endmodule

