module VAD (
  input [n-1:0] audio_samples,
  output speech_present
);

parameter n = 1024; // number of audio samples
parameter fs = 16000; // sampling frequency in Hz
parameter frame_size = 256; // number of samples in each analysis frame
parameter frame_shift = 128; // number of samples between adjacent frames
parameter threshold = 1000000; // energy threshold in arbitrary units

reg [frame_size-1:0] frame_samples; // buffer for samples in current frame
reg [frame_size-1:0] frame_energy; // energy of current frame
reg [31:0] energy_sum; // sum of squares of samples in current frame
reg [31:0] energy_avg; // average energy of current frame
reg speech_detected; // flag indicating speech detection

integer i, j; // loop counters

always @(*) begin
  // shift samples in buffer
  for (i = frame_size-1; i > 0; i = i - 1) begin
    frame_samples[i] = frame_samples[i-1];
  end
  // add new sample to buffer
  frame_samples[0] = audio_samples[0];
  // compute energy of frame
  energy_sum = 0;
  for (i = 0; i < frame_size; i = i + 1) begin
    energy_sum = energy_sum + frame_samples[i]*frame_samples[i];
  end
  frame_energy = energy_sum;
  // compute average energy of frame
  energy_avg = energy_sum/frame_size;
  // compare energy to threshold
  if (energy_avg > threshold) begin
    speech_detected = 1;
  end
  else begin
    speech_detected = 0;
  end
  // shift input samples
  for (i = 0; i < n-1; i = i + 1) begin
    audio_samples[i] = audio_samples[i+1];
  end
end

always @(posedge clk) begin
  // shift speech detection flag
  for (j = n/frame_shift-1; j > 0; j = j - 1) begin
    speech_present[j] = speech_present[j-1];
  end
  // set speech detection flag for current frame
  speech_present[0] = speech_detected;
end

endmodule

