module crc_check (
    input clk,
    input reset, // Synchronous active-high reset
    input [15:0] data_in, // 16-bit input data stream
    output reg error_detected // Output indicating whether an error has been detected or not
);

reg [7:0] crc_reg; // 8-bit shift register for CRC calculation
reg [15:0] crc_poly = 16'h8005; // CRC polynomial (x^16 + x^15 + x^2 + 1)

wire [31:0] data_crc; // Combined data and CRC value
wire [31:0] sum; // Intermediate sum for CSA
wire carry_out; // Carry-out signal for CSA

// CRC calculation process
always @(posedge clk) begin
    if (reset) begin
        crc_reg <= 8'h00;
    end else begin
        crc_reg <= {crc_reg[6:0], data_in[15]}; // Shift in MSB of data
        if (crc_reg[7]) begin // XOR with CRC polynomial if MSB of shift register is 1
            crc_reg <= crc_reg ^ crc_poly;
        end
    end
end

// CSA for generating combined data and CRC value
carry_select_adder_16bit csa1 (
    .a(data_in),
    .b(crc_reg),
    .sum(sum[15:0]),
    .carry_out(carry_out)
);

carry_select_adder_16bit csa2 (
    .a({16'h0000, sum[15:0]}),
    .b({16'h0000, crc_reg}),
    .sum(data_crc),
    .carry_out()
);

// Error detection process
always @(posedge clk) begin
    if (reset) begin
        error_detected <= 1'b0;
    end else begin
        error_detected <= (data_crc != 32'h0000);
    end
end

endmodule

// 16-bit carry select adder module
module carry_select_adder_16bit (
    input [15:0] a,
    input [15:0] b,
    output reg [15:0] sum,
    output reg carry_out
);

reg [15:0] sum0, sum1; // Intermediate sums
reg [15:0] carry0, carry1; // Intermediate carry signals

// Generate intermediate sums and carry signals
always @(*) begin
    sum0 = a + b;
    sum1 = a + b + 1'b1;
    carry0 = (a[3:0] + b[3:0]) >= 4'h8;
    carry1 = (sum1[3:0] + carry0) >= 4'h8;
end

// Generate final sum and carry-out signals using multiplexer
always @(sum0, sum1, carry0, carry1) begin
    if (carry1) begin
        sum <= sum1;
        carry_out <= 1'b1;
    end else begin
        sum <= sum0;
        carry_out <= carry0;
    end
end

endmodule

module spi_interface (
    input SCLK,
    input INTERRUPT,
    input CLOCK,
    output reg [7:0] DATA_IN,
    output reg [7:0] DATA_OUT,
    output reg NEW_DATA
);

reg [7:0] tx_data;
reg [7:0] rx_data;
reg tx_en;
reg rx_en;
reg tx_done;
reg rx_done;
reg [2:0] bit_count;
reg [2:0] rx_bit_count;
reg [2:0] tx_bit_count;

always @(posedge CLOCK) begin
    if (tx_en) begin
        if (tx_bit_count == 0) begin
            tx_done <= 0;
            tx_data <= DATA_OUT;
        end else begin
            tx_data <= {1'b0, tx_data[7:1]};
        end
        tx_bit_count <= tx_bit_count + 1;
        if (tx_bit_count == 8) begin
            tx_en <= 0;
            tx_done <= 1;
            tx_bit_count <= 0;
        end
    end else if (rx_en) begin
        if (rx_bit_count == 0) begin
            rx_data <= 0;
        end else begin
            rx_data <= {rx_data[6:0], SCLK};
        end
        rx_bit_count <= rx_bit_count + 1;
        if (rx_bit_count == 8) begin
            rx_en <= 0;
            rx_bit_count <= 0;
            NEW_DATA <= 1;
        end
    end else begin
        if (INTERRUPT) begin
            rx_en <= 1;
        end
    end
end

always @(negedge SCLK) begin
    if (tx_en) begin
        DATA_IN <= rx_data;
    end else if (rx_en) begin
        DATA_IN <= DATA_IN;
    end else begin
        DATA_IN <= 0;
    end
end

always @(posedge SCLK) begin
    if (tx_done) begin
        rx_en <= 1;
    end
end

always @(posedge SCLK) begin
    if (tx_en == 0 && rx_en == 0 && INTERRUPT == 0) begin
        NEW_DATA <= 0;
    end
end

always @(posedge SCLK) begin
    if (tx_en == 0 && rx_en == 0 && INTERRUPT == 1) begin
        NEW_DATA <= 1;
    end
end

always @(posedge SCLK) begin
    if (tx_en == 0 && rx_en == 0 && INTERRUPT == 1) begin
        tx_en <= 1;
    end
end

endmodule

