module output_arbiter #(
    parameter SIZE = 10,
    parameter LOOP = 2,
    parameter DEPTH = 5
)(
    input clk,
    input read,
    input write,
    input [7:0] dataIn,
    output wire [7:0] dataOut,
    output reg ramFull,
    output reg dataAvailable
);

    reg [7:0] nodeNum = 0;
    reg [7:0] largestVal = 0;
    reg [$clog2(SIZE*LOOP - 1'b1):0] outputCnt = 0;
    reg [7:0] memory [DEPTH-1:0];
    reg [7:0] readIndex = 0;
    reg [7:0] writeIndex = 0;
    reg [7:0] itemCount = 0;
    reg [7:0] loopCount = 0;

    assign dataOut = nodeNum;

    always@(posedge clk) begin
        if(write) begin
            if(itemCount == SIZE) begin
                ramFull <= 1;
            end else begin
                memory[writeIndex] <= dataIn;
                itemCount <= itemCount + 1;
                writeIndex <= writeIndex + 1;
                if(writeIndex == DEPTH) begin
                    writeIndex <= 0;
                end
                if(dataIn > largestVal) begin
                    nodeNum <= writeIndex - 1;
                    largestVal <= dataIn;
                end
            end
        end

        if(read) begin
            if(itemCount == 0) begin
                dataAvailable <= 0;
            end else begin
                dataAvailable <= 1;
                nodeNum <= readIndex;
                readIndex <= readIndex + 1;
                itemCount <= itemCount - 1;
                if(readIndex == DEPTH) begin
                    readIndex <= 0;
                    loopCount <= loopCount + 1;
                    if(loopCount == LOOP) begin
                        loopCount <= 0;
                        largestVal <= 0;
                    end
                end
            end
        end
    end

endmodule

