module tb_crc_mem;

   // Inputs
   reg clk;

   // Outputs
   wire [63:0] outData;

   // Instantiate the Unit Under Test (UUT)
   crc_mem uut (
      .clk(clk),
      .outData(outData)
   );

   // Initialize Inputs
   initial begin
      clk = 0;
   end

   // Toggle clock every 10 time units
   always #5 clk = ~clk;

   // Check output at each clock cycle
   integer i;
   initial begin
      for (i = 0; i < 100; i = i + 1) begin
         #10;
         if (i == 90) begin
            if (outData !== 64'h1265e3bddcd9bc27) begin
               $display("Error at cycle %d: Expected outData = 64'h1265e3bddcd9bc27, Actual outData = %h", i, outData);
               $stop;
            end
         end
         else if (i == 91) begin
            if (outData !== 64'h24cbc77bb9b3784e) begin
               $display("Error at cycle %d: Expected outData = 64'h24cbc77bb9b3784e, Actual outData = %h", i, outData);
               $stop;
            end
         end
         else if (i == 99) begin
            $display("*-* All Finished *-*");
            $finish;
         end
      end
   end

endmodule

module top_module( 
    input [99:0] a, b,
    input cin,
    output [99:0] sum,
    output cout,
    output [99:0] xor_out );

    wire [99:0] p, g, c, s;
    wire [99:0] c_in, c_out;

    // Generate and propagate signals for carry lookahead adder
    assign p = a & b;
    assign g = a | b;
    assign c_in[0] = cin;
    assign c = p | (g & c_in);
    assign s = a ^ b ^ c_in;

    // Ripple carry adder for the final carry-out
    genvar i;
    generate
        for (i = 1; i < 100; i = i + 1) begin : ripple_carry
            full_adder fa(
                .a(s[i-1]),
                .b(c[i-1]),
                .cin(c_in[i]),
                .sum(s[i]),
                .cout(c_out[i])
            );
        end
    endgenerate

    // Final carry-out and sum
    assign cout = c_out[99];
    assign sum = {c_out[98:0], s[99]};

    // XOR module for final output
    xor_module xor_inst(
        .a(sum),
        .b(cout),
        .xor_out(xor_out)
    );

endmodule

// Full adder module for ripple carry adder
module full_adder(
    input a, b, cin,
    output sum, cout
);

    assign sum = a ^ b ^ cin;
    assign cout = (a & b) | (a & cin) | (b & cin);

endmodule

// XOR module for final output
module xor_module(
    input [99:0] a, b,
    output [99:0] xor_out
);

    assign xor_out = a ^ b;

endmodule

module custom_op(
    input [15:0] in_value,
    input [15:0] mask_value,
    input [3:0] shift_value,
    input [2:0] op_select,
    output [15:0] out_value
);

reg [15:0] temp_value;

always @(*) begin
    case(op_select)
        3'b000: temp_value = in_value & mask_value;
        3'b001: temp_value = in_value | mask_value;
        3'b010: temp_value = in_value ^ mask_value;
        3'b011: temp_value = in_value << shift_value;
        3'b100: temp_value = in_value >> shift_value;
        default: temp_value = in_value;
    endcase
end

assign out_value = temp_value;

endmodule

