module SPI_IF( 
    input clk,
    input rst,
    input [6:0] mpu_address,
    input [7:0] mpu_wr_data,
    input mpu_rd_wr_sel,
    input start,
    output busy,
    output SPI_SS_g,
    output SPI_CK_g,
    output SPI_DO_g,
    input SPI_DI_g,
    output [7:0] mpu_rd_data
);

reg [7:0] mpu_rd_data_buff;
reg [7:0] SPIstate;
reg [11:0] counter;
reg MPUclk;
reg do_reg;
reg ss_reg;
reg ck_reg;
reg busy_bf;
reg [4:0] i;
reg [4:0] j;

parameter SPI_HALF_CLK = 50;
parameter SPI_CLK = SPI_HALF_CLK*2;

wire halfCLKpassed = (counter == SPI_HALF_CLK-1);

always@(posedge clk)
begin
    if(rst)
    begin
        counter <= 0;
        MPUclk <= 0;
    end
    else
    begin
        if(start==1) begin
            counter <= 0;       
            MPUclk <= 1;            
        end
        else if(halfCLKpassed)begin           
            counter <= 0;       
            MPUclk <= ~MPUclk;
            end
        else begin
            counter <= counter + 1;
        end
    end
end

always @(posedge clk)
    begin
        if(rst)
        begin
            SPIstate = 0;
        end
        else
        begin        
            case(SPIstate)
                0:if(start == 1) SPIstate = 1;
                1:SPIstate = 3;
                3:begin
                    if(i==0 && mpu_rd_wr_sel == 1)SPIstate = 4;
                    if(i==0 && mpu_rd_wr_sel == 0)SPIstate = 5;
                end
                4:if(j==0)SPIstate = 6;
                5:if(j==0)SPIstate = 6;
                6:if(halfCLKpassed)SPIstate = 7;
                7:SPIstate = 0;
            endcase
        end
    end

always @ (posedge clk)
begin 
    if(rst)
        begin
            do_reg = 0;
            ck_reg = 1;
            ss_reg = 1;
            busy_bf = 0;
            mpu_rd_data_buff = 0;
            i = 16;
            j = 17;
        end
    else
        case(SPIstate)
            0:begin
                do_reg = 0;
                ss_reg = 1; 
                busy_bf = 0;
               i = 16;
                j = 17;
              end
            1:begin
                    busy_bf = 1;
                    ss_reg = 0;
                    end
            3:begin
                if(halfCLKpassed)
                begin
                    case (i)
                        16:do_reg = mpu_rd_wr_sel;
                        14:do_reg = mpu_address[6];
                        12:do_reg = mpu_address[5];
                        10:do_reg = mpu_address[4];
                        8: do_reg = mpu_address[3];
                        6: do_reg = mpu_address[2];
                        4: do_reg = mpu_address[1];
                        2: do_reg = mpu_address[0];
                        0: do_reg = 0;
                    endcase
                    if(i!=0) i=i-1;
                end
              end
            4:begin
                if(halfCLKpassed)
                begin
                    case (j)
                        16:mpu_rd_data_buff[7] = SPI_DI_g;
                        14:mpu_rd_data_buff[6] = SPI_DI_g;
                        12:mpu_rd_data_buff[5] = SPI_DI_g;
                        10:mpu_rd_data_buff[4] = SPI_DI_g;
                        8:mpu_rd_data_buff[3] = SPI_DI_g;
                        6:mpu_rd_data_buff[2] = SPI_DI_g;
                        4:mpu_rd_data_buff[1] = SPI_DI_g;
                        2:mpu_rd_data_buff[0] = SPI_DI_g;                     
                    endcase
                    if(j!=0) j=j-1;
                end
            end 
            5:begin
                if(halfCLKpassed)
                begin
                    case (j)
                        16:do_reg = mpu_wr_data[7]; 
                        14:do_reg = mpu_wr_data[6]; 
                        12:do_reg = mpu_wr_data[5]; 
                        10:do_reg = mpu_wr_data[4]; 
                        8:do_reg = mpu_wr_data[3]; 
                        6:do_reg = mpu_wr_data[2]; 
                        4:do_reg = mpu_wr_data[1]; 
                        2:do_reg = mpu_wr_data[0]; 
                        0:do_reg = 0;
                    endcase
                    if(j!=0) j=j-1;
                end
            end
            6:begin
                ck_reg =1;
                do_reg =0;
                ss_reg = 1;
              end
            7:begin
                mpu_rd_data_buff = mpu_rd_data_buff;
            end
        endcase
end

assign SPI_DO_g = do_reg;
assign SPI_CK_g = MPUclk | ss_reg;
assign SPI_SS_g = ss_reg;
assign busy = busy_bf | start;
assign mpu_rd_data = mpu_rd_data_buff;
endmodule

module DDC (
  input clk,
  input reset,
  input [15:0] data_in,
  input [31:0] freq,
  input [7:0] dec_factor,
  output reg [15:0] data_out,
  output reg [31:0] out_freq
);

  // Internal signals
  reg [15:0] filtered_data;
  reg [31:0] counter;

  // Low-pass filter
  always @(posedge clk) begin
    if (reset) begin
      filtered_data <= 16'h0;
    end else begin
      filtered_data <= (data_in + filtered_data) >> 1;
    end
  end

  // Down-sampling
  always @(posedge clk) begin
    if (reset) begin
      counter <= 32'h0;
      data_out <= 16'h0;
    end else begin
      counter <= counter + 1;
      if (counter == dec_factor - 1) begin
        counter <= 32'h0;
        data_out <= filtered_data;
      end
    end
  end

  // Output frequency
  assign out_freq = freq / dec_factor;

endmodule

module DUC (
  input clk,
  input reset,
  input [15:0] data_in,
  input [31:0] freq,
  input [7:0] interp_factor,
  output reg [15:0] data_out,
  output reg [31:0] out_freq
);

  // Internal signals
  reg [15:0] upsampled_data;
  reg [31:0] counter;

  // Up-sampling
  always @(posedge clk) begin
    if (reset) begin
      counter <= 32'h0;
      upsampled_data <= 16'h0;
    end else begin
      counter <= counter + 1;
      if (counter == interp_factor - 1) begin
        counter <= 32'h0;
        upsampled_data <= data_in;
      end else begin
        upsampled_data <= 16'h0;
      end
    end
  end

  // Digital filter
  always @(posedge clk) begin
    if (reset) begin
      data_out <= 16'h0;
    end else begin
      data_out <= (upsampled_data + data_out) >> 1;
    end
  end

  // Output frequency
  assign out_freq = freq * interp_factor;

endmodule

module top_module( 
    input [99:0] in,
    output out_and,
    output out_or,
    output out_xor 
);

// First pipeline stage
reg [99:0] stage1_and [0:3];
reg [99:0] stage1_or [0:3];
reg [99:0] stage1_xor [0:3];

// Second pipeline stage
reg [99:0] stage2_and [0:1];
reg [99:0] stage2_or [0:1];
reg [99:0] stage2_xor [0:1];

// Third pipeline stage
reg [99:0] stage3_and;
reg [99:0] stage3_or;
reg [99:0] stage3_xor;

// Multiplexers for stage 1
wire [99:0] mux1_and_out [0:3];
wire [99:0] mux1_or_out [0:3];
wire [99:0] mux1_xor_out [0:3];

// Multiplexers for stage 2
wire [99:0] mux2_and_out [0:1];
wire [99:0] mux2_or_out [0:1];
wire [99:0] mux2_xor_out [0:1];

// AND gates for stage 3
wire [99:0] and_out;
and and_gate (and_out, stage3_and);

// OR gates for stage 3
wire [99:0] or_out;
or or_gate (or_out, stage3_or);

// XOR gates for stage 3
wire [99:0] xor_out;
xor xor_gate (xor_out, stage3_xor);

// Pipeline stage 1: 4:1 multiplexers
genvar i;
generate
    for (i = 0; i < 4; i = i + 1) begin : stage1_muxes
        mux4to1 mux1_and (
            .in0 (stage1_and[i*4 + 0]),
            .in1 (stage1_and[i*4 + 1]),
            .in2 (stage1_and[i*4 + 2]),
            .in3 (stage1_and[i*4 + 3]),
            .sel (in[i*25 +: 25]),
            .out (mux1_and_out[i])
        );

        mux4to1 mux1_or (
            .in0 (stage1_or[i*4 + 0]),
            .in1 (stage1_or[i*4 + 1]),
            .in2 (stage1_or[i*4 + 2]),
            .in3 (stage1_or[i*4 + 3]),
            .sel (in[i*25 +: 25]),
            .out (mux1_or_out[i])
        );

        mux4to1 mux1_xor (
            .in0 (stage1_xor[i*4 + 0]),
            .in1 (stage1_xor[i*4 + 1]),
            .in2 (stage1_xor[i*4 + 2]),
            .in3 (stage1_xor[i*4 + 3]),
            .sel (in[i*25 +: 25]),
            .out (mux1_xor_out[i])
        );
    end
endgenerate

// Pipeline stage 2: 4:1 multiplexers
mux4to1 mux2_and0 (
    .in0 (mux1_and_out[0]),
    .in1 (mux1_and_out[1]),
    .in2 (mux1_and_out[2]),
