module fsm_3bit_sequence_detection (
  input clk,
  input reset,
  input data,
  output reg match
);

  parameter S0 = 2'b00;
  parameter S1 = 2'b01;
  parameter S2 = 2'b10;
  parameter S3 = 2'b11;

  reg [1:0] state = S0;
  reg [2:0] shift_reg = 3'b000;

  always @(posedge clk) begin
    if (reset) begin
      state <= S0;
      shift_reg <= 3'b000;
      match <= 1'b0;
    end
    else begin
      case (state)
        S0: begin
          if (data) begin
            shift_reg <= {shift_reg[1:0], 1'b1};
            state <= S1;
          end
          else begin
            shift_reg <= 3'b000;
            state <= S0;
          end
        end
        S1: begin
          if (data) begin
            shift_reg <= {shift_reg[1:0], 1'b1};
            state <= S2;
          end
          else begin
            shift_reg <= 3'b000;
            state <= S0;
          end
        end
        S2: begin
          if (data) begin
            shift_reg <= {shift_reg[1:0], 1'b1};
            state <= S3;
          end
          else begin
            shift_reg <= 3'b000;
            state <= S0;
          end
        end
        S3: begin
          match <= 1'b1;
          shift_reg <= 3'b000;
          state <= S0;
        end
      endcase
    end
  end
endmodule

