module calculator (
    input clk,
    input rst,
    input [2:0] control,
    input [3:0] operand_1,
    input [3:0] operand_2,
    input write_en,
    input [2:0] write_addr,
    input [3:0] write_data,
    input read_en,
    input [2:0] read_addr,
    output reg [3:0] result
);

    reg [3:0] operand_1_reg;
    reg [3:0] operand_2_reg;
    reg [2:0] control_reg;
    reg [3:0] result_reg;

    // Dual-port RAM with a depth of 8 and a bit width of 4 bits
    reg [3:0] ram[0:7];

    // Write port
    always @ (posedge clk) begin
        if (rst) begin
            operand_1_reg <= 4'b0;
            operand_2_reg <= 4'b0;
            control_reg <= 3'b0;
            ram <= 8'b0;
        end else if (write_en) begin
            ram[write_addr] <= write_data;
        end
    end

    // Read port
    always @ (posedge clk) begin
        if (rst) begin
            result_reg <= 4'b0;
        end else if (read_en) begin
            operand_1_reg <= ram[read_addr];
            operand_2_reg <= ram[read_addr+1];
            control_reg <= ram[read_addr+2];
        end
    end

    // Calculator logic
    always @ (posedge clk) begin
        if (rst) begin
            result_reg <= 4'b0;
        end else begin
            case (control_reg)
                3'b000: result_reg <= operand_1_reg + operand_2_reg;
                3'b001: result_reg <= operand_1_reg - operand_2_reg;
                default: result_reg <= 4'b0;
            endcase
        end
    end

    // Output result
    always @ (posedge clk) begin
        if (rst) begin
            result <= 4'b0;
        end else begin
            result <= result_reg;
        end
    end

endmodule

