);

   reg [2:0] shift_reg;
   reg [1:0] flip_flop;

   always @(posedge clk or negedge clk) begin
      if (reset) begin
         shift_reg <= 3'b0;
         flip_flop <= 2'b0;
         count <= 3'b0;
