module mem_controller (
  input clk,
  input rst,
  input [n-1:0] addr,
  input [m-1:0] data_in,
  input write_enable,
  input read_enable,
  output [m-1:0] data_out
);

parameter n = 8; // number of address bits
parameter m = 16; // number of data bits

reg [m-1:0] mem [2**n-1:0];
reg [m-1:0] data_out_reg;
reg [1:0] state;

always @(posedge clk) begin
  if (rst) begin
    state <= 2'b00;
    data_out_reg <= 0;
  end else begin
    case (state)
      2'b00: begin // Idle state
        if (write_enable) begin
          state <= 2'b01;
        end else if (read_enable) begin
          state <= 2'b10;
        end
      end
      2'b01: begin // Write state
        mem[addr] <= data_in;
        state <= 2'b00;
      end
      2'b10: begin // Read state
        data_out_reg <= mem[addr];
        state <= 2'b00;
      end
    endcase
  end
end

assign data_out = read_enable ? data_out_reg : 'bz;

endmodule

module reverse_byte_order(
