assign byte1 = in[15:8];
assign byte2 = in[23:16];
assign byte3 = in[31:24];

// Reverse byte order using shift registers and multiplexers
reg [7:0] shift0, shift1, shift2, shift3;
always @(*) begin
    shift0 = byte3;
    shift1 = byte2;
    shift2 = byte1;
    shift3 = byte0;
end

assign out[7:0] = shift0;
assign out[15:8] = shift1;
assign out[23:16] = shift2;
assign out[31:24] = shift3;

endmodule

