  input load,
  input [WIDTH-1:0] D,
  output [WIDTH-1:0] Q
);

  reg [WIDTH-1:0] regs [0:DEPTH-1];
  reg [WIDTH:0] sum;

  integer i;

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      for (i = 0; i < DEPTH; i = i + 1) begin
        regs[i] <= 0;
      end
      sum <= 0;
    end else if (load) begin
      for (i = 0; i < DEPTH; i = i + 1) begin
        regs[i] <= D[i];
      end
    end else begin
      for (i = 0; i < DEPTH; i = i + 1) begin
        sum <= sum + {1'b0, regs[i]};
      end
      Q <= sum[WIDTH-1:0];
    end
  end

endmodule

