    reg [2:0] ssp_frame_divider_to_arm;
    reg [2:0] ssp_frame_divider_from_arm;
    reg [7:0] modulating_carrier_divider;
    reg modulating_carrier;

    always @(posedge clk) begin
        adc_clk <= ~adc_clk;
    end

    always @(negedge adc_clk) begin
        if(mod_type == 3'b100) begin
            if(adc_d >= 8'd224) begin
                ssp_din <= 1'b1;
            end else if(adc_d <= 8'd31) begin
                ssp_din <= 1'b0;
            end
        end else begin
            ssp_din <= 1'b0;
        end
    end

    always @(posedge clk) begin
        ssp_clk_divider <= ssp_clk_divider + 1;
        modulating_carrier_divider <= modulating_carrier_divider + 1;
    end

    always @(negedge clk) begin
        if(mod_type == 3'b100) begin
            ssp_clk <= ssp_clk_divider[4];
            ssp_frame_divider_from_arm <= ssp_frame_divider_from_arm + 1;
            if(ssp_frame_divider_to_arm == 3'b000) begin
                ssp_frame <= 1'b1;
            end else begin
                ssp_frame <= 1'b0;
            end
        end else begin
            ssp_clk <= ssp_clk_divider[3];
            ssp_frame_divider_to_arm <= ssp_frame_divider_to_arm + 1;
            if(ssp_frame_divider_from_arm == 3'b000) begin
                ssp_frame <= 1'b1;
            end else begin
                ssp_frame <= 1'b0;
            end
        end
    end

    always @(*) begin
        if(mod_type == 3'b100) begin
            if(ssp_dout == 1'b0) begin
                modulating_carrier <= 1'b0;
            end else if(ssp_dout == 1'b1) begin
                if(modulating_carrier_divider[6] == 1'b0) begin
                    modulating_carrier <= 1'b1;
                end else begin
                    modulating_carrier <= 1'b0;
                end
            end
        end else begin
            modulating_carrier <= 1'b0;
        end
    end

    always @(*) begin
        if(mod_type == 3'b100) begin
            pwr_lo <= 1'b0;
            pwr_hi <= 1'b0;
            pwr_oe1 <= modulating_carrier;
            pwr_oe2 <= 1'b0;
            pwr_oe3 <= 1'b0;
            pwr_oe4 <= modulating_carrier;
        end else if(mod_type == 3'b010) begin
            pwr_lo <= 1'b0;
            pwr_hi <= 1'b0;
            pwr_oe1 <= ssp_din;
            pwr_oe2 <= 1'b0;
            pwr_oe3 <= 1'b0;
            pwr_oe4 <= 1'b0;
