            pwr_lo <= 1'b0;
            pwr_hi <= 1'b0;
            pwr_oe1 <= 1'b0;
            pwr_oe2 <= 1'b0;
            pwr_oe3 <= 1'b1;
            pwr_oe4 <= 1'b0;
        end else if(mod_type == 3'b000) begin
            pwr_lo <= 1'b0;
            pwr_hi <= 1'b1;
            pwr_oe1 <= 1'b0;
            pwr_oe2 <= 1'b0;
            pwr_oe3 <= 1'b0;
            pwr_oe4 <= 1'b0;
