        for (i = 1; i < 17; i = i + 1) begin : buf_chain
            buf #(0.25) buf_inst (.Z(buf_out[i]), .A(buf_out[i-1]));
        end
    endgenerate

    // Output buffer
    buf #(0.25) buf_inst (.Z(X), .A(buf_out[16]));

endmodule

module audio_serializer(
    input clk,
    input reset,
    input bit_clk_rising_edge,
    input bit_clk_falling_edge,
    input left_right_clk_rising_edge,
    input left_right_clk_falling_edge,
    input [15:0] left_channel_data,
    input left_channel_data_en,
    input [15:0] right_channel_data,
    input right_channel_data_en,
    output reg [7:0] left_channel_fifo_write_space,
    output reg [7:0] right_channel_fifo_write_space,
    output reg serial_audio_out_data
);

parameter AUDIO_DATA_WIDTH = 16;

// Internal wires and registers Declarations
wire read_left_channel;
wire read_right_channel;
wire left_channel_fifo_is_empty;
wire right_channel_fifo_is_empty;
wire left_channel_fifo_is_full;
wire right_channel_fifo_is_full;
wire [6:0] left_channel_fifo_used;
wire [6:0] right_channel_fifo_used;
wire [AUDIO_DATA_WIDTH:1] left_channel_from_fifo;
wire [AUDIO_DATA_WIDTH:1] right_channel_from_fifo;
reg left_channel_was_read;
reg [AUDIO_DATA_WIDTH:1] data_out_shift_reg;

// State Machine Registers
reg [1:0] state;
localparam IDLE = 2'b00;
localparam LEFT_CHANNEL = 2'b01;
localparam RIGHT_CHANNEL = 2'b10;

// Internal Modules
altsyncram left_channel_fifo (
    .clock0(clk),
    .addressa({left_channel_fifo_used, 1'b0}),
    .wren_a(left_channel_data_en & ~left_channel_fifo_is_full),
    .data_a(left_channel_data),
    .q_a(left_channel_from_fifo),
    .fulla(left_channel_fifo_is_full),
    .emptya(left_channel_fifo_is_empty),
    .addressb({left_channel_fifo_used, 1'b1}),
    .q_b(),
    .fullb(),
    .emptyb(),
    .byteena(2'b11),
    .clocken(1'b1),
    .clocken_a(1'b1),
    .clocken_b(1'b1),
    .powerup(1'b0),
    .powerrst(1'b0),
    .rst(1'b0),
    .we(1'b0)
);
altsyncram right_channel_fifo (
    .clock0(clk),
    .addressa({right_channel_fifo_used, 1'b0}),
    .wren_a(right_channel_data_en & ~right_channel_fifo_is_full),
    .data_a(right_channel_data),
    .q_a(right_channel_from_fifo),
    .fulla(right_channel_fifo_is_full),
    .emptya(right_channel_fifo_is_empty),
    .addressb({right_channel_fifo_used, 1'b1}),
    .q_b(),
    .fullb(),
    .emptyb(),
    .byteena(2'b11),
    .clocken(1'b1),
    .clocken_a(1'b1),
    .clocken_b(1'b1),
    .powerup(1'b0),
    .powerrst(1'b0),
    .rst(1'b0),
    .we(1'b0)
);

// Sequential logic
always @(posedge clk) begin
    if (reset == 1'b1) begin
        left_channel_fifo_write_space <= 8'h00;
    end else begin
        left_channel_fifo_write_space <= 8'h80 - {left_channel_fifo_is_full,left_channel_fifo_used};
    end
end

always @(posedge clk) begin
    if (reset == 1'b1) begin
        right_channel_fifo_write_space <= 8'h00;
    end else begin
        right_channel_fifo_write_space <= 8'h80 - {right_channel_fifo_is_full,right_channel_fifo_used};
    end
end

always @(posedge clk) begin
    if (reset == 1'b1) begin
        serial_audio_out_data <= 1'b0;
    end else begin
        serial_audio_out_data <= data_out_shift_reg[AUDIO_DATA_WIDTH];
    end
end

always @(posedge clk) begin
    if (reset == 1'b1) begin
        left_channel_was_read <= 1'b0;
        state <= IDLE;
    end else begin
        case (state)
            IDLE: begin
                if (read_left_channel) begin
                    left_channel_was_read <= 1'b1;
                    state <= LEFT_CHANNEL;
                end else if (read_right_channel) begin
                    left_channel_was_read <= 1'b0;
                    state <= RIGHT_CHANNEL;
                end
            end
            LEFT_CHANNEL: begin
                if (bit_clk_falling_edge) begin
                    data_out_shift_reg <= {data_out_shift_reg[(AUDIO_DATA_WIDTH - 1):1], left_channel_from_fifo[1]};
                end
                if (left_right_clk_falling_edge) begin
                    state <= IDLE;
                end
            end
            RIGHT_CHANNEL: begin
                if (bit_clk_falling_edge) begin
                    data_out_shift_reg <= {data_out_shift_reg[(AUDIO_DATA_WIDTH - 1):1], right_channel_from_fifo[1]};
                end
                if (left_right_clk_falling_edge) begin
                    state <= IDLE;
                end
            end
        endcase
    end
end

// Combinational logic
assign read_left_channel = left_right_clk_rising_edge & ~left_channel_fifo_is_empty & ~right_channel_fifo_is_empty;
assign read_right_channel = left_right_clk_falling_edge & left_channel_was_read;

endmodule

module delay_buff #(parameter DELAY = 1) (
  input i,
  output o
);

  reg [DELAY-1:0] buffer [0:1];

  integer idx;

  always @(posedge clk) begin
    buffer[0][0] <= i;
    for (idx = 0; idx < DELAY-1; idx = idx + 1) begin
      buffer[0][idx+1] <= buffer[0][idx];
    end
    o <= buffer[1][DELAY-1];
    for (idx = 0; idx < DELAY-1; idx = idx + 1) begin
      buffer[1][idx] <= buffer[1][idx+1];
    end
    buffer[1][DELAY-1] <= buffer[0][DELAY-1];
  end

endmodule

module REG_LIST ( DIN, IPOS, INIT, OPOS, VALID);

	// Detects set bits in register list for SAVE/RESTORE & ENTER/EXIT

	input	 [7:0]	DIN;
	input	 [2:0]	IPOS;
	input			INIT;
	output	 [2:0]	OPOS;
	output			VALID;

	reg		 [7:1]	filter;
	wire	 [7:0]	mdat_0;
	wire	 [3:0]	mdat_1;
	wire	 [1:0]	mdat_2;

	always @(IPOS or DIN)
		case (IPOS)
		  3'd0 : filter =  DIN[7:1];
		  3'd1 : filter = {DIN[7:2],1'b0};
		  3'd2 : filter = {DIN[7:3],2'b0};
		  3'd3 : filter = {DIN[7:4],3'b0};
		  3'd4 : filter = {DIN[7:5],4'b0};
		  3'd5 : filter = {DIN[7:6],5'b0};
		  3'd6 : filter = {DIN[7]  ,6'b0};
		  3'd7 : filter =           7'b0;
		endcase

	assign mdat_0  = INIT ? DIN : {filter,1'b0};
	assign OPOS[2] = (mdat_0[3:0] == 4'h0);
	assign mdat_1  = OPOS[2] ? mdat_0[7:4] : mdat_0[3:0];
	assign OPOS[1] = (mdat_1[1:0] == 2'b00);
	assign mdat_2  = OPOS[1] ? mdat_1[3:2] : mdat_1[1:0];
	assign OPOS[0] = ~mdat_2[0];
	assign VALID   = (mdat_2 != 2'b00);

endmodule

module bitwise_ops (
  input [n-1:0] in1,
  input [n-1:0] in2,
  output [n-1:0] out_AND,
  output [n-1:0] out_OR,
  output [n-1:0] out_XOR,
  output [n-1:0] out_NOT
);

parameter n = 8; // number of input bits

assign out_AND = in1 & in2;
assign out_OR = in1 | in2;
assign out_XOR = in1 ^ in2;
assign out_NOT = ~in1;

endmodule

module limbus_nios2_qsys_0_nios2_oci_im (
  // inputs:
  clk,
  jdo,
  jrst_n,
  reset_n,
  take_action_tracectrl,
  take_action_tracemem_a,
  take_action_tracemem_b,
  take_no_action_tracemem_a,
  trc_ctrl,
  tw,

  // outputs:
  tracemem_on,
  tracemem_trcdata,
  tracemem_tw,
  trc_enb,
  trc_im_addr,
  trc_wrap,
  xbrk_wrap_traceoff
);

  output tracemem_on;
  output [35:0] tracemem_trcdata;
  output tracemem_tw;
  output trc_enb;
  output [6:0] trc_im_addr;
  output trc_wrap;
  output xbrk_wrap_traceoff;
  input clk;
  input [37:0] jdo;
  input jrst_n;
  input reset_n;
  input take_action_tracectrl;
  input take_action_tracemem_a;
  input take_action_tracemem_b;
  input take_no_action_tracemem_a;
  input [15:0] trc_ctrl;
  input [35:0] tw;

  wire tracemem_on;
  wire [35:0] tracemem_trcdata;
  wire tracemem_tw;
  wire trc_enb;
  reg [6:0] trc_im_addr /* synthesis ALTERA_ATTRIBUTE = "SUPPRESS_DA_RULE_INTERNAL=\"D101,D103,R101\""  */;
  wire [35:0] trc_im_data;
  reg [16:0] trc_jtag_addr /* synthesis ALTERA_ATTRIBUTE = "SUPPRESS_DA_RULE_INTERNAL=D101"  */;
  wire trc_on_chip;
  reg trc_wrap /* synthesis ALTERA_ATTRIBUTE = "SUPPRESS_DA_RULE_INTERNAL=\"D101,D103,R101\""  */;
  wire tw_valid;
  wire xbrk_wrap_traceoff;
  assign trc_im_data = tw;

  always @(posedge clk or negedge jrst_n) begin
    if (jrst_n == 0) begin
      trc_im_addr <= 0;
      trc_wrap <= 0;
    end else if (!take_action_tracectrl) begin
      if (jdo[4] | jdo[3]) begin
        if (jdo[4]) trc_im_addr <= 0;
        if (jdo[3]) trc_wrap <= 0;
      end else if (trc_enb & trc_on_chip & tw_valid) begin
        trc_im_addr <= trc_im_addr + 1;
        if (&trc_im_addr) trc_wrap <= 1;
      end
    end
  end

  always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
      trc_jtag_addr <= 0;
    end else if (take_action_tracemem_a | take_no_action_tracemem_a | take_action_tracemem_b) begin
      trc_jtag_addr <= take_action_tracemem_a ? jdo[35:19] : trc_jtag_addr + 1;
    end
  end

  assign trc_enb = trc_ctrl[0];
  assign trc_on_chip = ~trc_ctrl[8];
  assign tw_valid = |trc_im_data[35:32];
  assign xbrk_wrap_traceoff = trc_ctrl[10] & trc_wrap;
  assign tracemem_tw = trc_wrap;
  assign tracemem_on = trc_enb;
  assign tracemem_trcdata = 0;

endmodule

module RetimingBlock (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 4; // number of input signals
parameter m = 4; // number of output signals
parameter delay = 2; // number of clock cycles of delay

reg [n-1:0] shift_reg [0:delay-1];

integer i;

always @(posedge clk) begin
  for (i = delay-1; i > 0; i = i - 1) begin
    shift_reg[i] <= shift_reg[i-1];
  end
  shift_reg[0] <= in;
end

assign out = shift_reg[delay-1];

endmodule

module ADC (
  input clk,
  input input_signal,
  output reg [7:0] digital_output
);

parameter clk_frequency = 1000000; // 1MHz
parameter sampling_rate = 1000; // 1kHz
parameter counter_max = clk_frequency / sampling_rate;

reg [15:0] counter = 0;
reg [15:0] quantized_signal;

always @(posedge clk) begin
  counter <= counter + 1;
  if (counter == counter_max) begin
    counter <= 0;
    quantized_signal <= (input_signal * 255) / 5;
    digital_output <= quantized_signal[7:0];
  end
end


endmodule

module clock_gate (CLK, EN, TE, ENCLK);
  input CLK, EN, TE;
  output ENCLK;

  reg ENCLK;

  always @ (posedge CLK) begin
    if (EN && TE) begin
      ENCLK <= 1'b1;
    end else begin
      ENCLK <= 1'b0;
    end
  end

endmodule

module mux_pipeline(
