always @(posedge sel_b1 or posedge sel_b2) begin
    mux_out1 <= a;
    mux_out2 <= b;
end

always @(posedge sel_b1 or posedge sel_b2) begin
    if(sel_b1 & sel_b2) begin
        out_always <= mux_out2;
    end else begin
        out_always <= mux_out1;
    end
end

endmodule

