module ripple_carry_carry_save_adder(
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] sum
);

    wire [31:0] ripple_carry_sum;
    wire [31:0] carry_save_sum;
    wire [31:0] carry_out;

    // 32-bit Ripple Carry Adder
    ripple_carry_adder adder(
        .a(a),
        .b(b),
        .sum(ripple_carry_sum),
        .carry_out(carry_out)
    );

    // 32-bit Carry Save Adder
    carry_save_adder csa(
        .a(a),
        .b(b),
        .sum(carry_save_sum),
        .carry_out(carry_out)
    );

    // XOR gate to invert b input when sub is 1
    wire [31:0] inverted_b;
    assign inverted_b = (sub == 1) ? ~b : b;

    // Select output based on sub input
    assign sum = (sub == 1) ? ripple_carry_sum + inverted_b + 1 : ripple_carry_sum + carry_save_sum;

endmodule

module ripple_carry_adder(
    input [31:0] a,
    input [31:0] b,
    output [31:0] sum,
    output carry_out
);

    genvar i;
    wire [31:0] carry;

    generate
        for (i = 0; i < 32; i = i + 1) begin : adder_stage
            full_adder fa(
                .a(a[i]),
                .b(b[i]),
                .carry_in(carry[i]),
                .sum(sum[i]),
                .carry_out(carry[i+1])
            );
        end
    endgenerate

    assign carry_out = carry[32];

endmodule

module carry_save_adder(
    input [31:0] a,
    input [31:0] b,
    output [31:0] sum,
    output carry_out
);

    wire [31:0] carry;

    // First stage
    full_adder fa1(
        .a(a[0]),
        .b(b[0]),
        .carry_in(1),
        .sum(sum[0]),
        .carry_out(carry[0])
    );

    // Middle stages
    genvar i;
    generate
        for (i = 1; i < 31; i = i + 1) begin : adder_stage
            full_adder fa(
                .a(a[i]),
                .b(b[i]),
                .carry_in(carry[i-1]),
                .sum(sum[i]),
                .carry_out(carry[i])
            );
        end
    endgenerate

    // Last stage
    full_adder fa2(
        .a(a[31]),
        .b(b[31]),
        .carry_in(carry[30]),
        .sum(sum[31]),
        .carry_out(carry_out)
    );

endmodule

module full_adder(
    input a,
    input b,
    input carry_in,
    output sum,
    output carry_out
);

    assign {carry_out, sum} = a + b + carry_in;

endmodule

