module Debouncer (
  input in,
  output out
);

parameter debounce_time = 50; // debounce time in microseconds

reg [1:0] state;
reg out_reg;
reg [31:0] debounce_timer;

localparam IDLE = 2'b00;
localparam WAIT_HIGH = 2'b01;
localparam WAIT_LOW = 2'b10;

always @(posedge in or negedge in) begin
  case (state)
    IDLE: begin
      if (in) begin
        debounce_timer <= debounce_time;
        state <= WAIT_HIGH;
      end else begin
        debounce_timer <= debounce_time;
        state <= WAIT_LOW;
      end
    end
    WAIT_HIGH: begin
      if (in) begin
        if (debounce_timer == 0) begin
          out_reg <= 1;
          state <= IDLE;
        end else begin
          debounce_timer <= debounce_timer - 1;
        end
      end else begin
        debounce_timer <= debounce_time;
        state <= WAIT_LOW;
      end
    end
    WAIT_LOW: begin
      if (!in) begin
        if (debounce_timer == 0) begin
          out_reg <= 0;
          state <= IDLE;
        end else begin
          debounce_timer <= debounce_timer - 1;
        end
      end else begin
        debounce_timer <= debounce_time;
        state <= WAIT_HIGH;
      end
    end
  endcase
end

assign out = out_reg;

endmodule

