    always @(*) begin
        if (S == 2'b00) begin
            Y = D[0];
        end else if (S == 2'b01) begin
            Y = D[1];
        end else if (S == 2'b10) begin
            Y = D[2];
        end else begin // S == 2'b11
            Y = D[3];
        end
    end

endmodule

module add_sub_carry(
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] sum,
    output carry_out
);

    wire [31:0] a_inv;
    wire [31:0] b_inv;
    wire [31:0] b_neg;
    wire [31:0] carry_in;
    wire [31:0] carry_out_add;
    wire [31:0] carry_out_sub;

    assign a_inv = ~a;
    assign b_inv = ~b;
    assign b_neg = b_inv + 1;
    assign carry_in = sub ? 1 : 0;

    adder adder_inst(
        .a(a),
        .b(b),
        .carry_in(carry_in),
        .sum(sum),
        .carry_out(carry_out_add)
    );

    adder sub_inst(
        .a(a),
        .b(b_neg),
        .carry_in(carry_in),
        .sum(sum),
        .carry_out(carry_out_sub)
    );

    assign carry_out = sub ? ~carry_out_sub : carry_out_add;

endmodule

module combiner(
    input wire [7:0] in_hi,
    input wire [7:0] in_lo,
    output wire [15:0] out
);

    assign out = {in_hi, in_lo};

endmodule

module full_adder(
    input wire a,
    input wire b,
    input wire cin,
    output reg sum,
    output reg cout
);

    always @ (a or b or cin)
        begin
            sum = a ^ b ^ cin;
            cout = (a & b) | (a & cin) | (b & cin);
        end

endmodule

module functional_module(
    input wire [15:0] in1,
    input wire [15:0] in2,
    input wire select,
    output wire [15:0] out
);

    wire [15:0] comb_out;
    wire [15:0] adder_out;

    combiner comb(
        .in_hi(in1[15:8]),
        .in_lo(in1[7:0]),
        .out(comb_out)
    );

    full_adder adder(
        .a(in2[0]),
        .b(comb_out[0]),
        .cin(select),
        .sum(adder_out[0]),
        .cout()
    );

    genvar i;

    generate
        for (i = 1; i < 16; i = i + 1) begin : adder_gen
            full_adder adder_inst(
                .a(in2[i]),
                .b(comb_out[i]),
                .cin(adder_out[i-1]),
                .sum(adder_out[i]),
                .cout()
            );
        end
    endgenerate

    assign out = adder_out;

endmodule

module top_module( 
    input wire [7:0] in_hi,
    input wire [7:0] in_lo,
    input wire select,
    input wire a,
    input wire b,
    input wire cin,
    output wire [15:0] out
);

    wire [15:0] comb_out;
    wire [15:0] adder_out;

    combiner comb(
        .in_hi(in_hi),
        .in_lo(in_lo),
        .out(comb_out)
    );

    functional_module func(
        .in1(comb_out),
        .in2({a, b, cin}),
        .select(select),
        .out(adder_out)
    );

    assign out = adder_out;

endmodule

module top_module( 
    input [31:0] in,
    output out_and,
    output out_or,
    output out_xor,
    output final_out 
);

    wire [31:0] tree1_out, tree2_out, tree3_out, tree4_out, tree5_out;
    wire [4:0] priority_enc;
    wire [2:0] and_or_xor;

    // Instantiate the 5 binary trees
    binary_tree tree1(.in(in), .out(tree1_out));
    binary_tree tree2(.in(in), .out(tree2_out));
    binary_tree tree3(.in(in), .out(tree3_out));
    binary_tree tree4(.in(in), .out(tree4_out));
    binary_tree tree5(.in(in), .out(tree5_out));

    // Select the inputs using a 5-to-1 multiplexer
    mux_32_to_1 mux(.in({tree1_out, tree2_out, tree3_out, tree4_out, tree5_out}), .sel(priority_enc), .out(and_or_xor));

    // Use a priority encoder to determine the final output
    priority_encoder encoder(.in(and_or_xor), .out(priority_enc));

    // Output the AND, OR, and XOR results
    assign out_and = and_or_xor[2];
    assign out_or = and_or_xor[1];
    assign out_xor = and_or_xor[0];

    // Output the final result
    assign final_out = priority_enc != 5'b00000;

endmodule


module binary_tree(
    input [31:0] in,
    output [31:0] out
);

    wire [31:0] level1_1, level1_2, level2_1, level2_2, level3_1, level3_2, level4_1, level4_2, level5_1, level5_2;

    // Level 1
    and_gate and1(.in1(in[0]), .in2(in[1]), .out(level1_1[0]));
    and_gate and2(.in1(in[2]), .in2(in[3]), .out(level1_1[1]));
    and_gate and3(.in1(in[4]), .in2(in[5]), .out(level1_1[2]));
    and_gate and4(.in1(in[6]), .in2(in[7]), .out(level1_1[3]));
    and_gate and5(.in1(in[8]), .in2(in[9]), .out(level1_1[4]));
    and_gate and6(.in1(in[10]), .in2(in[11]), .out(level1_1[5]));
    and_gate and7(.in1(in[12]), .in2(in[13]), .out(level1_1[6]));
    and_gate and8(.in1(in[14]), .in2(in[15]), .out(level1_1[7]));
    and_gate and9(.in1(in[16]), .in2(in[17]), .out(level1_1[8]));
    and_gate and10(.in1(in[18]), .in2(in[19]), .out(level1_1[9]));
    and_gate and11(.in1(in[20]), .in2(in[21]), .out(level1_1[10]));
    and_gate and12(.in1(in[22]), .in2(in[23]), .out(level1_1[11]));
    and_gate and13(.in1(in[24]), .in2(in[25]), .out(level1_1[12]));
    and_gate and14(.in1(in[26]), .in2(in[27]), .out(level1_1[13]));
    and_gate and15(.in1(in[28]), .in2(in[29]), .out(level1_1[14]));
    and_gate and16(.in1(in[30]), .in2(in[31]), .out(level1_1[15]));

    // Level 2
    and_gate and17(.in1(level1_1[0]), .in2(level1_1[1]), .out(level2_1[0]));
    and_gate and18(.in1(level1_1[2]), .in2(level1_1[3]), .out(level2_1[1]));
    and_gate and19(.in1(level1_1[4]), .in2(level1_1[5]), .out(level2_1[2]));
    and_gate and20(.in1(level1_1[6]), .in2(level1_1[7]), .out(level2_1[3]));
    and_gate and21(.in1(level1_1[8]), .in2(level1_1[9]), .out(level2_1[4]));
    and_gate and22(.in1(level1_1[10]), .in2(level1_1[11]), .out(level2_1[5]));
    and_gate and23(.in1(level1_1[12]), .in2(level1_1[13]), .out(level2_1[6]));
    and_gate and24(.in1(level1_1[14]), .in2(level1_1[15]), .out(level2_1[7]));

    // Level 3
    and_gate and25(.in1(level2_1[0]), .in2(level2_1[1]), .out(level3_1[0]));
    and_gate and26(.in1(level2_1[2]), .in2(level2_1[3]), .out(level3_1[1]));
    and_gate and27(.in1(level2_1[4]), .in2(level2_1[5]), .out(level3_1[2]));
    and_gate and28(.in1(level2_1[6]), .in2(level2_1[7]), .out(level3_1[3]));

    // Level 4
    and_gate and29(.in1(level3_1[0]), .in2(level3_1[1]), .out(level4_1[0]));
    and_gate and30(.in1(level3_1[2]), .in2(level3_1[3]), .out(level4_1[1]));

    // Level 5
    and_gate and31(.in1(level4_1[0]), .in2(level4_1[1]), .out(level5_1[0]));

    // Inverters
    inverter inv1(.in(level1_1[0]), .out(level1_2[0]));
    inverter inv2(.in(level1_1[1]), .out(level1_2[1]));
    inverter inv3(.in(level1_1[2]), .out(level1_2[2]));
    inverter inv4(.in(level1_1[3]), .out(level1_2[3]));
    inverter inv5(.in(level1_1[4]), .out(level1_2[4]));
    inverter inv6(.in(level1_1[5]), .out(level1_2[5]));
    inverter inv7(.in(level1_1[6]), .out(level1_2[6]));
    inverter inv8(.in(level1_1[7]), .out(level1_2[7]));
    inverter inv9(.in(level1_1[8]), .out(level1_2[8]));
    inverter inv10(.in(level1_1[9]), .out(level1_2[9]));
    inverter inv11(.in(level1_1[10]), .out(level1_2[10]));
    inverter inv12(.in(level1_1[11]), .out(level1_2[11]));
    inverter inv13(.in(level1_1[12]), .out(level1_2[12]));
    inverter inv14(.in(level1_1[13]), .out(level1_2[13]));
    inverter inv15(.in(level1_1[14]), .out(level1_2[14]));
    inverter inv16(.in(level1_1[15]), .out(level1_2[15]));

    inverter inv17(.in(level2_1[0]), .out(level2_2[0]));
    inverter inv18(.in(level2_1[1]), .out(level2_2[1]));
    inverter inv19(.in(level2_1[2]), .out(level2_2[2]));
    inverter inv20(.in(level2_1[3]), .out(level2_2[3]));

    inverter inv21(.in(level3_1[0]), .out(level3_2[0]));
    inverter inv22(.in(level3_1[1]), .out(level3_2[1]));

    inverter inv23(.in(level4_1[0]), .out(level4_2[0]));

    inverter inv24(.in(level5_1[0]), .out(out));

endmodule


