module barrel_shifter (
    input [3:0] data_in,
    input [1:0] shift_amount,
    input mode,
    output reg [3:0] data_out
);

reg [3:0] stage1_out;
reg [3:0] stage2_out;

always @(*) begin
    case (mode)
        2'b00: stage1_out = data_in << shift_amount;
        2'b01: stage1_out = data_in >> shift_amount;
        2'b10: stage1_out = {data_in[1:0], data_in[3:2]};
        2'b11: stage1_out = {data_in[2:3], data_in[0:1]};
    endcase
end

always @(*) begin
    case (mode)
        2'b00: stage2_out = stage1_out << shift_amount;
        2'b01: stage2_out = stage1_out >> shift_amount;
        2'b10: stage2_out = {stage1_out[2:3], stage1_out[0:1]};
        2'b11: stage2_out = {stage1_out[1:0], stage1_out[3:2]};
    endcase
end

assign data_out = stage2_out;

endmodule

