module carry_save_multiplier (
    input [7:0] a,
    input [7:0] b,
    output [15:0] p
);

wire [7:0] a_mag, b_mag;
wire [7:0] a_neg, b_neg;
wire [7:0] a_booth, b_booth;
wire [7:0] p0, p1, p2;
wire [15:0] s0, s1;

assign a_mag = (a[7] == 1) ? (~a + 1) : a;
assign b_mag = (b[7] == 1) ? (~b + 1) : b;
assign a_neg = (~a_mag + 1);
assign b_neg = (~b_mag + 1);
assign a_booth = {a[7], a[7:0], 1'b0} + (a[7] ? b_neg : b_mag);
assign b_booth = {b[7], b[7:0], 1'b0} + (b[7] ? a_neg : a_mag);

assign p0 = a_booth[0] & b_booth[0];
assign p1 = a_booth[1] & b_booth[1];
assign p2 = a_booth[2] & b_booth[2];

assign s0 = {p0, p1, p2, {9{1'b0}}} + {a_booth, 1'b0} + {b_booth, 1'b0};
assign s1 = {p0, p1, p2, {9{1'b0}}} + {a_booth, 1'b0} - {b_booth, 1'b0};

assign p = (s0[15] == 1) ? s1 : s0;

endmodule

module overflow_detection (
    input [7:0] a,
    input [7:0] b,
    input [15:0] p,
    output overflow
);

assign overflow = ((a[7] == b[7]) && (a[7] != p[15]));

endmodule

module control_logic (
    input [7:0] a,
    input [7:0] b,
    input select,
    output [15:0] p,
    output overflow
);

wire [15:0] p_carry_save, p_binary;
wire overflow_carry_save, overflow_binary;

carry_save_multiplier csm (
    .a(a),
    .b(b),
    .p(p_carry_save)
);

overflow_detection od_csm (
    .a(a),
    .b(b),
    .p(p_carry_save),
    .overflow(overflow_carry_save)
);

assign p_binary = a * b;

overflow_detection od_binary (
    .a(a),
    .b(b),
    .p(p_binary),
    .overflow(overflow_binary)
);

assign p = (select == 1'b1) ? p_carry_save : p_binary;
assign overflow = (select == 1'b1) ? overflow_carry_save : overflow_binary;

endmodule

