module rule_scheduler(
  input CLK,
  input RST_N,
  input [31:0] r1__write_1,
  input EN_r1__write,
  input EN_r2__write,
  output reg [31:0] r1__read,
  output reg [31:0] r2__read,
  output reg RDY_r1__read,
  output reg RDY_r1__write,
  output reg RDY_r2__read,
  output reg RDY_r2__write
);

  // register ehr_r
  reg [31 : 0] ehr_r;
  wire [31 : 0] ehr_r$D_IN;
  wire ehr_r$EN;

  // rule scheduling signals
  wire CAN_FIRE_RL_ehr_do_stuff,
       CAN_FIRE_r1__write,
       CAN_FIRE_r2__write,
       WILL_FIRE_RL_ehr_do_stuff,
       WILL_FIRE_r1__write,
       WILL_FIRE_r2__write;

  // remaining internal signals
  wire [31 : 0] x__h1056;

  // action method r1__write
  assign RDY_r1__write = 1'd1 ;
  assign CAN_FIRE_r1__write = 1'd1 ;
  assign WILL_FIRE_r1__write = EN_r1__write ;

  // value method r1__read
  assign r1__read = ehr_r ;
  assign RDY_r1__read = 1'd1 ;

  // action method r2__write
  assign RDY_r2__write = 1'd1 ;
  assign CAN_FIRE_r2__write = 1'd1 ;
  assign WILL_FIRE_r2__write = EN_r2__write ;

  // value method r2__read
  assign r2__read = EN_r1__write ? r1__write_1 : ehr_r ;
  assign RDY_r2__read = 1'd1 ;

  // rule RL_ehr_do_stuff
  assign CAN_FIRE_RL_ehr_do_stuff = 1'd1 ;
  assign WILL_FIRE_RL_ehr_do_stuff = 1'd1 ;

  // register ehr_r
  assign ehr_r$D_IN = EN_r2__write ? r2__write_1 : x__h1056 ;
  assign ehr_r$EN = 1'd1 ;

  // remaining internal signals
  assign x__h1056 = r2__read ;

  // handling of inlined registers

  always@(posedge CLK)
  begin
    if (!RST_N)
      begin
        ehr_r <= `BSV_ASSIGNMENT_DELAY 32'd0;
      end
    else
      begin
        if (ehr_r$EN) ehr_r <= `BSV_ASSIGNMENT_DELAY ehr_r$D_IN;
      end
  end

  // synopsys translate_off
  `ifdef BSV_NO_INITIAL_BLOCKS
  `else // not BSV_NO_INITIAL_BLOCKS
  initial
  begin
    ehr_r = 32'hAAAAAAAA;
  end
  `endif // BSV_NO_INITIAL_BLOCKS
  // synopsys translate_on
endmodule

module counter_rollover2
#(parameter       W = 8, // width of counter
  parameter       N = 2) // not used, always equal to 2
 (input  wire         CLK,
  input  wire         ENABLE,
  input  wire         LOAD,
  input  wire [W-1:0] DI,
  output wire [W-1:0] DO
  );

  reg [(W/2)-1:0] CounterMSB;
  reg [(W/2)-1:0] CounterLSB;

  wire TerminalCount = & CounterLSB;

  wire RollOver = TerminalCount & ENABLE;

  always @(posedge CLK)
  if (LOAD)
    CounterMSB <= DI[W-1:W/2];
  else if (RollOver)
    CounterMSB <= CounterMSB + 1;

  always @(posedge CLK)
  if (LOAD)
    CounterLSB <= DI[(W/2)-1:0];
  else if (ENABLE)
    CounterLSB <= CounterLSB + 1;

  assign DO = {CounterMSB,CounterLSB};

endmodule

module ps2_receiver(
    input wire clk, clr,
    input wire ps2c, ps2d,
    output wire [15:0] xkey
);

    reg PS2Cf, PS2Df;
    reg [7:0] ps2c_filter, ps2d_filter;
    reg [10:0] shift1, shift2;

    assign xkey = {shift2[8:1], shift1[8:1]};

    // Filter for PS2 clock and data
    always @ (posedge clk or posedge clr) begin
        if (clr == 1) begin
            ps2c_filter <= 0;
            ps2d_filter <= 0;
            PS2Cf       <= 1;
            PS2Df       <= 1;
        end else begin
            ps2c_filter <= {ps2c, ps2c_filter[7:1]};
            ps2d_filter <= {ps2d, ps2d_filter[7:1]};
            if (ps2c_filter == 8'b1111_1111)
                PS2Cf <= 1;
            else if (ps2c_filter == 8'b0000_0000)
                PS2Cf <= 0;
            if (ps2d_filter == 8'b1111_1111)
                PS2Df <= 1;
            else if (ps2d_filter == 8'b0000_0000)
                PS2Df <= 0;
        end
    end

    // Shift register used to clock in scan codes from PS2
    always @ (negedge PS2Cf or posedge clr) begin
        if (clr == 1) begin
            shift1 <= 0;
            shift2 <= 1;
        end else begin
            shift1 <= {PS2Df, shift1[10:1]};
            shift2 <= {shift1[0], shift2[10:1]};
        end
    end

endmodule

module gray_code_state_machine (
  input [n-1:0] state,
  input clk,
  output [n-1:0] next_state
);

parameter n = 3; // number of bits in the state

// Define the Gray code states
reg [n-1:0] gray_states [0:2**n-1];
integer i;
initial begin
  for (i = 0; i < 2**n; i = i + 1) begin
    gray_states[i] = i ^ (i >> 1);
  end
end

// Define the Gray code state transition table
reg [n-1:0] gray_transition_table [0:2**n-1][0:1];
initial begin
  gray_transition_table[0][0] = 'h1;
  gray_transition_table[0][1] = 'h2;
  gray_transition_table[1][0] = 'h3;
  gray_transition_table[1][1] = 'h0;
  gray_transition_table[2][0] = 'h6;
  gray_transition_table[2][1] = 'h7;
  gray_transition_table[3][0] = 'h5;
  gray_transition_table[3][1] = 'h4;
  gray_transition_table[4][0] = 'h4;
  gray_transition_table[4][1] = 'h5;
  gray_transition_table[5][0] = 'h7;
  gray_transition_table[5][1] = 'h6;
  gray_transition_table[6][0] = 'h2;
  gray_transition_table[6][1] = 'h1;
  gray_transition_table[7][0] = 'h0;
  gray_transition_table[7][1] = 'h3;
end

// Compute the next state based on the current state and the clock signal
always @(posedge clk) begin
  next_state <= gray_transition_table[state][1];
end

endmodule

module ripple_adder(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout
);
    wire [3:0] xor1_out;
    wire [3:0] and1_out;
    wire [3:0] and2_out;
    wire [3:0] or1_out;
    wire [3:0] or2_out;
    wire [2:0] and3_out;
    wire [2:0] or3_out;

    // First bit
    xor x1(A[0], B[0], Cin, xor1_out[0]);
    and a1(A[0], B[0], and1_out[0]);
    or o1(and1_out[0], xor1_out[0], Sum[0]);
    and a2(and1_out[0], Cin, and2_out[0]);
    or o2(and2_out[0], xor1_out[0], Cout);

    // Second bit
    xor x2(A[1], B[1], xor1_out[1], xor1_out[2]);
    and a3(A[1], B[1], and1_out[1]);
    and a4(A[0], xor1_out[1], and2_out[1]);
    or o3(and1_out[1], and2_out[1], or1_out[0]);
    or o4(or1_out[0], xor1_out[2], Sum[1]);
    and a5(and1_out[1], xor1_out[1], and3_out[0]);
    or o5(and2_out[1], and3_out[0], or3_out[0]);

    // Third bit
    xor x3(A[2], B[2], xor1_out[2], xor1_out[3]);
    and a6(A[2], B[2], and1_out[2]);
    and a7(A[1], xor1_out[2], and2_out[2]);
    and a8(A[0], xor1_out[3], and3_out[1]);
    or o6(and1_out[2], and2_out[2], or1_out[1]);
    or o7(or1_out[1], xor1_out[3], Sum[2]);
    and a9(and1_out[2], xor1_out[2], and3_out[2]);
    or o8(and2_out[2], and3_out[2], or3_out[1]);

    // Fourth bit
    xor x4(A[3], B[3], xor1_out[3], Cout);
    and a10(A[3], B[3], and1_out[3]);
    and a11(A[2], xor1_out[3], and2_out[3]);
    and a12(A[1], xor1_out[2], and3_out[3]);
    or o9(and1_out[3], and2_out[3], or1_out[2]);
    or o10(or1_out[2], Cout, Sum[3]);
    and a13(and1_out[3], xor1_out[3], and3_out[4]);
    or o11(and2_out[3], and3_out[4], Cout);

endmodule

module xor(input a, input b, input c, output out);
    wire w1;
    wire w2;
    not n1(c, w1);
    and a1(a, b, w2);
    and a2(a, w1, w1);
    and a3(b, w1, w1);
    or o1(w2, w1, out);
endmodule

module and(input a, input b, output out);
    nand n1(a, b, out);
endmodule

module or(input a, input b, output out);
    nor n1(a, b, out);
endmodule

module nand(input a, input b, output out);
    not n1(a, w1);
    not n2(b, w2);
    and a1(w1, w2, out);
endmodule

module nor(input a, input b, output out);
    not n1(a, w1);
    not n2(b, w2);
    or o1(w1, w2, out);
endmodule

