module glitch_filter (
  input in,
  output out
);

parameter n = 10; // number of clock cycles to wait
parameter t = 5; // threshold value for glitch detection
parameter v = 0; // value to output when a glitch is detected

reg [n-1:0] timer;
reg glitch_detected;
reg [1:0] input_history;
wire input_above_threshold;

assign input_above_threshold = (in > t);

always @(posedge clk) begin
  if (timer == n-1) begin
    if (glitch_detected) begin
      out <= v;
    end else begin
      out <= in;
    end
    timer <= 0;
    glitch_detected <= 0;
  end else begin
    timer <= timer + 1;
    if (input_above_threshold) begin
      input_history <= {input_history[0], 1};
    end else begin
      input_history <= {input_history[0], 0};
    end
    if (input_history == 2'b10) begin
      glitch_detected <= 1;
    end
  end
end

endmodule

module barrel_shifter (
    input [3:0] in, // 4-bit input 
    output [3:0] out, // original input 
    output [3:0] out_shifted // input shifted left by one position 
);

assign out = in;
assign out_shifted = {in[2:0], 1'b0};

endmodule

module priority_encoder (
    input [3:0] in, // shifted input 
    output reg [2:0] out // position of highest bit set to 1 
);

always @* begin
    case(in)
        4'b1000: out = 3'b011;
        4'b0100: out = 3'b010;
        4'b0010: out = 3'b001;
        4'b0001: out = 3'b000;
        default: out = 3'b000;
    endcase
end

endmodule

module functional_module (
    input [3:0] in, // original input 
    input [3:0] in_shifted, // input shifted left by one position 
    input [2:0] priority, // position of highest bit set to 1 
    output reg [7:0] out // final output 
);

always @* begin
    if (priority == 0) begin
        out = 8'b00000000;
    end else begin
        out = {in ^ in_shifted, priority};
    end
end

endmodule

