module reg_module(CLK, RST, IN);
  input CLK, RST, IN;
  reg reg1, reg2, reg3, reg4;
  wire in1;

  always @(posedge CLK or negedge RST) begin
    if(RST == 0) begin
      reg1 <= 0;
    end else begin
      reg1 <= IN;
    end
  end

  always @(posedge CLK or negedge RST) begin
    if(RST == 0) begin
      reg2 <= 0;
    end else begin
      reg2 <= 1;
    end
  end

  assign in1 = IN;

  always @(posedge CLK or negedge RST) begin
    if(RST == 0) begin
      reg3 <= 0;
    end else begin
      reg3 <= in1;
    end
  end

  always @(posedge CLK or negedge RST) begin
    if(RST == 0) begin
      reg4 <= 1;
    end else begin
      if(in1 == 1) begin
        reg4 <= ~reg4;
      end
    end
  end

endmodule

module freqdiv(
    input clk,
    input rst_n,
    output reg clk_out,
    input [1:0] select
);

reg [23:0] counter;
reg [23:0] divider;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        counter <= 24'd0;
        clk_out <= 1'b0;
    end
    else begin
        case (select)
            2'b00: divider <= 24'd5;
            2'b01: divider <= 24'd5999999;
            2'b10: divider <= 24'd5999;
            2'b11: divider <= 24'd5;
        endcase

        if (counter == divider) begin
            counter <= 24'd0;
            clk_out <= ~clk_out;
        end
        else begin
            counter <= counter + 1;
        end
    end
end

endmodule

