    .CLKOUT2_USE_FINE_PS("FALSE")
) mmcm_adv_inst (
    .CLKFBIN(clkfbout),
    .CLKFBOUT(clkfbout),
    .CLKIN1(clk_in1),
    .CLKINSEL(1'b1),
    .CLKOUT0(aclk_buf),
    .CLKOUT1(uart_buf),
    .LOCKED(locked_buf),
    .DO(),
    .DRDY(),
    .PSDONE(),
    .RST(reset)
);

// Clock buffer instances
BUFG aclk_buf_inst (
    .I(aclk_buf),
    .O(aclk)
);

BUFG uart_buf_inst (
    .I(uart_buf),
    .O(uart)
);

