    wire [15:0] sum;
    wire Cout;
    ripple_carry_adder adder(.A(A), .B(B), .Cin(Cin), .S(sum), .Cout(Cout));

    // Barrel shifter
    wire [3:0] shifted_data;
    barrel_shifter shifter(.data(data), .shift(shift), .result(shifted_data));

    // Functional module
    always @(*) begin
        if (sum[15] == 1) begin
            result = ~shifted_data + 1;
        end else begin
            result = sum[15:12] + shifted_data;
        end
    end

endmodule

module ripple_carry_adder (
    input [15:0] A,
    input [15:0] B,
    input Cin,
    output reg [15:0] S,
    output reg Cout
);

    always @(*) begin
        S = A + B + Cin;
        Cout = (S[15] == 1) ? 1'b1 : 1'b0;
    end

endmodule

module barrel_shifter (
    input [3:0] data,
    input [1:0] shift,
    output reg [3:0] result
);

    always @(*) begin
        case (shift)
            2'b00: result = data;
            2'b01: result = {data[2:0], data[3]};
            2'b10: result = {data[1:0], data[3:2]};
            2'b11: result = {data[0], data[3:1]};
        endcase
    end

endmodule

