module carry_select_adder (
    input clk,
    input reset,
    input [7:0] a,
    input [7:0] b,
    input control,
    output [7:0] sum
);

    wire [7:0] carry_lookahead;
    wire [7:0] ripple_carry;

    full_adder fa0(a[0], b[0], 1'b0, sum[0], carry_lookahead[0]);
    full_adder fa1(a[1], b[1], carry_lookahead[0], sum[1], carry_lookahead[1]);
    full_adder fa2(a[2], b[2], carry_lookahead[1], sum[2], carry_lookahead[2]);
    full_adder fa3(a[3], b[3], carry_lookahead[2], sum[3], carry_lookahead[3]);
    full_adder fa4(a[4], b[4], carry_lookahead[3], sum[4], carry_lookahead[4]);
    full_adder fa5(a[5], b[5], carry_lookahead[4], sum[5], carry_lookahead[5]);
    full_adder fa6(a[6], b[6], carry_lookahead[5], sum[6], carry_lookahead[6]);
    full_adder fa7(a[7], b[7], carry_lookahead[6], sum[7], carry_lookahead[7]);

    assign ripple_carry[0] = 1'b0;
    assign ripple_carry[1] = carry_lookahead[0];
    assign ripple_carry[2] = carry_lookahead[1] & control;
    assign ripple_carry[3] = carry_lookahead[2] & control;
    assign ripple_carry[4] = carry_lookahead[3] & control;
    assign ripple_carry[5] = carry_lookahead[4] & control;
    assign ripple_carry[6] = carry_lookahead[5] & control;
    assign ripple_carry[7] = carry_lookahead[6] & control;

    always @(posedge clk) begin
        if (reset) begin
            sum <= 8'b0;
        end else begin
            if (control) begin
                sum <= carry_lookahead;
            end else begin
                sum <= ripple_carry;
            end
        end
    end

endmodule

module full_adder (
    input A,
    input B,
    input C_in,
    output Sum,
    output C_out
);

    assign Sum = A ^ B ^ C_in;
    assign C_out = (A & B) | (C_in & (A ^ B));

endmodule

module DFF_NS (
    output reg Q,
    input C, S, D
);

    `SB_DFF_INIT

    always @(negedge C) begin
        if (S) begin
            Q <= 1;
        end else begin
            Q <= D;
        end
    end

`ifdef ICE40_HX
    specify
        $setup(D, negedge C, 21);
        $setup(S, negedge C, 203);
        if ( S) (negedge C => (Q : 1'b1)) = 540;
        if (!S) (negedge C => (Q : D)) = 540;
    endspecify
`endif

`ifdef ICE40_LP
    specify
        $setup(D, negedge C, 31);
        $setup(S, negedge C, 299);
        if ( S) (negedge C => (Q : 1'b1)) = 796;
        if (!S) (negedge C => (Q : D)) = 796;
    endspecify
`endif

`ifdef ICE40_U
    specify
        $setup(D, negedge C, 0);
        $setup(S, negedge C, 530);
        if ( S) (negedge C => (Q : 1'b1)) = 1391;
        if (!S) (negedge C => (Q : D)) = 1391;
    endspecify
`endif

endmodule

module reverse_shift_and(
    input clk,                  // Clock signal
    input [7:0] in,             // 8-bit input vector
    input select,               // Select input to choose between module outputs
    output [7:0] out            // 8-bit final output
);

    // First module - Reverse bit order using shift register
    reg [7:0] shift_reg;
    always @ (posedge clk) begin
        shift_reg <= {shift_reg[6:0], in[7]};
    end

    // Second module - 3-bit shift register using D flip-flops and multiplexer
    reg [2:0] shift_reg_3;
    reg serial_out;
    always @ (posedge clk) begin
        shift_reg_3 <= {shift_reg_3[1:0], in[0]};
        serial_out <= select ? shift_reg[0] : shift_reg_3[0];
    end

    // Functional module - Bitwise AND operation to produce final output
    assign out = select ? shift_reg & in : {3'b0, serial_out, shift_reg_3};

endmodule

module adder (
    input [3:0] a,
    input [3:0] b,
    input cin,
    output reg [3:0] sum,
    output reg cout
);

reg [3:0] a_reg, b_reg, sum_reg;
reg cin_reg;

always @(posedge clk) begin
    a_reg <= a;
    b_reg <= b;
    cin_reg <= cin;
    sum_reg <= a_reg + b_reg + cin_reg;
end

always @(posedge clk) begin
    sum <= sum_reg;
    cout <= sum_reg[4];
end

endmodule

module comparator (
    input [3:0] A,
    input [3:0] B,
    output reg EQ,
    output reg GT,
    output reg LT
);

always @* begin
    if (A == B) begin
        EQ = 1;
        GT = 0;
        LT = 0;
    end else if (A > B) begin
        EQ = 0;
        GT = 1;
        LT = 0;
    end else begin
        EQ = 0;
        GT = 0;
        LT = 1;
    end
end

endmodule

module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [3:0] A,    // Input to first comparator
    input [3:0] B,    // Input to first comparator
    output reg EQ1,   // Equal output of first comparator
    output reg GT1,   // Greater than output of first comparator
    output reg LT1,   // Less than output of first comparator
    input [3:0] C,    // Input to second comparator
    input [3:0] D,    // Input to second comparator
    output reg EQ2,   // Equal output of second comparator
    output reg GT2,   // Greater than output of second comparator
    output reg LT2,   // Less than output of second comparator
    output [3:0] q    // 4-bit output of the larger value
);

reg [3:0] larger_value;

comparator comp1(.A(A), .B(B), .EQ(EQ1), .GT(GT1), .LT(LT1));
comparator comp2(.A(C), .B(D), .EQ(EQ2), .GT(GT2), .LT(LT2));

always @(posedge clk) begin
    if (reset) begin
        EQ1 <= 0;
        GT1 <= 0;
        LT1 <= 0;
        EQ2 <= 0;
        GT2 <= 0;
        LT2 <= 0;
        larger_value <= 0;
    end else begin
        if (GT1 || EQ1) begin
            larger_value <= A;
        end else begin
            larger_value <= B;
        end

        if (GT2 || EQ2) begin
            if (C > larger_value) begin
                larger_value <= C;
            end
        end else begin
            if (D > larger_value) begin
                larger_value <= D;
            end
        end

        q <= larger_value;
    end
end

endmodule

module and_gate4(
    input A, B, C, D,
    output reg X
);

    wire A_B, C_D, A_B_C_D;

    // AND gate for inputs A and B
    and gate1(A_B, A, B);

    // AND gate for inputs C and D
    and gate2(C_D, C, D);

    // AND gate for inputs A, B, C, and D
    and gate3(A_B_C_D, A_B, C_D);

    // Output X is high only when all inputs are high
    always @(*) begin
        if (A_B_C_D == 1'b1) begin
            X = 1'b1;
        end
        else begin
            X = 1'b0;
        end
    end

endmodule

module sequence_detector (
    input clk,
    input reset,
    input [3:0] in,
    output reg [6:0] seg_out
);

    reg [3:0] shift_reg;
    reg [3:0] seq = 4'b1100;
    reg [3:0] seq_detect;
    reg detect;

    always @(posedge clk) begin
        if (reset) begin
            shift_reg <= 4'b0000;
            detect <= 0;
            seq_detect <= 4'b0000;
            seg_out <= 7'b0000000;
        end
        else begin
            shift_reg <= {in, shift_reg[3:1]};
            seq_detect <= {shift_reg[2:0], in};
            if (seq_detect == seq) begin
                detect <= 1;
            end
            if (detect) begin
                seg_out <= 7'b0110000; // Display "1"
            end
            else begin
                seg_out <= 7'b0000000; // Display "0"
            end
        end
    end

endmodule

module top_module(
