    .out(out)
);

endmodule

module VCO_interface (
  input vin,
  input clk,
  input reset,
  input freq_min,
  input freq_max,
  output reg vco_out
);

  reg [31:0] counter;
  reg [31:0] phase_accumulator;
  reg [31:0] phase_increment;
  reg [31:0] frequency;
  reg [31:0] voltage_scaled;
  reg [31:0] voltage_range;
  reg [31:0] freq_range;
  reg [31:0] freq_scaled;
  reg [31:0] freq_offset;

  always @ (posedge clk or posedge reset) begin
    if (reset) begin
      counter <= 0;
      phase_accumulator <= 0;
      phase_increment <= 0;
      frequency <= 0;
      voltage_scaled <= 0;
      voltage_range <= 0;
      freq_range <= 0;
      freq_scaled <= 0;
      freq_offset <= 0;
      vco_out <= 0;
    end else begin
      counter <= counter + 1;
      phase_accumulator <= phase_accumulator + phase_increment;
      if (phase_accumulator >= 2**32) begin
        phase_accumulator <= phase_accumulator - 2**32;
      end
      if (counter >= frequency) begin
        counter <= 0;
        vco_out <= ~vco_out;
      end
    end
  end

  always @ (vin) begin
    voltage_scaled <= (vin * 2**31) / 5;
    voltage_range <= freq_max - freq_min;
    freq_range <= (voltage_scaled * voltage_range) / 2**31;
    freq_scaled <= freq_min + freq_range;
    freq_offset <= freq_scaled - clk;
    phase_increment <= (freq_offset * 2**32) / clk;
    frequency <= clk / freq_offset;
  end

endmodule

module crystal_interface (
  input clk_in,
  input rst,
  output reg clk_out,
  output reg locked
);

  reg [31:0] count;
  reg [31:0] prev_count;
  reg locked_flag;

  always @(posedge clk_in) begin
    if (rst) begin
      count <= 0;
      prev_count <= 0;
      clk_out <= 0;
      locked_flag <= 0;
    end
    else begin
      count <= count + 1;
      if (count == 0) begin
        prev_count <= count;
        clk_out <= ~clk_out;
        if (prev_count != 0) begin
          locked_flag <= 1;
        end
      end
    end
  end

  always @(posedge clk_in) begin
    if (rst) begin
      locked <= 0;
    end
    else begin
      locked <= locked_flag;
    end
  end

endmodule

module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out
);

reg [7:0] data_reg_1, data_reg_2, data_reg_3, data_reg_4;
reg [9:0] acc_reg_1, acc_reg_2, acc_reg_3, acc_reg_4;

wire [9:0] acc_out_1, acc_out_2, acc_out_3;

assign acc_out_1 = acc_reg_1 + data_reg_1;
assign acc_out_2 = acc_reg_2 + data_reg_2;
assign acc_out_3 = acc_reg_3 + data_reg_3;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        data_reg_1 <= 8'b0;
        data_reg_2 <= 8'b0;
        data_reg_3 <= 8'b0;
        data_reg_4 <= 8'b0;
        acc_reg_1 <= 10'b0;
        acc_reg_2 <= 10'b0;
        acc_reg_3 <= 10'b0;
        acc_reg_4 <= 10'b0;
        valid_b <= 1'b0;
        data_out <= 10'b0;
    end
    else begin
        if (valid_a && ready_b) begin
            data_reg_1 <= data_in;
            data_reg_2 <= data_reg_1;
            data_reg_3 <= data_reg_2;
            data_reg_4 <= data_reg_3;
            acc_reg_1 <= acc_out_1;
            acc_reg_2 <= acc_out_2;
            acc_reg_3 <= acc_out_3;
            acc_reg_4 <= acc_reg_3;
            valid_b <= 1'b0;
            data_out <= acc_reg_4;
        end
        else begin
            data_reg_1 <= data_reg_1;
            data_reg_2 <= data_reg_2;
            data_reg_3 <= data_reg_3;
            data_reg_4 <= data_reg_4;
            acc_reg_1 <= acc_reg_1;
            acc_reg_2 <= acc_reg_2;
            acc_reg_3 <= acc_reg_3;
            acc_reg_4 <= acc_reg_4;
            valid_b <= valid_a && ~valid_b;
            data_out <= data_out;
        end
    end
end

assign ready_a = ~valid_b;

endmodule

module control_regs (sclk, wen, wa, di, bayer_phase, hact_regen, reset_mcontr, break_frames, zoran, use_sensor_clk, xt_pol, arst, aro, encnvclk, sensor_trigger, mrst, external_timestamp, output_timestamp, dclkmode, pxd14, latehact, pclksrc, hfc_sel, blockvsync, compressed_frames);

