module adder_subtractor (
    A,
    B,
    C,
    Y
);
  input [3:0] A;
  input [3:0] B;
  input C;
  output [3:0] Y;

  wire [3:0] A_inv;
  wire [3:0] B_inv;
  wire [3:0] C_inv;
  wire [3:0] carry_in;
  wire [3:0] carry_out;

  // Invert A, B and C
  assign A_inv = ~A;
  assign B_inv = ~B;
  assign C_inv = ~C;

  // Calculate the carry in and carry out
  assign carry_in[0] = C;
  assign carry_in[1] = (C & A[0]) | (C_inv & A_inv[0]);
  assign carry_in[2] = (C & A[1] & A[0]) | (C_inv & A_inv[1] & A_inv[0]);
  assign carry_in[3] = (C & A[2] & A[1] & A[0]) | (C_inv & A_inv[2] & A_inv[1] & A_inv[0]);
  assign carry_out[0] = (C_inv & A[0] & B[0]) | (C & A_inv[0] & B_inv[0]);
  assign carry_out[1] = (C_inv & A[1] & B[1]) | (C & A_inv[1] & B_inv[1]) | (carry_in[1] & (A[0] ^ B[0]));
  assign carry_out[2] = (C_inv & A[2] & B[2]) | (C & A_inv[2] & B_inv[2]) | (carry_in[2] & (A[1] ^ B[1])) | (carry_in[1] & (A[0] & B[0]));
  assign carry_out[3] = (C_inv & A[3] & B[3]) | (C & A_inv[3] & B_inv[3]) | (carry_in[3] & (A[2] ^ B[2])) | (carry_in[2] & (A[1] & B[1])) | (carry_in[1] & (A[0] & B[0]));

  // Calculate the sum
  assign Y[0] = A[0] ^ B[0] ^ C;
  assign Y[1] = A[1] ^ B[1] ^ carry_in[1];
  assign Y[2] = A[2] ^ B[2] ^ carry_in[2];
  assign Y[3] = A[3] ^ B[3] ^ carry_in[3];

  // Subtract if C is 1
  assign Y = (C == 1) ? (~Y + 1) : Y;

endmodule

