module streaming_data_interface (
    input clk,
    input reset,
    input reset_n,
    input [63:0] sink_data,
    input sink_valid,
    output reg sink_ready,
    input source_ready,
    output reg [2:0] source_empty,
    output reg [63:0] source_data,
    output reg source_endofpacket,
    output reg source_valid,
    output reg eop_found,
    output reg [8:0] m_writefifo_fill
);

    reg [63:0] m_writefifo [511:0];
    reg [8:0] m_writefifo_usedw;
    reg [8:0] m_writefifo_usedr;
    reg [8:0] m_writefifo_usedr_next;
    reg [2:0] source_empty_next;
    reg [2:0] source_empty_hold;
    reg [67:0] source_data_hold;
    reg source_endofpacket_hold;
    reg eop_found_hold;

    wire m_writefifo_empty = (m_writefifo_usedw == m_writefifo_usedr);
    wire m_writefifo_full = (m_writefifo_usedw == m_writefifo_usedr_next);

    assign source_empty = source_empty_hold;
    assign source_data = source_data_hold[63:0];
    assign source_endofpacket = source_endofpacket_hold;
    assign source_valid = (source_data_hold[67] == 1'b1);

    always @(posedge clk or negedge reset_n) begin
        if (~reset_n) begin
            sink_ready <= 1'b0;
            m_writefifo_usedw <= 9'b0;
            m_writefifo_usedr <= 9'b0;
            m_writefifo_usedr_next <= 9'b0;
            source_empty_next <= 3'b111;
            source_empty_hold <= 3'b0;
            source_data_hold <= 68'b0;
            source_endofpacket_hold <= 1'b0;
            eop_found_hold <= 1'b0;
            m_writefifo_fill <= 9'b0;
        end else begin
            if (sink_valid && ~m_writefifo_full) begin
                m_writefifo[m_writefifo_usedw] <= {sink_data, 1'b0, 1'b0, 1'b0, 1'b1};
                m_writefifo_usedw <= m_writefifo_usedw + 1'b1;
                sink_ready <= 1'b1;
            end else begin
                sink_ready <= 1'b0;
            end

            if (source_ready && ~m_writefifo_empty) begin
                source_data_hold <= m_writefifo[m_writefifo_usedr];
                m_writefifo_usedr_next <= m_writefifo_usedr + 1'b1;
            end

            if (source_ready && source_valid) begin
                m_writefifo_usedr <= m_writefifo_usedr_next;
                source_empty_hold <= source_empty_next;
                source_endofpacket_hold <= source_data_hold[67];
                eop_found_hold <= eop_found_hold ? ~(source_ready && source_valid && source_endofpacket_hold) : source_endofpacket_hold;
            end else begin
                eop_found_hold <= 1'b0;
            end

            if (m_writefifo_usedw == m_writefifo_usedr) begin
                source_empty_next <= 3'b111;
            end else begin
                source_empty_next <= {3'b0, m_writefifo_usedw[8:0]} - {3'b0, m_writefifo_usedr[8:0]};
            end

            m_writefifo_fill <= m_writefifo_usedw[8:0];
        end
    end

    assign eop_found = eop_found_hold;

endmodule

module RLE (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 8; // number of input signals
parameter m = 16; // number of output signals (8 values and 8 counts)

// No additional parameters required for this module.

reg [n-1:0] current; // current input signal
reg [n-1:0] next; // next input signal
reg [m-1:0] encoded; // encoded output signals
reg [n-1:0] decoded; // decoded output signals
reg [3:0] state; // state variable for encoding/decoding state machine
reg [3:0] count; // count variable for encoding

// Encoding state machine
localparam IDLE = 4'b0000;
localparam COUNT = 4'b0001;
localparam VALUE = 4'b0010;

// Decoding state machine
localparam DECODE_IDLE = 4'b0000;
localparam DECODE_VALUE = 4'b0001;
localparam DECODE_COUNT = 4'b0010;

// Initialize state machine and count variable
initial begin
  state = IDLE;
  count = 0;
end

// Encoding state machine
always @(*) begin
  case(state)
    IDLE: begin
      count = 1;
      current = in;
      state = COUNT;
    end
    COUNT: begin
      if(in == current) begin
        count = count + 1;
      end
      else begin
        encoded = {encoded, current, count};
        count = 1;
        current = in;
        state = VALUE;
      end
    end
    VALUE: begin
      count = 1;
      current = in;
      state = COUNT;
    end
  endcase
end

// Decoding state machine
always @(*) begin
  repeat_count = 0;
  case(state)
    DECODE_IDLE: begin
      current = in;
      repeat_count = 0;
      state = DECODE_VALUE;
    end
    DECODE_VALUE: begin
      if(repeat_count > 0) begin
        decoded = {decoded, current};
        repeat_count = repeat_count - 1;
      end
      else begin
        repeat_count = in;
        state = DECODE_COUNT;
      end
    end
    DECODE_COUNT: begin
      current = in;
      state = DECODE_VALUE;
    end
  endcase
end

// Assign output signals
assign out = (state == IDLE) ? encoded : decoded;

endmodule

module fifo_buffer #(
  parameter DATA_WIDTH          = 32,
  parameter FIFO_WIDTH          = 8
)(
  input                             rst,
  input       [31:0]                test_id,

  //write side
  input                             WR_CLK,
