//Synchronous Logic
always @(posedge WR_CLK) begin
  if (r_rst) begin
    wr_ptr <= 0;
    rd_ptr <= 0;
    count <= 0;
    wr_starved <= 0;
    rd_inactive <= 1;
  end else begin
    if (WR_STB & WR_ACT & WR_RDY) begin
      wr_ptr <= wr_ptr + 1;
      count <= count + 1;
      rd_inactive <= 0;
      if (count == ADDR_MASK + 1) begin
        wr_starved <= 1;
      end
    end

    if (RD_STB & RD_ACT & RD_RDY) begin
      rd_ptr <= rd_ptr + 1;
      count <= count - 1;
      wr_starved <= 0;
      if (count == 1) begin
        rd_inactive <= 1;
      end
    end
  end
end

