module fifo_32in_32out_16kb(
    input rst,
    input wr_clk,
    input rd_clk,
    input [31:0] din,
    input wr_en,
    input rd_en,
    output [31:0] dout,
    output full,
    output empty,
    output [1:0] wr_data_count
);

    // Define FIFO parameters
    parameter WIDTH = 32;
    parameter DEPTH = 512;
    parameter ADDR_WIDTH = $clog2(DEPTH);

    // Define FIFO memory
    reg [WIDTH-1:0] mem [DEPTH-1:0];
    reg [ADDR_WIDTH-1:0] wr_ptr;
    reg [ADDR_WIDTH-1:0] rd_ptr;
    reg [1:0] count;

    // Define full and empty flags
    wire full = (count == DEPTH);
    wire empty = (count == 0);

    // Write operation
    always @(posedge wr_clk) begin
        if (rst) begin
            wr_ptr <= 0;
        end else if (wr_en && !full) begin
            mem[wr_ptr] <= din;
            wr_ptr <= wr_ptr + 1;
            count <= count + 1;
        end
    end

    // Read operation
    always @(posedge rd_clk) begin
        if (rst) begin
            rd_ptr <= 0;
        end else if (rd_en && !empty) begin
            dout <= mem[rd_ptr];
            rd_ptr <= rd_ptr + 1;
            count <= count - 1;
        end
    end

    // Update wr_data_count
    always @(*) begin
        wr_data_count = count;
    end

endmodule

