module CPU(
    input R1in, R2in, Yin, Zin, reset, Clock,
    input [1:0] StartAddress,
    input End,
    input [31:0] Number1, Number2,
    output reg R1out, R2out,
    output reg Add, Sub, Mul, Div,
    output reg SelectY, Zout,
    output reg [31:0] Register,
    output reg [1:0] InstructionCode
);

reg [31:0] Y, Z;
reg [1:0] address;
reg [2:0] state;

parameter IDLE = 2'b00;
parameter FETCH = 2'b01;
parameter EXECUTE = 2'b10;

always @(posedge Clock) begin
    if (reset) begin
        state <= IDLE;
        address <= StartAddress;
        InstructionCode <= 2'b00;
        R1out <= 1'b0;
        R2out <= 1'b0;
        Add <= 1'b0;
        Sub <= 1'b0;
        Mul <= 1'b0;
        Div <= 1'b0;
        SelectY <= 1'b0;
        Zout <= 1'b0;
        Register <= 32'h0;
    end else begin
        case (state)
            IDLE: begin
                if (!End) begin
                    state <= FETCH;
                end
            end
            FETCH: begin
                address <= address + 2'b01;
                case (address)
                    2'b00: begin
                        InstructionCode <= 2'b00;
                        state <= EXECUTE;
                    end
                    2'b01: begin
                        InstructionCode <= 2'b01;
                        state <= EXECUTE;
                    end
                    2'b10: begin
                        InstructionCode <= 2'b10;
                        state <= EXECUTE;
                    end
                    2'b11: begin
                        InstructionCode <= 2'b11;
                        state <= EXECUTE;
                    end
                endcase
            end
            EXECUTE: begin
                case (InstructionCode)
                    2'b00: begin
                        R1out <= 1'b1;
                        R2out <= 1'b1;
                        Add <= 1'b1;
                        SelectY <= 1'b0;
                        state <= IDLE;
                        Register <= Number1 + Y;
                    end
                    2'b01: begin
                        R1out <= 1'b1;
                        R2out <= 1'b1;
                        Sub <= 1'b1;
                        SelectY <= 1'b1;
                        state <= IDLE;
                        Register <= Number1 - Number2;
                    end
                    2'b10: begin
                        R1out <= 1'b1;
                        R2out <= 1'b1;
                        Mul <= 1'b1;
                        SelectY <= 1'b0;
                        state <= IDLE;
                        Register <= Number1 * Y;
                    end
                    2'b11: begin
                        R1out <= 1'b1;
                        R2out <= 1'b1;
                        Div <= 1'b1;
                        SelectY <= 1'b1;
                        state <= IDLE;
                        Register <= Number1 / Number2;
                    end
                endcase
            end
        endcase
    end
end

always @(posedge Clock) begin
    if (reset) begin
        Y <= 32'h0;
        Z <= 32'h0;
    end else begin
        case (state)
            IDLE: begin
                R1out <= 1'b0;
                R2out <= 1'b0;
                Add <= 1'b0;
                Sub <= 1'b0;
                Mul <= 1'b0;
                Div <= 1'b0;
                SelectY <= 1'b0;
                Zout <= 1'b0;
            end
            EXECUTE: begin
                case (InstructionCode)
                    2'b00: begin
                        if (R1in) begin
                            Y <= Register;
                        end
                        if (R2in) begin
                            Z <= Register;
                        end
                    end
                    2'b01: begin
                        if (R1in) begin
                            Y <= Register;
                        end
                        if (R2in) begin
                            Z <= Register;
                        end
                    end
                    2'b10: begin
                        if (R1in) begin
                            Y <= Register;
                        end
                        if (R2in) begin
                            Z <= Register;
                        end
                    end
                    2'b11: begin
                        if (R1in) begin
                            Y <= Register;
                        end
                        if (R2in) begin
                            Z <= Register;
                        end
                    end
                endcase
                if (SelectY) begin
                    Register <= Y;
                end else begin
                    Register <= Z;
                end
                if (Zin) begin
                    Z <= Register;
                end
                if (Zout) begin
                    Zout <= 1'b1;
                end else begin
                    Zout <= 1'b0;
                end
            end
        endcase
    end
end

endmodule

