module SD_controller (
  input clk,
  input rst,
  input [47:0] cmd,
  input [511:0] dat_i,
  output [511:0] dat_o,
  output cmd_busy,
  output dat_busy,
  output dat_ready,
  output dat_error
);

  // Define state machine states
  parameter IDLE = 0;
  parameter CMD_START = 1;
  parameter CMD_RESP = 2;
  parameter DATA_START = 3;
  parameter DATA_READ = 4;
  parameter DATA_WRITE = 5;
  parameter DATA_RESP = 6;
  parameter ERROR = 7;

  // Define state machine inputs
  parameter CMD_READ = 0;
  parameter CMD_WRITE = 1;
  parameter CMD_ERASE = 2;
  parameter CMD_FORMAT = 3;
  parameter DATA_SINGLE = 0;
  parameter DATA_MULTI = 1;

  // Define state machine outputs
  parameter CMD_BUSY = 1;
  parameter DAT_BUSY = 2;
  parameter DAT_READY = 4;
  parameter DAT_ERROR = 8;

  // Define internal signals
  reg [2:0] state;
  reg [1:0] cmd_type;
  reg [1:0] data_type;
  reg [47:0] cmd_reg;
  reg [511:0] dat_reg;
  reg [31:0] dat_cnt;
  reg [31:0] dat_len;
  reg cmd_busy_reg;
  reg dat_busy_reg;
  reg dat_ready_reg;
  reg dat_error_reg;

  // Define command response signals
  wire [47:0] cmd_resp;
  wire cmd_resp_valid;

  // Define data response signals
  wire [1:0] data_resp;
  wire data_resp_valid;

  // Define CRC error signal
  wire crc_error;

  // Define state machine
  always @(posedge clk or posedge rst) begin
    if (rst) begin
      state <= IDLE;
      cmd_type <= 0;
      data_type <= 0;
      cmd_reg <= 0;
      dat_reg <= 0;
      dat_cnt <= 0;
      dat_len <= 0;
      cmd_busy_reg <= 0;
      dat_busy_reg <= 0;
      dat_ready_reg <= 0;
      dat_error_reg <= 0;
    end else begin
      case (state)
        IDLE: begin
          if (cmd_busy_reg) begin
            state <= CMD_START;
            cmd_reg <= cmd;
            cmd_type <= cmd[47:40];
            case (cmd_type)
              CMD_READ: data_type <= cmd[31:30];
              CMD_WRITE: data_type <= cmd[31:30];
              CMD_ERASE: data_type <= DATA_SINGLE;
              CMD_FORMAT: data_type <= DATA_SINGLE;
            endcase
          end
        end
        CMD_START: begin
          cmd_busy_reg <= CMD_BUSY;
          state <= CMD_RESP;
        end
        CMD_RESP: begin
          if (cmd_resp_valid) begin
            if (cmd_resp[39:32] != 0) begin
              state <= ERROR;
              dat_error_reg <= DAT_ERROR;
            end else begin
              case (data_type)
                DATA_SINGLE: state <= DATA_START;
                DATA_MULTI: begin
                  dat_cnt <= 0;
                  state <= DATA_WRITE;
                end
              endcase
            end
          end
        end
        DATA_START: begin
          dat_busy_reg <= DAT_BUSY;
          state <= DATA_READ;
        end
        DATA_READ: begin
          if (dat_ready_reg) begin
            dat_o <= dat_reg;
            dat_cnt <= dat_cnt + 1;
            if (dat_cnt == dat_len) begin
              dat_busy_reg <= 0;
              dat_ready_reg <= 0;
              state <= DATA_RESP;
            end else begin
              state <= DATA_READ;
            end
          end
        end
        DATA_WRITE: begin
          if (dat_busy_reg) begin
            dat_reg <= dat_i;
            dat_cnt <= dat_cnt + 1;
            if (dat_cnt == dat_len) begin
              dat_busy_reg <= 0;
              dat_ready_reg <= DAT_READY;
              state <= DATA_RESP;
            end else begin
              state <= DATA_WRITE;
            end
          end
        end
        DATA_RESP: begin
          if (data_resp_valid) begin
            if (data_resp == 0) begin
              state <= IDLE;
              cmd_busy_reg <= 0;
              dat_error_reg <= 0;
            end else begin
              state <= ERROR;
              dat_error_reg <= DAT_ERROR;
            end
          end
        end
        ERROR: begin
          state <= IDLE;
          cmd_busy_reg <= 0;
          dat_busy_reg <= 0;
          dat_ready_reg <= 0;
        end
      endcase
    end
  end

  // Define command response logic
  assign cmd_resp = 48'h0000000000000000;
  assign cmd_resp_valid = (state == CMD_RESP);

  // Define data response logic
  assign data_resp = 2'b00;
  assign data_resp_valid = (state == DATA_RESP);

  // Define CRC error detection logic
  assign crc_error = 0;

  // Define output signals
  assign cmd_busy = cmd_busy_reg;
  assign dat_busy = dat_busy_reg;
  assign dat_ready = dat_ready_reg;
  assign dat_error = dat_error_reg;

endmodule

module top_module ( 
    input [1023:0] in, // 1024-bit input for the multiplexer 
    input [7:0] sel, // 8-bit select input for the multiplexer 
    input a, // First input for the NOR gate 
    input b, // Second input for the NOR gate 
    input sel_ctrl, // Select input for control logic 
    output [3:0] mux_out, // 4-bit output from the multiplexer 
    output nor_out, // Output from the NOR gate 
    output [3:0] final_out // Final output after bitwise OR operation 
);

wire [3:0] mux_sel;
wire [3:0] mux_out_int;

// Multiplexer module
mux_256to1 mux (
    .in(in),
    .sel(mux_sel),
    .out(mux_out_int)
);

// Binary tree architecture for 256-to-1 multiplexer
assign mux_sel[3] = sel[7];
assign mux_sel[2] = sel[6];
assign mux_sel[1] = sel[5:3];
assign mux_sel[0] = sel[2:0];

// NOR gate implemented using NAND gates
wire nand1_out;
wire nand2_out;
assign nand1_out = ~(a & a);
assign nand2_out = ~(b & b);
assign nor_out = ~(nand1_out & nand2_out);

// Control logic to select active module
wire active_module;
assign active_module = sel_ctrl ? nor_out : mux_out_int;

// Functional module for bitwise OR operation
assign final_out = active_module | mux_out;

endmodule

