module adder (
    input [7:0] a,
    input [7:0] b,
    output reg [7:0] sum,
    input clk,
    input reset
);

always @(posedge clk) begin
    if (reset) begin
        sum <= 8'b0;
    end else begin
        sum <= a + b;
    end
end

endmodule

module control_module (
    input select,
    output reg enable_adder1,
    output reg enable_adder2
);

always @(*) begin
    case (select)
        2'b00: begin
            enable_adder1 = 1'b1;
            enable_adder2 = 1'b0;
        end
        2'b01: begin
            enable_adder1 = 1'b0;
            enable_adder2 = 1'b1;
        end
        default: begin
            enable_adder1 = 1'b0;
            enable_adder2 = 1'b0;
        end
    endcase
end

endmodule

module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] a,    // Input for adder 1
    input [7:0] b,    // Input for adder 2
    input select,     // Select input to choose between adder 1 and 2
    output [7:0] sum  // Output of the enabled adder
);

reg enable_adder1, enable_adder2;
wire [7:0] sum1, sum2;

adder adder1(.a(a), .b(b), .sum(sum1), .clk(clk), .reset(reset));
adder adder2(.a(a), .b(b), .sum(sum2), .clk(clk), .reset(reset));
control_module control(.select(select), .enable_adder1(enable_adder1), .enable_adder2(enable_adder2));

always @(posedge clk) begin
    if (reset) begin
        sum <= 8'b0;
    end else begin
        if (enable_adder1) begin
            sum <= sum1;
        end else if (enable_adder2) begin
            sum <= sum2;
        end
    end
end

endmodule

module top_module (
    input clk,        // System clock
    input reset,      // Asynchronous active-high reset
    output reg out    // Output of the functional module
);

reg clk_divided;
reg [3:0] count;

// Edge detection module
always @(posedge clk) begin
    clk_divided <= ~clk_divided;
end

// 4-bit binary counter module
always @(posedge clk_divided or posedge reset) begin
    if (reset) begin
        count <= 4'b0000;
    end else begin
        count <= count + 1;
        if (count == 4'b1111) begin
            count <= 4'b0000;
        end
    end
end

// Functional module to generate square wave with 50% duty cycle
always @(posedge clk_divided or posedge reset) begin
    if (reset) begin
        out <= 1'b0;
    end else begin
        if (count < 4'b1000) begin
            out <= 1'b0;
        end else begin
            out <= 1'b1;
        end
    end
end

endmodule

module reverse_16bit_input (
  input [15:0] input_vector,
  output reg [15:0] output_vector
);

  integer i;
  reg [7:0] first_half;
  reg [7:0] second_half;

  always @(*) begin
    for (i = 0; i < 8; i = i + 1) begin
      first_half[i] = input_vector[7 - i];
      second_half[i] = input_vector[15 - i];
    end
    output_vector = {second_half, first_half};
  end

endmodule

