  input [26:0] PREADD_AB
);

reg [26:0] D_DATA_mux;
wire [26:0] preadd_out;

assign D_DATA_mux = INMODE2 ? D_DATA : 27'b0;

// pre-addition operation
assign preadd_out = ADDSUB ? (D_DATA_mux - PREADD_AB) : (D_DATA_mux + PREADD_AB);

// final output
assign AD = preadd_out;

endmodule

module falling_edge_detector (
    input clk,
    input reset,
    input [31:0] in,
    output reg [31:0] out
);

reg [31:0] shift_reg;

always @(posedge clk) begin
    if (reset) begin
        shift_reg <= 0;
        out <= 0;
    end else begin
        shift_reg <= {shift_reg[30:0], in};
        out <= out & ~shift_reg;
    end
end

endmodule

