    input [7:0] priority_in, // 8-bit input for priority encoder
    output reg [7:0] sum_out // 8-bit output from functional module
);

reg [3:0] twos_comp_out;
wire [2:0] priority_index;
wire priority_valid;

twos_complement twos_comp_inst (
    .in(in),
    .out(twos_comp_out)
);

priority_encoder priority_enc_inst (
    .in(priority_in),
    .out(priority_index[2]),
    .valid(priority_valid),
