endmodule

module priority_encoder (
    input [7:0] in, // 8 inputs
    output reg out, // 1-bit output
    output reg valid, // 1-bit output
    output reg [2:0] index // 3-bit output
);

always @(*) begin
    if (in[7]) begin
        out = 1;
        index = 7;
    end else if (in[6]) begin
        out = 1;
        index = 6;
    end else if (in[5]) begin
        out = 1;
        index = 5;
    end else if (in[4]) begin
        out = 1;
        index = 4;
    end else if (in[3]) begin
        out = 1;
        index = 3;
    end else if (in[2]) begin
        out = 1;
        index = 2;
    end else if (in[1]) begin
        out = 1;
        index = 1;
    end else if (in[0]) begin
        out = 1;
        index = 0;
    end else begin
        out = 0;
        index = 0;
    end
end

endmodule

