  wire [4:0] v1_reg;
  wire wr_en;
  wire wr_rst_busy;
  wire out;
  wire ram_full_fb_i_reg;

  // CARRY4 gate to compute carry-out of v1_reg + 1'b1
  (* XILINX_LEGACY_PRIM = "(MUXCY,XORCY)" *) 
  (* box_type = "PRIMITIVE" *) 
  CARRY4 carry_1
       (.CI(1'b0),
        .CO({carrynet_3,carrynet_2,carrynet_1,carrynet_0}),
        .CYINIT(1'b1),
        .DI({1'b0,1'b0,1'b0,1'b0}),
        .O(carry_out_1),
        .S(v1_reg[3:0]));

  // CARRY4 gate to compute carry-out of v1_reg + 16'h0020
  (* XILINX_LEGACY_PRIM = "(MUXCY,XORCY)" *) 
  (* box_type = "PRIMITIVE" *) 
  CARRY4 carry_2
       (.CI(carry_out_1[3]),
        .CO({carry_out_2[2],carry_out_2[1],carry_out_2[0],comp2}),
        .CYINIT(1'b0),
        .DI({carry_in_2[2],carry_in_2[1],carry_in_2[0],1'b0}),
        .O(carry_in_1),
        .S({carry_sum_2[2],carry_sum_2[1],carry_sum_2[0],v1_reg[4]}));

  // Connect the carry-out of the second CARRY4 gate to the input of the LUT5 gate
  LUT5 #(
    .INIT(32'h00FF0020)) 
    ram_full_i_i_1
       (.I0(comp2),
        .I1(out),
        .I2(wr_en),
        .I3(wr_rst_busy),
        .I4(carry_out_2[3]),
        .O(ram_full_fb_i_reg));
endmodule

module gated_clk (
    input  CLK ,
    input  GATE,
    input  VPB ,
    input  VPWR,
    input  VGND,
    input  VNB,
    output GCLK
);

    reg gated_clk;

    always @(posedge CLK) begin
        if (GATE) begin
            gated_clk <= 1'b1;
        end else begin
            gated_clk <= 1'b0;
        end
    end

    assign GCLK = gated_clk;

    // Output buffer
    bufif0 buf (
        .in(gated_clk),
        .out(GCLK),
        .vdd(VPB),
        .vss(VGND),
        .vpwr(VPWR),
        .vnw(VNB)
    );

endmodule

module seq_detector (
  input [n-1:0] in,
  output out
);

  parameter n = 4; // number of input signals
  parameter seq = 4'b1010; // sequence to be detected

  // Define the states of the state machine
  parameter IDLE = 2'b00;
  parameter MATCH1 = 2'b01;
  parameter MATCH2 = 2'b10;

  // Define the current state and next state variables
  reg [1:0] state, next_state;

  // Define the output signal
  reg out;

  // Define the sequence matching logic
  always @(*) begin
    case(state)
      IDLE: begin
        if(in == seq[0])
          next_state = MATCH1;
        else
          next_state = IDLE;
      end
      MATCH1: begin
        if(in == seq[1])
          next_state = MATCH2;
        else if(in == seq[0])
          next_state = MATCH1;
        else
          next_state = IDLE;
      end
      MATCH2: begin
        if(in == seq[2])
          next_state = IDLE;
        else if(in == seq[1])
          next_state = MATCH2;
        else if(in == seq[0])
          next_state = MATCH1;
        else
          next_state = IDLE;
      end
    endcase
  end

  // Define the state transition logic
  always @(posedge clk) begin
    state <= next_state;
  end

  // Define the output logic
  always @(*) begin
    if(state == MATCH2)
      out = 1'b1;
    else
      out = 1'b0;
  end

endmodule

module ripple_carry_adder (
  input [n-1:0] a,
  input [n-1:0] b,
  input cin,
  output [n-1:0] s,
  output cout
);

parameter n = 4; // number of bits in input numbers A and B

wire [n:0] carry;
assign carry[0] = cin;

// Full Adder
genvar i;
generate
  for (i = 0; i < n; i = i + 1) begin : full_adder
    assign s[i] = a[i] ^ b[i] ^ carry[i];
    assign carry[i+1] = (a[i] & b[i]) | (a[i] & carry[i]) | (b[i] & carry[i]);
  end
endgenerate

assign cout = carry[n];

endmodule

module FP16BAddSubS4Of5(
 input 	       clk,
 input 	       rst,
 input [14:0]  arg_0,
 input 	       arg_1,
 input 	       arg_2,
 input [7:0]   arg_3,
 input 	       arg_4,
 input 	       arg_5,
 input 	       arg_6,
 output [15:0] ret_0);

   // Assign input signals to internal wires
   wire [15:0] r;
   wire        xs;
   wire        ys;
   wire [7:0]  e;
   wire [7:0]  e_final;
   wire [8:0]  e_l0adjust;
   wire        underflow;
   wire [7:0]  e_adjust;
   wire        neg;
   wire        xn;
   wire        yn;
   wire [7:0] rr;
   wire [6:0] r_final;
   wire [15:0] r8;
   wire [15:0] r4;
   wire [15:0] r2;
   wire [15:0] r1;
   wire [3:0]  l0count;
   wire        s;

   assign r = arg_0;
   assign xs = arg_1;
   assign ys = arg_2;
   assign e = arg_3;
   assign neg = arg_4;
   assign xn = arg_5;
   assign yn = arg_6;

   // Compute s
   assign s = (xn == yn) ? xs : (yn ? (neg ^ xs): (neg ^ ys));

   // Compute r8
   assign r8 = (r[14:7] == 0) ? {r[6:0], 8'b0} : r;

   // Compute r4
   assign r4 = (r8[14:11] == 0) ? {r8[10:0], 4'b0} : r8;

   // Compute r2
   assign r2 = (r4[14:13] == 0) ? {r4[12:0], 2'b0} : r4;

   // Compute r1
   assign r1 = (r2[14:14] == 0) ? {r2[13:0], 1'b0} : r2;

   // Compute l0count
   assign l0count = {r[14:7] == 0, r8[14:11] == 0, r4[14:13] == 0, r2[14:14] == 0};

   // Compute rr
   assign rr = (xn == yn) ? r[14:7] : r1;

   // Compute e_l0adjust
   assign e_l0adjust = e - l0count;

   // Compute underflow
   assign underflow = e_l0adjust[8:8];

   // Compute e_adjust
   assign e_adjust = underflow ? 0 : e_l0adjust[7:0];

   // Compute e_final
   assign e_final = (xn == yn) ? e : e_adjust[7:0];

   // Compute r_final
   assign r_final = underflow ? 0 : rr[6:0];

   // Assign output signal
   assign ret_0 = {s, e_final, r_final};

endmodule

module top_module( 
    input [3:0] in,
    output out_and,
    output out_or,
    output out_xor
);

wire [3:0] nor_in;
wire nor_out_and, nor_out_or, nor_out_xor;

assign nor_in = ~in;

assign nor_out_and = ~(nor_in[0] | nor_in[1] | nor_in[2] | nor_in[3]);
assign nor_out_or = ~(nor_in[0] & nor_in[1] & nor_in[2] & nor_in[3]);
assign nor_out_xor = ~(nor_in[0] ^ nor_in[1] ^ nor_in[2] ^ nor_in[3]);

assign out_and = ~nor_out_and;
assign out_or = ~nor_out_or;
assign out_xor = ~nor_out_xor;

endmodule

module barrel_shifter (
    input [7:0] data_in,
    input [2:0] shift_amount,
    output [7:0] data_out
);

    always @(*) begin
        case(shift_amount)
            3'b000: data_out = data_in;
            3'b001: data_out = {data_in[7], data_in[7:1]};
            3'b010: data_out = {data_in[6:0], 2'b00};
            3'b011: data_out = {data_in[5:0], 3'b000};
            3'b100: data_out = {data_in[4:0], 4'b0000};
            3'b101: data_out = {data_in[3:0], 5'b00000};
            3'b110: data_out = {data_in[2:0], 6'b000000};
            3'b111: data_out = {data_in[1:0], 7'b0000000};
        endcase
    end

endmodule

module twos_complement (
    input [3:0] in,
    output reg [3:0] out
);

assign out = (~in) + 4'b1;

