module top_module (
    input [3:0] a,
    input [3:0] b,
    input [3:0] in,
    input ena,
    input select, // Select input to choose between adder and decoder
    output [3:0] out // Output from functional module
);

    wire [3:0] adder_out;
    wire decoder_en;
    wire [15:0] decoder_out;
    wire carry_out;

    binary_adder adder_inst (
        .a(a),
        .b(b),
        .sum(adder_out),
        .carry_out(carry_out)
    );

    decoder_4to16 decoder_inst (
        .in(in),
        .ena(decoder_en),
        .out(decoder_out)
    );

    assign decoder_en = ena & select;

    assign out[3] = decoder_out[15];
    assign out[2:0] = {carry_out, adder_out};

endmodule

module binary_adder (
    input [3:0] a,
    input [3:0] b,
    output reg [3:0] sum,
    output carry_out
);

    always @(*) begin
        {carry_out, sum} = a + b;
    end

