module up_counter (
    input clk,
    input rst,
    output reg [2:0] out,
    output reg carry_out
);

    always @(posedge clk) begin
        if (rst) begin
            out <= 3'b0;
            carry_out <= 1'b0;
        end
        else if (out == 3'b111) begin
            out <= 3'b0;
            carry_out <= 1'b1;
        end
        else begin
            out <= out + 1;
            carry_out <= 1'b0;
        end
    end

endmodule

module fifo_buffer (
    input clk,
    input rd,
    input reset_n,
    input wr,
    input [7:0] wr_data,
    output almost_empty,
    output almost_full,
    output empty,
    output full,
    output reg [7:0] rd_data
);

    reg [7:0] entry_0;
    reg [7:0] entry_1;
    reg [1:0] wr_address;
    reg [1:0] rd_address;
    reg [1:0] entries;

    assign almost_empty = (entries <= 1) ? 1'b1 : 1'b0;
    assign almost_full = (entries >= 1) ? 1'b1 : 1'b0;
    assign empty = (entries == 0) ? 1'b1 : 1'b0;
    assign full = (entries == 2) ? 1'b1 : 1'b0;

    always @(posedge clk or negedge reset_n) begin
        if (~reset_n) begin
            wr_address <= 2'b00;
            rd_address <= 2'b00;
            entries <= 0;
            rd_data <= 0;
        end else begin
            if (wr & ~full) begin
                case (wr_address)
                    2'b00: entry_0 <= wr_data;
                    2'b01: entry_1 <= wr_data;
                endcase
                wr_address <= (wr_address == 2'b01) ? 2'b00 : wr_address + 1;
                entries <= entries + 1;
            end
            if (rd & ~empty) begin
                case (rd_address)
                    2'b00: rd_data <= entry_0;
                    2'b01: rd_data <= entry_1;
                endcase
                rd_address <= (rd_address == 2'b01) ? 2'b00 : rd_address + 1;
                entries <= entries - 1;
            end
        end
    end

endmodule

module fifo(
    input clk,
    input rstn,
    input wr_en,
    input rd_en,
    input [7:0] data_in,
    output [7:0] data_out,
    output empty,
    output full
);

reg [7:0] mem [31:0];
reg [4:0] write_ptr;
reg [4:0] read_ptr;
reg [4:0] count;

assign empty = (count == 0);
assign full = (count == 32);

always @(posedge clk or negedge rstn) begin
    if (~rstn) begin
        write_ptr <= 5'd0;
        read_ptr <= 5'd0;
        count <= 5'd0;
    end
    else begin
        if (wr_en && ~full) begin
            mem[write_ptr] <= data_in;
            write_ptr <= write_ptr + 1;
            count <= count + 1;
        end
        if (rd_en && ~empty) begin
            data_out <= mem[read_ptr];
            read_ptr <= read_ptr + 1;
            count <= count - 1;
        end
    end
end

endmodule

module multiplier (
  input [31:0] A,
  input [31:0] B,
  output [63:0] Y
);

  reg signed [63:0] signed_A;
  reg signed [63:0] signed_B;
  reg signed [63:0] signed_Y;

  always @(*) begin
    if (A[31] == 1) begin
      signed_A = {32'b11111111_11111111_11111111_11111111, A};
    end else begin
      signed_A = {32'b00000000_00000000_00000000_00000000, A};
    end

    if (B[31] == 1) begin
      signed_B = {32'b11111111_11111111_11111111_11111111, B};
    end else begin
      signed_B = {32'b00000000_00000000_00000000_00000000, B};
    end

    signed_Y = signed_A * signed_B;

    if (A[31] == 1 && B[31] == 1) begin
      Y = signed_Y[63:0];
    end else if (A[31] == 0 && B[31] == 0) begin
      Y = signed_Y[31:0];
    end else begin
      Y = signed_Y[63:0];
    end
  end

endmodule

module decoder (
    input [2:0] ABC,
    input EN,
    output reg [7:0] Y
);

reg [7:0] Y_pipe1;
reg [7:0] Y_pipe2;

always @(ABC, EN) begin
    Y_pipe1 <= {8{1'b0}};
    if (EN == 1'b1) begin
        case (ABC)
            3'b000: Y_pipe1[0] <= 1'b1;
            3'b001: Y_pipe1[1] <= 1'b1;
            3'b010: Y_pipe1[2] <= 1'b1;
            3'b011: Y_pipe1[3] <= 1'b1;
            3'b100: Y_pipe1[4] <= 1'b1;
            3'b101: Y_pipe1[5] <= 1'b1;
            3'b110: Y_pipe1[6] <= 1'b1;
            3'b111: Y_pipe1[7] <= 1'b1;
            default: Y_pipe1 <= {8{1'b0}};
        endcase
    end
end

always @(posedge clk) begin
    Y_pipe2 <= Y_pipe1;
end

assign Y = EN ? Y_pipe2 : {8{1'b0}};

endmodule

