module dff_asynchronous_set (
    Q    ,
    Q_N  ,
    CLK  ,
    D    ,
    SET_B
);

    // Module ports
    output Q    ;
    output Q_N  ;
    input  CLK  ;
    input  D    ;
    input  SET_B;

    // Module supplies
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    // Local signals
    wire buf_Q        ;
    wire SET          ;
    reg  notifier     ;
    wire D_delayed    ;
    wire SET_B_delayed;
    wire CLK_delayed  ;
    wire awake        ;
    wire cond0        ;
    wire cond1        ;

    //                                  Name  Output  Other arguments
    not                                 not0 (SET   , SET_B_delayed                                    );
    sky130_fd_sc_ls__udp_dff$PS_pp$PG$N dff0 (buf_Q , D_delayed, CLK_delayed, SET, notifier, VPWR, VGND);
    assign awake = ( VPWR === 1'b1 );
    assign cond0 = ( SET_B_delayed === 1'b1 );
    assign cond1 = ( SET_B === 1'b1 );
    buf                                 buf0 (Q     , buf_Q                                            );
    not                                 not1 (Q_N   , buf_Q                                            );

    // Delayed versions of inputs
    sky130_fd_sc_ls__dlh dff1 (D_delayed    , D    , CLK, awake, VPWR, VGND);
    sky130_fd_sc_ls__dlh dff2 (SET_B_delayed, SET_B, CLK, awake, VPWR, VGND);
    sky130_fd_sc_ls__dlh dff3 (CLK_delayed  , CLK  , CLK, awake, VPWR, VGND);

    // Notifier for DFF
    always @(posedge CLK) begin
        notifier <= 1;
    end

    // Asynchronous set logic
    always @(SET_B or SET_B_delayed) begin
        if (SET_B == 1'b0 && SET_B_delayed == 1'b1) begin
            notifier <= 0;
        end
    end

endmodule

module shift_register(clk, rst, load, shift_left, shift_right, serial_in, shift_reg);
