		if (rst) begin
			shift_reg <= 0;
		end else if (load) begin
			shift_reg <= serial_in;
		end else if (shift_left) begin
			shift_reg <= {shift_reg[2:0], shift_reg[3]};
		end else if (shift_right) begin
			shift_reg <= {shift_reg[1], shift_reg[3:1]};
		end
