module top_module (
  input clk,
  input reset, // Synchronous active-high reset
  input a,
  input b,
  input c,
  input d,
  input [1:0] sel, // 2-bit selector input
  output reg [7:0] out // 8-bit output from the functional module
);

  reg [7:0] mux1_out;
  reg [7:0] mux2_out;
  reg [7:0] delayed_sum;

  mux_2to1 mux1 (.a(a), .b(b), .sel(sel[0]), .out_mux(mux1_out));
  mux_2to1 mux2 (.a(c), .b(d), .sel(sel[1]), .out_mux(mux2_out));
  func_module func (.in1(mux1_out), .in2(mux2_out), .out(delayed_sum));

  always @(posedge clk) begin
    if (reset) begin
      mux1_out <= 8'b00000001;
      mux2_out <= 8'b00000001;
      delayed_sum <= 8'b00000000;
      out <= 8'b00000000;
    end else begin
      mux1_out <= sel[0] ? b : a;
      mux2_out <= sel[1] ? d : c;
      out <= delayed_sum;
      delayed_sum <= mux1_out + mux2_out;
    end
  end

endmodule

