    end else begin
      if (io_in_valid && io_out_ready) begin
        io_in_ready <= 1'b0;
        io_out_valid <= 1'b1;
        io_out_bits_centeroidsFinished <= io_in_bits_centeroidsFinished;
        io_out_bits_pointsFinished <= io_in_bits_pointsFinished;
