module top_module (
    input clk,
    input reset,            // Asynchronous reset input
    input [7:0] in,
    output [7:0] dff_output, // Output from the D flip-flop
    output [7:0] anyedge_output // Output from the rising edge detector
);

    // Instantiate the D flip-flop module with asynchronous reset
    dff_with_reset dff (
        .clk(clk),
        .reset(reset),
        .d(in),
        .q(dff_output)
    );

    // Instantiate the rising edge detector module
    rising_edge_detector red (
        .clk(clk),
        .d(in),
        .q(anyedge_output)
    );

