// Rising edge detector module using shift register and D flip-flop
module rising_edge_detector (
    input clk,
    input d,
    output reg [7:0] q
);

    reg [7:0] shift_reg;
    reg [7:0] shifted_reg;

    always @(posedge clk) begin
        shift_reg <= d;
        shifted_reg <= shift_reg;
        q <= shifted_reg & ~shift_reg;
    end

endmodule

