module top_module (
    input clk,
    input [7:0] in1,
    input [7:0] in2,
    output reg [7:0] sum,
    output reg overflow
);

    wire [7:0] highest_priority_input;
    wire [7:0] second_input;
    wire [7:0] adder_output;

    priority_encoder priority_encoder_inst (
        .in1(in1),
        .in2(in2),
        .out(highest_priority_input)
    );

    assign second_input = (highest_priority_input == in1) ? in2 : in1;

    ripple_carry_adder ripple_carry_adder_inst (
        .clk(clk),
        .in1(highest_priority_input),
        .in2(second_input),
        .out(adder_output),
        .overflow(overflow)
    );

    assign sum = adder_output;

endmodule

module priority_encoder (
    input [7:0] in1,
    input [7:0] in2,
    output reg [7:0] out
);

    always @* begin
        if (in1 > in2) begin
            out = in1;
        end else begin
            out = in2;
        end
    end

endmodule

module ripple_carry_adder (
    input clk,
    input [7:0] in1,
    input [7:0] in2,
    output reg [7:0] out,
    output reg overflow
);

    reg [7:0] sum;
    reg carry;

    always @(posedge clk) begin
        {carry, sum} <= in1 + in2;
    end

    always @(posedge clk) begin
        if (carry == 1) begin
            overflow = 1;
        end else begin
            overflow = 0;
        end
    end

    assign out = sum;

endmodule

