always @(posedge clk or posedge rst) begin
  if (rst) begin
    wr_ptr <= 0;
    rd_ptr <= 0;
    cnt <= 0;
    full_reg <= 0;
    empty_reg <= 1;
    for (i=0; i<8192; i=i+1) begin
      mem[i] <= 0;
