module MemoryCompDecomp (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 32; // number of input signals
parameter m = 32; // number of output signals

wire [31:0] compressed_data [0:m/2-1];
wire [31:0] decompressed_data [0:n-1];

// Compression block
integer i, j, count;
reg [15:0] value;
reg [31:0] compressed_word;

always @* begin
  i = 0;
  j = 0;
  compressed_word = 0;
  count = 1;
  value = in[0];

  // Perform run-length encoding
  while (i < n) begin
    if (in[i] == value) begin
      count = count + 1;
    end else begin
      compressed_word = {count, value};
      compressed_data[j] = compressed_word;
      j = j + 1;
      count = 1;
      value = in[i];
    end
    i = i + 1;
  end

  // Output compressed data
  for (i = 0; i < m/2; i = i + 1) begin
    out[i*2] = compressed_data[i][31:16];
    out[i*2+1] = compressed_data[i][15:0];
  end
end

// Decompression block
integer k, l;
reg [31:0] decompressed_word;

always @* begin
  k = 0;
  l = 0;

  // Perform run-length decoding
  while (k < m/2) begin
    count = out[k*2];
    value = out[k*2+1];
    decompressed_word = {value, {16{1'b0}}};
    for (i = 0; i < count; i = i + 1) begin
      decompressed_data[l] = decompressed_word;
      l = l + 1;
    end
    k = k + 1;
  end

  // Output decompressed data
  for (i = 0; i < n; i = i + 1) begin
    out[i] = decompressed_data[i];
  end
end

endmodule

