module add_sub_shift_abs (
    input [15:0] a,
    input [15:0] b,
    input [7:0] select,
    output [15:0] result,
    output overflow
);

    wire [15:0] add_out;
    wire [15:0] sub_out;
    wire [15:0] shift_out;
    wire [15:0] abs_out;

    assign overflow = (add_out[15] & sub_out[15]);

    adder_subtractor add_sub (
        .a(a),
        .b(b),
        .add_out(add_out),
        .sub_out(sub_out)
    );

    barrel_shifter shift (
        .a(select[1:0] == 2'b00 ? add_out : select[1:0] == 2'b01 ? sub_out : a),
        .shift_amount(select[3:2]),
        .shift_out(shift_out)
    );

    assign abs_out = (result[15] == 1'b1) ? (~result + 1) : result;

    assign result = (select[1:0] == 2'b00) ? add_out :
                   (select[1:0] == 2'b01) ? sub_out :
                   (select[1:0] == 2'b10) ? shift_out :
                   (select[1:0] == 2'b11) ? shift_out :
                   16'b0;

endmodule

