module adder_4bit (
    input [3:0] A,
    input [3:0] B,
    input C_in,
    output [3:0] S,
    output C_out
);

    wire [3:0] adder1;
    wire [3:0] adder2;
    wire [3:0] adder3;
    wire [3:0] adder4;

    assign adder1[0] = A[0] ^ B[0] ^ C_in;
    assign adder1[1] = A[1] ^ B[1] ^ adder1[0];
    assign adder1[2] = A[2] ^ B[2] ^ adder1[1];
    assign adder1[3] = A[3] ^ B[3] ^ adder1[2];

    assign adder2[0] = A[0] & B[0];
    assign adder2[1] = A[1] & B[1];
    assign adder2[2] = A[2] & B[2];
    assign adder2[3] = A[3] & B[3];

    assign adder3[0] = adder1[0] & adder2[0];
    assign adder3[1] = adder1[1] & adder2[1];
    assign adder3[2] = adder1[2] & adder2[2];
    assign adder3[3] = adder1[3] & adder2[3];

    assign adder4[0] = C_in & adder2[0];
    assign adder4[1] = adder1[0] & adder2[1];
    assign adder4[2] = adder1[1] & adder2[2];
    assign adder4[3] = adder1[2] & adder2[3];

    assign C_out = adder3[3] | adder4[3];
    assign S[0] = adder1[0] ^ adder2[0];
    assign S[1] = adder1[1] ^ adder2[1] ^ adder3[0];
    assign S[2] = adder1[2] ^ adder2[2] ^ adder3[1];
    assign S[3] = adder1[3] ^ adder2[3] ^ adder3[2] ^ adder4[0];

endmodule

