module fifo_reader(
    input clk,
    input reset,
    input hold,
    input rxf,
    input [7:0] data,
    output reg [7:0] out,
    output reg newout
);

    // State definitions
    parameter RESET = 0;
    parameter WAIT = 1;
    parameter WAIT2 = 2;
    parameter WAIT3 = 3;
    parameter DATA_COMING = 4;
    parameter DATA_COMING_2 = 5;
    parameter DATA_COMING_3 = 6;
    parameter DATA_HERE = 7;
    parameter DATA_LEAVING = 8;
    parameter DATA_LEAVING_2 = 9;
    parameter DATA_LEAVING_3 = 10;
    parameter DATA_LEAVING_4 = 11;
    parameter DATA_LEAVING_5 = 12;
    parameter DATA_LEAVING_6 = 13;

    // Internal state register
    reg [3:0] state;

    // Output state for debugging purposes
    output state;

    // Read enable signal
    reg rd;

    // Initialize state and read enable
    initial begin
        state <= WAIT;
        rd <= 1;
    end

    // State machine
    always @(posedge clk) begin
        if (reset) begin
            newout <= 0;
            rd <= 1;
            state <= WAIT;
        end else if (~hold) begin
            newout <= 0;
            case (state)
                WAIT:
                    if (~rxf) begin
                        rd <= 1;
                        state <= WAIT2;
                    end
                WAIT2:
                    if (~rxf) begin
                        rd <= 1;
                        state <= WAIT3;
                    end else begin
                        state <= WAIT;
                    end
                WAIT3:
                    if (~rxf) begin
                        rd <= 0;
                        state <= DATA_COMING;
                    end else begin
                        state <= WAIT;
                    end
                DATA_COMING:
                    state <= DATA_COMING_2;
                DATA_COMING_2:
                    state <= DATA_COMING_3;
                DATA_COMING_3:
                    state <= DATA_HERE;
                DATA_HERE:
                    begin
                        out <= data;
                        state <= DATA_LEAVING;
                        newout <= 1;
                    end
                DATA_LEAVING:
                    begin
                        rd <= 1;
                        state <= DATA_LEAVING_2;
                        newout <= 0;
                    end
                DATA_LEAVING_2:
                    state <= DATA_LEAVING_3;
                DATA_LEAVING_3:
                    state <= DATA_LEAVING_4;
                DATA_LEAVING_4:
                    state <= DATA_LEAVING_5;
                DATA_LEAVING_5:
                    state <= DATA_LEAVING_6;
                DATA_LEAVING_6:
                    begin
                        state <= WAIT;
                        rd <= 1;
                    end
                default:
                    state <= WAIT;
            endcase
        end
    end

endmodule

