module uart_transmitter (
  input clk,
  input rst,
  input [7:0] data_in,
  input start,
  output reg tx,
  output reg done
);

  reg [3:0] counter;
  reg [9:0] shift_reg;

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      counter <= 4'b0;
      tx <= 1'b1;
      done <= 1'b0;
    end else begin
      if (start && counter == 4'b0) begin
        shift_reg <= {1'b1, data_in, 1'b0};
        counter <= 4'b0001;
        done <= 1'b0;
      end else if (counter != 4'b0) begin
        tx <= shift_reg[0];
        shift_reg <= {1'b1, shift_reg[9:1]};
        counter <= counter + 4'b0001;
        if (counter == 4'b1010) begin
          counter <= 4'b0;
          done <= 1'b1;
        end
      end
    end
  end
endmodule

module uart_receiver (
  input clk,
  input rst,
  input rx,
  output reg [7:0] data_out,
  output reg valid
);

  reg [3:0] counter;
  reg [9:0] shift_reg;
  reg waiting_for_start;

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      counter <= 4'b0;
      waiting_for_start <= 1'b1;
      valid <= 1'b0;
    end else begin
      if (waiting_for_start) begin
        if (!rx) begin
          counter <= 4'b0001;
          waiting_for_start <= 1'b0;
        end
      end else begin
        counter <= counter + 4'b0001;
        if (counter == 4'b1010) begin
          shift_reg <= {rx, shift_reg[9:1]};
          data_out <= shift_reg[8:1];
          valid <= shift_reg[9];
          waiting_for_start <= 1'b1;
          counter <= 4'b0;
        end else begin
          shift_reg <= {rx, shift_reg[9:1]};
          valid <= 1'b0;
        end
      end
    end
  end
endmodule

module interrupt_controller (
  input [n-1:0] irq,
  output [m-1:0] ack
);

parameter n = 4; // number of interrupt request signals
parameter m = 2; // number of interrupt acknowledge signals

reg [n-1:0] irq_priority; // priority encoder output
reg [m-1:0] ack_signals; // interrupt acknowledge signals

// add any other necessary parameters here

  // add any necessary input/output declarations here

  // Priority encoder logic
  always @* begin
    casez(irq)
      4'b1000: irq_priority = 4'b1000; // highest priority
      4'b0100: irq_priority = 4'b0100;
      4'b0010: irq_priority = 4'b0010;
      4'b0001: irq_priority = 4'b0001; // lowest priority
      default: irq_priority = 4'b0000; // no interrupt request
    endcase
  end

  // Interrupt acknowledge signal generation logic
  always @* begin
    casez(irq_priority)
      4'b1000: ack_signals = 2'b11; // highest priority
      4'b0100: ack_signals = 2'b10;
      4'b0010: ack_signals = 2'b01;
      4'b0001: ack_signals = 2'b01; // lowest priority
      default: ack_signals = 2'b00; // no interrupt request
    endcase
  end

  // Connect the interrupt request signals to the priority encoder
  assign irq_priority = irq;

  // Connect the priority encoder to the interrupt acknowledge signals
  assign ack = ack_signals;

  // Clear signal logic
  always @(posedge clear) begin
    irq_priority <= 4'b0000;
    ack_signals <= 2'b00;
  end

endmodule

