module fifo(clk, rst, data_in, data_out, wr_en, rd_en, empty, full, cnt);

parameter data_width = 1;
parameter addr_width = 1;
`define BUF_SIZE (1 << addr_width)

input clk, rst, wr_en, rd_en;
input[data_width-1:0] data_in;
output[data_width-1:0] data_out;
output empty, full;
output[addr_width-1:0] cnt;

reg[data_width-1:0] data_out;
reg[addr_width-1:0] cnt;

reg[addr_width-1:0] rd_ptr, wr_ptr;
reg[data_width-1:0] buf_mem[`BUF_SIZE-1:0];
wire rd, wr;

assign full = (cnt == (`BUF_SIZE-1));
assign empty = (!cnt);
assign rd = (!empty && rd_en);
assign wr = (!full && wr_en);

// cnt
always @ (posedge clk or posedge rst)
    cnt <= rst ? 0 : (rd && !wr) ? cnt-1 : (!rd && wr) ? cnt+1 : cnt;

// data_out
always @ (posedge clk or posedge rst)
    data_out <= rst ? 0 : rd ? buf_mem[rd_ptr] : data_out;

// data_in
always @ (posedge clk)
    buf_mem[wr_ptr] <= wr ? data_in : buf_mem[wr_ptr];

// pointers
always @ (posedge clk or posedge rst) begin
    if (rst) begin
        wr_ptr <= 0;
        rd_ptr <= 0;
    end else begin
        rd_ptr <= rd ? rd_ptr+1 : rd_ptr;
        wr_ptr <= wr ? wr_ptr+1 : wr_ptr;
    end
end

endmodule

module shift_register (
    input clk,
    input reset,            // Synchronous reset
    input [7:0] d,
    input shift_left,       // Control signal to shift left
    input shift_right,      // Control signal to shift right
    output reg [3:0] q
);

    reg [7:0] storage [0:3]; // 8-bit binary number storage module
    reg [7:0] temp;          // Temporary variable for shifting

    always @(posedge clk) begin
        if (reset) begin
            storage <= 0;
            q <= 0;
        end else begin
            // Shift left
            if (shift_left) begin
                temp[7] <= storage[0][0];
                temp[6:0] <= storage[0][7:1];
                storage[0] <= d;
                storage[1] <= temp;
                temp[7] <= storage[2][0];
                temp[6:0] <= storage[2][7:1];
                storage[2] <= storage[1];
                storage[3] <= temp;
            end
            // Shift right
            else if (shift_right) begin
                temp[0] <= storage[3][7];
                temp[1:7] <= storage[3][6:0];
                storage[3] <= d;
                storage[2] <= temp;
                temp[0] <= storage[1][7];
                temp[1:7] <= storage[1][6:0];
                storage[1] <= storage[2];
                storage[0] <= temp;
            end
            // No shift
            else begin
                storage[0] <= d;
                storage[1] <= storage[0];
                storage[2] <= storage[1];
                storage[3] <= storage[2];
            end
            // Bit-wise logical operation
            q <= {storage[3][0] & storage[2][0], storage[1][0] & storage[0][0]};
        end
    end

endmodule

