    reg [2:0] head, tail;
    reg [2:0] next_tail;
    wire [2:0] next_head;
    wire [2:0] curr_head;
    wire [2:0] curr_tail;

    assign curr_head = head;
    assign curr_tail = tail;
    assign next_head = (curr_head + 1'b1) % SIZE;

    always @(posedge clk) begin
        if(wr_en && !full) begin
            memory[tail] <= data_in;
            next_tail <= (tail + 1'b1) % SIZE;
        end
        tail <= next_tail;
    end

    always @(posedge clk) begin
        if(rd_en && !empty) begin
            data_out <= memory[head];
            head <= next_head;
        end
    end

    assign empty = (head == tail) ? 1'b1 : 1'b0;
    assign full = ((next_tail == head) && (head != tail)) ? 1'b1 : 1'b0;

endmodule

