module clock_generator(
    input sys_clk,
    input sys_reset,
    output reg clk_out,
    output reg reset_out
);

reg [3:0] counter;

always @(posedge sys_clk) begin
    if (counter == 4'd9) begin
        counter <= 4'd0;
        reset_out <= 1'b0;
    end else begin
        counter <= counter + 4'd1;
        reset_out <= 1'b1;
    end
    clk_out <= counter[0];
end

endmodule

module calculator(
   input [7:0] a,
   input [7:0] b,
   input [1:0] op,
   input start,
   output reg done,
   output reg [7:0] result
   );

   reg [15:0] temp;

   always@(posedge start)
   begin
      case(op)
         2'b00:result <= a + b;
         2'b01:result <= a - b;
         2'b10:result <= a * b;
         2'b11:begin
                  if(b == 0) result <= 8'hFF; // division by zero
                  else begin
                     temp <= a;
                     result <= 0;
                     for (i = 0; i < 8; i = i + 1) begin
                        if (temp >= b) begin
                           temp <= temp - b;
                           result[i] <= 1;
                        end
                        temp <= temp << 1;
                     end
                  end
               end
         default:result <= 8'hFF; // invalid operation
      endcase

      done <= 1;
      while(start) begin
         // wait for start to go low
      end
      done <= 0;
   end

endmodule

module key (
  input [1:0] address,
  input chipselect,
  input clk,
  input in_port,
  input reset_n,
  input write_n,
  input [31:0] writedata,
  output irq,
  output [31:0] readdata
);

  reg [31:0] mem [3:0];
  reg [31:0] read_mux_out;
  reg [31:0] readdata_reg;
  reg irq_mask;
  wire clk_en;

  assign clk_en = 1;

  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      readdata_reg <= 0;
      irq_mask <= 0;
    end else if (clk_en) begin
      readdata_reg <= read_mux_out;
    end
  end

  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      mem[0] <= 0;
      mem[1] <= 0;
      mem[2] <= 0;
      mem[3] <= 0;
    end else if (chipselect && ~write_n) begin
      mem[address] <= writedata;
    end
  end

  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      read_mux_out <= 0;
    end else begin
      case (address)
        2'b00: read_mux_out <= mem[0];
        2'b01: read_mux_out <= mem[1];
        2'b10: read_mux_out <= irq_mask;
        2'b11: read_mux_out <= mem[3];
      endcase
    end
  end

  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      irq_mask <= 0;
    end else if (chipselect && write_n && (address == 2)) begin
      irq_mask <= writedata;
    end
  end

  assign irq = |(in_port & irq_mask);

  assign readdata = readdata_reg;

endmodule

module top_module (
    input a, b, c,
