    output reg [2:0] pos,
    output w, x, y, z
);

    // Priority Encoder
    wire [7:0] in_inv;
    assign in_inv = ~in;
    wire [2:0] pos_inv;
    priority_encoder pe(
        .in(in_inv),
        .pos(pos_inv)
    );

    // Multiplexer
    wire [2:0] sel;
    mux4to1 mux(
        .a(a),
        .b(b),
        .c(c),
        .d(0),
        .sel(sel)
    );

    // Output
    always @(*) begin
        case (pos_inv)
            3'b000: begin
                w = in[sel];
                x = 0;
                y = 0;
                z = 0;
            end
            3'b001: begin
                w = 0;
                x = in[sel];
                y = 0;
                z = 0;
            end
            3'b010: begin
                w = 0;
                x = 0;
                y = in[sel];
                z = 0;
            end
            3'b011: begin
                w = 0;
                x = 0;
                y = 0;
                z = in[sel];
            end
            default: begin
                w = 0;
                x = 0;
                y = 0;
                z = 0;
            end
        endcase
    end

    // Output Position
    always @(in) begin
        if (in == 8'b00000000) begin
            pos = 3'b000;
        end else begin
            pos = pos_inv;
        end
    end

endmodule

