module non_restoring_divider (
    input signed [3:0] dividend,
    input signed [3:0] divisor,
    output reg signed [3:0] quotient,
    output reg signed [3:0] remainder
);

    reg signed [7:0] dividend_reg;
    reg signed [7:0] divisor_reg;
    reg signed [7:0] quotient_reg;
    reg signed [7:0] remainder_reg;
    reg signed [3:0] count;

    always @(*) begin
        dividend_reg = {dividend[3], dividend[3], dividend[3], dividend};
        divisor_reg = {divisor[3], divisor[3], divisor[3], divisor};
        quotient_reg = 0;
        remainder_reg = dividend_reg;
        count = 4;
    end

    always @(posedge clk) begin
        if (count > 0) begin
            if (remainder_reg[7] == 1) begin
                remainder_reg = remainder_reg - divisor_reg;
            end else begin
                remainder_reg = remainder_reg + divisor_reg;
            end
            quotient_reg = quotient_reg << 1;
            quotient_reg[0] = remainder_reg[7];
            remainder_reg = remainder_reg << 1;
            count = count - 1;
        end else begin
            quotient = quotient_reg[3:0];
            remainder = remainder_reg[3:0];
        end
    end

endmodule

