module one_shot(input clock, input in, output out);
   parameter PULSE_DURATION = 10; // in clock cycles

   reg [PULSE_DURATION-1:0] pulse;
   reg pulse_start;

   always @(posedge clock) begin
      if (in && !pulse_start) begin
         pulse_start <= 1;
         pulse <= {PULSE_DURATION{1'b1}};
      end else if (pulse_start) begin
         pulse_start <= 0;
         pulse <= {PULSE_DURATION{1'b0}};
      end
   end

   assign out = pulse[PULSE_DURATION-1];
endmodule

