module ripple_add_sub(
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] sum
);

    wire [31:0] carry;
    wire [31:0] diff;
    wire [31:0] temp;

    ripple_carry_adder adder1(
        .a(a),
        .b(b),
        .carry_in(1'b0),
        .sum(temp),
        .carry_out(carry)
    );

    full_subtractor sub1(
        .a(a),
        .b(b),
        .borrow(sub),
        .diff(diff)
    );

    ripple_carry_adder adder2(
        .a(temp),
        .b(diff),
        .carry_in(sub),
        .sum(sum),
        .carry_out()
    );

    assign b = sub ? ~b : b;

endmodule

module ripple_carry_adder(
    input [31:0] a,
    input [31:0] b,
    input carry_in,
    output [31:0] sum,
    output carry_out
);

    wire [31:0] temp;

    assign temp = a + b + carry_in;

    assign sum = temp;

    assign carry_out = temp[31];

endmodule

module full_subtractor(
    input [31:0] a,
    input [31:0] b,
    input borrow,
    output [31:0] diff
);

    wire [31:0] temp1;
    wire [31:0] temp2;

    assign temp1 = a - b;
    assign temp2 = temp1 - borrow;

    assign diff = temp2;

endmodule

