    input [3:0] sel,
    input mode,
    output reg [15:0] out
);

    wire eq;
    wire gt;
    wire lt;

    comparator_16bit cmp (
        .a(a),
        .b(b),
        .eq(eq),
        .gt(gt),
        .lt(lt)
    );

    wire [15:0] decoder_out;
    assign decoder_out = {3'b000, eq, gt, lt};

    wire [15:0] reg_in;
    assign reg_in = (mode == 0) ? a : b;

    reg [15:0] reg_out;
    always @(posedge clk) begin
        if (reset) begin
            reg_out <= 16'b0;
        end else if (decoder_out[sel] == 1'b0) begin
            reg_out <= reg_in;
        end
    end

    assign out = (decoder_out[sel] == 1'b0) ? reg_out : cmp.out;

endmodule

module flip_flops (
  input D, J, K, T, S, R, CLK,
  output Q_D, Q_JK, Q_T, Q_SR
);

// D flip-flop (positive edge-triggered)
reg Q_D;
always @(posedge CLK) begin
  Q_D <= D;
end

// JK flip-flop (negative edge-triggered)
reg Q_JK;
always @(negedge CLK) begin
  if (J && !K) begin
    Q_JK <= 1;
  end else if (!J && K) begin
    Q_JK <= 0;
  end else if (J && K) begin
    Q_JK <= ~Q_JK;
  end
end

// T flip-flop (positive edge-triggered)
reg Q_T;
always @(posedge CLK) begin
  if (T) begin
    Q_T <= ~Q_T;
  end
end

// SR flip-flop (negative edge-triggered)
reg Q_SR;
always @(negedge CLK) begin
  if (S && !R) begin
    Q_SR <= 1;
  end else if (!S && R) begin
    Q_SR <= 0;
  end else if (S && R) begin
    Q_SR <= 'bx; // undefined state
  end
end

assign Q_D = Q_D;
assign Q_JK = Q_JK;
assign Q_T = Q_T;
assign Q_SR = Q_SR;

endmodule

