module Logica_Barra(
    input clock,
    input reset,
    input actualizar_posicion,
    input revisar_bordes,
    input up_sync,
    input down_sync,
    output reg [8:0] barra_y
);

    reg [8:0] barra_posicion;

    always @(posedge clock) begin
        if (reset) begin
            barra_y <= 4'b1000_0000;
            barra_posicion <= 4'b1000;
        end else begin
            if (actualizar_posicion) begin
                if (up_sync) begin
                    barra_posicion <= barra_posicion - 1;
                end else if (down_sync) begin
                    barra_posicion <= barra_posicion + 1;
                end
            end

            if (revisar_bordes) begin
                if (barra_posicion == 0) begin
                    barra_y[8] <= 1;
                end else if (barra_posicion == 8) begin
                    barra_y[0] <= 1;
                end else begin
                    barra_y[8] <= 0;
                    barra_y[0] <= 0;
                end
            end

            barra_y[7:1] <= barra_posicion;
        end
    end

endmodule

module wb_dma_ch_rf_dummy(clk, rst,
			pointer, pointer_s, ch_csr, ch_txsz, ch_adr0, ch_adr1,
			ch_am0, ch_am1, sw_pointer, ch_stop, ch_dis, int,

			wb_rf_din, wb_rf_adr, wb_rf_we, wb_rf_re,

			// DMA Registers Write Back Channel Select
			ch_sel, ndnr,

			// DMA Engine Status
			dma_busy, dma_err, dma_done, dma_done_all,

			// DMA Engine Reg File Update ctrl signals
			de_csr, de_txsz, de_adr0, de_adr1,
			de_csr_we, de_txsz_we, de_adr0_we, de_adr1_we,
			de_fetch_descr, dma_rest,
			ptr_set

		);

parameter	CH_NO = 0;
parameter	HAVE_ARS = 1;
parameter	HAVE_ED  = 1;
parameter	HAVE_CBUF= 1;

input		clk, rst;

output	[31:0]	pointer;
output	[31:0]	pointer_s;
output	[31:0]	ch_csr;
output	[31:0]	ch_txsz;
output	[31:0]	ch_adr0;
output	[31:0]	ch_adr1;
output	[31:0]	ch_am0;
output	[31:0]	ch_am1;
output	[31:0]	sw_pointer;
output		ch_stop;
output		ch_dis;
output		int;

input	[31:0]	wb_rf_din;
input	[7:0]	wb_rf_adr;
input		wb_rf_we;
input		wb_rf_re;

input	[4:0]	ch_sel;
input		ndnr;

// DMA Engine Status
input		dma_busy, dma_err, dma_done, dma_done_all;

// DMA Engine Reg File Update ctrl signals
input	[31:0]	de_csr;
input	[11:0]	de_txsz;
input	[31:0]	de_adr0;
input	[31:0]	de_adr1;
input		de_csr_we, de_txsz_we, de_adr0_we, de_adr1_we, ptr_set;
input		de_fetch_descr;
input		dma_rest;

reg [31:0] read_pointer;
reg [31:0] write_pointer;
reg [31:0] transfer_size;
reg [31:0] source_address;
reg [31:0] destination_address;
reg [31:0] address_mode;
reg [31:0] channel_control;
reg [1:0] transfer_status;
reg [1:0] channel_status;
reg [1:0] channel_interrupt;

always @(posedge clk) begin
    if (rst) begin
        read_pointer <= 32'h0;
        write_pointer <= 32'h0;
        transfer_size <= 32'h0;
        source_address <= 32'h0;
        destination_address <= 32'h0;
        address_mode <= 32'h0;
        channel_control <= 32'h0;
        transfer_status <= 2'h0;
        channel_status <= 2'h0;
        channel_interrupt <= 2'h0;
    end else begin
        case (channel_status)
            2'h0: begin // Idle state
                if (ch_sel == CH_NO) begin
                    channel_status <= 2'h1; // Channel selected, move to setup state
                end
            end
            2'h1: begin // Setup state
                read_pointer <= ch_adr0;
                write_pointer <= ch_adr1;
                transfer_size <= ch_txsz;
                source_address <= read_pointer;
                destination_address <= write_pointer;
                address_mode <= ch_am0;
                channel_control <= ch_csr;
                transfer_status <= 2'h1; // Transfer in progress
                channel_status <= 2'h2; // Move to transfer state
            end
            2'h2: begin // Transfer state
                if (transfer_size > 0) begin
                    if (address_mode == 32'h0) begin // Linear mode
                        if (wb_rf_we) begin
                            wb_rf_din <= wb_rf_re ? {32'h0, source_address} : wb_rf_din;
                            source_address <= source_address + 4;
                            transfer_size <= transfer_size - 4;
                            wb_rf_we <= 1'b0;
                            wb_rf_re <= 1'b1;
                        end else if (wb_rf_re) begin
                            wb_rf_din <= wb_rf_din;
                            wb_rf_we <= 1'b1;
                            wb_rf_re <= 1'b0;
                        end
                        if (wb_rf_we && !wb_rf_re) begin
                            wb_rf_adr <= destination_address;
                            destination_address <= destination_address + 4;
                            wb_rf_we <= 1'b0;
                            wb_rf_re <= 1'b1;
                        end else if (wb_rf_re && !wb_rf_we) begin
                            wb_rf_adr <= wb_rf_adr;
                            wb_rf_we <= 1'b1;
                            wb_rf_re <= 1'b0;
                        end
                    end else if (address_mode == 32'h1) begin // Circular mode
                        // TODO: Implement circular mode
                    end
                end else begin
                    transfer_status <= 2'h2; // Transfer complete
                    channel_status <= 2'h3; // Move to completion state
                end
            end
            2'h3: begin // Completion state
                channel_interrupt <= 2'h1; // Interrupt
                channel_status <= 2'h0; // Move to idle state
            end
        endcase
    end
end

assign		pointer = read_pointer;
assign		pointer_s = write_pointer;
assign		ch_csr = channel_control;
assign		ch_txsz = transfer_size;
assign		ch_adr0 = read_pointer;
assign		ch_adr1 = write_pointer;
assign		ch_am0 = address_mode;
assign		ch_am1 = address_mode;
assign		sw_pointer = read_pointer;
assign		ch_stop = 1'b0;
assign		ch_dis = 1'b0;
assign		int = channel_interrupt;

endmodule

