module mux_and (
    input [2:0] sel, // Select input for 6-to-1 multiplexer
    input [3:0] data0, // 4-bit data inputs for 6-to-1 multiplexer
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output reg [3:0] out // 4-bit output from mux_and module
);

    always @(*) begin
        case (sel)
            3'b000: out = data0;
            3'b001: out = data1;
            3'b010: out = data2;
            3'b011: out = data3;
            3'b100: out = data4;
            3'b101: out = data5;
            default: out = sel & out;
        endcase
    end

endmodule

