module rotator(
    input clk,
    input reset,
    input load,
    input [1:0] ena,
    input [99:0] data,
    output [99:0] rotated_data
);

reg [99:0] shifted_data;

always @(posedge clk, posedge reset) begin
    if (reset) begin
        shifted_data <= 100'b0;
    end else if (load) begin
        shifted_data <= data;
    end else begin
        case (ena)
            2'b00: shifted_data <= data;
            2'b01: shifted_data <= {data[0], data[99:1]};
            2'b10: shifted_data <= {data[98:0], data[99]};
            2'b11: shifted_data <= {data[1:0], data[99:2]};
        endcase
    end
end

assign rotated_data = shifted_data;

endmodule

