module top_string (
	input clk,
	input btn1,
	input new,
	input [6:0] char,
	output reg [76:0] string,
	output reg complete,
	output reg change
);

	// Internal signals
	reg [76:0] string_reg;
	reg [6:0] char_reg;
	reg [7:0] counter;

	// Reset logic
	always @ (posedge clk) begin
		if (btn1) begin
			string_reg <= 77'b0;
			counter <= 0;
			complete <= 0;
			change <= 0;
		end
	end

	// Character addition logic
	always @ (posedge clk) begin
		if (new) begin
			if (counter < 77) begin
				string_reg[counter] <= char;
				counter <= counter + 1;
				change <= 1;
			end
			if (counter == 77) begin
				complete <= 1;
			end
		end
	end

	// Output logic
	always @ (posedge clk) begin
		string <= string_reg;
		char_reg <= char;
	end

	// Change detection logic
	always @ (posedge clk) begin
		if (string_reg != string) begin
			change <= 1;
		end else begin
			change <= 0;
		end
	end

endmodule

