    Q_next = Q_reg;
    if (LOAD) begin
        Q_next = D;
    end else if (SHL) begin
        Q_next = {Q_reg[2:0], 1'b0};
    end else if (SHR) begin
        Q_next = {1'b0, Q_reg[3:1]};
    end
end

always @(posedge clk) begin
    Q_reg <= Q_next;
end

assign Q = Q_reg;

endmodule

module scfifo_24in_24out_12kb_fifo_generator_top
   (empty,
    full,
    data_count,
    dout,
    clk,
    din,
    rst,
    rd_en,
    wr_en);
  output empty;
  output full;
  output [0:0]data_count;
  output [23:0]dout;
  input clk;
  input [23:0]din;
  input rst;
  input rd_en;
  input wr_en;

  wire [23:0] fifo_mem [511:0]; // 12kb / 24 bits = 512 memory locations
  wire [8:0] wr_ptr; // 9 bits to point to 512 memory locations
  wire [8:0] rd_ptr; // 9 bits to point to 512 memory locations
  wire [8:0] data_count_wire; // 9 bits to count up to 512 memory locations
  wire empty;
  wire full;
  wire rd_en_internal;
  wire wr_en_internal;
  wire [23:0] dout_internal;

  assign empty = (data_count_wire == 0);
  assign full = (data_count_wire == 512);
  assign data_count = data_count_wire;

  // read pointer logic
  always @(posedge clk) begin
    if (rst) begin
      rd_ptr <= 0;
    end else if (rd_en_internal) begin
      rd_ptr <= rd_ptr + 1;
    end
  end

  // write pointer logic
  always @(posedge clk) begin
    if (rst) begin
      wr_ptr <= 0;
    end else if (wr_en_internal) begin
      wr_ptr <= wr_ptr + 1;
    end
  end

  // data count logic
  always @(posedge clk) begin
    if (rst) begin
      data_count_wire <= 0;
    end else if (rd_en_internal && !empty) begin
      data_count_wire <= data_count_wire - 1;
    end else if (wr_en_internal && !full) begin
      data_count_wire <= data_count_wire + 1;
    end
  end

  // read enable logic
  assign rd_en_internal = (rd_en && !empty);

  // write enable logic
  assign wr_en_internal = (wr_en && !full);

  // data output logic
  assign dout_internal = fifo_mem[rd_ptr];

  // FIFO memory write logic
  always @(posedge clk) begin
    if (rst) begin
      fifo_mem <= 0;
    end else if (wr_en_internal) begin
      fifo_mem[wr_ptr] <= din;
    end
  end

  assign dout = dout_internal;
  assign empty = (data_count_wire == 0);
  assign full = (data_count_wire == 512);
endmodule

