module gray_code_counter (
    input clk,
    input reset,
    output reg [2:0] gray_code,
    output reg [2:0] rgb_led
);

// Instantiate binary-to-Gray module
binary_to_gray b2g (
    .binary(gray_code),
    .gray(gray_code)
);

// Instantiate shift register module
shift_register sr (
    .clk(clk),
    .reset(reset),
    .in(gray_code[2]),
    .out(shifted_bit)
);

// Instantiate functional module to generate next Gray code value
generate_gray_code ggc (
    .current_gray(gray_code),
    .shifted_bit(shifted_bit),
    .next_gray(next_gray)
);

// Assign next Gray code value to output
always @ (posedge clk) begin
    if (reset) begin
        gray_code <= 3'b000;
    end else begin
        gray_code <= next_gray;
    end
end

// Control RGB LED based on Gray code value
always @ (gray_code) begin
    case (gray_code)
        3'b000: rgb_led <= 3'b100; // Red
        3'b001: rgb_led <= 3'b010; // Green
        3'b011: rgb_led <= 3'b001; // Blue
        3'b010: rgb_led <= 3'b110; // Yellow
        3'b110: rgb_led <= 3'b011; // Cyan
        3'b111: rgb_led <= 3'b101; // Magenta
        3'b101: rgb_led <= 3'b111; // White
        default: rgb_led <= 3'b000; // Off
    endcase
end

reg shifted_bit;
reg [2:0] next_gray;

endmodule

// Binary-to-Gray module
module binary_to_gray (
    input [2:0] binary,
    output reg [2:0] gray
);

always @ (binary) begin
    gray[2] = binary[2];
    gray[1] = binary[2] ^ binary[1];
    gray[0] = binary[1] ^ binary[0];
end

endmodule

// Shift register module
module shift_register (
    input clk,
    input reset,
    input in,
    output reg out
);

reg [2:0] register;

always @ (posedge clk) begin
    if (reset) begin
        register <= 3'b000;
    end else begin
        register <= {register[1:0], in};
    end
end

assign out = register[2];

