// Functional module to generate next Gray code value
module generate_gray_code (
    input [2:0] current_gray,
    input shifted_bit,
    output reg [2:0] next_gray
);

always @ (current_gray, shifted_bit) begin
    case (current_gray)
        3'b000: next_gray = {shifted_bit, 3'b001}; // 0 -> 1
        3'b001: next_gray = {shifted_bit, 3'b011}; // 1 -> 2
        3'b011: next_gray = {shifted_bit, 3'b010}; // 2 -> 3
        3'b010: next_gray = {shifted_bit, 3'b110}; // 3 -> 5
        3'b110: next_gray = {shifted_bit, 3'b111}; // 5 -> 6
        3'b111: next_gray = {shifted_bit, 3'b101}; // 6 -> 4
        3'b101: next_gray = {shifted_bit, 3'b100}; // 4 -> 0
        default: next_gray = 3'b000; // Reset value
    endcase
end

endmodule

module t_ff_pipeline (
    input clk,
