module spi_dma_interface
(
    // General
    clk_i,
    rst_i,
    // SPI Interface
    spi_clk_o,
    spi_ss_o,
    spi_mosi_o,
    spi_miso_i,
    // Memory interface
    mem_address_o,
    mem_data_o,
    mem_data_i,
    mem_rd_o,
    mem_wr_o,
    // Control
    xfer_count_i,
    xfer_address_i,
    xfer_start_i,
    xfer_rx_only_i,
    xfer_done_o,
    xfer_busy_o
);

//-----------------------------------------------------------------
// Params
//-----------------------------------------------------------------
parameter                       MEM_ADDR_WIDTH      = 18;
parameter                       XFER_COUNT_WIDTH    = 32;
parameter                       SPI_CLK_DIV         = 4;
parameter                       TRANSFER_WIDTH      = 8;

//-----------------------------------------------------------------
// I/O
//----------------------------------------------------------------- 
// General
input                           clk_i /*verilator public*/;
input                           rst_i /*verilator public*/;
// SPI Interface
output                          spi_clk_o /*verilator public*/;
output                          spi_ss_o /*verilator public*/;
output                          spi_mosi_o /*verilator public*/;
input                           spi_miso_i /*verilator public*/;
// Memory interface
output[MEM_ADDR_WIDTH - 1:0]    mem_address_o /*verilator public*/;
output[TRANSFER_WIDTH - 1:0]    mem_data_o /*verilator public*/;
input[TRANSFER_WIDTH - 1:0]     mem_data_i /*verilator public*/;
output                          mem_rd_o /*verilator public*/;
output                          mem_wr_o /*verilator public*/;
// Control
input[XFER_COUNT_WIDTH - 1:0]   xfer_count_i /*verilator public*/;
input[MEM_ADDR_WIDTH - 1:0]     xfer_address_i /*verilator public*/;
input                           xfer_start_i /*verilator public*/;
input                           xfer_rx_only_i /*verilator public*/;
output                          xfer_done_o /*verilator public*/;
output                          xfer_busy_o /*verilator public*/;

//-----------------------------------------------------------------
// Registers
//-----------------------------------------------------------------
reg [MEM_ADDR_WIDTH - 1:0]      mem_address;
reg [TRANSFER_WIDTH - 1:0]      mem_data;
reg [XFER_COUNT_WIDTH - 1:0]    xfer_count;
reg                             xfer_start;
reg                             xfer_rx_only;
reg                             xfer_done;
reg                             xfer_busy;

//-----------------------------------------------------------------
// Wires
//-----------------------------------------------------------------
wire                            spi_clk;
wire                            spi_ss;
wire [TRANSFER_WIDTH - 1:0]     spi_mosi;
wire [TRANSFER_WIDTH - 1:0]     spi_miso;

//-----------------------------------------------------------------
// Instantiation
//----------------------------------------------------------------- 

// SPI Master
spi_master 
#(
    .CLK_DIV(SPI_CLK_DIV),
    .TRANSFER_WIDTH(TRANSFER_WIDTH)
)
U1_SPIM
(
    // Clocking / Reset
    .clk_i(clk_i),
    .rst_i(rst_i),

    // Control & Status
    .start_i(xfer_start),
    .done_o(xfer_done),
    .busy_o(xfer_busy),

    // Data
    .data_i(spi_mosi),
    .data_o(spi_miso),

    // SPI interface
    .spi_clk_o(spi_clk),
    .spi_ss_o(spi_ss),
    .spi_mosi_o(spi_mosi),
    .spi_miso_i(spi_miso_i)
);

// DMA controller
spi_ctrl 
#(
    .MEM_ADDR_WIDTH(MEM_ADDR_WIDTH),
    .XFER_COUNT_WIDTH(XFER_COUNT_WIDTH),
    .TRANSFER_WIDTH(TRANSFER_WIDTH)
)
U2_SPI_DMA
(
    // General
    .clk_i(clk_i),
    .rst_i(rst_i),

    // Memory interface
    .mem_address_o(mem_address_o),
    .mem_data_o(mem_data_o),
    .mem_data_i(mem_data_i),
    .mem_rd_o(mem_rd_o),
    .mem_wr_o(mem_wr_o),

    // SPI Access
    .spi_start_o(xfer_start),
    .spi_done_i(xfer_done),
    .spi_busy_i(xfer_busy),
    .spi_data_i(spi_miso),
    .spi_data_o(spi_mosi),

    // Control
    .xfer_count_i(xfer_count),
    .xfer_address_i(mem_address),
    .xfer_start_i(xfer_start),
    .xfer_rx_only_i(xfer_rx_only),
    .xfer_done_o(xfer_done_o),
    .xfer_busy_o(xfer_busy_o)
);

//-----------------------------------------------------------------
// Control
//-----------------------------------------------------------------
always @(posedge clk_i or posedge rst_i) begin
    if (rst_i) begin
        mem_address <= 0;
        mem_data <= 0;
        xfer_count <= 0;
        xfer_start <= 0;
        xfer_rx_only <= 0;
        xfer_done <= 0;
        xfer_busy <= 0;
    end else begin
        if (xfer_start_i && !xfer_busy) begin
            mem_address <= xfer_address_i;
            xfer_count <= xfer_count_i;
            xfer_start <= 1;
            xfer_rx_only <= xfer_rx_only_i;
            xfer_done <= 0;
            xfer_busy <= 1;
        end else if (xfer_start && !xfer_done) begin
            if (xfer_rx_only) begin
                mem_rd_o <= 0;
                mem_address <= mem_address + 1;
                spi_ss <= 0;
                spi_mosi <= 0;
            end else begin
                mem_rd_o <= 1;
                mem_address <= mem_address + 1;
                mem_data <= mem_data_i;
                spi_ss <= 0;
                spi_mosi <= mem_data;
            end
        end else if (xfer_start && xfer_done) begin
            if (xfer_rx_only) begin
                mem_rd_o <= 0;
                spi_ss <= 1;
            end else begin
                mem_rd_o <= 0;
                spi_ss <= 1;
            end
            xfer_start <= 0;
            xfer_rx_only <= 0;
            xfer_done <= 0;
            xfer_busy <= 0;
        end else begin
            mem_rd_o <= 0;
            spi_ss <= 1;
        end
    end
end

//-----------------------------------------------------------------
// Output
//-----------------------------------------------------------------
assign spi_clk_o = spi_clk;
assign spi_ss_o = spi_ss;
assign mem_data_o = mem_data;
assign mem_address_o = mem_address;

endmodule

