  always @(posedge clk or posedge rst) begin
    if (rst) begin
      count <= 0;
      wdout <= 0;
    end else begin
      count <= count + 1;
      if (count >= timeout) begin
        wdout <= 1;
      end else begin
        wdout <= 0;
      end
    end
  end

