module axi_accelerator (
    input sys_clk, sys_nreset,
    input m_wr_access, m_rd_access, m_rr_access,
    input [PW-1:0] m_wr_packet, m_rd_packet,
    input m_wr_wait, m_rd_wait, m_rr_wait,
    input s_wr_access, s_rd_access, s_rr_access,
    input [PW-1:0] s_wr_packet, s_rd_packet,
    input s_wr_wait, s_rd_wait, s_rr_wait,
    output reg m_wr_wait, m_rd_wait, m_rr_access,
    output reg [PW-1:0] m_wr_packet, m_rd_packet,
    output reg m_rr_wait, s_wr_wait, s_rd_wait,
    output reg [PW-1:0] s_wr_packet, s_rd_packet,
    output reg s_rr_access
);

// Internal signals
reg [PW-1:0] m_wr_packet_reg; // Register for storing master write data
reg [PW-1:0] s_wr_packet_reg; // Register for storing slave write data
reg [PW-1:0] m_rd_packet_reg; // Register for storing master read data
reg [PW-1:0] s_rd_packet_reg; // Register for storing slave read data

// Master write operation
always @(posedge sys_clk) begin
    if (sys_nreset == 1'b0) begin
        m_wr_wait <= 1'b0;
    end else begin
        if (m_wr_access == 1'b1 && m_wr_wait == 1'b1) begin
            m_wr_wait <= 1'b0;
            m_wr_packet <= m_wr_packet_reg;
        end else if (m_wr_access == 1'b1 && m_wr_wait == 1'b0) begin
            m_wr_wait <= 1'b1;
            m_wr_packet_reg <= m_wr_packet;
        end
    end
end

// Master read operation
always @(posedge sys_clk) begin
    if (sys_nreset == 1'b0) begin
        m_rd_wait <= 1'b0;
        m_rd_packet <= 0;
    end else begin
        if (m_rd_access == 1'b1 && m_rd_wait == 1'b1) begin
            m_rd_wait <= 1'b0;
        end else if (m_rd_access == 1'b1 && m_rd_wait == 1'b0) begin
            m_rd_wait <= 1'b1;
            m_rd_packet_reg <= m_rd_packet;
        end else if (m_rd_access == 1'b0 && m_rd_wait == 1'b1) begin
            m_rd_wait <= 1'b0;
            m_rd_packet <= m_rd_packet_reg;
        end
    end
end

// Master read request operation
always @(posedge sys_clk) begin
    if (sys_nreset == 1'b0) begin
        m_rr_access <= 1'b0;
        m_rr_wait <= 1'b0;
    end else begin
        if (m_rr_access == 1'b1 && m_rr_wait == 1'b1) begin
            m_rr_wait <= 1'b0;
            s_rr_access <= 1'b1;
        end else if (m_rr_access == 1'b1 && m_rr_wait == 1'b0) begin
            m_rr_wait <= 1'b1;
            s_rr_access <= 1'b0;
        end else if (m_rr_access == 1'b0 && m_rr_wait == 1'b1) begin
            m_rr_wait <= 1'b0;
        end
    end
end

// Slave write operation
always @(posedge sys_clk) begin
    if (sys_nreset == 1'b0) begin
        s_wr_wait <= 1'b0;
    end else begin
        if (s_wr_access == 1'b1 && s_wr_wait == 1'b1) begin
            s_wr_wait <= 1'b0;
            s_wr_packet <= s_wr_packet_reg;
        end else if (s_wr_access == 1'b1 && s_wr_wait == 1'b0) begin
            s_wr_wait <= 1'b1;
            s_wr_packet_reg <= s_wr_packet;
        end
    end
end

// Slave read operation
always @(posedge sys_clk) begin
    if (sys_nreset == 1'b0) begin
        s_rd_wait <= 1'b0;
        s_rd_packet <= 0;
    end else begin
        if (s_rd_access == 1'b1 && s_rd_wait == 1'b1) begin
            s_rd_wait <= 1'b0;
        end else if (s_rd_access == 1'b1 && s_rd_wait == 1'b0) begin
            s_rd_wait <= 1'b1;
            s_rd_packet_reg <= s_rd_packet;
        end else if (s_rd_access == 1'b0 && s_rd_wait == 1'b1) begin
            s_rd_wait <= 1'b0;
            s_rd_packet <= s_rd_packet_reg;
        end
    end
end

endmodule

module binary_to_bcd_converter (
