module Transmision (input rw, //rw=1 para transmitir
                    input clk,
                    input reset, //reset=0 para transmitir
                    input wire [7:0] din,   
                    output busy, 
                    output reg done,
                    output clk_blu, 
                    output reg tx
                   );

wire clk_f;
Divisor_frecuencia div(.clk(clk), .clk_f(clk_f), .reset(reset));

parameter count = 8;

assign clk_blu = clk_f;

initial begin
    tx <= 1'b1;
    done=0;
end

reg [7:0] dato = 8'b11111111;
reg [2:0] bitcount = 0;

parameter ESTADO_INACTIVO = 2'b00;
parameter ESTADO_INICIO	  = 2'b01;
parameter ESTADO_DATO	  = 2'b10;
parameter ESTADO_FINAL	  = 2'b11;
reg [1:0] estado = ESTADO_INACTIVO;

always @(posedge clk_f) begin 
    if (reset) begin
        tx <= 1'b1;
        estado <= ESTADO_INACTIVO;
    end
    else begin
        case (estado)
            ESTADO_INACTIVO: begin
                if(rw) begin
                    estado <= ESTADO_INICIO;
                    dato <= din;
                    bitcount <= 0;
                    done <= 0;
                    tx <= 0;
                end
            end
            ESTADO_INICIO: begin
                tx <= 0;
                estado <= ESTADO_DATO;
            end
            ESTADO_DATO: begin
                tx <= dato[bitcount];
                bitcount <= bitcount + 1;
                if (bitcount == count) begin
                    estado <= ESTADO_FINAL;
                    bitcount <= 0;
                end
            end
            ESTADO_FINAL: begin
                tx <= 1'b1;
                estado <= ESTADO_INACTIVO;
                done <= 1;
            end
            default: begin
                tx <= 1'b1;
                estado <= ESTADO_INACTIVO;
            end
        endcase
    end
end

assign busy = (estado != ESTADO_INACTIVO);

endmodule

module top_module (
    input clk,
    input reset,
    input [15:0] in0,
    input [15:0] in1,
    input select,
    input control,
    output reg [15:0] out
);

    reg [15:0] counter_out;
    reg [15:0] adder_out;
    reg [15:0] sum_out;

    up_down_counter counter(clk, reset, in0, select, counter_out);
    add_subtractor adder(clk, reset, in0, in1, control, adder_out);

    always @ (counter_out or adder_out) begin
        sum_out = counter_out + adder_out;
    end

    always @ (posedge clk) begin
        if (reset) begin
            out <= 0;
        end else begin
            if (select) begin
                out <= adder_out;
            end else begin
                out <= counter_out;
            end
        end
    end

endmodule

module up_down_counter (
    input clk,
    input reset,
    input [15:0] in,
    input select,
    output reg [15:0] out
);

    always @ (posedge clk) begin
        if (reset) begin
            out <= 0;
        end else begin
            if (select) begin
                out <= out + 1;
            end else begin
                out <= out - 1;
            end
        end
    end

endmodule

module add_subtractor (
    input clk,
    input reset,
    input [15:0] in0,
    input [15:0] in1,
    input control,
    output reg [15:0] out
);

    always @ (posedge clk) begin
        if (reset) begin
            out <= 0;
        end else begin
            if (control) begin
                out <= in0 + in1;
            end else begin
                out <= in0 - in1;
            end
        end
    end

endmodule

module t_ff_asr (T, S, R, CLK, Q, QN);
  input T, S, R, CLK;
  output Q, QN;
  reg Q, QN;

  always @(posedge CLK) begin
    if (S) begin
      Q <= 1;
      QN <= 0;
    end else if (R) begin
      Q <= 0;
      QN <= 1;
    end else if (T) begin
      Q <= ~Q;
      QN <= ~QN;
    end
  end
endmodule

module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out
);

    reg [9:0] accumulator;
    reg [3:0] counter;
    reg [7:0] register_data;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            accumulator <= 10'd0;
            counter <= 4'd0;
            register_data <= 8'h34;
            valid_b <= 1'b0;
        end else begin
            if (valid_a && ready_b) begin
                register_data <= data_in;
                counter <= counter + 1;
                if (counter == 4'd7) begin
                    accumulator <= accumulator + register_data;
                    counter <= 4'd0;
                    valid_b <= 1'b1;
                end else begin
                    valid_b <= 1'b0;
                end
            end
        end
    end

    assign ready_a = ~valid_b;

    assign data_out = {accumulator, 2'd0};

endmodule
module top_module (
    input clk,
    input reset,
    input [3:1] ena,
    output [15:0] q
);

    wire [9:0] accu_out;
    wire accu_ready;

    accu accu_inst (
        .clk(clk),
        .rst_n(reset),
        .data_in(q[7:0]),
        .valid_a(q[8]),
        .ready_b(accu_ready),
        .ready_a(q[9]),
        .valid_b(),
        .data_out(accu_out)
    );

    reg [3:0] bcd_counter;
    reg [15:0] output_reg;
    reg [3:1] enable_reg;

    always @(posedge clk or negedge reset) begin
        if (!reset) begin
            bcd_counter <= 4'd0;
            output_reg <= 16'd0;
            enable_reg <= 3'd0;
        end else begin
            if (accu_ready) begin
                bcd_counter <= bcd_counter + 1;
                if (bcd_counter == 4'd9) begin
                    bcd_counter <= 4'd0;
                    enable_reg <= enable_reg + 1;
                    if (enable_reg == ena) begin
                        output_reg <= accu_out;
                    end
                end
            end
        end
    end

    assign q = output_reg;

endmodule

module oddr #
(
    // target ("SIM", "GENERIC", "XILINX", "ALTERA")
    parameter TARGET = "GENERIC",
    // IODDR style ("IODDR", "IODDR2")
    // Use IODDR for Virtex-4, Virtex-5, Virtex-6, 7 Series, Ultrascale
    // Use IODDR2 for Spartan-6
    parameter IODDR_STYLE = "IODDR2",
    // Width of register in bits
    parameter WIDTH = 1
)
(
    input  wire             clk,

    input  wire [WIDTH-1:0] d1,
    input  wire [WIDTH-1:0] d2,

    output wire [WIDTH-1:0] q
);

genvar n;

generate

if (TARGET == "XILINX") begin
    for (n = 0; n < WIDTH; n = n + 1) begin : oddr
        if (IODDR_STYLE == "IODDR") begin
            ODDR #(
                .DDR_CLK_EDGE("SAME_EDGE"),
                .SRTYPE("ASYNC")
            )
            oddr_inst (
                .Q(q[n]),
                .C(clk),
                .CE(1'b1),
                .D1(d1[n]),
                .D2(d2[n]),
                .R(1'b0),
                .S(1'b0)
            );
        end else if (IODDR_STYLE == "IODDR2") begin
            ODDR2 #(
                .DDR_ALIGNMENT("C0"),
                .SRTYPE("ASYNC")
            )
            oddr_inst (
                .Q(q[n]),
                .C0(clk),
                .C1(~clk),
                .CE(1'b1),
                .D0(d1[n]),
                .D1(d2[n]),
                .R(1'b0),
                .S(1'b0)
            );
        end
    end
end else if (TARGET == "ALTERA") begin
    altddio_out #(
        .WIDTH(WIDTH),
        .POWER_UP_HIGH("OFF"),
        .OE_REG("UNUSED")
    )
    altddio_out_inst (
        .aset(1'b0),
        .datain_h(d1),
        .datain_l(d2),
        .outclocken(1'b1),
        .outclock(clk),
        .aclr(1'b0),
        .dataout(q)
    );
end else begin
    reg [WIDTH-1:0] d_reg_1 = {WIDTH{1'b0}};
    reg [WIDTH-1:0] d_reg_2 = {WIDTH{1'b0}};

    reg [WIDTH-1:0] q_reg = {WIDTH{1'b0}};

    always @(posedge clk) begin
        d_reg_1 <= d1;
        d_reg_2 <= d2;
    end

    always @(posedge clk) begin
        q_reg <= d1;
    end

    always @(negedge clk) begin
        q_reg <= d_reg_2;
    end

    assign q = q_reg;
end

endgenerate

endmodule

module top_module(
    input wire clk,
    input wire rst_n,
    input wire [31:0] in,
    output wire [31:0] filtered_out
);

    // Instantiate modules
    edge_detection edge_detector(.clk(clk), .rst_n(rst_n), .in(in));
    barrel_shifter barrel_shifter(.clk(clk), .rst_n(rst_n), .in(in), .shift_amt(31'h7));
    lowpass_filter filter(.clk(clk), .rst_n(rst_n), .in(edge_detector.out), .out(filtered_out));

endmodule

module edge_detection(
    input wire clk,
    input wire rst_n,
    input wire [31:0] in,
    output wire out
);

    wire [31:0] prev_in;
    reg out_reg;

    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            prev_in <= 0;
            out_reg <= 0;
        end else begin
            prev_in <= in;
            if(in > prev_in) begin
                out_reg <= 1;
            end else begin
                out_reg <= 0;
            end
        end
    end

    assign out = out_reg;

endmodule

module barrel_shifter(
    input wire clk,
    input wire rst_n,
    input wire [31:0] in,
    input wire [31:0] shift_amt,
    output wire [31:0] out
);

    reg [31:0] shift_reg;

    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            shift_reg <= 0;
        end else begin
            shift_reg <= {in, 2'b00} >> shift_amt;
        end
    end

    assign out = shift_reg;

endmodule

module lowpass_filter(
    input wire clk,
    input wire rst_n,
    input wire [31:0] in,
    output wire [31:0] out
);

    reg [9:0] window [0:9];
    reg [31:0] sum;
    reg [31:0] avg;

    integer i;

    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            for(i = 0; i < 10; i = i + 1) begin
                window[i] <= 0;
            end
            sum <= 0;
            avg <= 0;
        end else begin
            sum <= sum - window[0] + in;
            for(i = 0; i < 9; i = i + 1) begin
                window[i] <= window[i+1];
            end
            window[9] <= in;
            avg <= sum / 10;
        end
    end

    assign out = avg;

endmodule

module counter_rollover
#(parameter       W = 256, // width of counter
  parameter       N = 4)   // how many parts contain counter?
 (input  wire         CLK,
  input  wire         ENABLE,
  input  wire         LOAD,
  input  wire [W-1:0] DI,
  output wire [W-1:0] DO
  );

reg [(W/N)-1:0] cnt [N-1:0];

wire [N-1:0] tc; // TerminalCount
wire [N-1:0] ro; // RollOver


genvar k;
generate
  for (k=0;k<N;k=k+1) begin: gen_counter

    assign tc[k] = (k==0) ? 1'b1 : (tc[k-1] && (& cnt[k-1]));
    assign ro[k] = tc[k] & ENABLE;

    always @(posedge CLK) begin
      if (LOAD)
        cnt[k] <= DI[W/N*(k+1)-1:W/N*k];
      else if (ro[k])
        cnt[k] <= cnt[k] + 1;
    end

    assign DO[W/N*(k+1)-1:W/N*k] = cnt[k];

  end
endgenerate

endmodule

