module top(
    input USER_CLOCK,
    output [3:0] z
    );

    wire clk;
    clockdrv clockdrv(
        .CLK_IN1(USER_CLOCK),
        .CLK_OUT1(clk)
    );

    reg [41:0] state;
    assign z = state[27:24];

    wire [3:0] L;
    wire [3:0] U;
    wire [3:0] Y;
    wire [3:0] Z;

    wire [3:0] Lp;
    wire [3:0] Up;
    wire [3:0] Yp;
    wire [3:0] Zp;

    wire [1:0] select_ms;

    unit unit(
        .select_ms(select_ms),
        .L(L),
        .U(U),
        .Y(Y),
        .Z(Z),
        .Lp(Lp),
        .Up(Up),
        .Yp(Yp),
        .Zp(Zp)
    );

    icon2 icon2(
        .CONTROL0(CONTROL0),
        .CONTROL1(CONTROL1)
    );

    vio vio0(
        .CONTROL(CONTROL0),
        .ASYNC_IN(combout0),
        .ASYNC_OUT(combin0)
    );

    vio vio1(
        .CONTROL(CONTROL1),
        .ASYNC_IN(combout1),
        .ASYNC_OUT(combin1)
    );

    always @(posedge clk) begin
        state <= state + 1;
    end

    assign {select_ms, L, U, Y, Z} = state[41:37];

    assign combout0 = {16'b0, Lp, Up, Yp, Zp};
    assign combout1 = 32'b0;

    assign {Lp, Up, Yp, Zp} = select_ms == 2'b00 ? {L > U ? L : U, Y < Z ? Y : Z, L < U ? L : U, Y > Z ? Y : Z} :
                              select_ms == 2'b01 ? {L < U ? L : U, Y > Z ? Y : Z, L > U ? L : U, Y < Z ? Y : Z} :
                              select_ms == 2'b10 ? {L & U, Y | Z, L ^ U, Y ^ Z} :
                                                   4'b0;

    wire [35:0] CONTROL0;
    wire [35:0] CONTROL1;

    wire [31:0] combout0;
    wire [31:0] combout1;

    wire [31:0] combin0;
    wire [31:0] combin1;

endmodule

