reg [3:0] stage;

always @(posedge clk) begin
    case (stage)
        0: shift_reg <= in;
        1: shift_reg <= shift_reg >> 1;
        2: shift_reg <= shift_reg >> 1;
        3: shift_reg <= shift_reg >> 1;
        4: shift_reg <= shift_reg >> 1;
        5: shift_reg <= shift_reg >> 1;
        6: shift_reg <= shift_reg >> 1;
        7: shift_reg <= shift_reg >> 1;
        8: shift_reg <= shift_reg >> 8;
    endcase
    stage <= stage + 1;
end

assign out_hi = shift_reg[15:8];
assign out_lo = shift_reg[7:0];

endmodule

