module MyModule(
  input         clock,
  input         reset,
  input  [14:0] io_a,
  input  [14:0] io_b,
  input  [13:0] io_c,
  output [15:0] io_x,
  output [15:0] io_y,
  output [15:0] io_z,
  inout  [2:0]  io_analog1,
  inout  [2:0]  io_analog2,
  output [4:0]  io_v_0,
  output [4:0]  io_v_1,
  output [4:0]  io_v_2
);
  reg [15:0] MyModule_Internal_io_x;
  reg [15:0] MyModule_Internal_io_y;
  reg [15:0] MyModule_Internal_io_z;
  reg [4:0] MyModule_Internal_io_v_0;
  reg [4:0] MyModule_Internal_io_v_1;
  reg [4:0] MyModule_Internal_io_v_2;
  wire [14:0] mult_ab;
  wire [13:0] sub_c;

  // Reset outputs to 0 on rising edge of clock if reset signal is high
  always @(posedge clock) begin
    if (reset) begin
      MyModule_Internal_io_x <= 16'b0;
      MyModule_Internal_io_y <= 16'b0;
      MyModule_Internal_io_z <= 16'b0;
      MyModule_Internal_io_v_0 <= 5'b0;
      MyModule_Internal_io_v_1 <= 5'b0;
      MyModule_Internal_io_v_2 <= 5'b0;
    end
  end

  // Assign outputs to internal signals on falling edge of clock
  always @(negedge clock) begin
    io_x <= MyModule_Internal_io_x;
    io_y <= MyModule_Internal_io_y;
    io_z <= MyModule_Internal_io_z;
    io_v_0 <= MyModule_Internal_io_v_0;
    io_v_1 <= MyModule_Internal_io_v_1;
    io_v_2 <= MyModule_Internal_io_v_2;
  end

  // Perform operations on inputs and internal signals
  assign mult_ab = io_a * io_b;
  assign sub_c = mult_ab - io_c;
  always @(*) begin
    if (sub_c < 0) begin
      MyModule_Internal_io_v_0 = 5'b0;
      MyModule_Internal_io_v_1 = 5'b0;
      MyModule_Internal_io_v_2 = 5'b0;
    end else begin
      MyModule_Internal_io_v_0 = sub_c[4:0];
      MyModule_Internal_io_v_1 = sub_c[9:5];
      MyModule_Internal_io_v_2 = sub_c[13:10];
    end
    MyModule_Internal_io_x = io_a;
    MyModule_Internal_io_y = io_b;
    MyModule_Internal_io_z = sub_c;
  end

  // Perform operations on bidirectional inputs
  always @(*) begin
    if (io_analog1 >= io_analog2) begin
      io_analog2 = io_analog1;
    end
    if (io_analog2 >= io_analog1) begin
      io_analog1 = io_analog2;
    end
  end
endmodule

