module adder_4bit(A, B, Cin, S, Cout);
    input [3:0] A, B;
    input Cin;
    output [3:0] S;
    output Cout;

    wire c1, c2, c3;

    // 1-bit adders
    xor2 x1(S[0], A[0], B[0]);
    xor2 x2(S[1], A[1], B[1]);
    xor2 x3(S[2], A[2], B[2]);
    xor2 x4(S[3], A[3], B[3]);

    assign c1 = (A[0] & B[0]) | (Cin & (A[0] ^ B[0]));
    assign c2 = (A[1] & B[1]) | (S[0] & (A[1] ^ B[1]));
    assign c3 = (A[2] & B[2]) | (S[1] & (A[2] ^ B[2]));
    assign Cout = (A[3] & B[3]) | (S[2] & (A[3] ^ B[3]));

    // Carry-in
    and a1(Cin, A[0], B[0]);
    and a2(c1, A[1], B[1]);
    and a3(c2, A[2], B[2]);
    and a4(c3, A[3], B[3]);

    // Carry-out
    or o1(Cout, c1, c2);
    or o2(Cout, Cout, c3);
endmodule

module axi_stream_counter #(
