);

localparam WORDS_PER_PACKET = DATA_WIDTH/8;
localparam COUNTER_WIDTH = $clog2(WORDS_PER_PACKET+1);

reg [COUNTER_WIDTH-1:0] count;
reg [COUNTER_WIDTH-1:0] next_count;
reg [DATA_WIDTH-1:0] total_count;
reg [DATA_WIDTH-1:0] next_total_count;
reg [TAG_WIDTH-1:0] current_tag;
reg [TAG_WIDTH-1:0] next_tag;
reg counting;

always @(posedge clk) begin
    if (rst) begin
        count <= 0;
        total_count <= 0;
        current_tag <= 0;
        counting <= 0;
        busy <= 0;
    end else begin
        if (monitor_axis_tvalid && monitor_axis_tready) begin
            if (monitor_axis_tlast) begin
                // end of packet
                if (current_tag == tag && counting) begin
                    total_count <= next_total_count;
                end
                current_tag <= next_tag;
                counting <= 0;
                count <= 0;
                output_axis_tlast <= 1;
                output_axis_tvalid <= 1;
                output_axis_tdata <= total_count;
                output_axis_tuser <= monitor_axis_tuser;
                busy <= 0;
            end else begin
                // data word
                if (current_tag == tag && counting) begin
                    next_count <= count + 1;
                    next_total_count <= total_count + monitor_axis_tkeep;
                end else begin
                    next_count <= count;
                    next_total_count <= total_count;
                end
                output_axis_tlast <= 0;
                output_axis_tvalid <= 0;
                output_axis_tdata <= monitor_axis_tdata;
                output_axis_tuser <= monitor_axis_tuser;
                busy <= 1;
            end
        end else begin
            // idle state
            next_count <= count;
            next_total_count <= total_count;
            output_axis_tlast <= 0;
            output_axis_tvalid <= 0;
            output_axis_tdata <= 0;
            output_axis_tuser <= 0;
            busy <= 0;
        end
    end
end

always @* begin
    next_tag = tag;
    if (trigger && !counting && current_tag == tag) begin
        counting = 1;
        next_count = 1;
        next_total_count = monitor_axis_tkeep;
    end
    if (monitor_axis_tvalid && monitor_axis_tready && !monitor_axis_tlast) begin
        next_tag = monitor_axis_tuser;
    end
    count = next_count;
    total_count = next_total_count;
    current_tag = next_tag;
end

endmodule

module binary_adder_pipeline(
    input [99:0] a,
    input [99:0] b,
    output [99:0] sum,
    output [99:0] cout
);

reg [99:0] carry;
reg [99:0] sum_reg;

// First stage of pipeline
generate
    genvar i;
    for (i = 0; i < 100; i = i + 1) begin : stage1
        assign {carry[i], sum_reg[i]} = a[i] + b[i];
    end
endgenerate

// Second stage of pipeline
generate
    genvar i;
    for (i = 0; i < 100; i = i + 1) begin : stage2
        assign {carry[i], sum_reg[i]} = sum_reg[i] + carry[i-1];
    end
endgenerate

// Third stage of pipeline
generate
    genvar i;
    for (i = 0; i < 100; i = i + 1) begin : stage3
        assign {carry[i], sum[i]} = sum_reg[i] + carry[i-1];
    end
endgenerate

assign cout = carry;

endmodule

module checksum (
  input [n-1:0] data_in,
  input [n-1:0] checksum_in,
  output reg valid_data
);

parameter n = 8; // number of data signals

wire signed [n+1:0] sum;
wire signed [n+1:0] twos_complement;
wire signed [n+1:0] checksum_calc;

assign sum = {1'b0, data_in} + checksum_in;
assign twos_complement = ~sum + 1;
assign checksum_calc = {1'b0, data_in} + twos_complement;

assign checksum_out = twos_complement;

always @(*) begin
  if (checksum_calc == checksum_in) begin
    valid_data = 1'b1;
  end else begin
    valid_data = 1'b0;
  end
end

endmodule

