module top_module(
    input [31:0] a,
    input [31:0] b,
    input [1:0] select,
    input clk,
    output [63:0] sum,
    output carry_out,
    output [63:0] result
);

  wire [15:0] s0, s1, s2, s3;
  wire c0, c1, c2, c3;

  add16 adder0(.A(a[15:0]), .B(b[15:0]), .S(s0), .Cout(c0));
  add16 adder1(.A(a[31:16]), .B(b[31:16]), .S(s1), .Cout(c1));
  add16 adder2(.A(a[47:32]), .B(b[47:32]), .S(s2), .Cout(c2));
  add16 adder3(.A(a[63:48]), .B(b[63:48]), .S(s3), .Cout(c3));

  wire [63:0] sum_temp;
  assign sum_temp = {c3, c2, c1, c0, s3, s2, s1, s0};

  assign sum = select[0] ? sum_temp : 64'b0;

  wire [63:0] and_result;
  assign and_result = sum & carry_out;

  assign result = {and_result, carry_out};

  assign carry_out = c3;

endmodule

