module mealy_fsm (
  input clk,
  input reset,
  input in1,
  input in2,
  output reg out,
  output reg [2:0] state
);

  // Define the states
  parameter A = 3'b000;
  parameter B = 3'b001;
  parameter C = 3'b010;
  parameter D = 3'b011;
  parameter E = 3'b100;

  // Define the state transition table
  always @(posedge clk) begin
    if (reset) begin
      state <= A;
      out <= 0;
    end else begin
      case (state)
        A: begin
          if (in1 == 0 && in2 == 0) begin
            state <= B;
            out <= 0;
          end else if (in1 == 0 && in2 == 1) begin
            state <= A;
            out <= 0;
          end else if (in1 == 1 && in2 == 0) begin
            state <= C;
            out <= 1;
          end else if (in1 == 1 && in2 == 1) begin
            state <= D;
            out <= 0;
          end
        end
        B: begin
          if (in1 == 0 && in2 == 0) begin
            state <= A;
            out <= 0;
          end else if (in1 == 0 && in2 == 1) begin
            state <= B;
            out <= 0;
          end else if (in1 == 1 && in2 == 0) begin
            state <= C;
            out <= 1;
          end else if (in1 == 1 && in2 == 1) begin
            state <= D;
            out <= 0;
          end
        end
        C: begin
          if (in1 == 0 && in2 == 0) begin
            state <= A;
            out <= 0;
          end else if (in1 == 0 && in2 == 1) begin
            state <= B;
            out <= 0;
          end else if (in1 == 1 && in2 == 0) begin
            state <= C;
            out <= 1;
          end else if (in1 == 1 && in2 == 1) begin
            state <= D;
            out <= 0;
          end
        end
        D: begin
          if (in1 == 0 && in2 == 0) begin
            state <= A;
            out <= 0;
          end else if (in1 == 0 && in2 == 1) begin
            state <= B;
            out <= 0;
          end else if (in1 == 1 && in2 == 0) begin
            state <= C;
            out <= 1;
          end else if (in1 == 1 && in2 == 1) begin
            state <= D;
            out <= 0;
          end
        end
      endcase
    end
  end

endmodule

module DLL (
  input ref_clk,
  input fb_clk,
  input reset,
  input delay_ctrl,
  output out_clk
);

parameter n = 8; // number of delay stages
parameter delay_step = 10; // delay step size in picoseconds

reg [n-1:0] delay_line; // delay line implemented as a shift register
reg [n-1:0] delay_ctrl_reg; // register to hold the delay control value
reg [n-1:0] error; // register to hold the error signal

wire [n-1:0] fb_clk_delayed; // delayed feedback clock signal
wire [n-1:0] ref_clk_delayed; // delayed reference clock signal

assign fb_clk_delayed = delay_line;
assign ref_clk_delayed = {delay_line[n-2:0], ref_clk};

assign out_clk = ref_clk_delayed[n-1]; // output synchronized clock signal

always @(posedge fb_clk or posedge reset) begin
  if (reset) begin
    delay_line <= 0;
    delay_ctrl_reg <= 0;
    error <= 0;
  end else begin
    delay_line <= {delay_line[n-2:0], fb_clk_delayed[n-1]};
    error <= ref_clk_delayed ^ fb_clk_delayed;
    delay_ctrl_reg <= delay_ctrl_reg + delay_ctrl - error;
    delay_line <= {delay_line[n-2:0], delay_ctrl_reg[n-1]};
  end
end

endmodule

module div_pipelined_latch #(
		parameter N = 4
	)(
		//System
		input wire iCLOCK,
		input wire inRESET,
		input wire iREMOVE,
		//PREVIOUS
		input wire iPREVIOUS_VALID,
		output wire oPREVIOUS_BUSY,
		input wire iPREVIOUS_SIGN,
		input wire [31:0] iPREVIOUS_DIVISOR,
		input wire [31:0] iPREVIOUS_DIVIDEND,
		input wire [N-1:0] iPREVIOUS_Q,
		input wire [30:0] iPREVIOUS_R,
		//NEXT
		output wire oNEXT_VALID,
		input wire iNEXT_BUSY,
		output wire oNEXT_SIGN,
		output wire [31:0] oNEXT_DIVISOR,
		output wire [31:0] oNEXT_DIVIDEND,
		output wire [N-1:0] oNEXT_Q,
		output wire [30:0] oNEXT_R
	);

	reg b_valid;
	reg b_sign;
	reg [31:0] b_divisor;
	reg [31:0] b_dividend;
	reg [N-1:0] b_q;	
	reg [30:0] b_r;

	always@(posedge iCLOCK or negedge inRESET)begin
		if(!inRESET)begin
			b_valid <= 1'b0;
			b_sign <= 1'b0;
			b_divisor <= {32{1'b0}};
			b_dividend <= {32{1'b0}};	
			b_q <= {N{1'b0}};		
			b_r <= {31{1'b0}};		
		end
		else if(iREMOVE)begin
			b_valid <= 1'b0;
			b_sign <= 1'b0;
			b_divisor <= {32{1'b0}};
			b_dividend <= {32{1'b0}};	
			b_q	<= {N{1'b0}};		
			b_r	<= {31{1'b0}};	
		end
		else begin
			if(!iNEXT_BUSY)begin
				b_valid <= iPREVIOUS_VALID;
				b_sign <= iPREVIOUS_SIGN;
				b_divisor <= iPREVIOUS_DIVISOR;
				b_dividend <= iPREVIOUS_DIVIDEND;	
				b_q	<= iPREVIOUS_Q;		
				b_r	<= iPREVIOUS_R;
			end
		end
	end


	assign oPREVIOUS_BUSY = iNEXT_BUSY;
	assign oNEXT_VALID = b_valid;
	assign oNEXT_SIGN = b_sign;
	assign oNEXT_DIVISOR = b_divisor;
	assign oNEXT_DIVIDEND = b_dividend;
	assign oNEXT_Q = b_q;
	assign oNEXT_R = b_r;

endmodule

module timer
  (input wb_clk_i, input rst_i,
   input cyc_i, input stb_i, input [2:0] adr_i,
   input we_i, input [31:0] dat_i, output [31:0] dat_o, output ack_o,
   input sys_clk_i, input [31:0] master_time_i,
   output int_o );

   // Register to keep track of current time
   reg [31:0] time_wb;
   always @(posedge wb_clk_i)
     time_wb <= master_time_i;

   // Acknowledge signal
   assign ack_o = stb_i;

   // Interrupt logic
   reg [31:0] int_time;
   reg        int_reg;

   always @(posedge sys_clk_i)
     if(rst_i)
       begin
          int_time <= 0;
          int_reg <= 0;
       end
     else if(|int_time && (master_time_i == int_time))
       begin
          int_time <= 0;
          int_reg <= 1;
       end
     else if(stb_i & we_i)
       begin
          int_time <= dat_i;
          int_reg <= 0;
       end

   // Outputs
   assign dat_o = time_wb;
   assign int_o = int_reg;

endmodule

