    assign b_msb = sub ? b_msb_twos_comp : b_msb;

    // 16-bit adder modules
    adder_16bit adder_lsb(a_lsb, b_lsb, carry, sum_lsb);
    adder_16bit adder_msb(a_msb, b_msb, carry, sum_msb);

    // 32-bit sum output
    assign sum = {sum_msb, sum_lsb};

endmodule

module adder_16bit(
