module fifo (
    input clk,
    input rst_n,
    input push,
    input pop,
    input [7:0] datain,
    output empty,
    output almost_empty,
    output full,
    output almost_full,
    output error,
    output [7:0] dataout
);

wire [4:0] addr;
wire cen;
wire oen;
wire wen;
wire [7:0] data_to_ram;

fifo_ctr controller (
    .clk(clk),
    .rst_n(rst_n),
    .push(push),
    .pop(pop),
    .empty(empty),
    .almost_empty(almost_empty),
    .full(full),
    .almost_full(almost_full),
    .error(error),
    .cen(cen),
    .wen(wen),
    .oen(oen),
    .addr(addr)
);

RAM32x8 ram (
    .Q(dataout),
    .CLK(clk),
    .CEN(cen),
    .WEN(wen),
    .A(addr),
    .D(datain),
    .OEN(oen)
);

endmodule

module fifo_ctr (
    input clk,
    input rst_n,
    input push,
    input pop,
    output empty,
    output almost_empty,
    output full,
    output almost_full,
    output error,
    output cen,
    output wen,
    output oen,
    output reg [4:0] addr
);

reg [4:0] write_ptr;
reg [4:0] read_ptr;
reg [4:0] count;
reg [4:0] next_write_ptr;
reg [4:0] next_read_ptr;
reg [4:0] next_count;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        write_ptr <= 0;
        read_ptr <= 0;
        count <= 0;
    end else begin
        if (push && !pop && !full) begin
            next_write_ptr <= write_ptr + 1;
            next_count <= count + 1;
        end else begin
            next_write_ptr <= write_ptr;
            next_count <= count;
        end

        if (pop && !push && !empty) begin
            next_read_ptr <= read_ptr + 1;
            next_count <= count - 1;
        end else begin
            next_read_ptr <= read_ptr;
            next_count <= count;
        end

        if (count == 0) begin
            empty <= 1;
        end else begin
            empty <= 0;
        end

        if (count == 1) begin
            almost_empty <= 1;
        end else begin
            almost_empty <= 0;
        end

        if (count == 32) begin
            full <= 1;
        end else begin
            full <= 0;
        end

        if (count == 31) begin
            almost_full <= 1;
        end else begin
            almost_full <= 0;
        end

        if (push && pop) begin
            error <= 1;
        end else begin
            error <= 0;
        end
    end
end

assign cen = ~error & ~empty;
assign wen = push & ~error & ~full;
assign oen = pop & ~error & ~empty;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        addr <= 0;
    end else begin
        if (wen) begin
            addr <= next_write_ptr;
        end else if (oen) begin
            addr <= next_read_ptr;
        end
    end
end

assign next_write_ptr = (write_ptr == 31) ? 0 : write_ptr + 1;
assign next_read_ptr = (read_ptr == 31) ? 0 : read_ptr + 1;
assign next_count = count;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        write_ptr <= 0;
        read_ptr <= 0;
        count <= 0;
    end else begin
        write_ptr <= next_write_ptr;
        read_ptr <= next_read_ptr;
        count <= next_count;
    end
end

endmodule

module fifo
  #(parameter WIDTH=32, SIZE=9)
   (input clk, input reset, input clear,
    input [WIDTH-1:0] datain,
    input src_rdy_i,
    output dst_rdy_o,
    output [WIDTH-1:0] dataout,
    output src_rdy_o,
    input dst_rdy_i,

    output reg [15:0] space,
    output reg [15:0] occupied);

   wire write 	     = src_rdy_i & dst_rdy_o;
   wire read 	     = dst_rdy_i & src_rdy_o;
   wire full, empty;

   assign dst_rdy_o  = ~full;
   assign src_rdy_o  = ~empty;

   // Read side states
   localparam 	  EMPTY = 0;
   localparam 	  PRE_READ = 1;
   localparam 	  READING = 2;

   reg [SIZE-1:0] wr_addr, rd_addr;
   reg [1:0] 	  read_state;

   reg 	  empty_reg, full_reg;
   always @(posedge clk)
     if(reset)
       wr_addr <= 0;
     else if(clear)
       wr_addr <= 0;
     else if(write)
       wr_addr <= wr_addr + 1;

   ram_2port #(.DWIDTH(WIDTH),.AWIDTH(SIZE))
     ram (.clka(clk),
	  .ena(1'b1),
	  .wea(write),
	  .addra(wr_addr),
	  .dia(datain),
	  .doa(),

	  .clkb(clk),
	  .enb((read_state==PRE_READ)|read),
	  .web(0),
	  .addrb(rd_addr),
	  .dib({WIDTH{1'b1}}),
	  .dob(dataout));

   always @(posedge clk)
     if(reset)
       begin
	  read_state <= EMPTY;
	  rd_addr <= 0;
	  empty_reg <= 1;
       end
     else
       if(clear)
	 begin
	    read_state <= EMPTY;
	    rd_addr <= 0;
	    empty_reg <= 1;
	 end
       else 
	 case(read_state)
	   EMPTY :
	     if(write)
	       begin
		  //rd_addr <= wr_addr;
		  read_state <= PRE_READ;
	       end
	   PRE_READ :
	     begin
		read_state <= READING;
		empty_reg <= 0;
		rd_addr <= rd_addr + 1;
	     end

	   READING :
	     if(read)
	       if(rd_addr == wr_addr)
		 begin
		    empty_reg <= 1;
		    if(write)
		      read_state <= PRE_READ;
		    else
		      read_state <= EMPTY;
		 end
	       else
		 rd_addr <= rd_addr + 1;
	 endcase // case(read_state)

   wire [SIZE-1:0] dont_write_past_me = rd_addr - 3;
   wire 	   becoming_full = wr_addr == dont_write_past_me;

   always @(posedge clk)
     if(reset)
       full_reg <= 0;
     else if(clear)
       full_reg <= 0;
     else if(read & ~write)
       full_reg <= 0;
     //else if(write & ~read & (wr_addr == (rd_addr-3)))
     else if(write & ~read & becoming_full)
       full_reg <= 1;

   //assign empty = (read_state != READING);
   assign empty = empty_reg;

   // assign full = ((rd_addr - 1) == wr_addr);
   assign full = full_reg;

   //////////////////////////////////////////////
   // space and occupied are for diagnostics only
   // not guaranteed exact

   localparam NUMLINES = (1<<SIZE)-2;
   always @(posedge clk)
     if(reset)
       space <= NUMLINES;
     else if(clear)
       space <= NUMLINES;
     else if(read & ~write)
       space <= space + 1;
     else if(write & ~read)
       space <= space - 1;

   always @(posedge clk)
     if(reset)
       occupied <= 0;
     else if(clear)
       occupied <= 0;
     else if(read & ~write)
       occupied <= occupied - 1;
     else if(write & ~read)
       occupied <= occupied + 1;

endmodule

module PRNG (
  input reset,
  input clock,
  input [n-1:0] seed,
  output reg [n-1:0] rand
);

parameter n = 8; // number of bits in the pseudo-random number
parameter a = 3; // constant used to generate the pseudo-random number
parameter c = 5; // constant used to generate the pseudo-random number

reg [n-1:0] shift_reg;

always @(posedge clock) begin
  if (reset) begin
    shift_reg <= seed;
  end else begin
    shift_reg <= {shift_reg[n-2:0], shift_reg[n-a-1] ^ shift_reg[n-1]};
  end
  rand <= shift_reg;
end

endmodule

module shift_register (
  input clk,
  input data_in,
  input shift_en,
  input reset,
  output reg data_out
);

parameter n = 8; // number of bits in the shift register

reg [n-1:0] shift_reg;

always @(posedge clk) begin
  if (reset) begin
    shift_reg <= 0;
    data_out <= 0;
  end
  else if (shift_en) begin
    shift_reg <= {shift_reg[n-2:0], data_in};
    data_out <= shift_reg[n-1];
  end
end

endmodule

module d_ff_en_clock_gate (
  input CLK, EN, TE,
  output ENCLK
);

  TLATNTSCAX2TS latch (.E(EN), .SE(TE), .CK(CLK), .ECK(ENCLK));
  assign ENCLK = EN ? CLK : 1'b0;

endmodule

module crc8_single_bit (
  input data,
  input enable_crc,
  input reset,
  input sync_reset_crc,
  input clk,
  output reg [7:0] crc_out
);

  // polynomial: (0 1 2 8)
  // data width: 1
  function [7:0] nextCRC8_D1;
    input data;
    input [7:0] crc;

    reg [0:0] d;
    reg [7:0] c;
    reg [7:0] new_crc;

    begin
      d[0] = data;
      c = crc;

      new_crc[0] = d[0] ^ c[7];
      new_crc[1] = d[0] ^ c[0] ^ c[7];
      new_crc[2] = d[0] ^ c[1] ^ c[7];
      new_crc[3] = c[2];
      new_crc[4] = c[3];
      new_crc[5] = c[4];
      new_crc[6] = c[5];
      new_crc[7] = c[6];

      nextCRC8_D1 = new_crc;
    end
  endfunction

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      crc_out <= 0;
    end else if (sync_reset_crc) begin
      crc_out <= 0;
    end else if (enable_crc) begin
      crc_out <= nextCRC8_D1(data, crc_out);
    end
  end

endmodule

module adder_subtractor (
    input [7:0] A,
    input [7:0] B,
    input carry_in,
    input sub,
    output reg [7:0] sum,
    output reg borrow_out
);

reg [7:0] A_reg, B_reg, sum_reg;
reg carry_reg, borrow_reg;

always @(posedge clk) begin
    A_reg <= A;
    B_reg <= B;
    sum_reg <= sum;
    carry_reg <= carry_in;
    borrow_reg <= borrow_out;
end

always @(posedge clk) begin
    if (sub) begin
        sum_reg <= A_reg - B_reg - carry_reg;
        borrow_reg <= (sum_reg[7] == 1);
    end else begin
        sum_reg <= A_reg + B_reg + carry_reg;
        carry_reg <= (sum_reg[8] == 1);
    end
end

assign sum = sum_reg;
assign borrow_out = borrow_reg;

endmodule

module marker_tracker(
    input clk_cpu,
    input clk_camera,
    input cam_vsync,
    input go,
    input [20:0]track_clr,
    input [15:0] cam_pixel_data,
    input [16:0]  cam_pixel_addr,
    input cam_write_enable,
    output [16:0] marker_x,
    output [16:0] marker_y,
    output marker_valid,
    output [4:0] pixel_red,
    output [5:0] pixel_green,
    output [4:0] pixel_blue
);

    reg [4:0]thresh;
    reg [10:0]tg_clr_r;
    reg [10:0]tg_clr_g;
    reg [10:0]tg_clr_b;

    reg [16:0]marker_y_reg, marker_x_reg, i_marker_x, i_marker_y;    // Holds marker_x latched

    reg [31:0]sum_x;    //
    reg [31:0]sum_y;
    reg [31:0]sample_count; //

    reg marker_valid_reg;

    reg [9:0] cam_pixel_x;
    reg [9:0] cam_pixel_y;
    reg [16:0] last_captured;
    reg new_addr;
    reg [15:0]cam_pixel_data_reg;

    assign marker_valid = marker_valid_reg;
    assign marker_x = marker_x_reg;
    assign marker_y = marker_y_reg;

    assign pixel_red = cam_pixel_data_reg[15:11];
    assign pixel_green = cam_pixel_data_reg[10:5];
    assign pixel_blue = cam_pixel_data_reg[4:0];

    initial
    begin
        thresh = 5'b0;
        tg_clr_r = 5'b0;
        tg_clr_g = 6'b0;
        tg_clr_b = 5'b0;
        marker_x_reg = 17'd0;
        marker_y_reg = 17'd0;
        sum_x = 32'd0;
        sum_y = 32'd0;
        sample_count = 32'd0;
    end 

    wire r_valid;
    wire g_valid;
    wire b_valid;

    assign r_valid =  pixel_red >= tg_clr_r;
    assign g_valid = pixel_green >= tg_clr_g;
    assign b_valid =  pixel_blue >= tg_clr_b;

    //record x, y from address and capture new address to process
    always @(posedge clk_camera)
    begin
        if (cam_vsync)
        begin
            cam_pixel_x <= 10'b0;
            cam_pixel_y <= 10'b0;
            new_addr <= 0;
            last_captured <= 0;
            cam_pixel_data_reg <= 0;
        end
        else if(last_captured != cam_pixel_addr && cam_write_enable == 1)
        begin
            cam_pixel_y <= cam_pixel_addr/320;
            cam_pixel_x <= cam_pixel_addr - cam_pixel_y*320;
            new_addr = 1;
            cam_pixel_data_reg <= cam_pixel_data;
            last_captured <= cam_pixel_addr;
        end
        else
            new_addr <= 0;
    end

    //Capture color and threshold
    always @(posedge clk_cpu)
    begin
        thresh <= track_clr[20:16];
        tg_clr_r <= {5'b0, track_clr[15:11]};
        tg_clr_g <= {4'b0, track_clr[10:5]};
        tg_clr_b <= {5'b0, track_clr[4:0]};
    end

    //
    always @(posedge clk_camera)
    begin
       if(cam_vsync)
        begin
            // Reset counter
            sample_count <= 32'b0;
            // Reset sum x and y
            sum_x <= 32'b0;
            sum_y <= 32'b0;
            if(sample_count > 0)
                marker_valid_reg <= 1;
            else
                 marker_valid_reg <= 0;
            if(sample_count > 0)
            begin
                marker_x_reg <= i_marker_x;
                marker_y_reg <= i_marker_y;
            end
        end
        else
           marker_valid_reg <= 0;

       if(go && new_addr && !cam_vsync)
       begin
            if(r_valid && g_valid && b_valid)
            begin
                sum_x <= sum_x + cam_pixel_x;
                sum_y <= sum_y + cam_pixel_y;
                //Increment count
                sample_count <= sample_count + 1;
            end
        end
        i_marker_x <= sum_x/sample_count;
        i_marker_y <= sum_y/sample_count;
    end

endmodule

module spi4(  input   CLK,

              //host interface
              input  [ 2:0] CHANNEL,
              output [11:0] CONV_RESULT,
              input         REQUEST,
              output        BUSY,

              //device interface
              output  CS,
              output  SCLK,
              output  SDO,
              input   SDI  );

reg [ 4:0] tx_sreg = 0;
reg [15:0] rx_sreg = 0;
reg [11:0] saved_data = 0;
reg [4:0] bit_cnt = 0;


always @(negedge CLK)
  begin
  if(BUSY)
    begin
    if(bit_cnt < 16)  bit_cnt <= bit_cnt + 5'd1;
    else              
      begin
      saved_data <= rx_sreg[11:0];
      bit_cnt <= 0;
      end

    tx_sreg[4:1] <= tx_sreg[3:0];
    tx_sreg[0] <= 0;

    end
  else
    begin
    if(REQUEST)
      begin
      bit_cnt <= 1;
      tx_sreg <= {2'b0, CHANNEL};
      end
    end
  end              


always@(posedge CLK)
  begin
  if(BUSY)
    begin
    rx_sreg[0] <= SDI;
    rx_sreg[15:1] <= rx_sreg[14:0];
    end
  end

//-----------------------------------------------

assign BUSY = (bit_cnt != 5'd0);
assign CS   = ~BUSY;
assign SDO  = tx_sreg[4];
assign SCLK = BUSY & CLK;
assign CONV_RESULT = saved_data; 

endmodule

module binary_adder (
    input A1_N,
    input A2_N,
    input B1,
    input B2,
    output S1,
    output S2
);

    wire C1, C2, C3;

    xor(S2, A2_N, B2);
    xor(S1, A1_N, B1);
    and(C1, A1_N, B1);
    and(C2, A2_N, B2);
    and(C3, S1, S2);
    or(S2, C1, C2, C3);

endmodule

module rj_memory (input wr_en, rd_en, Sclk,
						input [3:0] rj_wr_addr, rj_rd_addr,
						input [15:0] data_in,
						output [15:0] rj_data);

	reg [15:0] rj_mem [0:15];

	always @(negedge Sclk)
	begin
		if(wr_en == 1'b1)
			rj_mem[rj_wr_addr] = data_in;
		else
			rj_mem[rj_wr_addr] = rj_mem[rj_wr_addr];		
	end

