module half_subtractor (
  input a,
  input b,
  output diff,
  output bout
);
  assign diff = a ^ b;
  assign bout = a & ~b;
endmodule

module full_subtractor (
  input a,
  input b,
  input bin,
  output diff,
  output bout
);
  wire temp_diff1, temp_diff2, temp_bout1, temp_bout2;
  half_subtractor hs1(.a(a), .b(b), .diff(temp_diff1), .bout(temp_bout1));
  half_subtractor hs2(.a(temp_diff1), .b(bin), .diff(diff), .bout(temp_bout2));
  assign bout = temp_bout1 | temp_bout2;
endmodule

module Adders (
  input a,
  input b,
  input cin,
  output s,
  output cout
);

// half adder
// inputs: a, b
// outputs: s, c
// s = a XOR b
// c = a AND b
wire ha_s = a ^ b;
wire ha_c = a & b;

// full adder
// inputs: a, b, cin
// outputs: s, cout
// s = a XOR b XOR cin
// cout = (a AND b) OR (a AND cin) OR (b AND cin)
wire fa_s1 = a ^ b;
wire fa_s = fa_s1 ^ cin;
wire fa_c1 = a & b;
wire fa_c2 = a & cin;
wire fa_c3 = b & cin;
wire fa_cout = fa_c1 | fa_c2 | fa_c3;

assign s = fa_s;
assign cout = fa_cout;

endmodule

module addr_gen(nrst, clk, wr_en, wr_inc, load_w2r, rd_inc, rd_step, addr_wr, addr_rd, wr_end);
    input nrst;
    input clk;
    input wr_en;
    input wr_inc;
    input load_w2r;
    input rd_inc;
    input [7:0] rd_step;
    output [17:0] addr_wr;
    output [17:0] addr_rd;
    output wr_end;

    wire [17:0] addr_wr;
    wire [17:0] addr_rd;
    wire [17:0] rd_step_ex;
    reg wr_end;
    wire wr_inc_sig;
    wire reach;

    // 写地址返回到读地址表示写满，实现预触发深度调整是触发后立即修改读地址到需要位置
    assign reach = (addr_wr == addr_rd);
    assign wr_inc_sig = wr_en & wr_inc & ~wr_end;

    assign rd_step_ex = {{11{rd_step[7]}}, rd_step[6:0]};

    // 写地址自增
    cntn #(18) u_wrcnt(.nrst(nrst), .clk(clk),
        .en(wr_inc_sig), .step(1), .load(0), .cin(0), .cnt(addr_wr));

    // 触发时设置读地址为写地址，否则自增或自减
    cntn #(18) u_rdcnt(.nrst(nrst), .clk(clk),
        .en(rd_inc), .step(rd_step_ex), .load(load_w2r), .cin(addr_wr), .cnt(addr_rd));

    // 生成采样完成信号，在停止采样时清除
    always @(posedge clk or negedge nrst) begin
        if (~nrst) begin
            wr_end <= 1'b0;
        end else if (reach) begin
            wr_end <= 1'b1;
        end else if (~wr_en) begin
            wr_end <= 1'b0;
        end
    end
endmodule

module eth_random (MTxClk, Reset, StateJam, StateJam_q, RetryCnt, NibCnt, ByteCnt, 
                   RandomEq0, RandomEqByteCnt);

input MTxClk;
input Reset;
input StateJam;
input StateJam_q;
input [3:0] RetryCnt;
input [15:0] NibCnt;
input [9:0] ByteCnt;
output RandomEq0;
output RandomEqByteCnt;

wire Feedback;
reg [9:0] x;
wire [9:0] Random;
reg  [9:0] RandomLatched;


always @ (posedge MTxClk or posedge Reset)
begin
  if(Reset)
    x[9:0] <=  0;
  else
    x[9:0] <=  {x[8:0], Feedback};
end

assign Feedback = ~(x[2] ^ x[9]);

assign Random [0] = x[0];
assign Random [1] = (RetryCnt > 1) ? x[1] : 1'b0;
assign Random [2] = (RetryCnt > 2) ? x[2] : 1'b0;
assign Random [3] = (RetryCnt > 3) ? x[3] : 1'b0;
assign Random [4] = (RetryCnt > 4) ? x[4] : 1'b0;
assign Random [5] = (RetryCnt > 5) ? x[5] : 1'b0;
assign Random [6] = (RetryCnt > 6) ? x[6] : 1'b0;
assign Random [7] = (RetryCnt > 7) ? x[7] : 1'b0;
assign Random [8] = (RetryCnt > 8) ? x[8] : 1'b0;
assign Random [9] = (RetryCnt > 9) ? x[9] : 1'b0;


always @ (posedge MTxClk or posedge Reset)
begin
  if(Reset)
    RandomLatched <=  10'h000;
  else
    begin
      if(StateJam & StateJam_q)
        RandomLatched <=  Random;
    end
end

// Random Number == 0      IEEE 802.3 page 68. If 0 we go to defer and not to backoff.
assign RandomEq0 = RandomLatched == 10'h0; 

assign RandomEqByteCnt = ByteCnt[9:0] == RandomLatched & (&NibCnt[6:0]);

endmodule

module comparator_and_and (
  input [3:0] in1,
  input [3:0] in2,
  output reg [1:0] out,
  output [3:0] and_out
);

  // Priority encoder to determine which input is greater
  wire [3:0] diff = in1 - in2;
  wire [3:0] abs_diff = {diff[3], diff[3:0] ^ diff[2:0], diff[1:0] ^ diff[0]};
  wire [1:0] priority = ~|abs_diff[3:0] ? 2'b10 : ~diff[3] ? 2'b01 : 2'b00;

  // Bitwise AND of the two inputs
  assign and_out = in1 & in2;

  // Output signal indicating which input is greater
  always @* begin
    out = priority;
  end

endmodule

