module phase_detector (
  input ref_clk,
  input feedback_clk,
  output reg control_voltage
);

reg [1:0] ref_phase;
reg [1:0] feedback_phase;

always @(posedge ref_clk) begin
  ref_phase <= {ref_phase[0], ref_clk};
end

always @(posedge feedback_clk) begin
  feedback_phase <= {feedback_phase[0], feedback_clk};
end

always @(posedge ref_clk) begin
  if (ref_phase[1] != feedback_phase[1]) begin
    control_voltage <= control_voltage + k*(ref_phase[1] - feedback_phase[1]);
  end
end

endmodule

module loop_filter (
  input control_voltage,
  output reg filtered_voltage
