  if (reset) begin
    clk_out <= 1'b0;
    counter <= 0;
  end else begin
    if (counter == N-1) begin
      clk_out <= ~clk_out;
      counter <= 0;
    end else begin
      counter <= counter + 1;
    end
  end
end

endmodule

