module hyperbolic (
  input x,
  output sineh_out,
  output cosh_out,
  output tanh_out
);

  // Define the exponential function
  function [31:0] exp;
    input [31:0] x;
    begin
      exp = $realtobits($exp(x));
    end
  endfunction

  // Define the division operator
  function [31:0] div;
    input [31:0] numerator;
    input [31:0] denominator;
    begin
      div = $realtobits($itor($bits2real(numerator) / $bits2real(denominator)));
    end
  endfunction

  // Calculate the values of sineh, cosh, and tanh at the input angle
  reg [31:0] exp_x;
  reg [31:0] exp_neg_x;
  reg [31:0] sineh;
  reg [31:0] cosh;
  reg [31:0] tanh;
  always @(*) begin
    exp_x = exp(x);
    exp_neg_x = exp(-x);
    sineh = div(exp_x - exp_neg_x, 32'b10);
    cosh = div(exp_x + exp_neg_x, 32'b10);
    tanh = div(sineh, cosh);
  end

  // Output the calculated values to the output signals
  assign sineh_out = sineh;
  assign cosh_out = cosh;
  assign tanh_out = tanh;

endmodule

module ioctrl_wb #(parameter BASE_ADDR = 32'h00000800) (

    // system signals
    input clk_i, 
    input rst_i,

    // wb signals
    input      [31:0] dat_i, 
    output reg [31:0] dat_o, 
    input      [31:0] adr_i, 
    input      we_i, 
    input      [3:0] sel_i, 
    input      cyc_i, 
    input      stb_i, 
    output reg ack_o,

	 // spi signals
	 input sdo_i,
	 output sck_o,
	 output cs_o
);

localparam IDLE = 0;
localparam WAIT = 1;
localparam ACK  = 2;

wire read_flag;

reg [31:0] data_w;
reg [31:0] adr_w;
reg [3:0] sel_w;
reg we_w;
reg cyc_w;
reg stb_w;

assign dat_o = (state_r == ACK && read_flag && adr_r == BASE_ADDR)? data_r: 0;

spi_read spi (
   .clk(clk_i),
	.sdo(sdo_i),
	.reset(rst_i),
	.data(data_r),
	.cs(cs_o),
	.sck(sck_o),
	.read_flag(read_flag)
);

always@(posedge clk_i, posedge rst_i)
    if(rst_i) begin
        state_r <= IDLE;
        ack_o   <= 1'b0;
    end else begin

        case(state_r)
            IDLE: 
                begin
                    if(read_w) begin
                        state_r <= WAIT;
                        cyc_w   <= 1'b1;
                        stb_w   <= 1'b1;
                        adr_w   <= adr_i;
                        sel_w   <= sel_i;
                        we_w    <= 1'b0;
                    end else if(write_w) begin
                        state_r <= WAIT;
                        cyc_w   <= 1'b1;
                        stb_w   <= 1'b1;
                        adr_w   <= adr_i;
                        sel_w   <= sel_i;
                        we_w    <= 1'b1;
                        data_w  <= dat_i;
                    end
                end
            WAIT:
                begin
                    if(read_flag) begin
                        if(read_w) begin
                            state_r <= ACK;
                            ack_o   <= 1'b1;
                        end else if(write_w) begin
                            state_r <= IDLE;
                            ack_o   <= 1'b1;
                        end
                    end
                end
            ACK:
                begin
                    state_r <= IDLE;
                    ack_o   <= 1'b0;
                end
        endcase
    end

reg [31:0] adr_r;
wire read_w  = cyc_w & stb_w & !we_w;
wire write_w = cyc_w & stb_w & we_w;

always@(posedge clk_i, posedge rst_i) begin
    if(rst_i) begin
        adr_r <= 0;
    end else begin
        if(read_w) begin
            adr_r <= adr_w;
        end else if(write_w) begin
            adr_r <= 0;
        end
    end
end

assign cs_o = state_r == WAIT;

always@(posedge clk_i, posedge rst_i) begin
    if(rst_i) begin
        sck_o <= 1'b0;
    end else begin
        if(state_r == WAIT) begin
            sck_o <= ~sck_o;
        end else begin
            sck_o <= 1'b0;
        end
    end
end

endmodule

module spi_interface(
  input [7:0] send_data,
  input begin_transmission,
  input slave_select,
  input miso,
  input clk,
  input rst,
  output reg [7:0] received_data,
  output reg end_transmission,
  output reg mosi,
  output reg sclk
);

  // Define states for the FSM
  parameter [1:0] RxTxTYPE_idle = 2'b00,
                  RxTxTYPE_rx_tx = 2'b01,
                  RxTxTYPE_hold = 2'b10;
  reg [1:0] RxTxSTATE;

  // Define constants for the SPI interface
  parameter [11:0] SPI_CLK_COUNT_MAX = 12'hFFF;
  parameter [3:0] RX_COUNT_MAX = 4'h8;

  // Define registers and wires for the SPI interface
  reg [11:0] spi_clk_count;
  reg [3:0] rx_count;
  reg [7:0] shift_register;
  reg sclk_buffer, sclk_previous;

  // Define the FSM
  always @(posedge clk) begin
    if (rst) begin
      mosi <= 1'b1;
      RxTxSTATE <= RxTxTYPE_idle;
      received_data <= 8'h00;
      shift_register <= 8'h00;
    end
    else begin
      case (RxTxSTATE)
        RxTxTYPE_idle: begin
          end_transmission <= 1'b0;
          if (begin_transmission) begin
            RxTxSTATE <= RxTxTYPE_rx_tx;
            rx_count <= 4'h0;
            shift_register <= send_data;
          end
        end
        RxTxTYPE_rx_tx: begin
          // Send bit
          if (rx_count < RX_COUNT_MAX) begin
            if (sclk_previous == 1'b1 && sclk_buffer == 1'b0) begin
              mosi <= shift_register[7];
            end
            // Receive bit
            else if (sclk_previous == 1'b0 && sclk_buffer == 1'b1) begin
              shift_register[7:1] <= shift_register[6:0];
              shift_register[0] <= miso;
              rx_count <= rx_count + 1'b1;
            end
          end
          else begin
            RxTxSTATE <= RxTxTYPE_hold;
            end_transmission <= 1'b1;
            received_data <= shift_register;
          end
        end
        RxTxTYPE_hold: begin
          end_transmission <= 1'b0;
          if (slave_select) begin
            mosi <= 1'b1;
            RxTxSTATE <= RxTxTYPE_idle;
          end
          else if (begin_transmission) begin
            RxTxSTATE <= RxTxTYPE_rx_tx;
            rx_count <= 4'h0;
            shift_register <= send_data;
          end
        end
      endcase
    end
  end

  // Define the serial clock generator
  always @(posedge clk) begin
    if (rst) begin
      sclk_previous <= 1'b1;
      sclk_buffer <= 1'b1;
      spi_clk_count <= 12'h000;
    end
    else if (RxTxSTATE == RxTxTYPE_rx_tx) begin
      if (spi_clk_count == SPI_CLK_COUNT_MAX) begin
        sclk_buffer <= ~sclk_buffer;
        spi_clk_count <= 12'h000;
      end
      else begin
        sclk_previous <= sclk_buffer;
        spi_clk_count <= spi_clk_count + 1'b1;
      end
    end
    else begin
      sclk_previous <= 1'b1;
    end
  end

  // Assign the serial clock output
  assign sclk = sclk_previous;

endmodule

module shift_register (
  input clk,
  input reset,
  input [7:0] data_in,
  input [1:0] shift_direction,
  input load,
  output [7:0] data_out
);

  reg [7:0] pipeline_reg [0:2];
  reg [1:0] pipeline_shift_dir [0:1];
  reg pipeline_load;

  always @(posedge clk) begin
    if (reset) begin
      pipeline_reg[0] <= 8'b00110100;
      pipeline_reg[1] <= 8'b00000000;
      pipeline_reg[2] <= 8'b00000000;
      pipeline_shift_dir[0] <= 2'b00;
      pipeline_shift_dir[1] <= 2'b00;
      pipeline_load <= 1'b0;
    end else begin
      pipeline_reg[0] <= pipeline_reg[1];
      pipeline_reg[1] <= pipeline_reg[2];
      if (pipeline_load) begin
        pipeline_reg[2] <= data_in;
      end else begin
        if (pipeline_shift_dir[0] == 2'b00) begin
          pipeline_reg[2] <= {pipeline_reg[2][6:0], pipeline_reg[1][7]};
        end else if (pipeline_shift_dir[0] == 2'b01) begin
          pipeline_reg[2] <= {pipeline_reg[1][0], pipeline_reg[2][7:1]};
        end else if (pipeline_shift_dir[0] == 2'b10) begin
          pipeline_reg[2] <= {pipeline_reg[2][1:7], pipeline_reg[1][0]};
        end else begin
          pipeline_reg[2] <= {pipeline_reg[1][7], pipeline_reg[2][7:1]};
        end
      end
      pipeline_shift_dir[0] <= pipeline_shift_dir[1];
      pipeline_shift_dir[1] <= shift_direction;
      pipeline_load <= load;
    end
  end

  assign data_out = pipeline_reg[0];

endmodule

module Moore #(
    parameter width = 2
)(
    output reg [width-1:0] out,
    input [width-1:0] in,
    input clk,
    input rst_n
);

parameter S0 = 2'b00;
parameter S1 = 2'b01;
parameter S2 = 2'b10;

reg [width-1:0] state, next_state;

always @(posedge clk, negedge rst_n) begin
    if (!rst_n) begin
        state <= S0;
    end else begin
        state <= next_state;
    end
end

always @(*) begin
    case(state)
        S0: begin
            if (in == 1) begin
                next_state = S1;
            end else begin
                next_state = S0;
            end
        end
        S1: begin
            if (in == 0) begin
                next_state = S2;
            end else begin
                next_state = S1;
            end
        end
        S2: begin
            if (in == 0) begin
                next_state = S0;
            end else begin
                next_state = S1;
            end
        end
        default: begin
            next_state = S0;
        end
    endcase
end

always @(state) begin
    case(state)
        S2: begin
            out = 1;
        end
        default: begin
            out = 0;
        end
    endcase
end

endmodule

