  output d_read, d_waitrequest,
  output [31:0] cpu_d_readdata, cpu_d_writedata,
  output d_write
);

reg [31:0] data_reg;
reg [31:0] trace_reg0;
reg [31:0] trace_reg1;
reg [31:0] trace_reg2;
reg [31:0] trace_reg3;
reg [3:0] breakpoint_armed;
reg [3:0] trace_enabled;
reg goto0_enabled;
reg goto1_enabled;
reg [17:0] goto_address;

assign cpu_d_address = d_address;
assign cpu_d_readdata = d_read ? data_reg : av_ld_data_aligned_filtered;
assign cpu_d_read = d_read;
assign cpu_d_writedata = E_st_data;
assign cpu_d_write = d_write;
assign d_waitrequest = d_waitrequest;

always @(posedge clk or negedge reset_n) begin
  if (!reset_n) begin
    dbrk_break <= 0;
    dbrk_trigout <= 0;
    dbrk_traceoff <= 0;
    dbrk_traceon <= 0;
    dbrk_traceme <= 0;
    dbrk_goto0 <= 0;
    dbrk_goto1 <= 0;
    goto0_enabled <= 0;
    goto1_enabled <= 0;
  end else begin
    if (d_write) begin
      data_reg <= cpu_d_writedata;
    end
    if (dbrk_break) begin
      dbrk_break <= debugack;
    end else begin
      if (breakpoint_armed[0] && (d_address == 18'h8000)) begin
        dbrk_break <= 1;
        dbrk_trigout <= trace_enabled[0];
        dbrk_traceoff <= ~trace_enabled[0];
        dbrk_traceon <= trace_enabled[0];
        dbrk_traceme <= 1;
        dbrk_goto0 <= goto0_enabled;
        dbrk_goto1 <= goto1_enabled;
        goto0_enabled <= 0;
        goto1_enabled <= 0;
        if (trace_enabled[0]) begin
          trace_reg0 <= data_reg;
        end
      end else if (breakpoint_armed[1] && (d_address == 18'h9000)) begin
        dbrk_break <= 1;
        dbrk_trigout <= trace_enabled[1];
        dbrk_traceoff <= ~trace_enabled[1];
        dbrk_traceon <= trace_enabled[1];
        dbrk_traceme <= 1;
        dbrk_goto0 <= goto0_enabled;
        dbrk_goto1 <= goto1_enabled;
        goto0_enabled <= 0;
        goto1_enabled <= 0;
        if (trace_enabled[1]) begin
          trace_reg1 <= data_reg;
        end
      end else if (breakpoint_armed[2] && (d_address == 18'ha000)) begin
        dbrk_break <= 1;
        dbrk_trigout <= trace_enabled[2];
        dbrk_traceoff <= ~trace_enabled[2];
        dbrk_traceon <= trace_enabled[2];
        dbrk_traceme <= 1;
        dbrk_goto0 <= goto0_enabled;
        dbrk_goto1 <= goto1_enabled;
        goto0_enabled <= 0;
        goto1_enabled <= 0;
        if (trace_enabled[2]) begin
          trace_reg2 <= data_reg;
        end
      end else if (breakpoint_armed[3] && (d_address == 18'hb000)) begin
        dbrk_break <= 1;
        dbrk_trigout <= trace_enabled[3];
        dbrk_traceoff <= ~trace_enabled[3];
        dbrk_traceon <= trace_enabled[3];
        dbrk_traceme <= 1;
        dbrk_goto0 <= goto0_enabled;
        dbrk_goto1 <= goto1_enabled;
        goto0_enabled <= 0;
        goto1_enabled <= 0;
        if (trace_enabled[3]) begin
          trace_reg3 <= data_reg;
        end
      end
    end
  end
end

always @(posedge clk or negedge reset_n) begin
  if (!reset_n) begin
    breakpoint_armed <= 0;
    trace_enabled <= 0;
  end else begin
    if (d_write) begin
      case(d_address)
        18'h8004: begin
          breakpoint_armed[0] <= cpu_d_writedata[0];
        end
        18'h8008: begin
          trace_enabled[0] <= cpu_d_writedata[0];
        end
        18'h800c: begin
          goto0_enabled <= cpu_d_writedata[0];
          goto_address <= cpu_d_writedata[17:0];
        end
        18'h8010: begin
          goto1_enabled <= cpu_d_writedata[0];
          goto_address <= cpu_d_writedata[17:0];
        end
        18'h9004: begin
          breakpoint_armed[1] <= cpu_d_writedata[0];
        end
        18'h9008: begin
          trace_enabled[1] <= cpu_d_writedata[0];
        end
        18'ha004: begin
          breakpoint_armed[2] <= cpu_d_writedata[0];
        end
        18'ha008: begin
          trace_enabled[2] <= cpu_d_writedata[0];
        end
        18'hb004: begin
          breakpoint_armed[3] <= cpu_d_writedata[0];
        end
        18'hb008: begin
          trace_enabled[3] <= cpu_d_writedata[0];
        end
      endcase
    end
  end
end

endmodule

module barrel_shifter (
    input [7:0] DATA,
    input [2:0] SHIFT_AMOUNT,
    input SHIFT_DIRECTION,
    output [7:0] SHIFTED_DATA
);

reg [7:0] pipeline_reg [2:0];

// Pipeline stage 1
always @(*) begin
    if (SHIFT_DIRECTION == 1'b0) // Left shift
        pipeline_reg[0] = DATA << SHIFT_AMOUNT;
    else // Right shift
        pipeline_reg[0] = DATA >> SHIFT_AMOUNT;
end

// Pipeline stage 2
always @(*) begin
    pipeline_reg[1] = pipeline_reg[0];
end

// Pipeline stage 3
always @(*) begin
    pipeline_reg[2] = pipeline_reg[1];
end

assign SHIFTED_DATA = pipeline_reg[2];

endmodule

