always @(posedge clk) begin
  i_dat_r <= i_dat;
end

integer cnt;

initial begin
  cnt = 0;
end

always @(posedge clk) begin
  if (i_dat_r !== i_dat) begin
    cnt <= 0;
  end else if (cnt < 1) begin
    cnt <= cnt + 1;
