module edge_detect_duration (
  input clk,
  input rst_n,
  input a,
  output reg rise,
  output reg fall,
  output [31:0] duration
);

  reg a_prev;
  reg [31:0] rise_time;
  reg [31:0] fall_time;

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      a_prev <= 1'b0;
      rise <= 1'b0;
      fall <= 1'b0;
      duration <= 32'h0;
      rise_time <= 32'h0;
      fall_time <= 32'h0;
    end
    else begin
      if (a == 1'b1 && a_prev == 1'b0) begin
        rise <= 1'b1;
        rise_time <= $time;
      end
      else begin
        rise <= 1'b0;
      end

      if (a == 1'b0 && a_prev == 1'b1) begin
        fall <= 1'b1;
        fall_time <= $time;
      end
      else begin
        fall <= 1'b0;
      end

      if (rise_time != 32'h0 && fall_time != 32'h0) begin
        duration <= fall_time - rise_time;
      end

      a_prev <= a;
    end
  end

