module fifo_buffer (
    input clk,
    input reset,
    input [7:0] data_in,
    input wr_en,
    input rd_en,
    output reg [7:0] data_out,
    output reg fifo_full,
    output reg fifo_empty
);

// FIFO buffer memory
reg [7:0] fifo_mem [15:0];

// FIFO buffer pointers
reg [3:0] wr_ptr;
reg [3:0] rd_ptr;

// FIFO buffer status flags
wire fifo_almost_full;
wire fifo_almost_empty;

// Initialize FIFO buffer pointers
initial begin
    wr_ptr = 4'b0000;
    rd_ptr = 4'b0000;
end

// Write data to the FIFO buffer
always @(posedge clk) begin
    if (reset) begin
        wr_ptr <= 4'b0000;
        fifo_full <= 1'b0;
    end else if (wr_en) begin
        fifo_mem[wr_ptr] <= data_in;
        wr_ptr <= wr_ptr + 1;
        if (wr_ptr == 4'b1111) begin
            fifo_full <= 1'b1;
        end
    end
end

// Read data from the FIFO buffer
always @(posedge clk) begin
    if (reset) begin
        rd_ptr <= 4'b0000;
        fifo_empty <= 1'b1;
    end else if (rd_en) begin
        data_out <= fifo_mem[rd_ptr];
        rd_ptr <= rd_ptr + 1;
        if (rd_ptr == 4'b1111) begin
            fifo_empty <= 1'b1;
        end
    end
end

// FIFO buffer status logic
assign fifo_almost_full = ((wr_ptr - rd_ptr) >= 12);
assign fifo_almost_empty = ((wr_ptr - rd_ptr) <= 4);

assign fifo_full = (wr_ptr == rd_ptr) && ~fifo_empty;
assign fifo_empty = (wr_ptr == rd_ptr) && ~fifo_full;

endmodule

