module delay_line #(
    parameter DELAY = 1,
    parameter WIDTH = 1
)(
    input clk,
    input ce,
    input signed [WIDTH-1:0] in,
    output signed [WIDTH-1:0] out,
    input rst
);
    reg signed [WIDTH-1:0] buffer [0:DELAY-1];
    integer i;

    always @(posedge clk) begin
        if (rst) begin
            for (i = 0; i < DELAY; i = i + 1) begin
                buffer[i] <= 0;
            end
        end else begin
            if (ce) begin
                for (i = DELAY-1; i > 0; i = i - 1) begin
                    buffer[i] <= buffer[i-1];
                end
                buffer[0] <= in;
            end
        end
    end

    assign out = buffer[DELAY-1];
