      4'b0111: psi = 2'b10;
      4'b1000: psi = 2'b01;
      4'b1001: psi = 2'b01;
      4'b1010: psi = 2'b01;
      4'b1011: psi = 2'b01;
      4'b1100: psi = 2'b10;
      4'b1101: psi = 2'b10;
      4'b1110: psi = 2'b10;
      4'b1111: psi = 2'b10;
    endcase
  end
endfunction

// Divide input samples into two sets of equal size
wire [n/2-1:0] x1 = x[0:n/2-1];
wire [n/2-1:0] x2 = x[n/2:n-1];

// Compute Haar wavelet transform for each set of samples
wire [m/2-1:0] c1;
wire [m/2-1:0] c2;
genvar i;
generate
  for (i = 0; i < m/2; i = i+1) begin
    assign c1[i] = phi({x1[2*i+1], x1[2*i]}) + psi({x1[2*i+1], x1[2*i]});
    assign c2[i] = phi({x2[2*i+1], x2[2*i]}) + psi({x2[2*i+1], x2[2*i]});
  end
endgenerate

// Combine coefficients from two sets of samples to produce output coefficients
generate
  for (i = 0; i < m/2; i = i+1) begin
    assign c[2*i] = c1[i] + c2[i];
    assign c[2*i+1] = c1[i] - c2[i];
  end
endgenerate

endmodule

module alu (a_in, b_in, alu_function, c_alu);

   input  [31:0] a_in        ;
   input  [31:0] b_in        ;
   input  [ 3:0] alu_function;
   output [31:0] c_alu       ;

   wire [32:0] aa      ;
   wire [32:0] bb      ;
   wire [32:0] sum     ;
   wire        do_add  ;
   wire        sign_ext;

   assign do_add   = (alu_function == 4'b0001) ? 1'b1 : 1'b0 ; // alu_add
   assign sign_ext = (alu_function == 4'b0010) ? 1'b0 : 1'b1 ; // alu_less_than
   assign aa       = {(a_in[31] & sign_ext), a_in} ;
   assign bb       = {(b_in[31] & sign_ext), b_in} ;

   reg [31:0] c_alu;
   always @(*) begin
        case(alu_function)
            4'b0001 : c_alu = sum[31:0]         ; // alu_add
            4'b0010 : c_alu = {31'b0, sum[32]}  ; // alu_less_than
            4'b0100 : c_alu = a_in | b_in       ; // alu_or
            4'b0101 : c_alu = a_in & b_in       ; // alu_and
            4'b0110 : c_alu = a_in ^ b_in       ; // alu_xor
            4'b0111 : c_alu = ~(a_in | b_in)    ; // alu_nor
            default : c_alu = 32'b0             ; // alu_nothing
        endcase
    end

   assign sum = (do_add)? aa+bb : aa-bb;

endmodule

module wb_7seg_new (
    input clk_i,
    input nrst_i,
    input [24:1] wb_adr_i,
    output [15:0] wb_dat_o,
    input [15:0] wb_dat_i,
    input [1:0] wb_sel_i,
    input wb_we_i,
    input wb_stb_i,
    input wb_cyc_i,
    output wb_ack_o,
    output wb_err_o,
    output wb_int_o,
    output reg [3:0] DISP_SEL,
    output reg [6:0] DISP_LED
);

    // Register to store data
    reg [15:0] data_reg;

    // Counter to cycle through digits
    reg [6:0] disp_cnt;

    // Data to display on 7-segment display
    reg [3:0] disp_data;

    // Position of digit to display
    reg [3:0] disp_pos;

    // Instantiate 7-segment display decoder module
    disp_dec u0 (disp_data, DISP_LED);

    // Logic to read and write to data register via Wishbone bus
    always @(posedge clk_i or negedge nrst_i) begin
        if (nrst_i == 0) begin
            data_reg <= 16'hABCD;
        end else if (wb_stb_i && wb_we_i) begin
            data_reg <= wb_dat_i;
        end
    end

    // Logic to output data register value on Wishbone bus
    assign wb_ack_o = wb_stb_i;
    assign wb_err_o = 1'b0;
    assign wb_int_o = 1'b0;
    assign wb_dat_o = data_reg;

    // Logic to cycle through digits on 7-segment display
    always @(posedge clk_i or negedge nrst_i) begin
        if (nrst_i == 0) begin
            disp_cnt <= 7'b0000000;
        end else begin
            disp_cnt <= disp_cnt + 1;
        end
    end

    // Logic to select which digit to display on 7-segment display
    always @(posedge clk_i or negedge nrst_i) begin
        if (nrst_i == 0) begin
            disp_pos <= 4'b0010;
        end else if (disp_cnt == 7'b1111111) begin
            disp_pos <= {DISP_SEL[2] , DISP_SEL[1] , DISP_SEL[0] , DISP_SEL[3]};
        end
    end

    // Logic to select which data to display on 7-segment display
    always @(posedge clk_i or negedge nrst_i) begin
        if (nrst_i == 0) begin
            disp_data <= 4'b0000;
        end else begin
            case (DISP_SEL)
                4'b1000: disp_data <= data_reg[3:0];
                4'b0100: disp_data <= data_reg[7:4];
                4'b0010: disp_data <= data_reg[11:8];
                4'b0001: disp_data <= data_reg[15:12];
            endcase
        end
    end

    // Logic to update DISP_LED output with 7-segment display data
    always @(posedge clk_i or negedge nrst_i) begin
        if (nrst_i == 0) begin
            DISP_LED <= 7'b0000000;
        end else begin
            DISP_LED <= disp_data_led;
        end
    end

    // Logic to update DISP_SEL output with digit position
    always @(posedge clk_i or negedge nrst_i) begin
        if (nrst_i == 0) begin
            DISP_SEL <= 0;
        end else begin
            DISP_SEL <= disp_pos;
        end
    end

endmodule

module debouncer (
  input signal_in,
  output signal_out
);

parameter t = 10; // debounce time in milliseconds

reg [31:0] counter;
reg signal_out_reg;
wire signal_in_sync;

assign signal_in_sync = signal_in;

always @(posedge signal_in_sync) begin
  counter <= 0;
end

always @(posedge signal_in_sync) begin
  if (counter < t) begin
    counter <= counter + 1;
    signal_out_reg <= signal_out_reg;
  end else begin
    counter <= 0;
    signal_out_reg <= signal_in_sync;
  end
end

assign signal_out = signal_out_reg;

endmodule

module RegisterAdd__parameterized7
   (round_flag,
    Q_reg_0,
    r_mode_IBUF,
    sign_final_result,
    E,
    D,
    CLK,
    AR);
  output round_flag;
  output [25:0] Q_reg_0;
  input [1:0] r_mode_IBUF;
  input sign_final_result;
  input [0:0] E;
  input [25:0] D;
  input CLK;
  input [0:0] AR;

  wire [25:0] Q_reg;
  wire [26:0] sum;
  wire [0:0] round_bit;
  wire [1:0] mode;
  wire [25:0] D_rounded;
  wire [25:0] D_sign_extended;
  wire [25:0] Q_reg_sign_extended;
  wire [25:0] sum_sign_extended;
  wire [26:0] sum_sign_extended_parity;
  wire [25:0] Q_reg_rounded;
  wire [25:0] Q_reg_rounded_sign_extended;
  wire [25:0] Q_reg_rounded_sign_extended_shifted;
  wire [25:0] Q_reg_rounded_shifted;
  wire [25:0] Q_reg_rounded_shifted_sign_extended;
  wire [25:0] Q_reg_rounded_shifted_sign_extended_xor_D_sign_extended;
  wire [25:0] Q_reg_rounded_shifted_sign_extended_xor_D_sign_extended_shifted;
  wire [25:0] Q_reg_rounded_shifted_sign_extended_xor_D_sign_extended_shifted_and_Q_reg_sign_extended;
  wire [25:0] Q_reg_rounded_shifted_sign_extended_xor_D_sign_extended_shifted_and_Q_reg_sign_extended_shifted;
  wire [25:0] Q_reg_rounded_shifted_sign_extended_xor_D_sign_extended_shifted_and_Q_reg_sign_extended_shifted_xor_D_sign_extended_shifted;

  // Sign-extend D and Q_reg for rounding
  assign D_sign_extended = {sign_final_result ? {26{1'b1}} : {26{1'b0}}, D};
  assign Q_reg_sign_extended = {sign_final_result ? {26{1'b1}} : {26{1'b0}}, Q_reg};

  // Determine rounding mode
  assign mode = (r_mode_IBUF == 2'b10) ? 2'b10 :
                (r_mode_IBUF == 2'b01) ? 2'b01 :
                2'b00;

  // Perform addition
  assign sum = D_sign_extended + Q_reg_sign_extended;

  // Extract round bit
  assign round_bit = sum[24] ^ sum[23];

  // Round D to nearest even
  assign D_rounded = (mode == 2'b10) ? {D[24:0], 1'b0} :
                     (mode == 2'b01 && round_bit) ? D + 1 :
                     (mode == 2'b00 && round_bit) ? D - 1 :
                     D;

  // Sign-extend rounded Q_reg for comparison
  assign Q_reg_rounded_sign_extended = {sign_final_result ? {26{1'b1}} : {26{1'b0}}, Q_reg_rounded};

  // Sign-extend sum for comparison
  assign sum_sign_extended = {sign_final_result ? {27{1'b1}} : {27{1'b0}}, sum};

  // Compute parity of sign-extended sum
  assign sum_sign_extended_parity = ^sum_sign_extended;

  // Shift rounded Q_reg and D for comparison
  assign Q_reg_rounded_shifted = {Q_reg_rounded[23:0], 2'b0};
  assign Q_reg_rounded_shifted_sign_extended = {sign_final_result ? {26{1'b1}} : {26{1'b0}}, Q_reg_rounded_shifted};
  assign Q_reg_rounded_sign_extended_shifted = {sign_final_result ? {26{1'b1}} : {26{1'b0}}, Q_reg_rounded[24:0]};
  assign D_rounded_shifted = {D_rounded[23:0], 2'b0};
  assign D_rounded_sign_extended_shifted = {sign_final_result ? {26{1'b1}} : {26{1'b0}}, D_rounded_shifted};

  // Compare rounded Q_reg and D for rounding
  assign Q_reg_rounded_shifted_sign_extended_xor_D_sign_extended = Q_reg_rounded_shifted_sign_extended ^ D_rounded_sign_extended_shifted;
  assign Q_reg_rounded_shifted_sign_extended_xor_D_sign_extended_shifted = {Q_reg_rounded_shifted_sign_extended_xor_D_sign_extended[22:0], 2'b0};
  assign Q_reg_rounded_shifted_sign_extended_xor_D_sign_extended_shifted_and_Q_reg_sign_extended = Q_reg_rounded_shifted_sign_extended_xor_D_sign_extended_shifted & Q_reg_sign_extended;
  assign Q_reg_rounded_shifted_sign_extended_xor_D_sign_extended_shifted_and_Q_reg_sign_extended_shifted_xor_D_sign_extended_shifted = Q_reg_rounded_shifted_sign_extended_xor_D_sign_extended_shifted_and_Q_reg_sign_extended ^ D_rounded_sign_extended_shifted;
  assign round_flag = (sum_sign_extended_parity[0] ^ sum_sign_extended_parity[1]) |
                      (Q_reg_rounded_sign_extended_shifted[23] & Q_reg_rounded_sign_extended_shifted[22] & Q_reg_rounded_sign_extended_shifted_xor_D_sign_extended_shifted_and_Q_reg_sign_extended_shifted_xor_D_sign_extended_shifted[23]) |
                      (Q_reg_rounded_sign_extended_shifted[23] & ~Q_reg_rounded_sign_extended_shifted[22] & Q_reg_rounded_sign_extended_shifted_xor_D_sign_extended_shifted_and_Q_reg_sign_extended_shifted[22]) |
                      (~Q_reg_rounded_sign_extended_shifted[23] & Q_reg_rounded_sign_extended_shifted_xor_D_sign_extended_shifted_and_Q_reg_sign_extended_shifted[23]);

  // Register for Q_reg
  always @(posedge CLK) begin
    if (E) begin
      Q_reg <= 26'b0;
    end else begin
      Q_reg <= sum[25:0];
    end
  end

  // Output Q_reg
  assign Q_reg_0 = Q_reg[25:0];
endmodule

module full_adder (
  input A,
  input B,
  input C_in,
  output S,
  output C_out
);
  assign S = A ^ B ^ C_in;
  assign C_out = (A & B) | (A & C_in) | (B & C_in);
endmodule

module array_multiplier (
  input [3:0] A,
  input [3:0] B,
  output [7:0] P
);

  wire [3:0] S_0;
  wire [3:0] S_1;
  wire [3:0] S_2;
  wire [3:0] S_3;
  wire [3:0] C_0;
  wire [3:0] C_1;
  wire [3:0] C_2;
  wire [3:0] C_3;
  wire [7:0] S_out;
  wire C;

  genvar i, j;
  generate
    for (i = 0; i < 4; i = i + 1) begin : FA_I
      for (j = 0; j < 4; j = j + 1) begin : FA_J
        full_adder FA (.A(A[i]), .B(B[j]), .C_in(1'b0), .S(S_out[i + j]), .C_out(C));
      end
    end
  endgenerate

  assign P = S_out;

endmodule

module top_level (
