module uart_transceiver(
    input sys_rst,
    input sys_clk,
    input uart_rx,
    output reg uart_tx,
    input [15:0] divisor,
    output reg [7:0] rx_data,
    output reg rx_done,
    input [7:0] tx_data,
    input tx_wr,
    output reg tx_done,
    output reg tx_busy,
    output reg rx_busy
);

reg [15:0] enable16_counter;
wire enable16;
assign enable16 = (enable16_counter == 16'd0);

always @(posedge sys_clk) begin
    if(sys_rst) begin
        enable16_counter <= divisor - 16'b1;
    end else begin
        enable16_counter <= enable16_counter - 16'd1;
        if(enable16) begin
            enable16_counter <= divisor - 16'b1;
        end
    end
end

reg uart_rx1;
reg uart_rx2;

always @(posedge sys_clk) begin
    uart_rx1 <= uart_rx;
    uart_rx2 <= uart_rx1;
end

reg [3:0] rx_count16;
reg [3:0] rx_bitcount;
reg [7:0] rx_reg;

always @(posedge sys_clk) begin
    if(sys_rst) begin
        rx_done <= 1'b0;
        rx_busy <= 1'b0;
        rx_count16  <= 4'd0;
        rx_bitcount <= 4'd0;
    end else begin
        rx_done <= 1'b0;
        if(enable16) begin
            if(~rx_busy) begin
                if(~uart_rx2) begin
                    rx_busy <= 1'b1;
                    rx_count16 <= 4'd7;
                    rx_bitcount <= 4'd0;
                end
            end else begin
                rx_count16 <= rx_count16 + 4'd1;
                if(rx_count16 == 4'd0) begin
                    rx_bitcount <= rx_bitcount + 4'd1;
                    if(rx_bitcount == 4'd0) begin
                        if(uart_rx2)
                            rx_busy <= 1'b0;
                    end else if(rx_bitcount == 4'd9) begin
                        rx_busy <= 1'b0;
                        if(uart_rx2) begin
                            rx_data <= rx_reg;
                            rx_done <= 1'b1;
                        end
                    end else
                        rx_reg <= {uart_rx2, rx_reg[7:1]};
                end
            end
        end
    end
end

reg [3:0] tx_bitcount;
reg [3:0] tx_count16;
reg [7:0] tx_reg;

always @(posedge sys_clk) begin
    if(sys_rst) begin
        tx_done <= 1'b0;
        tx_busy <= 1'b0;
        uart_tx <= 1'b1;
    end else begin
        tx_done <= 1'b0;
        if(tx_wr) begin
            tx_reg <= tx_data;
            tx_bitcount <= 4'd0;
            tx_count16 <= 4'd1;
            tx_busy <= 1'b1;
            uart_tx <= 1'b0;
        end else if(enable16 && tx_busy) begin
            tx_count16  <= tx_count16 + 4'd1;
            if(tx_count16 == 4'd0) begin
                tx_bitcount <= tx_bitcount + 4'd1;
                if(tx_bitcount == 4'd8) begin
                    uart_tx <= 1'b1;
                end else if(tx_bitcount == 4'd9) begin
                    uart_tx <= 1'b1;
                    tx_busy <= 1'b0;
                    tx_done <= 1'b1;
                end else begin
                    uart_tx <= tx_reg[0];
                    tx_reg <= {1'b0, tx_reg[7:1]};
                end
            end
        end
    end
end

endmodule

module vga(

    input wire        clock,        
    input wire [7:0]  char_code,
    output reg [13:0] addr,
    output reg [4:0]  r,
    output reg [5:0]  g,
    output reg [4:0]  b,
    output reg        hs,
    output reg        vs
);

// Timing parameters
parameter H_SYNC_PULSE_WIDTH = 96;
parameter H_BACK_PORCH_WIDTH = 48;
parameter H_FRONT_PORCH_WIDTH = 16;
parameter H_ACTIVE_VIDEO_WIDTH = 640;
parameter V_SYNC_PULSE_HEIGHT = 2;
parameter V_BACK_PORCH_HEIGHT = 33;
parameter V_FRONT_PORCH_HEIGHT = 10;
parameter V_ACTIVE_VIDEO_HEIGHT = 480;

// Pixel memory
reg [15:0] pixel_memory [0:H_ACTIVE_VIDEO_WIDTH-1][0:V_ACTIVE_VIDEO_HEIGHT-1];

// Font ROM
reg [127:0] font_rom [0:255];
initial begin
    // Initialize font ROM with 8x16 pixel font
    // Each pixel is represented by 16 bits, with 5 bits for red, 6 bits for green, and 5 bits for blue
    // Font is stored in row-major order
    // White pixels are represented by 0xFFFF, green pixels are represented by 0x07E0
    // Font is stored in ASCII order
    font_rom[0] = {16'hFFFF, 16'hFFFF, 16'hFFFF, 16'hFFFF, 16'hFFFF, 16'hFFFF, 16'hFFFF, 16'hFFFF}; // Null character
    font_rom[1] = {16'h0000, 16'h0000, 16'h0000, 16'h0000, 16'h0000, 16'h0000, 16'h0000, 16'h0000}; // Start of heading
    // ...
    font_rom[65] = {16'h7E0, 16'h7E0, 16'h7E0, 16'h7E0, 16'h7E0, 16'h7E0, 16'h7E0, 16'h7E0}; // A
    // ...
end

// VGA timing signals
reg [9:0] x;
reg [9:0] y;

// Horizontal sync pulse
reg [9:0] h_sync_start = H_FRONT_PORCH_WIDTH + 1;
reg [9:0] h_sync_end = h_sync_start + H_SYNC_PULSE_WIDTH - 1;

// Back porch
reg [9:0] h_back_porch_start = h_sync_end + 1;
reg [9:0] h_back_porch_end = h_back_porch_start + H_BACK_PORCH_WIDTH - 1;

// Front porch
reg [9:0] h_front_porch_start = h_back_porch_end + 1;
reg [9:0] h_front_porch_end = h_front_porch_start + H_FRONT_PORCH_WIDTH - 1;

// Active video
reg [9:0] h_active_video_start = h_front_porch_end + 1;
reg [9:0] h_active_video_end = h_active_video_start + H_ACTIVE_VIDEO_WIDTH - 1;

// Vertical sync pulse
reg [9:0] v_sync_start = V_FRONT_PORCH_HEIGHT + 1;
reg [9:0] v_sync_end = v_sync_start + V_SYNC_PULSE_HEIGHT - 1;

// Back porch
reg [9:0] v_back_porch_start = v_sync_end + 1;
reg [9:0] v_back_porch_end = v_back_porch_start + V_BACK_PORCH_HEIGHT - 1;

// Front porch
reg [9:0] v_front_porch_start = v_back_porch_end + 1;
reg [9:0] v_front_porch_end = v_front_porch_start + V_FRONT_PORCH_HEIGHT - 1;

// Active video
reg [9:0] v_active_video_start = v_front_porch_end + 1;
reg [9:0] v_active_video_end = v_active_video_start + V_ACTIVE_VIDEO_HEIGHT - 1;

// Horizontal and vertical sync signals
wire h_sync = (x >= h_sync_start) && (x <= h_sync_end);
wire v_sync = (y >= v_sync_start) && (y <= v_sync_end);

// Pixel memory address
wire [9:0] pixel_x = x - h_active_video_start;
wire [9:0] pixel_y = y - v_active_video_start;

// Character ROM address
wire [3:0] char_x = pixel_x / 8;
wire [3:0] char_y = pixel_y / 16;
wire [7:0] char_addr = char_code * 16 + char_y;

// Pixel output
assign r = pixel_memory[pixel_x][pixel_y][15:11];
assign g = pixel_memory[pixel_x][pixel_y][10:5];
assign b = pixel_memory[pixel_x][pixel_y][4:0];

// Horizontal and vertical sync output
assign hs = h_sync;
assign vs = v_sync;

// VGA timing generator
always @(posedge clock) begin

    // Horizontal timing
    if (x == h_active_video_end) begin
        x <= 0;
        y <= (y == v_active_video_end) ? 0 : (y + 1);
    end else begin
        x <= x + 1;
    end

    // Vertical timing
    case(y)
        v_active_video_start: begin
            addr <= {char_addr[7:6], char_addr[5:0], char_x};
            pixel_memory[pixel_x][pixel_y] <= font_rom[char_code][pixel_y % 16 * 8 + char_x];
        end
        v_sync_end: begin
            addr <= 14'h0000;
            pixel_memory[pixel_x][pixel_y] <= 16'h0000;
        end
        default: begin
            addr <= 14'h0000;
            pixel_memory[pixel_x][pixel_y] <= 16'h07E0;
        end
    endcase

end

endmodule

module calculator(
    input [7:0] num1,
    input [7:0] num2,
    input [1:0] opcode,
    input enable,
    output reg [7:0] result
);

always @(*) begin
    if(enable) begin
        case(opcode)
            2'b00: result = num1 + num2;
            2'b01: result = num1 - num2;
            2'b10: result = num1 * num2;
            2'b11: result = num1 / num2;
        endcase
    end
end

endmodule

