module tri_intersect_data_array(
    reset,
    clk,
    address0,
    ce0,
    we0,
    d0,
    q0,
    address1,
    ce1,
    we1,
    d1,
    q1);

parameter DataWidth = 32'd576;
parameter AddressRange = 32'd20;
parameter AddressWidth = 32'd5;

input reset;
input clk;
input[AddressWidth - 1:0] address0;
input ce0;
input we0;
input[DataWidth - 1:0] d0;
output[DataWidth - 1:0] q0;
input[AddressWidth - 1:0] address1;
input ce1;
input we1;
input[DataWidth - 1:0] d1;
output[DataWidth - 1:0] q1;

reg [DataWidth-1:0] tri_intersect_array [0:AddressRange-1];

integer i;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        for (i = 0; i < AddressRange; i = i + 1) begin
            tri_intersect_array[i] <= 0;
        end
    end else if (ce0 && we0) begin
        tri_intersect_array[address0] <= d0;
    end else if (ce1 && we1) begin
        tri_intersect_array[address1] <= d1;
    end
end

assign q0 = tri_intersect_array[address0] & tri_intersect_array[address1];
assign q1 = tri_intersect_array[address0] & tri_intersect_array[address1];

endmodule

module softusb_tx (
    input usb_clk,
    input usb_rst,
    input [7:0] tx_data,
    input tx_valid,
    output reg tx_ready,
    output reg txp,
    output reg txm,
    output reg txoe,
    input low_speed,
    input generate_eop
);

parameter BITCLK_DIVIDER = 4;
parameter BAUDRATE = 115200;
parameter DATA_BITS = 8;
parameter STOP_BITS = 1;
parameter START_BITS = 1;

localparam BITCLK_PERIOD = 1.0 / (BAUDRATE * BITCLK_DIVIDER);
localparam DATA_PERIOD = BITCLK_PERIOD * (START_BITS + DATA_BITS + STOP_BITS);
localparam HALF_BITCLK_PERIOD = BITCLK_PERIOD / 2;

reg [3:0] bit_counter;
reg [7:0] data_bits;
reg start_bit;
reg stop_bit;
reg [1:0] state;

assign txoe = 1;

always @(posedge usb_clk) begin
    if (usb_rst) begin
        tx_ready <= 0;
        state <= 2'b00;
        bit_counter <= 0;
        data_bits <= 0;
        start_bit <= 0;
        stop_bit <= 0;
        txp <= 1;
        txm <= 0;
    end else begin
        case (state)
            2'b00: begin // idle
                if (tx_valid) begin
                    state <= 2'b01;
                end
            end
            2'b01: begin // start bit
                start_bit <= 1;
                state <= 2'b10;
            end
            2'b10: begin // data bits
                if (bit_counter < DATA_BITS) begin
                    data_bits[bit_counter] <= tx_data[bit_counter];
                    bit_counter <= bit_counter + 1;
                end else begin
                    state <= 2'b11;
                end
            end
            2'b11: begin // stop bit
                stop_bit <= 1;
                state <= 2'b00;
                bit_counter <= 0;
                data_bits <= 0;
                start_bit <= 0;
                stop_bit <= 0;
                tx_ready <= 1;
            end
        endcase
    end
end

always @(posedge usb_clk) begin
    case (state)
        2'b00: begin // idle
            txp <= 1;
            txm <= 0;
        end
        2'b01: begin // start bit
            txp <= 0;
            txm <= 1;
        end
        2'b10: begin // data bits
            if (data_bits[bit_counter]) begin
                txp <= 1;
                txm <= 0;
            end else begin
                txp <= 0;
                txm <= 1;
            end
        end
        2'b11: begin // stop bit
            txp <= 1;
            txm <= 0;
        end
    endcase
end

endmodule

module fsm_bit_sequence_detection (
  input clk,
  input reset,
  input data,
  output reg match
);

  parameter S0 = 2'b00, S1 = 2'b01, S2 = 2'b10, S3 = 2'b11;
  reg [1:0] state;
  reg [4:0] shift_reg;

  always @(posedge clk) begin
    if (reset) begin
      state <= S0;
      shift_reg <= 5'b0;
      match <= 1'b0;
    end else begin
      case (state)
        S0: begin
          if (data) begin
            shift_reg <= {shift_reg[3:0], data};
            state <= S1;
          end else begin
            shift_reg <= 5'b0;
          end
        end
        S1: begin
          if (data) begin
            shift_reg <= {shift_reg[3:0], data};
            state <= S2;
          end else begin
            shift_reg <= 5'b0;
            state <= S0;
          end
        end
        S2: begin
          if (data) begin
            shift_reg <= {shift_reg[3:0], data};
            state <= S3;
          end else begin
            shift_reg <= 5'b0;
            state <= S0;
          end
        end
        S3: begin
          if (shift_reg == 5'b10110) begin
            match <= 1'b1;
          end else begin
            match <= 1'b0;
          end
          shift_reg <= 5'b0;
          state <= S0;
        end
      endcase
    end
  end

endmodule

