module floating_point_converter #(parameter W = 32, parameter EW = 8, parameter SW = 23, parameter SWR=26, parameter EWR = 5)(
    input wire clk,
    input wire rst,
    input wire [W-1:0] data_in,
    input wire op,
    output wire [W-1:0] data_out,
    output reg ready
);

    localparam EXP_WIDTH = EW + 1;
    localparam MANT_WIDTH = W - EXP_WIDTH - 1;
    localparam BIAS = (1 << (EW - 1)) - 1;
    localparam DENORM_BIAS = 1 - BIAS;
    localparam INF_EXP = (1 << EW) - 1;
    localparam EXP_MASK = (1 << EW) - 1;
    localparam MANT_MASK = (1 << MANT_WIDTH) - 1;

    wire [W-1:0] mant_in;
    wire [EXP_WIDTH-1:0] exp_in;
    wire sign_in;
    wire exp_out;
    wire [MANT_WIDTH-1:0] mant_out;
    wire sign_out;
    wire overflow;
    wire underflow;
    wire zero;

    assign mant_in = data_in[MANT_WIDTH:1];
    assign exp_in = data_in[W-2:W-EW-1];
    assign sign_in = data_in[W-1];

    // Convert input to normalized form
    reg [MANT_WIDTH:0] mant_norm;
    reg [EXP_WIDTH:0] exp_norm;
    reg [MANT_WIDTH+1:0] mant_shift;
    reg [EXP_WIDTH:0] exp_shift;
    reg denorm;
    reg norm;
    reg [W-1:0] data_shifted;

    always @* begin
        if (exp_in == EXP_MASK && mant_in != 0) begin
            // NaN
            exp_out = EXP_MASK;
            mant_out = MANT_MASK;
            sign_out = sign_in;
            ready = 1;
        end else if (exp_in == EXP_MASK && mant_in == 0) begin
            // Infinity
            exp_out = EXP_MASK;
            mant_out = 0;
            sign_out = sign_in;
            ready = 1;
        end else if (exp_in == 0 && mant_in == 0) begin
            // Zero
            exp_out = 0;
            mant_out = 0;
            sign_out = sign_in;
            ready = 1;
        end else if (exp_in == 0 && mant_in != 0) begin
            // Denormalized number
            denorm = 1;
            norm = 0;
            exp_shift = DENORM_BIAS;
            mant_shift = {1'b1, mant_in};
        end else begin
            // Normalized number
            denorm = 0;
            norm = 1;
            exp_shift = exp_in - BIAS + DENORM_BIAS;
            mant_shift = {1'b1, mant_in};
        end

        if (op == 0) begin
            // Addition
            data_shifted = {data_in, 2'b00};
        end else if (op == 1) begin
            // Subtraction
            data_shifted = {sign_in, ~data_in + 1, 2'b00};
        end else if (op == 2) begin
            // Multiplication
            data_shifted = {sign_in ^ sign_in, mant_shift, {MANT_WIDTH{1'b0}}, exp_shift};
        end else begin
            // Division
            data_shifted = {sign_in ^ sign_in, mant_shift, {MANT_WIDTH{1'b0}}, exp_shift - DENORM_BIAS + BIAS};
        end

        if (denorm) begin
            // Denormalized number
            mant_norm = mant_shift;
            exp_norm = 0;
            ready = 1;
        end else if (norm) begin
            // Normalized number
            if (data_shifted[W-2:W-EW-1] >= INF_EXP) begin
                // Overflow
                exp_out = EXP_MASK;
                mant_out = 0;
                sign_out = sign_in;
                overflow = 1;
            end else if (data_shifted[W-2:W-EW-1] <= 0) begin
                // Underflow
                exp_out = 0;
                mant_out = 0;
                sign_out = sign_in;
                underflow = 1;
            end else begin
                // Normalized number
                mant_norm = data_shifted[MANT_WIDTH+1:MANT_WIDTH];
                exp_norm = data_shifted[W-2:W-EW-1];
                ready = 1;
            end
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            ready <= 0;
            data_out <= 0;
        end else if (ready) begin
            // Convert output to floating-point format
            if (overflow) begin
                // Overflow
                data_out = {sign_out, EXP_MASK, 0};
                overflow = 0;
            end else if (underflow) begin
                // Underflow
                data_out = {sign_out, 0, 0};
                underflow = 0;
            end else begin
                // Normalized number
                data_out = {sign_out, exp_norm, mant_norm};
            end
            ready <= 0;
        end else begin
            data_out <= 0;
        end
    end

endmodule

module soc_system_button_pio (
  // inputs:
  address,
  chipselect,
  clk,
  in_port,
  reset_n,
  write_n,
  writedata,
  // outputs:
  irq,
  readdata
);

  output irq;
  output [31:0] readdata;
  input [1:0] address;
  input chipselect;
  input clk;
  input [3:0] in_port;
  input reset_n;
  input write_n;
  input [31:0] writedata;

  wire clk_en;
  reg [3:0] d1_data_in;
  reg [3:0] d2_data_in;
  wire [3:0] data_in;
  reg [3:0] edge_capture;
  wire edge_capture_wr_strobe;
  wire [3:0] edge_detect;
  wire irq;
  reg [3:0] irq_mask;
  wire [3:0] read_mux_out;
  reg [31:0] readdata;

  assign clk_en = 1;

  assign read_mux_out = ({4 {(address == 0)}} & data_in) |
                        ({4 {(address == 2)}} & irq_mask) |
                        ({4 {(address == 3)}} & edge_capture);

  always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
      readdata <= 0;
    end else if (clk_en) begin
      readdata <= {32'b0, read_mux_out};
    end
  end

  assign data_in = in_port;

  always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
      irq_mask <= 0;
    end else if (chipselect && ~write_n && (address == 2)) begin
      irq_mask <= writedata[3:0];
    end
  end

  assign irq = |(edge_capture & irq_mask);

  assign edge_capture_wr_strobe = chipselect && ~write_n && (address == 3);

  always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
      edge_capture[0] <= 0;
    end else if (clk_en) begin
      if (edge_capture_wr_strobe && writedata[0]) begin
        edge_capture[0] <= 0;
      end else if (edge_detect[0]) begin
        edge_capture[0] <= -1;
      end
    end
  end

  always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
      edge_capture[1] <= 0;
    end else if (clk_en) begin
      if (edge_capture_wr_strobe && writedata[1]) begin
        edge_capture[1] <= 0;
      end else if (edge_detect[1]) begin
        edge_capture[1] <= -1;
      end
    end
  end

  always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
      edge_capture[2] <= 0;
    end else if (clk_en) begin
      if (edge_capture_wr_strobe && writedata[2]) begin
        edge_capture[2] <= 0;
      end else if (edge_detect[2]) begin
        edge_capture[2] <= -1;
      end
    end
  end

  always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
      edge_capture[3] <= 0;
    end else if (clk_en) begin
      if (edge_capture_wr_strobe && writedata[3]) begin
        edge_capture[3] <= 0;
      end else if (edge_detect[3]) begin
        edge_capture[3] <= -1;
      end
    end
  end

  always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
      d1_data_in <= 0;
      d2_data_in <= 0;
    end else if (clk_en) begin
      d1_data_in <= data_in;
      d2_data_in <= d1_data_in;
    end
  end

  assign edge_detect = ~d1_data_in & d2_data_in;

endmodule

module top_module(
    input wire clk,
    input wire reset,
    output reg [7:0] address,
    output reg [7:0] out_ascii,
    output reg [7:0] out_bin_msb,
    output reg [7:0] out_bin_lsb
);

reg [7:0] counter;
reg [7:0] ram [0:255];

// Generate address lines using counter
always @(posedge clk) begin
    if (reset) begin
        counter <= 0;
        address <= 0;
    end else begin
        counter <= counter + 1;
        address <= counter;
    end
end

// Store ASCII characters in RAM
always @(posedge clk) begin
    if (reset) begin
        ram <= 0;
    end else begin
        case (counter)
            0: ram <= "00110000"; // ASCII value for '0'
            1: ram <= "00110001"; // ASCII value for '1'
            2: ram <= "00110010"; // ASCII value for '2'
            // ...
            255: ram <= "11111111"; // ASCII value for 'ÿ'
        endcase
    end
end

// Convert ASCII characters to binary values
always @(posedge clk) begin
    if (reset) begin
        out_ascii <= 0;
        out_bin_msb <= 0;
        out_bin_lsb <= 0;
    end else begin
        out_ascii <= ram[address];
        out_bin_msb <= {1'b0, ram[address]};
        out_bin_lsb <= {ram[address], 1'b0};
    end
end

endmodule

