  wire clk;
  (* IBUF_LOW_PWR *) wire clk125;
  wire clk_locked;

  assign clk_locked = (counter == 0);

  always @(posedge clk125) begin
    if (counter == 0) begin
      counter <= 1;
      clk <= 1;
