module my_module (
  RST_N,
  CLK,
  BUS_WE,
  BUS_ADDR,
  BUS_WDATA,
  BUS_RDATA,
  INT_IN,
  INT_OUT
);

  parameter BUS_WIDTH = 32;

  input wire RST_N;
  input wire CLK;
  input wire BUS_WE;
  input wire [3:0] BUS_ADDR;
  input wire [BUS_WIDTH-1:0] BUS_WDATA;
  output wire [BUS_WIDTH-1:0] BUS_RDATA;
  input wire [BUS_WIDTH-1:0] INT_IN;
  output wire [BUS_WIDTH-1:0] INT_OUT;

  wire [BUS_WIDTH-1:0] plic_int_out;
  wire [BUS_WIDTH-1:0] plic_bus_rdata;
  wire plic_bus_rvalid;
  wire plic_bus_rerror;
  wire plic_bus_werror;

  fmrv32im_plic inst (
    .RST_N(RST_N),
    .CLK(CLK),
    .BUS_WE(1'b0),
    .BUS_ADDR(4'b0),
    .BUS_WDATA(32'h0),
    .BUS_RDATA(plic_bus_rdata),
    .INT_IN(INT_IN),
    .INT_OUT(plic_int_out)
  );

  assign INT_OUT = plic_int_out;

  always @(posedge CLK) begin
    if (!RST_N) begin
      BUS_RDATA <= 32'h0;
    end else if (BUS_WE) begin
      case (BUS_ADDR)
        4'b0000: begin
          // handle write to address 0
