module edge_detection (
  input               clk,
  input               rst_n,
  input               a,
  output reg          rising_edge,
  output reg          falling_edge
);

  reg a_prev;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      rising_edge <= 1'b0;
      falling_edge <= 1'b0;
      a_prev <= 1'b0;
    end else begin
      if (a && !a_prev) begin
        rising_edge <= 1'b1;
      end else begin
        rising_edge <= 1'b0;
      end

      if (!a && a_prev) begin
        falling_edge <= 1'b1;
      end else begin
        falling_edge <= 1'b0;
      end

      a_prev <= a;
    end
  end

endmodule

