module SSCG (
  input clk,
  input fmod,
  input dmod,
  output ssc
);

  reg [31:0] phase_accumulator;
  reg [31:0] phase_increment;
  reg [31:0] modulator;
  reg [31:0] modulated_frequency;
  reg [31:0] modulated_period;
  reg [31:0] counter;

  parameter PI = 32'h3243F6A9;
  parameter TWO_PI = 32'h6487ED51;
  parameter MAX_COUNTER = 32'hFFFFFFFF;

  always @(posedge clk) begin
    if (counter == MAX_COUNTER) begin
      counter <= 0;
    end else begin
      counter <= counter + 1;
    end

    phase_accumulator <= phase_accumulator + phase_increment;
    modulator <= (dmod * $sin(2 * PI * fmod * counter)) >> 16;
    modulated_frequency <= (phase_accumulator + modulator) >> 16;
    modulated_period <= TWO_PI / modulated_frequency;
    ssc <= #1 $signed($bitxor($unsigned(ssc), $unsigned(1'b1)));
  end

  always @(posedge clk) begin
    phase_increment <= $signed((2**32 * modulated_period) / $period(clk));
  end

endmodule

module edge_detect_adder(
    input clk,
    input reset,             // Synchronous active-high reset
    input [15:0] a,          // 16-bit binary input a
    input [15:0] b,          // 16-bit binary input b
    input select,            // Select input to choose between edge detect and addition
    output reg rise,         // Rising edge output
    output reg fall,         // Falling edge output
    output [31:0] sum        // 32-bit binary output from adder module
);

// Edge detection state machine
reg [1:0] state, next_state;
always @(posedge clk, posedge reset) begin
    if (reset) begin
        state <= 2'b00;
        rise <= 1'b0;
        fall <= 1'b0;
    end else begin
        state <= next_state;
        rise <= 1'b0;
        fall <= 1'b0;
        case (state)
            2'b00: if (select) next_state = 2'b01; else next_state = 2'b00;
            2'b01: if (select) next_state = 2'b10; else next_state = 2'b00;
            2'b10: if (select) next_state = 2'b11; else next_state = 2'b00;
            2'b11: if (select) next_state = 2'b11; else next_state = 2'b00;
        endcase
    end
end

// Rising and falling edge detection
always @(posedge clk, posedge reset) begin
    if (reset) begin
        rise <= 1'b0;
        fall <= 1'b0;
    end else begin
        case (state)
            2'b00: begin
                rise <= 1'b0;
                fall <= 1'b0;
            end
            2'b01: begin
                rise <= 1'b1;
                fall <= 1'b0;
            end
            2'b10: begin
                rise <= 1'b0;
                fall <= 1'b1;
            end
            2'b11: begin
                rise <= 1'b0;
                fall <= 1'b0;
            end
        endcase
    end
end

// Carry look-ahead adder
wire [15:0] c;
wire [15:0] p;
wire [15:0] g;
wire [31:0] carry;
assign c = a & b;
assign p = a ^ b;
assign g = p & c;
assign carry[0] = g[0];
genvar i;
generate
    for (i = 1; i < 16; i = i + 1) begin
        assign carry[i] = g[i] | (p[i] & carry[i-1]);
    end
endgenerate
assign sum = {carry[15], carry} + {a, b};

endmodule

