    input reset_n,
    input in_valid,
    input in_ready,
    input [31:0] in_data,
    output reg out_valid,
    output reg out_ready,
    output reg [31:0] out_data,
    output reg out_error
);

    localparam ERROR_THRESHOLD = 10;

    reg [ERROR_THRESHOLD-1:0] in_valid_count;
    reg [ERROR_THRESHOLD-1:0] in_ready_count;
    reg [ERROR_THRESHOLD-1:0] out_ready_count;

    always @(posedge clk or negedge reset_n) begin
        if (~reset_n) begin
            in_valid_count <= 'b0;
            in_ready_count <= 'b0;
            out_ready_count <= 'b0;
            out_valid <= 1'b0;
            out_ready <= 1'b0;
            out_data <= 'b0;
            out_error <= 1'b0;
        end
        else begin
            if (in_valid) begin
                in_valid_count <= {in_valid_count[ERROR_THRESHOLD-2:0], 1'b1};
                if (in_ready) begin
                    in_ready_count <= 'b0;
                    out_valid <= 1'b1;
                    if (out_ready) begin
                        out_ready_count <= 'b0;
                        out_data <= in_data;
                        out_error <= 1'b0;
                    end
                    else begin
                        out_ready_count <= {out_ready_count[ERROR_THRESHOLD-2:0], 1'b1};
                        if (out_ready_count == ERROR_THRESHOLD-1) begin
                            out_error <= 1'b1;
                        end
                    end
                end
                else begin
                    in_ready_count <= {in_ready_count[ERROR_THRESHOLD-2:0], 1'b1};
                    if (in_ready_count == ERROR_THRESHOLD-1) begin
                        out_error <= 1'b1;
                    end
                end
            end
            else begin
                in_valid_count <= 'b0;
                if (in_ready) begin
                    in_ready_count <= {in_ready_count[ERROR_THRESHOLD-2:0], 1'b1};
                    if (in_ready_count == ERROR_THRESHOLD-1) begin
                        out_error <= 1'b1;
                    end
                end
                else begin
                    in_ready_count <= 'b0;
                end
            end
            if (out_ready) begin
                out_ready_count <= 'b0;
            end
            else begin
                out_ready_count <= {out_ready_count[ERROR_THRESHOLD-2:0], 1'b1};
                if (out_ready_count == ERROR_THRESHOLD-1) begin
                    out_error <= 1'b1;
                end
            end
        end
    end

endmodule

