module checksum (
  input [n-1:0] data,
  output c
);

parameter n = 8; // number of data bits

reg [n:0] sum;
reg [n-1:0] twos_comp;

// Compute the sum of the data bits
always @(*) begin
  sum = {1'b0, data} + 1'b0;
end

// Compute the two's complement of the sum
always @(*) begin
  twos_comp = ~sum + 1'b1;
end

// Output the checksum
assign c = twos_comp[n-1];

endmodule

module checksum_checker (
  input [n-1:0] data,
  input c,
  output reg error
);

parameter n = 8; // number of data bits

reg [n:0] sum;

// Compute the sum of the data bits and the checksum
always @(*) begin
  sum = {1'b0, data} + c + 1'b0;
end

// Check whether the sum is all ones
always @(sum) begin
  if (sum == {(n+1){1'b1}}) begin
    error = 1'b0; // No error
  end else begin
    error = 1'b1; // Error detected
  end
end

endmodule

module LIFO (
  input [7:0] din,
  input wen,
  input ren,
  output [7:0] dout
);

parameter depth = 8; // number of entries in the memory block

reg [7:0] memory [0:depth-1]; // memory array
reg [2:0] top; // pointer to top of memory block

always @ (posedge clk) begin
  if (wen && !ren) begin // write operation
    memory[top] <= din;
    if (top == depth-1) begin
      top <= 0;
    end else begin
      top <= top + 1;
    end
  end else if (!wen && ren) begin // read operation
    if (top == 0) begin
      dout <= memory[top];
      memory[top] <= 0;
    end else begin
      top <= top - 1;
      dout <= memory[top];
      memory[top] <= 0;
    end
  end else if (wen && ren) begin // write and read operation
    memory[top] <= din;
    dout <= memory[top];
    if (top == depth-1) begin
      top <= 0;
    end else begin
      top <= top + 1;
    end
  end else begin // no operation
    dout <= 0;
  end
end

endmodule

