module shift_register #(
  parameter SHIFT_REG_LEN = 10
)(
  input clk,
  input rst,
  input [SHIFT_REG_LEN-1:0] mosi_data,
  input lsb,
  input go,
  input pos_edge,
  input neg_edge,
  input rx_negedge,
  input tx_negedge,
  input s_clk,
  input s_in,
  output reg tip,
  output reg last,
  output reg [SHIFT_REG_LEN-1:0] miso_data,
  output reg s_out
);

localparam MAX_CHAR = 2 ** SHIFT_REG_LEN;

reg [SHIFT_REG_LEN-1:0] data;
reg [SHIFT_REG_LEN-1:0] cnt;
wire rx_clk;
wire tx_clk;

assign last = !(|cnt);

assign rx_clk = (rx_negedge ? neg_edge : pos_edge) && (!last || s_clk);
assign tx_clk = (tx_negedge ? neg_edge : pos_edge) && !last;

always @(posedge clk) begin
  if(rst) begin
    cnt <= 0;
  end
  else begin
    if(tip) begin
      cnt <= pos_edge ? (cnt - 1) : cnt;
    end
    else begin
      cnt <= !(|len) ? {1'b1, {SHIFT_REG_LEN{1'b0}}} : len;
    end
  end
end

always @(posedge clk) begin
  if(rst) begin
    s_out <= 1'b0;
    data <= 0;
  end
  else begin
    if(tx_clk && tip) begin
      if(!lsb) begin
        s_out <= data[(MAX_CHAR - 1)];
        data <= {data[(MAX_CHAR - 2):0], 1'b1};
      end
      else begin
        s_out <= data[0];
        data <= {1'b1, data[(MAX_CHAR - 1):1]};
      end
    end
    if(!tip) begin
      data <= mosi_data;
    end
  end
end

always @(posedge clk) begin
  if(rst) begin
    miso_data <= 0;
  end
  else begin
    if(rx_clk) begin
      miso_data <= {miso_data[(MAX_CHAR - 2):0], s_in};
    end
  end
end

always @(posedge clk) begin
  if(rst) begin
    tip <= 1'b0;
  end
  else begin
    if(go && ~tip) begin
      tip <= 1'b1;
    end
    else if(tip && last && pos_edge) begin
      tip <= 1'b0;
    end
  end
end

endmodule

