  input wire [15:0] icharge,
  input wire [15:0] idischg,
  output reg [7:0] soc,
  output reg [7:0] soh);

  integer capacity;
  integer health;

  always @(*) begin
    capacity = (voltage * icharge) - (voltage * idischg);
    soc = (capacity * 100) / (16'hFFFF * 16'h0A);

