module CIC_filter (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 1; // number of input signals
parameter m = 1; // number of output signals
parameter R = 2; // decimation rate
parameter M = 2; // number of stages in the integrator
parameter N = 4; // number of samples per input cycle

wire [n-1:0] decimated_in;
wire [M-1:0] integrated_signal;
wire [m-1:0] filtered_signal;

// Decimator
decimator #(.R(R)) decim(
  .in(in),
  .out(decimated_in)
);

// Integrator
integrator #(.M(M)) integr(
  .in(decimated_in),
  .out(integrated_signal)
);

// Comb Filter
comb_filter #(.N(N)) comb(
  .in(integrated_signal),
  .out(filtered_signal)
);

assign out = filtered_signal;

endmodule

module integrator (
  input in,
  output out
);

parameter M = 2; // number of stages in the integrator

reg [M-1:0] delay_line;
reg [M-1:0] integrator_out;

always @(posedge clk) begin
  delay_line <= {delay_line[M-2:0], in};
  integrator_out <= integrator_out + delay_line;
end

assign out = integrator_out;

endmodule

module comb_filter (
  input in,
  output out
);

parameter N = 4; // number of samples per input cycle

reg [N-1:0] delay_line;
reg [N-1:0] comb_out;

always @(posedge clk) begin
  delay_line <= {delay_line[N-2:0], in};
  comb_out <= comb_out - delay_line[N-1] + delay_line[0];
end

assign out = comb_out;

endmodule

module decimator (
  input [n-1:0] in,
  output [n-1:0] out
);

parameter R = 2; // decimation rate

reg [R-1:0] counter = 0;

always @(posedge clk) begin
  if (counter == R-1) begin
    out <= in;
    counter <= 0;
  end else begin
    counter <= counter + 1;
  end
end

endmodule

