module fsm_traffic_light_control (
  input clk,
  input reset,
  input ped,
  output reg red,
  output reg green,
  output reg yellow
);

  parameter S0 = 2'b00, S1 = 2'b01, S2 = 2'b10;
  reg [1:0] state, next_state;

  localparam red_time = 4;
  localparam green_time = 6;
  localparam yellow_time = 2;

  reg [2:0] counter;

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      state <= S0;
      counter <= 0;
    end
    else begin
      state <= next_state;
      case (state)
        S0: begin
          counter <= red_time;
        end
        S1: begin
          if (ped) begin
            counter <= yellow_time;
          end
          else begin
            counter <= green_time;
          end
        end
        S2: begin
          counter <= yellow_time;
        end
        default: begin
          counter <= 0;
        end
      endcase
    end
  end

  always @(posedge clk) begin
    if (reset) begin
      red <= 1'b1;
      green <= 1'b0;
      yellow <= 1'b0;
    end
    else begin
      case (state)
        S0: begin
          red <= 1'b1;
          green <= 1'b0;
          yellow <= 1'b0;
        end
        S1: begin
          if (ped) begin
            red <= 1'b0;
            green <= 1'b0;
            yellow <= 1'b1;
          end
          else begin
            red <= 1'b0;
            green <= 1'b1;
            yellow <= 1'b0;
          end
        end
        S2: begin
          red <= 1'b0;
          green <= 1'b0;
          yellow <= 1'b1;
        end
        default: begin
          red <= 1'b0;
          green <= 1'b0;
          yellow <= 1'b0;
        end
      endcase
    end
  end

  always @(*) begin
    case (state)
      S0: begin
        next_state = S1;
      end
      S1: begin
        if (counter == 0) begin
          next_state = S2;
        end
        else begin
          next_state = S1;
        end
      end
      S2: begin
        if (counter == 0) begin
          next_state = S0;
        end
        else begin
          next_state = S2;
        end
      end
      default: begin
        next_state = S0;
      end
    endcase
  end

endmodule

module testbench;

  // Inputs
  reg A;
  reg B;
  reg C;

  // Outputs
  wire Y;

  // Clock
  reg clk;

  // Instantiate the Unit Under Test (UUT)
  OAI21X1 uut (
    .A(A),
    .B(B),
    .C(C),
    .Y(Y)
  );

  // Generate clock signal
  always #5 clk = ~clk;

  // Initialize inputs
  initial begin
    A = 0;
    B = 0;
    C = 0;
    clk = 0;
  end

  // Toggle inputs and check outputs
  always @(posedge clk) begin
    // Generate random inputs
    A = $random;
    B = $random;
    C = $random;

    // Wait a few cycles for the output to stabilize
    #10;

    // Check output against expected value
    if (Y !== ~(A & B | C)) begin
      $display("Error: Y = %b, expected %b", Y, ~(A & B | C));
      $finish;
    end
  end

  // Check timing constraints
  initial begin
    // Wait for a few cycles to warm up the simulation
    #100;

    // Check input-to-output path delays
    $setuphold_check(
      $fullskew(clk, A, 0.05, 0.05),
      $fullskew(clk, Y, 0.066, 0.066),
      $fullskew(clk, B, 0.04, 0.04),
      $fullskew(clk, Y, 0.061, 0.061),
      $fullskew(clk, C, 0.03, 0.038),
      $fullskew(clk, Y, 0.048, 0.049),
      0.01, // slack
      "input-to-output path delays failed"
    );

    // Check output-to-output path delays
    $setuphold_check(
      $fullskew(clk, Y, 0.05, 0.05),
      $fullskew(clk, Y, 0.05, 0.05),
      0.01, // slack
      "output-to-output path delays failed"
    );

    $finish;
  end

