module top_module( 
    input wire [15:0] in,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo,
    output wire xor_out );

    wire [3:0] sel;
    wire [7:0] out1, out2;

    // 2-to-4 decoders
    decoder2to4 dec1(.in(sel[1:0]), .en(~sel[2]), .out(out1));
    decoder2to4 dec2(.in(sel[3:2]), .en(sel[2]), .out(out2));

    // 4-input OR gate
    assign xor_out = out1 ^ out2;

    // Multiplexer
    assign out_hi = in[15:8] & sel;
    assign out_lo = in[7:0] & sel;

endmodule

module decoder2to4(
    input wire [1:0] in,
    input wire en,
    output reg [3:0] out );

    always @(*) begin
        if (en == 0) begin
            out = 4'b0001;
        end else begin
            case (in)
                2'b00: out = 4'b0001;
                2'b01: out = 4'b0010;
                2'b10: out = 4'b0100;
                2'b11: out = 4'b1000;
            endcase
        end
    end

endmodule

