module uart_state_machine (
  input clk,
  input rst,
  input data_in,
  output reg data_out,
  output reg tx_ready,
  output reg rx_ready
);

parameter baud_rate = 9600;
parameter data_bits = 8;
parameter parity = "none";
parameter stop_bits = 1;

reg [2:0] state;
reg [7:0] tx_data;
reg [7:0] rx_data;
reg tx_start_bit;
reg [1:0] tx_stop_bits;
reg rx_start_bit;
reg [1:0] rx_stop_bits;
reg [3:0] bit_count;
reg [2:0] parity_bit;

localparam IDLE_STATE = 3'b000;
localparam TRANSMIT_STATE = 3'b001;
localparam RECEIVE_STATE = 3'b010;
localparam RESET_STATE = 3'b011;

assign data_out = rx_data;

always @(posedge clk) begin
  if (rst) begin
    state <= RESET_STATE;
    tx_ready <= 0;
    rx_ready <= 0;
    data_out <= 0;
    tx_data <= 0;
    rx_data <= 0;
    tx_start_bit <= 0;
    tx_stop_bits <= 0;
    rx_start_bit <= 0;
    rx_stop_bits <= 0;
    bit_count <= 0;
    parity_bit <= 0;
  end else begin
    case (state)
      IDLE_STATE: begin
        tx_ready <= 1;
        rx_ready <= 0;
        if (!tx_start_bit && tx_ready && data_in) begin
          tx_data <= data_in;
          tx_start_bit <= 1;
          tx_stop_bits <= stop_bits;
          bit_count <= 0;
          parity_bit <= 0;
          state <= TRANSMIT_STATE;
        end else if (rx_start_bit && rx_ready) begin
          bit_count <= bit_count + 1;
          if (bit_count == data_bits) begin
            if (parity == "none" || (parity == "odd" && parity_bit) || (parity == "even" && !parity_bit)) begin
              state <= IDLE_STATE;
            end else begin
              state <= RECEIVE_STATE;
            end
          end else if (bit_count == data_bits + 1 && parity != "none") begin
            parity_bit <= rx_data;
          end else if (bit_count == data_bits + 1 + (parity == "none" ? 0 : 1)) begin
            rx_stop_bits <= rx_stop_bits + 1;
          end
        end
      end
      TRANSMIT_STATE: begin
        tx_ready <= 0;
        rx_ready <= 0;
        if (bit_count == 0) begin
          data_out <= 0;
        end else if (bit_count <= data_bits) begin
          data_out <= tx_data[bit_count - 1];
        end else if (bit_count == data_bits + 1 && parity != "none") begin
          data_out <= parity_bit;
        end else if (bit_count == data_bits + 1 + (parity == "none" ? 0 : 1)) begin
          data_out <= 1;
        end else if (bit_count == data_bits + 1 + (parity == "none" ? 0 : 1) + tx_stop_bits) begin
          state <= IDLE_STATE;
        end
        bit_count <= bit_count + 1;
        if (bit_count == 1) begin
          tx_start_bit <= 1;
        end else if (bit_count == data_bits + 1 && parity != "none") begin
          parity_bit <= tx_data[data_bits - 1:0] ^ parity_bit;
        end else if (bit_count == data_bits + 1 + (parity == "none" ? 0 : 1)) begin
          tx_stop_bits <= tx_stop_bits - 1;
        end else if (bit_count == data_bits + 1 + (parity == "none" ? 0 : 1) + tx_stop_bits) begin
          tx_start_bit <= 0;
        end
      end
      RECEIVE_STATE: begin
        tx_ready <= 0;
        rx_ready <= 0;
        if (bit_count == 0) begin
          rx_data <= 0;
        end else if (bit_count <= data_bits) begin
          rx_data <= {rx_data[data_bits - 2:0], data_in};
        end else if (bit_count == data_bits + 1 && parity != "none") begin
          parity_bit <= data_in;
        end else if (bit_count == data_bits + 1 + (parity == "none" ? 0 : 1)) begin
          rx_stop_bits <= rx_stop_bits + 1;
        end else if (bit_count == data_bits + 1 + (parity == "none" ? 0 : 1) + rx_stop_bits) begin
          state <= IDLE_STATE;
        end
        bit_count <= bit_count + 1;
        if (bit_count == 1) begin
          rx_start_bit <= data_in;
        end else if (bit_count == data_bits + 1 && parity != "none") begin
          parity_bit <= rx_data[data_bits - 1:0] ^ parity_bit;
        end else if (bit_count == data_bits + 1 + (parity == "none" ? 0 : 1)) begin
          rx_stop_bits <= rx_stop_bits - 1;
        end else if (bit_count == data_bits + 1 + (parity == "none" ? 0 : 1) + rx_stop_bits) begin
          rx_start_bit <= 0;
        end
      end
      RESET_STATE: begin
        tx_ready <= 0;
        rx_ready <= 0;
        data_out <= 0;
        tx_data <= 0;
        rx_data <= 0;
        tx_start_bit <= 0;
        tx_stop_bits <= 0;
        rx_start_bit <= 0;
        rx_stop_bits <= 0;
        bit_count <= 0;
        parity_bit <= 0;
        state <= IDLE_STATE;
      end
    endcase
  end
end

endmodule

module adder_subtractor_4bit (
  input [3:0] A,
  input [3:0] B,
  input SUB,
  output [3:0] SUM,
  output CARRY
);

  wire [3:0] P, G;
  wire [4:0] C;

  assign P = A ^ B;
  assign G = A & B;
  assign C[0] = SUB;

  // Brent-Kung adder
  genvar i;
  generate
    for (i = 1; i < 4; i = i + 1) begin : brent_kung
      assign C[i] = (G[i-1] & P[i]) | (C[i-1] & (G[i-1] | P[i]));
      assign G[i] = G[i-1] & G[i] & (~P[i-1] | ~C[i-1]) | P[i-1] & ~G[i] & (C[i-1] | G[i-1]);
      assign P[i] = P[i-1] & P[i] & (~G[i-1] | ~C[i-1]) | ~P[i-1] & (G[i-1] ^ C[i-1]) & (~G[i] | ~C[i-1]);
    end
  endgenerate

  assign SUM = P ^ C[3];
  assign CARRY = C[4];

endmodule

module floating_point_multiplier(
    input clk,
    input reset,
    input en_i,
    input [31:0] a_i,
    input [31:0] b_i,
    output reg v_o,
    output reg [31:0] z_o,
    output reg unimplemented_o,
    output reg invalid_o,
    output reg overflow_o,
    output reg underflow_o
);

localparam width_p = 32;
localparam ring_width_p = width_p*2;
localparam rom_addr_width_p = 32;

logic [ring_width_p-1:0] tr_data_li;
logic tr_ready_lo;

logic tr_v_lo;
logic [ring_width_p-1:0] tr_data_lo;
logic tr_yumi_li;

logic [rom_addr_width_p-1:0] rom_addr;
logic [ring_width_p+4-1:0] rom_data;

logic done_lo;

bsg_fsb_node_trace_replay #(
  .ring_width_p(ring_width_p)
  ,.rom_addr_width_p(rom_addr_width_p)
) tr (
  .clk_i(clk)
  ,.reset_i(reset)
  ,.en_i(en_i)

  ,.v_i(v_o)
  ,.data_i(tr_data_li)
  ,.ready_o(tr_ready_lo)

  ,.v_o(tr_v_lo)
  ,.data_o(tr_data_lo)
  ,.yumi_i(tr_yumi_li)

  ,.rom_addr_o(rom_addr)
  ,.rom_data_i(rom_data)

  ,.done_o(done_lo)
  ,.error_o()
);

bsg_fpu_mul #(
  .e_p(8)
  ,.m_p(23)
) dut (
  .clk_i(clk)
  ,.reset_i(reset)
  ,.en_i(tr_v_lo & tr_ready_lo)

  ,.v_i(tr_v_lo)
  ,.a_i(tr_data_lo[width_p-1:0])
  ,.b_i(tr_data_lo[2*width_p-1:width_p])
  ,.ready_o(tr_yumi_li)

  ,.v_o(v_o)
  ,.z_o(z_o)
  ,.unimplemented_o(unimplemented_o)
  ,.invalid_o(invalid_o)
  ,.overflow_o(overflow_o)
  ,.underflow_o(underflow_o)
);

assign {sub_li, a_i, b_i} = tr_data_lo;
assign tr_data_li = {
  {ring_width_p-width_p-4{1'b0}},
  unimplemented_o,
  invalid_o,
  overflow_o,
  underflow_o,
  z_o
};

assign tr_yumi_li = tr_v_lo & dut.ready_o;

bsg_fpu_trace_rom #(
  .width_p(ring_width_p+4)
  ,.addr_width_p(rom_addr_width_p)
) rom (
  .addr_i(rom_addr)
  ,.data_o(rom_data)
);

initial begin
  wait(done_lo);
  $finish;
end

endmodule

