module TrafficLight (input clk,
                     output reg red,
                     output reg yellow,
                     output reg green);

    reg [5:0] count; // counter to keep track of time
    reg [1:0] state; // state variable to keep track of traffic light state

    // initialization
    initial begin
        count = 0;
        state = 2'b10;
        red = 1'b1;
        yellow = 1'b0;
        green = 1'b0;
    end

    always @(posedge clk) begin
        // increment counter every 20ns (50 MHz clock)
        count <= count + 1;

        // state machine to control traffic light sequence
        case (state)
            2'b00: begin // red light
                if (count == 100_000_000) begin // 10 seconds
                    count <= 0;
                    state <= 2'b01;
                    red <= 1'b0;
                    yellow <= 1'b1;
                end
            end
            2'b01: begin // yellow light
                if (count == 20_000_000) begin // 2 seconds
                    count <= 0;
                    state <= 2'b10;
                    yellow <= 1'b0;
                    green <= 1'b1;
                end
            end
            2'b10: begin // green light
                if (count == 100_000_000) begin // 10 seconds
                    count <= 0;
                    state <= 2'b11;
                    green <= 1'b0;
                    yellow <= 1'b1;
                end
            end
            2'b11: begin // yellow light
                if (count == 20_000_000) begin // 2 seconds
                    count <= 0;
                    state <= 2'b00;
                    yellow <= 1'b0;
                    red <= 1'b1;
                end
            end
        endcase
    end
endmodule

module PS2_Mouse_Data_In (
    input clk,
    input reset,
    input wait_for_incoming_data,
    input start_receiving_data,
    input ps2_clk_posedge,
    input ps2_clk_negedge,
    input ps2_data,
    output reg [7:0] received_data,
    output reg received_data_en
);

// --------------------------------------------------------------------
// Constant Declarations                           
// --------------------------------------------------------------------
localparam    PS2_STATE_0_IDLE            = 3'h0,
            PS2_STATE_1_WAIT_FOR_DATA    = 3'h1,
            PS2_STATE_2_DATA_IN            = 3'h2,
            PS2_STATE_3_PARITY_IN        = 3'h3,
            PS2_STATE_4_STOP_IN            = 3'h4;

// --------------------------------------------------------------------
// Internal wires and registers Declarations                 
// --------------------------------------------------------------------
reg            [3:0]    data_count;
reg            [7:0]    data_shift_reg;

// State Machine Registers
reg            [2:0]    ns_ps2_receiver;
reg            [2:0]    s_ps2_receiver;

// --------------------------------------------------------------------
// Finite State Machine(s)                           
// --------------------------------------------------------------------
always @(posedge clk) begin
    if (reset == 1'b1) s_ps2_receiver <= PS2_STATE_0_IDLE;
    else               s_ps2_receiver <= ns_ps2_receiver;
end

always @(*) begin     // Defaults
    ns_ps2_receiver = PS2_STATE_0_IDLE;

    case (s_ps2_receiver)
    PS2_STATE_0_IDLE:
        begin
            if((wait_for_incoming_data == 1'b1) && (received_data_en == 1'b0))
                ns_ps2_receiver = PS2_STATE_1_WAIT_FOR_DATA;
            else if ((start_receiving_data == 1'b1) && (received_data_en == 1'b0))
                ns_ps2_receiver = PS2_STATE_2_DATA_IN;
            else ns_ps2_receiver = PS2_STATE_0_IDLE;
        end
    PS2_STATE_1_WAIT_FOR_DATA:
        begin
            if((ps2_data == 1'b0) && (ps2_clk_posedge == 1'b1)) 
                ns_ps2_receiver = PS2_STATE_2_DATA_IN;
            else if (wait_for_incoming_data == 1'b0)
                ns_ps2_receiver = PS2_STATE_0_IDLE;
            else
                ns_ps2_receiver = PS2_STATE_1_WAIT_FOR_DATA;
        end
    PS2_STATE_2_DATA_IN:
        begin
            if((data_count == 3'h7) && (ps2_clk_posedge == 1'b1))
                ns_ps2_receiver = PS2_STATE_3_PARITY_IN;
            else
                ns_ps2_receiver = PS2_STATE_2_DATA_IN;
        end
    PS2_STATE_3_PARITY_IN:
        begin
            if (ps2_clk_posedge == 1'b1)
                ns_ps2_receiver = PS2_STATE_4_STOP_IN;
            else
                ns_ps2_receiver = PS2_STATE_3_PARITY_IN;
        end
    PS2_STATE_4_STOP_IN:
        begin
            if (ps2_clk_posedge == 1'b1)
                ns_ps2_receiver = PS2_STATE_0_IDLE;
            else
                ns_ps2_receiver = PS2_STATE_4_STOP_IN;
        end
    default:
        begin
            ns_ps2_receiver = PS2_STATE_0_IDLE;
        end
    endcase
end

// --------------------------------------------------------------------
// Sequential logic                              
// --------------------------------------------------------------------
always @(posedge clk) begin
    if (reset == 1'b1)     data_count <= 3'h0;
    else if((s_ps2_receiver == PS2_STATE_2_DATA_IN) && (ps2_clk_posedge == 1'b1))
        data_count    <= data_count + 3'h1;
    else if(s_ps2_receiver != PS2_STATE_2_DATA_IN)
        data_count    <= 3'h0;
end

always @(posedge clk) begin
    if(reset == 1'b1)     data_shift_reg <= 8'h00;
    else if((s_ps2_receiver == PS2_STATE_2_DATA_IN) && (ps2_clk_posedge == 1'b1))
        data_shift_reg    <= {ps2_data, data_shift_reg[7:1]};
end

always @(posedge clk) begin
    if(reset == 1'b1) received_data <= 8'h00;
    else if(s_ps2_receiver == PS2_STATE_4_STOP_IN)
        received_data    <= data_shift_reg;
end

always @(posedge clk) begin
    if(reset == 1'b1) received_data_en <= 1'b0;
    else if((s_ps2_receiver == PS2_STATE_4_STOP_IN) && (ps2_clk_posedge == 1'b1))
        received_data_en    <= 1'b1;
    else
        received_data_en    <= 1'b0;
end

endmodule

