module four_bit_adder(
    input [3:0] A, B,
    input Cin,
    output [3:0] S,
    output Cout
);

    wire [3:0] sum;
    wire C0, C1, C2;

    // Full Adder
    // Inputs: A, B, Cin
    // Outputs: sum, Cout
    // Cout = (A & B) | (Cin & (A | B))
    // sum = A ^ B ^ Cin
    // C0 = A & B
    // C1 = Cin & (A | B)
    // C2 = C0 | C1
    // sum = A ^ B ^ Cin
    // Cout = C2

    // First Full Adder
    full_adder FA0(A[0], B[0], Cin, sum[0], C0);
    // Second Full Adder
    full_adder FA1(A[1], B[1], C0, sum[1], C1);
    // Third Full Adder
    full_adder FA2(A[2], B[2], C1, sum[2], C2);
    // Fourth Full Adder
    full_adder FA3(A[3], B[3], C2, sum[3], Cout);

    assign S = sum;

endmodule

module full_adder(
    input A, B, Cin,
    output sum, Cout
);

    wire C0, C1, C2;

    // Full Adder
    // Inputs: A, B, Cin
    // Outputs: sum, Cout
    // Cout = (A & B) | (Cin & (A | B))
    // sum = A ^ B ^ Cin
    // C0 = A & B
    // C1 = Cin & (A | B)
    // C2 = C0 | C1
    // sum = A ^ B ^ Cin
    // Cout = C2

    assign C0 = A & B;
    assign C1 = Cin & (A | B);
    assign C2 = C0 | C1;
    assign sum = A ^ B ^ Cin;
    assign Cout = C2;

endmodule

module combinational_circuit(
    input [99:0] in,
    output out_and,
    output out_or,
    output out_xor,
    output out
);

wire [49:0] and_inputs;
wire [49:0] or_inputs;
wire [49:0] xor_inputs;

