module top_module (
    input [2:0] sel,           // Selection input for the multiplexer
    input [3:0] data0,         // Input 0 of the multiplexer
    input [3:0] data1,         // Input 1 of the multiplexer
    input [3:0] data2,         // Input 2 of the multiplexer
    input [3:0] data3,         // Input 3 of the multiplexer
    input [3:0] data4,         // Input 4 of the multiplexer
    input [3:0] data5,         // Input 5 of the multiplexer
    input [99:0] a,            // Input A of the adder
    input [99:0] b,            // Input B of the adder
    input cin,                 // Carry-in of the adder
    output cout,               // Carry-out of the adder
    output [99:0] sum,         // Sum output of the adder
    output [99:0] final_output // Final output of the system
);

// 6-to-1 Multiplexer
wire [3:0] mux_out;
assign mux_out = (sel == 0) ? (data0 & 4'b00001111) :
                 (sel == 1) ? (data1 & 4'b00001111) :
                 (sel == 2) ? (data2 & 4'b00001111) :
                 (sel == 3) ? (data3 & 4'b00001111) :
                 (sel == 4) ? (data4 & 4'b00001111) :
                 (sel == 5) ? (data5 & 4'b00001111) : 4'b0000;

// Bitwise OR operation for odd sel values
wire [3:0] or_out;
assign or_out = (sel % 2 == 1) ? (mux_out | 4'b11110000) : mux_out;

// Carry Look-Ahead Adder
wire [99:0] adder_sum;
wire adder_cout;
cla_adder adder(.a(a), .b(b), .cin(cin), .sum(adder_sum), .cout(adder_cout));

// Functional module for XOR operation
wire [99:0] xor_out;
assign xor_out = or_out ^ adder_sum;

// Output assignments
assign sum = adder_sum;
assign cout = adder_cout;
assign final_output = xor_out;

endmodule

module vending_machine_fsm (
  input clk,
  input reset,
  input coin_inserted,
  input item_selected,
  input item_dispensed,
  output reg dispense_item,
  output reg return_change,
  output reg item_not_available,
  output reg ready_to_dispense
);

  reg state, next_state;

  localparam IDLE = 2'b00, DISPENSE = 2'b01, RETURN_CHANGE = 2'b10, ITEM_NOT_AVAILABLE = 2'b11;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      state <= IDLE;
    end else begin
      state <= next_state;
    end
  end

  always @(*) begin
    next_state = state;
    dispense_item = 0;
    return_change = 0;
    item_not_available = 0;
    ready_to_dispense = 0;

    case (state)
      IDLE: begin
        if (coin_inserted && item_selected) begin
          next_state = DISPENSE;
        end else if (item_selected) begin
          next_state = ITEM_NOT_AVAILABLE;
        end else if (coin_inserted) begin
          next_state = RETURN_CHANGE;
        end
      end
      DISPENSE: begin
        dispense_item = 1;
        next_state = IDLE;
      end
      RETURN_CHANGE: begin
        return_change = ~item_dispensed;
        next_state = IDLE;
      end
      ITEM_NOT_AVAILABLE: begin
        item_not_available = ~item_dispensed;
        ready_to_dispense = item_dispensed;
        next_state = IDLE;
      end
    endcase
  end

endmodule

