module multiplier (
    input [15:0] a,
    input [15:0] b,
    input [1:0] ctrl,
    output [31:0] result
);

reg [31:0] prod;
reg [31:0] sum;
reg [4:0] count;
reg [15:0] a_reg;
reg [15:0] b_reg;
reg [1:0] ctrl_reg;
reg [1:0] ctrl_next;

always @(*) begin
    a_reg = a;
    b_reg = b;
    ctrl_reg = ctrl;
end

always @(posedge clk) begin
    if (reset) begin
        count <= 0;
        prod <= 0;
        sum <= 0;
        ctrl_next <= 0;
    end else begin
        count <= count + 1;
        ctrl_next <= ctrl_reg;
        if (count == 1) begin
            prod <= {a_reg, 16'b0};
        end else if (count == 3) begin
            prod <= {b_reg, 16'b0};
        end else if (count == 5) begin
            prod <= {a_reg, 16'b0};
        end else if (count == 7) begin
            if (ctrl_reg == 2'b00) begin
                sum <= prod[31:16] + prod[15:0];
            end else begin
                sum <= prod;
            end
        end else if (count == 9) begin
            if (ctrl_reg == 2'b00) begin
                sum <= sum[31:16] + sum[15:0];
            end
        end
    end
end

assign result = (ctrl_reg == 2'b00) ? sum[31:16] : sum;

endmodule

