    //write side address counter
    always @(posedge wr_clk, negedge wr_nreset) begin
        if(~wr_nreset) begin
            wr_addr <= 0;
            wr_addr_ahead <= 0;
        end else if(~prog_full && wr_en) begin
            wr_addr <= wr_addr + 1;
            wr_addr_ahead <= wr_addr + PROG_FULL;
        end
    end

    //convert to gray code
    assign wr_addr_gray = wr_addr ^ (wr_addr >> 1);
    assign rd_addr_gray = rd_addr ^ (rd_addr >> 1);

    //synchronize to read clock
    always @(posedge rd_clk, negedge rd_nreset) begin
        if(~rd_nreset) begin
            rd_addr_gray_sync <= 0;
        end else begin
            rd_addr_gray_sync <= rd_addr_gray;
        end
    end

    //synchronize to write clock
    always @(posedge wr_clk, negedge wr_nreset) begin
        if(~wr_nreset) begin
            wr_addr_gray_sync <= 0;
        end else begin
            wr_addr_gray_sync <= wr_addr_gray;
        end
    end

    //convert back to binary
    assign rd_addr_sync = rd_addr_gray_sync ^ (rd_addr_gray_sync >> 1);
    assign wr_addr_sync = wr_addr_gray_sync ^ (wr_addr_gray_sync >> 1);

    //dual ported memory
    dual_port_memory #(.DW(DW), .DEPTH(DEPTH)) mem (
        .wr_clk(wr_clk),
        .wr_en(wr_en),
        .wr_wem({(DW){1'b1}}),
        .wr_addr(wr_addr_sync[(log2(DEPTH)-1):0]),
        .wr_din(din),
        .rd_clk(rd_clk),
        .rd_en(rd_en),
        .rd_addr(rd_addr_sync[(log2(DEPTH)-1):0]),
        .rd_dout(dout)
    );

    //empty and full indicators
    assign empty = (rd_count == 0);
    assign full = (wr_count == DEPTH);
    assign prog_full = (wr_addr_ahead[(log2(DEPTH)-1):0] == rd_addr_sync[(log2(DEPTH)-1):0]) && (wr_addr_ahead[(log2(DEPTH))] != rd_addr_sync[(log2(DEPTH))]);

    //reset synchronizers
    oh_rsync wr_rsync (
        .nrst_out(wr_nreset),
        .clk(wr_clk),
        .nrst_in(nreset)
    );

    oh_rsync rd_rsync (
        .nrst_out(rd_nreset),
        .clk(rd_clk),
        .nrst_in(nreset)
    );

endmodule

module dual_port_memory #(parameter DW = 8, parameter DEPTH = 32)(
    input wr_clk,
    input wr_en,
    input [DW-1:0] wr_wem,
    input [(log2(DEPTH)-1):0] wr_addr,
    input [DW-1:0] wr_din,
    input rd_clk,
    input rd_en,
    input [(log2(DEPTH)-1):0] rd_addr,
    output reg [DW-1:0] rd_dout
);

    reg [DW-1:0] mem [0:DEPTH-1];

    always @(posedge wr_clk) begin
        if(wr_en) begin
            mem[wr_addr] <= wr_din;
            mem[wr_addr] <= wr_wem;
        end
    end

    always @(posedge rd_clk) begin
        if(rd_en) begin
            rd_dout <= mem[rd_addr];
        end
    end

endmodule

module top_module(
    input clk,
    input reset,  // sync active-high reset
    input load,
    input ena,
    input [3:0] data_in,
    output [3:0] data_out);

    reg [3:0] shift_reg;
    wire [1:0] select;
    wire [3:0] shifted_data;

    // 2-to-4 decoder
    assign select[0] = ~shift_reg[3] & ~shift_reg[2];
    assign select[1] = ~shift_reg[3] & shift_reg[2];

    // 4-bit shift register
    always @(posedge clk) begin
        if (reset) begin
            shift_reg <= 4'b0;
        end else if (load) begin
            shift_reg <= data_in;
        end else if (ena) begin
            shift_reg <= {shift_reg[2:0], shift_reg[3]};
        end
    end

    // 2-to-1 multiplexer
    assign shifted_data = {shift_reg[1:0], 2'b0};
    assign data_out = load ? data_in : (select[1] ? shifted_data : shift_reg);

endmodule

module edge_detector (
    input clk,
    input [7:0] in,
    output reg [7:0] out
);

reg [1:0] state;
reg [7:0] prev_in;

always @(posedge clk) begin
    case (state)
        2'b00: begin
            if (in > prev_in) begin
                out <= 8'b00000001;
                state <= 2'b01;
            end else if (in < prev_in) begin
                out <= 8'b00000010;
                state <= 2'b01;
            end else begin
                out <= 8'b00000000;
                state <= 2'b00;
            end
        end
        2'b01: begin
            out <= 8'b00000000;
            state <= 2'b00;
        end
    endcase
    prev_in <= in;
end

endmodule

module mux (
    input [5:0] sel,
    input [1:0] data0,
    input [1:0] data1,
    input [1:0] data2,
    input [1:0] data3,
    input [1:0] data4,
    input [1:0] data5,
    output reg [3:0] out
);

always @(*) begin
    case (sel)
        6'b000000: out <= data0;
        6'b000001: out <= data1;
        6'b000010: out <= data2;
        6'b000011: out <= data3;
        6'b000100: out <= data4;
        6'b000101: out <= data5;
        default: out <= 4'b0000;
    endcase
end

endmodule

module control_module (
