always @(anyedge, mux_out) begin
    if (anyedge != 8'b00000000) begin
        mux_sel <= anyedge[3:0];
        out <= mux_out;
    end else begin
        mux_sel <= 6'b000000;
        out <= 4'b0000;
    end
end

