module gray_converter (
  input [n-1:0] bin,
  output [n-1:0] gray
);

parameter n = 4; // number of bits in the binary and gray code

assign gray[n-1] = bin[n-1];
genvar i;
generate
  for (i = 0; i < n-1; i=i+1) begin
    assign gray[i] = bin[i] ^ bin[i+1];
  end
endgenerate

endmodule

module binary_converter (
  input [n-1:0] gray,
  output [n-1:0] bin
);

parameter n = 4; // number of bits in the binary and gray code

assign bin[n-1] = gray[n-1];
genvar i;
generate
  for (i = n-2; i >= 0; i=i-1) begin
    assign bin[i] = gray[i] ^ bin[i+1];
  end
endgenerate

endmodule

module binary_search(clk, reset, array, array_size, target, index);
