input [31:0] target;
input [31:0] array_size;
output reg [31:0] index;

reg [31:0] low, high, mid;

always @(posedge clk, posedge reset) begin
    if (reset) begin
        low <= 0;
        high <= array_size - 1;
        index <= -1;
    end
    else begin
        if (low <= high) begin
            mid <= (low + high) / 2;
            if (array[mid] == target) begin
                index <= mid;
                low <= mid + 1;
            end
            else if (array[mid] > target) begin
                high <= mid - 1;
            end
            else begin
                low <= mid + 1;
            end
        end
    end
end

endmodule

