module adders (
  input a,
  input b,
  input c,
  output s,
  output carry
);

  // Half Adder
  wire ha_s;
  wire ha_carry;
  half_adder ha_inst (
    .a(a),
    .b(b),
    .s(ha_s),
    .carry(ha_carry)
  );

  // Full Adder
  wire fa_s;
  wire fa_carry;
  full_adder fa_inst (
    .a(a),
    .b(b),
    .c(c),
    .s(fa_s),
    .carry(fa_carry)
  );

  // Output
  assign s = fa_s;
  assign carry = ha_carry | fa_carry;

