// Half Adder
module half_adder (
  input a,
  input b,
  output s,
  output carry
);

  assign s = a ^ b;
  assign carry = a & b;

endmodule

// Full Adder
module full_adder (
  input a,
  input b,
  input c,
  output s,
  output carry
);

  wire fa_carry1;
  wire fa_carry2;

  assign fa_carry1 = a & b;
  assign fa_carry2 = a | b;

  assign s = a ^ b ^ c;
  assign carry = fa_carry1 | (fa_carry2 & c);

endmodule

