generate
    for (i = 0; i < 32; i = i + 1) begin : gen_adder
        full_adder fa(
            .a(a[i]),
            .b(b[i]),
            .cin(carry[i]),
            .sum(sum1[i]),
            .cout(carry[i+1])
        );
