module feedforward_nn (
  input [1:0] x,
  input clk,
  input rst,
  output reg y
);

parameter DWIDTH = 32;
parameter AWIDTH = 2;
parameter MEM_SIZE = 16;

wire [3:0] h;
wire [3:0] w1;
wire [3:0] w2;

ram #(
  .DWIDTH(DWIDTH),
  .AWIDTH(AWIDTH),
  .MEM_SIZE(MEM_SIZE)
) ram_inst (
  .addr(ram_addr),
  .ce(ram_ce),
  .d(ram_d),
  .we(ram_we),
  .q(ram_q)
);

reg [AWIDTH-1:0] ram_addr;
reg ram_ce;
reg [DWIDTH-1:0] ram_d;
reg ram_we;
wire [DWIDTH-1:0] ram_q;

reg [3:0] i;

assign h[0] = 1'b1;
assign h[1] = 1'b1;
assign h[2] = 1'b1;
assign h[3] = 1'b1;

always @(posedge clk) begin
  if (rst) begin
    y <= 0;
  end else begin
    ram_addr <= 2'd0;
    ram_ce <= 1'b1;
    ram_we <= 1'b0;
    ram_d <= 0;
    for (i = 0; i < 4; i = i + 1) begin
      ram_ce <= 1'b0;
      w1[i] <= ram_q;
      ram_addr <= ram_addr + 1;
      ram_ce <= 1'b1;
    end
    for (i = 0; i < 4; i = i + 1) begin
      ram_ce <= 1'b0;
      w2[i] <= ram_q;
      ram_addr <= ram_addr + 1;
      ram_ce <= 1'b1;
    end
    for (i = 0; i < 4; i = i + 1) begin
      h[i] <= $exp((w1[i]*x[0] + w1[i+4]*x[1]) >> 8) / ($exp((w1[i]*x[0] + w1[i+4]*x[1]) >> 8) + 1'b0);
    end
    y <= $exp((w2[0]*h[0] + w2[1]*h[1] + w2[2]*h[2] + w2[3]*h[3]) >> 8) / ($exp((w2[0]*h[0] + w2[1]*h[1] + w2[2]*h[2] + w2[3]*h[3]) >> 8) + 1'b0);
  end
end

endmodule

