module nodeRouter(
  input clk,
  input rst,
  input [143:0] port0_ci,
  input [143:0] port1_ci,
  input [143:0] portl0_ci,
  input [143:0] portl1_ci,
  output reg [143:0] port0_co,
  output reg [143:0] port1_co,
  output reg [143:0] portl0_co,
  output reg [143:0] portl1_co,
  output reg portl0_ack,
  output reg portl1_ack
);

  // declare internal state variables
  reg [143:0] portl0_ci_reg;
  reg [143:0] portl1_ci_reg;
  reg [1:0] portl0_state;
  reg [1:0] portl1_state;

  // initialize internal state variables
  initial begin
    portl0_ci_reg = 144'h0;
    portl1_ci_reg = 144'h0;
    portl0_state = 2'b00;
    portl1_state = 2'b00;
  end

  // process input flits
  always @(posedge clk) begin
    if (rst) begin
      port0_co <= 144'h0;
      port1_co <= 144'h0;
      portl0_co <= 144'h0;
      portl1_co <= 144'h0;
      portl0_ack <= 1'b0;
      portl1_ack <= 1'b0;
      portl0_ci_reg <= 144'h0;
      portl1_ci_reg <= 144'h0;
      portl0_state <= 2'b00;
      portl1_state <= 2'b00;
    end else begin
      // process port0 input
      if (port0_ci[15:8] == 8'h00) begin
        port0_co <= port0_ci;
      end

      // process port1 input
      if (port1_ci[15:8] == 8'h01) begin
        port1_co <= port1_ci;
      end

      // process portl0 input
      case (portl0_state)
        // idle state
        2'b00: begin
          if (portl0_ci[15:8] == 8'h02) begin
            portl0_ci_reg <= portl0_ci;
            portl0_state <= 2'b01;
          end
        end

        // waiting for ack state
        2'b01: begin
          if (!portl0_ack) begin
            portl0_state <= 2'b00;
          end
        end
      endcase

      // process portl1 input
      case (portl1_state)
        // idle state
        2'b00: begin
          if (portl1_ci[15:8] == 8'h03) begin
            portl1_ci_reg <= portl1_ci;
            portl1_state <= 2'b01;
          end
        end

        // waiting for ack state
        2'b01: begin
          if (!portl1_ack) begin
            portl1_state <= 2'b00;
          end
        end
      endcase

      // process portl0 output
      if (portl0_state == 2'b00 && portl1_state == 2'b00) begin
        portl0_co <= portl0_ci_reg;
        portl0_ack <= 1'b1;
      end

      // process portl1 output
      if (portl0_state == 2'b00 && portl1_state == 2'b00) begin
        portl1_co <= portl1_ci_reg;
        portl1_ack <= 1'b1;
      end
    end
  end

endmodule

