module CDR(
  input data_in,
  input reset,
  input enable,
  output clk_out,
  output locked
);

  // Internal signals
  reg data_prev;
  reg data_curr;
  reg data_next;
  reg clk_out_prev;
  reg clk_out_curr;
  reg clk_out_next;
  reg locked_curr;
  reg locked_next;
  reg [7:0] phase_accumulator;

  // Constants
  parameter CLK_PERIOD = 10; // Clock period in ns
  parameter PHASE_STEP = 1; // Phase step in degrees
  parameter PHASE_MAX = 360; // Maximum phase in degrees

  // Detect transitions in the incoming data stream
  always @(posedge enable or posedge reset) begin
    if (reset) begin
      data_prev <= 1'b0;
      data_curr <= 1'b0;
      data_next <= 1'b0;
    end else begin
      data_prev <= data_curr;
      data_curr <= data_next;
      data_next <= data_in;
    end
  end

  // Generate a clock signal that is synchronized with the data stream
  always @(posedge enable or posedge reset) begin
    if (reset) begin
      clk_out_prev <= 1'b0;
      clk_out_curr <= 1'b0;
      clk_out_next <= 1'b0;
    end else begin
      clk_out_prev <= clk_out_curr;
      clk_out_curr <= clk_out_next;
      if (data_prev == 1'b0 && data_curr == 1'b1) begin
        clk_out_next <= 1'b1;
      end else if (data_prev == 1'b1 && data_curr == 1'b0) begin
        clk_out_next <= 1'b0;
      end
    end
  end

  // Use a phase-locked loop (PLL) to adjust the phase of the clock signal
  always @(posedge clk_out_curr or posedge reset) begin
    if (reset) begin
      phase_accumulator <= 0;
      locked_curr <= 1'b0;
      locked_next <= 1'b0;
    end else begin
      phase_accumulator <= phase_accumulator + PHASE_STEP;
      if (phase_accumulator >= PHASE_MAX) begin
        phase_accumulator <= phase_accumulator - PHASE_MAX;
        locked_next <= 1'b1;
      end else begin
        locked_next <= 1'b0;
      end
    end
  end

  // Output the recovered clock signal and a signal that indicates whether the CDR block has locked onto the incoming data stream
  assign clk_out = clk_out_curr;
  always @(posedge enable or posedge reset) begin
    if (reset) begin
      locked_curr <= 1'b0;
    end else begin
      locked_curr <= locked_next;
    end
  end
  assign locked = locked_curr;

endmodule

