module RegisterAdd__parameterized1
   (D,
    Q,
    Q_reg,
    CLK,
    AR);

  parameter WIDTH = 31;

  output [WIDTH-1:0] Q;
  input [WIDTH-1:0] Q_reg;
  input [1:0] D;
  input CLK;
  input AR;

  wire [WIDTH-1:0] Q_next;
  wire [WIDTH-1:0] Q_reset;
  wire [WIDTH-1:0] Q_add;

  assign Q_reset = 0;
  assign Q_add = Q + {1'b0, D};

  always @(posedge CLK or negedge AR) begin
    if (!AR) begin
      Q_next <= Q_reset;
    end else begin
      Q_next <= Q_add;
    end
  end

  assign Q = Q_next;

  generate
    genvar i;
    for (i = 0; i < WIDTH; i = i + 1) begin : reg_block
      if (Q_reg[i] == 1) begin
        FDCE #(
          .INIT(1'b0))
          reg_block (
            .C(CLK),
            .CE(1'b1),
            .CLR(AR),
            .D(Q[i]),
            .Q(Q_reg[i])
          );
      end
    end
  endgenerate

endmodule

module wb_abrg (
    input sys_rst,

    // Wishbone slave interface
    input             wbs_clk_i,
    input      [19:1] wbs_adr_i,
    input      [15:0] wbs_dat_i,
    output reg [15:0] wbs_dat_o,
    input      [ 1:0] wbs_sel_i,
    input             wbs_tga_i,
    input             wbs_stb_i,
    input             wbs_cyc_i,
    input             wbs_we_i,
    output            wbs_ack_o,

    // Wishbone master interface
    input             wbm_clk_i,
    output reg [19:1] wbm_adr_o,
    output reg [15:0] wbm_dat_o,
    input      [15:0] wbm_dat_i,
    output reg [ 1:0] wbm_sel_o,
    output reg        wbm_tga_o,
    output            wbm_stb_o,
    output            wbm_cyc_o,
    output reg        wbm_we_o,
    input             wbm_ack_i
  );

  // Registers and nets
  wire       wbs_stb;
  wire       init_tr;
  reg        wbm_stb;
  reg  [2:0] sync_stb;
  reg  [2:0] sync_ack;
  reg        ft_stb;
  reg        ft_ack;
  reg        stb_r;
  reg        ack_r;

  reg [19:1] wbm_adr_o_r;
  reg [15:0] wbm_dat_o_r;
  reg [ 1:0] wbm_sel_o_r;
  reg        wbm_tga_o_r;
  reg        wbm_we_o_r;
  reg [15:0] wbs_dat_o_r;
  reg [15:0] wbm_dat_i_r;

  // Continous assignments
  assign wbs_stb = wbs_stb_i & wbs_cyc_i;

  // recreate the flag from the level change
  assign wbs_ack_o = (sync_ack[2] ^ sync_ack[1]);
  assign wbm_stb_o = wbm_stb;
  assign wbm_cyc_o = wbm_stb;

  /*
   * A new wishbone transaction is issued:
   * . by changing stb from 0 to 1
   * . by continue asserting stb after ack is received
   */
  assign init_tr = ~stb_r & wbs_stb | ack_r & ~wbs_ack_o & wbs_stb;

  // Behaviour
  // wbm_stb
  always @(posedge wbm_clk_i)
    wbm_stb <= sys_rst ? 1'b0
      : (wbm_stb ? ~wbm_ack_i : sync_stb[2] ^ sync_stb[1]);

  // old stb and ack state
  always @(posedge wbs_clk_i) stb_r <= wbs_stb;
  always @(posedge wbs_clk_i) ack_r <= wbs_ack_o;

  always @(posedge wbs_clk_i)
    ft_stb <= sys_rst ? 1'b0 : (init_tr ? ~ft_stb : ft_stb);

  // synchronize the last level change
  always @(posedge wbm_clk_i)
    sync_stb <= sys_rst ? 3'h0 : {sync_stb[1:0], ft_stb};

  // this changes level when a flag is seen
  always @(posedge wbm_clk_i)
    ft_ack <= sys_rst ? 1'b0 : (wbm_ack_i ? ~ft_ack : ft_ack);

  // which can then be synched to wbs_clk_i
  always @(posedge wbs_clk_i)
    sync_ack <= sys_rst ? 3'h0 : {sync_ack[1:0], ft_ack};

  // rest of the wishbone signals
  always @(posedge wbm_clk_i)
    {wbm_adr_o, wbm_adr_o_r} <= {wbm_adr_o_r, wbs_adr_i};

  always @(posedge wbm_clk_i)
    {wbm_dat_o, wbm_dat_o_r} <= {wbm_dat_o_r, wbs_dat_i};

  always @(posedge wbm_clk_i)
    {wbm_sel_o, wbm_sel_o_r} <= {wbm_sel_o_r, wbs_sel_i};

  always @(posedge wbm_clk_i)
    {wbm_we_o, wbm_we_o_r} <= {wbm_we_o_r, wbs_we_i};

  always @(posedge wbm_clk_i)
    {wbm_tga_o, wbm_tga_o_r} <= {wbm_tga_o_r, wbs_tga_i};

  /*
   * Register input coming from the slave as that can change
   * after the ack is received
   */
  always @(posedge wbm_clk_i)
    wbm_dat_i_r <= wbm_ack_i ? wbm_dat_i : wbm_dat_i_r;

  always @(posedge wbs_clk_i)
    {wbs_dat_o, wbs_dat_o_r} <= {wbs_dat_o_r, wbm_dat_i_r};

endmodule

module top_module( 
    input [255:0] in,
    input [7:0] sel,
    input clk,
    input reset,
    output [7:0] q ); 

    // Priority Encoder
    wire [7:0] encoded_sel;
    priority_encoder pe(
        .in(sel),
        .out(encoded_sel)
    );

    // Decoder
    wire [255:0] decoded_in;
    decoder dec(
        .in(in),
        .sel(encoded_sel),
        .out(decoded_in)
    );

    // Multiplexer
    wire [7:0] mux_out;
    mux_256_1 mux(
        .in(decoded_in),
        .sel(encoded_sel),
        .out(mux_out)
    );

    // Counter
    reg [3:0] counter;
    always @(posedge clk) begin
        if (reset) begin
            counter <= 4'b0000;
        end else begin
            counter <= counter + 1;
        end
    end

    // Functional Module
    wire [7:0] sum;
    adder add(
        .a(mux_out),
        .b(counter),
        .sum(sum)
    );

    assign q = sum;

endmodule

// Priority Encoder
module priority_encoder(
    input [7:0] in,
    output [7:0] out
);
    assign out = ~(in - 1);
endmodule

