module uart_receiver (
  input clk,
  input rst_n,
  input rx,
  output reg clear_to_send_out,
  output reg [7:0] rx_byte_out,
  output reg rx_byte_valid_out,
  output reg rx_byte_done
);

  // Constants
  localparam BAUD_RATE = 9600;
  localparam CLOCK_FREQ = 50000000; // Assume 50 MHz clock

  // Internal signals
  reg [2:0] state;
  reg [7:0] data_bits;
  reg [3:0] bit_count;
  reg sample;
  reg sample_count;
  reg rx_byte_valid_next;

  // Calculate the number of clock cycles per bit
  localparam CYCLES_PER_BIT = CLOCK_FREQ / BAUD_RATE;

  // State machine states
  localparam IDLE = 3'b000;
  localparam START_BIT = 3'b001;
  localparam DATA_BITS = 3'b010;
  localparam STOP_BIT = 3'b011;

  always @(posedge clk) begin
    if (!rst_n) begin
      state <= IDLE;
      clear_to_send_out <= 1;
      bit_count <= 0;
      sample_count <= 0;
      rx_byte_done <= 0;
      rx_byte_valid_out <= 0;
      rx_byte_valid_next <= 0;
    end
    else begin
      case (state)
        IDLE: begin
          if (!rx) begin
            state <= START_BIT;
            bit_count <= 0;
            sample_count <= 0;
            data_bits <= 0;
            clear_to_send_out <= 0;
          end
        end
        START_BIT: begin
          if (sample_count >= CYCLES_PER_BIT) begin
            sample_count <= 0;
            bit_count <= bit_count + 1;
            data_bits[bit_count] <= sample;
            if (bit_count == 7) begin
              state <= STOP_BIT;
            end
            else begin
              state <= DATA_BITS;
            end
          end
          else begin
            sample_count <= sample_count + 1;
            sample <= rx;
          end
        end
        DATA_BITS: begin
          if (sample_count >= CYCLES_PER_BIT) begin
            sample_count <= 0;
            bit_count <= bit_count + 1;
            data_bits[bit_count] <= sample;
            if (bit_count == 7) begin
              state <= STOP_BIT;
            end
          end
          else begin
            sample_count <= sample_count + 1;
            sample <= rx;
          end
        end
        STOP_BIT: begin
          if (sample_count >= CYCLES_PER_BIT) begin
            sample_count <= 0;
            if (rx) begin
              rx_byte_out <= data_bits;
              rx_byte_valid_next <= 1;
            end
            state <= IDLE;
            clear_to_send_out <= 1;
            rx_byte_done <= 1;
          end
          else begin
            sample_count <= sample_count + 1;
          end
        end
        default: begin
          state <= IDLE;
          clear_to_send_out <= 1;
          bit_count <= 0;
          sample_count <= 0;
          rx_byte_valid_out <= 0;
          rx_byte_valid_next <= 0;
          rx_byte_done <= 0;
        end
      endcase
    end
  end

  always @(posedge clk) begin
    if (!rst_n) begin
      rx_byte_valid_out <= 0;
    end
    else begin
      rx_byte_valid_out <= rx_byte_valid_next;
    end
  end

endmodule

module top_module(
  input wire [15:0] in1,
  input wire [15:0] in2,
  input wire control,
  output wire [15:0] out
);

  wire [15:0] sum;
  wire [15:0] diff;
  wire cmp;

  adder add_inst(
    .a(in1),
    .b(in2),
    .sum(sum)
  );

  subtractor sub_inst(
    .a(in1),
    .b(in2),
    .diff(diff)
  );

  comparator cmp_inst(
    .a(in1),
    .b(in2),
    .cmp(cmp)
  );

  assign out = control ? {16'b0, cmp} : {16'b0, control ? diff : sum};

endmodule

