module tb_t;

   // Inputs
   reg clk;

   // Instantiate the Unit Under Test (UUT)
   t uut (
      .clk(clk)
   );

   initial begin
      // Initialize Inputs
      clk = 0;

      // Wait 100 clock cycles
      #100;

      // Check final values of crc and sum
      if (uut.crc !== 8'b01110000) $error("*-* ERROR: Incorrect final value of crc\n");
      if (uut.sum !== 224'h1fdff998855c3c38d467e28124847831f9ad6d4a09f2801098f032a8) $error("*-* ERROR: Incorrect final value of sum\n");

      $display("*-* All Finished *-*");
      $finish;
   end

   always #5 clk = ~clk;

endmodule

module t (/*AUTOARG*/
   // Inputs
   clk
   );

   input clk;
   integer cyc; initial cyc = 0;
   reg [7:0] crc;
   reg [223:0] sum;

   wire [255:0] mglehy = {32{~crc}};
   wire [215:0] drricx = {27{crc}};
   wire [15:0]  apqrli = {2{~crc}};
   wire [2:0]   szlfpf = crc[2:0];
   wire [15:0]  dzosui = {2{crc}};
   wire [31:0]  zndrba = {16{crc[1:0]}};
   wire [223:0] bxiouf;

   vliw vliw (
      // Outputs
      .bxiouf (bxiouf),
      // Inputs
      .mglehy  (mglehy[255:0]),
      .drricx  (drricx[215:0]),
      .apqrli  (apqrli[15:0]),
      .szlfpf  (szlfpf[2:0]),
      .dzosui  (dzosui[15:0]),
      .zndrba  (zndrba[31:0]));

   always @ (posedge clk) begin
      cyc <= cyc + 1;
      crc <= {crc[6:0], ~^ {crc[7],crc[5],crc[4],crc[3]}};
      if (cyc==0) begin
         // Setup
         crc <= 8'hed;
         sum <= 224'h0;
      end
      else if (cyc<90) begin
         //$write("[%0t] cyc==%0d BXI=%x\n", $time, cyc, bxiouf);
         sum <= {sum[222:0],sum[223]} ^ bxiouf;
      end
      else if (cyc==99) begin
         $write("[%0t] cyc==%0d crc=%b %x\n", $time, cyc, crc, sum);
         if (crc !== 8'b01110000) $stop;
         if (sum !== 224'h1fdff998855c3c38d467e28124847831f9ad6d4a09f2801098f032a8) $stop;
         $write("*-* All Finished *-*\n");
         $finish;
      end
   end

endmodule

