module alu(
    input [31:0] A, B, 
    input [2:0] F, 
    output reg [31:0] Y, 
    output reg Zero
);

always @*
begin
    case(F)
        3'b000: Y <= A & B;
        3'b001: Y <= A | B;
        3'b010: Y <= A + B;
        3'b011: Y <= A & ~B;
        3'b101: Y <= A + ~B;
        3'b110: Y <= A - B;
        3'b111: Y <= (A < B) ? 1 : 0;
        default: Y <= 0;
    endcase
    Zero <= (Y == 0) ? 1 : 0;
end

endmodule

module adder (
  input [7:0] A,
  input [7:0] B,
  input EN,
  output [7:0] SUM,
  output OVF
);

  reg [8:0] temp_sum;
  reg [7:0] prev_A;
  reg [7:0] prev_B;
  reg prev_EN;

  always @(*) begin
    if (EN == 1'b1) begin
      temp_sum = A + B;
      if ((A[7] == B[7]) && (A[7] != temp_sum[7]))
        OVF = 1'b1;
      else
        OVF = 1'b0;
    end
    else begin
      temp_sum = {prev_A, prev_B} + prev_EN;
    end
  end

  always @(posedge EN) begin
    if (EN == 1'b1) begin
      prev_A = A;
      prev_B = B;
      prev_EN = EN;
    end
  end

  assign SUM = temp_sum[7:0];

endmodule

