module edge_detection (
    input               clk,
    input               rst_n,
    input               a,
    output reg          rising_edge,
    output reg          falling_edge
);

reg prev_a;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        prev_a <= 1'b0;
        rising_edge <= 1'b0;
        falling_edge <= 1'b0;
    end else begin
        prev_a <= a;
        if (a && !prev_a) begin
            rising_edge <= 1'b1;
            falling_edge <= 1'b0;
        end else if (!a && prev_a) begin
            rising_edge <= 1'b0;
            falling_edge <= 1'b1;
        end else begin
            rising_edge <= 1'b0;
            falling_edge <= 1'b0;
        end
    end
end

endmodule

