pll100M gen_100MHz(.inclk0(clk),
                   .c0(clk100M));

reg [31:0] dds_accum;
reg [31:0] dds_adder;
reg [31:0] delay_cnt;

reg [2:0] gate_buff1;
reg [2:0] gate_buff2;

assign GATE1_D = (gate_buff1 == 3'b111);
assign GATE2_D = (gate_buff2 == 3'b111);

initial begin
    dds_accum <= 32'd0;
    dds_adder <= 32'd179272; // 440 Hz
    delay_cnt <= 32'd0;
    gate_buff1 <= 3'b000;
    gate_buff2 <= 3'b000;
end

always @ (posedge clk100M) begin
    gate_buff1 <= {gate_buff1[1:0], ~key1}; 
    gate_buff2 <= {gate_buff2[1:0], ~key2}; 
end

always @(posedge clk100M) begin
    if(delay_cnt == 32'd0) begin
        delay_cnt <= 32'd1000000;
        dds_adder <= (GATE1_D) ? dds_adder + 32'd100 :
                     (GATE2_D) ? dds_adder - 32'd100 : dds_adder;
    end else begin
        delay_cnt <= delay_cnt - 1'b1;
    end
end

always @(posedge clk100M) begin
    dds_accum <= dds_accum + dds_adder;
end

assign da_db = dds_accum[31:31-7];
assign da_clk = clk100M;

endmodule

module binary_comparator (
    input [3:0] a, // First 4-bit input
    input [3:0] b, // Second 4-bit input
    input clk, // Clock input
    input reset, // Reset input for the priority encoder
    output reg greater_than // Output signal indicating whether a > b
);

reg [3:0] a_gray, b_gray; // Gray code versions of the inputs
reg [1:0] priority; // Priority encoder output
wire [2:0] select; // Multiplexer select signal

// Binary-to-gray code converter
always @ (a) begin
    a_gray[0] = a[0];
    a_gray[1] = a[0] ^ a[1];
    a_gray[2] = a[1] ^ a[2];
    a_gray[3] = a[2] ^ a[3];
end

always @ (b) begin
    b_gray[0] = b[0];
    b_gray[1] = b[0] ^ b[1];
    b_gray[2] = b[1] ^ b[2];
    b_gray[3] = b[2] ^ b[3];
end

// Binary-to-decimal decoder for priority encoder
always @ (a_gray, b_gray, reset) begin
    if (reset) begin
        priority <= 2'b00;
    end else if (a_gray > b_gray) begin
        priority <= 2'b01;
    end else if (a_gray < b_gray) begin
        priority <= 2'b10;
    end else begin
        priority <= 2'b00;
    end
end

// Multiplexer select signal based on priority encoder output
assign select = (priority == 2'b00) ? 3'b000 : (priority == 2'b01) ? 3'b001 : 3'b010;

// Output signal indicating whether a > b
always @ (posedge clk) begin
    greater_than <= (a > b) ? 1'b1 : 1'b0;
end

// Assign output based on multiplexer select signal
always @ (select, a, b) begin
    case (select)
        3'b000: greater_than <= 1'b0; // a = b
        3'b001: greater_than <= 1'b1; // a > b
        3'b010: greater_than <= 1'b0; // a < b
        default: greater_than <= 1'b0; // Should not occur
    endcase
end

endmodule

