        valid_b <= 1'b0;
        data_out <= 10'b0;
    end
    else begin
        acc_reg1 <= acc_reg2 + data_in;
        acc_reg2 <= acc_reg1;
        count <= count + 1;
        if (count == 2'b11) begin
            data_out <= {acc_reg1, 2'b00};
            valid_b <= 1'b1;
