module fifo #
(
  parameter WIDTH = 8, // data width
  parameter DEPTH = 16 // depth of the FIFO
)
(
  input clk,
  input reset,
  input wr_en,
  input rd_en,
  input [WIDTH-1:0] data_in,
  output reg [WIDTH-1:0] data_out,
  output reg full,
  output reg empty
);

  reg [(WIDTH+1):0] mem [0:DEPTH-1]; // memory array
  reg [$clog2(DEPTH+1):0] wr_ptr = 0; // write pointer (initialized to 0)
  reg [$clog2(DEPTH+1):0] rd_ptr = 0; // read pointer (initialized to 0)
  reg [$clog2(DEPTH+1):0] count = 0; // number of elements in the FIFO (initialized to 0)

  // write operation
  always @(posedge clk) begin
    if (reset) begin
      wr_ptr <= 0;
      count <= 0;
      full <= 0;
      empty <= 1;
    end else if (wr_en && !full) begin
      mem[wr_ptr][WIDTH-1:0] <= data_in;
      wr_ptr <= wr_ptr + 1;
      count <= count + 1;
      empty <= 0;
      if (count == DEPTH) begin
        full <= 1;
      end
    end
  end

  // read operation
  always @(posedge clk) begin
    if (reset) begin
      rd_ptr <= 0;
      count <= 0;
      full <= 0;
      empty <= 1;
    end else if (rd_en && !empty) begin
      data_out <= mem[rd_ptr][WIDTH-1:0];
      rd_ptr <= rd_ptr + 1;
      count <= count - 1;
      full <= 0;
      if (count == 1) begin
        empty <= 1;
      end
    end
  end

endmodule

