        if(coins_inserted >= product_price && ready_state == 1) begin
            dispense_product <= 1;
            coins_returned <= coins_inserted - product_price;
            coins_inserted <= 0;
            ready_state <= 0;
        end else if(product_price > coins_inserted) begin
            return_coins <= coin;
        end
    end
end

assign dispense = dispense_product;
assign change = coins_returned;
assign ready = ready_state;

endmodule

module adder(A, B, Sum, Cout);
    input [7:0] A, B;
    output [8:0] Sum;
    output Cout;

    wire [7:0] temp_sum;
    wire carry;

    assign temp_sum = A + B;
    assign Sum = {1'b0, temp_sum};

    assign carry = (A[7] & B[7]) | (A[7] & ~temp_sum[7]) | (B[7] & ~temp_sum[7]);
    assign Cout = carry;

endmodule

module fifo_generator
   (dout,
    empty,
    full,
    rd_en,
    wr_en,
    rd_clk,
    wr_clk,
    din,
    rst);
  output [255:0]dout;
  output empty;
  output full;
  input rd_en;
  input wr_en;
  input rd_clk;
  input wr_clk;
  input [255:0]din;
  input rst;

  reg [255:0] fifo [0:15];
  reg [3:0] wr_ptr;
  reg [3:0] rd_ptr;
  reg [3:0] count;

  assign empty = (count == 0);
  assign full = (count == 16);

  always @(posedge wr_clk) begin
    if (rst) begin
      wr_ptr <= 0;
      rd_ptr <= 0;
      count <= 0;
      fifo <= 0;
    end else if (wr_en && !full) begin
      fifo[wr_ptr] <= din;
      wr_ptr <= wr_ptr + 1;
      count <= count + 1;
    end
  end

  always @(posedge rd_clk) begin
    if (rst) begin
      wr_ptr <= 0;
      rd_ptr <= 0;
      count <= 0;
      fifo <= 0;
    end else if (rd_en && !empty) begin
      dout <= fifo[rd_ptr];
      rd_ptr <= rd_ptr + 1;
      count <= count - 1;
    end
  end

endmodule

