module event_tagger(
    input [3:0] strobe_channels,
    input [3:0] delta_channels,
    input clk,
    input reset_counter,
    input capture_operate,
    input counter_operate,
    output ready,
    output [46:0] data
);

    reg [35:0] timer = 36'b0;
    reg [3:0] old_delta = 3'b0;
    reg ready = 0;
    reg [46:0] data = 47'b0;

    always @(posedge clk) begin
        if (delta_channels != old_delta) begin
            data[35:0] <= timer[35:0];
            data[39:36] <= delta_channels;
            data[44:40] <= 0;
            data[45] <= 1;
            data[46] <= (timer==1'b0) ? 1'b1 : 1'b0;
            ready <= capture_operate;
            old_delta <= delta_channels;
        end
        else if (strobe_channels != 4'b0 || (timer == 36'b0 && counter_operate)) begin
            data[35:0] <= timer[35:0];
            data[39:36] <= strobe_channels;
            data[44:40] <= 0;
            data[45] <= 0;
            data[46] <= (timer==36'b0) ? 1'b1 : 1'b0;
            ready <= capture_operate;
        end
        else begin
            ready <= 0;
            data <= 47'bX;
        end

        timer <= reset_counter ? 0 : timer + counter_operate;
    end

endmodule

module up_down_counter (
    input clk,
    input rst_n,
    input ctrl,
    input [7:0] data_in,
    output reg [7:0] count_out,
    output reg valid_a,
    input ready_a,
    input [1:0] state_in,
    output reg [1:0] state_out
);

reg [7:0] count_reg;
reg [1:0] state_reg;
wire [7:0] count_next;
wire [1:0] state_next;

parameter IDLE = 2'b00;
parameter UP = 2'b01;
parameter DOWN = 2'b10;

assign count_next = count_reg + 1;
assign state_next = state_reg;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        count_reg <= 8'h00;
        state_reg <= IDLE;
        valid_a <= 0;
    end else begin
        count_reg <= count_next;
        state_reg <= state_next;
        valid_a <= 1;
    end
end

always @(*) begin
    case (state_reg)
        IDLE: begin
            if (ctrl == 1) begin
                state_next = UP;
            end else if (ctrl == 0) begin
                state_next = DOWN;
            end
        end
        UP: begin
            if (count_reg == 8'hFF) begin
                state_next = IDLE;
            end
        end
        DOWN: begin
            if (count_reg == 8'h00) begin
                state_next = IDLE;
            end
        end
    endcase
end

always @(*) begin
    case (state_reg)
        IDLE: begin
            count_out = count_reg;
        end
        UP: begin
            count_out = count_next;
        end
        DOWN: begin
            count_out = count_reg - 1;
        end
    endcase
end

endmodule

