module stepper_motor_controller (
  input clk,
  input rst,
  input dir,
  input step,
  input [15:0] steps_per_rev,
  input [15:0] accel_rate,
  input [15:0] decel_rate,
  input [15:0] max_speed,
  input [15:0] target_pos,
  output [15:0] pos,
  output [15:0] speed,
  output done
);

  reg [15:0] current_pos;
  reg [15:0] prev_pos;
  reg [15:0] distance_to_target;
  reg [15:0] current_speed;
  reg [15:0] target_speed;
  reg [15:0] accel_count;
  reg [15:0] decel_count;
  reg [15:0] steps_to_decel;
  reg [15:0] steps_to_stop;
  reg [1:0] state;
  reg done_reg;

  parameter IDLE = 2'b00;
  parameter ACCELERATING = 2'b01;
  parameter CRUISING = 2'b10;
  parameter DECELERATING = 2'b11;

  always @(posedge clk) begin
    if (rst) begin
      current_pos <= 16'd0;
      prev_pos <= 16'd0;
      distance_to_target <= 16'd0;
      current_speed <= 16'd0;
      target_speed <= 16'd0;
      accel_count <= 16'd0;
      decel_count <= 16'd0;
      steps_to_decel <= 16'd0;
      steps_to_stop <= 16'd0;
      state <= IDLE;
      done_reg <= 1'b0;
    end else begin
      prev_pos <= current_pos;
      if (dir) begin
        current_pos <= current_pos + 1;
      end else begin
        current_pos <= current_pos - 1;
      end
      distance_to_target <= target_pos - current_pos;
      case (state)
        IDLE: begin
          if (step) begin
            state <= ACCELERATING;
            accel_count <= 16'd0;
            decel_count <= 16'd0;
            steps_to_decel <= (max_speed*max_speed)/(2*decel_rate);
            steps_to_stop <= (current_speed*current_speed)/(2*decel_rate);
            target_speed <= accel_rate;
          end
        end
        ACCELERATING: begin
          if (step) begin
            accel_count <= accel_count + 1;
            if (accel_count >= steps_to_decel) begin
              state <= DECELERATING;
              decel_count <= 16'd0;
              target_speed <= max_speed;
            end else begin
              target_speed <= target_speed + accel_rate;
            end
          end
        end
        CRUISING: begin
          if (step) begin
            if (distance_to_target <= steps_to_stop) begin
              state <= DECELERATING;
              decel_count <= 16'd0;
              target_speed <= (current_speed*distance_to_target)/steps_to_stop;
            end
          end
        end
        DECELERATING: begin
          if (step) begin
            decel_count <= decel_count + 1;
            if (decel_count >= steps_to_decel) begin
              state <= IDLE;
              target_speed <= 16'd0;
              done_reg <= 1'b1;
            end else begin
              target_speed <= target_speed - decel_rate;
            end
          end
        end
      endcase
      if (target_speed > max_speed) begin
        target_speed <= max_speed;
      end
      if (target_speed < 0) begin
        target_speed <= 0;
      end
      current_speed <= target_speed;
      done <= done_reg;
    end
  end

  assign pos = current_pos;
  assign speed = current_speed;

endmodule

module ethrx_realign
   (input clk, input reset, input clear,
    input [35:0] datain, input src_rdy_i, output dst_rdy_o,
    output [35:0] dataout, output src_rdy_o, input dst_rdy_i);

   reg [1:0] state;
   reg [15:0] held;
   reg [1:0] held_occ;

   wire xfer_in = src_rdy_i & dst_rdy_o;
   wire xfer_out = src_rdy_o & dst_rdy_i;

   wire sof_in = datain[32];
   wire eof_in = datain[33];
   wire [1:0] occ_in = datain[35:34];
   wire sof_out, eof_out;
   wire [1:0] occ_out;

   always @(posedge clk)
     if(reset | clear)
       begin
	  held <= 0;
	  held_occ <= 0;
       end
     else if(xfer_in)
       begin
	  held <= datain[15:0];
	  held_occ <= datain[35:34];
       end

   localparam RE_IDLE = 0;
   localparam RE_HELD = 1;
   localparam RE_DONE = 2;

   always @(posedge clk)
     if(reset | clear)
       state <= RE_IDLE;
     else
       case(state)
	 RE_IDLE :
	   if(src_rdy_i & dst_rdy_i)
	      if(eof_in)
		state <= RE_DONE;
	      else
		state <= RE_HELD;

	 RE_HELD :
	   if(src_rdy_i & dst_rdy_i & eof_in)
	     if((occ_in==0)|(occ_in==3))
	       state <= RE_DONE;
	     else
	       state <= RE_IDLE;

	 RE_DONE :
	   if(dst_rdy_i)
	     state <= RE_IDLE;

       endcase // case (state)


   assign sof_out = (state == RE_IDLE);
   assign eof_out = (state == RE_DONE) | (occ_in == 1) | (occ_in == 2);
   assign occ_out = (state == RE_DONE) ? ((held_occ == 3) ? 1 : 2) :
		    (occ_in == 1) ? 3 : 0;

   assign dataout = {occ_out,eof_out,sof_out,held,datain[31:16]};
   assign src_rdy_o = (state == RE_DONE) | src_rdy_i;
   assign dst_rdy_o = dst_rdy_i & ((state == RE_IDLE)|(state == RE_HELD));
endmodule

