module spi_master (
  input clk,
  input rst,
  input mosi,
  input ssel,
  output reg miso
);

  reg [7:0] tx_data;
  reg [7:0] rx_data;
  reg [2:0] bit_count;
  reg [2:0] state;

  parameter IDLE = 0;
  parameter SEND = 1;
  parameter RECEIVE = 2;

  always @(posedge clk) begin
    if (rst) begin
      miso <= 1'b0;
      tx_data <= 8'h00;
      rx_data <= 8'h00;
      bit_count <= 3'd0;
      state <= IDLE;
    end
    else begin
      case (state)
        IDLE: begin
          if (!ssel) begin
            state <= SEND;
            bit_count <= 3'd0;
            miso <= 1'b0;
          end
        end
        SEND: begin
          if (bit_count < 8) begin
            mosi <= tx_data[7-bit_count];
            bit_count <= bit_count + 1;
          end
          else begin
            state <= RECEIVE;
            bit_count <= 3'd0;
            mosi <= 1'b0;
          end
        end
        RECEIVE: begin
          if (bit_count < 8) begin
            rx_data[7-bit_count] <= mosi;
            bit_count <= bit_count + 1;
          end
          else begin
            state <= IDLE;
            bit_count <= 3'd0;
            miso <= 1'b1;
          end
        end
      endcase
    end
  end

endmodule

