module rle_encode (
  input clk,
  input rst,
  input [7:0] in,
  output [7:0] out,
  output [7:0] count
);

  reg [7:0] prev_val;
  reg [7:0] curr_val;
  reg [7:0] curr_count;
  reg [7:0] next_count;
  reg [7:0] out_val;
  reg [7:0] out_count;

  always @(posedge clk) begin
    if (rst) begin
      prev_val <= 8'h00;
      curr_val <= 8'h00;
      curr_count <= 8'h00;
      next_count <= 8'h00;
      out_val <= 8'h00;
      out_count <= 8'h00;
    end else begin
      prev_val <= curr_val;
      curr_val <= in;
      if (curr_val == prev_val) begin
        curr_count <= curr_count + 1;
      end else begin
        next_count <= curr_count;
        curr_count <= 1;
      end
      if (next_count != 0) begin
        out_count <= next_count;
        out_val <= prev_val;
        next_count <= 0;
      end else begin
        out_count <= 0;
        out_val <= 0;
      end
    end
  end

  assign count = out_count;
  assign out = out_val;

endmodule

module rle_decode (
  input clk,
  input rst,
  input [7:0] in,
  input [7:0] count,
  output [7:0] out
);

  reg [7:0] prev_val;
  reg [7:0] curr_val;
  reg [7:0] curr_count;
  reg [7:0] out_val;

  always @(posedge clk) begin
    if (rst) begin
      prev_val <= 8'h00;
      curr_val <= 8'h00;
      curr_count <= 8'h00;
      out_val <= 8'h00;
    end else begin
      prev_val <= curr_val;
      curr_val <= in;
      if (curr_count == 0) begin
        curr_count <= count;
        out_val <= curr_val;
      end else begin
        curr_count <= curr_count - 1;
        out_val <= prev_val;
      end
    end
  end

  assign out = out_val;

endmodule

