module tse_mac_loopback (
  ref_clk,
  txp,
  rxp
);

  output ref_clk;
  input txp;
  output rxp;

  reg clk_tmp;
  initial
     clk_tmp <= 1'b0;
  always
     #4 clk_tmp <= ~clk_tmp;

  reg reconfig_clk_tmp;
  initial
     reconfig_clk_tmp <= 1'b0;
  always
     #20 reconfig_clk_tmp <= ~reconfig_clk_tmp;

  reg [1:0] delay_counter = 2'b00;
  reg [1:0] tx_state = 2'b00;
  reg [1:0] rx_state = 2'b00;

  assign ref_clk = clk_tmp;
  assign rxp = ~txp;

  always @(posedge clk_tmp) begin
    if (delay_counter == 2'b11) begin
      delay_counter <= 2'b00;
      tx_state <= 2'b00;
      rx_state <= 2'b00;
    end else begin
      delay_counter <= delay_counter + 2'b01;
    end
  end

  always @(posedge clk_tmp) begin
    case (tx_state)
      2'b00: begin
        if (txp) begin
          tx_state <= 2'b01;
        end
      end
      2'b01: begin
        tx_state <= 2'b10;
      end
      2'b10: begin
        tx_state <= 2'b00;
      end
    endcase
  end

  always @(posedge clk_tmp) begin
    case (rx_state)
      2'b00: begin
        rx_state <= 2'b01;
      end
      2'b01: begin
        rx_state <= 2'b10;
      end
      2'b10: begin
        if (delay_counter == 2'b11) begin
          rx_state <= 2'b00;
        end
      end
    endcase
  end

endmodule

