module vending_machine(
    input clk,
    input reset,
    input [1:0] coin,
    input product,
    output reg dispense,
    output reg [1:0] return,
    output reg [3:0] display,
    output reg [1:0] status
);

reg [3:0] money;
reg [1:0] stock;

parameter READY = 2'b00;
parameter DISPENSING = 2'b01;
parameter OUT_OF_STOCK = 2'b10;
parameter UNUSED = 2'b11;

always @(posedge clk) begin
    if(reset) begin
        money <= 0;
        stock <= 0;
        dispense <= 0;
        return <= 0;
        display <= 0;
        status <= READY;
    end else begin
        if(product && stock > 0 && money >= 25) begin
            dispense <= 1;
            stock <= stock - 1;
            money <= money - 25;
            status <= DISPENSING;
        end else if(money > 0 && !product) begin
            return <= money;
            money <= 0;
            status <= READY;
        end else if(stock == 0) begin
            status <= OUT_OF_STOCK;
        end else begin
            status <= READY;
        end

        if(coin == 2'b01) begin
            money <= money + 5;
        end else if(coin == 2'b10) begin
            money <= money + 10;
        end else if(coin == 2'b11) begin
            money <= money + 25;
        end

        display <= {money[3:0] > 9, money[3:0] % 10};
    end
end

endmodule

module fifo(clk, rst, en, wr_data, rd_data, full, empty);

  parameter WIDTH = 8;
  parameter DEPTH = 8;

  input clk, rst, en;
  input [WIDTH-1:0] wr_data;
  output [WIDTH-1:0] rd_data;
  output full, empty;

  reg [WIDTH-1:0] mem [0:DEPTH-1];
  reg [2:0] wr_ptr, rd_ptr;
  reg [2:0] count;
  reg full, empty;

  always @(posedge clk) begin
    if (rst) begin
      count <= 0;
      wr_ptr <= 0;
      rd_ptr <= 0;
      full <= 0;
      empty <= 1;
    end else if (en) begin
      if (count == DEPTH) begin
        full <= 1;
        empty <= 0;
      end else if (count == 0) begin
        full <= 0;
        empty <= 1;
      end else begin
        full <= 0;
        empty <= 0;
      end

      if (~full) begin
        mem[wr_ptr] <= wr_data;
        wr_ptr <= wr_ptr + 1;
        count <= count + 1;
      end

      if (~empty) begin
        rd_data <= mem[rd_ptr];
        rd_ptr <= rd_ptr + 1;
        count <= count - 1;
      end
    end
  end

endmodule

module bin2bcd (
    input [4:0] BIN,
    output reg [3:0] BCD0,
    output reg [3:0] BCD1
);

reg [3:0] temp_bcd0;
reg [3:0] temp_bcd1;

always @(*) begin
    temp_bcd0 = 0;
    temp_bcd1 = 0;
    if (BIN >= 10) begin
        temp_bcd0 = temp_bcd0 + 1;
        BIN = BIN - 10;
    end
    if (BIN >= 5) begin
        temp_bcd0 = temp_bcd0 + 8;
        BIN = BIN - 5;
    end
    if (BIN >= 2) begin
        temp_bcd0 = temp_bcd0 + 4;
        BIN = BIN - 2;
    end
    if (BIN >= 1) begin
        temp_bcd0 = temp_bcd0 + 2;
        BIN = BIN - 1;
    end

    if (BIN >= 8) begin
        temp_bcd1 = temp_bcd1 + 1;
        BIN = BIN - 8;
    end
    if (BIN >= 4) begin
        temp_bcd1 = temp_bcd1 + 8;
        BIN = BIN - 4;
    end
    if (BIN >= 2) begin
        temp_bcd1 = temp_bcd1 + 4;
        BIN = BIN - 2;
    end
    if (BIN >= 1) begin
        temp_bcd1 = temp_bcd1 + 2;
        BIN = BIN - 1;
    end

    BCD0 = temp_bcd0;
    BCD1 = temp_bcd1;
end

endmodule

