module posManager (
    input wire clk,
    input wire m1,
    input wire m2,
    input wire [1:0] clear,
    output reg [15:0] pos11,
    output reg [15:0] pos12,
    output reg [15:0] pos21,
    output reg [15:0] pos22,
    output wire [15:0] pos_diff,
    output reg [31:0] count_clk
);

    reg m1_delay, m2_delay, m1_clean, m2_clean;
    initial begin
        count_clk = 32'b0;
        m1_delay = 1'b0;
        m2_delay = 1'b0;
        m1_clean = 1'b0;
        m2_clean = 1'b0;
    end

    always @(posedge clk) begin
        if (clear[0]) begin
            count_clk <= 32'b0;
            pos11 <= 16'b0;
            pos12 <= 16'b0;
            pos21 <= 16'b0;
            pos22 <= 16'b0;
        end
        else begin
            count_clk <= count_clk + 1'b1;
            pos11 <= pos12;
            pos21 <= pos22;
        end

        m1_delay <= m1;
        m2_delay <= m2;
        m1_clean <= m1_delay;
        m2_clean <= m2_delay;
    end

    wire subtract;
    assign subtract = pos12[15] | pos22[15];

    reg [15:0] distance;
    always @(*) begin
        if (pos12 < pos22) distance = pos12;
        else distance = pos22;
    end

    posCounter pos_counter1 (
        .clk(clk),
        .pos1(pos11),
        .pos2(pos12),
        .sensor(m1_clean),
        .clear(clear),
        .subtract(subtract),
        .distance(distance)
    );

    posCounter pos_counter2 (
        .clk(clk),
        .pos1(pos21),
        .pos2(pos22),
        .sensor(m2_clean),
        .clear(clear),
        .subtract(subtract),
        .distance(distance)
    );

    assign pos_diff = pos12 - pos22;

endmodule

