  reg [3:0] pwm_counter;
  reg pwm_out;

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      data_reg <= 8'h0;
      pwm_counter <= 4'h0;
      pwm_out <= 1'b0;
    end else begin
      data_reg <= data_in;
      pwm_counter <= pwm_counter + 1;
      pwm_out <= (pwm_counter < data_reg[3:0]) ? 1'b1 : 1'b0;
    end
  end

  assign ir_out = pwm_out;
