      data_reg <= 8'h0;
      pwm_counter <= 4'h0;
    end else begin
      if (ir_in) begin
        pwm_counter <= pwm_counter + 1;
      end else begin
        if (pwm_counter != 4'h0) begin
          data_reg <= {data_reg[6:0], pwm_counter[3]};
