always @(posedge clk) begin
    if (load) begin
        pipeline_reg[0] <= data_in;
        pipeline_reg[1] <= pipeline_reg[0];
        pipeline_reg[2] <= pipeline_reg[1];
    end else begin
        pipeline_reg[0] <= {shifted_data, data_in[0]};
        pipeline_reg[1] <= pipeline_reg[0];
        pipeline_reg[2] <= pipeline_reg[1];
