reg [7:0] q_demod;
reg [7:0] i_prev_demod;
reg [7:0] q_prev_demod;
reg [3:0] state_demod;
reg [7:0] count_demod;

// Modulation process
always @(posedge clk) begin
  if (rst) begin
    data_reg <= 8'h00;
    mod_reg <= 16'h0000;
    i_reg <= 8'h00;
    q_reg <= 8'h00;
    i_next <= 8'h00;
    q_next <= 8'h00;
    i_out <= 8'h00;
    q_out <= 8'h00;
    i_prev <= 8'h00;
    q_prev <= 8'h00;
    state <= 4'h0;
    count <= 8'h00;
  end else begin
    data_reg <= data_in;
    mod_reg <= {q_next, i_next};
    case (state)
      4'h0: begin
        i_reg <= 8'h00;
        q_reg <= 8'h00;
        i_next <= 8'h00;
        q_next <= 8'h00;
        i_out <= 8'h00;
        q_out <= 8'h00;
        i_prev <= 8'h00;
        q_prev <= 8'h00;
        count <= 8'h00;
        state <= 4'h1;
      end
      4'h1: begin
        i_reg <= data_reg;
        q_reg <= 8'h00;
        i_next <= i_reg;
        q_next <= q_reg;
        i_out <= i_prev;
        q_out <= q_prev;
        i_prev <= i_reg;
        q_prev <= q_reg;
        count <= count + 1;
        if (count == 8'h3f) begin
          state <= 4'h2;
        end
      end
      4'h2: begin
        i_reg <= 8'h00;
        q_reg <= data_reg;
        i_next <= i_reg;
        q_next <= q_reg;
        i_out <= i_prev;
        q_out <= q_prev;
        i_prev <= i_reg;
        q_prev <= q_reg;
        count <= count + 1;
        if (count == 8'h3f) begin
          state <= 4'h3;
        end
      end
      4'h3: begin
        i_reg <= data_reg;
        q_reg <= 8'h00;
        i_next <= i_reg;
        q_next <= q_reg;
        i_out <= i_prev;
        q_out <= q_prev;
        i_prev <= i_reg;
        q_prev <= q_reg;
        count <= count + 1;
        if (count == 8'h3f) begin
          state <= 4'h4;
        end
      end
      4'h4: begin
        i_reg <= 8'h00;
        q_reg <= data_reg;
        i_next <= i_reg;
        q_next <= q_reg;
        i_out <= i_prev;
        q_out <= q_prev;
        i_prev <= i_reg;
        q_prev <= q_reg;
        count <= count + 1;
        if (count == 8'h3f) begin
          state <= 4'h1;
        end
      end
    endcase
  end
end

// Demodulation process
always @(posedge clk) begin
  if (rst) begin
    demod_reg <= 16'h0000;
    i_demod <= 8'h00;
    q_demod <= 8'h00;
    i_prev_demod <= 8'h00;
    q_prev_demod <= 8'h00;
    state_demod <= 4'h0;
    count_demod <= 8'h00;
  end else begin
    demod_reg <= mod_out;
    case (state_demod)
      4'h0: begin
        i_demod <= 8'h00;
        q_demod <= 8'h00;
        i_prev_demod <= 8'h00;
        q_prev_demod <= 8'h00;
        count_demod <= 8'h00;
        state_demod <= 4'h1;
      end
      4'h1: begin
        i_demod <= demod_reg[7:0];
        q_demod <= demod_reg[15:8];
        i_prev_demod <= i_demod;
        q_prev_demod <= q_demod;
        count_demod <= count_demod + 1;
        if (count_demod == 8'h3f) begin
          state_demod <= 4'h2;
        end
      end
      4'h2: begin
        i_demod <= demod_reg[7:0];
        q_demod <= demod_reg[15:8];
        i_prev_demod <= i_demod;
        q_prev_demod <= q_demod;
        count_demod <= count_demod + 1;
        if (count_demod == 8'h3f) begin
          state_demod <= 4'h3;
        end
      end
      4'h3: begin
        i_demod <= demod_reg[7:0];
        q_demod <= demod_reg[15:8];
        i_prev_demod <= i_demod;
        q_prev_demod <= q_demod;
        count_demod <= count_demod + 1;
        if (count_demod == 8'h3f) begin
          state_demod <= 4'h4;
        end
      end
      4'h4: begin
        i_demod <= demod_reg[7:0];
        q_demod <= demod_reg[15:8];
        i_prev_demod <= i_demod;
        q_prev_demod <= q_demod;
        count_demod <= count_demod + 1;
        if (count_demod == 8'h3f) begin
          state_demod <= 4'h1;
        end
      end
    endcase
  end
end

// Output the modulated signal
assign mod_out = {q_out, i_out};

// Extract the data from the demodulated signal
always @(posedge clk) begin
  if (rst) begin
    data_out <= 8'h00;
  end else begin
    data_out <= i_prev_demod;
  end
