module convolution_module (
    input [24:0] input_matrix,
    input [8:0] kernel_matrix,
    output reg [24:0] output_matrix
);

reg [4:0] input_matrix_2d [0:4];
reg [8:0] kernel_matrix_2d [0:2][0:2];

integer i, j;

always @(*) begin
    for (i = 0; i < 5; i = i + 1) begin
        for (j = 0; j < 5; j = j + 1) begin
            if (i == 0 || i == 4 || j == 0 || j == 4) begin
                input_matrix_2d[i][j] = 0;
            end else begin
                input_matrix_2d[i][j] = input_matrix[(i-1)*5 + (j-1)];
            end
        end
    end

    for (i = 0; i < 3; i = i + 1) begin
        for (j = 0; j < 3; j = j + 1) begin
            kernel_matrix_2d[i][j] = kernel_matrix[i*3 + j];
        end
    end

    output_matrix = {25{1'b0}};
    for (i = 1; i < 4; i = i + 1) begin
        for (j = 1; j < 4; j = j + 1) begin
            output_matrix[(i-1)*5 + (j-1)] = 
                input_matrix_2d[i-1][j-1]*kernel_matrix_2d[0][0] +
                input_matrix_2d[i-1][j]*kernel_matrix_2d[0][1] +
                input_matrix_2d[i-1][j+1]*kernel_matrix_2d[0][2] +
                input_matrix_2d[i][j-1]*kernel_matrix_2d[1][0] +
                input_matrix_2d[i][j]*kernel_matrix_2d[1][1] +
                input_matrix_2d[i][j+1]*kernel_matrix_2d[1][2] +
                input_matrix_2d[i+1][j-1]*kernel_matrix_2d[2][0] +
                input_matrix_2d[i+1][j]*kernel_matrix_2d[2][1] +
                input_matrix_2d[i+1][j+1]*kernel_matrix_2d[2][2];
        end
    end
end

endmodule

