    inout sda,
    input scl,
    input [6:0] slave_addrs,
    output [7:0] curr_data
);

    // Internal registers and wires
    reg [7:0] mem;          // Memory to store data
    reg [3:0] bitcnt;       // Counts the bits being transmitted
    reg data_phase;         // Indicates whether the current bit is data or address
    reg adr_match;          // Indicates whether the received address matches the slave address
    reg op_read;            // Indicates whether the current operation is a read or write
    reg got_ACK;            // Indicates whether an ACK has been received
    reg SDAr;               // Sampled value of sda
    wire bit_DATA = ~bitcnt[3];
    wire bit_ACK = bitcnt[3];
    wire adr_phase = ~data_phase;
    wire op_write = ~op_read;
    wire mem_bit_low = ~mem[bitcnt[2:0]];
    wire SDA_assert_low = adr_match & bit_DATA & data_phase & op_read & mem_bit_low & got_ACK;
    wire SDA_assert_ACK = adr_match & bit_ACK & (adr_phase | op_write);
    wire SDA_low = SDA_assert_low | SDA_assert_ACK;

    // Detect start and stop conditions
    wire SDA_shadow;
    wire start_or_stop;
    `ifdef Xilinx
        BUF mybuf(.O(SDA_shadow), .I((~scl | start_or_stop) ? sda : SDA_shadow));
        BUF SOS_BUF(.O(start_or_stop), .I(~scl ? 1'b0 : (sda ^ SDA_shadow)));
    `else
        wire SDA_shadow = (~scl | start_or_stop) ? sda : SDA_shadow /* synthesis keep = 1 */;
        wire start_or_stop = ~scl ? 1'b0 : (sda ^ SDA_shadow) /* synthesis keep = 1 */;
    `endif

    // Count bits and detect address match
    reg incycle;
    always @(negedge scl or posedge start_or_stop) begin
        if (start_or_stop) begin
            incycle <= 1'b0;
            bitcnt <= 4'h7;
            data_phase <= 1'b0;
            adr_match <= 1'b0;
            op_read <= 1'b0;
            got_ACK <= 1'b0;
        end else if (~sda) begin
            incycle <= 1'b1;
            if (bit_ACK) begin
                bitcnt <= 4'h7;
                data_phase <= 1'b1;
            end else begin
                bitcnt <= bitcnt - 4'h1;
            end
            if (adr_phase & bitcnt == 7 & SDAr != slave_addrs[6]) begin
                adr_match <= 1'b0;
            end else if (adr_phase & bitcnt == 6 & SDAr != slave_addrs[5]) begin
                adr_match <= 1'b0;
            end else if (adr_phase & bitcnt == 5 & SDAr != slave_addrs[4]) begin
                adr_match <= 1'b0;
            end else if (adr_phase & bitcnt == 4 & SDAr != slave_addrs[3]) begin
                adr_match <= 1'b0;
            end else if (adr_phase & bitcnt == 3 & SDAr != slave_addrs[2]) begin
                adr_match <= 1'b0;
            end else if (adr_phase & bitcnt == 2 & SDAr != slave_addrs[1]) begin
                adr_match <= 1'b0;
            end else if (adr_phase & bitcnt == 1 & SDAr != slave_addrs[0]) begin
                adr_match <= 1'b0;
            end else if (adr_phase & bitcnt == 0) begin
                op_read <= SDAr;
            end
            if (bit_ACK) begin
                got_ACK <= ~SDAr;
            end
            if (adr_match & bit_DATA & data_phase & op_write) begin
                mem[bitcnt] <= SDAr;
            end
        end
    end

    // Drive sda line
    assign sda = SDA_low ? 1'b0 : 1'bz;

    // Output current data
    assign curr_data = mem;

endmodule

