module edge_detection(
    input clk,
    input reset,
    input signal,
    input select_edge,
    output reg edge
);

reg prev_signal;

always @(posedge clk, posedge reset) begin
    if (reset) begin
        prev_signal <= 1'b0;
        edge <= 1'b0;
    end else begin
        if (select_edge) begin
            if (signal && !prev_signal) begin
                edge <= 1'b1;
            end else begin
                edge <= 1'b0;
            end
        end else begin
            if (!signal && prev_signal) begin
                edge <= 1'b1;
            end else begin
                edge <= 1'b0;
            end
        end
        prev_signal <= signal;
    end
end

endmodule

