module data_bus_module (
  input wr_clk,
  input [9:0] RD_PNTR_WR,
  input AR,
  input wr_en,
  output reg full,
  output reg prog_full,
  output reg [9:0] Q,
  output reg E,
  output reg [9:0] wr_data_count,
  output reg out
);

  reg [9:0] data_bus [0:1023];
  reg [9:0] wr_ptr;
  reg [9:0] rd_ptr;
  reg [9:0] wr_count;
  reg [9:0] rd_count;
  reg [9:0] max_data_count;
  reg [9:0] max_prog_count;
  reg [9:0] data_bus_size;
  reg [9:0] data_bus_mask;
  reg [9:0] prog_mem_size;
  reg [9:0] prog_mem_mask;

  // Set the maximum data count based on the address range
  always @ (AR) begin
    if (AR == 1'b0) begin
      max_data_count = 10'b1111111111;
    end else begin
      max_data_count = 10'b111111111;
    end
  end

  // Set the maximum program memory count
  always @ (prog_full) begin
    if (prog_full == 1'b0) begin
      prog_mem_size = 10'b111111111;
    end else begin
      prog_mem_size = 10'b11111111;
    end
  end

  // Set the data bus size and mask based on the maximum data count
  always @ (max_data_count) begin
    data_bus_size = max_data_count + 1;
    data_bus_mask = max_data_count;
  end

  // Set the program memory mask based on the maximum program memory count
  always @ (prog_mem_size) begin
    prog_mem_mask = prog_mem_size;
  end

  // Write to the data bus if write is enabled and the data bus is not full
  always @ (posedge wr_clk) begin
    if (wr_en == 1'b1 && wr_count < max_data_count) begin
      data_bus[wr_ptr] <= Q;
      wr_ptr <= (wr_ptr == data_bus_mask) ? 10'b0 : wr_ptr + 1;
      wr_count <= wr_count + 1;
      wr_data_count <= wr_data_count + 1;
      full <= (wr_count == max_data_count) ? 1'b1 : 1'b0;
    end
  end

  // Check if the data bus is empty and set the out signal accordingly
  always @ (posedge wr_clk) begin
    if (rd_count == 0) begin
      out <= 1'b0;
    end
  end

  // Read from the data bus if the out signal is enabled and the data bus is not empty
  always @ (posedge wr_clk) begin
    if (out == 1'b1 && rd_count > 0) begin
      Q <= data_bus[rd_ptr];
      rd_ptr <= (rd_ptr == data_bus_mask) ? 10'b0 : rd_ptr + 1;
      rd_count <= rd_count - 1;
      out <= (rd_count == 1) ? 1'b0 : 1'b1;
    end
  end

  // Check if the data bus is full and set the full signal accordingly
  always @ (posedge wr_clk) begin
    if (wr_count == max_data_count) begin
      full <= 1'b1;
    end else begin
      full <= 1'b0;
    end
  end

  // Check if the program memory is full and set the prog_full signal accordingly
  always @ (posedge wr_clk) begin
    if (wr_count == max_data_count && wr_en == 1'b1) begin
      prog_full <= 1'b1;
    end
  end

  // Set the E signal if an error occurs
  always @ (posedge wr_clk) begin
    if (wr_en == 1'b1 && wr_count == max_data_count) begin
      E <= 1'b1;
    end else begin
      E <= 1'b0;
    end
  end

  // Initialize pointers and counters
  initial begin
    wr_ptr = 10'b0;
    rd_ptr = 10'b0;
    wr_count = 10'b0;
    rd_count = 10'b0;
  end

endmodule

