module execute_branch(
		input wire [31:0] iDATA_0,
		input wire [31:0] iDATA_1,		
		input wire [31:0] iPC,
		input wire [4:0] iFLAG,
		input wire [3:0] iCC,
		input wire [4:0] iCMD,
		output wire [31:0] oBRANCH_ADDR,
		output wire oJUMP_VALID,
		output wire oNOT_JUMP_VALID,
		output wire oIB_VALID,
		output wire oIDTS_VALID,
		output wire oHALT_VALID
	);

	// Calculate branch address
	assign oBRANCH_ADDR = func_branch_addr(
		iCMD,
		iPC,
		iDATA_1
	);

	// Determine if jump is valid
	assign oJUMP_VALID = (iCMD != 5'b01000 && iCMD != 5'b01010)? func_ex_branch_check(iCC, iFLAG) : 1'b0;
	assign oNOT_JUMP_VALID = (iCMD != 5'b01000 && iCMD != 5'b01010)? !func_ex_branch_check(iCC, iFLAG) : 1'b0;
	assign oIB_VALID = (iCMD == 5'b01000)? 1'b1 : 1'b0;
	assign oIDTS_VALID = (iCMD == 5'b01010)? 1'b1 : 1'b0;
	assign oHALT_VALID = (iCMD == 5'b01111)? 1'b1 : 1'b0;

	// Function to calculate branch address
	function [31:0] func_branch_addr;
		input [4:0] func_cmd;
		input [31:0] func_pc;
		input [31:0] func_source1;
		begin
			case(func_cmd)
				5'b01000:
					begin
						func_branch_addr = 32'h0;
					end
				5'b01001:
					begin
						func_branch_addr = func_source1 + func_pc;
					end
				5'b01010:
					begin
						func_branch_addr = func_pc + 32'h0000004;
					end
				5'b01111:
					begin
						func_branch_addr = func_pc + 32'h0000004;
					end
				default:
					begin
						func_branch_addr = 32'h0;
					end
			endcase
		end
	endfunction

	// Function to determine if jump is valid
	function func_ex_branch_check;
		input [3:0] func_ex_branch_check_cc;
		input [4:0] func_ex_branch_check_flag;
		begin
			case(func_ex_branch_check_cc)
				4'b0000 : func_ex_branch_check = 1'b1; // AL
				4'b0001 : // EQ
					begin
						if(func_ex_branch_check_flag[4])begin
							func_ex_branch_check = 1'b1;
						end
						else begin
							func_ex_branch_check = 1'b0;
						end
					end
				4'b0010 : // NEQ
					begin
						if(!func_ex_branch_check_flag[4])begin
							func_ex_branch_check = 1'b1;
						end
						else begin
							func_ex_branch_check = 1'b0;
						end
					end
				4'b0100 : // MI
					begin
						func_ex_branch_check = func_ex_branch_check_flag[2];
					end
				4'b0101 : // PL
					begin
						func_ex_branch_check = !func_ex_branch_check_flag[2];
					end
				4'b1010 : // ON
					begin
						if(func_ex_branch_check_flag[1])begin
							func_ex_branch_check = 1'b1;
						end
						else begin
							func_ex_branch_check = 1'b0;
						end
					end
				4'b1011 : // OVF
					begin
						if(func_ex_branch_check_flag[3])begin
							func_ex_branch_check = 1'b1;
						end
						else begin
							func_ex_branch_check = 1'b0;
						end
					end
				4'b1100 : // UEO
					begin
						func_ex_branch_check = func_ex_branch_check_flag[0];
					end
				4'b1101 : // UU
					begin
						func_ex_branch_check = !func_ex_branch_check_flag[0];
					end
				4'b1110 : // UO
					begin
						func_ex_branch_check = func_ex_branch_check_flag[0] && !func_ex_branch_check_flag[4];
					end
				4'b1111 : // UEU
					begin
						func_ex_branch_check = !func_ex_branch_check_flag[0] || func_ex_branch_check_flag[4];
					end
				default : func_ex_branch_check = 1'b1;
			endcase
		end
	endfunction

endmodule

