module adder_subtractor (
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] sum,
    output [31:0] sum_reverse
);

    wire [31:0] add_result;
    wire [31:0] sub_result;
    wire [31:0] xor_result;

    assign add_result = a + b;
    assign sub_result = a - b;
    assign xor_result = sub_result ^ add_result;

    assign sum = sub ? sub_result : add_result;
    assign sum_reverse = {sum[7:0], sum[15:8], sum[23:16], sum[31:24]};

endmodule

module byte_reversal (
    input [31:0] input_data,
    output [31:0] output_data
);

    assign output_data = {input_data[7:0], input_data[15:8], input_data[23:16], input_data[31:24]};

endmodule

module functional_module (
    input [31:0] input1,
    input [31:0] input2,
    output [31:0] final_output
);

    wire [31:0] abs_input1;
    wire [31:0] abs_input2;

    assign abs_input1 = (input1[31] == 1) ? ~input1 + 1 : input1;
    assign abs_input2 = (input2[31] == 1) ? ~input2 + 1 : input2;

    assign final_output = abs_input1 + abs_input2;

endmodule

module top_module (
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] sum,
    output [31:0] sum_reverse,
    output [31:0] final_output
);

    wire [31:0] add_sub_result;
    wire [31:0] byte_reversal_result;

    adder_subtractor add_sub_module (
        .a(a),
        .b(b),
        .sub(sub),
        .sum(add_sub_result),
        .sum_reverse(sum_reverse)
    );

    byte_reversal byte_reversal_module (
        .input_data(add_sub_result),
        .output_data(byte_reversal_result)
    );

    functional_module functional_module (
        .input1(add_sub_result),
        .input2(byte_reversal_result),
        .final_output(final_output)
    );

endmodule

module gost89_ecb(
  input              clk,
  input              reset,
  input              mode,
  input              load_data,
  input      [511:0] sbox,
  input      [255:0] key,
  input      [63:0]  in,
  output reg [63:0]  out,
  output reg         busy
);
  reg  [5:0]  round_num;
  reg  [31:0] n1, n2, round_key;
  wire [31:0] out1, out2;

  gost89_round
    rnd(clk, sbox, round_key, n1, n2, out1, out2);

  always @(posedge clk) begin
    if (load_data) begin
      n1 <= in[63:32];
      n2 <= in[31:0];
      busy <= 1;
      round_num <= 0;
    end

    if (reset && !load_data) begin
      busy <= 0;
      round_num <= 32;
    end

    if (!reset && !load_data) begin
      if (round_num < 32)
        round_num <= round_num + 1;
      if (round_num > 0 && round_num < 32) begin
        n1 <= out1;
        n2 <= out2;
      end
      if (round_num == 32) begin
        out[63:32] <= out2;
        out[31:0]  <= out1;
        busy <= 0;
      end
    end
  end

  always @(posedge clk) begin
    if (mode)
      case (round_num)
        0:  round_key <= key[255:224];
        1:  round_key <= key[223:192];
        2:  round_key <= key[191:160];
        3:  round_key <= key[159:128];
        4:  round_key <= key[127:96];
        5:  round_key <= key[95:64];
        6:  round_key <= key[63:32];
        7:  round_key <= key[31:0];
        8:  round_key <= key[31:0];
        9:  round_key <= key[63:32];
