module trng_control_unit(
  // Clock and reset.
  input wire clk,
  input wire reset_n,

  // Control.
  input wire cs,
  input wire we,

  // Data ports.
  input wire [7:0] address,
  input wire [31:0] write_data,
  output wire [31:0] read_data,
  output wire error,

  // Debug and control ports
  output wire csprng_debug_mode,
  output wire [4:0] csprng_num_rounds,
  output wire csprng_reseed,
  input wire csprng_error,
  output wire security_error
);

  // Internal constant and parameter definitions.
  parameter ADDR_NAME0 = 8'h00;
  parameter ADDR_NAME1 = 8'h01;
  parameter ADDR_VERSION = 8'h02;

  parameter CORE_NAME0 = 32'h73686132; // "sha2"
  parameter CORE_NAME1 = 32'h2d323536; // "-512"
  parameter CORE_VERSION = 32'h302e3830; // "0.80"

  // Registers including update variables and write enable.
  reg [31:0] name0;
  reg [31:0] name1;
  reg [31:0] version;
  reg name0_we;
  reg name1_we;
  reg version_we;

  // Wires.
  reg [31:0] tmp_read_data;
  reg tmp_error;

  // Concurrent connectivity for ports etc.
  assign read_data = tmp_read_data;
  assign error = tmp_error;

  // core instantiation.
  // TODO: Instantiate TRNG core and connect debug and control ports.

  // reg_update
  //
  // Update functionality for all registers in the core.
  // All registers are positive edge triggered with synchronous
  // active low reset. All registers have write enable.
  always @(posedge clk) begin
    if (!reset_n) begin
      name0 <= 0;
      name1 <= 0;
      version <= 0;
      name0_we <= 0;
      name1_we <= 0;
      version_we <= 0;
    end else begin
      if (name0_we) begin
        name0 <= write_data;
        name0_we <= 0;
      end
      if (name1_we) begin
        name1 <= write_data;
        name1_we <= 0;
      end
      if (version_we) begin
        version <= write_data;
        version_we <= 0;
      end
    end
  end // reg_update

  // addr_decoder
  //
  // Decodes the address and performs the appropriate read or write
  // operation on the internal registers.
  always @* begin
    tmp_read_data = 32'h00000000;
    tmp_error = 0;

    if (cs) begin
      if (we) begin
        case (address)
          // Write operations.
          ADDR_NAME0: begin
            name0_we <= 1;
          end
          ADDR_NAME1: begin
            name1_we <= 1;
          end
          ADDR_VERSION: begin
            version_we <= 1;
          end
          default: begin
            tmp_error = 1;
          end
        endcase // case (address)
      end // if (we)
      else begin
        case (address)
          // Read operations.
          ADDR_NAME0: begin
            tmp_read_data = name0;
          end
          ADDR_NAME1: begin
            tmp_read_data = name1;
          end
          ADDR_VERSION: begin
            tmp_read_data = version;
          end
          default: begin
            tmp_error = 1;
          end
        endcase // case (address)
      end
    end
  end // addr_decoder

  // TODO: Implement debug and control port logic.

endmodule

module flip_flop (
