module transition_detector (
    input clk,
    input reset,           // Synchronous active-high reset
    input [31:0] in,
    output reg [31:0] out
);

reg [31:0] prev_in;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        out <= 32'b0;
        prev_in <= 32'b0;
    end else begin
        out <= (in & ~prev_in);
        prev_in <= in;
    end
end

endmodule

