module AddReg (
  input clk, rst, load,
  input [0:0] D,
  output [0:0] Q
);

  wire [0:0] Q_next;
  wire [0:0] Q_reset;

  assign Q_reset = 1'b0;
  assign Q_next = Q + D;

  always @(posedge clk) begin
    if (rst) begin
      Q <= Q_reset;
    end else if (load) begin
      Q <= D;
    end else begin
      Q <= Q_next;
    end
  end

endmodule

module binary_counter (
    input CLK,
    input CLR_B,
    input LOAD,
    input [log2(MAX_VALUE):0] DATA_IN,
    output reg [log2(MAX_VALUE):0] Q
);

parameter MAX_VALUE = 16;

always @(posedge CLK) begin
    if (CLR_B) begin
        Q <= 0;
    end else if (LOAD) begin
        Q <= DATA_IN;
    end else if (Q == MAX_VALUE) begin
        Q <= 0;
    end else begin
        Q <= Q + 1;
    end
end

endmodule

