// PLL implementation
// This implementation uses a delay-locked loop (DLL) architecture

module pll (
   input clk, // input clock
   input rst, // asynchronous active-low reset
   input fb, // feedback clock
   input en, // enable
   input [7:0] mult, // feedback clock multiplier
   input [7:0] div, // clock divider
   input [15:0] phase, // clock phase
   output reg locked, // locked status
   output reg out // output clock
);

   reg [7:0] cnt; // counter for feedback clock multiplier
   reg [7:0] div_cnt; // counter for clock divider
   reg [15:0] phase_cnt; // counter for clock phase
   reg [15:0] delay; // delay line
   reg [7:0] delay_sel; // delay line select
   reg [15:0] phase_sel; // phase select
   wire [7:0] fb_mult; // feedback clock multiplied by multiplier
   wire [15:0] fb_phase; // feedback clock phase shifted

   // feedback clock multiplier
   assign fb_mult = fb & {8{mult}};

   // feedback clock phase shift
   assign fb_phase = {8{fb}} << phase;

   // delay line
   always @(posedge clk, negedge rst) begin
      if(!rst) begin
         delay <= 0;
         delay_sel <= 0;
      end
      else begin
         delay <= {fb_mult,delay[15:8]};
         delay_sel <= delay[15:8];
      end
   end

   // phase select
   always @(posedge clk, negedge rst) begin
      if(!rst) begin
         phase_cnt <= 0;
         phase_sel <= 0;
      end
      else begin
         phase_cnt <= phase_cnt + 1;
         if(phase_cnt == div) begin
            phase_sel <= phase_sel + 1;
            phase_cnt <= 0;
         end
      end
   end

   // locked status
   always @(posedge clk, negedge rst) begin
      if(!rst) begin
         locked <= 0;
      end
      else begin
         locked <= (delay_sel == phase_sel);
      end
   end

   // output clock
   always @(posedge clk, negedge rst) begin
      if(!rst) begin
         cnt <= 0;
         div_cnt <= 0;
         out <= 0;
      end
      else begin
         cnt <= cnt + 1;
         if(cnt == mult) begin
            div_cnt <= div_cnt + 1;
            if(div_cnt == N) begin
               out <= ~out;
               div_cnt <= 0;
            end
         cnt <= 0;
         end
      end
   end

endmodule

// oh_pll implementation
// This implementation uses N instances of the pll module

module oh_pll_impl (
   input            clkin,    // primary clock input
   input 	      nreset, // async active low reset
   input 	      clkfb, // feedback clock
   input 	      pll_en, // enable pll   
   input [N*8-1:0]  clkdiv, // clock divider settings (per clock)
   input [N*16-1:0] clkphase, // clock phase setting (rise/fall edge)
   input [7:0]      clkmult, // feedback clock multiplier 	       
   output [N-1:0]   clkout, // output clocks
   output 	      locked // PLL locked status
   );

   wire [N-1:0] locked_int; // internal signal for locked status
   wire [N-1:0] out_int; // internal signal for output clocks

   genvar i;
   generate
      for(i=0; i<N; i=i+1) begin : pll_inst
         pll pll_inst (
            .clk(clkin),
            .rst(nreset),
            .fb(clkfb),
            .en(pll_en),
            .mult(clkmult),
            .div(clkdiv[i*8 +: 8]),
            .phase(clkphase[i*16 +: 16]),
            .locked(locked_int[i]),
            .out(out_int[i])
         );
      end
   endgenerate

   assign clkout = out_int;
   assign locked = &locked_int;

endmodule

module top_module(
    input clk,
    input reset,
    input [254:0] in,
    output [7:0] out
);

    // Define the shift register
    reg [254:0] shift_reg;
    always @(posedge clk) begin
        if (reset) begin
            shift_reg <= 255'b0;
        end else begin
            shift_reg <= {shift_reg[253:0], in};
        end
    end

    // Define the adder
    reg [7:0] count;
    always @(posedge clk) begin
        if (reset) begin
            count <= 8'b0;
        end else begin
            count <= count + (~shift_reg[0]);
        end
    end

    // Define the comparator
    assign out = (count == 8'hFF);

endmodule

