module CDC_synchronizer (
  input data_in,
  input clk_in,
  input clk_out,
  input reset,
  output reg data_out
);

reg [1:0] sync_data;
reg [1:0] sync_clk;

always @(posedge clk_in or negedge reset) begin
  if (~reset) begin
    sync_data <= 2'b0;
    sync_clk <= 2'b0;
  end else begin
    sync_data <= {sync_data[0], data_in};
    sync_clk <= {sync_clk[0], clk_in};
  end
end

always @(posedge clk_out or negedge reset) begin
  if (~reset) begin
    data_out <= 1'b0;
  end else begin
    if (sync_clk[1] != sync_clk[0]) begin
      data_out <= sync_data[0];
    end else begin
      data_out <= sync_data[1];
    end
  end
end

endmodule

