module top_module (
    input clk,
    input reset,   // Synchronous active-high reset
    input [3:1] ena, // Enable signals for the BCD counter
    output [2:0] pos, // Output of the priority encoder
    output reg out // Final output after performing logical AND operation
);

    reg [3:0] bcd_counter = 4'b0000; // 4-digit BCD counter
    wire [3:0] bcd_counter_wire = bcd_counter; // Wire for connecting to priority encoder
    wire [2:0] priority_encoder_out; // Output of the priority encoder

    // BCD counter module
    always @(posedge clk) begin
        if (reset) begin
            bcd_counter <= 4'b0000;
        end else begin
            if (ena[0]) begin
                bcd_counter[0] <= bcd_counter[0] + 1;
                if (bcd_counter[0] == 4'b1010) begin
                    bcd_counter[0] <= 4'b0000;
                    if (ena[1]) begin
                        bcd_counter[1] <= bcd_counter[1] + 1;
                        if (bcd_counter[1] == 4'b1010) begin
                            bcd_counter[1] <= 4'b0000;
                            if (ena[2]) begin
                                bcd_counter[2] <= bcd_counter[2] + 1;
                                if (bcd_counter[2] == 4'b1010) begin
                                    bcd_counter[2] <= 4'b0000;
                                    bcd_counter[3] <= bcd_counter[3] + 1;
                                    if (bcd_counter[3] == 4'b1010) begin
                                        bcd_counter[3] <= 4'b0000;
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end

    // Priority encoder module
    assign pos = priority_encoder_out;
    priority_encoder priority_encoder_inst (
        .in(bcd_counter_wire),
        .out(priority_encoder_out)
    );

    // Logical AND module
    always @(posedge clk) begin
        if (reset) begin
            out <= 1'b0;
        end else begin
            if (priority_encoder_out != 3'b000) begin
                out <= 1'b1;
            end else begin
                out <= 1'b0;
            end
        end
    end

endmodule

