module MULTADDSUB18X18 (
    input [17:0] A,
    input [17:0] B,
    input [53:0] C,
    input CLK,
    input CEA,
    input RSTA,
    input CEB,
    input RSTB,
    input CEC,
    input RSTC,
    input SIGNED,
    input RSTPIPE,
    input CEPIPE,
    input RSTCTRL,
    input CECTRL,
    input RSTCIN,
    input CECIN,
    input LOADC,
    input ADDSUB,
    output [53:0] Z,
    input RSTOUT,
    input CEOUT,
    input CIN
);

reg [17:0] A_reg;
reg [17:0] B_reg;
reg [53:0] C_reg;
reg [53:0] Z_reg;

wire [17:0] A_ext;
wire [17:0] B_ext;
wire [53:0] C_ext;
wire [53:0] Z_ext;

reg [17:0] A_pipe;
reg [17:0] B_pipe;
reg [53:0] C_pipe;
reg [53:0] Z_pipe;

reg [17:0] A_ctrl;
reg [17:0] B_ctrl;
reg [53:0] C_ctrl;
reg [53:0] Z_ctrl;

reg [53:0] C_in;
reg [1:0] C_in_ctrl;

reg [17:0] A_add;
reg [17:0] B_add;
reg [53:0] C_add;
reg [53:0] Z_add;

reg [17:0] A_sub;
reg [17:0] B_sub;
reg [53:0] C_sub;
reg [53:0] Z_sub;

// Sign extension
assign A_ext = (SIGNED && A[17]) ? {{14{1'b1}}, A[17:0]} : {{18{1'b0}}, A};
assign B_ext = (SIGNED && B[17]) ? {{14{1'b1}}, B[17:0]} : {{18{1'b0}}, B};
assign C_ext = (SIGNED && C[53]) ? {{10{1'b1}}, C[53:0]} : {{18{1'b0}}, C};

// Pipeline registers
always @(posedge CLK) begin
    if (RSTPIPE) begin
        A_pipe <= 18'd0;
        B_pipe <= 18'd0;
        C_pipe <= 54'd0;
        Z_pipe <= 54'd0;
    end else if (CEPIPE) begin
        A_pipe <= A_reg;
        B_pipe <= B_reg;
        C_pipe <= C_reg;
        Z_pipe <= Z_reg;
    end
end

// Control registers
always @(posedge CLK) begin
    if (RSTCTRL) begin
        A_ctrl <= 18'd0;
        B_ctrl <= 18'd0;
        C_ctrl <= 54'd0;
        Z_ctrl <= 54'd0;
    end else if (CECTRL) begin
        A_ctrl <= A_pipe;
        B_ctrl <= B_pipe;
        C_ctrl <= C_pipe;
        Z_ctrl <= Z_pipe;
    end
end

// Carry-in register
always @(posedge CLK) begin
    if (RSTCIN) begin
        C_in <= 54'd0;
        C_in_ctrl <= 2'd0;
    end else if (CECIN) begin
        C_in_ctrl <= ADDSUB ? 2'd1 : 2'd0;
        if (LOADC) begin
            C_in <= C_ext;
        end else if (ADDSUB == 0) begin
            C_in <= {2'd0, C_add[53:1]};
        end else begin
            C_in <= {2'd0, C_sub[53:1]};
        end
    end
end

// Addition
assign C_add = C_ctrl + C_in;
assign Z_add = {C_add[53], C_add[53:1] + A_ext + B_ext};
assign Z_reg = ADDSUB ? Z_sub : Z_add;

// Subtraction
assign C_sub = C_ctrl + (~C_in + 1);
assign Z_sub = {C_sub[53], C_sub[53:1] + A_ext - B_ext};

// Output register
always @(posedge CLK) begin
    if (RSTOUT) begin
        Z_reg <= 54'd0;
    end else if (CEOUT) begin
        Z_reg <= Z_pipe;
    end
end

// Output
assign Z = Z_ext;

endmodule

module fifo_sync_16bit
  (dout,
   din,
   wr_clk,
   rd_clk);

  parameter DEPTH = 8;

  input wr_clk;
  input [15:0]din;
  input rd_clk;
  output [15:0]dout;

  reg [15:0]fifo [0:DEPTH-1];
  reg wr_en = 0;
  reg rd_en = 0;
  reg [2:0]wr_ptr = 0;
  reg [2:0]rd_ptr = 0;
  wire fifo_full = (wr_ptr == rd_ptr) && wr_en && !rd_en;
  wire fifo_empty = (wr_ptr == rd_ptr) && !wr_en && rd_en;

  always @(posedge wr_clk) begin
    if (!fifo_full) begin
      fifo[wr_ptr] <= din;
      wr_ptr <= wr_ptr + 1;
      wr_en <= 1;
    end
  end

  always @(posedge rd_clk) begin
    if (!fifo_empty) begin
      dout <= fifo[rd_ptr];
      rd_ptr <= rd_ptr + 1;
      rd_en <= 1;
    end
  end

  always @(posedge wr_clk, posedge rd_clk) begin
    if (wr_ptr == DEPTH-1) begin
      wr_ptr <= 0;
    end
    if (rd_ptr == DEPTH-1) begin
      rd_ptr <= 0;
    end
    if (wr_en && rd_en) begin
      if (wr_ptr == rd_ptr) begin
        wr_en <= 0;
        rd_en <= 0;
      end
    end
  end

endmodule

