module booth_multiplier (
    input signed [3:0] A,
    input signed [3:0] B,
    output reg signed [7:0] C
);

    reg signed [3:0] P;
    reg signed [3:0] P_prev;
    reg signed [3:0] B_prev;
    integer i;

    always @(A or B) begin
        P_prev = 4'b0000;
        B_prev = {B[3], B[3:1]};
        C = 8'b00000000;
        for (i = 0; i < 4; i = i + 1) begin
            if (B[0] == 1'b1 && B_prev[0] == 1'b0) begin
                P = A;
            end else if (B[0] == 1'b0 && B_prev[0] == 1'b1) begin
                P = -A;
            end else begin
                P = 4'b0000;
            end
            P = {P[2:0], P[3]};
            C = C + {P, P_prev};
            P_prev = P;
            B_prev = {B[3], B[3:1]};
            B = {B[2:0], B[3]};
        end
        C = C >> 4;
    end

endmodule

