module parity_generator (
    input [7:0] in,
    output [8:0] out
);

wire [2:0] priority;
wire [7:0] encoded;

assign priority = {in[7], in[6], in[5]};
assign encoded = ~in & (in + 1);

reg parity;

always @* begin
    case (priority)
        3'b000: parity = encoded[2] ^ encoded[1] ^ encoded[0] ^ in[0];
        3'b001: parity = encoded[2] ^ encoded[1] ^ encoded[0] ^ in[1];
        3'b010: parity = encoded[2] ^ encoded[1] ^ encoded[0] ^ in[2];
        3'b011: parity = encoded[2] ^ encoded[1] ^ encoded[0] ^ in[3];
        3'b100: parity = encoded[2] ^ encoded[1] ^ encoded[0] ^ in[4];
        3'b101: parity = encoded[2] ^ encoded[1] ^ encoded[0] ^ in[5];
        3'b110: parity = encoded[2] ^ encoded[1] ^ encoded[0] ^ in[6];
        3'b111: parity = encoded[2] ^ encoded[1] ^ encoded[0] ^ in[7];
    endcase
end

assign out = {parity, in};

endmodule

