module saturation_enqcK #(
parameter
    ID                = 0,
    NUM_STAGE         = 1,
    din0_WIDTH       = 32,
    din1_WIDTH       = 32,
    din2_WIDTH       = 32,
    din3_WIDTH       = 32,
    din4_WIDTH         = 2,
    dout_WIDTH            = 32
)(
    input  signed [din0_WIDTH - 1 : 0]     din0,
    input  signed [din1_WIDTH - 1 : 0]     din1,
    input  signed [din2_WIDTH - 1 : 0]     din2,
    input  signed [din3_WIDTH - 1 : 0]     din3,
    input  [din4_WIDTH - 1 : 0]    din4,
    output signed [dout_WIDTH - 1 : 0]   dout);

// puts internal signals
wire [1 : 0]     sel;
// level 1 signals
wire [dout_WIDTH - 1 : 0]         mux_1_0;
wire [dout_WIDTH - 1 : 0]         mux_1_1;
// level 2 signals
wire [dout_WIDTH - 1 : 0]         mux_2_0;

assign sel = din4;

// Generate level 1 logic
assign mux_1_0 = (sel[0] == 0)? din0 : din1;
assign mux_1_1 = (sel[0] == 0)? din2 : din3;

// saturation logic
assign mux_1_0 = (mux_1_0 >= 0 && mux_1_0 <= (2**(dout_WIDTH-1)-1)) ? mux_1_0 : ((mux_1_0 < 0) ? 0 : (2**(dout_WIDTH-1)-1));
assign mux_1_1 = (mux_1_1 >= 0 && mux_1_1 <= (2**(dout_WIDTH-1)-1)) ? mux_1_1 : ((mux_1_1 < 0) ? 0 : (2**(dout_WIDTH-1)-1));

// Generate level 2 logic
assign mux_2_0 = (sel[1] == 0)? mux_1_0 : mux_1_1;

// enable logic
assign dout = (sel == 2'b00) ? 0 : ((sel[1] == 0 && mux_1_0 < 0) ? 0 : ((sel[1] == 1 && mux_1_1 < 0) ? 0 : mux_2_0));

endmodule

