module spi_receiver (
  // system signals
  input  wire        clk,
  input  wire        rst,
  // SPI signals
  input  wire        spi_sclk,
  input  wire        spi_mosi,
  input  wire        spi_cs_n,
  //
  input  wire        transmitting,
  output reg   [7:0] opcode,
  output reg  [31:0] opdata,
  output reg         execute
);

localparam READOPCODE = 1'h0;
localparam READLONG   = 1'h1;

reg state, next_state;			// receiver state
reg [1:0] bytecount, next_bytecount;	// count rxed bytes of current command
reg [7:0] next_opcode;		// opcode byte
reg [31:0] next_opdata;	// data dword
reg next_execute;

reg [2:0] bitcount, next_bitcount;	// count rxed bits of current byte
reg [7:0] spiByte, next_spiByte;
reg byteready, next_byteready;

dly_signal mosi_reg (clk, spi_mosi, sampled_mosi);
dly_signal dly_sclk_reg (clk, spi_sclk, dly_sclk);
wire sclk_posedge = !dly_sclk && spi_sclk;

dly_signal dly_cs_reg (clk, spi_cs_n, dly_cs);
wire cs_negedge = dly_cs && !spi_cs_n;


//
// Accumulate byte from serial input...
//
initial bitcount = 0;
always @(posedge clk, posedge rst)
if (rst) bitcount <= 0;
else     bitcount <= next_bitcount;

always @(posedge clk)
begin
  spiByte   <= next_spiByte;
  byteready <= next_byteready;
end

always @*
begin
  next_bitcount = bitcount;
  next_spiByte = spiByte;
  next_byteready = 1'b0;

  if (cs_negedge)
    next_bitcount = 0;

  if (sclk_posedge) // detect rising edge of sclk
    if (spi_cs_n)
      begin
        next_bitcount = 0;
        next_spiByte = 0;
      end
    else
      begin
        next_bitcount = bitcount + 1'b1;
        next_byteready = &bitcount;
        next_spiByte = {spiByte[6:0],sampled_mosi};
      end
end



//
// Command tracking...
//
initial state = READOPCODE;
always @(posedge clk, posedge rst) 
if (rst)  state <= READOPCODE;
else      state <= next_state;

initial opcode = 0;
initial opdata = 0;
always @(posedge clk) 
begin
  bytecount <= next_bytecount;
  opcode    <= next_opcode;
  opdata    <= next_opdata;
  execute   <= next_execute;
end

always @*
begin
  next_state = state;
  next_bytecount = bytecount;
  next_opcode = opcode;
  next_opdata = opdata;
  next_execute = 1'b0;

  case (state)
    READOPCODE : // receive byte
      begin
	next_bytecount = 0;
	if (byteready)
	  begin
	    next_opcode = spiByte;
	    if (spiByte[7])
	      next_state = READLONG;
	    else // short command
	      begin
		next_execute = 1'b1;
	  	next_state = READOPCODE;
	      end
	  end
      end

    READLONG : // receive 4 word parameter
      begin
	if (byteready)
	  begin
	    next_bytecount = bytecount + 1'b1;
	    next_opdata = {spiByte,opdata[31:8]};
	    if (&bytecount) // execute long command
	      begin
		next_execute = 1'b1;
	  	next_state = READOPCODE;
	      end
	  end
      end
  endcase
end

endmodule

module spi(
    input        clk,
    input        rsth,     // H:reset
    input        mod_sel,  // 
    input        req,      // H:request
    input  [3:0] command,  // 
    input  [17:0] wdata,   // 
    output [31:0] rdata,   // 
    output        ack,     // H:ack
    output        oSCL,     // 
    output        oDCX,     // 
    output        oCSX,     // 
    inout         oSDA     // 
);

  reg [31:0] read_data = 0;
  reg [5:0] read_pos = 6'b11_1111;
  reg req_1d;

  always @(negedge oSCL) begin
    req_1d <= req;
  end

  wire req_pe = ~req_1d & req;
  wire is_read_command = (command[3:2] == 2'b01);
  wire [1:0] readsize = command[1:0];

  always @(negedge oSCL or posedge req) begin
    if(rsth)                          read_pos = 6'b11_1111;
    else if(is_read_command & req_pe) read_pos = readsize * 8 + 8;
    else if(read_pos == 6'b11_1111)   read_pos = -1;
    else if(oCSX)                     read_pos = read_pos - 1;
  end

  always @(negedge oSCL) begin
    if(read_pos == 6'b11_1111) rdata = 0;
    else                       rdata = read_data[read_pos];
  end

  reg [31:0] write_data = 0;
  reg [5:0] write_pos = 6'b11_1111;
  reg req_1d_w;

  always @(negedge oSCL) begin
    req_1d_w <= req;
  end

  wire req_pe_w = ~req_1d_w & req;
  wire is_write_command = (command[3:2] == 2'b10);
  wire [1:0] writesize = command[1:0];

  always @(negedge oSCL or posedge req) begin
    if(rsth)                           write_pos = 6'b11_1111;
    else if(is_write_command & req_pe_w) write_pos = writesize * 8 + 8;
    else if(write_pos == 6'b11_1111)    write_pos = -1;
    else if(oCSX)                      write_pos = write_pos - 1;
  end

  always @(negedge oSCL) begin
    if(write_pos == 6'b11_1111) write_data <= 0;
    else if(write_pos == 6'b11_1110) write_data <= wdata;
    else if(write_pos == 6'b11_1101) write_data <= {write_data[15:0], wdata};
    else if(write_pos == 6'b11_1100) write_data <= {write_data[7:0], wdata};
    else if(write_pos == 6'b11_1011) write_data <= {write_data[23:0], wdata};
    else if(write_pos == 6'b11_1010) write_data <= {write_data[15:0], wdata};
    else if(write_pos == 6'b11_1001) write_data <= {write_data[7:0], wdata};
    else if(write_pos == 6'b11_1000) write_data <= {write_data[31:0], wdata};
    else if(oCSX) write_data <= {write_data[23:0], wdata};
  end

  reg [1:0] state = 2'b00;
  reg [1:0] next_state = 2'b00;

  always @(posedge clk) begin
    state <= next_state;
  end

  always @(*) begin
    oSCL = 1'b0;
    oSDA = 1'bz;
    oDCX = 1'b0;
    oCSX = 1'b1;

    case(state)
      2'b00: begin
        oCSX = 1'b0;
        oSDA = 1'b0;
        next_state = 2'b01;
      end
      2'b01: begin
        oSCL = 1'b1;
        next_state = 2'b10;
      end
      2'b10: begin
        oSCL = 1'b0;
        next_state = 2'b11;
      end
      2'b11: begin
        oSDA = (write_data[31-write_pos] == 1'b1) ? 1'b1 : 1'b0;
        oDCX = (write_pos == 6'b11_1111) ? 1'b1 : 1'b0;
        oSCL = 1'b1;
        next_state = 2'b00;
        if(write_pos != 6'b11_1111) write_pos <= write_pos - 1;
      end
    endcase
  end

  always @(*) begin
    ack = 1'b0;

    if(is_read_command) begin
      case(readsize)
        2'b00: ack = 1'b1;
        2'b01: ack = (read_pos == 6'b11_1110) ? 1'b1 : 1'b0;
        2'b10: ack = (read_pos == 6'b11_1110) ? 1'b1 : 1'b0;
        2'b11: ack = (read_pos == 6'b11_1110) ? 1'b1 : 1'b0;
      endcase
    end else begin
      case(writesize)
        2'b00: ack = 1'b1;
        2'b01: ack = (write_pos == 6'b11_1101) ? 1'b1 : 1'b0;
        2'b10: ack = (write_pos == 6'b11_1100) ? 1'b1 : 1'b0;
        2'b11: ack = (write_pos == 6'b11_1000) ? 1'b1 : 1'b0;
      endcase
    end
  end

endmodule

