module signed_mag_sqrt (
    input signed [3:0] a,
    output signed [3:0] sqrt,
    output error
);

reg signed [3:0] temp;
reg [1:0] count;
wire [3:0] temp_sqrt;

assign temp_sqrt = temp[3:2] ? 2'b10 : 2'b01;

always @(*) begin
    if (a < 0) begin
        error = 1;
        sqrt = 4'b0;
    end else begin
        error = 0;
        temp = a;
        count = 0;
        while (count < 2) begin
            temp[3:2] = temp_sqrt;
            count = count + 1;
        end
        sqrt = temp;
    end
end

endmodule

