module fsm_traffic_light (
  input clk,
  input reset,
  output reg green,
  output reg yellow,
  output reg red
);

parameter GREEN = 2'b00;
parameter YELLOW = 2'b01;
parameter RED = 2'b10;

reg [1:0] state;
reg [5:0] counter;

always @(posedge clk) begin
  if (reset) begin
    state <= GREEN;
    counter <= 0;
  end
  else begin
    case (state)
      GREEN: begin
        green <= 1;
        yellow <= 0;
        red <= 0;
        if (counter == 20) begin
          state <= YELLOW;
          counter <= 0;
        end
        else begin
          counter <= counter + 1;
        end
      end

      YELLOW: begin
        green <= 0;
        yellow <= 1;
        red <= 0;
        if (counter == 5) begin
          state <= RED;
          counter <= 0;
        end
        else begin
          counter <= counter + 1;
        end
      end

      RED: begin
        green <= 0;
        yellow <= 0;
        red <= 1;
        if (counter == 25) begin
          state <= GREEN;
          counter <= 0;
        end
        else begin
          counter <= counter + 1;
        end
      end
    endcase
  end
end

endmodule

