module BinarySearch (
  input clk,
  input reset,
  input [31:0] arr [0:1023],
  input [9:0] n,
  input [31:0] target,
  output reg [9:0] index
);

  reg [9:0] low = 0;
  reg [9:0] high = n - 1;
  reg [9:0] mid;

  always @(posedge clk) begin
    if (reset) begin
      index <= -1;
      low <= 0;
      high <= n - 1;
    end else begin
      if (low > high) begin
        index <= -1;
      end else begin
        mid = (low + high) / 2;
        if (arr[mid] == target) begin
          index <= mid;
        end else if (arr[mid] > target) begin
          high <= mid - 1;
        end else begin
          low <= mid + 1;
        end
      end
    end
  end

endmodule

module digital_clock(
  input clk,
  input reset,
  input set,
  input alarm,
  input [4:0] hours_set,
  input [5:0] minutes_set,
  input [5:0] seconds_set,
  output reg [4:0] hours,
  output reg [5:0] minutes,
  output reg [5:0] seconds,
  output reg [4:0] alarm_hours,
  output reg [5:0] alarm_minutes,
  output reg [5:0] alarm_seconds
);

  reg [4:0] hours_reg;
  reg [5:0] minutes_reg;
  reg [5:0] seconds_reg;
  reg [4:0] alarm_hours_reg;
  reg [5:0] alarm_minutes_reg;
  reg [5:0] alarm_seconds_reg;
  reg [4:0] hours_set_reg;
  reg [5:0] minutes_set_reg;
  reg [5:0] seconds_set_reg;
  reg alarm_triggered;

  always @(posedge clk) begin
    if (reset) begin
      hours_reg <= 5'b00000;
      minutes_reg <= 6'b000000;
      seconds_reg <= 6'b000000;
      alarm_hours_reg <= 5'b00000;
      alarm_minutes_reg <= 6'b000000;
      alarm_seconds_reg <= 6'b000000;
      alarm_triggered <= 0;
    end else if (set) begin
      hours_set_reg <= hours_set;
      minutes_set_reg <= minutes_set;
      seconds_set_reg <= seconds_set;
    end else if (hours_reg == hours_set_reg && minutes_reg == minutes_set_reg && seconds_reg == seconds_set_reg) begin
      alarm_triggered <= 1;
    end else if (alarm_triggered && !(hours_reg == alarm_hours_reg && minutes_reg == alarm_minutes_reg && seconds_reg == alarm_seconds_reg)) begin
      alarm_triggered <= 0;
    end else begin
      alarm_triggered <= alarm_triggered;
    end

    if (alarm_triggered) begin
      alarm_hours <= alarm_hours_reg;
      alarm_minutes <= alarm_minutes_reg;
      alarm_seconds <= alarm_seconds_reg;
    end else begin
      alarm_hours <= 5'b00000;
      alarm_minutes <= 6'b000000;
      alarm_seconds <= 6'b000000;
    end

    if (!set) begin
      if (seconds_reg == 59) begin
        seconds_reg <= 6'b000000;
        if (minutes_reg == 59) begin
          minutes_reg <= 6'b000000;
          if (hours_reg == 23) begin
            hours_reg <= 5'b00000;
          end else begin
            hours_reg <= hours_reg + 1;
          end
        end else begin
          minutes_reg <= minutes_reg + 1;
        end
      end else begin
        seconds_reg <= seconds_reg + 1;
      end
    end else begin
      hours_reg <= hours_set_reg;
      minutes_reg <= minutes_set_reg;
      seconds_reg <= seconds_set_reg;
    end

    hours <= hours_reg;
    minutes <= minutes_reg;
    seconds <= seconds_reg;
  end

endmodule

module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    input C_in,
    output [3:0] S,
    output C_out
);

wire [3:0] c;

full_adder fa0(.a(A[0]), .b(B[0]), .c_in(C_in), .s(S[0]), .c(c[0]));
full_adder fa1(.a(A[1]), .b(B[1]), .c_in(c[0]), .s(S[1]), .c(c[1]));
full_adder fa2(.a(A[2]), .b(B[2]), .c_in(c[1]), .s(S[2]), .c(c[2]));
full_adder fa3(.a(A[3]), .b(B[3]), .c_in(c[2]), .s(S[3]), .c(C_out));

endmodule

module full_adder(
    input a,
    input b,
    input c_in,
    output s,
    output c
);

wire w1, w2;

half_adder ha1(.a(a), .b(b), .s(w1), .c(w2));
half_adder ha2(.a(w1), .b(c_in), .s(s), .c(w3));
or_gate or1(.a(w2), .b(w3), .c(c));

endmodule

module half_adder(
    input a,
    input b,
    output s,
    output c
);

xor_gate xor1(.a(a), .b(b), .s(s));
and_gate and1(.a(a), .b(b), .s(c));

endmodule

module xor_gate(
    input a,
    input b,
    output s
);

assign s = a ^ b;

endmodule

module and_gate(
    input a,
    input b,
    output s
);

assign s = a & b;

endmodule

module or_gate(
    input a,
    input b,
    output c
);

assign c = a | b;

endmodule

module counter (
    input clk,
    input rst,
    output reg [3:0] count
);

always @(posedge clk) begin
    if (rst) begin
        count <= 4'b0;
    end else begin
        count <= count + 1;
    end
end

endmodule

module DFF_EN_CLK_GATE (
  input clk,
  input en,
  input te,
  input [31:0] d,
  output reg [31:0] q
);

  wire gated_clk;
  assign gated_clk = (en & te) ? clk : 1'b0;

  always @(posedge gated_clk) begin
    q <= d;
  end

endmodule

module UART_LOOPBACK(
	 // UART USB ports
	 input sys_clk, // 27 MHZ on SP605
    output CTS,// I am ready to receive data
    input RTS, // USB Clear to send
    output TX, // Output to USB
    input RX,  // Input to USB
	 output [7:0] TxD_par,
	 output TxD_ready
    );

	// LOOPBACK WIRES
	wire [7:0] RxD_par;
	wire RxD_start;

	// BAUD RATE DIVIDER
	reg [15:0] baud_div;

	// DATA REGISTERS
	reg [7:0] tx_data;
	reg [7:0] rx_data;

	// PARITY CHECKER
	reg parity_enable;
	reg parity;

	// STATE MACHINE
	reg [2:0] state;
	parameter IDLE = 3'b000;
	parameter START = 3'b001;
	parameter DATA = 3'b010;
	parameter PARITY = 3'b011;
	parameter STOP = 3'b100;

	// COUNTERS
	reg [2:0] bit_count;
	reg [3:0] parity_count;

	// OUTPUT REGISTERS
	reg cts_out;
	reg tx_out;

	// BAUD RATE DIVIDER
	always @(posedge sys_clk) begin
		if (baud_div == 16'd0) begin
			baud_div <= 16'd138; // 115200 baud rate
		end else begin
			baud_div <= baud_div - 1;
		end
	end

	// TX STATE MACHINE
	always @(posedge sys_clk) begin
		case (state)
			IDLE: begin
				if (!CTS) begin
					state <= START;
					tx_out <= 1'b0;
					bit_count <= 3'd0;
					parity_count <= 4'd0;
				end
			end

			START: begin
				if (baud_div == 16'd0) begin
					state <= DATA;
					tx_out <= 1'b1;
					bit_count <= 3'd1;
					parity_count <= 4'd0;
				end
			end

			DATA: begin
				if (baud_div == 16'd0) begin
					if (bit_count < 8) begin
						tx_out <= tx_data[bit_count];
						bit_count <= bit_count + 1;
						parity_count <= parity_count + tx_data[bit_count];
					end else begin
						state <= PARITY;
						tx_out <= parity;
						bit_count <= 3'd0;
						parity_count <= 4'd0;
					end
				end
			end

			PARITY: begin
				if (baud_div == 16'd0) begin
					state <= STOP;
					tx_out <= 1'b1;
					bit_count <= 3'd0;
					parity_count <= 4'd0;
				end
			end

			STOP: begin
				if (baud_div == 16'd0) begin
					state <= IDLE;
					tx_out <= 1'b1;
					bit_count <= 3'd0;
					parity_count <= 4'd0;
				end
			end
		endcase
	end

	// RX STATE MACHINE
	always @(posedge sys_clk) begin
		case (state)
			IDLE: begin
				if (RX == 1'b0) begin
					state <= START;
					rx_data <= 8'd0;
					bit_count <= 3'd0;
					parity_count <= 4'd0;
				end
			end

			START: begin
				if (baud_div == 16'd0) begin
					state <= DATA;
					bit_count <= 3'd1;
					parity_count <= 4'd0;
				end
			end

			DATA: begin
				if (baud_div == 16'd0) begin
					if (bit_count < 8) begin
						rx_data[bit_count] <= RX;
						bit_count <= bit_count + 1;
						parity_count <= parity_count + RX;
					end else begin
						state <= PARITY;
						parity <= (parity_enable && (parity_count % 2 == 0)) || (!parity_enable && (parity_count % 2 == 1));
						bit_count <= 3'd0;
						parity_count <= 4'd0;
					end
				end
			end

			PARITY: begin
				if (baud_div == 16'd0) begin
					state <= STOP;
					bit_count <= 3'd0;
					parity_count <= 4'd0;
				end
			end

			STOP: begin
				if (baud_div == 16'd0) begin
					state <= IDLE;
					if (cts_out && RTS) begin
						TxD_par <= rx_data;
						TxD_ready <= 1'b1;
					end else begin
						TxD_ready <= 1'b0;
					end
					bit_count <= 3'd0;
					parity_count <= 4'd0;
				end
			end
		endcase
	end

	// PARITY ENABLE
	always @(rx_data) begin
		parity_enable <= (rx_data[7] == 1'b1);
	end

	// CTS OUTPUT
	always @(posedge sys_clk) begin
		if (baud_div == 16'd0) begin
			cts_out <= (state == IDLE);
		end
	end

	assign CTS = cts_out;
	assign TX = tx_out;
	assign RxD_par = rx_data;
	assign RxD_start = (state == START);

endmodule

module CIRCUIT4(a, b, c, d, e, f, g, h, i, j, k, l, m, n, o, p, Clk, Rst, final);

    input Clk, Rst;
    input [7:0] a, b, c, d, e, f, g, h, i, j, k, l, m, n, o, p;
    output [31:0] final;

    wire [31:0] t1, t2, t3, t4, t5, t6, t7, t8, t9, t10, t11, t12, t13, t14;

    ADD #(8) add1(a, b, t1);
    ADD #(32) add2(t1, c, t2);
    ADD #(32) add3(t2, d, t3);
    ADD #(32) add4(t3, e, t4);
    ADD #(32) add5(t4, f, t5);
    ADD #(32) add6(t5, g, t6);
    ADD #(32) add7(t6, h, t7);
    ADD #(32) add8(t7, i, t8);
    ADD #(32) add9(t8, j, t9);
    ADD #(32) add10(t9, k, t10);
    ADD #(32) add11(t10, l, t11);
    ADD #(32) add12(t11, m, t12);
    ADD #(32) add13(t12, n, t13);
    ADD #(32) add14(t13, o, t14);

    REG #(32) reg1(t14, Clk, Rst, final);

endmodule

module usb_ep(
    input clk,

    input direction_in,
    input setup,
    input success,
    input[6:0] cnt,

    output reg toggle,
    output bank_usb,
    output reg[1:0] handshake,
    output bank_in,
    output bank_out,
    output in_data_valid
    );

localparam
    hs_ack = 2'b00,
    hs_none = 2'b01,
    hs_nak = 2'b10,
    hs_stall = 2'b11;

reg ep_setup;
reg ep_out_full;
reg ep_out_empty;
reg ep_in_full;
reg ep_out_stall;
reg ep_in_stall;
reg ep_out_toggle;
reg ep_in_toggle;
reg[6:0] ep_in_cnt;
reg[6:0] ep_out_cnt;

assign in_data_valid = (cnt != ep_in_cnt);
assign bank_usb = 1'b0;
assign bank_in = 1'b0;
assign bank_out = 1'b0;

always @(*) begin
    if (!direction_in && setup)
        toggle = 1'b0;
    else if (ep_setup)
        toggle = 1'b1;
    else if (direction_in)
        toggle = ep_in_toggle;
    else
        toggle = ep_out_toggle;
end

always @(*) begin
    if (direction_in) begin
        if (!ep_in_stall && !ep_setup && ep_in_full) begin
            handshake = hs_ack;
        end else if (!ep_setup && ep_in_stall) begin
            handshake = hs_stall;
        end else begin
            handshake = hs_nak;
        end
    end else begin
        if (setup || (!ep_out_stall && !ep_setup && ep_out_full)) begin
            handshake = hs_ack;
        end else if (!ep_setup && ep_out_stall) begin
            handshake = hs_stall;
        end else begin
            handshake = hs_nak;
        end
    end
end

always @(*) begin
    if (ctrl_dir_in) begin
        ctrl_rd_data[15:8] = ep_in_cnt;
        ctrl_rd_data[7:0] = { ep_in_toggle, ep_in_stall, 1'b0, !ep_in_full, ep_in_full };
    end else begin
        ctrl_rd_data[15:8] = ep_out_cnt;
        ctrl_rd_data[7:0] = { ep_out_toggle, ep_out_stall, ep_setup, ep_out_empty, ep_out_full };
    end
end

wire flush = ctrl_wr_data[5] || ctrl_wr_data[4] || ctrl_wr_data[3];

always @(posedge clk) begin
    if (success) begin
        if (direction_in) begin
            ep_in_full <= 1'b0;
            ep_in_toggle <= !ep_in_toggle;
        end else begin
            if (setup)
                ep_setup <= 1'b1;

            ep_out_toggle <= !ep_out_toggle;
            ep_out_empty <= 1'b0;
            ep_out_full <= 1'b0;
            ep_out_cnt <= cnt;
        end
    end

    if (ctrl_wr_en[1] && ctrl_dir_in) begin
        ep_in_cnt <= ctrl_wr_data[14:8];
    end

    if (ctrl_wr_en[0] && ctrl_dir_in) begin
        if (ctrl_wr_data[5]) begin
            ep_in_toggle <= 1'b0;
            ep_in_stall <= 1'b0;
        end
        if (ctrl_wr_data[4]) begin
            ep_in_toggle <= 1'b1;
            ep_in_stall <= 1'b0;
        end
        if (ctrl_wr_data[3])
            ep_in_stall <= 1'b1;

        if (flush)
            ep_in_full <= 1'b0;

        if (ctrl_wr_data[0])
            ep_in_full <= 1'b1;
    end

    if (ctrl_wr_en[0] && !ctrl_dir_in) begin
        if (ctrl_wr_data[5]) begin
            ep_out_toggle <= 1'b0;
            ep_out_stall <= 1'b0;
        end
        if (ctrl_wr_data[4]) begin
            ep_out_toggle <= 1'b1;
            ep_out_stall <= 1'b0;
        end
        if (ctrl_wr_data[3])
            ep_out_stall <= 1'b1;

        if (flush) begin
            ep_out_full <= 1'b0;
            ep_out_empty <= 1'b1;
        end

        if (ctrl_wr_data[2])
            ep_setup <= 1'b0;
        if (ctrl_wr_data[1])
            ep_out_empty <= 1'b1;
        if (ctrl_wr_data[0])
            ep_out_full <= 1'b1;
    end
end

endmodule

module clock_mgr (
    input CLKIN_IN,
    output CLKFX_OUT,
    output CLKIN_IBUFG_OUT,
    output CLK0_OUT
);

    wire CLKFB_IN;
    wire CLKFX_BUF;
    wire CLKIN_IBUFG;
    wire CLK0_BUF;
    wire GND_BIT;

    assign GND_BIT = 0;
    assign CLKIN_IBUFG_OUT = CLKIN_IBUFG;
    assign CLK0_OUT = CLKFB_IN;

    BUFG CLKFX_BUFG_INST (
        .I(CLKFX_BUF), 
        .O(CLKFX_OUT)
    );

    IBUFG CLKIN_IBUFG_INST (
        .I(CLKIN_IN), 
        .O(CLKIN_IBUFG)
    );

    BUFG CLK0_BUFG_INST (
        .I(CLK0_BUF), 
        .O(CLKFB_IN)
    );

    DCM_SP #(
        .CLK_FEEDBACK("1X"), 
        .CLKDV_DIVIDE(2.0), 
        .CLKFX_DIVIDE(1),
        .CLKFX_MULTIPLY(16),
        .CLKIN_DIVIDE_BY_2("FALSE"), 
        .CLKIN_PERIOD(20.0), 
        .CLKOUT_PHASE_SHIFT("NONE"), 
        .DESKEW_ADJUST("SYSTEM_SYNCHRONOUS"), 
        .DFS_FREQUENCY_MODE("LOW"), 
        .DLL_FREQUENCY_MODE("LOW"), 
        .DUTY_CYCLE_CORRECTION("TRUE"), 
        .FACTORY_JF(16'hC080), 
        .PHASE_SHIFT(0), 
        .STARTUP_WAIT("FALSE") 
    ) DCM_SP_INST (
        .CLKFB(CLKFB_IN), 
        .CLKIN(CLKIN_IBUFG), 
        .DSSEN(GND_BIT), 
        .PSCLK(GND_BIT), 
        .PSEN(GND_BIT), 
        .PSINCDEC(GND_BIT), 
        .RST(GND_BIT), 
        .CLKDV(), 
        .CLKFX(CLKFX_BUF), 
        .CLKFX180(), 
        .CLK0(CLK0_BUF), 
        .CLK2X(), 
        .CLK2X180(), 
        .CLK90(), 
        .CLK180(), 
        .CLK270(), 
        .LOCKED(), 
        .PSDONE(), 
        .STATUS()
    );

endmodule

module final_module (
  input [7:0] data_in,
  output [7:0] data_out,
  output [2:0] pos_out,
  output o2_out,
  output o1_out,
  output o0_out
);

  // Priority Encoder
  wire [2:0] priority;
  assign priority = ({data_in[7], data_in[6], data_in[5]} == 3'b000) ? 3'b000 :
                     ({data_in[7], data_in[6], data_in[4]} == 3'b000) ? 3'b001 :
                     ({data_in[7], data_in[5], data_in[4]} == 3'b000) ? 3'b010 :
                     ({data_in[6], data_in[5], data_in[4]} == 3'b000) ? 3'b011 :
                     ({data_in[7], data_in[6], data_in[3]} == 3'b000) ? 3'b100 :
                     ({data_in[7], data_in[5], data_in[3]} == 3'b000) ? 3'b101 :
                     ({data_in[6], data_in[5], data_in[3]} == 3'b000) ? 3'b110 :
                     3'b111;

  // Barrel Shifter
  wire [7:0] shifted_data;
  assign shifted_data = {data_in[0], data_in[0], data_in[0], data_in[0], data_in[0], data_in[0], data_in[0], data_in[0]} >> priority;

  assign o2_out = shifted_data[2];
  assign o1_out = shifted_data[1];
  assign o0_out = shifted_data[0];

  // Output MUX
  assign data_out = (shifted_data[priority] == 1'b1) ? data_in[priority] : 8'b0;
  assign pos_out = priority;

endmodule

module onehot_to_bin (
    input [ONEHOT_WIDTH-1:0] onehot,
    output [BIN_WIDTH-1:0] bin
);

parameter ONEHOT_WIDTH = 16;
parameter BIN_WIDTH = $clog2(ONEHOT_WIDTH-1);

genvar i,j;
generate
    for (j=0; j<BIN_WIDTH; j=j+1) begin : jl
        wire [ONEHOT_WIDTH-1:0] tmp_mask;
        for (i=0; i<ONEHOT_WIDTH; i=i+1) begin : il
            assign tmp_mask[i] = i == j;
        end
        assign bin[j] = |(tmp_mask & onehot);
    end
endgenerate

endmodule

module addsub(X, A, B, S, clk);
  output [3:0] X;
  input [3:0] A, B;
  input S, clk;

  wire [3:0] A_inv;
  wire [3:0] B_neg;
  wire [3:0] sum;
  wire C_out;

  // inverting A
  assign A_inv = ~A;

  // creating 2's complement of B
  assign B_neg = B + 1'b1;

  // ripple carry adder for A + B
  add4 ripple_carry_adder(sum, A, B, C_out, clk);

  // 1-bit multiplexer for selecting between sum and 2's complement of B
  mux4 mux(X, sum, B_neg, S);

  // inverting the output when S is high
  assign X = (S) ? ~X : X;

endmodule

module add4(sum, A, B, C_out, clk);
  output [3:0] sum;
  input [3:0] A, B;
  input clk;
  wire [3:0] carry;

  // 1-bit full adder
  add1 fa0(sum[0], A[0], B[0], 1'b0, clk);
  add1 fa1(sum[1], A[1], B[1], fa0[1], clk);
  add1 fa2(sum[2], A[2], B[2], fa1[1], clk);
  add1 fa3(sum[3], A[3], B[3], fa2[1], clk);

  // carry out of the last full adder
  assign C_out = fa3[2];

endmodule

module add1(sum, A, B, C_in, clk);
  output [1:0] sum;
  output C_out;
  input A, B, C_in, clk;
  wire xor1;
  wire and1;
  wire and2;

  // XOR gate for sum
  assign xor1 = A ^ B;

  // AND gate for carry out
  assign and1 = A & B;
  assign and2 = xor1 & C_in;

  // sum and carry out
  assign sum = {xor1, and1 | and2};
  assign C_out = and1 | and2;

endmodule

module mux4(Y, A, B, S);
  output [3:0] Y;
  input [3:0] A, B;
  input S;

  // 1-bit multiplexer for each bit
  assign Y[0] = (S) ? B[0] : A[0];
  assign Y[1] = (S) ? B[1] : A[1];
  assign Y[2] = (S) ? B[2] : A[2];
  assign Y[3] = (S) ? B[3] : A[3];

endmodule

module msg_rx(
    input clk_sys,
    input [0:7] data_in,
    input data_in_ready,
    output reg ready,
    output reg r,
    output reg w,
    output reg in,
    output reg pa,
    output reg ok,
    output reg pe,
    output reg en,
    output reg cpd,
    output reg cpr,
    output reg cpf,
    output reg cps,
    output reg [0:7] a1,
    output reg [0:15] a2,
    output reg [0:15] a3
);

    // Define states for the state machine
    localparam IDLE = 4'd0;
    localparam ARG  = 4'd1;
    localparam A1   = 4'd2;
    localparam A2H  = 4'd3;
    localparam A2L  = 4'd4;
    localparam A3H  = 4'd5;
    localparam A3L  = 4'd6;
    localparam DONE = 4'd7;

    // Define registers for storing decoded message
    reg [0:7] tcmd;
    reg [0:7] ta1;
    reg [0:15] ta2;
    reg [0:15] ta3;

    // Define wire for extracting arguments from decoded message
    wire [1:3] arg = tcmd[5:7];

    // Instantiate decoder module
    msg_cmd_dec MSG_CMD_DEC(
        .cmd(tcmd),
        .r(r),
        .w(w),
        .in(in),
        .pa(pa),
        .ok(ok),
        .pe(pe),
        .en(en),
        .cpd(cpd),
        .cpr(cpr),
        .cpf(cpf),
        .cps(cps)
    );

    // Define state machine for receiving message
    reg [0:2] state = IDLE;
    always @ (posedge clk_sys) begin
        ready <= 0;
        case (state)
            IDLE: begin
                if (data_in_ready) begin
                    tcmd <= data_in;
                    state <= ARG;
                end
            end
            ARG: begin
                if (arg[1]) state <= A1;
                else if (arg[2]) state <= A2H;
                else if (arg[3]) state <= A3H;
                else state <= DONE;
            end
            A1: begin
                if (data_in_ready) begin
                    ta1 <= data_in;
                    if (arg[2]) state <= A2H;
                    else if (arg[3]) state <= A3H;
                    else state <= DONE;
                end
            end
            A2H: begin
                if (data_in_ready) begin
                    ta2[0:7] <= data_in;
                    state <= A2L;
                end
            end
            A2L: begin
                if (data_in_ready) begin
                    ta2[8:15] <= data_in;
                    if (arg[3]) state <= A3H;
                    else state <= DONE;
                end
            end
            A3H: begin
                if (data_in_ready) begin
                    ta3[0:7] <= data_in;
                    state <= A3L;
                end
            end
            A3L: begin
                if (data_in_ready) begin
                    ta3[8:15] <= data_in;
                    state <= DONE;
                end
            end
            DONE: begin
                // Set output registers
                a1 <= ta1;
                a2 <= ta2;
                a3 <= ta3;
                ready <= 1;
                state <= IDLE;
            end
        endcase
    end
endmodule

module top_module( 
    input [1023:0] in,
    input [7:0] sel,
    output [3:0] out );

    wire [7:0] sel_decoded;
    wire [7:0] sel_inv;
    wire [31:0] mux_out;

    // Decoder to decode the selector input
    decoder dec(sel, sel_decoded);

    // Inverter to invert the selector input
    inv sel_inv_inst(sel, sel_inv);

    // 8-to-1 multiplexers to select the input bits
    mux8to1 mux0(in[3:0], in[7:4], in[11:8], in[15:12], in[19:16], in[23:20], in[27:24], in[31:28], sel_decoded[2:0], mux_out[3:0]);
    mux8to1 mux1(in[35:32], in[39:36], in[43:40], in[47:44], in[51:48], in[55:52], in[59:56], in[63:60], sel_decoded[5:3], mux_out[7:4]);
    mux8to1 mux2(in[67:64], in[71:68], in[75:72], in[79:76], in[83:80], in[87:84], in[91:88], in[95:92], sel_decoded[6], mux_out[11:8]);
    mux8to1 mux3(in[99:96], in[103:100], in[107:104], in[111:108], in[115:112], in[119:116], in[123:120], in[127:124], sel_decoded[7], mux_out[15:12]);
    mux8to1 mux4(in[131:128], in[135:132], in[139:136], in[143:140], in[147:144], in[151:148], in[155:152], in[159:156], sel_inv[0], mux_out[19:16]);
    mux8to1 mux5(in[163:160], in[167:164], in[171:168], in[175:172], in[179:176], in[183:180], in[187:184], in[191:188], sel_inv[1], mux_out[23:20]);
    mux8to1 mux6(in[195:192], in[199:196], in[203:200], in[207:204], in[211:208], in[215:212], in[219:216], in[223:220], sel_inv[2], mux_out[27:24]);
    mux8to1 mux7(in[227:224], in[231:228], in[235:232], in[239:236], in[243:240], in[247:244], in[251:248], in[255:252], sel_inv[3], mux_out[31:28]);

    // Output port
    assign out = mux_out[3:0];

endmodule

// 8-to-1 multiplexer module
module mux8to1(in0, in1, in2, in3, in4, in5, in6, in7, sel, out);

    output [3:0] out;
    input [3:0] in0, in1, in2, in3, in4, in5, in6, in7;
    input [2:0] sel;

    wire [3:0] mux1_out;
    wire [3:0] mux2_out;
    wire [3:0] mux3_out;
    wire [3:0] mux4_out;
    wire [3:0] mux5_out;
    wire [3:0] mux6_out;
    wire [3:0] mux7_out;

    // First level of 2-to-1 multiplexers
    mux2to1 mux1(in0, in1, sel[0], mux1_out);
    mux2to1 mux2(in2, in3, sel[0], mux2_out);
    mux2to1 mux3(in4, in5, sel[0], mux3_out);
    mux2to1 mux4(in6, in7, sel[0], mux4_out);

    // Second level of 2-to-1 multiplexers
    mux2to1 mux5(mux1_out, mux2_out, sel[1], mux5_out);
    mux2to1 mux6(mux3_out, mux4_out, sel[1], mux6_out);

    // Final level of 2-to-1 multiplexer
    mux2to1 mux7(mux5_out, mux6_out, sel[2], mux7_out);

    // Output
    assign out = mux7_out;

endmodule

// 2-to-1 multiplexer module
module mux2to1(in0, in1, sel, out);

    output [3:0] out;
    input [3:0] in0, in1;
    input sel;

    assign out = sel ? in1 : in0;

endmodule

// Decoder module
module decoder(sel, out);

    output [7:0] out;
    input [7:0] sel;

    assign out = 8'b0;
    assign out[sel] = 1'b1;

endmodule

// Inverter module
module inv(in, out);

    output [7:0] out;
    input [7:0] in;

    assign out = ~in;

endmodule

