module pipelined_adder(
    input [99:0] a,
    input [99:0] b,
    input cin,
    output [99:0] cout,
    output [99:0] sum
);

reg [99:0] p, g, c;
reg [99:0] s;

initial begin
    p = a & b;
    g = a | b;
    c[0] = cin;
    s[0] = a[0] ^ b[0] ^ cin;
end

generate
    genvar i;
    for (i = 1; i < 100; i = i + 1) begin : stage
        assign p[i] = s[i-1] & g[i];
        assign c[i] = p[i] | (s[i-1] & c[i-1]);
        assign s[i] = a[i] ^ b[i] ^ c[i];
    end
endgenerate

assign cout = c[99];
assign sum = s;

endmodule

