module spi_slave(
    input clk,
    input rst_n,
    input sck,
    input mosi,
    input ssel,
    output reg miso,
    output reg recived_status
);

reg [2:0] sckr;
reg [2:0] sselr;
reg [1:0] mosir;
reg [2:0] bitcnt;
reg [7:0] bytecnt;
reg byte_received;  // high when a byte has been received
reg [7:0] byte_data_received;
reg [7:0] received_memory;
reg [7:0] byte_data_sent;
reg [7:0] cnt;

wire ssel_active;
wire sck_risingedge;
wire sck_fallingedge;
wire ssel_startmessage;
wire ssel_endmessage;
wire mosi_data;

/*******************************************************************************
*detect the rising edge and falling edge of sck
*******************************************************************************/
always @(posedge clk or negedge rst_n)begin
	if(!rst_n)
		sckr <= 3'h0;
	else
		sckr <= {sckr[1:0],sck};
end

assign sck_risingedge = (sckr[2:1] == 2'b01) ? 1'b1 : 1'b0;
assign sck_fallingedge = (sckr[2:1] == 2'b10) ? 1'b1 : 1'b0;

/*******************************************************************************
*detect starts at falling edge and stops at rising edge of ssel
*******************************************************************************/
always @(posedge clk or negedge rst_n)begin
	if(!rst_n)
		sselr <= 3'h0;
	else
		sselr <= {sselr[1:0],ssel};
end

assign  ssel_active = (~sselr[1]) ? 1'b1 : 1'b0;  // SSEL is active low
assign  ssel_startmessage = (sselr[2:1]==2'b10) ? 1'b1 : 1'b0;  // message starts at falling edge
assign  ssel_endmessage = (sselr[2:1]==2'b01) ? 1'b1 : 1'b0;  // message stops at rising edge

/*******************************************************************************
*read from mosi
*******************************************************************************/
always @(posedge clk or negedge rst_n)begin
	if(!rst_n)
		mosir <= 2'h0;
	else
		mosir <={mosir[0],mosi};
end

assign mosi_data = mosir[1];

/*******************************************************************************
*SPI slave reveive in 8-bits format
*******************************************************************************/
always @(posedge clk or negedge rst_n)begin
  if(!rst_n)begin
	bitcnt <= 3'b000;
	byte_data_received <= 8'h0;
  end
  else begin
   if(~ssel_active)
     bitcnt <= 3'b000;
   else begin
      if(sck_risingedge)begin
        bitcnt <= bitcnt + 3'b001;
        byte_data_received <= {byte_data_received[6:0], mosi_data};
      end
		else begin
		  bitcnt <= bitcnt;
        byte_data_received <= byte_data_received;
		end
	  end
  end
end

always @(posedge clk or negedge rst_n) begin
	if(!rst_n)
		byte_received <= 1'b0;
	else
		byte_received <= ssel_active && sck_risingedge && (bitcnt==3'b111);
end

always @(posedge clk or negedge rst_n) begin
	if(!rst_n)begin
		bytecnt <= 8'h0;
		received_memory <= 8'h0;
	end
   else begin 
	 if(byte_received) begin
		  bytecnt <= bytecnt + 1'b1;
	     received_memory <= (byte_data_received == bytecnt) ? (received_memory + 1'b1) : received_memory;
	 end
	 else begin
		  bytecnt <= bytecnt;
	     received_memory <= received_memory;
	 end
	end
end

/*******************************************************************************
*SPI  slave send date 
*******************************************************************************/
always @(posedge clk or negedge rst_n) begin
	 if(!rst_n)
	  cnt<= 8'h0;
	 else begin
     if(byte_received) 
			cnt<=cnt+8'h1;  // count the messages
		else
			cnt<=cnt;
    end
end

always @(posedge clk or negedge rst_n) begin
    if(!rst_n)
		byte_data_sent <= 8'h0;
	 else begin
      if(ssel_active && sck_fallingedge) begin
          if(bitcnt==3'b000)
               byte_data_sent <= cnt;  // after that, we send 0s
           else
               byte_data_sent <= {byte_data_sent[6:0], 1'b0};
		end
		else
			byte_data_sent <= byte_data_sent;
	end
end

assign miso = byte_data_sent[7];  // send MSB first

always @(posedge clk or negedge rst_n) begin
	 if(!rst_n)
	  recived_status <= 1'b0;
	 else 
	  recived_status <= (received_memory == 8'd64) ? 1'b1 : 1'b0;
end

endmodule

module division_restoring_algorithm (
    input [7:0] a,
    input [7:0] b,
    output reg [7:0] out);

    reg [15:0] dividend;
    reg [7:0] divisor;
    reg [7:0] quotient;
    reg [3:0] count;

    always @(*) begin
        dividend = {a, 8'b0};
        divisor = b;
        quotient = 8'b0;
        count = 4'b0;
    end

    always @(posedge clk) begin
        if (count < 4'b1000) begin
            dividend = dividend << 1;
            quotient = quotient << 1;
            quotient[0] = dividend[15];
            dividend[15:8] = dividend[15:8] - divisor;
            if (dividend[15] == 1) begin
                dividend[15:8] = dividend[15:8] + divisor;
            end
            count = count + 1;
        end
        out <= quotient;
    end
endmodule

module top_module (
    input [7:0] a,
    input [7:0] b,
    output reg [7:0] out);

    division_restoring_algorithm div (
        .a(a),
        .b(b),
        .out(out)
    );

endmodule

module top_module (
    input clk,
    input reset,
    input [7:0] A,
    input [7:0] B,
    input select, // Select input to choose between division and shift register
    output reg [3:0] PAR_OUT,
    output reg valid
);

    reg [7:0] quotient;
    reg [7:0] remainder;
    wire [7:0] shifted_quotient;
    reg shift_enable;

    // Division module
    div_module div_inst(
        .clk(clk),
        .reset(reset),
        .A(A),
        .B(B),
        .quotient(quotient),
        .remainder(remainder)
    );

    // Shift register module
    shift_register_module shift_inst(
        .clk(clk),
        .reset(reset),
        .SER_IN(quotient),
        .SH_EN(shift_enable),
        .PAR_OUT(PAR_OUT)
    );

    // Control logic module
    always @(*) begin
        if (select == 0) begin
            shift_enable = 0;
            valid = 1;
        end else begin
            shift_enable = 1;
            valid = 1;
        end
    end

    // Output 0 on PAR_OUT if divisor is 0
    always @(posedge clk) begin
        if (B == 0) begin
            PAR_OUT <= 4'b0000;
            valid <= 0;
        end
    end

endmodule

module div_module (
    input clk,
    input reset,
    input [7:0] A,
    input [7:0] B,
    output reg [7:0] quotient,
    output reg [7:0] remainder
);

    reg [7:0] dividend;
    reg [7:0] divisor;
    reg [7:0] temp;
    reg [3:0] count;

    always @(posedge clk) begin
        if (reset) begin
            quotient <= 8'b0;
            remainder <= 8'b0;
            dividend <= 8'b0;
            divisor <= 8'b0;
            temp <= 8'b0;
            count <= 4'b0;
        end else begin
            dividend <= A;
            divisor <= B;
            count <= 4'b0;
            temp <= dividend;
            while (temp >= divisor) begin
                temp <= temp - divisor;
                count <= count + 1;
            end
            quotient <= count;
            remainder <= temp;
        end
    end

endmodule

module shift_register_module (
    input clk,
    input reset,
    input [7:0] SER_IN,
    input SH_EN,
    output reg [3:0] PAR_OUT
);

    reg [7:0] shift_reg;

    always @(posedge clk) begin
        if (reset) begin
            shift_reg <= 8'b0;
            PAR_OUT <= 4'b0;
        end else begin
            if (SH_EN) begin
                shift_reg <= {shift_reg[6:0], SER_IN[0]};
            end
            PAR_OUT <= shift_reg[3:0];
        end
    end

endmodule

module Control(
    Inst_i,
    Branch_o,
    Jump_o,
    Control_o
);
input		     [5:0]   Inst_i;
output reg	         Branch_o,Jump_o;
output reg 	[7:0]   Control_o;

always@(*) begin // R-type
    Branch_o = 0;
    Jump_o = 0;
    Control_o = 8'b0;
    case(Inst_i)
        6'b000000: begin // R-type
            Control_o[0] = 1;
            Control_o[1] = 0;
            Control_o[4] = 0;
            Control_o[5:6] = 2'b10;
            Control_o[7] = 1;
        end
        6'b001000: begin // addi
            Control_o[0] = 1;
            Control_o[1] = 0;
            Control_o[2] = 0;
            Control_o[4] = 1;
        end
        6'b101011: begin // sw
            Control_o[3] = 1;
            Control_o[4] = 1;
        end
        6'b100011: begin // lw
            Control_o[0] = 1;
            Control_o[1] = 1;
            Control_o[2] = 1;
            Control_o[4] = 1;
        end
        6'b000010: begin // j
            Jump_o = 1;
        end
        6'b000100: begin // beq
            Branch_o = 1;
            Control_o[5:6] = 2'b01;
        end
        default: begin // unused
            Control_o = 8'b0;
        end
    endcase
end

endmodule

module four_to_one (
    input A1,
    input A2,
    input B1,
    input B2,
    output X
);

    // Define intermediate signals
    wire w1, w2, w3;

    // Implement XOR gates
    assign w1 = A1 ^ A2;
    assign w2 = B1 ^ B2;

    // Implement AND gates
    assign w3 = w1 & w2;

    // Implement final XOR gate
    assign X = w3 ^ A2;

endmodule

module priority_encoder (
