);

    wire [2:0] inverted_in = ~in;
    wire [2:0] priority = {inverted_in[2], inverted_in[1], inverted_in[0]};

    assign out[0] = &inverted_in;
    assign out[1] = priority == 3'b100 ? 1'b1 : 1'b0;
    assign out[2] = priority == 3'b010 ? 1'b1 : 1'b0;
    assign out[3] = 1'b0;
    assign out[4] = priority == 3'b001 ? 1'b1 : 1'b0;
    assign out[5] = 1'b0;
    assign out[6] = 1'b0;
    assign out[7] = 1'b0;

endmodule

