module look_ahead_adder_4(
  input [3:0] A,
  input [3:0] B,
  output [3:0] SUM,
  output CARRY
);

  wire [3:0] x;
  wire [3:0] y;
  wire [3:0] z;
  wire [3:0] g;
  wire [3:0] p;
  wire [3:0] c;

  assign x = A ^ B;
  assign y = A & B;

  assign g[0] = x[0] & 1'b1;
  assign p[0] = y[0] | (x[0] & 1'b1);
  assign c[0] = g[0] | (p[0] & 1'b0);

  assign g[1] = x[1] & c[0];
  assign p[1] = y[1] | (x[1] & c[0]);
  assign c[1] = g[1] | (p[1] & c[0]);

  assign g[2] = x[2] & c[1];
  assign p[2] = y[2] | (x[2] & c[1]);
  assign c[2] = g[2] | (p[2] & c[1]);

  assign g[3] = x[3] & c[2];
  assign p[3] = y[3] | (x[3] & c[2]);
  assign CARRY = g[3] | (p[3] & c[2]);

  assign z = x & c;
  assign SUM = z ^ c;

endmodule

module Wait (reset, clk, PossibleStart, WriteChar, clk_2, check);

   input clk;
   input PossibleStart;
   input WriteChar;
   input reset;

   output reg clk_2;
   output reg check;

   parameter period = 10416;
   parameter n =14;
   parameter halfPeriod = period/2;
   reg [n:0]  counter;

   parameter period1 = 2;
   parameter n1 =1;
   parameter halfPeriod1 = period1/2;
   reg [n1:0]  counter1;

   reg [1:0]  current_state;
   reg [1:0]  next_state;

   parameter IDLE = 2'b00;
   parameter POSSIBLESTART = 2'b01;
   parameter READ = 2'b10;
   parameter PARITY = 2'b11;


   always @(posedge clk or posedge reset) begin
      if (reset == 1'b1) begin
	 counter = 0;
	 counter1 = 0;
	 clk_2=0;
	 check = 0;
	 next_state <= IDLE;
      end
      else begin
	 case (current_state)
	   IDLE: begin
	      if (PossibleStart==0)
		next_state<=IDLE;
	      else begin
		 next_state<=POSSIBLESTART;
		 clk_2=0;
	      end

	      if (WriteChar==1)
		next_state<=READ;

	      check=0;
	      counter=0;
	      if (counter1 == period1-1) begin
		 counter1 = 0;
		 clk_2 = 1;
	      end
	      else counter1 = counter1 +1'b1;
	      if (counter1 == halfPeriod1) clk_2 =0;
	   end // case: IDLE

	   POSSIBLESTART: begin
	      if (WriteChar==1) begin
		 next_state<=READ;
		 clk_2=1;
		 counter = 0;
	      end
	      if (WriteChar==0 && check==1)
		next_state<=IDLE;
	      if (WriteChar==0 && check==0)
		next_state<=POSSIBLESTART;

	      if (counter == halfPeriod-1) begin
		 counter=0;
		 check=1;
		 clk_2=1;

	      end
	      else
		counter = counter +1'b1;

	      if (counter1 == period1-1) begin
		 counter1 = 0;
		 clk_2 = 1;
	      end
	      else counter1 = counter1 +1'b1;
	      if (counter1 == halfPeriod1) clk_2 =0;
	   end // case: POSSIBLESTART

	   READ: begin
	      if (WriteChar==1)
		next_state<=READ;
	      else begin
		 next_state<=PARITY;
		 clk_2 = 0;
	      end

	      check=0;
	      if (counter == period-1) begin
		 counter = 0;
		 clk_2 = 1;
	      end
	      else counter = counter +1'b1;
	      if (counter == halfPeriod) clk_2 =0;

	   end // case: READ
	   PARITY: begin
	      if (clk_2==1)
		next_state<= IDLE;
	      else
		next_state<=PARITY;

	      if (counter == period-1) begin
		 counter = 0;
		 clk_2 = 1;
	      end
	      else counter = counter +1'b1;
	      if (counter == halfPeriod) clk_2 =0;

	   end // case: PARITY

	   default: begin
	      next_state<=IDLE;
	      check=0;
	      clk_2=0;
	   end

	 endcase // case (current_state)
      end // else: !if(reset == 1'b1)
   end // always @ (posedge clk)	  

   always @(negedge clk or posedge reset) begin
      if (reset == 1'b1)
	current_state<=IDLE;
      else
	current_state<=next_state;
   end

endmodule

