module delay_chain (
    input clk,
    input [5:0] delayctrlin,
    input [3:0] phasectrlin,
    output delayed_clkout
);

parameter sim_buffer_intrinsic_delay = 350;
parameter sim_buffer_delay_increment = 10;
parameter phasectrlin_limit = 7;

reg delayed_clk;
wire [5:0] delayctrl_bin;
integer acell_delay;
integer delay_chain_len;
integer clk_delay;

assign delayctrl_bin = {1'b0, delayctrlin[5:1]};

arriaiigz_ddr_gray_decoder m_delayctrl_in_dec(
    .gray_in(delayctrl_bin),
    .bin_out(delayctrlin)
);

always @(delayctrl_bin or phasectrlin)
begin
    acell_delay = sim_buffer_intrinsic_delay + delayctrl_bin * sim_buffer_delay_increment;

    if (phasectrlin > phasectrlin_limit) begin
        delay_chain_len = 0;
        $display($time, " Warning: DDR phasesetting %m has invalid setting %b", phasectrlin);
    end else if (phasectrlin == 0) begin
        delay_chain_len = delayctrlin;
    end else begin
        delay_chain_len = phasectrlin * (delayctrlin + 1);
    end

    clk_delay = delay_chain_len * acell_delay + 1;
end

always @(posedge clk)
    delayed_clk <= #(clk_delay) 1'b1;

assign delayed_clkout = delayed_clk;

endmodule

module SSCG (
  input clk_ref,
  input [1:0] spread_sel,
  output reg clk_sscg
);

parameter spread_rate = 5; // in percentage
parameter mod_rate = 10000; // in Hz

reg [31:0] cnt;
reg [31:0] mod_cnt;
reg [31:0] tri_cnt;
reg [31:0] tri_amp;

always @(posedge clk_ref) begin
  cnt <= cnt + 1;
  mod_cnt <= mod_cnt + 1;
  tri_cnt <= tri_cnt + 1;

  if (mod_cnt >= (50000000 / mod_rate)) begin
    mod_cnt <= 0;
  end

  if (tri_cnt >= (50000000 / (2 * mod_rate))) begin
    tri_cnt <= 0;
  end

  if (cnt >= (50000000 / (2 * mod_rate))) begin
    cnt <= 0;
  end

  if (spread_sel == 2'b00) begin
    tri_amp <= (50000000 * spread_rate) / (100 * mod_rate);
  end else if (spread_sel == 2'b01) begin
    tri_amp <= (50000000 * 2 * spread_rate) / (100 * mod_rate);
  end else if (spread_sel == 2'b10) begin
    tri_amp <= (50000000 * 3 * spread_rate) / (100 * mod_rate);
  end else if (spread_sel == 2'b11) begin
    tri_amp <= (50000000 * 4 * spread_rate) / (100 * mod_rate);
  end

  if (tri_cnt < tri_amp) begin
    clk_sscg <= 1;
  end else begin
    clk_sscg <= 0;
  end

  if (mod_cnt < (tri_amp / 2)) begin
    clk_sscg <= clk_sscg ^ 1;
  end
end

endmodule

module ripple_carry_adder(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout
);

    wire [3:0] carry;
    wire [3:0] sum;

    // Full adder for the first bit
    full_adder fa0(
        .A(A[0]),
        .B(B[0]),
        .Cin(Cin),
        .Sum(sum[0]),
        .Cout(carry[0])
    );

    // Full adder for the second bit
    full_adder fa1(
        .A(A[1]),
        .B(B[1]),
        .Cin(carry[0]),
        .Sum(sum[1]),
        .Cout(carry[1])
    );

    // Full adder for the third bit
    full_adder fa2(
        .A(A[2]),
        .B(B[2]),
        .Cin(carry[1]),
        .Sum(sum[2]),
        .Cout(carry[2])
    );

    // Full adder for the fourth bit
    full_adder fa3(
        .A(A[3]),
        .B(B[3]),
        .Cin(carry[2]),
        .Sum(sum[3]),
        .Cout(Cout)
    );

    assign Sum = sum;

endmodule

module full_adder(
    input A,
    input B,
    input Cin,
    output Sum,
    output Cout
);

    wire s1, s2, s3;

    // First XOR gate
    xor x1(
        .A(A),
        .B(B),
        .Z(s1)
    );

    // Second XOR gate
    xor x2(
        .A(s1),
        .B(Cin),
        .Z(s2)
    );

    // Third AND gate
    and a1(
        .A(A),
        .B(B),
        .Z(s3)
    );

    // Fourth AND gate
    and a2(
        .A(s1),
        .B(Cin),
        .Z(Cout)
    );

    // Final XOR gate
    xor x3(
        .A(s2),
        .B(s3),
        .Z(Sum)
    );

endmodule

