module ARM_CU_ALU(
    input MFC,
    input Reset,
    input Clk,
    input MEMSTORE,
    input MEMLOAD,
    input [31:0] MEMDAT,
    output reg [31:0] MEMADD,
    output reg MFA,
    output reg READ_WRITE,
    output reg WORD_BYTE
);

reg [2:0] state;
reg [31:0] mem_data;
reg [31:0] mem_addr;

parameter IDLE = 3'b000;
parameter FETCH = 3'b001;
parameter STORE = 3'b010;
parameter LOAD = 3'b011;

always @(posedge Clk) begin
    case (state)
        IDLE:
            if (MEMLOAD) begin
                state <= FETCH;
                MFA <= 1;
                READ_WRITE <= 1;
                WORD_BYTE <= 1;
                case (MEMADD[7:0])
                    8'h00: mem_addr <= 32'b11100010_00000001_00000000_00000000;
                    8'h01: mem_addr <= 32'b11100011_10000000_00010000_00101000;
                    8'h02: mem_addr <= 32'b11100111_11010001_00100000_00000000;
                    8'h03: mem_addr <= 32'b11100101_11010001_00110000_00000010;
                    8'h04: mem_addr <= 32'b11100000_10000000_01010000_00000000;
                    8'h05: mem_addr <= 32'b11100000_10000010_01010000_00000101;
                    8'h06: mem_addr <= 32'b11100010_01010011_00110000_00000001;
                    8'h07: mem_addr <= 32'b00011010_11111111_11111111_11111101;
                    8'h08: mem_addr <= 32'b11100101_11000001_01010000_00000011;
                    8'h09: mem_addr <= 32'b11101010_00000000_00000000_00000001;
                    8'h0A: mem_addr <= 32'b00001011_00000101_00000111_00000100;
                    8'h0B: mem_addr <= 32'b11101010_11111111_11111111_11111111;
                    default: mem_addr <= 32'h00000000;
                endcase
            end else if (MEMSTORE) begin
                state <= STORE;
                MFA <= 0;
                READ_WRITE <= 0;
                WORD_BYTE <= 1;
                mem_addr <= MEMADD;
                mem_data <= MEMDAT;
            end
        FETCH:
            if (MFC) begin
                state <= IDLE;
                MEMADD <= mem_addr;
                MEMDAT <= mem_data;
            end
        STORE:
            if (MFC) begin
                state <= IDLE;
            end
        LOAD:
            if (MFC) begin
                state <= IDLE;
                MEMADD <= mem_addr;
                MEMDAT <= mem_data;
            end
    endcase
end

always @(posedge Clk) begin
    if (Reset) begin
        state <= IDLE;
        MEMADD <= 0;
        MFA <= 0;
        READ_WRITE <= 0;
        WORD_BYTE <= 0;
        mem_data <= 0;
        mem_addr <= 0;
    end else begin
        case (state)
            IDLE:
                if (MEMLOAD || MEMSTORE) begin
                    state <= FETCH;
                end
            FETCH:
                if (!MFC) begin
                    state <= LOAD;
                end
            STORE:
                if (!MFC) begin
                    state <= IDLE;
                end
            LOAD:
                if (!MFC) begin
                    state <= IDLE;
                end
        endcase
    end
end

endmodule

