    access_size = 2'b10;
    enable = 1;
    rw = 1;
    #10;
    if (data_out !== 32'h12345678) $display("Error: data_out does not match expected value.");
    address = address + 4;
    access_size = 2'b10;
    enable = 1;
    rw = 1;
    #10;
    if (data_out !== 32'h9abcdef0) $display("Error: data_out does not match expected value.");
    address = address + 4;
    access_size = 2'b10;
    enable = 1;
    rw = 1;
    #10;
    if (data_out !== 32'hdeadbeef) $display("Error: data_out does not match expected value.");
    $finish;
end

