module ripple_carry_adder_with_overflow (
    input [31:0] A,
    input [31:0] B,
    output reg [31:0] S,
    output reg overflow
);

reg [3:0] C_in, C_out;
wire [3:0] A_i, B_i, S_i;

genvar i;

generate
    for (i = 0; i < 8; i = i + 1) begin : adder_block
        full_adder_4bit FA (
            .A(A[(i*4)+3:(i*4)]),
            .B(B[(i*4)+3:(i*4)]),
            .Cin(C_in),
            .S(S_i),
            .Cout(C_out)
        );

        assign A_i = A[(i*4)+3:(i*4)];
        assign B_i = B[(i*4)+3:(i*4)];

        always @(*) begin
            C_in = (i == 0) ? 1'b0 : C_out;
            S[(i*4)+3:(i*4)] = S_i;
        end
    end
endgenerate

assign overflow = (S[31] != C_out);

endmodule

module full_adder_4bit (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output reg [3:0] S,
    output reg Cout
);

always @(*) begin
    S = A ^ B ^ Cin;
    Cout = (A & B) | (Cin & (A ^ B));
end

endmodule

