module axi_arbiter (
  input rstn,
  input sw_clk,
  input [axi_qos_width-1:0] qos1,
  input [axi_qos_width-1:0] qos2,
  input prt_dv1,
  input prt_dv2,
  input [max_burst_bits-1:0] prt_data1,
  input [max_burst_bits-1:0] prt_data2,
  input [addr_width-1:0] prt_addr1,
  input [addr_width-1:0] prt_addr2,
  input [max_burst_bytes_width:0] prt_bytes1,
  input [max_burst_bytes_width:0] prt_bytes2,
  output reg prt_ack1,
  output reg prt_ack2,
  output reg prt_req,
  output reg [max_burst_bits-1:0] prt_data,
  output reg [addr_width-1:0] prt_addr,
  output reg [max_burst_bytes_width:0] prt_bytes,
  output reg [axi_qos_width-1:0] prt_qos
);

  parameter wait_req = 2'b00, serv_req1 = 2'b01, serv_req2 = 2'b10, wait_ack_low = 2'b11;
  reg [1:0] state, temp_state;

  always @(posedge sw_clk or negedge rstn) begin
    if (!rstn) begin
      state = wait_req;
      prt_req = 1'b0;
      prt_ack1 = 1'b0;
      prt_ack2 = 1'b0;
      prt_qos = 0;
    end else begin
      case (state)
        wait_req: begin
          state = wait_req;
          prt_ack1 = 1'b0;
          prt_ack2 = 1'b0;
          prt_req = 1'b0;
          if (prt_dv1 && !prt_dv2) begin
            state = serv_req1;
            prt_req = 1;
            prt_data = prt_data1;
            prt_addr = prt_addr1;
            prt_bytes = prt_bytes1;
            prt_qos = qos1;
          end else if (!prt_dv1 && prt_dv2) begin
            state = serv_req2;
            prt_req = 1;
            prt_qos = qos2;
            prt_data = prt_data2;
            prt_addr = prt_addr2;
            prt_bytes = prt_bytes2;
          end else if (prt_dv1 && prt_dv2) begin
            if (qos1 > qos2) begin
              prt_req = 1;
              prt_qos = qos1;
              prt_data = prt_data1;
              prt_addr = prt_addr1;
              prt_bytes = prt_bytes1;
              state = serv_req1;
            end else if (qos1 < qos2) begin
              prt_req = 1;
              prt_qos = qos2;
              prt_data = prt_data2;
              prt_addr = prt_addr2;
              prt_bytes = prt_bytes2;
              state = serv_req2;
            end else begin
              if (temp_state == serv_req1) begin
                prt_req = 1;
                prt_qos = qos2;
                prt_data = prt_data2;
                prt_addr = prt_addr2;
                prt_bytes = prt_bytes2;
                state = serv_req2;
              end else begin
                prt_req = 1;
                prt_qos = qos1;
                prt_data = prt_data1;
                prt_addr = prt_addr1;
                prt_bytes = prt_bytes1;
                state = serv_req1;
              end
            end
          end
        end
        serv_req1: begin
          state = serv_req1;
          prt_ack2 = 1'b0;
          if (prt_ack) begin
            prt_ack1 = 1'b1;
            prt_req = 0;
            if (prt_dv2) begin
              prt_req = 1;
              prt_qos = qos2;
              prt_data = prt_data2;
              prt_addr = prt_addr2;
              prt_bytes = prt_bytes2;
              state = serv_req2;
            end else begin
              temp_state = state;
              state = wait_ack_low;
            end
          end
        end
        serv_req2: begin
          state = serv_req2;
          prt_ack1 = 1'b0;
          if (prt_ack) begin
            prt_ack2 = 1'b1;
            prt_req = 0;
            if (prt_dv1) begin
              prt_req = 1;
              prt_qos = qos1;
              prt_data = prt_data1;
              prt_addr = prt_addr1;
              prt_bytes = prt_bytes1;
              state = serv_req1;
            end else begin
              temp_state = state;
              state = wait_ack_low;
            end
          end
        end
        wait_ack_low: begin
          prt_ack1 = 1'b0;
          prt_ack2 = 1'b0;
          state = wait_ack_low;
          if (!prt_ack) begin
            state = wait_req;
          end
        end
      endcase
    end
  end
endmodule

module signed_mag_comp (
    input signed [3:0] A,
    input signed [3:0] B,
    output reg C
);

    always @(*) begin
        if (A[3] == 0 && B[3] == 1) // A is positive, B is negative
            C = 1;
        else if (A[3] == 1 && B[3] == 0) // A is negative, B is positive
            C = 0;
        else if (A[3] == 0 && B[3] == 0) // Both A and B are positive
            C = (A >= B) ? 1 : 0;
        else if (A[3] == 1 && B[3] == 1) // Both A and B are negative
            C = (A <= B) ? 1 : 0;
    end

endmodule

module fifo_cdc (
   // Outputs
   wait_out, access_out, packet_out,
   // Inputs
   clk_in, reset_in, access_in, packet_in, clk_out, reset_out,
   wait_in
);

   parameter DW    = 104;
   parameter DEPTH = 16;

   /********************************/
   /*Incoming Packet               */
   /********************************/
   input              clk_in;   
   input              reset_in;
   input              access_in;   
   input [DW-1:0]     packet_in;   
   output             wait_out;   

   /********************************/
   /*Outgoing Packet               */
   /********************************/  
   input              clk_out;   
   input              reset_out;
   output             access_out;   
   output [DW-1:0]    packet_out;   
   input              wait_in;   

   //Local wires
   wire               wr_en;
   wire               rd_en;   
   wire               empty;
   wire               full;
   wire               valid;   
   reg                access_out;

   assign wr_en    = access_in & ~full;
   assign rd_en    = ~empty & ~wait_in;
   assign wait_out = full;

   //Keep access high until "acknowledge"
   always @ (posedge clk_out) begin
      if(reset_out) begin
         access_out <= 1'b0;
      end else if(~wait_in) begin
         access_out <= rd_en;
      end
   end

   //Read response fifo (from master)
   fifo_async  fifo (
      .prog_full(full), //stay safe for now
      .full(),
      // Outputs
      .dout(packet_out[DW-1:0]),
      .empty(empty),
      .valid(valid), 
      // Inputs
      .wr_rst(reset_in),
      .rd_rst(reset_out),
      .wr_clk(clk_in),
      .rd_clk(clk_out),
      .wr_en(wr_en),
      .din(packet_in[DW-1:0]),
      .rd_en(rd_en)
   );

endmodule

module fifo_async (
   input  wr_clk,
   input  rd_clk,
   input  wr_rst,
   input  rd_rst,
   input  wr_en,
   input  rd_en,
   input  [DW-1:0] din,
   output [DW-1:0] dout,
   output valid,
   output full,
   output empty,
   input  prog_full
);

   parameter DW    = 104;
   parameter DEPTH = 16;

   reg [DW-1:0] mem [0:DEPTH-1];
   reg [DW-1:0] dout_reg;
   reg [4:0]    wr_ptr;
   reg [4:0]    rd_ptr;
   reg          empty_reg;
   reg          full_reg;
   reg          valid_reg;
   reg          wr_clk_reg;
   reg          rd_clk_reg;

   initial begin
      wr_ptr = 5'b0;
      rd_ptr = 5'b0;
      empty_reg = 1'b1;
      full_reg = 1'b0;
      valid_reg = 1'b0;
      wr_clk_reg = 1'b0;
      rd_clk_reg = 1'b0;
   end

   always @ (posedge wr_clk) begin
      if (wr_rst) begin
         wr_ptr <= 5'b0;
         empty_reg <= 1'b1;
         full_reg <= 1'b0;
         wr_clk_reg <= 1'b0;
      end else if (wr_en) begin
         mem[wr_ptr] <= din;
         wr_ptr <= wr_ptr + 1;
         empty_reg <= 1'b0;
         if (wr_ptr == DEPTH-1) begin
            full_reg <= 1'b1;
         end
         wr_clk_reg <= ~wr_clk_reg;
      end
   end

   always @ (posedge rd_clk) begin
      if (rd_rst) begin
         rd_ptr <= 5'b0;
         full_reg <= 1'b0;
         empty_reg <= 1'b1;
         valid_reg <= 1'b0;
         rd_clk_reg <= 1'b0;
      end else if (rd_en) begin
         dout_reg <= mem[rd_ptr];
         rd_ptr <= rd_ptr + 1;
         full_reg <= 1'b0;
         if (rd_ptr == DEPTH-1) begin
            empty_reg <= 1'b1;
         end
         valid_reg <= 1'b1;
         rd_clk_reg <= ~rd_clk_reg;
      end
   end

   assign dout = dout_reg;
   assign full = full_reg;
   assign empty = empty_reg;
   assign valid = valid_reg & ~prog_full;

endmodule

module edge_detector (
    input clk,          // clock input
    input reset,        // reset input
    input a,            // input signal for edge detector
    input delay_param,  // delay parameter for edge detector
    output rise,        // output indicating rising edge
    output down         // output indicating falling edge
);

    reg a_dly1, a_dly2;
    reg rise_dly, down_dly;
    wire a_xor, a_xor_dly;
    wire rise_or, down_or;
    wire rise_and, down_and;

    // XOR gate to detect edge
    assign a_xor = a ^ a_dly1;
    assign a_xor_dly = a_dly1 ^ a_dly2;

    // OR gate to generate edge pulse
    assign rise_or = a_xor & a_xor_dly & ~a;
    assign down_or = a_xor & a_xor_dly & a;

    // AND gate to synchronize edge pulse with clock
    assign rise_and = rise_or & ~rise_dly;
    assign down_and = down_or & ~down_dly;

    // Delay-locked loop to synchronize edge detection with clock
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            a_dly1 <= 1'b0;
            a_dly2 <= 1'b0;
            rise_dly <= 1'b0;
            down_dly <= 1'b0;
        end else begin
            a_dly1 <= a;
            a_dly2 <= a_dly1;
            rise_dly <= rise_and | (rise_dly & ~delay_param);
            down_dly <= down_and | (down_dly & ~delay_param);
        end
    end

    // Output signals
    assign rise = rise_dly;
    assign down = down_dly;

endmodule

module not_gate (
    input in,    // input signal
    output out   // output signal
);

    wire in_not;

    // NAND gate to implement NOT gate
    assign in_not = ~(in & in);

    // Output signal
    assign out = in_not;

endmodule

module top_module (
    input clk,          // clock input
    input reset,        // reset input
    input a,            // input signal for edge detector
    input delay_param,  // delay parameter for edge detector
    output out          // output signal from NOT gate
);

    wire rise, down;

    // Edge detector module
    edge_detector detector (
        .clk(clk),
        .reset(reset),
        .a(a),
        .delay_param(delay_param),
        .rise(rise),
        .down(down)
    );

    // NOT gate module
    not_gate not_gate (
        .in(down),
        .out(out)
    );

    // AND gate to combine edge detector outputs
    assign out = rise & down;

endmodule

