    wire [7:0] uart_data_tx;
    wire uart_clock_enable_tx;
    wire uart_tx_pin_tx;
    wire uart_clock_tx;

    uart_tx #(.CLOCK_FREQ(CLOCK_FREQ), .BAUD_RATE(BAUD_RATE))
    SERIAL (
        .read_data(uart_data_tx),
        .read_clock_enable(uart_clock_enable_tx),
        .reset(reset),
