        .tx(uart_tx_pin_tx),
        .clock(ext_clock),
        .uart_clock(uart_clock_tx)
    );

    assign uart_tx_pin = uart_tx_pin_tx;
    assign uart_clock = uart_clock_tx;

    always @(posedge ext_clock) begin
        if (reset) begin
            uart_ready <= 0;
            uart_data <= 0;
            uart_clock_enable <= 0;
        end else begin
            if (empty_ringbuffer) begin
                uart_ready <= 0;
            end else begin
                uart_ready <= 1;
                uart_data <= write_data_ringbuffer[7:0];
                uart_clock_enable <= 1;
                if (uart_ready_tx) begin
                    write_clock_enable_ringbuffer <= 1;
                end
            end
        end
    end

    always @(posedge uart_clock_tx) begin
        if (uart_ready_tx) begin
            read_clock_enable_ringbuffer <= 1;
        end
    end

endmodule

module trace_cntrl_mul_32s_32s_32_7_MulnS_0(clk, ce, a, b, p);
input clk;
input ce;
input[32 - 1 : 0] a;
input[32 - 1 : 0] b;
output[32 - 1 : 0] p;

reg signed [32 - 1 : 0] a_reg0;
reg signed [32 - 1 : 0] b_reg0;
wire signed [32 - 1 : 0] tmp_product;
reg signed [32 - 1 : 0] buff0;
reg signed [32 - 1 : 0] buff1;
reg signed [32 - 1 : 0] buff2;
reg signed [32 - 1 : 0] buff3;
reg signed [32 - 1 : 0] buff4;

assign p = buff4;
assign tmp_product = a_reg0 * b_reg0;

always @ (posedge clk) begin
    if (ce) begin
        // Stage 0: Input register stage
        a_reg0 <= a;
        b_reg0 <= b;

        // Stage 1: Multiplication stage
        buff0 <= tmp_product;

        // Stage 2: Accumulation stage
        buff1 <= buff0 + buff1;
        buff2 <= buff1 + buff2;
        buff3 <= buff2 + buff3;

        // Stage 3: Output register stage
        buff4 <= buff3;
    end
end

endmodule

