module simple_calculator(
    input logic clk,
    input logic reset,
    input logic [1:0] op,
    input logic [31:0] A,
    input logic [31:0] B,
    output logic [31:0] sum,
    output logic [31:0] difference,
    output logic [31:0] product,
    output logic [31:0] quotient,
    output logic ready
);

    logic [31:0] temp;
    logic [31:0] temp2;
    logic [31:0] temp3;
    logic [31:0] temp4;

    always_ff@(posedge clk) begin
        if (reset) begin
            sum <= 0;
            difference <= 0;
            product <= 0;
            quotient <= 0;
            ready <= 1;
        end else begin
            case(op)
                2'b00: begin
                    temp <= A + B;
                    sum <= temp;
                end
                2'b01: begin
                    temp <= A - B;
                    difference <= temp;
                end
                2'b10: begin
                    temp <= A * B;
                    product <= temp;
                end
                2'b11: begin
                    temp <= A / B;
                    quotient <= temp;
                end
                default: begin
                    sum <= 0;
                    difference <= 0;
                    product <= 0;
                    quotient <= 0;
                end
            endcase

            ready <= 0;
            temp2 <= A;
            temp3 <= B;
            temp4 <= op;
        end
    end

    always_comb begin
        if (ready == 0) begin
            sum <= sum;
            difference <= difference;
            product <= product;
            quotient <= quotient;
        end else begin
            sum <= 0;
            difference <= 0;
            product <= 0;
            quotient <= 0;
        end
    end

    always_ff@(posedge clk) begin
        if (reset) begin
            A <= 0;
            B <= 0;
            op <= 0;
        end else if (ready == 1) begin
            A <= temp2;
            B <= temp3;
            op <= temp4;
        end
    end

endmodule

