module rot_pop_count(
    input clk,
    input load,
    input [1:0] ena,
    input [99:0] data,
    input select,
    output reg [7:0] out
);

reg [99:0] shift_reg;
reg [99:0] shifted_data;
reg [7:0] pop_count;

always @(negedge clk) begin
    if (load) begin
        shift_reg <= data;
    end else begin
        if (ena[0]) begin
            shifted_data <= {shift_reg[98:0], shift_reg[99]};
        end else if (ena[1]) begin
            shifted_data <= {shift_reg[1:99], shift_reg[0]};
        end else begin
            shifted_data <= shift_reg;
        end
        shift_reg <= shifted_data;
    end

    if (select) begin
        // Population count circuit
        pop_count <= {pop_count[6:0], (shifted_data[99] + shifted_data[98] + shifted_data[97] + shifted_data[96] + shifted_data[95] + shifted_data[94] + shifted_data[93] + shifted_data[92])};
        out <= pop_count;
    end else begin
        // Rotator module
        out <= shifted_data;
    end
end

endmodule

module piso_barrel_shift(
    input clk,
    input data_in,
    input shift_in,
    input reset,
    input [1:0] shift_amt,
    input dir,
    output [15:0] q
);

    reg [15:0] shift_reg;
    reg [15:0] shifted_output;
    wire [3:0] barrel_out;

    // PISO Shift Register
    always @(posedge clk) begin
        if (reset) begin
            shift_reg <= 16'b0;
        end else if (shift_in) begin
            shift_reg <= {shift_reg[14:0], data_in};
        end
    end

    // Barrel Shifter
    barrel_shifter barrel(
        .data_in(shift_reg),
        .shift_amt(shift_amt),
        .dir(dir),
        .barrel_out(barrel_out)
    );

    // Adder
    always @(*) begin
        if (dir == 0) begin
            shifted_output = {barrel_out, 4'b0};
        end else begin
            shifted_output = {4'b0, barrel_out};
        end
        q = shifted_output + shift_reg;
    end

endmodule

module barrel_shifter(
    input [15:0] data_in,
    input [1:0] shift_amt,
    input dir,
    output [3:0] barrel_out
);

    wire [15:0] shifted_input;

    // Left Shifter
    assign shifted_input = (dir == 0) ? (data_in << shift_amt) : (data_in >> shift_amt);

    // Barrel Shifter
    assign barrel_out[0] = shifted_input[15];
    assign barrel_out[1] = shifted_input[14] ^ shifted_input[15];
    assign barrel_out[2] = shifted_input[13] ^ shifted_input[14] ^ shifted_input[15];
    assign barrel_out[3] = shifted_input[12] ^ shifted_input[13] ^ shifted_input[14] ^ shifted_input[15];

endmodule

module arithmetic(
    input [7:0] A,
    input [7:0] B,
    input [1:0] op,
    output reg [7:0] result,
    output reg error
);

always @(*) begin
    case(op)
        2'b00: result = A + B;
        2'b01: result = A - B;
        2'b10: result = A * B;
        2'b11: begin
            if(B == 0) begin
                result = 8'b0;
                error = 1;
            end
            else begin
                result = A / B;
                error = 0;
            end
        end
    endcase
end

endmodule

