        .LOAD_IN(LOAD_IN),
        .Q3(Q3),
        .Q2(Q2),
        .Q1(Q1),
        .Q0(Q0)
    );

    // Perform bitwise AND operation between the outputs of the ALU and counter modules
    assign and_out = alu_out & {Q3,Q2,Q1,Q0};

    // Concatenate the 4-bit counter output and the 4-bit ALU output to get an 8-bit output
