            OUT <= 8'b0;
        end else if (LD) begin
            OUT <= {4'b0, LOAD_IN};
        end else if (UD) begin
            OUT <= {4'b0, and_out};
        end else begin
            OUT <= {4'b0, {Q3,Q2,Q1,Q0}};
        end
    end

endmodule

