module sevenSegCounter(
    input clk,
    input btn,
    input reset,
    output reg [6:0] seg
);

reg [3:0] counter = 4'b0000;
reg [3:0] pauseCounter = 4'b0000;
reg [2:0] state = 3'b000;
reg pause = 1'b0;

always @(posedge clk) begin
    if (reset) begin
        counter <= 4'b0000;
        pauseCounter <= 4'b0000;
        state <= 3'b000;
        pause <= 1'b0;
    end else begin
        case (state)
            3'b000: begin // increment counter
                if (pause) begin
                    pauseCounter <= pauseCounter + 1;
                    if (pauseCounter == 4'd9) begin
                        pauseCounter <= 4'b0000;
                        pause <= 1'b0;
                    end
                end else begin
                    counter <= counter + 1;
                    if (counter == 4'd9) begin
                        counter <= 4'b0000;
                    end
                end
                seg <= getSeg(counter);
                state <= 3'b001;
            end
            3'b001: begin // wait for one second
                if (!pause && (pauseCounter == 4'b0000)) begin
                    state <= 3'b010;
                end
            end
            3'b010: begin // decrement pause counter
                pauseCounter <= pauseCounter - 1;
                if (pauseCounter == 4'b0000) begin
                    state <= 3'b000;
                end
            end
        endcase
    end
end

always @(posedge clk) begin
    if (btn) begin
        if (pauseCounter == 4'b0000) begin
            pause <= ~pause;
        end
    end
end

function [6:0] getSeg;
    input [3:0] num;
    begin
        case (num)
            4'd0: getSeg = 7'b1000000;
            4'd1: getSeg = 7'b1111001;
            4'd2: getSeg = 7'b0100100;
            4'd3: getSeg = 7'b0110000;
            4'd4: getSeg = 7'b0011001;
            4'd5: getSeg = 7'b0010010;
            4'd6: getSeg = 7'b0000010;
            4'd7: getSeg = 7'b1111000;
            4'd8: getSeg = 7'b0000000;
            4'd9: getSeg = 7'b0010000;
            default: getSeg = 7'b1111111;
        endcase
    end
endfunction

endmodule

