module float_arithmetic (
  input [31:0] operand1,
  input [31:0] operand2,
  input [1:0] sel,
  output [31:0] result
);

  // Extracting sign, exponent, and mantissa of operand1
  wire sign1 = operand1[31];
  wire [7:0] exp1 = operand1[30:23];
  wire [22:0] mant1 = operand1[22:0];

  // Extracting sign, exponent, and mantissa of operand2
  wire sign2 = operand2[31];
  wire [7:0] exp2 = operand2[30:23];
  wire [22:0] mant2 = operand2[22:0];

  // Initializing variables for result calculation
  wire [24:0] mant_res;
  wire [8:0] exp_res;
  wire sign_res;

  // Addition operation
  wire [24:0] mant_add;
  wire [8:0] exp_add;
  wire sign_add;
  assign {sign_add, exp_add, mant_add} = (sign1 == sign2) ? {sign1, exp1, mant1} + {1'b0, exp2, mant2} : {sign1, exp1, mant1} - {1'b0, exp2, mant2};

  // Subtraction operation
  wire [24:0] mant_sub;
  wire [8:0] exp_sub;
  wire sign_sub;
  assign {sign_sub, exp_sub, mant_sub} = (sign1 == sign2) ? {sign1, exp1, mant1} - {1'b0, exp2, mant2} : {sign1, exp1, mant1} + {1'b0, exp2, mant2};

  // Multiplication operation
  wire [24:0] mant_mul;
  wire [8:0] exp_mul;
  wire sign_mul;
  assign {sign_mul, exp_mul, mant_mul} = {sign1 ^ sign2, exp1 + exp2 - 127'h7f, mant1 * mant2};

  // Division operation
  wire [24:0] mant_div;
  wire [8:0] exp_div;
  wire sign_div;
  assign {sign_div, exp_div, mant_div} = {sign1 ^ sign2, exp1 - exp2 + 127'h7f, mant1 / mant2};

  // Rounding the result to the nearest representable floating-point number
  wire [24:0] mant_round;
  wire [8:0] exp_round;
  wire sign_round;
  assign {sign_round, exp_round, mant_round} = (sel == 2'b00) ? {sign_add, exp_add, mant_add} :
                                               (sel == 2'b01) ? {sign_sub, exp_sub, mant_sub} :
                                               (sel == 2'b10) ? {sign_mul, exp_mul, mant_mul} :
                                                                 {sign_div, exp_div, mant_div};
  assign result = {sign_round, exp_round, mant_round};

endmodule

module adder(
  input [7:0] A,
  input [7:0] B,
  input carry_in,
  output [7:0] sum,
  output carry_out
);

  wire [7:0] carry;
  wire [7:0] temp_sum;

  assign sum = temp_sum;
  assign carry_out = carry[7];

  full_adder fa0(A[0], B[0], carry_in, temp_sum[0], carry[0]);
  full_adder fa1(A[1], B[1], carry[0], temp_sum[1], carry[1]);
  full_adder fa2(A[2], B[2], carry[1], temp_sum[2], carry[2]);
  full_adder fa3(A[3], B[3], carry[2], temp_sum[3], carry[3]);
  full_adder fa4(A[4], B[4], carry[3], temp_sum[4], carry[4]);
  full_adder fa5(A[5], B[5], carry[4], temp_sum[5], carry[5]);
  full_adder fa6(A[6], B[6], carry[5], temp_sum[6], carry[6]);
  full_adder fa7(A[7], B[7], carry[6], temp_sum[7], carry[7]);

endmodule

module full_adder(
  input a,
  input b,
  input carry_in,
  output sum,
  output carry_out
);

  assign sum = a ^ b ^ carry_in;
  assign carry_out = (a & b) | (a & carry_in) | (b & carry_in);

endmodule

module edge_detector (
    input clk,
    input reset,
    input [7:0] in,
    output reg [3:0] out,
    output reg [2:0] select,
    output reg [3:0] counter,
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5
);

    // Define states
    parameter IDLE = 2'b00;
    parameter RISING_EDGE = 2'b01;
    parameter FALLING_EDGE = 2'b10;

    // Define counters
    parameter COUNTER_IDLE = 2'b00;
    parameter COUNTER_ONE_EDGE = 2'b01;
    parameter COUNTER_TWO_EDGES = 2'b10;

    // Define signals
    reg [1:0] state;
    reg [1:0] next_state;
    reg [1:0] counter_state;
    reg [1:0] next_counter_state;
    reg edge_detected;
    reg [2:0] mux_select;

    // Detect edges
    always @(posedge clk, negedge reset) begin
        if (reset == 0) begin
            state <= IDLE;
            counter_state <= COUNTER_IDLE;
            edge_detected <= 0;
        end else begin
            state <= next_state;
            counter_state <= next_counter_state;
            edge_detected <= 0;
            case (state)
                IDLE: begin
                    if (in[0] == 1'b1) begin
                        next_state = RISING_EDGE;
                        edge_detected = 1;
                    end else begin
                        next_state = IDLE;
                    end
                end
                RISING_EDGE: begin
                    if (in[0] == 1'b0) begin
                        next_state = FALLING_EDGE;
                        edge_detected = 1;
                    end else begin
                        next_state = RISING_EDGE;
                    end
                end
                FALLING_EDGE: begin
                    if (in[0] == 1'b1) begin
                        next_state = RISING_EDGE;
                        edge_detected = 1;
                    end else begin
                        next_state = FALLING_EDGE;
                    end
                end
            endcase
        end
    end

    // Count edges
    always @(posedge clk, negedge reset) begin
        if (reset == 0) begin
            counter <= 0;
        end else begin
            counter <= counter + edge_detected;
            case (counter)
                COUNTER_IDLE: begin
                    next_counter_state = COUNTER_IDLE;
                end
                COUNTER_ONE_EDGE: begin
                    next_counter_state = COUNTER_ONE_EDGE;
                end
                COUNTER_TWO_EDGES: begin
                    next_counter_state = COUNTER_TWO_EDGES;
                end
                default: begin
                    next_counter_state = COUNTER_IDLE;
                end
            endcase
        end
    end

    // Select data input based on edge detection
    always @(posedge clk, negedge reset) begin
        if (reset == 0) begin
            select <= 0;
            mux_select <= 6;
            out <= 0;
        end else begin
            select <= counter_state;
            case (mux_select)
                0: begin
                    out <= data0;
                end
                1: begin
                    out <= data1;
                end
                2: begin
                    out <= data2;
                end
                3: begin
                    out <= data3;
                end
                4: begin
                    out <= data4;
                end
                5: begin
                    out <= data5;
                end
                default: begin
                    out <= 4'b1;
                end
            endcase
            if (counter_state == COUNTER_IDLE) begin
                mux_select <= 6;
            end else if (counter_state == COUNTER_ONE_EDGE) begin
                mux_select <= select;
            end else if (counter_state == COUNTER_TWO_EDGES) begin
                mux_select <= select + 1;
            end
        end
    end

endmodule

