module fsm_sequence_detection (
  input clk,
  input reset,
  input in,
  output reg match
);

  parameter IDLE = 2'b00, S1 = 2'b01, S2 = 2'b10, DETECTED = 2'b11;
  reg [1:0] state;
  reg [4:0] count;
  reg [4:0] match_count;
  reg [4:0] detect_count;
  reg [4:0] reset_count;

  always @(posedge clk) begin
    if (reset) begin
      state <= IDLE;
      count <= 0;
      match_count <= 0;
      detect_count <= 0;
      reset_count <= 0;
      match <= 0;
    end
    else begin
      case (state)
        IDLE: begin
          if (in == 5'b10101) begin
            state <= DETECTED;
            match <= 1;
            match_count <= 0;
            detect_count <= 0;
            reset_count <= 0;
          end
          else begin
            state <= S1;
            count <= 0;
            match_count <= 0;
            detect_count <= 0;
            reset_count <= 0;
          end
        end
        S1: begin
          if (in == 1'b1) begin
            state <= S2;
            count <= 0;
            match_count <= 0;
            detect_count <= 0;
            reset_count <= 0;
          end
          else begin
            state <= IDLE;
            count <= 0;
            match_count <= 0;
            detect_count <= 0;
            reset_count <= 0;
          end
        end
        S2: begin
          if (in == 1'b0) begin
            state <= S1;
            count <= 0;
            match_count <= 0;
            detect_count <= 0;
            reset_count <= 0;
          end
          else if (count == 3) begin
            state <= DETECTED;
            match <= 1;
            match_count <= 0;
            detect_count <= 0;
            reset_count <= 0;
          end
          else begin
            state <= S2;
            count <= count + 1;
            match_count <= match_count + 1;
            detect_count <= detect_count + 1;
            reset_count <= reset_count + 1;
          end
        end
        DETECTED: begin
          if (detect_count == 3) begin
            state <= IDLE;
            match <= 0;
            count <= 0;
            match_count <= 0;
            detect_count <= 0;
            reset_count <= 0;
          end
          else begin
            state <= DETECTED;
            count <= 0;
            match_count <= match_count + 1;
            detect_count <= detect_count + 1;
            reset_count <= reset_count + 1;
          end
        end
      endcase
    end
  end

endmodule

