module uart(
    input clk,
    input reset,
    input rxin,
    output txout,
    output [7:0] Led 
);

// Define constants
`define START_BIT 1'b0
`define STOP_BIT 1'b1
`define DATA_BITS 8
`define BAUD_RATE 115200
`define BIT_PERIOD (1.0 / BAUD_RATE)

// Define states for the UART state machine
`define IDLE 2'b00
`define WAIT_START_BIT 2'b01
`define READ_DATA_BITS 2'b10
`define WAIT_STOP_BIT 2'b11

// Define internal signals
reg [2:0] state = `IDLE;
reg [3:0] data = 4'b0000;
reg start_bit_detected = 1'b0;
reg [7:0] led_data = 8'b00000000;
reg [7:0] baud_counter = 8'b00000000;
wire tx_ready = (state == `IDLE);

// Implement the UART state machine
always @(posedge clk) begin
    if (reset) begin
        state <= `IDLE;
        data <= 4'b0000;
        start_bit_detected <= 1'b0;
        led_data <= 8'b00000000;
        baud_counter <= 8'b00000000;
    end else begin
        case (state)
            `IDLE: begin
                if (rxin == `START_BIT) begin
                    state <= `WAIT_START_BIT;
                    start_bit_detected <= 1'b1;
                    baud_counter <= 8'b00000000;
                end
            end
            `WAIT_START_BIT: begin
                if (baud_counter == 8'd4) begin
                    baud_counter <= 8'b00000000;
                    state <= `READ_DATA_BITS;
                end else begin
                    baud_counter <= baud_counter + 1;
                end
            end
            `READ_DATA_BITS: begin
                if (baud_counter == 8'd8) begin
                    baud_counter <= 8'b00000000;
                    state <= `WAIT_STOP_BIT;
                end else begin
                    data <= {data[2:0], rxin};
                    baud_counter <= baud_counter + 1;
                end
            end
            `WAIT_STOP_BIT: begin
                if (baud_counter == 8'd12) begin
                    baud_counter <= 8'b00000000;
                    if (rxin == `STOP_BIT && start_bit_detected) begin
                        txout <= 1'b0;
                        state <= `IDLE;
                        led_data <= data;
                    end else begin
                        state <= `IDLE;
                    end
                    start_bit_detected <= 1'b0;
                end else begin
                    baud_counter <= baud_counter + 1;
                end
            end
        endcase
    end
end

// Transmit data on the txout output
always @(posedge clk) begin
    if (reset) begin
        txout <= 1'b0;
    end else begin
        if (tx_ready) begin
            txout <= 1'b0;
        end else begin
            if (baud_counter == 8'd8) begin
                txout <= data[0];
                baud_counter <= 8'b00000000;
                data <= {1'b0, data[3:1]};
            end else begin
                baud_counter <= baud_counter + 1;
            end
        end
    end
end

// Control the LEDs using the led_data signal
always @(posedge clk) begin
    if (reset) begin
        Led <= 8'b00000000;
    end else begin
        Led <= led_data;
    end
end

endmodule

