module Integrador_theta(
    input [15:0] a,
    input [15:0] dt,
    input enable,
    input rst,
    input clk,
    output [31:0] v,
    output reg busy
    );

	 wire busy_mul;
	 reg en;
	 reg [63:0] acum;
	 reg [63:0] acum_d;
	 wire [31:0] varS;
	 reg rest;

	 assign v = acum[63:32];

	booth_mult Multi(
		.clk(clk),
		.rst(rest),
		.en(en),
		.A(dt),
		.B(a),
		.busy(busy_mul),
		.R(varS)
	);

	 reg div1_rst;
	 reg div_en;
	 reg [63:0] div_A;
	 localparam div_B = 64'd100000000;
	 wire div_busy;
	 wire [63:0] div_res;

	 div_64 divider (
		.clk(clk), 
		.rst(div1_rst), 
		.init_in(div_en), 
		.A({div_A,32'h00000000}), 
		.B(div_B), 
		.Result(div_res), 
		.busy(div_busy)
     );


	 initial begin
		rest 	= 1'b1;
		div1_rst = 1'b1;
		acum = 64'd0;
		acum_d = 64'd0;
		div_A = 64'd0;
		busy = 1'b1;
	 end

	//--------------------------------Modulo states



	 	 localparam 
					reset 		= 5'd0,
					ini	  		= 5'd1,
					mulv			= 5'd2,
					check_1  	= 5'd3,
					div_1			= 5'd4,
					check_2		= 5'd5,
					afterv		= 5'd6,
					end_state	= 5'd7;

	 // State Machine Regs
	 reg[4:0] state;
	 reg[4:0] next_state;

	 initial state = reset;
	 initial next_state = reset;



	 always @(posedge clk)begin
		if(rst) state <= reset;
		else state <= next_state;
	 end

	always @(*)begin
		case(state)
			reset: begin
				acum 			<= 64'd0;
				busy 			<= 1'd1;
				en 			<= 1'd0;
				rest 			<= 1'd1;
				div_A			<= 64'd0;
				div1_rst		<= 1'b1;
				div_en		<= 1'b0;

				next_state 	<= ini;
			end

			ini: begin
				busy 			<= 1'd0;
				acum 			<= acum_d;
				en 			<= 1'd0;
				rest 			<= 1'd0;
				div_A			<= 64'd0;
				div1_rst		<= 1'b0;
				div_en		<= 1'b0;

				if (enable) next_state <= mulv;
				else 		next_state <= ini;

			end

			mulv: begin
				acum 			<= acum_d;
			  	busy 			<= 1'd1;
				en 			<= 1'b1;
				rest 			<= 1'b0;
				div_A			<= 64'd0;
				div1_rst		<= 1'b0;
				div_en		<= 1'b0;

				if(busy_mul)	next_state <= check_1;
				else 			next_state <= mulv;
			end

			check_1: begin
				acum 		<= acum_d;
			  	busy 		<= 1'd1;
				en 			<= 1'd0;
				rest 		<= 1'd0;
				div_A			<= 64'd0;
				div1_rst	<= 1'b0;
				div_en		<= 1'b0;

				if (busy_mul) 	next_state <= check_1;
				else 			next_state <= div_1;

			end

			div_1: begin
				busy <= 1'd1;
				en <= 1'd0;
				rest <= 1'd0;
				if(varS[31]) 	div_A <= (~varS)+1;
				else				div_A <= varS;
				div1_rst	<= 1'b0;
				div_en		<= 1'b1;

				if(div_busy) next_state <= check_2;
				else next_state <= div_1;
			end

			check_2: begin
				busy <= 1'd1;
				en <= 1'd0;
				rest <= 1'd0;

				div1_rst	<= 1'b0;
				div_en		<= 1'b1;

				if(div_busy) next_state <= check_2;
				else next_state <= afterv;
			end

			afterv: begin
				if(clk) 	begin
					//if (varS == 0)		acum <= acum_d;
					if(varS[31]) acum <= acum_d + 1 + ~div_res;
					else					acum <= acum_d + div_res;
				end
				else 		acum <= acum_d;
				busy <= 1'd1;
				rest <= 1'b1;
				en <= 1'd0;
				next_state <= ini;
			end
			/*
			end_state: begin
				en <= 1'd0;
				rest <=1'b1;
				busy <= 1'd0;
				if (!enable) next_state <= end_state;
				else 		next_state <= ini;
			end
			*/
			default: begin
				acum <= acum_d;
				en <= 1'd0;
				rest <= 1'b1;
				busy <= 1'd0;
				next_state <= ini;
			end
		endcase
	 end

	always @(negedge clk)begin
		acum_d <= acum;
	end

endmodule

module compare_8bit_inputs (
    input clk,              // Clock signal
    input reset,            // Asynchronous reset
    input [7:0] a,          // 8-bit input
    input [7:0] b,          // 8-bit input
    input control,          // Control signal
