reg [15:0] x_next;
reg [15:0] temp;
reg [3:0] count;

initial begin
    x = num;
    count = 0;
end

always @(*) begin
    temp = x_next;
    x_next = (x + (num / x)) >> 1;
    if (temp == x_next) begin
        count = count + 1;
    end
end

always @(posedge clk) begin
    if (count == 2) begin
        sqrt <= x_next[15:8];
    end
    x <= x_next;
end

