        {BORROW_OUT, SUM_DIFF_reg} <= A_reg - B_reg - BORROW_IN_reg;
        CARRY_OUT <= (A_reg >= B_reg) && ((A_reg != B_reg) || (BORROW_IN_reg == 1'b1));
