  reg [3:0] bit_counter;
  reg NFC_out;

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      data_buffer <= 8'b0;
      bit_counter <= 4'b0;
      NFC_out <= 0;
    end else begin
      if (bit_counter == 4'b0) begin
        data_buffer <= data_in;
      end
      NFC_out <= RF_in ^ data_buffer[7];
      data_buffer <= {data_buffer[6:0], 1'b0};
      bit_counter <= bit_counter + 1;
    end
  end
