    if (rst) begin
      data_buffer <= 8'b0;
      bit_counter <= 4'b0;
      last_NFC_in <= 0;
      data_out <= 8'b0;
    end else begin
      if (bit_counter == 4'b0) begin
        data_out <= data_buffer;
      end
      data_buffer <= {data_buffer[6:0], NFC_in ^ last_NFC_in};
      last_NFC_in <= NFC_in;
      bit_counter <= bit_counter + 1;
    end
  end
