module timer (
  input clk,
  input reset,
  input [1:0] timer_cfg,
  input stop_count,
  input start_count,
  output timeout
);

  parameter DW = 32;
  parameter AW = 32;

  reg [31:0] timeout_reg;
  reg do_count;
  wire timer_en;
  wire start_count_sync;
  wire timer_expired;

  // Synchronize the start count
  synchronizer #(.DW(1)) sync(
    .out(start_count_sync),
    .in(start_count),
    .clk(clk),
    .reset(reset)
  );

  // Determine if the timer is enabled
  assign timer_en = |(timer_cfg[1:0]);

  // Count down the timer
  always @(posedge clk) begin
    if (reset) begin
      do_count <= 1'b0;
      timeout_reg[31:0] <= 32'hffffffff;
    end
    else if (start_count_sync & timer_en) begin
      do_count <= 1'b1;
      timeout_reg[31:0] <= (timer_cfg[1:0] == 2'b01) ? 32'h000000ff :
                           (timer_cfg[1:0] == 2'b10) ? 32'h0000ffff :
                                                       32'hffffffff;
    end
    else if (stop_count) begin
      do_count <= 1'b0;
    end
    else if (timer_expired) begin
      do_count <= 1'b0;
      timeout_reg[31:0] <= 32'hffffffff;
    end
    else if (do_count) begin
      timeout_reg[31:0] <= timeout_reg[31:0] - 1'b1;
    end
  end

  // Determine if the timer has expired
  assign timer_expired = ~(|timeout_reg[31:0]);

  // Generate the timeout signal
  assign timeout = timer_en & timer_expired;

endmodule

module pipelined_adder_32bit (
