// Stage 1
full_adder_32bit fa1(.A(A), .B(B), .Cin(1'b0), .S(sum1), .Cout(carry1));

// Stage 2
full_adder_32bit fa2(.A(A), .B(B), .Cin(carry1[0]), .S(sum2), .Cout(carry2));

