                      SumInLSBs, CarryInLSBs,
                      SCLSBs, SBLSBs, SALSBs,
                      CCLSB, CBLSB, CALSB,
// outputs
                      Shift,
                      Pos,
                      Zero,
                      CarryOut0,
                      CarryOut3,
                      SumOut0,
                  SumCarryLoadEn,
                  InitialMulStep,
                  InitialCarryBit);

input notAbortWB, Rom_ResetMul;
input [2:0] SumInLSBs, CarryInLSBs;
input [1:0] SCLSBs, SBLSBs, SALSBs;
input CCLSB, CBLSB, CALSB;
input [8:0] notMultip;
output [3:0] Shift, Pos, Zero;
output       CarryOut0,
             CarryOut3,
             SumOut0;
output            InitialCarryBit,
                  SumCarryLoadEn,
                  InitialMulStep;

wire CCIn, CBIn, CAIn;
wire [3:0] CCOut, CBOut, CAOut;
wire [3:0] ShiftOut, PosOut, ZeroOut;
wire SumCarryLoadEnOut, InitialMulStepOut, InitialCarryBitOut;

/* *************************************************

      Multipler Selection Decoding

   ************************************************* */

MulSelCtl m13 (notMultip[8:6], ShiftOut[3], PosOut[3], ZeroOut[3], CarryOut3);
MulSelCtl m12 (notMultip[6:4], ShiftOut[2], PosOut[2], ZeroOut[2], CCIn);
MulSelCtl m11 (notMultip[4:2], ShiftOut[1], PosOut[1], ZeroOut[1], CBIn);
MulSelCtl m10 (notMultip[2:0], ShiftOut[0], PosOut[0], ZeroOut[0], CAIn);

/* *************************************************

      Full Add over LSBs and OR result

   ************************************************* */

MulLSBlog lbg (SumInLSBs[2:1], CarryInLSBs[2:1],
            {SCLSBs, SBLSBs, SALSBs},
            {CCLSB, CCIn, CBLSB, CBIn, CALSB, CAIn},
            CarryInLSBs[0], SumInLSBs[0],
           CarryOut0, SumOut0);

carrysaveregslsb csrl (Rom_ResetMul,
                  notMultip[0],
                  notAbortWB,
                  SumCarryLoadEnOut,
                  InitialMulStepOut,
                  InitialCarryBitOut);

/* *************************************************

      Output assignments

   ************************************************* */

assign Shift = ShiftOut;
assign Pos = PosOut;
assign Zero = ZeroOut;
assign CarryOut0 = CarryOut0;
assign CarryOut3 = CarryOut3;
assign SumOut0 = SumOut0;
assign SumCarryLoadEn = SumCarryLoadEnOut;
assign InitialMulStep = InitialMulStepOut;
assign InitialCarryBit = InitialCarryBitOut;

endmodule

/* *************************************************

      MulSelCtl module

   ************************************************* */

module MulSelCtl (Sel, Shift, Pos, Zero, CarryOut);

input [2:0] Sel;
output Shift, Pos, Zero, CarryOut;

assign Shift = (Sel == 3) ? 1 : 0;
assign Pos = (Sel == 1) ? 1 : 0;
assign Zero = (Sel == 0) ? 1 : 0;
assign CarryOut = (Sel == 2) ? 1 : 0;

endmodule

/* *************************************************

      MulLSBlog module

   ************************************************* */

module MulLSBlog (SumIn, CarryIn, Shift, Carry, Cin, Sin, Cout, Sout);

input [1:0] SumIn, CarryIn, Shift;
input [5:0] Carry;
input Cin, Sin;
output Cout, Sout;

wire [1:0] SumOut, CarryOut;

assign SumOut[0] = (Cin ^ SumIn[0] ^ CarryIn[0]);
assign CarryOut[0] = (Cin & SumIn[0]) | (CarryIn[0] & (Cin ^ SumIn[0]));
assign SumOut[1] = (CarryOut[0] ^ SumIn[1] ^ CarryIn[1]);
assign CarryOut[1] = (CarryIn[1] & (CarryOut[0] ^ SumIn[1])) | (CarryOut[0] & (Cin ^ SumIn[1]));
assign SumOut[2] = (CarryOut[1] ^ SumIn[2] ^ CarryIn[2]);
assign CarryOut[2] = (CarryIn[2] & (CarryOut[1] ^ SumIn[2])) | (CarryOut[1] & (Cin ^ SumIn[2]));
assign Sout = (CarryOut[2] ^ Sin ^ Carry[Shift]);
assign Cout = CarryOut[2];

endmodule

/* *************************************************

      carrysaveregslsb module

   ************************************************* */

module carrysaveregslsb (Reset, notMultip, notAbortWB, SumCarryLoadEn, InitialMulStep, InitialCarryBit);

input Reset, notMultip, notAbortWB;
output SumCarryLoadEn, InitialMulStep, InitialCarryBit;

reg [1:0] CarrySaveReg;
reg InitialSumZero;

always @(posedge notAbortWB or posedge Reset) begin
    if (Reset) begin
        CarrySaveReg <= 2'b00;
        InitialSumZero <= 1'b0;
    end
    else begin
        if (notMultip) begin
            CarrySaveReg <= {CarrySaveReg[0], CarrySaveReg[1]};
            if (SumCarryLoadEn) begin
                CarrySaveReg <= {InitialCarryBit, CarrySaveReg[1]};
                InitialSumZero <= 1'b0;
            end
            else begin
                if (InitialMulStep) begin
                    CarrySaveReg <= {InitialCarryBit, CarrySaveReg[1]};
                    InitialSumZero <= (CarrySaveReg == 2'b00);
                end
                else begin
                    CarrySaveReg <= {CarrySaveReg[0], InitialCarryBit};
                    InitialSumZero <= (CarrySaveReg == 2'b00);
                end
            end
        end
    end
end

assign SumCarryLoadEn = (CarrySaveReg != 2'b00) & notAbortWB;
assign InitialMulStep = (CarrySaveReg == 2'b00) & notAbortWB;
assign InitialCarryBit = (InitialSumZero & notMultip) ? 1'b1 : 1'b0;

endmodule

module altera_up_av_config_auto_init_ltm (
    // Inputs
    rom_address,

    // Outputs
    rom_data
);

/*****************************************************************************
 *                           Parameter Declarations                          *
 *****************************************************************************/

/*****************************************************************************
 *                             Port Declarations                             *
 *****************************************************************************/
// Inputs
input           [4:0]   rom_address;

// Outputs
output      [23:0]  rom_data;

/*****************************************************************************
 *                           Constant Declarations                           *
 *****************************************************************************/

// States
localparam [4:0] STATE_0 = 5'h0;
localparam [4:0] STATE_1 = 5'h1;
localparam [4:0] STATE_2 = 5'h2;
localparam [4:0] STATE_3 = 5'h3;
localparam [4:0] STATE_4 = 5'h4;
localparam [4:0] STATE_5 = 5'h5;
localparam [4:0] STATE_6 = 5'h6;
localparam [4:0] STATE_7 = 5'h7;
localparam [4:0] STATE_8 = 5'h8;
localparam [4:0] STATE_9 = 5'h9;
localparam [4:0] STATE_10 = 5'hA;
localparam [4:0] STATE_11 = 5'hB;
localparam [4:0] STATE_12 = 5'hC;
localparam [4:0] STATE_13 = 5'hD;
localparam [4:0] STATE_14 = 5'hE;
localparam [4:0] STATE_15 = 5'hF;
localparam [4:0] STATE_16 = 5'h10;
localparam [4:0] STATE_17 = 5'h11;
localparam [4:0] STATE_18 = 5'h12;
localparam [4:0] STATE_19 = 5'h13;

/*****************************************************************************
 *                 Internal Wires and Registers Declarations                 *
 *****************************************************************************/
// Internal Wires
reg         [23:0] data;

// State Machine Registers
reg         [4:0]   state_reg;
reg         [4:0]   next_state;

/*****************************************************************************
 *                         Finite State Machine(s)                           *
 *****************************************************************************/

always @(*) begin
    case (state_reg)
        STATE_0 : next_state = (rom_address == 5'h0) ? STATE_0 : STATE_1;
        STATE_1 : next_state = (rom_address == 5'h1) ? STATE_1 : STATE_2;
        STATE_2 : next_state = (rom_address == 5'h2) ? STATE_2 : STATE_3;
        STATE_3 : next_state = (rom_address == 5'h3) ? STATE_3 : STATE_4;
        STATE_4 : next_state = (rom_address == 5'h4) ? STATE_4 : STATE_5;
        STATE_5 : next_state = (rom_address == 5'h5) ? STATE_5 : STATE_6;
        STATE_6 : next_state = (rom_address == 5'h6) ? STATE_6 : STATE_7;
        STATE_7 : next_state = (rom_address == 5'h7) ? STATE_7 : STATE_8;
        STATE_8 : next_state = (rom_address == 5'h8) ? STATE_8 : STATE_9;
        STATE_9 : next_state = (rom_address == 5'h9) ? STATE_9 : STATE_10;
        STATE_10 : next_state = (rom_address == 5'hA) ? STATE_10 : STATE_11;
        STATE_11 : next_state = (rom_address == 5'hB) ? STATE_11 : STATE_12;
        STATE_12 : next_state = (rom_address == 5'hC) ? STATE_12 : STATE_13;
        STATE_13 : next_state = (rom_address == 5'hD) ? STATE_13 : STATE_14;
        STATE_14 : next_state = (rom_address == 5'hE) ? STATE_14 : STATE_15;
        STATE_15 : next_state = (rom_address == 5'hF) ? STATE_15 : STATE_16;
        STATE_16 : next_state = (rom_address == 5'h10) ? STATE_16 : STATE_17;
        STATE_17 : next_state = (rom_address == 5'h11) ? STATE_17 : STATE_18;
        STATE_18 : next_state = (rom_address == 5'h12) ? STATE_18 : STATE_19;
        STATE_19 : next_state = (rom_address == 5'h13) ? STATE_19 : STATE_0;
        default : next_state = STATE_0;
    endcase
end

/*****************************************************************************
 *                             Sequential Logic                              *
 *****************************************************************************/

// State machine
always @(posedge clk) begin
    state_reg <= next_state;
end

/*****************************************************************************
 *                            Combinational Logic                            *
 *****************************************************************************/

// Output Assignments
assign rom_data = {data[13:8], 2'h0, data[7:0]};

// Internal Assignments
always @(*) begin
    case (state_reg)
        STATE_0 : data <= {6'h02, 8'h07};
        STATE_1 : data <= {6'h03, 8'hDF};
        STATE_2 : data <= {6'h04, 8'h17};
        STATE_3 : data <= {6'h11, 8'h00};
        STATE_4 : data <= {6'h12, 8'h5B};
        STATE_5 : data <= {6'h13, 8'hFF};
        STATE_6 : data <= {6'h14, 8'h00};
        STATE_7 : data <= {6'h15, 8'h20};
        STATE_8 : data <= {6'h16, 8'h40};
        STATE_9 : data <= {6'h17, 8'h80};
        STATE_10 : data <= {6'h18, 8'h00};
        STATE_11 : data <= {6'h19, 8'h80};
        STATE_12 : data <= {6'h1A, 8'h00};
        STATE_13 : data <= {6'h1B, 8'h00};
        STATE_14 : data <= {6'h1C, 8'h80};
        STATE_15 : data <= {6'h1D, 8'hC0};
        STATE_16 : data <= {6'h1E, 8'hE0};
        STATE_17 : data <= {6'h1F, 8'hFF};
        STATE_18 : data <= {6'h20, 8'hD2};
        STATE_19 : data <= {6'h21, 8'hD2};
        default : data <= 24'h000000;
    endcase
end

/*****************************************************************************
 *                              Internal Modules                             *
 *****************************************************************************/

endmodule

module uart_echo(
  input wire clk, // Clock
  input wire rx,  // Receive data
  output wire tx  // Transmit data
);

  // Baud rate
  localparam BAUD_RATE = 115200;

  // Data register
  reg [7:0] data_reg;

  // Data received flag
  wire rcv;

  // Transmitter ready flag
  wire ready;

  // Reset signal
  reg rstn = 0;

  // Instantiate UART receiver
  uart_rx #(
    .BAUD_RATE(BAUD_RATE)
  ) rx_inst (
    .clk(clk),
    .rstn(rstn),
    .rx(rx),
    .rcv(rcv),
    .data(data_reg)
  );

  // Instantiate UART transmitter
  uart_tx #(
    .BAUD_RATE(BAUD_RATE)
  ) tx_inst (
    .clk(clk),
    .rstn(rstn),
    .start(rcv),
    .data(data_reg),
    .tx(tx),
    .ready(ready)
  );

  // Reset logic
  always @(posedge clk) begin
    rstn <= 1;
  end

endmodule

