  input [3:0] A,
  input [3:0] B,
  input C,
  output [3:0] S,
  output [3:0] D
);

  wire [4:0] temp;

  assign temp = C ? (A - B) : (A + B);

  assign S = temp[3:0];
  assign D = temp[4] ? (temp[3:0] - 16) : temp[3:0];

endmodule

module add_sub_overflow (
    input [3:0] A,
    input [3:0] B,
    input Sub,
    output [3:0] Sum,
    output Overflow
);

    reg [3:0] temp_sum;
    reg temp_overflow;

    always @(*) begin
        if (Sub == 1) begin
            temp_sum = A - B;
            if (A[3] == 1 && B[3] == 0 && temp_sum[3] == 0) begin
                temp_overflow = 1;
            end else if (A[3] == 0 && B[3] == 1 && temp_sum[3] == 1) begin
                temp_overflow = 1;
            end else begin
                temp_overflow = 0;
            end
        end else begin
            temp_sum = A + B;
            if (A[3] == 0 && B[3] == 0 && temp_sum[3] == 1) begin
                temp_overflow = 1;
            end else if (A[3] == 1 && B[3] == 1 && temp_sum[3] == 0) begin
                temp_overflow = 1;
            end else begin
                temp_overflow = 0;
            end
        end
    end

    assign Sum = temp_sum;
    assign Overflow = temp_overflow;

endmodule

module data_selector (
    input rst,
    input clk,
    input [37:0] data_in,
    input [5:0] distance,
    output reg [37:0] data_out
);

reg [37:0] shifted_data;
reg [3:0] select_index;

always @(posedge clk, posedge rst) begin
    if (rst) begin
        shifted_data <= 0;
        select_index <= 0;
        data_out <= 0;
    end else begin
        // Shift data left or right based on distance
        if (distance[5]) begin
            shifted_data <= {data_in[37], data_in};
        end else begin
            shifted_data <= {data_in, data_in[0]};
        end

        // Select subset of shifted data based on distance
        case (distance[4:0])
            5'b00000: select_index <= 0;
            5'b00001: select_index <= 1;
            5'b00010: select_index <= 2;
            5'b00011: select_index <= 3;
            5'b00100: select_index <= 4;
            5'b00101: select_index <= 5;
            5'b00110: select_index <= 6;
            5'b00111: select_index <= 7;
            5'b01000: select_index <= 8;
            5'b01001: select_index <= 9;
            5'b01010: select_index <= 10;
            5'b01011: select_index <= 11;
            5'b01100: select_index <= 12;
            5'b01101: select_index <= 13;
            5'b01110: select_index <= 14;
            5'b01111: select_index <= 15;
            5'b10000: select_index <= 16;
            5'b10001: select_index <= 17;
            5'b10010: select_index <= 18;
            5'b10011: select_index <= 19;
            5'b10100: select_index <= 20;
            5'b10101: select_index <= 21;
            5'b10110: select_index <= 22;
            5'b10111: select_index <= 23;
            5'b11000: select_index <= 24;
            5'b11001: select_index <= 25;
            5'b11010: select_index <= 26;
            5'b11011: select_index <= 27;
            5'b11100: select_index <= 28;
            5'b11101: select_index <= 29;
            5'b11110: select_index <= 30;
            5'b11111: select_index <= 31;
        endcase

        // Combine selected data into result
        data_out <= shifted_data[select_index +: 38];
    end
end

endmodule

module decoder_4to16_nand (
