assign nY[3] = nA & nB & C & D;
assign nY[4] = nA & C & nB & nD;
assign nY[5] = nA & C & nB & D;
assign nY[6] = nA & C & D & nB;
assign nY[7] = nA & C & D & D;
assign nY[8] = A & nB & nC & nD;
assign nY[9] = A & nB & nC & D;
assign nY[10] = A & nB & C & nD;
assign nY[11] = A & nB & C & D;
assign nY[12] = A & C & nB & nD;
assign nY[13] = A & C & nB & D;
assign nY[14] = A & C & D & nB;
