module xor_gate (
    input a,
    input b,
    output out
);

// Behavioral implementation using always block
always @ (a, b)
begin
    out = a ^ b;
end

// Structural implementation using NAND gates
nand (nand1, a, b);
nand (nand2, a, nand1);
nand (nand3, b, nand1);
nand (nand4, nand2, nand3);
assign out = nand4;

endmodule

