module parity_xor (
    input [7:0] in,
    output [9:0] out
);

    // Parity generator module
    wire parity = ^in;
    wire [8:0] parity_out = {parity, in};

    // XOR gate module
    wire [7:0] xor_in = in;
    wire xor_out = xor_in[0] ^ xor_in[1] ^ xor_in[2] ^ xor_in[3] ^ xor_in[4] ^ xor_in[5] ^ xor_in[6] ^ xor_in[7];

    // Control logic
    reg enable_parity = 1'b1;
    reg enable_xor = 1'b0;

    always @ (in) begin
        if (enable_parity) begin
            enable_parity = 1'b0;
            enable_xor = 1'b1;
        end
        else if (enable_xor) begin
            enable_xor = 1'b0;
            enable_parity = 1'b1;
        end
    end

    // Output
    assign out = {parity_out, xor_out};

endmodule

