module alu64 (
  input [63:0] a,
  input [63:0] b,
  input [5:0] S,
  output [63:0] d,
  output Cout,
  output [3:0] NZVC
);

  wire [63:0] addResult;
  wire [63:0] subResult;
  wire [63:0] andResult;
  wire [63:0] orResult;
  wire [63:0] xorResult;
  wire [63:0] sllResult;
  wire [63:0] srlResult;
  wire [63:0] sraResult;
  wire [63:0] sltResult;
  wire [63:0] sleResult;
  wire [63:0] moveResult;

  // Addition
  assign addResult = a + b;
  // Subtraction
  assign subResult = a - b;
  // Bitwise AND
  assign andResult = a & b;
  // Bitwise OR
  assign orResult = a | b;
  // Bitwise XOR
  assign xorResult = a ^ b;
  // Shift left logical
  assign sllResult = a << S;
  // Shift right logical
  assign srlResult = a >> S;
  // Shift right arithmetic
  assign sraResult = $signed(a) >>> S;
  // Set on less than
  assign sltResult = (a < b) ? 64'h0000000000000001 : 64'h0000000000000000;
  // Set on less than or equal
  assign sleResult = (a <= b) ? 64'h0000000000000001 : 64'h0000000000000000;
  // Move
  assign moveResult = (S == 6'b001100) ? b : 64'hzzzzzzzzzzzzzzzz;

  // Output d based on the selected operation
  always @(*) begin
    case (S)
      6'b000000: d = addResult;
      6'b000001: d = subResult;
      6'b000010: d = andResult;
      6'b000011: d = orResult;
      6'b000100: d = xorResult;
      6'b000101: d = sllResult;
      6'b000110: d = srlResult;
      6'b000111: d = sraResult;
      6'b001010: d = sltResult;
      6'b001011: d = sleResult;
      6'b001100: d = moveResult;
      default: d = 64'hzzzzzzzzzzzzzzzz;
    endcase
  end

  // Output Cout based on the selected operation
  assign Cout = (S == 6'b000000 && addResult[63] == 1'b1) ||
               (S == 6'b000001 && subResult[63] == 1'b1) ||
               (S == 6'b000101 && a[63:S] != 0) ||
               (S == 6'b000110 && a[63:S] != 0);

  // Output NZVC based on the selected operation
  assign NZVC[3] = (d[63] == 1'b1) ? 1'b1 : 1'b0; // N (negative)
  assign NZVC[2] = (d == 64'h0000000000000000) ? 1'b1 : 1'b0; // Z (zero)
  assign NZVC[1] = (S == 6'b000000 || S == 6'b000001) ? // V (overflow, signed)
                     ((a[63] == b[63] && d[63] != a[63]) ||
                      (a[63] != b[63] && d[63] == a[63])) ? 1'b1 : 1'b0
                   : 1'bx;
  assign NZVC[0] = Cout; // C (carry)

endmodule

module ConstantCurrentDriver(
  input wire Vdd,
  input wire Rload,
  input wire Iconst,
  output wire Vload
);

  reg [31:0] Vload_reg;
  reg [31:0] Iload_reg;
  reg [31:0] Vdrop_reg;

  assign Vload = Vload_reg;

  always @ (Vdd or Rload or Iconst or Vload_reg) begin
    Vdrop_reg = Iconst * Rload;
    Iload_reg = Vdd / Rload;
    Vload_reg = Vload_reg + (Iload_reg * (Vdd - Vload_reg) - Vdrop_reg) / 1000;
  end

endmodule

