module music(clk, gate, note, pitch, lfo_sig, lfo_depth, lfo_depth_fine, wave_form, signal_out);
    input wire clk;
    input wire gate;
    input wire [6:0] note;
    input wire [7:0] lfo_sig;
    input wire [6:0] lfo_depth;
    input wire [6:0] lfo_depth_fine;
    input wire [13:0] pitch;
    output wire [7:0] signal_out;
    input wire [2:0] wave_form;

    // wave_forms
    parameter SAW      = 3'b000;
    parameter SQUARE   = 3'b001; //with PWM
    parameter TRIANGLE = 3'b010;
    parameter SINE     = 3'b011;
    parameter RAMP     = 3'b100;
    parameter SAW_TRI  = 3'b101;
    parameter NOISE    = 3'b110;
    parameter UNDEF    = 3'b111;

    wire [31:0] adder_center;
    note_pitch2dds  transl1(.clk(clk), .note(note), .pitch(pitch), .lfo_sig(lfo_sig), .lfo_depth(lfo_depth), .lfo_depth_fine(lfo_depth_fine), .adder(adder_center)); 

    wire [31:0] vco_out;
    dds #(.WIDTH(32)) vco(.clk(clk), .adder(adder_center), .signal_out(vco_out));

    wire [7:0] saw_out = vco_out[31:31-7];
    wire [7:0] square_out = (vco_out[31:31-7] > 127) ? 8'b11111111 : 1'b00000000;
    wire [7:0] tri_out = (saw_out>8'd191) ? 7'd127 + ((saw_out << 1) - 9'd511) : 
                         (saw_out>8'd063) ? 8'd255 - ((saw_out << 1) - 7'd127) : 7'd127 + (saw_out << 1);

    //SINE table
    wire [7:0] sine_out;
    sine sine_rom(.address(vco_out[31:31-7]),
                  .q(sine_out),
                  .clock(clk));

    wire [7:0] ramp_out = -saw_out;    
    wire [7:0] saw_tri_out = (saw_out > 7'd127) ?  -saw_out : 8'd127 + saw_out;    

    //noise
    reg  [7:0] noise_reg;
    wire [7:0] noise_out = noise_reg;
    wire [7:0] noise_sig;
    //16000 hz GENERATOR
    wire clk16000;
    frq1divmod1 divider1(clk, 25'd1563, clk16000); //50000000 / 16000 / 2 = 1563
    reg [1:0] clk16000_prev=2'b00;
    always @(posedge clk) clk16000_prev <= {clk16000_prev[0], clk16000};
    wire clk16000_posege = (clk16000_prev==2'b01);
    rndx #(.WIDTH(8)) random8(.clk(clk), .signal_out(noise_sig));
    always @(posedge clk) begin
        if (clk16000_posege) begin
            noise_reg <= noise_sig;
        end
    end

    //signal_out
    assign signal_out = (wave_form ==      SAW) ? saw_out :
                        (wave_form ==   SQUARE) ? square_out : 
                        (wave_form == TRIANGLE) ? tri_out : 
                        (wave_form ==     SINE) ? sine_out : 
                        (wave_form ==     RAMP) ? ramp_out : 
                        (wave_form ==  SAW_TRI) ? saw_tri_out : 
                        (wave_form ==    NOISE) ? noise_out : 8'd127;

endmodule

module pulse_sender (
  input grst_i,
  input odom_clk_i,
  input odom_pulse_i,
  input xdom_clk_i,
  output xdom_pulse_o,
  output busy_o,
  output err_o
);

  parameter IDLE = 2'b00;
  parameter WAITING_FOR_FEEDBACK = 2'b01;
  parameter WAITING_FOR_NEXT_REQUEST = 2'b10;

  reg [1:0] state = IDLE;
  reg odom_pulse_request = 0;
  reg xdom_pulse_request = 0;
  reg odom_pulse_delay_r = 0;
  reg odom_pulse_keeper_r = 0;
  reg odom_pulse_gen_r = 0;
  reg xdom_pulse_gen_r = 0;
  reg [1:0] xdom_double_flips_r = 0;
  reg xdom_pulse_en_delay_r = 0;
  reg [1:0] odom_feedback_double_flips_r = 0;
  reg err_r = 0;
  wire xdom_pulse_en = xdom_double_flips_r[0];
  wire odom_pulse_safe_cancel = odom_feedback_double_flips_r[0];
  assign busy_o = (state != IDLE) | odom_pulse_request | odom_pulse_safe_cancel;

  always @(posedge odom_clk_i or posedge grst_i) begin
    if (grst_i) begin
      odom_pulse_delay_r <= 0;
      odom_pulse_keeper_r <= 0;
      odom_pulse_gen_r <= 0;
      state <= IDLE;
    end else begin
      odom_pulse_delay_r <= odom_pulse_i;
      case (state)
        IDLE: begin
          if (odom_pulse_i) begin
            odom_pulse_request <= 1;
            state <= WAITING_FOR_FEEDBACK;
          end else begin
            odom_pulse_request <= 0;
            state <= IDLE;
          end
        end
        WAITING_FOR_FEEDBACK: begin
          if (odom_pulse_keeper_r == 0 && odom_pulse_gen_r == 1) begin
            odom_pulse_keeper_r <= 1;
            state <= WAITING_FOR_FEEDBACK;
          end else if (odom_pulse_keeper_r == 1 && odom_pulse_safe_cancel == 1) begin
            odom_pulse_keeper_r <= 0;
            state <= WAITING_FOR_NEXT_REQUEST;
          end else begin
            odom_pulse_keeper_r <= odom_pulse_keeper_r;
            state <= WAITING_FOR_FEEDBACK;
          end
        end
        WAITING_FOR_NEXT_REQUEST: begin
          if (odom_pulse_i) begin
            err_r <= 1;
            state <= WAITING_FOR_NEXT_REQUEST;
          end else begin
            err_r <= 0;
            state <= IDLE;
          end
        end
      endcase
      if ((odom_pulse_i == 1) && (odom_pulse_delay_r == 0)) begin
        odom_pulse_gen_r <= 1;
      end else begin
        odom_pulse_gen_r <= 0;
      end
    end
  end

  always @(posedge xdom_clk_i or posedge grst_i) begin
    if (grst_i) begin
      xdom_double_flips_r <= 0;
      xdom_pulse_en_delay_r <= 0;
      xdom_pulse_gen_r <= 0;
    end else begin
      xdom_double_flips_r <= {odom_pulse_keeper_r, xdom_double_flips_r[1]};
      if (xdom_pulse_en == 1 && xdom_pulse_en_delay_r == 0) begin
        xdom_pulse_gen_r <= 1;
      end else begin
        xdom_pulse_gen_r <= 0;
      end
      xdom_pulse_en_delay_r <= xdom_pulse_en;
    end
  end

  always @(posedge odom_clk_i or posedge grst_i) begin
    if (grst_i) begin
      odom_feedback_double_flips_r <= 0;
    end else begin
      odom_feedback_double_flips_r <= {xdom_pulse_en, odom_feedback_double_flips_r[1]};
    end
  end

  assign xdom_pulse_o = xdom_pulse_gen_r;
  assign err_o = err_r;

endmodule

module REG_LIST ( DIN, IPOS, INIT, OPOS, VALID);

	// Detects set bits in register list for SAVE/RESTORE & ENTER/EXIT

	input	 [7:0]	DIN;
	input	 [2:0]	IPOS;
	input			INIT;
	output	 [2:0]	OPOS;
	output			VALID;

	reg		 [7:1]	filter;
	wire	 [7:0]	mdat_0;
	wire	 [3:0]	mdat_1;
	wire	 [1:0]	mdat_2;

	always @(IPOS or DIN)
		case (IPOS)
		  3'd0 : filter =  DIN[7:1];
		  3'd1 : filter = {DIN[7:2],1'b0};
		  3'd2 : filter = {DIN[7:3],2'b0};
		  3'd3 : filter = {DIN[7:4],3'b0};
		  3'd4 : filter = {DIN[7:5],4'b0};
		  3'd5 : filter = {DIN[7:6],5'b0};
		  3'd6 : filter = {DIN[7]  ,6'b0};
		  3'd7 : filter =           7'b0;
		endcase

	assign mdat_0  = INIT ? DIN : {filter,1'b0};
	assign OPOS[2] = (mdat_0[3:0] == 4'h0);
	assign mdat_1  = OPOS[2] ? mdat_0[7:4] : mdat_0[3:0];
	assign OPOS[1] = (mdat_1[1:0] == 2'b00);
	assign mdat_2  = OPOS[1] ? mdat_1[3:2] : mdat_1[1:0];
	assign OPOS[0] = ~mdat_2[0];
	assign VALID   = (mdat_2 != 2'b00);

endmodule

module adder4(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

    wire c1, c2, c3;

    // First bit
    xor x1(A[0], B[0], c1);
    and a1(A[0], B[0], c2);
    or o1(c1, c2, S[0]);

    // Second bit
    xor x2(A[1], B[1], c1);
    and a2(A[1], B[1], c2);
    and a3(A[0], B[0], c3);
    or o2(c1, c2, c3, S[1]);

    // Third bit
    xor x3(A[2], B[2], c1);
    and a4(A[2], B[2], c2);
    and a5(A[1], B[1], c3);
    or o3(c1, c2, c3, S[2]);

    // Fourth bit
    xor x4(A[3], B[3], c1);
    and a6(A[3], B[3], c2);
    and a7(A[2], B[2], c3);
    or o4(c1, c2, c3, S[3]);

    // Carry-out
    or o5(c1, c2, c3, Cout);

endmodule

module velocityControlHdl_Inverse_Park_Transform(
  input signed [17:0] direct_voltage,
  input signed [17:0] quadrature_voltage,
  input signed [17:0] sin_coefficient,
  input signed [17:0] cos_coefficient,
  output signed [17:0] alpha_voltage,
  output signed [17:0] beta_voltage
);

  wire signed [35:0] Product1_out1; // sfix36_En28
  wire signed [35:0] Product2_out1; // sfix36_En28
  wire signed [35:0] alpha_voltage_1; // sfix36_En28
  wire signed [17:0] Convert_Data_Type_out1; // sfix18_En10
  wire signed [35:0] beta_voltage_1; // sfix36_En28
  wire signed [17:0] Convert_Data_Type1_out1; // sfix18_En10

  // Calculate alpha voltage
  assign Product1_out1 = direct_voltage * cos_coefficient;
  assign Product2_out1 = quadrature_voltage * sin_coefficient;
  assign alpha_voltage_1 = Product1_out1 - Product2_out1;
  velocityControlHdl_Convert_Data_Type_block1 u_Convert_Data_Type(.In1(alpha_voltage_1), .Out1(Convert_Data_Type_out1));
  assign alpha_voltage = Convert_Data_Type_out1;

  // Calculate beta voltage
  assign Product1_out1 = direct_voltage * sin_coefficient;
  assign Product2_out1 = quadrature_voltage * cos_coefficient;
  assign beta_voltage_1 = Product1_out1 + Product2_out1;
  velocityControlHdl_Convert_Data_Type1_block1 u_Convert_Data_Type1(.In1(beta_voltage_1), .Out1(Convert_Data_Type1_out1));
  assign beta_voltage = Convert_Data_Type1_out1;

endmodule

