module mux_comparator (
    input [63:0] sel,
    input [63:0] in,
    input [3:0] cmp_val,
    output reg cmp_out
);

reg [3:0] mux_out;

always @(*) begin
    case (sel[5:2])
        4'b0000: mux_out = in[3:0];
        4'b0001: mux_out = in[7:4];
        4'b0010: mux_out = in[11:8];
        // Add more cases for other select values
        default: mux_out = 4'b0000;
    endcase
end

always @(mux_out, cmp_val) begin
    if (mux_out == cmp_val) begin
        cmp_out <= 1'b1;
    end else begin
        cmp_out <= 1'b0;
    end
end

endmodule

