    if (rst_n) begin
        pipe_tx_rcvr_det_q <= #TCQ 0;
        pipe_tx_reset_q <= #TCQ 1'b1;
        pipe_tx_rate_q <= #TCQ 0;
        pipe_tx_deemph_q <= #TCQ 1'b1;
        pipe_tx_margin_q <= #TCQ 0;
        pipe_tx_swing_q <= #TCQ 0;
