assign pipe_tx_rate_o = (PIPE_PIPELINE_STAGES == 0) ? pipe_tx_rate_i : (PIPE_PIPELINE_STAGES == 1) ? pipe_tx_rate_q : pipe_tx_rate_qq;
assign pipe_tx_deemph_o = (PIPE_PIPELINE_STAGES == 0) ? pipe_tx_deemph_i : (PIPE_PIPELINE_STAGES == 1) ? pipe_tx_deemph_q : pipe_tx_deemph_qq;
assign pipe_tx_margin_o = (PIPE_PIPELINE_STAGES == 0) ? pipe_tx_margin_i : (PIPE_PIPELINE_STAGES == 1) ? pipe_tx_margin_q : pipe_tx_margin_qq;
assign pipe_tx_swing_o = (PIPE_PIPELINE_STAGES == 0) ? pipe_tx_swing_i : (PIPE_PIPELINE_STAGES == 1) ? pipe_tx_swing_q : pipe_tx_swing_qq;

