  flex_counter_0 a1 ( .clk(clk), .n_rst(n_rst), .clear(_0_net_), 
        .count_enable(shift_enable), .rollover_val({1'b1, 1'b0, 1'b0, 1'b0}), 
        .rollover_flag(fullbyte) );

