  INVX1 U9 ( .A(n6), .Y(shift_enable) );
  NAND3X1 U10 ( .A(igot[1]), .B(n7), .C(n8), .Y(n6) );
  NOR2X1 U11 ( .A(igot[3]), .B(igot[2]), .Y(n8) );
  INVX1 U12 ( .A(igot[0]), .Y(n7) );
  NAND2X1 U13 ( .A(rcving), .B(n9), .Y(_0_net_) );
  INVX1 U14 ( .A(fullbyte), .Y(n9) );
endmodule

