module npc (iaddr, branch, jump, ins, jiaddr, imm16, imm26, riaddr, niaddr);
	input 	branch, jump;
	input [31:0] 	ins;
	input [31:0]	jiaddr;// Jump to instruction address.
	input [31:0]	iaddr;// Instruction Address.
	input [15:0] 	imm16;
	input [25:0]	imm26;

	output 	 	[31:0] riaddr;// Return instruction address;
	output reg 	[31:0] niaddr;// Next Instruction Address;

	wire [5:0]	op;
	wire [5:0] 	func;
	assign op 	= ins[31:26];
	assign func = ins[5:0];
	// Operation code.
	parameter 	R 		= 6'b000000,
				J  		= 6'b000010,
				JAL		= 6'b000011,
				ERET	= 6'b010000;
	// Function code.
	parameter 	JR		= 6'b001000,
				JALR	= 6'b001001,
				SYSCALL = 6'b001100;

	wire [31:0] pc4;

	assign pc4 		= iaddr + 3'b100;
	assign riaddr 	= pc4 + 3'b100;

	always @ ( * ) begin
		if (branch) begin// Branch;
			// Arithmetic extend.
			niaddr = {{14{imm16[15]}}, imm16[15:0], 2'b00} + iaddr + 3'b100;

		end else if (jump) begin// Jump.
			case (op)
				J: begin// Jump.
					niaddr = {iaddr[31:28], imm26, 2'b00};
				end
				JAL: begin// Jump and link.
					riaddr <= iaddr + 3'b100;
					niaddr <= {iaddr[31:28], imm26, 2'b00};
				end
				R: begin
					case (func)
						JR: begin// Jump register.
							niaddr = jiaddr;
						end
						JALR: begin// Jump and link register.
							riaddr <= iaddr + 3'b100;
							niaddr <= jiaddr;
						end
						SYSCALL: begin
							niaddr <= jiaddr;
						end
					endcase
				end
				ERET: begin
					niaddr <= jiaddr;
				end
			endcase

		end else begin// PC + 4;
			niaddr = iaddr + 3'b100;
		end
	end

endmodule

module uart_tx (
	input reset, // active low
	input clock,
	input [7:0] read_data,
	input read_clock_enable,
	output reg ready, // ready to read new data
	output reg tx, // UART transmission
	output reg uart_clock
);

parameter CLOCK_FREQ = 2400;
parameter BAUD_RATE = 1200;
parameter BIT_TIME = CLOCK_FREQ / BAUD_RATE;

reg [3:0] state;
reg [7:0] data;
reg start_bit;
reg [2:0] bit_count;
reg stop_bit;

assign uart_clock = clock;

always @(posedge clock) begin
	if (reset == 0) begin
		state <= 4'b0000;
		ready <= 0;
		tx <= 1;
		data <= 0;
		start_bit <= 0;
		bit_count <= 0;
		stop_bit <= 1;
	end else begin
		case (state)
			4'b0000: begin // wait for read clock enable
				if (read_clock_enable == 1) begin
					state <= 4'b0001;
				end
			end
			4'b0001: begin // wait for ready
				if (ready == 1) begin
					state <= 4'b0010;
					data <= read_data;
				end
			end
			4'b0010: begin // start bit
				start_bit <= 0;
				bit_count <= 0;
				stop_bit <= 1;
				state <= 4'b0011;
			end
			4'b0011: begin // data bits
				if (bit_count < 8) begin
					tx <= data[bit_count];
					bit_count <= bit_count + 1;
				end else begin
					state <= 4'b0100;
				end
			end
			4'b0100: begin // stop bit
				start_bit <= 1;
				bit_count <= 0;
				stop_bit <= 0;
				state <= 4'b0101;
			end
			4'b0101: begin // wait for stop bit
				if (bit_count >= BIT_TIME) begin
					state <= 4'b0000;
					ready <= 1;
				end else begin
					bit_count <= bit_count + 1;
				end
			end
			default: begin
				state <= 4'b0000;
			end
		endcase
	end
end

endmodule

module subtraction_module (input [3:0] a, b, output [3:0] diff, borrow_out);

  wire [3:0] ones_complement_b;
  wire [3:0] sum;
  wire carry_out;

  // Calculate the ones complement of b
  assign ones_complement_b = ~b;

  // Connect the full adder modules to perform subtraction
  full_adder fa0(a[0], ones_complement_b[0], 1'b1, sum[0], borrow_out);
  full_adder fa1(a[1], ones_complement_b[1], borrow_out, sum[1], borrow_out);
  full_adder fa2(a[2], ones_complement_b[2], borrow_out, sum[2], borrow_out);
  full_adder fa3(a[3], ones_complement_b[3], borrow_out, sum[3], borrow_out);

  // Output the difference and borrow out
  assign diff = sum;
  assign borrow_out = ~borrow_out;

endmodule

