module adder32(
    input [31:0] a,
    input [31:0] b,
    output [31:0] sum
);
    wire [31:0] g;
    wire [31:0] p;
    wire [31:0] c;
    wire [31:0] c_out;

    assign g = a & b;
    assign p = a | b;
    assign c[0] = g[0];

    genvar i;
    generate
        for (i = 1; i < 32; i = i + 1) begin
            assign c[i] = g[i] | (p[i] & c[i-1]);
        end
    endgenerate

    assign c_out = c[31];
    assign sum = a + b;
endmodule
