module control_logic(
    input select,
    output reg [1:0] active_module
);
    always @(*) begin
        if (select == 1'b0) begin
            active_module <= 2'b01; // XOR gate is active
        end else begin
            active_module <= 2'b10; // Adder is active
        end
    end
endmodule
module top_module(
    input clk,
    input reset,
    input [31:0] a,
    input [31:0] b,
    input select,
    output [31:0] out_always_ff
);
    wire [1:0] active_module;
    wire [31:0] xor_out;
    wire [31:0] adder_out;
    wire [31:0] and_out;

    xor_gate xor_inst(
        .clk(clk),
        .in({a[0], b[0]}),
        .out(xor_out)
    );

    adder32 adder_inst(
        .a(a),
        .b(b),
        .sum(adder_out)
    );

    and_gate and_inst(
        .in1(xor_out),
        .in2(adder_out),
        .out(and_out)
    );

    control_logic control_inst(
        .select(select),
        .active_module(active_module)
    );

    always @(posedge clk) begin
        if (reset) begin
            out_always_ff <= 0;
        end else begin
            case (active_module)
                2'b01: out_always_ff <= xor_out;
                2'b10: out_always_ff <= adder_out;
            endcase
        end
    end
endmodule

