module data_accumulation_bcd_conversion (
  input clk,
  input reset,
  input [7:0] data_in,
  input valid_a,
  input ready_b,
  input [2:0] threshold,
  output ready_a,
  output reg valid_b,
  output reg [11:0] data_out_binary,
  output reg [3:0] data_out_bcd
);

  // Internal signals
  reg [11:0] accumulator;
  reg [3:0] bcd_value;
  reg [3:0] bcd_temp;
  reg [2:0] count;

  // Valid-ready handshake
  wire valid_a_next;
  wire ready_b_next;
  assign valid_a_next = (accumulator >= {4'b0, threshold});
  assign ready_a = ~valid_b;
  assign ready_b_next = ~valid_a_next;
  assign valid_b = valid_a & ready_b;

  // Data accumulation
  always @(posedge clk) begin
    if (reset) begin
      accumulator <= 12'b0;
      count <= 3'b0;
      bcd_value <= 4'b0;
      bcd_temp <= 4'b0;
    end else if (valid_a & ready_b) begin
      accumulator <= accumulator + data_in;
      count <= count + 1;
      if (count == 4) begin
        bcd_temp <= accumulator[11:8];
        bcd_value <= bcd_value + bcd_temp;
        bcd_value <= {bcd_value[2:0], bcd_value[3]};
        bcd_temp <= accumulator[7:4];
        bcd_value <= bcd_value + bcd_temp;
        bcd_value <= {bcd_value[2:0], bcd_value[3]};
        bcd_temp <= accumulator[3:0];
        bcd_value <= bcd_value + bcd_temp;
        bcd_value <= {bcd_value[2:0], bcd_value[3]};
        count <= 3'b0;
        accumulator <= 12'b0;
      end
    end
  end

  // Output assignment
  always @(posedge clk) begin
    if (reset) begin
      data_out_binary <= 12'b0;
      data_out_bcd <= 4'b0;
    end else if (valid_a & ready_b) begin
      data_out_binary <= accumulator;
      data_out_bcd <= bcd_value;
    end
  end

  // Ready and valid signals
  always @(posedge clk) begin
    if (reset) begin
      ready_b <= 1'b1;
    end else begin
      ready_b <= ready_b_next;
    end
  end

endmodule

module mux_encoder (
    input [3:0] A,
    input [3:0] B,
    input [3:0] C,
    input [3:0] D,
    input [1:0] SEL,
    output [3:0] Q
);

wire [3:0] highest_priority_input;

// Priority encoder
assign highest_priority_input = (D > C) ? 4'b1100 : 4'b1000;
assign highest_priority_input = (highest_priority_input > B) ? highest_priority_input : 4'b0100;
assign highest_priority_input = (highest_priority_input > A) ? highest_priority_input : 4'b0010;
assign highest_priority_input = (highest_priority_input > 4'b0001) ? highest_priority_input : 4'b0001;

// Multiplexer
always @(*) begin
    case (SEL)
        2'b00: Q = A;
        2'b01: Q = B;
        2'b10: Q = C;
        2'b11: Q = D;
    endcase
end

// Output the highest priority input if multiple inputs are high
assign Q = (A == highest_priority_input) ? A :
            (B == highest_priority_input) ? B :
            (C == highest_priority_input) ? C :
            (D == highest_priority_input) ? D :
            4'b0000;

endmodule

