module ripple_carry_adder (
  input [3:0] A,
  input [3:0] B,
  output [3:0] S,
  output cout
);

  wire [3:0] sum;
  wire [3:0] carry;

  assign sum[0] = A[0] ^ B[0];
  assign carry[0] = A[0] & B[0];

  assign sum[1] = A[1] ^ B[1] ^ carry[0];
  assign carry[1] = (A[1] & B[1]) | (A[1] & carry[0]) | (B[1] & carry[0]);

  assign sum[2] = A[2] ^ B[2] ^ carry[1];
  assign carry[2] = (A[2] & B[2]) | (A[2] & carry[1]) | (B[2] & carry[1]);

  assign sum[3] = A[3] ^ B[3] ^ carry[2];
  assign cout = (A[3] & B[3]) | (A[3] & carry[2]) | (B[3] & carry[2]);

  assign S = sum;

endmodule

module full_adder (
  input a,
  input b,
  input cin,
  output sum,
  output cout
);

  wire s1, c1, c2;

  assign {c1, s1} = a + b;
  assign {cout, sum} = s1 + cin;

endmodule

module top_module (
  input [3:0] A,
  input [3:0] B,
  input a,
  input b,
  input cin,
  output [3:0] S,
  output cout,
  output [3:0] final_output
);

  wire [3:0] ripple_sum;
  wire ripple_cout;
  wire full_sum, full_cout;

  ripple_carry_adder rca (
    .A(A),
    .B(B),
    .S(ripple_sum),
    .cout(ripple_cout)
  );

  full_adder fa (
    .a(a),
    .b(b),
    .cin(ripple_cout),
    .sum(full_sum),
    .cout(full_cout)
  );

  assign final_output = ripple_sum + {full_cout, full_sum};

  assign S = ripple_sum;
  assign cout = full_cout;

endmodule

