always @(posedge clk, negedge reset) begin
    if (!reset) begin
        shift_reg <= 4'b0;
    end else if (load) begin
        shift_reg <= data_in;
    end else begin
        shift_reg <= {shift_reg[2:0], shift_reg[3]};
    end
end

assign data_out = shift_reg;

endmodule

