module MMU (
  input [31:0] va,
  input [31:0] ptba,
  input pte_v,
  input pte_d,
  input [1:0] pte_p,
  output [31:0] pa
);

  reg [31:0] page_table [0:1023];
  reg [9:0] page_number;
  reg [9:0] page_offset;
  reg [31:0] page_table_entry;

  assign page_number = va[31:22];
  assign page_offset = va[21:0];

  always @(*) begin
    if (pte_v == 0) begin
      $display("Page table entry is not valid");
      $finish;
    end else if (pte_p == 0) begin
      $display("No access to page table entry");
      $finish;
    end else if (pte_p == 1 && pte_d == 1) begin
      $display("Write to read-only page table entry");
      $finish;
    end else begin
      page_table_entry = page_table[ptba + page_number];
      if (page_table_entry[0] == 0) begin
        $display("Page table entry is not valid");
        $finish;
      end else begin
        if (pte_d == 1) begin
          page_table_entry[1] = 1;
          page_table[ptba + page_number] = page_table_entry;
          $display("Page table entry is dirty, writing back to memory");
        end
        pa = (page_table_entry & 32'hFFFFF000) | page_offset;
      end
    end
  end

endmodule

