// VGA interface
module vga_interface (
    input clk,
    output reg [4:0]b,
    output reg [5:0]g,
    output reg hs,
    output reg [4:0]r,
    output reg vs
);

    // VGA timing parameters
    parameter H_RES = 640;
    parameter H_SYNC_START = 656;
    parameter H_SYNC_END = 752;
    parameter H_TOTAL = 800;
    parameter V_RES = 480;
    parameter V_SYNC_START = 490;
    parameter V_SYNC_END = 492;
    parameter V_TOTAL = 525;

    // VGA counters
    reg [9:0]h_count, v_count;

    // VGA horizontal sync
    always @(posedge clk) begin
        if (h_count == H_TOTAL - 1) begin
            hs <= 1'b1;
            h_count <= 0;
        end else if (h_count == H_SYNC_END - 1) begin
            hs <= 1'b0;
            h_count <= h_count + 1;
        end else if (h_count == H_SYNC_START - 1) begin
            h_count <= h_count + 1;
        end else begin
            h_count <= h_count + 1;
        end
    end

    // VGA vertical sync
    always @(posedge clk) begin
        if (v_count == V_TOTAL - 1) begin
            vs <= 1'b1;
            v_count <= 0;
        end else if (v_count == V_SYNC_END - 1) begin
            vs <= 1'b0;
            v_count <= v_count + 1;
        end else if (v_count == V_SYNC_START - 1) begin
            v_count <= v_count + 1;
        end else begin
            v_count <= v_count + 1;
        end
    end

    // VGA color output
    always @(posedge clk) begin
        if (h_count >= H_RES || v_count >= V_RES) begin
            r <= 5'b0;
            g <= 6'b0;
            b <= 5'b0;
        end else begin
            r <= 5'b11111;
            g <= 6'b111111;
            b <= 5'b11111;
        end
    end

endmodule

