  output reg [3:0] count
);

  reg [3:0] next_count;

  always @ (posedge clk) begin
    if (reset) begin
      next_count <= 4'b0000;
    end
    else begin
      next_count <= count + 1;
    end
  end

  always @ (*) begin
    case (count)
      4'b0000: begin
        count[0] = 1'b0;
        count[1] = 1'b0;
        count[2] = 1'b0;
        count[3] = 1'b0;
      end
      4'b0001: begin
        count[0] = 1'b1;
        count[1] = 1'b0;
        count[2] = 1'b0;
        count[3] = 1'b0;
      end
      4'b0010: begin
        count[0] = 1'b0;
        count[1] = 1'b1;
        count[2] = 1'b0;
        count[3] = 1'b0;
      end
      4'b0011: begin
        count[0] = 1'b1;
        count[1] = 1'b1;
        count[2] = 1'b0;
        count[3] = 1'b0;
      end
      4'b0100: begin
        count[0] = 1'b0;
        count[1] = 1'b0;
        count[2] = 1'b1;
        count[3] = 1'b0;
      end
      4'b0101: begin
        count[0] = 1'b1;
        count[1] = 1'b0;
        count[2] = 1'b1;
        count[3] = 1'b0;
      end
      4'b0110: begin
        count[0] = 1'b0;
        count[1] = 1'b1;
        count[2] = 1'b1;
        count[3] = 1'b0;
      end
      4'b0111: begin
        count[0] = 1'b1;
        count[1] = 1'b1;
        count[2] = 1'b1;
        count[3] = 1'b0;
      end
      4'b1000: begin
        count[0] = 1'b0;
        count[1] = 1'b0;
        count[2] = 1'b0;
        count[3] = 1'b1;
      end
      4'b1001: begin
        count[0] = 1'b1;
        count[1] = 1'b0;
        count[2] = 1'b0;
        count[3] = 1'b1;
      end
      4'b1010: begin
        count[0] = 1'b0;
        count[1] = 1'b1;
        count[2] = 1'b0;
        count[3] = 1'b1;
      end
      4'b1011: begin
        count[0] = 1'b1;
        count[1] = 1'b1;
        count[2] = 1'b0;
        count[3] = 1'b1;
      end
      4'b1100: begin
        count[0] = 1'b0;
        count[1] = 1'b0;
        count[2] = 1'b1;
        count[3] = 1'b1;
      end
      4'b1101: begin
        count[0] = 1'b1;
        count[1] = 1'b0;
        count[2] = 1'b1;
        count[3] = 1'b1;
      end
      4'b1110: begin
        count[0] = 1'b0;
        count[1] = 1'b1;
        count[2] = 1'b1;
        count[3] = 1'b1;
      end
      4'b1111: begin
        count[0] = 1'b1;
        count[1] = 1'b1;
        count[2] = 1'b1;
        count[3] = 1'b1;
      end
      default: begin
        count[0] = 1'b0;
        count[1] = 1'b0;
        count[2] = 1'b0;
        count[3] = 1'b0;
      end
    endcase
  end

  always @ (*) begin
    count <= next_count;
  end

endmodule

