module pipeline (
    input clk,
    input reset,
    input [7:0] instruction,
    input [2:0] stage,
    input [4:0] rs1,
    input [4:0] rs2,
    input [4:0] rd,
    input [31:0] data1,
    input [31:0] data2,
    output reg [31:0] regfile [7:0]
);

reg [7:0] pc;
reg [7:0] inst_mem [255:0];
wire [31:0] alu_out;
wire [31:0] data_out;
reg [31:0] data_in;

// Fetch stage
always @(posedge clk) begin
    if (reset) begin
        pc <= 0;
    end else begin
        pc <= pc + 1;
    end
end

// Decode stage
always @(posedge clk) begin
    if (reset) begin
        rs1 <= 0;
        rs2 <= 0;
        rd <= 0;
    end else begin
        rs1 <= instruction[4:0];
        rs2 <= instruction[9:5];
        rd <= instruction[7:5];
    end
end

// Execute stage
always @(posedge clk) begin
    if (reset) begin
        data_in <= 0;
    end else begin
        case (instruction[7:0])
            8'b00000000: alu_out <= data1 + data2; // ADD
            8'b00010000: alu_out <= data1 - data2; // SUB
            8'b00100000: alu_out <= data1 & data2; // AND
            8'b00110000: alu_out <= data1 | data2; // OR
            default: alu_out <= 0;
        endcase
        data_in <= alu_out;
    end
end

// Register file
always @(posedge clk) begin
    if (reset) begin
        regfile <= 0;
    end else begin
        case (stage)
            3'b001: data_out <= regfile[rs1];
            3'b010: data_out <= regfile[rs2];
            3'b100: data_out <= data_in;
            default: data_out <= 0;
        endcase
        if (stage == 3'b100) begin
            regfile[rd] <= data_out;
        end
    end
end

// Instruction memory
initial begin
    inst_mem[0] = 8'b00000000; // ADD R0, R0, R0
    inst_mem[1] = 8'b00010001; // SUB R0, R0, R1
    inst_mem[2] = 8'b00100010; // AND R0, R0, R2
    inst_mem[3] = 8'b00110011; // OR R0, R0, R3
end

assign instruction = inst_mem[pc];

endmodule

