module functional_module (
    input [31:0] regfile_data,
    input [31:0] execute_data,
    input [7:0] instruction,
    output [31:0] alu_result
);

reg [31:0] alu_in;

always @(*) begin
    case (instruction[7:0])
        8'b00000000: alu_in = regfile_data + execute_data; // ADD
        8'b00010000: alu_in = regfile_data - execute_data; // SUB
        8'b00100000: alu_in = regfile_data & execute_data; // AND
        8'b00110000: alu_in = regfile_data | execute_data; // OR
        default: alu_in = 0;
    endcase
end

assign alu_result = alu_in;

endmodule

