module MD5 (
  input [511:0] message,
  output [127:0] hash
);

  // Constants for MD5
  reg [31:0] A = 32'h67452301;
  reg [31:0] B = 32'hEFCDAB89;
  reg [31:0] C = 32'h98BADCFE;
  reg [31:0] D = 32'h10325476;

  // Padding
  reg [511:0] padded_message;
  always @(*) begin
    padded_message[0] = 1'b1;
    padded_message[511:1] = message;
  end

  // Message Digest Initialization
  reg [127:0] digest;
  always @(*) begin
    digest[31:0] = A;
    digest[63:32] = B;
    digest[95:64] = C;
    digest[127:96] = D;
  end

  // Message Digest Calculation
  integer i;
  reg [31:0] F, G;
  always @(*) begin
    for (i = 0; i < 64; i = i + 1) begin
      if (i < 16) begin
        F = (B & C) | (~B & D);
        G = i;
      end else if (i < 32) begin
        F = (D & B) | (~D & C);
        G = (5 * i + 1) % 16;
      end else if (i < 48) begin
        F = B ^ C ^ D;
        G = (3 * i + 5) % 16;
      end else begin
        F = C ^ (B | ~D);
        G = (7 * i) % 16;
      end

      F = F + A + padded_message[32*G +: 32] + 32'h5A827999;
      A = D;
      D = C;
      C = B;
      B = B + (F << i | F >> (32 - i));
    end
  end

  // Output
  assign hash = digest;

endmodule

module fifo_ctr (

    // inputs
    input wire clk,
    input wire rst_n,
    input wire push,
    input wire pop,

    // outputs
    output reg empty,
    output reg almost_empty,
    output reg full,
    output reg almost_full,
    output reg error,
    output reg cen,
    output reg wen,
    output reg oen,
    output reg [4:0] addr
);

parameter numOfRam = 32;
// small delay of flip-flop outputs
parameter delay = 1.5;

// state encoding
parameter EMPTY   = 2'b00;
parameter BETWEEN = 2'b01;
parameter READOUT = 2'b10;
parameter FULL    = 2'b11;

// state vector
reg    [1:0] state;
reg    [1:0] state_next;

// pointers
reg    [4:0] head;
reg    [4:0] head_next;
reg    [4:0] tail;
reg    [4:0] tail_next;

reg    head_plus;
reg    tail_plus;
reg    addr_head;
reg    addr_tail;

reg    do_idle;
reg    do_pop;
reg    do_push;
reg    do_push_pop;

// sequential part
always @(posedge clk or negedge rst_n) begin
    if (rst_n == 0) begin
        state <= EMPTY;
        head  <= 5'b0;
        tail  <= 5'b0;
    end else begin
        state <= #(delay) state_next;
        head  <= #(delay) head_next;
        tail  <= #(delay) tail_next;
    end
end

// combinational parts

always @(*) begin
    do_idle = 1'b0;
    do_pop  = 1'b0;
    do_push = 1'b0;
    do_push_pop = 1'b0;
    case ({push,pop})
        2'b00: begin do_idle = 1'b1; end
        2'b01: begin do_pop = 1'b1; end
        2'b10: begin do_push = 1'b1; end
        2'b11: begin do_push_pop = 1'b1; end
    endcase
end

always @(*) begin
    if (head_plus) begin
        head_next = (head + 1'b1)%numOfRam;
    end else begin
        head_next = head;
    end
    if (tail_plus) begin
        tail_next = (tail + 1'b1)%numOfRam;
    end else begin
        tail_next = tail;
    end
end

always @(*) begin
    if (tail == head - 1'b1) begin
        almost_empty  = 1'b1;
    end else begin
        almost_empty  = 1'b0;
    end
    if (head == tail - 1'b1) begin
        almost_full   = 1'b1;
    end else begin
        almost_full   = 1'b0;
    end
    oen               = 1'b0;
end

// FSM
always @(*) begin
    empty         = 1'b0;
    full          = 1'b0;
    error         = 1'b0;
    cen           = 1'b0;
    wen           = 1'b0;
    addr          = 5'b0;
    head_plus     = 1'b0;
    tail_plus     = 1'b0;
    addr_head     = 1'b0;
    addr_tail     = 1'b0;
    state_next    = state;

    case (state)
        EMPTY:    begin
            if (do_idle || do_pop || do_push_pop) begin
                error         = (do_pop | do_push_pop);
                state_next    = EMPTY;
            end else if (do_push) begin
                addr          = head;
                head_plus     = 1'b1;
                wen           = 1'b0;
                state_next    = BETWEEN;
            end
        end
        BETWEEN:  begin
            if (do_push && !almost_full) begin
                addr          = head;
                head_plus     = 1'b1;
                wen           = 1'b0;
                state_next    = BETWEEN;
            end else if (do_idle || do_push_pop) begin
                error         = do_push_pop;
                state_next    = BETWEEN;
            end else if (do_pop) begin
                addr          = tail;
                state_next    = READOUT;
            end else if (do_push && almost_full) begin
                addr          = head;
                head_plus     = 1'b1;
                wen           = 1'b0;
                state_next    = FULL;
            end
        end
        READOUT:  begin
            if (!almost_empty) begin
                tail_plus     = 1'b1;
                error         = (do_push | do_pop);
                state_next    = BETWEEN;
            end else begin
                tail_plus     = 1'b1;
                error         = (do_push | do_pop);
                state_next    = EMPTY;
            end
        end
        FULL:     begin
            if (do_pop) begin
                addr          = tail;
                state_next    = READOUT;
            end else if (do_idle || do_push || do_push_pop) begin
                error         = (do_push | do_push_pop);
                state_next    = FULL;
            end
        end
    endcase
end

assign cen = 1'b1;
assign addr_head = (state == BETWEEN) && (do_push || do_push_pop);
assign addr_tail = (state == READOUT) && (do_pop);
assign addr = addr_head ? head : addr_tail ? tail : 5'b0;

assign empty = (state == EMPTY) && (!almost_empty);
assign full = (state == FULL) && (!almost_full);
assign wen = (state == BETWEEN) && (do_push || do_push_pop);
assign oen = (state == READOUT) && (do_pop);

endmodule

