module cpu_module (
  input clk,
  input reset_,
  input cs,
  input rnw,
  input req,
  input [7:0] wr_data,
  input [7:0] addr,
  input up,
  input down,
  input left,
  input right,
  output rdy,
  output reg [7:0] dpads,
  output reg [7:0] leds,
  output reg [7:0] rd_data
);

  wire up_debounced;
  wire down_debounced;
  wire left_debounced;
  wire right_debounced;

  wire wr_enable;
  wire rd_enable;
  wire up_released;
  wire down_released;
  wire left_released;
  wire right_released;
  wire up_pressed;
  wire down_pressed;
  wire left_pressed;
  wire right_pressed;

  reg [1:0] up_shift;
  reg [1:0] down_shift;
  reg [1:0] left_shift;
  reg [1:0] right_shift;

  parameter LED_CTRL_REG    = 8'd0;
  parameter SWITCH_CTRL_REG = 8'd1;
  parameter DPAD_CTRL_REG   = 8'd2;

  assign wr_enable = cs && !rnw && req;
  assign rd_enable = cs && rnw && req;

  assign left_released  = left_shift == 2'b10;
  assign right_released = right_shift == 2'b10;
  assign up_released    = up_shift == 2'b10;
  assign down_released  = down_shift == 2'b10;
  assign left_pressed   = left_shift == 2'b01;
  assign right_pressed  = right_shift == 2'b01;
  assign up_pressed     = up_shift == 2'b01;
  assign down_pressed   = down_shift == 2'b01;

  always @ (posedge clk or negedge reset_) begin
    if (!reset_) begin
      leds <= 8'h00;
    end else if (addr == LED_CTRL_REG && wr_enable) begin
      leds <= wr_data[7:0];
    end
  end

  always @ (posedge clk or negedge reset_) begin
    if (!reset_) begin
      dpads <= 8'd0;
    end else if (wr_enable && addr == DPAD_CTRL_REG) begin
      dpads <= 8'd0;
    end else begin
      dpads <= {dpads[7] || up_pressed,
                dpads[6] || down_pressed,
                dpads[5] || left_pressed,
                dpads[4] || right_pressed,
                dpads[3] || up_released,
                dpads[2] || down_released,
                dpads[1] || left_released,
                dpads[0] || right_released};
    end
  end

  always @ (posedge clk or negedge reset_) begin
    if (!reset_) begin
      rd_data <= 8'h00;
    end else if (addr == LED_CTRL_REG && rd_enable) begin
      rd_data <= leds;
    end else if (addr == SWITCH_CTRL_REG && rd_enable) begin
      rd_data <= {switches[6:0], 1'b0};
    end else if (addr == DPAD_CTRL_REG && rd_enable) begin
      rd_data <= dpads;
    end
  end

  always @ (posedge clk or negedge reset_) begin
    if (!reset_) begin
      rdy <= 1'b0;
    end else begin
      rdy <= req;
    end
  end

  always @ (posedge clk or negedge reset_) begin
    if (!reset_) begin
      up_shift <= 2'd0;
    end else begin
      up_shift <= {up_shift[0], up_debounced};
    end
  end

  always @ (posedge clk or negedge reset_) begin
    if (!reset_) begin
      down_shift <= 2'd0;
    end else begin
      down_shift <= {down_shift[0], down_debounced};
    end
  end

  always @ (posedge clk or negedge reset_) begin
    if (!reset_) begin
      left_shift <= 2'd0;
    end else begin
      left_shift <= {left_shift[0], left_debounced};
    end
  end

  always @ (posedge clk or negedge reset_) begin
    if (!reset_) begin
      right_shift <= 2'd0;
    end else begin
      right_shift <= {right_shift[0], right_debounced};
    end
  end

  debouncer up_debouncer (
    .clk(clk),
    .reset_(reset_),
    .raw(up),
    .debounced(up_debounced)
  );

  debouncer down_debouncer (
    .clk(clk),
    .reset_(reset_),
    .raw(down),
    .debounced(down_debounced)
  );

  debouncer left_debouncer (
    .clk(clk),
    .reset_(reset_),
    .raw(left),
    .debounced(left_debounced)
  );

  debouncer right_debouncer (
    .clk(clk),
    .reset_(reset_),
    .raw(right),
    .debounced(right_debounced)
  );

endmodule

