module ram (
	address,
	byteena,
	clock,
	data,
	rden,
	wren,
	q);

	input	[9:0]  address;
	input	[3:0]  byteena;
	input	  clock;
	input	[31:0]  data;
	input	  rden;
	input	  wren;
	output	[31:0]  q;

	reg [31:0] mem [0:1023];

	always @(posedge clock) begin
		if (wren == 1'b0 && rden == 1'b1) begin
			q <= {mem[address][31:24], mem[address][23:16], mem[address][15:8], mem[address][7:0]} & byteena;
		end
		if (wren == 1'b1 && rden == 1'b0) begin
			if (byteena == 4'b1111) begin
				mem[address] <= data;
			end else if (byteena == 4'b0001) begin
				mem[address][7:0] <= data[7:0];
			end else if (byteena == 4'b0010) begin
				mem[address][15:8] <= data[15:8];
			end else if (byteena == 4'b0100) begin
				mem[address][23:16] <= data[23:16];
			end else if (byteena == 4'b1000) begin
				mem[address][31:24] <= data[31:24];
			end
		end
	end

endmodule

module ripple_carry_adder (
    input [15:0] A,
    input [15:0] B,
    output reg [15:0] sum,
    output overflow
);

reg [15:0] carry;
wire [15:0] temp_sum;

genvar i;
generate
    for (i = 0; i < 16; i = i + 1) begin : full_adder_loop
        full_adder fa(
            .a(A[i]),
            .b(B[i]),
            .cin(carry[i]),
            .sum(temp_sum[i]),
            .cout(carry[i+1])
        );
    end
endgenerate

assign sum = temp_sum;
assign overflow = carry[16];

endmodule

module full_adder (
    input a,
    input b,
    input cin,
    output reg sum,
    output reg cout
);

always @(*) begin
    sum = a ^ b ^ cin;
    cout = (a & b) | (a & cin) | (b & cin);
end

endmodule

