module fifo9togmii (
    input sys_rst,
    input rd_en,
    input rd_clk,
    output reg [8:0] dout,
    output reg empty,
    output reg gmii_tx_en,
    output reg [7:0] gmii_txd,
    output reg gmii_tx_clk
);

parameter FIFO_DEPTH = 4096;
parameter FIFO_WIDTH = 9;

reg [FIFO_WIDTH-1:0] fifo [0:FIFO_DEPTH-1];
reg [11:0] wr_ptr = 0;
reg [11:0] rd_ptr = 0;
reg [11:0] next_wr_ptr = 0;
reg [11:0] next_rd_ptr = 0;
reg [11:0] fifo_count = 0;

always @(posedge rd_clk) begin
    if (rd_en && !empty) begin
        dout <= fifo[rd_ptr];
        rd_ptr <= rd_ptr + 1;
        fifo_count <= fifo_count - 1;
        if (fifo_count == 0) begin
            empty <= 1;
        end
    end
end

always @(posedge gmii_tx_clk) begin
    if (gmii_tx_en) begin
        gmii_txd <= fifo[rd_ptr];
        rd_ptr <= rd_ptr + 1;
        fifo_count <= fifo_count - 1;
        if (fifo_count == 0) begin
            empty <= 1;
        end
    end
end

always @(posedge rd_clk) begin
    if (next_rd_ptr != rd_ptr) begin
        empty <= 0;
    end
end

always @(posedge rd_clk) begin
    if (sys_rst) begin
        wr_ptr <= 0;
        rd_ptr <= 0;
        next_wr_ptr <= 0;
        next_rd_ptr <= 0;
        fifo_count <= 0;
        empty <= 1;
    end else begin
        wr_ptr <= next_wr_ptr;
        rd_ptr <= next_rd_ptr;
        fifo_count <= fifo_count + (next_wr_ptr != next_rd_ptr ? 1 : 0);
    end
end

always @(posedge rd_clk) begin
    if (!empty && rd_ptr == wr_ptr) begin
        wr_ptr <= wr_ptr + 1;
        fifo_count <= fifo_count - 1;
    end
end

always @(posedge rd_clk) begin
    if (fifo_count < FIFO_DEPTH) begin
        next_wr_ptr <= wr_ptr + 1;
    end else begin
        next_wr_ptr <= wr_ptr;
    end
end

assign gmii_tx_clk = rd_clk;

endmodule

module top_module (
    input clk,
    input reset,            // Synchronous active-high reset
    input [15:0] in,        // 16-bit input
    output [7:0] out_hi,    // 8-bit output for the upper byte
    output [7:0] out_lo,    // 8-bit output for the lower byte
    output reg [7:0] out    // 8-bit output for the final output
);

    reg [7:0] lo_reg, hi_reg;

    barrel_shifter shifter(.in(in), .out(hi_reg));
    flip_flop lo_flip_flop(.clk(clk), .reset(reset), .d(in & 8'hFF), .q(lo_reg));
    functional_module func(.in1(hi_reg), .in2(lo_reg), .out(out));

    always @(posedge clk, posedge reset) begin
        if (reset) begin
            lo_reg <= 8'h34;
            hi_reg <= 8'h34;
            out <= 8'h00;
        end else begin
            lo_reg <= lo_flip_flop.q;
            hi_reg <= shifter.out;
            out <= func.out;
        end
    end

    assign out_hi = hi_reg;
    assign out_lo = lo_reg;

endmodule

