module PLL (
  input clk_ref, // reference clock signal
  input clk_fb, // feedback clock signal
  output reg clk_out // output clock signal
);

parameter N = 4; // multiplication factor
parameter M = 1; // division factor
parameter F = 100000000; // target frequency

reg [31:0] phase_accumulator;
reg [31:0] phase_increment;

always @(posedge clk_ref) begin
  phase_accumulator <= phase_accumulator + phase_increment;
end

always @(posedge clk_fb) begin
  phase_increment <= ((N * F) << 32) / (M * $frequency(clk_fb));
end

always @(posedge clk_ref) begin
  if (phase_accumulator >= (1 << 31)) begin
    phase_accumulator <= phase_accumulator - (1 << 31);
    clk_out <= ~clk_out;
  end
end

endmodule

module bit_reverse (
    input [7:0] in,
    output [7:0] out
);
    assign out = {in[7], in[6], in[5], in[4], in[3], in[2], in[1], in[0]};
endmodule

module priority_encoder (
    input [3:0] in,
    output [1:0] out
);
    assign out = (in[3]) ? 2 :
                 (in[2]) ? 1 :
                 (in[1]) ? 0 :
                 (in[0]) ? 0 : 2;
endmodule

module sum_modulo_256 (
    input [7:0] in1,
    input [1:0] in2,
    output [7:0] out
);
    assign out = (in1 + in2) % 256;
endmodule

