    wire [1:0] priority_encoder_out;
    bit_reverse bit_reverse_inst (
        .in(in),
        .out(bit_reverse_out)
    );
    priority_encoder priority_encoder_inst (
        .in(pri_enc_in),
        .out(priority_encoder_out)
    );
    sum_modulo_256 sum_modulo_256_inst (
        .in1(bit_reverse_out),
        .in2(priority_encoder_out),
        .out(out)
    );
endmodule

