module pipeline_multiplier (
  input clk,
  input reset,
  input [15:0] in,
  output reg [15:0] out
);

reg [7:0] in_low;
reg [7:0] in_high;
reg [7:0] mult1_out;
reg [7:0] mult2_out;
reg [15:0] pipeline_reg1;
reg [15:0] pipeline_reg2;

// Split input into two 8-bit parts
assign in_low = in[7:0];
assign in_high = in[15:8];

// First multiplier
always @(posedge clk) begin
  if (reset) begin
    mult1_out <= 0;
  end else begin
    mult1_out <= in_low * 3;
  end
end

// Second multiplier and pipeline register 1
always @(posedge clk) begin
  if (reset) begin
    mult2_out <= 0;
    pipeline_reg1 <= 0;
  end else begin
    mult2_out <= in_high * 3;
    pipeline_reg1 <= mult1_out;
  end
end

// Pipeline register 2 and output
always @(posedge clk) begin
  if (reset) begin
    pipeline_reg2 <= 0;
    out <= 0;
  end else begin
    pipeline_reg2 <= mult2_out;
    out <= pipeline_reg1 + pipeline_reg2;
  end
end

endmodule

module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    input cin,
    output [3:0] C,
    output cout
);

wire [3:0] s;
wire [3:0] c;

// Full adder for least significant bit
full_adder fa0(A[0], B[0], cin, s[0], c[0]);

// Full adder for second least significant bit
full_adder fa1(A[1], B[1], c[0], s[1], c[1]);

// Full adder for third least significant bit
full_adder fa2(A[2], B[2], c[1], s[2], c[2]);

// Full adder for most significant bit
full_adder fa3(A[3], B[3], c[2], s[3], cout);

assign C = s;

endmodule

module full_adder(
    input a,
    input b,
    input cin,
    output s,
    output cout
);

wire sum;
wire carry1;
wire carry2;

// XOR gate for sum
xor(sum, a, b);

// XOR gate for carry1
xor(carry1, sum, cin);

// AND gate for carry2
and(carry2, a, b);

// OR gate for cout
or(cout, carry1, carry2);

assign s = sum;

endmodule

