  output s_axi_awready,
  input [31:0]s_axi_wdata,
  input [3:0]s_axi_wstrb,
  input s_axi_wvalid,
  output s_axi_wready,
  output [1:0]s_axi_bresp,
  output s_axi_bvalid,
  input s_axi_bready,
  input [8:0]s_axi_araddr,
  input s_axi_arvalid,
  output s_axi_arready,
  output [31:0]s_axi_rdata,
  output [1:0]s_axi_rresp,
  output s_axi_rvalid,
  input s_axi_rready,
  output ip2intc_irpt,
  inout [19:0]gpio_io_i,
  inout [19:0]gpio_io_o,
  inout [19:0]gpio_io_t
);

  reg [19:0] gpio_input_reg;
  reg [19:0] gpio_output_reg;

  assign gpio_io_i = gpio_input_reg;
  assign gpio_io_o = gpio_output_reg;
  assign gpio_io_t = 20'hFFFFF;

  always @(posedge s_axi_aclk) begin
    if (!s_axi_aresetn) begin
      gpio_input_reg <= 20'h0;
      gpio_output_reg <= 20'h0;
    end else begin
      if (s_axi_arvalid && s_axi_arready) begin
        case (s_axi_araddr)
          8'h00: s_axi_rdata <= gpio_input_reg;
          default: s_axi_rdata <= 32'h0;
        endcase
      end

      if (s_axi_awvalid && s_axi_awready) begin
        case (s_axi_awaddr)
          8'h00: gpio_output_reg <= s_axi_wdata & s_axi_wstrb;
          default: gpio_output_reg <= gpio_output_reg;
        endcase
      end
    end
  end

  assign s_axi_awready = 1'b1;
  assign s_axi_wready = 1'b1;
  assign s_axi_bresp = 2'b00;
  assign s_axi_bvalid = 1'b0;
  assign s_axi_arready = 1'b1;
