module spi_state_machine (
  input clk,
  input rst,
  input start,
  input [7:0] data_in,
  input data_ready,
  output reg [7:0] data_out,
  output reg done
);

  // Define state machine states
  parameter IDLE = 2'b00;
  parameter TRANSMIT = 2'b01;
  parameter RECEIVE = 2'b10;

  // Define state machine signals
  reg [1:0] state;
  reg [7:0] tx_data;
  reg [7:0] rx_data;
  reg tx_done;
  reg rx_done;

  // State machine logic
  always @(posedge clk) begin
    if (rst) begin
      state <= IDLE;
      tx_data <= 8'h00;
      rx_data <= 8'h00;
      tx_done <= 1'b0;
      rx_done <= 1'b0;
      done <= 1'b0;
    end else begin
      case (state)
        IDLE: begin
          if (start) begin
            state <= TRANSMIT;
          end
        end
        TRANSMIT: begin
          if (tx_done) begin
            state <= RECEIVE;
          end
        end
        RECEIVE: begin
          if (rx_done) begin
            state <= IDLE;
            done <= 1'b1;
          end
        end
      endcase
    end
  end

  // Transmit logic
  always @(posedge clk) begin
    if (rst) begin
      tx_data <= 8'h00;
      tx_done <= 1'b0;
    end else begin
      case (state)
        IDLE: begin
          tx_data <= 8'h00;
          tx_done <= 1'b0;
        end
        TRANSMIT: begin
          if (data_ready) begin
            tx_data <= data_in;
            tx_done <= 1'b1;
          end
        end
        RECEIVE: begin
          tx_data <= 8'h00;
          tx_done <= 1'b0;
        end
      endcase
    end
  end

  // Receive logic
  always @(posedge clk) begin
    if (rst) begin
      rx_data <= 8'h00;
      rx_done <= 1'b0;
    end else begin
      case (state)
        IDLE: begin
          rx_data <= 8'h00;
          rx_done <= 1'b0;
        end
        TRANSMIT: begin
          rx_data <= 8'h00;
          rx_done <= 1'b0;
        end
        RECEIVE: begin
          rx_data <= rx_data << 1;
          rx_data[0] <= 1'b0;
          if (data_ready) begin
            rx_data[0] <= 1'b1;
          end
          if (rx_done) begin
            data_out <= rx_data;
          end
        end
      endcase
    end
  end

endmodule

