module subtractor (
    input clk,
    input reset,
    input [7:0] a,
    input [7:0] b,
    output reg [8:0] out
);

reg [7:0] a_inv;
reg [8:0] sum;

// 8-bit ripple carry adder with active high synchronous reset
always @(posedge clk) begin
    if (reset) begin
        sum <= 0;
    end else begin
        sum <= {1'b0, a} + {1'b1, ~b} + sum[8];
    end
end

// comparator that outputs 1 if the two 8-bit inputs are equal
assign out[7:1] = (a == b) ? 1 : 0;

// functional module that takes in both of the outputs of the previous two modules and outputs the difference of the two 8-bit values
always @(*) begin
    a_inv = ~a;
    out[0] = sum[7:0] + a_inv[7:0] + 1;
    out[8] = sum[8] | a_inv[8];
end

endmodule

