module clock(
    input reset_in,
    input clk_10mhz_int,
    input clk_10mhz_ext,
    output reg clk_250mhz_int,
    output reg rst_250mhz_int,
    output reg clk_250mhz,
    output reg rst_250mhz,
    output reg ext_clock_selected
);

localparam IDLE = 2'b00, INTERNAL = 2'b01, EXTERNAL = 2'b10;

reg [1:0] state = IDLE;
reg [1:0] next_state = IDLE;
reg [1:0] prev_state = IDLE;

reg internal_clock_locked = 0;
reg external_clock_locked = 0;
reg external_clock_enable = 0;
reg external_clock_selected = 0;

reg [31:0] external_clock_count = 0;

wire external_clock_edge = clk_10mhz_ext ^ prev_clk_10mhz_ext;
reg [31:0] external_clock_period = 0;
reg [31:0] external_clock_period_filtered = 0;

always @(posedge clk_10mhz_int) begin
    prev_state <= state;
    state <= next_state;
end

always @(posedge clk_10mhz_int) begin
    case (state)
        IDLE: begin
            rst_250mhz <= 1'b1;
            clk_250mhz <= 1'b0;
            rst_250mhz_int <= 1'b1;
            clk_250mhz_int <= 1'b0;
            internal_clock_locked <= 0;
            external_clock_locked <= 0;
            external_clock_enable <= 0;
            external_clock_selected <= 0;
            external_clock_count <= 0;
            next_state <= INTERNAL;
        end
        INTERNAL: begin
            rst_250mhz <= 1'b0;
            clk_250mhz <= 1'b1;
            rst_250mhz_int <= reset_in;
            clk_250mhz_int <= clk_250mhz_int ^ internal_clock_locked;
            internal_clock_locked <= 1'b1;
            external_clock_locked <= 0;
            external_clock_enable <= 0;
            external_clock_selected <= 0;
            external_clock_count <= 0;
            if (reset_in) begin
                next_state <= INTERNAL;
            end else if (external_clock_edge) begin
                next_state <= EXTERNAL;
            end else begin
                next_state <= INTERNAL;
            end
        end
        EXTERNAL: begin
            rst_250mhz <= 1'b0;
            clk_250mhz <= 1'b1;
            rst_250mhz_int <= reset_in;
            clk_250mhz_int <= clk_250mhz_int ^ external_clock_locked;
            internal_clock_locked <= 0;
            external_clock_locked <= 1'b1;
            external_clock_enable <= 1'b1;
            external_clock_selected <= 1'b1;
            external_clock_count <= external_clock_count + 1;
            if (reset_in) begin
                next_state <= INTERNAL;
            end else if (external_clock_edge) begin
                next_state <= EXTERNAL;
            end else if (external_clock_count == 40000000) begin
                next_state <= INTERNAL;
            end else begin
                next_state <= EXTERNAL;
            end
        end
    endcase
end

always @(posedge clk_10mhz_int) begin
    prev_clk_10mhz_ext <= clk_10mhz_ext;
    external_clock_period <= external_clock_period + external_clock_edge;
    if (external_clock_period == 40000000) begin
        external_clock_period_filtered <= external_clock_period_filtered + external_clock_edge;
        external_clock_period <= 0;
    end
