module shift_adder_subtractor (
    input clk,
    input reset,
    input [3:0] data_in,
    input [3:0] A,
    input [3:0] B,
    input SUB,
    input CIN,
    output serial_out,
    output [3:0] sum,
    output reg overflow
);

// 4-bit shift register with parallel load and serial I/O
reg [3:0] shift_reg;
reg [3:0] shift_reg_next;
reg serial_out_next;
reg parallel_load;

always @(posedge clk) begin
    if (reset) begin
        shift_reg <= 4'b0000;
        serial_out <= 1'b0;
    end else begin
        if (parallel_load) begin
            shift_reg <= data_in;
        end else begin
            shift_reg <= shift_reg_next;
        end
        serial_out <= shift_reg[0];
    end
end

always @(*) begin
    if (serial_out) begin
        serial_out_next = shift_reg[3];
        shift_reg_next = {shift_reg[3:1], serial_out_next};
    end else begin
        serial_out_next = shift_reg[0];
        shift_reg_next = {serial_out, shift_reg[3:1]};
    end
end

// 4-bit adder/subtractor with overflow detection
wire [4:0] adder_out;
assign adder_out = {1'b0, A} + ({SUB, B});

always @(*) begin
    if (SUB) begin
        sum = A - B;
    end else begin
        sum = A + B;
    end
    overflow = (adder_out[4] != adder_out[3]);
end

// Additional functional module
wire [3:0] shift_reg_out;
assign shift_reg_out = shift_reg;

