wire [8:0] in_parity = {in, parity};
wire [8:0] in_parity_inv = ~in_parity;
wire carry;
full_adder fa0 (.a(in_parity_inv[0]), .b(in_parity_inv[1]), .c(1'b1), .s(out[0]), .co(carry));
