generate
    for (i = 1; i < 8; i = i + 1) begin : fa_gen
        full_adder fa (.a(in_parity_inv[i]), .b(carry), .c(1'b0), .s(out[i]), .co(carry));
    end
endgenerate
assign out[8] = parity;

// Output
assign out[9:3] = in_parity;
