module binary_adder_subtractor (
    A,
    B,
    S,
    C
);

    input [3:0] A, B;
    input S;
    output [3:0] C;

    wire [3:0] sum;
    wire carry;

    // Full adder for least significant bit
    fulladder fa0(
        .a(A[0]),
        .b(B[0]),
        .cin(S),
        .sum(sum[0]),
        .cout(carry)
    );

    // Full adder for second least significant bit
    fulladder fa1(
        .a(A[1]),
        .b(B[1]),
        .cin(carry),
        .sum(sum[1]),
        .cout(carry)
    );

    // Full adder for third least significant bit
    fulladder fa2(
        .a(A[2]),
        .b(B[2]),
        .cin(carry),
        .sum(sum[2]),
        .cout(carry)
    );

    // Full adder for most significant bit
    fulladder fa3(
        .a(A[3]),
        .b(B[3]),
        .cin(carry),
        .sum(sum[3]),
        .cout(carry)
    );

    // Mux to select between addition and subtraction
    assign C = S ? (A - B) : sum;

