  reg[1:0] msb;
  integer i;

  always @(posedge clk) begin
    msb = 2'b00;
    lsb = 4'b0000;
    for (i = 4; i >= 0; i = i - 1) begin
      if (lsb >= 5) begin
        lsb = lsb + 3;
