module or1200_freeze(
	// Clock and reset
	clk, rst,

	// Internal i/f
	multicycle, flushpipe, extend_flush, lsu_stall, if_stall,
	lsu_unstall, du_stall, mac_stall, 
	abort_ex,
	genpc_freeze, if_freeze, id_freeze, ex_freeze, wb_freeze,
	icpu_ack_i, icpu_err_i
);

//
// I/O
//
input				clk;
input				rst;
input	[`OR1200_MULTICYCLE_WIDTH-1:0]	multicycle;
input				flushpipe;
input				extend_flush;
input				lsu_stall;
input				if_stall;
input				lsu_unstall;
input				abort_ex;
input				du_stall;
input				mac_stall;
output				genpc_freeze;
output				if_freeze;
output				id_freeze;
output				ex_freeze;
output				wb_freeze;
input				icpu_ack_i;
input				icpu_err_i;

//
// Internal wires and regs
//
wire				multicycle_freeze;
reg	[`OR1200_MULTICYCLE_WIDTH-1:0]	multicycle_cnt;
reg				flushpipe_r;

//
// Pipeline freeze
//
// Rules how to create freeze signals:
// 1. Not overwriting pipeline stages:
// Freze signals at the beginning of pipeline (such as if_freeze) can be asserted more
// often than freeze signals at the of pipeline (such as wb_freeze). In other words, wb_freeze must never
// be asserted when ex_freeze is not. ex_freeze must never be asserted when id_freeze is not etc.
//
// 2. Inserting NOPs in the middle of pipeline only if supported:
// At this time, only ex_freeze (and wb_freeze) can be deassrted when id_freeze (and if_freeze) are asserted.
// This way NOP is asserted from stage ID into EX stage.
//
//assign genpc_freeze = du_stall | flushpipe_r | lsu_stall;
assign genpc_freeze = du_stall | flushpipe_r;
assign if_freeze = id_freeze | extend_flush;
assign id_freeze = (lsu_stall | (~lsu_unstall & if_stall) | multicycle_freeze ) | du_stall | mac_stall;
assign ex_freeze = wb_freeze;
assign wb_freeze = (lsu_stall | (~lsu_unstall & if_stall) | multicycle_freeze) | du_stall | mac_stall | abort_ex;

//
// registered flushpipe
//
always @(posedge clk or posedge rst)
	if (rst)
		flushpipe_r <= #1 1'b0;
	else if (icpu_ack_i | icpu_err_i)
		flushpipe_r <= #1 flushpipe;
	else if (!flushpipe)
		flushpipe_r <= #1 1'b0;

//
// Multicycle freeze
//
assign multicycle_freeze = |multicycle_cnt;

//
// Multicycle counter
//
always @(posedge clk or posedge rst)
	if (rst)
		multicycle_cnt <= #1 2'b00;
	else if (|multicycle_cnt)
		multicycle_cnt <= #1 multicycle_cnt - 2'd1;
	else if (|multicycle & !ex_freeze)
		multicycle_cnt <= #1 multicycle;

//
// Abstruct the signal we are interested in
//
always @(posedge clk or posedge rst)
	if (rst)
		id_freeze <= #1 1'b0;
	else if (extend_flush | if_freeze)
		id_freeze <= #1 1'b0;
	else
		id_freeze <= #1 ((lsu_stall | (~lsu_unstall & if_stall) | multicycle_freeze ) | du_stall | mac_stall);

endmodule

module lin_tx (
  input [7:0] data,
  input break,
  input sync,
  input clk,
  output tx
);

  reg [7:0] tx_data;
  reg [7:0] checksum;
  reg [3:0] state;
  reg tx_enable;
  reg break_sent;
  reg sync_sent;

  assign tx = tx_data[0];

  always @(posedge clk) begin
    if (break) begin
      state <= 4'b0001;
      tx_enable <= 1'b1;
      break_sent <= 1'b0;
      sync_sent <= 1'b0;
    end else if (sync) begin
      state <= 4'b0010;
      tx_enable <= 1'b1;
      break_sent <= 1'b1;
      sync_sent <= 1'b0;
    end else if (tx_enable) begin
      case (state)
        4'b0010: begin
          tx_data <= 8'b00000000;
          state <= 4'b0011;
          sync_sent <= 1'b1;
        end
        4'b0011: begin
          tx_data <= data;
          state <= 4'b0100;
        end
        4'b0100: begin
          checksum <= ~(tx_data + 8'b00000000);
          tx_data <= checksum;
          state <= 4'b0101;
        end
        4'b0101: begin
          tx_data <= 8'b11111111;
          state <= 4'b0110;
        end
        4'b0110: begin
          tx_data <= 8'b00000000;
          state <= 4'b0111;
        end
        4'b0111: begin
          tx_enable <= 1'b0;
          state <= 4'b0000;
        end
      endcase
    end else begin
      tx_data <= 8'b00000000;
    end
  end

endmodule

module lin_rx (
  input rx,
  input break,
  input sync,
  input clk,
  output [7:0] data
