module MMU_UP ( BCLK, BRESET, NEW_PTB, PTB1, IVAR, WR_MRAM, VADR, VADR_R, MVALID, UPDATE,
                WE_MV, WADR_MV, RADR_MV, DAT_MV, NEW_PTB_RUN );

    input           BCLK;
    input           BRESET; 
    input           NEW_PTB;    // the MMU memory is cleared. Pulse of one BCLK cycle, Op-Dec is waiting
    input           PTB1;       // which one
    input           IVAR;
    input           WR_MRAM;    // BCLK : update MRAM and MMU_VAL
    input  [19:16]  VADR,VADR_R;    // For update
    input   [31:0]  MVALID,UPDATE;

    output          WE_MV;      // Write Enable MMU Valid
    output  [3:0]   WADR_MV,RADR_MV;
    output  [31:0]  DAT_MV;
    output          NEW_PTB_RUN;

    reg             neue_ptb,wr_flag,old_rst,run_over;
    reg         [3:0]   count;

    wire    [15:0]  new_val;

    assign WE_MV   = wr_flag | WR_MRAM | IVAR; // write on falling edge BCLK
    assign RADR_MV = run_over ? count : VADR;
    assign WADR_MV = wr_flag ? (count - 4'b0001) : VADR_R;
    assign DAT_MV  = wr_flag ? {MVALID[31:16],new_val} : UPDATE; // Only the matching entries are cleared : PTB0/PTB1

    // [31:16] Address-Space memory, [15:0] Valid memory
    assign new_val = neue_ptb ? (PTB1 ? (MVALID[15:0] & ~MVALID[31:16]) : (MVALID[15:0] & MVALID[31:16])) : 16'h0;

    always @(posedge BCLK or negedge BRESET)
        if (!BRESET) neue_ptb <= 1'b0;
            else neue_ptb <= NEW_PTB | (neue_ptb & run_over);

    always @(posedge BCLK) old_rst <= BRESET;    // after Reset all will be set to 0 

    always @(posedge BCLK) run_over <= ((~old_rst | NEW_PTB) | (run_over & (count != 4'hF))) & BRESET;

    always @(posedge BCLK) count <= run_over ? count + 4'h1 : 4'h0;

    always @(posedge BCLK) wr_flag <= run_over;

    assign NEW_PTB_RUN = wr_flag;   // Info to Op-Dec

endmodule

module unsigned_booth_multiplier (
  input [n-1:0] A,
  input [n-1:0] B,
  input clk,
  input rst,
  output reg [n-1:0] P
);

parameter n = 8; // number of bits in input and output

reg [n+1:0] shift_reg; // shift register with n+1 bits
reg [n-1:0] partial_product; // partial product register

always @(posedge clk) begin
  if (rst) begin
    shift_reg <= {1'b0, A, 1'b0}; // initialize shift register with n+1 bits
    partial_product <= {n{1'b0}}; // initialize partial product register with n bits
    P <= {n{1'b0}}; // initialize output with n bits
  end else begin
    for (i = 0; i < n; i = i + 1) begin
      // determine current state based on last two bits of shift register
      case (shift_reg[n+1:n]) 
        2'b00: value_to_add = {1'b0, B}; // shift A to right
        2'b01: value_to_add = {n{1'b0}} - B; // subtract B from A
        2'b10: value_to_add = B; // add B to A
        2'b11: value_to_add = {1'b0, {n-1{1'b0}}, 1'b1} - B; // shift A to left and subtract B
      endcase

      // add value to shift register
      shift_reg <= {shift_reg[n+1], shift_reg[n:1] + value_to_add};

      // shift A to left by iteration number
      A_shifted = {A, {i{1'b0}}};
      if (i >= n) begin
        A_shifted = {n{1'b0}};
      end

      // add product of A_shifted and value added to shift register to partial product register
      partial_product <= partial_product + (A_shifted * value_to_add);
    end

    // assign final value of partial product register to output
    P <= partial_product;
  end
end

endmodule

