module HMAC (
  input [l-1:0] msg,
  input [k-1:0] key,
  input ctrl,
  output [h-1:0] auth,
  output ctrl
);

parameter l = 64; // length of message
parameter k = 128; // length of key
parameter h = 256; // length of authentication code

reg [l-1:0] padded_msg;
reg [h-1:0] hash1;
reg [h-1:0] hash2;
reg [h-1:0] hmac;

// Padding function
function [l-1:0] pad;
  input [l-1:0] msg;
  integer pad_len;
  begin
    pad_len = (l/512 + 1) * 512 - l - 128;
    pad = {msg, 1'b1, {pad_len{1'b0}}, {128{1'b0}}};
  end
endfunction

// Hashing function
function [h-1:0] hash;
  input [l-1:0] msg;
  input [h-1:0] key;
  reg [h-1:0] hash_out;
  begin
    // Compute inner hash
    hash_out = {msg, key} ^ 32'h5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c;
    hash_out = $hash(hash_out);

    // Compute outer hash
    hash_out = {key, hash_out} ^ 32'h3636363636363636363636363636363636363636363636363636363636363636;
    hash_out = $hash(hash_out);

    hash = hash_out;
  end
endfunction

// Comparison function
function [1:0] compare;
  input [h-1:0] hmac1;
  input [h-1:0] hmac2;
  begin
    if (hmac1 == hmac2) begin
      compare = 2'b10; // Authentic
    end else begin
      compare = 2'b00; // Not authentic
    end
  end
endfunction

// Generate HMAC
always @ (posedge ctrl) begin
  if (ctrl == 0) begin
    padded_msg = pad(msg);
    hash1 = $hash({key, padded_msg});
    hash2 = hash({key, hash1});
    hmac = hash2;
  end
end

// Check HMAC
always @ (posedge ctrl) begin
  if (ctrl == 1) begin
    padded_msg = pad(msg);
    hash1 = $hash({key, padded_msg});
    hash2 = hash({key, hash1});
    auth = hash2;
    ctrl = compare(hmac, auth);
  end
end

endmodule

module barrel_shifter (
    input [3:0] data,
    input [2:0] shift,
    output [3:0] out
);

    reg [3:0] shift_reg;

    always @(*) begin
        if (shift > 3) begin
            shift_reg[0] = data[3];
            shift_reg[1] = data[0];
            shift_reg[2] = data[1];
            shift_reg[3] = data[2];
        end else begin
            shift_reg = data << shift;
        end
    end

    assign out = shift_reg;

endmodule

