module fifo_buffer (
  input clk,
  input reset,
  input [7:0] data_in,
  input add_got,
  input add_exp,
  output reg [1:0] status,
  output reg [7:0] data_out,
  input check
);

  parameter DATASIZE = 8;
  parameter BUFFSIZE = 1024;
  parameter ADDRSIZE = 10;

  reg [DATASIZE : 0] buffer [BUFFSIZE - 1 : 0];
  reg [ADDRSIZE - 1 : 0] rd_ptr;
  reg [ADDRSIZE - 1 : 0] wr_ptr;
  reg [ADDRSIZE - 1 : 0] exp_ptr;
  reg [ADDRSIZE - 1 : 0] exp_rd_ptr;
  reg [1:0] buffer_status;
  reg [1:0] add_got_status;
  reg [1:0] add_exp_status;
  reg [1:0] check_status;

  integer i;

  always @(posedge clk) begin
    if (reset) begin
      wr_ptr <= 0;
      rd_ptr <= 0;
      exp_ptr <= 0;
      exp_rd_ptr <= 0;
      buffer_status <= 2'b00;
      add_got_status <= 2'b00;
      add_exp_status <= 2'b00;
      check_status <= 2'b00;
      for (i = 0; i < BUFFSIZE; i = i + 1) begin
        buffer[i] <= 0;
      end
    end
    else begin
      if (add_got) begin
        case (buffer_status)
          2'b00: begin
            buffer[wr_ptr] <= data_in;
            wr_ptr <= wr_ptr + 1;
            if (wr_ptr == BUFFSIZE) begin
              wr_ptr <= 0;
            end
            if (wr_ptr == rd_ptr) begin
              buffer_status <= 2'b11;
            end
            else if (wr_ptr == (rd_ptr + 1014) % BUFFSIZE) begin
              buffer_status <= 2'b10;
            end
            else if (wr_ptr == (rd_ptr + 1023) % BUFFSIZE) begin
              buffer_status <= 2'b01;
            end
            else begin
              buffer_status <= 2'b00;
            end
            add_got_status <= 2'b00;
          end
          default: begin
            add_got_status <= buffer_status;
          end
        endcase
      end
      if (add_exp) begin
        case (buffer_status)
          2'b00: begin
            buffer[exp_ptr] <= data_in;
            exp_ptr <= exp_ptr + 1;
            if (exp_ptr == BUFFSIZE) begin
              exp_ptr <= 0;
            end
            if (exp_ptr == exp_rd_ptr) begin
              buffer_status <= 2'b11;
            end
            else if (exp_ptr == (exp_rd_ptr + 1014) % BUFFSIZE) begin
              buffer_status <= 2'b10;
            end
            else if (exp_ptr == (exp_rd_ptr + 1023) % BUFFSIZE) begin
              buffer_status <= 2'b01;
            end
            else begin
              buffer_status <= 2'b00;
            end
            add_exp_status <= 2'b00;
          end
          default: begin
            add_exp_status <= buffer_status;
          end
        endcase
      end
      if (check) begin
        case (buffer_status)
          2'b00: begin
            if (exp_rd_ptr == exp_ptr) begin
              check_status <= 2'b00;
            end
            else begin
              data_out <= buffer[exp_rd_ptr];
              exp_rd_ptr <= exp_rd_ptr + 1;
              if (exp_rd_ptr == BUFFSIZE) begin
                exp_rd_ptr <= 0;
              end
              check_status <= 2'b00;
            end
          end
          default: begin
            check_status <= buffer_status;
          end
        endcase
      end
    end
  end

  always @(posedge clk) begin
    if (reset) begin
      status <= 2'b00;
    end
    else begin
      case (check_status)
        2'b00: begin
          status <= buffer_status;
        end
        default: begin
          status <= check_status;
        end
      endcase
    end
  end

endmodule

