   pll_adv #(
      .CLKIN_PERIOD(10.0),
      .CLKFBOUT_MULT(8),
      .CLKFBOUT_PHASE(0.0),
      .CLKOUT0_DIVIDE(8),
      .CLKOUT1_DIVIDE(16),
