      .CLKOUT3()
   );

   wire cpuclk_selected, cpuclk_3_2, cpuclk_1_0;

   BUFGMUX speed_3_and_2 (  // 28MHz and 14MHz for CPU
     .O(cpuclk_3_2),
     .I0(CLK_OUT2),
     .I1(CLK_OUT1),
     .S(turbo_enable[0])
   );

   reg [2:0] clkdivider = 3'b000;
   always @(posedge CLK_OUT1)
     clkdivider <= clkdivider + 3'd1;

   BUFG bclkout2 (
    .O(CLK_OUT2),
    .I(clkdivider[0])
   );

   BUFG bclkout3 (
    .O(CLK_OUT3),
    .I(clkdivider[1])
   );

   BUFG bclkout4 (
    .O(CLK_OUT4),
    .I(clkdivider[2])
