parameter m = 2; // number of output signals
parameter d = 4; // depth of pipeline register

reg [n-1:0] shift_reg [0:d-1]; // shift register implemented using flip-flops

integer i;

always @ (posedge clk) begin
  // shift input signals into shift register
  for (i = d-1; i > 0; i = i - 1) begin
    shift_reg[i] <= shift_reg[i-1];
  end
  shift_reg[0] <= in;
end

// output signals are the values stored in the flip-flops
assign out = shift_reg[d-1];

endmodule

module alu(
  input [2:0] op,
  input [7:0] a,
  input [7:0] b,
  input [4:0] reg_addr,
  input reg_write,
  output [7:0] result
);

  reg [7:0] out;
  reg [7:0] neg_b;
  reg [7:0] and_out;
  reg [7:0] or_out;
  reg [7:0] xor_out;

  always @(*) begin
    case(op)
      3'b000: out = a + b;
      3'b001: out = a - b;
      3'b010: and_out = a & b;
      3'b011: or_out = a | b;
      3'b100: xor_out = a ^ b;
      default: out = 8'h00;
    endcase
  end

  always @(*) begin
    if (op == 3'b001) begin
      neg_b = ~b + 1;
      out = a + neg_b;
    end
  end

  always @(*) begin
    if (op == 3'b010) begin
      out = and_out;
    end
  end

  always @(*) begin
    if (op == 3'b011) begin
      out = or_out;
    end
  end

  always @(*) begin
    if (op == 3'b100) begin
      out = xor_out;
    end
  end

  always @(posedge reg_write) begin
    if (reg_write) begin
      case(reg_addr)
        5'b00000: result <= out;
        5'b00001: result <= out;
        5'b00010: result <= out;
        5'b00011: result <= out;
        5'b00100: result <= out;
        5'b00101: result <= out;
        5'b00110: result <= out;
        5'b00111: result <= out;
        5'b01000: result <= out;
        5'b01001: result <= out;
        5'b01010: result <= out;
        5'b01011: result <= out;
        5'b01100: result <= out;
        5'b01101: result <= out;
        5'b01110: result <= out;
        5'b01111: result <= out;
        5'b10000: result <= out;
        5'b10001: result <= out;
        5'b10010: result <= out;
        5'b10011: result <= out;
        default: result <= 8'h00;
      endcase
    end
  end

endmodule

