module uart_tx_buffer(
    input clk, rst, dataReady,
    input [7:0] data,
    output reg txStart,
    output reg [7:0] txData,
    output reg empty,
    output reg full,
    output reg txBusy
);

    reg [7:0] buffer [0:7];
    reg [2:0] head, tail;
    reg [2:0] count;
    reg [7:0] currentByte;

    always @(posedge clk) begin
        if (rst) begin
            head <= 0;
            tail <= 0;
            count <= 0;
            empty <= 1;
            full <= 0;
            txBusy <= 0;
            txStart <= 0;
            txData <= 0;
        end
        else begin
            if (dataReady && !full) begin
                buffer[head] <= data;
                head <= (head == 7) ? 0 : head + 1;
                count <= count + 1;
                empty <= 0;
                if (count == 8) full <= 1;
            end

            if (!txBusy && !empty) begin
                currentByte <= buffer[tail];
                tail <= (tail == 7) ? 0 : tail + 1;
                count <= count - 1;
                full <= 0;
                if (count == 0) empty <= 1;
                txBusy <= 1;
                txStart <= 1;
                txData <= currentByte;
            end
            else if (txBusy) begin
                txStart <= 0;
                txData <= 0;
                txBusy <= 0;
            end
        end
    end

endmodule

module Johnson_counter (
  input                clk,
  input                rst_n,
  input                select,
  output reg  [63:0]   Q
);

  reg [63:0] shift_reg;
  reg [3:0]  counter;

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      shift_reg <= 64'b0;
      counter <= 4'b0;
      Q <= 64'b0;
    end
    else begin
      if (select) begin
        // Johnson counter
        case (counter)
          4'b0000: shift_reg <= 64'b0001;
          4'b0001: shift_reg <= 64'b0011;
          4'b0011: shift_reg <= 64'b0111;
          4'b0111: shift_reg <= 64'b1111;
          4'b1111: shift_reg <= 64'b1110;
          4'b1110: shift_reg <= 64'b1100;
          4'b1100: shift_reg <= 64'b1000;
          4'b1000: shift_reg <= 64'b0000;
        endcase
        counter <= counter + 1;
      end
      else begin
        // Shift register
        shift_reg <= {shift_reg[62:0], shift_reg[63]};
      end
      Q <= select ? shift_reg : {64{1'b0}};
    end
  end

endmodule

