    input [$clog2(RMAX+1)-1:0] rate
);

reg [WIDTH-1:0] comb_out;
reg [WIDTH-1:0] integrator_out;
reg [N-1:0] comb_reg [$clog2(RMAX*M)**N-1:0];
reg [N-1:0] integrator_reg [$clog2(RMAX*M)**N-1:0];
reg [$clog2(RMAX*M)**N-1:0] output_reg;
reg [$clog2(RMAX*M)**N-1:0] output_reg_temp;
reg [$clog2(RMAX*M)**N-1:0] output_reg_temp2;
reg [$clog2(RMAX+1)-1:0] rate_reg;

integer i, j, k;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        comb_out <= 'd0;
        integrator_out <= 'd0;
        for (i=0; i<$clog2(RMAX*M)**N; i=i+1) begin
            comb_reg[i] <= 'd0;
            integrator_reg[i] <= 'd0;
        end
        output_reg <= 'd0;
        output_reg_temp <= 'd0;
        output_reg_temp2 <= 'd0;
        rate_reg <= 'd0;
        output_tvalid <= 0;
        output_tdata <= 'd0;
    end else begin
        if (input_tvalid && input_tready) begin
            comb_out <= input_tdata;
            for (i=0; i<N; i=i+1) begin
                for (j=0; j<RMAX*M; j=j+1) begin
                    k = i*(RMAX*M) + j;
                    if (j == 0) begin
                        integrator_out = comb_out + integrator_reg[k];
                    end else begin
                        integrator_out = integrator_reg[k-1] + integrator_reg[k] + comb_out;
                    end
                    integrator_reg[k] <= integrator_out;
                end
            end
            for (i=0; i<$clog2(RMAX*M)**N; i=i+1) begin
                if (i == 0) begin
                    comb_reg[i] <= integrator_out - output_reg_temp;
                end else begin
                    comb_reg[i] <= integrator_reg[i-1] - comb_reg[i-1];
                end
            end
            output_reg_temp <= integrator_out;
            output_reg_temp2 <= output_reg;
            for (i=0; i<rate; i=i+1) begin
                output_reg_temp2 <= output_reg_temp2 + comb_reg[i*(RMAX*M)**N/(rate)];
            end
            output_reg <= output_reg_temp2;
            output_tvalid <= 1;
            output_tdata <= output_reg[(REG_WIDTH-1):0];
        end else begin
            output_tvalid <= 0;
        end
    end
end

assign input_tready = !input_tvalid || (input_tvalid && input_tready);

always @(posedge clk or posedge rst) begin
    if (rst) begin
        rate_reg <= 'd0;
    end else begin
        rate_reg <= rate;
    end
end

endmodule

