module PLL_Frequency_Synthesizer (
  input ref_clk,
  input [31:0] out_freq,
  output out_clk
);

parameter N = 10;
parameter M = 5;
parameter K = 1;
parameter A = 1;
parameter B = 1;

reg [31:0] phase_accumulator;
reg [31:0] vco_frequency;
reg [31:0] control_voltage;

wire [31:0] multiplied_ref_clk;
wire [31:0] divided_ref_clk;
wire [31:0] phase_error;
wire [31:0] filtered_error;

assign multiplied_ref_clk = ref_clk * N;
assign divided_ref_clk = multiplied_ref_clk / M;

always @(posedge ref_clk) begin
  phase_accumulator <= phase_accumulator + vco_frequency;
  out_clk <= $signed(phase_accumulator[N-1:0] >= (1 << N-1));
end

always @(posedge ref_clk) begin
  phase_error <= out_freq - (divided_ref_clk * phase_accumulator[M-1:0]);
  filtered_error <= filtered_error + (B * phase_error) - (A * control_voltage);
  control_voltage <= control_voltage + (K * filtered_error);
  vco_frequency <= divided_ref_clk + control_voltage;
end

endmodule
module DDS_Frequency_Synthesizer (
  input ref_clk,
  input [31:0] out_freq,
  output out_clk
);

parameter N = 16;
parameter M = 12;
parameter F = 100000000;

reg [31:0] phase_accumulator;
reg [31:0] frequency_tuning_word;

wire [31:0] dac_output;

assign dac_output = $signed((1 << 16) * sin((2 * $pi * phase_accumulator) / (1 << 16)));

always @(posedge ref_clk) begin
  frequency_tuning_word <= (out_freq * (1 << M)) / F;
  phase_accumulator <= phase_accumulator + frequency_tuning_word;
  out_clk <= dac_output;
end

endmodule

