    assign A_comp = (~A) + 1;
    assign B_comp = (~B) + 1;

    assign sum = A_comp + B_comp + C;

    assign carry = sum[4];

    assign Z = (C) ? (~sum[3:0] + 1) : sum[3:0];

endmodule

