wire [3:0] ripple_carry_adder_output;
wire carry_out;

shift_register shift_reg (
    .clk(clk),
    .reset(reset),
    .d({a, 4'b0}),
    .q(shift_register_output)
);

ripple_carry_adder ripple_adder (
    .a(shift_register_output[3:0]),
    .b(b),
    .sum(ripple_carry_adder_output),
    .carry_out(carry_out)
);

