module ripple_carry_adder(
    input [3:0] a,
    input [3:0] b,
    output [3:0] sum,
    output carry_out
);

assign sum[0] = a[0] ^ b[0];
assign sum[1] = a[1] ^ b[1] ^ sum[0];
assign sum[2] = a[2] ^ b[2] ^ sum[1];
assign sum[3] = a[3] ^ b[3] ^ sum[2];
assign carry_out = (a[3] & b[3]) | (a[2] & b[2]) | (a[1] & b[1] & ~sum[0]) | (a[0] & b[0] & ~(sum[1] | sum[2] | sum[3]));

endmodule

