module top_module (
    input clk,
    input rst_n,
    input [3:0] in,
    output reg [1:0] pos,
    input write_en,
    input [7:0] write_addr,
    input [3:0] write_data,
    input read_en,
    input [7:0] read_addr,
    output reg [3:0] read_data,
    output reg [5:0] final_output
);

// Binary to Gray code converter
wire [1:0] gray_code;
assign gray_code = (pos >> 1) ^ pos;

// 4-bit priority encoder
reg [1:0] priority_encoder;
always @(in) begin
    if (in[3]) priority_encoder = 2'b11;
    else if (in[2]) priority_encoder = 2'b10;
    else if (in[1]) priority_encoder = 2'b01;
    else if (in[0]) priority_encoder = 2'b00;
    else priority_encoder = 2'b00;
end

// True dual-port RAM
reg [3:0] ram [0:7];
integer i;
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        for (i = 0; i < 8; i = i + 1) begin
            ram[i] <= 4'b0000;
        end
    end else begin
        if (write_en) begin
            ram[write_addr] <= write_data;
        end
        if (read_en) begin
            read_data <= ram[read_addr];
        end
    end
end

// Additional functional module
always @(posedge clk) begin
    pos <= priority_encoder;
    final_output <= {gray_code, read_data};
end

endmodule

module AdlerChecksum (
  input clk,
  input rst,
  input [7:0] data_in,
  input valid_in,
  output valid_out,
  output reg [15:0] checksum
);

  // parameter declaration
  parameter N = 65521; // largest prime number less than 2^16

  // internal registers
  reg [15:0] s1 = 1;
  reg [15:0] s2 = 0;

  // state machine
  reg [1:0] state = 0;
  parameter IDLE = 2'b00;
  parameter PROCESS = 2'b01;
  parameter OUTPUT = 2'b10;

  // combinational logic
  assign valid_out = (state == OUTPUT);

  // sequential logic
  always @(posedge clk) begin
    if (rst) begin
      s1 <= 1;
      s2 <= 0;
      state <= IDLE;
    end else begin
      case (state)
        IDLE: begin
          if (valid_in) begin
            s1 <= data_in;
            s2 <= data_in;
            state <= PROCESS;
          end
        end
        PROCESS: begin
          if (valid_in) begin
            s1 <= (s1 + data_in) % N;
            s2 <= (s2 + s1) % N;
          end else begin
            state <= OUTPUT;
          end
        end
        OUTPUT: begin
          checksum <= (s2 << 16) | s1;
          state <= IDLE;
        end
      endcase
    end
  end

endmodule

module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] instruction,
    input [4:0] rs1,
    input [4:0] rs2,
    input [4:0] rd,
    input [31:0] data1,
    input [31:0] data2,
    output [11:0] result
);

    // Counter module from Problem 1
    reg [3:0] counter;
    always @(posedge clk, posedge reset) begin
        if (reset) begin
            counter <= 0;
        end else if (counter == 15) begin
            counter <= 0;
        end else begin
            counter <= counter + 1;
        end
    end

    // Pipeline modules from Problem 2
    reg [7:0] instruction_reg;
    reg [7:0] opcode;
    reg [4:0] rs1_reg;
    reg [4:0] rs2_reg;
    reg [4:0] rd_reg;
    reg [31:0] data1_reg;
    reg [31:0] data2_reg;
    reg [31:0] alu_result;
    reg [7:0] shamt;
    reg [31:0] reg_file [0:7];
    reg [1:0] stage;

    always @(posedge clk, posedge reset) begin
        if (reset) begin
            instruction_reg <= 0;
            opcode <= 0;
            rs1_reg <= 0;
            rs2_reg <= 0;
            rd_reg <= 0;
            data1_reg <= 0;
            data2_reg <= 0;
            alu_result <= 0;
            shamt <= 0;
            reg_file <= 0;
            stage <= 0;
        end else begin
            case (stage)
                0: begin // Instruction decoding stage
                    instruction_reg <= instruction;
                    opcode <= instruction_reg[7:4];
                    rs1_reg <= instruction_reg[3:0];
                    rs2_reg <= instruction_reg[7:4];
                    rd_reg <= instruction_reg[3:0];
                    stage <= 1;
                end
                1: begin // Instruction execution stage
                    data1_reg <= reg_file[rs1_reg];
                    data2_reg <= reg_file[rs2_reg];
                    shamt <= data2_reg[4:0];
                    case (opcode)
                        2'b00: alu_result <= data1_reg + data2_reg; // ADD
                        2'b01: alu_result <= data1_reg - data2_reg; // SUB
                        2'b10: alu_result <= data1_reg & data2_reg; // AND
                        2'b11: alu_result <= ~(data1_reg & data2_reg); // NAND
                    endcase
                    stage <= 2;
                end
                2: begin // Write back stage
                    reg_file[rd_reg] <= alu_result;
                    stage <= 0;
                end
            endcase
        end
    end

    // Additional functional module
    reg [11:0] final_result;
    always @(posedge clk, posedge reset) begin
        if (reset) begin
            final_result <= 0;
        end else begin
            final_result <= {counter, alu_result};
        end
    end

    assign result = final_result;

endmodule

