module lcd_controller (
    input               rst,
    input               clk,
    input               i_cmd_write_stb,
    input               i_cmd_read_stb,
    input       [7:0]   i_cmd_data,
    input               i_enable,
    input               i_cmd_parameter,
    output      [31:0]  debug,
    output reg [7:0]    o_cmd_data,
    output reg          o_cmd_finished,
    output              o_cmd_mode,
    output reg          o_write,
    output reg          o_read,
    output reg  [7:0]   o_data_out,
    input       [7:0]   i_data_in,
    output reg          o_data_out_en
);

// Local parameters
localparam IDLE = 2'b00;
localparam READ_WAIT = 2'b01;
localparam FINISHED = 2'b10;

// Registers/Wires
reg [1:0] state;
reg [7:0] data_out;

// Submodules
assign o_cmd_mode = i_cmd_parameter;

// Synchronous logic
always @(posedge clk) begin
    if (rst) begin
        state <= IDLE;
        o_data_out_en <= 0;
        o_data_out <= 0;
        o_cmd_finished <= 0;
        o_cmd_data <= 0;
        o_write <= 0;
        o_read <= 0;
    end else begin
        o_cmd_finished <= 0;
        case (state)
            IDLE: begin
                o_write <= 0;
                o_read <= 0;
                o_data_out_en <= 0;
                if (i_cmd_write_stb) begin
                    o_data_out_en <= 1;
                    data_out <= i_cmd_data;
                    o_write <= 1;
                    state <= FINISHED;
                end else if (i_cmd_read_stb) begin
                    o_data_out_en <= 0;
                    o_read <= 1;
                    state <= READ_WAIT;
                end
            end
            READ_WAIT: begin
                state <= FINISHED;
            end
            FINISHED: begin
                o_write <= 0;
                o_read <= 0;
                if (!o_data_out_en) begin
                    o_cmd_data <= i_data_in;
                end
                o_cmd_finished <= 1;
                state <= IDLE;
            end
        endcase
    end
end

endmodule

module bram_switch #
(
  parameter integer BRAM_DATA_WIDTH = 32,
  parameter integer BRAM_ADDR_WIDTH = 15  // 2^11 = 2048 positions
)
(
  // System signals
  input  wire                        switch,


  // BRAM PORT A
  input  wire                        bram_porta_clk,
  input  wire                        bram_porta_rst,
  input  wire [BRAM_ADDR_WIDTH-1:0]  bram_porta_addr,
  input  wire [BRAM_DATA_WIDTH-1:0]  bram_porta_wrdata,
  output wire [BRAM_DATA_WIDTH-1:0]  bram_porta_rddata,
