  input  wire                        bram_portb_rst,
  input  wire [BRAM_ADDR_WIDTH-1:0]  bram_portb_addr,
  input  wire [BRAM_DATA_WIDTH-1:0]  bram_portb_wrdata,
  output wire [BRAM_DATA_WIDTH-1:0]  bram_portb_rddata,
  input  wire                        bram_portb_we,


  // BRAM PORT C
  output wire                        bram_portc_clk,
  output wire                        bram_portc_rst,
  output wire [BRAM_ADDR_WIDTH-1:0]  bram_portc_addr,
  output wire [BRAM_DATA_WIDTH-1:0]  bram_portc_wrdata,
  input  wire [BRAM_DATA_WIDTH-1:0]  bram_portc_rddata,
  output wire                        bram_portc_we

);

  reg bram_portc_clk;
  reg bram_portc_rst;
  reg [BRAM_ADDR_WIDTH-1:0] bram_portc_addr;
  reg [BRAM_DATA_WIDTH-1:0] bram_portc_wrdata;
  wire [BRAM_DATA_WIDTH-1:0] bram_portc_rddata;
  reg bram_portc_we;

  always @ (posedge bram_porta_clk) begin
    if (switch) begin
      bram_portc_clk <= bram_porta_clk;
      bram_portc_rst <= bram_porta_rst;
      bram_portc_addr <= bram_porta_addr;
      bram_portc_wrdata <= bram_porta_wrdata;
      bram_portc_we <= bram_porta_we;
    end
  end

  always @ (posedge bram_portb_clk) begin
    if (!switch) begin
      bram_portc_clk <= bram_portb_clk;
      bram_portc_rst <= bram_portb_rst;
      bram_portc_addr <= bram_portb_addr;
      bram_portc_wrdata <= bram_portb_wrdata;
      bram_portc_we <= bram_portb_we;
    end
  end

  assign bram_porta_rddata = switch ? bram_portc_rddata : {(BRAM_DATA_WIDTH){1'b0}};
  assign bram_portb_rddata = !switch ? bram_portc_rddata : {(BRAM_DATA_WIDTH){1'b0}};

  assign bram_portc_clk = switch ? bram_porta_clk : bram_portb_clk;
  assign bram_portc_rst = switch ? bram_porta_rst : bram_portb_rst;
  assign bram_portc_addr = switch ? bram_porta_addr : bram_portb_addr;
  assign bram_portc_wrdata = switch ? bram_porta_wrdata : bram_portb_wrdata;
  assign bram_portc_we = switch ? bram_porta_we : bram_portb_we;

endmodule

