    abs_sum abs1(.in(selected_input), .out(abs_val1));
    abs_sum abs2(.in(in1), .out(abs_val2));
    abs_sum abs3(.in(in2), .out(abs_val3));
    abs_sum abs4(.in(in3), .out(abs_val4));

