module binary_adder(
    input [3:0] A,
    input [3:0] B,
    input C_in,
    output [3:0] S,
    output C_out
);

wire [3:0] sum;
wire [3:0] carry_out;

full_adder fa0(A[0], B[0], C_in, sum[0], carry_out[0]);
full_adder fa1(A[1], B[1], carry_out[0], sum[1], carry_out[1]);
full_adder fa2(A[2], B[2], carry_out[1], sum[2], carry_out[2]);
full_adder fa3(A[3], B[3], carry_out[2], sum[3], C_out);

assign S = sum;

endmodule

module full_adder(
    input A,
    input B,
    input C_in,
    output S,
    output C_out
);

assign S = A ^ B ^ C_in;
assign C_out = (A & B) | (C_in & (A ^ B));

endmodule

module predictor_2_15 ( clock, reset, enable, taken_i, prediction_o );
  input clock, reset, enable, taken_i;
  output prediction_o;
  wire   N11, N12, n5, n6, n8, n9, n11, n10, n12;
  wire   [1:0] next_STATE;

  // D flip-flops to store current state
  DFFR_X1 \STATE_reg[0]  ( .D(n6), .CK(clock), .RN(n12), .Q(n5), .QN(n10) );
  DFFR_X1 \STATE_reg[1]  ( .D(n8), .CK(clock), .RN(n12), .Q(prediction_o) );

  // DL latches to store next state
  DLH_X1 \next_STATE_reg[0]  ( .G(enable), .D(N11), .Q(next_STATE[0]) );
  DLH_X1 \next_STATE_reg[1]  ( .G(enable), .D(N12), .Q(next_STATE[1]) );

  // Multiplexers to select between current and next state
  MUX2_X1 U8 ( .A(prediction_o), .B(next_STATE[1]), .S(enable), .Z(n8) );
  MUX2_X1 U9 ( .A(n5), .B(next_STATE[0]), .S(enable), .Z(n6) );

  // Gates to generate intermediate signals
  NOR2_X1 U7 ( .A1(prediction_o), .A2(taken_i), .ZN(n9) );
  NAND2_X1 U6 ( .A1(prediction_o), .A2(taken_i), .ZN(n11) );

  // OR-AND-INVERT gates to generate next state
  OAI21_X1 U3 ( .B1(n9), .B2(n10), .A(n11), .ZN(N12) );
  OAI21_X1 U5 ( .B1(n5), .B2(n9), .A(n11), .ZN(N11) );

  // Inverter to generate reset signal for flip-flops
  INV_X1 U2 ( .A(reset), .ZN(n12) );
endmodule

module top_module( 
    input [255:0] in, // 256-bit input for the multiplexer 
    input [7:0] sel, // Selection vector for the multiplexer 
    input a, // First input signal for the NOR gate 
    input b, // Second input signal for the NOR gate 
    output [6:0] seg // Output signals that control the seven segments of the display 
);

// Implementing the 256-to-1 multiplexer using a binary tree and a priority encoder
wire [7:0] priority;
wire [7:0] sel_inv;
assign sel_inv = ~sel;
priority_encoder_8to3 encoder(.in(sel_inv), .out(priority));
wire [7:0] mux_out;
wire [7:0] mux_out_inv;
wire [7:0] mux_out_sel;
wire [7:0] mux_out_sel_inv;
wire [7:0] mux_out_sel_inv_and_priority;
wire [7:0] mux_out_sel_inv_and_priority_inv;
wire [7:0] mux_out_sel_inv_and_priority_inv_nand;
wire [7:0] mux_out_sel_inv_and_priority_inv_nor;
assign mux_out = in[mux_out_sel];
assign mux_out_inv = ~mux_out;
assign mux_out_sel = mux_out_sel_inv_and_priority_inv_nor;
assign mux_out_sel_inv_and_priority = mux_out_sel_inv & priority;
assign mux_out_sel_inv_and_priority_inv = ~mux_out_sel_inv_and_priority;
assign mux_out_sel_inv_and_priority_inv_nand = ~(mux_out_sel_inv_and_priority_inv[0] & mux_out_sel_inv_and_priority_inv[1] & mux_out_sel_inv_and_priority_inv[2] & mux_out_sel_inv_and_priority_inv[3] & mux_out_sel_inv_and_priority_inv[4] & mux_out_sel_inv_and_priority_inv[5] & mux_out_sel_inv_and_priority_inv[6] & mux_out_sel_inv_and_priority_inv[7]);
assign mux_out_sel_inv_and_priority_inv_nor = ~(mux_out_sel_inv_and_priority_inv_nand);

// Implementing the NOR gate using only NAND gates
wire [3:0] nand_out;
assign nand_out[0] = ~(a & b);
assign nand_out[1] = ~(a & b);
assign nand_out[2] = ~(a & b);
assign nand_out[3] = ~(a & b);
assign seg = ~(nand_out[0] & nand_out[1] & nand_out[2] & nand_out[3]);

endmodule

module priority_encoder_8to3(
    input [7:0] in, // Input signals to be encoded
    output [2:0] out // Encoded output signals
);
wire [7:0] in_inv;
assign in_inv = ~in;
wire [7:0] in_inv_and;
wire [7:0] in_inv_and_inv;
wire [7:0] in_inv_and_inv_or;
assign in_inv_and = in_inv & in;
assign in_inv_and_inv = ~in_inv_and;
assign in_inv_and_inv_or = in_inv_and_inv[0] | in_inv_and_inv[1] | in_inv_and_inv[2] | in_inv_and_inv[3] | in_inv_and_inv[4] | in_inv_and_inv[5] | in_inv_and_inv[6] | in_inv_and_inv[7];
assign out[0] = in_inv_and_inv_or[0];
assign out[1] = in_inv_and_inv_or[1];
assign out[2] = in_inv_and_inv_or[2];

endmodule

