module prometheus_fx3_partial(
    input  rst_n,
    input  clk_100,
    input  partial_mode_selected,
    input  i_gpif_in_ch0_rdy_d,
    input  i_gpif_out_ch0_rdy_d,
    output o_gpif_we_n_partial_,
    output o_gpif_pkt_end_n_partial_,
    output [31:0] data_out_partial
);

reg [2:0] current_partial_state;
reg [2:0] next_partial_state;

//parameters for PARTIAL mode state machine
parameter [2:0] partial_idle                      = 3'd0;
parameter [2:0] partial_wait_flagb                = 3'd1;
parameter [2:0] partial_write                     = 3'd2;
parameter [2:0] partial_write_wr_delay            = 3'd3;
parameter [2:0] partial_wait                      = 3'd4;

reg [3:0] strob_cnt;
reg strob; 
reg [3:0] short_pkt_cnt;
reg [31:0] data_gen_partial;
reg o_gpif_pkt_end_n_prtl_;

assign o_gpif_we_n_partial_ = ((current_partial_state == partial_write) && (i_gpif_out_ch0_rdy_d == 1'b1)) ? 1'b0 : 1'b1;

//counters for short pkt
always @(posedge clk_100, negedge rst_n) begin
    if (!rst_n) begin 
        short_pkt_cnt <= 4'd0;
    end else if (current_partial_state == partial_idle) begin
        short_pkt_cnt <= 4'd0;
    end else if ((current_partial_state == partial_write)) begin
        short_pkt_cnt <= short_pkt_cnt + 1'b1;
    end	
end

//counter to generate the strob for PARTIAL
always @(posedge clk_100, negedge rst_n) begin
    if (!rst_n) begin 
        strob_cnt <= 4'd0;
    end else if (current_partial_state == partial_idle) begin
        strob_cnt <= 4'd0;
    end else if (current_partial_state == partial_wait) begin
        strob_cnt <= strob_cnt + 1'b1;
    end	
end

//Strob logic
always @(posedge clk_100, negedge rst_n) begin
    if (!rst_n) begin
        strob <= 1'b0;
    end else if ((current_partial_state == partial_wait) && (strob_cnt == 4'b0111)) begin
        strob <= !strob;
    end
end

always @(*) begin
    if ((partial_mode_selected) & (strob == 1'b1) & (short_pkt_cnt == 4'b1111)) begin
        o_gpif_pkt_end_n_prtl_ = 1'b0;
    end else begin
        o_gpif_pkt_end_n_prtl_ = 1'b1;
    end
end	

assign o_gpif_pkt_end_n_partial_ = o_gpif_pkt_end_n_prtl_;

//PARTIAL mode state machine
always @(posedge clk_100, negedge rst_n) begin
    if (!rst_n) begin 
        current_partial_state <= partial_idle;
    end else begin
        current_partial_state <= next_partial_state;
    end	
end

//PARTIAL mode state machine combo
always @(*) begin
    next_partial_state = current_partial_state;
    case(current_partial_state)
        partial_idle: begin
            if ((partial_mode_selected) & (i_gpif_in_ch0_rdy_d == 1'b1)) begin
                next_partial_state = partial_wait_flagb; 
            end else begin
                next_partial_state = partial_idle;
            end	
        end
        partial_wait_flagb: begin
            if (i_gpif_out_ch0_rdy_d == 1'b1) begin
                next_partial_state = partial_write; 
            end else begin
                next_partial_state = partial_wait_flagb; 
            end
        end
        partial_write: begin
            if ((i_gpif_out_ch0_rdy_d == 1'b0) | ((strob == 1'b1) & (short_pkt_cnt == 4'b1111))) begin
                next_partial_state = partial_write_wr_delay;
            end else begin
                next_partial_state = partial_write;
            end
        end
        partial_write_wr_delay: begin
            next_partial_state = partial_wait;
        end
        partial_wait: begin
            if (strob_cnt == 4'b0111) begin
                next_partial_state = partial_idle;
            end else begin
                next_partial_state = partial_wait;
            end
        end	
    endcase
end

//data generator counter for Partial mode
always @(posedge clk_100, negedge rst_n) begin
    if (!rst_n) begin 
        data_gen_partial <= 32'd0;
    end else if ((o_gpif_we_n_partial_ == 1'b0) & (partial_mode_selected)) begin
        data_gen_partial <= data_gen_partial + 1;
    end else if (!partial_mode_selected) begin
        data_gen_partial <= 32'd0;
    end	
end

assign data_out_partial = data_gen_partial;

endmodule

module top_module (
    input [31:0] a, // First 32-bit input
    input [31:0] b, // Second 32-bit input
    output [63:0] prod, // 64-bit product
    output reg [3:0] count // 4-bit counter
);

    // Internal wires and registers
    wire [15:0] pp [15:0]; // 16-bit partial products
    wire [31:0] pp_sum [3:0]; // 32-bit partial product sums
    wire [63:0] prod_sum [3:0]; // 64-bit product sums
    reg [3:0] counter_reg; // Counter register
    wire [3:0] counter_next; // Next counter value
    wire [3:0] counter_reset; // Counter reset value

    // Generate partial products
    assign pp[0] = a[15:0] * b[15:0];
    assign pp[1] = a[15:0] * b[31:16];
    assign pp[2] = a[31:16] * b[15:0];
    assign pp[3] = a[31:16] * b[31:16];
    assign pp_sum[0] = pp[0];
    assign pp_sum[1] = pp[1] + pp[2];
    assign pp_sum[2] = pp[3] + pp_sum[1][31:16];
    assign pp_sum[3] = {pp_sum[2][15:0], pp_sum[2][31:16]};

    // Generate product using 16x16 bit adders
    genvar i, j;
    generate
        for (i = 0; i < 4; i = i + 1) begin
            for (j = 0; j < 4; j = j + 1) begin
                if (i + j == 3) begin
                    assign prod_sum[i+j] = prod_sum[i+j] + pp_sum[i];
                end
            end
        end
    endgenerate

    // Output product
    assign prod = {prod_sum[3], prod_sum[2], prod_sum[1], prod_sum[0]};

    // Generate counter using synchronous resettable up-counter
    always @(posedge clk or negedge rst) begin
        if (~rst) begin
            counter_reg <= 0;
        end else begin
            counter_reg <= counter_next;
        end
    end

    // Increment counter every time multiplication is performed
    always @(*) begin
        counter_next = counter_reg + 1;
    end

    // Reset counter when multiplication is performed
    assign counter_reset = (counter_reg == 15);
    always @(posedge clk or negedge rst) begin
        if (~rst) begin
            count <= 0;
        end else if (counter_reset) begin
            count <= 0;
        end else begin
            count <= counter_reg + 1;
        end
    end

endmodule

module Johnson_counter(
  input                clk,
  input                rst_n,
  output reg  [15:0]   Q
);

  reg [3:0]            count;
  reg                  ce;

  // Dual-port RAM to store the state of the counter
  reg [15:0]           ram [11:0];

  // Initialize RAM with cyclic state of 8-bit Johnson counter
  initial begin
    ram[0]  = 16'b0000000000000000;
    ram[1]  = 16'b1000000000000000;
    ram[2]  = 16'b1100000000000000;
    ram[3]  = 16'b1110000000000000;
    ram[4]  = 16'b1111000000000000;
    ram[5]  = 16'b0111100000000000;
    ram[6]  = 16'b0011110000000000;
    ram[7]  = 16'b0001111000000000;
    ram[8]  = 16'b0000111100000000;
    ram[9]  = 16'b0000011110000000;
    ram[10] = 16'b0000001111000000;
    ram[11] = 16'b0000000111100000;
  end

  // Clock enable signal
  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      ce <= 1'b0;
    end else begin
      ce <= 1'b1;
    end
  end

  // Johnson counter logic
  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      count <= 4'b0000;
      Q <= 16'b0000000000000000;
    end else begin
      if (ce) begin
        count <= count + 1;
        Q <= ram[count];
      end
    end
  end

endmodule

module async_fifo (reset_b, rclk, wclk, write, read, wdata, rdata, empty, full);
    parameter WIDTH =  8;
    parameter DEPTH = 32;
    parameter ADDR  =  5;

    input  wire          reset_b;
    input  wire          rclk;
    input  wire          wclk;
    input  wire          write;
    input  wire          read;
    input  wire [WIDTH-1:0] wdata;
    output wire [WIDTH-1:0] rdata;
    output wire             empty;
    output wire             full;

    wire             write_wclk;
    wire             read_rclk;
    wire [WIDTH-1:0] wdata_wclk;
    wire [WIDTH-1:0] rdata_wclk;
    wire [ADDR   :0] raddr_wclk;
    wire [ADDR   :0] waddr_wclk;
    wire [ADDR   :0] raddr_rclk;
    wire [ADDR   :0] waddr_rclk;

    // Clock synchronization for write
    sync #(
        .WIDTH(WIDTH)
    ) i_write_ClockSync [ADDR:0] (
        .OutputClock(rclk),
        .reset_b(reset_b),
        .InputData(waddr_wclk[ADDR:0]),
        .OutputData(waddr_rclk[ADDR:0])
    );

    // Clock synchronization for read
    sync #(
        .WIDTH(WIDTH)
    ) i_read_ClockSync [ADDR:0] (
        .OutputClock(wclk),
        .reset_b(reset_b),
        .InputData(raddr_rclk[ADDR:0]),
        .OutputData(raddr_wclk[ADDR:0])
    );

    // Write pointer
    POINTER #(ADDR) write_pointer_wclk (
        .clk(wclk),
        .reset_b(reset_b),
        .incr(write_wclk),
        .ptr(waddr_wclk)
    );

    // Read pointer
    POINTER #(ADDR) read_pointer_rclk (
        .clk(rclk),
        .reset_b(reset_b),
        .incr(read_rclk),
        .ptr(raddr_rclk)
    );

    // Memory
    memory #(WIDTH, DEPTH, ADDR) i_memory (
        .clk(wclk),
        .reset_b(reset_b),
        .write(write_wclk),
        .waddr(waddr_wclk[ADDR-1:0]),
        .raddr(raddr_wclk[ADDR-1:0]),
        .wdata(wdata_wclk),
        .rdata(rdata_wclk)
    );

    // Compare pointers for empty/full
    COMPARE #(ADDR) comparator_rclk (
        .wptr(waddr_rclk),
        .rptr(raddr_rclk),
        .empty(empty),
        .full()
    );

    COMPARE #(ADDR) comparator_wclk (
        .wptr(waddr_wclk),
        .rptr(raddr_wclk),
        .empty(),
        .full(full)
    );

    // Assignments
    assign wdata_wclk = wdata;
    assign write_wclk = write;
    assign read_rclk = read;
    assign rdata = rdata_wclk;

endmodule

