module packet_transmit (
    input clk,
    input rst_n,
    input exe2disp_data_wr,
    input [7:0] exe2disp_data,
    input exe2disp_valid_wr,
    input exe2disp_valid,
    input exe2disp_direction_req,
    input exe2disp_direction,
    input um2npe_data_wr,
    input [7:0] um2npe_data,
    input um2npe_valid_wr,
    input um2npe_valid,
    input disp2usermux_data_wr,
    input [7:0] disp2usermux_data,
    input disp2usermux_valid_wr,
    input disp2usermux_valid,
    output [7:0] exe2disp_data,
    output exe2disp_valid,
    output disp2exe_alf,
    output [7:0] um2npe_data,
    output um2npe_valid,
    output um2npe_alf,
    output [7:0] disp2usermux_data,
    output disp2usermux_valid,
    output usermux2disp_alf
);

reg [7:0] pkt_buffer;
reg pkt_valid;
reg pkt_direction;

always @(posedge clk) begin
    if (!rst_n) begin
        pkt_buffer <= 8'h00;
        pkt_valid <= 1'b0;
        pkt_direction <= 1'b0;
    end else if (exe2disp_data_wr && exe2disp_direction_req) begin
        pkt_buffer <= exe2disp_data;
        pkt_valid <= exe2disp_valid;
        pkt_direction <= exe2disp_direction;
    end else if (um2npe_data_wr) begin
        pkt_buffer <= um2npe_data;
        pkt_valid <= um2npe_valid;
        pkt_direction <= 0;
    end else if (disp2usermux_data_wr) begin
        pkt_buffer <= disp2usermux_data;
        pkt_valid <= disp2usermux_valid;
        pkt_direction <= 1;
    end
end

assign exe2disp_data = pkt_buffer;
assign exe2disp_valid = pkt_valid && (pkt_direction == 0);
assign disp2exe_alf = pkt_valid && (pkt_direction == 0);
assign um2npe_data = pkt_buffer;
assign um2npe_valid = pkt_valid && (pkt_direction == 0);
assign um2npe_alf = pkt_valid && (pkt_direction == 0);
assign disp2usermux_data = pkt_buffer;
assign disp2usermux_valid = pkt_valid && (pkt_direction == 1);
assign usermux2disp_alf = pkt_valid && (pkt_direction == 1);

endmodule

module selector_module(
    input [1:0] SEL,
    input [7:0] A,
    input [7:0] B,
    output [7:0] OUT
);

    wire [7:0] sum, diff, prod, quo;

    assign sum = A + B;
    assign diff = A - B;
    assign prod = A * B;
    assign quo = A / B;

    always @(*) begin
        case (SEL)
            2'b00: OUT = sum;
            2'b01: OUT = diff;
            2'b10: OUT = prod;
            2'b11: OUT = quo;
        endcase
    end

endmodule

module reverse_bits (
  input [7:0] input_vector,
  output reg [7:0] output_vector
);

  reg [7:0] temp_vector;
  integer i;

  always @(*) begin
    if (input_vector == 8'b00000000) begin
      output_vector = 8'b00000000;
    end else begin
      for (i = 0; i < 8; i = i + 1) begin
        temp_vector[i] = input_vector[7 - i];
      end
      output_vector = temp_vector;
    end
  end

endmodule

