        count <= 0;
        full <= 0;
    end else if (wput && !full) begin
        buffer[waddr] <= din;
        waddr <= (waddr == DEPTH-1) ? 0 : waddr + 1;
        count <= count + 1;
        full <= (count == DEPTH);
    end
end

always @(posedge rclk or posedge rrst) begin
    if (rrst) begin
        raddr <= 0;
        count <= 0;
        empty <= 1;
    end else if (rget && !empty) begin
        dout <= buffer[raddr];
        raddr <= (raddr == DEPTH-1) ? 0 : raddr + 1;
        count <= count - 1;
        empty <= (count == 0);
    end
end

endmodule

