module egg_timer(
  input reset, sysclk, selection,
  output reg [6:0] egg_timer
);

  reg [31:0] timer_var;
  reg [31:0] a, i, j, k;
  reg [31:0] zz5;
  reg [511:0] zz;

  always @(posedge sysclk) begin
    if(reset == 1'b1) begin
      egg_timer <= 7'b0;
      timer_var <= 32'b0;
      a <= 32'b0;
      i <= 32'b0;
      j <= 32'b0;
      k <= 32'b0;
      zz5 <= 32'b0;
      zz <= 512'b0;
    end else begin
      if(selection == 1'b1) begin
        egg_timer <= 7'b1111111;
      end else begin
        if(egg_timer != 7'b0) begin
          egg_timer <= egg_timer - 1;
        end
        else begin
          a <= a + i;
          k <= a - 9;
          for (i=0; i <= j * k; i = i + 1) begin
            for (k=a - 9; k >=  -14; k = k - 1) begin
              zz5 = zz[31 + k:k];
            end
          end
        end
      end
    end
  end
endmodule

module adder_4bit (
    A,
    B,
    CI,
    SUM,
    COUT
);

    input [3:0] A;
    input [3:0] B;
    input CI;
    output [3:0] SUM;
    output COUT;

    wire [3:0] xor_out;
    wire [3:0] or_out;
    wire [3:0] and_out;
    wire [4:0] carry;

    sky130_fd_sc_hd__xor2 xor0 (xor_out[0], A[0], B[0]);
    sky130_fd_sc_hd__xor2 xor1 (xor_out[1], A[1], B[1]);
    sky130_fd_sc_hd__xor2 xor2 (xor_out[2], A[2], B[2]);
    sky130_fd_sc_hd__xor2 xor3 (xor_out[3], A[3], B[3]);

    sky130_fd_sc_hd__or2 or0 (or_out[0], A[0], B[0]);
    sky130_fd_sc_hd__or2 or1 (or_out[1], A[1], B[1]);
    sky130_fd_sc_hd__or2 or2 (or_out[2], A[2], B[2]);
    sky130_fd_sc_hd__or2 or3 (or_out[3], A[3], B[3]);

    assign and_out[0] = A[0] & B[0];
    assign and_out[1] = A[1] & B[1];
    assign and_out[2] = A[2] & B[2];
    assign and_out[3] = A[3] & B[3];

    assign carry[0] = CI;
    assign carry[1] = (and_out[0] | (xor_out[0] & CI));
    assign carry[2] = (and_out[1] | (xor_out[1] & carry[1]));
    assign carry[3] = (and_out[2] | (xor_out[2] & carry[2]));
    assign carry[4] = (and_out[3] | (xor_out[3] & carry[3]));

    assign SUM[0] = xor_out[0];
    assign SUM[1] = xor_out[1] ^ carry[1];
    assign SUM[2] = xor_out[2] ^ carry[2];
    assign SUM[3] = xor_out[3] ^ carry[3];

    assign COUT = carry[4];

endmodule

