module PLL (
    input areset,
    input inclk0,
    output reg c0,
    output reg locked
);

reg [31:0] counter;
reg [31:0] phase_accumulator;
reg [31:0] phase_increment;
reg [31:0] frequency_ratio;
reg [31:0] reference_period;
reg [31:0] output_period;

// Calculate frequency ratio
always @ (posedge inclk0 or posedge areset) begin
    if (areset) begin
        frequency_ratio <= 0;
    end else begin
        frequency_ratio <= (reference_period << 16) / output_period;
    end
end

// Calculate phase increment
always @ (posedge inclk0 or posedge areset) begin
    if (areset) begin
        phase_increment <= 0;
    end else begin
        phase_increment <= frequency_ratio;
    end
end

// Calculate output period
always @ (posedge inclk0 or posedge areset) begin
    if (areset) begin
        output_period <= 0;
    end else begin
        output_period <= reference_period * frequency_ratio >> 16;
    end
end

// Update phase accumulator
always @ (posedge c0 or posedge areset) begin
    if (areset) begin
        phase_accumulator <= 0;
    end else begin
        phase_accumulator <= phase_accumulator + phase_increment;
    end
end

// Generate output clock signal
always @ (posedge c0 or posedge areset) begin
    if (areset) begin
        c0 <= 0;
    end else begin
        if (phase_accumulator >= (1 << 31)) begin
            c0 <= ~c0;
            phase_accumulator <= phase_accumulator - (1 << 31);
        end
    end
end

// Update locked output
always @ (posedge c0 or posedge areset) begin
    if (areset) begin
        locked <= 0;
    end else begin
        locked <= (phase_accumulator == 0);
    end
end

// Update reference period
always @ (posedge inclk0 or posedge areset) begin
    if (areset) begin
        reference_period <= 0;
    end else begin
        reference_period <= counter;
        counter <= 0;
    end
end

// Increment counter
always @ (posedge inclk0 or posedge areset) begin
    if (areset) begin
        counter <= 0;
    end else begin
        counter <= counter + 1;
    end
end

endmodule

module top_module (
  input clk,
  input reset,      // Asynchronous active-high reset
  input [1:0] ena,  // Control input to choose between rotator and counter
  input [99:0] data, // 100-bit input for the rotator
  input select,     // Select input to choose between rotator and counter
  output reg match  // Output signal to indicate a match
);

  // Instantiate the left/right rotator module
  left_right_rotator rotator (
    .clk(clk),
    .reset(reset),
    .load(ena[1]),  // Load input is high when ena[1] is high
    .dir(ena[0]),   // Direction is controlled by ena[0]
    .data_in(data),
    .data_out(rotated_data)
  );

  // Instantiate the 3-bit binary counter module
  binary_counter counter (
    .clk(clk),
    .reset(reset),
    .count_en(ena[0]),  // Counter is enabled when ena[0] is high
    .count_dir(ena[1]), // Count direction is controlled by ena[1]
    .count_out(counter_out)
  );

  // Instantiate the pattern matching module
  pattern_matcher matcher (
    .data_in(rotated_data),
    .count_in(counter_out),
    .select(select),
    .match_out(match)
  );

  // Internal signal to hold the rotated data
  reg [99:0] rotated_data;

  // Internal signal to hold the counter output
  reg [2:0] counter_out;

endmodule

// Left/right rotator module
module left_right_rotator (
  input clk,
  input reset,      // Asynchronous active-high reset
  input load,       // Load input to load data into shift register
  input dir,        // Direction input to control shift direction
  input [99:0] data_in,  // 100-bit input data
  output [99:0] data_out // 100-bit output data
);

  reg [99:0] shift_reg;  // Shift register to hold the data

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      shift_reg <= 0;
    end else begin
      if (load) begin
        shift_reg <= data_in;
      end else begin
        if (dir) begin
          shift_reg <= {shift_reg[0], shift_reg[99:1]};
        end else begin
          shift_reg <= {shift_reg[98:0], shift_reg[99]};
        end
      end
    end
  end

  assign data_out = shift_reg;

endmodule

// 3-bit binary counter module
module binary_counter (
  input clk,
  input reset,      // Asynchronous active-high reset
  input count_en,   // Enable input to enable counting
  input count_dir,  // Direction input to control count direction
  output reg [2:0] count_out // 3-bit output count
);

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      count_out <= 0;
    end else begin
      if (count_en) begin
        if (count_dir) begin
          count_out <= count_out + 1;
        end else begin
          count_out <= count_out - 1;
        end
      end
    end
  end

endmodule

// Pattern matching module
module pattern_matcher (
  input [99:0] data_in, // Input data from rotator
  input [2:0] count_in, // Input count from counter
  input select,     // Select input to choose between rotator and counter
  output reg match_out // Output signal to indicate a match
);

  always @(data_in, count_in, select) begin
    if (select) begin
      // Look for the specific 4-bit pattern in the rotated data
      if (data_in[3:0] == 4'hF) begin
        match_out <= 1;
      end else begin
        match_out <= 0;
      end
    end else begin
      // Look for the specific count in the counter output
      if (count_in == 3'b101) begin
        match_out <= 1;
      end else begin
        match_out <= 0;
      end
    end
  end

endmodule

