        in_data = $random;

        // Write data to the register with wenb=0
        wenb = 0;
        #10 clk = 1;
        #10 clk = 0;

        // Retain the current value of the register with wenb=1
        wenb = 1;
        #10 clk = 1;
        #10 clk = 0;

        // Check the output
        if (reg_0x4D !== in_data) begin
            $display("Test failed: Expected output %h but got %h", in_data, reg_0x4D);
            $finish;
        end

        // Write random data to the register again
        in_data = $random;

        // Write data to the register with wenb=0
        wenb = 0;
        #10 clk = 1;
        #10 clk = 0;

        // Write data to the register with wenb=0 again
        in_data = $random;
        #10 clk = 1;
