module avalon_slave_interface (
    input clk_proc,
    input reset_n,
    input [31:0] datawr_i,
    input [3:0] addr_rel_i,
    input wr_i,
    input rd_i,
    output reg [31:0] datard_o,
    output reg [31:0] magnitude_data,
    output reg [31:0] angle_data,
    output reg magnitude_dv,
    output reg angle_dv,
    output reg magnitude_fv,
    output reg angle_fv
);

localparam DEFAULT_SCR = 32'h00000000; // default value for configuration setup
localparam DEFAULT_TH = 32'h00000000; // default value for threshold

reg [31:0] config_setup; // register for configuration setup
reg [31:0] threshold; // register for threshold value
reg [31:0] data_d; // internal register for storing data

reg [31:0] config_setup_new; // new value for configuration setup
reg [31:0] threshold_new; // new value for threshold value
reg [31:0] readdata_new; // new value for read data

reg [31:0] dir_d; // register for dir_d

reg [1:0] d_max; // max value for d
reg [1:0] m_max; // max value for m

reg binarize_bit; // binarize bit
reg [3:0] NORM_FACTOR; // normalization factor
reg [7:0] token_s; // token_s
reg [7:0] token_d; // token_d

always@(posedge clk_proc or negedge reset_n) begin
    if (reset_n == 0) begin
        config_setup <= DEFAULT_SCR;
        threshold <= DEFAULT_TH;
        datard_o <= 32'b0;
        data_d <= 0;
    end else begin
        config_setup <= config_setup_new;
        threshold <= threshold_new;
        datard_o <= readdata_new;
        dir_d <= d_max;
        if (token_s[7]) begin
            if (m_max[((COEF_WIDTH + IN_SIZE)+1):0] > threshold[((COEF_WIDTH + IN_SIZE)+1):0]) begin
                if(binarize_bit) begin
                    data_d <= {(COEF_WIDTH + IN_SIZE - NORM_FACTOR){1'b1}};
                end else begin
                    data_d <= m_max[(COEF_WIDTH + IN_SIZE):NORM_FACTOR-1];
                end
            end else begin
                if(binarize_bit) begin
                    data_d <= {(COEF_WIDTH + IN_SIZE - NORM_FACTOR){1'b0}};
                end else begin
                    data_d <= {(COEF_WIDTH + IN_SIZE - NORM_FACTOR){1'b0}};
                end
            end
        end
    end
end

assign magnitude_data = data_d;
assign angle_data = dir_d;

assign magnitude_dv = token_s[8];
assign angle_dv = token_s[8];

assign magnitude_fv = (token_d[8]) ? 1'b1 : 1'b0;
assign angle_fv = (token_d[8]) ? 1'b1 : 1'b0;

always @ (*) begin
    if (wr_i) begin
        case(addr_rel_i)
            1'd0: begin
                config_setup_new = datawr_i;
                threshold_new = threshold;
            end
            1'd1: begin
                config_setup_new = config_setup;
                threshold_new = datawr_i;
            end
            default: begin
                config_setup_new = config_setup;
                threshold_new = threshold;
            end
        endcase
    end else begin
        config_setup_new = config_setup;
        threshold_new = threshold;
    end
end

always @ (*) begin
    if (rd_i) begin
        case(addr_rel_i)
            1'd0: readdata_new = config_setup;
            1'd1: readdata_new = threshold;
            default: readdata_new = datard_o;
        endcase
    end else begin
        readdata_new = datard_o;
    end
end

endmodule

