  output [7:0] rx_data,
  output rx_en,
  output tx_done,
  output rx_done
);

  reg [7:0] tx_data_reg;
  reg tx_en_reg;
  reg tx_done_reg;
  reg rx_en_reg;
  reg rx_done_reg;
  reg [7:0] rx_data_reg;
  reg [2:0] state;

  parameter IDLE = 0;
  parameter TX_START = 1;
  parameter TX_DATA = 2;
  parameter TX_DONE = 3;
  parameter RX_START = 4;
  parameter RX_DATA = 5;
  parameter RX_DONE = 6;

  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      tx_data_reg <= 8'b0;
      tx_en_reg <= 1'b0;
      tx_done_reg <= 1'b0;
      rx_en_reg <= 1'b0;
      rx_done_reg <= 1'b0;
      rx_data_reg <= 8'b0;
      state <= IDLE;
    end else begin
      case (state)
        IDLE: begin
          if (tx_en) begin
            tx_data_reg <= tx_data;
            tx_en_reg <= 1'b1;
            state <= TX_START;
          end else if (rx_en) begin
            rx_en_reg <= 1'b1;
            state <= RX_START;
          end
        end
        TX_START: begin
          tx_en_reg <= 1'b0;
          state <= TX_DATA;
        end
        TX_DATA: begin
          state <= TX_DONE;
        end
        TX_DONE: begin
          tx_done_reg <= 1'b1;
          state <= IDLE;
        end
        RX_START: begin
          rx_en_reg <= 1'b0;
          state <= RX_DATA;
        end
        RX_DATA: begin
          rx_data_reg <= rx_data;
          rx_done_reg <= 1'b1;
          state <= RX_DONE;
        end
        RX_DONE: begin
          state <= IDLE;
        end
      endcase
    end
  end

  assign rx_data = rx_data_reg;
  assign rx_en = rx_en_reg;
  assign tx_done = tx_done_reg;
  assign rx_done = rx_done_reg;

endmodule

module Profibus_slave (
  input clk,
  input reset_n,
  input [7:0] rx_data,
  input rx_en,
  output [7:0] tx_data,
  output tx_en,
  output tx_done
);

  reg [7:0] tx_data_reg;
  reg tx_en_reg;
  reg tx_done_reg;
  reg rx_en_reg;
  reg [7:0] rx_data_reg;
  reg [2:0] state;

  parameter IDLE = 0;
  parameter RX_START = 1;
  parameter RX_DATA = 2;
  parameter RX_DONE = 3;
  parameter TX_START = 4;
  parameter TX_DATA = 5;
  parameter TX_DONE = 6;

  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      tx_data_reg <= 8'b0;
      tx_en_reg <= 1'b0;
      tx_done_reg <= 1'b0;
      rx_en_reg <= 1'b0;
      rx_data_reg <= 8'b0;
      state <= IDLE;
    end else begin
      case (state)
        IDLE: begin
          if (rx_en) begin
            rx_en_reg <= 1'b1;
            state <= RX_START;
          end else if (tx_done) begin
            tx_en_reg <= 1'b0;
            tx_done_reg <= 1'b0;
            state <= TX_START;
          end
        end
        RX_START: begin
          rx_en_reg <= 1'b0;
          state <= RX_DATA;
        end
        RX_DATA: begin
          rx_data_reg <= rx_data;
          state <= RX_DONE;
        end
        RX_DONE: begin
          rx_en_reg <= 1'b1;
          state <= IDLE;
        end
        TX_START: begin
          tx_data_reg <= rx_data_reg;
          tx_en_reg <= 1'b1;
          state <= TX_DATA;
        end
        TX_DATA: begin
          state <= TX_DONE;
        end
        TX_DONE: begin
          tx_done_reg <= 1'b1;
          state <= IDLE;
        end
      endcase
    end
  end

  assign tx_data = tx_data_reg;
  assign tx_en = tx_en_reg;
  assign tx_done = tx_done_reg;

endmodule

module flow_led(
    input clk_src,
    input reset,
    input [4:0] clk_sel,
    input M,
    output reg [3:0] state
    );

    reg [3:0] counter;
    reg [4:0] pattern;

    always @(posedge clk_src, posedge reset) begin
        if (reset) begin
            counter <= 0;
            pattern <= 5'b0000;
            state <= 4'b0000;
        end else begin
            if (counter == 0) begin
                pattern <= pattern + 1;
                if (pattern > 5'b1001) begin
                    pattern <= 5'b0000;
                end
            end
            if (M) begin
                state <= {state[2:0], state[3]};
            end else begin
                state <= {state[1:3], state[0]};
            end
            case (pattern)
                5'b0000: state <= 4'b0000;
                5'b0001: state <= 4'b1111;
                5'b0010: state <= {state[2:0], state[3]};
                5'b0011: state <= {state[2:0], 1'b0};
                5'b0100: state <= {1'b0, state[3:1]};
                5'b0101: state <= {state[2:1], state[1:0]};
                5'b0110: state <= {4{1'b1}} & counter[0];
                5'b0111: state <= {4{1'b1}} & counter[1];
                5'b1000: state <= {4{1'b1}} & counter[2];
                5'b1001: state <= {4{1'b1}} & counter[3];
                default: state <= 4'b0000;
            endcase
            counter <= counter + 1;
            if (counter == 15) begin
                counter <= 0;
            end
        end
    end
endmodule

module parity (
    input [7:0] in,
    output [8:0] out);

    reg [7:0] shift_reg;
    reg parity_bit;

    always @ (posedge clk) begin
        shift_reg <= {shift_reg[6:0], in};
        parity_bit <= ^shift_reg;
    end

    assign out = {parity_bit, in};

endmodule

module delay_module (
    input A,
    output X
);
parameter DELAY_TIME = 10; // Delay time in nanoseconds

reg [DELAY_TIME-1:0] delay_reg; // Register to hold delayed signal

always @(posedge clk) begin
    delay_reg <= {delay_reg[(DELAY_TIME-2):0], A};
end

assign X = delay_reg[DELAY_TIME-1];

endmodule

module logic_op (
    input [7:0] A,
    input [7:0] B,
    input [1:0] op,
    output [7:0] Z
);

    wire [7:0] and_out;
    wire [7:0] or_out;
    wire [7:0] xor_out;
    wire [7:0] not_out;

    and_gate and_inst(
        .A(A),
        .B(B),
        .Z(and_out)
    );

    or_gate or_inst(
        .A(A),
        .B(B),
        .Z(or_out)
    );

    xor_gate xor_inst(
        .A(A),
        .B(B),
        .Z(xor_out)
    );

    not_gate not_inst(
        .A(A),
        .Z(not_out)
    );

    assign Z = (op == 2'b00) ? and_out :
              (op == 2'b01) ? or_out :
              (op == 2'b10) ? xor_out :
                              not_out;

endmodule

module and_gate (
    input [7:0] A,
    input [7:0] B,
    output [7:0] Z
);

    assign Z = A & B;

endmodule

module or_gate (
    input [7:0] A,
    input [7:0] B,
    output [7:0] Z
);

    assign Z = A | B;

endmodule

module xor_gate (
    input [7:0] A,
    input [7:0] B,
    output [7:0] Z
);

    assign Z = A ^ B;

endmodule

module not_gate (
    input [7:0] A,
    output [7:0] Z
);

    assign Z = ~A;

endmodule

module rotator (
    input clk,
    input load,
    input [1:0] ena,
    input [99:0] data,
    input d,
    output reg q
);

    reg [99:0] shifted_data;
    reg [5:0] shift_amt;
    wire [99:0] or_data;
    wire [99:0] shifted_data_left;
    wire [99:0] shifted_data_right;

    // Barrel shifter architecture
    assign shifted_data_left = {data[99-shift_amt:0], {shift_amt{1'b0}}};
    assign shifted_data_right = {{shift_amt{1'b0}}, data[99:shift_amt]};
    always @ (posedge clk) begin
        if (load) begin
            shifted_data <= data;
            shift_amt <= 0;
        end else begin
            case (ena)
                2'b00: begin // Right shift
                    shifted_data <= shifted_data_right;
                    shift_amt <= shift_amt + 1;
                end
                2'b01: begin // Left shift
                    shifted_data <= shifted_data_left;
                    shift_amt <= shift_amt + 1;
                end
                2'b10: begin // No shift
                    shifted_data <= data;
                    shift_amt <= 0;
                end
                2'b11: begin // Rotate right
                    shifted_data <= shifted_data_right;
                    shift_amt <= shift_amt + 1;
                    if (shift_amt == 100) begin
                        shift_amt <= 0;
                    end
                end
            endcase
        end
    end

    // D flip-flop using JK flip-flop and logic gate
    reg j, k;
    assign j = d;
    assign k = ~d;
    always @ (posedge clk) begin
        if (load) begin
            q <= d;
        end else begin
            q <= shifted_data[99];
        end
    end

    // Bitwise OR operation
    assign or_data = shifted_data | data;

endmodule

module top_module (
    input clk,
    input load,
    input [1:0] ena,
    input [99:0] data,
    input d,
    output reg q
);

    rotator rotator_inst (
        .clk(clk),
        .load(load),
        .ena(ena),
        .data(data),
        .d(d),
        .q(q)
    );

endmodule

module dac_interface (
    input dac_clk_1x,
    input dac_clk_2x,
    input dac_clk_2p,
    input dac_locked,
    input [13:0] dac_dat_a_i,
    input [13:0] dac_dat_b_i,
    output [13:0] dac_dat_o,
    output dac_wrt_o,
    output dac_sel_o,
    output dac_clk_o,
    output dac_rst_o
);

    reg [13:0] dac_dat_a;
    reg [13:0] dac_dat_b;
    reg dac_rst;

    always @(posedge dac_clk_1x) begin
        dac_dat_a <= {dac_dat_a_i[13], ~dac_dat_a_i[12:0]};
        dac_dat_b <= {dac_dat_b_i[13], ~dac_dat_b_i[12:0]};
        dac_rst <= !dac_locked;
    end

    assign dac_dat_o = {dac_dat_b, dac_dat_a};

    assign dac_wrt_o = 1'b0;

    always @(posedge dac_clk_2x) begin
        dac_clk_o <= 1'b0;
    end

    always @(posedge dac_clk_2p) begin
        dac_clk_o <= 1'b1;
    end

    always @(posedge dac_clk_1x) begin
        if (dac_rst) begin
            dac_sel_o <= 1'b1;
        end else begin
            dac_sel_o <= 1'b0;
        end
    end

    always @(posedge dac_clk_1x) begin
        if (dac_rst) begin
            dac_rst_o <= 1'b1;
        end else begin
            dac_rst_o <= 1'b0;
        end
    end

endmodule

module adder_subtractor (
    input [3:0] a,
    input [3:0] b,
    input sub,
    output reg [3:0] result,
    output reg co
);

reg [4:0] c;

// Adder module
adder adder_inst (
    .a(a),
    .b(b),
    .c(c)
);

// Adder-subtractor module
add_sub add_sub_inst (
    .a(c),
    .b(4'b0000),
    .sub(sub),
    .result(result)
);

// Final output module
final_output final_output_inst (
    .c(c),
    .result(result),
    .sub(sub),
    .final_result(result),
    .co(co)
);

endmodule

module adder (
    input [3:0] a,
    input [3:0] b,
    output reg [4:0] c
);

always @(*) begin
    c = {a, 1'b0} + {b, 1'b0};
end

endmodule

module add_sub (
    input [4:0] a,
    input [3:0] b,
    input sub,
    output reg [3:0] result
);

always @(*) begin
    if (sub) begin
        result = a[3:0] - b;
    end else begin
        result = a[3:0] + b;
    end
end

endmodule

module final_output (
    input [4:0] c,
    input [3:0] result,
    input sub,
    output reg [3:0] final_result,
    output reg co
);

always @(*) begin
    if (sub) begin
        final_result = result;
        co = ~c[4];
    end else begin
        final_result = c[3:0];
        co = c[4];
    end
end

endmodule

module random_wait_time(
    input clk,
    input nreset,
    input WAIT,
    output reg [5:0] wait_random
);

reg [8:0] wait_counter;

always @ (posedge clk or negedge nreset) begin
    if (!nreset) begin
        wait_counter <= 'b0;
    end else begin
        wait_counter <= wait_counter + 1'b1;
    end
end

generate
    if (WAIT) begin
        assign wait_random = |wait_counter[5:0];
    end else begin
        assign wait_random = 6'b0;
    end
endgenerate

endmodule

module ps2_rx
   (
    input wire clk, reset,
    inout wire ps2d, ps2c, 
    input wire rx_en,
    output reg rx_done_tick,
    output wire [7:0] dout
   );

   // symbolic state declaration
   localparam [1:0]
      idle = 2'b00,
      dps  = 2'b01,
      load = 2'b10;

   // signal declaration
   reg [1:0] state_reg, state_next;
   reg [7:0] filter_reg;
   wire [7:0] filter_next;
   reg f_ps2c_reg;
   wire f_ps2c_next;
   reg [3:0] n_reg, n_next;
   reg [10:0] b_reg, b_next;
   wire fall_edge;

   // body
   //=================================================
   // filter and falling-edge tick generation for ps2c
   //=================================================
   always @(posedge clk, posedge reset)
   if (reset)
      begin
         filter_reg <= 0;
         f_ps2c_reg <= 0;
      end
   else
      begin
         filter_reg <= filter_next;
         f_ps2c_reg <= f_ps2c_next;
      end

   assign filter_next = {ps2c, filter_reg[7:1]};
   assign f_ps2c_next = (filter_reg==8'b11111111) ? 1'b1 :
                        (filter_reg==8'b00000000) ? 1'b0 :
                         f_ps2c_reg;
   assign fall_edge = f_ps2c_reg & ~f_ps2c_next;

   //=================================================
   // FSMD
   //=================================================
   // FSMD state & data registers
   always @(posedge clk, posedge reset)
      if (reset)
         begin
            state_reg <= idle;
            n_reg <= 0;
            b_reg <= 0;
         end
      else
         begin
            state_reg <= state_next;
            n_reg <= n_next;
            b_reg <= b_next;
         end
   // FSMD next-state logic
   always @*
   begin
      state_next = state_reg;
      rx_done_tick = 1'b0;
      n_next = n_reg;
      b_next = b_reg;
      case (state_reg)
         idle:
            if (fall_edge & rx_en)
               begin
                  // shift in start bit
                  b_next = {1'b0, ps2d, b_reg[9:1]};
                  n_next = 4'b1001;
                  state_next = dps;
               end
         dps: // 8 data + 1 parity + 1 stop
            if (fall_edge)
               begin
                  b_next = {ps2d, b_reg[9:1]};
                  if (n_reg==0)
                     state_next = load;
                  else
                     n_next = n_reg - 1'b1;
               end
         load: // 1 extra clock to complete the last shift
            begin
               state_next = idle;
               rx_done_tick = 1'b1;
            end
      endcase
   end
   // output
   assign dout = b_reg[8:1]; // data bits

endmodule

module miller_enc(
    output miller_data,
    output mil_complete,
    input clk_mil,
    input rst_for_new_package,
    input clk_blf,
    input send_data,
    input en_fm0,
    input trext,
    input st_enc,
    input fg_complete
);

parameter GetData = 2'b00;
parameter DataP = 2'b01;
parameter DataN = 2'b10;

reg [1:0] ps;
reg [1:0] ns;

wire clk_blf_n;
wire en_mil_out;
wire m2o;
wire mp_complete;
wire me_start;

reg [5:0] mp_end;
reg [5:0] mp_cnt;
reg m_cnt;
reg m1o;
reg [1:0] data_select;
reg [1:0] fg_comp_cnt;

assign clk_blf_n = ~clk_blf;
assign en_mil_out = (mp_cnt > 6'h0)? 1'b1 : 1'b0;
assign miller_data = (en_mil_out & ~mil_complete)? m2o : 1'b0;
assign m2o = mp_complete? m1o : clk_blf;
assign mp_complete = (mp_cnt == mp_end)? 1'b1 : 1'b0;
assign me_start = (mp_cnt > mp_end - 6'h2)? 1'b1 : 1'b0;

always @(*) begin
    if (~trext) mp_end = 6'h9;
    else mp_end = 6'h21;
end

always @(posedge clk_mil or negedge rst_for_new_package) begin
    if (~rst_for_new_package) mp_cnt <= 6'h0;
    else begin
        if (mp_cnt == mp_end) mp_cnt <= mp_cnt;
        else if (~en_fm0 & st_enc) mp_cnt <= mp_cnt + 6'h1;
    end
end

always @(posedge clk_mil or negedge rst_for_new_package) begin
    if (~rst_for_new_package) m_cnt <= 1'b0;
    else if (me_start) m_cnt <= m_cnt + 1'b1;
end

always @(posedge clk_mil or negedge rst_for_new_package) begin
    if (~rst_for_new_package) ps <= GetData;
    else if (st_enc) ps <= ns;
end

always @(*) begin
    case (ps)
        GetData : if (~en_fm0 & me_start) ns = DataP;
                  else ns = GetData;
        DataP   : if (~send_data) ns = DataP;
                  else begin
                      if (~m_cnt) ns = DataP;
                      else ns = DataN;
                  end
        DataN   : if (~send_data) ns = DataN;
                  else begin
                      if (~m_cnt) ns = DataN;
                      else ns = DataP;
                  end
        default : ns = GetData;
    endcase
end

always @(*) begin
    case (ps)
        GetData : data_select = 2'h0;
        DataP   : data_select = 2'h1;
        DataN   : data_select = 2'h2;
        default : data_select = 2'h0;
    endcase
end

always @(*) begin
    case (data_select)
        2'h0   : m1o = 1'b0;
        2'h1   : m1o = clk_blf;
        2'h2   : m1o = clk_blf_n;
        default : m1o = 1'b0;
    endcase
end

always @(posedge clk_mil or negedge rst_for_new_package) begin
    if (~rst_for_new_package) fg_comp_cnt <= 2'b0;
    else begin
        if (fg_comp_cnt == 2'b11) fg_comp_cnt <= fg_comp_cnt;
        else if (~en_fm0 & fg_complete) fg_comp_cnt <= fg_comp_cnt + 2'b1;
    end
end

assign mil_complete = (fg_comp_cnt == 2'b11)? 1'b1 : 1'b0;

endmodule

module four_input_and_gate (
  A,
  B,
  C,
  D,
  EN,
  Y
);

  input [1:0] A;
  input [1:0] B;
  input [1:0] C;
  input [1:0] D;
  input EN;
  output Y;

  assign Y = (EN == 1'b1) && (A == 2'b11) && (B == 2'b10) && (C == 2'b01) && (D == 2'b00);

endmodule

module wishbone_bridge(

    input clk, rst, 
    input wb_ack_i, wb_err_i, wb_rty_i,
    input [dw-1:0] wb_dat_i,
    input [aw-1:0] cbu_adr_i,
    input [dw-1:0] cbu_dat_i,
    input cbu_rqt_i,
    input cbu_we_i,
    input [3:0] cbu_sel_i,

    output wb_cyc_o,
    output [aw-1:0] wb_adr_o,
    output wb_stb_o,
    output wb_we_o,
    output [3:0] wb_sel_o,
    output [dw-1:0] wb_dat_o,
    output [2:0] wb_cti_o,
    output [1:0] wb_bte_o,
    output cbu_ack_o,
    output cbu_err_o,
    output [dw-1:0] cbu_dat_o,
    output [aw-1:0] cbu_adr_o
);

parameter dw = 32;
parameter aw = 32;

// currently no burst support
`define WB_CTI  3'b000
`define WB_BTE  2'b00

//
// reg & wires
//
reg wb_cyc_o;   
reg [aw-1:0] wb_adr_o;
reg wb_stb_o;   
reg wb_we_o;    
reg [3:0] wb_sel_o;   
reg [dw-1:0] wb_dat_o;   
reg [2:0] wb_cti_o;    
reg [1:0] wb_bte_o;    
reg [dw-1:0] cbu_dat_o;
reg cbu_ack_o;
reg cbu_err_o;
reg [aw-1:0] cbu_adr_o;

//
// logic implementation
//

// registered request 
always @(posedge clk or posedge rst) begin
    if (rst) begin
        wb_cyc_o <= #1 1'b0;
        wb_stb_o <= #1 1'b0;
        wb_dat_o <= #1 32'd0;
        wb_adr_o <= #1 32'd0;
        wb_sel_o <= #1 4'd0;
        wb_we_o <= #1 1'd0;
        wb_cti_o <= #1 3'd0;
        wb_bte_o <= #1 2'd0;
    end
    else begin
        if (cbu_rqt_i) begin
            wb_cyc_o <= #1 cbu_rqt_i;
            wb_stb_o <= #1 cbu_rqt_i;
            wb_dat_o <= #1 cbu_dat_i;
            wb_adr_o <= #1 cbu_adr_i;
            wb_sel_o <= #1 cbu_sel_i;
            wb_we_o <= #1 cbu_we_i;    
            wb_cti_o <= #1 `WB_CTI;
            wb_bte_o <= #1 `WB_BTE;
        end
        else begin              // when core cancel bus request
            wb_cyc_o <= #1 1'b0;
            wb_stb_o <= #1 1'b0;
            wb_dat_o <= #1 32'd0;
            wb_adr_o <= #1 32'd0;
            wb_sel_o <= #1 4'd0;
            wb_we_o <= #1 1'd0;
            wb_cti_o <= #1 3'd0;
            wb_bte_o <= #1 2'd0;
        end
    end
end

// registered request 
always @(posedge clk or posedge rst) begin
    if (rst) begin
        cbu_ack_o <= #1 1'b0;
        cbu_err_o <= #1 1'b0;
    end
    else begin
        if (cbu_rqt_i) begin
            cbu_ack_o <= #1 wb_ack_i;
            cbu_err_o <= #1 wb_err_i;
        end
        else begin
            cbu_ack_o <= #1 1'b0;
            cbu_err_o <= #1 1'b0;
        end
    end
end

// special case for IMX
