module adder(a, b, sum, c_out);
   input [3:0] a, b;
   output [4:0] sum;
   output c_out;
   wire [3:0] carry;

   assign sum = a + b;
   assign carry = {a[3], b[3], sum[3]} == 3'b001 || {a[3], b[3], sum[3]} == 3'b010 || {a[3], b[3], sum[3]} == 3'b100;
   assign c_out = carry[3];

endmodule

module top_module (
    input [3:0] A,
    input [3:0] B,
    input Select,
    output [31:0] Output
);

    wire [3:0] adder_out;
    wire [31:0] multiplier_out;
    wire [31:0] max_out;

    ripple_carry_adder adder_inst (
        .A(A),
        .B(B),
        .Cin(1'b0),
        .Sum(adder_out),
        .Cout()
    );

    booth_multiplier multiplier_inst (
        .A(A),
        .B(B),
        .Product(multiplier_out)
    );

    max_module max_inst (
        .A(adder_out),
        .B(multiplier_out),
        .Max(max_out)
    );

