module booth_multiplier (
    input [3:0] A,
    input [3:0] B,
    output [31:0] Product
);

    wire [7:0] A_signed;
    wire [7:0] B_signed;
    wire [15:0] Booth_encoded;
    wire [7:0] Booth_encoded_shifted;
    wire [15:0] Product_unsigned;
    wire [31:0] Product_signed;

    assign A_signed = { {4{A[3]}}, A };
    assign B_signed = { {4{B[3]}}, B };
    assign Booth_encoded = { A_signed, 4'b0 } << 4;
    assign Booth_encoded_shifted = { Booth_encoded[15], Booth_encoded[15:8] };
    assign Product_unsigned = { {16{1'b0}}, B_signed } << 4;

    always @(*) begin
        case (Booth_encoded_shifted[15:13])
            3'b000: Product_signed = { {16{Product_unsigned[31]}}, Product_unsigned[31:16] } - Product_unsigned;
            3'b001: Product_signed = { {16{Product_unsigned[31]}}, Product_unsigned[31:16] } - (Product_unsigned >> 1);
            3'b010: Product_signed = { {16{Product_unsigned[31]}}, Product_unsigned[31:16] } + (Product_unsigned >> 1);
            3'b011: Product_signed = { {16{Product_unsigned[31]}}, Product_unsigned[31:16] } + (Product_unsigned >> 2);
            3'b100: Product_signed = { {16{Product_unsigned[31]}}, Product_unsigned[31:16] } + (Product_unsigned >> 3);
            3'b101: Product_signed = { {16{Product_unsigned[31]}}, Product_unsigned[31:16] } + (Product_unsigned >> 4);
            3'b110: Product_signed = { {16{Product_unsigned[31]}}, Product_unsigned[31:16] } + (Product_unsigned >> 5);
            3'b111: Product_signed = { {16{Product_unsigned[31]}}, Product_unsigned[31:16] } + (Product_unsigned >> 6);
        endcase
    end

    assign Product = Product_signed;

endmodule

module max_module (
    input [31:0] A,
    input [31:0] B,
    output [31:0] Max
);

    assign Max = (A > B) ? A : B;

endmodule

