module priority_encoder(
    input [3:0] in0, // First 4-bit input to the 2-to-1 multiplexer
    input [3:0] in1, // Second 4-bit input to the 2-to-1 multiplexer
    input [3:0] in2, // Third 4-bit input to the 2-to-1 multiplexer
    input [3:0] in3, // Fourth 4-bit input to the 2-to-1 multiplexer
    input sel, // 2-bit selector input to the population count circuit
    output [3:0] out // 4-bit output from the priority encoder
);

wire [3:0] mux_out; // Output from the 2-to-1 multiplexer
wire [1:0] pop_count_out; // Output from the population count circuit

// Instantiate the 2-to-1 multiplexer
mux_2to1 mux(
    .in0(in0),
    .in1(in1),
    .sel(sel[0]),
    .out(mux_out[3:0])
);

// Instantiate the population count circuit
pop_count pop_count(
    .in(mux_out[3:0]),
    .out(pop_count_out[1:0])
);

// Priority encoder logic
always @(*) begin
    if (in3 > in2 && in3 > in1 && in3 > in0) begin
        out = in3;
    end else if (in2 > in1 && in2 > in0) begin
        out = in2;
    end else if (in1 > in0) begin
        out = in1;
    end else begin
        out = in0;
    end

    if (in3 == out && pop_count_out[1] == 1) begin
        out = in3;
    end else if (in2 == out && pop_count_out[1:0] == 2'b10) begin
        out = in2;
    end else if (in1 == out && pop_count_out[1:0] == 2'b01) begin
        out = in1;
    end else if (in0 == out && pop_count_out[0] == 1) begin
        out = in0;
    end
end

endmodule

