    rise = 1'b0;
    down = 1'b0;
    case (state)
        S0: begin
            if (a) begin
                next_state = S1;
            end
        end
        S1: begin
            if (delay) begin
                next_state = S2;
            end
        end
        S2: begin
            if (!a) begin
                next_state = S0;
                down = 1'b1;
            end else begin
                rise = 1'b1;
            end
        end
    endcase
