// Control logic module
module control_logic_module (
    input [7:0] a,
    input [7:0] b,
    output reg greater_than,
    output reg equal,
    output reg enable
);

    always @(*) begin
        if (a > b) begin
            greater_than = 1;
            equal = 0;
            enable = 1;
        end else if (a < b) begin
            greater_than = 0;
            equal = 0;
            enable = 0;
        end else begin
            greater_than = 0;
            equal = 1;
            enable = 1;
        end
    end

endmodule

// Additional functional module
module functional_module (
    input [7:0] a,
    input [3:0] b,
    output reg [7:0] sum
);

    always @(*) begin
        sum = a + b;
    end

