  input                reset,      // Synchronous active-high reset
  input  [7:0]         sel,        // Select input to choose between multiplexer and counter
  input  [1023:0]      in,         // 1024-bit input vector for the multiplexer
  output [3:0]         out,        // 4-bit output of the multiplexer
  output reg [15:0]    Q          // 16-bit output of the Johnson counter
);

  // 256-to-1 multiplexer
  wire [3:0] mux_out;
  assign mux_out = in[sel*4 +: 4];
  assign out = mux_out;

  // 16-bit Johnson counter
  reg [15:0] Q_next;
  always @(posedge clk, posedge reset) begin
    if (reset) begin
      Q_next <= 16'b0000000000000000;
    end else begin
      Q_next <= {Q[14:0], Q[15] ^ Q[14]};
    end
  end
  assign Q = Q_next;

  // Functional module
  wire [3:0] mux_out_delayed;
  reg [15:0] Q_delayed;
  always @(posedge clk) begin
    mux_out_delayed <= mux_out;
    Q_delayed <= Q;
  end
  assign final_output = {mux_out_delayed, Q_delayed};

endmodule

module combined_module (
    input [15:0] data_in, // 16-bit input for barrel shifter
    input [3:0] shift_amount, // 4-bit shift amount for barrel shifter
    input shift_direction, // control input for shift direction
    output [3:0] B // output of multiply-by-three module
); 
// Internal signals
wire [15:0] barrel_shifted_output;
reg [15:0] data_out;

// Instantiate barrel shifter module
barrel_shifter barrel(
    .data_in(data_in),
    .shift_amount(shift_amount),
    .shift_direction(shift_direction),
    .data_out(barrel_shifted_output)
);

// Instantiate multiply-by-three module
multiply_by_three multiplier(
    .A(barrel_shifted_output),
    .B(B)
);

// Output of combined module
always @ (posedge clk) begin
    if (reset) begin
        data_out <= 16'h0034; // Reset to 0x34
    end else begin
        if (select) begin
            data_out <= barrel_shifted_output; // Output of barrel shifter
        end else begin
            data_out <= multiplier.B; // Output of multiply-by-three module
        end
    end
end

// Select logic to choose between barrel shifter and multiplier output
reg select;
always @ (posedge clk) begin
    if (reset) begin
        select <= 0;
    end else begin
        select <= ~select; // Enable one module at a time
    end
end

// Output of combined module
assign B = (select) ? data_out[3:0] * 3 : data_out[7:4] * 3;
endmodule

