begin : ap_ret_ap_CS_fsm
    if (ap_rst == 1'b1) begin
        ap_CS_fsm <= ap_ST_st1_fsm_0;
    end else begin
        ap_CS_fsm <= ap_NS_fsm;
    end
end

always @ (posedge ap_clk)
begin : ap_ret_cnt
    if (ap_rst == 1'b1) begin
        cnt <= ap_const_lv32_0;
    end else begin
        if (((ap_ST_st1_fsm_0 == ap_CS_fsm) & ~ap_sig_bdd_24)) begin
            cnt <= tmp_fu_49_p2;
        end
    end
end

always @ (ap_CS_fsm or ap_sig_bdd_24)
begin
    if (((ap_ST_st1_fsm_0 == ap_CS_fsm) & ~ap_sig_bdd_24)) begin
        ap_NS_fsm = ap_ST_st1_fsm_0;
    end else begin
        ap_NS_fsm = ap_CS_fsm;
    end
end

always @ (in_fifo_V_empty_n or out_fifo_V_full_n)
begin
    ap_sig_bdd_24 = ((in_fifo_V_empty_n == ap_const_logic_0) | (out_fifo_V_full_n == ap_const_logic_0));
end

assign out_fifo_V_din = (cnt + ap_const_lv32_FFFFFFFF);
assign tmp_fu_49_p2 = (cnt + ap_const_lv32_FFFFFFFF);

always @ (in_fifo_V_empty_n, out_fifo_V_full_n, ap_CS_fsm)
begin
    if (in_fifo_V_empty_n == 1'b1 && out_fifo_V_full_n == 1'b1 && ap_CS_fsm == 1'b0) begin
        // Idle state
        in_fifo_V_read = 1'b1;
        out_fifo_V_write = 1'b0;
    end else if (in_fifo_V_empty_n == 1'b0 && out_fifo_V_full_n == 1'b1 && ap_CS_fsm == 1'b0) begin
        // Empty input FIFO
        in_fifo_V_read = 1'b0;
        out_fifo_V_write = 1'b0;
    end else if (in_fifo_V_empty_n == 1'b1 && out_fifo_V_full_n == 1'b0 && ap_CS_fsm == 1'b0) begin
        // Full output FIFO
        in_fifo_V_read = 1'b1;
        out_fifo_V_write = 1'b0;
    end else if (in_fifo_V_empty_n == 1'b1 && out_fifo_V_full_n == 1'b1 && ap_CS_fsm == 1'b1) begin
        // Writing to output FIFO
        in_fifo_V_read = 1'b0;
        out_fifo_V_write = 1'b1;
    end else begin
        // Invalid state
        in_fifo_V_read = 1'b0;
        out_fifo_V_write = 1'b0;
    end
end

endmodule

module FSM (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 4; // number of input signals
parameter m = 2; // number of output signals
parameter s = 8; // number of states

reg [2:0] state; // current state
reg [1:0] substate; // current sub-state

// transition functions
always @ (in, state) begin
  case (state)
    3'b000: if (in[0]) substate <= 2'b01; else substate <= 2'b00;
    3'b001: if (in[1]) substate <= 2'b01; else substate <= 2'b00;
    3'b010: if (in[2]) substate <= 2'b01; else substate <= 2'b00;
    3'b011: if (in[3]) substate <= 2'b01; else substate <= 2'b00;
    3'b100: if (in[0] && in[1]) substate <= 2'b01; else substate <= 2'b00;
    3'b101: if (in[2] && in[3]) substate <= 2'b01; else substate <= 2'b00;
    3'b110: if (in[0] || in[1]) substate <= 2'b01; else substate <= 2'b00;
    3'b111: if (in[2] || in[3]) substate <= 2'b01; else substate <= 2'b00;
  endcase
end

// output functions
always @ (in, substate) begin
  case (substate)
    2'b00: out <= {in[0], in[1]};
    2'b01: out <= {in[2], in[3]};
  endcase
end

// next state logic
always @ (substate) begin
  case (substate)
    2'b00: state <= 3'b000;
    2'b01: state <= 3'b001;
  endcase
end

endmodule

module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out
);

reg [9:0] sum1, sum2, sum3, sum4, sum5, sum6, sum7;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sum1 <= 0;
        sum2 <= 0;
        sum3 <= 0;
        sum4 <= 0;
        sum5 <= 0;
        sum6 <= 0;
        sum7 <= 0;
        valid_b <= 0;
        data_out <= 0;
    end else begin
        sum1 <= sum7 + data_in;
        sum2 <= sum1;
        sum3 <= sum2;
        sum4 <= sum3;
        sum5 <= sum4;
        sum6 <= sum5;
        sum7 <= sum6;
        if (valid_a && ready_b) begin
            valid_b <= 1;
            data_out <= sum7;
        end else begin
            valid_b <= 0;
        end
    end
end

assign ready_a = ~valid_b;

endmodule

module VGA_Controller (
    input wire Clock,
    input wire Enable,
    input wire Reset,
    input wire[2:0] iPixel,
    output wire oHorizontalSync,
    output wire oVerticalSync,
    output wire oRed,
    output wire oGreen,
    output wire oBlue,
    output wire[9:0] oColumnCount,
    output wire[9:0] oRowCount
);

    // Counter for horizontal pixel count
    wire [10:0] wColumnCount;
    wire wColumnReset;
    assign wColumnReset = (wColumnCount == 11'd1599);
    assign oColumnCount = wColumnCount[10:1];

    UPCOUNTER_POSEDGE # (11) COLUMN_COUNTER (
        .Clock(Clock),
        .Reset(wColumnReset | Reset),
        .Initial(11'd0),
        .Enable(Enable),
        .Q(wColumnCount)
    );

    // Counter for vertical pixel count
    wire [9:0] wRowCount;
    wire wRowReset;
    assign wRowReset = (wRowCount == 10'd524 && wColumnReset);
    assign oRowCount = wRowCount;

    UPCOUNTER_POSEDGE # (10) ROW_COUNTER (
        .Clock(Clock),
        .Reset(wRowReset | Reset),
        .Initial(10'd0),
        .Enable(wColumnReset),
        .Q(wRowCount)
    );

    // VGA timings
    parameter H_VISIBLE_AREA = 640;
    parameter H_FRONT_PORCH = 16;
    parameter H_PULSE = 96;
    parameter H_BACK_PORCH = 48;
    parameter HORIZONTAL_LINE = 800;
    parameter V_VISIBLE_AREA = 480;
    parameter V_FRONT_PORCH = 10;
    parameter V_PULSE = 2;
    parameter V_BACK_PORCH = 33;
    parameter VERTICAL_LINE = 525;

    // Horizontal sync signal
    wire hSync;
    assign hSync = (wColumnCount[10:1] >= (H_VISIBLE_AREA + H_FRONT_PORCH) && wColumnCount[10:1] <= (H_VISIBLE_AREA + H_FRONT_PORCH + H_PULSE)) ? 1'b0 : 1'b1;
    assign oHorizontalSync = hSync;

    // Vertical sync signal
    wire vSync;
    assign vSync = (wRowCount >= (V_VISIBLE_AREA + V_FRONT_PORCH) && wRowCount <= (V_VISIBLE_AREA + V_FRONT_PORCH + V_PULSE)) ? 1'b0 : 1'b1;
    assign oVerticalSync = vSync;

    // Pixel color
    parameter BLACK = 3'b000;
    assign {oRed, oGreen, oBlue} = (wColumnCount[10:1] < H_VISIBLE_AREA && wRowCount < V_VISIBLE_AREA) ? iPixel : BLACK;

endmodule

module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] in,   // 8-bit input for the parity generator
    output [7:0] out  // 8-bit output from the system
);

    // Parity generator
    wire [7:0] in_xor = ^in;
    wire parity_bit = in_xor[0] ^ in_xor[1] ^ in_xor[2] ^ in_xor[3] ^ in_xor[4] ^ in_xor[5] ^ in_xor[6] ^ in_xor[7];

    // Asynchronous reset 4-bit binary counter
    reg [3:0] counter = 4'b1000;
    always @(posedge clk or negedge reset) begin
        if (!reset) begin
            counter <= 4'b1000;
        end else if (counter == 4'b1111) begin
            counter <= 4'b0000;
        end else begin
            counter <= counter + 1;
        end
    end

    // Functional module to add parity bit and counter output
    wire [3:0] counter_plus_parity = counter + parity_bit;

    // Output
    assign out = {counter_plus_parity, counter};

endmodule

