module hilbert_transform (
  input in,
  output out1,
  output out2
);

  // Define the transfer function of the Hilbert transform block
  // Transfer function: H(jw) = -j * sign(w)
  // where j is the imaginary unit and sign(w) is the sign function of the frequency w
  // We can implement the sign function using a simple comparator
  // If w is positive, the output of the comparator is 1, otherwise it is -1
  // We can then multiply the input signal by -j and the sign function to get the complex output signal
  // The real and imaginary components of the complex signal are the output signals out1 and out2

  wire sign;
  assign sign = (in >= 0) ? 1 : -1;

  assign out1 = in * sign;
  assign out2 = -in * $signed(sign);

endmodule

