module magnitude_comparator_selector_decoder (
    input clk,
    input [2:0] a, b,
    input [1:0] select,
    output reg Y0,
    output reg Y1,
    output reg Y2,
    output reg Y3,
    output reg [2:0] comparison_result,
    output reg [1:0] input_selected,
    output reg [1:0] final_output
);

reg [2:0] magnitude_result;
reg [2:0] a_mag;
reg [2:0] b_mag;

// Magnitude Comparator Module
always @ (posedge clk) begin
    if (a > b) begin
        magnitude_result <= 3'b001;
        a_mag <= a;
        b_mag <= 3'b000;
    end else if (a < b) begin
        magnitude_result <= 3'b010;
        a_mag <= 3'b000;
        b_mag <= b;
    end else begin
        magnitude_result <= 3'b100;
        a_mag <= 3'b000;
        b_mag <= 3'b000;
    end
end

// Selector Module
always @ (posedge clk) begin
    case (select)
        2'b00: begin
            comparison_result <= magnitude_result;
            input_selected <= 2'b00;
        end
        2'b01: begin
            comparison_result <= magnitude_result;
            input_selected <= 2'b01;
        end
        2'b10: begin
            comparison_result <= 3'b000;
            input_selected <= 2'b00;
        end
        2'b11: begin
            comparison_result <= 3'b000;
            input_selected <= 2'b01;
        end
    endcase
end

// Decoder Module
always @ (posedge clk) begin
    case (comparison_result)
        3'b001: begin
            Y0 <= 1'b0;
            Y1 <= 1'b0;
            Y2 <= 1'b0;
            Y3 <= 1'b1;
        end
        3'b010: begin
            Y0 <= 1'b0;
            Y1 <= 1'b0;
            Y2 <= 1'b1;
            Y3 <= 1'b0;
        end
        3'b100: begin
            Y0 <= 1'b0;
            Y1 <= 1'b1;
            Y2 <= 1'b0;
            Y3 <= 1'b0;
        end
        default: begin
            Y0 <= 1'b1;
            Y1 <= 1'b0;
            Y2 <= 1'b0;
            Y3 <= 1'b0;
        end
    endcase
end

// Final Output Module
always @ (posedge clk) begin
    final_output <= {Y3, Y2};
end

endmodule

module carry_lookahead_adder (
    input [7:0] a,
    input [7:0] b,
    output [7:0] s,
    output carry_out
);

wire [7:0] p, g;
wire [7:0] c;

assign p = a ^ b;
assign g = a & b;

assign c[0] = g[0];
assign c[1] = g[1] | (p[1] & g[0]);
assign c[2] = g[2] | (p[2] & g[1]) | (p[2] & p[1] & g[0]);
assign c[3] = g[3] | (p[3] & g[2]) | (p[3] & p[2] & g[1]) | (p[3] & p[2] & p[1] & g[0]);
assign c[4] = g[4] | (p[4] & g[3]) | (p[4] & p[3] & g[2]) | (p[4] & p[3] & p[2] & g[1]) | (p[4] & p[3] & p[2] & p[1] & g[0]);
assign c[5] = g[5] | (p[5] & g[4]) | (p[5] & p[4] & g[3]) | (p[5] & p[4] & p[3] & g[2]) | (p[5] & p[4] & p[3] & p[2] & g[1]) | (p[5] & p[4] & p[3] & p[2] & p[1] & g[0]);
assign c[6] = g[6] | (p[6] & g[5]) | (p[6] & p[5] & g[4]) | (p[6] & p[5] & p[4] & g[3]) | (p[6] & p[5] & p[4] & p[3] & g[2]) | (p[6] & p[5] & p[4] & p[3] & p[2] & g[1]) | (p[6] & p[5] & p[4] & p[3] & p[2] & p[1] & g[0]);
assign c[7] = g[7] | (p[7] & g[6]) | (p[7] & p[6] & g[5]) | (p[7] & p[6] & p[5] & g[4]) | (p[7] & p[6] & p[5] & p[4] & g[3]) | (p[7] & p[6] & p[5] & p[4] & p[3] & g[2]) | (p[7] & p[6] & p[5] & p[4] & p[3] & p[2] & g[1]) | (p[7] & p[6] & p[5] & p[4] & p[3] & p[2] & p[1] & g[0]);

assign s = a + b + {1'b0, c};

assign carry_out = c[7];

endmodule

module top_module (
    input [7:0] a,
    input [7:0] b,
    output [7:0] s,
    output overflow
);

wire carry_out;
wire signed_overflow;

carry_lookahead_adder adder(a, b, s, carry_out);

assign signed_overflow = ((a[7] == b[7]) && (a[7] != s[7]));

assign overflow = signed_overflow || carry_out;

endmodule

module Divider(
   input  clock,
   input  reset,
   input  OP_div,     		// True to initiate a signed divide
   input  OP_divu,    		// True to initiate an unsigned divide
   input  [31:0] Dividend,
   input  [31:0] Divisor,
   output [31:0] Quotient,
   output [31:0] Remainder,
   output Stall,       		// True while calculating
   //Voter Signals for Registers
   input  active,     		// True if the divider is running
   input  neg,        		// True if the result will be negative
   input  [31:0] result,  // Begin with dividend, end with quotient
   input  [31:0] denom,   // Divisor
   input  [31:0] work,
   output reg  vote_active,     		// True if the divider is running
   output reg  vote_neg,        		// True if the result will be negative
   output reg  [31:0] vote_result,  // Begin with dividend, end with quotient
   output reg  [31:0] vote_denom,   // Divisor
   output reg  [31:0] vote_work
);

   reg [4:0] cycle;      // Number of cycles to go
   wire [32:0] sub;      // Difference between work and denom
   reg [31:0] divisor;   // Absolute value of divisor
   reg [31:0] dividend;  // Absolute value of dividend
   reg [31:0] quotient;  // Absolute value of quotient
   reg [31:0] remainder; // Absolute value of remainder
   reg neg_quot;         // True if quotient is negative
   reg neg_rem;          // True if remainder is negative

   // Calculate the current digit
   assign sub = { work[30:0], result[31] } - denom;

   // Send the results to our master
   assign Quotient = neg_quot ? -quotient : quotient;
   assign Remainder = neg_rem ? -remainder : remainder;
   assign Stall = active;

   // The state machine
   always @(posedge clock) begin
      if (reset) begin
         vote_active <= 0;
         vote_neg <= 0;
         cycle <= 0;
         vote_result <= 0;
         vote_denom <= 0;
         vote_work <= 0;
