module DLL (
  input ref_clk,
  input fb_clk,
  output out_clk
);

parameter n = 4; // number of delay stages
parameter delay = 10; // delay of each stage in ps

reg [n-1:0] delay_reg; // register to hold delay values for each stage
reg [n-1:0] delay_adj; // register to hold delay adjustments for each stage
reg [n-1:0] delay_out; // register to hold output delay values for each stage
reg [n-1:0] delay_in; // register to hold input delay values for each stage

wire [n-1:0] fb_delayed; // wire to hold delayed feedback clock signal
wire [n-1:0] ref_delayed; // wire to hold delayed reference clock signal
wire [n-1:0] phase_diff; // wire to hold phase difference between delayed feedback and reference signals

assign fb_delayed = {n{1'b0}}; // initialize delayed feedback signal to all zeros

// create chain of delay elements
genvar i;
generate
  for (i = 0; i < n; i = i + 1) begin : delay_chain
    always @(posedge ref_clk) begin
      delay_reg[i] <= delay_in[i];
      delay_out[i] <= delay_reg[i];
    end
    assign delay_in[i] = (i == 0) ? fb_clk : delay_out[i-1];
  end
endgenerate

// delay feedback signal by n*delay
always @(posedge ref_clk) begin
  fb_delayed <= {fb_delayed[(n-2):0], fb_clk};
end

// delay reference signal by n*delay
always @(posedge ref_clk) begin
  ref_delayed <= {ref_delayed[(n-2):0], ref_clk};
end

// calculate phase difference between delayed feedback and reference signals
assign phase_diff = fb_delayed ^ ref_delayed;

// adjust delay values based on phase difference
always @(posedge ref_clk) begin
  if (phase_diff != 0) begin
    delay_adj <= phase_diff;
  end
  delay_reg <= delay_reg + delay_adj;
end

// output phase-aligned clock signal
assign out_clk = delay_out[n-1];

endmodule

