                    buffer_valid <= 1'b1;
                    m_axi_arready <= 1'b0;
                    m_axi_rvalid <= 1'b0;
                    state <= IDLE;
                end
            end
            WRITE_CUSTOM: begin
                if (!custom_in_valid) begin
                    custom_out_valid <= 1'b0;
                    state <= IDLE;
                end
            end
        endcase
    end
end

// Output buffer data to custom interface
always @(posedge aclk) begin
    if (areset) begin
        buffer_valid <= 1'b0;
    end else begin
        if (buffer_valid && !custom_out_valid) begin
            custom_out_data <= buffer;
            custom_out_valid <= 1'b1;
            buffer_valid <= 1'b0;
        end
    end
end

// Output AXI read data to module output
always @(posedge aclk) begin
    if (areset) begin
        m_axi_rvalid <= 1'b0;
    end else begin
        if (buffer_valid && !custom_out_valid && buffer_addr == m_axi_araddr) begin
            m_axi_rdata <= buffer;
            m_axi_rvalid <= 1'b1;
        end
    end
end

