assign m_axi_wvalid = axi_wr;
assign m_axi_araddr = read_addr;
assign m_axi_arvalid = axi_rd;
assign m_axi_rready = 1'b1;

always @(posedge m_axi_awready or negedge m_axi_awvalid) begin
    if (axi_wr && m_axi_awready) begin
        write_addr <= m_axi_awaddr;
    end
