module top_module (
  input [7:0] a, b, c, d, // 8-bit unsigned numbers
  input [3:0] data0, // 4-bit input data0
  input [3:0] data1, // 4-bit input data1
  input [3:0] data2, // 4-bit input data2
  input [3:0] data3, // 4-bit input data3
  input [3:0] data4, // 4-bit input data4
  input [3:0] data5, // 4-bit input data5
  input [2:0] sel, // Select input to choose between 6 inputs
  output [11:0] out // 12-bit output from the functional module
);

  // Priority Encoder to find the position of the minimum value
  wire [1:0] pos;
  priority_encoder pe(a < b, b < c, c < d);
  assign pos = pe.pos;

  // Multiplexer to output the corresponding value as an 8-bit unsigned number
  wire [7:0] min_val;
  always @* begin
    case (pos)
      2'b00: min_val = a;
      2'b01: min_val = b;
      2'b10: min_val = c;
      2'b11: min_val = d;
    endcase
  end
  assign out[7:0] = min_val;

  // Case statement to select the input based on the value of sel
  wire [3:0] selected_input;
  always @* begin
    case (sel)
      3'b000: selected_input = data0;
      3'b001: selected_input = data1;
      3'b010: selected_input = data2;
      3'b011: selected_input = data3;
      3'b100: selected_input = data4;
      3'b101: selected_input = data5;
      default: selected_input = 4'b0;
    endcase
  end

  // If-else statement to perform the bitwise AND or OR operation based on the parity of sel
  wire [3:0] result;
  always @* begin
    if (sel[0] == 1'b0) begin
      result = min_val & selected_input;
    end else begin
      result = min_val | selected_input;
    end
  end

  // Assign the output to the result of the bitwise operation or 0 if sel is greater than 5 as a 4-bit value
  always @* begin
    if (sel > 3'b101) begin
      out[3:0] = 4'b0;
    end else begin
      out[3:0] = result;
    end
    out[11:4] = min_val;
  end

endmodule

// Priority Encoder module
module priority_encoder (
  input [3:0] in0,
  input [3:0] in1,
  input [3:0] in2,
  input [3:0] in3,
  output reg [1:0] pos
);
  always @* begin
    if (in0 < in1 && in0 < in2 && in0 < in3) begin
      pos = 2'b00;
    end else if (in1 < in2 && in1 < in3) begin
      pos = 2'b01;
    end else if (in2 < in3) begin
      pos = 2'b10;
    end else begin
      pos = 2'b11;
    end
  end
endmodule

