wire [255:0] stage2_in [0:3];
wire [255:0] stage3_in [0:1];

// Stage 1
genvar i;
generate
    for (i = 0; i < 8; i = i + 1) begin : stage1
        assign stage1_in[i] = (i == 0) ? in : stage2_out[i-1];
        assign stage1_out[i] = stage1_in[i][sel[2:0]];
    end
endgenerate

// Stage 2
genvar j;
generate
    for (j = 0; j < 4; j = j + 1) begin : stage2
        assign stage2_in[j] = (j == 0) ? stage1_out[7] : stage3_out[j-1];
        assign stage2_out[j] = stage2_in[j][sel[5:3]];
    end
endgenerate

// Stage 3
genvar k;
generate
    for (k = 0; k < 2; k = k + 1) begin : stage3
        assign stage3_in[k] = (k == 0) ? stage2_out[3] : stage3_out[k-1];
        assign stage3_out[k] = stage3_in[k][sel[7:6]];
    end
endgenerate

assign out = stage3_out[1];

endmodule

