module branch_predictor (clock, reset, enable, taken_i, prediction_o);

  input clock, reset, enable, taken_i;
  output prediction_o;

  wire [1:0] current_state;
  wire [3:0] prediction_table [0:3];

  // 2-bit saturating counter
  always @(posedge clock, posedge reset) begin
    if (reset) begin
      current_state <= 2'b00;
    end else begin
      case ({current_state, taken_i})
        2'b00_0: current_state <= 2'b00;
        2'b00_1: current_state <= 2'b01;
        2'b01_0: current_state <= 2'b00;
        2'b01_1: current_state <= 2'b10;
        2'b10_0: current_state <= 2'b01;
        2'b10_1: current_state <= 2'b11;
        2'b11_0: current_state <= 2'b10;
        2'b11_1: current_state <= 2'b11;
      endcase
    end
  end

  // Predictor table
  always @(posedge clock, posedge reset) begin
    if (reset) begin
      prediction_table[0] <= 2'b00;
      prediction_table[1] <= 2'b00;
      prediction_table[2] <= 2'b00;
      prediction_table[3] <= 2'b00;
    end else begin
      case (current_state)
        2'b00: begin
          if (taken_i) begin
            if (prediction_table[0] < 2'b11) begin
              prediction_table[0] <= prediction_table[0] + 1;
            end
          end else begin
            if (prediction_table[0] > 2'b00) begin
              prediction_table[0] <= prediction_table[0] - 1;
            end
          end
        end
        2'b01: begin
          if (taken_i) begin
            if (prediction_table[1] < 2'b11) begin
              prediction_table[1] <= prediction_table[1] + 1;
            end
          end else begin
            if (prediction_table[1] > 2'b00) begin
              prediction_table[1] <= prediction_table[1] - 1;
            end
          end
        end
        2'b10: begin
          if (taken_i) begin
            if (prediction_table[2] < 2'b11) begin
              prediction_table[2] <= prediction_table[2] + 1;
            end
          end else begin
            if (prediction_table[2] > 2'b00) begin
              prediction_table[2] <= prediction_table[2] - 1;
            end
          end
        end
        2'b11: begin
          if (taken_i) begin
            if (prediction_table[3] < 2'b11) begin
              prediction_table[3] <= prediction_table[3] + 1;
            end
          end else begin
            if (prediction_table[3] > 2'b00) begin
              prediction_table[3] <= prediction_table[3] - 1;
            end
          end
        end
      endcase
    end
  end

  // Output prediction
  always @(current_state or prediction_table) begin
    case (current_state)
      2'b00: prediction_o <= (prediction_table[0][1] == 1'b1);
      2'b01: prediction_o <= (prediction_table[1][1] == 1'b1);
      2'b10: prediction_o <= (prediction_table[2][1] == 1'b1);
      2'b11: prediction_o <= (prediction_table[3][1] == 1'b1);
    endcase
  end

endmodule

