module display_module(
    input CLK_EXT,
    input [1:0] RXD,
    input [17:0] SRAM_A,
    inout [15:0] SRAM_D,
    output reg [7:0] SEG,
    output reg [7:0] DIG
);

    // Define constants
    parameter CLK_FREQ = 50000000;
    parameter DISPLAY_TIME = 2 * CLK_FREQ;
    parameter DIGIT_COUNT = 4;

    // Define variables
    reg [15:0] input_value;
    reg [3:0] digit_select;
    reg [31:0] display_timer;

    // Read input value from RAM module
    always @(posedge CLK_EXT) begin
        SRAM_A <= {2'b0, digit_select};
        input_value <= SRAM_D;
    end

    // Set digit select output
    always @(posedge CLK_EXT) begin
        if (display_timer == 0) begin
            digit_select <= digit_select + 1;
            if (digit_select == DIGIT_COUNT) begin
                digit_select <= 0;
            end
            display_timer <= DISPLAY_TIME;
        end else begin
            display_timer <= display_timer - 1;
        end
        DIG <= {4'b1110, ~digit_select};
    end

    // Set 7-segment display output
    always @(posedge CLK_EXT) begin
        case (input_value[digit_select*4 +: 4])
            4'b0000: SEG <= 7'b1000000; // 0
            4'b0001: SEG <= 7'b1111001; // 1
            4'b0010: SEG <= 7'b0100100; // 2
            4'b0011: SEG <= 7'b0110000; // 3
            4'b0100: SEG <= 7'b0011001; // 4
            4'b0101: SEG <= 7'b0010010; // 5
            4'b0110: SEG <= 7'b0000010; // 6
            4'b0111: SEG <= 7'b1111000; // 7
            4'b1000: SEG <= 7'b0000000; // 8
            4'b1001: SEG <= 7'b0010000; // 9
            default: SEG <= 7'b0000001; // error
        endcase
    end

    // Read rotary encoder input
    always @(posedge CLK_EXT) begin
        if (RXD == 2'b01) begin
            input_value <= input_value + 1;
        end else if (RXD == 2'b10) begin
            input_value <= input_value - 1;
        end
        SRAM_A <= {2'b0, digit_select};
        SRAM_D <= input_value;
    end

endmodule

