module alu(
    input clk,
    input reset_n,
    input opcode_valid,
    input [2:0] opcode,
    input signed [7:0] data,
    output reg done,
    output reg overflow,
    output reg signed [7:0] result
);

reg signed [7:0] a;
reg signed [7:0] b;
reg signed [15:0] m;
reg signed [15:0] d;
reg signed [7:0] not_data;

always @(posedge clk) begin
    if (!reset_n) begin
        done <= 0;
        overflow <= 0;
        result <= 0;
    end else if (opcode_valid) begin
        done <= 1;
        case (opcode)
            3'b000: begin // addition
                a <= data;
                b <= result;
                result <= a + b;
                overflow <= (a[7] == b[7] && result[7] != a[7]);
            end
            3'b001: begin // subtraction
                a <= data;
                b <= result;
                result <= a - b;
                overflow <= (a[7] != b[7] && result[7] != a[7]);
            end
            3'b010: begin // multiplication
                a <= data;
                b <= result;
                m <= a * b;
                result <= m[7:0];
                overflow <= (m[15:8] != 8'b0 && m[15:8] != 8'b11111111);
            end
            3'b011: begin // division
                a <= data;
                b <= result;
                if (b != 0) begin
                    d <= a / b;
                    result <= d[7:0];
                    overflow <= 0;
                end else begin
                    overflow <= 1;
                end
            end
            3'b100: begin // logical AND
                a <= data;
                b <= result;
                result <= a & b;
                overflow <= 0;
            end
            3'b101: begin // logical OR
                a <= data;
                b <= result;
                result <= a | b;
                overflow <= 0;
            end
            3'b110: begin // logical NOT
                not_data <= ~data;
                result <= not_data[7:0];
                overflow <= 0;
            end
            default: begin // invalid opcode
                done <= 0;
                overflow <= 0;
                result <= 0;
            end
        endcase
    end
end

endmodule

