    input wire Cin,
    output reg S,
    output reg C
);

assign S = A ^ B ^ Cin;
assign C = (A & B) | (Cin & (A ^ B));

endmodule

module barrel_shifter (
    input i_clk,
    input [31:0] i_in,
    input i_carry_in,
    input [7:0] i_shift_amount,
    input i_shift_imm_zero,
    input [1:0] i_function,
    output reg [31:0] o_out,
    output reg o_carry_out,
    output reg o_stall
);

wire [31:0] quick_out;
wire quick_carry_out;
wire [31:0] full_out;
wire full_carry_out;
reg [31:0] full_out_r = 32'd0;
reg full_carry_out_r = 1'd0;
reg use_quick_r = 1'd1;

// Full barrel shifter
a25_shifter_full u_shifter_full (
    .i_in(i_in),
    .i_carry_in(i_carry_in),
    .i_shift_amount(i_shift_amount),
    .i_shift_imm_zero(i_shift_imm_zero),
    .i_function(i_function),
    .o_out(full_out),
    .o_carry_out(full_carry_out)
);

// Quick barrel shifter
a25_shifter_quick u_shifter_quick (
    .i_in(i_in),
    .i_carry_in(i_carry_in),
    .i_shift_amount(i_shift_amount),
    .i_shift_imm_zero(i_shift_imm_zero),
    .i_function(i_function),
    .o_out(quick_out),
    .o_carry_out(quick_carry_out)
);

// Select output based on control signal
always @(*) begin
    if (i_function == 2'b00) begin
        o_out = full_out_r;
        o_carry_out = full_carry_out_r;
    end else if (i_function == 2'b01 && i_shift_amount <= 7) begin
        o_out = quick_out;
        o_carry_out = quick_carry_out;
    end else begin
        o_out = full_out;
        o_carry_out = full_carry_out;
    end
end

// Stall output until shift operation is complete
always @(posedge i_clk) begin
    full_out_r <= full_out;
    full_carry_out_r <= full_carry_out;
    use_quick_r <= !o_stall;
end

assign o_stall = (|i_shift_amount[7:2]) & use_quick_r;

endmodule

