module Multiplexer
   (ctrl,
    D0,
    D1,
    S);
  input ctrl;
  input [0:0]D0;
  input [0:0]D1;
  output [0:0]S;

  wire [0:0]S;
  wire [0:0]not_ctrl;
  wire [0:0]ctrl_and_D0;
  wire [0:0]ctrl_and_D1;

  assign not_ctrl = ~ctrl;
  assign ctrl_and_D0 = ctrl & D0;
  assign ctrl_and_D1 = ctrl & D1;

  LUT3 #(
    .INIT(8'hB8)) 
    \S[0]_INST_0 
       (.I0(D1),
        .I1(ctrl),
        .I2(D0),
        .O(S));

  assign S = ctrl_and_D1 | (not_ctrl & ctrl_and_D0);
endmodule

