        if (MemWrite) begin
            MemRead <= 0;
            MemWrite <= 1;
        end else if (MemRead) begin
            MemWrite <= 0;
            MemRead <= 1;
        end else begin
            MemWrite <= 0;
            MemRead <= 0;
        end
