module top_module (
    input A,
    input B,
    input C,
    input invert,
    input select,
    output reg [2:0] out
);

reg mux_out;
reg [7:0] decoder_out;

mux mux_inst (
    .A(A),
    .B(B),
    .C(C),
    .invert(invert),
    .out(mux_out)
);

decoder decoder_inst (
    .A(A),
    .B(B),
    .C(C),
    .OUT(decoder_out)
);

always @(*) begin
    if (invert) begin
        out = 3'b111;
    end else begin
        if (C) begin
            out = 3'b100;
        end else if (B) begin
            out = 3'b010;
        end else if (A) begin
            out = 3'b001;
        end
    end
end

always @(select) begin
    if (select) begin
        out <= decoder_out[2:0];
    end else begin
        out <= mux_out;
    end
end

endmodule

