module arbiter (
    input clk,
    input reset,
    // Source 1 pins
    input s1_request,
    output s1_grant,
    output [0:0] s1_byteenable_out,
    output [21:0] s1_address_out,
    output [0:0] s1_read_n_out,
    output [0:0] s1_write_n_out,
    output [7:0] s1_data_out,
    input [7:0] s1_data_in,
    output s1_data_outen,
    output [0:0] s1_chipselect_n_out,
    output [0:0] s1_begintransfer_out,
    // Source 2 pins
    input s2_request,
    output s2_grant,
    output [0:0] s2_byteenable_out,
    output [21:0] s2_address_out,
    output [0:0] s2_read_n_out,
    output [0:0] s2_write_n_out,
    output [7:0] s2_data_out,
    input [7:0] s2_data_in,
    output s2_data_outen,
    output [0:0] s2_chipselect_n_out,
    output [0:0] s2_begintransfer_out,
    // Arbiter outputs
    output [0:0] grant_data,
    output grant_ready,
    output sink0_valid
);

// Internal signals
reg [1:0] state;
reg [0:0] next_grant_data;

// Initialize signals
assign s1_grant = (state == 2) ? 1'b1 : 1'b0;
assign s2_grant = (state == 1) ? 1'b1 : 1'b0;
assign grant_data = next_grant_data;
assign grant_ready = (state == 0) ? 1'b1 : 1'b0;
assign sink0_valid = (state == 0) ? 1'b0 : 1'b1;

// State machine
always @(posedge clk) begin
    if (reset) begin
        state <= 2'b00;
        next_grant_data <= 1'b0;
    end else begin
        case (state)
            2'b00: begin // Idle state
                if (s1_request) begin
                    state <= 2'b10;
                    next_grant_data <= 1'b1;
                end else if (s2_request) begin
                    state <= 2'b01;
                    next_grant_data <= 1'b0;
                end
            end
            2'b01: begin // Source 2 has access
                if (!s2_request) begin
                    state <= 2'b00;
                    next_grant_data <= 1'b0;
                end
            end
            2'b10: begin // Source 1 has access
                if (!s1_request) begin
                    state <= 2'b00;
                    next_grant_data <= 1'b0;
                end
            end
        endcase
    end
end

// Assign outputs based on state
always @(*) begin
    case (state)
        2'b00: begin // Idle state
            s1_byteenable_out = 1'b0;
            s1_address_out = 22'b0;
            s1_read_n_out = 1'b1;
            s1_write_n_out = 1'b1;
            s1_data_out = 8'b0;
            s1_data_outen = 1'b0;
            s1_chipselect_n_out = 1'b1;
            s1_begintransfer_out = 1'b0;
            s2_byteenable_out = 1'b0;
            s2_address_out = 22'b0;
            s2_read_n_out = 1'b1;
            s2_write_n_out = 1'b1;
            s2_data_out = 8'b0;
            s2_data_outen = 1'b0;
            s2_chipselect_n_out = 1'b1;
            s2_begintransfer_out = 1'b0;
        end
        2'b01: begin // Source 2 has access
            s1_byteenable_out = 1'b0;
            s1_address_out = 22'b0;
            s1_read_n_out = 1'b1;
            s1_write_n_out = 1'b1;
            s1_data_out = 8'b0;
            s1_data_outen = 1'b0;
            s1_chipselect_n_out = 1'b1;
            s1_begintransfer_out = 1'b0;
            s2_byteenable_out = s2_byteenable_out;
            s2_address_out = s2_address_out;
            s2_read_n_out = s2_read_n_out;
            s2_write_n_out = s2_write_n_out;
            s2_data_out = s2_data_out;
            s2_data_outen = s2_data_outen;
            s2_chipselect_n_out = s2_chipselect_n_out;
            s2_begintransfer_out = s2_begintransfer_out;
        end
        2'b10: begin // Source 1 has access
            s1_byteenable_out = s1_byteenable_out;
            s1_address_out = s1_address_out;
            s1_read_n_out = s1_read_n_out;
            s1_write_n_out = s1_write_n_out;
            s1_data_out = s1_data_out;
            s1_data_outen = s1_data_outen;
            s1_chipselect_n_out = s1_chipselect_n_out;
            s1_begintransfer_out = s1_begintransfer_out;
            s2_byteenable_out = 1'b0;
            s2_address_out = 22'b0;
            s2_read_n_out = 1'b1;
            s2_write_n_out = 1'b1;
            s2_data_out = 8'b0;
            s2_data_outen = 1'b0;
            s2_chipselect_n_out = 1'b1;
            s2_begintransfer_out = 1'b0;
        end
    endcase
end

// Assign next grant data
always @(*) begin
    case (state)
        2'b00: begin // Idle state
            next_grant_data = 1'b0;
        end
        2'b01: begin // Source 2 has access
            next_grant_data = 1'b0;
        end
        2'b10: begin // Source 1 has access
            next_grant_data = 1'b1;
        end
    endcase
end

endmodule

