  always @(posedge clk, posedge rst) begin
    if (rst) begin
      vad_out <= 0;
      buffer_ptr <= 0;
      audio_buffer <= 0;
    end else begin
      audio_buffer[buffer_ptr] <= audio_in;
      buffer_ptr <= (buffer_ptr == BUFFER_SIZE-1) ? 0 : buffer_ptr + 1;
      vad_out <= (energy > THRESHOLD) ? 1 : 0;
    end
  end

