  );

  // Connect the sum signals of the full adders
  assign S[0] = s[0];
  generate
    for (j = 1; j < 4; j = j + 1) begin : sum
      assign S[j] = s[j] ^ c[j];
    end
  endgenerate

endmodule

module full_adder(
  input A,
