module clk_wiz(
    input clk_in,
    input rst,
    input [31:0] f_out,
    output reg clk_out,
    output reg locked
);

reg [31:0] cnt;
reg [31:0] M;
reg [31:0] N;
reg [31:0] f_d;

always @(posedge clk_in or posedge rst) begin
    if (rst) begin
        cnt <= 0;
        M <= 0;
        N <= 0;
        f_d <= 0;
        clk_out <= 0;
        locked <= 0;
    end else begin
        cnt <= cnt + 1;
        if (cnt == M) begin
            cnt <= 0;
            clk_out <= ~clk_out;
        end
    end
end

always @(posedge clk_in or posedge rst) begin
    if (rst) begin
        locked <= 0;
    end else begin
        if (cnt == 0) begin
            if (f_d == f_out) begin
                locked <= 1;
            end else begin
                locked <= 0;
            end
        end
    end
end

always @(*) begin
    N = $floor(clk_in / f_out);
    M = $floor(N + 0.5);
    f_d = $floor(clk_in / M);
end

endmodule

module pipeline_adder(
    input wire [15:0] in,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo
);

    wire [7:0] adder_out1, adder_out2;
    wire [7:0] select_out1, select_out2;
    wire [7:0] mux_out1, mux_out2;

    // Stage 1
    ripple_carry_adder adder1(.a(in[7:0]), .b(in[15:8]), .cin(1'b0), .sum(adder_out1), .cout());

    // Stage 2
    carry_select_adder select1(.a(in[7:0]), .b(in[15:8]), .cin(1'b0), .sum(select_out1), .cout());

    // Stage 3
    mux2x1 mux1(.a(adder_out1), .b(select_out1), .sel(in[8]), .out(mux_out1));

    // Stage 4
    ripple_carry_adder adder2(.a(mux_out1), .b(in[7:0]), .cin(1'b0), .sum(adder_out2), .cout());

    // Stage 5
    carry_select_adder select2(.a(mux_out1), .b(in[7:0]), .cin(1'b0), .sum(select_out2), .cout());

    // Stage 6
    mux2x1 mux2(.a(adder_out2), .b(select_out2), .sel(in[8]), .out(mux_out2));

    assign out_hi = mux_out1;
    assign out_lo = mux_out2;

endmodule

module barrel_shifter (
    input [7:0] A,
    input [3:0] B,
    output reg [7:0] Q
);

always @(*) begin
    if (B == 0) begin
        Q = A;
    end else if (B < 8) begin
        Q = {A[B-1:0], A[7:B]};
    end else begin
        Q = 8'b0;
    end
end

endmodule

module comparator (
    input [7:0] a,
    input [7:0] b,
    output reg gt,
    output reg lt,
    output reg eq
);

always @(*) begin
    if (a > b) begin
        gt = 1;
        lt = 0;
        eq = 0;
    end else if (a < b) begin
        gt = 0;
        lt = 1;
        eq = 0;
    end else begin
        gt = 0;
        lt = 0;
        eq = 1;
    end
end

endmodule

