module instruction_cache(
  input clk,
  input reset,
  input [31:0] ic_addr,
  input ic_rq,
  output reg ic_data_out_valid,
  output reg [31:0] ic_data_out,
  input [31:0] data_in,
  input data_in_ready,
  output reg data_rd,
  output reg [31:0] data_address
);

  parameter IC_WIDTH_BITS = 5; // 32B cache line
  parameter IC_LINES_BITS = 6; // 64 lines
  parameter IC_WIDTH_ZERO = 5'b0;
  parameter IC_WIDTH_ONES = 5'h1f;

  reg [31-IC_WIDTH_BITS+1:0] ictags[0:IC_LINES_BITS-1];
  reg [31:0] cacheram[0:IC_LINES_BITS*32-1];
  wire [31-IC_WIDTH_BITS:0] addrtag;

  assign addrtag = ic_addr[31:IC_WIDTH_BITS];

  reg [31-IC_WIDTH_BITS+1:0] icnewtag;

  parameter S_IDLE = 2'b00;
  parameter S_FILL = 2'b01;
  parameter S_FILL_STEP = 2'b10;

  reg [1:0] ic_state;
  reg [31:0] ictagsout;
  reg [1:0] ic_rq_shift;

  always @(posedge clk) begin
    if (!reset) begin
      ic_data_out_valid <= 0;
      ic_data_out <= 0;
      icnewtag <= 0;
      data_rd <= 0;
      ic_state <= S_IDLE;
      ictagsout <= 0;
      ic_rq_shift <= 0;
    end else begin
      ic_rq_shift <= {ic_rq_shift[0], ic_rq};
      ictagsout <= ictags[ic_addr[IC_WIDTH_BITS+IC_LINES_BITS-1:IC_WIDTH_BITS]];
      case (ic_state)
        S_IDLE: begin
          if (ic_rq_shift[1]) begin
            if (ictagsout == {addrtag, 3'b1}) begin // hit
              ic_data_out <= cacheram[ic_addr[IC_WIDTH_BITS+IC_LINES_BITS-1:0]];
              ic_data_out_valid <= 1;
            end else begin // miss
              ic_data_out_valid <= 0;
              ictags[ic_addr[IC_WIDTH_BITS+IC_LINES_BITS-1:IC_WIDTH_BITS]] <= {addrtag, 3'b1}; // update tag
              ic_state <= S_FILL;
              data_address <= {ic_addr[31:IC_WIDTH_BITS], IC_WIDTH_ZERO}; // start of cache line
              data_rd <= 1;
              icnewtag <= {addrtag, 3'b1};
            end
          end else begin
            ic_data_out_valid <= 0;
            ic_data_out <= 0;
          end
        end
        S_FILL: begin
          if (data_in_ready) begin
            if (ic_rq && data_address == ic_addr) begin // premature hit
              ic_data_out <= data_in;
              ic_data_out_valid <= 1;
            end else begin
              ic_data_out_valid <= 0;
              ic_data_out <= 0;
            end
            cacheram[data_address[IC_LINES_BITS+IC_WIDTH_BITS-1:0]] <= data_in; // write to cache
            data_rd <= 0;
            if (data_address[IC_WIDTH_BITS-1:0] == IC_WIDTH_ONES) begin // end of cache line
              ictags[data_address[IC_LINES_BITS+IC_WIDTH_BITS-1:IC_WIDTH_BITS]] <= icnewtag; // update tag
              ic_state <= S_IDLE;
            end else begin
              ic_state <= S_FILL_STEP;
              data_address <= data_address + 1;
            end
          end else begin // data_in_ready is false
            if (ic_rq && data_address[IC_LINES_BITS+IC_WIDTH_BITS-1:IC_WIDTH_BITS] == ic_addr[IC_LINES_BITS+IC_WIDTH_BITS-1:IC_WIDTH_BITS]
                && !(data_address[31:IC_WIDTH_BITS] == ic_addr[31:IC_WIDTH_BITS])) begin // evict cache line
              ictags[ic_addr[IC_WIDTH_BITS+IC_LINES_BITS-1:IC_WIDTH_BITS]] <= 0;
              ic_state <= S_IDLE;
              ic_data_out_valid <= 0;
            end
            if (ic_rq && data_address[31:IC_WIDTH_BITS] == ic_addr[31:IC_WIDTH_BITS]
                && ic_addr[IC_WIDTH_BITS-1:0] < data_address[IC_WIDTH_BITS-1:0]) begin // cache hit
              ic_data_out <= cacheram[ic_addr[IC_WIDTH_BITS+IC_LINES_BITS-1:0]];
              ic_data_out_valid <= 1;
            end else begin
              ic_data_out_valid <= 0;
              ic_data_out <= 0;
            end
          end
        end
        S_FILL_STEP: begin
          data_rd <= 1;
          ic_state <= S_FILL;
          ic_data_out_valid <= 0;
          ic_data_out <= 0;
        end
      endcase
    end
  end

endmodule

module tone_detection_generation (
  input clk,
  input audio_in,
  input tone_freq,
  output tone_detected,
  output tone_out
);

parameter sampling_rate = 44100; // in Hz
parameter tone_frequency = 1000; // in Hz

// additional parameters and io definitions can be added as needed.

// Tone detection block
reg [15:0] audio_buffer [0:2];
wire [15:0] filtered_audio;
wire tone_present;

assign tone_detected = tone_present;

// Band-pass filter
fir_filter #(.TAPS(32), .COEFFICIENTS("insert filter coefficients here")) filter (
  .clk(clk),
  .data_in(audio_in),
  .data_out(filtered_audio)
);

// Threshold detector
