wire pll_clk;
wire pll_locked;

// instantiate the Altera PLL
altpll_pll pll (
    .inclk0(inclk0),
    .c0(pll_clk),
    .c1(pll_locked)
);

// configure the PLL to generate the output clock signal
assign locked = (pll_locked == 1'b1);
assign outclk = pll_clk / div;

// reset the frequency divider on the rising edge of the reset signal
reg [3:0] count;
always @(posedge reset) begin
    count <= 4'b0000;
end

// increment the counter on every rising edge of the output clock signal
always @(posedge outclk) begin
    if (count == div - 1) begin
        count <= 4'b0000;
    end else begin
        count <= count + 1;
    end
end

endmodule

module divider (
  input signed [31:0] dividend,
  input signed [31:0] divisor,
  input ctrl,
  output signed [31:0] quotient,
  output signed [31:0] remainder
);

parameter unsigned_div = 1; // enable unsigned division by default
parameter signed_div = 0; // disable signed division by default

reg unsigned_div_reg;
reg signed_div_reg;

always @* begin
  unsigned_div_reg = unsigned_div;
  signed_div_reg = signed_div;
end

reg [31:0] dividend_reg;
reg [31:0] divisor_reg;
reg ctrl_reg;

always @(posedge clk) begin
  dividend_reg <= dividend;
  divisor_reg <= divisor;
  ctrl_reg <= ctrl;
end

reg [31:0] quotient_reg;
reg [31:0] remainder_reg;

always @* begin
  if (ctrl_reg == 1'b1) begin
    if (unsigned_div_reg == 1'b1 && signed_div_reg == 1'b0) begin
      quotient_reg = dividend_reg / divisor_reg;
      remainder_reg = dividend_reg % divisor_reg;
    end
    else if (unsigned_div_reg == 1'b0 && signed_div_reg == 1'b1) begin
      quotient_reg = $signed(dividend_reg) / $signed(divisor_reg);
      remainder_reg = $signed(dividend_reg) % $signed(divisor_reg);
    end
    else begin
      $error("Error: Both unsigned_div and signed_div are false.");
    end
  end
  else begin
    quotient_reg = 0;
    remainder_reg = 0;
  end
end

assign quotient = quotient_reg;
assign remainder = remainder_reg;

endmodule

