module digital_system(led, gpioBank1, gpioBank2, clk, sw, btn);
  output [7:0] led;
  output [3:0] gpioBank1;
  output [3:0] gpioBank2;
  input clk;
  input [7:0] sw;
  input [3:0] btn;

  parameter memBits = 10;
  parameter memAddrWidth = 16;
  parameter dataBits = 8;

  wire sclk, sclkPosEdge, sclkNegEdge;
  wire sclk8PosEdge;
  wire writeEnable;
  wire [memAddrWidth-1:0] addr;
  wire [memBits-1:0] dataIn, dataOut;
  wire [memBits-1:0] instr;
  wire cs, dc;
  wire [dataBits-1:0] parallelData;
  wire parallelLoad, serialDataIn, serialDataOut;
  wire [dataBits-1:0] parallelDataOut;
  wire [memAddrWidth-1:0] memAddr;
  wire reset;
  wire md, mq, cd, cq, dd, dq;
  wire delayEn, pcEn;

  assign addr = memAddr;
  assign parallelLoad = sclk8PosEdge;
  assign parallelDataIn = dataOut;
  assign instr = dataOut;
  assign md = serialDataOut;
  assign cd = cs;
  assign dd = dc;
  assign mq = parallelDataOut[7];
  assign cq = parallelDataOut[6];
  assign dq = parallelDataOut[5];
  assign led = parallelDataOut[7:0];
  assign reset = btn[0];
  assign gpioBank2[0] = !btn[1];

  serialClock #(3) sc(clk, sclk, sclkPosEdge, sclkNegEdge, sclk8PosEdge);
  memory m(clk, writeEnable, addr, dataIn, dataOut);
  programCounter pc(clk, sclkPosEdge, pcEn, memAddr, sclk8PosEdge, reset);
  shiftRegister sr(clk, sclkPosEdge, parallelLoad, parallelDataIn, serialDataIn, parallelDataOut, serialDataOut, sclk8PosEdge);
  finiteStateMachine fsm(clk, sclkPosEdge, instr, cs, dc, delayEn, parallelData);
  mosiFF mff(clk, sclkNegEdge, md, mq);
  mosiFF csff(clk, sclkNegEdge, cd, cq);
  mosiFF dcff(clk, sclkNegEdge, dd, dq);
  delayCounter delC(clk, delayEn, pcEn);

endmodule

module serialClock(clk, sclk, sclkPosEdge, sclkNegEdge, sclk8PosEdge);
  input clk;
  output sclk, sclkPosEdge, sclkNegEdge, sclk8PosEdge;

  reg [2:0] count = 0;

  always @(posedge clk) begin
    count <= count + 1;
    sclk <= count[2];
    sclkPosEdge <= (count == 0);
    sclkNegEdge <= (count == 1);
    sclk8PosEdge <= (count == 2);
  end

endmodule

module memory(clk, writeEnable, addr, dataIn, dataOut);
  input clk, writeEnable;
  input [memAddrWidth-1:0] addr;
  inout [memBits-1:0] dataIn, dataOut;

  reg [memBits-1:0] mem[0:(2**memAddrWidth)-1];

  always @(posedge clk) begin
    if (writeEnable) begin
      mem[addr] <= dataIn;
    end
    dataOut <= mem[addr];
  end

endmodule

module programCounter(clk, sclkPosEdge, pcEn, memAddr, sclk8PosEdge, reset);
  input clk, sclkPosEdge, pcEn, reset;
  output reg [memAddrWidth-1:0] memAddr;
  output reg sclk8PosEdge;

  always @(posedge clk) begin
    if (reset) begin
      memAddr <= 0;
      sclk8PosEdge <= 0;
    end else if (sclkPosEdge) begin
      if (pcEn) begin
        memAddr <= memAddr + 1;
      end
      sclk8PosEdge <= 0;
    end else if (sclk8PosEdge == 0) begin
      sclk8PosEdge <= 1;
    end
  end

endmodule

module shiftRegister(clk, sclkPosEdge, parallelLoad, parallelDataIn, serialDataIn, parallelDataOut, serialDataOut, sclk8PosEdge);
  input clk, sclkPosEdge, parallelLoad, serialDataIn, sclk8PosEdge;
  input [dataBits-1:0] parallelDataIn;
  output [dataBits-1:0] parallelDataOut;
  output serialDataOut;

  reg [dataBits-1:0] shiftReg;

  always @(posedge clk) begin
    if (parallelLoad) begin
      shiftReg <= parallelDataIn;
    end else if (sclkPosEdge) begin
      shiftReg <= {shiftReg[dataBits-2:0], serialDataIn};
    end
  end

  assign parallelDataOut = shiftReg;

  assign serialDataOut = shiftReg[dataBits-1];

endmodule

module finiteStateMachine(clk, sclkPosEdge, instr, cs, dc, delayEn, parallelData);
  input clk, sclkPosEdge;
  input [memBits-1:0] instr;
  output reg cs, dc;
  output reg [dataBits-1:0] parallelData;
  output reg delayEn;

  reg [2:0] state = 0;

  always @(posedge clk) begin
    case (state)
      0: begin // idle
        cs <= 1;
        dc <= 1;
        parallelData <= 0;
        delayEn <= 0;
        if (instr == 8'b00000001) begin
          state <= 1;
        end
      end
      1: begin // send command
        cs <= 0;
        dc <= 0;
        parallelData <= 8'b11010100;
        delayEn <= 1;
        state <= 2;
      end
      2: begin // wait
        cs <= 0;
        dc <= 0;
        parallelData <= 8'b11010100;
        delayEn <= 0;
        if (instr == 8'b00000010) begin
          state <= 3;
        end
      end
      3: begin // send data
        cs <= 0;
        dc <= 1;
        parallelData <= sw;
        delayEn <= 1;
        state <= 4;
      end
      4: begin // wait
        cs <= 0;
        dc <= 1;
        parallelData <= sw;
        delayEn <= 0;
        if (instr == 8'b00000011) begin
          state <= 5;
        end
      end
      5: begin // send command
        cs <= 0;
        dc <= 0;
        parallelData <= 8'b11010111;
        delayEn <= 1;
        state <= 6;
      end
      6: begin // wait
        cs <= 0;
        dc <= 0;
        parallelData <= 8'b11010111;
        delayEn <= 0;
        state <= 0;
      end
      default: begin
        state <= 0;
      end
    endcase
  end

endmodule

module mosiFF(clk, sclkNegEdge, d, q);
  input clk, sclkNegEdge, d;
  output reg q;

  always @(negedge sclkNegEdge) begin
    q <= d;
  end

endmodule

module delayCounter(clk, delayEn, pcEn);
  input clk, delayEn;
  output reg pcEn;

  reg [15:0] count = 0;

  always @(posedge clk) begin
    if (delayEn) begin
      count <= count + 1;
      pcEn <= 0;
    end else begin
      count <= 0;
      pcEn <= 1;
    end
  end

endmodule

module VAD (
  input audio_in,
  output speech_detected
);

parameter fs = 8000; // sample rate of the audio signal
parameter frame_size = 160; // number of samples in each frame
parameter frame_overlap = 80; // number of samples that overlap between frames
parameter threshold = 100; // energy threshold for detecting speech

reg [15:0] frame_samples [0:frame_size-1]; // buffer for storing audio samples in each frame
reg [15:0] energy; // energy of the current frame
reg [15:0] energy_threshold; // threshold for detecting speech
reg [1:0] frame_index; // current frame index
reg speech_detected; // output indicating whether speech is present

// compute the energy of the signal in the current frame
function [15:0] compute_energy;
  input [15:0] samples [0:frame_size-1];
  reg [15:0] energy;
  integer i;
  begin
    energy = 0;
    for (i = 0; i < frame_size; i = i + 1) begin
      energy = energy + (samples[i] * samples[i]);
    end
    compute_energy = energy;
  end
endfunction

// initialize the module
initial begin
  energy_threshold = threshold * frame_size;
  frame_index = 0;
  speech_detected = 0;
end

// process each audio sample
always @(posedge audio_in) begin
  frame_samples[frame_index] = audio_in;
  if (frame_index == frame_size - 1) begin
    energy = compute_energy(frame_samples);
    if (energy > energy_threshold) begin
      speech_detected = 1;
    end else begin
      speech_detected = 0;
    end
  end
  frame_index = (frame_index + 1) % frame_overlap;
end

endmodule

