module chatgpt_generate_edge_detect(
  input               clk,
  input               rst_n,
  input               a,
  output reg          rise,
  output reg          fall
);

  // Define states for the state machine
  parameter IDLE = 2'b00;
  parameter RISING = 2'b01;
  parameter FALLING = 2'b10;

  // Define current state and next state variables
  reg [1:0] state, next_state;

  // Define edge detection variables
  reg a_prev;

  // Initialize state and edge detection variables
  initial begin
    state = IDLE;
    a_prev = 1'b0;
  end

  // State machine logic
  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      state <= IDLE;
      a_prev <= 1'b0;
    end
    else begin
      state <= next_state;
      a_prev <= a;
    end
  end

  // Next state logic
  always @(*) begin
    case (state)
      IDLE: begin
        if (a != a_prev) begin
          if (a > a_prev) begin
            next_state = RISING;
          end
          else begin
            next_state = FALLING;
          end
        end
        else begin
          next_state = IDLE;
        end
      end
      RISING: begin
        next_state = IDLE;
      end
      FALLING: begin
        next_state = IDLE;
      end
      default: begin
        next_state = IDLE;
      end
    endcase
  end

  // Output logic
  always @(state) begin
    case (state)
      IDLE: begin
        rise <= 1'b0;
        fall <= 1'b0;
      end
      RISING: begin
        rise <= 1'b1;
        fall <= 1'b0;
      end
      FALLING: begin
        rise <= 1'b0;
        fall <= 1'b1;
      end
      default: begin
        rise <= 1'b0;
        fall <= 1'b0;
      end
    endcase
  end

endmodule

