assign ahl[3] = a[3];
assign bhl[2:0] = b[6:4] ^ b[2:0];
assign bhl[3] = b[3];
Sks4 ksm3(ahl, bhl, m3);

assign  d[00] = m2[00];
assign  d[01] = m2[01];
assign  d[02] = m2[02];
assign  d[03] = m2[03];
assign  d[04] = m2[04] ^ m1[00] ^ m2[00] ^ m3[00];
assign  d[05] = m2[05] ^ m1[01] ^ m2[01] ^ m3[01];
assign  d[06] = m2[06] ^ m1[02] ^ m2[02] ^ m3[02];
assign  d[07] = m1[03] ^ m2[03] ^ m3[03];
assign  d[08] = m1[04] ^ m2[04] ^ m3[04] ^ m1[00];
assign  d[09] = m2[05] ^ m3[05] ^ m1[01];
assign  d[10] = m2[06] ^ m3[06] ^ m1[02];
assign  d[11] = m1[03];
assign  d[12] = m1[04];

endmodule

module bitwise_shift (
   // Inputs
   clk,
   amt
   );

   input clk;
   input [31:0] amt;

   reg [31:0] right;
   reg [31:0] left;
   reg [63:0] qright;
   reg [63:0] qleft;

   always @* begin
      right = 32'h819b018a >> amt;
      left  = 32'h819b018a << amt;
      qright = 64'hf784bf8f_12734089 >> amt;
      qleft  = 64'hf784bf8f_12734089 << amt;
   end

   integer cyc; initial cyc=1;
   always @ (posedge clk) begin
      if (cyc!=0) begin
         cyc <= cyc + 1;
         if (cyc==1) begin
            amt <= 32'd0;
            if (5'b10110>>2  != 5'b00101) $stop;
            if (5'b10110>>>2 != 5'b00101) $stop;  // Note it cares about sign-ness
            if (5'b10110<<2  != 5'b11000) $stop;
            if (5'b10110<<<2 != 5'b11000) $stop;
            if (5'sb10110>>2  != 5'sb00101) $stop;
            if (5'sb10110>>>2 != 5'sb11101) $stop;
            if (5'sb10110<<2  != 5'sb11000) $stop;
            if (5'sb10110<<<2 != 5'sb11000) $stop;
         end
         if (cyc==2) begin
            amt <= 32'd28;
            if (left  != 32'h819b018a) $stop;
            if (right != 32'h819b018a) $stop;
            if (qleft  != 64'hf784bf8f_12734089) $stop;
            if (qright != 64'hf784bf8f_12734089) $stop;
         end
         if (cyc==3) begin
            amt <= 32'd31;
            if (left  != 32'ha0000000) $stop;
            if (right != 32'h8) $stop;
            if (qleft  != 64'h0000000f784bf8f1) $stop;
            if (qright != 64'h0000000f784bf8f1) $stop;
         end
         if (cyc==4) begin
            amt <= 32'd32;
            if (left  != 32'h0) $stop;
            if (right != 32'h1) $stop;
            if (qleft  != 64'h00000001ef097f1e) $stop;
            if (qright != 64'h00000001ef097f1e) $stop;
         end
         if (cyc==5) begin
            amt <= 32'd33;
            if (left  != 32'h0) $stop;
            if (right != 32'h0) $stop;
            if (qleft  != 64'h00000000f784bf8f) $stop;
            if (qright != 64'h00000000f784bf8f) $stop;
         end
         if (cyc==6) begin
            amt <= 32'd64;
            if (left  != 32'h0) $stop;
            if (right != 32'h0) $stop;
            if (qleft  != 64'h000000007bc25fc7) $stop;
            if (qright != 64'h000000007bc25fc7) $stop;
         end
         if (cyc==7) begin
            amt <= 32'd128;
            if (left  != 32'h0) $stop;
            if (right != 32'h0) $stop;
            if (qleft  != 64'h0) $stop;
            if (qright != 64'h0) $stop;
         end
         if (cyc==8) begin
            if (left  != 32'h0) $stop;
            if (right != 32'h0) $stop;
            if (qleft  != 64'h0) $stop;
            if (qright != 64'h0) $stop;
         end
         if (cyc==9) begin
            $write("*-* All Finished *-*\n");
            $finish;
         end
      end
   end
endmodule

