module top_module( 
    input [2:0] a,
    input [2:0] b,
    input sel_b1,
    input sel_b2,
    output [2:0] out_or_bitwise,
    output out_or_logical,
    output [5:0] out_not,
    output reg final_output
);

    wire [2:0] mux_out;
    wire [2:0] bitwise_or;
    wire bitwise_logical_or;
    wire [2:0] bitwise_not_a;
    wire [2:0] bitwise_not_b;

    // Instantiate the 2-to-1 mux
    mux_2to1 mux_inst(
        .a(a),
        .b(b),
        .sel(sel_b1),
        .out(mux_out)
    );

    // Instantiate the 3-bit bitwise operator
    bitwise_operator bitwise_inst(
        .a(a),
        .b(b),
        .out_or(bitwise_or),
        .out_logical_or(bitwise_logical_or),
        .out_not_a(bitwise_not_a),
        .out_not_b(bitwise_not_b)
    );

    // Final output logic
    always @(*) begin
        if (sel_b2 == 0) begin
            final_output = bitwise_logical_or | mux_out[0];
        end else begin
            final_output = bitwise_logical_or | mux_out[1];
        end
    end

    // Output assignments
    assign out_or_bitwise = bitwise_or;
    assign out_or_logical = bitwise_logical_or;
    assign out_not = {bitwise_not_b, bitwise_not_a};

endmodule

