module fifo_buffer (
  input wire i_dat,
  input wire i_vld,
  output reg o_dat,
  output reg o_vld,
  input wire o_rdy
);

  reg fifo_i_dat;
  reg fifo_i_vld;
  reg fifo_o_dat;
  reg fifo_o_vld;

  wire i_rdy = fifo_i_rdy;

  // The FIFO is bypassed when:
  //   * fifo is empty, and o_rdy is high
  wire byp = i_vld & o_rdy & (~fifo_o_vld);

  // FIFO o-ready just use the o_rdy
  assign fifo_o_rdy = o_rdy;

  // The output is valid if FIFO or input have valid
  assign o_vld = fifo_o_vld | i_vld;

  // The output data select the FIFO as high priority
  assign o_dat = fifo_o_vld ? fifo_o_dat : i_dat;

  assign fifo_i_dat  = i_dat;

  // Only pass to FIFO i-valid if FIFO is not bypassed
  assign fifo_i_vld = i_vld & (~byp);

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      fifo_i_dat <= 0;
      fifo_i_vld <= 0;
      fifo_o_dat <= 0;
      fifo_o_vld <= 0;
      o_dat <= 0;
      o_vld <= 0;
    end else begin
      // FIFO input write
      if (i_vld & i_rdy & (~byp)) begin
        fifo_i_dat <= i_dat;
        fifo_i_vld <= 1;
      end

      // FIFO output read
      if (o_rdy & fifo_o_vld) begin
        fifo_o_vld <= 0;
      end else if (o_rdy & (~byp)) begin
        fifo_o_dat <= fifo_i_dat;
        fifo_o_vld <= fifo_i_vld;
        fifo_i_vld <= 0;
      end

      // Output bypass
      if (o_rdy & (~fifo_o_vld) & i_vld & (~byp)) begin
        o_dat <= i_dat;
        o_vld <= 1;
      end else begin
        o_dat <= fifo_o_dat;
        o_vld <= fifo_o_vld;
      end
    end
  end

endmodule

