module axi_register_slice #(parameter DATA_WIDTH = 32) (
    input wire clk,
    input wire resetn,
    input wire s_axi_arvalid,
    input wire [DATA_WIDTH-1:0] s_axi_araddr,
    input wire s_axi_rready,
    output wire s_axi_arready,
    output wire s_axi_rvalid,
    output wire [DATA_WIDTH-1:0] s_axi_rdata,
    output wire [1:0] s_axi_rresp
);

    // Internal registers
    reg [DATA_WIDTH-1:0] rdata_reg;
    reg [1:0] rresp_reg;
    reg rvalid_reg;
    reg arready_reg;
    reg skid_buffer_reg;

    // Payload logic
    wire [1:0] bresp_acc_reg;
    wire [DATA_WIDTH-1:0] out;
    wire [2:0] skid_buffer;
    wire [0:0] s_bresp_acc_reg;

    LUT6 #(
        .INIT(64'hB8FFB8B8B800B8B8)) 
    m_payload_i_1 (
        .I0(s_bresp_acc_reg[0]),
        .I1(rvalid_reg),
        .I2(skid_buffer_reg),
        .I3(s_axi_rready),
        .I4(s_axi_rvalid),
        .I5(bresp_acc_reg[0]),
        .O(out)
    );

    LUT6 #(
        .INIT(64'hB8FFB8B8B800B8B8)) 
    m_payload_i_2 (
        .I0(s_bresp_acc_reg[1]),
        .I1(rvalid_reg),
        .I2(skid_buffer_reg),
        .I3(s_axi_rready),
        .I4(s_axi_rvalid),
        .I5(bresp_acc_reg[1]),
        .O(out)
    );

    LUT6 #(
        .INIT(64'hB8FFB8B8B800B8B8)) 
    m_payload_i_3 (
        .I0(out),
        .I1(rvalid_reg),
        .I2(skid_buffer_reg),
        .I3(s_axi_rready),
        .I4(s_axi_rvalid),
        .I5(s_axi_araddr),
        .O(out)
    );

    // Register slice logic
    always @(posedge clk) begin
        if (!resetn) begin
            rdata_reg <= 0;
            rresp_reg <= 0;
            rvalid_reg <= 0;
            arready_reg <= 0;
            skid_buffer_reg <= 0;
        end else begin
            if (s_axi_rready && rvalid_reg) begin
                rvalid_reg <= 0;
            end

            if (s_axi_arvalid && !rvalid_reg && !skid_buffer_reg) begin
                rdata_reg <= out;
                rresp_reg <= 0;
                rvalid_reg <= 1;
                arready_reg <= 1;
            end else if (s_axi_arvalid && rvalid_reg && !skid_buffer_reg) begin
                skid_buffer_reg <= 1;
            end else if (skid_buffer_reg && s_axi_rready) begin
                skid_buffer_reg <= 0;
                rdata_reg <= out;
                rresp_reg <= 0;
                rvalid_reg <= 1;
                arready_reg <= 1;
            end else if (s_axi_rvalid && rvalid_reg) begin
                rresp_reg <= bresp_acc_reg;
                arready_reg <= 0;
            end else begin
                arready_reg <= 0;
            end
        end
    end

    // Output logic
    assign s_axi_arready = arready_reg;
    assign s_axi_rvalid = rvalid_reg;
    assign s_axi_rdata = rdata_reg;
    assign s_axi_rresp = rresp_reg;
    assign s_bresp_acc_reg[0] = bresp_acc_reg[0];
    assign s_bresp_acc_reg[1] = bresp_acc_reg[1];
    assign bresp_acc_reg[0] = s_axi_rresp[0];
    assign bresp_acc_reg[1] = s_axi_rresp[1];
    assign skid_buffer[0] = s_bresp_acc_reg[0] && rvalid_reg;
    assign skid_buffer[1] = s_bresp_acc_reg[1] && rvalid_reg;
    assign skid_buffer[2] = s_axi_arvalid && !rvalid_reg && !skid_buffer_reg;
    assign s_axi_rready = !skid_buffer[0] && !skid_buffer[1] && !skid_buffer[2];

endmodule

