module control_logic (
    input select,
    input [2:0] a,
    input [2:0] b,
    input data,
    output [3:0] shift_out,
    output [2:0] out_or_bitwise,
    output out_or_logical,
    output [5:0] out_not,
    output led
);

    reg shift_enable;
    reg bitwise_enable;
    reg [1:0] counter;

    always @(posedge clk) begin
        if (counter == 2'd0) begin
            counter <= 2'd1;
            led <= shift_enable;
        end else begin
            counter <= 2'd0;
            led <= bitwise_enable;
        end
    end

    assign shift_enable = select;
    assign bitwise_enable = ~select;

    shift_register shift_reg (
        .clk(clk),
        .reset(reset),
        .data(data),
        .shift_out(shift_out)
    );

    bitwise_or_logical_or_inverter bitwise_or (
        .a(a),
        .b(b),
        .out_or_bitwise(out_or_bitwise),
        .out_or_logical(out_or_logical),
        .out_not(out_not)
    );

    always @(select, a, b, data) begin
        if (shift_enable) begin
            shift_reg.data <= data;
        end else begin
            shift_reg.data <= 1'b0;
        end

        if (bitwise_enable) begin
            bitwise_or.a <= a;
            bitwise_or.b <= b;
        end else begin
            bitwise_or.a <= 3'b0;
            bitwise_or.b <= 3'b0;
        end
    end

endmodule

