module state_machine(
    input [1:0] ain,
    input clk, reset,
    output reg yout
);

    reg [2:0] state, nextstate;
    parameter S0 = 0, S1 = 1, S2 = 2, S3 = 3, S4 = 4, S5 = 5, S6 = 6;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= S0;
            yout <= 0;
        end else begin
            state <= nextstate;
        end
    end

    always @(state or ain) begin
        case (state)
            S0: begin
                if (ain == 0) begin
                    nextstate = S0;
                end else if (ain == 1) begin
                    nextstate = S1;
                end else if (ain == 3) begin
                    nextstate = S2;
                end else begin
                    nextstate = S3;
                end
            end
            S1: begin
                if (ain == 0) begin
                    nextstate = S4;
                end else if (ain == 1) begin
                    nextstate = S1;
                end else if (ain == 3) begin
                    nextstate = S2;
                end else begin
                    nextstate = S3;
                end
            end
            S2: begin
                if (ain == 0) begin
                    nextstate = S5;
                end else if (ain == 1) begin
                    nextstate = S1;
                end else if (ain == 3) begin
                    nextstate = S2;
                end else begin
                    nextstate = S3;
                end
            end
            S3: begin
                if (ain == 0) begin
                    nextstate = S6;
                end else if (ain == 1) begin
                    nextstate = S1;
                end else if (ain == 3) begin
                    nextstate = S2;
                end else begin
                    nextstate = S3;
                end
            end
            S4: begin
                if (ain == 0) begin
                    nextstate = S0;
                end else if (ain == 1) begin
                    nextstate = S1;
                end else if (ain == 3) begin
                    nextstate = S2;
                end else begin
                    nextstate = S3;
                end
            end
            S5: begin
                if (ain == 0) begin
                    nextstate = S0;
                end else if (ain == 1) begin
                    nextstate = S1;
                end else if (ain == 3) begin
                    nextstate = S2;
                end else begin
                    nextstate = S3;
                end
            end
            S6: begin
                if (ain == 0) begin
                    nextstate = S0;
                end else if (ain == 1) begin
                    nextstate = S1;
                end else if (ain == 3) begin
                    nextstate = S2;
                end else begin
                    nextstate = S3;
                end
            end
        endcase
    end

    always @(state) begin
        case (state)
            S0, S1, S2, S3: begin
                yout = yout;
            end
            S4: begin
                yout = 0;
            end
            S5: begin
                yout = 1;
            end
            S6: begin
                yout = ~yout;
