module uart_rx (
    input clk,
    input rst,
    input m_axis_tready,
    input rxd,
    input [15:0] prescale,
    output reg [7:0] m_axis_tdata,
    output reg m_axis_tvalid,
    output reg busy,
    output reg overrun_error,
    output reg frame_error
);

reg [7:0] data_reg;
reg [3:0] state;

localparam IDLE = 2'b00;
localparam START_BIT = 2'b01;
localparam DATA_BITS = 2'b10;
localparam STOP_BIT = 2'b11;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        state <= IDLE;
        busy <= 0;
        overrun_error <= 0;
        frame_error <= 0;
        m_axis_tdata <= 0;
        m_axis_tvalid <= 0;
        data_reg <= 0;
    end else begin
        case (state)
            IDLE: begin
                if (!rxd) begin
                    state <= START_BIT;
                    busy <= 1;
                end
            end
            START_BIT: begin
                if (rxd) begin
                    state <= IDLE;
                    frame_error <= 1;
                    busy <= 0;
                end else begin
                    state <= DATA_BITS;
                end
            end
            DATA_BITS: begin
                data_reg <= {data_reg[6:0], rxd};
                if (m_axis_tready) begin
                    m_axis_tdata <= data_reg;
                    m_axis_tvalid <= 1;
                    state <= STOP_BIT;
                end
            end
            STOP_BIT: begin
                if (rxd) begin
                    state <= IDLE;
                    busy <= 0;
                end else begin
                    overrun_error <= 1;
                    state <= IDLE;
                    busy <= 0;
                end
            end
        endcase
    end
end

endmodule

