module four_bit_adder (A, B, Ci, S, Co);

  input [3:0] A, B;
  input Ci;
  output [3:0] S;
  output Co;

  wire [3:0] x, y, z;
  wire c1, c2, c3;

  // First bit
  XOR2 U1 (.A(A[0]), .B(B[0]), .ZN(x[0]));
  AND2 U2 (.A(A[0]), .B(B[0]), .ZN(c1));
  XOR2 U3 (.A(x[0]), .B(Ci), .ZN(S[0]));
  OR2 U4 (.A(c1), .B(Ci), .ZN(c2));

  // Second bit
  XOR2 U5 (.A(A[1]), .B(B[1]), .ZN(x[1]));
  AND2 U6 (.A(A[1]), .B(B[1]), .ZN(c1));
  XOR2 U7 (.A(x[1]), .B(c2), .ZN(z[1]));
  AND2 U8 (.A(x[1]), .B(c2), .ZN(c3));
  OR2 U9 (.A(c1), .B(c3), .ZN(c2));

  // Third bit
  XOR2 U10 (.A(A[2]), .B(B[2]), .ZN(x[2]));
  AND2 U11 (.A(A[2]), .B(B[2]), .ZN(c1));
  XOR2 U12 (.A(x[2]), .B(c2), .ZN(z[2]));
  AND2 U13 (.A(x[2]), .B(c2), .ZN(c3));
  OR2 U14 (.A(c1), .B(c3), .ZN(c2));

  // Fourth bit
  XOR2 U15 (.A(A[3]), .B(B[3]), .ZN(x[3]));
  AND2 U16 (.A(A[3]), .B(B[3]), .ZN(c1));
  XOR2 U17 (.A(x[3]), .B(c2), .ZN(z[3]));
  AND2 U18 (.A(x[3]), .B(c2), .ZN(c3));
  OR2 U19 (.A(c1), .B(c3), .ZN(Co));

  assign S = z;

endmodule

