module adder(
  input wire [3:0] A,
  input wire [3:0] B,
  input wire reset,
  output reg [4:0] sum
);

  wire [3:0] carry;

  assign carry[0] = A[0] & B[0];
  assign sum[0] = A[0] ^ B[0];

  genvar i;
  generate
    for (i = 1; i < 4; i = i + 1) begin
      assign carry[i] = (A[i] & B[i]) | (A[i] & carry[i-1]) | (B[i] & carry[i-1]);
      assign sum[i] = A[i] ^ B[i] ^ carry[i-1];
    end
  endgenerate

  assign sum[4] = carry[3];

  always @ (posedge clk) begin
    if (reset) begin
      sum <= 0;
    end
    else begin
      sum <= sum;
    end
  end

endmodule

module freq_counter (
  input wire CLK_IN1,
  input wire RESET,
  input wire COUNTER_RESET,
  output wire LOCKED,
  output wire COUNT,
  output reg CLK_OUT
);

  // Define constants
  localparam PER1 = 7.518;
  localparam COUNT_PHASE = 1024;

  // Define variables
  reg [9:0] count;
  reg [1:0] phase;
  reg locked;
  reg [9:0] count_phase;
  reg [31:0] time_count;

  // Generate the input clock signals
  reg CLK_IN1_1;
  reg CLK_IN1_2;
  always begin
    CLK_IN1_1 = #(PER1/2) ~CLK_IN1_1;
    CLK_IN1_2 = #(PER1/2) ~CLK_IN1_2;
    CLK_IN1 = CLK_IN1_1 ^ CLK_IN1_2;
  end

  // Generate the output clock signal
  always @(posedge CLK_IN1) begin
    if (phase == 2'b00) begin
      CLK_OUT <= 1'b0;
    end else if (phase == 2'b01) begin
      CLK_OUT <= 1'b1;
    end else if (phase == 2'b10) begin
      CLK_OUT <= 1'b0;
    end else begin // phase == 2'b11
      CLK_OUT <= 1'b1;
    end
  end

  // Count the number of clock cycles
  always @(posedge CLK_IN1) begin
    if (RESET) begin
      count <= 10'b0;
      phase <= 2'b00;
      locked <= 0;
      count_phase <= COUNT_PHASE;
      time_count <= 0;
    end else if (COUNTER_RESET) begin
      phase <= 2'b00;
      locked <= 0;
      count_phase <= COUNT_PHASE;
      time_count <= 0;
    end else if (phase == 2'b00 && !locked) begin
      count <= count + 10'b1;
      if (count == 10'b0) begin
        phase <= 2'b01;
      end
    end else if (phase == 2'b01 && !locked) begin
      if (count == 10'b0) begin
        phase <= 2'b10;
      end
    end else if (phase == 2'b10 && !locked) begin
      count <= count - 10'b1;
      if (count == count_phase - 10'b1) begin
        phase <= 2'b11;
      end
    end else if (phase == 2'b11 && !locked) begin
      if (count == count_phase - 10'b1) begin
        locked <= 1;
        time_count <= $time;
      end
    end else if (locked) begin
      if ($time - time_count >= COUNT_PHASE * PER1) begin
        locked <= 0;
        phase <= 2'b00;
        count <= 10'b0;
      end
    end
  end

  // Output the high bit of the sampling counter
  assign COUNT = count[9];

  // Output the locked signal
  assign LOCKED = locked;

endmodule

module vending_machine(
    input clk,
    input rst,
    input btn1,
    input btn2,
    input btn3,
    input [1:0] coin,
    input return,
    output dispense,
    output reg [1:0] change,
    output reg [3:0] display
);

parameter COFFEE_PRICE = 3'b011;
parameter TEA_PRICE = 3'b010;
parameter SODA_PRICE = 3'b001;

reg [2:0] bev_type;
reg [2:0] bev_price;
reg [2:0] bev_cost;
reg [2:0] bev_dispense;

reg [2:0] coin_cnt;
reg [2:0] coin_sum;
reg [2:0] coin_return;
reg [2:0] coin_dispense;

reg [2:0] state;
reg [2:0] next_state;

parameter IDLE = 3'b000;
parameter SELECT_BEVERAGE = 3'b001;
parameter INSERT_COIN = 3'b010;
parameter DISPENSE_BEVERAGE = 3'b011;
parameter RETURN_COIN = 3'b100;

always @(posedge clk) begin
    if (rst) begin
        bev_type <= 3'b000;
        bev_price <= 3'b000;
        bev_cost <= 3'b000;
        bev_dispense <= 3'b000;
        coin_cnt <= 3'b000;
        coin_sum <= 3'b000;
        coin_return <= 3'b000;
        coin_dispense <= 3'b000;
        state <= IDLE;
        next_state <= IDLE;
    end else begin
        state <= next_state;
    end
end

always @* begin
    case (state)
        IDLE: begin
            display = 4'b0000;
            change = 2'b00;
            dispense = 1'b0;
            if (btn1) begin
                bev_type = 3'b011;
                bev_price = COFFEE_PRICE;
                bev_cost = 3'b011;
                next_state = SELECT_BEVERAGE;
            end else if (btn2) begin
                bev_type = 3'b010;
                bev_price = TEA_PRICE;
                bev_cost = 3'b010;
                next_state = SELECT_BEVERAGE;
            end else if (btn3) begin
                bev_type = 3'b001;
                bev_price = SODA_PRICE;
                bev_cost = 3'b001;
                next_state = SELECT_BEVERAGE;
            end else begin
                next_state = IDLE;
            end
        end
        SELECT_BEVERAGE: begin
            display = {2'b00, bev_type};
            change = 2'b00;
            dispense = 1'b0;
            if (coin[1]) begin
                coin_cnt[2] <= coin_cnt[2] + 1;
                coin_sum[2] <= coin_sum[2] + 1;
            end else if (coin[0]) begin
                coin_cnt[1] <= coin_cnt[1] + 1;
                coin_sum[1] <= coin_sum[1] + 1;
            end else if (coin[0]) begin
                coin_cnt[0] <= coin_cnt[0] + 1;
                coin_sum[0] <= coin_sum[0] + 1;
            end
            if (coin_sum >= bev_price) begin
                next_state = DISPENSE_BEVERAGE;
            end else if (return) begin
                next_state = RETURN_COIN;
            end else begin
                next_state = INSERT_COIN;
            end
        end
        INSERT_COIN: begin
            display = {2'b01, bev_type};
            change = coin_sum - bev_price;
            dispense = 1'b0;
            if (coin[1]) begin
                coin_cnt[2] <= coin_cnt[2] + 1;
                coin_sum[2] <= coin_sum[2] + 1;
            end else if (coin[0]) begin
                coin_cnt[1] <= coin_cnt[1] + 1;
                coin_sum[1] <= coin_sum[1] + 1;
            end else if (coin[0]) begin
                coin_cnt[0] <= coin_cnt[0] + 1;
                coin_sum[0] <= coin_sum[0] + 1;
            end
            if (coin_sum >= bev_price) begin
                next_state = DISPENSE_BEVERAGE;
            end else if (return) begin
                next_state = RETURN_COIN;
            end else begin
                next_state = INSERT_COIN;
            end
        end
        DISPENSE_BEVERAGE: begin
            display = {2'b10, bev_type};
            change = coin_sum - bev_price;
            dispense = 1'b1;
            bev_dispense = bev_type;
            coin_dispense = coin_sum - bev_price;
            coin_return = coin_sum - bev_cost;
            next_state = RETURN_COIN;
        end
        RETURN_COIN: begin
            display = {2'b11, bev_type};
            change = 2'b00;
            dispense = 1'b0;
            bev_type = 3'b000;
            coin_cnt <= 3'b000;
            coin_sum <= 3'b000;
            if (coin_return[2]) begin
                coin_return[2] <= coin_return[2] - 1;
                coin_dispense[2] <= coin_dispense[2] - 1;
            end else if (coin_return[1]) begin
                coin_return[1] <= coin_return[1] - 1;
                coin_dispense[1] <= coin_dispense[1] - 1;
            end else if (coin_return[0]) begin
                coin_return[0] <= coin_return[0] - 1;
                coin_dispense[0] <= coin_dispense[0] - 1;
            end
            if (coin_return == 3'b000) begin
                next_state = IDLE;
            end else begin
                next_state = RETURN_COIN;
            end
        end
    endcase
end

endmodule

