module carry_lookahead_adder (
    input [7:0] a,
    input [7:0] b,
    output [7:0] s,
    output overflow
);

wire [7:0] g, p, c;
wire [6:0] c_out;

assign g = a & b;
assign p = a ^ b;
assign c[0] = 1'b0;

generate
    genvar i;
    for (i = 0; i < 7; i = i + 1) begin : carry_lookahead_adder_generate
        assign c[i+1] = g[i] | (p[i] & c[i]);
    end
endgenerate

assign s = a + b + c;
assign overflow = (a[7] == b[7]) && (a[7] != s[7]);

endmodule

