module shifter (
  input [n-1:0] in,
  input [1:0] ctrl,
  input [n-1:0] shift_amt,
  output [n-1:0] out
);

parameter n = 8; // number of bits in the input and output signals

reg [n-1:0] shifted_in; // register to hold the shifted input signal

// Left shift operation
always @(*) begin
  if (ctrl == 0) begin
    shifted_in = {in[shift_amt-1:0], {shift_amt{1'b0}}};
  end
  // Right shift operation
  else if (ctrl == 1) begin
    shifted_in = {{shift_amt{1'b0}}, in[n-shift_amt-1:0]};
  end
  // Arithmetic shift operation
  else if (ctrl == 2) begin
    shifted_in = {{shift_amt{in[n-1]}}, in[n-shift_amt-1:0]};
  end
end

// Assign the shifted input signal to the output
assign out = shifted_in;

endmodule

