module top_module (
    input clk,
    input [3:0] in,
    output [2:0] shift_out,
    output reg [1:0] pos
);

    // Priority Encoder
    wire [1:0] priority;
    assign priority = (in[3]) ? 2'b11 :
                      (in[2]) ? 2'b10 :
                      (in[1]) ? 2'b01 :
                      (in[0]) ? 2'b00 : 2'b00;

    // Shift Register
    reg [2:0] shift_reg;
    always @(posedge clk) begin
        shift_reg <= {shift_reg[1:0], in[0]};
    end
    assign shift_out = shift_reg;

    // Bitwise OR
    always @(*) begin
        case (priority)
            2'b00: pos = shift_reg[0:1];
            2'b01: pos = {shift_reg[1], shift_reg[0] | shift_reg[2]};
            2'b10: pos = {shift_reg[2], shift_reg[1] | shift_reg[0]};
            2'b11: pos = shift_reg[1:2];
        endcase
    end

endmodule

module d_ff (
    input clk,    // Clock input
    input d,      // Data input
    output q      // Output of the D flip-flop
);

    wire s, r;      // Set and reset signals for the SR latch
    wire q_buf;     // Output of the clocked buffer

    // Set and reset signals for the SR latch
    assign s = d;
    assign r = ~d;

    // Clocked buffer
    bufif0 buf (q_buf, 1'b0, clk);

    // SR latch
    nand n1 (s, q_buf, r);
    nand n2 (r, q_buf, s);

    // Output of the D flip-flop
    assign q = q_buf;

endmodule

module shift_register (
    input clk,        // Clock input
    input [2:0] d_in, // Data input
    output reg [2:0] q_out   // Output of the shift register
);

    always @(posedge clk) begin
        // Shift the register
        q_out[2] <= q_out[1];
        q_out[1] <= q_out[0];
        q_out[0] <= d_in;
    end

endmodule

