module top_module (
    input clk,    // Clock input
    input d,      // Data input
    output q_shift,  // Output of the shift register
    output q_xor  // Output of the XOR module
);

    wire d_ff_out;      // Output of the D flip-flop
    wire [2:0] sr_out;  // Output of the shift register

    // Instantiate the D flip-flop
    d_ff d_ff_inst (clk, d, d_ff_out);

    // Instantiate the shift register
    shift_register sr_inst (clk, d_ff_out, sr_out);

    // Instantiate the XOR module
    xor_module xor_inst (d_ff_out, sr_out[2], q_xor);

    // Output of the shift register
    assign q_shift = sr_out[2];

endmodule

module fifo_generator_ramfifo
   (dout,
    empty,
    full,
    rd_en,
    wr_en,
    rd_clk,
    wr_clk,
    din,
    rst);

  output [255:0] dout;
  output empty;
  output full;
  input rd_en;
  input wr_en;
  input rd_clk;
  input wr_clk;
  input [255:0] din;
  input rst;

  reg [255:0] fifo [0:255]; // FIFO buffer
  reg [7:0] wr_ptr = 0; // write pointer
  reg [7:0] rd_ptr = 0; // read pointer
  reg [7:0] count = 0; // number of elements in the FIFO

  wire [7:0] next_wr_ptr = wr_ptr + 1; // next write pointer
  wire [7:0] next_rd_ptr = rd_ptr + 1; // next read pointer
  wire [7:0] next_count = count + wr_en - rd_en; // next number of elements in the FIFO

  assign empty = (count == 0);
  assign full = (count == 256);

  always @(posedge wr_clk) begin
    if (wr_en && !full) begin
      fifo[wr_ptr] <= din;
      wr_ptr <= next_wr_ptr;
      count <= next_count;
    end
  end

  always @(posedge rd_clk) begin
    if (rd_en && !empty) begin
      dout <= fifo[rd_ptr];
      rd_ptr <= next_rd_ptr;
      count <= next_count;
    end
  end

  always @(posedge wr_clk or posedge rd_clk or posedge rst) begin
    if (rst) begin
      wr_ptr <= 0;
      rd_ptr <= 0;
      count <= 0;
    end
  end

endmodule

module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [31:0]  data_out
);

reg [7:0] buffer [0:3];
reg [31:0] acc [0:3];
reg [1:0] stage;
wire [1:0] next_stage;

assign next_stage = (stage == 2'b11) ? 2'b00 : stage + 1'b1;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        buffer <= 8'b0;
        acc <= 32'b0;
        stage <= 2'b00;
        valid_b <= 1'b0;
        data_out <= 32'b0;
    end else begin
        case (stage)
            2'b00: begin
                if (valid_a && ready_b) begin
                    buffer[0] <= data_in;
                    stage <= next_stage;
                end
            end
            2'b01: begin
                if (valid_a && ready_b) begin
                    buffer[1] <= data_in;
                    stage <= next_stage;
                end
            end
            2'b10: begin
                if (valid_a && ready_b) begin
                    buffer[2] <= data_in;
                    stage <= next_stage;
                end
            end
            2'b11: begin
                if (valid_a && ready_b) begin
                    buffer[3] <= data_in;
                    stage <= next_stage;
                end
            end
        endcase
    end
end

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        acc <= 32'b0;
    end else begin
        case (stage)
            2'b00: begin
                acc[0] <= acc[0] + buffer[0];
            end
            2'b01: begin
                acc[1] <= acc[1] + buffer[1];
            end
            2'b10: begin
                acc[2] <= acc[2] + buffer[2];
            end
            2'b11: begin
                acc[3] <= acc[3] + buffer[3];
            end
        endcase
    end
end

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        data_out <= 32'b0;
        valid_b <= 1'b0;
    end else begin
        case (stage)
            2'b00: begin
                data_out <= acc[0];
                valid_b <= 1'b1;
            end
            2'b01: begin
                data_out <= acc[1];
                valid_b <= 1'b1;
            end
            2'b10: begin
                data_out <= acc[2];
                valid_b <= 1'b1;
            end
            2'b11: begin
                data_out <= acc[3];
                valid_b <= 1'b1;
            end
        endcase
    end
end

assign ready_a = (stage == 2'b11) ? 1'b1 : 1'b0;

endmodule

