module round_and_saturation (
  input signed [width-1:0] data_in,
  input signed [width-1:0] max_val,
  input signed [width-1:0] min_val,
  output reg signed [width-1:0] data_out
);

parameter width = 16; // width of the fixed-point number
parameter scale = 8; // number of fractional bits in the fixed-point number

real float_in;
real float_rounded;
real float_max;
real float_min;

always @(*) begin
  float_in = data_in / (2 ** scale);
  float_rounded = round(float_in);
  data_out = $signed(float_rounded * (2 ** scale));
  float_max = max_val / (2 ** scale);
  float_min = min_val / (2 ** scale);

  if (float_rounded > float_max) begin
    data_out = $signed(float_max * (2 ** scale));
  end

  if (float_rounded < float_min) begin
    data_out = $signed(float_min * (2 ** scale));
  end
end

endmodule

module full_adder_4bit (
    input [3:0] A,
    input [3:0] B,
    input [3:0] Cin,
    input Rst,
    output [3:0] Sum,
    output Cout
);

    wire [3:0] S;
    wire C1, C2, C3;

    // 1-bit full adder
    // Generates Sum and Cout for a single bit
    // Inputs: A, B, Cin
    // Outputs: S, Cout
    // Cout = A&B | A&Cin | B&Cin
    // S = A^B^Cin
    // Where ^ is XOR and & is AND

    // First bit
    full_adder_1bit fa1bit_0 (
        .A(A[0]),
        .B(B[0]),
        .Cin(Cin[0]),
        .S(S[0]),
        .Cout(C1)
    );

    // Second bit
    full_adder_1bit fa1bit_1 (
        .A(A[1]),
        .B(B[1]),
        .Cin(C1),
        .S(S[1]),
        .Cout(C2)
    );

    // Third bit
    full_adder_1bit fa1bit_2 (
        .A(A[2]),
        .B(B[2]),
        .Cin(C2),
        .S(S[2]),
        .Cout(C3)
    );

    // Fourth bit
    full_adder_1bit fa1bit_3 (
        .A(A[3]),
        .B(B[3]),
        .Cin(C3),
        .S(S[3]),
        .Cout(Cout)
    );

    // Reset
    assign Sum = Rst ? 4'b0000 : S;
    assign Cout = Rst ? 1'b0 : Cout;

endmodule


module full_adder_1bit (
    input A,
    input B,
    input Cin,
    output S,
    output Cout
);

    // Cout = A&B | A&Cin | B&Cin
    // S = A^B^Cin
    // Where ^ is XOR and & is AND

    assign Cout = (A & B) | (A & Cin) | (B & Cin);
    assign S = A ^ B ^ Cin;

endmodule

