module priority_encoder (
    input [3:0] in,     // 4-bit input to be encoded
    output reg [1:0] out // 2-bit output after encoding
);

    always @(*) begin
        case (in)
            4'b0001: out = 2'b00;
            4'b0010: out = 2'b01;
            4'b0100: out = 2'b10;
            4'b1000: out = 2'b11;
            default: out = 2'b00;
        endcase
    end

endmodule

module final_module (
    input clk,          // clock input
    input reset,        // synchronous active-high reset
    input [7:0] in,     // 8-bit input for the barrel shifter
    output reg [3:0] out // 4-bit output from the priority encoder
);

    reg [7:0] shifted_in; // 8-bit output from the barrel shifter

    barrel_shifter bs(
        .in(in),
        .out(shifted_in)
    );

    priority_encoder pe(
        .in(shifted_in[3:0]),
        .out(out)
    );

    always @(posedge clk) begin
        if (reset) begin
            out <= 4'b0000;
        end else begin
            out <= {2'b00, pe.out};
        end
    end

endmodule

module frequency_divider (
  input clk,
  input reset,
  input data,
  output reg pulse
);

  parameter PRESET_VALUE = 100; // Change this value to adjust the output frequency

  reg [PRESET_VALUE-1:0] shift_reg;
  reg [7:0] counter = 8'd0;

  always @(posedge clk) begin
    if (reset) begin
      shift_reg <= 0;
      counter <= 0;
      pulse <= 0;
    end else begin
      shift_reg <= {data, shift_reg[PRESET_VALUE-2:0]};
      counter <= counter + 1;
      if (counter == PRESET_VALUE-1) begin
        counter <= 0;
        pulse <= ~pulse;
      end
    end
  end

endmodule

