    assign nand1 = ~(a & b);
    assign nand2 = ~(a & nand1);
    assign nand3 = ~(b & nand1);

    assign sum = ~(nand2 & nand3);
    assign cout = ~(nand1 & nand3);

endmodule

module bcd_counter (
    input clk,
    input sync_reset,
    input async_reset,
    output [3:1] ena,
    output reg [15:0] q);

    reg [3:0] johnson;
    reg [3:1] bcd;

    always @(posedge clk or posedge async_reset) begin
        if (async_reset) begin
            johnson <= 4'b0001;
            bcd <= 3'b000;
            q <= 16'b0000000000000000;
        end else if (sync_reset) begin
            johnson <= 4'b0001;
            bcd <= 3'b000;
        end else begin
            johnson <= {johnson[2:0], ~johnson[3]};
            if (ena[3]) begin
                if (johnson[3]) begin
                    bcd[2] <= ~bcd[2];
                end
            end
            if (ena[2]) begin
                if (bcd[2]) begin
                    if (bcd[1]) begin
                        bcd[1] <= 0;
                        bcd[0] <= ~bcd[0];
                    end else begin
                        bcd[1] <= 1;
                    end
                end else begin
                    if (bcd[1]) begin
                        bcd[1] <= 0;
                        bcd[0] <= ~bcd[0];
                    end else begin
                        bcd[0] <= ~bcd[0];
                    end
                end
            end
        end
    end

    assign ena = {1'b0, bcd};
    assign q[3:0] = johnson;
    assign q[15:4] = {4'b0000, bcd};

endmodule

