module top_module (
    input clk,
    input reset,
    input [1:0] enable,
    output [5:0] count
);

    // Instantiate the 4-bit counter module
    counter_4bit counter_inst (
        .clk(clk),
        .reset(reset),
        .count(count[3:0])
    );

    // Instantiate the 2-bit up/down counter module
    up_down_counter_2bit up_down_inst (
        .clk(clk),
        .reset(enable[1]),
        .enable(enable[0]),
        .count(count[5:4])
    );

    // Connect the enable input of the up/down counter to the carry-out bit of the 4-bit counter
    assign enable[0] = (count == 6'hF) ? 1'b1 : 1'b0;

    // Concatenate the outputs of the two counters to create the 6-bit counter output
    assign count = {up_down_inst.count, counter_inst.count};

endmodule

