module counter_4bit (
    input clk,
    input reset,
    output reg [3:0] count
);

    always @(posedge clk) begin
        if (reset) begin
            count <= 4'b0;
        end else begin
            count <= (count == 4'hF) ? 4'b0 : count + 1;
        end
    end

endmodule

// 2-bit up/down counter module with asynchronous reset and enable
module up_down_counter_2bit (
    input clk,
    input reset,
    input enable,
    output reg [1:0] count
);

    always @(posedge clk) begin
        if (reset) begin
            count <= 2'b0;
        end else if (enable) begin
            count <= (count == 2'h3) ? 2'b0 : count + 1;
        end
    end

endmodule

