module booth_multiplier (
    input clk,
    input reset,
    input signed [7:0] a,
    input signed [7:0] b,
    input select,
    output reg signed [15:0] result
);

reg signed [7:0] m;
reg signed [7:0] ac;
reg signed [3:0] count;

always @(posedge clk) begin
    if (reset) begin
        m <= 8'b0;
        ac <= {a, 4'b0};
        count <= 4'b0;
        result <= 16'b0;
    end else begin
        if (count == 4'b0) begin
            m <= b;
            count <= 4'b1;
        end else begin
            case ({ac[3], ac[2]}) 
                2'b01: ac <= ac + m;
                2'b10: ac <= ac - m;
                2'b11: ac <= ac >> 1;
            endcase
            count <= count + 1;
        end
    end
end

always @(posedge clk) begin
    if (reset) begin
        result <= 16'b0;
    end else begin
        if (select == 1) begin
            result <= ac[15:8];
        end else begin
            result <= ac;
        end
    end
end

endmodule

