  input [3:0] B,
  input mode,
  output [3:0] Y
);

  wire [3:0] B_neg;
  assign B_neg = (~B) + 1;

  always @(*) begin
    if (mode == 0) begin
      Y = A + B;
    end else begin
      Y = A + B_neg;
    end
  end

endmodule

module fifo_buffer (
    input clk,
    input rst,
    input wr_en,
    input rd_en,
    input [15:0] data_in,
    output [15:0] data_out,
    output empty,
    output full,
    output reg [3:0] count
);

parameter DEPTH = 16;
reg [15:0] buffer [0:DEPTH-1];
reg [3:0] head = 4'b0000;
reg [3:0] tail = 4'b0000;
reg [3:0] next_head;
reg [3:0] next_tail;

always @(posedge clk) begin
    if (rst) begin
        head <= 4'b0000;
        tail <= 4'b0000;
        count <= 4'b0000;
    end else begin
        next_head = head;
        next_tail = tail;
        if (wr_en & ~full) begin
            buffer[head] <= data_in;
            next_head = (head == DEPTH-1) ? 4'b0000 : head + 1;
            count <= count + 1;
        end
        if (rd_en & ~empty) begin
            data_out <= buffer[tail];
            next_tail = (tail == DEPTH-1) ? 4'b0000 : tail + 1;
            count <= count - 1;
        end
        head <= next_head;
        tail <= next_tail;
    end
end

assign empty = (count == 0);
assign full = (count == DEPTH);

endmodule

