module ad9467_spi (

  spi_csn,
  spi_clk,
  spi_mosi,
  spi_miso,

  spi_sdio);

  // 4 wire

  input   [1:0] spi_csn;
  input         spi_clk;
  input         spi_mosi;
  output        spi_miso;

  // 3 wire

  inout         spi_sdio;

  // internal registers

  reg     [5:0] spi_count = 6'd0;
  reg           spi_rd_wr_n = 1'd0;
  reg           spi_enable = 1'd0;

  // internal signals

  wire          spi_csn_s;
  wire          spi_enable_s;

  // check on rising edge and change on falling edge

  assign spi_csn_s = &spi_csn;
  assign spi_enable_s = spi_enable & ~spi_csn_s;

  always @(posedge spi_clk or posedge spi_csn_s) begin
    if (spi_csn_s == 1'b1) begin
      spi_count <= 6'd0;
      spi_rd_wr_n <= 1'd0;
    end else begin
      spi_count <= spi_count + 1'b1;
      if (spi_count == 6'd0) begin
        spi_rd_wr_n <= spi_mosi;
      end
    end
  end

  always @(negedge spi_clk or posedge spi_csn_s) begin
    if (spi_csn_s == 1'b1) begin
      spi_enable <= 1'b0;
    end else begin
      if (spi_count == 6'd16) begin
        spi_enable <= spi_rd_wr_n;
      end
    end
  end

  // io buffer

  IOBUF i_iobuf_sdio (
    .T (spi_enable_s),
    .I (spi_mosi),
    .O (spi_miso),
    .IO (spi_sdio));

endmodule

