module pipelined_decoder_2to4(
    input wire [1:0] A, B,
    output reg [3:0] Y0, Y1, Y2, Y3
);

reg [1:0] stage1_A, stage1_B;
reg [1:0] stage2_A, stage2_B;

always @(posedge clk) begin
    stage1_A <= A;
    stage1_B <= B;
    stage2_A <= stage1_A;
    stage2_B <= stage1_B;
end

always @(posedge clk) begin
    case (stage2_A)
        2'b00: begin
            Y0 <= 1'b1;
            Y1 <= 1'b0;
            Y2 <= 1'b0;
            Y3 <= 1'b0;
        end
        2'b01: begin
            Y0 <= 1'b0;
            Y1 <= 1'b1;
            Y2 <= 1'b0;
            Y3 <= 1'b0;
        end
        2'b10: begin
            Y0 <= 1'b0;
            Y1 <= 1'b0;
            Y2 <= 1'b1;
            Y3 <= 1'b0;
        end
        2'b11: begin
            Y0 <= 1'b0;
            Y1 <= 1'b0;
            Y2 <= 1'b0;
            Y3 <= 1'b1;
        end
    endcase
end

endmodule

module fifo_module (
  input clk,
  input reset_n,
  input wr,
  input [7:0] wr_data,
  input rd,
  output [7:0] rd_data,
  output empty,
  output full
);

  parameter DEPTH = 4;
  parameter ADDR_WIDTH = $clog2(DEPTH);

  reg [7:0] fifo[0:DEPTH-1];
  reg [ADDR_WIDTH-1:0] wr_ptr;
  reg [ADDR_WIDTH-1:0] rd_ptr;
  reg [ADDR_WIDTH-1:0] num_entries;

  assign empty = (num_entries == 0);
  assign full = (num_entries == DEPTH);

  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      wr_ptr <= 0;
      rd_ptr <= 0;
      num_entries <= 0;
    end else begin
      if (wr && ~full) begin
        fifo[wr_ptr] <= wr_data;
        wr_ptr <= wr_ptr + 1;
        num_entries <= num_entries + 1;
      end
      if (rd && ~empty) begin
        rd_data <= fifo[rd_ptr];
        rd_ptr <= rd_ptr + 1;
        num_entries <= num_entries - 1;
      end
    end
  end

endmodule

