    // Instantiate 2-to-1 multiplexers
    mux2to1 mux0(.a(in[3:0]), .b(in[7:4]), .s(decoder_out[0]), .y(mux_out[0]));
    mux2to1 mux1(.a(in[11:8]), .b(in[15:12]), .s(decoder_out[1]), .y(mux_out[1]));
    mux2to1 mux2(.a(in[19:16]), .b(in[23:20]), .s(decoder_out[2]), .y(mux_out[2]));
    mux2to1 mux3(.a(in[27:24]), .b(in[31:28]), .s(decoder_out[3]), .y(mux_out[3]));
    mux2to1 mux4(.a(in[35:32]), .b(in[39:36]), .s(decoder_out[4]), .y(mux_out[4]));
