module addsub (
    A,
    B,
    S,
    X,
    V
);

    input [3:0] A;
    input [3:0] B;
    input S;
    output [3:0] X;
    output V;

    wire [3:0] sum;
    wire [3:0] diff;

    // Full Adder
    assign sum[0] = A[0] ^ B[0] ^ S;
    assign V = (A[0] & B[0]) | (A[0] & S) | (B[0] & S);
    assign sum[1] = A[1] ^ B[1] ^ sum[0];
    assign V = V | ((A[1] & B[1]) | (A[1] & sum[0]) | (B[1] & sum[0]));
    assign sum[2] = A[2] ^ B[2] ^ sum[1];
    assign V = V | ((A[2] & B[2]) | (A[2] & sum[1]) | (B[2] & sum[1]));
    assign sum[3] = A[3] ^ B[3] ^ sum[2];
    assign V = V | ((A[3] & B[3]) | (A[3] & sum[2]) | (B[3] & sum[2]));

    // Full Subtractor
    assign diff[0] = A[0] ^ B[0] ^ S;
    assign V = V | (~A[0] & B[0] & S) | (~A[0] & ~B[0] & ~S) | (A[0] & B[0] & ~S);
    assign diff[1] = A[1] ^ B[1] ^ diff[0];
    assign V = V | (~A[1] & B[1] & diff[0]) | (~A[1] & ~B[1] & ~diff[0]) | (A[1] & B[1] & ~diff[0]);
    assign diff[2] = A[2] ^ B[2] ^ diff[1];
    assign V = V | (~A[2] & B[2] & diff[1]) | (~A[2] & ~B[2] & ~diff[1]) | (A[2] & B[2] & ~diff[1]);
    assign diff[3] = A[3] ^ B[3] ^ diff[2];
    assign V = V | (~A[3] & B[3] & diff[2]) | (~A[3] & ~B[3] & ~diff[2]) | (A[3] & B[3] & ~diff[2]);

    // Mux for selecting the output
    assign X = (S == 0) ? sum : diff;

