reg [s-1:0] next_state;

// Define the priority encoder module
priority_encoder pe (
  .in(in),
  .out(priority)
);

always @ (current_state or in) begin
  case (current_state)
    // Define the states and their corresponding next states and outputs
    3'b000: begin // State 0
      if (priority == 2'b10) begin
        next_state = 3'b001;
        out = 2'b10;
      end else if (priority == 2'b01) begin
        next_state = 3'b010;
        out = 2'b01;
      end else begin
        next_state = 3'b000;
        out = 2'b00;
      end
    end
    3'b001: begin // State 1
      if (priority == 2'b10) begin
        next_state = 3'b010;
        out = 2'b01;
      end else if (priority == 2'b01) begin
        next_state = 3'b011;
        out = 2'b00;
      end else begin
        next_state = 3'b001;
        out = 2'b10;
      end
    end
    3'b010: begin // State 2
      if (priority == 2'b10) begin
        next_state = 3'b011;
        out = 2'b00;
      end else if (priority == 2'b01) begin
        next_state = 3'b100;
        out = 2'b10;
      end else begin
        next_state = 3'b010;
        out = 2'b01;
      end
    end
    3'b011: begin // State 3
      if (priority == 2'b10) begin
        next_state = 3'b100;
        out = 2'b10;
      end else if (priority == 2'b01) begin
        next_state = 3'b101;
        out = 2'b01;
      end else begin
        next_state = 3'b011;
        out = 2'b00;
      end
    end
    3'b100: begin // State 4
      if (priority == 2'b10) begin
        next_state = 3'b101;
        out = 2'b01;
      end else if (priority == 2'b01) begin
        next_state = 3'b110;
        out = 2'b10;
      end else begin
        next_state = 3'b100;
        out = 2'b00;
      end
    end
    3'b101: begin // State 5
      if (priority == 2'b10) begin
        next_state = 3'b110;
        out = 2'b10;
      end else if (priority == 2'b01) begin
        next_state = 3'b111;
        out = 2'b01;
      end else begin
        next_state = 3'b101;
        out = 2'b00;
      end
    end
    3'b110: begin // State 6
      if (priority == 2'b10) begin
        next_state = 3'b111;
        out = 2'b01;
      end else if (priority == 2'b01) begin
        next_state = 3'b000;
        out = 2'b10;
      end else begin
        next_state = 3'b110;
        out = 2'b00;
      end
    end
    3'b111: begin // State 7
      if (priority == 2'b10) begin
        next_state = 3'b000;
        out = 2'b10;
      end else if (priority == 2'b01) begin
        next_state = 3'b001;
        out = 2'b01;
      end else begin
        next_state = 3'b111;
        out = 2'b00;
      end
    end
  endcase
end

always @ (next_state) begin
  current_state = next_state;
end

// Define the done signal
assign done = (current_state == 3'b111);

endmodule

