module debouncer (
  input in,
  output reg out
);

parameter n = 4; // number of bits used to represent the counter
parameter max_count = 10; // maximum value for the counter

reg [n-1:0] count;
reg last_in;

always @(posedge in) begin
  if (in != last_in) begin
    count <= 0;
  end else if (count == max_count-1) begin
    out <= in;
  end else begin
    count <= count + 1;
  end
  last_in <= in;
end

endmodule

module barrel_shifter (
    input [3:0] A,
    input [3:0] B,
    input DIR,
    input [1:0] AMT,
    output [3:0] S
);

reg [3:0] A_reg1, A_reg2, A_reg3, A_reg4;
reg [3:0] B_reg1, B_reg2, B_reg3, B_reg4;
reg [1:0] AMT_reg1, AMT_reg2, AMT_reg3;
reg DIR_reg1, DIR_reg2;

always @(*) begin
    A_reg1 = A;
    B_reg1 = B;
    AMT_reg1 = AMT;
    DIR_reg1 = DIR;
end

pipeline_stage1 stage1 (
    .A(A_reg1),
    .B(B_reg1),
    .AMT(AMT_reg1),
    .DIR(DIR_reg1),
    .A_reg2(A_reg2),
    .B_reg2(B_reg2),
    .AMT_reg2(AMT_reg2),
    .DIR_reg2(DIR_reg2)
);

pipeline_stage2 stage2 (
    .A(A_reg2),
    .B(B_reg2),
    .AMT(AMT_reg2),
    .DIR(DIR_reg2),
    .A_reg3(A_reg3),
    .B_reg3(B_reg3),
    .AMT_reg3(AMT_reg3)
);

pipeline_stage3 stage3 (
    .A(A_reg3),
    .B(B_reg3),
    .AMT(AMT_reg3),
    .S(S)
);

endmodule

module pipeline_stage1 (
    input [3:0] A,
    input [3:0] B,
    input [1:0] AMT,
    input DIR,
    output [3:0] A_reg2,
    output [3:0] B_reg2,
    output [1:0] AMT_reg2,
    output DIR_reg2
);

reg [3:0] A_reg1, B_reg1;
reg [1:0] AMT_reg1;
reg DIR_reg1;

always @(*) begin
    A_reg1 = A;
    B_reg1 = B;
    AMT_reg1 = AMT;
    DIR_reg1 = DIR;
end

assign A_reg2 = A_reg1 << AMT_reg1;
assign B_reg2 = B_reg1 >> (4 - AMT_reg1);
assign AMT_reg2 = AMT_reg1 - 1;
assign DIR_reg2 = DIR_reg1;

endmodule

module pipeline_stage2 (
    input [3:0] A,
    input [3:0] B,
    input [1:0] AMT,
    input DIR,
    output [3:0] A_reg3,
    output [3:0] B_reg3,
    output [1:0] AMT_reg3
);

reg [3:0] A_reg2, B_reg2;
reg [1:0] AMT_reg2;

always @(*) begin
    A_reg2 = A;
    B_reg2 = B;
    AMT_reg2 = AMT;
end

assign A_reg3 = A_reg2 << AMT_reg2;
assign B_reg3 = B_reg2 >> (4 - AMT_reg2);
assign AMT_reg3 = AMT_reg2 - 1;

endmodule

module pipeline_stage3 (
    input [3:0] A,
    input [3:0] B,
    input [1:0] AMT,
    output [3:0] S
);

reg [3:0] A_reg3, B_reg3;

always @(*) begin
    A_reg3 = A;
    B_reg3 = B;
end

assign S = (AMT == 0) ? A_reg3 : (DIR == 0) ? (A_reg3 << AMT) | (B_reg3 >> (4 - AMT)) : (A_reg3 >> AMT) | (B_reg3 << (4 - AMT));

endmodule

module top_module (
    input clk,
    input rst_n,
    input up_down,
    input [3:0] load_data,
    input [1:0] SHIFT,
    output reg [3:0] data_out,
    output reg overflow
);

reg [3:0] count;
reg [3:0] shifted_count;
wire [3:0] and_output;

// Up/Down Counter Module
always @(posedge clk) begin
    if (!rst_n) begin
        count <= 4'b0000;
    end else if (up_down) begin
        count <= count + 4'b0001;
    end else begin
        count <= count - 4'b0001;
    end

    if (load) begin
        count <= load_data;
    end
end

// Barrel Shifter Module
always @(posedge clk) begin
    if (!rst_n) begin
        shifted_count <= 4'b0000;
    end else begin
        case (SHIFT)
            2'b00: shifted_count <= count << 1;
            2'b01: shifted_count <= count >> 1;
            2'b10: shifted_count <= count << 2;
            2'b11: shifted_count <= count >> 2;
        endcase
    end
end

// AND Module
assign and_output = shifted_count & count;
assign data_out = and_output;

// Overflow Control Logic Module
always @(posedge clk) begin
    if (!rst_n) begin
        overflow <= 1'b0;
    end else if (count == 4'b1111 && up_down) begin
        overflow <= 1'b1;
    end else if (count == 4'b0000 && !up_down) begin
        overflow <= 1'b1;
    end else begin
        overflow <= 1'b0;
    end
end

endmodule

module spdu_7 ( 
