  assign out2 = ~(in0 | in1) & d2;
  assign out1 = ~(in2 | in3) & d1;
  assign out0 = ~(in0 | in1) & d0;

  // Implementing flip-flops
  DFFPOSX1 out3_reg ( .D(out3), .CLK(clk), .Q(out3) );
  DFFPOSX1 out2_reg ( .D(out2), .CLK(clk), .Q(out2) );
