  // Implementing NOR gates for reset signal
  NOR2X1 U37 ( .A(reset), .B(n1), .Y(out3) );
  NOR2X1 U39 ( .A(reset), .B(n2), .Y(out2) );
  NOR2X1 U41 ( .A(reset), .B(n3), .Y(out1) );
