module peripheral_mult(clk, rst, d_in, cs, addr, rd, wr, d_out);

  input clk;
  input rst;
  input [15:0] d_in;
  input cs;
  input [3:0] addr; // 4 LSB from j1_io_addr
  input rd;
  input wr;
  output reg [15:0] d_out;

  //------------------------------------ regs and wires-------------------------------

  reg [5:0] s; //selector mux_4  and write registers

  reg [15:0] A = 0; //---mult_32 input registers
  reg [15:0] B = 0;
  reg init = 0;

  wire [31:0] pp; //mult_32 output Regs
  wire done;

  //------------------------------------ regs and wires-------------------------------

  always @(*) begin //------address_decoder------------------------------
    case (addr)
      4'h0: begin s = (cs && wr) ? 6'b000001 : 6'b000000 ; end //A
      4'h2: begin s = (cs && wr) ? 6'b000010 : 6'b000000 ; end //B
      4'h4: begin s = (cs && wr) ? 6'b000100 : 6'b000000 ; end //init

      4'h6: begin s = (cs && rd) ? 6'b001000 : 6'b000000 ; end //done
      4'h8: begin s = (cs && rd) ? 6'b010000 : 6'b000000 ; end //pp[31:16]
      4'hA: begin s = (cs && rd) ? 6'b100000 : 6'b000000 ; end //pp[15:0]
      default: begin s = 6'b000000 ; end
    endcase
  end //------------------address_decoder--------------------------------

  always @(negedge clk) begin //-------------------- escritura de registros 

    A = (s[0]) ? d_in : A; //Write Registers
    B = (s[1]) ? d_in : B; //Write Registers
    init = s[2] ; // (s[2]) ? d_in : init; //Write Registers

  end //------------------------------------------- escritura de registros

  always @(negedge clk) begin //-----------------------mux_4 :  multiplexa salidas del periferico
    case (s[5:3])
      3'b001: d_out[0] = done;
      3'b010: d_out = pp[31:16];
      3'b100: d_out = pp[15:0];
      default: d_out = 0;
    endcase
  end //-----------------------------------------------mux_4

  mult_32 mt_32 ( .clk(clk), .rst(rst), .A(A), .B(B), .init(init), .pp(pp), .done(done) );

endmodule

module traffic_light_controller (
  input clk,
  input reset,
  output reg green,
  output reg yellow,
  output reg red
);

  // define the states
  localparam [1:0] GREEN = 2'b00;
  localparam [1:0] YELLOW = 2'b01;
  localparam [1:0] RED = 2'b10;

  // define the state register and initialize to GREEN
  reg [1:0] state_reg = GREEN;

  // define the counter for each state
  reg [3:0] green_counter = 4'd0;
  reg [3:0] yellow_counter = 4'd0;
  reg [3:0] red_counter = 4'd0;

  always @(posedge clk) begin
    if (reset) begin
      state_reg <= GREEN;
      green_counter <= 4'd0;
      yellow_counter <= 4'd0;
      red_counter <= 4'd0;
      green <= 1'b1;
      yellow <= 1'b0;
      red <= 1'b0;
    end
    else begin
      case (state_reg)
        GREEN: begin
          green_counter <= green_counter + 1;
          if (green_counter == 4'd9) begin
            state_reg <= YELLOW;
            green_counter <= 4'd0;
            yellow <= 1'b1;
            green <= 1'b0;
          end
        end
        YELLOW: begin
          yellow_counter <= yellow_counter + 1;
          if (yellow_counter == 4'd1) begin
            state_reg <= RED;
            yellow_counter <= 4'd0;
            red <= 1'b1;
            yellow <= 1'b0;
          end
        end
        RED: begin
          red_counter <= red_counter + 1;
          if (red_counter == 4'd7) begin
            state_reg <= GREEN;
            red_counter <= 4'd0;
            green <= 1'b1;
            red <= 1'b0;
          end
        end
      endcase
    end
  end

endmodule

