module d_ff_async_set_reset (
  input CLK,
  input D,
  input SET,
  input RESET,
  output Q,
  output QN
);

  reg Q;
  wire QN;

  always @(posedge CLK or negedge SET or negedge RESET) begin
    if (!SET) begin
      Q <= 1'b1;
    end else if (!RESET) begin
      Q <= 1'b0;
    end else begin
      Q <= D;
    end
  end

  assign QN = ~Q;

endmodule

module true_dual_port_ram (
