    input [3:0] write_data,
    input write_en,
    input [2:0] read_addr,
    output reg [3:0] read_data,
    input read_en
);

    reg [3:0] ram [0:7];

    always @(posedge clk) begin
        if (write_en) begin
            ram[write_addr] <= write_data;
        end
        if (read_en) begin
