module address_decoder (
    input [2:0] control,
    input [3:0] operand_1,
    input [3:0] operand_2,
    output reg [3:0] result,
    output reg write_en,
    output reg read_en,
    output reg [2:0] write_addr,
    output reg [2:0] read_addr
);

    reg [3:0] operand_1_reg;
    reg [3:0] operand_2_reg;
    reg [3:0] result_reg;

    true_dual_port_ram ram (
        .clk(clk),
        .write_addr(write_addr),
        .write_data(operand_1_reg),
        .write_en(write_en),
        .read_addr(read_addr),
        .read_data(operand_2_reg),
        .read_en(read_en)
    );

    always @(posedge clk) begin
        operand_1_reg <= operand_1;
        operand_2_reg <= operand_2;

        case (control)
            3'b000: begin
                result_reg <= operand_1_reg & operand_2_reg;
            end
            3'b001: begin
                result_reg <= operand_1_reg | operand_2_reg;
            end
            3'b010: begin
                result_reg <= operand_1_reg ^ operand_2_reg;
            end
            3'b011: begin
                result_reg <= ~operand_1_reg;
            end
            3'b100: begin
                result_reg <= operand_1_reg << 1;
            end
            3'b101: begin
                result_reg <= operand_1_reg >> 1;
            end
            3'b110: begin
                result_reg <= operand_1_reg + operand_2_reg;
            end
            3'b111: begin
                result_reg <= operand_1_reg - operand_2_reg;
            end
        endcase

        write_en <= 1'b1;
        read_en <= 1'b1;
        write_addr <= control;
        read_addr <= control;
    end

    always @(negedge clk) begin
        result <= result_reg;
    end

endmodule

module Shifter (
  input [31:0] in,
  input [1:0] ctrl,
  input [2:0] amt,
  output [31:0] out
);

  reg [31:0] shifted;

  always @(*) begin
    case(ctrl)
      2'b00: shifted = in << amt;
      2'b01: shifted = in >> amt;
      2'b10: begin
        if(in[31] == 1) begin
          shifted = { {amt{1'b1}}, in[31:amt] };
        end else begin
          shifted = { {amt{1'b0}}, in[31:amt] };
        end
      end
      default: shifted = 32'h0;
    endcase
  end

  assign out = shifted;

endmodule

module fsm_3bit_counter (
  input clk,
  input reset,
  input [2:0] counter,
  output reg [2:0] next_counter
);

reg [2:0] state, next_state;

always @ (counter) begin
  case (counter)
    3'h0: next_state = 3'h1;
    3'h1: next_state = 3'h2;
    3'h2: next_state = 3'h3;
    3'h3: next_state = 3'h0;
  endcase
end

always @ (posedge clk) begin
  if (reset) begin
    next_counter <= 3'h0;
    state <= 3'h0;
  end else begin
    next_counter <= next_state;
    state <= next_state;
  end
end

endmodule

