module edge_detection (
    input clk,
    input a,
    output reg rise,
    output reg down
);
    reg a_d1;
    always @(posedge clk) begin
        if (a && !a_d1) begin
            rise <= 1;
            down <= 0;
        end else if (!a && a_d1) begin
            rise <= 0;
            down <= 1;
        end else begin
            rise <= 0;
            down <= 0;
        end
        a_d1 <= a;
    end
endmodule

