    always @(posedge clk_a) begin
        if (clk_en_a) begin
            mem[addr_a] <= din;
        end
    end

    always @(posedge clk_b) begin
        if (clk_en_b) begin
            dout <= mem[addr_b];
        end
    end

endmodule

