module priority_encoder (
    input [7:0] in,
    output [2:0] out
);

    wire [7:0] gray;
    wire [2:0] dec;

    assign gray[7] = in[7];
    assign gray[6] = in[7] ^ in[6];
    assign gray[5] = in[6] ^ in[5];
    assign gray[4] = in[5] ^ in[4];
    assign gray[3] = in[4] ^ in[3];
    assign gray[2] = in[3] ^ in[2];
    assign gray[1] = in[2] ^ in[1];
    assign gray[0] = in[1] ^ in[0];

    assign dec[0] = ~gray[0] & ~gray[1] & ~gray[2] & ~gray[3] & ~gray[4] & ~gray[5] & ~gray[6] & gray[7];
    assign dec[1] = ~gray[0] & ~gray[1] & ~gray[2] & ~gray[3] & ~gray[4] & ~gray[5] & gray[6] & ~gray[7];
    assign dec[2] = ~gray[0] & ~gray[1] & ~gray[2] & ~gray[3] & gray[4] & ~gray[5] & ~gray[6] & ~gray[7];

    assign out = dec;

endmodule

module final_module (
