    assign mux_in[0] = nand_out[0];
    assign mux_in[1] = nand_out[1];
    assign mux_in[2] = nand_out[2];

    assign final_output = {mux_in[priority_out], 1'b0};

endmodule

module Peripheral_clk_interruptor(
    input clk,
    input rst,
    input [15:0] d_in,
    input cs,
    input [3:0] addr,
    input rd,
    input wr,
    output reg [15:0] d_out
    );

    reg [5:0] s;   //selector mux_4  and write registers

    reg [31:0] limit;
    reg [31:0] count;
    reg en=0;

    wire int_0;
    wire done;

    //----------------------------------------

    always @(*) begin
        case (addr)
            4'h0: s = (cs && wr) ? 6'b000001 : 6'b000000 ; //limit
            4'h2: s = (cs && wr) ? 6'b000010 : 6'b000000 ; //count
            4'h4: s = (cs && wr) ? 6'b000100 : 6'b000000 ; //en
            4'h6: s = (cs && rd) ? 6'b001000 : 6'b000000 ; //done
            4'h8: s = (cs && rd) ? 6'b010000 : 6'b000000 ; //int_0
            default: s = 6'b000000 ; 
        endcase
    end

    //----------------------------------------

    always @(negedge clk) begin
        limit    = (s[0]) ? d_in : limit;    //Write Registers
        count    = (s[1]) ? d_in : count;    //Write Registers
        en       = (s[2]) ? d_in : en;       //Write Registers
    end

    //----------------------------------------

    always @(negedge clk) begin
        case (s[5:3])
            3'b001: d_out[0] = done ;
            3'b010: d_out    = int_0 ;
            default: d_out   = 0 ;
        endcase
    end

    //----------------------------------------

    clk_interruptor c_i ( .clk(clk), .rst(rst), .limit(limit), .count(count), .en(en), .int_0(int_0), .done(done) );

endmodule

module full_adder (
    input A,
    input B,
    input C_IN,
    output SUM,
    output C_OUT
);

    assign SUM = A ^ B ^ C_IN;
    assign C_OUT = (A & B) | (C_IN & (A ^ B));

