    full_adder fa1 (.A(A[1]), .B(B[1]), .C_IN(C[0]), .SUM(SUM[1]), .C_OUT(C[1]));
    full_adder fa2 (.A(A[2]), .B(B[2]), .C_IN(C[1]), .SUM(SUM[2]), .C_OUT(C[2]));
    full_adder fa3 (.A(A[3]), .B(B[3]), .C_IN(C[2]), .SUM(SUM[3]), .C_OUT(X[4]));

