module pipelined_half_adder(
    input a,
    input b,
    output sum,
    output cout
);

    wire p, g;

    assign p = a ^ b;
    assign g = a & b;

    reg s, c;

    always @(posedge clk) begin
        s <= p ^ c;
        c <= g | (p & c);
    end

    assign sum = s;
    assign cout = c;

endmodule

