module SimpleRam
	#(parameter BUS_WIDTH = 8, parameter SIZE = 512, parameter ADDRESS_WIDTH = 32)
	(
		input wire clk,
		input wire reset,

		input wire [ADDRESS_WIDTH-1:0] addrA,
		input wire [BUS_WIDTH-1:0] dataIn,
		input wire writeEnable,

		input wire [ADDRESS_WIDTH-1:0] addrB,

		output reg [BUS_WIDTH-1:0] outA,
		output reg [BUS_WIDTH-1:0] outB,

		output reg busyA,
		output reg busyB
	);

	reg [BUS_WIDTH-1:0] memory[0:SIZE-1];

	reg [BUS_WIDTH-1:0] lastAddrA = 0;
	reg [BUS_WIDTH-1:0] lastAddrB = 0;

	// Counter variable for initialization
	integer i;

	// For debugging
	always @(posedge reset) $writememh("ram.hex", memory);

	always @(posedge clk)
	begin

		if(writeEnable)
		begin
			outA <= dataIn;
			memory[addrA] <= dataIn;

		end

		if(addrA != lastAddrA)
			busyA <= 1;

		if(addrB != lastAddrB)
			busyA <= 1;

		if(~writeEnable)
		begin
			busyA <= 0;
			outA <= memory[addrA];

			busyB <= 0;
			outB <= memory[addrB];
		end

		lastAddrA = addrA;
		lastAddrB = addrB;

		if(reset)
		begin
			busyA <= 1;
			busyB <= 1;

			outA <= 0;
			outB <= 0;

			for(i = 0; i < SIZE; i=i+1)
				memory[i] <= 0;
		end
	end

endmodule

module booth_multiplier (
    input clk,
    input reset,
    input [3:0] DATA_IN_A,
    input [2:0] DATA_IN_B,
    output reg [6:0] PRODUCT_OUT
);

    reg [4:0] A;
    reg [3:0] S;
    reg [2:0] P;
    reg [1:0] count;
    reg [3:0] temp;

    always @(posedge clk) begin
        if (reset) begin
            A <= 0;
            S <= 0;
            P <= 0;
            count <= 0;
        end else begin
            temp <= {DATA_IN_A, 2'b0};
            if (count == 0) begin
                S <= DATA_IN_B;
                P <= 0;
            end else begin
                if (S[1:0] == 2'b01) begin
                    P <= P + temp;
                end else if (S[1:0] == 2'b10) begin
                    P <= P - temp;
                end
                S <= {S[1], S[0], S[2]};
            end
            count <= count + 1;
        end
    end

    assign PRODUCT_OUT = P[6:0];

endmodule

