		.credit_in_din(credit_in_din),
		.output_channel_dout(output_channel_dout)
	);

	// Rearrange header flit fields
	assign shifted_header = {1'b1, 1'b1, header_flit_reg[CHANNEL_WIDTH-3:CHANNEL_WIDTH-1],
							 header_flit_reg[CHANNEL_WIDTH-4:CHANNEL_WIDTH-6],
							 header_flit_reg[CHANNEL_WIDTH-7:CHANNEL_WIDTH-9],
							 header_flit_reg[CHANNEL_WIDTH-1:0]};

