    output [7:0] anyedge
);

    reg [7:0] prev_in;
    reg [7:0] edge_detected;
    wire [3:0] priority;
    wire [3:0] mux_out;

    // Binary edge detector
    always @(posedge clk) begin
        if (in[0] && !prev_in[0]) begin
            edge_detected[0] <= 1;
        end else if (!in[0] && prev_in[0]) begin
            edge_detected[0] <= 0;
        end
        if (in[1] && !prev_in[1]) begin
            edge_detected[1] <= 1;
        end else if (!in[1] && prev_in[1]) begin
            edge_detected[1] <= 0;
        end
        if (in[2] && !prev_in[2]) begin
            edge_detected[2] <= 1;
        end else if (!in[2] && prev_in[2]) begin
            edge_detected[2] <= 0;
        end
        if (in[3] && !prev_in[3]) begin
            edge_detected[3] <= 1;
        end else if (!in[3] && prev_in[3]) begin
            edge_detected[3] <= 0;
        end
        if (in[4] && !prev_in[4]) begin
            edge_detected[4] <= 1;
        end else if (!in[4] && prev_in[4]) begin
            edge_detected[4] <= 0;
        end
        if (in[5] && !prev_in[5]) begin
            edge_detected[5] <= 1;
        end else if (!in[5] && prev_in[5]) begin
            edge_detected[5] <= 0;
        end
        if (in[6] && !prev_in[6]) begin
            edge_detected[6] <= 1;
        end else if (!in[6] && prev_in[6]) begin
            edge_detected[6] <= 0;
        end
        if (in[7] && !prev_in[7]) begin
            edge_detected[7] <= 1;
        end else if (!in[7] && prev_in[7]) begin
            edge_detected[7] <= 0;
        end
        prev_in <= in;
    end

    // Priority encoder for selecting input signals
    assign priority = {in0, in1, in2, in3} > sel;

    // 4-to-1 multiplexer
    assign mux_out = (priority[0]) ? in0 : (priority[1]) ? in1 : (priority[2]) ? in2 : in3;

    // Output signals
    assign out = mux_out;
    assign anyedge = edge_detected;

endmodule

