module flip_flop (
  input clk, reset, set, d, j, k, t, s,
  output q, q_bar
);

parameter type = "D"; // type of flip-flop (D, JK, T, SR)

reg q, q_bar;

always @(posedge clk or posedge reset or posedge set) begin
  if (reset) begin
    q <= 1'b0;
    q_bar <= 1'b1;
  end else if (set) begin
    q <= 1'b1;
    q_bar <= 1'b0;
  end else begin
    case (type)
      "D": q <= d;
      "JK": begin
        if (j && !k) q <= 1'b1;
        else if (!j && k) q <= 1'b0;
      end
      "T": begin
        if (t) q <= ~q;
      end
      "SR": begin
        if (s && !r) begin
          q <= 1'b1;
          q_bar <= 1'b0;
        end else if (!s && r) begin
          q <= 1'b0;
          q_bar <= 1'b1;
        end
      end
    endcase
  end
end

assign q_bar = ~q;

endmodule

module top_module (
    input clk,
    input reset,      // Asynchronous active-high reset
    input up_down,    // Control input to select count direction
    input [1:0] input_value, // 2-bit input for the functional module
    output [1:0] output_value, // 2-bit output from the functional module
    output [2:0] counter_output // 3-bit output from the counter
);

reg [2:0] counter;
wire [1:0] sum;
wire carry_out;

// 3-bit binary counter with asynchronous reset
always @(posedge clk or posedge reset) begin
    if (reset) begin
        counter <= 3'b0;
    end else begin
        if (up_down) begin
            counter <= counter + 1;
        end else begin
            counter <= counter - 1;
        end
    end
end

// Functional module that adds the output of the counter and a 2-bit input value using only XOR and AND gates
assign sum[0] = counter[0] ^ input_value[0];
assign sum[1] = (counter[1] ^ input_value[1]) ^ (counter[0] & input_value[0]);
assign carry_out = (counter[1] & input_value[1]) | (counter[0] & input_value[0]);
assign output_value = sum;

// Output signals
assign counter_output = counter;

endmodule

module up_down_barrel (
    input clk,
    input reset,
    input control,
    input [3:0] A,
    input [1:0] B,
    output [3:0] Q,
    output COUT
);

reg [3:0] count;

always @(posedge clk) begin
    if (reset) begin
        count <= 4'b0;
    end else if (control) begin
        count <= count + 1;
    end else begin
        count <= count - 1;
    end
end

assign COUT = (B == 2'b11) ? ((control) ? (count == 4'b1111) : (count == 4'b0000)) : 1'b0;

assign Q = (B == 2'b00) ? A :
          (B == 2'b01) ? {A[2:0], COUT} :
          (B == 2'b10) ? {COUT, A[3:1]} :
          (control) ? count : (15 - count);

endmodule

module jt12_eg_pure(
    input           attack,
    input           step,
    input [5:1]     rate,
    input [9:0]     eg_in,
    input           ssg_en,
    input           sum_up,
    output reg [9:0] eg_pure
);

reg [3:0]   dr_sum;
reg [9:0]   dr_adj;
reg [10:0]  dr_result;

always @(*) begin : dr_calculation
    case(rate[5:2])
        4'b1100: dr_sum = {2'b0, step, ~step}; // 12
        4'b1101: dr_sum = {1'b0, step, ~step, 1'b0}; // 13
        4'b1110: dr_sum = {step, ~step, 2'b0}; // 14
        4'b1111: dr_sum = 4'd8;// 15
        default: dr_sum = {2'b0, step, 1'b0};
    endcase
    // Decay rate attenuation is multiplied by 4 for SSG operation
    dr_adj = ssg_en ? {4'd0, dr_sum, 2'd0} : {6'd0, dr_sum};
    dr_result = dr_adj + eg_in;
end

reg [7:0] ar_sum0;
reg [8:0] ar_sum1;
reg [10:0] ar_result;
reg [9:0] ar_sum;

always @(*) begin : ar_calculation
    casez(rate[5:2])
        default: ar_sum0 = {2'd0, eg_in[9:4]};
        4'b1101: ar_sum0 = {1'd0, eg_in[9:3]};
        4'b111?: ar_sum0 = eg_in[9:2];
    endcase
    ar_sum1 = ar_sum0 + 9'd1;
    if(rate[5:4] == 2'b11)
        ar_sum = step ? {ar_sum1, 1'b0} : {1'b0, ar_sum1};
    else
        ar_sum = step ? {1'b0, ar_sum1} : 10'd0;
    ar_result = eg_in - ar_sum;
end

///////////////////////////////////////////////////////////
// rate not used below this point
reg [9:0] eg_pre_fastar; // pre fast attack rate
always @(*) begin
    if(sum_up) begin
        if(attack)
            eg_pre_fastar = ar_result[10] ? 10'd0 : ar_result[9:0];
        else
            eg_pre_fastar = dr_result[10] ? 10'h3FF : dr_result[9:0];
    end
    else eg_pre_fastar = eg_in;
    eg_pure = (attack&rate[5:1]==5'h1F) ? 10'd0 : eg_pre_fastar;
end

endmodule

