module MIB (
  input clk,
  input rst,
  input en,
  input [n-1:0] addr,
  input [n-1:0] data_in,
  input wr,
  output reg [n-1:0] data_out
);

parameter n = 16; // width of the data bus
parameter k = 4; // number of banks
parameter tCK = 5; // clock period (in ns)
parameter tRCD = 10; // RAS to CAS delay (in ns)
parameter tRP = 15; // row precharge time (in ns)
parameter tRAS = 25; // active to precharge time (in ns)
parameter tRC = 40; // row cycle time (in ns)
parameter tWR = 10; // write recovery time (in ns)

// Verilog code to implement the memory interface block

reg [n-1:0] mem [k-1:0][2**n-1:0]; // memory array

reg [n-1:0] data_out_reg; // register to hold output data
reg [n-1:0] data_in_reg; // register to hold input data
reg [n-1:0] addr_reg; // register to hold address

reg [1:0] state; // state machine state
parameter IDLE = 2'b00;
parameter READ_ADDR = 2'b01;
parameter READ_DATA = 2'b10;
parameter WRITE_ADDR = 2'b11;
parameter WRITE_DATA = 2'b100;
parameter WRITE_WAIT = 2'b101;

reg [tCK-1:0] count; // counter to keep track of timing

always @(posedge clk) begin
  if (rst) begin
    state <= IDLE;
    count <= 0;
    data_out_reg <= 0;
    data_in_reg <= 0;
    addr_reg <= 0;
  end else begin
    case (state)
      IDLE: begin
        if (en) begin
          if (wr) begin
            state <= WRITE_ADDR;
            addr_reg <= addr;
            data_in_reg <= data_in;
          end else begin
            state <= READ_ADDR;
            addr_reg <= addr;
          end
          count <= 0;
        end
      end
      READ_ADDR: begin
        if (count >= tRCD/tCK) begin
          state <= READ_DATA;
          count <= 0;
        end else begin
          count <= count + 1;
        end
      end
      READ_DATA: begin
        if (count >= tRL/tCK) begin
          data_out_reg <= mem[addr_reg[k-1:0]][addr_reg[n-1:0]];
          state <= IDLE;
          count <= 0;
        end else begin
          count <= count + 1;
        end
      end
      WRITE_ADDR: begin
        if (count >= tRCD/tCK) begin
          state <= WRITE_DATA;
          count <= 0;
        end else begin
          count <= count + 1;
        end
      end
      WRITE_DATA: begin
        if (count >= tWL/tCK) begin
          mem[addr_reg[k-1:0]][addr_reg[n-1:0]] <= data_in_reg;
          state <= WRITE_WAIT;
          count <= 0;
        end else begin
          count <= count + 1;
        end
      end
      WRITE_WAIT: begin
        if (count >= tWR/tCK) begin
          state <= IDLE;
          count <= 0;
        end else begin
          count <= count + 1;
        end
      end
    endcase
  end
end

assign data_out = data_out_reg;

endmodule

module FSM (
  input in1,
  input in2,
  output out1,
  output out2
);

  // Define the four states using two binary digits
  parameter S0 = 2'b00;
  parameter S1 = 2'b01;
  parameter S2 = 2'b10;
  parameter S3 = 2'b11;

  // Define the current state and next state variables
  reg [1:0] current_state, next_state;

  // Define the output signals based on the current state of the FSM
  assign out1 = (current_state == S0 || current_state == S2) ? 1'b1 : 1'b0;
  assign out2 = (current_state == S1 || current_state == S2) ? 1'b1 : 1'b0;

  // Implement the state machine and the transitions between states
  always @(current_state, in1, in2) begin
    case (current_state)
      S0: begin
        if (in1) next_state = S1;
        else if (in2) next_state = S2;
        else if (in1 && in2) next_state = S3;
        else next_state = S0;
      end
      S1: begin
        if (in2) next_state = S3;
        else if (!in1) next_state = S0;
        else next_state = S1;
      end
      S2: begin
        if (in1) next_state = S3;
        else if (!in2) next_state = S0;
        else next_state = S2;
      end
      S3: begin
        if (!in1 && !in2) next_state = S0;
        else next_state = S3;
      end
    endcase
    current_state <= next_state;
  end

endmodule

