    .in1(in1),
    .in2(in2),
    .mult_result(mult_result),
    .out(shift_add_result)
  );

  control_logic_module control_logic_inst(
    .mult_result(mult_result),
    .enable_out_lo(enable_out_lo)
  );

  assign out = mult_result;
  assign out_lo = enable_out_lo ? shift_add_result : 8'b0;

endmodule

module mult_module(
  input clk,
  input reset,
  input [7:0] in1,
  input [7:0] in2,
  output reg [15:0] out
);

  always @(posedge clk) begin
    if (reset) begin
      out <= 16'b0;
    end else begin
      out <= in1 * in2;
    end
  end

endmodule

module shift_add_module(
  input [7:0] in1,
  input [7:0] in2,
  input [15:0] mult_result,
  output reg [7:0] out
);

  always @(*) begin
    out = (mult_result >> 8) + in1 * (mult_result & 8'hFF) + in2 * (mult_result & 8'hFF00);
  end

endmodule

module control_logic_module(
  input [15:0] mult_result,
  output reg enable_out_lo
);

  always @(*) begin
    enable_out_lo = (mult_result[15] == 1);
  end

endmodule

module bram_interface (
  input wire clk,
  input wire [14:0] addr,
  input wire [7:0] din,
  input wire write_en,
  output wire [7:0] dout
);

wire [7:0] douta;
reg [7:0] dout_reg;

XEVIOUS_BROM bram (
  .clka(clk),
  .addra(addr),
  .dina(din),
  .wea(write_en),
  .douta(douta)
);

always @(posedge clk) begin
  if (!write_en) begin
    dout_reg <= douta;
  end
end

assign dout = write_en ? 8'b0 : dout_reg;

endmodule

module axis_decimator #
(
  parameter integer AXIS_TDATA_WIDTH = 32
)
(
  // System signals
  input  wire                        aclk,
  input  wire                        aresetn,

  // I2S signals
  inout  wire [3:0]                  gpio_data,

  // ALEX signals
  input wire                         alex_flag,
  input wire [3:0]                   alex_data,

  // Slave side
  output wire                        s_axis_tready,
  input  wire [AXIS_TDATA_WIDTH-1:0] s_axis_tdata,
  input  wire                        s_axis_tvalid,

  // Master side
  input  wire                        m_axis_tready,
  output wire [AXIS_TDATA_WIDTH-1:0] m_axis_tdata,
  output wire                        m_axis_tvalid
);

  localparam I2S_DATA_WIDTH = AXIS_TDATA_WIDTH / 2;
  localparam CNTR_WIDTH = 6;

  reg [1:0] adc_case_reg, adc_case_next;
  reg [CNTR_WIDTH-1:0] adc_cntr_reg, adc_cntr_next;
  reg [I2S_DATA_WIDTH-1:0] adc_data_reg, adc_data_next;
  reg [AXIS_TDATA_WIDTH-1:0] adc_tdata_reg, adc_tdata_next;
  reg adc_tvalid_reg, adc_tvalid_next;

  reg [1:0] dac_case_reg, dac_case_next;
  reg [I2S_DATA_WIDTH-1:0] dac_data_reg, dac_data_next;
  reg [AXIS_TDATA_WIDTH-1:0] dac_tdata_reg, dac_tdata_next;

  wire i2s_bclk, i2s_lrclk, i2s_adc_data;

  wire not_alex_flag = ~alex_flag;

  IOBUF buf_bclk (.O(i2s_bclk), .IO(gpio_data[0]), .I(alex_data[0]), .T(not_alex_flag));
  IOBUF buf_adc_data (.O(i2s_adc_data), .IO(gpio_data[1]), .I(alex_data[1]), .T(not_alex_flag));
  IOBUF buf_dac_data (.O(), .IO(gpio_data[2]), .I(alex_flag ? alex_data[2] : dac_tdata_reg[I2S_DATA_WIDTH-1]), .T(1'b0));
  IOBUF buf_lrclk (.O(i2s_lrclk), .IO(gpio_data[3]), .I(alex_data[3]), .T(not_alex_flag));

  always @(posedge aclk)
  begin
    if(~aresetn)
    begin
      adc_case_reg <= 2'd0;
      adc_cntr_reg <= {(CNTR_WIDTH){1'b0}};
      adc_data_reg <= {(I2S_DATA_WIDTH){1'b0}};
      adc_tdata_reg <= {(AXIS_TDATA_WIDTH){1'b0}};
      adc_tvalid_reg <= 1'b0;
      dac_case_reg <= 2'd0;
      dac_data_reg <= {(I2S_DATA_WIDTH){1'b0}};
      dac_tdata_reg <= {(AXIS_TDATA_WIDTH){1'b0}};
    end
    else
    begin
      adc_case_reg <= adc_case_next;
      adc_cntr_reg <= adc_cntr_next;
      adc_data_reg <= adc_data_next;
      adc_tdata_reg <= adc_tdata_next;
      adc_tvalid_reg <= adc_tvalid_next;
      dac_case_reg <= dac_case_next;
      dac_data_reg <= dac_data_next;
      dac_tdata_reg <= dac_tdata_next;
    end
  end

  assign int_bclk_posedge = i2s_bclk[1] & ~i2s_bclk[2];
  assign int_bclk_negedge = ~i2s_bclk[1] & i2s_bclk[2];
  assign int_lrclk_negedge = ~i2s_lrclk[1] & i2s_lrclk[2];

  always @*
  begin
    adc_case_next = adc_case_reg;
    adc_cntr_next = adc_cntr_reg;
    adc_data_next = adc_data_reg;
    adc_tdata_next = adc_tdata_reg;
    adc_tvalid_next = adc_tvalid_reg;

    if(int_bclk_posedge & (adc_cntr_reg < I2S_DATA_WIDTH))
    begin
      adc_data_next = {adc_data_reg[I2S_DATA_WIDTH-2:0], i2s_adc_data};
      adc_cntr_next = adc_cntr_reg + 1'b1;
    end

    if(m_axis_tready & adc_tvalid_reg)
    begin
      adc_tvalid_next = 1'b0;
    end

    case(adc_case_reg)
      2'd0:
      begin
        if(int_lrclk_negedge)
        begin
          adc_case_next = 2'd1;
        end
      end
      2'd1:
      begin
        if(int_bclk_posedge)
        begin
          adc_cntr_next = {(CNTR_WIDTH){1'b0}};
          adc_case_next = 2'd2;
        end
      end
      2'd2:
      begin
        if(int_bclk_posedge)
        begin
          adc_tvalid_next = 1'b1;
          adc_tdata_next = {adc_data_reg, {(AXIS_TDATA_WIDTH - I2S_DATA_WIDTH){1'b0}}};
          adc_case_next = 2'd0;
        end
      end
    endcase
  end

  always @*
  begin
    dac_case_next = dac_case_reg;
    dac_data_next = dac_data_reg;
    dac_tdata_next = dac_tdata_reg;

    if(int_bclk_negedge)
    begin
      dac_data_next = {dac_data_reg[I2S_DATA_WIDTH-2:0], 1'b0};
    end

    if(int_lrclk_negedge)
    begin
      dac_tdata_next = s_axis_tvalid ? s_axis_tdata : {(AXIS_TDATA_WIDTH){1'b0}};
    end

    case(dac_case_reg)
      2'd0:
      begin
        if(int_lrclk_negedge)
        begin
          dac_case_next = 2'd1;
        end
      end
      2'd1:
      begin
        if(int_bclk_posedge)
        begin
          dac_case_next = 2'd2;
        end
      end
      2'd2:
      begin
        if(int_bclk_negedge)
        begin
          dac_data_next = dac_tdata_reg[I2S_DATA_WIDTH-1:0];
          dac_case_next = 2'd0;
        end
      end
    endcase
  end

  assign s_axis_tready = int_lrclk_negedge;
  assign m_axis_tdata = adc_tdata_reg;
  assign m_axis_tvalid = adc_tvalid_reg;

endmodule

module configurable_counter (
  input clk,
  input reset,
  input [7:0] max_count,
  output reg [7:0] count
);

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      count <= 8'b0;
    end else if (count == max_count) begin
      count <= 8'b0;
    end else begin
      count <= count + 1;
    end
  end

endmodule

module gray_code_counter (
  input clk,
  input reset,
  output reg [3:0] gray_code
);

  // Define the four states of the FSM
  parameter S0 = 2'b00;
  parameter S1 = 2'b01;
  parameter S2 = 2'b10;
  parameter S3 = 2'b11;

  // Define the state register and next state logic
  reg [1:0] state_reg, state_next;

  // Define the Gray code counter
  reg [3:0] gray_code_reg, gray_code_next;

  // Initialize the state and Gray code registers
  initial begin
    state_reg = S0;
    gray_code_reg = 4'b0000;
  end

  // Define the state transition logic
  always @ (posedge clk, posedge reset) begin
    if (reset) begin
      state_reg <= S0;
      gray_code_reg <= 4'b0000;
    end else begin
      state_reg <= state_next;
      gray_code_reg <= gray_code_next;
    end
  end

  // Define the next state and Gray code logic
  always @ (state_reg, gray_code_reg) begin
    case (state_reg)
      S0: begin
        state_next = S1;
        gray_code_next = 4'b0001;
      end
      S1: begin
        state_next = S2;
        gray_code_next = 4'b0011;
      end
      S2: begin
        state_next = S3;
        gray_code_next = 4'b0010;
      end
      S3: begin
        state_next = S0;
        gray_code_next = 4'b0110;
      end
    endcase

    // Wrap around to zero after reaching 15
    if (gray_code_reg == 4'b1111) begin
      gray_code_next = 4'b0000;
    end
  end

  // Assign the Gray code output
  assign gray_code = gray_code_reg;

endmodule

module adder (
    input clk,
    input reset,
    input [7:0] a,
    input [7:0] b,
    output reg [7:0] sum
);

    always @(posedge clk) begin
        if (reset) begin
            sum <= 8'b0;
        end else begin
            sum <= a + b;
        end
    end

endmodule

module top_module (
    input clk,
    input reset,
    input [7:0] a,
    input [7:0] b,
    input select,
    output [7:0] sum
);

    wire [7:0] sum1, sum2;

    adder adder1 (
        .clk(clk),
        .reset(reset),
        .a(a),
        .b(b),
        .sum(sum1)
    );

    adder adder2 (
        .clk(clk),
        .reset(reset),
        .a(a),
        .b(b),
        .sum(sum2)
    );

    assign sum = select ? sum2 : sum1;

endmodule

module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [3:0] a0,   // 4-bit input for adder 0
    input [3:0] a1,   // 4-bit input for adder 1
    input select,     // Select input for the multiplexer
    output [3:0] out  // 4-bit output from the active module
);

    // Instantiate the two 4-bit adders
    wire [3:0] sum0;
    wire [3:0] sum1;
    adder4 adder0(.a(a0), .b(a1), .sum(sum0));
    adder4 adder1(.a(a0), .b(a1), .sum(sum1));

    // Instantiate the 2-to-1 multiplexer
    wire [3:0] mux_out;
    mux2to1 mux(.a(sum0), .b(sum1), .sel(select), .out(mux_out));

    // Instantiate the bitwise AND module
    wire [3:0] and_out;
    and4 and(.a(sum0), .b(sum1), .out(and_out));

    // Output either the multiplexer output or the AND output based on the select input
    assign out = select ? and_out : mux_out;

endmodule

// 4-bit adder module
module adder4 (
    input [3:0] a,
    input [3:0] b,
    output [3:0] sum
);

    assign sum = a + b;

endmodule

// 2-to-1 multiplexer module
module mux2to1 (
    input [3:0] a,
    input [3:0] b,
    input sel,
    output [3:0] out
);

    assign out = sel ? b : a;

endmodule

// 4-bit bitwise AND module
module and4 (
    input [3:0] a,
    input [3:0] b,
    output [3:0] out
);

    assign out = a & b;

endmodule

module full_adder (
    input a,
    input b,
    input cin,
    output sum,
    output cout
);

    assign sum = a ^ b ^ cin;
    assign cout = (a & b) | (a & cin) | (b & cin);

endmodule

module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    output [4:0] sum
);

    wire [3:0] carry;
    full_adder fa0(.a(A[0]), .b(B[0]), .cin(1'b0), .sum(sum[0]), .cout(carry[0]));
    full_adder fa1(.a(A[1]), .b(B[1]), .cin(carry[0]), .sum(sum[1]), .cout(carry[1]));
    full_adder fa2(.a(A[2]), .b(B[2]), .cin(carry[1]), .sum(sum[2]), .cout(carry[2]));
    full_adder fa3(.a(A[3]), .b(B[3]), .cin(carry[2]), .sum(sum[3]), .cout(sum[4]));

endmodule

module dc_ctrl(input  wire        clk,
               input  wire        rst,

               input  wire `REQ   dc_ctrl_req,
               output wire `RES   dc_ctrl_res);

   parameter       debug = 0;

   wire [31:0]     addr, q;
   reg             r_ = 0;
   always @(posedge clk) r_ <= rst ? 1'b0 : dc_ctrl_req`R;
   assign addr             = dc_ctrl_req`A;
   assign dc_ctrl_res`RD   = r_ ? q : 0;
   assign dc_ctrl_res`HOLD = !dcache.clken;

   dcache dc(.clock  (clk),
             .clken  (!dc_ctrl_res.HOLD),
             .address(addr[12:2]),
             .wren   (dc_ctrl_req`W),
             .data   (dc_ctrl_req`WD),
             .byteena(dc_ctrl_req`WBE),
             .q      (q));

`ifdef SIMULATE_MAIN
   pipechecker check("dc_ctrl", clk, dc_ctrl_req, dc_ctrl_res);

   // Debugging
   always @(posedge clk) if (debug) begin
      if (dc_ctrl_res`HOLD)
        $display("%5d D$: Stall x_load %d x_store %d m_stall %d opcode %2x",
                 $time, dc_ctrl_req`R, dc_ctrl_req`W);
      else begin
         if (dc_ctrl_req`R)
           $display("%5d D$: load [%x]", $time, dc_ctrl_req`A);

         if (r_)
           $display("%5d D$: load -> %x", $time, dc_ctrl_res`RD);

         if (dc_ctrl_req`W)
           $display("%5d D$: store %x->[%x] (bytena %x)",
                    $time, dc_ctrl_req`WD, addr, dc_ctrl_req`WBE);
      end
   end
`endif
endmodule

module barrel_shifter (
    input [3:0] data,
    input [1:0] shift_amount,
    output reg [3:0] result
);

always @(*) begin
    case(shift_amount)
        2'b00: result = data;
        2'b01: result = {data[2:0], 1'b0};
        2'b10: result = {data[1:0], 2'b00};
        2'b11: result = 4'b0000;
    endcase
end

endmodule

module shift_register (
    LOAD,
    DATA_IN,
    CLK,
    RESET_B,
    DATA_OUT,
    Q_N
);

    input LOAD;
    input [3:0] DATA_IN;
    input CLK;
    input RESET_B;
    output [3:0] DATA_OUT;
    output Q_N;

    wire [3:0] Q;
    wire [3:0] Q_N_internal;

    sky130_fd_sc_ls__dlrbp_1 flip_flop_0 (
        .D(DATA_IN[0]),
        .RESET_B(RESET_B),
        .GATE(1),
        .Q(Q[0]),
        .Q_N(Q_N_internal[0])
    );

    sky130_fd_sc_ls__dlrbp_1 flip_flop_1 (
        .D(Q[0]),
        .RESET_B(RESET_B),
        .GATE(1),
        .Q(Q[1]),
        .Q_N(Q_N_internal[1])
    );

    sky130_fd_sc_ls__dlrbp_1 flip_flop_2 (
        .D(Q[1]),
        .RESET_B(RESET_B),
        .GATE(1),
        .Q(Q[2]),
        .Q_N(Q_N_internal[2])
    );

    sky130_fd_sc_ls__dlrbp_1 flip_flop_3 (
        .D(Q[2]),
        .RESET_B(RESET_B),
        .GATE(1),
        .Q(Q[3]),
        .Q_N(Q_N_internal[3])
    );

    assign Q_N = Q_N_internal[3];

    always @ (posedge CLK) begin
        if (RESET_B == 0) begin
            Q <= 4'b0000;
        end else if (LOAD == 1) begin
            Q <= DATA_IN;
        end else begin
            Q <= {Q[2:0], 1'b0};
        end
    end

    assign DATA_OUT = Q;

endmodule

module top_module (
    input clk,
    input reset,
    input [1:0] sel, // 2-bit input for the decoder
    input [3:0] a, b, // 4-bit inputs for the multiplier
    output reg [7:0] product, // 8-bit output from the multiplier
    output reg [15:0] out // 16-bit output from the decoder
);

reg [15:0] decoder_out;
reg [3:0] multiplier_out;

// 4-to-16 decoder
always @ (sel) begin
    case (sel)
        2'b00: decoder_out = 16'b1111111111111110;
        2'b01: decoder_out = 16'b1111111111111101;
        2'b10: decoder_out = 16'b1111111111111011;
        2'b11: decoder_out = 16'b1111111111110111;
    endcase
end

// 4-bit multiplier using shift-and-add method
always @(posedge clk) begin
    if (reset) begin
        product <= 8'b0;
        multiplier_out <= 4'b0;
    end else begin
        multiplier_out <= a;
        for (i = 0; i < 4; i = i + 1) begin
            if (b[i] == 1) begin
                product <= product + (multiplier_out << i);
            end
        end
    end
end

// Output from selected decoder output used as one of the inputs to the multiplier
always @ (decoder_out, multiplier_out) begin
    case (sel)
        2'b00: product[7:0] <= decoder_out[7:0];
        2'b01: product[7:0] <= decoder_out[15:8];
        2'b10: product[7:0] <= decoder_out[11:4];
        2'b11: product[7:0] <= decoder_out[15:8];
    endcase
end

// Output from the decoder
assign out = decoder_out;

endmodule

module alu_reg #(parameter word_sz = 8, addr_sz = 5)
	(	output [word_sz:0] alu_out,
		input [word_sz-1:0] di,
		input [addr_sz-1:0] raddr_1, raddr_2, waddr,
		input [2:0] opcode,
		input c_in, wr_enable, clk);

	wire [word_sz-1:0] do_1, do_2;

	reg_file #(word_sz, addr_sz) rfile(do_1, do_2, di, raddr_1, raddr_2,
		waddr, wr_enable, clk);
	alu_p #(word_sz) alu(alu_out, do_1, do_2, c_in, opcode);
endmodule

module reg_file #(parameter word_sz = 8, addr_sz = 5)
	(	output reg [word_sz-1:0] do_1, do_2,
		input [word_sz-1:0] di,
		input [addr_sz-1:0] raddr_1, raddr_2, waddr,
		input wr_enable, clk);

	reg [word_sz-1:0] reg_file [0:(1<<addr_sz)-1];

	always @(posedge clk) begin
		if (wr_enable) begin
			reg_file[waddr] <= di;
		end
		do_1 <= reg_file[raddr_1];
		do_2 <= reg_file[raddr_2];
	end
endmodule

module alu_p #(parameter word_sz = 8)
	(	output reg [word_sz-1:0] alu_out,
		input [word_sz-1:0] a, b,
		input c_in,
		input [2:0] opcode);

	reg [word_sz:0] result;

	always @* begin
		case (opcode)
			3'b000: result = a + b + c_in;
			3'b001: result = a & b;
			3'b010: result = a | b;
			3'b011: result = a ^ b;
			3'b100: result = a << 1;
			3'b101: result = a >> 1;
			3'b110: result = {1'b0, a[word_sz-1:1]};
			3'b111: result = {a[word_sz-1], a[word_sz-1:1]};
		endcase
	end

	always @(posedge clk) begin
		alu_out <= result[word_sz-1:0];
	end
endmodule

module mux4to1(
  input in0,
  input in1,
  input in2,
  input in3,
  input sel0,
  input sel1,
  output reg out
);

  always @(*) begin
    case ({sel1, sel0})
      2'b00: out = in0;
      2'b01: out = in1;
      2'b10: out = in2;
      2'b11: out = in3;
    endcase
  end

endmodule

module foc_module(
  input wire clk,
  input wire [47:0] i_d,
  input wire i_dv,
  output wire [15:0] clark_x,
  output wire [15:0] clark_y,
  output wire [15:0] park_x,
  output wire [15:0] park_y,
