  output wire [15:0] v_a,
  output wire [15:0] v_b,
  output wire [15:0] v_c,
  output wire [15:0] pwm_a,
  output wire [15:0] pwm_b,
  output wire [15:0] pwm_c,
  output wire [31:0] integrator_d,
