);

// Define constants
localparam V_RATED = 24;
localparam P_RATED = 1000;
localparam MAX_SPEED = 3000;
localparam MAX_INT_WINDUP = 16'h100;

// Define variables
reg [10:0] menc_raw;
reg [15:0] current_target;
reg [15:0] p_gain;
reg [15:0] i_gain;
reg [15:0] max_v;
reg active;
reg [31:0] max_integrator_windup;
reg [15:0] stator_offset;
reg [15:0] i_alpha;
reg [15:0] i_beta;
reg [15:0] i_q;
reg [15:0] i_d_ref;
reg [15:0] i_q_ref;
reg [15:0] v_alpha;
reg [15:0] v_beta;
reg [15:0] v_q;
reg [15:0] v_d;
reg [15:0] v_d_ref;
reg [15:0] v_q_ref;
reg [15:0] error_alpha;
reg [15:0] error_beta;
reg [15:0] error_d_int;
reg [15:0] error_q_int;
reg [15:0] pwm_alpha;
reg [15:0] pwm_beta;
reg [15:0] pwm_d;
reg [15:0] pwm_q;
reg [31:0] integrator_d_int;
reg [31:0] integrator_q_int;
reg [15:0] max_v_d;
reg [15:0] max_v_q;
reg [15:0] max_i_q;
reg [15:0] max_i_d;

// Set initial values
initial begin
  menc_raw = 10'h035;
  current_target = 16'h1234;
  p_gain = 8000;
  i_gain = 0;
  active = 0;
  max_v = 16'h7fff;
  max_integrator_windup = MAX_INT_WINDUP;
  stator_offset = 10'h0;
  max_v_d = V_RATED;
  max_v_q = V_RATED;
  max_i_q = P_RATED / V_RATED;
  max_i_d = sqrt((P_RATED / V_RATED) ** 2 - max_i_q ** 2);
end

// Calculate clark transform
assign clark_x = (i_d[31:16] * 2 - i_d[47:32]) >> 1;
assign clark_y = (i_d[31:16] - i_d[47:32]) >> 1;

// Calculate park transform
assign park_x = clark_x * sin(stator_offset) + clark_y * cos(stator_offset);
assign park_y = -clark_x * cos(stator_offset) + clark_y * sin(stator_offset);

// Calculate error values
assign error_alpha = current_target - i_alpha;
assign error_beta = -i_beta;
assign error_d = error_alpha * cos(stator_offset) - error_beta * sin(stator_offset);
assign error_q = error_alpha * sin(stator_offset) + error_beta * cos(stator_offset);

// Calculate PI controller gains
always @(*) begin
  i_d_ref = error_d * p_gain + integrator_d_int / i_gain;
  i_q_ref = error_q * p_gain + integrator_q_int / i_gain;
end

// Calculate voltage vector components
assign v_alpha = i_alpha * max_v / max_i_q;
assign v_beta = i_beta * max_v / max_i_q;
assign v_q_ref = i_q_ref * max_v_q / max_i_q;
assign v_d_ref = i_d_ref * max_v_d / max_i_d;

// Calculate voltage vector components in rotating reference frame
always @(posedge clk) begin
  v_q <= v_q_ref;
  v_d <= v_d_ref;
  v_alpha <= v_q * sin(stator_offset) + v_d * cos(stator_offset);
  v_beta <= -v_q * cos(stator_offset) + v_d * sin(stator_offset);
end

// Calculate PWM values
always @(posedge clk) begin
  pwm_alpha <= pwm_a - pwm_b;
  pwm_beta <= pwm_c - pwm_b;
  pwm_d <= pwm_alpha * cos(stator_offset) + pwm_beta * sin(stator_offset);
  pwm_q <= pwm_alpha * sin(stator_offset) - pwm_beta * cos(stator_offset);
end

// Calculate integrator values
always @(posedge clk) begin
  if (active) begin
    integrator_d_int <= integrator_d_int + error_d_int;
    integrator_q_int <= integrator_q_int + error_q_int;
  end
end

// Calculate maximum voltage values
always @(*) begin
  max_v_d = min(max_v, sqrt((max_v ** 2 - v_q_ref ** 2) / (1 + (v_d_ref / v_q_ref) ** 2)));
  max_v_q = min(max_v, sqrt((max_v ** 2 - v_d_ref ** 2) / (1 + (v_q_ref / v_d_ref) ** 2)));
end

// Calculate maximum current values
always @(*) begin
  max_i_q = min(max_i_q, sqrt((max_v_q ** 2 - v_alpha ** 2) / (v_beta ** 2 + v_alpha ** 2)));
  max_i_d = min(max_i_d, sqrt((max_v_d ** 2 - v_alpha ** 2) / (v_beta ** 2 + v_alpha ** 2)));
end

// Calculate PWM values for each phase
always @(posedge clk) begin
  if (active) begin
    if (v_alpha > max_v_d) begin
      pwm_a <= 1;
      pwm_b <= 0;
      pwm_c <= 0;
    end else if (v_alpha < -max_v_d) begin
      pwm_a <= 0;
      pwm_b <= 1;
      pwm_c <= 0;
    end else if (v_beta > max_v_q) begin
      pwm_a <= 0;
      pwm_b <= 0;
      pwm_c <= 1;
    end else if (v_beta < -max_v_q) begin
      pwm_a <= 0;
      pwm_b <= 1;
      pwm_c <= 1;
    end else begin
      pwm_a <= 1;
      pwm_b <= 1;
      pwm_c <= 1;
    end
  end else begin
    pwm_a <= 0;
    pwm_b <= 0;
    pwm_c <= 0;
  end
end

// Calculate current values in rotating reference frame
always @(posedge clk) begin
  i_alpha <= clark_x * cos(stator_offset) - clark_y * sin(stator_offset);
  i_beta <= clark_x * sin(stator_offset) + clark_y * cos(stator_offset);
  i_q <= i_alpha * sin(stator_offset) + i_beta * cos(stator_offset);
end

// Calculate integrator windup values
always @(posedge clk) begin
  if (active) begin
    if (integrator_d_int > max_integrator_windup) begin
      integrator_d_int <= max_integrator_windup;
    end else if (integrator_d_int < -max_integrator_windup) begin
      integrator_d_int <= -max_integrator_windup;
    end
    if (integrator_q_int > max_integrator_windup) begin
      integrator_q_int <= max_integrator_windup;
    end else if (integrator_q_int < -max_integrator_windup) begin
      integrator_q_int <= -max_integrator_windup;
    end
  end
end

// Calculate output values
assign integrator_d = integrator_d_int;
assign integrator_q = integrator_q_int;

endmodule

