module adxl362_system_controller (
   // Outputs
   output reg clk,
   output reg clk_sys,
   output wire reset,
   output wire clk_odr,
   output wire rst,
   // Inputs
   input wire soft_reset,
   input wire [2:0] odr
);

   // Reset Logic
   reg [5:0] reset_count = 0;
   reg por = 1;
   assign rst = |reset_count;

   always @(posedge clk_sys) begin
      if (por || soft_reset) begin
         reset_count <= 1;
         por <= 0;
      end else begin
         if (rst) begin
            reset_count <= reset_count + 1;
         end
      end
   end

   // Free Running 51.2 KHz clock
   initial begin
      clk <= 1'b0;
      forever begin
         #9803 clk <= ~clk;
      end
   end

   // Free Running clock
   // Added this in to work out SPI/Register access
   initial begin
      clk_sys <= 1'b0;
      forever begin
         #5 clk_sys <= ~clk_sys;
      end
   end

   // ODR clocks
   reg [31:0] clk_12_5_Hz_count = 0;
   reg [31:0] clk_25_Hz_count = 0;
   reg [31:0] clk_50_Hz_count = 0;
   reg [31:0] clk_100_Hz_count = 0;
   reg [31:0] clk_200_Hz_count = 0;
   reg [31:0] clk_400_Hz_count = 0;

   initial begin
      clk_12_5_Hz_count <= 0;
      clk_25_Hz_count <= 0;
      clk_50_Hz_count <= 0;
      clk_100_Hz_count <= 0;
      clk_200_Hz_count <= 0;
      clk_400_Hz_count <= 0;
   end

   always @(posedge clk_12_5_Hz) begin
      clk_12_5_Hz_count <= clk_12_5_Hz_count + 1;
   end

   always @(posedge clk_25_Hz) begin
      clk_25_Hz_count <= clk_25_Hz_count + 1;
   end

   always @(posedge clk_50_Hz) begin
      clk_50_Hz_count <= clk_50_Hz_count + 1;
   end

   always @(posedge clk_100_Hz) begin
      clk_100_Hz_count <= clk_100_Hz_count + 1;
   end

   always @(posedge clk_200_Hz) begin
      clk_200_Hz_count <= clk_200_Hz_count + 1;
   end

   always @(posedge clk_400_Hz) begin
      clk_400_Hz_count <= clk_400_Hz_count + 1;
   end

   // 12.5Hz ODR Clk
   reg clk_12_5_Hz;
   initial begin
      clk_12_5_Hz <= 0;
      forever begin
         #40000000 clk_12_5_Hz <= ~clk_12_5_Hz;
      end
   end

   // 25Hz ODR Clk
   reg clk_25_Hz;
   initial begin
      clk_25_Hz <= 0;
      forever begin
         #20000000 clk_25_Hz <= ~clk_25_Hz;
      end
   end

   // 50Hz ODR Clk
   reg clk_50_Hz;
   initial begin
      clk_50_Hz <= 0;
      forever begin
         #10000000 clk_50_Hz <= ~clk_50_Hz;
      end
   end

   // 100Hz ODR Clk
   reg clk_100_Hz;
   initial begin
      clk_100_Hz <= 0;
      forever begin
         #5000000 clk_100_Hz <= ~clk_100_Hz;
      end
   end

   // 200Hz ODR Clk
   reg clk_200_Hz;
   initial begin
      clk_200_Hz <= 0;
      forever begin
         #2500000 clk_200_Hz <= ~clk_200_Hz;
      end
   end

   // 400Hz ODR Clk
   reg clk_400_Hz;
   initial begin
      clk_400_Hz <= 0;
      forever begin
         #1250000 clk_400_Hz <= ~clk_400_Hz;
      end
   end

   assign clk_odr = (odr == 3'b000) ? clk_12_5_Hz :
                    (odr == 3'b001) ? clk_25_Hz :
                    (odr == 3'b010) ? clk_50_Hz :
                    (odr == 3'b011) ? clk_100_Hz :
                    (odr == 3'b100) ? clk_200_Hz : clk_400_Hz;

endmodule

