module DCT_IDCT (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 8; // number of input signals
parameter m = 8; // number of output signals

// DCT block
wire [m-1:0] dct_out;
genvar i, j;
generate
  for (i = 0; i < m; i = i + 1) begin : dct_rows
    assign dct_out[i] = 0;
    for (j = 0; j < n; j = j + 1) begin : dct_cols
      assign dct_out[i] = dct_out[i] + in[j] * cos((2*j+1)*i*PI/(2*n));
    end
    assign dct_out[i] = dct_out[i] * sqrt(2.0/m);
    if (i == 0) assign dct_out[i] = dct_out[i] * sqrt(1.0/2);
  end
endgenerate

// IDCT block
wire [n-1:0] idct_out;
genvar k, l;
generate
  for (k = 0; k < n; k = k + 1) begin : idct_rows
    assign idct_out[k] = 0;
    for (l = 0; l < m; l = l + 1) begin : idct_cols
      assign idct_out[k] = idct_out[k] + dct_out[l] * cos((2*k+1)*l*PI/(2*n));
    end
    assign idct_out[k] = idct_out[k] * sqrt(2.0/n);
    if (k == 0) assign idct_out[k] = idct_out[k] * sqrt(1.0/2);
  end
endgenerate

// assign outputs
assign out = idct_out;

endmodule

