module FSM (
  input clk,
  input rst,
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 2; // number of input signals
parameter m = 1; // number of output signals
parameter s = 4; // number of states in the original FSM

reg [s-1:0] state; // current state
reg [s-1:0] next_state; // next state
reg [m-1:0] output_reg; // output register

// Define the original FSM and its transitions
always @ (posedge clk) begin
  if (rst) begin
    state <= 0;
  end else begin
    case (state)
      0: begin
        if (in == 2'b00) begin
          next_state <= 1;
        end else if (in == 2'b01) begin
          next_state <= 2;
        end else begin
          next_state <= 0;
        end
      end
      1: begin
        if (in == 2'b00) begin
          next_state <= 1;
        end else if (in == 2'b01) begin
          next_state <= 3;
        end else begin
          next_state <= 0;
        end
      end
      2: begin
        if (in == 2'b00) begin
          next_state <= 3;
        end else if (in == 2'b01) begin
          next_state <= 2;
        end else begin
          next_state <= 0;
        end
      end
      3: begin
        if (in == 2'b00) begin
          next_state <= 1;
        end else if (in == 2'b01) begin
          next_state <= 2;
        end else begin
          next_state <= 0;
        end
      end
      default: next_state <= 0;
    endcase
  end
end

// Use state merging to reduce the number of states in the FSM
always @ (next_state) begin
  case (next_state)
    1, 3: begin
      output_reg <= 1;
    end
    2: begin
      output_reg <= 0;
    end
    default: output_reg <= 0;
  endcase
end

// Define the transitions between the merged states and the output signals
always @ (posedge clk) begin
  if (rst) begin
    state <= 0;
  end else begin
    state <= next_state;
  end
end

assign out = output_reg;

endmodule

