module up_down_counter (
    input [3:0] load_value,
    input up_down,
    input clk,
    input reset,
    output reg [3:0] count,
    output overflow
);

    reg [3:0] next_count;

    always @(posedge clk or negedge reset) begin
        if (reset == 0) begin
            count <= 0;
        end else if (up_down == 1) begin
            if (count == 15) begin
                next_count <= 0;
                overflow <= 1;
            end else begin
                next_count <= count + 1;
                overflow <= 0;
            end
        end else begin
            if (count == 0) begin
                next_count <= 15;
                overflow <= 1;
            end else begin
                next_count <= count - 1;
                overflow <= 0;
            end
        end

        if (load_value != count && up_down == 0) begin
            next_count <= load_value;
        end

        count <= next_count;
    end

endmodule

