module adder_subtractor (
    input clk,
    input reset,
    input [3:0] A, B,
    input SUB,
    output [3:0] out
);

    reg [3:0] result;

    always @(posedge clk) begin
        if (reset) begin
            result <= 4'b0;
        end else begin
            if (SUB) begin
                result <= A - B;
            end else begin
                result <= A + B;
            end
        end
    end

    assign out = result;

endmodule

