module booth_multiplier(
    input [7:0] a,
    input [7:0] b,
    input sub,
    output [7:0] result
);

    wire [15:0] p;
    wire [8:0] ac;
    wire [8:0] s;
    wire [8:0] m;

    assign p = {a, 8'b0} + ({b[7], b});
    assign ac = {b[7], b} + ({1'b0, b[7:1]});
    assign s = ac - {1'b0, b};
    assign m = (sub) ? {~b[7], ~b} + 8'b1 : {1'b0, b};

    ripple_carry_adder adder(
        .a(p[15:8]),
        .b(m[7:0]),
        .cin(1'b0),
        .s(result[7:0])
    );

    full_subtractor subtractor(
        .a(result[7:0]),
        .b(s[7:0]),
        .bin(sub),
        .s(result[7:0])
    );

endmodule

module ripple_carry_adder(
    input [7:0] a,
    input [7:0] b,
    input cin,
    output [7:0] s
);

    wire [7:0] c;

    assign c[0] = cin;
    genvar i;
    generate
        for (i = 1; i < 8; i = i + 1) begin
            assign c[i] = (a[i-1] & b[i-1]) | (a[i-1] & c[i-1]) | (b[i-1] & c[i-1]);
        end
    endgenerate

    assign s = {c[7], c[6:0] ^ a ^ b};

endmodule

module full_subtractor(
    input [7:0] a,
    input [7:0] b,
    input bin,
    output [7:0] s
);

    wire [7:0] b_inv;
    wire [7:0] c;

    assign b_inv = (bin) ? ~b : b;

    assign c[0] = (bin) ? 1'b1 : 1'b0;
    genvar i;
    generate
        for (i = 1; i < 8; i = i + 1) begin
            assign c[i] = (~a[i-1] & ~b_inv[i-1] & c[i-1]) | (~a[i-1] & b_inv[i-1] & ~c[i-1]) | (a[i-1] & ~b_inv[i-1] & ~c[i-1]) | (a[i-1] & b_inv[i-1] & c[i-1]);
        end
    endgenerate

    assign s = {c[7], c[6:0] ^ a ^ b_inv};

endmodule

module two_bit_adder (
    A,
    B,
    C_in,
    S,
    C_out
);

    // Module ports
    input [1:0] A;
    input [1:0] B;
    input C_in;
    output [1:0] S;
    output C_out;

    // Local signals
    wire carry_out_1;
    wire carry_out_2;

    //  Name      Output          Other arguments
    xor  xor0_1 (S[0]           , A[0], B[0]           );
    xor  xor0_2 (S[1]           , A[1], B[1]           );
    and  and0_1 (carry_out_1    , A[0], B[0]           );
    and  and0_2 (carry_out_2    , A[1], B[1]           );
    or   or0_1  (C_out          , carry_out_1, C_in   );
    or   or0_2  (C_out          , carry_out_2, C_out  );

endmodule

