module logic_gates(input [1:0] in, input [1:0] expect, output [1:0] out);

  // Bitwise AND operation
  assign out[0] = in[0] & in[1];

  // Bitwise OR operation
  assign out[1] = in[0] | in[1];

  // Bitwise XOR operation
  assign out[2] = in[0] ^ in[1];

  // Inverted bitwise AND operation
  assign out[3] = ~(in[0] & in[1]);

  // Inverted bitwise OR operation
  assign out[4] = ~(in[0] | in[1]);

  // Inverted bitwise XOR operation
  assign out[5] = ~(in[0] ^ in[1]);

  // Compare output to expected output
  always @* begin
    if (out[0] !== expect[0]) $display("FAILED reduction & with input %b, expected %b, got %b", in, expect[0], out[0]);
    if (out[1] !== expect[1]) $display("FAILED reduction | with input %b, expected %b, got %b", in, expect[1], out[1]);
    if (out[2] !== expect[2]) $display("FAILED reduction ^ with input %b, expected %b, got %b", in, expect[2], out[2]);
    if (out[3] !== ~expect[0]) $display("FAILED reduction ~& with input %b, expected %b, got %b", in, ~expect[0], out[3]);
    if (out[4] !== ~expect[1]) $display("FAILED reduction ~| with input %b, expected %b, got %b", in, ~expect[1], out[4]);
    if (out[5] !== ~expect[2]) $display("FAILED reduction ~^ with input %b, expected %b, got %b", in, ~expect[2], out[5]);
  end

endmodule

module fifo_buffer #(
    parameter BUF_SIZE = 10
) (
    input clock,
    input reset,
    input clear,
    input set_stb,
    input [7:0] set_addr,
    input [31:0] set_data,
    output buffer_full,
    input buffer_empty,
    output access_we,
    output access_stb,
    input access_ok,
    output access_done,
    output access_skip_read,
    output [BUF_SIZE-1:0] access_adr,
    input [BUF_SIZE-1:0] access_len,
    output [35:0] access_dat_o,
    input [35:0] access_dat_i
);

    reg [31:0] buffer[BUF_SIZE-1:0];
    reg [7:0] write_ptr;
    reg [7:0] read_ptr;
    reg [7:0] count;
    reg [7:0] set_data_reg;
    reg [7:0] set_addr_reg;
    reg set_stb_reg;
    wire ram_we;
    wire ram_stb;
    wire ram_ok;
    wire ram_done;
    wire ram_skip_read;
    wire [BUF_SIZE-1:0] ram_adr;
    wire [35:0] ram_dat_o;
    wire [BUF_SIZE-1:0] ram_len;
    wire [35:0] ram_dat_i;

    assign buffer_full = (count == BUF_SIZE);
    assign access_we = ram_we;
    assign access_stb = ram_stb;
    assign access_adr = ram_adr;
    assign access_dat_o = ram_dat_o;
    assign access_len = ram_len;
    assign access_skip_read = ram_skip_read;
    assign access_done = ram_done;

    always @(posedge clock) begin
        if (reset) begin
            write_ptr <= 0;
            read_ptr <= 0;
            count <= 0;
        end else if (clear) begin
            count <= 0;
        end else begin
            if (ram_done && !ram_skip_read && count > 0) begin
                read_ptr <= (read_ptr + ram_len) % BUF_SIZE;
                count <= count - ram_len;
            end
            if (!buffer_full && access_ok && ram_we && ram_ok) begin
                buffer[write_ptr] <= ram_dat_i;
                write_ptr <= (write_ptr + ram_len) % BUF_SIZE;
                count <= count + ram_len;
            end
        end
    end

    always @(posedge clock) begin
        if (reset) begin
            set_data_reg <= 0;
            set_addr_reg <= 0;
            set_stb_reg <= 0;
        end else begin
            if (set_stb) begin
                set_data_reg <= set_data;
                set_addr_reg <= set_addr;
                set_stb_reg <= 1;
            end else begin
                set_stb_reg <= 0;
            end
            case(set_addr_reg)
                8'h00: BUF_SIZE <= set_data_reg;
            endcase
        end
    end

    ram_interface ram_interface_inst (
        .clock(clock),
        .reset(reset),
        .clear(clear),
        .access_we(ram_we),
        .access_stb(ram_stb),
        .access_ok(ram_ok),
        .access_done(ram_done),
        .access_skip_read(ram_skip_read),
        .access_adr(ram_adr),
        .access_len(ram_len),
        .access_dat_o(ram_dat_o),
        .access_dat_i(ram_dat_i)
    );

endmodule

module ram_interface (
    input clock,
    input reset,
    input clear,
    output access_we,
    output access_stb,
    input access_ok,
    output access_done,
    output access_skip_read,
    output [BUF_SIZE-1:0] access_adr,
    input [BUF_SIZE-1:0] access_len,
    output [35:0] access_dat_o,
    input [35:0] access_dat_i
);

    reg [35:0] ram[BUF_SIZE-1:0];
    reg [31:0] addr;
    reg [31:0] len;
    reg we;
    reg stb;
    reg ok;
    reg done;
    reg skip_read;

    assign access_dat_o = ram[addr];
    assign access_done = done;

    always @(posedge clock) begin
        if (reset) begin
            addr <= 0;
            len <= 0;
            we <= 0;
            stb <= 0;
            ok <= 0;
            done <= 0;
            skip_read <= 0;
        end else if (clear) begin
            ok <= 0;
            done <= 0;
            skip_read <= 0;
        end else begin
            if (access_ok && !stb) begin
                addr <= access_adr;
                len <= access_len;
                we <= access_we;
                stb <= access_stb;
                ok <= 1;
            end else if (stb && ok) begin
                if (we) begin
                    ram[addr] <= access_dat_i;
                end
                done <= 1;
                stb <= 0;
            end else if (access_skip_read && ok) begin
                done <= 1;
                skip_read <= 1;
            end
        end
    end

endmodule

module top_module (
    input [3:0] a,
    input [3:0] b,
    input [2:0] op,
    input [2:0] select,
    output reg [3:0] result
);

    wire [7:0] decoder_out;
    wire [3:0] alu_out;
    wire [3:0] final_out;

    decoder_3to8 decoder_inst (
        .select(select),
        .out(decoder_out)
    );

    alu alu_inst (
        .a(a),
        .b(b),
        .op(op),
        .out(alu_out)
    );

    functional functional_inst (
        .decoder_out(decoder_out),
        .alu_out(alu_out),
        .result(final_out)
    );

    always @(*) begin
        case(final_out)
            4'b0001: result = ~decoder_out[0];
            4'b0010: result = ~decoder_out[1];
            4'b0011: result = ~decoder_out[2];
            4'b0100: result = ~decoder_out[3];
            4'b0101: result = ~decoder_out[4];
            4'b0110: result = ~decoder_out[5];
            4'b0111: result = ~decoder_out[6];
            4'b1000: result = ~decoder_out[7];
            default: result = 4'b0000;
        endcase
    end

endmodule

module decoder_3to8 (
    input [2:0] select,
    output reg [7:0] out
);

    always @(*) begin
        case(select)
            3'b000: out = 8'b00000001;
            3'b001: out = 8'b00000010;
            3'b010: out = 8'b00000100;
            3'b011: out = 8'b00001000;
            3'b100: out = 8'b00010000;
            3'b101: out = 8'b00100000;
            3'b110: out = 8'b01000000;
            3'b111: out = 8'b10000000;
            default: out = 8'b00000000;
        endcase
    end

endmodule

module alu (
    input [3:0] a,
    input [3:0] b,
    input [2:0] op,
    output reg [3:0] out
);

    always @(*) begin
        case(op)
            3'b000: out = a + b;
            3'b001: out = a - b;
            3'b010: out = a & b;
            3'b011: out = a | b;
            3'b100: out = a ^ b;
            3'b101: out = a << 1;
            default: out = 4'b0000;
        endcase
    end

endmodule

module functional (
    input [7:0] decoder_out,
    input [3:0] alu_out,
    output [3:0] result
);

    assign result = decoder_out & alu_out;

endmodule

module sonic_sensor_interface (
    input clk,
    input rst_32,
    input sig,
    input [31:0] din_32,
    input wr_en_32,
    input rd_en_32,
    output [31:0] dout_32,
    output reg full_32,
    output reg empty_32,
    output [31:0] out_data,
    output reg led
);

parameter INIT_32 = 0,
            READY_RCV_32 = 1,
            RCV_DATA_32 = 2,
            POSE_32 = 3,
            READY_SND_32 = 4,
            SND_DATA_32 = 5;

// for input fifo
wire [31:0] rcv_data_32;
wire rcv_en_32;
wire data_empty_32;
// for output fifo
wire [31:0] snd_data_32;
wire snd_en_32;
wire data_full_32;
// state register
reg [3:0] state_32;
reg req_sonic_sensor;
wire busy_sonic_sensor;

//instance for sonic_sensor
sonic_sensor sonic_sensor
(
.clk(clk),
.rst(rst_32),
.req(req_sonic_sensor),
.busy(busy_sonic_sensor),
.sig(sig),
.out_data(out_data),
.led(led)
);

// input fifo
fifo_32x512 input_fifo_32(
    .clk(clk),
    .srst(rst_32),
    .din(din_32),
    .wr_en(wr_en_32),
    .full(full_32),
    .dout(rcv_data_32),
    .rd_en(rcv_en_32),
    .empty(data_empty_32)
);

// output fifo
fifo_32x32 output_fifo_32(
    .clk(clk),
    .srst(rst_32),
    .din(snd_data_32),
    .wr_en(snd_en_32),
    .full(data_full_32),
    .dout(dout_32),
    .rd_en(rd_en_32),
    .empty(empty_32)
);

// process data
reg [31:0] processed_data;

always @(*) begin
    processed_data = rcv_data_32 + 1; // example processing
end

// state machine
always @(posedge clk) begin
    if (rst_32) begin
        state_32 <= INIT_32;
        full_32 <= 0;
        empty_32 <= 1;
    end else begin
        case (state_32)
            INIT_32: begin
                full_32 <= 0;
                empty_32 <= 1;
                state_32 <= READY_RCV_32;
            end
            READY_RCV_32: begin
                if (sig) begin
                    state_32 <= RCV_DATA_32;
                end
            end
            RCV_DATA_32: begin
                state_32 <= POSE_32;
            end
            POSE_32: begin
                if (busy_sonic_sensor == 0) begin
                    state_32 <= READY_SND_32;
                end
            end
            READY_SND_32: begin
                if (data_full_32 == 0) begin
                    state_32 <= SND_DATA_32;
                end
            end
            SND_DATA_32: begin
                state_32 <= READY_RCV_32;
            end
        endcase
    end
end

assign rcv_en_32 = (state_32 == RCV_DATA_32);
assign snd_en_32 = (state_32 == SND_DATA_32);
assign snd_data_32 = processed_data;

endmodule

