module restoring_divider(
    clk,
    ena,
    z,
    d,
    q,
    s,
    div0,
    ovf
);

parameter z_width = 64;
parameter d_width = 32;

input clk;
input ena;

input [z_width-1:0] z;
input [d_width-1:0] d;

output [d_width-1:0] q;
output [d_width-1:0] s;
output div0;
output ovf;

reg [z_width-1:0] z_reg;
reg [d_width-1:0] d_reg;
reg [d_width-1:0] q_reg;
reg [z_width:0] s_reg;
reg div0_reg;
reg ovf_reg;

wire [d_width:0] s_abs;
wire [d_width:1] q_abs;

assign s_abs = (s_reg[z_width]) ? ~{1'b0, s_reg[z_width-1:0]} + 1 : {1'b0, s_reg[z_width-1:0]};
assign q_abs = (q_reg[d_width-1]) ? ~q_reg[d_width-2:0] + 1 : q_reg[d_width-2:0];

always @(posedge clk) begin
    if (ena) begin
        z_reg <= z;
        d_reg <= d;
        q_reg <= 0;
        s_reg <= {z, 1'b0};
        div0_reg <= (d == 0);
        ovf_reg <= 0;
    end
end

integer i;
always @(posedge clk) begin
    if (ena) begin
        if (s_reg[z_width] == 1) begin
            s_reg <= {s_reg[z_width-1:0], 1'b0} + d_reg;
            q_reg[d_width-2:0] <= q_reg[d_width-2:0] << 1;
            q_reg[d_width-1] <= 0;
        end else begin
            s_reg <= {s_reg[z_width-1:0], 1'b0} - d_reg;
            q_reg[d_width-2:0] <= q_reg[d_width-2:0] << 1;
            q_reg[d_width-1] <= 1;
        end
        for (i = 0; i < d_width; i = i + 1) begin
            if (s_reg[z_width] == 1) begin
                s_reg <= {s_reg[z_width-1:0], 1'b0} + d_reg;
                q_reg[d_width-2:0] <= q_reg[d_width-2:0] << 1;
                q_reg[d_width-1] <= 0;
            end else begin
                s_reg <= {s_reg[z_width-1:0], 1'b0} - d_reg;
                q_reg[d_width-2:0] <= q_reg[d_width-2:0] << 1;
                q_reg[d_width-1] <= 1;
            end
        end
        if (s_reg[z_width] == 1) begin
            s_reg <= {s_reg[z_width-1:0], 1'b0} + d_reg;
            q_reg[d_width-2:0] <= q_reg[d_width-2:0] << 1;
            q_reg[d_width-1] <= 0;
        end
        if (s_reg[z_width] == 1 || s_abs > d_reg) begin
            s_reg <= s_reg + d_reg;
            q_reg[d_width-1] <= 0;
        end
        if (q_abs >= 2**d_width) begin
            ovf_reg <= 1;
        end
    end
end

assign q = q_reg[d_width-2:0];
assign s = s_reg[z_width-1:z_width-d_width];
assign div0 = div0_reg;
assign ovf = ovf_reg;

endmodule

