module binary_counter (
  input clk,
  input rst,
  output reg [2:0] count
);

  // Define the states
  parameter IDLE = 2'b00;
  parameter COUNTING = 2'b01;
  parameter RESET = 2'b10;

  // Define the current state and next state variables
  reg [1:0] current_state, next_state;

  // Define the counter variable
  reg [2:0] counter;

  // Assign the initial state to idle and the counter to 0
  initial begin
    current_state = IDLE;
    counter = 3'b000;
  end

  // Define the state machine
  always @ (posedge clk) begin
    // Set the next state based on the current state and inputs
    case (current_state)
      IDLE: begin
        if (rst) begin
          next_state = RESET;
        end else begin
          next_state = COUNTING;
        end
      end
      COUNTING: begin
        if (counter == 3'b111) begin
          next_state = IDLE;
        end else begin
          next_state = COUNTING;
        end
      end
      RESET: begin
        next_state = IDLE;
      end
    endcase

    // Set the current state to the next state
    current_state <= next_state;

    // Update the counter based on the current state
    case (current_state)
      COUNTING: begin
        counter <= counter + 1;
      end
      RESET: begin
        counter <= 3'b000;
      end
    endcase
  end

  // Assign the counter to the output
  assign count = counter;

endmodule

module alu8b (input wire [7:0] A_in,
              input wire [7:0] B_in,
              input wire       C_in,
              input wire [2:0] Opcode_in,
              output reg [7:0] Result_out,
              output reg       C_out);

  always @ ( * ) begin
    case (Opcode_in)
      3'b000: // A+B+Cin
              begin
                // perform addition with carry in
                {C_out, Result_out} = A_in + B_in + C_in;
              end
      3'b001: // A-B
              begin
                // perform subtraction
                Result_out = A_in - B_in;
                C_out = (A_in < B_in) ? 1 : 0; // set carry out if A_in < B_in
              end
      3'b010: // A & B
              begin
                // perform bitwise AND
                Result_out = A_in & B_in;
                C_out = 0; // no carry out for bitwise AND
              end
      3'b011: // A|B
              begin
                // perform bitwise OR
                Result_out = A_in | B_in;
                C_out = 0; // no carry out for bitwise OR
              end
      3'b100: // A % B
              begin
                // perform modulo operation
                Result_out = A_in % B_in;
                C_out = 0; // no carry out for modulo operation
              end
      default:
              begin
                // default case: set result to 0
                Result_out = 8'b0;
                C_out = 0;
              end
    endcase
  end
endmodule

