      rd_address <= 0;
      entries <= 0;
    end else begin
      case (rdwr)
        2'd1: begin
          // Write data
          if (!full) begin
            entries <= entries + 1;
            wr_address <= (wr_address == 1) ? 0 : (wr_address + 1);
          end
        end
        2'd2: begin
          // Read data
          if (!empty) begin
            entries <= entries - 1;
            rd_address <= (rd_address == 1) ? 0 : (rd_address + 1);
          end
        end
        2'd3: begin
          wr_address <= (wr_address == 1) ? 0 : (wr_address + 1);
          rd_address <= (rd_address == 1) ? 0 : (rd_address + 1);
        end
        default: begin
        end
      endcase
    end
  end

  always @(posedge clk) begin
    //Write data
    if (wr & !full) begin
      case (wr_address)
        1'd0: entry_0 <= wr_data;
        1'd1: entry_1 <= wr_data;
        default: begin
        end
      endcase
    end
  end

endmodule

module padder(in, byte_num, out);
    input      [31:0] in;
    input      [1:0]  byte_num;
    output reg [31:0] out;

    always @ (*)
      case (byte_num)
        0: out = 32'h1000000;
        1: out = {in[31:8], 8'h01};
        2: out = {in[31:16], 16'h0100};
        3: out = {in[31:24], 24'h010000};
      endcase
endmodule

module binary_to_serial_converter(
  input clk,
  input reset,
  input [7:0] in_data,
  output out_data
);

  reg [7:0] data_reg;
  reg [3:0] bit_counter;
  reg out_data_reg;

  always @(posedge clk, negedge reset) begin
    if(!reset) begin
      data_reg <= 0;
      bit_counter <= 0;
      out_data_reg <= 0;
    end else begin
      data_reg <= in_data;
      bit_counter <= 0;
      out_data_reg <= 0;
    end
  end

  always @(posedge clk) begin
    if(bit_counter < 8) begin
      out_data_reg <= data_reg[bit_counter];
      bit_counter <= bit_counter + 1;
    end else begin
      bit_counter <= 0;
    end
  end

  assign out_data = out_data_reg;

endmodule

