endmodule

module sequence_detector (
  input in,
  output out
);

  // Define the states
  parameter S0 = 2'b00;
  parameter S1 = 2'b01;
  parameter S2 = 2'b10;
  parameter S3 = 2'b11;

  // Define the state register and next state logic
  reg [1:0] state, next_state;
  always @ (state, in) begin
    case (state)
      S0: if (in) next_state = S1; else next_state = S0;
      S1: if (in) next_state = S2; else next_state = S0;
      S2: if (in) next_state = S3; else next_state = S0;
      S3: if (in) next_state = S3; else next_state = S0;
    endcase
  end

  // Define the output logic
  always @ (state) begin
    if (state == S3) out = 1'b1;
    else out = 1'b0;
  end

  // Assign the next state to the current state
  always @ (posedge clk) begin
    state <= next_state;
  end

endmodule

module Span12Mux_h5(input [11:0] I, output O);

  wire [4:0] intermediate_vector;
  wire [4:0] intermediate_select;

  Mux2to1 M1(.I(I[1:0]), .S(I[2]), .O(intermediate_vector[0]));
  Mux2to1 M2(.I(I[3:2]), .S(I[4]), .O(intermediate_vector[1]));
  Mux2to1 M3(.I(I[5:4]), .S(I[6]), .O(intermediate_vector[2]));
  Mux2to1 M4(.I(I[7:6]), .S(I[8]), .O(intermediate_vector[3]));
  Mux2to1 M5(.I(I[9:8]), .S(I[10]), .O(intermediate_vector[4]));

  assign intermediate_select[0] = I[11] & ~I[10] & ~I[9];
  assign intermediate_select[1] = I[11] & ~I[10] & I[9];
  assign intermediate_select[2] = I[11] & I[10] & ~I[8];
  assign intermediate_select[3] = I[11] & I[10] & I[8];
  assign intermediate_select[4] = ~I[11] & I[10] & I[9];

  Mux5to1 M6(.I(intermediate_vector), .S(intermediate_select), .O(O));

endmodule

module Mux2to1(input [1:0] I, input S, output O);
  assign O = (S == 1'b0) ? I[0] : I[1];
endmodule

module Mux5to1(input [4:0] I, input [4:0] S, output O);
  assign O = (S == 5'b00001) ? I[0] :
             (S == 5'b00010) ? I[1] :
             (S == 5'b00100) ? I[2] :
             (S == 5'b01000) ? I[3] :
             (S == 5'b10000) ? I[4] : 1'b0;
endmodule

