module addsub_4bit(
    input [3:0] A,
    input [3:0] B,
    input SUB,
    output [3:0] OUT
);

    wire [3:0] B_NEG;
    wire CARRY_IN;
    wire CARRY_OUT;

    assign B_NEG = ~B + 1;

    assign CARRY_IN = SUB & 1'b1;
    assign CARRY_OUT = (SUB & (A < B)) | (~SUB & (OUT < A+B));

    assign OUT = SUB ? A + B_NEG + CARRY_IN : A + B + CARRY_IN;

endmodule

module priority_encoder (
    input               clk,
    input               reset_n,
    input               locked,
    input       [15:0]  data_in,

    output reg [ 5:0]  dprio_address,
    output reg          dprio_read,
    output reg [ 1:0]  dprio_byteen,
    output reg          dprio_write,
    output reg [15:0]  dprio_writedata,

    output  reg         atpgmode,
    output  reg         mdio_dis,
    output  reg         scanen,
    output  reg         ser_shift_load,
    output  reg         dprio_init_done
);

    reg [1:0] rst_n = 2'b00;
    reg [6:0] count = 7'd0;
    reg [15:0] highest_data_in = 16'd0;
    reg [5:0] highest_index = 6'd0;
    reg [5:0] highest_priority = 6'd0;
    reg [5:0] current_address = 6'd0;
    reg [5:0] current_priority = 6'd0;
    reg [1:0] current_byteen = 2'd0;
    reg [15:0] current_writedata = 16'd0;
    reg [5:0] current_index = 6'd0;
    reg [5:0] i = 6'd0;
    reg [5:0] j = 6'd0;
    reg [15:0] data_temp = 16'd0;
    reg [5:0] priority_temp = 6'd0;
    reg [5:0] index_temp = 6'd0;

    // Internal versions of control signals
    wire  int_mdio_dis;
    wire  int_ser_shift_load;
    wire  int_dprio_init_done;
    wire  int_atpgmode/*synthesis keep*/;
    wire  int_scanen/*synthesis keep*/;

    assign  dprio_address   = current_address;
    assign  dprio_byteen    = current_byteen;
    assign  dprio_write     = dprio_writedata !== 16'd0;
    assign  dprio_read      = 1'b0;
    assign  dprio_writedata = current_writedata;

    assign  int_ser_shift_load  = 1'b1; 
    assign  int_mdio_dis        = 1'b1;
    assign  int_dprio_init_done = count === 7'd63;
    assign  int_atpgmode        = 1'b0;
    assign  int_scanen          = 1'b0;

    always @(posedge clk or negedge reset_n)
    begin
        if(!reset_n)  rst_n <= 2'b00;
        else          rst_n <= {rst_n[0],1'b1};
    end

    always @(posedge clk)
    begin
        if (~locked)
        begin
            if (dprio_writedata !== 16'd0)
            begin
                current_byteen <= 2'd3;
                current_writedata <= data_in;
            end
            else
            begin
                current_byteen <= 2'd0;
                current_writedata <= 16'd0;
            end

            if (count < 7'd64)
            begin
                current_address <= 6'd0;
                current_priority <= 6'd0;
            end
            else
            begin
                highest_data_in <= data_in;
                highest_index <= 6'd0;
                highest_priority <= 6'd0;

                for (i = 6'd0; i < 6'd16; i = i + 1)
                begin
                    data_temp <= highest_data_in;
                    priority_temp <= highest_priority;
                    index_temp <= highest_index;

                    for (j = i; j < 6'd16; j = j + 1)
                    begin
                        if (data_temp > highest_data_in)
                        begin
                            highest_data_in <= data_temp;
                            highest_priority <= priority_temp;
                            highest_index <= index_temp;
                        end

                        data_temp <= data_temp >> 1;
                        priority_temp <= priority_temp + 1;
                        index_temp <= index_temp + 1;
                    end

                    current_address <= highest_index;
                    current_priority <= highest_priority;
                    current_index <= highest_index;

                    if (dprio_writedata === 16'd0)
                    begin
                        highest_data_in <= 16'd0;
                        highest_index <= 6'd0;
                        highest_priority <= 6'd0;
                    end
                    else
                    begin
                        highest_data_in <= dprio_writedata;
                        highest_index <= current_index;
                        highest_priority <= current_priority;
                    end
                end
            end

            if (dprio_writedata === 16'd0 && count >= 7'd64)
            begin
                current_address <= highest_index;
                current_priority <= highest_priority;
            end

            if (count >= 7'd64)
            begin
                dprio_address <= current_address;
                dprio_byteen <= current_byteen;
                dprio_write <= dprio_writedata !== 16'd0;
                dprio_read <= 1'b0;
                dprio_writedata <= current_writedata;
            end

            count <= count + 1;
        end
    end

    always @(posedge clk)
    begin
        mdio_dis        <= int_mdio_dis;
        ser_shift_load  <= int_ser_shift_load;
        dprio_init_done <= int_dprio_init_done;
        atpgmode        <= int_atpgmode;
        scanen          <= int_scanen;
    end

endmodule

module dffrl_s (din, clk, rst_l, q, se, si, so);

parameter SIZE = 1;

input	[SIZE-1:0]	din ;	// data in
input			clk ;	// clk or scan clk
input			rst_l ;	// reset

output	[SIZE-1:0]	q ;	// output

input			se ;	// scan-enable
input	[SIZE-1:0]	si ;	// scan-input
output	[SIZE-1:0]	so ;	// scan-output

reg 	[SIZE-1:0]	q ;

`ifdef NO_SCAN
always @ (posedge clk)
	q[SIZE-1:0]  <= rst_l ? din[SIZE-1:0] : {SIZE{1'b0}};
`else

// Reset dominates
always @ (posedge clk)

	q[SIZE-1:0]  <= rst_l ? ((se) ? si[SIZE-1:0]  : din[SIZE-1:0] ) : {SIZE{1'b0}};

assign so[SIZE-1:0] = q[SIZE-1:0] ;
`endif

endmodule

module fifo_buffer (
  input clk,
  input [7:0] fifo_wdata,
  input fifo_wr,
  output fifo_FF,
  output [7:0] r_dat,
  output wfifo_empty,
  output [5:0] wfifo_used
);

  reg [7:0] buffer [0:63];
  reg [5:0] wr_ptr;
  reg [5:0] rd_ptr;
  reg [5:0] used;

  assign fifo_FF = used == 64;
  assign wfifo_empty = used == 0;
  assign wfifo_used = used;

  always @(posedge clk) begin
    if (fifo_wr && !fifo_FF) begin
      buffer[wr_ptr] <= fifo_wdata;
      wr_ptr <= wr_ptr + 1;
      used <= used + 1;
    end
    if (!wfifo_empty) begin
      r_dat <= buffer[rd_ptr];
      rd_ptr <= rd_ptr + 1;
      used <= used - 1;
    end
  end

endmodule

