module crossbar(clk, ctrl, in0, in1, in2, in3, out0, out1, out2, out3, valid_out0, valid_out1, valid_out2, valid_out3);

input clk;
input [1:0] ctrl;
input [15:0] in0, in1, in2, in3;
output [15:0] out0, out1, out2, out3;
output valid_out0, valid_out1, valid_out2, valid_out3;

reg [15:0] mem[0:15];
reg [15:0] temp_out0, temp_out1, temp_out2, temp_out3;
reg valid_temp_out0, valid_temp_out1, valid_temp_out2, valid_temp_out3;

always @(posedge clk) begin
    if (ctrl == 2'b00) begin
        temp_out0 <= in0;
        valid_temp_out0 <= 1'b1;
        temp_out1 <= in1;
        valid_temp_out1 <= 1'b1;
        temp_out2 <= in2;
        valid_temp_out2 <= 1'b1;
        temp_out3 <= in3;
        valid_temp_out3 <= 1'b1;
    end
    else if (ctrl == 2'b01) begin
        temp_out0 <= in1;
        valid_temp_out0 <= 1'b1;
        temp_out1 <= in0;
        valid_temp_out1 <= 1'b1;
        temp_out2 <= in3;
        valid_temp_out2 <= 1'b1;
        temp_out3 <= in2;
        valid_temp_out3 <= 1'b1;
    end
    else if (ctrl == 2'b10) begin
        temp_out0 <= in2;
        valid_temp_out0 <= 1'b1;
        temp_out1 <= in3;
        valid_temp_out1 <= 1'b1;
        temp_out2 <= in0;
        valid_temp_out2 <= 1'b1;
        temp_out3 <= in1;
        valid_temp_out3 <= 1'b1;
    end
    else if (ctrl == 2'b11) begin
        temp_out0 <= in3;
        valid_temp_out0 <= 1'b1;
        temp_out1 <= in2;
        valid_temp_out1 <= 1'b1;
        temp_out2 <= in1;
        valid_temp_out2 <= 1'b1;
        temp_out3 <= in0;
        valid_temp_out3 <= 1'b1;
    end
    else begin
        temp_out0 <= 16'h0000;
        valid_temp_out0 <= 1'b0;
        temp_out1 <= 16'h0000;
        valid_temp_out1 <= 1'b0;
        temp_out2 <= 16'h0000;
        valid_temp_out2 <= 1'b0;
        temp_out3 <= 16'h0000;
        valid_temp_out3 <= 1'b0;
    end
end

assign out0 = temp_out0;
assign out1 = temp_out1;
assign out2 = temp_out2;
assign out3 = temp_out3;

assign valid_out0 = valid_temp_out0;
assign valid_out1 = valid_temp_out1;
assign valid_out2 = valid_temp_out2;
assign valid_out3 = valid_temp_out3;

endmodule

