module serial_tx_fsm (
    input clk,
    input rst,
    input send,
    output reg txd,
    output reg [1:0] state,
    output reg [7:0] data
);

    // Define the states
    parameter IDLE = 2'b00;
    parameter START = 2'b01;
    parameter DATA = 2'b10;
    parameter STOP = 2'b11;

    // Define the bit count
    parameter BIT_COUNT = 10;

    // Define the data
    reg [7:0] data_reg;

    // Define the counter
    reg [3:0] count;

    // Define the FSM
    always @(posedge clk, posedge rst) begin
        if (rst) begin
            state <= IDLE;
            count <= 0;
            txd <= 1;
            data_reg <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (send) begin
                        state <= START;
                        count <= 0;
                        txd <= 0;
                        data_reg <= data;
                    end
                end
                START: begin
                    if (count == BIT_COUNT-1) begin
                        state <= DATA;
                        count <= 0;
                        txd <= 1;
                    end else begin
                        count <= count + 1;
                    end
                end
                DATA: begin
                    if (count == BIT_COUNT-1) begin
                        state <= STOP;
                        count <= 0;
                        txd <= 1;
                    end else begin
                        count <= count + 1;
                        txd <= data_reg[7];
                        data_reg <= {data_reg[6:0], 1'b0};
                    end
                end
                STOP: begin
                    if (count == BIT_COUNT-1) begin
                        state <= IDLE;
                        count <= 0;
                        txd <= 1;
                    end else begin
                        count <= count + 1;
                    end
                end
            endcase
        end
    end

endmodule

