module FlipFlop (
  input CLK,
  input D,
  input S,
  input R,
  input J,
  input K,
  output Q
);

parameter type = "D"; // type of flip-flop (D, JK, T, SR)

reg Q;

always @(posedge CLK) begin
  case (type)
    "D": Q <= D;
    "JK": if (CLK) begin
             if (J && !K) Q <= 1;
             else if (!J && K) Q <= 0;
             else if (J && K) Q <= ~Q;
           end
           else Q <= Q;
    "T": if (CLK) Q <= ~Q;
          else Q <= Q;
    "SR": if (S) Q <= 1;
           else if (R) Q <= 0;
           else Q <= Q;
  endcase
end

endmodule

