module top_module(
    input wire [7:0] in1,
    input wire [7:0] in2,
    output wire [7:0] out
);

    // Splitting inputs into 4-bit values
    split_1_4bit split1(in1, in1_hi, in1_lo);
    split_1_4bit split2(in2, in2_hi, in2_lo);

    // Adding corresponding 4-bit values
    adder_4bit add1(in1_hi, in2_hi, sum1);
    adder_4bit add2(in1_lo, in2_lo, sum2);

    // Adding the total sum
    adder_8bit add3(sum1, sum2, out_sum);

    // Dividing by 4 to get the average
    assign out = out_sum >> 2;

endmodule

