module shift_register (
    input clk, LOAD,
    input [7:0] DATA_IN,
    output [7:0] Q,
    output Q7
);

reg [7:0] shift_reg;

always @(posedge clk) begin
    if (LOAD) begin
        shift_reg <= DATA_IN;
    end else begin
        shift_reg <= {shift_reg[6:0], Q7};
    end
end

assign Q = shift_reg;
assign Q7 = shift_reg[7];

endmodule

module sliding_window_max (
    input clk,
    input [7:0] data_in,
    output [15:0] max_value,
    output valid
);

reg [7:0] window [0:7];
reg [3:0] max_index;

integer i;

always @(posedge clk) begin
    for (i = 7; i > 0; i = i - 1) begin
        window[i] <= window[i-1];
    end
    window[0] <= data_in;

    max_index <= 0;
    for (i = 1; i < 8; i = i + 1) begin
        if (window[i] > window[max_index]) begin
            max_index <= i;
        end
    end

    max_value <= {window[max_index], max_index};
    valid <= 1;
end

endmodule

module xor_module (
    input [15:0] max_value,
    input Q7,
    output xor_output
);

assign xor_output = max_value[Q7 ? 7 : max_value[3:0] + 8] ^ 1'b1;

endmodule

