assign Q = shift_reg_out;
assign max_value = max_value_out;
assign valid = valid_out;

endmodule

module exu_eclcomp8 (
  input [7:0] a,
  input [7:0] b,
  output result
);

  wire [7:0] xor_result;
  wire [3:0] first_nor_input;
  wire [3:0] second_nor_input;
  wire [2:0] third_nor_input;
  wire [2:0] nand_input;

  assign xor_result = a ^ b;
  assign first_nor_input = {~xor_result[7], ~xor_result[6], ~xor_result[5], ~xor_result[4]};
  assign second_nor_input = {~xor_result[3], ~xor_result[2], ~xor_result[1], ~xor_result[0]};
  assign third_nor_input = {~xor_result[4], ~xor_result[5], ~xor_result[6]};
  assign nand_input = {~second_nor_input[3], ~second_nor_input[2], ~second_nor_input[1], ~third_nor_input[2]};

  assign result = ~(|(first_nor_input) | |(second_nor_input) | ~(|(third_nor_input) | &(nand_input)));

endmodule

module four_bit_adder (A, B, Cin, S, Cout);

  input [3:0] A, B;
  input Cin;
  output [3:0] S;
  output Cout;

  wire [3:0] C;

  // Instantiate full-adder modules
  full_adder FA0(.A(A[0]), .B(B[0]), .Cin(Cin), .S(S[0]), .Cout(C[0]));
  full_adder FA1(.A(A[1]), .B(B[1]), .Cin(C[0]), .S(S[1]), .Cout(C[1]));
  full_adder FA2(.A(A[2]), .B(B[2]), .Cin(C[1]), .S(S[2]), .Cout(C[2]));
  full_adder FA3(.A(A[3]), .B(B[3]), .Cin(C[2]), .S(S[3]), .Cout(Cout));

endmodule

module full_adder (A, B, Cin, S, Cout);

  input A, B, Cin;
  output S, Cout;

  assign S = A ^ B ^ Cin;
  assign Cout = (A & B) | (Cin & (A ^ B));

endmodule

module top_module (
    input clk,
    input reset,
    input [3:0] DIN,
    input [15:0] A,
    input [15:0] B,
    input [3:0] S,
    output reg [15:0] Y,
    output reg [7:0] DAC_out,
    output reg [15:0] final_output
);

reg [3:0] DAC_input;
reg [7:0] DAC_out_reg;
reg [15:0] shifted_output;

// DAC module
always @ (posedge clk) begin
    if (reset) begin
        DAC_input <= 0;
        DAC_out_reg <= 0;
    end else begin
        DAC_input <= DIN;
        DAC_out_reg <= DAC_input * 64;
    end
end

assign DAC_out = DAC_out_reg;

// Barrel shifter module
always @ (A, B, S) begin
    case (S)
        4'b0000: shifted_output <= A;
        4'b1111: shifted_output <= B;
        default: begin
            shifted_output <= 0;
            for (i = 0; i < 16; i = i + 1) begin
                if (S[3] == 1) shifted_output[i] <= B[i];
                else shifted_output[i] <= A[i];
                if (S[2] == 1) shifted_output[i] <= shifted_output[i] << 1;
                if (S[1] == 1) shifted_output[i] <= shifted_output[i] << 1;
                if (S[0] == 1) shifted_output[i] <= shifted_output[i] << 1;
            end
        end
    endcase
end

// Final output module
always @ (DAC_out, shifted_output) begin
    final_output <= DAC_out + shifted_output;
end

endmodule

module axi_slave
    (input aclk,
     input aresetn_d,
     input [2:0] m_axi_arready,
     input [2:0] m_axi_awready,
     input [2:0] m_axi_rvalid,
     input [2:0] m_axi_bvalid,
     input aa_rready,
     input [1:0] Q,
     input [0:0] SR,
     input [0:0] mi_rvalid,
     input [3:3] mi_arready,
     input [0:0] mi_bvalid,
     input [2:0] mi_wready,
     output reg [1:0] m_ready_d,
     output reg m_valid_i_reg,
     output reg [2:0] m_axi_arready,
     output reg [2:0] m_axi_awready,
     output reg [2:0] m_axi_rvalid,
     output reg [2:0] m_axi_bvalid
    );

    reg [2:0] mi_arready_reg;
    reg [2:0] mi_wready_reg;
    reg [2:0] mi_rvalid_reg;
    reg [2:0] mi_bvalid_reg;
    reg [1:0] m_ready_d_reg;
    reg m_valid_i_reg_reg;

    always @(posedge aclk or negedge aresetn_d) begin
        if (!aresetn_d) begin
            mi_arready_reg <= 3'b0;
            mi_wready_reg <= 3'b0;
            mi_rvalid_reg <= 3'b0;
            mi_bvalid_reg <= 3'b0;
            m_ready_d_reg <= 2'b0;
            m_valid_i_reg_reg <= 1'b0;
        end else begin
            mi_arready_reg <= mi_arready;
            mi_wready_reg <= mi_wready;
            mi_rvalid_reg <= mi_rvalid;
            mi_bvalid_reg <= mi_bvalid;
            m_ready_d_reg <= {mi_arready_reg[1], mi_arready_reg[2]};
            m_valid_i_reg_reg <= mi_rvalid_reg[0];
        end
    end

    assign m_axi_arready = m_axi_arready & mi_arready_reg;
    assign m_axi_awready = m_axi_awready & mi_wready_reg;
    assign m_axi_rvalid = m_axi_rvalid & mi_rvalid_reg;
    assign m_axi_bvalid = m_axi_bvalid & mi_bvalid_reg;

    always @(posedge aclk or negedge aresetn_d) begin
        if (!aresetn_d) begin
            m_ready_d <= 2'b0;
            m_valid_i_reg <= 1'b0;
        end else begin
            m_ready_d <= m_ready_d_reg;
            m_valid_i_reg <= m_valid_i_reg_reg;
        end
    end

endmodule

