module vga_color_generator (
    input clk,
    input rst,
    input [9:0] x,
    input [9:0] y,
    input hsync,
    input vsync,
    output reg [7:0] r,
    output reg [7:0] g,
    output reg [7:0] b
);

reg [9:0] h_count;
reg [9:0] v_count;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        h_count <= 10'h0;
        v_count <= 10'h0;
    end else begin
        if (hsync == 0) begin
            if (h_count == 799) begin
                h_count <= 10'h0;
                if (vsync == 0) begin
                    if (v_count == 524) begin
                        v_count <= 10'h0;
                    end else begin
                        v_count <= v_count + 1;
                    end
                end
            end else begin
                h_count <= h_count + 1;
            end
        end
    end
end

reg [7:0] color;

always @(*) begin
    if (h_count < 8 || h_count >= 792 || v_count < 8 || v_count >= 488) begin
        color = 8'h0;
    end else if (h_count < 648) begin
        color = {8'h0, 8'h0, h_count[5:0]};
    end else begin
        color = {8'h0, 8'h0, 8'hff - (h_count[5:0] - 8'h8)};
    end
end

always @(posedge clk or posedge rst) begin
    if (rst) begin
        r <= 8'h0;
        g <= 8'h0;
        b <= 8'h0;
    end else begin
        if (hsync == 0 && vsync == 0) begin
            r <= color;
            g <= color;
            b <= color;
        end else begin
            r <= 8'h0;
            g <= 8'h0;
            b <= 8'h0;
        end
    end
end

endmodule

module Comparator
   (CO,
    Q,
    zero_flag,
    DI,
    S,
    Q_reg_15,
    Q_reg_15_0,
    Q_reg_23,
    Q_reg_23_0,
    Q_reg_30,
    Q_reg_30_0,
    Q_reg_10,
    Q_reg_22,
    Q_reg_30_1,
    Q_reg_0,
    Q_reg_0_0,
    Q_reg_31);

  output CO;
  output Q;
  output zero_flag;
  input [31:0] DI;
  input [31:0] S;
  input [3:0] Q_reg_15;
  input [3:0] Q_reg_15_0;
  input [3:0] Q_reg_23;
  input [3:0] Q_reg_23_0;
  input [3:0] Q_reg_30;
  input [3:0] Q_reg_30_0;
  input [3:0] Q_reg_10;
  input [3:0] Q_reg_22;
  input [2:0] Q_reg_30_1;
  input Q_reg_0;
  input Q_reg_0_0;
  input [3:0] Q_reg_31;

  wire [31:0] diff;
  assign diff = DI - S;

  // Internal registers
  reg [3:0] Q_reg [0:31];
  always @(posedge clk) begin
    if (reset) begin
      Q_reg <= 0;
    end else begin
      Q_reg[0] <= Q_reg_0 ? diff[3:0] : Q_reg[0];
      Q_reg[0] <= Q_reg_0_0 ? 0 : Q_reg[0];
      Q_reg[10] <= eqXY(Q_reg[0], Q, Q_reg[0]) ? 4'b1111 : Q_reg[10];
      Q_reg[15] <= Q_reg_15;
      Q_reg[15] <= eqXY(Q_reg[15], Q, Q_reg[15_0]) ? 4'b1111 : Q_reg[15];
      Q_reg[22] <= eqXY(Q_reg[23], Q, Q_reg[22]) ? 4'b1111 : Q_reg[22];
      Q_reg[23] <= Q_reg_23;
      Q_reg[23] <= eqXY(Q_reg[23], Q, Q_reg[23_0]) ? 4'b1111 : Q_reg[23];
      Q_reg[30] <= Q_reg_30;
      Q_reg[30] <= eqXY(Q_reg[30], Q, Q_reg[30_0]) ? 4'b1111 : Q_reg[30];
      Q_reg[30] <= gtXY(Q_reg[30], Q_reg[23], Q_reg[23_0], Q_reg[22], Q_reg[15], Q_reg[15_0], Q_reg[10], Q_reg[0]) ? 4'b1111 : Q_reg[30];
      Q_reg[31] <= Q_reg_31;
    end
  end

  // Output signals
  assign CO = gtXY(Q_reg[31], Q_reg[30], Q_reg[30_1], Q_reg[23], Q_reg[22], Q_reg[15], Q_reg[10], Q_reg[0]);
  assign Q = eqXY(Q_reg[31], Q, S[31:31]);
  assign zero_flag = (DI == 0);

  // Helper functions
  function eqXY;
    input [3:0] X;
    input Y;
    input [3:0] Y_;
    begin
      eqXY = (X == Y) ? 1'b1 : (X == Y_) ? 1'b1 : 1'b0;
    end
  endfunction

  function gtXY;
    input [3:0] X;
    input [3:0] Y;
    input [3:0] Y_;
    input [3:0] X_;
    input [3:0] W;
    input [3:0] W_;
    input [3:0] V;
    input [3:0] V_;
    begin
