module mag_comp (
    input [3:0] A,
    input [3:0] B,
    output EQ
);

    wire [3:0] diff;
    wire [3:0] gt;
    wire [3:0] eq;
    wire [3:0] lt;

    // Calculate A - B
    // We can use a ripple carry adder with B negated and a carry-in of 1
    // to get the two's complement of B, and then add A to it.
    // This gives us A - B.
    ripple_carry_adder #(.WIDTH(4)) sub (
        .A(A),
        .B(~B + 1),
        .CIN(1),
        .SUM(diff),
        .COUT()
    );

    // Calculate A > B
    // We can use a full adder and an AND gate to compare each bit of A and B.
    // We start with the most significant bit, and use the carry-out of the full adder
    // as the input carry for the next full adder.
    // If A is greater than B, the most significant bit of diff will be 0, and the
    // corresponding bit of gt will be 1.
    full_adder fa0 (
        .A(A[3]),
        .B(B[3]),
        .CIN(1),
        .SUM(gt[3]),
        .COUT()
    );
    assign eq[3] = ~(A[3] ^ B[3]) & gt[3];
    full_adder fa1 (
        .A(A[2]),
        .B(B[2]),
        .CIN(gt[3]),
        .SUM(gt[2]),
        .COUT()
    );
    assign eq[2] = ~(A[2] ^ B[2]) & gt[2];
    full_adder fa2 (
        .A(A[1]),
        .B(B[1]),
        .CIN(gt[2]),
        .SUM(gt[1]),
        .COUT()
    );
    assign eq[1] = ~(A[1] ^ B[1]) & gt[1];
    full_adder fa3 (
        .A(A[0]),
        .B(B[0]),
        .CIN(gt[1]),
        .SUM(gt[0]),
        .COUT()
    );
    assign eq[0] = ~(A[0] ^ B[0]) & gt[0];

    // Calculate A < B
    // We can use a full adder and an AND gate to compare each bit of A and B.
    // We start with the most significant bit, and use the carry-out of the full adder
    // as the input carry for the next full adder.
    // If A is less than B, the most significant bit of diff will be 1, and the
    // corresponding bit of lt will be 1.
    full_adder fa4 (
        .A(A[3]),
        .B(B[3]),
        .CIN(1),
        .SUM(lt[3]),
        .COUT()
    );
    full_adder fa5 (
        .A(A[2]),
        .B(B[2]),
        .CIN(lt[3]),
        .SUM(lt[2]),
        .COUT()
    );
    full_adder fa6 (
        .A(A[1]),
        .B(B[1]),
        .CIN(lt[2]),
        .SUM(lt[1]),
        .COUT()
    );
    full_adder fa7 (
        .A(A[0]),
        .B(B[0]),
        .CIN(lt[1]),
        .SUM(lt[0]),
        .COUT()
    );

    // EQ is high if all bits of eq are high
    assign EQ = &(eq);

endmodule

