module sound_selector(
    input clock,
    input lrck,
    input reset,
    input [1:0] sound_code,
    output reg [15:0] left_data,
    output reg [15:0] right_data
);

reg [31:0] phase_accumulator;
reg [3:0] square_wave_counter;
reg [15:0] triangle_wave_value;

always @(posedge clock) begin
    if (reset) begin
        phase_accumulator <= 0;
        square_wave_counter <= 0;
        triangle_wave_value <= 0;
        left_data <= 0;
        right_data <= 0;
    end else begin
        case (sound_code)
            2'b00: begin // Sine wave
                left_data <= 16'h7FFF * $sin(phase_accumulator[15:0]);
                right_data <= left_data;
                phase_accumulator <= phase_accumulator + 2**(32-18);
            end
            2'b01: begin // Square wave
                if (square_wave_counter < 7) begin
                    left_data <= 16'h7FFF;
                    right_data <= left_data;
                end else begin
                    left_data <= 16'h8000;
                    right_data <= left_data;
                end
                square_wave_counter <= square_wave_counter + 1;
                if (square_wave_counter == 15) begin
                    square_wave_counter <= 0;
                end
            end
            2'b10: begin // Sawtooth wave
                left_data <= 16'h7FFF * (phase_accumulator[15:0] - 32768) / 32768;
                right_data <= left_data;
                phase_accumulator <= phase_accumulator + 2**(32-18);
            end
            2'b11: begin // Triangle wave
                if (phase_accumulator[15]) begin
                    triangle_wave_value <= 16'h7FFF - (phase_accumulator[15:0] - 32768) * 2;
                end else begin
                    triangle_wave_value <= (phase_accumulator[15:0] - 32768) * 2 - 16'h8000;
                end
                left_data <= triangle_wave_value;
                right_data <= left_data;
                phase_accumulator <= phase_accumulator + 2**(32-17);
            end
        endcase
        if (lrck) begin
            phase_accumulator <= 0;
        end
    end
end

endmodule

module top_module (
    input clk,
    input reset,
    input [3:0] A,
    input [3:0] B,
    input [15:0] in0,
