// Control logic module
always @(posedge clk or posedge reset) begin
    if (reset) begin
        enable_mult <= 1'b0;
        enable_add_sub <= 1'b0;
    end else begin
        enable_mult <= ~select;
        enable_add_sub <= select;
    end
end

