module barrel_shifter_decoder (
    input [15:0] in,
    input [3:0] ctrl,
    output reg [15:0] out
);

    wire [15:0] shifted_in;
    wire [15:0] decoded_out;

    // Instantiate barrel shifter and decoder modules
    barrel_shifter shifter(.in(in), .ctrl(ctrl), .out(shifted_in));
    decoder decoder(.in(decoded_out), .sel(shifted_in));

    // Output unchanged input when ctrl is 0
    always @(*) begin
        if (ctrl == 0) begin
            out = in;
        end
    end

    // Shift input left when ctrl is positive and decode the shifted output
    always @(*) begin
        if (ctrl > 0) begin
            out = 16'b0;
            shifted_in = in << ctrl;
            decoded_out = 16'b0;
            decoded_out[ctrl-1:0] = shifted_in[15:ctrl];
            out[decoded_out] = 1'b1;
        end
    end

    // Shift input right when ctrl is negative and decode the shifted output
    always @(*) begin
        if (ctrl < 0) begin
            out = 16'b0;
            shifted_in = in >> abs(ctrl);
            decoded_out = 16'b0;
            decoded_out[15-abs(ctrl)-1:0] = shifted_in[15:abs(ctrl)];
            out[decoded_out] = 1'b1;
        end
    end

endmodule

// Barrel shifter module
module barrel_shifter (
    input [15:0] in,
    input [3:0] ctrl,
    output reg [15:0] out
);

    always @(*) begin
        case (ctrl)
            4'b0000: out = in;
            4'b0001: out = in << 1;
            4'b0010: out = in << 2;
            4'b0011: out = in << 3;
            4'b0100: out = in << 4;
            4'b0101: out = in << 5;
            4'b0110: out = in << 6;
            4'b0111: out = in << 7;
            4'b1000: out = in << 8;
            4'b1001: out = in << 9;
            4'b1010: out = in << 10;
            4'b1011: out = in << 11;
            4'b1100: out = in << 12;
            4'b1101: out = in << 13;
            4'b1110: out = in << 14;
            4'b1111: out = in << 15;
        endcase
    end

endmodule

// Decoder module
module decoder (
    input [15:0] in,
    output reg [15:0] out,
    input [3:0] sel
);

    always @(*) begin
        case (sel)
            4'b0000: out = 16'b0000000000000001;
            4'b0001: out = 16'b0000000000000010;
            4'b0010: out = 16'b0000000000000100;
            4'b0011: out = 16'b0000000000001000;
            4'b0100: out = 16'b0000000000010000;
            4'b0101: out = 16'b0000000000100000;
            4'b0110: out = 16'b0000000001000000;
            4'b0111: out = 16'b0000000010000000;
            4'b1000: out = 16'b0000000100000000;
            4'b1001: out = 16'b0000001000000000;
            4'b1010: out = 16'b0000010000000000;
            4'b1011: out = 16'b0000100000000000;
            4'b1100: out = 16'b0001000000000000;
            4'b1101: out = 16'b0010000000000000;
            4'b1110: out = 16'b0100000000000000;
            4'b1111: out = 16'b1000000000000000;
        endcase
    end

endmodule

