module top_module (
    input clk,
    input reset,
    input shift_parallel,
    input select,
    output reg [4:0] out
);

    reg [3:0] counter_out;
    reg [3:0] shift_reg_out;
    wire [4:0] adder_out;

    binary_counter counter_inst (
        .RST(reset),
        .Q(counter_out)
    );

    shift_reg_4bit shift_reg_inst (
        .clk(clk),
        .shift_parallel(shift_parallel),
        .parallel_in(counter_out),
        .out(shift_reg_out)
    );

    adder adder_inst (
        .a(shift_reg_out),
        .b(counter_out),
        .sum(adder_out)
    );

    always @(posedge clk) begin
        if (reset) begin
            out <= 0;
        end else begin
            if (select) begin
                out <= shift_reg_out;
            end else begin
                out <= counter_out;
            end
        end
    end

endmodule

module binary_counter (
    input RST,
    output reg [3:0] Q
);
    always @(posedge clk or negedge RST) begin
        if (RST == 0) begin
            Q <= 0;
        end else begin
            Q <= Q + 1;
        end
    end
endmodule

module shift_reg_4bit (
    input clk,
    input shift_parallel,
    input [3:0] parallel_in,
    output reg [3:0] out
);
    always @(posedge clk) begin
        if (shift_parallel) begin
            out <= parallel_in;
        end else begin
            out <= {out[2:0], out[3]};
        end
    end
endmodule

module adder (
    input [3:0] a,
    input [3:0] b,
    output reg [4:0] sum
);
    always @(a, b) begin
        sum <= {1'b0, a} + {1'b0, b};
    end
endmodule

