module hybrid_pwm_sd
(
    input clk,
    input n_reset,
    input [15:0] din,
    output dout
);

    reg [4:0] pwmcounter;
    reg [4:0] pwmthreshold;
    reg [33:0] scaledin;
    reg [15:0] sigma;
    reg out;

    assign dout = out;

    always @(posedge clk, negedge n_reset)
    begin
        if (!n_reset)
        begin
            sigma <= 16'b00000100_00000000;
            pwmthreshold <= 5'b10000;
            pwmcounter <= 5'd0;
            scaledin <= 34'd0;
        end
        else
        begin
            pwmcounter <= pwmcounter + 1;

            if (pwmcounter == pwmthreshold)
                out <= 1'b0;

            if (pwmcounter == 5'b11111)
            begin
                scaledin <= (1<<(16-5))<<16 + din*61440;
                sigma <= scaledin[31:16] + {5'b000000, sigma[10:0]};
                pwmthreshold <= sigma[15:11];
                out <= 1'b1;
            end
            else
            begin
                out <= 1'b1;
            end
        end
    end

endmodule

module rcswitch_receive(
    input clk, 
    input rst,
    input in,
    output [39:0] addr,
    output [39:0] chan,
    output [15:0] stat,
    output ready
);

    reg [8:0] count;
    reg [95:0] msg;

    reg [39:0] r_addr;
    reg [39:0] r_chan;
    reg [15:0] r_stat;

    reg r_ready;

    initial begin
        count   <= 0;
        msg     <= 0;
        r_addr  <= 0;
        r_chan  <= 0;
        r_stat  <= 0;
        r_ready <= 0;
    end

    wire [31:0] count_h;
    wire [31:0] count_l;
    wire detected;

    tri_state_detect tsd_inst (
        .clk(clk),
        .rst(rst),
        .in(in),
        .count_h(count_h),
        .count_l(count_l),
        .detected(detected)
    );

    always @(posedge detected or posedge rst) begin

        if(rst) begin
            count   <= 0;
            r_addr  <= 0;
            r_chan  <= 0;
            r_stat  <= 0;
            r_ready <= 0;
        end
        else begin

            // detected SYNC
            if(count_h * 10 < count_l) begin
                count <= 0;
                msg <= 0;
            end 
            // detected 1000
            else if(count_h < count_l) begin
                msg <= (msg << 4) | 96'b1000;
                count <= count + 1;
            end 
            // detected 1110
            else if(count_l < count_h) begin
                msg <= (msg << 4) | 96'b1110;
                count <= count + 1;
            end

            // message complete?
            if(count == 24) begin    
                {r_addr[39:0], r_chan[39:0], r_stat[15:0]} <= msg;
                r_ready <= 1;
                count <= 0;
                msg <= 0;
            end    
            else begin
                r_ready <= 0;
            end
        end

    end

    assign ready = r_ready;
    assign addr  = r_addr;
    assign chan  = r_chan;
    assign stat  = r_stat;

endmodule

module full_adder (
    input A,
    input B,
    input CI,
    output SUM,
    output COUT
);

    wire xor1_out;
    wire xor2_out;
    wire and1_out;
    wire and2_out;
    wire or1_out;

    xor xor1(xor1_out, A, B);
    xor xor2(SUM, xor1_out, CI);
    and and1(and1_out, A, B);
    and and2(and2_out, xor1_out, CI);
    or or1(or1_out, and1_out, and2_out);
    assign COUT = or1_out;

endmodule

module add_module #
  (
   parameter A_WL = 16,
   parameter B_WL = 16
   )
   (
    input logic                   aclk,
    input logic                   areset,
    input logic signed [A_WL-1:0] a_tdata,
    input logic                   a_tvalid,
    input logic signed [B_WL-1:0] b_tdata,
    input logic                   b_tvalid,
    output logic signed [max(A_WL, B_WL)-1:0] c_tdata,
    output logic                   c_tvalid
    );

    // Register to synchronize the valid signals
    logic a_tvalid_sync;
    logic b_tvalid_sync;

    // Register to hold the sum of the input data streams
    logic signed [max(A_WL, B_WL):0] sum_reg;

    // Combinational logic to determine if both input streams are valid
    logic both_valid;
    assign both_valid = a_tvalid_sync & b_tvalid_sync;

    // Synchronize the input valid signals
    always_ff @(posedge aclk, negedge areset) begin
        if (~areset) begin
            a_tvalid_sync <= 0;
            b_tvalid_sync <= 0;
        end
        else begin
            a_tvalid_sync <= a_tvalid;
            b_tvalid_sync <= b_tvalid;
        end
    end

    // Combinational logic to calculate the sum of the input data streams
    always_comb begin
        if (both_valid) begin
            sum_reg <= a_tdata + b_tdata;
        end
    end

    // Register to hold the output data stream
    logic signed [max(A_WL, B_WL):0] c_tdata_reg;

    // Register to synchronize the output valid signal
    logic c_tvalid_sync;

    // Synchronize the output valid signal and output data stream
    always_ff @(posedge aclk, negedge areset) begin
        if (~areset) begin
            c_tvalid_sync <= 0;
            c_tdata_reg <= 0;
        end
        else begin
            c_tvalid_sync <= both_valid;
            c_tdata_reg <= sum_reg;
        end
    end

    // Assign the output ports
    assign c_tvalid = c_tvalid_sync;
    assign c_tdata = c_tdata_reg;

endmodule

