    if (reset) begin
        shift_reg <= 100'b0;
        out <= 100'b0;
    end else begin
        if (load) begin
            shift_reg <= in;
            out <= in;
        end else begin
            if (ena == 2'b01) begin // right shift
                shift_reg <= {shift_reg[0], shift_reg[99:1]};
                out <= shift_reg;
            end else if (ena == 2'b10) begin // left shift
                shift_reg <= {shift_reg[98:0], shift_reg[99]};
                out <= shift_reg;
            end else begin // no shift
                out <= shift_reg;
            end
        end
    end
