module fifo_24in_24out_12kb (
    input clk,
    input rd_en,
    input [0:0] E,
    input [0:0] Q,
    input [23:0] din,
    output [23:0] dout,
    output [11:0] count
);

    // Declare internal signals
    reg [23:0] mem [0:23];
    reg [11:0] wr_ptr = 0;
    reg [11:0] rd_ptr = 0;
    reg [11:0] cnt = 0;
    reg [11:0] next_wr_ptr = 0;
    reg [11:0] next_rd_ptr = 0;
    reg [11:0] next_cnt = 0;
    wire mem_full = (cnt == 24);
    wire mem_empty = (cnt == 0);

    // Write logic
    always @ (posedge clk) begin
        if (E) begin
            next_wr_ptr = wr_ptr + 1;
            if (next_wr_ptr == 24) begin
                next_wr_ptr = 0;
            end
            if (!mem_full) begin
                mem[wr_ptr] <= din;
                next_cnt = cnt + 1;
            end
        end
    end

    // Read logic
    always @ (posedge clk) begin
        if (Q) begin
            next_rd_ptr = rd_ptr + 1;
            if (next_rd_ptr == 24) begin
                next_rd_ptr = 0;
            end
            if (!mem_empty && rd_en) begin
                dout <= mem[rd_ptr];
                next_cnt = cnt - 1;
            end
        end
    end

    // Update state
    always @ (posedge clk) begin
        wr_ptr <= next_wr_ptr;
        rd_ptr <= next_rd_ptr;
        cnt <= next_cnt;
    end

    // Output count
    assign count = cnt;

endmodule

module priority_encoder (
    input [7:0] in,
    output reg [1:0] pos
);

wire [7:0] inv_in = ~in;
wire [3:0] priority;
wire [1:0] final_priority;

assign priority[0] = in[0];
assign priority[1] = in[1] & inv_in[0];
assign priority[2] = in[2] & inv_in[1:0];
assign priority[3] = in[3] & inv_in[2:0];
assign priority[4] = in[4] & inv_in[3:0];
assign priority[5] = in[5] & inv_in[4:0];
assign priority[6] = in[6] & inv_in[5:0];
assign priority[7] = in[7] & inv_in[6:0];

assign final_priority[0] = (priority[0] | priority[1] | priority[2] | priority[3]) ? 0 : 1;
assign final_priority[1] = (priority[4] | priority[5] | priority[6] | priority[7]) ? 0 : 1;

always @* begin
    if (final_priority[0]) begin
        if (priority[0]) pos = 0;
        else if (priority[1]) pos = 1;
        else if (priority[2]) pos = 2;
        else if (priority[3]) pos = 3;
    end else if (final_priority[1]) begin
        if (priority[4]) pos = 4;
        else if (priority[5]) pos = 5;
        else if (priority[6]) pos = 6;
        else if (priority[7]) pos = 7;
    end else pos = 8;
end

endmodule

module top_module (
    input [7:0] in,
    output reg [1:0] pos1,
    output reg [1:0] pos2,
    output reg [1:0] final_pos
);

wire [1:0] priority1;
wire [1:0] priority2;

priority_encoder pe1(.in(in[3:0]), .pos(priority1));
priority_encoder pe2(.in(in), .pos(priority2));

always @* begin
    if (priority1[0] > priority2[0]) final_pos = priority1;
    else if (priority2[0] > priority1[0]) final_pos = priority2;
    else if (priority1[1] > priority2[1]) final_pos = priority1;
    else if (priority2[1] > priority1[1]) final_pos = priority2;
    else final_pos = priority1;
end

assign pos1 = (priority1 == 2'b10) ? 2'b00 : priority1;
assign pos2 = (priority2 == 2'b10) ? 2'b00 : priority2;

endmodule

