module fifo_generator(
    input wr_clk,
    input wr_en,
    input [31:0] din,
    input rst,
    output rd_clk,
    output reg rd_en,
    output [31:0] dout,
    output empty,
    output full,
    output [4:0] wr_data_count,
    output [4:0] rd_data_count,
    output prog_empty,
    output prog_full
);

    reg [31:0] fifo [0:15];
    reg [3:0] wr_ptr = 0;
    reg [3:0] rd_ptr = 0;
    reg [4:0] wr_count = 0;
    reg [4:0] rd_count = 0;
    wire [3:0] next_wr_ptr;
    wire [3:0] next_rd_ptr;
    wire [4:0] next_wr_count;
    wire [4:0] next_rd_count;
    wire empty_n;
    wire full_n;

    assign next_wr_ptr = wr_ptr + 1;
    assign next_rd_ptr = rd_ptr + 1;
    assign next_wr_count = wr_count + 1;
    assign next_rd_count = rd_count - 1;

    assign empty_n = (wr_count != rd_count);
    assign full_n = (wr_count != 16);

    always @(posedge wr_clk) begin
        if (rst) begin
            wr_ptr <= 0;
            rd_ptr <= 0;
            wr_count <= 0;
            rd_count <= 0;
            rd_en <= 0;
        end else begin
            if (wr_en && full_n) begin
                fifo[wr_ptr] <= din;
                wr_ptr <= next_wr_ptr;
                wr_count <= next_wr_count;
            end
            rd_en <= (~empty_n && rd_en);
        end
    end

    always @(posedge rd_clk) begin
        if (rst) begin
            rd_en <= 0;
        end else begin
            if (rd_en && ~empty_n) begin
                dout <= fifo[rd_ptr];
                rd_ptr <= next_rd_ptr;
                rd_count <= next_rd_count;
            end
        end
    end

    assign rd_clk = wr_clk;

    assign empty = ~empty_n;
    assign full = ~full_n;

    assign wr_data_count = wr_count;
    assign rd_data_count = rd_count;

    assign prog_empty = (wr_count <= 2);
    assign prog_full = (wr_count >= 14);

endmodule

module seq_up_counter (
  output reg [5:0] Q,
  input seq_clr,
  input seq_cnt_en,
  input slowest_sync_clk
);

  wire [5:0] q_int0;
  wire clear;

  LUT1 #(
    .INIT(2'h1)
  ) q_int_0_i_1 (
    .I0(Q[0]),
    .O(q_int0[0])
  );

  LUT2 #(
    .INIT(4'h6)
  ) q_int_1_i_1 (
    .I0(Q[0]),
    .I1(Q[1]),
    .O(q_int0[1])
  );

  LUT3 #(
    .INIT(8'h78)
  ) q_int_2_i_1 (
    .I0(Q[0]),
    .I1(Q[1]),
    .I2(Q[2]),
    .O(q_int0[2])
  );

  LUT4 #(
    .INIT(16'h7F80)
  ) q_int_3_i_1 (
    .I0(Q[1]),
    .I1(Q[0]),
    .I2(Q[2]),
    .I3(Q[3]),
    .O(q_int0[3])
  );

  LUT5 #(
    .INIT(32'h7FFF8000)
  ) q_int_4_i_1 (
    .I0(Q[2]),
    .I1(Q[0]),
    .I2(Q[1]),
    .I3(Q[3]),
    .I4(Q[4]),
    .O(q_int0[4])
  );

  LUT1 #(
    .INIT(2'h1)
  ) q_int_5_i_1 (
    .I0(seq_clr),
    .O(clear)
  );

  LUT6 #(
    .INIT(64'h7FFFFFFF80000000)
  ) q_int_5_i_2 (
    .I0(Q[3]),
    .I1(Q[1]),
    .I2(Q[0]),
    .I3(Q[2]),
    .I4(Q[4]),
    .I5(Q[5]),
    .O(q_int0[5])
  );

  always @(posedge slowest_sync_clk) begin
    if (seq_clr) begin
      Q <= 6'h0;
    end else if (seq_cnt_en) begin
      Q <= q_int0;
    end
  end

  always @(posedge slowest_sync_clk) begin
    if (clear) begin
      Q <= 6'h0;
    end
  end

endmodule

module arriaiigz_dpa_block(
    input clkin,
    input dpareset,
    input dpahold,
    input datain,
    output clkout,
    output dataout,
    output dpalock
);

parameter net_ppm_variation = 0;
parameter is_negative_ppm_drift = "off";
parameter enable_soft_cdr_mode = "on";

reg [2:0] select = 3'b000;
reg clkout_tmp;
reg dataout_tmp;
real counter_reset_value;
integer count_value = 0;
integer i = 0;

wire clk0_tmp;
wire clk1_tmp;
wire clk2_tmp;
wire clk3_tmp;
wire clk4_tmp;
wire clk5_tmp;
wire clk6_tmp;
wire clk7_tmp;
wire data0_tmp;
wire data1_tmp;
wire data2_tmp;
wire data3_tmp;
wire data4_tmp;
wire data5_tmp;
wire data6_tmp;
wire data7_tmp;

arriaiigz_dpa_retime_block data_clock_retime(
    .clkin(clkin),
    .datain(datain),
    .reset(dpareset),
    .clk0(clk0_tmp),
    .clk1(clk1_tmp),
    .clk2(clk2_tmp),
    .clk3(clk3_tmp),
    .clk4(clk4_tmp),
    .clk5(clk5_tmp),
    .clk6(clk6_tmp),
    .clk7(clk7_tmp),
    .data0(data0_tmp),
    .data1(data1_tmp),
    .data2(data2_tmp),
    .data3(data3_tmp),
    .data4(data4_tmp),
    .data5(data5_tmp),
    .data6(data6_tmp),
    .data7(data7_tmp),
    .lock(dpalock)
);

always @(posedge clkin, posedge dpareset, posedge dpahold) begin
    if (dpareset == 1'b1) begin
        i = 0;
        select = 3'b000;
        clkout_tmp = clkin;
        dataout_tmp = datain;
    end else if (dpahold == 1'b0) begin
        // Hold current clock and data signals
    end else begin
        if (net_ppm_variation == 0) begin
            select = 3'b000;
        end else begin
            if (i < count_value) begin
                i = i + 1;
            end else begin
                select = select + 1'b1;
                i = 0;
            end
        end
    end
end

always @(*) begin
    case (select)
        3'b000: begin
            clkout_tmp = clk0_tmp;
            dataout_tmp = data0_tmp;
        end
        3'b001: begin
            if (is_negative_ppm_drift == "on") begin
                clkout_tmp = clk7_tmp;
                dataout_tmp = data7_tmp;
            end else begin
                clkout_tmp = clk1_tmp;
                dataout_tmp = data1_tmp;
            end
        end
        3'b010: begin
            if (is_negative_ppm_drift == "on") begin
                clkout_tmp = clk6_tmp;
                dataout_tmp = data6_tmp;
            end else begin
                clkout_tmp = clk2_tmp;
                dataout_tmp = data2_tmp;
            end
        end
        3'b011: begin
            if (is_negative_ppm_drift == "on") begin
                clkout_tmp = clk5_tmp;
                dataout_tmp = data5_tmp;
            end else begin
                clkout_tmp = clk3_tmp;
                dataout_tmp = data3_tmp;
            end
        end
        3'b100: begin
            clkout_tmp = clk4_tmp;
            dataout_tmp = data4_tmp;
        end
        3'b101: begin
            if (is_negative_ppm_drift == "on") begin
                clkout_tmp = clk3_tmp;
                dataout_tmp = data3_tmp;
            end else begin
                clkout_tmp = clk5_tmp;
                dataout_tmp = data5_tmp;
            end
        end
        3'b110: begin
            if (is_negative_ppm_drift == "on") begin
                clkout_tmp = clk2_tmp;
                dataout_tmp = data2_tmp;
            end else begin
                clkout_tmp = clk6_tmp;
                dataout_tmp = data6_tmp;
            end
        end
        3'b111: begin
            if (is_negative_ppm_drift == "on") begin
                clkout_tmp = clk1_tmp;
                dataout_tmp = data1_tmp;
            end else begin
                clkout_tmp = clk7_tmp;
                dataout_tmp = data7_tmp;
            end
        end
    endcase
end

assign clkout = (enable_soft_cdr_mode == "on") ? clkout_tmp : clkin;
assign dataout = (enable_soft_cdr_mode == "on") ? dataout_tmp : datain;

endmodule

module lifo_memory_block (
  input clk,
  input reset,
  input write_en,
  input [7:0] data_in,
  input pop_en,
  output reg [7:0] data_out
);

parameter depth = 16; // number of data elements the memory block can store

reg [7:0] memory [0:depth-1]; // array to store the data elements
reg [3:0] top; // pointer to the top data element

always @(posedge clk) begin
  if (reset) begin
    top <= 0;
  end else begin
    if (write_en) begin
      memory[top] <= data_in;
      if (top == depth-1) begin
        top <= 0;
      end else begin
        top <= top + 1;
      end
    end else if (pop_en) begin
      if (top == 0) begin
        data_out <= memory[top];
        top <= depth-1;
      end else begin
        data_out <= memory[top-1];
        top <= top - 1;
      end
    end else begin
      data_out <= memory[top];
    end
  end
end

endmodule

