module spi_control(
  input clk,
  input rst,
  input [31:0] send_data,
  input send_valid,
  input query_id,
  input query_dataIn,
  output reg [31:0] dataOut,
  output reg busy,
  output reg byteDone,
  output reg writeReset,
  output reg writeByte,
  output reg [31:0] dataIn
);

  // internal variables
  reg [31:0] sampled_send_data;
  reg [3:0] sampled_send_valid;
  reg [2:0] bytesel;
  reg send = 0;
  reg [31:0] txBuffer;
  reg [4:0] bits = 0;
  reg [31:0] next_txBuffer;
  reg [4:0] next_bits;
  reg byteDone = 0;
  reg next_byteDone = 0;
  reg busy = 0;
  reg next_busy = 0;

  // control FSM states
  parameter [1:0] INIT = 0, IDLE = 1, SEND = 2, POLL = 3;
  reg [1:0] state, next_state;

  // FSM control logic
  always @(posedge clk, posedge rst) begin
    if (rst) begin
      state <= INIT;
      sampled_send_data <= 32'h0;
      sampled_send_valid <= 4'h0;
      bytesel <= 3'h0;
      busy <= 1'b0;
    end else begin
      state <= next_state;
      sampled_send_data <= next_sampled_send_data;
      sampled_send_valid <= next_sampled_send_valid;
      bytesel <= next_bytesel;
      busy <= next_busy;
      byteDone <= next_byteDone;
    end
  end

  // FSM state transitions and actions
  always @* begin
    next_state = state;
    next_sampled_send_data = sampled_send_data;
    next_sampled_send_valid = sampled_send_valid;
    next_bytesel = bytesel;
    next_busy = (state != IDLE) || send || !byteDone;

    writeReset = 1'b0;
    writeByte = 1'b0;

    case (state)
      INIT: begin
        writeReset = 1'b1;
        next_sampled_send_data = 32'h0;
        next_sampled_send_valid = 4'hF;
        next_bytesel = 3'h0;
        next_busy = 1'b0;
        next_state = IDLE;
      end

      IDLE: begin
        next_sampled_send_data = send_data;
        next_sampled_send_valid = send_valid;
        next_bytesel = 0;

        if (send) begin
          next_state = SEND;
        end else if (query_id) begin
          next_sampled_send_data = 32'h534c4131; // "SLA1"
          next_sampled_send_valid = 4'hF;
          next_state = SEND;
        end else if (query_dataIn) begin
          next_sampled_send_data = dataIn;
          next_sampled_send_valid = 4'hF;
          next_state = SEND;
        end
      end

      SEND: begin
        writeByte = 1'b1;
        next_bytesel = bytesel + 1'b1;
        next_state = POLL;
      end

      POLL: begin
        if (byteDone) begin
          if (~|bytesel) begin
            next_state = IDLE;
          end else begin
            next_state = SEND;
          end
        end
      end

      default: next_state = INIT;
    endcase
  end

  // SPI bus interface logic
  always @(posedge clk) begin
    if (spi_cs_n) begin
      next_bits = 0;
    end

    if (!spi_cs_n && dly_sclk && !spi_sclk && !byteDone) begin
      next_bits = bits + 1'b1;
      next_byteDone = &next_bits;
    end

    next_txBuffer = (spi_cs_n || byteDone) ? 32'hFFFFFFFF : {txBuffer, 1'b0};
  end

  // update internal variables
  always @* begin
    send = (sampled_send_valid[bytesel] == 1'b1) && (bytesel < 4'hF);
    txBuffer = sampled_send_data;
    bits = bytesel[1:0];

    if (next_bits == 5'b0) begin
      dataOut = 32'h0;
    end else if (next_bits == 5'b10000) begin
      dataOut = next_txBuffer[31:0];
    end else if (next_bits == 5'b10001) begin
      dataOut = next_txBuffer[63:32];
    end else if (next_bits == 5'b10010) begin
      dataOut = next_txBuffer[95:64];
    end else if (next_bits == 5'b10011) begin
      dataOut = next_txBuffer[127:96];
    end else if (next_bits == 5'b10100) begin
      dataOut = next_txBuffer[159:128];
    end else if (next_bits == 5'b10101) begin
      dataOut = next_txBuffer[191:160];
    end else if (next_bits == 5'b10110) begin
      dataOut = next_txBuffer[223:192];
    end else if (next_bits == 5'b10111) begin
      dataOut = next_txBuffer[255:224];
    end else begin
      dataOut = 32'h0;
    end
  end

  // update byteDone signal
  always @* begin
    if (next_bits[3:0] != bits[3:0]) begin
      next_byteDone = 1'b1;
    end
  end

  // update dataIn signal
  always @(posedge clk) begin
    if (spi_cs_n && dly_sclk && spi_sclk) begin
      dataIn <= {dataIn[31:8], spi_mosi};
    end
  end

endmodule

module TurboCode (
  input [k-1:0] data_in,
  input clk,
  input rst,
  output [n-1:0] sys_out,
  output [m-1:0] par_out,
  output [k-1:0] data_out
);

parameter k = 8; // number of bits in input data
parameter n = 16; // number of bits in output data
parameter m = 8; // number of parity bits

reg [k-1:0] data_reg;
reg [n-1:0] sys_reg;
reg [m-1:0] par_reg;
reg [k-1:0] data_out_reg;

wire [m-1:0] par_gen;
wire [n-1:0] received_data;
wire [k-1:0] decoded_data;

// Feedback shift register for parity generation
reg [m-1:0] par_shift_reg;
always @(posedge clk) begin
  if (rst) begin
    par_shift_reg <= 0;
  end else begin
    par_shift_reg <= {par_shift_reg[m-2:0], data_reg[k-1]};
  end
end

// Polynomial generator functions for parity generation
assign par_gen[0] = par_shift_reg[0] ^ par_shift_reg[1] ^ par_shift_reg[2] ^ par_shift_reg[4] ^ par_shift_reg[7];
assign par_gen[1] = par_shift_reg[0] ^ par_shift_reg[2] ^ par_shift_reg[3] ^ par_shift_reg[5] ^ par_shift_reg[7];
assign par_gen[2] = par_shift_reg[0] ^ par_shift_reg[1] ^ par_shift_reg[3] ^ par_shift_reg[6] ^ par_shift_reg[7];
assign par_gen[3] = par_shift_reg[1] ^ par_shift_reg[2] ^ par_shift_reg[4] ^ par_shift_reg[6] ^ par_shift_reg[7];
assign par_gen[4] = par_shift_reg[0] ^ par_shift_reg[2] ^ par_shift_reg[5] ^ par_shift_reg[6] ^ par_shift_reg[7];
assign par_gen[5] = par_shift_reg[1] ^ par_shift_reg[3] ^ par_shift_reg[4] ^ par_shift_reg[5] ^ par_shift_reg[7];
assign par_gen[6] = par_shift_reg[0] ^ par_shift_reg[3] ^ par_shift_reg[4] ^ par_shift_reg[6] ^ par_shift_reg[7];
assign par_gen[7] = par_shift_reg[2] ^ par_shift_reg[3] ^ par_shift_reg[5] ^ par_shift_reg[6] ^ par_shift_reg[7];

// Encoder logic
always @(posedge clk) begin
  if (rst) begin
    data_reg <= 0;
    sys_reg <= 0;
    par_reg <= 0;
  end else begin
    data_reg <= data_in;
    sys_reg <= data_in;
    par_reg <= par_gen;
  end
end

// Decoder logic
TurboDecoder decoder(
  .clk(clk),
  .rst(rst),
  .sys_in(sys_reg),
  .par_in(par_reg),
  .data_out(decoded_data),
  .sys_out(received_data)
);

// Output logic
always @(posedge clk) begin
  if (rst) begin
    data_out_reg <= 0;
  end else begin
    data_out_reg <= decoded_data;
  end
end

assign sys_out = sys_reg;
assign par_out = par_reg;
assign data_out = data_out_reg;

endmodule

