    input [1023:0] in,      // 1024-bit input vector
    input [7:0] sel,        // 8-bit selection input
    output [3:0] out        // 4-bit output of the multiplexer
);

    wire [3:0] shifter_out;

    barrel_shifter shifter(
        .in(in),
        .sel(sel),
        .out(shifter_out)
