module barrel_shifter(
    input [1023:0] in,      // 1024-bit input vector
    input [7:0] sel,        // 8-bit selection input
    output [3:0] out        // 4-bit output of the barrel shifter
);

    wire [255:0] shifted_in;

    assign shifted_in = in >> (sel * 4);

    assign out = shifted_in[3:0];

endmodule

