	output reg         rdcmd_valid,
	input  wire         rdcmd_ready,

	input  wire [31:0] mem_data,
	output wire         mem_valid
);

    reg selectInputNext;
    reg selectInput; //1 == input, 0==feedback

	localparam [2:0]
		ST_IDLE   = 0,
		ST_ISSUE_READ = 3,
		ST_OUTPUT_KEY  = 4;
	reg [2:0] state;    

    wire[HASHADDR_WIDTH+KEY_WIDTH+META_WIDTH-1:0] in_data;
    wire in_valid;
    reg in_ready;
    wire[31:0] hash_data;


    assign in_data = (selectInput==1) ? input_data : feedback_data;
    assign in_valid = (selectInput==1) ? input_valid : feedback_valid;
    assign input_ready = (selectInput==1) ? in_ready : 0;
    assign feedback_ready = (selectInput==1) ? 0 : in_ready;

    assign hash_data = (selectInput==1) ? input_data[KEY_WIDTH+META_WIDTH+HASHADDR_WIDTH-1:KEY_WIDTH+META_WIDTH] : feedback_data[KEY_WIDTH+META_WIDTH+HASHADDR_WIDTH-1:KEY_WIDTH+META_WIDTH];    

    wire[MEMADDR_WIDTH-1:0] addr;    

    assign addr = hash_data[31:32 - MEMADDR_WIDTH] ^ hash_data[MEMADDR_WIDTH-1:0];

    reg [7:0] cache [0:31];

    always @(posedge clk) begin
    	if (rst) begin
    		selectInput <= 1;
    		selectInputNext <= 0;    		
    		state <= ST_IDLE;
    		in_ready <= 0;
    		rdcmd_valid <= 0;
    		output_valid <= 0;
            mem_valid <= 0;
    	end
    	else begin

    		if (rdcmd_ready==1 && rdcmd_valid==1) begin
    			rdcmd_valid <= 0;
    		end

    		if (output_ready==1 && output_valid==1) begin
    			output_valid <= 0;
    		end

            in_ready <= 0;


    		case (state)    		
    			ST_IDLE : begin
    				if (output_ready==1 && rdcmd_ready==1) begin
    					selectInput <= selectInputNext;
    					selectInputNext <= ~selectInputNext;

    					if (selectInputNext==1 && input_valid==0 && feedback_valid==1) begin
    						selectInput <= 0;
    						selectInputNext <= 1;    						
    					end

    					if (selectInputNext==0 && input_valid==1 && feedback_valid==0) begin
    						selectInput <= 1;
    						selectInputNext <= 0;    						
    					end

    					if (selectInput==1 && input_valid==1) begin
    						state <= ST_ISSUE_READ;    						
    					end

						if (selectInput==0 && feedback_valid==1) begin
    						state <= ST_ISSUE_READ;    						
    					end    					

    				end
    			end

    			ST_ISSUE_READ: begin    			
                    if (in_data[KEY_WIDTH+META_WIDTH-4]==1) begin
                        // ignore this and don't send read!

                    end else begin			                        
                        if (cache[addr[4:0]] == mem_data) begin
                            // data is present in cache
                            output_data <= cache[addr[4:0]];
                            output_data[KEY_WIDTH+META_WIDTH+HASHADDR_WIDTH-1:KEY_WIDTH+META_WIDTH] <= addr;
                            output_valid <= 1;
                            mem_valid <= 1;
                        end else begin
                            // data is not present in cache
            				rdcmd_data <= addr;
            				rdcmd_valid <= 1;
                            rdcmd_data[31:MEMADDR_WIDTH] <= 0;
            				state <= ST_OUTPUT_KEY;                      
                            in_ready <= 1;
                        end
                    end
    			end

    			ST_OUTPUT_KEY: begin
    				if (output_ready==1) begin
                        cache[addr[4:0]] <= mem_data;
                        output_data <= mem_data;
                        output_data[KEY_WIDTH+META_WIDTH+HASHADDR_WIDTH-1:KEY_WIDTH+META_WIDTH] <= addr;
                        output_valid <= 1;
                        mem_valid <= 1;
                        state <= ST_IDLE;
    				end
    			end


    		endcase
    	end
    end

endmodule

module UART_TX(
    input rst, clk, baud_edge, data_ready,
    input [7:0] data,
    output reg tx, data_accepted
);

    localparam START = 2'b01, DATA = 2'b10, END = 2'b11;

    reg [7:0] data_reg;
    reg [2:0] state;
    reg [2:0] data_counter;
    reg [1:0] baud_counter;

    initial begin
        tx <= 1;
        data_accepted <= 0;
    end

    always @(posedge clk) begin
        if(rst) begin
            state <= END;
            tx <= 1;
            data_accepted <= 0;
            baud_counter <= 0;
        end else if(baud_edge) begin
            case(state)
            START: begin
                tx <= 0;
                data_counter <= 0;
                baud_counter <= 0;
                state <= DATA;
            end
            DATA: begin
                if(baud_counter == 0) begin
                    tx <= data_reg[data_counter];
                    if(data_counter != 7) begin
                        data_counter <= data_counter + 1;
                    end else begin
                        state <= END;
                        data_counter <= 0;
                    end
                end
                baud_counter <= baud_counter + 1;
            end
            END: begin
                tx <= 1;
                if(data_ready) begin
                    data_accepted <= 1;
                    data_reg <= data;
                    state <= START;
                end
            end
            default: begin
                tx <= 1;
                state <= END;
            end
            endcase
        end else begin
            baud_counter <= 0;
            data_accepted <= 0;
        end
    end
endmodule

module prot_eng_rx
  #(parameter BASE=0)
   (input clk, input reset, input clear,
    input set_stb, input [7:0] set_addr, input [31:0] set_data,
    input [18:0] datain, input src_rdy_i, output dst_rdy_o,
    output [18:0] dataout, output src_rdy_o, input dst_rdy_i);

   localparam HDR_WIDTH  = 16 + 7;  // 16 bits plus flags
   localparam HDR_LEN 	 = 32;      // Up to 64 bytes of protocol

   // Store header values in a small dual-port (distributed) ram
   reg [HDR_WIDTH-1:0] header_ram[0:HDR_LEN-1];
   wire [HDR_WIDTH-1:0] header_word;

   always @(posedge clk)
     if(set_stb & ((set_addr & 8'hE0) == BASE))
       header_ram[set_addr[4:0]] <= set_data;

   assign header_word 	= header_ram[state];

   wire consume_input 	= src_rdy_i & dst_rdy_o;
   wire produce_output 	= src_rdy_o & dst_rdy_i;

   // Main State Machine
   reg [15:0] pkt_length, fail_word, dataout_int;

   reg slowpath, error, sof_o, eof_o, occ_o, odd;

   assign dataout    = {occ_o, eof_o, sof_o, dataout_int};

   wire [15:0] calc_ip_checksum, calc_udp_checksum;
   reg [15:0] rx_ip_checksum, rx_udp_checksum;

   always @(posedge clk) 
     if(header_word[19]) 
       rx_ip_checksum  <= datain[15:0];
   always @(posedge clk) 
     if(header_word[18]) 
       rx_udp_checksum <= datain[15:0];

   always @(posedge clk)
     if(reset | clear)
       begin
	  slowpath     <= 0;
	  error        <= 0;
	  state        <= 0;
	  fail_word    <= 0;
	  eof_o        <= 0;
	  occ_o        <= 0;
       end
     else if(src_rdy_i & dst_rdy_i)
       case (state)
	 0 :
	   begin
	      slowpath 	   <= 0;
	      error 	   <= 0;
	      eof_o 	   <= 0;
	      occ_o 	   <= 0;
	      state 	   <= 1;
	   end

	 ST_SLOWPATH :
	   begin
	      slowpath 	   <= 1;
	      error 	   <= 0;
	      eof_o 	   <= 0;
	      occ_o 	   <= 0;
	      dataout_int   <= 19'b0;
	      state 	   <= state + 1;
	   end

	 ST_ERROR :
	   begin
	      slowpath 	   <= 0;
	      error 	   <= 1;
	      eof_o 	   <= 0;
	      occ_o 	   <= 0;
	      dataout_int   <= 19'b0;
	      state 	   <= state + 1;
	   end

	 ST_PAYLOAD :
	   begin
	      slowpath 	   <= 0;
	      error 	   <= 0;
	      eof_o 	   <= 0;
	      occ_o 	   <= 1;
	      dataout_int   <= datain;
	      state 	   <= state + 1;
	   end

	 ST_FILLER :
	   begin
	      slowpath 	   <= 0;
	      error 	   <= 0;
	      eof_o 	   <= 0;
	      occ_o 	   <= 1;
	      dataout_int   <= 19'b0;
	      state 	   <= state + 1;
	   end

	 ST_END1 :
	   begin
	      slowpath 	   <= 0;
	      error 	   <= 0;
	      eof_o 	   <= 1;
	      occ_o 	   <= 0;
	      dataout_int   <= 19'b0;
	      fail_word 	   <= 16'h0000;
	      state 	   <= state + 1;
	   end

	 ST_END2 :
	   begin
	      slowpath 	   <= 0;
	      error 	   <= 0;
	      eof_o 	   <= 1;
	      occ_o 	   <= 0;
	      dataout_int   <= 19'b0;
	      fail_word 	   <= 16'hFFFF;
	      state 	   <= state + 1;
	   end

	 default :
	   if(header_word[21] && mismatch)
	     state <= ST_SLOWPATH;
	   else if(header_word[20] && mismatch)
	     state <= ST_ERROR;
	   else if(header_word[22])
	     state <= ST_PAYLOAD;
	   else
	     state <= state + 1;
       endcase // case (state)



   // IP + UDP checksum state machines
   checksum_sm ip_chk
     (.clk(clk), .reset(reset), .in(datain), 
      .calc(consume_input & header_word[17]), .clear(state==0), .checksum(ip_checksum));

   checksum_sm udp_chk
     (.clk(clk), .reset(reset), .in(datain), 
      .calc(consume_input & header_word[16]), .clear(state==0), .checksum(udp_checksum));

endmodule

module top_module (
    input wire [15:0] in,
    input wire [2:0] sel,
    input wire [3:0] data0,
    input wire [3:0] data1,
    input wire [3:0] data2,
    input wire [3:0] data3,
    input wire [3:0] data4,
    input wire [3:0] data5,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo
);

    wire [3:0] mux_out;
    wire [7:0] split_out_hi;
    wire [7:0] split_out_lo;
    wire [7:0] and_out;

    mux_module mux_inst (
        .sel(sel),
        .data0(data0),
        .data1(data1),
        .data2(data2),
        .data3(data3),
        .data4(data4),
        .data5(data5),
        .out(mux_out)
    );

    split_module split_inst (
        .in(in),
        .out_hi(split_out_hi),
        .out_lo(split_out_lo)
    );

    and_module and_inst (
        .in1(split_out_hi),
        .in2(split_out_lo),
        .out(and_out)
    );

    always @(*) begin
        case (sel)
            3'b000: out_lo <= mux_out;
            3'b001: out_lo <= mux_out;
            3'b010: out_lo <= mux_out;
            3'b011: out_lo <= mux_out;
            3'b100: out_lo <= mux_out;
            3'b101: out_lo <= mux_out;
            default: out_lo <= in[15];
        endcase
        out_hi <= and_out;
    end

    priority_encoder priority_enc_inst (
        .in(sel),
        .out(mux_inst.sel)
    );

endmodule

module mux_module (
    input wire [2:0] sel,
    input wire [3:0] data0,
    input wire [3:0] data1,
    input wire [3:0] data2,
    input wire [3:0] data3,
    input wire [3:0] data4,
    input wire [3:0] data5,
    output reg [3:0] out
);

    always @(*) begin
        case (sel)
            3'b000: out <= data0;
            3'b001: out <= data1;
            3'b010: out <= data2;
            3'b011: out <= data3;
            3'b100: out <= data4;
            3'b101: out <= data5;
            default: out <= 4'b0000;
        endcase
    end

endmodule

module split_module (
    input wire [15:0] in,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo
);

    wire [7:0] shift_out;

    assign shift_out = in >> 8;

    assign out_hi = shift_out;
    assign out_lo = in;

endmodule

module and_module (
    input wire [7:0] in1,
    input wire [7:0] in2,
    output wire [7:0] out
);

    assign out = in1 & in2;

endmodule

module priority_encoder (
    input wire [5:0] in,
    output reg [2:0] out
);

    always @(*) begin
        case (in)
            6'b000001: out <= 3'b000;
            6'b000010: out <= 3'b001;
            6'b000100: out <= 3'b010;
            6'b001000: out <= 3'b011;
            6'b010000: out <= 3'b100;
            6'b100000: out <= 3'b101;
            default: out <= 3'b111;
        endcase
    end

endmodule

