module multiplier_block (
    i_data0,
    o_data0
);

  // Port mode declarations:
  input   [31:0] i_data0;
  output  [31:0] o_data0;

  //Multipliers:
  wire [31:0] w1, w512, w513, w64, w449, w7184, w7633, w15266;

  // Calculate the intermediate signals using multipliers:
  assign w1 = i_data0;
  assign w512 = i_data0 << 9;
  assign w513 = i_data0 + w512;
  assign w64 = i_data0 << 6;
  assign w449 = w513 - w64;
  assign w7184 = w449 << 4;
  assign w7633 = w449 + w7184;
  assign w15266 = w7633 << 1;

  // Output signal:
  assign o_data0 = w15266;

  //multiplier_block area estimate = 4630.34883442059;
endmodule

module MEMWB_Stage(
    input  clock,
    input  reset,
    input  M_Flush,
    input  M_Stall,
    input  WB_Stall,
    // Control Signals
    input  M_RegWrite,
    input  M_MemtoReg,
    // Data Signals
    input  [31:0] M_ReadData,
    input  [31:0] M_ALU_Result,
    input  [4:0]  M_RtRd,
    // Voter Signals for Registers
    input WB_RegWrite,
    input WB_MemtoReg,
    input [31:0] WB_ReadData,
    input [31:0] WB_ALU_Result,
    input [4:0]  WB_RtRd,
    output reg vote_WB_RegWrite,
    output reg vote_WB_MemtoReg,
    output reg [31:0] vote_WB_ReadData,
    output reg [31:0] vote_WB_ALU_Result,
    output reg [4:0]  vote_WB_RtRd
);

    // Initialize the outputs
    always @ (posedge clock) begin
        if (reset) begin
            vote_WB_RegWrite <= 1'b0;
            vote_WB_MemtoReg <= 1'b0;
            vote_WB_ReadData <= 32'b0;
            vote_WB_ALU_Result <= 32'b0;
            vote_WB_RtRd <= 5'b0;
        end
    end

    // Update the pipeline register
    always @(posedge clock) begin
        if (reset) begin
            vote_WB_RegWrite <= 1'b0;
            vote_WB_MemtoReg <= 1'b0;
            vote_WB_ReadData <= 32'b0;
            vote_WB_ALU_Result <= 32'b0;
            vote_WB_RtRd <= 5'b0;
        end
        else begin
            if (WB_Stall) begin
                vote_WB_RegWrite <= WB_RegWrite;
                vote_WB_MemtoReg <= WB_MemtoReg;
                vote_WB_ReadData <= WB_ReadData;
                vote_WB_ALU_Result <= WB_ALU_Result;
                vote_WB_RtRd <= WB_RtRd;
            end
            else if (M_Stall | M_Flush) begin
                vote_WB_RegWrite <= 1'b0;
                vote_WB_MemtoReg <= 1'b0;
                vote_WB_ReadData <= 32'b0;
                vote_WB_ALU_Result <= 32'b0;
                vote_WB_RtRd <= 5'b0;
            end
            else begin
                vote_WB_RegWrite <= M_RegWrite;
                vote_WB_MemtoReg <= M_MemtoReg;
                vote_WB_ReadData <= M_ReadData;
                vote_WB_ALU_Result <= M_ALU_Result;
                vote_WB_RtRd <= M_RtRd;
            end
        end
    end

endmodule

module FSM (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 4; // number of input signals
parameter m = 2; // number of output signals
parameter s = 8; // number of states

reg [2:0] state; // register to hold current state

// Define the states and transitions as Boolean functions of the input signals
always @ (in) begin
  case (state)
    3'b000: begin // state 0
      if (in[0] && in[1])
        state <= 3'b001;
      else if (in[2])
        state <= 3'b010;
      else
        state <= 3'b100;
    end
    3'b001: begin // state 1
      if (in[0] && in[1])
        state <= 3'b011;
      else if (in[2])
        state <= 3'b010;
      else
        state <= 3'b101;
    end
    3'b010: begin // state 2
      if (in[0] && in[1])
        state <= 3'b011;
      else if (in[2])
        state <= 3'b111;
      else
        state <= 3'b100;
    end
    3'b011: begin // state 3
      if (in[0] && in[1])
        state <= 3'b001;
      else if (in[2])
        state <= 3'b111;
      else
        state <= 3'b101;
    end
    3'b100: begin // state 4
      if (in[0] && in[1])
        state <= 3'b101;
      else if (in[2])
        state <= 3'b010;
      else
        state <= 3'b000;
    end
    3'b101: begin // state 5
      if (in[0] && in[1])
        state <= 3'b111;
      else if (in[2])
        state <= 3'b010;
      else
        state <= 3'b001;
    end
    3'b110: begin // state 6
      if (in[0] && in[1])
        state <= 3'b111;
      else if (in[2])
        state <= 3'b100;
      else
        state <= 3'b010;
    end
    3'b111: begin // state 7
      if (in[0] && in[1])
        state <= 3'b101;
      else if (in[2])
        state <= 3'b100;
      else
        state <= 3'b011;
    end
  endcase
end

// Generate the output signals based on the current state and the input signals
always @ (state, in) begin
  case (state)
    3'b000: begin // state 0
      out[0] <= in[0] && in[1];
      out[1] <= in[2] || in[3];
    end
    3'b001: begin // state 1
      out[0] <= in[0] && in[1];
      out[1] <= in[2] && in[3];
    end
    3'b010: begin // state 2
      out[0] <= in[0] || in[1];
      out[1] <= in[2] && in[3];
    end
    3'b011: begin // state 3
      out[0] <= in[0] && in[1];
      out[1] <= in[2] || in[3];
    end
    3'b100: begin // state 4
      out[0] <= in[0] && in[1];
      out[1] <= in[2] || in[3];
    end
    3'b101: begin // state 5
      out[0] <= in[0] && in[1];
      out[1] <= in[2] && in[3];
    end
    3'b110: begin // state 6
      out[0] <= in[0] || in[1];
      out[1] <= in[2] && in[3];
    end
    3'b111: begin // state 7
      out[0] <= in[0] && in[1];
      out[1] <= in[2] || in[3];
    end
  endcase
end

endmodule

module binary_division (
    input logic [WIDTH-1:0] A, B,
    output logic [WIDTH-1:0] Y, R
);

parameter WIDTH = 1;

wire [WIDTH*WIDTH-1:0] chaindata;

genvar i;
generate
    for (i = 0; i < WIDTH; i=i+1) begin : stage
        wire [WIDTH-1:0] stage_in;

        if (i == 0) begin : cp
            assign stage_in = A;
        end else begin : cp
            assign stage_in = chaindata[i*WIDTH-1:(i-1)*WIDTH];
        end

        assign Y[WIDTH-(i+1)] = stage_in >= {B, {WIDTH-(i+1){1'b0}}};
        assign chaindata[(i+1)*WIDTH-1:i*WIDTH] = Y[WIDTH-(i+1)] ? stage_in - {B, {WIDTH-(i+1){1'b0}}} : stage_in;
    end
endgenerate

assign R = chaindata[WIDTH*WIDTH-1:WIDTH*(WIDTH-1)];

endmodule

module scan_chain(
  input mclr,
  input phi1,
  input phi2,
  input rd,
  input sin,
  input wr,
  output dout,
  output doutb,
  output sout
);

  // Internal signals
  wire net_2, net_4, net_6, net_7;

  // Scan cells
  scanChainFive__scanL scan1(.in(sin), .out(net_2));
  scanChainFive__scanL scan2(.in(net_2), .out(sout));
  scanChainFive__scanL scan3(.in(net_4), .out(doutb));
  scanChainFive__scanL scan4(.in(net_6), .out(net_7));
  scanChainFive__scanL scan5(.in(net_7), .out(dout));

  // NOT gate
  not #(100) inv(dout, doutb);

  // Scan chain control signals
  scanChainFive__scanP p1(.in(wr), .src(sout), .drn(net_4));
  scanChainFive__scanP p2(.in(rd), .src(gnd), .drn(net_2));
  scanChainFive__scanP p3(.in(mclr), .src(vdd), .drn(net_4));
  scanChainFive__scanP p4(.in(phi1), .src(net_7), .drn(net_2));
  scanChainFive__scanP p5(.in(phi2), .src(sin), .drn(net_6));

endmodule

module FlipFlops (
  input D, CLK, CLR, PR,
  output Q, Q_not
);

// D flip-flop inputs and outputs
reg D_FF, Q_FF, Q_not_FF;
always @(posedge CLK, posedge CLR, posedge PR) begin
  if (CLR) begin
    Q_FF <= 0;
    Q_not_FF <= 1;
  end else if (PR) begin
    Q_FF <= 1;
    Q_not_FF <= 0;
  end else begin
    Q_FF <= D_FF;
    Q_not_FF <= ~D_FF;
  end
end
assign Q = Q_FF;
assign Q_not = Q_not_FF;

// JK flip-flop inputs and outputs
reg J_FF, K_FF;
always @(posedge CLK, posedge CLR, posedge PR) begin
  if (CLR) begin
    Q_FF <= 0;
    Q_not_FF <= 1;
  end else if (PR) begin
    Q_FF <= 1;
    Q_not_FF <= 0;
  end else begin
    if (J_FF && K_FF) begin
      Q_FF <= ~Q_FF;
      Q_not_FF <= ~Q_not_FF;
    end else if (J_FF) begin
      Q_FF <= 1;
      Q_not_FF <= 0;
    end else if (K_FF) begin
      Q_FF <= 0;
      Q_not_FF <= 1;
    end
  end
end

// T flip-flop inputs and outputs
reg T_FF;
always @(posedge CLK, posedge CLR, posedge PR) begin
  if (CLR) begin
    Q_FF <= 0;
    Q_not_FF <= 1;
  end else if (PR) begin
    Q_FF <= 1;
    Q_not_FF <= 0;
  end else begin
    if (T_FF) begin
      Q_FF <= ~Q_FF;
      Q_not_FF <= ~Q_not_FF;
    end
  end
end

// SR flip-flop inputs and outputs
reg S_FF, R_FF;
always @(posedge CLK, posedge CLR, posedge PR) begin
  if (CLR) begin
    Q_FF <= 0;
    Q_not_FF <= 1;
  end else if (PR) begin
    Q_FF <= 1;
    Q_not_FF <= 0;
  end else begin
    if (S_FF) begin
      Q_FF <= 1;
      Q_not_FF <= 0;
    end else if (R_FF) begin
      Q_FF <= 0;
      Q_not_FF <= 1;
    end
  end
end

endmodule

module by_width (
		 input clk
		 );
   parameter 	       WIDTH=1;

   reg signed 	       i1;
   reg signed [62:0]   i63;
   reg signed [64:0]   i65;

   // verilator lint_off WIDTH
   wire signed [WIDTH-1:0] i1extp  /*verilator public*/ = i1;
   wire signed [WIDTH-1:0] i1ext  = i1;
   wire signed [WIDTH-1:0] i63ext = i63[WIDTH-1:0];
