module noise_reduction (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 1024; // number of input samples
parameter m = 1024; // number of output samples
parameter fs = 48000; // sampling frequency
parameter frame_size = 512; // number of samples per frame
parameter overlap = 256; // number of overlapping samples

// Signal processing operations
wire [frame_size-1:0] frames;
wire [frame_size-1:0] power_spectrum;
wire [frame_size-1:0] noise_spectrum;
wire [frame_size-1:0] enhanced_spectrum;
wire [frame_size-1:0] enhanced_signal;
wire [frame_size-1:0] reconstructed_signal;

// Divide input signal into frames
frame_divider fd (
  .in(in),
  .frames(frames),
  .frame_size(frame_size),
  .overlap(overlap)
);

// Compute power spectrum of each frame
power_spectrum_computation psc (
  .frames(frames),
  .power_spectrum(power_spectrum),
  .frame_size(frame_size)
);

// Estimate noise spectrum
noise_spectrum_estimation nse (
  .power_spectrum(power_spectrum),
  .noise_spectrum(noise_spectrum),
  .frame_size(frame_size)
);

// Subtract estimated noise spectrum from power spectrum
subtract_noise sn (
  .power_spectrum(power_spectrum),
  .noise_spectrum(noise_spectrum),
  .enhanced_spectrum(enhanced_spectrum),
  .frame_size(frame_size)
);

// Inverse Fourier transform the enhanced spectrum
inverse_fourier_transform ift (
  .enhanced_spectrum(enhanced_spectrum),
  .enhanced_signal(enhanced_signal),
  .frame_size(frame_size)
);

// Reconstruct output signal
overlap_add oa (
  .enhanced_signal(enhanced_signal),
  .reconstructed_signal(reconstructed_signal),
  .frame_size(frame_size),
  .overlap(overlap)
);

assign out = reconstructed_signal;

endmodule

module synchronizer (clk, rst, x, sync_x);

	input clk, rst, x;

	output sync_x;

	reg f1, f2;

	assign sync_x = f2;

	always @(posedge clk or posedge rst) begin

		if (rst) begin

			f1 <= 0;

			f2 <= 0;

		end else begin

			f1 <= x;

			f2 <= f1;

		end

	end

endmodule

module multiboot (
    input wire clk_icap,   // WARNING: this clock must not be greater than 20MHz (50ns period)
    input wire mrst_n,
    output reg reboot_ff
    );

    reg [4:0] q = 5'b00000;
    always @(posedge clk_icap) begin
      q[0] <= ~mrst_n;
      q[1] <= q[0];
      q[2] <= q[1];
      q[3] <= q[2];
      q[4] <= q[3];
      reboot_ff <= (q[4] && (!q[3]) && (!q[2]) && (!q[1]) );
    end

endmodule

module nor_and(
    Y, A, B, C, D,
