module block (en, wr, rst, data_in, data_out, ack);

	input en;
	input wr;
	input rst;
	input [0:15] data_in;
	output [0:15] data_out;
	output ack;

	reg [0:15] data;

	always @ (posedge en or posedge rst) begin
		if (rst) begin
			data <= 16'h0000;
			ack <= 1'b1;
		end else if (en) begin
			if (wr) begin
				data <= data_in;
				ack <= 1'b1;
			end else begin
				ack <= 1'b0;
			end
		end else begin
			ack <= 1'b0;
		end
	end

	assign data_out = data;

endmodule

module set (enable, word, comp,
	write, rst, tag_in, data_in, valid_in,
	hit, dirty_out, tag_out,
	data_out, valid_out, ack);

	/* set number of block in a set */
	parameter N = 4;

	input enable;
	input rst;
	input [0:1] word;
	input comp;
	input write;
	input rst;
	input [0:4] tag_in;
	input [0:15] data_in;
	input valid_in;

	output reg hit;
	output reg dirty_out;
	output reg [0:4] tag_out;
	output reg [0:15] data_out;
	output reg valid_out;
	output reg ack;

	reg [0:4] tag;
	reg valid = 1'b0;
	reg dirty = 1'b0;

	reg [0:15] word_in [0:N - 1];
	reg word_en [0:N - 1];
	reg word_wr [0:N - 1];
	wire [0:15] word_out [0:N - 1];
	wire word_ack [0:N - 1];

	generate
	genvar i;
	for (i = 0; i < N; i = i + 1) begin
		block blk_ins(word_en[i], word_wr[i], 1'b0, word_in[i], word_out[i], word_ack[i]);
	end
	endgenerate

	always @ (enable) begin
		ack = 1'b0;
		if (enable) begin
			/* Reset */
			if (rst) begin
				valid = 1'b0;
				ack = 1'b1;
			end
			/* Compare Read */
			if (comp && !write) begin
				if (tag == tag_in && valid) begin
					/* HIT */
					hit = 1'b1;
					valid_out = valid;
					dirty_out = dirty;
					tag_out = tag;
					word_en[word] = 1'b1;

					/* waiting for block ack */
					wait (word_ack[word]) begin
						data_out = word_out[word];
					end

					ack = 1'b1;
				end else begin
					/* MISS */
					hit = 1'b0;
					valid_out = valid;
					dirty_out = dirty;
					ack = 1'b1;
				end
			end
			/* Compare Write */
			if (comp && write)  begin
				if (tag == tag_in && valid) begin
					/* HIT -- Valid */
					dirty = 1'b1;
					dirty_out = 1'b0;
					hit = 1'b1;
					word_en[word] = 1'b1;
					word_wr[word] = 1'b1;
					word_in[word] = data_in;

					/* waiting for block ack */
					wait (word_ack[word]) begin
						ack = 1'b1;
					end
				end else if (!valid) begin
					/* HIT -- Invalid */
					valid = 1'b1;
					dirty = 1'b1;
					dirty_out = 1'b0;
					hit = 1'b1;
					tag = tag_in;
					word_en[word] = 1'b1;
					word_wr[word] = 1'b1;
					word_in[word] = data_in;

					/* waiting for block ack */
					wait (word_ack[word]) begin
						ack = 1'b1;
					end
				end else begin
					/* MISS -- Valid */
					valid_out = valid;
					dirty_out = dirty;
					ack = 1'b1;
				end
			end
			/* Access Read */
			if (!comp && !write) begin
				dirty_out = dirty;
				valid_out = valid;
				tag_out = tag;

				ack = 1'b1;
			end
			/* Access Write */
			if (!comp && write) begin
				tag <= tag_in;
				valid <= valid_in;
				dirty <= 1'b0;
				word_in[word] <= data_in;
				word_wr[word] <= 1'b1;
				word_en[word] <= 1'b1;

				/* waiting for block ack */
				wait (word_ack[word]) begin
					ack = 1'b1;
				end
			end
		end else begin
			word_en[word] = 1'b0;
			word_wr[word] = 1'b0;
			hit = 1'b0;
		end
	end	
endmodule

module tb_ram_sync_nolatch_4r2w;
   parameter BRAM_ADDR_WIDTH = 8;
   parameter BRAM_DATA_WIDTH = 16;
   parameter DATA_DEPTH = 64;

   reg clk;
   reg [BRAM_ADDR_WIDTH-1:0] raddr1, raddr2, raddr3, raddr4, waddr1, waddr2;
   reg [BRAM_DATA_WIDTH-1:0] wdata1, wdata2;
   reg we1, we2;
   wire [BRAM_DATA_WIDTH-1:0] rdata1, rdata2, rdata3, rdata4;

   ram_sync_nolatch_4r2w #(
      .BRAM_ADDR_WIDTH(BRAM_ADDR_WIDTH),
      .BRAM_DATA_WIDTH(BRAM_DATA_WIDTH),
      .DATA_DEPTH(DATA_DEPTH)
   ) dut (
      .clk(clk),
      .raddr1(raddr1),
      .raddr2(raddr2),
      .raddr3(raddr3),
      .raddr4(raddr4),
      .rdata1(rdata1),
      .rdata2(rdata2),
      .rdata3(rdata3),
      .rdata4(rdata4),
      .waddr1(waddr1),
      .waddr2(waddr2),
      .wdata1(wdata1),
      .wdata2(wdata2),
      .we1(we1),
      .we2(we2)
   );

   integer i, j;
   reg [BRAM_DATA_WIDTH-1:0] mem [0:DATA_DEPTH-1];

   initial begin
      // Initialize memory with random data
      for (i = 0; i < DATA_DEPTH; i = i + 1) begin
         mem[i] = $random;
      end

      // Write and read data from memory multiple times
      for (j = 0; j < 10; j = j + 1) begin
         // Write random data to memory
         waddr1 = $random % DATA_DEPTH;
         wdata1 = $random;
         we1 = 1;
         waddr2 = $random % DATA_DEPTH;
         wdata2 = $random;
         we2 = 1;
         #10;
         we1 = 0;
         we2 = 0;

         // Read data from memory and verify
         for (i = 0; i < DATA_DEPTH; i = i + 1) begin
            raddr1 = i;
            raddr2 = i;
            raddr3 = i;
            raddr4 = i;
            #1;
            if (rdata1 !== mem[i] || rdata2 !== mem[i] || rdata3 !== mem[i] || rdata4 !== mem[i]) begin
               $display("Error: Read data does not match written data at address %d", i);
               $finish;
            end
         end
      end

      $display("Testbench finished successfully");
      $finish;
   end

   always #5 clk = ~clk;
endmodule

module shift_reg_mux_xor (
