module main_minimal_interface(
    input clock,
    input reset,
    input start_port,
    output RX_VALID,
    output reg [7:0] RX_DATA,
    output TX_READY,
    output reg done_port,
    output reg [31:0] return_port,
    input TX_ENABLE,
    input [7:0] TX_DATA
);

    parameter IDLE_STATE = 2'b00;
    parameter START_STATE = 2'b01;
    parameter RECEIVE_STATE = 2'b10;
    parameter TRANSMIT_STATE = 2'b11;

    reg [1:0] state;
    reg [31:0] byte_count;
    reg [7:0] tx_data_reg;

    wire TX_WRITE;
    wire TX_BUSY;
    wire [7:0] TX_DATA_UART;
    wire RX_VALID_UART;
    wire [7:0] RX_DATA_UART;

    uart_top uart (.clock(clock), .reset(reset),.ser_in(RX_DATA_UART), .ser_out(TX_DATA_UART),
        .rx_data(RX_DATA_UART), .new_rx_data(RX_VALID_UART), 
        .tx_data(TX_DATA_UART), .new_tx_data(TX_WRITE), .tx_busy(TX_BUSY), 
        .baud_freq(`D_BAUD_FREQ), .baud_limit(`D_BAUD_LIMIT), 
        .baud_clk()
    );

    always @(posedge clock or negedge reset) begin
        if (!reset) begin
            state <= IDLE_STATE;
            byte_count <= 0;
            RX_DATA <= 0;
            tx_data_reg <= 0;
            done_port <= 0;
            return_port <= 0;
        end else begin
            case(state)
                IDLE_STATE: begin
                    if (start_port) begin
                        state <= START_STATE;
                    end
                end
                START_STATE: begin
                    if (~TX_BUSY) begin
                        tx_data_reg <= byte_count + 1;
                        byte_count <= byte_count + 1;
                        state <= TRANSMIT_STATE;
                    end
                end
                RECEIVE_STATE: begin
                    if (RX_VALID) begin
                        RX_DATA <= RX_DATA_UART;
                        byte_count <= byte_count + 1;
                        if (byte_count == tx_data_reg) begin
                            done_port <= 1;
                            state <= IDLE_STATE;
                            return_port <= byte_count;
                        end else begin
                            state <= TRANSMIT_STATE;
                        end
                    end
                end
                TRANSMIT_STATE: begin
                    if (~TX_BUSY) begin
                        TX_DATA <= tx_data_reg - byte_count;
                        TX_ENABLE <= 1;
                        state <= RECEIVE_STATE;
                    end
                end
            endcase
        end
    end

    assign TX_READY = ~TX_BUSY && state == RECEIVE_STATE;

endmodule

module binary_adder(
  input [3:0] A,
  input [3:0] B,
  input CIN,
  output [3:0] SUM
);

  wire [3:0] carry;
  assign carry[0] = CIN;

  genvar i;
  generate
    for (i = 0; i < 4; i = i + 1) begin
      full_adder F(
        .A(A[i]),
        .B(B[i]),
        .CIN(carry[i]),
        .SUM(SUM[i]),
        .COUT(carry[i+1])
      );
    end
  endgenerate

endmodule

module full_adder(
  input A,
  input B,
  input CIN,
  output SUM,
  output COUT
);

  assign SUM = A ^ B ^ CIN;
  assign COUT = (A & B) | (CIN & (A ^ B));

endmodule

