module nios_nios2_gen2_0_cpu_nios2_oci_im (
    input clk,           // clock input
    input jrst_n,        // reset input
    input [15:0] trc_ctrl,  // trace control input
    input [35:0] tw,     // 36-bit data input
    output reg tracemem_on,  // trace memory enable signal
    output reg [35:0] tracemem_trcdata,  // 36-bit trace data output
    output reg tracemem_tw,  // trace memory write signal
    output reg [6:0] trc_im_addr,  // 7-bit trace instruction memory address output
    output reg trc_wrap,  // trace wrap signal
    output reg xbrk_wrap_traceoff  // cross-break wrap trace-off signal
);

    reg [6:0] trc_im_addr_next;
    wire trc_on_chip;
    wire tw_valid;

    assign trc_on_chip = ~trc_ctrl[8];
    assign tw_valid = |tw[35:32];

    always @(posedge clk or negedge jrst_n) begin
        if (~jrst_n) begin
            trc_im_addr <= 0;
            trc_wrap <= 0;
        end
        else begin
            trc_im_addr <= trc_im_addr_next;
            trc_wrap <= (trc_im_addr_next == 0);
        end
    end

    always @(posedge clk or negedge jrst_n) begin
        if (~jrst_n) begin
            trc_im_addr_next <= 0;
            tracemem_on <= 0;
            tracemem_trcdata <= 0;
            tracemem_tw <= 0;
        end
        else begin
            trc_im_addr_next <= trc_im_addr + 1;
            tracemem_on <= trc_ctrl[9] & trc_on_chip;
            tracemem_trcdata <= tracemem_on ? tw : 0;
            tracemem_tw <= tracemem_on & tw_valid;
        end
    end

    assign xbrk_wrap_traceoff = trc_ctrl[10] & trc_wrap;

endmodule

