    if (reset) begin
      prev_input <= 0;
      out1 <= 0;
    end else begin
      if (in1 == 1 && prev_input == 0) begin
        out1 <= 1;
      end else begin
        out1 <= 0;
      end
      prev_input <= in1;
    end
  end

