    if (shift) begin
        Q_reg <= {Q_reg[2:0], D[0]};
        Q3 <= Q_reg[3];
    end
    else begin
        Q_reg <= {D, Q_reg[3]};
        Q3 <= Q_reg[3];
    end
end

assign Q = Q_reg;

