module up_down_counter (
    input clk,
    input reset,
    input up_down,
    output reg [3:0] q
);

    parameter CNT_MAX = 4'b1111;
    parameter CNT_MIN = 4'b0000;

    reg [3:0] cnt_next;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            q <= CNT_MIN;
        end
        else begin
            if (up_down) begin
                cnt_next <= q + 1;
            end
            else begin
                cnt_next <= q - 1;
            end

            if (cnt_next > CNT_MAX) begin
                q <= CNT_MIN;
            end
            else if (cnt_next < CNT_MIN) begin
                q <= CNT_MAX;
            end
            else begin
                q <= cnt_next;
            end
        end
    end

endmodule

module transition_detector (
    input clk,
    input reset,
    input [3:0] q,
    output reg transition
);

    reg [3:0] q_prev;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            q_prev <= 4'b0000;
            transition <= 1'b0;
        end
        else begin
            if (q != q_prev) begin
                transition <= 1'b1;
            end
            else begin
                transition <= 1'b0;
            end
            q_prev <= q;
        end
    end

endmodule

