    wire [3:0] and_out;
    wire [3:0] or_out;

    assign xor_out = a ^ b;
    assign and_out = a & b;
    assign or_out = a | b;

    assign sum[0] = xor_out[0] ^ cin;
    assign sum[1] = xor_out[1] ^ and_out[0];
    assign sum[2] = xor_out[2] ^ and_out[1];
    assign sum[3] = xor_out[3] ^ and_out[2];

    assign cout = or_out[3] | and_out[2] & xor_out[3] |
                  and_out[1] & xor_out[2] |
                  and_out[0] & xor_out[1] |
                  cin & xor_out[0];

endmodule

