module UART_echo_test_module (
    input clock,
    input echo_test_rx,
    input echo_test_reset,
    output reg echo_test_tx
);

reg [3:0] state;
reg [7:0] data;
reg start_bit_received;
reg stop_bit_received;
reg [15:0] counter;

parameter IDLE_STATE = 2'b11;
parameter START_STATE = 2'b10;
parameter DATA_STATE = 2'b01;
parameter STOP_STATE = 2'b00;

always @(posedge clock) begin
    if (echo_test_reset) begin
        state <= START_STATE;
        data <= 8'b0;
        start_bit_received <= 0;
        stop_bit_received <= 0;
        counter <= 0;
        echo_test_tx <= 1'b1;
    end
    else begin
        case (state)
            START_STATE: begin
                if (echo_test_rx == 1'b0) begin
                    start_bit_received <= 1;
                    state <= DATA_STATE;
                    counter <= 0;
                end
                else begin
                    start_bit_received <= 0;
                    state <= START_STATE;
                end
            end
            DATA_STATE: begin
                if (counter < 8) begin
                    data[counter] <= echo_test_rx;
                    counter <= counter + 1;
                end
                else begin
                    stop_bit_received <= 1;
                    state <= STOP_STATE;
                end
            end
            STOP_STATE: begin
                if (echo_test_rx == 1'b1) begin
                    stop_bit_received <= 1;
                    state <= IDLE_STATE;
                end
                else begin
                    stop_bit_received <= 0;
                    state <= START_STATE;
                end
            end
            IDLE_STATE: begin
                if (start_bit_received == 1) begin
                    state <= DATA_STATE;
                    counter <= 0;
                    start_bit_received <= 0;
                    data <= 8'b0;
                end
                else begin
                    state <= IDLE_STATE;
                end
            end
        endcase
    end
end

always @(posedge clock) begin
    if (state == DATA_STATE) begin
        echo_test_tx <= data[7];
    end
    else begin
        echo_test_tx <= 1'b1;
    end
end

endmodule

