    input [31:0] b,
    input sub,
    output [31:0] sum
);

reg [31:0] a_reg, b_reg, sum_reg;
wire [31:0] add_out, sub_out;

assign add_out = a_reg + b_reg;
assign sub_out = a_reg + (~b_reg) + sub;

always @(posedge clk) begin
    a_reg <= a;
    b_reg <= (sub) ? (~b) : b;
    sum_reg <= (sub) ? sub_out : add_out;
end

assign sum = sum_reg;

endmodule

module carry_select_adder (
  input [n-1:0] A,
  input [n-1:0] B,
  input Cin,
  output [n-1:0] S,
  output Cout
);

parameter n = 4; // number of bits in input signals

// Generate the sum and carry signals for each input number
wire [n:0] sumA, sumB;
wire [n:0] carryA, carryB;

genvar i;
generate
  for (i = 0; i < n; i = i + 1) begin : gen_sum_carry
    full_adder fa(
      .a(A[i]),
      .b(B[i]),
      .c(carryA[i]),
      .s(sumA[i])
    );
    full_adder fb(
      .a(A[i]),
      .b(B[i]),
      .c(carryB[i]),
      .s(sumB[i])
    );
  end
endgenerate

// Select the appropriate signals based on the carry-in signal
wire [n-1:0] S1, S2;
wire C1, C2;

assign S1 = sumA;
assign S2 = sumB;
assign C1 = carryA[n];
assign C2 = carryB[n];

assign S = Cin ? S2 : S1;
assign Cout = Cin ? C2 : C1;

endmodule

// Full adder module
module full_adder (
  input a,
  input b,
  input c,
  output s,
  output cout
);

assign s = a ^ b ^ c;
assign cout = (a & b) | (c & (a ^ b));

endmodule

module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] in,   // 8-bit input for the shift register
    input [63:0] sel, // Select input to choose from 16 4-bit inputs
    output reg [1:0] out // 2-bit output from the functional module
);

reg [7:0] shift_reg; // Shift register to shift input by two positions to the left
reg [3:0] mux_out;   // Output from the 16-to-1 multiplexer
reg cmp_out;         // Output from the comparator

// Shift register
always @(posedge clk) begin
    if (reset) begin
        shift_reg <= 8'b0;
    end else begin
        shift_reg <= {in[7:2], 2'b0};
    end
end

// 16-to-1 multiplexer
always @(*) begin
    case (sel[5:4])
        2'b00: mux_out = in[3:0];
        2'b01: mux_out = in[7:4];
        2'b10: mux_out = in[11:8];
        2'b11: mux_out = in[15:12];
    endcase
end

// Comparator
always @(*) begin
    if (mux_out == 4'b1010) begin
        cmp_out = 1'b1;
    end else begin
        cmp_out = 1'b0;
    end
end

// Functional module
always @(*) begin
    out[1:0] = {cmp_out, shift_reg[7:6]} | {cmp_out, shift_reg[5:4]} | {cmp_out, shift_reg[3:2]} | {cmp_out, shift_reg[1:0]};
end

endmodule

