        count_reg1 <= 4'b0;
        count_reg2 <= 4'b0;
    end
    else begin
        count_reg1 <= count;
        if (up_down) begin
            count_reg2 <= count_reg1 + 1;
        end
        else begin
            count_reg2 <= count_reg1 - 1;
        end
    end
end

always @(posedge clk) begin
    if (reset) begin
        count <= 4'b0;
    end
    else begin
        count <= count_reg2;
    end
end

endmodule

module POR (
  input pwr,
  output rst
);

