  reg reset_active;

  always @(posedge pwr) begin
    if (pwr) begin
      counter <= 0;
      reset_active <= 1;
    end else begin
      reset_active <= 0;
    end
  end

  always @(posedge clk) begin
    if (reset_active) begin
      if (counter == 8'hFF) begin
        rst <= 1;
        counter <= 0;
      end else begin
        rst <= 0;
        counter <= counter + 1;
      end
    end else begin
      rst <= 0;
    end
  end

endmodule

