always @(posedge clk_in or posedge reset) begin
  if (reset) begin
    clk_out <= 0;
    counter <= 0;
  end else begin
    if (counter == divisor-1) begin
      clk_out <= ~clk_out;
      counter <= 0;
    end else begin
      counter <= counter + 1;
    end
  end
end

reg [31:0] counter = 0;
