module alu
#(parameter DATA_WIDTH = 32)
(
    input [DATA_WIDTH-1:0] srcA,
    input [DATA_WIDTH-1:0] srcB,
    input [3:0] aluop,
    output reg [DATA_WIDTH-1:0] aluout,
    output zero,
    output of,
    output uof
);

    wire signed [DATA_WIDTH-1:0] signed_srcA;
    wire signed [DATA_WIDTH-1:0] signed_srcB;
    wire signed [DATA_WIDTH*2-1:0] signed_aluout;
    wire [DATA_WIDTH:0] unsigned_srcA;
    wire [DATA_WIDTH:0] unsigned_srcB;
    wire [DATA_WIDTH*2-1:0] unsigned_aluout;

    assign signed_srcA = $signed(srcA);
    assign signed_srcB = $signed(srcB);
    assign unsigned_srcA = $unsigned(srcA);
    assign unsigned_srcB = $unsigned(srcB);

    always @ ( * ) begin
        case (aluop)
            4'd0: aluout <= srcA << srcB;
            4'd1: aluout <= signed_srcA >>> srcB;
            4'd2: aluout <= srcA >> srcB;
            4'd3: begin
                    signed_aluout <= signed_srcA * signed_srcB;
                    if (signed_aluout[DATA_WIDTH*2-1:DATA_WIDTH] != {{DATA_WIDTH-1{signed_aluout[DATA_WIDTH*2-1]}}, signed_aluout[DATA_WIDTH-1:0]}) begin
                        of <= 1;
                    end else begin
                        of <= 0;
                    end
                    aluout <= signed_aluout[DATA_WIDTH-1:0];
                end
            4'd4: begin
                    if (srcB == 0) begin
                        aluout <= {DATA_WIDTH{1'b0}};
                        uof <= 1;
                    end else begin
                        aluout <= srcA / srcB;
                    end
                end
            4'd5: begin
                    signed_aluout <= signed_srcA + signed_srcB;
                    if (signed_aluout[DATA_WIDTH-1] != signed_srcA[DATA_WIDTH-1] & signed_aluout[DATA_WIDTH-1] != signed_srcB[DATA_WIDTH-1]) begin
                        of <= 1;
                    end else begin
                        of <= 0;
                    end
                    aluout <= signed_aluout[DATA_WIDTH-1:0];
                end
            4'd6: begin
                    signed_aluout <= signed_srcA - signed_srcB;
                    if (signed_aluout[DATA_WIDTH-1] != signed_srcA[DATA_WIDTH-1] & signed_aluout[DATA_WIDTH-1] == signed_srcB[DATA_WIDTH-1]) begin
                        of <= 1;
                    end else begin
                        of <= 0;
                    end
                    aluout <= signed_aluout[DATA_WIDTH-1:0];
                end
            4'd7: aluout <= srcA & srcB;
            4'd8: aluout <= srcA | srcB;
            4'd9: aluout <= srcA ^ srcB;
            4'd10: aluout <= ~(srcA | srcB);
            4'd11: begin
                    if (signed_srcA < signed_srcB) begin
                        aluout <= 1;
                    end else begin
                        aluout <= 0;
                    end
                end
            4'd12: begin
                    if (unsigned_srcA < unsigned_srcB) begin
                        aluout <= 1;
                    end else begin
                        aluout <= 0;
                    end
                end
            default: aluout <= 0;
        endcase
        if (aluop != 4) begin
            uof <= 0;
        end
        if (aluout == 0) begin
            zero <= 1;
        end else begin
            zero <= 0;
        end
    end

endmodule

module Modulo (
  input [n-1:0] numerator,
  input [n-1:0] denominator,
  output [n-1:0] remainder
);

parameter n = 8; // number of bits for numerator and denominator.

reg [n-1:0] quotient;
reg [n-1:0] dividend;

always @(*) begin
  if (denominator == 0) begin
    remainder = 0;
  end
  else if (numerator < denominator) begin
    remainder = numerator;
  end
  else begin
    quotient = numerator / denominator;
    dividend = quotient * denominator;
    remainder = numerator - dividend;
  end
end

endmodule

module ethernet_interface(
    input clk_100mhz,
    input clk_25mhz_rx,
    input clk_25mhz_tx,
    input rst_n,
    input [3:0] phy_rx_data,
    input phy_dv,
    input phy_rx_er,
    output reg phy_tx_en,
    output reg [3:0] phy_tx_data,
    output wire irq_rx,
    output wire irq_tx,
    input wire [31:0] wb_adr_i,
    input wire [31:0] wb_dat_i,
    output wire [31:0] wb_dat_o,
    input wire wb_cyc_i,
    input wire wb_stb_i,
    input wire wb_we_i,
    input wire [3:0] wb_sel_i,
    output wire wb_ack_o
);

/*
 * Configuration register map:
 * 0x00 - Reserved
 * 0x04 - Reserved
 * 0x08 - Interrupt Enable
 * 0x0C - Interrupt Status
 * 0x10 - RX Enable
 * 0x14 - TX Enable
 * 0x18 - TX Data
 */

reg [31:0] config_reg;
reg [31:0] tx_data;

reg [13:0] csr_a;
reg csr_we;
reg [31:0] csr_di;
wire [31:0] csr_do;

reg [31:0] wb_addr;
reg [31:0] wb_data;
wire [31:0] wb_resp;

wire [31:0] tx_fifo [0:7];
reg [2:0] tx_fifo_head;
reg [2:0] tx_fifo_tail;
reg [2:0] tx_fifo_count;
reg tx_fifo_full;

wire [31:0] rx_fifo [0:7];
reg [2:0] rx_fifo_head;
reg [2:0] rx_fifo_tail;
reg [2:0] rx_fifo_count;
reg rx_fifo_full;

wire [31:0] tx_fifo_next_addr;
wire [31:0] rx_fifo_next_addr;

assign wb_dat_o = (wb_ack_o) ? wb_resp : 32'hZZZZZZZZ;

assign irq_rx = (rx_fifo_count > 0);
assign irq_tx = (tx_fifo_count < 8);

assign tx_fifo_next_addr = wb_adr_i[7:3];
assign rx_fifo_next_addr = wb_adr_i[7:3];

assign wb_ack_o = (wb_cyc_i && wb_stb_i && ((wb_sel_i & 4'hF) == 4'hF));

always @(posedge clk_100mhz) begin
    if (!rst_n) begin
        config_reg <= 32'h00000000;
        tx_data <= 32'h00000000;
        csr_a <= 14'h0000;
        csr_di <= 32'h00000000;
        csr_we <= 1'b0;
        wb_addr <= 32'h00000000;
        wb_data <= 32'h00000000;
        tx_fifo_head <= 3'h0;
        tx_fifo_tail <= 3'h0;
        tx_fifo_count <= 3'h0;
        tx_fifo_full <= 1'b0;
        rx_fifo_head <= 3'h0;
        rx_fifo_tail <= 3'h0;
        rx_fifo_count <= 3'h0;
        rx_fifo_full <= 1'b0;
    end else begin
        if (csr_we) begin
            case (csr_a)
                14'h08: config_reg[0] <= csr_di[0];
                14'h10: config_reg[1] <= csr_di[0];
                14'h18: tx_data <= csr_di;
            endcase
        end
        if (wb_cyc_i && wb_stb_i) begin
            if (wb_we_i) begin
                if (wb_adr_i[31:3] == 28'h00000) begin
                    wb_addr <= wb_adr_i[2:0];
                    wb_data <= wb_dat_i;
                    case (wb_adr_i[7:3])
                        5'h00: begin
                            if (wb_adr_i[2:0] == 3'h0) begin
                                csr_a <= wb_dat_i[31:16];
                            end else if (wb_adr_i[2:0] == 3'h1) begin
                                csr_di <= wb_dat_i;
                                csr_we <= 1'b1;
                            end
                        end
                        5'h01: begin
                            if (wb_adr_i[2:0] == 3'h0) begin
                                tx_fifo_count <= tx_fifo_count + 1;
                                tx_fifo[tx_fifo_head] <= wb_dat_i;
                                tx_fifo_head <= tx_fifo_head + 1;
                                if (tx_fifo_head == 3'h8) begin
                                    tx_fifo_head <= 3'h0;
                                end
                                if (tx_fifo_head == tx_fifo_tail) begin
                                    tx_fifo_full <= 1'b1;
                                end
                            end
                        end
                    endcase
                end
            end else begin
                if (wb_adr_i[31:3] == 28'h00000) begin
                    case (wb_adr_i[7:3])
                        5'h00: begin
                            case (wb_adr_i[2:0])
                                3'h0: wb_resp <= {18'h0000, csr_a};
                                3'h1: wb_resp <= csr_do;
                                default: wb_resp <= 32'h00000000;
                            endcase
                        end
                        5'h01: begin
                            if (wb_adr_i[2:0] == 3'h0) begin
                                rx_fifo_count <= rx_fifo_count - 1;
                                rx_fifo_tail <= rx_fifo_tail + 1;
                                if (rx_fifo_tail == 3'h8) begin
                                    rx_fifo_tail <= 3'h0;
                                end
                                if (rx_fifo_full) begin
                                    rx_fifo_full <= 1'b0;
                                end
                            end
                            wb_resp <= rx_fifo[rx_fifo_tail];
                        end
                        default: wb_resp <= 32'h00000000;
                    endcase
                end
            end
        end
    end
end

always @(posedge clk_25mhz_rx) begin
    if (phy_dv) begin
        if (!rx_fifo_full) begin
            rx_fifo_count <= rx_fifo_count + 1;
            rx_fifo[rx_fifo_head] <= phy_rx_data;
            rx_fifo_head <= rx_fifo_head + 1;
            if (rx_fifo_head == 3'h8) begin
                rx_fifo_head <= 3'h0;
            end
            if (rx_fifo_head == rx_fifo_tail) begin
                rx_fifo_full <= 1'b1;
            end
        end
    end
end

always @(posedge clk_25mhz_tx) begin
    if (tx_fifo_count > 0 && !tx_fifo_full) begin
        tx_fifo_count <= tx_fifo_count - 1;
        tx_fifo_tail <= tx_fifo_tail + 1;
        if (tx_fifo_tail == 3'h8) begin
            tx_fifo_tail <= 3'h0;
        end
        phy_tx_en <= 1'b1;
        phy_tx_data <= tx_fifo[tx_fifo_tail];
        if (tx_fifo_count == 1) begin
            tx_fifo_full <= 1'b0;
        end
    end else begin
        phy_tx_en <= 1'b0;
    end
end

endmodule

