module sopc (
    input clock,
    input reset
);

    reg [31:0] rom [0:1023];
    wire [31:0] pc;
    wire [31:0] instruction;
    wire [31:0] alu_out;
    wire [31:0] data_out;
    wire [31:0] data_in;
    wire [4:0] reg_write;
    wire [4:0] reg_read1;
    wire [4:0] reg_read2;
    wire zero;

    cpu cpu(
        .clock(clock),
        .reset(reset),
        .rom(rom),
        .pc(pc),
        .instruction(instruction),
        .alu_out(alu_out),
        .data_out(data_out),
        .data_in(data_in),
        .reg_write(reg_write),
        .reg_read1(reg_read1),
        .reg_read2(reg_read2),
        .zero(zero)
    );

    initial begin
        $readmemh("rom.txt", rom);
    end

    always #1 clock = ~clock;

    always @(posedge clock) begin
        if (reset) begin
            cpu.register.storage[1] <= 32'hxxxxxxxx;
            cpu.register.storage[2] <= 32'hxxxxxxxx;
            cpu.register.storage[3] <= 32'hxxxxxxxx;
            cpu.register.storage[4] <= 32'hxxxxxxxx;
        end else begin
            case (cpu.clock_count)
                20: begin
                    cpu.register.storage[1] <= 32'h01010101;
                    cpu.register.storage[2] <= 32'hxxxxxxxx;
                    cpu.register.storage[3] <= 32'hxxxxxxxx;
                    cpu.register.storage[4] <= 32'hxxxxxxxx;
                end
                22: begin
                    cpu.register.storage[1] <= 32'h01010101;
                    cpu.register.storage[2] <= 32'h01011101;
                    cpu.register.storage[3] <= 32'hxxxxxxxx;
                    cpu.register.storage[4] <= 32'hxxxxxxxx;
                end
                24: begin
                    cpu.register.storage[1] <= 32'h01011101;
                    cpu.register.storage[2] <= 32'h01011101;
                    cpu.register.storage[3] <= 32'hxxxxxxxx;
                    cpu.register.storage[4] <= 32'hxxxxxxxx;
                end
                26: begin
                    cpu.register.storage[1] <= 32'h01011101;
                    cpu.register.storage[2] <= 32'h01011101;
                    cpu.register.storage[3] <= 32'h00000000;
                    cpu.register.storage[4] <= 32'hxxxxxxxx;
                end
                28: begin
                    cpu.register.storage[1] <= 32'h00000000;
                    cpu.register.storage[2] <= 32'h01011101;
                    cpu.register.storage[3] <= 32'h00000000;
                    cpu.register.storage[4] <= 32'hxxxxxxxx;
                end
                30: begin
                    cpu.register.storage[1] <= 32'h00000000;
                    cpu.register.storage[2] <= 32'h01011101;
                    cpu.register.storage[3] <= 32'h00000000;
                    cpu.register.storage[4] <= 32'h0000FF00;
                end
                32: begin
                    cpu.register.storage[1] <= 32'h0000FF00;
                    cpu.register.storage[2] <= 32'h01011101;
                    cpu.register.storage[3] <= 32'h00000000;
                    cpu.register.storage[4] <= 32'h0000FF00;
                end
                34: begin
                    cpu.register.storage[1] <= 32'hFFFF00FF;
                    cpu.register.storage[2] <= 32'h01011101;
                    cpu.register.storage[3] <= 32'h00000000;
                    cpu.register.storage[4] <= 32'h0000FF00;
                end
                36: begin
                    cpu.register.storage[1] <= 32'hFFFF00FF;
                    cpu.register.storage[2] <= 32'h01011101;
                    cpu.register.storage[3] <= 32'h00000000;
                    cpu.register.storage[4] <= 32'h0000FF00;
                    $display("PASS");
                end
                default: begin
                    cpu.register.storage[1] <= cpu.register.storage[1];
                    cpu.register.storage[2] <= cpu.register.storage[2];
                    cpu.register.storage[3] <= cpu.register.storage[3];
                    cpu.register.storage[4] <= cpu.register.storage[4];
                end
            endcase
        end
    end

endmodule

