   reg RX_PEND;
   reg TX_FAIL;
   reg TX_SUCC;

   reg [1:0] state;
   reg [1:0] next_state;

   reg [7:0] tx_buffer;
   reg [19:0] tx_addr_buffer;
   reg tx_pending;

   reg [7:0] rx_buffer;
   reg [19:0] rx_addr_buffer;
   reg rx_pending;
   reg rx_broadcast;

   always @(posedge CLKIN or negedge RESETn) begin
      if (!RESETn) begin
         CLKOUT <= 1'b0;
         DOUT <= 1'b0;
         TX_ACK <= 1'b0;
         RX_ADDR <= 20'h0;
         RX_DATA <= 8'h0;
         RX_REQ <= 1'b0;
         RX_BROADCAST <= 1'b0;
         RX_FAIL <= 1'b0;
         RX_PEND <= 1'b0;
         TX_FAIL <= 1'b0;
         TX_SUCC <= 1'b0;
         state <= 2'b00;
         next_state <= 2'b00;
         tx_buffer <= 8'h0;
         tx_addr_buffer <= 20'h0;
         tx_pending <= 1'b0;
         rx_buffer <= 8'h0;
         rx_addr_buffer <= 20'h0;
         rx_pending <= 1'b0;
         rx_broadcast <= 1'b0;
      end else begin
         CLKOUT <= ~CLKOUT;
         case (state)
            2'b00: begin
               DOUT <= DIN;
               if (TX_REQ) begin
                  tx_buffer <= TX_DATA;
                  tx_addr_buffer <= TX_ADDR;
                  tx_pending <= 1'b1;
                  next_state <= 2'b01;
               end else if (RX_REQ) begin
                  rx_pending <= 1'b1;
                  next_state <= 2'b10;
               end
            end
            2'b01: begin
               if (tx_pending) begin
                  DOUT <= tx_buffer;
                  tx_pending <= 1'b0;
                  next_state <= 2'b00;
               end else if (TX_RESP_ACK) begin
                  TX_ACK <= 1'b1;
                  TX_SUCC <= 1'b1;
                  next_state <= 2'b00;
               end else begin
                  TX_ACK <= 1'b0;
                  TX_FAIL <= 1'b1;
                  next_state <= 2'b00;
               end
            end
            2'b10: begin
               if (rx_pending) begin
                  rx_buffer <= DIN;
                  rx_pending <= 1'b0;
                  next_state <= 2'b11;
               end
            end
            2'b11: begin
               rx_addr_buffer <= DIN;
               if (rx_addr_buffer == ADDRESS) begin
                  RX_ADDR <= rx_addr_buffer;
                  RX_DATA <= rx_buffer;
                  RX_REQ <= 1'b1;
                  rx_broadcast <= 1'b0;
                  if (RX_DATA[7:0] == 8'hFF) begin
                     RX_BROADCAST <= 1'b1;
                     rx_broadcast <= 1'b1;
                  end
                  RX_PEND <= 1'b0;
                  RX_FAIL <= 1'b0;
                  next_state <= 2'b00;
               end else if (rx_pending) begin
                  RX_PEND <= 1'b1;
                  next_state <= 2'b10;
               end else begin
                  RX_FAIL <= 1'b1;
                  next_state <= 2'b00;
               end
            end
         endcase
         state <= next_state;
      end
   end

endmodule

