    output [7:0] total_money,
    output [1:0] num_dispensed
    );

    reg [7:0] total_money_reg = 0;
    reg [1:0] num_dispensed_reg = 0;
    reg [7:0] change_reg = 0;
    reg [1:0] product_reg = 0;

