        if (button == 2'b00 && money >= price) begin
            total_money_reg = total_money_reg + money;
            num_dispensed_reg = num_dispensed_reg + 1;
            change_reg = money - price;
            product_reg = 2'b00;
        end else if (button == 2'b01 && money >= price) begin
            total_money_reg = total_money_reg + money;
            num_dispensed_reg = num_dispensed_reg + 1;
            change_reg = money - price;
            product_reg = 2'b01;
