reg [n-1:0] next_state; // next state

// Gray code sequence
always @(*) begin
  case(state)
    0: next_state = 1;
    1: next_state = 3;
    2: next_state = 6;
    3: next_state = 4;
    4: next_state = 5;
    5: next_state = 7;
    6: next_state = 2;
    7: next_state = 0;
  endcase
end

