module adder_4bit(
    input [3:0] in1,
    input [3:0] in2,
    output [4:0] out,
    output cout
);

wire [3:0] sum;
wire carry;

// Full adder for 1-bit inputs
// Returns the sum and carry out
// of the two inputs and a carry in
function [1:0] full_adder;
    input a, b, c;
    begin
        {carry, sum} = a + b + c;
    end
endfunction

// 4-bit ripple carry adder
// Chains together full adders to add
// the two 4-bit inputs
genvar i;
generate
    for (i = 0; i < 4; i = i + 1) begin : adder_gen
        full_adder fa(
            .a(in1[i]),
            .b(in2[i]),
            .c(i == 0 ? 1'b0 : carry),
            .sum(sum[i]),
            .carry(carry)
        );
    end
endgenerate

assign cout = carry;
assign out = {carry, sum};

endmodule

