module HMAC (
  input [k-1:0] key,
  input [m-1:0] msg,
  input [h-1:0] hash,
  output [h-1:0] out,
  output valid
);

parameter k = 128; // key length in bits
parameter m = 512; // message length in bits
parameter h = 256; // hash length in bits

// Define the block size for the hash function
localparam blockSize = h * 8;

// Define the inner and outer padding constants
localparam innerPad = 8'h36;
localparam outerPad = 8'h5C;

// Define the intermediate signals
wire [blockSize-1:0] keyPadded;
wire [blockSize-1:0] keyXorInnerPad;
wire [blockSize-1:0] keyXorOuterPad;
wire [blockSize+m-1:0] innerConcat;
wire [blockSize+h-1:0] outerConcat;

// Instantiate the hash function module
HashFunction hashFunc1(.dataIn(innerConcat), .dataOut(out));
HashFunction hashFunc2(.dataIn(outerConcat), .dataOut(hash));

// Pad the key if necessary
assign keyPadded = (k > blockSize) ? hashFunc1(key) : {blockSize-k{1'b0}} | key;

// XOR the key with the inner and outer padding
assign keyXorInnerPad = keyPadded ^ {blockSize{innerPad}};
assign keyXorOuterPad = keyPadded ^ {blockSize{outerPad}};

// Concatenate the results with the message and the hash
assign innerConcat = {keyXorInnerPad, msg};
assign outerConcat = {keyXorOuterPad, out};

// Compare the computed hash with the input hash
assign valid = (hash == out);

endmodule

