module pipeline (
  input clk,
  input reset,
  input [31:0] data1,
  input [31:0] data2,
  input [7:0] instruction,
  input [2:0] stage,
  input [3:0] rs1,
  input [3:0] rs2,
  input [3:0] rd,
  output reg [31:0] regfile [15:0]
);

reg [31:0] pc;
reg [31:0] instr;
reg [31:0] alu_out;
reg [3:0] rd_reg;
reg [31:0] rd_data;

always @(posedge clk) begin
  if (reset) begin
    pc <= 0;
    instr <= 0;
    alu_out <= 0;
    rd_reg <= 0;
    rd_data <= 0;
  end else begin
    case (stage)
      0: begin // instruction fetch
        instr <= $readmemh("program.mem", pc >> 2);
        pc <= pc + 4;
      end
      1: begin // instruction decode
        rd_reg <= instruction[11:8];
        if (instruction[7:0] == 8'h00) begin // add
          alu_out <= data1 + data2;
        end else if (instruction[7:0] == 8'h01) begin // subtract
          alu_out <= data1 - data2;
        end else if (instruction[7:0] == 8'h02) begin // bitwise and
          alu_out <= data1 & data2;
        end else if (instruction[7:0] == 8'h03) begin // bitwise or
          alu_out <= data1 | data2;
        end else if (instruction[7:0] == 8'h04) begin // bitwise xor
          alu_out <= data1 ^ data2;
        end else if (instruction[7:0] == 8'h05) begin // shift left logical
          alu_out <= data1 << data2[4:0];
        end else if (instruction[7:0] == 8'h06) begin // shift right logical
          alu_out <= data1 >> data2[4:0];
        end else if (instruction[7:0] == 8'h07) begin // shift right arithmetic
          alu_out <= $signed(data1) >>> data2[4:0];
        end else begin
          alu_out <= 0;
        end
      end
      2: begin // write back
        regfile[rd_reg] <= alu_out;
      end
    endcase
  end
end

always @(posedge clk) begin
  if (reset) begin
    rd_data <= 0;
  end else begin
    rd_data <= regfile[rs2];
  end
end

endmodule

