end

always @(*) begin
    stage2_out = (B[2]) ? {stage1_out[1:0], 2'b00} : {2'b00, stage1_out[3:2]};
end

always @(*) begin
    Q = (B[1]) ? {stage2_out[0], stage2_out[3:1]} : {stage2_out[2:0], stage2_out[3]};
end

endmodule

module ps2_interface(
    input io_read_clk,
    input clk_ps2,
    input rst,
    input PS2_clk,
    input PS2_Data,
    input ps2_iack,
    input [31:0] dat_i,
    input [31:0] adr_i,
    input we_i,
    input stb_i,
    output reg [31:0] dat_o,
    output ack_o,
    output [7:0] ps2_key,
    output [7:0] key
);

reg [31:0] key_d;
wire ps2_rdn;
wire ps2_rd;
wire ps2_irq;
wire ps2_ready;

assign ps2_irq = ps2_ready & ~ps2_iack;
assign ack_o = stb_i;

assign ps2_rd = stb_i & ack_o & ~we_i;

assign ps2_rdn = ~(ps2_rd & ps2_ready);

always @(posedge ps2_rd or posedge rst) begin
    if(rst) begin
        key_d <= 0;
    end else if(ps2_ready) begin
        key_d <= {key_d[23:0], ps2_key};
        dat_o <= {23'h0, ps2_ready, ps2_key};
    end else begin
        dat_o <= 32'h0000_00bb;
    end
end

ps2_kbd ps2_kbd(
    .clk(clk_ps2),
    .clrn(~rst),
    .ps2_clk(PS2_clk),
    .ps2_data(PS2_Data),
    .rdn(ps2_rdn),
    .data(ps2_key),
    .ready(ps2_ready),
    .overflow()
);

always @(posedge io_read_clk) begin
    if(stb_i && ack_o) begin
        if(we_i && ps2_ready) begin
            ps2_key <= dat_i[7:0];
        end
    end
end

assign key = {ps2_key, ~^ps2_key};

endmodule

module motor_control (
