// PWM block
module PWM (
  input clk,
  input rst,
  input [7:0] duty_cycle,
  input [15:0] frequency,
  output reg pwm_out
);

reg [15:0] counter;
reg [7:0] threshold;

always @(posedge clk) begin
  if (rst) begin
    counter <= 0;
    threshold <= 0;
    pwm_out <= 0;
  end else begin
    counter <= counter + 1;
    if (counter == frequency) begin
      counter <= 0;
      threshold <= (duty_cycle * PWM_WIDTH) / 100;
    end
    if (counter < threshold) begin
      pwm_out <= 1;
    end else begin
      pwm_out <= 0;
    end
  end
end

endmodule

// H-bridge block
module H_bridge (
  input clk,
  input rst,
  input [1:0] dir,
  input pwm_in,
  output reg h_bridge_out
);

always @(posedge clk) begin
  if (rst) begin
    h_bridge_out <= 0;
  end else begin
    if (dir == 0) begin
      h_bridge_out <= pwm_in;
    end else begin
      h_bridge_out <= ~pwm_in;
    end
  end
end

endmodule

// Stepper motor controller block
module Stepper_motor_controller (
  input clk,
  input rst,
  input [1:0] dir,
  input [15:0] steps,
  output reg step_out
);

reg [15:0] counter;

always @(posedge clk) begin
  if (rst) begin
    counter <= 0;
    step_out <= 0;
  end else begin
    if (counter == steps) begin
      counter <= 0;
    end else begin
      counter <= counter + 1;
      if (dir == 0) begin
        step_out <= 1;
      end else begin
        step_out <= 0;
      end
    end
  end
end

endmodule

module accumulator
  #(parameter IWIDTH=16, OWIDTH=30)
    (input clk,
     input clear,
     input acc,
     input signed [IWIDTH-1:0] in,
     output reg signed [OWIDTH-1:0] out);

   wire signed [OWIDTH-1:0] in_signext;
   sign_extend #(.bits_in(IWIDTH),.bits_out(OWIDTH)) 
     acc_signext (.in(in),.out(in_signext));

   //  CLEAR & ~ACC  -->  clears the accumulator
   //  CLEAR & ACC -->    loads the accumulator
   //  ~CLEAR & ACC -->   accumulates
   //  ~CLEAR & ~ACC -->  hold

   wire signed [OWIDTH-1:0] addend1 = clear ? 0 : out;
   wire signed [OWIDTH-1:0] addend2 = ~acc ? 0 : in_signext;
   wire signed [OWIDTH-1:0] sum_int = addend1 + addend2;

   always @(posedge clk)
     out <= sum_int;

endmodule

module IF_STAGE(
  input         clk,
  input         rst,
  input         instr_fetch_enable,
  input [5:0]   imm_branch_offset,
  input         branch_enable,
  input         jump,
  output [7:0]  pc,
  output [15:0] instr
);

  wire[7:0] PCI;
  wire[7:0] PCO;
  wire[7:0] PCAdd1O;
  wire[7:0] PC1AddBr8;
  wire[7:0] Br8;
  wire[1:0] Mux4Select;

  // Six-to-eight bit sign extension module
  SixToEightExtend mySixToEight(
      .In(imm_branch_offset),
      .Out(Br8)
  );

  // Program counter module
  PC myPC(
      .clock(clk), 
      .reset(rst), 
      .PCEn(instr_fetch_enable),
      .in(PCI), 
      .out(PCO)
  );

  // Adder module to add 1 to program counter
  Add myPCByOne( 
    .a(PCO),
    .b(8'b00000001),
    .out(PCAdd1O)
  );

  // Adder module to add branch offset to program counter + 1
  Add myPC1ByBz( 
    .a(Br8),
    .b(PCAdd1O),
    .out(PC1AddBr8)
  );

  // Multiplexer module to select between program counter + 1, program counter + branch offset, and jump
  MUX4#(8) myIfMux4(
  .SLCT(Mux4Select), 
  .IN3(), 
  .IN2(Br8), 
  .IN1(PC1AddBr8), 
  .IN0(PCAdd1O), 
  .OT(PCI)
  );

  // Instruction memory module
  InstructionMemory#(256) myInstMem( 
    .reset(rst),
    .addr(PCO),
    .inst(instr)
  );

  // Output program counter
  assign pc = PCO;

endmodule

module adapter_ppfifo_2_axi_stream #(
  parameter DATA_WIDTH = 32,
  parameter STROBE_WIDTH = DATA_WIDTH / 8,
  parameter USE_KEEP = 0
)(
  input rst,

  //Ping Poing FIFO Read Interface
  input i_ppfifo_rdy,
  output reg o_ppfifo_act,
  input [23:0] i_ppfifo_size,
  input [(DATA_WIDTH + 1) - 1:0] i_ppfifo_data,
  output o_ppfifo_stb,

  //AXI Stream Output
  input i_axi_clk,
  output [3:0] o_axi_user,
  input i_axi_ready,
  output [DATA_WIDTH - 1:0] o_axi_data,
  output o_axi_last,
  output reg o_axi_valid,

  output [31:0] o_debug
);

  //local parameters
  localparam IDLE = 0;
  localparam READY = 1;
  localparam RELEASE = 2;

  //registes/wires
  reg [3:0] state;
  reg [23:0] r_count;

  //submodules
  //asynchronous logic
  assign o_axi_data = i_ppfifo_data[DATA_WIDTH - 1:0];
  assign o_ppfifo_stb = (i_axi_ready & o_axi_valid);

  assign o_axi_user[0] = (r_count < i_ppfifo_size) ? i_ppfifo_data[DATA_WIDTH] : 1'b0;
  assign o_axi_user[3:1] = 3'h0;

  assign o_axi_last = ((r_count + 1) >= i_ppfifo_size) & o_ppfifo_act & o_axi_valid;
  //synchronous logic
  assign o_debug[3:0] = state;
  assign o_debug[4] = (r_count < i_ppfifo_size) ? i_ppfifo_data[DATA_WIDTH] : 1'b0;
  assign o_debug[5] = o_ppfifo_act;
  assign o_debug[6] = i_ppfifo_rdy;
  assign o_debug[7] = (r_count > 0);
  assign o_debug[8] = (i_ppfifo_size > 0);
  assign o_debug[9] = (r_count == i_ppfifo_size);
  assign o_debug[15:10] = 0;
  assign o_debug[23:16] = r_count[7:0];
  assign o_debug[31:24] = 0;

  always @(posedge i_axi_clk) begin
    o_axi_valid <= 0;

    if (rst) begin
      state <= IDLE;
      o_ppfifo_act <= 0;
      r_count <= 0;
    end
    else begin
      case (state)
        IDLE: begin
          o_ppfifo_act <= 0;
          if (i_ppfifo_rdy && !o_ppfifo_act) begin
            r_count <= 0;
            o_ppfifo_act <= 1;
            state <= READY;
          end
        end
        READY: begin
          if (r_count < i_ppfifo_size) begin
            o_axi_valid <= 1;
            if (i_axi_ready && o_axi_valid) begin
              r_count <= r_count + 1;
              if ((r_count + 1) >= i_ppfifo_size) begin
                o_axi_valid <= 0;
              end
            end
          end
          else begin
            o_ppfifo_act <= 0;
            state <= RELEASE;
          end
        end
        RELEASE: begin
          state <= IDLE;
        end
        default: begin
        end
      endcase
    end
  end

endmodule

module HMAC (
  input [63:0] key,
  input [511:0] msg,
  input gen_hmac,
  input check_hmac,
  output [255:0] hmac,
  output hmac_ok
);

  // Define SHA-256 hash function
  // ...

  // Define constants
  parameter BLOCK_SIZE = 64;
  parameter HASH_SIZE = 256;
  parameter IPAD = 8'h36;
  parameter OPAD = 8'h5c;

  // Define internal signals
  reg [BLOCK_SIZE-1:0] inner_key;
  reg [BLOCK_SIZE-1:0] outer_key;
  reg [HASH_SIZE-1:0] inner_hash;
  reg [HASH_SIZE-1:0] outer_hash;
  reg [HASH_SIZE-1:0] computed_hmac;
  reg [HASH_SIZE-1:0] input_hmac;
  reg hmac_match;

  // Pad key if necessary
  always @(*) begin
    if (key > BLOCK_SIZE) begin
      inner_key = sha256(key);
    end else begin
      inner_key = {key, {64*8-$size(key){1'b0}}};
    end
  end

  // Compute inner and outer keys
  always @(*) begin
    outer_key = inner_key ^ {64{OPAD}};
    inner_key = inner_key ^ {64{IPAD}};
  end

  // Compute HMAC
  always @(*) begin
    if (gen_hmac) begin
      inner_hash = sha256({inner_key, msg});
      outer_hash = sha256({outer_key, inner_hash});
      computed_hmac = outer_hash;
    end else if (check_hmac) begin
      inner_hash = sha256({inner_key, msg});
      outer_hash = sha256({outer_key, inner_hash});
      computed_hmac = outer_hash;
      input_hmac = hmac;
      hmac_match = (computed_hmac == input_hmac);
    end
  end

  // Assign outputs
  assign hmac = computed_hmac;
  assign hmac_ok = hmac_match;

endmodule

module my_module (
    Q      ,
    Q_N    ,
    CLK    ,
    D      ,
    SCD    ,
    SCE    ,
    RESET_B
);

    // Module ports
    output Q      ;
    output Q_N    ;
    input  CLK    ;
    input  D      ;
    input  SCD    ;
    input  SCE    ;
    input  RESET_B;

    // Module supplies
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    // Local signals
    wire buf_Q          ;
    wire RESET          ;
    wire mux_out        ;
    reg  notifier       ;
    wire cond0          ;
    wire cond1          ;
    wire cond2          ;
    wire cond3          ;
    wire D_delayed      ;
    wire SCD_delayed    ;
    wire SCE_delayed    ;
    wire RESET_B_delayed;
    wire CLK_delayed    ;

    //                                   Name       Output   Other arguments
    not                                  not0      (RESET  , RESET_B_delayed                                  );
    sky130_fd_sc_hvl__udp_mux_2to1       mux_2to10 (mux_out, D_delayed, SCD_delayed, SCE_delayed              );
    sky130_fd_sc_hvl__udp_dff$PR_pp$PG$N dff0      (buf_Q  , mux_out, CLK_delayed, RESET, notifier, VPWR, VGND);

    assign cond0 = ( RESET_B_delayed === 1'b1 );
    assign cond1 = ( ( SCE_delayed === 1'b0 ) & cond0 );
    assign cond2 = ( ( SCE_delayed === 1'b1 ) & cond0 );
    assign cond3 = ( ( D_delayed !== SCD_delayed ) & cond0 );

    buf                                  buf0      (Q      , buf_Q                                            );
    not                                  not1      (Q_N    , buf_Q                                            );

    // Delayed inputs
    sky130_fd_sc_hvl__udp_dff$SR_pp$PG$N dff1 (D_delayed      , D      , CLK_delayed, RESET, notifier, VPWR, VGND);
    sky130_fd_sc_hvl__udp_dff$SR_pp$PG$N dff2 (SCD_delayed    , SCD    , CLK_delayed, RESET, notifier, VPWR, VGND);
    sky130_fd_sc_hvl__udp_dff$SR_pp$PG$N dff3 (SCE_delayed    , SCE    , CLK_delayed, RESET, notifier, VPWR, VGND);
    sky130_fd_sc_hvl__udp_dff$SR_pp$PG$N dff4 (RESET_B_delayed, RESET_B, CLK_delayed, RESET, notifier, VPWR, VGND);
    sky130_fd_sc_hvl__udp_dff$SR_pp$PG$N dff5 (CLK_delayed    , CLK    , VPWR       , RESET, notifier, VPWR, VGND);

    always @(posedge CLK) begin
        if (cond1) begin
            buf_Q <= 1'b0;
        end else if (cond2) begin
            buf_Q <= D_delayed;
        end else if (cond3) begin
            buf_Q <= SCD_delayed;
        end else begin
            buf_Q <= buf_Q;
        end
    end

endmodule

