module falling_edge_detector (
    input clk,
    input reset,
    input [31:0] in,
    output [31:0] out
);
    reg [31:0] prev_in;
    reg [31:0] capture;

    always @(posedge clk, negedge reset) begin
        if (reset == 0) begin
            prev_in <= 0;
            capture <= 0;
        end else begin
            prev_in <= in;
            capture <= (prev_in & ~in);
        end
    end

    assign out = capture;
endmodule

