module hcsr04 (
  input rst,
  input clk,
  input tclk,
  input measure,
  input echo,
  output reg [15:0] ticks,
  output reg valid,
  output reg trigger
);

  parameter TRIGGER_DURATION = 1;
  parameter MAX_COUNT = 3800;

  reg [15:0] count;
  reg [15:0] trigger_count;
  reg [15:0] echo_count;

  always @(posedge tclk) begin
    if (rst) begin
      count <= 0;
      trigger_count <= 0;
      echo_count <= 0;
      trigger <= 0;
      valid <= 0;
      ticks <= 0;
    end else begin
      if (measure) begin
        trigger_count <= trigger_count + 1;
        if (trigger_count == TRIGGER_DURATION) begin
          trigger_count <= 0;
          trigger <= 1;
        end else if (trigger_count == TRIGGER_DURATION + 1) begin
          trigger <= 0;
          count <= 0;
        end
      end else begin
        if (echo) begin
          echo_count <= 0;
        end else begin
          echo_count <= echo_count + 1;
          if (echo_count == MAX_COUNT) begin
            valid <= 0;
          end
        end
        if (count > 0) begin
          count <= count - 1;
        end else if (trigger) begin
          count <= MAX_COUNT;
        end else if (!echo) begin
          valid <= 1;
          ticks <= MAX_COUNT - count;
        end
      end
    end
  end

endmodule

module phase_detector (
  input ref_clk,
  input fb_clk,
  output reg pd_out
);

always @(posedge ref_clk or posedge fb_clk) begin
  pd_out <= ref_clk ^ fb_clk;
end

endmodule

module loop_filter (
  input clk,
  input reset,
  input pd_in,
  output reg [7:0] filter_out
);

parameter Kp = 1;
parameter Ki = 1;
parameter Kd = 1;

reg [7:0] error;
reg [7:0] integral;
reg [7:0] derivative;
reg [7:0] last_error;

always @(posedge clk) begin
  if (reset) begin
    error <= 0;
    integral <= 0;
    derivative <= 0;
    last_error <= 0;
  end else begin
    error <= pd_in;
    integral <= integral + error;
    derivative <= error - last_error;
    last_error <= error;
    filter_out <= Kp*error + Ki*integral + Kd*derivative;
  end
end

endmodule

module vco (
  input clk,
  input reset,
  input [7:0] control_voltage,
  output reg vco_out
);

parameter MAX_FREQ = 1000;

reg [31:0] phase_accumulator;
reg [31:0] phase_increment;

always @(posedge clk) begin
  if (reset) begin
    phase_accumulator <= 0;
    phase_increment <= 0;
    vco_out <= 0;
  end else begin
    phase_accumulator <= phase_accumulator + phase_increment;
    if (phase_accumulator >= MAX_FREQ) begin
      phase_accumulator <= phase_accumulator - MAX_FREQ;
      vco_out <= ~vco_out;
    end
  end
end

assign phase_increment = (control_voltage * F) / MAX_FREQ;

endmodule

module frequency_divider (
  input clk,
  input reset,
  input [7:0] divide_factor,
  output reg fd_out
);

reg [7:0] counter;

always @(posedge clk) begin
  if (reset) begin
    counter <= 0;
    fd_out <= 0;
  end else begin
    counter <= counter + 1;
    if (counter >= divide_factor) begin
      counter <= 0;
      fd_out <= ~fd_out;
    end
  end
end

endmodule

module PLL (
  input ref_clk,
  input fb_clk,
  input rst,
  output pll_clk
);

parameter N = 10; // multiplication factor
parameter M = 5; // division factor
parameter F = 100; // VCO frequency multiplication factor

wire pd_out;
wire [7:0] filter_out;
wire [7:0] control_voltage;
wire vco_out;
wire fd_out;

phase_detector pd(ref_clk, fb_clk, pd_out);
loop_filter lf(fd_out, rst, pd_out, filter_out);
vco v(clk, rst, filter_out, vco_out);
frequency_divider fd(vco_out, rst, M, fd_out);

assign pll_clk = fd_out;

endmodule

module calculator (
    input clk,
    input reset,
    input [3:0] operand1,
    input [3:0] operand2,
    input operation,
    output reg [3:0] result,
    output reg overflow
);

always @(posedge clk) begin
    if (reset) begin
        result <= 4'b0;
        overflow <= 1'b0;
    end else begin
        if (operation == 1'b0) begin
            result <= operand1 + operand2;
            overflow <= (result > 4'b1111);
        end else begin
            result <= operand1 - operand2;
            overflow <= (result < 4'b0000);
        end
    end
end

endmodule

