    input B1,
    output X
);

    wire A1_not;
    wire A2_not;
    wire A1_and_A2;
    wire A1_nand_A2;
    wire B1_not;
    wire A1_and_A2_nand_B1;

    assign A1_not = ~A1;
    assign A2_not = ~A2;
    assign A1_and_A2 = A1 & A2;
    assign A1_nand_A2 = ~(A1 & A2);
    assign B1_not = ~B1;
    assign A1_and_A2_nand_B1 = ~(A1 & A2 & B1);

    assign X = (A1 & A2_not) | (A1_not & A2) | (B1_not & A1_and_A2_nand_B1);

endmodule

module bin_to_gray(
  input clk,
  input rst,
  input [3:0] bin,
  output reg [3:0] gray
);

  reg [3:0] gray_prev;

  assign gray = bin ^ (bin >> 1);

  always @(posedge clk) begin
    if (rst) begin
      gray_prev <= 4'b0;
      gray <= 4'b0;
    end
    else begin
      gray_prev <= gray;
    end
  end

  always @(posedge clk) begin
    if (rst) begin
      gray <= 4'b0;
    end
    else begin
      if (gray != gray_prev) begin
        gray <= gray;
      end
    end
  end

endmodule

