module xor_module (
    input [3:0] a,     // 4-bit input A
    input [3:0] b,     // 4-bit input B
    output reg [3:0] y // 4-bit output
);

    always @(*) begin
        y = a ^ b;
    end

endmodule

module top_module (
    input clk,         // Clock input for both counters
    input reset,       // Synchronous active-high reset for both counters
    input select,      // Select input to choose between the two counters
    output reg [3:0] q // 4-bit output from the active counter
);

    wire [3:0] counter1_q;
    wire [3:0] counter2_q;
    wire [3:0] xor_output;

    binary_counter counter1 (
        .clk(clk),
        .reset(reset),
        .q(counter1_q)
    );

    binary_counter counter2 (
        .clk(clk),
        .reset(reset),
        .q(counter2_q)
    );

    xor_module xor (
        .a(counter1_q),
        .b(counter2_q),
        .y(xor_output)
    );

    always @(posedge clk) begin
        if (reset) begin
            q <= 4'b0000;
        end else begin
            if (select) begin
                q <= counter2_q;
            end else begin
                q <= counter1_q;
            end
        end
    end

endmodule

