module clock_generator (
  input clk_freq,
  input duty_cycle,
  input reset,
  output reg clk_out
);

parameter CLK_PERIOD = 1 / clk_freq; // period of the generated clock signal
parameter HALF_CLK_PERIOD = CLK_PERIOD / 2; // half of the period of the generated clock signal

reg [31:0] high_time; // high time of the clock signal
reg [31:0] low_time; // low time of the clock signal
reg [31:0] count; // counter for the clock signal
reg edge; // edge detector for the clock signal

always @ (posedge reset) begin
  high_time <= 0;
  low_time <= 0;
  count <= 0;
  edge <= 0;
end

always @ (posedge clk_freq or posedge reset) begin
  if (reset) begin
    high_time <= 0;
    low_time <= 0;
    count <= 0;
    edge <= 0;
  end else begin
    if (edge) begin
      high_time <= CLK_PERIOD * (duty_cycle / 100);
      low_time <= CLK_PERIOD - high_time;
      edge <= 0;
    end else begin
      if (count >= high_time) begin
        clk_out <= 1;
        edge <= 1;
        count <= 0;
      end else begin
        clk_out <= 0;
        count <= count + 1;
      end
    end
  end
end

endmodule

