reg [31:0] phase_accumulator;
reg tone_detected;

localparam TWOPI = 32'h6487ED51; // 2 * pi in fixed-point format

// Calculate the detection threshold based on the input frequency and sampling frequency
assign threshold = ((2 * TWOPI * f0) / fs) * (2 ** 31);

// Implement the tone detection and generation block
always @(posedge clk) begin
  accumulator <= accumulator + in;
  phase_accumulator <= phase_accumulator + ((2 * TWOPI * f0) / fs) * (2 ** 31);

  if (phase_accumulator >= (2 ** 32)) begin
    phase_accumulator <= phase_accumulator - (2 ** 32);
  end

  if (accumulator >= threshold) begin
    tone_detected <= 1;
  end else begin
    tone_detected <= 0;
  end

  if (tone_detected) begin
    out <= sin(phase_accumulator[31:0]);
  end else begin
    out <= 0;
  end
end

endmodule

