    dividend_reg = DIVIDEND;
    divisor_reg = DIVISOR;
    count = 8;
    quotient_reg = 0;
    remainder_reg = 0;

    while(count != 0) begin
        remainder_reg = remainder_reg << 1;
        remainder_reg[0] = dividend_reg[7];
        dividend_reg = dividend_reg << 1;
        remainder_reg = remainder_reg - divisor_reg;
        if(remainder_reg[7] == 0) begin
            quotient_reg = quotient_reg << 1;
            quotient_reg[0] = 1;
        end else begin
            remainder_reg = remainder_reg + divisor_reg;
            quotient_reg = quotient_reg << 1;
            quotient_reg[0] = 0;
        end
        count = count - 1;
    end

    QUOTIENT = quotient_reg;
    REMAINDER = remainder_reg;
end

