module dqsenable (
    input dqsin,
    input dqsenable,
    input devclrn,
    input devpor,
    output reg dqsbusout
);

// Buffer dqsin to dqsbusout
assign dqsbusout = dqsin;

// Buffer dqsenable to dqsbusout, but only when it is asserted
assign dqsbusout = (dqsenable == 1'b1) ? 1'b1 : dqsbusout;

// Tri-state buffers for devclrn and devpor
assign dqsbusout = (devclrn == 1'b0) ? 1'bz : dqsbusout;
assign dqsbusout = (devpor == 1'b0) ? 1'bz : dqsbusout;

// PMOS transistor to drive dqsbusout when dqsenable is asserted and dqsin is valid
always @(posedge dqsin, posedge dqsenable) begin
    if (dqsenable == 1'b1 && dqsin == 1'b1) begin
        dqsbusout <= 1'b1;
    end else begin
        dqsbusout <= 1'bz;
    end
end

endmodule

