module spiMaster (
  input clk_i,
  input rst_i,
  input [2:0] address_i,
  input [17:0] data_i,
  output [17:0] data_o,
  input select,
  input we_i,
  input spiSysClk,
  output spiClkOut,
  input spiDataIn,
  output spiDataOut,
  output spiCS_n,
  inout [17:0] do_peri,
  inout [17:0] di_peri,
  inout [31:0] addr_peri,
  input mem_clk,
  output mem_access,
  output store_access,
  input [31:0] addr_high
);

  // Declare internal signals and registers
  reg [17:0] spi_data_out_reg;
  reg [7:0] spi_bit_count;
  reg spi_clk_out_reg;
  reg spi_cs_n_reg;
  reg [7:0] spi_dummy_count;
  reg spi_dummy_enable;
  reg spi_transfer_enable;
  reg spi_read_enable;
  reg spi_write_enable;
  reg spi_data_in_reg;
  wire spi_data_in;
  reg [7:0] spi_data_in_count;
  reg spi_data_in_enable;
  reg [7:0] spi_data_out_count;
  reg spi_data_out_enable;
  reg [2:0] spi_state;
  reg [7:0] spi_address_count;
  reg spi_address_enable;
  reg [31:0] spi_address_reg;

  // Define constants
  localparam SPI_STATE_IDLE = 3'b000;
  localparam SPI_STATE_ADDRESS = 3'b001;
  localparam SPI_STATE_READ = 3'b010;
  localparam SPI_STATE_WRITE = 3'b011;
  localparam SPI_STATE_DUMMY = 3'b110;
  localparam SPI_STATE_DONE = 3'b111;
  localparam SPI_BIT_COUNT_MAX = 8'h7;
  localparam SPI_DUMMY_COUNT_MAX = 8'h7;
  localparam SPI_DATA_IN_COUNT_MAX = 8'h7;
  localparam SPI_DATA_OUT_COUNT_MAX = 8'h7;
  localparam SPI_ADDRESS_COUNT_MAX = 32'hFFFF;

  // Assign internal signals and registers
  assign spiDataIn = spi_data_in_reg;
  assign spiClkOut = spi_clk_out_reg;
  assign spiCS_n = spi_cs_n_reg;
  assign data_o = spi_data_out_reg;

  // Initialize internal signals and registers
  initial begin
    spi_data_out_reg <= 18'b0;
    spi_bit_count <= 8'h0;
    spi_clk_out_reg <= 1'b1;
    spi_cs_n_reg <= 1'b1;
    spi_dummy_count <= 8'h0;
    spi_dummy_enable <= 1'b0;
    spi_transfer_enable <= 1'b0;
    spi_read_enable <= 1'b0;
    spi_write_enable <= 1'b0;
    spi_data_in_reg <= 1'b0;
    spi_data_in_count <= 8'h0;
    spi_data_in_enable <= 1'b0;
    spi_data_out_count <= 8'h0;
    spi_data_out_enable <= 1'b0;
    spi_state <= SPI_STATE_IDLE;
    spi_address_count <= 32'h0;
    spi_address_enable <= 1'b0;
    spi_address_reg <= 32'h0;
  end

  // Handle state transitions
  always @(posedge spiSysClk) begin
    // Reset state machine on reset
    if (rst_i) begin
      spi_state <= SPI_STATE_IDLE;
      spi_bit_count <= 8'h0;
      spi_clk_out_reg <= 1'b1;
      spi_cs_n_reg <= 1'b1;
      spi_dummy_count <= 8'h0;
      spi_dummy_enable <= 1'b0;
      spi_transfer_enable <= 1'b0;
      spi_read_enable <= 1'b0;
      spi_write_enable <= 1'b0;
      spi_data_in_reg <= 1'b0;
      spi_data_in_count <= 8'h0;
      spi_data_in_enable <= 1'b0;
      spi_data_out_count <= 8'h0;
      spi_data_out_enable <= 1'b0;
      spi_address_count <= 32'h0;
      spi_address_enable <= 1'b0;
      spi_address_reg <= 32'h0;
    end else begin
      case (spi_state)
        // Idle state
        SPI_STATE_IDLE: begin
          if (select == address_i) begin
            spi_state <= SPI_STATE_ADDRESS;
            spi_address_count <= 32'h0;
            spi_address_enable <= 1'b1;
            spi_cs_n_reg <= 1'b0;
          end
        end

        // Address state
        SPI_STATE_ADDRESS: begin
          if (spi_address_enable) begin
            spi_address_reg <= spi_address_reg << 1;
            spi_address_reg[0] <= spiDataIn;
            spi_address_count <= spi_address_count + 1;
            if (spi_address_count == SPI_ADDRESS_COUNT_MAX) begin
              spi_address_enable <= 1'b0;
              spi_state <= spi_read_enable ? SPI_STATE_READ : spi_write_enable ? SPI_STATE_WRITE : SPI_STATE_DUMMY;
              spi_bit_count <= 8'h0;
              spi_dummy_count <= 8'h0;
              spi_data_in_count <= 8'h0;
              spi_data_out_count <= 8'h0;
            end
          end
        end

        // Read state
        SPI_STATE_READ: begin
          if (spi_transfer_enable) begin
            spi_data_out_reg <= sd_dat_out;
            spi_data_out_count <= spi_data_out_count + 1;
            if (spi_data_out_count == SPI_DATA_OUT_COUNT_MAX) begin
              spi_transfer_enable <= 1'b0;
              spi_state <= SPI_STATE_DONE;
            end
          end
        end

        // Write state
        SPI_STATE_WRITE: begin
          if (spi_transfer_enable) begin
            spi_data_in_reg <= spiDataIn;
            spi_data_in_count <= spi_data_in_count + 1;
            if (spi_data_in_count == SPI_DATA_IN_COUNT_MAX) begin
              spi_transfer_enable <= 1'b0;
              spi_state <= SPI_STATE_DONE;
            end
          end
        end

        // Dummy state
        SPI_STATE_DUMMY: begin
          if (spi_dummy_enable) begin
            spi_dummy_count <= spi_dummy_count + 1;
            if (spi_dummy_count == SPI_DUMMY_COUNT_MAX) begin
              spi_dummy_enable <= 1'b0;
              spi_state <= spi_read_enable ? SPI_STATE_READ : spi_write_enable ? SPI_STATE_WRITE : SPI_STATE_DUMMY;
              spi_bit_count <= 8'h0;
              spi_dummy_count <= 8'h0;
              spi_data_in_count <= 8'h0;
              spi_data_out_count <= 8'h0;
            end
          end
        end

        // Done state
        SPI_STATE_DONE: begin
          spi_cs_n_reg <= 1'b1;
          spi_state <= SPI_STATE_IDLE;
        end
      endcase
    end
  end

  // Handle clock generation
  always @(posedge spiSysClk) begin
    if (spi_state == SPI_STATE_IDLE || spi_state == SPI_STATE_DONE) begin
      spi_clk_out_reg <= 1'b1;
    end else begin
      spi_bit_count <= spi_bit_count + 1;
      if (spi_bit_count == SPI_BIT_COUNT_MAX) begin
        spi_bit_count <= 8'h0;
        spi_clk_out_reg <= ~spi_clk_out_reg;
        spi_dummy_enable <= spi_state == SPI_STATE_DUMMY;
        spi_transfer_enable <= spi_state == SPI_STATE_READ || spi_state == SPI_STATE_WRITE;
        spi_read_enable <= we_i == 1'b0;
        spi_write_enable <= we_i == 1'b1;
        spi_data_in_enable <= spi_state == SPI_STATE_WRITE;
        spi_data_out_enable <= spi_state == SPI_STATE_READ;
      end
    end
  end

endmodule

module user_io( 
	   input      SPI_CLK,
	   input      SPI_SS_IO,
	   output     reg SPI_MISO,
	   input      SPI_MOSI,
	   input [7:0] CORE_TYPE,

		output [5:0] JOY0,
		output [5:0] JOY1,

		output [2:0] MOUSE_BUTTONS,
		output       KBD_MOUSE_STROBE,
		output [1:0] KBD_MOUSE_TYPE,
		output [7:0] KBD_MOUSE_DATA,

		output [1:0] BUTTONS,
		output [1:0] SWITCHES
	   );

   reg [6:0]         sbuf;
   reg [7:0]         cmd;
   reg [5:0] 	      cnt;
   reg [5:0]         joystick0;
   reg [5:0]         joystick1;
   reg [3:0] 	      but_sw;

	reg               kbd_mouse_strobe;
   reg [1:0]         kbd_mouse_type;
   reg [7:0]         kbd_mouse_data;
   reg [2:0]         mouse_buttons;

	assign JOY0 = joystick0;
	assign JOY1 = joystick1;

	assign KBD_MOUSE_DATA = kbd_mouse_data;
	assign KBD_MOUSE_TYPE = kbd_mouse_type;
	assign KBD_MOUSE_STROBE = kbd_mouse_strobe;
	assign MOUSE_BUTTONS = mouse_buttons;

	assign BUTTONS = but_sw[1:0];
	assign SWITCHES = but_sw[3:2];

   always@(negedge SPI_CLK) begin
      if(cnt < 8)
		  SPI_MISO <= CORE_TYPE[7-cnt];
	end

   always@(posedge SPI_CLK) begin
		if(SPI_SS_IO == 1) begin
        cnt <= 0;
		end else begin
			sbuf[6:1] <= sbuf[5:0];
			sbuf[0] <= SPI_MOSI;

			cnt <= cnt + 1;

	      if(cnt == 7) begin
			   cmd[7:1] <= sbuf; 
				cmd[0] <= SPI_MOSI;
		   end	

	      if(cnt == 8) begin
				if(cmd == 4)
				  kbd_mouse_type <= 2'b00;
				else if(cmd == 5)
				  kbd_mouse_type <= 2'b10;
		 		else if(cmd == 6)
				  kbd_mouse_type <= 2'b11;
		   end

			kbd_mouse_strobe <= 0;

	      if(cnt == 15) begin
			   if(cmd == 1) begin
					 but_sw[3:1] <= sbuf[2:0]; 
					 but_sw[0] <= SPI_MOSI; 
				end
			   if(cmd == 2) begin
					 joystick0[5:1] <= sbuf[4:0]; 
					 joystick0[0] <= SPI_MOSI; 
				end
			   if(cmd == 3) begin
					 joystick1[5:1] <= sbuf[4:0]; 
					 joystick1[0] <= SPI_MOSI; 
			   end
			   if((cmd == 4)||(cmd == 5)||(cmd == 6)) begin
					 kbd_mouse_data[7:1] <= sbuf[6:0]; 
					 kbd_mouse_data[0] <= SPI_MOSI; 
					 kbd_mouse_strobe <= 1;		
				end
			end	

			if(cmd == 4) begin

				if(cnt == 23) begin
					 kbd_mouse_data[7:1] <= sbuf[6:0]; 
					 kbd_mouse_data[0] <= SPI_MOSI; 
					 kbd_mouse_strobe <= 1;		
					 kbd_mouse_type <= 2'b01;
				end

				if(cnt == 31) begin
					 mouse_buttons[2:1] <= sbuf[1:0]; 
					 mouse_buttons[0] <= SPI_MOSI; 
				end
			end
		end
	end

endmodule

