module axi_protocol_converter (
  input aclk,
  input m_valid_i_reg,
  input [51:0] m_payload_i_reg,
  input [11:0] m_axi_awaddr,
  input sel_first_i,
  input wrap_next_pending,
  input incr_next_pending,
  input [3:0] axaddr_incr_reg,
  input [3:0] axaddr_offset_r_reg,
  input [3:0] wrap_second_len_r_reg,
  input [1:0] state_reg,
  output next,
  output reg m_valid_i_reg,
  output reg [51:0] m_payload_i_reg,
  output reg [11:0] m_axi_awaddr,
  output reg sel_first_reg,
  output reg wrap_next_pending,
  output reg next_pending_r_reg,
  output reg [3:0] axaddr_incr_reg,
  output reg [3:0] axaddr_offset_r_reg,
  output reg [3:0] wrap_second_len_r_reg,
  output reg [1:0] state_reg
);

  // Define internal signals
  reg [3:0] pending_state;
  reg [3:0] next_state;
  reg [3:0] axaddr_incr_next;
  reg [3:0] axaddr_offset_next;
  reg [3:0] wrap_second_len_next;
  reg wrap_pending_next;

  // Define constants
  localparam IDLE = 2'b00;
  localparam WRAP_PENDING = 2'b01;
  localparam WRAP_SECOND = 2'b10;
  localparam INCR_PENDING = 2'b11;

  // Define state machine
  always @ (posedge aclk) begin
    case (state_reg)
      IDLE: begin
        // Check if input data is valid
        if (m_valid_i_reg) begin
          // Set output data and control signals
          m_payload_i_reg <= m_payload_i_reg;
          m_axi_awaddr <= m_axi_awaddr;
          sel_first_reg <= sel_first_i;
          m_valid_i_reg <= 1'b1;
          next_pending_r_reg <= wrap_next_pending ? 1'b1 : 1'b0;
          wrap_next_pending <= 1'b0;
          axaddr_offset_r_reg <= axaddr_offset_r_reg;
          axaddr_incr_reg <= axaddr_incr_reg;
          wrap_second_len_r_reg <= wrap_second_len_r_reg;
          // Transition to next state
          if (sel_first_i) begin
            state_reg <= IDLE;
            next <= 1'b1;
          end else if (wrap_next_pending) begin
            state_reg <= WRAP_PENDING;
          end else if (incr_next_pending) begin
            state_reg <= INCR_PENDING;
          end else begin
            state_reg <= IDLE;
          end
        end else begin
          // Set output data and control signals
          m_valid_i_reg <= 1'b0;
          next_pending_r_reg <= wrap_next_pending ? 1'b1 : 1'b0;
          wrap_next_pending <= 1'b0;
          // Stay in current state
          state_reg <= IDLE;
          next <= 1'b1;
        end
      end
      WRAP_PENDING: begin
        // Set output data and control signals
        m_payload_i_reg <= m_payload_i_reg;
        m_axi_awaddr <= m_axi_awaddr;
        sel_first_reg <= sel_first_i;
        m_valid_i_reg <= 1'b1;
        next_pending_r_reg <= 1'b1;
        wrap_next_pending <= 1'b0;
        axaddr_offset_r_reg <= axaddr_offset_r_reg;
        axaddr_incr_reg <= axaddr_incr_reg;
        wrap_second_len_r_reg <= wrap_second_len_r_reg;
        // Transition to next state
        if (sel_first_i) begin
          state_reg <= IDLE;
          next <= 1'b1;
        end else begin
          state_reg <= WRAP_SECOND;
        end
      end
      WRAP_SECOND: begin
        // Set output data and control signals
        m_payload_i_reg <= m_payload_i_reg;
        m_axi_awaddr <= m_axi_awaddr;
        sel_first_reg <= sel_first_i;
        m_valid_i_reg <= 1'b1;
        next_pending_r_reg <= 1'b0;
        wrap_next_pending <= 1'b0;
        axaddr_offset_r_reg <= axaddr_offset_r_reg;
        axaddr_incr_reg <= axaddr_incr_reg;
        wrap_second_len_r_reg <= wrap_second_len_r_reg;
        // Transition to next state
        state_reg <= IDLE;
        next <= 1'b1;
      end
      INCR_PENDING: begin
        // Set output data and control signals
        m_payload_i_reg <= m_payload_i_reg;
        m_axi_awaddr <= m_axi_awaddr;
        sel_first_reg <= sel_first_i;
        m_valid_i_reg <= 1'b1;
        next_pending_r_reg <= 1'b1;
        wrap_next_pending <= 1'b0;
        axaddr_offset_r_reg <= axaddr_offset_next;
        axaddr_incr_reg <= axaddr_incr_next;
        wrap_second_len_r_reg <= wrap_second_len_next;
        // Transition to next state
        state_reg <= IDLE;
        next <= 1'b1;
      end
      default: begin
        // Stay in current state
        state_reg <= state_reg;
        next <= 1'b0;
      end
    endcase
  end

  // Define increment logic
  always @ (posedge aclk) begin
    // Check if increment transaction is pending
    if (incr_next_pending) begin
      // Update internal signals
      axaddr_offset_next <= axaddr_offset_r_reg + axaddr_incr_reg;
      axaddr_incr_next <= axaddr_incr_reg;
      wrap_second_len_next <= wrap_second_len_r_reg;
      // Clear pending transaction
      incr_next_pending <= 1'b0;
    end
  end

  // Define wrap logic
  always @ (posedge aclk) begin
    // Check if wrap transaction is pending
    if (wrap_pending_next) begin
      // Update internal signals
      axaddr_offset_next <= 4'd0;
      axaddr_incr_next <= axaddr_incr_reg;
      wrap_second_len_next <= wrap_second_len_r_reg;
      // Clear pending transaction
      wrap_pending_next <= 1'b0;
    end
  end

  // Define wrap trigger logic
  always @ (posedge aclk) begin
    // Check if wrap transaction is triggered
    if (wrap_next_pending && state_reg == IDLE) begin
      // Set internal signal
      wrap_pending_next <= 1'b1;
    end
  end

endmodule

