module vending_machine (
  input clk,
  input reset,
  input coin,
  output reg dispense,
  output reg change,
  output reg product
);

  parameter S0 = 2'b00, S1 = 2'b01, S2 = 2'b10, S3 = 2'b11;
  reg [1:0] state, next_state;
  reg [3:0] count;
  reg [3:0] change_count;

  // State transitions
  always @(posedge clk) begin
    if (reset) begin
      state <= S0;
      count <= 0;
      change_count <= 0;
    end
    else begin
      state <= next_state;
      count <= count + coin;
      change_count <= count - 50;
    end
  end

  // State machine logic
  always @(*) begin
    case (state)
      S0: begin
        dispense = 0;
        change = 0;
        product = 0;
        if (count == 25) begin
          next_state = S1;
        end
        else if (count == 10) begin
          next_state = S2;
        end
        else if (count == 5) begin
          next_state = S3;
        end
        else begin
          next_state = S0;
        end
      end
      S1: begin
        dispense = 0;
        change = 0;
        product = 0;
        if (count == 50) begin
          next_state = S0;
          dispense = 1;
          product = 1;
        end
        else if (count > 50) begin
          next_state = S0;
          dispense = 1;
          change = 1;
          count = count - 50;
          change_count = count;
        end
        else begin
          next_state = S1;
        end
      end
      S2: begin
        dispense = 0;
        change = 0;
        product = 0;
        if (count == 50) begin
          next_state = S0;
          dispense = 1;
          product = 1;
        end
        else if (count > 50) begin
          next_state = S0;
          dispense = 1;
          change = 1;
          count = count - 50;
          change_count = count;
        end
        else begin
          next_state = S2;
        end
      end
      S3: begin
        dispense = 0;
        change = 0;
        product = 0;
        if (count == 50) begin
          next_state = S0;
          dispense = 1;
          product = 1;
        end
        else if (count > 50) begin
          next_state = S0;
          dispense = 1;
          change = 1;
          count = count - 50;
          change_count = count;
        end
        else begin
          next_state = S3;
        end
      end
      default: begin
        next_state = S0;
      end
    endcase
  end

endmodule

