        .wrreq(in_inputctrl_pkt),
        .q(out_inputctrl_pkt_q),
        .usedw(out_inputctrl_pkt_usedw)
    );

    // State machine
    reg [1:0] current_state;
    parameter idle_s = 2'b00;
    parameter send_data_s = 2'b01;
    parameter discard_s = 2'b10;

    always @(posedge clk) begin
        if (reset) begin
            current_state <= idle_s;
            out_inputctrl_pkt_rd <= 1'b0;
            out_inputctrl_valid_rd <= 1'b0;
            out_offset_pkt_wr <= 1'b0;
            out_offset_valid_wr <= 1'b0;
            out_offset_valid <= 1'b0;
        end
        else begin
            case (current_state)
                idle_s:begin
                    out_inputctrl_valid_rd <= 1'b1;
                    if (!in_inputctrl_valid_empty && !out_inputctrl_valid_empty) begin
                        current_state <= send_data_s;
                    end
                end
                send_data_s:begin
                    out_inputctrl_valid_rd <= 1'b0;
                    out_offset_pkt_wr <= 1'b1;
                    out_offset_pkt <= out_inputctrl_pkt_q;
                    out_offset_valid_wr <= 1'b1;
                    out_offset_valid <= 1'b1;
                    if (in_inputctrl_pkt_q[133:132] == 2'b10) begin
                        out_inputctrl_pkt_rd <= 1'b0;
                        current_state <= idle_s;
                    end
                    else begin
                        out_inputctrl_pkt_rd <= 1'b1;
                        current_state <= send_data_s;
                    end
                end
                discard_s:begin
                    out_inputctrl_valid_rd <= 1'b0;
                    if (in_inputctrl_pkt_q[133:132] == 2'b10) begin
                        out_inputctrl_pkt_rd <= 1'b0;
                        current_state <= idle_s;
                    end
                    else begin
                        out_inputctrl_pkt_rd <= 1'b1;
                        current_state <= discard_s;
                    end
                end
                default:;
            endcase
        end
    end

