module int_to_fp (
    clk_en,
    clock,
    dataa,
    result);

    input   clk_en;
    input   clock;
    input   [31:0]  dataa;
    output  [63:0]  result;

    wire [31:0] sign;
    wire [31:0] exponent;
    wire [52:0] mantissa;

    // Extract sign bit
    assign sign = dataa[31];

    // Extract exponent
    assign exponent = dataa[30:23];

    // Convert exponent from bias 127 to bias 1023
    assign exponent = exponent + 1023 - 127;

    // Extract mantissa
    assign mantissa = {1'b1, dataa[22:0]};

    // Convert mantissa from integer to binary fraction format
    assign mantissa = mantissa / (1 << 23);

    // Combine sign bit, exponent, and mantissa to form floating-point number
    assign result = {sign, exponent, mantissa};

endmodule

