module GlitchFreeClockMux (
  input [n-1:0] clk,
  input [n-1:0] sel,
  output out
);

parameter n = 4; // number of clock signals
parameter num_ff = 2; // number of flip-flops to be used

reg [n-1:0] synced_clk;
reg [num_ff-1:0] ff_out;
reg [num_ff-1:0] ff_in;

always @(posedge clk[0] or posedge clk[1] or posedge clk[2] or posedge clk[3])
begin
  // Synchronize all clock signals to the first clock signal
  synced_clk[0] <= clk[0];
  synced_clk[1] <= clk[0];
  synced_clk[2] <= clk[0];
  synced_clk[3] <= clk[0];

  // Select the appropriate clock signal based on the select signals
  case(sel)
    4'b0001: synced_clk <= {clk[0], synced_clk[1:2]};
    4'b0010: synced_clk <= {synced_clk[0], clk[1], synced_clk[2]};
    4'b0100: synced_clk <= {synced_clk[0:1], clk[2], synced_clk[3]};
    4'b1000: synced_clk <= {synced_clk[0:2], clk[3]};
    default: synced_clk <= synced_clk; // No change if select signals are invalid
  endcase
end

always @(posedge synced_clk)
begin
  // Use flip-flops to ensure glitch-free operation
  ff_in <= synced_clk;
  for (i = 0; i < num_ff; i = i + 1)
  begin
    ff_out[i] <= ff_in[i];
    ff_in[i] <= ff_out[i];
  end
  out <= ff_out[num_ff-1];
end

endmodule

