module shift_register(
    input clk,
    input areset,
    input load,
    input ena,
    input [3:0] in_data,
    output [3:0] q,
    output [3:0] q_next
);
    reg [3:0] q_reg;
    wire [3:0] in_data_dly;

    assign in_data_dly[0] = in_data[0];
    assign in_data_dly[1] = q_reg[0];
    assign in_data_dly[2] = q_reg[1];
    assign in_data_dly[3] = q_reg[2];

    always @(posedge clk or negedge areset) begin
        if(!areset) begin
            q_reg <= 4'b0;
        end
        else begin
            if(load) begin
                q_reg <= in_data;
            end
            else if(ena) begin
                q_reg <= in_data_dly;
            end
        end
    end

    assign q = q_reg;
    assign q_next = in_data_dly;
endmodule
