module full_adder (
  input a,
  input b,
  input cin,
  output sum,
  output cout
);

  wire ha1_sum, ha1_carry, ha2_carry;

  // First half adder
  half_adder ha1 (
    .a(a),
    .b(b),
    .sum(ha1_sum),
    .carry(ha1_carry)
  );

  // Second half adder
  half_adder ha2 (
    .a(ha1_sum),
    .b(cin),
    .sum(sum),
    .carry(ha2_carry)
  );

  // Carry out is the OR of the two half adder carries
  assign cout = ha1_carry | ha2_carry;

endmodule
module half_adder (
  input a,
  input b,
  output sum,
  output carry
);

  assign sum = a ^ b;
  assign carry = a & b;

endmodule

module mem (
    input clk,
    input reset,

    input [31:0] addr,
    input [3:0] mask,
    input enable,

    input cmd,
    input [31:0] write_data,
    output reg [31:0] load_data,
    output reg valid
);

    localparam MEMORY_SIZE = (1 << 14);

    reg [31:0] memory [MEMORY_SIZE - 1:0];

    wire [29:0] word_addr = addr[31:2];

    initial begin
        /* Loads by word addresses. Address 0x302c corresponds to 0x0c0b. */
        $readmemh("mem.hex", memory);
    end

    always @ (*) begin
        if (enable && cmd == 1'b0) begin
            load_data = memory[word_addr];
            valid = 1;
        end else begin
            load_data = 32'b0;
            valid = 0;
        end
    end

    wire [31:0] expanded_mask = {mask[3] ? 8'hFF : 8'h00,
                                 mask[2] ? 8'hFF : 8'h00,
                                 mask[1] ? 8'hFF : 8'h00,
                                 mask[0] ? 8'hFF : 8'h00};

    wire [31:0] to_be_written = (memory[word_addr] & ~expanded_mask) | (write_data & expanded_mask);

    always @ (*) begin
        if (enable && cmd == 1'b1) begin
            memory[word_addr] = to_be_written;
        end
    end

endmodule

module fp_arithmetic (
  input [31:0] num1,
  input [31:0] num2,
  input [1:0] op,
  output [31:0] result
);

  // Define constants for IEEE 754 single precision format
  parameter EXPONENT_WIDTH = 8;
  parameter MANTISSA_WIDTH = 23;
  parameter BIAS = 127;

  // Define variables for input numbers in IEEE 754 format
  reg [31:0] num1_sign;
  reg [7:0] num1_exponent;
  reg [22:0] num1_mantissa;
  reg [31:0] num2_sign;
  reg [7:0] num2_exponent;
  reg [22:0] num2_mantissa;

  // Define variables for output number in IEEE 754 format
  wire [31:0] result_sign;
  wire [7:0] result_exponent;
  wire [22:0] result_mantissa;

  // Convert input numbers to IEEE 754 format
  assign num1_sign = num1[31];
  assign num1_exponent = num1[30:23] - BIAS;
  assign num1_mantissa = {1'b1, num1[22:0]};
  assign num2_sign = num2[31];
  assign num2_exponent = num2[30:23] - BIAS;
  assign num2_mantissa = {1'b1, num2[22:0]};

  // Perform arithmetic operation based on op parameter
  always @* begin
    case (op)
      2'b00: // Addition
        begin
          // Align exponents
          if (num1_exponent > num2_exponent) begin
            result_exponent = num1_exponent;
            num2_mantissa = {num2_mantissa, {(num1_exponent - num2_exponent){1'b0}}};
          end else begin
            result_exponent = num2_exponent;
            num1_mantissa = {num1_mantissa, {(num2_exponent - num1_exponent){1'b0}}};
          end
          // Perform addition
          if (num1_sign == num2_sign) begin
            result_sign = num1_sign;
            result_mantissa = num1_mantissa + num2_mantissa;
          end else begin
            if (num1_mantissa > num2_mantissa) begin
              result_sign = num1_sign;
              result_mantissa = num1_mantissa - num2_mantissa;
            end else begin
              result_sign = num2_sign;
              result_mantissa = num2_mantissa - num1_mantissa;
            end
          end
          // Normalize result
          if (result_mantissa[MANTISSA_WIDTH]) begin
            result_exponent = result_exponent + 1;
            result_mantissa = {result_mantissa[MANTISSA_WIDTH-1:0], 1'b0};
          end
        end
      2'b01: // Subtraction
        begin
          // Negate num2
          num2_sign = ~num2_sign;
          // Perform addition
          op = 2'b00;
          end
      2'b10: // Multiplication
        begin
          // Calculate new exponent
          result_exponent = num1_exponent + num2_exponent - BIAS;
          // Calculate new mantissa
          result_mantissa = num1_mantissa * num2_mantissa;
          // Normalize result
          if (result_mantissa[MANTISSA_WIDTH*2-1]) begin
            result_exponent = result_exponent + 1;
            result_mantissa = {result_mantissa[MANTISSA_WIDTH*2-2:MANTISSA_WIDTH], result_mantissa[MANTISSA_WIDTH-1:0]};
          end else begin
            result_mantissa = {result_mantissa[MANTISSA_WIDTH*2-2:MANTISSA_WIDTH], result_mantissa[MANTISSA_WIDTH-1:0]};
          end
          // Set sign
          result_sign = num1_sign ^ num2_sign;
        end
      2'b11: // Division
        begin
          // Calculate new exponent
          result_exponent = num1_exponent - num2_exponent + BIAS;
          // Calculate new mantissa
          result_mantissa = num1_mantissa / num2_mantissa;
          // Normalize result
          if (result_mantissa[MANTISSA_WIDTH-1]) begin
            result_exponent = result_exponent + 1;
            result_mantissa = {result_mantissa[MANTISSA_WIDTH-2:0], 1'b0};
          end
          // Set sign
          result_sign = num1_sign ^ num2_sign;
        end
    endcase
  end

  // Convert output number to binary format
  assign result = {result_sign, result_exponent + BIAS, result_mantissa[21:0]};

endmodule

module fault_detection (
    input clk_i,
    input rst_i,
    output reg fault_o,
    output reg break_o
);

    reg [31:0] cycle_count;

    // reset the module and cycle count when rst_i is high
    always @(posedge rst_i)
    begin
        if (rst_i)
        begin
            cycle_count <= 0;
            fault_o <= 0;
            break_o <= 0;
        end
    end

    // increment cycle count and check for fault or break conditions
    always @(posedge clk_i)
    begin
        cycle_count <= cycle_count + 1;

        if (fault_o)
        begin
            $display("Fault detected");
            $finish;
        end
        else if (break_o)
        begin
            $display("Completed after %2d cycles", cycle_count);
            $finish;
        end
    end

    // generate fault and break signals
    always @(cycle_count)
    begin
        if (cycle_count == 100)
        begin
            fault_o <= 1;
        end
        else if (cycle_count == 200)
        begin
            break_o <= 1;
        end
    end

endmodule

