module top_ALU(
    input [31:0] a,    // First input
    input [31:0] b,    // Second input
    input [2:0] select,    // 3-bit select input for operation type
    input enable,    // Input to enable or disable the output
    output reg [31:0] out    // 32-bit output
);

    wire [15:0] a_low, b_low, out_low;
    wire [15:0] a_high, b_high, out_high;

    // Split the inputs into two 16-bit parts
    assign a_low = a[15:0];
    assign b_low = b[15:0];
    assign a_high = a[31:16];
    assign b_high = b[31:16];

    // Create two adder-subtractor modules for the two 16-bit parts
    adder_subtractor addsub_low(
        .a(a_low),
        .b(b_low),
        .select(select[0]),
        .out(out_low)
    );

    adder_subtractor addsub_high(
        .a(a_high),
        .b(b_high),
        .select(select[0]),
        .out(out_high)
    );

    // Combine the two 16-bit results into a 32-bit result
    always @(*) begin
        case (select)
            3'b000: out = a & b;    // Bitwise AND
            3'b001: out = a | b;    // Bitwise OR
            3'b010: out = a ^ b;    // Bitwise XOR
            3'b011: out = out_high + out_low;    // Addition
            3'b100: out = out_high - out_low;    // Subtraction
            3'b101: out = ~a;    // Bitwise NOT for first input
            3'b110: out = ~b;    // Bitwise NOT for second input
            3'b111: out = 0;    // Clear output
            default: out = 0;    // Default case
        endcase
    end

    // Enable or disable the output based on the enable input
    assign out = enable ? out : 32'b0;

endmodule

// Adder-subtractor module
module adder_subtractor(
    input [15:0] a,    // First input
    input [15:0] b,    // Second input
    input select,    // Select input for add or subtract
    output reg [15:0] out    // Output
);

    always @(*) begin
        if (select) begin
            out = a - b;    // Subtraction
        end else begin
            out = a + b;    // Addition
        end
    end

endmodule

module top_module (
    input clk,
    input reset,   // Synchronous active-high reset
    input [7:0] d, // 8-bit input for the shift register
    output [3:1] ena, // 3-bit output to enable each digit of the binary counter
    output reg [11:0] q // 12-bit output from the functional module
);

    // Instantiate the shift register module
    reg [7:0] shift_reg_out;
    shift_register shift_reg (
        .clk(clk),
        .reset(reset),
        .d(d),
        .q(shift_reg_out)
    );

    // Instantiate the binary counter module
    wire [3:1] counter_ena;
    wire [3:0] counter_out;
    binary_counter counter (
        .clk(clk),
        .reset(reset),
        .ena(counter_ena),
        .q(counter_out)
    );

    // Instantiate the functional module
    functional_module func (
        .shift_reg_out(shift_reg_out),
        .counter_out(counter_out),
        .q(q)
    );

    // Assign the counter enable signals to the output
    assign ena = counter_ena;

endmodule

// Shift register module
module shift_register (
    input clk,
    input reset,
    input [7:0] d,
    output reg [7:0] q
);
    always @(posedge clk, negedge reset) begin
        if (reset == 1'b0) begin
            q <= 8'b0;
        end else begin
            q <= {q[6:0], d[0]};
        end
    end
endmodule

// Binary counter module
module binary_counter (
    input clk,
    input reset,
    input [3:1] ena,
    output reg [3:0] q
);
    always @(posedge clk, negedge reset) begin
        if (reset == 1'b0) begin
            q <= 4'b0;
        end else begin
            if (ena[1] == 1'b1) begin
                q[0] <= ~q[0];
            end
            if (ena[2] == 1'b1) begin
                q[1] <= q[0] & ~q[1];
            end
            if (ena[3] == 1'b1) begin
                q[2] <= q[1] & ~q[2];
            end
            if (ena[3] == 1'b1) begin
                q[3] <= q[2] & ~q[3];
            end
        end
    end
endmodule

// Functional module
module functional_module (
    input [7:0] shift_reg_out,
    input [3:0] counter_out,
    output reg [11:0] q
);
    always @(*) begin
        q = {shift_reg_out, counter_out};
    end
endmodule

module johnson_counter (
    input clk,
    input reset,
    input select,
    output [3:0] q);

    reg [3:0] q_reg;
    reg [2:0] johnson_reg;
    wire [3:0] johnson_out;
    wire enable;

    assign johnson_out = {johnson_reg[2], johnson_reg[1], johnson_reg[0], johnson_reg[1]};
    assign enable = (select == 1'b1);

    always @(posedge clk, posedge reset) begin
        if (reset) begin
            q_reg <= 4'b0;
            johnson_reg <= 3'b0;
        end else begin
            if (enable) begin
                johnson_reg <= johnson_out;
                if (johnson_reg == 3'b111) begin
                    q_reg <= q_reg + 1;
                end
            end
        end
    end

    assign q = q_reg;

endmodule

module johnson_counter_with_pause (
    input clk,
    input reset,
    input select,
    input pause,
    output [3:0] q);

    wire [3:0] johnson_out;
    wire enable;
    wire [3:0] mux_out;

    johnson_counter jc (
        .clk(clk),
        .reset(reset),
        .select(select),
        .q(johnson_out)
    );

    assign enable = (select == 1'b1) && (pause == 1'b0);

    assign mux_out = {
        (enable) ? johnson_out : q[3],
        (enable) ? johnson_out : q[2],
        (enable) ? johnson_out : q[1],
        (enable) ? johnson_out : q[0]
    };

    always @(posedge clk, posedge reset) begin
        if (reset) begin
            q <= 4'b0;
        end else begin
            q <= mux_out;
        end
    end

endmodule

module register_file (
  input clk,
  input wr_en,
  input [log2n-1:0] wr_addr,
  input [m-1:0] wr_data,
  output reg [m-1:0] rd_data1,
  output reg [m-1:0] rd_data2
);

parameter n = 16; // number of registers
parameter m = 8; // number of bits per register

integer log2n = $clog2(n);

reg [m-1:0] regs [n-1:0];

// write operation
always @(posedge clk) begin
  if (wr_en) begin
    regs[wr_addr] <= wr_data;
  end
end

// read operation
assign rd_data1 = regs[0];
assign rd_data2 = regs[1];

endmodule

module my_module (
    Q,
    CLK,
    D,
    SCD,
    SCE,
    SET_B
);

    output Q;
    input CLK;
    input D;
    input SCD;
    input SCE;
    input SET_B;

    reg Q_reg;
    wire Q_next;
    reg SET_reg;
    reg SCE_reg;
    reg D_reg;
    reg SCD_reg;

    always @(posedge CLK) begin
        SET_reg <= SET_B;
        SCE_reg <= SCE;
        D_reg <= D;
        SCD_reg <= SCD;
        Q_reg <= Q_next;
    end

    assign Q = Q_reg;

    always @* begin
        if (SET_reg) begin
            Q_next = 1;
        end
        else if (!SCE_reg) begin
            Q_next = 0;
        end
        else if (D_reg != SCD_reg) begin
            Q_next = D_reg;
        end
        else begin
            Q_next = Q_reg;
        end
    end

endmodule

module vga_controller(
    input vclock,
    output reg [10:0] hcount,
    output reg [9:0] vcount,
    output reg vsync,
    output reg hsync,
    output reg blank
);

    // horizontal: 1056 pixels total
    // display 800 pixels per line
    reg hblank, hblankon;
    wire hsyncon, hsyncoff, hreset;
    assign hblankon = (hcount == 799);
    assign hsyncon = (hcount == 839);
    assign hsyncoff = (hcount == 967);
    assign hreset = (hcount == 1055);

    // vertical: 628 lines total
    // display 600 lines
    reg vblank, vblankon;
    wire vsyncon, vsyncoff, vreset;
    assign vblankon = hreset & (vcount == 599);
    assign vsyncon = hreset & (vcount == 600);
    assign vsyncoff = hreset & (vcount == 604);
    assign vreset = hreset & (vcount == 627);

    // sync and blanking
    wire next_hblank, next_vblank;
    assign next_hblank = hreset ? 0 : hblankon ? 1 : hblank;
    assign next_vblank = vreset ? 0 : vblankon ? 1 : vblank;
    always @(posedge vclock) begin
        hcount <= hreset ? 0 : hcount + 1;
        hblank <= next_hblank;
        hsync <= hsyncon ? 0 : hsyncoff ? 1 : hsync;  // active low

        vcount <= hreset ? (vreset ? 0 : vcount + 1) : vcount;
        vblank <= next_vblank;
        vsync <= vsyncon ? 0 : vsyncoff ? 1 : vsync;  // active low

        blank <= next_vblank | (next_hblank & ~hreset);
    end
endmodule

