    #10;
    we16 = 0;
    #10;
    en16 = 0;
    addr16 = 0;
    di16 = 0;

    // read back and verify the values
    for (i = 0; i < 2; i = i + 1) begin
      // read the 32-bit value back from the 32-bit port
      en32 = 1;
      addr32 = 32'h00123456;
      di32 = 0;
      #10;
      en32 = 0;
      #10;
      if (do32 !== 32'hdeadbeef) begin
        $display("Error: readback mismatch at address 0x00123456");
      end
      addr32 = 0;

      // read the 16-bit value back from the 16-bit port
      en16 = 1;
      addr16 = 11'h01234567;
      di16 = 0;
      #10;
      en16 = 0;
      #10;
      if (do16 !== 16'habcd) begin
        $display("Error: readback mismatch at address 0x01234567");
      end
      addr16 = 0;
    end

    // repeat the above operations with different values and addresses
    // ...

