module conflict_ff_param (
    input  wire        CLK,
    input  wire        RST,
    input  wire [ 8:0] A,
    input  wire [ 8:0] B,
    output wire [17:0] Z
);
    wire [8:0] ra;

    always @(posedge CLK or posedge RST) begin
        if (RST) 
            ra[8:4] <= A[8:4];
        else     
            ra[8:4] <= ra[8:4];
    end

    always @(posedge CLK) begin
        if (RST) 
            ra[3:0] <= A[3:0];
        else     
            ra[3:0] <= ra[3:0];
    end

    MULT9X9 # (
        .REGINPUTA("BYPASS"),
        .REGINPUTB("BYPASS"),
        .REGOUTPUT("BYPASS")
    ) mult (
        .A (ra),
        .B (B),
        .Z (Z)
    );

endmodule

