module control_logic (
    input select, // Select input to choose between adder and multiplier
    input [3:0] a, b, // Inputs to the adder/multiplier modules
    output reg [7:0] q // Output from functional module
);

    reg [3:0] adder_sum;
    reg [7:0] multiplier_product;

    adder adder_inst (
        .a(a),
        .b(b),
        .sum(adder_sum),
        .carry_out()
    );

    multiplier multiplier_inst (
        .a(a),
        .b(b),
        .product(multiplier_product)
    );

    functional_module functional_inst (
        .adder_sum(adder_sum),
        .multiplier_product(multiplier_product),
        .q(q)
    );

    always @(posedge clk) begin
        if (reset) begin
            adder_sum <= 4'b0;
            multiplier_product <= 8'b0;
            q <= 8'b0;
        end else begin
            if (select) begin
                q <= multiplier_product;
            end else begin
                q <= adder_sum & multiplier_product;
            end
        end
    end

endmodule

module top_module (
    input clk,
    input reset, // Synchronous active-high reset
    input [3:0] a, b, // Input for adder/multiplier modules
    input select, // Select input to choose between adder and multiplier
    output reg [7:0] q // Output from functional module
