        .sel(select),
        .in0(upper_byte),
        .in1(lower_byte),
        .out(out_hi)
    );

    assign out_lo = lower_byte;

    // Second module - Outputs input vector and individual bits
    wire [2:0] vec_out;
    wire [2:0] vec_in = vec;

    bit_extractor be0 (
        .in(vec_in),
        .out(o0)
    );

    bit_extractor be1 (
        .in(vec_in),
        .out(o1)
    );

    bit_extractor be2 (
        .in(vec_in),
        .out(o2)
    );

    assign vec_out = vec_in;

    // Functional module - Combines outputs of first and second modules
    wire [7:0] func_out;

    assign final_output = (select) ? vec_out : out_hi;

endmodule

