module pmos_transistor(D, G, S, B, l, w, I_d);

  parameter V_dd = 1.8;
  parameter V_in = 1.8;
  parameter V_ss = 0;
  parameter mu_n = 503.521;
  parameter C_ox = 41.8e-9;
  parameter V_th = -0.8;
  parameter lambda = 0.01;

  input D, G, S, B;
  input l, w;
  output I_d;

  wire V_gs, V_ds, I_ds, I_d_sat;

  assign V_gs = G - S;
  assign V_ds = D - S;

  assign I_ds = (V_gs > V_th) ? mu_n * C_ox * w / l * (V_gs - V_th)^2 * (1 + lambda * V_ds) : 0;
  assign I_d_sat = (V_ds > V_gs - V_th) ? I_ds : mu_n * C_ox * w / 2 * (V_gs - V_th)^2 * (1 + lambda * (V_ds - V_gs + V_th));

  assign I_d = (B == V_dd) ? -I_d_sat : I_d_sat;

endmodule

