module error_detector #(
   parameter TCQ           = 100,  
   parameter DWIDTH = 32
    )
    (
   input                            clk_i  ,        
   input                            rst_i ,
   input                            manual_clear_error,
   input                            data_error_i ,  
   input [DWIDTH-1:0]               cmp_data_i,     
   input [DWIDTH-1:0]               rd_data_i ,     
   input [31:0]                     cmp_addr_i ,    
   input [5:0]                      cmp_bl_i ,      
   input                            mcb_cmd_full_i ,
   input                            mcb_wr_full_i,  
   input                            mcb_rd_empty_i, 
   output reg [96 + (2*DWIDTH - 1):0] error_status,   
   output                           error                  
  );

reg data_error_r;
reg error_set;
assign  error = error_set;

always @ (posedge clk_i)
    data_error_r <= #TCQ  data_error_i;

always @ (posedge clk_i)
begin

if (rst_i || manual_clear_error) begin
   error_status <= #TCQ  'b0;
   error_set    <= #TCQ  1'b0;
end
else begin
  // latch the first error only
  if (data_error_i && ~data_error_r && ~error_set ) begin
     error_status[31:0]  <= #TCQ  cmp_addr_i;
     error_status[37:32] <= #TCQ  cmp_bl_i;
     error_status[40] <= #TCQ  mcb_cmd_full_i;
     error_status[41] <= #TCQ  mcb_wr_full_i;
     error_status[42] <= #TCQ  mcb_rd_empty_i;
     error_set <= #TCQ  1'b1;
     error_status[96 + (DWIDTH - 1)  :96]           <= #TCQ  cmp_data_i;
     error_status[96 + (2*DWIDTH - 1):96 + DWIDTH]  <= #TCQ  rd_data_i;

  end

  error_status[39:38]  <= #TCQ  'b0;    // reserved
  error_status[95:43] <= #TCQ  'b0;    // reserved


end end

endmodule

module PARALLEL_TO_SERIAL (
    input wire enable_pts, 
    input wire reset_pts, 
    input wire SD_CLK, 
    input wire [31:0] signal_in, 
    output reg signal_out, 
    output reg parallel_complete
    );

    //internal registers and wires
    reg [8:0] counter = 0;

    always @ ( posedge SD_CLK ) begin
        if (~reset_pts) begin
            signal_out <= 0;
            counter <= 0;
            parallel_complete <= 0;
        end else begin
            if (enable_pts == 1) begin
                if (counter == 32) begin
                    parallel_complete <= 1;
                    counter <= 0;
                end else begin
                    parallel_complete <= 0;
                    signal_out = signal_in[31 - counter];
                    counter <= counter + 1;
                end
            end else begin
                signal_out <= 0;
            end
        end
    end
