module data_transfer(
  input clk, rst,
  input [143:0] flit0c, flit1c, flitl0, flitl1,
  output reg [143:0] port0_co, port1_co, portl0_co, portl1_co,
  output reg ack0, ack1
);

  reg [143:0] port0_buffer, port1_buffer, portl0_buffer, portl1_buffer;
  reg [1:0] priority; // 00 = both empty, 01 = port 0, 10 = port 1, 11 = local 0

  always @(posedge clk) begin
    if (rst) begin
      port0_buffer <= 144'h0;
      port1_buffer <= 144'h0;
      portl0_buffer <= 144'h0;
      portl1_buffer <= 144'h0;
      priority <= 2'b00;
      ack0 <= 0;
      ack1 <= 0;
    end else begin
      // Check if port 0 has data
      if (flit0c != 144'h0 && priority < 2'b01) begin
        port0_buffer <= flit0c;
        ack0 <= 1;
        priority <= 2'b01;
      end
      // Check if port 1 has data
      else if (flit1c != 144'h0 && priority < 2'b10) begin
        port1_buffer <= flit1c;
        ack1 <= 1;
        priority <= 2'b10;
      end
      // Check if local port 0 has data
      else if (flitl0 != 144'h0 && priority < 2'b11) begin
        portl0_buffer <= flitl0;
        priority <= 2'b11;
      end
      // Check if local port 1 has data
      else if (flitl1 != 144'h0 && priority < 2'b11) begin
        portl1_buffer <= flitl1;
        priority <= 2'b11;
      end

      // Transfer data to output ports
      if (priority == 2'b01) begin
        port0_co <= port0_buffer;
        ack0 <= 0;
      end else if (priority == 2'b10) begin
        port1_co <= port1_buffer;
        ack1 <= 0;
      end else if (priority == 2'b11) begin
        portl0_co <= portl0_buffer;
        portl1_co <= portl1_buffer;
        priority <= 2'b00;
      end
    end
  end

endmodule

