module multiplier(
  input clk,
  input [N-1:0] a,
  input [N-1:0] b,
  input start,
  output reg done,
  output reg [2*N-1:0] p
);

parameter N = 8;
parameter SERIAL = 0;
parameter COUNTER_WIDTH = 4;

reg [N-1:0] a_reg;
reg [N-1:0] b_reg;
reg [2*N-1:0] p_reg;

reg [COUNTER_WIDTH-1:0] counter;

always @ (posedge clk) begin
  if (start) begin
    done <= 0;
    a_reg <= a;
    b_reg <= b;
    p_reg <= 0;
    counter <= 0;
  end else if (SERIAL) begin
    if (counter < N) begin
      if (b_reg[0] == 1'b1) begin
        p_reg <= p_reg + (a_reg << counter);
      end
      counter <= counter + 1;
      b_reg <= {b_reg[N-2:0], 1'b0};
    end else begin
      done <= 1;
      p <= p_reg;
    end
  end else begin
    if (counter < N) begin
      p_reg <= p_reg + ({a_reg[N-1], a_reg} & {b_reg[counter], {N{1'b0}}});
      counter <= counter + 1;
    end else begin
      done <= 1;
      p <= p_reg;
    end
  end
end

endmodule

