		   .twobits (twobits[15:8]),
		   .bitout (bitout[17:14]));

   sub
     i_sub4 [7:4] (.allbits (allbits),
		   .twobits (twobits[15:8]),
		   .bitout (short_bitout[27:24]));

   sub
     i_sub5 [7:0] (.allbits (allbits),
		   .twobits (twobits),
		   .bitout (bitout[17:10]));

   integer 	cyc=0;
   reg [63:0] 	crc;
   reg [63:0] 	sum;

   // Signals under test
   assign allbits = crc[7:0];
   assign twobits = crc[15:0];
   wire [63:0] result = {52'h0, short_bitout, bitout};

   // Test loop
   always @ (posedge clk) begin
      cyc <= cyc + 1;
      crc <= {crc[62:0], crc[63]^crc[2]^crc[0]};
      sum <= sum ^ result;
      if (cyc==0) begin
	 // Setup
	 crc <= 64'h5aef0c8d_d70a4497;
	 sum <= 64'h0;
      end
      else if (cyc<10) begin
	 sum <= 64'h0;
      end
      else if (cyc==99) begin
	 if (crc !== 64'hc77bb9b3784ea091) $stop;
	 // What checksum will we end up with (above print should match)
`define EXPECTED_SUM 64'h0bf9559ce1f98425
	 if (sum !== `EXPECTED_SUM) $stop;
	 $finish;
      end
   end

endmodule

module gcd (
  input clk,
  input reset,
  input req_val,
  input [31:0] req_msg,
  output req_rdy,
  input resp_rdy,
  output resp_val,
  output [31:0] resp_msg
);

  reg [31:0] a;
  reg [31:0] b;
  reg [31:0] rem;
  reg [31:0] gcd;
  reg [1:0] state;

  assign req_rdy = (state == 0) ? 1 : 0;

  always @(posedge clk) begin
    if (reset) begin
      state <= 0;
      req_rdy <= 0;
      resp_val <= 0;
      a <= 0;
      b <= 0;
      rem <= 0;
      gcd <= 0;
    end else begin
      case (state)
        0: begin // wait for request
          if (req_val) begin
            state <= 1;
            a <= req_msg;
          end
        end
        1: begin // wait for second number
          if (req_val) begin
            state <= 2;
            b <= req_msg;
          end
        end
        2: begin // compute GCD
          rem <= a % b;
          if (rem == 0) begin
            gcd <= b;
            state <= 3;
          end else begin
            a <= b;
            b <= rem;
          end
        end
        3: begin // output result
          if (resp_rdy) begin
            resp_val <= 1;
            resp_msg <= gcd;
            state <= 0;
          end
        end
      endcase
    end
  end

endmodule

