module addsub(
    input [3:0] A,
    input [3:0] B,
    input sel,
    output [3:0] sum,
    output [3:0] diff
);

    wire [3:0] negB;
    assign negB = (~B) + 1;

    assign sum = (sel == 1'b0) ? A + B : A - negB;
    assign diff = (sel == 1'b0) ? A - B : A + negB;

endmodule

