module ripple_carry_adder (
  input [n-1:0] A,
  input [n-1:0] B,
  input cin,
  output [n-1:0] S,
  output cout
);
  parameter n = 4; // number of bits

  wire [n:0] carry;
  genvar i;
  assign carry[0] = cin;

  generate
    for (i = 0; i < n; i = i + 1) begin : adder
      full_adder FA (
        .a(A[i]),
        .b(B[i]),
        .cin(carry[i]),
        .sum(S[i]),
        .cout(carry[i+1])
      );
    end
  endgenerate

  assign cout = carry[n];

endmodule

module pcie_interface
  (
   input 	 clock,
   input 	 reset,
   input [15:0]  pci_id,
   // read completion (rc)
   input [31:0]  rc_dw2,
   input [31:0]  rc_data,
   input 	 rc_valid,
   output reg 	 rc_ready,
   // read request (rr)
   input 	 rr_valid,
   output reg 	 rr_ready,
   input [63:0]  rr_addr,
   input [7:0] 	 rr_tag,
   // write request (wr)
   input 	 wr_valid,
   output  	 wr_ready, // pulses 16 times in request of the next data value
   input [63:0]  wr_data,
   input [63:0]  wr_addr,
   input 	 wr_last,
   // AXI stream to PCI Express core
   input 	 tx_tready,
   output [63:0] tx_tdata,
   output 	 tx_1dw,
   output 	 tx_tlast,
   output 	 tx_tvalid
   );

   localparam IDLE_STATE = 3'b000;
   localparam RC_STATE = 3'b001;
   localparam RC_DW2_STATE = 3'b010;
   localparam RR_STATE = 3'b011;
   localparam RR_ADDR_STATE = 3'b100;
   localparam WR_STATE = 3'b101;
   localparam WR_ADDR_STATE = 3'b110;
   localparam WR_DATA_STATE = 3'b111;

   reg [2:0] state = IDLE_STATE;

   // FIFO input
   wire 	     fi_ready;
   reg [65:0] 	     fi_data;
   reg 		     fi_valid = 0;

   // wr
   reg [63:0] 	     wr_data_next;
   reg 		     wr_is_32;

   // rr
   wire 	     rr_is_32 = rr_addr[63:32] == 0;
   reg 		     rr_is_32_q;

   // packet counter
   reg [3:0] packet_count = 0;

   assign wr_ready = (state == WR_DATA_STATE);

   always @(posedge clock)
     begin
	if(reset)
	  state <= IDLE_STATE;
	else
	  case(state)
	    IDLE_STATE: begin
	      if(rc_valid) state <= RC_STATE;
	      else if(rr_valid) state <= RR_STATE;
	      else if(wr_valid) state <= WR_STATE;
	      else state <= IDLE_STATE;
	    end
	    RC_STATE: begin
	      fi_data <= {2'b00, pci_id, 16'd4, 32'h4A000001};
	      fi_valid <= 1;
	      rc_ready <= 1;
	      if(tx_tready && tx_tvalid) begin
		packet_count <= packet_count + 1;
		if(packet_count == 1) state <= RC_DW2_STATE;
		else begin
		  packet_count <= 0;
		  fi_valid <= 0;
		  rc_ready <= 0;
		  state <= IDLE_STATE;
		end
	      end
	    end
	    RC_DW2_STATE: begin
	      fi_data <= {2'b01, rc_data[7:0], rc_data[15:8], rc_data[23:16], rc_data[31:24], rc_dw2[7:0], rc_dw2[15:8], rc_dw2[23:16], rc_dw2[31:24]};
	      fi_valid <= 1;
	      rc_ready <= 1;
	      if(tx_tready && tx_tvalid) begin
		packet_count <= packet_count + 1;
		if(packet_count == 1) begin
		  packet_count <= 0;
		  fi_valid <= 0;
		  rc_ready <= 0;
		  state <= IDLE_STATE;
		end
	      end
	    end
	    RR_STATE: begin
	      fi_data <= {2'b00, {pci_id, rr_tag[7:0], 8'hFF}, {2'd0, ~rr_is_32, 29'd128}};
	      fi_valid <= 1;
	      rr_ready <= 1;
	      if(tx_tready && tx_tvalid) state <= RR_ADDR_STATE;
	    end
	    RR_ADDR_STATE: begin
	      fi_data <= {rr_is_32_q, 1'b1, rr_addr[31:0], rr_is_32_q ? rr_addr[31:0] : rr_addr[63:32]};
	      fi_valid <= 1;
	      rr_ready <= 1;
	      if(tx_tready && tx_tvalid) begin
		fi_valid <= 0;
		rr_ready <= 0;
		state <= IDLE_STATE;
	      end
	    end
	    WR_STATE: begin
	      wr_is_32 <= wr_addr[63:32] == 0;
	      fi_data <= {2'b00, pci_id, 16'h00FF, 2'b01, wr_addr[63:32] != 0, 23'd0, 5'd16, 1'b0};
	      fi_valid <= 1;
	      if(tx_tready && tx_tvalid) state <= WR_ADDR_STATE;
	    end
	    WR_ADDR_STATE: begin
	      fi_data <= {2'b00, wr_is_32 ? {wr_data[7:0], wr_data[15:8], wr_data[23:16], wr_data[31:24]} : {wr_addr[31:0], wr_addr[63:32]}};
	      fi_valid <= 1;
	      if(tx_tready && tx_tvalid) state <= WR_DATA_STATE;
	    end
	    WR_DATA_STATE: begin
	      fi_data[65:64] <= wr_last ? {wr_is_32, 1'b1} : 2'b00;
	      fi_data[63:0] <= {wr_is_32 ? {wr_data[7:0], wr_data[15:8], wr_data[23:16], wr_data[31:24]} : {wr_data_next[7:0], wr_data_next[15:8], wr_data_next[23:16], wr_data_next[31:24]}, wr_data_next[63:32]};
	      fi_valid <= 1;
	      if(tx_tready && tx_tvalid) begin
		fi_valid <= 0;
		state <= IDLE_STATE;
	      end
	    end
	  endcase
	wr_data_next <= wr_data;
	rr_ready <= (state == RR_STATE);
	rr_is_32_q <= rr_is_32;
     end

   fwft_fifo #(.NBITS(66), .FULL_OFFSET(9'h1C0)) tx_fifo
     (
      .reset(reset),
      .i_clock(clock),
      .i_data(fi_data),
      .i_valid(fi_valid),
      .i_ready(fi_ready),
      .o_clock(clock),
      .o_read(tx_tready & tx_tvalid),
      .o_data({tx_1dw, tx_tlast, tx_tdata}),
      .o_valid(tx_tvalid),
      .o_almost_empty()
      );

endmodule

module adder(
    input [3:0] A,
    input [3:0] B,
    input C,
    output reg [3:0] S
);

reg [3:0] sum;
reg [3:0] carry;

initial begin
    sum = 4'b0000;
    carry = 4'b0000;
end

always @ (A or B or C) begin
    if (C == 1'b0) begin
        sum = A + B;
        carry = (A + B >= 4'b10000) ? 4'b0001 : 4'b0000;
    end
    else begin
        sum = carry;
        carry = (A + B + carry >= 4'b10000) ? 4'b0001 : 4'b0000;
    end
end

ultra_slice_logic_ffx #(
    .LOC("SLICE_X0Y0"),
    .BEL("CARRY4"),
    .TYPE("FDPE")
) ff_i (
    .C(C),
    .CE(1'b1),
    .SR(1'b0),
    .D(carry[3]),
    .Q(carry[3])
);

ultra_slice_logic_ffx #(
    .LOC("SLICE_X0Y1"),
    .BEL("CARRY4"),
    .TYPE("FDPE")
) ff_i (
    .C(C),
    .CE(1'b1),
    .SR(1'b0),
    .D(carry[2]),
    .Q(carry[2])
);

ultra_slice_logic_ffx #(
    .LOC("SLICE_X0Y2"),
    .BEL("CARRY4"),
    .TYPE("FDPE")
) ff_i (
    .C(C),
    .CE(1'b1),
    .SR(1'b0),
    .D(carry[1]),
    .Q(carry[1])
);

ultra_slice_logic_ffx #(
    .LOC("SLICE_X0Y3"),
    .BEL("CARRY4"),
    .TYPE("FDPE")
) ff_i (
    .C(C),
    .CE(1'b1),
    .SR(1'b0),
    .D(carry[0]),
    .Q(carry[0])
);

assign S = (C == 1'b0) ? sum : carry;

endmodule

module oh_counter #(parameter DW   = 32,         // width of data inputs
		    parameter TYPE = "INCREMENT" // also DECREMENT, GRAY, LFSR
		    ) 
   (
   input 	   clk, // clk input
   input 	   in, // input to count
   input 	   en, // enable counter
   input 	   load, // load counter
   input [DW-1:0]  load_data,// load data
   output [DW-1:0] count, // current count value   
   output 	   carry, // carry out from counter
   output 	   zero   // counter is zero
    );

   // local variables
   reg [DW-1:0]    count;
   reg 		   carry;
   wire [DW-1:0]   count_in;
   wire 	   carry_in;

   // configure counter based on type
   generate
      if(TYPE=="INCREMENT")
	begin
	   assign {carry_in,count_in[DW-1:0]} = count[DW-1:0] + in;
	end
      else if(TYPE=="DECREMENT")
	begin
	   assign count_in[DW-1:0] = count[DW-1:0] - in;
	end
      else if (TYPE=="GRAY")
	begin
	   initial
	     $display ("NOT IMPLEMENTED");	   
	end
      else if (TYPE=="LFSR")
	begin
	   initial
	     $display ("NOT IMPLEMENTED");	   
	end      
   endgenerate

   // counter
   always @(posedge clk)
     if(load)
       begin
	  carry         <= 1'b0;	  
	  count[DW-1:0] <= load_data[DW-1:0];
       end
     else if (en)
       begin
	  carry         <= carry_in;
	  count[DW-1:0] <= count_in[DW-1:0];
       end

   // counter expired
   assign zero = ~(count[DW-1:0]);

endmodule

