module axi_to_custom_protocol_converter
(
    input aclk,
    input areset_d1,
    input si_rs_bvalid,
    input si_rs_bready,
    output m_axi_bvalid,
    input m_axi_bready,
    output [1:0] m_axi_bresp,
    input [19:0] in,
    output [11:0] out,
    output [1:0] skid_buffer_reg,
    output reg [31:0] cnt_read_reg
);

    reg [11:0] out_reg;
    reg [1:0] skid_buffer_reg_reg;
    reg [31:0] cnt_read_reg_reg;

    wire [19:0] in_reg;
    wire [1:0] m_axi_bresp_reg;
    wire [1:0] m_axi_bresp_reg_reg;
    wire skid_buffer_full;
    wire skid_buffer_empty;
    wire skid_buffer_push;
    wire skid_buffer_pop;

    assign in_reg = in;
    assign m_axi_bresp_reg = m_axi_bresp_reg_reg;

    // Skid buffer
    skid_buffer #(
        .WIDTH(20),
        .DEPTH(2)
    ) skid_buffer_inst (
        .aclk(aclk),
        .areset(areset_d1),
        .push(skid_buffer_push),
        .pop(skid_buffer_pop),
        .full(skid_buffer_full),
        .empty(skid_buffer_empty),
        .din(in_reg),
        .dout(out_reg),
        .skid_buffer_reg(skid_buffer_reg_reg)
    );

    // AXI protocol converter
    axi_protocol_converter #(
        .DATA_WIDTH(32),
        .ADDR_WIDTH(32),
        .ID_WIDTH(4)
    ) axi_protocol_converter_inst (
        .aclk(aclk),
        .areset(areset_d1),
        .arid(4'b0),
        .araddr(32'b0),
        .arlen(8'b0),
        .arsize(3'b0),
        .arburst(2'b0),
        .arvalid(1'b0),
        .arready(1'b0),
        .rid(m_axi_bresp_reg),
        .rdata(out_reg),
        .rresp(m_axi_bresp_reg_reg),
        .rlast(1'b1),
        .rvalid(m_axi_bvalid),
        .rready(m_axi_bready)
    );

    // Counter
    always @(posedge aclk) begin
        if (areset_d1) begin
            cnt_read_reg_reg <= 0;
        end else if (si_rs_bvalid && si_rs_bready) begin
            cnt_read_reg_reg <= cnt_read_reg_reg + 1;
        end
    end

    // Skid buffer push
    always @(posedge aclk) begin
        if (areset_d1) begin
            skid_buffer_push <= 0;
        end else if (si_rs_bvalid && si_rs_bready && !skid_buffer_full) begin
            skid_buffer_push <= 1;
        end else begin
            skid_buffer_push <= 0;
        end
    end

    // Skid buffer pop
    always @(posedge aclk) begin
        if (areset_d1) begin
            skid_buffer_pop <= 0;
        end else if (si_rs_bvalid && si_rs_bready && skid_buffer_empty) begin
            skid_buffer_pop <= 0;
        end else if (si_rs_bvalid && si_rs_bready && !skid_buffer_empty) begin
            skid_buffer_pop <= 1;
        end else begin
            skid_buffer_pop <= 0;
        end
    end

    // Skid buffer status
    always @(posedge aclk) begin
        if (areset_d1) begin
            skid_buffer_reg_reg <= 2'b0;
        end else if (skid_buffer_push && skid_buffer_full) begin
            skid_buffer_reg_reg <= 2'b11;
        end else if (skid_buffer_push && !skid_buffer_full) begin
            skid_buffer_reg_reg <= 2'b01;
        end else if (skid_buffer_pop && skid_buffer_empty) begin
            skid_buffer_reg_reg <= 2'b00;
        end else if (skid_buffer_pop && !skid_buffer_empty) begin
            skid_buffer_reg_reg <= 2'b10;
        end
    end

    // Output
    assign out = out_reg;
    assign skid_buffer_reg = skid_buffer_reg_reg;
    assign cnt_read_reg = cnt_read_reg_reg[31:0];

endmodule

module debug_interface (
  input clk, // clock signal
  input reset_n, // asynchronous reset signal
  input [31:0] data_in, // input data
  input data_in_valid, // input data valid signal
  input read, // read signal from CPU
  input write, // write signal from CPU
  input [20:0] address, // address from CPU
  input waitrequest, // waitrequest signal from CPU
  input debug_request, // debug request signal
  input debug_ack, // debug acknowledge signal
  output [31:0] data_out, // output data
  output read_ack, // read acknowledge signal to CPU
  output write_ack, // write acknowledge signal to CPU
  output [20:0] address_out, // output address to CPU
  output wait_out, // wait signal to CPU
  output debug_break, // debug break signal
  output debug_trigger_0, // debug trigger 0 output
  output debug_trigger_1, // debug trigger 1 output
  output debug_trigger_2, // debug trigger 2 output
  output debug_trigger_3 // debug trigger 3 output
);

  // internal signals
  reg [31:0] data_reg;
  reg [20:0] address_reg;
  reg read_ack_reg;
  reg write_ack_reg;
  reg wait_reg;
  reg debug_break_reg;
  reg debug_trigger_0_reg;
  reg debug_trigger_1_reg;
  reg debug_trigger_2_reg;
  reg debug_trigger_3_reg;
  reg [31:0] debug_data_reg;
  reg [31:0] debug_address_reg;
  reg debug_armed_0;
  reg debug_armed_1;
  reg debug_armed_2;
  reg debug_armed_3;

  // assign outputs
  assign data_out = data_reg;
  assign read_ack = read_ack_reg;
  assign write_ack = write_ack_reg;
  assign address_out = address_reg;
  assign wait_out = wait_reg;
  assign debug_break = debug_break_reg;
  assign debug_trigger_0 = debug_trigger_0_reg;
  assign debug_trigger_1 = debug_trigger_1_reg;
  assign debug_trigger_2 = debug_trigger_2_reg;
  assign debug_trigger_3 = debug_trigger_3_reg;

  // process input data
  always @(posedge clk, negedge reset_n) begin
    if (!reset_n) begin
      data_reg <= 'h0;
      address_reg <= 'h0;
      read_ack_reg <= 1'b0;
      write_ack_reg <= 1'b0;
      wait_reg <= 1'b0;
    end else begin
      if (data_in_valid) begin
        data_reg <= data_in;
      end
      if (read) begin
        address_reg <= address;
        read_ack_reg <= 1'b1;
      end
      if (write) begin
        address_reg <= address;
        write_ack_reg <= 1'b1;
      end
      wait_reg <= waitrequest;
    end
  end

  // process debug requests
  always @(posedge clk, negedge reset_n) begin
    if (!reset_n) begin
      debug_break_reg <= 1'b0;
      debug_trigger_0_reg <= 1'b0;
      debug_trigger_1_reg <= 1'b0;
      debug_trigger_2_reg <= 1'b0;
      debug_trigger_3_reg <= 1'b0;
      debug_data_reg <= 'h0;
      debug_address_reg <= 'h0;
      debug_armed_0 <= 1'b0;
      debug_armed_1 <= 1'b0;
      debug_armed_2 <= 1'b0;
      debug_armed_3 <= 1'b0;
    end else begin
      if (debug_request) begin
        debug_break_reg <= 1'b1;
      end else if (debug_ack) begin
        debug_break_reg <= 1'b0;
      end
      if (debug_armed_0 && (address_reg == debug_address_reg)) begin
        debug_trigger_0_reg <= 1'b1;
        debug_data_reg <= data_reg;
      end
      if (debug_armed_1 && (address_reg == debug_address_reg)) begin
        debug_trigger_1_reg <= 1'b1;
        debug_data_reg <= data_reg;
      end
      if (debug_armed_2 && (address_reg == debug_address_reg)) begin
        debug_trigger_2_reg <= 1'b1;
        debug_data_reg <= data_reg;
      end
      if (debug_armed_3 && (address_reg == debug_address_reg)) begin
        debug_trigger_3_reg <= 1'b1;
        debug_data_reg <= data_reg;
      end
    end
  end

  // set debug triggers
  always @(posedge clk, negedge reset_n) begin
    if (!reset_n) begin
      debug_armed_0 <= 1'b0;
      debug_armed_1 <= 1'b0;
      debug_armed_2 <= 1'b0;
      debug_armed_3 <= 1'b0;
    end else begin
      if (debug_request) begin
        debug_address_reg <= address;
        if (data_in[1:0] == 2'b00) begin
          debug_armed_0 <= 1'b1;
        end else if (data_in[1:0] == 2'b01) begin
          debug_armed_1 <= 1'b1;
        end else if (data_in[1:0] == 2'b10) begin
          debug_armed_2 <= 1'b1;
        end else if (data_in[1:0] == 2'b11) begin
          debug_armed_3 <= 1'b1;
        end
      end
    end
  end

endmodule

module up_down_counter (
  input clk,
  input areset,
  input dir,
  output reg [2:0] count,
  output reg cout
);

  always @(posedge clk or negedge areset) begin
    if (areset == 0) begin
      count <= 3'b0;
      cout <= 1'b0;
    end else begin
      if (dir == 1) begin
        if (count == 3'b111) begin
          count <= 3'b000;
          cout <= 1'b1;
        end else begin
          count <= count + 1;
          cout <= 1'b0;
        end
      end else begin
        if (count == 3'b000) begin
          count <= 3'b111;
          cout <= 1'b1;
        end else begin
          count <= count - 1;
          cout <= 1'b0;
        end
      end
    end
  end

endmodule

module register_array
  #(parameter WIDTH = 8, DEPTH = 256, INITVAL = 0)
  (
    input clk,
    input reset,
    input write_enable,
    input [log2(DEPTH)-1:0] address,
    input [WIDTH-1:0] data_in,
    output reg [WIDTH-1:0] data_out
  );

  reg [WIDTH-1:0] mem [0:DEPTH-1];

  integer i;

  initial begin
    for (i = 0; i < DEPTH; i = i + 1) begin
      mem[i] = INITVAL;
    end
  end

  always @(posedge clk) begin
    if (reset) begin
      data_out <= 0;
    end else if (write_enable) begin
      mem[address] <= data_in;
    end
    data_out <= mem[address];
  end
endmodule

