module top_module(
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] sum,
    output [31:0] min
);

    wire [31:0] a_inv;
    wire [31:0] b_sel;
    wire [31:0] a_sel;
    wire [31:0] b_inv;
    wire [31:0] carry;
    wire [31:0] sum_temp;
    wire [31:0] min_temp;

    // Invert b if sub is 1
    xor #(32) xor_gate(b_inv, b, {32{sub}});

    // Select a or b based on sub input
    mux #(32) mux_a(a_sel, a, b_inv, sub);
    mux #(32) mux_b(b_sel, b, a_inv, sub);

    // Find the minimum of a and b
    comparator #(32) comp(a, b, min_temp);

    // Carry-lookahead adder
    carry_lookahead_adder #(32) adder(a_sel, b_sel, carry, sum_temp);

    // Output sum and min
    assign sum = sum_temp;
    assign min = min_temp;

endmodule

module mux(
    input [31:0] a,
    input [31:0] b,
    input [0:0] sel,
    output [31:0] out
);

    assign out = sel ? b : a;

endmodule

module comparator(
    input [31:0] a,
    input [31:0] b,
    output [31:0] min
);

    assign min = (a < b) ? a : b;

endmodule

module carry_lookahead_adder(
    input [31:0] a,
    input [31:0] b,
    output [31:0] carry,
    output [31:0] sum
);

    wire [31:0] p;
    wire [31:0] g;
    wire [31:0] c;

    // Generate and propagate signals
    gen_propagate #(32) gp(a, b, p, g);

    // Carry lookahead logic
    carry_lookahead #(32) cl(p, g, c, carry);

    // Sum output
    assign sum = a + b + carry;

endmodule

module gen_propagate(
    input [31:0] a,
    input [31:0] b,
    output [31:0] p,
    output [31:0] g
);

    assign p = a ^ b;
    assign g = a & b;

endmodule

module gray_code_generator (
