  always @(posedge clk) begin
    lfsr <= {lfsr[2:0], lfsr[3] ^ lfsr[2]};
  end

  assign gray_code = {lfsr[3], lfsr[2] ^ lfsr[3], lfsr[1] ^ lfsr[2], lfsr[0] ^ lfsr[1]};

