module top_module (
    input [2:0] priority_enc,
    output [1:0] output_sum
);

  wire [3:0] gray_code;
  gray_code_generator g (
    .clk(clk),
    .gray_code(gray_code)
  );

  assign output_sum[0] = priority_enc[2] + priority_enc[1];
  assign output_sum[1] = 0;

  always @(*) begin
