module adder (A, B, Cin, C);
    input [3:0] A;
    input [3:0] B;
    input Cin;
    output [3:0] C;

    wire [3:0] temp1;
    wire [3:0] temp2;

    // Calculate the sum of A and B without considering carry-in
    assign temp1 = A ^ B;

    // Calculate the carry-out from A and B
    assign temp2 = A & B;

    // Calculate the final sum with carry-in
    assign C = Cin ? (temp1 ^ Cin) : temp1;

    // Calculate the final carry-out
    assign C[4] = (temp1 & Cin) | temp2;
endmodule

