        if (reset == 0) begin
            counter <= 4'b0000;
        end else if (load == 1) begin
            counter <= load_data;
        end else if (up_down == 1) begin
            counter <= counter + 1;
        end else begin
            counter <= counter - 1;
        end
    end

    // Comparator
    assign match = (counter == preset);

    // Pulse Generator
    pulse_generator pulse_gen_inst (
        .clk(clk),
        .reset(reset),
        .match(match),
        .pulse(pulse_gen)
    );

    assign pulse = pulse_gen;

