module pulse_generator (
    input clk,
    input reset,
    input match,
    output pulse
);

    reg [1:0] state;
    reg pulse_gen;

    parameter IDLE = 2'b00;
    parameter PULSE_HIGH = 2'b01;
    parameter PULSE_LOW = 2'b10;

    always @(posedge clk or negedge reset) begin
        if (reset == 0) begin
            state <= IDLE;
            pulse_gen <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (match == 1) begin
                        state <= PULSE_HIGH;
                    end
                end
                PULSE_HIGH: begin
                    pulse_gen <= 1;
                    state <= PULSE_LOW;
                end
                PULSE_LOW: begin
                    pulse_gen <= 0;
                    state <= IDLE;
                end
            endcase
        end
    end

    assign pulse = pulse_gen;

endmodule

