module fifo_buffer(clk, wb_rst_i, data_in, data_out, push, pop, overrun, count, fifo_reset, reset_status);

  parameter fifo_width = 8;
  parameter fifo_depth = 16;
  parameter fifo_pointer_w = 4;
  parameter fifo_counter_w = 5;

  input clk;
  input wb_rst_i;
  input [fifo_width-1:0] data_in;
  input push;
  input pop;
  input fifo_reset;
  input reset_status;

  output [fifo_width-1:0] data_out;
  output overrun;
  output [fifo_counter_w-1:0] count;

  reg [fifo_pointer_w-1:0] top;
  reg [fifo_pointer_w-1:0] bottom;
  reg [fifo_counter_w-1:0] count_reg;
  reg overrun_reg;
  wire [fifo_pointer_w-1:0] top_plus_1 = top + 1'b1;

  ram #(.aw(fifo_pointer_w), .dw(fifo_width)) fifo_mem (
    .clk(clk),
    .we(push & (count_reg < fifo_depth)),
    .addr(top),
    .di(data_in),
    .do(data_out)
  );

  always @(posedge clk or posedge wb_rst_i) begin
    if (wb_rst_i) begin
      top <= 0;
      bottom <= 0;
      count_reg <= 0;
      overrun_reg <= 0;
    end else if (fifo_reset) begin
      top <= 0;
      bottom <= 0;
      count_reg <= 0;
      overrun_reg <= 0;
    end else begin
      if (push & (count_reg < fifo_depth)) begin
        top <= top_plus_1;
        count_reg <= count_reg + 1'b1;
        if (count_reg == fifo_depth) begin
          overrun_reg <= 1'b1;
        end
      end else if (pop & (count_reg > 0)) begin
        bottom <= bottom + 1'b1;
        count_reg <= count_reg - 1'b1;
        if (count_reg == 1'b0) begin
          overrun_reg <= 1'b0;
        end
      end else if (push & (count_reg == fifo_depth)) begin
        overrun_reg <= 1'b1;
      end
    end
  end

  assign overrun = overrun_reg;
  assign count = count_reg;

endmodule

