module wb_reg(
    input clk,
    input rst,
    input [7:0] current_test,
    input [ADDR_WIDTH-1:0] wbm_adr_i,
    input [DATA_WIDTH-1:0] wbm_dat_i,
    output reg [DATA_WIDTH-1:0] wbm_dat_o,
    input wbm_we_i,
    input [SELECT_WIDTH-1:0] wbm_sel_i,
    input wbm_stb_i,
    output reg wbm_ack_o,
    output reg wbm_err_o,
    output reg wbm_rty_o,
    input wbm_cyc_i,
    output reg [ADDR_WIDTH-1:0] wbs_adr_o,
    input [DATA_WIDTH-1:0] wbs_dat_i,
    output reg [DATA_WIDTH-1:0] wbs_dat_o,
    output reg wbs_we_o,
    output reg [SELECT_WIDTH-1:0] wbs_sel_o,
    output reg wbs_stb_o,
    input wbs_ack_i,
    input wbs_err_i,
    input wbs_rty_i,
    output reg wbs_cyc_o
);

// Registers
reg [DATA_WIDTH-1:0] reg_data [0:(1<<ADDR_WIDTH)-1];

// Combinational logic
assign wbm_dat_o = wbm_stb_i ? reg_data[wbm_adr_i] : 'bz;
assign wbs_dat_o = reg_data[wbs_adr_o];
assign wbm_ack_o = wbm_stb_i;
assign wbm_err_o = 0;
assign wbm_rty_o = 0;
assign wbs_we_o = 0;
assign wbs_sel_o = 0;
assign wbs_stb_o = 0;

// State machine
localparam IDLE = 2'b00, WRITE = 2'b01, READ = 2'b10;
reg [1:0] state = IDLE;
always @(posedge clk) begin
    if (rst) begin
        state <= IDLE;
        wbm_ack_o <= 0;
        wbm_err_o <= 0;
        wbm_rty_o <= 0;
        wbs_dat_o <= 0;
        wbs_we_o <= 0;
        wbs_sel_o <= 0;
        wbs_stb_o <= 0;
        wbs_cyc_o <= 0;
    end else begin
        case (state)
            IDLE: begin
                if (wbm_cyc_i && wbm_stb_i) begin
                    state <= WRITE;
                    wbm_ack_o <= 1;
                    reg_data[wbm_adr_i] <= wbm_dat_i;
                end else if (wbm_cyc_i && !wbm_stb_i) begin
                    state <= READ;
                    wbs_adr_o <= wbm_adr_i;
                    wbs_we_o <= 0;
                    wbs_sel_o <= wbm_sel_i;
                    wbs_stb_o <= 1;
                    wbs_cyc_o <= 1;
                end
            end
            WRITE: begin
                if (wbm_cyc_i && wbm_stb_i) begin
                    state <= WRITE;
                    wbm_ack_o <= 1;
                    reg_data[wbm_adr_i] <= wbm_dat_i;
                end else begin
                    state <= IDLE;
                    wbm_ack_o <= 0;
                end
            end
            READ: begin
                if (wbs_ack_i) begin
                    state <= IDLE;
                    wbs_stb_o <= 0;
                    wbs_cyc_o <= 0;
                    wbs_dat_o <= wbs_dat_i;
                end else if (wbs_err_i || wbs_rty_i) begin
                    state <= IDLE;
                    wbs_stb_o <= 0;
                    wbs_cyc_o <= 0;
                end
            end
        endcase
    end
end

endmodule

module predictor_2bit (clock, reset, enable, taken_i, prediction_o);

  input clock, reset, enable, taken_i;
  output prediction_o;

  reg [1:0] counter;
  reg [1:0] next_counter;
  reg [1:0] next_state;

  always @(posedge clock) begin
    if (reset) begin
      counter <= 2'b00;
    end else if (enable) begin
      next_counter <= counter;
      if (taken_i) begin
        if (counter < 2) begin
          next_counter <= counter + 2'b01;
        end
      end else begin
        if (counter > 0) begin
          next_counter <= counter - 2'b01;
        end
      end
    end
  end

  always @(*) begin
    case (counter)
      2'b00: begin
        if (next_state == 2'b00) begin
          prediction_o = 1'b0;
        end else begin
          if ($random < 8'h60) begin
            prediction_o = 1'b1;
          end else begin
            prediction_o = 1'b0;
          end
        end
      end
      2'b01: begin
        if (next_state == 2'b00 || next_state == 2'b01) begin
          prediction_o = 1'b0;
        end else begin
          if ($random < 8'h60) begin
            prediction_o = 1'b1;
          end else begin
            prediction_o = 1'b0;
          end
        end
      end
      2'b10: begin
        if (next_state == 2'b11 || next_state == 2'b10) begin
          prediction_o = 1'b1;
        end else begin
          if ($random < 8'h60) begin
            prediction_o = 1'b1;
          end else begin
            prediction_o = 1'b0;
          end
        end
      end
      2'b11: begin
        if (next_state == 2'b11) begin
          prediction_o = 1'b1;
        end else begin
          if ($random < 8'h60) begin
            prediction_o = 1'b1;
          end else begin
            prediction_o = 1'b0;
          end
        end
      end
    endcase
  end

  always @(posedge clock) begin
    if (reset) begin
      next_state <= 2'b00;
    end else if (enable) begin
      next_state <= next_counter;
    end
  end

endmodule

