  input D, CLK, CLR, SET;
  output Q, QN;
  reg Q, QN;

  always @(posedge CLK or negedge CLR or posedge SET)
    if (~CLR)
      begin
        Q <= 1'b0;
        QN <= 1'b1;
      end
    else if (SET)
      begin
        Q <= 1'b1;
        QN <= 1'b0;
      end
    else
      begin
        Q <= D;
        QN <= ~D;
      end
endmodule

module addsub_4bit (
    input [3:0] O,
    input [3:0] A,
    input C,
    output reg [3:0] S,
    output reg [3:0] D,
    output reg B
);

reg [3:0] adder_out;
reg [3:0] sub_out;
reg [3:0] sub_borrow;

always @(*) begin
    if(C) begin
        adder_out[0] = O[0] + A[0];
        adder_out[1] = O[1] + A[1] + adder_out[0][1];
        adder_out[2] = O[2] + A[2] + adder_out[1][2];
        adder_out[3] = O[3] + A[3] + adder_out[2][3];
        S = adder_out;
    end else begin
        sub_out[0] = O[0] - A[0];
        sub_borrow[0] = ~O[0] & A[0];
        sub_out[1] = O[1] - A[1] - sub_borrow[0];
        sub_borrow[1] = (~O[1] & A[1]) | (sub_borrow[0] & (O[1] < A[1]));
        sub_out[2] = O[2] - A[2] - sub_borrow[1];
        sub_borrow[2] = (~O[2] & A[2]) | (sub_borrow[1] & (O[2] < A[2]));
        sub_out[3] = O[3] - A[3] - sub_borrow[2];
        B = sub_borrow[2];
        D = sub_out;
    end
end

endmodule

module ripple_carry_adder (
    input [3:0] a, b,
    input carry_in,
    output [3:0] sum,
    output carry_out
);

    wire [3:0] temp_sum;
    wire [3:0] temp_carry;

    assign temp_sum = a + b + carry_in;
    assign sum = temp_sum[3:0];
    assign carry_out = temp_sum[4] | temp_carry[3];

    genvar i;
    generate
        for (i = 0; i < 3; i = i + 1) begin : carry_gen
            assign temp_carry[i] = temp_sum[i+1] & temp_carry[i+1];
        end
    endgenerate

endmodule

