module binary_to_bcd (
    input [2:0] bin,
    output reg [7:0] bcd
);

integer i;

always @(*) begin
    bcd = 8'b0000_0000;
    for (i = 0; i < 3; i = i + 1) begin
        if (bcd[3:0] >= 5) begin
            bcd[3:0] = bcd[3:0] + 3;
        end
        if (bcd[7:4] >= 5) begin
            bcd[7:4] = bcd[7:4] + 3;
        end
        bcd = bcd << 1;
        bcd[0] = bin[2 - i];
    end
end

endmodule

