        .clk(clk),
        .d(final_output[0]),
        .q(register_output)
    );

    shift_register_module shift_register_inst (
        .clk(clk),
        .d(shift_register_output),
        .q(shift_register_output)
    );

    always @(posedge clk) begin
        if (reset) begin
            register_output <= 4'b0000;
            shift_register_output <= 16'b0000000000000000;
        end else begin
            register_output <= {register_output[2:0], final_output[0]};
            shift_register_output <= {shift_register_output[14:0], shift_register_output[15] ^ shift_register_output[13]};
        end
    end

    assign final_output = (shift_register_output[15:0] << 8) | (shift_register_output[14] << 7) | (shift_register_output[13] << 6) | (shift_register_output[12] << 5) | (shift_register_output[11] << 4) | (shift_register_output[10] << 3) | (shift_register_output[9] << 2) | (shift_register_output[8] << 1) | (shift_register_output[7] >> 7) | (shift_register_output[6] >> 6) | (shift_register_output[5] >> 5) | (shift_register_output[4] >> 4) | (shift_register_output[3] >> 3) | (shift_register_output[2] >> 2) | (shift_register_output[1] >> 1) | shift_register_output[0] + register_output;

