module control_logic (
  input [15:0] in,
  input [3:0] ctrl,
  output [15:0] out
);

  always @(*) begin
    case(ctrl)
      4'b0000: out = {in[14:0], 1'b0};
      4'b0001: out = {1'b0, in[15:1]};
      4'b0010: out = in + 1;
      4'b0011: out = in - 1;
      4'b0100: out = in & 16'h00FF;
      4'b0101: out = in | 16'hFF00;
      4'b0110: out = in ^ 16'hFFFF;
      4'b0111: out = ~in;
      4'b1000: out = in;
      4'b1001: out = 16'h0000;
      4'b1010: out = 16'hFFFF;
      4'b1011: out = in[0];
      4'b1100: out = in[15];
      4'b1101: out = in[ctrl[3:2]];
      4'b1110: out = in[ctrl[1:0]];
      default: out = 16'h0000;
    endcase
  end

endmodule

