module OutBuff #(parameter WIDTH = 13)(
    input clk,
    input [WIDTH-1:0] in,
    output reg [WIDTH-1:0] out,
    input writedone,
    input clkdiv,
    output reg outclk,
    output towrite);

    reg [6:0] i;
    reg [WIDTH-1:0] outbuf [20:0];
    reg [15:0] counter = 0;
    reg oldwrite = 0;
    reg [6:0] bufpointer = 0;

    assign towrite = (bufpointer < 8'd19);

    always @(posedge clk) begin
        if (counter > clkdiv) begin
            outclk <= !outclk;
            counter <= 0;
            if (bufpointer > 0) begin
                out <= outbuf[bufpointer - 1];
                bufpointer <= bufpointer - 1;
            end
        end
        if (!oldwrite) begin
            if (writedone && bufpointer < 20) begin
                for(i=19;i>=1;i=i-1) begin
                    outbuf[i] <= outbuf[i-1];
                end
                outbuf[0] <= in;
                bufpointer <= bufpointer + 1;
                oldwrite <= 1;
            end
        end
        if (!writedone) begin
            oldwrite <= 0;
        end
        counter <= counter + 1;
    end
endmodule

module jtag_interface (
    input tms,
    input tck,
    input tdi,
    input ntrst,
    input tdoutap,
    input tdouser,
    output tdo,
    output tmsutap,
    output tckutap,
    output tdiutap,
    output shiftuser,
    output clkdruser,
    output updateuser,
    output runidleuser,
    output usr1user
);

    reg[3:0] tms_state;
    reg tdo_internal;
    reg[31:0] tdi_internal;
    reg[31:0] tdoutap_internal;
    reg[31:0] tdouser_internal;

    always @(posedge tck) begin
        if (ntrst) begin
            tms_state <= 4'b1111;
            tdo_internal <= 1'b0;
            tdi_internal <= 32'h0;
            tdoutap_internal <= 32'h0;
            tdouser_internal <= 32'h0;
        end else begin
            case (tms_state)
                4'b1111: begin // Test-Logic-Reset
                    tms_state <= tms ? 4'b0000 : 4'b1111;
                    tdo_internal <= 1'b0;
                end
                4'b0000: begin // Run-Test/Idle
                    tms_state <= tms ? 4'b0001 : 4'b0000;
                    tdo_internal <= 1'b0;
                end
                4'b0001: begin // Select-DR-Scan
                    tms_state <= tms ? 4'b0010 : 4'b0011;
                    tdo_internal <= 1'b0;
                end
                4'b0010: begin // Capture-DR
                    tms_state <= tms ? 4'b0011 : 4'b0010;
                    tdo_internal <= 1'b0;
                    tdi_internal <= {tdi_internal[30:0], tdi};
                end
                4'b0011: begin // Shift-DR
                    tms_state <= tms ? 4'b0100 : 4'b0011;
                    tdo_internal <= tdi_internal[31];
                    tdi_internal <= {tdi_internal[30:0], tdi};
                end
                4'b0100: begin // Exit1-DR
                    tms_state <= tms ? 4'b0101 : 4'b0100;
                    tdo_internal <= tdi_internal[31];
                end
                4'b0101: begin // Pause-DR
                    tms_state <= tms ? 4'b0110 : 4'b0101;
                    tdo_internal <= tdi_internal[31];
                end
                4'b0110: begin // Exit2-DR
                    tms_state <= tms ? 4'b0010 : 4'b0110;
                    tdo_internal <= tdi_internal[31];
                end
                4'b0010: begin // Update-DR
                    tms_state <= tms ? 4'b0000 : 4'b0010;
                    tdo_internal <= tdi_internal[31];
                end
                4'b0011: begin // Select-IR-Scan
                    tms_state <= tms ? 4'b0100 : 4'b1000;
                    tdo_internal <= 1'b0;
                end
                4'b1000: begin // Capture-IR
                    tms_state <= tms ? 4'b1001 : 4'b1000;
                    tdo_internal <= 1'b0;
                    tdi_internal <= {tdi_internal[30:0], tdi};
                end
                4'b1001: begin // Shift-IR
                    tms_state <= tms ? 4'b1010 : 4'b1001;
                    tdo_internal <= tdi_internal[31];
                    tdi_internal <= {tdi_internal[30:0], tdi};
                end
                4'b1010: begin // Exit1-IR
                    tms_state <= tms ? 4'b1011 : 4'b1010;
                    tdo_internal <= tdi_internal[31];
                end
                4'b1011: begin // Pause-IR
                    tms_state <= tms ? 4'b1100 : 4'b1011;
                    tdo_internal <= tdi_internal[31];
                end
                4'b1100: begin // Exit2-IR
                    tms_state <= tms ? 4'b1000 : 4'b1100;
                    tdo_internal <= tdi_internal[31];
                end
                4'b1000: begin // Update-IR
                    tms_state <= tms ? 4'b0000 : 4'b1000;
                    tdo_internal <= tdi_internal[31];
                end
            endcase
        end
    end

    assign tdo = tdo_internal;
    assign tmsutap = 1'b0;
    assign tckutap = tck;
    assign tdiutap = tdi;
    assign shiftuser = 1'b0;
    assign clkdruser = 1'b0;
    assign updateuser = 1'b0;
    assign runidleuser = 1'b0;
    assign usr1user = 1'b0;

endmodule

module up_down_counter (
