module carry_lookahead_adder (
  input [31:0] a,
  input [31:0] b,
  output [31:0] sum
);

generate
  genvar i;
  wire [31:0] c;
  assign c[0] = 1'b0;
  for (i = 1; i < 32; i = i + 1) begin
    assign c[i] = (a[i-1] & b[i-1]) | (a[i-1] & c[i-1]) | (b[i-1] & c[i-1]);
  end
endgenerate

assign sum = a + b + c;

endmodule

