module sg_list_reader_128 #(
	parameter C_DATA_WIDTH = 9'd128
)
(
	input CLK,
	input RST,

	input [C_DATA_WIDTH-1:0] BUF_DATA,	// Scatter gather buffer data 
	input BUF_DATA_EMPTY,				// Scatter gather buffer data empty
	output BUF_DATA_REN,				// Scatter gather buffer data read enable

	output VALID,						// Scatter gather element data is valid
	output EMPTY,						// Scatter gather elements empty
	input REN,							// Scatter gather element data read enable
	output [63:0] ADDR,					// Scatter gather element address
	output [31:0] LEN					// Scatter gather element length (in words)
);

// Define states
parameter [1:0] S_SGR128_CAP_0 = 2'b00;
parameter [1:0] S_SGR128_CAP_RDY = 2'b01;
parameter [1:0] S_SGR128_RD_0 = 2'b00;
parameter [1:0] S_SGR128_RD_WAIT = 2'b01;

// Define registers
reg rRdState = S_SGR128_RD_0;
reg rCapState = S_SGR128_CAP_0;
reg [C_DATA_WIDTH-1:0] rData = {C_DATA_WIDTH{1'd0}};
reg [C_DATA_WIDTH-1:0] _rData = {C_DATA_WIDTH{1'd0}};
reg [63:0] rAddr = 64'd0;
reg [63:0] _rAddr = 64'd0;
reg [31:0] rLen = 0;
reg [31:0] _rLen = 0;
reg rFifoValid = 0;
reg _rFifoValid = 0;
reg rDataValid = 0;
reg _rDataValid = 0;

// Define outputs
assign BUF_DATA_REN = (rRdState != S_SGR128_RD_WAIT);
assign VALID = (rCapState == S_SGR128_CAP_RDY);
assign EMPTY = (BUF_DATA_EMPTY & (rRdState != S_SGR128_RD_WAIT));
assign ADDR = rAddr;
assign LEN = rLen;

// Capture address and length as it comes out of the FIFO
always @(posedge CLK) begin
	if (RST) begin
		rRdState <= S_SGR128_RD_0;
		rCapState <= S_SGR128_CAP_0;
		rData <= {C_DATA_WIDTH{1'd0}};
		rFifoValid <= 1'd0;
		rDataValid <= 1'd0;
		rAddr <= 64'd0;
		rLen <= 32'd0;
	end else begin
		rRdState <= _rRdState;
		rCapState <= _rCapState;
		rData <= BUF_DATA;
		rFifoValid <= _rFifoValid;
		rDataValid <= _rDataValid;
		rAddr <= _rAddr;
		rLen <= _rLen;
	end
end

// Determine next state
always @(*) begin
	_rRdState = rRdState;
	_rCapState = rCapState;
	_rData = BUF_DATA;
	_rFifoValid = (BUF_DATA_REN & !BUF_DATA_EMPTY);
	_rDataValid = rFifoValid;
	_rAddr = rAddr;
	_rLen = rLen;

	case (rCapState)
		S_SGR128_CAP_0: begin
			if (rDataValid) begin
				_rAddr = rData[63:0];
				_rLen = rData[95:64];
				_rCapState = S_SGR128_CAP_RDY;
			end
		end
		S_SGR128_CAP_RDY: begin
			if (REN)
				_rCapState = S_SGR128_CAP_0;
		end
	endcase

	case (rRdState)
		S_SGR128_RD_0: begin
			if (!BUF_DATA_EMPTY)
				_rRdState = S_SGR128_RD_WAIT;
		end
		S_SGR128_RD_WAIT: begin
			if (REN)
				_rRdState = S_SGR128_RD_0;
		end
	endcase
end

endmodule

module crc_module (/*AUTOARG*/
   // Inputs
   clk,
   // Outputs
   Output
   );

   input clk;
   output reg [8:0] Output;

   integer cyc; initial cyc = 0;
   reg [63:0] crc;
   reg [31:0] sum;

   wire [8:0] Input = crc[8:0];

   always @ (posedge clk) begin
      cyc <= cyc + 1;
      crc <= {crc[62:0], crc[63] ^ crc[2] ^ crc[0]};
      if (cyc==0) begin
         // Setup
         crc <= 64'h5aef0c8d_d70a4497;
         sum <= 32'h0;
      end
      else if (cyc>10 && cyc<90) begin
         sum <= {sum[30:0],sum[31]} ^ {23'h0, crc[8:0]};
      end
      else if (cyc==99) begin
         if (sum == 32'he8bbd130) begin
            Output <= 9'h4a;
         end
         else begin
            Output <= 9'h55;
         end
         $finish;
      end
   end

endmodule

