module serial_communication(
    input wire CLK_100MHz,
    input wire reset,
    input wire Rx,
    output wire Tx,
    output wire transmit,
    output wire [7:0] LED,
    output wire [7:0] recv_error
);

reg [7:0] display_byte;
reg [7:0] tx_byte;
reg is_received;
reg is_transmitting;

assign Tx = tx_byte[0];
assign is_receiving = !Rx;
assign is_transmitting = (tx_byte != 8'b00000000);

always @(posedge CLK_100MHz) begin
    if (reset) begin
        display_byte <= 8'b00000000;
        tx_byte <= 8'b00000000;
        transmit <= 1'b0;
        is_received <= 1'b0;
        recv_error <= 8'b00000000;
    end else begin
        if (is_received) begin
            display_byte <= rx_byte;
            tx_byte <= rx_byte;
            LED <= rx_byte;
            transmit <= 1'b1;
            is_received <= 1'b0;
        end else if (is_transmitting) begin
            tx_byte <= {tx_byte[6:0], 1'b0};
            transmit <= 1'b1;
        end else begin
            tx_byte <= 8'b00000000;
            transmit <= 1'b0;
        end
    end
end

always @(posedge CLK_100MHz) begin
    if (reset) begin
        recv_error <= 8'b00000000;
    end else begin
        if (is_received) begin
            recv_error <= 8'b00000000;
        end else if (Rx == 1'b0) begin
            recv_error <= 8'b00000001;
        end
    end
end

always @(posedge CLK_100MHz) begin
    if (reset) begin
        is_received <= 1'b0;
    end else begin
        if (Rx == 1'b0) begin
            is_received <= 1'b1;
        end
    end
end

endmodule

module fsm_4bit_sequence_detection (
  input clk,
  input reset,
  input [3:0] data,
  output reg match
);

parameter A = 2'b00, B = 2'b01, C = 2'b10, D = 2'b11;

reg [1:0] state;
reg [3:0] shift_reg;

always @(posedge clk or negedge reset) begin
  if (reset == 0) begin
    state <= A;
    shift_reg <= 4'b0000;
    match <= 0;
  end
  else begin
    case (state)
      A: begin
        shift_reg <= {shift_reg[2:0], data};
        if (shift_reg == 4'b1010) begin
          match <= 1;
          state <= B;
        end
        else begin
          match <= 0;
          state <= A;
        end
      end
      B: begin
        match <= 0;
        state <= C;
      end
      C: begin
        match <= 0;
        state <= D;
      end
      D: begin
        match <= 0;
        state <= A;
      end
    endcase
  end
end

endmodule

module top_module (
    input clk,
    input reset,
    input [3:0] input_data,
    output reg [3:0] BCD1,
    output reg [3:0] BCD0,
    output reg [7:0] result
);

reg [3:0] shift_reg;
reg load;
wire [3:0] bcd_out;

shift_register shift_reg_inst (
    .clk(clk),
    .reset(reset),
    .data_in(input_data),
    .data_out(shift_reg),
    .load(load)
);

binary_to_bcd_converter bcd_inst (
    .binary_in(shift_reg),
    .bcd_out(bcd_out)
);

always @(posedge clk) begin
    if (reset) begin
        load <= 1'b0;
        BCD1 <= 4'b0;
        BCD0 <= 4'b0;
        result <= 8'b0;
    end else begin
        load <= 1'b1;
        BCD1 <= (bcd_out[3:2] >= 2'b010) ? bcd_out[3:2] + 2'b011 : bcd_out[3:2];
        BCD0 <= (bcd_out[1:0] >= 2'b010) ? bcd_out[1:0] + 2'b011 : bcd_out[1:0];
        result <= BCD1 + BCD0;
    end
end

endmodule

module shift_register (
    input clk,
    input reset,
    input [3:0] data_in,
    output reg [3:0] data_out,
    input load
);

always @(posedge clk) begin
    if (reset) begin
        data_out <= 4'b0;
    end else if (load) begin
        data_out <= data_in;
    end else begin
        data_out <= {data_out[2:0], data_out[3]};
    end
end

endmodule

module binary_to_bcd_converter (
    input [3:0] binary_in,
    output reg [3:0] bcd_out
);

always @* begin
    case (binary_in)
        4'b0000: bcd_out = 4'b0000;
        4'b0001: bcd_out = 4'b0001;
        4'b0010: bcd_out = 4'b0010;
        4'b0011: bcd_out = 4'b0011;
        4'b0100: bcd_out = 4'b0100;
        4'b0101: bcd_out = 4'b0101;
        4'b0110: bcd_out = 4'b0110;
        4'b0111: bcd_out = 4'b0111;
        4'b1000: bcd_out = 4'b0011;
        4'b1001: bcd_out = 4'b0100;
        4'b1010: bcd_out = 4'b0101;
        4'b1011: bcd_out = 4'b0110;
        4'b1100: bcd_out = 4'b0111;
        4'b1101: bcd_out = 4'b1000;
        4'b1110: bcd_out = 4'b1001;
        4'b1111: bcd_out = 4'b1010;
        default: bcd_out = 4'bxxxx;
    endcase
end

endmodule

module clock_divider (
  // Clock in ports
  input         CLOCK_PLL,
  // Clock out ports
  output        CLOCK_100,
  output        CLOCK_7_143,
  output        CLOCK_25,
  // Status and control signals
  input         reset,
  output        locked
);

  // Input buffering
  //------------------------------------
  IBUF clkin1_ibufg (
    .O (CLOCK_PLL_clock_divider),
    .I (CLOCK_PLL)
  );

  // Clocking PRIMITIVE
  //------------------------------------

  // Instantiation of the MMCM PRIMITIVE
  //    * Unused inputs are tied off
  //    * Unused outputs are labeled unused
  wire [15:0] do_unused;
  wire        drdy_unused;
  wire        psdone_unused;
  wire        locked_int;
  wire        clkfbout_clock_divider;
  wire        clkfbout_buf_clock_divider;
  wire        clkfboutb_unused;
  wire        clkout3_unused;
  wire        clkout4_unused;
  wire        clkout5_unused;
  wire        clkout6_unused;
  wire        clkfbstopped_unused;
  wire        clkinstopped_unused;
  wire        reset_high;

  PLLE2_ADV #(
    .BANDWIDTH            ("OPTIMIZED"),
    .COMPENSATION         ("ZHOLD"),
    .DIVCLK_DIVIDE        (1),
    .CLKFBOUT_MULT        (8),
    .CLKFBOUT_PHASE       (0.000),
    .CLKOUT0_DIVIDE       (8),
    .CLKOUT0_PHASE        (0.000),
    .CLKOUT0_DUTY_CYCLE   (0.500),
    .CLKOUT1_DIVIDE       (112),
    .CLKOUT1_PHASE        (0.000),
    .CLKOUT1_DUTY_CYCLE   (0.500),
    .CLKOUT2_DIVIDE       (32),
    .CLKOUT2_PHASE        (0.000),
    .CLKOUT2_DUTY_CYCLE   (0.500),
    .CLKIN1_PERIOD        (10.0)
  ) plle2_adv_inst (
    // Output clocks
    .CLKFBOUT            (clkfbout_clock_divider),
    .CLKOUT0             (CLOCK_100_clock_divider),
    .CLKOUT1             (CLOCK_7_143_clock_divider),
    .CLKOUT2             (CLOCK_25_clock_divider),
    .CLKOUT3             (clkout3_unused),
    .CLKOUT4             (clkout4_unused),
    .CLKOUT5             (clkout5_unused),
    // Input clock control
    .CLKFBIN             (clkfbout_buf_clock_divider),
    .CLKIN1              (CLOCK_PLL_clock_divider),
    .CLKIN2              (1'b0),
    // Tied to always select the primary input clock
    .CLKINSEL            (1'b1),
    // Ports for dynamic reconfiguration
    .DADDR               (7'h0),
    .DCLK                (1'b0),
    .DEN                 (1'b0),
    .DI                  (16'h0),
    .DO                  (do_unused),
    .DRDY                (drdy_unused),
    .DWE                 (1'b0),
    // Other control and status signals
    .LOCKED              (locked_int),
    .PWRDWN              (1'b0),
    .RST                 (reset_high)
  );

  assign reset_high = reset; 

  assign locked = locked_int;

  // Output buffering
  //-----------------------------------

  BUFG clkf_buf (
    .O (clkfbout_buf_clock_divider),
    .I (clkfbout_clock_divider)
  );

  BUFG clkout1_buf (
    .O (CLOCK_100),
    .I (CLOCK_100_clock_divider)
  );

  BUFG clkout2_buf (
    .O (CLOCK_7_143),
    .I (CLOCK_7_143_clock_divider)
  );

  BUFG clkout3_buf (
    .O (CLOCK_25),
    .I (CLOCK_25_clock_divider)
  );

endmodule

module Palette(
    clk_a, wr_a, rd_a, addr_a, data_in_a, data_out_a, byte_en_a,
    clk_b, wr_b, rd_b, addr_b, data_in_b, data_out_b);
  parameter NUM_CHANNELS = 3;
  localparam BITS_PER_BYTE = 8;
  localparam DATA_WIDTH = NUM_CHANNELS * BITS_PER_BYTE;
  localparam ADDR_WIDTH = 10;

  input clk_a;
  input wr_a;
  input rd_a;
  input [NUM_CHANNELS-1:0] byte_en_a;
  input [ADDR_WIDTH-1:0] addr_a;
  input [DATA_WIDTH-1:0] data_in_a;
  output [DATA_WIDTH-1:0] data_out_a;

  input clk_b;
  input wr_b;
  input rd_b;
  input [ADDR_WIDTH-1:0] addr_b;
  input [DATA_WIDTH-1:0] data_in_b;
  output [DATA_WIDTH-1:0] data_out_b;

  genvar i;
  generate
    for (i = 0; i < NUM_CHANNELS; i = i + 1) begin : RAM
      // Instantiate 1Kx8 RAMs in parallel.
      palette_ram_1Kx8 ram(.clock_a(clk_a),      .clock_b(clk_b),
                           .address_a(addr_a),   .address_b(addr_b),
                           .wren_a(wr_a),        .wren_b(wr_b),
                           .rden_a(rd_a),        .rden_b(rd_b),
                           .data_a(data_in_a[(i + 1) * BITS_PER_BYTE - 1 :
                                             i * BITS_PER_BYTE]),
                           .data_b(data_in_b[(i + 1) * BITS_PER_BYTE - 1 :
                                             i * BITS_PER_BYTE]),
                           .q_a(data_out_a[(i + 1) * BITS_PER_BYTE - 1 :
                                           i * BITS_PER_BYTE]),
                           .q_b(data_out_b[(i + 1) * BITS_PER_BYTE - 1 :
                                           i * BITS_PER_BYTE]),
                           .byteena_a(byte_en_a[i]));
    end
  endgenerate

endmodule

module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out
);

reg [7:0] data_reg [3:0];
reg [1:0] counter;
reg valid_reg [3:0];

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        counter <= 2'b0;
        valid_b <= 1'b0;
        data_out <= 10'b0;
    end else begin
        if (valid_a && ready_b) begin
            data_reg[counter] <= data_in;
            valid_reg[counter] <= 1'b1;
            counter <= counter + 1'b1;
        end

        if (counter == 2'b11) begin
            data_out <= data_reg[0] + data_reg[1] + data_reg[2] + data_reg[3];
            valid_b <= valid_reg[3];
            counter <= 2'b0;
        end else begin
            valid_b <= 1'b0;
        end
    end
end

assign ready_a = (counter != 2'b11);

endmodule

module top_module (
    input clk,
    input rst,
    input en,
    input [7:0] in,
    output [3:0] out,
    output valid
);

    wire [3:0] counter_out;
    wire [7:0] priority_encoder_in;
    wire [2:0] priority_encoder_out;

    counter_4bit counter_inst (
        .clk(clk),
        .rst(rst),
        .en(en),
        .out(counter_out)
    );

    priority_encoder priority_encoder_inst (
        .in({counter_out, in}),
        .out(priority_encoder_out)
    );

    assign out = priority_encoder_out[2:0];
    assign valid = |in;

endmodule

module counter_4bit (
    input clk,
    input rst,
    input en,
    output reg [3:0] out
);

    always @(posedge clk or negedge rst) begin
        if (!rst) begin
            out <= 4'b0;
        end else if (en) begin
            out <= out + 1;
        end
    end

endmodule

module priority_encoder (
    input [11:0] in,
    output reg [2:0] out
);

    always @* begin
        casez(in)
            12'b000000000001: out = 3'b000;
            12'b000000000010: out = 3'b001;
            12'b000000000100: out = 3'b010;
            12'b000000001000: out = 3'b011;
            12'b000000010000: out = 3'b100;
            12'b000000100000: out = 3'b101;
            12'b000001000000: out = 3'b110;
            12'b000010000000: out = 3'b111;
            default: out = 3'b000;
        endcase
    end

endmodule

module shift_reg(
    // inputs
    input in,
    input shift,
    input clk,
    input reset,
    // outputs
    output reg [3:0] out
);

always @(posedge clk or negedge reset) begin
    if (reset == 0) begin
        out <= 4'b0;
    end else if (shift == 1) begin
        out <= {out[2:0], in};
    end
end

endmodule

module dff_4 (
