module top_module (
    input [7:0] in,
    input sel,
    output reg [2:0] pos,
    output reg [7:0] out_always );

    reg [7:0] in_reg;
    reg [2:0] pos_reg;

    always @(*) begin
        in_reg = in;
        pos_reg = 0;
        if (in_reg[7] == 1) pos_reg = 7;
        else if (in_reg[6] == 1) pos_reg = 6;
        else if (in_reg[5] == 1) pos_reg = 5;
        else if (in_reg[4] == 1) pos_reg = 4;
        else if (in_reg[3] == 1) pos_reg = 3;
        else if (in_reg[2] == 1) pos_reg = 2;
        else if (in_reg[1] == 1) pos_reg = 1;
        else if (in_reg[0] == 1) pos_reg = 0;
        pos = pos_reg;
    end

    always @(posedge sel) begin
        if (sel == 1) out_always = pos_reg;
        else out_always = in_reg;
    end

endmodule

module counter_4bit (
    input clk,
    input rst,
    input en,
    input [1:0] sel,
    output reg [3:0] out
);

    always @(posedge clk or negedge rst) begin
        if (~rst) begin
            out <= 4'b0000;
        end else if (en) begin
            case (sel)
                2'b00: out <= out[0] ? {out[3:1], 1'b0} : {out[3:1], 1'b1};
                2'b01: out <= out[1] ? {out[3:2], out[0], 1'b0} : {out[3:2], out[0], 1'b1};
                2'b10: out <= out[2] ? {out[3], out[1:0], 1'b0} : {out[3], out[1:0], 1'b1};
                2'b11: out <= out[3] ? {1'b0, out[2:0]} : {1'b1, out[2:0]};
            endcase
        end
    end

endmodule

module signal_splitter(
    input clk,
    input [15:0] in,
    output reg [3:0] i_high1,
    output reg [3:0] i_low1,
    output reg [3:0] i_high0,
    output reg [3:0] i_low0,
    input [3:0] o_high1,
    input [3:0] o_low1,
    input [3:0] o_high0,
    input [3:0] o_low0,
    output reg [15:0] out
);

always @(posedge clk) begin
    i_high1 <= in[15:12];
    i_low1 <= in[11:8];
    i_high0 <= in[7:4];
    i_low0 <= in[3:0];
    out[15:12] <= o_high1;
    out[11:8] <= o_low1;
    out[7:4] <= o_high0;
    out[3:0] <= o_low0;
end

endmodule

module four_bit_register (input clk, input rst, input [3:0] din, output reg [3:0] dout);
  reg [3:0] reg_out;
  always @(posedge clk or negedge rst) begin
    if (!rst) begin
      reg_out <= 4'b0;
    end else begin
      reg_out <= din;
    end
  end
  assign dout = reg_out;
endmodule

module top_module (
    input [31:0] a, // 32-bit input a
    input [31:0] b, // 32-bit input b
    input select, // Select input to choose between adder and functional module
    output [31:0] sum // 32-bit output from the active module
);

wire [31:0] adder_out;
wire [31:0] xor_out;

carry_select_adder adder_inst (
    .a(a),
    .b(b),
    .sum(adder_out)
);

xor_gate xor_inst (
    .a(adder_out),
    .b(xor_out)
);

assign sum = select ? xor_out : adder_out;

endmodule

module carry_select_adder (
    input [31:0] a, // 32-bit input a
    input [31:0] b, // 32-bit input b
    output [31:0] sum // 32-bit output sum
);

wire [31:0] carry;
wire [31:0] s;

genvar i;
generate
    for (i = 0; i < 32; i = i + 1) begin : adder_loop
        full_adder adder_inst (
            .a(a[i]),
            .b(b[i]),
            .c(carry[i]),
            .s(s[i])
        );
    end
endgenerate

generate
    for (i = 0; i < 16; i = i + 1) begin : carry_loop
        carry_select carry_inst (
            .a(s[i*2+1]),
            .b(s[i*2]),
            .c(carry[i*2+1]),
            .sum(sum[i*2])
        );
    end
endgenerate

endmodule

module full_adder (
    input a,
    input b,
    input c,
    output s,
    output cout
);

assign s = a ^ b ^ c;
assign cout = (a & b) | (c & (a ^ b));

endmodule

module carry_select (
    input a,
    input b,
    input c,
    output sum,
    output c_out
);

assign sum = (a ^ b) ^ c;
assign c_out = (a & b) | (c & (a ^ b));

endmodule

module xor_gate (
    input a,
    input b,
    output out
);

assign out = ~(a & b) & ~(~a & ~b);

endmodule

module binary_to_gray (
  input [3:0] binary,
  output reg [3:0] gray
);

  always @* begin
    gray[3] = binary[3];
    gray[2] = binary[3] ^ binary[2];
    gray[1] = binary[2] ^ binary[1];
    gray[0] = binary[1] ^ binary[0];
  end

endmodule

module binary_decoder (input [3:0] in_bin, output [2:0] out_dec);

    assign out_dec = (in_bin == 4'b000) ? 3'b001 : // enable digit A
                    (in_bin == 4'b001) ? 3'b010 : // enable digit B
                    (in_bin == 4'b010) ? 3'b100 : // enable digit C
                                        3'b000 ; // disable all digits

endmodule

module bcd_counter (input clk, input reset, input [2:0] ena, output reg [3:0] out_bcd [0:3]);

    reg [13:0] count;

    always @(posedge clk, posedge reset) begin
        if (reset) begin
            count <= 0;
            out_bcd <= 4'b0000;
        end else if (ena[0]) begin
            count <= count + 1;
            out_bcd[0] <= count[3:0];
        end else if (ena[1]) begin
            count <= count + 1;
            out_bcd[1] <= count[7:4];
        end else if (ena[2]) begin
            count <= count + 1;
            out_bcd[2] <= count[11:8];
        end else begin
            count <= count + 1;
            out_bcd[3] <= count[15:12];
        end
    end

endmodule

module seven_segment_decoder (input [3:0] in_bcd, output reg [6:0] out_seg);

    always @(*) begin
        case (in_bcd)
            4'b0000: out_seg = 7'b1000000; // 0
            4'b0001: out_seg = 7'b1111001; // 1
            4'b0010: out_seg = 7'b0100100; // 2
            4'b0011: out_seg = 7'b0110000; // 3
            4'b0100: out_seg = 7'b0011001; // 4
            4'b0101: out_seg = 7'b0010010; // 5
            4'b0110: out_seg = 7'b0000010; // 6
            4'b0111: out_seg = 7'b1111000; // 7
            4'b1000: out_seg = 7'b0000000; // 8
            4'b1001: out_seg = 7'b0010000; // 9
            default: out_seg = 7'b1111111; // blank
        endcase
    end

endmodule

module top_module (input clk, input reset, input [3:0] in_bin, input [3:1] ena, output [6:0] seg_a, output [6:0] seg_b, output [6:0] seg_c, output [6:0] seg_d);

    wire [2:0] dec_out;
    wire [3:0] bcd_out [0:3];

    binary_decoder decoder (in_bin, dec_out);
    bcd_counter counter (clk, reset, ena, bcd_out);
    seven_segment_decoder seg_a_decoder (bcd_out[0], seg_a);
    seven_segment_decoder seg_b_decoder (bcd_out[1], seg_b);
    seven_segment_decoder seg_c_decoder (bcd_out[2], seg_c);
    seven_segment_decoder seg_d_decoder (bcd_out[3], seg_d);

endmodule

module clock_splitter (
  input clk_in,
  output reg clk_out_1,
  output reg clk_out_2
);
  reg [1:0] counter = 2'b00;
  always @(posedge clk_in) begin
    counter <= counter + 1;
    if (counter == 2'b10) begin
      counter <= 2'b00;
      clk_out_1 <= ~clk_out_1;
      clk_out_2 <= ~clk_out_2;
    end
  end
endmodule

module memory_interface (
    output wire [14:0] mem_a,
    output wire [2:0] mem_ba,
    output wire mem_ck,
    output wire mem_ck_n,
    output wire mem_cke,
    output wire mem_cs_n,
    output wire mem_ras_n,
    output wire mem_cas_n,
    output wire mem_we_n,
    output wire mem_reset_n,
    inout wire [15:0] mem_dq,
    inout wire [1:0] mem_dqs,
    inout wire [1:0] mem_dqs_n,
    output wire mem_odt,
    output wire [1:0] mem_dm,
    input wire oct_rzqin
);

    // Declare internal signals
    wire [13:0] row_addr;
    wire [2:0] bank_addr;
    wire [9:0] col_addr;
    reg [1:0] dm;
    wire ck_en;

    // Address decoding
    assign row_addr = mem_a[13:0];
    assign bank_addr = mem_a[16:14];
    assign col_addr = mem_a[9:0];

    // Data mask
    always @ (mem_dq)
    begin
        dm = 2'b11;
        if (mem_dq == 16'h0000)
            dm = 2'b00;
        else if (mem_dq == 16'hffff)
            dm = 2'b00;
    end

    // Clock enable
    assign ck_en = mem_cke & (mem_cs_n == 1'b0);

    // Memory controller
    memory_controller mc (
        .clk (mem_ck),
        .rst_n (mem_reset_n),
        .cke (ck_en),
        .cs_n (mem_cs_n),
        .ras_n (mem_ras_n),
