        .ba (bank_addr),
        .dqi (mem_dq),
        .dqo (mem_dq),
        .dm (dm),
        .odt (mem_odt)
    );

    // Output signals
    assign mem_a = { row_addr, col_addr };
    assign mem_ba = bank_addr;
    assign mem_ck = mc.clk;
    assign mem_ck_n = ~mc.clk;
    assign mem_dm = dm;
    assign mem_dqs = mem_dqs;
    assign mem_dqs_n = mem_dqs_n;
    assign mem_cke = mem_cke;
    assign mem_cs_n = mem_cs_n;
