module matrix_multiplier (
    input clk,
    input rst,
    input [15:0] a,
    input [15:0] b,
    input start,
    output reg done,
    output reg [15:0] result
);

// Define constants
parameter WIDTH = 4;
parameter STAGES = 16;

// Define registers
reg [15:0] a_reg [WIDTH-1:0];
reg [15:0] b_reg [WIDTH-1:0][WIDTH-1:0];
reg [15:0] c_reg [WIDTH-1:0][WIDTH-1:0];
reg [3:0] stage;

// Define wires
wire [15:0] a_wire [WIDTH-1:0];
wire [15:0] b_wire [WIDTH-1:0][WIDTH-1:0];
wire [15:0] c_wire [WIDTH-1:0][WIDTH-1:0];

// Define pipeline stages
genvar i, j, k;
generate
    for (i = 0; i < WIDTH; i = i + 1) begin : stage_0
        assign a_wire[i] = a_reg[i];
    end

    for (i = 0; i < WIDTH; i = i + 1) begin : stage_1
        for (j = 0; j < WIDTH; j = j + 1) begin : stage_1_inner
            assign b_wire[i][j] = b_reg[i][j];
        end
    end

    for (i = 0; i < WIDTH; i = i + 1) begin : stage_2
        for (j = 0; j < WIDTH; j = j + 1) begin : stage_2_inner
            assign c_wire[i][j] = c_reg[i][j];
        end
    end

    for (i = 0; i < WIDTH; i = i + 1) begin : stage_3
        assign a_reg[i] = a;
    end

    for (i = 0; i < WIDTH; i = i + 1) begin : stage_4
        for (j = 0; j < WIDTH; j = j + 1) begin : stage_4_inner
            assign b_reg[i][j] = b;
        end
    end

    for (i = 0; i < WIDTH; i = i + 1) begin : stage_5
        for (j = 0; j < WIDTH; j = j + 1) begin : stage_5_inner
            assign c_reg[i][j] = 0;
        end
    end

    for (i = 0; i < WIDTH; i = i + 1) begin : stage_6
        for (j = 0; j < WIDTH; j = j + 1) begin : stage_6_inner
            for (k = 0; k < WIDTH; k = k + 1) begin : stage_6_innermost
                always @(posedge clk) begin
                    c_reg[i][j] <= c_wire[i][j] + a_wire[i] * b_wire[k][j];
                end
            end
        end
    end
endgenerate

// Define done signal
always @(posedge clk) begin
    if (rst) begin
        done <= 0;
        stage <= 0;
    end else if (start) begin
        if (stage == STAGES - 1) begin
            done <= 1;
            stage <= 0;
        end else begin
            done <= 0;
            stage <= stage + 1;
        end
    end else begin
        done <= 0;
        stage <= 0;
    end
end

// Define output
assign result = c_wire[3][3];

endmodule

