            output_data_ready <= 1'b1;
            dout <= (din * COEF0) +
                    (n_delay_reg1 * COEF1) +
                    (n_delay_reg2 * COEF2) +
                    (n_delay_reg3 * COEF3) +
                    (n_delay_reg4 * COEF4) +
