    output [2:0] out_vec,
    output even_parity
);

    // Reverse parity module
    reg [2:0] shift_reg;
    reg even_parity;
    assign out_vec = shift_reg;

    always @(posedge clk) begin
        if (reset) begin
            shift_reg <= 3'b0;
            even_parity <= 1'b0;
        end else begin
            shift_reg <= {in_vec[0], shift_reg[2:1]};
            even_parity <= ^in_vec;
        end
    end

    // Carry-lookahead adder
    wire [100:0] p, g, c;
    wire [99:0] s;
    assign p[0] = cin;
    assign g[0] = cin;

    genvar i;
