            assign g[i+1] = a[i] & b[i];
            assign c[i+1] = g[i+1] | (p[i+1] & c[i]);
            assign s[i] = a[i] ^ b[i] ^ c[i];
        end
    endgenerate

    assign cout = c[100];

    // Functional module
    reg [99:0] shift_reg_sum;
    reg select;
    assign sum = shift_reg_sum;

    always @(posedge clk) begin
        if (reset) begin
            shift_reg_sum <= 100'b0;
            select <= 1'b0;
