module RegisterAdd_W1 ( clk, rst, load, D, Q );
  input [0:0] D;
  output [0:0] Q;
  input clk, rst, load;
  wire   n3, n4, n6;

  // Create a D flip-flop to store the current value of the register
  DFFRX2TS Q_reg ( .D(n3), .CK(clk), .RN(rst), .Q(Q[0]), .QN(n4) );

  // Create an OR gate to determine whether to load the register
  OR2X1TS load_or ( .A(load), .B(n4), .Y(n6) );

  // Create an XOR gate to add the D input to the current value of the register
  XOR2X1TS add_xor ( .A(n3), .B(D), .Y(n4) );

  // Create an AND gate to determine whether to add the D input to the register
  AND2X1TS add_and ( .A(n6), .B(n4), .Y(n3) );
endmodule

