module hamming_code_encoder (
    input [3:0] data_in,
    output reg [7:0] byte_out
);

    // Parity bit calculation
    wire p1 = data_in[0] ^ data_in[1] ^ data_in[3];
    wire p2 = data_in[0] ^ data_in[2] ^ data_in[3];
    wire p3 = data_in[1] ^ data_in[2] ^ data_in[3];

    // Full adder circuit
    wire c1, c2;
    wire sum1, sum2, sum3;

    half_adder ha1(.a(data_in[0]), .b(p1), .sum(sum1), .carry(c1));
    half_adder ha2(.a(data_in[1]), .b(p2), .sum(sum2), .carry(c2));
    full_adder fa(.a(data_in[2]), .b(p3), .c(c1), .sum(sum3), .carry(byte_out[0]));

    // Parity bit insertion
    assign byte_out[1] = p1;
    assign byte_out[2] = p2;
    assign byte_out[3] = data_in[0];
    assign byte_out[4] = p3;
    assign byte_out[5] = data_in[1];
    assign byte_out[6] = data_in[2];
    assign byte_out[7] = data_in[3];

endmodule

module booth_multiplier (
    input [3:0] A,
    input [3:0] B,
    output reg [7:0] P
);

reg [4:0] AC;
reg [2:0] count;

always @(*) begin
    AC = {A, 2'b0};
    P = 8'b0;
    count = 3'd4;

    while(count > 0) begin
        if(AC[0] == 1 && AC[1] == 0) begin
            P = P + (B << (4-count));
            AC = AC + (~B + 1);
        end
        else if(AC[0] == 0 && AC[1] == 1) begin
            P = P + (B << (4-count));
            AC = AC + B;
        end
        AC = AC >> 1;
        count = count - 1;
    end
end

endmodule

