module counter (
    input clk,
    input rst_n,
    input ce,
    input ctrl,
    output reg [3:0] count,
    output tc,
    output borrow
);

reg [3:0] count_reg1, count_reg2;
wire [3:0] count_next;
wire tc_next, borrow_next;

assign count_next = (ctrl == 1'b0) ? (count_reg1 + 4'd1) : (count_reg1 - 4'd1);
assign tc_next = (count_reg1 == 4'hF) ? 1'b1 : 1'b0;
assign borrow_next = (count_reg1 == 4'h0) ? 1'b1 : 1'b0;

always @(posedge clk) begin
    if (rst_n == 1'b0) begin
        count_reg1 <= 4'h0;
        count_reg2 <= 4'h0;
        tc <= 1'b0;
        borrow <= 1'b0;
    end else begin
        if (ce == 1'b1) begin
            count_reg1 <= count_next;
            tc <= tc_next;
            borrow <= borrow_next;
        end
        count_reg2 <= count_reg1;
    end
end

assign count = count_reg2;

endmodule

module booth_multiplier (
    input [3:0] A,
    input [3:0] B,
    output reg [7:0] P
);

reg [3:0] A_reg;
reg [3:0] B_reg;
reg [2:0] counter;
reg [7:0] P_reg;
reg [1:0] state;

always @(*) begin
    A_reg = A;
    B_reg = B;
    counter = 3;
    P_reg = 0;
    state = 0;
end

always @(posedge clk) begin
    case (state)
        0: begin
            if (B_reg[0] == 1) begin
                P_reg = P_reg + (A_reg << 0);
            end
            state = 1;
        end
        1: begin
            if (counter == 0) begin
                state = 3;
            end else begin
                if (B_reg[0] == 0 && B_reg[1] == 0) begin
                    state = 2;
                end else if (B_reg[0] == 1 && B_reg[1] == 0) begin
                    P_reg = P_reg + (A_reg << 1);
                    state = 2;
                end else if (B_reg[0] == 0 && B_reg[1] == 1) begin
                    P_reg = P_reg + (A_reg >> 1);
                    state = 2;
                end else begin
                    state = 1;
                end
                B_reg = {B_reg[2], B_reg[3], B_reg[3], B_reg[3]};
                counter = counter - 1;
            end
        end
        2: begin
            if (counter == 0) begin
                state = 3;
            end else begin
                if (B_reg[0] == 0 && B_reg[1] == 0) begin
                    state = 1;
                end else if (B_reg[0] == 1 && B_reg[1] == 0) begin
                    P_reg = P_reg + (A_reg << 2);
                    state = 1;
                end else if (B_reg[0] == 0 && B_reg[1] == 1) begin
                    P_reg = P_reg + (A_reg >> 2);
                    state = 1;
                end else begin
                    state = 2;
                end
                B_reg = {B_reg[2], B_reg[3], B_reg[3], B_reg[3]};
                counter = counter - 1;
            end
        end
        3: begin
            P = P_reg;
            state = 0;
        end
    endcase
end

endmodule

module top_module (
    input a,
    input b,
    input sel_b1,
    input sel_b2,
    input clk,
    input reset,
    input enable,
    output reg q
);

reg [2:0] shift_reg;
wire mux_output;

// 2-to-1 multiplexer
assign mux_output = (sel_b1) ? b : ((sel_b2) ? a : (a & b));

// Shift register
always @(posedge clk) begin
    if (reset) begin
        shift_reg <= 3'b0;
    end else if (enable) begin
        shift_reg <= {mux_output, shift_reg[2:1]};
    end
end

// Output
assign q = shift_reg[0];

endmodule

