module Overflow_153600(
  input CLK,
  input process_valid,
  input CE,
  input [63:0] process_input,
  output [64:0] process_output,
  input reset
);
  parameter INSTANCE_NAME="INST";

  // Check for invalid inputs
  always @(posedge CLK) begin 
    if(process_valid===1'bx) begin 
      $display("Valid bit can't be x! Module '%s' function 'process'", INSTANCE_NAME);  
    end 
  end

  always @(posedge CLK) begin 
    if(reset===1'bx) begin 
      $display("Valid bit can't be x! Module '%s' function 'reset'", INSTANCE_NAME);  
    end 
  end

  // Delay the input by one clock cycle
  reg [63:0] process_input_delay1;
  reg process_input_delay1_valid;
  always @ (posedge CLK) begin 
    if (CE) begin 
      process_input_delay1 <= process_input; 
      process_input_delay1_valid <= process_valid;
    end 
  end

  // Set the valid bit to 1 if process_valid is '1'
  wire [31:0] cnt_GET_OUTPUT;
  reg process_output_valid;
  always @ (posedge CLK) begin 
    if (CE) begin 
      if (process_valid) begin 
        process_output_valid <= 1'b1;
      end else begin 
        process_output_valid <= 1'b0;
      end 
    end 
  end

  // Output the delayed input value along with the valid bit
  assign process_output = {{1'b0, process_output_valid}, process_input_delay1};

  // Clear the delayed input value if reset is '1'
  always @ (posedge CLK) begin 
    if (reset) begin 
      process_input_delay1 <= 64'b0;
      process_input_delay1_valid <= 1'b0;
    end 
  end
endmodule

