module fifo (
  aclr,
  data,
  rdclk,
  rdreq,
  wrclk,
  wrreq,
  q,
  rdempty,
  wrusedw
);

  parameter WIDTH = 16;
  parameter DEPTH = 8;

  input aclr;
  input [WIDTH-1:0] data;
  input rdclk;
  input rdreq;
  input wrclk;
  input wrreq;
  output [WIDTH-1:0] q;
  output rdempty;
  output [log2(DEPTH)+1:0] wrusedw;

  reg [WIDTH-1:0] mem [0:DEPTH-1];
  reg [log2(DEPTH)-1:0] rdptr;
  reg [log2(DEPTH)-1:0] wrptr;
  reg [log2(DEPTH)+1:0] count;

  always @ (posedge wrclk) begin
    if (wrreq) begin
      mem[wrptr] <= data;
      wrptr <= (wrptr == DEPTH-1) ? 0 : wrptr + 1;
      count <= count + 1;
    end
  end

  always @ (posedge rdclk) begin
    if (rdreq && !rdempty) begin
      q <= mem[rdptr];
      rdptr <= (rdptr == DEPTH-1) ? 0 : rdptr + 1;
      count <= count - 1;
    end
  end

  assign rdempty = (count == 0);
  assign wrusedw = count;

  always @ (posedge aclr) begin
    if (aclr) begin
      rdptr <= 0;
      wrptr <= 0;
      count <= 0;
    end
  end

