module pipelined_priority_encoder (
    input [7:0] in,
    output reg [2:0] pos
);

reg [7:0] data [0:2];
reg [2:0] pos_reg [0:1];
reg [1:0] stage;

always @(*) begin
    case(stage)
        0: begin
            data[0] = in;
            data[1] = in;
            data[2] = in;
            pos_reg[0] = 0;
            pos_reg[1] = 0;
        end
        1: begin
            if(data[0][3:0] != 0) begin
                data[1] = data[0];
                pos_reg[1] = pos_reg[0];
            end
            else begin
                data[1] = data[2];
                pos_reg[1] = pos_reg[1] + 4;
            end
        end
        2: begin
            if(data[1][1:0] != 0) begin
                data[2] = data[1];
                pos_reg[0] = pos_reg[1];
            end
            else begin
                data[2] = data[1] >> 2;
                pos_reg[0] = pos_reg[1] + 2;
            end
        end
        3: begin
            if(data[2][0] != 0) begin
                pos_reg[1] = pos_reg[0];
            end
            else begin
                pos_reg[1] = pos_reg[0] + 1;
            end
        end
    endcase
end

always @(posedge clk) begin
    if(reset) begin
        stage <= 0;
        pos <= 0;
    end
    else begin
        if(stage == 3) begin
            pos <= pos_reg[1];
        end
        stage <= stage + 1;
    end
end

endmodule

