module DEMUX (
  input in,
  input [log2(n)-1:0] sel,
  output [n-1:0] out
);

parameter n = 4; // number of output signals (2^n)

wire [n-1:0] mux_out;
wire [log2(n)-1:0] inv_sel;

assign inv_sel = ~sel; // invert select signal

// Implement MUX with n inputs and 1 output
assign mux_out[0] = in;
genvar i;
generate
  for (i = 1; i < n; i = i + 1) begin
    assign mux_out[i] = 0; // initialize to 0
    if (i < 2**inv_sel) begin
      assign mux_out[i] = in;
    end
  end
endgenerate

// Drive output signals with MUX output
assign out = mux_out;

endmodule

