module gpio (
    input clk,
    input resetn,

    input [15:0] sw,
    output [15:0] led,

    input [31:0] iomem_addr,
    input [31:0] iomem_wdata,
    input [3:0] iomem_wstrb,
    input iomem_valid,
    output iomem_ready
);

    reg [31:0] gpio;

    // Read operation
    assign led = gpio[15:0];
    always @(posedge clk) begin
        if (!resetn) begin
            gpio <= 0;
        end else begin
            if (iomem_valid && !iomem_ready && (iomem_addr[31:16] == 16'h0001)) begin
                iomem_ready <= 1;
                iomem_rdata <= {sw, gpio[15:0]};
            end
        end
    end

    // Write operation
    always @(posedge clk) begin
        if (!resetn) begin
            gpio <= 0;
        end else begin
            iomem_ready <= 0;
            if (iomem_valid && !iomem_ready && (iomem_addr[31:16] == 16'h0002)) begin
                iomem_ready <= 1;
                if (iomem_wstrb[0]) gpio[7:0] <= iomem_wdata[7:0];
                if (iomem_wstrb[1]) gpio[15:8] <= iomem_wdata[15:8];
            end
        end
    end

endmodule

module FixedToFloat(
    input wire CLK,
    input wire [31:0] FIXED,
    input wire EN_REG1,
    input wire EN_REGmult,
    input wire LOAD,
    input wire MS_1,
    input wire RST,
    input wire EN_REG2,
    output wire Bandcomp,
    output wire [31:0] FLOATOUT,
    output wire [7:0] Encd
);

    parameter P = 32;
    parameter W = 8;

    wire [31:0] fixed;
    wire [31:0] complemento;
    wire [31:0] MUXSIGN;
    wire [31:0] P_RESULT;
    wire [31:0] DESNORM;
    wire [7:0] Encoder;
    wire [31:0] mult;

    // Store the fixed-point number in a register
    FF_D #(.P(P)) REG_FIXED_I (
        .CLK(CLK),
        .RST(RST),
        .EN(EN_REG1),
        .D(FIXED),
        .Q(fixed)
    );

    // Calculate the two's complement of the fixed-point number
    Complement COMPLEMENTO2 (
        .a_i(fixed),
        .twos_comp(complemento)
    );

    // Determine the sign of the number and store it in a MUX
    Mux_2x1_32Bits MUX2x1_0_I (
        .MS(fixed[31]),
        .D_0(fixed),
        .D_1(complemento),
        .D_out(MUXSIGN)
    );

    // Truncate the number to 30 bits
    FF_D #(.P(P)) REG_FLOAT_mult (
        .CLK(CLK),
        .RST(RST),
        .EN(EN_REGmult),
        .D(MUXSIGN),
        .Q(mult)
    );

    // Determine the position of the first 1 in the binary sequence
    Priority_Encoder OUTONE (
        .d_in(mult),
        .d_out(Encoder)
    );

    // Normalize the number and calculate the exponent
    S_SUBT #(.P(W),.W(W)) SUBT_EXP_1_I (
        .A(Encoder),
        .B(8'b00011010), // 26 in binary
        .Y(Bandcomp)
    );

    // If the exponent is greater than 26, set the Bandcomp signal to 1 and subtract 26 from the exponent
    S_SUBT #(.P(W),.W(W)) SUBT_EXP_2_I (
        .A(8'b00011010), // 26 in binary
        .B(Encoder),
        .Y(P_RESULT[7:0])
    );

    Mux_2x1_8Bits MUX2x1_1_I (
        .MS(Bandcomp),
        .D_0(P_RESULT[7:0]),
        .D_1(Encoder),
        .D_out(P_RESULT[7:0])
    );

    ADDT_8Bits #(.P(W),.W(W)) ADDT_EXPONENTE_I (
        .A(Encoder),
        .B(8'b01100101), // 101 in binary
        .Y(FLOATOUT[30:23])
    );

    // Shift the mantissa left or right depending on the value of Bandcomp
    Barrel_Shifter #(.SWR(32),.EWR(8)) S_REG_I (
        .clk(CLK),
        .rst(RST),
        .load_i(LOAD),
        .Shift_Value_i(MS_1),
        .Shift_Data_i(mult),
        .Left_Right_i(~Bandcomp),
        .Bit_Shift_i(1'b0),
        .N_mant_o(P_RESULT)
    );

    // Combine the sign, exponent, and mantissa to form the floating-point number
    assign FLOATOUT[31] = fixed[31];
    assign FLOATOUT[22:0] = P_RESULT[25:3];

    // Store the floating-point number in a register
    FF_D #(.P(P)) REG_FLOAT (
        .CLK(CLK),
        .RST(RST),
        .EN(EN_REG2),
        .D(FLOATOUT),
        .Q(FLOATOUT)
    );

    // Output the value of the first 1 in the binary sequence
    assign Encd = Encoder[7:0];

endmodule

module vga_sync
   (
    input wire clk, reset,
    output wire hsync, vsync, video_on, p_tick,
    output wire [9:0] pixel_x, pixel_y
   );

   // constant declaration
   localparam HD = 640; // horizontal display area
   localparam HF = 48 ; // h. front (left) border
   localparam HB = 16 ; // h. back (right) border
   localparam HR = 96 ; // h. retrace
   localparam VD = 480; // vertical display area
   localparam VF = 10;  // v. front (top) border
   localparam VB = 33;  // v. back (bottom) border
   localparam VR = 2;   // v. retrace

   // mod-2 counter
   reg mod2_reg;
   wire mod2_next;
   // sync counters
   reg [9:0] h_count_reg, h_count_next;
   reg [9:0] v_count_reg, v_count_next;
   // output buffer
   reg v_sync_reg, h_sync_reg;
   wire v_sync_next, h_sync_next;
   // status signal
   wire h_end, v_end, pixel_tick;

   // mod-2 circuit to generate 25 MHz enable tick
   assign mod2_next = ~mod2_reg;
   assign pixel_tick = mod2_reg;

   // state switch
   always @(posedge clk, posedge reset)
      if (reset)
         begin
            mod2_reg <= 1'b0;
            v_count_reg <= 0;
            h_count_reg <= 0;
            v_sync_reg <= 1'b0;
            h_sync_reg <= 1'b0;
         end
      else
         begin
            mod2_reg <= mod2_next;
            v_count_reg <= v_count_next;
            h_count_reg <= h_count_next;
            v_sync_reg <= v_sync_next;
            h_sync_reg <= h_sync_next;
         end

   // status signals
   assign h_end = (h_count_reg==(HD+HF+HB+HR-1));
   assign v_end = (v_count_reg==(VD+VF+VB+VR-1));

   // next-state logic of mod-800 horizontal sync counter
   always @ (*)
      if (pixel_tick)  // 25 MHz pulse
         if (h_end)
            h_count_next = 0;
         else
            h_count_next = h_count_reg + 1;
      else
         h_count_next = h_count_reg;

   // next-state logic of mod-525 vertical sync counter
   always @ (*)
      if (pixel_tick & h_end)
         if (v_end)
            v_count_next = 0;
         else
            v_count_next = v_count_reg + 1;
      else
         v_count_next = v_count_reg;

   // horizontal and vertical sync, buffered to avoid glitch
   assign h_sync_next = (h_count_reg>=(HD+HB) &&
                         h_count_reg<=(HD+HB+HR-1));
   assign v_sync_next = (v_count_reg>=(VD+VB) &&
                         v_count_reg<=(VD+VB+VR-1));
   always @ (posedge clk)
      begin
         h_sync_reg <= h_sync_next;
         v_sync_reg <= v_sync_next;
      end

   // video on/off
   assign video_on = (h_count_reg<HD) && (v_count_reg<VD);

   // output
   assign hsync = h_sync_reg;
   assign vsync = v_sync_reg;
   assign pixel_x = h_count_reg;
   assign pixel_y = v_count_reg;
   assign p_tick = pixel_tick;

endmodule

module adder (
    input [7:0] a,
    input [7:0] b,
    output [7:0] s,
    output carry_out
);

wire [7:0] sum1, sum2;
wire carry1, carry2;

assign {carry1, sum1} = a + b;
assign {carry2, sum2} = a + ~b + 1;

assign s = carry1 ? sum2 : sum1;
assign carry_out = carry1 ^ (a[7] ^ b[7]);

endmodule

module top_module (
    input [7:0] a,
    input [7:0] b,
    output [7:0] s,
    output overflow
);

