module LIN (
  input clk,
  input reset,
  input [7:0] tx_data,
  input tx_en,
  input rx_en,
  output reg [7:0] rx_data
);

  reg [7:0] tx_crc;
  reg [7:0] rx_crc;
  reg [7:0] crc_poly = 8'h07;
  reg tx_busy, rx_busy;
  reg [3:0] bit_count;
  reg tx_bit, rx_bit;

  // Transmitter state machine
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      tx_busy <= 1'b0;
      tx_crc <= 8'h00;
      bit_count <= 4'b0;
      tx_bit <= 1'b0;
    end else if (tx_en && !tx_busy) begin
      tx_busy <= 1'b1;
      tx_crc <= 8'h00;
      bit_count <= 4'b0;
      tx_bit <= 1'b0;
    end else if (tx_busy) begin
      tx_bit <= tx_data[bit_count];
      tx_crc <= (tx_crc << 1) ^ ((tx_crc[7] ^ tx_bit) ? crc_poly : 8'h00);
      bit_count <= bit_count + 1;
      if (bit_count == 4'h8) begin
        tx_busy <= 1'b0;
      end
    end
  end

  // Receiver state machine
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      rx_busy <= 1'b0;
      rx_crc <= 8'h00;
      bit_count <= 4'b0;
      rx_bit <= 1'b0;
    end else if (rx_en && !rx_busy) begin
      rx_busy <= 1'b1;
      rx_crc <= 8'h00;
      bit_count <= 4'b0;
      rx_bit <= 1'b0;
    end else if (rx_busy) begin
      rx_bit <= rx_data[bit_count];
      rx_crc <= (rx_crc << 1) ^ ((rx_crc[7] ^ rx_bit) ? crc_poly : 8'h00);
      bit_count <= bit_count + 1;
      if (bit_count == 4'h8) begin
        if (rx_crc == 8'h00) begin
          rx_data <= rx_data;
        end else begin
          rx_data <= 8'h00;
        end
        rx_busy <= 1'b0;
      end
    end
  end

endmodule

module stage_mult
#(
  parameter DATA_WIDTH = 32,
  parameter SEL_WIDTH = 8
)
(
  input  wire clk,
  input  wire rst,
  input  wire en,
  input  wire [DATA_WIDTH-1:0] mcand_i, mplier_i, prod_i,
  output wire done_o,
  output wire [DATA_WIDTH-1:0] mcand_o, mplier_o, prod_o
);
  wire [DATA_WIDTH-1:0] partial_prod;
  reg  [DATA_WIDTH-1:0] mcand, mplier, prod;
  reg  done;

  assign partial_prod = mplier_i[SEL_WIDTH-1:0] * mcand_i;
  assign mcand_o = mcand;
  assign mplier_o = mplier;
  assign prod_o = prod;
  assign done_o = done;

  always @(posedge clk) begin
    done <= rst ? 0 : en;
