module garage_door (botao, aberto, fechado, motor, sentido, ledVerde, ledVermelho, display, clock);
    input botao, aberto, fechado, motor, sentido, clock;
    output ledVerde, ledVermelho;
    output [6:0] display;

    reg [1:0] estado;
    reg [4:0] entrada;

    reg [6:0] tmpDisplay;
    reg tmpLedVerde, tmpLedVermelho;

    parameter Fechado = 2'b00, Abrindo = 2'b01, Aberto = 2'b10, Fechando = 2'b11;

    initial estado = Fechado;

    always @(posedge clock) begin
        entrada[4] = botao;
        entrada[3] = aberto;
        entrada[2] = fechado;
        entrada[1] = motor;
        entrada[0] = sentido;

        case (estado)
            Fechado: begin
                tmpDisplay = 7'b0001110;
                tmpLedVerde = 0;
                tmpLedVermelho = 0;

                if (entrada == 5'b10110) // botao = 1 & aberto = 0 & fechado = 1 & motor = 1 & sentido = 0
                    estado = Abrindo;
            end

            Abrindo: begin
                tmpDisplay = 7'b1000000;
                tmpLedVerde = 1;
                tmpLedVermelho = 0;

                if (entrada == 5'b10010) // botao = 1 & aberto = 0 & fechado = 0 && motor = 1 & sentido = 0
                    estado = Aberto;
                if (entrada == 5'b00010) // botao = 0 & aberto = 0 & fechado = 0 & motor = 1 & sentido == 0
                    estado = Fechando;
            end

            Aberto: begin
                tmpDisplay = 7'b0001000;
                tmpLedVerde = 0;
                tmpLedVermelho = 0;

                if (entrada == 5'b01011) // botao = 0 & aberto = 1 & fechado = 0 & motor = 1 & sentido = 1
                    estado = Fechando;
            end

            Fechando: begin
                tmpDisplay = 7'b1000000;
                tmpLedVerde = 0;
                tmpLedVermelho = 1;

                if (entrada == 5'b10011) // botao = 1 & aberto = 0 & fechado = 0 & motor = 1 & sentido = 1
                    estado = Abrindo;
                if (entrada == 5'b00011) // botao = 0 & aberto = 0 & fechado = 0 & motor = 1 & sentido = 1
                    estado = Fechado;
            end

            default: estado = Fechado;

        endcase
    end

    assign display = tmpDisplay;
    assign ledVerde = tmpLedVerde;
    assign ledVermelho = tmpLedVermelho;

endmodule

module top_module (
    input CLK,
    input RST,
    input [15:0] data_in,
    input [3:0] shift_amount,
    input mode,
    output reg [4:0] count_set_bits
);

    reg [15:0] shifted_data;
    reg [31:0] shift_reg;
    reg [4:0] count;

    always @(posedge CLK or negedge RST) begin
        if (RST == 0) begin
            shifted_data <= 0;
            shift_reg <= 0;
            count <= 0;
        end else begin
            if (mode == 0) begin // logical left shift
                shifted_data <= data_in << shift_amount;
            end else if (mode == 1) begin // logical right shift
                shifted_data <= data_in >> shift_amount;
            end else if (mode == 2) begin // arithmetic right shift
                shifted_data <= $signed(data_in) >>> shift_amount;
            end else begin // rotate left
                shifted_data <= {data_in[shift_amount-1:0], data_in[15:shift_amount]};
            end

            shift_reg <= shifted_data;
            count <= {count[3:0], shift_reg[31]} + shift_reg[15] + shift_reg[14] + shift_reg[13] + shift_reg[12] + shift_reg[11] + shift_reg[10] + shift_reg[9] + shift_reg[8] + shift_reg[7] + shift_reg[6] + shift_reg[5] + shift_reg[4] + shift_reg[3] + shift_reg[2] + shift_reg[1] + shift_reg[0];
        end
    end

    assign count_set_bits = count;

endmodule

module mux_36bit
  #(parameter prio = 0)
   (input clk, input reset, input clear,
    input [35:0] data0_i, input src0_rdy_i, output dst0_rdy_o,
    input [35:0] data1_i, input src1_rdy_i, output dst1_rdy_o,
    output [35:0] data_o, output src_rdy_o, input dst_rdy_i);

   wire [35:0] 	  data0_int, data1_int;
   wire 	  src0_rdy_int, dst0_rdy_int, src1_rdy_int, dst1_rdy_int;

   fifo_short #(.WIDTH(36)) mux_fifo_in0
     (.clk(clk), .reset(reset), .clear(clear),
      .datain(data0_i), .src_rdy_i(src0_rdy_i), .dst_rdy_o(dst0_rdy_o),
      .dataout(data0_int), .src_rdy_o(src0_rdy_int), .dst_rdy_i(dst0_rdy_int));

   fifo_short #(.WIDTH(36)) mux_fifo_in1
     (.clk(clk), .reset(reset), .clear(clear),
      .datain(data1_i), .src_rdy_i(src1_rdy_i), .dst_rdy_o(dst1_rdy_o),
      .dataout(data1_int), .src_rdy_o(src1_rdy_int), .dst_rdy_i(dst1_rdy_int));

   localparam MUX_IDLE0 = 0;
   localparam MUX_DATA0 = 1;
   localparam MUX_IDLE1 = 2;
   localparam MUX_DATA1 = 3;

   reg [1:0] 	  state;

   wire 	  eof0 = data0_int[33];
   wire 	  eof1 = data1_int[33];

   wire [35:0] 	  data_int;
   wire 	  src_rdy_int, dst_rdy_int;

   always @(posedge clk)
     if(reset | clear)
       state <= MUX_IDLE0;
     else
       case(state)
	 MUX_IDLE0 :
	   if(src0_rdy_int)
	     state <= MUX_DATA0;
	   else if(src1_rdy_int)
	     state <= MUX_DATA1;

	 MUX_DATA0 :
	   if(src0_rdy_int & dst_rdy_int & eof0)
	     state <= prio ? MUX_IDLE0 : MUX_IDLE1;

	 MUX_IDLE1 :
	   if(src1_rdy_int)
	     state <= MUX_DATA1;
	   else if(src0_rdy_int)
	     state <= MUX_DATA0;

	 MUX_DATA1 :
	   if(src1_rdy_int & dst_rdy_int & eof1)
	     state <= MUX_IDLE0;

	 default :
	   state <= MUX_IDLE0;
       endcase // case (state)

   assign dst0_rdy_int = (state==MUX_DATA0) ? dst_rdy_int : 0;
   assign dst1_rdy_int = (state==MUX_DATA1) ? dst_rdy_int : 0;
   assign src_rdy_int = (state==MUX_DATA0) ? src0_rdy_int : (state==MUX_DATA1) ? src1_rdy_int : 0;
   assign data_int = (state==MUX_DATA0) ? data0_int : data1_int;

   fifo_short #(.WIDTH(36)) mux_fifo
     (.clk(clk), .reset(reset), .clear(clear),
      .datain(data_int), .src_rdy_i(src_rdy_int), .dst_rdy_o(dst_rdy_int),
      .dataout(data_o), .src_rdy_o(src_rdy_o), .dst_rdy_i(dst_rdy_i));
endmodule

module fifo_short
  #(parameter WIDTH = 8, DEPTH = 16)
   (input clk, input reset, input clear,
    input [WIDTH-1:0] datain, input src_rdy_i, output dst_rdy_o,
    output [WIDTH-1:0] dataout, output src_rdy_o, input dst_rdy_i);

   reg [WIDTH-1:0] fifo [DEPTH-1:0];
   reg [DEPTH-1:0] rd_ptr, wr_ptr;
   wire empty = (rd_ptr == wr_ptr) & !src_rdy_i;
   wire full = (wr_ptr == (rd_ptr - 1)) | !dst_rdy_i;

   assign src_rdy_o = !full;
   assign dst_rdy_o = !empty;

   always @(posedge clk)
     if(reset)
       begin
	 rd_ptr <= 0;
	 wr_ptr <= 0;
       end
     else if(clear)
       begin
	 rd_ptr <= wr_ptr;
       end
     else
       begin
	 if(src_rdy_i & !full)
	   begin
	     fifo[wr_ptr] <= datain;
	     wr_ptr <= (wr_ptr == (DEPTH-1)) ? 0 : wr_ptr + 1;
	   end
	 if(dst_rdy_i & !empty)
	   begin
	     dataout <= fifo[rd_ptr];
	     rd_ptr <= (rd_ptr == (DEPTH-1)) ? 0 : rd_ptr + 1;
	   end
       end
endmodule

module shift_register (
  input clk,
  input reset,
  input load,
  input [5:0] data,
  output [5:0] q
);

