module Exp_Operation_m_EW8 ( clk, rst, load_a_i, load_b_i, load_c_i, Data_A_i, 
        Data_B_i, Add_Subt_i, Data_Result_o, Overflow_flag_o, Underflow_flag_o
 );
  input [8:0] Data_A_i;
  input [8:0] Data_B_i;
  output [8:0] Data_Result_o;
  input clk, rst, load_a_i, load_b_i, load_c_i, Add_Subt_i;
  output Overflow_flag_o, Underflow_flag_o;
  reg [8:0] A, B, C;
  wire [9:0] Data_S;
  wire Overflow_A, Overflow_flag_A, Underflow_A, Underflow_flag_A;

  // Load input data into register A
  always @(posedge clk) begin
    if (rst) begin
      A <= 9'b0;
    end else if (load_a_i) begin
      A <= Data_A_i;
    end
  end

  // Load input data into register B
  always @(posedge clk) begin
    if (rst) begin
      B <= 9'b0;
    end else if (load_b_i) begin
      B <= Data_B_i;
    end
  end

  // Load input data or result into register C
  always @(posedge clk) begin
    if (rst) begin
      C <= 9'b0;
    end else if (load_c_i) begin
      C <= Data_Result_o;
    end
  end

  // Perform addition or subtraction and store result in register C
  always @(posedge clk) begin
    if (rst) begin
      C <= 9'b0;
    end else if (Add_Subt_i) begin
      C <= A + B;
    end else begin
      C <= A - B;
    end
  end

  // Check for overflow
  assign Overflow_A = (A[8] == 1 && B[8] == 1 && C[8] == 0) || (A[8] == 0 && B[8] == 0 && C[8] == 1);
  always @(posedge clk) begin
    if (rst) begin
      Overflow_flag_A <= 1'b0;
    end else if (load_b_i) begin
      Overflow_flag_A <= Overflow_A;
    end
  end

  // Check for underflow
  assign Underflow_A = (A[8] == 0 && B[8] == 1 && C[8] == 1) || (A[8] == 1 && B[8] == 0 && C[8] == 0);
  always @(posedge clk) begin
    if (rst) begin
      Underflow_flag_A <= 1'b0;
    end else if (load_a_i) begin
      Underflow_flag_A <= Underflow_A;
    end
  end

  // Set overflow flag if result is greater than 511
  assign Overflow_flag_o = (C > 511) ? 1'b1 : Overflow_flag_A;

  // Set underflow flag if result is less than 0
  assign Underflow_flag_o = (C < 0) ? 1'b1 : Underflow_flag_A;

  // Output result
  assign Data_Result_o = C;
endmodule

