module priority_encoder_d_ff (
    input clk,
    input reset,       // Synchronous active-high reset
    input [7:0] in,    // 8-bit input for the priority encoder
    output reg [2:0] pe_out,  // 3-bit output from the priority encoder
    output reg q       // Output from the D flip-flop delayed by one clock cycle
);

// Priority Encoder
assign pe_out = ~{in[7], in[6], in[5], in[4], in[3], in[2], in[1], in[0]} + 1'b1;

always @(posedge clk) begin
    if (reset) begin
        pe_out <= 3'b000;
        q <= 1'b0;
    end
    else begin
        q <= pe_out;
    end
end

// D Flip-Flop
reg d;
always @(posedge clk) begin
    if (reset) begin
        d <= 1'b0;
    end
    else begin
        d <= q;
    end
end

always @(posedge clk) begin
    if (reset) begin
        q <= 1'b0;
    end
    else begin
        q <= d;
    end
end

endmodule

module top_module (
    input clk,
    input reset,   // Synchronous active-high reset
    input pause,   // Control signal to pause or resume the counting process
    input up_down, // Control signal to select counting direction
    output [15:0] q);

    reg [3:0] digit0, digit1, digit2, digit3;
    reg [1:0] direction;
    reg [1:0] count_enable;

    // Counter logic for each digit
    always @(posedge clk) begin
        if (reset) begin
            digit0 <= 4'b0000;
            digit1 <= 4'b0000;
            digit2 <= 4'b0000;
            digit3 <= 4'b0000;
        end
        else if (pause) begin
            // Do nothing
        end
        else if (count_enable == 2'b01) begin
            if (direction == 2'b00) begin
                // Count up
                if (digit0 == 4'b1001) begin
                    digit0 <= 4'b0000;
                    if (digit1 == 4'b1001) begin
                        digit1 <= 4'b0000;
                        if (digit2 == 4'b1001) begin
                            digit2 <= 4'b0000;
                            if (digit3 == 4'b1001) begin
                                digit3 <= 4'b0000;
                            end
                            else begin
                                digit3 <= digit3 + 1;
                            end
                        end
                        else begin
                            digit2 <= digit2 + 1;
                        end
                    end
                    else begin
                        digit1 <= digit1 + 1;
                    end
                end
                else begin
                    digit0 <= digit0 + 1;
                end
            end
            else begin
                // Count down
                if (digit0 == 4'b0000) begin
                    digit0 <= 4'b1001;
                    if (digit1 == 4'b0000) begin
                        digit1 <= 4'b1001;
                        if (digit2 == 4'b0000) begin
                            digit2 <= 4'b1001;
                            if (digit3 == 4'b0000) begin
                                digit3 <= 4'b1001;
                            end
                            else begin
                                digit3 <= digit3 - 1;
                            end
                        end
                        else begin
                            digit2 <= digit2 - 1;
                        end
                    end
                    else begin
                        digit1 <= digit1 - 1;
                    end
                end
                else begin
                    digit0 <= digit0 - 1;
                end
            end
        end
    end

    // Control logic for counting direction and enable
    always @(posedge clk) begin
        if (reset) begin
            direction <= 2'b00;
            count_enable <= 2'b00;
        end
        else if (pause) begin
            // Do nothing
        end
        else begin
            if (up_down == 1'b1) begin
                // Count down
                direction <= 2'b01;
            end
            else begin
                // Count up
                direction <= 2'b00;
            end

            if (count_enable == 2'b00 && pause == 1'b0) begin
                count_enable <= 2'b01;
            end
            else if (count_enable == 2'b01 && pause == 1'b1) begin
                count_enable <= 2'b00;
            end
        end
    end

    // Output logic
    assign q = {digit3, digit2, digit1, digit0};

endmodule

