input aclr;
input [31:0] data;
input rdclk;
input rdreq;
input wrclk;
input wrreq;
output [31:0] q;
output rdempty;
output wrfull;

reg [31:0] fifo_mem [511:0];
reg [8:0] read_ptr;
reg [8:0] write_ptr;
wire [8:0] next_write_ptr;
wire [8:0] next_read_ptr;
wire [8:0] num_entries;
wire [8:0] next_num_entries;

assign next_write_ptr = write_ptr + 1;
assign next_read_ptr = read_ptr + 1;
assign num_entries = write_ptr - read_ptr;
assign next_num_entries = next_write_ptr - read_ptr;

assign q = fifo_mem[read_ptr];
assign rdempty = (num_entries == 0);
assign wrfull = (next_num_entries == 512);

always @(posedge rdclk) begin
    if (rdreq && !rdempty) begin
        read_ptr <= next_read_ptr;
    end
end

always @(posedge wrclk) begin
    if (wrreq && !wrfull) begin
        fifo_mem[write_ptr] <= data;
        write_ptr <= next_write_ptr;
    end
end

always @(posedge aclr) begin
    if (aclr) begin
        read_ptr <= 0;
        write_ptr <= 0;
    end
end

endmodule

module top_module (
    input clk,
    input RST,
    input enable,
    input [3:0] B,
    input subtract,
    output [3:0] result
);

    reg [3:0] counter;
    wire [3:0] adder_input;
    wire [3:0] adder_output;

    // Instantiate the binary counter module
    binary_counter counter_inst (
        .clk(clk),
        .RST(RST),
        .enable(enable),
        .Q(counter)
    );

    // Create the adder/subtractor input by selecting between the counter and B
    assign adder_input = (subtract) ? (counter - B) : (counter + B);

    // Instantiate the adder/subtractor module
    adder_subtractor adder_inst (
        .A(adder_input),
        .B(4'b0001),
        .subtract(subtract),
        .result(adder_output)
    );

    // Output the final result
    assign result = adder_output;

endmodule

// Binary counter module
module binary_counter (
    input clk,
    input RST,
    input enable,
    output reg [3:0] Q
);
    always @(posedge clk, negedge RST) begin
        if (RST == 0) begin
            Q <= 4'b0000;
        end else if (enable) begin
            Q <= Q + 1;
        end
    end
endmodule

// Adder/subtractor module
module adder_subtractor (
    input [3:0] A,
    input [3:0] B,
    input subtract,
    output reg [3:0] result
);
    always @(*) begin
        if (subtract) begin
            result = A - B;
        end else begin
            result = A + B;
        end
    end
endmodule

module clock_divider(
