    input CIN,
    input SUB,
    output reg [7:0] SUM,
    output reg OVF
);

reg [7:0] A_reg, B_reg, SUM_reg;
reg CIN_reg, SUB_reg;
reg [8:0] SUM_temp;
reg OVF_reg;

always @ (posedge clk) begin
    A_reg <= A;
    B_reg <= B;
    CIN_reg <= CIN;
    SUB_reg <= SUB;
end

always @ (posedge clk) begin
    if (SUB_reg) begin
        SUM_temp <= A_reg - B_reg - CIN_reg;
    end else begin
        SUM_temp <= A_reg + B_reg + CIN_reg;
    end
end

always @ (posedge clk) begin
    SUM_reg <= SUM_temp[7:0];
    OVF_reg <= SUM_temp[8];
end

assign SUM = SUM_reg;
assign OVF = OVF_reg;

endmodule

module four_digit_7seg(
    input wire [31:0] disp_num,
    input wire clk,
    input wire clr,
    input wire [1:0] SW,
    output wire [7:0] SEGMENT,
    output wire [3:0] AN
);

    wire [3:0] an_sel;
    wire [6:0] seg_sel;
    wire dp_sel;

    reg [31:0] number;

    assign an_sel = 4'b1110;
    assign seg_sel = 7'b1000000;
    assign dp_sel = 1'b0;

    initial number <= 0;

    always @(posedge clk) begin
        if (clr) begin
            number <= 0;
        end else begin
            case (SW)
                2'b01: number <= {16'b0, disp_num[15:0]};
                2'b11: number <= {16'b0, disp_num[31:16]};
                default: number <= disp_num;
            endcase
        end
    end

    assign AN = an_sel;

    display D0(clk, clr, dp_sel, number[3:0], SEGMENT, seg_sel);
    display D1(clk, clr, dp_sel, number[7:4], SEGMENT, seg_sel);
    display D2(clk, clr, dp_sel, number[11:8], SEGMENT, seg_sel);
    display D3(clk, clr, dp_sel, number[15:12], SEGMENT, seg_sel);

endmodule

module display(
    input wire clk,
    input wire clr,
    input wire DP,
    input wire [3:0] number,
    output wire [6:0] SEGMENT,
    output wire [6:0] AN
);

    reg [2:0] count;

    always @(posedge clk) begin
        if (clr) begin
            count <= 0;
        end else begin
            count <= count + 1;
        end
    end

    always @(count) begin
        case (count)
            3'd0: begin SEGMENT = 7'b1000000; AN = 4'b1110; end
            3'd1: begin
                case (number)
                    4'b0000: SEGMENT = 7'b1111110;
                    4'b0001: SEGMENT = 7'b0110000;
                    4'b0010: SEGMENT = 7'b1101101;
                    4'b0011: SEGMENT = 7'b1111001;
                    4'b0100: SEGMENT = 7'b0110011;
                    4'b0101: SEGMENT = 7'b1011011;
                    4'b0110: SEGMENT = 7'b1011111;
                    4'b0111: SEGMENT = 7'b1110000;
                    4'b1000: SEGMENT = 7'b1111111;
                    4'b1001: SEGMENT = 7'b1111011;
                    default: SEGMENT = 7'b0000000;
                endcase
                AN = 4'b1101;
            end
            3'd2: begin
                if (DP) begin
                    SEGMENT = 7'b1111110;
                end else begin
                    SEGMENT = 7'b0000000;
                end
                AN = 4'b1011;
            end
            3'd3: begin SEGMENT = 7'b0000000; AN = 4'b0111; end
            default: begin SEGMENT = 7'b0000000; AN = 4'b1111; end
        endcase
    end

endmodule

