module accumulator (
    input clk,
    input rst_n,
    input [7:0] in,
    input valid_in,
    output reg [9:0] out,
    output reg valid_out,
    input ready_out
);
    reg [9:0] sum;
    reg [7:0] prev_in;
    reg [1:0] stage;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            sum <= 10'b0;
            prev_in <= 8'b0;
            stage <= 2'b00;
            valid_out <= 1'b0;
        end
        else begin
            case (stage)
                2'b00: begin
                    prev_in <= in;
                    stage <= 2'b01;
                end
                2'b01: begin
                    sum <= prev_in + in;
                    stage <= 2'b10;
                end
                2'b10: begin
                    if (valid_in) begin
                        valid_out <= 1'b1;
                        out <= sum;
                        stage <= 2'b00;
                    end
                    else begin
                        valid_out <= 1'b0;
                        stage <= 2'b01;
                    end
