module top_module (
    input clk,
    input rst_n,
    input [7:0] in,
    output [7:0] anyedge,
    output reg valid_b,
    output reg [9:0] data_out,
    input [7:0] accum_in,
    input valid_a,
    input ready_b,
    output reg ready_a
);
    wire [7:0] edge_out;
    wire [9:0] accum_out;
    wire or_valid_out;
    wire [7:0] or_out;

    edge_detector edge_detector_inst (
        .clk(clk),
        .rst_n(rst_n),
        .in(in),
        .out(edge_out)
    );

    accumulator accumulator_inst (
        .clk(clk),
        .rst_n(rst_n),
        .in(accum_in),
        .valid_in(valid_a),
        .out(accum_out),
        .valid_out(valid_b),
        .ready_out(ready_b)
    );

    or_gate or_gate_inst (
        .in1(edge_out),
        .in2(accum_out[7:0]),
        .out(or_out),
        .valid_out(or_valid_out),
        .ready_out(1'b1)
    );

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            valid_b <= 1'b0;
            data_out <= 10'b0;
            ready_a <= 1'b0;
        end
        else begin
            if (or_valid_out && valid_b && ready_a) begin
                data_out <= accum_out;
                ready_a <= 1'b0;
            end
            else if (valid_b && ready_a) begin
                data_out <= or_out;
                ready_a <= 1'b0;
            end
            else if (or_valid_out && valid_b) begin
                data_out <= accum_out;
                ready_a <= 1'b1;
            end
            else if (valid_b) begin
                data_out <= or_out;
                ready_a <= 1'b1;
            end
            else begin
                data_out <= 10'b0;
                ready_a <= 1'b0;
