module sqrt_calculator(
  input [31:0] num_in,
  output reg [15:0] sqrt_out
);

  reg [31:0] temp;
  reg [15:0] sqrt_temp;
  reg [4:0] i;

  always @(*) begin
    temp = {16'b0, num_in};
    sqrt_temp = 16'b0;

    for (i = 15; i >= 0; i = i - 1) begin
      temp[i+16] = sqrt_temp;
      sqrt_temp = sqrt_temp << 1;
      sqrt_temp[i] = 1'b1;

      if (temp >= sqrt_temp*sqrt_temp) begin
        sqrt_out[i] = 1'b1;
      end else begin
        sqrt_out[i] = 1'b0;
        sqrt_temp = sqrt_temp - (1 << i);
      end
    end
  end

endmodule

