  output signed [15:0] out
);

  localparam MIN_VAL = -32768;
  localparam MAX_VAL = 32767;

  reg signed [15:0] temp;
  reg signed [15:0] rounded;

  always @(*) begin
    temp = in + 0.5;
    rounded = $floor(temp);
    rounded = rounded - 0.5;
    if (rounded > MAX_VAL) begin
      out = MAX_VAL;
    end else if (rounded < MIN_VAL) begin
      out = MIN_VAL;
    end else begin
      out = rounded;
    end
  end

