module priorityEncoder(in, ei, out, gs, eo);
    input [0:7]in;
    input ei;
    output [0:2]out;
    output gs;
    output eo;
    wire [0:7] and_out;
    wire [0:2] priority;
    wire highest_priority;

    // AND gates
    assign and_out[0] = ~in[1] & in[2] & in[4] & in[6] & ~ei;
    assign and_out[1] = ~in[3] & in[4] & in[6] & ~ei;
    assign and_out[2] = ~in[5] & in[6] & ~ei;
    assign and_out[3] = ~in[7] & ~ei;
    assign and_out[4] = ~in[2] & in[4] & in[5] & ~ei;
    assign and_out[5] = ~in[3] & in[4] & in[5] & ~ei;
    assign and_out[6] = ~in[6] & ~ei;
    assign and_out[7] = ~in[7] & ~ei;
    assign and_out[8] = ~in[4] & ~ei;
    assign and_out[9] = ~in[5] & ~ei;
    assign and_out[10] = ~in[6] & ~ei;
    assign and_out[11] = ~in[7] & ~ei;

    // Priority encoding
    assign priority[0] = and_out[3] ? 2'b11 :
                         and_out[2] ? 2'b10 :
                         and_out[1] ? 2'b01 :
                         and_out[0] ? 2'b00 : 2'b00;
    assign priority[1] = and_out[7] ? 2'b11 :
                         and_out[6] ? 2'b10 :
                         and_out[5] ? 2'b01 :
                         and_out[4] ? 2'b00 : 2'b00;
    assign priority[2] = and_out[11] ? 2'b11 :
                         and_out[10] ? 2'b10 :
                         and_out[9] ? 2'b01 :
                         and_out[8] ? 2'b00 : 2'b00;

    // Highest priority bit
    assign highest_priority = in[priority[0]+priority[1]+priority[2]] ? 1'b1 : 1'b0;

    // NOR gates
    assign out[0] = ~(and_out[0] | and_out[1] | and_out[2] | and_out[3] | highest_priority);
    assign out[1] = ~(and_out[4] | and_out[5] | and_out[6] | and_out[7] | highest_priority);
    assign out[2] = ~(and_out[8] | and_out[9] | and_out[10] | and_out[11] | highest_priority);

    // NAND gates
    assign eo = ~(in[0] & in[1] & in[2] & in[3] & in[4] & in[5] & in[6] & in[7] & ~ei);
    assign gs = ~(eo & ~ei);
endmodule

module etx_protocol (
   // Outputs
   etx_rd_wait, etx_wr_wait, etx_ack, tx_frame_par, tx_data_par,
   ecfg_tx_datain,
   // Inputs
   reset, etx_access, etx_write, etx_datamode, etx_ctrlmode,
   etx_dstaddr, etx_srcaddr, etx_data, tx_lclk_par, tx_rd_wait,
   tx_wr_wait
);

   // System reset input
   input         reset;

   // Input from TX Arbiter
   input         etx_access;
   input         etx_write;
   input [1:0]   etx_datamode;
   input [3:0]   etx_ctrlmode;
   input [31:0]  etx_dstaddr;
   input [31:0]  etx_srcaddr;
   input [31:0]  etx_data;
   output        etx_rd_wait;
   output        etx_wr_wait;
   output        etx_ack;

   // Parallel interface, 8 eLink bytes at a time
   input         tx_lclk_par; // Parallel-rate clock from eClock block
   output [7:0]  tx_frame_par;
   output [63:0] tx_data_par;
   input         tx_rd_wait;  // The wait signals are passed through
   input         tx_wr_wait;  // to the emesh interfaces

   //Debug/gpio signals
   output [1:0]  ecfg_tx_datain; // {wr_wait, rd_wait}

   //############
   //# Local regs & wires
   //############
   reg           etx_ack;  // Acknowledge transaction
   reg [7:0]     tx_frame_par;
   reg [63:0]    tx_data_par;

   //############
   //# Logic
   //############

   always @( posedge tx_lclk_par or posedge reset ) 
   begin
      if(reset) 
      begin	     
         etx_ack          <= 1'b0;
         tx_frame_par[7:0] <= 8'd0;
         tx_data_par[63:0] <= 64'd0;	     
      end 
      else 
      begin
         if( etx_access & ~etx_ack ) 
         begin
            etx_ack  <= 1'b1;
            tx_frame_par[7:0] <= 8'h3F;
            tx_data_par[63:0]  <= {8'd0,  // Not used
                                    8'd0,
                                    ~etx_write, 7'd0, // B0-TODO: For bursts, add the inc bit
                                    etx_ctrlmode[3:0], etx_dstaddr[31:28], // B1
                                    etx_dstaddr[27:4],  // B2, B3, B4
                                    etx_dstaddr[3:0], etx_datamode[1:0], etx_write, etx_access // B5
                                 };
         end 
         else if( etx_ack ) 
         begin
            etx_ack  <= 1'b0;
            tx_frame_par[7:0] <= 8'hFF;
            tx_data_par[63:0]  <= { etx_data[31:0], etx_srcaddr[31:0]};   
         end 
         else 
         begin
            etx_ack    <= 1'b0;
            tx_frame_par[7:0] <= 8'h00;
            tx_data_par[63:0]  <= 64'd0;
         end
      end // else: !if(reset)	
   end // always @ ( posedge txlclk_p or posedge reset )


   //#############################
   //# Wait signals
   //#############################

   reg     rd_wait_sync;
   reg     wr_wait_sync;
   reg     etx_rd_wait;
   reg     etx_wr_wait;

   always @ (posedge tx_lclk_par) 
   begin
      rd_wait_sync <= tx_rd_wait;
      etx_rd_wait <= rd_wait_sync;
      wr_wait_sync <= tx_wr_wait;
      etx_wr_wait <= wr_wait_sync;
   end

   assign ecfg_tx_datain[1:0] = {etx_wr_wait, etx_rd_wait};

endmodule

