module clock_generator (
  input [n-1:0] ctrl,
  output clk
);

parameter n = 4; // number of control signals
parameter fmax = 1000000; // maximum frequency of the clock signal
parameter duty = 50; // duty cycle of the clock signal (in percent)

reg clk_reg;
wire clk_int;

assign clk = clk_int;

always @(posedge clk_int) begin
  clk_reg <= ~clk_reg;
end

reg [n-1:0] counter;
reg [31:0] divider;

always @(posedge clk_int) begin
  if (counter == 0) begin
    divider <= fmax / (ctrl + 1);
    counter <= ctrl;
  end else begin
    counter <= counter - 1;
  end
end

assign clk_int = (divider >> 1) & counter ? 1'b1 : 1'b0;

endmodule

