module uart_transceiver(
	input sys_rst,
	input sys_clk,

	input uart_rxd,
	output reg uart_txd,

	input [15:0] divisor,

	output reg [7:0] rx_data,
	output reg rx_done,

	input [7:0] tx_data,
	input tx_wr,
	output reg tx_done
);

// Define constants
localparam DATA_BITS = 8;
localparam START_BIT = 0;
localparam STOP_BIT = DATA_BITS + 1;

// Define state machine states
localparam IDLE = 2'b00;
localparam START_BIT_DETECT = 2'b01;
localparam DATA_BITS_RECEIVE = 2'b10;
localparam STOP_BIT_VERIFY = 2'b11;

// Define state machine signals
reg [1:0] state;
reg [3:0] bit_count;
reg [7:0] shift_reg;
reg [15:0] rx_counter;
reg [15:0] tx_counter;

// Define enable signal
wire enable;
assign enable = (rx_counter == 0);

// Define state machine
always @(posedge sys_clk) begin
	if (sys_rst) begin
		state <= IDLE;
		bit_count <= 0;
		shift_reg <= 0;
		rx_counter <= divisor;
		tx_counter <= divisor;
		rx_done <= 0;
		tx_done <= 0;
	end else begin
		case (state)
			IDLE: begin
				if (~uart_rxd) begin
					state <= START_BIT_DETECT;
					bit_count <= 0;
					shift_reg <= 0;
				end
			end
			START_BIT_DETECT: begin
				if (enable) begin
					shift_reg[DATA_BITS - 1:0] <= shift_reg[DATA_BITS:1];
					shift_reg[DATA_BITS] <= uart_rxd;
					bit_count <= bit_count + 1;
					if (bit_count == DATA_BITS) begin
						state <= STOP_BIT_VERIFY;
						bit_count <= 0;
					end
				end
			end
			DATA_BITS_RECEIVE: begin
				if (enable) begin
					shift_reg[DATA_BITS - 1:0] <= shift_reg[DATA_BITS:1];
					shift_reg[DATA_BITS] <= uart_rxd;
					bit_count <= bit_count + 1;
					if (bit_count == STOP_BIT) begin
						state <= IDLE;
						bit_count <= 0;
						rx_data <= shift_reg[DATA_BITS - 1:0];
						rx_done <= 1;
					end
				end
			end
			STOP_BIT_VERIFY: begin
				if (enable) begin
					if (uart_rxd) begin
						state <= DATA_BITS_RECEIVE;
					end else begin
						state <= IDLE;
						bit_count <= 0;
					end
				end
			end
		endcase

		if (tx_wr && enable) begin
			if (tx_counter == 0) begin
				uart_txd <= 0;
				tx_counter <= divisor;
				state <= START_BIT_DETECT;
				bit_count <= 0;
				shift_reg <= {START_BIT, tx_data, 0};
			end else begin
				uart_txd <= shift_reg[0];
				tx_counter <= tx_counter - 1;
				shift_reg <= {shift_reg[DATA_BITS + 1:0], 0};
			end
		end else begin
			uart_txd <= 1;
			tx_counter <= divisor;
		end
	end
end

// Define enable16 generator
reg [15:0] enable16_counter;

always @(posedge sys_clk) begin
	if (sys_rst) begin
		enable16_counter <= divisor - 1;
	end else begin
		enable16_counter <= enable16_counter - 1;
		if (enable16_counter == 0) begin
			enable16_counter <= divisor - 1;
			rx_counter <= divisor;
			tx_counter <= divisor;
		end
	end
end

// Define tx_done signal
always @(posedge sys_clk) begin
	if (sys_rst) begin
		tx_done <= 0;
	end else begin
		if (state == IDLE && tx_counter == divisor) begin
			tx_done <= 1;
		end else begin
			tx_done <= 0;
		end
	end
end

endmodule

