    full_adder FA0(
        .a(A[0]),
        .b(B[0]),
        .c_in(1'b0),
        .sum(sum[0]),
        .c_out(carry[0])
    );

    // remaining full adders
    generate
        genvar i;
        for (i = 1; i < 8; i = i + 1) begin : FA_GEN
            full_adder FA(
                .a(A[i]),
                .b(B[i]),
                .c_in(carry[i-1]),
