module debouncer(
   clk,
   reset_,
   raw,
   debounced);

   input      clk;
   input      reset_;
   input      raw;
   output     debounced;

   // This circuit debounces a raw input. That is, it "ignores" brief changes
   // to the raw signal and outputs a steady value that cannot change more often
   // than once per 256 clock cycles.

   reg [7:0]  counter;      // 256 clock cycle counter
   reg 	      debounced;    // Debounced (steady) output
   reg 	      sampled;      // Raw input sampled by clock

   // "Clock in" the  raw input
   always@ (posedge clk or negedge reset_)
     if (!reset_)
       sampled <= 1'b0;
     else
       sampled <= raw;

   // Count the number of cycles the sampled input is steady
   always@ (posedge clk or negedge reset_)
     if (!reset_)
       counter <= 8'd0;
     else if (raw != sampled)
       counter <= 8'd0;
     else
       counter <= counter + 8'd1;

   // When the counter reaches its saturated state, output the sampled value
   always@ (posedge clk or negedge reset_)
     if (!reset_)
       debounced <= 1'b0;
     else if (counter == 8'hff)
       debounced <= sampled;
     else
       debounced <= debounced;

endmodule

module vga_noise(clk, color, pause, vsync, hsync, style, test, audio_l, audio_r);

input clk;
output [7:0] color;
input pause;
input vsync, hsync;
input style;
input test;
output audio_l, audio_r;

reg [1:0] audio_data;

reg [7:0] latch;
reg [7:0] sr;

reg [12:0] divider;

wire noise_bit;

// LFSR noise generator
noise_generator gen (
    .clk(clk),
    .reset(pause&vsync),
    .random_bit(noise_bit)
);

// handy line-synchronised counter
always @(negedge clk) begin
    if(hsync) divider <= 0;
    else divider <= divider + 1;
end

// divider[2] is a clock at pixel frequency
always @(posedge divider[2]) begin
    latch <= sr;
end

// audio noise can be at a much lower rate
always @(posedge divider[12]) begin
    if(!test && !pause) audio_data <= sr[1:0];
end

always @(posedge clk) begin
    if(style) begin
        // colored noise
        if(test) sr <= {divider[9],divider[9],divider[9],divider[8],divider[8],divider[8],divider[7],divider[7]};
        else begin
            sr[7:1] <= sr[6:0];
            sr[0] <= noise_bit;
        end
    end
    else begin
        // monochrome noise
        if(test) sr <= {divider[5],divider[5],divider[5],divider[5],divider[5],divider[5],divider[5],divider[5]};
        else sr <= {noise_bit,noise_bit,noise_bit,noise_bit,noise_bit,noise_bit,noise_bit,noise_bit};
    end
end

assign color = latch;

// stereo noise!
assign audio_l = audio_data[0];
assign audio_r = audio_data[1];

endmodule

