module noise_generator(clk, reset, random_bit);

input clk, reset;
output reg random_bit;

reg [15:0] shift_register;

always @(posedge clk, posedge reset) begin
    if(reset) shift_register <= 16'h1;
    else shift_register <= {shift_register[0]^shift_register[2]^shift_register[3]^shift_register[5], shift_register[15:1]};
    random_bit <= shift_register[0];
end

endmodule

