module memory(clk, mem_read, mem_write, address, data_in, data_out);
  input  clk, mem_read, mem_write;
  input  [31:0] address, data_in;
  output [31:0] data_out;
  reg    [31:0] data_out;

  parameter BASE_ADDRESS = 25'd0; // address that applies to this memory - change if desired

  reg [31:0] mem_array [0:31];
  wire [4:0] mem_offset;
  wire address_select;

  assign mem_offset = address[6:2];  // drop 2 LSBs to get word offset

  assign address_select = (address[31:7] == BASE_ADDRESS);  // address decoding

  always @(mem_read or address_select or mem_offset or mem_array[mem_offset])
  begin

    if (mem_read == 1'b1 && address_select == 1'b1)
    begin
      if ((address % 4) != 0)
          $display($time, " memory error: unaligned address %d", address);
      data_out = mem_array[mem_offset];
      $display($time, " reading data: Mem[%h] => %h", address, data_out);
    end
      else data_out = 32'hxxxxxxxx;
  end

  // for WRITE operations
  always @(posedge clk)
  begin
    if (mem_write == 1'b1 && address_select == 1'b1)
    begin
      $display($time, " writing data: Mem[%h] <= %h", address,data_in);
      mem_array[mem_offset] <= data_in;
    end
  end

  // initialize with some arbitrary values

  integer i;
  initial begin
    for (i=0; i<32; i=i+1) mem_array[i] = i*4;
  end
endmodule

module CAN (
  input [7:0] data_in,
  input [10:0] id_in,
  input tx_req,
  input clk,
  output tx,
  output tx_ack,
  input rx,
  output [10:0] id_out,
  output [7:0] data_out
);

  // Define CAN protocol and message format
  parameter CAN_BITRATE = 125000; // 125 kbps
  parameter CAN_MSG_SIZE = 11; // 11-bit identifier
  parameter CAN_DATA_SIZE = 8; // 8-bit data

  // Define internal signals
  reg [CAN_MSG_SIZE-1:0] tx_id;
  reg [CAN_DATA_SIZE-1:0] tx_data;
  reg tx_valid;
  reg tx_busy;
  reg [CAN_MSG_SIZE-1:0] rx_id;
  reg [CAN_DATA_SIZE-1:0] rx_data;
  reg rx_valid;

  // Define transmitter block
  always @(posedge clk) begin
    if (tx_req && !tx_busy) begin
      tx_id <= id_in;
      tx_data <= data_in;
      tx_valid <= 1;
      tx_busy <= 1;
    end else if (tx_valid) begin
      tx <= 1;
      tx_ack <= 0;
      tx_valid <= 0;
      tx_busy <= 0;
    end else begin
      tx <= 0;
      tx_ack <= 1;
    end
  end

  // Define receiver block
  always @(posedge clk) begin
    if (rx) begin
      rx_id <= id_out;
      rx_data <= data_out;
      rx_valid <= 1;
    end else begin
      rx_valid <= 0;
    end
  end

  // Connect inputs and outputs to transmitter and receiver blocks
  assign id_out = rx_id;
  assign data_out = rx_data;
  assign tx = tx_valid;
  assign tx_ack = tx_busy;

endmodule

