module top_module (
    input [3:0] in_0, // First operand input
    input [3:0] in_1, // Second operand input
    output reg [1:0] out // Comparison result output
);

    wire [3:0] sum; // Binary addition result
    wire carry; // Carry output from full adder

    // Instantiate four full adder modules for 4-bit binary addition
    full_adder fa0(.a(in_0[0]), .b(in_1[0]), .c(1'b0), .sum(sum[0]), .carry(carry));
    full_adder fa1(.a(in_0[1]), .b(in_1[1]), .c(carry), .sum(sum[1]), .carry(carry));
    full_adder fa2(.a(in_0[2]), .b(in_1[2]), .c(carry), .sum(sum[2]), .carry(carry));
    full_adder fa3(.a(in_0[3]), .b(in_1[3]), .c(carry), .sum(sum[3]), .carry(carry));

    // Instantiate comparator module for 2-bit comparison
    comparator comp(.a(sum[3:2]), .b(sum[1:0]), .out(out));

    always @(*) begin
        // Determine output based on comparison result
        if (out == 2'b10) begin
            out = 2'b01;
        end else if (out == 2'b01) begin
            out = 2'b00;
        end else begin
            out = 2'b10;
        end
    end

endmodule

