module carry_select_adder (
    input wire [15:0] in1,
    input wire [15:0] in2,
    input wire cin,
    output wire [15:0] sum,
    output wire cout
);

wire [15:0] p, g, c1, c2;

assign p = in1 ^ in2;
assign g = in1 & in2;
assign c1 = {cin, 16'b0} + {~p, p} + {16'b1, 16'b0};
assign c2 = {cin, 16'b0} + {~g, g} + {16'b0, 16'b1};

assign sum = c1[15:0] ^ c2[15:0];
assign cout = c1[16] | c2[16];

endmodule

