module vending_machine (
    input A,
    input B,
    input C,
    input five_cents,
    input ten_cents,
    input twentyfive_cents,
    output X_dispense,
    output Y_dispense,
    output Z_dispense,
    output five_cents_return,
    output ten_cents_return,
    output twentyfive_cents_return
);

    reg [7:0] total_inserted;
    reg [7:0] price_X = 25;
    reg [7:0] price_Y = 50;
    reg [7:0] price_Z = 75;
    reg [7:0] change;

    always @(*) begin
        X_dispense = 0;
        Y_dispense = 0;
        Z_dispense = 0;
        five_cents_return = 0;
        ten_cents_return = 0;
        twentyfive_cents_return = 0;

        if (A && total_inserted >= price_X) begin
            X_dispense = 1;
            change = total_inserted - price_X;
        end else if (B && total_inserted >= price_Y) begin
            Y_dispense = 1;
            change = total_inserted - price_Y;
        end else if (C && total_inserted >= price_Z) begin
            Z_dispense = 1;
            change = total_inserted - price_Z;
        end else begin
            change = total_inserted;
        end

        if (change >= 25) begin
            twentyfive_cents_return = 1;
            change = change - 25;
        end
        if (change >= 10) begin
            ten_cents_return = 1;
            change = change - 10;
        end
        if (change >= 5) begin
            five_cents_return = 1;
            change = change - 5;
        end
    end

    always @(posedge five_cents or posedge ten_cents or posedge twentyfive_cents) begin
        if (five_cents) begin
            total_inserted = total_inserted + 5;
        end
        if (ten_cents) begin
            total_inserted = total_inserted + 10;
        end
        if (twentyfive_cents) begin
            total_inserted = total_inserted + 25;
        end
    end

endmodule

