    input [7:0] data3, // 8-bit input for multiplexer 
    input [7:0] data4, // 8-bit input for multiplexer 
    input [7:0] data5, // 8-bit input for multiplexer 
    output [7:0] q // 8-bit output from the active module 
);

reg [7:0] reg0, reg1;
wire [7:0] mux_out;

// Register 0
