reg [3:0] bit_count;
reg xmit_bit;

wire start_bit;
wire stop_bit;

assign start_bit = (bit_count == 0);
assign stop_bit = (bit_count == 9);

always @(posedge clk) begin
    if (xmit) begin
        if (start_bit) begin
            tx_reg <= tx;
            bit_count <= 1;
            xmit_bit <= 0;
        end else if (stop_bit) begin
            xmit_bit <= 1;
            bit_count <= 0;
        end else begin
            xmit_bit <= tx_reg[0];
            tx_reg <= {tx_reg[6:0], 1'b0};
            bit_count <= bit_count + 1;
        end
    end else begin
        bit_count <= 0;
    end
end

always @(posedge clk) begin
    if (recv) begin
        if (start_bit) begin
            rx <= 0;
            bit_count <= 1;
        end else if (stop_bit) begin
            bit_count <= 0;
        end else begin
            rx <= {rx[6:0], recv};
            bit_count <= bit_count + 1;
        end
    end else begin
        bit_count <= 0;
    end
end

assign xmit_bit = (xmit_bit == 1'b0) ? 1'b1 : 1'b0;

assign rx = (bit_count == 9) ? rx : 8'hZZ;

endmodule

