module counter (
    CLK,
    RESET,
    ENABLE,
    COUNT,
    OVERFLOW
);

    input CLK;
    input RESET;
    input ENABLE;
    output reg [3:0] COUNT;
    output reg OVERFLOW;

    wire Q;
    wire Q_N;

    sky130_fd_sc_lp__sdfsbp_lp flip_flop (
        .CLK(CLK),
        .D(ENABLE & (~RESET) & (Q_N)),
        .SCD(ENABLE & (~RESET)),
        .SCE(ENABLE & (~RESET)),
        .SET_B(RESET),
        .Q(Q),
        .Q_N(Q_N)
    );

    always @(posedge CLK) begin
        if (Q & (~Q_N)) begin
            COUNT <= COUNT + 1;
            if (COUNT == 4'hF) begin
                OVERFLOW <= 1;
            end
        end
    end

    always @(negedge CLK) begin
        if (OVERFLOW) begin
            COUNT <= 0;
            OVERFLOW <= 0;
        end
    end

endmodule

module calculator(
  input         rst,
  input         clk,
  input  [7:0]  a,
  input  [7:0]  b,
  input  [1:0]  op,
  output [7:0]  result,
  output        valid
);

  reg [7:0] result_reg;
  reg valid_reg;

  always @(posedge clk or negedge rst) begin
    if (rst == 0) begin
      result_reg <= 0;
      valid_reg <= 0;
    end
    else begin
      case(op)
        2'b00: result_reg <= a + b; // addition
        2'b01: result_reg <= a - b; // subtraction
        2'b10: result_reg <= a * b; // multiplication
        2'b11: result_reg <= a / b; // division
      endcase
      valid_reg <= 1;
    end
  end

  assign result = result_reg;
  assign valid = valid_reg;

endmodule

module xor_gate_pipeline(
