module v_vid_in_axi4s
  #(
    parameter C_M_AXIS_VIDEO_DATA_WIDTH = 8,
    parameter C_M_AXIS_VIDEO_FORMAT = 0,
    parameter VID_IN_DATA_WIDTH = 16,
    parameter C_M_AXIS_VIDEO_TDATA_WIDTH = 16,
    parameter PADDING_BITS = 0,
    parameter RAM_ADDR_BITS = 10,
    parameter HYSTERESIS_LEVEL = 12
  )
  (
    input vid_in_clk,
    input rst,
    input vid_de,
    input vid_vblank,
    input vid_hblank,
    input vid_vsync,
    input vid_hsync,
    input [VID_IN_DATA_WIDTH-1:0] vid_data,
    input aclk,
    input aresetn,
    input aclken,
    output [C_M_AXIS_VIDEO_TDATA_WIDTH-1:0] m_axis_video_tdata,
    output m_axis_video_tvalid,
    input m_axis_video_tready,
    output m_axis_video_tuser,
    output m_axis_video_tlast,
    output vtd_active_video,
    output vtd_vblank,
    output vtd_hblank,
    output vtd_vsync,
    output vtd_hsync,
    output wr_error,
    output empty,
    input axis_enable
  );

  localparam C_M_AXIS_VIDEO_TUSER_WIDTH = 1;
  localparam C_M_AXIS_VIDEO_TLAST_WIDTH = 1;
  localparam C_M_AXIS_VIDEO_TID_WIDTH = 1;
  localparam C_M_AXIS_VIDEO_TDEST_WIDTH = 1;

  localparam C_M_AXIS_VIDEO_TUSER_MSB = C_M_AXIS_VIDEO_TUSER_WIDTH - 1;
  localparam C_M_AXIS_VIDEO_TLAST_MSB = C_M_AXIS_VIDEO_TLAST_WIDTH - 1;
  localparam C_M_AXIS_VIDEO_TID_MSB = C_M_AXIS_VIDEO_TID_WIDTH - 1;
  localparam C_M_AXIS_VIDEO_TDEST_MSB = C_M_AXIS_VIDEO_TDEST_WIDTH - 1;

  reg [C_M_AXIS_VIDEO_TDATA_WIDTH-1:0] tdata_reg;
  reg [C_M_AXIS_VIDEO_TUSER_MSB:0] tuser_reg;
  reg [C_M_AXIS_VIDEO_TLAST_MSB:0] tlast_reg;
  reg [C_M_AXIS_VIDEO_TID_MSB:0] tid_reg;
  reg [C_M_AXIS_VIDEO_TDEST_MSB:0] tdest_reg;
  reg [RAM_ADDR_BITS-1:0] addr_reg;
  reg [C_M_AXIS_VIDEO_DATA_WIDTH-1:0] data_reg;
  reg [1:0] state_reg;
  reg [HYSTERESIS_LEVEL-1:0] hysteresis_reg;

  assign m_axis_video_tdata = tdata_reg;
  assign m_axis_video_tvalid = (state_reg == 2) && (tlast_reg == 1);
  assign m_axis_video_tuser = tuser_reg;
  assign m_axis_video_tlast = tlast_reg;

  always @(posedge aclk)
  begin
    if (aresetn == 0)
    begin
      state_reg <= 0;
      addr_reg <= 0;
      data_reg <= 0;
      tdata_reg <= 0;
      tuser_reg <= 0;
      tlast_reg <= 0;
      tid_reg <= 0;
      tdest_reg <= 0;
      hysteresis_reg <= 0;
    end
    else
    begin
      case (state_reg)
        0: // Idle state
          begin
            if (vid_de)
            begin
              state_reg <= 1;
              addr_reg <= 0;
              data_reg <= vid_data;
              hysteresis_reg <= 0;
            end
          end
        1: // Data capture state
          begin
            if (!vid_de)
            begin
              state_reg <= 2;
              tdata_reg <= {data_reg, {PADDING_BITS{1'b0}}};
              tuser_reg <= 0;
              tlast_reg <= 0;
              tid_reg <= 0;
              tdest_reg <= 0;
            end
            else if (hysteresis_reg < HYSTERESIS_LEVEL)
            begin
              hysteresis_reg <= hysteresis_reg + 1;
            end
            else
            begin
              addr_reg <= addr_reg + 1;
              data_reg <= vid_data;
              hysteresis_reg <= 0;
            end
          end
        2: // Output state
          begin
            if (m_axis_video_tready)
            begin
              state_reg <= 0;
              tlast_reg <= 1;
            end
            else
            begin
              tlast_reg <= 0;
            end
          end
        default:
          state_reg <= 0;
      endcase
    end
  end

  assign vtd_active_video = vid_de;
  assign vtd_vblank = vid_vblank;
  assign vtd_hblank = vid_hblank;
  assign vtd_vsync = vid_vsync;
  assign vtd_hsync = vid_hsync;
  assign wr_error = 0;
  assign empty = (state_reg == 0) && !vid_de;

endmodule

