module sigma_delta (
  input analog_in,
  output digital_out,
  input digital_in,
  output analog_out
);

parameter OSR = 64;
parameter NUM_BITS = 16;
parameter MOD_ORDER = 1;
parameter SAMPLING_FREQ = 1000000;

reg [NUM_BITS-1:0] quantized_signal;
reg [NUM_BITS-1:0] feedback_signal;
reg [NUM_BITS-1:0] digital_out_reg;
reg [NUM_BITS-1:0] digital_in_reg;
reg [NUM_BITS-1:0] analog_out_reg;

always @(posedge clk) begin
  // Sigma-delta modulator
  feedback_signal <= analog_in - digital_out_reg;
  quantized_signal <= $signed(feedback_signal) >= 0 ? {NUM_BITS{1'b1}} : {NUM_BITS{1'b0}};
  digital_out_reg <= digital_out_reg + quantized_signal - feedback_signal/(OSR*MOD_ORDER);

  // Sigma-delta demodulator
  digital_in_reg <= digital_in;
  analog_out_reg <= $signed(digital_in_reg)/(OSR*MOD_ORDER);
end

assign digital_out = digital_out_reg;
assign analog_out = analog_out_reg;

endmodule

module CDC_Synchronizer (
  input data_in,
  input clk_in,
  input reset_in,
  output reg data_out,
  output reg clk_out,
  output reg reset_out
);

reg data_sync1;
reg data_sync2;
reg reset_sync;

always @(posedge clk_in) begin
  data_sync1 <= data_in;
end

always @(posedge clk_out) begin
  data_sync2 <= data_sync1;
  data_out <= data_sync2;
end

always @(posedge clk_out) begin
  reset_sync <= reset_in;
  reset_out <= reset_sync;
end

assign clk_out = clk_in;

endmodule

module csrbrg(
	input sys_clk,
	input sys_rst,

	/* WB */
	input [31:0] wb_adr_i,
	input [31:0] wb_dat_i,
	output reg [31:0] wb_dat_o,
	input wb_cyc_i,
	input wb_stb_i,
	input wb_we_i,
	output reg wb_ack_o,

	/* CSR */
	output reg [13:0] csr_a,
	output reg csr_we,
	output reg [31:0] csr_do,
	input [31:0] csr_di
);

/* Datapath: WB <- CSR */
always @(posedge sys_clk) begin
	wb_dat_o <= csr_di;
end

/* Datapath: CSR <- WB */
reg next_csr_we;
always @(posedge sys_clk) begin
	csr_a <= wb_adr_i[15:2];
	csr_we <= next_csr_we;
	csr_do <= wb_dat_i;
end

/* Controller */

reg [1:0] state;
reg [1:0] next_state;

parameter IDLE		= 2'd0;
parameter DELAYACK1	= 2'd1;
parameter DELAYACK2	= 2'd2;
parameter ACK		= 2'd3;

always @(posedge sys_clk) begin
	if(sys_rst)
		state <= IDLE;
	else
		state <= next_state;
end

always @(*) begin
	next_state = state;

	wb_ack_o = 1'b0;
	next_csr_we = 1'b0;

	case(state)
		IDLE: begin
			if(wb_cyc_i & wb_stb_i) begin
				/* We have a request for us */
				next_csr_we = wb_we_i;
				if(wb_we_i)
					next_state = ACK;
				else
					next_state = DELAYACK1;
			end
		end
		DELAYACK1: next_state = DELAYACK2;
		DELAYACK2: next_state = ACK;
		ACK: begin
			wb_ack_o = 1'b1;
			next_state = IDLE;
		end
	endcase
end

endmodule

