    assign Q_N = ~Q;

    always @(posedge CLK or negedge SET_B or negedge RESET_B) begin
        if (!SET_B) begin
            Q <= 1'b1;
        end else if (!RESET_B) begin
            Q <= 1'b0;
        end else begin
            Q <= D;
        end
    end

endmodule

module SignalProcessor (
    input clk,
    input reset,
    input [15:0] data_in,
    input process,
    output [15:0] data_out,
    output valid
);

    reg [15:0] processed_data;
    reg valid_reg;

    always @(posedge clk) begin
        if (reset) begin
            processed_data <= 0;
            valid_reg <= 0;
        end
        else begin
            if (process) begin
                processed_data <= data_in * 2;
                valid_reg <= 1;
            end
            else begin
                processed_data <= data_in;
                valid_reg <= 1;
            end
        end
    end

    assign data_out = processed_data;
    assign valid = valid_reg;

endmodule

module adder_32bit(
    input [31:0] a,
    input [31:0] b,
    output [31:0] sum
);

wire [7:0] a0, a1, a2, a3;
wire [7:0] b0, b1, b2, b3;
wire [7:0] s0, s1, s2, s3;
wire c0, c1, c2;

// Break down 32-bit inputs into four 8-bit chunks
assign a0 = a[7:0];
assign a1 = a[15:8];
assign a2 = a[23:16];
assign a3 = a[31:24];

assign b0 = b[7:0];
assign b1 = b[15:8];
assign b2 = b[23:16];
assign b3 = b[31:24];

// Add the corresponding chunks together using 8-bit adders
adder_8bit adder0(a0, b0, s0, c0);
adder_8bit adder1(a1, b1, s1, c1);
adder_8bit adder2(a2, b2, s2, c2);
adder_8bit adder3(a3, b3, s3, sum[31]);

// Use 2-to-1 multiplexers to select the correct carry bit between each 8-bit addition
mux2to1 mux0(c1, c0, sum[8], c2);
mux2to1 mux1(c2, c1, sum[16], sum[24]);
mux2to1 mux2(sum[31], c2, s3, sum[23]);
mux2to1 mux3(sum[23], sum[24], s2, sum[15]);
mux2to1 mux4(sum[15], sum[16], s1, sum[7]);
mux2to1 mux5(sum[7], sum[8], s0, sum[0]);

endmodule

