module pulse_gen(
  input clk,
  input trigger,
  input [15:0] pulse_width,
  output reg pulse
);

reg [15:0] counter = 0;
reg pulse_gen = 0;

always @(posedge clk) begin
  if (trigger) begin
    pulse_gen <= 1;
    counter <= 0;
  end else begin
    if (counter >= pulse_width) begin
      pulse_gen <= 0;
    end
    counter <= counter + 1;
  end
end

always @(posedge clk) begin
  pulse <= pulse_gen;
end

endmodule

module quad_demod (
  input in,
  input ref,
  output out
);

  reg [15:0] filtered_in;
  reg [15:0] filtered_ref;
  reg [15:0] product;
  reg [15:0] filtered_product;

  // Low-pass filter coefficients
  parameter LPF_A = 16384;
  parameter LPF_B = 49152;

  always @(posedge clk) begin
    // Low-pass filter input signal
    filtered_in <= (LPF_A * in) + (LPF_B * filtered_in);

    // Low-pass filter reference signal
    filtered_ref <= (LPF_A * ref) + (LPF_B * filtered_ref);

    // Compute product of input and reference signals
    product <= filtered_in * filtered_ref;

    // Low-pass filter product
    filtered_product <= (LPF_A * product) + (LPF_B * filtered_product);

    // Output demodulated signal
    out <= filtered_product;
  end

endmodule


module quad_mod (
  input in,
  input carrier,
  output out_i,
  output out_q
);

  reg [15:0] filtered_in;
  reg [15:0] cos_val;
  reg [15:0] sin_val;
  reg [15:0] filtered_cos;
  reg [15:0] filtered_sin;

  // Low-pass filter coefficients
  parameter LPF_A = 16384;
  parameter LPF_B = 49152;

  always @(posedge clk) begin
    // Low-pass filter input signal
    filtered_in <= (LPF_A * in) + (LPF_B * filtered_in);

    // Compute cosine and sine values
    cos_val <= filtered_in * $cos(carrier);
    sin_val <= filtered_in * $sin(carrier);

    // Low-pass filter cosine and sine values
    filtered_cos <= (LPF_A * cos_val) + (LPF_B * filtered_cos);
    filtered_sin <= (LPF_A * sin_val) + (LPF_B * filtered_sin);

    // Output in-phase and quadrature-phase components
    out_i <= filtered_cos;
    out_q <= filtered_sin;
  end

endmodule

module debounce(input clk, but, output reg debounced);
    reg [9:0] debTimer;
    always @(posedge clk) begin
        if (debounced == but) // button is stable
            debTimer <= 0;
        else if (debTimer != 10'd9) // button is bouncing
            debTimer <= debTimer + 1;
        else if (debTimer == 10'd9) // button has been stable for 10 cycles
            debounced <= but;
    end
endmodule

module wb_mux
  #(parameter dw = 32,        // Data width
    parameter aw = 32,        // Address width
    parameter num_slaves = 2, // Number of slaves
    parameter [num_slaves*aw-1:0] MATCH_ADDR = 0,
    parameter [num_slaves*aw-1:0] MATCH_MASK = 0)

   (input                      wb_clk_i,
    input 		       wb_rst_i,

    // Master Interface
    input [aw-1:0] 	       wbm_adr_i,
    input [dw-1:0] 	       wbm_dat_i,
    input [3:0] 	       wbm_sel_i,
    input 		       wbm_we_i,
    input 		       wbm_cyc_i,
    input 		       wbm_stb_i,
    input [2:0] 	       wbm_cti_i,
    input [1:0] 	       wbm_bte_i,
    output [dw-1:0] 	       wbm_dat_o,
    output 		       wbm_ack_o,
    output 		       wbm_err_o,
    output 		       wbm_rty_o,
    // Wishbone Slave interface
    output [num_slaves*aw-1:0] wbs_adr_o,
    output [num_slaves*dw-1:0] wbs_dat_o,
    output [num_slaves*4-1:0]  wbs_sel_o,
    output [num_slaves-1:0]    wbs_we_o,
    output [num_slaves-1:0]    wbs_cyc_o,
    output [num_slaves-1:0]    wbs_stb_o,
    output [num_slaves*3-1:0]  wbs_cti_o,
    output [num_slaves*2-1:0]  wbs_bte_o,
    input [num_slaves*dw-1:0]  wbs_dat_i,
    input [num_slaves-1:0]     wbs_ack_i,
    input [num_slaves-1:0]     wbs_err_i,
    input [num_slaves-1:0]     wbs_rty_i);

   //Use parameter instead of localparam to work around a bug in Xilinx ISE
   parameter slave_sel_bits = num_slaves > 1 ? $clog2(num_slaves) : 1;

   reg  			 wbm_err;
   wire [slave_sel_bits-1:0] 	 slave_sel;
   wire [num_slaves-1:0] 	 match;

   genvar 			 idx;

   generate
      for(idx=0; idx<num_slaves ; idx=idx+1) begin : addr_match
	 assign match[idx] = (wbm_adr_i & MATCH_MASK[idx*aw+:aw]) == MATCH_ADDR[idx*aw+:aw];
      end
   endgenerate

   function [slave_sel_bits-1:0] ff1;
      input [num_slaves-1:0] in;
      integer 		     i;

      begin
	 ff1 = 0;
	 for (i = num_slaves-1; i >= 0; i=i-1) begin
	    if (in[i])
	      ff1 = i;
	 end
      end
   endfunction

   assign slave_sel = ff1(match);

   always @(posedge wb_clk_i)
     wbm_err <= wbm_cyc_i & !(|match);

   assign wbs_adr_o = {num_slaves{wbm_adr_i}};
   assign wbs_dat_o = {num_slaves{wbm_dat_i}};
   assign wbs_sel_o = {num_slaves{wbm_sel_i}};
   assign wbs_we_o  = {num_slaves{wbm_we_i}};
   assign wbs_cyc_o = match & (wbm_cyc_i << slave_sel);
   assign wbs_stb_o = {num_slaves{wbm_stb_i}};
   assign wbs_cti_o = {num_slaves{wbm_cti_i}};
   assign wbs_bte_o = {num_slaves{wbm_bte_i}};

   assign wbm_dat_o = wbs_dat_i[slave_sel*dw+:dw];
   assign wbm_ack_o = wbs_ack_i[slave_sel];
   assign wbm_err_o = wbs_err_i[slave_sel] | wbm_err;
   assign wbm_rty_o = wbs_rty_i[slave_sel];

endmodule

