module vending_machine (
  input clk,
  input reset,
  input [1:0] coin,
  input [1:0] item,
  output reg dispense,
  output reg [1:0] change
);

  // Define the states of the vending machine
  parameter IDLE = 2'b00;
  parameter WAITING = 2'b01;
  parameter DISPENSING = 2'b10;

  // Define the costs of the items
  parameter ITEM1_COST = 1;
  parameter ITEM2_COST = 2;

  // Define the state and output registers
  reg [1:0] state = IDLE;
  reg [1:0] inserted_coins = 2'b00;
  reg [1:0] selected_item = 2'b00;
  reg [1:0] item_cost = 2'b00;

  // Initialize outputs to 0
  assign dispense = 1'b0;
  assign change = 2'b00;

  // Define the state machine
  always @(posedge clk) begin
    if (reset == 1'b0) begin
      // Reset the state machine and output registers
      state <= IDLE;
      inserted_coins <= 2'b00;
      selected_item <= 2'b00;
      item_cost <= 2'b00;
      dispense <= 1'b0;
      change <= 2'b00;
    end else begin
      case (state)
        IDLE: begin
          // Wait for the user to insert coins and select an item
          if (coin != 2'b00 && item != 2'b00) begin
            // Save the selected item and calculate its cost
            selected_item <= item;
            if (item == 2'b01) begin
              item_cost <= ITEM1_COST;
            end else begin
              item_cost <= ITEM2_COST;
            end
            // Move to the waiting state
            state <= WAITING;
          end
        end
        WAITING: begin
          // Keep track of the total amount of money inserted
          inserted_coins <= inserted_coins + coin;
          // Check if the user has inserted enough money to buy the selected item
          if (inserted_coins >= item_cost) begin
            // Dispense the item and return change
            dispense <= 1'b1;
            change <= inserted_coins - item_cost;
            // Move to the dispensing state
            state <= DISPENSING;
          end
        end
        DISPENSING: begin
          // Wait for one clock cycle before returning to the idle state
          dispense <= 1'b0;
          change <= 2'b00;
          state <= IDLE;
        end
      endcase
    end
  end

endmodule

module restoring_divider (
    input [3:0] dividend,
    input [3:0] divisor,
    output reg [3:0] quotient,
    output reg [3:0] remainder
);

reg [7:0] dividend_reg;
reg [3:0] divisor_reg;
reg [3:0] quotient_reg;
reg [3:0] remainder_reg;
reg [2:0] count;

always @(*) begin
    dividend_reg = {dividend, 4'b0};
    divisor_reg = {divisor, 2'b0};
    quotient_reg = 4'b0;
    remainder_reg = dividend_reg;
    count = 4'd0;
end

always @(posedge clk) begin
    if (count < 4'd4) begin
        remainder_reg = remainder_reg << 1;
        remainder_reg[0] = quotient_reg[3];
        quotient_reg = quotient_reg << 1;
        if (remainder_reg >= divisor_reg) begin
            remainder_reg = remainder_reg - divisor_reg;
            quotient_reg[0] = 1;
        end
        count = count + 1;
    end
end

assign quotient = quotient_reg;
assign remainder = remainder_reg[3:0];

endmodule

module barrel_shifter (
  input [31:0] in,
  input [3:0] shift_amount,
  output [31:0] out
);

  reg [31:0] shifted;

  always @(*) begin
    case(shift_amount)
      4'b0000: shifted = in;
      4'b0001: shifted = in << 1;
      4'b0010: shifted = in << 2;
      4'b0011: shifted = in << 3;
      4'b0100: shifted = in << 4;
      4'b0101: shifted = in << 5;
      4'b0110: shifted = in << 6;
      4'b0111: shifted = in << 7;
      4'b1000: shifted = in >> 1;
      4'b1001: shifted = in >> 2;
      4'b1010: shifted = in >> 3;
      4'b1011: shifted = in >> 4;
      4'b1100: shifted = in >> 5;
      4'b1101: shifted = in >> 6;
      4'b1110: shifted = in >> 7;
      4'b1111: shifted = in >> 8;
    endcase
    out = shifted;
  end

endmodule

