module top_module (
  input [15:0] in,
  input [3:0] shift_amount,
  output [7:0] out_lo,
  output [7:0] out_hi,
  output [7:0] final_output
);

  wire [31:0] shifted_lo;
  wire [31:0] shifted_hi;

  barrel_shifter bs_lo(
    .in(in),
    .shift_amount(shift_amount),
    .out(shifted_lo)
  );

  barrel_shifter bs_hi(
    .in(in >> 8),
    .shift_amount(shift_amount),
    .out(shifted_hi)
  );

  assign out_lo = shifted_lo[7:0];
  assign out_hi = shifted_hi[7:0];

  adder add(
    .in1(shifted_lo[7:0]),
    .in2(shifted_hi[7:0]),
    .out(final_output)
  );

endmodule

