module up_down_counter (
    input clk,
    input reset,       // Synchronous active-high reset
    input up_down,     // Up/down select input
    output reg [15:0] count_out  // Output count value
);

    always @(posedge clk) begin
        if (reset) begin
            count_out <= 0;
        end else begin
            if (up_down) begin
