module Debouncer (
  input in,
  output out
);

  parameter debounce_time = 10; // debounce time in milliseconds
  parameter clk_period = 20; // clock period in nanoseconds

  reg [1:0] state; // state variable to keep track of the current state
  reg [31:0] debounce_counter; // counter to keep track of the elapsed time since the last state change

  always @(posedge clk) begin
    case (state)
      2'b00: // initial state
        if (in == 1'b1) begin
          debounce_counter <= 0;
          state <= 2'b01;
        end else if (in == 1'b0) begin
          debounce_counter <= 0;
          state <= 2'b10;
        end
      2'b01: // stable high state
        if (in == 1'b0) begin
          debounce_counter <= 0;
          state <= 2'b10;
        end else if (debounce_counter >= debounce_time*1000000/clk_period) begin
          out <= 1'b1;
          debounce_counter <= 0;
          state <= 2'b11;
        end else begin
          debounce_counter <= debounce_counter + 1;
        end
      2'b10: // stable low state
        if (in == 1'b1) begin
          debounce_counter <= 0;
          state <= 2'b01;
        end else if (debounce_counter >= debounce_time*1000000/clk_period) begin
          out <= 1'b0;
          debounce_counter <= 0;
          state <= 2'b00;
        end else begin
          debounce_counter <= debounce_counter + 1;
        end
      2'b11: // debounced state
        if (in == 1'b1) begin
          debounce_counter <= 0;
          state <= 2'b01;
        end else if (in == 1'b0) begin
          debounce_counter <= 0;
          state <= 2'b10;
        end
    endcase
  end

endmodule

