module binary_adder(
    input [3:0] A,
    input [3:0] B,
    output [3:0] S,
    output C
);

    wire c1, c2, c3;
    wire s0, s1, s2, s3;

    // Full adder for bit 0
    full_adder fa0(
        .a(A[0]),
        .b(B[0]),
        .c(1'b0),
        .s(s0),
        .co(c1)
    );

    // Full adder for bit 1
    full_adder fa1(
        .a(A[1]),
        .b(B[1]),
        .c(c1),
        .s(s1),
        .co(c2)
    );

    // Full adder for bit 2
    full_adder fa2(
        .a(A[2]),
        .b(B[2]),
        .c(c2),
        .s(s2),
        .co(c3)
    );

    // Full adder for bit 3
    full_adder fa3(
        .a(A[3]),
        .b(B[3]),
        .c(c3),
        .s(s3),
        .co(C)
    );

    assign S = {s3, s2, s1, s0};

endmodule

module full_adder(
    input a,
    input b,
    input c,
    output s,
    output co
);

    wire w1, w2, w3;

