    xor x1(.a(a), .b(b), .o(w1));
    xor x2(.a(w1), .b(c), .o(s));

    // AND gate to calculate carry out
    and a1(.a(a), .b(b), .o(w2));
    and a2(.a(w1), .b(c), .o(w3));
    or o1(.a(w2), .b(w3), .o(co));

endmodule

