module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] a,    // 8-bit input for number A
    input [7:0] b,    // 8-bit input for number B
    output q          // Output signal from the dual-edge triggered flip-flop module
);

    wire [8:0] sum;
    wire carry_out;
    wire [7:0] abs_sum;
    wire sum_is_negative;
    wire [7:0] twos_complement;

    // Instantiate carry-lookahead adder
    carry_lookahead_adder adder(
        .a(a),
        .b(b),
        .carry_in(1'b0),
        .sum(sum),
        .carry_out(carry_out)
    );

    // Instantiate addictive functional module
    addictive_functional_module afm(
        .a(a),
        .b(b),
        .sum(sum),
        .abs_sum(abs_sum),
        .sum_is_negative(sum_is_negative),
        .twos_complement(twos_complement)
    );

    // Instantiate dual-edge triggered flip-flop module
    dual_edge_triggered_flip_flop detff(
        .clk(clk),
        .reset(reset),
        .d(sum_is_negative),
        .q(q)
    );

endmodule

module carry_lookahead_adder (
    input [7:0] a,
    input [7:0] b,
    input carry_in,
    output [8:0] sum,
    output carry_out
);

    wire [7:0] p;
    wire [7:0] g;

    assign p = a ^ b;
    assign g = a & b;

    assign sum[0] = carry_in;

    genvar i;
    generate
        for (i = 0; i < 8; i = i + 1) begin : gen
            assign sum[i+1] = p[i] ^ carry_in;
            assign carry_in = g[i] | (p[i] & carry_in);
        end
    endgenerate

    assign carry_out = carry_in;

endmodule

module addictive_functional_module (
    input [7:0] a,
    input [7:0] b,
    input [8:0] sum,
    output [7:0] abs_sum,
    output sum_is_negative,
    output [7:0] twos_complement
);

    assign abs_sum = (sum[8] == 1) ? (~sum[7:0] + 1) : sum[7:0];
    assign sum_is_negative = sum[8];
    assign twos_complement = (sum[8] == 1) ? (~abs_sum + 1) : abs_sum;

endmodule

