module any_edge_detection (
    input clk,
    input [7:0] in,
    output [7:0] anyedge
);

reg [7:0] current_state;
reg [7:0] previous_state;
reg [7:0] edge_detected;

// Store the current state of each bit in the input vector
always @(posedge clk) begin
    current_state <= in;
end

// Compare the current state with the previous state of each bit
// If there is a change, set the output of the XOR gate high
// indicating an edge transition
assign edge_detected = current_state ^ previous_state;

// Delay the output by one cycle
// so that the output bit is set high on the cycle after the edge transition occurs
always @(posedge clk) begin
    previous_state <= current_state;
    anyedge <= edge_detected;
end

endmodule

