module full_adder(
    input a, b, cin,
    output cout, sum );

    wire w1, w2, w3;

    // First stage of full adder
    xor x1(sum, a, b);
    xor x2(cout, sum, cin);

    // Second stage of full adder
    and a1(w1, a, b);
    and a2(w2, sum, cin);
    and a3(w3, a, cin);

    // Third stage of full adder
    mux m1(sum, w1, w2, cin);
    mux m2(cout, w1, w3, w2);

endmodule

module priority_mux_barrel_shifter (
    input A,
    input B,
    input C,
    input [3:0] data,
    input S,
    input mode,
    input P,
    input [1:0] shift,
    input shift_right,
    input shift_left,
    input rotate_right,
    input rotate_left,
    output reg [3:0] Y
);

reg [3:0] shifted_data;

always @(*) begin
    case (mode)
        2'b00: shifted_data = {data[2:0], 1'b0};
        2'b01: shifted_data = {1'b0, data[3:1]};
        2'b10: shifted_data = {data[0], data[3:1]};
        2'b11: shifted_data = {data[2:0], data[3]};
    endcase

    if (shift_right) begin
        shifted_data = shifted_data >> shift;
    end else if (shift_left) begin
        shifted_data = shifted_data << shift;
    end else if (rotate_right) begin
        shifted_data = {shifted_data[shift-1:0], shifted_data[3:shift]};
    end else if (rotate_left) begin
        shifted_data = {shifted_data[3-shift+1:3], shifted_data[2:0]};
    end

    if (P) begin
        Y = C;
    end else if (S) begin
        Y = B;
    end else begin
        Y = A;
    end

    if (mode != 2'b00 && mode != 2'b01) begin
        Y = shifted_data;
    end
end

endmodule

module FSM_State_Merging (
  input clk,
  input reset,
  input in_signal,
  output reg [1:0] state,
  output out_signal
);

  // State encoding
  localparam S0 = 2'b00, S1 = 2'b01, S2 = 2'b10, S3 = 2'b11;

  // State transition and output logic
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      state <= S0;
      out_signal <= 1'b0;
    end else begin
      case (state)
        S0: begin
          if (in_signal) begin
            state <= S1;
            out_signal <= 1'b0;
          end
        end
        S1: begin
          if (!in_signal) begin
            state <= S2;
            out_signal <= 1'b1;
          end
        end
        S2: begin
          if (in_signal) begin
            state <= S3;
            out_signal <= 1'b1;
          end else begin
            state <= S1;
            out_signal <= 1'b1;
          end
        end
        S3: begin
          if (!in_signal) begin
            state <= S0;
            out_signal <= 1'b0;
          end
        end
      endcase
    end
  end


endmodule

