module top_module (
    input clk,
    input [1:0] in1,
    input [1:0] in2,
    input select,
    output [3:0] out
);

    wire [3:0] decoder1_out;
    wire [3:0] decoder2_out;
    wire [3:0] binary_out;

    // Decoder 1 implementation using AND, OR, and NOT gates
    assign decoder1_out[0] = ~(in1[1] & in1[0]);
    assign decoder1_out[1] = ~(in1[1] & ~in1[0]);
    assign decoder1_out[2] = ~(~in1[1] & in1[0]);
    assign decoder1_out[3] = ~(~in1[1] & ~in1[0]);

    // Decoder 2 implementation using AND, OR, and NOT gates
    assign decoder2_out[0] = ~(in2[1] & in2[0]);
    assign decoder2_out[1] = ~(in2[1] & ~in2[0]);
    assign decoder2_out[2] = ~(~in2[1] & in2[0]);
    assign decoder2_out[3] = ~(~in2[1] & ~in2[0]);

    // Binary output implementation
    assign binary_out[0] = in1[0] & in2[0];
    assign binary_out[1] = in1[0] & in2[1];
    assign binary_out[2] = in1[1] & in2[0];
    assign binary_out[3] = in1[1] & in2[1];

    // Control logic to select active module
    always @ (select) begin
        if (select == 0) begin
            out <= decoder1_out;
        end else if (select == 1) begin
            out <= decoder2_out;
        end else begin
            out <= binary_out;
        end
    end

endmodule

module record_play (
    clk_i,
    button_a,
    button_b,
    leds_o
);

input clk_i;
input button_a;
input button_b;
output [4:0] leds_o;

reg [4:0] leds_o;
reg [0:0] data_i;
reg wr;
reg do_sample;
reg [0:0] data_o;
reg reset;
reg [2:0] state;
reg [10:0] end_addr;
reg [10:0] addr;
reg [16:0] chunk_insts_0_cntr;
reg [0:0] chunk_insts_1_cntr;
reg [0:0] k_mem [0:2048-1];

always @(posedge clk_i) begin: RECORD_PLAY_LOC_INSTS_CHUNK_INSTS_0_LOC_INSTS_CHUNK_INSTS_K
    chunk_insts_0_cntr <= (chunk_insts_0_cntr + 1);
    do_sample <= 0;
    if ((chunk_insts_0_cntr == 119999)) begin
        do_sample <= 1;
        chunk_insts_0_cntr <= 0;
    end
end

always @(posedge clk_i) begin: RECORD_PLAY_LOC_INSTS_CHUNK_INSTS_1_LOC_INSTS_CHUNK_INSTS_K
    if ((chunk_insts_1_cntr < 1)) begin
        chunk_insts_1_cntr <= (chunk_insts_1_cntr + 1);
        reset <= 1;
    end
    else begin
        reset <= 0;
    end
end

always @(posedge clk_i) begin: RECORD_PLAY_LOC_INSTS_CHUNK_INSTS_2
    wr <= 0;
    if (reset) begin
        state <= 0;
    end
    else if (do_sample) begin
        case (state)
            'h0: begin
                leds_o <= 21;
                if ((button_a == 1)) begin
                    state <= 1;
                end
            end
            'h1: begin
                leds_o <= 26;
                if ((button_a == 0)) begin
                    addr <= 0;
                    data_i <= button_b;
                    wr <= 1;
                    state <= 2;
                end
            end
            'h2: begin
                addr <= (addr + 1);
                data_i <= button_b;
                wr <= 1;
                leds_o <= {1, button_b, button_b, button_b, button_b};
                if ((button_a == 1)) begin
                    end_addr <= (addr + 1);
                    state <= 3;
                end
            end
            'h3: begin
                leds_o <= 16;
                if ((button_a == 0)) begin
                    addr <= 0;
                    state <= 4;
                end
            end
            'h4: begin
                leds_o <= {1, data_o[0], data_o[0], data_o[0], data_o[0]};
                addr <= (addr + 1);
                if ((addr == end_addr)) begin
                    addr <= 0;
                end
                if ((button_a == 1)) begin
                    state <= 1;
                end
            end
        endcase
    end
end

always @(posedge clk_i) begin: RECORD_PLAY_LOC_INSTS_CHUNK_INSTS_K_LOC_INSTS_CHUNK_INSTS_K
    if (wr) begin
        k_mem[addr] <= data_i;
    end
    else begin
        data_o <= k_mem[addr];
    end
end

endmodule

module servo_controller (
  input clk,
  input rst,
  input [12:0] data,
  output reg [7:0] address,
  output reg servo_q
);

  parameter CLK_FREQUENCY = 50000000;
  parameter VALUE_SCALING = 256;
  parameter CTR_LEN = 21;
  parameter SPEED_DATA_LEN = 5;
  parameter POSITION_DATA_LEN = 8;
  parameter ADDR_LEN = 8;
  parameter MAX_RAM_POS = 256;
  parameter DATA_LEN = 13;

  wire [CTR_LEN-1:0] freq;
  wire [SPEED_DATA_LEN-1:0] speed;
  wire [POSITION_DATA_LEN-1:0] pos;
  wire [CTR_LEN-9:0] pulseCount;

  assign speed = data[12-SPEED_DATA_LEN+1:12];
  assign freq = CLK_FREQUENCY*(speed/1000.0);
  assign pos = data[POSITION_DATA_LEN-1:0];

  reg [CTR_LEN-1:0] ctr;
  always @(posedge clk) begin
    if (rst) begin
      address <= 8'b0;
      ctr <= 0;
    end else begin
      ctr <= ctr + 1;
      if (ctr >= freq) begin
        if (address < MAX_RAM_POS-1) begin
          address <= address + 1;
        end else begin
          address <= 8'b0;
        end
        ctr <= 0;
      end
    end
  end

  always @(posedge clk) begin
    if (pulseCount < pos + 165) begin
      servo_q <= 1'b1;
    end else begin
      servo_q <= 1'b0;
    end
  end

  always @(posedge clk) begin
    if (rst) begin
      pulseCount <= 0;
    end else begin
      pulseCount <= pulseCount + 1;
      if (pulseCount >= 20000) begin
        pulseCount <= 0;
      end
    end
  end

endmodule

module time_sender
  (input clk, input rst,
   input [63:0] vita_time,
   input send_sync,
   output reg exp_time_out);

   reg [7:0] datain;
   reg 	     k;
   wire [9:0] dataout;
   reg [9:0]  dataout_reg;
   reg 	      disp_reg;
   wire       disp, new_word;
   reg [4:0]  state;
   reg [3:0]  bit_count;

   // 8b/10b encoder module
   encode_8b10b encode_8b10b 
     (.datain({k,datain}),.dispin(disp_reg),
      .dataout(dataout),.dispout(disp));

   // Output disp_reg on the next clock cycle after a new word is received
   always @(posedge clk)
     if(rst)
       disp_reg <= 0;
     else if(new_word)
       disp_reg <= disp;

   // Shift dataout_reg left by one bit every clock cycle, except when a new word is received
   always @(posedge clk)
     if(rst)
       dataout_reg <= 0;
     else if(new_word)
       dataout_reg <= dataout;
     else
       dataout_reg <= {1'b0,dataout_reg[9:1]};

   // Output the first bit of dataout_reg as exp_time_out
   always @(posedge clk)
     exp_time_out <= dataout_reg[0];

   // Set new_word to 1 when bit_count reaches 9
   assign    new_word = (bit_count == 9);

   // Reset bit_count to 0 when a new word is received or send_sync is asserted
   always @(posedge clk)
     if(rst)
       bit_count <= 0;
     else if(new_word | send_sync)
       bit_count <= 0;
     else
       bit_count <= bit_count + 1;

   // Define the states of the state machine
   localparam SEND_IDLE = 0;
   localparam SEND_HEAD = 1;
   localparam SEND_T0 = 2;
   localparam SEND_T1 = 3;
   localparam SEND_T2 = 4;
   localparam SEND_T3 = 5;
   localparam SEND_T4 = 6;
   localparam SEND_T5 = 7;
   localparam SEND_T6 = 8;
   localparam SEND_T7 = 9;
   localparam SEND_TAIL = 10;

   // Define the comma, header, and tail values
   localparam COMMA = 8'hBC;
   localparam HEAD = 8'h3C;
   localparam TAIL = 8'hF7;

   reg [63:0] vita_time_reg;

   // Store the vita_time input in vita_time_reg when send_sync is asserted
   always @(posedge clk)
     if(rst)
       vita_time_reg <= 0;
     else if(send_sync)
       vita_time_reg <= vita_time;

   // State machine to send the data
   always @(posedge clk)
     if(rst)
       begin
	  {k,datain} <= 0;
	  state <= SEND_IDLE;
       end
     else
       if(send_sync)
	 state <= SEND_HEAD;
       else if(new_word)
	 case(state)
	   SEND_IDLE :
	     {k,datain} <= {1'b1,COMMA};
	   SEND_HEAD :
	     begin
		{k,datain} <= {1'b1, HEAD};
		state <= SEND_T0;
	     end
	   SEND_T0 :
	     begin
		{k,datain} <= {1'b0, vita_time_reg[7:0] };
		state <= SEND_T1;
	     end
	   SEND_T1 :
	     begin
		{k,datain} <= {1'b0, vita_time_reg[15:8]};
		state <= SEND_T2;
	     end
	   SEND_T2 :
	     begin
		{k,datain} <= {1'b0, vita_time_reg[23:16]};
		state <= SEND_T3;
	     end
	   SEND_T3 :
	     begin
		{k,datain} <= {1'b0, vita_time_reg[31:24]};
		state <= SEND_T4;
	     end
	   SEND_T4 :
	     begin
		{k,datain} <= {1'b0, vita_time_reg[39:32]};
		state <= SEND_T5;
	     end
	   SEND_T5 :
	     begin
		{k,datain} <= {1'b0, vita_time_reg[47:40]};
		state <= SEND_T6;
	     end
	   SEND_T6 :
	     begin
		{k,datain} <= {1'b0, vita_time_reg[55:48]};
		state <= SEND_T7;
	     end
	   SEND_T7 :
	     begin
		{k,datain} <= {1'b0, vita_time_reg[63:56]};
		state <= SEND_TAIL;
	     end
	   SEND_TAIL :
	     begin
		{k,datain} <= {1'b1, TAIL};
		state <= SEND_IDLE;
	     end
	   default :
	     state <= SEND_IDLE;
	 endcase // case(state)

endmodule

