module priority_encoder (
    input [31:0] in,
    output reg [1:0] out
);

    always @* begin
        case (in)
            32'h00000001: out = 2'b00;
            32'h00000100: out = 2'b01;
            32'h00010000: out = 2'b10;
            32'h01000000: out = 2'b11;
            default: out = 2'b00;
        endcase
    end

endmodule

module max_value_module (
    input [7:0] in [3:0],
    output reg [7:0] out,
    input ctrl
);

    always @* begin
        case (ctrl)
            2'b00: out = in[0];
            2'b01: out = (in[0] > in[1]) ? in[0] : in[1];
            2'b10: out = (in[2] > in[3]) ? in[2] : in[3];
            2'b11: out = (in[1] > in[3]) ? in[1] : in[3];
            default: out = in[0];
        endcase
    end

endmodule

module bcd_counter (
    input clk,
    input reset,
    output [3:0] out
);

    reg [13:0] count;

    always @(posedge clk) begin
        if (reset) begin
            count <= 14'h0000;
        end else begin
            count <= count + 1;
        end
    end

    assign out = count[3:0];

endmodule

module final_output_module (
    input [7:0] max_val,
    input [3:0] bcd_out,
    output [15:0] out
);

    assign out = {bcd_out, max_val};

endmodule

module arbiter (clk, rst, request, acknowledge, grant, grant_valid, grant_encoded);
  input [3:0] acknowledge;
  input clk;
  output [3:0] grant;
  output [1:0] grant_encoded;
  output grant_valid;
  input [3:0] request;
  input rst;

  reg [3:0] grant_reg;
  reg [1:0] grant_encoded_reg;
  reg grant_valid_reg;

  always @(posedge clk) begin
    if (rst) begin
      grant_reg <= 4'b0000;
      grant_encoded_reg <= 2'b00;
      grant_valid_reg <= 1'b0;
    end else begin
      if (request[0] && !acknowledge[0]) begin
        grant_reg <= 4'b0001;
        grant_encoded_reg <= 2'b01;
        grant_valid_reg <= 1'b1;
      end else if (request[1] && !acknowledge[1]) begin
        grant_reg <= 4'b0010;
        grant_encoded_reg <= 2'b10;
        grant_valid_reg <= 1'b1;
      end else if (request[2] && !acknowledge[2]) begin
        grant_reg <= 4'b0100;
        grant_encoded_reg <= 2'b11;
        grant_valid_reg <= 1'b1;
      end else if (request[3] && !acknowledge[3]) begin
        grant_reg <= 4'b1000;
        grant_encoded_reg <= 2'b11;
        grant_valid_reg <= 1'b1;
      end else begin
        grant_reg <= 4'b0000;
        grant_encoded_reg <= 2'b00;
        grant_valid_reg <= 1'b0;
      end
    end
  end

  assign grant = grant_reg;
  assign grant_valid = grant_valid_reg;
  assign grant_encoded = grant_encoded_reg;

endmodule

module barrel_shifter (
  input [n-1:0] in,
  input [log2(n)-1:0] shift,
  output [n-1:0] out
);

parameter n = 8; // number of bits in the binary number to be shifted

// Left shift operation
assign out = (shift > 0) ? {in[shift-1:0], {shift{1'b0}}} : in;

// Right shift operation
assign out = (shift < 0) ? (in >> -shift) : out;

endmodule

module FixedRoundSigned(
	clk,
	fixed_num,
	round,
	overflow
	);

	parameter num_width = 42;
	parameter fixed_pos = 16;
	parameter res_width = 12;

	input clk;
	input signed [num_width - 1 : 0] fixed_num;
	output reg signed [res_width : 0] round;
	output reg overflow;

	reg signed [num_width - 1 : 0] num_orig;
	reg num_orig_sflag, num_orig_rflag, reg_overflow;
	reg signed [res_width : 0] num_comp;

	always @(posedge clk) begin
		num_orig <= fixed_num[num_width - 1] == 0 ? fixed_num : 
			{fixed_num[num_width - 1], ~(fixed_num[num_width - 2 : 0] - 1)};
		num_comp <= num_orig[num_width - 1] == 0 ? 
			{num_orig[num_width - 1], num_orig[res_width + fixed_pos - 1 : fixed_pos]} : 
			{num_orig[num_width - 1], ~num_orig[res_width + fixed_pos - 1 : fixed_pos] + 1};
		reg_overflow <= num_orig[num_width - 2 : res_width + fixed_pos] == 0 ? 0 : 1;
		overflow <= reg_overflow;
		num_orig_sflag <= num_orig[num_width - 1];
		num_orig_rflag <= num_orig[fixed_pos - 1];
		//Why not use num_comp[25] to judge? : if 0
		case(num_orig_sflag)
			0 : round <= num_orig_rflag == 0 ? num_comp : num_comp + 1;
			1 : round <= num_orig_rflag == 0 ? num_comp : num_comp - 1;
			default : /* default */;
		endcase
	end

endmodule

module bluetooth_transmitter (
  input clk,
  input reset,
  input [7:0] data_in,
  input enable,
  output [15:0] tx_out
);

  reg [7:0] encoded_data;
  reg [15:0] modulated_data;
  reg [3:0] bit_counter;
  reg [15:0] carrier_signal;
  reg [15:0] tx_data;

  // Bluetooth encoding scheme
  always @ (posedge clk) begin
    if (reset) begin
      encoded_data <= 8'b00000000;
      bit_counter <= 4'd0;
    end else if (enable) begin
      encoded_data <= {data_in[6], data_in[5], data_in[4], data_in[3], data_in[2], data_in[1], data_in[0], ~(data_in[6] ^ data_in[5] ^ data_in[4] ^ data_in[3] ^ data_in[2] ^ data_in[1] ^ data_in[0])};
      bit_counter <= bit_counter + 1;
    end
  end

  // Bluetooth modulation
  always @ (posedge clk) begin
    if (reset) begin
      modulated_data <= 16'b0000000000000000;
      carrier_signal <= 16'b0000000000000000;
    end else if (enable) begin
      if (bit_counter == 4'd0) begin
        carrier_signal <= {carrier_signal[14:0], ~carrier_signal[15]};
      end
      modulated_data <= {modulated_data[14:0], encoded_data[7] & carrier_signal[15]};
      carrier_signal <= {carrier_signal[14:0], carrier_signal[15] ^ modulated_data[15]};
    end
  end

  // Output data
  always @ (posedge clk) begin
    if (reset) begin
      tx_data <= 16'b0000000000000000;
    end else if (enable) begin
      tx_data <= modulated_data;
    end
  end

  assign tx_out = tx_data;

endmodule

module bluetooth_receiver (
  input clk,
  input reset,
  input [15:0] rx_in,
  output [7:0] data_out
);

  reg [15:0] demodulated_data;
  reg [7:0] decoded_data;
  reg [3:0] bit_counter;
  reg [15:0] carrier_signal;

  // Bluetooth demodulation
  always @ (posedge clk) begin
    if (reset) begin
      demodulated_data <= 16'b0000000000000000;
      carrier_signal <= 16'b0000000000000000;
    end else begin
      if (rx_in[15] != carrier_signal[15]) begin
        demodulated_data <= {demodulated_data[14:0], rx_in[15]};
      end
      carrier_signal <= {carrier_signal[14:0], rx_in[15]};
    end
  end

  // Bluetooth decoding scheme
  always @ (posedge clk) begin
    if (reset) begin
      decoded_data <= 8'b00000000;
      bit_counter <= 4'd0;
    end else begin
      if (bit_counter == 4'd3) begin
        decoded_data <= {demodulated_data[6], demodulated_data[5], demodulated_data[4], demodulated_data[3], demodulated_data[2], demodulated_data[1], demodulated_data[0]};
        bit_counter <= 4'd0;
      end else begin
        bit_counter <= bit_counter + 1;
      end
    end
  end

  // Output data
  always @ (posedge clk) begin
    if (reset) begin
      data_out <= 8'b00000000;
    end else begin
      data_out <= decoded_data;
    end
  end

endmodule

module i2c_state_machine (
  input sda,
  input scl,
  input reset,
  output ack,
  output data
);

  // Define the states of the state machine
  parameter IDLE = 0;
  parameter START = 1;
  parameter ADDR_WRITE = 2;
  parameter ADDR_READ = 3;
  parameter DATA_WRITE = 4;
  parameter DATA_READ = 5;
  parameter STOP = 6;
  parameter ERROR = 7;

  // Define the internal signals of the state machine
  reg [2:0] state;
  reg [7:0] address;
  reg [7:0] data_out;
  reg [7:0] data_in;
  reg ack_out;
  reg ack_in;
  reg scl_out;
  reg sda_out;
  reg sda_in;
  reg error;

  // Define the clock generator
  always @(posedge scl or negedge reset) begin
    if (!reset) begin
      scl_out <= 1'b0;
    end else begin
      scl_out <= ~scl_out;
    end
  end

  // Define the state machine
  always @(posedge scl or negedge reset) begin
    if (!reset) begin
      state <= IDLE;
      address <= 8'b0;
      data_out <= 8'b0;
      data_in <= 8'b0;
      ack_out <= 1'b0;
      ack_in <= 1'b0;
      sda_out <= 1'b1;
      sda_in <= 1'b1;
      error <= 1'b0;
    end else begin
      case (state)
        IDLE: begin
          if (!sda) begin
            state <= START;
          end
        end
        START: begin
          sda_out <= 1'b0;
          if (scl && !sda) begin
            state <= ADDR_WRITE;
          end
        end
        ADDR_WRITE: begin
          if (scl && sda) begin
            address <= {1'b0, sda};
            state <= DATA_WRITE;
          end
        end
        ADDR_READ: begin
          if (scl && sda) begin
            address <= {1'b1, sda};
            state <= DATA_READ;
          end
        end
        DATA_WRITE: begin
          if (scl && sda) begin
            data_out <= sda;
            state <= ACK;
          end
        end
        DATA_READ: begin
          if (scl && !sda) begin
            data_in <= {data_in[6:0], sda};
            state <= ACK;
          end
        end
        ACK: begin
          ack_out <= 1'b0;
          if (scl) begin
            ack_in <= sda;
            if (ack_in) begin
              if (state == DATA_READ) begin
                state <= DATA_READ;
              end else begin
                state <= STOP;
              end
            end else begin
              error <= 1'b1;
              state <= ERROR;
            end
          end
        end
        STOP: begin
          sda_out <= 1'b0;
          if (!scl) begin
            ack_out <= 1'b1;
            state <= IDLE;
          end
        end
        ERROR: begin
          sda_out <= 1'b0;
          if (!scl) begin
            state <= IDLE;
          end
        end
      endcase
    end
  end

  // Define the output signals
  assign ack = ack_in;
  assign data = data_in;

  // Define the input and output buffers
  assign sda = sda_in;
  assign sda_out = sda;

endmodule

