module top_module (
    input clk,
    input reset,       // Synchronous active-high reset
    input [7:0] in,    // Input for priority encoder
    output [3:0] ena,  // Enable signal for each digit of Gray code to BCD counter
    output reg [3:0] q // Final output in decimal format
);

    // Priority encoder module
    priority_encoder pe(
        .in(in),
        .out(pe_out)
    );

    // Gray code to BCD counter module
    gray_to_bcd_counter gtbc(
        .clk(clk),
        .reset(reset),
        .ena(ena),
        .gray(gtbc_gray)
    );

    // Output decoder module
    output_decoder od(
        .pe_out(pe_out),
        .gtbc_gray(gtbc_gray),
        .q(q)
    );

    // Internal signals
    wire [2:0] pe_out;
    wire [13:0] gtbc_gray;

endmodule

// Priority encoder module
module priority_encoder (
    input [7:0] in,
    output reg [2:0] out
);
    always @(*) begin
        casez(in)
            8'b00000001: out = 0;
            8'b00000010: out = 1;
            8'b00000100: out = 2;
            8'b00001000: out = 3;
            8'b00010000: out = 4;
            8'b00100000: out = 5;
            8'b01000000: out = 6;
            8'b10000000: out = 7;
            default: out = 3'b111;
        endcase
    end
endmodule

// Gray code to BCD counter module
module gray_to_bcd_counter (
    input clk,
    input reset,       // Synchronous active-high reset
    input [3:0] ena,   // Enable signal for each digit
    output reg [13:0] gray // Gray code output
);
    always @(posedge clk) begin
        if (reset) begin
            gray <= 14'b00000000000000;
        end else begin
            if (ena[0]) begin
                gray[0] <= ~gray[0];
            end
            if (ena[1]) begin
                gray[1] <= gray[0] ^ ~gray[1];
            end
            if (ena[2]) begin
                gray[3:2] <= gray[1:0] ^ ~gray[3:2];
            end
            if (ena[3]) begin
                gray[7:4] <= gray[3:0] ^ ~gray[7:4];
            end
            gray <= gray + 1;
        end
    end
endmodule

// Output decoder module
module output_decoder (
    input [2:0] pe_out,         // Priority encoder output
    input [13:0] gtbc_gray,    // Gray code output from counter
    output reg [3:0] q          // Decimal output
);
    always @(*) begin
        case(pe_out)
            3'b000: q = gtbc_gray[3:0];
            3'b001: q = gtbc_gray[7:4];
            3'b010: q = gtbc_gray[11:8];
            default: q = 4'b1111;
        endcase
    end
endmodule

module LZD_48bit(
    input [47:0] in,
    output reg [5:0] out,
    output reg valid
);

wire v1, v2;
wire [4:0] l1, l2;

LZD_32bit d9(
    .in(in[31:0]),
    .out(l1),
    .valid(v1)
);

LZD_16bit d10(
    .in(in[47:32]),
    .out(l2),
    .valid(v2)
);

always @* begin
    if (in == 0) begin
        out <= 0;
        valid <= 1;
    end else if (in > 65535) begin
        out[5] <= v1 & v2;
        out[4:3] <= ~v2;
        out[2:0] <= {l1[3:0], l2[3:0]};
        valid <= v1 | v2;
    end else begin
        out[5] <= v2;
        out[4] <= 0;
        out[3:0] <= l2[3:0];
        valid <= v2;
    end
end

endmodule

