module multiplication_with_comparator (
  input clk,
  input reset,
  input [7:0] a,
  input [7:0] b,
  output reg [15:0] result
);

  wire [15:0] product;
  wire [7:0] sum1, sum2, sum3;
  wire [1:0] greater;

  carry_save_adder csa_inst (
    .a(a),
    .b(b),
    .sum1(sum1),
    .sum2(sum2),
    .sum3(sum3)
  );

  assign product = {sum1, sum2, sum3};

  comparator comp_inst (
    .a(a),
    .b(b),
    .greater(greater)
  );

  always @(posedge clk) begin
    if (reset) begin
      result <= 0;
    end else begin
      if (greater == 2'b01) begin
        result <= product;
      end else begin
        result <= 0;
      end
    end
  end

endmodule

module carry_save_adder (
  input [7:0] a,
  input [7:0] b,
  output reg [7:0] sum1,
  output reg [7:0] sum2,
  output reg [7:0] sum3
);

  always @(*) begin
    sum1 = a ^ b;
    sum2 = a & b;
    sum3 = {sum2[6:0], 1'b0} + {sum2[7], sum1[7:0]};
  end

endmodule

module comparator (
  input [7:0] a,
  input [7:0] b,
  output reg [1:0] greater
);

  always @(*) begin
    if (a > b) begin
      greater = 2'b10;
    end else if (a < b) begin
      greater = 2'b01;
    end else begin
      greater = 2'b00;
    end
  end

endmodule

