module interrupt_controller
(
  input wire iClock,
  input wire iReset,

   input wire        iMcuWe,
   input wire [3:0]  iMcuRegSelect, //control register select comes from cpu
   input wire [7:0]  iMcuWriteData, //what does the cpu want to write

   output wire[7:0]  oInterruptEnableRegister,
   output wire[7:0]  oInterruptFlag,


  input wire [7:0] iInterruptRequest,
  output reg [7:0] oInterruptResquestPending
);

  // Interrupt Enable register (0xFFFF)
  wire wWeInterrutpRegister;
  assign wWeInterrutpRegister = (iMcuWe & iMcuRegSelect == 4'h0) ? 1'b1 : 1'b0;
  FFD_POSEDGE_SYNCRONOUS_RESET # ( 8 ) FF_IE(
    iClock, iReset, wWeInterrutpRegister, iMcuWriteData, oInterruptEnableRegister
  );

  // Interrupt Flag register (0xFF0F)
  wire wWeInterruptFlag;
  assign wWeInterruptFlag = (iMcuWe & iMcuRegSelect == 4'hf) ? 1'b1 : 1'b0;
  FFD_POSEDGE_SYNCRONOUS_RESET_INIT # ( 8 ) FF_IF(
    iClock, iReset | wWeInterruptFlag, |iInterruptRequest, iMcuWriteData, iInterruptRequest, oInterruptFlag
  );

  // Determine which interrupts are pending
  wire [7:0] wPendingInterrupts;
  assign wPendingInterrupts = oInterruptFlag & oInterruptEnableRegister;

  // Set oInterruptRequestPending based on which interrupts are pending
  always @(*)
  begin
    case (wPendingInterrupts)
      8'h1: oInterruptResquestPending = 8'b00000001; // V-Blank
      8'h2: oInterruptResquestPending = 8'b00000010; // LCD STAT
      8'h4: oInterruptResquestPending = 8'b00000100; // Timer
      8'h8: oInterruptResquestPending = 8'b00001000; // Serial
      8'h10: oInterruptResquestPending = 8'b00010000; // Joypad
      default: oInterruptResquestPending = 8'b0;
    endcase
  end

endmodule

module not_gate( input in, output out );
    assign out = ~(in & in);
endmodule

module counter #( parameter max_val_p = 8'hFF
                , parameter init_val_p = 8'h00
                , parameter max_step_p = 8'h01 )(
    input clk_i,
    input reset_i,
    input [7:0] up_i,
    input [7:0] down_i,
    output reg [7:0] count_o
);

always @(posedge clk_i) begin
    if (reset_i) begin
        count_o <= init_val_p;
    end else begin
        if (up_i > max_step_p || down_i > max_step_p) begin
            $display("%m error: step size greater than max_step_p at time %t", $time);
        end else if (up_i > 0) begin
            if (count_o + up_i > max_val_p) begin
                $display("%m error: counter overflow at time %t", $time);
                count_o <= init_val_p;
            end else begin
                count_o <= count_o + up_i;
            end
        end else if (down_i > 0) begin
            if (count_o - down_i < 0) begin
                $display("%m error: counter underflow at time %t", $time);
                count_o <= max_val_p;
            end else begin
                count_o <= count_o - down_i;
            end
        end
    end
end

endmodule

module request_response (
  input CLK,
  input RST_N,
  input [76:0] client_request_put,
  input EN_client_request_put,
  output [64:0] client_response_get,
  input EN_client_response_get,
  output [76:0] server_request_get,
  input EN_server_request_get,
  input [64:0] server_response_put,
  input EN_server_response_put,
  output [426:0] trace_data_out_put,
  input EN_trace_data_out_put
);

  // internal registers
  reg [76:0] client_request;
  reg [64:0] server_response;
  reg [63:0] trace_data;
  reg [63:0] x__h577;

  // internal wires
  wire [76:0] server_request;
  wire [64:0] client_response;
  wire trace_data_en;

  // submodules
  fifo #(.width(77), .depth(16)) client_request_fifo (
    .CLK(CLK),
    .RST_N(RST_N),
    .D_IN(client_request_put),
    .EN_IN(EN_client_request_put),
    .D_OUT(client_request),
    .EN_OUT(EN_server_request_get),
    .FULL_N(client_request_fifo_full),
    .EMPTY_N(client_request_fifo_empty)
  );

  fifo #(.width(77), .depth(16)) server_request_fifo (
    .CLK(CLK),
    .RST_N(RST_N),
    .D_IN(server_request),
    .EN_IN(EN_client_response_get),
    .D_OUT(server_request_get),
    .EN_OUT(EN_server_response_put),
    .FULL_N(server_request_fifo_full),
    .EMPTY_N(server_request_fifo_empty)
  );

  fifo #(.width(65), .depth(16)) server_response_fifo (
    .CLK(CLK),
    .RST_N(RST_N),
    .D_IN(server_response_put),
    .EN_IN(EN_server_response_put),
    .D_OUT(server_response),
    .EN_OUT(EN_client_response_get),
    .FULL_N(server_response_fifo_full),
    .EMPTY_N(server_response_fifo_empty)
  );

  fifo #(.width(427), .depth(16)) trace_data_fifo (
    .CLK(CLK),
    .RST_N(RST_N),
    .D_IN(trace_data),
    .EN_IN(trace_data_en),
    .D_OUT(trace_data_out_put),
    .EN_OUT(EN_trace_data_out_put),
    .FULL_N(trace_data_fifo_full),
    .EMPTY_N(trace_data_fifo_empty)
  );

  // rule: client_request_to_server_request
  always @(posedge CLK) begin
    if (!RST_N) begin
      server_request <= 77'h0;
    end else if (EN_server_request_get && !server_request_fifo_full) begin
      server_request <= client_request;
    end
  end

  // rule: server_response_to_client_response
  always @(posedge CLK) begin
    if (!RST_N) begin
      client_response <= 65'h0;
    end else if (EN_client_response_get && !server_response_fifo_empty) begin
      client_response <= server_response;
    end
  end

  // rule: trace_data_generation
  always @(posedge CLK) begin
    if (!RST_N) begin
      trace_data <= 427'h0;
      x__h577 <= 64'h0;
    end else if (EN_trace_data_out_put && !trace_data_fifo_full) begin
      trace_data <= { 235'h0EAAAAAAAAAAAAAAA955555554AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA,
                      x__h577,
                      client_request[63:0],
                      64'hAAAAAAAAAAAAAAAA };
      trace_data_en <= 1'b1;
    end else begin
      trace_data_en <= 1'b0;
    end
  end

  // rule: x__h577_generation
  always @(posedge CLK) begin
    if (!RST_N) begin
      x__h577 <= 64'h0;
    end else if (EN_client_request_put) begin
      x__h577 <= { 52'h0, client_request[75:64] };
    end
  end

endmodule

module full_adder (
    A,
    B,
    Cin,
    Sum,
    Cout,
    V
);

    input [3:0] A;
    input [3:0] B;
    input Cin;
    output [3:0] Sum;
    output Cout;
    output V;

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire c1, c2, c3;

    sky130_fd_sc_hd__xor2_0 xor1 (
        .X(A[0]),
        .Y(B[0]),
        .Z(c1)
    );

    sky130_fd_sc_hd__xor2_0 xor2 (
        .X(A[1]),
        .Y(B[1]),
        .Z(c2)
    );

    sky130_fd_sc_hd__xor2_0 xor3 (
        .X(A[2]),
        .Y(B[2]),
        .Z(c3)
    );

    sky130_fd_sc_hd__and2_0 and1 (
        .A(c1),
        .B(c2),
        .Z(Sum[0])
    );

    sky130_fd_sc_hd__and2_0 and2 (
        .A(c2),
        .B(c3),
        .Z(Sum[1])
    );

    sky130_fd_sc_hd__and2_0 and3 (
        .A(c1),
        .B(c3),
        .Z(Cout)
    );

    sky130_fd_sc_hd__or2_0 or1 (
        .A(Cin),
        .B(Cout),
        .X(V)
    );

    assign Sum[2] = A[2] ^ B[2] ^ Cout;
    assign Sum[3] = A[3] ^ B[3] ^ V;

endmodule

module counter_4bit(
    input clk,
    input reset,
    input enable,
    input control,
    output max_min,
    output reg [3:0] count
);

    always @(posedge clk) begin
        if (reset) begin
            count <= 4'b0;
            max_min <= 1'b0;
        end
        else if (enable) begin
            if (control) begin
                if (count == 4'b1111) begin
                    count <= 4'b0;
                    max_min <= 1'b1;
                end
                else begin
                    count <= count + 1;
                    max_min <= 1'b0;
                end
            end
            else begin
                if (count == 4'b0000) begin
                    count <= 4'b1111;
                    max_min <= 1'b1;
                end
                else begin
                    count <= count - 1;
                    max_min <= 1'b0;
                end
            end
        end
    end

endmodule

module pipelined_multiplier(
    input clk,
    input [31:0] A,
    input [31:0] B,
    input load,
    output reg [63:0] C
);

reg [15:0] A0, A1, A2, B0, B1, B2;
reg [31:0] P0, P1, P2;

always @(posedge clk) begin
    if (load) begin
        A0 <= A[15:0];
        A1 <= A[31:16];
        A2 <= 16'h0;
        B0 <= B[15:0];
        B1 <= B[31:16];
        B2 <= 16'h0;
        C <= 64'h0;
    end else begin
        P0 <= A0 * B0;
        P1 <= A1 * B1;
        P2 <= A2 * B2;
        C <= {P2[31:0], P1[47:16], P0[63:32]} + C;
        A0 <= A[31:16];
        A1 <= A2;
        A2 <= 16'h0;
        B0 <= B[31:16];
        B1 <= B2;
        B2 <= 16'h0;
    end
end

always @(posedge clk) begin
    if (!load) begin
        A2 <= A[47:32];
        B2 <= B[47:32];
        P0 <= A1 * B0;
        P1 <= A2 * B1;
        P2 <= A2 * B2;
        C <= {P2[31:0], P1[47:16], P0[63:32]} + C;
    end
end

endmodule

module niosII_system_switches (
                                // inputs:
                                 address,
                                 clk,
                                 in_port,
                                 reset_n,

                                // outputs:
                                 readdata
                              )
;

  output  [ 31: 0] readdata;
  input   [  1: 0] address;
  input            clk;
  input   [  7: 0] in_port;
  input            reset_n;

  wire             clk_en;
  wire    [  7: 0] data_in;
  wire    [  7: 0] read_mux_out;
  reg     [ 31: 0] readdata;
  assign clk_en = 1;

  //s1, which is an e_avalon_slave
  assign read_mux_out = {8 {(address == 0)}} & data_in;

  always @(posedge clk or negedge reset_n)
    begin
      if (reset_n == 0)
          readdata <= 0;
      else if (clk_en) begin
          case (address)
            2'b00: readdata <= {24'b0, data_in};
            2'b01: readdata <= {24'b0, data_in};
            2'b10: readdata <= {24'b0, data_in};
            2'b11: readdata <= {data_in, data_in, data_in, data_in};
            default: readdata <= 0;
          endcase
      end
    end

  assign data_in = in_port;

endmodule

module altpcie_tl_cfg_pipe
  (
   input             clk,
   input             srst,
   output reg [ 3:0] o_tl_cfg_add,
   output reg [31:0] o_tl_cfg_ctl,
   output reg        o_tl_cfg_ctl_wr,
   output reg [52:0] o_tl_cfg_sts,
   output reg        o_tl_cfg_sts_wr,
   input  [ 3:0]     i_tl_cfg_add,
   input  [31:0]     i_tl_cfg_ctl,
   input             i_tl_cfg_ctl_wr,
   input  [52:0]     i_tl_cfg_sts,
   input             i_tl_cfg_sts_wr
   );

   reg sts_wr_r,sts_wr_rr;
   reg ctl_wr_r,ctl_wr_rr;

   always @ (posedge clk)
     begin
     if (srst)
       begin
       o_tl_cfg_add <= 4'h0;
       o_tl_cfg_ctl <= {32{1'b0}};
       o_tl_cfg_ctl_wr <= {1{1'b0}};
       o_tl_cfg_sts <= {53{1'b0}};
       o_tl_cfg_sts_wr <= {1{1'b0}};
       end
     else
       begin
       // sts pipeline
       sts_wr_r <= i_tl_cfg_sts_wr;
       sts_wr_rr <= sts_wr_r;
       o_tl_cfg_sts_wr <= sts_wr_rr;
       if (o_tl_cfg_sts_wr != sts_wr_rr)
	 o_tl_cfg_sts <= i_tl_cfg_sts;

       // ctl pipeline
       ctl_wr_r <= i_tl_cfg_ctl_wr;
       ctl_wr_rr <= ctl_wr_r;
       o_tl_cfg_ctl_wr <= ctl_wr_rr;
       if (o_tl_cfg_ctl_wr != ctl_wr_rr)
	 begin
	 o_tl_cfg_add <= i_tl_cfg_add;
	 o_tl_cfg_ctl <= i_tl_cfg_ctl;
	 end

       end
     end
endmodule

module FSM (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 4; // number of input signals
parameter m = 2; // number of output signals
parameter s = 8; // number of states in the original FSM
parameter sm = 6; // number of states in the merged FSM

// Define the states of the original FSM
parameter S0 = 3'b000;
parameter S1 = 3'b001;
parameter S2 = 3'b010;
parameter S3 = 3'b011;
parameter S4 = 3'b100;
parameter S5 = 3'b101;
parameter S6 = 3'b110;
parameter S7 = 3'b111;

// Define the merged states of the FSM
parameter MS0 = 3'b000;
parameter MS1 = 3'b001;
parameter MS2 = 3'b010;
parameter MS3 = 3'b011;
parameter MS4 = 3'b100;
parameter MS5 = 3'b101;

// Define the output functions for each state
assign out[0] = (in[0] & in[1]) | (in[2] & in[3]); // Output 1 for states S0, S1, S2, S3
assign out[1] = (in[0] & in[2]) | (in[1] & in[3]); // Output 2 for states S4, S5, S6, S7

// Define the next state function for each state and input combination
always @ (in) begin
  case (in)
    S0: out = {MS0, MS1}; // Next state for input 0
    S1: out = {MS2, MS3}; // Next state for input 0
    S2: out = {MS0, MS1}; // Next state for input 0
    S3: out = {MS2, MS3}; // Next state for input 0
    S4: out = {MS4, MS5}; // Next state for input 1
    S5: out = {MS4, MS5}; // Next state for input 1
    S6: out = {MS4, MS5}; // Next state for input 1
    S7: out = {MS4, MS5}; // Next state for input 1
  endcase
end

endmodule

module top_module (
    input [3:0] ABCD,
    output reg [15:0] out,
    output reg [3:0] count,
    output [3:0] final_out
);

    wire [15:0] decoder_out;
    wire [3:0] bit_count_out;

    decoder_4to16 decoder(
        .in(ABCD),
        .out(decoder_out)
    );

    bit_counter counter(
        .in(decoder_out),
        .out(bit_count_out)
    );

    assign final_out = count + decoder_out;

    always @(*) begin
        out = decoder_out;
        count = bit_count_out;
    end

endmodule

module decoder_4to16 (
    input [3:0] in,
    output reg [15:0] out
);

    always @(*) begin
        case(in)
            4'b0001: out = 16'b0000000000000001;
            4'b0010: out = 16'b0000000000000010;
            4'b0011: out = 16'b0000000000000100;
            4'b0100: out = 16'b0000000000001000;
            4'b0101: out = 16'b0000000000010000;
            4'b0110: out = 16'b0000000000100000;
            4'b0111: out = 16'b0000000001000000;
            4'b1000: out = 16'b0000000010000000;
            4'b1001: out = 16'b0000000100000000;
            4'b1010: out = 16'b0000001000000000;
            4'b1011: out = 16'b0000010000000000;
            4'b1100: out = 16'b0000100000000000;
            4'b1101: out = 16'b0001000000000000;
            4'b1110: out = 16'b0010000000000000;
            4'b1111: out = 16'b0100000000000000;
            default: out = 16'b0000000000000000;
        endcase
    end

endmodule

module bit_counter (
    input [15:0] in,
    output reg [3:0] out
);

    wire [3:0] p[3:0];

    assign p[0] = in[0:3];
    assign p[1] = in[4:7];
    assign p[2] = in[8:11];
    assign p[3] = in[12:15];

    prefix_adder adder1(
        .a(p[0]),
        .b(p[1]),
        .c({2'b00, out[2:1]}),
        .s(p[0])
    );

    prefix_adder adder2(
        .a(p[2]),
        .b(p[3]),
        .c({2'b00, out[3]}),
        .s(p[2])
    );

    prefix_adder adder3(
        .a(p[0]),
        .b(p[2]),
        .c({2'b00, out[1]}),
        .s(p[0])
    );

    prefix_adder adder4(
        .a(p[0]),
        .b(p[1]),
        .c({2'b00, out[0]}),
        .s(p[0])
    );

endmodule

module prefix_adder (
    input [3:0] a,
    input [3:0] b,
    input [2:0] c,
    output reg [3:0] s
);

    wire [3:0] p, g;

    assign p = a ^ b;
    assign g = a & b;

    always @(*) begin
        s[0] = p[0] ^ c[0];
        s[1] = p[1] ^ (g[0] & c[0]);
        s[2] = p[2] ^ ((g[1] | (g[0] & c[0])) & c[1]);
        s[3] = p[3] ^ ((g[2] | (g[1] & c[1])) & c[2]);
    end

endmodule

module signal_module(
    input clk,
    input reset,
    input [3:0] data_in,
    input enable,
    output [3:0] data_out,
    output parity,
    output overflow,
    output underflow
);

reg [3:0] data_out_reg;
reg parity_reg;
reg overflow_reg;
reg underflow_reg;

always @(posedge clk) begin
    if (reset) begin
        data_out_reg <= 4'b0000;
        parity_reg <= 1'b0;
        overflow_reg <= 1'b0;
        underflow_reg <= 1'b0;
    end else if (enable) begin
        data_out_reg <= data_out_reg + data_in;
        parity_reg <= ~parity_reg;
        overflow_reg <= (data_out_reg + data_in) > 4'b1111;
        underflow_reg <= (data_out_reg + data_in) < 4'b0000;
    end
end

assign data_out = data_out_reg;
assign parity = parity_reg;
assign overflow = overflow_reg;
assign underflow = underflow_reg;

endmodule

module top_module (
    input clk,
    input reset,
    input [7:0] dividend,
    input [7:0] divisor,
    input [3:0] A,
    input [3:0] B,
    input sub,
    output reg [7:0] quotient,
    output reg [7:0] remainder,
    output reg [3:0] sum,
    output reg carry,
    output reg [7:0] final_output
);

// Instantiate the signed divider module
signed_divider div_inst (
    .clk(clk),
    .reset(reset),
    .dividend(dividend),
    .divisor(divisor),
    .quotient(quotient),
    .remainder(remainder)
);

// Instantiate the ripple carry adder/subtractor module
ripple_carry_adder_subtractor add_sub_inst (
    .A(A),
    .B(B),
    .sub(sub),
    .sum(sum),
    .carry(carry)
);

// Addictive functional module
always @(*) begin
    if (carry == 1'b0) begin
        final_output = remainder + sum;
    end else begin
        final_output = remainder + sum + 1;
    end
end

endmodule

// Signed Divider module
module signed_divider (
    input clk,
    input reset,
    input signed [7:0] dividend,
    input signed [7:0] divisor,
    output reg signed [7:0] quotient,
    output reg signed [7:0] remainder
);

reg signed [7:0] dividend_reg;
reg signed [7:0] divisor_reg;
reg signed [7:0] quotient_reg;
reg signed [7:0] remainder_reg;
reg signed [7:0] divisor_neg;

integer i;

always @(posedge clk) begin
    if (reset) begin
        dividend_reg <= 0;
        divisor_reg <= 0;
        quotient_reg <= 0;
        remainder_reg <= 0;
    end else begin
        dividend_reg <= dividend;
        divisor_reg <= divisor;
    end
end

always @(*) begin
    if (dividend_reg[7] == 1'b0) begin
        divisor_neg = -divisor_reg;
    end else begin
        divisor_neg = divisor_reg;
    end
end

always @(posedge clk) begin
    if (reset) begin
        quotient_reg <= 0;
        remainder_reg <= 0;
    end else begin
        quotient_reg <= 0;
        remainder_reg <= dividend_reg;
        for (i = 7; i >= 0; i = i - 1) begin
            remainder_reg <= remainder_reg << 1;
            remainder_reg[0] <= dividend_reg[i];
            if (remainder_reg >= 0) begin
                remainder_reg <= remainder_reg - divisor_neg;
                quotient_reg[i] <= 1;
            end
        end
    end
end

assign quotient = quotient_reg;
assign remainder = remainder_reg;

endmodule

// Ripple Carry Adder/Subtractor module
module ripple_carry_adder_subtractor (
    input [3:0] A,
    input [3:0] B,
    input sub,
    output reg [3:0] sum,
    output reg carry
);

reg [3:0] sum_reg;
reg carry_reg;

always @(*) begin
    if (sub == 1'b0) begin
        sum_reg = A + B;
        carry_reg = (sum_reg[4] == 1'b1) ? 1'b1 : 1'b0;
    end else begin
        sum_reg = A - B;
        carry_reg = (sum_reg[4] == 1'b0) ? 1'b1 : 1'b0;
    end
end

assign sum = sum_reg[3:0];
assign carry = carry_reg;

endmodule

module xor_gate(
    input a,
    input b,
    output out
);

    assign out = (a & ~b) | (~a & b);

endmodule
module xor_module(
    input clk,
