                D[3]: priority = 3'b100;
                D[2]: priority = 3'b010;
                D[1]: priority = 3'b001;
                D[0]: priority = 3'b000;
                default: priority = 3'b000;
            endcase
        end else begin
            priority = 3'b000;
        end
    end

    always @ (priority) begin
        case (priority)
            3'b100: Y = D[3];
