module combinational_circuit (
    input [3:0] in,
    output out_nand,
    output out_nor,
    output out_xnor
);

    wire [3:0] inv_in;
    wire nand1, nand2, nand3, nand4;
    wire nor1, nor2, nor3, nor4;
    wire xnor1, xnor2, xnor3, xnor4;

    assign inv_in = ~in;

    assign nand1 = inv_in[0] & inv_in[1] & inv_in[2] & inv_in[3];
    assign nand2 = inv_in[0] & inv_in[1] & inv_in[2] & in[3];
    assign nand3 = inv_in[0] & inv_in[1] & in[2] & inv_in[3];
    assign nand4 = inv_in[0] & in[1] & inv_in[2] & inv_in[3];

    assign nor1 = inv_in[0] | inv_in[1] | inv_in[2] | inv_in[3];
    assign nor2 = inv_in[0] | inv_in[1] | inv_in[2] | in[3];
    assign nor3 = inv_in[0] | inv_in[1] | in[2] | inv_in[3];
    assign nor4 = inv_in[0] | in[1] | inv_in[2] | inv_in[3];

    assign xnor1 = ~(inv_in[0] ^ inv_in[1] ^ inv_in[2] ^ inv_in[3]);
    assign xnor2 = ~(inv_in[0] ^ inv_in[1] ^ inv_in[2] ^ in[3]);
    assign xnor3 = ~(inv_in[0] ^ inv_in[1] ^ in[2] ^ inv_in[3]);
    assign xnor4 = ~(inv_in[0] ^ in[1] ^ inv_in[2] ^ inv_in[3]);

    assign out_nand = nand1;
    assign out_nor = nor1;
    assign out_xnor = xnor1;

endmodule

module functional_module (
