    input [2:0] b,
    output [2:0] out_xor,
    output [5:0] out_not,
    output out_final
);

    wire [2:0] inv_a, inv_b;
    wire xor1, xor2, xor3;

    assign inv_a = ~a;
    assign inv_b = ~b;

    assign xor1 = inv_a[0] ^ inv_b[0];
    assign xor2 = inv_a[1] ^ inv_b[1];
    assign xor3 = inv_a[2] ^ inv_b[2];

    assign out_xor = {xor3, xor2, xor1};
    assign out_not = {inv_b[2], inv_b[1], inv_b[0], inv_a[2], inv_a[1], inv_a[0]};

    assign out_final = out_nand & out_nor & out_xnor & xor1 & xor2 & xor3;

endmodule

