    sky130_fd_sc_hd__buf_6 buf_C (.A(C), .X(C_buf), .VPWR(1'b1), .VGND(1'b0), .VPB(1'b0), .VNB(1'b0));
    sky130_fd_sc_hd__buf_6 buf_D (.A(D), .X(D_buf), .VPWR(1'b1), .VGND(1'b0), .VPB(1'b0), .VNB(1'b0));

    assign not_S0 = ~S0;
    assign not_S1 = ~S1;
    assign not_S0_and_not_S1 = not_S0 & not_S1;
    assign not_S0_and_S1 = not_S0 & S1;
    assign S0_and_not_S1 = S0 & not_S1;
    assign S0_and_S1 = S0 & S1;

    assign Y = not_S0_and_not_S1 & A_buf |
               not_S0_and_S1 & B_buf |
               S0_and_not_S1 & C_buf |
               S0_and_S1 & D_buf;

endmodule

module binary_to_bcd(
    input clk,
    input reset,
    input signed [31:0] in,
    output [39:0] out
);

    reg [39:0] bcd_out;
    reg [31:0] temp_in;
    reg [3:0] nibble;
    reg [4:0] i;

    always @ (posedge clk) begin
        if (reset) begin
            bcd_out <= 40'b0;
            temp_in <= 32'd0;
            nibble <= 4'd0;
            i <= 5'd0;
        end else begin
            temp_in <= in;
            bcd_out <= 40'b0;
            for (i = 0; i < 32; i = i + 1) begin
                nibble <= nibble + (temp_in[i] << 3);
                nibble <= nibble + (temp_in[i] << 2);
                nibble <= nibble + (temp_in[i] << 1);
                if (nibble >= 10) begin
                    nibble <= nibble + 6;
                end
                bcd_out[i+7] <= nibble;
                nibble <= 4'd0;
            end
        end
    end

    assign out = bcd_out;

endmodule

