module sync_module (
    Q,
    CLK,
    D,
    SCD,
    SCE,
    RST,
    EN
);

    output Q;
    input CLK;
    input D;
    input SCD;
    input SCE;
    input RST;
    input EN;

    parameter delay_cycles = 1;

    wire [delay_cycles-1:0] delay_line;
    assign delay_line[0] = D;

    genvar i;
    generate
        for (i = 1; i < delay_cycles; i = i + 1) begin
            assign delay_line[i] = delay_line[i-1];
        end
    endgenerate

    wire Q_sync;
    sky130_fd_sc_lp__sdfxtp_1 base (
        .Q(Q_sync),
        .CLK(CLK),
        .D(delay_line[delay_cycles-1]),
        .SCD(SCD),
        .SCE(SCE)
    );

    always @ (posedge CLK or posedge RST) begin
        if (RST) begin
            Q <= 0;
        end else begin
            if (EN) begin
                Q <= Q_sync;
            end else begin
                Q <= 0;
            end
        end
    end

endmodule

