module top_module (
    input [7:0] a,
    input [7:0] b,
    input clk,
    input reset,
    output [7:0] s,
    output overflow
);

    wire [7:0] sum;
    wire carry_out;
    wire [7:0] neg_b;
    wire [7:0] neg_b_plus_1;
    wire [7:0] neg_sum;

    adder_module adder_inst (
        .a(a),
        .b(b),
        .s(sum),
        .overflow(carry_out)
    );

    dff_inverter_module neg_b_inst (
        .clk(clk),
        .d(~b),
        .q(neg_b)
    );

    adder_module neg_b_plus_1_inst (
        .a(neg_b),
        .b({8'b0, 1'b1}),
        .s(neg_b_plus_1),
        .overflow()
    );

    adder_module neg_sum_inst (
        .a(~sum),
        .b({8'b0, 1'b1}),
        .s(neg_sum),
        .overflow()
    );

    assign s = sum;
    assign overflow = carry_out | (neg_b[7] & neg_b_plus_1[7]) | (sum[7] & neg_sum[7]);

endmodule

