module top_module (
    input [1:0] a,
    input [1:0] b,
    input [15:0] in,
    input parity,
    output reg [2:0] pos,
    output reg [15:0] out
);

wire [15:0] xor_result;
wire [3:0] decoder_out;
wire [3:0] priority_encoder_out;

// XOR gate to calculate the parity bit
assign xor_result = in ^ 16'b1111111111111110;

// 4-to-16 decoder using NAND gates
nand n1(a[0], a[1], b[0], b[1], decoder_out[0]);
nand n2(a[0], a[1], b[0], ~b[1], decoder_out[1]);
nand n3(a[0], a[1], ~b[0], b[1], decoder_out[2]);
nand n4(a[0], a[1], ~b[0], ~b[1], decoder_out[3]);
nand n5(~a[0], a[1], b[0], b[1], decoder_out[4]);
nand n6(~a[0], a[1], b[0], ~b[1], decoder_out[5]);
nand n7(~a[0], a[1], ~b[0], b[1], decoder_out[6]);
nand n8(~a[0], a[1], ~b[0], ~b[1], decoder_out[7]);
nand n9(a[0], ~a[1], b[0], b[1], decoder_out[8]);
nand n10(a[0], ~a[1], b[0], ~b[1], decoder_out[9]);
nand n11(a[0], ~a[1], ~b[0], b[1], decoder_out[10]);
nand n12(a[0], ~a[1], ~b[0], ~b[1], decoder_out[11]);
nand n13(~a[0], ~a[1], b[0], b[1], decoder_out[12]);
nand n14(~a[0], ~a[1], b[0], ~b[1], decoder_out[13]);
nand n15(~a[0], ~a[1], ~b[0], b[1], decoder_out[14]);
nand n16(~a[0], ~a[1], ~b[0], ~b[1], decoder_out[15]);

// Priority encoder to find the first different bit
priority_encoder pe(decoder_out, priority_encoder_out);

always @(*) begin
    if (parity == 1) begin
        out = in;
        pos = 3'b000;
    end else begin
        out = in ^ (1 << priority_encoder_out);
        pos = priority_encoder_out;
    end
end

endmodule

// Priority encoder module
module priority_encoder (
    input [15:0] in,
    output reg [3:0] out
);

always @(*) begin
    if (in[0] == 1'b1) begin
        out = 4'b0000;
    end else if (in[1] == 1'b1) begin
        out = 4'b0001;
    end else if (in[2] == 1'b1) begin
        out = 4'b0010;
    end else if (in[3] == 1'b1) begin
        out = 4'b0011;
    end else if (in[4] == 1'b1) begin
        out = 4'b0100;
    end else if (in[5] == 1'b1) begin
        out = 4'b0101;
    end else if (in[6] == 1'b1) begin
        out = 4'b0110;
    end else if (in[7] == 1'b1) begin
        out = 4'b0111;
    end else if (in[8] == 1'b1) begin
        out = 4'b1000;
    end else if (in[9] == 1'b1) begin
        out = 4'b1001;
    end else if (in[10] == 1'b1) begin
        out = 4'b1010;
    end else if (in[11] == 1'b1) begin
        out = 4'b1011;
    end else if (in[12] == 1'b1) begin
        out = 4'b1100;
    end else if (in[13] == 1'b1) begin
        out = 4'b1101;
    end else if (in[14] == 1'b1) begin
        out = 4'b1110;
    end else if (in[15] == 1'b1) begin
        out = 4'b1111;
    end
end

