  buf #(.delay(1)) clrn_buf(clrn, clrn_buf_out);
  buf #(.delay(1)) prn_buf(prn, prn_buf_out);
  buf #(.delay(1)) ena_buf(ena, ena_buf_out);
  buf #(.delay(1)) d_buf(d, d_buf_out);

  // Internal signals
  reg q_reg;
  wire q_wire;
  wire q_preset;

