module fsm_pattern_detection (
  input clk,
  input reset,
  input data,
  output reg match
);

reg [1:0] state;
parameter A = 2'b00, B = 2'b01, C = 2'b10, D = 2'b11;

always @(posedge clk) begin
  if (reset) begin
    state <= A;
    match <= 0;
  end
  else begin
    case (state)
      A: begin
        if (data) state <= B;
        else state <= A;
      end
      B: begin
        if (data) state <= C;
        else state <= A;
      end
      C: begin
        if (data) state <= D;
        else state <= A;
      end
      D: begin
        match <= 1;
        state <= A;
      end
      default: state <= A;
    endcase
  end
end

endmodule

module byte_swapper (
    input wire [15:0] in, // 16-bit input word
    output wire [7:0] out_hi, // Upper byte output
    output wire [7:0] out_lo // Lower byte output
);

    wire [7:0] in_hi = in[15:8]; // Extract upper byte
    wire [7:0] in_lo = in[7:0]; // Extract lower byte

    // Swap upper and lower bytes using 2-input muxes and demuxes
    wire [7:0] out_hi_mux_sel = {in_lo[0], in_hi[0]}; // Select input for upper byte output
    wire [7:0] out_lo_mux_sel = {in_hi[0], in_lo[0]}; // Select input for lower byte output

    wire [7:0] out_hi_muxed;
    wire [7:0] out_lo_muxed;

    // Upper byte output
    demux2x1 demux_out_hi_mux_sel (
        .in(out_hi_mux_sel),
