module compressor_processor(
    input clk,
    input rst,
    input [15:0] data_in,
    input start,
    input done,
    output [15:0] data_out,
    output compressor_done,
    output irq
);

    reg [15:0] compressed_data;
    reg [15:0] uncompressed_data;
    reg [15:0] current_data;
    reg [15:0] next_data;
    reg [3:0] count;
    reg [3:0] current_count;
    reg [3:0] next_count;
    reg [1:0] state;
    reg [1:0] next_state;
    reg compressor_done_reg;
    reg irq_reg;

    always @(posedge clk) begin
        if (rst) begin
            state <= 2'b00;
            current_data <= 16'b0;
            next_data <= 16'b0;
            count <= 4'b0;
            current_count <= 4'b0;
            next_count <= 4'b0;
            compressed_data <= 16'b0;
            uncompressed_data <= 16'b0;
            compressor_done_reg <= 1'b0;
            irq_reg <= 1'b0;
        end else begin
            state <= next_state;
            current_data <= next_data;
            current_count <= next_count;
            compressor_done_reg <= 1'b0;
            irq_reg <= 1'b0;
        end
    end

    always @(*) begin
        next_state = state;
        next_data = current_data;
        next_count = current_count;
        compressor_done = compressor_done_reg;
        irq = irq_reg;

        case (state)
            2'b00: begin // idle state
                if (start) begin
                    next_state = 2'b01;
                    next_data = data_in;
                    next_count = 4'b1;
                end else begin
                    next_data = 16'b0;
                    next_count = 4'b0;
                end
            end
            2'b01: begin // compressing state
                if (done) begin
                    next_state = 2'b10;
                    next_data = compressed_data;
                end else begin
                    if (data_in == current_data) begin
                        next_count = current_count + 1;
                    end else begin
                        if (current_count > 1) begin
                            next_data = {current_data[15:8], current_count};
                            next_count = 4'b1;
                            compressed_data = {compressed_data, next_data};
                        end else begin
                            compressed_data = {compressed_data, current_data};
                        end
                        next_data = data_in;
                    end
                end
            end
            2'b10: begin // outputting compressed data state
                if (compressed_data > uncompressed_data) begin
                    next_state = 2'b11;
                    next_data = uncompressed_data;
                end else begin
                    compressor_done_reg = 1'b1;
                    irq_reg = 1'b1;
                end
            end
            2'b11: begin // outputting uncompressed data state
                compressor_done_reg = 1'b1;
                irq_reg = 1'b1;
            end
        endcase
    end

    assign data_out = next_data;

endmodule

