module traffic_light(
    input clk,
    input reset,
    input ns_sensor,
    input ew_sensor,
    output reg ns_green,
    output reg ns_yellow,
    output reg ns_red,
    output reg ew_green,
    output reg ew_yellow,
    output reg ew_red
);

// constants
localparam GREEN_TIME = 10; // duration of green light
localparam YELLOW_TIME = 2; // duration of yellow light
localparam RED_TIME = 8; // duration of red light
localparam NS_PRIORITY_TIME = 20; // duration of North-South priority
localparam EW_PRIORITY_TIME = 10; // duration of East-West priority

// state variables
reg [3:0] ns_state; // North-South state machine
reg [3:0] ew_state; // East-West state machine
reg [4:0] timer; // timer for each state

// state machine states
localparam NS_GREEN = 4'b0001;
localparam NS_YELLOW = 4'b0010;
localparam NS_RED = 4'b0100;
localparam EW_GREEN = 4'b1000;
localparam EW_YELLOW = 4'b1010;
localparam EW_RED = 4'b1100;

// initialize state machines
initial begin
    ns_state = NS_GREEN;
    ew_state = EW_RED;
end

// state machine for North-South road
always @(posedge clk, negedge reset) begin
    if (!reset) begin
        ns_state <= NS_GREEN;
        timer <= 0;
    end else begin
        case (ns_state)
            NS_GREEN: begin
                if (timer == GREEN_TIME) begin
                    ns_state <= NS_YELLOW;
                    timer <= 0;
                end
            end
            NS_YELLOW: begin
                if (timer == YELLOW_TIME) begin
                    ns_state <= NS_RED;
                    timer <= 0;
                end
            end
            NS_RED: begin
                if (timer == RED_TIME) begin
                    ns_state <= NS_GREEN;
                    timer <= 0;
                end
            end
        endcase

        // check for priority switch
        if (timer == NS_PRIORITY_TIME) begin
            ns_state <= NS_GREEN;
            ew_state <= EW_GREEN;
            timer <= 0;
        end

        // increment timer
        timer <= timer + 1;
    end
end

// state machine for East-West road
always @(posedge clk, negedge reset) begin
    if (!reset) begin
        ew_state <= EW_RED;
    end else begin
        case (ew_state)
            EW_GREEN: begin
                if (timer == GREEN_TIME) begin
                    ew_state <= EW_YELLOW;
                    timer <= 0;
                end
            end
            EW_YELLOW: begin
                if (timer == YELLOW_TIME) begin
                    ew_state <= EW_RED;
                    timer <= 0;
                end
            end
            EW_RED: begin
                if (timer == RED_TIME) begin
                    ew_state <= EW_GREEN;
                    timer <= 0;
                end
            end
        endcase

        // check for priority switch
        if (timer == EW_PRIORITY_TIME) begin
            ns_state <= NS_GREEN;
            ew_state <= EW_GREEN;
            timer <= 0;
        end

        // increment timer
        timer <= timer + 1;
    end
end

// control signals for North-South road
always @(*) begin
    case (ns_state)
        NS_GREEN: begin
            ns_green = 1;
            ns_yellow = 0;
            ns_red = 0;
        end
        NS_YELLOW: begin
            ns_green = 0;
            ns_yellow = 1;
            ns_red = 0;
        end
        NS_RED: begin
            ns_green = 0;
            ns_yellow = 0;
            ns_red = 1;
        end
    endcase
end

// control signals for East-West road
always @(*) begin
    case (ew_state)
        EW_GREEN: begin
            ew_green = 1;
            ew_yellow = 0;
            ew_red = 0;
        end
        EW_YELLOW: begin
            ew_green = 0;
            ew_yellow = 1;
            ew_red = 0;
        end
        EW_RED: begin
            ew_green = 0;
            ew_yellow = 0;
            ew_red = 1;
        end
    endcase
end

endmodule

