  dff dff3 (.CK(CLK), .D(count[3]), .Q(count[3]));

  always @(posedge CLK, posedge RST) begin
    if (RST) begin
      count <= 4'b0;
    end else begin
      count <= count + 1;
    end
  end

  assign Q = count;

