module i2c_readback
(
    input clk,
    input sync,
    input reset,

    input go,
    input rda,
    input sync2,
    input i2c_send,
    output [31:0]d
);

    // register to hold synchronized rda signal
    reg rdaff;
    always @(posedge clk or posedge reset) rdaff <= reset ? 0 : rda;

    // wire to indicate timeout
    wire nto;

    // wire to indicate last bit of data
    wire last;

    // wire to indicate whether I2C read operation is ongoing
    wire running;

    // timeout flip-flop
    srff_timeout ffto
    (
        .clk(clk),
        .sync(sync),
        .reset(reset),
        .s(go),
        .r(running),
        .to_disable(i2c_send),
        .q(nto)
    );

    // bit counter
    rda_bitcounter bitcounter
    (
        .aclr(reset),
        .clk_en(sync),
        .clock(clk),
        .cnt_en(running),
        .sset(sync && !rda && rdaff && nto),
        .cout(last),
        .q()
    );

    // assign running wire
    assign running = !last;

    // shift register
    reg [28:0]shiftreg;
    always @(posedge clk or posedge reset)
    begin
        if (reset) shiftreg <= 0;
        else if (running && sync) shiftreg <= {shiftreg[28:0], rdaff};
    end

    // data mapping
    wire [4:0]ha = shiftreg[7:3];
    wire [2:0]pa = shiftreg[2:0];
    wire [7:0]ra = {shiftreg[28:25], shiftreg[23:20]};
    wire [7:0]rd = {shiftreg[18:15], shiftreg[13:10]};
    wire start = shiftreg[8];
    wire _s3 = shiftreg[24];
    wire _rw = shiftreg[19];
    wire _d4 = shiftreg[14];
    wire _d0 = shiftreg[9];

    assign d = {running || nto, 2'b00, _s3, _rw, _d4, _d0, start, ha, pa, ra, rd};

endmodule

// timeout flip-flop module
module srff_timeout
(
    input clk,
    input sync,
    input reset,
    input s,
    input r,
    input to_disable,
    output q
);

    // timeout counter
    reg [31:0]timeout_cnt;

    always @(posedge clk or posedge reset)
    begin
        if (reset) timeout_cnt <= 0;
        else if (s) timeout_cnt <= 32'd0;
        else if (sync) timeout_cnt <= timeout_cnt + 32'd1;
    end

    // flip-flop
    reg qff;
    always @(posedge clk or posedge reset)
    begin
        if (reset) qff <= 0;
        else if (r) qff <= 0;
        else if (sync) qff <= qff ? 0 : (to_disable ? 0 : (timeout_cnt == 32'd100 ? 1 : 0));
    end

    assign q = qff;

endmodule

// bit counter module
module rda_bitcounter
(
    input aclr,
    input clk_en,
    input clock,
    input cnt_en,
    input sset,
    output cout,
    output reg [7:0] q
);

    // counter
    reg [3:0]cnt;

    always @(posedge clock or posedge aclr)
    begin
        if (aclr) cnt <= 4'd0;
        else if (clk_en && cnt_en) cnt <= cnt + 4'd1;
    end

    // output register
    always @(posedge clock or posedge aclr)
    begin
        if (aclr) q <= 8'd0;
        else if (clk_en && cnt_en && cnt == 4'd0) q <= sset ? 8'd0 : {q[6:0], sset};
    end

    // output wire
    assign cout = (cnt == 4'd1);

endmodule

