module min_finder_pipeline (
    input [7:0] a, b, c, d,
    output [7:0] min);

    reg [7:0] stage1_out, stage2_out, stage3_out;

    // Stage 1
    always @(*) begin
        if (a < b)
            stage1_out = a;
        else
            stage1_out = b;
    end

    // Stage 2
    always @(*) begin
        if (c < d)
            stage2_out = c;
        else
            stage2_out = d;
    end

    // Stage 3
    always @(*) begin
        if (stage1_out < stage2_out)
            stage3_out = stage1_out;
        else
            stage3_out = stage2_out;
    end

    // Output
    assign min = stage3_out;

endmodule

module fsm(X, RESET, CLOCK, Z);
  input X, RESET, CLOCK;
  output Z;

  // State variables
  output reg [1:0] CurrentState;
  reg [1:0] NextState;

  // State codes
  parameter State0 = 0, State1 = 1, State2 = 2, State3 = 3;

  // Output logic
  always @ (CurrentState)
    if (CurrentState == State0) Z <= 1;
    else if (CurrentState == State3) Z <= 0;
    else Z <= 0;

  // State registers
  always @ (posedge CLOCK)
    if (RESET == 1) CurrentState <= State0;
    else CurrentState <= NextState;

  // Next state logic
  always @ (CurrentState or X)
    case (CurrentState)
      State0: if (X == 0) NextState <= State1;
              else NextState <= State0;
      State1: if (X == 0) NextState <= State1;
              else NextState <= State0;
      State3: if (X == 0) NextState <= State1;
              else NextState <= State2;
      State2: NextState <= State2;
    endcase
endmodule

module routerConnection(
  input clk, rst,
  input [143:0] port_in, inj,
  output [143:0] port_out,
  output accept, push, eject,
  output bfull
);

  reg [143:0] buffer;
  reg [3:0] state;
  wire [3:0] nextState;

  connectRouter_nobuffer r(
    .clk(clk),
    .rst(rst),
    .port_in(buffer),
    .inj(buffer),
    .port_out(port_out),
    .accept(accept),
    .bfull(bfull),
    .eject(eject),
    .push(push)
  );

  always @(posedge clk) begin
    if (rst) begin
      state <= 0;
      buffer <= 0;
    end else begin
      state <= nextState;
      case (state)
        0: begin // IDLE
          if (push) begin
            buffer <= port_in;
            nextState <= 1;
          end else begin
            nextState <= 0;
          end
        end
        1: begin // WAIT FOR ACCEPT
          if (accept) begin
            nextState <= 2;
          end else begin
            nextState <= 1;
          end
        end
        2: begin // WAIT FOR EJECT
          if (eject) begin
            buffer <= 0;
            nextState <= 0;
          end else begin
            nextState <= 2;
          end
        end
      endcase
    end
  end

endmodule

