module fp_add (
  input [31:0] a,
  input [31:0] b,
  output reg [31:0] c
);

  reg [31:0] a_mantissa;
  reg [31:0] b_mantissa;
  reg [7:0] a_exponent;
  reg [7:0] b_exponent;
  reg a_sign;
  reg b_sign;
  reg c_sign;
  reg [7:0] c_exponent;
  reg [31:0] c_mantissa;
  reg carry;
  reg [31:0] temp;

  assign a_mantissa = {1'b1, a[22:0]};
  assign b_mantissa = {1'b1, b[22:0]};
  assign a_exponent = a[30:23];
  assign b_exponent = b[30:23];
  assign a_sign = a[31];
  assign b_sign = b[31];

  always @(*) begin
    if (a_exponent > b_exponent) begin
      c_exponent = a_exponent;
      b_mantissa = {b_mantissa, {8{1'b0}}};
      temp = b_mantissa >> (a_exponent - b_exponent);
    end else begin
      c_exponent = b_exponent;
      a_mantissa = {a_mantissa, {8{1'b0}}};
      temp = a_mantissa >> (b_exponent - a_exponent);
    end
    if (a_sign == b_sign) begin
      c_sign = a_sign;
      c_mantissa = a_mantissa + b_mantissa;
    end else begin
      if (a_mantissa > b_mantissa) begin
        c_sign = a_sign;
        c_mantissa = a_mantissa - b_mantissa;
      end else begin
        c_sign = b_sign;
        c_mantissa = b_mantissa - a_mantissa;
      end
    end
    if (c_mantissa[24]) begin
      carry = 1'b1;
      c_mantissa = c_mantissa >> 1;
      c_exponent = c_exponent + 1;
    end else begin
      carry = 1'b0;
    end
    if (c_exponent == 0 || c_exponent == 255) begin
      c = {8'b11111111, 23'b11111111111111111111111};
    end else begin
      c = {c_sign, c_exponent, c_mantissa[22:0]};
    end
  end

endmodule

module fp_sub (
  input [31:0] a,
  input [31:0] b,
  output reg [31:0] c
);

  reg [31:0] a_mantissa;
  reg [31:0] b_mantissa;
  reg [7:0] a_exponent;
  reg [7:0] b_exponent;
  reg a_sign;
  reg b_sign;
  reg c_sign;
  reg [7:0] c_exponent;
  reg [31:0] c_mantissa;
  reg borrow;
  reg [31:0] temp;

  assign a_mantissa = {1'b1, a[22:0]};
  assign b_mantissa = {1'b1, b[22:0]};
  assign a_exponent = a[30:23];
  assign b_exponent = b[30:23];
  assign a_sign = a[31];
  assign b_sign = b[31];

  always @(*) begin
    if (a_exponent > b_exponent) begin
      c_exponent = a_exponent;
      b_mantissa = {b_mantissa, {8{1'b0}}};
      temp = b_mantissa >> (a_exponent - b_exponent);
    end else begin
      c_exponent = b_exponent;
      a_mantissa = {a_mantissa, {8{1'b0}}};
      temp = a_mantissa >> (b_exponent - a_exponent);
    end
    if (a_sign != b_sign) begin
      c_sign = a_sign;
      c_mantissa = a_mantissa + b_mantissa;
    end else begin
      if (a_mantissa > b_mantissa) begin
        c_sign = a_sign;
        c_mantissa = a_mantissa - b_mantissa;
      end else begin
        c_sign = !b_sign;
        c_mantissa = b_mantissa - a_mantissa;
      end
    end
    if (c_mantissa[24]) begin
      borrow = 1'b0;
    end else begin
      borrow = 1'b1;
      c_mantissa = ~c_mantissa + 1;
    end
    if (c_exponent == 0 || c_exponent == 255) begin
      c = {8'b11111111, 23'b11111111111111111111111};
    end else begin
      c = {c_sign, c_exponent, c_mantissa[22:0]};
    end
  end

endmodule

module fp_mul (
  input [31:0] a,
  input [31:0] b,
  output reg [31:0] c
);

  reg [31:0] a_mantissa;
  reg [31:0] b_mantissa;
  reg [7:0] a_exponent;
  reg [7:0] b_exponent;
  reg a_sign;
  reg b_sign;
  reg c_sign;
  reg [7:0] c_exponent;
  reg [31:0] c_mantissa;
  reg [63:0] temp;
  reg [7:0] temp_exponent;
  reg [31:0] temp_mantissa;

  assign a_mantissa = {1'b1, a[22:0]};
  assign b_mantissa = {1'b1, b[22:0]};
  assign a_exponent = a[30:23];
  assign b_exponent = b[30:23];
  assign a_sign = a[31];
  assign b_sign = b[31];

  always @(*) begin
    temp = a_mantissa * b_mantissa;
    temp_exponent = a_exponent + b_exponent - 127;
    if (temp[63]) begin
      temp = temp >> 1;
      temp_exponent = temp_exponent + 1;
    end
    c_sign = a_sign ^ b_sign;
    temp_mantissa = temp[54:23];
    if (temp_exponent == 0 || temp_exponent == 255) begin
      c = {8'b11111111, 23'b11111111111111111111111};
    end else begin
      c = {c_sign, temp_exponent, temp_mantissa};
    end
  end

endmodule

module fp_div (
  input [31:0] a,
  input [31:0] b,
  output reg [31:0] c
);

  reg [31:0] a_mantissa;
  reg [31:0] b_mantissa;
  reg [7:0] a_exponent;
  reg [7:0] b_exponent;
  reg a_sign;
  reg b_sign;
  reg c_sign;
  reg [7:0] c_exponent;
  reg [31:0] c_mantissa;
  reg [63:0] temp;
  reg [7:0] temp_exponent;
  reg [31:0] temp_mantissa;

  assign a_mantissa = {1'b1, a[22:0]};
  assign b_mantissa = {1'b1, b[22:0]};
  assign a_exponent = a[30:23];
  assign b_exponent = b[30:23];
  assign a_sign = a[31];
  assign b_sign = b[31];

  always @(*) begin
    temp = a_mantissa;
    temp_exponent = a_exponent - b_exponent + 127;
    if (temp[23]) begin
      temp = temp << 1;
      temp_exponent = temp_exponent - 1;
    end
    temp = temp / b_mantissa;
    c_sign = a_sign ^ b_sign;
    temp_mantissa = temp[22:0];
    if (temp_exponent == 0 || temp_exponent == 255) begin
      c = {8'b11111111, 23'b11111111111111111111111};
    end else begin
      c = {c_sign, temp_exponent, temp_mantissa};
    end
  end

endmodule

