module booth_multiplier (
    input signed [3:0] a,
    input signed [3:0] b,
    output reg signed [7:0] out
);

reg signed [7:0] product;

always @(*) begin
    product = {a, 4'b0};
    case (b[3:0])
        4'b0000: out = 8'b00000000;
        4'b0001: out = product;
        4'b0010: out = product << 1;
        4'b0011: out = product + (product << 1);
        4'b0100: out = product << 2;
        4'b0101: out = (product << 1) + (product << 2);
        4'b0110: out = (product << 2) + (product << 1);
        4'b0111: out = (product << 3) - product;
        4'b1000: out = product << 3;
        4'b1001: out = (product << 3) + product;
        4'b1010: out = (product << 3) + (product << 1);
        4'b1011: out = (product << 3) + (product << 1) + product;
        4'b1100: out = (product << 3) + (product << 2);
        4'b1101: out = (product << 3) + (product << 2) + product;
        4'b1110: out = (product << 3) + (product << 2) + (product << 1);
        4'b1111: out = (product << 3) + (product << 2) + (product << 1) + product;
    endcase
end

endmodule

module add_sub (
