        result = $signed(A) + $signed(B);
    end else begin
        result = $signed(A) - $signed(B);
    end
    if (result > 7 || result < -8) begin
        OVF = 1;
    end else begin
        OVF = 0;
    end
    OUT = result[3:0];
end

endmodule

