module signal_generator #
    (
        parameter SIZE = 3200
    )
    (
        input wire EN,
        input wire TRIG,
        input wire [SIZE-1:0] DATA,
        input wire CLK_PE,
        input wire SYS_CLK,
        output wire GEN_SIGNAL
    );

    reg [31:0] clk_idx = 0;
    reg [SIZE-1:0] signal_reg = 0;

    always @(posedge SYS_CLK) begin
        if (TRIG) begin
            clk_idx <= 0;
            signal_reg <= 0;
        end else if (CLK_PE && (clk_idx >= 0)) begin
            if (clk_idx < SIZE) begin
                signal_reg <= DATA[clk_idx];
            end
            clk_idx <= clk_idx + 1;
        end
    end

    assign GEN_SIGNAL = EN && (clk_idx < SIZE) && signal_reg;

endmodule

