module memory_comp_decomp (
  input [n*k-1:0] data_in,
  input compress,
  output [m*k-1:0] data_out
);

parameter n = 16; // number of input data signals
parameter m = 16; // number of output data signals
parameter k = 8; // number of bits used to represent each data signal
parameter w = 4; // number of bits used to represent the compressed data

// Compression Algorithm
wire [n*w-1:0] compressed_data;
assign compressed_data = compress ? compress_data(data_in) : data_in;

// Decompression Algorithm
wire [m*k-1:0] decompressed_data;
assign decompressed_data = compress ? data_out : decompress_data(data_in);

// Output MUX
assign data_out = compress ? compressed_data : decompressed_data;

// Compression Function
function [n*w-1:0] compress_data;
  input [n*k-1:0] data;
  reg [n*w-1:0] compressed;
  integer i, j;
  begin
    for (i = 0; i < n; i = i + 1) begin
      for (j = 0; j < w; j = j + 1) begin
        compressed[i*w+j] = data[i*k+j];
      end
    end
    compress_data = compressed;
  end
endfunction

// Decompression Function
function [m*k-1:0] decompress_data;
  input [n*w-1:0] data;
  reg [m*k-1:0] decompressed;
  integer i, j;
  begin
    for (i = 0; i < m; i = i + 1) begin
      for (j = 0; j < k; j = j + 1) begin
        decompressed[i*k+j] = data[i*w+j];
      end
    end
    decompress_data = decompressed;
  end
endfunction

endmodule

module xnor_gate(
    input A,
    input B,
    input VPWR,
    input VGND,
    output Y
);

    reg [3:0] state = 4'b0000;
    reg [1:0] input_state = 2'b00;
    wire [1:0] xnor_out;

    assign xnor_out = ~^({A, B});

    always @(posedge VPWR, negedge VGND) begin
        case(state)
            4'b0000: begin
                A <= 1'bx;
                B <= 1'bx;
                VGND <= 1'bx;
                VPWR <= 1'bx;
                input_state <= 2'b00;
                state <= 4'b0001;
            end
            4'b0001: begin
                A <= 1'b0;
                input_state <= 2'b01;
                state <= 4'b0010;
            end
            4'b0010: begin
                B <= 1'b0;
                input_state <= 2'b10;
                state <= 4'b0011;
            end
            4'b0011: begin
                VGND <= 1'b0;
                input_state <= 2'b11;
                state <= 4'b0100;
            end
            4'b0100: begin
                VPWR <= 1'b0;
                state <= 4'b0101;
            end
            4'b0101: begin
                A <= 1'b1;
                input_state <= 2'b01;
                state <= 4'b0110;
            end
            4'b0110: begin
                B <= 1'b1;
                input_state <= 2'b10;
                state <= 4'b0111;
            end
            4'b0111: begin
                VGND <= 1'b1;
                input_state <= 2'b11;
                state <= 4'b1000;
            end
            4'b1000: begin
                VPWR <= 1'b1;
                state <= 4'b1001;
            end
            4'b1001: begin
                A <= 1'b0;
                input_state <= 2'b01;
                state <= 4'b1010;
            end
            4'b1010: begin
                B <= 1'b0;
                input_state <= 2'b10;
                state <= 4'b1011;
            end
            4'b1011: begin
                VGND <= 1'b0;
                input_state <= 2'b11;
                state <= 4'b1100;
            end
            4'b1100: begin
                VPWR <= 1'b0;
                state <= 4'b1101;
            end
            4'b1101: begin
                VPWR <= 1'b1;
                VGND <= 1'b1;
                state <= 4'b1110;
            end
            4'b1110: begin
                B <= 1'b1;
                input_state <= 2'b10;
                state <= 4'b1111;
            end
            4'b1111: begin
                A <= 1'b1;
                input_state <= 2'b01;
                state <= 4'b0000;
            end
        endcase
    end

    assign Y = xnor_out;

endmodule

module top_module( 
