    wire [99:0] final_sum;
    wire final_carry_out;
    control_logic control(.a(a), .b(b), .cin(cin), .ripple_sum(ripple_sum), .ripple_carry_out(ripple_carry_out), .lookahead_sum(lookahead_sum), .lookahead_carry_out(lookahead_carry_out), .final_sum(final_sum), .final_carry_out(final_carry_out));

    assign sum = final_sum;
    assign cout = final_carry_out;

endmodule

module control_logic(
    input [99:0] a, b,
    input cin,
    input [99:0] ripple_sum, lookahead_sum,
    input ripple_carry_out, lookahead_carry_out,
    output [99:0] final_sum,
    output final_carry_out );

    wire [99:0] xor_sum;
    wire and_carry;
    wire [99:0] and_sum;

    assign xor_sum = ripple_sum ^ lookahead_sum;
    assign and_carry = ripple_carry_out & lookahead_carry_out;
    assign and_sum = ripple_sum & lookahead_sum;

    assign final_sum = and_sum ^ xor_sum;
    assign final_carry_out = and_carry | (and_sum & xor_sum);

endmodule

module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

    wire [3:0] sum;
    wire [3:0] carry;

    // Full adder for bit 0
    full_adder fa0(A[0], B[0], Cin, sum[0], carry[0]);

    // Full adder for bit 1
    full_adder fa1(A[1], B[1], carry[0], sum[1], carry[1]);

    // Full adder for bit 2
    full_adder fa2(A[2], B[2], carry[1], sum[2], carry[2]);

    // Full adder for bit 3
    full_adder fa3(A[3], B[3], carry[2], sum[3], Cout);

    assign S = sum;

endmodule

module full_adder (
    input a,
    input b,
    input cin,
    output sum,
    output carry
);

    assign sum = a ^ b ^ cin;
    assign carry = (a & b) | (a & cin) | (b & cin);

endmodule

module regfile(
