module ADC (
  input analog_input,
  output [n-1:0] digital_output
);

parameter n = 8; // number of bits in the output signal

reg [n-1:0] digital_output_reg;
wire [n-1:0] reference_voltages;

// Define reference voltages
generate
  genvar i;
  for (i = 0; i < n; i = i + 1) begin: REF_VOLTAGES
    assign reference_voltages[i] = (2**i)/(2**n);
  end
endgenerate

// Binary search algorithm
always @(*) begin
  if (analog_input < reference_voltages[n-1]) begin
    digital_output_reg = {n{1'b0}};
  end else begin
    for (i = n-2; i >= 0; i = i - 1) begin
      if (analog_input < reference_voltages[i]) begin
        digital_output_reg[i+1:n-1] = {i+1{1'b0}};
        digital_output_reg[i] = 1'b1;
      end
    end
  end
end

assign digital_output = digital_output_reg;

endmodule

