  reg [3:0] count;

  always @ (posedge clk) begin
    if (rst) begin
      data <= 8'h00;
      lane <= 2'b00;
      count <= 4'h0;
    end else begin
      data <= px;
      count <= count + 1;
      if (count == 4'hF) begin
        count <= 4'h0;
        lane <= lane + 1;
        if (lane == 2'b11) begin
          lane <= 2'b00;
        end
      end
    end
