  // load the timer with a new value when load is high
  always @(posedge clk) begin
    if (rst) begin
      count <= 0;
    end else if (load) begin
      count <= value;
    end else if (enable) begin
      if (tick) begin
        if (count == 0) begin
          timeout <= 1;
        end else begin
          count <= count - 1;
        end
      end else begin
        timeout <= 0;
      end
    end else begin
      timeout <= 0;
    end
  end

