module arithmetic_display(DIGIT, DISPLAY, value_A, value_B, clk);
	input clk;
	input [3:0] value_A;
	input [3:0] value_B;

	output reg [3:0] DIGIT;
	output reg [8:0] DISPLAY;

	reg [7:0] result;
	reg sign_result;
	reg sign_A;
	reg sign_B;
	reg [3:0] value_result_tens;
	reg [3:0] value_result_units;

	always @(*) begin
		// Determine sign of A and B
		if (value_A[3] == 1) begin
			sign_A = 1;
			value_A = ~value_A + 1;
		end else begin
			sign_A = 0;
		end
		if (value_B[3] == 1) begin
			sign_B = 1;
			value_B = ~value_B + 1;
		end else begin
			sign_B = 0;
		end

		// Perform arithmetic operation
		if (value_A[3] == 0 && value_B[3] == 0) begin
			// Addition
			result = value_A + value_B;
			if (result[7] == 1) begin
				sign_result = 1;
				result = ~result + 1;
			end else begin
				sign_result = 0;
			end
		end else if (value_A[3] == 1 && value_B[3] == 1) begin
			// Subtraction
			result = value_A - value_B;
			if (result[7] == 1) begin
				sign_result = 1;
				result = ~result + 1;
			end else begin
				sign_result = 0;
			end
		end else begin
			// Multiplication
			result = value_A * value_B;
			if (result[7] == 1) begin
				sign_result = 1;
				result = ~result + 1;
			end else begin
				sign_result = 0;
			end
		end

		// Determine tens and units digits of result
		if (result < 10) begin
			value_result_tens = 0;
			value_result_units = result;
		end else begin
			value_result_tens = result / 10;
			value_result_units = result % 10;
		end
	end

	reg [3:0] value;
	reg sign;

	always @ ( posedge clk ) begin	
		case(DIGIT) 
			4'b0111: begin
				value = value_B;
				sign = sign_B;
				DIGIT <= 4'b1011;
			end
			4'b1011: begin
				value = value_result_tens;
				sign = 0;
				DIGIT <= 4'b1101;
			end
			4'b1101: begin
				value = value_result_units;
				sign = sign_result;
				DIGIT <= 4'b1110;
			end
			4'b1110: begin
				value = value_A;
				sign = sign_A;
				DIGIT <= 4'b0111;
			end
			default: begin
				DIGIT <= 4'b0111;
			end
		endcase	
	end

	always @(*) begin
		case (value)
			4'h0: DISPLAY = { ~sign, 8'b11000000 };
			4'h1: DISPLAY = { ~sign, 8'b11111001 };
			4'h2: DISPLAY = { ~sign, 8'b00100100 };
			4'h3: DISPLAY = { ~sign, 8'b00110000 };
			4'h4: DISPLAY = { ~sign, 8'b00011001 };
			4'h5: DISPLAY = { ~sign, 8'b00010010 };
			4'h6: DISPLAY = { ~sign, 8'b00000010 };
			4'h7: DISPLAY = { ~sign, 8'b11111000 };
			4'h8: DISPLAY = { ~sign, 8'b00000000 };
			4'h9: DISPLAY = { ~sign, 8'b00010000 };
			default: begin
				DISPLAY = 9'b111111111;
			end
		endcase
	end

endmodule

module round_counter_module (pulse, reset, clk, clk_1, work, mileage, number_of_halfkm);

input pulse, reset, clk, clk_1;
output work;
output [11:0] mileage, number_of_halfkm;

reg work;
reg [11:0] mileage, number_of_halfkm;

reg [7:0] ib;
reg [11:0] sample;
reg flag;

always @ (posedge clk, negedge reset)
begin
    if(!reset)
    begin
        ib <= 0;
        mileage <= 0;
        sample <= 0;
        number_of_halfkm <= 0;
    end
    else
    begin
        if(pulse == 0)  
        begin
            sample <= sample +1;
            if (flag == 1 && sample >= 49) 
            begin               
                if (ib >= 1)
                begin
                    mileage <= mileage +1;
                    if(mileage % 5 == 4) 
                        number_of_halfkm <= number_of_halfkm +1;

                    ib <= 0;
                end
                else ib <= ib +1;

                flag <= 0; 
            end
        end
        else 
        begin
            sample <= 0;
            flag <= 1;     
        end
    end
end

reg [11:0] count;

always @ (posedge clk_1, negedge flag)  
begin
        if(flag == 0)
        begin
            work <= 1;
            count <= 0;
        end
        else
        begin
            if (count >= 4) work <= 0;
            else    count <= count +1;
        end
end 

endmodule

