module traffic_light_controller(
    input clk,
    input [3:0] pedestrian_buttons,
    input manual_override,
    output reg [3:0] traffic_lights,
    output reg [3:0] yellow_lights
);

// Define states for the traffic light controller
parameter IDLE = 2'b00;
parameter GREEN = 2'b01;
parameter YELLOW = 2'b10;
parameter PEDESTRIAN = 2'b11;

// Define constants for timing
parameter GREEN_TIME = 10;
parameter YELLOW_TIME = 2;
parameter PEDESTRIAN_TIME = 10;

// Define variables for state machine
reg [1:0] state;
reg [1:0] next_state;
reg [3:0] time_counter;
reg [3:0] pedestrian_counter;
reg [3:0] manual_override_lights;

// Initialize variables
initial begin
    state = IDLE;
    next_state = GREEN;
    time_counter = 0;
    pedestrian_counter = 0;
    manual_override_lights = 0;
end

// State machine
always @(posedge clk) begin
    // Transition to next state
    state <= next_state;
    time_counter <= time_counter + 1;

    case(state)
        IDLE: begin
            // Wait for manual override or pedestrian button press
            if(manual_override) begin
                manual_override_lights <= traffic_lights;
                next_state <= MANUAL_OVERRIDE;
            end else if(pedestrian_buttons & ~traffic_lights) begin
                pedestrian_counter <= 0;
                next_state <= PEDESTRIAN;
            end else begin
                next_state <= GREEN;
            end
        end
        GREEN: begin
            // Set traffic light to green
            traffic_lights <= 1 << time_counter[1:0];
            yellow_lights <= 0;

            // Transition to yellow light after green time
            if(time_counter == GREEN_TIME) begin
                time_counter <= 0;
                next_state <= YELLOW;
            end
        end
        YELLOW: begin
            // Set yellow light to transition between green and red
            traffic_lights <= 0;
            yellow_lights <= 1 << time_counter[1:0];

            // Transition to next state after yellow time
            if(time_counter == YELLOW_TIME) begin
                time_counter <= 0;
                // Check if pedestrian button was pressed during yellow light
                if(pedestrian_buttons & ~traffic_lights) begin
                    pedestrian_counter <= 0;
                    next_state <= PEDESTRIAN;
                end else begin
                    next_state <= IDLE;
                end
            end
        end
        PEDESTRIAN: begin
            // Set traffic light to red and pedestrian light to green
            traffic_lights <= 0;
            yellow_lights <= 0;
            pedestrian_counter <= pedestrian_counter + 1;
            if(pedestrian_counter == PEDESTRIAN_TIME) begin
                pedestrian_counter <= 0;
                next_state <= IDLE;
            end
        end
        MANUAL_OVERRIDE: begin
            // Set traffic lights to manual override lights
            traffic_lights <= manual_override_lights;
            yellow_lights <= 0;

            // Deactivate manual override if pedestrian button is pressed
            if(pedestrian_buttons & ~traffic_lights) begin
                pedestrian_counter <= 0;
                next_state <= PEDESTRIAN;
            end else if(~manual_override) begin
                next_state <= IDLE;
            end
        end
    endcase
end

endmodule

