module frame_rate (
    inclk0,
    c0,
    c1,
    locked
);

input   inclk0;
output  c0;
output  c1;
output  locked;

reg     inclk0_d; // delayed inclk0 signal
reg     locked_d; // delayed locked signal
reg     locked_dd; // doubly delayed locked signal
reg     c0_d; // delayed c0 signal
reg     c1_d; // delayed c1 signal
reg     c0_dd; // doubly delayed c0 signal
reg     c1_dd; // doubly delayed c1 signal
reg     locked_next; // next value of locked signal
reg     c0_next; // next value of c0 signal
reg     c1_next; // next value of c1 signal

parameter   COUNT_MAX = 2; // number of clock cycles to wait before updating output signals

integer count = 0; // counter for number of clock cycles elapsed

always @(posedge inclk0)
begin
    // update delayed signals
    inclk0_d <= inclk0;
    c0_d <= c0_next;
    c1_d <= c1_next;
    locked_d <= locked_next;

    // update doubly delayed signals
    c0_dd <= c0_d;
    c1_dd <= c1_d;
    locked_dd <= locked_d;

    // update output signals
    if (count == COUNT_MAX)
    begin
        c0 <= c0_d;
        c1 <= c1_d;
        locked <= locked_d;

        // calculate next values of output signals
        c0_next <= ~c0_dd;
        c1_next <= c0_dd;
        locked_next <= (inclk0_d == locked_dd) ? 1 : 0;

        count <= 0;
    end
    else
    begin
        count <= count + 1;
    end
end

endmodule

module top_module (
    input [3:0] A,
    input [3:0] B,
    input SUB,
    input sel1,
    input sel2,
    output reg [3:0] Y,
    output reg CARRY
);

reg [3:0] result; // result of addition or subtraction
wire [3:0] SUM; // sum output from adder-subtractor module

adder_subtractor add_sub (
    .A(A),
    .B(B),
    .SUB(SUB),
    .SUM(SUM),
    .CARRY(CARRY)
);

mux_nand mux (
    .A(SUM),
    .B(A),
    .C(B),
    .sel1(sel1),
    .sel2(sel2),
    .Y(Y)
);

always @(*) begin
    if (SUB) begin
        result <= A - B;
    end else begin
        result <= A + B;
    end
end

endmodule

// Adder-subtractor module
module adder_subtractor (
    input [3:0] A,
    input [3:0] B,
    input SUB,
    output reg [3:0] SUM,
    output reg CARRY
);

reg [3:0] twos_complement_B; // two's complement of B

assign twos_complement_B = ~B + 1;

always @(*) begin
    if (SUB) begin
        SUM <= A + twos_complement_B;
        CARRY <= ~(A[3] ^ twos_complement_B[3] ^ SUM[3]);
    end else begin
        SUM <= A + B;
        CARRY <= ~(A[3] ^ B[3] ^ SUM[3]);
    end
end

endmodule

// 3-to-1 NAND multiplexer module
module mux_nand (
    input A,
    input B,
    input C,
    input sel1,
    input sel2,
    output Y
);

wire nand1, nand2, nand3;

assign nand1 = ~(A & B & C);
assign nand2 = ~(A & B & ~C);
assign nand3 = ~(A & ~B & C);

assign Y = sel1 & sel2 ? nand3 : sel1 ? nand2 : sel2 ? nand1 : 0;

endmodule

