module SD_Controller (
  input CMD,
  input DAT,
  input CLK,
  input RST,
  output BUSY,
  output RESP,
  output DATA,
  output reg CMD_out,
  output reg DAT_out,
  output reg CLK_out,
  output reg RST_out,
  input BUSY_in,
  input RESP_in,
  input DATA_in
);

  // Inputs and Outputs for Host
  // input CMD, DAT, CLK, RST
  // output BUSY, RESP, DATA

  // Inputs and Outputs for Device
  // output CMD, DAT, CLK, RST
  // input BUSY, RESP, DATA

  // Define states for the state machine
  localparam IDLE = 2'b00;
  localparam CMD_TX = 2'b01;
  localparam CMD_RX = 2'b10;
  localparam DATA_TX = 2'b11;
  localparam DATA_RX = 2'b100;

  // Define variables for the state machine
  reg [1:0] state;
  reg [7:0] cmd;
  reg [31:0] data;
  reg [3:0] crc;
  reg [3:0] crc_rx;
  reg [7:0] resp;
  reg [7:0] resp_rx;
  reg [7:0] dummy;

  // Define constants for the state machine
  localparam CMD0 = 8'h40;
  localparam CMD8 = 8'h48;
  localparam CMD17 = 8'h51;
  localparam CMD24 = 8'h58;
  localparam CMD55 = 8'h77;
  localparam ACMD41 = 8'h69;
  localparam START_BLOCK = 8'hfe;
  localparam STOP_TRANSMISSION = 8'hfd;

  // Define the state machine
  always @(posedge CLK) begin
    case(state)
      IDLE: begin
        BUSY = 1'b0;
        RESP = 8'b0;
        DATA = 32'b0;
        if(CMD) begin
          state = CMD_TX;
          cmd = DAT;
          crc = 4'b1001;
        end
        else if(DAT) begin
          state = DATA_TX;
          data = DAT;
          crc = 4'b1001;
        end
      end
      CMD_TX: begin
        BUSY = 1'b1;
        RESP = 8'b0;
        DATA = 32'b0;
        CMD_out = 1'b0;
        DAT_out = 1'b0;
        CLK_out = 1'b0;
        RST_out = 1'b0;
        if(!RST) begin
          state = IDLE;
        end
        else if(CMD_out) begin
          state = CMD_RX;
          crc = crc ^ cmd;
        end
      end
      CMD_RX: begin
        BUSY = 1'b1;
        RESP = 8'b0;
        DATA = 32'b0;
        CMD_out = 1'b1;
        DAT_out = 1'b0;
        CLK_out = 1'b0;
        RST_out = 1'b0;
        if(!RST) begin
          state = IDLE;
        end
        else if(RESP_in) begin
          state = IDLE;
          resp_rx = RESP_in;
          crc_rx = 4'b1001;
        end
      end
      DATA_TX: begin
        BUSY = 1'b1;
        RESP = 8'b0;
        DATA = 32'b0;
        CMD_out = 1'b0;
        DAT_out = 1'b1;
        CLK_out = 1'b0;
        RST_out = 1'b0;
        if(!RST) begin
          state = IDLE;
        end
        else if(DAT_out) begin
          state = DATA_RX;
          crc = crc ^ (data >> 24);
        end
      end
      DATA_RX: begin
        BUSY = 1'b1;
        RESP = 8'b0;
        DATA = 32'b0;
        CMD_out = 1'b0;
        DAT_out = 1'b0;
        CLK_out = 1'b0;
        RST_out = 1'b0;
        if(!RST) begin
          state = IDLE;
        end
        else if(DATA_in) begin
          state = IDLE;
          dummy = DATA_in;
          crc_rx = 4'b1001;
        end
      end
    endcase
  end

  // Calculate CRC for outgoing data
  always @(posedge CLK) begin
    if(state == CMD_TX || state == DATA_TX) begin
      if(CMD_out || DAT_out) begin
        if(crc[3]) begin
          crc = {crc[2:0], crc[3] ^ 1'b1};
        end
        else begin
          crc = {crc[2:0], crc[3]};
        end
      end
    end
  end

  // Check CRC for incoming data
  always @(posedge CLK) begin
    if(state == CMD_RX || state == DATA_RX) begin
      if(RESP_in || DATA_in) begin
        if(crc_rx[3]) begin
          crc_rx = {crc_rx[2:0], crc_rx[3] ^ 1'b1};
        end
        else begin
          crc_rx = {crc_rx[2:0], crc_rx[3]};
        end
      end
    end
  end

  // Handle error conditions
  always @(posedge CLK) begin
    if(RESP_in && !crc_rx[3]) begin
      resp = RESP_in;
    end
    else if(DATA_in && !crc_rx[3]) begin
      resp = 8'h5;
    end
    else if(state == CMD_RX && !RESP_in) begin
      resp = 8'h5;
    end
    else if(state == DATA_RX && !DATA_in) begin
      resp = 8'h5;
    end
    else begin
      resp = 8'h0;
    end
  end

endmodule

