    generate
        genvar i;
        for (i = 0; i < 30; i = i + 1) begin : chunk_gen
            assign din_clb[i] = din[i*4 +: 4];
            clbs clb (.clk(clk), .din(din_clb[i]), .dout(dout_clb[i]));
