    assign dout = {dout_clb};
endmodule

module AGC (
  input in,
  input ref,
  output out
);

parameter k = 10; // gain coefficient

reg [31:0] accumulator;
reg [31:0] prev_accumulator;
reg [31:0] gain;
reg [31:0] prev_gain;

always @(posedge clk) begin
  accumulator <= accumulator + in * gain;
  prev_accumulator <= accumulator;
  prev_gain <= gain;
  if (accumulator > ref) begin
    gain <= gain - 1;
  end else if (accumulator < ref) begin
    gain <= gain + 1;
  end
  if (gain > k) begin
    gain <= k;
  end else if (gain < 1) begin
    gain <= 1;
  end
end

assign out = in * gain;

endmodule

