module binary_op(
    input [3:0] A,
    input [3:0] B,
    input [1:0] S,
    output [3:0] Y
);

    wire [3:0] sum;
    wire [3:0] diff;
    wire [3:0] and_out;
    wire [3:0] or_out;

    // Full adder
    // Inputs: A, B, Cin
    // Outputs: Sum, Cout
    // Cout is discarded
    // (code for full_adder not shown)
    // ...

    // Calculate sum
    full_adder fa0(.A(A[0]), .B(B[0]), .Cin(1'b0), .Sum(sum[0]), .Cout());
    full_adder fa1(.A(A[1]), .B(B[1]), .Cin(fa0.Cout), .Sum(sum[1]), .Cout());
    full_adder fa2(.A(A[2]), .B(B[2]), .Cin(fa1.Cout), .Sum(sum[2]), .Cout());
    full_adder fa3(.A(A[3]), .B(B[3]), .Cin(fa2.Cout), .Sum(sum[3]), .Cout());

    // Calculate difference
    full_adder fa4(.A(A[0]), .B(~B[0]), .Cin(1'b1), .Sum(diff[0]), .Cout());
    full_adder fa5(.A(A[1]), .B(~B[1]), .Cin(fa4.Cout), .Sum(diff[1]), .Cout());
    full_adder fa6(.A(A[2]), .B(~B[2]), .Cin(fa5.Cout), .Sum(diff[2]), .Cout());
    full_adder fa7(.A(A[3]), .B(~B[3]), .Cin(fa6.Cout), .Sum(diff[3]), .Cout());

    // Bitwise AND
    assign and_out = A & B;

    // Bitwise OR
    assign or_out = A | B;

    // Select output based on S
    always @(*) begin
        case (S)
            2'b00: Y = sum;
            2'b01: Y = diff;
            2'b10: Y = and_out;
            2'b11: Y = or_out;
            default: Y = 4'bzzzz;
        endcase
    end

endmodule

