module arbitrator(
    input reset,
    input clk,
    input [5:0] request,
    input [5:0] release,
    output reg [5:0] permit
    );

    parameter NUM_REQUESTS = 6;
    parameter WAIT_CYCLES = 4;

    reg [2:0] state;
    reg [2:0] count;
    reg [2:0] index;

    always @(posedge clk, negedge reset) begin
        if (!reset) begin
            state <= 3'b000;
            permit <= 6'b000000;
            index <= 3'b000;
            count <= 3'b000;
        end else begin
            case (state)
                3'b000: begin // REQUEST0
                    if (request[0]) begin
                        permit[0] <= 1;
                        state <= 3'b001;
                        index <= 3'b001;
                    end else begin
                        state <= 3'b001;
                    end
                end

                3'b001: begin // REQUEST1
                    if (request[1]) begin
                        permit[1] <= 1;
                        state <= 3'b0010;
                        index <= 3'b010;
                    end else begin
                        state <= 3'b010;
                    end
                end

                3'b010: begin // REQUEST2
                    if (request[2]) begin
                        permit[2] <= 1;
                        state <= 3'b0010;
                        index <= 3'b011;
                    end else begin
                        state <= 3'b011;
                    end
                end

                3'b011: begin // REQUEST3
                    if (request[3]) begin
                        permit[3] <= 1;
                        state <= 3'b0010;
                        index <= 3'b100;
                    end else begin
                        state <= 3'b100;
                    end
                end

                3'b100: begin // REQUEST4
                    if (request[4]) begin
                        permit[4] <= 1;
                        state <= 3'b0010;
                        index <= 3'b101;
                    end else begin
                        state <= 3'b101;
                    end
                end

                3'b101: begin // REQUEST5
                    if (request[5]) begin
                        permit[5] <= 1;
                        state <= 3'b0010;
                        index <= 3'b000;
                    end else begin
                        state <= 3'b000;
                    end
                end

                3'b0010: begin // WAIT_RELEASE
                    if (release != 6'b000000) begin
                        permit <= 6'b000000;
                        count <= 3'b000;
                        state <= 3'b0011;
                    end else begin
                        state <= 3'b0010;
                    end
                end

                3'b0011: begin // WAIT_CYCLES
                    if (count == WAIT_CYCLES) begin
                        state <= index;
                    end else begin
                        count <= count + 3'b001;
                        state <= 3'b0011;
                    end
                end

                default: begin
                    state <= 3'b000;
                end
            endcase
        end
    end

endmodule

