        end
        else begin
            case (state)
                0: begin
                    dividend_reg <= dividend;
                    divisor_reg <= divisor;
                    quotient_reg <= 0;
                    remainder_reg <= 0;
                    state <= 1;
                end
                1: begin
                    if (dividend_reg < 0) begin
                        dividend_reg <= -dividend_reg;
                        quotient_reg <= -quotient_reg;
                        remainder_reg <= -remainder_reg;
                        state <= 2;
                    end
                    else begin
                        state <= 2;
                    end
                end
                2: begin
                    if (count == 4) begin
                        done <= 1;
                        state <= 0;
                    end
                    else if (dividend_reg >= 0) begin
                        temp <= dividend_reg;
                        dividend_reg <= dividend_reg - (divisor_reg << 1);
                        quotient_reg[count] <= 1;
                        count <= count + 1;
                        state <= 2;
                    end
                    else begin
                        quotient_reg[count] <= 0;
                        count <= count + 1;
                        state <= 3;
                    end
                end
                3: begin
                    dividend_reg <= temp;
                    quotient_reg[count] <= 0;
                    count <= count + 1;
                    state <= 2;
                end
            endcase
        end
    end

    assign remainder = remainder_reg;
    assign quotient = quotient_reg;

endmodule

module priority_encoder (
    input A, B, C, D,                    // Inputs to be encoded
    output reg Y1,                       // Output indicating the highest priority input
    output reg Y0                        // Output indicating the input with the next highest priority
);

    always @(A, B, C, D) begin
        case ({A, B, C, D})
            4'b0001: begin
                Y1 <= 0;
                Y0 <= 0;
            end
            4'b0010: begin
                Y1 <= 0;
                Y0 <= 1;
            end
            4'b0100: begin
                Y1 <= 1;
                Y0 <= 0;
            end
            4'b1000: begin
                Y1 <= 1;
                Y0 <= 1;
            end
            default: begin
                Y1 <= 0;
                Y0 <= 0;
            end
        endcase
    end

endmodule

module top_module (
    input signed [3:0] dividend,         // 4-bit dividend for the non-restoring divider
    input signed [3:0] divisor,          // 4-bit divisor for the non-restoring divider
    input A, B, C, D,                    // Inputs for the 4-to-2 priority encoder
    input select,                        // Select input to choose between non-restoring divider and priority encoder
    output reg signed [3:0] quotient,    // 4-bit quotient output from the non-restoring divider
    output reg signed [3:0] remainder,   // 4-bit remainder output from the non-restoring divider
    output reg Y1,                       // Output indicating the highest priority input from the priority encoder
    output reg Y0                        // Output indicating the input with the next highest priority from the priority encoder
);

    wire [1:0] priority;                 // Wire to hold the priority encoder output
    wire [3:0] dividend_neg;             // Wire to hold the two's complement of the dividend
    wire [3:0] divisor_neg;              // Wire to hold the two's complement of the divisor

    non_restoring_divider divider (
        .dividend(dividend),
        .divisor(divisor),
        .quotient(quotient),
        .remainder(remainder),
        .clk(1'b1),
        .rst(1'b0)
    );

    priority_encoder encoder (
        .A(A),
        .B(B),
        .C(C),
        .D(D),
        .Y1(priority[1]),
        .Y0(priority[0])
    );

    assign dividend_neg = ~dividend + 1;
    assign divisor_neg = ~divisor + 1;

    always @(select, dividend, divisor, A, B) begin
        if (select) begin
            Y1 <= priority[1];
            Y0 <= priority[0];
            quotient <= 0;
            remainder <= 0;
        end
        else begin
            Y1 <= 0;
            Y0 <= 0;
            quotient <= divider.quotient;
            remainder <= divider.remainder;
        end
    end

endmodule

