  spi driver(
    .clk(clk),
    .reset(rst),
    .datain(datain),
    .enable(enable),
    .dataout(dataout),
    .done(done)
  );

  // Address decoder
  always @(*) begin
    case (addr)
      4'h0: begin s = (cs && wr) ? 4'b0001 : 6'b0000; end // datain
      4'h2: begin s = (cs && wr) ? 4'b0010 : 6'b0000; end // enable
      4'h4: begin s = (cs && rd) ? 4'b0100 : 6'b0000; end // done
