          if (!go) begin
            state <= PLAYBACK;
            mode[1:0] <= {1'b1, 1'b1};
          end else begin
            mode[1:0] <= {1'b0, 1'b1};
            cyclecounter_local <= cyclecounter_local + 1;
          end
        end
        PLAYBACK: begin
          if (!go) begin
            state <= IDLE;
            mode[1:0] <= {1'b0, 1'b0};
          end else begin
            mode[1:0] <= {1'b1, 1'b1};
          end
        end
      endcase
    end
  end

  assign cyclecounter = cyclecounter_local;

endmodule

