  if (reset) begin
    count <= 0;
    selection <= 1'b1;
    egg_timer <= 7'b0;
  end else begin
    count <= count + 1;
    if (count == TOGGLE_VALUE) begin
      selection <= ~selection;
      if (count == TOGGLE_VALUE) begin
        egg_timer <= 7'b1111111;
