module vga_stripes(
	VIDON,
	HC,
	VC,
	R,
	G,
	B,
	SW
);

// |--------------------|
// | Port Declarations  |
// | -------------------|
input VIDON;
input [9:0] HC;
input [9:0] VC;
input [17:0] SW;
output [7:0] R;
output [7:0] G;
output [7:0] B;

// |---------------------|
// | Signal Declarations |
// | --------------------|
reg [7:0] Rr, Gg, Bb;
assign R = Rr;
assign G = Gg;
assign B = Bb;

always @ (VIDON, VC, SW)
begin
	Rr <= 8'b00000000;
	Gg <= 8'b00000000;
	Bb <= 8'b00000000;

	if (VIDON == 1'b1)
	begin
		if (SW != 0)
		begin
			Rr <= SW[17:10];
			Gg[1:0] <= {SW[1:0],1'b0,1'b0,1'b0,1'b0,1'b0,1'b0};
			Bb <= SW[9:2];
		end
		else
		begin
			if (VC > 400)
			begin
				Rr <= 8'b11111111;
				Gg <= 8'b00000000;
				Bb <= 8'b00000000;
			end
			else if (VC > 300)
			begin
				Rr <= 8'b00000000;
				Gg <= 8'b11110100;
				Bb <= 8'b00000000;
			end
			else if (VC > 200)
			begin
				Rr <= 8'b00000000;
				Gg <= 8'b00000000;
				Bb <= 8'b11111110;
			end
			else
			begin
				Rr <= 8'b00000000;
				Gg <= 8'b00000000;
				Bb <= 8'b00000000;
			end
		end
	end
end

endmodule

module p_source_files_sr (
        ap_clk,
        ap_rst,
        ap_start,
        ap_done,
        ap_continue,
        ap_idle,
        ap_ready,
        p_read,
        ap_return
);

parameter    ap_ST_fsm_state1 = 1'd1;
parameter    ap_ST_fsm_state2 = 1'd2;

input   ap_clk;
input   ap_rst;
input   ap_start;
output   ap_done;
input   ap_continue;
output   ap_idle;
output   ap_ready;
input  [63:0] p_read;
output  [63:0] ap_return;

reg ap_done;
reg ap_idle;
reg ap_ready;
reg[63:0] ap_return;

reg    ap_done_reg;
(* fsm_encoding = "none" *) reg   [1:0] ap_CS_fsm;
wire    ap_CS_fsm_state1;
wire    ap_CS_fsm_state2;
reg    ap_block_state1;
reg   [63:0] ap_return_preg;
reg   [63:0] ap_return_div;
reg   [0:0] ap_NS_fsm;

// power-on initialization
initial begin
#0 ap_done_reg = 1'b0;
#0 ap_CS_fsm = 2'd1;
#0 ap_return_preg = 64'd0;
#0 ap_return_div = 64'd0;
end

always @ (posedge ap_clk) begin
    if (ap_rst == 1'b1) begin
        ap_CS_fsm <= ap_ST_fsm_state1;
    end else begin
        ap_CS_fsm <= ap_NS_fsm;
    end
end

always @ (posedge ap_clk) begin
    if (ap_rst == 1'b1) begin
        ap_done_reg <= 1'b0;
        ap_return_div <= 64'd0;
    end else begin
        if ((1'b1 == ap_continue)) begin
            ap_done_reg <= 1'b0;
        end else if (((1'b1 == ap_CS_fsm_state1) & ~((1'b0 == ap_start) | (ap_done_reg == 1'b1)))) begin
            ap_done_reg <= 1'b1;
        end else if (((1'b1 == ap_CS_fsm_state2) & ~(ap_return_div == 64'd0))) begin
            ap_done_reg <= 1'b1;
        end
    end
end

always @ (posedge ap_clk) begin
    if (ap_rst == 1'b1) begin
        ap_return_preg <= 64'd0;
    end else begin
        if (((1'b1 == ap_CS_fsm_state1) & ~((1'b0 == ap_start) | (ap_done_reg == 1'b1)))) begin
            ap_return_preg <= p_read;
        end else if (((1'b1 == ap_CS_fsm_state2) & ~(ap_return_div == 64'd0))) begin
            ap_return_preg <= ap_return_div;
        end
    end
end

always @ (*) begin
    if (((1'b1 == ap_CS_fsm_state1) & ~((1'b0 == ap_start) | (ap_done_reg == 1'b1)))) begin
        ap_done = 1'b1;
    end else begin
        ap_done = ap_done_reg;
    end
end

always @ (*) begin
    if (((1'b0 == ap_start) & (1'b1 == ap_CS_fsm_state1))) begin
        ap_idle = 1'b1;
    end else begin
        ap_idle = 1'b0;
    end
end

always @ (*) begin
    if (((1'b1 == ap_CS_fsm_state1) & ~((1'b0 == ap_start) | (ap_done_reg == 1'b1)))) begin
        ap_ready = 1'b1;
    end else begin
        ap_ready = 1'b0;
    end
end

always @ (*) begin
    if (((1'b1 == ap_CS_fsm_state1) & ~((1'b0 == ap_start) | (ap_done_reg == 1'b1)))) begin
        ap_return = p_read;
    end else if (((1'b1 == ap_CS_fsm_state2) & ~(ap_return_div == 64'd0))) begin
        ap_return = ap_return_div;
    end else begin
        ap_return = ap_return_preg;
    end
end

always @ (*) begin
    case (ap_CS_fsm)
        ap_ST_fsm_state1 : begin
            ap_NS_fsm = ap_ST_fsm_state1;
            if (p_read >= 1000) begin
                ap_CS_fsm <= ap_ST_fsm_state2;
            end
        end
        ap_ST_fsm_state2 : begin
            ap_NS_fsm = ap_ST_fsm_state2;
            ap_return_div <= p_read / 10;
            ap_CS_fsm <= ap_ST_fsm_state1;
        end
        default : begin
            ap_NS_fsm = 'bx;
        end
    endcase
end

assign ap_CS_fsm_state1 = ap_CS_fsm[32'd0];
assign ap_CS_fsm_state2 = ap_CS_fsm[32'd1];

always @ (*) begin
    ap_block_state1 = ((1'b0 == ap_start) | (ap_done_reg == 1'b1));
end

endmodule

