    always @(posedge sys_clk) begin
        if(we[0]) begin
            ram0[addr] <= ram0di;
            ram0do <= ram0di;
        end else
            ram0do <= ram0[addr];
    end

    assign ram0di = dat_i[7:0];
    assign ram1di = dat_i[15:8];

    assign dat_o = {ram1do, ram0do};

endmodule

module uart (
  input clk,
  input rst,
  input rx,
  input tx_busy,
  input [7:0] data_in,
  output reg tx,
  output reg rx_done,
  output reg [7:0] data_out
);

  // Define states
  parameter IDLE = 2'b00;
  parameter RECEIVE = 2'b01;
  parameter TRANSMIT = 2'b10;

  // Define start, data, and stop bits
  parameter START_BIT = 1'b0;
  parameter STOP_BIT = 1'b1;

  // Define shift register for received data
  reg [9:0] rx_shift_reg;
  reg [3:0] rx_bit_count;

  // Define shift register for transmitted data
  reg [9:0] tx_shift_reg;
  reg [3:0] tx_bit_count;
  reg tx_start_bit_sent;
  reg tx_stop_bit_sent;

  // Define state register and next state logic
  reg [1:0] state;
  always @ (posedge clk, posedge rst) begin
    if (rst) begin
      state <= IDLE;
    end else begin
      case (state)
        IDLE: begin
          if (rx) begin
            state <= RECEIVE;
          end else if (!tx_busy && tx) begin
            state <= TRANSMIT;
            tx_shift_reg <= {START_BIT, data_in, STOP_BIT};
            tx_bit_count <= 0;
            tx_start_bit_sent <= 0;
            tx_stop_bit_sent <= 0;
          end else begin
            state <= IDLE;
          end
        end
        RECEIVE: begin
          if (rx_bit_count == 0) begin
            rx_shift_reg <= {rx, 8'b0};
          end else begin
            rx_shift_reg <= {rx_shift_reg[8:0], rx};
          end
          rx_bit_count <= rx_bit_count + 1;
          if (rx_bit_count == 9) begin
            rx_done <= 1;
            data_out <= rx_shift_reg[8:1];
            state <= IDLE;
          end
        end
        TRANSMIT: begin
          if (!tx_start_bit_sent) begin
            tx <= tx_shift_reg[0];
            tx_start_bit_sent <= 1;
          end else if (tx_bit_count < 8) begin
            tx <= tx_shift_reg[tx_bit_count + 1];
            tx_bit_count <= tx_bit_count + 1;
          end else if (!tx_stop_bit_sent) begin
            tx <= STOP_BIT;
            tx_stop_bit_sent <= 1;
          end else begin
            tx <= 1;
            state <= IDLE;
          end
        end
      endcase
    end
  end

endmodule

