module fifo (clock, in_data, out_data);
    input clock;
    input [3:0] in_data;
    output [3:0] out_data;
    reg [3:0] buffer [0:4];
    reg [2:0] head;
    reg [2:0] tail;
    integer i;

    always @(posedge clock) begin
        if (head != tail || i == 0) begin
            out_data <= buffer[tail];
            tail <= tail + 1;
            if (tail == 5) tail <= 0;
        end else begin
            out_data <= 4'b0;
        end
    end

    always @(posedge clock) begin
        if (head != tail || i == 0) begin
            buffer[head] <= in_data;
            head <= head + 1;
            if (head == 5) head <= 0;
            i <= i + 1;
        end
    end
endmodule

