module pwm_ctl (
    input clk, rst,
    input [14:0] para_in,
    input dir_in,
    output reg dir_out,
    output reg en_out
);

parameter MAX = 19999;

reg [14:0] duty_cycle;
reg [14:0] duty_cycle_;
reg dir_;
reg [31:0] counter;
wire [31:0] divflag;
reg [31:0] PWMctl_clk;

initial PWMctl_clk = MAX;
initial duty_cycle = MAX;

assign divflag = PWMctl_clk - duty_cycle;

assign dir_out = dir_;
assign en_out = dir_;

always @(posedge clk) begin
    if (rst) begin
        duty_cycle <= 0;
        dir_ <= 0;
    end
    else if (para_in < PWMctl_clk) begin
        duty_cycle <= para_in;
        dir_ <= dir_in;
    end
    else begin
        duty_cycle <= MAX;
    end
end

always @(posedge clk) begin
    if (rst) begin
        dir_ <= 0;
        en_out <= 0;
        duty_cycle_ <= 0;
    end
    else if (divflag > counter) begin
        dir_ <= dir_;
        en_out <= 1;
    end
    else begin
        en_out <= 0;
    end
end

always @(posedge clk) begin
    if (rst) begin
        counter <= 0;
    end
    else if (PWMctl_clk == counter) begin
        counter <= 0;
    end
    else begin
        counter <= counter + 1;
    end
end

endmodule

