module top_module (
    input clk,
    input reset,
    input [7:0] in,
    input select,
    input [7:0] read_addr,
    input write_en,
    input [7:0] write_addr,
    input [3:0] write_data,
    input read_en,
    output reg [3:0] read_data,
    output reg led
);
    wire edge_detected;
    wire [3:0] ram_data;
    wire [3:0] sum;

    edge_detection edge_detect (
        .clk(clk),
        .reset(reset),
        .in(in),
        .edge_detected(edge_detected)
    );

    dual_port_ram ram (
        .clk(clk),
        .reset(reset),
        .read_addr(read_addr),
        .write_en(write_en),
        .write_addr(write_addr),
        .write_data(write_data),
        .read_en(read_en),
        .read_data(ram_data)
    );

    adder add (
        .a(ram_data[3:0]),
        .b(ram_data[7:4]),
        .sum(sum)
    );

    always @(posedge clk, posedge reset) begin
        if (reset) begin
            read_data <= 0;
            led <= 0;
        end else begin
            if (select) begin
                if (edge_detected) begin
                    ram.write_en <= 1;
                    ram.write_addr <= read_addr;
                    ram.write_data <= in;
                end
                ram.read_en <= 1;
                read_data <= ram_data;
                led <= sum;
            end else begin
                ram.read_en <= 0;
                read_data <= 0;
                led <= 0;
            end
        end
    end
endmodule

