module priority_encoder (
    input [7:0] in, // 8-bit input
    output [2:0] out, // 3-bit output for the highest priority input
    output valid, // Valid signal indicating if there is a valid input
    output [2:0] index // 3-bit output for the index of the highest priority input
);

    assign valid = |in; // Check if there is a valid input

    // Priority encoder logic
    assign out = {in[7], in[6], in[5]} > {in[4], in[3], in[2]} ?
                 {in[7], in[6], in[5]} > {in[1], in[0], 1'b0} ?
                 {in[7], in[6], in[5]} : {in[1], in[0], 1'b0} :
                 {in[4], in[3], in[2]} > {in[1], in[0], 1'b0} ?
                 {in[4], in[3], in[2]} : {in[1], in[0], 1'b0};

    // Index of the highest priority input
    assign index = out == {in[7], in[6], in[5]} ? 3 :
                   out == {in[4], in[3], in[2]} ? 2 : 1;

endmodule

module ripple_carry_adder (
    input [3:0] A, // 4-bit input A
    input [3:0] B, // 4-bit input B
    output [3:0] S, // 4-bit output sum
    output Cout // Carry-out
);

    wire [3:0] C; // Carry bits

    // Full adder logic
    assign {Cout, S} = A + B + C;

    // Ripple carry logic
    assign C[0] = A[0] & B[0];
    assign C[1] = (A[1] & B[1]) | (A[1] & B[0]) | (A[0] & B[1]);
    assign C[2] = (A[2] & B[2]) | (A[2] & B[1]) | (A[2] & B[0]) | (A[1] & B[2]) | (A[1] & B[1]) | (A[0] & B[2]);
    assign C[3] = A[3] & B[3] | A[3] & B[2] | A[3] & B[1] | A[3] & B[0] | A[2] & B[3] | A[2] & B[2] | A[1] & B[3] | A[0] & B[3];

endmodule

module top_module (
    input [7:0] in, // 8-bit input for the priority encoder
    input [3:0] A, // 4-bit input A for the ripple carry adder
    input [3:0] B, // 4-bit input B for the ripple carry adder
    output [3:0] S, // 4-bit output sum from the ripple carry adder
    output Cout, // Carry-out from the ripple carry adder
    output [7:0] q // 8-bit output from the functional module
);

    wire [2:0] out; // Highest priority input from the priority encoder
    wire valid; // Valid signal from the priority encoder
    wire [2:0] index; // Index of the highest priority input from the priority encoder

    priority_encoder pe (
        .in(in),
        .out(out),
        .valid(valid),
        .index(index)
    );

    ripple_carry_adder rca (
        .A(A),
        .B(B),
        .S(S),
        .Cout(Cout)
    );

    // Functional module logic
    always @(*) begin
        if (valid && index < 3) begin
            q = {4'b0, S};
        end else begin
            q = {4'b0, out};
        end
    end

endmodule

module mig_7series_v2_0_data_prbs_gen #
  (
    parameter TCQ           = 100,

    parameter EYE_TEST   = "FALSE",
    parameter PRBS_WIDTH = 32,                                                                       // "SEQUENTIAL_BUrst_i"
    parameter SEED_WIDTH = 32    
   )
  (
   input           clk_i,
   input           clk_en,
   input           rst_i,
   input           prbs_seed_init,
   input [PRBS_WIDTH - 1:0]  prbs_seed_i,

   output  [PRBS_WIDTH - 1:0]  prbs_o
  );

reg [PRBS_WIDTH - 1 :0] prbs;  
reg [PRBS_WIDTH :1] lfsr_q;
integer i;

// Initialize LFSR to known good state
always @ (posedge clk_i) begin
   if (prbs_seed_init && EYE_TEST == "FALSE" || rst_i)
      begin
        lfsr_q[4:1] <= #TCQ   prbs_seed_i[3:0] | 4'h5;
        lfsr_q[PRBS_WIDTH:5] <= #TCQ  prbs_seed_i[PRBS_WIDTH-1:4] ;
      end
end

// Generate PRBS using LFSR
always @ (posedge clk_i) begin
   if (clk_en && !rst_i && !(prbs_seed_init && EYE_TEST == "FALSE")) begin
        lfsr_q[32:9] <= #TCQ  lfsr_q[31:8];
        lfsr_q[8]    <= #TCQ  lfsr_q[32] ^ lfsr_q[7];
        lfsr_q[7]    <= #TCQ  lfsr_q[32] ^ lfsr_q[6];
        lfsr_q[6:4]  <= #TCQ  lfsr_q[5:3];
        lfsr_q[3]    <= #TCQ  lfsr_q[32] ^ lfsr_q[2];
        lfsr_q[2]    <= #TCQ  lfsr_q[1] ;
        lfsr_q[1]    <= #TCQ  lfsr_q[32];
   end
end

// Output PRBS
always @ (lfsr_q[PRBS_WIDTH:1]) begin
       prbs = lfsr_q[PRBS_WIDTH:1];
end

assign prbs_o = EYE_TEST ? {prbs[PRBS_WIDTH-1:PRBS_WIDTH-8], prbs[PRBS_WIDTH-1:PRBS_WIDTH-8]} : prbs;

endmodule

