    output reg [5:0] out
);

    wire [5:0] mux_out;
    wire [5:0] demux_out;

    // Multiplexer
    mux_6to1 mux(
        .in({in[0], in[1], in[2], in[3], in[4], in[5]}),
        .sel(select),
        .out(mux_out)
    );

    // Demultiplexer
    demux_1to6 demux(
        .in(out),
        .sel(select),
        .out({demux_out[0], demux_out[1], demux_out[2], demux_out[3], demux_out[4], demux_out[5]})
    );

    // Control logic
    always @ (select) begin
        if (select == 1'b0) begin
            out <= {demux_out[0], demux_out[1], demux_out[2], demux_out[3], demux_out[4], demux_out[5]};
        end else begin
            out <= mux_out;
        end
    end

endmodule

module mux_6to1(
    input [5:0] in,
    input sel,
    output reg [5:0] out
);

    always @ (in, sel) begin
        case (sel)
            2'b00: out <= in[0];
            2'b01: out <= in[1];
            2'b10: out <= in[2];
            2'b11: out <= in[3];
            default: out <= 6'b0;
        endcase
    end

endmodule

module demux_1to6(
    input [5:0] in,
    input sel,
    output reg [5:0] out
);

    always @ (in, sel) begin
        case (sel)
            2'b00: out <= {in, 4'b0000};
            2'b01: out <= {4'b0000, in};
            default: out <= 6'b0;
        endcase
    end

endmodule

module data_serializer(
