    output reg [99:0] sum, // Output port for sum
    output reg cout // Output port for carry-out
);

    always @(*) begin
        {cout, sum} = a + b + cin;
    end

endmodule

// 4-bit binary counter module
module binary_counter(
    input clk, // Clock input
    input reset, // Synchronous active-high reset input
    output reg [3:0] out // Output port for counter value
);

    always @(posedge clk) begin
        if (reset) begin
            out <= 4'b0;
        end else begin
            out <= out + 1;
        end
    end

endmodule

// Functional module that adds the output of the adder to the counter value
module functional_module(
    input [99:0] adder_out, // Input port for output of 100-bit binary adder
    input [3:0] counter_out, // Input port for output of 4-bit binary counter
    output reg [99:0] final_sum // Output port for final sum
);

    always @(*) begin
        final_sum = adder_out + {96'b0, counter_out};
    end

endmodule

module PicoBlaze_OutReg
    #(parameter LOCAL_PORT_ID = 8'h00)
    (
    clk,
    reset,
    port_id,
    write_strobe,
    out_port,
    new_out_port
    );

    input wire clk;
    input wire reset;
    input wire [7:0] port_id;
    input wire write_strobe;
    input wire [7:0] out_port;
    output reg [7:0] new_out_port;

    reg RegEnable = 1;

    always @(*)
    begin
        if(write_strobe == 1)
        begin
            case(port_id)
                LOCAL_PORT_ID: RegEnable = 1;
                default: RegEnable = 0;
            endcase
        end
        else
        begin
            RegEnable = 0;
        end
    end

    always @(posedge clk, posedge reset)
    begin
        if(reset == 1)
        begin
            new_out_port <= 8'h00;
        end
        else
        begin
            if(RegEnable == 1)
            begin
                new_out_port <= out_port;
            end
            else
            begin
                new_out_port <= new_out_port;
            end
        end
    end

endmodule

module pulse_generator #
(
  parameter         CONTINUOUS = "FALSE"
)
(
  input  wire        aclk,
  input  wire        aresetn,

  input  wire [95:0] cfg,

  output wire        dout
);

  reg int_dout_reg, int_dout_next;
  reg [31:0] int_cntr_reg, int_cntr_next;

  always @(posedge aclk)
  begin
    if(~aresetn)
    begin
      int_dout_reg <= 1'b0;
      int_cntr_reg <= 32'd0;
    end
    else
    begin
      int_dout_reg <= int_dout_next;
      int_cntr_reg <= int_cntr_next;
    end
  end

  always @*
  begin
    int_dout_next = int_dout_reg;

    if(int_cntr_reg == cfg[31:0])
    begin
      int_dout_next = 1'b1;
    end

    if(int_cntr_reg == cfg[63:32])
    begin
      int_dout_next = 1'b0;
    end
  end

  generate
    if(CONTINUOUS == "TRUE")
    begin : CONTINUOUS
      always @*
      begin
        int_cntr_next = int_cntr_reg;

        if(int_cntr_reg < cfg[95:64])
        begin
          int_cntr_next = int_cntr_reg + 1'b1;
        end
        else
        begin
          int_cntr_next = 32'd0;
        end
      end
    end
    else
    begin : STOP
      always @*
      begin
        int_cntr_next = int_cntr_reg;

        if(int_cntr_reg < cfg[95:64])
        begin
          int_cntr_next = int_cntr_reg + 1'b1;
        end
      end
    end
  endgenerate

  assign dout = int_dout_reg;

endmodule

module mux4to1 (
    in0,
    in1,
    in2,
    in3,
    out,
    sel0,
    sel1
);

    input in0, in1, in2, in3, sel0, sel1;
    output out;

    wire w1, w2, w3;

    assign w1 = sel0 & sel1;
    assign w2 = sel0 & ~sel1;
    assign w3 = ~sel0 & sel1;

    assign out = (w1 & in3) | (w2 & in2) | (w3 & in1) | (~sel0 & ~sel1 & in0);

endmodule

module search_and_shift (
    input [15:0] array [7:0], // Array of sorted 16-bit integers
    input [15:0] search_key, // 16-bit input for the search key
    input [3:0] shift_amount, // 4-bit input for the shift amount
    output reg [2:0] index, // 3-bit output for the index of the search key in the array
    output reg overflow // 1-bit output indicating whether the shifted search key is greater than 16 bits
);

reg [15:0] shifted_key;
integer i;
integer left;
integer right;
integer mid;
reg found;

always @(*) begin
    shifted_key = search_key << shift_amount;
    overflow = (shift_amount > 15) ? 1'b1 : 1'b0;
    left = 0;
    right = 7;
    found = 0;
    index = 3'b111;

    while (left <= right && !found && !overflow) begin
        mid = (left + right) / 2;
        if (array[mid] == shifted_key) begin
            found = 1;
            index = mid;
        end else if (array[mid] < shifted_key) begin
            left = mid + 1;
        end else begin
            right = mid - 1;
        end
    end
end

endmodule

