module barrel_shift_up_down_counter (
    input clk,
    input [15:0] data_in,
    input [3:0] shift_amount,
    input shift_direction,
    input U_D,
    output reg [15:0] final_output
);

    reg [15:0] shifted_data;
    reg [3:0] counter;

    always @(posedge clk) begin
        // Perform barrel shift operation
        if (shift_direction == 0) begin
            shifted_data = data_in << shift_amount;
        end else begin
            shifted_data = data_in >> shift_amount;
        end

        // Connect barrel shifter output to up/down counter input
        if (U_D == 0) begin
            counter <= counter + 1;
        end else begin
            counter <= counter - 1;
        end

        // Limit counter to range 0-15
        if (counter > 15) begin
            counter <= 15;
        end else if (counter < 0) begin
            counter <= 0;
        end

        // Perform arithmetic operation on shifted data and counter output
        if (U_D == 0) begin
            final_output <= shifted_data + counter;
        end else begin
            final_output <= shifted_data - counter;
        end
    end

endmodule

