module perfect_shuffle #(
  parameter NUM_GROUPS = 2,
  parameter WORDS_PER_GROUP = 2,
  parameter WORD_WIDTH = 8
) (
  input [NUM_GROUPS*WORDS_PER_GROUP*WORD_WIDTH-1:0] data_in,
  output [NUM_GROUPS*WORDS_PER_GROUP*WORD_WIDTH-1:0] data_out
);

  // Define localparams for readability
  localparam NUM_WORDS = NUM_GROUPS * WORDS_PER_GROUP;
  localparam GROUP_WIDTH = WORDS_PER_GROUP * WORD_WIDTH;
  localparam WORDS_PER_GROUP_OUT = NUM_GROUPS;

  generate
    genvar i;
    genvar j;
    for (i = 0; i < NUM_GROUPS; i = i + 1) begin: shuffle_outer
      for (j = 0; j < WORDS_PER_GROUP; j = j + 1) begin: shuffle_inner
        localparam src_lsb = (j + i * WORDS_PER_GROUP) * WORD_WIDTH;
        localparam dst_lsb = (i + j * NUM_GROUPS) * WORD_WIDTH;

        assign data_out[dst_lsb+:WORD_WIDTH] = data_in[src_lsb+:WORD_WIDTH];
      end
    end
  endgenerate

  // Define localparams for readability
  localparam NUM_GROUPS_OUT = WORDS_PER_GROUP;
  localparam GROUP_WIDTH_OUT = NUM_GROUPS * WORD_WIDTH;
  localparam WORDS_PER_GROUP_IN = NUM_GROUPS;

  generate
    genvar i;
    genvar j;
    for (i = 0; i < WORDS_PER_GROUP_OUT; i = i + 1) begin: unshuffle_outer
      for (j = 0; j < NUM_GROUPS_OUT; j = j + 1) begin: unshuffle_inner
        localparam src_lsb = (j + i * NUM_GROUPS_OUT) * WORD_WIDTH;
        localparam dst_lsb = (i + j * WORDS_PER_GROUP_IN) * WORD_WIDTH;

        assign data_in[dst_lsb+:WORD_WIDTH] = data_out[src_lsb+:WORD_WIDTH];
      end
    end
  endgenerate

endmodule

module unsigned_sqrt (
    input [3:0] num,
    output reg [3:0] sqrt
);

reg [3:0] num_reg;
reg [1:0] stage;
reg [3:0] sqrt_reg;
reg [3:0] sqrt_next;
reg [3:0] num_next;
reg [3:0] num_temp;

always @(*) begin
    num_reg = num;
end

always @(posedge clk) begin
    case(stage)
        0: begin
            sqrt_reg <= 2'b0;
            num_next <= num_reg;
            num_temp <= num_reg;
        end
        1: begin
            sqrt_reg <= {sqrt_reg[2:0], 1'b0};
            num_next <= {num_temp[2:0], 1'b0};
            num_temp <= num_temp - {sqrt_reg[2:0], 1'b0};
        end
        2: begin
            sqrt_reg <= {sqrt_reg[1:0], 1'b1};
            num_next <= {num_temp[1:0], 2'b00};
            num_temp <= num_temp - {sqrt_reg[1:0], 2'b00};
        end
        3: begin
            sqrt_reg <= {sqrt_reg[0], 1'b0};
            num_next <= {num_temp[0], 3'b000};
            num_temp <= num_temp - {sqrt_reg[0], 3'b000};
        end
        default: begin
            sqrt_reg <= sqrt_reg;
            num_next <= num_next;
            num_temp <= num_temp;
        end
    endcase
    stage <= stage + 1;
end

always @(posedge clk) begin
    case(stage)
        0: begin
            sqrt_next <= 2'b0;
        end
        1: begin
            sqrt_next <= {sqrt_reg[2:0], 1'b1};
        end
        2: begin
            sqrt_next <= {sqrt_reg[1:0], 1'b0};
        end
        3: begin
            sqrt_next <= {sqrt_reg[0], 1'b1};
        end
        default: begin
            sqrt_next <= sqrt_next;
        end
    endcase
end

always @(posedge clk) begin
    sqrt <= sqrt_next;
    num_reg <= num_next;
    if(stage == 3) begin
        stage <= 0;
    end
end

endmodule

module memory(clk, rst, read_addr, write_addr, write_data, read_data);

parameter WIDTH = 64;
parameter SIZE = 1024;
parameter LATENCY = 10;

input clk, rst;
input [log2(SIZE)-1:0] read_addr, write_addr;
input [WIDTH-1:0] write_data;
output reg [WIDTH-1:0] read_data;

reg [WIDTH-1:0] mem [0:SIZE-1];
reg [log2(SIZE)-1:0] read_addr_reg, write_addr_reg;
reg [WIDTH-1:0] write_data_reg;
reg [LATENCY-1:0] write_latency, read_latency;

always @(posedge clk) begin
    if (rst) begin
        for (i = 0; i < SIZE; i = i + 1) begin
            mem[i] <= 0;
        end
        read_data <= 0;
        read_addr_reg <= 0;
        write_addr_reg <= 0;
        write_data_reg <= 0;
        write_latency <= 0;
        read_latency <= 0;
    end else begin
        // Write operation
        if (write_latency > 0) begin
            write_latency <= write_latency - 1;
        end else if (write_addr_reg != write_addr) begin
            write_addr_reg <= write_addr;
            write_data_reg <= write_data;
            write_latency <= LATENCY - 1;
            mem[write_addr] <= write_data;
        end else if (write_addr_reg == write_addr) begin
            write_latency <= LATENCY - 1;
            mem[write_addr] <= write_data_reg;
        end

        // Read operation
        if (read_latency > 0) begin
            read_latency <= read_latency - 1;
        end else if (read_addr_reg != read_addr) begin
            read_addr_reg <= read_addr;
            read_latency <= LATENCY - 1;
            read_data <= mem[read_addr];
        end else if (read_addr_reg == read_addr) begin
            read_latency <= LATENCY - 1;
            read_data <= mem[read_addr_reg];
        end
    end
end

