    input [31:0] array [0:65535],
    input [15:0] length,
    input [31:0] target,
    output reg [15:0] index
);

reg [15:0] low = 0;
reg [15:0] high = length - 1;
reg [15:0] mid;
reg [31:0] mid_val;

always @(posedge clk) begin
    if (reset) begin
        low <= 0;
        high <= length - 1;
        index <= -1;
    end else begin
        mid <= (low + high) / 2;
        mid_val <= array[mid];

        if (mid_val == target) begin
            index <= mid;
        end else if (mid_val < target) begin
            low <= mid + 1;
        end else begin
            high <= mid - 1;
        end

        if (low > high) begin
            index <= -1;
        end
    end
end

endmodule

