module fletcher_checksum (
  input [n*w-1:0] data_in,
  output [m*w-1:0] checksum_out
);

parameter n = 32; // number of input signals
parameter m = 16; // number of output signals
parameter w = 8;  // block size in bits

reg [w-1:0] data_block [0:n-1];
reg [w-1:0] sum1 = 0;
reg [w-1:0] sum2 = 0;

integer i, j;

// Generate checksum
always @ (data_in) begin
  sum1 <= 0;
  sum2 <= 0;
  for (i = 0; i < n; i = i + 1) begin
    for (j = 0; j < w; j = j + 1) begin
      sum1 <= sum1 + data_block[i][j];
      sum2 <= sum2 + sum1;
    end
  end
  checksum_out <= {sum1, sum2};
end

endmodule

module fletcher_check (
  input [n*w-1:0] data_in,
  input [m*w-1:0] checksum_in,
  output error
);

parameter n = 32; // number of input signals
parameter m = 16; // number of output signals
parameter w = 8;  // block size in bits

reg [w-1:0] data_block [0:n-1];
reg [w-1:0] sum1 = 0;
reg [w-1:0] sum2 = 0;
wire [m*w-1:0] computed_checksum;

integer i, j;

// Compute checksum
always @ (data_in) begin
  sum1 <= 0;
  sum2 <= 0;
  for (i = 0; i < n; i = i + 1) begin
    for (j = 0; j < w; j = j + 1) begin
      sum1 <= sum1 + data_block[i][j];
      sum2 <= sum2 + sum1;
    end
  end
  computed_checksum <= {sum1, sum2};
end

// Check for errors
assign error = (computed_checksum == checksum_in) ? 1'b0 : 1'b1;

endmodule

