  reg [15:0] IR_q;
  reg [15:0] MAR_q;
  reg [15:0] MDR_q;
  reg [15:0] ACC_next;
  reg [15:0] PC_next;
  reg [15:0] LINK_next;
  wire [3:0] opcode;
  wire [15:0] operand;
  wire zero;

  // Instruction decode
  assign opcode = data[15:12];
  assign operand = data[11:0];

  // ALU operations
  always @ (posedge clk)
    case (opcode)
      4'b0000: ACC_next <= ACC_q + MDR_q; // ADD
      4'b0001: ACC_next <= ACC_q - MDR_q; // SUB
      4'b0010: ACC_next <= MDR_q; // LD
      4'b0011: MDR_q <= ACC_q; // ST
      4'b0100: PC_next <= (ACC_q == 0) ? operand : PC_q; // JZ
      4'b0101: PC_next <= operand; // JMP
      4'b0110: $finish; // HALT
      default: ACC_next <= ACC_q;
    endcase

  // Memory operations
  always @ (posedge clk)
    if (rnw && !zero)
      MDR_q <= mem[address];
    else if (!rnw && !zero)
      mem[address] <= ACC_q;

  // Register updates
  always @ (posedge clk)
    begin
      if (reset_b == 0)
        begin
          PC_q <= 16'h0000;
          ACC_q <= 16'h0000;
          LINK_q <= 16'h0000;
          IR_q <= 16'h0000;
        end
      else
        begin
          IR_q <= data;
          MAR_q <= address;
          PC_next <= PC_q + 1;
          LINK_next <= PC_q;
          if (opcode == 4'b0010)
            MDR_q <= mem[operand];
          else if (opcode == 4'b0011)
            MAR_q <= operand;
          else
            MDR_q <= ACC_q;
          ACC_q <= ACC_next;
          PC_q <= PC_next;
          LINK_q <= LINK_next;
        end
    end

  // Zero flag
  assign zero = (ACC_q == 0);

endmodule

module top_module (
    input clk,
    input [7:0] in,
    output reg [7:0] q
);

// Edge Detection Module
reg [7:0] in_prev;
wire [7:0] edge_detected;
always @(posedge clk) begin
    in_prev <= in;
end
assign edge_detected = in ^ in_prev;

// Dual-Edge Triggered Flip-Flop Module
reg [7:0] flip_flop_out;
always @(posedge clk or negedge clk) begin
    flip_flop_out <= edge_detected;
end

// Functional Module
assign q = edge_detected | flip_flop_out;

endmodule

module binary_to_decimal (binary, decimal);

    input [3:0] binary;
    output [2:0] decimal;

    assign decimal = 8 * binary[3] + 4 * binary[2] + 2 * binary[1] + binary[0];

endmodule

module pcm_dac (
    input 				  clk,		// Main Clock
    input  		[15:0]  dac_L,		// Left DAC 
    input 		[15:0]  dac_R,		// Right DAC 
    input 				  wren_L,	// Write data to Left DAC
    input 				  wren_R,	// Write data to Right DAC
    output 				  audio_L,	// Left PCM audio output
    output 				  audio_R	// Right PCM audio output
);

  // --------------------------------------------------------------------
  // DAC CLock Generation Section:
  // We need to divide down the clock for PCM, clk = 50Mhz
  // then 50,000,000 / 256 = 195,312.5Hz which is ~2X highest CODEC rate (96Khz)
  // 0 =   2 => 25,000,000.00 Hz
  // 1 =   4 => 12,500,000.00 Hz
  // 2 =   8 =>  6,250,000.00 Hz
  // 3 =  16 =>  3,125,000.00 Hz
  // 4 =  32 =>  1,562,500.00 Hz
  // 5 =  64 =>    781,250.00 Hz
  // 6 = 128 =>    390,625.00 Hz
  // 7 = 256 =>    195,312.50 Hz
  // 8 = 512 =>     97,656.25 Hz
  // --------------------------------------------------------------------
  wire       dac_clk = clkdiv[4];
  reg  [8:0] clkdiv;
  always @(posedge clk) clkdiv <= clkdiv + 9'd1; 

  // --------------------------------------------------------------------
  // Pulse the DAC data into the DAC registers
  // --------------------------------------------------------------------
  always @(posedge wren_L) begin
    dsp_audio_l <= {~dac_L[15], dac_L[14:0]};
  end

  always @(posedge wren_R) begin
    dsp_audio_r <= {~dac_R[15], dac_R[14:0]};
  end

  // --------------------------------------------------------------------
  // Audio Generation Section
  // --------------------------------------------------------------------
  reg [15:0] dsp_audio_l;
  reg [15:0] dsp_audio_r;
  dac16 left (.clk(dac_clk),.DAC_in(dsp_audio_l),.audio_out(audio_L));
  dac16 right(.clk(dac_clk),.DAC_in(dsp_audio_r),.audio_out(audio_R));

endmodule

module pcm_dac_clock (
    input 				  clk,		// Main Clock
    input 				  clk_sel,	// Clock division factor selection
    output 				  dac_clk	// DAC Clock
);

  // Generate the clock division factor
  reg [8:0] clkdiv;
  always @(posedge clk) clkdiv <= clkdiv + 9'd1; 

  // Generate the DAC clock signal
  wire [2:0] clk_div_factors = {3'b000, 3'b001, 3'b010, 3'b011, 3'b100, 3'b101, 3'b110, 3'b111};
  assign dac_clk = clkdiv[clk_div_factors[clk_sel]];

endmodule

module cache(
    input enable,
    input [1:0] word,
    input cmp,
    input write,
    input rst,
    input [4:0] tag,
    input [15:0] data_in,
    input valid_in,
    input ack,
    output [15:0] data_out,
    output hit,
    output dirty,
    output valid
);

wire [15:0] data_out_0;
wire [15:0] data_out_1;
wire [15:0] data_out_2;
wire [15:0] data_out_3;

wire hit_0;
wire hit_1;
wire hit_2;
wire hit_3;

wire dirty_0;
wire dirty_1;
wire dirty_2;
wire dirty_3;

wire valid_0;
wire valid_1;
wire valid_2;
wire valid_3;

reg [1:0] lru;

assign data_out = (lru == 0) ? data_out_0 :
                 (lru == 1) ? data_out_1 :
                 (lru == 2) ? data_out_2 :
                              data_out_3;

assign hit = hit_0 | hit_1 | hit_2 | hit_3;

assign dirty = (lru == 0) ? dirty_0 :
               (lru == 1) ? dirty_1 :
               (lru == 2) ? dirty_2 :
                            dirty_3;

assign valid = (lru == 0) ? valid_0 :
               (lru == 1) ? valid_1 :
               (lru == 2) ? valid_2 :
                            valid_3;

way way0(enable, word, cmp, write, rst, tag, data_in, valid_in, hit_0, dirty_0, _, data_out_0, valid_0, ack);
way way1(enable, word, cmp, write, rst, tag, data_in, valid_in, hit_1, dirty_1, _, data_out_1, valid_1, ack);
way way2(enable, word, cmp, write, rst, tag, data_in, valid_in, hit_2, dirty_2, _, data_out_2, valid_2, ack);
way way3(enable, word, cmp, write, rst, tag, data_in, valid_in, hit_3, dirty_3, _, data_out_3, valid_3, ack);

always @(posedge ack) begin
    if (hit) begin
        lru <= (lru == 0) ? 0 :
               (lru == 1) ? 1 :
               (lru == 2) ? 2 :
                            3;
    end else begin
        lru <= (lru == 3) ? 0 :
               (lru == 2) ? 3 :
               (lru == 1) ? 2 :
                            1;
    end
end

endmodule

module fifo(
    input rd,
    input wr,
    input [7:0] din,
    output [7:0] dout,
    output empty,
    output full,
    input clock,
    input reset
);

reg [7:0] mem [0:15];
reg [3:0] head;
reg [3:0] tail;
reg full_reg;
reg empty_reg;

assign dout = mem[tail];

always @(posedge clock) begin
    if (reset) begin
        head <= 0;
        tail <= 0;
        full_reg <= 0;
        empty_reg <= 1;
    end else begin
        if (wr && !full_reg) begin
            mem[head] <= din;
            head <= (head == 15) ? 0 : head + 1;
            empty_reg <= 0;
            if (head == tail) begin
                full_reg <= 1;
            end
        end
        if (rd && !empty_reg) begin
            tail <= (tail == 15) ? 0 : tail + 1;
            full_reg <= 0;
            if (tail == head) begin
                empty_reg <= 1;
            end
        end
    end
end

assign empty = empty_reg;
assign full = full_reg;

endmodule

module DisplayPort_Transmitter (
  input pixel_clk,
  input [7:0] video_data,
  input hsync,
  input vsync,
  input blank,
  input [3:0] audio_data,
  output tx_p,
  output tx_n,
  output aux_p,
  output aux_n
);

  // Define the data format and encoding used by the DisplayPort interface
  parameter DATA_WIDTH = 8;
  parameter AUX_WIDTH = 4;
  parameter SYMBOL_WIDTH = 10;
  parameter SYNC_WIDTH = 2;
  parameter BLANK_WIDTH = 6;
  parameter AUDIO_WIDTH = 4;

  // Define the symbols used for the DisplayPort interface
  parameter SYMBOL_IDLE = 10'b0000000000;
  parameter SYMBOL_SYNC = 10'b0011111100;
  parameter SYMBOL_BLANK = 10'b1100000000;
  parameter SYMBOL_AUDIO = 10'b0100000000;
  parameter SYMBOL_VIDEO = 10'b1000000000;

  // Define the encoding scheme used for the DisplayPort interface
  function [SYMBOL_WIDTH-1:0] encode_symbol;
    input [DATA_WIDTH-1:0] data;
    input [SYMBOL_WIDTH-1:0] symbol;
    begin
      encode_symbol = {symbol[9:0] ^ data[7:0], ~symbol[9:0]};
    end
  endfunction

  // Define the transmitter logic
  reg [SYMBOL_WIDTH-1:0] tx_symbol;
  reg [SYMBOL_WIDTH-1:0] tx_next_symbol;
  reg [SYMBOL_WIDTH-1:0] tx_idle_count;
  reg [SYMBOL_WIDTH-1:0] tx_sync_count;
  reg [SYMBOL_WIDTH-1:0] tx_blank_count;
  reg [SYMBOL_WIDTH-1:0] tx_audio_count;
  reg [SYMBOL_WIDTH-1:0] tx_video_count;
  reg [DATA_WIDTH-1:0] tx_data;
  reg [AUX_WIDTH-1:0] tx_aux_data;
  reg tx_idle;
  reg tx_sync;
  reg tx_blank;
  reg tx_audio;
  reg tx_video;
  reg tx_data_valid;
  reg tx_aux_valid;

  always @(posedge pixel_clk) begin
    // Generate the next symbol based on the current state
    case (tx_symbol)
      SYMBOL_IDLE: begin
        if (tx_idle_count == 0) begin
          tx_next_symbol = SYMBOL_SYNC;
          tx_sync_count = SYNC_WIDTH;
        end else begin
          tx_next_symbol = SYMBOL_IDLE;
          tx_idle_count = tx_idle_count - 1;
        end
      end

      SYMBOL_SYNC: begin
        if (tx_sync_count == 0) begin
          tx_next_symbol = SYMBOL_BLANK;
          tx_blank_count = BLANK_WIDTH;
        end else begin
          tx_next_symbol = SYMBOL_SYNC;
          tx_sync_count = tx_sync_count - 1;
        end
      end

      SYMBOL_BLANK: begin
        if (tx_blank_count == 0) begin
          if (tx_audio) begin
            tx_next_symbol = SYMBOL_AUDIO;
            tx_audio_count = AUDIO_WIDTH;
          end else if (tx_video) begin
            tx_next_symbol = SYMBOL_VIDEO;
            tx_video_count = DATA_WIDTH;
          end else begin
            tx_next_symbol = SYMBOL_IDLE;
            tx_idle_count = SYNC_WIDTH;
          end
        end else begin
          tx_next_symbol = SYMBOL_BLANK;
          tx_blank_count = tx_blank_count - 1;
        end
      end

      SYMBOL_AUDIO: begin
        if (tx_audio_count == 0) begin
          tx_next_symbol = SYMBOL_BLANK;
          tx_blank_count = BLANK_WIDTH;
        end else begin
          tx_next_symbol = encode_symbol(tx_aux_data, SYMBOL_AUDIO);
          tx_audio_count = tx_audio_count - 1;
        end
      end

      SYMBOL_VIDEO: begin
        if (tx_video_count == 0) begin
          tx_next_symbol = SYMBOL_BLANK;
          tx_blank_count = BLANK_WIDTH;
        end else begin
          tx_next_symbol = encode_symbol(tx_data, SYMBOL_VIDEO);
          tx_video_count = tx_video_count - 1;
        end
      end
    endcase

    // Update the current state based on the next symbol
    tx_symbol <= tx_next_symbol;

    // Generate the differential signals for the current symbol
    case (tx_symbol)
      SYMBOL_IDLE: begin
        tx_p <= 1'b0;
        tx_n <= 1'b0;
        aux_p <= 1'b0;
        aux_n <= 1'b0;
      end

      SYMBOL_SYNC: begin
        tx_p <= 1'b1;
        tx_n <= 1'b0;
        aux_p <= 1'b0;
        aux_n <= 1'b0;
      end

      SYMBOL_BLANK: begin
        tx_p <= 1'b0;
        tx_n <= 1'b1;
        aux_p <= 1'b0;
        aux_n <= 1'b0;
      end

      SYMBOL_AUDIO: begin
        tx_p <= tx_data_valid ? 1'b1 : 1'b0;
        tx_n <= tx_data_valid ? 1'b0 : 1'b1;
        aux_p <= tx_aux_valid ? 1'b1 : 1'b0;
        aux_n <= tx_aux_valid ? 1'b0 : 1'b1;
      end

      SYMBOL_VIDEO: begin
        tx_p <= tx_data_valid ? 1'b1 : 1'b0;
        tx_n <= tx_data_valid ? 1'b0 : 1'b1;
        aux_p <= 1'b0;
        aux_n <= 1'b0;
      end
    endcase
  end

  // Update the data and auxiliary data inputs
  always @(posedge pixel_clk) begin
    if (tx_video_count > 0) begin
      tx_data <= video_data;
      tx_data_valid <= 1'b1;
    end else begin
      tx_data <= 0;
      tx_data_valid <= 1'b0;
    end

    if (tx_audio_count > 0) begin
      tx_aux_data <= audio_data;
      tx_aux_valid <= 1'b1;
    end else begin
      tx_aux_data <= 0;
      tx_aux_valid <= 1'b0;
    end
  end

endmodule

