module left_shift (
    input [3:0] in,
    output [3:0] out
);

    // Module supplies
    supply1 VPWR;
    supply0 VGND;

    // Local signals
    wire [3:0] temp;
    wire [3:0] shifted;

    // Assign the input to temp
    assign temp = in;

    // Shift the bits in temp to the left by one position and assign the result to shifted
    assign shifted = {temp[2:0], temp[3]};

    // Assign shifted to the output
    assign out = shifted;

endmodule

module barrel_shifter (
    input [3:0] data_in,
    input [1:0] shift_amount,
    output reg [3:0] shifted_out
);

always @(*) begin
    case(shift_amount)
        2'b00: shifted_out = data_in;
        2'b01: shifted_out = {data_in[2:0], 1'b0};
        2'b10: shifted_out = {1'b0, data_in[3:1]};
        2'b11: shifted_out = 4'b0000;
    endcase
end

endmodule

module gray_code_generator (
    input [3:0] shifted_in,
    output reg [5:0] gray_code_out
);

always @(*) begin
    gray_code_out[0] = shifted_in[0];
    gray_code_out[1] = shifted_in[0] ^ shifted_in[1];
    gray_code_out[2] = shifted_in[1] ^ shifted_in[2];
    gray_code_out[3] = shifted_in[2] ^ shifted_in[3];
    gray_code_out[4] = shifted_in[3];
    gray_code_out[5] = gray_code_out[4] ^ gray_code_out[3];
end

endmodule

module sum_module (
    input [3:0] data_in,
    input [5:0] gray_code_in,
    output [7:0] sum_out
);

assign sum_out = data_in + gray_code_in;

