module ECC_memory_block (
  input [n-1:0] data,
  output [n-1:0] corrected
);

parameter n = 8; // number of data signals
parameter m = 3; // number of parity bits

// Generate parity bits using Hamming code algorithm
wire [m-1:0] parity_bits;
genvar i, j;
generate
  for (i = 0; i < m; i = i + 1) begin
    assign parity_bits[i] = ^data[{2**i-1}+:2**i];
  end
  for (i = 0; i < n; i = i + 1) begin
    for (j = 0; j < m; j = j + 1) begin
      if ((i+1) & (2**j) != 0) begin
        assign parity_bits[j] = parity_bits[j] ^ data[i];
      end
    end
  end
endgenerate

// Check parity and correct errors
wire [m-1:0] received_parity_bits;
wire error_detected;
assign received_parity_bits = data[{n-1}:n-m];
assign error_detected = ^({m{received_parity_bits ^ parity_bits}});
assign corrected = error_detected ? (data ^ (1 << (n-1-error_detected))) : data;

endmodule

