module shift_register (
    input parallel_load,
    input reset,
    input shift_left_clk,
    input shift_right_clk,
    input [3:0] data_in,
    output reg [3:0] data_out
);

reg [3:0] stage1, stage2, stage3, stage4;

always @(posedge shift_left_clk or posedge shift_right_clk or posedge parallel_load or posedge reset) begin
    if (reset) begin
        stage1 <= 4'b0000;
        stage2 <= 4'b0000;
        stage3 <= 4'b0000;
        stage4 <= 4'b0000;
    end else if (parallel_load) begin
        stage1 <= data_in;
        stage2 <= stage1;
        stage3 <= stage2;
        stage4 <= stage3;
    end else begin
        stage1 <= (shift_right_clk) ? data_out : stage2;
        stage2 <= (shift_right_clk) ? stage1 : stage3;
        stage3 <= (shift_right_clk) ? stage2 : stage4;
        stage4 <= (shift_right_clk) ? stage3 : data_in;
    end
end

assign data_out = stage1;

endmodule

