module register_file
    (
        // global
        input  wire                clk_i,
        input  wire                reset_i,
        // write port
        input  wire                wreg_a_wr_i,
        input  wire          [4:0] wreg_a_addr_i,
        input  wire          [31:0] wreg_a_data_i,
        input  wire                wreg_b_wr_i,
        input  wire          [4:0] wreg_b_addr_i,
        input  wire          [31:0] wreg_b_data_i,
        // read port
        input  wire                rreg_a_rd_i,
        input  wire          [4:0] rreg_a_addr_i,
        output reg  [31:0] rreg_a_data_o,
        input  wire                rreg_b_rd_i,
        input  wire          [4:0] rreg_b_addr_i,
        output reg  [31:0] rreg_b_data_o
    );

    //--------------------------------------------------------------

    reg [31:0] mem[1:31];

    //--------------------------------------------------------------

    //--------------------------------------------------------------
    // write
    //--------------------------------------------------------------
    always @ (posedge clk_i) begin
        if (reset_i) begin
            mem <= 0;
        end else begin
            // write port a
            if (wreg_a_wr_i) begin
                mem[wreg_a_addr_i] <= wreg_a_data_i;
            end
            // write port b
            if (wreg_b_wr_i) begin
                mem[wreg_b_addr_i] <= wreg_b_data_i;
            end
        end
    end


    //--------------------------------------------------------------
    // read
    //--------------------------------------------------------------
    always @ (*) begin
        // read port a
        if (rreg_a_rd_i && rreg_a_addr_i != 5'b0) begin
            rreg_a_data_o = mem[rreg_a_addr_i];
        end else begin
            rreg_a_data_o = 0;
        end
        // read port b
        if (rreg_b_rd_i && rreg_b_addr_i != 5'b0) begin
            rreg_b_data_o = mem[rreg_b_addr_i];
        end else begin
            rreg_b_data_o = 0;
        end
    end
endmodule

module edge_detection(
  input               clk, // Clock signal
  input               rst_n, // Active low reset
  input [3:0]         data_in, // 4-bit input signal
  output reg          rise_detect, // Rising edge detection output
  output reg          fall_detect, // Falling edge detection output
  output reg          led_rise, // LED for rising edge detection
  output reg          led_fall // LED for falling edge detection
);

  reg [3:0] prev_data; // Previous input signal value
  reg [3:0] curr_data; // Current input signal value
  reg        d_ff; // D flip-flop output

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      prev_data <= 4'b0;
      curr_data <= 4'b0;
      d_ff <= 1'b0;
      rise_detect <= 1'b0;
      fall_detect <= 1'b0;
      led_rise <= 1'b0;
      led_fall <= 1'b0;
    end
    else begin
      prev_data <= curr_data;
      curr_data <= data_in;
      d_ff <= curr_data[0];
      rise_detect <= (d_ff ^ prev_data[0]) & ~d_ff;
      fall_detect <= (d_ff ^ prev_data[0]) & d_ff;
      led_rise <= rise_detect;
      led_fall <= fall_detect;
    end
  end

endmodule

