// Parallel prefix adder module
module parallel_prefix_adder(
  input clk, //Clock input
  input rst_n, //Asynchronous active-low reset input
  input select, //Select input used to choose between two parallel prefix adder configurations
  input [31:0] in_0, //First 32-bit input chunk
  input [31:0] in_1, //Second 32-bit input chunk
  input [31:0] in_2, //Third 32-bit input chunk
  input [31:0] in_3, //Fourth 32-bit input chunk
  output [3:0] out_0, //Output representing the number of '1's in the first two input chunks
  output [3:0] out_1 //Output representing the number of '1's in the last two input chunks
);

  // Configuration 1: 4-bit parallel prefix adder
  wire [3:0] pp_out_0_1;
  wire [3:0] pp_out_1_1;
  parallel_prefix_adder_4bit pp_adder_1 (
    .in_0(in_0),
    .in_1(in_1),
    .out_0(pp_out_0_1),
    .out_1(pp_out_1_1)
  );

  // Configuration 2: 8-bit parallel prefix adder
  wire [7:0] pp_out_0_2;
  wire [7:0] pp_out_1_2;
  parallel_prefix_adder_8bit pp_adder_2 (
    .in_0(in_0),
    .in_1(in_1),
    .in_2(in_2),
    .in_3(in_3),
    .out_0(pp_out_0_2),
    .out_1(pp_out_1_2)
  );

  // Select the appropriate parallel prefix adder configuration based on the select input
  assign out_0 = (select == 1'b0) ? pp_out_0_1 : pp_out_0_2;
  assign out_1 = (select == 1'b0) ? pp_out_1_1 : pp_out_1_2;

endmodule

