  output [3:0] out_0, //Output representing the number of '1's in the first two input chunks
  output [3:0] out_1 //Output representing the number of '1's in the last two input chunks
);

  // Generate the partial sums
  wire [3:0] ps_0 = in_0;
  wire [3:0] ps_1 = in_1;

  // Generate the final sums
  wire [3:0] fs_0;
  wire [3:0] fs_1;
  assign fs_0 = ps_0;
  assign fs_1 = ps_1 + ps_0;

