  output [7:0] out_0, //Output representing the number of '1's in the first two input chunks
  output [7:0] out_1 //Output representing the number of '1's in the last two input chunks
);

  // Generate the partial sums
  wire [7:0] ps_0 = in_0;
  wire [7:0] ps_1 = in_1;
  wire [7:0] ps_2 = in_2;
  wire [7:0] ps_3 = in_3;

  // Generate the final sums
  wire [7:0] fs_0;
  wire [7:0] fs_1;
  assign fs_0 = ps_0;
  assign fs_1 = ps_1 + ps_0;
  assign fs_2 = ps_2 + ps_1 + ps_0;
  assign fs_3 = ps_3 + ps_2 + ps_1 + ps_0;

  // Output the final sums
  assign out_0 = {fs_1[3:0], fs_0};
  assign out_1 = {fs_3[3:0], fs_2};

endmodule

