        4'd7: displayout = seven;
        4'd8: displayout = eight;
        4'd9: displayout = nine;
        4'd10: displayout = 7'b0111111; // A
        4'd11: displayout = 7'b0001111; // b
        4'd12: displayout = 7'b0100111; // C
        4'd13: displayout = 7'b0011110; // d
        4'd14: displayout = 7'b0100111; // E
        4'd15: displayout = 7'b0100011; // F
        default: displayout = blank;
    endcase
end

endmodule

module top_module(
    input clk,
    input reset,
    input [15:0] in,
    input load,
    input ena,
    input select,
    output [7:0] out
);

    // Shift Register
    reg [15:0] shift_reg;
    always @(posedge clk, negedge reset) begin
        if (reset == 0) begin
            shift_reg <= 0;
        end else if (load) begin
            shift_reg <= in;
        end else if (ena) begin
            if (select) begin
                shift_reg <= {shift_reg[14:0], shift_reg[15]};
            end else begin
                shift_reg <= {shift_reg[0], shift_reg[15:1]};
            end
        end
    end

    // Rising Edge Detector
    reg [3:0] red_out;
    reg [15:0] prev_in;
    always @(posedge clk, negedge reset) begin
        if (reset == 0) begin
            red_out <= 0;
            prev_in <= 0;
        end else begin
            red_out <= {prev_in[0] ^ in[0], prev_in[1] ^ in[1], prev_in[2] ^ in[2], prev_in[3] ^ in[3]};
            prev_in <= in;
        end
    end

    // Control Logic
    reg active_module;
    always @(select, ena) begin
        if (ena) begin
            active_module <= select;
        end
    end

    // Output
    always @(active_module, shift_reg, red_out) begin
        if (active_module) begin
            out <= {shift_reg[7:0], red_out[3:0]};
        end else begin
            out <= {shift_reg[7:0], 0};
        end
    end

endmodule

module fifo_1kx16 (
    aclr,
    clock,
    data,
    rdreq,
    wrreq,
    almost_empty,
    empty,
    full,
    q,
    usedw
);

    parameter FIFO_DEPTH = 1024;
    parameter DATA_WIDTH = 16;
    parameter ADDR_WIDTH = $clog2(FIFO_DEPTH);

    input aclr;
    input clock;
    input [DATA_WIDTH-1:0] data;
    input rdreq;
    input wrreq;
    output almost_empty;
    output empty;
    output full;
    output [DATA_WIDTH-1:0] q;
    output [ADDR_WIDTH-1:0] usedw;

    reg [ADDR_WIDTH-1:0] head;
    reg [ADDR_WIDTH-1:0] tail;
    reg [ADDR_WIDTH-1:0] usedw_reg;
    reg [DATA_WIDTH-1:0] fifo_mem [0:FIFO_DEPTH-1];
    wire [ADDR_WIDTH-1:0] next_head = (head == FIFO_DEPTH-1) ? 0 : head+1;
    wire [ADDR_WIDTH-1:0] next_tail = (tail == FIFO_DEPTH-1) ? 0 : tail+1;

    assign usedw = usedw_reg;
    assign empty = (usedw_reg == 0);
    assign full = (usedw_reg == FIFO_DEPTH);
    assign almost_empty = (usedw_reg <= 1);
    assign q = fifo_mem[tail];

    always @(posedge clock) begin
        if (aclr) begin
            head <= 0;
            tail <= 0;
            usedw_reg <= 0;
        end else begin
            if (wrreq && !full) begin
                fifo_mem[head] <= data;
                head <= next_head;
                usedw_reg <= usedw_reg + 1;
            end
            if (rdreq && !empty) begin
                tail <= next_tail;
                usedw_reg <= usedw_reg - 1;
            end
        end
    end

endmodule

module custom_logic (
