module shift_register(
    input start, //% start signal
    input [DATA_WIDTH-1:0] din, //% data input
    input clk, //% clock signal
    input rst, //% reset signal
    output reg data_out, //% data sent to shift register
    output reg load_sr, //% load signal sent to shift register
    output reg [CNT_WIDTH-1:0] count_delay //% count signal sent to Clock_SR.v.
    );

    reg [4:0] current_state_out, next_state_out; //% State machine states
    reg [DATA_WIDTH-1:0] count; //% Counter for bits shifted
    parameter s0=5'b00001;
    parameter s1=5'b00010;
    parameter s2=5'b00100;
    parameter s3=5'b01000;
    parameter s4=5'b10000;
    parameter SHIFT_DIRECTION = 1'b1; //% 0 for right shift, 1 for left shift

    //% State machine 1, used to send signals to SR
    always@(posedge clk or posedge rst) begin
        if(rst) begin
            current_state_out <= s0;
        end else begin
            current_state_out <= next_state_out;
        end
    end  

    always@(current_state_out or rst or start or count) begin
        if(rst) begin
            next_state_out = s0;
        end else begin
            case(current_state_out)
                s0: begin
                    if(start) begin
                        next_state_out = s1;
                    end else begin
                        next_state_out = s0;
                    end
                end
                s1,s2: begin
                    if(count == DATA_WIDTH) begin
                        next_state_out = s3;
                    end else begin
                        next_state_out = s2;
                    end
                end
                s3: begin
                    next_state_out = s4;
                end
                s4: begin
                    next_state_out = s0;
                end
                default: next_state_out = s0;
            endcase
        end
    end

    always@(posedge clk or posedge rst) begin
        if(rst) begin
            count <= 0;
            count_delay <= 0;
            data_out <= 1'b0;
            load_sr <= 1'b0;
        end else begin
            case(next_state_out)
                s0: begin
                    count <= 0;
                    count_delay <= 0;
                    data_out <= 1'b0;
                    load_sr <= 1'b0;
                end
                s1,s2: begin
                    count <= count + 1'b1;
                    count_delay <= count_delay + 1'b1;
                    if(SHIFT_DIRECTION) begin
                        data_out <= din[DATA_WIDTH-1-count];
                    end else begin
                        data_out <= din[count];
                    end
                    load_sr <= 1'b0;
                end
                s3: begin
                    count <= 0;
                    count_delay <= count_delay + 1'b1;
                    data_out <= 1'b0;
                    load_sr <= 1'b1;
                end
                s4: begin
                    count <= 0;
                    count_delay <= 0;
                    data_out <= 1'b0;
                    load_sr <= 1'b0;
                end
                default: begin
                    count <= 0;
                    count_delay <= 0;
                    data_out <= 1'b0;
                    load_sr <= 1'b0;
                end
            endcase
        end
    end

endmodule

module DLL (
  input ref_clk,
  input fb_clk,
  output clk_out
);

parameter delay = 10; // delay time of the DLL
parameter k = 0.5; // gain factor of the DLL

// Define delay line submodule
reg [delay-1:0] delay_line;
always @(posedge ref_clk) begin
  delay_line <= {delay_line[delay-2:0], 1'b0};
end

// Define phase detector submodule
wire xor_out = ref_clk ^ delay_line[delay-1];
wire phase_error = fb_clk ^ xor_out;

// Define control circuit submodule
reg [31:0] integral = 0;
reg [31:0] prev_error = 0;
wire control_out = (k * phase_error) + (k * (integral >> 8));
always @(posedge ref_clk) begin
  prev_error <= phase_error;
  integral <= integral + phase_error;
end

// Generate synchronized clock signal
always @(posedge ref_clk) begin
  clk_out <= delay_line[delay-1] + control_out;
end

endmodule

module binary_counter (
  input clk,
  input reset,
  input load,
  input [3:0] data_in,
  output reg [3:0] count
);

  // Define the three states of the FSM
  parameter [1:0]
    IDLE = 2'b00,
    COUNTING = 2'b01,
    LOADING = 2'b10;

  // Define the current state and next state variables
  reg [1:0] state, next_state;

  // Define the counter register
  reg [3:0] counter_reg;

  // Assign the current state to the next state at the beginning of each clock cycle
  always @ (posedge clk) begin
    state <= next_state;
  end

  // Define the FSM
  always @ (*) begin
    case (state)
      IDLE: begin
        if (reset) begin
          next_state = IDLE;
        end else if (load) begin
          next_state = LOADING;
        end else begin
          next_state = COUNTING;
        end
      end
      COUNTING: begin
        if (reset) begin
          next_state = IDLE;
        end else if (load) begin
          next_state = LOADING;
        end else begin
          next_state = COUNTING;
        end
      end
      LOADING: begin
        next_state = IDLE;
      end
      default: begin
        next_state = IDLE;
      end
    endcase
  end

  // Define the output logic based on the current state
  always @ (*) begin
    case (state)
      IDLE: begin
        count <= counter_reg;
      end
      COUNTING: begin
        counter_reg <= counter_reg + 1;
        count <= counter_reg;
      end
      LOADING: begin
        counter_reg <= data_in;
        count <= counter_reg;
      end
      default: begin
        count <= counter_reg;
      end
    endcase
  end

endmodule

