        case (OPCODE)
            7'b0000000: begin // ADD
                FS <= 4'b0001;
                CNTRL_FLAGS <= 7'b0000001;
            end
            7'b0000001: begin // SUB
                FS <= 4'b0010;
                CNTRL_FLAGS <= 7'b0000001;
            end
            7'b0000010: begin // AND
                FS <= 4'b0100;
                CNTRL_FLAGS <= 7'b0000001;
            end
            7'b0000011: begin // OR
                FS <= 4'b0101;
                CNTRL_FLAGS <= 7'b0000001;
            end
            7'b0000100: begin // XOR
                FS <= 4'b0110;
                CNTRL_FLAGS <= 7'b0000001;
            end
            7'b0000101: begin // NOT
                FS <= 4'b0111;
                CNTRL_FLAGS <= 7'b0000001;
            end
            7'b0000110: begin // LD
                FS <= 4'b0000;
                CNTRL_FLAGS <= 7'b0000000;
            end
            7'b0000111: begin // ST
                FS <= 4'b0000;
                CNTRL_FLAGS <= 7'b0000010;
            end
            default: begin
                FS <= 4'b0000;
                CNTRL_FLAGS <= 7'b0000000;
            end
        endcase
    end
end

