module binary_to_octal_converter(
    input [11:0] binary_input,
    output reg [2:0] octal_output
);

    // Define the fixed 12-bit binary value
    parameter [11:0] FIXED_VALUE = 12'b110011001100;

    // Define the 100-bit carry look-ahead adder
    wire [99:0] adder_output;
    generate
        genvar i;
        for (i = 0; i < 100; i = i + 1) begin
            ripple_carry_adder rca(
                .a(binary_input[i]),
                .b(FIXED_VALUE[i]),
                .cin(i == 0 ? 1'b0 : adder_output[i - 1]),
                .cout(adder_output[i])
            );
        end
    endgenerate

    // Define the 4-bit wide, 16-to-1 multiplexer
    wire [3:0] mux_input = adder_output[99:96];
    wire [3:0] mux_output;
    assign mux_output = {
        (mux_input == 4'b0000) ? octal_output[2:0] :
        (mux_input == 4'b0001) ? octal_output[2:0] :
        (mux_input == 4'b0010) ? octal_output[2:0] :
        (mux_input == 4'b0011) ? octal_output[2:0] :
        (mux_input == 4'b0100) ? octal_output[2:0] :
        (mux_input == 4'b0101) ? octal_output[2:0] :
        (mux_input == 4'b0110) ? octal_output[2:0] :
        (mux_input == 4'b0111) ? octal_output[2:0] :
        (mux_input == 4'b1000) ? octal_output[2:0] :
        (mux_input == 4'b1001) ? octal_output[2:0] :
        (mux_input == 4'b1010) ? octal_output[2:0] :
        (mux_input == 4'b1011) ? octal_output[2:0] :
        (mux_input == 4'b1100) ? octal_output[2:0] :
        (mux_input == 4'b1101) ? octal_output[2:0] :
        (mux_input == 4'b1110) ? octal_output[2:0] :
        (mux_input == 4'b1111) ? octal_output[2:0] : 3'b0
    };

    // Define the binary decoder
    wire [15:0] decoder_output;
    assign decoder_output = 16'b0000_0000_0000_0001;

    // Define the 2-to-1 multiplexers
    wire [3:0] mux1_output;
    assign mux1_output = {
        (decoder_output[15]) ? mux_output[2:0] : octal_output[2:0]
    };
    wire [3:0] mux2_output;
    assign mux2_output = {
        (decoder_output[14]) ? mux1_output[2:0] : octal_output[2:0]
    };
    wire [3:0] mux3_output;
    assign mux3_output = {
        (decoder_output[13]) ? mux2_output[2:0] : octal_output[2:0]
    };
    wire [3:0] mux4_output;
    assign mux4_output = {
        (decoder_output[12]) ? mux3_output[2:0] : octal_output[2:0]
    };

    // Define the final 4-bit output module
    final_output_module final_output(
        .octal_input(mux4_output),
        .final_output(octal_output)
    );

endmodule

module ripple_carry_adder(
    input a,
    input b,
    input cin,
    output reg sum,
    output cout
);

    always @(*) begin
        sum = a ^ b ^ cin;
        cout = (a & b) | (a & cin) | (b & cin);
    end

endmodule

module final_output_module(
    input [2:0] octal_input,
    output reg [3:0] final_output
);

    always @(*) begin
        case (octal_input)
            3'b000: final_output = 4'b0000;
            3'b001: final_output = 4'b0001;
            3'b010: final_output = 4'b0010;
            3'b011: final_output = 4'b0011;
            3'b100: final_output = 4'b0100;
            3'b101: final_output = 4'b0101;
            3'b110: final_output = 4'b0110;
            3'b111: final_output = 4'b0111;
            default: final_output = 4'b0000;
        endcase
    end

endmodule

module fifo_async 
   (/*AUTOARG*/
   // Outputs
   full, prog_full, dout, empty, valid,
   // Inputs
   wr_rst, rd_rst, wr_clk, rd_clk, wr_en, din, rd_en
   );

   parameter DW    = 104;        //FIFO width
   parameter DEPTH = 16;          //FIFO depth

   reg [DW-1:0] fifo [DEPTH-1:0];
   reg [4:0] wr_ptr;
   reg [4:0] rd_ptr;
   wire [4:0] fifo_count;

   assign full = (fifo_count == DEPTH);
   assign prog_full = (fifo_count >= DEPTH-4);
   assign empty = (fifo_count == 0);
   assign valid = (fifo_count > 0);

   always @(posedge wr_clk or negedge wr_rst) begin
      if(!wr_rst) begin
         wr_ptr <= 0;
      end else if(wr_en && !full) begin
         fifo[wr_ptr] <= din;
         wr_ptr <= wr_ptr + 1;
      end
   end

   always @(posedge rd_clk or negedge rd_rst) begin
      if(!rd_rst) begin
         rd_ptr <= 0;
      end else if(rd_en && !empty) begin
         dout <= fifo[rd_ptr];
         rd_ptr <= rd_ptr + 1;
      end
   end

   assign fifo_count = wr_ptr - rd_ptr;

endmodule

module mux_dff(
  input D, SCD, SCE, CLK_N, SET_B, RESET_B,
  output Q, Q_N
);

  wire RESET, SET, CLK, buf_Q, mux_out;

  not not0(RESET, RESET_B);
  not not1(SET, SET_B);
  not not2(CLK, CLK_N);
  sky130_fd_sc_ls__udp_mux_2to1 mux_2to10(mux_out, D, SCD, SCE);
  sky130_fd_sc_ls__udp_dff$NSR `UNIT_DELAY dff0(buf_Q, SET, RESET, CLK, mux_out);
  buf buf0(Q, buf_Q);
  not not3(Q_N, buf_Q);

endmodule

module top_module (
    input clk,
    input reset,
    input [31:0] A,
    input [31:0] B,
    input d,
    output [31:0] D,
    output reg q,
    output reg Cout
);

    // 32-bit adder
    wire [31:0] sum = A + B;

    // D flip-flop
    reg [31:0] d_latch;
    always @(posedge clk) begin
        if (reset) begin
            d_latch <= 0;
            q <= 0;
        end else begin
            d_latch <= d;
            q <= d_latch;
        end
    end

    // Output difference module
    assign D = sum - q;

    // Carry out
    assign Cout = sum[31] & q[31];

endmodule

