);

    binary_gray_converter bin2gray(.binary_in(binary_in), .gray_out(gray_out));
    gray_binary_converter gray2bin(.gray_in(gray_in), .binary_out(binary_out));
    sum_module sum(.gray_in(gray_out), .binary_in(binary_out), .sum_out(sum_out));

    always @(posedge clk, negedge reset) begin
        if (reset == 0) begin
            sum_out <= 0;
        end
    end

endmodule

module Mux(sel, in0, in1, in2, in3, out);
  input sel;
  input in0;
  input in1;
  input in2;
  input in3;
  output out;

  assign out = (sel == 0) ? in0 :
               (sel == 1) ? in1 :
               (sel == 2) ? in2 :
               (sel == 3) ? in3 : 1'b0;

endmodule

module PWM_Controller (
    CLOCK,
    PWM_IN,
    PWM_OUT,
    PWM_WIDTH,
    RESET
);

    input CLOCK;
    input PWM_IN;
    output PWM_OUT;
    input [7:0]PWM_WIDTH;
    input RESET;

    reg [7:0]counter;
    reg output_reg;

    always @(posedge CLOCK) begin
        if (RESET) begin
            counter <= 8'b0;
            output_reg <= 1'b0;
        end else begin
            counter <= counter + 1;
            if (counter >= PWM_WIDTH) begin
                output_reg <= ~output_reg;
                counter <= 8'b0;
            end
        end
    end

    assign PWM_OUT = output_reg & PWM_IN;

endmodule

