);

  always @* begin
    out_ff = a ^ b;
  end

endmodule

module display_module(
    input wire clk,
    input wire rst,
    input wire [7:0] in0,
    input wire [7:0] in1,
    input wire [7:0] in2,
    input wire [7:0] in3,
    output reg [3:0] anode,
    output reg [7:0] cathode
    );

    localparam N = 18;
    reg [N-1:0] q_reg;
    wire [N-1:0] q_next;

    always @(posedge clk, posedge rst) begin
        if (rst) begin
            q_reg <= 0;
            anode <= 4'b1111;
            cathode <= 8'b00000000;
        end else begin
            q_reg <= q_next;
        end
    end

    assign q_next = q_reg + 1;

    always @(*) begin
        case (q_reg[N-1:N-2])
            2'b00: begin
                anode <= 4'b1110;
                cathode <= in0;
            end 
            2'b01: begin
                anode <= 4'b1101;
                cathode <= in1;
            end 
            2'b10: begin
                anode <= 4'b1011;
                cathode <= in2;
            end 
            default: begin
                anode <= 4'b0111;
                cathode <= in3;
            end 
        endcase
    end

endmodule

module top_module (
  input clk,
  input reset,
  input [3:0] a,
  input [3:0] b,
  input sel,
  output [3:0] out
);

  wire [3:0] shifted_data;
  wire [3:0] sum;
  wire carry_out;

  ripple_carry_adder rca_inst(
    .a(a),
    .b(b),
    .shifted_data(shifted_data),
    .sum(sum),
    .carry_out(carry_out)
  );

  shift_register sr_inst(
    .clk(clk),
    .data_in(sum),
    .data_out(shifted_data)
  );

  mux_2to1 mux_inst(
    .sel(sel),
    .data_0(shifted_data),
    .data_1(sum),
    .out(out)
  );

endmodule

module ripple_carry_adder(
  input [3:0] a,
  input [3:0] b,
  input [3:0] shifted_data,
  output [3:0] sum,
  output carry_out
);

  wire [3:0] carry;

  full_adder fa0_inst(
    .a(a[0]),
    .b(b[0]),
    .cin(1'b0),
    .cout(carry[0]),
    .sum(sum[0])
  );

  full_adder fa1_inst(
    .a(a[1]),
    .b(b[1]),
    .cin(carry[0]),
    .cout(carry[1]),
    .sum(sum[1])
  );

  full_adder fa2_inst(
    .a(a[2]),
    .b(b[2]),
    .cin(carry[1]),
    .cout(carry[2]),
    .sum(sum[2])
  );

  full_adder fa3_inst(
    .a(a[3]),
    .b(b[3]),
    .cin(carry[2]),
    .cout(carry_out),
    .sum(sum[3])
  );

  assign shifted_data = {sum[2:0], shifted_data[0]};

endmodule

module full_adder(
  input a, b, cin,
  output cout, sum
);

  assign {cout, sum} = a + b + cin;

endmodule

module shift_register (
  input clk,
  input [3:0] data_in,
  output [3:0] data_out
);

  reg [3:0] data;

  always @(posedge clk) begin
    data <= {data[2:0], data_in[0]};
  end

  assign data_out = {data[2:0], data_in[0]};

endmodule

module mux_2to1 (
  input sel,
  input [3:0] data_0,
  input [3:0] data_1,
  output [3:0] out
);

