module PmodOLEDCtrl(
        CLK,
        RST,
        UPDATE,
        CS,
        SDIN,
        SCLK,
        DC,
        RES,
        VBAT,
        VDD,
        // Position on the screen
        xpos,
        ypos
    );

    // ===========================================================================
    //                                      Port Declarations
    // ===========================================================================
    input CLK;
    input RST;
    input UPDATE;
    output reg CS;
    output reg SDIN;
    output reg SCLK;
    output reg DC;
    output RES;
    output VBAT;
    output VDD;
    // Screen positions
    input [9:0] xpos;
    input [9:0] ypos;

    // ===========================================================================
    //                              Parameters, Registers, and Wires
    // ===========================================================================

    parameter Idle = 2'd0, OledInitialize = 2'd1, OledUpdate = 2'd2, Done = 2'd3;
    reg [1:0] current_state = Idle;

    wire init_en;
    wire init_done;
    wire init_cs;
    wire init_sdo;
    wire init_sclk;
    wire init_dc;

    wire example_en;
    wire example_cs;
    wire example_sdo;
    wire example_sclk;
    wire example_dc;
    wire example_done;

    // ===========================================================================
    //                                      Implementation
    // ===========================================================================

    OledInit Init(
            .CLK(CLK),
            .RST(RST),
            .EN(init_en),
            .CS(init_cs),
            .SDO(init_sdo),
            .SCLK(init_sclk),
            .DC(init_dc),
            .RES(RES),
            .VBAT(VBAT),
            .VDD(VDD),
            .FIN(init_done)
    );

    OledEX Update(
            .CLK(CLK),
            .RST(RST),
            .EN(example_en),
            .CS(example_cs),
            .SDO(example_sdo),
            .SCLK(example_sclk),
            .DC(example_dc),
            .FIN(example_done),
            // Position on the screen
            .xpos(xpos),
            .ypos(ypos)
    );


    //MUXes to indicate which outputs are routed out depending on which block is enabled
    always @(*) begin
        case(current_state)
            OledInitialize: begin
                CS = init_cs;
                SDIN = init_sdo;
                SCLK = init_sclk;
                DC = init_dc;
            end
            OledUpdate: begin
                CS = example_cs;
                SDIN = example_sdo;
                SCLK = example_sclk;
                DC = example_dc;
            end
            default: begin
                CS = 1'b0;
                SDIN = 1'b0;
                SCLK = 1'b0;
                DC = 1'b0;
            end
        endcase
    end

    //MUXes that enable blocks when in the proper states
    assign init_en = (current_state == OledInitialize) ? 1'b1 : 1'b0;
    assign example_en = (current_state == OledUpdate) ? 1'b1 : 1'b0;
    //END enable MUXes


    //  State Machine
    always @(posedge CLK) begin
            if(RST == 1'b1) begin
                    current_state <= Idle;
            end
            else begin
                    case(current_state)
                        Idle : begin
                            current_state <= OledInitialize;
                        end
                        // Go through the initialization sequence
                        OledInitialize : begin
                                if(init_done == 1'b1) begin
                                    current_state <= OledUpdate;
                                end
                        end
                        // Do example and Do nothing when finished
                        OledUpdate : begin
                                if((example_done == 1'b1) && (UPDATE == 1'b0)) begin
                                    current_state <= Done;
                                end
                        end
                        // Do Nothing
                        Done : begin
                                if(UPDATE == 1'b1) begin
                                    current_state <= OledUpdate;
                                end
                        end

                        default : current_state <= Idle;
                    endcase
            end
    end

endmodule

module add_sub (
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] sum
);

    wire [15:0] a_low = a[15:0];
    wire [15:0] a_high = a[31:16];
    wire [15:0] b_low = b[15:0];
    wire [15:0] b_high = b[31:16];
    wire [15:0] carry;

    ripple_adder add_low (
        .a(a_low),
        .b(b_low),
        .carry_in(sub),
        .sum(sum[15:0]),
        .carry_out(carry[0])
    );

    ripple_adder add_high (
        .a(a_high),
        .b(b_high),
        .carry_in(carry[0]),
        .sum(sum[31:16]),
        .carry_out(carry[1])
    );

    xor_gate xor_b (
        .a(b),
        .b({32{sub}}),
        .y(b_xor)
    );

    assign sum = sum + (b_xor << 16);

endmodule

