    joint0_angle <= current_angles[0];
    joint1_angle <= current_angles[1];
    joint2_angle <= current_angles[2];
    joint3_angle <= current_angles[3];
    joint4_angle <= current_angles[4];
    joint5_angle <= current_angles[5];
