module comparator(input [3:0] input1, input [3:0] input2, output output1);

  wire [3:0] carry_out;
  wire [3:0] carry_in;
  wire [3:0] diff;
  wire [3:0] select;

  assign carry_in[0] = 1'b0;
  assign diff = input1 - input2;
  assign select = diff >> 31;

  CARRY4 carry4_0 (.CI(carry_in[0]), .CYINIT(1'b1), .DI(diff), .S(select), .CO(carry_out[0]), .O());

  assign carry_in[1] = carry_out[0];
  assign select = diff >> 30;

  CARRY4 carry4_1 (.CI(carry_in[1]), .CYINIT(1'b0), .DI(diff), .S(select), .CO(carry_out[1]), .O());

  assign carry_in[2] = carry_out[1];
  assign select = diff >> 29;

  CARRY4 carry4_2 (.CI(carry_in[2]), .CYINIT(1'b0), .DI(diff), .S(select), .CO(carry_out[2]), .O());

  assign carry_in[3] = carry_out[2];
  assign select = diff >> 28;

  CARRY4 carry4_3 (.CI(carry_in[3]), .CYINIT(1'b0), .DI(diff), .S(select), .CO(carry_out[3]), .O());

  assign output1 = carry_out[3];

endmodule

module calculator(
    input clk,
    input rst,
    input [7:0] operand1,
    input [7:0] operand2,
    input [1:0] opcode,
    output [7:0] result,
    output ovf,
    output unf
);

    reg [15:0] temp_result;
    reg [7:0] temp_result_lo;
    reg [7:0] temp_result_hi;
    reg ovf_reg;
    reg unf_reg;

    always @(posedge clk) begin
        if (rst) begin
            temp_result <= 0;
            ovf_reg <= 0;
            unf_reg <= 0;
        end else begin
            case (opcode)
                2'b00: temp_result <= operand1 + operand2;
                2'b01: temp_result <= operand1 - operand2;
                2'b10: temp_result <= operand1 * operand2;
                2'b11: begin
                    if (operand2 == 0) begin
                        temp_result <= 0;
                        ovf_reg <= 0;
                        unf_reg <= 0;
                    end else begin
                        temp_result <= operand1 / operand2;
                        if (temp_result > 255) begin
                            temp_result <= 255;
                            ovf_reg <= 1;
                        end else if (temp_result < 0) begin
                            temp_result <= 0;
                            unf_reg <= 1;
                        end
                    end
                end
            endcase
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            temp_result_lo <= 0;
            temp_result_hi <= 0;
        end else begin
            temp_result_lo <= temp_result[7:0];
            temp_result_hi <= temp_result[15:8];
        end
    end

    assign result = {temp_result_hi, temp_result_lo};
    assign ovf = ovf_reg;
    assign unf = unf_reg;

endmodule

