  input in,
  input lo,
  input clk,
  output out
);

  parameter fclk = 10e6; // sampling clock frequency
  parameter fif = 1e6; // intermediate frequency
  parameter bw = 2e6; // bandwidth of input signal

  // Calculate the first mixer output
  wire mixed1 = in * lo;

  // Calculate the band-pass filter output
  wire filtered;
  assign filtered = $bandpass(mixed1, fif, bw, fclk);

  // Calculate the second mixer output
  wire mixed2 = filtered * lo;

  // Output the final signal
  assign out = mixed2;

endmodule

