module uart_state_machine (
  input clk,
  input rst,
  input [7:0] tx_data,
  input tx_start,
  output reg tx_busy,
  output reg [7:0] rx_data,
  output reg rx_valid,
  output reg rx_busy
);

  // Define the states
  parameter IDLE = 2'b00;
  parameter TX = 2'b01;
  parameter RX = 2'b10;

  // Define the state register and initialize it to IDLE
  reg [1:0] state = IDLE;

  // Define the shift register for transmitting data
  reg [9:0] tx_shift_reg = 10'b0;

  // Define the shift register for receiving data
  reg [9:0] rx_shift_reg = 10'b0;

  // Define the bit counter for transmitting data
  reg [3:0] tx_bit_count = 4'b0;

  // Define the bit counter for receiving data
  reg [3:0] rx_bit_count = 4'b0;

  // Define the start and stop bits
  parameter START_BIT = 1'b0;
  parameter STOP_BIT = 1'b1;

  always @(posedge clk) begin
    if (rst) begin
      // Reset the state machine
      state <= IDLE;
      tx_shift_reg <= 10'b0;
      rx_shift_reg <= 10'b0;
      tx_bit_count <= 4'b0;
      rx_bit_count <= 4'b0;
      tx_busy <= 1'b0;
      rx_valid <= 1'b0;
      rx_busy <= 1'b0;
    end else begin
      case (state)
        IDLE: begin
          // Wait for a transmission or reception to start
          if (tx_start) begin
            // Start transmitting data
            state <= TX;
            tx_shift_reg <= {START_BIT, tx_data, STOP_BIT};
            tx_bit_count <= 4'b1;
            tx_busy <= 1'b1;
          end else if (rx_busy) begin
            // Start receiving data
            state <= RX;
            rx_bit_count <= 4'b1;
          end
        end
        TX: begin
          // Transmit data over the UART interface
          if (tx_bit_count < 5) begin
            // Send the next bit
            tx_bit_count <= tx_bit_count + 1;
            tx_shift_reg <= {tx_shift_reg[8:0], 1'b0};
          end else begin
            // Transmission complete
            state <= IDLE;
            tx_busy <= 1'b0;
          end
        end
        RX: begin
          // Receive data over the UART interface
          if (rx_bit_count < 10) begin
            // Receive the next bit
            rx_bit_count <= rx_bit_count + 1;
            rx_shift_reg <= {rx_shift_reg[8:0], rx_data};
          end else begin
            // Reception complete
            state <= IDLE;
            rx_valid <= 1'b1;
            rx_busy <= 1'b0;
          end
        end
      endcase
    end
  end

  // Connect the UART interface to the shift registers
  assign tx_busy = (state == TX);
  assign rx_data = rx_shift_reg[8:1];
  always @(posedge clk) begin
    if (tx_busy) begin
      tx_shift_reg <= {tx_shift_reg[8:0], 1'b0};
    end else if (state == RX) begin
      rx_shift_reg <= {rx_shift_reg[8:0], rx_data};
    end
  end

endmodule

module top_module(
    input               clk         ,
    input               rst_n       ,
    input       [99:0]  a           ,
    input       [99:0]  b           ,
    input               valid_a     ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out
);

    wire [199:0] product;
    wire        valid_product;
    wire        ready_product;
    wire [9:0]  data_in;
    wire        valid_data_in;
    wire        ready_data_in;

    // Instantiate the multiplier module
    multiplier_module multiplier(
        .clk(clk),
        .rst_n(rst_n),
        .a(a),
        .b(b),
        .product(product),
        .valid(valid_product),
        .ready(ready_product)
    );

    // Instantiate the accumulator module
    accumulator_module accumulator(
        .clk(clk),
        .rst_n(rst_n),
        .product(product),
        .valid(valid_product),
        .ready(ready_product),
        .data_in(data_in),
        .valid_data_in(valid_data_in),
        .ready_data_in(ready_data_in),
        .data_out(data_out),
        .valid_b(valid_b),
        .ready_a(ready_a)
    );

    // Valid-ready handshake for input a
    assign ready_a = !valid_a || (valid_a && ready_product);

    // Valid-ready handshake for output b
    assign valid_b = valid_data_in && ready_b;
    assign ready_data_in = valid_b && (data_out != 10);

endmodule

