module top_module(
    input clk,
    input reset,
    input [3:0] a,
    input [3:0] b,
    output reg [7:0] mult_result,
    output reg overflow
);

    // Declare internal signals
    reg [7:0] temp_result;
    wire [3:0] adder_input;
    wire adder_carry;

    // Instantiate the adder module
    adder adder_inst(
        .a(temp_result[3:0]),
        .b(adder_input),
        .sum(mult_result[3:0]),
        .carry(adder_carry)
    );

    // Combinational logic for multiplication
    always @ (a, b) begin
        temp_result = {a, b};
        overflow = (temp_result > 8'b1111_1111) ? 1 : 0;
        adder_input = temp_result[7:4] + temp_result[3:0] * b;
    end

    // Synchronous reset
    always @(posedge clk) begin
        if (reset) begin
            mult_result <= 0;
            overflow <= 0;
        end else begin
            mult_result <= {mult_result[6:0], adder_carry};
        end
    end

endmodule

