module adder_cla (
    input [7:0] a,
    input [7:0] b,
    output [7:0] sum,
    output carry_out,
    output overflow
);

    wire [7:0] p, g;
    wire [8:0] c;
    assign p = a ^ b;
    assign g = a & b;
    assign c[0] = 1'b0;
    generate
        genvar i;
        for (i = 0; i < 8; i = i + 1) begin : gen
            assign c[i+1] = g[i] | (p[i] & c[i]);
        end
    endgenerate
    assign carry_out = c[8];
    assign sum = p ^ c[1:8];
    assign overflow = (a[7] == b[7]) && (a[7] != sum[7]);

endmodule

