module overlay_wrapper (
  input clk,
  input reset,
  input [NUM_INPUTS-1:0] inputs,
  output [NUM_OUTPUTS-1:0] outputs
);

  parameter LUT_SIZE = ZUMA_LUT_SIZE;
  parameter NUM_STAGES = NUM_CONFIG_STAGES;
  parameter CONFIG_WIDTH = LUT_SIZE + 3;

  reg [31:0] next_address;
  reg [31:0] address;

  wire [CONFIG_WIDTH-1:0] cfg;
  wire [CONFIG_WIDTH-1:0] cfg_in;

  reg write;
  reg reset_done;
  reg virtual_reset;

  // Counter for generating configuration addresses
  always @(posedge clk) begin
    if (reset) begin
      next_address <= 32'b0;
      write <= 1'b1;
      reset_done <= 1'b0;
      virtual_reset <= 1'b0;
    end else if (write) begin
      next_address <= next_address + 1;
      if (next_address > (2**LUT_SIZE)*NUM_STAGES) begin
        write <= 1'b0;
      end
    end else if (~reset_done) begin
      virtual_reset <= 1'b1;
      reset_done <= 1'b1;
    end else if (virtual_reset) begin
      virtual_reset <= 1'b0;
    end else begin
      next_address <= next_address;
    end
  end

  // Reverse the retrieved config data
  generate
    genvar i;
    for (i = 0; i < CONFIG_WIDTH; i = i + 1) begin : reverse
      assign cfg_in[CONFIG_WIDTH-1-i] = cfg[i];
    end
  endgenerate

  // Fetch config data for next address
  fixed_config #(.LUT_SIZE(LUT_SIZE), .NUM_STAGES(NUM_STAGES)) config_data (
    .address_in(next_address),
    .clock(clk),
    .q(cfg)
  );

  // Include the actual overlay
  ZUMA_custom_generated XUM (
    .clk(clk),
    .fpga_inputs(inputs),
    .fpga_outputs(outputs),
    .config_data(cfg_in),
    .config_en(write),
    .progress(),
    .config_addr(address),
    .clk2(clk),
    .ffrst(virtual_reset)
  );

endmodule

module erx_core (
    input clk,
    input nreset,
    input [PW-1:0] rx_packet,
    input rx_access,
    input rx_wr_wait,
