    output load_taps,
    output rxrd_access,
    output [PW-1:0] rxrd_packet,
    output rxrr_access,
    output [PW-1:0] rxrr_packet,
    output rxwr_access,
    output [PW-1:0] rxwr_packet,
    output erx_cfg_wait,
    output mailbox_irq
);

    // Define FIFOs
    reg [PW-1:0] rxrd_fifo [0:ERX_RXRD_FIFO_DEPTH-1];
    reg [PW-1:0] rxrr_fifo [0:ERX_RXRR_FIFO_DEPTH-1];
    reg [PW-1:0] rxwr_fifo [0:ERX_RXWR_FIFO_DEPTH-1];

    // Define FIFO pointers
    reg [ERX_FIFO_PTR_WIDTH-1:0] rxrd_fifo_ptr = 0;
    reg [ERX_FIFO_PTR_WIDTH-1:0] rxrr_fifo_ptr = 0;
    reg [ERX_FIFO_PTR_WIDTH-1:0] rxwr_fifo_ptr = 0;

    // Define FIFO access signals
    wire rxrd_fifo_access = (rx_access && !rx_rd_wait);
    wire rxrr_fifo_access = (rx_access && !rx_rd_wait);
    wire rxwr_fifo_access = (rx_access && !rx_wr_wait);

    // Define FIFO wait signals
    reg rxrd_fifo_wait = 0;
    reg rxrr_fifo_wait = 0;
    reg rxwr_fifo_wait = 0;

    // Implement FIFO logic
    always @(posedge clk or negedge nreset) begin
        if (~nreset) begin
            // Reset FIFO pointers
            rxrd_fifo_ptr <= 0;
            rxrr_fifo_ptr <= 0;
            rxwr_fifo_ptr <= 0;

            // Reset FIFO wait signals
            rxrd_fifo_wait <= 0;
            rxrr_fifo_wait <= 0;
            rxwr_fifo_wait <= 0;
        end else begin
            // Handle rxrd FIFO
            if (rxrd_fifo_access) begin
                rxrd_fifo[rxrd_fifo_ptr] <= rx_packet;
                rxrd_fifo_ptr <= (rxrd_fifo_ptr + 1) % ERX_RXRD_FIFO_DEPTH;
            end else if (rxrd_fifo_wait) begin
                rxrd_fifo_wait <= 0;
            end else if (!rxrd_fifo_access) begin
                rxrd_fifo_wait <= 1;
            end

            // Handle rxrr FIFO
            if (rxrr_fifo_access) begin
                rxrr_fifo[rxrr_fifo_ptr] <= rx_packet;
                rxrr_fifo_ptr <= (rxrr_fifo_ptr + 1) % ERX_RXRR_FIFO_DEPTH;
            end else if (rxrr_fifo_wait) begin
                rxrr_fifo_wait <= 0;
            end else if (!rxrr_fifo_access) begin
                rxrr_fifo_wait <= 1;
            end

            // Handle rxwr FIFO
            if (rxwr_fifo_access) begin
                rxwr_fifo[rxwr_fifo_ptr] <= rx_packet;
                rxwr_fifo_ptr <= (rxwr_fifo_ptr + 1) % ERX_RXWR_FIFO_DEPTH;
            end else if (rxwr_fifo_wait) begin
                rxwr_fifo_wait <= 0;
            end else if (!rxwr_fifo_access) begin
                rxwr_fifo_wait <= 1;
            end
        end
    end

    // Define FIFO output signals
    assign rxrd_access = rxrd_fifo_access;
    assign rxrd_packet = rxrd_fifo[rxrd_fifo_ptr];
    assign rxrr_access = rxrr_fifo_access;
    assign rxrr_packet = rxrr_fifo[rxrr_fifo_ptr];
    assign rxwr_access = rxwr_fifo_access;
    assign rxwr_packet = rxwr_fifo[rxwr_fifo_ptr];

    // Implement remaining logic
    assign idelay_value = 45'b0;
    assign load_taps = 0;
    assign erx_cfg_wait = 0;
    assign mailbox_irq = 0;

endmodule

