module carry_lookahead_adder (
    input [7:0] a,
    input [7:0] b,
    output [7:0] s,
    output carry_out
);

wire [7:0] p, g, c;

assign p = a ^ b;
assign g = a & b;
assign c[0] = g[0];

genvar i;
generate
    for (i = 1; i < 8; i = i + 1) begin : gen
        assign c[i] = g[i] | (p[i] & c[i-1]);
    end
endgenerate

assign s = p ^ c;
assign carry_out = c[7];

