    comparator_module cmp_inst (
        .a(add_out),
        .b(4'b1010),
        .out(cmp_out)
    );

    always @ (posedge clk or negedge reset) begin
        if (!reset) begin
            sum <= 5'b0;
            flag <= 1'b0;
        end else begin
            if (select) begin
                sum <= add_out;
                flag <= carry_out;
            end else begin
                sum <= cmp_out ? 5'b1010 : 5'b0;
                flag <= cmp_out;
            end
        end
    end

endmodule

