module bcd_counter (
    input clk,
    input reset,   // Synchronous active-high reset
    input [2:0] ena, // Enable signals for upper three digits
    output reg [15:0] q // 4-digit BCD output
);

reg [3:0] gray_q [0:3]; // Gray code representation of BCD digits
reg [3:0] bcd_q [0:3]; // BCD representation of BCD digits

always @ (posedge clk) begin
    if (reset) begin
        gray_q <= 4'b0000;
        bcd_q <= 4'b0000;
    end else begin
        // Gray code to BCD conversion
        gray_q[0] <= gray_q[0] ^ ena[0];
        bcd_q[0] <= gray_q[0] ^ (gray_q[0] >> 1);
        gray_q[1] <= gray_q[1] ^ (ena[1] & bcd_q[0][3]);
        bcd_q[1] <= gray_q[1] ^ (gray_q[1] >> 1);
        gray_q[2] <= gray_q[2] ^ (ena[2] & bcd_q[1][3]);
        bcd_q[2] <= gray_q[2] ^ (gray_q[2] >> 1);
        gray_q[3] <= gray_q[3] ^ (bcd_q[2][3] & (ena[1] | ena[2]));
        bcd_q[3] <= gray_q[3] ^ (gray_q[3] >> 1);
    end
end

assign q = {bcd_q[3], bcd_q[2], bcd_q[1], bcd_q[0]};

endmodule

module functional_module (
