    output [15:0] q // 4-digit BCD output from the functional module
);

reg [3:0] ones_digit; // Ones digit of BCD counter
reg [7:0] d1_out; // Output of first given module
reg [7:0] d2_out; // Output of second given module

assign ones_digit = bcd_q[3:0];
assign d1_out = d1;
assign d2_out = d2;

always @ (*) begin
    q = {bcd_q[15:4], ones_digit + d1_out - d2_out};
end

endmodule

