module SPIfrontend(nCS, CLK, MOSI, MISO, inbyte, outbyte, out_valid, mode, busy);
   input nCS;
   input CLK;
   input MOSI;
   input [1:0] mode;
   output MISO;
   output busy;

   reg MISO;
   reg [7:0] inbyte;
   reg [7:0] outbyte;
   reg [2:0] bitcnt;
   reg busy;

   assign out_valid = bitcnt == 0;

   always @(posedge nCS) begin // 'reset' condition
      bitcnt <= 0;
      outbyte <= 0;
      busy <= 0;
   end

   always @(posedge CLK) if (!nCS) begin
      case (mode)
         2'b00: begin // Normal SPI mode
            MISO <= inbyte[bitcnt];
            outbyte <= 0;
            out_valid <= 0;
            busy <= 1;
         end
         2'b01: begin // Read mode
            MISO <= inbyte;
            outbyte <= 0;
            out_valid <= 0;
            bitcnt <= 0;
            busy <= 1;
         end
         2'b10: begin // Write mode
            MISO <= 0;
            if (bitcnt < 8) begin
               outbyte[bitcnt] <= MOSI;
               bitcnt <= bitcnt + 1;
               out_valid <= 0;
               busy <= 1;
            end else begin
               out_valid <= 1;
               busy <= 0;
            end
         end
         default: begin // Reserved
            MISO <= 0;
            outbyte <= 0;
            out_valid <= 0;
            busy <= 0;
         end
      endcase
   end // always @ (posedge CLK)

endmodule

