module FSM (
  input clk,
  input rst,
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 4; // number of input signals
parameter m = 2; // number of output signals
parameter p = 4; // number of states in the FSM

// Define the states
parameter S0 = 2'b00;
parameter S1 = 2'b01;
parameter S2 = 2'b10;
parameter S3 = 2'b11;

// Define the inputs
parameter I0 = 4'b0000;
parameter I1 = 4'b0001;
parameter I2 = 4'b0010;
parameter I3 = 4'b0011;
parameter I4 = 4'b0100;
parameter I5 = 4'b0101;
parameter I6 = 4'b0110;
parameter I7 = 4'b0111;
parameter I8 = 4'b1000;
parameter I9 = 4'b1001;
parameter I10 = 4'b1010;
parameter I11 = 4'b1011;
parameter I12 = 4'b1100;
parameter I13 = 4'b1101;
parameter I14 = 4'b1110;
parameter I15 = 4'b1111;

// Define the outputs
parameter O0 = 2'b00;
parameter O1 = 2'b01;
parameter O2 = 2'b10;
parameter O3 = 2'b11;

// Define the state register and next state logic
reg [1:0] state, next_state;
always @(posedge clk, posedge rst) begin
  if (rst) begin
    state <= S0;
  end else begin
    state <= next_state;
  end
end

// Define the output logic
always @(state, in) begin
  case (state)
    S0: out = O0;
    S1: out = O1;
    S2: out = O2;
    S3: out = O3;
  endcase
end

// Define the next state logic
always @(state, in) begin
  case (state)
    S0: begin
      if (in == I0 || in == I1 || in == I2 || in == I3) begin
        next_state = S1;
      end else if (in == I4 || in == I5 || in == I6 || in == I7) begin
        next_state = S2;
      end else if (in == I8 || in == I9 || in == I10 || in == I11) begin
        next_state = S3;
      end else if (in == I12 || in == I13 || in == I14 || in == I15) begin
        next_state = S0;
      end
    end
    S1: begin
      if (in == I0 || in == I1 || in == I2 || in == I3) begin
        next_state = S1;
      end else if (in == I4 || in == I5 || in == I6 || in == I7) begin
        next_state = S2;
      end else if (in == I8 || in == I9 || in == I10 || in == I11) begin
        next_state = S3;
      end else if (in == I12 || in == I13 || in == I14 || in == I15) begin
        next_state = S0;
      end
    end
    S2: begin
      if (in == I0 || in == I1 || in == I2 || in == I3) begin
        next_state = S1;
      end else if (in == I4 || in == I5 || in == I6 || in == I7) begin
        next_state = S2;
      end else if (in == I8 || in == I9 || in == I10 || in == I11) begin
        next_state = S3;
      end else if (in == I12 || in == I13 || in == I14 || in == I15) begin
        next_state = S0;
      end
    end
    S3: begin
      if (in == I0 || in == I1 || in == I2 || in == I3) begin
        next_state = S1;
      end else if (in == I4 || in == I5 || in == I6 || in == I7) begin
        next_state = S2;
      end else if (in == I8 || in == I9 || in == I10 || in == I11) begin
        next_state = S3;
      end else if (in == I12 || in == I13 || in == I14 || in == I15) begin
        next_state = S0;
      end
    end
  endcase
end

endmodule

module sequencer_cpu (
  input clk,
  input dbrk_break,
  input debugreq,
  input hbreak_enabled,
  input [37:0] jdo,
  input jrst_n,
  input ocireg_ers,
  input ocireg_mrs,
  input reset,
  input st_ready_test_idle,
  input take_action_ocimem_a,
  input take_action_ocireg,
  input xbrk_break,
  output debugack,
  output monitor_error,
  output monitor_go,
  output monitor_ready,
  output oci_hbreak_req,
  output resetlatch,
  output resetrequest
);

  wire debugack;
  wire oci_hbreak_req;
  reg monitor_error;
  reg monitor_go;
  reg monitor_ready;
  reg resetlatch;
  reg resetrequest;
  reg jtag_break;
  reg probepresent;

  always @(posedge clk or negedge jrst_n) begin
    if (jrst_n == 0) begin
      probepresent <= 1'b0;
      resetrequest <= 1'b0;
      jtag_break <= 1'b0;
    end
    else if (take_action_ocimem_a) begin
      resetrequest <= jdo[22];
      jtag_break <= jdo[21] ? 1 : jdo[20] ? 0 : jtag_break;
      probepresent <= jdo[19] ? 1 : jdo[18] ? 0 : probepresent;
      resetlatch <= jdo[24] ? 0 : resetlatch;
    end
    else if (reset) begin
      jtag_break <= probepresent;
      resetlatch <= 1;
    end
    else if (~debugack & debugreq & probepresent) begin
        jtag_break <= 1'b1;
    end
  end

  always @(posedge clk or negedge jrst_n) begin
    if (jrst_n == 0) begin
      monitor_ready <= 1'b0;
      monitor_error <= 1'b0;
      monitor_go <= 1'b0;
    end
    else begin
      if (take_action_ocimem_a && jdo[25]) begin
        monitor_ready <= 1'b0;
      end
      else if (take_action_ocireg && ocireg_mrs) begin
        monitor_ready <= 1'b1;
      end
      if (take_action_ocimem_a && jdo[25]) begin
        monitor_error <= 1'b0;
      end
      else if (take_action_ocireg && ocireg_ers) begin
        monitor_error <= 1'b1;
      end
      if (take_action_ocimem_a && jdo[23]) begin
        monitor_go <= 1'b1;
      end
      else if (st_ready_test_idle) begin
        monitor_go <= 1'b0;
      end
    end
  end

  assign debugack = ~hbreak_enabled;
  assign oci_hbreak_req = jtag_break | dbrk_break | xbrk_break | debugreq;

endmodule

