);

  always @ (binary_in)
    case(binary_in)
      3'b000: binary_out = 8'b00000001;
      3'b001: binary_out = 8'b00000010;
      3'b010: binary_out = 8'b00000100;
      3'b011: binary_out = 8'b00001000;
      3'b100: binary_out = 8'b00010000;
      3'b101: binary_out = 8'b00100000;
      3'b110: binary_out = 8'b01000000;
      3'b111: binary_out = 8'b10000000;
    endcase

endmodule

module top_module (
    input [2:0] in,
    input enable,
    input [15:0] a,
    input [15:0] b,
    input add_sub,
    output [7:0] decoder_out,
    output reg [15:0] adder_out,
    output [15:0] final_out,
    output isNaN,
    output isInf
);

    // 3-to-8 decoder with enable input
    decoder dec(
        .in(in),
        .enable(enable),
        .out(decoder_out)
    );

    // 16-bit floating point adder
    floating_point_adder fpa(
        .a(a),
        .b(b),
        .add_sub(add_sub),
        .out(adder_out),
        .isNaN(isNaN),
        .isInf(isInf)
    );

    // Functional module to get final output
    always @(*) begin
        final_out = adder_out + decoder_out;
    end

endmodule

module decoder (
    input [2:0] in,
    input enable,
    output reg [7:0] out
);

    always @(in, enable) begin
        if (enable) begin
            case (in)
                3'b000: out = 8'b00000001;
                3'b001: out = 8'b00000010;
                3'b010: out = 8'b00000100;
                3'b011: out = 8'b00001000;
                3'b100: out = 8'b00010000;
                3'b101: out = 8'b00100000;
                3'b110: out = 8'b01000000;
                3'b111: out = 8'b10000000;
                default: out = 8'b00000000;
            endcase
        end else begin
            out = 8'b00000000;
        end
    end

endmodule

module floating_point_adder (
    input [15:0] a,
    input [15:0] b,
    input add_sub,
    output reg [15:0] out,
    output isNaN,
    output isInf
);

    reg [30:0] a_mantissa;
    reg [30:0] b_mantissa;
    reg [7:0] a_exponent;
    reg [7:0] b_exponent;
    reg a_sign;
    reg b_sign;
    reg [7:0] exponent_diff;
    reg [30:0] mantissa_sum;
    reg carry;
    reg [30:0] shifted_mantissa;
    reg [7:0] shifted_exponent;
    reg [7:0] out_exponent;
    reg [30:0] out_mantissa;

    // Extracting sign, exponent, and mantissa of a
    assign a_sign = a[15];
    assign a_exponent = a[14:7];
    assign a_mantissa = {1'b1, a[6:0], 23'b0};

    // Extracting sign, exponent, and mantissa of b
    assign b_sign = b[15];
    assign b_exponent = b[14:7];
    assign b_mantissa = {1'b1, b[6:0], 23'b0};

    // Calculating exponent difference
    always @(a_exponent, b_exponent) begin
        exponent_diff = a_exponent - b_exponent;
    end

    // Shifting mantissa of b based on exponent difference
    always @(b_mantissa, exponent_diff) begin
        if (exponent_diff > 0) begin
            shifted_mantissa = {b_mantissa[29-exponent_diff:0], {exponent_diff{1'b0}}};
            shifted_exponent = b_exponent + exponent_diff;
        end else if (exponent_diff < 0) begin
            shifted_mantissa = {1'b0, b_mantissa};
            shifted_exponent = a_exponent + exponent_diff;
        end else begin
            shifted_mantissa = b_mantissa;
            shifted_exponent = b_exponent;
        end
    end

    // Adding/subtracting mantissas
    always @(a_mantissa, shifted_mantissa, add_sub) begin
        if (add_sub) begin
            mantissa_sum = a_mantissa - shifted_mantissa;
        end else begin
            mantissa_sum = a_mantissa + shifted_mantissa;
        end
    end

    // Handling carry
    always @(mantissa_sum) begin
        if (mantissa_sum[31]) begin
            carry = 1'b1;
            out_mantissa = {mantissa_sum[30:0], 1'b0};
        end else begin
            carry = 1'b0;
            out_mantissa = mantissa_sum[30:0];
        end
    end

    // Handling overflow
    always @(a_sign, b_sign, out_mantissa, carry) begin
        if (a_sign == b_sign && a_sign != out_mantissa[30]) begin
            isInf = 1'b1;
            isNaN = 1'b0;
            if (a_sign) begin
                out = 16'b1111111111111111;
            end else begin
                out = 16'b0111111111111111;
            end
        end else if (out_mantissa[31]) begin
            isInf = 1'b0;
            isNaN = 1'b1;
            out = 16'b0111111111111111;
        end else begin
            isInf = 1'b0;
            isNaN = 1'b0;
            out_exponent = shifted_exponent;
            out_mantissa = {out_mantissa[29:0], carry};
            out = {a_sign, out_exponent, out_mantissa[22:0]};
        end
    end

endmodule

module display (
    input [159:0] floor,
    input clk,
    input resetn,
    output reg [7:0] x,
    output reg [6:0] y,
    output reg [2:0] colour
    );

    // initialization
    reg [7:0] x_init=8'd2;
    reg [6:0] y_init = 7'd80;
    reg [2:0] count = 3'b000;
    reg [10:0] counter = 11'b0;

    // counts from 0 to 9 for the first two pixel for the runner
    reg [4:0] runner_count = 5'b0;
    reg [2:0] runner_height = 3'b0;

    // copy of floor value, will do left shift on local value
    reg [159:0] local_draw;

    always@(posedge clk) begin
        if (!resetn) begin
            x_init <= 8'd2;
            y_init <= 7'd80;
            count <= 3'b000;
            counter <= 11'b0;
            local_draw <= floor<<2;
        end
        else begin
            if (counter < 11'd652) begin
                // first 20 counts used to display runner
                if (counter < 11'd20) begin
                    // first or second pixel
                    if (counter < 11'd10) 
                        x <= 8'd0;
                    else 
                        x <= 8'd1;
                    // stands for current display height
                    runner_count = counter % 10;
                    y = y_init - runner_count;
                    // runner's height
                    runner_height = floor[159:158] * 2;
                    if (runner_count == 5'd0) 
                        // base line
                        colour = 3'b110;
                    else if (runner_count < runner_height || runner_count > runner_height + 3)
                        // dark part
                        colour = 3'b000;
                    else 
                        // runner part
                        colour = 3'b101;
                end
                else 
                // next 632 counts (158 pixels) to display obstacles 
                begin
                    count = (counter-20) % 8;
                    // x_init starts from 2
                    x <= x_init + count[2];
                    // the base line case
                    if (count[1:0] == 2'b00) begin
                        colour <= 3'b110;
                        y <= y_init;
                    end 
                    else begin 
                        if (count[1:0] > local_draw[159:158])
                            colour = 3'b000;
                        else 
                            colour = 3'b011;
                        y <= y_init - count[1:0];
                    end
                    if (count == 3'b111) begin
                        x_init <= x_init + 2;
                        local_draw <= local_draw << 2;
                    end
                end
                counter = counter + 1;
            end
            else begin 
                x_init <= 8'd2;
                y_init <= 7'd80;
                count <= 3'b000;
                counter <= 11'b0;
                local_draw <= floor << 2;
            end
        end
    end
endmodule

module Multiplier
   #(parameter SW = 24,
     parameter Opt_FPGA_ASIC=0)  //Se está optimizando el modulo para FPGA o para un ASIC
  (
    input wire clk,
    input wire rst,
    input wire load_b_i,
    input wire [SW-1:0] Data_A_i,
    input wire [SW-1:0] Data_B_i,
    output wire [2*SW-1:0] sgf_result_o
  );

  // Declare a wire for the product of the two inputs
  wire [2*SW-1:0] Result;

  // Instantiate a multiplier module
  generate
    if (Opt_FPGA_ASIC) begin
      // For an ASIC, use the KOA_FPGA module
      KOA_FPGA #(.SW(SW)) main_KOA(
        .Data_A_i(Data_A_i),
        .Data_B_i(Data_B_i),
        .sgf_result_o(Result)
      );
    end else begin
      // For an FPGA, use the KOA_c module
      KOA_c #(.SW(SW), .precision(1)) main_KOA(
        .Data_A_i(Data_A_i),
        .Data_B_i(Data_B_i),
        .sgf_result_o(Result)
      );
    end
  endgenerate

  // Instantiate a register module to store the output value
  RegisterAdd #(.W(2*SW)) finalreg (
    .clk(clk),
    .rst(rst),
    .load(load_b_i),
    .D(Result),
    .Q(sgf_result_o)
  );

endmodule

