    d_ff <= d;
    if (d_ff) begin
        shift_reg <= {shift_reg[1:0], 1'b1};
    end else begin
        shift_reg <= {shift_reg[1:0], 1'b0};
    end
end

assign q = shift_reg[2];

endmodule

module calculator(a, b, op, clk, result);

  input [7:0] a, b;
  input [1:0] op;
  input clk;
  output [7:0] result;

  reg [7:0] temp_result;

  always @(posedge clk) begin
    case(op)
      2'b00: temp_result <= a + b; // addition
      2'b01: temp_result <= a - b; // subtraction
      2'b10: temp_result <= a * b; // multiplication
      2'b11: temp_result <= a / b; // division
    endcase
  end

  assign result = temp_result;

endmodule

