module priority_encoder (
  input clk,
  input reset,
  input [3:0] in1,
  input [3:0] in2,
  output reg [3:0] out,
  output reg [2:0] select
);

  reg [1:0] priority;
  reg [3:0] highest;
  reg [3:0] temp_out;
  reg [2:0] temp_select;
  reg [2:0] select_reg;

  always @(posedge clk) begin
    if (reset) begin
      priority <= 2'b00;
      highest <= 4'b0000;
      temp_out <= 4'b0000;
      temp_select <= 3'b000;
      select_reg <= 3'b000;
    end else begin
      if (in1 > in2) begin
        priority <= 2'b01;
        highest <= in1;
        temp_select <= 3'b001;
      end else begin
        priority <= 2'b10;
        highest <= in2;
        temp_select <= 3'b010;
      end
      temp_out <= highest;
      select_reg <= temp_select;
    end
  end

  always @(posedge clk) begin
    if (reset) begin
      out <= 4'b0000;
      select <= 3'b000;
    end else begin
      out <= temp_out;
      select <= select_reg;
    end
  end

endmodule

module adder_subtractor (
  input [3:0] A,
  input [3:0] B,
  input sub,
  input clk,
  input rst,
  output [3:0] out,
  output cout
);

  reg [3:0] A_inv;
  reg [3:0] B_inv;
  reg [3:0] sum;
  reg carry;

  // Invert B if subtracting
  assign B_inv = sub ? ~B + 1 : B;

  // Invert A if subtracting
  assign A_inv = sub ? ~A : A;

  // Full adder
  always @(posedge clk) begin
    if (rst) begin
      sum <= 0;
      carry <= 0;
    end else begin
      {carry, sum} <= A_inv + B_inv + carry;
    end
  end

  // Output
  assign out = sum;
  assign cout = carry;

endmodule

