module clock_div(CLKIN_IN, 
                 CLKDV_OUT, 
                 CLKIN_IBUFG_OUT, 
                 CLK0_OUT);

    input CLKIN_IN;
    output CLKDV_OUT;
    output CLKIN_IBUFG_OUT;
    output CLK0_OUT;

    // IBUFG buffer for input clock signal
    wire CLKIN_IBUFG;
    IBUFG CLKIN_IBUFG_INST (.I(CLKIN_IN), .O(CLKIN_IBUFG));
    assign CLKIN_IBUFG_OUT = CLKIN_IBUFG;

    // DCM_SP module for clock division and buffering
    wire CLKFB_IN;
    wire CLKDV_BUF;
    wire CLK0_BUF;
    wire GND_BIT = 0;
    DCM_SP #(
        .CLK_FEEDBACK("1X"),
        .CLKDV_DIVIDE(2.0),
        .CLKFX_DIVIDE(1),
        .CLKFX_MULTIPLY(4),
        .CLKIN_DIVIDE_BY_2("FALSE"),
        .CLKIN_PERIOD(20.000),
        .CLKOUT_PHASE_SHIFT("NONE"),
        .DESKEW_ADJUST("SYSTEM_SYNCHRONOUS"),
        .DFS_FREQUENCY_MODE("LOW"),
        .DLL_FREQUENCY_MODE("LOW"),
        .DUTY_CYCLE_CORRECTION("TRUE"),
        .FACTORY_JF(16'hC080),
        .PHASE_SHIFT(0),
        .STARTUP_WAIT("FALSE")
    ) DCM_SP_INST (
        .CLKFB(CLKFB_IN),
        .CLKIN(CLKIN_IBUFG),
        .DSSEN(GND_BIT),
        .PSCLK(GND_BIT),
        .PSEN(GND_BIT),
        .PSINCDEC(GND_BIT),
        .RST(GND_BIT),
        .CLKDV(CLKDV_BUF),
        .CLKFX(),
        .CLKFX180(),
        .CLK0(CLK0_BUF),
        .CLK2X(),
        .CLK2X180(),
        .CLK90(),
        .CLK180(),
        .CLK270(),
        .LOCKED(),
        .PSDONE(),
        .STATUS()
    );

    // Divide the output clock signal by 2 to get CLKDV_OUT
    assign CLKDV_OUT = CLKDV_BUF;

    // Multiply the input clock signal by 4 to get CLK0_OUT
    assign CLK0_OUT = CLK0_BUF;

endmodule

