    if (areset) begin
        sum_reg <= 4'b0;
        carry_reg <= 1'b0;
    end else begin
        sum_reg <= A + B + carry_reg;
        carry_reg <= (A[3] & B[3]) | (A[3] & carry_reg) | (B[3] & carry_reg);
