module fsm_pattern_detection (
  input clk,
  input reset,
  input [3:0] data,
  output reg match
);

  parameter S0 = 2'b00;
  parameter S1 = 2'b01;
  parameter S2 = 2'b10;
  parameter S3 = 2'b11;

  reg [1:0] state;
  reg [1:0] next_state;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      state <= S0;
      match <= 0;
    end
    else begin
      state <= next_state;
      match <= (state == S3);
    end
  end

  always @* begin
    case (state)
      S0: begin
        if (data == 4'b1_0_1_0)
          next_state = S1;
        else
          next_state = S0;
      end

      S1: begin
        if (data[2:0] == 3'b010)
          next_state = S2;
        else if (data == 4'b1_0_1_0)
          next_state = S1;
        else
          next_state = S0;
      end

      S2: begin
        if (data[1:0] == 2'b10)
          next_state = S3;
        else if (data[2:0] == 3'b010)
          next_state = S2;
        else
          next_state = S0;
      end

      S3: begin
        next_state = S0;
      end
    endcase
  end

endmodule

module ALU(
    input wire [31:0] a,
    input wire [31:0] b,
    input wire [3:0] s,
    output reg [31:0] Z,
    output reg le,
    output reg eq,
    output reg gt,
    output reg ovf
);

    //Operations
    localparam SUMA = 4'd0;
    localparam RESTA = 4'd1;
    localparam MULT = 4'd2;
    localparam DIV = 4'd3;
    localparam LT = 4'd4;
    localparam EQ = 4'd5;
    localparam GT = 4'd6;
    localparam AND = 4'd7;
    localparam OR = 4'd8;
    localparam NOT = 4'd9;

    wire [31:0] rsuma;
    wire ovfsuma;
    wire [31:0] rresta;
    wire ovfresta;
    wire [31:0] rmult;
    wire ovfmult;
    wire [31:0] rdiv;
    wire ovfdiv;
    wire lesser;
    wire greater;
    wire equal;

    //Modules
    Comparador comp(
        .a(a),
        .b(b),
        .lt(lesser),
        .gt(greater),
        .eq(equal)
    );

    Sumador suma(
        .a(a),
        .b(b),
        .Z(rsuma),
        .ovf(ovfsuma)
    );

    Sumador resta(
        .a(a),
        .b({~b[31],b[30:0]}),
        .Z(rresta),
        .ovf(ovfresta)
    );

    Multiplicador mult(
        .a(a),
        .b(b),
        .Z(rmult),
        .ovf(ovfmult)
    );

    Divisor divs(
        .a(a),
        .b(b),
        .Z(rdiv),
        .ovf(ovfdiv)
    );

    always @* begin
        le = lesser;
        gt = greater;
        eq = equal;
        case(s)
            SUMA: begin
                Z = rsuma;
                ovf = ovfsuma;
            end
            RESTA: begin
                Z = rresta;
                ovf = ovfresta;
            end
            MULT: begin
                Z = rmult;
                ovf = ovfmult;
            end
            DIV: begin
                Z = rdiv;
                ovf = ovfdiv;
            end
            LT, EQ, GT: begin
                Z = 32'b0;
                ovf = 1'b0;
            end
            AND: begin
                Z = a & b;
                ovf = 1'b0;
            end
            OR: begin
                Z = a | b;
                ovf = 1'b0;
            end
            NOT: begin
                Z = ~a;
                ovf = 1'b0;
            end
        endcase
    end

endmodule

