module CAN_transmitter (
  input [7:0] data,
  input [10:0] id,
  input tx_en,
  output reg tx
);

reg [111:0] message; // 112-bit CAN message
reg [4:0] crc; // 5-bit CRC value

reg [7:0] stuffing_count; // Counter for bit stuffing
reg [1:0] error_count; // Counter for error state

reg [111:0] tx_buffer; // Buffer for transmitting the message
reg [4:0] tx_count; // Counter for transmitting the message

// Bit stuffing logic
always @ (posedge tx_en) begin
  if (stuffing_count == 5'b11111) begin
    tx_buffer[tx_count] = 1;
    tx_count = tx_count + 1;
    stuffing_count = 1;
  end else if (data[stuffing_count-1] == 1'b1) begin
    tx_buffer[tx_count] = 1;
    tx_count = tx_count + 1;
    stuffing_count = stuffing_count + 1;
  end else begin
    tx_buffer[tx_count] = 0;
    tx_count = tx_count + 1;
    stuffing_count = 1;
  end
end

// CRC calculation
always @ (posedge tx_en) begin
  crc = 5'b00000; // Initialize CRC value
  for (i = 0; i < 112; i = i + 1) begin
    crc = crc ^ message[i];
    for (j = 0; j < 5; j = j + 1) begin
      if (crc[4] == 1'b1) begin
        crc = (crc << 1) ^ 5'b00111;
      end else begin
        crc = crc << 1;
      end
    end
  end
end

// Message encoding
always @ (posedge tx_en) begin
  message[0:7] = data;
  message[8:18] = id;
  message[19:23] = crc;
end

// Transmission logic
always @ (posedge tx_en) begin
  if (tx_count == 112) begin
    tx = 1; // Start of frame
    tx_buffer = 0;
    tx_count = 0;
  end else if (tx_count == 113) begin
    tx = 0; // End of frame
  end else begin
    tx = tx_buffer[tx_count];
  end
end

endmodule
module CAN_receiver (
  input rx,
  input [10:0] id,
  input rx_en,
  output reg [7:0] data
);

reg [111:0] message; // 112-bit CAN message
reg [4:0] crc; // 5-bit CRC value

reg [7:0] stuffing_count; // Counter for bit stuffing
reg [1:0] error_count; // Counter for error state

reg [111:0] rx_buffer; // Buffer for receiving the message
reg [4:0] rx_count; // Counter for receiving the message

// Bit stuffing logic
always @ (posedge rx_en) begin
  if (stuffing_count == 5'b11111) begin
    rx_buffer[rx_count] = rx;
    rx_count = rx_count + 1;
    stuffing_count = 1;
  end else if (rx == 1'b1) begin
    rx_buffer[rx_count] = rx;
    rx_count = rx_count + 1;
    stuffing_count = stuffing_count + 1;
  end else begin
    rx_buffer[rx_count] = rx;
    rx_count = rx_count + 1;
    stuffing_count = 1;
  end
end

// CRC calculation
always @ (posedge rx_en) begin
  crc = 5'b00000; // Initialize CRC value
  for (i = 0; i < 112; i = i + 1) begin
    crc = crc ^ message[i];
    for (j = 0; j < 5; j = j + 1) begin
      if (crc[4] == 1'b1) begin
        crc = (crc << 1) ^ 5'b00111;
      end else begin
        crc = crc << 1;
      end
    end
  end
end

// Message decoding
always @ (posedge rx_en) begin
  if (rx_count == 113) begin
    if (crc == rx_buffer[19:23]) begin
      data = rx_buffer[0:7];
    end
    rx_buffer = 0;
    rx_count = 0;
  end else if (rx_count > 113) begin
    rx_buffer = 0;
    rx_count = 0;
  end else begin
    message[rx_count-1] = rx_buffer[rx_count-1];
  end
end

endmodule

