module lzw (
  input clk,
  input rst,
  input [7:0] data_in,
  output reg [7:0] data_out,
  output reg [11:0] code_out,
  output reg done
);

  // Define dictionary as a 2D array of 12-bit codes and 8-bit substrings
  reg [11:0] dict [4095:0];
  reg [7:0] substr [4095:0];
  reg [11:0] next_code = 256; // Initialize next code to 256

  // Define variables for compression and decompression logic
  reg [7:0] prev = 0;
  reg [7:0] curr = 0;
  reg [11:0] code = 0;
  reg [11:0] new_code = 0;
  reg [11:0] dict_index = 0;
  reg [3:0] dict_size = 8; // Initialize dictionary size to 8

  // Define state machine for compression and decompression
  reg [1:0] state = 0;
  parameter IDLE = 0;
  parameter COMPRESS = 1;
  parameter DECOMPRESS = 2;

  always @(posedge clk) begin
    if (rst) begin
      state <= IDLE;
      data_out <= 0;
      code_out <= 0;
      done <= 0;
      next_code <= 256;
      dict_size <= 8;
    end
    else begin
      case (state)
        IDLE: begin
          if (data_in != 0) begin
            state <= COMPRESS;
          end
          else begin
            state <= DECOMPRESS;
          end
        end
        COMPRESS: begin
          if (prev == 0) begin
            // Initialize previous byte
            prev <= data_in;
          end
          else begin
            curr <= data_in;
            code <= (prev << 8) | curr;
            dict_index <= 0;
            new_code <= 0;
            // Search for code in dictionary
            while ((dict_index < next_code) && (new_code == 0)) begin
              if (dict[dict_index] == code) begin
                new_code <= dict_index;
              end
              dict_index <= dict_index + 1;
            end
            if (new_code == 0) begin
              // Add new code to dictionary
              dict[next_code] <= code;
              substr[next_code] <= curr;
              next_code <= next_code + 1;
              // Output code for previous substring
              code_out <= prev;
              prev <= curr;
              dict_size <= dict_size + 1;
            end
            else begin
              // Update previous substring
              prev <= new_code;
            end
            if (dict_size == 4095) begin
              // Dictionary is full, reset dictionary
              next_code <= 256;
              dict_size <= 8;
            end
          end
          state <= IDLE;
        end
        DECOMPRESS: begin
          if (code == 0) begin
            // Initialize code
            code <= data_in;
            data_out <= substr[code];
            prev <= code;
          end
          else begin
            if (data_in < next_code) begin
              // Code is in dictionary
              data_out <= substr[data_in];
              substr[next_code] <= substr[prev] + substr[data_in][0];
              dict[next_code] <= (prev << 8) | substr[next_code];
              next_code <= next_code + 1;
              prev <= data_in;
              if (next_code == 4095) begin
                // Dictionary is full, reset dictionary
                next_code <= 256;
                dict_size <= 8;
              end
            end
            else begin
              // Code is not in dictionary
              substr[next_code] <= substr[prev] + substr[prev][0];
              data_out <= substr[next_code];
              dict[next_code] <= (prev << 8) | substr[next_code];
              next_code <= next_code + 1;
              prev <= next_code - 1;
              if (next_code == 4095) begin
                // Dictionary is full, reset dictionary
                next_code <= 256;
                dict_size <= 8;
              end
            end
            code_out <= prev;
            code <= data_in;
          end
          state <= IDLE;
        end
      endcase
      if (data_in == 0) begin
        done <= 1;
      end
    end
  end

endmodule

