        min_exp_count <= clk_chk_n_exp - (1<<shift_amount);
        max_exp_count <= clk_chk_n_exp + (1<<shift_amount);
    end

    always @* begin
        state_nxt = state;
        saw_error = 0;
        go_nxt = 0;
        stop_nxt = 0;

        case (state)

            START: begin
                go_nxt = 1;
                state_nxt = COUNT;
            end

            COUNT: begin
                if (p_count == clk_chk_p_max) begin
                    stop_nxt = 1;
                    state_nxt = WAIT1;
                end
            end

            WAIT1: begin
                if (p_count == (clk_chk_p_max + 2))
                    state_nxt = CHECK;
            end

            CHECK: begin
                if ((n_count < min_exp_count) || (n_count > max_exp_count)) 
                    saw_error = 1;
                state_nxt = START;
            end  

            default: state_nxt = START;

        endcase
    end

    always @(posedge p_clk) begin
        go <= go_nxt;
        stop <= stop_nxt;
        state <= reset ? START : state_nxt;
    end

    always @(posedge p_clk)
        if (reset || go) p_count <= 0;
        else p_count <= p_count + 1;

    always @(posedge n_clk) begin
        go_n <= go;
        reset_n <= reset;
        stop_n <= stop;
    end

    always @(posedge n_clk) begin
        if (reset_n || stop_n) run_n <= 0; 
        else if (go_n) run_n <= 1;
    end

    always @(posedge n_clk) begin
        if (reset_n || go_n) n_count <= 0;
        else if (run_n) n_count <= n_count + 1;
    end

    always @(posedge n_clk) begin
        if (reset_n) 
            n_clk_count <= 'h0; 
        else if (stop_n) 
            n_clk_count <= n_count;
    end

    always @(posedge p_clk) begin
        if (reset)
            error_cnt <= 0;
        else if (saw_error) 
            error_cnt <= 10000;
        else if (error_cnt > 0)
            error_cnt <= error_cnt - 1;
    end

    assign error = (error_cnt != 0);

