module ModuloOperator (
  input signed [31:0] a, // dividend
  input signed [31:0] b, // divisor
  output signed [31:0] q, // quotient
  output signed [31:0] r // remainder
);

  always @(*) begin
    if (b == 0) begin
      $warning("Divisor is zero. Output values are undefined.");
      q = 0;
      r = 0;
    end else if (a < 0) begin
      $warning("Dividend is negative. Remainder will be negative.");
      q = a / b;
      r = a % b;
      if (r < 0) begin
        r = r + abs(b);
        q = q - 1;
      end
    end else if (b < 0) begin
      $warning("Divisor is negative. Remainder will be negative.");
      q = a / b;
      r = a % b;
      if (r < 0) begin
        r = r - abs(b);
        q = q + 1;
      end
    end else begin
      q = a / b;
      r = a % b;
    end
  end

endmodule

