    case (current_state)
      IDLE: begin
        if (button_a && !button_b && !button_c) begin
          next_state = DRINK_X;
        end else if (!button_a && button_b && !button_c) begin
          next_state = DRINK_Y;
        end else if (!button_a && !button_b && button_c) begin
          next_state = DRINK_Z;
