module i64ToRecF16 (
    input [(`floatControlWidth - 1):0] control,
    input [63:0] in,
    input [2:0] roundingMode,
    output [16:0] out,
    output [4:0] exceptionFlags
);

    // Determine the sign bit of the output floating-point number based on the sign of the input integer.
    wire signBit = in[63];

    // Convert the absolute value of the input integer to binary.
    wire [63:0] absIn = (in < 0) ? (~in + 1) : in;
    wire [10:0] mantissa = absIn[52:42];
    wire [30:0] exp = {11'd0, absIn[62:52]} - 15'd127;

    // Determine the exponent of the output floating-point number based on the position of the most significant bit in the binary representation of the input integer.
    wire [30:0] shiftedExp = (mantissa[9]) ? exp + 1 : exp;

    // Normalize the binary representation of the input integer by shifting the binary point to the left or right as needed.
    wire [10:0] shiftedMantissa = (mantissa[9]) ? {1'b1, mantissa[8:0]} : {1'b0, mantissa[9:0]};
    wire [10:0] roundedMantissa;
    wire [4:0] roundingExceptionFlags;
    iNToRecFN#(11, 5, 16) iNToRecFN(control, 1, shiftedMantissa, roundingMode, roundedMantissa, roundingExceptionFlags);

    // Convert the rounded binary representation to the final floating-point number format.
    wire [15:0] roundedOut = {signBit, shiftedExp[8:0], roundedMantissa[9:0]};

    // Set the exception flags if any exceptions occurred during the conversion process.
    assign exceptionFlags = {1'b0, 1'b0, 1'b0, 1'b0, roundingExceptionFlags};

    // Output the result.
    assign out = roundedOut;

endmodule

module top_module (
    input wire [15:0] in,
    input wire [7:0] a,
    input wire [7:0] b,
    output wire [7:0] out
);

    wire [15:0] mult_out;
    wire [7:0] out_hi, out_lo;
    wire [7:0] add_out;
    wire overflow;

    multiplication mult_inst(
        .a(a),
        .b(b),
        .s(mult_out)
    );

    byte_splitter byte_inst(
        .in(mult_out),
        .out_hi(out_hi),
        .out_lo(out_lo)
    );

    add_overflow_detection add_inst(
        .a(out_hi),
        .b(out_lo),
        .s(add_out),
        .overflow(overflow)
    );

    assign out = add_out;

endmodule

module byte_splitter (
    input wire [15:0] in,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo
);
    assign out_hi = in[15:8];
    assign out_lo = in[7:0];
endmodule

module add_overflow_detection (
    input [7:0] a,
    input [7:0] b,
    output [7:0] s,
    output overflow
);
    reg signed [8:0] sum;

    always @(*) begin
        sum = $signed(a) + $signed(b);
        if (sum > 127 || sum < -128) begin
            overflow = 1;
        end else begin
            overflow = 0;
        end
    end

    assign s = sum[7:0];

endmodule

module multiplication (
    input [7:0] a,
    input [7:0] b,
    output [15:0] s
);
    reg signed [15:0] product;

    always @(*) begin
        product = $signed(a) * $signed(b);
        s = product[15:0];
    end

endmodule

module PWM (
  input ctrl, // control signal
  input clk, // clock signal
  output reg pwm // pulse signal with variable duty cycle
);

parameter n = 8; // number of bits used to represent the duty cycle

// other internal signals and variables
reg [n-1:0] duty_cycle;

// define the duty cycle as a function of the control signal
always @ (ctrl)
begin
  duty_cycle = ctrl * (2**n-1);
end

// use the duty cycle to adjust the pulse signal generated by the clock signal
always @ (posedge clk)
begin
  if (duty_cycle > 0)
    pwm <= 1;
  else
    pwm <= 0;
  duty_cycle <= duty_cycle - 1;
end

endmodule

module decoder_2to4 (
    input A,
    input B,
    output reg Y0,
    output reg Y1,
    output reg Y2,
    output reg Y3
);

always @ (A or B) begin
    Y0 = ~(A & B);
    Y1 = ~A & B;
    Y2 = A & ~B;
    Y3 = A & B;
end

endmodule

module top(
    input wire clk,
    input wire reset,
    output reg [3:0] count,
    output wire [3:0] leds
);

    reg [3:0] next_count;

    always @ (posedge clk, posedge reset)
    begin
        if (reset)
            count <= 4'b0000;
        else
            count <= next_count;
    end

    always @ (count)
    begin
        next_count = count + 1;
    end

    assign leds = count;

endmodule

module ripple_carry_adder_subtractor (
    input [3:0] A,
    input [3:0] B,
    input sub,
    output [3:0] sum,
    output carry_out
);

    wire [3:0] carry;

    assign carry[0] = sub;

    genvar i;
    generate
        for (i = 1; i < 4; i = i + 1) begin : adder_subtractor
            full_adder fa(
                .a(A[i]),
                .b(B[i]),
                .cin(carry[i-1]),
                .sum(sum[i]),
                .cout(carry[i])
            );

            assign carry[3] = carry[2];
        end
    endgenerate

    full_adder fa0(
        .a(A[0]),
        .b(B[0]),
        .cin(carry[0]),
        .sum(sum[0]),
        .cout(carry[1])
    );

    assign carry_out = carry[3] ^ sub;

endmodule

module full_adder (
    input a,
    input b,
    input cin,
    output sum,
    output cout
);

    assign sum = a ^ b ^ cin;
    assign cout = (a & b) | (a & cin) | (b & cin);

endmodule

module cpu_module # (
        // Size of Code TCM in 32-bit words.
        parameter   OPTION_CTCM_NUM_WORDS = 1024
    )
    (
        input               CLK,
        input               RESET_I,

        input       [31:0]  DEBUG_I,
        output reg  [31:0]  DEBUG_O
    ); 

    wire [31:0] code_addr;
    wire [ 1:0] code_trans;
    reg         code_ready;
    reg  [ 1:0] code_resp;
    reg  [31:0] code_rdata;

    wire [31:0] data_addr;
    wire [ 1:0] data_trans;
    wire [ 2:0] data_size;
    reg         data_ready;
    reg  [ 1:0] data_resp;
    reg  [31:0] data_rdata;
    wire [31:0] data_wdata;
    wire        data_write;
    reg         data_wpending;
    reg  [ 1:0] data_wsize;
    reg  [31:0] data_waddr;
    reg  [31:0] mem_op_pc; 
    reg  [31:0] mem_rdata;
    reg  [ 4:0] hw_irq;

    reg [31:0] ctcm [0:OPTION_CTCM_NUM_WORDS-1];
    reg [10:0] ctcm_addr;
    reg [31:0] ctcm_data;

    always @(posedge CLK) begin
        ctcm_data <= ctcm[ctcm_addr];
    end

    always @(posedge CLK) begin
        if (RESET_I) begin
            code_ready <= 1'b0;
            code_resp <= 2'b00;
            code_rdata <= 32'h0;
            data_ready <= 1'b0;
            data_resp <= 2'b00;
            data_rdata <= 32'h0;
            data_wpending <= 1'b0;
            data_wsize <= 2'b00;
            data_waddr <= 32'h0;
            mem_op_pc <= 32'h0;
            mem_rdata <= 32'h0;
            hw_irq <= 5'h0;
        end else begin
            code_ready <= 1'b1;
            code_resp <= 2'b00;
            data_ready <= 1'b1;
            data_resp <= 2'b00;

            if (code_trans == 2'b10) begin
                code_rdata <= ctcm_data;
                code_resp <= 2'b00;
            end else if (code_trans == 2'b01) begin
                code_resp <= 2'b10;
            end

            if (data_trans == 2'b10) begin
                data_rdata <= mem_rdata;
                data_resp <= 2'b00;
            end else if (data_trans == 2'b01) begin
                data_resp <= 2'b10;
            end else if (data_trans == 2'b11) begin
                if (data_write) begin
                    if (data_wpending) begin
                        data_resp <= 2'b11;
                    end else begin
                        data_waddr <= data_addr;
                        data_wsize <= data_size;
                        data_wdata <= data_wdata;
                        data_wpending <= 1'b1;
                    end
                end else begin
                    mem_op_pc <= data_addr;
                    data_resp <= 2'b00;
                end
            end
        end
    end

    always @(posedge CLK) begin
        if (data_wpending) begin
            ctcm[data_waddr[12:2]] <= data_wdata;
            data_wpending <= 1'b0;
            data_resp <= 2'b00;
        end else begin
            mem_rdata <= ctcm[mem_op_pc[12:2]];
        end
    end

    always @(posedge CLK) begin
        DEBUG_O <= {code_trans, data_trans, data_size, data_write, 24'h0} ^ 
                   data_addr ^ 
                   data_wdata;
    end 

    always @(*) begin
        ctcm_addr = code_addr[12:2];
        code_ready = 1'b1;
        code_resp = 2'b00;
        code_rdata = ctcm_data;

        hw_irq = 5'h0;

        data_resp = 2'b00;
        data_ready = 1'b1;
        data_rdata = DEBUG_I;
    end

endmodule

