module pattern_detection (
  input clk,
  input reset,
  input [7:0] data,
  output reg match
);

  reg [2:0] pattern = 3'b101;
  reg [2:0] shift_reg = 3'b000;

  always @(posedge clk) begin
    if (reset) begin
      shift_reg <= 3'b000;
      match <= 1'b0;
    end else begin
      shift_reg <= {shift_reg[1:0], data[0]};
      if (shift_reg == pattern) begin
        match <= 1'b1;
      end else begin
        match <= 1'b0;
      end
    end
  end

endmodule

