module rotator(
    input [1:0] ena,
    input [15:0] in,
    output reg [63:0] out
);
    always @(*) begin
        case (ena)
            2'b00: out = {48'b0, in};
            2'b01: out = {in[15], in[14:0], 48'b0};
            2'b10: out = {in[0], 48'b0, in[15:1]};
            2'b11: out = {48'b0, in};
        endcase
    end
endmodule

