module fifo_buffer(
    input clk,
    input rst,
    input wr_en,
    input rd_en,
    input [31:0] wr_data,
    output [31:0] rd_data,
    output full,
    output empty
);

    parameter WIDTH = 32;
    parameter DEPTH = 512;
    parameter ADDR_WIDTH = $clog2(DEPTH);
    parameter FULL_THRESHOLD = DEPTH;
    parameter EMPTY_THRESHOLD = 0;

    reg [ADDR_WIDTH-1:0] wr_ptr;
    reg [ADDR_WIDTH-1:0] rd_ptr;
    reg [WIDTH-1:0] mem [0:DEPTH-1];
    reg full;
    reg empty;

    assign full = (wr_ptr == rd_ptr) && (wr_en != rd_en);
    assign empty = (wr_ptr == rd_ptr) && (wr_en == rd_en);

    always @(posedge clk) begin
        if (rst) begin
            wr_ptr <= 0;
            rd_ptr <= 0;
            full <= 0;
            empty <= 1;
        end else begin
            if (wr_en && !full) begin
                mem[wr_ptr] <= wr_data;
                wr_ptr <= wr_ptr + 1;
                if (wr_ptr == FULL_THRESHOLD) begin
                    wr_ptr <= 0;
                end
            end
            if (rd_en && !empty) begin
                rd_data <= mem[rd_ptr];
                rd_ptr <= rd_ptr + 1;
                if (rd_ptr == FULL_THRESHOLD) begin
                    rd_ptr <= 0;
                end
            end
            full <= (wr_ptr == rd_ptr) && (wr_en != rd_en);
            empty <= (wr_ptr == rd_ptr) && (wr_en == rd_en);
        end
    end

endmodule

