wire ref_clk_edge, fb_clk_edge;

always @(posedge ref_clk) ref_clk_d <= ref_clk;
always @(posedge fb_clk) fb_clk_d <= fb_clk;

assign ref_clk_edge = (ref_clk_d == 1'b0) && (ref_clk == 1'b1);
assign fb_clk_edge = (fb_clk_d == 1'b0) && (fb_clk == 1'b1);

