module LF (
  input clk,
  input reset,
  input [7:0] coef,
  output reg lf_out
);

reg [7:0] coef_d;
reg [15:0] acc;

always @(posedge clk) begin
  if (reset) begin
    coef_d <= 8'h00;
    acc <= 16'h0000;
    lf_out <= 1'b0;
  end else begin
    coef_d <= coef;
    acc <= acc + coef_d * (f_vco_max / n_div - f_ref);
    lf_out <= (acc[15] == 1'b1);
  end
end

endmodule

module freq_div (
  input clk_in,
  input reset,
  input [7:0] n_div,
  output reg clk_out
);

reg [7:0] cnt;

always @(posedge clk_in) begin
  if (reset) begin
    cnt <= 8'h00;
    clk_out <= 1'b0;
  end else begin
    cnt <= cnt + 1'b1;
    if (cnt == n_div - 1) begin
      cnt <= 8'h00;
      clk_out <= ~clk_out;
    end
  end
end

endmodule

