parameter f_vco_max = 2000000000; // maximum frequency of the VCO (2 GHz)
parameter k_vco = 1; // gain factor of the VCO
parameter n_div = 10; // division factor of the frequency divider

wire up_down;
wire cp_out;
wire lf_out;
wire clk_div;

PFD pfd (
  .ref_clk(ref_clk),
  .fb_clk(fb_clk),
  .up_down(up_down)
);

CP cp (
  .up_down(up_down),
  .cp_out(cp_out)
);

LF lf (
  .clk(cp_out),
  .reset(1'b0),
  .coef(8'h80),
  .lf_out(lf_out)
);

freq_div div (
  .clk_in(clk_div),
  .reset(1'b0),
  .n_div(n_div),
  .clk_out(clk_out)
);

assign clk_div = lf_out ? f_vco_min / k_vco : f_vco_max / k_vco;

endmodule

module top_module (
    input clk,
    input reset, // Synchronous active-high reset
    input [7:0] data_in, // 8-bit input for the shift register
    input [31:0] A, // 32-bit input A for the adder
    input [31:0] B, // 32-bit input B for the adder
    output [7:0] data_out // 8-bit output from the shift register
);

    // Shift register module
    reg [7:0] shift_reg;
    wire load;
    always @(posedge clk) begin
        if (reset) begin
            shift_reg <= 8'b0;
        end else if (load) begin
            shift_reg <= data_in;
        end else begin
            shift_reg <= {shift_reg[6:0], shift_reg[7]};
        end
    end

    // Adder module
    wire [31:0] sum;
    wire carry_out;
    wire [15:0] A_lsb = A[15:0];
    wire [15:0] A_msb = A[31:16];
    wire [15:0] B_lsb = B[15:0];
    wire [15:0] B_msb = B[31:16];
    carry_select_adder_16bit CSA1(
        .A(A_lsb),
        .B(B_lsb),
        .Cin(1'b0),
        .S(sum[15:0]),
        .Cout(carry_out)
    );
    carry_select_adder_16bit CSA2(
        .A(A_msb),
        .B(B_msb),
        .Cin(1'b0),
        .S(sum[31:16]),
        .Cout(carry_out)
    );
    assign sum[31:16] = carry_out ? 16'b1111111111111111 : 16'b0;

    // Functional module
    wire [7:0] functional_out;
    assign functional_out = shift_reg | sum[7:0];

    // Connect modules
    assign load = functional_out[0];
    assign data_out = shift_reg;

endmodule

module carry_select_adder_16bit (
    input [15:0] A,
    input [15:0] B,
    input Cin,
    output [15:0] S,
    output Cout
);

    wire [15:0] P = A + B;
    wire [15:0] G = A & B;
    wire [15:0] U = P + (Cin ? 1 : 0);
    wire [15:0] V = G + (Cin ? A : 0);
    assign S = U ^ V;
    assign Cout = U[15] & V[15];

endmodule

module dffre_s (din, rst, en, clk, q, se, si, so);
