module ripple_add_sub(
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] sum
);

    wire [15:0] carry;
    wire [15:0] xor_out;
    wire [15:0] add_out;

    // Instantiate 16-bit adder module four times
    adder_16bit adder0(.a(a[15:0]), .b(b[15:0]), .cin(1'b0), .sum(add_out[0]), .cout(carry[0]));
    adder_16bit adder1(.a(a[31:16]), .b(b[31:16]), .cin(carry[0]), .sum(add_out[16]), .cout(carry[1]));
    adder_16bit adder2(.a(a[47:32]), .b(b[47:32]), .cin(carry[1]), .sum(add_out[32]), .cout(carry[2]));
    adder_16bit adder3(.a(a[63:48]), .b(b[63:48]), .cin(carry[2]), .sum(add_out[48]), .cout(carry[3]));

    // XOR gate for subtraction
    assign xor_out = sub ? ~b : b;

    // Ripple carry adder for addition
    assign sum = sub ? a - xor_out : add_out;

endmodule

