module ripple_shift_adder (
    input [15:0] A,
    input [15:0] B,
    input [3:0] shift_amount,
    input direction,
    output [15:0] q
);

    wire [15:0] add_result;
    wire [15:0] shift_result;

    ripple_carry_adder adder(.A(A), .B(B), .Cin(1'b0), .Sum(add_result));

    barrel_shifter shifter(.data_in(add_result), .shift_amount(shift_amount), .direction(direction), .data_out(shift_result));

    assign q = shift_result;

endmodule

module ripple_carry_adder (
    input [15:0] A,
    input [15:0] B,
    input Cin,
    output [15:0] Sum
);

    wire [15:0] carry;
    assign carry[0] = Cin;

    genvar i;
    generate
        for (i = 0; i < 16; i = i + 1) begin : adder_stage
            full_adder adder(.A(A[i]), .B(B[i]), .Cin(carry[i]), .Sum(Sum[i]), .Cout(carry[i+1]));
        end
    endgenerate

endmodule

module full_adder (
    input A,
    input B,
    input Cin,
    output Sum,
    output Cout
);

    assign {Cout, Sum} = A + B + Cin;

endmodule

module barrel_shifter (
    input [15:0] data_in,
    input [3:0] shift_amount,
    input direction,
    output [15:0] data_out
);

    wire [15:0] shifted_data;

    assign shifted_data = (direction) ? (data_in << shift_amount) : (data_in >> shift_amount);

    assign data_out = shifted_data;

endmodule

