module priority_encoder_byte_reverser (
    input [7:0] in,
    input [31:0] input_vector,
    output reg [35:0] output_vector
);

    // Priority Encoder
    wire [2:0] gray_code;
    wire [2:0] binary_code;
    assign gray_code = in ? {3'b000, in} ^ {3'b000, in-1} : 3'b000;
    assign binary_code = gray_code ^ {3'b000, gray_code[2], gray_code[1], gray_code[0]};

    // Byte Reverser
    wire [7:0] byte0;
    wire [7:0] byte1;
    wire [7:0] byte2;
    wire [7:0] byte3;
    assign byte0 = input_vector[7:0];
    assign byte1 = input_vector[15:8];
    assign byte2 = input_vector[23:16];
    assign byte3 = input_vector[31:24];
    wire [31:0] reversed_vector;
    assign reversed_vector = {byte3, byte2, byte1, byte0};

    // Output Concatenation
    always @(*) begin
        output_vector = {binary_code, reversed_vector};
    end

endmodule

module top_module (
    input [7:0] in,
    input [31:0] input_vector,
    output reg [35:0] output_vector
);

    priority_encoder_byte_reverser pe_br (
        .in(in),
        .input_vector(input_vector),
        .output_vector(output_vector)
    );

endmodule

