module scanlinebuffer (pixeldataA, pixeldataB, pixeldataC, nextpixelA, nextpixelB, nextpixelC, startframe, nextscanline, fbdata, fbnextscanline, fbdatavalid, globalreset, clk);

    output[20:0] pixeldataA; 
    wire[20:0] pixeldataA;
    output[20:0] pixeldataB; 
    wire[20:0] pixeldataB;
    output[20:0] pixeldataC; 
    wire[20:0] pixeldataC;
    input nextpixelA; 
    input nextpixelB; 
    input nextpixelC; 
    input startframe; 
    input nextscanline; 
    input[62:0] fbdata; 
    output fbnextscanline; 
    reg fbnextscanline;
    output fbdatavalid;
    reg fbdatavalid;
    input globalreset; 
    input clk; 

    reg[1:0] state; 
    reg[1:0] next_state; 
    reg weA; 
    reg weB; 
    reg weC; 

    reg temp_fbnextscanline;

    scanline scanlineA (nextpixelA, weA, fbdata[62:0], pixeldataA, globalreset, clk); 
    scanline scanlineB (nextpixelB, weB, fbdata[62:0], pixeldataB, globalreset, clk); 
    scanline scanlineC (nextpixelC, weC, fbdata[62:0], pixeldataC, globalreset, clk); 

    always @(posedge clk or posedge globalreset)
    begin
        if (globalreset == 1'b1)
        begin
            state <= 0 ; 
            fbnextscanline <= 1'b0 ; 
            fbdatavalid <= 1'b0;
        end
        else
        begin
            state <= next_state ; 
            if (fbdatavalid == 1'b1)
            begin
                fbnextscanline <= 1'b0 ; 
            end 
            else
            begin
                fbnextscanline <= temp_fbnextscanline;
            end
        end
    end

    always @(state or nextscanline or fbdatavalid or startframe)
    begin
        case (state)
            0 :
                begin
                    weB = 1'b0 ; 
                    weC = 1'b0 ; 
                    weA = fbdatavalid ; 
                    if (nextscanline == 1'b1 & startframe == 1'b1)
                    begin
                        next_state = 2 ; 
                    end
                    else
                    begin
                        next_state = 0 ; 
                    end 
                    if (startframe == 1'b1 & nextscanline == 1'b1)
                    begin
                        temp_fbnextscanline = 1'b1 ; 
                    end 
                    fbdatavalid <= 1'b1;
                end
            1 :
                begin
                    weB = 1'b0 ; 
                    weC = 1'b0 ; 
                    weA = fbdatavalid ; 
                    if (nextscanline == 1'b1)
                    begin
                        next_state = 2 ; 
                    end
                    else
                    begin
                        next_state = 1 ; 
                    end 
                    if (nextscanline == 1'b1)
                    begin
                        temp_fbnextscanline = 1'b1 ; 
                    end 
                    fbdatavalid <= 1'b1;
                end
            2 :
                begin
                    weA = 1'b0 ; 
                    weC = 1'b0 ; 
                    weB = fbdatavalid ; 
                    if (nextscanline == 1'b1)
                    begin
                        next_state = 3 ; 
                    end
                    else
                    begin
                        next_state = 2 ; 
                    end 
                    if (nextscanline == 1'b1)
                    begin
                        temp_fbnextscanline = 1'b1 ; 
                    end 
                    fbdatavalid <= 1'b1;
                end
            3 :
                begin
                    weA = 1'b0 ; 
                    weB = 1'b0 ; 
                    weC = fbdatavalid ; 
                    if (nextscanline == 1'b1)
                    begin
                        next_state = 1 ; 
                    end
                    else
                    begin
                        next_state = 3 ; 
                    end 
                    if (nextscanline == 1'b1)
                    begin
                        temp_fbnextscanline = 1'b1 ; 
                    end 
                    fbdatavalid <= 1'b1;
                end
        endcase 
    end 
 endmodule

module top_module (
    input wire [15:0] in,
    input wire [7:0] a,
    input wire [7:0] b,
    output wire [7:0] out
);

    wire [7:0] upper_byte;
    wire [7:0] lower_byte;
    wire [7:0] sum;
    wire overflow;

    byte_splitter bs(
        .in(in),
        .out_hi(upper_byte),
        .out_lo(lower_byte)
    );

    add_overflow_detection aod_upper(
        .a(a),
        .b(upper_byte),
        .s(sum),
        .overflow(overflow)
    );

    add_overflow_detection aod_lower(
        .a(b),
        .b(lower_byte),
        .s(sum),
        .overflow(overflow)
    );

    assign out = sum;

endmodule

module byte_splitter (
    input wire [15:0] in,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo
);
    assign out_hi = in[15:8];
    assign out_lo = in[7:0];
endmodule

module add_overflow_detection (
    input [7:0] a,
    input [7:0] b,
    output [7:0] s,
    output overflow
);
    reg [8:0] temp_sum;
    assign s = temp_sum[7:0];
    assign overflow = (temp_sum[8] == 1);

    always @(*) begin
        temp_sum = a + b;
    end

endmodule

module small_fifo (
    input clock,
    input [71:0] data,
    input rdreq,
    input sclr,
    input wrreq,
    output empty,
    output full,
    output [71:0] q,
    output [2:0] usedw
);

    reg [71:0] buffer [0:7];
    reg [2:0] head;
    reg [2:0] tail;
    reg [2:0] next_tail;
    reg [2:0] usedw_reg;
    wire full_reg;
    wire empty_reg;

    assign full = full_reg;
    assign empty = empty_reg;
    assign q = buffer[tail];
    assign usedw = usedw_reg;

    always @(posedge clock) begin
        if (sclr) begin
            head <= 3'b0;
            tail <= 3'b0;
            next_tail <= 3'b0;
            usedw_reg <= 3'b0;
        end else begin
            if (wrreq && !full_reg) begin
                buffer[head] <= data;
                head <= head + 1;
                usedw_reg <= usedw_reg + 1;
            end
            if (rdreq && !empty_reg) begin
                tail <= next_tail;
                next_tail <= next_tail + 1;
                usedw_reg <= usedw_reg - 1;
            end
        end
    end

    assign full_reg = (usedw_reg == 3'b100);
    assign empty_reg = (usedw_reg == 3'b0);

endmodule

module log_exp (
  input [31:0] x,
  input [2:0] ctrl,
  output [31:0] y
);

  reg signed [31:0] ln_x;
  reg signed [31:0] log2_x;
  reg signed [31:0] log10_x;
  reg signed [31:0] exp_x;
  reg signed [31:0] exp2_x;
  reg signed [31:0] exp10_x;

  always @(*) begin
    ln_x = $ln(x);
    log2_x = $log10(x) / $log10(2);
    log10_x = $log10(x);
    exp_x = $exp(x);
    exp2_x = $pow(2, x);
    exp10_x = $pow(10, x);

    case(ctrl)
      3'b000: y = ln_x;
      3'b001: y = log2_x;
      3'b010: y = log10_x;
      3'b011: y = exp_x;
      3'b100: y = exp2_x;
      3'b101: y = exp10_x;
      default: y = 0;
    endcase
  end

endmodule

