module ConvolutionalEncoderViterbiDecoder (
  input [n-1:0] in,
  output [k-1:0] out
);

parameter n = 4; // number of input bits
parameter k = 8; // number of output bits
parameter m = 3; // memory depth of encoder and decoder
parameter [k-1:0] g = {3'b111, 3'b101}; // generator polynomials of the encoder

// Convolutional Encoder
reg [m-1:0] shift_register;
integer i;
always @(in) begin
  shift_register <= {shift_register[m-2:0], in};
  for (i = 0; i < k; i = i + 1) begin
    out[i] <= shift_register[0] ^ (shift_register & g[i]);
  end
end

// Viterbi Decoder
reg [m-1:0] state_register;
reg [n-1:0] decoded_bits;
integer j;
integer min_metric;
integer min_index;
integer metric;

always @(out) begin
  for (j = 0; j < n; j = j + 1) begin
    min_metric = 2**m;
    min_index = 0;
    for (i = 0; i < k; i = i + 1) begin
      state_register <= {state_register[m-2:0], i};
      metric = out[i] ^ (state_register[0] ^ (state_register & g[i]));
      if (metric < min_metric) begin
        min_metric = metric;
        min_index = i;
      end
    end
    decoded_bits[j] <= min_index;
  end
end

assign in = decoded_bits;

endmodule

