module master_slave_mux (
    input [PW-1:0] packet_in,
    input access_in,
    input wait_in,
    input master_active,
    input [1:0] datamode,
    input [4:0] ctrlmode,
    input [AW-1:0] dstaddr,
    input [AW-1:0] data_in,
    input [AW-1:0] srcaddr_in,
    input write_in,
    output reg [PW-1:0] packet_out,
    output reg access_out,
    output reg wait_out,
    output reg [1:0] datamode_out,
    output reg [4:0] ctrlmode_out,
    output reg [AW-1:0] dstaddr_out,
    output reg [AW-1:0] data_out,
    output reg [AW-1:0] srcaddr_out
);

    // If master is active, use input values as output values
    always @(*) begin
        if (master_active) begin
            datamode_out = datamode;
            ctrlmode_out = ctrlmode;
            dstaddr_out = dstaddr;
            data_out = data_in;
            srcaddr_out = srcaddr_in;
            packet_out = 0;
            access_out = write_in ? 0 : 1;
        end
    end

    // If slave is active, use input values as output values
    always @(*) begin
        if (!master_active) begin
            datamode_out = datamode_in[1:0];
            ctrlmode_out = ctrlmode_in[4:0];
            dstaddr_out = dstaddr_in[AW-1:0];
            data_out = data_in[31:0];
            srcaddr_out = srcaddr_in[31:0];
            packet_out = packet_in;
            access_out = access_in;
        end
    end

    // Wait output is same as wait input
    assign wait_out = wait_in;

endmodule

