module cpu_vreg(
	input wire clk,
	input wire copy_in_progress,
	input wire cpu_rd,
	input wire cpu_wr,
	input wire cpu_mreq,
	input wire [15:0] cpu_addr,
	inout wire [7:0] cpu_data,
	output reg back_vram_wr_low,
	output reg [12:0] back_vram_addr,
	output reg [7:0] back_vram_data
	);

reg is_busy_out;
assign cpu_data = is_busy_out ? 4 : 8'bzzzzzzzz;

always @(posedge clk)
begin
	if(cpu_rd == 0 && cpu_mreq == 0 && cpu_addr >= 16'ha000) begin
		is_busy_out = 1;
	end
	else begin
		is_busy_out = 0;
	end

	if(copy_in_progress == 0 && cpu_wr == 0 && cpu_mreq == 0 && cpu_addr >= 16'h8000 && cpu_addr <= 16'h92bf) begin
		back_vram_addr = cpu_addr[12:0];
		back_vram_data = cpu_data;
		back_vram_wr_low = 0;
	end	
	else begin
		back_vram_wr_low = 1;
		back_vram_addr = 13'bzzzzzzzzzzzzz;
		back_vram_data = 8'bzzzzzzzz;
	end
end

endmodule

module serial_to_parallel(
    input clk,
    input in1,
    input in0,
    output reg [7:0] sr_adr,
    output reg [22:0] sr_dat,
    output reg ce_wr
);

reg [31:0] tmp_buf = 32'd0;
reg [31:0] out_buf = 32'd0;
reg [1:0] Nvel = 3;
reg [10:0] cb_tce = 0;
wire [10:0] AR_Nt = (Nvel [1:0] == 3)? (50000000 / (2 * 1000000)) : (Nvel [1:0] == 2)? (50000000 / (2 * 100000)) : (Nvel [1:0] == 1)? (50000000 / (2 * 50000)) : (50000000 / (2 * 12500));
wire ce_tact = (cb_tce == AR_Nt);
reg [2:0] cur_state = 0;
reg clr_before_next = 0;
reg act_par_bit = 0;
reg ok_check = 0;
reg [5:0] rec_bit_num = 0;
reg [3:0] time_out = 0;
parameter WaitNextData = 0;
parameter RecData = 1;
parameter WaitPos = 2;
parameter WaitNeg = 3;
parameter Done = 4;
parameter Clear = 5;

always @(posedge clk) begin
    if (cur_state == WaitNextData) begin
        cur_state <= (in1 | in0) ? Clear : WaitNextData;
        clr_before_next <= 1;
        cb_tce <= 0;
        time_out <= 0;
    end else begin
        cb_tce <= (ce_tact) ? 1 : cb_tce + 1;
    end

    if (cur_state == WaitPos) begin
        time_out <= ce_tact ? time_out : time_out + 1;
        cur_state <= (time_out > 20) ? Clear : (rec_bit_num == 32) ? Done : (in1 | in0) ? RecData : WaitPos;
    end else if (cur_state == RecData) begin
        tmp_buf <= in1 ? (tmp_buf << 1 | 1) : in0 ? (tmp_buf << 1) : tmp_buf;
        act_par_bit <= act_par_bit ^ in1;
        rec_bit_num <= rec_bit_num + 1;
        time_out <= 0;
        cur_state <= WaitNeg;
    end else if (cur_state ==  WaitNeg) begin 
        cur_state <= (!in1 & !in0) ? WaitPos : WaitNeg;
    end else if (cur_state ==  Done) begin
        out_buf <= tmp_buf;
        ok_check <= act_par_bit;
        cur_state <= WaitNextData;
    end else if (cur_state == Clear) begin
        tmp_buf <= 0;
        out_buf <= 0;
        act_par_bit <= 0;
        ok_check <= 0;
        rec_bit_num <= 0;
        time_out <= 0;
        cur_state <= clr_before_next ? WaitPos : WaitNextData;
    end
end

assign sr_adr = out_buf [31:24];
generate
    genvar i;
    for (i = 0; i <= 22 ; i = i + 1) begin: data_loop
        assign sr_dat[i] = out_buf [23 - i];
    end
endgenerate

assign ce_wr = ok_check;

endmodule

module singlePortRAM
#(parameter DATA_WIDTH=16, parameter ADDR_WIDTH=8)
(
   input [(DATA_WIDTH-1):0] data,
   input [(ADDR_WIDTH-1):0] addr,
   input we, clk,
   output [(DATA_WIDTH-1):0] q
);

   // Declare the RAM variable
   reg [DATA_WIDTH-1:0] ram[2**ADDR_WIDTH-1:0];

   // Variable to hold the registered read address
   reg [ADDR_WIDTH-1:0] addr_reg;

   // Specify the initial contents. You can also use the $readmemb
   // system task to initialize the RAM variable from a text file.
   initial 
   begin : INIT
      $readmemb("C:/ram_init.txt", ram);
   end 

   always @ (posedge clk)
   begin
      // Write
      if (we)
         ram[addr] <= data;

      addr_reg <= addr;
   end

   // Continuous assignment implies read returns NEW data.
   // This is the natural behavior of the TriMatrix memory
   // blocks in Single Port mode.  
   assign q = ram[addr_reg];

endmodule

