module mux256(
    input [2047:0] in,
    input [7:0] sel,
    input [1:0] enable,
    output reg [7:0] out1,
    output reg [7:0] out2,
    output reg [7:0] out3,
    output reg [7:0] out4,
    output [7:0] mux256_output
);

always @(*) begin
    case (sel)
        8'h00: mux256_output = in[7:0];
        8'h01: mux256_output = in[15:8];
        // ...
        8'hFE: mux256_output = in[2039:2032];
        8'hFF: mux256_output = in[2047:2040];
    endcase

    out1 = (enable[0]) ? 8'h00 : mux256_output;
    out2 = (enable[1]) ? 8'h00 : mux256_output;
    out3 = (~enable[0] & ~enable[1]) ? 8'h00 : mux256_output;
    out4 = (~enable[0] & enable[1]) ? 8'h00 : mux256_output;
end

