module hyperbolic (
  input signed [31:0] x,
  input [1:0] select,
  output signed [31:0] y
);

  reg signed [31:0] exp_x;
  reg signed [31:0] exp_neg_x;

  always @(*) begin
    exp_x = $exp(x);
    exp_neg_x = $exp(-x);
  end

  always @(*) begin
    case (select)
      2'b00: y = (exp_x - exp_neg_x) / 2;
      2'b01: y = (exp_x + exp_neg_x) / 2;
      2'b10: y = (exp_x - exp_neg_x) / (exp_x + exp_neg_x);
      default: y = 0;
    endcase
  end

endmodule

