module fifo (
    input rst,
    input wr_clk,
    input rd_clk,
    input [63:0] din,
    input wr_en,
    input rd_en,
    output [255:0] dout,
    output full,
    output empty
);

reg [63:0] mem [255:0]; // 256 64-bit registers
reg [7:0] wr_ptr = 8'd0; // write pointer
reg [7:0] rd_ptr = 8'd0; // read pointer
reg [7:0] count = 8'd0; // counter for number of elements in FIFO

// write logic
always @(posedge wr_clk) begin
    if (rst) begin
        wr_ptr <= 8'd0;
    end else if (wr_en) begin
        mem[wr_ptr] <= din;
        wr_ptr <= wr_ptr + 1;
        count <= count + 1;
    end
end

// read logic
always @(posedge rd_clk) begin
    if (rst) begin
        rd_ptr <= 8'd0;
    end else if (rd_en) begin
        dout <= mem[rd_ptr];
        rd_ptr <= rd_ptr + 1;
        count <= count - 1;
    end
end

// full and empty flags
assign full = (count == 8'd256);
assign empty = (count == 8'd0);

endmodule

