module stratixiv_round_block(
                        datain,
                        round,
                        datain_width,
                        dataout
                       );

parameter round_mode = "nearest_integer";
parameter operation_mode = "output_only";
parameter round_width = 15;

input [71 :0 ] datain;
input round;
input [7:0] datain_width;

output [71  : 0] dataout;

reg sign;
reg [71 :0] result_tmp;
reg [71:0] dataout_tmp;
reg [71 :0 ] dataout_value;
integer i,j;

initial
begin
    result_tmp = {(72){1'b0}};
end

assign dataout =  dataout_value;

always@(datain or round)
    begin
        if(round == 1'b0)
            dataout_value = datain;
        else
            begin
                j = 0;
                sign = 0;
                dataout_value = datain;
                if(datain_width > round_width)
                    begin
                        for(i = datain_width - round_width ; i < datain_width ; i = i+1)
                           begin
                               result_tmp[j]= datain[i];
                                j = j +1;
                           end
                        for (i = 0; i < datain_width - round_width -1 ; i = i +1)
                           begin
                               sign = sign | datain[i];
                               dataout_value[i] = 1'bX;
                           end
                       dataout_value[datain_width - round_width -1] = 1'bX;
                        //rounding logic
                        if(datain[datain_width - round_width -1 ] == 1'b0)// fractional < 0.5
                            begin
                                dataout_tmp = result_tmp;
                            end
                        else if((datain[datain_width - round_width -1 ] == 1'b1) && (sign == 1'b1))//fractional > 0.5
                            begin
                                dataout_tmp = result_tmp + 1'b1;
                            end
                        else
                            begin
                                if(round_mode == "nearest_even")//unbiased rounding
                                    begin
                                        if(result_tmp % 2) //check for odd integer
                                            dataout_tmp = result_tmp + 1'b1;
                                        else
                                            dataout_tmp = result_tmp;
                                    end
                                else //biased rounding
                                    begin
                                        dataout_tmp = result_tmp + 1'b1;
                                    end
                            end
                        j = 0;
                        for(i = datain_width - round_width ; i < datain_width  ; i = i+1)
                           begin
                               dataout_value[i]= dataout_tmp[j];
                               j = j+1;
                           end  
                    end
            end
    end         
endmodule

module pipelined_add_sub (
  input clk,
  input reset,
  input mode,
  input [7:0] A,
  input [7:0] B,
  output reg [7:0] Result
);

  // Internal signals
  wire [3:0] carry_in_add;
  wire [3:0] carry_in_sub;
  wire [3:0] carry_out_add;
  wire [3:0] carry_out_sub;
  wire [7:0] add_out;
  wire [7:0] sub_out;
  reg [7:0] reg_add_out;
  reg [7:0] reg_sub_out;

  // Carry lookahead adder and subtractor instances
  carry_lookahead_adder adder_inst (
    .A(A[3:0]),
    .B(B[3:0]),
    .C(carry_in_add),
    .S(add_out[3:0]),
    .CO(carry_out_add[3:0])
  );

  carry_lookahead_subtractor sub_inst (
    .A(A[3:0]),
    .B(B[3:0]),
    .C(carry_in_sub),
    .D(sub_out[3:0]),
    .BO(carry_out_sub[3:0])
  );

  // Pipeline registers
  always @(posedge clk) begin
    if (reset) begin
      reg_add_out <= 0;
      reg_sub_out <= 0;
    end else begin
      reg_add_out <= add_out;
      reg_sub_out <= sub_out;
    end
  end

  // Output mux
  always @(*) begin
    if (mode) begin
      Result <= reg_sub_out;
    end else begin
      Result <= reg_add_out;
    end
  end

  // Carry input generation
  assign carry_in_add = {4{carry_out_add[3]}};
  assign carry_in_sub = {4{~carry_out_sub[3]}};

endmodule

module carry_lookahead_adder (
  input [3:0] A,
  input [3:0] B,
  input [3:0] C,
  output [3:0] S,
  output [3:0] CO
);

  assign S = A + B + C;
  assign CO = (A & B) | (C & (A | B));

endmodule

module carry_lookahead_subtractor (
  input [3:0] A,
  input [3:0] B,
  input [3:0] C,
  output [3:0] D,
  output [3:0] BO
);

  assign D = A - B - C;
  assign BO = (~A & B) | ((~A | B) & (C | ~(A ^ B)));

endmodule

