module vending_machine (
    input clk,
    input rst,
    input [1:0] coin,
    input [1:0] product,
    output reg dispense,
    output reg [1:0] change,
    output reg [5:0] collected
);

// internal signals
reg [5:0] money;
reg [5:0] price;
reg [1:0] product_selected;
reg [1:0] coin_inserted;

// constants
parameter A_PRICE = 25;
parameter B_PRICE = 35;
parameter C_PRICE = 45;

// state machine
reg [1:0] state, next_state;

parameter IDLE = 2'b00;
parameter COIN_INSERTED = 2'b01;
parameter PRODUCT_SELECTED = 2'b10;

always @(posedge clk) begin
    if (rst) begin
        // reset
        money <= 0;
        price <= 0;
        product_selected <= 0;
        coin_inserted <= 0;
        state <= IDLE;
        change <= 0;
        collected <= 0;
        dispense <= 0;
    end else begin
        // update internal signals
        if (coin == 2'b00) begin
            coin_inserted <= 2'b00;
            money <= money + 5;
        end else if (coin == 2'b01) begin
            coin_inserted <= 2'b01;
            money <= money + 10;
        end else if (coin == 2'b10) begin
            coin_inserted <= 2'b10;
            money <= money + 25;
        end

        if (product == 2'b00) begin
            product_selected <= 2'b00;
            price <= A_PRICE;
        end else if (product == 2'b01) begin
            product_selected <= 2'b01;
            price <= B_PRICE;
        end else if (product == 2'b10) begin
            product_selected <= 2'b10;
            price <= C_PRICE;
        end

        // state machine
        state <= next_state;
        case (state)
            IDLE: begin
                if (coin_inserted != 2'b00) begin
                    next_state = COIN_INSERTED;
                end else begin
                    next_state = IDLE;
                end
            end
            COIN_INSERTED: begin
                if (product_selected == 2'b00 && money >= A_PRICE) begin
                    next_state = PRODUCT_SELECTED;
                end else if (product_selected == 2'b01 && money >= B_PRICE) begin
                    next_state = PRODUCT_SELECTED;
                end else if (product_selected == 2'b10 && money >= C_PRICE) begin
                    next_state = PRODUCT_SELECTED;
                end else begin
                    next_state = COIN_INSERTED;
                end
            end
            PRODUCT_SELECTED: begin
                if (money > price) begin
                    change <= money - price;
                    collected <= collected + price;
                    dispense <= 1;
                    next_state = IDLE;
                end else if (money == price) begin
                    collected <= collected + price;
                    dispense <= 1;
                    next_state = IDLE;
                end else begin
                    next_state = PRODUCT_SELECTED;
                end
            end
            default: next_state = IDLE;
        endcase
    end
end

endmodule

module clock_gate (
  input CLK, EN, TE,
  output reg ENCLK
);

  reg gated_clk;

  always @(posedge CLK) begin
    if (EN && TE) begin
      gated_clk <= 1'b1;
    end else begin
      gated_clk <= 1'b0;
    end
  end

  always @(posedge CLK) begin
    if (EN && TE) begin
      ENCLK <= gated_clk;
    end
  end

endmodule

