module fifo (
  input clk,
  input wr,
  input rd,
  input reset_n,
  input [7:0] wr_data,
  output [7:0] rd_data,
  output empty,
  output full,
  output almost_empty,
  output almost_full
);

  reg [7:0] buffer [1:0];
  reg [1:0] wr_ptr;
  reg [1:0] rd_ptr;
  wire [1:0] next_wr_ptr = (wr_ptr == 2'b11) ? 2'b00 : (wr_ptr + 1);
  wire [1:0] next_rd_ptr = (rd_ptr == 2'b11) ? 2'b00 : (rd_ptr + 1);

  assign empty = (wr_ptr == rd_ptr);
  assign full = (next_wr_ptr == rd_ptr);
  assign almost_empty = ((wr_ptr == next_rd_ptr) && !empty);
  assign almost_full = ((next_wr_ptr == rd_ptr) && !full);

  always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
      buffer[1] <= 8'b0;
      buffer[0] <= 8'b0;
      wr_ptr <= 2'b00;
      rd_ptr <= 2'b00;
    end else begin
      if (wr && !full) begin
        buffer[wr_ptr] <= wr_data;
        wr_ptr <= next_wr_ptr;
      end
      if (rd && !empty) begin
        rd_data <= buffer[rd_ptr];
        rd_ptr <= next_rd_ptr;
      end
    end
  end

endmodule

module avgai(input clk, reset, input [9:0] SW,
					output reg [9:0] LEDG,
					output [3:0] VGA_R, VGA_G, VGA_B, output VGA_VS, VGA_HS,
					inout [31:0] GPIO_1);
	wire [5:0] inData = {GPIO_1[13],GPIO_1[11],GPIO_1[9],GPIO_1[7],GPIO_1[5],GPIO_1[3]};
	wire inDataClk = GPIO_1[1];

	wire ready;
	wire wAck;
	assign GPIO_1[0] = ready;

	wire [15:0] SRAM_data;
	wire [7:0] INT_X, INT_Y, SRAM_X, SRAM_Y;
	wire [11:0] SRAM_out;
	wire [11:0] VGA_Data;
	wire [9:0] hNeed, vNeed;
	vgaControl(clk, reset_, VGA_VS, VGA_HS, need, hNeed, vNeed);

	wire [11:0] wDbg;

	comm_int(clk, 0, inDataClk, inData, INT_X, INT_Y, SRAM_data, write);

	wire SRAM_read = need;
	wire SRAM_write = !SRAM_read & write;
	assign ready = !write | wAck;
	assign SRAM_X = SRAM_read ? hNeed >> 2 : INT_X;
	assign SRAM_Y = SRAM_read ? vNeed >> 2 : INT_Y;

	reg needBuf;
	always @(posedge clk) needBuf <= need;
	assign {VGA_R, VGA_G, VGA_B} = VGA_Data;
	assign VGA_Data = needBuf ? SRAM_out : 0;

	SRAM(clk, SRAM_read, SRAM_write, SRAM_X, SRAM_Y, SRAM_data >> 4, SRAM_out, wAck, wDbg);
	clkDiv(clk, divClk);

	// Debugging LEDs
	always @* begin
		LEDG[9] = inDataClk;
		LEDG[8] = ready;
		LEDG[7] = write;
		LEDG[5:0] = inData;
	end

	// Average Calculation
	reg [7:0] sum = 0;
	reg [7:0] count = 0;
	wire [7:0] avg;
	wire [7:0] avgBin;

	always @(posedge clk) begin
		if (ready && !write) begin
			sum <= sum + inData;
			count <= count + 1;
		end
	end

	assign avg = sum / count;
	assign avgBin = {avg[7], avg[6], avg[5], avg[4], avg[3], avg[2], avg[1], avg[0]};

	// VGA Display
	wire [9:0] hCenter = 320;
	wire [9:0] vCenter = 240;
	wire [11:0] color = {8'b0, avg[7:4], 8'b0, avg[3:0]};
	wire [11:0] blank = 12'b0;
	wire [9:0] hNeedOffset = hNeed - hCenter;
	wire [9:0] vNeedOffset = vNeed - vCenter;
	wire [10:0] distance = hNeedOffset*hNeedOffset + vNeedOffset*vNeedOffset;
	wire [10:0] radius = 100*100;

	assign VGA_Data = (distance < radius) ? color : blank;

	// LEDG Display
	assign LEDG = avgBin;

endmodule

module FreqSynth (
  input clk_ref,
  input [m-1:0] ctrl,
  input rst,
  output reg clk_out
);

parameter m = 4; // number of control signals
parameter ref_freq = 50; // frequency of the reference clock signal
parameter out_freq = 500; // desired frequency of the output clock signal

reg [7:0] divider = 0;
reg [7:0] multiplier = 0;

always @(posedge clk_ref or posedge rst) begin
  if (rst) begin
    divider <= 0;
    multiplier <= 0;
    clk_out <= 0;
  end else begin
    if (divider == 0) begin
      divider <= ctrl + 1;
      if (multiplier == 0) begin
        multiplier <= (out_freq / ref_freq) - 1;
      end else begin
        multiplier <= multiplier - 1;
      end
    end else begin
      divider <= divider - 1;
    end
    if (multiplier == 0) begin
      clk_out <= ~clk_out;
    end
  end
end

endmodule

module AddSub16(
    input clk,
    input rst,
    input [15:0] arg_0,
    input [15:0] arg_1,
    input is_sub,
    output [15:0] ret_0,
    output [15:0] ret_1,
    output ret_2,
    output ret_3
);

    wire [15:0] x;
    wire [15:0] y;
    wire        ys;
    wire        yys;
    wire [15:0] yy;
    wire        diff_sign;
    wire [4:0]  xe;
    wire [4:0]  ye;
    wire        swap;
    wire        neg_lhs;
    wire        neg_rhs;
    wire [15:0] lhs;
    wire [15:0] rhs;
    wire [16:0] sum;

    assign x = arg_0;
    assign y = arg_1;
    assign ys = y[15];
    assign yys = is_sub ? ~ys : ys;
    assign yy = {yys, y[14:0]};
    assign xe = x[14:10];
    assign ye = y[14:10];

    assign diff_sign = x[15] ^ yy[15];

    assign swap = xe < ye;
    assign lhs = swap ? yy : x;
    assign rhs = swap ? x : yy;

    assign neg_lhs = diff_sign ? lhs[15] : 0;
    assign neg_rhs = diff_sign ? rhs[15] : 0;

    assign sum = {1'b0, lhs} + {neg_rhs, rhs};

    assign ret_0 = lhs;
    assign ret_1 = rhs;
    assign ret_2 = neg_lhs;
    assign ret_3 = neg_rhs;

    always @(posedge clk) begin
        if (rst) begin
            ret_0 <= 16'b0;
            ret_1 <= 16'b0;
            ret_2 <= 1'b0;
            ret_3 <= 1'b0;
        end else begin
            if (is_sub) begin
                ret_0 <= lhs;
                ret_1 <= rhs;
                ret_2 <= neg_lhs;
                ret_3 <= neg_rhs;
            end else begin
                ret_0 <= sum[15:0];
                ret_1 <= sum[15:0];
                ret_2 <= sum[16];
                ret_3 <= 1'b0;
            end
        end
    end
endmodule

module adder(input [3:0] A, input [3:0] B, input Cin, output [3:0] S, output Cout);

  wire C1, C2, C3;
  wire S0, S1, S2, S3;

  // 1st bit
  full_adder FA1(A[0], B[0], Cin, S0, C1);

  // 2nd bit
  full_adder FA2(A[1], B[1], C1, S1, C2);

  // 3rd bit
  full_adder FA3(A[2], B[2], C2, S2, C3);

  // 4th bit
  full_adder FA4(A[3], B[3], C3, S3, Cout);

  assign S = {S3, S2, S1, S0};

endmodule

module full_adder(input A, input B, input Cin, output S, output Cout);

  wire C1, C2, C3;

  // First stage
  xor (S, A, B);
  and (C1, A, B);

  // Second stage
  xor (S, S, Cin);
  and (C2, S, Cin);

  // Third stage
  or (Cout, C1, C2);

endmodule

module RAM16x4(
    input [11:0] address,
    input clken,
    input clock,
    input [3:0] data,
    input wren,
    output reg [3:0] q
);

    wire [3:0] q0, q1, q2, q3;
    wire [11:0] a0, a1, a2, a3;

    assign a0 = address[11:8];
    assign a1 = {address[11:9], address[7]};
    assign a2 = {address[11:10], address[6:5]};
    assign a3 = {address[11], address[4:0]};

    RAMB16_S4_altera ram0 (
        .address(a0),
        .clken(clken),
        .clock(clock),
        .data(data),
        .wren(wren),
        .q(q0)
    );

    RAMB16_S4_altera ram1 (
        .address(a1),
        .clken(clken),
        .clock(clock),
        .data(data),
        .wren(wren),
        .q(q1)
    );

    RAMB16_S4_altera ram2 (
        .address(a2),
        .clken(clken),
        .clock(clock),
        .data(data),
        .wren(wren),
        .q(q2)
    );

    RAMB16_S4_altera ram3 (
        .address(a3),
        .clken(clken),
        .clock(clock),
        .data(data),
        .wren(wren),
        .q(q3)
    );

    always @(posedge clock) begin
        if (wren) begin
            case (address[11:8])
                4'b0000: q0 <= data;
                4'b0001: q1 <= data;
                4'b0010: q2 <= data;
                4'b0011: q3 <= data;
                default: q <= 4'bZZZZ;
            endcase
        end else begin
            case (address[11:8])
                4'b0000: q <= q0;
                4'b0001: q <= q1;
                4'b0010: q <= q2;
                4'b0011: q <= q3;
                default: q <= 4'bZZZZ;
            endcase
        end
    end

endmodule

module modulo (
  input [31:0] A,
  input [31:0] B,
  output [31:0] C
);

  // If B is zero, the output C should be zero.
  // If A is zero, the output C should be zero.
  // In both cases, we can simply assign zero to the output.
  assign C = (B == 0) ? 0 : ((A == 0) ? 0 : C);

  // If A is negative, the output C should be the modulus of A with respect to B.
  // If B is negative, the output C should be the modulus of A with respect to -B.
  // In both cases, we can use the mod operator to compute the modulus.
  // Note that we need to use the absolute value of B in the second case.
  assign C = (A < 0) ? ((B < 0) ? -A % -B : -A % B) : ((B < 0) ? A % -B : A % B);

endmodule

module xor_gate(
    input A,
    input B,
    output Y
);

    assign Y = (A & ~B) | (~A & B);

endmodule

module fifo_buffer(
    input clock,
    input ready,
    input [7:0] head,

    output reg tail_req,
    input tail_ack,
    input [7:0] tail_value,
    input tail_value_valid,

    input req,
    output reg ack,
    output reg [7:0] value,
    output reg value_valid
);

reg [7:0] buffer [0:255];
reg [7:0] read_pointer;
reg [7:0] write_pointer;
reg [7:0] next_write_pointer;
reg [7:0] next_read_pointer;
reg [7:0] read_data;
reg [7:0] write_data;
reg [7:0] tail_data;
reg [7:0] next_tail_data;
reg [7:0] tail_pointer;
reg [7:0] next_tail_pointer;
reg [7:0] head_pointer;
reg [7:0] next_head_pointer;
reg [7:0] buffer_size;
reg [7:0] next_buffer_size;
reg tail_full;
reg head_full;
reg tail_empty;
reg head_empty;
reg [7:0] i;

always @(posedge clock) begin
    if (ready) begin

        // Write data to the head
        if (!head_full && head_pointer == write_pointer) begin
            buffer[write_pointer] <= head;
            next_write_pointer <= write_pointer + 1;
            if (next_write_pointer == 256) begin
                next_write_pointer <= 0;
            end
            head_full <= (next_write_pointer == read_pointer);
        end else begin
            next_write_pointer <= write_pointer;
            head_full <= 0;
        end

        // Read data from the head
        if (req && !head_empty && read_pointer == head_pointer) begin
            read_data <= buffer[read_pointer];
            next_read_pointer <= read_pointer + 1;
            if (next_read_pointer == 256) begin
                next_read_pointer <= 0;
            end
            head_empty <= (next_read_pointer == write_pointer);
        end else begin
            next_read_pointer <= read_pointer;
            head_empty <= 1;
        end

        // Write data to the tail
        if (!tail_full && tail_pointer == read_pointer) begin
            buffer[tail_pointer] <= tail_data;
            next_tail_pointer <= tail_pointer - 1;
            if (next_tail_pointer == -1) begin
                next_tail_pointer <= 255;
            end
            tail_full <= (next_tail_pointer == write_pointer);
        end else begin
            next_tail_pointer <= tail_pointer;
            tail_full <= 0;
        end

        // Read data from the tail
        if (tail_req && !tail_empty && write_pointer == tail_pointer) begin
            tail_data <= buffer[tail_pointer];
            next_tail_data <= tail_value;
            next_tail_pointer <= tail_pointer - 1;
            if (next_tail_pointer == -1) begin
                next_tail_pointer <= 255;
            end
            tail_empty <= (next_tail_pointer == read_pointer);
        end else begin
            next_tail_data <= tail_value;
            next_tail_pointer <= tail_pointer;
            tail_empty <= 1;
        end

        // Update buffer size
        if (head_pointer <= tail_pointer) begin
            buffer_size <= tail_pointer - head_pointer;
        end else begin
            buffer_size <= 256 - head_pointer + tail_pointer;
        end
        next_buffer_size <= buffer_size;

        // Update head pointer
        if (!head_empty) begin
            next_head_pointer <= next_read_pointer;
        end else begin
            next_head_pointer <= head_pointer;
        end

        // Update tail pointer
        if (!tail_full) begin
            next_tail_pointer <= next_tail_pointer;
        end else begin
            next_tail_pointer <= tail_pointer;
        end

    end else begin
        next_write_pointer <= write_pointer;
        next_read_pointer <= read_pointer;
        next_head_pointer <= head_pointer;
        next_tail_pointer <= tail_pointer;
        next_tail_data <= tail_value;
        next_buffer_size <= buffer_size;
    end
end

always @(*) begin
    write_pointer <= next_write_pointer;
    read_pointer <= next_read_pointer;
    head_pointer <= next_head_pointer;
    tail_pointer <= next_tail_pointer;
    tail_data <= next_tail_data;
    buffer_size <= next_buffer_size;

    if (!head_empty && head_pointer == read_pointer) begin
        value <= read_data;
        ack <= 1;
        value_valid <= 1;
    end else begin
        value <= 0;
        ack <= 0;
        value_valid <= 0;
    end

    if (tail_full) begin
        tail_req <= 0;
    end else begin
        tail_req <= 1;
    end

end

endmodule

module d_ff_using_t_ff (
    input clk,    // Clocks are used in sequential circuits
    input d,      // Data input
    output reg q // Single-bit output stored in a register with active high synchronous reset
);

reg t; // T input for the T flip-flop

// Combinational circuit to generate T input based on clock and data inputs
always @ (posedge clk) begin
    t <= d ^ q; // XOR gate generates T input
end

// T flip-flop with active high synchronous reset
always @ (posedge clk, posedge rst) begin
    if (rst) begin
        q <= 1'b0;
    end else begin
        q <= t;
    end
end

endmodule

module freq_synth (
  input ref_clk,
  input [n-1:0] ctrl,
  output freq_out
);

parameter f_ref = 10_000_000; // frequency of reference clock signal (10 MHz)
parameter f_out = 1_000_000; // desired frequency of output signal (1 MHz)
parameter n = 16; // number of bits in phase accumulator

wire [n-1:0] phase;
wire [n-1:0] phase_inc;
wire [n-1:0] phase_acc;
wire [7:0] sine_out;
wire [7:0] dac_out;
wire lp_filter_out;
wire vco_out;

// Phase accumulator module
phase_accumulator #(.N(n)) pa (
  .clk(ref_clk),
  .ctrl(ctrl),
  .phase(phase),
  .phase_inc(phase_inc),
  .phase_acc(phase_acc)
);

// Lookup table module
lookup_table lt (
  .phase(phase),
  .sine_out(sine_out)
);

// Digital-to-analog converter module
dac #(.N(8)) d (
  .data_in(sine_out),
  .data_out(dac_out)
);

// Low-pass filter module
lp_filter lp (
  .data_in(dac_out),
  .data_out(lp_filter_out)
);

// Voltage-controlled oscillator module
vco v (
  .clk(ref_clk),
  .ctrl(lp_filter_out),
  .freq_out(freq_out)
);

endmodule

// Phase accumulator module
module phase_accumulator (
  input clk,
  input [n-1:0] ctrl,
  output reg [n-1:0] phase,
  output reg [n-1:0] phase_inc,
  output reg [n-1:0] phase_acc
);

always @(posedge clk) begin
  if (ctrl == 1'b1) begin
    phase <= 0;
    phase_inc <= (f_out/f_ref)*(2**n);
    phase_acc <= phase_acc + phase_inc;
    phase <= phase_acc[n-1:0];
  end
end

endmodule

// Lookup table module
module lookup_table (
  input [n-1:0] phase,
  output reg [7:0] sine_out
);

always @(phase) begin
  case (phase[n-1:8])
    0: sine_out <= 8'h80;
    1: sine_out <= 8'h8f;
    2: sine_out <= 8'h9e;
    3: sine_out <= 8'hae;
    4: sine_out <= 8'hbd;
    5: sine_out <= 8'hcb;
    6: sine_out <= 8'hd9;
    7: sine_out <= 8'he6;
    8: sine_out <= 8'hef;
    9: sine_out <= 8'hf7;
    10: sine_out <= 8'hfd;
    11: sine_out <= 8'hff;
    12: sine_out <= 8'hff;
    13: sine_out <= 8'hfd;
    14: sine_out <= 8'hf7;
    15: sine_out <= 8'hef;
    16: sine_out <= 8'he6;
    17: sine_out <= 8'hd9;
    18: sine_out <= 8'hcb;
    19: sine_out <= 8'hbd;
    20: sine_out <= 8'hae;
    21: sine_out <= 8'h9e;
    22: sine_out <= 8'h8f;
    23: sine_out <= 8'h80;
  endcase
end

endmodule

// Digital-to-analog converter module
module dac (
  input [7:0] data_in,
  output reg data_out
);

always @(data_in) begin
  data_out <= data_in;
end

endmodule

// Low-pass filter module
module lp_filter (
  input [7:0] data_in,
  output reg data_out
);

parameter alpha = 0.1;

reg [7:0] prev_data;

always @(data_in) begin
  prev_data <= prev_data*(1-alpha) + data_in*alpha;
  data_out <= prev_data;
end

endmodule

// Voltage-controlled oscillator module
module vco (
  input clk,
  input lp_filter_out,
  output freq_out
);

parameter k = 1;

reg [31:0] phase_acc;

always @(posedge clk) begin
  phase_acc <= phase_acc + k*lp_filter_out;
  freq_out <= $sin(2*3.14159*phase_acc/2**32);
end

endmodule

