module uart(
    input clk,
    input reset,
    input rx_data,
    input rx_valid,
    input tx_ready,
    input [7:0] tx_data,
    output tx_valid,
    output rx_ready,
    output rx_error
);

    // Baud rate divisor calculation
    parameter BAUD_RATE = 9600;
    parameter CLK_FREQ = 50000000;
    parameter BAUD_DIV = CLK_FREQ / (BAUD_RATE * 16);

    // Counter for baud rate generation
    reg [15:0] baud_counter = 0;

    // Register for received data
    reg [7:0] rx_reg = 0;

    // Flags for received data and errors
    reg rx_flag = 0;
    reg rx_error_flag = 0;

    // Register for transmitted data
    reg [7:0] tx_reg = 0;

    // Flags for transmitted data
    reg tx_flag = 0;

    // Counter for transmitting data
    reg [3:0] tx_counter = 0;

    // Baud rate generator
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            baud_counter <= 0;
        end else begin
            if (baud_counter == BAUD_DIV - 1) begin
                baud_counter <= 0;
            end else begin
                baud_counter <= baud_counter + 1;
            end
        end
    end

    // Receiver
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            rx_flag <= 0;
            rx_error_flag <= 0;
            rx_reg <= 0;
        end else begin
            if (baud_counter == BAUD_DIV - 1) begin
                rx_reg <= {rx_data, rx_reg[7:1]};
                if (!rx_flag && rx_valid) begin
                    rx_flag <= 1;
                end
            end
            if (rx_flag && !rx_error_flag && baud_counter == BAUD_DIV / 2) begin
                if (rx_reg[0] == 1'b0) begin
                    rx_flag <= 0;
                    rx_ready <= 1;
                end else if (rx_reg[0] == 1'b1) begin
                    rx_error_flag <= 1;
                    rx_error <= 1;
                end
            end
        end
    end

    // Transmitter
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            tx_flag <= 0;
            tx_counter <= 0;
            tx_reg <= 0;
            tx_valid <= 0;
        end else begin
            if (tx_ready && !tx_flag) begin
                tx_reg <= tx_data;
                tx_flag <= 1;
                tx_counter <= 0;
                tx_valid <= 1;
            end
            if (tx_flag && baud_counter == BAUD_DIV - 1) begin
                tx_counter <= tx_counter + 1;
                if (tx_counter == 4) begin
                    tx_flag <= 0;
                    tx_valid <= 0;
                    tx_ready <= 0;
                end else begin
                    tx_ready <= 1;
                end
            end
        end
    end

endmodule

