    output reg equal
);

reg [3:0] a_shifted;
reg [3:0] b_shifted;

always @(a, b) begin
    a_shifted = {a[0], a[1], a[2], a[3]};
    b_shifted = {b[0], b[1], b[2], b[3]};

    if (a_shifted == b_shifted) begin
        equal = 1;
    end
    else begin
        equal = 0;
    end
end

endmodule
