module top_module( 
    input [99:0] in,
    output out_and,
    output out_or,
    output out_xor 
);

wire [19:0] and_out [4:0];
wire [19:0] or_out [4:0];
wire [19:0] xor_out [4:0];

// First pipeline stage
genvar i;
generate
    for (i = 0; i < 5; i = i + 1) begin : and_stage
        and_gate and_inst (
            .in(in[i*20 +: 20]),
            .out(and_out[i])
        );
    end
endgenerate

generate
    for (i = 0; i < 5; i = i + 1) begin : or_stage
        or_gate or_inst (
            .in(in[i*20 +: 20]),
            .out(or_out[i])
        );
    end
endgenerate

generate
    for (i = 0; i < 5; i = i + 1) begin : xor_stage
        xor_gate xor_inst (
            .in(in[i*20 +: 20]),
            .out(xor_out[i])
        );
    end
endgenerate

// Second pipeline stage
and_gate and_inst2 (
    .in(and_out),
    .out(out_and)
);

or_gate or_inst2 (
    .in(or_out),
    .out(out_or)
);

xor_gate xor_inst2 (
    .in(xor_out),
    .out(out_xor)
);

endmodule

