module random_number_generator (
  input clk,
  output reg [bit_width-1:0] rand
);

parameter seed = 1234; // initial seed value
parameter bit_width = 8; // number of bits in the random number

// Verilog code for the feedback function
reg [bit_width-1:0] lfsr;
integer i;

initial begin
  lfsr = seed;
end

always @(posedge clk) begin
  lfsr[0] = lfsr[bit_width-1] ^ lfsr[bit_width-2] ^ lfsr[bit_width-3] ^ lfsr[0];
  rand = lfsr[bit_width-1];

  for (i = bit_width-1; i > 0; i = i - 1) begin
    lfsr[i] = lfsr[i-1];
  end
end

endmodule

