module fsm_4bit_sequence_detection (
  input clk,
  input reset,
  input [3:0] data,
  output reg match
);

  reg [1:0] state;
  parameter S0 = 2'b00, S1 = 2'b01, S2 = 2'b10, S3 = 2'b11;

  always @(posedge clk) begin
    if (reset) begin
      state <= S0;
      match <= 0;
    end else begin
      case (state)
        S0: begin
          if (data == 4'b1_0__x) state <= S1;
          else state <= S0;
        end
        S1: begin
          if (data == 4'b1_0__x) state <= S1;
          else if (data == 4'b0_1__x) state <= S2;
          else state <= S0;
        end
        S2: begin
          if (data == 4'b1_0__x) state <= S1;
          else if (data == 4'b0_1__x) state <= S2;
          else if (data == 4'b1_0_1) state <= S3;
          else state <= S0;
        end
        S3: begin
          state <= S0;
          match <= 1;
        end
      endcase
    end
  end

