module glitch_filter (
  input clk,
  input reset,
  input data,
  output reg filtered_data
);

parameter time_window = 10; // time window for detecting glitches in clock cycles

reg [1:0] state; // state machine state
reg [1:0] prev_data; // previous data value
reg [3:0] glitch_count; // glitch counter

always @(posedge clk) begin
  if (reset) begin
    state <= 2'b00; // reset state
    filtered_data <= 1'b0;
    prev_data <= 1'b0;
    glitch_count <= 4'b0000;
  end else begin
    case (state)
      2'b00: begin // reset state
        filtered_data <= 1'b0;
        prev_data <= 1'b0;
        glitch_count <= 4'b0000;
        if (data != prev_data) begin
          state <= 2'b01; // transition to stable state
          prev_data <= data;
        end
      end
      2'b01: begin // stable state
        if (data != prev_data) begin
          state <= 2'b10; // transition to glitch state
          glitch_count <= 4'b0001;
        end
        prev_data <= data;
        filtered_data <= prev_data;
      end
      2'b10: begin // glitch state
        if (data == prev_data) begin
          state <= 2'b01; // transition to stable state
          filtered_data <= prev_data;
        end else if (glitch_count == time_window) begin
          state <= 2'b01; // transition to stable state
          filtered_data <= data;
        end else begin
          glitch_count <= glitch_count + 1;
        end
      end
    endcase
  end
end

endmodule

module Switch_Debounce_Synchronizer
#(
	parameter CLK_RATE_HZ = 50000000, // Hz
	parameter DEBOUNCE_TIME = 10000, // ns
	parameter SIG_OUT_INIT = 1'b0
)
(
	// Input  Signals (asynchronous)
	input      SIG_IN,

	// Output Signals (synchronized to CLK domain)
	output reg SIG_OUT,

	// System Signals
	input CLK
);

	localparam CLK_PERIOD_NS = 1000000000.0 / CLK_RATE_HZ;
	localparam DBNC_TICKS = DEBOUNCE_TIME / CLK_PERIOD_NS;
	localparam DBNC_COUNT_WIDTH = $clog2(DBNC_TICKS);
	localparam DBNC_COUNT_LOADVAL = DBNC_TICKS - 1;

	reg [1:0] dbnc_reg;
	reg [DBNC_COUNT_WIDTH-1:0] dbnc_count_reg;

	wire dbnc_transition;
	wire dbnc_count_done;

	initial begin
		dbnc_reg = 2'b11;
		dbnc_count_reg = DBNC_COUNT_LOADVAL;
		SIG_OUT = SIG_OUT_INIT;
	end

	CDC_Input_Synchronizer #(.SYNC_REG_LEN(1)) sw_synchronizer (
		.ASYNC_IN(SIG_IN),
		.SYNC_OUT(dbnc_reg[0]),
		.CLK(CLK)
	);

	assign dbnc_transition = dbnc_reg[1] ^ dbnc_reg[0];

	always @(posedge CLK) begin
		dbnc_reg <= {dbnc_reg[0], sw_synchronizer.SYNC_OUT};
	end

	always @(posedge CLK) begin
		if (dbnc_transition)
			dbnc_count_reg <= DBNC_COUNT_LOADVAL;
		else if (!dbnc_count_done)
			dbnc_count_reg <= dbnc_count_reg - 1'b1;
	end

	always @(posedge CLK) begin
		if (dbnc_count_done)
			SIG_OUT <= dbnc_reg[1];
	end

	assign dbnc_count_done = (dbnc_count_reg == 0);
endmodule

module shift_register_counter (
    input clk,
    input reset,      // Synchronous active-high reset
    input in,         // Input signal to be delayed
    input [3:0] delay, // Number of clock cycles to delay the input signal
    output [3:0] q    // 4-bit output from the functional module
);

    reg [3:0] counter = 4'd0;
    reg [3:0] shift_reg = 4'd0;
    wire [3:0] delayed_out;
    wire [3:0] counter_out;

    // Shift register with delay
    always @(posedge clk) begin
        if (reset) begin
            shift_reg <= 4'd0;
        end else begin
            shift_reg <= {in, shift_reg[3:1]};
        end
    end

    assign delayed_out = shift_reg[delay];

    // State machine counter
    always @(posedge clk) begin
        if (reset) begin
            counter <= 4'd0;
        end else begin
            counter <= counter + 1;
        end
    end

    assign counter_out = counter;

    // Functional module
    assign q = delayed_out | counter_out;

endmodule

module SensorFSM #(
  parameter DataWidth = 8
) (
  input                        Reset_n_i,
  input                        Clk_i,
  input                        Enable_i,
  output reg                   CpuIntr_o,
  output     [2*DataWidth-1:0] SensorValue_o,
  output reg                   MeasureFSM_Start_o,
  input                        MeasureFSM_Done_i,
  input     [DataWidth-1:0]    MeasureFSM_Byte0_i,
  input     [DataWidth-1:0]    MeasureFSM_Byte1_i,
  input [2*DataWidth-1:0]      ParamThreshold_i,
  input [2*DataWidth-1:0]      ParamCounterPreset_i
);

  // Sensor FSM
  localparam stDisabled   = 2'b00;
  localparam stIdle       = 2'b01;
  localparam stXfer       = 2'b10;
  localparam stNotify     = 2'b11;
  reg  [1:0]             SensorFSM_State;
  reg  [1:0]             SensorFSM_NextState;
  wire                   SensorFSM_TimerOvfl;
  reg                    SensorFSM_TimerPreset;
  reg                    SensorFSM_TimerEnable;
  wire                   SensorFSM_DiffTooLarge;
  reg                    SensorFSM_StoreNewValue;
  /////////////////////////////////////////////////////////////////////////////
  // Word Arithmetic
  // interconnecting signals
  wire [2*DataWidth-1:0] SensorValue;
  reg  [2*DataWidth-1:0] Word0;
  wire [2*DataWidth-1:0] AbsDiffResult;

  /////////////////////////////////////////////////////////////////////////////
  // FSM //////////////////////////////////////////////////////////////////////
  /////////////////////////////////////////////////////////////////////////////

  always @(negedge Reset_n_i or posedge Clk_i)
  begin
    if (!Reset_n_i)
    begin
      SensorFSM_State <= stDisabled;
    end
    else
    begin
      SensorFSM_State <= SensorFSM_NextState;
    end  
  end

  always @(SensorFSM_State, Enable_i, SensorFSM_TimerOvfl, MeasureFSM_Done_i, SensorFSM_DiffTooLarge)
  begin  // process SensorFSM_CombProc
    SensorFSM_NextState     = SensorFSM_State;
    // control signal default values
    SensorFSM_TimerPreset   = 1'b0;
    SensorFSM_TimerEnable   = 1'b0;
    MeasureFSM_Start_o      = 1'b0;
    SensorFSM_StoreNewValue = 1'b0;
    CpuIntr_o               = 1'b0;
    // next state and output logic
    case (SensorFSM_State)
      stDisabled: begin
        if (Enable_i == 1'b1)
        begin
          SensorFSM_TimerPreset   = 1'b1;
          SensorFSM_NextState     = stIdle;
        end
      end
      stIdle: begin
        if (Enable_i == 1'b0)
        begin
          SensorFSM_NextState     = stDisabled;
        end
        else
        if (SensorFSM_TimerOvfl == 1'b1)
        begin
          SensorFSM_NextState     = stXfer;
          MeasureFSM_Start_o      = 1'b1;
        end
        else
        begin
          SensorFSM_TimerEnable   = 1'b1;  // timer running
        end
      end
      stXfer: begin
        if (MeasureFSM_Done_i == 1'b1)
        begin
          SensorFSM_TimerPreset   = 1'b1;
          if (SensorFSM_DiffTooLarge == 1'b1)
          begin
            SensorFSM_NextState     = stNotify;
            SensorFSM_StoreNewValue = 1'b1;  // store new value
          end
          else
          begin
            SensorFSM_NextState     = stIdle;
          end
        end
      end
      stNotify: begin
        SensorFSM_TimerEnable   = 1'b1;  // timer running
        SensorFSM_NextState     = stIdle;
        CpuIntr_o               = 1'b1;  // notify CPU
      end
      default: begin
      end
    endcase
  end 

  /////////////////////////////////////////////////////////////////////////////
  // Word Arithmetic //////////////////////////////////////////////////////////
  /////////////////////////////////////////////////////////////////////////////

  reg [2*DataWidth-1:0] SensorFSM_Timer;

  always @(negedge Reset_n_i or posedge Clk_i)
  begin
    if (!Reset_n_i)
    begin
      SensorFSM_Timer <= 16'd0;
    end
    else
    begin
      if (SensorFSM_TimerPreset)
      begin
        SensorFSM_Timer <= ParamCounterPreset_i;
      end
      else if (SensorFSM_TimerEnable)
      begin
        SensorFSM_Timer <= SensorFSM_Timer - 1'b1;
      end
    end  
  end

  assign SensorFSM_TimerOvfl = (SensorFSM_Timer == 0) ? 1'b1 : 1'b0;

  assign SensorValue = {MeasureFSM_Byte1_i, MeasureFSM_Byte0_i};

  always @(negedge Reset_n_i or posedge Clk_i)
  begin
    if (!Reset_n_i)
    begin
      Word0 <= 16'd0;
    end
    else
    begin
      if (SensorFSM_StoreNewValue)
      begin
        Word0 <= SensorValue;
      end
    end  
  end

  wire [2*DataWidth   : 0] DiffAB;
  wire [2*DataWidth-1 : 0] DiffBA;
  assign DiffAB = {1'b0, SensorValue} - {1'b0, Word0};
  assign DiffBA =        Word0        -        SensorValue;
  assign AbsDiffResult = DiffAB[2*DataWidth] ? DiffBA : DiffAB[2*DataWidth-1 : 0];

  assign SensorFSM_DiffTooLarge = (AbsDiffResult > ParamThreshold_i) ? 1'b1 : 1'b0;

  assign SensorValue_o = Word0;

endmodule

module dual_port_ram (
    input clk,
    input rst_n,
    input write_en,
    input [3:0] write_addr,
    input [7:0] write_data,
    input read_en,
    input [3:0] read_addr,
    output reg [7:0] read_data
);

reg [7:0] ram0 [0:15];
reg [7:0] ram1 [0:15];

reg [7:0] ram0_data;
reg [7:0] ram1_data;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        read_data <= 8'hFF;
    end else begin
        if (read_en) begin
            ram0_data <= ram0[read_addr];
            ram1_data <= ram1[read_addr];
        end
        if (write_en) begin
            ram0[write_addr] <= write_data;
            ram1[write_addr] <= write_data;
        end
    end
end

always @(posedge clk) begin
    if (read_en) begin
        case (read_addr[3])
            1'b0: read_data <= ram0_data;
            1'b1: read_data <= ram1_data;
        endcase
    end
end

endmodule

