module snes_controller_adapter(
  input  wire        clock,
  input  wire        reset,
  // to gameboy
  input  wire  [1:0] button_sel,
  output wire  [3:0] button_data,
  // to controller
  input  wire        controller_data,
  output wire        controller_latch,
  output wire        controller_clock
);

  parameter WAIT_STATE = 0;
  parameter LATCH_STATE = 1;
  parameter READ_STATE = 2;

  reg   [1:0] state;
  reg   [3:0] button_index;
  reg  [15:0] button_state;

  /**
   * State transitions occur on the clock's positive edge.
   */
  always @(posedge clock) begin
    if (reset)
      state <= WAIT_STATE;
    else begin
      if (state == WAIT_STATE)
        state <= LATCH_STATE;
      else if (state == LATCH_STATE)
        state <= READ_STATE;
      else if (state == READ_STATE) begin
        if (button_index == 15)
          state <= WAIT_STATE;
      end
    end
  end

  /**
   * Button reading occurs on the negative edge to give
   * values from the controller time to settle.
   */
  always @(negedge clock) begin
    if (reset) begin
      button_index <= 4'b0;
      button_state <= 16'hFFFF;
    end else begin
      if (state == WAIT_STATE)
        button_index <= 4'b0;
      else if (state == READ_STATE) begin
        button_state[button_index] <= controller_data;
        button_index <= button_index + 1;
      end
    end
  end

  assign controller_latch = (state == LATCH_STATE) ? 1'b1 : 1'b0;
  assign controller_clock = (state == READ_STATE) ? clock : 1'b1;

  // button order is
  // B Y SELECT START UP DOWN LEFT RIGHT A X L R - - - -
  assign button_data =
    button_sel[0] == 1'b0 ? { button_state[7], button_state[6], button_state[4], button_state[5] } :
    button_sel[1] == 1'b0 ? { button_state[8], button_state[0], button_state[2], button_state[3] } : 4'b1111;

endmodule

module lemmings_fsm (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  input dig,
  output reg walk_left,
  output reg walk_right,
  output reg falling,
  output reg splattered
);

// State definitions
parameter IDLE = 2'b00;
parameter WALK_LEFT = 2'b01;
parameter WALK_RIGHT = 2'b10;
parameter DIG = 2'b11;

// State register and next state logic
reg [1:0] state, next_state;
always @ (posedge clk or negedge areset) begin
  if (areset == 0) begin
    state <= IDLE;
  end else begin
    state <= next_state;
  end
end

// Output logic
always @ (state) begin
  case (state)
    IDLE: begin
      walk_left <= 0;
      walk_right <= 0;
      falling <= 0;
      splattered <= 0;
    end
    WALK_LEFT: begin
      walk_left <= 1;
      walk_right <= 0;
      falling <= 0;
      splattered <= 0;
    end
    WALK_RIGHT: begin
      walk_left <= 0;
      walk_right <= 1;
      falling <= 0;
      splattered <= 0;
    end
    DIG: begin
      walk_left <= 0;
      walk_right <= 0;
      falling <= 1;
      splattered <= 0;
    end
  endcase
end

// State transition logic
always @ (state, bump_left, bump_right, ground, dig) begin
  case (state)
    IDLE: begin
      if (bump_left) begin
        next_state <= WALK_RIGHT;
      end else if (bump_right) begin
        next_state <= WALK_LEFT;
      end else if (!ground) begin
        next_state <= DIG;
      end else if (dig) begin
        next_state <= DIG;
      end else begin
        next_state <= IDLE;
      end
    end
    WALK_LEFT: begin
      if (bump_right) begin
        next_state <= WALK_RIGHT;
      end else if (!ground) begin
        next_state <= DIG;
      end else if (dig) begin
        next_state <= DIG;
      end else begin
        next_state <= WALK_LEFT;
      end
    end
    WALK_RIGHT: begin
      if (bump_left) begin
        next_state <= WALK_LEFT;
      end else if (!ground) begin
        next_state <= DIG;
      end else if (dig) begin
        next_state <= DIG;
      end else begin
        next_state <= WALK_RIGHT;
      end
    end
    DIG: begin
      if (!ground) begin
        next_state <= DIG;
      end else if (dig) begin
        next_state <= DIG;
      end else if (splattered) begin
        next_state <= IDLE;
      end else begin
        if (state == WALK_LEFT) begin
          next_state <= WALK_RIGHT;
        end else begin
          next_state <= WALK_LEFT;
        end
      end
    end
  endcase
end

// Splatter detection
reg [4:0] fall_counter;
always @ (posedge clk or negedge areset) begin
  if (areset == 0) begin
    fall_counter <= 0;
  end else begin
    if (!ground) begin
      fall_counter <= fall_counter + 1;
    end else begin
      fall_counter <= 0;
    end
  end
end
always @ (state, fall_counter) begin
  if (state == DIG && fall_counter >= 20) begin
    splattered <= 1;
  end else begin
    splattered <= 0;
  end
end

endmodule

module d_flipflop_with_setreset(input D, SET_B, VPWR, VGND, VPB, VNB, CLK,
                                output Q, Q_N);

    // Internal signals
    wire S;
    wire R;

    // Set/reset circuitry
    assign S = ~SET_B & VPB & VNB;
    assign R = SET_B & VPB & VNB;

    // D latch
    reg Q_reg;
    always @(posedge CLK)
    begin
        if (S) Q_reg <= 1'b1;
        else if (R) Q_reg <= 1'b0;
        else Q_reg <= D;
    end

    // Output
    assign Q = Q_reg;
    assign Q_N = ~Q_reg;

endmodule

module sky130_fd_sc_lp__a31oi (
