    //# {{power|Power}}
    input  VPB ,
    input  VPWR,
    input  VGND,
    input  VNB
);

// Declare internal wires
wire Y1, Y2, Y3;

// Implement logic
assign Y1 = A1;
assign Y2 = (A2 & !A3);
