module top_module (
    input clk,
    input reset, // Synchronous active-high reset
    input [31:0] a, // Input for adder module
    input [31:0] b, // Input for adder module
    input [31:0] c, // Input for multiplexer
    input [31:0] d, // Input for multiplexer
    input [7:0] in, // Input for priority encoder
    input [1:0] select, // Select inputs to choose between the four inputs of the multiplexer
    output reg [2:0] pos, // Output from priority encoder
    output reg [31:0] out // Output from active module and additional functional module
);

// Instantiate the adder module
adder_module adder_inst (
    .clk(clk),
    .reset(reset),
    .a(a),
    .b(b),
    .sum(out)
);

// Instantiate the priority encoder module
priority_encoder_module priority_encoder_inst (
    .in(in),
    .pos(pos)
);

// Multiplexer control logic
always @ (select, c, d) begin
    case (select)
        2'b00: out <= c;
