// Adder module with carry-lookahead architecture
module adder_module (
    input clk,
    input reset, // Synchronous active-high reset
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] sum
);

reg [31:0] p [0:30];
reg [31:0] g [0:30];
reg [31:0] c [0:31];

always @ (posedge clk) begin
    if (reset) begin
        sum <= 32'b0;
    end else begin
        p[0] <= a[0] ^ b[0];
        g[0] <= a[0] & b[0];
        c[0] <= g[0];
        sum[0] <= p[0];

        for (i = 1; i < 32; i = i + 1) begin
            p[i] <= a[i] ^ b[i] ^ c[i-1];
            g[i] <= (a[i] & b[i]) | (a[i] & c[i-1]) | (b[i] & c[i-1]);
            c[i] <= g[i] | (p[i] & c[i-1]);
            sum[i] <= p[i] ^ c[i-1];
        end
    end
end

endmodule

