module edge_detection (
    input clk,
    input reset,
    input a,
    input control,
    output reg rise,
    output reg down
);
reg [1:0] state;
parameter IDLE = 2'd0, RISE = 2'd1, DOWN = 2'd2;
always @(posedge clk, posedge reset) begin
    if(reset) begin
        state <= IDLE;
        rise <= 1'b0;
        down <= 1'b0;
    end else begin
        case(state)
            IDLE: begin
                if(control) begin
                    if(a) begin
                        state <= RISE;
                    end else begin
                        state <= DOWN;
                    end
                end
            end
            RISE: begin
                rise <= 1'b1;
                state <= IDLE;
            end
            DOWN: begin
                down <= 1'b1;
                state <= IDLE;
            end
            default: state <= IDLE;
        endcase
    end
end
endmodule

