  MUX2_X1 mux3 (.A(2'b01), .B(n4), .S(n9), .Z(prediction_o[0]));
  MUX2_X1 mux4 (.A(2'b00), .B(n1), .S(n10), .Z(prediction_o[0]));
  MUX2_X1 mux5 (.A(2'b10), .B(n2), .S(n12), .Z(prediction_o[1]));
  MUX2_X1 mux6 (.A(2'b11), .B(n3), .S(n13), .Z(prediction_o[1]));
  MUX2_X1 mux7 (.A(2'b01), .B(n4), .S(n14), .Z(prediction_o[1]));
  MUX2_X1 mux8 (.A(2'b00), .B(n1), .S(n11), .Z(prediction_o[1]));

  // Connect the next state to the flip-flops
  DFFR_X1 next_state_reg_0 (.D(next_state[0]), .CK(clock), .RN(reset), .Q(n1), .QN(n2));
  DFFR_X1 next_state_reg_1 (.D(next_state[1]), .CK(clock), .RN(reset), .Q(n3), .QN(n4));

endmodule

module bit_change_detector (
