module mux_4to1 (
    input [3:0] in0,
    input [3:0] in1,
    input [3:0] in2,
    input [3:0] in3,
    input [1:0] sel,
    input enable,
    output reg [3:0] out
);

always @(*) begin
    case (sel)
        2'b00: out = enable ? in0 : 4'b0;
        2'b01: out = enable ? in1 : 4'b0;
        2'b10: out = enable ? in2 : 4'b0;
        2'b11: out = enable ? in3 : 4'b0;
    endcase
end

endmodule

module accumulator (
  input clk, // clock signal
  input [15:0] data, // input data signal
  output reg [15:0] acc // accumulated value
);

  // Define a register to store the accumulated value
  reg [15:0] acc_reg;

  // Reset the accumulator to zero on power up or when a reset signal is received
  initial begin
    acc_reg <= 16'd0;
  end

  // On the rising edge of the clock signal, add the input data value to the previous accumulated value
  always @(posedge clk) begin
    acc_reg <= acc_reg + data;
  end

  // Output the accumulated value on each clock cycle
  assign acc = acc_reg;

endmodule

module mux_nand(
    input [3:0] sel,
    input [7:0] in0,
    input [7:0] in1,
    input [7:0] in2,
    input [7:0] in3,
    input [7:0] in4,
    input [7:0] in5,
    input [7:0] in6,
    input [7:0] in7,
    output reg out
);

reg [3:0] sel_reg;
reg [7:0] selected_vector;
wire [3:0] sel_inv;
wire [7:0] selected_vector_inv;
wire nand_out;

// 256-to-1 multiplexer
always @(*) begin
    case(sel)
        4'b0000: selected_vector = in0;
        4'b0001: selected_vector = in1;
        4'b0010: selected_vector = in2;
        4'b0011: selected_vector = in3;
        4'b0100: selected_vector = in4;
        4'b0101: selected_vector = in5;
        4'b0110: selected_vector = in6;
        4'b0111: selected_vector = in7;
        // default: selected_vector = 8'b0; // optional default case
    endcase
end

// Invert the selection input and the selected vector
assign sel_inv = ~sel;
assign selected_vector_inv = ~selected_vector;

// NAND gate
assign nand_out = ~(selected_vector_inv[0] & selected_vector_inv[1] & selected_vector_inv[2] & selected_vector_inv[3]);

// Final output module
always @(nand_out) begin
    if(nand_out) begin
        out = 1'b1;
    end else begin
        out = 1'b0;
    end
end

endmodule

module Multiplier(input CLK, input reset, input enable, input [7:0] input_num, output reg [15:0] output_num);

