module shift_reg_splitter_adder(
    input clk,
    input areset,  // async active-high reset to zero
    input load,
    input ena,
    input [3:0] data,
    input [15:0] in,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo,
    output wire [11:0] final_out);

    // 4-bit shift register with asynchronous reset, synchronous load, and enable
    reg [3:0] q;
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            q <= 4'b0;
        end else if (load) begin
            q <= data;
        end else if (ena) begin
            q <= {1'b0, q[3:1]};
        end
    end

    // 16-bit splitter using shift registers
    reg [7:0] shift_reg1, shift_reg2;
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            shift_reg1 <= 8'b0;
            shift_reg2 <= 8'b0;
        end else begin
            shift_reg1 <= {in[15], shift_reg1[7:1]};
            shift_reg2 <= {in[7:0], shift_reg2[7:1]};
        end
    end
    assign out_hi = shift_reg1;
    assign out_lo = shift_reg2;

    // Adder module to add the outputs of the shift register and the splitter
    wire [11:0] adder_out;
    assign adder_out = {4'b0, q} + {8'b0, shift_reg1} + {8'b0, shift_reg2};
    assign final_out = adder_out;

endmodule

module ripple_carry_adder(
  input [3:0] A,
  input [3:0] B,
  input carry_in,
  output [3:0] sum,
  output carry_out
);

  wire [3:0] carry_outs;
  wire [3:0] sums;

  // First full adder
  full_adder FA0(
    .a(A[0]),
    .b(B[0]),
    .c(carry_in),
    .sum(sums[0]),
    .carry_out(carry_outs[0])
  );

  // Second full adder
  full_adder FA1(
    .a(A[1]),
    .b(B[1]),
    .c(carry_outs[0]),
    .sum(sums[1]),
    .carry_out(carry_outs[1])
  );

  // Third full adder
  full_adder FA2(
    .a(A[2]),
    .b(B[2]),
    .c(carry_outs[1]),
    .sum(sums[2]),
    .carry_out(carry_outs[2])
  );

  // Fourth full adder
  full_adder FA3(
    .a(A[3]),
    .b(B[3]),
    .c(carry_outs[2]),
    .sum(sums[3]),
    .carry_out(carry_out)
  );

  assign sum = sums;

endmodule

