module traffic_light_controller (
  input clk,
  input reset,
  input pedestrian_crossing,
  input timer_expired,
  output reg green_light,
  output reg yellow_light,
  output reg red_light
);

  // Define the states of the FSM
  localparam IDLE = 2'b00;
  localparam GREEN = 2'b01;
  localparam YELLOW = 2'b10;
  localparam RED = 2'b11;

  // Define the current state and next state variables
  reg [1:0] current_state;
  reg [1:0] next_state;

  // Define the timer counter
  reg [3:0] timer_counter;

  // Define the output signals for each state
  assign green_light = (current_state == GREEN) ? 1'b1 : 1'b0;
  assign yellow_light = (current_state == YELLOW) ? 1'b1 : 1'b0;
  assign red_light = (current_state == RED) ? 1'b1 : 1'b0;

  // Define the state transition logic
  always @(posedge clk, posedge reset) begin
    if (reset) begin
      current_state <= IDLE;
      timer_counter <= 0;
    end else begin
      current_state <= next_state;
      if (current_state == YELLOW) begin
        timer_counter <= timer_counter + 1;
      end else begin
        timer_counter <= 0;
      end
    end
  end

  // Define the next state logic
  always @(*) begin
    case (current_state)
      IDLE: begin
        if (pedestrian_crossing) begin
          next_state = RED;
        end else if (timer_expired) begin
          next_state = YELLOW;
        end else begin
          next_state = GREEN;
        end
      end
      GREEN: begin
        if (pedestrian_crossing) begin
          next_state = RED;
        end else if (timer_expired && timer_counter < 10) begin
          next_state = YELLOW;
        end else if (timer_counter == 10) begin
          next_state = RED;
        end else begin
          next_state = GREEN;
        end
      end
      YELLOW: begin
        if (pedestrian_crossing) begin
          next_state = RED;
        end else if (timer_counter == 3) begin
          next_state = RED;
        end else begin
          next_state = YELLOW;
        end
      end
      RED: begin
        if (pedestrian_crossing) begin
          next_state = RED;
        end else if (timer_counter == 10) begin
          next_state = GREEN;
        end else begin
          next_state = RED;
        end
      end
    endcase
  end

endmodule

