module binary_adder(
    input [7:0] a,
    input [7:0] b,
    output [7:0] sum,
    output carry_out
);
    genvar i;
    wire [7:0] carry;
    assign carry[0] = 1'b0;
    generate
        for (i = 1; i < 8; i = i + 1) begin : gen_adder
            full_adder adder (.a(a[i]), .b(b[i]), .carry_in(carry[i-1]), .sum(sum[i]), .carry_out(carry[i]));
        end
    endgenerate
    assign carry_out = carry[7];
endmodule

module full_adder(
    input a,
    input b,
    input carry_in,
    output sum,
    output carry_out
);
    assign {carry_out, sum} = a + b + carry_in;
endmodule

