   input we_i, input stb_i, input cyc_i, output reg ack_o,
   input run_rx, input run_tx,
   output [31:0] ctrl_lines);

   reg [1:0] state;
   reg [31:0] audio_ram [0:15];  // DP distributed RAM

   wire [1:0] sel_int = { (sel_i[1] & adr_i[1]), (sel_i[0] & adr_i[1]),
