module top_module(
    input clk,
    input load,
    input [1:0] ena,
    input a,
    input b,
    input [15:0] data,
    output reg [15:0] q,
    output out,
    output [15:0] result);

    // 3-input NOR gate constructed with NAND gates
    wire nand1, nand2, nand3, nand4, nand5, nand6, nor;
    assign nand1 = ~(a & b);
    assign nand2 = ~(a & nand1);
    assign nand3 = ~(b & nand1);
    assign nand4 = ~(nand2 & nand3);
    assign nand5 = ~(nand4 & nand4);
    assign nand6 = ~(nand5 & nand5);
    assign nor = ~(nand6 & nand6);

    // 16-bit barrel shifter with synchronous load input
    reg [15:0] shift_reg;
    always @(posedge clk) begin
        if (load) begin
            shift_reg <= data;
        end else begin
            case (ena)
                2'b00: shift_reg <= {shift_reg[14:0], shift_reg[15]};
                2'b01: shift_reg <= {shift_reg[13:0], shift_reg[15:14]};
                2'b10: shift_reg <= {shift_reg[1:15], shift_reg[0]};
                2'b11: shift_reg <= {shift_reg[2:15], shift_reg[0:1]};
            endcase
        end
    end

    // Bitwise OR operation module
    assign result = shift_reg | nor;

    // Output signals
    assign q = shift_reg;
    assign out = nor;

endmodule

module transition_detection (
    input clk,
    input reset,
    input [15:0] in,
    output reg out
);

reg [15:0] prev_in;
reg [15:0] curr_in;

wire transition;
wire is_multiple_of_5;

assign transition = (prev_in ^ curr_in) & curr_in[0];
assign is_multiple_of_5 = (in % 5 == 0);

always @(posedge clk) begin
    if (reset) begin
        prev_in <= 16'b0;
        curr_in <= 16'b0;
        out <= 1'b0;
    end else begin
        prev_in <= curr_in;
        curr_in <= in;
        if (transition) begin
            if (is_multiple_of_5) begin
                out <= 1'b0;
            end else begin
                out <= 1'b1;
            end
        end
    end
end

endmodule

