module Memory_Testing_Block (
  input [n-1:0] addr,
  input [m-1:0] data,
  input [k-1:0] control,
  output [m-1:0] data_out,
  output flag
);

parameter n = 8; // number of address signals
parameter m = 16; // number of data signals
parameter k = 4; // number of control signals

reg [m-1:0] memory [2**n-1:0]; // memory array

reg write_enable;
reg read_enable;
reg reset;

integer i;

// Write test pattern to memory
always @(posedge control[0]) begin
  if (write_enable) begin
    for (i = 0; i < 2**n; i = i + 1) begin
      memory[i] <= data;
    end
  end
end

// Read data from memory and compare with test pattern
always @(posedge control[1]) begin
  if (read_enable) begin
    flag <= 1;
    for (i = 0; i < 2**n; i = i + 1) begin
      if (memory[i] != data_out) begin
        flag <= 0;
      end
    end
  end
end

// Control signals
assign write_enable = control[2];
assign read_enable = control[3];
assign reset = control[4];

// Memory address decoding
wire [n-1:0] addr_decoded;
assign addr_decoded = addr;

// Memory read and write operations
assign data_out = memory[addr_decoded];

always @(posedge control[2]) begin
  if (write_enable) begin
    memory[addr_decoded] <= data;
  end
end

endmodule

module dma_tester(

    input  wire        clk,

    input  wire        can_go,


    output reg         req,
    output reg         rnw,
    output reg   [7:0] wd,
    output reg  [20:0] addr,

    input  wire        ack,
    input  wire        done,
    input  wire  [7:0] rd
);
    parameter BEG_ADDR = 21'h00C000;
    parameter BLK_SIZE = 21'd004096;

    // Burst generator
    reg [3:0] burst_count;
    reg [3:0] pause_count;
    reg [3:0] burst_length;
    reg [7:0] data [15:0];
    reg        idle;
    reg        burst_done;
    reg        first_burst;
    reg        mem_error;

    // DMA Controller Interface
    reg        dma_can_go;
    reg        dma_rnw;
    reg  [7:0] dma_rd;
    reg  [7:0] dma_wd;
    reg  [20:0] dma_addr;
    wire       dma_req;
    wire       dma_ack;
    wire       dma_done;

    // Random number generation
    `define RND_PAUSE (8'd20 + ( 8'd63 & ($random>>20)))
    `define RND_BURST (8'd1 + ( 8'd15 & ($random>>20)))

    // Assign DMA controller interface signals
    assign dma_req = req;
    assign dma_rnw = rnw;
    assign dma_wd  = wd;
    assign dma_addr = addr;
    assign dma_ack = ack;
    assign dma_done = done;

    // DMA controller interface
    always @(posedge clk) begin
        dma_can_go <= can_go;
        dma_rd <= rd;
    end

    // Burst generator
    always @(posedge clk) begin
        if (dma_can_go) begin
            if (dma_req && !burst_done) begin
                if (idle) begin
                    // Start new burst
                    burst_length <= `RND_BURST;
                    pause_count <= `RND_PAUSE;
                    burst_count <= burst_length - 1;
                    first_burst <= 1'b1;
                    idle <= 1'b0;
                end else begin
                    // Continue existing burst
                    if (burst_count == 0) begin
                        burst_done <= 1'b1;
                        pause_count <= `RND_PAUSE;
                    end else begin
                        burst_count <= burst_count - 1;
                    end
                end
            end else if (dma_ack) begin
                if (!burst_done) begin
                    if (dma_rnw) begin
                        // Read data
                        if (first_burst) begin
                            mem_error <= 1'b0;
                            data[0] <= $random;
                        end else begin
                            if (data[burst_length - burst_count - 1] != dma_rd) begin
                                $display("Error: readback data mismatch at address %h. Expected %h, got %h.", dma_addr, data[burst_length - burst_count - 1], dma_rd);
                                mem_error <= 1'b1;
                            end
                        end
                    end else begin
                        // Write data
                        data[burst_length - burst_count - 1] <= dma_wd;
                    end
                    if (burst_count == 0) begin
                        burst_done <= 1'b1;
                        pause_count <= `RND_PAUSE;
                    end else begin
                        burst_count <= burst_count - 1;
                    end
                end else begin
                    if (pause_count == 0) begin
                        burst_done <= 0;
                        idle <= 1'b1;
                    end else begin
                        pause_count <= pause_count - 1;
                    end
                end
            end
        end else begin
            burst_done <= 1'b1;
            pause_count <= `RND_PAUSE;
            idle <= 1'b1;
        end
    end

    // Address generation
    always @(posedge clk) begin
        if (!dma_can_go) begin
            addr <= BEG_ADDR;
            rnw <= 1'b1;
        end else if (dma_ack && !burst_done) begin
            if (addr >= (BEG_ADDR+BLK_SIZE-1)) begin
                addr <= BEG_ADDR;
                rnw <= ~rnw;
            end else begin
                addr <= addr + 21'd1;
            end
        end
    end

    // Output control
    always @(posedge clk) begin
        if (dma_can_go) begin
            req <= !burst_done;
            wd <= data[burst_length - burst_count - 1];
        end else begin
            req <= 1'b0;
        end
    end

endmodule

module SendCommand
( input Clk,
  output reg [7:0] SendData,
  output reg SendReq,
  input SendAck,
  input [5:0] Command,
  input [31:0] Args,
  input [6:0] CRC,
  input CmdSend,
  output reg CmdAck
);

  integer Status;
  integer Count;
  reg [7:0] Buffer [5:0];

  initial
    begin
	   Status = 0;
		SendData = 8'hFF;
		SendReq = 0;
		CmdAck = 0;
	 end

  always @(posedge Clk)
    begin
	   case(Status)
		  0: begin
		       if (CmdSend == 1) Status = 1;
				 else Status = 0;
		     end
		  1: begin
		       Buffer[0] = {1'b0, 1'b1, Command};
				 Buffer[1] = Args[31:24];
				 Buffer[2] = Args[23:16];
				 Buffer[3] = Args[15:8];
				 Buffer[4] = Args[7:0];
				 Buffer[5] = {CRC, 1'b1};
				 CmdAck = 1;
				 Count = 0;
				 Status = 2;
		     end
		  2: begin
				 if (SendAck == 0)
				   begin
					  SendData = Buffer[Count];
					  SendReq = 1;
					  Status = 3;
					end
				 else Status = 2;
		     end
		  3: begin
		       if (SendAck == 1)
				   begin
					  SendReq = 0;
					  Status = 4;
					end
				 else Status = 3;
		     end
		  4: begin
		       if (Count < 5)
				   begin
					  Count = Count + 1;
					  Status = 2;
					end
				 else Status = 5;
           end
		  5: begin
		       if (SendAck == 0)
				   begin
					  CmdAck = 0;
					  Status = 0;
					end
				 else Status = 5;
		     end
		endcase
	 end

endmodule

