module fifo_buffer(
  input clk,
  input rst,
  input [71:0] din,
  input wr_en,
  input rd_en,
  output [71:0] dout,
  output full,
  output empty,
  output prog_full
);

// Define the FIFO depth
localparam DEPTH = 128;

// Define the width of the pointers and counters
localparam WIDTH = $clog2(DEPTH);

// Define the FIFO memory
reg [71:0] fifo_mem [0:DEPTH-1];

// Define the write and read pointers
reg [WIDTH-1:0] wr_ptr;
reg [WIDTH-1:0] rd_ptr;

// Define the full and empty flags
reg full;
reg empty;

// Define the programmable flag
reg prog_full;

// Define the write and read enable signals
reg wr_en_int;
reg rd_en_int;

// Define the output data
wire [71:0] dout;

// Define the FIFO write logic
always @(posedge clk, posedge rst) begin
  if (rst) begin
    wr_ptr <= 0;
    full <= 0;
    wr_en_int <= 0;
  end else begin
    if (wr_en) begin
      if (!full) begin
        fifo_mem[wr_ptr] <= din;
        wr_ptr <= wr_ptr + 1;
        if (wr_ptr == DEPTH) begin
          wr_ptr <= 0;
        end
        if (wr_ptr == rd_ptr) begin
          full <= 1;
        end
      end else begin
        wr_en_int <= 1;
      end
    end else begin
      wr_en_int <= 0;
    end
  end
end

// Define the FIFO read logic
always @(posedge clk, posedge rst) begin
  if (rst) begin
    rd_ptr <= 0;
    empty <= 1;
    rd_en_int <= 0;
  end else begin
    if (rd_en) begin
      if (!empty) begin
        dout <= fifo_mem[rd_ptr];
        rd_ptr <= rd_ptr + 1;
        if (rd_ptr == DEPTH) begin
          rd_ptr <= 0;
        end
        if (rd_ptr == wr_ptr) begin
          empty <= 1;
        end
      end else begin
        rd_en_int <= 1;
      end
    end else begin
      rd_en_int <= 0;
    end
  end
end

// Define the full and empty flags
assign full = (wr_ptr == rd_ptr) && (wr_en_int == 1);
assign empty = (wr_ptr == rd_ptr) && (rd_en_int == 0);

// Define the programmable flag
assign prog_full = (wr_ptr >= (DEPTH - 2));

endmodule

module spiseq(
  input [3:0] spiclkcounter,
  input spien,
  input mode,
  output addrt,
  output spioe,
  output rdt,
  output rdld,
  output wrt,
  output modet
);

  reg modetreg;
  reg addrtreg;
  reg rdtreg;
  reg wrtreg;
  reg rdldreg;
  reg spioereg;

  assign modet = modetreg;
  assign addrt = addrtreg;
  assign rdt = rdtreg;
  assign wrt = wrtreg;
  assign rdld = rdldreg;
  assign spioe = spioereg;

  always @(*) begin
    modetreg = 0;
    rdtreg = 0;
    addrtreg = 0;
    wrtreg = 0;
    rdldreg = 0;
    spioereg = spien & mode;

    case(spiclkcounter)
      4'h0:
        modetreg <= 1; // Signal to load mode register

      4'h1, 4'h2, 4'h3, 4'h4:
      	addrtreg <= spien; // Signal to load address register

      4'h5, 4'h6, 4'h7:
        rdtreg <= (mode & spien); // Signal to indicate read transaction

      4'h8:
        begin
          rdtreg <= (mode & spien); // Signal to indicate read transaction
          rdldreg <= (mode & spien); // Load shift register
          wrtreg <= (~mode & spien); // Signal to indicate write transaction  
        end

      4'h9, 4'ha, 4'hb, 
      4'hc, 4'hd, 4'he, 4'hf:
        wrtreg <= (~mode & spien); // Signal to indicate write transaction

      default:
        begin
          rdtreg <= 1'bx;
          wrtreg <= 1'bx;
          addrtreg <= 1'bx;
          modetreg <= 1'bx;
          rdldreg <= 1'bx;
        end   
    endcase
  end
endmodule

module PWMModule (
    input clock,
    input reset,
    input [7:0] dutyCycle,
    output reg pwm,
    output reg done
);

    reg [23:0] counter = 0;
    reg [7:0] threshold = 0;
    reg [7:0] duty = 0;

    always @(posedge clock) begin
        if (reset) begin
            counter <= 0;
            threshold <= 0;
            duty <= 0;
            pwm <= 0;
            done <= 0;
        end else begin
            // calculate threshold based on duty cycle
            duty <= dutyCycle;
            threshold <= (256 * (duty / 100)) - 1;

            // increment counter and reset at end of cycle
            if (counter == 999) begin
                counter <= 0;
                done <= 1;
            end else begin
                counter <= counter + 1;
                done <= 0;
            end

            // set pwm value based on counter and threshold
            if (counter < threshold) begin
                pwm <= 1;
            end else begin
                pwm <= 0;
            end
        end
    end

endmodule

