module top_module (
    input [3:0] ABCD, // 4-bit input
    input [7:0] inputs, // 8-bit input for priority encoder
    output reg [7:0] final_output // 8-bit output from decoder and encoder
);

    wire [15:0] decoder_output;
    wire [7:0] encoder_output;

    // Instantiate the 4-to-16 decoder module
    decoder_4to16 decoder (
        .in(ABCD),
        .out(decoder_output)
    );

    // Instantiate the 8-bit priority encoder module
    priority_encoder_8bit encoder (
        .in(inputs),
        .out(encoder_output)
    );

    // Concatenate the decoder and encoder outputs to get the final output
    always @(*) begin
        case (decoder_output)
            16'b0000000000000001: final_output = {encoder_output, 1'b0, 1'b0, 1'b0};
            16'b0000000000000010: final_output = {1'b0, encoder_output, 1'b0, 1'b0};
            16'b0000000000000100: final_output = {1'b0, 1'b0, encoder_output, 1'b0};
            16'b0000000000001000: final_output = {1'b0, 1'b0, 1'b0, encoder_output};
            default: final_output = 8'b00000000;
        endcase
    end

endmodule

// 4-to-16 decoder module
module decoder_4to16 (
    input [3:0] in,
    output reg [15:0] out
);

    always @(*) begin
        case (in)
            4'b0000: out = 16'b0000000000000001;
            4'b0001: out = 16'b0000000000000010;
            4'b0010: out = 16'b0000000000000100;
            4'b0011: out = 16'b0000000000001000;
            4'b0100: out = 16'b0000000000010000;
            4'b0101: out = 16'b0000000000100000;
            4'b0110: out = 16'b0000000001000000;
            4'b0111: out = 16'b0000000010000000;
            4'b1000: out = 16'b0000000100000000;
            4'b1001: out = 16'b0000001000000000;
            4'b1010: out = 16'b0000010000000000;
            4'b1011: out = 16'b0000100000000000;
            4'b1100: out = 16'b0001000000000000;
            4'b1101: out = 16'b0010000000000000;
            4'b1110: out = 16'b0100000000000000;
            4'b1111: out = 16'b1000000000000000;
        endcase
    end

endmodule

// 8-bit priority encoder module
module priority_encoder_8bit (
    input [7:0] in,
    output reg [7:0] out
);

    always @(*) begin
        casez (~in)
            8'b11111110: out = 8'b00000001;
            8'b11111101: out = 8'b00000010;
            8'b11111011: out = 8'b00000100;
            8'b11110111: out = 8'b00001000;
            8'b11101111: out = 8'b00010000;
            8'b11011111: out = 8'b00100000;
            8'b10111111: out = 8'b01000000;
            8'b01111111: out = 8'b10000000;
            default: out = 8'b00000000;
        endcase
    end

endmodule

