module carry_lookahead_adder(
    input [31:0] a,
    input [31:0] b,
    output [31:0] sum
);
    wire [31:0] g;
    wire [31:0] p;
    wire [31:0] c;

    assign g = a & b;
    assign p = a ^ b;
    assign c[0] = 1'b0;
    generate
        genvar i;
        for (i = 1; i < 32; i = i + 1) begin : gen
            assign c[i] = (g[i-1] | (p[i-1] & c[i-1]));
        end
    endgenerate
    assign sum = p ^ c;
endmodule

