module priority_encoder_pipeline (
    input [7:0] in1,
    input [7:0] in2,
    output reg [2:0] pos );

    reg [7:0] in_reg1, in_reg2;
    reg [3:0] stage1_out, stage2_out, stage3_out;

    always @(posedge clk) begin
        in_reg1 <= in1;
        in_reg2 <= in2;
    end

    // Stage 1
    always @* begin
        if (in_reg1[7]) stage1_out = 7;
        else if (in_reg1[6]) stage1_out = 6;
        else if (in_reg1[5]) stage1_out = 5;
        else if (in_reg1[4]) stage1_out = 4;
        else stage1_out = 3;
    end

    // Stage 2
    always @* begin
        if (in_reg2[7]) stage2_out = 7;
        else if (in_reg2[6]) stage2_out = 6;
        else if (in_reg2[5]) stage2_out = 5;
        else if (in_reg2[4]) stage2_out = 4;
        else stage2_out = 3;
    end

    // Stage 3
    always @* begin
        if (stage1_out < stage2_out) stage3_out = stage1_out;
        else stage3_out = stage2_out;
    end

    always @(posedge clk) begin
        pos <= stage3_out;
    end

endmodule

module checksum (
  input [n-1:0] data,
  output [m-1:0] chksum
);

parameter n = 8; // number of data words
parameter m = 16; // number of bits in each data word

reg [m-1:0] sum; // register to hold the sum of the data words

// compute the sum of the data words
always @ (data) begin
  sum = 0;
  for (i = 0; i < n; i = i + 1) begin
    sum = sum + data[i];
  end
end

// compute the checksum by taking the sum modulo 2^m
assign chksum = sum % (1 << m);

endmodule

module blk_mem_gen_v8_3_4_softecc_output_reg_stage
  #(parameter C_DATA_WIDTH          = 32,
    parameter C_ADDRB_WIDTH         = 10,
    parameter C_HAS_SOFTECC_OUTPUT_REGS_B= 0,
    parameter C_USE_SOFTECC         = 0,
    parameter FLOP_DELAY            = 100
  )
  (
   input                         CLK,
   input      [C_DATA_WIDTH-1:0] DIN,
   output reg [C_DATA_WIDTH-1:0] DOUT,
   input                         SBITERR_IN,
   input                         DBITERR_IN,
