reg [31:0] edge_detect;

always @(posedge clk) begin
    if (reset) begin
        shift_reg <= 0;
        prev_reg <= 0;
        edge_detect <= 0;
    end
    else begin
        shift_reg <= {shift_reg[30:0], in[31]};
        prev_reg <= shift_reg;
        edge_detect <= (shift_reg & ~prev_reg);
    end
end

assign out = edge_detect;

