module output_shaper_core (
	input wire d,
	input wire [3:0] hightime,
	input wire [3:0] deadtime,
	input wire CLK,
	output wire pulse,
	output wire gate_closed,
	input wire reset);

	reg closed;
	reg signal_entered;
	reg output_pulse;

	wire delay_hightime;
	wire delay_deadtime;

	reg hightime_reset;
	reg deadtime_reset;

	// handle asynchronous reset
	always @(posedge CLK or posedge reset) begin
		if (reset) begin
			hightime_reset <= 1'b1;
			deadtime_reset <= 1'b1;
			closed <= 1'b0;
			signal_entered <= 1'b0;
			output_pulse <= 1'b0;
		end else begin
			hightime_reset <= delay_hightime;
			deadtime_reset <= delay_deadtime;
			if (d) signal_entered <= 1'b1; else signal_entered <= 1'b0;
			if (hightime_reset) output_pulse <= 1'b0;
			else if (signal_entered) output_pulse <= 1'b1;
			if (deadtime_reset) closed <= 1'b0;
			else if (signal_entered) closed <= 1'b1;
		end
	end

	assign pulse = output_pulse;
	assign gate_closed = signal_entered || closed;

	SRL16 #(.INIT(16'h0000)) HIGHTIME_DELAY (
			.D(signal_entered),
			.A0(hightime[0]),	.A1(hightime[1]),	.A2(hightime[2]),	.A3(hightime[3]),     
			.CLK(CLK),
			.Q(delay_hightime));
	SRL16 #(.INIT(16'h0000)) DEADTIME_DELAY (
			.D(delay_hightime),
			.A0(deadtime[0]),	.A1(deadtime[1]),	.A2(deadtime[2]),	.A3(deadtime[3]),     
			.CLK(CLK),
			.Q(delay_deadtime));

endmodule

