module FloatingPointMultiplier (input [31:0] a, input [31:0] b, output [31:0] result, output overflow, output underflow);

  wire [36:0] SFPU_OUT;
  wire zero;
  wire sign;
  wire orlow;
  wire [9:0] exponent;
  wire [9:0] expoh;
  wire [9:0] expol;
  wire [1:0] restlow;
  wire [1:0] resthigh;

  SFPU_MUL SFPU_MUL_inst(.SRC1(a), .SRC2(b), .MRESULT(SFPU_OUT), .NZEXP({1'b1, 1'b1}), .OUT());

  assign zero = ~(a[30:23] | b[30:23]);
  assign sign = (a[31] ^ b[31]) & ~zero;
  assign orlow = (SFPU_OUT[21:0] != 22'b0);
  assign restlow = {SFPU_OUT[22], orlow};
  assign resthigh = {SFPU_OUT[23], (SFPU_OUT[22] | orlow)};
  assign exponent = {2'b00, a[30:23]} + {2'b00, b[30:23]};
  assign expoh = exponent - 10'h07E;
  assign expol = exponent - 10'h07F;

  assign result = SFPU_OUT[47] ? {zero, sign, expoh, SFPU_OUT[46:24], resthigh}
                               : {zero, sign, expol, SFPU_OUT[45:23], restlow};

  assign overflow = (exponent > 10'h7F);
  assign underflow = (exponent < 10'h01);

endmodule

module binary_divider (
    input [15:0] dividend,
    input [15:0] divisor,
    output reg [15:0] quotient,
    output reg [15:0] remainder
);

reg [15:0] dividend_reg;
reg [15:0] divisor_reg;
reg [15:0] quotient_reg;
reg [15:0] remainder_reg;

reg [3:0] count;

always @(*) begin
    dividend_reg = dividend;
    divisor_reg = divisor;
end

always @(posedge clk) begin
    if (count == 0) begin
        quotient_reg <= 0;
        remainder_reg <= dividend_reg;
    end else begin
        if (remainder_reg[15] == 1) begin
            remainder_reg <= (remainder_reg << 1) | 1;
        end else begin
            remainder_reg <= remainder_reg << 1;
        end
        quotient_reg <= quotient_reg << 1;
        if (remainder_reg >= divisor_reg) begin
            remainder_reg <= remainder_reg - divisor_reg;
            quotient_reg <= quotient_reg | 1;
        end
    end
    count <= count + 1;
end

assign quotient = quotient_reg;
assign remainder = remainder_reg;

endmodule

