module regfile (regA, regB, Wdat, regW, RegWrite, DualWrite, clk, resetn, Adat, Bdat, regTEST, TESTdat);
    input clk, RegWrite, resetn, DualWrite;		// write enable
    input [4:0] regA, regB, regW, regTEST;	// source/dest register address
    input [31:0] Wdat;			// data writing to dest
    output wire [31:0] Adat, Bdat, TESTdat;		// data read from source
    reg [31:0] regfile [0:31];
    reg [5:0] i;
    assign Adat = regfile[regA];
    assign Bdat = regfile[regB];
    assign TESTdat = regfile[regTEST];

    always @(posedge clk) begin
        //Deal with asynchronized Reset signal
        if (~resetn) begin
            for (i = 0; i < 32; i = i + 1) begin
                regfile[i] = 0;
            end
        end else begin
            if (DualWrite) begin
                regfile[regW] <= Wdat;
                Adat <= regfile[regA];
                Bdat <= regfile[regB];
            end else begin
                if (RegWrite) begin
                    regfile[regW] <= (regW == 0) ? 32'b0 : Wdat;
                end
                Adat <= regfile[regA];
                Bdat <= regfile[regB];
            end
        end
    end
