module cmd_seq_core #(
    parameter CMD_MEM_SIZE = 2048,
    parameter ABUSWIDTH = 16,
    parameter OUTPUTS = 1
) (
    input wire                  BUS_CLK,
    input wire                  BUS_RST,
    input wire  [ABUSWIDTH-1:0] BUS_ADD,
    input wire  [7:0]           BUS_DATA_IN,
    input wire                  BUS_RD,
    input wire                  BUS_WR,
    output wire [7:0]           BUS_DATA_OUT,

    output wire [OUTPUTS-1:0]   CMD_CLK_OUT,
    input wire                  CMD_CLK_IN,
    input wire                  CMD_EXT_START_FLAG,
    output wire                 CMD_EXT_START_ENABLE,
    output wire [OUTPUTS-1:0]   CMD_DATA,
    output wire                 CMD_READY,
    output wire                 CMD_START_FLAG
);

reg [7:0] mem [CMD_MEM_SIZE-1:0];
reg [ABUSWIDTH-1:0] addr;
reg [OUTPUTS-1:0] data;
reg start_flag;
reg ready;
reg ext_start_enable;
reg [OUTPUTS-1:0] clk_out;

integer i;

always @(posedge BUS_CLK) begin
    if (BUS_RST) begin
        addr <= 0;
        data <= 0;
        start_flag <= 0;
        ready <= 0;
        ext_start_enable <= 0;
        for (i=0; i<OUTPUTS; i=i+1) begin
            clk_out[i] <= 0;
        end
    end else begin
        if (BUS_WR) begin
            mem[BUS_ADD - BASEADDR] <= BUS_DATA_IN;
        end
        if (BUS_RD) begin
            BUS_DATA_OUT <= mem[BUS_ADD - BASEADDR];
        end
        if (CMD_EXT_START_FLAG) begin
            ext_start_enable <= 1;
        end
        if (ext_start_enable && !start_flag) begin
            start_flag <= 1;
            ready <= 0;
            addr <= BASEADDR;
        end
        if (start_flag) begin
            if (CMD_CLK_IN) begin
                clk_out <= ~clk_out;
                if (clk_out == (1 << OUTPUTS) - 1) begin
                    addr <= addr + 1;
                end
            end
            for (i=0; i<OUTPUTS; i=i+1) begin
                data[i] <= mem[addr - BASEADDR][i];
            end
            if (addr == HIGHADDR) begin
                start_flag <= 0;
                ready <= 1;
            end
        end
    end
end

assign CMD_EXT_START_ENABLE = ext_start_enable;
assign CMD_DATA = data;
assign CMD_READY = ready;
assign CMD_START_FLAG = start_flag;
assign CMD_CLK_OUT = clk_out;

endmodule

module fifo (
    // Inputs
    input mclk,
    input puc_rst,
    input [15:0] fifo_data_i,
    input fifo_enable_i,
    input fifo_push_i,
    input fifo_pop_i,
    // Outputs
    output reg [3:0] fifo_cnt_o,
    output reg [3:0] fifo_empty_cnt_o,
    output reg [15:0] fifo_data_o,
    output reg fifo_done_evt_o,
    output reg fifo_empty_o,
    output reg fifo_full_o,
    output reg fifo_ovfl_evt_o
);

// Parameter declaration
parameter FIFO_EMPTY = 4'h0;
parameter FIFO_FULL = 4'hf;

// Registers and wires
reg [15:0] fifo_mem [0:15];
reg [3:0] wr_ptr;
reg [3:0] rd_ptr;
reg [3:0] fifo_cnt_nxt;
wire fifo_push_int;
wire fifo_pop_int;

// Counter logic
assign fifo_full_o = (fifo_cnt_o == FIFO_FULL);
assign fifo_empty_o = (fifo_cnt_o == FIFO_EMPTY);
assign fifo_empty_cnt_o = (FIFO_FULL - fifo_cnt_o);
assign fifo_done_evt_o = ~fifo_empty_o & (fifo_cnt_nxt == FIFO_EMPTY);
assign fifo_ovfl_evt_o = fifo_push_i & fifo_full_o;

// Write pointer
always @(posedge mclk or posedge puc_rst) begin
    if (puc_rst) begin
        wr_ptr <= 4'h0;
    end else if (~fifo_enable_i) begin
        wr_ptr <= 4'h0;
    end else if (fifo_push_int) begin
        if (wr_ptr == (FIFO_FULL - 1)) begin
            wr_ptr <= 4'h0;
        end else begin
            wr_ptr <= wr_ptr + 4'h1;
        end
    end
end

// Memory logic
always @(posedge mclk or posedge puc_rst) begin
    if (puc_rst) begin
        fifo_mem[0] <= 16'h0000;
        fifo_mem[1] <= 16'h0000;
        fifo_mem[2] <= 16'h0000;
        fifo_mem[3] <= 16'h0000;
        fifo_mem[4] <= 16'h0000;
        fifo_mem[5] <= 16'h0000;
        fifo_mem[6] <= 16'h0000;
        fifo_mem[7] <= 16'h0000;
        fifo_mem[8] <= 16'h0000;
        fifo_mem[9] <= 16'h0000;
        fifo_mem[10] <= 16'h0000;
        fifo_mem[11] <= 16'h0000;
        fifo_mem[12] <= 16'h0000;
        fifo_mem[13] <= 16'h0000;
        fifo_mem[14] <= 16'h0000;
        fifo_mem[15] <= 16'h0000;
    end else if (fifo_push_int) begin
        fifo_mem[wr_ptr] <= fifo_data_i;
    end
end

// Read pointer and data output logic
always @(posedge mclk or posedge puc_rst) begin
    if (puc_rst) begin
        rd_ptr <= 4'h0;
        fifo_data_o <= 16'h0000;
    end else if (~fifo_enable_i) begin
        rd_ptr <= 4'h0;
        fifo_data_o <= 16'h0000;
    end else if (fifo_pop_int) begin
        if (rd_ptr == (FIFO_FULL - 1)) begin
            rd_ptr <= 4'h0;
        end else begin
            rd_ptr <= rd_ptr + 4'h1;
        end
    end else begin
        fifo_data_o <= fifo_mem[rd_ptr];
    end
end

// Counter logic
always @(posedge mclk or posedge puc_rst) begin
    if (puc_rst) begin
        fifo_cnt_o <= FIFO_EMPTY;
    end else begin
        if (!fifo_enable_i) begin
            fifo_cnt_o <= FIFO_EMPTY;
        end else if (fifo_push_int && fifo_pop_int) begin
            fifo_cnt_o <= fifo_cnt_o;
        end else if (fifo_push_int) begin
            fifo_cnt_nxt <= fifo_cnt_o + 4'h1;
            fifo_cnt_o <= fifo_cnt_nxt;
        end else if (fifo_pop_int) begin
            fifo_cnt_nxt <= fifo_cnt_o - 4'h1;
            fifo_cnt_o <= fifo_cnt_nxt;
        end else begin
            fifo_cnt_o <= fifo_cnt_o;
        end
    end
end

// Push and pop signals
assign fifo_push_int = fifo_push_i & !fifo_full_o;
assign fifo_pop_int = fifo_pop_i & !fifo_empty_o;

endmodule

module full_adder (
    input A,
    input B,
    input C_in,
    output S,
    output C_out
