    assign S = A ^ B ^ C_in;
    assign C_out = (A & B) | (A & C_in) | (B & C_in);

endmodule

module adder4 (
    input [3:0] A,
    input [3:0] B,
    output [3:0] S,
    output C
);

    wire [3:0] sum;
    wire [3:0] carry;

    full_adder fa0 (.A(A[0]), .B(B[0]), .C_in(1'b0), .S(sum[0]), .C_out(carry[0]));
    full_adder fa1 (.A(A[1]), .B(B[1]), .C_in(carry[0]), .S(sum[1]), .C_out(carry[1]));
    full_adder fa2 (.A(A[2]), .B(B[2]), .C_in(carry[1]), .S(sum[2]), .C_out(carry[2]));
    full_adder fa3 (.A(A[3]), .B(B[3]), .C_in(carry[2]), .S(sum[3]), .C_out(C));

    assign S = sum;

endmodule

module clock_stopwatch (
  input clk,
  input reset,
  input ena,
  input mode_switch,
  output reg [2:0] hours,
  output reg [5:0] minutes_seconds
);

reg [3:0] hours_count;
reg [5:0] minutes_count;
reg [5:0] seconds_count;
reg [1:0] stopwatch_minutes_count;
reg [5:0] stopwatch_seconds_count;
reg [1:0] mode;

always @(posedge clk) begin
  if (reset) begin
    hours_count <= 4'd0;
    minutes_count <= 6'd0;
    seconds_count <= 6'd0;
    stopwatch_minutes_count <= 2'd0;
    stopwatch_seconds_count <= 6'd0;
    hours <= 3'd0;
    minutes_seconds <= 6'd0;
    mode <= 2'd0;
  end else begin
    if (ena) begin
      if (mode_switch) begin
        mode <= ~mode;
        if (mode == 2'd0) begin
          hours_count <= 4'd0;
          minutes_count <= 6'd0;
          seconds_count <= 6'd0;
          hours <= 3'd0;
          minutes_seconds <= 6'd0;
        end else begin
          stopwatch_minutes_count <= 2'd0;
          stopwatch_seconds_count <= 6'd0;
          minutes_seconds <= {stopwatch_minutes_count, stopwatch_seconds_count};
        end
      end else begin
        if (mode == 2'd0) begin
          if (seconds_count == 6'd59) begin
            seconds_count <= 6'd0;
            if (minutes_count == 6'd59) begin
              minutes_count <= 6'd0;
              if (hours_count == 4'd23) begin
                hours_count <= 4'd0;
              end else begin
                hours_count <= hours_count + 4'd1;
              end
            end else begin
              minutes_count <= minutes_count + 6'd1;
            end
          end else begin
            seconds_count <= seconds_count + 6'd1;
          end
          hours <= hours_count;
          minutes_seconds <= {minutes_count, seconds_count};
        end else begin
          if (stopwatch_seconds_count == 6'd59) begin
            stopwatch_seconds_count <= 6'd0;
            if (stopwatch_minutes_count == 2'd59) begin
              stopwatch_minutes_count <= 2'd0;
            end else begin
              stopwatch_minutes_count <= stopwatch_minutes_count + 2'd1;
            end
          end else begin
            stopwatch_seconds_count <= stopwatch_seconds_count + 6'd1;
          end
          minutes_seconds <= {stopwatch_minutes_count, stopwatch_seconds_count};
        end
      end
    end
  end
end

endmodule

