module DFFJKSR (CK, J, K, S, R, Q, QN);
input CK, J, K, S, R;
output Q, QN;
reg Q, QN;

always @(posedge CK, negedge S, negedge R)
begin
  if (S)
    Q <= 1;
  else if (R)
    Q <= 0;
  else if (J && K)
    Q <= ~Q;
