  XOR2_X1 U2(.A(C1), .B(Cin), .Z(S));
  AND2_X1 U3(.A1(A), .A2(B), .ZN(C2));
  AND2_X1 U4(.A1(Cin), .A2(C1), .ZN(Cout));
