multiply_by_3 binary_mult_A(.a(A_LSB), .out(P_LSB[5:0]));
multiply_by_3 binary_mult_B(.a(B_LSB), .out(P_LSB[4:0]));
adder add(.in1(P_MSB), .in2(P_LSB), .out(P));

always @(*) begin
    A_MSB = A[3];
