    input [7:0] b,
    output [7:0] s,
    output overflow
);

wire [7:0] sum;
wire carry;

full_adder fa0(a[0], b[0], 1'b0, sum[0], carry);
full_adder fa1(a[1], b[1], carry, sum[1], carry);
full_adder fa2(a[2], b[2], carry, sum[2], carry);
full_adder fa3(a[3], b[3], carry, sum[3], carry);
