module uart_tx(
    input wire clk,
    input wire rst,
    input wire en,
    input wire [7:0] data_out,
    output reg rdy,
    output reg dout);

reg [2:0] state;
reg [3:0] count;
reg [7:0] data;

assign dout = state == 0 ? 1 : 0;

always @ (posedge clk)
begin
  if(rst)
  begin
    state <= 3'd0;
    count <= 4'd0;
    rdy <= 1'b1;
    data <= 8'd0;
  end
  else
  begin
    case(state)
      3'd0:
      begin
        if(en)
        begin
          state <= 3'd1;
          count <= 4'd0;
          data <= data_out;
        end
      end

      3'd1:
      begin
        if(count < 4'd8)
        begin
          count <= count + 1;
        end
        else
        begin
          count <= 4'd0;
          state <= 3'd2;
        end
      end

      3'd2:
      begin
        if(count < 4'd2)
        begin
          count <= count + 1;
        end
        else
        begin
          count <= 4'd0;
          state <= 3'd3;
          rdy <= 1'b0;
        end
      end

      3'd3:
      begin
        if(count < 4'd8)
        begin
          count <= count + 1;
        end
        else
        begin
          count <= 4'd0;
          state <= 3'd4;
        end
      end

      3'd4:
      begin
        state <= 3'd0;
        rdy <= 1'b1;
      end
    endcase
  end
end

endmodule

module krake_tx_port(
    input wire        clk_i,
    input wire        rst_i,
    output reg        ack_o,
    input wire [7:0]  dat_i,
    input wire [3:0]  adr_i,
    output reg [7:0]  dat_o,
    input wire        stb_i,
    input wire        we_i,
    output wire       dout);

reg [7:0] data;
reg tx_en;
wire tx_rdy;
reg tx_rst;

uart_tx txi(
  .clk(clk_i),
  .rst(rst_i),
  .en(tx_en),
  .data_out(data),
  .rdy(tx_rdy),
  .dout(dout));

parameter UART_STATUS = 4'd0;
parameter UART_DATAREG = 4'd1;

always @ (posedge clk_i)
begin
  if(rst_i)
  begin
    tx_rst <= 1'd1;
    data <= 8'd0;
    tx_en <= 1'd0;
  end
  else
  begin
    // Default Assignments
    ack_o <= 1'b0;
    dat_o <= 8'd0;
    tx_en <= 1'b0;
    data <= data;

    if(stb_i)
    begin
      case(adr_i)

        UART_STATUS:
        begin
          if(we_i) // Write
          begin
            tx_en <= dat_i[0];
            ack_o <= 1'b1;
          end
          else // Read
          begin
            dat_o[0] <= tx_rdy;
            ack_o <= 1'b1;
          end
        end

        UART_DATAREG:
        begin
          if(we_i) // Write
          begin
            data <= dat_i;
            ack_o <= 1'b1;
          end
          else // Read
          begin
            dat_o <= data;
            ack_o <= 1'b1;
          end
        end


      endcase
    end
  end
end

endmodule

