    if (trigger) begin
      pulse_out <= 1'b1;
      count <= width;
    end else if (count > 0) begin
      pulse_out <= 1'b1;
      count <= count - 1;
    end else begin
      pulse_out <= 1'b0;
    end
  end

endmodule

module my_module (
    O1,
    O2,
    I1,
    I2,
    A1,
    A2,
    B1,
    B2,
