module i2cSlave (
  input clk,
  input rst,
  inout sda,
  input scl,
  output [7:0] myReg0,
  output [7:0] myReg1,
  output [7:0] myReg2,
  output [7:0] myReg3,
  output [7:0] myReg4,
  output [7:0] myReg5,
  output [7:0] myReg6,
  output [7:0] myReg7
);

  // Internal registers
  reg [6:0] address;
  reg [7:0] data;
  reg [2:0] bitCount;
  reg [2:0] state;

  // Output registers
  reg [7:0] reg0;
  reg [7:0] reg1;
  reg [7:0] reg2;
  reg [7:0] reg3;
  reg [7:0] reg4;
  reg [7:0] reg5;
  reg [7:0] reg6;
  reg [7:0] reg7;

  // Assign output registers to the corresponding output ports
  assign myReg0 = reg0;
  assign myReg1 = reg1;
  assign myReg2 = reg2;
  assign myReg3 = reg3;
  assign myReg4 = reg4;
  assign myReg5 = reg5;
  assign myReg6 = reg6;
  assign myReg7 = reg7;

  // I2C state machine
  always @(posedge scl) begin
    if (rst) begin
      state <= 3'b000;
      bitCount <= 3'b000;
      address <= 7'b0000000;
      data <= 8'b00000000;
    end else begin
      case (state)
        3'b000: begin  // Address
          if (sda == 1'b0) begin
            bitCount <= 3'b001;
            state <= 3'b001;
          end
        end
        3'b001: begin  // Address
          address[bitCount] <= sda;
          bitCount <= bitCount + 1;
          if (bitCount == 3'b111) begin
            if (address == 7'b0000000) begin
              state <= 3'b010;  // Write to register
            end else if (address == 7'b0000001) begin
              state <= 3'b100;  // Read from register
            end else begin
              state <= 3'b000;  // Invalid address
            end
            bitCount <= 3'b000;
          end
        end
        3'b010: begin  // Write to register
          if (sda == 1'b0) begin
            bitCount <= 3'b000;
            state <= 3'b011;
          end
        end
        3'b011: begin  // Write to register
          data[bitCount] <= sda;
          bitCount <= bitCount + 1;
          if (bitCount == 3'b111) begin
            reg0 <= data;
            state <= 3'b000;
            bitCount <= 3'b000;
          end
        end
        3'b100: begin  // Read from register
          sda <= reg0[bitCount];
          bitCount <= bitCount + 1;
          if (bitCount == 3'b111) begin
            state <= 3'b000;
            bitCount <= 3'b000;
          end
        end
      endcase
    end
  end

endmodule

