    if (~rst) begin
      count <= 4'b0;
    end
    else if (en) begin
      count <= count + 1;
    end
  end

  assign carry_out = (count == 4'hF);

  assign carry_in = en;

  // Wrap around to 0 when count reaches its maximum value of 15
  always @(posedge clk) begin
    if (carry_out) begin
      count <= 4'b0;
    end
  end

endmodule

