module adder_subtractor (
    input [3:0] A,
    input [3:0] B,
    input sub,
    output [3:0] result,
    output carry_out
);

    wire [3:0] sum;
    wire [3:0] complement;
    wire carry_in;

    // Calculate the 2's complement of B if sub is high
    assign complement = sub ? ~B + 1 : B;

    // Calculate sum and carry out using full adders
    full_adder fa0(.A(A[0]), .B(complement[0]), .Cin(sub), .S(sum[0]), .Cout(carry_in));
    full_adder fa1(.A(A[1]), .B(complement[1]), .Cin(carry_in), .S(sum[1]), .Cout(carry_in));
    full_adder fa2(.A(A[2]), .B(complement[2]), .Cin(carry_in), .S(sum[2]), .Cout(carry_in));
    full_adder fa3(.A(A[3]), .B(complement[3]), .Cin(carry_in), .S(sum[3]), .Cout(carry_out));

    // Assign the output
    assign result = sum;

endmodule

module full_adder (
    input A,
    input B,
    input Cin,
    output S,
    output Cout
);

    assign S = A ^ B ^ Cin;
    assign Cout = (A & B) | (A & Cin) | (B & Cin);

endmodule

module clock_divider (
  input clock,
  input reset,
  output reg clk_out
);

parameter divisor = 2; // factor by which the frequency of the input clock signal is divided

always @ (posedge clock, posedge reset) begin
  if (reset) begin
    clk_out <= 0;
    counter <= 0;
  end else begin
    if (counter == divisor - 1) begin
      clk_out <= ~clk_out;
      counter <= 0;
    end else begin
      counter <= counter + 1;
    end
  end
end

reg [log2(divisor)-1:0] counter;

endmodule

module signed_multiplier (
    input clk, reset,
    input [7:0] multiplier,
    input [7:0] multiplicand,
    input [7:0] adder_out,
    input [7:0] sub_out,
    output reg [15:0] product
);

    reg signed [15:0] temp_product;
    reg signed [3:0] temp_multiplier;
    reg signed [3:0] temp_multiplicand;
    reg signed [7:0] temp_adder_out;
    reg signed [7:0] temp_sub_out;

    always @(posedge clk) begin
        if (reset) begin
            product <= 0;
            temp_product <= 0;
            temp_multiplier <= 0;
            temp_multiplicand <= 0;
            temp_adder_out <= 0;
            temp_sub_out <= 0;
        end else begin
            temp_multiplier <= multiplier;
            temp_multiplicand <= multiplicand;
            temp_adder_out <= adder_out;
            temp_sub_out <= sub_out;

            temp_product <= {temp_multiplier, 4'b0} * {temp_multiplicand, 4'b0};
            product <= temp_product + {temp_adder_out, 8'b0} - {temp_sub_out, 8'b0};
        end
    end

endmodule

module timer (
  input  wire        clk,
  input  wire        reset,
  input  wire        wrenb,
  input  wire        wraddr,
  input  wire [31:0] config_data,
  input  wire        update_timers,
  input  wire        fsm_start_timer,
  input  wire        fsm_clear_timer,
  input  wire        fsm_stop_timer,
  output reg         timer_elapsed
);

reg [35:0] timer, next_timer;
reg [35:0] timer_limit, next_timer_limit; // 10ns to 687 seconds
reg timer_active, next_timer_active;
reg next_timer_elapsed;

//
// 10ns resolution timer's...
//
initial 
begin 
  timer = 36'h0;
  timer_active = 1'b0;
  timer_elapsed = 1'b0;
  timer_limit = 36'h0;
end

always @ (posedge clk)
begin
  timer         <= next_timer;
  timer_active  <= next_timer_active;
  timer_elapsed <= next_timer_elapsed;
  timer_limit   <= next_timer_limit;
end

always @*
begin
  next_timer = (timer_elapsed) ? 36'h0 : timer;
  next_timer_active = timer_active;
  next_timer_elapsed = timer_elapsed;
  next_timer_limit = timer_limit;

  if (timer_active) 
    begin
      next_timer = timer+1'b1;
      if (timer >= timer_limit) 
	begin
	  next_timer_elapsed = 1'b1;
	  next_timer_active = 1'b0;
	end
    end

  if (update_timers) 
    begin
      if (fsm_start_timer) next_timer_active=1'b1;
      if (fsm_clear_timer) begin next_timer=0; next_timer_elapsed=1'b0; end
      if (fsm_stop_timer) next_timer_active=1'b0;
    end

  if (wrenb)
    case (wraddr)
      1'b0 : next_timer_limit[31:0] = config_data;
      1'b1 : next_timer_limit[35:32] = config_data[3:0];
    endcase

  if (reset)
    begin
      next_timer = 0;
      next_timer_active = 0;
      next_timer_elapsed = 0;
    end
end

always @(posedge clk)
begin
  if (timer >= timer_limit) 
    begin
      timer_elapsed <= 1'b1;
    end
  else
    begin
      timer_elapsed <= 1'b0;
    end
end

endmodule

module fsm_pattern_detection (
  input clk,
  input reset,
  input [3:0] data,
  output reg match
);

  reg [1:0] state, next_state;

  always @(posedge clk) begin
    if (reset) begin
      state <= 2'b00; // initialize to S0
      match <= 1'b0;
    end
    else begin
      state <= next_state;
      if (state == 2'b11) // if in S3, pattern has been detected
        match <= 1'b1;
      else
        match <= 1'b0;
    end
  end

  always @(*) begin
    case (state)
      2'b00: if (data == 4'b0001) next_state = 2'b01; else next_state = 2'b00;
      2'b01: if (data == 4'b0010) next_state = 2'b10; else next_state = 2'b01;
      2'b10: if (data == 4'b0100) next_state = 2'b00; else next_state = 2'b11;
      2'b11: if (data == 4'b1000) next_state = 2'b01; else next_state = 2'b00;
    endcase
  end

endmodule

module three_input_gate (
    Y,
    A1,
    A2,
    B1
);

    output Y;
    input A1;
    input A2;
    input B1;

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB;
    supply0 VNB;

    // Output Y should be high if A1 is high and A2 is low
    assign Y = (A1 && !A2) ? 1'b1 :
               // Output Y should be high if A2 is high and A1 is low
               (!A1 && A2) ? 1'b1 :
               // Output Y should be low if B1 is low
               (B1 == 1'b0) ? 1'b0 :
               // Output Y should be high if B1 is high and either A1 or A2 is high
               ((B1 == 1'b1) && (A1 || A2)) ? 1'b1 :
               // Output Y should be low if B1 is high and both A1 and A2 are low
               1'b0;

endmodule

module csrbrg(
    input sys_clk,
    input sys_rst,

    /* WB */
    input [31:0] wb_adr_i,
    input [31:0] wb_dat_i,
    output reg [31:0] wb_dat_o,
    input wb_cyc_i,
    input wb_stb_i,
    input wb_we_i,
    output reg wb_ack_o,

    /* CSR */
    output reg [13:0] csr_a,
    output reg csr_we,
    output reg [31:0] csr_do,
    input [31:0] csr_di
);

reg [1:0] state;
reg [1:0] next_state;

parameter IDLE       = 2'd0;
parameter DELAYACK1  = 2'd1;
parameter DELAYACK2  = 2'd2;
parameter ACK        = 2'd3;

/* Datapath: WB <- CSR */
always @(posedge sys_clk) begin
    if (csr_we) begin
        csr_do <= wb_dat_i;
    end
    wb_dat_o <= csr_do;
end

/* Datapath: CSR -> WB */
reg next_csr_we;
always @(posedge sys_clk) begin
    csr_a <= wb_adr_i[15:2];
    csr_we <= next_csr_we;
end

/* Controller */
always @(posedge sys_clk) begin
    if (sys_rst) begin
        state <= IDLE;
    end else begin
        state <= next_state;
    end
end

always @(*) begin
    next_state = state;
    wb_ack_o = 1'b0;
    next_csr_we = 1'b0;

    case(state)
        IDLE: begin
            if (wb_cyc_i & wb_stb_i) begin
                /* We have a request for us */
                next_csr_we = wb_we_i;
                if (wb_we_i) begin
                    next_state = ACK;
                end else begin
                    next_state = DELAYACK1;
                end
            end
        end
        DELAYACK1: begin
            next_state = DELAYACK2;
        end
        DELAYACK2: begin
            next_state = ACK;
        end
        ACK: begin
            wb_ack_o = 1'b1;
            next_state = IDLE;
        end
    endcase
end

endmodule

