module packet_generator
  (input clk, input reset, input clear,
   output [7:0] data_o, output sof_o, output eof_o,
   input [127:0] header,
   output src_rdy_o, input dst_rdy_i);

   reg [31:0] count;
   reg [127:0] packet;
   reg [7:0] data;
   reg [2:0] state;

   assign data_o = data;
   assign src_rdy_o = (state == 0);

   always @(posedge clk) begin
      if (reset) begin
         count <= 0;
         packet <= 0;
         data <= 0;
         state <= 0;
      end else if (clear) begin
         count <= 0;
         packet <= header;
         data <= packet[31:24];
         state <= 1;
      end else begin
         case (state)
            1: begin
               if (dst_rdy_i) begin
                  data <= packet[31:24];
                  count <= count + 1;
                  if (count == 7) begin
                     state <= 2;
                  end
               end
            end
            2: begin
               if (dst_rdy_i) begin
                  data <= packet[23:16];
                  count <= count + 1;
                  if (count == 15) begin
                     state <= 3;
                  end
               end
            end
            3: begin
               if (dst_rdy_i) begin
                  data <= packet[15:8];
                  count <= count + 1;
                  if (count == 23) begin
                     state <= 4;
                  end
               end
            end
            4: begin
               if (dst_rdy_i) begin
                  data <= packet[7:0];
                  count <= count + 1;
                  if (count == 31) begin
                     state <= 5;
                  end
               end
            end
            5: begin
               if (dst_rdy_i) begin
                  data <= 0;
                  sof_o <= 1;
                  count <= 0;
                  state <= 6;
               end
            end
            6: begin
               if (dst_rdy_i) begin
                  data <= 0;
                  eof_o <= 1;
                  state <= 0;
               end
            end
         endcase
      end
   end

