module ll8_to_fifo36
  (input clk, input reset, input clear,
   input [7:0] ll_data, input ll_sof_n, input ll_eof_n,
   input ll_src_rdy_n, output ll_dst_rdy_n,
   output [35:0] f36_data, output f36_src_rdy_o, input f36_dst_rdy_i);

   reg [35:0] fifo [0:7];
   reg [2:0] read_ptr, write_ptr;
   reg [2:0] count;
   reg [1:0] state;
   wire ll_sof, ll_eof, ll_src_rdy_n, ll_dst_rdy_n;
   assign ll_sof = ~ll_sof_n;
   assign ll_eof = ~ll_eof_n;
   assign ll_dst_rdy_n = ~ll_dst_rdy_n;

   assign f36_data = fifo[read_ptr];
   assign f36_src_rdy_o = (count < 8);

   always @(posedge clk) begin
      if (reset) begin
         read_ptr <= 0;
         write_ptr <= 0;
         count <= 0;
         state <= 0;
      end else if (clear) begin
         read_ptr <= 0;
         write_ptr <= 0;
         count <= 0;
         state <= 1;
      end else begin
         case (state)
            1: begin
               if (ll_src_rdy_n) begin
                  fifo[write_ptr] <= {ll_data, 0};
                  write_ptr <= write_ptr + 1;
                  count <= count + 1;
                  if (ll_eof) begin
                     state <= 2;
                  end
               end
            end
            2: begin
               if (f36_dst_rdy_i) begin
                  read_ptr <= read_ptr + 1;
                  count <= count - 1;
                  if (count == 0) begin
                     state <= 3;
                  end
               end
            end
            3: begin
               if (ll_src_rdy_n) begin
                  fifo[write_ptr] <= {ll_data, 0};
                  write_ptr <= write_ptr + 1;
                  count <= count + 1;
                  if (ll_sof) begin
                     state <= 4;
                  end
               end
            end
            4: begin
               if (f36_dst_rdy_i) begin
                  read_ptr <= read_ptr + 1;
                  count <= count - 1;
                  if (count == 0) begin
                     state <= 1;
                  end
               end
            end
         endcase
      end
      ll_dst_rdy_n <= (count < 8);
   end

endmodule

