module turbo_code (
  input [k-1:0] in,
  output [n-1:0] out
);

parameter k = 1024; // number of input bits
parameter n = 2048; // number of output bits
parameter m = 16;   // interleaver depth
parameter p = 8;    // number of iterations in decoding process

// Define shift registers for encoder and decoder
reg [k-1:0] enc_sr1;
reg [k-1:0] enc_sr2;
reg [n-1:0] dec_sr1;
reg [n-1:0] dec_sr2;

// Define interleaver
reg [m-1:0] intv_table [k/m-1:0];
integer i, j, k;
initial begin
  for (i = 0; i < k/m; i = i + 1) begin
    for (j = 0; j < m; j = j + 1) begin
      k = i * m + j;
      intv_table[i][j] = k;
    end
  end
end

// Define encoder
integer i;
always @ (in) begin
  enc_sr1 <= {in, enc_sr1[k-1:1]};
  enc_sr2 <= {enc_sr1[k-1:0], enc_sr2[k-1:1]};
  for (i = 0; i < n; i = i + 1) begin
    out[i] = enc_sr1[intv_table[i%m][i/m]] ^ enc_sr2[intv_table[i%m][i/m]];
  end
end

// Define decoder
integer j, l;
reg [n-1:0] dec_out;
always @ (out) begin
  dec_sr1 <= {out, dec_sr1[n-1:1]};
  for (j = 0; j < p; j = j + 1) begin
    dec_sr2 <= {dec_sr1[n-1:0], dec_sr2[n-1:1]};
    for (l = 0; l < n; l = l + 1) begin
      dec_out[l] = dec_sr1[intv_table[l%m][l/m]] ^ dec_sr2[intv_table[l%m][l/m]];
    end
    dec_sr1 <= dec_out;
  end
end

endmodule

