module vending_machine(
    input clk,
    input rst,
    input coin,
    input soda_btn,
    input chips_btn,
    output reg dispense,
    output reg change,
    output reg msg
);

// define states
parameter IDLE = 2'b00;
parameter SODA_SELECTED = 2'b01;
parameter CHIPS_SELECTED = 2'b10;
parameter SODA_DISPENSED = 2'b11;
parameter CHIPS_DISPENSED = 2'b100;
parameter CHANGE_RETURNED = 2'b101;

// define state register and next state logic
reg [2:0] state, next_state;
always @(posedge clk) begin
    if (rst) begin
        state <= IDLE;
    end else begin
        state <= next_state;
    end
end

// define outputs
assign dispense = (state == SODA_DISPENSED || state == CHIPS_DISPENSED);
assign change = (state == CHANGE_RETURNED);
assign msg = (state == IDLE);

// define state transition logic
always @(*) begin
    case (state)
        IDLE: begin
            if (coin) begin
                if (soda_btn) begin
                    next_state = SODA_SELECTED;
                end else if (chips_btn) begin
                    next_state = CHIPS_SELECTED;
                end else begin
                    next_state = IDLE;
                end
            end else begin
                next_state = IDLE;
            end
        end
        SODA_SELECTED: begin
            if (coin) begin
                next_state = (soda_btn && !chips_btn && state == SODA_SELECTED) ? SODA_DISPENSED : SODA_SELECTED;
                next_state = (!soda_btn && chips_btn && state == CHIPS_SELECTED) ? CHIPS_DISPENSED : next_state;
            end else begin
                next_state = IDLE;
