module DLL (
  input ref_clk,
  input fb_clk,
  output sync_clk
);

  // Phase Detector
  reg ref_clk_last;
  reg fb_clk_last;
  reg [1:0] phase_diff;

  always @(posedge ref_clk or posedge fb_clk) begin
    if (ref_clk_last == 1'b1 && ref_clk == 1'b0) begin
      if (fb_clk_last == 1'b1 && fb_clk == 1'b0) begin
        phase_diff <= 2'b00; // No phase difference
      end else begin
        phase_diff <= 2'b01; // fb_clk is leading
      end
    end else begin
      if (fb_clk_last == 1'b1 && fb_clk == 1'b0) begin
        phase_diff <= 2'b10; // ref_clk is leading
      end else begin
        phase_diff <= 2'b11; // No phase difference
      end
    end
    ref_clk_last <= ref_clk;
    fb_clk_last <= fb_clk;
  end

  // Delay Line
  reg [7:0] delay_count;
  reg [7:0] delay_value;

  always @(posedge ref_clk) begin
    case (phase_diff)
      2'b00: delay_count <= 8'b00000000; // No phase difference
      2'b01: delay_count <= delay_count + 1; // fb_clk is leading
      2'b10: delay_count <= delay_count - 1; // ref_clk is leading
      2'b11: delay_count <= delay_count; // No phase difference
    endcase
    delay_value <= (delay_count == 8'b00000000) ? 8'b00000001 : delay_value << 1;
  end

  // Feedback Loop
  reg [7:0] fb_clk_delayed;

  always @(posedge fb_clk or posedge delay_value) begin
    fb_clk_delayed <= (delay_value == 8'b00000000) ? fb_clk : fb_clk_delayed;
  end

  assign sync_clk = ref_clk & fb_clk_delayed;

endmodule

