      count_out <= 8'b0;
      max_count <= 1'b0;
    end else begin
      if (count_out == 8'b11111111) begin
        count_out <= 8'b0;
        max_count <= 1'b1;
      end else begin
        count_out <= count_out + 1;
        max_count <= 1'b0;
      end
    end
  end

