// Register module
module register (
  input clk,
  input reset,
  input [7:0] data_in,
  output reg [7:0] data_out
);

  always @(posedge clk) begin
    if (reset) begin
      data_out <= 8'b0;
    end else begin
      data_out <= data_in;
    end
  end

endmodule

// Adder module
module adder (
  input [7:0] a,
  input [7:0] b,
  output reg [7:0] sum
);

  always @(*) begin
    sum = a + b;
  end

endmodule

// Functional module
module function_modulo256 (
  input [7:0] input_data,
  output reg [7:0] output_data
);

  always @(*) begin
    output_data = input_data % 256;
  end

endmodule

module decoder (
    input [2:0] in,
    output reg [7:0] out
);

    always @* begin
        case (in)
            3'b000: out = 8'b00000001;
            3'b001: out = 8'b00000010;
            3'b010: out = 8'b00000100;
            3'b011: out = 8'b00001000;
            3'b100: out = 8'b00010000;
            3'b101: out = 8'b00100000;
            3'b110: out = 8'b01000000;
            3'b111: out = 8'b10000000;
            default: out = 8'b00000000;
        endcase
    end

endmodule

module vending_machine (
  input clk,
  input reset,
  input A,
  input B,
  input C,
  input D,
  output reg P,
  output reg Q,
  output reg R
);

  reg [1:0] state;
  parameter IDLE = 2'b00, ABD = 2'b01, BCD = 2'b10, ACD = 2'b11;

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      state <= IDLE;
      P <= 0;
      Q <= 0;
      R <= 0;
    end else begin
      case (state)
        IDLE: begin
          if (A) begin
            state <= ABD;
          end else if (B) begin
            state <= BCD;
          end else if (C) begin
            state <= ACD;
          end else begin
            state <= IDLE;
            P <= 0;
            Q <= 0;
            R <= 0;
          end
        end
        ABD: begin
          if (B) begin
            state <= BCD;
          end else if (A) begin
            state <= ABD;
          end else if (C || D) begin
            state <= IDLE;
            P <= 0;
            Q <= 0;
            R <= 0;
          end else begin
            state <= ABD;
          end
        end
        BCD: begin
          if (C) begin
            state <= ACD;
          end else if (B) begin
            state <= BCD;
          end else if (A || D) begin
            state <= IDLE;
            P <= 0;
            Q <= 0;
            R <= 0;
          end else begin
            state <= BCD;
          end
        end
        ACD: begin
          if (C) begin
            state <= ACD;
          end else if (A) begin
            state <= ABD;
          end else if (B || D) begin
            state <= IDLE;
            P <= 0;
            Q <= 0;
            R <= 0;
          end else begin
            state <= ACD;
          end
        end
      endcase
      case (state)
        ABD: begin
          P <= 1;
          Q <= 0;
          R <= 0;
        end
        BCD: begin
          P <= 0;
          Q <= 1;
          R <= 0;
        end
        ACD: begin
          P <= 0;
          Q <= 0;
          R <= 1;
        end
        default: begin
          P <= 0;
          Q <= 0;
          R <= 0;
        end
      endcase
    end
  end
endmodule

module dff_chain (
    input clk,
    input reset,
    input [7:0] d,
    output reg [7:0] q
);

reg [7:0] q_temp;

always @(posedge clk) begin
    if (reset) begin
        q_temp <= 8'h34;
    end else begin
        q_temp <= {q[6:0], d};
    end
end

assign q = q_temp;

endmodule

module top_module (
    input clk,
