module calculator (
  input op,
  input [3:0] a,
  input [3:0] b,
  output [3:0] result,
  output carry
);

  reg [4:0] temp_result;
  reg temp_carry;

  always @(*) begin
    if (op == 0) begin
      temp_result = a + b;
      temp_carry = (temp_result[4] == 1);
    end else begin
      temp_result = a - b;
      temp_carry = 0;
    end
  end

  assign result = temp_result[3:0];
  assign carry = temp_carry;

endmodule

module BRAM1Load(
  input CLK,
  input EN,
  input WE,
  input [ADDR_WIDTH-1:0] ADDR,
  input [DATA_WIDTH-1:0] DI,
  output [DATA_WIDTH-1:0] DO
);

  parameter FILENAME = "";
  parameter PIPELINED = 0;
  parameter ADDR_WIDTH = 1;
  parameter DATA_WIDTH = 1;
  parameter MEMSIZE = 1;
  parameter BINARY = 0;

  reg [DATA_WIDTH-1:0] RAM [0:MEMSIZE-1];
  reg [DATA_WIDTH-1:0] DO_R;
  reg [DATA_WIDTH-1:0] DO_R2;

  initial begin
    if (FILENAME != "") begin
      if (BINARY)
        $readmemb(FILENAME, RAM, 0, MEMSIZE-1);
      else
        $readmemh(FILENAME, RAM, 0, MEMSIZE-1);
    end
  end

  always @(posedge CLK) begin
    if (EN) begin
      if (WE) begin
        RAM[ADDR] <= DI;
        DO_R <= DI;
      end else begin
        DO_R <= RAM[ADDR];
      end
    end
    DO_R2 <= DO_R;
  end

  assign DO = PIPELINED ? DO_R2 : DO_R;

endmodule

module circular_shift_register (
    input CLK,
    input RESET,
    input enable,
    output reg [2:0] OUT
);

reg [2:0] reg1, reg2, reg3;

always @(posedge CLK) begin
    if(RESET) begin
        reg1 <= 3'b000;
        reg2 <= 3'b000;
        reg3 <= 3'b000;
    end
    else if(enable) begin
        reg1 <= OUT;
        reg2 <= reg1;
        reg3 <= reg2;
    end
end

assign OUT = enable ? reg3 : OUT;

endmodule

module sky130_fd_sc_hdll__o21ai (
    Y ,
    A1,
