module Half_Subtractor (
  input A, B,
  output D, Bout
);

  assign D = A ^ B;
  assign Bout = A < B;

endmodule

module Full_Subtractor (
  input A, B, Bin,
  output D, Bout
);

  wire D1, Bout1;
  Half_Subtractor HS1 (.A(A), .B(B), .D(D1), .Bout(Bout1));
  Half_Subtractor HS2 (.A(D1), .B(Bin), .D(D), .Bout(Bout));

  assign Bout = Bout1 | (Bin & (A <= B));

endmodule

module lut_ff
   (aclk,
    input_signals,
    lut_output,
    ff_output);

  input aclk;
  input [1:0] input_signals;
  output lut_output;
  output ff_output;

  wire const0;
  wire const1;
  wire pre_rdy;
  wire lut_output;
  wire ff_output;

  GND GND (.G(const0));
  VCC VCC (.P(const1));

  LUT2 #(.INIT(4'h1)) lut (.I0(input_signals[0]), .I1(input_signals[1]), .O(pre_rdy));

  FDRE #(.INIT(1'b0)) ff (.C(aclk), .CE(const1), .D(pre_rdy), .Q(ff_output), .R(const0));

  assign lut_output = pre_rdy;

endmodule

module t2(
  input [2:0] i_clks,
  input        i_clk0,
  input        i_clk1,
  input        i_clk2,
  input        i_data,

  output       o_data,
  output       o_clk,
  output       o_clk2,
  output       o_clk3
);

  reg [3:0] data_delay;
  reg [3:0] clk_cnt;
  reg [3:0] clk2_cnt;
  reg [3:0] clk3_cnt;

  always @(posedge i_clk0) begin
    data_delay <= {data_delay[2:0], i_data};
    o_data <= data_delay[3];
  end

  always @(posedge i_clk1) begin
    if (clk_cnt == 9) begin
      clk_cnt <= 0;
    end else begin
      clk_cnt <= clk_cnt + 1;
    end
    o_clk <= (clk_cnt < 5) ? 1'b1 : 1'b0;
  end

  always @(posedge i_clk2) begin
    if (clk2_cnt == 14) begin
      clk2_cnt <= 0;
    end else begin
      clk2_cnt <= clk2_cnt + 1;
    end
    o_clk2 <= (clk2_cnt < 7) ? 1'b1 : 1'b0;
  end

  always @(posedge i_clk0) begin
    if (clk3_cnt == 2) begin
      clk3_cnt <= 0;
    end else begin
      clk3_cnt <= clk3_cnt + 1;
    end
    o_clk3 <= (clk3_cnt == 0) ? 1'b1 : 1'b0;
  end

endmodule

