module top_module (
    input [7:0] a, b, c, d, // Inputs to the first module
    input [7:0] d_in, // Input to the second module
    output [7:0] max // Maximum value obtained from the sum
);

wire [7:0] sum_out;
wire [1:0] encoder_out;

module_1 m1(a, b, c, d, sum_out);
module_2 m2(d_in, sum_out);
sum_module sm(sum_out, a, b, c, d, sum_out);
priority_encoder pe(sum_out[0], sum_out[1], sum_out[2], sum_out[3], d_in, encoder_out);

assign max = (encoder_out == 2'b00) ? a :
             (encoder_out == 2'b01) ? b :
             (encoder_out == 2'b10) ? c :
             (encoder_out == 2'b11) ? d : 8'h00;

endmodule

module module_1 (
    input [7:0] a, b, c, d,
    output [7:0] out
);

assign out = a + b + c + d;

endmodule

module module_2 (
    input [7:0] in,
    output [7:0] out
);

assign out = in;

endmodule

module sum_module (
    input [7:0] in_1, in_2, in_3, in_4, in_5,
    output [7:0] out
);

assign out = in_1 + in_2 + in_3 + in_4 + in_5;

endmodule

module priority_encoder (
    input [7:0] in_1, in_2, in_3, in_4, in_5,
    output [1:0] out
);

wire [7:0] max_val;
assign max_val[0] = (in_1 > in_2) ? in_1 : in_2;
assign max_val[1] = (in_3 > in_4) ? in_3 : in_4;
assign max_val[2] = (max_val[0] > max_val[1]) ? max_val[0] : max_val[1];
assign max_val[3] = (in_5 > max_val[2]) ? in_5 : max_val[2];

assign out = (max_val[3] == in_1) ? 2'b00 :
             (max_val[3] == in_2) ? 2'b01 :
             (max_val[3] == in_3) ? 2'b10 :
             (max_val[3] == in_4) ? 2'b11 :
             2'b00;

endmodule

module dff_async_set_reset (
    input wire D,
    input wire SET_B,
    input wire RESET_B,
    input wire CLK,
    output reg Q,
    output reg Q_B
    );

    always @(posedge CLK) begin
        if (!RESET_B) begin
            Q <= 1'b0;
            Q_B <= 1'b1;
        end else if (!SET_B) begin
            Q <= 1'b1;
            Q_B <= 1'b0;
        end else begin
            Q <= D;
            Q_B <= ~D;
        end
    end

endmodule

module lo_simulate(
    pck0, ck_1356meg, ck_1356megb,
    pwr_lo, pwr_hi, pwr_oe1, pwr_oe2, pwr_oe3, pwr_oe4,
    adc_d, adc_clk,
    ssp_frame, ssp_din, ssp_dout, ssp_clk,
    cross_hi, cross_lo,
    dbg,
    divisor
);
    input pck0, ck_1356meg, ck_1356megb;
    output pwr_lo, pwr_hi, pwr_oe1, pwr_oe2, pwr_oe3, pwr_oe4;
    input [7:0] adc_d;
    output adc_clk;
    input ssp_dout;
    output ssp_frame, ssp_din, ssp_clk;
    input cross_hi, cross_lo;
    output dbg;
    input [7:0] divisor;

    assign pwr_oe3 = 1'b0;
    assign pwr_oe1 = ssp_dout;
    assign pwr_oe2 = ssp_dout;
    assign pwr_oe4 = ssp_dout;
    assign ssp_clk = cross_lo;
    assign pwr_lo = 1'b0;
    assign pwr_hi = 1'b0;
    assign dbg = ssp_frame;

    reg [7:0] pck_divider;
    reg clk_state;

    always @(posedge pck0) begin
        if(pck_divider == divisor[7:0]) begin
            pck_divider <= 8'd0;
            clk_state = !clk_state;
        end
        else begin
            pck_divider <= pck_divider + 1;
        end
    end

    assign adc_clk = ~clk_state;

    reg is_high;
    reg is_low;
    reg output_state;

    always @(posedge pck0) begin
        if((pck_divider == 8'd7) && !clk_state) begin
            is_high = (adc_d >= 8'd200);
            is_low = (adc_d <= 8'd64);
        end
    end

    always @(posedge is_high or posedge is_low) begin
        if(is_high) begin
            output_state <= 1'd1;
        end
        else if(is_low) begin
            output_state <= 1'd0;
        end
    end

    assign ssp_frame = output_state;

endmodule

module mux_min (
    input wire [2:0] vec, // 3-bit input for the multiplexer
    input wire select, // Select input for the multiplexer
    input [7:0] a, b, c, d, // 4 unsigned 8-bit input values for the functional module
    output wire [2:0] outv, // 3 output ports for the selected bit from the multiplexer
    output wire o2,
    output wire o1,
    output wire o0,
    output wire [7:0] min // 8-bit output representing the minimum value among the four input values
);

// Multiplexer
assign outv = {vec[2] ? vec[2] : vec[1] ? vec[1] : vec[0], vec[2] ? vec[2] : vec[1] ? vec[1] : vec[0], vec[2] ? vec[2] : vec[1] ? vec[1] : vec[0]};
assign o2 = outv[2];
assign o1 = outv[1];
assign o0 = outv[0];

// Comparator and Multiplexer for minimum value
wire [7:0] min1, min2, min3;
assign min1 = a < b ? a : b;
assign min2 = c < d ? c : d;
assign min3 = min1 < min2 ? min1 : min2;
assign min = min3;

endmodule

