module top_module (
    input [3:0] a,
    input [3:0] b,
    output [7:0] out
);

    // 4-bit binary adder
    wire [4:0] sum;
    assign sum = a + b;

    // 2-bit comparator
    wire [1:0] comp;
    assign comp = (a > b) ? 2'b01 : (a < b) ? 2'b10 : 2'b00;

    // Functional module
    wire [7:0] final;
    assign final = (comp == 2'b01) ? {sum, 2'b00} : (comp == 2'b10) ? {(a - b), 2'b00} : {a & b, 4'b0000};

    // Output
    assign out = final;

endmodule

module fsm_4bit_sequence_detection (
  input clk,
  input reset,
  input data,
  output reg match
);

  parameter S0 = 2'b00, S1 = 2'b01, S2 = 2'b10, S3 = 2'b11;
  reg [1:0] state, next_state;

  always @ (posedge clk, posedge reset) begin
    if (reset) begin
      state <= S0;
      match <= 0;
    end
    else begin
      state <= next_state;
      if (state == S0) begin
        if (data == 1'b1) begin
          next_state <= S1;
        end
        else begin
          next_state <= S0;
        end
      end
      else if (state == S1) begin
        if (data == 1'b0) begin
          next_state <= S0;
        end
        else begin
          next_state <= S2;
        end
      end
      else if (state == S2) begin
        if (data == 1'b1) begin
          next_state <= S3;
        end
        else begin
          next_state <= S0;
        end
      end
      else if (state == S3) begin
        if (data == 1'b1) begin
          next_state <= S1;
          match <= 1;
        end
        else begin
          next_state <= S2;
        end
      end
    end
  end

endmodule

module full_adder(
    input A,
    input B,
    input Cin,
    output S,
    output Cout
);

    assign S = A ^ B ^ Cin;
    assign Cout = (A & B) | (Cin & (A ^ B));

endmodule

module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    output [3:0] S,
    output Cout
);

    wire [3:0] c;
    wire [3:0] s;

    full_adder fa0(
        .A(A[0]),
        .B(B[0]),
        .Cin(1'b0),
        .S(s[0]),
        .Cout(c[0])
    );
    full_adder fa1(
        .A(A[1]),
        .B(B[1]),
        .Cin(c[0]),
        .S(s[1]),
        .Cout(c[1])
    );
    full_adder fa2(
        .A(A[2]),
        .B(B[2]),
        .Cin(c[1]),
        .S(s[2]),
        .Cout(c[2])
    );
    full_adder fa3(
        .A(A[3]),
        .B(B[3]),
        .Cin(c[2]),
        .S(s[3]),
        .Cout(Cout)
    );

    assign S = s;

endmodule

