module checksum_generator (
  input wire clk,
  input wire reset,
  input wire [7:0] data_in,
  input wire data_valid,
  output reg [7:0] checksum_out,
  output reg checksum_ready
);

  reg [7:0] xor_result;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      xor_result <= 8'b0;
      checksum_ready <= 1'b0;
    end else begin
      if (data_valid) begin
        xor_result <= xor_result ^ data_in;
      end
      checksum_out <= xor_result;
      checksum_ready <= data_valid;
    end
  end

endmodule

module checksum_checker (
  input wire clk,
  input wire reset,
  input wire [7:0] data_in,
  input wire data_valid,
  input wire [7:0] checksum_in,
  input wire checksum_valid,
  output reg pass,
  output reg fail
);

  reg [7:0] xor_result;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      xor_result <= 8'b0;
      pass <= 1'b0;
      fail <= 1'b0;
    end else begin
      if (data_valid) begin
        xor_result <= xor_result ^ data_in;
      end
      if (checksum_valid) begin
        if (xor_result == checksum_in) begin
          pass <= 1'b1;
          fail <= 1'b0;
        end else begin
          pass <= 1'b0;
          fail <= 1'b1;
        end
      end
    end
  end

endmodule

