module psdos (
    input Rx,
    input CLKOUT,
    output reg Rx_error,
    output [7:0] DATA,
    output reg DONE
);

    reg [8:0] regis;
    reg [7:0] regis0;
    reg [3:0] i;
    reg [3:0] j;
    reg [1:0] k;
    reg init;
    reg DoIt;

    initial begin
        i = 0;
        j = 0;
        init = 0;
        regis = 0;
        regis0 = 0;
        Rx_error = 0;
        DONE = 0;
        k = 0;
        DoIt = 1;
    end

    always @(posedge CLKOUT) begin
        if (!Rx && !i) begin
            init <= 1;
            DONE <= 0;
            Rx_error <= 0;
        end

        if (init) begin
            regis[i] <= Rx;
            i <= i + 1;
            if (regis[i] && (i < 8)) begin
                j <= j + 1;
            end
        end

        if (DoIt) begin
            k <= k + 1;
        end

        if (i == 9) begin
            if (((j % 2) && (regis[8])) || (!(j % 2) && (!regis[8]))) begin
                Rx_error <= 0;
                regis0 <= {regis[7:0]};
                DONE <= 1;
            end
            else begin
                Rx_error <= 1;
                regis0 <= 0;
                DONE <= 0;
            end
            j <= 0;
            i <= 0;
            init <= 0;
        end
    end

    assign DATA = regis0;

endmodule

module vending_machine (
  input clk,
  input reset,
  input [3:0] coin_in,
  output reg [3:0] coin_out,
  output reg product_dispensed
);

  parameter S_IDLE = 2'b00, S_DISPENSE = 2'b01, S_RETURN_CHANGE = 2'b10;
  reg [1:0] state = S_IDLE;
  reg [5:0] amount_inserted = 6'd0;

  always @(posedge clk) begin
    if (reset) begin
      state <= S_IDLE;
      amount_inserted <= 6'd0;
      coin_out <= 4'd0;
      product_dispensed <= 1'b0;
    end
    else begin
      case (state)
        S_IDLE: begin
          if (amount_inserted < 6'd75) begin
            amount_inserted <= amount_inserted + coin_in;
            coin_out <= amount_inserted;
          end
          else if (amount_inserted == 6'd75) begin
            product_dispensed <= 1'b1;
          end
          else begin
            state <= S_RETURN_CHANGE;
          end
        end
        S_DISPENSE: begin
          coin_out <= 4'd0;
          product_dispensed <= 1'b1;
          amount_inserted <= amount_inserted - 6'd75;
          if (amount_inserted > 6'd0) begin
            state <= S_RETURN_CHANGE;
          end
          else begin
            state <= S_IDLE;
          end
        end
        S_RETURN_CHANGE: begin
          if (amount_inserted >= 6'd50) begin
            coin_out <= 4'd10;
            amount_inserted <= amount_inserted - 6'd50;
          end
          else if (amount_inserted >= 6'd25) begin
            coin_out <= 4'd5;
            amount_inserted <= amount_inserted - 6'd25;
          end
          else if (amount_inserted >= 6'd10) begin
            coin_out <= 4'd2;
            amount_inserted <= amount_inserted - 6'd10;
          end
          else if (amount_inserted >= 6'd5) begin
            coin_out <= 4'd1;
            amount_inserted <= amount_inserted - 6'd5;
          end
          else if (amount_inserted >= 6'd1) begin
            coin_out <= 4'd1;
            amount_inserted <= amount_inserted - 6'd1;
          end
          if (amount_inserted == 6'd0) begin
            state <= S_IDLE;
          end
        end
      endcase
    end
  end

endmodule

