module fifo_32in_32out_16kb_memory
  (
    input clk,
    input rst,
    input [31:0] din,
    input [31:0] din_en,
    output reg [31:0] dout,
    input [31:0] dout_en
  );

  // Parameters
  parameter WIDTH = 32;
  parameter DEPTH = 512;

  // Internal signals
  reg [WIDTH-1:0] mem [DEPTH-1:0];
  reg [9:0] wr_ptr = 0;
  reg [9:0] rd_ptr = 0;
  reg [9:0] count = 0;
  wire full = (count == DEPTH);
  wire empty = (count == 0);

  // Write enable logic
  reg we = 0;
  always @ (posedge clk) begin
    if (rst) begin
      we <= 0;
    end else if (din_en) begin
      we <= ~full;
    end
  end

  // Write pointer logic
  always @ (posedge clk) begin
    if (rst) begin
      wr_ptr <= 0;
    end else if (we) begin
      wr_ptr <= wr_ptr + 1;
    end
  end

  // Read enable logic
  reg re = 0;
  always @ (posedge clk) begin
    if (rst) begin
      re <= 0;
    end else if (dout_en) begin
      re <= ~empty;
    end
  end

  // Read pointer logic
  always @ (posedge clk) begin
    if (rst) begin
      rd_ptr <= 0;
    end else if (re) begin
      rd_ptr <= rd_ptr + 1;
    end
  end

  // Count logic
  always @ (posedge clk) begin
    if (rst) begin
      count <= 0;
    end else begin
      count <= count + we - re;
    end
  end

  // Memory read/write logic
  always @ (posedge clk) begin
    if (rst) begin
      mem <= 0;
    end else begin
      if (we) begin
        mem[wr_ptr] <= din;
      end
      if (re) begin
        dout <= mem[rd_ptr];
      end
    end
  end

endmodule

