    wire [3:0] twos_comp_b;

    full_adder_1bit fa0(.A(A[0]), .B(~B[0]), .CIN(SEL), .SUM(sum[0]), .COUT());
    full_adder_1bit fa1(.A(A[1]), .B(~B[1]), .CIN(sum[0]), .SUM(sum[1]), .COUT());
    full_adder_1bit fa2(.A(A[2]), .B(~B[2]), .CIN(sum[1]), .SUM(sum[2]), .COUT());
    full_adder_1bit fa3(.A(A[3]), .B(~B[3]), .CIN(sum[2]), .SUM(sum[3]), .COUT());

    assign neg_b = ~B + 1;
    assign twos_comp_b = SEL ? B : neg_b;

    assign Y = CLK ? (SEL ? (A + twos_comp_b) : (A + B)) : 4'b0;
    assign COUT = CLK ? (SEL ? (Y[3] ^ A[3] ^ twos_comp_b[3]) : (Y[3] ^ A[3] ^ B[3])) : 1'b0;

    always @(posedge CLK, posedge RST) begin
        if(RST) begin
            Y <= 4'b0;
        end else begin
            Y <= Y;
        end
    end

endmodule

module crc_engine
(
	//OUTPUTS
	output [31:0] HRDATA,
	output HREADYOUT,
	output HRESP,
	output [31:0] bus_wr,
	output [ 1:0] crc_poly_size,
	output [ 1:0] bus_size,
	output [ 1:0] rev_in_type,
	output rev_out_type,
	output crc_init_en,
	output crc_idr_en,
	output crc_poly_en,
	output buffer_write_en,
	output reset_chain,
	//INPUTS
	input [31:0] HWDATA,
	input [31:0] HADDR,
	input [ 2:0] HSIZE,
	input [ 1:0] HTRANS,
	input HWRITE,
	input HSElx,
	input HREADY,
	input HRESETn,
	input HCLK,
	input [31:0] crc_poly_out,
	input [31:0] crc_out,
	input [31:0] crc_init_out,
	input [ 7:0] crc_idr_out,
	input buffer_full,
	input reset_pending,
	input read_wait
);

//Reset Values
localparam RESET_CRC_CR = 6'h00;

//CRC Register Map
localparam CRC_DR   = 3'h0;
localparam CRC_IDR  = 3'h1;
localparam CRC_CR   = 3'h2;
localparam CRC_INIT = 3'h4;
localparam CRC_POL  = 3'h5;

//Transfer Type Encoding
localparam IDLE    = 2'b00;
localparam BUSY    = 2'b01;
localparam NON_SEQ = 2'b10;
localparam SEQ     = 2'b11;

//HRESP Encoding
localparam OK    = 1'b0;
localparam ERROR = 1'b1;

//Pipeline flops
reg [2:0] haddr_pp;
reg [2:0] hsize_pp;
reg [1:0] htrans_pp;
reg hwrite_pp;
reg hselx_pp;

//Flops
reg [4:0] crc_cr_ff;

//Internal Signals
wire [31:0] crc_cr_rd;
wire crc_dr_sel;
wire crc_init_sel;
wire crc_idr_sel;
wire crc_poly_sel;
wire crc_cr_sel;
wire ahb_enable;
wire write_en;
wire read_en;
wire crc_cr_en;
wire sample_bus;
wire buffer_read_en;

//Pipeline Registers for Address Phase of AHB Protocol
always @(posedge HCLK)
	begin
		if(!HRESETn)
			begin
				hselx_pp <= 1'b0;
			end
		else
			if(sample_bus)
				begin
					haddr_pp  <= HADDR[4:2];
					hsize_pp  <= HSIZE;
					htrans_pp <= HTRANS;
					hwrite_pp <= HWRITE;
					hselx_pp  <= HSElx;
				end
	end

//Enable Signals
assign ahb_enable = (htrans_pp == NON_SEQ);
assign write_en = hselx_pp &&  hwrite_pp && ahb_enable;
assign read_en  = hselx_pp && !hwrite_pp && ahb_enable;

//Registers decoding
assign crc_dr_sel   = (haddr_pp == CRC_DR  );
assign crc_init_sel = (haddr_pp == CRC_INIT);
assign crc_idr_sel  = (haddr_pp == CRC_IDR );
assign crc_poly_sel = (haddr_pp == CRC_POL );
assign crc_cr_sel   = (haddr_pp == CRC_CR  );

//Write Enables Signals for Registers
assign buffer_write_en = crc_dr_sel   && write_en;
assign crc_init_en     = crc_init_sel && write_en;
assign crc_idr_en      = crc_idr_sel  && write_en;
assign crc_poly_en     = crc_poly_sel && write_en;
assign crc_cr_en       = crc_cr_sel   && write_en;

//Indicates reading operation request to crc_dr register
assign buffer_read_en = crc_dr_sel && read_en;

//Bus Size is the output of HSIZE pipeline register
assign bus_size = hsize_pp;

//The Write Bus is not pipelined
assign bus_wr = HWDATA;

//HREADY Signal outputed to Master
assign HREADYOUT = !((buffer_write_en && buffer_full   ) ||
                     (buffer_read_en  && read_wait     ) ||
                     (crc_init_en     && reset_pending ) );

//Signal to control sampling of bus
assign sample_bus = HREADYOUT && HREADY;

//HRESP Signal outputed to Master
//This implementation never signalizes bus error to master
assign HRESP = OK;

//CRC_CR Data Read
assign crc_cr_rd = {24'h0, crc_cr_ff[4:0], 3'h0};

//Mux to HRDATA
assign HRDATA = ({32{crc_dr_sel  }} & crc_out             ) |
                ({32{crc_init_sel}} & crc_init_out        ) |
                ({32{crc_idr_sel }} & {24'h0, crc_idr_out}) |
                ({32{crc_poly_sel}} & crc_poly_out        ) |
                ({32{crc_cr_sel  }} & crc_cr_rd           ) ;

//Control Register
always @(posedge HCLK)
	begin
		if(!HRESETn)
			crc_cr_ff <= RESET_CRC_CR;
		else
			if(crc_cr_en)
				crc_cr_ff <= {HWDATA[7], HWDATA[6:5], HWDATA[4:3]};
	end

//Configuration Signals
assign reset_chain   = (crc_cr_en && HWDATA[0]);
assign crc_poly_size = crc_cr_ff[1:0];
assign rev_in_type   = crc_cr_ff[3:2];
assign rev_out_type  = crc_cr_ff[4];

endmodule

module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [3:0] d,    // 4-bit input for the shift register and adder
    output [3:0] out   // 4-bit output from the active module
);

    reg [3:0] reg_out;
    wire [3:0] add_out;
    wire active;

    // 4-bit shift register with active high synchronous reset to 0
    always @(posedge clk) begin
        if (reset) begin
            reg_out <= 4'b0;
        end else begin
            reg_out <= {d[2:0], d[3]};
        end
    end

    // 4-bit adder that adds the value of the register with the input data
    assign add_out = reg_out + d;

    // Functional module that performs an AND operation on the MSBs of the register and adder outputs
    assign active = (reg_out[3] & add_out[3]);

    // Output the value of the active module
    assign out = (active) ? add_out : reg_out;

endmodule

module control_module (
    input [7:0] data_in,
    input [1:0] control_in,
    output reg [7:0] data_out
);

    always @(*) begin
        case (control_in)
            2'b00: data_out = data_in;
            2'b01: data_out = ~data_in;
            2'b10: data_out = {data_in[6:0], 1'b0};
            2'b11: data_out = {1'b0, data_in[7:1]};
            default: data_out = 8'b0;
        endcase
    end

endmodule

module four_bit_adder(
  input [3:0] A,
  input [3:0] B,
  input Cin,
  output [3:0] S,
  output Cout
);

  wire [3:0] sum;
  wire carry;

  // Full adder for bit 0
  full_adder fa0 (.a(A[0]), .b(B[0]), .cin(Cin), .sum(sum[0]), .cout(carry));

  // Full adder for bit 1
  full_adder fa1 (.a(A[1]), .b(B[1]), .cin(carry), .sum(sum[1]), .cout(carry));

  // Full adder for bit 2
  full_adder fa2 (.a(A[2]), .b(B[2]), .cin(carry), .sum(sum[2]), .cout(carry));

  // Full adder for bit 3
  full_adder fa3 (.a(A[3]), .b(B[3]), .cin(carry), .sum(sum[3]), .cout(Cout));

  assign S = sum;

endmodule

// Full adder module
module full_adder(
  input a,
  input b,
  input cin,
  output sum,
  output cout
);

  assign sum = a ^ b ^ cin;
  assign cout = (a & b) | (cin & (a ^ b));

endmodule

module mem_interface
    #(parameter BYTES = 4)
    (
     input           mclock,
     input           mc_push,
     `ifdef BYTE16 input [2:0]     mc_addr,
     `elsif BYTE8  input [3:0]     mc_addr,
     `else         input [4:0]     mc_addr,
     `endif

     input           hclock,
     input           hb_we,
     input [4:0]     hb_addr,
     input [(BYTES*8)-1:0] hb_dout_ram,

     `ifdef BYTE16 input [2:0]     rad,
     `elsif BYTE8  input [3:0]     rad,
     `else         input [4:0]     rad, `endif

     `ifdef BYTE16 output [3:0] ca_enable,
     `elsif BYTE8  output [1:0] ca_enable,
     `else         output       ca_enable,
     `endif
     output     [31:0]          hb_dout,
     output     [4:0]           hb_ram_addr,
     output [4:0]           ca_ram_addr0,
     output [4:0]           ca_ram_addr1
     );

     reg [4:0] ca_ram_addr0_reg;
     reg [4:0] ca_ram_addr1_reg;

     always @(posedge mclock) begin
         if (mc_push) begin
             ca_ram_addr0_reg <= mc_addr;
             ca_ram_addr1_reg <= mc_addr + 1;
         end
     end

     `ifdef BYTE16
     assign hb_dout   = hb_dout_ram[hb_addr[1:0]*32 +: 32];
     assign ca_enable[0] = hb_we & (hb_addr[1:0] == 2'd0);
     assign ca_enable[1] = hb_we & (hb_addr[1:0] == 2'd1);
     assign ca_enable[2] = hb_we & (hb_addr[1:0] == 2'd2);
     assign ca_enable[3] = hb_we & (hb_addr[1:0] == 2'd3);
     assign hb_ram_addr = {2'b0, hb_addr[4:2]};
     assign ca_ram_addr0 = (mc_push) ? {2'b0, mc_addr} : {2'b0, rad};
     assign ca_ram_addr1 = (mc_push) ? {2'b0, mc_addr} : {2'b0, rad+1};
     `elsif BYTE8
     assign hb_dout   = hb_dout_ram[hb_addr[0]*32 +: 32];
     assign ca_enable[0] = hb_we & (hb_addr[0] == 1'b0);
     assign ca_enable[1] = hb_we & (hb_addr[0] == 1'b1);
     assign hb_ram_addr = {1'b0, hb_addr[4:1]};
     assign ca_ram_addr0 = (mc_push) ? {1'b0, mc_addr} : {1'b0, rad};
     assign ca_ram_addr1 = (mc_push) ? {1'b0, mc_addr} : {1'b0, rad+1};
     `else
     assign hb_dout = hb_dout_ram[31:0];
     assign ca_enable  = hb_we;
     assign hb_ram_addr = hb_addr[4:0];
     assign ca_ram_addr0 = (mc_push) ? mc_addr : rad;
     assign ca_ram_addr1 = (mc_push) ? mc_addr : rad+1;
     `endif

endmodule

module shift_register ( input clk, input d, output q );
  reg [2:0] reg_data;
  always @(posedge clk) begin
    reg_data <= {reg_data[1:0], d};
  end
  assign q = reg_data[0];
endmodule

module combinational_circuit(
    input A,
    input B,
    output Y
);

assign Y = (A & ~B) | (~A & B);

endmodule

module sipo_shift_register (
    input CLK,
    input DIN,
    input LOAD,
    output reg [3:0] Q,
    output reg [3:0] QBAR
);

parameter WIDTH = 4;

reg [WIDTH-1:0] shift_reg;

always @(posedge CLK) begin
    if (LOAD) begin
        shift_reg <= DIN;
    end else begin
        shift_reg <= {shift_reg[WIDTH-2:0], DIN};
    end
end

assign Q = shift_reg;
assign QBAR = ~shift_reg;

endmodule

module top_module(
    input clk,
    input load,
    input [1:0] ena,
    input a,
    input b,
    output reg out,
    input [99:0] data,
    output reg [99:0] q
);

reg [99:0] temp_data;
reg [99:0] shifted_data;
reg [99:0] rotated_data;
wire [99:0] xor_output;

// XOR gate implementation
assign xor_output = a ^ b;

// Left/Right rotator implementation
always @(posedge clk) begin
    if (load) begin
        temp_data <= data;
    end else if (ena[0]) begin
        shifted_data[0] <= temp_data[99];
        shifted_data[1:99] <= temp_data[0:98];
        temp_data <= shifted_data;
    end else if (ena[1]) begin
        shifted_data[99] <= temp_data[0];
        shifted_data[0:98] <= temp_data[1:99];
        temp_data <= shifted_data;
    end
end

// Final output implementation
always @(posedge clk) begin
    rotated_data <= temp_data;
    out <= xor_output[0] ^ rotated_data[0];
    q <= xor_output[1:100] ^ rotated_data[1:100];
end

endmodule

module top_module (
    input clk,
    input reset,
    input A, B, EN,
    input [3:0] parallel_in,
    input serial_in,
    output serial_out,
    output [3:0] final_output
);

    // 2-to-4 decoder
    wire [3:0] decoder_out;
    decoder_2to4 decoder_inst (
        .A(A),
        .B(B),
        .EN(EN),
        .Y(decoder_out)
    );

    // 4-bit shift register with parallel load and serial input/output
    wire [3:0] shift_reg_out;
    shift_reg_4bit shift_reg_inst (
        .clk(clk),
        .reset(reset),
        .parallel_in(parallel_in),
        .serial_in(serial_in),
        .serial_out(serial_out),
        .shift_reg_out(shift_reg_out)
    );

    // Bitwise AND operation
    assign final_output = decoder_out & shift_reg_out;

endmodule

// 2-to-4 decoder module
module decoder_2to4 (
    input A, B, EN,
    output [3:0] Y
);

    assign Y[0] = ~(A | B | EN);
    assign Y[1] = ~(A | ~B | EN);
    assign Y[2] = ~(~A | B | EN);
    assign Y[3] = ~(~A | ~B | EN);

endmodule

// 4-bit shift register module
module shift_reg_4bit (
    input clk,
    input reset,
    input [3:0] parallel_in,
    input serial_in,
    output serial_out,
    output [3:0] shift_reg_out
);

    reg [3:0] shift_reg;

    always @(posedge clk) begin
        if (reset) begin
            shift_reg <= 4'b0000;
        end else begin
            shift_reg <= {shift_reg[2:0], serial_in};
        end
    end

    assign shift_reg_out = shift_reg;
    assign serial_out = shift_reg[0];

    // Parallel load
    always @(parallel_in) begin
        if (EN) begin
            shift_reg <= parallel_in;
        end
    end

endmodule

module packet_buffer_bypass(
    input           clk,
    input           reset,
    output  [239:0] TRIG0,

    input       [63:0] in_data,
    input       [23:0] in_pkt_route,
    input           in_wr,
    output reg      in_empty,
    input           in_req,
    output reg      in_ack,

    output reg  [63:0] out_data,
    output reg  [23:0] out_pkt_route,
    output reg      out_wr,
    output reg      out_req,
    input           out_ack,
    output reg  [1:0] out_neighbor,
    output reg      out_bop,
    output reg      out_eop,
    input           out_rdy,
    output reg      out_bypass
);

// Internal signals
reg wea;
reg web;
reg [8:0] addra;
reg [8:0] addrb;
reg [31:0] dia;
reg [31:0] dib;
wire [31:0] doa;
wire [31:0] dob;
wire [3:0]  dipa;
wire [3:0]  dipb;

// RAM
RAM16_s36_s36_altera pm(
    .aclr_a (reset),
    .aclr_b (reset),
    .address_a (addra),
    .address_b (addrb),
    .clock_a (clk),
    .clock_b (clk),
    .data_a (dia),
    .data_b (dib),
    .wren_a (wea),
    .wren_b (web),
    .q_a (doa),
    .q_b (dob) 

); 

// Packet and buffer state variables
reg [7:0] pkt_len;
reg [7:0] send_len;
parameter   BUFF_EMPTY      = 3'b001,
            BUFF_RECV_PKT   = 3'b010,
            BUFF_SEND_REQ   = 3'b100,
            BUFF_SEND_PKT   = 3'b101,
            BUFF_SEND_CANCEL= 3'b110;
wire eop;
reg state_idle;
reg state_pkt_send;
reg need_process;

reg [2:0] buff_state;
reg [2:0] buff_state_next;

// State machine
always @(*)
begin
    buff_state_next = buff_state;
    in_ack = 0;
    out_req = 0;
    in_empty = 0;
    {wea, web} = 2'b00;
    out_wr = 0;
    state_idle = 0;
    state_pkt_send = 0;
    case(buff_state)
        BUFF_EMPTY: begin
            state_idle = 1;
            if(in_req) begin
                in_ack = 1;
                buff_state_next = BUFF_RECV_PKT;
            end else begin
                in_empty = 1;
            end
        end
        BUFF_RECV_PKT: begin
            in_ack = 1;
            if(in_wr) begin
                {wea, web} = 2'b11;
                {dia, dib} = in_data;
                addra = {pkt_len, 1'b0};
                addrb = {pkt_len, 1'b1};
                out_neighbor = in_pkt_route[1:0];
                out_bypass = in_pkt_route[5];
                out_pkt_route = {3'b000, in_pkt_route[23:3]};
            end
            if(!in_req) begin
                if(buff_state == BUFF_RECV_PKT && pkt_len > 0) begin
                    buff_state_next = BUFF_SEND_REQ;
                end else begin
                    buff_state_next = BUFF_EMPTY;
                end
            end
        end

        BUFF_SEND_REQ: begin
            out_req = 1;
            if(out_ack) begin
                buff_state_next = BUFF_SEND_PKT;
            end
        end

        BUFF_SEND_PKT: begin
            out_req = 1;
            state_pkt_send = 1;
            if(out_rdy) begin
                if(send_len <= pkt_len+1) begin
                    addra = {send_len, 1'b0};
                    addrb = {send_len, 1'b1};
                    out_data = {doa, dob};
                    out_wr = (send_len < 1) ? 0 : (send_len > pkt_len) ? 0 : 1;
                    out_bop = (send_len == 1) ? 1 : 0;
                    out_eop = (send_len == pkt_len) ? 1 : 0;
                end
            end
            if(eop) begin
                buff_state_next = BUFF_SEND_CANCEL;
            end
        end

        BUFF_SEND_CANCEL: begin
            out_req = 0;
            if(!out_ack) begin
                buff_state_next = BUFF_EMPTY;
            end
        end

        default: begin
            buff_state_next = BUFF_EMPTY;
        end
    endcase
end

// State updates
always @(posedge clk)
begin
    if(reset) begin
        buff_state <= 0;
    end else begin
        buff_state <= buff_state_next;
    end

    if(state_idle) begin
        pkt_len <= 0;
        send_len <= 0;
    end
    if(in_wr) begin
        pkt_len <= pkt_len + 1'b1;
    end

    if(state_pkt_send && out_rdy) begin
        send_len <= send_len + 1'b1;
    end
end

// End of packet detection
assign eop = (send_len == pkt_len+1) ? 1 : 0;

// Output signals
assign TRIG0[63:0] = in_data;
assign TRIG0[79:64] = in_pkt_route;
assign TRIG0[80] = in_wr;
assign TRIG0[81] = in_empty;
assign TRIG0[82] = in_req;
assign TRIG0[83] = in_ack;

assign TRIG0[147:84] = out_data;
assign TRIG0[163:148] = out_pkt_route;
assign TRIG0[164] = out_wr;
assign TRIG0[165] = out_req;
assign TRIG0[166] = out_ack;
assign TRIG0[168:167] = out_neighbor;
assign TRIG0[169] = out_bop;
assign TRIG0[170] = out_eop;
assign TRIG0[171] = out_rdy;

assign TRIG0[175:172] = dia[7:4];
assign TRIG0[179:176] = doa[7:4];

assign TRIG0[207:200] = pkt_len;
assign TRIG0[217:210] = send_len;
assign TRIG0[218] = eop;
assign TRIG0[219] = state_idle;
assign TRIG0[220] = state_pkt_send;

assign TRIG0[232:230] = buff_state;

endmodule

module priority_encoder_pipeline (
    input [3:0] in,
    output reg [1:0] pos
);

reg [3:0] in_reg1, in_reg2;
reg [1:0] pos_reg1, pos_reg2;

always @ (posedge clk) begin
    in_reg1 <= in;
    pos_reg1 <= pos;
    in_reg2 <= in_reg1;
    pos_reg2 <= pos_reg1;
end

always @ (posedge clk) begin
    if (in_reg2[3]) begin
        pos <= 2'b11;
    end else if (in_reg2[2]) begin
        pos <= 2'b10;
    end else if (in_reg2[1]) begin
        pos <= 2'b01;
    end else if (in_reg2[0]) begin
        pos <= 2'b00;
    end else begin
        pos <= 2'b00;
    end
end

endmodule

module fpoint_division(
    input reset,
    input enable,
    input clock,
    input [31:0] dividend,
    output reg [31:0] quotient
);

reg [31:0] divisor;
reg [7:0] exponent;
reg [22:0] mantissa;
reg sign;
reg normalized;
reg [31:0] dividend_shifted;
reg [31:0] remainder;
reg [31:0] divisor_shifted;
reg [31:0] quotient_shifted;
reg [4:0] count;
reg error;

// Extract sign, exponent, and mantissa from the input
assign sign = dividend[31];
assign exponent = dividend[30:23];
assign mantissa = dividend[22:0];

// Check if input is normalized
always @(*) begin
    if (exponent == 0 || exponent == 255) begin
        normalized = 0;
        error = 1;
    end
    else begin
        normalized = 1;
        error = 0;
    end
end

// Convert exponent to a signed integer
reg [31:0] exponent_signed;
assign exponent_signed = {8{sign}} & {exponent, 23'b0} - 127;

// Create divisor from exponent
always @(*) begin
    if (exponent_signed >= 0) begin
        divisor = {1'b1, mantissa, 23'b0} << exponent_signed;
    end
    else begin
        divisor = {1'b1, mantissa, 23'b0} >> -exponent_signed;
    end
end

always @(posedge clock) begin
    if (reset) begin
        count <= 0;
        quotient <= 0;
        remainder <= 0;
        divisor_shifted <= 0;
        quotient_shifted <= 0;
        dividend_shifted <= 0;
    end
    else if (enable) begin
        if (count == 0) begin
            // Align divisor with dividend
            dividend_shifted <= {1'b0, mantissa, 23'b0};
            remainder <= dividend_shifted;
            divisor_shifted <= divisor;
        end
        else begin
            // Shift divisor and quotient to the right
            divisor_shifted <= divisor_shifted >> 1;
            quotient_shifted <= quotient_shifted >> 1;
        end

        if (remainder >= divisor_shifted) begin
            // Subtract divisor from remainder
            remainder <= remainder - divisor_shifted;
            quotient_shifted <= {1'b1, quotient_shifted};
        end
        else begin
            quotient_shifted <= {1'b0, quotient_shifted};
        end

        if (count == 31) begin
            // Output quotient
            quotient <= quotient_shifted;
        end

        count <= count + 1;
    end
end

endmodule

module RFID_transmitter (
  input data,
  input clock,
  input enable,
  output tx_out
);

  reg [7:0] counter;
  reg [7:0] data_reg;
  reg tx_data;

  always @(posedge clock) begin
    if (enable) begin
      if (counter == 0) begin
        tx_data <= 1;
        data_reg <= data;
      end else if (counter == 7) begin
        tx_data <= 0;
      end
      counter <= counter + 1;
    end else begin
      tx_data <= 0;
      counter <= 0;
    end
  end

  always @(posedge clock) begin
    if (enable && counter == 0) begin
      tx_out <= 1;
    end else if (enable && counter == 15) begin
      tx_out <= 0;
    end else begin
      tx_out <= 0;
    end
  end

endmodule

module RFID_receiver (
  input rx_in,
  input clock,
  input enable,
  output data_out
);

  reg [7:0] counter;
  reg [7:0] data_reg;
  reg rx_data;

  always @(posedge clock) begin
    if (enable && counter == 0) begin
      rx_data <= rx_in;
    end else if (enable && counter == 7) begin
      rx_data <= 0;
    end
    counter <= counter + 1;
  end

  always @(posedge clock) begin
    if (enable && counter == 8) begin
      data_out <= data_reg;
      counter <= 0;
    end else if (!enable) begin
      counter <= 0;
    end
    if (rx_data && counter < 8) begin
      data_reg[counter] <= rx_in;
    end
  end

endmodule

module nor_gate(
    input a,
    input b,
    output out
);
    wire temp1, temp2;
    nand_gate nand1(a, a, temp1);
    nand_gate nand2(b, b, temp2);
    nand_gate nand3(temp1, temp2, out);
endmodule

module shift_register(
    input clk,
    input rst,
    input data,
    output reg [2:0] out
);
    reg [2:0] reg1, reg2, reg3;
    always @(posedge clk or negedge rst) begin
        if (~rst) begin
            reg1 <= 3'b0;
            reg2 <= 3'b0;
            reg3 <= 3'b0;
        end else begin
            reg1 <= data;
            reg2 <= reg1;
            reg3 <= reg2;
        end
    end
    assign out = reg3;
endmodule

module or_module(
    input a,
    input [2:0] b,
    output out
);
    wire temp;
    nor_gate nor1(a, b[0], temp);
    nor_gate nor2(temp, b[1], temp);
    nor_gate nor3(temp, b[2], out);
endmodule

module top_module(
    input a,
    input b,
    input clk,
    input rst,
    input data,
    output out
);
    wire [2:0] shift_out;
    shift_register shift_reg(clk, rst, data, shift_out);
    or_module or_mod(nor_out, shift_out, out);
    nor_gate nor_gate_inst(a, b, nor_out);
    assign nor_out = ~nor_gate_inst.out;
endmodule

module alt_priority_encoder(
    input [7:0] data,
    output reg [2:0] q
);

reg [3:0] ms_nibble;
wire [1:0] ls_nibble_enc;

// Extract most significant nibble
assign ms_nibble = data[7:4];

// Priority encoder for least significant nibble
priority_encoder_4bit ls_nibble_enc_inst(
    .data(data[3:0]),
    .q(ls_nibble_enc)
);

// Output logic
always @(*) begin
    if (ms_nibble == 4'b0000) begin
        q = 3'b000;
    end else if (ms_nibble[3] == 1'b1) begin
        q[2:1] = ~ms_nibble[3:2];
        q[0] = ~ms_nibble[1];
    end else if (ms_nibble[2] == 1'b1) begin
        q[2:1] = ~ms_nibble[2:1];
        q[0] = ~ms_nibble[3];
    end else if (ms_nibble[1] == 1'b1) begin
        q[2:1] = ~ms_nibble[3:2];
        q[0] = ~ms_nibble[0];
    end else if (ms_nibble[0] == 1'b1) begin
        q[2:1] = ~ms_nibble[2:1];
        q[0] = ~ms_nibble[1];
    end else begin
        q = {1'b0, ls_nibble_enc};
    end
end

endmodule

module priority_encoder_4bit(
    input [3:0] data,
    output reg [1:0] q
);

always @(*) begin
    case (data)
        4'b0001: q = 2'b00;
        4'b0010: q = 2'b01;
        4'b0100: q = 2'b10;
        4'b1000: q = 2'b11;
        default: q = 2'b00;
    endcase
end

endmodule

module messbauer_test_environment
(
    input wire global_clock,                     // 50 MHz GCLK, T8
    input wire global_reset,                     // L3 as Button
    // Left Side of AX309 Board
    output wire v1_channel,                      // F16
    output wire v1_start,                        // E16
	 output wire [11:0] v1_velocity_reference,
    output wire v1_lower_threshold,              // C10
    output wire v1_upper_threshold,              // D16
    // Right Side of AX309 Board
    output wire v2_channel,                      // L16
    output wire v2_start,                        // M15
	 output wire [11:0] v2_velocity_reference,
    output wire v2_lower_threshold,              // R16
    output wire v2_upper_threshold               // T14
);

reg internal_reset;
reg [5:0] counter;

// Left Side (v1) interface
// Start, Channel generation
messbauer_generator #(.CHANNEL_NUMBER(512), .CHANNEL_TYPE(1)) v1_generator(.aclk(global_clock), .areset_n(global_reset & internal_reset), .start(v1_start), .channel(v1_channel));
// Saw tooth generation (velocity refence signal)
messbauer_saw_tooth_generator #(.DIRECT_SLOPE_DURATION(512)) v1_velocity_reference_generator(.clk(global_clock), .areset_n(global_reset & internal_reset), .out_value(v1_velocity_reference));
// Signals 4 testing Differntial discriminator test
messbauer_diff_discriminator_signals v1_diff_discriminator(.aclk(global_clock), .areset_n(global_reset & internal_reset), .channel(v1_channel), .lower_threshold(v1_lower_threshold), .upper_threshold(v1_upper_threshold));

// Right Side (v1) interface
// Start, Channel generation
messbauer_generator #(.CHANNEL_NUMBER(512), .CHANNEL_TYPE(2)) v2_generator(.aclk(global_clock), .areset_n(global_reset & internal_reset), .start(v2_start), .channel(v2_channel));
// Saw tooth generation (velocity refence signal)
messbauer_saw_tooth_generator #(.DIRECT_SLOPE_DURATION(512)) v2_velocity_reference_generator(.clk(global_clock), .areset_n(global_reset & internal_reset), .out_value(v2_velocity_reference));
// Signals 4 testing Differntial discriminator test
messbauer_diff_discriminator_signals v2_diff_discriminator(.aclk(global_clock), .areset_n(global_reset & internal_reset), .channel(v2_channel), .lower_threshold(v2_lower_threshold), .upper_threshold(v2_upper_threshold));

// Reset generation
always @(posedge global_clock)
begin
     if(~global_reset)
     begin
         internal_reset <= 1;
          counter <= 0;
     end
     if(counter < 16)
         counter <= counter + 1'b1;
     if(counter >= 16 && counter < 32)
     begin
         counter <= counter + 1'b1;
          internal_reset <= 0;
     end
     if(counter == 32)
         internal_reset <= 1;
end

endmodule

