module combined_module (
    input clk,
    input reset,
    input [7:0] data_in,
    input [31:0] in,
    input valid_a,
    input ready_b,
    output ready_a,
    output reg valid_b,
    output reg [9:0] data_out,
    output [31:0] out
);

// Instantiate accu module
reg [7:0] accu_reg = 8'h00;
wire accu_valid;
wire accu_ready;
accu accu_inst (
    .clk(clk),
    .reset(reset),
    .data_in(data_in),
    .valid(accu_valid),
    .ready(accu_ready),
    .data_out(accu_reg)
);

// Instantiate top_module module
reg [31:0] top_reg = 32'h00000000;
wire top_valid;
wire top_ready;
wire [31:0] top_out;
top_module top_inst (
    .clk(clk),
    .reset(reset),
    .in(in),
    .valid(top_valid),
    .ready(top_ready),
    .out(top_out)
);

// Pipeline registers
reg [7:0] accu_reg1;
reg [31:0] top_reg1;
reg valid_b1;
reg [9:0] data_out1;

always @(posedge clk) begin
    if (reset) begin
        accu_reg1 <= 8'h00;
        top_reg1 <= 32'h00000000;
        valid_b1 <= 1'b0;
        data_out1 <= 10'h000;
    end else begin
        accu_reg1 <= accu_reg;
        top_reg1 <= top_reg;
        valid_b1 <= valid_b;
        data_out1 <= data_out;
    end
end

// Output logic
always @(posedge clk) begin
    if (reset) begin
        valid_b <= 1'b0;
        data_out <= 32'h00000000;
    end else begin
        // Check if both upstream modules are ready
        if (valid_a && accu_ready && top_ready) begin
            // Accumulate data and check for 8 inputs
            if (accu_valid) begin
                accu_reg <= accu_reg + data_in;
                if (accu_reg1 == 8'hFF) begin
                    data_out <= {1'b1, top_out[31], top_out[30], top_out[29], top_out[28], top_out[27], top_out[26], top_out[25], accu_reg + 8'h01};
                    valid_b <= 1'b1;
                end else begin
                    data_out <= {1'b0, top_out[31], top_out[30], top_out[29], top_out[28], top_out[27], top_out[26], top_out[25], accu_reg};
                    valid_b <= 1'b1;
                end
            end else begin
                data_out <= {1'b0, top_out[31], top_out[30], top_out[29], top_out[28], top_out[27], top_out[26], top_out[25], accu_reg};
                valid_b <= 1'b1;
            end
        end else begin
            data_out <= data_out1;
            valid_b <= valid_b1;
        end
    end
end

// Handshake logic
assign ready_a = (!valid_a || (valid_a && valid_b && ready_b));
assign top_ready = (!valid_a || (valid_a && valid_b && ready_b));
assign accu_ready = (!valid_a || (valid_a && valid_b && ready_b));
assign top_inst.valid = top_ready;
assign accu_inst.valid = accu_ready;

endmodule

