module LIN_transmitter (
  input [12:0] data_in,
  input [3:0] id,
  input parity,
  input en,
  output tx_success
);

  reg [17:0] packet;
  reg tx_start;
  reg [3:0] header;
  reg [7:0] crc;
  wire [7:0] crc_calc;

  assign crc_calc = crc8({header, data_in});

  always @(posedge en) begin
    if (tx_start) begin
      tx_success <= 0;
      tx_start <= 0;
    end else begin
      tx_success <= 1;
      tx_start <= 1;
      packet <= {header, data_in, crc};
    end
  end

  always @(*) begin
    header = {1'b0, parity, id};
    crc = crc_calc;
  end

endmodule

module LIN_receiver (
  input [12:0] data_out,
  input [3:0] id_out,
  input parity_out,
  output rx_success,
  output parity_success,
  output id_success,
  output [12:0] data_received
);

  reg [17:0] packet;
  reg rx_start;
  reg [3:0] header;
  reg [7:0] crc;
  wire [7:0] crc_calc;

  assign crc_calc = crc8({header, data_received});

  always @(posedge data_out) begin
    if (rx_start) begin
      rx_success <= 0;
      parity_success <= 0;
      id_success <= 0;
      rx_start <= 0;
    end else begin
      rx_success <= 1;
      rx_start <= 1;
      packet <= data_out;
    end
  end

  always @(*) begin
    header = {1'b0, parity_out, id_out};
    crc = crc_calc;
    data_received = packet[15:3];
    if (packet[2:0] != id_out) begin
      id_success <= 0;
    end else begin
      id_success <= 1;
    end
    if (packet[16:9] != crc) begin
      parity_success <= 0;
    end else begin
      parity_success <= 1;
    end
  end

endmodule

