module parity_generator (
    input [7:0] in,
    input clk,
    output reg [8:0] out);

    reg [2:0] state;
    reg parity_bit;

    always @(posedge clk) begin
        case (state)
            3'b000: begin // Wait for input
                out <= {in, 1'b0};
                state <= 3'b001;
            end
            3'b001: begin // Calculate parity
                parity_bit <= ~(in[0] ^ in[1] ^ in[2] ^ in[3] ^ in[4] ^ in[5] ^ in[6] ^ in[7]);
                state <= 3'b010;
            end
            3'b010: begin // Output byte with parity bit
                out <= {in, parity_bit};
                state <= 3'b000;
            end
        endcase
    end

endmodule

