module GPIO(input clk,
            input rst,
            input Start,
            input EN,
            input [31:0] P_Data,
            output reg [1:0] counter_set,
            output [15:0] LED_out,
            output wire ledclk,
            output wire ledsout,
            output wire ledclrn,
            output wire LEDEN,
            output reg [13:0] GPIOf0);

    reg [31:0] counter;
    reg [31:0] timer;
    reg [3:0] timer_tick;
    reg [1:0] display_mode;
    reg [15:0] LED_value;
    reg [1:0] LED_digit;
    reg [13:0] GPIO_value;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            LED_value <= 0;
            LED_digit <= 0;
            timer <= 0;
            timer_tick <= 0;
            display_mode <= 0;
            GPIOf0 <= 0;
        end else begin
            GPIOf0 <= P_Data[13:0];
            if (Start) begin
                counter <= P_Data;
            end
            if (EN) begin
                if (display_mode == 0) begin
                    LED_value <= counter;
                end else begin
                    LED_value <= timer;
                end
            end
            if (ledsout) begin
                ledclk <= 1;
            end else begin
                ledclk <= 0;
            end
            if (ledclrn) begin
                LED_digit <= 0;
            end
            if (LEDEN) begin
                LED_digit <= LED_digit + 1;
                if (LED_digit == 2) begin
                    LED_digit <= 0;
                    if (display_mode == 0) begin
                        display_mode <= 1;
                        timer <= 0;
                    end else begin
                        display_mode <= 0;
                    end
                end
            end
            if (display_mode == 1) begin
                if (timer_tick == 15) begin
                    timer <= timer + 1;
                    timer_tick <= 0;
                end else begin
                    timer_tick <= timer_tick + 1;
                end
            end
            if (counter == 32'hFFFFFFFF) begin
                counter <= 0;
            end else begin
                counter <= counter + 1;
            end
        end
    end

    always @(posedge ledclk) begin
        case(LED_digit)
            2'd0: LED_out <= {4'b1111, LED_value[3:0]};
            2'd1: LED_out <= {4'b1110, LED_value[7:4]};
            2'd2: LED_out <= {4'b1101, LED_value[11:8]};
            2'd3: LED_out <= {4'b1011, LED_value[15:12]};
        endcase
    end

    assign GPIOf0[14:0] = {1'b0, EN, Start, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0};

    assign GPIOf0[13] = counter_set[1];
    assign GPIOf0[12] = counter_set[0];

    always @(GPIOf0) begin
        if (GPIOf0[0]) begin
            counter_set <= 2'b01;
        end else begin
            counter_set <= 2'b00;
        end
    end

endmodule

