module sqrt_pipelined (
  input clk,
  input reset_n,
  input start,
  input [3:0] radicand,
  output reg data_valid,
  output reg [2:0] root
);

  reg [3:0] count;
  reg [3:0] remainder;
  reg [3:0] temp;
  reg [2:0] int_part;
  reg [1:0] frac_part;
  reg [3:0] x;
  reg [1:0] y;
  reg [1:0] z;
  reg [3:0] x_next;
  reg [1:0] y_next;
  reg [1:0] z_next;
  reg [1:0] q;
  reg [2:0] r;

  // Binary search stage
  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      count <= 0;
      remainder <= 0;
      temp <= 0;
      int_part <= 0;
    end else if (start) begin
      count <= 3;
      remainder <= radicand;
      temp <= 0;
      int_part <= 0;
    end else if (count > 0) begin
      temp <= {remainder, 2'b0};
      remainder <= temp - ((int_part << 1) + 1);
      int_part <= {int_part[1:0], 1'b0} | (temp >= ((int_part << 2) + (int_part << 1) + 1));
      count <= count - 1;
    end else begin
      count <= 0;
      remainder <= 0;
      temp <= 0;
      int_part <= {int_part[1:0], 1'b0} | (remainder >= ((int_part << 2) + (int_part << 1) + 1));
    end
  end

  // Linear interpolation stage
  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      x <= 0;
      y <= 0;
      z <= 0;
      frac_part <= 0;
      q <= 0;
      r <= 0;
    end else if (start && int_part != 0) begin
      x <= int_part;
      y <= 1;
      z <= remainder;
      frac_part <= 0;
      q <= 0;
      r <= 0;
    end else if (int_part != 0) begin
      x_next <= x - (y << 1);
      y_next <= y + 2;
      z_next <= (z << 2) - ((x << 2) + (x << 1) + y_next);
      q <= (z_next >= 0) ? 1'b1 : 1'b0;
      r <= (q == 1'b1) ? z_next : z;
      x <= x_next;
      y <= y_next;
      z <= r;
      frac_part <= frac_part | (q << (1 - frac_part));
    end else begin
      frac_part <= 0;
    end
  end

  // Output stage
  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      data_valid <= 0;
      root <= 0;
    end else if (start && int_part != 0) begin
      data_valid <= 0;
      root <= 0;
    end else if (int_part != 0) begin
      data_valid <= 1;
      root <= {int_part, frac_part};
    end else begin
      data_valid <= 0;
      root <= 0;
    end
  end

endmodule

module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] a,    // 8-bit input for a
    input [7:0] b,    // 8-bit input for b
    input ctrl,       // Control input for signed or unsigned multiplication
    output [7:0] q    // 8-bit output for the sum of two Gray codes
);

    // Instantiate the multiplier module
    multiplier_8bit multiplier(
        .a(a),
        .b(b),
        .ctrl(ctrl),
        .c(mult_out)
    );

    // Instantiate the binary-to-Gray code converter module
    bin_to_gray_converter gray_converter(
        .BIN(mult_out),
        .GRAY(gray_out)
    );

    // Instantiate the Gray code adder module
    gray_adder adder(
        .a(gray_out),
        .b(gray_out),
        .sum(gray_sum)
    );

    // Instantiate the Gray code-to-binary converter module
    gray_to_bin_converter bin_converter(
        .GRAY(gray_sum),
        .BIN(q)
    );

    // Internal wires
    wire [15:0] mult_out;
    wire [3:0] gray_out;
    wire [3:0] gray_sum;

endmodule

// Multiplier module
module multiplier_8bit (
    input [7:0] a,
    input [7:0] b,
    input ctrl,
    output reg [15:0] c
);

    always @(*) begin
        if (ctrl == 0) begin
            c = a * b;  // Unsigned multiplication
        end else begin
            c = $signed(a) * $signed(b);  // Signed multiplication
        end
    end

endmodule

// Binary-to-Gray code converter module
module bin_to_gray_converter (
    input [15:0] BIN,
    output reg [3:0] GRAY
);

    always @(*) begin
        GRAY[0] = BIN[0];
        GRAY[1] = BIN[1] ^ BIN[0];
        GRAY[2] = BIN[2] ^ BIN[1];
        GRAY[3] = BIN[3] ^ BIN[2];
    end

endmodule

// Gray code adder module
module gray_adder (
    input [3:0] a,
    input [3:0] b,
    output reg [3:0] sum
);

    always @(*) begin
        sum[0] = a[0] ^ b[0];
        sum[1] = a[1] ^ b[1] ^ sum[0];
        sum[2] = a[2] ^ b[2] ^ sum[1];
        sum[3] = a[3] ^ b[3] ^ sum[2];
    end

endmodule

// Gray code-to-binary converter module
module gray_to_bin_converter (
    input [3:0] GRAY,
    output reg [7:0] BIN
);

    always @(*) begin
        BIN[0] = GRAY[0];
        BIN[1] = GRAY[1] ^ BIN[0];
        BIN[2] = GRAY[2] ^ BIN[1];
        BIN[3] = GRAY[3] ^ BIN[2];
        BIN[4] = BIN[3];
        BIN[5] = BIN[4];
        BIN[6] = BIN[5];
        BIN[7] = BIN[6];
    end

endmodule

module bit_reverse(
    input [31:0] in,
    output [31:0] out
);
    genvar i;
    generate
        for (i = 0; i < 32; i = i + 1) begin : reverse_loop
            assign out[i] = in[31 - i];
        end
    endgenerate
endmodule

module bitwise_or(
    input [31:0] in1,
    input [31:0] in2,
    output [31:0] out
);
    assign out = in1 | in2;
endmodule

module top_module(
    input [31:0] in,
    input a,
    input b,
    input sel_b1,
    input sel_b2,
    output [31:0] out
);
    wire [31:0] reversed_in;
    bit_reverse reverse_module(.in(in), .out(reversed_in));
    wire [31:0] mux_out;
    assign mux_out = (sel_b1 & sel_b2) ? reversed_in : a;
    bitwise_or or_module(.in1(mux_out), .in2(b), .out(out));
endmodule

module SRFF_sp(
  input   clock,
  input   reset,
  input   io_input_set,
  input   io_input_reset,
  input   io_input_asyn_reset,
  output  io_output_data
);
  reg  _T_14;
  reg [31:0] _GEN_0;
  wire  _T_18;
  wire  _T_19;
  wire  _T_20;
  wire  _T_22;
  assign io_output_data = _T_22;
  assign _T_18 = io_input_reset ? 1'h0 : _T_14;
  assign _T_19 = io_input_set ? 1'h1 : _T_18;
  assign _T_20 = io_input_asyn_reset ? 1'h0 : _T_19;
  assign _T_22 = io_input_asyn_reset ? 1'h0 : _T_14;
`ifdef RANDOMIZE
  integer initvar;
  initial begin
    `ifndef verilator
      #0.002 begin end
    `endif
  `ifdef RANDOMIZE_REG_INIT
  _GEN_0 = {1{$random}};
  _T_14 = _GEN_0[0:0];
  `endif
  end
`endif
  always @(posedge clock) begin
    if (reset) begin
      _T_14 <= 1'h0;
    end else begin
      if (io_input_asyn_reset) begin
        _T_14 <= 1'h0;
      end else begin
        if (io_input_set) begin
          _T_14 <= 1'h1;
        end else begin
          if (io_input_reset) begin
            _T_14 <= 1'h0;
          end
        end
      end
    end
  end
endmodule

module binary_to_gray(
  input [7:0] bin_in,
  output [7:0] gray_out
);

  // Create a 8-bit wire to store the previous value of bin_in
  wire [7:0] prev_bin_in;

  // Create a 8-bit wire to store the xor of bin_in and prev_bin_in
  wire [7:0] xor_out;

  // Create a 8-bit wire to store the gray code output
  wire [7:0] gray_temp;

  // Create a 8-bit wire to store the previous value of gray_out
  wire [7:0] prev_gray_out;

  // Assign the xor output to the input xor with the previous input
  assign xor_out = bin_in ^ prev_bin_in;

  // Assign the gray code output to the xor output xor with the previous gray code output
  assign gray_temp = xor_out ^ prev_gray_out;

  // Assign the gray code output to the gray_temp
  assign gray_out = gray_temp;

  // Assign the current input to the previous input
  assign prev_bin_in = bin_in;

  // Assign the current gray code output to the previous gray code output
  assign prev_gray_out = gray_out;

endmodule

module shift_register_with_parallel_load(clk, load, parallel_in, shift_in, parallel_out, serial_out);

  parameter WIDTH = 4;

  input clk, load, shift_in;
  input [WIDTH-1:0] parallel_in;
  output [WIDTH-1:0] parallel_out;
  output serial_out;

  reg [WIDTH-1:0] shift_reg;

  always @(posedge clk) begin
    if (load) begin
      shift_reg <= parallel_in;
    end else begin
      shift_reg <= {shift_reg[WIDTH-2:0], shift_in};
    end
  end

  assign parallel_out = shift_reg;
  assign serial_out = shift_reg[0];

endmodule

module shift_register ( input clk, input d, output q );

  reg [2:0] reg_out;
  wire [2:0] reg_in;

  // Master-slave D flip-flop
  always @(posedge clk) begin
    reg_out <= reg_in;
  end

  // Pipeline structure
  assign reg_in = {reg_out[1:0], d};

  assign q = reg_out[2];

endmodule

module shift_register(
    input clk,
    input areset,  // async active-high reset to zero
    input load,
    input ena,
    input [3:0] data,
    output reg [3:0] q);

    reg [1:0] counter;
    reg [3:0] shift_reg;

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            counter <= 2'b0;
            shift_reg <= 4'b0;
        end else begin
            if (ena) begin
                if (load) begin
                    shift_reg <= data;
                end else begin
                    counter <= counter + 1;
                    shift_reg <= {shift_reg[2:0], data[0]};
                end
            end
        end
    end

    always @* begin
        case (counter)
            2'b00: q = shift_reg[0];
            2'b01: q = shift_reg[1];
            2'b10: q = shift_reg[2];
            2'b11: q = shift_reg[3];
        endcase
    end

endmodule

module top_module(
    input clk,
    input areset,  // async active-high reset to zero
    input load,
    input ena,
    input [3:0] data,
    output reg [3:0] q);

    shift_register sr(
        .clk(clk),
        .areset(areset),
        .load(load),
        .ena(ena),
        .data(data),
        .q(q)
    );

endmodule

module dff_reset (
    input D,
    input RESET_B,
    input CLK,
    output reg Q,
    output reg Q_B
);

    always @(posedge CLK, negedge RESET_B) begin
        if (!RESET_B) begin
            Q <= 0;
            Q_B <= 1;
        end else begin
            Q <= D;
            Q_B <= ~D;
        end
    end

endmodule

