module top_module (
    input a,
    input b,
    input sel,
    output z
);

    wire mux_out;
    wire xor_in1, xor_in2;

    // 2-to-1 multiplexer
    mux_2to1 mux_inst (
        .a(a),
        .b(b),
        .sel(sel),
        .mux_out(mux_out)
    );

    // XOR gate
    xor_gate xor_inst (
        .xor_in1(mux_out),
        .xor_in2(sel),
        .xor_out(z)
    );

endmodule

module mux_2to1 (
    input a,
    input b,
    input sel,
    output mux_out
);

    assign mux_out = (sel == 1'b0) ? a : b;

endmodule

module xor_gate (
    input xor_in1,
    input xor_in2,
    output xor_out
);

    assign xor_out = xor_in1 ^ xor_in2;

endmodule

module sky130_fd_sc_hdll__dlrtn (
    Q      ,
    RESET_B,
    D      ,
    GATE_N
);

    // Module ports
    output Q      ;
    input  RESET_B;
    input  D      ;
    input  GATE_N ;

    // Local signals
    wire RESET          ;
    wire GATE           ;
    wire D_delayed      ;
    wire GATE_N_delayed ;
    wire RESET_delayed  ;
    wire RESET_B_delayed;
    wire buf_Q          ;
    wire awake          ;

    //                                       Name     Output  Other arguments
    not                                      not0    (RESET , RESET_B_delayed                             );
    not                                      not1    (GATE  , GATE_N_delayed                              );
    and                                      and0    (RESET_B_delayed, GATE_N, GATE                        );
    and                                      and1    (buf_Q, GATE_N_delayed, RESET_B_delayed, D_delayed    );
    sky130_fd_sc_hdll__dlatch$PR_pp$PG$N dlatch0 (Q     , buf_Q, GATE, RESET, awake, VPWR, VGND);
    sky130_fd_sc_hdll__dlatch$PR_pp$PG$N dlatch1 (buf_Q , D_delayed, and0, RESET, awake, VPWR, VGND);
    sky130_fd_sc_hdll__udp_inv$NI_PP_1_0     inv0    (RESET_delayed, RESET);
    sky130_fd_sc_hdll__udp_inv$NI_PP_1_0     inv1    (GATE_N_delayed, GATE );
    sky130_fd_sc_hdll__udp_inv$NI_PP_1_0     inv2    (RESET_B_delayed, RESET_B);

    assign awake = ( VPWR === 1'b1 );
    assign RESET_delayed = RESET;
    assign GATE_N_delayed = GATE;
    assign RESET_B_delayed = RESET_B;
    assign D_delayed = D;

endmodule

module top_module(
    input a,
    input b,
    input sel_b1,
    input sel_b2,
    output reg out_always,
    output out);

    wire mux_out, nor_out;
    wire [1:0] nand_in;

    // 2-to-1 Multiplexer
    mux_2to1 mux(
        .a(a),
        .b(b),
        .sel(sel_b1),
        .out(mux_out)
    );

    // NOR Gate using NAND gates
    nand nand1(
        .a(mux_out),
        .b(mux_out),
        .out(nand_in[0])
    );

    nand nand2(
        .a(nand_in[0]),
        .b(nand_in[0]),
        .out(nor_out)
    );

    // Bitwise AND operation
    and and_gate(
        .a(nor_out),
        .b(out_always),
        .out(out)
    );

endmodule

// 2-to-1 Multiplexer
module mux_2to1(
    input a,
    input b,
    input sel,
    output reg out
);

    always @(*) begin
        if(sel == 1'b0) begin
            out = a;
        end else begin
            out = b;
        end
    end

endmodule

// NAND Gate
module nand(
    input a,
    input b,
    output reg out
);

    always @(*) begin
        out = ~(a & b);
    end

endmodule

// Bitwise AND Gate
module and(
    input [1:0] a,
    input [1:0] b,
    output reg [1:0] out
);

    always @(*) begin
        out = a & b;
    end

endmodule

module mux_4to1(
  input [3:0] in,
  input [1:0] sel,
  output reg out
);

always @(*)
begin
  case(sel)
    2'b00: out = in[0];
    2'b01: out = in[1];
    2'b10: out = in[2];
    2'b11: out = in[3];
  endcase
end

endmodule

module shift_register (
    input clk,
    input SH_EN,
    input LD_EN,
    input [7:0] DATA_IN,
    output [7:0] SER_OUT,
    output [7:0] PAR_OUT
);

reg [7:0] shift_reg;

always @(posedge clk) begin
    if (LD_EN) begin
        shift_reg <= DATA_IN;
    end else if (SH_EN) begin
        shift_reg <= {shift_reg[6:0], shift_reg[7]};
    end
end

assign PAR_OUT = shift_reg;
assign SER_OUT = shift_reg[0];

endmodule

module bitwise_or_logical_or(
    input [2:0] a,
    input [2:0] b,
    output [2:0] out_or_bitwise,
    output out_or_logical,
    output [5:0] out_not
);

    assign out_or_bitwise = a | b;
    assign out_or_logical = (a != 0) || (b != 0);
    assign out_not = ~{a, b};

endmodule

module and_or_xor(
    input [99:0] in,
    output out_and,
    output out_or,
    output out_xor
);

    wire [49:0] and_out;
    wire [49:0] or_out;
    wire [98:0] xor_out;

    genvar i;
    generate
        for (i = 0; i < 50; i = i + 1) begin : and_gate
            and_gate and_inst(
                .a(in[i*2]),
                .b(in[i*2+1]),
                .y(and_out[i])
            );
        end

        for (i = 0; i < 50; i = i + 1) begin : or_gate
            or_gate or_inst(
                .a(in[i*2]),
                .b(in[i*2+1]),
                .y(or_out[i])
            );
        end

        for (i = 0; i < 99; i = i + 1) begin : xor_gate
            xor_gate xor_inst(
                .a(in[i]),
                .b(in[i+1]),
                .y(xor_out[i])
            );
        end
    endgenerate

    assign out_and = &and_out;
    assign out_or = |or_out;
    assign out_xor = ^xor_out;

endmodule

module top_module( 
    input [2:0] a,
    input [2:0] b,
    output [2:0] out_or_bitwise,
    output out_or_logical,
    output [5:0] out_not,
    input [99:0] in,
    output out_and,
    output out_or,
    output out_xor,
    output [2:0] final_output
);

    bitwise_or_logical_or bitwise_or_logical_or_inst(
        .a(a),
        .b(b),
        .out_or_bitwise(out_or_bitwise),
        .out_or_logical(out_or_logical),
        .out_not(out_not)
    );

    and_or_xor and_or_xor_inst(
        .in(in),
        .out_and(out_and),
        .out_or(out_or),
        .out_xor(out_xor)
    );

    assign final_output = out_or_bitwise + out_or_bitwise;

endmodule

module my_nor4 (
    Y  ,
    A  ,
    B  ,
    C  ,
    D_N
);

    output Y  ;
    input  A  ;
    input  B  ;
    input  C  ;
    input  D_N;

    wire AB, CD, ABCD;

    assign AB = ~(A | B);
    assign CD = ~(C | D_N);
    assign ABCD = ~(AB | CD);

    assign Y = ABCD;

endmodule

module sub_func (
    input [15:0] in_0,
    input [15:0] in_1,
    output reg [15:0] out_diff
);
    always @ (in_0, in_1) begin
        out_diff <= in_0 - in_1;
    end
endmodule

module mux_4to1 (
    input [15:0] in_0,
    input [15:0] in_1,
    input [15:0] in_2,
    input [15:0] in_3,
    input [1:0] sel,
    output reg [15:0] out_mux
);
    always @ (sel, in_0, in_1, in_2, in_3) begin
        case (sel)
            2'b00: out_mux <= in_0;
            2'b01: out_mux <= in_1;
            2'b10: out_mux <= in_2;
            2'b11: out_mux <= in_3;
        endcase
    end
endmodule

