module counter(
  input clk,
  input reset,
  output [3:0] count
);

reg [3:0] count_reg;

always @(posedge clk) begin
  if (reset) begin
    count_reg <= 4'b0000;
  end else begin
    count_reg <= count_reg + 1;
  end
end

assign count = count_reg;

endmodule


module counter_top(
  input clk,
  input reset,
  output reg [4:0] count
);

wire [3:0] count1, count2;

counter c1(
  .clk(clk),
  .reset(reset),
  .count(count1)
);

counter c2(
  .clk(clk),
  .reset(reset),
  .count(count2)
);

always @(posedge clk) begin
  count <= count1 + count2;
end

endmodule

module calculator(
    input clk,
    input rst,
    input [1:0] op,
    input [7:0] in,
    output reg [3:0] out
);

reg [3:0] a;
reg [3:0] b;
reg [3:0] result;
reg [3:0] temp;

always @(posedge clk) begin
    if (rst) begin
        out <= 4'b0000;
    end else begin
        a <= in[3:0];
        b <= in[7:4];
        case (op)
            2'b00: result <= a + b;
            2'b01: result <= a - b;
            2'b10: result <= a * b;
            2'b11: result <= a / b;
        endcase
        out <= result;
    end
end

endmodule

module mag_comp(
    input [3:0] A,
    input [3:0] B,
    output EQ,
    output GT,
    output LT
);

    reg EQ, GT, LT;

    always @(*) begin
        case(A > B)
            1'b0: begin
                EQ = (A == B);
                GT = 1'b0;
                LT = 1'b1;
            end
            1'b1: begin
                EQ = 1'b0;
                GT = 1'b1;
                LT = 1'b0;
            end
        endcase
    end

endmodule

module chris_pipelined (
		input  wire [3:0]  avs_s0_address,       //   avs_s0.address
		input  wire        avs_s0_read,          //         .read
		output wire [31:0] avs_s0_readdata,      //         .readdata
		output wire        avs_s0_readdatavalid, //         .readdatavalid
		input  wire        avs_s0_write,         //         .write
		input  wire [31:0] avs_s0_writedata,     //         .writedata
		output wire        avs_s0_waitrequest,   //         .waitrequest
		input  wire [3:0]  avs_s0_byteenable,    //         .byteenable
		input  wire        clock_clk,            //    clock.clk
		input  wire        reset_reset,          //    reset.reset
		output wire        ins_irq0_irq          // ins_irq0.irq
	);

	reg [31:0] pipeline_reg1_readdata;
	reg [31:0] pipeline_reg2_readdata;
	reg [3:0]  pipeline_reg1_address;
	reg [3:0]  pipeline_reg2_address;
	reg        pipeline_reg1_read;
	reg        pipeline_reg2_read;
	reg        pipeline_reg1_write;
	reg        pipeline_reg2_write;
	reg [31:0] pipeline_reg1_writedata;
	reg [31:0] pipeline_reg2_writedata;
	reg        pipeline_reg1_byteenable;
	reg        pipeline_reg2_byteenable;
	reg        pipeline_reg1_valid;
	reg        pipeline_reg2_valid;
	reg        pipeline_busy;
	reg        pipeline_reset;

	// Pipeline registers
	always @(posedge clock_clk) begin
		if (pipeline_reset) begin
			pipeline_reg1_readdata <= 32'b0;
			pipeline_reg2_readdata <= 32'b0;
			pipeline_reg1_address <= 4'b0;
			pipeline_reg2_address <= 4'b0;
			pipeline_reg1_read <= 1'b0;
			pipeline_reg2_read <= 1'b0;
			pipeline_reg1_write <= 1'b0;
