module decoder_2to4 (
    input A,
    input B,
    output reg Y0,
    output reg Y1,
    output reg Y2,
    output reg Y3
);
    always @* begin
        Y0 = ~(A | B);
        Y1 = ~(A | ~B);
        Y2 = ~(~A | B);
        Y3 = ~(~A | ~B);
    end
endmodule

module barrel_shifter (
    input [3:0] D,
    input [1:0] S,
    input shift_right,
    output reg [3:0] Q
);
    always @* begin
        case (S)
            2'b00: Q = D; // No shift
            2'b01: Q = shift_right ? {D[3], D[3:1]} : {D[2:0], D[3]}; // Shift 1 bit
            2'b10: Q = shift_right ? {D[3:2], D[3:1]} : {D[1:0], D[3:2]}; // Shift 2 bits
            2'b11: Q = shift_right ? {D[3:3], D[3:2]} : {D[2:1], D[3:0]}; // Shift 3 bits
        endcase
    end
endmodule

module final_output_module (
    input Y0,
    input Y1,
    input Y2,
    input Y3,
    input [3:0] shifted_data,
    output reg [3:0] final_output
);
    always @* begin
        final_output = {Y3, Y2, Y1, Y0} | shifted_data;
    end
endmodule

module adc_spi(
    input clk,
    input rst,
    input [7:0] adc_d,
    input adc_clk,
    input spi_clk,
    input [15:0] spi_frame_delay,
    input [15:0] spi_freq_divisor,
    input spi_frame,
    input spi_din,
    output reg spi_dout,
    output reg adc_read,
    output reg debug
);

reg [15:0] spi_clk_divider;
reg [15:0] spi_frame_counter;
reg [15:0] spi_delay_counter;
reg spi_output_en;

always @(posedge clk) begin
    if (rst) begin
        spi_clk_divider <= 0;
        spi_frame_counter <= 0;
        spi_delay_counter <= 0;
        spi_output_en <= 0;
        spi_dout <= 0;
        adc_read <= 0;
        debug <= 0;
    end else begin
        // ADC read
        if (spi_frame_counter == spi_frame_delay) begin
            adc_read <= 1;
            debug <= 1;
        end else begin
            adc_read <= 0;
            debug <= 0;
        end

        // SPI clock divider
        if (spi_clk_divider == spi_freq_divisor - 1) begin
            spi_clk_divider <= 0;
        end else begin
            spi_clk_divider <= spi_clk_divider + 1;
        end

        // SPI frame counter
        if (spi_frame_counter == 15) begin
            spi_frame_counter <= 0;
            spi_output_en <= 0;
        end else begin
            spi_frame_counter <= spi_frame_counter + 1;
            spi_output_en <= 1;
        end

        // SPI delay counter
        if (spi_delay_counter == spi_frame_delay - 1) begin
            spi_delay_counter <= 0;
        end else begin
            spi_delay_counter <= spi_delay_counter + 1;
        end

        // SPI output
        if (spi_output_en) begin
            spi_dout <= spi_frame[spi_frame_counter];
        end else begin
            spi_dout <= 0;
        end
    end
end

endmodule

