module shift_adder (
    input CLK,
    input RST,
    input LD,
    input [3:0] D,
    input [15:0] A,
    input [15:0] B,
    output reg [15:0] SUM
);

reg [3:0] shift_reg;
wire [15:0] shifted_value;
wire [15:0] signed_sum;

// Shift register module
shift_reg_mod shift_reg_inst (
    .CLK(CLK),
    .RST(RST),
    .LD(LD),
    .D(D),
    .OUT(shift_reg)
);

// Signed magnitude adder module
signed_adder signed_adder_inst (
    .A(A),
