// Shift register module
module shift_reg_mod (
    input CLK,
    input RST,
    input LD,
    input [3:0] D,
    output reg [3:0] OUT
);

always @(posedge CLK) begin
    if (RST) begin
        OUT <= 4'b0;
    end else if (LD) begin
        OUT <= D;
    end else begin
        OUT <= {OUT[2:0], 1'b0};
    end
end

endmodule

// Signed magnitude adder module
module signed_adder (
    input [15:0] A,
    input [15:0] B,
    output reg [15:0] SUM
);

reg [15:0] abs_A;
reg [15:0] abs_B;
reg [15:0] signed_sum;

always @(*) begin
    if (A[15] == 1'b1) begin
        abs_A = ~A + 1;
    end else begin
        abs_A = A;
    end
    if (B[15] == 1'b1) begin
        abs_B = ~B + 1;
    end else begin
        abs_B = B;
    end
end

always @(*) begin
    if (A[15] == B[15]) begin
        signed_sum = {A[15], abs_A + abs_B};
    end else if (abs_A > abs_B) begin
        signed_sum = {A[15], abs_A - abs_B};
    end else begin
        signed_sum = {B[15], abs_B - abs_A};
    end
end

assign SUM = signed_sum;

endmodule

module top_module (
