module mist1032sa_arbiter_matching_queue #(
		//Queue Depth
		parameter D = 8,
		//Queue Depth_N
		parameter DN = 3,
		//Queue Flag_N
		parameter FN = 3	
	)(
		input wire iCLOCK,
		input wire inRESET,
		//Flash
		input wire iFLASH,
		//Write
		input wire iWR_REQ,
		input wire [7:0] iWR_DATA,
		input wire [FN-1:0] iWR_PRIORITY,
		output wire oWR_FULL,
		//Read
		input wire iRD_REQ,
		output wire oRD_VALID,
		output wire [7:0] oRD_DATA,
		output wire [FN-1:0] oRD_PRIORITY,
		output wire oRD_EMPTY
	);


	/***********************************************************
	Control
	***********************************************************/
	wire full_flag;
	wire empty_flag;
	wire [DN:0] count;

	reg [DN:0] wr_counter;
	reg [DN:0] rd_counter;
	reg queue_valid[0:D-1];
	reg [FN-1:0] queue_type[0:D-1];
	reg [7:0] queue_data[0:D-1];

	integer i;


	assign full_flag = count[DN];
	assign empty_flag = (wr_counter == rd_counter)? 1'b1 : 1'b0;
	assign count = wr_counter - rd_counter;


	always@(posedge iCLOCK or negedge inRESET)begin
		if(!inRESET)begin
			wr_counter <= {DN+1{1'b0}};
			rd_counter <= {DN+1{1'b0}};
			//Flag Clear
			for(i = 0; i < D; i = i + 1)begin
				queue_valid[i] <= 1'b0;
			end
		end
		else begin
			if(iFLASH)begin
				//Flag Clear
				for(i = 0; i < D; i = i + 1)begin
					queue_valid[i] <= 1'b0;
				end
			end
			//Prev -> Next
			if(!full_flag && iWR_REQ)begin
				wr_counter <= wr_counter + {{DN{1'b0}}, 1'b1};
				queue_valid[wr_counter[DN-1:0]] <= 1'b1;
				queue_type[wr_counter[DN-1:0]] <= iWR_PRIORITY;
				queue_data[wr_counter[DN-1:0]] <= iWR_DATA;
			end
			//Next -> Data
			if(!empty_flag && iRD_REQ)begin
				rd_counter <= rd_counter + {{DN{1'b0}}, 1'b1};
				queue_valid[rd_counter[DN-1:0]] <= 1'b0;
			end
		end
	end

	/***********************************************************
	Output Assign
	***********************************************************/
	assign oWR_FULL = full_flag;

	reg [DN:0] max_priority_index;
	reg [FN-1:0] max_priority;

	always @* begin
		max_priority_index = {DN+1{1'b0}};
		max_priority = {FN{1'b0}};
		for (i = 0; i < D; i = i + 1) begin
			if (queue_valid[i] && (queue_type[i] > max_priority || (queue_type[i] == max_priority && i <= rd_counter[DN:0]))) begin
				max_priority_index = i;
				max_priority = queue_type[i];
			end
		end
	end

	assign oRD_VALID = queue_valid[max_priority_index] && !iFLASH;
	assign oRD_DATA = queue_data[max_priority_index];
	assign oRD_PRIORITY = queue_type[max_priority_index];
	assign oRD_EMPTY = empty_flag;

endmodule

