module debounce(
  input wire clk,
  input wire sw_in,
  input wire timer_ena,
  output wire sw_out
);

//------------------------------
//-- CONTROLLER
//------------------------------

//-- fsm states
localparam IDLE  = 2'b00; //-- Idle state. Button not pressed
localparam WAIT_1  = 2'b01; //-- Waiting for the stabilization of 1. Butt pressed
localparam PULSE = 2'b10; //-- 1-clk pulse is generated
localparam WAIT_0 = 2'b11; //-- Button released. Waiting for stabilization of 0

//-- Registers for storing the states
reg [1:0] state = IDLE;
reg [1:0] next_state;

//-- Control signals
reg out = 0;
reg timer_trig = 0;

assign sw_out = out;

//-- Transition between states
always @(posedge clk)
  state <= next_state;

//-- Control signal generation and next states
always @(*) begin

  //-- Default values
  next_state = state;      //-- Stay in the same state by default
  timer_trig = 0;
  out = 0;

  case (state)

    //-- Button not pressed
    //-- Remain in this state until the botton is pressed
    IDLE: begin
      timer_trig = 0;
      out = 0;
      if (sw_in)
        next_state = WAIT_1;
    end

    //-- Wait until x ms has elapsed
    WAIT_1: begin
      timer_trig = 0;
      out = 0;
      if (timer_ena)
        next_state = PULSE;
    end

    PULSE: begin
      timer_trig = 0;
      out = 1;
      next_state = WAIT_0;
    end

    WAIT_0: begin
      timer_trig = 0;
      out = 0;
      if (timer_ena && ~sw_in)
        next_state = IDLE;
    end

    default: begin

    end
  endcase
end

//-- Timer
prescaler #(
  .N(16)
) pres0 (
  .clk_in(clk),
  .ena(timer_ena),
  .clk_out(timer_trig)
);

endmodule

module fsm_3input_1output (
  input clk,
  input reset,
  input a,
  input b,
  input c,
  output reg d
);

  reg [1:0] state, next_state;

  parameter S0 = 2'b00, S1 = 2'b01;

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      state <= S0;
    end else begin
      state <= next_state;
    end
  end

  always @* begin
    case (state)
      S0: begin
        if (a & ~b & ~c) begin
          next_state = S1;
          d = 1'b0;
        end else if (~a & ~b & c) begin
          next_state = S0;
          d = 1'b0;
        end else begin
          next_state = S0;
          d = 1'b1;
        end
      end
      S1: begin
        if (~a & ~b & ~c) begin
          next_state = S0;
          d = 1'b1;
        end else if (~a & ~b & c) begin
          next_state = S1;
          d = 1'b1;
        end else begin
          next_state = S1;
          d = 1'b0;
        end
      end
      default: begin
        next_state = S0;
        d = 1'b0;
      end
    endcase
  end

endmodule

