module FSM (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 4; // number of input signals
parameter m = 2; // number of output signals
parameter s = 3; // number of states

reg [s-1:0] state;
reg [m-1:0] out_reg;

always @ (posedge clk) begin
  case (state)
    0: begin
      if (in[0] && in[1]) begin
        state <= 1;
        out_reg <= 2'b10;
      end else if (in[2]) begin
        state <= 2;
        out_reg <= 2'b11;
      end else begin
        state <= 0;
        out_reg <= 2'b00;
      end
    end
    1: begin
      if (in[3]) begin
        state <= 2;
        out_reg <= 2'b11;
      end else begin
        state <= 1;
        out_reg <= 2'b10;
      end
    end
    2: begin
      if (in[0] && in[1] && in[2]) begin
        state <= 0;
        out_reg <= 2'b00;
      end else if (in[3]) begin
        state <= 2;
        out_reg <= 2'b11;
      end else begin
        state <= 1;
        out_reg <= 2'b10;
      end
    end
  endcase
end

assign out = out_reg;

endmodule

