    wire [31:0] A_and_B;
    wire [31:0] A_and_B_shifted;
    wire [31:0] A_xor_B_shifted;
    wire [31:0] A_xor_B_shifted_and_carry_out;

    assign A_xor_B = A ^ B;
    assign A_and_B = A & B;
    assign A_and_B_shifted = A_and_B << 1;
    assign A_xor_B_shifted = A_xor_B << 1;

    ripple_carry_adder rca1(
        .clk(clk),
        .reset(reset),
        .A(A_xor_B),
        .B(A_and_B_shifted),
        .sum(A_xor_B_shifted_and_carry_out),
        .carry_out()
    );

    ripple_carry_adder rca2(
        .clk(clk),
        .reset(reset),
        .A(A_xor_B_shifted),
        .B(A_and_B_shifted),
        .sum(sum),
        .carry_out()
    );

    assign carry_out = A_xor_B_shifted_and_carry_out[31];

    // 8-bit multiplier
    wire [15:0] product;
    wire [7:0] result_shifted;

    assign product = sum[7:0] * A_reversed[7:0];
    assign result_shifted = {product[15:8], product[7:0]} << 1;
    assign result = result_shifted[7:0] ^ B_reversed[7:0];

endmodule

module ripple_carry_adder (
    input clk,
    input reset,
    input [31:0] A,
    input [31:0] B,
    output [31:0] sum,
    output carry_out
);

    wire [31:0] carry;

    assign carry[0] = 1'b0;
    generate
        genvar i;
        for (i = 0; i < 31; i = i + 1) begin : gen
            assign carry[i+1] = (A[i] & B[i]) | (A[i] & carry[i]) | (B[i] & carry[i]);
        end
    endgenerate

    assign sum = A + B + carry;
    assign carry_out = carry[31];

endmodule

module d_flip_flop (
    input clk,
    input d,
    output reg q );

    wire j, k;
    assign j = d;
    assign k = ~d;

    jk_flip_flop jk_ff (
        .clk(clk),
        .j(j),
        .k(k),
        .q(q)
    );

endmodule

module jk_flip_flop (
    input clk,
    input j,
    input k,
    output reg q );

    always @(posedge clk) begin
        if (j && ~k) begin
            q <= 1'b1;
        end else if (~j && k) begin
            q <= 1'b0;
        end else if (j && k) begin
            q <= ~q;
        end
    end

endmodule

module top_module (
    input clk,
    input d,
    output reg q );

    d_flip_flop d_ff (
        .clk(clk),
        .d(d),
        .q(q)
    );

endmodule

module mux6to1_pipeline (
    input [2:0] sel,
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output reg [3:0] out
);

reg [3:0] stage1_out [5:0];
reg [3:0] stage2_out [2:0];

always @(*) begin
    case(sel)
        3'b000: begin
            stage1_out[0] = data0 & 4'h0F;
            stage1_out[1] = data1 & 4'h0F;
            stage1_out[2] = data2 & 4'h0F;
            stage1_out[3] = data3 & 4'h0F;
            stage1_out[4] = data4 & 4'h0F;
            stage1_out[5] = data5 & 4'h0F;
        end
        3'b001: begin
            stage1_out[0] = data0 | 4'hF0;
            stage1_out[1] = data1 | 4'hF0;
            stage1_out[2] = data2 | 4'hF0;
            stage1_out[3] = data3 | 4'hF0;
            stage1_out[4] = data4 | 4'hF0;
            stage1_out[5] = data5 | 4'hF0;
        end
        3'b010: begin
            stage1_out[0] = data0 & 4'h0F;
            stage1_out[1] = data1 & 4'h0F;
            stage1_out[2] = data2 & 4'h0F;
            stage1_out[3] = data3 & 4'h0F;
            stage1_out[4] = data4 & 4'h0F;
            stage1_out[5] = data5 & 4'h0F;
        end
        3'b011: begin
            stage1_out[0] = data0 | 4'hF0;
            stage1_out[1] = data1 | 4'hF0;
            stage1_out[2] = data2 | 4'hF0;
            stage1_out[3] = data3 | 4'hF0;
            stage1_out[4] = data4 | 4'hF0;
            stage1_out[5] = data5 | 4'hF0;
        end
        3'b100: begin
            stage1_out[0] = 4'h0;
            stage1_out[1] = 4'h0;
            stage1_out[2] = 4'h0;
            stage1_out[3] = 4'h0;
            stage1_out[4] = 4'h0;
            stage1_out[5] = 4'h0;
        end
        default: begin
            stage1_out[0] = 4'h0;
            stage1_out[1] = 4'h0;
            stage1_out[2] = 4'h0;
            stage1_out[3] = 4'h0;
            stage1_out[4] = 4'h0;
            stage1_out[5] = 4'h0;
        end
    endcase
end

always @(*) begin
    stage2_out[0] = stage1_out[0] | stage1_out[1];
    stage2_out[1] = stage1_out[2] | stage1_out[3];
    stage2_out[2] = stage1_out[4] | stage1_out[5];
end

always @(*) begin
    out = 3'b000;
    case(sel)
        3'b000: out = stage2_out[0];
        3'b001: out = stage2_out[0];
        3'b010: out = stage2_out[1];
        3'b011: out = stage2_out[1];
        3'b100: out = stage2_out[2];
        default: out = 3'b000;
    endcase
end

endmodule

module shift_register (
    input clk,
    input [3:0] data_in,
    input shift_right,
    input load,
    output reg [3:0] data_out
);

reg [3:0] stage1, stage2, stage3, stage4;

always @(posedge clk) begin
    if (load) begin
        stage1 <= data_in;
        stage2 <= stage1;
        stage3 <= stage2;
        stage4 <= stage3;
    end else begin
        if (shift_right) begin
            stage1 <= data_out;
            stage2 <= stage1;
            stage3 <= stage2;
            stage4 <= stage3;
        end else begin
            stage1 <= stage2;
            stage2 <= stage3;
            stage3 <= stage4;
            stage4 <= data_out;
        end
    end
end

assign data_out = stage4;

endmodule

module tkr_chr (inpF, inpT, outF, outT);
	input [7:0] inpF;
	input [7:0] inpT;
	output [7:0] outF;
	output [7:0] outT;

	reg [7:0] outF;
	reg [7:0] outT;

	reg [7:0] str;
	reg [7:0] i;
	reg sink;

	initial outF = 0;
	initial outT = 0;

	always @(posedge inpF or posedge inpT) begin
		i = inpT;

		str = 0;
		str[7:0] = i;

		outT = tkr_global.new_string (str, 1);
		outF = ~outT;
	end

	always @(negedge inpF or negedge inpT) begin
		wait (inpT == 0 & inpF == 0);
		outT = 0;
		outF = 0;
	end
endmodule

module majority_gate (
    input A,
    input B,
    input C,
    input D,
    output X
);

wire AB, AC, AD, BC, BD, CD;
wire ABC, ABD, ACD, BCD;
wire AB_CD, AC_BD, AD_BC;

assign AB = A & B;
assign AC = A & C;
assign AD = A & D;
assign BC = B & C;
assign BD = B & D;
assign CD = C & D;

assign ABC = AB & C;
assign ABD = AB & D;
assign ACD = AC & D;
assign BCD = BC & D;

assign AB_CD = ABC | ABD | CD;
assign AC_BD = ABC | ACD | BD;
assign AD_BC = ABD | ACD | BC;

assign X = AB_CD & AC_BD & AD_BC;

endmodule

module calculator (
  input clk,
  input areset, // async active-high reset to zero
  input load,
  input ena,
  input [2:0] bin_in,  // Binary input for the binary to binary converter
  input shift_left,   // Control input to shift left instead of right
  input operation,    // 0 for addition, 1 for subtraction
  output reg [3:0] result // 4-bit output from the shift register
);

  wire [2:0] bin_out;
  wire o2, o1, o0;
  binary_to_binary b2b(.vec(bin_in), .outv(bin_out), .o2(o2), .o1(o1), .o0(o0));
  shift_register sr(.clk(clk), .areset(areset), .load(load), .ena(ena), .shift_left(shift_left), .data_in({bin_out, o2, o1, o0}), .result(result));

  always @(posedge clk) begin
    if (areset) begin
      result <= 0;
    end else if (load) begin
      result <= bin_out;
    end else if (ena) begin
      if (operation == 0) begin
        result <= result + {1'b0, bin_out};
      end else begin
        result <= result - {1'b0, bin_out};
      end
    end
  end

endmodule

module binary_to_binary (
  input wire [2:0] vec, // 3-bit binary input
  output wire [2:0] outv, // Binary output
  output wire o2, // Output corresponding to the input binary at bit position 2
  output wire o1, // Output corresponding to the input binary at bit position 1
  output wire o0 // Output corresponding to the input binary at bit position 0
);

  assign outv = vec;
  assign o2 = vec[2];
  assign o1 = vec[1];
  assign o0 = vec[0];

endmodule

module shift_register (
  input clk,
  input areset, // async active-high reset to zero
  input load,
  input ena,
  input shift_left,   // Control input to shift left instead of right
  input [3:0] data_in, // 4-bit input for the shift register
  output reg [3:0] result // 4-bit output from the shift register
);

  always @(posedge clk) begin
    if (areset) begin
      result <= 0;
    end else if (load) begin
      result <= data_in;
    end else if (ena) begin
      if (shift_left) begin
        result <= {result[2:0], data_in[3]};
      end else begin
        result <= {data_in[0], result[3:1]};
      end
    end
  end

endmodule

module rrab (
    output reg [1:0] grant,
    input [1:0] request,
    input clk,
    input reset_n
);

reg [1:0] counter;

always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
        counter <= 2'b00;
        grant <= 2'b00;
    end else if (request != 2'b11) begin
        counter <= 2'b00;
        grant <= request;
    end else begin
        if (counter == 2'b00) begin
            grant <= 2'b01;
            counter <= 2'b01;
        end else begin
            grant <= 2'b10;
            counter <= 2'b00;
        end
    end
end

endmodule

module dual_port_ram (
  input clk,
  input rst_n,
  input write_en,
  input [2:0] write_addr,
  input [3:0] write_data,
  input read_en,
  input [2:0] read_addr,
  output reg [3:0] read_data0,
  output reg [3:0] read_data1
);

  reg [3:0] ram [7:0];
  reg [2:0] write_ptr;
  reg [2:0] read_ptr;

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      write_ptr <= 0;
      read_ptr <= 0;
      ram <= 0;
    end else begin
      if (write_en) begin
        ram[write_addr] <= write_data;
        write_ptr <= write_addr + 1;
      end
      if (read_en) begin
        read_data0 <= ram[read_addr];
        read_data1 <= ram[(read_addr + 1) % 8];
        read_ptr <= read_addr + 1;
      end
    end
  end

endmodule

module mux_6_to_1 (
  input [3:0] data0,
  input [3:0] data1,
  input [3:0] data2,
  input [3:0] data3,
  input [3:0] data4,
  input [3:0] data5,
  input [2:0] sel,
  output reg [3:0] out
);

  always @* begin
    case (sel)
      3'd0: out <= data0;
      3'd1: out <= data1;
      3'd2: out <= data2;
      3'd3: out <= data3;
      3'd4: out <= data4;
      3'd5: out <= data5;
      3'd6, 3'd7: out <= {data0[1:0], data1[1:0], data2[1:0], data3[1:0], data4[1:0], data5[1:0]} ^ 2'b11;
    endcase
  end

endmodule

module top_module (
  input clk,
  input rst_n,
  input write_en,
  input [7:0] write_addr,
  input [3:0] write_data,
  input read_en,
  input [7:0] read_addr,
  input [2:0] sel,
  input [3:0] data0,
  input [3:0] data1,
  input [3:0] data2,
  input [3:0] data3,
  input [3:0] data4,
  input [3:0] data5,
  output reg [3:0] final_output,
  output reg [3:0] sum_output
);

  wire [3:0] ram_data0;
  wire [3:0] ram_data1;
  wire [3:0] mux_out;

  dual_port_ram ram (
    .clk(clk),
    .rst_n(rst_n),
    .write_en(write_en),
    .write_addr(write_addr[2:0]),
    .write_data(write_data),
    .read_en(read_en),
    .read_addr(read_addr[2:0]),
    .read_data0(ram_data0),
    .read_data1(ram_data1)
  );

  mux_6_to_1 mux (
    .data0(data0),
    .data1(data1),
    .data2(data2),
    .data3(data3),
    .data4(data4),
    .data5(data5),
    .sel(sel),
    .out(mux_out)
  );

  always @* begin
    final_output = ram_data0 & ram_data1 & mux_out;
    sum_output = final_output + write_data;
  end

endmodule

module calculator(
    input [7:0] A,
    input [7:0] B,
    input [2:0] OP,
    input RESET_B,
    output reg [7:0] C
);

    always @(*) begin
        case (OP)
            3'b000: C = A + B;
            3'b001: C = A - B;
            3'b010: C = A & B;
            3'b011: C = A | B;
            3'b100: C = A ^ B;
            3'b101: C = A << B;
            3'b110: C = A >> B;
            3'b111: C = ~A;
        endcase
    end

    always @(posedge RESET_B) begin
        C <= 8'b0;
    end

endmodule

module binary_counter (
    input clk,
    input reset,
    output reg [15:0] q,
    output reg [3:0] ov,
    output reg [3:1] ena
);

reg [3:0] count;

always @(posedge clk) begin
    if (reset) begin
        count <= 0;
        q <= 0;
        ov <= 0;
    end else begin
        if (ena[3]) begin
            count[3] <= ~count[3];
            if (count[3]) begin
                if (ena[2]) begin
                    count[2] <= ~count[2];
                    if (count[2]) begin
                        if (ena[1]) begin
                            count[1] <= ~count[1];
                            if (count[1]) begin
                                count[0] <= ~count[0];
                            end
                        end
                    end
                end
            end
        end
        q <= {count, 12'h0};
        ov <= count == 4'hF;
    end
end

endmodule

module overflow_counter (
    input [15:0] q,
    output reg [3:0] ov
);

always @(*) begin
    ov = q[15] + q[14] + q[13] + q[12];
end

endmodule

module sramcontrol(
    input wire clk50,
    input wire rst,

    //Input
    //Control
    input wire[2:0] ramOp_i,
    input wire[31:0] storeData_i,
    input wire[21:0] ramAddr_i,

    //Data from SRAM
    input wire[31:0] ramData_i,

    //Output
    //Control
    output wire[21:0] ramAddr_o,
    output wire sramEnable_o,
    output wire writeEnable_o,
    output wire busEnable_o,
    output wire[31:0] writeData_o,
    output wire readEnable_o,

    //Data to MMU
    output wire[31:0] ramData_o

    );

    reg[2:0] state;

    //Control
    assign sramEnable_o = ~rst;
    assign readEnable_o = (state == 2'b01 || state == 2'b10);
    assign writeEnable_o = (state == 2'b01);
    assign busEnable_o = (state == 2'b01 || state == 2'b10);

    //Address & Data
    assign writeData_o = storeData_i;
    assign ramData_o = readEnable_o ? ramData_i : 32'h0;
    assign ramAddr_o = (state == 2'b00) ? 22'h0 : ramAddr_i;

    //State machine
    always @(posedge clk50) begin
        if (rst == 1'b1) begin
            state <= 2'b00;
        end else if (state == 2'b01) begin
            state <= 2'b10;
        end else if (state == 2'b10) begin
            state <= 2'b00;
        end else if (ramOp_i == 3'b001) begin
            state <= 2'b01;
        end else if (ramOp_i == 3'b010) begin
            state <= 2'b01;
        end else begin
            state <= 2'b00;
        end
    end

endmodule

