module Video_System_CPU_nios2_oci_debug (
    // inputs:
    clk,
    dbrk_break,
    debugreq,
    hbreak_enabled,
    jdo,
    jrst_n,
    ocireg_ers,
    ocireg_mrs,
    reset,
    st_ready_test_idle,
    take_action_ocimem_a,
    take_action_ocireg,
    xbrk_break,

    // outputs:
    debugack,
    monitor_error,
    monitor_go,
    monitor_ready,
    oci_hbreak_req,
    resetlatch,
    resetrequest
);

input clk;
input dbrk_break;
input debugreq;
input hbreak_enabled;
input [37:0] jdo;
input jrst_n;
input ocireg_ers;
input ocireg_mrs;
input reset;
input st_ready_test_idle;
input take_action_ocimem_a;
input take_action_ocireg;
input xbrk_break;

output debugack;
output monitor_error;
output monitor_go;
output monitor_ready;
output oci_hbreak_req;
output resetlatch;
output resetrequest;

wire jtag_break;
wire probepresent;

assign oci_hbreak_req = jtag_break | dbrk_break | xbrk_break | debugreq;
assign debugack = ~hbreak_enabled;

reg monitor_ready;
reg monitor_error;
reg monitor_go;
reg resetlatch;
reg resetrequest;

always @(posedge clk or negedge jrst_n) begin
    if (!jrst_n) begin
        monitor_ready <= 0;
        monitor_error <= 0;
        monitor_go <= 0;
        resetlatch <= 0;
        resetrequest <= 0;
    end else begin
        if (take_action_ocireg && ocireg_mrs) begin
            monitor_ready <= 1;
        end else begin
            monitor_ready <= 0;
        end

        if (take_action_ocireg && ocireg_ers) begin
            monitor_error <= 1;
        end else begin
            monitor_error <= 0;
        end

        if (take_action_ocimem_a && jdo[23]) begin
            monitor_go <= 1;
        end else if (!st_ready_test_idle) begin
            monitor_go <= 1;
        end else begin
            monitor_go <= 0;
        end

        if (reset == 1) begin
            resetlatch <= probepresent;
            resetrequest <= jdo[22];
        end else if (take_action_ocimem_a) begin
            resetlatch <= jdo[24] ? 0 : resetlatch;
        end
    end
end

always @(posedge clk or negedge jrst_n) begin
    if (!jrst_n) begin
        probepresent <= 0;
        jtag_break <= 0;
    end else if (take_action_ocimem_a) begin
        probepresent <= jdo[19] ? 1 : jdo[18] ? 0 : probepresent;
        jtag_break <= jdo[21] ? 1 : jdo[20] ? 0 : jtag_break;
    end else if (reset == 1) begin
        jtag_break <= probepresent;
    end else if (~debugack & debugreq & probepresent) begin
        jtag_break <= 1;
    end
end

endmodule

