module timer_periph (
    input clk_i,
    input rst_i,
    output intr_systick_o,
    output intr_hires_o,
    input [7:0] addr_i,
    output reg [31:0] data_o,
    input [31:0] data_i,
    input we_i,
    input stb_i
);

parameter CLK_KHZ = 12288;
parameter SYSTICK_INTR_MS = 1;
parameter ENABLE_SYSTICK_TIMER = "ENABLED";
parameter ENABLE_HIGHRES_TIMER = "ENABLED";

reg [31:0] timer_val;
reg [31:0] timer_reload_val;
reg [1:0] timer_mode;
reg timer_enabled;
reg [31:0] timer_count;

wire timer_intr_systick;
wire timer_intr_hires;

assign intr_systick_o = timer_intr_systick;
assign intr_hires_o = timer_intr_hires;

always @(posedge clk_i) begin
    if (rst_i) begin
        timer_val <= 0;
        timer_reload_val <= 0;
        timer_mode <= 0;
        timer_enabled <= 0;
        timer_count <= 0;
    end else begin
        if (we_i && stb_i) begin
            case (addr_i)
                8'h00: timer_val[7:0] <= data_i[7:0];
                8'h01: timer_val[15:8] <= data_i[7:0];
                8'h02: timer_val[23:16] <= data_i[7:0];
                8'h03: timer_val[31:24] <= data_i[7:0];
                8'h04: timer_reload_val[7:0] <= data_i[7:0];
                8'h05: timer_reload_val[15:8] <= data_i[7:0];
                8'h06: timer_reload_val[23:16] <= data_i[7:0];
                8'h07: timer_reload_val[31:24] <= data_i[7:0];
                8'h08: timer_mode <= data_i[1:0];
                8'h09: timer_enabled <= data_i[0];
            endcase
        end
        if (timer_enabled) begin
            timer_count <= timer_count + 1;
            if (timer_count == ((CLK_KHZ * 1000) / (timer_mode == 2'b00 ? 1000 : 1000000))) begin
                timer_count <= 0;
                timer_val <= timer_val - 1;
                if (timer_val == 0) begin
                    timer_val <= timer_reload_val;
                    if (timer_mode == 2'b01) begin
                        timer_intr_systick <= 1;
                    end else if (timer_mode == 2'b10) begin
                        timer_intr_hires <= 1;
                    end
                end
            end
        end
    end
end

endmodule

module top_module(
    input t,
    input clk,
    output reg [1:0] out
);

reg [1:0] flip_flop;
wire d1, d2;

// T flip-flop 1
assign d1 = flip_flop[0] ^ t;
always @(posedge clk) begin
    flip_flop[0] <= d1;
end

// T flip-flop 2
assign d2 = flip_flop[1] ^ flip_flop[0];
always @(posedge clk) begin
    flip_flop[1] <= d2;
end

// Functional module
always @(*) begin
    case (flip_flop)
        2'b00: out = 2'b00;
        2'b01: out = 2'b01;
        2'b10: out = 2'b10;
        2'b11: out = 2'b11;
    endcase
end

endmodule

