module top_module (
    input clk,
    input [2:0] counter_in, // Input to the counter module
    input Up_Down, // Control input to choose between up and down count
    input Reset, // Synchronous active-high reset
    output reg [4:0] result // Output from the next_power_of_two module
);

    reg [2:0] counter_out; // Output from the counter module
    wire [4:0] next_power; // Output from the next_power_of_two module

    counter counter_inst (
        .clk(clk),
        .reset(Reset),
        .up_down(Up_Down),
        .in(counter_in),
        .out(counter_out)
    );

    next_power_of_two next_power_inst (
        .in(counter_out),
        .out(next_power)
    );

    always @ (posedge clk) begin
        if (Reset) begin
            counter_out <= 0;
            result <= 1;
        end
        else begin
            if (Up_Down) begin
                counter_out <= counter_out + 1;
            end
            else begin
                counter_out <= counter_out - 1;
            end

            next_power <= next_power;
            if (counter_out == 0) begin
                result <= 1;
            end
            else begin
                result <= next_power;
            end
        end
    end

endmodule

