module shift_register (
  input clk,
  input reset,
  input [7:0] parallel_in,
  input serial_in,
  output [7:0] parallel_out,
  output serial_out
);

  reg [3:0] counter_out;
  reg [7:0] register_out;
  reg select_input;

  // 4-bit binary counter with synchronous reset to 0 and a period of 10
  always @(posedge clk) begin
    if (reset) begin
      counter_out <= 4'b0000;
    end else begin
      counter_out <= counter_out + 1;
    end
  end

  // 8-bit register with synchronous reset to 0
  always @(posedge clk) begin
    if (reset) begin
      register_out <= 8'b00000000;
    end else begin
      register_out <= parallel_in;
    end
  end

  // Functional module to select between serial and parallel input
  always @(posedge clk) begin
    if (reset) begin
      select_input <= 1'b0;
    end else begin
      select_input <= counter_out[0] ^ register_out[0];
    end
  end

  // Shift register implementation
  reg [7:0] shift_register [0:3];
  always @(posedge clk) begin
    if (reset) begin
      shift_register <= {8{1'b0}};
    end else begin
      if (select_input) begin
        // Shift in serial input
        shift_register <= {shift_register[2:0], serial_in};
      end else begin
        // Shift in parallel input
        shift_register <= {shift_register[2:0], register_out};
      end
    end
  end

  // Output the parallel output and the serial output
  assign parallel_out = shift_register[3];
  assign serial_out = shift_register[0];

endmodule

module fifo_arbitration(
   input          emtx_ack,
   input          clock,
   input          reset,
   input [3:0]    emm_tx_wr_wait,
   input [3:0]    emm_tx_rd_wait,
   input          emrr_empty,
   input [31:0]   emrr_rd_data,
   input          emrq_empty,
   input [31:0]   emrq_rd_data,
   input          emwr_empty,
   input [31:0]   emwr_rd_data,
   output         emm_tx_access,
   output         emm_tx_write,
   output [1:0]   emm_tx_datamode,
   output [3:0]   emm_tx_ctrlmode,
   output [31:0]  emm_tx_dstaddr,
   output [31:0]  emm_tx_srcaddr,
   output [31:0]  emm_tx_data
);

   reg            ready;
   reg [102:0]    fifo_data;

   // priority-based ready signals
   wire           rr_ready = ~emrr_empty & ~emm_tx_wr_wait;
   wire           rq_ready = ~emrq_empty & ~emm_tx_rd_wait & ~rr_ready;
   wire           wr_ready = ~emwr_empty & ~emm_tx_wr_wait & ~rr_ready & ~rq_ready;

   // FIFO read enables, when we're idle or done with the current datum
   wire           emrr_rd_en = rr_ready & (~ready | emtx_ack);
   wire           emrq_rd_en = rq_ready & (~ready | emtx_ack);
   wire           emwr_rd_en = wr_ready & (~ready | emtx_ack);

   always @ (posedge clock) begin
      if( reset ) begin

         ready     <= 1'b0;
         fifo_data <= 'd0;

      end else begin

         if( emrr_rd_en ) begin

            ready <= 1'b1;
            fifo_data <= {emrr_rd_data, 3'b001};

         end else if( emrq_rd_en ) begin

            ready <= 1'b1;
            fifo_data <= {emrq_rd_data, 3'b010};

         end else if( emwr_rd_en ) begin

            ready <= 1'b1;
            fifo_data <= {emwr_rd_data, 3'b100};

         end else if( emtx_ack ) begin

            ready <= 1'b0;

         end
      end // else: !if( reset )
   end // always @ (posedge clock)

   //#############################
   //# Break-out the emesh signals
   //#############################

   assign emm_tx_access   = ready;
   assign emm_tx_write    = fifo_data[102];
   assign emm_tx_datamode = fifo_data[101:100];
   assign emm_tx_ctrlmode = fifo_data[99:96];
   assign emm_tx_dstaddr  = fifo_data[95:64];
   assign emm_tx_srcaddr  = fifo_data[63:32];
   assign emm_tx_data     = fifo_data[31:0];

endmodule

