module carry_select_adder (
    input [31:0] A,
    input [31:0] B,
    input reset,
    output reg [31:0] S,
    output reg Cout
);

reg [31:0] P, G, C;

always @(A or B or reset) begin
    if (reset) begin
        S <= 0;
        Cout <= 0;
        P <= 0;
        G <= 0;
        C <= 0;
    end else begin
        P <= A ^ B;
        G <= A & B;
        C <= {1'b0, G} | {1'b0, P & C};
        S <= A + B + C;
        Cout <= C[32];
    end
end

endmodule

