            priority = 3'b011;
            encoded = 8'b00001000;
        end else if (I[2]) begin
            priority = 3'b010;
            encoded = 8'b00000100;
        end else if (I[1]) begin
            priority = 3'b001;
            encoded = 8'b00000010;
