    input [31:0] in,
    input [31:0] transition,
    input reset,
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] out
);

    wire [15:0] add_sub_result;
    wire [31:0] xor_result;
    wire [31:0] carry_out;

    bit_transition bit_trans(.clk(clk), .in(in), .transition(transition), .reset(reset));
    adder_subtractor add_sub(.a(a[15:0]), .b(b[15:0]), .sub(sub), .result(add_sub_result));
    assign xor_result = {16'b0, in} ^ {16'b0, transition};
    assign carry_out = {16'b0, add_sub_result} + {16'b0, xor_result};

    always @(posedge clk) begin
        if (!reset) begin
            out <= 0;
        end else begin
            out <= carry_out[31:0];
        end
    end

endmodule

module top_module (
    input clk,
    input reset,
    input [31:0] in,
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] out
);

    wire [31:0] transition;
    wire [31:0] functional_result;

    functional_module func(.in(in), .transition(transition), .reset(reset), .a(a), .b(b), .sub(sub), .out(functional_result));

    assign out = functional_result;

endmodule

