module stratixv_bias_logic(
			clk,
			shiftnld,
			captnupdt,
			mainclk,
			updateclk,
			capture,
			update
			);

// INPUT PORTS
input  clk;
input  shiftnld;
input  captnupdt;

// OUTPUTPUT PORTS
output mainclk;
output updateclk;
output capture;
output update;

wire clk_int;
wire update_int;
wire captnupdt_int;

// Generate the main clock signal
assign mainclk = clk_int;

always @(posedge clk) begin
    if (shiftnld) begin
        clk_int <= 1'b0;
    end else begin
        clk_int <= ~clk_int;
    end
end

// Generate the update clock signal
assign updateclk = update_int;

always @(posedge clk) begin
    if (captnupdt) begin
        update_int <= 1'b0;
    end else begin
        update_int <= ~update_int;
    end
end

// Generate the capture and update signals
assign capture = captnupdt_int;
assign update = ~captnupdt_int;

always @(posedge clk) begin
    if (captnupdt) begin
        captnupdt_int <= 1'b0;
    end else begin
        captnupdt_int <= 1'b1;
    end
end

endmodule

