module nfc_transmitter (
  input data_in,
  input clk,
  input reset,
  output tx,
  output tx_en,
  output tx_done
);

  reg [7:0] count;
  reg [7:0] data;
  reg tx_data;
  reg tx_enable;
  reg tx_complete;
  parameter CARRIER_FREQ = 13.56e6;
  parameter BIT_RATE = 106e3;
  parameter MODULATION_TYPE = "ASK"; // or "FSK"

  always @(posedge clk) begin
    if (reset) begin
      count <= 0;
      data <= 0;
      tx_data <= 0;
      tx_enable <= 0;
      tx_complete <= 0;
    end else begin
      if (count == 0) begin
        data <= data_in;
        tx_enable <= 1;
      end else if (count == 8) begin
        tx_enable <= 0;
        tx_complete <= 1;
      end else begin
        if (MODULATION_TYPE == "ASK") begin
          tx_data <= (data[count] == 1);
        end else if (MODULATION_TYPE == "FSK") begin
          tx_data <= (count % 2 == 0) ? (data[count] == 1) : ~(data[count] == 1);
        end
      end
      count <= count + 1;
    end
  end

  assign tx = tx_data;
  assign tx_en = tx_enable;
  assign tx_done = tx_complete;

endmodule

module nfc_receiver (
  input rx,
  input clk,
  input reset,
  output data_out,
  output rx_en,
  output rx_done
);

  reg [7:0] count;
  reg [7:0] data;
  reg rx_data;
  reg rx_enable;
  reg rx_complete;
  parameter CARRIER_FREQ = 13.56e6;
  parameter BIT_RATE = 106e3;
  parameter MODULATION_TYPE = "ASK"; // or "FSK"

  always @(posedge clk) begin
    if (reset) begin
      count <= 0;
      data <= 0;
      rx_data <= 0;
      rx_enable <= 0;
      rx_complete <= 0;
    end else begin
      if (count == 0) begin
        rx_enable <= 1;
      end else if (count == 8) begin
        rx_enable <= 0;
        rx_complete <= 1;
      end else begin
        if (MODULATION_TYPE == "ASK") begin
          rx_data <= rx;
        end else if (MODULATION_TYPE == "FSK") begin
          rx_data <= (count % 2 == 0) ? rx : ~rx;
        end
        data[count] <= rx_data;
      end
      count <= count + 1;
    end
  end

  assign data_out = data;
  assign rx_en = rx_enable;
  assign rx_done = rx_complete;

endmodule

