);

reg [3:0] counter;

always @(posedge clk, posedge reset) begin
    if (reset) begin
        counter <= 0;
        newClk <= 0;
    end else begin
        counter <= counter + 1;
        if (counter == 9) begin
            counter <= 0;
            newClk <= ~newClk;
        end
    end
end

endmodule

