module SSCG (
  input clk_in,
  input modulation_rate,
  input modulation_depth,
  output clk_out
);

parameter f_in = 50e6; // input clock frequency
parameter f_out = 51e6; // output clock frequency

reg [31:0] counter;
reg [31:0] triangle_counter;
reg [31:0] modulation_counter;

wire triangle_wave;
wire modulated_frequency;

assign triangle_wave = (triangle_counter < (f_out/modulation_rate)/2) ? triangle_counter : (f_out/modulation_rate) - triangle_counter;
assign modulated_frequency = (modulation_counter < (f_out/modulation_rate)*modulation_depth) ? f_in - (f_in*modulation_depth) + (modulation_counter*f_in/modulation_rate) : f_in + ((modulation_counter - (f_out/modulation_rate)*modulation_depth)*f_in/modulation_rate);

always @(posedge clk_in) begin
  counter <= counter + 1;
  modulation_counter <= modulation_counter + 1;
  if (counter >= modulated_frequency) begin
    counter <= 0;
    triangle_counter <= triangle_counter + 1;
  end
end

assign clk_out = (counter < (modulated_frequency/2)) ? 1'b1 : 1'b0;

endmodule

