module ConditionCheck(
	input [2:0] Condition,
	input Branch,
	input RegWrite,
	input Less,Zero,Overflow,
	output reg BranchValid,RegWriteValid
);

always @(*)
begin
    // Set BranchValid based on Condition and Branch
    if(Branch==0)
        BranchValid=0;
    else
    begin
        case(Condition)
            3'b000:
                BranchValid=0;
            3'b001:
                BranchValid=Zero;
            3'b010:
                BranchValid=~Zero;
            3'b011:
                BranchValid=Less|Zero;
            3'b100:
                BranchValid=Less;
            3'b101:
                BranchValid=~Less;
            3'b110:
                BranchValid=~(Less|Zero);
            3'b111:
                BranchValid=0;
        endcase
    end

    // Set RegWriteValid based on RegWrite and Overflow
    if(RegWrite==0)
        RegWriteValid=0;
    else if(Overflow==1)
        RegWriteValid=0;
    else
        RegWriteValid=1;
end

endmodule

module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               select      ,
    input               valid_a     ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out
);

reg [8:0] accumulator;
reg [7:0] previous_data;
reg [1:0] state;

assign ready_a = ~valid_a || ready_b;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        accumulator <= 0;
        previous_data <= 0;
        state <= 0;
        valid_b <= 0;
        data_out <= 0;
    end else begin
        case (state)
            0: begin // wait for valid input
                if (valid_a) begin
                    previous_data <= data_in;
                    state <= 1;
                end
            end
            1: begin // wait for valid input
                if (valid_a) begin
                    if (select) begin
                        accumulator <= accumulator + previous_data;
                    end else begin
                        accumulator <= accumulator + data_in;
                    end
                    previous_data <= data_in;
                    state <= 1;
                end else begin
                    state <= 2;
                end
            end
            2: begin // output accumulated result
                data_out <= accumulator;
                accumulator <= 0;
                valid_b <= 1;
                state <= 0;
            end
        endcase
    end
end

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        valid_b <= 0;
    end else begin
        if (valid_b && ready_b) begin
            valid_b <= 0;
        end
    end
end

endmodule

