    read_ptr = 6'd0;
    write_ptr = 6'd0;
    next_write_ptr = 6'd1;
    unread_ff = 6'd0;
end

always @(posedge clk) begin
    if (rst) begin
        read_ptr <= 6'd0;
        write_ptr <= 6'd0;
        next_write_ptr <= 6'd1;
        unread_ff <= 6'd0;
    end else begin
        if (we_i) begin
            ram[addr_i] <= data_i;
            next_write_ptr <= write_ptr + 1;
            if (next_write_ptr == 6'd64) begin
                next_write_ptr <= 6'd0;
            end
            unread_ff <= unread_ff + 1;
        end
        read_ptr <= next_write_ptr;
        data_o <= ram[read_ptr];
        if (unread_ff > 0) begin
            unread_ff <= unread_ff - 1;
        end
    end
end

endmodule

