module int_ctrl(
    input wire clk_i,
    input wire rst_i,
    input wire [15:0] io_int_i,
    output reg io_int_o,
    output reg [3:0] int_num_o
);

    reg [3:0] highest_priority_int; // interrupt with highest priority
    reg [15:0] pending_int; // pending interrupts
    reg [3:0] int_num; // interrupt number

    always @(posedge clk_i) begin
        if (rst_i) begin
            io_int_o <= 1'b0;
            int_num_o <= 4'h0;
            highest_priority_int <= 4'h0;
            pending_int <= 16'h0;
            int_num <= 4'h0;
        end
        else begin
            // update pending interrupts
            pending_int <= io_int_i & ~highest_priority_int;

            // update interrupt number
            case (highest_priority_int)
                4'h0: int_num <= 4'h0;
                4'h1: int_num <= 4'h1;
                4'h2: int_num <= 4'h2;
                4'h3: int_num <= 4'h3;
                4'h4: int_num <= 4'h4;
                4'h5: int_num <= 4'h5;
                4'h6: int_num <= 4'h6;
                4'h7: int_num <= 4'h7;
                4'h8: int_num <= 4'h8;
                4'h9: int_num <= 4'h9;
                4'ha: int_num <= 4'ha;
                4'hb: int_num <= 4'hb;
                4'hc: int_num <= 4'hc;
                4'hd: int_num <= 4'hd;
                4'he: int_num <= 4'he;
                4'hf: int_num <= 4'hf;
            endcase

            // update interrupt output
            if (pending_int != 16'h0) begin
                io_int_o <= 1'b1;
                highest_priority_int <= $priority(pending_int);
            end
            else begin
                io_int_o <= 1'b0;
                highest_priority_int <= 4'h0;
            end
        end
    end

    assign int_num_o = int_num;

endmodule

