    if(~addr[18]) begin
        if(addr[15:8] == 8'b0000_0000) A = 6'h5 + A_cnt;
        else A = 6'h11 - {2'b0, addr[15:12]} + A_cnt;
    end
    else begin
        case(addr[17:16])
            2'b00 : A = addr[15:8] + A_cnt;
            2'b01 : A = addr[15:8] + 6'h4 + A_cnt;
            2'b10 : A = addr[15:8] + 6'h27 + A_cnt;
