module carry_lookahead_adder (
    input [7:0] a,
    input [7:0] b,
    input cin,
    output [7:0] s,
    output cout
);

wire [7:0] g;
wire [7:0] p;
wire [7:0] c;

assign g = a & b;
assign p = a ^ b;
assign c[0] = cin;

genvar i;
generate
    for (i = 1; i < 8; i = i + 1) begin
        assign c[i] = g[i-1] | (p[i-1] & c[i-1]);
    end
endgenerate

assign s = p ^ c;
assign cout = g[7] | (p[7] & c[7]);

endmodule

