assign s = sum;

assign overflow = (a[7] == b[7]) && (a[7] != s[7]);

endmodule

module fifo (
    input clk,
    input rst,
    input [15:0] data_in,
    input write_en,
    input read_en,
    output [15:0] data_out,
    output empty,
    output full
);

reg [15:0] buffer [0:7];
reg [2:0] head;
reg [2:0] tail;
wire [2:0] next_head;
wire [2:0] next_tail;

assign next_head = write_en & (~full) ? head + 1 : head;
assign next_tail = read_en & (~empty) ? tail + 1 : tail;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        head <= 0;
        tail <= 0;
        buffer <= 0;
    end else begin
        head <= next_head;
        tail <= next_tail;
        if (write_en & (~full)) buffer[head] <= data_in;
    end
end

assign empty = (head == tail);
assign full = (next_head == tail);

always @(*) begin
    data_out = empty ? 16'h0000 : buffer[tail];
end

endmodule

module right_shift #(
    parameter SHIFT_AMOUNT = 2
)(
    input [3:0] in,
    input [1:0] shift_amt,
    input mode,
    output reg [3:0] out
);

reg [3:0] stage1, stage2;

always @(*) begin
    if (mode) begin
        stage1 = in >> SHIFT_AMOUNT;
    end else begin
        stage1 = in << SHIFT_AMOUNT;
    end
end

always @(*) begin
    if (mode) begin
        stage2 = stage1 >> SHIFT_AMOUNT;
    end else begin
        stage2 = stage1 << SHIFT_AMOUNT;
    end
end

always @(*) begin
    out = stage2;
end

endmodule

module up_down_counter (
