module signed_non_restoring_divider (
  input signed [31:0] dividend,
  input signed [31:0] divisor,
  output signed [31:0] quotient
);

  reg signed [31:0] remainder;
  reg signed [31:0] dividend_reg;
  reg signed [31:0] divisor_reg;
  reg signed [31:0] quotient_reg;
  reg signed [31:0] adder_input;
  reg signed [31:0] adder_output;
  reg [4:0] count;
  reg sign;

  always @(*) begin
    dividend_reg = dividend;
    divisor_reg = divisor;
    sign = (dividend_reg < 0) ^ (divisor_reg < 0);
    dividend_reg = $signed(abs(dividend_reg));
    divisor_reg = $signed(abs(divisor_reg));
  end

  always @(posedge clk) begin
    if (count == 0) begin
      remainder = dividend_reg;
      quotient_reg = 0;
    end else begin
      if (remainder < 0) begin
        adder_input = divisor_reg - remainder;
        adder_output = remainder + adder_input;
        remainder = adder_output;
        quotient_reg[count-1] = 0;
      end else begin
        adder_input = remainder - divisor_reg;
        adder_output = remainder - adder_input;
        remainder = adder_output;
        quotient_reg[count-1] = 1;
      end
    end

    if (count == 16) begin
      quotient = $signed(quotient_reg);
    end

    count <= count + 1;
  end

endmodule

module uart_tx(
  input clk,
  input reset,
  input [7:0] data_in,
  input start,
  output reg tx,
  output reg done
);

  localparam IDLE = 2'b00;
  localparam START = 2'b01;
  localparam TRANSMIT = 2'b10;
  reg [1:0] state = IDLE;
  reg [3:0] bit_count = 4'd0;
  reg [7:0] data_reg;
  reg start_reg;

  always @(posedge clk) begin
    if (reset) begin
      state <= IDLE;
      bit_count <= 4'd0;
      data_reg <= 8'd0;
      tx <= 1'b1;
      done <= 1'b0;
      start_reg <= 1'b0;
    end else begin
      case (state)
        IDLE: begin
          if (start) begin
            start_reg <= 1'b1;
            state <= START;
          end
        end
        START: begin
          if (!start) begin
            state <= IDLE;
          end else if (bit_count == 4'd0) begin
            tx <= 1'b0;
            data_reg <= data_in;
            bit_count <= 4'd1;
          end else begin
            bit_count <= bit_count + 1;
            state <= TRANSMIT;
          end
        end
        TRANSMIT: begin
          if (bit_count == 4'd9) begin
            tx <= 1'b1;
            bit_count <= 4'd0;
            state <= START;
            if (data_reg == 8'hFF) begin
              done <= 1'b1;
            end
          end else begin
            tx <= data_reg[0];
            data_reg <= {data_reg[6:0], 1'b0};
            bit_count <= bit_count + 1;
          end
        end
      endcase
    end
  end

  always @(posedge clk) begin
    if (reset) begin
      start_reg <= 1'b0;
    end else begin
      if (start) begin
        start_reg <= 1'b1;
      end else if (done) begin
        start_reg <= 1'b0;
      end
    end
  end

  assign start = start_reg;

endmodule

module salsa (clk, B, Bx, Bo, X0out, Xaddr);

// Latency 8 clock cycles, approx 40nS propagation delay (SLOW!)

input clk;
input [511:0]B;
input [511:0]Bx;
output [511:0]Bo;			// Output is async
output [511:0]X0out;		// Becomes new X0
output [9:0] Xaddr;
wire [9:0] xa1, xa2, xa3, xa4, ya1, ya2, ya3, ya4;

reg [511:0]x1d1;
reg [511:0]x1d2;
reg [511:0]x1d3;
reg [511:0]x1d4;

reg [511:0]Xod1;
reg [511:0]Xod2;
reg [511:0]Xod3;
reg [511:0]X0out;

reg [511:0]xxd1;
reg [511:0]xxd2;
reg [511:0]xxd3;
reg [511:0]xxd4;

reg [511:0]yyd1;
reg [511:0]yyd2;
reg [511:0]yyd3;
reg [511:0]yyd4;

wire [511:0]xx;			// Initial xor
wire [511:0]x1;			// Salasa core outputs
wire [511:0]x2;
wire [511:0]x3;
wire [511:0]xr;
wire [511:0]Xo;

// Four salsa iterations. NB use registered salsa_core so 4 clock cycles.
salsa_core salsax1 (clk, xx, x1, xa1);
salsa_core salsax2 (clk, x1, x2, xa2);
salsa_core salsax3 (clk, x2, x3, xa3);
salsa_core salsax4 (clk, x3, xr, xa4);

wire [511:0]yy;			// Initial xor
wire [511:0]y1;			// Salasa core outputs
wire [511:0]y2;
wire [511:0]y3;
wire [511:0]yr;

// Four salsa iterations. NB use registered salsa_core so 4 clock cycles.
salsa_core salsay1 (clk, yy, y1, ya1);
salsa_core salsay2 (clk, y1, y2, ya2);
salsa_core salsay3 (clk, y2, y3, ya3);
salsa_core salsay4 (clk, y3, yr, ya4);

genvar i;
generate
	for (i = 0; i < 16; i = i + 1) begin : XX
		// Initial XOR. NB this adds to the propagation delay of the first salsa, may want register it.
		assign xx[`IDX(i)] = B[`IDX(i)] ^ Bx[`IDX(i)];
		assign Xo[`IDX(i)] = xxd4[`IDX(i)] + xr[`IDX(i)];
		assign yy[`IDX(i)] = x1d4[`IDX(i)] ^ Xo[`IDX(i)];
		assign Bo[`IDX(i)] = yyd4[`IDX(i)] + yr[`IDX(i)];	// Async output
	end
endgenerate

always @ (posedge clk)
begin
	x1d1 <= Bx;
	x1d2 <= x1d1;
	x1d3 <= x1d2;
	x1d4 <= x1d3;
	Xod1 <= Xo;
	Xod2 <= Xod1;
	Xod3 <= Xod2;
	X0out <= Xod3;	// We output this to become new X0

	xxd1 <= xx;
	xxd2 <= xxd1;
	xxd3 <= xxd2;
	xxd4 <= xxd3;

	yyd1 <= yy;
	yyd2 <= yyd1;
	yyd3 <= yyd2;
	yyd4 <= yyd3;
end

assign Xaddr = yyd3[9:0] + ya4;

endmodule

module FreqSynth (
  input clk_ref,
  input ctrl,
  output reg clk_syn
);

parameter f_ref = 100e6; // frequency of reference clock signal in Hz
parameter f_out = 1e6; // desired frequency of synthesized clock signal in Hz
parameter n = 12; // number of bits in phase accumulator
parameter m = 8; // number of bits in frequency accumulator

reg [n-1:0] phase_accumulator;
reg [m-1:0] frequency_accumulator;

localparam divider = f_ref / f_out;

always @(posedge clk_ref) begin
  // increment phase accumulator
  phase_accumulator <= phase_accumulator + 1;

  // increment frequency accumulator based on control signal
  if (ctrl) begin
    frequency_accumulator <= frequency_accumulator + 1;
  end
end

always @(posedge clk_ref) begin
  // calculate synthesized clock signal
  if (phase_accumulator >= divider) begin
    clk_syn <= ~clk_syn;
    phase_accumulator <= phase_accumulator - divider;
  end
end

endmodule

module crc_module (
  input clk,
  input rst,
  input [67:0] crc,
  input [6:0] amt,
  output reg [67:0] left,
  output reg [67:0] right
);

  wire [67:0] in = {crc[3:0], crc[63:0]};
  wire [63:0] result;

  always @ (posedge clk) begin
    if (rst) begin
      left <= 68'h0;
      right <= 68'h0;
    end else begin
      result = (left[63:0] ^ {60'h0, left[67:64]} ^ right[63:0] ^ {60'h0, right[67:64]});
      result = result << 4;
      result = result ^ (amt << 60) ^ in;
      result = result ^ left;
      result = result ^ right;
      left <= result[127:60];
      right <= result[59:0];
    end
  end

endmodule

