module multiplier_adder(
  input clk, // clock input
  input ena, // enable input
  input dclr, // clear input
  input [7:0] coef, // coefficient input
  input [7:0] din, // data input
  output reg [23:0] result // output
);

  // define widths
  localparam cwidth = 8; // coefficient width
  localparam dwidth = 8; // data width
  localparam mwidth = cwidth + dwidth; // multiplier width
  localparam rwidth = mwidth + 3; // result width

  // define signals
  reg [mwidth-1:0] mult_res; // multiplier output
  reg [rwidth-1:0] ext_mult_res; // multiplier output extended
  reg [rwidth-1:0] ext_result; // result output extended

  // pad inputs with zeros
  assign icoef = { {(mwidth-cwidth){coef[cwidth-1]}}, coef};
  assign idin  = { {(mwidth-dwidth){din[dwidth-1]}}, din};

  // generate multiplier structure
  always @(posedge clk)
    if(ena)
      mult_res <= #1 icoef * idin;

  // extend multiplier output
  assign ext_mult_res = { {3{mult_res[mwidth-1]}}, mult_res};

  // generate adder structure
  always @(posedge clk)
    if(ena)
      if(dclr)
        result <= #1 ext_mult_res;
      else
        result <= #1 ext_mult_res + ext_result;

  // extend result output
  assign ext_result = { {3{result[rwidth-1]}}, result};

endmodule

module uart_state_machine (
  input clk,
  input rst,
  input tx_data,
  input tx_start,
  input rx_data,
  input rx_ready,
  output tx_busy,
  output rx_valid
);

  // Define the states of the UART state machine
  localparam IDLE = 2'b00;
  localparam START_BIT = 2'b01;
  localparam DATA_BITS = 2'b10;
  localparam STOP_BIT = 2'b11;

  // Define the baud rate
  localparam BAUD_RATE = 9600;

  // Define the number of data bits
  localparam DATA_BITS_NUM = 8;

  // Define the parity type
  localparam PARITY_TYPE = "NONE";

  // Define the shift register
  reg [DATA_BITS_NUM:0] shift_reg;

  // Define the parity bit
  reg parity_bit;

  // Define the state register
  reg [1:0] state;

  // Define the counter for the baud rate
  reg [15:0] baud_counter;

  // Define the transmitter busy flag
  reg tx_busy;

  // Define the receiver valid flag
  reg rx_valid;

  // Define the receiver ready flag
  reg rx_ready_flag;

  // Define the transmitter data
  reg tx_data_reg;

  // Define the receiver data
  reg rx_data_reg;

  // Define the start bit
  reg start_bit;

  // Define the stop bit
  reg stop_bit;

  // Define the parity check
  reg parity_check;

  // Define the parity error flag
  reg parity_error;

  // Define the stop bit error flag
  reg stop_bit_error;

  // Define the data ready flag
  reg data_ready;

  // Define the data bit counter
  reg [2:0] data_counter;

  // Define the state machine
  always @(posedge clk) begin
    if (rst) begin
      state <= IDLE;
      baud_counter <= 0;
      tx_busy <= 0;
      rx_valid <= 0;
      rx_ready_flag <= 0;
      tx_data_reg <= 0;
      rx_data_reg <= 0;
      start_bit <= 0;
      stop_bit <= 0;
      parity_check <= 0;
      parity_error <= 0;
      stop_bit_error <= 0;
      data_ready <= 0;
      data_counter <= 0;
    end
    else begin
      case (state)
        IDLE: begin
          if (tx_start) begin
            state <= START_BIT;
            baud_counter <= 0;
            tx_busy <= 1;
            tx_data_reg <= tx_data;
            parity_bit <= (PARITY_TYPE == "EVEN" || PARITY_TYPE == "ODD") ? 1 : 0;
            parity_check <= (PARITY_TYPE == "ODD" || PARITY_TYPE == "EVEN");
          end
          else if (rx_ready) begin
            state <= START_BIT;
            baud_counter <= 0;
            rx_valid <= 0;
            rx_data_reg <= 0;
            start_bit <= 0;
            stop_bit <= 0;
            parity_check <= (PARITY_TYPE == "ODD" || PARITY_TYPE == "EVEN");
            parity_error <= 0;
            stop_bit_error <= 0;
            data_ready <= 0;
            data_counter <= 0;
          end
        end
        START_BIT: begin
          if (baud_counter == (1000000/BAUD_RATE)) begin
            baud_counter <= 0;
            state <= DATA_BITS;
            shift_reg <= {parity_bit, tx_data_reg};
            start_bit <= 1;
          end
          else begin
            baud_counter <= baud_counter + 1;
          end
        end
        DATA_BITS: begin
          if (baud_counter == (1000000/BAUD_RATE)) begin
            baud_counter <= 0;
            if (rx_ready) begin
              rx_valid <= 0;
              rx_data_reg <= 0;
              start_bit <= 0;
              stop_bit <= 0;
              parity_check <= (PARITY_TYPE == "ODD" || PARITY_TYPE == "EVEN");
              parity_error <= 0;
              stop_bit_error <= 0;
              data_ready <= 0;
              data_counter <= 0;
              state <= IDLE;
            end
            else begin
              if (data_counter == DATA_BITS_NUM) begin
                data_counter <= 0;
                state <= STOP_BIT;
                shift_reg <= {parity_bit, tx_data_reg, 1'b1};
                stop_bit <= 1;
              end
              else begin
                data_counter <= data_counter + 1;
                shift_reg <= {parity_bit, tx_data_reg, shift_reg[DATA_BITS_NUM]};
              end
            end
          end
          else begin
            baud_counter <= baud_counter + 1;
          end
        end
        STOP_BIT: begin
          if (baud_counter == (1000000/BAUD_RATE)) begin
            baud_counter <= 0;
            state <= IDLE;
            tx_busy <= 0;
            shift_reg <= 0;
            stop_bit <= 0;
          end
          else begin
            baud_counter <= baud_counter + 1;
          end
        end
      endcase
    end
  end

  // Define the shift register for the receiver
  always @(posedge clk) begin
    if (rst) begin
      data_ready <= 0;
      data_counter <= 0;
    end
    else begin
      if (rx_ready) begin
        rx_valid <= 1;
        rx_data_reg <= shift_reg[DATA_BITS_NUM-1:0];
        parity_error <= (PARITY_TYPE == "ODD" && ~parity_check) || (PARITY_TYPE == "EVEN" && parity_check);
        stop_bit_error <= ~shift_reg[DATA_BITS_NUM];
        data_ready <= 1;
        data_counter <= 0;
      end
      else if (state == DATA_BITS && baud_counter == (1000000/BAUD_RATE)) begin
        data_ready <= 0;
        data_counter <= data_counter + 1;
        shift_reg <= {shift_reg[DATA_BITS_NUM-1:1], rx_data};
        parity_check <= parity_check ^ rx_data;
      end
    end
  end

  // Define the receiver ready flag
  always @(posedge clk) begin
    if (rst) begin
      rx_ready_flag <= 0;
    end
    else begin
      if (state == IDLE && rx_ready) begin
        rx_ready_flag <= 1;
      end
      else if (state == STOP_BIT) begin
        rx_ready_flag <= 0;
      end
    end
  end

  // Define the outputs
  assign tx_busy = state != IDLE;
  assign rx_ready = rx_ready_flag && ~data_ready;

endmodule

module ring_oscillator (
  input clk,
  output freq
);

parameter n = 5; // number of inverters in the ring oscillator

reg [n-1:0] inverter_outputs;
wire [n-1:0] inverter_inputs;

genvar i;
generate
  for (i = 0; i < n; i = i + 1) begin : inverter_gen
    not #(.delay(1)) inverter (
      .in (inverter_inputs[i]),
      .out (inverter_outputs[i])
    );
  end
endgenerate

assign inverter_inputs[0] = inverter_outputs[n-1];
assign freq = 1 / (2 * n * (1 + inverter.in.delay));

endmodule

module shift_reg_pl (
    input clk,
    input load,
    input [31:0] data_in,
    output reg [31:0] data_out
);

    parameter len = 8;

    reg [31:0] shift_reg [len-1:0];
    integer i;

    always @(posedge clk) begin
        if (load) begin
            for (i = 0; i < len; i = i + 1) begin
                shift_reg[i] <= data_in;
            end
        end else begin
            for (i = len-1; i > 0; i = i - 1) begin
                shift_reg[i] <= shift_reg[i-1];
            end
            shift_reg[0] <= data_out;
        end
    end

    assign data_out = shift_reg[len-1];

endmodule

module priority_encoder_and_gate (
    input [7:0] in, // 8-bit input for priority encoder
    input a, // First input for AND gate
    input b, // Second input for AND gate
    output reg out, // Output of the functional module
    output reg [2:0] pos // Output of the priority encoder
);

// Priority Encoder
wire [7:0] in_not;
assign in_not = ~in;
wire [7:0] in_not_plus_one;
assign in_not_plus_one = in_not + 1;
wire [7:0] in_and_not_plus_one;
assign in_and_not_plus_one = in & in_not_plus_one;
wire [3:0] pos_temp;
assign pos_temp = {in_and_not_plus_one[3], in_and_not_plus_one[2], in_and_not_plus_one[1], in_and_not_plus_one[0]};
wire [3:0] pos_temp_not;
assign pos_temp_not = ~pos_temp;
wire [3:0] pos_temp_not_plus_one;
assign pos_temp_not_plus_one = pos_temp_not + 1;
assign pos = pos_temp_not_plus_one[2:0];

// AND Gate
always @ (a, b) begin
    if (a & b) begin
        out = 1;
    end
    else begin
        out = 0;
    end
end

endmodule

module adder4 (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

    wire [3:0] c, s;

    // Full adder implementation
    assign c[0] = A[0] & B[0];
    assign s[0] = A[0] ^ B[0] ^ Cin;
    assign c[1] = (A[0] & B[0]) | (A[1] & B[0]) | (A[0] & B[1]);
    assign s[1] = A[1] ^ B[1] ^ c[0];
    assign c[2] = (A[0] & B[1]) | (A[1] & B[0]) | (A[2] & B[0]) | (A[1] & B[1]) | (A[0] & B[2]);
    assign s[2] = A[2] ^ B[2] ^ c[1];
    assign c[3] = (A[0] & B[2]) | (A[1] & B[1]) | (A[2] & B[0]) | (A[3] & B[0]) | (A[2] & B[1]) | (A[1] & B[2]) | (A[0] & B[3]);
    assign s[3] = A[3] ^ B[3] ^ c[2];

    // Assign outputs
    assign S = s;
    assign Cout = c[3];

endmodule

module booth_multiplier (
    input signed [7:0] A,
    input signed [7:0] B,
    input ready,
    output reg valid,
    output reg signed [15:0] product
);

    reg signed [7:0] a_reg;
    reg signed [7:0] b_reg;
    reg signed [15:0] product_reg;
    reg [3:0] counter;
    reg [2:0] state;
    reg signed [7:0] adder_input;
    reg signed [15:0] adder_output;

    always@(posedge ready) begin
        if (ready) begin
            a_reg <= A;
            b_reg <= B;
            counter <= 4;
            state <= 0;
            product_reg <= 0;
        end
    end

    always@(posedge clk) begin
        case(state)
            0: begin
                if (counter > 0) begin
                    if (b_reg[0] == 1 && b_reg[1] == 0) begin
                        adder_input <= ~(a_reg) + 1;
                        state <= 1;
                    end
                    else if (b_reg[0] == 0 && b_reg[1] == 1) begin
                        adder_input <= a_reg;
                        state <= 1;
                    end
                    else begin
                        state <= 2;
                    end
                end
                else begin
                    valid <= 1;
                    product <= product_reg;
                    state <= 0;
                end
