module EthernetMAC (
  input [n-1:0] DataIn,
  input StartTransmission,
  input TxClk,
  output [n-1:0] DataOut,
  output EndTransmission,
  output RxClk
);

parameter n = 8; // number of bits in the data signal

reg [n-1:0] encoded_data;
reg [n-1:0] decoded_data;
reg [1:0] manchester_state;
reg [1:0] rx_manchester_state;
reg tx_clk_sync;
reg rx_clk_sync;
reg [n-1:0] bit_count;
reg [n-1:0] rx_bit_count;
reg start_rx;
reg end_rx;
reg start_tx;
reg end_tx;

assign DataOut = decoded_data;
assign EndTransmission = end_rx;
assign RxClk = rx_clk_sync;

always @(posedge TxClk) begin
  if (StartTransmission) begin
    start_tx <= 1;
    bit_count <= 0;
    manchester_state <= 2'b00;
  end
  if (start_tx) begin
    if (bit_count < n) begin
      case (manchester_state)
        2'b00: begin
          encoded_data[bit_count] <= DataIn[bit_count];
          manchester_state <= 2'b01;
        end
        2'b01: begin
          encoded_data[bit_count] <= ~DataIn[bit_count];
          manchester_state <= 2'b10;
        end
        2'b10: begin
          manchester_state <= 2'b00;
          bit_count <= bit_count + 1;
        end
      endcase
    end else begin
      start_tx <= 0;
      end_tx <= 1;
    end
  end else begin
    end_tx <= 0;
  end
end

always @(posedge RxClk) begin
  if (start_rx) begin
    case (rx_manchester_state)
      2'b00: begin
        rx_manchester_state <= 2'b01;
      end
      2'b01: begin
        decoded_data[rx_bit_count] <= rx_clk_sync ^ rx_bit_count;
        rx_manchester_state <= 2'b10;
      end
      2'b10: begin
        rx_manchester_state <= 2'b00;
        rx_bit_count <= rx_bit_count + 1;
      end
    endcase
    if (rx_bit_count == n) begin
      start_rx <= 0;
      end_rx <= 1;
    end
  end else begin
    end_rx <= 0;
  end
end

always @(posedge TxClk) begin
  tx_clk_sync <= ~tx_clk_sync;
end

always @(posedge RxClk) begin
  rx_clk_sync <= ~rx_clk_sync;
end

always @(posedge TxClk or posedge RxClk) begin
  if (StartTransmission) begin
    start_rx <= 1;
    rx_bit_count <= 0;
    rx_manchester_state <= 2'b00;
  end
end

endmodule

