          5'b01101: quantized_signal = 4'b1101;
          5'b01110: quantized_signal = 4'b1110;
          5'b01111: quantized_signal = 4'b1111;
          default: quantized_signal = 4'b1111; // Overflow
        endcase
      end else begin
        // Negative input signal
        case (input_signal[14:10])
          5'b00000: quantized_signal = 4'b1111;
          5'b00001: quantized_signal = 4'b1110;
          5'b00010: quantized_signal = 4'b1101;
          5'b00011: quantized_signal = 4'b1100;
          5'b00100: quantized_signal = 4'b1011;
          5'b00101: quantized_signal = 4'b1010;
          5'b00110: quantized_signal = 4'b1001;
          5'b00111: quantized_signal = 4'b1000;
          5'b01000: quantized_signal = 4'b0111;
          5'b01001: quantized_signal = 4'b0110;
          5'b01010: quantized_signal = 4'b0101;
          5'b01011: quantized_signal = 4'b0100;
          5'b01100: quantized_signal = 4'b0011;
          5'b01101: quantized_signal = 4'b0010;
          5'b01110: quantized_signal = 4'b0001;
          5'b01111: quantized_signal = 4'b0000;
          default: quantized_signal = 4'b0000; // Overflow
        endcase
      end
    end else begin
      // u-law encoding
      if (input_signal[15] == 1'b0) begin
        // Positive input signal
        input_signal = input_signal + G711_BIAS;
      end else begin
        // Negative input signal
        input_signal = ~input_signal + 1;
        input_signal = input_signal + G711_BIAS;
      end
      case (input_signal[14:10])
        5'b00000: quantized_signal = 4'b0000;
        5'b00001: quantized_signal = 4'b0001;
