    // Compress the quantized signal using a logarithmic compression function
    case (quantized_signal)
      4'b0000: compressed_signal = 8'b00000000;
      4'b0001: compressed_signal = 8'b00000001;
      4'b0010: compressed_signal = 8'b00000011;
      4'b0011: compressed_signal = 8'b00000111;
