module data_receiver(
    input wire rx, // input bit from transmitter
    input wire clk_in, // input clock signal
    input wire reset, // input reset signal
    output wire [7:0] dout, // output received data
    output wire avail, // output signal indicating when ready to receive new data
    output wire clk_div // output divided clock signal
);

    reg [2:0] state = 3'b000; // state variable for FSM
    reg [3:0] bitpos = 0; // bit position in received data
    reg [7:0] data = 8'b0; // received data
    reg [3:0] counter = 0; // counter for generating divided clock signal

    always @(posedge clk_in, posedge reset) begin
        if (reset) begin // reset state machine and variables
            state <= 3'b000;
            bitpos <= 4'd0;
            data <= 8'b0;
            counter <= 4'd0;
        end else begin
            case (state)
                3'b000: begin // wait for start bit
                    if (~rx) begin // start bit received
                        state <= 3'b001;
                        bitpos <= 4'd0;
                        data <= 8'b0;
                        counter <= 4'd0;
                    end
                end
                3'b001: begin // receive data bits
                    if (counter == 4'd2) begin // sample data on rising edge of clock
                        data[bitpos] <= rx;
                        bitpos <= bitpos + 1;
                        if (bitpos == 8) begin // all data bits received
                            state <= 3'b010;
                            bitpos <= 4'd0;
                            counter <= 4'd0;
                        end
                    end
                end
                3'b010: begin // wait for stop bit
                    if (counter == 4'd2) begin // sample stop bit on rising edge of clock
                        if (rx) begin // stop bit received
                            dout <= data; // output received data
                            avail <= 1; // set available signal
                            state <= 3'b000; // return to wait for start bit
                        end else begin // invalid stop bit
                            state <= 3'b011;
                            bitpos <= 4'd0;
                            counter <= 4'd0;
                        end
                    end
                end
                3'b011: begin // invalid stop bit received
                    if (counter == 4'd2) begin
                        state <= 3'b000; // return to wait for start bit
                    end
                end
                default: begin // should not occur
                    state <= 3'b000;
                end
            endcase
        end
    end

    always @(posedge clk_in) begin
        counter <= counter + 1;
        if (counter == 4'd3) begin // generate divided clock signal
            clk_div <= ~clk_div;
            counter <= 4'd0;
        end
    end

endmodule

module mux12bit(I, S, clk, O0, O1);
  input [11:0] I;
  input S, clk;
  output [11:0] O0, O1;

  wire [11:0] notI, and0, and1, or0, or1, xor0, xor1, nand0, nand1, nor0, nor1;

  assign notI = ~I;
  assign and0 = notI & S;
  assign and1 = I & S;
  assign or0 = notI | and0;
  assign or1 = I | and1;
  assign xor0 = notI ^ and0;
  assign xor1 = I ^ and1;
  assign nand0 = ~(notI & S);
  assign nand1 = ~(I & S);
  assign nor0 = ~(notI | and0);
  assign nor1 = ~(I | and1);

  dff dff0 (.D(or0), .CLK(clk), .Q(O0));
  dff dff1 (.D(or1), .CLK(clk), .Q(O1));
  dff dff2 (.D(xor0), .CLK(clk), .Q(O0));
  dff dff3 (.D(xor1), .CLK(clk), .Q(O1));
  dff dff4 (.D(nand0), .CLK(clk), .Q(O0));
  dff dff5 (.D(nand1), .CLK(clk), .Q(O1));
  dff dff6 (.D(nor0), .CLK(clk), .Q(O0));
  dff dff7 (.D(nor1), .CLK(clk), .Q(O1));
endmodule

module binary_counter (
    input clk,
    input reset,           // Synchronous active-high reset
    input [31:0] in,       // 32-bit input for the transition detector module
    output reg [7:0] count // 8-bit output representing the count
);

    reg [7:0] counter; // 8-bit binary counter
    reg [31:0] prev_in; // Previous value of the input vector for transition detection

    // Instantiate the 8-bit flip-flop module
    always @(negedge clk or posedge reset) begin
        if (reset) begin
            counter <= 8'b0;
        end else begin
            counter <= prev_in[7:0];
        end
    end

    // Instantiate the 32-bit transition detector module
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            prev_in <= 32'b0;
        end else begin
            prev_in <= in;
            if (in[31:1] > prev_in[30:0]) begin
                counter <= counter + 1;
            end
        end
    end

    assign count = counter;

endmodule

module cache_miss_fifo (
  input clk_i,
  input reset_i,
  input v_i,
  input ready_o,
  input yumi_i,
  input yumi_op_i,
  input scan_not_dq_i,
  input read_write_same_addr,
  input v_r,
  output reg empty,
  output reg rptr_valid,
  output reg enque,
  output reg v_o,
  output reg yumi_o
);

  parameter FIFO_DEPTH = 16;
  parameter DATA_WIDTH = 32;

  reg [DATA_WIDTH-1:0] fifo [0:FIFO_DEPTH-1];
  reg [DATA_WIDTH-1:0] data_out;
  reg [DATA_WIDTH-1:0] data_in;
  reg [4:0] wr_ptr;
  reg [4:0] rd_ptr;
  reg [4:0] fifo_count;

  always @(posedge clk_i) begin
    if (reset_i) begin
      wr_ptr <= 0;
      rd_ptr <= 0;
      fifo_count <= 0;
      empty <= 1;
      rptr_valid <= 0;
      enque <= 1;
      v_o <= 0;
    end else begin
      if (v_i && enque) begin
        fifo[wr_ptr] <= {yumi_op_i, yumi_i};
        wr_ptr <= wr_ptr + 1;
        fifo_count <= fifo_count + 1;
        empty <= 0;
        if (fifo_count == FIFO_DEPTH) begin
          enque <= 0;
        end
      end

      if (ready_o && ~empty) begin
        data_out <= fifo[rd_ptr];
        rd_ptr <= rd_ptr + 1;
        fifo_count <= fifo_count - 1;
        if (fifo_count == 0) begin
          empty <= 1;
        end
        rptr_valid <= 1;
      end else begin
        data_out <= 0;
        rptr_valid <= 0;
      end
    end
  end

  always @(posedge clk_i) begin
    if (reset_i) begin
      data_in <= 0;
    end else begin
      if (v_i && ready_o) begin
        data_in <= {yumi_op_i, yumi_i};
      end
    end
  end

  always @(posedge clk_i) begin
    if (reset_i) begin
      yumi_o <= 0;
    end else begin
      if (ready_o && ~empty) begin
        yumi_o <= data_out[DATA_WIDTH-1:0];
        v_o <= 1;
      end else begin
        yumi_o <= 0;
        v_o <= 0;
      end
    end
  end

endmodule

module tone_detection_generation (
  input clk,
  input audio_in,
  output tone_detected,
  output audio_out
);

parameter fs = 44100; // sampling frequency
parameter f1 = 500; // lower frequency
parameter f2 = 2000; // higher frequency
parameter threshold = 0.5; // minimum amplitude of detected tone

// Bandpass filter
reg [15:0] x1, x2, x3, y1, y2, y3;
reg [15:0] b0, b1, b2, a1, a2;
assign b0 = 2 * (f2 - f1) / fs;
assign b1 = 0;
assign b2 = -2 * (f2 - f1) / fs;
assign a1 = -1.9999 * cos(2 * $pi * (f1 + f2) / (2 * fs));
assign a2 = 0.9999 * pow(sin($pi * (f2 - f1) / fs), 2) - 1.9999 * cos(2 * $pi * (f1 + f2) / (2 * fs));

always @(posedge clk) begin
  x3 <= x2;
  x2 <= x1;
  x1 <= audio_in;
  y3 <= y2;
  y2 <= y1;
  y1 <= (b0 * x1 + b1 * x2 + b2 * x3 - a1 * y1 - a2 * y2) / 32768;
end

// Peak detector
reg [15:0] max_val;
reg [3:0] count;
always @(posedge clk) begin
  if (y1 > max_val) begin
    max_val <= y1;
    count <= 0;
  end else if (count < 15) begin
    count <= count + 1;
  end else begin
    max_val <= 0;
    count <= 0;
  end
end

// Tone detection
reg tone_detected_reg;
always @(posedge clk) begin
  if (max_val > threshold * 32768) begin
    tone_detected_reg <= 1;
  end else begin
    tone_detected_reg <= 0;
  end
end
assign tone_detected = tone_detected_reg;

// Tone generation
reg [31:0] phase_acc;
reg [15:0] sin_val;
assign sin_val = $signed(32767 * sin(2 * $pi * (f1 + f2) / (2 * fs) * phase_acc));
always @(posedge clk) begin
  phase_acc <= phase_acc + (f1 + f2) * 4294967296 / fs;
  audio_out <= audio_in + tone_detected_reg * sin_val / 32768;
end

endmodule

module touch_sensor_interface (
  input sensor_type,
  input touch,
  output touched
);

  // Capacitive sensing algorithm
  reg cap_sense;
  always @ (posedge touch) begin
    if (sensor_type == 1'b1) begin
      cap_sense <= !cap_sense;
    end
  end

  // Resistive sensing algorithm
  reg res_sense;
  always @ (posedge touch) begin
    if (sensor_type == 1'b0) begin
      res_sense <= !res_sense;
    end
  end

  // Output signal
  always @ (*) begin
    if (sensor_type == 1'b1) begin
      touched = cap_sense;
    end else begin
      touched = res_sense;
    end
  end

endmodule

module bit_rotate
  #(
    parameter C_DIRECTION = "LEFT",
    parameter C_WIDTH = 4
  )
  (
    input [C_WIDTH-1:0] WR_DATA,
    input [clog2s(C_WIDTH)-1:0] WR_SHIFTAMT,
    output [C_WIDTH-1:0] RD_DATA
  );

  // Duplicate the input data to create a 2*C_WIDTH bit vector.
  wire [2*C_WIDTH-1:0] wPreShiftL = {WR_DATA,WR_DATA};
  wire [2*C_WIDTH-1:0] wPreShiftR = {WR_DATA,WR_DATA};

  // Shift the duplicated data left by WR_SHIFTAMT bits.
  wire [2*C_WIDTH-1:0] wShiftL = wPreShiftL << WR_SHIFTAMT;

  // Shift the duplicated data right by WR_SHIFTAMT bits.
  wire [2*C_WIDTH-1:0] wShiftR = wPreShiftR >> WR_SHIFTAMT;

  // Output the rotated data based on the C_DIRECTION parameter.
  generate
    if (C_DIRECTION == "LEFT") begin
      assign RD_DATA = wShiftL[2*C_WIDTH-1:C_WIDTH];
    end else if (C_DIRECTION == "RIGHT") begin
      assign RD_DATA = wShiftR[C_WIDTH-1:0];
    end
  endgenerate

endmodule

module pc_forwarding(
    input clk, equ,
    input [15:0] pr2_IR, pr3_IR, pr4_IR, pr5_IR,
    output reg [2:0] pc_mux_select
);

    parameter ADD = 6'b000000;
    parameter NDU = 6'b001000;
    parameter ADC = 6'b000010;
    parameter ADZ = 6'b000001;
    parameter ADI = 4'b0001;
    parameter NDC = 6'b001010;
    parameter NDZ = 6'b001001;
    parameter LHI = 4'b0011;
    parameter LW  = 4'b0100;
    parameter LM  = 4'b0110;
    parameter BEQ = 4'b1100;
    parameter JAL = 4'b1000;
    parameter JLR = 4'b1001;

    parameter rb = 3'd1;
    parameter c = 3'd2;
    parameter m = 3'd3;
    parameter one = 3'd4;
    parameter h = 3'd5;
    parameter a = 3'd6;

    wire [5:0] op2, op3, op4, op5;
    wire [2:0] pr2RA, pr2RB, pr4RC, pr5RA;

    assign op2 = {pr2_IR[15:12], pr2_IR[1:0]};
    assign op3 = {pr3_IR[15:12], pr3_IR[1:0]};
    assign op4 = {pr4_IR[15:12], pr4_IR[1:0]};
    assign op5 = {pr5_IR[15:12], pr5_IR[1:0]};

    assign pr2RA = pr2_IR[11:9];
    assign pr2RB = pr2_IR[8:6];
    assign pr4RC = pr4_IR[5:3];
    assign pr5RA = pr5_IR[11:9];

    always @(negedge clk) begin
        if ((op5[5:2] == LW || op5[5:2] == LM) && pr5RA == 3'b111)
            pc_mux_select = c;
        else if (op2[5:2] == LHI && pr2RA == 3'b111)
            pc_mux_select = h;
        else if ((op4 == ADD || op4 == NDU || op4 == ADC || op4 == ADZ || op4 == NDC || op4 == NDZ) && pr4RC == 3'b111)
            pc_mux_select = a;
        else if (op4[5:2] == ADI && pr2RB == 3'b111)
            pc_mux_select = a;
        else if (equ == 1 && op3[5:2] == BEQ)
            pc_mux_select = one;
        else if (op3[5:2] == JLR)
            pc_mux_select = rb;
        else if (op2[5:2] == JAL)
            pc_mux_select = m;
        else
            pc_mux_select = 0;
    end

endmodule

module johnson_counter (
    input clk,              // Clock input
    input reset,            // Synchronous active-low reset
    output reg [3:0] out    // 4-bit output
);

reg [2:0] state;

always @(posedge clk, negedge reset) begin
    if (reset == 0) begin
        state <= 3'b000;
    end else begin
        case (state)
            3'b000: state <= 3'b100;
            3'b100: state <= 3'b110;
            3'b110: state <= 3'b111;
            3'b111: state <= 3'b011;
            3'b011: state <= 3'b001;
            3'b001: state <= 3'b000;
            3'b000: state <= 3'b000;
        endcase
    end
end

assign out = state;

endmodule

