module div_16bit_unsigned (
    input [15:0] D,
    input [15:0] V,
    output reg [15:0] Q,
    output reg [15:0] R
);

reg [15:0] remainder;
reg [15:0] quotient;
reg [15:0] divisor;
reg [15:0] dividend;
reg [15:0] bit_count;

always @(*) begin
    dividend = D;
    divisor = V;
    bit_count = 16;
    remainder = 0;
    quotient = 0;

    while (bit_count > 0) begin
        remainder = remainder << 1;
        remainder[0] = dividend[15];
        dividend = dividend << 1;
        remainder = remainder - divisor;
        if (remainder < 0) begin
            dividend[0] = 0;
            remainder = remainder + divisor;
        end else begin
            dividend[0] = 1;
            quotient = quotient << 1;
            quotient[0] = 1;
        end
        bit_count = bit_count - 1;
    end
end

assign Q = quotient;
assign R = remainder;

endmodule

module top_module (
    input [7:0] a,
    input [7:0] b,
    input clk,
    output reg [7:0] s,
    output reg overflow
);

reg [7:0] a_reg, b_reg, s_reg;
reg carry_in_reg, carry_out_reg;
wire [7:0] sum_wire;
wire carry_out_wire;

always @(posedge clk) begin
    a_reg <= a;
    b_reg <= b;
end

carry_lookahead_adder adder_inst (
    .a(a_reg),
    .b(b_reg),
    .carry_in(carry_in_reg),
    .sum(sum_wire),
    .carry_out(carry_out_wire)
);

always @(posedge clk) begin
    s_reg <= sum_wire;
    carry_in_reg <= carry_out_reg;
    carry_out_reg <= carry_out_wire;
end

always @(posedge clk) begin
    if (s_reg[7] == a_reg[7] && s_reg[7] != b_reg[7]) begin
        overflow <= 1;
    end else begin
        overflow <= 0;
    end
end

assign s = s_reg;

endmodule

module carry_lookahead_adder (
    input [7:0] a,
    input [7:0] b,
    input carry_in,
    output [7:0] sum,
    output carry_out
);

wire [7:0] p_wire, g_wire;
wire [7:0] c_wire;

assign p_wire = a ^ b;
assign g_wire = a & b;
assign c_wire[0] = carry_in;

genvar i;
generate
    for (i = 1; i < 8; i = i + 1) begin
        assign c_wire[i] = g_wire[i-1] | (p_wire[i-1] & c_wire[i-1]);
    end
endgenerate

assign sum = p_wire + (c_wire << 1);
assign carry_out = g_wire[6] | (p_wire[6] & c_wire[6]) | (p_wire[7] & p_wire[6]);

endmodule

module Pipeline (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 4; // number of input signals
parameter m = 2; // number of output signals
parameter p = 3; // number of pipeline stages

wire [n-1:0] stage0_out; // output of stage 0
wire [n-1:0] stage1_out; // output of stage 1
wire [n-1:0] stage2_out; // output of stage 2

// instantiate pipeline stages
Stage0 stage0(.in(in), .out(stage0_out));
Stage1 stage1(.in(stage0_out), .out(stage1_out));
Stage2 stage2(.in(stage1_out), .out(stage2_out));

// output signals are the final output of the last stage of the pipeline
assign out[0] = stage2_out[0];
assign out[1] = stage2_out[1];

endmodule
module Stage0 (
  input [n-1:0] in,
  output [n-1:0] out
);

reg [n-1:0] reg_out; // pipeline register

// perform computation in this stage
assign out = in + 1;

// store output in pipeline register
always @(posedge clk) begin
  reg_out <= out;
end

endmodule
module Stage1 (
  input [n-1:0] in,
  output [n-1:0] out
);

reg [n-1:0] reg_out; // pipeline register

// perform computation in this stage
assign out = in + 2;

// store output in pipeline register
always @(posedge clk) begin
  reg_out <= out;
end

endmodule
module Stage2 (
  input [n-1:0] in,
  output [n-1:0] out
);

reg [n-1:0] reg_out; // pipeline register

// perform computation in this stage
assign out = in + 3;

// store output in pipeline register
always @(posedge clk) begin
  reg_out <= out;
end

endmodule

module xor_counter (
    input clk,
    input reset,
    input async_reset,
    input a,
    input b,
    output reg out,
    output reg [3:0] q
);

reg [3:0] counter;
reg xor_out;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        counter <= 4'b0000;
        xor_out <= 1'b0;
    end else if (counter == 4'b0111) begin
        counter <= 4'b0000;
        xor_out <= a ^ b;
    end else begin
        counter <= counter + 1;
    end
end

always @(posedge clk) begin
    out <= xor_out;
end

endmodule

module digital_filter (
   input                 adc_clk_i       ,  // ADC clock
   input                 adc_rstn_i      ,  // ADC reset - active low
   input      [ 14-1: 0] adc_dat_i       ,  // ADC data
   output reg [ 14-1: 0] adc_dat_o       ,  // ADC data

   input signed [ 25-1: 0] cfg_aa_i        ,  // config AA coefficient
   input signed [ 25-1: 0] cfg_bb_i        ,  // config BB coefficient
   input signed [ 25-1: 0] cfg_kk_i        ,  // config KK coefficient
   input signed [ 25-1: 0] cfg_pp_i           // config PP coefficient
);

// register configuration - timing improvements
reg signed [ 25-1: 0] cfg_aa_r  ;
reg signed [ 25-1: 0] cfg_bb_r  ;
reg signed [ 25-1: 0] cfg_kk_r  ;
reg signed [ 25-1: 0] cfg_pp_r  ;

always @(posedge adc_clk_i) begin
   cfg_aa_r <= cfg_aa_i ;
   cfg_bb_r <= cfg_bb_i ;
   cfg_kk_r <= cfg_kk_i ;
   cfg_pp_r <= cfg_pp_i ;
end

// FIR
wire signed [ 47-1: 0] bb_mult   ;
wire signed [ 39-1: 0] r2_sum    ;
reg  signed [ 39-1: 0] r1_reg    ;
reg  signed [ 23-1: 0] r2_reg    ;
reg  signed [ 38-1: 0] r01_reg   ;
reg  signed [ 32-1: 0] r02_reg   ;


assign bb_mult = $signed(adc_dat_i) * $signed(cfg_bb_r);
assign r2_sum  = $signed(r01_reg) + $signed(r1_reg);

always @(posedge adc_clk_i) begin
   if (adc_rstn_i == 1'b0) begin
      r1_reg  <= 40'h0 ;
      r2_reg  <= 24'h0 ;
      r01_reg <= 39'h0 ;
      r02_reg <= 33'h0 ;
   end
   else begin
      r1_reg  <= $signed(r02_reg) - $signed(r01_reg) ;
      r2_reg  <= r2_sum[39-1:16];
      r01_reg <= {adc_dat_i,14'h0};
      r02_reg <= bb_mult[47-1:14];
   end
end

// IIR 1
wire signed [ 49-1: 0] aa_mult   ;
wire signed [ 47-1: 0] r3_sum    ;
reg  signed [ 23-1: 0] r3_reg    ;


assign aa_mult = $signed(r3_reg) * $signed(cfg_aa_r);
assign r3_sum  = $signed({r2_reg,24'h0}) + $signed({r3_reg,24'h0}) - $signed(aa_mult[49-1:0]);

always @(posedge adc_clk_i) begin
   if (adc_rstn_i == 1'b0) begin
      r3_reg  <= 24'h0 ;
   end
   else begin
      r3_reg  <= r3_sum[47-1:24] ;
   end
end

// IIR 2
wire signed [ 40-1: 0] pp_mult   ;
wire signed [ 16-1: 0] r4_sum    ;
reg  signed [ 16-1: 0] r4_reg    ;
reg  signed [ 16-1: 0] r3_shr    ;


assign pp_mult = $signed(r4_reg) * $signed(cfg_pp_r);
assign r4_sum  = $signed(r3_shr) + $signed(pp_mult[40-1:16]);

always @(posedge adc_clk_i) begin
   if (adc_rstn_i == 1'b0) begin
      r3_shr <= 16'h0 ;
      r4_reg <= 16'h0 ;
   end
   else begin
      r3_shr <= r3_reg[23-1:8] ;
      r4_reg <= r4_sum[16-1:0] ;
   end
end

// Scaling
wire signed [ 40-1: 0] kk_mult   ;
reg  signed [ 16-1: 0] r4_reg_r  ;
reg  signed [ 16-1: 0] r4_reg_rr ;
reg  signed [ 14-1: 0] r5_reg    ;


assign kk_mult = $signed(r4_reg_rr) * $signed(cfg_kk_r);

always @(posedge adc_clk_i) begin
   if (adc_rstn_i == 1'b0) begin
      r4_reg_r  <= 16'h0 ;
      r4_reg_rr <= 16'h0 ;
      r5_reg    <= 14'h0 ;
   end
   else begin
      r4_reg_r  <= r4_reg   ;
      r4_reg_rr <= r4_reg_r ;

      if ($signed(kk_mult[40-1:24]) > $signed(14'h1FFF))
         r5_reg <= 14'h1FFF ;
      else if ($signed(kk_mult[40-1:24]) < $signed(14'h2000))
         r5_reg <= 14'h2000 ;
      else
         r5_reg <= kk_mult[24+14-1:24];
   end
end

assign adc_dat_o = r5_reg ;

endmodule

module tone_detection_generation (
  input audio_in,
  input tone_detected,
  output audio_out
);

parameter f = 1000; // frequency to detect/generate

// Tone detection block using Goertzel algorithm
reg [15:0] s1;
reg [15:0] s2;
reg [15:0] coeff;
reg [15:0] threshold;
wire tone_detected;

assign tone_detected = (s1*s1 + s2*s2 - coeff*s1*s2) > threshold;

always @ (posedge clk) begin
  s1 <= audio_in + (coeff * s1) - (s2 << 1);
  s2 <= s1 + (coeff * s2);
end

assign coeff = 2*cos(2*3.14159*f/sample_rate);
assign threshold = 2*(0.9**2) - 2*cos(2*3.14159*f/sample_rate);

// Tone generation block using sine wave generator
reg [15:0] phase;
wire [15:0] sin_wave;
wire [15:0] audio_out;

assign sin_wave = $signed(32767*sin(phase));
assign audio_out = sin_wave & tone_detected;

always @ (posedge clk) begin
  phase <= phase + 2*3.14159*f/sample_rate;
end

endmodule

