module Calculator (Num1, Num2, OpSel, Reset, Result, OvfFlag, UnfFlag, ZeroFlag);

    input [7:0] Num1, Num2;
    input [1:0] OpSel;
    input Reset;
    output [7:0] Result;
    output OvfFlag, UnfFlag, ZeroFlag;

    wire [15:0] temp_result;
    wire [8:0] temp_dividend;
    wire [7:0] temp_quotient;

    assign temp_result = Num1 * Num2;
    assign temp_dividend = (OpSel == 2'b11) ? Num1 : temp_result;
    assign temp_quotient = (OpSel == 2'b11) ? Num2 : temp_dividend;

    always @ (Num1 or Num2 or OpSel or Reset) begin
        case (OpSel)
            2'b00: Result <= Num1 + Num2;
            2'b01: Result <= Num1 - Num2;
            2'b10: begin
                if (temp_result[15] == 1) begin
                    OvfFlag <= 1;
                    Result <= 0;
                end else begin
                    OvfFlag <= 0;
                    Result <= temp_result[7:0];
                end
            end
            2'b11: begin
                if (Num2 == 0) begin
                    ZeroFlag <= 1;
                    Result <= 0;
                end else if (temp_dividend[7:0] < Num1) begin
                    OvfFlag <= 1;
                    Result <= 0;
                end else if (temp_quotient > 255) begin
                    OvfFlag <= 1;
                    Result <= 0;
                end else begin
                    OvfFlag <= 0;
                    ZeroFlag <= 0;
                    Result <= temp_quotient;
                end
            end
            default: Result <= 0;
        endcase

        if (OpSel == 2'b00 || OpSel == 2'b01) begin
            if (Result[7] != Num1[7] && Result[7] != Num2[7]) begin
                OvfFlag <= 1;
                UnfFlag <= 0;
            end else if (OpSel == 2'b00 && Result[7] == 1 && Num1[7] == 0 && Num2[7] == 0) begin
                OvfFlag <= 1;
                UnfFlag <= 0;
            end else if (OpSel == 2'b01 && Result[7] == 0 && Num1[7] == 1 && Num2[7] == 0) begin
                OvfFlag <= 1;
                UnfFlag <= 0;
            end else if (OpSel == 2'b01 && Result[7] == 1 && Num1[7] == 0 && Num2[7] == 1) begin
                OvfFlag <= 1;
                UnfFlag <= 0;
            end else if (OpSel == 2'b01 && Result[7] == 0 && Num1[7] == 0 && Num2[7] == 1) begin
                OvfFlag <= 1;
                UnfFlag <= 0;
            end else if (Result[7:0] == 0) begin
                ZeroFlag <= 1;
                OvfFlag <= 0;
                UnfFlag <= 0;
            end else if (OpSel == 2'b01 && Result[7] == 1 && Num1[7] == 1 && Num2[7] == 0) begin
                UnfFlag <= 1;
                OvfFlag <= 0;
            end else if (OpSel == 2'b01 && Result[7] == 0 && Num1[7] == 0 && Num2[7] == 1) begin
                UnfFlag <= 1;
                OvfFlag <= 0;
            end else begin
                UnfFlag <= 0;
                OvfFlag <= 0;
            end
        end else begin
            UnfFlag <= 0;
        end
    end

endmodule

module GrayCodeStateMachine (
  input clk,
  input reset,
  output [n-1:0] out
);

parameter n = 4; // number of output signals

reg [n-1:0] state;
reg [n-1:0] gray;

// Define the Gray code for each state
localparam [n-1:0] gray_codes = {0, 1, 3, 2, 6, 7, 5, 4, 12, 13, 15, 14, 10, 11, 9, 8};

// Assign the initial state and Gray code
initial begin
  state = 0;
  gray = gray_codes[state];
end

// Transition between states on each rising edge of the clock signal
always @(posedge clk) begin
  if (reset) begin
    state <= 0;
    gray <= gray_codes[state];
  end else begin
    state <= state + 1;
    gray <= gray_codes[state];
  end
end

// Assign the output signals to the current Gray code
assign out = gray;

endmodule

