            write_addr_reg <= write_addr;
            write_data_reg <= write_data;
            write_en_reg <= 2'h3;
        end
        if (read_en) begin
            read_addr_reg <= read_addr;
            read_en_reg <= 2'h3;
        end
    end
end

always @(posedge clk) begin
    if (~rst_n) begin
        read_data <= 4'h0;
    end else begin
        if (write_en_reg[1]) begin
            mem[write_addr_reg[2:0]] <= write_data_reg;
            write_en_reg[1] <= 1'b0;
        end
        if (read_en_reg[1]) begin
            read_data <= mem[read_addr_reg[2:0]];
            read_en_reg[1] <= 1'b0;
        end
    end
end

endmodule

