module top_module(
    input [63:0] a, b,  // Two 64-bit binary numbers
    input ctrl,         // Control signal to select between adder and multiplexer
    input [63:0] in,    // 64-bit input vector for the multiplexer
    input [3:0] sel,    // Selector for the multiplexer
    output [79:0] out   // 80-bit final output
);

    wire [63:0] sum;
    wire [15:0] mux_out;
    wire [79:0] final_out;

    // Instantiate the 64-bit ripple-carry adder module
    ripple_adder adder_inst(
        .a(a),
        .b(b),
        .sum(sum)
    );

    // Instantiate the 16-to-1 multiplexer with a barrel shifter module
    mux_barrel_shifter mux_inst(
        .in(in),
        .sel(sel),
        .out(mux_out)
    );

    // Instantiate the 2-bit control logic module
    control_logic ctrl_inst(
        .ctrl(ctrl),
        .add_out(sum),
        .mux_out(mux_out)
    );

    // Instantiate the functional module that generates the final output
    final_module final_inst(
        .sum(sum),
        .mux_out(mux_out),
        .out(final_out)
    );

    // Assign the final output to the output port
    assign out = final_out;

endmodule


module ripple_adder(
    input [63:0] a, b,
    output [63:0] sum
);

    genvar i;
    generate
        for (i = 0; i < 64; i = i + 1) begin : adder_loop
            full_adder adder_inst(
                .a(a[i]),
                .b(b[i]),
                .cin(sum[i-1]),
                .sum(sum[i]),
                .cout(sum[i+1])
            );
        end
    endgenerate

endmodule


module full_adder(
    input a, b, cin,
    output sum, cout
);

    assign sum = a ^ b ^ cin;
    assign cout = (a & b) | (a & cin) | (b & cin);

endmodule


module mux_barrel_shifter(
    input [63:0] in,
    input [3:0] sel,
    output [15:0] out
);

    wire [15:0] shifted_in;

    // Shift the 64-bit input vector based on the selector
    assign shifted_in[15:0] = in[4*sel +: 16];

    // Instantiate the 16-to-1 multiplexer module
    mux16 mux_inst(
        .in(shifted_in),
        .sel(sel[1:0]),
        .out(out)
    );

endmodule


module mux16(
    input [15:0] in,
    input [1:0] sel,
    output reg [0:0] out
);

    always @(*) begin
        case (sel)
            2'b00: out = in[0];
            2'b01: out = in[1];
            2'b10: out = in[2];
            2'b11: out = in[3];
        endcase
    end

endmodule


module control_logic(
    input ctrl,
    input [63:0] add_out,
    input [15:0] mux_out,
    output reg [63:0] active_out
);

    always @(ctrl, add_out, mux_out) begin
        if (ctrl == 0) begin
            active_out = add_out;
        end else begin
            active_out = {16'b0, mux_out};
        end
    end

endmodule


module final_module(
    input [63:0] sum,
    input [15:0] mux_out,
    output [79:0] out
);

    assign out = {sum, mux_out};

endmodule

