module SPI_master (
  input clk,
  input rst,
  input mosi,
  input cs,
  output reg miso
);

parameter sclk_div = 2; // clock divider

reg [7:0] shift_reg;
reg [2:0] counter;

always @(posedge clk or posedge rst) begin
  if (rst) begin
    counter <= 3'b0;
    miso <= 1'b0;
  end else begin
    if (counter == sclk_div - 1) begin
      shift_reg <= {shift_reg[6:0], mosi};
      miso <= shift_reg[7];
    end
    counter <= (cs) ? 3'b0 : counter + 1;
  end
end

endmodule

