reg [2:0] counter;

always @(posedge clk or posedge rst) begin
  if (rst) begin
    counter <= 3'b0;
    mosi <= 1'b0;
  end else begin
    if (counter == 7) begin
      shift_reg <= {shift_reg[6:0], miso};
      mosi <= shift_reg[7];
    end
    counter <= (cs) ? 3'b0 : counter + 1;
  end
end

endmodule

module ArithmeticLogicUnit
	#(parameter BUS_WIDTH = 8)
	(input wire [BUS_WIDTH-1:0] a,
	 input wire [BUS_WIDTH-1:0] b,
	 input wire [3:0] command,
	 input wire clk,
	 input wire reset,

    output wire [BUS_WIDTH-1:0] out,
    output wire overflow
    );

	reg addcin;
	wire addcout;
	wire [BUS_WIDTH-1:0] adds;

	reg [BUS_WIDTH-1:0] adda;
	reg [BUS_WIDTH-1:0] addb;

	reg overflow_register;
	reg [BUS_WIDTH-1:0] output_register;

	assign out = output_register;
	assign overflow = overflow_register;

	BitAdder #(.BUS_WIDTH(BUS_WIDTH))  adder(.a(adda),.b(addb),.substract(addcin),.out(adds),.carry(addcout));

	always @(*)
	begin	
		if(reset)
		begin
			addcin = 0;
			adda = 0;
			addb = 0;
			overflow_register = 0;
			output_register = 0;
		end

		case(command)
			0: begin 
					addcin = 0;
					adda = a;
					addb = b;
					overflow_register = addcout; 
					output_register = adds;
				end
			1: begin
					addcin = 1;
					adda = a;
					addb = ~b;
					overflow_register = addcout; 
					output_register = adds;
				end

			2: output_register = a << b;
			3: output_register = a | b;
			4: output_register = a & b;
			5: output_register = a ^ b;			

			6: output_register = (a << b) | (a >> (BUS_WIDTH-b));

			7: overflow_register = (a == b);
			8: overflow_register = (a > b);
			9: overflow_register = (a < b);

			default:
				begin
					overflow_register = 0;
					output_register = 0;
				end
		endcase
	end
endmodule

module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    input carry_in,
    output [3:0] sum,
    output carry_out
);

    wire [3:0] carry;

    assign carry[0] = carry_in;

    genvar i;
    generate
        for (i = 0; i < 4; i = i + 1) begin : adder
            full_adder fa(
                .a(A[i]),
                .b(B[i]),
                .c_in(carry[i]),
                .sum(sum[i]),
                .c_out(carry[i+1])
            );
        end
    endgenerate

    assign carry_out = carry[4];

endmodule

