module counter_timeout
(
    input  clk,
    input  reset,
    input  sync,
    input  [15:0]len,
    output [15:0]size,
    input  start,
    input  stop,
    output reg running
);

    reg [15:0]cnt;
    wire timeout = cnt == len;

    always @(posedge clk or posedge reset)
    begin
        if (reset) running <= 0;
        else if (sync)
        begin
            if (stop || timeout) running <= 0;
            else if (start) running <= 1;
        end
    end

    always @(posedge clk or posedge reset)
    begin
        if (reset) cnt <= 0;
        else if (sync)
        begin
            if (running)    cnt <= cnt + 1;
            else if (start) cnt <= 0;
        end
    end

    assign size = cnt;
endmodule

module four_bit_adder(
  input [3:0] A,
  input [3:0] B,
  output [3:0] S,
  output C
);

  wire [3:0] sum;

  // Full adder for least significant bit
  full_adder fa0(
    .a(A[0]),
    .b(B[0]),
    .c_in(1'b0),
    .sum(sum[0]),
    .c_out(C)
  );

  // Full adder for second least significant bit
  full_adder fa1(
    .a(A[1]),
    .b(B[1]),
    .c_in(C),
    .sum(sum[1]),
    .c_out(C)
  );

  // Full adder for third least significant bit
  full_adder fa2(
    .a(A[2]),
    .b(B[2]),
    .c_in(C),
    .sum(sum[2]),
    .c_out(C)
  );

  // Full adder for most significant bit
  full_adder fa3(
    .a(A[3]),
    .b(B[3]),
    .c_in(C),
    .sum(sum[3]),
    .c_out(C)
  );

  assign S = sum;

endmodule

