module USB_device_controller (
  input usb_dp,
  input usb_dm,
  input reset,
  input clk,
  output reg [6:0] usb_addr,
  output reg [31:0] usb_data,
  output reg [1:0] usb_status
);

parameter USB_DATA_WIDTH = 8;
parameter MAX_PACKET_SIZE = 64;
parameter ENDPOINT_BUFFER_SIZE = 1024;

// USB transaction definitions
parameter USB_PID_OUT = 8'h1;
parameter USB_PID_IN = 8'h9;
parameter USB_PID_SETUP = 8'hD;
parameter USB_PID_ACK = 8'h2;
parameter USB_PID_NAK = 8'hA;
parameter USB_PID_STALL = 8'hE;
parameter USB_PID_DATA0 = 8'h3;
parameter USB_PID_DATA1 = 8'hB;
parameter USB_PID_DATA2 = 8'hC;
parameter USB_PID_MDATA = 8'h0;
parameter USB_PID_PING = 8'h4;
parameter USB_PID_ERR = 8'hC;

// USB protocol definitions
parameter USB_STATE_IDLE = 2'b00;
parameter USB_STATE_SETUP = 2'b01;
parameter USB_STATE_DATA = 2'b10;
parameter USB_STATE_STATUS = 2'b11;

// Endpoint buffer
reg [7:0] endpoint_buffer [0:ENDPOINT_BUFFER_SIZE-1];
reg [9:0] endpoint_buffer_head = 0;
reg [9:0] endpoint_buffer_tail = 0;
reg [9:0] endpoint_buffer_count = 0;

// USB state machine
reg [1:0] usb_state = USB_STATE_IDLE;
reg [2:0] usb_pid = 0;
reg [1:0] usb_data_toggle = 0;
reg [9:0] usb_data_count = 0;
reg [9:0] usb_packet_size = 0;
reg [31:0] usb_setup_packet [0:7];
reg [2:0] usb_setup_packet_index = 0;
reg [6:0] usb_device_address = 0;
reg [1:0] usb_error = 0;

// USB transaction handling logic
always @(posedge clk) begin
  if (reset) begin
    usb_state <= USB_STATE_IDLE;
    usb_pid <= 0;
    usb_data_toggle <= 0;
    usb_data_count <= 0;
    usb_packet_size <= 0;
    usb_setup_packet_index <= 0;
    usb_device_address <= 0;
    usb_error <= 0;
    endpoint_buffer_head <= 0;
    endpoint_buffer_tail <= 0;
    endpoint_buffer_count <= 0;
  end else begin
    case (usb_state)
      USB_STATE_IDLE: begin
        if (usb_dp && !usb_dm) begin
          usb_pid <= usb_dp[2:0];
          case (usb_pid)
            USB_PID_OUT: begin
              usb_state <= USB_STATE_DATA;
              usb_data_toggle <= 0;
              usb_data_count <= 0;
              usb_packet_size <= 0;
            end
            USB_PID_IN: begin
              usb_state <= USB_STATE_DATA;
              usb_data_toggle <= 0;
              usb_data_count <= 0;
              usb_packet_size <= 0;
            end
            USB_PID_SETUP: begin
              usb_state <= USB_STATE_SETUP;
              usb_data_toggle <= 0;
              usb_data_count <= 0;
              usb_packet_size <= 8;
              usb_setup_packet_index <= 0;
            end
            default: begin
              usb_error <= 1;
              usb_pid <= USB_PID_ERR;
            end
          endcase
        end
      end
      USB_STATE_SETUP: begin
        if (usb_dp && !usb_dm) begin
          usb_setup_packet[usb_setup_packet_index] <= usb_dp[7:0];
          usb_setup_packet_index <= usb_setup_packet_index + 1;
          if (usb_setup_packet_index == 8) begin
            usb_state <= USB_STATE_DATA;
            usb_data_toggle <= 0;
            usb_data_count <= 0;
            usb_packet_size <= MAX_PACKET_SIZE;
            usb_setup_packet_index <= 0;
            usb_device_address <= usb_setup_packet[4:0];
          end
        end
      end
      USB_STATE_DATA: begin
        if (usb_dp && !usb_dm) begin
          case (usb_pid)
            USB_PID_OUT: begin
              if (usb_data_toggle == usb_dp[0]) begin
                endpoint_buffer[endpoint_buffer_head] <= usb_dp[7:0];
                endpoint_buffer_head <= endpoint_buffer_head + 1;
                endpoint_buffer_count <= endpoint_buffer_count + 1;
                usb_data_toggle <= ~usb_data_toggle;
                usb_data_count <= usb_data_count + USB_DATA_WIDTH;
                if (usb_data_count == usb_packet_size) begin
                  usb_state <= USB_STATE_STATUS;
                  usb_data_toggle <= 0;
                  usb_data_count <= 0;
                  usb_packet_size <= 0;
                  usb_pid <= USB_PID_ACK;
                end
              end else begin
                usb_error <= 1;
                usb_pid <= USB_PID_ERR;
              end
            end
            USB_PID_IN: begin
              if (usb_data_toggle == usb_dp[0]) begin
                usb_data <= endpoint_buffer[endpoint_buffer_tail];
                endpoint_buffer_tail <= endpoint_buffer_tail + 1;
                endpoint_buffer_count <= endpoint_buffer_count - 1;
                usb_data_toggle <= ~usb_data_toggle;
                usb_data_count <= usb_data_count + USB_DATA_WIDTH;
                if (usb_data_count == usb_packet_size) begin
                  usb_state <= USB_STATE_STATUS;
                  usb_data_toggle <= 0;
                  usb_data_count <= 0;
                  usb_packet_size <= 0;
                  usb_pid <= USB_PID_ACK;
                end
              end else begin
                usb_error <= 1;
                usb_pid <= USB_PID_ERR;
              end
            end
            default: begin
              usb_error <= 1;
              usb_pid <= USB_PID_ERR;
            end
          endcase
        end
      end
      USB_STATE_STATUS: begin
        if (usb_dp && !usb_dm) begin
          if (usb_dp[2:0] == USB_PID_OUT) begin
            usb_state <= USB_STATE_IDLE;
            usb_pid <= 0;
          end else if (usb_dp[2:0] == USB_PID_IN) begin
            usb_state <= USB_STATE_DATA;
            usb_data_toggle <= 0;
            usb_data_count <= 0;
            usb_packet_size <= MAX_PACKET_SIZE;
            usb_pid <= USB_PID_DATA1;
          end else begin
            usb_error <= 1;
            usb_pid <= USB_PID_ERR;
          end
        end
      end
      default: begin
        usb_error <= 1;
        usb_pid <= USB_PID_ERR;
      end
    endcase
  end
end

// USB status handling logic
always @(posedge clk) begin
  if (reset) begin
    usb_status <= 0;
  end else begin
    case (usb_pid)
      USB_PID_ACK: begin
        usb_status <= 2'b10;
      end
      USB_PID_NAK: begin
        usb_status <= 2'b01;
      end
      USB_PID_STALL: begin
        usb_status <= 2'b11;
      end
      default: begin
        usb_status <= 2'b00;
      end
    endcase
  end
end

endmodule

