module top_module (
    input [7:0] a,
    input [7:0] b,
    output [7:0] sum,
    output overflow
);

wire [7:0] sum1, sum2;
wire cout1, cout2;
wire [7:0] diff;
wire borrow;

adder adder1(.a(a), .b(b), .cin(1'b0), .sum(sum1), .cout(cout1));
adder adder2(.a(~a), .b(1'b1), .cin(cout1), .sum(diff), .cout(borrow));
adder adder3(.a(diff), .b(b), .cin(cout1), .sum(sum2), .cout(cout2));

assign sum = (borrow) ? ~sum2 + 1 : sum2;
overflow_detector overflow_detector1(.sum(sum), .overflow(overflow));

endmodule

module adder (
    input [7:0] a,
    input [7:0] b,
    input cin,
    output [7:0] sum,
    output cout
);

wire [7:0] sum_temp;
wire [7:0] carry_temp;

