generate
    for (i = 0; i < 8; i = i + 1) begin : adder_loop
        full_adder full_adder1(.a(a[i]), .b(b[i]), .cin(cin), .sum(sum_temp[i]), .cout(carry_temp[i]));
        assign cin = carry_temp[i];
    end
endgenerate

assign sum = sum_temp;
assign cout = carry_temp[7];

