module full_adder (
    input a,
    input b,
    input cin,
    output sum,
    output cout
);

assign sum = a ^ b ^ cin;
assign cout = (a & b) | (a & cin) | (b & cin);

endmodule

module overflow_detector (
    input [7:0] sum,
    output overflow
);

assign overflow = (sum[7] == 1) ? ~(sum[6:0]) : (sum[6:0] == 7'b1111111);

endmodule

module up_down_counter (
    input clk,
    input reset,
    input up_down,
    input load,
    input [3:0] load_value,
    output [3:0] q,
    output sum
);

    wire [1:0] input_bits;
    wire [1:0] output_bits;
    wire carry_out;

    // Instantiate half adder
    half_adder ha (
        .a(input_bits[0]),
        .b(input_bits[1]),
        .sum(output_bits[0]),
        .carry_out(carry_out)
    );

    // Instantiate binary up-down counter
    binary_up_down_counter counter (
        .clk(clk),
        .reset(reset),
        .up_down(up_down),
        .load(load),
        .load_value(load_value),
        .q(q)
    );

    // Instantiate functional module
    functional_module fm (
        .input_bits(input_bits),
