module binary_up_down_counter (
    input clk,
    input reset,
    input up_down,
    input load,
    input [3:0] load_value,
    output reg [3:0] q
);

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            q <= 4'b0000;
        end else if (load) begin
            q <= load_value;
        end else if (up_down) begin
            q <= q + 1;
        end else begin
            q <= q - 1;
        end
    end

endmodule

