module priority_encoder_accumulator (
    input clk,             // Clock input
    input rst_n,           // Active low reset input
    input [7:0] in,        // 8-bit input for the accumulator
    input valid_a,         // Valid input for the accumulator
    input ready_b,         // Ready input for the priority encoder
    output ready_a,        // Ready output for the accumulator
    output reg valid_b,    // Valid output for the priority encoder
    output reg [9:0] out   // 10-bit output from the functional module
);

    // Priority Encoder
    reg [7:0] input_reg;
    reg [2:0] priority_enc;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            input_reg <= 8'b0;
            priority_enc <= 3'b000;
            valid_b <= 1'b0;
        end
        else begin
            input_reg <= in;
            if (ready_b) begin
                priority_enc <= {~|input_reg[7:4], ~|input_reg[3:0]};
                valid_b <= 1'b1;
            end
        end
    end

    // Accumulator
    reg [31:0] acc_reg;
    reg [1:0] count;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            acc_reg <= 32'b0;
            count <= 2'b00;
            ready_a <= 1'b1;
        end
        else begin
            if (valid_a && ready_a) begin
                acc_reg <= acc_reg + {24'b0, in};
                count <= count + 1'b1;
                if (count == 2'b11) begin
                    count <= 2'b00;
                    out <= acc_reg[31:22];
                    acc_reg <= 32'b0;
                    ready_a <= 1'b0;
                end
            end
        end
    end

    // Functional Module
    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            out <= 10'b0;
        end
        else begin
            if (valid_b && ready_a) begin
                out <= priority_enc + acc_reg[31:22];
                ready_a <= 1'b1;
            end
        end
    end

endmodule

module MUX4x1_custom (S, D0, D1, D2, D3, Z);
input  S;
input  D0;
input  D1;
input  D2;
input  D3;
output Z;

wire not_S, not_S1, not_S0;
wire M0, M1, M2, M3;
wire O0, O1;

not (not_S, S);
not (not_S1, S[1]);
not (not_S0, S[0]);

and (M0, D0, not_S1, not_S0);
and (M1, D1, not_S1, S0);
and (M2, D2, S1, not_S0);
and (M3, D3, S1, S0);

or (O0, M0, M1);
or (O1, M2, M3);

and (Z, O0, not_S);
and (Z, O1, S);

endmodule

