// Booth multiplier module
module booth_multiplier (
    input [3:0] A,
    input [3:0] B,
    output reg [7:0] product
);
    reg [7:0] m;
    reg [7:0] a;
    reg [3:0] b;
    reg [1:0] count;

    always @(*) begin
        m = {A, 4'b0};
        a = {4'b0, A};
        b = {4'b0, B};
        count = 2;
        product = 8'b0;

        while (count > 0) begin
            if (b[0] == 1 && count == 2) begin
                product = product + m;
            end else if (b[0] == 0 && count == 2) begin
                product = product;
            end else if (b[0] == 1 && count == 1) begin
                product = product + a;
            end else if (b[0] == 0 && count == 1) begin
                product = product;
            end
            if (product[0] == 1) begin
                product = {product[7:1], product[0]};
                product = product + {4'b0, -m};
            end else begin
                product = {product[7:1], product[0]};
                product = product + {4'b0, m};
            end
            b = {b[3], b[2], b[1], product[7]};
            count = count - 1;
        end
    end

endmodule

