    input [7:0] d2,   // 8-bit input for the second register
    output [7:0] q    // 8-bit output from the functional module
);

    reg [7:0] reg1, reg2;
    wire [7:0] diff;

    // Registers with synchronous reset
    always @(posedge clk) begin
        if (reset) begin
            reg1 <= 8'd0;
            reg2 <= 8'd0;
        end else begin
            reg1 <= d1;
            reg2 <= d2;
        end
    end

    // Difference calculator
    assign diff = reg1 - reg2;

    // Output
    assign q = diff;

endmodule

module counter_mod_rtl(
  input clk, rst, up_down,
  output reg [3:0] q,
  output reg carry
);

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      q <= 4'b0;
      carry <= 1'b0;
    end else if (up_down == 1'b0) begin
      // Up counter
      if (q == 4'b1111) begin
        q <= 4'b0;
        carry <= 1'b1;
      end else begin
        q <= q + 4'b1;
        carry <= 1'b0;
      end
    end else begin
      // Down counter
      if (q == 4'b0000) begin
        q <= 4'b1111;
        carry <= 1'b1;
      end else begin
        q <= q - 4'b1;
        carry <= 1'b0;
      end
    end
  end

endmodule

