module EchoCancellation (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 2; // number of input signals
parameter m = 2; // number of output signals
parameter d = 64; // delay in number of samples

reg [n-1:0] delayed_in;
wire [n-1:0] subtracted_in;

// Delay element
always @(in) begin
  delayed_in <= {in[d-1:0], in[n-1:d]};
end

// Subtraction element
assign subtracted_in = in - delayed_in;

// Output signals
assign out = subtracted_in;

endmodule

