module lsu_streaming_prefetch_avalon_bust_master #(
        parameter AWIDTH           = 32,
        parameter MWIDTH           = 256,
        parameter MWIDTH_BYTES     = 32,
        parameter BURSTCOUNT_WIDTH = 6,
        parameter FIFO_DEPTH_LOG2   = 5
    ) (
        input clk,
        input reset,
        input flush,
        output active,

        // from FIFO
        output                            ready,
        input            [AWIDTH - 1 : 0] fifo_read_addr,
        input                             fifo_read,
        input  [BURSTCOUNT_WIDTH - 1 : 0] fifo_burst_size,
        output                            fifo_data_valid,
        output            [MWIDTH -1 : 0] fifo_data,

        // master inputs and outputs
        output           [AWIDTH - 1 : 0] master_address,
        output                            master_read,
        output     [MWIDTH_BYTES - 1 : 0] master_byteenable,
        input            [MWIDTH - 1 : 0] master_readdata,
        input                             master_readdatavalid,
        output [BURSTCOUNT_WIDTH - 1 : 0] master_burstcount,
        input                             master_waitrequest
    );

    reg  [FIFO_DEPTH_LOG2 : 0] pending_reads;
    reg  [FIFO_DEPTH_LOG2 : 0] pending_discards; //at most we will need to discard 2 full bursts of data
    wire                      keep_read;
    wire                      avm_read_accepted;
    wire                      finished_discard;
    wire                      can_discard_full_burst;

    // track pending reads
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            pending_reads <= 0;
            pending_discards <= 0;
        end else begin
            if (flush) begin
                pending_reads <= 0;
                pending_discards <= pending_discards + pending_reads - master_readdatavalid;
            end else begin
                pending_reads <= pending_reads + (avm_read_accepted ? master_burstcount : 0) - keep_read;
                pending_discards <= pending_discards - (~finished_discard & master_readdatavalid);
            end
        end
    end

    assign finished_discard = (pending_discards == 0);
    assign can_discard_full_burst = ~pending_discards[FIFO_DEPTH_LOG2];
    assign keep_read = finished_discard & master_readdatavalid;
    assign avm_read_accepted = master_read & !master_waitrequest;

    // check for memory stall
    assign ready = !master_waitrequest & can_discard_full_burst;

    assign master_address = fifo_read_addr;
    assign master_read = fifo_read & can_discard_full_burst & !flush;
    assign master_byteenable = {MWIDTH_BYTES{1'b1}};
    assign master_burstcount = fifo_burst_size;

    assign fifo_data = master_readdata;
    assign fifo_data_valid = keep_read;

    assign active = |pending_reads | ~finished_discard;

endmodule

module top_module (
    input [3:0] in,
    output [15:0] out1, // Outputs from 4-to-16 decoder
    output [7:0] out2, // Outputs from 3-to-8 decoder
    output [15:0] out_final // Bitwise OR of out1 and out2
);

// 4-to-16 decoder using NAND gates
wire [15:0] nand_out;
assign nand_out[0] = ~(in[0] & in[1] & in[2] & in[3]);
assign nand_out[1] = ~(in[0] & in[1] & in[2] & ~in[3]);
assign nand_out[2] = ~(in[0] & in[1] & ~in[2] & in[3]);
assign nand_out[3] = ~(in[0] & in[1] & ~in[2] & ~in[3]);
assign nand_out[4] = ~(in[0] & ~in[1] & in[2] & in[3]);
assign nand_out[5] = ~(in[0] & ~in[1] & in[2] & ~in[3]);
assign nand_out[6] = ~(in[0] & ~in[1] & ~in[2] & in[3]);
assign nand_out[7] = ~(in[0] & ~in[1] & ~in[2] & ~in[3]);
assign nand_out[8] = ~(~in[0] & in[1] & in[2] & in[3]);
assign nand_out[9] = ~(~in[0] & in[1] & in[2] & ~in[3]);
assign nand_out[10] = ~(~in[0] & in[1] & ~in[2] & in[3]);
assign nand_out[11] = ~(~in[0] & in[1] & ~in[2] & ~in[3]);
assign nand_out[12] = ~(~in[0] & ~in[1] & in[2] & in[3]);
assign nand_out[13] = ~(~in[0] & ~in[1] & in[2] & ~in[3]);
assign nand_out[14] = ~(~in[0] & ~in[1] & ~in[2] & in[3]);
assign nand_out[15] = ~(~in[0] & ~in[1] & ~in[2] & ~in[3]);
assign out1 = nand_out;

// 3-to-8 decoder with active-low outputs
wire [7:0] decoder_out;
assign decoder_out[0] = ~(in[0] & in[1] & in[2]);
assign decoder_out[1] = ~(in[0] & in[1] & ~in[2]);
assign decoder_out[2] = ~(in[0] & ~in[1] & in[2]);
assign decoder_out[3] = ~(in[0] & ~in[1] & ~in[2]);
assign decoder_out[4] = ~(~in[0] & in[1] & in[2]);
assign decoder_out[5] = ~(~in[0] & in[1] & ~in[2]);
assign decoder_out[6] = ~(~in[0] & ~in[1] & in[2]);
assign decoder_out[7] = ~(~in[0] & ~in[1] & ~in[2]);
assign out2 = decoder_out;

// Bitwise OR of out1 and out2
wire [15:0] or_out;
assign or_out = out1 | {8'b0, out2};
assign out_final = or_out;

endmodule

module combinational_logic(
    input wire A,
    input wire B,
    input wire C,
    input wire D,
    output reg X,
    output reg Y
);

always @(*) begin
    if (A) begin
        X = 1'b1;
        Y = 1'b0;
    end else begin
        if (B || (C && !D)) begin
            X = 1'b1;
        end else begin
            X = 1'b0;
        end
        if (!B || (C && D)) begin
            Y = 1'b1;
        end else begin
            Y = 1'b0;
        end
    end
end

endmodule

module adder_subtractor (
    input [3:0] A,
    input [3:0] B,
    input SUB,
    output reg [3:0] SUM,
    output reg CARRY
);

reg [3:0] A_reg, B_reg, SUM_reg;
reg SUB_reg;

always @(posedge clk) begin
    A_reg <= A;
    B_reg <= B;
    SUB_reg <= SUB;
end

always @(posedge clk) begin
    if (SUB_reg) begin
        SUM_reg <= A_reg - B_reg;
        CARRY <= (A_reg < B_reg);
    end else begin
        SUM_reg <= A_reg + B_reg;
        CARRY <= (SUM_reg[4] == 1);
    end
end

always @(posedge clk) begin
    SUM <= SUM_reg;
end

endmodule

