    if (!reset) begin
        Q <= 4'b0000;
    end else begin
        case (shift_amount)
            2'b00: Q <= A;
            2'b01: Q <= {A[2:0], A[3]};
            2'b10: Q <= {A[3], A[3:1]};
            2'b11: Q <= {A[2:0], A[3]};
