module up_down_counter (
    input clk,
    input reset,
    input up_down,
    output wire [3:0] count
);

reg [3:0] shift_reg;
wire [3:0] decoder_out;

assign decoder_out[0] = (shift_reg == 4'b0001) ? 1'b1 : 1'b0;
assign decoder_out[1] = (shift_reg == 4'b0010) ? 1'b1 : 1'b0;
assign decoder_out[2] = (shift_reg == 4'b0100) ? 1'b1 : 1'b0;
assign decoder_out[3] = (shift_reg == 4'b1000) ? 1'b1 : 1'b0;

wire [1:0] mux_sel;
assign mux_sel = (up_down) ? 2'b10 : 2'b01;

always @(posedge clk) begin
    if (reset) begin
        shift_reg <= 4'b0000;
    end else begin
        shift_reg <= {shift_reg[2:0], shift_reg[3]};
        shift_reg[0] <= mux_sel[0] ^ mux_sel[1];
    end
end

