module cache_ctl(
    input clk,
    input enable,
    input [3:0] index,
    input [1:0] word,
    input cmp,
    input write,
    input [4:0] tag,
    input [15:0] data_in,
    input valid_in,
    input rst,
    output [15:0] data_out,
    output reg [4:0] tag_out,
    output reg hit,
    output reg dirty,
    output reg valid
);

parameter NUM_LINES = 16;
parameter LINE_SIZE = 16;
parameter TAG_SIZE = 5;
parameter WORD_SIZE = 2;
parameter INDEX_SIZE = $clog2(NUM_LINES);

reg [LINE_SIZE-1:0] cache [NUM_LINES-1:0];
reg [TAG_SIZE-1:0] tag_array [NUM_LINES-1:0];
reg [1:0] lru_array [NUM_LINES-1:0];
reg [0:1] word_select;

reg [3:0] index_reg;
reg [4:0] tag_reg;
reg [1:0] lru_reg;
reg [15:0] data_reg;
reg valid_reg;
reg dirty_reg;

integer i;
integer lru_index;

always @(posedge clk) begin
    if (rst) begin
        for (i = 0; i < NUM_LINES; i = i + 1) begin
            cache[i] <= 0;
            tag_array[i] <= 0;
            lru_array[i] <= 0;
        end
        index_reg <= 0;
        tag_reg <= 0;
        word_select <= 0;
        lru_reg <= 0;
        data_reg <= 0;
        valid_reg <= 0;
        dirty_reg <= 0;
        tag_out <= 0;
        hit <= 0;
        valid <= 0;
    end else if (enable) begin
        index_reg <= index;
        tag_reg <= tag;
        word_select <= word;
        if (write) begin
            cache[index][word_select*8 +: 8] <= data_in;
            tag_array[index] <= tag_reg;
            valid_reg <= valid_in;
            dirty_reg <= 1;
        end else begin
            hit <= 0;
            for (i = 0; i < NUM_LINES; i = i + 1) begin
                if (tag_array[i] == tag_reg) begin
                    lru_array[i] <= 3;
                    lru_index = i;
                    hit <= 1;
                end else if (lru_array[i] > 0) begin
                    lru_array[i] <= lru_array[i] - 1;
                end
            end
            if (hit) begin
                data_reg <= cache[lru_index];
                lru_array[lru_index] <= 3;
                dirty_reg <= 0;
            end else begin
                lru_index = 0;
                for (i = 0; i < NUM_LINES; i = i + 1) begin
                    if (lru_array[i] < lru_array[lru_index]) begin
                        lru_index = i;
                    end
                end
                if (dirty_reg) begin
                    cache[lru_index] <= cache[lru_index];
                end
                cache[lru_index] <= {data_in[15:8], data_in[7:0]};
                tag_array[lru_index] <= tag_reg;
                lru_array[lru_index] <= 3;
                data_reg <= cache[lru_index];
                dirty_reg <= 0;
            end
        end
    end
end

always @(posedge clk) begin
    if (enable) begin
        case (word_select)
            2'b00: data_out <= {cache[index_reg][7:0], cache[index_reg][15:8]};
            2'b01: data_out <= {cache[index_reg][23:16], cache[index_reg][31:24]};
            2'b10: data_out <= {cache[index_reg][39:32], cache[index_reg][47:40]};
            2'b11: data_out <= {cache[index_reg][55:48], cache[index_reg][63:56]};
        endcase
        tag_out <= tag_array[index_reg];
        valid <= valid_reg;
        if (hit) begin
            lru_reg <= lru_array[lru_index];
        end else begin
            lru_reg <= 3;
        end
        if (write) begin
            dirty <= 1;
        end else begin
            dirty <= dirty_reg;
        end
    end
end

endmodule

