module Hyperbolic_Functions (
  input x,
  output sineh_x,
  output cosh_x,
  output tanh_x
);

  // Calculate e^x and e^(-x)
  wire exp_x = exp(x);
  wire exp_neg_x = exp(-x);

  // Calculate sineh(x)
  wire sineh_x_temp = exp_x - exp_neg_x;
  assign sineh_x = sineh_x_temp / 2;

  // Calculate cosh(x)
  wire cosh_x_temp = exp_x + exp_neg_x;
  assign cosh_x = cosh_x_temp / 2;

  // Calculate tanh(x)
  wire tanh_x_temp = exp_x - exp_neg_x;
  assign tanh_x = tanh_x_temp / cosh_x_temp;

endmodule

module fsm_control(
	input 		clk,
	input		clk_cpu,
	input 		rst,
	input		jt_sample,
	// Sound
	output reg	[ 7:0] sound_latch,
	input		[15:0] jt_left,
	input		[15:0] jt_right,         
	output reg 	irq,
	input 		clear_irq,
	// Program
	output reg	cpu_rst,
	output		rom_prog,
	output reg	rom_wr,
	output reg [14:0] rom_addr,
	output reg [7:0]  rom_data,
	// UART wires
	input		uart_rx,
	output		uart_tx
);	

// Define states
parameter STATE_IDLE = 2'b00;
parameter STATE_SEND_LSB = 2'b01;
parameter STATE_SEND_MSB = 2'b10;

// Define send state machine
reg [1:0] send_state;
reg [7:0] send_data;
reg send_done;

// Define program state machine
reg [1:0] prog_state;
reg prog_done;

// Define UART transceiver
wire  	[7:0] 	uart_rx_data; 
reg		[7:0]	uart_tx_data;
wire 			uart_received, uart_error;
reg				uart_tx_wr;
wire			uart_tx_done;
reg	[1:0] 	send_st;
uart_transceiver u_uart(
	.sys_rst( rst ),
	.sys_clk( clk ),

	.uart_rx(uart_rx),
	.uart_tx(uart_tx),

	// 461 kbps @ 50MHz
	// .clk_divider(  5'd6 ), 
	// 921.6 kbps @ 50MHz
	.clk_divider(  5'd3 ), 
	.uart_divider( 5'd17 ), 

	.rx_data( uart_rx_data ),
	.rx_done( uart_received ),
	.rx_error( uart_error ),

	.tx_data	( uart_tx_data	),
	.tx_wr		( uart_tx_wr	),
	.tx_done	( uart_tx_done	)
);

// Define sound generation
reg [15:0] left, right, mono;
reg sample;

always @(*) { left, right, sample } <= { jt_left, jt_right, jt_sample };    
always @(*) mono <= (left+right)>>1;

// Define interrupt generation
reg set_irq;

always @(posedge clk_cpu or posedge rst ) begin
	if( rst )
		irq <= 1'b0;
	else begin
		if(set_irq) irq<=1'b1;
		else if(clear_irq ) irq<=1'b0;
	end
end

// Define CPU reset
always @(posedge clk or posedge rst ) begin
	if( rst ) begin
		cpu_rst		<= 1'b1;
		prog_done	<= 1'b0;
		prog_state	<= STATE_IDLE;
		send_state	<= STATE_IDLE;
	end
	else begin		
		if( uart_received && !uart_error ) begin
			if( prog_done ) begin					
					sound_latch <= uart_rx_data;
					set_irq     <= 1'b1;
				end
			else begin
					prog_state	<= STATE_SEND_LSB;
					send_data	<= sound_latch;
					send_done	<= 0;
				end
    	end
		else begin
			cpu_rst <= !prog_done;
			if(irq) set_irq <= 1'b0;
		end
	end	
end

// Define program ROM
always @(posedge clk or posedge rst ) begin
	if( rst ) begin
		rom_prog	<= 1'b1;
		rom_addr	<= 15'h0;
		rom_wr		<= 1'b0;
		rom_data	<= 8'h00;
	end
	else begin
		if( prog_state == STATE_IDLE ) begin
			rom_prog	<= 1'b1;
			rom_wr		<= 1'b0;
			prog_done	<= 1'b1;
		end
		else begin
			rom_prog	<= 1'b0;
			rom_wr		<= 1'b1;
			rom_data	<= send_data;
			if( send_done ) begin
				prog_state	<= STATE_IDLE;
				prog_done	<= 1'b1;
			end
		end
		if( prog_state == STATE_SEND_LSB ) begin
			send_state	<= STATE_SEND_MSB;
			send_data	<= sound_latch[7:0];
			send_done	<= 0;
			rom_addr	<= rom_addr + 1;
			prog_state	<= STATE_SEND_MSB;
		end
		else if( prog_state == STATE_SEND_MSB ) begin
			send_state	<= STATE_IDLE;
			send_data	<= sound_latch[15:8];
			send_done	<= 0;
			rom_addr	<= rom_addr + 1;
			prog_state	<= STATE_IDLE;
		end
	end
end

// Define UART transmit
always @(posedge clk or posedge rst) begin
	if( rst ) begin
		uart_tx_wr	<= 1'b0;
		send_st		<= STATE_IDLE;
	end
	else begin
		case( send_st )
			STATE_IDLE:
				if( sample && !last_sample ) begin
					send_st		<= STATE_SEND_LSB;
					uart_tx_data<= mono[7:0];
					uart_tx_wr	<= 1'b1;
				end
			STATE_SEND_LSB: begin
				uart_tx_wr	<= 1'b0;
				if( uart_tx_done ) begin
					send_st		<= STATE_SEND_MSB;
					uart_tx_data<= mono[15:8];
					uart_tx_wr	<= 1'b1;
				end
			end
			STATE_SEND_MSB: begin
				uart_tx_wr	<= 1'b0;
				if( uart_tx_done ) 
					send_st		<= STATE_IDLE;
			end
		endcase
	end
end

// Define last sample for UART transmit
reg	last_sample;

always @(posedge clk or posedge rst) begin
	if( rst ) begin
		last_sample <= 0;
	end
	else begin
		last_sample <= sample;
	end
end

endmodule

