module dds_channel (
  input clk,
  input [15:0] phase,
  input [15:0] scale,
  output [15:0] sine,
  output [31:0] acc,
  output [31:0] adder
);

  localparam WIDTH = 16; // data width
  localparam PHASE_WIDTH = 16; // phase width
  localparam ACC_WIDTH = 32; // accumulator width

  reg [PHASE_WIDTH-1:0] phase_r = 16'h0000; // register for phase
  reg [PHASE_WIDTH-1:0] phase_inc_r = 16'h0000; // register for phase increment
  reg [ACC_WIDTH-1:0] acc_r = 32'h00000000; // register for accumulator

  // generate sine wave
  always @(posedge clk) begin
    phase_r <= phase;
    phase_inc_r <= scale;
  end

  assign sine = $sin(phase_r);

  // update accumulator
  always @(posedge clk) begin
    acc_r <= acc_r + phase_inc_r;
  end

  assign acc = acc_r;

  // generate output
  assign adder = {acc_r[ACC_WIDTH-1], acc_r[ACC_WIDTH-2:WIDTH-1]} + {sine[WIDTH-1], sine[WIDTH-2:0], {WIDTH{1'b0}}};

endmodule

