module code_tracking_loop (
  input [code_length-1:0] in,
  input [code_length-1:0] code_rep,
  input [31:0] freq_offset,
  output [code_length-1:0] error,
  output [code_length-1:0] code_rep_out
);

parameter code_length = 1023; // length of pseudorandom code used in GPS signal.

reg [code_length-1:0] code_rep_adj; // adjusted code replica
reg [code_length-1:0] code_rep_phase; // code replica phase
reg [code_length-1:0] code_rep_corr; // correlation between received signal and code replica
reg [code_length-1:0] error_reg; // error signal

// generate code replica with adjusted frequency
always @ (posedge clk) begin
  code_rep_adj <= code_rep * exp(freq_offset);
end

// correlate received signal with code replica and generate error signal
always @ (posedge clk) begin
  code_rep_corr <= in * code_rep_adj;
  error_reg <= code_length/2 - $countones(code_rep_corr);
end

// adjust phase of code replica using PLL
always @ (posedge clk) begin
  code_rep_phase <= code_rep_phase + error_reg;
end

// generate output code replica and error signal
always @ (posedge clk) begin
  code_rep_out <= code_rep * exp(code_rep_phase);
  error <= error_reg;
end

endmodule

