module file_reader(
    input clk,
    input rst,
    input file_in,
    input read_enable,
    output reg [31:0] data_out,
    output reg pass
);

  reg [31:0] in_32;
  integer res, fd;

  always @(posedge clk) begin
    if (rst) begin
      data_out <= 0;
      pass <= 0;
    end else if (read_enable) begin
      // read data from file
      fd = $fopen(file_in, "rb");
      res = $fscanf(fd, "%u", in_32);
      $fclose(fd);

      // check for missing bytes
      if (res !== -1) begin
        $display("FAILED: $fscanf() returned %d (%b)", res, in_32);
        pass <= 0;
      end

      // assign output data
      data_out <= in_32;

      // check suppression of data reads
      fd = $fopen(file_in, "rb");
      res = $fscanf(fd, "%*u", in_32);
      $fclose(fd);
      if (res !== -1) begin
        $display("FAILED: $fscanf() suppression returned %d (%b)", res, in_32);
        pass <= 0;
      end

      // check that data was read correctly
      fd = $fopen(file_in, "rb");
      res = $fscanf(fd, "%u", in_32);
      $fclose(fd);
      if (res !== 1) begin
        $display("FAILED: $fscanf() read returned %d (%b)", res, in_32);
        pass <= 0;
      end else if (in_32 !== data_out) begin
        $display("FAILED: Data mismatch (%b != %b)", in_32, data_out);
        pass <= 0;
      end

      // check that there is no more data to read
      fd = $fopen(file_in, "rb");
      res = $fscanf(fd, "%u", in_32);
      $fclose(fd);
      if (res !== -1) begin
        $display("FAILED: EOF not reached (%d bytes remaining)", res);
        pass <= 0;
      end

      // if all checks passed, set pass signal
      if (pass) pass <= 1;
    end
  end
endmodule

module Full_Adder (
  input A,
  input B,
  input Cin,
  output S,
  output Cout
);

  // XOR gate function
  function [0:0] XOR;
    input [0:0] a, b;
    begin
      XOR = a ^ b;
    end
  endfunction

  // OR gate function
  function [0:0] OR;
    input [0:0] a, b;
    begin
      OR = a | b;
    end
  endfunction

  // Compute sum output (S)
  assign S = XOR(XOR(A, B), Cin);

  // Compute carry-out output (Cout)
  assign Cout = OR(AND(A, B), AND(Cin, XOR(A, B)));

endmodule

