module ripple_adder (
    input [3:0] a,
    input [3:0] b,
    output reg [4:0] sum
);

    reg carry;

    always @(*) begin
        sum[0] = a[0] ^ b[0] ^ carry;
        sum[1] = a[1] ^ b[1] ^ carry;
        sum[2] = a[2] ^ b[2] ^ carry;
        sum[3] = a[3] ^ b[3] ^ carry;
        carry = (a[0] & b[0]) | (a[1] & b[1]) | (a[2] & b[2]) | (a[3] & b[3]) | (a[0] & b[1]) | (a[1] & b[2]) | (a[2] & b[3]) | (a[3] & 1'b0);
        sum[4] = carry;
    end

endmodule

module top_module( 
    input [3:0] in,
    output out_nand,
    output out_nor,
    output out_xnor
);

wire [3:0] inv_in;
wire [3:0] and1_out;
wire [3:0] and2_out;
wire [3:0] and3_out;

// Inverters
assign inv_in = ~in;

// AND gates
assign and1_out = inv_in & {inv_in[2], inv_in[1], inv_in[0]};
assign and2_out = inv_in & {inv_in[3], inv_in[2], inv_in[1]};
assign and3_out = inv_in & {in[3], in[2], in[1], in[0]};

// Outputs
assign out_nand = ~(and1_out[3] & and1_out[2] & and1_out[1] & and1_out[0]);
assign out_nor = ~(and2_out[3] | and2_out[2] | and2_out[1] | and2_out[0]);
assign out_xnor = ~(and3_out[3] ^ and3_out[2] ^ and3_out[1] ^ and3_out[0]);

endmodule

module processor(
    input clk,
    input reset,
    input [7:0] instruction,
    input [31:0] data_in,
    input select,
    output reg [31:0] data_out,
    output flag
);

  wire [31:0] alu_out;
  wire [3:0] rs, rt, rd;
  wire [15:0] regfile [15:0];
  wire flag_out;
  wire [1:0] mux_sel;

  pipeline pipe(clk, reset, instruction, regfile, flag_out);
  three_to_four_mux mux(alu_out, regfile[rd], data_in, data_out, mux_sel);
  control ctrl(instruction, rs, rt, rd, select, mux_sel);
  alu alu(rs, rt, alu_out, flag_out);

  assign flag = flag_out;

endmodule

module pipeline (
  input clk,
  input reset,
  input [7:0] instruction,
  output reg [31:0] regfile [15:0],
  output reg flag
);

  reg [31:0] pc;
  reg [31:0] instruction_reg;
  reg [3:0] rs, rt, rd;
  reg [1:0] stage;
  wire [31:0] alu_out;
  wire flag_out;

  always @(posedge clk) begin
    if (reset) begin
      pc <= 0;
      instruction_reg <= 0;
      rs <= 0;
      rt <= 0;
      rd <= 0;
      stage <= 0;
      flag <= 0;
      regfile <= 0;
    end else begin
      case (stage)
        0: begin // Fetch
          instruction_reg <= instruction;
          pc <= pc + 1;
          stage <= 1;
        end
        1: begin // Decode
          rs <= instruction_reg[23:20];
          rt <= instruction_reg[19:16];
          rd <= instruction_reg[15:12];
          stage <= 2;
        end
        2: begin // Execute
          alu_out <= regfile[rs] + regfile[rt];
          flag_out <= (alu_out < 0);
          stage <= 3;
        end
        3: begin // Writeback
          regfile[rd] <= alu_out;
          flag <= flag_out;
          stage <= 0;
        end
      endcase
    end
  end

endmodule

module three_to_four_mux(
  input [31:0] in0,
  input [31:0] in1,
  input [31:0] in2,
  input [31:0] in3,
  input [1:0] sel,
  output reg [31:0] out
);

  always @(*) begin
    case (sel)
      0: out <= in0;
      1: out <= in1;
      2: out <= in2;
      3: out <= in3;
    endcase
  end

endmodule

module control(
  input [7:0] instruction,
  output reg [3:0] rs,
  output reg [3:0] rt,
  output reg [3:0] rd,
  output reg select,
  output reg [1:0] mux_sel
);

  always @(*) begin
    case (instruction[7:4])
      4'h0: begin // ADD
        rs <= instruction[3:0];
        rt <= instruction[7:4];
        rd <= instruction[11:8];
        select <= 1;
        mux_sel <= 0;
      end
      4'h1: begin // SUB
        rs <= instruction[3:0];
        rt <= instruction[7:4];
        rd <= instruction[11:8];
        select <= 1;
        mux_sel <= 1;
      end
      4'h2: begin // AND
        rs <= instruction[3:0];
        rt <= instruction[7:4];
        rd <= instruction[11:8];
        select <= 1;
        mux_sel <= 2;
      end
      4'h3: begin // OR
        rs <= instruction[3:0];
        rt <= instruction[7:4];
        rd <= instruction[11:8];
        select <= 1;
        mux_sel <= 3;
      end
      default: begin // NOP
        rs <= 0;
        rt <= 0;
        rd <= 0;
        select <= 0;
        mux_sel <= 0;
      end
    endcase
  end

endmodule

module alu(
  input [3:0] rs,
  input [3:0] rt,
  output reg [31:0] out,
  output reg flag
);

  always @(*) begin
    out <= rs + rt;
    flag <= (out < 0);
  end

endmodule

module twos_complement (
    input [31:0] in,
    output [31:0] out
);

wire [31:0] inverted;
wire [31:0] one = 32'b0;
assign one[0] = 1'b1;

// Invert all bits of the input binary number
assign inverted = ~in;

// Add 1 to the inverted number
adder add1(
    .a(inverted),
    .b(one),
    .sum(out)
);

endmodule

module adder (
    input [31:0] a,
    input [31:0] b,
    output [31:0] sum
);

genvar i;
generate
    for (i = 0; i < 32; i = i + 1) begin : adder_loop
        full_adder adder(
            .a(a[i]),
            .b(b[i]),
            .cin(sum[i-1]),
            .sum(sum[i]),
            .cout(sum[i+1])
        );
    end
endgenerate

endmodule

module full_adder (
    input a,
    input b,
    input cin,
    output sum,
    output cout
);

assign sum = a ^ b ^ cin;
assign cout = (a & b) | (a & cin) | (b & cin);

endmodule

module reset_handler(
    input slowest_sync_clk,
    input ext_reset_in,
    input aux_reset_in,
    input mb_debug_sys_rst,
    input dcm_locked,
    output mb_reset,
    output [0:0]bus_struct_reset,
    output [0:0]peripheral_reset,
    output [0:0]interconnect_aresetn,
    output [0:0]peripheral_aresetn
);

    // Assign default values to all reset signals
    assign mb_reset = 1'b0;
    assign bus_struct_reset = 1'b0;
    assign peripheral_reset = 1'b0;
    assign interconnect_aresetn = 1'b0;
    assign peripheral_aresetn = 1'b0;

    // When ext_reset_in is asserted, assert all reset signals
    always @(posedge slowest_sync_clk) begin
        if (ext_reset_in) begin
            mb_reset <= 1'b1;
            bus_struct_reset <= 1'b1;
            peripheral_reset <= 1'b1;
            interconnect_aresetn <= 1'b1;
            peripheral_aresetn <= 1'b1;
        end
    end

    // When aux_reset_in is asserted, assert all reset signals except mb_reset
    always @(posedge slowest_sync_clk) begin
        if (aux_reset_in) begin
            bus_struct_reset <= 1'b1;
            peripheral_reset <= 1'b1;
            interconnect_aresetn <= 1'b1;
            peripheral_aresetn <= 1'b1;
        end
    end

    // When mb_debug_sys_rst is asserted, assert mb_reset
    always @(posedge slowest_sync_clk) begin
        if (mb_debug_sys_rst) begin
            mb_reset <= 1'b1;
        end
    end

    // When dcm_locked is not asserted, assert all reset signals
    always @(posedge slowest_sync_clk) begin
        if (!dcm_locked) begin
            mb_reset <= 1'b1;
            bus_struct_reset <= 1'b1;
            peripheral_reset <= 1'b1;
            interconnect_aresetn <= 1'b1;
            peripheral_aresetn <= 1'b1;
        end
    end

    // When none of the above conditions are met, de-assert all reset signals
    always @(posedge slowest_sync_clk) begin
        if (!ext_reset_in && !aux_reset_in && !mb_debug_sys_rst && dcm_locked) begin
            mb_reset <= 1'b0;
            bus_struct_reset <= 1'b0;
            peripheral_reset <= 1'b0;
            interconnect_aresetn <= 1'b0;
            peripheral_aresetn <= 1'b0;
        end
    end

endmodule

module crc_module (
  input Clk,
  input Reset,
  input [7:0] Data_FrmCrc,
  input Enable_FrmCrc,
  input Initialize_FrmCrc,
  output reg [15:0] FrmCrc,
  output reg FrmCrcError
);

  wire [7:0] Data;
  wire Enable;
  wire Initialize;
  wire [15:0] Crc;
  wire CrcError;

  assign Data = Data_FrmCrc;
  assign Enable = Enable_FrmCrc;
  assign Initialize = Initialize_FrmCrc;

  fb_crc framecrc (
    .Clk(Clk),
    .Reset(Reset),
    .Data(Data),
    .Enable(Enable),
    .Initialize(Initialize),
    .Crc(Crc),
    .CrcError(CrcError)
  );

  always @(posedge Clk) begin
    if (Reset) begin
      FrmCrc <= 16'h0000;
      FrmCrcError <= 1'b0;
    end else if (CrcError) begin
      FrmCrc <= 16'hFFFF;
      FrmCrcError <= 1'b1;
    end else if (Enable) begin
      FrmCrc <= Crc;
      FrmCrcError <= 1'b0;
    end
  end

endmodule

module fb_crc (
  input Clk,
  input Reset,
  input [7:0] Data,
  input Enable,
  input Initialize,
  output reg [15:0] Crc,
  output reg CrcError
);

  reg [15:0] crc_reg;
  reg [7:0] data_reg;
  reg [3:0] bit_counter;
  reg [15:0] poly;
  reg [15:0] crc_const;
  reg [15:0] xor_const;
  reg [15:0] xor_reg;
  reg [15:0] crc_temp;
  reg [15:0] crc_temp2;
  reg [15:0] crc_temp3;
  reg [15:0] crc_temp4;
  reg [15:0] crc_temp5;
  reg [15:0] crc_temp6;
  reg [15:0] crc_temp7;
  reg [15:0] crc_temp8;
  reg [15:0] crc_temp9;
  reg [15:0] crc_temp10;
  reg [15:0] crc_temp11;
  reg [15:0] crc_temp12;
  reg [15:0] crc_temp13;
  reg [15:0] crc_temp14;
  reg [15:0] crc_temp15;

  assign Crc = crc_reg;
  assign CrcError = 0;

  always @(posedge Clk) begin
    if (Reset) begin
      crc_reg <= 16'h0000;
      data_reg <= 8'h00;
      bit_counter <= 4'h0;
    end else if (Initialize) begin
      crc_reg <= 16'h0000;
    end else if (Enable) begin
      data_reg <= Data;
      poly <= 16'h1021;
      crc_const <= 16'hFFFF;
      xor_const <= 16'h0000;
      xor_reg <= 16'h0000;

      crc_temp <= {crc_reg[14:0], data_reg};
      crc_temp2 <= crc_temp ^ xor_reg;
      crc_temp3 <= {crc_temp2[13:0], crc_temp2[15:14]};
      crc_temp4 <= crc_temp3 ^ xor_reg;
      crc_temp5 <= {crc_temp4[12:0], crc_temp4[15:13]};
      crc_temp6 <= crc_temp5 ^ xor_reg;
      crc_temp7 <= {crc_temp6[11:0], crc_temp6[15:12]};
      crc_temp8 <= crc_temp7 ^ xor_reg;
      crc_temp9 <= {crc_temp8[10:0], crc_temp8[15:11]};
      crc_temp10 <= crc_temp9 ^ xor_reg;
      crc_temp11 <= {crc_temp10[9:0], crc_temp10[15:10]};
      crc_temp12 <= crc_temp11 ^ xor_reg;
      crc_temp13 <= {crc_temp12[8:0], crc_temp12[15:9]};
      crc_temp14 <= crc_temp13 ^ xor_reg;
      crc_temp15 <= {crc_temp14[7:0], crc_temp14[15:8]};
      crc_reg <= crc_temp15 ^ crc_const;

      if (bit_counter == 4'hF) begin
        xor_reg <= crc_reg << 1;
        bit_counter <= 4'h0;
      end else begin
        xor_reg <= 16'h0000;
        bit_counter <= bit_counter + 1;
      end
    end
  end

  always @(posedge Clk) begin
    if (Reset) begin
      CrcError <= 1'b0;
    end else if (Initialize) begin
      CrcError <= 1'b0;
    end else if (Enable) begin
      if (crc_reg != 16'h0000) begin
        CrcError <= 1'b1;
      end else begin
        CrcError <= 1'b0;
      end
    end
  end

endmodule

module ones_counter (
    input [15:0] A,
    output reg [4:0] count
);
    integer i;
    always @(*) begin
        count = 0;
        for (i = 0; i < 16; i = i + 1) begin
            count = count + A[i];
        end
    end
endmodule

module binary_to_bcd (
    input [4:0] binary,
    output reg [3:0] B,
    output reg [3:0] C
);
    integer i;
    reg [7:0] bcd;
    always @(*) begin
        bcd = 0;
        for (i = 0; i < 5; i = i + 1) begin
            bcd = (bcd << 1) + binary[i];
            if (bcd[3:0] > 4) bcd[3:0] = bcd[3:0] + 3;
            if (bcd[7:4] > 4) bcd[7:4] = bcd[7:4] + 3;
        end
        B = bcd[7:4];
        C = bcd[3:0];
    end
endmodule

module top_module (
    input [15:0] A,
    output reg [3:0] B,
    output reg [3:0] C
);
    wire [4:0] count;
    ones_counter counter (
        .A(A),
        .count(count)
    );

    binary_to_bcd converter (
        .binary(count),
        .B(B),
        .C(C)
    );
endmodule

module top_module (
    input clk,
    input reset,
    input [7:0] d1,
    input [7:0] d2,
    input [3:0] adder_input,
    output [3:0] final_output
);

reg [7:0] shift_register_output;
wire [3:0] ripple_carry_adder_output;

shift_register shift_reg (
    .clk(clk),
    .reset(reset),
    .d(d1),
    .q(shift_register_output)
);

ripple_carry_adder ripple_adder (
    .a(shift_register_output[3:0]),
    .b(adder_input),
    .sum(ripple_carry_adder_output),
    .carry_out()
);

functional_module func_mod (
    .shift_register_output(shift_register_output),
    .ripple_carry_adder_output(ripple_carry_adder_output),
    .final_output(final_output)
);

shift_register shift_reg2 (
    .clk(clk),
    .reset(reset),
    .d(d2),
    .q(shift_register_output)
);

endmodule

module shift_register (
    input clk,
    input reset,
    input [7:0] d,
    output reg [7:0] q
);

always @(posedge clk, posedge reset) begin
    if (reset) begin
        q <= 8'b0;
    end else begin
        q <= {q[6:0], d[0]};
    end
end

endmodule

module ripple_carry_adder(
    input [3:0] a,
    input [3:0] b,
    output [3:0] sum,
    output carry_out
);

assign {carry_out, sum} = a + b;

endmodule

module functional_module (
    input [7:0] shift_register_output,
    input [3:0] ripple_carry_adder_output,
    output [3:0] final_output
);

assign final_output = shift_register_output[7:4] + ripple_carry_adder_output;

endmodule

module byte_splitter (
    input [15:0] in,
    output reg [7:0] out_hi,
    output reg [7:0] out_lo
);

    assign out_hi = in >> 8;
    assign out_lo = in & 8'hFF;

endmodule

module accumulator (
    input clk,
    input reset,
    input [7:0] in,
    input valid_in,
    output reg valid_out,
    output reg [9:0] out
);

    reg [9:0] sum;

    always @(posedge clk) begin
        if (reset) begin
            sum <= 10'h000;
        end else if (valid_in) begin
            sum <= sum + {2'b00, in};
        end
    end

    always @(posedge clk) begin
        if (reset) begin
            valid_out <= 1'b0;
            out <= 10'h000;
        end else if (valid_in) begin
            if (sum[9]) begin
                valid_out <= 1'b1;
                out <= sum;
                sum <= 10'h000;
            end else begin
                valid_out <= 1'b0;
            end
        end
    end

endmodule

module final_module (
    input [7:0] in_hi,
    input [7:0] in_lo,
    input [9:0] in_acc,
    input select,
    input valid_in,
    output reg valid_out,
    output reg [9:0] out
);

    always @(select or in_hi or in_lo or in_acc or valid_in) begin
        if (select) begin
            out <= in_acc;
            valid_out <= valid_in;
        end else begin
            out <= {in_hi, in_lo};
            valid_out <= valid_in;
        end
    end

endmodule

module top_module (
    input clk,
    input reset,
    input [15:0] in,
    input select,
    input valid_a,
    input ready_b,
    output ready_a,
    output reg valid_b,
    output reg [9:0] data_out,
    output reg [7:0] out_hi,
    output reg [7:0] out_lo
);

    wire [7:0] byte_splitter_out_hi;
    wire [7:0] byte_splitter_out_lo;
    wire [9:0] accumulator_out;

    byte_splitter byte_splitter_inst (
        .in(in),
        .out_hi(byte_splitter_out_hi),
        .out_lo(byte_splitter_out_lo)
    );

    accumulator accumulator_inst (
        .clk(clk),
        .reset(reset),
        .in(byte_splitter_out_lo),
        .valid_in(valid_a),
        .valid_out(valid_b),
        .out(data_out)
    );

    final_module final_module_inst (
        .in_hi(byte_splitter_out_hi),
        .in_lo(byte_splitter_out_lo),
        .in_acc(accumulator_out),
        .select(select),
        .valid_in(valid_b),
        .valid_out(valid_a),
        .out(in)
    );

    assign ready_a = ~valid_b;
    assign valid_b = ready_b;

endmodule

module Splitter (
    input [31:0] instruction,
    output reg [5:0] fld_opcode,
    output reg [1:0] fld_affect,
    output reg [4:0] fld_field0,
    output reg [4:0] fld_field1,
    output reg [4:0] fld_field2,
    output reg [1:0] fld_shift_type,
    output reg fld_shift_IR,
    output reg [4:0] fld_shamt_S,
    output reg [4:0] fld_shamt_I,
    output reg [4:0] fld_shamt_R,
    output reg [15:0] fld_immediate
);

    always @(*) begin
        fld_opcode = instruction[31:26];
        fld_affect = instruction[25:24];
        fld_field0 = instruction[23:19];
        fld_field1 = instruction[18:14];
        fld_field2 = instruction[13:9];
        fld_shift_type = instruction[8:7];
        fld_shift_IR = instruction[6];
        fld_shamt_S = instruction[4:0];
        fld_shamt_I = instruction[4:0];
        fld_shamt_R = instruction[4:0];
        fld_immediate = instruction[15:0];
    end

endmodule

module top_module (
    input [1:0] in_0_a,
    input [1:0] in_0_b,
    input [1:0] in_1_a,
    input [1:0] in_1_b,
    output reg [7:0] out
);

    wire [1:0] mux_sel;
    wire [1:0] comp_in;

    mux_4to1 mux (
        .in_0(in_0_a),
        .in_1(in_0_b),
        .in_2(in_1_a),
        .in_3(in_1_b),
        .sel(mux_sel),
        .out(comp_in)
    );

    comparator_2bit comp (
        .in_a(comp_in[3:2]),
        .in_b(comp_in[1:0]),
        .out(out[7:0])
    );

    always @(*) begin
        if (in_0_a > in_0_b) begin
            mux_sel[0] = 1'b0;
        end else begin
            mux_sel[0] = 1'b1;
        end

        if (in_1_a > in_1_b) begin
            mux_sel[1] = 1'b0;
        end else begin
            mux_sel[1] = 1'b1;
        end
    end

endmodule

module mux_4to1 (
    input [1:0] in_0,
    input [1:0] in_1,
    input [1:0] in_2,
    input [1:0] in_3,
    input [1:0] sel,
    output reg [1:0] out
);

    always @(*) begin
        case (sel)
            2'b00: out = in_0;
            2'b01: out = in_1;
            2'b10: out = in_2;
            2'b11: out = in_3;
        endcase
    end

endmodule

module comparator_2bit (
    input [1:0] in_a,
    input [1:0] in_b,
    output reg [7:0] out
);

    always @(*) begin
        if (in_a > in_b) begin
            out[3:2] = 2'b01;
        end else if (in_a < in_b) begin
            out[3:2] = 2'b10;
        end else begin
            out[3:2] = 2'b00;
        end

        if (in_a[1] > in_b[1]) begin
            out[1:0] = 2'b01;
        end else if (in_a[1] < in_b[1]) begin
            out[1:0] = 2'b10;
        end else begin
            out[1:0] = 2'b00;
        end
    end

endmodule

module calculator(
    input wire [7:0] num1,
    input wire [7:0] num2,
    input wire [1:0] opcode,
    output reg [7:0] result
);

always @(*) begin
    case(opcode)
        2'b00: result = num1 + num2;
        2'b01: result = num1 - num2;
        2'b10: result = num1 * num2;
        2'b11: result = num1 / num2;
    endcase
end

endmodule

module xor_gate(input a, b, output out);
  reg out;

  always @(*) begin
    case ({a, b})
      2'b00: out = 1'b0;
      2'b01: out = 1'b1;
      2'b10: out = 1'b1;
      2'b11: out = 1'b0;
    endcase
  end

endmodule

module vga640x480(
    CLK,
    CLR,
    HSYNC,
    VSYNC,
    HC,
    VC,
    VIDON
);

// |--------------------|
// | Port Declarations  |
// | -------------------|
input CLK;  // Clock
input CLR;  // Clear

output HSYNC; // Horizontal Sync
output VSYNC; // Vertical Sync

output [9:0] HC; // Horizontal Counter
output [9:0] VC; // Vertical Counter

output VIDON;    // When active, data may be displayed


// |------------------------|
// | Parameters (Constants) |
// | -----------------------|
localparam hpixels = 640, // Pixels in horizontal line = 640
           vlines = 480, // Horizontal lines = 480
           hbp = 48,    // Horizontal Back Porch = 48
           hfp = 16,    // Horizontal Front Porch = 16
           vbp = 33,    // Vertical Back Porch = 33
           vfp = 10;    // Vertical Front Porch = 10

reg [9:0] HCS, VCS; // Horizontal and Vertical counters
reg VSenable;       // Enable for Vertical counter


assign HC    = HCS;
assign VC    = VCS;
assign HSYNC = (HCS < hbp || HCS >= (hbp + hpixels)) ? 1'b0 : 1'b1; // HS Pulse is low for HCS from 0-47 and 656-799
assign VSYNC = (VCS < vbp || VCS >= (vbp + vlines)) ? 1'b0 : 1'b1; // VS Pulse is low for VCS from 0-32 and 513-480
assign VIDON = (((HCS < (hbp + hpixels)) && (HCS >= hbp)) && ((VCS < (vbp + vlines)) && (VCS >= vbp))) ? 1'b1 : 1'b0;

// Counter for the horizontal sync signal
always @ (posedge CLK)
begin
    if(CLR == 1'b1)
        HCS <= 10'b0000000000;

    else if(CLK == 1'b1) 
    begin
        if(HCS < (hpixels + hbp + hfp - 1'b1) )
        begin
            HCS <= HCS + 1'b1;
            VSenable <= 1'b0;  // Leave VSenable off
        end
        else
        begin    
            // Counter reached end of the pixel count
            HCS <= 10'b0000000000; // Reset counter, then,
            VSenable <= 1'b1;      // Enable vertical counter
        end 
    end
end

// Counter for the vertical sync signal
always @ (posedge CLK)
begin
    if(CLR == 1'b1)
        VCS <= 10'b0000000000;

    else if(CLK == 1'b1 && VSenable == 1'b1)
    begin
        // Increment when enabled
        if( VCS < (vlines + vbp + vfp - 1'b1) )
        begin
            VCS <= VCS + 1'b1; // Increment vertical counter
        end
        else
        begin
            VCS <= 10'b0000000000; 
        end
    end
end

endmodule

module top_module( 
    input [99:0] a, b, // 100-bit binary numbers
    input cin, // Carry-in input
    input [7:0] sel_mux, // Selection input for the 256-to-1 multiplexer
    input sel_func, // Selection input for the functional module
    output out // Output of the functional module
);

    // 100-bit binary adder with carry-lookahead
    wire [100:0] c; // Intermediate carry signals
    wire [99:0] sum; // Output sum
    wire cout; // Output carry-out
    cla_adder_100bit adder(.a(a), .b(b), .cin(cin), .c(c), .sum(sum), .cout(cout));

    // 256-to-1 multiplexer
    wire [255:0] mux_inputs; // 256 inputs to the multiplexer
    assign mux_inputs[0] = cout; // Use the carry-out signal as the first input
    assign mux_inputs[1:255] = 0; // Set all other inputs to 0
    wire mux_output; // Output of the multiplexer
    assign mux_output = mux_inputs[sel_mux]; // Select one of the inputs based on the selection input

    // Functional module
    wire func_output; // Output of the functional module
    and_gate and_gate_inst(.a(sum), .b(mux_output), .out(func_output)); // Logical AND of the sum and the multiplexer output

    // Output
    assign out = sel_func ? func_output : mux_output; // Select the output of the functional module or the multiplexer based on the selection input

endmodule

// 100-bit carry-lookahead adder
module cla_adder_100bit(
    input [99:0] a, b, // 100-bit binary numbers
    input cin, // Carry-in input
    output [100:0] c, // Intermediate carry signals
    output [99:0] sum, // Output sum
    output cout // Output carry-out
);

    wire [99:0] p, g; // P and G signals for each bit
    assign p = a ^ b; // XOR of the inputs
    assign g = a & b; // AND of the inputs
    assign c[0] = cin; // Set the first carry signal to the carry-in input

    // Generate carry signals for each level of the hierarchy
    genvar i;
    generate
        for (i = 0; i < 99; i = i + 2) begin : gen_level
            assign c[i+2] = g[i] | (p[i] & c[i]);
            assign c[i+3] = p[i+1] | (g[i+1] & c[i+1]);
        end
    endgenerate

    // Calculate the sum and carry-out signals
    assign sum = a + b + cin;
    assign cout = c[100];

endmodule

// 2-input AND gate
module and_gate(
    input a, b, // Input signals
    output out // Output signal
);

    assign out = a & b;

endmodule

module fifo(
  rst,
  wr_clk,
  rd_clk,
  din,
  wr_en,
  rd_en,
  dout,
  full,
  empty,
  prog_full
);

input rst;
input wr_clk;
input rd_clk;
input [71:0] din;
input wr_en;
input rd_en;
output [71:0] dout;
output full;
output empty;
output prog_full;

reg [71:0] mem [511:0];  // Memory array
reg [8:0] wr_ptr;         // Write pointer
reg [8:0] rd_ptr;         // Read pointer
reg [8:0] count;          // Number of elements in the FIFO
reg [8:0] prog_full_reg;  // Programmable full flag register

assign full = count == 512;  // FIFO is full when count equals 512
assign empty = count == 0;   // FIFO is empty when count equals 0
assign prog_full = count >= prog_full_reg;  // Programmable full flag

always @(posedge wr_clk or negedge rst) begin
  if (!rst) begin
    wr_ptr <= 0;
  end
  else if (wr_en && !full) begin
    mem[wr_ptr] <= din;
    wr_ptr <= wr_ptr + 1;
    count <= count + 1;
  end
end

always @(posedge rd_clk or negedge rst) begin
  if (!rst) begin
    rd_ptr <= 0;
  end
  else if (rd_en && !empty) begin
    dout <= mem[rd_ptr];
    rd_ptr <= rd_ptr + 1;
    count <= count - 1;
  end
end

always @(posedge wr_clk or negedge rst) begin
  if (!rst) begin
    prog_full_reg <= 0;
  end
  else if (wr_en && !full && (count + 1) >= prog_full_reg) begin
    prog_full_reg <= prog_full_reg + 1;
  end
end

endmodule

module fifo_generator (
    input clk,
    input rst,
    input wr_en,
    input rd_en,
    input [31:0]din,
    output [31:0]dout,
    output empty,
    output full
);

    parameter DEPTH = 256; // FIFO depth
    parameter WIDTH = 32; // Data width

    reg [WIDTH-1:0] fifo[DEPTH-1:0]; // FIFO memory
    reg [WIDTH-1:0] dout; // Output data
    wire empty; // Empty flag
    wire full; // Full flag
    reg [7:0] head = 0; // Head pointer
    reg [7:0] tail = 0; // Tail pointer
    reg [7:0] count = 0; // Number of elements in the FIFO

    always @(posedge clk) begin
        if (rst) begin // Reset the FIFO
            head <= 0;
            tail <= 0;
            count <= 0;
        end else begin
            if (wr_en && !full) begin // Write data to the FIFO
                fifo[head] <= din;
                head <= head + 1;
                count <= count + 1;
                if (head == DEPTH) head <= 0; // Wrap around
            end
            if (rd_en && !empty) begin // Read data from the FIFO
                dout <= fifo[tail];
                tail <= tail + 1;
                count <= count - 1;
                if (tail == DEPTH) tail <= 0; // Wrap around
            end
        end
    end

    assign empty = (count == 0);
    assign full = (count == DEPTH);

endmodule

module shift_register (
  input clk,
  input reset,
  input clear,
  input [7:0] data_in,
  output [7:0] data_out
);

  reg [7:0] shift_reg;

  always @(posedge clk) begin
    if (reset) begin
      shift_reg <= 8'b0;
    end else if (clear) begin
      shift_reg <= 8'b11111111;
    end else begin
      shift_reg <= {shift_reg[6:0], data_in};
    end
  end

  assign data_out = shift_reg;

endmodule

module cpu(
    input clk,
    input reset,
    input rd,
    input wr,
    input [12:0] addr,
    inout [7:0] data,
    output halt
);

    reg [7:0] reg1;
    reg [7:0] reg2;
    reg [12:0] pc;
    reg [2:0] opcode;
    reg [12:0] operand;
    reg [7:0] alu_out;
    reg [7:0] mem_out;
    reg [7:0] mem_in;
    reg [7:0] zero;
    wire [7:0] addr_out;

    assign addr_out = (rd) ? data : addr;

    always @(posedge clk) begin
        if(reset) begin
            reg1 <= 8'h00;
            reg2 <= 8'h00;
            pc <= 13'h000;
        end else begin
            case(opcode)
                3'b000: reg1 <= alu_out;
                3'b001: reg1 <= alu_out;
                3'b010: reg1 <= alu_out;
                3'b011: reg1 <= alu_out;
                3'b100: reg1 <= alu_out;
                3'b101: reg1 <= mem_out;
                3'b110: reg1 <= reg2;
                3'b111: reg1 <= reg1;
            endcase

            case(opcode)
                3'b000: alu_out <= reg1 + reg2;
                3'b001: alu_out <= reg1 - reg2;
                3'b010: alu_out <= reg1 & reg2;
                3'b011: alu_out <= reg1 | reg2;
                3'b100: alu_out <= reg1 ^ reg2;
                3'b101: mem_out <= mem_in;
                3'b110: alu_out <= reg1;
                3'b111: alu_out <= reg1;
            endcase

            if(wr) begin
                mem_in <= reg1;
            end

            if(rd) begin
                data <= mem_out;
            end

            if(opcode == 3'b111) begin
                pc <= operand;
            end else begin
                pc <= pc + 1;
            end
        end
    end

    always @(posedge clk) begin
        if(reset) begin
            reg2 <= 8'h00;
            opcode <= 3'b000;
            operand <= 13'h000;
            halt <= 1'b0;
        end else begin
            case(opcode)
                3'b000: reg2 <= data;
                3'b001: reg2 <= data;
                3'b010: reg2 <= data;
                3'b011: reg2 <= data;
                3'b100: reg2 <= data;
                3'b101: mem_in <= data;
                3'b110: operand <= data;
                3'b111: operand <= data;
            endcase

            if(rd) begin
                mem_out <= data;
            end

            case(data)
                3'b000: opcode <= 3'b000;
                3'b001: opcode <= 3'b001;
                3'b010: opcode <= 3'b010;
                3'b011: opcode <= 3'b011;
                3'b100: opcode <= 3'b100;
                3'b101: opcode <= 3'b101;
                3'b110: opcode <= 3'b110;
                3'b111: opcode <= 3'b111;
            endcase

            if(opcode == 3'b111) begin
                pc <= operand;
            end else begin
                pc <= pc + 1;
            end

            if(opcode == 3'b000 || opcode == 3'b001 || opcode == 3'b010 || opcode == 3'b011 || opcode == 3'b100) begin
                reg2 <= addr_out;
            end

            if(opcode == 3'b111) begin
                halt <= 1'b1;
            end else begin
                halt <= 1'b0;
            end
        end
    end

endmodule

