module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    input CIN,
    output reg [3:0] SUM,
    output reg COUT
);

reg [3:0] s1;
reg [3:0] s2;
reg [3:0] s3;
reg [3:0] s4;

full_adder fa1(.a(A[0]), .b(B[0]), .cin(CIN), .sum(s1[0]), .cout(s2[0]));
full_adder fa2(.a(A[1]), .b(B[1]), .cin(s1[0]), .sum(s2[1]), .cout(s3[1]));
full_adder fa3(.a(A[2]), .b(B[2]), .cin(s2[1]), .sum(s3[2]), .cout(s4[2]));
full_adder fa4(.a(A[3]), .b(B[3]), .cin(s3[2]), .sum(SUM[3]), .cout(COUT));

assign s1[1] = fa1.cout;
assign s2[2] = fa2.cout;
assign s3[3] = fa3.cout;

assign SUM[0] = s1[0];
assign SUM[1] = s2[1];
assign SUM[2] = s3[2];
assign SUM[3] = s4[3];

endmodule

