module flip_flop_module (
    input clk,
    input [7:0] reset,      // Asynchronous reset
    input [15:0] data_in,
    output reg [7:0] q
);

    reg [7:0] q_next;

    always @(posedge clk or negedge reset) begin
        if (~reset) begin
            q <= 8'b0;
        end else begin
            q <= q_next;
        end
    end

    always @(*) begin
        q_next[7] = q[6] & q[5] & q[4] & q[3] & q[2] & q[1] & q[0] & data_in[0];
        q_next[6] = q[5] & q[4] & q[3] & q[2] & q[1] & q[0] & data_in[1];
        q_next[5] = q[4] & q[3] & q[2] & q[1] & q[0] & data_in[2];
        q_next[4] = q[3] & q[2] & q[1] & q[0] & data_in[3];
        q_next[3] = q[2] & q[1] & q[0] & data_in[4];
        q_next[2] = q[1] & q[0] & data_in[5];
        q_next[1] = q[0] & data_in[6];
        q_next[0] = data_in[7];
    end

endmodule

