module booth_multiplier (
    input [3:0] A,
    input [3:0] B,
    output [7:0] result
);

reg [7:0] product;
reg [4:0] counter;

always @(*) begin
    product = {4'b0, A} << 1;
    counter = 4'd4;
    while (counter > 0) begin
        if (B[0] == 1 && B[1] == 0) begin
            product = product - {4'b0, A};
        end else if (B[0] == 0 && B[1] == 1) begin
            product = product + {4'b0, A};
        end
        B = {B[2], B[1], B[0], 1'b0};
        counter = counter - 1;
    end
end

assign result = product;

endmodule

module signed_adder (
    input signed [3:0] A,
    input signed [3:0] B,
    output signed [3:0] sum
);

reg signed [3:0] temp_sum;

always @(*) begin
    temp_sum = A + B;
    if (temp_sum > 7 || temp_sum < -8) begin
        sum = 4'b0000;
    end else begin
        sum = temp_sum;
    end
end

endmodule

module final_module (
    input [3:0] A,
    input [3:0] B,
    output [7:0] multiplier_result,
    output signed [3:0] adder_result,
    output signed [3:0] final_result,
    output overflow
);

wire [7:0] product;
wire signed [3:0] sum;

booth_multiplier multiplier(.A(A), .B(B), .result(product));
signed_adder adder(.A(A), .B(B), .sum(sum));

assign multiplier_result = product;
assign adder_result = sum;

always @(*) begin
    if (product > 127 || product < -128) begin
        final_result = 4'b0000;
        overflow = 1'b1;
    end else begin
        final_result = sum + product[3:0];
        overflow = 1'b0;
    end
end

endmodule

module final_output (
  input clk,
  input reset,
  input [7:0] in,
  output [7:0] anyedge,
  output [7:0] count,
  output [7:0] result
);

  // Shift register to detect bit transitions
  reg [7:0] sr;
  always @(posedge clk) begin
    if (reset) begin
      sr <= 8'b0;
      anyedge <= 8'b0;
    end else begin
      sr <= {in[6:0], sr[7]};
      anyedge <= (in ^ sr);
    end
  end

  // Population count circuit
  function integer popcount;
    input [7:0] data;
    begin
      if (data == 8'b0) begin
        popcount = 0;
      end else begin
        popcount = popcount(data[3:0]) + popcount(data[7:4]);
        popcount = popcount + popcount({popcount[3:0], popcount[3:0]});
        popcount = popcount + popcount({popcount[6:4], popcount[6:4]});
        popcount = popcount + popcount({popcount[7], popcount[7]});
      end
    end
  endfunction

  // Final output generation
  assign count = popcount(in);
  assign result = count + anyedge;

endmodule

module CDR (
  input data_in,
  input clk_ref,
  output clk_out,
  output data_out
);

  // Internal signals
  reg data_in_delayed;
  reg [1:0] data_in_edge;
  reg clk_out_delayed;
  reg data_out_delayed;

  // Delayed data input
  always @(posedge clk_ref) begin
    data_in_delayed <= data_in;
  end

  // Detect data input edges
  always @(posedge clk_ref) begin
    data_in_edge <= {data_in_delayed, data_in} - {data_in, data_in_delayed};
  end

  // Generate recovered clock
  always @(posedge clk_ref) begin
    if (data_in_edge == 2'b01 || data_in_edge == 2'b10) begin
      clk_out_delayed <= ~clk_out_delayed;
    end
  end

  // Generate recovered data
  always @(posedge clk_out_delayed) begin
    data_out_delayed <= data_in_delayed;
  end

  // Output signals
  assign clk_out = clk_out_delayed;
  assign data_out = data_out_delayed;

endmodule

module ad_iqcor #(
  // select i/q if disabled
  parameter   Q_OR_I_N = 0,
  parameter   SCALE_ONLY = 0,
  parameter   DISABLE = 0
) (
  // data interface
  input           clk,
  input           valid,
  input   [15:0]  data_in,
  input   [15:0]  data_iq,
  output          valid_out,
  output  [15:0]  data_out,
  // control interface
  input           iqcor_enable,
  input   [15:0]  iqcor_coeff_1,
  input   [15:0]  iqcor_coeff_2
);
  // internal registers
  reg             p1_valid = 'd0;
  reg     [33:0]  p1_data_p = 'd0;
  reg             valid_int = 'd0;
  reg     [15:0]  data_int = 'd0;
  reg     [15:0]  iqcor_coeff_1_r = 'd0;
  reg     [15:0]  iqcor_coeff_2_r = 'd0;
  // internal signals
  wire    [15:0]  data_i_s;
  wire    [15:0]  data_q_s;
  wire    [33:0]  p1_data_p_i_s;
  wire            p1_valid_s;
  wire    [15:0]  p1_data_i_s;
  wire    [33:0]  p1_data_p_q_s;
  wire    [15:0]  p1_data_q_s;
  wire    [15:0]  p1_data_i_int;
  wire    [15:0]  p1_data_q_int;
  // data-path disable
  generate
  if (DISABLE == 1) begin
    assign valid_out = valid;
    assign data_out = data_in;
  end else begin
    assign valid_out = valid_int;
    assign data_out = data_int;
  end
  endgenerate
  // swap i & q
  assign data_i_s = (Q_OR_I_N == 1 && SCALE_ONLY == 1'b0) ? data_iq : data_in;
  assign data_q_s = (Q_OR_I_N == 1) ? data_in : data_iq;
  // coefficients are flopped to remove warnings from vivado
  always @(posedge clk) begin
    iqcor_coeff_1_r <= iqcor_coeff_1;
    iqcor_coeff_2_r <= iqcor_coeff_2;
  end
  // scaling functions - i
  ad_mul #(.DELAY_DATA_WIDTH(17)) i_mul_i (
    .clk (clk),
    .data_a ({data_i_s[15], data_i_s}),
    .data_b ({iqcor_coeff_1_r[15], iqcor_coeff_1_r}),
    .data_p (p1_data_p_i_s),
    .ddata_in ({valid, data_i_s}),
    .ddata_out ({p1_valid_s, p1_data_i_s})
  );
  generate
  if (SCALE_ONLY == 0) begin
    // scaling functions - q
    ad_mul #(.DELAY_DATA_WIDTH(16)) i_mul_q (
      .clk (clk),
      .data_a ({data_q_s[15], data_q_s}),
      .data_b ({iqcor_coeff_2_r[15], iqcor_coeff_2_r}),
      .data_p (p1_data_p_q_s),
      .ddata_in (data_q_s),
      .ddata_out (p1_data_q_s)
    );
    // sum
  end else begin
    assign p1_data_p_q_s = 34'h0;
    assign p1_data_q_s = 16'h0;
  end
  endgenerate
  generate
  if (Q_OR_I_N == 1 && SCALE_ONLY == 0) begin
    reg [15:0]  p1_data_q = 'd0;
    always @(posedge clk) begin
      p1_data_q <= p1_data_q_s;
    end
    assign p1_data_i_int = 16'h0;
    assign p1_data_q_int = p1_data_q;
    // sum
  end else begin
    reg [15:0]  p1_data_i = 'd0;
    always @(posedge clk) begin
      p1_data_i <= p1_data_i_s;
    end
    assign p1_data_i_int = p1_data_i;
    assign p1_data_q_int = 16'h0;
  end
  endgenerate
  always @(posedge clk) begin
    p1_valid <= p1_valid_s;
    p1_data_p <= p1_data_p_i_s + p1_data_p_q_s;
  end
  // output registers
  always @(posedge clk) begin
    valid_int <= p1_valid;
    if (iqcor_enable == 1'b1) begin
      data_int <= p1_data_p[29:14];
    end else if (Q_OR_I_N == 1 && SCALE_ONLY == 0) begin
      data_int <= p1_data_q_int;
    end else begin
      data_int <= p1_data_i_int;
    end
  end
endmodule

module traffic_light_controller (
  input clk,
  input reset,
  output reg red,
  output reg green,
  output reg yellow
);

  parameter RED = 2'b00;
  parameter GREEN = 2'b01;
  parameter YELLOW = 2'b10;

  reg [1:0] state = RED;
  reg [3:0] count = 4'b0000;

  always @(posedge clk) begin
    if (reset) begin
      state <= RED;
      count <= 4'b0000;
    end else begin
      case (state)
        RED: begin
          if (count == 4'b0101) begin
            state <= GREEN;
            count <= 4'b0000;
          end else begin
            count <= count + 1;
          end
        end

        GREEN: begin
          if (count == 4'b1010) begin
            state <= YELLOW;
            count <= 4'b0000;
          end else begin
            count <= count + 1;
          end
        end

        YELLOW: begin
          if (count == 4'b0010) begin
            state <= RED;
            count <= 4'b0000;
          end else begin
            count <= count + 1;
          end
        end
      endcase
    end
  end

  always @(state) begin
    case (state)
      RED: begin
        red <= 1;
        green <= 0;
        yellow <= 0;
      end

      GREEN: begin
        red <= 0;
        green <= 1;
        yellow <= 0;
      end

      YELLOW: begin
        red <= 0;
        green <= 0;
        yellow <= 1;
      end
    endcase
  end

endmodule

