module top_module (
  input wire [7:0] first_num, // First 8-bit input
  input wire [7:0] second_num, // Second 8-bit input
  output reg [7:0] greater_num, // Output the greater number
  output reg [3:0] binary_equiv // Output the 4-bit binary equivalent of the selected number
);

  reg greater;
  wire [7:0] sum;
  wire overflow;
  wire [2:0] and_or_in;
  reg [3:0] binary_equiv_temp;

  comparator comp(.a(first_num), .b(second_num), .greater(greater));
  carry_select_adder adder(.a(first_num), .b(second_num), .s(sum), .overflow(overflow));
  and_or_module and_or(.in_vec({greater, overflow, greater}), .out_vec(and_or_in));

  always @(*) begin
    if (greater) begin
      greater_num = first_num;
      binary_equiv_temp = first_num[7:4];
    end else begin
      greater_num = second_num;
      binary_equiv_temp = second_num[7:4];
    end

    case(and_or_in)
      3'b000: binary_equiv = 4'b0000;
      3'b001: binary_equiv = 4'b0001;
      3'b010: binary_equiv = 4'b0010;
      3'b011: binary_equiv = 4'b0011;
      3'b100: binary_equiv = 4'b0100;
      3'b101: binary_equiv = 4'b0101;
      3'b110: binary_equiv = 4'b0110;
      3'b111: binary_equiv = 4'b0111;
    endcase

    binary_equiv = {binary_equiv, binary_equiv_temp};
  end

endmodule

module comparator (
  input wire [7:0] a, // First 8-bit input to be compared
  input wire [7:0] b, // Second 8-bit input to be compared
  output reg greater // Output indicating which input is greater
);

  always @(a, b) begin
    if (a > b) begin
      greater = 1;
    end else begin
      greater = 0;
    end
  end

endmodule

module carry_select_adder (
  input wire [7:0] a, // First 8-bit input to be added
  input wire [7:0] b, // Second 8-bit input to be added
  output reg [7:0] s, // Sum output of the adder
  output reg overflow // Overflow output of the adder
);

  wire [7:0] p;
  wire [7:0] g;

  assign p = a + b;
  assign g = a & b;

  always @(a, b) begin
    if (p[7] == g[7]) begin
      s = p;
      overflow = 0;
    end else begin
      s = ~p;
      overflow = 1;
    end
  end

endmodule

module and_or_module (
  input wire [2:0] in_vec, // 3-bit input to AND and OR gates
  output reg [2:0] out_vec // 3-bit output of the module
);

  wire [2:0] and_out;
  wire [2:0] or_out;

  assign and_out = in_vec & 3'b111;
  assign or_out = in_vec | 3'b000;

  always @(and_out, or_out) begin
    out_vec = and_out | or_out;
  end

endmodule

