module ripple_carry_adder (
    input [3:0] in0,
    input [3:0] in1,
    input carry_in,
    output reg [3:0] sum,
    output reg carry_out
);

    // Define internal signals
    reg [3:0] temp_sum;
    reg temp_carry;

    // Implement the adder
    always @(*) begin
        temp_sum = in0 + in1 + carry_in;
        temp_carry = (temp_sum > 4'b1111) ? 1'b1 : 1'b0;
        sum = temp_sum;
        carry_out = temp_carry;
    end

endmodule

module FullAdder(input a,b,c, output sum, carry);
  wire s1, c1, c2;
  Xor g1(a,  b,  s1);
  Xor g2(s1, c,  sum);
  And g3(a,  b,  c1);
  And g4(s1, c,  c2);
  Xor g5(c2, c1, carry);
endmodule

module RippleCarryAdder(input [3:0] A, input [3:0] B, output [3:0] S, output Cout);

  wire c1, c2, c3;

  FullAdder fa1(A[0], B[0], 0, S[0], c1);
  FullAdder fa2(A[1], B[1], c1, S[1], c2);
  FullAdder fa3(A[2], B[2], c2, S[2], c3);
  FullAdder fa4(A[3], B[3], c3, S[3], Cout);

endmodule

module top_module(
