    assign priority_sel = (sel_b1 & sel_b2) ? 3'b111 : (sel_b1) ? {2'b00, sel} : {2'b01, sel};
    mux_6to1 mux_6to1_inst(
        .sel(priority_sel),
        .data(data),
        .out(mux_6to1_out)
    );

    // OR gate
    wire [3:0] or_gate_in;
    assign or_gate_in = {mux_2to1_out, mux_6to1_out};
