module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [2:0] sel,  // 3-bit selection input for the multiplexer
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output reg [63:0] out
);

// Priority encoder for the 6-to-1 multiplexer
wire [5:0] priority;
assign priority = ~{data0, data1, data2, data3, data4, data5};

// Combinational logic for the 6-to-1 multiplexer
wire [3:0] mux_out;
assign mux_out = (sel > 5) ? 4'b0000 :
                (sel == priority[5]) ? data5 :
                (sel == priority[4]) ? data4 :
                (sel == priority[3]) ? data3 :
                (sel == priority[2]) ? data2 :
                (sel == priority[1]) ? data1 :
                (sel == priority[0]) ? data0 :
                4'b0000;

// Johnson counter
reg [7:0] counter;
always @(posedge clk, posedge reset) begin
    if (reset) begin
        counter <= 8'b00000000;
    end else begin
        case (counter)
            8'b00000000: counter <= 8'b10000000;
            8'b10000000: counter <= 8'b11000000;
            8'b11000000: counter <= 8'b11100000;
            8'b11100000: counter <= 8'b11110000;
            8'b11110000: counter <= 8'b11111000;
            8'b11111000: counter <= 8'b11111100;
            8'b11111100: counter <= 8'b11111110;
            8'b11111110: counter <= 8'b11111111;
            8'b11111111: counter <= 8'b01111111;
            8'b01111111: counter <= 8'b00111111;
            8'b00111111: counter <= 8'b00011111;
            8'b00011111: counter <= 8'b00001111;
            8'b00001111: counter <= 8'b00000111;
            8'b00000111: counter <= 8'b00000011;
            8'b00000011: counter <= 8'b00000001;
            8'b00000001: counter <= 8'b00000000;
        endcase
    end
end

// Bitwise AND module
wire [63:0] and_out;
assign and_out = counter & mux_out;

// Output
always @(posedge clk) begin
    out <= and_out;
end

endmodule

module shift_reg (
