reg [WIDTH-1:0] next_data;

always @(posedge clk) begin
    if (rst) begin
        reg_data <= {WIDTH{1'b0}};
    end else begin
        if (parallel_in) begin
            reg_data <= next_data;
        end else begin
            reg_data <= {reg_data[WIDTH-2:0], serial_in};
        end
    end
end

assign serial_out = reg_data[WIDTH-1:0];

endmodule

