module lab07_0416037(
	input rst,
	input clk,
	input BTN_WEST,
	input BTN_NORTH,
	input BTN_EAST,
	input [3:0] SW,
	output reg [7:0] LED
);

// Parameter declaration
parameter IDLE = 2'b00;
parameter OPT = 2'b01;
parameter NUM = 2'b10;

parameter RESET = 2'b00;
parameter ADD = 2'b01;
parameter SQRT = 2'b10;
parameter MULT = 2'b11;

// Wire and register declaration
wire [4:0] sqrtAns;
reg [1:0] cState, nState;
reg [20:0] cnt;
reg [10:0] haha;
reg [7:0] ans;
reg [1:0] opt;
reg can;

// Combinational circuit
sqrt sqrt_module(
	.x_in(ans),
	.x_out(sqrtAns),
	.clk(clk)
);

// Finite-State Machine
always @(posedge clk, posedge rst) begin
	if (rst) begin
		cState <= IDLE;
		ans <= 0;
		cnt <= 0;
		opt <= RESET;
		can <= 0;
	end
	else begin
		cState <= nState;
	end
end

always @(*) begin
	case(cState)
		IDLE: begin
			if (BTN_WEST || BTN_NORTH || BTN_EAST) begin
				nState = OPT;
			end
			else begin
				nState = IDLE;
			end
		end
		NUM: begin
			if ((haha > 1000) && (BTN_WEST || BTN_NORTH || BTN_EAST)) begin
				nState = OPT;
			end
			else begin
				nState = NUM;
			end
		end
		OPT: begin
			if (cnt >= 2000000) begin
				nState = NUM;
			end
			else begin
				nState = OPT;
			end
		end
		default: begin
			nState = IDLE;
		end
	endcase
end

// haha
always @(posedge clk, posedge rst) begin
	if (rst) begin
		haha <= 0;
	end
	else begin
		case(cState)
			IDLE: begin
				haha <= 0;
			end
			NUM: begin
				if ((haha > 1000) || !(BTN_WEST || BTN_NORTH || BTN_EAST)) begin
					haha <= haha;
				end
				else begin
					haha <= 0;
				end
			end
			OPT: begin
				haha <= 0;
			end
		endcase
	end
end

// can
always @(posedge clk, posedge rst) begin
	if (rst) begin
		can <= 0;
	end
	else begin
		if (cState == OPT && !can) begin
			can <= 1;
		end
		else if (cState == OPT) begin
			can <= can;
		end
		else begin
			can <= 0;
		end
	end
end

// cnt
always @(posedge clk, posedge rst) begin
	if (rst) begin
		cnt <= 0;
	end
	else begin
		case(cState)
			IDLE: begin
				cnt <= 0;
			end
			NUM: begin
				cnt <= 0;
			end
			OPT: begin
				if (BTN_WEST || BTN_NORTH || BTN_EAST) begin
					cnt <= cnt + 1;
				end
				else begin
					cnt <= cnt;
				end
			end
			default: begin
				cnt <= cnt;
			end
		endcase
	end
end

// opt
always @(posedge clk, posedge rst) begin
	if (rst) begin
		opt <= RESET;
	end
	else begin
		case(cState)
			IDLE: begin
				opt <= RESET;
			end
			OPT: begin
				if (BTN_WEST) begin
					opt <= SQRT;
				end
				else if (BTN_EAST) begin
					opt <= ADD;
				end
				else if (BTN_NORTH) begin
					opt <= MULT;
				end
				else begin
					opt <= RESET;
				end
			end
			NUM: begin
				opt <= opt;
			end
			default: begin
				opt <= opt;
			end
		endcase
	end
end

// ans
always @(posedge clk, posedge rst) begin
	if (rst) begin
		ans <= 0;
	end
	else begin
		case(cState)
			IDLE: begin
				ans <= SW;
			end
			OPT: begin
				if (!can) begin
					case(opt)
						RESET: begin
							ans <= SW;
						end
						ADD: begin
							ans <= ans + SW;
						end
						MULT: begin
							ans <= ans * SW;
						end
						SQRT: begin
							ans <= sqrtAns;
						end
						default: begin
							ans <= ans;
						end
					endcase
				end
				else begin
					ans <= ans;
				end
			end
			NUM: begin
				ans <= ans;
			end
			default: begin
				ans <= ans;
			end
		endcase
	end
end

// LED
always @(posedge clk, posedge rst) begin
	if (rst) begin
		LED <= 0;
	end
	else begin
		case(cState)
			IDLE: begin
				LED <= SW;
			end
			OPT: begin
				LED <= LED;
			end
			NUM: begin
				case(opt)
					RESET: begin
						LED <= SW;
					end
					ADD: begin
						LED <= ans + SW;
					end
					MULT: begin
						LED <= ans * SW;
					end
					SQRT: begin
