module pulse_width_detection(
    input clk,
    input a,
    output reg pulse,
    output reg no_pulse
);

parameter THRESHOLD = 10; // Set threshold value to 10

reg [7:0] counter;

always @(posedge clk) begin
    if (a) begin
        if (counter < THRESHOLD) begin
            counter <= counter + 1;
        end else begin
            pulse <= 1;
            no_pulse <= 0;
        end
    end else begin
        counter <= 0;
        pulse <= 0;
        no_pulse <= 1;
    end
end

endmodule

