    if (load) begin
        shift_reg <= data;
    end else if (ena == 2'b10) begin // Right rotation
        shift_reg <= {shift_reg[0], shift_reg[99:1]};
    end else if (ena == 2'b01) begin // Left rotation
        shift_reg <= {shift_reg[98:0], shift_reg[99]};
    end
end

assign q = shift_reg;

endmodule

