module hilbert_transform (
  input in,
  output out
);

parameter n = 4; // number of delay elements
parameter k1 = 0.5; // coefficient for first multiplier
parameter k2 = -0.5; // coefficient for second multiplier

reg [n-1:0] delay_line;
wire [n-1:0] delayed_signal;
wire [n-1:0] multiplied_signal;
wire [n-1:0] sum_signal;

assign delayed_signal[0] = in;
assign multiplied_signal[0] = k1 * delayed_signal[0];

genvar i;
generate
  for (i = 1; i < n; i = i + 1) begin : delay_elements
    always @(delay_line[i-1] or delayed_signal[i-1]) begin
      delay_line[i-1] <= delayed_signal[i-1];
    end
    assign delayed_signal[i] = delay_line[i-1];
    assign multiplied_signal[i] = k1 * delayed_signal[i] + k2 * delayed_signal[i-1];
  end
endgenerate

assign sum_signal = {multiplied_signal[n-1], multiplied_signal[n-2], multiplied_signal[n-3], multiplied_signal[n-4]};

assign out = in - sum_signal;

endmodule

