module pipeline (
  input clk,
  input reset,
  input [7:0] instruction,
  input [2:0] stage,
  input [4:0] rs1,
  input [4:0] rs2,
  input [4:0] rd,
  input [31:0] data1,
  input [31:0] data2,
  output reg [31:0] regfile [7:0]
);

reg [31:0] stage1_out;
reg [31:0] stage2_out;
reg [31:0] stage3_out;

reg [31:0] rs1_data;
reg [31:0] rs2_data;
reg [31:0] alu_out;
reg [31:0] imm;

reg [4:0] rs1_reg;
reg [4:0] rs2_reg;
reg [4:0] rd_reg;

reg [2:0] next_stage;

wire [31:0] shift_data;
wire [31:0] mux_data;

// Stage 1: Instruction Decode
always @(posedge clk) begin
  if (reset) begin
    rs1_reg <= 0;
    rs2_reg <= 0;
    rd_reg <= 0;
    next_stage <= 0;
  end else begin
    case (instruction[7:5])
      3'b000: begin // ADD
        rs1_reg <= rs1;
        rs2_reg <= rs2;
        rd_reg <= rd;
        imm <= 0;
        next_stage <= 1;
      end
      3'b001: begin // SUB
        rs1_reg <= rs1;
        rs2_reg <= rs2;
        rd_reg <= rd;
        imm <= 0;
        next_stage <= 1;
      end
      3'b010: begin // AND
        rs1_reg <= rs1;
        rs2_reg <= rs2;
        rd_reg <= rd;
        imm <= 0;
        next_stage <= 1;
      end
      3'b011: begin // NAND
        rs1_reg <= rs1;
        rs2_reg <= rs2;
        rd_reg <= rd;
        imm <= 0;
        next_stage <= 1;
      end
      3'b100: begin // SLL
        rs1_reg <= rs1;
        rs2_reg <= 0;
        rd_reg <= rd;
        imm <= rs2;
        next_stage <= 1;
      end
      3'b101: begin // SRL
        rs1_reg <= rs1;
        rs2_reg <= 0;
        rd_reg <= rd;
        imm <= rs2;
        next_stage <= 1;
      end
      3'b110: begin // SRA
        rs1_reg <= rs1;
        rs2_reg <= 0;
        rd_reg <= rd;
        imm <= rs2;
        next_stage <= 1;
      end
      3'b111: begin // NOP
        rs1_reg <= 0;
        rs2_reg <= 0;
        rd_reg <= 0;
        imm <= 0;
        next_stage <= 0;
      end
    endcase
  end
end

// Stage 2: Instruction Execution
always @(posedge clk) begin
  if (reset) begin
    rs1_data <= 0;
    rs2_data <= 0;
    alu_out <= 0;
    stage2_out <= 0;
  end else begin
    rs1_data <= regfile[rs1_reg];
    rs2_data <= (instruction[4]) ? imm : regfile[rs2_reg];
    shift_data <= (instruction[4]) ? {rs1_data, {27{1'b0}}} : rs2_data << imm;
    mux_data <= (instruction[3]) ? ~(rs1_data & rs2_data) : rs1_data & rs2_data;
    case (instruction[7:5])
      3'b000: begin // ADD
        alu_out <= rs1_data + rs2_data;
        stage2_out <= alu_out;
      end
      3'b001: begin // SUB
        alu_out <= rs1_data - rs2_data;
        stage2_out <= alu_out;
      end
      3'b010: begin // AND
        alu_out <= rs1_data & rs2_data;
        stage2_out <= alu_out;
      end
      3'b011: begin // NAND
        alu_out <= ~(rs1_data & rs2_data);
        stage2_out <= alu_out;
      end
      3'b100: begin // SLL
        alu_out <= shift_data;
        stage2_out <= alu_out;
      end
      3'b101: begin // SRL
        alu_out <= shift_data;
        stage2_out <= alu_out;
      end
      3'b110: begin // SRA
        alu_out <= shift_data;
        stage2_out <= alu_out;
      end
      3'b111: begin // NOP
        alu_out <= 0;
        stage2_out <= 0;
      end
    endcase
    next_stage <= 2;
  end
end

// Stage 3: Write Back
always @(posedge clk) begin
  if (reset) begin
    stage3_out <= 0;
  end else begin
    case (instruction[7:5])
      3'b000: begin // ADD
        regfile[rd_reg] <= alu_out;
        stage3_out <= alu_out;
      end
      3'b001: begin // SUB
        regfile[rd_reg] <= alu_out;
        stage3_out <= alu_out;
      end
      3'b010: begin // AND
        regfile[rd_reg] <= alu_out;
        stage3_out <= alu_out;
      end
      3'b011: begin // NAND
        regfile[rd_reg] <= alu_out;
        stage3_out <= alu_out;
      end
      3'b100: begin // SLL
        regfile[rd_reg] <= alu_out;
        stage3_out <= alu_out;
      end
      3'b101: begin // SRL
        regfile[rd_reg] <= alu_out;
        stage3_out <= alu_out;
      end
      3'b110: begin // SRA
        regfile[rd_reg] <= alu_out;
        stage3_out <= alu_out;
      end
      3'b111: begin // NOP
        stage3_out <= 0;
      end
    endcase
    next_stage <= 0;
  end
end

// Pipeline Register
always @(posedge clk) begin
  if (reset) begin
    stage1_out <= 0;
  end else begin
    case (stage)
      3'b000: begin
        stage1_out <= {instruction, rs1, rs2, rd};
      end
      3'b001: begin
        stage1_out <= stage1_out;
        stage2_out <= stage2_out;
      end
      3'b010: begin
        stage1_out <= stage1_out;
        stage2_out <= stage2_out;
        stage3_out <= stage3_out;
      end
    endcase
  end
end

// Output Register File
always @(posedge clk) begin
  if (reset) begin
    regfile <= 0;
  end else begin
    if (next_stage == 0) begin
      regfile[rd_reg] <= stage3_out;
    end
  end
end

endmodule

