        end else begin
            q <= 1'b0;
        end
    end

endmodule

module MM_slave (
		input  wire [7:0]  avs_s0_address,     //     avs_s0.address
		input  wire        avs_s0_read,        //           .read
		output wire [31:0] avs_s0_readdata,    //           .readdata
		input  wire        avs_s0_write,       //           .write
		input  wire [31:0] avs_s0_writedata,   //           .writedata
		output wire        avs_s0_waitrequest, //           .waitrequest
		input  wire        clock_clk,          //      clock.clk
		input  wire        reset_reset,        //      reset.reset
		output wire        LED_OUT             // LED_output.led_out
	);

	reg [31:0] memory [0:255]; // 256 32-bit memory locations

	assign avs_s0_readdata = memory[avs_s0_address];

	reg [1:0] state = 2'b00;
	reg [31:0] write_data;

	always @(posedge clock_clk) begin
		if (reset_reset) begin
			state <= 2'b00;
			write_data <= 32'b0;
			avs_s0_waitrequest <= 1'b0;
			LED_OUT <= 1'b0;
		end else begin
			case(state)
				2'b00: begin // Idle state
					if (avs_s0_read && !avs_s0_write) begin
						avs_s0_readdata <= memory[avs_s0_address];
						avs_s0_waitrequest <= 1'b1;
						state <= 2'b01;
					end else if (!avs_s0_read && avs_s0_write) begin
						write_data <= avs_s0_writedata;
						avs_s0_waitrequest <= 1'b1;
						state <= 2'b10;
					end
				end
				2'b01: begin // Read state
					if (!avs_s0_read) begin
						avs_s0_waitrequest <= 1'b0;
						state <= 2'b00;
					end
				end
				2'b10: begin // Write state
					if (!avs_s0_write) begin
						memory[avs_s0_address] <= write_data;
						avs_s0_waitrequest <= 1'b0;
						LED_OUT <= avs_s0_writedata[0];
						state <= 2'b00;
					end
				end
			endcase
		end
	end

endmodule

module dffrl_async (din, clk, rst_l, q, se, si, so);

parameter SIZE = 1;

input   [SIZE-1:0]      din ;   // data in
input                   clk ;   // clk or scan clk
input                   rst_l ;   // reset

output  [SIZE-1:0]      q ;     // output

input                   se ;    // scan-enable
input   [SIZE-1:0]      si ;    // scan-input
output  [SIZE-1:0]      so ;    // scan-output

reg     [SIZE-1:0]      q ;
reg     [SIZE-1:0]      q_scan ;

always @ (posedge clk or negedge rst_l)
  q[SIZE-1:0]  <= (!rst_l) ? {SIZE{1'b0}} : ((se) ? si[SIZE-1:0]  : din[SIZE-1:0] );

always @ (posedge clk or negedge rst_l)
  q_scan[SIZE-1:0] <= (!rst_l) ? {SIZE{1'b0}} : ((se) ? si[SIZE-1:0] : q[SIZE-1:0]);

assign so[SIZE-1:0] = (se) ? q[SIZE-1:0] : q_scan[SIZE-1:0];

endmodule

module mem_arbiter (
  input [n-1:0] req,
  input [n-1:0] src,
  output grant
);

parameter n = 4; // number of sources

reg [n-1:0] priority_levels; // priority levels for each source
reg [n-1:0] grant_request; // request signals for granted source
reg [n-1:0] grant_source; // source signals for granted source
reg [n-1:0] grant_priority; // priority levels for granted source
reg [n-1:0] granted; // granted signals for each source

// initialize priority levels
initial begin
  priority_levels[0] = 3; // highest priority for source 0
  priority_levels[1] = 2; // medium priority for source 1
  priority_levels[2] = 1; // low priority for source 2
  priority_levels[3] = 0; // lowest priority for source 3
end

// determine highest priority request
always @* begin
  grant_request = 0;
  grant_source = 0;
  grant_priority = 0;

  for (i = 0; i < n; i = i + 1) begin
    if (req[i] && priority_levels[i] > grant_priority[grant_source]) begin
      grant_request = req[i];
      grant_source = src[i];
      grant_priority[grant_source] = priority_levels[i];
    end
  end
end

// grant access to highest priority request
always @* begin
  granted = 0;

  if (grant_request != 0) begin
    granted[grant_source] = 1;
  end

  grant = granted;
end

endmodule

