module vending_machine(
    input clk,
    input reset,
    input coin,
    input product1,
    input product2,
    input product3,
    output reg dispense,
    output reg product1_out,
    output reg product2_out,
    output reg product3_out
);

    // Constants
    parameter C5 = 5;
    parameter C10 = 10;
    parameter C25 = 25;
    parameter PRODUCT_PRICE = 50;

    // Internal signals
    reg [7:0] balance = 0; // Maximum balance is 255 cents
    reg [2:0] product = 0; // 0 = no product, 1 = product 1, 2 = product 2, 3 = product 3
    reg [2:0] product_enable = 0; // Bitwise enable for each product
    reg dispense_next = 0; // Next value for dispense signal
    reg [2:0] product_next = 0; // Next value for product signal
    reg [2:0] product_enable_next = 0; // Next value for product_enable signal

    // Combinational logic
    assign product1_out = product_enable[0];
    assign product2_out = product_enable[1];
    assign product3_out = product_enable[2];

    // Sequential logic
    always @(posedge clk, posedge reset) begin
        if (reset) begin
            balance <= 0;
            product <= 0;
            product_enable <= 0;
            dispense <= 0;
        end else begin
            // Update balance
            if (coin) begin
                balance <= balance + C5;
                if (balance >= PRODUCT_PRICE) begin
                    product_enable_next[0] <= 1;
                    product_enable_next[1] <= 1;
                    product_enable_next[2] <= 1;
                end else begin
                    product_enable_next <= 0;
                end
            end

            // Update product
            case ({product1, product2, product3})
                3'b001: begin // Product 1
                    if (balance >= PRODUCT_PRICE) begin
                        product_next <= 1;
                        dispense_next <= 1;
                        balance <= balance - PRODUCT_PRICE;
                        product_enable_next <= 0;
                    end
                end
                3'b010: begin // Product 2
                    if (balance >= PRODUCT_PRICE) begin
                        product_next <= 2;
                        dispense_next <= 1;
                        balance <= balance - PRODUCT_PRICE;
                        product_enable_next <= 0;
                    end
                end
                3'b100: begin // Product 3
                    if (balance >= PRODUCT_PRICE) begin
                        product_next <= 3;
                        dispense_next <= 1;
                        balance <= balance - PRODUCT_PRICE;
                        product_enable_next <= 0;
                    end
                end
                default: begin // No product selected
                    product_next <= 0;
                    dispense_next <= 0;
                end
            endcase
        end
    end

    // Assign next state to current state
    always @(posedge clk) begin
        product <= product_next;
        dispense <= dispense_next;
        product_enable <= product_enable_next;
    end

endmodule

module mux4to1 (
