module binary_to_gray	(
						input		[3:0]	in,
						input				load,
						output		[3:0]	out,
						output				valid
						);

reg			[3:0]	gray_out;
reg					loaded;

always@(posedge load)
begin
	if(load)
	begin
		gray_out	<=	(in>>1) ^ in;
		loaded		<=	1;
	end
end

always@(posedge load or posedge gray_out)
begin
	if(load)
	valid	<=	1;
	else if(loaded)
	valid	<=	1;
	else
	valid	<=	0;
end

assign	out	=	gray_out;

endmodule

module top_module (
    input [2:0] sel1, // Select input for 6-to-1 mux
    input [7:0] sel2, // Select input for 256-to-1 mux
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    input [255:0] in,
    output reg [3:0] out,
