    wrusedw
);

    parameter IDLE = 2'b00;
    parameter READ = 2'b01;
    parameter WRITE = 2'b10;

    input [173:0] data_in;
    input rdclk;
    input rdreq;
    input wrclk;
    input wrreq;
    output [173:0] data_out;
    output rdempty;
    output wrempty;
    output wrfull;
    output [6:0] wrusedw;

