        .data(data_in),
        .rdclk(rdclk),
        .rdreq(rdreq),
        .wrclk(wrclk),
        .wrreq(wrreq),
        .q(fifo_data),
        .rdempty(rdempty_fifo),
        .wrempty(wrempty_fifo),
        .wrfull(wrfull_fifo),
        .wrusedw(wrusedw_fifo)
    );

    reg [1:0] state;
    reg [6:0] write_count;
    reg [6:0] read_count;
    reg [173:0] data_out_reg;

    always @ (posedge rdclk or posedge wrclk) begin
        if (rdempty_fifo && !wrempty_fifo && state == READ) begin
            state <= WRITE;
        end else if (!rdempty_fifo && wrempty_fifo && state == WRITE) begin
            state <= READ;
        end
    end

    always @ (posedge rdclk) begin
        if (state == READ && !rdempty_fifo) begin
            data_out_reg <= fifo_data;
            read_count <= read_count + 1;
        end
    end

    always @ (posedge wrclk) begin
        if (state == WRITE && !wrfull_fifo) begin
            write_count <= write_count + 1;
        end
    end

    assign data_out = data_out_reg;
    assign rdempty = rdempty_fifo && state == READ;
    assign wrempty = wrempty_fifo && state == WRITE;
    assign wrfull = wrfull_fifo && state == WRITE;
    assign wrusedw = state == WRITE ? write_count : wrusedw_fifo;

    initial begin
        state = IDLE;
        write_count = 0;
        read_count = 0;
        data_out_reg = 0;
    end

endmodule

module fsm_consecutive_ones (
  input clk,
  input reset,
  input in,
  output reg [2:0] count
);

  // Define the states
  parameter S0 = 2'b00;
  parameter S1 = 2'b01;
  parameter S2 = 2'b10;

  // Define the state register and initialize it to S0
  reg [1:0] state = S0;

  // Define the count register and initialize it to 0
  reg [2:0] consecutive_ones = 3'd0;

  always @(posedge clk) begin
    if (reset) begin
      state <= S0;
      consecutive_ones <= 3'd0;
    end else begin
      case(state)
        S0: begin
          if (in) begin
            state <= S1;
            consecutive_ones <= 3'd1;
          end else begin
            state <= S0;
            consecutive_ones <= 3'd0;
          end
        end
        S1: begin
          if (in) begin
            state <= S2;
            consecutive_ones <= consecutive_ones + 1;
          end else begin
            state <= S0;
            consecutive_ones <= 3'd0;
          end
        end
        S2: begin
          state <= S0;
          count <= consecutive_ones;
          consecutive_ones <= 3'd0;
        end
      endcase
    end
  end

endmodule

module multiplier (
  input [n-1:0] A,
  input [n-1:0] B,
  input mode,
  output reg [2*n-1:0] P
);

parameter n = 8; // number of bits in input integers

reg [n-1:0] multiplicand;
reg [n-1:0] multiplier;
reg [2*n-1:0] product;

always @(*) begin
  if (mode == 0) begin
    // Unsigned multiplication
    multiplicand = A;
    multiplier = B;
  end else begin
    // Signed multiplication
    multiplicand = $signed(A);
    multiplier = $signed(B);
  end
end

integer i;
always @(posedge clk) begin
  product = 0;
  for (i = 0; i < n; i = i + 1) begin
    if (multiplier[i]) begin
      product = product + (multiplicand << i);
    end
  end
  P = product;
end

endmodule

