module adder (
    A,
    B,
    CIN,
    SUM,
    COUT,
    VPWR,
    VGND
);

    input [3:0] A;
    input [3:0] B;
    input CIN;
    output [3:0] SUM;
    output COUT;
    output VPWR;
    output VGND;

    wire [3:0] fa0_SUM;
    wire fa0_COUT;
    wire [3:0] fa1_SUM;
    wire fa1_COUT;
    wire [3:0] fa2_SUM;
    wire fa2_COUT;
    wire [3:0] fa3_SUM;
    wire fa3_COUT;

    full_adder fa0(.A(A[0]), .B(B[0]), .CIN(CIN), .SUM(fa0_SUM[0]), .COUT(fa0_COUT));
    full_adder fa1(.A(A[1]), .B(B[1]), .CIN(fa0_COUT), .SUM(fa1_SUM[1]), .COUT(fa1_COUT));
    full_adder fa2(.A(A[2]), .B(B[2]), .CIN(fa1_COUT), .SUM(fa2_SUM[2]), .COUT(fa2_COUT));
    full_adder fa3(.A(A[3]), .B(B[3]), .CIN(fa2_COUT), .SUM(fa3_SUM[3]), .COUT(COUT));

    assign SUM = {fa3_SUM[3], fa2_SUM[2], fa1_SUM[1], fa0_SUM[0]};
    assign VPWR = 1'b1;
    assign VGND = 1'b0;

endmodule

