module mpram_gen
 #(  parameter MEMD    = 16, // memory depth
     parameter DATAW   = 32, // data width
     parameter nRPORTS = 3 , // number of reading ports
     parameter nWPORTS = 2 , // number of writing ports
     parameter IZERO   = 0 , // binary / Initial RAM with zeros (has priority over INITFILE)
     parameter IFILE   = ""  // initialization hex file (don't pass extension), optional
  )( input                                clk  , // clock
     input      [nWPORTS-1:0            ] WEnb , // write enable for each writing port
     input      [`log2(MEMD)*nWPORTS-1:0] WAddr, // write addresses - packed from nWPORTS write ports
     input      [DATAW      *nWPORTS-1:0] WData, // write data      - packed from nRPORTS read ports
     input      [`log2(MEMD)*nRPORTS-1:0] RAddr, // read  addresses - packed from nRPORTS  read  ports
     output reg [DATAW      *nRPORTS-1:0] RData  // read  data      - packed from nRPORTS read ports
  );

  localparam ADDRW = `log2(MEMD); // address width
  integer i;

  // initialize RAM, with zeros if IZERO or file if IFLE.
  reg [DATAW-1:0] mem [0:MEMD-1]; // memory array
  initial
    if (IZERO)
      for (i=0; i<MEMD; i=i+1) mem[i] = {DATAW{1'b0}};
    else
      if (IFILE != "") $readmemh({IFILE,".hex"}, mem);

  always @(posedge clk) begin
      // write to nWPORTS ports; nonblocking statement to read old data
      for (i=1; i<=nWPORTS; i=i+1)
        if (WEnb[i-1]) mem[WAddr[i*ADDRW-1 -: ADDRW]] <= WData[i*DATAW-1 -: DATAW];
      // Read from nRPORTS ports; nonblocking statement to read old data
      for (i=1; i<=nRPORTS; i=i+1)
        RData[i*DATAW-1 -: DATAW] <= mem[RAddr[i*ADDRW-1 -: ADDRW]];
    end

endmodule

module pic_controller(
    input clk,
    input rst,
    input spr_cs,
    input spr_write,
    input [31:0] spr_addr,
    input [31:0] spr_dat_i,
    input [7:0] pic_int,
    output [31:0] spr_dat_o,
    output pic_wakeup,
    output intr
);

parameter NUM_INTS = 8;

reg [NUM_INTS-1:0] picmr;
reg [NUM_INTS-1:0] picsr;
wire [NUM_INTS-1:0] um_ints;
wire [NUM_INTS-1:0] active_ints;
wire [NUM_INTS-1:0] int_priority;

assign pic_wakeup = |active_ints;
assign intr = |active_ints;

// Priority encoder
priority_encoder pe(
    .ints(pic_int & um_ints),
    .priority(int_priority)
);

// Unmasked interrupts
assign um_ints = pic_int & picmr;

// Active interrupts
assign active_ints = um_ints & ~picsr;

// PIC registers address decoder
wire picmr_sel = (spr_cs && (spr_addr[7:0] == 8'h02)) ? 1'b1 : 1'b0;
wire picsr_sel = (spr_cs && (spr_addr[7:0] == 8'h03)) ? 1'b1 : 1'b0;

// Write to PICMR
always @(posedge clk or posedge rst)
    if (rst) begin
        picmr <= {NUM_INTS{1'b1}};
    end
    else if (picmr_sel && spr_write) begin
        picmr <= #1 spr_dat_i[NUM_INTS-1:0];
    end

// Write to PICSR
always @(posedge clk or posedge rst)
    if (rst) begin
        picsr <= {NUM_INTS{1'b0}};
    end
    else if (picsr_sel && spr_write) begin
        picsr <= #1 spr_dat_i[NUM_INTS-1:0] | um_ints;
    end
    else begin
        picsr <= #1 picsr | um_ints;
    end

// Read PIC registers
always @(*) begin
    case (spr_addr[7:0])
        8'h02: begin
            spr_dat_o[NUM_INTS-1:0] = {picmr, 2'b0};
        end
        8'h03: begin
            spr_dat_o[NUM_INTS-1:0] = picsr;
        end
        default: begin
            spr_dat_o[NUM_INTS-1:0] = 0;
        end
    endcase
end

endmodule

module priority_encoder(
    input [7:0] ints,
    output [2:0] priority
);

wire [7:0] priority_levels;

// Priority levels
assign priority_levels[0] = ints[0];
assign priority_levels[1] = ints[1] | priority_levels[0];
assign priority_levels[2] = ints[2] | priority_levels[1];
assign priority_levels[3] = ints[3] | priority_levels[2];
assign priority_levels[4] = ints[4] | priority_levels[3];
assign priority_levels[5] = ints[5] | priority_levels[4];
assign priority_levels[6] = ints[6] | priority_levels[5];
assign priority_levels[7] = ints[7] | priority_levels[6];

// Priority encoder
assign priority = {priority_levels[7:0]} ^ {priority_levels[6:0], 3'b000};

endmodule

