module top_module (
    input [3:0] A,
    input [3:0] B,
    input [2:0] OP,
    output reg [1:0] result
);

    reg [3:0] Y;
    wire equal, greater_than, less_than;

    alu_module alu_inst (
        .A(A),
        .B(B),
        .OP(OP),
        .Y(Y)
    );

    comparator_module comp_inst (
        .A(A),
        .B(B),
        .equal(equal),
        .greater_than(greater_than),
        .less_than(less_than)
    );

    always @(*) begin
        case ({equal, greater_than, less_than})
            3'b000: result = 2'b00;
            3'b001: result = 2'b01;
            3'b010: result = 2'b10;
            3'b100: result = 2'b10;
            3'b011: result = 2'b00;
            3'b101: result = 2'b00;
            3'b110: result = 2'b00;
            3'b111: result = 2'b11;
        endcase
    end

endmodule

module alu_module (
    input [3:0] A,
    input [3:0] B,
    input [2:0] OP,
    output reg [3:0] Y
);

    always @(*) begin
        case (OP)
            3'b000: Y = A & B;
            3'b001: Y = A | B;
            3'b010: Y = A + B;
            3'b011: Y = A - B;
            3'b100: Y = A ^ B;
            3'b101: Y = ~A;
            3'b110: Y = A << 1;
            3'b111: Y = A >> 1;
        endcase
    end

endmodule

module comparator_module (
    input [3:0] A,
    input [3:0] B,
    output reg equal,
    output reg greater_than,
    output reg less_than
);

    always @(*) begin
        if (A == B) begin
            equal = 1;
            greater_than = 0;
            less_than = 0;
        end else if (A > B) begin
            equal = 0;
            greater_than = 1;
            less_than = 0;
        end else begin
            equal = 0;
            greater_than = 0;
            less_than = 1;
        end
    end

endmodule

