);

reg [3:0] shift_reg;

always @(posedge clk or negedge areset) begin
    if (areset == 0) begin
        shift_reg <= 4'b0000;
    end else if (ena) begin
        if (load) begin
            shift_reg <= data;
        end else begin
            shift_reg <= {shift_reg[2:0], a};
        end
    end
end

assign shift_reg_out = shift_reg;

endmodule
