module TDC (
  input in1,
  input in2,
  output reg [31:0] out
);

parameter t = 1e-9; // resolution in seconds
parameter f = 100e6; // clock frequency in Hz

reg [31:0] delay1 = 0;
reg [31:0] delay2 = 0;

always @(posedge in1 or posedge in2) begin
  if (in1) begin
    delay1 <= 0;
  end else begin
    delay1 <= delay1 + 1;
  end
end

always @(posedge in2 or posedge in1) begin
  if (in2) begin
    delay2 <= 0;
  end else begin
    delay2 <= delay2 + 1;
  end
end

always @(posedge in1 or posedge in2) begin
  out <= $floor((delay2 - delay1) * t * f);
end

endmodule

