module jFIFO(DATAOUT, full, empty, clock, reset, wn, rn, DATAIN);
  output reg [7:0] DATAOUT;
  output full, empty;
  input [7:0] DATAIN;
  input clock, reset, wn, rn; // Need to understand what is wn and rn are for

  reg [2:0] wptr, rptr; // pointers tracking the stack
  reg [7:0] memory [7:0]; // the stack is 8 bit wide and 8 locations in size

  assign full = ( (wptr == 3'b111) & (rptr == 3'b000) ? 1 : 0 );
  assign empty = (wptr == rptr) ? 1 : 0;

  always @(posedge clock)
  begin
    if (reset)
      begin
        memory[0] <= 0; memory[1] <= 0; memory[2] <= 0; memory[3] <= 0;
        memory[4] <= 0; memory[5] <= 0; memory[6] <= 0; memory[7] <= 0;
        DATAOUT <= 0; wptr <= 0; rptr <= 0;
      end
    else if (wn & !full)
      begin
        memory[wptr] <= DATAIN;
        wptr <= wptr + 1;
      end
    else if (rn & !empty)
      begin
        DATAOUT <= memory[rptr];
        rptr <= rptr + 1;
      end
  end
endmodule

module barrel_shifter (
  input clk,
  input reset,
  input [31:0] data,
  input load,
  input ena,
  input [4:0] amount,
  output reg [31:0] q
);

always @(posedge clk, posedge reset) begin
  if (reset) begin
    q <= 0;
  end else if (load) begin
    q <= data;
  end else if (ena) begin
    if (amount[4]) begin
      q <= {32{data[31]}};
    end else if (amount != 0) begin
      if (amount[3]) q[31] <= data[31];
      if (amount[2]) q[30:0] <= q[31:1];
      if (amount[1]) q[31:1] <= q[30:0];
      if (amount[0]) q[0] <= data[0];
    end
  end
end

endmodule

