module summator_tb;

	// Inputs
	reg [12:0] A;
	reg clk;
	reg ce;
	reg rst;

	// Outputs
	wire [20:0] Y;

	reg [20:0] acc;

	reg [8:0] i;

	// Instantiate the Unit Under Test (UUT)
	summator uut (
		.A(A), 
		.clk(clk), 
		.ce(ce), 
		.rst(rst), 
		.Y(Y)
	);

	initial begin
		// Initialize Inputs
		A = 13'b0000000000000;
		clk = 0;
		ce = 0;
		rst = 0;
		acc = 0;
		i = 0;

		// Wait 100 ns for global reset to finish
		#100;

		// Add stimulus here

		// Set ce to 1
		ce = 1;

		// Wait for 100 clock cycles
		while(i < 100)
		begin
			i = i + 1;
			#1 clk = ~clk;
		end

		// Set rst to 1 for the first two clock cycles and then set to 0
		rst = 1;
		#1 clk = ~clk;
		#1 clk = ~clk;
		rst = 0;

		// Set A to 13'b0000000001101 and acc to 21'b000000000000000001101 for the third and fourth clock cycles
		A = 13'b0000000001101;
		acc = 21'b000000000000000001101;
		#1 clk = ~clk;
		#1 clk = ~clk;

		// Set A to 13'b1111111111001 and acc to 21'b000000000000000000110 for the fifth and sixth clock cycles
		A = 13'b1111111111001;
		acc = 21'b000000000000000000110;
		#1 clk = ~clk;
		#1 clk = ~clk;

		// Set A to 13'b1111111111001 and acc to 21'b111111111111111111111 for the seventh and eighth clock cycles
		A = 13'b1111111111001;
		acc = 21'b111111111111111111111;
		#1 clk = ~clk;
		#1 clk = ~clk;

		// Set A to 13'b0000000000011 and acc to 21'b000000000000000000010 for the ninth and tenth clock cycles
		A = 13'b0000000000011;
		acc = 21'b000000000000000000010;
		#1 clk = ~clk;
		#1 clk = ~clk;

		// Set A to 13'b1111111111111 and acc to 21'b000000000000000000001 for the eleventh and twelfth clock cycles
		A = 13'b1111111111111;
		acc = 21'b000000000000000000001;
		#1 clk = ~clk;
		#1 clk = ~clk;

		// Set A to 13'b1111111111100 and acc to 21'b111111111111111111101 for the thirteenth and fourteenth clock cycles
		A = 13'b1111111111100;
		acc = 21'b111111111111111111101;
		#1 clk = ~clk;
		#1 clk = ~clk;

		// Set A to 13'b0000000000101 and acc to 21'b000000000000000000010 for the fifteenth and sixteenth clock cycles
		A = 13'b0000000000101;
		acc = 21'b000000000000000000010;
		#1 clk = ~clk;
		#1 clk = ~clk;

		// Set A to 13'b0000000001110 and acc to 21'b000000000000000010000 for the seventeenth and eighteenth clock cycles
		A = 13'b0000000001110;
		acc = 21'b000000000000000010000;
		#1 clk = ~clk;
		#1 clk = ~clk;

		// Set A to 13'b0000000000100 and acc to 21'b000000000000000010100 for the nineteenth and twentieth clock cycles
		A = 13'b0000000000100;
		acc = 21'b000000000000000010100;
		#1 clk = ~clk;
		#1 clk = ~clk;

		// Set A to 13'b1111111111001 and acc to 21'b000000000000000001101 for the twenty-first and twenty-second clock cycles
		A = 13'b1111111111001;
		acc = 21'b000000000000000001101;
		#1 clk = ~clk;
		#1 clk = ~clk;

	end

endmodule

module jserialadder(y,carryout,isValid,currentsum,currentcarryout,currentbitcount,clk,rst,a,b,carryin);
  output reg [3:0]y;
  output reg carryout;
  output reg isValid; 
  output reg currentsum, currentcarryout;
  output reg [1:0]currentbitcount;
  input clk,rst;
  input a,b,carryin;

  wire intermediatecarry;

  // intermediatecarry should point to the carryin only for the 1st bit afterward it is previous bit's carryout
  assign intermediatecarry = ( currentbitcount == 3'd0) ? carryin : currentcarryout;

  // Full adder to work on the posedge of the clock
  always@(posedge clk)
  begin
    currentsum <= a ^ b ^ intermediatecarry;
    currentcarryout <= ( a & b ) | ( a & intermediatecarry ) | ( b & intermediatecarry );
  end

  // Shift register for serial addition
  always@(posedge clk)
  begin
    if(rst)
      begin
        y <= 0;
        carryout <= 0;
      end
    else
      begin
        y <= {currentsum, y[3:1]};
        carryout <= ( currentbitcount == 3'd4 ) ? currentcarryout : 0;
      end
    end

  // Bit counter to keep track of number of bits added
  always@(posedge clk)
  begin
    if(rst)
        currentbitcount <= 0;
    else
        currentbitcount <= currentbitcount + 1;
  end

  // isValid will provide the indication as to whether the addition is completed  
  always@(posedge clk)
  begin
    if(rst)
        isValid <= 0;
    else
        isValid <= (currentbitcount == 3) ? 1 : 0;
  end

endmodule

