module shift_register_parallel_load
(
    input clk,
    input reset,
    input load,
    input direction,
    input [N-1:0] data_in,
    output [N-1:0] data_out
);

parameter N = 8; // number of bits in the shift register

reg [N-1:0] reg_data;

always @(posedge clk or negedge reset) begin
    if (!reset) begin
        reg_data <= 0;
    end else if (load) begin
        reg_data <= data_in;
    end else begin
        if (direction) begin
            reg_data <= {reg_data[N-2:0], reg_data[N-1]};
        end else begin
            reg_data <= {reg_data[1:N-1], reg_data[0]};
        end
    end
end

assign data_out = reg_data;

endmodule

module top_module (
    input [31:0] in0,       // First 32-bit floating point input
    input [31:0] in1,       // Second 32-bit floating point input
    output [31:0] out,      // Output of the system
    output overflow        // Overflow flag
);

    wire EQ, GT;
    wire [31:0] sum;
    wire overflow_adder;

    comparator_4bit comparator(
        .in0(in0[31:28]),
        .in1(in1[31:28]),
        .EQ(EQ),
        .GT(GT)
    );

    fp_adder adder(
        .a(in0),
        .b(in1),
        .sum(sum),
        .overflow(overflow_adder)
    );

    assign overflow = overflow_adder;
    assign out = GT ? sum : in1;

endmodule

module comparator_4bit (
    input [3:0] in0,
    input [3:0] in1,
    output EQ,
    output GT
);
    assign EQ = (in0 == in1);
    assign GT = (in0 > in1);
endmodule

module fp_adder (
    input [31:0] a,
    input [31:0] b,
    output [31:0] sum,
    output overflow
);
    reg [31:0] mantissa_a, mantissa_b, mantissa_sum;
    reg [7:0] exponent_a, exponent_b, exponent_sum;
    reg sign_a, sign_b, sign_sum;
    reg overflow_internal;

    assign sign_sum = (sign_a == sign_b) ? sign_a : (mantissa_a > mantissa_b) ? sign_a : sign_b;

    always @(*) begin
        if (exponent_a > exponent_b) begin
            exponent_sum = exponent_a;
            mantissa_b = mantissa_b >> (exponent_a - exponent_b);
        end else begin
            exponent_sum = exponent_b;
            mantissa_a = mantissa_a >> (exponent_b - exponent_a);
        end
        if (sign_a != sign_b) begin
            mantissa_sum = mantissa_a - mantissa_b;
            if (mantissa_sum < 0) begin
                mantissa_sum = -mantissa_sum;
                sign_sum = (sign_sum == 0) ? 1 : 0;
            end
        end else begin
            mantissa_sum = mantissa_a + mantissa_b;
            if (mantissa_sum[32]) begin
                mantissa_sum = mantissa_sum >> 1;
                exponent_sum = exponent_sum + 1;
                overflow_internal = 1;
            end
        end
    end

    assign sum = {sign_sum, exponent_sum, mantissa_sum[22:0]};
    assign overflow = overflow_internal;

endmodule

module majority_logic (
  input a,
  input b,
  input c,
  output reg out
);

  always @* begin
    if ({a,b,c} == 3'b111 || {a,b,c} == 3'b110 || {a,b,c} == 3'b101 || {a,b,c} == 3'b011)
      out = 1'b1;
    else
      out = 1'b0;
  end

endmodule

