module lcd_display(input CCLK, debpb0, input [255:0]strdata, input lcdreset, lcdclear, lcdhome, lcddata, lcdaddr, output reg resetlcd,
					output reg clearlcd, output reg homelcd,
					output reg datalcd, output reg addrlcd,
					output reg initlcd, output reg [7:0] lcddatin);

reg [3:0] gstate;		// state register
integer i;

always@(posedge CCLK)
	begin
		if (debpb0 == 1) // if push button is pressed, reset the LCD display
			begin
				resetlcd = 0;
				clearlcd = 0;
				homelcd = 0;
				datalcd = 0;
				gstate = 0;
			end
		else
			case (gstate)
				0: begin // initialize the LCD display
						initlcd = 1;
						gstate = 1;
					end
				1: begin // deassert initialization signal
						initlcd = 0;
						gstate = 2;
					end
				2: begin // reset the LCD display
						resetlcd = 1;
						if (lcdreset == 1)
							begin
								resetlcd = 0;
								gstate = 3;
							end
					end
				3: begin // assert initialization signal
						initlcd = 1;
						gstate = 4;
					end
				4: begin // deassert initialization signal
						initlcd = 0;
						gstate = 5;
					end
				5: begin // clear the LCD display
						clearlcd = 1;
						if (lcdclear == 1)
							begin
								clearlcd = 0;
								gstate = 6;
							end
					end
				6: begin // assert initialization signal
						initlcd = 1;
						gstate = 7;
					end
				7: begin // deassert initialization signal and set counter
						initlcd = 0;
						i = 255;
						gstate = 8;
					end
				8: begin // write address to LCD display
						if (i > 127)
							lcddatin[7:0] = 8'b0000_0000;
						else
							lcddatin[7:0] = 8'b0100_0000;

						addrlcd = 1;
						if (lcdaddr == 1)
							begin
								addrlcd = 0;
								gstate = 9;
							end
					end
				9: begin // assert initialization signal
						initlcd = 1;
						gstate = 10;
					end
				10: begin // deassert initialization signal
						initlcd = 0;
						gstate = 11;
					end
				11: begin // write data to LCD display
						lcddatin[7:0] = strdata[i-:8];
						datalcd = 1;
						if (lcddata == 1)
							begin
								datalcd = 0;
								gstate = 12;
							end
					end
				12: begin // assert initialization signal
						initlcd = 1;
						gstate = 13;
					end
				13: begin // deassert initialization signal
						initlcd = 0;
						gstate = 14;
					end
				14: begin // decrement counter and check if done
						i = i - 8;
						if (i < 0)
							gstate = 15;
						else if (i == 127)
							gstate = 8;
						else
							gstate = 11;
					end
				15: begin // reset all signals and return to initial state
						resetlcd = 0;
						clearlcd = 0;
						homelcd = 0;
						datalcd = 0;
						gstate = 0;
					end
				default: gstate = 15;
			endcase
	end
endmodule

