module CAM_block (
  input [n-1:0] search_data,
  output [m-1:0] mem_addr
);

parameter n = 8; // number of bits in the search data
parameter m = 4; // number of bits in the memory address
parameter k = 16; // number of entries in the memory

input [n-1:0] data_words [0:k-1];
output [m-1:0] mem_addresses [0:k-1];

integer i;
reg [m-1:0] matched_addresses [0:k-1];
integer num_matches;

always @(*) begin
  num_matches = 0;
  for (i = 0; i < k; i = i + 1) begin
    if (search_data == data_words[i]) begin
      matched_addresses[num_matches] = mem_addresses[i];
      num_matches = num_matches + 1;
    end
  end
end

assign mem_addr = matched_addresses;

endmodule

