module sha2_hash (
    input wire i_clk,
    input wire i_start,
    input wire [16-1:0] i_rnd,
    input wire [3:0] i_c_mdat,
    input wire [3:0] i_c_mask,
    input wire i_op0_mdat,
    input wire i_op1_mdat,
    input wire i_op2_mdat,
    input wire i_op3_mdat,
    input wire i_op4_mdat,
    input wire i_op0_mask, 
    input wire i_op1_mask,
    input wire i_op2_mask,
    input wire i_op3_mask,
    input wire i_op4_mask,    	
    output reg o_dat_mdat,
    output reg o_dat_mask
);

wire [1:0] op0 = {i_op0_mask,i_op0_mdat};
wire [1:0] op1 = {i_op1_mask,i_op1_mdat};
wire [1:0] op2 = {i_op2_mask,i_op2_mdat};
wire [1:0] op3 = {i_op3_mask,i_op3_mdat};
wire [1:0] op4 = {i_op4_mask,i_op4_mdat};

wire [1:0] c0 = {i_c_mask[0],i_c_mdat[0]};
wire [1:0] c1 = {i_c_mask[1],i_c_mdat[1]};
wire [1:0] c2 = {i_c_mask[2],i_c_mdat[2]};
wire [1:0] c3 = {i_c_mask[3],i_mdat[3]};

reg [2-1:0] op4_l1,op4_l2;
reg start_l1,start_l2;

always @(posedge i_clk) begin
    op4_l1 <= op4;
    op4_l2 <= op4_l1;
    start_l1 <= i_start;
    start_l2 <= start_l1;
end

wire [2-1:0] q01,co01;
wire [2-1:0] ci01 = i_start ? c0 : co01;

sha2_masked_full_adder add01(
    .i_clk(i_clk),
    .i_a(op0),
    .i_b(op1),
    .i_c(ci01),
    .o_q(q01),
    .o_c(co01)
);

wire [2-1:0] q23,co23;
wire [2-1:0] ci23 = i_start ? c1 : co23;

sha2_masked_full_adder add23(
    .i_clk(i_clk),
    .i_a(op2),
    .i_b(op3),
    .i_c(ci23),
    .o_q(q23),
    .o_c(co23)
);

wire [2-1:0] q03,co03;
wire [2-1:0] ci03 = start_l1 ? c2 : co03;

sha2_masked_full_adder add03(
    .i_clk(i_clk),
    .i_a(q01),
    .i_b(q23),
    .i_c(ci03),
    .o_q(q03),
    .o_c(co03)
);

wire [2-1:0] q04,co04;
wire [2-1:0] ci04 = start_l2 ? c3 : co04;

sha2_masked_full_adder add04(
    .i_clk(i_clk),
    .i_a(op4_l2),
    .i_b(q03),
    .i_c(ci04),
    .o_q(q04),
    .o_c(co04)
);

always @* begin
    o_dat_mdat = q04[0];
    o_dat_mask = q04[1];
end

endmodule

module sha2_masked_full_adder (
    input wire i_clk,
    input wire [1:0] i_a,
    input wire [1:0] i_b,
    input wire [1:0] i_c,
    output reg [1:0] o_q,
    output reg [1:0] o_c
);

wire [1:0] s;
wire c1,c2;

assign s = i_a ^ i_b ^ i_c;
assign c1 = (i_a & i_b) | (i_c & (i_a ^ i_b));
assign c2 = (i_a & i_b) | (i_a & i_c) | (i_b & i_c);

always @(posedge i_clk) begin
    o_q <= s;
    o_c <= c1 | (c2 & o_c);
end

endmodule

module half_adder(
  input A,
  input B,
  output S,
  output C
);

  assign S = A ^ B;
  assign C = A & B;

endmodule

module full_adder(
  input A,
  input B,
  input Cin,
  output S,
  output Cout
);

  wire c1, c2;

  half_adder HA1(.A(A), .B(B), .S(S), .C(c1));
  half_adder HA2(.A(S), .B(Cin), .S(S), .C(c2));

  assign Cout = c1 | c2;

endmodule

module FIFO_pixelq_op_img_data_stream_2_V_shiftReg (
    clk,
    data,
    ce,
    a,
    q);

parameter DATA_WIDTH = 32'd8;
parameter ADDR_WIDTH = 32'd1;
parameter DEPTH = 32'd2;

input clk;
input [DATA_WIDTH-1:0] data;
input ce;
input [ADDR_WIDTH-1:0] a;
output reg [DATA_WIDTH-1:0] q;

reg [DATA_WIDTH-1:0] SRL_SIG [0:DEPTH-1];
integer i;

always @ (posedge clk)
begin
    if (ce)
    begin
        for (i=0;i<DEPTH-1;i=i+1)
            SRL_SIG[i+1] <= SRL_SIG[i];
        SRL_SIG[0] <= data;
    end
end

always @ (a or SRL_SIG)
begin
    case(a)
        1'b0: q <= SRL_SIG[0];
        1'b1: q <= SRL_SIG[1];
        default: q <= 8'b0;
    endcase
end

endmodule

module audio_peripheral (
  input clk, rst, micData, enable, dataIn,
  output reg [15:0] dataOut
);

  reg [15:0] buffer [0:255];
  reg [7:0] bufferIndex;
  reg processing;

  always @(posedge clk) begin
    if (rst) begin
      bufferIndex <= 0;
      processing <= 0;
      dataOut <= 0;
    end else begin
      if (enable) begin
        buffer[bufferIndex] <= micData;
        bufferIndex <= bufferIndex + 1;
      end
      if (dataIn) begin
        processing <= 1;
        bufferIndex <= 0;
      end
      if (processing) begin
        dataOut <= buffer[bufferIndex];
        bufferIndex <= bufferIndex + 1;
        if (bufferIndex == 255) begin
          processing <= 0;
        end
      end
    end
  end

endmodule

module clkgen
       (
	// Main clocks in, depending on board
	input  sys_clk_pad_i,
	// Asynchronous, active low reset in
	input  rst_n_pad_i,
	// Input reset - through a buffer, asynchronous
	output async_rst_o,

	// Wishbone clock and reset out
	output wb_clk_o,
	output wb_rst_o,

	// JTAG clock
	// input  tck_pad_i,
	// output dbg_tck_o,

	// VGA CLK
	// output dvi_clk_o,

	// Main memory clocks
	output ddr2_if_clk_o,
	output ddr2_if_rst_o
	// output clk100_o
);

// First, deal with the asynchronous reset
wire	async_rst_n;

assign async_rst_n = ~rst_n_pad_i;

// Declare synchronous reset wires here
wire	sync_wb_rst_n;
wire	sync_ddr2_rst_n;

// Synchronous reset signal for the Wishbone clock and reset
reg wb_rst_r;

// DCM providing main system/Wishbone clock
DCM_SP #(
	// Generate 200 MHz from CLKFX
	.CLKFX_MULTIPLY	(4),
	.CLKFX_DIVIDE	(1),
	.CLKIN_PERIOD (20.0),
	// Generate 25 MHz from CLKDV
	.CLKDV_DIVIDE	(2.0)
) dcm0 (
	// Outputs
	.CLK0		(),
	.CLK180		(),
	.CLK270		(),
	.CLK2X180	(),
	.CLK2X		(),
	.CLK90		(),
	.CLKDV		(),
	.CLKFX180	(),
	.CLKFX		(),
	.LOCKED		(),
	// Inputs
	.CLKFB		(),
	.CLKIN		(sys_clk_pad_i),
	.PSEN		(1'b0),
	.RST		(async_rst_o)
);

BUFG dcm0_clkfx_bufg
       (// Outputs
	.O	(ddr2_if_clk_o),
	// Inputs
	.I	(dcm0.CLKFX)
);

assign wb_clk_o = dcm0.CLKDV;
assign sync_wb_rst_n = dcm0.LOCKED;
assign sync_ddr2_rst_n = dcm0.LOCKED;

//
// Reset generation
//

// Synchronous reset signal for the Wishbone clock and reset
always @(posedge wb_clk_o or negedge async_rst_n)
    if (~async_rst_n)
        wb_rst_r <= 1'b1;
    else
        wb_rst_r <= #1 1'b0;
assign async_rst_o = ~wb_rst_r;
always @(posedge wb_clk_o)
    wb_rst_o <= #1 async_rst_o;

assign ddr2_if_rst_o = async_rst_o;

endmodule

module shift_register(input clk, stb, di, output reg do);
	localparam integer DIN_N = 256;
	localparam integer DOUT_N = 256;

	reg [DIN_N-1:0] din;
	reg [DIN_N-1:0] din_shr;
	reg [DOUT_N-1:0] dout;
	reg [DOUT_N-1:0] dout_shr;

	always @(posedge clk) begin
		din_shr <= {din_shr, di};
		dout_shr <= {dout_shr, din_shr[DIN_N-1]};
		if (stb) begin
			din <= din_shr;
			dout <= dout_shr;
		end
	end

	assign do = dout_shr[DOUT_N-1];

endmodule

