module tone_generator (
  input clk,
  input rst,
  input [1:0] tone,
  output audio_out
);

parameter f_clk = 50_000_000; // frequency of the clock signal
parameter f_tone = 440; // frequency of the selected tone (default: A4)
parameter t_duration = 1; // duration of the tone in seconds (default: 1 second)

reg [31:0] tone_counter = 0;
reg [31:0] tone_duration = 0;
reg [31:0] sample_counter = 0;
reg [31:0] sample_period = 0;
reg [1:0] tone_type = 2'b00; // default: sine wave

wire tone_signal;

// DTMF tone generation
always @ (posedge clk) begin
  if (rst) begin
    tone_counter <= 0;
    tone_duration <= 0;
    sample_counter <= 0;
    sample_period <= 0;
    tone_type <= 2'b00;
  end else if (tone == 2'b00) begin // no tone selected
    tone_counter <= 0;
    tone_duration <= 0;
    sample_counter <= 0;
    sample_period <= 0;
    tone_type <= 2'b00;
  end else begin // tone selected
    if (tone != tone_type) begin // new tone selected
      tone_counter <= 0;
      tone_duration <= t_duration * f_clk;
      sample_counter <= 0;
      sample_period <= f_clk / f_tone;
      tone_type <= tone;
    end else begin // same tone selected
      if (tone_counter >= tone_duration) begin // tone duration reached
        tone_counter <= 0;
        tone_duration <= 0;
        sample_counter <= 0;
        sample_period <= 0;
        tone_type <= 2'b00;
      end else begin // tone duration not reached
        tone_counter <= tone_counter + 1;
        sample_counter <= sample_counter + 1;
        if (sample_counter >= sample_period) begin // new sample
          sample_counter <= 0;
        end
      end
    end
  end
end

// Sine wave generation
assign tone_signal = (tone_type == 2'b00) ? 1'b0 :
                     (tone_type == 2'b01) ? $signed($sin(2 * $pi * f_tone * tone_counter / f_clk)) :
                     (tone_type == 2'b10) ? ($signed(tone_counter < (f_clk / (2 * f_tone)))) :
                     1'b0;

// Audio output
assign audio_out = tone_signal;

endmodule

module binary_adder (A, B, Cin, S, Cout);

    input [3:0] A, B;
    input Cin;
    output [3:0] S;
    output Cout;

    wire [3:0] temp_sum;
    wire Cout1, Cout2;

    assign temp_sum = A + B + Cin;
    assign Cout1 = (temp_sum > 4'b1111);
    assign Cout2 = (temp_sum == 4'b1111);

    assign Cout = Cout1 | Cout2;
    assign S = temp_sum;

endmodule

module binary_adder_tb;

    reg [3:0] A, B;
    reg Cin;
    wire [3:0] S;
    wire Cout;

    binary_adder DUT (A, B, Cin, S, Cout);

    initial begin
        $monitor("A = %b, B = %b, Cin = %b, S = %b, Cout = %b", A, B, Cin, S, Cout);

        A = 4'b0000; B = 4'b0000; Cin = 1'b0;
        #10;

        A = 4'b0000; B = 4'b0000; Cin = 1'b1;
        #10;

        A = 4'b0010; B = 4'b0110; Cin = 1'b0;
        #10;

        A = 4'b0010; B = 4'b0110; Cin = 1'b1;
        #10;

        A = 4'b1111; B = 4'b1111; Cin = 1'b0;
        #10;

        A = 4'b1111; B = 4'b1111; Cin = 1'b1;
        #10;

        $finish;
    end

endmodule

module top_module( 
    input a0,b0,c0,
    input a1,b1,c1,
    input [1:0] ctrl,
    input select,
    output [5:0] out );

    // Define the two 3-to-4 multiplexers
    wire [3:0] mux0_out;
    wire [3:0] mux1_out;
    mux3to4 mux0(.a(a0), .b(b0), .c(c0), .sel(ctrl[0]), .y(mux0_out));
    mux3to4 mux1(.a(a1), .b(b1), .c(c1), .sel(ctrl[0]), .y(mux1_out));

    // Define the control logic to select one of the multiplexers
    wire [3:0] selected_mux_out;
    assign selected_mux_out = select ? mux1_out : mux0_out;

    // Define the functional module to add the two 4-bit outputs
    wire [5:0] sum_out;
    adder add(.a(selected_mux_out), .b(mux1_out), .sum(sum_out));

    // Assign the output
    assign out = sum_out;

endmodule

// Define the 3-to-4 multiplexer module
module mux3to4(
    input a, b, c,
    input sel,
    output [3:0] y
);
    assign y[0] = (~sel & ~a & ~b & c) | (~sel & ~a & b & ~c) | (~sel & a & ~b & ~c) | (sel & a & b & c);
    assign y[1] = (~sel & ~a & b & c) | (~sel & a & ~b & c) | (sel & a & b & ~c) | (sel & ~a & ~b & ~c);
    assign y[2] = (~sel & a & b & c) | (sel & ~a & b & c) | (sel & a & ~b & ~c) | (sel & ~a & ~b & c);
    assign y[3] = (sel & a & b & c) | (sel & ~a & b & ~c) | (sel & a & ~b & c) | (~sel & ~a & ~b & ~c);
endmodule

// Define the 4-bit adder module
module adder(
    input [3:0] a,
    input [3:0] b,
    output [5:0] sum
);
    assign sum = {2'b0, a} + {2'b0, b};
endmodule

module DisplayPort_transmitter (
  input clk,
  input rst,
  input [7:0] data,
  output dp_data,
  output dp_clk
);

  reg [7:0] data_reg;
  reg [7:0] data_shift_reg;
  reg [1:0] data_shift_count;
  reg [3:0] lane_count;
  reg [7:0] crc;
  reg [1:0] crc_count;
  reg [1:0] scrambler_state;
  reg [7:0] scrambler_reg;
  reg [1:0] scrambler_count;
  reg dp_clk_reg;
  reg dp_data_reg;

  assign dp_data = dp_data_reg;
  assign dp_clk = dp_clk_reg;

  always @(posedge clk) begin
    if (rst) begin
      data_reg <= 0;
      data_shift_reg <= 0;
      data_shift_count <= 0;
      lane_count <= 0;
      crc <= 0;
      crc_count <= 0;
      scrambler_state <= 0;
      scrambler_reg <= 0;
      scrambler_count <= 0;
      dp_clk_reg <= 0;
      dp_data_reg <= 0;
    end else begin
      data_reg <= data;
      if (data_shift_count == 0) begin
        data_shift_reg <= data_reg;
        data_shift_count <= 7;
      end else begin
        data_shift_reg <= {data_shift_reg[6:0], data_reg};
        data_shift_count <= data_shift_count - 1;
      end

      if (lane_count == 0) begin
        dp_data_reg <= 1;
        lane_count <= 1;
      end else if (lane_count == 1) begin
        dp_data_reg <= data_shift_reg[0];
        lane_count <= 2;
      end else if (lane_count == 2) begin
        dp_data_reg <= data_shift_reg[1];
        lane_count <= 3;
      end else if (lane_count == 3) begin
        dp_data_reg <= data_shift_reg[2];
        lane_count <= 4;
      end else if (lane_count == 4) begin
        dp_data_reg <= data_shift_reg[3];
        lane_count <= 5;
      end else if (lane_count == 5) begin
        dp_data_reg <= data_shift_reg[4];
        lane_count <= 6;
      end else if (lane_count == 6) begin
        dp_data_reg <= data_shift_reg[5];
        lane_count <= 7;
      end else if (lane_count == 7) begin
        dp_data_reg <= data_shift_reg[6];
        lane_count <= 0;
      end

      if (crc_count == 0) begin
        crc <= {data_reg, crc[7:1]} ^ 8'h07;
        crc_count <= 7;
      end else begin
        crc <= {crc[6:0], crc[7]} ^ 8'h07;
        crc_count <= crc_count - 1;
      end

      if (scrambler_count == 0) begin
        scrambler_reg <= data_shift_reg ^ scrambler_state;
        scrambler_state <= scrambler_reg[7] ^ scrambler_reg[5] ^ scrambler_reg[4] ^ scrambler_reg[0];
        scrambler_count <= 7;
      end else begin
        scrambler_reg <= {scrambler_reg[6:0], data_shift_reg} ^ scrambler_state;
        scrambler_state <= scrambler_reg[7] ^ scrambler_reg[5] ^ scrambler_reg[4] ^ scrambler_reg[0];
        scrambler_count <= scrambler_count - 1;
      end

      dp_clk_reg <= ~dp_clk_reg;
    end
  end
endmodule

module DisplayPort_receiver (
  input dp_data,
  input dp_clk,
  input rst,
  output [7:0] data
);

  reg [7:0] data_reg;
  reg [7:0] data_shift_reg;
  reg [1:0] data_shift_count;
  reg [3:0] lane_count;
  reg [7:0] crc;
  reg [1:0] crc_count;
  reg [1:0] descrambler_state;
  reg [7:0] descrambler_reg;
  reg [1:0] descrambler_count;
  reg dp_clk_reg;

  assign data = data_reg;

  always @(posedge dp_clk) begin
    if (rst) begin
      data_reg <= 0;
      data_shift_reg <= 0;
      data_shift_count <= 0;
      lane_count <= 0;
      crc <= 0;
      crc_count <= 0;
      descrambler_state <= 0;
      descrambler_reg <= 0;
      descrambler_count <= 0;
      dp_clk_reg <= 0;
    end else begin
      if (lane_count == 0) begin
        lane_count <= 1;
      end else if (lane_count == 1) begin
        data_shift_reg[0] <= dp_data;
        lane_count <= 2;
      end else if (lane_count == 2) begin
        data_shift_reg[1] <= dp_data;
        lane_count <= 3;
      end else if (lane_count == 3) begin
        data_shift_reg[2] <= dp_data;
        lane_count <= 4;
      end else if (lane_count == 4) begin
        data_shift_reg[3] <= dp_data;
        lane_count <= 5;
      end else if (lane_count == 5) begin
        data_shift_reg[4] <= dp_data;
        lane_count <= 6;
      end else if (lane_count == 6) begin
        data_shift_reg[5] <= dp_data;
        lane_count <= 7;
      end else if (lane_count == 7) begin
        data_shift_reg[6] <= dp_data;
        lane_count <= 0;
      end

      if (crc_count == 0) begin
        crc <= {data_shift_reg[6:0], crc[7:1]} ^ 8'h07;
        crc_count <= 7;
      end else begin
        crc <= {crc[6:0], crc[7]} ^ 8'h07;
        crc_count <= crc_count - 1;
      end

      if (descrambler_count == 0) begin
        descrambler_reg <= data_shift_reg ^ descrambler_state;
        descrambler_state <= descrambler_reg[7] ^ descrambler_reg[5] ^ descrambler_reg[4] ^ descrambler_reg[0];
        descrambler_count <= 7;
      end else begin
        descrambler_reg <= {descrambler_reg[6:0], data_shift_reg} ^ descrambler_state;
        descrambler_state <= descrambler_reg[7] ^ descrambler_reg[5] ^ descrambler_reg[4] ^ descrambler_reg[0];
        descrambler_count <= descrambler_count - 1;
      end

      if (dp_clk_reg == 0) begin
        data_reg <= descrambler_reg;
      end

      dp_clk_reg <= ~dp_clk_reg;
    end
  end
endmodule

