module traffic_light_controller (
  input clk,
  input reset,
  output reg [1:0] light_status
);

  reg [1:0] state;
  reg [3:0] count;

  parameter RED = 2'b01;
  parameter GREEN = 2'b10;
  parameter YELLOW = 2'b11;

  always @(posedge clk) begin
    if (reset) begin
      state <= RED;
      count <= 0;
    end else begin
      case (state)
        RED: begin
          if (count == 10) begin
            state <= GREEN;
            count <= 0;
          end else begin
            count <= count + 1;
          end
        end
        GREEN: begin
          if (count == 10) begin
            state <= YELLOW;
            count <= 0;
          end else begin
            count <= count + 1;
          end
        end
        YELLOW: begin
          if (count == 10) begin
            state <= RED;
            count <= 0;
          end else begin
            count <= count + 1;
          end
        end
      endcase
    end
  end

  always @(state) begin
    case (state)
      RED: light_status <= {1'b1, 1'b0};
      GREEN: light_status <= {1'b0, 1'b1};
      YELLOW: light_status <= {1'b0, 1'b0};
    endcase
  end

endmodule

module vga_output(
  input clk,
  output reg vga_hs,
  output reg vga_vs,
  output reg [4:0] vga_r,
  output reg [5:0] vga_g,
  output reg [4:0] vga_b
);

  // Define constants
  localparam H_RES = 640;
  localparam V_RES = 480;
  localparam H_SYNC_PULSE = 96;
  localparam H_FRONT_PORCH = 16;
  localparam H_BACK_PORCH = 48;
  localparam V_SYNC_PULSE = 2;
  localparam V_FRONT_PORCH = 10;
  localparam V_BACK_PORCH = 33;
  localparam PIXEL_CLOCK = 25175000;

  // Define counters
  reg [9:0] h_counter = 0;
  reg [8:0] v_counter = 0;

  // Horizontal timing
  always @(posedge clk) begin
    if (h_counter >= H_RES + H_SYNC_PULSE + H_FRONT_PORCH + H_BACK_PORCH - 1) begin
      h_counter <= 0;
      v_counter <= v_counter + 1;
    end else begin
      h_counter <= h_counter + 1;
    end
  end

  // Vertical timing
  always @(posedge clk) begin
    if (v_counter >= V_RES + V_SYNC_PULSE + V_FRONT_PORCH + V_BACK_PORCH - 1) begin
      h_counter <= 0;
      v_counter <= 0;
    end
  end

  // Horizontal sync
  always @(posedge clk) begin
    if (h_counter >= H_RES + H_FRONT_PORCH && h_counter < H_RES + H_FRONT_PORCH + H_SYNC_PULSE) begin
      vga_hs <= 0;
    end else begin
      vga_hs <= 1;
    end
  end

  // Vertical sync
  always @(posedge clk) begin
    if (v_counter >= V_RES + V_FRONT_PORCH && v_counter < V_RES + V_FRONT_PORCH + V_SYNC_PULSE) begin
      vga_vs <= 0;
    end else begin
      vga_vs <= 1;
    end
  end

  // Color generation
  always @(posedge clk) begin
    if (h_counter >= H_RES + H_FRONT_PORCH && h_counter < H_RES + H_FRONT_PORCH + 8) begin
      vga_r <= 31;
      vga_g <= 63;
      vga_b <= 31;
    end else begin
      vga_r <= 0;
      vga_g <= 0;
      vga_b <= 0;
    end
  end

endmodule

module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    input CI,
    output [3:0] C,
    output CO
);

wire [3:0] sum;
wire carry;

// Full adder
assign sum[0] = A[0] ^ B[0] ^ CI;
assign carry = (A[0] & B[0]) | (A[0] & CI) | (B[0] & CI);
assign CO = (sum[0] > 3) ? 1 : 0;

assign sum[1] = A[1] ^ B[1] ^ carry;
assign carry = (A[1] & B[1]) | (A[1] & carry) | (B[1] & carry);
assign CO = (sum[1] > 3) ? 1 : CO;

assign sum[2] = A[2] ^ B[2] ^ carry;
assign carry = (A[2] & B[2]) | (A[2] & carry) | (B[2] & carry);
assign CO = (sum[2] > 3) ? 1 : CO;

assign sum[3] = A[3] ^ B[3] ^ carry;
assign CO = (sum[3] > 3) ? 1 : CO;

assign C = sum;

endmodule

module TDC (
  input start,
  input stop,
  output reg [n-1:0] tdc
);

parameter n = 8; // number of bits in the digital signal

reg [n-1:0] counter;
reg counting;

always @(posedge clk) begin
  if (counting) begin
    counter <= counter + 1;
  end
end

always @(posedge clk) begin
  if (start && !counting) begin
    counter <= 0;
    counting <= 1;
  end else if (stop && counting) begin
    counting <= 0;
    tdc <= counter;
  end
end

endmodule

module top_module (
    input [3:0] A,
    input [3:0] B,
    input [3:0] LOAD,
    input UP_DOWN,
    input CLK,
    input RESET,
    output reg [7:0] product
);

reg [3:0] counter;
reg [3:0] multiplier_output;

always @ (posedge CLK) begin
    if (RESET) begin
        counter <= 4'b0;
    end else if (UP_DOWN) begin
        counter <= counter + 1;
    end else begin
        counter <= counter - 1;
    end

    if (LOAD) begin
        counter <= LOAD;
    end
end

always @ (A, B) begin
    multiplier_output = 4'b0;
    for (i = 0; i < 4; i = i + 1) begin
        if (B[i] == 1) begin
            multiplier_output = multiplier_output + (A << i);
        end
    end
end

always @ (counter, multiplier_output) begin
    product = counter * multiplier_output;
end

endmodule

