module ring_oscillator (
  output out
);

parameter n = 3; // number of NOT gates in the ring oscillator

wire [n-1:0] not_outputs;
wire feedback;

assign not_outputs[0] = ~feedback;

genvar i;
generate
  for (i = 1; i < n; i = i + 1) begin
    assign not_outputs[i] = ~not_outputs[i-1];
  end
endgenerate

assign feedback = not_outputs[n-1];

assign out = not_outputs[n-1];

endmodule

module top_module( 
    input wire clk,
    input wire reset,
    input wire [15:0] in,
    input wire select,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo,
    output wire [1023:0] out_demux );

    // Demultiplexer
    wire [255:0] demux_out;
    wire [3:0] demux_sel = in[3:0];
    demux_256to1 demux(
        .in(select ? 0 : demux_sel),
        .out(demux_out)
    );

    // Multiplexer
    wire [7:0] mux_out;
    wire [1:0] mux_sel = in[11:10];
    mux_2to1 mux(
        .in0(in[7:0]),
        .in1(in[15:8]),
        .sel(select ? mux_sel : 2'b0),
        .out(mux_out)
    );

    // Control Logic
    wire demux_enable = select ? 0 : 1;
    wire mux_enable = select ? 1 : 0;

    // Output
    assign out_demux = {demux_enable ? demux_out : 256'b0};
    assign out_hi = {mux_enable ? mux_out : 8'b0};
    assign out_lo = {demux_enable ? 256'b0 : 8'b0};

