module multiplication_module(
  input [7:0] A,
  input [7:0] B,
  output reg [15:0] C
);

  reg [15:0] shifted_B;
  reg [7:0] multiplier;
  reg [15:0] product;

  // Shift B left by one byte
  barrel_shifter barrel_shifter(
    .data_in(B),
    .shift_amount(8),
    .data_out(shifted_B)
  );

  // Multiply A and B
  assign product = A * B;

  // Extract lower byte of product
  assign multiplier = product[7:0];

  // Multiply A and shifted B
  assign product = A * shifted_B;

  // Shift product right by one byte
  barrel_shifter barrel_shifter(
    .data_in(product),
    .shift_amount(-8),
    .data_out(product)
  );

  // Add upper byte of product to C
  always @(*) begin
    C = {product[15:8], 0} + multiplier;
  end

endmodule

module top_module(
  input [7:0] A,
  input [15:0] B,
  output [15:0] C
);

  multiplication_module multiplication_module(
