module top_module(
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] sum
);

    wire [31:0] add_out;
    wire [31:0] sub_out;

    // Instantiate two 32-bit full adders
    full_adder_32 adder1(.a(a), .b(b), .cin(1'b0), .sum(add_out[0]), .cout(carry1));
    full_adder_32 adder2(.a(add_out), .b(~b), .cin(carry1), .sum(sum), .cout(carry2));

    // Instantiate two 32-bit full subtractors
    full_subtractor_32 sub1(.a(a), .b(b), .bin(sub), .diff(sub_out[0]), .bout(borrow1));
    full_subtractor_32 sub2(.a(sub_out), .b(~b), .bin(sub), .diff(sum), .bout(borrow2));

    // Connect the carry-out of the subtractors to the carry-in of the adders
    assign carry1 = borrow1;
    assign carry2 = borrow2;

endmodule

// 32-bit full adder module
module full_adder_32(
    input [31:0] a,
    input [31:0] b,
    input cin,
    output [31:0] sum,
    output cout
);

    genvar i;
    wire [31:0] carry;

    // Instantiate 32 full adders
    generate
        for (i = 0; i < 32; i = i + 1) begin
            full_adder fa(.a(a[i]), .b(b[i]), .cin(carry[i]), .sum(sum[i]), .cout(carry[i+1]));
        end
    endgenerate

    // Connect the carry-in and carry-out of the first and last full adders
    assign carry[0] = cin;
    assign cout = carry[32];

endmodule

// 32-bit full subtractor module
module full_subtractor_32(
    input [31:0] a,
    input [31:0] b,
    input bin,
    output [31:0] diff,
    output bout
);

    genvar i;
    wire [31:0] borrow;

    // Instantiate 32 full subtractors
    generate
        for (i = 0; i < 32; i = i + 1) begin
            full_subtractor fs(.a(a[i]), .b(b[i]), .bin(bin), .diff(diff[i]), .bout(borrow[i]));
        end
    endgenerate

    // Connect the borrow-in and borrow-out of the first and last full subtractors
    assign borrow[0] = bin;
    assign bout = borrow[32];

endmodule

// 1-bit full adder module
module full_adder(
    input a,
    input b,
    input cin,
    output sum,
    output cout
);

    assign sum = a ^ b ^ cin;
    assign cout = (a & b) | (a & cin) | (b & cin);

endmodule

// 1-bit full subtractor module
module full_subtractor(
    input a,
    input b,
    input bin,
    output diff,
    output bout
);

    assign diff = a ^ b ^ bin;
    assign bout = (~a & b & bin) | (a & ~b & bin);

endmodule

