module pipelined_module(
    input [3:0] in,
    output out_and,
    output out_or,
    output out_xnor
);

reg [3:0] stage1_out;
reg [3:0] stage2_out;

// Stage 1
and #(1) and_gate_1(in[0], in[1], in[2], in[3], stage1_out[0]);
or #(1) or_gate_1(in[0], in[1], in[2], in[3], stage1_out[1]);
xnor #(1) xnor_gate_1(in[0], in[1], in[2], in[3], stage1_out[2]);

// Stage 2
and #(1) and_gate_2(stage1_out[0], stage1_out[1], stage1_out[2], 1'b1, stage2_out[0]);
or #(1) or_gate_2(stage1_out[0], stage1_out[1], stage1_out[2], 1'b0, stage2_out[1]);
xnor #(1) xnor_gate_2(stage1_out[0], stage1_out[1], stage1_out[2], 1'b1, stage2_out[2]);

// Output
assign out_and = stage2_out[0];
assign out_or = stage2_out[1];
assign out_xnor = stage2_out[2];

endmodule

module pipeline (
  input clk,
  input reset,
  input [7:0] instruction,
  input [2:0] reg1_addr,
  input [2:0] reg2_addr,
  input [2:0] reg3_addr,
  input [15:0] reg1_data,
  input [15:0] reg2_data,
  input [15:0] reg3_data,
  output [15:0] reg1_out,
  output [15:0] reg2_out,
  output [15:0] reg3_out
);

reg [5:0] state, next_state;
reg [1:0] opcode;
reg [2:0] rs1, rs2, rd;
reg [15:0] alu_result;
reg [7:0] instruction_reg;
reg [15:0] reg_file [0:7];

assign reg1_out = reg_file[reg1_addr];
assign reg2_out = reg_file[reg2_addr];
assign reg3_out = reg_file[reg3_addr];

parameter A = 6'b000001, B = 6'b000010, C = 6'b000100, D = 6'b001000, E = 6'b010000, F = 6'b100000;

always @(posedge clk or posedge reset) begin
  if (reset) begin
    state <= A;
    reg_file <= {16'd0, 16'd0, 16'd0, 16'd0, 16'd0, 16'd0, 16'd0, 16'd0};
  end else begin
    state <= next_state;
    instruction_reg <= instruction;

    case (state)
      A: begin
        opcode <= instruction_reg[7:6];
        rs1 <= instruction_reg[5:3];
        rs2 <= instruction_reg[2:0];
        rd <= instruction_reg[5:3];
        next_state <= B;
      end

      B: begin
        alu_result <= reg_file[rs1] + reg_file[rs2];
        next_state <= C;
      end

      C: begin
        reg_file[rd] <= alu_result;
        next_state <= D;
      end

      D: begin
        opcode <= instruction_reg[7:6];
        rs1 <= instruction_reg[5:3];
        rs2 <= instruction_reg[2:0];
        rd <= instruction_reg[5:3];
        next_state <= E;
      end

      E: begin
        case (opcode)
          2'b00: alu_result <= reg_file[rs1] & reg_file[rs2];
          2'b01: alu_result <= reg_file[rs1] | reg_file[rs2];
          2'b10: alu_result <= reg_file[rs1] ^ reg_file[rs2];
          2'b11: alu_result <= ~reg_file[rs1];
        endcase
        next_state <= F;
      end

      F: begin
        reg_file[rd] <= alu_result;
        next_state <= A;
      end
    endcase
  end
end

endmodule

module pipeline_ripple_carry_adder (
  input [3:0] A,
  input [3:0] B,
  input cin,
  output [3:0] S,
  output cout
);

  wire [3:0] c;
  wire [3:0] s;

  // First stage
  full_adder fa1(A[0], B[0], cin, s[0], c[0]);

  // Second stage
  full_adder fa2(A[1], B[1], c[0], s[1], c[1]);

  // Third stage
  full_adder fa3(A[2], B[2], c[1], s[2], c[2]);

  // Fourth stage
  full_adder fa4(A[3], B[3], c[2], s[3], cout);

  assign S = s;

endmodule

