    #10;
    if (abus !== 32'bz) $display("Test failed: abus should be z");
    Bselect = 32'b10;
    #10;
    if (bbus !== 32'bz) $display("Test failed: bbus should be z");

    // Test write to register 1
    Dselect = 32'b10;
    dbus = 32'hdeadbeef;
    #10;
    Aselect = 32'b10;
    #10;
    if (abus !== 32'hdeadbeef) $display("Test failed: abus should be deadbeef");
    Bselect = 32'b10;
    #10;
    if (bbus !== 32'hdeadbeef) $display("Test failed: bbus should be deadbeef");

    $display("All tests passed");
    $finish;
  end

endmodule

module sky130_fd_sc_lp__a31o (
