module MemoryUnit
#(
	parameter DATA_WIDTH = 32,
	parameter MEMORY_ADDR_WIDTH = 13,
    parameter BIOS_ADDRESS_WIDTH = 8,
    parameter STORAGE_ADDR_WIDTH = 15,
    parameter INSTRUCTION_SIZE = 16
)(
	input allow_write_on_memory, slow_clock, fast_clock,
	input [(DATA_WIDTH -1):0] original_address,
                                original_instruction_address,
                                MemOut,
    input is_bios,
    output [(INSTRUCTION_SIZE -1):0] output_instruction,
	output [(DATA_WIDTH-1):0] data_read_from_memory
);
    wire [(STORAGE_ADDR_WIDTH - 1) : 0] storage_addr;
    wire [(DATA_WIDTH -1): 0] memory_data, storage_data;
    wire is_storage;
    wire [(INSTRUCTION_SIZE -1) : 0] memory_instruction,
                                  bios_instruction;

    // Memory controller to determine whether to access main memory or storage drive
    MemoryController controller(
        original_address,
        is_storage,
        storage_addr
    );

    // Main memory module
    Memory main_memory(
        MemOut,
        original_instruction_address[(MEMORY_ADDR_WIDTH - 1) : 0],
        original_address[(MEMORY_ADDR_WIDTH - 1) : 0],
        allow_write_on_memory, fast_clock, slow_clock,
        memory_instruction,
        memory_data
    );

    // Storage drive module
    StorageDrive hd(
        storage_addr,
        MemOut,
        is_storage && allow_write_on_memory , fast_clock, slow_clock,
        storage_data
    );

    // Memory data handler to select data from main memory or storage drive
    MemoryDataHandler poolMux(
        is_storage,
        storage_data, memory_data,
        data_read_from_memory
    );

    // BIOS module to provide instructions during startup
    BIOS bios(
        fast_clock,
        original_instruction_address[(BIOS_ADDRESS_WIDTH - 1):0],
        bios_instruction
    );

    // Instruction data handler to select instructions from BIOS or main memory
    MemoryDataHandler #(.DATA_WIDTH(INSTRUCTION_SIZE))
        instructionMUX(
            is_bios,
            bios_instruction,
            memory_instruction,
            output_instruction
        );

endmodule

// Memory controller module to determine whether to access main memory or storage drive
module MemoryController(
    input [(DATA_WIDTH -1):0] original_address,
    output is_storage,
    output [(STORAGE_ADDR_WIDTH - 1) : 0] storage_addr
);
    assign is_storage = (original_address[MEMORY_ADDR_WIDTH] == 1'b1);
    assign storage_addr = original_address[(STORAGE_ADDR_WIDTH - 1) : MEMORY_ADDR_WIDTH];
endmodule

// Main memory module to handle read/write operations
module Memory(
    input [(DATA_WIDTH -1):0] MemOut,
    input [(MEMORY_ADDR_WIDTH - 1) : 0] address,
    input allow_write,
    input fast_clock, slow_clock,
    output [(INSTRUCTION_SIZE -1) : 0] instruction,
    inout [(DATA_WIDTH -1):0] data
);
    reg [(INSTRUCTION_SIZE -1) : 0] memory_instruction;
    reg [(DATA_WIDTH -1): 0] memory_data;

    always @(posedge slow_clock) begin
        if (allow_write) begin
            memory_data <= data;
        end
    end

    always @(posedge fast_clock) begin
        memory_instruction <= MemOut;
    end

    assign instruction = memory_instruction;
    assign data = memory_data;
endmodule

// Storage drive module to handle read/write operations
module StorageDrive(
    input [(STORAGE_ADDR_WIDTH - 1) : 0] address,
    input [(DATA_WIDTH -1):0] MemOut,
    input allow_write,
    input fast_clock, slow_clock,
    output [(DATA_WIDTH -1):0] data
);
    reg [(DATA_WIDTH -1): 0] storage_data;

    always @(posedge slow_clock) begin
        if (allow_write) begin
            storage_data[address] <= MemOut;
        end
    end

    always @(posedge fast_clock) begin
        data <= storage_data[address];
    end
endmodule

// Memory data handler to select data from main memory or storage drive
module MemoryDataHandler(
    input is_storage,
    input [(DATA_WIDTH -1):0] storage_data,
    input [(DATA_WIDTH -1):0] memory_data,
    output [(DATA_WIDTH -1):0] data
);
    assign data = (is_storage) ? storage_data : memory_data;
endmodule

// BIOS module to provide instructions during startup
module BIOS(
    input fast_clock,
    input [(BIOS_ADDRESS_WIDTH - 1):0] address,
    output [(INSTRUCTION_SIZE -1):0] instruction
);
    reg [(INSTRUCTION_SIZE -1):0] bios_instruction;

    initial begin
        // Load BIOS instructions
        bios_instruction[0] = 16'h0000;
        bios_instruction[1] = 16'h0000;
        bios_instruction[2] = 16'h0000;
        bios_instruction[3] = 16'h0000;
    end

    always @(posedge fast_clock) begin
        instruction <= bios_instruction[address];
    end
endmodule

module logic_gate(
    input A1,
    input A2,
    input [1:0] B1,
    input [1:0] B2,
    input C1,
    output Y
);

    assign Y = (A1) ? 1'b1 : ((A2) ? 1'b0 : ((B1 > B2) ? 1'b1 : ((B1 < B2) ? 1'b0 : ((C1) ? 1'b1 : 1'b0))));

endmodule

module mux4to1(
