module LUT (
  input [n-1:0] in,
  input [w-1:0] addr,
  output reg [w-1:0] out
);

parameter n = 4; // number of input signals
parameter w = 1; // width of data stored in memory block
parameter d = 16; // depth of memory block

reg [w-1:0] memory [0:d-1];

// Define the lookup table
initial begin
  memory[0] = 1'b0;
  memory[1] = 1'b1;
  memory[2] = 1'b1;
  memory[3] = 1'b0;
  memory[4] = 1'b1;
  memory[5] = 1'b0;
  memory[6] = 1'b0;
  memory[7] = 1'b1;
  memory[8] = 1'b1;
  memory[9] = 1'b0;
  memory[10] = 1'b0;
  memory[11] = 1'b1;
  memory[12] = 1'b0;
  memory[13] = 1'b1;
  memory[14] = 1'b1;
  memory[15] = 1'b0;
end

// Select the appropriate output value from the memory block
always @(*) begin
  out = memory[addr];
end

endmodule

module tone_generator (
  input clk,
  input [15:0] freq,
  input [1:0] type,
  input enable,
  output tone
);

  // Define the different types of waveforms as Verilog functions
  function [7:0] sine_wave;
    input [15:0] phase;
    begin
      sine_wave = $signed(127 * sin(2 * $pi * phase / 65536) + 128);
    end
  endfunction

  function [7:0] square_wave;
    input [15:0] phase;
    begin
      if (phase < 32768) begin
        square_wave = 0;
      end else begin
        square_wave = 255;
      end
    end
  endfunction

  // Select the appropriate waveform based on the waveform type control signal
  always @ (posedge clk) begin
    case (type)
      2'b00: tone <= sine_wave(freq);
      2'b01: tone <= square_wave(freq);
      default: tone <= 0;
    endcase
  end

  // Generate the appropriate frequency for the selected waveform
  reg [15:0] phase;
  always @ (posedge clk) begin
    if (enable) begin
      phase <= phase + freq;
    end else begin
      phase <= 0;
    end
  end

endmodule

module on_board_ddr_controller(
		output reg [`DDR_DATA_WIDTH-1:0] q,
		input [`DDR_DATA_WIDTH-1:0] d,
		input [`DDR_ADDR_WIDTH-1:0] write_address, read_address,
		input we, clk);

	// data size, count elems
	reg [`DDR_DATA_WIDTH-1:0] mem [2**`DDR_ADDR_WIDTH-1:0];  

	parameter MEM_INIT_FILE = "src.mif";

	initial begin
		if (MEM_INIT_FILE != "") begin
			$readmemh(MEM_INIT_FILE, mem);
		end
	end

	always @ (posedge clk) begin
		if (we)
			mem[write_address] <= d;
		q <= mem[read_address];
	end

endmodule

module top_module( 
    input wire [7:0] in_hi,
    input wire [7:0] in_lo,
    output wire [15:0] out );

    // Pipeline registers
    reg [7:0] stage1_out;
    reg [15:0] stage2_out;

    // Stage 1: Concatenate the two input bytes
    always @(*) begin
        stage1_out = {in_hi, in_lo};
    end

    // Stage 2: Pass the concatenated half-word to the output
    always @(posedge clk) begin
        stage2_out <= stage1_out;
    end

    assign out = stage2_out;

endmodule

