module pipeline (
  input clk,
  input reset,
  input [15:0] instruction,
  input [4:0] reg1_addr,
  input [4:0] reg2_addr,
  input [4:0] reg3_addr,
  input [4:0] reg4_addr,
  input [31:0] reg1_data,
  input [31:0] reg2_data,
  input [31:0] reg3_data,
  input [31:0] reg4_data,
  output [31:0] reg1_out,
  output [31:0] reg2_out,
  output [31:0] reg3_out,
  output [31:0] reg4_out
);

reg [15:0] if_id_inst;
reg [4:0] if_id_reg1_addr;
reg [4:0] if_id_reg2_addr;
reg [4:0] id_ex_reg1_addr;
reg [4:0] id_ex_reg2_addr;
reg [4:0] ex_mem_reg1_addr;
reg [4:0] ex_mem_reg2_addr;
reg [4:0] mem_wb_reg1_addr;
reg [4:0] mem_wb_reg2_addr;
reg [31:0] if_id_reg1_data;
reg [31:0] if_id_reg2_data;
reg [31:0] id_ex_reg1_data;
reg [31:0] id_ex_reg2_data;
reg [31:0] ex_mem_reg1_data;
reg [31:0] ex_mem_reg2_data;
reg [31:0] mem_wb_reg1_data;
reg [31:0] mem_wb_reg2_data;
reg [31:0] ex_mem_alu_out;
reg [31:0] mem_wb_alu_out;
reg [31:0] mem_wb_mem_out;

always @(posedge clk) begin
  if (reset) begin
    if_id_inst <= 16'h0000;
    if_id_reg1_addr <= 5'b0;
    if_id_reg2_addr <= 5'b0;
    id_ex_reg1_addr <= 5'b0;
    id_ex_reg2_addr <= 5'b0;
    ex_mem_reg1_addr <= 5'b0;
    ex_mem_reg2_addr <= 5'b0;
    mem_wb_reg1_addr <= 5'b0;
    mem_wb_reg2_addr <= 5'b0;
    if_id_reg1_data <= 32'h00000000;
    if_id_reg2_data <= 32'h00000000;
    id_ex_reg1_data <= 32'h00000000;
    id_ex_reg2_data <= 32'h00000000;
    ex_mem_reg1_data <= 32'h00000000;
    ex_mem_reg2_data <= 32'h00000000;
    mem_wb_reg1_data <= 32'h00000000;
    mem_wb_reg2_data <= 32'h00000000;
    ex_mem_alu_out <= 32'h00000000;
    mem_wb_alu_out <= 32'h00000000;
    mem_wb_mem_out <= 32'h00000000;
  end else begin
    if_id_inst <= instruction;
    if_id_reg1_addr <= reg1_addr;
    if_id_reg2_addr <= reg2_addr;
    id_ex_reg1_addr <= if_id_reg1_addr;
    id_ex_reg2_addr <= if_id_reg2_addr;
    ex_mem_reg1_addr <= id_ex_reg1_addr;
    ex_mem_reg2_addr <= id_ex_reg2_addr;
    mem_wb_reg1_addr <= ex_mem_reg1_addr;
    mem_wb_reg2_addr <= ex_mem_reg2_addr;
    if_id_reg1_data <= reg1_data;
    if_id_reg2_data <= reg2_data;
    id_ex_reg1_data <= if_id_reg1_data;
    id_ex_reg2_data <= if_id_reg2_data;
    ex_mem_reg1_data <= id_ex_reg1_data;
    ex_mem_reg2_data <= id_ex_reg2_data;
    mem_wb_reg1_data <= ex_mem_reg1_data;
    mem_wb_reg2_data <= ex_mem_reg2_data;
    ex_mem_alu_out <= mem_wb_alu_out;
    mem_wb_alu_out <= mem_wb_mem_out;
  end
end

always @(posedge clk) begin
  case(if_id_inst[15:13])
    3'b000: begin // ADD or SUB
      id_ex_reg1_data <= if_id_reg1_data;
      id_ex_reg2_data <= if_id_reg2_data;
      case(if_id_inst[12])
        1'b0: ex_mem_alu_out <= id_ex_reg1_data + id_ex_reg2_data;
        1'b1: ex_mem_alu_out <= id_ex_reg1_data - id_ex_reg2_data;
      endcase
    end
    3'b001: begin // MUL or DIV
      id_ex_reg1_data <= if_id_reg1_data;
      id_ex_reg2_data <= if_id_reg2_data;
      case(if_id_inst[12])
        1'b0: ex_mem_alu_out <= id_ex_reg1_data * id_ex_reg2_data;
        1'b1: ex_mem_alu_out <= id_ex_reg1_data / id_ex_reg2_data;
      endcase
    end
    3'b010: begin // SHIFT
      id_ex_reg1_data <= if_id_reg1_data;
      id_ex_reg2_data <= if_id_reg2_data;
      case(if_id_inst[12:11])
        2'b00: ex_mem_alu_out <= id_ex_reg1_data << id_ex_reg2_data;
        2'b01: ex_mem_alu_out <= id_ex_reg1_data >> id_ex_reg2_data;
        2'b10: ex_mem_alu_out <= id_ex_reg1_data >>> id_ex_reg2_data;
      endcase
    end
    3'b011: begin // COMPARISON
      id_ex_reg1_data <= if_id_reg1_data;
      id_ex_reg2_data <= if_id_reg2_data;
      case(if_id_inst[12:11])
        2'b00: ex_mem_alu_out <= (id_ex_reg1_data == id_ex_reg2_data) ? 1 : 0;
        2'b01: ex_mem_alu_out <= (id_ex_reg1_data != id_ex_reg2_data) ? 1 : 0;
        2'b10: ex_mem_alu_out <= (id_ex_reg1_data < id_ex_reg2_data) ? 1 : 0;
        2'b11: ex_mem_alu_out <= (id_ex_reg1_data >= id_ex_reg2_data) ? 1 : 0;
      endcase
    end
  endcase
end

always @(posedge clk) begin
  if (reset) begin
    mem_wb_mem_out <= 32'h00000000;
  end else begin
    case(if_id_inst[15:13])
      3'b000: begin // ADD or SUB
        case(if_id_inst[12])
          1'b0: mem_wb_mem_out <= ex_mem_alu_out;
          1'b1: mem_wb_mem_out <= ex_mem_alu_out;
        endcase
      end
      3'b001: begin // MUL or DIV
        case(if_id_inst[12])
          1'b0: mem_wb_mem_out <= ex_mem_alu_out;
          1'b1: mem_wb_mem_out <= ex_mem_alu_out;
        endcase
      end
      3'b010: begin // SHIFT
        case(if_id_inst[12:11])
          2'b00: mem_wb_mem_out <= ex_mem_alu_out;
          2'b01: mem_wb_mem_out <= ex_mem_alu_out;
          2'b10: mem_wb_mem_out <= ex_mem_alu_out;
        endcase
      end
      3'b011: begin // COMPARISON
        case(if_id_inst[12:11])
          2'b00: mem_wb_mem_out <= ex_mem_alu_out;
          2'b01: mem_wb_mem_out <= ex_mem_alu_out;
          2'b10: mem_wb_mem_out <= ex_mem_alu_out;
          2'b11: mem_wb_mem_out <= ex_mem_alu_out;
        endcase
      end
    endcase
  end
end

assign reg1_out = (mem_wb_reg1_addr == reg1_addr) ? mem_wb_alu_out : ex_mem_alu_out;
assign reg2_out = (mem_wb_reg2_addr == reg2_addr) ? mem_wb_alu_out : ex_mem_alu_out;
assign reg3_out = (mem_wb_reg1_addr == reg3_addr) ? mem_wb_alu_out : ex_mem_alu_out;
assign reg4_out = (mem_wb_reg2_addr == reg4_addr) ? mem_wb_alu_out : ex_mem_alu_out;

endmodule

module RAM128X8 (
