module binary_to_bcd (
    input [3:0] binary_in,
    input clk,
    output reg [3:0] bcd_out,
    output reg EN1,
    output reg EN2,
    output reg EN3
);

reg [3:0] bcd_temp;
reg [2:0] count;

always @(posedge clk) begin
    if(count == 0) begin
        bcd_temp = binary_in;
        EN1 = 1;
        EN2 = 0;
        EN3 = 0;
    end
    else if(count == 1) begin
        bcd_temp = bcd_temp + (bcd_temp >= 5);
        EN1 = 0;
        EN2 = 1;
        EN3 = 0;
    end
    else if(count == 2) begin
        bcd_temp = bcd_temp + (bcd_temp >= 10);
        EN1 = 0;
        EN2 = 0;
        EN3 = 1;
    end
    else if(count == 3) begin
        bcd_temp = bcd_temp + (bcd_temp >= 10);
        bcd_out = bcd_temp;
        EN1 = 0;
        EN2 = 0;
        EN3 = 0;
        count <= 0;
    end
    count <= count + 1;
end

endmodule

module OAI21X1 (input IN1, IN2, IN3, output QN, input VDD, VSS);

  wire a, b, c, d, e, f, g, h, i, j, k, l, m, n, o, p, q, r, s, t, u, v, w, x, y, z;

  assign a = IN1 | IN2;
  assign b = ~a;
  assign c = ~IN2;
  assign d = c | IN3;
  assign e = b & d;
  assign f = ~c;
  assign g = f & IN3;
  assign h = e | g;
  assign i = ~h;
  assign j = i & VDD;
  assign k = ~VSS;
  assign l = j & k;
  assign m = ~l;
  assign n = m & VDD;
  assign o = ~VSS;
  assign p = n & o;
  assign q = ~p;
  assign r = q & VDD;
  assign s = ~VSS;
  assign t = r & s;
  assign u = ~t;
  assign v = u & VDD;
  assign w = ~VSS;
  assign x = v & w;
  assign y = ~x;
  assign z = y & VDD;

  assign QN = z & ~VSS;

endmodule

module xor_adder (
    input [7:0] in,
    output reg [3:0] out,
    input clk,
    input reset
);

reg [7:0] constant = 8'b10101010;

always @(posedge clk, posedge reset) begin
    if (reset) begin
        out <= 4'b0;
    end else begin
        out <= {in ^ constant} + 4'b1;
    end
end

endmodule

module decoder_4to16 (
    input [1:0] select,
    input enable,
    output reg [15:0] out
);

always @ (select or enable) begin
    if (!enable) begin
        out <= 16'b0;
    end else begin
        case (select)
            2'b00: out <= 16'b0000000000000001;
            2'b01: out <= 16'b0000000000000010;
            2'b10: out <= 16'b0000000000000100;
            2'b11: out <= 16'b0000000000001000;
            default: out <= 16'b0;
        endcase
    end
end

endmodule

module nor_gate (
