module d_flip_flop (
    input clk,
    input d,
    output reg q
);
    reg mux_out;
    always @ (posedge clk) begin
        mux_out <= d;
    end
    always @ (*) begin
        if (mux_out == 1'b0)
            q <= 1'b0;
        else
            q <= 1'b1;
    end
endmodule

module and_gate (
    input a,
    input b,
    output reg out
);
    assign out = a & b;
