module top_module (
    input clk,
    input reset,
    input [7:0] d,
    input a,
    input b,
    output reg q
);
    wire nor_out;
    wire dff_out;
    nor_gate nor_inst (
        .a(a),
        .b(b),
        .out(nor_out)
    );
    d_flip_flop dff_inst (
        .clk(clk),
        .d(d[0]),
        .q(dff_out)
    );
    and_gate and_inst (
        .a(nor_out),
        .b(dff_out),
        .out(q)
    );
endmodule

module NIOS_Sys_nios2_qsys_0_nios2_oci_fifocount_inc (
    input empty,
    input free2,
    input free3,
    input [1:0] tm_count,
    output reg [4:0] fifocount_inc
);

always @(*) begin
    if (empty) begin
        fifocount_inc = tm_count;
    end else if (free3 & (tm_count == 2'b11)) begin
        fifocount_inc = 2;
    end else if (free2 & (tm_count >= 2)) begin
        fifocount_inc = 1;
    end else if (tm_count >= 1) begin
        fifocount_inc = 0;
    end else begin
        fifocount_inc = 5'b11111;
    end
end

endmodule

module top_module(
    input wire clk,
    input wire reset,
    output reg [7:0] out_hi,
    output reg [7:0] out_lo,
    output reg [15:0] final_out
);

reg [15:0] input_num;
reg [7:0] upper_byte;
reg [7:0] lower_byte;
reg [1:0] counter;

always @(posedge clk) begin
    if (reset) begin
        counter <= 2'b00;
        input_num <= 16'b0;
    end else begin
        input_num <= $random;
        upper_byte <= input_num[15:8];
        lower_byte <= input_num[7:0];
        case(counter)
            2'b00: final_out <= {upper_byte, lower_byte};
            2'b01: final_out <= {lower_byte, upper_byte};
            2'b10: final_out <= {upper_byte, upper_byte};
            2'b11: final_out <= {lower_byte, lower_byte};
        endcase
        counter <= counter + 1;
    end
end

assign out_hi = upper_byte;
assign out_lo = lower_byte;

endmodule

module full_adder (A, B, Cin, S, Cout);
  input A, B, Cin;
  output S, Cout;

  assign S = A ^ B ^ Cin;
  assign Cout = (A & B) | (Cin & (A ^ B));
endmodule

module adder (A, B, Cin, S, Cout, Overflow);
  input [3:0] A, B;
  input Cin;
  output [3:0] S;
  output Cout, Overflow;

  wire [3:0] S_int;
  wire C0, C1, O0, O1;

  full_adder fa0(
    .A(A[0]),
    .B(B[0]),
    .Cin(Cin),
    .S(S_int[0]),
    .Cout(C0)
  );

  full_adder fa1(
    .A(A[1]),
    .B(B[1]),
    .Cin(C0),
    .S(S_int[1]),
    .Cout(C1)
  );

  full_adder fa2(
    .A(A[2]),
    .B(B[2]),
    .Cin(C1),
    .S(S_int[2]),
    .Cout(Cout)
  );

  full_adder fa3(
    .A(A[3]),
    .B(B[3]),
    .Cin(Cout),
    .S(S_int[3]),
    .Cout(O0)
  );

  assign Overflow = O0 | O1;
  assign S = S_int;
endmodule

