module stack_queue #(
    parameter MODE = 0, // 0 for stack mode, 1 for queue mode
    parameter DEPTH = 8, // maximum number of elements that can be stored
    parameter SIZE = 16, // bit width of each element
    parameter ADDR_WIDTH = 3 // number of bits required to address each element
) (
    input [SIZE-1:0] Datain,
    output [SIZE-1:0] Dataout,
    output Full,
    output Empty
);

    // Internal variables
    reg [ADDR_WIDTH-1:0] wr_pointer;
    reg [ADDR_WIDTH-1:0] rd_pointer;
    reg [ADDR_WIDTH:0] status_cnt;

    reg [SIZE-1:0] data_out;
    wire [SIZE-1:0] data_ram;

    // Inputs, outputs, wires

    // Internal circuitry

    // RAM instantiation
    ram #(
        .dat_width(SIZE),
        .adr_width(ADDR_WIDTH),
        .mem_size(DEPTH)
    ) XIFO_RAM (
        .dat_i(data_ram),
        .dat_o(Dataout),
        .adr_wr_i(wr_pointer),
        .adr_rd_i(rd_pointer),
        .we_i(Wren),
        .rde_i(Rden),
        .clk(Rdclk)
    );

    // Stack mode
    always @ (posedge Wrclk) begin
        if (Wren && !Full) begin
            data_ram[wr_pointer] <= Datain;
            wr_pointer <= wr_pointer + 1;
            if (wr_pointer == DEPTH) begin
                wr_pointer <= 0;
            end
            status_cnt <= status_cnt + 1;
        end
    end

    always @ (posedge Rdclk) begin
        if (Rden && !Empty) begin
            data_out <= data_ram[rd_pointer];
            rd_pointer <= rd_pointer + 1;
            if (rd_pointer == DEPTH) begin
                rd_pointer <= 0;
            end
            status_cnt <= status_cnt - 1;
        end
    end

    assign Full = (status_cnt == DEPTH);
    assign Empty = (status_cnt == 0);

    // Queue mode
    always @ (posedge Wrclk) begin
        if (Wren && !Full) begin
            data_ram[wr_pointer] <= Datain;
            wr_pointer <= wr_pointer + 1;
            if (wr_pointer == DEPTH) begin
                wr_pointer <= 0;
            end
            status_cnt <= status_cnt + 1;
        end
    end

    always @ (posedge Rdclk) begin
        if (Rden && !Empty) begin
            data_out <= data_ram[rd_pointer];
            rd_pointer <= rd_pointer + 1;
            if (rd_pointer == DEPTH) begin
                rd_pointer <= 0;
            end
            status_cnt <= status_cnt - 1;
        end
    end

    assign Full = (status_cnt == DEPTH);
    assign Empty = (status_cnt == 0);

    // Queue-specific functionality
    always @ (posedge Wrclk) begin
        if (Wren && !Full && MODE == 1) begin
            wr_pointer <= wr_pointer + 1;
            if (wr_pointer == DEPTH) begin
                wr_pointer <= 0;
            end
        end
    end

    always @ (posedge Rdclk) begin
        if (Rden && !Empty && MODE == 1) begin
            rd_pointer <= rd_pointer + 1;
            if (rd_pointer == DEPTH) begin
                rd_pointer <= 0;
            end
        end
    end

endmodule

