        .zero(wire_altpriority_encoder13_zero)
    );

    fp_convert_altpriority_encoder_6e8 altpriority_encoder14 (
        .data(data[7:4]),
        .q(wire_altpriority_encoder14_q),
        .zero(wire_altpriority_encoder14_zero)
    );

    assign q = {
        (~wire_altpriority_encoder14_zero),
        (
            ({2{wire_altpriority_encoder14_zero}} & wire_altpriority_encoder13_q) |
            ({2{~wire_altpriority_encoder14_zero}} & wire_altpriority_encoder14_q)
        )
    };

    assign zero = (wire_altpriority_encoder13_zero & wire_altpriority_encoder14_zero);

