module phase_detector (
    input ref_clk,
    input in_clk,
    output reg pd_out
);
always @(posedge ref_clk or posedge in_clk) begin
    pd_out <= ref_clk ^ in_clk;
end
endmodule

module loop_filter (
    input pd_out,
    output reg lf_out
);
integer i;
always @(posedge pd_out) begin
    for (i = 0; i < 32; i = i + 1) begin
        lf_out <= pd_out;
    end
end
endmodule

module vco (
    input lf_out,
    output reg vco_out
);
integer counter;
always @(posedge lf_out) begin
    counter <= counter + 1;
    if (counter >= N) begin
        vco_out <= ~vco_out;
        counter <= 0;
    end
end
endmodule

module frequency_divider (
    input vco_out,
    output reg fd_out
);
integer div_counter;
always @(posedge vco_out) begin
    div_counter <= div_counter + 1;
    if (div_counter >= M) begin
        fd_out <= ~fd_out;
        div_counter <= 0;
    end
end
endmodule

module PLL (
    input ref_clk,
    input in_clk,
    output out_clk
);
parameter N = 8; // multiplication factor
parameter M = 2; // division factor

wire pd_out, lf_out, vco_out;

phase_detector PD (
    .ref_clk(ref_clk),
    .in_clk(in_clk),
    .pd_out(pd_out)
);

loop_filter LF (
    .pd_out(pd_out),
    .lf_out(lf_out)
);

vco VCO (
    .lf_out(lf_out),
    .vco_out(vco_out)
);

frequency_divider FD (
    .vco_out(vco_out),
    .fd_out(out_clk)
);
endmodule

