module counter(
    input clk,
    input rst,
    input [31:0] max_count,
    output reg count_done
);

    localparam COUNTING = 1'b0;
    localparam RESETTING = 1'b1;

    reg [31:0] count;
    reg [1:0] state;

    always @(posedge clk) begin
        if (rst) begin
            count <= 0;
            state <= COUNTING;
            count_done <= 1'b0;
        end
        else begin
            case (state)
                COUNTING: begin
                    if (count == max_count) begin
                        state <= RESETTING;
                        count_done <= 1'b1;
                    end
                    else begin
                        count <= count + 1;
                        count_done <= 1'b0;
                    end
                end
                RESETTING: begin
                    state <= COUNTING;
                    count <= 0;
                    count_done <= 1'b0;
                end
            endcase
        end
    end

endmodule

