module PLL_freq_synthesizer (
  input CLK_in,
  input reset,
  input freq_select,
  output CLK_out
);

parameter M = 10; // multiplication factor of the PLL
parameter N = 5; // division factor of the PLL
parameter R = 16; // number of bits in the phase accumulator
parameter f_ref = 50_000_000; // reference frequency of the PLL
parameter f_out = 500_000_000; // desired output frequency of the synthesizer

// Define input and output signal widths
parameter CLK_in_width = 1;
parameter CLK_out_width = 1;

// Define input and output signal names
parameter CLK_in_name = "CLK_in";
parameter CLK_out_name = "CLK_out";
parameter reset_name = "reset";
parameter freq_select_name = "freq_select";

// Define the module's input and output signals
input [CLK_in_width-1:0] CLK_in;
output [CLK_out_width-1:0] CLK_out;
input reset;
input freq_select;

// Define the phase accumulator
reg [R-1:0] phase_accumulator;
always @(posedge CLK_in or posedge reset) begin
  if (reset) begin
    phase_accumulator <= 0;
  end else begin
    phase_accumulator <= phase_accumulator + M;
  end
end

// Define the phase-frequency detector (PFD)
reg [CLK_in_width-1:0] CLK_in_last;
reg [CLK_out_width-1:0] CLK_out_last;
reg pfd_out;
always @(posedge CLK_in or posedge CLK_out) begin
  if (CLK_in_last != CLK_in) begin
    CLK_in_last <= CLK_in;
    pfd_out <= CLK_in ^ CLK_out_last;
  end else if (CLK_out_last != CLK_out) begin
    CLK_out_last <= CLK_out;
    pfd_out <= CLK_in ^ CLK_out_last;
  end
end

// Define the loop filter
reg [15:0] loop_filter_out;
reg [15:0] loop_filter_in;
always @(posedge CLK_in) begin
  loop_filter_in <= pfd_out ? 16'hFFFF : 16'h0000;
  loop_filter_out <= loop_filter_out + loop_filter_in;
end

// Define the voltage-controlled oscillator (VCO)
reg [31:0] vco_out;
reg [31:0] vco_in;
always @(posedge CLK_in) begin
  vco_in <= loop_filter_out;
  vco_out <= vco_out + vco_in;
end

// Define the output clock signal
reg [31:0] counter;
always @(posedge CLK_in or posedge reset) begin
  if (reset) begin
    counter <= 0;
  end else begin
    counter <= counter + 1;
  end
end

assign CLK_out = vco_out[R+N-1:R] > counter[R-1:0];

endmodule

// Define the PFD module
module PFD (
  input CLK_in,
  input CLK_out,
  output reg pfd_out
);

always @(posedge CLK_in or posedge CLK_out) begin
  if (CLK_in_last != CLK_in) begin
    CLK_in_last <= CLK_in;
    pfd_out <= CLK_in ^ CLK_out_last;
  end else if (CLK_out_last != CLK_out) begin
    CLK_out_last <= CLK_out;
    pfd_out <= CLK_in ^ CLK_out_last;
  end
end

endmodule

// Define the loop filter module
module loop_filter (
  input pfd_out,
  output reg [15:0] loop_filter_out
);

always @(posedge CLK_in) begin
  loop_filter_in <= pfd_out ? 16'hFFFF : 16'h0000;
  loop_filter_out <= loop_filter_out + loop_filter_in;
end

endmodule

// Define the VCO module
module VCO (
  input [15:0] loop_filter_out,
  output reg [31:0] vco_out
);

always @(posedge CLK_in) begin
  vco_in <= loop_filter_out;
  vco_out <= vco_out + vco_in;
end

endmodule

module strobe_gen(
    input clk_sys,
    input ss11, ss12, ss13, ss14, ss15,
    input ok$, zw, oken,
    input mode, step,
    input strob_fp,
    input strobb_fp,
    output ldstate,
    output got,
    output strob1,
    output strob1b,
    output strob2,
    output strob2b
);

    // Define states
    localparam S_GOT   = 3'd0;
    localparam S_GOTW  = 3'd1;
    localparam S_ST1   = 3'd2;
    localparam S_ST1W  = 3'd3;
    localparam S_ST1B  = 3'd4;
    localparam S_PGOT  = 3'd5;
    localparam S_ST2   = 3'd6;
    localparam S_ST2B  = 3'd7;

    // Define signals
    wire if_busy = zw & oken;
    wire es1 = ss11 | (ss12 & ok$) | (ss13 & ok$) | ss14 | ss15;
    wire has_strob2 = ss11 | ss12;
    wire no_strob2 = ss13 | ss14 | ss15;

    // Define outputs
    assign got = state == S_GOT;
    assign strob1 = (state == S_ST1) | strob_fp;
    assign strob1b = (state == S_ST1B) | strobb_fp;
    assign strob2 = state == S_ST2;
    assign strob2b = state == S_ST2B;
    assign ldstate = ~if_busy & ((state == S_PGOT) | ((state == S_ST1B) & no_strob2) | (state == S_ST2B));

    // Define step signal
    reg lstep;
    always @ (posedge clk_sys) begin
        lstep <= step;
    end
    wire step_trig = ~mode | (step & ~lstep);

    // Define state machine
    reg [0:2] state;
    always @ (posedge clk_sys) begin
        case (state)
            // GOT
            S_GOT: begin
                if (es1) begin
                    state <= S_ST1;
                end else begin
                    state <= S_GOTW;
                end
            end

            S_GOTW: begin
                if (es1) begin
                    state <= S_ST1;
                end
            end

            // STROB1 front
            S_ST1: begin
                if (step_trig) state <= S_ST1B;
                else state <= S_ST1W;
            end

            // STROB1 front (wait for STEP)
            S_ST1W: begin
                if (step_trig) state <= S_ST1B;
            end

            // STROB1 back
            S_ST1B: begin
                if (has_strob2) begin
                    state <= S_ST2;
                end else if (no_strob2 & ~if_busy) begin
                    state <= S_GOT;
                end else begin
                    state <= S_PGOT;
                end
            end

            // STROB2 front
            S_ST2: begin
                state <= S_ST2B;
            end

            // STROB2 back
            S_ST2B: begin
                if (~if_busy) begin
                    state <= S_GOT;
                end else begin
                    state <= S_PGOT;
                end
            end

            // STROB2 back (wait for I/F operation to end)
            S_PGOT: begin
                if (~if_busy) begin
                    state <= S_GOT;
                end
            end
        endcase
    end

endmodule

