module edge_detector(
    clk,
    reset_n,
    in, // detector input
    out, // detector output
    edge_detect // specifies whether rising or falling edge it to detect
);

    parameter DEL = 1; // delay parameter

    input clk;
    input reset_n;
    input in;
    input edge_detect;
    output reg out;

    reg latch;
    reg prev_in;

    always @(posedge clk or negedge reset_n) begin
        if (~reset_n) begin
            out <= #DEL 1'b0;
            latch <= #DEL 1'b0;
        end else begin
            // update latch with input signal
            latch <= #DEL in;

            if (edge_detect == 1) begin
                // detect rising edge
                if (prev_in == 0 && in == 1) begin
                    out <= #DEL 1'b1;
                end else begin
                    out <= #DEL 1'b0;
                end
            end else begin
                // detect falling edge
                if (prev_in == 1 && in == 0) begin
                    out <= #DEL 1'b1;
                end else begin
                    out <= #DEL 1'b0;
                end
            end

            // store current input signal for next cycle
            prev_in <= #DEL in;
        end
    end

endmodule

module stack2pipe4 (
  input clk,
  input we,
  input [15:0] wd,
  input move,
  input pop,
  output [15:0] rd,
  output reg [1:0] last,
  output wire [1:0] next
);

  reg [15:0] stack [0:3];
  reg [1:0] ptr;
  wire [1:0] ptr_next;

  assign next = ptr_next;

  // Grey code counter
  greycount gc_(.last(last), .next(ptr_next));

  // Stack read and write pointers
  always @(posedge clk) begin
    if (we) begin
      stack[ptr] <= wd;
      ptr <= ptr_next;
    end
  end

  // Stack move and freeze functionality
  always @(posedge clk) begin
    if (move) begin
      stack[ptr_next] <= stack[ptr];
      stack[ptr] <= 16'b0;
    end
  end

  // Stack push and pop functionality
  always @(posedge clk) begin
    if (pop) begin
      rd <= stack[ptr];
      stack[ptr] <= 16'b0;
      ptr <= (ptr==0) ? 3'b011 : ptr-1;
    end else begin
      rd <= 16'b0;
    end
  end

  always @(posedge clk) begin
    if (!pop && we) begin
      ptr <= ptr_next;
    end
  end

endmodule

module counter
(
    input clk,
    input reset,
    input up_down,
    output reg [3:0] q
);

reg [3:0] next_q;

always @(posedge clk or posedge reset)
begin
    if (reset)
        q <= 4'b0000;
    else
        q <= next_q;
end

always @*
begin
    if (reset)
        next_q = 4'b0000;
    else if (up_down)
        next_q = q + 1;
    else
        next_q = q - 1;
end

endmodule

module top_module (
    input clk,
    input reset, // Synchronous active-high reset
    input [7:0] d, // 8-bit input for the register
    input select, // Select input to choose between register and D flip-flops
    output [7:0] q, // 8-bit output from the active module
    output done // Signal indicating when all D flip-flops have finished loading their initial values
);

    // 8-bit register with active high asynchronous reset
    reg [7:0] reg_out;
    always @ (posedge clk or posedge reset) begin
        if (reset) begin
            reg_out <= 8'h34;
        end else begin
            reg_out <= d;
        end
    end

    // 8 D flip-flops with active high asynchronous reset
    reg [7:0] dff_out [0:7];
    integer i;
    always @ (posedge clk or posedge reset) begin
        if (reset) begin
            for (i = 0; i < 8; i = i + 1) begin
                dff_out[i] <= 8'h34;
            end
        end else begin
            for (i = 0; i < 8; i = i + 1) begin
                dff_out[i] <= select ? dff_out[i] : d[i];
            end
        end
    end

    // 9th D flip-flop triggered by negative edge of clk
    reg done_out;
    reg [7:0] or_out;
    always @ (negedge clk or posedge reset) begin
        if (reset) begin
            done_out <= 1'b0;
            or_out <= 8'h00;
        end else begin
            done_out <= 1'b1;
            for (i = 0; i < 8; i = i + 1) begin
                or_out[i] <= reg_out[i] | dff_out[i];
                done_out <= done_out & (dff_out[i] != 8'h34);
            end
        end
    end

    // Output the final result based on select input
    assign q = select ? reg_out : or_out;
    assign done = done_out;

endmodule

module acl_profile_counter
(
  input clock,
  input resetn,
  input enable,

  input shift,
  input incr_cntl,
  input [63:0] shift_in,
  input [31:0] incr_val,
  output reg [31:0] data_out,
  output reg [63:0] shift_out
);

parameter COUNTER_WIDTH=64;
parameter INCREMENT_WIDTH=32;
parameter DAISY_WIDTH=64;

reg [COUNTER_WIDTH-1:0] counter;

always@(posedge clock or negedge resetn)
begin
  if(!resetn)
    counter <= {COUNTER_WIDTH{1'b0}};
  else if(shift)
    counter <= {shift_in, counter[DAISY_WIDTH-1:0]};
  else if(enable && incr_cntl)
    counter <= counter + {incr_val, 32'b0};
end

assign data_out = counter[31:0];
assign shift_out = {counter, shift_in} >> COUNTER_WIDTH;

endmodule

module valve_controller
  (input clk, input reset, input clear,
   input shutoff,
   input [35:0] data_i, input src_rdy_i, output dst_rdy_o,
   output [35:0] data_o, output src_rdy_o, input dst_rdy_i);

   reg shutoff_int, active;
   wire active_next = (src_rdy_i & dst_rdy_o) ? ~data_i[33] : active;

   assign data_o = data_i;

   assign dst_rdy_o = shutoff_int ? 1'b1 : dst_rdy_i;
   assign src_rdy_o = shutoff_int ? 1'b0 : src_rdy_i;

   always @(posedge clk)
     if(reset | clear)
       active <= 0;
     else
       active <= active_next;

   always @(posedge clk)
     if(reset | clear)
       shutoff_int <= 0;
     else if(~active_next)
       shutoff_int <= shutoff;

endmodule

module population_count( 
    input [254:0] in,
    output [7:0] out );

    reg [7:0] count;
    reg [7:0] temp;
    reg [7:0] temp2;

    always @* begin
        count = 0;
        temp = {in[254:128]} ^ {in[127:0]};
        temp2 = {temp[6:0], 1'b0} ^ {temp[7], 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0};
        count = count + temp2;
        temp = {in[126:64]} ^ {in[63:0]};
        temp2 = {temp[6:0], 1'b0} ^ {temp[7], 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0};
        count = count + temp2;
        temp = {in[62:32]} ^ {in[31:0]};
        temp2 = {temp[6:0], 1'b0} ^ {temp[7], 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0};
        count = count + temp2;
        temp = {in[30:16]} ^ {in[15:0]};
        temp2 = {temp[6:0], 1'b0} ^ {temp[7], 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0};
        count = count + temp2;
        temp = {in[14:8]} ^ {in[7:0]};
        temp2 = {temp[6:0], 1'b0} ^ {temp[7], 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0};
        count = count + temp2;
        temp = {in[6:4]} ^ {in[3:0]};
        temp2 = {temp[2:0], 1'b0} ^ {temp[3], 1'b0, 1'b0, 1'b0};
        count = count + temp2;
        out = count;
    end

endmodule

module seven_segment_display (
    input [3:0] D,
    output A,
    output B,
    output C,
    output D,
    output E,
    output F,
    output G
);

reg [6:0] segment_data [0:15];
reg [3:0] pipeline_reg;
reg [6:0] pipeline_data [0:3];

assign A = pipeline_data[0][6];
assign B = pipeline_data[0][5];
assign C = pipeline_data[0][4];
assign D = pipeline_data[0][3];
assign E = pipeline_data[0][2];
assign F = pipeline_data[0][1];
assign G = pipeline_data[0][0];

always @(*) begin
    case (D)
        4'b0000: segment_data[0] = 7'b1111110;
        4'b0001: segment_data[1] = 7'b0110000;
        4'b0010: segment_data[2] = 7'b1101101;
        4'b0011: segment_data[3] = 7'b1111001;
        4'b0100: segment_data[4] = 7'b0110011;
        4'b0101: segment_data[5] = 7'b1011011;
        4'b0110: segment_data[6] = 7'b1011111;
        4'b0111: segment_data[7] = 7'b1110000;
        4'b1000: segment_data[8] = 7'b1111111;
        4'b1001: segment_data[9] = 7'b1111011;
        4'b1010: segment_data[10] = 7'b1110111;
        4'b1011: segment_data[11] = 7'b0011111;
