module protocol_converter (
  input aclk,
  input areset_d1,
  input [31:0] m_axi_araddr,
  input m_axi_arvalid,
  input m_axi_rready,
  input [31:0] in,
  output m_axi_arready,
  output [31:0] m_axi_rdata,
  output [1:0] m_axi_rresp,
  output m_axi_rvalid,
  output [31:0] out
);

  // AXI state machine states
  localparam IDLE = 2'b00;
  localparam READ = 2'b01;
  localparam RESP = 2'b10;

  // Custom protocol state machine states
  localparam CUSTOM_IDLE = 2'b00;
  localparam CUSTOM_READ = 2'b01;

  // Internal registers
  reg [31:0] data_reg;
  reg [1:0] resp_reg;
  reg [1:0] custom_state_reg;
  reg [1:0] axi_state_reg;
  reg [31:0] addr_reg;
  reg [31:0] custom_data_reg;
  reg custom_valid_reg;
  reg custom_ready_reg;

  // Default values
  assign m_axi_arready = 1'b0;
  assign m_axi_rdata = 32'h0;
  assign m_axi_rresp = 2'h0;
  assign m_axi_rvalid = 1'b0;
  assign out = 32'h0;

  // AXI state machine
  always @(posedge aclk) begin
    if (areset_d1) begin
      axi_state_reg <= IDLE;
      addr_reg <= 32'h0;
      data_reg <= 32'h0;
      resp_reg <= 2'h0;
    end else begin
      case(axi_state_reg)
        IDLE: begin
          if (m_axi_arvalid) begin
            axi_state_reg <= READ;
            addr_reg <= m_axi_araddr;
            m_axi_arready <= 1'b1;
          end
        end
        READ: begin
          if (m_axi_rready) begin
            axi_state_reg <= RESP;
            m_axi_rvalid <= 1'b1;
            data_reg <= in;
          end
        end
        RESP: begin
          if (m_axi_rready) begin
            axi_state_reg <= IDLE;
            m_axi_rvalid <= 1'b0;
            resp_reg <= 2'h0;
          end
        end
      endcase
    end
  end

  // Custom protocol state machine
  always @(posedge aclk) begin
    if (areset_d1) begin
      custom_state_reg <= CUSTOM_IDLE;
      custom_data_reg <= 32'h0;
      custom_valid_reg <= 1'b0;
      custom_ready_reg <= 1'b0;
    end else begin
      case(custom_state_reg)
        CUSTOM_IDLE: begin
          if (m_axi_rvalid) begin
            custom_state_reg <= CUSTOM_READ;
            custom_data_reg <= data_reg;
            custom_valid_reg <= 1'b1;
          end
        end
        CUSTOM_READ: begin
          if (custom_ready_reg) begin
            custom_state_reg <= CUSTOM_IDLE;
            custom_valid_reg <= 1'b0;
          end
        end
      endcase
    end
  end

  // Custom protocol interface
  assign out = custom_data_reg;
  assign custom_ready_reg = 1'b1;

endmodule

