    sky130_fd_sc_hd__udp_inv_1           inv5      (RESET_B_delayed, RESET_B);

    // Delayed signals with delay of 1 clock cycle
    sky130_fd_sc_hd__udp_dff$NSR_pp$PG$N dff1      (D_delayed      , SET, RESET, CLK_delayed, D      , notifier, VPWR, VGND);
    sky130_fd_sc_hd__udp_dff$NSR_pp$PG$N dff2      (SCD_delayed    , SET, RESET, CLK_delayed, SCD    , notifier, VPWR, VGND);
    sky130_fd_sc_hd__udp_dff$NSR_pp$PG$N dff3      (SCE_delayed    , SET, RESET, CLK_delayed, SCE    , notifier, VPWR, VGND);
    sky130_fd_sc_hd__udp_dff$NSR_pp$PG$N dff4      (CLK_delayed    , SET, RESET, CLK_delayed, CLK    , notifier, VPWR, VGND);
    sky130_fd_sc_hd__udp_dff$NSR_pp$PG$N dff5      (SET_B_delayed  , SET, RESET, CLK_delayed, SET_B  , notifier, VPWR, VGND);
    sky130_fd_sc_hd__udp_dff$NSR_pp$PG$N dff6      (RESET_B_delayed, SET, RESET, CLK_delayed, RESET_B, notifier, VPWR, VGND);

    // Combinational logic
    assign RESET = RESET_B_delayed;
    assign SET = SET_B_delayed;

    // Multiplexer
    assign mux_out = (SCD_delayed == 1'b1) ? SCE_delayed : D_delayed;

    // Output logic
    always @ (posedge CLK) begin
        if (cond_D) begin
            buf_Q <= D_delayed;
            notifier <= 1'b1;
