module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    input [1:0] Sel,
    input clk,
    output [3:0] Sum,
    output Cout,
    output [3:0] Z
    );

    reg [3:0] temp_sum;
    reg temp_cout;
    reg [3:0] temp_z;

    always @(posedge clk) begin
        case (Sel)
            2'b00: begin // addition
                temp_sum = A + B + Cin;
                temp_cout = (temp_sum > 4'hF);
                Sum = temp_sum;
                Cout = temp_cout;
                temp_z = 4'h0;
            end
            2'b01: begin // subtraction
                temp_sum = A - B - Cin;
                temp_cout = (temp_sum < 0);
                Sum = temp_sum;
                Cout = temp_cout;
                temp_z = 4'h0;
            end
            2'b10: begin // bitwise AND
                temp_z = A & B;
                Sum = 4'h0;
                Cout = 1'b0;
            end
            2'b11: begin // bitwise OR
                temp_z = A | B;
                Sum = 4'h0;
                Cout = 1'b0;
            end
            default: begin
                temp_sum = 4'h0;
                temp_cout = 1'b0;
                temp_z = 4'h0;
            end
        endcase
        Z = temp_z;
    end

endmodule

