module binary_to_bcd (
    input [3:0] BIN,
    output reg [3:0] BCD_HIGH,
    output reg [3:0] BCD_LOW
);

integer i;

always @(*) begin
    for (i = 0; i < 4; i = i + 1) begin
        if (BIN[i] >= 5) begin
            BCD_HIGH = BCD_HIGH + {1'b0, 1'b0, 1'b1, 1'b0};
            BIN[i] = BIN[i] - 5;
        end
        if (BIN[i] >= 2) begin
            BCD_HIGH = BCD_HIGH + {1'b0, 1'b0, 1'b0, 1'b1};
            BIN[i] = BIN[i] - 2;
        end
        BCD_LOW = BCD_LOW + BIN[i];
    end
end

endmodule

