module mux8(
   // Outputs
   out,
   // Inputs
   in0, in1, in2, in3, in4, in5, in6, in7, sel0, sel1, sel2, sel3, sel4,
   sel5, sel6
   );

   //data inputs
   input [7:0]  in0;
   input [7:0]  in1;
   input [7:0]  in2;
   input [7:0]  in3;
   input [7:0]  in4;
   input [7:0]  in5;
   input [7:0]  in6;
   input [7:0]  in7;

   //select inputs
   input        sel0;
   input        sel1;
   input        sel2;
   input        sel3;
   input        sel4;
   input        sel5;
   input        sel6;


   output [7:0] out;


   assign out[7:0] = ({8{sel0}} & in0[7:0] |
                      {8{sel1}} & in1[7:0] |
                      {8{sel2}} & in2[7:0] |
                      {8{sel3}} & in3[7:0] |
                      {8{sel4}} & in4[7:0] |
                      {8{sel5}} & in5[7:0] |
                      {8{sel6}} & in6[7:0] |
                      {8{~(sel0|sel1|sel2|sel3|sel4|sel5|sel6)}} & in7[7:0]);


   // synthesis translate_off
   always @*
     if((sel0+sel1+sel2+sel3+sel4+sel5+sel6>1) & $time>0) begin
       $display("ERROR>>Arbitration failure in cell %m");
       out = 8'h00;
     end
   // synthesis translate_on


endmodule

module MAIN (
    input clk,
    input [4:0] R_Addr_A,
    input [4:0] R_Addr_B,
    input [4:0] W_Addr,
    input Reset,
    input Write_Reg,
    input [2:0] ALU_OP,
    output [31:0] LED,
    output [31:0] A,
    output [31:0] B,
    output OF,
    output ZF
);

    // Register file
    reg [31:0] regs [31:0];

    // Combinational logic for OF and ZF
    wire [32:0] result;
    assign result = {1'b0, A} + {1'b0, B};
    assign OF = (result[33] != result[32]);
    assign ZF = (result == 0);

    // Read A and B from register file
    assign A = regs[R_Addr_A];
    assign B = regs[R_Addr_B];

    // Perform operation based on ALU_OP
    always @(posedge clk) begin
        if (Reset) begin
            LED <= 0;
        end else begin
            case (ALU_OP)
                3'b000: LED <= A + B;
                3'b001: LED <= A - B;
                3'b010: LED <= A & B;
                3'b011: LED <= A | B;
                3'b100: LED <= A ^ B;
                3'b101: LED <= A << B;
                3'b110: LED <= A >> B;
                3'b111: LED <= $signed(A) >>> B;
            endcase
        end
    end

    // Write LED to register file if Write_Reg is high
    always @(posedge clk) begin
        if (Reset) begin
            regs[W_Addr] <= 0;
        end else if (Write_Reg) begin
            regs[W_Addr] <= LED;
        end
    end

endmodule

module pipeline_processor(
    input clk, PCSrc,
    input [31:0] EX_MEM_NPC, IF_ID_IR, IF_ID_NPC,
    output reg [31:0] ID_EX_IR, ID_EX_A, ID_EX_B, ID_EX_NPC,
    output reg ID_EX_Flush
);

reg [31:0] reg_file[31:0];
reg [31:0] mem[1023:0];
reg [31:0] PC;

localparam ADD_OP = 5'b00000;
localparam SUB_OP = 5'b00001;
localparam LW_OP = 5'b00010;
localparam SW_OP = 5'b00011;
localparam BEQ_OP = 5'b00100;

localparam ST_IF = 2'b00;
localparam ST_ID = 2'b01;
localparam ST_EX = 2'b10;

reg [1:0] state;
reg [31:0] ID_EX_IR_temp, ID_EX_NPC_temp;
reg [4:0] ID_EX_rs, ID_EX_rt, ID_EX_rd, ID_EX_imm, ID_EX_func;
reg [2:0] ID_EX_ALUOp;
reg [31:0] ID_EX_A_temp, ID_EX_B_temp;

always @(posedge clk) begin
    if (state == ST_IF) begin
        ID_EX_Flush <= 0;
        ID_EX_IR_temp <= IF_ID_IR;
        ID_EX_NPC_temp <= IF_ID_NPC;
        PC <= IF_ID_NPC;
        state <= ST_ID;
    end else if (state == ST_ID) begin
        ID_EX_IR <= ID_EX_IR_temp;
        ID_EX_NPC <= ID_EX_NPC_temp;
        ID_EX_rs <= ID_EX_IR_temp[25:21];
        ID_EX_rt <= ID_EX_IR_temp[20:16];
        ID_EX_rd <= ID_EX_IR_temp[15:11];
        ID_EX_imm <= ID_EX_IR_temp[15:0];
        ID_EX_func <= ID_EX_IR_temp[5:0];
        ID_EX_A_temp <= reg_file[ID_EX_rs];
        ID_EX_B_temp <= reg_file[ID_EX_rt];
        case (ID_EX_IR_temp[31:26])
            ADD_OP, SUB_OP: ID_EX_ALUOp <= 3'b000;
            LW_OP: ID_EX_ALUOp <= 3'b001;
            SW_OP: ID_EX_ALUOp <= 3'b010;
            BEQ_OP: ID_EX_ALUOp <= 3'b100;
        endcase
        state <= ST_EX;
    end else if (state == ST_EX) begin
        ID_EX_A <= ID_EX_A_temp;
        ID_EX_B <= ID_EX_B_temp;
        case (ID_EX_ALUOp)
            3'b000: ID_EX_IR <= {6'b000000, ID_EX_rs, ID_EX_rt, ID_EX_rd, 5'b00000, ID_EX_func};
            3'b001: ID_EX_IR <= {6'b100011, ID_EX_rs, ID_EX_rt, ID_EX_imm};
            3'b010: ID_EX_IR <= {6'b101011, ID_EX_rs, ID_EX_rt, ID_EX_imm};
            3'b100: begin
                if (ID_EX_A_temp == ID_EX_B_temp) begin
                    ID_EX_Flush <= 1;
                    ID_EX_NPC <= ID_EX_NPC + (ID_EX_imm << 2);
                end else begin
                    ID_EX_Flush <= 0;
                    ID_EX_NPC <= ID_EX_NPC + 4;
                end
            end
        endcase
        state <= ST_IF;
        if (PCSrc == 1 || ID_EX_Flush == 1) begin
            PC <= EX_MEM_NPC;
        end else begin
            PC <= ID_EX_NPC;
        end
    end
end

always @(posedge clk) begin
    if (state == ST_EX) begin
        case (ID_EX_ALUOp)
            3'b000: reg_file[ID_EX_rd] <= ID_EX_A_temp + ID_EX_B_temp;
            3'b001: reg_file[ID_EX_rt] <= mem[ID_EX_A_temp + ID_EX_imm];
            3'b010: mem[ID_EX_A_temp + ID_EX_imm] <= ID_EX_B_temp;
        endcase
    end
end

endmodule

module meet_the_requirement(
	input csi_clk,
	input csi_reset_n,
	input [7:0] avs_address,
	input [31:0] avs_writedata,
	input avs_write_n,
	input avs_read_n,
	output reg [31:0] read_data_buf,
	output reg [31:0] write_reg_buf [(TIME_QLT_BASE + TIME_QLT_LEN - 1) : 0],
	output reg [31:0] write_refresh,
	output reg io_update
	);

	localparam SEC_CNT_DATA_BASE	= 0;
	localparam NS_CNT_DATA_BASE	= 6;
	localparam CTRL_CNT_BASE		= 9;
	localparam ERR_CNT_BASE		= 12;
	localparam UTC_TIME_BASE		= 15;
	localparam TIME_ZONE_BASE	= 18;
	localparam LEAP_CNT_BASE		= 19;
	localparam LEAP_OCCUR_BASE	= 20;
	localparam LEAP_DCT_BASE		= 22;
	localparam DST_INGRESS_BASE	= 23;
	localparam DST_ENGRESS_BASE	= 25;
	localparam TIME_QUALITY_BASE	= 27;

	localparam SEC_DATA_LEN		= 6;
	localparam NS_DATA_LEN		= 3;
	localparam CTRL_CNT_LEN		= 3;
	localparam ERR_CNT_LEN		= 3;
	localparam UTC_TIME_LEN		= 3;
	localparam TIME_ZONE_LEN		= 1;
	localparam LEAP_CNT_LEN		= 1;
	localparam LEAP_OCCR_LEN	= 2;
	localparam LEAP_DCT_LEN		= 2;
	localparam DST_INEN_LEN		= 2;
	localparam TIME_QLT_LEN		= 1;

	localparam WRITE_NEW_DATA_YES = 1'b1;
	localparam WRITE_NEW_DATA_NO  = 1'b0;

	// Read logic block
	always @ (posedge csi_clk or negedge csi_reset_n) begin
		if (!csi_reset_n) begin
			read_data_buf <= 32'b0;
		end
		else if (!avs_read_n) begin
			read_data_buf <= write_reg_buf[avs_address];
		end
		else begin
			read_data_buf <= read_data_buf;
		end
	end

	// Write logic block
	always @ (posedge csi_clk or negedge csi_reset_n) begin
		if (!csi_reset_n) begin
			write_reg_buf[SEC_CNT_DATA_BASE	+ 0] <= 32'b0;
			write_reg_buf[SEC_CNT_DATA_BASE	+ 1] <= 32'b0;
			write_reg_buf[SEC_CNT_DATA_BASE	+ 2] <= 32'b0;
			write_reg_buf[SEC_CNT_DATA_BASE	+ 3] <= 32'b0;
			write_reg_buf[SEC_CNT_DATA_BASE	+ 4] <= 32'b0;
			write_reg_buf[SEC_CNT_DATA_BASE	+ 5] <= 32'b0;

			write_reg_buf[NS_CNT_DATA_BASE	+ 0] <= 32'b0;
			write_reg_buf[NS_CNT_DATA_BASE	+ 1] <= 32'b0;
			write_reg_buf[NS_CNT_DATA_BASE	+ 2] <= 32'b0;

			write_reg_buf[CTRL_CNT_BASE		+ 0] <= 32'b0;
			write_reg_buf[CTRL_CNT_BASE		+ 1] <= 32'b0;
			write_reg_buf[CTRL_CNT_BASE		+ 2] <= 32'b0;

			write_reg_buf[TIME_ZONE_BASE	+ 0] <= 32'b0;

			write_reg_buf[LEAP_CNT_BASE		+ 0] <= 32'b0;
			write_reg_buf[LEAP_OCCUR_BASE	+ 0] <= 32'b0;
			write_reg_buf[LEAP_OCCUR_BASE	+ 1] <= 32'b0;
			write_reg_buf[LEAP_DCT_BASE		+ 0] <= 32'b0;

			write_reg_buf[DST_INGRESS_BASE	+ 0] <= 32'b0;
			write_reg_buf[DST_INGRESS_BASE	+ 1] <= 32'b0;
			write_reg_buf[DST_ENGRESS_BASE	+ 0] <= 32'b0;
			write_reg_buf[DST_ENGRESS_BASE	+ 1] <= 32'b0; 

			write_reg_buf[TIME_QUALITY_BASE	+ 0] <= 32'b0;
		end
		else begin
			write_reg_buf[avs_address] <= avs_writedata;
			if (avs_write_n == 0) begin
				write_refresh[avs_address] <= 1'b1;
			end
		end
	end

	// Refresh logic block
	always @ (posedge csi_clk or negedge csi_reset_n) begin
		if (!csi_reset_n) begin
			write_refresh <= 32'b0;
		end
		else if (io_update) begin
			write_refresh <= 32'b0;
		end
		else if (write_refresh[avs_address] == 1'b1) begin
			write_refresh[avs_address] <= 1'b0;
		end
	end

	// Update logic block
	always @ (posedge csi_clk or negedge csi_reset_n) begin
		if (!csi_reset_n) begin
			io_update <= 1'b0;
		end
		else begin
			if (io_update == 1'b0 && io_update_state == 2'b00 && coe_io_update_in == 1'b1) begin
				io_update_state <= 2'b01;
			end
			else if (io_update == 1'b0 && io_update_state == 2'b01 && coe_io_update_in == 1'b1) begin
				io_update_state <= 2'b10;
			end
			else if (io_update == 1'b0 && io_update_state == 2'b10 && coe_io_update_in == 1'b0) begin
				io_update_state <= 2'b00;
				io_update <= 1'b1;
			end
			else begin
				io_update_state <= 2'b00;
			end
		end
	end

endmodule

