module clock_gen (
	inclk0,
	c0,
	c1
);

	input	  inclk0;
	output	  c0;
	output	  c1;

	reg	  [1:0]	counter;

	always @(posedge inclk0) begin
		counter <= counter + 1;
		if (counter == 2'b00) begin
			c0 <= ~c0;
		end
		if (counter == 2'b01) begin
			c1 <= ~c1;
		end
	end

endmodule

module serial (rxd, txd, clk);

	input rxd;
	input clk;
	output txd;

	parameter [3:0] send1 = 3'b001, send2 = 3'b011, send3 = 3'b101, send4 = 3'b111,
			s1 = 3'b000, s2 = 3'b010, s3 = 3'b100, s4 = 3'b110;

	reg [3:0] present_state = s1;
	reg [3:0] next_state = s1;

	/* sender ports */
	reg [7:0] snd_data;
	reg snd_start;
	wire snd_busy;

	/* set sender port */
	async_transmitter snd(clk, snd_start, snd_data, txd, snd_busy);

	always @(posedge clk) begin
		present_state <= next_state;
	end

	always @(present_state, snd_busy) begin
		case (present_state)
			s1: begin
				/* start send @ */
				snd_data <= 8'b0100_0000;
				snd_start <= 1'b1;
				next_state <= send1;
			end
			s2: begin
				snd_start <= 1'b0;
				if (snd_busy == 1'b0)
					next_state <= s3;
			end
			send1: begin
				snd_data <= 8'b0011_0000;
				snd_start <= 1'b1;
				next_state <= send2;
			end
			s3: begin
				snd_start <= 1'b0;
				if (snd_busy == 1'b0)
					next_state <= s4;
			end
			send2: begin
				snd_data <= 8'b0010_1111;
				snd_start <= 1'b1;
				next_state <= send3;
			end
			s4: begin
				snd_start <= 1'b0;
				if (snd_busy == 1'b0)
					next_state <= s1;
			end
			send3: begin
				snd_data <= 8'b0001_0001;
				snd_start <= 1'b1;
				next_state <= send4;
			end
			send4: begin
				snd_start <= 1'b0;
				if (snd_busy == 1'b0)
					next_state <= s1;
			end
		endcase
	end
endmodule

module async_transmitter(clk, start, data, tx, busy);

	input clk;
	input start;
	input [7:0] data;
	output tx;
	output reg busy;

	reg [2:0] bit_count;
	reg [7:0] data_reg;

	assign tx = busy ? 1'b0 : data_reg[0];

	always @(posedge clk) begin
		if (start) begin
			data_reg <= data;
			bit_count <= 3'd0;
			busy <= 1'b1;
		end else if (bit_count < 3'd8) begin
			data_reg <= {data_reg[6:0], 1'b0};
			bit_count <= bit_count + 1;
		end else begin
			data_reg <= {data_reg[6:0], 1'b1};
			bit_count <= 3'd0;
			busy <= 1'b0;
		end
	end
endmodule

