module expanded_accu(
    input               clk         ,   
    input               rst_n       ,
    input       [3:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out
);

reg [7:0] accu_data;
reg [3:0] input_data;
reg [1:0] input_count;

expanded_adder adder(
    .in_data({accu_data, input_data}),
    .out_data(data_out)
);

always @(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        accu_data <= 10'b0;
        input_data <= 4'b0;
        input_count <= 2'b0;
        valid_b <= 1'b0;
    end else begin
        if(valid_a && ready_b) begin
            input_data <= data_in;
            input_count <= input_count + 1;
            if(input_count == 2'b11) begin
                accu_data <= accu_data + {8'b0, expanded_adder.out_data};
                input_count <= 2'b0;
                valid_b <= 1'b1;
            end
        end
        if(ready_a && valid_b) begin
            valid_b <= 1'b0;
        end
    end
end

assign ready_a = ~valid_b;

endmodule

