logic [3:0] d;

assign a = in_data[3:0];
assign b = in_data[7:4];
assign c = in_data[11:8];
assign d = in_data[15:12];

always @* begin
    out_data = {a, 4'b0} + {b, 4'b0} + {c, 4'b0} + {d, 4'b0};
end

endmodule

