module counter (
    input clk,
    input rst_n,
    input ce,
    input ctrl,
    output reg [3:0] count,
    output reg tc,
    output reg borrow
);

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        count <= 4'b0000;
        tc <= 1'b0;
        borrow <= 1'b0;
    end else begin
        if (ce) begin
            if (ctrl) begin
                count <= count + 1;
                if (count == 4'b1111) begin
                    tc <= 1'b1;
                end
            end else begin
                count <= count - 1;
                if (count == 4'b0000) begin
                    borrow <= 1'b1;
                end
            end
        end
    end
end

endmodule

