module next_power_of_2 (
    input [3:0] num,
    output reg [4:0] result
);

    always @(*) begin
        case(num)
            4'b0001: result = 5'b00001;
            4'b0010: result = 5'b00010;
            4'b0011: result = 5'b00100;
            4'b0100: result = 5'b01000;
            4'b0101: result = 5'b01000;
            4'b0110: result = 5'b01000;
            4'b0111: result = 5'b01000;
            4'b1000: result = 5'b1000;
            4'b1001: result = 5'b1000;
            4'b1010: result = 5'b1000;
            4'b1011: result = 5'b1000;
            4'b1100: result = 5'b1000;
            4'b1101: result = 5'b1000;
            4'b1110: result = 5'b1000;
            4'b1111: result = 5'b10000;
        endcase
    end

endmodule

module max_value (
    input [4:0] a,
    input [4:0] b,
    output reg [4:0] result
);

    wire [4:0] next_power;
    next_power_of_2 np2(.num(a + b), .result(next_power));
    ripple_carry_adder rca(.a(a), .b(b), .cin(1'b0), .sum(result), .cout());

    always @(*) begin
        if (a >= b) begin
            result = a;
        end else begin
            result = b;
        end

        if (next_power > result) begin
            result = next_power;
        end
    end

endmodule

