module xor_mux_shift (
    input clk,
    input areset,  // Async active-high reset to zero
    input load,
    input ena,
    input [2:0] sel,
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output reg [3:0] q,
    output reg xor_out
);

reg [3:0] shift_reg [3:0];
reg [1:0] sel_reg;
wire [3:0] mux_out;

// Multiplexer
mux_6to1 mux (
    .sel(sel),
    .in0(data0),
    .in1(data1),
    .in2(data2),
    .in3(data3),
    .in4(data4),
    .in5(data5),
    .out(mux_out)
);

// Shift register
always @(posedge clk) begin
    if (areset) begin
        shift_reg <= 4'b0;
        sel_reg <= 2'b0;
    end else if (load) begin
        shift_reg <= {mux_out, 4'b0};
        sel_reg <= 2'b0;
    end else if (ena) begin
        shift_reg <= {shift_reg[2:0], shift_reg[3]};
        sel_reg <= sel_reg + 1;
    end
end

// Output
assign q = shift_reg[0];
assign xor_out = q ^ mux_out;

endmodule

module combined_counter (
    input clk,
    input reset,
    input load,
    input up_down,
    input [3:0] data_in,
    input select_counter,
    input select_output,
    output reg [3:0] count_out,
    output reg [3:0] sum_out
);

reg [3:0] counter1;
reg [3:0] counter2;
reg [3:0] sum;

always @(posedge clk) begin
    if (reset) begin
        counter1 <= 4'b0;
        counter2 <= 4'b0;
        sum <= 4'b0;
    end else if (load) begin
        counter1 <= data_in;
        counter2 <= data_in;
    end else if (select_counter) begin
        if (up_down) begin
            if (counter2 == 4'b1111) begin
                counter2 <= 4'b0000;
            end else begin
                counter2 <= counter2 + 1;
            end
        end else begin
            if (counter2 == 4'b0000) begin
                counter2 <= 4'b1111;
            end else begin
                counter2 <= counter2 - 1;
            end
        end
    end else begin
        if (up_down) begin
            if (counter1 == 4'b1111) begin
                counter1 <= 4'b0000;
            end else begin
                counter1 <= counter1 + 1;
            end
        end else begin
            if (counter1 == 4'b0000) begin
                counter1 <= 4'b1111;
            end else begin
                counter1 <= counter1 - 1;
            end
        end
    end

    sum <= counter1 + counter2;

    if (select_output) begin
        count_out <= select_counter ? counter2 : counter1;
        sum_out <= sum;
    end else begin
        count_out <= sum;
        sum_out <= 4'b0;
    end
end

endmodule

module mux4x1 (out, in0, in1, in2, in3, sel0, sel1);

  output out;
