  S_AXI_BREADY,
  S_AXI_ARID,
  S_AXI_ARADDR,
  S_AXI_ARLEN,
  S_AXI_ARSIZE,
  S_AXI_ARBURST,
  S_AXI_ARVALID,
  S_AXI_ARREADY,
  S_AXI_RID,
  S_AXI_RDATA,
  S_AXI_RRESP,
  S_AXI_RLAST,
  S_AXI_RVALID,
  S_AXI_RREADY
);

input clka;
input [0 : 0] wea;
input [6 : 0] addra;
input [7 : 0] dina;
input clkb;
input [6 : 0] addrb;
output [7 : 0] doutb;

input [3:0] S_AXI_AWID;
input [31:0] S_AXI_AWADDR;
input [7:0] S_AXI_AWLEN;
input [2:0] S_AXI_AWSIZE;
input [1:0] S_AXI_AWBURST;
input S_AXI_AWVALID;
output S_AXI_AWREADY;
input [31:0] S_AXI_WDATA;
input [3:0] S_AXI_WSTRB;
input S_AXI_WLAST;
input S_AXI_WVALID;
output S_AXI_WREADY;
output [3:0] S_AXI_BID;
output [1:0] S_AXI_BRESP;
output S_AXI_BVALID;
input S_AXI_BREADY;
input [3:0] S_AXI_ARID;
input [31:0] S_AXI_ARADDR;
input [7:0] S_AXI_ARLEN;
input [2:0] S_AXI_ARSIZE;
input [1:0] S_AXI_ARBURST;
input S_AXI_ARVALID;
output S_AXI_ARREADY;
output [3:0] S_AXI_RID;
output [31:0] S_AXI_RDATA;
output [1:0] S_AXI_RRESP;
output S_AXI_RLAST;
output S_AXI_RVALID;
input S_AXI_RREADY;

reg [7:0] memory [0:127];
reg [7:0] doutb_reg;
reg [1:0] S_AXI_BRESP_reg;
reg S_AXI_BVALID_reg;
reg S_AXI_WREADY_reg;
reg S_AXI_RVALID_reg;
reg S_AXI_RLAST_reg;
reg S_AXI_ARREADY_reg;

integer i;

// AXI write address ready
assign S_AXI_AWREADY = 1;

// AXI write data ready
assign S_AXI_WREADY = S_AXI_WVALID && !S_AXI_WLAST && !S_AXI_BVALID_reg;

// AXI write response valid
assign S_AXI_BVALID = S_AXI_BVALID_reg;

// AXI read address ready
assign S_AXI_ARREADY = 1;

// AXI read data valid
assign S_AXI_RVALID = S_AXI_RVALID_reg;

// AXI read last beat
assign S_AXI_RLAST = S_AXI_RLAST_reg;

// AXI read response ID
assign S_AXI_RID = S_AXI_ARID;

// AXI write response ID
assign S_AXI_BID = S_AXI_AWID;

// AXI write response
assign S_AXI_BRESP = S_AXI_BRESP_reg;

always @(posedge clka) begin
  // Write operation
  if (wea == 1'b1) begin
    memory[addra] <= dina;
  end

  // Read operation
  doutb_reg <= memory[addrb];
end

always @(posedge clkb) begin
  // AXI write response
  if (S_AXI_AWVALID && S_AXI_WVALID && S_AXI_WLAST && S_AXI_WREADY_reg) begin
    S_AXI_BRESP_reg <= 2'b00;
    S_AXI_BVALID_reg <= 1'b1;
  end

  // AXI read response
  if (S_AXI_ARVALID && S_AXI_ARREADY_reg && !S_AXI_RVALID_reg) begin
    S_AXI_RDATA <= memory[S_AXI_ARADDR];
    S_AXI_RLAST_reg <= (S_AXI_ARLEN == 1);
    S_AXI_RRESP <= 2'b00;
    S_AXI_RVALID_reg <= 1'b1;
  end
end

always @(posedge clkb) begin
  // AXI write data ready
  if (S_AXI_AWVALID && S_AXI_WVALID && !S_AXI_WLAST && !S_AXI_WREADY_reg) begin
    S_AXI_WREADY_reg <= 1'b1;
