module top_module (
    input clk,
    input reset,       // Synchronous active-high reset
    input select,      // Select input to choose between up_down_counter and shift_register
    input [3:0] data_in, // Input to up_down_counter and shift_register
    input [3:0] max_count, // Max count limit for up_down_counter
    input load,        // Parallel load input for up_down_counter and shift_register
    output [3:0] q     // Output sum of active module's value and functional module's output
);

    reg [3:0] up_down_counter_out;
    reg [3:0] shift_register_out;
    wire [3:0] functional_out;

    up_down_counter up_down_counter_inst (
        .clk(clk),
        .reset(reset),
        .data_in(data_in),
        .max_count(max_count),
        .load(load),
        .q(up_down_counter_out)
    );

    shift_register shift_register_inst (
        .clk(clk),
        .reset(reset),
        .data_in(data_in),
        .load(load),
        .q(shift_register_out)
    );

    functional_module functional_inst (
        .up_down_counter_out(up_down_counter_out),
        .shift_register_out(shift_register_out),
        .sum_out(functional_out)
    );

    always @(posedge clk, posedge reset) begin
        if (reset) begin
            q <= 4'b0;
        end else begin
            if (select) begin
                q <= functional_out + shift_register_out;
            end else begin
                q <= functional_out + up_down_counter_out;
            end
        end
    end

endmodule

