module shift_reg_counter_xor_mux (
    input clk,
    input reset,
    input [7:0] d,
    output [3:0] counter_out,
    output reg shift_reg_out,
    output xor_out
);

reg [7:0] shift_reg;
reg [3:0] counter;
reg up_down;

always @(posedge clk) begin
    if (reset) begin
        shift_reg <= 8'b00110100;
        counter <= 4'b0000;
        up_down <= 1'b0;
    end else begin
        if (up_down) begin
            counter <= counter - 1;
            if (counter == 4'b0000) begin
                up_down <= 1'b0;
            end
        end else begin
            counter <= counter + 1;
            if (counter == 4'b1111) begin
                up_down <= 1'b1;
            end
        end
        shift_reg <= {shift_reg[6:0], d};
    end
end

assign xor_out = shift_reg ^ counter;

assign shift_reg_out = (up_down) ? shift_reg[0] : shift_reg[7];

assign counter_out = counter;

endmodule

