            if (i < 8) begin
                if (b[i]) begin
                    sum <= sum + (DOUT[(i+1)*LC_RF_DATA_WIDTH-1:i*LC_RF_DATA_WIDTH] << i);
                end
                i <= i + 1;
            end else begin
                result <= sum;
            end
            LOAD <= {LOAD[RF_DEPTH-2:0], 1'b1};
        end
    end

endmodule

