module ripple_carry_adder (
    input clk,
    input reset,
    input [3:0] A,
    input [3:0] B,
    output [3:0] OUT
);

reg [3:0] sum;
reg carry;

always @(posedge clk) begin
    if (reset) begin
        sum <= 4'b0;
        carry <= 1'b0;
    end else begin
        {carry, sum} <= A + B + carry;
    end
end

assign OUT = sum;

endmodule

