module top_module (
    input a,
    input b,
    input [7:0] in,
    output reg out_func_module
);

    // XOR gate
    always @* begin
        out_xor_gate = a ^ b;
    end

    // Priority encoder
    always @* begin
        if (in[7] == 1) begin
            out_priority_encoder = 7;
        end else if (in[6] == 1) begin
            out_priority_encoder = 6;
        end else if (in[5] == 1) begin
            out_priority_encoder = 5;
        end else if (in[4] == 1) begin
            out_priority_encoder = 4;
        end else if (in[3] == 1) begin
            out_priority_encoder = 3;
        end else if (in[2] == 1) begin
            out_priority_encoder = 2;
        end else if (in[1] == 1) begin
            out_priority_encoder = 1;
        end else if (in[0] == 1) begin
            out_priority_encoder = 0;
        end else begin
            out_priority_encoder = 0;
        end
    end

    // Functional module
    always @* begin
        if (out_priority_encoder == 0) begin
            out_func_module = in ^ 0;
        end else begin
            out_func_module = in ^ out_priority_encoder;
        end
    end

    // Outputs
    output reg out_xor_gate;
    output reg [2:0] out_priority_encoder;

endmodule

