    input dir,
    input [2:0] in,
    output reg Y0,
    output reg Y1,
    output reg Y2,
    output reg Y3,
    output reg Y4,
    output reg Y5,
    output reg Y6,
    output reg Y7
);

reg [2:0] shift_reg;

always @(posedge clk) begin
    if (dir == 1'b0) begin // shift right
        shift_reg[0] <= in[2];
        shift_reg[1] <= shift_reg[0];
        shift_reg[2] <= shift_reg[1];
    end else begin // shift left
        shift_reg[2] <= in[0];
        shift_reg[1] <= shift_reg[2];
        shift_reg[0] <= shift_reg[1];
    end
end

assign {Y7, Y6, Y5, Y4, Y3, Y2, Y1, Y0} = ~(8'b00000001 << shift_reg);

