module axi_tap (
    input clk,
    input rst,
    input [DATA_WIDTH-1:0] tap_axis_tdata,
    input [KEEP_WIDTH-1:0] tap_axis_tkeep,
    input tap_axis_tvalid,
    output tap_axis_tready,
    input tap_axis_tlast,
    input [ID_WIDTH-1:0] tap_axis_tid,
    input [DEST_WIDTH-1:0] tap_axis_tdest,
    input [USER_WIDTH-1:0] tap_axis_tuser,
    output reg [DATA_WIDTH-1:0] m_axis_tdata,
    output reg [KEEP_WIDTH-1:0] m_axis_tkeep,
    output reg m_axis_tvalid,
    input m_axis_tready,
    output reg m_axis_tlast,
    output reg [ID_WIDTH-1:0] m_axis_tid,
    output reg [DEST_WIDTH-1:0] m_axis_tdest,
    output reg [USER_WIDTH-1:0] m_axis_tuser
);

// Parameters
parameter DATA_WIDTH = 8;
parameter KEEP_ENABLE = (DATA_WIDTH>8);
parameter KEEP_WIDTH = (DATA_WIDTH/8);
parameter ID_ENABLE = 1;
parameter ID_WIDTH = 8;
parameter DEST_ENABLE = 1;
parameter DEST_WIDTH = 8;
parameter USER_ENABLE = 1;
parameter USER_WIDTH = 1;
parameter USER_BAD_FRAME_VALUE = 1'b1;
parameter USER_BAD_FRAME_MASK = 1'b1;

// Internal signals
reg [DATA_WIDTH-1:0] tap_data_reg;
reg [KEEP_WIDTH-1:0] tap_keep_reg;
reg tap_valid_reg;
reg tap_last_reg;
reg [ID_WIDTH-1:0] tap_id_reg;
reg [DEST_WIDTH-1:0] tap_dest_reg;
reg [USER_WIDTH-1:0] tap_user_reg;

// Bad frame detection
reg bad_frame;
always @(posedge clk) begin
    if (rst) begin
        bad_frame <= 0;
    end else if (tap_valid_reg && !tap_last_reg && !m_axis_tready) begin
        bad_frame <= 1;
    end else if (tap_valid_reg && tap_last_reg && !m_axis_tvalid) begin
        bad_frame <= 1;
    end else if (tap_valid_reg && tap_last_reg && m_axis_tvalid && (tap_user_reg & USER_BAD_FRAME_MASK) == USER_BAD_FRAME_VALUE) begin
        bad_frame <= 1;
    end else begin
        bad_frame <= 0;
    end
end

// AXI tap
axis_tap #(
    .DATA_WIDTH(DATA_WIDTH),
    .KEEP_ENABLE(KEEP_ENABLE),
    .KEEP_WIDTH(KEEP_WIDTH),
    .ID_ENABLE(ID_ENABLE),
    .ID_WIDTH(ID_WIDTH),
    .DEST_ENABLE(DEST_ENABLE),
    .DEST_WIDTH(DEST_WIDTH),
    .USER_ENABLE(USER_ENABLE),
    .USER_WIDTH(USER_WIDTH),
    .USER_BAD_FRAME_VALUE(USER_BAD_FRAME_VALUE),
    .USER_BAD_FRAME_MASK(USER_BAD_FRAME_MASK)
)
UUT (
    .clk(clk),
    .rst(rst),
    // AXI tap
    .tap_axis_tdata(tap_data_reg),
    .tap_axis_tkeep(tap_keep_reg),
    .tap_axis_tvalid(tap_valid_reg),
    .tap_axis_tready(tap_axis_tready),
    .tap_axis_tlast(tap_last_reg),
    .tap_axis_tid(tap_id_reg),
    .tap_axis_tdest(tap_dest_reg),
    .tap_axis_tuser(tap_user_reg),
    // AXI output
    .m_axis_tdata(m_axis_tdata),
    .m_axis_tkeep(m_axis_tkeep),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),
    .m_axis_tlast(m_axis_tlast),
    .m_axis_tid(m_axis_tid),
    .m_axis_tdest(m_axis_tdest),
    .m_axis_tuser(m_axis_tuser)
);

// Tap into input signals and modify user value
always @(posedge clk) begin
    if (rst) begin
        tap_data_reg <= 0;
        tap_keep_reg <= 0;
        tap_valid_reg <= 0;
        tap_last_reg <= 0;
        tap_id_reg <= 0;
        tap_dest_reg <= 0;
        tap_user_reg <= 0;
    end else begin
        if (current_test == 0) begin
            // Send valid frame with user value of 0
            tap_data_reg <= 8'hFF;
            tap_keep_reg <= {KEEP_WIDTH{1'b1}};
            tap_valid_reg <= 1;
            tap_last_reg <= 0;
            tap_id_reg <= 8'hAA;
            tap_dest_reg <= 8'hBB;
            tap_user_reg <= 1'b0;
        end else if (current_test == 1) begin
            // Tap into input signals and modify user value
            tap_data_reg <= tap_axis_tdata;
            tap_keep_reg <= tap_axis_tkeep;
            tap_valid_reg <= tap_axis_tvalid;
            tap_last_reg <= tap_axis_tlast;
            tap_id_reg <= tap_axis_tid;
            tap_dest_reg <= tap_axis_tdest;
            tap_user_reg <= 1'b1;
        end else if (current_test == 2) begin
            // Send valid frame with user value of 0
            tap_data_reg <= 8'hFF;
            tap_keep_reg <= {KEEP_WIDTH{1'b1}};
            tap_valid_reg <= 1;
            tap_last_reg <= 1;
            tap_id_reg <= 8'hAA;
            tap_dest_reg <= 8'hBB;
            tap_user_reg <= 1'b0;
        end
    end
end

// Output signals match input signals, except for modified user value
always @(posedge clk) begin
    if (rst) begin
        m_axis_tdata <= 0;
        m_axis_tkeep <= 0;
        m_axis_tvalid <= 0;
        m_axis_tlast <= 0;
        m_axis_tid <= 0;
        m_axis_tdest <= 0;
        m_axis_tuser <= 0;
    end else begin
        if (tap_axis_tvalid && m_axis_tready) begin
            m_axis_tdata <= tap_axis_tdata;
            m_axis_tkeep <= tap_axis_tkeep;
            m_axis_tvalid <= tap_axis_tvalid;
            m_axis_tlast <= tap_axis_tlast;
            m_axis_tid <= tap_axis_tid;
            m_axis_tdest <= tap_axis_tdest;
            m_axis_tuser <= bad_frame ? USER_BAD_FRAME_VALUE : tap_axis_tuser;
        end
    end
end

endmodule

module control_logic(
  input clock, execute,
  input [7:0] opcode,
  output [3:0] wrtrigmask,
  output [3:0] wrtrigval,
  output [3:0] wrtrigcfg,
  output wrspeed,
  output wrsize,
  output wrFlags,
  output wrTrigSelect,
  output wrTrigChain,
  output finish_now,
  output arm_basic,
  output arm_adv,
  output resetCmd
);

reg resetCmd, next_resetCmd;
reg arm_basic, next_arm_basic;
reg arm_adv, next_arm_adv;
reg [3:0] wrtrigmask, next_wrtrigmask;
reg [3:0] wrtrigval, next_wrtrigval;
reg [3:0] wrtrigcfg, next_wrtrigcfg;
reg wrspeed, next_wrspeed;
reg wrsize, next_wrsize;
reg wrFlags, next_wrFlags;
reg finish_now, next_finish_now;
reg wrTrigSelect, next_wrTrigSelect;
reg wrTrigChain, next_wrTrigChain;
reg dly_execute, next_dly_execute;

always @(posedge clock) begin
  resetCmd <= next_resetCmd;
  arm_basic <= next_arm_basic;
  arm_adv <= next_arm_adv;
  wrtrigmask <= next_wrtrigmask;
  wrtrigval <= next_wrtrigval;
  wrtrigcfg <= next_wrtrigcfg;
  wrspeed <= next_wrspeed;
  wrsize <= next_wrsize;
  wrFlags <= next_wrFlags;
  finish_now <= next_finish_now;
  wrTrigSelect <= next_wrTrigSelect;
  wrTrigChain <= next_wrTrigChain;
  dly_execute <= next_dly_execute;
end

always @* begin
  #1;
  next_resetCmd = 1'b0;
  next_arm_basic = 1'b0;
  next_arm_adv = 1'b0;
  next_wrtrigmask = 4'b0000;
  next_wrtrigval = 4'b0000;
  next_wrtrigcfg = 4'b0000;
  next_wrspeed = 1'b0;
  next_wrsize = 1'b0;
  next_wrFlags = 1'b0;
  next_finish_now = 1'b0;
  next_wrTrigSelect = 1'b0;
  next_wrTrigChain = 1'b0;
  next_dly_execute = execute;

  if (execute & !dly_execute) begin
    case(opcode)
      // short commands
      8'h00 : next_resetCmd = 1'b1;
      8'h01 : next_arm_basic = 1'b1;
      8'h02 :;// Query ID (decoded in spi_slave.v)
      8'h03 :;// Selftest (reserved)
      8'h04 :;// Query Meta Data (decoded in spi_slave.v)
      8'h05 : next_finish_now = 1'b1;
      8'h06 :;// Query input data (decoded in spi_slave.v)
      8'h0F : next_arm_adv = 1'b1;
      8'h11 :;// XON (reserved)
      8'h13 :;// XOFF (reserved)

      // long commands
      8'h80 : next_wrspeed = 1'b1;
      8'h81 : next_wrsize = 1'b1;
      8'h82 : next_wrFlags = 1'b1;

      8'h9E : next_wrTrigSelect = 1'b1;
      8'h9F : next_wrTrigChain = 1'b1;

      8'hC0 : next_wrtrigmask[0] = 1'b1;
      8'hC1 : next_wrtrigval[0] = 1'b1;
      8'hC2 : next_wrtrigcfg[0] = 1'b1;
      8'hC4 : next_wrtrigmask[1] = 1'b1;
      8'hC5 : next_wrtrigval[1] = 1'b1;
      8'hC6 : next_wrtrigcfg[1] = 1'b1;
      8'hC8 : next_wrtrigmask[2] = 1'b1;
      8'hC9 : next_wrtrigval[2] = 1'b1;
      8'hCA : next_wrtrigcfg[2] = 1'b1;
      8'hCC : next_wrtrigmask[3] = 1'b1;
      8'hCD : next_wrtrigval[3] = 1'b1;
      8'hCE : next_wrtrigcfg[3] = 1'b1;
    endcase
  end
end

