module fsm_pattern_detection (
  input clk,
  input reset,
  input data,
  output reg pattern_detected
);

  parameter S0 = 2'b00, S1 = 2'b01, S2 = 2'b10, S3 = 2'b11;
  reg [1:0] state, next_state;

  always @(posedge clk) begin
    if (reset) begin
      state <= S0;
      pattern_detected <= 1'b0;
    end
    else begin
      state <= next_state;
      pattern_detected <= 1'b0;
      case (state)
        S0: begin
          if (data == 1'b1)
            next_state = S1;
          else
            next_state = S0;
        end
        S1: begin
          if (data == 1'b0)
            next_state = S2;
          else
            next_state = S0;
        end
        S2: begin
          if (data == 1'b1)
            next_state = S3;
          else
            next_state = S0;
        end
        S3: begin
          pattern_detected <= 1'b1;
          next_state = S0;
        end
      endcase
    end
  end
endmodule

