        A: begin
          if (in1 == 1'b0 && in2 == 1'b0) begin
            next_state = C;
            out <= 0;
          end else if (in1 == 1'b0 && in2 == 1'b1) begin
            next_state = B;
            out <= 1;
          end else begin
            next_state = A;
            out <= 0;
