  always @(posedge feedback_clk) begin
    delay_line_out <= delay_reg[7] ? feedback_clk : delay_line_out;
    delay_line_out <= delay_reg[6] ? delay_line_out : feedback_clk;
    delay_line_out <= delay_reg[5] ? delay_line_out : feedback_clk;
    delay_line_out <= delay_reg[4] ? delay_line_out : feedback_clk;
    delay_line_out <= delay_reg[3] ? delay_line_out : feedback_clk;
    delay_line_out <= delay_reg[2] ? delay_line_out : feedback_clk;
    delay_line_out <= delay_reg[1] ? delay_line_out : feedback_clk;
    delay_line_out <= delay_reg[0] ? delay_line_out : feedback_clk;

    phase_detector_out <= delay_line_out ^ feedback_clk;

    error_filtered_next <= (error_filtered + error) >> 1;
    error_integrated_next <= error_integrated + error_filtered_next;

    delay_next <= delay_reg + error_integrated_next;

    out_clk_next <= delay_reg[7] ? delay_line_out : out_clk_reg;
    out_clk_next <= delay_reg[6] ? out_clk_reg : delay_line_out;
    out_clk_next <= delay_reg[5] ? out_clk_reg : delay_line_out;
    out_clk_next <= delay_reg[4] ? out_clk_reg : delay_line_out;
    out_clk_next <= delay_reg[3] ? out_clk_reg : delay_line_out;
    out_clk_next <= delay_reg[2] ? out_clk_reg : delay_line_out;
    out_clk_next <= delay_reg[1] ? out_clk_reg : delay_line_out;
    out_clk_next <= delay_reg[0] ? out_clk_reg : delay_line_out;
  end

  assign out_clk = out_clk_reg;

endmodule

module norflash32 #(
    parameter adr_width = 21 /* in 32-bit words */
) (
    input sys_clk,
    input sys_rst,

    input [31:0] wb_adr_i,
    output reg [31:0] wb_dat_o,
    input wb_stb_i,
    input wb_cyc_i,
    output reg wb_ack_o,

    /* 32-bit granularity */
    output reg [adr_width-1:0] flash_adr,
    input [31:0] flash_d
);

reg [31:0] reg_wb_adr_i;
reg [3:0] counter;

always @(posedge sys_clk) begin
    /* Use IOB registers to prevent glitches on address lines */
    if(wb_cyc_i & wb_stb_i) /* register only when needed to reduce EMI */
        reg_wb_adr_i <= wb_adr_i[adr_width+1:2];
    flash_adr <= reg_wb_adr_i;

    wb_dat_o <= flash_d;
end

/*
 * Timing of the ML401 flash chips is 110ns.
 * By using 16 cycles at 100MHz and counting
 * the I/O registers delay we have some margins
 * and simple hardware for generating WB ack.
 */
always @(posedge sys_clk) begin
    if(sys_rst)
        counter <= 4'd1;
    else begin
        if(wb_cyc_i & wb_stb_i)
            counter <= counter + 4'd1;
        else
            counter <= 4'd1;
        wb_ack_o <= (counter == 4'd16);
    end
end

endmodule

module top_module (
    input clk,
    input reset,
    input [31:0] in,
    output reg out
);

    // Instantiate the transition detector module
    transition_detector td (
        .clk(clk),
        .reset(reset),
        .in(in),
        .transition_detected(transition_detected)
    );

    // Instantiate the 4-bit comparator module
    four_bit_comparator fbc (
        .a(a),
        .b(b),
        .equal(equal)
    );

    // Instantiate the functional module
    functional_module fm (
        .clk(clk),
        .reset(reset),
        .in(in),
        .equal(equal),
        .out(out)
    );

    // Declare signals
    reg [31:0] a;
    reg [31:0] b;
    reg equal;
    reg transition_detected;

    // Assign a and b based on the 4-bit window
    always @ (posedge clk) begin
        if (reset) begin
            a <= 0;
            b <= 0;
        end else if (transition_detected) begin
            a <= in;
            b <= {b[27:0], in[31:28]};
        end else begin
            a <= a;
            b <= b;
        end
    end

endmodule


module transition_detector (
    input clk,
    input reset,
    input [31:0] in,
    output reg transition_detected
);

    reg [31:0] prev_in;

    always @ (posedge clk) begin
        if (reset) begin
            prev_in <= 0;
            transition_detected <= 0;
        end else begin
            if (in == 0 && prev_in == 1) begin
                transition_detected <= 1;
            end else begin
                transition_detected <= 0;
            end
            prev_in <= in;
        end
    end

endmodule


module four_bit_comparator (
    input [3:0] a,
    input [3:0] b,
    output reg equal
);

    always @ (*) begin
        if (a == b) begin
            equal = 1;
        end else begin
            equal = 0;
        end
    end

endmodule


module functional_module (
    input clk,
    input reset,
    input [31:0] in,
    input equal,
    output reg out
);

    reg [127:0] pattern = 128'h0000FFFF0000FFFF0000FFFF0000FFFF;
    reg [31:0] pattern_index;

    always @ (posedge clk) begin
        if (reset) begin
            out <= 0;
            pattern_index <= 0;
        end else begin
            if (equal) begin
                pattern_index <= pattern_index + 1;
                if (pattern_index == 31) begin
                    out <= 1;
                end
            end else begin
                pattern_index <= 0;
                out <= 0;
            end
        end
    end

endmodule

module cla_32(a, b, c_in, g_out, p_out, s, c_out);
