module fsm_3bit_sequence_detection (
  input clk,
  input reset,
  input A,
  input B,
  input C,
  output reg match
);

  // Define states
  localparam IDLE = 2'b00;
  localparam S0 = 2'b01;
  localparam S1 = 2'b10;

  // Define inputs
  reg [1:0] state;
  reg [2:0] input_buffer;

  // State transition and output logic
  always @(posedge clk) begin
    if (reset) begin
      state <= IDLE;
      input_buffer <= 3'b0;
      match <= 1'b0;
    end else begin
      case (state)
        IDLE: begin
          if (A) begin
            input_buffer <= {input_buffer[1:0], A};
            state <= S0;
          end
        end
        S0: begin
          if (B) begin
            input_buffer <= {input_buffer[1:0], B};
            state <= S1;
          end else if (!A) begin
            input_buffer <= 3'b0;
            state <= IDLE;
          end
        end
        S1: begin
          if (C) begin
            input_buffer <= {input_buffer[1:0], C};
            state <= IDLE;
            match <= 1'b1;
          end else if (!B) begin
            input_buffer <= 3'b0;
            state <= IDLE;
          end
        end
      endcase
    end
  end
endmodule

module cycloneii_scale_cntr (
  input clk,
  input reset,
  input [31:0] high,
  input [31:0] low,
  input [31:0] initial_value,
  input [8*6:1] mode,
  input [31:0] ph_tap,
  output reg cout
);

  reg [31:0] count;
  reg [31:0] output_shift_count;
  reg tmp_cout;
  reg first_rising_edge;
  reg clk_last_value;
  reg init;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      count <= 1;
      output_shift_count <= 1;
      tmp_cout <= 0;
      first_rising_edge <= 0;
    end else begin
      if (init !== 1'b1) begin
        clk_last_value <= 0;
        init <= 1'b1;
      end
      if (clk_last_value !== clk) begin
        if (mode == "   off") begin
          tmp_cout <= 0;
        end else if (mode == "bypass") begin
          tmp_cout <= clk;
          first_rising_edge <= 1;
        end else if (first_rising_edge == 0) begin
          if (clk == 1) begin
            if (output_shift_count == initial_value) begin
              tmp_cout <= clk;
              first_rising_edge <= 1;
            end else begin
              output_shift_count <= output_shift_count + 1;
            end
          end
        end else if (output_shift_count < initial_value) begin
          if (clk == 1) begin
            output_shift_count <= output_shift_count + 1;
          end
        end else begin
          count <= count + 1;
          if (mode == "  even" && (count == (high*2) + 1)) begin
            tmp_cout <= 0;
          end else if (mode == "   odd" && (count == (high*2))) begin
            tmp_cout <= 0;
          end else if (count == (high + low)*2 + 1) begin
            tmp_cout <= 1;
            count <= 1;
          end
        end
        clk_last_value <= clk;
      end
    end
    cout <= tmp_cout;
  end

endmodule

