module full_adder(
    input A,
    input B,
    input CIN,
    output SUM,
    output COUT
);

wire X1, X2, X3;

assign X1 = A ^ B;
assign X2 = X1 ^ CIN;
assign SUM = X2;
assign X3 = A & B;
assign COUT = X3 | (X1 & CIN);

endmodule

module dual_clock_fifo (
    // Inputs
    input clk_stream_in,
    input reset_stream_in,
    input clk_stream_out,
    input reset_stream_out,
    input [28:0] stream_in_data,
    input stream_in_startofpacket,
    input stream_in_endofpacket,
    input [0:0] stream_in_empty,
    input stream_in_valid,
    input stream_out_ready,
    // Outputs
    output stream_in_ready,
    output [28:0] stream_out_data,
    output stream_out_startofpacket,
    output stream_out_endofpacket,
    output [0:0] stream_out_empty,
    output stream_out_valid
);

parameter DW = 29; // Data width
parameter EW = 1; // Empty width
parameter NUM_WORDS = 128; // Maximum number of words in FIFO

// Internal signals
reg [DW-1:0] buffer [0:NUM_WORDS-1];
reg [7:0] wr_ptr = 0; // Write pointer
reg [7:0] rd_ptr = 0; // Read pointer
reg [7:0] num_words = 0; // Number of words in FIFO
wire [7:0] next_wr_ptr = wr_ptr + 1; // Next write pointer
wire [7:0] next_rd_ptr = rd_ptr + 1; // Next read pointer
wire [7:0] next_num_words = num_words + stream_in_valid - stream_out_ready; // Next number of words in FIFO

// Synchronize input signals to write clock domain
reg [28:0] sync_stream_in_data;
reg sync_stream_in_startofpacket;
reg sync_stream_in_endofpacket;
reg [0:0] sync_stream_in_empty;
reg sync_stream_in_valid;
always @(posedge clk_stream_in or posedge reset_stream_in) begin
    if (reset_stream_in) begin
        sync_stream_in_data <= 0;
        sync_stream_in_startofpacket <= 0;
        sync_stream_in_endofpacket <= 0;
        sync_stream_in_empty <= 0;
        sync_stream_in_valid <= 0;
    end else begin
        sync_stream_in_data <= stream_in_data;
        sync_stream_in_startofpacket <= stream_in_startofpacket;
        sync_stream_in_endofpacket <= stream_in_endofpacket;
        sync_stream_in_empty <= stream_in_empty;
        sync_stream_in_valid <= stream_in_valid;
    end
end

// Synchronize output signals to read clock domain
reg [28:0] sync_stream_out_data;
reg sync_stream_out_startofpacket;
reg sync_stream_out_endofpacket;
reg [0:0] sync_stream_out_empty;
reg sync_stream_out_valid;
always @(posedge clk_stream_out or posedge reset_stream_out) begin
    if (reset_stream_out) begin
        sync_stream_out_data <= 0;
        sync_stream_out_startofpacket <= 0;
        sync_stream_out_endofpacket <= 0;
        sync_stream_out_empty <= 1;
        sync_stream_out_valid <= 0;
    end else begin
        sync_stream_out_data <= buffer[rd_ptr];
        sync_stream_out_startofpacket <= (rd_ptr == 0) ? sync_stream_in_startofpacket : 0;
        sync_stream_out_endofpacket <= (rd_ptr == num_words-1) ? sync_stream_in_endofpacket : 0;
        sync_stream_out_empty <= (num_words == 0);
        sync_stream_out_valid <= (num_words > 0);
    end
end

// Write data to FIFO buffer
always @(posedge clk_stream_in) begin
    if (stream_in_valid && stream_in_ready && (num_words < NUM_WORDS)) begin
        buffer[wr_ptr] <= sync_stream_in_data;
        wr_ptr <= next_wr_ptr;
        num_words <= next_num_words;
    end
end

// Read data from FIFO buffer
always @(posedge clk_stream_out) begin
    if (stream_out_ready && (num_words > 0)) begin
        rd_ptr <= next_rd_ptr;
        num_words <= next_num_words;
    end
end

// Assign output signals
assign stream_in_ready = (num_words < NUM_WORDS);
assign stream_out_data = sync_stream_out_data;
assign stream_out_startofpacket = sync_stream_out_startofpacket;
assign stream_out_endofpacket = sync_stream_out_endofpacket;
assign stream_out_empty = sync_stream_out_empty;
assign stream_out_valid = sync_stream_out_valid;

endmodule

module adder_subtractor(A, B, C, S);
