module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] adder_in1, // 8-bit input 1 for the adder
    input [7:0] adder_in2, // 8-bit input 2 for the adder
    input [3:0] mult_in1, // 4-bit input 1 for the multiplier
    input [3:0] mult_in2, // 4-bit input 2 for the multiplier
    input select, // Select input to choose between adder and multiplier
    output [7:0] adder_out, // 8-bit output from the adder
    output [3:0] mult_out, // 4-bit output from the multiplier
    output [7:0] final_out // 8-bit final output from the additional functional module
);

// Instantiate the adder module
adder adder_inst(
    .in1(adder_in1),
    .in2(adder_in2),
    .out(adder_out)
);

// Instantiate the multiplier module
multiplier mult_inst(
    .in1(mult_in1),
    .in2(mult_in2),
    .out(mult_out)
);

// Control logic to choose between adder and multiplier
always @ (posedge clk) begin
    if (reset) begin
        adder_out <= 8'b0;
        mult_out <= 4'b0;
    end else begin
        if (select) begin
            adder_out <= adder_inst.out;
            mult_out <= 4'b0;
        end else begin
            adder_out <= 8'b0;
            mult_out <= mult_inst.out;
        end
    end
end

// Additional functional module to perform bitwise OR operation
assign final_out = adder_out | mult_out;

endmodule

