module memory_controller(
    input wire [63:0] addr,
    output reg is_mem_addr,
    output reg is_IO_addr,
    output reg is_near_mem_IO_addr
);

    // Define memory map ranges
    localparam BOOT_ROM_BASE = 64'h0000000000001000;
    localparam BOOT_ROM_SIZE = 64'h0000000000001000;
    localparam BOOT_ROM_LIM = 64'd8192;
    localparam MAIN_MEM_BASE = 64'h0000000080000000;
    localparam MAIN_MEM_SIZE = 64'h0000000010000000;
    localparam MAIN_MEM_LIM = 64'h0000000090000000;
    localparam IO_MEM_BASE_1 = 64'h0000000002000000;
    localparam IO_MEM_SIZE_1 = 64'h000000000000C000;
    localparam IO_MEM_LIM_1 = 64'd33603584;
    localparam IO_MEM_BASE_2 = 64'h00000000C0000000;
    localparam IO_MEM_SIZE_2 = 64'h0000000000000080;
    localparam IO_MEM_LIM_2 = 64'h00000000C0000080;
    localparam PLIC_BASE = 64'h000000000C000000;
    localparam PLIC_SIZE = 64'h0000000000400000;
    localparam PLIC_LIM = 64'd205520896;
    localparam TCM_BASE = 64'h0;
    localparam TCM_SIZE = 64'd0;
    localparam TCM_LIM = 64'd0;

    // Check if address is for boot ROM
    always @(*) begin
        if (addr >= BOOT_ROM_BASE && addr < BOOT_ROM_BASE + BOOT_ROM_SIZE) begin
            is_mem_addr = 1'b0;
            is_IO_addr = 1'b0;
            is_near_mem_IO_addr = 1'b0;
        end
    end

    // Check if address is for main memory
    always @(*) begin
        if (addr >= MAIN_MEM_BASE && addr < MAIN_MEM_LIM) begin
            is_mem_addr = 1'b1;
            is_IO_addr = 1'b0;
            is_near_mem_IO_addr = 1'b0;
        end
    end

    // Check if address is for memory-mapped I/O device
    always @(*) begin
        if ((addr >= IO_MEM_BASE_1 && addr < IO_MEM_LIM_1) ||
            (addr >= IO_MEM_BASE_2 && addr < IO_MEM_LIM_2) ||
            (addr >= PLIC_BASE && addr < PLIC_LIM)) begin
            is_mem_addr = 1'b0;
            is_IO_addr = 1'b1;
            is_near_mem_IO_addr = 1'b0;
        end
    end

    // Check if address is for nearby memory-mapped I/O device
    always @(*) begin
        if (addr >= IO_MEM_BASE_1 && addr < IO_MEM_LIM_1) begin
            is_mem_addr = 1'b0;
            is_IO_addr = 1'b0;
            is_near_mem_IO_addr = 1'b1;
        end
    end

endmodule

