module booth_multiplier (
    input signed [15:0] a,
    input signed [15:0] b,
    input signed_ctrl,
    output signed [31:0] product
);

    reg signed [31:0] multiplicand;
    reg signed [31:0] multiplier;
    reg signed [31:0] product_reg;
    reg signed [1:0] control;

    always @(*) begin
        multiplicand = {16'b0, a};
        multiplier = {16'b0, b};
        control = signed_ctrl ? 2'b10 : 2'b01;
    end

    always @(posedge clk) begin
        if (reset) begin
            product_reg <= 32'b0;
        end else begin
            case (control)
                2'b01: begin // unsigned multiplication
                    product_reg <= multiplicand * multiplier;
                end
                2'b10: begin // signed multiplication
                    product_reg <= $signed($unsigned(multiplicand) * $unsigned(multiplier));
                end
            endcase
        end
    end

    assign product = product_reg;

endmodule

module ripple_carry_adder (
    input signed [3:0] A,
    input signed [3:0] B,
    output signed [3:0] sum,
    output carry_out
);

    reg signed [3:0] sum_reg;
    reg carry_out_reg;

    always @(A or B or carry_in) begin
        sum_reg = A + B + carry_in;
        carry_out_reg = (sum_reg[4] == 1);
    end

    assign sum = sum_reg[3:0];
    assign carry_out = carry_out_reg;

endmodule

module signed_adder (
    input signed [31:0] multiplicand,
    input signed [3:0] addend,
    output signed [15:0] result
);

    reg signed [31:0] sum_reg;

    always @(posedge clk) begin
        if (reset) begin
            sum_reg <= 32'b0;
        end else begin
            sum_reg <= multiplicand + {16'b0, addend};
        end
    end

    assign result = sum_reg[31:16];

endmodule

module top_module (
