    );

endmodule

module digital_clock(
    input clk,
    input reset,
    output reg [6:0] seg,
    output reg [3:0] an
);

reg [3:0] hours = 4'd0;
reg [3:0] minutes = 4'd0;
reg [3:0] seconds = 4'd0;

always @(posedge clk) begin
    if (reset) begin
        hours <= 4'd0;
        minutes <= 4'd0;
        seconds <= 4'd0;
    end else begin
        seconds <= seconds + 1;
        if (seconds == 60) begin
            seconds <= 4'd0;
            minutes <= minutes + 1;
        end
        if (minutes == 60) begin
            minutes <= 4'd0;
            hours <= hours + 1;
        end
        if (hours == 24) begin
            hours <= 4'd0;
        end
    end
end

always @(hours, minutes, seconds) begin
    case ({hours, minutes, seconds})
        0: begin seg = 7'b1111110; an = 4'b1110; end // 0
        1: begin seg = 7'b0110000; an = 4'b1110; end // 1
        2: begin seg = 7'b1101101; an = 4'b1110; end // 2
        3: begin seg = 7'b1111001; an = 4'b1110; end // 3
        4: begin seg = 7'b0110011; an = 4'b1110; end // 4
        5: begin seg = 7'b1011011; an = 4'b1110; end // 5
        6: begin seg = 7'b1011111; an = 4'b1110; end // 6
        7: begin seg = 7'b1110000; an = 4'b1110; end // 7
        8: begin seg = 7'b1111111; an = 4'b1110; end // 8
        9: begin seg = 7'b1111011; an = 4'b1110; end // 9
        default: begin seg = 7'b0000000; an = 4'b1111; end // blank
    endcase
end

endmodule

module RLE (
  input [7:0] data_in,
  input encode,
  input reset,
  output [7:0] data_out,
  output valid_out,
  output underflow,
  output overflow
);

  // Define state machine states
  parameter IDLE = 2'b00;
  parameter ENCODE = 2'b01;
  parameter DECODE = 2'b10;

  // Define state machine inputs
  reg [1:0] state;
  reg [7:0] count;
  reg [7:0] value;
  reg [7:0] prev_value;
  reg [7:0] output_value;
  reg [7:0] input_value;
  reg valid_flag;
  reg underflow_flag;
  reg overflow_flag;

  // State machine
  always @(posedge reset or posedge encode or posedge data_in) begin
    if (reset) begin
      state <= IDLE;
      count <= 0;
      value <= 0;
      prev_value <= 0;
      output_value <= 0;
      input_value <= 0;
      valid_flag <= 0;
      underflow_flag <= 0;
      overflow_flag <= 0;
    end else begin
      case (state)
        IDLE: begin
          if (encode) begin
            state <= ENCODE;
            count <= 1;
            value <= data_in;
            prev_value <= data_in;
          end else begin
            state <= DECODE;
            count <= 0;
            value <= 0;
            prev_value <= 0;
          end
        end
        ENCODE: begin
          if (data_in == prev_value && count < 255) begin
            count <= count + 1;
          end else begin
            output_value <= {count, prev_value};
            if (valid_flag) begin
              overflow_flag <= 1;
            end else begin
              valid_flag <= 1;
            end
            count <= 1;
            value <= data_in;
            prev_value <= data_in;
          end
          if (valid_flag && !overflow_flag) begin
            state <= IDLE;
            count <= 0;
            value <= 0;
            prev_value <= 0;
            input_value <= 0;
            valid_flag <= 0;
          end
        end
        DECODE: begin
          if (count == 0) begin
            count <= data_in;
            value <= data_in[7:0];
            if (input_value == 0) begin
              input_value <= 1;
            end else begin
              output_value <= value;
              if (valid_flag) begin
                underflow_flag <= 1;
              end else begin
                valid_flag <= 1;
              end
              count <= count - 1;
              if (count == 0) begin
                state <= IDLE;
                count <= 0;
                value <= 0;
                prev_value <= 0;
                input_value <= 0;
                valid_flag <= 0;
              end
            end
          end else begin
            output_value <= value;
            if (valid_flag) begin
              underflow_flag <= 1;
            end else begin
              valid_flag <= 1;
            end
            count <= count - 1;
            if (count == 0) begin
              state <= IDLE;
              count <= 0;
              value <= 0;
              prev_value <= 0;
              input_value <= 0;
              valid_flag <= 0;
            end
          end
        end
      endcase
    end
  end

  // Assign outputs
  assign data_out = output_value;
  assign valid_out = valid_flag;
  assign underflow = underflow_flag;
  assign overflow = overflow_flag;

endmodule

module shift_register (
  input clk,
  input reset,
  input [15:0] parallel_load,
  input load,
  input shift_left,
  input shift_right,
  output reg [15:0] q,
  output reg serial_out
);

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      q <= 16'b0;
      serial_out <= 1'b0;
    end
    else begin
      if (load) begin
        q <= parallel_load;
        serial_out <= q[15];
      end
      else if (shift_left) begin
        q <= {q[14:0], 1'b0};
        serial_out <= q[15];
      end
      else if (shift_right) begin
        q <= {1'b0, q[15:1]};
        serial_out <= q[0];
      end
      else begin
        serial_out <= q[15];
      end
    end
  end

endmodule

module PLL (
  input ref,
  input in,
  output out
);

parameter freq = 1000000; // frequency of output signal
parameter phase_diff = 0; // initial phase difference between input and reference signals

reg [31:0] phase_accumulator = 0; // phase accumulator
reg [31:0] phase_increment = 0; // phase increment
reg [31:0] vco_frequency = 0; // VCO frequency
reg [31:0] vco_phase = 0; // VCO phase
reg [31:0] loop_filter_output = 0; // loop filter output

// Phase detector
always @(posedge ref or posedge in) begin
  if (ref && in) begin
    phase_accumulator <= phase_accumulator + phase_increment;
  end
end

// Loop filter
always @(posedge ref) begin
  loop_filter_output <= loop_filter_output + (phase_diff - (phase_accumulator >> 16));
end

// VCO
always @(posedge ref) begin
  vco_frequency <= loop_filter_output;
  vco_phase <= vco_phase + vco_frequency;
end

// Output signal
always @(posedge ref) begin
  out <= $signed($bitstoreal($itor(vco_phase[31:0]) / freq));
end

// Calculate phase increment
initial begin
  phase_increment = $signed($itor(freq * (2**16)));
end

endmodule

