reg [2:0] buffer;

always @(posedge clk)
begin
    buffer <= {buffer[1:0], d};
end

assign q = buffer[2];

endmodule

module HMAC (
  input [n-1:0] message,
  input [k-1:0] key,
  input [h-1:0] code,
  output [h-1:0] computed_code,
  output valid
);

parameter n = 512; // number of bits in message
parameter k = 256; // number of bits in key
parameter h = 256; // number of bits in code

// SHA-256 hash function module
SHA256 sha256 (
  .data(message),
  .hash(computed_code)
);

// XOR the key with ipad and opad
wire [k-1:0] key_xor_ipad;
wire [k-1:0] key_xor_opad;
genvar i;
generate
  for (i = 0; i < k; i = i + 1) begin : xor_key
    assign key_xor_ipad[i] = key[i] ^ 8'h36;
    assign key_xor_opad[i] = key[i] ^ 8'h5C;
  end
endgenerate

// Concatenate key_xor_ipad with message
wire [n+k-1:0] key_ipad_message;
assign key_ipad_message = {key_xor_ipad, message};

// Compute the inner hash
wire [h-1:0] inner_hash;
SHA256 inner_sha256 (
  .data(key_ipad_message),
  .hash(inner_hash)
);

// Concatenate key_xor_opad with inner_hash
wire [k+h-1:0] key_opad_inner_hash;
assign key_opad_inner_hash = {key_xor_opad, inner_hash};

// Compute the final HMAC code
SHA256 final_sha256 (
  .data(key_opad_inner_hash),
  .hash(computed_code)
);

// Check if the computed code is valid
assign valid = (computed_code == code);

endmodule

module comparator (
  input [n-1:0] A,
  input [n-1:0] B,
  output eq,
  output gt,
  output lt
);

parameter n = 8; // number of bits in A and B

reg unsigned_eq, unsigned_gt, unsigned_lt; // signals for unsigned comparison
reg signed_eq, signed_gt, signed_lt; // signals for signed comparison

// unsigned comparison
always @(*) begin
  unsigned_eq = (A == B);
  unsigned_gt = (A > B);
  unsigned_lt = (A < B);
end

// signed comparison
always @(*) begin
  if (A[n-1] == 0 && B[n-1] == 1) begin // A is positive, B is negative
    signed_eq = 0;
    signed_gt = 1;
    signed_lt = 0;
  end else if (A[n-1] == 1 && B[n-1] == 0) begin // A is negative, B is positive
    signed_eq = 0;
    signed_gt = 0;
    signed_lt = 1;
  end else begin // A and B have the same sign
    unsigned_eq = ({1'b0, A[n-2:0]} == {1'b0, B[n-2:0]});
    unsigned_gt = (A[n-1] == 0 && B[n-1] == 1 && !signed_eq) || (unsigned_gt && !signed_eq);
    unsigned_lt = (A[n-1] == 1 && B[n-1] == 0 && !signed_eq) || (unsigned_lt && !signed_eq);
  end
end

// output signals
assign eq = unsigned_eq || signed_eq;
assign gt = unsigned_gt || signed_gt;
assign lt = unsigned_lt || signed_lt;

endmodule

module my_module (
    Y ,
