module functionGen (
    input clk,
    input rst,
    input en,
    input [1:0] waveType,
    input [15:0] freq,
    input [15:0] phaseOffset,
    input signed [7:0] offset,
    input [7:0] amplitude,
    output signed [7:0] outSignal
);

reg [15:0] phaseAcc;
reg [7:0] sample;
reg [7:0] sampleNext;
reg [1:0] waveTypeNext;
reg [15:0] freqNext;
reg [15:0] phaseOffsetNext;
reg signed [7:0] offsetNext;
reg [7:0] amplitudeNext;

parameter SINE = 2'b00;
parameter TRIANGLE = 2'b01;
parameter SAWTOOTH = 2'b10;
parameter SQUARE = 2'b11;

always @(posedge clk) begin
    if (rst) begin
        phaseAcc <= 0;
        sample <= 0;
        waveTypeNext <= waveType;
        freqNext <= freq;
        phaseOffsetNext <= phaseOffset;
        offsetNext <= offset;
        amplitudeNext <= amplitude;
    end else begin
        if (en) begin
            waveType <= waveTypeNext;
            freq <= freqNext;
            phaseOffset <= phaseOffsetNext;
            offset <= offsetNext;
            amplitude <= amplitudeNext;
        end
        case (waveType)
            SINE: begin
                phaseAcc <= phaseAcc + freq;
                sampleNext <= amplitude * $sin(2 * $pi * (phaseAcc + phaseOffset) / 2**16) + offset;
            end
            TRIANGLE: begin
                phaseAcc <= phaseAcc + freq;
                if (phaseAcc < 2**15) begin
                    sampleNext <= (amplitude * 2 * phaseAcc) / 2**16 + offset;
                end else begin
                    sampleNext <= (amplitude * 2 * (2**16 - phaseAcc)) / 2**16 + offset;
                end
            end
            SAWTOOTH: begin
                phaseAcc <= phaseAcc + freq;
                sampleNext <= (amplitude * phaseAcc) / 2**16 + offset;
            end
            SQUARE: begin
                phaseAcc <= phaseAcc + freq;
                if (phaseAcc < 2**15) begin
                    sampleNext <= amplitude + offset;
                end else begin
                    sampleNext <= -amplitude + offset;
                end
            end
        endcase
        sample <= sampleNext;
    end
end

assign outSignal = sample;

endmodule

