module DCT_IDCT (
  input [n-1:0] in,
  input rst,
  input start,
  output [n-1:0] out,
  output done
);

parameter n = 8; // number of input signals

// Define internal signals
reg signed [n-1:0] dct_out;
reg signed [n-1:0] idct_out;
reg [n-1:0] count;
reg dct_done;
reg idct_done;

// DCT block
always @ (posedge start) begin
  if (rst) begin
    count <= 0;
    dct_done <= 0;
  end
  else begin
    // Compute DCT
    dct_out[0] <= 1/sqrt(n) * (in[0] + in[1] + in[2] + in[3] + in[4] + in[5] + in[6] + in[7]);
    dct_out[1] <= 1/sqrt(n) * (in[0] + in[1] + in[2] + in[3] - in[4] - in[5] - in[6] - in[7]);
    dct_out[2] <= 1/sqrt(n) * (in[0] + in[1] - in[2] - in[3] - in[4] - in[5] + in[6] + in[7]);
    dct_out[3] <= 1/sqrt(n) * (in[0] + in[1] - in[2] - in[3] + in[4] + in[5] - in[6] - in[7]);
    dct_out[4] <= 1/sqrt(n) * (in[0] - in[1] - in[2] + in[3] + in[4] - in[5] - in[6] + in[7]);
    dct_out[5] <= 1/sqrt(n) * (in[0] - in[1] - in[2] + in[3] - in[4] + in[5] + in[6] - in[7]);
    dct_out[6] <= 1/sqrt(n) * (in[0] - in[1] + in[2] - in[3] - in[4] + in[5] - in[6] + in[7]);
    dct_out[7] <= 1/sqrt(n) * (in[0] - in[1] + in[2] - in[3] + in[4] - in[5] + in[6] - in[7]);

    // Set done signal
    dct_done <= 1;
  end
end

// IDCT block
always @ (posedge dct_done) begin
  if (rst) begin
    count <= 0;
    idct_done <= 0;
  end
  else begin
    // Compute IDCT
    idct_out[0] <= 1/sqrt(n) * (dct_out[0] + dct_out[1] + dct_out[2] + dct_out[3] + dct_out[4] + dct_out[5] + dct_out[6] + dct_out[7]);
    idct_out[1] <= 1/sqrt(n) * (dct_out[0] + dct_out[1] + dct_out[2] + dct_out[3] - dct_out[4] - dct_out[5] - dct_out[6] - dct_out[7]);
    idct_out[2] <= 1/sqrt(n) * (dct_out[0] + dct_out[1] - dct_out[2] - dct_out[3] - dct_out[4] - dct_out[5] + dct_out[6] + dct_out[7]);
    idct_out[3] <= 1/sqrt(n) * (dct_out[0] + dct_out[1] - dct_out[2] - dct_out[3] + dct_out[4] + dct_out[5] - dct_out[6] - dct_out[7]);
    idct_out[4] <= 1/sqrt(n) * (dct_out[0] - dct_out[1] - dct_out[2] + dct_out[3] + dct_out[4] - dct_out[5] - dct_out[6] + dct_out[7]);
    idct_out[5] <= 1/sqrt(n) * (dct_out[0] - dct_out[1] - dct_out[2] + dct_out[3] - dct_out[4] + dct_out[5] + dct_out[6] - dct_out[7]);
    idct_out[6] <= 1/sqrt(n) * (dct_out[0] - dct_out[1] + dct_out[2] - dct_out[3] - dct_out[4] + dct_out[5] - dct_out[6] + dct_out[7]);
    idct_out[7] <= 1/sqrt(n) * (dct_out[0] - dct_out[1] + dct_out[2] - dct_out[3] + dct_out[4] - dct_out[5] + dct_out[6] - dct_out[7]);

    // Set done signal
    idct_done <= 1;
  end
end

// Output signals
assign out = idct_out;
assign done = idct_done;

endmodule

module barrel_shifter (
    input [15:0] data_in,
    input [3:0] shift_amt,
    output [15:0] data_out
);

reg [15:0] stage1_out, stage2_out, stage3_out, stage4_out;

// Stage 1: Shift left by 8 bits
always @(*) begin
    stage1_out = {data_in[7:0], data_in};
end

// Stage 2: Shift left by 4 bits
always @(*) begin
    stage2_out = {stage1_out[3:0], stage1_out};
end

// Stage 3: Shift left by 2 bits, right by 2 bits, or rotate left by 2 bits
always @(*) begin
    case(shift_amt[1:0])
        2'b00: stage3_out = {stage2_out[1:0], stage2_out[15:2]};
        2'b01: stage3_out = {stage2_out[3:0], stage2_out[15:4]};
        2'b10: stage3_out = {stage2_out[5:0], stage2_out[15:6]};
        2'b11: stage3_out = {stage2_out[7:0], stage2_out[15:8]};
    endcase
end

// Stage 4: Shift left by 1 bit, right by 1 bit, or rotate left by 1 bit
always @(*) begin
    case(shift_amt[3:2])
        2'b00: stage4_out = {stage3_out[0], stage3_out[15:1]};
        2'b01: stage4_out = {stage3_out[2:0], stage3_out[15:3]};
        2'b10: stage4_out = {stage3_out[4:0], stage3_out[15:5]};
        2'b11: stage4_out = {stage3_out[6:0], stage3_out[15:7]};
    endcase
end

assign data_out = stage4_out;

endmodule

