module ADC_UART(
    input  clkp,
    input  clkn,
    input  vp,
    input  vn,
    inout  rx,
    inout  tx,
    input  rst,
    input  [7:0] command,
    output reg [7:0] status
);

parameter ADDR_WIDTH = 8;
parameter DATA_WIDTH = 16;
parameter SAMPLES = 4;

wire [DATA_WIDTH-1:0] adc_data;
wire adc_busy, adc_drdy, adc_eoc, adc_eos;

reg [ADDR_WIDTH-1:0] addr;
reg [DATA_WIDTH-1:0] data_in;
reg [DATA_WIDTH-1:0] data_out;
reg valid;
reg [1:0] state;

wire [DATA_WIDTH-1:0] uart_data_in;
wire [DATA_WIDTH-1:0] uart_data_out;
wire [ADDR_WIDTH-1:0] uart_addr;
wire uart_we;

wire [DATA_WIDTH-1:0] ram_data_out;
wire ram_we;

xadc_temp xadc_inst (
    .daddr_in({2'b00, 5'b0}),
    .dclk_in(clkp),
    .den_in(1'b1),
    .di_in(0),
    .dwe_in(0),
    .reset_in(rst),
    .busy_out(adc_busy),
    .channel_out(),
    .do_out(adc_data),
    .drdy_out(adc_drdy),
    .eoc_out(adc_eoc),
    .eos_out(adc_eos),
    .alarm_out(),
    .vp_in(vp),
    .vn_in(vn)
);

dpram ram_inst (
    .clka(clkp),
    .wea(ram_we),
    .addra(addr),
    .dina(data_in),
    .douta(),
    .clkb(clkp),
    .web(uart_we),
    .addrb(uart_addr),
    .dinb({1'b0, uart_data_in}),
    .doutb(ram_data_out)
);

assign uart_data_out = ram_data_out[DATA_WIDTH-1:0];
assign status = data_out[7:0];

always @(posedge clkp or posedge rst) begin
    if (rst) begin
        addr <= 0;
        data_in <= 0;
        data_out <= 0;
        valid <= 0;
        state <= 0;
    end else begin
        case (state)
            0: begin // Idle
                if (uart_we) begin
                    addr <= uart_addr;
                    data_in <= uart_data_in;
                    ram_we <= 1;
                    state <= 1;
                    valid <= 1;
                end else if (command == 8'h01) begin // STRT_ADC
                    addr <= 0;
                    ram_we <= 0;
                    state <= 2;
                end
            end
            1: begin // Write to RAM
                if (!uart_we) begin
                    state <= 0;
                    valid <= 0;
                end
            end
            2: begin // ADC conversion
                if (adc_drdy) begin
                    data_in <= adc_data[DATA_WIDTH-5:DATA_WIDTH-20];
                    addr <= addr + 1;
                    if (addr == SAMPLES-1) begin
                        state <= 3;
                    end
                end
            end
            3: begin // Read from RAM
                data_out <= ram_data_out;
                state <= 0;
            end
        endcase
    end
end

top_UART uart_inst (
    .rst(rst),
    .clk(clkp),
    .rx(rx),
    .tx(tx),
    .command(command),
    .ram_we(uart_we),
    .ram_din(uart_data_in),
    .ram_dout(uart_data_out),
    .ram_addr(uart_addr)
);

endmodule

