    input clk,
    input rst,
    input [7:0] load,
    input shift_en,
    output reg [7:0] data_out
);

    always @(posedge clk) begin
        if (rst) begin
            data_out <= 8'b0;
        end else if (shift_en) begin
            data_out <= {data_out[6:0], 1'b0};
        end else begin
            data_out <= load;
        end
    end

