module top_module( 
    input wire [7:0] num1,
    input wire [7:0] num2,
    output wire [15:0] product );

    wire [3:0] num1_low, num1_high, num2_low, num2_high;
    wire [7:0] mult1_out, mult2_out;

    // Splitting the 8-bit numbers into two 4-bit numbers
    assign num1_low = num1[3:0];
    assign num1_high = num1[7:4];
    assign num2_low = num2[3:0];
    assign num2_high = num2[7:4];

    // Multiplying the two 4-bit numbers using the given module
    mult_4bit mult1(.a(num1_low), .b(num2_low), .result(mult1_out));
    mult_4bit mult2(.a(num1_high), .b(num2_high), .result(mult2_out));

    // Combining the outputs of the two 4-bit multipliers using the given module
    combiner combine(.a(mult1_out), .b(mult2_out), .result(product));

endmodule

// Given modules for multiplication of two 4-bit numbers
module mult_4bit(
    input wire [3:0] a,
    input wire [3:0] b,
    output wire [7:0] result
);

    assign result = a * b;

endmodule

// Given module for combining the outputs of two 4-bit multipliers
module combiner(
    input wire [7:0] a,
    input wire [7:0] b,
    output wire [15:0] result
);

    assign result = {a, b};

endmodule

module REGfn(reg_out, clk, reset, flush, reg_in);

  parameter RegLen = 63;

  // outputs
  output [RegLen:0] reg_out;
  // inouts
  // special inputs
  input clk;
  input reset;
  input flush;
  // inputs
  input [RegLen:0] reg_in;

  // internal vars
  reg [RegLen:0] reg_val;

  // assign vars

  // assign outputs
  assign reg_out = reg_val;

  // change the value of the register on every rising clock edge if the flush signal is low
  always @(posedge clk)
  begin
    if (flush == 1'b1)
    begin
      reg_val <= 'b0;
    end
    else
    begin
      reg_val <= reg_in;
    end
  end

  // async. reset
  always @(posedge reset)
  begin
    reg_val = 'b0;
  end

