module packet_converter (
  input clk,
  input nreset,
  input [31:0] packet_in,
  input [1:0] datamode_in,
  input [12:0] ctrlmode_in,
  input [31:0] dstaddr_in,
  input [31:0] srcaddr_in,
  input write_in,
  output reg ready_out,
  output [31:0] packet_out,
  output [1:0] datamode_out,
  output [4:0] ctrlmode_out,
  output [31:0] dstaddr_out,
  output [31:0] srcaddr_out
);

  wire [31:0] read_data;
  wire access_in;
  reg access_out;

  packet2emesh #(.AW(32), .PW(1)) p2e (
    // Outputs
    .write_in(write_in),
    .datamode_in(datamode_in),
    .ctrlmode_in(ctrlmode_in),
    .dstaddr_in(dstaddr_in),
    .srcaddr_in(srcaddr_in),
    .data_in(packet_in),
    // Inputs
    .packet_in(read_data)
  );

  reg [31:0] data_out;
  reg [31:0] dstaddr_out_reg;
  reg [1:0] datamode_out_reg;
  reg [4:0] ctrlmode_out_reg;

  always @ (posedge clk or negedge nreset) begin
    if (!nreset) begin
      access_out <= 1'b0;
      ready_out <= 1'b0;
    end else if (access_in & ~write_in) begin
      access_out <= 1'b1;
      ready_out <= 1'b1;
      datamode_out <= datamode_out_reg;
      ctrlmode_out <= ctrlmode_out_reg;
      dstaddr_out <= dstaddr_out_reg;
      data_out <= read_data[31:0];
      srcaddr_out <= read_data[63:32];
    end
  end

  always @ (posedge clk) begin
    if (access_in & ~write_in) begin
      datamode_out_reg <= datamode_in;
      ctrlmode_out_reg[4:0] <= 5'b00001;
      dstaddr_out_reg <= srcaddr_in;
    end
  end

  emesh2packet #(.AW(32), .PW(1)) e2p (
    // Outputs
    .packet_out(packet_out),
    .datamode_out(datamode_out_reg),
    .ctrlmode_out(ctrlmode_out_reg),
    .dstaddr_out(dstaddr_out_reg),
    .data_out(data_out),
    .srcaddr_out(srcaddr_out)
    // Inputs
    // .write_out()
  );

endmodule

module barrel_shift_mux (
    input [7:0] data_in0,
    input [7:0] data_in1,
    input [7:0] data_in2,
    input [7:0] data_in3,
    input [1:0] select,
    input shift_left,
    input shift_right,
    input rotate_right,
    output [7:0] data_out
);

reg [7:0] shifted_data;

// Barrel Shifter Module
always @(*) begin
    case ({shift_left, shift_right, rotate_right})
        3'b001: shifted_data = {data_in0[6:0], 1'b0};
        3'b010: shifted_data = {1'b0, data_in0[7:1]};
        3'b100: shifted_data = {data_in0[0], data_in0[7:1]};
        default: shifted_data = data_in0;
    endcase
end

// Multiplexer Module
always @(*) begin
    case (select)
        2'b00: data_out = shifted_data;
        2'b01: data_out = data_in1;
        2'b10: data_out = data_in2;
        2'b11: data_out = data_in3;
    endcase
end

endmodule

module priority_encoder (
