            8'b00000011, 8'b00000101, 8'b00001001, 8'b00010001, 8'b00100001, 8'b01000001, 8'b10000001: pos = 3'b001;
            8'b00000111, 8'b00001111, 8'b00011111, 8'b00111111, 8'b01111111, 8'b11111111: pos = 3'b010;
            default: pos = 3'b000;
        endcase
    end
endmodule

