module fifo (
  input clk,
  input rst,
  input wr_en,
  input rd_en,
  input [7:0] data_in,
  output [7:0] data_out,
  output empty,
  output full
);

  reg [7:0] buffer [0:7];
  reg write_ptr = 0;
  reg read_ptr = 0;
  reg [2:0] count = 0;

  always @(posedge clk or negedge rst) begin
    if (~rst) begin
      write_ptr <= 0;
      read_ptr <= 0;
      count <= 0;
    end else begin
      if (wr_en && ~full) begin
        buffer[write_ptr] <= data_in;
        write_ptr <= (write_ptr + 1) % 8;
        count <= count + 1;
      end
      if (rd_en && ~empty) begin
        data_out <= buffer[read_ptr];
        read_ptr <= (read_ptr + 1) % 8;
        count <= count - 1;
      end
    end
  end

  assign empty = (count == 0);
  assign full = (count == 8);

endmodule

module four_bit_adder(
    input [3:0] A, B,
    output [3:0] S,
    output Cout
);

// Internal signals
wire [3:0] sum;
wire [3:0] carry;

// Full adder instances
full_adder fa0(.A(A[0]), .B(B[0]), .Cin(1'b0), .Sum(sum[0]), .Cout(carry[0]));
full_adder fa1(.A(A[1]), .B(B[1]), .Cin(carry[0]), .Sum(sum[1]), .Cout(carry[1]));
full_adder fa2(.A(A[2]), .B(B[2]), .Cin(carry[1]), .Sum(sum[2]), .Cout(carry[2]));
full_adder fa3(.A(A[3]), .B(B[3]), .Cin(carry[2]), .Sum(sum[3]), .Cout(Cout));

// Output assignment
assign S = sum;

endmodule

module full_adder(
    input A, B, Cin,
    output Sum, Cout
);

// Internal signals
wire s1, c1, c2;

// XOR gates
assign s1 = A ^ B;
assign Sum = s1 ^ Cin;

// AND gates
assign c1 = A & B;
assign c2 = s1 & Cin;

// OR gate
assign Cout = c1 | c2;

endmodule

