  wire [10:0] fifo_prog_full;

  assign full = fifo_full[1];
  assign almost_full = fifo_almost_full[1];
  assign empty = fifo_empty[1];
  assign almost_empty = fifo_almost_empty[1];
  assign rd_data_count = fifo_data_count;
  assign prog_full = fifo_prog_full[10];

  always @(posedge wr_clk) begin
    if (rst) begin
      wr_ptr <= 0;
      rd_ptr <= 0;
      fifo_full <= 2'b0;
      fifo_empty <= 2'b1;
      fifo_almost_full <= 2'b0;
      fifo_almost_empty <= 2'b1;
