module ALU(
    input [31:0] input1,
    input [31:0] input2,
    input [3:0] aluCtr,
    output reg zero,
    output reg [31:0] aluRes
);

always @ (input1 or input2 or aluCtr)
begin
    case (aluCtr)
        4'b0000: begin // AND
            aluRes = input1 & input2;
            zero = (aluRes == 0) ? 1 : 0;
        end
        4'b0001: begin // OR
            aluRes = input1 | input2;
            zero = (aluRes == 0) ? 1 : 0;
        end
        4'b0010: begin // ADD
            aluRes = input1 + input2;
            zero = (aluRes == 0) ? 1 : 0;
        end
        4'b0110: begin // SUBTRACT
            aluRes = input1 - input2;
            zero = (aluRes == 0) ? 1 : 0;
        end
        4'b0111: begin // SET ON LESS THAN
            zero = (input1 < input2) ? 1 : 0;
            aluRes = zero;
        end
        4'b1100: begin // NOR
            aluRes = ~(input1 | input2);
            zero = (aluRes == 0) ? 1 : 0;
        end
        default: begin
            aluRes = 0;
            zero = 0;
        end
    endcase
end

endmodule

module calculator (
    input clk,
    input rst,
    input [1:0] op,
    input [7:0] a,
    input [7:0] b,
    output reg [7:0] out,
    output reg valid
);

reg [15:0] result;
reg [7:0] a_reg;
reg [7:0] b_reg;
reg [1:0] op_reg;
reg valid_reg;

always @(posedge clk) begin
    if (rst) begin
        result <= 0;
        a_reg <= 0;
        b_reg <= 0;
        op_reg <= 0;
        valid_reg <= 0;
    end else begin
        a_reg <= a;
        b_reg <= b;
        op_reg <= op;
        case (op)
            2'b00: result <= a_reg + b_reg;
            2'b01: result <= a_reg - b_reg;
            2'b10: result <= a_reg * b_reg;
            2'b11: result <= a_reg / b_reg;
        endcase
        out <= result[7:0];
        valid_reg <= 1;
    end
end

always @(negedge clk) begin
    valid <= valid_reg;
end

endmodule

module IBUFDS_DIFF_OUT (O, OB, I, IB);

    parameter DIFF_TERM = "FALSE";
    parameter DQS_BIAS = "FALSE";
    parameter IBUF_LOW_PWR = "TRUE";
    parameter IOSTANDARD = "DEFAULT";

    output O, OB;
    input  I, IB;

    wire i_xor_ib;
    assign i_xor_ib = I ^ IB;

    reg o_out;

    buf B0 (O, o_out);
    not B1 (OB, o_out);

    initial begin
        case (DIFF_TERM)
            "TRUE", "FALSE" : ;
            default : begin
                          $display("Attribute Syntax Error : The attribute DIFF_TERM on IBUFDS_DIFF_OUT instance %m is set to %s.  Legal values for this attribute are TRUE or FALSE.", DIFF_TERM);
                          $finish;
                      end
        endcase // case(DIFF_TERM)

        case (IBUF_LOW_PWR)
            "FALSE", "TRUE" : ;
            default : begin
                          $display("Attribute Syntax Error : The attribute IBUF_LOW_PWR on IBUFDS_DIFF_OUT instance %m is set to %s.  Legal values for this attribute are TRUE or FALSE.", IBUF_LOW_PWR);
                          $finish;
                      end
        endcase

        case (DQS_BIAS)
            "TRUE"  : o_out <= #1 1'b0;
            "FALSE" : o_out <= #1 1'bx;
            default : begin
                          $display("Attribute Syntax Error : The attribute DQS_BIAS on IBUFDS_DIFF_OUT instance %m is set to %s.  Legal values for this attribute are TRUE or FALSE.", DQS_BIAS);
                          $finish;
                      end
        endcase
    end

    always @(I or IB or DQS_BIAS or i_xor_ib) begin
        if (i_xor_ib) begin
            if (I) begin
                o_out <= 1'b1;
            end else begin
                o_out <= 1'b0;
            end
        end else begin
            if (I === 1'bz || IB === 1'bz) begin
                o_out <= 1'bx;
            end else begin
                o_out <= 1'bz;
            end
        end
    end

    `ifdef XIL_TIMING
        specify
            (I => O) = (0:0:0, 0:0:0);
            (I => OB) = (0:0:0, 0:0:0);
            (IB => O) = (0:0:0, 0:0:0);
            (IB => OB) = (0:0:0, 0:0:0);
            specparam PATHPULSE$ = 0;
        endspecify
    `endif

endmodule

module bcd_counter (
    input clk,
    input reset,   // Synchronous active-high reset
    output reg [15:0] bcd_out // BCD output
);

reg [3:0] digit0, digit1, digit2, digit3;
reg [2:0] enable;

always @(posedge clk) begin
    if (reset) begin
        digit0 <= 4'b0000;
        digit1 <= 4'b0000;
        digit2 <= 4'b0000;
        digit3 <= 4'b0000;
        enable <= 3'b111;
    end else begin
        digit0 <= digit0 + 1;
        if (digit0 == 4'b1010) begin
            digit0 <= 4'b0000;
            digit1 <= digit1 + 1;
        end
        if (digit1 == 4'b1010) begin
            digit1 <= 4'b0000;
            digit2 <= digit2 + 1;
        end
        if (digit2 == 4'b1010) begin
            digit2 <= 4'b0000;
            digit3 <= digit3 + 1;
        end
        if (digit3 == 4'b1010) begin
            digit3 <= 4'b0000;
        end
        enable <= {digit3[3], digit2[3], digit1[3]};
    end
end

assign bcd_out = {digit3, digit2, digit1, digit0};

endmodule

