module booth_keypad (
    input clk,
    input rst,
    input signed [7:0] a,
    input signed [7:0] b,
    input [3:0] col,
    output [3:0] row,
    output reg signed [15:0] p
);

// Booth Multiplier
reg signed [7:0] m;
reg signed [7:0] a_reg;
reg signed [7:0] b_reg;
reg signed [7:0] b_neg;
reg [3:0] count;
reg [1:0] state;

always @(posedge clk) begin
    if (rst) begin
        m <= 0;
        a_reg <= 0;
        b_reg <= 0;
        b_neg <= 0;
        count <= 0;
        state <= 0;
    end else begin
        a_reg <= a;
        b_reg <= b;
        b_neg <= ~b + 1;
        case (state)
            0: begin
                if (count == 3) begin
                    state <= 1;
                    count <= 0;
                end else begin
                    count <= count + 1;
                end
            end
            1: begin
                if (b_reg[0] == 1) begin
                    m <= m + a_reg;
                end
                state <= 2;
            end
            2: begin
                if (b_reg[0] == 0) begin
                    state <= 3;
                end
                b_reg <= b_reg >> 1;
                count <= count + 1;
            end
            3: begin
                m <= m - a_reg;
                state <= 4;
            end
            4: begin
                if (b_reg[0] == 1) begin
                    m <= m + b_neg;
                end
                state <= 5;
            end
            5: begin
                if (b_reg[0] == 0) begin
                    state <= 0;
                end
                b_reg <= b_reg >> 1;
                count <= count + 1;
            end
        endcase
    end
end

// Keypad Scanner
reg [3:0] row_reg;
reg [3:0] col_reg;
reg [3:0] row_out;
reg [3:0] col_out;
reg [1:0] keypad_state;

parameter [3:0] ROW1 = 4'b1110;
parameter [3:0] ROW2 = 4'b1101;
parameter [3:0] ROW3 = 4'b1011;
parameter [3:0] ROW4 = 4'b0111;

always @(posedge clk) begin
    if (rst) begin
        row_reg <= 4'b1111;
        col_reg <= 4'b1111;
        row_out <= 4'b1111;
        col_out <= 4'b1111;
        keypad_state <= 0;
    end else begin
        case (keypad_state)
            0: begin
                row_reg <= ROW1;
                col_reg <= 4'b1110;
                keypad_state <= 1;
            end
            1: begin
                row_out[0] <= ~row_reg[0] & col[0];
                row_out[1] <= ~row_reg[1] & col[0];
                row_out[2] <= ~row_reg[2] & col[0];
                row_out[3] <= ~row_reg[3] & col[0];
                col_out[0] <= ~col_reg[0] & row[0];
                col_out[1] <= ~col_reg[1] & row[0];
                col_out[2] <= ~col_reg[2] & row[0];
                col_out[3] <= ~col_reg[3] & row[0];
                row_reg <= ROW2;
                col_reg <= 4'b1101;
                keypad_state <= 2;
            end
            2: begin
                row_out[0] <= ~row_reg[0] & col[1];
                row_out[1] <= ~row_reg[1] & col[1];
                row_out[2] <= ~row_reg[2] & col[1];
                row_out[3] <= ~row_reg[3] & col[1];
                col_out[0] <= ~col_reg[0] & row[1];
                col_out[1] <= ~col_reg[1] & row[1];
                col_out[2] <= ~col_reg[2] & row[1];
                col_out[3] <= ~col_reg[3] & row[1];
                row_reg <= ROW3;
                col_reg <= 4'b1011;
                keypad_state <= 3;
            end
            3: begin
                row_out[0] <= ~row_reg[0] & col[2];
                row_out[1] <= ~row_reg[1] & col[2];
                row_out[2] <= ~row_reg[2] & col[2];
                row_out[3] <= ~row_reg[3] & col[2];
                col_out[0] <= ~col_reg[0] & row[2];
                col_out[1] <= ~col_reg[1] & row[2];
                col_out[2] <= ~col_reg[2] & row[2];
                col_out[3] <= ~col_reg[3] & row[2];
                row_reg <= ROW4;
                col_reg <= 4'b0111;
                keypad_state <= 4;
            end
            4: begin
                row_out[0] <= ~row_reg[0] & col[3];
                row_out[1] <= ~row_reg[1] & col[3];
                row_out[2] <= ~row_reg[2] & col[3];
                row_out[3] <= ~row_reg[3] & col[3];
                col_out[0] <= ~col_reg[0] & row[3];
                col_out[1] <= ~col_reg[1] & row[3];
                col_out[2] <= ~col_reg[2] & row[3];
                col_out[3] <= ~col_reg[3] & row[3];
                row_reg <= 4'b1111;
                col_reg <= 4'b1111;
                keypad_state <= 0;
            end
        endcase
    end
end

// Output
always @(posedge clk) begin
    if (rst) begin
        p <= 0;
    end else begin
        case ({row_out, col_out})
            8'b11101110: p <= m;
            8'b11101101: p <= m >> 4;
            8'b11101011: p <= m >> 8;
            8'b11100111: p <= m >> 12;
            default: p <= p;
        endcase
    end
end

// Output Row and Column Signals
assign row = row_out;
assign col = col_out;

endmodule

module counter(
    input ain, clk, reset,
    output reg [3:0] count,
    output reg yout
);

reg [1:0] state, nextstate;
parameter S0 = 2'b00, S1 = 2'b01, S2 = 2'b10, S3 = 2'b11;

// Initialize nextstate to S2
initial begin
    nextstate = S2;
end

// State transition logic
always @(state or ain) begin
    case(state)
        S0: begin
            if (ain) nextstate = S2;
            else nextstate = S0;
        end
        S1: begin
            if (ain) nextstate = S2;
            else nextstate = S1;
        end
        S2: begin
            if (ain) nextstate = S3;
            else nextstate = S2;
        end
        S3: begin
            if (ain) nextstate = S1;
            else nextstate = S3;
        end
    endcase
end

// State and output logic
always @(posedge clk or posedge reset) begin
    if (reset) begin
        count <= 4'b0000;
        state <= S0;
        yout <= 1'b0;
    end else begin
        if (ain) begin
            if (count == 4'b1111) begin
                count <= 4'b0000;
                state <= S0;
            end else begin
                count <= count + 1;
                state <= nextstate;
            end
        end
        case(state)
            S0: begin
                if (~ain) yout <= 1'b1;
                else yout <= 1'b0;
            end
            S1: begin
                if (ain) yout <= 1'b1;
                else yout <= 1'b0;
            end
            default: yout <= 1'b0;
        endcase
    end
end

endmodule

