module brightness_clk_2hz (
    areset,
    inclk0,
    c0,
    locked,
    brightness_control
);

input areset;
input inclk0;
input [3:0] brightness_control;
output c0;
output locked;

reg [31:0] counter;
reg [31:0] duty_cycle;
reg locked;

parameter clk_divider = 25000000; // 50MHz / 2Hz
parameter lock_range = 100; // 200ppm / 2

wire clk_edge = inclk0 ^ ~inclk0;
wire locked_edge = locked ^ ~locked;

// Phase-locked loop
reg [31:0] phase_accumulator;
reg [31:0] phase_increment;
reg [31:0] error_accumulator;
reg [31:0] error_increment;

always @(posedge inclk0 or posedge areset) begin
    if (areset) begin
        phase_accumulator <= 0;
        error_accumulator <= 0;
    end else begin
        phase_accumulator <= phase_accumulator + phase_increment;
        error_accumulator <= error_accumulator + error_increment;
    end
end

assign c0 = phase_accumulator[31];
assign locked = (error_accumulator < lock_range) && (error_accumulator > -lock_range);

always @(posedge clk_edge or posedge areset) begin
    if (areset) begin
        phase_increment <= 0;
        error_increment <= 0;
    end else begin
        phase_increment <= clk_divider + error_accumulator;
        error_increment <= (brightness_control << 28) - error_accumulator / clk_divider;
    end
end

// Brightness control
always @(posedge c0 or posedge areset) begin
    if (areset) begin
        counter <= 0;
        duty_cycle <= 0;
    end else begin
        counter <= counter + 1;
        if (counter >= clk_divider) begin
            counter <= 0;
            duty_cycle <= brightness_control;
        end
    end
end

assign c0 = (counter < (clk_divider * duty_cycle / 16));

endmodule

module timer #(parameter
    CW      = 8, // counter bit width. This is the counter that can be loaded
    FW      = 4, // number of bits for the free-running counter
    FREE_EN = 0  // enables a 4-bit free enable count
) (
    input   rst,
    input   clk,
    input   cen,
    input   zero,
    input   [CW-1:0] start_value,
    input   load,
    input   clr_flag,
    output reg flag,
    output reg overflow
);

reg          load_l;
reg [CW-1:0] cnt, next;
reg [FW-1:0] free_cnt, free_next;
reg          free_ov;

always@(posedge clk, posedge rst)
    if( rst )
        flag <= 1'b0;
    else /*if(cen)*/ begin
        if( clr_flag )
            flag <= 1'b0;
        else if( cen && zero && load && overflow ) flag<=1'b1;
    end

always @(*) begin
    {free_ov, free_next} = { 1'b0, free_cnt} + 1'b1;
    {overflow, next }    = { 1'b0, cnt }     + (FREE_EN ? free_ov : 1'b1);
end

always @(posedge clk) begin
    load_l <= load;
    if( !load_l && load ) begin
        cnt <= start_value;
    end else if( cen && zero && load )
        cnt <= overflow ? start_value : next;
end

// Free running counter
always @(posedge clk) begin
    if( rst ) begin
        free_cnt <= 0;
    end else if( cen && zero ) begin
        free_cnt <= free_cnt+1'd1;
    end
end

endmodule

module modulo_operator (
  input [15:0] dividend,
  input [3:0] divisor,
  output [3:0] remainder
);

  reg [15:0] dividend_reg;
  reg [3:0] divisor_reg;
  reg [3:0] remainder_reg;

  always @(*) begin
    dividend_reg = dividend;
    divisor_reg = divisor;

    if (divisor_reg == 0) begin
      remainder_reg = 0;
    end else begin
      if (dividend_reg < 0) begin
        remainder_reg = -((-dividend_reg) % divisor_reg);
      end else begin
        remainder_reg = dividend_reg % divisor_reg;
      end
    end
  end

  assign remainder = remainder_reg;

endmodule

