module calculator (
    input signed [31:0] a,
    input signed [31:0] b,
    input [1:0] op,
    output reg valid,
    output reg error,
    output reg signed [31:0] add_out,
    output reg signed [31:0] sub_out,
    output reg signed [31:0] mul_out,
    output reg signed [31:0] div_out
);

    // Local variables
    reg signed [31:0] temp;

    // Addition
    always @* begin
        temp = a + b;
        if (a > 0 && b > 0 && temp < 0) begin
            error = 1;
            valid = 0;
        end else if (a < 0 && b < 0 && temp > 0) begin
            error = 1;
            valid = 0;
        end else begin
            error = 0;
            valid = 1;
            add_out = temp;
        end
    end

    // Subtraction
    always @* begin
        temp = a - b;
        if (a > 0 && b < 0 && temp < 0) begin
            error = 1;
            valid = 0;
        end else if (a < 0 && b > 0 && temp > 0) begin
            error = 1;
            valid = 0;
        end else begin
            error = 0;
            valid = 1;
            sub_out = temp;
        end
    end

    // Multiplication
    always @* begin
        temp = a * b;
        if (a != 0 && b != 0 && temp / a != b) begin
            error = 1;
            valid = 0;
        end else begin
            error = 0;
            valid = 1;
            mul_out = temp;
        end
    end

    // Division
    always @* begin
        if (b == 0) begin
            error = 1;
            valid = 0;
        end else begin
            temp = a / b;
            error = 0;
            valid = 1;
            div_out = temp;
        end
    end

    // Output selection
    always @* begin
        case (op)
            2'b00: begin // Addition
                add_out = temp;
                sub_out = 0;
                mul_out = 0;
                div_out = 0;
            end
            2'b01: begin // Subtraction
                add_out = 0;
                sub_out = temp;
                mul_out = 0;
                div_out = 0;
            end
            2'b10: begin // Multiplication
                add_out = 0;
                sub_out = 0;
                mul_out = temp;
                div_out = 0;
            end
            2'b11: begin // Division
                add_out = 0;
                sub_out = 0;
                mul_out = 0;
                div_out = temp;
            end
            default: begin // Invalid operation
                add_out = 0;
                sub_out = 0;
                mul_out = 0;
                div_out = 0;
                error = 1;
                valid = 0;
            end
        endcase
    end

endmodule

