module mulAdd (
    input [15:0] a,
    input [15:0] b,
    input [2:0] roundingMode,
    input int_mul,
    output reg [15:0] out,
    output reg [4:0] exceptionFlags,
    output reg [15:0] out_imul
);

    // Multiply a and b
    wire [31:0] mul_result = a * b;

    // Add the multiplication result to a
    wire [31:0] add_result = mul_result + {16'b0, a};

    // If int_mul is 1, multiply the add_result by 2
    wire [32:0] final_result = int_mul ? add_result << 1 : add_result;

    // Round the final result according to the roundingMode value
    wire [16:0] rounded_result;
    always @(*) begin
        case (roundingMode)
            3'b000: rounded_result = final_result[16:1]; // Round to nearest, ties to even
            3'b001: rounded_result = final_result[16:1] + (final_result[0] & (final_result[1:0] != 2'b00)); // Round to nearest, ties to away
            3'b010: rounded_result = final_result[16:1] + (final_result[0] & (final_result[1:0] != 2'b00)) + final_result[0]; // Round towards +inf
            3'b011: rounded_result = final_result[16:1] + (final_result[0] & (final_result[1:0] != 2'b00)) + ~final_result[0]; // Round towards -inf
            3'b100: rounded_result = final_result[16:1] + (final_result[0] | (final_result[1:0] != 2'b00)); // Round towards 0
            default: rounded_result = final_result[16:1]; // Default to round to nearest, ties to even
        endcase
    end

    // Set the exceptionFlags value based on any exceptions that occurred
    always @(*) begin
        exceptionFlags = 5'b00000;
        if (final_result[31] == 1) begin
            exceptionFlags[0] = 1; // Invalid operation
        end else if (final_result[30] == 1) begin
            exceptionFlags[1] = 1; // Overflow
        end else if (final_result[29] == 1) begin
            exceptionFlags[2] = 1; // Underflow
        end else if (final_result[28] == 1) begin
            exceptionFlags[3] = 1; // Inexact
        end
    end

    // Store the final result in out
    assign out = rounded_result;

    // Store the intermediate multiplication result in out_imul
    assign out_imul = mul_result[31:16];

endmodule

