module top_level_module(
    input clk,
    input rst,
    input [15:0] hex,
    output [31:0] sseg,
    output dp
    );

    wire [7:0] sseg0, sseg1, sseg2, sseg3;
    wire dp3;

    hex_to_sseg sseg_inst0(.hex(hex[3:0]), .sseg(sseg0), .dp(0));
    hex_to_sseg sseg_inst1(.hex(hex[7:4]), .sseg(sseg1), .dp(0));
    hex_to_sseg sseg_inst2(.hex(hex[11:8]), .sseg(sseg2), .dp(0));
    hex_to_sseg sseg_inst3(.hex(hex[15:12]), .sseg(sseg3), .dp(dp3));

    assign sseg = {sseg3, sseg2, sseg1, sseg0};
    assign dp = dp3;

    reg [3:0] digit_sel = 0;
    always @(posedge clk) begin
        if (rst) begin
            sseg <= 32'b00000000000000000000000000000000;
            dp <= 1'b0;
            digit_sel <= 0;
        end else begin
            case (digit_sel)
                0: begin
                    sseg0 <= sseg0;
                    sseg1 <= sseg1;
                    sseg2 <= sseg2;
                    sseg3 <= sseg3;
                    dp3 <= dp3;
                end
                1: begin
                    sseg0 <= sseg1;
                    sseg1 <= sseg2;
                    sseg2 <= sseg3;
                    sseg3 <= sseg0;
                    dp3 <= dp;
                end
                2: begin
                    sseg0 <= sseg2;
                    sseg1 <= sseg3;
                    sseg2 <= sseg0;
                    sseg3 <= sseg1;
                    dp3 <= dp;
                end
                3: begin
                    sseg0 <= sseg3;
                    sseg1 <= sseg0;
                    sseg2 <= sseg1;
                    sseg3 <= sseg2;
                    dp3 <= dp;
                end
            endcase
            digit_sel <= digit_sel + 1;
        end
    end

endmodule

module top_module(
    input clk,
    input [99:0] a, b,
    input cin,
    input load,
    input [1:0] ena,
    input [99:0] data,
    output cout,
    output reg [99:0] q
);

// 100-bit binary adder
wire [99:0] sum;
wire [99:0] carry_out;
assign {carry_out, sum} = a + b + cin;

// 100-bit left/right rotator
wire [99:0] rotated_data;
reg [99:0] shift_reg;
always @(posedge clk) begin
    if (load) begin
        shift_reg <= data;
    end else begin
        case (ena)
            2'b00: shift_reg <= {shift_reg[98:0], shift_reg[99]};
            2'b01: shift_reg <= {shift_reg[99], shift_reg[98:0]};
            2'b10: shift_reg <= shift_reg;
            2'b11: shift_reg <= shift_reg;
        endcase
    end
end
assign rotated_data = shift_reg;

// Bitwise OR operation
wire [99:0] final_output;
assign final_output = sum | rotated_data;

// Output signals
assign cout = carry_out[99];
always @(posedge clk) begin
    q <= final_output;
end

endmodule

