module top_module (
    input wire clk,
    input wire reset, // Synchronous active-high reset
    input wire [15:0] in, // 16-bit input
    input wire select, // Select input to choose between barrel shifter and logical operation module or functional module
    output wire [10:0] out // 11-bit output of the active module
);

    wire [7:0] shifted_in;
    wire and_out, or_out, xor_out;
    wire [7:0] functional_out;

    barrel_shifter barrel_shifter_inst (
        .in(in),
        .out(shifted_in)
    );

    logical_operations logical_operations_inst (
        .a(shifted_in[3:0]),
        .b(shifted_in[7:4]),
        .and_out(and_out),
        .or_out(or_out),
        .xor_out(xor_out)
    );

    functional_module functional_module_inst (
        .in(in),
        .out(functional_out)
    );

    always @(posedge clk) begin
        if (reset) begin
            out <= 0;
        end else begin
            if (select) begin
                out <= {and_out, or_out, xor_out};
            end else begin
                out <= {functional_out, 3'b0};
            end
        end
    end

endmodule

