module Modulo (
  input [31:0] a,
  input [31:0] b,
  output reg [31:0] result
);

  always @(*) begin
    result = a % b;
    result = $floor(result);
  end

endmodule

module multiplier(
    input [7:0] A,
    input [7:0] B,
    output [15:0] P
);

reg [15:0] temp;

always @(A, B)
begin
    temp = 0;
    for (i = 0; i < 8; i = i + 1)
    begin
        if (A[i] == 1)
        begin
            temp = temp + (B << i);
        end
    end
    P = temp;
end

endmodule

module fifo_tx
#(
	parameter integer DWIDTH = 9,
	parameter integer AWIDTH = 6
)

(
	input clock, reset, wr_en, rd_en,
	input [DWIDTH-1:0] data_in/* synthesis syn_noprune */,
	output reg f_full,write_tx,f_empty,
	output [DWIDTH-1:0] data_out/* synthesis syn_noprune */,
	output reg [AWIDTH-1:0] counter/* synthesis syn_noprune */
);
	reg [AWIDTH-1:0] wr_ptr/* synthesis syn_noprune */;
	reg [AWIDTH-1:0] rd_ptr/* synthesis syn_noprune */;

	reg  [1:0] state_data_write;
	reg  [1:0] next_state_data_write;

	reg  [1:0] state_data_read;
	reg  [1:0] next_state_data_read;

	//reg [AWIDTH-1:0] counter_writer/* synthesis syn_noprune */;
	//reg [AWIDTH-1:0] counter_reader/* synthesis syn_noprune */;


/****************************************/

always@(*)
begin
	next_state_data_write = state_data_write;

	case(state_data_write)
	2'd0:
	begin
		if(wr_en && !f_full)
		begin
			next_state_data_write = 2'd1;
		end
		else 
		begin
			next_state_data_write = 2'd0;
		end
	end
	2'd1:
	begin
		if(wr_en)
		begin
			next_state_data_write = 2'd1;
		end
		else 
		begin
			next_state_data_write = 2'd2;
		end
	end
	2'd2:
	begin
		next_state_data_write = 2'd0;
	end
	default:
	begin
		next_state_data_write = 2'd0;
	end
	endcase
end

/****************************************/

always@(*)
begin
	next_state_data_read = state_data_read;

	case(state_data_read)
	2'd0:
	begin
		if(counter > 6'd0)
		begin
			next_state_data_read = 2'd1;
		end
		else 
		begin
			next_state_data_read = 2'd0;
		end
	end
	2'd1:
	begin
		if(rd_en && !f_empty)
		begin
			next_state_data_read = 2'd2;
		end
		else 
		begin
			next_state_data_read = 2'd1;
		end
	end
	2'd2:
	begin
		if(rd_en)
		begin
			next_state_data_read = 2'd2;
		end
		else 
		begin
			next_state_data_read = 2'd3;
		end
	end
	2'd3:
	begin
		next_state_data_read = 2'd0;
	end
	default:
	begin
		next_state_data_read = 2'd0;
	end
	endcase
end

//Write pointer
	always@(posedge clock or negedge reset)
	begin
		if (!reset)
		begin
			wr_ptr      <= {(AWIDTH){1'b0}};
			state_data_write <= 2'd0;
		end
		else
		begin

			state_data_write <= next_state_data_write;

			case(state_data_write)
			2'd0:
			begin
				wr_ptr <= wr_ptr;
			end
			2'd1:
			begin
				wr_ptr <= wr_ptr;
			end
			2'd2:
			begin
				wr_ptr <= wr_ptr + 6'd1;
			end
			default:
			begin
				wr_ptr <= wr_ptr;
			end
			endcase
		end
	end

//FULL - EMPTY COUNTER
always@(posedge clock or negedge reset)
begin
	if (!reset)
	begin
		f_full  <= 1'b0;
		f_empty <= 1'b0;
		counter <= {(AWIDTH){1'b0}};
	end
	else
	begin

		if(state_data_write == 2'd2)
		begin
			counter <= counter + 6'd1;
		end
		else
		begin
			if(counter > 6'd0 && state_data_read == 2'd3)
				counter <= counter - 6'd1;
			else
				counter <= counter;	
		end

		if(counter == 6'd63)
		begin
			f_full  <= 1'b1;
		end
		else
		begin
			f_full  <= 1'b0;
		end

		if(counter == 6'd0)
		begin
			f_empty <= 1'b1;
		end
		else
		begin
			f_empty <= 1'b0;
		end
	end
end


//Read pointer
always@(posedge clock or negedge reset)
begin
	if (!reset)
	begin
		rd_ptr     <= {(AWIDTH){1'b0}};
		write_tx   <= 1'b0;
		state_data_read <= 2'd0;
	end
	else
	begin
		state_data_read <= next_state_data_read;
		case(state_data_read)
		2'd0:
		begin
			write_tx<= 1'b0;
		end
		2'd1:
		begin
			if(rd_en && !f_empty)
			begin
				rd_ptr     <= rd_ptr + 6'd1;
			end
			else
			begin
				rd_ptr     <= rd_ptr;				
			end

			write_tx<= 1'b1;
		end
		2'd2:
		begin
			write_tx<= 1'b0;
		end
		2'd3:
		begin
			write_tx<= 1'b0;
		end
		default:
		begin
			rd_ptr     <= rd_ptr;
		end
		endcase
	end
end

mem_data mem_dta_fifo_tx(

		.clock(clock), 
		.reset(reset), 

		.data_in(data_in),
		.wr_ptr(wr_ptr),
		.rd_ptr(rd_ptr),
		.data_out(data_out)
);

endmodule

module johnson_binary_counter (
    input clk,
    input rst_n,
    input select,
    output reg [63:0] Q
);

reg [5:0] johnson_state;
reg [3:0] binary_state;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        johnson_state <= 6'b000001;
        binary_state <= 4'b0000;
        Q <= 64'b0;
    end else begin
        if (select) begin
            // Johnson counter
            case (johnson_state)
                6'b000001: johnson_state <= 6'b000010;
                6'b000010: johnson_state <= 6'b000100;
                6'b000100: johnson_state <= 6'b001000;
                6'b001000: johnson_state <= 6'b010000;
                6'b010000: johnson_state <= 6'b100000;
                6'b100000: johnson_state <= 6'b000001;
            endcase
            Q <= {johnson_state[5], johnson_state[4], johnson_state[3], johnson_state[2], johnson_state[1], johnson_state[0], 2'b00};
        end else begin
            // Binary counter
            if (binary_state == 4'b1111) begin
                binary_state <= 4'b0000;
            end else begin
                binary_state <= binary_state + 1;
            end
            Q <= {4'b0000, binary_state};
        end
    end
end

endmodule

module top_module (
    input clk,
    input rst_n,
    input select,
    output [63:0] Q
);

wire [63:0] johnson_out;
wire [63:0] binary_out;

johnson_binary_counter johnson_counter (
    .clk(clk),
    .rst_n(rst_n),
    .select(1'b1),
    .Q(johnson_out)
);

johnson_binary_counter binary_counter (
    .clk(clk),
    .rst_n(rst_n),
    .select(select),
    .Q(binary_out)
);

assign Q = select ? binary_out : johnson_out;

endmodule

module lcd_driver (
  input [15:0] data,
  input [2:0] ctrl,
  input en,
  output [6:0] addr,
  output rw,
  output rs,
  output rst
);

  // Define control signals
  reg [2:0] cmd;
  reg [3:0] state;
  reg [15:0] lcd_data;
  reg [6:0] lcd_addr;
  reg lcd_rw;
  reg lcd_rs;
  reg lcd_rst;

  // Define timing parameters
  parameter t_setup = 10;
  parameter t_hold = 10;
  parameter t_pulse = 10;
  parameter t_wait = 100;

  // Define state machine
  localparam IDLE = 0, SEND_CMD = 1, SEND_DATA = 2, WAIT = 3;

  always @ (posedge en) begin
    if (ctrl == 3'b000) begin // Clear display
      cmd <= 3'b000;
      state <= SEND_CMD;
    end else if (ctrl == 3'b001) begin // Set cursor position
      cmd <= 3'b001;
      state <= SEND_CMD;
    end else if (ctrl == 3'b010) begin // Send data
      cmd <= 3'b010;
      state <= SEND_DATA;
    end else begin
      state <= IDLE;
    end
  end

  always @ (posedge en) begin
    case (state)
      IDLE: begin
        lcd_rw <= 1'b0;
        lcd_rs <= 1'b0;
        lcd_rst <= 1'b0;
        lcd_addr <= 7'b0000000;
        lcd_data <= 16'b0;
      end
      SEND_CMD: begin
        lcd_rw <= 1'b0;
        lcd_rs <= 1'b0;
        lcd_rst <= 1'b0;
        lcd_addr <= 7'b0000000;
        lcd_data <= {8'b0, cmd};
        state <= WAIT;
      end
      SEND_DATA: begin
        lcd_rw <= 1'b0;
        lcd_rs <= 1'b1;
        lcd_rst <= 1'b0;
        lcd_addr <= 7'b0000000;
        lcd_data <= {8'b0, data[7:0]};
        state <= WAIT;
      end
      WAIT: begin
        lcd_rw <= 1'b0;
        lcd_rs <= 1'b0;
        lcd_rst <= 1'b0;
        lcd_addr <= 7'b0000000;
        lcd_data <= 16'b0;
        state <= IDLE;
        #t_wait;
      end
      default: begin
        state <= IDLE;
      end
    endcase
  end

  // Assign outputs
  assign addr = lcd_addr;
  assign rw = lcd_rw;
  assign rs = lcd_rs;
  assign rst = lcd_rst;

endmodule

module gray_to_binary(
    input src_clk,
    input [3:0] src_in_bin,
    input dest_clk,
    output [3:0] dest_out_bin
);

    // Gray code to binary conversion logic
    wire [3:0] async_path;
    wire [2:0] binval;
    wire [3:0] dest_out_gray;
    wire [2:0] gray_enc;

    // Gray code to binary conversion
    LUT2 #(
        .INIT(4'h6)
    ) gray_ff0 (
        .I0(src_in_bin[0]),
        .I1(src_in_bin[1]),
        .O(gray_enc[0])
    );

    LUT2 #(
        .INIT(4'h6)
    ) gray_ff1 (
        .I0(src_in_bin[1]),
        .I1(src_in_bin[2]),
        .O(gray_enc[1])
    );

    LUT2 #(
        .INIT(4'h6)
    ) gray_ff2 (
        .I0(src_in_bin[2]),
        .I1(src_in_bin[3]),
        .O(gray_enc[2])
    );

    FDRE gray_ff3 (
        .C(src_clk),
        .CE(1'b1),
        .D(src_in_bin[3]),
        .Q(async_path[3]),
        .R(1'b0)
    );

    // Binary output conversion
    (* RTL_KEEP = "true" *) (* async_reg = "true" *) (* xpm_cdc = "GRAY" *)
    wire [3:0] dest_graysync_ff0;
    (* RTL_KEEP = "true" *) (* async_reg = "true" *) (* xpm_cdc = "GRAY" *)
    wire [3:0] dest_graysync_ff1;
    wire [3:0] dest_out_bin;

    (* ASYNC_REG *) 
    (* XPM_CDC = "GRAY" *) 
    FDRE dest_graysync_ff_reg0_0 (
        .C(dest_clk),
        .CE(1'b1),
        .D(async_path[0]),
        .Q(dest_graysync_ff0[0]),
        .R(1'b0)
    );

    (* ASYNC_REG *) 
    (* XPM_CDC = "GRAY" *) 
    FDRE dest_graysync_ff_reg0_1 (
        .C(dest_clk),
        .CE(1'b1),
        .D(async_path[1]),
        .Q(dest_graysync_ff0[1]),
        .R(1'b0)
    );

    (* ASYNC_REG *) 
    (* XPM_CDC = "GRAY" *) 
    FDRE dest_graysync_ff_reg0_2 (
        .C(dest_clk),
        .CE(1'b1),
        .D(async_path[2]),
        .Q(dest_graysync_ff0[2]),
        .R(1'b0)
    );

    (* ASYNC_REG *) 
    (* XPM_CDC = "GRAY" *) 
    FDRE dest_graysync_ff_reg0_3 (
        .C(dest_clk),
        .CE(1'b1),
        .D(async_path[3]),
        .Q(dest_graysync_ff0[3]),
        .R(1'b0)
    );

    (* ASYNC_REG *) 
    (* XPM_CDC = "GRAY" *) 
    FDRE dest_graysync_ff_reg1_0 (
        .C(dest_clk),
        .CE(1'b1),
        .D(dest_graysync_ff0[0]),
        .Q(dest_graysync_ff1[0]),
        .R(1'b0)
    );

    (* ASYNC_REG *) 
    (* XPM_CDC = "GRAY" *) 
    FDRE dest_graysync_ff_reg1_1 (
        .C(dest_clk),
        .CE(1'b1),
        .D(dest_graysync_ff0[1]),
        .Q(dest_graysync_ff1[1]),
        .R(1'b0)
    );

    (* ASYNC_REG *) 
    (* XPM_CDC = "GRAY" *) 
    FDRE dest_graysync_ff_reg1_2 (
        .C(dest_clk),
        .CE(1'b1),
        .D(dest_graysync_ff0[2]),
        .Q(dest_graysync_ff1[2]),
        .R(1'b0)
    );

    (* ASYNC_REG *) 
    (* XPM_CDC = "GRAY" *) 
    FDRE dest_graysync_ff_reg1_3 (
        .C(dest_clk),
        .CE(1'b1),
        .D(dest_graysync_ff0[3]),
        .Q(dest_graysync_ff1[3]),
        .R(1'b0)
    );

    LUT4 #(
        .INIT(16'h6996)
    ) dest_out_bin_ff0_i_1 (
        .I0(dest_graysync_ff1[2]),
        .I1(dest_graysync_ff1[3]),
        .I2(dest_graysync_ff1[0]),
        .I3(dest_graysync_ff1[1]),
        .O(binval[0])
    );

    LUT3 #(
        .INIT(8'h96)
    ) dest_out_bin_ff1_i_1 (
        .I0(dest_graysync_ff1[3]),
        .I1(dest_graysync_ff1[1]),
        .I2(dest_graysync_ff1[2]),
        .O(binval[1])
    );

    LUT2 #(
        .INIT(4'h6)
    ) dest_out_bin_ff2_i_1 (
        .I0(dest_graysync_ff1[3]),
        .I1(dest_graysync_ff1[2]),
        .O(binval[2])
    );

    FDRE dest_out_bin_ff_reg0 (
        .C(dest_clk),
        .CE(1'b1),
        .D(binval[0]),
        .Q(dest_out_bin[0]),
        .R(1'b0)
    );

    FDRE dest_out_bin_ff_reg1 (
        .C(dest_clk),
        .CE(1'b1),
        .D(binval[1]),
        .Q(dest_out_bin[1]),
        .R(1'b0)
    );

    FDRE dest_out_bin_ff_reg2 (
        .C(dest_clk),
        .CE(1'b1),
        .D(binval[2]),
        .Q(dest_out_bin[2]),
        .R(1'b0)
    );

    FDRE dest_out_bin_ff_reg3 (
        .C(dest_clk),
        .CE(1'b1),
        .D(dest_graysync_ff1[3]),
        .Q(dest_out_bin[3]),
        .R(1'b0)
    );

endmodule

module uart(
   // Outputs
   output wire uart_busy,   // High means UART is transmitting
   output reg uart_tx,     // UART transmit wire
   // Inputs
   input uart_wr_i,   // Raise to transmit byte
   input [7:0]uart_dat_i,  // 8-bit data
   input sys_clk_i,   // System clock, 68 MHz
   input sys_rst_i    // System reset
);

  reg [3:0] bitcount;
  reg [8:0] shifter;

  assign uart_busy = |bitcount[3:1];
  assign sending = |bitcount;

  // sys_clk_i is 50MHz.  We want a 115200Hz clock

  reg [28:0] d;
  wire [28:0] dInc = d[28] ? (115200) : (115200 - 50000000);
  wire [28:0] dNxt = d + dInc;
  always @(posedge sys_clk_i)
  begin
    d = dNxt;
  end
  wire ser_clk = ~d[28]; // this is the 115200 Hz clock

  always @(posedge sys_clk_i)
  begin
    if (sys_rst_i) begin
      uart_tx <= 1;
      bitcount <= 0;
      shifter <= 0;
    end else begin
      // just got a new byte
      if (uart_wr_i & ~uart_busy) begin
        shifter <= { uart_dat_i[7:0], 1'h0 };
        bitcount <= (1 + 8 + 2);
      end

      if (sending & ser_clk) begin
        { shifter, uart_tx } <= { 1'h1, shifter };
        bitcount <= bitcount - 1;
      end
    end
  end

endmodule

module up_down_counter (
    input clk, // Clock signal
    input enable, // Enable signal
    input reset, // Reset signal
    input up_down, // Direction signal
    output reg [3:0] count, // Count value
    output reg direction // Direction signal
);

    always @(posedge clk) begin
        if (reset) begin
            count <= 0;
            direction <= 1;
        end else if (enable) begin
            if (up_down) begin
                count <= count + 1;
                direction <= 1;
            end else begin
                count <= count - 1;
                direction <= 0;
            end
        end
    end

endmodule

module speaker_i2c_controller (
	CLOCK,
	I2C_SCLK,//I2C CLOCK
 	I2C_SDAT,//I2C DATA
	I2C_DATA,//DATA:[SLAVE_ADDR,SUB_ADDR,DATA]
	GO,      //GO transfor
	END,     //END transfor 
	W_R,     //W_R
	ACK,      //ACK
	RESET
);
	input  CLOCK;
	input  [23:0]I2C_DATA;	
	input  GO;
	input  RESET;	
	input  W_R;
 	inout  I2C_SDAT;	
	output I2C_SCLK;
	output END;	
	output ACK;


reg SDO;
reg SCLK;
reg END;
reg [23:0]SD;
reg [5:0]SD_COUNTER;

wire I2C_SCLK=SCLK | ( ((SD_COUNTER >= 4) & (SD_COUNTER <=30))? ~CLOCK :1'b0 );
wire I2C_SDAT=SDO?1'bz:1'b0 ;

reg ACK1,ACK2,ACK3;
wire ACK=ACK1 | ACK2 |ACK3;

  //--I2C COUNTER
  always @(posedge CLOCK)begin
    if (RESET)
      SD_COUNTER <= 6'b111111;
    else
      begin
        if (!GO)
          SD_COUNTER <= 6'd0;
        else
          if (SD_COUNTER < 6'b111111) SD_COUNTER <= SD_COUNTER + 6'b1;
        end
      end
  //----

  always @(posedge CLOCK)
    begin
      if (RESET)
        begin
          SCLK <= 1'b1;
          SDO  <= 1'b1;
          ACK1 <= 1'b0;
          ACK2 <= 1'b0;
          ACK3 <= 1'b0;
          END  <= 1'b1;
        end
      else
        case (SD_COUNTER)
          6'd0:
            begin
              ACK1 <= 1'b0;
              ACK2 <= 1'b0;
              ACK3 <= 1'b0;
              END  <= 1'b0;
              SDO  <= 1'b1;
              SCLK <= 1'b1;
            end

          //start
          6'd1:
            begin
              SD  <= I2C_DATA;
              SDO <= 1'b0;
            end

          6'd2: SCLK <= 1'b0;

          //SLAVE ADDR
          6'd3: SDO  <= SD[23];
	6'd4  : SDO<=SD[22];
	6'd5  : SDO<=SD[21];
	6'd6  : SDO<=SD[20];
	6'd7  : SDO<=SD[19];
	6'd8  : SDO<=SD[18];
	6'd9  : SDO<=SD[17];
	6'd10 : SDO<=SD[16];	
	6'd11 : SDO<=1'b1;//ACK

	//SUB ADDR
	6'd12  : begin SDO<=SD[15]; ACK1<=I2C_SDAT; end
	6'd13  : SDO<=SD[14];
	6'd14  : SDO<=SD[13];
	6'd15  : SDO<=SD[12];
	6'd16  : SDO<=SD[11];
	6'd17  : SDO<=SD[10];
	6'd18  : SDO<=SD[9];
	6'd19  : SDO<=SD[8];
	6'd20  : SDO<=1'b1;//ACK

	//DATA
	6'd21  : begin SDO<=SD[7]; ACK2<=I2C_SDAT; end
	6'd22  : SDO<=SD[6];
	6'd23  : SDO<=SD[5];
	6'd24  : SDO<=SD[4];
	6'd25  : SDO<=SD[3];
	6'd26  : SDO<=SD[2];
	6'd27  : SDO<=SD[1];
	6'd28  : SDO<=SD[0];
	6'd29  : SDO<=1'b1;//ACK


	//stop
    6'd30 : begin SDO<=1'b0;	SCLK<=1'b0; ACK3<=I2C_SDAT; end	
    6'd31 : SCLK<=1'b1; 
    6'd32 : begin SDO<=1'b1; END<=1; end 

endcase
end



endmodule

module pipelined_decoder (
    input [1:0] in,
    output reg [15:0] out
);

reg [15:0] stage1_out;
reg [15:0] stage2_out;
reg [15:0] stage3_out;

always @ (posedge clk) begin
    stage1_out <= {16{1'b0}};
    stage1_out[in] <= 1'b1;
end

always @ (posedge clk) begin
    stage2_out <= stage1_out;
end

always @ (posedge clk) begin
    stage3_out <= stage2_out;
end

assign out = stage3_out;

endmodule

module VGA7SegDisplay(
  input [9:0] digitXPosition, digitYPosition, xpos, ypos,
  input [3:0] digit,
  output reg digitpixel
);

parameter SegmentWidth = 10'd20, SegmentHeight = 10'd28, lineWidth = 10'd4;

wire segmentA = (xpos >= digitXPosition+lineWidth && xpos <= digitXPosition+SegmentWidth-4 && ypos >= digitYPosition && ypos <= digitYPosition+lineWidth-1);
wire segmentB = (xpos >= digitXPosition+SegmentWidth-lineWidth && xpos <= digitXPosition+SegmentWidth-1 && ypos >= digitYPosition && ypos <= digitYPosition+SegmentHeight/2-2);
wire segmentC = (xpos >= digitXPosition+SegmentWidth-lineWidth && xpos <= digitXPosition+SegmentWidth-1 && ypos >= digitYPosition+SegmentHeight/2+2 && ypos <= digitYPosition+SegmentHeight-1);
wire segmentD = (xpos >= digitXPosition+lineWidth && xpos <= digitXPosition+SegmentWidth-4 && ypos >= digitYPosition+SegmentHeight-lineWidth && ypos <= digitYPosition+SegmentHeight-1);
wire segmentE = (xpos >= digitXPosition && xpos <= digitXPosition+lineWidth-1 && ypos >= digitYPosition+SegmentHeight/2+2 && ypos <= digitYPosition+SegmentHeight-1);
wire segmentF = (xpos >= digitXPosition && xpos <= digitXPosition+lineWidth-1 && ypos >= digitYPosition && ypos <= digitYPosition+SegmentHeight/2-2);
wire segmentG = (xpos >= digitXPosition+lineWidth && xpos <= digitXPosition+SegmentWidth-1 && ypos >= digitYPosition+(SegmentHeight-lineWidth)/2 && ypos <= digitYPosition+(SegmentHeight+lineWidth)/2);

always @(digit,segmentA,segmentA,segmentB,segmentC,segmentD,segmentE,segmentF,segmentG) begin
  case (digit) 
    0: digitpixel <= (segmentA | segmentB | segmentC | segmentD | segmentE | segmentF );
    1: digitpixel <= (segmentB | segmentC );
    2: digitpixel <= (segmentA | segmentB | segmentD | segmentE | segmentG );
    3: digitpixel <= (segmentA | segmentB | segmentC | segmentD | segmentG );
    4: digitpixel <= (segmentB | segmentC | segmentF | segmentG );
    5: digitpixel <= (segmentA | segmentC | segmentD | segmentF | segmentG );
    6: digitpixel <= (segmentA | segmentC | segmentD | segmentE | segmentF | segmentG );
    7: digitpixel <= (segmentA | segmentB | segmentC );
    8: digitpixel <= (segmentA | segmentB | segmentC | segmentD | segmentE | segmentF | segmentG );
    9: digitpixel <= (segmentA | segmentB | segmentC | segmentD | segmentF | segmentG );
    default: digitpixel <= 0;
  endcase
end

endmodule

module top_module (
    input UD,
    input CLK,
    input RST,
    input LD,
    input SEL,
    input signed [3:0] A,
    input signed [3:0] B,
    output reg signed [3:0] C,
    output reg [3:0] Q
);

// Up-Down Counter Module
reg [3:0] count;
always @(posedge CLK or negedge RST) begin
    if (RST == 0) begin
        count <= 4'b0000;
    end else if (UD == 1) begin
        count <= count + 1;
    end else if (UD == 0) begin
        count <= count - 1;
    end
end

// Booth's Multiplier Module
reg [7:0] product;
reg [3:0] multiplicand;
always @(posedge CLK or negedge RST) begin
    if (RST == 0) begin
        product <= 8'b00000000;
        multiplicand <= 4'b0000;
    end else begin
        case ({product[0], A[3:2]}) 
            2'b01: begin
                product <= {product[7:1], A[1:0], 1'b0};
                multiplicand <= multiplicand + B;
            end
            2'b10: begin
                product <= {product[7:1], A[1:0], 1'b0};
                multiplicand <= multiplicand - B;
            end
            2'b11: begin
                product <= {product[7:1], A[1:0], 1'b0};
            end
            default: begin
                product <= {product[7:1], A[1:0], 1'b0};
            end
        endcase
    end
end
assign C = product[7:4];
assign Q = (SEL == 1) ? multiplicand : count;

// Functional Module
reg signed [3:0] sum;
always @(posedge CLK or negedge RST) begin
    if (RST == 0) begin
        sum <= 4'b0000;
    end else begin
        sum <= Q + C;
    end
end

endmodule

