module inv_trig (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 1; // number of input signals
parameter m = 3; // number of output signals

// Define mathematical constants
parameter pi = 3.141592653589793;
parameter half_pi = 1.570796326794897;
parameter two_pi = 6.283185307179586;

// Define local variables
reg signed [31:0] x;
reg signed [31:0] y;
reg signed [31:0] z;
reg signed [31:0] w;

// Calculate arcsine
always @(*) begin
  if (in >= 1) begin
    out[0] = half_pi;
  end else if (in <= -1) begin
    out[0] = -half_pi;
  end else begin
    x = in;
    y = $signed($clog2(x));
    z = $signed($clog2(y));
    w = z + 1;
    out[0] = $signed($itor(w)) * pi / 2 - $signed($itor(y)) * pi / 4 + x * (0.15504 + x * (-0.009572 + x * 0.001204));
  end
end

// Calculate arccosine
always @(*) begin
  if (in >= 1) begin
    out[1] = 0;
  end else if (in <= -1) begin
    out[1] = pi;
  end else begin
    out[1] = half_pi - out[0];
  end
end

// Calculate arctangent
always @(*) begin
  out[2] = atan2(in, 1);
end

endmodule

module altera_reset_synchronizer
#(
    parameter ASYNC_RESET = 1,
    parameter DEPTH       = 2
)
(
    input   reset_in /* synthesis ALTERA_ATTRIBUTE = "SUPPRESS_DA_RULE_INTERNAL=R101" */,

    input   clk,
    output  reset_out
);

    // -----------------------------------------------
    // Synchronizer register chain. We cannot reuse the
    // standard synchronizer in this implementation 
    // because our timing constraints are different.
    //
    // Instead of cutting the timing path to the d-input 
    // on the first flop we need to cut the aclr input.
    // 
    // We omit the "preserve" attribute on the final
    // output register, so that the synthesis tool can
    // duplicate it where needed.
    // -----------------------------------------------
    (*preserve*) reg [DEPTH-1:0] altera_reset_synchronizer_int_chain;
    reg altera_reset_synchronizer_int_chain_out;

    generate if (ASYNC_RESET) begin

        // -----------------------------------------------
        // Assert asynchronously, deassert synchronously.
        // -----------------------------------------------
        always @(posedge clk or posedge reset_in) begin
            if (reset_in) begin
                altera_reset_synchronizer_int_chain <= {DEPTH{1'b1}};
                altera_reset_synchronizer_int_chain_out <= 1'b1;
            end
            else begin
                altera_reset_synchronizer_int_chain[DEPTH-2:0] <= altera_reset_synchronizer_int_chain[DEPTH-1:1];
                altera_reset_synchronizer_int_chain[DEPTH-1] <= 0;
                altera_reset_synchronizer_int_chain_out <= altera_reset_synchronizer_int_chain[0];
            end
        end

        assign reset_out = altera_reset_synchronizer_int_chain_out;

    end else begin

        // -----------------------------------------------
        // Assert synchronously, deassert synchronously.
        // -----------------------------------------------
        always @(posedge clk) begin
            altera_reset_synchronizer_int_chain[DEPTH-2:0] <= altera_reset_synchronizer_int_chain[DEPTH-1:1];
            altera_reset_synchronizer_int_chain[DEPTH-1] <= reset_in;
            altera_reset_synchronizer_int_chain_out <= altera_reset_synchronizer_int_chain[0];
        end

        assign reset_out = altera_reset_synchronizer_int_chain_out;

    end
    endgenerate

endmodule

