module adder_subtractor(
  input [3:0] A,
  input [3:0] B,
  input C,
  output [3:0] S
);

  wire [3:0] B_comp; // complement of B
  wire [3:0] carry_in; // carry in for subtraction
  wire [3:0] sum; // sum of A and B
  wire [3:0] diff; // difference of A and B

  // compute the complement of B
  assign B_comp = ~B + 1;

  // compute the carry in for subtraction
  assign carry_in = C ? B_comp : 1'b0;

  // compute the sum and difference
  assign sum = A + B;
  assign diff = A + B_comp + carry_in;

  // select the output based on the control input C
  assign S = C ? diff : sum;

endmodule

module shift_reg_comb (
    input clk,          // Clock input
    input d,            // Input for shift register
    input [3:0] in,     // Input for combinational circuit
    output out_and,     // 2-level AND-OR circuit output
    output out_or,      // 2-level OR-AND circuit output
    output out_xor,     // 2-level XOR-AND circuit output
    output [7:0] sum    // Sum of shift register and combinational circuit outputs
);

reg [2:0] shift_reg;
wire q;

// Shift register
always @(posedge clk) begin
    shift_reg <= {shift_reg[1:0], d};
end

assign q = shift_reg[2];

// Combinational circuit
wire and1 = in[0] & in[1];
wire and2 = in[2] & in[3];
wire or1 = in[0] | in[1];
wire or2 = in[2] | in[3];
wire xor1 = in[0] ^ in[1];
wire xor2 = in[2] ^ in[3];

assign out_and = and1 | and2;
assign out_or = or1 & or2;
assign out_xor = xor1 & xor2;

// Sum module
wire [7:0] shift_sum = {1'b0, shift_reg};
wire [7:0] comb_sum = {1'b0, out_and, out_or, out_xor};

assign sum = shift_sum + comb_sum;

endmodule

module gray_shift (
    input clk,
    input reset,
    input ena,
    input parallel_load,
    input serial_in,
    output serial_out,
    output reg [3:0] q,
    input [3:0] data_in
);

    reg [3:0] gray_q;
    reg [3:0] shift_reg;

    // Gray code counter
    always @(posedge clk) begin
        if (reset) begin
            gray_q <= 4'b0000;
        end else if (ena) begin
            gray_q <= gray_q + 1;
        end else begin
            gray_q <= gray_q - 1;
        end
    end

    // Shift register
    always @(posedge clk) begin
        if (parallel_load) begin
            shift_reg <= data_in;
        end else begin
            shift_reg <= {shift_reg[2:0], serial_in};
        end
    end

    // XOR module
    assign serial_out = shift_reg[0] ^ gray_q[0];
    assign q = gray_q;

endmodule

