module fifo(CLK, DIN, RST, IN_EN, OUT_EN, DOUT, FULL, EMPTY);
  input CLK;
  input [18:0] DIN;
  input RST;
  input IN_EN;
  input OUT_EN;
  output reg [18:0] DOUT;
  output reg FULL;
  output reg EMPTY;

  // Declare internal signals
  wire [3:0] cnthead;
  wire [3:0] cnttail;
  wire [18:0] fifo [0:15];
  reg [18:0] DOUT_temp;
  reg [4:0] fcnt;
  reg [1:0] state;
  reg [1:0] next_state;
  reg [1:0] ctrl;
  reg [3:0] cnt;

  // Define control states
  parameter NOTHING = 2'b00;
  parameter HEAD = 2'b01;
  parameter BODY = 2'b10;
  parameter TAIL = 2'b11;

  // Initialize internal signals
  assign cnthead = cnt[3:0];
  assign cnttail = cnt[7:4];
  assign FULL = (fcnt == 15) ? 1 : 0;
  assign EMPTY = (fcnt == 0) ? 1 : 0;

  // Counter for FIFO depth
  always @(posedge CLK or posedge RST) begin
    if (RST) begin
      fcnt <= 0;
    end else if ((IN_EN && !OUT_EN) || (!IN_EN && OUT_EN)) begin
      fcnt <= fcnt + 1;
    end
  end

  // Counter for head pointer
  always @(posedge CLK or posedge RST) begin
    if (RST) begin
      cnt[3:0] <= 0;
    end else if (state == HEAD) begin
      cnt[3:0] <= cnt[3:0] + 1;
    end
  end

  // Counter for tail pointer
  always @(posedge CLK or posedge RST) begin
    if (RST) begin
      cnt[7:4] <= 0;
    end else if (state == TAIL) begin
      cnt[7:4] <= cnt[7:4] + 1;
    end
  end

  // Write data into FIFO
  always @(posedge CLK) begin
    if (IN_EN && state == BODY) begin
      fifo[cnt[7:4]] <= DIN;
      ctrl <= 2'b10;
    end else if (IN_EN && state == HEAD) begin
      fifo[cnt[3:0]] <= DIN;
      ctrl <= 2'b01;
    end else begin
      ctrl <= 2'b00;
    end
  end

  // Read data from FIFO
  always @(posedge CLK) begin
    if (OUT_EN && state == BODY) begin
      DOUT_temp <= fifo[cnt[3:0]];
      ctrl <= 2'b10;
    end else if (OUT_EN && state == TAIL) begin
      DOUT_temp <= fifo[cnt[7:4]];
      ctrl <= 2'b11;
    end else begin
      DOUT_temp <= 19'h00000;
      ctrl <= 2'b00;
    end
  end

  // State machine to control head, body, and tail pointers
  always @(posedge CLK or posedge RST) begin
    if (RST) begin
      state <= NOTHING;
      next_state <= NOTHING;
    end else begin
      state <= next_state;
    end

    case (state)
      NOTHING: begin
        if (IN_EN) begin
          next_state <= HEAD;
        end else if (OUT_EN) begin
          next_state <= TAIL;
        end else begin
          next_state <= NOTHING;
        end
      end

      HEAD: begin
        if (ctrl == 2'b01) begin
          next_state <= BODY;
        end else begin
          next_state <= HEAD;
        end
      end

      BODY: begin
        if (FULL) begin
          next_state <= TAIL;
        end else if (!IN_EN) begin
          next_state <= HEAD;
        end else begin
          next_state <= BODY;
        end
      end

      TAIL: begin
        if (ctrl == 2'b11) begin
          next_state <= BODY;
        end else begin
          next_state <= TAIL;
        end
      end
    endcase
  end

  // Assign output signals
  assign DOUT = DOUT_temp;
endmodule

module my_uart_tx8to8(
	clk,
	rst_n,
	uart_ctl,
	data_out,
	data_sign,
	data_valid,
	rs_tx
);

	input clk;
	input rst_n;
	input [2:0] uart_ctl;
	input [7:0] data_out;
	input data_sign;
	output data_valid;
	output rs_tx;

	parameter bps9600 = 13'd5208;
	parameter bps19200 = 13'd2603;
	parameter bps38400 = 13'd1301;
	parameter bps57600 = 13'd867;
	parameter bps115200 = 13'd434;
	parameter bps256000 = 13'd195;

	reg [12:0] cnt;
	reg bps_sel;
	reg [3:0] tran_cnt;
	reg rs_tx;
	reg sign_delay;
	reg data_valid;

	always @(posedge clk or negedge rst_n) begin
		if (!rst_n) begin
			bps_sel <= 1'b0;
			cnt <= 'h0;
		end
		else begin
			case (uart_ctl)
				3'h0: cnt <= (cnt == bps9600) ? 'h0 : cnt + 1'b1;
				3'h1: cnt <= (cnt == bps19200) ? 'h0 : cnt + 1'b1;
				3'h2: cnt <= (cnt == bps38400) ? 'h0 : cnt + 1'b1;
				3'h3: cnt <= (cnt == bps57600) ? 'h0 : cnt + 1'b1;
				3'h4: cnt <= (cnt == bps115200) ? 'h0 : cnt + 1'b1;
				3'h5: cnt <= (cnt == bps256000) ? 'h0 : cnt + 1'b1;
				default: cnt <= (cnt == bps9600) ? 'h0 : cnt + 1'b1;
			endcase
			bps_sel <= ~|cnt;
		end
	end

	always @(posedge clk or negedge rst_n) begin
		if (!rst_n) begin
			sign_delay <= 1'b0;
			data_valid <= 1'b0;
		end
		else begin
			if (bps_sel) sign_delay <= 1'b0;
			else if (data_sign) sign_delay <= 1'b1;
			if (data_sign | sign_delay) data_valid <= 1'b0;
			else if (tran_cnt == 9) data_valid <= 1'b1;
		end
	end

	always @(posedge clk or negedge rst_n) begin
		if (!rst_n) begin
			tran_cnt <= 'h9;
		end
		else if (bps_sel) begin
			if (tran_cnt != 9) tran_cnt <= tran_cnt + 1'b1;
			else if (data_sign | sign_delay) tran_cnt <= 'h0;
		end
	end

	always @(posedge clk or negedge rst_n) begin
		if (!rst_n) begin
			rs_tx <= 1'b1;
		end
		else if (bps_sel) begin
			if (tran_cnt == 0) rs_tx <= 1'b0;
			else if (tran_cnt == 9) rs_tx <= 1'b1;
			else rs_tx <= data_out[tran_cnt - 1];
		end
	end

endmodule

module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out
);

reg [7:0] acc_reg;
reg [7:0] booth_reg;
reg [1:0] booth_sel;

assign ready_a = ~valid_b;
assign booth_sel = {booth_reg[7], data_in[7]};
assign data_out = acc_reg;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        acc_reg <= 0;
        booth_reg <= 0;
        valid_b <= 0;
    end else begin
        if (valid_a && ready_b) begin
            booth_reg <= {booth_reg[6:0], booth_sel};
            case (booth_sel)
                2'b00: acc_reg <= acc_reg + data_in;
                2'b01: acc_reg <= acc_reg + (data_in >> 1);
                2'b10: acc_reg <= acc_reg + (data_in << 1);
                2'b11: acc_reg <= acc_reg + (~data_in + 1);
            endcase
            if (booth_sel[1]) begin
                valid_b <= 1;
            end
        end
        if (valid_b && ready_a) begin
            valid_b <= 0;
        end
    end
end

endmodule

module Booth_Multiplier (
  input [3:0] A,
  input [3:0] B,
  output [7:0] P
);

  // 4-bit unsigned binary numbers
  // A and B are inputs, P is the output

  // Example: A = 0101, B = 0011, P = 00010011

  // Convert A and B to signed numbers
  reg [4:0] A_signed = {1'b0, A};
  reg [4:0] B_signed = {1'b0, B};

  // Booth algorithm
  reg [7:0] partial_product = 8'b0;
  always @(*) begin
    case (B_signed[1:0])
      2'b00: partial_product = {4'b0, A_signed};
      2'b01: partial_product = {4'b0, A_signed} - A_signed;
      2'b10: partial_product = {4'b0, A_signed} + A_signed;
      2'b11: partial_product = {4'b0, A_signed};
    endcase
  end

  // 8-bit adder
  reg [7:0] sum = 8'b0;
  always @(*) begin
    sum = partial_product + {4'b0, B_signed};
  end

  // Output
  assign P = sum;

endmodule

