module top_module (
    input [1:0] counter_input,
    input [1:0] decoder_input,
    input clk,
    input reset,
    output reg [15:0] shift_reg_output,
    output reg final_output
);

    // Instantiate 4-to-16 decoder using NAND gates
    wire [15:0] decoder_output;
    nand #(.N(4)) nand_gate_1(decoder_output[0], decoder_input[0], decoder_input[1], decoder_input[0], decoder_input[1]);
    nand #(.N(4)) nand_gate_2(decoder_output[1], decoder_input[0], decoder_input[1], decoder_input[0], ~decoder_input[1]);
    nand #(.N(4)) nand_gate_3(decoder_output[2], decoder_input[0], decoder_input[1], ~decoder_input[0], decoder_input[1]);
    nand #(.N(4)) nand_gate_4(decoder_output[3], decoder_input[0], decoder_input[1], ~decoder_input[0], ~decoder_input[1]);
    nand #(.N(4)) nand_gate_5(decoder_output[4], decoder_input[0], ~decoder_input[1], decoder_input[0], decoder_input[1]);
    nand #(.N(4)) nand_gate_6(decoder_output[5], decoder_input[0], ~decoder_input[1], decoder_input[0], ~decoder_input[1]);
    nand #(.N(4)) nand_gate_7(decoder_output[6], decoder_input[0], ~decoder_input[1], ~decoder_input[0], decoder_input[1]);
    nand #(.N(4)) nand_gate_8(decoder_output[7], decoder_input[0], ~decoder_input[1], ~decoder_input[0], ~decoder_input[1]);
    nand #(.N(4)) nand_gate_9(decoder_output[8], ~decoder_input[0], decoder_input[1], decoder_input[0], decoder_input[1]);
    nand #(.N(4)) nand_gate_10(decoder_output[9], ~decoder_input[0], decoder_input[1], decoder_input[0], ~decoder_input[1]);
    nand #(.N(4)) nand_gate_11(decoder_output[10], ~decoder_input[0], decoder_input[1], ~decoder_input[0], decoder_input[1]);
    nand #(.N(4)) nand_gate_12(decoder_output[11], ~decoder_input[0], decoder_input[1], ~decoder_input[0], ~decoder_input[1]);
    nand #(.N(4)) nand_gate_13(decoder_output[12], ~decoder_input[0], ~decoder_input[1], decoder_input[0], decoder_input[1]);
    nand #(.N(4)) nand_gate_14(decoder_output[13], ~decoder_input[0], ~decoder_input[1], decoder_input[0], ~decoder_input[1]);
    nand #(.N(4)) nand_gate_15(decoder_output[14], ~decoder_input[0], ~decoder_input[1], ~decoder_input[0], decoder_input[1]);
    nand #(.N(4)) nand_gate_16(decoder_output[15], ~decoder_input[0], ~decoder_input[1], ~decoder_input[0], ~decoder_input[1]);

    // Create 2-bit binary counter
    reg [1:0] counter;
    always @(posedge clk) begin
        if (reset) begin
            counter <= 2'b00;
        end else if (counter == 2'b11) begin
            counter <= 2'b00;
        end else begin
            counter <= counter + 1;
        end
    end

    // Implement 16-bit shift register using D flip-flops
    reg [15:0] shift_reg;
    always @(posedge clk) begin
        if (reset) begin
            shift_reg <= 16'b0000000000000000;
        end else begin
            shift_reg <= {shift_reg[14:0], counter_input};
        end
    end

    // Combine shift register output with decoder output using logical AND operation
    always @(posedge clk) begin
        if (reset) begin
            shift_reg_output <= 16'b0000000000000000;
            final_output <= 1'b0;
        end else begin
            shift_reg_output <= shift_reg;
            final_output <= decoder_output[counter] & shift_reg_output[counter];
        end
    end

endmodule

