module BOR (
  input voltage,
  input reset,
  input threshold,
  output reg bor_reset
);

  reg prev_voltage;

  always @(posedge voltage) begin
    if (voltage < threshold) begin
      bor_reset <= 1;
    end else if (voltage >= threshold && prev_voltage < threshold) begin
      bor_reset <= 0;
    end
    prev_voltage <= voltage;
  end

  always @(posedge reset) begin
    bor_reset <= 1;
  end

  assign bor_reset = bor_reset || reset;

endmodule

module priority_encoder (
    input [7:0] in,
    output reg [2:0] out,
    output valid,
    output reg [2:0] priority
);

    reg [7:0] in_reg;
    reg [2:0] out_reg;
    reg [2:0] priority_reg;
    reg [2:0] priority_next;
    reg valid_reg;
    reg valid_next;

    always @(posedge clk) begin
        in_reg <= in;
        priority_reg <= priority_next;
        valid_reg <= valid_next;
        out_reg <= out;
    end

    always @(posedge clk) begin
        priority_next = 3'b000;
        valid_next = 1'b0;
        case(in_reg)
            8'b10000000: begin
                priority_next = 3'b111;
                valid_next = 1'b1;
            end
            8'b01000000: begin
                priority_next = 3'b110;
                valid_next = 1'b1;
            end
            8'b00100000: begin
                priority_next = 3'b101;
                valid_next = 1'b1;
            end
            8'b00010000: begin
                priority_next = 3'b100;
                valid_next = 1'b1;
            end
            8'b00001000: begin
                priority_next = 3'b011;
                valid_next = 1'b1;
            end
            8'b00000100: begin
                priority_next = 3'b010;
                valid_next = 1'b1;
            end
            8'b00000010: begin
                priority_next = 3'b001;
                valid_next = 1'b1;
            end
            8'b00000001: begin
                priority_next = 3'b000;
                valid_next = 1'b1;
            end
            default: begin
                priority_next = priority_reg;
                valid_next = valid_reg;
            end
        endcase
    end

    always @(posedge clk) begin
        if(valid_reg) begin
            out <= priority_reg;
        end else begin
            out <= 3'b000;
        end
        priority <= priority_reg;
        valid <= valid_reg;
    end

endmodule

