module fifo_32x128 (
	data,
	wrreq,
	rdreq,
	clock,
	aclr,
	q,
	full,
	empty,
	usedw);

	input	[31:0]  data;
	input	  wrreq;
	input	  rdreq;
	input	  clock;
	input	  aclr;
	output	[31:0]  q;
	output	  full;
	output	  empty;
	output	[6:0]  usedw;

	reg [31:0] buffer[0:31];
	reg [5:0] head = 0;
	reg [5:0] tail = 0;
	reg [6:0] usedw_reg = 0;
	wire full_reg = (usedw_reg == 32);
	wire empty_reg = (usedw_reg == 0);

	always @(posedge clock) begin
		if (aclr) begin
			head <= 0;
			tail <= 0;
			usedw_reg <= 0;
		end else begin
			if (wrreq && !full_reg) begin
				buffer[head] <= data;
				head <= (head + 1) % 32;
				usedw_reg <= usedw_reg + 1;
			end
			if (rdreq && !empty_reg) begin
				q <= buffer[tail];
				tail <= (tail + 1) % 32;
				usedw_reg <= usedw_reg - 1;
			end
		end
	end

	assign full = full_reg;
	assign empty = empty_reg;
	assign usedw = usedw_reg;

endmodule

