module priority_encoder (
    input [7:0] in,
    output reg [2:0] pos );

    wire [7:0] gray;
    wire [2:0] dec;

    // Binary-to-Gray code conversion
    assign gray = in ^ (in >> 1);

    // Binary-to-Decimal decoding
    assign dec = {gray[7], gray[6], gray[5], gray[4], gray[3], gray[2], gray[1], gray[0]};

    always @* begin
        case(dec)
            8'b00000001: pos = 0;
            8'b00000011: pos = 1;
            8'b00000111: pos = 2;
            8'b00001111: pos = 3;
            8'b00011111: pos = 4;
            8'b00111111: pos = 5;
            8'b01111111: pos = 6;
            8'b11111111: pos = 7;
            default: pos = 0;
        endcase
    end

endmodule

