module crystal_oscillator_interface (
  input osc_in,
  input reset,
  input clk_enable,
  output reg clk_out
);

parameter osc_freq = 50e6; // frequency of the crystal oscillator
parameter clk_div = 2; // clock divider value

reg [31:0] counter;

always @ (posedge osc_in or posedge reset) begin
  if (reset) begin
    counter <= 0;
    clk_out <= 0;
  end else begin
    counter <= counter + 1;
    if (counter == osc_freq / (2 * clk_div)) begin
      counter <= 0;
      if (clk_enable) begin
        clk_out <= ~clk_out;
      end
    end
  end
end

endmodule

module top_module (
    input clk,
    input reset,
    input [7:0] in,
    output reg valid
);

    wire [7:0] rising_edge;
    wire [8:0] parity_byte;
    wire valid_input;

    edge_detector ed (
        .clk(clk),
        .in(in),
        .rising_edge(rising_edge)
    );

    parity_generator pg (
        .in(in),
        .out(parity_byte)
    );

    and_gate ag (
        .rising_edge(rising_edge),
        .parity_bit(parity_byte[8]),
        .valid_input(valid_input)
    );

    always @(posedge clk) begin
        if (reset) begin
            valid <= 0;
        end else begin
            valid <= valid_input;
        end
    end

