module edge_transition_color_controller (
  input clk,
  input reset,
  input [7:0] in,
  input [2:0] sel,
  input [4:0] color0,
  input [4:0] color1,
  input [4:0] color2,
  input [4:0] color3,
  input [4:0] color4,
  input [4:0] color5,
  output reg [5:0] led_display
);

  reg [2:0] counter;
  reg [7:0] prev_in;
  reg [2:0] edge_detected;
  reg [4:0] priority;
  reg [4:0] data_out;

  always @(posedge clk) begin
    if (reset) begin
      counter <= 0;
      prev_in <= 0;
      edge_detected <= 0;
      priority <= 0;
      data_out <= 0;
      led_display <= 0;
    end else begin
      prev_in <= in;
      counter <= counter + 1;
      if (in[0] == 0 && prev_in[0] == 1) begin
        edge_detected <= counter;
      end
      if (sel <= 5) begin
        case (sel)
          0: data_out <= color0;
          1: data_out <= color1;
          2: data_out <= color2;
          3: data_out <= color3;
          4: data_out <= color4;
          5: data_out <= color5;
        endcase
      end else begin
        data_out <= 16'b1;
      end
    end
  end

  always @(*) begin
    if (edge_detected != 0) begin
      priority[0] = (edge_detected >= 4'b0001) ? 1 : 0;
      priority[1] = (edge_detected >= 4'b0010) ? 1 : 0;
      priority[2] = (edge_detected >= 4'b0100) ? 1 : 0;
      priority[3] = (edge_detected >= 4'b1000) ? 1 : 0;
      casez (priority)
        4'b0001: led_display = {1'b1, data_out[4:0]};
        4'b0010: led_display = {1'b1, data_out[4:0]};
        4'b0100: led_display = {1'b1, data_out[4:0]};
        4'b1000: led_display = {1'b1, data_out[4:0]};
        default: led_display = 6'b000000;
      endcase
    end else begin
      led_display = 6'b000000;
    end
  end

endmodule

