module top_module (
    input clk,
    input reset,
    input [7:0] d,
    output [8:0] q
);

    reg [7:0] d_ff;
    wire [7:0] d_ff_next;
    wire parity_bit;
    wire [8:0] final_output;

    // Instantiate D flip-flop module
    d_flip_flop dff (
        .clk(clk),
        .reset(reset),
        .d(d),
        .q(d_ff_next)
    );

    // Instantiate parity bit generator module
    parity_generator pg (
        .data_in(d_ff_next),
        .parity_out(parity_bit)
    );

    // Functional module to perform XOR operation
    assign final_output = {d_ff_next, parity_bit};

    // Assign outputs
    assign q = final_output;

    // Negative edge trigger for D flip-flop
    always @(negedge clk, posedge reset) begin
        if (reset) begin
            d_ff <= 8'h34;
        end else begin
            d_ff <= d_ff_next;
        end
    end

endmodule

