module d_flip_flop (
    input clk,
    input reset,
    input [7:0] d,
    output reg [7:0] q
);

    always @(negedge clk, posedge reset) begin
        if (reset) begin
            q <= 8'h34;
        end else begin
            q <= d;
        end
    end

endmodule

// Parity bit generator module
module parity_generator (
    input [7:0] data_in,
    output reg parity_out
);

    always @(*) begin
        case ({data_in})
            8'b00000001, 8'b00000010, 8'b00000100, 8'b00001000, 8'b00010000, 8'b00100000, 8'b01000000, 8'b10000000: parity_out = 1'b1;
            default: parity_out = 1'b0;
        endcase
    end

endmodule

