    parameter RAM_ADDR_LSB = 0)
  (input aclk,
   input s_axis_data_tvalid,
   input [FREQ_WIDTH + PHASE_WIDTH - 1:0] s_axis_data_tdata,
   output m_axis_data_tvalid,
   output [DATA_WIDTH - 1:0] m_axis_data_tdata);

  wire [ADDR_WIDTH - 1:0] ram_addr;
  wire [DATA_WIDTH - 1:0] ram_data;

  // Instantiate the internal RAM.
  dds_ram #(.DATA_WIDTH(DATA_WIDTH),
             .ADDR_WIDTH(ADDR_WIDTH),
             .RAM_DEPTH(RAM_DEPTH),
             .RAM_STYLE(RAM_STYLE),
             .RAM_INIT(RAM_INIT),
             .RAM_ADDR_MSB(RAM_ADDR_MSB),
             .RAM_ADDR_LSB(RAM_ADDR_LSB)) ram_inst
    (.aclk(aclk),
     .addr(ram_addr),
     .data(ram_data));

  // Extract the frequency and phase inputs from the input data.
  wire [FREQ_WIDTH - 1:0] freq;
  wire [PHASE_WIDTH - 1:0] phase;
  assign freq = s_axis_data_tdata[FREQ_WIDTH + PHASE_WIDTH - 1:FREQ_WIDTH];
  assign phase = s_axis_data_tdata[FREQ_WIDTH - 1:0];

  // Calculate the output data using the frequency and phase inputs.
  wire [DATA_WIDTH - 1:0] out_data;
  assign out_data = ram_data[freq];

  // Update the RAM address and data if the input data is valid.
  always @(posedge aclk) begin
    if (s_axis_data_tvalid) begin
      ram_addr <= freq;
      ram_data[freq] <= out_data;
