module dds_ram
  #(parameter DATA_WIDTH = 8,
    parameter ADDR_WIDTH = 8,
    parameter RAM_DEPTH = 256,
    parameter RAM_STYLE = "block",
    parameter RAM_INIT = 0,
    parameter RAM_ADDR_MSB = 7,
    parameter RAM_ADDR_LSB = 0)
  (input aclk,
   input [ADDR_WIDTH - 1:0] addr,
   inout [DATA_WIDTH - 1:0] data);

  // Define the RAM.
  genvar i;
  generate
    if (RAM_STYLE == "block") begin
      reg [DATA_WIDTH - 1:0] ram [0:RAM_DEPTH-1];
      initial begin
        for (i = 0; i < RAM_DEPTH; i = i + 1) begin
          ram[i] = RAM_INIT;
        end
      end
      assign data = ram[addr];
      always @(posedge aclk) begin
        ram[addr] <= data;
      end
    end else if (RAM_STYLE == "distributed") begin
      reg [DATA_WIDTH - 1:0] ram [0:RAM_DEPTH-1];
      initial begin
        ram[0] = RAM_INIT;
      end
      assign data = ram[addr];
      always @(posedge aclk) begin
        if (addr != 0) begin
          ram[addr] <= data;
        end
      end
    end else begin
      reg [DATA_WIDTH - 1:0] ram [0:RAM_DEPTH-1];
      initial begin
        for (i = 0; i < RAM_DEPTH; i = i + 1) begin
          ram[i] = RAM_INIT;
        end
      end
      assign data = ram[addr];
      always @(posedge aclk) begin
        ram[addr] <= data;
      end
    end
  endgenerate

endmodule

