module parity_checker (
  input clk,
  input reset,
  input [15:0] data,
  output reg parity_bit
);

reg [3:0] ones_count;

always @(posedge clk or negedge reset) begin
  if (reset == 0) begin
    ones_count <= 0;
    parity_bit <= 0;
  end else begin
    ones_count <= ones_count + data[0] + data[1] + data[2] + data[3] + data[4] + data[5] + data[6] + data[7] + data[8] + data[9] + data[10] + data[11] + data[12] + data[13] + data[14] + data[15];
    parity_bit <= ones_count[0];
  end
end

endmodule

module top_module (
    input clk,
    input reset,
    input [7:0] d,
    input a,
    input b,
    input sel_b1,
    input sel_b2,
    output [7:0] q,
    output [7:0] sum
);

    reg [7:0] q_reg;
    reg [7:0] sum_reg;
    wire [7:0] mux_out;

    // 2-to-1 multiplexer
    mux_2to1 mux (
        .a(a),
        .b(b),
        .sel(sel_b1 | sel_b2),
        .out(mux_out)
    );

    // D flip-flop register
    always @(posedge clk) begin
        if (reset) begin
            q_reg <= {8{1'b0}};
            while (q_reg == 8'h00 || q_reg == 8'h34) begin
                q_reg <= $random;
            end
        end else begin
            q_reg <= d;
        end
    end

    // Adder
    always @(posedge clk) begin
        sum_reg <= q_reg + mux_out;
    end

    assign q = q_reg;
    assign sum = sum_reg;

endmodule

// 2-to-1 multiplexer module
module mux_2to1 (
    input a,
    input b,
    input sel,
    output reg out
);

    always @(a, b, sel) begin
        if (sel) begin
            out <= b;
        end else begin
            out <= a;
        end
    end

endmodule

