module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] in,   // 8-bit input for the shift register
    output [3:0] q,   // 4-bit output from the shift register
    output out_assign,    // output from the XOR gate using assign statement
    output reg out_alwaysblock  // output from the XOR gate using combinational always block
);

    reg [7:0] shift_reg;
    wire [3:0] shifted_value;
    wire [3:0] xor_value;

    // Shift register
    always @(posedge clk) begin
        if (reset) begin
            shift_reg <= 8'b0;
        end else begin
            shift_reg <= {shift_reg[3:0], in};
        end
    end

    assign shifted_value = shift_reg[3:0];

    // XOR gate using assign statement
    assign out_assign = shifted_value ^ in;

    // XOR gate using combinational always block
    always @(*) begin
        xor_value = shifted_value ^ in;
        out_alwaysblock = xor_value;
    end

    or_module or_inst (
        .in1(shifted_value),
        .in2(xor_value),
        .out(q)
    );

endmodule

