module flip_flops (
  input [width-1:0] D,
  input [width-1:0] J,
  input [width-1:0] K,
  input [width-1:0] T,
  input [width-1:0] S,
  input [width-1:0] R,
  input CLK,
  output reg [width-1:0] Q
);

parameter width = 1; // width of flip-flop data input

  always @(posedge CLK) begin
    // D flip-flop
    Q <= D;

    // JK flip-flop
    if (J == 1 && K == 1) begin
      Q <= ~Q;
    end else if (J == 1) begin
      Q <= 1;
    end else if (K == 1) begin
      Q <= 0;
    end

    // T flip-flop
    if (T == 1) begin
      Q <= ~Q;
    end

    // SR flip-flop
    if (S == 1 && R == 0) begin
      Q <= 1;
    end else if (S == 0 && R == 1) begin
      Q <= 0;
    end
  end

endmodule

module resistive_touch (
  input Xplus,
  input Xminus,
  input Yplus,
  input Yminus,
  output touch
);

  reg Xplus_prev, Xminus_prev, Yplus_prev, Yminus_prev;
  reg Xplus_curr, Xminus_curr, Yplus_curr, Yminus_curr;
  reg Xres, Yres;

  always @(Xplus, Xminus, Yplus, Yminus) begin
    Xplus_prev <= Xplus_curr;
    Xminus_prev <= Xminus_curr;
    Yplus_prev <= Yplus_curr;
    Yminus_prev <= Yminus_curr;

    Xplus_curr <= Xplus;
    Xminus_curr <= Xminus;
    Yplus_curr <= Yplus;
    Yminus_curr <= Yminus;

    Xres <= Xplus_curr ^ Xminus_curr;
    Yres <= Yplus_curr ^ Yminus_curr;
  end

  always @(Xres, Yres) begin
    if (Xres || Yres) begin
      touch <= 1;
    end else begin
      touch <= 0;
    end
  end

endmodule

