module fifo_ctrl (
  input ClrW,
  input Wclk,
  input Start,
  input nRclk,
  input RE,
  input H_L,
  input [11:0] Depth,
  input [11:0] PerCnt,
  input [31:0] Delay,
  output Sampled,
  output Ready,
  output Full,
  output Empty,
  output [11:0] Wptr,
  output [11:0] Rptr
);

  reg Full;
  reg Ready;
  reg Loaded;
  reg [11:0] Wptr;
  reg [11:0] Rptr;
  reg [12:0] Pcnt;
  reg [11:0] Bptr;
  reg [31:0] DelayCnt;
  reg Sampled;

  assign Empty = (Rptr == Wptr) ? 1'b1 : 1'b0;

  always @(posedge Wclk or posedge ClrW) begin
    if (ClrW) begin
      Full <= 0;
      Pcnt <= 0;
      Sampled <= 0;
      DelayCnt <= 0;
      Ready <= 0;
    end else begin
      if (Start) DelayCnt <= DelayCnt + 1;
      if (Pcnt >= PerCnt) Sampled <= 1;
      if (!Full) Wptr <= Wptr + 1;
      if (Pcnt >= Depth) Full <= Ready;
      else Pcnt <= Pcnt + 1;
      if ((!Start) && (Pcnt >= PerCnt)) Pcnt <= PerCnt;
      if (DelayCnt == Delay) begin
        Ready <= 1;
        Bptr <= Wptr;
        Pcnt <= PerCnt;
      end
    end
  end

  always @(posedge nRclk or posedge ClrW) begin
    if (ClrW) begin
      Loaded <= 0;
      Rptr <= 0;
    end else begin
      if (H_L && RE) Rptr <= Rptr + 1;
      if ((H_L) && RE && (~Loaded) && Start) begin
        Loaded <= 1;
        Rptr <= Bptr - 151;
      end
    end
  end

endmodule

module crystal_oscillator_interface (
  input clk,
  input rst,
  input xtal,
  output reg clk_div,
  output reg pd_out
);

parameter f_clk = 50000000; // input clock frequency
parameter f_xtal = 25000000; // crystal oscillator frequency
parameter n = 8; // number of bits in divider chain

reg [n-1:0] divider; // divider chain
reg ref_clk; // reference clock signal

always @(posedge clk or posedge rst) begin
  if (rst) begin
    divider <= 0;
    ref_clk <= 0;
    clk_div <= 0;
    pd_out <= 0;
  end else begin
    // increment divider chain
    if (divider == (1 << n) - 1) begin
      divider <= 0;
    end else begin
      divider <= divider + 1;
    end

    // generate reference clock signal
    if (divider == 0) begin
      ref_clk <= ~ref_clk;
    end

    // generate divided clock signal
    if (divider == (1 << (n-1)) - 1) begin
      clk_div <= ~clk_div;
    end

    // generate phase detector output signal
    if (ref_clk == xtal) begin
      pd_out <= 0;
    end else if (ref_clk == ~xtal) begin
      pd_out <= 1;
    end
  end
end

endmodule

