    if (reset) begin
        count <= 0;
        q <= 0;
    end else begin
        if (ena[2]) begin
            count[3:2] <= count[3:2] + 1;
            if (count[3:2] == 5) count[3:2] <= 0;
        end
        if (ena[1]) begin
            count[5:4] <= count[5:4] + 1;
            if (count[5:4] == 10) count[5:4] <= 0;
        end
        if (ena[0]) begin
            count[7:6] <= count[7:6] + 1;
            if (count[7:6] == 10) count[7:6] <= 0;
        end
        q <= {count[3:0], count[5:2], count[7:4], 0};
    end
end

