    output wire [7:0] out_lo
);

    wire [3:0] mux_out;
    wire [7:0] split_out_hi;
    wire [7:0] split_out_lo;
    wire [7:0] and_out;

    mux_module mux_inst (
        .sel(sel),
        .data0(data0),
        .data1(data1),
        .data2(data2),
        .data3(data3),
        .data4(data4),
        .data5(data5),
        .out(mux_out)
    );

    split_module split_inst (
        .in(in),
        .out_hi(split_out_hi),
        .out_lo(split_out_lo)
    );

    and_module and_inst (
        .in1(split_out_hi & mux_out),
        .in2(split_out_lo & mux_out),
        .out(and_out)
    );

    assign out_hi = and_out[7:0];
    assign out_lo = and_out[15:8];

