module barrel_shift(
    input wire [15:0] in,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo
);

    wire [7:0] upper_byte;
    wire [7:0] lower_byte;
    wire [15:0] shifted_in;

    // Split input into upper and lower bytes
    assign {upper_byte, lower_byte} = in >> 8;

    // Concatenate least significant bits of each byte to form lower byte of output
    assign out_lo = {lower_byte[0], upper_byte[0]};

    // Concatenate most significant bits of each byte to form upper byte of output
    assign out_hi = {lower_byte[7], upper_byte[7]};

    // Shift input to align with output of second module
    assign shifted_in = in << 8;

    // Add the two outputs of the second module to get the final output
    adder adder_inst(.a(out_hi), .b(out_lo), .sum({8'b0, shifted_in}), .carry());

    // Split final output into upper and lower bytes
    assign {out_hi, out_lo} = {out_hi, out_lo} >> 8;

endmodule

