module top_module (
    input [7:0] in,
    input [7:0] sel,
    output [3:0] out
);

    // Priority Encoder
    wire [7:0] in_inv = ~in;
    wire [2:0] priority;
    assign priority = (in_inv[7]) ? 3 :
                      (in_inv[6]) ? 2 :
                      (in_inv[5]) ? 1 :
                      (in_inv[4]) ? 0 :
                      (in_inv[3]) ? 3 :
                      (in_inv[2]) ? 2 :
                      (in_inv[1]) ? 1 :
                      (in_inv[0]) ? 0 : 0;
    wire [3:0] sel_mux = sel[7:4];

    // Multiplexer
    wire [3:0] mux_out;
    genvar i;
    generate
        for (i = 0; i < 256; i = i + 1) begin : mux_block
            assign mux_out = (i == sel_mux) ? in[3:0] : mux_out;
        end
    endgenerate

    // Functional Module
    wire [3:0] final_out;
    assign final_out = (priority != 0) ? mux_out : in[3:0];
    assign out = final_out;

endmodule

