module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] d,    // 8-bit input for the register
    output [3:0] counter_out, // 4-bit counter output
    output [7:0] max_out // Maximum value between the register and counter outputs
);

    reg [7:0] reg_out;
    reg [3:0] counter;

    always @(posedge clk) begin
        if (reset) begin
            reg_out <= 8'h34;
            counter <= 4'b0;
        end else begin
            reg_out <= d;
            counter <= counter + 1;
        end
    end

    assign counter_out = counter;

    // Extend counter output to 8 bits
    wire [7:0] counter_ext = {4'b0, counter};

    // Functional module to output maximum value
    assign max_out = (reg_out > counter_ext) ? reg_out : counter_ext;

endmodule

module reverse_bit_order_pipeline(
    input clk,
    input reset,
    input [7:0] in,
    output [7:0] out
);

reg [7:0] shift_reg [0:7];
reg [2:0] stage;

always @(posedge clk) begin
    if (reset) begin
        stage <= 0;
        shift_reg <= 0;
    end else begin
        case (stage)
            0: begin
                shift_reg[0] <= in;
                stage <= 1;
            end
            1: begin
                shift_reg[1] <= shift_reg[0] >> 1;
                stage <= 2;
            end
            2: begin
                shift_reg[2] <= shift_reg[1] >> 1;
                stage <= 3;
            end
            3: begin
                shift_reg[3] <= shift_reg[2] >> 1;
                stage <= 4;
            end
            4: begin
                shift_reg[4] <= shift_reg[3] >> 1;
                stage <= 5;
            end
            5: begin
                shift_reg[5] <= shift_reg[4] >> 1;
                stage <= 6;
            end
            6: begin
                shift_reg[6] <= shift_reg[5] >> 1;
                stage <= 7;
            end
            7: begin
                shift_reg[7] <= shift_reg[6] >> 1;
                out <= shift_reg[7];
                stage <= 0;
            end
            default: stage <= 0;
        endcase
    end
end

endmodule

