module sequence_counter (
    input clk,
    input reset,   // Synchronous active-high reset
    input reset_count, // Asynchronous active-high reset of the count
    input [3:0] sequence, // The 4-bit sequence to be detected
    input data, // The incoming data stream
    output reg [15:0] count // The count of occurrences of the sequence
);

    reg [3:0] data_reg [0:3]; // Four 4-bit data registers
    reg [15:0] count_reg; // Count register

    always @(posedge clk) begin
        if (reset) begin
            // Synchronous reset
            data_reg[0] <= 4'b0000;
            data_reg[1] <= 4'b0000;
            data_reg[2] <= 4'b0000;
            data_reg[3] <= 4'b0000;
            count_reg <= 16'b0000000000000000;
        end else begin
            // Shift in new data
            data_reg[0] <= data;
            data_reg[1] <= data_reg[0];
            data_reg[2] <= data_reg[1];
            data_reg[3] <= data_reg[2];

            // Detect sequence
            if (data_reg[0] == sequence && data_reg[1] == sequence && data_reg[2] == sequence && data_reg[3] == sequence) begin
                count_reg <= count_reg + 1;
            end

            // Asynchronous reset of the count
            if (reset_count) begin
                count_reg <= 16'b0000000000000000;
            end
        end
    end

    assign count = count_reg;

endmodule

module edge_detector (
    input clk,
    input [7:0] in,
    output reg [7:0] anyedge
);

reg [7:0] prev_in;

always @(posedge clk) begin
    if (in > prev_in) begin
        anyedge <= in;
    end else if (in < prev_in) begin
        anyedge <= ~in;
    end
    prev_in <= in;
end

endmodule

module min_detector (
    input [7:0] a, b, c, d,
    output reg [7:0] min
);

always @* begin
    if (a < b && a < c && a < d) begin
        min <= a;
    end else if (b < a && b < c && b < d) begin
        min <= b;
    end else if (c < a && c < b && c < d) begin
        min <= c;
    end else begin
        min <= d;
    end
end

endmodule

