    .a(a),
    .b(b),
    .c(c),
    .d(d),
    .min(min_out)
);

always @(edge_out or min_out) begin
    if (edge_out == a) begin
        min <= a;
    end else if (edge_out == b) begin
        min <= b;
    end else if (edge_out == c) begin
        min <= c;
    end else if (edge_out == d) begin
