module barrel_shifter (
    input [15:0] A,
    input [3:0] B,
    output [15:0] shift_left,
    output [15:0] shift_right
);

reg [15:0] stage1_out;
reg [15:0] stage2_out;
reg [15:0] stage3_out;

// Stage 1: Shift left by 1 bit
always @(*) begin
    stage1_out[0] = A[1];
    stage1_out[1] = A[2];
    stage1_out[2] = A[3];
    stage1_out[3] = A[4];
    stage1_out[4] = A[5];
    stage1_out[5] = A[6];
    stage1_out[6] = A[7];
    stage1_out[7] = A[8];
    stage1_out[8] = A[9];
    stage1_out[9] = A[10];
    stage1_out[10] = A[11];
    stage1_out[11] = A[12];
    stage1_out[12] = A[13];
    stage1_out[13] = A[14];
    stage1_out[14] = A[15];
    stage1_out[15] = 0;
end

// Stage 2: Shift left by 2 bits
always @(*) begin
    stage2_out[0] = stage1_out[2];
    stage2_out[1] = stage1_out[3];
    stage2_out[2] = stage1_out[4];
    stage2_out[3] = stage1_out[5];
    stage2_out[4] = stage1_out[6];
    stage2_out[5] = stage1_out[7];
    stage2_out[6] = stage1_out[8];
    stage2_out[7] = stage1_out[9];
    stage2_out[8] = stage1_out[10];
    stage2_out[9] = stage1_out[11];
    stage2_out[10] = stage1_out[12];
    stage2_out[11] = stage1_out[13];
    stage2_out[12] = stage1_out[14];
    stage2_out[13] = stage1_out[15];
    stage2_out[14] = 0;
    stage2_out[15] = 0;
end

// Stage 3: Shift left by 4 bits
always @(*) begin
    stage3_out[0] = stage2_out[4];
    stage3_out[1] = stage2_out[5];
    stage3_out[2] = stage2_out[6];
    stage3_out[3] = stage2_out[7];
    stage3_out[4] = stage2_out[8];
    stage3_out[5] = stage2_out[9];
    stage3_out[6] = stage2_out[10];
    stage3_out[7] = stage2_out[11];
    stage3_out[8] = stage2_out[12];
    stage3_out[9] = stage2_out[13];
    stage3_out[10] = stage2_out[14];
    stage3_out[11] = stage2_out[15];
    stage3_out[12] = 0;
    stage3_out[13] = 0;
    stage3_out[14] = 0;
    stage3_out[15] = 0;
end

// Shift left output
assign shift_left = (B == 0) ? A : stage3_out;

// Stage 4: Shift right by 1 bit
always @(*) begin
    stage1_out[0] = 0;
    stage1_out[1] = A[0];
    stage1_out[2] = A[1];
    stage1_out[3] = A[2];
    stage1_out[4] = A[3];
    stage1_out[5] = A[4];
    stage1_out[6] = A[5];
    stage1_out[7] = A[6];
    stage1_out[8] = A[7];
    stage1_out[9] = A[8];
    stage1_out[10] = A[9];
    stage1_out[11] = A[10];
    stage1_out[12] = A[11];
    stage1_out[13] = A[12];
    stage1_out[14] = A[13];
    stage1_out[15] = A[14];
end

// Stage 5: Shift right by 2 bits
always @(*) begin
    stage2_out[0] = 0;
    stage2_out[1] = 0;
    stage2_out[2] = stage1_out[0];
    stage2_out[3] = stage1_out[1];
    stage2_out[4] = stage1_out[2];
    stage2_out[5] = stage1_out[3];
    stage2_out[6] = stage1_out[4];
    stage2_out[7] = stage1_out[5];
    stage2_out[8] = stage1_out[6];
    stage2_out[9] = stage1_out[7];
    stage2_out[10] = stage1_out[8];
    stage2_out[11] = stage1_out[9];
    stage2_out[12] = stage1_out[10];
    stage2_out[13] = stage1_out[11];
    stage2_out[14] = stage1_out[12];
    stage2_out[15] = stage1_out[13];
end

// Stage 6: Shift right by 4 bits
always @(*) begin
    stage3_out[0] = 0;
    stage3_out[1] = 0;
    stage3_out[2] = 0;
    stage3_out[3] = 0;
    stage3_out[4] = stage2_out[0];
    stage3_out[5] = stage2_out[1];
    stage3_out[6] = stage2_out[2];
    stage3_out[7] = stage2_out[3];
    stage3_out[8] = stage2_out[4];
    stage3_out[9] = stage2_out[5];
    stage3_out[10] = stage2_out[6];
    stage3_out[11] = stage2_out[7];
    stage3_out[12] = stage2_out[8];
    stage3_out[13] = stage2_out[9];
    stage3_out[14] = stage2_out[10];
    stage3_out[15] = stage2_out[11];
end

// Shift right output
assign shift_right = (B == 0) ? A : stage3_out;

endmodule

module dual_port_ram_mux (
  input clk,
  input rst_n, // Active-low reset input
  input write_en, // Write enable signal
  input [7:0] write_addr, // Address input for write port
  input [3:0] in1, // First 4-bit input for the 2-to-1 multiplexer
  input [3:0] in2, // Second 4-bit input for the 2-to-1 multiplexer
  input select, // Select input for the 2-to-1 multiplexer
  input read_en, // Read enable signal
  input [7:0] read_addr, // Address input for read port
  output reg [3:0] read_data // 4-bit output from the read port
);

reg [3:0] ram [0:7]; // True dual-port RAM with depth of 8 and bit width of 4 bits

// Initialize RAM with all data set to 0000
integer i;
initial begin
  for (i = 0; i < 8; i = i + 1) begin
    ram[i] = 4'b0000;
  end
end

// Write port
always @(posedge clk or negedge rst_n) begin
  if (~rst_n) begin
    // Reset RAM to all 0000
    for (i = 0; i < 8; i = i + 1) begin
      ram[i] <= 4'b0000;
    end
  end else if (write_en && (write_addr < 8)) begin
    // Write input data from selected input of 2-to-1 mux to specified address
    ram[write_addr] <= select ? in2 : in1;
  end
end

// Read port
always @(posedge clk or negedge rst_n) begin
  if (~rst_n) begin
    read_data <= 4'b0000;
  end else if (read_en && (read_addr < 8)) begin
    // Read data stored at specified address
    read_data <= ram[read_addr];
  end
end

// Functional module to perform logical AND operation with constant 4-bit value of 1100
wire [3:0] and_value = 4'b1100;
assign read_data = ram[read_addr] & and_value;

endmodule

