module sync_ram (
    input clk,
    input datain,
    input write_reset,
    input [2:0] waddr,
    input [2:0] raddr,
    input we,
    output reg dataout
);

    reg [0:5] ram_d;
    reg [0:5] ram_q;

    wire [0:5] data_reg;

    integer i;

    initial begin
        dataout = 0;
        for (i = 0; i <= 5; i = i + 1)
            ram_q[i] <= 1'b0;
    end

    // Write port
    always @(posedge clk or posedge write_reset) begin
        if (write_reset == 1'b1) begin
            for (i = 0; i <= 5; i = i + 1)
                ram_q[i] <= 1'b0;
        end
        else begin
            for (i = 0; i <= 5; i = i + 1)
                ram_q[i] <= ram_d[i];
        end
    end

    always @(we or data_reg or ram_q) begin
        if (we === 1'b1) begin
            ram_d <= data_reg;
        end
        else begin
            ram_d <= ram_q;
        end
    end

    // Read port
    assign data_reg[0] = (waddr == 3'b000) ? datain : ram_q[0];
    assign data_reg[1] = (waddr == 3'b001) ? datain : ram_q[1];
    assign data_reg[2] = (waddr == 3'b010) ? datain : ram_q[2];
    assign data_reg[3] = (waddr == 3'b011) ? datain : ram_q[3];
    assign data_reg[4] = (waddr == 3'b100) ? datain : ram_q[4];
    assign data_reg[5] = (waddr == 3'b101) ? datain : ram_q[5];

    always @(ram_q or we or waddr or raddr) begin
        case (raddr)
            3'b000: dataout <= ram_q[0];
            3'b001: dataout <= ram_q[1];
            3'b010: dataout <= ram_q[2];
            3'b011: dataout <= ram_q[3];
            3'b100: dataout <= ram_q[4];
            3'b101: dataout <= ram_q[5];
            default: dataout <= 0;
        endcase
    end

endmodule

module diffeq_paj_convert (
    input clk, reset,
    input [31:0] Xinport, Yinport, Uinport, Aport, DXport,
    output reg [31:0] Xoutport, Youtport, Uoutport
);

    reg [31:0] x_var;
    reg [31:0] y_var;
    reg [31:0] u_var;
    wire [31:0] temp;
    reg looping;

    assign temp = u_var * DXport;

    always @(posedge clk) begin
        if (reset == 1'b1) begin
            looping <= 1'b0;
            x_var <= 0;
            y_var <= 0;
            u_var <= 0;
        end else if (looping == 1'b0) begin
            x_var <= Xinport;
            y_var <= Yinport;
            u_var <= Uinport;
            looping <= 1'b1;
        end else if (x_var < Aport) begin
            u_var <= (u_var - (temp * 3 * x_var)) - (DXport * 3 * y_var);
            y_var <= y_var + temp;
            x_var <= x_var + DXport;
            looping <= looping;
        end else begin
            Xoutport <= x_var;
            Youtport <= y_var;
            Uoutport <= u_var;
            looping <= 1'b0;
        end
    end

endmodule

module calculator (
    input clk,
    input rst,
    input [1:0] op,
    input signed [7:0] a,
    input signed [7:0] b,
    output reg signed [7:0] result
);

reg signed [15:0] temp;

always @(posedge clk) begin
    if (rst) begin
        result <= 0;
    end else begin
        case (op)
            2'b00: begin // addition
                temp <= a + b;
            end
            2'b01: begin // subtraction
                temp <= a - b;
            end
            2'b10: begin // multiplication
                temp <= a * b;
            end
            2'b11: begin // division
                temp <= a / b;
            end
        endcase

        // handle overflow and underflow
        if (temp > 127) begin
            result <= 127;
        end else if (temp < -128) begin
            result <= -128;
        end else begin
            result <= temp[7:0];
        end
    end
end

endmodule

module counter_4bit_delay(input clk, input reset, input enable, input in, output reg [3:0] count);

	reg [1:0] delay_counter;
	reg [3:0] counter;

	always @(posedge clk) begin
		if (reset) begin
			counter <= 0;
			delay_counter <= 0;
		end
		else begin
			if (enable) begin
				if (delay_counter == 2'b11) begin
					counter <= counter + 1;
				end
				delay_counter <= delay_counter + 1;
			end
			if (in) begin
				counter <= 0;
				delay_counter <= 0;
			end
		end
	end

	assign count = counter;

endmodule

module nor_using_nand_pipeline(
    input a,
    input b,
    output out
);

reg a_reg, b_reg;
wire nand1_out, nand2_out, nand3_out;

// Pipeline stage 1
assign nand1_out = ~(a_reg & b_reg);
always @(posedge clk) begin
    a_reg <= a;
    b_reg <= b;
end

// Pipeline stage 2
assign nand2_out = ~(a_reg & nand1_out);
always @(posedge clk) begin
    a_reg <= a_reg;
end

// Pipeline stage 3
assign nand3_out = ~(b_reg & nand2_out);
always @(posedge clk) begin
    b_reg <= b_reg;
end

// Output stage
assign out = nand3_out;

endmodule

module t_latch_async_reset(D, G, RN, Q, QN);
  input D;
  input G;
  input RN;
  output Q;
  output QN;
  reg Q, QN;

  always @ (D, G, RN) begin
    if (RN == 1'b0) begin
      Q <= 1'b0;
      QN <= 1'b1;
    end else if (G == 1'b0) begin
      Q <= 1'b0;
      QN <= 1'b1;
    end else begin
      Q <= D;
