module barrel_shifter (
    input [15:0] data_in,
    input [3:0] shift_amount,
    output reg [15:0] data_out,
    output reg carry_out
);

always @(*) begin
    if (shift_amount > 16) begin
        data_out = 16'b0;
        carry_out = data_in[15];
    end else begin
        data_out = data_in << shift_amount;
        carry_out = data_out[15];
    end
end

endmodule

module FIR_filter
  (// Inputs
   CLK             ,   // Clock
   ARST            ,   // Reset
   filterCoef      ,   // Filter Coefficients
   InData          ,   // Input Data
   input_Valid     ,   // Input Valid
   initialize      ,   // Initialize
   // Outputs
   OutData         ,   // Output Data
   output_Valid        // Output Valid
   );


   //**************************************************************************//
   //*                         Declarations                                   *//
   //**************************************************************************//
   // DATA TYPE - PARAMETERS
   parameter IWIDTH    = 16;   // Input bit width
   parameter OWIDTH    = 32;   // Output bit width
   parameter AWIDTH    = 32;   // Internal bit width
   parameter NTAPS     = 15;   // Total number of taps including zeros
   parameter NTAPSr    = 15;   // Real number of taps in the filter
   parameter CNTWIDTH  = 4 ;   // Count bit width, depends on number of taps
   parameter NMULT     = 1 ;   // Number of clocks it takes for multiplier 
                               // to generate an answer

   // DATA TYPE - INPUTS AND OUTPUTS
   input                               CLK                     ;  // 60MHz Clock
   input                               ARST                    ;
   input                               input_Valid             ;
   input                               initialize              ;
   input   signed [(IWIDTH-1):0]       InData, filterCoef      ;
   output  signed [(OWIDTH-1):0]       OutData                 ;
   output                              output_Valid            ;

   // DATA TYPE - REGISTERS
   reg     signed [(AWIDTH-1):0]       mult, accum             ;
   reg                                 input_Valid0            ;
   reg                                 initialize1             ;

   reg                                 output_Valid_1          ;

   wire                                output_Valid            ;
   reg            [CNTWIDTH-1:0]       count                   ;

   // DATA TYPE - WIRES
   wire    signed [(AWIDTH-1):0]       accum_tmp               ;
   wire           [CNTWIDTH-1:0]       taps                    ;


   assign  taps = (NTAPS == NTAPSr) ? 0: (NTAPS - NTAPS + NTAPSr) ;


   //**************************************************************************//
   //*                         Input Buffers                                  *//
   //**************************************************************************//
   always @(posedge CLK or posedge ARST)
     if (ARST)     input_Valid0 <=  1'b0 ;
     else          input_Valid0 <=  input_Valid ;

   always @(posedge CLK or posedge ARST)
     if (ARST)     initialize1 <=  1'b0 ;
     else          initialize1 <=  initialize ;


   //**************************************************************************//
   //*                         Multiply-Accumulate                            *//
   //**************************************************************************//
   // Multiplier
   always @(posedge CLK or posedge ARST)
     if (ARST)     mult[(AWIDTH-1):0] <=  {(AWIDTH-1){1'b0}} ;
     else          mult[(AWIDTH-1):0] <=  filterCoef*InData  ;

   assign  accum_tmp[(AWIDTH-1):0] =   mult[(AWIDTH-1):0] + accum[(AWIDTH-1):0];

   // Accumulator
   always @(posedge CLK or posedge ARST)// or initialize)
     if (ARST)     accum[(OWIDTH-1):0] <=  {(OWIDTH){1'b0}} ;
     else          accum[(OWIDTH-1):0] <= (initialize1) ?
                                          mult[(AWIDTH-1):0] :
                                          (input_Valid0 ? accum_tmp[(AWIDTH-1):0]
                                           : accum[(AWIDTH-1):0]) ;


   //**************************************************************************//
   //*                            Counters                                    *//
   //**************************************************************************//
   always @ (posedge CLK or posedge ARST)
     if (ARST)     count[CNTWIDTH-1:0] <=  {(CNTWIDTH){1'b0}}  ;
     else          count[CNTWIDTH-1:0] <= initialize ?
                                          0 :
                                          input_Valid0 + count[CNTWIDTH-1:0] ;


   //**************************************************************************//
   //*                           Output Buffers                               *//
   //**************************************************************************//
   always @(posedge CLK or posedge ARST)
     if (ARST)     output_Valid_1 <=  1'b0 ;
     else          output_Valid_1 <=  (count[CNTWIDTH-1:0]==(NTAPSr-1+NMULT-1))   ;

   assign  output_Valid            = output_Valid_1 & (count[CNTWIDTH-1:0]==taps) ;
   assign  OutData[(OWIDTH-1):0]   = accum[(OWIDTH-1):0]                          ;


endmodule

module coredffr2(q, d, purst, S_R, cbit, clk, clkb, ce);
  input S_R;
  input [1:0] cbit;
  input ce;
  input clk;
  input clkb;
  input d;
  input purst;
  output reg q;

  always @(posedge clk or negedge clkb) begin
    if(purst) begin
      q <= 1;
    end else if(S_R) begin
      q <= 0;
    end else if(ce) begin
      case(cbit)
        2'b00: q <= d;
        2'b01: q <= d;
        2'b10: q <= d;
        2'b11: q <= d;
      endcase
    end
  end

  always @(posedge clkb or negedge clk) begin
    if(purst) begin
      q <= 1;
    end else if(S_R) begin
      q <= 0;
    end else if(ce) begin
      case(cbit)
        2'b00: q <= q;
        2'b01: q <= q;
        2'b10: q <= d;
        2'b11: q <= d;
      endcase
    end
  end
endmodule

module BT_transmitter (
  input clk,
  input reset,
  input [7:0] data_in,
  output out
);

  reg [7:0] data_reg;
  reg [7:0] data_next;
  reg [1:0] state;

  parameter BIT_PERIOD = 1000; // 1MHz clock frequency
  parameter BT_PERIOD = 4 * BIT_PERIOD; // Bluetooth symbol period
  parameter BT_FREQ_DEV = 0.5 * BIT_PERIOD; // Frequency deviation
  parameter BT_MOD_INDEX = BT_FREQ_DEV / BIT_PERIOD; // Modulation index
  parameter BT_GAUSSIAN_COEFF = 0.5; // Gaussian filter coefficient

  always @(posedge clk) begin
    if (reset) begin
      data_reg <= 8'b0;
      state <= 2'b00;
    end else begin
      case (state)
        2'b00: begin // Wait for start bit
          if (data_in == 1'b0) begin
            data_next <= data_reg;
            state <= 2'b01;
          end
        end
        2'b01: begin // Transmit data bits
          if (data_next[0] == 1'b1) begin
            out <= 1'b1;
          end else begin
            out <= -1'b1;
          end
          data_next <= {data_next[6:0], 1'b0};
          state <= 2'b10;
        end
        2'b10: begin // Wait for stop bit
          out <= -out;
          state <= 2'b00;
        end
      endcase
      data_reg <= data_next;
    end
  end

  // GFSK modulation
  always @(posedge clk) begin
    if (reset) begin
      out <= 1'b0;
    end else begin
      if (state == 2'b01) begin
        if (data_next[0] == 1'b1) begin
          out <= out + BT_MOD_INDEX;
        end else begin
          out <= out - BT_MOD_INDEX;
        end
      end
    end
  end

  // Gaussian filter
  reg [7:0] filter_reg;
  reg [7:0] filter_next;
  always @(posedge clk) begin
    if (reset) begin
      filter_reg <= 8'b0;
    end else begin
      filter_next <= (BT_GAUSSIAN_COEFF * filter_reg) + ((1 - BT_GAUSSIAN_COEFF) * out);
      filter_reg <= filter_next;
    end
  end

  assign out = filter_next;

endmodule

module BT_receiver (
  input clk,
  input reset,
  input in,
  output reg [7:0] data_out
);

  parameter BIT_PERIOD = 1000; // 1MHz clock frequency
  parameter BT_PERIOD = 4 * BIT_PERIOD; // Bluetooth symbol period
  parameter BT_FREQ_DEV = 0.5 * BIT_PERIOD; // Frequency deviation
  parameter BT_MOD_INDEX = BT_FREQ_DEV / BIT_PERIOD; // Modulation index
  parameter BT_GAUSSIAN_COEFF = 0.5; // Gaussian filter coefficient

  reg [7:0] filter_reg;
  reg [7:0] filter_next;
  reg [1:0] state;
  reg [7:0] data_reg;
  reg [7:0] data_next;
  reg [1:0] bit_count;

  always @(posedge clk) begin
    if (reset) begin
      filter_reg <= 8'b0;
      state <= 2'b00;
      data_reg <= 8'b0;
      bit_count <= 2'b00;
    end else begin
      // Gaussian filter
      filter_next <= (BT_GAUSSIAN_COEFF * filter_reg) + ((1 - BT_GAUSSIAN_COEFF) * in);
      filter_reg <= filter_next;

      case (state)
        2'b00: begin // Wait for start bit
          if (filter_next > 0) begin
            state <= 2'b01;
            data_next <= 8'b0;
            bit_count <= 2'b00;
          end
        end
        2'b01: begin // Receive data bits
          if (bit_count < 2'b10) begin
            if (filter_next > 0) begin
              data_next <= {data_next[6:0], 1'b1};
            end else begin
              data_next <= {data_next[6:0], 1'b0};
            end
            bit_count <= bit_count + 1;
          end else begin
            data_reg <= data_next;
            state <= 2'b10;
          end
        end
        2'b10: begin // Wait for stop bit
          if (filter_next < 0) begin
            data_out <= data_reg;
            state <= 2'b00;
          end
        end
      endcase
    end
  end

  // Matched filter
  reg [7:0] matched_reg;
  reg [7:0] matched_next;
  always @(posedge clk) begin
    if (reset) begin
      matched_reg <= 8'b0;
    end else begin
      matched_next <= (matched_reg >> 1) + (filter_next * BT_MOD_INDEX);
      matched_reg <= matched_next;
    end
  end

endmodule

