module wallace_multiplier (
    input [7:0] A,
    input [7:0] B,
    output [15:0] Y
);

reg [7:0] a_reg [0:7];
reg [7:0] b_reg [0:7];
reg [8:0] p_reg [0:15];
reg [8:0] g_reg [0:15];
reg [8:0] h_reg [0:15];
reg [8:0] c_reg [0:15];
reg [15:0] s_reg [0:15];
reg [15:0] c_out;
integer i, j;

always @(*) begin
    for (i = 0; i < 8; i = i + 1) begin
        a_reg[i] = A[i];
        b_reg[i] = B[i];
    end
end

always @(*) begin
    for (i = 0; i < 16; i = i + 1) begin
        p_reg[i] = 0;
        g_reg[i] = 0;
        h_reg[i] = 0;
        c_reg[i] = 0;
        s_reg[i] = 0;
    end
    c_out = 0;
end

always @(*) begin
    for (i = 0; i < 8; i = i + 1) begin
        for (j = 0; j < 8; j = j + 1) begin
            p_reg[i+j] = p_reg[i+j] + (a_reg[i] & b_reg[j]);
        end
    end
end

always @(*) begin
    for (i = 0; i < 15; i = i + 1) begin
        g_reg[i] = p_reg[i] & p_reg[i+1];
        h_reg[i] = p_reg[i] ^ p_reg[i+1];
    end
end

always @(*) begin
    for (i = 0; i < 14; i = i + 1) begin
        c_reg[i+2] = g_reg[i] | (h_reg[i] & c_reg[i+1]);
        s_reg[i+1] = h_reg[i] ^ g_reg[i] ^ c_reg[i+1];
    end
    c_reg[1] = g_reg[14];
    s_reg[15] = h_reg[14] ^ g_reg[14] ^ c_reg[14];
end

assign Y = {c_out, s_reg};

endmodule

module pipelined_addsub (
    input [3:0] a,
    input [3:0] b,
    input add_sub,
    output reg [3:0] result,
    output reg overflow
);

reg [3:0] sum, diff;
reg [3:0] a_reg, b_reg;
reg [1:0] stage;

always @(*) begin
    case (stage)
        0: begin
            a_reg = a;
            b_reg = b;
            stage = 1;
        end
        1: begin
            if (add_sub) begin
                sum = a_reg + b_reg;
                stage = 2;
            end
            else begin
                diff = a_reg - b_reg;
                stage = 2;
            end
        end
        2: begin
            if (add_sub) begin
                result = sum;
                stage = 3;
            end
            else begin
                result = diff;
                stage = 3;
            end
        end
        3: begin
            if (result > 7 || result < -8) begin
                overflow = 1;
            end
            else begin
                overflow = 0;
            end
            stage = 0;
        end
    endcase
end

endmodule

module mealy_fsm_1010_detection (
  input clk,
  input reset,
  input data,
  output reg match
);

  parameter IDLE = 2'b00, STATE1 = 2'b01, STATE2 = 2'b10;
  reg [1:0] state, next_state;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      state <= IDLE;
    end else begin
      state <= next_state;
    end
  end

  always @(*) begin
    case (state)
      IDLE: begin
        if (data == 1) begin
          next_state = STATE1;
        end else begin
          next_state = IDLE;
        end
        match = 0;
      end

      STATE1: begin
        if (data == 0) begin
          next_state = STATE2;
        end else begin
          next_state = STATE1;
        end
        match = 0;
      end

      STATE2: begin
        if (data == 1) begin
          next_state = STATE1;
        end else begin
          next_state = STATE2;
        end
        if (match == 0 && state == STATE2) begin
          match = 1;
        end
      end
    endcase
  end

endmodule

