module multiplexer (
    input [2:0] sel, // 3-bit selection signal
    input [3:0] data0, // 4-bit input data 0
    input [3:0] data1, // 4-bit input data 1
    input [3:0] data2, // 4-bit input data 2
    input [3:0] data3, // 4-bit input data 3
    output reg [3:0] out // 4-bit output
);

always @(*) begin
    case (sel)
        3'b000: out = data0;
        3'b001: out = data1;
        3'b010: out = data2;
        3'b011: out = data3;
        default: out = 4'b0000;
    endcase
end

endmodule

module functional_module (
    input parity, // parity bit input
    input [3:0] data, // 4-bit input data
    output reg [3:0] out // 4-bit output
);

always @(*) begin
    if (parity) begin
        out = data; // output selected data if parity bit is 1
    end else begin
        out = 4'b0000; // output 0 otherwise
    end
end

endmodule

module top_module (
    input [7:0] in, // 8-bit input data
