    input [3:0] data0, // 4-bit input data 0 for multiplexer
    input [3:0] data1, // 4-bit input data 1 for multiplexer
    input [3:0] data2, // 4-bit input data 2 for multiplexer
    input [3:0] data3, // 4-bit input data 3 for multiplexer
    output [3:0] out // 4-bit output from functional module
);

wire parity;
parity_generator pg(in, parity);

wire [3:0] selected_data;
multiplexer mux(sel, data0, data1, data2, data3, selected_data);

functional_module fm(parity, selected_data, out);

endmodule

module top_module (
    input clk,
    input reset, // Synchronous active-high reset
    input [7:0] d, // 8-bit input for the register
    output [3:0] q, // 4-bit output from the counter
    output reg [4:0] out_sum // 5-bit output from the functional module
);

reg [7:0] reg_out;
wire [3:0] counter_out;
wire [3:0] counter_out_next;
wire sum;

register_module reg_module (
    .clk(clk),
    .reset(reset),
    .d(d),
    .q(reg_out)
);

counter_module counter_module (
    .clk(clk),
    .reset(reset),
    .q(counter_out)
);

assign counter_out_next = counter_out + 1;

sum_module sum_module (
    .a(reg_out[3:0]),
    .b(counter_out),
    .sum(sum)
);

always @(posedge clk) begin
    if (reset) begin
        q <= 4'b0000;
        out_sum <= 5'b00000;
    end else begin
        q <= counter_out;
        out_sum <= {q, sum};
        counter_out <= counter_out_next;
    end
end

endmodule

