module memory(
      gm_or_lds,
      rd_en,
      wr_en,
      addresses,
      wr_data,
      input_tag,
//      wr_mask,
      rd_data,
      output_tag,
      ack,
      clk,
      rst
 );

input clk;
input rst;

input gm_or_lds;
input rd_en, wr_en;
input [31:0] addresses;
input [31:0] wr_data;
input [6:0] input_tag;

output [6:0] output_tag;
output ack;
output [31:0] rd_data;

reg[7:0] data_memory[50000:0];
reg[7:0] lds_memory[65535:0];

reg ack_reg;
reg [6:0] tag_reg;

//integer locrd = 4; // num of loc to read

assign ack = ack_reg;
assign output_tag = tag_reg;
integer i;
always@(posedge clk, posedge rst) begin
      if(rst) begin
            for(i = 0; i < 50001; i = i+1) begin
                  data_memory[i] <= 0;
            end
            for(i = 0; i < 65536; i = i+1) begin
                  lds_memory[i] <= 0;
            end
      end
      else if(wr_en) begin
            if(gm_or_lds) begin
                  lds_memory [addresses] <= wr_data[7:0];
                  lds_memory [addresses+1] <= wr_data[15:7];
                  lds_memory [addresses+2] <= wr_data[23:16];
                  lds_memory [addresses+3] <= wr_data[31:24];
            end
            else begin
                  data_memory [addresses] <= wr_data[7:0];
                  data_memory [addresses+1] <= wr_data[15:7];
                  data_memory [addresses+2] <= wr_data[23:16];
                  data_memory [addresses+3] <= wr_data[31:24];
            end
            ack_reg <= 1'b1;
            tag_reg <= input_tag;
      end
      else begin
            ack_reg <= 1'b0;
      end
end

always@(posedge clk) begin
      if(rst) begin
            tag_reg <= 7'd0;
      end
      else begin
            if(rd_en) begin
                  if(gm_or_lds) begin
                        rd_data <= {lds_memory[addresses+3],lds_memory[addresses+2],lds_memory[addresses+1],lds_memory[addresses]};
                  end
                  else begin
                        rd_data <= {data_memory[addresses+3],data_memory[addresses+2],data_memory[addresses+1],data_memory[addresses]};
                  end
                  ack_reg <= 1'b1;
                  tag_reg <= input_tag;
            end
            else begin
                  tag_reg <= 7'd0;
            end
      end
end

endmodule

module nios_dut_pio_0 (
  // inputs:
  address,
  chipselect,
  clk,
  in_port,
  reset_n,
  write_n,
  writedata,

  // outputs:
  irq,
  readdata
);

  output irq;
  output [31:0] readdata;
  input [1:0] address;
  input chipselect;
  input clk;
  input in_port;
  input reset_n;
  input write_n;
  input [31:0] writedata;

  wire clk_en;
  wire data_in;
  wire irq;
  reg irq_mask;
  wire read_mux_out;
  reg [31:0] readdata;
  assign clk_en = 1;

  // s1, which is an e_avalon_slave
  assign read_mux_out = ({1 {(address == 0)}} & data_in) |
                        ({1 {(address == 2)}} & irq_mask);

  always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
      readdata <= 0;
    end else if (clk_en) begin
      readdata <= {32'b0, read_mux_out};
    end
  end

  assign data_in = in_port;
  always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
      irq_mask <= 0;
    end else if (chipselect && ~write_n && (address == 2)) begin
      irq_mask <= writedata;
    end
  end

  assign irq = |(data_in & irq_mask);

endmodule

module BrzCallMux_8_2 (
  inp_0r, inp_0a, inp_0d,
  inp_1r, inp_1a, inp_1d,
  out_0r, out_0a, out_0d
);
  input inp_0r;
  output inp_0a;
  input [7:0] inp_0d;
  input inp_1r;
  output inp_1a;
  input [7:0] inp_1d;
  output out_0r;
  input out_0a;
  output [7:0] out_0d;
  wire [7:0] muxOut_0n;
  wire select_0n;
  wire nselect_0n;
  wire [1:0] nwaySelect_0n;
  wire [7:0] nwayMuxOut_0n;
  wire [7:0] nwayMuxOut_1n;
  mux2 I0 (out_0d[0], inp_0d[0], inp_1d[0], select_0n);
  mux2 I1 (out_0d[1], inp_0d[1], inp_1d[1], select_0n);
  mux2 I2 (out_0d[2], inp_0d[2], inp_1d[2], select_0n);
  mux2 I3 (out_0d[3], inp_0d[3], inp_1d[3], select_0n);
  mux2 I4 (out_0d[4], inp_0d[4], inp_1d[4], select_0n);
  mux2 I5 (out_0d[5], inp_0d[5], inp_1d[5], select_0n);
  mux2 I6 (out_0d[6], inp_0d[6], inp_1d[6], select_0n);
  mux2 I7 (out_0d[7], inp_0d[7], inp_1d[7], select_0n);
  mux2 I8 (out_0r, inp_0r, inp_1r, select_0n);
  AN2 I9 (inp_0a, nselect_0n, out_0a);
  AN2 I10 (inp_1a, select_0n, out_0a);
  SRFF I11 (inp_1r, inp_0r, select_0n, nselect_0n);

  assign nwayMuxOut_0n = {8{1'b0}};
  mux2 nwayMux0 (nwayMuxOut_0n, inp_0d, inp_1d, nwaySelect_0n[0]);
  mux2 nwayMux1 (nwayMuxOut_1n, inp_0d, inp_1d, nwaySelect_0n[1]);
  mux2 nwayMuxOut (muxOut_0n, nwayMuxOut_0n, nwayMuxOut_1n, select_0n);

  always @(*) begin
    if (!inp_0r && !inp_1r) begin
      out_0r = 1'b0;
      out_0a = 1'b0;
    end else if (inp_0r && !inp_1r) begin
      out_0r = inp_0r;
      out_0a = inp_0a;
      out_0d = inp_0d;
      select_0n = 1'b0;
    end else if (!inp_0r && inp_1r) begin
      out_0r = inp_1r;
      out_0a = inp_1a;
      out_0d = inp_1d;
      select_0n = 1'b1;
    end else begin
      case(nwaySelect_0n)
        2'b00: begin
          out_0r = inp_0r;
          out_0a = inp_0a & inp_1a;
          out_0d = muxOut_0n;
          select_0n = 1'b0;
        end
        2'b01: begin
          out_0r = inp_1r;
          out_0a = inp_0a & inp_1a;
          out_0d = muxOut_0n;
          select_0n = 1'b1;
        end
        2'b10: begin
          out_0r = nwayMuxOut_0n[0];
          out_0a = inp_0a & inp_1a;
          out_0d = muxOut_0n;
          select_0n = nwaySelect_0n[0];
        end
        2'b11: begin
          out_0r = nwayMuxOut_1n[0];
          out_0a = inp_0a & inp_1a;
          out_0d = muxOut_0n;
          select_0n = nwaySelect_0n[1];
        end
      endcase
    end
  end
endmodule

