module data_transfer(
  input clk,
  input nreset,
  input [4:0] ctrlmode_in,
  input [AW-1:0] data_in,
  input [1:0] datamode_in,
  input [AW-1:0] dstaddr_in,
  input [AW-1:0] srcaddr_in,
  input write_in,
  output reg [PW-1:0] reg_packet_out,
  output reg reg_access_out,
  output reg reg_wait_out,
  output reg irq
);

  // Internal signals and registers
  reg [31:0] config_reg;
  reg dma_en;
  reg mastermode;
  reg chainmode;
  reg manualmode;
  reg irqmode;
  reg [1:0] datamode;
  reg [4:0] ctrlmode;
  reg [15:0] next_descr;
  reg [31:0] stride_reg;
  reg [31:0] count_reg;
  reg [AW-1:0] srcaddr_reg;
  reg [AW-1:0] dstaddr_reg;
  reg [31:0] status_reg;
  reg [15:0] curr_descr;
  reg [PW-1:0] fetch_packet;
  reg fetch_access;
  reg update;
  reg [3:0] dma_state;

  // Decode input signals
  packet2emesh #(.AW(AW), .PW(PW)) p2e (
    .packet_in(reg_packet_in[PW-1:0]),
    .write_in(write_in),
    .datamode_in(datamode_in[1:0]),
    .ctrlmode_in(ctrlmode_in[4:0]),
    .dstaddr_in(dstaddr_in[AW-1:0]),
    .srcaddr_in(srcaddr_in[AW-1:0]),
    .data_in(data_in[AW-1:0])
  );

  // Assign values to internal registers and signals
  always @ (posedge clk or negedge nreset) begin
    if (!nreset) begin
      config_reg <= DEF_CFG;
      dma_en <= 0;
      mastermode <= 0;
      chainmode <= 0;
      manualmode <= 1;
      irqmode <= 0;
      datamode <= 2'b00;
      ctrlmode <= 5'b00000;
      next_descr <= 0;
      stride_reg <= 0;
      count_reg <= 0;
      srcaddr_reg <= 0;
      dstaddr_reg <= 0;
      status_reg <= 0;
      curr_descr <= 0;
      fetch_packet <= 0;
      fetch_access <= 0;
      update <= 0;
      dma_state <= 0;
    end else begin
      config_reg <= (config_write) ? data_in[31:0] : config_reg;
      dma_en <= config_reg[0];
      mastermode <= config_reg[1];
      chainmode <= config_reg[2];
      manualmode <= ~config_reg[3];
      irqmode <= config_reg[4];
      datamode <= config_reg[6:5];
      ctrlmode <= 5'b00000;
      next_descr <= config_reg[31:16];
      stride_reg <= (stride_write) ? data_in[31:0] : stride_reg;
      count_reg <= (count_write) ? data_in[31:0] : (update) ? count[31:0] : count_reg;
      srcaddr_reg <= (srcaddr0_write) ? data_in[31:0] : (srcaddr1_write) ? data_in[31:0] << 32 : (update) ? srcaddr[AW-1:0] : srcaddr_reg;
      dstaddr_reg <= (dstaddr0_write) ? data_in[31:0] : (dstaddr1_write) ? data_in[31:0] << 32 : (update) ? dstaddr[AW-1:0] : dstaddr_reg;
      status_reg <= (status_write) ? data_in[31:0] : (config_write) ? {next_descr[15:0], 12'b0, dma_state[3:0]} : status_reg;
      curr_descr <= status_reg[31:16];
      fetch_packet <= (reg_access_in && reg_wait_out) ? reg_packet_in[PW-1:0] : fetch_packet;
      fetch_access <= (reg_access_in && reg_wait_out) ? 1 : fetch_access;
      update <= (reg_access_in && reg_wait_out) ? 1 : update;
      dma_state <= (dma_en) ? dma_state + 1 : 0;
    end
  end

  // Readback circuit
  assign reg_wait_out = (reg_access_in && reg_wait_out) ? 0 : fetch_access;
  assign reg_access_out = fetch_access;
  assign reg_packet_out[PW-1:0] = fetch_packet[PW-1:0];

  assign irq = 0;

endmodule

