module four_bit_adder(
  input [3:0] a,
  input [3:0] b,
  input cin,
  output [3:0] sum,
  output cout
);

  wire [3:0] xor_out;
  wire [3:0] and_out;
  wire [3:0] or_out;

  // XOR gates
  assign xor_out[0] = a[0] ^ b[0];
  assign xor_out[1] = a[1] ^ b[1];
  assign xor_out[2] = a[2] ^ b[2];
  assign xor_out[3] = a[3] ^ b[3];

  // AND gates
  assign and_out[0] = a[0] & b[0];
  assign and_out[1] = a[1] & b[1];
  assign and_out[2] = a[2] & b[2];
  assign and_out[3] = a[3] & b[3];

  // OR gates
  assign or_out[0] = xor_out[0] ^ cin;
  assign or_out[1] = (xor_out[1] & xor_out[0]) ^ (cin & xor_out[1]);
  assign or_out[2] = (xor_out[2] & xor_out[1] & xor_out[0]) ^ (cin & xor_out[2] & (xor_out[1] ^ xor_out[0]));
  assign or_out[3] = (xor_out[3] & xor_out[2] & xor_out[1] & xor_out[0]) ^ (cin & xor_out[3] & (xor_out[2] ^ xor_out[1] ^ xor_out[0]));

  // Output signals
  assign sum[0] = xor_out[0];
  assign sum[1] = xor_out[1] ^ and_out[0];
  assign sum[2] = xor_out[2] ^ and_out[1] ^ or_out[0];
  assign sum[3] = xor_out[3] ^ and_out[2] ^ or_out[1];

  assign cout = and_out[3] ^ or_out[2];

endmodule

module top_module (
    input clk,
    input reset,
    input [7:0] a,
    input [7:0] b,
    input add_sub_ctrl,
    input select,
    output [7:0] result,
    output overflow,
    output eq,
    output gt,
    output lt,
    output max_value,
    output max_from_add_sub
);

    wire [7:0] add_sub_result;
    wire add_sub_overflow;
    wire [3:0] comp_result;
    wire comp_eq;
    wire comp_gt;
    wire comp_lt;
    wire [7:0] max_value_temp;

    add_sub add_sub_inst (
        .a(a),
        .b(b),
        .add_sub_ctrl(add_sub_ctrl),
        .result(add_sub_result),
        .overflow(add_sub_overflow)
    );

    comparator comparator_inst (
        .a(a[3:0]),
        .b(b[3:0]),
        .eq(comp_eq),
        .gt(comp_gt),
        .lt(comp_lt),
        .result(comp_result)
    );

    assign eq = (add_sub_result == b);
    assign gt = (add_sub_result > b);
    assign lt = (add_sub_result < b);

    always @(*) begin
        if (select == 1'b0) begin
            result = add_sub_result;
            overflow = add_sub_overflow;
        end else begin
            result = comp_result;
            overflow = 1'b0;
        end

        if (gt) begin
            max_value_temp = add_sub_result;
            max_from_add_sub = 1'b1;
        end else begin
            max_value_temp = b;
            max_from_add_sub = 1'b0;
        end

        if (comp_gt) begin
            max_value_temp[3:0] = a[3:0];
            max_from_add_sub = 1'b0;
        end

        max_value = max_value_temp;
    end

endmodule

module add_sub (
    input [7:0] a,
    input [7:0] b,
    input add_sub_ctrl,
    output [7:0] result,
    output overflow
);

    reg [8:0] temp_result;

    always @(*) begin
        if (add_sub_ctrl == 1'b0) begin
            temp_result = a + b;
        end else begin
            temp_result = a - b;
        end
    end

    assign result = temp_result[7:0];
    assign overflow = (temp_result[8] == 1'b1);

endmodule

module comparator (
    input [3:0] a,
    input [3:0] b,
    output eq,
    output gt,
    output lt,
    output [3:0] result
);

    assign eq = (a == b);
    assign gt = (a > b);
    assign lt = (a < b);

    assign result = (gt) ? a : b;

endmodule

