module signed_mag_comparator (
    input signed [7:0] A,
    input signed [7:0] B,
    output eq,
    output lt,
    output gt,
    output overflow
);

    reg signed [7:0] A_reg, B_reg, diff_reg;
    reg [2:0] stage;
    wire [7:0] diff;
    wire msb_A, msb_B, msb_diff;

    assign eq = (diff == 0);
    assign lt = (msb_diff == 1);
    assign gt = (msb_diff == 0);
    assign overflow = ((msb_A != msb_B) && (msb_A != msb_diff));

    always @(posedge clk) begin
        case (stage)
            0: begin
                A_reg <= A;
                B_reg <= B;
                stage <= 1;
            end
            1: begin
                diff_reg <= A_reg - B_reg;
                stage <= 2;
            end
            2: begin
                A_reg <= A;
                B_reg <= B;
                stage <= 3;
            end
            3: begin
                diff_reg <= A_reg - B_reg;
                stage <= 0;
            end
        endcase
    end

    assign diff = (stage == 1) ? diff_reg : A - B;
    assign msb_A = A[7];
    assign msb_B = B[7];
    assign msb_diff = diff[7];

endmodule

