    input wire [15:0] in,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo );

    wire [7:0] sum_hi;
    wire [7:0] sum_lo;

    byte_decoder decoder(.in(in), .out_hi(sum_hi), .out_lo(sum_lo));
    byte_mux mux_hi(.a(sum_hi), .b(8'b0), .sel(in[15]), .out(out_hi));
    byte_mux mux_lo(.a(sum_lo), .b(8'b0), .sel(in[7]), .out(out_lo));

endmodule

module byte_decoder(
    input wire [15:0] in,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo );

    assign out_hi = in[15:8];
    assign out_lo = in[7:0];

endmodule

module byte_mux(
    input a,
    input b,
    input sel,
    output out );

    assign out = sel ? b : a;

endmodule

module fsm_4bit_binary_counter (
  input clk,
  output reg [3:0] q
);

  reg [3:0] state;

  always @(posedge clk) begin
    if (state < 4'b1111) begin
      state <= state + 1;
    end else begin
      state <= 4'b0;
    end
  end

  assign q = state;

endmodule

module booth_multiplier (
    input [7:0] a,
    input [7:0] b,
    input start,
    output reg [15:0] product,
    output done
);

reg [7:0] m;
reg [7:0] ac;
reg [1:0] count;
reg done_flag;

always @(posedge start) begin
    m = b;
    ac = {a, 8'b0};
    count = 8'd8;
    done_flag = 0;
end

always @(posedge start) begin
    if (count == 0) begin
        done_flag = 1;
    end else begin
        if (ac[0] == 0 && ac[1] == 1) begin
            ac = ac + m;
        end else if (ac[0] == 1 && ac[1] == 0) begin
            ac = ac - m;
        end
        ac = {ac[7], ac};
        count = count - 1;
    end
end

always @(posedge start) begin
    if (done_flag == 1) begin
        product = ac;
        done = 1;
    end else begin
        done = 0;
    end
end

endmodule

module fifo(CLK, RST, ENQ, FULL_N, DEQ, EMPTY_N, CLR);

   parameter CAPACITY = 10;
   parameter guarded = 1;

   input CLK;
   input RST;
   input ENQ;
   input DEQ;
   input CLR;

   output FULL_N;
   output EMPTY_N;

   reg [CAPACITY-1:0] data;
   reg [CAPACITY-1:0] ptr;
   reg [CAPACITY-1:0] next_ptr;
   reg [CAPACITY-1:0] clear_cnt;
   reg [CAPACITY-1:0] enq_cnt;
   reg [CAPACITY-1:0] deq_cnt;
   reg empty_reg;
   reg full_reg;

   assign FULL_N = ~full_reg;
   assign EMPTY_N = ~empty_reg;

   always @ (posedge CLK) begin
      if (RST) begin
         ptr <= 0;
         next_ptr <= 0;
         clear_cnt <= 0;
         enq_cnt <= 0;
         deq_cnt <= 0;
         empty_reg <= 1;
         full_reg <= 0;
      end else begin
         if (CLR) begin
            ptr <= 0;
            next_ptr <= 0;
            clear_cnt <= CAPACITY;
            enq_cnt <= 0;
            deq_cnt <= 0;
            empty_reg <= 1;
            full_reg <= 0;
         end else begin
            if (ENQ && ~full_reg) begin
               data[ptr] <= enq_cnt;
               next_ptr <= ptr + 1;
               enq_cnt <= enq_cnt + 1;
            end
            if (DEQ && ~empty_reg) begin
               next_ptr <= ptr + 1;
               deq_cnt <= deq_cnt + 1;
            end
            ptr <= next_ptr;
            empty_reg <= (ptr == next_ptr) && (clear_cnt == 0);
            full_reg <= (ptr != next_ptr) && (clear_cnt == 0);
         end
         if (clear_cnt > 0) begin
            clear_cnt <= clear_cnt - 1;
         end
      end
   end

   always @ (posedge CLK) begin
      if (RST) begin
         $display("FIFO reset");
      end else begin
         if (~empty_reg && DEQ) begin
            $display("Warning: FIFO is not empty, dequeuing");
         end
         if (~full_reg && ENQ && (~DEQ || guarded)) begin
            $display("Warning: FIFO is not full, enqueuing");
         end
      end
   end

endmodule

module priority_encoder (
    input A1,
    input A2,
    input A3,
    input A4,
    output reg [1:0] X
);

always @* begin
    if (A4) begin
        X = 2'b11;
    end else if (A3) begin
        X = 2'b10;
    end else if (A2) begin
        X = 2'b01;
    end else if (A1) begin
        X = 2'b00;
    end else begin
        X = 2'b00;
    end
end

endmodule

module single_port_ram(
    input [13:0] address,
    input [15:0] data_in,
    input [1:0] byte_select,
    input chip_select,
    input write_enable,
    input output_enable,
    input power_down,
    input standby,
    input sleep,
    output reg [15:0] data_out
);

    reg [15:0] memory [0:16383];
    reg [15:0] masked_data;
    reg [13:0] byte_address;

    always @(posedge chip_select or negedge power_down or negedge standby or negedge sleep) begin
        if (!power_down && !standby && !sleep && chip_select) begin
            byte_address = address[13:1];
            masked_data = data_in;

            case (byte_select)
                2'b00: masked_data = {data_in[7:0], memory[byte_address][7:0]};
                2'b01: masked_data = {memory[byte_address][15:8], data_in[7:0]};
                2'b10: masked_data = {data_in[7:0], data_in[15:8]};
                2'b11: masked_data = {memory[byte_address][15:8], data_in[15:8]};
            endcase

            if (write_enable) begin
                memory[byte_address] <= masked_data;
            end

            if (output_enable) begin
                data_out <= masked_data;
            end
        end
    end
endmodule

module assert_next_cover (clk, reset_n, test_expr, start_event, no_overlapping);
  parameter OVL_COVER_BASIC_ON = 1;
  parameter OVL_COVER_CORNER_ON = 1;

  input clk, reset_n, test_expr, start_event, no_overlapping;
  output cover_ok, cover_fail;

  reg cover_ok, cover_fail;
  reg [31:0] basic_cov, corner_cov;
  reg [31:0] prev_basic_cov, prev_corner_cov;

  always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
      basic_cov <= 0;
      corner_cov <= 0;
      prev_basic_cov <= 0;
      prev_corner_cov <= 0;
      cover_ok <= 0;
      cover_fail <= 0;
    end
    else begin
      if (start_event) begin
        basic_cov <= 0;
        corner_cov <= 0;
        prev_basic_cov <= 0;
        prev_corner_cov <= 0;
        cover_ok <= 0;
        cover_fail <= 0;
      end
      else begin
        if (test_expr) begin
          basic_cov <= basic_cov | (1 << $bits(basic_cov));
          corner_cov <= corner_cov | (1 << $bits(corner_cov));
        end
        else begin
          corner_cov <= corner_cov | ((prev_basic_cov & basic_cov) << $bits(corner_cov));
          prev_basic_cov <= basic_cov;
          basic_cov <= basic_cov | (1 << $bits(basic_cov));
        end
        if (no_overlapping) begin
          if (((basic_cov & prev_basic_cov) != 0) || ((corner_cov & prev_corner_cov) != 0)) begin
            cover_fail <= 1;
          end
          else if ((OVL_COVER_BASIC_ON && (basic_cov == ((1 << $bits(basic_cov))-1))) ||
                   (OVL_COVER_CORNER_ON && (corner_cov == ((1 << $bits(corner_cov))-1)))) begin
            cover_ok <= 1;
          end
        end
        else begin
          if ((OVL_COVER_BASIC_ON && (basic_cov == ((1 << $bits(basic_cov))-1))) ||
              (OVL_COVER_CORNER_ON && (corner_cov == ((1 << $bits(corner_cov))-1)))) begin
            cover_ok <= 1;
          end
        end
      end
    end
  end
endmodule

module top_module (
    input clk,
    input areset,      // Asynchronous active-high reset to zero
    input load,
    input ena,
    input [3:0] data,
    input [3:0] in,    // Input for the priority encoder
    output [3:0] q     // Final 4-bit output
);

    // Priority encoder
    wire [1:0] sel;
    assign sel[1] = in[3] | in[2];
    assign sel[0] = sel[1] | in[1];
    assign q = {3'b0, sel[0], sel[1], in[0]};

    // Shift register
    reg [3:0] shift_reg;
    always @(posedge clk or negedge areset) begin
        if (areset) begin
            shift_reg <= 4'b0;
        end else if (load) begin
            shift_reg <= data;
        end else if (ena) begin
            shift_reg <= {shift_reg[2:0], shift_reg[3]};
        end
    end

    // OR operation
    wire [3:0] or_output;
    assign or_output = q | shift_reg;

    // Bit counter
    reg [2:0] count;
    always @(posedge clk or negedge areset) begin
        if (areset) begin
            count <= 3'b0;
        end else begin
            count <= count + {1'b0, or_output[3], or_output[2], or_output[1], or_output[0]};
        end
    end

    assign q = count;

endmodule

module burst_converter
  #(
    parameter IADDR = 32,
    parameter OADDR = 32
    )
    (
     input wire              clk_sys,
     input wire              rst,

     input wire [IADDR-1:0]  addr_in,
     input wire              write_in,
     input wire [31:0]       writedata_in,
     input wire              read_in,
     output wire [31:0]      readdata_out,
     output wire             readdatavalid_out,
     input wire [3:0]        byteenable_in,
     input wire [2:0]        burstcount_in,
     output wire             waitrequest_out,

     output wire [OADDR-1:0] addr_out,
     output wire             write_out,
     output wire [31:0]      writedata_out,
     output wire             read_out,
     input wire [31:0]       readdata_in,
     input wire              readdatavalid_in,
     output wire [3:0]       byteenable_out,
     input wire              waitrequest_in
     );


    // data
    // data[8] = valid bit
    reg [IADDR-1:0]          raddr, waddr;
    reg [3:0]                rcount, wcount;

    assign addr_out = (rcount[1]) ? raddr + 4 :
                      (rcount[2]) ? raddr + 8 :
                      (rcount[3]) ? raddr + 12 :
                      (wcount[1]) ? waddr + 4 :
                      (wcount[2]) ? waddr + 8 :
                      (wcount[3]) ? waddr + 12 : addr_in;

    assign writedata_out = writedata_in;
    assign byteenable_out = byteenable_in;

    assign write_out = write_in;
    assign read_out  = (read_in && burstcount_in != 0) || rcount;

    assign readdata_out = readdata_in;
    assign readdatavalid_out = readdatavalid_in;
    assign waitrequest_out = waitrequest_in;

    /////////////////////////////////////////////////////////////////////////
    // burst write
    /////////////////////////////////////////////////////////////////////////
    always @(posedge clk_sys) begin
        if(rst) begin
            wcount <= 0;
            waddr <= 0;
        end else if(wcount[1] && !waitrequest_in) begin
            wcount[1] <= 0;
        end else if(wcount[2] && !waitrequest_in) begin
            wcount[2] <= 0;
        end else if(wcount[3] && !waitrequest_in) begin
            wcount[3] <= 0;
        end else if(burstcount_in > 1 && write_in && !waitrequest_out) begin
            waddr <= addr_in;

            wcount <= (burstcount_in == 4) ? 4'b1110 :
                      (burstcount_in == 3) ? 4'b0110 :
                      (burstcount_in == 2) ? 4'b0010 : 0;
        end
    end

    /////////////////////////////////////////////////////////////////////////
    // burst read
    /////////////////////////////////////////////////////////////////////////
    always @(posedge clk_sys) begin
        if(rst) begin
            rcount <= 0;
            raddr <= 0;
        end else if(rcount[1] && !waitrequest_in) begin
            rcount[1] <= 0;
        end else if(rcount[2] && !waitrequest_in) begin
            rcount[2] <= 0;
        end else if(rcount[3] && !waitrequest_in) begin
            rcount[3] <= 0;
        end else if(burstcount_in > 1 && read_in && !waitrequest_out) begin
            raddr <= addr_in;

            rcount <= (burstcount_in == 4) ? 4'b1110 :
                      (burstcount_in == 3) ? 4'b0110 :
                      (burstcount_in == 2) ? 4'b0010 : 0;
        end
    end

endmodule

