module vending_machine_controller (
  input clk,
  input reset,
  input [2:0] product_select,
  input coin_insert,
  output reg [3:0] price_display,
  output reg dispense_product,
  output reg [3:0] change_due
);

  // define constants for product prices
  localparam PRODUCT_1_PRICE = 4'b0110; // 75 cents
  localparam PRODUCT_2_PRICE = 4'b0011; // 50 cents
  localparam PRODUCT_3_PRICE = 4'b1011; // 90 cents
  localparam PRODUCT_4_PRICE = 4'b0001; // 25 cents
  localparam PRODUCT_5_PRICE = 4'b0110; // 60 cents

  // define state machine states
  localparam IDLE_STATE = 2'b00;
  localparam SELECTED_STATE = 2'b01;
  localparam DISPENSING_STATE = 2'b10;

  // define state machine register and default state
  reg [1:0] state = IDLE_STATE;

  // define product price register
  reg [3:0] selected_product_price;

  // define coin insertion register
  reg coin_inserted = 0;

  // define money inserted register
  reg [3:0] money_inserted = 0;

  always @(posedge clk) begin
    if (reset) begin
      // reset state machine and registers
      state <= IDLE_STATE;
      selected_product_price <= 0;
      coin_inserted <= 0;
      money_inserted <= 0;
      price_display <= 0;
      dispense_product <= 0;
      change_due <= 0;
    end else begin
      case (state)
        IDLE_STATE: begin
          // display price of selected product
          case (product_select)
            3'b000: price_display <= PRODUCT_1_PRICE;
            3'b001: price_display <= PRODUCT_2_PRICE;
            3'b010: price_display <= PRODUCT_3_PRICE;
            3'b011: price_display <= PRODUCT_4_PRICE;
            3'b100: price_display <= PRODUCT_5_PRICE;
            default: price_display <= 0;
          endcase

          // transition to SELECTED_STATE when product is selected
          if (product_select != 3'b000) begin
            selected_product_price <= price_display;
            state <= SELECTED_STATE;
          end
        end

        SELECTED_STATE: begin
          // keep track of coins inserted
          if (coin_insert && !coin_inserted) begin
            coin_inserted <= 1;
            money_inserted <= money_inserted + 1;
          end else begin
            coin_inserted <= 0;
          end

          // check if enough money has been inserted
          if (money_inserted >= selected_product_price) begin
            state <= DISPENSING_STATE;
          end
        end

        DISPENSING_STATE: begin
          // dispense product and calculate change
          dispense_product <= 1;
          change_due <= money_inserted - selected_product_price;

          // reset state machine and registers
          state <= IDLE_STATE;
          selected_product_price <= 0;
          coin_inserted <= 0;
          money_inserted <= 0;
          price_display <= 0;
        end
      endcase
    end
  end

endmodule

