module sixteen_bit_counter (
    input clk,
    input [7:0] parallel_load_data,
    output reg [15:0] counter_data
);

reg [3:0] count1;
reg [3:0] count2;
reg [3:0] count3;
reg [3:0] count4;

four_bit_counter counter1 (.clk(clk), .count(count1));
four_bit_counter counter2 (.clk(clk), .count(count2));
four_bit_counter counter3 (.clk(clk), .count(count3));
four_bit_counter counter4 (.clk(clk), .count(count4));

reg [3:0] adder_in1;
reg [3:0] adder_in2;
reg [3:0] adder_out1;
reg [3:0] adder_out2;

four_bit_adder adder1 (.a(count1), .b(adder_in1), .sum(adder_out1));
four_bit_adder adder2 (.a(count3), .b(adder_in2), .sum(adder_out2));

always @(*) begin
    if (parallel_load_data != 8'b00000000) begin
        count1 <= parallel_load_data[3:0];
        count2 <= parallel_load_data[7:4];
        count3 <= parallel_load_data[11:8];
        count4 <= parallel_load_data[15:12];
    end else begin
        adder_in1 <= count2;
        adder_in2 <= count4;
        counter_data <= {count4, count3, count2, count1};
    end
end

always @(posedge clk) begin
    if (parallel_load_data == 8'b00000000) begin
        adder_in1 <= adder_out1;
        adder_in2 <= adder_out2;
        counter_data <= {count4, count3, count2, count1};
    end
end

endmodule

module fifo32to256(
  rst,
  wr_clk,
  rd_clk,
  din,
  wr_en,
  rd_en,
  dout,
  full,
  empty,
  rd_data_count,
  wr_data_count
);

input rst;
input wr_clk;
input rd_clk;
input [31 : 0] din;
input wr_en;
input rd_en;
output [255 : 0] dout;
output full;
output empty;
output [9 : 0] rd_data_count;
output [12 : 0] wr_data_count;

reg [31:0] fifo[0:255];
reg [9:0] rd_count;
reg [12:0] wr_count;
reg full_flag;
reg empty_flag;

// Write operation
always @(posedge wr_clk) begin
  if (rst) begin
    wr_count <= 0;
    full_flag <= 0;
    empty_flag <= 1;
  end else if (wr_en && !full_flag) begin
    fifo[wr_count] <= din;
    wr_count <= wr_count + 1;
    if (wr_count == 255) begin
      full_flag <= 1;
    end
    empty_flag <= 0;
  end
end

// Read operation
always @(posedge rd_clk) begin
  if (rst) begin
    rd_count <= 0;
    full_flag <= 0;
    empty_flag <= 1;
  end else if (rd_en && !empty_flag) begin
    dout <= fifo[rd_count];
    rd_count <= rd_count + 1;
    if (rd_count == 255) begin
      empty_flag <= 1;
    end
    full_flag <= 0;
  end
end

// Counters and flags
always @(posedge wr_clk, posedge rd_clk) begin
  if (rst) begin
    rd_count <= 0;
    wr_count <= 0;
    full_flag <= 0;
    empty_flag <= 1;
  end else begin
    rd_data_count <= rd_count;
    wr_data_count <= wr_count;
    full <= full_flag;
    empty <= empty_flag;
  end
end

endmodule

module arithmetic_op (
  output reg [7:0] result,
  input [7:0] operand1,
  input [7:0] operand2,
  input [1:0] select
);

