module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [3:0] ABCD, // Input for priority encoder
    output reg [1:0] Y, // Output from priority encoder
    output reg [7:0] sum // Output from functional module
);

reg [3:0] count; // 4-bit counter

// Synchronous reset
always @(posedge clk) begin
    if (reset) begin
        count <= 4'b0;
    end else begin
        count <= count + 1;
    end
end

// Priority encoder
always @(ABCD) begin
    casez(ABCD)
        4'b0001: Y <= 2'b00;
        4'b0010: Y <= 2'b01;
        4'b0100: Y <= 2'b10;
        4'b1000: Y <= 2'b11;
        default: Y <= 2'b00;
    endcase
end

// Functional module
always @(count, Y) begin
    sum <= count + Y;
end

endmodule

module phase_detector (
  input clk_ref,
  input clk_fb,
  output reg phase_diff
);

always @ (posedge clk_ref or posedge clk_fb) begin
  phase_diff <= clk_ref ^ clk_fb;
end

endmodule
module charge_pump (
  input phase_diff,
  input enable,
  output reg [7:0] charge
);

parameter CP_GAIN = 2; // charge pump gain factor

always @ (posedge phase_diff) begin
  if (enable) begin
    if (phase_diff) begin
      charge <= charge + CP_GAIN;
    end else begin
      charge <= charge - CP_GAIN;
    end
  end
end

endmodule
module loop_filter (
  input clk,
  input reset,
  input [7:0] charge,
  output reg [7:0] v_ctrl
);

parameter LPF_GAIN = 2; // loop filter gain factor

reg [7:0] v_int;
reg [7:0] v_prev;

always @ (posedge clk) begin
  if (reset) begin
    v_int <= 0;
    v_prev <= 0;
  end else begin
    v_int <= v_prev + charge;
    v_prev <= v_int;
  end
end

assign v_ctrl = v_int * LPF_GAIN;

endmodule
module vco (
  input clk,
  input reset,
  input [7:0] v_ctrl,
  output reg vco_ctrl
);

parameter VCO_GAIN = 2; // VCO gain factor

reg [7:0] v_int;
reg [7:0] v_prev;

always @ (posedge clk) begin
  if (reset) begin
    v_int <= 0;
    v_prev <= 0;
  end else begin
    v_int <= v_prev + v_ctrl;
    v_prev <= v_int;
  end
end

assign vco_ctrl = v_int * VCO_GAIN;

endmodule
module frequency_divider (
  input clk,
  input reset,
  input [7:0] vco_ctrl,
  output reg clk_out
);

parameter DIV_FACTOR = 8; // division factor for the frequency divider

reg [3:0] count;

always @ (posedge clk) begin
  if (reset) begin
    count <= 0;
    clk_out <= 0;
  end else begin
    count <= count + 1;
    if (count == DIV_FACTOR) begin
      count <= 0;
      clk_out <= ~clk_out;
    end
  end
end

assign clk = clk_out ^ vco_ctrl;

endmodule
module delay_line (
  input clk,
  input reset,
  input [7:0] v_ctrl,
  output reg [7:0] delay_out
);

parameter DELAY_TAP = 4; // delay line tap

reg [7:0] delay_line [0:DELAY_TAP-1];
reg [2:0] delay_index;

always @ (posedge clk) begin
  if (reset) begin
    delay_line <= 0;
    delay_index <= 0;
  end else begin
    delay_index <= delay_index + 1;
    if (delay_index == DELAY_TAP) begin
      delay_index <= 0;
    end
    delay_line[delay_index] <= v_ctrl;
  end
end

assign delay_out = delay_line[delay_index];

endmodule
