module pll (
	areset,
	inclk0,
	c0,
	c1,
	locked);

	input	  areset;
	input	  inclk0;
	output	  c0;
	output	  c1;
	output	  locked;

	reg [31:0] counter;
	reg [31:0] phase_accumulator;
	reg [31:0] phase_increment;
	reg [31:0] frequency_ratio;
	reg        locked_reg;

	// Calculate the phase increment and frequency ratio
	always @(*) begin
		frequency_ratio = 1000000000 / inclk0;
		phase_increment = frequency_ratio * (1 << 31) / 10000;
	end

	// Reset the PLL
	always @(posedge areset) begin
		counter <= 0;
		phase_accumulator <= 0;
		locked_reg <= 0;
	end

	// Generate the output clocks and detect lock
	always @(posedge inclk0) begin
		// Increment the phase accumulator
		phase_accumulator <= phase_accumulator + phase_increment;

		// Generate the output clock c0
		if (counter == 0) begin
			c0 <= 1;
			counter <= frequency_ratio / 2 - 1;
		end else begin
			c0 <= 0;
			counter <= counter - 1;
		end

		// Generate the output clock c1
		if (phase_accumulator[31] && !locked_reg) begin
			c1 <= 1;
			locked_reg <= 1;
		end else if (!phase_accumulator[31] && locked_reg) begin
			c1 <= 0;
			locked_reg <= 0;
		end
	end

	// Output the locked signal
	assign locked = locked_reg;

endmodule

module FrameTrans(Reset,Clock100M,Mode,Clock,DataIn);
  input Reset;
  input Clock100M;
  input [1:0] Mode;
  output Clock;
  output reg DataIn;

  reg [31:0] Counter;
  reg Clk_10ms;

  reg [7:0] StateCnt256;
  reg [1:0] FrameCnt4;
  reg FrameStart;
  reg ScrambEn;

  wire ScrambOut;

  parameter DELAY_NUM = 5;
  parameter FRAMEHEAD = 8'b1001_1011;
  parameter FRAMEHEAD_WRONG = 8'b1000_1001;

  assign Clock = Clk_10ms;

  // Generate Clk_400ms Signal;
  always@(negedge Reset or posedge Clock100M) begin
    if(Reset == 1'b0) begin
      Counter <= 0;
      Clk_10ms <= 0;
    end else begin
      Counter <= Counter + 1;
      if(Counter == DELAY_NUM) begin
        Counter <= 0;
        Clk_10ms <= ~Clk_10ms;
      end
    end
  end

  // Transmission Control
  always@(negedge Reset or posedge Clk_10ms) begin
    if(Reset == 1'b0) begin
      StateCnt256 <= 0;
      DataIn <= 0;
      FrameStart <= 0;
      ScrambEn <= 0;
      FrameCnt4 <= 0;
    end else if(Mode > 0) begin
      StateCnt256 <= StateCnt256 + 1;
      if(StateCnt256 == 0) begin
        FrameCnt4 <= 0;
        FrameStart <= 0;
        ScrambEn <= 0;
        DataIn <= 0;
      end else if(StateCnt256 < 8) begin
        ScrambEn <= 0;
        if(Mode == 3 && FrameCnt4 == 2) begin
          DataIn <= FRAMEHEAD_WRONG>>(7 - StateCnt256);
        end else begin
          DataIn <= FRAMEHEAD>>(7 - StateCnt256);
        end
        if(StateCnt256 == 4) begin
          FrameStart <= 1;
        end else if(StateCnt256 >= 5) begin
          ScrambEn <= 1;
        end
      end else begin
        DataIn <= ScrambOut;
        if(StateCnt256 == 255 && Mode == 1) begin
          StateCnt256 <= 255;
          ScrambEn <= 0;
          DataIn <= 0;
        end
      end
      if(StateCnt256 == 255) begin
        FrameCnt4 <= FrameCnt4 + 1;
      end
    end else begin
      StateCnt256 <= 0;
      DataIn <= 0;
      FrameStart <= 0;
      ScrambEn <= 0;
      FrameCnt4 <= 0;
    end
  end

  scrambler U1(
    .clk(Clk_10ms),
    .rst(Reset),
    .frame_start(FrameStart),
    .scramb_en(ScrambEn),
    .din(0),
    .dout(ScrambOut),
    .scramb_out_en()
  );

endmodule

module lcd_write_number
(
    input CLK_50MHZ,
    input ball_live,
    input [31:0] if_data,
    input if_write,
    output reg LCD_E,
    output reg LCD_RS,
    output reg LCD_RW,
    output reg [3:0] LCD_D
);

reg [1:0] state;
reg [31:0] cntr;
reg [31:0] cnt;
reg [7:0] hour, min, sec;
reg [15:0] decimal_number;

parameter IDLE = 2'b00,
IF_WRITE_1 = 2'b01,
SET_IF_WRITE_0 = 2'b10,
WAIT = 2'b11;

// Instantiate the Unit Under Test (UUT)
lcd_write_number_test uut
(
    .CLK_50MHZ(CLK_50MHZ),
    .ball_live(ball_live),
    .LCD_E(LCD_E),
    .LCD_RS(LCD_RS),
    .LCD_RW(LCD_RW),
    .LCD_D(LCD_D),
    .if_data(if_data),
    .if_write(if_write),
    .if_ready(if_ready)
);

assign LCD_D = decimal_number[15:12];

always @ (posedge CLK_50MHZ) begin
    if (if_ready && if_write) begin
        decimal_number = if_data / 100;
        decimal_number = decimal_number * 100;
        decimal_number = if_data - decimal_number;
        state <= IF_WRITE_1;
    end
end

always @ (posedge CLK_50MHZ) begin
    case (state)
        IDLE:
            if (if_ready) begin
                decimal_number = if_data / 100;
                decimal_number = decimal_number * 100;
                decimal_number = if_data - decimal_number;
                state <= IF_WRITE_1;
            end
        IF_WRITE_1:
            if (if_write) begin
                state <= SET_IF_WRITE_0;
            end
        SET_IF_WRITE_0:
            begin
                state <= WAIT;
                cntr <= 0;
            end
        WAIT:
            if (cntr < 25000000) begin
                cntr <= cntr + 1;
            end else begin
                state <= IDLE;
            end
    endcase
end

always @ (posedge CLK_50MHZ) begin
    if (cnt == 49999999 || ball_live == 0) begin
        cnt <= 0;
    end else begin
        cnt <= cnt + 1;
    end

    if (cnt == 49999999 && ball_live) begin
        if (sec != 59) begin
            if (sec[3:0] == 9) begin
                sec <= sec + 7;
            end else begin
                sec <= sec + 1;
            end
        end else begin
            sec <= 0;
            if (min != 59) begin
                if (min[3:0] == 9) begin
                    min <= min + 7;
                end else begin
                    min <= min + 1;
                end
            end else begin
                min <= 0;
                hour <= hour + 1;
            end
        end
    end else if (~ball_live) begin
        hour <= 0;
        min <= 0;
        sec <= 0;
    end
end

always @ (posedge CLK_50MHZ) begin
    if (state == IF_WRITE_1) begin
        LCD_RS <= 1;
        LCD_RW <= 0;
        LCD_E <= 1;
        LCD_D <= decimal_number[11:8];
    end else begin
        LCD_RS <= 0;
        LCD_RW <= 0;
        LCD_E <= 0;
        LCD_D <= 0;
    end
end

always @ (posedge CLK_50MHZ) begin
    if (state == SET_IF_WRITE_0) begin
        LCD_RS <= 1;
        LCD_RW <= 0;
        LCD_E <= 1;
        LCD_D <= decimal_number[7:4];
    end else begin
        LCD_RS <= 0;
        LCD_RW <= 0;
        LCD_E <= 0;
        LCD_D <= 0;
    end
end

endmodule

module altsyncram(clocken0,
                  wren_a,
                  clock0,
                  byteena_a,
                  address_a,
                  address_b,
                  data_a,
                  q_a,
                  q_b);

   parameter             intended_device_family = "Cyclone";
   parameter             width_a = 32;
   parameter             width_b = 32;
   parameter             widthad_a = 11;
   parameter             widthad_b = 11;
   parameter             numwords_a = 2048;
   parameter             numwords_b = 2048;
   parameter             operation_mode = "SINGLE_PORT";
   parameter             outdata_reg_a = "UNREGISTERED";
   parameter             indata_aclr_a = "NONE";
   parameter             wrcontrol_aclr_a = "NONE";
   parameter             address_aclr_a = "NONE";
   parameter             outdata_aclr_a = "NONE";
   parameter             width_byteena_a = 4;
   parameter             byte_size = 0;
   parameter             byteena_aclr_a = "NONE";
   parameter             ram_block_type = "AUTO";
   parameter             init_file = "dcache.mif";
   parameter             lpm_type = "altsyncram";

   // Dummys
   parameter             address_aclr_b = "NONE";
   parameter             address_reg_b = "CLOCK0";
   parameter             outdata_aclr_b = "NONE";
   parameter             outdata_reg_b = "UNREGISTERED";
   parameter             read_during_write_mode_mixed_ports = "DONT_CARE";

   parameter             debug = 0;

   input  wire                       clocken0;
   input  wire                       wren_a;
   input  wire                       clock0;
   input  wire [width_byteena_a-1:0] byteena_a;
   input  wire [widthad_a-1:0]       address_a;
   input  wire [widthad_b-1:0]       address_b;
   input  wire [width_a-1:0]         data_a;
   output wire [width_a-1:0]         q_a;
   output wire [width_b-1:0]         q_b;

   reg [width_a-1:0]          ram[numwords_a-1:0];

   reg [widthad_a-1:0]        addr_a_delayed;
   reg [width_a-1:0]          data_a_delayed;
   reg                        wren_a_delayed;
   reg [3:0]                  byteena_a_delayed;

   reg [widthad_b-1:0]        addr_b_delayed;
   reg [width_b-1:0]          data_b_delayed;
   reg                        wren_b_delayed;
   reg [3:0]                  byteena_b_delayed;

   wire [width_a-1:0] wr_mask =
                      byte_size
                      ? {{8{byteena_a_delayed[3]}},
                         {8{byteena_a_delayed[2]}},
                         {8{byteena_a_delayed[1]}},
                         {8{byteena_a_delayed[0]}}}
                      : ~0;

   always @(posedge clock0) begin
     if (clocken0 | byte_size == 0) begin
        data_a_delayed    <= data_a;
        addr_a_delayed    <= address_a;
        addr_b_delayed    <= address_b;
        wren_a_delayed    <= wren_a;
        byteena_a_delayed <= byteena_a;

        if (debug && operation_mode == "DUAL_PORT") begin
           $display("%5d altsyncram a: (%x) ram[%x] = %x", $time, address_a, addr_a_delayed, q_a);
           $display("%5d altsyncram b: (%x) ram[%x] = %x", $time, address_b, addr_b_delayed, q_b);

           if (wren_a_delayed)
             $display("%5d altsyncram ram[%x] <= %x",
                      $time, addr_a_delayed,
                      data_a_delayed & wr_mask |
                      ram[addr_a_delayed] & ~wr_mask);
        end

        // XXX 2005-06-20: As far as I can tell all this shouldn't
        // have used delayed signals!
        if (wren_a_delayed) begin

           ram[addr_a_delayed] <=
                 data_a_delayed & wr_mask | ram[addr_a_delayed] & ~wr_mask;
        end
     end
   end

   assign q_a = ram[addr_a_delayed];
   assign q_b = ram[addr_b_delayed];
endmodule

module top_module (
    input [1:0] sel,
    input [7:0] data0,
    input [7:0] data1,
    input [7:0] data2,
    input [7:0] data3,
    output reg [7:0] out
);

    wire [7:0] mux_out;
    wire [15:0] mult_out;

    mux_4to1 mux_inst (
        .sel(sel),
        .in0(data0),
        .in1(data1),
        .in2(data2),
        .in3(data3),
        .out(mux_out)
    );

    multiplier mult_inst (
        .in1(mux_out),
        .in2(8'b11111111),
        .out(mult_out)
    );

    always @(*) begin
        out <= mult_out[7:0];
    end

endmodule

module mux_4to1 (
    input [1:0] sel,
    input [7:0] in0,
    input [7:0] in1,
    input [7:0] in2,
    input [7:0] in3,
    output reg [7:0] out
);

    always @(*) begin
        case(sel)
            2'b00: out = in0;
            2'b01: out = in1;
            2'b10: out = in2;
            2'b11: out = in3;
        endcase
    end

endmodule

module multiplier (
    input [7:0] in1,
    input [7:0] in2,
    output reg [15:0] out
);

    always @(*) begin
        out = in1 * in2;
    end

endmodule

module multiplier_block (
    i_data0,
    o_data0
);

  // Port mode declarations:
  input   [31:0] i_data0;
  output  [31:0] o_data0;

  //Multipliers:
  wire [31:0]
    w1,
    w4,
    w5,
    w4096,
    w4101,
    w160,
    w4261,
    w17044,
    w17043;

  assign w1 = i_data0;
  assign w4 = i_data0 << 2;
  assign w5 = i_data0 + w4;
  assign w4096 = i_data0 << 12;
  assign w4101 = w5 + w4096;
  assign w160 = w5 << 5;
  assign w4261 = w4101 + w160;
  assign w17044 = w4261 << 2;
  assign w17043 = w17044 - w1;

  assign o_data0 = w17043;

endmodule

module data_shifter (
    clk,
    reset_n,
    shift_by,
    datain,
    dataout
);

parameter DATA_WIDTH = 8;
parameter REG_POST_RESET_HIGH = 0;

input clk;
input reset_n;
input [1:0] shift_by;
input [DATA_WIDTH-1:0] datain;
output [DATA_WIDTH-1:0] dataout;

reg [DATA_WIDTH-1:0] datain_r;

always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
        if (REG_POST_RESET_HIGH == 1)
            datain_r <= {DATA_WIDTH{1'b1}};
        else
            datain_r <= {DATA_WIDTH{1'b0}};
    end else begin
        datain_r <= datain;
    end
end

wire [DATA_WIDTH-1:0] dataout_pre;

assign dataout_pre = (shift_by[0] == 1'b1) ? {datain[2*DATA_WIDTH-1:DATA_WIDTH], datain_r[2*DATA_WIDTH-1:DATA_WIDTH]} : {datain[DATA_WIDTH-1:0], datain[2*DATA_WIDTH-1:DATA_WIDTH]};

assign dataout = (shift_by[1] == 1'b1) ? {dataout_pre[DATA_WIDTH-1:0], dataout_pre[2*DATA_WIDTH-1:DATA_WIDTH]} : {dataout_pre[2*DATA_WIDTH-1:DATA_WIDTH], dataout_pre[DATA_WIDTH-1:0]};

endmodule

module carry_select_adder(
    input [99:0] a, b,
    input cin,
    output cout,
    output [99:0] sum
);

wire [99:0] p, g, c, s;
wire [49:0] c0, c1, c2, c3, c4, c5, c6, c7, c8, c9;

assign p = a ^ b;
assign g = a & b;
assign c0 = cin;
assign c1 = g[0] | (p[0] & c0);
assign c2 = g[1] | (p[1] & c1);
assign c3 = g[2] | (p[2] & c2);
assign c4 = g[3] | (p[3] & c3);
assign c5 = g[4] | (p[4] & c4);
assign c6 = g[5] | (p[5] & c5);
assign c7 = g[6] | (p[6] & c6);
assign c8 = g[7] | (p[7] & c7);
assign c9 = g[8] | (p[8] & c8);

assign s = p ^ c;
assign cout = c9;
assign sum = {c9, s};

endmodule

module top_module( 
    input [99:0] a, b,
    input cin,
    output cout,
    output [99:0] sum );

carry_select_adder csa(
    .a(a),
    .b(b),
    .cin(cin),
    .cout(cout),
    .sum(sum)
);

endmodule

module ripple_carry_adder (
  input [3:0] A,
  input [3:0] B,
  input cin,
  output [3:0] sum,
  output cout
);

  wire [3:0] carry;
  full_adder fa0(A[0], B[0], cin, sum[0], carry[0]);
  full_adder fa1(A[1], B[1], carry[0], sum[1], carry[1]);
  full_adder fa2(A[2], B[2], carry[1], sum[2], carry[2]);
  full_adder fa3(A[3], B[3], carry[2], sum[3], cout);

endmodule
module full_adder (
  input a,
  input b,
  input cin,
  output sum,
  output cout
);

  assign sum = a ^ b ^ cin;
  assign cout = (a & b) | (a & cin) | (b & cin);

endmodule

module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    input reset,
    input Clk,
    input Clk_180,
    output [3:0] S,
    output Cout
);

reg [3:0] S_reg;
reg Cout_reg;

always @(posedge Clk, posedge reset) begin
    if (reset) begin
        S_reg <= 4'b0;
        Cout_reg <= 1'b0;
    end else begin
        S_reg <= A + B + Cin;
        Cout_reg <= ((A[3] & B[3]) | (Cin & (A[3] | B[3])));
    end
end

assign S = S_reg;
assign Cout = Cout_reg;

endmodule

module pllclk (input ext_clock, output pll_clock, input nrst, output lock);
