module td_mode_selector (
  input clk,
  input rst,
  input [8:0] ctrl,
  output reg [3:0] td_mode
);

  always @(posedge clk, posedge rst) begin
    if (rst) begin
      td_mode <= 4'b0000;
    end else begin
      case (ctrl[8:6])
        3'b000: td_mode <= 4'b0000;
        3'b001: td_mode <= 4'b1000;
        3'b010: td_mode <= 4'b0100;
        3'b011: td_mode <= 4'b1100;
        3'b100: td_mode <= 4'b0010;
        3'b101: td_mode <= 4'b1010;
        3'b110: td_mode <= 4'b0101;
        3'b111: td_mode <= 4'b1111;
        default: td_mode <= 4'b0000;
      endcase
    end
  end

endmodule

module bit_slip (
    input wire clk,
    input wire rst,
    input wire slip_dir,
    input wire [9:0] rxpdat2,
    input wire [9:0] rxpdat3,
    output reg [9:0] dataout
);

    parameter CHANNEL_WIDTH = 10;

    // Internal registers
    reg [9:0] dataout_tmp;
    reg [9:0] rxpdat;
    reg [9:0] rxpdat_next;
    reg [3:0] slip_count;
    reg [3:0] slip_count_next;
    reg [1:0] slip_dir_reg;
    reg [1:0] slip_dir_next;

    // Synchronous logic
    always @(posedge clk) begin
        if (rst) begin
            dataout <= 10'b0;
            dataout_tmp <= 10'b0;
            rxpdat <= 10'b0;
            rxpdat_next <= 10'b0;
            slip_count <= 4'b0;
            slip_count_next <= 4'b0;
            slip_dir_reg <= 2'b0;
            slip_dir_next <= 2'b0;
        end else begin
            // Update internal registers
            dataout_tmp <= {dataout_tmp[8:0], dataout_tmp[9]};
            rxpdat <= rxpdat_next;
            slip_count <= slip_count_next;
            slip_dir_reg <= slip_dir_next;

            // Handle bit slipping
            if (slip_dir_reg == 2'b00) begin
                // No slip
                dataout_tmp[0] <= rxpdat[0];
            end else if (slip_dir_reg == 2'b01) begin
                // Slip left
                dataout_tmp[0] <= rxpdat[1];
            end else if (slip_dir_reg == 2'b10) begin
                // Slip right
                dataout_tmp[0] <= rxpdat[CHANNEL_WIDTH-1];
            end

            // Update slip count and select next data channel
            if (slip_count == CHANNEL_WIDTH-1) begin
                slip_count_next <= 4'b0;
                rxpdat_next <= rxpdat3;
            end else begin
                slip_count_next <= slip_count + 1;
                rxpdat_next <= rxpdat2;
            end

            // Update output
            dataout <= dataout_tmp;
        end
    end

    // Combinational logic
    always @(*) begin
        // Update slip direction
        if (slip_dir == 1'b1) begin
            slip_dir_next[1] <= ~slip_dir_reg[0];
            slip_dir_next[0] <= ~slip_dir_reg[1];
        end else begin
            slip_dir_next <= slip_dir_reg;
        end
    end

endmodule

module top_module (
    input [3:0] A,
    input [3:0] B,
    input select,
    output reg [3:0] excess_3_out
);

reg [3:0] sum;
wire borrow;

addsub addsub_inst (
    .A(A),
    .B(B),
    .C(select),
    .sum(sum),
    .borrow(borrow)
);

excess_3_code excess_3_inst (
    .data_in(select ? sum : ~sum + 1),
    .excess_3_out(excess_3_out)
);

endmodule

module addsub (
    input [3:0] A,
    input [3:0] B,
    input C,
    output [3:0] sum,
    output borrow
);

wire [3:0] A_inv;
wire [3:0] B_inv;
wire [3:0] C_inv;

assign A_inv = ~A;
assign B_inv = ~B;
assign C_inv = ~C;

assign sum = C ? A + B : A + B_inv + 1;
assign borrow = C ? ~((A_inv & B) | (A_inv & C) | (B & C)) : ((A & B_inv) | (A & C_inv) | (B_inv & C_inv));

endmodule

module excess_3_code (
    input [3:0] data_in,
    output reg [3:0] excess_3_out
);

always @* begin
    case (data_in)
        4'b0000: excess_3_out = 4'b0011;
        4'b0001: excess_3_out = 4'b0100;
        4'b0010: excess_3_out = 4'b0101;
        4'b0011: excess_3_out = 4'b0110;
        4'b0100: excess_3_out = 4'b0111;
        4'b0101: excess_3_out = 4'b1000;
        4'b0110: excess_3_out = 4'b1001;
        4'b0111: excess_3_out = 4'b1010;
        4'b1000: excess_3_out = 4'b1011;
        4'b1001: excess_3_out = 4'b1100;
        4'b1010: excess_3_out = 4'b1101;
        4'b1011: excess_3_out = 4'b1110;
        4'b1100: excess_3_out = 4'b1111;
        4'b1101: excess_3_out = 4'b0000;
        4'b1110: excess_3_out = 4'b0001;
        4'b1111: excess_3_out = 4'b0010;
    endcase
end

endmodule

module full_adder (
  input A,
  input B,
  input C_in,
  output Sum,
  output C_out
);

  assign Sum = A ^ B ^ C_in;
  assign C_out = (A & B) | (C_in & (A ^ B));

endmodule

module ripple_carry_adder (
  input [3:0] A,
  input [3:0] B,
  input C_in,
  output [3:0] Sum,
  output C_out
);

  wire [3:0] carry;
  full_adder fa0(A[0], B[0], C_in, Sum[0], carry[0]);
  full_adder fa1(A[1], B[1], carry[0], Sum[1], carry[1]);
  full_adder fa2(A[2], B[2], carry[1], Sum[2], carry[2]);
  full_adder fa3(A[3], B[3], carry[2], Sum[3], C_out);

endmodule

module spi_cfg (
  input                     aclk,
  input [32-1:0]            s_axis_tdata,
  input                     s_axis_tvalid,
  input [8-1:0]             cmd,
  output reg [4-1:0]        cs,
  output reg                sdi,
  output reg                sclk,
  output reg                s_axis_tready
);

  reg [32-1:0]              data_reg;
  reg [8-1:0]               cmd_reg;
  reg [4-1:0]               cs_reg;
  reg                       sdi_reg;
  reg                       sclk_reg;
  reg                       busy;

  always @(posedge aclk) begin
    if (s_axis_tvalid && !busy) begin
      data_reg <= s_axis_tdata;
      cmd_reg <= cmd;
      cs_reg <= 4'b1110;
      sdi_reg <= 1'b1;
      sclk_reg <= 1'b0;
      s_axis_tready <= 1'b1;
      busy <= 1'b1;
    end else if (busy) begin
      if (cs_reg == 4'b1110) begin
        cs_reg <= 4'b1101;
        sdi_reg <= data_reg[31];
        data_reg <= {data_reg[30:0], 1'b0};
      end else if (cs_reg == 4'b1101) begin
        cs_reg <= 4'b1011;
        sdi_reg <= data_reg[31];
        data_reg <= {data_reg[30:0], 1'b0};
      end else if (cs_reg == 4'b1011) begin
        cs_reg <= 4'b0111;
        sdi_reg <= data_reg[31];
        data_reg <= {data_reg[30:0], 1'b0};
      end else if (cs_reg == 4'b0111) begin
        cs_reg <= 4'b1110;
        sdi_reg <= cmd_reg[7];
        cmd_reg <= {cmd_reg[6:0], 1'b0};
      end else begin
        busy <= 1'b0;
        s_axis_tready <= 1'b0;
      end
      sclk_reg <= ~sclk_reg;
    end else begin
      cs_reg <= 4'b1111;
      sdi_reg <= 1'b0;
      sclk_reg <= 1'b0;
      s_axis_tready <= 1'b0;
    end
  end

  assign cs = cs_reg;
  assign sdi = sdi_reg;
  assign sclk = sclk_reg;

endmodule

module SB_GB (
