module one_shot (
  input trig,
  input clk,
  input rst,
  output out
);

  parameter t = 10; // duration of output pulse in clock cycles

  reg [31:0] count = 0;
  reg pulse = 0;

  always @(posedge clk) begin
    if (rst) begin
      count <= 0;
      pulse <= 0;
      out <= 0;
    end
    else if (trig && !pulse) begin
      count <= 0;
      pulse <= 1;
      out <= 1;
    end
    else if (pulse && count < t-1) begin
      count <= count + 1;
      out <= 1;
    end
    else if (pulse && count == t-1) begin
      count <= 0;
      pulse <= 0;
      out <= 0;
    end
    else begin
      out <= 0;
    end
  end

endmodule

module division_module (
    input [7:0] A,
    input [7:0] B,
    output reg [7:0] quotient,
    output reg [7:0] remainder,
    output reg valid
);

always @(*) begin
    if (B == 0) begin
        quotient <= 8'b0;
        remainder <= 8'b0;
        valid <= 1'b1;
    end else begin
        quotient <= A / B;
        remainder <= A % B;
        valid <= 1'b1;
    end
end

endmodule

module binary_counter(
  input rst,
  input clk,
  input [31:0] max_count,
  output reg [31:0] count
);

always @(posedge clk) begin
  if(rst) begin
    count <= 0;
  end else if(count == max_count) begin
    count <= 0;
  end else begin
    count <= count + 1;
  end
end

endmodule

module my_module (
    input [2:0] a,
    input [2:0] b,
    input [2:0] c,
    input [2:0] d,
    input [1:0] e,
    input clk,
    input rst,
    output reg y
);

reg [2:0] a_msb, b_msb;
reg [2:0] c_lsb, d_lsb;
reg [1:0] e_lsb;
reg e_msb;

always @ (posedge clk) begin
    if (rst) begin
        y <= 0;
    end else begin
        a_msb <= a[2:0];
        b_msb <= b[2:0];
        c_lsb <= c[0:2];
        d_lsb <= d[0:2];
        e_lsb <= e[0:1];
        e_msb <= e[2];

        if ((a_msb == b_msb) && (c_lsb == d_lsb) && (e_lsb == a[0] && e_msb == c[2])) begin
            y <= 1;
        end else begin
            y <= 0;
        end
    end
end

endmodule

module dtc
  #(parameter MIN_PULSE = 50, MAX_PULSE = 200, MIN_DEAD = 10)
  (input wire c, i_tgt,
   output reg [15:0] i_est,
   output reg i_est_valid,
   output reg mosfet_hi, mosfet_lo);

  reg [15:0] i_tgt_prev;
  reg [15:0] i_est_prev;
  reg [15:0] i_est_next;
  reg [15:0] i_diff;
  reg [15:0] i_diff_abs;
  reg [15:0] max_t;
  reg [15:0] min_t;
  reg [15:0] dead;
  reg [15:0] pulse;
  reg [15:0] pulse_count;
  reg [15:0] dead_count;
  reg [15:0] pulse_dir;
  reg [15:0] dead_dir;
  reg [15:0] mosfet_hi_next;
  reg [15:0] mosfet_lo_next;

  always @(posedge c) begin
    i_tgt_prev <= i_tgt;
  end

  always @(negedge c) begin
    i_est_prev <= i_est;
    i_diff <= i_tgt_prev - i_est_prev;
    i_diff_abs <= (i_diff >= 0) ? i_diff : -i_diff;
    if (i_diff_abs >= 50) begin
      if (i_diff >= 0) begin
        mosfet_hi_next <= 1'b1;
        mosfet_lo_next <= 1'b0;
      end else begin
        mosfet_hi_next <= 1'b0;
        mosfet_lo_next <= 1'b1;
      end
    end else begin
      mosfet_hi_next <= 1'b0;
      mosfet_lo_next <= 1'b0;
    end
  end

  always @(negedge c) begin
    if (pulse_count == 0) begin
      pulse_dir <= (i_diff >= 0) ? 1'b0 : 1'b1;
      pulse <= (i_diff_abs > MAX_PULSE) ? MAX_PULSE : i_diff_abs;
      pulse_count <= pulse;
      dead_count <= MIN_DEAD;
      max_t <= (pulse > dead) ? pulse : dead;
      min_t <= (pulse < dead) ? pulse : dead;
      dead_dir <= (pulse > dead) ? pulse_dir : ~pulse_dir;
    end else begin
      pulse_count <= pulse_count - 1;
      dead_count <= dead_count - 1;
    end
  end

  always @(negedge c) begin
    if (pulse_count == 0) begin
      i_est_next <= i_est_prev + (pulse_dir ? -pulse : pulse);
    end else if (dead_count == 0) begin
      i_est_next <= i_est_prev + (dead_dir ? -dead : dead);
    end else begin
      i_est_next <= i_est_prev;
    end
  end

  always @(negedge c) begin
    i_est <= i_est_next;
    i_est_valid <= 1'b1;
  end

  always @(posedge c) begin
    i_est_valid <= 1'b0;
    mosfet_hi <= mosfet_hi_next;
    mosfet_lo <= mosfet_lo_next;
  end

endmodule

module counter (
