module uart (
  input clk,
  input reset_n,
  input begintransfer,
  input chipselect,
  input write_n,
  input [7:0] writedata,
  input read_n,
  input [2:0] address,
  output reg dataavailable,
  output reg irq,
  output reg [7:0] readdata,
  output reg readyfordata,
  output reg txd
);

  // Internal signals
  reg [7:0] rx_data;
  reg [7:0] tx_data;
  reg [1:0] tx_state;
  reg [3:0] rx_state;
  reg [3:0] bit_count;
  reg [3:0] parity_count;
  reg [7:0] shift_reg;
  reg [7:0] last_rx_data;
  reg       rx_char_ready;
  reg       tx_ready;
  reg       tx_shift_empty;
  reg       framing_error;
  reg       parity_error;
  reg       rx_overrun;
  reg       tx_overrun;
  reg       break_detect;
  reg       do_force_break;
  reg       irq_pending;

  // Constants
  localparam BAUD_RATE = 115200;
  localparam BIT_PERIOD = 1_000_000_000 / BAUD_RATE;
  localparam HALF_BIT_PERIOD = BIT_PERIOD / 2;
  localparam PARITY_BIT = 1;

  // Divider for generating baud rate
  reg [15:0] baud_divisor;
  always @ (posedge clk) begin
    if (reset_n == 0) begin
      baud_divisor <= 0;
    end else begin
      baud_divisor <= $floor((clk / BAUD_RATE) + 0.5);
    end
  end

  // Transmitter state machine
  always @ (posedge clk) begin
    if (reset_n == 0) begin
      tx_data <= 0;
      tx_state <= 2'b00;
      txd <= 1;
      tx_ready <= 1;
      tx_shift_empty <= 1;
      irq_pending <= 0;
    end else begin
      case (tx_state)
        // Start bit
        2'b00: begin
          txd <= 0;
          tx_state <= 2'b01;
          bit_count <= 0;
          parity_count <= 0;
          shift_reg <= {1'b0, tx_data, PARITY_BIT};
          tx_shift_empty <= 0;
        end

        // Data bits
        2'b01: begin
          if (bit_count < 8) begin
            txd <= shift_reg[0];
            shift_reg <= {shift_reg[0], shift_reg[8:1], PARITY_BIT};
            bit_count <= bit_count + 1;
            parity_count <= parity_count + shift_reg[0];
          end else begin
            tx_state <= 2'b10;
            bit_count <= 0;
          end
        end

        // Stop bits
        2'b10: begin
          txd <= 1;
          tx_state <= 2'b00;
          tx_ready <= 1;
          tx_shift_empty <= 1;
          if (irq_pending == 1) begin
            irq <= 1;
          end
        end
      endcase
    end
  end

  // Receiver state machine
  always @ (posedge clk) begin
    if (reset_n == 0) begin
      rx_state <= 4'b0000;
      rx_data <= 8'd0;
      last_rx_data <= 8'd0;
      rx_char_ready <= 0;
      framing_error <= 0;
      parity_error <= 0;
      rx_overrun <= 0;
      break_detect <= 0;
    end else begin
      case (rx_state)
        // Start bit
        4'b0000: begin
          if (chipselect == 1 && begintransfer == 1 && read_n == 0 && write_n == 1 && address == 8'h00) begin
            do_force_break <= writedata[0];
            rx_state <= 4'b0001;
            bit_count <= 0;
            parity_count <= 0;
            rx_data <= 8'd0;
            last_rx_data <= 8'd0;
          end else if (rx_char_ready == 1) begin
            rx_overrun <= 1;
            rx_state <= 4'b0000;
          end
        end

        // Data bits
        4'b0001: begin
          if (bit_count < 8) begin
            rx_data <= {rx_data[6:0], rxd};
            bit_count <= bit_count + 1;
            parity_count <= parity_count + rxd;
          end else begin
            rx_state <= 4'b0010;
            bit_count <= 0;
          end
        end

        // Parity bit
        4'b0010: begin
          if (rxd == (parity_count & 1)) begin
            rx_state <= 4'b0011;
          end else begin
            parity_error <= 1;
            rx_state <= 4'b0000;
          end
        end

        // Stop bits
        4'b0011: begin
          if (rxd == 1) begin
            rx_char_ready <= 1;
            last_rx_data <= rx_data;
            if (last_rx_data == 8'h00 && rx_data == 8'h00 && do_force_break == 1) begin
              break_detect <= 1;
              irq_pending <= 1;
            end
            if (rx_char_ready == 1) begin
              dataavailable <= 1;
              irq_pending <= 1;
            end
            rx_state <= 4'b0000;
          end else if (rxd == 0) begin
            framing_error <= 1;
            rx_state <= 4'b0000;
          end
        end
      endcase
    end
  end

  // Interface control logic
  always @ (posedge clk) begin
    if (reset_n == 0) begin
      dataavailable <= 0;
      irq <= 0;
      readdata <= 0;
      readyfordata <= 0;
    end else begin
      if (chipselect == 1 && begintransfer == 1) begin
        if (read_n == 0) begin
          case (address)
            3'b000: begin
              readdata <= rx_data;
              dataavailable <= 0;
              irq <= 0;
            end

            3'b001: begin
              readdata <= 0;
              dataavailable <= rx_char_ready;
              irq <= irq_pending;
              irq_pending <= 0;
            end

            3'b010: begin
              readdata <= 0;
              readyfordata <= tx_ready;
            end

            3'b011: begin
              readdata <= 0;
              irq <= 0;
            end

            default: begin
              readdata <= 0;
              dataavailable <= 0;
              irq <= 0;
            end
          endcase
        end else if (write_n == 0) begin
          case (address)
            3'b000: begin
              rx_data <= writedata;
              rx_char_ready <= 0;
              irq_pending <= 0;
              framing_error <= 0;
              parity_error <= 0;
              rx_overrun <= 0;
              break_detect <= 0;
            end

            3'b001: begin
              irq <= 0;
            end

            3'b010: begin
              tx_data <= writedata;
              tx_ready <= 0;
            end

            3'b011: begin
              irq <= 0;
            end
          endcase
        end
      end
    end
  end

endmodule

