module top_module (
    input clk,
    input [7:0] A,
    input [7:0] B,
    input [1:0] shift,
    output [15:0] product
);

    reg [7:0] shifted_B;
    reg [15:0] partial_product;
    reg [15:0] final_product;

    barrel_shifter_4bit shifter (
        .in(B),
        .shift(shift),
        .out(shifted_B)
    );

    binary_multiplier multiplier (
        .clk(clk),
        .A(A),
        .B(shifted_B),
        .product(partial_product)
    );

    always @(posedge clk) begin
        final_product <= final_product + partial_product;
    end

    assign product = final_product;

endmodule

module barrel_shifter_4bit (
    input [3:0] in,
    input [1:0] shift,
    output reg [3:0] out
);

    always @(*) begin
        case (shift)
            2'b00: out = in << 1;
            2'b01: out = in >> 1;
            2'b10: out = $signed({in[3], in[3:1]}) << 1;
            2'b11: out = $signed({in[3], in[3:1]}) >> 1;
        endcase
    end

endmodule

module binary_multiplier (
    input clk,
    input [7:0] A,
    input [7:0] B,
    output reg [15:0] product
);

    reg [7:0] shifted_B;

    always @(posedge clk) begin
        shifted_B <= {B[6:0], 1'b0};
    end

    always @(posedge clk) begin
        product <= A * shifted_B;
    end

endmodule

