module decoder (
    input [2:0] ABC,
    output reg [7:0] Y
);

reg [2:0] A, B, C;
reg [7:0] Y_temp;

always @ (posedge clk) begin
    A <= ABC[0];
    B <= ABC[1];
    C <= ABC[2];
end

always @ (posedge clk) begin
    Y_temp <= 8'b00000000;
    if (A == 0 && B == 0 && C == 0) Y_temp[0] <= 1;
    else if (A == 0 && B == 0 && C == 1) Y_temp[1] <= 1;
    else if (A == 0 && B == 1 && C == 0) Y_temp[2] <= 1;
    else if (A == 0 && B == 1 && C == 1) Y_temp[3] <= 1;
    else if (A == 1 && B == 0 && C == 0) Y_temp[4] <= 1;
    else if (A == 1 && B == 0 && C == 1) Y_temp[5] <= 1;
    else if (A == 1 && B == 1 && C == 0) Y_temp[6] <= 1;
    else if (A == 1 && B == 1 && C == 1) Y_temp[7] <= 1;
end

always @ (posedge clk) begin
    Y <= Y_temp;
end

endmodule

module fifo(
  input rst,
  input wr_clk,
  input rd_clk,
  input [30:0] din,
  input wr_en,
  input rd_en,
  output [30:0] dout,
  output full,
  output empty
);

reg [30:0] mem [0:15];
reg [3:0] wr_ptr;
reg [3:0] rd_ptr;
wire [3:0] next_wr_ptr;
wire [3:0] next_rd_ptr;
wire [3:0] wr_ptr_plus_1;
wire [3:0] rd_ptr_plus_1;
wire [3:0] rd_ptr_plus_2;
wire [3:0] mem_count;
wire [3:0] mem_count_plus_1;
wire [3:0] mem_count_minus_1;

assign wr_ptr_plus_1 = wr_ptr + 1;
assign rd_ptr_plus_1 = rd_ptr + 1;
assign rd_ptr_plus_2 = rd_ptr + 2;
assign mem_count = wr_ptr - rd_ptr;
assign mem_count_plus_1 = wr_ptr_plus_1 - rd_ptr;
assign mem_count_minus_1 = wr_ptr - rd_ptr_plus_1;

assign full = (mem_count_plus_1 == 16);
assign empty = (mem_count == 0);

assign next_wr_ptr = (wr_en && !full) ? wr_ptr_plus_1 : wr_ptr;
assign next_rd_ptr = (rd_en && !empty) ? rd_ptr_plus_1 : rd_ptr;

always @(posedge wr_clk) begin
  if (rst) begin
    wr_ptr <= 0;
  end else begin
    wr_ptr <= next_wr_ptr;
    mem[wr_ptr] <= din;
  end
end

always @(posedge rd_clk) begin
  if (rst) begin
    rd_ptr <= 0;
  end else begin
    rd_ptr <= next_rd_ptr;
    dout <= mem[rd_ptr];
  end
end

endmodule

module top_module( 
    input [99:0] in,
    output out_and,
    output out_or,
    output out_xor 
);

    wire [24:0] and_out;
    wire [24:0] or_out;
    wire [24:0] xor_out;

    // Implementing 100-input AND gate using 4-input AND gates
    and_gate and1(
        .in({in[3:0], in[7:4], in[11:8], in[15:12], in[19:16], in[23:20], in[27:24], in[31:28], in[35:32], in[39:36], in[43:40], in[47:44], in[51:48], in[55:52], in[59:56], in[63:60], in[67:64], in[71:68], in[75:72], in[79:76], in[83:80], in[87:84], in[91:88], in[95:92], in[99:96]}),
        .out(and_out)
    );

    // Implementing 100-input OR gate
    or_gate or1(
        .in({in[3:0], in[7:4], in[11:8], in[15:12], in[19:16], in[23:20], in[27:24], in[31:28], in[35:32], in[39:36], in[43:40], in[47:44], in[51:48], in[55:52], in[59:56], in[63:60], in[67:64], in[71:68], in[75:72], in[79:76], in[83:80], in[87:84], in[91:88], in[95:92], in[99:96]}),
        .out(or_out)
    );

    // Implementing 100-input XOR gate
    xor_gate xor1(
        .in({and_out[3:0], and_out[7:4], and_out[11:8], and_out[15:12], and_out[19:16], and_out[23:20], and_out[27:24], and_out[31:28], and_out[35:32], and_out[39:36], and_out[43:40], and_out[47:44], and_out[51:48], and_out[55:52], and_out[59:56], and_out[63:60], and_out[67:64], and_out[71:68], and_out[75:72], and_out[79:76], and_out[83:80], and_out[87:84], and_out[91:88], and_out[95:92], and_out[99:96]}),
        .out(xor_out)
    );

    assign out_and = and_out[24];
    assign out_or = or_out[24];
    assign out_xor = xor_out[24];

endmodule

