module clock_generator (
  input clk_in,
  input rst,
  input [31:0] frequency,
  input [7:0] duty_cycle,
  output reg clk_out
);

  reg [31:0] period;
  reg [31:0] high_time;
  reg [31:0] low_time;
  reg [1:0] duty_cycle_divider;

  always @ (posedge clk_in or posedge rst) begin
    if (rst) begin
      clk_out <= 0;
      period <= 0;
      high_time <= 0;
      low_time <= 0;
      duty_cycle_divider <= 0;
    end else begin
      period <= clk_in / frequency;
      high_time <= period * duty_cycle / 100;
      low_time <= period - high_time;
      duty_cycle_divider <= period / 256;
      if (duty_cycle_divider == 0) begin
        duty_cycle_divider <= 1;
      end
      if (duty_cycle_divider == 1) begin
        clk_out <= 1;
      end else begin
        if (duty_cycle_divider == 2) begin
          clk_out <= (high_time > low_time);
        end else begin
          clk_out <= (duty_cycle_divider[1] == 1) ? (high_time > low_time) : ~clk_out;
        end
      end
    end
  end

endmodule

module darren_jones_2 (/*AUTOARG*/
   // Outputs
   next_WSTATE,
   // Inputs
   WSTATE
   );
   input [1:0] WSTATE;
   output [1:0] next_WSTATE;
   reg [1:0] 	next_WSTATE;
   parameter
     WIDLE		= 0,		// No Manual Write Burst
       WCB0		= 1;		// 1st of the 4 Manual Write Burst

   always @ (/*AUTOSENSE*/WSTATE) begin
      next_WSTATE = 2'b0;
      case (1'b1)
	WSTATE[WIDLE]:
	  next_WSTATE[1'b0] = 1'b1;
	WSTATE[WCB0]:
	  next_WSTATE[WCB0] = 1'b1;
      endcase
   end
endmodule

module FrequencyDivider(clk, clk_out);

input clk;
output reg clk_out;
reg rst;

// Calculate the value of n
parameter Ts = 80;
parameter Te = 20;
parameter n = ((Ts / (2 * Te)) - 1);

// Determine the number of bits needed to represent n in binary
parameter bitCount = $clog2(n + 1) - 1;

// Counter to keep track of the number of input clock cycles
reg [bitCount:0] counter;

initial
begin
    rst = 0;
end

always @(posedge clk or negedge rst)
begin
    if (!rst)
    begin
        // Reset the counter and output clock signal
        rst <= 1;
        counter <= {bitCount{1'b0}};
        clk_out <= 1'b0;
    end
    else
    begin
        // Increment the counter
        counter <= counter + 1;

        // If the counter reaches n, toggle the output clock signal
        if (counter == n)
        begin
            counter <= {bitCount{1'b0}};
            clk_out <= ~clk_out;
        end
    end
end

endmodule

module add_subtract_overflow (
    input [15:0] A,
    input [15:0] B,
    input MODE,
    input CIN,
    output [15:0] Q,
    output overflow
);

    wire [15:0] sum;
    wire carry_out;
    wire overflow_detect;

    // First given module for addition or subtraction
    full_adder_16 FA16 (
        .A(A),
        .B(B),
        .CIN(CIN),
        .SUM(sum),
        .COUT(carry_out)
    );

    // Second given module for overflow detection
    overflow_detector_16 OD16 (
        .A(A),
        .B(B),
        .SUM(sum),
        .CIN(CIN),
        .COUT(carry_out),
        .OVERFLOW(overflow_detect)
    );

    // Additional functional module for final output
    assign Q = (MODE) ? (A - B - CIN) : (A + B + CIN);
    assign overflow = overflow_detect;

endmodule

