module serial_device(reset, clk, data, tx, rts, cts, end_flag);
    input  reset;
    input  clk;
    output tx;
    output [7:0] data;
    output rts;
    input cts;
    output end_flag;

    reg tx;
    reg [7:0] data;
    wire rts;
    reg end_flag;

    reg [7:0] buffer;
    reg [3:0] data_cnt;
    reg [4:0] multi_cnt;
    reg sending;
    reg start_bit;
    reg stop_bit;
    reg stop_bit_running;

    assign rts = ~sending;

    always @(negedge reset) begin
        buffer <= 8'b0;
        data <= 8'b0;
        multi_cnt <= 8'b0;
        sending <= 1'b0;
        end_flag <= 1'b0;
        tx <= 1'b1;
    end

    always @(posedge clk) begin
        if (reset) begin
            if (sending) begin
                multi_cnt <= multi_cnt + 5'b1;
                if (multi_cnt == 5'b11111) begin
                    if (start_bit) begin
                        tx <= 1'b0;
                        start_bit <= 1'b0;
                    end else if (stop_bit) begin
                        if (stop_bit_running) begin
                            sending <= 1'b0;
                            data[7:0] <= data[7:0] + 8'b1;
                            if (data[7:0] == 8'b11111111) begin
                                end_flag <= 1'b1;
                            end
                        end else begin
                            tx <= 1'b1;
                            stop_bit_running <= 1'b1;
                        end
                    end else begin
                        tx <= buffer[0];
                        buffer[7:0] <= { 1'b0, buffer[7:1] };
                        data_cnt <= data_cnt + 3'b1;
                        if (data_cnt == 3'b111) begin
                            stop_bit <= 1'b1;
                            stop_bit_running <= 1'b0;
                        end
                    end
                end
            end else begin
                if (cts) begin
                    sending <= 1'b1;
                    multi_cnt <= 5'b0;
                    start_bit <= 1'b1;
                    stop_bit <= 1'b0;
                    stop_bit_running <= 1'b0;
                    data_cnt <= 3'b0;
                    buffer[7:0] <= data[7:0];
                end
            end
        end else begin
            if (rts) begin
                data <= 8'b0;
            end else begin
                data <= data;
            end
        end
    end
endmodule

module tausworthe(urng_seed1, urng_seed2, urng_seed3, clk, reset, out, valid);

input [31:0] urng_seed1;
input [31:0] urng_seed2;
input [31:0] urng_seed3;
input clk, reset;
output reg [31:0] out;
output reg valid;

reg [31:0] b1, b2, b3, seed1, seed2, seed3, seed4;

initial begin
    out = 0;
    valid = 0;
    seed1 = 0;
    seed2 = 0;
    seed3 = 0;
    seed4 = 0;
    b1 = 0;
    b2 = 0;
    b3 = 0;
end

always @(posedge clk, posedge reset) begin
    if (reset) begin
        out <= 0;
        valid <= 0;
    end else begin
        // Generate LFSR outputs
        b1 <= (((urng_seed1 << 13) ^ urng_seed1) >> 19);
        seed1 <= (((urng_seed1 & 'hFFFFFFFE) << 12) ^ b1);
        b2 <= (((urng_seed2 << 2) ^ urng_seed2) >> 25);
        seed2 <= (((urng_seed2 & 'hFFFFFFF8) << 4) ^ b2);
        b3 <= (((urng_seed3 << 3) ^ urng_seed3) >> 11);
        seed3 <= (((urng_seed3 & 'hFFFFFFF0) << 17) ^ b3);

        // Combine LFSR outputs to generate pseudo-random number
        seed4 <= seed1 ^ seed2;
        out <= seed4 ^ seed3;
        valid <= 1;
    end
end

endmodule

module GlitchFreeClockMux (
  input [n-1:0] clk,
  input sel,
  output out
);

parameter n = 4; // number of clock signals

reg [n-1:0] sync_clk;
reg [n-1:0] prev_clk;
reg [n-1:0] delay_clk;

always @ (posedge clk[0] or posedge clk[1] or posedge clk[2] or posedge clk[3] or posedge sel) begin
  if (sel == 1'b0) begin
    sync_clk <= clk[0];
  end else begin
    sync_clk <= clk[1];
  end
end

always @ (posedge clk[0] or posedge clk[1] or posedge clk[2] or posedge clk[3] or posedge sel) begin
  if (sel == 1'b0) begin
    delay_clk <= clk[1];
  end else begin
    delay_clk <= clk[0];
  end
end

always @ (posedge clk[0] or posedge clk[1] or posedge clk[2] or posedge clk[3] or posedge sel) begin
  if (sel == 1'b0) begin
    prev_clk <= clk[0];
  end else begin
    prev_clk <= clk[1];
  end
end

always @ (posedge sync_clk) begin
  out <= delay_clk;
end

always @ (posedge sync_clk) begin
  if (prev_clk != sync_clk) begin
    out <= delay_clk;
  end
end

endmodule

module add4(
