module adder_8bit (
    input [7:0] a,
    input [7:0] b,
    output [8:0] s,
    output overflow
);

wire [7:0] g, p, c;

assign g = a & b;
assign p = a ^ b;
assign c[0] = 1'b0;

genvar i;
generate
    for (i = 1; i < 8; i = i + 1) begin
        assign c[i] = (g[i-1] | (p[i-1] & c[i-1]));
    end
endgenerate

assign s = {c[7], p} + a + b;

assign overflow = ((a[7] == b[7]) && (a[7] != s[8]));

endmodule

module decade_counter (
    input clk,
    input slowena,
    input reset,
    output reg [3:0] q);

    reg [3:0] q_next;
    wire [1:0] select;
    wire [3:0] q_mux;

    // D flip-flops
    always @(posedge clk or negedge reset) begin
        if (reset == 0) begin
            q <= 4'b0000;
        end else begin
            q <= q_next;
        end
    end

    // Multiplexers
    assign select = slowena ? 2'b10 : 2'b01;
    assign q_mux = {4'b0000, q} + select;

    // Next state logic
    always @(posedge clk or negedge reset) begin
        if (reset == 0) begin
            q_next <= 4'b0000;
        end else if (slowena == 0) begin
            q_next <= q + 1;
        end else begin
            q_next <= q;
        end
    end

    // Output
    assign q = q_mux;

endmodule

