module three_stage_register(
    input b,
    input [10:0] e,
    input c,
    input reset,
    input clk,
    output reg [10:0] q,
    output reg rb
);

reg [10:0] r_b;
reg [10:0] r_e;
reg [10:0] r_c;
reg [10:0] rr_e;
reg [10:0] rr_b;
reg [10:0] r_qx;
reg [10:0] e2;

always @(posedge clk) begin
    if (reset) begin
        r_b <= 0;
        r_e <= 0;
    end else begin
        r_e <= e;
        r_b <= b;
    end
end

always @(posedge clk) begin
    if (reset) begin
        r_c <= 0;
        rr_e <= 0;
        rr_b <= 0;
    end else begin
        r_c <= c;
        rr_e <= r_e;
        rr_b <= r_b;
    end
end

always @(posedge clk) begin
    if (reset) begin
        rb <= 0;
    end else begin
        r_qx <= c;
        rb <= rr_b;
        e2 <= rr_e;
    end
end

assign q = e2 & r_qx;

endmodule

module top_module ( 
    input clk, 
    input reset, // Synchronous active-high reset 
    input [7:0] d, // 8-bit input for the flip-flop module 
    input a, // First input of the majority gate module 
    input b, // Second input of the majority gate module 
    input c, // Third input of the majority gate module 
    input select, // Select input to choose between flip-flop and majority gate 
    output reg [7:0] q // 8-bit output from the active module 
); 

// Instantiate the flip-flop module 
reg [7:0] ff_q; 
flip_flop_module ff_inst ( 
    .clk(clk), 
    .reset(reset), 
    .d(d), 
    .q(ff_q) 
); 

// Instantiate the majority gate module 
reg [2:0] mg_out; 
majority_gate_module mg_inst ( 
    .clk(clk), 
    .reset(reset), 
    .a(a), 
    .b(b), 
    .c(c), 
    .out(mg_out) 
); 

// Control logic to select between flip-flop and majority gate 
always @ (posedge clk) begin 
    if (reset) begin 
        q <= 8'b0; 
    end else begin 
        if (select) begin 
            q <= {mg_out, mg_out, mg_out, mg_out, mg_out, mg_out, mg_out, mg_out}; 
        end else begin 
            q <= ff_q; 
        end 
    end 
end 

// Functional module to perform bitwise AND on the outputs of both modules 
always @ (posedge clk) begin 
    if (reset) begin 
        q <= 8'b0; 
    end else begin 
        q <= ff_q & {mg_out, mg_out, mg_out, mg_out, mg_out, mg_out, mg_out, mg_out}; 
    end 
end 

endmodule 

