// 3-input majority gate module with synchronous reset 
module majority_gate_module ( 
    input clk, 
    input reset, // Synchronous active-high reset 
    input a, // First input 
    input b, // Second input 
    input c, // Third input 
    output reg [2:0] out // 3-bit output 
); 

always @ (posedge clk) begin 
    if (reset) begin 
        out <= 3'b0; 
    end else begin 
        if (a & b | a & c | b & c) begin 
            out <= 3'b111; 
        end else begin 
            out <= 3'b000; 
        end 
    end 
end 

endmodule

module data_inverter (
  input [15:0] data_in,
  input enable,
  output reg [15:0] data_out,
  output reg valid
);

  always @ (posedge enable) begin
    if (enable) begin
      data_out[15:12] = ~data_in[15:12];
      data_out[11:0] = data_in[11:0];
      valid = 1;
    end
  end

  always @ (negedge enable) begin
    valid = 0;
  end

endmodule

module division_module (
    input clk,
    input rst_n,
    input [7:0] A,
    input [7:0] B,
    input ready,
    output reg [7:0] quotient,
    output reg [7:0] remainder,
    output reg valid
);

reg [7:0] dividend_reg;
reg [7:0] divisor_reg;
reg [7:0] quotient_reg;
reg [7:0] remainder_reg;
reg [2:0] state;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        dividend_reg <= 8'b0;
        divisor_reg <= 8'b0;
        quotient_reg <= 8'b0;
        remainder_reg <= 8'b0;
        state <= 3'b000;
        valid <= 1'b0;
    end else begin
        case (state)
            3'b000: begin
                dividend_reg <= A;
                divisor_reg <= B;
                state <= 3'b001;
            end
            3'b001: begin
                if (divisor_reg == 8'b0) begin
                    quotient_reg <= 8'b0;
                    remainder_reg <= 8'b0;
                    state <= 3'b000;
                    valid <= 1'b1;
                end else begin
                    quotient_reg <= dividend_reg / divisor_reg;
                    remainder_reg <= dividend_reg % divisor_reg;
                    state <= 3'b010;
                end
            end
            3'b010: begin
                if (ready) begin
                    state <= 3'b011;
                end
            end
            3'b011: begin
                quotient <= quotient_reg;
                remainder <= remainder_reg;
                valid <= 1'b1;
                state <= 3'b000;
            end
        endcase
    end
end

endmodule

module binary_counter(clk, rstn, en, leds);
  parameter width=4;

  input clk;
  input rstn;
  input en;
  output reg [width-1:0] leds;

  always @(posedge clk, negedge rstn) begin
    if (~rstn)
      leds <= {width{1'b0}};
    else if (en)
      leds <= leds + 1'b1;
  end
endmodule

module binary_divider (
    input [7:0] A,
    input [7:0] B,
    output reg [7:0] Y
);

reg [7:0] reg_Y;
reg [7:0] reg_A;
reg [7:0] reg_B;
reg [2:0] state;

always @(*) begin
    case(state)
        0: begin // initialize
            reg_Y <= 8'b0;
            reg_A <= A;
            reg_B <= B;
            state <= 1;
        end
        1: begin // shift A left by 1 bit
            reg_A <= {reg_A[6:0], 1'b0};
            state <= 2;
        end
        2: begin // compare A and B
            if(reg_A >= reg_B) begin
                reg_A <= reg_A - reg_B;
                reg_Y[0] <= 1'b1;
            end
            reg_Y <= {reg_Y[6:0], 1'b0};
            state <= 3;
        end
        3: begin // shift register left by 1 bit
            reg_Y <= {reg_Y[6:0], 1'b0};
            state <= 4;
        end
        4: begin // repeat for all bits of A
            if(reg_A != 8'b0) begin
                state <= 1;
            end else begin
                state <= 5;
            end
        end
        5: begin // output quotient
            Y <= reg_Y;
            state <= 0;
        end
    endcase
end

endmodule

module stratixiv_bias_logic (
    input clk,
    input shiftnld,
    input captnupdt,
    output mainclk,
    output updateclk,
    output capture,
    output update
);

reg mainclk_tmp;
reg updateclk_tmp;
reg capture_tmp;
reg update_tmp;

always @(*) begin
    case ({captnupdt, shiftnld})
        2'b10, 2'b11 :
            begin
                mainclk_tmp = 1'b0;
                updateclk_tmp = clk;
                capture_tmp = 1'b1;
                update_tmp = 1'b0;
            end
        2'b01 :
            begin
                mainclk_tmp = 1'b0;
                updateclk_tmp = clk;
                capture_tmp = 1'b0;
                update_tmp = 1'b0;
            end
        2'b00 :
            begin
                mainclk_tmp = clk;
                updateclk_tmp = 1'b0;
                capture_tmp = 1'b0;
                update_tmp = 1'b1;
            end
        default :
            begin
                mainclk_tmp = 1'b0;
                updateclk_tmp = 1'b0;
                capture_tmp = 1'b0;
                update_tmp = 1'b0;
            end
    endcase
end

assign mainclk = mainclk_tmp;
assign updateclk = updateclk_tmp;
assign capture = capture_tmp;
assign update = update_tmp;

endmodule

module adder_subtractor(A, B, S, Y);
  input [3:0] A, B;
  input S;
  output [3:0] Y;

  wire C1, C2;
  wire [3:0] SUM;

  // Implementing the full-adder subcircuit
  // with basic gates
  xor x1(SUM[0], A[0], B[0]);
  xor x2(SUM[1], A[1], B[1]);
  xor x3(SUM[2], A[2], B[2]);
  xor x4(SUM[3], A[3], B[3]);

  and a1(C1, A[0], B[0]);
  and a2(C2, A[1], B[1]);

  xor x5(SUM[1], SUM[1], C1);
  xor x6(SUM[2], SUM[2], C2);

  and a3(C1, SUM[0], S);
  and a4(C2, SUM[1], S);

  xor x7(Y[0], SUM[0], S);
  xor x8(Y[1], SUM[1], C1);
  xor x9(Y[2], SUM[2], C2);
  xor x10(Y[3], SUM[3], C1);

endmodule

module counter (
  input clk,
  input rst,
  input [31:0] max_count,
  output reg [31:0] count
);

  always @(posedge clk) begin
    if (rst) begin
      count <= 0;
    end else if (count >= max_count) begin
      count <= max_count;
    end else begin
      count <= count + 1;
    end
  end

endmodule

module shift_accumulator_system (
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,
    input               select      , // Select input to choose between accu and top_module
    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out
);

    // Shift register to accumulate four input data
    reg [7:0] shift_reg [3:0];
    reg [9:0] accum;

    // Instantiate accu and top_module
    accu accu_inst (
        .clk(clk),
        .rst_n(rst_n),
        .data_in(data_in),
        .valid_a(valid_a),
        .ready_a(),
        .valid_b(),
        .ready_b(),
        .data_out(accum)
    );

    top_module top_inst (
        .clk(clk),
        .rst_n(rst_n),
        .data_in(data_in),
        .valid_a(valid_a),
        .ready_a(),
        .valid_b(),
        .ready_b(),
        .data_out(shift_reg[0])
    );

    // Shift register logic
    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            shift_reg <= 0;
            accum <= 0;
        end else begin
            shift_reg[0] <= top_inst.data_out;
            shift_reg[1] <= shift_reg[0];
            shift_reg[2] <= shift_reg[1];
            shift_reg[3] <= shift_reg[2];

            if (valid_a && ready_b) begin
                if (select) begin
                    accum <= accum + shift_reg[3];
                end else begin
                    accum <= accum + accu_inst.data_out;
                end
            end
        end
    end

    // Valid-ready handshake logic
    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            valid_b <= 0;
            data_out <= 0;
        end else begin
            if (valid_a && ready_b && (select || accu_inst.valid_b)) begin
                valid_b <= 1;
                data_out <= accum + accu_inst.data_out;
            end else begin
                valid_b <= 0;
                data_out <= 0;
            end
        end
    end

    // Ready signal logic
    assign ready_a = ~valid_b || (valid_b && ready_b);

endmodule

module sm_clk_divider
#(
    parameter shift  = 16,
              bypass = 0
)
(
