module top_module ( 
    input a, b, cin,
    output cout, sum,
    input [2:0] sel,
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output [3:0] out
);

    full_adder fa_inst (
        .a(a),
        .b(b),
        .cin(cin),
        .sum(sum),
        .cout(cout)
    );

    mux_6to1 mux_inst (
        .sel(sel),
        .data0(data0),
        .data1(data1),
        .data2(data2),
        .data3(data3),
        .data4(data4),
        .data5(data5),
        .out(mux_out)
    );

    final_module final_inst (
        .mux_out(mux_out),
        .adder_out({cout, sum}),
        .out(out)
    );

    wire [3:0] mux_out;

endmodule

module clock_divider(
    input clk,
    input RST,
    output dclk
);

    // Define the maximum counter value
    parameter [15:0] CNTENDVAL = 16'b1011011100110101;

    // Define the counter register
    reg [15:0] cntval;

    // Define the flip-flop to toggle the output clock
    reg dclk_ff;

    // Increment the counter on the rising edge of the input clock
    always @(posedge clk) begin
        if (RST) begin
            // Reset the counter to 0 if the reset signal is high
            cntval <= 0;
        end else begin
            // Increment the counter by 1
            cntval <= cntval + 1;
        end
    end

    // Toggle the output clock when the counter reaches its maximum value
    always @(posedge clk) begin
        if (cntval == CNTENDVAL) begin
            dclk_ff <= ~dclk_ff;
        end
    end

    // Assign the output clock to the flip-flop output
    assign dclk = dclk_ff;

endmodule

module k580ww55(
    input clk, reset, we_n,
    input [1:0] addr,
    input [7:0] idata,
    output reg [7:0] odata,
    output reg [7:0] opa,
    output reg [7:0] opb,
    output reg [7:0] opc
);

always @(posedge clk or posedge reset) begin
    if (reset) begin
        odata <= 8'h00;
        opa <= 8'hFF;
        opb <= 8'hFF;
        opc <= 8'hFF;
    end else begin
        case (addr)
            2'b00: odata <= opa;
            2'b01: odata <= opb;
            2'b10: odata <= opc;
            2'b11: odata <= 8'h00;
        endcase

        if (~we_n) begin
            case (addr)
                2'b00: opa <= idata;
                2'b01: opb <= idata;
                2'b10: opc <= idata;
                2'b11: begin
                    opc[idata[3:1]] <= idata[0];
                end
            endcase
        end
    end
end

endmodule

module addsub (
    input [15:0] A,
    input [15:0] B,
    input mode,
    output reg negative
);

reg [15:0] sum_reg;
reg [15:0] diff_reg;
reg [1:0] stage;
wire [15:0] A_reg;
wire [15:0] B_reg;
wire mode_reg;

assign A_reg = (stage == 0) ? A : sum_reg;
assign B_reg = (stage == 0) ? B : diff_reg;
assign mode_reg = (stage == 0) ? mode : 1'b1;

always @(*) begin
    case(stage)
        0: begin
            sum_reg = A + B;
            diff_reg = A - B;
        end
        1: begin
            sum_reg = A_reg + B_reg;
            diff_reg = A_reg - B_reg;
        end
        2: begin
            sum_reg = A_reg + B_reg;
            diff_reg = A_reg - B_reg;
        end
    endcase
end

always @(posedge mode_reg) begin
    if (stage == 2) begin
        negative <= (diff_reg[15] == 1);
        stage <= 0;
    end else begin
        stage <= stage + 1;
    end
end

endmodule

module memory_module (
    address,
    byteena,
    clock,
    data,
    wren,
    q
);

    parameter WORD_SIZE = 16;
    parameter WORDS = 76800;
    parameter BYTE_SIZE = 8;
    parameter BYTES = WORD_SIZE / BYTE_SIZE;

    input [16:0] address;
    input [1:0] byteena;
    input clock;
    input [WORD_SIZE-1:0] data;
    input wren;
    output reg [WORD_SIZE-1:0] q;

    reg [WORD_SIZE-1:0] mem [0:WORDS-1];

    always @(posedge clock) begin
        if (wren) begin
            case (byteena)
                2'b00: mem[address][7:0] <= data[7:0];
                2'b01: mem[address][15:8] <= data[7:0];
                2'b10: mem[address][23:16] <= data[7:0];
                2'b11: mem[address][31:24] <= data[7:0];
            endcase
        end
        case (byteena)
            2'b00: q <= mem[address][7:0];
            2'b01: q <= mem[address][15:8];
            2'b10: q <= mem[address][23:16];
            2'b11: q <= mem[address][31:24];
        endcase
    end

endmodule

module pipelined_adder (
    input clk,
    input rst,
    input [7:0] a,
    input [7:0] b,
    output [7:0] s,
    output overflow
);

reg [7:0] a_reg, b_reg, s_reg;
reg carry_in_reg, carry_out_reg;
wire [7:0] sum_wire;
wire carry_out_wire;

assign sum_wire = a_reg + b_reg + carry_in_reg;
assign carry_out_wire = (a_reg[6] & b_reg[6]) | (a_reg[6] & carry_in_reg) | (b_reg[6] & carry_in_reg);
assign overflow = ~(a_reg[6] ^ b_reg[6]) & (a_reg[6] ^ s_reg[6]);

always @(posedge clk) begin
    if (rst) begin
        a_reg <= 8'b0;
        b_reg <= 8'b0;
        s_reg <= 8'b0;
        carry_in_reg <= 1'b0;
        carry_out_reg <= 1'b0;
    end else begin
        a_reg <= a;
        b_reg <= b;
        s_reg <= sum_wire;
        carry_in_reg <= carry_out_wire;
        carry_out_reg <= carry_out_wire;
    end
end

