module top_module(
    input clk,
    input reset,
    input [31:0] a,
    input [31:0] b,
    input sub,
    input c,
    output [31:0] out
);

    wire [31:0] add_out;
    wire [31:0] and_out;
    wire [31:0] final_out;

    // Instantiate 32-bit adder module
    adder_32 adder_inst(
        .a(a),
        .b(b),
        .sub(sub),
        .out(add_out)
    );

    // Instantiate AND gate module
    and_gate and_inst(
        .a(add_out),
        .b(c),
        .sub(sub),
        .out(and_out)
    );

    // Instantiate final output module
    final_output final_inst(
        .add_out(add_out),
        .and_out(and_out),
        .sub(sub),
        .out(final_out)
    );

    // D flip-flop to store output of AND gate
    reg [31:0] dff_out;
    always @(posedge clk, negedge reset) begin
        if (!reset) begin
            dff_out <= 0;
        end else begin
            if (sub) begin
                dff_out <= and_out;
            end else begin
                dff_out <= add_out;
            end
        end
    end

    assign out = final_out;

endmodule

// 32-bit adder module
module adder_32(
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] out
);

    assign out = sub ? a - b : a + b;

endmodule

// AND gate module
module and_gate(
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] out
);

    assign out = sub ? a & b : 0;

endmodule

// Final output module
module final_output(
    input [31:0] add_out,
    input [31:0] and_out,
    input sub,
    output [31:0] out
);

    assign out = sub ? and_out : add_out;

endmodule

module Clock_Divider (
    input clock,
    input reset,
    output reg clock_out
);

reg [1:0] count;

always @(posedge clock or posedge reset) begin
    if (reset) begin
        count <= 2'b00;
        clock_out <= 1'b0;
    end
    else begin
        count <= count + 1;
        if (count == 2'b01) begin
            clock_out <= ~clock_out;
        end
    end
end

endmodule

