module trigterm_range_byte (
  input  wire  [7:0] sti_data,
  input  wire        clk,
  input  wire        wrenb,
  input  wire        din,
  output wire        dout,
  input  wire        cin,
  output wire        cout
);

  // Calculate the input value in radians
  parameter pi = 3.14159265358979323846;
  wire [7:0] rad_val = sti_data * (2*pi/256);

  // Calculate the sine of the input value
  wire [7:0] sin_val;
  assign sin_val = $sin(rad_val);

  // Scale the sine value to fit within the range of a byte-sized output
  wire [7:0] scaled_val;
  assign scaled_val = sin_val * 127 + 128;

  // Round the scaled sine value to the nearest integer
  wire [7:0] rounded_val;
  assign rounded_val = scaled_val + 1'b1;

  // Create the chain of sub-modules
  wire [6:0] chain, carry;
  trigterm_range_bit bit0 (sti_data[0], clk, wrenb,      din, chain[0],      cin, carry[0]);
  trigterm_range_bit bit1 (sti_data[1], clk, wrenb, chain[0], chain[1], carry[0], carry[1]);
  trigterm_range_bit bit2 (sti_data[2], clk, wrenb, chain[1], chain[2], carry[1], carry[2]);
  trigterm_range_bit bit3 (sti_data[3], clk, wrenb, chain[2], chain[3], carry[2], carry[3]);
  trigterm_range_bit bit4 (sti_data[4], clk, wrenb, chain[3], chain[4], carry[3], carry[4]);
  trigterm_range_bit bit5 (sti_data[5], clk, wrenb, chain[4], chain[5], carry[4], carry[5]);
  trigterm_range_bit bit6 (sti_data[6], clk, wrenb, chain[5], chain[6], carry[5], carry[6]);
  trigterm_range_bit bit7 (sti_data[7], clk, wrenb, chain[6],     dout, carry[6],     cout);

  // Output the rounded value as the final result
  assign dout = rounded_val;

endmodule

// Sub-module to calculate a single bit of the trigonometric calculation
module trigterm_range_bit (
  input  wire        sti_data,
  input  wire        clk,
  input  wire        wrenb,
  input  wire        din,
  output wire        dout,
  input  wire        cin,
  output wire        cout
);

  // Calculate the intermediate result for this bit of the calculation
  reg [1:0] term;
  always @(posedge clk) begin
    if (wrenb) begin
      term <= {term[0], sti_data};
    end
  end
  assign dout = term[1] ^ din ^ cin;

  // Calculate the carry signal for this bit of the calculation
  reg carry;
  always @(posedge clk) begin
    if (wrenb) begin
      carry <= term[0] & (din | cin);
    end
  end
  assign cout = carry;

endmodule

module comparator (
  input [3:0] A,
  input [3:0] B,
  output reg out_greater,
  output reg out_equal,
  output reg out_less
);

  always @ (A, B) begin
    if (A > B) begin
      out_greater = 1;
      out_equal = 0;
      out_less = 0;
    end else if (A == B) begin
      out_greater = 0;
      out_equal = 1;
      out_less = 0;
    end else begin
      out_greater = 0;
      out_equal = 0;
      out_less = 1;
    end
  end

endmodule

