module pipelined_ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    input CIN,
    output reg [3:0] S,
    output reg COUT
);

reg [3:0] sum1;
reg [3:0] sum2;

assign S = sum2;

always @(*) begin
    sum1[0] = A[0] ^ B[0] ^ CIN;
    sum1[1] = A[1] ^ B[1] ^ sum1[0];
    sum1[2] = A[2] ^ B[2] ^ sum1[1];
    sum1[3] = A[3] ^ B[3] ^ sum1[2];
end

always @(posedge clk) begin
    sum2[0] <= sum1[0];
    sum2[1] <= sum1[1];
    sum2[2] <= sum1[2];
    sum2[3] <= sum1[3];
    COUT <= (sum1[3] & (sum1[2] | sum1[1] | sum1[0])) | (sum1[2] & (sum1[1] | sum1[0])) | (sum1[1] & sum1[0]);
end

endmodule

module clocking_module (
  input         clk_in1,
  input         reset,
  output        aclk,
  output        uart,
  output        locked
);

  // Input buffering
  //------------------------------------
  wire clk_in1_buf;
  IBUF clkin1_ibufg (.O (clk_in1_buf), .I (clk_in1));

  // Clocking PRIMITIVE
  //------------------------------------

  // Instantiation of the MMCM PRIMITIVE
  //    * Unused inputs are tied off
  //    * Unused outputs are labeled unused

  wire        aclk_buf;
  wire        uart_buf;
  wire        clkfbout_buf;
  wire        locked_int;
  wire        reset_high;

  MMCME2_ADV #(
    .BANDWIDTH            ("HIGH"),
    .CLKOUT4_CASCADE      ("FALSE"),
    .COMPENSATION         ("ZHOLD"),
    .STARTUP_WAIT         ("FALSE"),
    .DIVCLK_DIVIDE        (1),
    .CLKFBOUT_MULT_F      (63.000),
    .CLKFBOUT_PHASE       (0.000),
    .CLKFBOUT_USE_FINE_PS ("FALSE"),
    .CLKOUT0_DIVIDE_F     (10.500),
    .CLKOUT0_PHASE        (0.000),
    .CLKOUT0_DUTY_CYCLE   (0.500),
    .CLKOUT0_USE_FINE_PS  ("FALSE"),
    .CLKOUT1_DIVIDE       (63),
    .CLKOUT1_PHASE        (0.000),
    .CLKOUT1_DUTY_CYCLE   (0.500),
    .CLKOUT1_USE_FINE_PS  ("FALSE"),
    .CLKIN1_PERIOD        (83.333)
  ) mmcm_adv_inst (
    // Output clocks
    .CLKFBOUT            (clkfbout_buf),
    .CLKFBOUTB           (),
    .CLKOUT0             (aclk_buf),
    .CLKOUT0B            (),
    .CLKOUT1             (uart_buf),
    .CLKOUT1B            (),
    .CLKOUT2             (),
    .CLKOUT2B            (),
    .CLKOUT3             (),
    .CLKOUT3B            (),
    .CLKOUT4             (),
    .CLKOUT5             (),
    .CLKOUT6             (),
    // Input clock control
    .CLKFBIN             (clkfbout_buf),
    .CLKIN1              (clk_in1_buf),
    .CLKIN2              (1'b0),
    // Tied to always select the primary input clock
    .CLKINSEL            (1'b1),
    // Ports for dynamic reconfiguration
    .DADDR               (7'h0),
    .DCLK                (1'b0),
    .DEN                 (1'b0),
    .DI                  (16'h0),
    .DO                  (),
    .DRDY                (),
    .DWE                 (1'b0),
    // Ports for dynamic phase shift
    .PSCLK               (1'b0),
    .PSEN                (1'b0),
    .PSINCDEC            (1'b0),
    .PSDONE              (),
    // Other control and status signals
    .LOCKED              (locked_int),
    .CLKINSTOPPED        (),
    .CLKFBSTOPPED        (),
    .PWRDWN              (1'b0),
    .RST                 (reset_high)
  );
  assign reset_high = reset;

  // Output buffering
  //-----------------------------------

  BUFG aclk_bufg (.O (aclk), .I (aclk_buf));
  BUFG uart_bufg (.O (uart), .I (uart_buf));

  // Locked signal
  //-----------------------------------

  reg [1:0] locked_reg;
  always @(posedge clk_in1_buf or posedge reset_high) begin
    if (reset_high) begin
      locked_reg <= 2'b00;
    end else begin
      locked_reg <= {locked_reg[0], locked_int};
    end
  end
  assign locked = (locked_reg == 2'b11);

endmodule

module edge_enhance(
  input clk,
  input enable_feature,
  input in_blank,
  input in_hsync,
  input in_vsync,
  input [7:0] in_red,
  input [7:0] in_green,
  input [7:0] in_blue,
  output out_blank,
  output out_hsync,
  output out_vsync,
  output [7:0] out_red,
  output [7:0] out_green,
  output [7:0] out_blue
);

  reg [7:0] _0_;
  reg [7:0] _1_;
  wire [7:0] delayed_red;
  wire [7:0] delayed_green;
  wire [7:0] delayed_blue;

  line_delay i_line_delay (
    .clk(clk),
    .in_blank(in_blank),
    .in_blue(in_blue),
    .in_green(in_green),
    .in_hsync(in_hsync),
    .in_red(in_red),
    .in_vsync(in_vsync),
    .out_blank(out_blank),
    .out_blue(delayed_blue),
    .out_green(delayed_green),
    .out_hsync(out_hsync),
    .out_red(delayed_red),
    .out_vsync(out_vsync)
  );

  always @(posedge clk) begin
    _0_ <= delayed_green;
    _1_ <= delayed_blue;
  end

  always @(*) begin
    if(enable_feature) begin
      out_blank = in_blank;
      out_hsync = in_hsync;
      out_vsync = in_vsync;
      out_red = in_red;
      out_green = _0_ + in_green - delayed_green;
      out_blue = _1_ + in_blue - delayed_blue;
    end else begin
      out_blank = in_blank;
      out_hsync = in_hsync;
      out_vsync = in_vsync;
      out_red = in_red;
      out_green = in_green;
      out_blue = in_blue;
    end
  end

endmodule

module line_delay(
  input clk,
  input in_blank,
  input [7:0] in_blue,
  input [7:0] in_green,
  input in_hsync,
  input [7:0] in_red,
  input in_vsync,
