  output [7:0] out_blue,
  output [7:0] out_green,
  output out_hsync,
  output [7:0] out_red,
  output out_vsync
);

  reg [7:0] delay_buffer_red[0:2];
  reg [7:0] delay_buffer_green[0:2];
  reg [7:0] delay_buffer_blue[0:2];
  reg [7:0] delay_buffer_blank[0:2];
  reg delay_buffer_hsync[0:2];
  reg delay_buffer_vsync[0:2];

  always @(posedge clk) begin
    delay_buffer_red[0] <= in_red;
    delay_buffer_green[0] <= in_green;
    delay_buffer_blue[0] <= in_blue;
    delay_buffer_blank[0] <= in_blank;
    delay_buffer_hsync[0] <= in_hsync;
    delay_buffer_vsync[0] <= in_vsync;

    delay_buffer_red[1] <= delay_buffer_red[0];
    delay_buffer_green[1] <= delay_buffer_green[0];
    delay_buffer_blue[1] <= delay_buffer_blue[0];
    delay_buffer_blank[1] <= delay_buffer_blank[0];
    delay_buffer_hsync[1] <= delay_buffer_hsync[0];
    delay_buffer_vsync[1] <= delay_buffer_vsync[0];

    delay_buffer_red[2] <= delay_buffer_red[1];
    delay_buffer_green[2] <= delay_buffer_green[1];
    delay_buffer_blue[2] <= delay_buffer_blue[1];
    delay_buffer_blank[2] <= delay_buffer_blank[1];
    delay_buffer_hsync[2] <= delay_buffer_hsync[1];
    delay_buffer_vsync[2] <= delay_buffer_vsync[1];
  end

  assign out_red = delay_buffer_red[2];
  assign out_green = delay_buffer_green[2];
  assign out_blue = delay_buffer_blue[2];
  assign out_blank = delay_buffer_blank[2];
  assign out_hsync = delay_buffer_hsync[2];
  assign out_vsync = delay_buffer_vsync[2];

endmodule

