module fsm_sequence_detection (
  input clk,
  input reset,
  input data,
  output reg match
);

  // Define the states
  parameter S0 = 2'b00;
  parameter S1 = 2'b01;
  parameter S2 = 2'b10;

  // Define the state register and next state logic
  reg [1:0] state, next_state;
  always @ (posedge clk, posedge reset) begin
    if (reset) begin
      state <= S0;
    end else begin
      state <= next_state;
    end
  end

  // Define the output logic
  always @ (state, data) begin
    if (state == S2 && data == 1'b1) begin
      match <= 1'b1;
    end else begin
      match <= 1'b0;
    end
  end

  // Define the next state logic
  always @ (state, data) begin
    case (state)
      S0: begin
        if (data == 1'b1) begin
          next_state = S1;
        end else begin
          next_state = S0;
        end
      end
      S1: begin
        if (data == 1'b0) begin
          next_state = S0;
        end else if (data == 1'b1) begin
          next_state = S2;
        end else begin
          next_state = S1;
        end
      end
      S2: begin
        next_state = S0;
      end
      default: next_state = S0;
    endcase
  end

endmodule

module clk_delay_buffer (
