reg [7:0] last_eight_bits;

always @(posedge clk) begin
    if (data_in[31:24] == 8'hFF) begin
        first_eight_bits <= 8'hFF;
        last_eight_bits <= 8'h00;
    end else if (data_in[7:0] == 8'h00) begin
        first_eight_bits <= 8'h00;
        last_eight_bits <= 8'h0F;
    end else begin
        first_eight_bits <= data_in[31:24];
        last_eight_bits <= data_in[7:0];
    end
end

assign data_out = {first_eight_bits, last_eight_bits};

endmodule

module dc_diff_gen(
    input clk,
    input ena,
    input rst,
    input dstrb,
    input signed [11:0] din,
    output signed [11:0] dout,
    output douten
);

    reg signed [11:0] prev_dc;
    reg signed [11:0] cur_dc;
    reg signed [11:0] diff;
    reg douten;

    always @(posedge clk) begin
        if (rst) begin
            prev_dc <= 0;
            cur_dc <= 0;
            diff <= 0;
            douten <= 0;
        end else if (ena) begin
            // Update current DC component
            if (dstrb) begin
                cur_dc <= din;
            end

            // Calculate differential signal
            diff <= cur_dc - prev_dc;
            prev_dc <= cur_dc;

            // Output differential signal
            if (dstrb) begin
                dout <= diff;
                douten <= 1;
            end else begin
                douten <= 0;
            end
        end
    end

endmodule

