// /```\___/

reg [31:0] run; // free running counter
reg [31:0] mem [0:255]; // pulse sequence array
reg [31:0] limit;
reg [31:0] timer;
reg [7:0] pointer; // pointer
reg start; // start condition
reg prestart; // pre-history for the start condition

// Initialize mem array with pulse sequence
initial begin
    $readmemh("ram.txt", mem);
end

// Update limit value based on pointer
always @ (*) limit = mem[pointer];

// Free running counter
always @ (posedge clk) run <= run + 1;

// Detect start condition
always @ (posedge clk) prestart <= run[23];

always @ (*) start = ~prestart & run[23]; // __/``` posedge detector

// Generate pulse sequence
always @ (posedge clk)
    if (start) begin
        pointer <= 0;
        timer <= 0; // initial load
    end else begin
        if (timer == 0) begin
            timer <= limit;
            pointer <= pointer + 1;
        end else begin
            timer = timer - 1;
        end
    end

// Output pulse sequence on drv
assign drv = pointer[0];

endmodule

module nor3 (
    input A,
    input B,
    input C,
    input VPB,
    input VPWR,
    input VGND,
    input VNB,
    output Y
);

    // Create three inverters
    not (invA, A);
    not (invB, B);
    not (invC, C);

    // Create two NOR gates
    nor2 (norAB, invA, invB);
    nor2 (norABC, norAB, invC);

    // Assign output to norABC
    assign Y = norABC;

endmodule

