module top_module (
    input [255:0] in, // 256 inputs packed into 8 32-bit input vectors
    input [7:0] sel, // Selection input for the 256-to-1 multiplexer
    output [7:0] out_hi, // Upper 8 bits of the selected input after barrel shifting
    output [7:0] out_lo, // Lower 8 bits of the selected input
    output [7:0] result // Result of the bitwise OR operation between out_hi and out_lo
);

  wire [7:0] mux_out;
  wire [7:0] shift_out;

  // 256-to-1 multiplexer
  mux_256to1 mux (
    .in(in),
    .sel(sel),
    .out(mux_out)
  );

  // Barrel shifter
  barrel_shifter shifter (
    .in(mux_out),
    .out_hi(out_hi),
    .out_lo(out_lo)
  );

  // Bitwise OR operation
  assign result = out_hi | out_lo;

endmodule

// 256-to-1 multiplexer module
module mux_256to1 (
    input [255:0] in, // 256 inputs packed into 8 32-bit input vectors
    input [7:0] sel, // Selection input for the multiplexer
    output [7:0] out // Output of the multiplexer
);

  assign out = in[sel];

endmodule

// Barrel shifter module
module barrel_shifter (
    input [7:0] in, // Input to be shifted
    output [7:0] out_hi, // Upper 8 bits of the shifted input
    output [7:0] out_lo // Lower 8 bits of the shifted input
);

  assign out_hi = in >> 8;
  assign out_lo = in & 8'hFF;

endmodule

