module top_module (
    input [7:0] a,
    input [7:0] b,
    input wire [7:0] in_hi,
    input wire [7:0] in_lo,
    output [7:0] s,
    output wire overflow,
    output wire [15:0] out
);

    binary_adder adder(.a(a), .b(b), .s(s), .overflow(overflow));
    half_word_concatenation concat(.in_hi(in_hi), .in_lo(in_lo), .out(out));
    max_value max(.a(s), .b(out[7:0]), .in(out), .out(s));

endmodule

