module synchronous_double_port_ram
  (
   // Generic synchronous double-port RAM interface
   clk_a, ce_a, addr_a, do_a,
   clk_b, ce_b, we_b, addr_b, di_b
   );

   //
   // Default address and data buses width
   //
   parameter aw = 5;
   parameter dw = 32;

   //
   // Generic synchronous double-port RAM interface
   //
   input clk_a; // Clock for port A
   input ce_a; // Chip enable for port A
   input [aw-1:0] addr_a; // Address bus inputs for port A
   output [dw-1:0] do_a; // Output data bus for port A
   input clk_b; // Clock for port B
   input ce_b; // Chip enable for port B
   input we_b; // Write enable for port B
   input [aw-1:0] addr_b; // Address bus inputs for port B
   input [dw-1:0] di_b; // Input data bus for port B

   //
   // Internal wires and registers
   //
   reg [dw-1:0] mem [(1<<aw)-1:0] /*synthesis syn_ramstyle = "no_rw_check"*/; // RAM content
   reg [aw-1:0] addr_a_reg; // RAM address registered
   integer k;

   //
   // Data output drivers
   //
   assign do_a = mem[addr_a_reg];

   //
   // RAM read
   //
   always @(posedge clk_a)
     if (ce_a)
       addr_a_reg <=  addr_a;

   //
   // RAM write
   //
   always @(posedge clk_b)
     if (ce_b & we_b)
       mem[addr_b] <=  di_b;

   //
   // RAM initialization
   //
   initial begin 
      for(k = 0; k < (1 << aw); k = k + 1)
      begin
         mem[k] = 0;
      end
   end

endmodule

module jtag_uart_log_module (
  // inputs:
  clk,
  data,
  strobe,
  valid
);

  input clk;
  input [7:0] data;
  input strobe;
  input valid;

  // Register to hold the text handle for the output file
  reg [31:0] text_handle;

  // Register to hold the last data value
  reg [7:0] last_data;

  // Register to hold the number of consecutive valid data
  reg [7:0] count;

  // Register to hold the ASCII value of the last data
  reg [7:0] last_ascii;

  // Register to hold the ASCII value of the current data
  reg [7:0] current_ascii;

  // Open the output file when the module is instantiated
  initial begin
    text_handle = $fopen("jtag_uart_output_stream.dat", "w");
  end

  // Always block to write the data to the output file and output to the screen
  always @(posedge clk) begin
    if (valid && strobe) begin
      // Write the binary data to the output file
      $fwrite(text_handle, "%b\n", data);

      // Convert the binary data to ASCII and output to the screen
      if (data == 8'h0a) begin
        $write("\n");
      end else if (data == 8'h0d) begin
        // Do nothing for carriage return
      end else begin
        current_ascii = (data == 8'h0d) ? 8'h20 : data;
        if (current_ascii != last_ascii) begin
          if (count > 1) begin
            $write("(%d)%c", count, last_ascii);
          end else begin
            $write("%c", last_ascii);
          end
          count = 0;
        end
        last_ascii = current_ascii;
        count = count + 1;
      end

      // Flush the data to the output file
      $fflush(text_handle);
    end
  end

endmodule

module adder_subtractor(A, B, C, S);
  input [3:0] A, B;
  input C;
  output [3:0] S;

  reg [3:0] TwosComplementB;

  always @ (A or B or C) begin
    if (C == 0) begin // Add
      S = A + B;
    end else begin // Subtract
      TwosComplementB = ~B + 1;
      S = A + TwosComplementB;
    end
  end

endmodule

