module splitter_stage2(
    input wire [7:0] in_lo,
    input wire [7:0] in_hi,
    output wire [7:0] out_lo,
    output wire [7:0] out_hi
);

    reg [7:0] lo_byte_reg;
    reg [7:0] hi_byte_reg;

    always @(posedge clk) begin
        lo_byte_reg <= in_lo;
        hi_byte_reg <= in_hi;
    end

    assign out_lo = lo_byte_reg;
    assign out_hi = hi_byte_reg;

endmodule

module up_down_counter (
    input clk,
    input async_reset,
    input [1:0] enable,
    output reg [1:0] count
);

reg [1:0] count_reg1, count_reg2;

always @(posedge clk) begin
    if (async_reset) begin
        count_reg1 <= 2'b00;
        count_reg2 <= 2'b00;
    end
    else begin
        count_reg1 <= count_reg2;
        count_reg2 <= count;
    end
end

always @(*) begin
    case (enable)
        2'b00: count = count_reg1;
        2'b01: count = count_reg1 + 2'b01;
        2'b10: count = count_reg1 - 2'b01;
        default: count = count_reg1;
    endcase
end

endmodule

module adder_4bit(
    input [3:0] A,
    input [3:0] B,
    input C,
    output reg [3:0] S,
    output reg OF,
    output reg CF
);

    wire [3:0] A_inv;
    wire [3:0] B_inv;
    wire [3:0] B_neg;
    wire [4:0] S_temp;
    wire [4:0] C_temp;

    // Calculate two's complement of B
    assign B_inv = ~B;
    assign B_neg = B_inv + 1;

    // Calculate A + B or A + B_neg based on C
    assign S_temp = (C == 1'b0) ? (A + B) : (A + B_neg);

    // Calculate overflow flag
    assign OF = (S_temp[4] == 1);

    // Calculate carry flag
    assign CF = (S_temp[3] & (C == 1'b0)) | (S_temp[4] & (C == 1'b1));

    // Assign S
    always @(posedge clk) begin
        S <= S_temp[3:0];
    end

endmodule

module shifter_32b #(
	parameter LENGTH = 1
) (
	input clk,
	input [31:0] val_in,
	output [31:0] val_out
);

reg [32 * LENGTH - 1:0] r;
reg [7:0] addr = 0;
reg [31:0] m[0:(LENGTH-4)];
reg [31:0] out0, out1;
reg [32 * 4 - 1:0] r_shift;
(* KEEP = "TRUE" *) reg [31:0] out0_shift;

generate
	if(LENGTH >= 8) begin
		// Infer RAM
		// RAM's output registered by r (included for free in Xilinx's
		// RAM primitives).
		// NOTE: Added out0 and out1. Since r is inside the
		// RAM primative, it doesn't help routing from the RAM to the
		// target slices. out0 and out1 should be flip-flops and mask RAM
		// routing.

		always @ (posedge clk)
		begin
			addr <= (addr + 1) % (LENGTH - 3);
			r <= m[addr];
			m[addr] <= val_in;

			out0 <= r;
			out1 <= out0;
		end
		assign val_out = out1;
	end
	else if (LENGTH == 5) begin
		always @ (posedge clk)
		begin
			r_shift <= (r_shift << 32) | val_in;
			out0_shift <= r_shift[32 * 4 - 1:32 * 3];
		end

		assign val_out = out0_shift;
	end
	else begin
		always @ (posedge clk)
			r <= (r << 32) | val_in;
		assign val_out = r[32 * LENGTH - 1:32 * (LENGTH - 1)];
	end
endgenerate

endmodule

module johnson_counter (
    input clk,
    input reset,
    output reg [2:0] count
);

always @(posedge clk) begin
    if (reset) begin
        count <= 3'b000;
    end else begin
        count <= {count[1:0], ~count[2]};
    end
end

