module FullAdder4Bit (A, B, CIN, SUM, COUT);
input [3:0] A, B, CIN;
output [3:0] SUM;
output COUT;

wire [3:0] CARRY;
wire [3:0] CARRYOUT;
wire [1:0] CINMUX;

FullAdder FA0(A[0], B[0], CIN, SUM[0], CARRY[0]);
FullAdder FA1(A[1], B[1], CARRY[0], SUM[1], CARRY[1]);
FullAdder FA2(A[2], B[2], CARRY[1], SUM[2], CARRY[2]);
FullAdder FA3(A[3], B[3], CARRY[2], SUM[3], CARRY[3]);

// 2-to-1 MUX to select carry-out
assign CINMUX = {CARRY[3], CARRYOUT[3]};
assign COUT = CINMUX[1];

// generate carry-out
generate
    FullAdder FA4(CARRY[0], CARRY[1], CARRY[2], CARRYOUT[3], CARRYOUT[2]);
    FullAdder FA5(CARRY[0], CARRY[1], CARRYOUT[2], CARRYOUT[1], CARRYOUT[0]);
endgenerate

endmodule

module FullAdder (A, B, CIN, SUM, COUT);
input A, B, CIN;
output SUM, COUT;

wire CARRY;

// generate sum
assign SUM = A ^ B ^ CIN;

// generate carry-out
assign COUT = (A & B) | (CIN & (A ^ B));

endmodule

