module mux4(
    input [3:0] in0,
    input [3:0] in1,
    input [3:0] in2,
    input [3:0] in3,
    input [1:0] sel,
    input en,
    output reg [3:0] out
);

wire [3:0] w1, w2, w3, w4, w5, w6, w7;

// generate NOT gates for enable and select inputs
assign n_en = ~en;
assign n_sel0 = ~sel[0];
assign n_sel1 = ~sel[1];

// generate AND gates for enable and select inputs
assign a_en_sel0 = en & n_sel0;
assign a_en_sel1 = en & sel[0];
assign a_nen_sel0 = n_en & n_sel0;
assign a_nen_sel1 = n_en & sel[0];

// generate AND gates for input and select inputs
assign a_in0_sel1_sel0 = in0 & sel[1] & sel[0];
assign a_in1_nsel1_sel0 = in1 & n_sel1 & sel[0];
assign a_in2_sel1_nsel0 = in2 & sel[1] & n_sel0;
assign a_in3_nsel1_nsel0 = in3 & n_sel1 & n_sel0;

// generate OR gates for input and select inputs
assign o_w1 = a_in0_sel1_sel0 | a_in1_nsel1_sel0;
assign o_w2 = a_in2_sel1_nsel0 | a_in3_nsel1_nsel0;

// generate AND gates for enable and OR gates
assign a_w3 = a_en_sel1 & o_w1;
assign a_w4 = a_nen_sel1 & o_w1;
assign a_w5 = a_en_sel0 & o_w2;
assign a_w6 = a_nen_sel0 & o_w2;

// generate OR gates for AND gates
assign o_w7 = a_w3 | a_w4 | a_w5 | a_w6;

// assign output
always @(*) begin
  if (en == 1'b1) begin
    out = o_w7;
  end
  else begin
    out = 4'b0;
  end
end

endmodule

module logic_analyzer #( parameter line_width_p = 32, LA_els_p = 256 ) (
    input clk,
    input reset,
    input valid_en_i,
    input [line_width_p-1:0] posedge_value_i,
    input [line_width_p-1:0] negedge_value_i,
    input [`BSG_SAFE_CLOG2(line_width_p)-1:0] input_bit_selector_i,
    input start_i,
    output ready_o,
    output logic_analyzer_data_o,
    output v_o,
    input deque_i
);

// keeping state of enque
logic enque, enque_r;

always_ff @ (posedge clk)
    if (reset)
        enque_r <= 0;
    else
        enque_r <= enque;

// Enque starts by start_i signal and remains high until deque signal
// is asserted. It is assumed that start_i would not be asserted 
// while dequing due to logic analyzer behavior. When first deque 
// signal is asserted it will stop enquing. Since fifo uses a
// valid_and_read protocol, in case of fifo becoming full it would stop
// enqueing until deque is asserted, and as stated there would be no 
// more enquing on that time.
assign enque = (start_i | enque_r) & ready_o; 

// Select one bit of input signal for Logic Analyzer
// LSB is posedge and MSB is negedge
logic [1:0] LA_selected_line;
assign LA_selected_line[0] = posedge_value_i[input_bit_selector_i];
assign LA_selected_line[1] = negedge_value_i[input_bit_selector_i];

// Masking the valid bit
logic valid;
assign v_o = valid & valid_en_i;

// The protocol is ready_THEN_valid since we are checking the ready_o
// signal for generating the enque signal.
bsg_fifo_1r1w_narrowed 
    #( .width_p(2),
       .els_p(LA_els_p),
       .width_out_p(1),
       .lsb_to_msb_p(1),     
       .ready_THEN_valid_p(1)
    ) narrowed_fifo (
        .clk_i(clk),
        .reset_i(reset),
        .data_i(LA_selected_line),
        .v_i(enque),
        .ready_o(ready_o),
        .v_o(valid),
        .data_o(logic_analyzer_data_o),
        .yumi_i(deque_i)
    );

endmodule

module synchronizer
   (lpf_exr_reg,
    scndry_out,
    lpf_exr,
    p_3_out,
    mb_debug_sys_rst,
    ext_reset_in,
    slowest_sync_clk);

  output lpf_exr_reg;
  output scndry_out;
  input lpf_exr;
  input [2:0] p_3_out;
  input mb_debug_sys_rst;
  input ext_reset_in;
  input slowest_sync_clk;

  wire cdc_to_i_1__0;
  wire slowest_sync_clk;
  wire [2:0] p_3_out;
  wire s_level_out_d1_cdc_to;
  wire s_level_out_d2;
  wire s_level_out_d3;
  wire scndry_out;
  wire slowest_sync_clk;

  // Clocked flip-flop that synchronizes the input signal "slowest_sync_clk" and generates the output "scndry_out".
  FDRE #(.INIT(1'b0)) flip_flop_1 (.C(slowest_sync_clk), .CE(1'b1), .D(cdc_to_i_1__0), .Q(s_level_out_d1_cdc_to), .R(1'b0));

  // LUT2 that generates the intermediate signal "cdc_to_i_1__0".
  LUT2 #(.INIT(4'hB)) lut_1 (.I0(mb_debug_sys_rst), .I1(ext_reset_in), .O(cdc_to_i_1__0));

  // Series of clocked flip-flops that synchronize the input signals "mb_debug_sys_rst" and "ext_reset_in" and generate intermediate signals that are used in the LUT5.
  FDRE #(.INIT(1'b0)) flip_flop_2 (.C(slowest_sync_clk), .CE(1'b1), .D(s_level_out_d1_cdc_to), .Q(s_level_out_d2), .R(1'b0));
  FDRE #(.INIT(1'b0)) flip_flop_3 (.C(slowest_sync_clk), .CE(1'b1), .D(s_level_out_d2), .Q(s_level_out_d3), .R(1'b0));

  // LUT5 that takes the inputs "lpf_exr", "p_3_out[0]", "scndry_out", "p_3_out[1]", and "p_3_out[2]" and generates the output "lpf_exr_reg".
  LUT5 #(.INIT(32'hEAAAAAA8)) lut_2 (.I0(lpf_exr), .I1(p_3_out[0]), .I2(scndry_out), .I3(p_3_out[1]), .I4(p_3_out[2]), .O(lpf_exr_reg));

endmodule

