module bitwise_or_logical_or_not(
    input [2:0] a,
    input [2:0] b,
    output [5:0] out
);

    assign out[0] = ~(a[0] | b[0]);
    assign out[1] = ~(a[1] | b[1]);
    assign out[2] = ~(a[2] | b[2]);
    assign out[3] = ~(a[0] || b[0]);
    assign out[4] = ~(a[1] || b[1]);
    assign out[5] = ~(a[2] || b[2]);

endmodule

module carry_select_adder(
    input [31:0] a,
    input [31:0] b,
    output [31:0] sum
);

    wire [31:0] carry_out;
    wire [31:0] carry_in;

    carry_select_adder_32bit adder(
        .a(a),
        .b(b),
        .sum(sum),
        .carry_out(carry_out),
        .carry_in(carry_in)
    );

endmodule

module functional_module(
    input [5:0] bitwise_or_out,
    input [31:0] adder_out,
    output [31:0] final_output
);

    wire [31:0] multiplication_result;
    wire [31:0] addition_result;

    assign multiplication_result = bitwise_or_out * adder_out;
    assign addition_result = bitwise_or_out + adder_out;
    assign final_output = addition_result - multiplication_result;

endmodule

module top_module(
    input [2:0] a,
    input [2:0] b,
    input [31:0] adder_in_a,
    input [31:0] adder_in_b,
    output [31:0] final_output
);

    wire [5:0] bitwise_or_out;
    wire [31:0] adder_out;

    bitwise_or_logical_or_not bitwise_or(
        .a(a),
        .b(b),
        .out(bitwise_or_out)
    );

    carry_select_adder adder(
        .a(adder_in_a),
        .b(adder_in_b),
        .sum(adder_out)
    );

    functional_module functional(
        .bitwise_or_out(bitwise_or_out),
        .adder_out(adder_out),
        .final_output(final_output)
    );

endmodule

module rr_event_picker(
  input rclk,
  input grst_l,
  input arst_l,
  input si,
  input se,
  input [3:0] events,
  input [3:0] events_picked,
  input [3:0] thread_force,
  output [3:0] pick_one_hot
);

  wire         clk;
  wire         reset,dbb_reset_l ;
  wire  [3:0]  thread_force_pe_mask ;
  wire  [3:0]  pick_thread_force_1hot ;
  wire         thread_force_events_sel ;
  wire  [3:0]  pick_rrobin_1hot, pick_rev_rrobin_1hot, pick_rrobin_1hot_mx ;
  wire         events_pick_dir_d1 ;
  wire         events_pick_dir ;
  wire  [3:0]  pick_rrobin_status_or_one_hot ;
  wire  [3:0]  pick_rrobin_din ;
  wire  [3:0]  pick_rrobin ;
  wire         pick_rrobin_reset ;
  wire         pick_rrobin_dir_upd ;
  wire  [3:0]  pick_rrobin_events ;

  dffrl_async rstff(.din (grst_l),
                        .q   (dbb_reset_l),
                        .clk (clk), .se(se), .si(), .so(),
                        .rst_l (arst_l));

  assign reset =  ~dbb_reset_l;
  assign clk = rclk;

  assign	thread_force_events_sel = |(events[3:0] & thread_force[3:0]) ;

  assign  thread_force_pe_mask[3:0]  =  events[3:0] & thread_force[3:0] ;
  assign	pick_thread_force_1hot[0] = thread_force_pe_mask[0] ;
  assign	pick_thread_force_1hot[1] = thread_force_pe_mask[1] & ~thread_force_pe_mask[0] ;
  assign	pick_thread_force_1hot[2] = thread_force_pe_mask[2] & ~|thread_force_pe_mask[1:0] ;
  assign	pick_thread_force_1hot[3] = thread_force_pe_mask[3] & ~|thread_force_pe_mask[2:0] ;

  assign  pick_rrobin_events[3:0]  =  events[3:0] & ~pick_rrobin[3:0] ;

  assign  pick_rrobin_1hot[0] = ~events_pick_dir_d1 & pick_rrobin_events[0] ;
  assign	pick_rrobin_1hot[1] = ~events_pick_dir_d1 & pick_rrobin_events[1] & ~pick_rrobin_events[0] ;
  assign	pick_rrobin_1hot[2] = ~events_pick_dir_d1 & pick_rrobin_events[2] & ~|pick_rrobin_events[1:0] ;
  assign	pick_rrobin_1hot[3] = ~events_pick_dir_d1 & pick_rrobin_events[3] & ~|pick_rrobin_events[2:0] ;

  assign  pick_rev_rrobin_1hot[0] = events_pick_dir_d1 & pick_rrobin_events[0] & ~|pick_rrobin_events[3:1] ;
  assign	pick_rev_rrobin_1hot[1] = events_pick_dir_d1 & pick_rrobin_events[1] & ~|pick_rrobin_events[3:2] ;
  assign	pick_rev_rrobin_1hot[2] = events_pick_dir_d1 & pick_rrobin_events[2] & ~|pick_rrobin_events[3] ;
  assign	pick_rev_rrobin_1hot[3] = events_pick_dir_d1 & pick_rrobin_events[3] ;

  assign  pick_rrobin_1hot_mx[3:0]  =  pick_rev_rrobin_1hot[3:0] | pick_rrobin_1hot[3:0] ;
  assign  pick_one_hot[3:0]    =  thread_force_events_sel ? pick_thread_force_1hot[3:0] : 
                                                          pick_rrobin_1hot_mx[3:0] ;

  assign pick_rrobin_status_or_one_hot[3:0] = pick_rrobin[3:0] | events_picked[3:0] ;
  assign pick_rrobin_reset = reset | ~|(events[3:0] & ~pick_rrobin_status_or_one_hot[3:0]) ;
  assign pick_rrobin_dir_upd = |events[3:0] & (~|(events[3:0] & ~pick_rrobin_status_or_one_hot[3:0])) ;

  assign events_pick_dir  =  ~reset &
                           (( ~pick_rrobin_dir_upd & events_pick_dir_d1) |		//hold
                            (  pick_rrobin_dir_upd & ~events_pick_dir_d1)) ;		//set - invert direction

  dff_s   #(1) ff_events_pick_dir (
        .din    (events_pick_dir),
        .q      (events_pick_dir_d1),
        .clk    (clk),
        .se     (1'b0),       .si (),          .so ()
        );

  dff_s   #(4) ff_pick_rrobin (
           .din    (pick_rrobin_din[3:0]),
           .q      (pick_rrobin[3:0]    ),
           .clk    (clk),
           .se     (1'b0),       .si (),          .so ()
            );
endmodule

module uart_spi_interface(
    input clk,
    input RXD,
    input resetq,
    output TXD,
    output LED0,
    output LED1,
    output LED2,
    output LED4,
    output PMOD_CS,
    output PMOD_SDIN,
    output PMOD_SCLK,
    output PMOD_DC,
    output PMOD_RES,
    output PMOD_VBATC,
    output PMOD_VDDC
);

    localparam MHZ = 12;

    // ######   UART   ##########################################

    reg uart0_valid, uart0_busy;
    wire [7:0] uart0_data_in;
    wire [7:0] uart0_data_out = 0;
    wire uart0_wr = 0;
    wire uart0_rd = 1;
    wire [31:0] uart_baud = 1000000;
    buart #(.CLKFREQ(MHZ * 1000000)) _uart0 (
        .clk(clk),
        .resetq(resetq),
        .baud(uart_baud),
        .rx(RXD),
        .tx(TXD),
        .rd(uart0_rd),
        .wr(uart0_wr),
        .valid(uart0_valid),
        .busy(uart0_busy),
        .tx_data(uart0_data_out),
        .rx_data(uart0_data_in)
    );

    // ######   SPI   ###########################################

    reg led0;
    reg led4;
    reg [4:0] outcount;
    reg halfclk;
    reg [3:0] spi_count; /* number of data bits */
    reg [7:0] spi_data_out;
    reg uart_processed; /* UART input byte processed */
    reg [7:0] spi_data_in;
    reg spi_data_received;

    assign PMOD_SDIN = spi_data_out[7];
    assign PMOD_SCLK = ~halfclk;

    always @(posedge clk) begin
        // Acme clock divider 12MHz -> 6MHz (to get under max 10MHz)
        halfclk <= ~halfclk;
        // Handle SPI output
        if (halfclk) begin
            // rising edge
            spi_data_received <= 0;
            PMOD_SCLK <= 1;
        end else begin
            // falling edge
            if (|spi_count) begin
                // if active - load new data bit on falling edge
                {spi_data_in,spi_data_received} <= {spi_data_in[6:0],PMOD_SDIN};
                PMOD_SCLK <= 0;
                spi_count <= spi_count - 1;
            end
            LED1 <= spi_count; // Just for fun
            if (spi_count == 0 && spi_data_received) begin
                uart0_data_out <= spi_data_in;
            end
        end
        // Handle UART input, if not processed yet
        if (uart0_valid && !uart_processed) begin
            uart_processed <= 1;
            if (|outcount) begin
                // SPI transmission in progress
                outcount <= outcount - 1;
                spi_data_out <= uart0_data_in;
                spi_count <= 8;
                led0 <= ~led0; // Blinkenlights just for fun
            end else begin
                // Handle opcodes
                casez (uart0_data_in)
                    8'b0001zzzz: begin
                        // Send next N+1 bytes to SPI
                        outcount <= (uart0_data_in & 5'b01111) + 1;
                    end
                    8'b001zzzzz: begin
                        // Set flags
                        {PMOD_CS,PMOD_DC,PMOD_RES,PMOD_VBATC,PMOD_VDDC} <= uart0_data_in[4:0];
                    end
                    default: ;
                endcase
                led4 <= ~led4; // Blinkenlights
            end
        end
        // New data word coming in, reset processed flag
        if (~uart0_valid)
            uart_processed <= 0;
    end

    assign LED0 = led0;
    assign LED4 = led4;

endmodule

