module peripheral_ult(
    input           clk,
    input           rst,
    input [15:0]    d_in,   // Dato de entrada
    input           cs,     // 
    input [3:0]     addr,   // 4 LSB from j1_io_addr
    input           rd,     // Para leer 
    input           wr,     // Comando para escribir
    input           signal, // Del dispositivo físico

    output reg [15:0] d_out // Dato de salida
    );

//------------------------------------ regs and wires-------------------------------

    reg [1:0]       s;  // Selector

    wire            rst_n = ~rst ;
    wire [15:0]     value ; 
    wire            done ;

//------------------------------------ regs and wires-------------------------------

    ultrasonic  ut ( .clk(clk), .rst_n(rst_n), .signal(signal) , .value(value) , .done(done) );

    always @(*) begin// Selector de modo
        case (addr)
            4'h0:       s = (cs && rd) ? 2'b01 : 2'b00 ; // Done
            4'h2:       s = (cs && rd) ? 2'b10 : 2'b00 ; // Value[15:0]
            default:    s = 2'b00 ;
        endcase
    end

    always @(negedge clk) begin // Multiplexa salidas del periferico
        case (s)
            2'b01:      d_out[0]    = done ;
            2'b10:      d_out       = value ;
            default:    d_out       = 0 ;
        endcase
    end

    always @(posedge clk) begin
        if (rst_n) begin
            d_out <= 0;
        end else if (cs && wr) begin
            // Configure the ultrasonic sensor
            // The configuration is in the lower 8 bits of d_in
            // Bits 0-3: Trigger pin number
            // Bits 4-7: Echo pin number
            ut.trigger_pin <= d_in[3:0];
            ut.echo_pin <= d_in[7:4];
        end else if (cs && rd) begin
            // Read the measured distance from the ultrasonic sensor
            d_out[15:0] <= value[15:0];
        end
    end

endmodule

module ultrasonic(
    input           clk,
    input           rst_n,
    input           signal,

    output reg [15:0] value,
    output reg      done
    );

    reg [31:0]      counter;
    reg             trigger;
    reg             measuring;
    reg             pulse_started;
    reg             pulse_ended;
    reg             pulse_width_started;
    reg             pulse_width_ended;

    parameter       MAX_COUNTER = 50000000; // Counter maximum value

    // Configuration inputs
    reg [3:0]       trigger_pin;
    reg [3:0]       echo_pin;

    always @(posedge clk) begin
        if (rst_n) begin
            counter <= 0;
            trigger <= 0;
            measuring <= 0;
            pulse_started <= 0;
            pulse_ended <= 0;
            pulse_width_started <= 0;
            pulse_width_ended <= 0;
            value <= 0;
            done <= 0;
        end else begin
            // Trigger a pulse if not already measuring
            if (!measuring && trigger) begin
                signal <= 1 << trigger_pin;
                measuring <= 1;
                pulse_started <= 1;
                counter <= 0;
            end

            // Measure pulse width
            if (measuring) begin
                if (signal & (1 << echo_pin) && !pulse_ended) begin
                    pulse_ended <= 1;
                    pulse_width_started <= 1;
                end else if (!signal & (1 << echo_pin) && pulse_ended) begin
                    pulse_width_ended <= 1;
                end

                if (pulse_width_ended) begin
                    value <= counter;
                    done <= 1;
                    measuring <= 0;
                end
            end

            // Increment counter
            if (counter < MAX_COUNTER) begin
                counter <= counter + 1;
            end else begin
                measuring <= 0;
            end
        end
    end

endmodule

module ram_controller_ex_lfsr8 (
  input clk,
  input reset_n,
  input enable,
  input pause,
  input load,
  input [7:0] ldata,
  output reg [7:0] data
);

  parameter seed = 8'h32;

  reg [7:0] lfsr_data;

  always @ (posedge clk or negedge reset_n) begin
    if (!reset_n) begin
      lfsr_data <= seed;
    end
    else begin
      if (!enable) begin
        lfsr_data <= seed;
      end
      else begin
        if (load) begin
          lfsr_data <= ldata;
        end
        else begin
          if (!pause) begin
            lfsr_data[0] <= lfsr_data[7] ^ lfsr_data[0];
            lfsr_data[1] <= lfsr_data[0] ^ lfsr_data[1];
            lfsr_data[2] <= lfsr_data[1] ^ lfsr_data[2];
            lfsr_data[3] <= lfsr_data[2] ^ lfsr_data[3];
            lfsr_data[4] <= lfsr_data[3] ^ lfsr_data[4];
            lfsr_data[5] <= lfsr_data[4] ^ lfsr_data[5];
            lfsr_data[6] <= lfsr_data[5] ^ lfsr_data[6];
            lfsr_data[7] <= lfsr_data[6] ^ lfsr_data[7];
          end
        end
      end
    end
  end

  assign data = lfsr_data;

endmodule

module JK_FF_async_rst (CK, J, K, RN, Q, QN);
input CK;
input J;
input K;
input RN;
output Q;
output QN;
reg Q;
reg QN;

always @ (posedge CK or negedge RN) begin
  if (RN == 0) begin
    Q <= 0;
    QN <= 1;
  end else begin
    if (J == 1 && K == 0) begin
      Q <= 1;
    end else if (J == 0 && K == 1) begin
      Q <= 0;
    end else if (J == 1 && K == 1) begin
      Q <= ~Q;
    end
    QN <= ~Q;
  end
end

endmodule

module d_flip_flop (
    input clk,
    input d,
    output reg q
);

    reg s, r;

    always @(posedge clk) begin
        s <= d;
        r <= ~d;
    end

    always @(posedge clk) begin
        if (s && !r)
            q <= 1'b1;
        else if (!s && r)
            q <= 1'b0;
    end

endmodule

module top_module (
    input [3:0] a,
    input [3:0] b,
    input control,
    output [3:0] out_add,
    output [3:0] out_sub,
    output [7:0] s,
    output overflow
);

// Sequential shift register module for storing the inputs
reg [3:0] reg_a, reg_b;
always @(posedge clk) begin
    if (reset) begin
        reg_a <= 4'b0;
        reg_b <= 4'b0;
    end else begin
        reg_a <= a;
        reg_b <= b;
    end
end

// Combinational circuit for addition and subtraction operations
wire [3:0] add_result, sub_result;
assign add_result = reg_a + reg_b;
assign sub_result = reg_a - reg_b;

// Carry look-ahead adder for addition and overflow detection
wire [4:0] add_carry;
assign add_carry = {1'b0, add_result} + {1'b0, reg_a} + {1'b0, reg_b};
assign overflow = add_carry[5];

// FSM for controlling the operation
reg [1:0] state;
parameter ADD = 2'b00, SUB = 2'b01;
always @(posedge clk) begin
    if (reset) begin
        state <= ADD;
    end else begin
        case (state)
            ADD: begin
                out_add <= add_result;
                s <= {1'b0, add_result};
                if (control) begin
                    state <= SUB;
                end
            end
            SUB: begin
                out_sub <= sub_result;
                s <= {1'b0, sub_result};
                if (!control) begin
                    state <= ADD;
                end
            end
        endcase
    end
end

endmodule

module ripple_addsub (
    input [7:0] A,
    input [7:0] B,
    input SUB,
    input CLK,
    output reg [7:0] SUM,
    output reg CARRY_OUT
);

    reg [7:0] temp_sum;
    reg carry_in;

    always @(posedge CLK) begin
        if(SUB) begin
            temp_sum <= A - B - carry_in;
            CARRY_OUT <= ~((~A[7] & B[7]) | (~B[7] & temp_sum[7]) | (temp_sum[7] & ~A[7]));
        end else begin
            temp_sum <= A + B + carry_in;
            CARRY_OUT <= (temp_sum[8] == 1);
        end
        SUM <= temp_sum[7:0];
        carry_in <= CARRY_OUT;
    end

endmodule

module FIFO_image_filter_img_5_data_stream_1_V_shiftReg (
