wire [9:0] final_out;

edge_detection edge_detector (
    .clk(clk),
    .in(in),
    .anyedge(anyedge_wire)
);

accumulator accumulator_inst (
    .clk(clk),
    .in(in),
    .valid(valid_a),
    .counter_reset(counter_reset),
    .data_out(accumulator_out),
    .valid_out()
);

functional_module functional_inst (
