module unsigned_non_restoring_divider (
  input [N-1:0] dividend,
  input [N-1:0] divisor,
  input clk,
  input rst,
  output reg [N-1:0] quotient,
  output reg [N-1:0] remainder
);

parameter N = 8; // number of bits for dividend and divisor

reg [N-1:0] dividend_reg;
reg [N-1:0] divisor_reg;
reg [N-1:0] quotient_reg;
reg [N-1:0] remainder_reg;
reg [N-1:0] dividend_shift_reg;
reg [N:0] counter_reg;

always @(posedge clk) begin
  if (rst) begin
    dividend_reg <= 0;
    divisor_reg <= 0;
    quotient_reg <= 0;
    remainder_reg <= 0;
    dividend_shift_reg <= {dividend, 1'b0};
    counter_reg <= N+1;
  end
  else begin
    dividend_reg <= dividend_shift_reg[N-1:0];
    divisor_reg <= divisor;
    quotient_reg <= 0;
    remainder_reg <= dividend_shift_reg[N-1:0];
    dividend_shift_reg <= {dividend_shift_reg[N-1:0], dividend_shift_reg[N]};
    if (counter_reg > 0) begin
      if (remainder_reg >= divisor_reg) begin
        remainder_reg <= remainder_reg - divisor_reg;
        quotient_reg <= {quotient_reg[N-2:0], 1'b1};
      end
      else begin
        quotient_reg <= {quotient_reg[N-2:0], 1'b0};
      end
      counter_reg <= counter_reg - 1;
    end
  end
end

assign quotient = quotient_reg;
assign remainder = remainder_reg[N-1:0];

endmodule

module counter(
    input clk_i,
    input reset_i,
    input [3:0] count_i,
    output [3:0] count_o
);

    reg [3:0] count;

    assign count_o = count;

    always @(posedge clk_i) begin
        if (reset_i) begin
            count <= 0;
        end else if (count == 15) begin
            count <= 0;
        end else begin
            count <= count + 1;
        end
    end

endmodule

module counter (
    input CLK,
    output reg [3:0] Q
);

    always @(posedge CLK) begin
        if (Q == 4'b1111) begin
            Q <= 4'b0000;
        end else begin
            Q <= Q + 1;
        end
    end

endmodule

module and_gate_using_mux_not(
    input a,
    input b,
    output wire out
);

wire not_a, not_b;
not not_gate_a(a, not_a);
not not_gate_b(b, not_b);

wire mux_out;
assign mux_out = not_a & not_b;

not not_gate_out(mux_out, out);

endmodule

module i2c_master(
  input SDA,
  input SCL,
  input START,
  input STOP,
  input [7:0] ADDR,
  input WRITE,
  input [7:0] DATA,
  output reg ACK,
  output reg ACK_ERR,
  output reg BUS_BUSY
);

  reg [7:0] data_reg;
  reg [7:0] addr_reg;
  reg [2:0] state;
  reg [2:0] next_state;
  reg [2:0] ack_state;
  reg [2:0] ack_err_state;
  reg [2:0] bus_busy_state;
  reg [2:0] write_state;
  reg [2:0] read_state;

  assign SDA = (state == 0) ? 1'b1 : (state == 1) ? START : (state == 2) ? STOP : (state == 3) ? ADDR[7] : (state == 4) ? ADDR[6] : (state == 5) ? ADDR[5] : (state == 6) ? ADDR[4] : (state == 7) ? ADDR[3] : (state == 8) ? ADDR[2] : (state == 9) ? ADDR[1] : (state == 10) ? ADDR[0] : (state == 11) ? WRITE : (state == 12) ? DATA[7] : (state == 13) ? DATA[6] : (state == 14) ? DATA[5] : (state == 15) ? DATA[4] : (state == 16) ? DATA[3] : (state == 17) ? DATA[2] : (state == 18) ? DATA[1] : DATA[0];

  assign BUS_BUSY = (state != 0) ? 1'b1 : 1'b0;

  always @(posedge SCL) begin
    if (state == 0) begin
      if (START) begin
        addr_reg <= ADDR;
        data_reg <= DATA;
        state <= 1;
      end
    end
    else if (state == 1) begin
      if (!SDA) begin
        state <= 2;
      end
    end
    else if (state >= 3 && state <= 10) begin
      if (SCL) begin
        state <= state + 1;
      end
    end
    else if (state == 11) begin
      if (SCL) begin
        state <= 12;
      end
    end
    else if (state >= 12 && state <= 19) begin
      if (SCL) begin
        state <= state + 1;
      end
    end
    else if (state == 20) begin
      if (!SDA) begin
        ack_state <= 0;
        ack_err_state <= 0;
        bus_busy_state <= 0;
        write_state <= 0;
        read_state <= 0;
        if (WRITE) begin
          write_state <= 1;
          next_state <= 21;
        end
        else begin
          read_state <= 1;
          next_state <= 23;
        end
      end
    end
    else if (state == 21) begin
      if (SCL) begin
        state <= 22;
      end
    end
    else if (state == 22) begin
      if (SCL) begin
        state <= 20;
        ack_state <= 1;
      end
    end
    else if (state == 23) begin
      if (SCL) begin
        state <= 24;
      end
    end
    else if (state == 24) begin
      if (SDA) begin
        state <= 25;
      end
    end
    else if (state == 25) begin
      if (SCL) begin
        state <= 26;
      end
    end
    else if (state == 26) begin
      if (SCL) begin
        state <= 27;
        data_reg <= {SDA, data_reg[7:1]};
      end
    end
    else if (state == 27) begin
      if (!SCL) begin
        state <= 28;
      end
    end
    else if (state == 28) begin
      if (SDA) begin
        state <= 29;
      end
    end
    else if (state == 29) begin
      if (SCL) begin
        state <= 30;
        ack_state <= 1;
      end
    end
    else if (state == 30) begin
      if (!SCL) begin
        state <= 31;
      end
    end
    else if (state == 31) begin
      if (read_state) begin
        state <= 32;
      end
      else begin
        state <= 20;
      end
    end
    else if (state == 32) begin
      if (SCL) begin
        state <= 33;
      end
    end
    else if (state == 33) begin
      if (SCL) begin
        state <= 34;
        SDA <= data_reg[7];
      end
    end
    else if (state == 34) begin
      if (!SCL) begin
        state <= 35;
      end
    end
    else if (state == 35) begin
      if (SCL) begin
        state <= 36;
        SDA <= data_reg[6];
      end
    end
    else if (state == 36) begin
      if (!SCL) begin
        state <= 37;
      end
    end
    else if (state == 37) begin
      if (SCL) begin
        state <= 38;
        SDA <= data_reg[5];
      end
    end
    else if (state == 38) begin
      if (!SCL) begin
        state <= 39;
      end
    end
    else if (state == 39) begin
      if (SCL) begin
        state <= 40;
        SDA <= data_reg[4];
      end
    end
    else if (state == 40) begin
      if (!SCL) begin
        state <= 41;
      end
    end
    else if (state == 41) begin
      if (SCL) begin
        state <= 42;
        SDA <= data_reg[3];
      end
    end
    else if (state == 42) begin
      if (!SCL) begin
        state <= 43;
      end
    end
    else if (state == 43) begin
      if (SCL) begin
        state <= 44;
        SDA <= data_reg[2];
      end
    end
    else if (state == 44) begin
      if (!SCL) begin
        state <= 45;
      end
    end
    else if (state == 45) begin
      if (SCL) begin
        state <= 46;
        SDA <= data_reg[1];
      end
    end
    else if (state == 46) begin
      if (!SCL) begin
        state <= 47;
      end
    end
    else if (state == 47) begin
      if (SCL) begin
        state <= 48;
        SDA <= data_reg[0];
      end
    end
    else if (state == 48) begin
      if (!SCL) begin
        state <= 49;
      end
    end
    else if (state == 49) begin
      if (SCL) begin
        state <= 50;
        ack_state <= 1;
      end
    end
    else if (state == 50) begin
      if (!SCL) begin
        state <= 51;
      end
    end
    else if (state == 51) begin
      if (write_state) begin
        state <= 20;
      end
      else begin
        state <= 32;
      end
    end

    if (ack_state == 1) begin
      if (SDA) begin
        ACK <= 0;
        ack_state <= 0;
      end
    end

    if (ack_err_state == 1) begin
      if (SDA) begin
        ACK_ERR <= 1;
        ack_err_state <= 0;
      end
    end

    if (bus_busy_state == 1) begin
      if (SDA) begin
        BUS_BUSY <= 1;
        bus_busy_state <= 0;
      end
    end

    if (state == 22 || state == 30 || state == 50) begin
      if (!SDA) begin
        ack_err_state <= 1;
      end
    end

  end

endmodule

module byte_swapping (
    input [7:0] in,
    output reg [7:0] out
);
    always @(*) begin
        out[7:0] = {in[0+8*1], in[1+8*1], in[2+8*1], in[3+8*1], in[4+8*1], in[5+8*1], in[6+8*1], in[7+8*1]};
    end
endmodule

module edge_detection (
    input clk,
    input reset,      // Synchronous active-high reset
    input in,         // Input signal
    output reg out    // Output edge detection signal
);
    reg in_prev;

    always @(posedge clk) begin
        if (reset) begin
            in_prev <= 1'b0;
            out <= 1'b0;
        end else begin
            in_prev <= in;
            out <= (in & ~in_prev);
        end
    end
endmodule

module edge_detection_and_counter (
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] in,   // Input vector
    output reg [3:0] counter_out   // Output 4-bit LED counter
);
    wire [7:0] swapped_in;
    wire edge_detected;

    byte_swapping bs (
        .in(in),
        .out(swapped_in)
    );

    edge_detection ed (
        .clk(clk),
        .reset(reset),
        .in(swapped_in[0]),
        .out(edge_detected)
    );

    always @(posedge clk) begin
        if (reset) begin
            counter_out <= 4'b0;
        end else begin
            if (edge_detected) begin
                if (counter_out == 4'b1111) begin
                    counter_out <= 4'b0;
                end else begin
                    counter_out <= counter_out + 1;
                end
            end
        end
    end
endmodule

module add_sub (
    input [3:0] A,
    input [3:0] B,
    input sub,
    output [3:0] q
);

    assign q = sub ? A - B : A + B;

endmodule

module mux (
    input [3:0] A,
    input [3:0] B,
    input [3:0] C,
    input [3:0] D,
    input S0,
    input S1,
    output [3:0] q
);

    wire [3:0] out1, out2, out3, out4;

    transmission_gate #(1,1) tg1 (out1[0], A[0], S0);
    transmission_gate #(1,1) tg2 (out1[1], A[1], S0);
    transmission_gate #(1,1) tg3 (out1[2], A[2], S0);
    transmission_gate #(1,1) tg4 (out1[3], A[3], S0);

    transmission_gate #(1,1) tg5 (out2[0], B[0], ~S0);
    transmission_gate #(1,1) tg6 (out2[1], B[1], ~S0);
    transmission_gate #(1,1) tg7 (out2[2], B[2], ~S0);
    transmission_gate #(1,1) tg8 (out2[3], B[3], ~S0);

    transmission_gate #(1,1) tg9 (out3[0], C[0], S1);
    transmission_gate #(1,1) tg10 (out3[1], C[1], S1);
    transmission_gate #(1,1) tg11 (out3[2], C[2], S1);
    transmission_gate #(1,1) tg12 (out3[3], C[3], S1);

    transmission_gate #(1,1) tg13 (out4[0], D[0], ~S1);
    transmission_gate #(1,1) tg14 (out4[1], D[1], ~S1);
    transmission_gate #(1,1) tg15 (out4[2], D[2], ~S1);
    transmission_gate #(1,1) tg16 (out4[3], D[3], ~S1);

    assign q = S1 ? {out3, out4} : {out1, out2};

endmodule

module or_gate (
    input [3:0] A,
    input [3:0] B,
    output [3:0] q
);

    assign q = A | B;

endmodule

module top_module (
    input [3:0] A,
    input [3:0] B,
    input sub,
    input select,
    input [3:0] C,
    input [3:0] D,
    input S0,
    input S1,
    output [3:0] q
);

    wire [3:0] add_sub_out, mux_out, or_gate_out;

    add_sub add_sub_inst (.A(A), .B(B), .sub(sub), .q(add_sub_out));
    mux mux_inst (.A(A), .B(B), .C(C), .D(D), .S0(S0), .S1(S1), .q(mux_out));
    or_gate or_gate_inst (.A(add_sub_out), .B(mux_out), .q(or_gate_out));

    assign q = or_gate_out;

endmodule

