module fpga_control (
	input wire clk,
	input wire rst,
	input wire [3:0] AD,
	input wire [7:0] DI,
	output reg [7:0] DO,
	input wire rw,
	input wire cs,
	output wire irq,

	input wire clk_in,

	// physical connections
	output reg [7:0] leds,
	output reg [7:0] led7hi,
	output reg [7:0] led7lo,
	output reg [2:0] rgb1,
	output reg [2:0] rgb2,
	input wire  [3:0] switches,
	input wire  [3:0] keys
);

	// Timer logic
	reg [23:0] timer_cnt; // 24-bit counter for timer
	reg [23:0] timer_prescaler; // 24-bit prescaler for timer
	reg [7:0] timer_mode; // 8-bit mode register for timer
	reg timer_eq_flag; // Flag to indicate timer match

	// IRQ logic
	assign irq = timer_mode[7] & timer_mode[6];

	// Timer logic
	always @ (posedge clk_in) begin
		if (rst) begin
			timer_cnt <= 0;
			timer_eq_flag <= 0;
		end else begin
			if (timer_mode[0]) begin
				if (timer_cnt == timer_prescaler) begin
					timer_eq_flag <= 1;
					timer_cnt <= 0;
				end else begin
					timer_cnt <= timer_cnt + 1'b1;
					if (timer_mode[7]) timer_eq_flag <= 0;
				end
			end
		end
	end

	// IO logic
	always @ (posedge clk) begin
		if (rst) begin
			leds <= 8'b11111111;
			rgb1 <= 3'b111;
			rgb2 <= 3'b111;
			led7hi <= 0;
			led7lo <= 0;
			timer_mode <= 0;
			timer_prescaler <= 0;
		end else begin
			if (timer_eq_flag) timer_mode[7] <= 1;

			if (cs) begin
				if (rw) begin // Read operation
					case (AD[3:0])
						4'b0000: DO <= ~leds; // Inverted LED output
						4'b0001: DO <= led7hi; // Upper half of 7-segment display output
						4'b0010: DO <= led7lo; // Lower half of 7-segment display output
						4'b0011: begin // RGB LED output
							DO[6:4] <= ~rgb1;
							DO[2:0] <= ~rgb2;
						end
						4'b0100: DO <= {switches, ~keys}; // Switch and key input
						4'b1000: begin // Timer mode
							DO <= timer_mode;
							timer_mode[7] <= 0;
						end
						4'b1001: DO <= timer_mode[0]?timer_cnt[23:16]:timer_prescaler[23:16]; // Timer counter (upper 8 bits)
						4'b1010: DO <= timer_mode[0]?timer_cnt[15:8]:timer_prescaler[15:8]; // Timer counter (middle 8 bits)
						4'b1011: DO <= timer_mode[0]?timer_cnt[7:0]:timer_prescaler[7:0]; // Timer counter (lower 8 bits)
					endcase
				end else begin // Write operation
					case (AD[3:0])
						4'b0000: leds <= ~DI; // Inverted LED output
						4'b0001: led7hi <= DI; // Upper half of 7-segment display output
						4'b0010: led7lo <= DI; // Lower half of 7-segment display output
						4'b0011: begin // RGB LED output
							rgb1 <= ~DI[6:4];
							rgb2 <= ~DI[2:0];
						end
						4'b1000: timer_mode[6:0] <= DI[6:0]; // Timer mode
						4'b1001: timer_prescaler[23:16] <= DI; // Timer prescaler (upper 8 bits)
						4'b1010: timer_prescaler[15:8] <= DI; // Timer prescaler (middle 8 bits)
						4'b1011: timer_prescaler[7:0] <= DI; // Timer prescaler (lower 8 bits)
					endcase
				end
			end
		end
	end
endmodule

module mux_dff (
    Q  ,
    CLK,
    D  ,
    DE ,
    SCD,
    SCE
);

    // Module ports
    output Q  ;
    input  CLK;
    input  D  ;
    input  DE ;
    input  SCD;
    input  SCE;

    // Module supplies
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    // Local signals
    wire buf_Q      ;
    reg  notifier   ;
    wire D_delayed  ;
    wire DE_delayed ;
    wire SCD_delayed;
    wire SCE_delayed;
    wire CLK_delayed;
    wire mux_out    ;
    wire de_d       ;
    wire awake      ;
    wire cond1      ;
    wire cond2      ;
    wire cond3      ;

    //                                 Name       Output   Other arguments
    sky130_fd_sc_hd__udp_mux_2to1      mux_2to10 (mux_out, de_d, SCD_delayed, SCE_delayed            );
    sky130_fd_sc_hd__udp_mux_2to1      mux_2to11 (de_d   , buf_Q, D_delayed, DE_delayed              );
    sky130_fd_sc_hd__udp_dff$P_pp$PG$N dff0      (buf_Q  , mux_out, CLK_delayed, notifier, VPWR, VGND);
    assign awake = ( VPWR === 1'b1 );
    assign cond1 = ( awake && ( SCE_delayed === 1'b0 ) && ( DE_delayed === 1'b1 ) );
    assign cond2 = ( awake && ( SCE_delayed === 1'b1 ) );
    assign cond3 = ( awake && ( DE_delayed === 1'b1 ) && ( D_delayed !== SCD_delayed ) );
    buf                                buf0      (Q      , buf_Q                                     );

    // Delay inputs by one clock cycle
    sky130_fd_sc_hd__udp_dff$P_pp$PG$N dff1 (D_delayed  , D  , CLK, 1'b0, VPWR, VGND);
    sky130_fd_sc_hd__udp_dff$P_pp$PG$N dff2 (DE_delayed , DE , CLK, 1'b0, VPWR, VGND);
    sky130_fd_sc_hd__udp_dff$P_pp$PG$N dff3 (SCD_delayed, SCD, CLK, 1'b0, VPWR, VGND);
    sky130_fd_sc_hd__udp_dff$P_pp$PG$N dff4 (SCE_delayed, SCE, CLK, 1'b0, VPWR, VGND);
    sky130_fd_sc_hd__udp_dff$P_pp$PG$N dff5 (CLK_delayed, CLK, CLK, 1'b0, VPWR, VGND);

    // Connect wires to outputs of delay elements
    assign de_d = mux_2to10.out;
    assign CLK_delayed = dff5.Q;

    // Select inputs for the 2-to-1 mux based on conditions
    assign mux_2to10.in0 = D_delayed;
    assign mux_2to10.in1 = SCD_delayed;
    assign mux_2to11.sel = DE_delayed;
    assign mux_2to11.in0 = buf_Q;
    assign mux_2to11.in1 = de_d;

    // Connect notifier to output of D flip-flop
    always @(posedge CLK_delayed) begin
        notifier <= buf_Q;
    end

endmodule

module d_ff_en_parameterized #(parameter N=1) (
  input [31:0] D,
  input E,
  input CLK,
  output [31:0] Q
);

  wire [31:0] Q_int [0:N-1];

  genvar i;
  generate
    for (i = 0; i < N; i = i + 1) begin : d_ff_en_instance
      d_ff_en #( .INIT(1'b0) ) dff (
        .D(D[i]),
        .E(E),
        .CLK(CLK),
        .Q(Q_int[i])
      );
    end
  endgenerate

  assign Q = Q_int[N-1];

endmodule

module d_ff_en #(parameter INIT=1'b0) (
  input D,
  input E,
  input CLK,
  output Q
);

  reg Q_reg;

  always @(posedge CLK) begin
    if (E) begin
      Q_reg <= D;
    end
  end

  assign Q = Q_reg;

endmodule

module binary_counter (
  input clk,
  input reset,
  output reg [1:0] count
);

  reg [1:0] next_count;

  always @(posedge clk) begin
    if (reset) begin
      count <= 2'b00;
    end else begin
      count <= next_count;
    end
  end

  always @(*) begin
    case (count)
      2'b00: next_count = 2'b01;
      2'b01: next_count = 2'b10;
      2'b10: next_count = 2'b11;
      2'b11: next_count = 2'b00;
    endcase
  end

endmodule

module light_control_block (
  input enable,
  input [7:0] brightness,
  input [7:0] in,
  output out
);

  // Analog-to-Digital Converter (ADC) module to convert the analog input to digital
  // Assumes 8-bit resolution for simplicity
  reg [7:0] adc_out;
  always @ (posedge clk) begin
    if (enable) begin
      adc_out <= in;
    end
  end

  // Pulse-Width Modulation (PWM) module to control the brightness of the light source
  // Assumes a 50% duty cycle for simplicity
  reg [7:0] pwm_out;
  always @ (posedge clk) begin
    if (enable) begin
      pwm_out <= (adc_out > brightness) ? 8'hFF : 8'h00;
    end else begin
      pwm_out <= 8'h00;
    end
  end

  // Assign the PWM output to the module output
  assign out = pwm_out;

endmodule

module usb_tx(
    input rst_n,
    input clk_48,

    output tx_en,
    output tx_j,
    output tx_se0,

    input transmit,
    input[7:0] data,
    input update_crc16,
    input send_crc16,
    output data_strobe
    );

reg[1:0] tx_clock;
wire bit_strobe = tx_clock == 2'b00;
always @(posedge clk_48 or negedge rst_n) begin
    if (!rst_n) begin
        tx_clock <= 2'b00;
    end else begin
        tx_clock <= tx_clock + 1'b1;
    end
end

wire bit_stuff;
wire tx_strobe = bit_strobe && !bit_stuff;

reg[2:0] state;
localparam
    st_idle = 3'b000,
    st_sync = 3'b101,
    st_run  = 3'b001,
    st_eop1 = 3'b010,
    st_eop2 = 3'b011,
    st_eop3 = 3'b100,
    st_crc1 = 3'b110,
    st_crc2 = 3'b111;

assign tx_en = (state != st_idle);

reg[8:0] tx_data;
reg crc_enabled;

wire dump_crc = state == st_crc1 || state == st_crc2;
wire crc_out;
wire d = dump_crc? !crc_out: tx_data[0];
wire se0 = !bit_stuff && (state == st_eop1 || state == st_eop2);

wire tx_data_empty = (tx_data[8:2] == 1'b0);
assign data_strobe = transmit && tx_data_empty && tx_strobe;

always @(posedge clk_48 or negedge rst_n) begin
    if (!rst_n) begin
        state <= st_idle;
    end else if (tx_strobe) begin
        case (state)
            st_idle: begin
                if (transmit)
                    state <= st_run;
            end
            st_sync: begin
                if (tx_data_empty)
                    state <= st_run;
            end
            st_run: begin
                if (tx_data_empty && !transmit) begin
                    if (send_crc16)
                        state <= st_crc1;
                    else
                        state <= st_eop1;
                end
            end
            st_crc1: begin
                if (tx_data_empty)
                    state <= st_crc2;
            end
            st_crc2: begin
                if (tx_data_empty)
                    state <= st_eop1;
            end
            st_eop1: begin
                state <= st_eop2;
            end
            st_eop2: begin
                state <= st_eop3;
            end
            st_eop3: begin
                state <= st_idle;
            end
        endcase
    end
end

always @(posedge clk_48) begin
    if (tx_strobe) begin
        if (!tx_en) begin
            tx_data <= 9'b110000000; // starting with J, go through KJKJKJKK
            crc_enabled <= 1'b0;
        end else if (tx_data_empty) begin
            tx_data <= { 1'b1, data };
            crc_enabled <= update_crc16;
        end else begin
            tx_data <= { 1'b0, tx_data[8:1] };
        end
    end
end

reg[2:0] bit_stuff_counter;
assign bit_stuff = bit_stuff_counter == 3'd6;
always @(posedge clk_48 or negedge rst_n) begin
    if (!rst_n) begin
        bit_stuff_counter <= 1'b0;
    end else if (bit_strobe) begin
        if (state == st_idle || !d || bit_stuff || se0)
            bit_stuff_counter <= 1'b0;
        else
            bit_stuff_counter <= bit_stuff_counter + 1'b1;
    end
end

reg last_j;
wire j = state == st_idle || state == st_eop3? 1'b1: ((bit_stuff || !d)? !last_j: last_j);
always @(posedge clk_48) begin
    if (bit_strobe)
        last_j <= tx_en? j: 1'b1;
end

assign tx_j = j;
assign tx_se0 = se0;

usb_crc16 tx_crc(
    .rst_n(rst_n && state != st_idle),
    .clk(clk_48),
    .clken(tx_strobe && (dump_crc || crc_enabled)),
    .d(d),
    .dump(dump_crc),
    .out(crc_out),
    .valid()
    );

endmodule

