    reg [65:0] tosend_reg;
    reg [65:0] tosend_en_reg;
    reg [6:0] bit_count;
    reg [6:0] transmit_count;
    reg [6:0] receive_count;

    assign mdio = (bit_count <= 32) ? tosend[bit_count] : 1'bz;

    always @(posedge mdc) begin
        if (!reset_n) begin
            tosend_reg <= 0;
            tosend_en_reg <= 0;
            bit_count <= 0;
            transmit_count <= 0;
            receive_count <= 0;
        end else begin
            tosend_reg <= tosend;
            tosend_en_reg <= tosend_en;
            bit_count <= (bit_count == 65) ? 0 : bit_count + 1;
            if (tosend_en_reg[bit_count]) begin
                transmit_count <= (transmit_count == 63) ? 0 : transmit_count + 1;
                mdio <= tosend_reg[bit_count];
            end else begin
                mdio <= 1'bz;
            end
            receive_count <= (receive_count == 63) ? 0 : receive_count + 1;
