module pio (
  input [2:0] address,
  input chipselect,
  input clk,
  input [31:0] in_port,
  input reset_n,
  input write_n,
  input [31:0] writedata,
  output irq,
  output [31:0] out_port,
  output [31:0] readdata
);

  wire clk_en;
  wire [31:0] data_in;
  reg [31:0] data_out;
  wire irq;
  reg [31:0] irq_mask;
  wire [31:0] out_port;
  wire [31:0] read_mux_out;
  reg [31:0] readdata;
  wire wr_strobe;

  assign clk_en = 1;

  assign read_mux_out = ({32 {(address == 0)}} & data_in) |
                        ({32 {(address == 2)}} & irq_mask);

  always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
      readdata <= 0;
    end else if (clk_en) begin
      readdata <= {32'b0 | read_mux_out};
    end
  end

  assign wr_strobe = chipselect && !write_n;

  always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
      data_out <= 0;
    end else if (clk_en) begin
      if (wr_strobe) begin
        case (address)
          0: data_out <= writedata[31:0];
          4: data_out <= {data_out[31:0], writedata[31:0]};
          5: data_out <= data_out & ~writedata[31:0];
          default: data_out <= data_out;
        endcase
      end
    end
  end

  assign out_port = data_out;
  assign data_in = in_port;

  always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
      irq_mask <= 0;
    end else if (wr_strobe && (address == 2)) begin
      irq_mask <= writedata[31:0];
    end
  end

  assign irq = |(data_in & irq_mask);

endmodule

module memory_testing_block (
  input [n-1:0] addr,
  input [m-1:0] data,
  output ok
);

parameter n = 4; // number of address signals
parameter m = 8; // number of data signals

// Define expected data values for each address
reg [m-1:0] expected_data [2**n-1:0];

// Generate address and data signals
reg [n-1:0] cur_addr = 0;
reg [m-1:0] cur_data = 0;
always @(posedge clk) begin
  cur_addr <= cur_addr + 1;
  cur_data <= cur_data + 1;
end

// Read data from memory module and compare to expected data
always @(posedge clk) begin
  if (data == expected_data[addr]) begin
    ok <= 1;
  end else begin
    ok <= 0;
  end
end

// Generate all possible address signals and test memory module
integer i;
initial begin
  for (i = 0; i < 2**n; i = i + 1) begin
    cur_addr <= i;
    expected_data[i] <= cur_data;
    #10;
  end
end

endmodule

module bitwise_OR_decoder (
    input [3:0] a,
    input [3:0] b,
    output reg [3:0] out,
    input A,
    input B,
    input C,
    input D,
    output reg [15:0] Y
);

    wire [15:0] decoder_out;
    wire [3:0] or_out;

    decoder_4to16 decoder(
        .A(A),
        .B(B),
        .C(C),
        .D(D),
        .Y(decoder_out)
    );

    bitwise_OR or_module(
        .a(a),
        .b(b),
        .out(or_out)
    );

    always @* begin
        case(decoder_out)
            16'b0000000000000001: out = or_out[0];
            16'b0000000000000010: out = or_out[1];
            16'b0000000000000100: out = or_out[2];
            16'b0000000000001000: out = or_out[3];
            16'b0000000000010000: out = or_out[4];
            16'b0000000000100000: out = or_out[5];
            16'b0000000001000000: out = or_out[6];
            16'b0000000010000000: out = or_out[7];
            16'b0000000100000000: out = or_out[8];
            16'b0000001000000000: out = or_out[9];
            16'b0000010000000000: out = or_out[10];
            16'b0000100000000000: out = or_out[11];
            16'b0001000000000000: out = or_out[12];
            16'b0010000000000000: out = or_out[13];
            16'b0100000000000000: out = or_out[14];
            16'b1000000000000000: out = or_out[15];
            default: out = 4'b0000;
        endcase
    end

    assign Y = ~decoder_out;

endmodule

module decoder_4to16 (
    input A,
    input B,
    input C,
    input D,
    output reg [15:0] Y
);

    always @* begin
        Y = 16'b1111111111111111;
        if(A == 1'b0) Y[0] = 1'b0;
        if(B == 1'b0) Y[1] = 1'b0;
        if(C == 1'b0) Y[2] = 1'b0;
        if(D == 1'b0) Y[3] = 1'b0;
    end

endmodule

