module top_module (
    input clk,
    input reset,
    input [7:0] in,
    output reg led1,
    output reg led2,
    output reg led3
);

reg [7:0] in_reg;
reg [2:0] priority;
reg [2:0] edge_detect;

always @(posedge clk) begin
    if (reset) begin
        in_reg <= 0;
        priority <= 0;
        edge_detect <= 0;
    end else begin
        in_reg <= in;
        edge_detect <= {in_reg[7] ^ in_reg[6], in_reg[6] ^ in_reg[5], in_reg[5] ^ in_reg[4]};
        if (edge_detect[2]) begin
            priority <= 3'b100;
        end else if (edge_detect[1]) begin
            priority <= 3'b010;
        end else if (edge_detect[0]) begin
            priority <= 3'b001;
        end else begin
            priority <= 0;
        end
    end
end

always @(posedge clk) begin
    if (reset) begin
        led1 <= 0;
        led2 <= 0;
        led3 <= 0;
    end else begin
        case (priority)
            3'b100: begin
                led1 <= 1;
                led2 <= 0;
                led3 <= 0;
            end
            3'b010: begin
                led1 <= 0;
                led2 <= 1;
                led3 <= 0;
            end
            3'b001: begin
                led1 <= 0;
                led2 <= 0;
                led3 <= 1;
            end
            default: begin
                led1 <= 0;
                led2 <= 0;
                led3 <= 0;
            end
        endcase
    end
end

endmodule

module parity (
    input [7:0] D,
    output reg P
);

reg [3:0] count1;
reg [3:0] count2;
reg [3:0] count3;
reg [3:0] count4;

wire [3:0] sum1;
wire [3:0] sum2;
wire [3:0] sum3;

assign sum1 = count1 + count2;
assign sum2 = count3 + count4;
assign sum3 = sum1 + sum2;

always @ (posedge clk) begin
    count1 <= D[0] + D[1] + D[2] + D[3];
    count2 <= D[4] + D[5] + D[6] + D[7];
    count3 <= sum1[0] + sum1[1] + sum1[2] + sum1[3];
    count4 <= sum2[0] + sum2[1] + sum2[2] + sum2[3];
    P <= ~sum3[0];
end

endmodule

module fsm_control  #(parameter width=10)(
	input                  clk,
	input                  rst,
	input                  dump_memory,
	// cpu control
	output reg             cpu_rst,
	// memory control
	output     [width-1:0] fsm_addr,
	output reg             fsm_wr,
	// UART wires
	input                  uart_received,
	input                  uart_tx_done,
	output reg             uart_tx_wr,
	output reg             uart_tx_memory,
	// LED information
	output reg [7:0]       led
);	

  reg [      1:0]  rst_cnt; // this is used to delay the memory writing by one clock, and make it last for two clocks.
  reg              prog_done,
                   prog_start,
                   dump_start,
                   dump_done,
                   addr_sel;

  reg [width-1:0]  fsm_wr_addr,
                   fsm_rd_addr;

  always @(negedge clk or posedge rst ) begin : addr_selection
    if( rst )
      addr_sel <= 1'b0;
    else begin
      if( prog_start ) addr_sel <= 1'b1;
      if( prog_done  ) addr_sel <= 1'b0;
    end
  end

  assign fsm_addr = addr_sel ? fsm_wr_addr : fsm_rd_addr;

  always @(negedge clk or posedge rst ) begin : reset_release
    if( rst ) begin
      cpu_rst        <=  1'b1;    
      uart_tx_memory <= 1'b0;
    end
    else begin
      if (prog_done  | dump_done ) cpu_rst <= 1'b0;
      if (prog_start | dump_start) cpu_rst <= 1'b1;
      if ( dump_start ) 
        uart_tx_memory <= 1'b1;
      else if( dump_done ) 
        uart_tx_memory <= 1'b0;
    end
  end

  always @(posedge clk or posedge rst ) begin : fsm_write
    if( rst ) begin    
      fsm_wr <= 1'b0;
    end
    else begin
      if( ^rst_cnt && cpu_rst )
        fsm_wr <= 1'b1;
      else
        fsm_wr <= 1'b0;
    end
  end

  reg [23:0] led_cnt;

  always @(posedge clk or posedge rst ) begin : led_game
    if( rst ) begin  
      led_cnt <= 23'd0;
      led     <= 1'b1;
    end
    else begin
      led_cnt <= led_cnt + 1'b1;
      if( !led_cnt && cpu_rst )
        if( prog_start ) 
          led <= { led[6:0], led[7] };
        else
          led <= { led[0], led[7:1] };
    end
  end


  always @(posedge clk or posedge rst ) begin : data_input
    if( rst ) begin    
  `ifdef SIM_SKIPPROG
      fsm_wr_addr     <=  {(width){1'b1}};
      rst_cnt      <=  2'b0;
      prog_done    <=  1'b1;
      prog_start   <=  1'b0;    
  `else
      fsm_wr_addr     <=  {(width){1'b1}};
      rst_cnt      <=  2'b0;
      prog_done    <=  1'b0;
      prog_start   <=  1'b0;    
  `endif
    end
    else begin
        /* writes the incoming data until the memory is full.
            it does not admit reload. it will handle the control
            to the CPU after loading the memory. */            
        if( prog_done || (prog_start && (&fsm_wr_addr)  && (&rst_cnt))  ) begin    
          prog_start <= 1'b0;
          prog_done  <= 1'b1;
        end
        else begin
          if( uart_received ) begin
            fsm_wr_addr   <= fsm_wr_addr + 1'b1;
            rst_cnt    <= 2'b0;
            prog_start <= 1'b1;          
          end
          else if( rst_cnt != 2'b11 ) rst_cnt <= rst_cnt + 1'b1;
        end
    end
  end

  always @(posedge clk or posedge rst ) begin : data_output
    if( rst ) begin    
      fsm_rd_addr <= {(width){1'b0}};
      dump_start  <= 1'b0;
      dump_done   <= 1'b0;
      uart_tx_wr  <= 1'b0;
    end
    else begin
      if( dump_memory ) begin
        fsm_rd_addr <= {(width){1'b0}};
        dump_start  <= 1'b1;
        dump_done   <= 1'b0;
        uart_tx_wr  <= 1'b1;
      end
      else
      if( uart_tx_done && dump_start && !dump_done ) begin
        if( &fsm_rd_addr ) begin
          dump_start <= 1'b0;
          dump_done  <= 1'b1;
        end
        else begin
          fsm_rd_addr <= fsm_rd_addr + 1'b1;
          uart_tx_wr  <= 1'b1;
        end
      end
      else uart_tx_wr <= 1'b0;    

    end
  end 

endmodule

module bitwise_or_logical_not(
    input [2:0] a,
    input [2:0] b,
    output [2:0] out_or_bitwise,
    output out_or_logical,
    output [5:0] out_not
);

    // Bitwise OR using XOR and inverter gates
    assign out_or_bitwise = a ^ b;

    // Logical OR using AND and OR gates
    assign out_or_logical = (a & b) | (a | b);

    // NOT using inverter gates
    assign out_not = ~{a, b};

endmodule

