    output [2:0] out_or_bitwise_2,
    output out_or_logical,
    output [5:0] out_not,
    output [2:0] final_output
);

    // Instantiate two instances of the bitwise_or_logical_not module
    bitwise_or_logical_not module_1(a, b, out_or_bitwise_1, out_or_logical, out_not);
    bitwise_or_logical_not module_2(out_or_bitwise_1, out_or_bitwise_2, final_output, out_or_logical, out_not);

    // Bitwise OR between the two individual bitwise OR outputs
    assign out_or_bitwise_2 = out_or_bitwise_1 | final_output;

endmodule

