module adder(
    input wire [7:0] in1,
    input wire [7:0] in2,
    input wire clk,
    input wire rst,
    input wire en,
    output wire [7:0] final_out
);

    reg [7:0] sum;

    always @(posedge clk) begin
        if (rst) begin
            sum <= 8'b0;
        end else if (en) begin
            sum <= in1 + in2;
        end
    end

    assign final_out = sum;

endmodule

module top_module( 
    input wire clk,
    input wire rst,
    input wire en,
    input wire [15:0] in,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo,
    output wire [7:0] final_out
);

    wire [7:0] adder_in1;
    wire [7:0] adder_in2;

    byte_splitter splitter(
        .in(in),
        .out_hi(out_hi),
        .out_lo(out_lo)
    );

    assign adder_in1 = out_hi;
    assign adder_in2 = out_lo;

    adder add(
        .in1(adder_in1),
        .in2(adder_in2),
        .clk(clk),
        .rst(rst),
        .en(en),
        .final_out(final_out)
    );

endmodule

module audio_interface(
    input avs_s1_clk, avs_s1_reset, avs_s1_address, avs_s1_read, avs_s1_write,
    output reg [15:0] avs_s1_readdata,
    input avs_s1_export_BCLK, avs_s1_export_DACLRC, avs_s1_export_ADCLRC,
    output reg avs_s1_export_DACDAT, input avs_s1_export_ADCDAT
);

// Constant Declarations
localparam DAC_LFIFO_ADDR = 3'b000;
localparam DAC_RFIFO_ADDR = 3'b001;
localparam ADC_LFIFO_ADDR = 3'b010;
localparam ADC_RFIFO_ADDR = 3'b011;
localparam CMD_ADDR = 3'b100;
localparam STATUS_ADDR = 3'b101;

// Internal wires and registers Declarations
reg [15:0] reg_readdata;
reg fifo_clear;

wire dacfifo_full;
reg dacfifo_write;
reg [31:0] dacfifo_writedata;

wire adcfifo_empty;
reg adcfifo_read;
wire [31:0] adcfifo_readdata;
reg [31:0] data32_from_adcfifo;
reg [31:0] data32_from_adcfifo_2;

// fifo clear
always @(posedge avs_s1_clk) begin
    if (avs_s1_reset) fifo_clear <= 1'b0;
    else if (avs_s1_write && (avs_s1_address == CMD_ADDR)) fifo_clear <= avs_s1_writedata[0];
    else if (fifo_clear) fifo_clear <= 1'b0;
end

// write audio data(left&right) to dac-fifo
always @(posedge avs_s1_clk) begin
    if (avs_s1_reset || fifo_clear) begin
        dacfifo_write <= 1'b0;
    end
    else if (avs_s1_write && (avs_s1_address == DAC_LFIFO_ADDR)) begin
        dacfifo_writedata[31:16] <= avs_s1_writedata;
        dacfifo_write <= 1'b0;
    end
    else if (avs_s1_write && (avs_s1_address == DAC_RFIFO_ADDR)) begin
        dacfifo_writedata[15:0] <= avs_s1_writedata;
        dacfifo_write <= 1'b1;
    end
    else dacfifo_write <= 1'b0;
end

// response data to avalon-mm
always @(negedge avs_s1_clk) begin
    if (avs_s1_reset || fifo_clear) data32_from_adcfifo = 0;
    else if (avs_s1_read && (avs_s1_address == STATUS_ADDR)) reg_readdata <= {adcfifo_empty, dacfifo_full};
    else if (avs_s1_read && (avs_s1_address == ADC_LFIFO_ADDR)) reg_readdata <= data32_from_adcfifo[31:16];
    else if (avs_s1_read && (avs_s1_address == ADC_RFIFO_ADDR)) begin
        reg_readdata <= data32_from_adcfifo[15:0];
        data32_from_adcfifo <= data32_from_adcfifo_2;
    end
end

// read audio data from adc fifo
always @(negedge avs_s1_clk) begin
    if (avs_s1_reset) begin
        adcfifo_read <= 1'b0;
        data32_from_adcfifo_2 <= 0;
    end
    else if ((avs_s1_address == ADC_LFIFO_ADDR) & avs_s1_read & ~adcfifo_empty) begin
        adcfifo_read <= 1'b1;
    end
    else if (adcfifo_read) begin
        data32_from_adcfifo_2 = adcfifo_readdata;
        adcfifo_read <= 1'b0;
    end
end

// Combinational logic
assign avs_s1_readdata = reg_readdata;

