module matrix_multiplier (
    input [7:0] matrix_a [0:15],
    input [7:0] matrix_b [0:15],
    output reg [15:0] matrix_out [0:15],
    output reg valid
);

reg [7:0] row_a [0:3];
reg [7:0] col_b [0:3];
reg [15:0] product [0:3][0:3];

integer i, j, k;

always @(*) begin
    for (i = 0; i < 4; i = i + 1) begin
        for (j = 0; j < 4; j = j + 1) begin
            product[i][j] = 0;
            for (k = 0; k < 4; k = k + 1) begin
                row_a[k] = matrix_a[i*4 + k];
                col_b[k] = matrix_b[k*4 + j];
                product[i][j] = product[i][j] + row_a[k] * col_b[k];
            end
        end
    end
end

always @(*) begin
    for (i = 0; i < 16; i = i + 1) begin
        matrix_out[i] = product[i/4][i%4];
    end
    valid = 1;
end

endmodule

