module Comparator_Less(Data_A, Data_B, less);
  input [8:0] Data_A;
  input [8:0] Data_B;
  output less;

  wire [8:0] A_inv;
  wire [8:0] B_inv;
  wire [8:0] A_xor_B;
  wire [8:0] A_and_B;
  wire [8:0] A_less_B;

  // Invert the inputs
  assign A_inv = ~Data_A;
  assign B_inv = ~Data_B;

  // Compute the XOR and AND of the inverted inputs
  assign A_xor_B = A_inv ^ B_inv;
  assign A_and_B = A_inv & B_inv;

  // Determine if A is less than B
  assign A_less_B = ((A_xor_B & Data_B) | A_and_B) == 0;

  // Output the result
  assign less = A_less_B[8];

endmodule

module adder_4bit_carry(
  input [3:0] a,
  input [3:0] b,
  input cin,
  output [3:0] sum,
  output cout
);

wire [3:0] carry;
wire [3:0] xor1;
wire [3:0] xor2;

// Full adder for bit 0
full_adder fa0(
  .a(a[0]),
  .b(b[0]),
  .cin(cin),
  .sum(sum[0]),
  .cout(carry[0])
);

// Full adder for bit 1
full_adder fa1(
  .a(a[1]),
  .b(b[1]),
  .cin(carry[0]),
  .sum(sum[1]),
  .cout(carry[1])
);

// Full adder for bit 2
full_adder fa2(
  .a(a[2]),
  .b(b[2]),
  .cin(carry[1]),
  .sum(sum[2]),
  .cout(carry[2])
);

// Full adder for bit 3
full_adder fa3(
  .a(a[3]),
  .b(b[3]),
  .cin(carry[2]),
  .sum(sum[3]),
  .cout(cout)
);

// XOR gates to calculate carry bit
xor x1(.a(a[0]), .b(b[0]), .out(xor1[0]));
xor x2(.a(xor1[0]), .b(cin), .out(carry[0]));
xor x3(.a(a[1]), .b(b[1]), .out(xor1[1]));
xor x4(.a(xor1[1]), .b(carry[0]), .out(carry[1]));
xor x5(.a(a[2]), .b(b[2]), .out(xor1[2]));
xor x6(.a(xor1[2]), .b(carry[1]), .out(carry[2]));
xor x7(.a(a[3]), .b(b[3]), .out(xor1[3]));
xor x8(.a(xor1[3]), .b(carry[2]), .out(cout));

endmodule

module full_adder(
  input a,
  input b,
  input cin,
  output sum,
  output cout
);

wire s1;
wire s2;

// XOR gate to calculate sum bit
xor x1(.a(a), .b(b), .out(s1));

// XOR gate to calculate carry-out bit
xor x2(.a(s1), .b(cin), .out(sum));

// AND gate to calculate carry-out bit
and a1(.a(a), .b(b), .out(s2));
and a2(.a(s1), .b(cin), .out(cout));

// OR gate to combine carry-out bits
or o1(.a(s2), .b(cout), .out(cout));

endmodule

module EX_MEM_Seg(
input Clk,
input stall,
input flush,

input [31:0] Branch_addr,PC_add,
input [2:0] Condition,
input Branch,
input [2:0]PC_write,
input [3:0]Mem_Byte_Write,Rd_Write_Byte_en,
input MemWBSrc,OverflowEn,
input [31:0] MemData,WBData,
input Less,Zero,Overflow,
input [4:0]Rd,


output reg [31:0] Branch_addr_out,PC_add_out,
output reg [2:0] Condition_out,
output reg Branch_out,
output reg [2:0]PC_write_out,
output reg [3:0]Mem_Byte_Write_out,Rd_Write_Byte_en_out,
output reg MemWBSrc_out,OverflowEn_out,
output reg [31:0] MemData_out,WBData_out,
output reg Less_out,Zero_out,Overflow_out,
output reg [4:0]Rd_out
);

always@(posedge Clk)
begin
if(flush)
begin
    // reset all outputs
	OverflowEn_out <= 1'b0;
	Branch_addr_out <= 32'b0;
	PC_add_out <= 32'b0;
	Condition_out <= 3'b0;
	Branch_out <= 1'b0;
	PC_write_out =3'b0;
	Mem_Byte_Write_out <= 4'b0;
	Rd_Write_Byte_en_out <= 4'b0;
	MemWBSrc_out <= 1'b0;
	MemData_out <= 32'h0;
	WBData_out <= 32'b0;
	Less_out <= 1'b0;
	Zero_out <= 1'b0;
	Overflow_out  <= 1'b0;
	Rd_out <= 5'b0;
end
else if(~stall)
begin
    // update outputs with input values
	OverflowEn_out <= OverflowEn;
	Branch_addr_out <= Branch_addr;
	PC_add_out <= PC_add;
	Condition_out <= Condition;
	Branch_out <= Branch;
	PC_write_out = PC_write;
	Mem_Byte_Write_out <= Mem_Byte_Write;
	Rd_Write_Byte_en_out <= Rd_Write_Byte_en;
	MemWBSrc_out <= MemWBSrc;
	MemData_out <= MemData;
	WBData_out <= WBData;
	Less_out <= Less;
	Zero_out <= Zero;
	Overflow_out  <= Overflow;
	Rd_out <= Rd;
end
end
endmodule

