module binary_search (
    input clk,
    input reset,
    input start,
    input [31:0] array [15:0],
    input [31:0] target,
    output reg done,
    output reg [3:0] index
);

    // State machine states
    localparam IDLE = 2'b00;
    localparam SEARCH = 2'b01;
    localparam FOUND = 2'b10;

    reg [1:0] state;
    reg [3:0] low;
    reg [3:0] high;
    reg [3:0] mid;

    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            low <= 0;
            high <= 15;
            mid <= 7;
            done <= 0;
            index <= -1;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        state <= SEARCH;
                    end
                end
                SEARCH: begin
                    if (array[mid] == target) begin
                        state <= FOUND;
                    end else if (low >= high) begin
                        state <= FOUND;
                    end else if (array[mid] < target) begin
                        low <= mid + 1;
                        mid <= (low + high) / 2;
                    end else begin
                        high <= mid - 1;
                        mid <= (low + high) / 2;
                    end
                end
                FOUND: begin
                    done <= 1;
                    index <= (array[mid] == target) ? mid : -1;
                end
            endcase
        end
    end
endmodule

