module fifo_async_103x16_fifo_generator_ramfifo
   (dout,
    empty,
    full,
    prog_full,
    wr_en,
    rd_clk,
    wr_clk,
    rst,
    din,
    rd_en);
  output [15:0] dout;
  output empty;
  output full;
  output prog_full;
  input wr_en;
  input rd_clk;
  input wr_clk;
  input rst;
  input [15:0] din;
  input rd_en;

  // Internal signals
  wire [102:0] mem [0:102];
  reg [6:0] wr_ptr;
  reg [6:0] rd_ptr;
  reg [6:0] next_wr_ptr;
  reg [6:0] next_rd_ptr;
  reg [6:0] almost_full_threshold;
  reg [6:0] count;
  wire [6:0] next_count;
  wire [6:0] almost_full_count;
  wire [6:0] next_almost_full_count;
  wire [15:0] out_data;
  wire empty;
  wire full;
  wire prog_full;

  // Write pointer logic
  always @(posedge wr_clk) begin
    if (wr_en && !full) begin
      mem[wr_ptr] <= din;
      next_wr_ptr <= wr_ptr + 1;
      almost_full_count <= count + 1;
    end
  end

  // Read pointer logic
  always @(posedge rd_clk) begin
    if (rd_en && !empty) begin
      out_data <= mem[rd_ptr];
      next_rd_ptr <= rd_ptr + 1;
    end
  end

  // Count logic
  always @(*) begin
    next_count = count;
    next_almost_full_count = almost_full_count;
    if (wr_en && !full) begin
      next_count = count + 1;
      next_almost_full_count = almost_full_count + 1;
    end
    if (rd_en && !empty) begin
      next_count = count - 1;
      next_almost_full_count = almost_full_count - 1;
    end
  end

  // Almost full threshold logic
  always @(*) begin
    almost_full_threshold = 98;
    if (count < 98) begin
      almost_full_threshold = 95;
    end
  end

  // Full and empty logic
  assign empty = (count == 0);
  assign full = (count == 103);

  // Almost full logic
  assign prog_full = (next_almost_full_count >= almost_full_threshold);

  // Pointer wraparound logic
  always @(*) begin
    if (next_wr_ptr == 103) begin
      next_wr_ptr = 0;
    end
    if (next_rd_ptr == 103) begin
      next_rd_ptr = 0;
    end
  end

  // Assign outputs
  assign dout = out_data;
  assign wr_ptr = next_wr_ptr;
  assign rd_ptr = next_rd_ptr;
  assign count = next_count;
  assign almost_full_count = next_almost_full_count;

endmodule

