module assert_time_cover (
    input clk, reset_n, start_event, window, reset_on_new_start, window_close,
    output basic_cover, corner_cover, reset
);
    parameter OVL_COVER_BASIC_ON = 1;
    parameter OVL_COVER_CORNER_ON = 1;

    localparam IDLE = 2'b00, WINDOW_OPEN = 2'b01, EVENT_DETECT = 2'b10;
    reg [1:0] state, next_state;

    reg [1:0] window_cnt, event_cnt;
    reg basic_cover_reg, corner_cover_reg;

    assign basic_cover = basic_cover_reg;
    assign corner_cover = corner_cover_reg;
    assign reset = ~reset_n;

    always @(posedge clk or negedge reset_n) begin
        if (~reset_n) begin
            state <= IDLE;
            window_cnt <= 0;
            event_cnt <= 0;
            basic_cover_reg <= 0;
            corner_cover_reg <= 0;
        end else begin
            state <= next_state;
            window_cnt <= (window_close) ? 0 : window_cnt + 1;
            event_cnt <= (start_event) ? 0 : event_cnt + 1;
            basic_cover_reg <= 0;
            corner_cover_reg <= 0;
        end
    end

    always @* begin
        next_state = state;
        case (state)
            IDLE: begin
                if (start_event) begin
                    next_state = EVENT_DETECT;
                end
            end
            WINDOW_OPEN: begin
                if (event_cnt >= window_cnt) begin
                    basic_cover_reg = 1;
                    next_state = IDLE;
                end else if (window_close) begin
                    next_state = IDLE;
                end else if (start_event) begin
                    next_state = EVENT_DETECT;
                end
            end
            EVENT_DETECT: begin
                if (window_cnt == 0) begin
                    next_state = IDLE;
                end else if (event_cnt == 0) begin
                    next_state = WINDOW_OPEN;
                end else if (window_cnt <= event_cnt) begin
                    basic_cover_reg = 1;
                    next_state = IDLE;
                end else if (OVL_COVER_CORNER_ON) begin
                    if (event_cnt == 1 && window_cnt == 1) begin
                        corner_cover_reg = 1;
                        next_state = IDLE;
                    end else if (event_cnt == 1 && window_cnt > 1) begin
                        corner_cover_reg = 1;
                        next_state = WINDOW_OPEN;
                    end else if (event_cnt > 1 && window_cnt == 1) begin
                        corner_cover_reg = 1;
                        next_state = IDLE;
                    end else if (event_cnt > 1 && window_cnt > 1) begin
                        next_state = WINDOW_OPEN;
                    end
                end else begin
                    next_state = WINDOW_OPEN;
                end
            end
        endcase
    end
endmodule

