module recv_credit_flow_ctrl
    (
     input        CLK,
     input        RST,
     input [2:0]  CONFIG_MAX_READ_REQUEST_SIZE, // Maximum read payload: 000=128B, 001=256B, 010=512B, 011=1024B, 100=2048B, 101=4096B
     input [11:0] CONFIG_MAX_CPL_DATA, // Receive credit limit for data
     input [7:0]  CONFIG_MAX_CPL_HDR, // Receive credit limit for headers
     input        CONFIG_CPL_BOUNDARY_SEL, // Read completion boundary (0=64 bytes, 1=128 bytes)w
     input        RX_ENG_RD_DONE, // Read completed
     input        TX_ENG_RD_REQ_SENT, // Read completion request issued
     output       RXBUF_SPACE_AVAIL // High if enough read completion credits exist to make a read completion request
     );

    reg           rCreditAvail=0;
    reg           rCplDAvail=0;
    reg           rCplHAvail=0;
    reg [12:0]    rMaxRecv=0;
    reg [11:0]    rCplDAmt=0;
    reg [7:0]     rCplHAmt=0;
    reg [11:0]    rCplD=0;
    reg [7:0]     rCplH=0;

    reg           rInfHCred; // TODO: Altera uses sideband signals (would have been more convenient, thanks Xilinx!)
    reg           rInfDCred; // TODO: Altera uses sideband signals (would have been more convenient, thanks Xilinx!)


    assign RXBUF_SPACE_AVAIL = rCreditAvail;

    // Determine the completions required for a max read completion request.
    always @(posedge CLK) begin
        rInfHCred <= (CONFIG_MAX_CPL_HDR == 0);
        rInfDCred <= (CONFIG_MAX_CPL_DATA == 0);
        rMaxRecv <= #1 (13'd128<<CONFIG_MAX_READ_REQUEST_SIZE);
        rCplHAmt <= #1 (rMaxRecv>>({2'b11, CONFIG_CPL_BOUNDARY_SEL}));
        rCplDAmt <= #1 (rMaxRecv>>4);
        rCplHAvail <= #1 (rCplH <= CONFIG_MAX_CPL_HDR);
        rCplDAvail <= #1 (rCplD <= CONFIG_MAX_CPL_DATA);
        rCreditAvail <= #1 ((rCplHAvail|rInfHCred) & (rCplDAvail | rInfDCred));
    end

    // Count the number of outstanding read completion requests.
    always @ (posedge CLK) begin
        if (RST) begin
            rCplH <= #1 0;
            rCplD <= #1 0;
        end
        else if (RX_ENG_RD_DONE & TX_ENG_RD_REQ_SENT) begin
            rCplH <= #1 rCplH;
            rCplD <= #1 rCplD;
        end
        else if (TX_ENG_RD_REQ_SENT) begin
            rCplH <= #1 rCplH + rCplHAmt;
            rCplD <= #1 rCplD + rCplDAmt;
        end
        else if (RX_ENG_RD_DONE) begin
            rCplH <= #1 rCplH - rCplHAmt;
            rCplD <= #1 rCplD - rCplDAmt;
        end
    end

endmodule

module add_sub (
    input [3:0] A,
    input [3:0] B,
    input SUBTRACT,
    output reg [3:0] SUM,
    output reg OVERFLOW
);

always @(*) begin
    if (SUBTRACT == 1) begin
        SUM <= A - B;
        if (A < B) begin
            OVERFLOW <= 1;
        end else begin
            OVERFLOW <= 0;
        end
    end else begin
        SUM <= A + B;
        if (SUM > 15) begin
            OVERFLOW <= 1;
        end else begin
            OVERFLOW <= 0;
        end
    end
end

endmodule

module vending_machine(
    input clk,
    input rst,
    input nickel,
    input dime,
    input quarter,
    input select_A,
    input select_B,
    input select_C,
    output dispense,
    output change_10,
    output change_25,
    output product_A,
    output product_B,
    output product_C
);

reg [7:0] total_amount;
reg [1:0] product_selected;
reg [1:0] change_returned;
wire [7:0] cost = 50;

assign dispense = (total_amount >= cost) & (select_A | select_B | select_C);
assign change_10 = (change_returned == 2'b10);
assign change_25 = (change_returned == 2'b01);
assign product_A = (product_selected == 2'b01);
assign product_B = (product_selected == 2'b10);
assign product_C = (product_selected == 2'b11);

always @(posedge clk) begin
    if (rst) begin
        total_amount <= 0;
        product_selected <= 0;
        change_returned <= 0;
    end else begin
        if (nickel) begin
            total_amount <= total_amount + 5;
            change_returned <= 2'b00;
        end
        if (dime) begin
            total_amount <= total_amount + 10;
            change_returned <= 2'b00;
        end
        if (quarter) begin
            total_amount <= total_amount + 25;
            change_returned <= 2'b00;
        end
        if (select_A) begin
            if (total_amount >= cost) begin
                product_selected <= 2'b01;
                total_amount <= total_amount - cost;
                change_returned <= total_amount;
            end else begin
                product_selected <= 0;
                total_amount <= 0;
                change_returned <= 0;
            end
        end
        if (select_B) begin
            if (total_amount >= cost) begin
                product_selected <= 2'b10;
                total_amount <= total_amount - cost;
                change_returned <= total_amount;
            end else begin
                product_selected <= 0;
                total_amount <= 0;
                change_returned <= 0;
            end
        end
        if (select_C) begin
            if (total_amount >= cost) begin
                product_selected <= 2'b11;
                total_amount <= total_amount - cost;
                change_returned <= total_amount;
            end else begin
                product_selected <= 0;
                total_amount <= 0;
                change_returned <= 0;
            end
        end
    end
end

endmodule

