module signed_adder (
    input signed [3:0] A, B, // 4-bit signed magnitude numbers
    output reg signed [3:0] out, // 4-bit signed magnitude output
    output overflow // overflow detection output
);

    always @(*) begin
        out = A + B;
        if (out > 7 || out < -8) // check for overflow
            overflow = 1;
        else
            overflow = 0;
    end

endmodule

module barrel_shifter (
    input [7:0] in, // 8-bit input
    input [2:0] shift, // 3-bit shift value
    output reg [7:0] out // 8-bit output
);

    always @(*) begin
        case (shift)
            3'b000: out = in; // no shift
            3'b001: out = in >> 1; // right shift by 1
            3'b010: out = in >> 2; // right shift by 2
            3'b011: out = in >> 3; // right shift by 3
            3'b100: out = in << 1; // left shift by 1
            3'b101: out = in << 2; // left shift by 2
            3'b110: out = in << 3; // left shift by 3
            3'b111: out = 8'b0; // clear output
        endcase
    end

endmodule

module control_logic (
    input signed [3:0] A, B, // 4-bit signed magnitude numbers
    input [2:0] shift, // 3-bit shift value for the barrel shifter
    input select, // Select input to choose between adder and barrel shifter
    output reg [7:0] out // 8-bit output from the selected module's output after shifting
);

    wire signed [3:0] adder_out;
    wire overflow;

    signed_adder adder(.A(A), .B(B), .out(adder_out), .overflow(overflow));
    barrel_shifter shifter(.in(adder_out), .shift(shift), .out(out));

    always @(*) begin
        if (select == 1'b0) // choose adder
            out = {4'b0000, adder_out};
        else // choose barrel shifter
            out = shifter.out;
    end

endmodule

module top_module (
    input signed [3:0] A, B, // 4-bit signed magnitude numbers
    input [2:0] shift, // 3-bit shift value for the barrel shifter
    input select, // Select input to choose between adder and barrel shifter
    output reg [7:0] out // 8-bit output from the selected module's output after shifting
);

    control_logic control(.A(A), .B(B), .shift(shift), .select(select), .out(out));

endmodule

module syncfifo
  #(
    // Address width (must be 5 => 32-deep FIFO)
    parameter AW = 5,
    // Data width
    parameter DW = 16
    )
   (
    input                clk,
    input                reset,
    input [DW-1:0]       wdata,
    input                wen,
    input                ren,
    output wire [DW-1:0] rdata,
    output reg           empty,
    output reg           full
    );

   reg [AW-1:0]          waddr;
   reg [AW-1:0]          raddr;
   reg [AW-1:0]          count;

   always @ ( posedge clk ) begin
      if( reset ) begin

         waddr <= 'd0;
         raddr <= 'd0;
         count <= 'd0;
         empty <= 1'b1;
         full  <= 1'b0;

      end else begin

         if( wen & ren ) begin

            waddr <= waddr + 'd1;
            raddr <= raddr + 'd1;

         end else if( wen ) begin

            waddr <= waddr + 'd1;
            count <= count + 'd1;
            empty <= 1'b0;
            if( & count )
              full <= 1'b1;

         end else if( ren ) begin

            raddr <= raddr + 'd1;
            count <= count - 'd1;
            full <= 1'b0;
            if( count == 'd1 )
              empty <= 1'b1;

         end
      end // else: !if( reset )
   end // always @ ( posedge clk )

   genvar               dn;

   generate for(dn=0; dn<DW; dn=dn+1)
     begin : genbits
        RAM32X1D RAM32X1D_inst
          (
           .DPO(rdata[dn] ),   // Read-only 1-bit data output
           .SPO(),            // Rw/ 1-bit data output
           .A0(waddr[0]),     // Rw/ address[0] input bit
           .A1(waddr[1]),     // Rw/ address[1] input bit
           .A2(waddr[2]),     // Rw/ address[2] input bit
           .A3(waddr[3]),     // Rw/ address[3] input bit
           .A4(waddr[4]),     // Rw/ address[4] input bit
           .D(wdata[dn]),     // Write 1-bit data input
           .DPRA0(raddr[0]),  // Read-only address[0] input bit
           .DPRA1(raddr[1]),  // Read-only address[1] input bit
           .DPRA2(raddr[2]),  // Read-only address[2] input bit
           .DPRA3(raddr[3]),  // Read-only address[3] input bit
           .DPRA4(raddr[4]),  // Read-only address[4] input bit
           .WCLK(clk),        // Write clock input
           .WE(wen)           // Write enable input
           );
     end
   endgenerate

endmodule

module alu (a, b, op, result);
  input signed [12:0] a, b;
  input [4:0] op;
  output signed [12:0] result;

  always @(*) begin
    case (op)
      5'b00000: result = a + b;
      5'b00001: result = a - b;
      5'b00010: result = a & b;
      5'b00011: result = a | b;
      5'b00100: result = a ^ b;
      5'b00101: result = (b[2:0] > 0) ? (a << b[2:0]) : a;
      5'b00110: result = (b[2:0] > 0) ? (a >> b[2:0]) : a;
      default: result = 0;
    endcase
  end
endmodule

module calculator(A, B, OP, R, F, clk);

  input [3:0] A, B;
  input [1:0] OP;
  output reg [3:0] R;
  output reg F;
  input clk;

  wire [7:0] product;
  wire [3:0] quotient;
  wire [3:0] remainder;

  adder add(R, A, B, clk);
  subtractor sub(R, A, B, clk);
  multiplier mul(product, A, B, clk);
  divider div(quotient, remainder, A, B, clk);

  always @(posedge clk) begin
    case(OP)
      2'b00: R <= add.sum;
      2'b01: R <= sub.difference;
      2'b10: R <= product[7:0];
      2'b11: if(B == 0) begin
               R <= 4'b0000;
               F <= 1;
             end else begin
               R <= quotient;
               F <= 0;
             end
    endcase
  end

endmodule

module adder(sum, a, b, clk);
  output reg [3:0] sum;
  input [3:0] a, b;
  input clk;

  always @(posedge clk) begin
    sum <= a + b;
  end
endmodule

module subtractor(difference, a, b, clk);
  output reg [3:0] difference;
  input [3:0] a, b;
  input clk;

  always @(posedge clk) begin
    difference <= a - b;
  end
endmodule

module multiplier(product, a, b, clk);
  output reg [7:0] product;
  input [3:0] a, b;
  input clk;

  always @(posedge clk) begin
    product <= a * b;
  end
endmodule

module divider(quotient, remainder, a, b, clk);
  output reg [3:0] quotient, remainder;
  input [3:0] a, b;
  input clk;

  always @(posedge clk) begin
    quotient <= a / b;
    remainder <= a % b;
  end
endmodule

module binary_counter (
    input clk,
    input reset,      // Synchronous active-high reset
    output reg [3:0] q);

    // Define states
    parameter [1:0] S0 = 2'b00;
    parameter [1:0] S1 = 2'b01;
    parameter [1:0] S2 = 2'b10;
    parameter [1:0] S3 = 2'b11;

    // Define state register and next state logic
    reg [1:0] state, next_state;
    always @ (posedge clk, posedge reset) begin
        if (reset) begin
            state <= S0;
        end else begin
            state <= next_state;
        end
    end

    // Define output logic
    always @ (state) begin
        case (state)
            S0: q <= 4'b0000;
            S1: q <= 4'b0001;
            S2: q <= 4'b0010;
            S3: q <= 4'b0011;
        endcase
    end

    // Define next state logic
    always @ (state) begin
        case (state)
            S0: next_state <= S1;
            S1: next_state <= S2;
            S2: next_state <= S3;
            S3: next_state <= S0;
        endcase
    end

endmodule

