    input reset,
    input [2:0] a,
    input [2:0] b,
    input sel_mux_1,
    input sel_mux_2,
    input sel_or,
    output reg [2:0] sum,
    output reg carry_out
);

reg [2:0] or_out;
reg [2:0] inv_a;
reg [2:0] inv_b;
reg [1:0] mux_out;

mux_2to1 mux_inst(
    .data_in({a,b}),
    .sel({sel_mux_1,sel_mux_2}),
    .out(mux_out)
);

