    .a(mux_out),
    .b({inv_a,inv_b}),
    .or_out(or_out),
    .inv_a(inv_a),
    .inv_b(inv_b)
);

always @(posedge clk) begin
    if(reset) begin
        sum <= 3'b000;
        carry_out <= 1'b0;
    end else begin
        if(sel_or) begin
            sum <= or_out;
            carry_out <= or_out[2] & or_out[1] | or_out[2] & or_out[0] | or_out[1] & or_out[0];
        end else begin
            sum <= mux_out;
            carry_out <= mux_out[2] & mux_out[1] | mux_out[2] & mux_out[0] | mux_out[1] & mux_out[0];
        end
    end
end

endmodule

