module adder_subtractor(input [3:0] A, B, input Cin, Sub, output [3:0] Sum, Cout);

    wire [3:0] B_comp; // complement of B
    wire [3:0] temp_sum; // temporary sum

    assign B_comp = ~B + 1; // 2's complement of B

    // Adder-Subtractor logic
    assign temp_sum = (Sub == 1) ? A + B_comp + Cin : A + B + Cin;

    // Output sum and carry
    assign Sum = temp_sum[3:0];
    assign Cout = temp_sum[4];

endmodule

module four_to_one (
    input a,
    input b,
    input c,
    input d,
    output y
);

    wire a_and_b, a_and_c, a_and_d, b_and_c, b_and_d, c_and_d;
    wire three_or_four_ones, two_ones, one_one;

    assign a_and_b = a & b;
    assign a_and_c = a & c;
    assign a_and_d = a & d;
    assign b_and_c = b & c;
    assign b_and_d = b & d;
    assign c_and_d = c & d;

    assign three_or_four_ones = (a & b & c) | (a & b & d) | (a & c & d) | (b & c & d) | (a & b & c & d);
    assign two_ones = (a & b & ~c & ~d) | (a & c & ~b & ~d) | (a & d & ~b & ~c) | (b & c & ~a & ~d) | (b & d & ~a & ~c) | (c & d & ~a & ~b);
    assign one_one = (a & ~b & ~c & ~d) | (~a & b & ~c & ~d) | (~a & ~b & c & ~d) | (~a & ~b & ~c & d);

    assign y = three_or_four_ones | one_one;
    assign y = y & ~two_ones;

endmodule

module async_fifo_read #(
    parameter                  FWFTEN    = 1,  // 0 : disable
    parameter                  ADDRWIDTH = 6,
    parameter   [ADDRWIDTH:0]  FIFODEPTH = 44,
    parameter   [ADDRWIDTH:0]  MINBIN2   = 0,
    parameter   [ADDRWIDTH:0]  MAXBIN2   = 7
) (
    input  wire                    r_clk    ,
    input  wire                    r_rst_n  ,
    input  wire                    r_en     ,
    input  wire [ADDRWIDTH:0]      w2r_ptr  ,
    output reg  [ADDRWIDTH-1:0]    rbin     ,
    output reg  [ADDRWIDTH:0]      rptr     ,
    output                         inc      ,
    output reg                     r_valid  ,
    output reg  [ADDRWIDTH:0]      r_counter,
    output reg                     r_error
);

//
wire    zero = (r_counter == {(ADDRWIDTH+1){1'b0}} );
// FWFT (First Word Fall Through)
wire    fwft = FWFTEN ? (!r_valid && !zero) : 1'b0;
//
assign  inc  = (r_en && !zero) || fwft;

//---------------------------------------------------------------
// "rbin2" is double the amount of "rbin"
//---------------------------------------------------------------
reg  [ADDRWIDTH:0]  rbin2;
wire [ADDRWIDTH:0]  rbnext = (rbin2>=MINBIN2 && rbin2<MAXBIN2) ?
                             (rbin2 + 1'b1) : MINBIN2;
//
always @(posedge r_clk or negedge r_rst_n)
    if (!r_rst_n)
        rbin2 <= MINBIN2;
    else if (inc)
        rbin2 <= rbnext;

//---------------------------------------------------------------
// memory address
//---------------------------------------------------------------
always @(posedge r_clk or negedge r_rst_n)
    if (!r_rst_n)
        rbin <= {ADDRWIDTH{1'b0}};
    else if (inc)
        rbin <= rbnext[ADDRWIDTH] ? rbnext[ADDRWIDTH-1:0] :
                    (rbnext[ADDRWIDTH-1:0] - MINBIN2[ADDRWIDTH-1:0]);

//---------------------------------------------------------------
// GRAY pointer
//---------------------------------------------------------------
// binary-to-gray conversion
wire [ADDRWIDTH:0]  rptr_gray = {1'b0,rbnext[ADDRWIDTH:1]} ^ rbnext;

always @(posedge r_clk or negedge r_rst_n)
    if (!r_rst_n)
        rptr <= (MINBIN2>>1) ^ MINBIN2;
    else if (inc)
        rptr <= rptr_gray;

//---------------------------------------------------------------
// from other-side
//---------------------------------------------------------------
reg [ADDRWIDTH:0] w2r_bin;

always @(w2r_ptr)
begin: GrayToBin
    integer i;
    for (i=ADDRWIDTH; i>=0; i=i-1)
        w2r_bin[i] = ^(w2r_ptr>>i);
end

//---------------------------------------------------------------
// output signals
//---------------------------------------------------------------
wire [ADDRWIDTH:0] distance = ( (w2r_bin >= rbin2) ?
                                (w2r_bin  - rbin2) :
                                (w2r_bin  - rbin2 - (MINBIN2<<1) )
                              ) - inc;

// "r_counter" is precise.
always @(posedge r_clk or negedge r_rst_n)
    if (!r_rst_n)
        r_counter <= {(ADDRWIDTH+1){1'b0}};
    else
        r_counter <= distance;


// "r_valid" is alignment with "dout" because of FWFT
always @(posedge r_clk or negedge r_rst_n)
    if (!r_rst_n)
        r_valid <= 1'b0;
    else if (r_en || fwft)
        r_valid <= !zero;

//
always @(posedge r_clk or negedge r_rst_n)
    if (!r_rst_n)
        r_error <= 1'b0;
    else
        r_error <= (r_counter > FIFODEPTH);

//
endmodule

