module top_module (
    input clk,
    input rst_n,
    input [15:0] in,
    input write_en,
    input [2:0] write_addr,
    input [3:0] write_data,
    input read_en,
    input [2:0] read_addr,
    output reg [3:0] read_data,
    output reg [7:0] out_hi,
    output reg [7:0] out_lo
);
    wire [7:0] barrel_out_lo;
    wire [7:0] barrel_out_hi;
    wire [3:0] ram_out;

    barrel_shifter barrel_inst (
        .in(in),
        .out_lo(barrel_out_lo),
        .out_hi(barrel_out_hi)
    );

    true_dual_port_ram ram_inst (
        .clk(clk),
        .rst_n(rst_n),
        .write_addr(write_addr),
        .write_data(write_data),
        .write_en(write_en),
        .read_addr(read_addr),
        .read_en(read_en),
        .read_data(ram_out)
    );

    functional_module func_inst (
        .in1(barrel_out_lo),
        .in2(ram_out),
        .out(read_data)
    );

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            out_hi <= 8'b0;
            out_lo <= 8'b0;
        end else begin
            out_hi <= barrel_out_hi;
            out_lo <= barrel_out_lo;
        end
    end
endmodule

module binary_up_down_counter (
    input clk,
    input reset,
    output reg [3:0] counter
);

    reg [4:0] count;

    always @(posedge clk) begin
        if (reset) begin
            count <= 0;
        end else begin
            if (count == 4'b1111) begin
                count <= count - 1;
            end else if (count == 0) begin
                count <= count + 1;
            end else begin
                if (count[3] == 1) begin
                    count <= count - 1;
                end else begin
                    count <= count + 1;
                end
            end
        end
    end

    assign counter = count[3:0];

endmodule

module binary_to_gray_converter (
    input [2:0] binary,
    output reg [2:0] gray
);

    always @(*) begin
        gray[2] = binary[2];
        gray[1] = binary[2] ^ binary[1];
        gray[0] = binary[1] ^ binary[0];
    end

endmodule

