    w128,
    w17281,
    w32,
    w17249;

  assign w1 = i_data0;
  assign w128 = w1 << 7;
  assign w16 = w1 << 4;
  assign w17 = w1 + w16;
  assign w17249 = w17281 - w32;
  assign w17281 = w17409 - w128;
  assign w17408 = w17 << 10;
  assign w17409 = w1 + w17408;
  assign w32 = w1 << 5;

  assign o_data0 = w17249;

  //multiplier_block area estimate = 6612.88314944412;
endmodule

module tea_top(
    input clock,
    input [255:0] plain,
    output [255:0] cipher,
    output done
);

    reg [3:0] state = 0;
    reg [255:0] out;
    wire [63:0] mod_in;
    wire mod_in_ready;
    wire mod_in_ack;
    wire [63:0] mod_out;
    wire mod_out_ready;
    wire mod_out_ack;

    tea_encrypt mod (
        .clock(clock),
        .in(mod_in),
        .in_ready(mod_in_ready),
        .in_ack(mod_in_ack),
        .out(mod_out),
        .out_ready(mod_out_ready),
        .out_ack(mod_out_ack)
    );

    always @* begin
        case (state)
            0: mod_in = plain[255:192];
            2: mod_in = plain[191:128];
            4: mod_in = plain[127:64];
            6: mod_in = plain[63:0];
            default: mod_in = 0;
        endcase
    end

    assign mod_out_ack = (state == 1 || state == 3 || state == 5 || state == 7);
    assign mod_in_ready = (state == 0 || state == 2 || state == 4 || state == 6);

    assign done = (state == 8);
    assign cipher = out;

    always @(posedge clock) begin
        case (state)
            0: begin
                if (mod_in_ack) state <= 1;
            end
            1: begin
                if (mod_out_ready) state <= 2;
                out[255:192] <= mod_out;
            end
            2: begin
                if (mod_in_ack) state <= 3;
            end
            3: begin
                if (mod_out_ready) state <= 4;
                out[191:128] <= mod_out;
            end
            4: begin
                if (mod_in_ack) state <= 5;
            end
            5: begin
                if (mod_out_ready) state <= 6;
                out[127:64] <= mod_out;
            end
            6: begin
                if (mod_in_ack) state <= 7;
            end
            7: begin
                if (mod_out_ready) state <= 8;
                out[63:0] <= mod_out;
            end
        endcase
    end
endmodule

module top_module (
    input [3:0] A,
    input [3:0] B,
    input [2:0] OP,
    input [1:0] SHIFT,
    output reg [3:0] q
);

    wire [3:0] alu_out;
    wire [3:0] barrel_out;
    wire [3:0] func_out;

    alu_4bit alu_inst (
        .A(A),
        .B(B),
        .OP(OP),
        .q(alu_out)
    );

    barrel_shifter barrel_inst (
        .data(alu_out),
        .SHIFT(SHIFT),
        .q(barrel_out)
    );

    always @(*) begin
        case (OP)
            3'b000: func_out = alu_out + barrel_out;
            3'b001: func_out = alu_out - barrel_out;
            3'b010: func_out = alu_out & barrel_out;
            default: func_out = 4'b0;
        endcase
        q = func_out;
    end

endmodule

module delayed_buffer (
    input D,
    input CLK,
    input DE,
    output Q,
    output Q_N
);

    // Local signals
    wire buf_Q;
    wire mux_out;

    // 2-to-1 multiplexer with unit delay
    sky130_fd_sc_ls__udp_mux_2to1 #(`UNIT_DELAY) mux_2to1 (mux_out, buf_Q, D, DE);

    // D flip-flop with unit delay
    sky130_fd_sc_ls__udp_dff$P #(`UNIT_DELAY) dff0 (buf_Q, mux_out, CLK);

    // Buffer with no delay
    buf buf0 (Q, buf_Q);

    // Inverter with no delay
    not not0 (Q_N, buf_Q);

endmodule

