module functional_module (
    input [7:0] edge_detector_out,
    input [2:0] bitwise_or_out,
    input [2:0] logical_or_out,
    input select,
    output [7:0] out
);

reg [7:0] and_result;

always @(*) begin
    if (select) begin
        and_result = edge_detector_out & {3'b0, bitwise_or_out};
    end else begin
        and_result = edge_detector_out & {3'b0, logical_or_out};
    end
end

assign out = ~(|and_result);

endmodule

module top_module (
    input clk,
    input reset,
    input [7:0] in,
    input [2:0] a,
    input [2:0] b,
    input select,
    output [7:0] out_combined
);

wire [7:0] edge_detector_out;
wire [2:0] bitwise_or_out;
wire [2:0] logical_or_out;
wire [2:0] not_a;
wire [2:0] not_b;

edge_detector ed (
    .clk(clk),
    .reset(reset),
    .in(in),
    .out(edge_detector_out)
);

bitwise_logical_or bo (
    .a(a),
    .b(b),
    .bitwise_or(bitwise_or_out),
    .logical_or(logical_or_out),
    .not_a(not_a),
    .not_b(not_b)
);

functional_module fm (
    .edge_detector_out(edge_detector_out),
    .bitwise_or_out(bitwise_or_out),
    .logical_or_out(logical_or_out),
    .select(select),
    .out(out_combined)
);

endmodule

module clock_buffer_driver (
  input clk_in,
  input delay,
  output clk_out,
  output clk_out_delay
);

  reg delayed_clk;
  wire buffered_clk;

  // Delay element
  always @(posedge clk_in)
    #delay delayed_clk <= clk_in;

  // Buffer element
  assign buffered_clk = delayed_clk | clk_in;
  assign clk_out = buffered_clk;
  assign clk_out_delay = delayed_clk;

endmodule

module Computer_System_Pushbuttons (
  input [1:0] address,
  input chipselect,
  input clk,
  input [3:0] in_port,
  input reset_n,
  input write_n,
  input [31:0] writedata,
  output irq,
  output [31:0] readdata
);

  wire [3:0] data_in;
  reg [3:0] irq_mask;
  reg [3:0] edge_capture;
  wire edge_capture_wr_strobe;
  wire [3:0] edge_detect;
  wire [3:0] read_mux_out;
  reg [31:0] readdata_reg;

  assign read_mux_out = ({4 {(address == 2'b00)}} & data_in) |
                        ({4 {(address == 2'b10)}} & irq_mask) |
                        ({4 {(address == 2'b11)}} & edge_capture);

  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      readdata_reg <= 0;
    end
    else if (write_n == 0 && chipselect && address == 2'b11) begin
      irq_mask <= writedata[3:0];
    end
    else begin
      readdata_reg <= {32'b0, read_mux_out};
    end
  end

  assign data_in = in_port;

  assign irq = |(edge_capture & irq_mask);

  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      edge_capture <= 0;
    end
    else if (edge_capture_wr_strobe && writedata[0]) begin
      edge_capture[0] <= 0;
    end
    else if (edge_detect[0]) begin
      edge_capture[0] <= 1;
    end
  end

  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      edge_capture <= 0;
    end
    else if (edge_capture_wr_strobe && writedata[1]) begin
      edge_capture[1] <= 0;
    end
    else if (edge_detect[1]) begin
      edge_capture[1] <= 1;
    end
  end

  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      edge_capture <= 0;
    end
    else if (edge_capture_wr_strobe && writedata[2]) begin
      edge_capture[2] <= 0;
    end
    else if (edge_detect[2]) begin
      edge_capture[2] <= 1;
    end
  end

  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      edge_capture <= 0;
    end
    else if (edge_capture_wr_strobe && writedata[3]) begin
      edge_capture[3] <= 0;
    end
    else if (edge_detect[3]) begin
      edge_capture[3] <= 1;
    end
  end

  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      edge_detect <= 0;
    end
    else begin
      edge_detect <= ~data_in & {4{data_in}};
    end
  end

endmodule

