module binary_counter (
  input clk,
  input reset,
  input count_en,
  output reg [3:0] count_val
);

  reg [3:0] next_val;

  always @(posedge clk) begin
    if (reset) begin
      count_val <= 4'b0000;
    end
    else if (count_en) begin
      case (count_val)
        4'b0000: next_val <= 4'b0001;
        4'b0001: next_val <= 4'b0010;
        4'b0010: next_val <= 4'b0011;
        4'b0011: next_val <= 4'b0100;
        4'b0100: next_val <= 4'b0101;
        4'b0101: next_val <= 4'b0110;
        4'b0110: next_val <= 4'b0111;
        4'b0111: next_val <= 4'b1000;
        4'b1000: next_val <= 4'b1001;
        4'b1001: next_val <= 4'b1010;
        4'b1010: next_val <= 4'b1011;
        4'b1011: next_val <= 4'b1100;
        4'b1100: next_val <= 4'b1101;
        4'b1101: next_val <= 4'b1110;
        4'b1110: next_val <= 4'b1111;
        4'b1111: next_val <= 4'b0000;
      endcase
      count_val <= next_val;
    end
  end

endmodule

module bcd_converter(clk, wr, data_in, data_out);

	// Parameter Definitions

	parameter width = 'd16; // Data Width (Signed) (Maximum 16)

	// Inputs

	input wire clk /* Clock (Full Speed) */, wr /* Write Request Notification */;
	input wire [width-1:0] data_in /* Data Input Port */;

	// Outputs

	output wire [20:0] data_out /* Data Output Port */;

	// Internal

	reg sign /* Represents the sign of the number being currently converted */;
	reg [1:0] stclk /* State Clock, keeps track of the current conversion stage */;
	reg [4:0] shst /* Shift State, keeps track of the number of shifts completed */;
	reg [3:0] five, four, three, two, one; // These represent five BCD digits, four bits each.
	reg [width-1:0] data_in_buf /* Data Input Buffer */;
	reg [20:0] data_out_buf /* Data Output Buffer */;

	// Initialization

	initial begin
		stclk [1:0] <= 2'b0;
	end

	// Output Logic

	assign data_out = data_out_buf; // Data Output

	// Conversion Block ('Shift and Add Three'/'Double Dabble' algorithm. )

	always@(posedge clk) begin
		case(stclk) // synthesis parallel_case
			2'b00: begin
				if(!wr) begin
					stclk [1:0] <= 2'b01;
					data_in_buf [width-1:0] <= data_in [width-1:0]; // Current Input buffered in.
					sign <= 1'b0;
					shst [4:0] <= 5'b0;
					five [3:0] <= 4'b0;
					four [3:0] <= 4'b0;
					three [3:0] <= 4'b0;
					two [3:0] <= 4'b0;
					one [3:0] <= 4'b0;
				end
			end
			2'b01: begin
				stclk [1:0] <= 2'b10;
				if(data_in_buf[width-1]) begin
					sign <= 1'b1;
					data_in_buf [width-1:0] <= ~data_in_buf [width-1:0] + 1'b1; // Inverts and adds one if the number is negative to convert it back from two's complement.
				end
			end
			2'b10: begin
				stclk [1:0] <= 2'b11;
				shst [4:0] <= shst + 1'b1;
				{five, four, three, two, one, data_in_buf} <= {five, four, three, two, one, data_in_buf} << 1; // Shift Left
			end
			2'b11: begin
				if(shst [4:0] == (width)) begin
					stclk [1:0] <= 2'b00;
					data_out_buf [20:0] <= {sign, five, four, three, two, one};
				end else begin
					stclk [1:0] <= 2'b10;

					// Add three to those BCD registers whose current value is greater than or equal to five.

					if(five [3:0] >= 4'b0101) five [3:0] <= five [3:0] + 2'b11;
					if(four [3:0] >= 4'b0101) four [3:0] <= four [3:0] + 2'b11;
					if(three [3:0] >= 4'b0101) three [3:0] <= three [3:0] + 2'b11;
					if(two [3:0] >= 4'b0101) two [3:0] <= two [3:0] + 2'b11;
					if(one [3:0] >= 4'b0101) one [3:0] <= one [3:0] + 2'b11;
				end
			end
		endcase
	end

endmodule

module top_module (
    input wire [15:0] in,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo,
    output parity,
    output [7:0] sum
);

    wire [7:0] in_hi;
    wire [7:0] in_lo;
    wire [7:0] out_hi_shifted;
    wire [7:0] out_lo_shifted;
    wire [7:0] sum_temp;

    // Split input into two 8-bit outputs
    split_16_to_8 split_input(
        .in(in),
        .out_hi(in_hi),
        .out_lo(in_lo),
        .out_hi_shifted(out_hi_shifted),
        .out_lo_shifted(out_lo_shifted)
    );

    // Compute parity bit for 8-bit byte
    parity_8bit compute_parity(
        .in(in_lo),
        .out(parity)
    );

    // Compute sum of two 8-bit outputs
    add_8bit compute_sum(
        .in_a(out_hi_shifted),
        .in_b(in_hi),
        .out(sum_temp)
    );

    // Shift sum output to the right by 1 bit
    shift_right_8 shift_sum(
        .in(sum_temp),
        .out(sum)
    );

    // Assign outputs
    assign out_hi = out_hi_shifted;
    assign out_lo = in_lo;

endmodule

// Split 16-bit input into two 8-bit outputs using logic gates and shift registers
module split_16_to_8 (
    input wire [15:0] in,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo,
    output wire [7:0] out_hi_shifted,
    output wire [7:0] out_lo_shifted
);

    wire [7:0] in_shifted;

    // Shift input to the right by 8 bits
    shift_right_16 shift_input(
        .in(in),
        .out(in_shifted)
    );

    // Split input into two 8-bit outputs
    assign out_hi = in_shifted[15:8];
    assign out_lo = in[7:0];

    // Shift output hi and output lo to the right by 1 bit
    shift_right_8 shift_out_hi(
        .in(out_hi),
        .out(out_hi_shifted)
    );
    shift_right_8 shift_out_lo(
        .in(out_lo),
        .out(out_lo_shifted)
    );

endmodule

// Compute parity bit for an 8-bit byte using combinational logic architecture
module parity_8bit (
    input wire [7:0] in,
    output wire parity
);

    assign parity = ^in;

endmodule

// Compute sum of two 8-bit inputs using combinational logic architecture
module add_8bit (
    input wire [7:0] in_a,
    input wire [7:0] in_b,
    output wire [7:0] out
);

    assign out = in_a + in_b;

endmodule

// Shift 8-bit input to the right by 1 bit using shift register
module shift_right_8 (
    input wire [7:0] in,
    output wire [7:0] out
);

    reg [7:0] shift_reg;

    always @(*) begin
        shift_reg[7:1] = in[6:0];
        shift_reg[0] = 1'b0;
    end

    assign out = shift_reg;

endmodule

// Shift 16-bit input to the right by 8 bits using shift register
module shift_right_16 (
    input wire [15:0] in,
    output wire [15:0] out
);

    reg [15:0] shift_reg;

    always @(*) begin
        shift_reg[15:8] = in[7:0];
        shift_reg[7:0] = 8'b0;
    end

    assign out = shift_reg;

endmodule

module hdmi_out
(
  input hdmi_clk,
  input hdmi_vs,
  input hdmi_de,
  input [31:0] hdmi_data
);

  integer fm1 = 0;
  reg [7:0] vsc = 8'h0;
  reg vse = 1;

  initial begin
    fm1 = $fopen("out_0.ppm", "wb");
  end

  always @(posedge hdmi_clk) begin
    vse <= hdmi_vs;

    if ((hdmi_vs == 1'b0) && (vse == 1'b1)) begin
      $fclose(fm1);
      $stop;
    end

    if ((hdmi_vs == 1'b1) && (vse == 1'b0)) begin
      $fclose(fm1);
      fm1 = $fopen({"out_", vsc[5:0] / 10 + 8'h30, vsc[5:0] % 10 + 8'h30, ".ppm"}, "wb");
      $display("out%d.ppm saved", vsc);
      $fwrite(fm1, "P6%c64 64%c255\n", 10, 10);
      vsc <= vsc + 1;
    end else begin
      if (hdmi_de) begin
        $fwrite(fm1, "%c", {hdmi_data[23:16]});
        $fwrite(fm1, "%c", {hdmi_data[15:8]});
        $fwrite(fm1, "%c", {hdmi_data[7:0]});
      end
    end
  end

endmodule

module EnergyHarvestingBlock (
  input [n-1:0] in,
  output out
);

parameter n = 4; // number of input signals
parameter m = 1; // number of output signals

reg [n-1:0] in_reg; // input register
reg [7:0] count; // counter for energy conversion process
reg [7:0] energy; // energy accumulator
reg [7:0] voltage; // output voltage

// energy conversion process
always @ (posedge clk) begin
  if (count == 0) begin
    energy <= 0;
    for (i = 0; i < n; i = i + 1) begin
      energy <= energy + in_reg[i];
    end
  end
  count <= count + 1;
end

// output voltage calculation
always @ (posedge clk) begin
  if (count == 255) begin
    voltage <= energy / n;
    if (voltage > 255) begin
      voltage <= 255;
    end
    out <= voltage;
  end
end

endmodule

module digital_circuit (
    input D,
    output Q,
    input RESET_B,
    input GATE
);

    reg Q_reg;

    always @(posedge GATE) begin
        if (RESET_B == 0) begin
            Q_reg <= 0;
        end else begin
            Q_reg <= D;
        end
    end

    assign Q = Q_reg;

endmodule

module top_module( 
    input wire [7:0] in_hi,
    input wire [7:0] in_lo,
    output wire [15:0] out,
    output wire parity_bit );

    wire [7:0] in_hi_reg;
    wire [7:0] in_lo_reg;
    wire [15:0] out_reg;
    wire parity_bit_reg;

    // Pipeline stage 1
    reg [7:0] in_hi_pipe1;
    reg [7:0] in_lo_pipe1;
    always @(posedge clk) begin
        in_hi_pipe1 <= in_hi;
        in_lo_pipe1 <= in_lo;
    end

    // Pipeline stage 2
    reg [15:0] out_pipe2;
    reg parity_bit_pipe2;
    always @(posedge clk) begin
        in_hi_reg <= in_hi_pipe1;
        in_lo_reg <= in_lo_pipe1;
        out_pipe2 <= {in_hi_reg, in_lo_reg};
        parity_bit_pipe2 <= in_hi_reg ^ in_lo_reg;
    end

    // Pipeline stage 3
    always @(posedge clk) begin
        out_reg <= out_pipe2;
        parity_bit_reg <= parity_bit_pipe2;
    end

    assign out = out_reg;
    assign parity_bit = parity_bit_reg;

endmodule

module barrel_shifter (
    input [3:0] A,
    input [1:0] B,
    output reg [3:0] Q
);

always @(*) begin
    case(B)
        2'b00: Q = A;
        2'b01: Q = {A[0], A[3:1]};
        2'b10: Q = {A[1:0], A[3:2]};
        2'b11: Q = {A[2:0], A[3]};
    endcase
end

endmodule

module up_counter (
    input clk,
    input reset,
    output reg [2:0] Q
);

always @(posedge clk) begin
    if (reset) begin
        Q <= 3'b000;
    end else begin
        Q <= Q + 1;
        if (Q == 3'b111) begin
            Q <= 3'b000;
        end
    end
end

endmodule

module adder (
    input [3:0] A,
    input [3:0] B,
    output [7:0] Q
);

assign Q = A + B;

endmodule

