  if (!rst) begin
    shifted_data <= 4'b0;
  end else begin
    case(shift_amount)
      2'b00: shifted_data <= data_in;
      2'b01: shifted_data <= {data_in[2:0], 1'b0};
      2'b10: shifted_data <= {data_in[1:0], 2'b0};
      2'b11: shifted_data <= {data_in[0], 3'b0};
      default: shifted_data <= 4'b1;
    endcase
  end
end

assign data_out = shifted_data;

endmodule

module pipelined_logic(
    input [99:0] in,
    output out_and,
    output out_or,
    output out_xor
);

    wire [99:0] and_out, or_out, xor_out;
    wire [49:0] and_stage1_out, or_stage1_out, xor_stage1_out;
    wire [24:0] and_stage2_out, or_stage2_out, xor_stage2_out;
    wire [12:0] and_stage3_out, or_stage3_out, xor_stage3_out;
    wire [6:0] and_stage4_out, or_stage4_out, xor_stage4_out;
    wire [3:0] and_stage5_out, or_stage5_out, xor_stage5_out;
    wire [1:0] and_stage6_out, or_stage6_out, xor_stage6_out;

    // Stage 1
    and_stage1 and1(.in(in), .out(and_stage1_out));
    or_stage1 or1(.in(in), .out(or_stage1_out));
    xor_stage1 xor1(.in(in), .out(xor_stage1_out));

    // Stage 2
    and_stage2 and2(.in(and_stage1_out), .out(and_stage2_out));
    or_stage2 or2(.in(or_stage1_out), .out(or_stage2_out));
    xor_stage2 xor2(.in(xor_stage1_out), .out(xor_stage2_out));

    // Stage 3
    and_stage3 and3(.in(and_stage2_out), .out(and_stage3_out));
    or_stage3 or3(.in(or_stage2_out), .out(or_stage3_out));
    xor_stage3 xor3(.in(xor_stage2_out), .out(xor_stage3_out));

    // Stage 4
    and_stage4 and4(.in(and_stage3_out), .out(and_stage4_out));
    or_stage4 or4(.in(or_stage3_out), .out(or_stage4_out));
    xor_stage4 xor4(.in(xor_stage3_out), .out(xor_stage4_out));

    // Stage 5
    and_stage5 and5(.in(and_stage4_out), .out(and_stage5_out));
    or_stage5 or5(.in(or_stage4_out), .out(or_stage5_out));
    xor_stage5 xor5(.in(xor_stage4_out), .out(xor_stage5_out));

    // Stage 6
    and_stage6 and6(.in(and_stage5_out), .out(and_stage6_out));
    or_stage6 or6(.in(or_stage5_out), .out(or_stage6_out));
    xor_stage6 xor6(.in(xor_stage5_out), .out(xor_stage6_out));

    assign out_and = and_stage6_out[0];
    assign out_or = or_stage6_out[0];
    assign out_xor = xor_stage6_out[0];

endmodule

