always @(posedge clk or negedge reset) begin
    if (!reset) begin
        count <= 4'b0;
    end else if (load) begin
        count <= load_data;
    end else if (up_down) begin
        count <= count + 1;
    end else begin
        count <= count - 1;
    end
end

endmodule

