module axi_gpio_module (
  input  wire                   s_axi_aclk,
  input  wire                   s_axi_aresetn,
  input  wire                   s_axi_awvalid,
  input  wire [2:0]             s_axi_awaddr,
  input  wire                   s_axi_wvalid,
  input  wire [31:0]            s_axi_wdata,
  input  wire [3:0]             s_axi_wstrb,
  input  wire                   s_axi_bready,
  input  wire                   s_axi_arvalid,
  input  wire [2:0]             s_axi_araddr,
  input  wire                   s_axi_rready,
  input  wire [3:0]             gpio_io_t,
  input  wire                   gpio_xferAck_Reg,
  output wire                   s_axi_awready,
  output wire                   s_axi_wready,
  output wire                   s_axi_bvalid,
  output wire [1:0]             s_axi_bresp,
  output wire                   s_axi_arready,
  output wire                   s_axi_rvalid,
  output wire [31:0]            s_axi_rdata,
  output wire [3:0]             gpio2_io_t,
  output wire                   GPIO_xferAck_i
);

  reg [31:0] gpio_data_out_reg;
  reg [31:0] gpio_data_in_reg;
  reg [3:0]  gpio_oe_reg;

  always @(posedge s_axi_aclk) begin
    if (s_axi_aresetn == 1'b0) begin
      gpio_data_out_reg <= 0;
      gpio_data_in_reg <= 0;
      gpio_oe_reg <= 0;
    end else begin
      if (s_axi_awvalid && s_axi_wvalid) begin
        case(s_axi_awaddr[1:0])
          2'b00: gpio_data_out_reg[7:0] <= s_axi_wstrb[0] ? gpio_data_out_reg[7:0] : s_axi_wdata[7:0];
          2'b01: gpio_data_out_reg[15:8] <= s_axi_wstrb[1] ? gpio_data_out_reg[15:8] : s_axi_wdata[15:8];
          2'b10: gpio_data_out_reg[23:16] <= s_axi_wstrb[2] ? gpio_data_out_reg[23:16] : s_axi_wdata[23:16];
          2'b11: gpio_data_out_reg[31:24] <= s_axi_wstrb[3] ? gpio_data_out_reg[31:24] : s_axi_wdata[31:24];
        endcase
      end

      if (s_axi_arvalid && s_axi_rready) begin
        case(s_axi_araddr[1:0])
          2'b00: s_axi_rdata[7:0] <= gpio_data_in_reg[7:0];
          2'b01: s_axi_rdata[15:8] <= gpio_data_in_reg[15:8];
          2'b10: s_axi_rdata[23:16] <= gpio_data_in_reg[23:16];
          2'b11: s_axi_rdata[31:24] <= gpio_data_in_reg[31:24];
        endcase
      end

      gpio_data_in_reg <= gpio_io_t;

      if (gpio_xferAck_Reg) begin
        gpio_oe_reg <= gpio_oe_reg & ~gpio_data_out_reg | ~gpio_oe_reg & gpio_data_out_reg;
      end
    end
  end

  assign gpio2_io_t = gpio_data_out_reg;
  assign GPIO_xferAck_i = gpio_xferAck_Reg;

  assign s_axi_awready = 1'b1;
  assign s_axi_wready = 1'b1;

  always @(posedge s_axi_aclk) begin
    if (s_axi_aresetn == 1'b0) begin
      s_axi_bvalid <= 0;
      s_axi_bresp <= 2'b00;
    end else begin
      if (s_axi_awvalid && s_axi_wvalid && s_axi_bready) begin
        s_axi_bvalid <= 1'b1;
        s_axi_bresp <= 2'b00;
      end else if (s_axi_arvalid && s_axi_rready) begin
        s_axi_rvalid <= 1'b1;
      end

      if (s_axi_bvalid && s_axi_bready) begin
        s_axi_bvalid <= 1'b0;
      end else if (s_axi_rvalid && s_axi_rready) begin
        s_axi_rvalid <= 1'b0;
      end
    end
  end

endmodule

module one_shot_pulse_generator (
