  if (trigger) begin
    counter <= 0;
    pulse_state <= 1;
  end else if (pulse_state) begin
    counter <= counter + 1;
    if (counter >= pulse_duration) begin
      pulse_state <= 0;
    end
  end
end

assign pulse = pulse_state;

endmodule

