module video_fetcher(
    input RST_I,
    input CLK_I_25MHZ,
    input VSYNC_I,
    input VFEN_I,
    input RAM_ACK_I,
    input [15:0] RAM_DAT_I,
    output reg [12:0] RAM_ADR_O,
    output reg RAM_CYC_O,
    output reg RAM_STB_O,
    output reg [5:0] LB_ADR_O,
    output reg [15:0] LB_DAT_O,
    output reg LB_WE_O
);

    reg [12:0] bitmap_ptr;
    reg bitmap_fetch_in_progress;

    reg [12:0] n_bitmap_ptr;
    reg n_bitmap_fetch_in_progress;
    reg last_transfer;
    reg start_transfer;
    reg [5:0] fetch_counter;
    reg [5:0] n_fetch_counter;
    reg o_vfen;
    reg rst_fetch_ctr;
    reg inc_fetch_ctr;
    reg line_buffer_write;

    assign RAM_ADR_O = bitmap_ptr;
    assign RAM_CYC_O = bitmap_fetch_in_progress;
    assign RAM_STB_O = bitmap_fetch_in_progress;
    assign LB_ADR_O = fetch_counter;
    assign LB_WE_O = line_buffer_write;
    assign LB_DAT_O = RAM_DAT_I;

    always @(posedge CLK_I_25MHZ) begin
        bitmap_ptr <= n_bitmap_ptr;
        bitmap_fetch_in_progress <= n_bitmap_fetch_in_progress;
        fetch_counter <= n_fetch_counter;
        o_vfen <= VFEN_I;
    end

    always @(*) begin
        start_transfer <= VFEN_I & !o_vfen;
        last_transfer <= (fetch_counter == 40);
        rst_fetch_ctr <= (RST_I | last_transfer);
        line_buffer_write <= RAM_CYC_O & RAM_STB_O & RAM_ACK_I;
        inc_fetch_ctr <= (bitmap_fetch_in_progress & line_buffer_write);

        case({VSYNC_I, line_buffer_write})
            2'b10: n_bitmap_ptr <= bitmap_ptr;
            2'b11: n_bitmap_ptr <= bitmap_ptr + 1;
            default: n_bitmap_ptr <= 0;
        endcase

        case({rst_fetch_ctr, inc_fetch_ctr})
            2'b01: n_fetch_counter <= fetch_counter + 1;
            2'b10: n_fetch_counter <= 0;
            2'b11: n_fetch_counter <= 0;
            default: n_fetch_counter <= fetch_counter;
        endcase

        case({start_transfer, last_transfer})
            3'b01: n_bitmap_fetch_in_progress <= 0;
            3'b10: n_bitmap_fetch_in_progress <= !RST_I;
            default: n_bitmap_fetch_in_progress <= (RST_I) ? 0 : bitmap_fetch_in_progress;
        endcase
    end
endmodule

module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out
);

reg [9:0] acc;  // Accumulator register
reg [2:0] stage;  // Pipeline stage register

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        acc <= 10'd0;
        stage <= 3'd0;
        valid_b <= 1'b0;
        data_out <= 10'd0;
    end else begin
        case (stage)
            3'd0: begin  // Stage 0: Idle
                if (valid_a) begin
                    acc <= data_in;
                    stage <= 3'd1;
                end
            end
            3'd1: begin  // Stage 1: Accumulate
                if (valid_a) begin
                    acc <= acc + data_in;
                    stage <= 3'd2;
                end
            end
            3'd2: begin  // Stage 2: Accumulate
                if (valid_a) begin
                    acc <= acc + data_in;
                    stage <= 3'd3;
                end
            end
            3'd3: begin  // Stage 3: Output
                data_out <= acc;
                valid_b <= 1'b1;
                stage <= 3'd0;
            end
        endcase
    end
end

assign ready_a = (stage == 3'd0) ? 1'b1 : 1'b0;
assign valid_b = (stage == 3'd3) ? 1'b1 : 1'b0;

endmodule

module fifo1(
    input clk_i,
    input rst_i,
    input [g_width-1:0] data_i,
    input push_i,
    input pull_i,
    output [g_width-1:0] data_o,
    output full_o,
    output empty_o
);

    parameter g_width = 32;

    reg [g_width-1:0] mem [0:15];
    reg [3:0] head;
    reg [3:0] tail;
    wire [3:0] next_head;
    wire [3:0] next_tail;
    reg full;
    reg empty;

    assign next_head = (head == 15) ? 0 : head + 1;
    assign next_tail = (tail == 15) ? 0 : tail + 1;

    always @(posedge clk_i, negedge rst_i) begin
        if (!rst_i) begin
            head <= 0;
            tail <= 0;
            empty <= 1;
            full <= 0;
        end else begin
            if (push_i && !full) begin
                mem[head] <= data_i;
                head <= next_head;
                empty <= 0;
                if (next_head == tail) begin
                    full <= 1;
                end
            end
            if (pull_i && !empty) begin
                tail <= next_tail;
                full <= 0;
                if (next_tail == head) begin
                    empty <= 1;
                end
            end
        end
    end

    assign data_o = mem[tail];
    assign full_o = full;
    assign empty_o = empty;

endmodule

module priority_encoder (
    input [7:0] in0, in1, in2, in3,
    output reg [1:0] out);

    reg [7:0] temp0, temp1;
    wire [1:0] index0, index1;

    assign index0 = (temp0 <= temp1) ? 2'b00 : 2'b01;
    assign index1 = (in2 <= in3) ? 2'b10 : 2'b11;

    always @* begin
        if (in0 <= in1) begin
            temp0 = in0;
            out[0] = 1'b0;
        end else begin
            temp0 = in1;
            out[0] = 1'b1;
        end

        if (in2 <= in3) begin
            temp1 = in2;
            out[1] = 1'b0;
        end else begin
            temp1 = in3;
            out[1] = 1'b1;
        end
    end

    always @* begin
        case ({out, index0, index1})
            3'b000: out = 2'b00;
            3'b001: out = 2'b01;
            3'b010: out = 2'b10;
            3'b011: out = 2'b01;
            3'b100: out = 2'b11;
            3'b101: out = 2'b11;
            3'b110: out = 2'b10;
            3'b111: out = 2'b11;
        endcase
    end
endmodule

module top_module (
    input [7:0] a, b, c, d,
    output [7:0] min);

    wire [1:0] index;
    wire [7:0] temp0, temp1, temp2, temp3;

    priority_encoder pe0 (.in0(a), .in1(b), .in2(c), .in3(d), .out(index));
    assign temp0 = (index == 2'b00) ? a : b;
    assign temp1 = (index == 2'b01) ? c : d;
    assign temp2 = (index == 2'b10) ? temp0 : temp1;
    assign temp3 = (index == 2'b11) ? temp1 : temp0;
    assign min = temp3;

endmodule

module address_filter
  (input clk,
   input reset,
   input go,
   input [7:0] data,
   output match,
   output done);

   reg [2:0] af_state;

   always @(posedge clk)
     if(reset)
       af_state <= 0;
     else if(go)
       if(data[0] == 1'b0)
         af_state <= 1'b0;
       else
         af_state <= 3'b001;
     else
       case(af_state)
         3'b001: af_state <= 3'b010;
         3'b010: af_state <= 3'b011;
         3'b011: af_state <= 3'b100;
         3'b100: af_state <= 3'b101;
         3'b101: af_state <= 3'b110;
         3'b110: af_state <= 3'b000;
         default: af_state <= 3'b000;
       endcase

   assign match = (af_state == 3'b110);
   assign done = (af_state == 3'b110) || (af_state == 3'b000);

endmodule

module comparator (
