module ripple_adder_mux (
    input [3:0] A,
    input [3:0] B,
    input CIN,
    input A_sel, B_sel, C_sel, D_sel,
    output reg [3:0] S,
    output reg COUT,
    output reg [3:0] Y
);

    // Ripple Carry Adder
    wire [3:0] adder_out;
    wire carry_out;
    ripple_carry_adder adder(.A(A), .B(B), .CIN(CIN), .S(adder_out), .COUT(carry_out));

    // 4-to-1 Multiplexer
    wire [3:0] mux_out;
    assign mux_out = (A_sel) ? A : (B_sel) ? B : (C_sel) ? C : D;
    assign Y = mux_out;

    // Final Sum Calculation
    always @(*) begin
        case ({A_sel, B_sel, C_sel, D_sel})
            2'b00: S = adder_out;
            2'b01: S = adder_out + 1;
            2'b10: S = adder_out + 2;
            2'b11: S = adder_out + 3;
        endcase

        if (S >= 16) begin
            S = S - 16;
            COUT = 1;
        end else begin
            COUT = 0;
        end
    end

endmodule

module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    input CIN,
    output reg [3:0] S,
    output reg COUT
);

    always @(*) begin
        S = A + B + CIN;
        if (S >= 16) begin
            S = S - 16;
            COUT = 1;
        end else begin
            COUT = 0;
        end
    end

endmodule

