    end
    if (mem_write) begin
      mem[mem_addr] <= mem_in;
    end
  end
end

endmodule

module top_module (
    input clk,
    input reset, // Synchronous active-high reset
    input [99:0] in, // Input to the combinational circuit
    output out_and, // Output of a 50-input AND gate
    output out_or, // Output of a 50-input OR gate
    output out_xor, // Output of a 50-input XOR gate
    output [3:1] ena, // Enable signal for each of the upper three digits
    output [7:0] final_output // Final output of the system
);

    wire [49:0] and_inputs;
    wire [49:0] or_inputs;
    wire [49:0] xor_inputs;
    wire [7:0] bcd_out;
    wire [7:0] final_out;

    // Instantiate the combinational circuit
    and_gate and_inst (
        .in(and_inputs),
        .out(out_and)
    );
    or_gate or_inst (
        .in(or_inputs),
        .out(out_or)
    );
    xor_gate xor_inst (
        .in(xor_inputs),
        .out(out_xor)
    );

    // Instantiate the BCD counter
    bcd_counter bcd_inst (
        .clk(clk),
        .reset(reset),
        .ena(ena),
        .bcd_out(bcd_out)
    );

    // Instantiate the functional module
    functional_module func_inst (
        .in_and(out_and),
        .in_or(out_or),
        .in_xor(out_xor),
        .in_bcd(bcd_out),
        .out(final_out)
    );

    // Split the input to the combinational circuit into three parts
    assign and_inputs = in[99:50];
    assign or_inputs = in[49:0];
    assign xor_inputs = in[49:0];

    // Enable signals for the upper three digits of the BCD counter
    assign ena = {3{bcd_out[7]}};

    // Output the final 8-bit value
    assign final_output = final_out;

endmodule

// Define the and_gate module
module and_gate (
    input [49:0] in,
    output out
);
    assign out = &in;
endmodule

// Define the or_gate module
module or_gate (
    input [49:0] in,
    output out
);
    assign out = |in;
endmodule

// Define the xor_gate module
module xor_gate (
    input [49:0] in,
    output out
);
    assign out = ^in;
endmodule

// Define the BCD counter module
module bcd_counter (
    input clk,
    input reset, // Synchronous active-high reset
    input [2:0] ena, // Enable signal for each of the upper three digits
    output reg [7:0] bcd_out // Output in BCD format
);
    reg [3:0] gray_out;

    always @ (posedge clk) begin
        if (reset) begin
            gray_out <= 4'b0000;
            bcd_out <= 8'b00000000;
        end else begin
            gray_out <= gray_out + 1;
            if (ena[2]) begin
                bcd_out[7:4] <= gray_out[3:0];
            end
            if (ena[1]) begin
                bcd_out[3:0] <= gray_out[3:0];
            end
            if (ena[0]) begin
                bcd_out[7:4] <= gray_to_bcd(gray_out[3:0]);
            end
        end
    end

    function [3:0] gray_to_bcd;
        input [3:0] gray_in;
        begin
            case (gray_in)
                4'b0000: gray_to_bcd = 4'b0000;
                4'b0001: gray_to_bcd = 4'b0001;
                4'b0011: gray_to_bcd = 4'b0010;
                4'b0010: gray_to_bcd = 4'b0011;
                4'b0110: gray_to_bcd = 4'b0100;
                4'b0111: gray_to_bcd = 4'b0101;
                4'b0101: gray_to_bcd = 4'b0110;
                4'b0100: gray_to_bcd = 4'b0111;
                4'b1100: gray_to_bcd = 4'b1000;
                4'b1101: gray_to_bcd = 4'b1001;
                4'b1111: gray_to_bcd = 4'b1010;
                4'b1110: gray_to_bcd = 4'b1011;
                4'b1010: gray_to_bcd = 4'b1100;
                4'b1011: gray_to_bcd = 4'b1101;
                4'b1001: gray_to_bcd = 4'b1110;
                4'b1000: gray_to_bcd = 4'b1111;
                default: gray_to_bcd = 4'bxxxx;
            endcase
        end
    endfunction

endmodule

// Define the functional module
module functional_module (
    input [7:0] in_and,
    input [7:0] in_or,
    input [7:0] in_xor,
    input [7:0] in_bcd,
    output reg [7:0] out
);
    always @* begin
        out = in_and + in_or + in_xor + in_bcd;
    end
endmodule

