module max_4bit (
    input [3:0] A,
    input [3:0] B,
    output [3:0] max_out
);

    wire [3:0] temp_max;

    // Compare each bit and store the maximum value in temp_max
    assign temp_max[0] = (A[0] > B[0]) ? A[0] : B[0];
    assign temp_max[1] = (A[1] > B[1]) ? A[1] : B[1];
    assign temp_max[2] = (A[2] > B[2]) ? A[2] : B[2];
    assign temp_max[3] = (A[3] > B[3]) ? A[3] : B[3];

    // Assign the temporary maximum value to the output
    assign max_out = temp_max;

endmodule

module adder_4bit (
    input [3:0] A,
    input [3:0] B,
    input S,
    output [3:0] Y,
    output V
);

    wire [4:0] sum;
    wire signed [3:0] A_signed;
    wire signed [3:0] B_signed;

    // Convert inputs to signed if necessary
    assign A_signed = ({1'b0, A} - (S ? 8'b10000000 : 0));
    assign B_signed = ({1'b0, B} - (S ? 8'b10000000 : 0));

    // Calculate sum
    assign sum = A_signed + B_signed;

    // Determine overflow
    assign V = (S ? (sum[4] != sum[3]) : (sum[4] == 1));

    // Output sum
    assign Y = sum[3:0];

endmodule

