    output overflow
);

    // Carry Select Adder
    wire [7:0] sum;
    wire carry;
    carry_select_adder adder(.a(a), .b(b), .sum(sum), .carry(carry));

    // Overflow Detection
    wire overflow_detection;
    overflow_detector detector(.a(a), .b(b), .sum(sum), .carry(carry), .overflow(overflow_detection));

    // Shift Register
    reg [7:0] sum_reversed_reg;
    always @ (posedge clk) begin
        sum_reversed_reg <= {sum[0], sum[1], sum[2], sum[3], sum[4], sum[5], sum[6], sum[7]};
    end

    assign sum_reversed = sum_reversed_reg;

endmodule

module carry_select_adder (
    input [7:0] a,
    input [7:0] b,
    output [7:0] sum,
    output carry
);

    wire [3:0] g;
    wire [3:0] p;
    wire [3:0] c;
    wire [3:0] s;

    // Generate and Propagate signals
    gen_propagate_unit gen_propagate_unit_0(.a(a[3:0]), .b(b[3:0]), .g(g[0]), .p(p[0]));
    gen_propagate_unit gen_propagate_unit_1(.a(a[7:4]), .b(b[7:4]), .g(g[1]), .p(p[1]));
    gen_propagate_unit gen_propagate_unit_2(.a({4'b0, g[0]}), .b({4'b0, p[0]}), .g(g[2]), .p(p[2]));
    gen_propagate_unit gen_propagate_unit_3(.a({4'b0, g[1]}), .b({4'b0, p[1]}), .g(g[3]), .p(p[3]));

    // Carry signals
    assign c[0] = 1'b0;
    assign c[1] = carry_select(g[0], p[0], c[0]);
    assign c[2] = carry_select(g[1], p[1], c[1]);
    assign c[3] = carry_select(g[2], p[2], c[2]);

    // Sum signals
    assign s[0] = a[0] ^ b[0] ^ c[0];
    assign s[1] = a[1] ^ b[1] ^ c[1];
    assign s[2] = a[2] ^ b[2] ^ c[2];
    assign s[3] = a[3] ^ b[3] ^ c[3];
    assign s[4] = a[4] ^ b[4] ^ c[3];
    assign s[5] = a[5] ^ b[5] ^ c[3];
    assign s[6] = a[6] ^ b[6] ^ c[3];
    assign s[7] = a[7] ^ b[7] ^ c[3];

    // Output signals
    assign carry = c[3];
    assign sum = {s[7], s[6], s[5], s[4], s[3], s[2], s[1], s[0]};

endmodule

module gen_propagate_unit (
    input [3:0] a,
    input [3:0] b,
    output g,
    output p
);

    assign g = a[3] & b[3];
    assign p = a[3] ^ b[3];

    assign g = g | (a[2] & b[2]);
    assign p = p | (a[2] ^ b[2]);

    assign g = g | (a[1] & b[1]);
    assign p = p | (a[1] ^ b[1]);

    assign g = g | (a[0] & b[0]);
    assign p = p | (a[0] ^ b[0]);

endmodule

module overflow_detector (
    input [7:0] a,
    input [7:0] b,
    input [7:0] sum,
    input carry,
    output overflow
);

    assign overflow = ((a[7] == b[7]) && (a[7] != sum[7])) || ((a[7] == b[7]) && (a[7] == sum[7]) && (a[7] != carry));

endmodule

