module float_add_sub (
    clk_en,
    clock,
    dataa,
    datab,
    overflow,
    result
);

    input clk_en;
    input clock;
    input [31:0] dataa;
    input [31:0] datab;
    output overflow;
    output [31:0] result;

    wire signa = dataa[31];
    wire signb = datab[31];
    wire expa = dataa[30:23];
    wire expb = datab[30:23];
    wire fraca = (signa) ? -dataa[22:0] : dataa[22:0];
    wire fracb = (signb) ? -datab[22:0] : datab[22:0];
    wire expo_diff = expa - expb;
    wire fracb_shifted = (expo_diff > 0) ? {1'b1, fracb} >> expo_diff : {1'b1, fracb};
    wire fraca_shifted = (expo_diff < 0) ? {1'b1, fraca} >> -expo_diff : {1'b1, fraca};
    wire result_frac;
    wire result_exp;
    wire result_sign;

    assign result_sign = (result_frac[31] == 1) ? 1'b1 : 1'b0;
    assign result_exp = (result_frac[31:23] == 8'h00) ? expa : result_frac[31:23] + expa;
    assign result_frac = result_frac[22:0];
    assign overflow = (result_exp == 8'hFF) ? 1'b1 : 1'b0;
    assign result = {result_sign, result_exp, result_frac};

    always @ (posedge clock) begin
        if (clk_en == 1'b1) begin
            if (expa > expb) begin
                result_frac = fraca_shifted - fracb_shifted;
            end else begin
                result_frac = fracb_shifted - fraca_shifted;
            end
        end else begin
            result_frac = 0;
            result_exp = 0;
            result_sign = 0;
            overflow = 0;
        end
    end

endmodule

module top_module (
    input [31:0] a,
    input [31:0] b,
    output [31:0] sum,
    output overflow,
    output [31:0] abs_sum
);

wire [31:0] add_result;
wire [31:0] abs_result;
wire carry_out;

// Adder module
adder adder_inst (
    .a(a),
    .b(b),
    .sum(add_result),
    .carry_out(carry_out)
);

// Overflow detection module
overflow_detector overflow_inst (
    .a(a),
    .b(b),
    .sum(add_result),
    .overflow(overflow)
);

// Absolute value module
abs abs_inst (
    .in(add_result),
    .out(abs_result)
);

// Mux for determining whether to output sum or absolute value
assign sum = (carry_out) ? abs_result : add_result;

// Mux for determining whether to output overflow or not
assign overflow = carry_out;

// Output absolute value of sum
assign abs_sum = abs_result;

endmodule

