module ringbuffer
#(
  parameter AW = 4,
  parameter DW = 8
)(
  input wire clk,
  input wire rst,
  input wire wr_en,
  input wire rd_en,
  input wire [DW-1:0] wr_data,
  output reg [DW-1:0] rd_data,
  output reg empty,
  output reg overflow
);

  reg [DW-1:0] mem [0:(1<<AW)-1];
  reg [AW-1:0] wr_ptr;
  reg [AW-1:0] rd_ptr;
  reg [AW-1:0] next_wr_ptr;
  reg [AW-1:0] next_rd_ptr;

  always @(posedge clk) begin
    if (rst) begin
      wr_ptr <= 0;
      rd_ptr <= 0;
      next_wr_ptr <= 0;
      next_rd_ptr <= 0;
      empty <= 1;
      overflow <= 0;
    end else begin
      wr_ptr <= next_wr_ptr;
      rd_ptr <= next_rd_ptr;
      empty <= (wr_ptr == rd_ptr);
      overflow <= ((wr_ptr+1) == rd_ptr);
      if (wr_en && !overflow) begin
        mem[wr_ptr] <= wr_data;
        next_wr_ptr <= (wr_ptr+1) % (1<<AW);
      end
      if (rd_en && !empty) begin
        rd_data <= mem[rd_ptr];
        next_rd_ptr <= (rd_ptr+1) % (1<<AW);
      end
    end
  end

endmodule

