module digit_display(
    input clk,
    input reset,
    output reg [6:0] seg,
    output reg DG1,
    output reg DG2
);

    reg [3:0] digit1, digit2;
    reg [9:0] count;
    wire clk_500ms;

    // Generate 500ms clock
    always @(posedge clk) begin
        if (reset) begin
            count <= 0;
            clk_500ms <= 0;
        end else if (count == 999) begin
            count <= 0;
            clk_500ms <= ~clk_500ms;
        end else begin
            count <= count + 1;
            clk_500ms <= clk_500ms;
        end
    end

    // Display digit1 for first 500ms, then digit2 for next 500ms
    always @(posedge clk_500ms) begin
        if (reset) begin
            digit1 <= 0;
            digit2 <= 0;
            DG1 <= 1;
            DG2 <= 0;
        end else if (DG1) begin
            digit1 <= digit1 + 1;
            if (digit1 == 9) begin
                digit1 <= 0;
                DG1 <= 0;
                DG2 <= 1;
            end
        end else if (DG2) begin
            digit2 <= digit2 + 1;
            if (digit2 == 9) begin
                digit2 <= 0;
                DG1 <= 1;
                DG2 <= 0;
            end
        end
    end

    // Display appropriate segment for digit
    always @(*) begin
        case (DG1)
            1: seg = {
                digit1 == 4'b0000 ? 7'b1000000 :
                digit1 == 4'b0001 ? 7'b1111001 :
                digit1 == 4'b0010 ? 7'b0100100 :
                digit1 == 4'b0011 ? 7'b0110000 :
                digit1 == 4'b0100 ? 7'b0011001 :
                digit1 == 4'b0101 ? 7'b0010010 :
                digit1 == 4'b0110 ? 7'b0000010 :
                digit1 == 4'b0111 ? 7'b1111000 :
                digit1 == 4'b1000 ? 7'b0000000 :
                digit1 == 4'b1001 ? 7'b0010000 :
                7'b0000000
            };
            0: seg = {
                digit2 == 4'b0000 ? 7'b1000000 :
                digit2 == 4'b0001 ? 7'b1111001 :
                digit2 == 4'b0010 ? 7'b0100100 :
                digit2 == 4'b0011 ? 7'b0110000 :
                digit2 == 4'b0100 ? 7'b0011001 :
                digit2 == 4'b0101 ? 7'b0010010 :
                digit2 == 4'b0110 ? 7'b0000010 :
                digit2 == 4'b0111 ? 7'b1111000 :
                digit2 == 4'b1000 ? 7'b0000000 :
                digit2 == 4'b1001 ? 7'b0010000 :
                7'b0000000
            };
        endcase
    end

endmodule

module binary_counter(clk, rst, count);

