module uart_sync_flops
(
  // internal signals
  rst_i,
  clk_i,
  stage1_rst_i,
  stage1_clk_en_i,
  async_dat_i,
  sync_dat_o
);

parameter width         = 1;
parameter init_value    = 1'b0;

input                           rst_i;                  // reset input
input                           clk_i;                  // clock input
input                           stage1_rst_i;           // synchronous reset for stage 1 FF
input                           stage1_clk_en_i;        // synchronous clock enable for stage 1 FF
input   [width-1:0]             async_dat_i;            // asynchronous data input
output  [width-1:0]             sync_dat_o;             // synchronous data output


//
// Interal signal declarations
//

reg     [width-1:0]             sync_dat_o;
reg     [width-1:0]             flop_0;


// first stage
always @ (posedge clk_i or posedge rst_i)
begin
    if (rst_i)
        flop_0 <= {width{init_value}};
    else
        flop_0 <= async_dat_i;    
end

// second stage
always @ (posedge clk_i or posedge rst_i)
begin
    if (rst_i)
        sync_dat_o <= {width{init_value}};
    else if (stage1_rst_i)
        sync_dat_o <= {width{init_value}};
    else if (stage1_clk_en_i)
        sync_dat_o <= flop_0;       
end

endmodule

module hamming (
  input [n-1:0] data,
  input ctrl,
  output [m-1:0] hamming,
  output [n-1:0] corrected
);

parameter n = 4; // length of the data word
parameter m = 7; // length of the Hamming code word
parameter r = 3; // number of redundant bits

// Encoder
wire [r-1:0] parity;
assign parity = {data[0]^data[1]^data[3], data[0]^data[2]^data[3], data[1]^data[2]^data[3]};

always @ (posedge ctrl) begin
  if (ctrl) begin
    hamming[0] = parity[0];
    hamming[1] = parity[1];
    hamming[2] = data[0];
    hamming[3] = parity[2];
    hamming[4] = data[1];
    hamming[5] = data[2];
    hamming[6] = data[3];
  end
end

// Decoder
wire [r-1:0] syndrome;
assign syndrome = {hamming[0]^hamming[2]^hamming[4]^hamming[6], hamming[1]^hamming[2]^hamming[5]^hamming[6], hamming[3]^hamming[4]^hamming[5]^hamming[6]};

always @ (posedge ctrl) begin
  if (!ctrl) begin
    if (syndrome == 0) begin
      corrected = data;
    end else begin
      corrected = {data[0]^syndrome[2], data[1]^syndrome[1], data[2]^syndrome[0], data[3]};
    end
  end
end

endmodule

module dff_ce_clr(clk, clr, ce, d, q);

