module multiplier (p, a, b);
  output [7:0] p;
  input [3:0] a, b;

  wire [7:0] p0, p1, p2, p3, p4, p5, p6, p7;

  and_gate and0 (p0[0], a[0], b[0]);
  and_gate and1 (p1[0], a[0], b[1]);
  and_gate and2 (p2[0], a[0], b[2]);
  and_gate and3 (p3[0], a[0], b[3]);
  and_gate and4 (p4[0], a[1], b[0]);
  and_gate and5 (p5[0], a[1], b[1]);
  and_gate and6 (p6[0], a[1], b[2]);
  and_gate and7 (p7[0], a[1], b[3]);

  or_gate or0 (p[0], p0[0], p1[0]);
  or_gate or1 (p[1], p2[0], p3[0]);
  or_gate or2 (p[2], p4[0], p5[0]);
  or_gate or3 (p[3], p6[0], p7[0]);

  and_gate and8 (p0[1], a[2], b[0]);
  and_gate and9 (p1[1], a[2], b[1]);
  and_gate and10 (p2[1], a[2], b[2]);
  and_gate and11 (p3[1], a[2], b[3]);
  and_gate and12 (p4[1], a[3], b[0]);
  and_gate and13 (p5[1], a[3], b[1]);
  and_gate and14 (p6[1], a[3], b[2]);
  and_gate and15 (p7[1], a[3], b[3]);

  or_gate or4 (p[4], p0[1], p1[1], p2[0], p3[0]);
  or_gate or5 (p[5], p4[0], p5[0], p6[0], p7[0]);
  or_gate or6 (p[6], p0[1], p1[1], p2[1], p3[1]);
  or_gate or7 (p[7], p4[1], p5[1], p6[1], p7[1]);
endmodule

module afifo(
    din,
    wr_en,
    wr_clk,
    rd_en,
    rd_clk,
    ainit,
    dout,
    full,
    almost_full,
    empty,
    wr_count,
    rd_count,
    rd_ack,
    wr_ack
);

parameter DATA_WIDTH          = 16;
parameter ADDR_WIDTH          = 8;
parameter COUNT_DATA_WIDTH    = 8;
parameter ALMOST_FULL_DEPTH   = 8;

input [DATA_WIDTH-1:0]         din;
input                          wr_en;
input                          wr_clk;
input                          rd_en;
input                          rd_clk;
input                          ainit;
output [DATA_WIDTH-1:0]        dout;
output                         full;
output                         almost_full;
output                         empty;
output [COUNT_DATA_WIDTH-1:0]  wr_count;
output [COUNT_DATA_WIDTH-1:0]  rd_count;
output                         rd_ack;
output                         wr_ack;

reg [ADDR_WIDTH-1:0]           Add_wr;
reg [ADDR_WIDTH-1:0]           Add_wr_ungray;
reg [ADDR_WIDTH-1:0]           Add_wr_gray;
reg [ADDR_WIDTH-1:0]           Add_wr_gray_dl1;

reg [ADDR_WIDTH-1:0]           Add_rd;
wire [ADDR_WIDTH-1:0]          Add_rd_pluse;
reg [ADDR_WIDTH-1:0]           Add_rd_gray;
reg [ADDR_WIDTH-1:0]           Add_rd_gray_dl1;
reg [ADDR_WIDTH-1:0]           Add_rd_ungray;

integer i;

reg full;
reg empty;
reg rd_ack;
reg rd_ack_tmp;
reg almost_full;
wire [DATA_WIDTH-1:0] dout_tmp;

assign ff_used_wr = Add_wr - Add_rd_ungray;
assign wr_count = ff_used_wr[ADDR_WIDTH-1:ADDR_WIDTH-COUNT_DATA_WIDTH];

always @ (posedge ainit or posedge wr_clk) begin
    if (ainit) begin
        Add_wr_gray <= 0;
    end else begin
        Add_wr_gray[ADDR_WIDTH-1] <= Add_wr[ADDR_WIDTH-1];
        for (i = ADDR_WIDTH-2; i >= 0; i = i - 1) begin
            Add_wr_gray[i] <= Add_wr[i+1] ^ Add_wr[i];
        end
    end
end

always @ (posedge wr_clk or posedge ainit) begin
    if (ainit) begin
        Add_rd_gray_dl1 <= 0;
    end else begin
        Add_rd_gray_dl1 <= Add_rd_gray;
    end
end

always @ (posedge wr_clk or posedge ainit) begin
    if (ainit) begin
        Add_rd_ungray = 0;
    end else begin
        Add_rd_ungray[ADDR_WIDTH-1] = Add_rd_gray_dl1[ADDR_WIDTH-1];
        for (i = ADDR_WIDTH-2; i >= 0; i = i - 1) begin
            Add_rd_ungray[i] = Add_rd_ungray[i+1] ^ Add_rd_gray_dl1[i];
        end
    end
end

always @ (posedge wr_clk or posedge ainit) begin
    if (ainit) begin
        full <= 0;
    end else if (Add_wr_pluse == Add_rd_ungray && wr_en) begin
        full <= 1;
    end else if (Add_wr != Add_rd_ungray) begin
        full <= 0;
    end
end

always @ (posedge wr_clk or posedge ainit) begin
    if (ainit) begin
        almost_full <= 0;
    end else if (wr_count >= ALMOST_FULL_DEPTH) begin
        almost_full <= 1;
    end else begin
        almost_full <= 0;
    end
end

always @ (posedge wr_clk or posedge ainit) begin
    if (ainit) begin
        Add_wr <= 0;
    end else if (wr_en && !full) begin
        Add_wr <= Add_wr + 1;
    end
end

assign Add_wr_pluse = Add_wr + 1;

assign ff_used_rd = Add_wr_ungray - Add_rd;
assign rd_count = ff_used_rd[ADDR_WIDTH-1:ADDR_WIDTH-COUNT_DATA_WIDTH];
assign Add_rd_pluse = Add_rd + 1;

always @ (posedge rd_clk or posedge ainit) begin
    if (ainit) begin
        rd_ack <= 0;
    end else if (rd_en && !empty) begin
        rd_ack <= 1;
    end else begin
        rd_ack <= 0;
    end
end

always @ (posedge rd_clk or posedge ainit) begin
    if (ainit) begin
        Add_rd_gray <= 0;
    end else begin
        Add_rd_gray[ADDR_WIDTH-1] <= Add_rd[ADDR_WIDTH-1];
        for (i = ADDR_WIDTH-2; i >= 0; i = i - 1) begin
            Add_rd_gray[i] <= Add_rd[i+1] ^ Add_rd[i];
        end
    end
end

always @ (posedge rd_clk or posedge ainit) begin
    if (ainit) begin
        Add_wr_gray_dl1 <= 0;
    end else begin
        Add_wr_gray_dl1 <= Add_wr_gray;
    end
end

always @ (posedge rd_clk or posedge ainit) begin
    if (ainit) begin
        Add_wr_ungray = 0;
    end else begin
        Add_wr_ungray[ADDR_WIDTH-1] = Add_wr_gray_dl1[ADDR_WIDTH-1];
        for (i = ADDR_WIDTH-2; i >= 0; i = i - 1) begin
            Add_wr_ungray[i] = Add_wr_ungray[i+1] ^ Add_wr_gray_dl1[i];
        end
    end
end

always @ (posedge rd_clk or posedge ainit) begin
    if (ainit) begin
        empty <= 1;
    end else if (Add_rd_pluse == Add_wr_ungray && rd_en) begin
        empty <= 1;
    end else if (Add_rd != Add_wr_ungray) begin
        empty <= 0;
    end
end

duram #(
    DATA_WIDTH,
    ADDR_WIDTH
) 
U_duram (
    .data_a(din),
    .wren_a(wr_en),
    .address_a(Add_wr),
    .address_b(Add_rd),
    .clock_a(wr_clk),
    .clock_b(rd_clk),
    .q_b(dout_tmp)
