module boolean_ops (
   // Outputs
   logic_out, 
   // Inputs
   rs1_data, rs2_data, isand, isor, isxor, pass_rs2_data, inv_logic, 
   ifu_exu_sethi_inst_e
   );

   input [63:0] rs1_data;             // 1st input operand
   input [63:0] rs2_data;             // 2nd input operand
   input isand;
   input isor;
   input isxor;
   input pass_rs2_data;
   input inv_logic;
   input ifu_exu_sethi_inst_e;       // zero out top half of rs2 on mov

   output [63:0] logic_out;      // output of logic block

   wire [63:0] rs1_data_bf1;                 // buffered rs1_data
   wire [63:0] rs2_data_bf1;                 // buffered rs2_data
   wire [63:0] mov_data;
   wire [63:0] result_and;              // rs1_data & rs2_data
   wire [63:0] result_or;               // rs1_data | rs2_data
   wire [63:0] result_xor;              // rs1_data ^ rs2_data
   wire [63:0] rs2_xor_invert;           // output of mux between various results

   // buffer inputs
   dp_buffer #(64) rs1_data_buf(.dout(rs1_data_bf1[63:0]), .in(rs1_data[63:0]));
   dp_buffer #(64) rs2_data_buf(.dout(rs2_data_bf1[63:0]), .in(rs2_data[63:0]));

   // zero out top of rs2 for sethi_inst
   assign mov_data[63:32] = rs2_data_bf1[63:32] & {32{~ifu_exu_sethi_inst_e}};
   dp_buffer #(32) rs2_data_buf2(.dout(mov_data[31:0]), .in(rs2_data_bf1[31:0]));

   // invert input2 for andn, orn, xnor
   assign rs2_xor_invert[63:0] = rs2_data_bf1[63:0] ^ {64{inv_logic}};

   // do boolean ops
   assign result_and = rs1_data_bf1 & rs2_xor_invert;
   assign result_or = rs1_data_bf1 | rs2_xor_invert;
   assign result_xor = rs1_data_bf1 ^ rs2_xor_invert;

   // mux between various results
   mux4ds #(64) logic_mux(.dout(logic_out[63:0]),
                        .in0(result_and[63:0]), 
                        .in1(result_or[63:0]),
                        .in2(result_xor[63:0]), 
                        .in3(mov_data[63:0]), 
                        .sel0(isand),
                        .sel1(isor), 
                        .sel2(isxor),
                        .sel3(pass_rs2_data));

endmodule

module top_module(
    input clk,    // clock signal for the D flip-flop
    input [15:0] in,    // 16-bit input for the barrel shifter
    output reg [15:0] out    // 16-bit final output
);

    reg [7:0] in_lsb;    // 8-bit input for the left side of the barrel shifter
    reg [7:0] in_msb;    // 8-bit input for the right side of the barrel shifter
    reg [7:0] out_lsb;    // 8-bit output for the left side of the barrel shifter
    reg [7:0] out_msb;    // 8-bit output for the right side of the barrel shifter
    reg [7:0] temp_lsb;    // 8-bit temporary storage for the left side of the input
    reg [7:0] temp_msb;    // 8-bit temporary storage for the right side of the input

    assign {out_msb, out_lsb} = {temp_lsb, temp_msb};    // concatenate the two 8-bit outputs in reverse order

    // instantiate the barrel shifter
    barrel_shifter bs(
        .in(in),
        .out_lsb(out_lsb),
        .out_msb(out_msb)
    );

    // instantiate the D flip-flop
    always @(posedge clk) begin
        temp_lsb <= out_lsb;
        temp_msb <= out_msb;
    end

    // assign the final output
    assign out = {out_msb, out_lsb};

endmodule

// barrel shifter module
module barrel_shifter(
    input [15:0] in,    // 16-bit input
    output reg [7:0] out_lsb,    // 8-bit output for the left side of the barrel shifter
    output reg [7:0] out_msb    // 8-bit output for the right side of the barrel shifter
);

    assign {out_msb, out_lsb} = in >> 8;    // split the 16-bit input into two 8-bit outputs

endmodule

module nkmd_dai_tx(
    input wire clk,
    input wire rst,

    // dmix interface
    output wire [23:0] tx_data_o,
    input wire tx_pop_i,
    output wire tx_ack_o,

    // To nkmm R bus
    input wire [31:0] data_i,
    output wire [31:0] data_o,
    input wire [31:0] addr_i,
    input wire we_i);

reg [5:0] queued_ff;
reg [5:0] lastr_ff;
reg [5:0] nextw_ff;

reg [23:0] ringbuf [63:0];
assign tx_data_o = ringbuf[lastr_ff];

wire should_queue;
assign should_queue = we_i && addr_i[15:12] == 4'hd && addr_i[7:0] == 8'h01;
always @(posedge clk) begin
    if (rst) begin
        queued_ff <= 0;
        lastr_ff <= 6'h3f;
        nextw_ff <= 0;
    end else if (should_queue && !tx_pop_i) begin
        ringbuf[nextw_ff] <= data_i;
        queued_ff <= queued_ff + 1;
        nextw_ff <= nextw_ff + 1;
    end else if (!should_queue && tx_pop_i) begin
        if (queued_ff > 0) begin
            queued_ff <= queued_ff - 1;
            lastr_ff <= lastr_ff + 1;
        end
    end else if (should_queue && tx_pop_i) begin
        ringbuf[nextw_ff] <= data_i;
        if (queued_ff > 0) begin
            lastr_ff <= lastr_ff + 1;
        end else begin
            queued_ff <= queued_ff + 1;
        end
        nextw_ff <= nextw_ff + 1;
    end
end

reg tx_ack_ff;
always @(posedge clk)
    tx_ack_ff <= tx_pop_i;
assign tx_ack_o = tx_ack_ff;

// RAM interface
reg [31:0] data_o_ff;
assign data_o = data_o_ff;

// {4'hd, ch[3:0], 8'h01} => tx ringbuf queued
// {4'he, ch[3:0], offset} => tx ringbuf
// FIXME: add ch check

wire [5:0] offset_i;
assign offset_i = addr_i[5:0];

always @(posedge clk) begin
    if (addr_i[15:12] == 4'he)
        data_o_ff <= ringbuf[nextw_ff - 1 - offset_i];
    else if (addr_i[15:12] == 4'hd && addr_i[7:0] == 8'h01)
        data_o_ff <= queued_ff;
    else
        data_o_ff <= 0;
end

endmodule

