module thermal_management_block (
  input clk,
  input rst,
  input temp_sensor,
  input [7:0] temp_threshold_high,
  input [7:0] temp_threshold_low,
  output reg [7:0] fan_speed,
  output reg [7:0] temp_digital
);

  // ADC module
  reg [7:0] adc_value;
  always @(posedge clk) begin
    if (rst) begin
      adc_value <= 8'h00;
    end else begin
      adc_value <= temp_sensor;
    end
  end

  // Digital filter module
  reg [7:0] filtered_value;
  always @(posedge clk) begin
    if (rst) begin
      filtered_value <= 8'h00;
    end else begin
      filtered_value <= (filtered_value + adc_value) >> 1;
    end
  end

  // PWM module
  reg [7:0] pwm_count;
  always @(posedge clk) begin
    if (rst) begin
      pwm_count <= 8'h00;
      fan_speed <= 8'h00;
    end else begin
      if (pwm_count >= filtered_value) begin
        pwm_count <= 8'h00;
        if (filtered_value > temp_threshold_high) begin
          fan_speed <= 8'hFF;
        end else if (filtered_value < temp_threshold_low) begin
          fan_speed <= 8'h00;
        end
      end else begin
        pwm_count <= pwm_count + 1;
      end
    end
  end

  // Output digital temperature value
  always @(posedge clk) begin
    if (rst) begin
      temp_digital <= 8'h00;
    end else begin
      temp_digital <= filtered_value;
    end
  end

endmodule

module signed_mag_sqrt (
    input signed [3:0] a,
    output signed [3:0] sqrt,
    output error
);

reg signed [3:0] stage1_out;
reg signed [3:0] stage2_out;
reg signed [3:0] stage3_out;
reg signed [3:0] stage4_out;

reg [1:0] stage;

assign error = (a < 0);

always @(*) begin
    case(stage)
        0: stage1_out = a;
        1: stage2_out = stage1_out[3:2] + 2'b10;
        2: stage3_out = {stage2_out[2], stage2_out[1], stage2_out[0], 1'b0};
        3: stage4_out = stage3_out[3:2] + 2'b10;
    endcase
end

always @(posedge clk) begin
    if (reset) begin
        stage <= 0;
    end else begin
        case(stage)
            0: begin
                stage1_out = a;
                stage <= 1;
            end
            1: begin
                stage2_out = stage1_out[3:2] + 2'b10;
                stage <= 2;
            end
            2: begin
                stage3_out = {stage2_out[2], stage2_out[1], stage2_out[0], 1'b0};
                stage <= 3;
            end
            3: begin
                stage4_out = stage3_out[3:2] + 2'b10;
                stage <= 4;
            end
            default: begin
                sqrt = stage4_out;
                stage <= 0;
            end
        endcase
    end
end

endmodule

