module sequence_detector(
    input clk_i,
    input in_i,
    output reg out_o
);

    reg [1:0] state;
    parameter IDLE = 2'b00;
    parameter FOUND_0 = 2'b01;
    parameter FOUND_01 = 2'b10;

    always @(posedge clk_i) begin
        case(state)
            IDLE: begin
                if(in_i == 1'b0) begin
                    state <= FOUND_0;
                end
            end
            FOUND_0: begin
                if(in_i == 1'b1) begin
                    state <= FOUND_01;
                end else begin
                    state <= IDLE;
                end
            end
            FOUND_01: begin
                if(in_i == 1'b0) begin
                    state <= FOUND_0;
                end else begin
                    state <= IDLE;
                    out_o <= 1'b1;
                end
            end
            default: begin
                state <= IDLE;
            end
        endcase
    end

    always @(posedge clk_i or posedge rst_i) begin
        if(rst_i) begin
            state <= IDLE;
            out_o <= 1'b0;
        end else if(state == FOUND_01) begin
            out_o <= 1'b0;
        end
    end

endmodule

module stego_decode(clk, rst, start, data_in, message, rdy);
output rdy, message;
input clk, rst, start; 
input [7:0] data_in; 

reg [5:0] cnt;
reg [5:0] bit_cnt;
reg [41:0] message_reg;
reg rdy;
reg message;

always @(posedge clk) begin
    if (rst) begin
        cnt <= 0;
        bit_cnt <= 0;
        message_reg <= 0;
        rdy <= 0;
        message <= 0;
    end
    else begin
        if (start) begin
            if (cnt < 42) begin
                message_reg[cnt] <= data_in[0];
                cnt <= cnt + 1;
            end
            else begin
                if (bit_cnt < 42) begin
                    message <= message_reg[bit_cnt];
                    bit_cnt <= bit_cnt + 1;
                    rdy <= 1;
                end
                else begin
                    rdy <= 0;
                end
            end
        end
    end
end

endmodule

module lcd_sync (
    input           rst,
    input   [23:0] lcd_data_i,
    input           lcd_pclk_i,
    input           lcd_vsync_i,
    input           lcd_hsync_i,
    input           lcd_de_i,
    output          lcd_clk_o,
    output  [11:0]  lcd_x_o,
    output  [11:0]  lcd_y_o,
    output  [23:0]  lcd_data_o,
    output          lcd_data_valid_o
);

    reg     [11:0] lcd_x_q;
    reg     [11:0] lcd_y_q;
    reg     [23:0] lcd_data_q;
    reg             lcd_hsync_q;
    reg             lcd_vsync_q;
    reg             lcd_de_q;
    reg             lcd_vsync_end_q;
    reg             lcd_hsync_end_q;

    assign          lcd_clk_o = lcd_pclk_i;
    assign          lcd_x_o = lcd_x_q;
    assign          lcd_y_o = lcd_y_q;
    assign          lcd_data_o = lcd_data_q;
    assign          lcd_data_valid_o = lcd_de_q;

    wire            lcd_hsync_end = (lcd_hsync_i == 0) && (lcd_hsync_q == 1);
    wire            lcd_vsync_end = (lcd_vsync_i == 1) && (lcd_vsync_q == 0);

    always @(posedge lcd_pclk_i) begin
        if (rst) begin
            lcd_x_q <= 0;
            lcd_y_q <= 0;
            lcd_data_q <= 0;
            lcd_hsync_q <= 0;
            lcd_vsync_q <= 0;
            lcd_de_q <= 0;
            lcd_vsync_end_q <= 0;
            lcd_hsync_end_q <= 0;
        end
        else begin
            lcd_hsync_q <= lcd_hsync_i;
            lcd_vsync_q <= lcd_vsync_i;
            lcd_de_q <= lcd_de_i;

            if (lcd_de_i) begin
                lcd_data_q <= lcd_data_i;
            end else begin
                lcd_data_q <= 0;
            end

            if (lcd_vsync_i != lcd_vsync_q) begin
                lcd_vsync_end_q <= lcd_vsync_q;
            end

            if (lcd_hsync_i != lcd_hsync_q) begin
                lcd_hsync_end_q <= lcd_hsync_q;
            end

            if (lcd_vsync_end_q) begin
                lcd_y_q <= 0;
            end else begin
                if (lcd_hsync_end_q) begin
                    lcd_y_q <= lcd_y_q + 1;
                end
            end

            if (lcd_hsync_end_q) begin
                lcd_x_q <= 0;
            end else begin
                if (lcd_de_q) begin
                    lcd_x_q <= lcd_x_q + 1;
                end
            end
        end
    end

endmodule

module fifo_36x256 (
    input clock,
    input [35:0] data,
    input rdreq,
    input wrreq,
    output empty,
    output full,
    output [35:0] q,
    output [7:0] usedw
);

    // Internal FIFO memory
    reg [35:0] mem [0:255];
    // Read and write pointers
    reg [7:0] rptr = 0;
    reg [7:0] wptr = 0;
    // Number of words in the FIFO
    reg [7:0] count = 0;

    // Full and empty signals
    assign empty = (count == 0);
    assign full = (count == 256);

    // Read logic
    always @(posedge clock) begin
        if (rdreq && !empty) begin
            q <= mem[rptr];
            rptr <= rptr + 1;
            count <= count - 1;
        end
    end

    // Write logic
    always @(posedge clock) begin
        if (wrreq && !full) begin
            mem[wptr] <= data;
            wptr <= wptr + 1;
            count <= count + 1;
        end
    end

    // Output the number of words used in the FIFO
    assign usedw = count;

endmodule

