module four_bit_adder (
    A,
    B,
    Cin,
    Clk,
    S,
    Cout
);

    input [3:0] A;
    input [3:0] B;
    input Cin;
    input Clk;
    output [3:0] S;
    output Cout;

    wire [3:0] sum;
    wire carry;

    // Full Adder
    assign sum = A + B + Cin;
    assign Cout = (A[3] & B[3]) | (Cin & (A[3] ^ B[3]));
    assign S = sum;

    always @(posedge Clk) begin
        S <= sum;
        Cout <= carry;
    end

endmodule

module jbi_1r1w_16x160(
    input rdclk,
    input read_en,
    input [3:0] rd_adr,
    input wrclk,
    input wr_en,
    input [3:0] wr_adr,
    input [159:0] din,
    input rst_l,
    output [159:0] dout
);

    // Parameter declarations
    parameter WIDTH = 160;
    parameter DEPTH = 16;

    // Local signal declarations
    wire [WIDTH-1:0] mem [DEPTH-1:0];
    reg [3:0] rd_ptr;
    reg [3:0] wr_ptr;
    reg [WIDTH-1:0] rd_data;
    reg [WIDTH-1:0] wr_data;

    // Read pointer logic
    always @(posedge rdclk or negedge rst_l) begin
        if (~rst_l) begin
            rd_ptr <= 0;
        end else if (read_en) begin
            rd_ptr <= rd_adr;
        end
    end

    // Write pointer logic
    always @(posedge wrclk or negedge rst_l) begin
        if (~rst_l) begin
            wr_ptr <= 0;
        end else if (wr_en) begin
            wr_ptr <= wr_adr;
        end
    end

    // Read data logic
    always @(posedge rdclk or negedge rst_l) begin
        if (~rst_l) begin
            rd_data <= 0;
        end else if (read_en) begin
            rd_data <= mem[rd_ptr];
        end
    end

    // Write data logic
    always @(posedge wrclk or negedge rst_l) begin
        if (~rst_l) begin
            wr_data <= 0;
        end else if (wr_en) begin
            wr_data <= din;
            mem[wr_ptr] <= din;
        end
    end

    // Output data logic
    always @(posedge rdclk or negedge rst_l) begin
        if (~rst_l) begin
            dout <= 0;
        end else if (read_en && wr_en && (rd_ptr == wr_ptr)) begin
            dout <= wr_data;
        end else if (read_en) begin
            dout <= rd_data;
        end
    end

endmodule

module altpll2 (
	areset,
	clkswitch,
	inclk0,
	inclk1,
	activeclock,
	c0,
	c1,
	c2,
	c3,
	clkbad0,
	clkbad1,
	locked);

	input	  areset;
	input	  clkswitch;
	input	  inclk0;
	input	  inclk1;
	output	  activeclock;
	output	  c0;
	output	  c1;
	output	  c2;
	output	  c3;
	output	  clkbad0;
	output	  clkbad1;
	output	  locked;

	reg [31:0] counter0 = 0;
	reg [31:0] counter1 = 0;
	reg [31:0] counter2 = 0;
	reg [31:0] counter3 = 0;
	reg [31:0] prev_counter0 = 0;
	reg [31:0] prev_counter1 = 0;
	reg [31:0] prev_counter2 = 0;
	reg [31:0] prev_counter3 = 0;
	reg [1:0]  clk_sel = 0;
	reg        locked_reg = 0;
	reg        clkbad0_reg = 0;
	reg        clkbad1_reg = 0;

	assign activeclock = clk_sel ? inclk1 : inclk0;
	assign c0 = counter0[31];
	assign c1 = counter1[31];
	assign c2 = counter2[31];
	assign c3 = counter3[31];
	assign clkbad0 = clkbad0_reg;
	assign clkbad1 = clkbad1_reg;
	assign locked = locked_reg;

	always @(posedge inclk0 or posedge inclk1 or posedge areset) begin
		if (areset) begin
			counter0 <= 0;
			counter1 <= 0;
			counter2 <= 0;
			counter3 <= 0;
			prev_counter0 <= 0;
			prev_counter1 <= 0;
			prev_counter2 <= 0;
			prev_counter3 <= 0;
			clk_sel <= 0;
			locked_reg <= 0;
			clkbad0_reg <= 0;
			clkbad1_reg <= 0;
		end else begin
			if (clk_sel == 0) begin
				counter0 <= counter0 + 1;
				counter1 <= counter1 + 2;
				counter2 <= counter2 + 4;
				counter3 <= counter3 + 8;
			end else begin
				counter0 <= counter0 + 2;
				counter1 <= counter1 + 4;
				counter2 <= counter2 + 8;
				counter3 <= counter3 + 16;
			end

			if (counter0 == 0) begin
				clkbad0_reg <= 1;
			end else if (counter0 == prev_counter0) begin
				clkbad0_reg <= 1;
			end else begin
				clkbad0_reg <= 0;
			end

			if (counter1 == 0) begin
				clkbad1_reg <= 1;
			end else if (counter1 == prev_counter1) begin
				clkbad1_reg <= 1;
			end else begin
				clkbad1_reg <= 0;
			end

			if (counter0[31] == 1 && counter1[31] == 1 && counter2[31] == 1 && counter3[31] == 1) begin
				locked_reg <= 1;
			end else begin
				locked_reg <= 0;
			end

			prev_counter0 <= counter0;
			prev_counter1 <= counter1;
			prev_counter2 <= counter2;
			prev_counter3 <= counter3;

			if (clkswitch) begin
				clk_sel <= ~clk_sel;
			end
		end
	end

endmodule

module and_or_xor_adder (
    input [7:0] in1,
    input [7:0] in2,
    output reg [7:0] out
);

    // Step 1: Compute the bitwise AND of in1 and in2
    wire [7:0] and_result = in1 & in2;

    // Step 2: Compute the bitwise OR of in1 and in2
    wire [7:0] or_result = in1 | in2;

    // Step 3: Add the results of step 1 and step 2
    wire [8:0] add_result = and_result + or_result;

    // Step 4: Compute the bitwise XOR of the results of step 1 and step 2
    wire [7:0] xor_result = and_result ^ or_result;

    // Step 5: Add 1 to the result of step 4
    wire [7:0] add_one = 1;
    wire [7:0] add_one_result = xor_result + add_one;

    // Step 6: Assign the result of step 5 to out
    always @(*) begin
        out = add_one_result;
    end

endmodule

