module keypad_to_7seg(
  input CLK,
  input RESET,
  input [3:0] COL,
  inout [3:0] ROW,
  output [6:0] SEG,
  output ANODE
);

  reg [3:0] row_sel = 4'b1110; // Initialize to 4th row selected
  reg [3:0] key_val = 4'b0000; // Initialize to no key pressed
  reg [3:0] key_val_last = 4'b0000; // Initialize to no key pressed
  reg [26:0] counter = 0; // Initialize counter for debouncing

  // Define 7-segment values for each number
  parameter [6:0] NUM_0 = 7'b0111111;
  parameter [6:0] NUM_1 = 7'b0000110;
  parameter [6:0] NUM_2 = 7'b1011011;
  parameter [6:0] NUM_3 = 7'b1001111;
  parameter [6:0] NUM_4 = 7'b1100110;
  parameter [6:0] NUM_5 = 7'b1101101;
  parameter [6:0] NUM_6 = 7'b1111101;
  parameter [6:0] NUM_7 = 7'b0000111;
  parameter [6:0] NUM_8 = 7'b1111111;
  parameter [6:0] NUM_9 = 7'b1101111;

  // Define an array to store the 7-segment values for each number
  reg [6:0] num_array [0:9];

  // Initialize the num_array with the defined values
  initial begin
    num_array[0] = NUM_0;
    num_array[1] = NUM_1;
    num_array[2] = NUM_2;
    num_array[3] = NUM_3;
    num_array[4] = NUM_4;
    num_array[5] = NUM_5;
    num_array[6] = NUM_6;
    num_array[7] = NUM_7;
    num_array[8] = NUM_8;
    num_array[9] = NUM_9;
  end

  // Define the logic for selecting the row
  always @(posedge CLK) begin
    if (counter < 27) begin
      counter <= counter + 1;
    end else begin
      counter <= 0;
      ROW <= row_sel;
      row_sel <= {row_sel[2:0], row_sel[3]};
    end
  end

  // Define the logic for reading the keypad and displaying the value
  always @(posedge CLK) begin
    if (RESET) begin
      SEG <= NUM_0;
      ANODE <= 1;
      key_val <= 4'b0000;
      key_val_last <= 4'b0000;
    end else begin
      key_val <= {COL, ROW} & 4'b1111;
      if (key_val != key_val_last) begin
        key_val_last <= key_val;
        if (key_val != 4'b0000) begin
          SEG <= num_array[key_val];
          ANODE <= 0;
        end else begin
          SEG <= NUM_0;
          ANODE <= 1;
        end
      end else begin
        if (key_val != 4'b0000) begin
          ANODE <= 0;
        end else begin
          ANODE <= 1;
        end
      end
    end
  end

endmodule

