module fg_burst_gen (
    input clk,
    input rst,
    input input_fd_valid,
    output input_fd_ready,
    input [7:0] input_fd_dest,
    input [15:0] input_fd_rate_num,
    input [15:0] input_fd_rate_denom,
    input [31:0] input_fd_len,
    input [31:0] input_fd_burst_len,
    output output_bd_valid,
    input output_bd_ready,
    output [7:0] output_bd_dest,
    output [31:0] output_bd_burst_len,
    output busy,
    output [4:0] active_flows
);

// Parameters
parameter FLOW_ADDR_WIDTH = 5;
parameter DEST_WIDTH = 8;
parameter RATE_SCALE = 8;

// Internal signals
reg [7:0] dest;
reg [31:0] burst_len;
reg [31:0] len;
reg [15:0] rate_num;
reg [15:0] rate_denom;
reg [31:0] tokens;
reg [31:0] burst_tokens;
reg [31:0] rate;
reg [31:0] burst_rate;
reg [31:0] burst_count;
reg [31:0] burst_count_max;
reg [4:0] active_flow;
reg busy_reg;

// State machine states
parameter IDLE = 2'b00;
parameter BURST = 2'b01;

// State machine signals
reg [1:0] state;
reg [31:0] count;

// Output signals
reg output_bd_valid_reg;
reg [7:0] output_bd_dest_reg;
reg [31:0] output_bd_burst_len_reg;
reg busy_reg;

// Initialize state machine
initial begin
    state = IDLE;
    count = 0;
end

// Update active flow list
always @(posedge clk) begin
    if (rst) begin
        active_flows <= 0;
    end else if (state == IDLE && input_fd_valid) begin
        active_flows <= {active_flows, input_fd_dest};
    end else if (state == BURST && burst_count == burst_count_max) begin
        active_flows <= {active_flows[3:0], 0};
    end
end

// Update state machine
always @(posedge clk) begin
    if (rst) begin
        state <= IDLE;
        count <= 0;
        input_fd_ready <= 1;
        output_bd_valid_reg <= 0;
        output_bd_dest_reg <= 0;
        output_bd_burst_len_reg <= 0;
        busy_reg <= 0;
    end else begin
        case (state)
            IDLE: begin
                if (input_fd_valid && output_bd_ready) begin
                    // Get flow parameters
                    dest <= input_fd_dest;
                    len <= input_fd_len;
                    rate_num <= input_fd_rate_num;
                    rate_denom <= input_fd_rate_denom;
                    tokens <= 0;
                    burst_tokens <= 0;
                    rate <= (rate_num << RATE_SCALE) / rate_denom;
                    burst_rate <= (input_fd_burst_len << RATE_SCALE) / input_fd_len;
                    burst_count_max <= input_fd_len / input_fd_burst_len;
                    burst_count <= 0;

                    // Update state machine
                    state <= BURST;
                    count <= 0;
                    input_fd_ready <= 0;
                    output_bd_valid_reg <= 1;
                    output_bd_dest_reg <= dest;
                    output_bd_burst_len_reg <= input_fd_burst_len;
                    busy_reg <= 1;
                end else begin
                    input_fd_ready <= 1;
                    output_bd_valid_reg <= 0;
                    output_bd_dest_reg <= 0;
                    output_bd_burst_len_reg <= 0;
                    busy_reg <= 0;
                end
            end
            BURST: begin
                count <= count + rate;
                tokens <= tokens + rate;
                burst_tokens <= burst_tokens + burst_rate;
                if (burst_tokens >= (1 << RATE_SCALE)) begin
                    burst_count <= burst_count + 1;
                    burst_tokens <= burst_tokens - (1 << RATE_SCALE);
                    output_bd_valid_reg <= 1;
                    output_bd_dest_reg <= dest;
                    output_bd_burst_len_reg <= input_fd_burst_len;
                end else begin
                    output_bd_valid_reg <= 0;
                    output_bd_dest_reg <= 0;
                    output_bd_burst_len_reg <= 0;
                end
                if (count >= (1 << RATE_SCALE)) begin
                    count <= count - (1 << RATE_SCALE);
                    tokens <= tokens - (1 << RATE_SCALE);
                end
                if (burst_count == burst_count_max && tokens >= len) begin
                    // Update state machine
                    state <= IDLE;
                    input_fd_ready <= 1;
                    output_bd_valid_reg <= 0;
                    output_bd_dest_reg <= 0;
                    output_bd_burst_len_reg <= 0;
                    busy_reg <= 0;
                end
            end
        endcase
    end
end

// Assign output signals
assign output_bd_valid = output_bd_valid_reg;
assign output_bd_dest = output_bd_dest_reg;
assign output_bd_burst_len = output_bd_burst_len_reg;
assign busy = busy_reg;

endmodule

module top (
    input             clk,      // 100MHz clock input, unused

    input             btnC,     // push button inputs
    input             btnU,
    input             btnD,
    input             btnR,
    input             btnL,

    input      [15:0] sw,       // slide switch inputs

