    output reg  [6:0] seg,      // 7-segment display outputs, active low
    output reg        dp,       // decimal point, active low
    output reg  [3:0] an        // common anodes, active low
);

    initial seg = 7'b1111111;   // clear 7-segment display

    initial an = 4'b1111;       // all digits enabled

    always @(btnC or btnU or btnD or btnR or btnL) begin
        // Buttons control the digit on 7-segment LED.
        seg[0] <= ~btnU;

        seg[1] <= ~btnR;
        seg[2] <= ~btnR;

        seg[3] <= ~btnD;

        seg[4] <= ~btnL;
        seg[5] <= ~btnL;

        seg[6] <= ~btnC;

        // Highlight the dot when no button pressed.
        dp <= ~(btnU | btnL | btnC | btnR | btnD);
    end

endmodule

module mul(clk, resetn, sa, dst, opB, opA, op, start, stalled, shift_result, lo, hi);

  // Inputs
  input clk;
  input resetn;
  input start;
  input [4:0] dst;
  input [31:0] opA;
  input [31:0] opB;
  input [4:0] sa;
  input [2:0] op;

  // Outputs
  output stalled;
  output [31:0] shift_result;
  output [31:0] lo;
  output [31:0] hi;

  // Internal signals
  wire is_signed;
  wire dir;
  wire is_mul;
  wire [32:0] opB_mux_out;
  wire [4:0] left_sa;
  reg [32:0] decoded_sa;
  wire [31:0] result;
  wire or_dst;
  wire start_and_ismul;
  wire request;

  // Control signals
  assign is_mul = op[2];
  assign is_signed = op[1];
  assign dir = op[0];

  // Multiplexer for opB input
  assign opB_mux_out = (is_mul) ? {is_signed & opB[31], opB} : decoded_sa;

  // Multiplication circuit
  dummy_mult fake_mult_one (opA, opB_mux_out, clk, resetn, result);
  assign hi = result[15:8];
  assign lo = result[7:0];

  // Shift amount decoder
  always @(*) begin
    if (dir == 0) begin
      decoded_sa = {27'b0, sa};
    end else begin
      decoded_sa = {sa, 27'b0};
    end
  end

  // Shift circuit
  assign shift_result = (dir & |sa) ? hi : lo;

  // Stall state machine
  assign or_dst = |dst;
  assign start_and_ismul = start & is_mul;
  assign request = (or_dst & start & ~is_mul) | (start_and_ismul);
  onecyclestall staller(request, clk, resetn, stalled);

endmodule

module top_module(
    input a, b,
    output xor_out, cout, sum);

    // Structural implementation of XOR gate using MUX
    wire mux_out;
    assign mux_out = (a ^ b) ? 1'b1 : 1'b0;
    assign xor_out = mux_out;

    // Half adder implementation using XOR and AND gates
    wire ha_xor_out, ha_and_out;
    assign ha_xor_out = a ^ b;
    assign ha_and_out = a & b;
    assign cout = ha_and_out;
    assign sum = ha_xor_out;

endmodule

