module shift_reg_mux (
    input wire clk,
    input wire rst_n,
    input wire [7:0] in_vec,
    output wire [7:0] out_vec,
    output wire msb_out,
    output wire mid_out,
    output wire lsb_out
);

reg [7:0] shift_reg;
wire [3:0] select;
wire shifted_out;

binary_number_module binary_number_module_inst (
    .binary_in(shift_reg[7:4]),
    .binary_out(select),
    .msb_out(msb_out),
    .mid_out(mid_out),
    .lsb_out(lsb_out)
);

assign shifted_out = shift_reg[0];
assign out_vec = {shift_reg[7:1], select};

always @(posedge clk) begin
    if (!rst_n) begin
        shift_reg <= 8'b0;
    end else begin
        shift_reg <= {shift_reg[6:0], in_vec};
    end
end

mux4to1 mux4to1_inst (
    .in0(shifted_out),
    .in1(8'b0),
    .in2(8'b0),
    .in3(8'b0),
    .sel(select),
    .out(out_vec[3:0])
);

