module mux4to1 (
    input wire [7:0] in0,
    input wire [7:0] in1,
    input wire [7:0] in2,
    input wire [7:0] in3,
    input wire [3:0] sel,
    output wire [7:0] out
);

assign out = (sel == 4'b0000) ? in0 :
             (sel == 4'b0001) ? in1 :
             (sel == 4'b0010) ? in2 :
             (sel == 4'b0011) ? in3 :
             8'b0;

endmodule

module top_module ( 
