module axis_packetizer #
(
  parameter integer AXIS_TDATA_WIDTH = 32,
  parameter integer CNTR_WIDTH = 32,
  parameter         CONTINUOUS = "FALSE",
  parameter         ALWAYS_READY = "FALSE"
)
(
  // System signals
  input  wire                        aclk,
  input  wire                        aresetn,

  input  wire [CNTR_WIDTH-1:0]       cfg_data,

  // Slave side
  output wire                        s_axis_tready,
  input  wire [AXIS_TDATA_WIDTH-1:0] s_axis_tdata,
  input  wire                        s_axis_tvalid,

  // Master side
  input  wire                        m_axis_tready,
  output wire [AXIS_TDATA_WIDTH-1:0] m_axis_tdata,
  output wire                        m_axis_tvalid,
  output wire                        m_axis_tlast
);

  reg [CNTR_WIDTH-1:0] int_cntr_reg, int_cntr_next;
  reg int_enbl_reg, int_enbl_next;

  wire int_comp_wire, int_tvalid_wire, int_tlast_wire;

  always @(posedge aclk)
  begin
    if(~aresetn)
    begin
      int_cntr_reg <= {(CNTR_WIDTH){1'b0}};
      int_enbl_reg <= 1'b0;
    end
    else
    begin
      int_cntr_reg <= int_cntr_next;
      int_enbl_reg <= int_enbl_next;
    end
  end

  assign int_comp_wire = int_cntr_reg < cfg_data;
  assign int_tvalid_wire = int_enbl_reg & s_axis_tvalid;
  assign int_tlast_wire = ~int_comp_wire;

  generate
    if(CONTINUOUS == "TRUE")
    begin : CONTINUOUS
      always @*
      begin
        int_cntr_next = int_cntr_reg;
        int_enbl_next = int_enbl_reg;

        if(~int_enbl_reg & int_comp_wire)
        begin
          int_enbl_next = 1'b1;
        end

        if(m_axis_tready & int_tvalid_wire & int_comp_wire)
        begin
          int_cntr_next = int_cntr_reg + 1'b1;
        end

        if(m_axis_tready & int_tvalid_wire & int_tlast_wire)
        begin
          int_cntr_next = {(CNTR_WIDTH){1'b0}};
        end
      end
    end
    else
    begin : STOP
      always @*
      begin
        int_cntr_next = int_cntr_reg;
        int_enbl_next = int_enbl_reg;

        if(~int_enbl_reg & int_comp_wire)
        begin
          int_enbl_next = 1'b1;
        end

        if(m_axis_tready & int_tvalid_wire & int_comp_wire)
        begin
          int_cntr_next = int_cntr_reg + 1'b1;
        end

        if(m_axis_tready & int_tvalid_wire & int_tlast_wire)
        begin
          int_enbl_next = 1'b0;
        end
      end
    end
  endgenerate

  generate
    if(ALWAYS_READY == "TRUE")
    begin : READY
      assign s_axis_tready = 1'b1;
    end
    else
    begin : BLOCKING
      assign s_axis_tready = int_enbl_reg & m_axis_tready;
    end
  endgenerate

  assign m_axis_tdata = s_axis_tdata;
  assign m_axis_tvalid = int_tvalid_wire;
  assign m_axis_tlast = int_enbl_reg & int_tlast_wire;

endmodule

module top_module (
    input [3:0] A,
    input [3:0] B,
    input shift,
    output [3:0] result
);

    wire [3:0] add_three_output;
    wire [3:0] barrel_shifter_output;
    wire [3:0] final_output;

    add_three_module add_three_inst(
        .A(A),
        .result(add_three_output)
    );

    barrel_shifter barrel_shifter_inst(
        .A(add_three_output),
        .B(B),
        .shift(shift),
        .result(barrel_shifter_output)
    );

    functional_module functional_inst(
        .add_three_output(add_three_output),
        .barrel_shifter_output(barrel_shifter_output),
        .final_output(final_output)
    );

    assign result = final_output;

endmodule

module add_three_module (
    input [3:0] A,
    output [3:0] result
);

    assign result = A + 3;

endmodule

module barrel_shifter (
    input [3:0] A,
    input [3:0] B,
    input shift,
    output [3:0] result
);

    assign result = shift ? (A + 3) << B : A + 3;

endmodule

module functional_module (
    input [3:0] add_three_output,
    input [3:0] barrel_shifter_output,
    output [3:0] final_output
);

    assign final_output = shift ? barrel_shifter_output : add_three_output;

endmodule

module encryption_system (
  input clk,
  input reset,
  input [3:0] data_in,
  output reg [3:0] encrypted_data
);

  reg [3:0] key = 4'b1010; // Fixed key value

  reg [3:0] adder_out; // Output of the ripple carry adder
  reg [3:0] shift_reg; // Shift register

  always @(posedge clk) begin
    if (reset) begin
      adder_out <= 4'b0;
      shift_reg <= 4'b0;
      encrypted_data <= 4'b0;
    end else begin
      // Add input data and key using ripple carry adder
      adder_out <= data_in + key;

      // Shift the output of the adder left by one bit
      shift_reg <= {adder_out[2:0], 1'b0};

      // Output the shifted data as encrypted data
      encrypted_data <= shift_reg;
    end
  end

endmodule

module BinaryMultiplier(Product, Multiplicant, Multiplier, Shift1, Shift0, reset, clock);
  input clock, reset;
  input [3:0] Multiplicant, Multiplier;
  input [2:0] Shift1, Shift0;
  output [7:0] Product;

  wire [3:0] MultiplierOut;
  wire [3:0] Sum;
  wire [3:0] QA, QB, QC, QD;
  reg CarryOut;

  //Multiplier shift register
  SN74194 MultiplierRegister(Multiplier,MultiplierOut,1'b0,1'b0,Shift1[2],Shift0[2],reset,clock);
  SN74157 MultiplicantMux(Multiplicant[3],1'b0,Multiplicant[2],1'b0,Multiplicant[1],1'b0,Multiplicant[0],1'b0,1'b0,MultiplierOut[0],QA,QB,QC,QD);

  //upper product
  SN7483 Adder1({QA,QB,QC,QD},Product[7:4],1'b0,CarryOut,Sum);
  SN74194 UpperProductRegister(Sum,Product[7:4],1'b0,CarryOut,Shift1[1],Shift0[1],reset,clock);

  //lower product
  SN74194 LowerProductRegister(4'd0,Product[3:0],1'b0,Product[4],Shift1[0],Shift0[0],reset,clock);

  always@(posedge clock or negedge reset) begin
    if(reset==0) begin
      CarryOut <= 0;
    end else begin
      CarryOut <= Sum[3];
    end
  end
endmodule

module Parity (
  input [n-1:0] d,
  output p, e
);

parameter n = 8; // number of data bits
parameter parity = "even"; // parity type (even or odd)

reg parity_bit;
wire [n-1:0] ones_count;
wire parity_match;

assign ones_count = {n{1'b0}} + d;
assign parity_match = (parity == "even") ? (ones_count % 2 == 0) : (ones_count % 2 == 1);

always @* begin
  if (parity == "even") begin
    parity_bit = (ones_count % 2 == 0) ? 1'b0 : 1'b1;
  end else begin
    parity_bit = (ones_count % 2 == 1) ? 1'b0 : 1'b1;
  end
end

assign p = parity_bit;
assign e = (parity_match) ? 1'b0 : 1'b1;

endmodule

module clock_gate (
    input CLK,
    input EN,
    input TE,
    output ENCLK
);

    reg gated_clk;

    always @ (posedge CLK) begin
        if (EN && !TE) begin
            gated_clk <= 1'b1;
        end else if (TE) begin
            gated_clk <= CLK;
        end else begin
            gated_clk <= 1'b0;
        end
    end

    assign ENCLK = gated_clk & EN;

endmodule

module multiplier (
    input [1:0] A, B,
    output [3:0] P,
    output CARRY
);

reg [1:0] a_reg, b_reg;
reg [3:0] p_reg;
reg carry_reg;

always @(posedge clk) begin
    a_reg <= A;
    b_reg <= B;
end

always @(posedge clk) begin
    p_reg <= {2'b0, a_reg[0] & b_reg[0]};
    carry_reg <= a_reg[0] & b_reg[0];
end

always @(posedge clk) begin
    p_reg <= p_reg + {1'b0, a_reg[1] & b_reg[0], a_reg[0] & b_reg[1]};
    carry_reg <= carry_reg | (a_reg[1] & b_reg[0]) | (a_reg[0] & b_reg[1]);
end

always @(posedge clk) begin
    p_reg <= p_reg + {1'b0, 1'b0, a_reg[1] & b_reg[1]};
    P <= p_reg;
    CARRY <= carry_reg;
end

endmodule

module shift_register (
    input clk,
    input SH_EN,
    input LD_EN,
    input [7:0] DATA_IN,
    output [7:0] SER_OUT,
    output [7:0] PAR_OUT
);

reg [7:0] shift_reg [0:1];
reg [7:0] parallel_out;

always @(posedge clk) begin
    if (LD_EN) begin
        shift_reg[0] <= DATA_IN;
        shift_reg[1] <= DATA_IN;
    end else if (SH_EN) begin
        shift_reg[0] <= {shift_reg[0][6:0], shift_reg[1][7]};
        shift_reg[1] <= {shift_reg[1][6:0], shift_reg[0][7]};
    end
end

assign SER_OUT = shift_reg[0];
assign PAR_OUT = parallel_out;

always @(shift_reg[0], shift_reg[1]) begin
    parallel_out = shift_reg[1];
end

endmodule

module USB_Host (
  input clk,
  input rst,
  input usb_dp,
  input usb_dm,
  output usb_pwr,
  output usb_suspend,
  output usb_reset,
  output usb_vbus
);

  // Define constants for USB protocol
  parameter IDLE = 2'b00;
  parameter SYNC = 2'b01;
  parameter DATA = 2'b10;
  parameter ERROR = 2'b11;

  // Define state machine states
  reg [1:0] state;
  parameter IDLE_STATE = 2'b00;
  parameter SYNC_STATE = 2'b01;
  parameter DATA_STATE = 2'b10;
  parameter ERROR_STATE = 2'b11;

  // Define variables for USB communication
  reg [7:0] tx_data;
  reg [7:0] rx_data;
  reg [1:0] tx_state;
  reg [1:0] rx_state;

  // Define variables for error detection and correction
  reg [7:0] crc;
  reg [7:0] tx_crc;
  reg [7:0] rx_crc;
  reg [1:0] error_state;

  // Define variables for USB power and suspend signals
  reg usb_pwr_reg;
  reg usb_suspend_reg;

  // Define variables for USB reset and voltage bus signals
  reg usb_reset_reg;
  reg usb_vbus_reg;

  // Define counter for USB data transfer rate
  reg [15:0] data_counter;

  // Define USB packet structure
  parameter PACKET_SIZE = 8;
  reg [PACKET_SIZE-1:0] packet;
  reg [PACKET_SIZE-1:0] tx_packet;
  reg [PACKET_SIZE-1:0] rx_packet;

  // Define USB initialization sequence
  initial begin
    state <= IDLE_STATE;
    tx_state <= IDLE;
    rx_state <= IDLE;
    error_state <= IDLE;
    data_counter <= 0;
    packet <= 0;
    tx_packet <= 0;
    rx_packet <= 0;
    crc <= 0;
    tx_crc <= 0;
    rx_crc <= 0;
    usb_pwr_reg <= 0;
    usb_suspend_reg <= 0;
    usb_reset_reg <= 0;
    usb_vbus_reg <= 0;
  end

  // Define USB communication state machine
  always @(posedge clk) begin
    if (rst) begin
      state <= IDLE_STATE;
      tx_state <= IDLE;
      rx_state <= IDLE;
      error_state <= IDLE;
      data_counter <= 0;
      packet <= 0;
      tx_packet <= 0;
      rx_packet <= 0;
      crc <= 0;
      tx_crc <= 0;
      rx_crc <= 0;
      usb_pwr_reg <= 0;
      usb_suspend_reg <= 0;
      usb_reset_reg <= 0;
      usb_vbus_reg <= 0;
    end
    else begin
      case (state)
        IDLE_STATE: begin
          // Wait for USB device to connect
          if (usb_dp && usb_dm) begin
            state <= SYNC_STATE;
          end
        end

        SYNC_STATE: begin
          // Send sync packet to USB device
          case (tx_state)
            IDLE: begin
              tx_packet <= {1'b0, 1'b1, 1'b0, 1'b1, 1'b0, 1'b1, 1'b0, 1'b1};
              tx_crc <= 8'hFF;
              tx_state <= SYNC;
              data_counter <= 0;
            end

            SYNC: begin
              if (data_counter < PACKET_SIZE) begin
                tx_data <= tx_packet[data_counter];
                data_counter <= data_counter + 1;
              end
              else begin
                tx_data <= tx_crc;
                tx_state <= DATA;
                data_counter <= 0;
              end
            end

            DATA: begin
              if (data_counter < PACKET_SIZE) begin
                tx_data <= packet[data_counter];
                data_counter <= data_counter + 1;
              end
              else begin
                tx_data <= crc;
                tx_state <= IDLE;
                data_counter <= 0;
              end
            end
          endcase

          // Receive sync packet from USB device
          case (rx_state)
            IDLE: begin
              rx_state <= SYNC;
              data_counter <= 0;
            end

            SYNC: begin
              if (data_counter < PACKET_SIZE) begin
                rx_packet[data_counter] <= rx_data;
                data_counter <= data_counter + 1;
              end
              else begin
                rx_crc <= rx_data;
                rx_state <= DATA;
                data_counter <= 0;
              end
            end

            DATA: begin
              if (data_counter < PACKET_SIZE) begin
                rx_packet[data_counter] <= rx_data;
                data_counter <= data_counter + 1;
              end
              else begin
                rx_crc <= rx_data;
                rx_state <= IDLE;
                data_counter <= 0;
              end
            end
          endcase

          // Check for errors in sync packet
          if (tx_state == IDLE && rx_state == IDLE) begin
            if (rx_packet == {1'b1, 1'b0, 1'b1, 1'b0, 1'b1, 1'b0, 1'b1, 1'b0}) begin
              state <= DATA_STATE;
            end
            else begin
              error_state <= ERROR;
            end
          end
        end

        DATA_STATE: begin
          // Send data packet to USB device
          case (tx_state)
            IDLE: begin
              tx_packet <= packet;
              tx_crc <= crc;
              tx_state <= DATA;
              data_counter <= 0;
            end

            DATA: begin
              if (data_counter < PACKET_SIZE) begin
                tx_data <= tx_packet[data_counter];
                data_counter <= data_counter + 1;
              end
              else begin
                tx_data <= tx_crc;
                tx_state <= IDLE;
                data_counter <= 0;
              end
            end
          endcase

          // Receive data packet from USB device
          case (rx_state)
            IDLE: begin
              rx_state <= DATA;
              data_counter <= 0;
            end

            DATA: begin
              if (data_counter < PACKET_SIZE) begin
                rx_packet[data_counter] <= rx_data;
                data_counter <= data_counter + 1;
              end
              else begin
                rx_crc <= rx_data;
                rx_state <= IDLE;
                data_counter <= 0;
              end
            end
          endcase

          // Check for errors in data packet
          if (tx_state == IDLE && rx_state == IDLE) begin
            if (rx_crc == crc) begin
              state <= IDLE_STATE;
            end
            else begin
              error_state <= ERROR;
            end
          end
        end

        ERROR_STATE: begin
          // Handle errors in USB communication
          // ...
        end
      endcase

      // Update USB power and suspend signals
      usb_pwr_reg <= 1;
      usb_suspend_reg <= 0;

      // Update USB reset and voltage bus signals
      usb_reset_reg <= 0;
      usb_vbus_reg <= 5;
    end
  end

  // Assign output signals
  assign usb_pwr = usb_pwr_reg;
  assign usb_suspend = usb_suspend_reg;
  assign usb_reset = usb_reset_reg;
  assign usb_vbus = usb_vbus_reg;

