  wire s1, s2, s3, s4; // intermediate sum signals

  // Full adder for bit 0
  sky130_fd_sc_ls__xor2 xor1(a[0], b[0], s1);
  sky130_fd_sc_ls__xor2 xor2(s1, cin, sum[0]);
  sky130_fd_sc_ls__and2 and1(a[0], b[0], c1);
  sky130_fd_sc_ls__and2 and2(s1, cin, c2);
