module max_detector(
    input clk, 
    input areset,  // Async active-high reset to zero
    input load,
    input ena,
    input [7:0] a, b, c, d,    // Four 8-bit unsigned numbers as input
    output [3:0] q);           // 4-bit output from the shift register.

    reg [7:0] max_value;    // Register to hold the maximum value
    reg [3:0] shift_reg;    // Shift register to hold the max value
    reg [1:0] priority;     // Priority encoder output

    always @(posedge clk or negedge areset) begin
        if(!areset) begin
            max_value <= 8'd0;
            shift_reg <= 4'd0;
            priority <= 2'd0;
        end
        else begin
            if(load) begin
                max_value <= a;
                shift_reg <= 4'd0;
                priority <= 2'd0;
            end
            else if(ena) begin
                priority <= 2'b00;
                if(b > max_value) begin
                    max_value <= b;
                    priority <= 2'b01;
                end
                if(c > max_value) begin
                    max_value <= c;
                    priority <= 2'b10;
                end
                if(d > max_value) begin
                    max_value <= d;
                    priority <= 2'b11;
                end
                shift_reg <= {shift_reg[2:0], priority}; // Shift left and add priority encoder output
            end
        end
    end

    assign q = shift_reg;

endmodule

