module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out
);

reg [9:0]   accu_reg;
reg [1:0]   stage;

assign ready_a = (stage == 0) ? 1'b1 : 1'b0;
assign valid_b = (stage == 1) ? 1'b1 : 1'b0;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        accu_reg <= 10'b0;
        stage <= 2'b00;
    end else begin
        case (stage)
            2'b00: begin
                if (valid_a) begin
                    accu_reg <= accu_reg + data_in;
                    stage <= 2'b01;
                end
            end
            2'b01: begin
                if (valid_a && ready_b) begin
                    accu_reg <= accu_reg + data_in;
                    stage <= 2'b10;
                end
            end
            2'b10: begin
                if (valid_a && ready_b) begin
                    accu_reg <= accu_reg + data_in;
                    stage <= 2'b11;
                end
            end
            2'b11: begin
                if (valid_a && ready_b) begin
                    accu_reg <= accu_reg + data_in;
                    data_out <= accu_reg;
                    accu_reg <= 10'b0;
                    stage <= 2'b00;
                end
            end
        endcase
    end
end

endmodule

