    else if (counter < pulse_width) begin
      pwm_output <= 1;
      counter <= counter + 1;
    end
    else begin
      pwm_output <= 0;
      counter <= counter + 1;
    end
  end

  always @ (posedge clk) begin
    pulse_width <= (duty_cycle * 1000) / (2**32);
  end

endmodule

