module dcfifo_32in_32out_16kb_synchronizer
  (D,
   Q,
   rd_clk,
   wr_clk,
   rd_en,
   wr_en,
   empty,
   full,
   almost_full,
   almost_empty);

  parameter DEPTH = 16384;
  parameter WIDTH = 32;
  parameter ADDR_WIDTH = $clog2(DEPTH);

  input [WIDTH-1:0] D;
  output [WIDTH-1:0] Q;
  input rd_clk;
  input wr_clk;
  input rd_en;
  input wr_en;
  output empty;
  output full;
  output almost_full;
  output almost_empty;

  reg [WIDTH-1:0] fifo [0:DEPTH-1];
  reg [ADDR_WIDTH-1:0] wr_ptr;
  reg [ADDR_WIDTH-1:0] rd_ptr;
  reg [ADDR_WIDTH-1:0] count;
  reg [ADDR_WIDTH-1:0] next_wr_ptr;
  reg [ADDR_WIDTH-1:0] next_rd_ptr;
  reg [ADDR_WIDTH-1:0] next_count;
  wire [ADDR_WIDTH-1:0] count_plus_one = count + 1;
  wire [ADDR_WIDTH-1:0] count_minus_one = count - 1;
  wire [ADDR_WIDTH-1:0] count_plus_two = count + 2;
  wire [ADDR_WIDTH-1:0] count_minus_two = count - 2;

  // Write logic
  always @(posedge wr_clk) begin
    if (wr_en && !full) begin
      fifo[wr_ptr] <= D;
      next_wr_ptr <= wr_ptr + 1;
      next_count <= count_plus_one;
    end else begin
      next_wr_ptr <= wr_ptr;
      next_count <= count;
    end
  end

  // Read logic
  always @(posedge rd_clk) begin
    if (rd_en && !empty) begin
      Q <= fifo[rd_ptr];
      next_rd_ptr <= rd_ptr + 1;
      next_count <= count_minus_one;
    end else begin
      next_rd_ptr <= rd_ptr;
      next_count <= count;
    end
  end

  // Pointer and count logic
  always @* begin
    empty = (count == 0);
    full = (count == DEPTH);
    almost_full = (count >= DEPTH - 1);
    almost_empty = (count <= 1);
    wr_ptr = next_wr_ptr;
    rd_ptr = next_rd_ptr;
    count = next_count;
  end

endmodule

