module check_tpu (
    input clk,
    input reset,
    output reg timeprecision,
    output reg timeunit
);

    // Internal state variables
    reg [31:0] counter;
    reg [31:0] last_time;
    reg [31:0] current_time;

    // Constants
    parameter TIME_PRECISION = 10000; // 10 microseconds in picoseconds
    parameter TIME_UNIT = 10000; // 10 microseconds in picoseconds

    // Reset state
    always @ (posedge clk, posedge reset) begin
        if (reset) begin
            timeprecision <= 0;
            timeunit <= 0;
            counter <= 0;
            last_time <= 0;
            current_time <= 0;
        end
    end

    // Check time precision and unit
    always @ (posedge clk) begin
        // Increment counter
        counter <= counter + 1;

        // Get current time
        current_time <= $time;

        // Check time precision
        if (counter == TIME_PRECISION) begin
            if (current_time - last_time == TIME_PRECISION) begin
                timeprecision <= 1;
            end else begin
                timeprecision <= 0;
            end
            last_time <= current_time;
            counter <= 0;
        end

        // Check time unit
        if (current_time % TIME_UNIT == 0) begin
            timeunit <= 1;
        end else begin
            timeunit <= 0;
        end
    end

endmodule

