endmodule

module shift_register_twos_comp (
    input clk,
    input reset,
    input [3:0] D,
    input SI,
    output reg [3:0] twos_comp,
    output reg SO
);

reg [3:0] shift_reg;

always @(posedge clk) begin
    if (reset) begin
        shift_reg <= 4'b0000;
    end else begin
        shift_reg <= {shift_reg[2:0], SI};
        if (D != 4'b0000) begin
            shift_reg <= D;
        end
    end
end

assign SO = shift_reg[0];

always @* begin
    if (shift_reg[3] == 1) begin
        twos_comp = ~(shift_reg[2:0]) + 1;
    end else begin
        twos_comp = shift_reg[2:0];
    end
end

endmodule

module apu_div
#(
  parameter PERIOD_BITS = 16
)
(
  input                    clk_in,     // system clock signal
  input                    rst_in,     // reset signal
  input                    pulse_in,   // input pulse
  input                    reload_in,  // reset counter to period_in (no pulse_out generated)
  input  [PERIOD_BITS-1:0] period_in,  // new period value
  output                   pulse_out   // divided output pulse
);

reg  [PERIOD_BITS-1:0] q_cnt;
wire [PERIOD_BITS-1:0] d_cnt;

always @(posedge clk_in)
  begin
    if (rst_in)
      q_cnt <= 0;
    else
      q_cnt <= d_cnt;
  end

assign d_cnt     = (reload_in || (pulse_in && (q_cnt == 0))) ? period_in    :
                   (pulse_in)                                ? q_cnt - 1'h1 : q_cnt;
assign pulse_out = pulse_in && (q_cnt == 0);

endmodule

module eight_bit_comparator (
    input [7:0] A,
    input [7:0] B,
    output equal,
    output A_greater_than_B,
    output A_less_than_B
);

reg [7:0] A_reg, B_reg;
reg [2:0] stage;

assign equal = (A_reg == B_reg);
assign A_greater_than_B = (A_reg > B_reg);
assign A_less_than_B = (A_reg < B_reg);

always @(*) begin
    case(stage)
        0: begin
            A_reg = A;
            B_reg = B;
        end
        1: begin
            A_reg = A_reg >> 1;
            B_reg = B_reg >> 1;
        end
        2: begin
            A_reg = A_reg >> 2;
            B_reg = B_reg >> 2;
        end
        3: begin
            A_reg = A_reg >> 4;
            B_reg = B_reg >> 4;
        end
    endcase
end

always @(posedge clk) begin
    if (stage == 3) begin
        stage <= 0;
    end else begin
        stage <= stage + 1;
    end
end

endmodule

module top_module (
