    output reg [7:0] out_final
);

    // XOR module
    assign out_xor = in1 ^ in2;

    // AND module
    assign out_and = in1 & in2 & in3;

    // Additive functional module
    always @ (posedge clk) begin
        out_final <= out_xor + out_and;
    end

endmodule

module binary_to_BCD(A,ONES,TENS,HUNDREDS);
	input [7:0] A;
	output [3:0] ONES, TENS;
	output [3:0] HUNDREDS;
	wire [3:0] c1,c2,c3,c4,c5,c6,c7;
	wire [3:0] d1,d2,d3,d4,d5,d6,d7;

	// Extract the 4 most significant bits of the input and convert them to BCD
	assign d1 = {1'b0,A[7:5]};
	add3 m1(d1,c1);
	assign d6 = {1'b0,c1[3],c2[3],c3[3]};
	add3 m6(d6,c6);
	assign HUNDREDS = {2'b00, c6[3],c7[3]};

	// Extract the next 4 bits of the input and convert them to BCD
	assign d2 = {c1[2:0],A[4]};
	add3 m2(d2,c2);
	assign d3 = {c2[2:0],A[3]};
	add3 m3(d3,c3);
	assign d7 = {c6[2:0],c4[3]};
	add3 m7(d7,c7);
	assign TENS = {c7[2:0],c5[3]};

	// Extract the last 4 bits of the input and convert them to BCD
	assign d4 = {c3[2:0],A[2]};
	add3 m4(d4,c4);
	assign d5 = {c4[2:0],A[1]};
	add3 m5(d5,c5);
	assign ONES = {c5[2:0],A[0]};

endmodule

module add3(a,b,sum,carry);
	input [3:0] a,b;
	output [3:0] sum;
	output carry;

	assign sum = a + b + carry;
	assign carry = (a[3] & b[3]) | (a[3] & carry) | (b[3] & carry);

endmodule

