module cycloneii_m_cntr   ( clk,
                            reset,
                            cout,
                            initial_value,
                            modulus,
                            time_delay);

    // INPUT PORTS
    input clk;
    input reset;
    input [31:0] initial_value;
    input [31:0] modulus;
    input [31:0] time_delay;

    // OUTPUT PORTS
    output cout;

    // INTERNAL VARIABLES AND NETS
    reg [31:0] count;
    reg tmp_cout;
    reg first_rising_edge;
    reg clk_last_value;
    reg cout_tmp;

    initial
    begin
        count = initial_value;
        first_rising_edge = 1;
        clk_last_value = 0;
    end

    always @(posedge clk or posedge reset)
    begin
        if (reset)
        begin
            count <= initial_value;
            tmp_cout <= 0;
            first_rising_edge <= 1;
            cout_tmp <= tmp_cout;
        end
        else begin
            if (first_rising_edge)
            begin
                first_rising_edge <= 0;
                tmp_cout <= 1'b0;
                cout_tmp <= #(time_delay) tmp_cout;
            end
            else if (count < modulus-1)
            begin
                count <= count + 1;
                tmp_cout <= 1'b0;
                cout_tmp <= #(time_delay) tmp_cout;
            end
            else
            begin
                count <= initial_value;
                tmp_cout <= 1'b1;
                cout_tmp <= #(time_delay) tmp_cout;
            end
        end
        clk_last_value <= clk;
    end

    assign cout = cout_tmp;

endmodule

module serial_fifo_buffer (
  input wire s_axi_aclk,
  input wire s_axi_aresetn,
  input wire fifo_wr,
  input wire tx_Start,
  input wire tx_Data_Enable_reg,
  input wire [7:0] tx_DataBits,
  input wire [7:0] s_axi_wdata,
  input wire p_4_in,
  input wire fifo_Read,
  input wire reset_TX_FIFO_reg,
  input wire mux_sel_reg_0,
  input wire mux_sel_reg_2,
  output wire tx_Buffer_Full,
  output wire mux_Out,
  output wire [0:0] Q,
  output wire tx_Start0
);

  reg [3:0] write_ptr;
  reg [3:0] read_ptr;
  reg [7:0] fifo [15:0];
  reg tx_Buffer_Full;

  always @(posedge s_axi_aclk) begin
    if (~s_axi_aresetn) begin
      write_ptr <= 0;
      read_ptr <= 0;
      tx_Buffer_Full <= 0;
    end else begin
      if (fifo_wr && !tx_Buffer_Full) begin
        fifo[write_ptr] <= s_axi_wdata;
        write_ptr <= write_ptr + 1;
        if (write_ptr == 15) begin
          write_ptr <= 0;
        end
        if (write_ptr == read_ptr) begin
          tx_Buffer_Full <= 1;
        end
      end
      if (fifo_Read) begin
        Q <= fifo[read_ptr];
        read_ptr <= read_ptr + 1;
        if (read_ptr == 15) begin
          read_ptr <= 0;
        end
        tx_Buffer_Full <= 0;
      end
    end
  end

  assign mux_Out = mux_sel_reg_0 ? tx_DataBits : p_4_in;
  assign tx_Start0 = tx_Start && tx_Data_Enable_reg;

endmodule

module game(input clk,
            input [9:0] xpos,
            input [9:0] ypos,
            input rota,
            input rotb,
            output [2:0] red,
            output [2:0] green,
            output [1:0] blue);

    // paddle movement
    reg [8:0] paddlePosition;
    reg [2:0] quadAr, quadBr;
    always @(posedge clk) quadAr <= {quadAr[1:0], rota};
    always @(posedge clk) quadBr <= {quadBr[1:0], rotb};

    always @(posedge clk)
    if(quadAr[2] ^ quadAr[1] ^ quadBr[2] ^ quadBr[1])
    begin
        if(quadAr[2] ^ quadBr[1]) begin
            if(paddlePosition < 508)        // make sure the value doesn't overflow
                paddlePosition <= paddlePosition + 9'd4;
        end
        else begin
            if(paddlePosition > 3)        // make sure the value doesn't underflow
                paddlePosition <= paddlePosition - 9'd4;
        end
    end

    // ball movement
    reg [9:0] ballX;
    reg [8:0] ballY;
    reg ballXdir, ballYdir;
    reg bounceX, bounceY;

    wire endOfFrame = (xpos == 0 && ypos == 480);

    always @(posedge clk) begin
        if (endOfFrame) begin // update ball position at end of each frame
            if (ballX == 0 && ballY == 0) begin // cheesy reset handling, assumes initial value of 0
                ballX <= 480;
                ballY <= 300;
            end
            else begin
                if (ballXdir ^ bounceX) 
                    ballX <= ballX + 10'd2;
                else 
                    ballX <= ballX - 10'd2;

                if (ballYdir ^ bounceY) 
                    ballY <= ballY + 9'd2;
                else
                    ballY <= ballY - 9'd2;
            end
        end    
    end    

    // pixel color
    reg [5:0] missTimer;    
    wire visible = (xpos < 640 && ypos < 480);
    wire top = (visible && ypos <= 3);
    wire bottom = (visible && ypos >= 476);
    wire left = (visible && xpos <= 3);
    wire right = (visible && xpos >= 636);
    wire border = (visible && (left || right || top));
    wire paddle = (xpos >= paddlePosition+4 && xpos <= paddlePosition+124 && ypos >= 440 && ypos <= 447);
    wire ball = (xpos >= ballX && xpos <= ballX+7 && ypos >= ballY && ypos <= ballY+7);
    wire background = (visible && !(border || paddle || ball));
    wire checkerboard = (xpos[5] ^ ypos[5]);
    wire missed = visible && missTimer != 0;

    assign red   = { missed || border || paddle, paddle, paddle};
    assign green = { !missed && (border || paddle || ball), ball, ball};
    assign blue  = { !missed && (border || ball), background && checkerboard}; 

    // ball collision
    always @(posedge clk) begin
        if (!endOfFrame) begin
            if (ball && (left || right))
                bounceX <= 1;
            if (ball && (top || bottom || (paddle && ballYdir)))
                bounceY <= 1;
            if (ball && bottom)
                missTimer <= 63;
        end
        else begin
            if (ballX == 0 && ballY == 0) begin // cheesy reset handling, assumes initial value of 0
                ballXdir <= 1;
                ballYdir <= 1;
                bounceX <= 0;
                bounceY <= 0;
            end 
            else begin
                if (bounceX)
                    ballXdir <= ~ballXdir;
                if (bounceY)
                    ballYdir <= ~ballYdir;            
                bounceX <= 0;
                bounceY <= 0;
                if (missTimer != 0)
                    missTimer <= missTimer - 6'd1;
            end
        end
    end

endmodule

module johnson_counter (
    input clk,
    input reset,
    output reg [2:0] count
);

reg [2:0] count_reg1, count_reg2, count_reg3;

always @(posedge clk) begin
    if (reset) begin
        count_reg1 <= 3'b000;
        count_reg2 <= 3'b000;
        count_reg3 <= 3'b000;
    end else begin
        count_reg1 <= count_reg2;
        count_reg2 <= count_reg3;
        count_reg3 <= ~{count_reg2[1:0], count_reg2[2]};
    end
end

assign count = count_reg1;

endmodule

