module top_module (
    input [3:0] A, B, // Two 4-bit inputs
    input carry_in, // Carry input for the ripple carry adder
    output [3:0] sum, // 4-bit output from the ripple carry adder
    output carry_out, // Carry output from the ripple carry adder
    output EQ, GT, LT // Comparison outputs from the functional module
);

    // Ripple carry adder
    wire [3:0] adder_out;
    wire carry_out_internal;
    ripple_carry_adder adder(.A(A), .B(B), .carry_in(carry_in), .sum(adder_out), .carry_out(carry_out_internal));

    // Output sum and carry_out from the adder
    assign sum = adder_out;
    assign carry_out = carry_out_internal;

    // Functional module for comparison
    assign EQ = (A == B);
    assign GT = (A > B);
    assign LT = (A < B);

endmodule

// Ripple carry adder module
module ripple_carry_adder (
    input [3:0] A, B, // Two 4-bit inputs
    input carry_in, // Carry input
    output [3:0] sum, // 4-bit output from the adder
    output carry_out // Carry output from the adder
);

    wire [3:0] sum_internal;
    wire [3:0] carry_out_internal;

    // Full adder for the least significant bit
    full_adder adder0(.A(A[0]), .B(B[0]), .carry_in(carry_in), .sum(sum_internal[0]), .carry_out(carry_out_internal[0]));

    // Ripple carry adder for the remaining bits
    genvar i;
    generate
        for (i = 1; i < 4; i = i + 1) begin : adder_loop
            full_adder adder(.A(A[i]), .B(B[i]), .carry_in(carry_out_internal[i-1]), .sum(sum_internal[i]), .carry_out(carry_out_internal[i]));
        end
    endgenerate

    // Output sum and carry_out from the adder
    assign sum = sum_internal;
    assign carry_out = carry_out_internal[3];

endmodule

// Full adder module
module full_adder (
    input A, B, carry_in, // Three inputs
    output sum, carry_out // Two outputs
);

    assign sum = A ^ B ^ carry_in;
    assign carry_out = (A & B) | (carry_in & (A ^ B));

endmodule

module johnson_counter (
  input clk,
  output [n-1:0] out
);

  parameter n = 4; // number of output signals

  reg [n-1:0] state;
  wire [n-1:0] next_state;

  assign out = state;

  always @ (posedge clk) begin
    state <= next_state;
  end

  assign next_state[0] = state[n-1] ^ state[0];
  assign next_state[1] = state[0] ^ state[1];
  assign next_state[2] = state[1] ^ state[2];
  assign next_state[3] = state[2] ^ state[3];

endmodule

module BinaryToBCD (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 8; // number of input bits
parameter m = 10; // number of output bits (4 bits for each decimal digit)

reg [3:0] bcd [0:(n/4)-1];

integer i;

always @(*) begin
  for (i = 0; i < n/4; i = i + 1) begin
    case (in[i*4 +: 4])
      4'b0000: bcd[i] = 4'b0000;
      4'b0001: bcd[i] = 4'b0001;
      4'b0010: bcd[i] = 4'b0010;
      4'b0011: bcd[i] = 4'b0011;
      4'b0100: bcd[i] = 4'b0100;
      4'b0101: bcd[i] = 4'b0101;
      4'b0110: bcd[i] = 4'b0110;
      4'b0111: bcd[i] = 4'b0111;
      4'b1000: bcd[i] = 4'b1000;
      4'b1001: bcd[i] = 4'b1001;
      default: bcd[i] = 4'b0000;
    endcase
  end
end

assign out = {bcd[0:(n/4)-1]};

endmodule

module edge_detector (
    input clk,
    input reset,
    input [7:0] in,
    output [7:0] out
);
    reg [7:0] delayed_in;

    always @(posedge clk) begin
        if (reset) begin
            delayed_in <= 8'b0;
        end else begin
            delayed_in <= in;
        end
    end

    assign out = delayed_in;

endmodule

module word_splitter (
    input clk,
    input reset,
    input [15:0] in,
    output [7:0] out_hi,
    output [7:0] out_lo
);
    assign out_hi = in[15:8];
    assign out_lo = in[7:0];

endmodule

module functional_module (
    input [7:0] anyedge_out,
    input [7:0] out_hi,
    input [7:0] out_lo,
    output [7:0] final_out
);
    assign final_out = anyedge_out + out_hi + out_lo;

endmodule

module control_logic (
    input select,
    input [7:0] anyedge_out,
    input [7:0] out_hi,
    input [7:0] out_lo,
    output [7:0] final_out
);
    wire [7:0] delayed_out;
    edge_detector edge_detector_inst (
        .clk(clk),
        .reset(reset),
        .in(anyedge_out),
        .out(delayed_out)
    );
    word_splitter word_splitter_inst (
        .clk(clk),
        .reset(reset),
        .in(word_in),
        .out_hi(out_hi),
        .out_lo(out_lo)
    );
    functional_module functional_module_inst (
        .anyedge_out(delayed_out),
        .out_hi(out_hi),
        .out_lo(out_lo),
        .final_out(final_out)
    );

    assign final_out = select ? functional_module_inst.final_out : word_in;

endmodule

module top_module (
