module a311o_testbench;
    // Inputs
    reg A1, A2, A3, B1, C1, VPWR, VGND, VPB, VNB;

    // Outputs
    wire X;

    // Instantiate the Unit Under Test (UUT)
    sky130_fd_sc_ls__a311o uut (
        .X(X),
        .A1(A1),
        .A2(A2),
        .A3(A3),
        .B1(B1),
        .C1(C1),
        .VPWR(VPWR),
        .VGND(VGND),
        .VPB(VPB),
        .VNB(VNB)
    );

    initial begin
        // Initialize Inputs
        A1 = 0; A2 = 0; A3 = 0; B1 = 0; C1 = 0; VPWR = 0; VGND = 1; VPB = 0; VNB = 0;

        // Wait 100 ns for global reset to finish
        #100;

        // Test case 1
        A1 = 1; A2 = 1; A3 = 1; B1 = 0; C1 = 1; VPWR = 1; VGND = 0; VPB = 0; VNB = 0;
        #10;
        if (X !== 1'b1) $error("Test case 1 failed");

        // Test case 2
        A1 = 0; A2 = 1; A3 = 1; B1 = 1; C1 = 0; VPWR = 1; VGND = 0; VPB = 0; VNB = 0;
        #10;
        if (X !== 1'b1) $error("Test case 2 failed");

        // Test case 3
        A1 = 0; A2 = 0; A3 = 0; B1 = 0; C1 = 0; VPWR = 1; VGND = 0; VPB = 0; VNB = 0;
        #10;
        if (X !== 1'b0) $error("Test case 3 failed");

        // Test case 4
        A1 = 1; A2 = 1; A3 = 1; B1 = 0; C1 = 0; VPWR = 0; VGND = 0; VPB = 0; VNB = 0;
        #10;
        if (X !== 1'b0) $error("Test case 4 failed");

        $display("All test cases passed");
        $finish;
    end

endmodule

module two_bit_sat_counter (
    input [1:0] count_i,
    input op,
    output [1:0] count
);

    always @*
    begin
        case (count_i)
            2'b00: count = op ? 2'b01 : 2'b00;
            2'b01: count = op ? 2'b10 : 2'b00;
            2'b10: count = op ? 2'b10 : 2'b01;
            2'b11: count = op ? 2'b11 : 2'b10;
        endcase
    end

endmodule

module binary_adder(
    input [3:0] A,
    input [3:0] B,
    input CTRL,
    output reg [3:0] C
);

    // Module supplies
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    always @(*) begin
        if(CTRL == 0) begin
            C = A + B;
        end else begin
            C = {1'b0, A[3:1]} + {1'b0, B[3:1]};
        end
    end

endmodule

module binary_up_counter (input clk, input reset, output reg [3:0] count);

	always @(posedge clk) begin
		if (reset) begin
			count <= 4'd0;
		end else begin
			count <= count + 1;
		end
	end

endmodule

module processor_reset(
  input slowest_sync_clk,
  input ext_reset_in,
  input aux_reset_in,
  input mb_debug_sys_rst,
  input dcm_locked,
  output mb_reset,
  output reg [0:0] bus_struct_reset,
  output reg [0:0] peripheral_reset,
  output reg [0:0] interconnect_aresetn,
  output reg [0:0] peripheral_aresetn
);

  (* C_AUX_RESET_HIGH = "1'b0" *) 
  (* C_AUX_RST_WIDTH = "4" *) 
  (* C_EXT_RESET_HIGH = "1'b1" *) 
  (* C_EXT_RST_WIDTH = "4" *) 
  (* C_FAMILY = "artix7" *) 
  (* C_NUM_BUS_RST = "1" *) 
  (* C_NUM_INTERCONNECT_ARESETN = "1" *) 
  (* C_NUM_PERP_ARESETN = "1" *) 

  reg [3:0] ext_rst_count;
  reg [3:0] aux_rst_count;
  reg [3:0] debug_rst_count;
  reg [3:0] dcm_count;

  always @(posedge slowest_sync_clk) begin
    if (ext_reset_in == 1'b1) begin
      ext_rst_count <= ext_rst_count + 1;
      if (ext_rst_count >= C_EXT_RST_WIDTH) begin
        mb_reset <= 1'b1;
        bus_struct_reset <= 1'b1;
        peripheral_reset <= 1'b1;
        interconnect_aresetn <= 1'b1;
        peripheral_aresetn <= 1'b1;
      end
    end else begin
      ext_rst_count <= 0;
    end

    if (aux_reset_in == 1'b1) begin
      aux_rst_count <= aux_rst_count + 1;
      if (aux_rst_count >= C_AUX_RST_WIDTH) begin
        mb_reset <= 1'b1;
        bus_struct_reset <= 1'b1;
        peripheral_reset <= 1'b1;
        interconnect_aresetn <= 1'b1;
        peripheral_aresetn <= 1'b1;
      end
    end else begin
      aux_rst_count <= 0;
    end

    if (mb_debug_sys_rst == 1'b1) begin
      debug_rst_count <= debug_rst_count + 1;
      if (debug_rst_count >= 1) begin
        mb_reset <= 1'b1;
        bus_struct_reset <= 1'b1;
        peripheral_reset <= 1'b1;
        interconnect_aresetn <= 1'b1;
        peripheral_aresetn <= 1'b1;
      end
    end else begin
      debug_rst_count <= 0;
    end

    if (dcm_locked == 1'b0) begin
      mb_reset <= 1'b0;
      bus_struct_reset <= 1'b0;
      peripheral_reset <= 1'b0;
      interconnect_aresetn <= 1'b0;
      peripheral_aresetn <= 1'b0;
    end else begin
      dcm_count <= dcm_count + 1;
      if (dcm_count >= C_NUM_BUS_RST) begin
        mb_reset <= 1'b1;
      end
      if (dcm_count >= C_NUM_INTERCONNECT_ARESETN) begin
        interconnect_aresetn <= 1'b1;
      end
      if (dcm_count >= C_NUM_PERP_ARESETN) begin
        peripheral_aresetn <= 1'b1;
      end
      if (dcm_count >= (C_NUM_BUS_RST + C_NUM_INTERCONNECT_ARESETN + C_NUM_PERP_ARESETN)) begin
        bus_struct_reset <= 1'b1;
        peripheral_reset <= 1'b1;
      end
    end
  end

endmodule

module red_pitaya_iq_lpf_block #(
    parameter     ALPHABITS = 25,
    parameter     HIGHESTALPHABIT = 18,
    parameter     LPFBITS   = 18
)
(
    input clk_i,
    input reset_i,
    input signed [HIGHESTALPHABIT-1:0] alpha_i, 
    input signed [LPFBITS-1:0] signal_i,
    output signed [LPFBITS-1:0] signal_o
);

reg  signed [ALPHABITS+LPFBITS-1:0] y;
reg  signed [ALPHABITS+LPFBITS-1:0] delta;

always @(posedge clk_i) begin
    if (reset_i == 1'b1) begin
        y <=            {ALPHABITS+LPFBITS{1'b0}};
        delta <=        {ALPHABITS+LPFBITS{1'b0}};
    end
    else begin
        delta <= (signal_i-y)*alpha_i;
        y <= y + delta;
    end
end

assign signal_o = y[ALPHABITS+LPFBITS-1:ALPHABITS];

endmodule

module echo_cancel (
  input signed [15:0] mic_in,
  input signed [15:0] spkr_in,
  output signed [15:0] out
);

parameter N = 32; // length of the filter
parameter mu = 0.01; // step size for the LMS algorithm

reg signed [15:0] filter_taps [0:N-1]; // filter taps
reg signed [15:0] delayed_mic_in [0:N-1]; // delayed microphone input
reg signed [15:0] error; // error signal
reg signed [15:0] filtered_spkr_in; // filtered speaker input
reg signed [15:0] filtered_mic_in; // filtered microphone input
reg signed [15:0] sum; // sum of filtered inputs

integer i; // loop index

// Delayed microphone input
always @(posedge clk) begin
  for (i = N-1; i > 0; i = i - 1) begin
    delayed_mic_in[i] <= delayed_mic_in[i-1];
  end
  delayed_mic_in[0] <= mic_in;
end

// Filtered speaker input
always @(posedge clk) begin
  filtered_spkr_in <= 0;
  for (i = 0; i < N; i = i + 1) begin
    filtered_spkr_in <= filtered_spkr_in + spkr_in * filter_taps[i];
  end
end

// Filtered microphone input
always @(posedge clk) begin
  filtered_mic_in <= 0;
  for (i = 0; i < N; i = i + 1) begin
    filtered_mic_in <= filtered_mic_in + delayed_mic_in[i] * filter_taps[i];
  end
end

// Error signal
always @(posedge clk) begin
  error <= filtered_mic_in - filtered_spkr_in;
end

// Update filter taps
always @(posedge clk) begin
  for (i = 0; i < N; i = i + 1) begin
    filter_taps[i] <= filter_taps[i] + mu * error * delayed_mic_in[i];
  end
end

// Output signal
always @(posedge clk) begin
  sum <= 0;
  for (i = 0; i < N; i = i + 1) begin
    sum <= sum + spkr_in * filter_taps[i];
  end
  out <= sum;
end

endmodule

