module counter(
  input clk,
  input reset,
  input [31:0] max_value,
  output reg [31:0] count
);

  always @(posedge clk) begin
    if (reset) begin
      count <= 0;
    end else if (count == max_value) begin
      count <= 0;
    end else begin
      count <= count + 1;
    end
  end

endmodule

module sqrt
  (input clk,
   output wire rdy,
   input reset,
   input [31:0] x,
   output reg [15:0] sqrt);

   // The maximum number of iterations required to converge.
   parameter ITERATIONS = 16;

   // The width of the guess register.
   parameter WIDTH = 16;

   // The initial guess for the square root.
   reg [WIDTH-1:0] guess = {WIDTH{1'b0}};

   // The current iteration number.
   reg [4:0] iter = 0;

   // The square of the current guess.
   reg [31:0] guess_sq;

   // The square of the next guess.
   reg [31:0] next_guess_sq;

   // The next guess.
   reg [WIDTH-1:0] next_guess;

   // The difference between the input value and the square of the guess.
   reg [31:0] diff;

   // The difference between the input value and the square of the next guess.
   reg [31:0] next_diff;

   // The output is ready when the number of iterations exceeds the maximum
   // or when the difference between the input value and the square of the guess
   // is less than or equal to one.
   assign rdy = (iter >= ITERATIONS) || (diff <= 1);

   // The square of the guess is calculated using a multiplier.
   always @(*) begin
      guess_sq = guess * guess;
   end

   // The square of the next guess is calculated using a multiplier.
   always @(*) begin
      next_guess_sq = next_guess * next_guess;
   end

   // The difference between the input value and the square of the guess is
   // calculated using a subtractor.
   always @(*) begin
      diff = x - guess_sq;
   end

   // The difference between the input value and the square of the next guess
   // is calculated using a subtractor.
   always @(*) begin
      next_diff = x - next_guess_sq;
   end

   // The next guess is calculated by shifting the current guess to the left
   // by one bit and then adding the appropriate bit to the LSB.
   always @(*) begin
      next_guess = {guess[WIDTH-2:0], 1'b0} + (diff[31] << (WIDTH-1));
   end

   // The guess is updated when the next guess is closer to the input value.
   always @(posedge clk or posedge reset) begin
      if (reset) begin
         guess <= {WIDTH{1'b0}};
         iter <= 0;
      end else if (iter < ITERATIONS) begin
         if (next_diff <= diff) begin
            guess <= next_guess;
            diff <= next_diff;
         end
         next_guess <= guess;
         iter <= iter + 1;
      end
   end

   // The square root is the guess rounded down to the nearest integer.
   always @(*) begin
      sqrt = guess[WIDTH-1:WIDTH-16];
   end

endmodule

module Adder (
    input [7:0] a,
    input [7:0] b,
    output [8:0] sum
);

    wire [7:0] carry;
    wire [7:0] half_sum;

    // Generate the carry bit for each bit of the sum
    assign carry[0] = 1'b0;
    generate
        genvar i;
        for (i = 1; i < 8; i = i + 1) begin
            assign carry[i] = (a[i-1] & b[i-1]) | (a[i-1] & carry[i-1]) | (b[i-1] & carry[i-1]);
        end
    endgenerate

    // Generate the half-sum for each bit of the sum
    assign half_sum[0] = a[0] ^ b[0];
    generate
        genvar i;
        for (i = 1; i < 8; i = i + 1) begin
            assign half_sum[i] = a[i] ^ b[i] ^ carry[i-1];
        end
    endgenerate

    // Combine the carry and half-sum to form the final sum
    assign sum[0] = carry[7];
    assign sum[1:8] = half_sum;
endmodule

module mask_ROM (
  input [n-1:0] addr,
  output [m-1:0] data
);

parameter n = 3; // number of address signals
parameter m = 8; // number of data signals
parameter d = 8; // number of data words
parameter w = 8; // number of bits per data word

reg [w-1:0] rom [0:d-1];

initial begin
  // Initialize the ROM with data words
  rom[0] = 8'b00000000;
  rom[1] = 8'b00000001;
  rom[2] = 8'b00000010;
  rom[3] = 8'b00000011;
  rom[4] = 8'b00000100;
  rom[5] = 8'b00000101;
  rom[6] = 8'b00000110;
  rom[7] = 8'b00000111;
end

assign data = rom[addr];

endmodule

module reverse_word(
    input wire clk,
    input wire reset,
    input wire [15:0] in,
    input wire select,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo,
    output wire [15:0] out_reassembled
);

    wire [3:0] select_demux = in[15:12];
    wire [3:0] select_mux = select ? 4'b1111 : 4'b0000;
    wire [255:0] demux_out;
    wire [7:0] mux_out;

    // 256-to-1 demultiplexer
    demux_256to1 demux(
        .clk(clk),
        .reset(reset),
        .select(select_demux),
        .in(in),
        .out(demux_out)
    );

    // 8-to-1 multiplexer
    mux_8to1 mux(
        .in0(demux_out[7:0]),
        .in1(demux_out[15:8]),
        .in2(demux_out[23:16]),
        .in3(demux_out[31:24]),
        .in4(demux_out[39:32]),
        .in5(demux_out[47:40]),
        .in6(demux_out[55:48]),
        .in7(demux_out[63:56]),
        .select(select_mux),
        .out(mux_out)
    );

    assign out_hi = mux_out[7:0];
    assign out_lo = mux_out[15:8];
    assign out_reassembled = {out_lo, out_hi};

endmodule

// 256-to-1 demultiplexer
module demux_256to1(
    input wire clk,
    input wire reset,
    input wire [3:0] select,
    input wire [15:0] in,
    output wire [255:0] out
);

    reg [255:0] out_reg;

    always @(posedge clk) begin
        if (reset) begin
            out_reg <= 256'b0;
        end else begin
            out_reg[select +: 16] <= in;
        end
    end

    assign out = out_reg;

endmodule

// 8-to-1 multiplexer
module mux_8to1(
    input wire [7:0] in0,
    input wire [7:0] in1,
    input wire [7:0] in2,
    input wire [7:0] in3,
    input wire [7:0] in4,
    input wire [7:0] in5,
    input wire [7:0] in6,
    input wire [7:0] in7,
    input wire [3:0] select,
    output wire [7:0] out
);

    assign out = (select == 4'b0000) ? in0 :
                 (select == 4'b0001) ? in1 :
                 (select == 4'b0010) ? in2 :
                 (select == 4'b0011) ? in3 :
                 (select == 4'b0100) ? in4 :
                 (select == 4'b0101) ? in5 :
                 (select == 4'b0110) ? in6 :
                                      in7 ;

endmodule

module touch_sensor_interface (
  input touch_signal,
  input ref_signal,
  input threshold,
  output touch_detected
);

  reg voltage_diff;

  always @(touch_signal, ref_signal) begin
    voltage_diff = touch_signal - ref_signal;
  end

  assign touch_detected = (voltage_diff > threshold) ? 1'b1 : 1'b0;

endmodule

module inputiso1n (
    X      ,
    A      ,
    SLEEP_B,
    VPWR   ,
    VGND   ,
    VPB    ,
    VNB
);

    output X      ;
    input  A      ;
    input  SLEEP_B;
    input  VPWR   ;
    input  VGND   ;
    input  VPB    ;
    input  VNB    ;

    wire A_iso, SLEEP_B_iso, VPWR_iso, VGND_iso, VPB_iso, VNB_iso;

    assign A_iso = A ^ VPWR;
    assign SLEEP_B_iso = SLEEP_B ^ VGND;
    assign VPWR_iso = VPWR;
    assign VGND_iso = VGND;
    assign VPB_iso = VPB;
    assign VNB_iso = VNB;

    assign X = A_iso & SLEEP_B_iso & VPWR_iso & VGND_iso & VPB_iso & VNB_iso;

endmodule

module memory_block (
  input                 rst,            // reset
  input                 clk,
  output  reg           din_stb,
  input         [1:0]   din_ready,
  output  reg   [1:0]   din_activate,
  output  reg   [31:0]  din,
  input         [23:0]  din_size,
  input                 dout_ready,
  output  reg           dout_activate,
  input         [31:0]  dout,
  output  reg           dout_stb,
  input         [23:0]  dout_size,
  output  reg           count_error,
  output  reg           incorrect_data,
  output  reg   [23:0]  count_detected,
  output  reg   [31:0]  detected_value
);

  // Parameters
  localparam DATA_WIDTH = 32;

  // Registers/Wires
  reg [31:0] write_count;
  reg [31:0] read_count;
  reg [31:0] mem [0:((2**24)/DATA_WIDTH)-1];

  // Asynchronous Logic
  // None

  // Synchronous Logic
  always @(posedge clk) begin
    if (rst) begin
      din_stb          <= 0;
      din_activate     <= 0;
      din              <= 0;
      write_count      <= 0;
      dout_activate    <= 0;
      dout_stb         <= 0;
      read_count       <= 0;
      count_error      <= 0;
      incorrect_data   <= 0;
      detected_value   <= 0;
      count_detected   <= 0;
    end
    else begin
      din_stb          <= 0;
      dout_stb         <= 0;
      count_error      <= 0;
      incorrect_data   <= 0;

      if ((din_ready > 0) && (din_activate == 0)) begin
        write_count  <= 0;
        din          <= 0;
        if (din_ready[0]) begin
          din_activate[0] <= 1;
        end
        else begin
          din_activate[1] <= 1;
        end
      end
      else if (din_activate != 0) begin
        if (write_count < din_size) begin
          din_stb      <= 1;
          din          <= write_count;
          mem[write_count] <= din;
          write_count  <= write_count + 1;
        end
        else begin
          din_activate <= 0;
        end
      end

      if (dout_ready && !dout_activate) begin
        read_count    <= 0;
        dout_activate <= 1;
        if (dout_size != 24'h0800) begin
          count_error <= 1;
          count_detected <= dout_size;
        end
      end
      else if (dout_activate) begin
        if (read_count < dout_size) begin
          dout_stb    <= 1;
          dout        <= mem[read_count];
          read_count  <= read_count + 1;
        end
        else begin
          dout_activate <= 0;
        end

        // Error Detection
        if (read_count > 0) begin
          if (dout != read_count - 1) begin
            incorrect_data <= 1;
            count_detected <= read_count[23:0];
            detected_value <= dout;
          end
        end
        else begin
          if (dout != 0) begin
            incorrect_data <= 1;
            count_detected <= read_count[23:0];
            detected_value <= dout;
          end
        end
      end
    end
  end

endmodule

module uart_baud_generator(clk,baud,baud16,rst);
	input clk,rst;
	output baud;
	output baud16;

	parameter b_rate = 57600;
	parameter c_rate = 25000000; /* 25 Mhz */
	parameter divider = c_rate / b_rate;
	parameter divider16 = c_rate / (16 * b_rate); /* 16 times faster! */

	reg [31:0] count,count16;

	assign baud = (count == 0) ? 1 : 0;
	assign baud16 = (count16 == 0) ? 1 : 0;

	always @(negedge clk) begin
		count = count + 1;
		count16 = count16 + 1;
		if (count == divider)
			count = 0;
		if (count16 == divider16) 
			count16 = 0;
		if (rst) begin
			count = 0;
			count16 = 0;
		end
	end
endmodule

module barrel_shifter (
    input [3:0] D,
    input [1:0] S,
    input shift_right,
    output reg [3:0] Q
);

reg [3:0] stage1_out;
reg [3:0] stage2_out;

always @(*) begin
    if (shift_right) begin
        case(S)
            2'b00: stage1_out = {2'b00, D[3:2]};
            2'b01: stage1_out = {2'b00, D[3:1]};
            2'b10: stage1_out = {2'b00, D[3]};
            2'b11: stage1_out = D;
        endcase
    end else begin
        case(S)
            2'b00: stage1_out = {D[2:0], 2'b00};
            2'b01: stage1_out = {D[1:0], D[3]};
            2'b10: stage1_out = {D[0], D[3:1]};
            2'b11: stage1_out = D;
        endcase
    end
end

always @(posedge clk) begin
    stage2_out <= stage1_out;
end

assign Q = stage2_out;

endmodule

module binary_counter (
  input clk,
  input rst,
  output reg [3:0] count,
  output reg out_range
);

  always @(posedge clk, posedge rst) begin
    if (rst) begin
      count <= 4'b0000;
      out_range <= 1'b0;
    end else begin
      if (count == 4'b1010) begin
        out_range <= 1'b1;
      end else if (count == 4'b1111) begin
        count <= 4'b0000;
        out_range <= 1'b0;
      end else begin
        out_range <= 1'b0;
      end
      count <= count + 1;
    end
  end

endmodule

