module top_module (
    input clk,
    input reset,
    input signed [7:0] A [0:3][0:3],
    input signed [7:0] B [0:3][0:3],
    input [3:0] data_in,
    input select,
    input load,
    output reg signed [15:0] C [0:3][0:3],
    output reg [3:0] data_out
);

reg [3:0] shift_reg [0:3][0:3];
reg [3:0] shift_reg_load [0:3][0:3];
reg [3:0] shift_reg_out [0:3][0:3];
reg [3:0] shift_reg_out_temp [0:3][0:3];
reg [3:0] shift_reg_out_final [0:3][0:3];
reg [15:0] product [0:3][0:3];
reg [15:0] product_temp [0:3][0:3];
reg [15:0] product_final [0:3][0:3];

integer i, j, k;

always @(posedge clk) begin
    if (reset) begin
        for (i = 0; i < 4; i = i + 1) begin
            for (j = 0; j < 4; j = j + 1) begin
                C[i][j] <= 0;
                shift_reg[i][j] <= 0;
                shift_reg_load[i][j] <= 0;
                shift_reg_out[i][j] <= 0;
                shift_reg_out_temp[i][j] <= 0;
                shift_reg_out_final[i][j] <= 0;
                product[i][j] <= 0;
                product_temp[i][j] <= 0;
                product_final[i][j] <= 0;
            end
        end
    end else begin
        if (select) begin
            if (load) begin
                for (i = 0; i < 4; i = i + 1) begin
                    for (j = 0; j < 4; j = j + 1) begin
                        shift_reg_load[i][j] <= data_in;
                    end
                end
            end
            for (i = 0; i < 4; i = i + 1) begin
                for (j = 0; j < 4; j = j + 1) begin
                    shift_reg[i][j] <= shift_reg_load[i][j];
                end
            end
            for (i = 0; i < 4; i = i + 1) begin
                for (j = 0; j < 4; j = j + 1) begin
                    if (j == 0) begin
                        shift_reg_out_temp[i][j] <= shift_reg[i][j];
                    end else begin
                        shift_reg_out_temp[i][j] <= shift_reg_out_temp[i][j-1];
                    end
                end
            end
            for (i = 0; i < 4; i = i + 1) begin
                for (j = 0; j < 4; j = j + 1) begin
                    shift_reg_out_final[i][j] <= {shift_reg_out_temp[i][j], 4'b0000};
                    C[i][j] <= shift_reg_out_final[i][j];
                end
            end
            data_out <= shift_reg_out_final[3][3];
        end else begin
            for (i = 0; i < 4; i = i + 1) begin
                for (j = 0; j < 4; j = j + 1) begin
                    product_temp[i][j] <= 0;
                    for (k = 0; k < 4; k = k + 1) begin
                        product_temp[i][j] <= product_temp[i][j] + A[i][k] * B[k][j];
                    end
                end
            end
            for (i = 0; i < 4; i = i + 1) begin
                for (j = 0; j < 4; j = j + 1) begin
                    product_final[i][j] <= {product_temp[i][j], 4'b0000};
                    C[i][j] <= product_final[i][j];
                end
            end
            data_out <= product_final[3][3];
        end
    end
end

endmodule

module motor_control_block(
  input dir,
  input step,
  input [7:0] duty_cycle,
  output enable,
  output step_dir,
  output reg [3:0] step_pulse
);

  reg pwm_out;
  reg hbridge_dir;

  // PWM controller
  always @ (posedge step) begin
    if (duty_cycle >= 100) begin
      pwm_out <= 1;
    end else if (duty_cycle == 0) begin
      pwm_out <= 0;
    end else begin
      pwm_out <= (step % (100 / duty_cycle)) == 0;
    end
  end

  // H-bridge driver
  always @ (dir, pwm_out) begin
    if (dir) begin
      hbridge_dir <= 1;
    end else begin
      hbridge_dir <= 0;
    end
    enable <= 1;
    step_dir <= hbridge_dir;
  end

  // Stepper motor controller
  always @ (posedge step) begin
    if (step_pulse == 4'b0001) begin
      step_pulse <= 4'b0010;
    end else if (step_pulse == 4'b0010) begin
      if (hbridge_dir) begin
        step_pulse <= 4'b0100;
      end else begin
        step_pulse <= 4'b0001;
      end
    end else if (step_pulse == 4'b0100) begin
      step_pulse <= 4'b1000;
    end else begin
      if (hbridge_dir) begin
        step_pulse <= 4'b0001;
      end else begin
        step_pulse <= 4'b0010;
      end
    end
  end

endmodule

