module square_wave_gen (
  input clk,
  input freq,
  output reg square_wave
);

  reg [31:0] counter;
  reg [31:0] half_period;
  reg [31:0] clk_period;

  always @ (posedge clk) begin
    if (counter == half_period) begin
      square_wave <= ~square_wave;
      counter <= 0;
    end else begin
      counter <= counter + 1;
    end
  end

  always @ (posedge clk) begin
    clk_period <= $floor($period(clk));
    half_period <= clk_period / (2 * freq);
  end

endmodule

