module adapter_axi_stream_2_block_fifo #(
  parameter DATA_WIDTH = 32,
  parameter STROBE_WIDTH = DATA_WIDTH / 8,
  parameter USE_KEEP = 0
)(
  input rst,

  //AXI Stream Input
  input i_axi_clk,
  output o_axi_ready,
  input [DATA_WIDTH - 1:0] i_axi_data,
  input [STROBE_WIDTH - 1:0] i_axi_keep,
  input i_axi_last,
  input i_axi_valid,

  //Ping Pong FIFO Write Controller
  output o_block_fifo_clk,
  input i_block_fifo_rdy,
  output reg o_block_fifo_act,
  input [23:0] i_block_fifo_size,
  output reg [DATA_WIDTH - 1:0] o_block_fifo_data
);
  //local parameters
  localparam IDLE = 2'b00;
  localparam READY = 2'b01;
  localparam RELEASE = 2'b10;
  //registes/wires
  wire clk;  //Convenience Signal
  reg [1:0] state;
  reg [23:0] r_count;
  //submodules
  //asynchronous logic

  //This is a little strange to just connect the output clock with the input clock but if this is done
  //Users do not need to figure out how to hook up the clocks
  assign o_block_fifo_clk = i_axi_clk;
  assign clk = i_axi_clk;
  assign o_axi_ready = o_block_fifo_act && (r_count < i_block_fifo_size);
  //synchronous logic

  always @(posedge clk) begin
    o_block_fifo_stb <= 0;

    if (rst) begin
      r_count <= 0;
      o_block_fifo_act <= 0;
      o_block_fifo_data <= 0;
      state <= IDLE;
    end
    else begin
      case (state)
        IDLE: begin
          o_block_fifo_act <= 0;
          if (i_block_fifo_rdy && !o_block_fifo_act) begin
            r_count <= 0;
            o_block_fifo_act <= 1;
            state <= READY;
          end
        end
        READY: begin
          if (r_count < i_block_fifo_size) begin
            if (i_axi_valid) begin
              o_block_fifo_stb <= 1;
              o_block_fifo_data <= i_axi_data;

              r_count <= r_count + 1;
            end
          end
          //Conditions to release the FIFO or stop a transaction
          else begin
            state <= RELEASE;
          end
          if (i_axi_last) begin
            state <= RELEASE;
          end
        end
        RELEASE: begin
          o_block_fifo_act <= 0;
          state <= IDLE;
        end
        default: begin
        end
      endcase
    end
  end

endmodule

module calculator (
    input clk,
    input rst,
    input [1:0] op,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] result,
    output reg valid
);

    reg [31:0] temp_result;
    reg [1:0] state;

    always @(posedge clk) begin
        if (rst) begin
            state <= 2'b00;
            result <= 0;
            temp_result <= 0;
            valid <= 0;
        end else begin
            case (state)
                2'b00: begin // addition
                    temp_result <= a + b;
                    state <= 2'b01;
                end
                2'b01: begin // subtraction
                    temp_result <= a - b;
                    state <= 2'b10;
                end
                2'b10: begin // multiplication
                    temp_result <= a * b;
                    state <= 2'b11;
                end
                2'b11: begin // division
                    temp_result <= a / b;
                    state <= 2'b00;
                end
                default: begin
                    state <= 2'b00;
                    result <= 0;
                    temp_result <= 0;
                    valid <= 0;
                end
            endcase
            result <= temp_result;
            valid <= 1;
        end
    end

endmodule

module gray_code_converter (
