    assign gray_out[2] = binary_in[1] ^ binary_in[2];
    assign gray_out[3] = binary_in[2] ^ binary_in[3];

    always @ (select or binary_in) begin
        if (select == 1'b1) begin
            gray_out <= {gray_out[3], gray_out[3] ^ gray_out[2], gray_out[2] ^ gray_out[1], gray_out[1] ^ gray_out[0]};
        end else begin
            gray_out <= binary_in;
        end
    end

endmodule

module mux6to1_and (
    input [2:0] sel,
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output reg [3:0] out
);

reg [2:0] priority;
reg [3:0] mux4to1_out;

always @(*) begin
    if (sel >= 6) begin
        out = 4'b0000;
    end else begin
        case (sel)
            3'b000: priority = 3'b000;
            3'b001: priority = 3'b001;
            3'b010: priority = 3'b010;
            3'b011: priority = 3'b011;
            3'b100: priority = 3'b100;
            3'b101: priority = 3'b101;
            default: priority = 3'b000;
        endcase

        case (priority)
            3'b000: mux4to1_out = data0;
            3'b001: mux4to1_out = data1;
            3'b010: mux4to1_out = data2;
            3'b011: mux4to1_out = data3;
            3'b100: mux4to1_out = data4;
            3'b101: mux4to1_out = data5;
            default: mux4to1_out = 4'b0000;
        endcase

        out = {mux4to1_out[3] & mux4to1_out[2] & mux4to1_out[1] & mux4to1_out[0]};
    end
end

endmodule

module wireless_communication (
