module pwm (
  input clk,
  input [7:0] data,
  output pwm_out
);

parameter clk_freq = 50_000_000; // 50 MHz
parameter pwm_freq = 10_000; // 10 KHz
parameter resolution = 8; // 8-bit duty cycle resolution

reg [resolution-1:0] duty_cycle;
reg [31:0] counter;
wire comparator_out;

assign pwm_out = comparator_out;

always @(posedge clk) begin
  counter <= counter + 1;
  if (counter >= ((clk_freq/pwm_freq)/2)) begin
    counter <= 0;
  end
end

always @(posedge clk) begin
  duty_cycle <= data;
end

assign comparator_out = (counter < ((clk_freq/pwm_freq)*duty_cycle/(2**resolution)));

endmodule

module multiplier_4bit (
    input [3:0] M,
    input [3:0] N,
    output reg [7:0] P,
    output reg E
);

reg [3:0] shift_reg;
reg [7:0] prod_reg;
reg [1:0] stage;

always @ (posedge clk) begin
    case (stage)
        0: begin
            shift_reg <= N;
            prod_reg <= 0;
        end
        1: begin
            shift_reg <= {shift_reg[2:0], 1'b0};
            prod_reg <= {prod_reg[6:0], shift_reg[0] & M};
        end
        2: begin
            shift_reg <= {shift_reg[2:0], 1'b0};
            prod_reg <= {prod_reg[6:0], shift_reg[0] & M};
        end
        3: begin
            shift_reg <= {shift_reg[2:0], 1'b0};
            prod_reg <= {prod_reg[6:0], shift_reg[0] & M};
        end
        4: begin
            shift_reg <= {shift_reg[2:0], 1'b0};
            prod_reg <= {prod_reg[6:0], shift_reg[0] & M};
        end
        5: begin
            shift_reg <= {shift_reg[2:0], 1'b0};
            prod_reg <= {prod_reg[6:0], shift_reg[0] & M};
        end
        6: begin
            shift_reg <= {shift_reg[2:0], 1'b0};
            prod_reg <= {prod_reg[6:0], shift_reg[0] & M};
        end
        7: begin
            shift_reg <= {shift_reg[2:0], 1'b0};
            prod_reg <= {prod_reg[6:0], shift_reg[0] & M};
            P <= prod_reg;
            E <= (prod_reg[7] == 1) ? 1 : 0;
        end
    endcase
    stage <= (stage == 7) ? 0 : stage + 1;
end

endmodule

