    assign b_twos_comp = sub ? (~b + 1) : b;

    // Low 16-bit adder
    adder a_low_adder(
        .a(a_low),
        .b(b_low ^ sub ? 32'hFFFF : 0),
        .sum(add_low),
        .carry(carry_out)
    );

    // High 16-bit adder
    adder a_high_adder(
        .a(a_high),
        .b(b_high ^ sub ? 32'hFFFF0000 : 0),
        .sum(add_high),
        .carry(carry_out)
    );

    // Combine low and high 16-bit results
    assign sum = {add_high, add_low};

