module viterbi_decoder (
  input [n-1:0] in,
  output [k-1:0] out
);

parameter n = 256; // number of bits in the input sequence
parameter k = 128; // number of bits in the output sequence
parameter m = 16;  // number of bits in the shift register

reg [m-1:0] shift_reg [0:k-1];
reg [m-1:0] next_shift_reg [0:k-1];
reg [1:0] path_metric [0:(1<<m)-1][0:k-1];
reg [1:0] next_path_metric [0:(1<<m)-1][0:k-1];
reg [1:0] branch_metric [0:(1<<m)-1][0:k-1];

integer i, j, l, s, t;
integer min_metric, min_state;

initial begin
  // initialize shift register and path metric
  for (i = 0; i < k; i = i + 1) begin
    shift_reg[i] = 0;
    for (j = 0; j < (1<<m); j = j + 1) begin
      path_metric[j][i] = 0;
    end
  end
end

always @(*) begin
  // compute branch metric
  for (i = 0; i < k; i = i + 1) begin
    for (j = 0; j < (1<<m); j = j + 1) begin
      branch_metric[j][i] = 0;
      for (l = 0; l < m; l = l + 1) begin
        if (in[i*m+l] != ((j>>(m-1-l)) & 1)) begin
          branch_metric[j][i] = branch_metric[j][i] + 1;
        end
      end
    end
  end

  // compute path metric and update shift register
  for (i = 0; i < k; i = i + 1) begin
    min_metric = 3;
    min_state = 0;
    for (j = 0; j < (1<<m); j = j + 1) begin
      next_path_metric[j][i] = path_metric[j][i-1] + branch_metric[j][i];
      if (next_path_metric[j][i] < min_metric) begin
        min_metric = next_path_metric[j][i];
        min_state = j;
      end
    end
    for (j = 0; j < k-1; j = j + 1) begin
      next_shift_reg[j+1] = shift_reg[j][m-2:0];
    end
    next_shift_reg[0] = min_state;
    for (j = 0; j < k; j = j + 1) begin
      for (s = 0; s < (1<<m); s = s + 1) begin
        if (s == next_shift_reg[j]) begin
          path_metric[s][j] = min_metric;
        end else begin
          path_metric[s][j] = next_path_metric[s][j];
        end
      end
    end
    for (j = 0; j < k-1; j = j + 1) begin
      shift_reg[j] = next_shift_reg[j];
    end
  end

  // output decoded bits
  for (i = 0; i < k; i = i + 1) begin
    out[i] = shift_reg[i][m-1];
  end
end

endmodule

