module spi_slave_rxq(
  input c,
  input cs,
  input sclk,
  input mosi,
  output [7:0] rxd,
  output rxdv,
  output rxe
);

  // Shift register to store incoming data
  reg [7:0] shift_reg;
  reg [2:0] shift_count;

  // FIFO signals
  wire [7:0] fifo_data;
  wire fifo_rdreq;
  wire fifo_empty;
  wire [7:0] fifo_usedw;

  // SPI receiver state machine
  localparam IDLE = 2'b00;
  localparam RX = 2'b01;
  localparam TX = 2'b10;

  reg [1:0] state;
  reg [7:0] tx_data;
  reg [2:0] tx_count;

  // Initialize state machine
  always @ (posedge c) begin
    if (cs == 0) begin
      state <= RX;
      shift_count <= 0;
      tx_count <= 0;
    end else begin
      state <= IDLE;
    end
  end

  // Shift in data on rising edge of sclk
  always @ (posedge sclk) begin
    if (state == RX) begin
      shift_reg <= {mosi, shift_reg[7:1]};
      shift_count <= shift_count + 1;

      if (shift_count == 7) begin
        shift_count <= 0;
        state <= TX;
        tx_data <= shift_reg;
      end
    end
  end

  // Write data to FIFO in TX state
  scfifo #(.lpm_width(8),
           .lpm_numwords(256),
           .lpm_widthu(8),
           .lpm_showahead("ON"),
           .use_eab("ON"),
           .intended_device_family("CYCLONE V"))
  fifo (
    .clock(c),
    .wrreq(tx_count == 0),
    .data(tx_data),
    .rdreq(fifo_rdreq),
    .q(fifo_data),
    .empty(fifo_empty),
    .usedw(fifo_usedw),
    .aclr(1'b0),
    .sclr(1'b0)
  );

  // Update state machine
  always @ (posedge c) begin
    case (state)
      IDLE:
        if (cs == 0) begin
          state <= RX;
        end
      RX:
        if (shift_count == 7) begin
          shift_count <= 0;
          state <= TX;
          tx_data <= shift_reg;
        end
      TX:
        if (fifo_rdreq == 1) begin
          tx_count <= tx_count + 1;
          if (tx_count == 7) begin
            tx_count <= 0;
            state <= RX;
          end
        end
    endcase
  end

  // Output data from FIFO
  assign rxd = fifo_data;
  assign rxdv = ~fifo_empty;
  assign rxe = fifo_usedw == 0;

endmodule

module mux_pipeline (
    input A,
    input B,
    input C,
    input D,
    input SEL1,
    input SEL2,
    input EN,
    output reg OUT
);

reg [1:0] stage1_sel;
reg [1:0] stage2_sel;
reg [1:0] stage3_sel;

wire stage1_out_A;
wire stage1_out_B;
wire stage1_out_C;
wire stage1_out_D;

wire stage2_out_A;
wire stage2_out_B;

wire stage3_out;

assign stage1_out_A = (SEL1 & ~SEL2) ? A : 1'b0;
assign stage1_out_B = (~SEL1 & ~SEL2) ? B : 1'b0;
assign stage1_out_C = (SEL1 & SEL2) ? C : 1'b0;
assign stage1_out_D = (~SEL1 & SEL2) ? D : 1'b0;

assign stage2_out_A = (stage1_sel[1] & ~stage1_sel[0]) ? stage1_out_A : 1'b0;
assign stage2_out_B = (~stage1_sel[1] & ~stage1_sel[0]) ? stage1_out_B : 1'b0;

assign stage3_out = (stage2_sel[1] & ~stage2_sel[0]) ? stage2_out_A : stage2_out_B;

always @(posedge clk) begin
    if (EN) begin
        stage1_sel <= {SEL2, SEL1};
        stage2_sel <= stage1_sel;
        stage3_sel <= stage2_sel;
        OUT <= stage3_out;
    end
end

endmodule

