module sqrt (
  input [31:0] in,
  output [15:0] out
);

  reg [15:0] guess;
  reg [31:0] temp;

  always @(*) begin
    guess = 16'd1;
    temp = in;
    while (temp > guess * guess) begin
      guess = guess + 1;
    end
    out = guess - 1;
  end

endmodule

