module tone_generator (
  input clk,
  input rst,
  input [1:0] tone_type,
  output reg tone_out
);

parameter CLK_FREQ = 50e6; // clock frequency
parameter TONE_FREQ = 1000; // tone frequency
parameter TONE_DURATION = 1; // tone duration in seconds

// Define tone types
parameter DTMF = 2'b00;
parameter SINE_WAVE = 2'b01;
parameter SQUARE_WAVE = 2'b10;
parameter TRIANGLE_WAVE = 2'b11;

// Define other parameters based on tone type
parameter DTMF_FREQ1 = 697;
parameter DTMF_FREQ2 = 1209;
parameter SINE_AMPLITUDE = 100;
parameter SQUARE_DUTY_CYCLE = 0.5;
parameter TRIANGLE_SLOPE = 100;

// Define input signals for each tone type
reg [15:0] dtmf_in;
reg [15:0] sine_wave_in;
reg [15:0] square_wave_in;
reg [15:0] triangle_wave_in;

// Define waveform for each tone type
always @(*) begin
  case (tone_type)
    DTMF: begin
      dtmf_in = (CLK_FREQ / DTMF_FREQ1) + (CLK_FREQ / DTMF_FREQ2);
    end
    SINE_WAVE: begin
      sine_wave_in = CLK_FREQ / TONE_FREQ;
    end
    SQUARE_WAVE: begin
      square_wave_in = CLK_FREQ / TONE_FREQ;
    end
    TRIANGLE_WAVE: begin
      triangle_wave_in = CLK_FREQ / TONE_FREQ;
    end
  endcase
end

// Counter for generating tone signal
reg [31:0] counter;

// Generate tone signal based on counter and waveform
always @(posedge clk or posedge rst) begin
  if (rst) begin
    counter <= 0;
    tone_out <= 0;
  end else begin
    counter <= counter + 1;
    case (tone_type)
      DTMF: begin
        if (counter >= dtmf_in) begin
          counter <= 0;
          tone_out <= ~tone_out;
        end
      end
      SINE_WAVE: begin
        if (counter >= sine_wave_in) begin
          counter <= 0;
          tone_out <= ~tone_out;
        end
      end
      SQUARE_WAVE: begin
        if (counter >= square_wave_in * (1 - SQUARE_DUTY_CYCLE)) begin
          tone_out <= 1;
        end else if (counter >= square_wave_in * SQUARE_DUTY_CYCLE) begin
          tone_out <= 0;
        end
      end
      TRIANGLE_WAVE: begin
        if (counter >= triangle_wave_in / 2) begin
          tone_out <= 1;
        end else if (counter >= triangle_wave_in) begin
          tone_out <= 0;
          counter <= 0;
        end
      end
    endcase
  end
end

endmodule

module OneHotStateMachine (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 4; // number of input signals
parameter m = 2; // number of output signals
parameter s = 4; // number of states

reg [s-1:0] state; // register to hold the current state

always @ (posedge clk) begin
  // compute the next state based on the input signals
  case (state)
    0: state <= in[0] ? 1 : 0;
    1: state <= in[1] ? 2 : 0;
    2: state <= in[2] ? 3 : 0;
    3: state <= in[3] ? 0 : 0;
  endcase
end

// compute the output signals based on the current state
assign out = {state == 0, state == 1};

endmodule

module matrix_multiplier(
    input [31:0] a,
    input [31:0] b,
    input clk,
    output [31:0] c
);

reg [7:0] a_matrix [0:3][0:3];
reg [7:0] b_matrix [0:3][0:3];
reg [7:0] c_matrix [0:3][0:3];

integer i, j, k;

// Unpack input vectors into matrices
always @ (posedge clk) begin
    for (i = 0; i < 4; i = i + 1) begin
        for (j = 0; j < 4; j = j + 1) begin
            a_matrix[i][j] <= a[(i * 4 + j) * 8 +: 8];
            b_matrix[i][j] <= b[(i * 4 + j) * 8 +: 8];
        end
    end
end

// Compute matrix product
always @ (posedge clk) begin
    for (i = 0; i < 4; i = i + 1) begin
        for (j = 0; j < 4; j = j + 1) begin
            c_matrix[i][j] <= 0;
            for (k = 0; k < 4; k = k + 1) begin
                c_matrix[i][j] <= c_matrix[i][j] + a_matrix[i][k] * b_matrix[k][j];
            end
        end
    end
end

// Pack output matrix into output vector
always @ (posedge clk) begin
    for (i = 0; i < 4; i = i + 1) begin
        for (j = 0; j < 4; j = j + 1) begin
            c[(i * 4 + j) * 8 +: 8] <= c_matrix[i][j];
        end
    end
end

endmodule

module alu (
    input [3:0] A,
    input [3:0] B,
    input [2:0] op,
    output [3:0] Z
);

    reg [3:0] temp;

    always @(*) begin
        case (op)
            3'b000: temp = A + B;
            3'b001: temp = A - B;
            3'b010: temp = A & B;
            3'b011: temp = A | B;
            3'b100: temp = A ^ B;
            3'b101: temp = ~A;
            default: temp = 4'b0;
        endcase
    end

    assign Z = temp;

endmodule

module shift_register (
    input clk,
    input LOAD,
    input SHIFT,
    input [7:0] DATA_IN,
    output reg [3:0] Q_OUT,
    output reg [3:0] Q_BAR_OUT
);

    always @(posedge clk) begin
        if (LOAD) begin
            Q_OUT <= DATA_IN[3:0];
            Q_BAR_OUT <= ~DATA_IN[3:0];
        end else if (SHIFT) begin
            Q_OUT <= {Q_OUT[2:0], DATA_IN[0]};
            Q_BAR_OUT <= {Q_BAR_OUT[2:0], ~DATA_IN[0]};
        end
    end

endmodule

module final_module (
    input [3:0] A,
