    parameter [6:0] cinco = ~7'h6D;
    parameter [6:0] seis = ~7'h7D;
    parameter [6:0] siete = ~7'h07;
    parameter [6:0] ocho = ~7'h7F;
    parameter [6:0] nueve = ~7'h6F;
    parameter [6:0] ha = ~7'h77;
    parameter [6:0] hb = ~7'h7C;
    parameter [6:0] hc = ~7'h39;
    parameter [6:0] hd = ~7'h5E;
    parameter [6:0] he = ~7'h79;
    parameter [6:0] hf = ~7'h71;

    always @(posedge clock_50mhz) begin
        cuenta_para_1hz <= cuenta_para_1hz + 1;
        if (cuenta_para_1hz == 25_000_000) begin
            clock_1hz <= ~clock_1hz;
            cuenta_para_1hz <= 0;
        end
    end

    always @(posedge clock_1hz) begin
        case(estado)
            0: segmentos <= cero;
            1: segmentos <= uno;
            2: segmentos <= dos;
            3: segmentos <= tres;
            4: segmentos <= cuatro;
            5: segmentos <= cinco;
            6: segmentos <= seis;
            7: segmentos <= siete;
            8: segmentos <= ocho;
            9: segmentos <= nueve;
            10: segmentos <= ha;
            11: segmentos <= hb;
            12: segmentos <= hc;
            13: segmentos <= hd;
            14: segmentos <= he;
            15: segmentos <= hf;
        endcase

        if (estado == 15) begin
            estado <= 0;
        end else begin
            estado <= estado + 1;
        end
    end

    always @(segmentos) begin
        anodo <= 1;
        #1 anodo <= 0;
    end
endmodule

module serial # (
    parameter TRUE = 1'b1,
    parameter FALSE = 1'b0,

    parameter CLOCK_PER_BAUD_RATE = 5208,
    parameter SERIAL_STATE_LAST = 8,
    parameter SERIAL_STATE_SENT = 9,
    parameter SERIAL_STATE_WAIT = 10
)(
    input CLOCK_50M,
    output TX,
    input [63:0] send_buffer_in,
    input [2:0] send_buffer_count_in,
    output [63:0] send_buffer_out,
    output [2:0] send_buffer_count_out,
    output LED1,
    output LED2
);

reg [63:0] send_buffer;
reg [2:0] send_buffer_count;
assign send_buffer_out = send_buffer;
assign send_buffer_count_out = send_buffer_count;

/*
 * CLOCK GENERATOR
 */
reg CLOCK = FALSE;
reg [15:0] clock_counter;
always @(posedge CLOCK_50M) begin
    if (clock_counter < CLOCK_PER_BAUD_RATE) begin
        CLOCK <= FALSE;
        clock_counter <= clock_counter + 1;
    end
    else begin
        CLOCK <= TRUE;
        clock_counter <= 0;
    end
end

/*
 * TRANSMIT DATA
 */
reg [7:0] tx_buffer = "A";
reg [3:0] tx_counter = SERIAL_STATE_WAIT;
reg tx_state = TRUE;
assign TX = tx_state;
assign LED1 = tx_state;
assign LED2 = TRUE;

always @(posedge CLOCK) begin
    if (tx_counter == SERIAL_STATE_WAIT) begin
        tx_state <= FALSE;
        tx_counter <= 0;
    end
    else if (tx_counter == SERIAL_STATE_LAST) begin
        tx_state <= TRUE;
        tx_counter <= SERIAL_STATE_SENT;
    end
    else if (tx_counter == SERIAL_STATE_SENT && send_buffer_count_in > 0) begin
        tx_buffer <= send_buffer_in[7:0];
        send_buffer <= send_buffer_in >> 8;
        send_buffer_count <= send_buffer_count_in - 1;
        tx_counter <= 0;
    end
    else begin
        tx_state <= tx_buffer[tx_counter];
        tx_counter <= tx_counter + 1;
    end
end

endmodule

