module RGB_Resampler (
    // Inputs
    clk,
    reset,
    stream_in_data,
    stream_in_startofpacket,
    stream_in_endofpacket,
    stream_in_empty,
    stream_in_valid,
    stream_out_ready,
    // Outputs
    stream_in_ready,
    stream_out_data,
    stream_out_startofpacket,
    stream_out_endofpacket,
    stream_out_empty,
    stream_out_valid
);

parameter IDW = 15;
parameter ODW = 29;
parameter IEW = 0;
parameter OEW = 1;
parameter ALPHA = 10'h3FF;

input clk;
input reset;
input [IDW:0] stream_in_data;
input stream_in_startofpacket;
input stream_in_endofpacket;
input [IEW:0] stream_in_empty;
input stream_in_valid;
input stream_out_ready;
output stream_in_ready;
output [ODW:0] stream_out_data;
output stream_out_startofpacket;
output stream_out_endofpacket;
output [OEW:0] stream_out_empty;
output stream_out_valid;

reg [ODW:0] converted_data;

wire [9:0] r;
wire [9:0] g;
wire [9:0] b;
wire [9:0] a;

assign r = {stream_in_data[15:11], stream_in_data[15:11]};
assign g = {stream_in_data[10:5], stream_in_data[10:7]};
assign b = {stream_in_data[4:0], stream_in_data[4:0]};
assign a = ALPHA;

assign converted_data[29:20] = r[9:0];
assign converted_data[19:10] = g[9:0];
assign converted_data[9:0] = b[9:0];

reg [1:0] state;
parameter IDLE = 2'b00;
parameter OUTPUT = 2'b01;
parameter WAIT = 2'b10;

always @(posedge clk) begin
    if (reset) begin
        state <= IDLE;
        stream_out_startofpacket <= 1'b0;
        stream_out_endofpacket <= 1'b0;
        stream_out_empty <= {OEW{1'b0}};
        stream_out_valid <= 1'b0;
    end else begin
        case (state)
            IDLE: begin
                if (stream_out_ready & stream_in_valid) begin
                    state <= OUTPUT;
                    stream_out_startofpacket <= stream_in_startofpacket;
                    stream_out_endofpacket <= stream_in_endofpacket;
                    stream_out_empty <= stream_in_empty;
                    stream_out_valid <= 1'b1;
                end else begin
                    stream_out_startofpacket <= 1'b0;
                    stream_out_endofpacket <= 1'b0;
                    stream_out_empty <= {OEW{1'b0}};
                    stream_out_valid <= 1'b0;
                end
            end
            OUTPUT: begin
                if (stream_out_ready) begin
                    state <= WAIT;
                    stream_out_startofpacket <= 1'b0;
                    stream_out_endofpacket <= 1'b0;
                    stream_out_empty <= {OEW{1'b0}};
                    stream_out_valid <= 1'b0;
                end else begin
                    stream_out_startofpacket <= stream_in_startofpacket;
                    stream_out_endofpacket <= stream_in_endofpacket;
                    stream_out_empty <= stream_in_empty;
                    stream_out_valid <= 1'b1;
                end
            end
            WAIT: begin
                if (stream_in_valid & stream_out_ready) begin
                    state <= OUTPUT;
                    stream_out_startofpacket <= stream_in_startofpacket;
                    stream_out_endofpacket <= stream_in_endofpacket;
                    stream_out_empty <= stream_in_empty;
                    stream_out_valid <= 1'b1;
                end else begin
                    stream_out_startofpacket <= 1'b0;
                    stream_out_endofpacket <= 1'b0;
                    stream_out_empty <= {OEW{1'b0}};
                    stream_out_valid <= 1'b0;
                end
            end
        endcase
    end
end

assign stream_in_ready = (state == IDLE) & ~stream_out_valid;

assign stream_out_data = converted_data;

endmodule

module PLL (
  input clk_in,
  input reset,
  input enable,
  input freq_in,
  input freq_out,
  output reg clk_out
);

  // Phase Detector module
  wire phase_diff;
  phase_detector pd_inst (
    .clk_in(clk_in),
    .clk_out(clk_out),
    .phase_diff(phase_diff)
  );

  // Low-pass Filter module
  reg [31:0] error_accumulator = 0;
  wire [7:0] error_voltage;
  low_pass_filter lpf_inst (
    .clk_in(clk_in),
    .reset(reset),
    .phase_diff(phase_diff),
    .error_accumulator(error_accumulator),
    .error_voltage(error_voltage)
  );

  // Voltage-controlled Oscillator module
  reg [31:0] vco_accumulator = 0;
  wire [31:0] vco_frequency;
  vco vco_inst (
    .clk_in(clk_in),
    .reset(reset),
    .vco_accumulator(vco_accumulator),
    .vco_frequency(vco_frequency)
  );

  // Divider module
  reg [31:0] divider_accumulator = 0;
  reg [31:0] divider_threshold = 0;
  reg [31:0] divider_count = 0;
  always @(posedge vco_frequency) begin
    if (divider_count == divider_threshold) begin
      clk_out <= ~clk_out;
      divider_count <= 0;
    end else begin
      divider_count <= divider_count + 1;
    end
  end

  // Enable and Reset control
  always @(posedge clk_in) begin
    if (reset) begin
      clk_out <= 0;
      error_accumulator <= 0;
      vco_accumulator <= 0;
      divider_accumulator <= 0;
      divider_threshold <= 0;
      divider_count <= 0;
    end else if (enable) begin
      divider_threshold <= (vco_frequency * freq_out) / freq_in;
    end
  end

endmodule

// Phase Detector module
module phase_detector (
  input clk_in,
  input clk_out,
  output reg phase_diff
);
  always @(posedge clk_in, posedge clk_out) begin
    phase_diff <= clk_out ^ clk_in;
  end
endmodule

// Low-pass Filter module
module low_pass_filter (
  input clk_in,
  input reset,
  input [7:0] phase_diff,
  inout [31:0] error_accumulator,
  output reg [7:0] error_voltage
);
  reg [7:0] error;
  always @(posedge clk_in) begin
    if (reset) begin
      error_accumulator <= 0;
    end else begin
      error <= phase_diff;
      error_accumulator <= error_accumulator + error;
    end
  end
  always @(posedge clk_in) begin
    error_voltage <= error_accumulator >> 24;
  end
endmodule

// Voltage-controlled Oscillator module
module vco (
  input clk_in,
  input reset,
  inout [31:0] vco_accumulator,
  output reg [31:0] vco_frequency
);
  reg [31:0] vco_increment = 0;
  always @(posedge clk_in) begin
    if (reset) begin
      vco_accumulator <= 0;
    end else begin
      vco_accumulator <= vco_accumulator + vco_increment;
    end
  end
  always @(posedge clk_in) begin
    vco_increment <= (freq_in << 31) / (freq_out * 2);
    vco_frequency <= vco_accumulator[31];
  end
endmodule

// Divider module
module divider (
  input clk_in,
  input [31:0] frequency_in,
  input [31:0] frequency_out,
  output reg clk_out
);
  reg [31:0] accumulator = 0;
  reg [31:0] threshold = 0;
  reg [31:0] count = 0;
  always @(posedge clk_in) begin
    if (count == threshold) begin
      clk_out <= ~clk_out;
      count <= 0;
    end else begin
      count <= count + 1;
    end
  end
  always @(posedge clk_in) begin
    threshold <= (frequency_in * frequency_out) / (2 * frequency_out);
  end
endmodule

module clock_gate (CLK, EN, TE, ENCLK);
  input CLK, EN, TE;
