module operation(input         sclk,   // System clock, negedge
                 input         xclk,   // Half frequency (80 MHz nominal)
                 input         we,     // Write enable for registers to log (@negedge sclk)
                 input  [3:0]  wa,     // Write address for register (4 bits, @negedge sclk)
                 input  [15:0] di,     // 16-bit data in (32 multiplexed)
                 input         en,     // Enable
                 input         trig,   // Leading edge - sample time, trailing set rdy
                 output        ts,     // Timestamp request
                 output        rdy,    // Encoded nmea data ready
                 input         rd_stb, // Encoded nmea data read strobe (increment address)
                 output [15:0] rdata); // Encoded data (16 bits)

  reg  [ 4:0]   raddr;
  reg           rdy=1'b0;
  reg           we_d;
  reg  [ 4:1]   waddr;
  reg  [ 2:0]   trig_d;
  reg  [ 7:0]   denoise_count;
  reg  [ 1:0]   trig_denoise;
  reg           ts;
  reg    [15:0] di_d;

  always @ (negedge sclk) begin
    di_d[15:0] <= di[15:0];
    waddr[4:1] <= wa[3:0];
    we_d <= we;
  end

  always @ (posedge xclk) begin
    if (!en) begin
      trig_d[2:0] <= 3'h0;
    end else begin
      trig_d[2:0] <= {trig_d[1:0], trig};
    end

    if (!en) begin
      trig_denoise[0] <= 1'b0;
    end else if (denoise_count[7:0] == 8'h0) begin
      trig_denoise[0] <= trig_d[2];
    end

    if (trig_d[2] == trig_denoise[0]) begin
      denoise_count[7:0] <= 8'hff;
    end else begin
      denoise_count[7:0] <= denoise_count[7:0] - 1;
    end

    trig_denoise[1] <= trig_denoise[0];
    ts <= !trig_denoise[1] && trig_denoise[0];

    if (!en || ts) begin
      raddr[4:0] <= 5'h0;
    end else if (rd_stb) begin
      raddr[4:0] <= raddr[4:0] + 1;
    end

    if (ts || (rd_stb && (raddr[4:0] == 5'h1b)) || !en) begin
      rdy <= 1'b0;
    end else if (trig_denoise[1] && !trig_denoise[0]) begin
      rdy <= 1'b1;
    end
  end

  myRAM_WxD_D #( .DATA_WIDTH(16), .DATA_DEPTH(5))
            i_odbuf (.D(di_d[15:0]),
                     .WE(we | we_d),
                     .clk(~sclk),
                     .AW({waddr[4:1], we_d}),
                     .AR(raddr[4:0]),
                     .QW(),
                     .QR(rdata[15:0]));

endmodule

module ADC (
  input analog_signal,
  input clk,
  output reg [7:0] digital_signal
);

  reg [7:0] approx_value;
  reg [7:0] temp_value;
  reg [2:0] bit_counter;
  reg conversion_done;

  always @(posedge clk) begin
    if (bit_counter == 0) begin
      approx_value[0] <= analog_signal > ((1 << 7) - 1);
      temp_value <= approx_value;
    end else begin
      approx_value[bit_counter] <= temp_value[bit_counter-1];
      temp_value <= approx_value;
    end

    bit_counter <= bit_counter + 1;

    if (bit_counter == 8) begin
      conversion_done <= 1;
      digital_signal <= approx_value;
    end
  end

  always @(posedge clk) begin
    if (conversion_done) begin
      bit_counter <= 0;
      conversion_done <= 0;
    end
  end

endmodule

module SRFF_sp_tb;

  // Inputs
  reg clock;
  reg reset;
  reg io_input_set;
  reg io_input_reset;
