  // Outputs
  wire io_output_data;

  // Instantiate the Unit Under Test (UUT)
  SRFF_sp uut (
    .clock(clock), 
    .reset(reset), 
    .io_input_set(io_input_set), 
    .io_input_reset(io_input_reset), 
    .io_input_asyn_reset(io_input_asyn_reset), 
    .io_output_data(io_output_data)
  );

  initial begin
    // Initialize inputs
    clock = 0;
    reset = 1;
    io_input_set = 0;
    io_input_reset = 0;
    io_input_asyn_reset = 0;

    // Wait for 2 clock cycles
    #20;

    // Apply synchronous set
    io_input_set = 1;
    #20;
    io_input_set = 0;

    // Wait for 2 clock cycles
    #20;

    // Apply synchronous reset
    io_input_reset = 1;
    #20;
    io_input_reset = 0;

    // Wait for 2 clock cycles
    #20;

    // Apply asynchronous reset
    io_input_asyn_reset = 1;
    #20;
    io_input_asyn_reset = 0;

    // Wait for 2 clock cycles
    #20;

    // Apply asynchronous reset and synchronous set
    io_input_asyn_reset = 1;
    io_input_set = 1;
    #20;
    io_input_asyn_reset = 0;
    io_input_set = 0;

    // Wait for 2 clock cycles
    #20;

    // Apply asynchronous reset and synchronous reset
    io_input_asyn_reset = 1;
    io_input_reset = 1;
    #20;
    io_input_asyn_reset = 0;
    io_input_reset = 0;

    // Wait for 2 clock cycles
    #20;

    // Apply asynchronous reset, synchronous reset, and synchronous set
    io_input_asyn_reset = 1;
    io_input_reset = 1;
    io_input_set = 1;
    #20;
    io_input_asyn_reset = 0;
    io_input_reset = 0;
    io_input_set = 0;

    // Verify output
    $display("Output = %b", io_output_data);
    $finish;
  end

  always #10 clock = ~clock;

endmodule

