    XOR2X1 x5(.IN1(Sum[0]), .IN2(Cin), .Q(c[0]));
    XOR2X1 x6(.IN1(Sum[1]), .IN2(c[0]), .Q(c[1]));
    XOR2X1 x7(.IN1(Sum[2]), .IN2(c[1]), .Q(c[2]));
    XOR2X1 x8(.IN1(Sum[3]), .IN2(c[2]), .Q(c[3]));

    assign Cout = c[3];
endmodule

