module alu_sign(
	input sys_clk,
	input alu_rst,

	input [31:0] a,
	input [31:0] b,
	input valid_i,

	output [31:0] r,
	output reg valid_o
);

reg [31:0] abs_a;
reg [31:0] abs_b;
reg [31:0] abs_r;
reg [1:0] sign;
reg [31:0] a_div_b;

always @(posedge sys_clk) begin
	if(alu_rst)
		valid_o <= 1'b0;
	else
		valid_o <= valid_i;

	// Calculate absolute values of inputs
	if(a[31] == 1)
		abs_a = ~a + 1;
	else
		abs_a = a;

	if(b[31] == 1)
		abs_b = ~b + 1;
	else
		abs_b = b;

	// Determine sign of output
	if(a[31] == 0 && b[31] == 0)
		sign = 2'b00; // both inputs are positive
	else if(a[31] == 1 && b[31] == 0)
		sign = 2'b01; // a is negative, b is positive
	else if(a[31] == 0 && b[31] == 1)
		sign = 2'b10; // a is positive, b is negative
	else if(a[31] == 1 && b[31] == 1)
		sign = 2'b11; // both inputs are negative

	// Calculate output based on sign
	case(sign)
		2'b00: abs_r = 32'h3f800000; // positive / positive = 1.0
		2'b01: abs_r = 32'h80000000; // negative / positive = -0.0
		2'b10: abs_r = 32'h00000000; // positive / negative = +0.0
		2'b11: abs_r = 32'hbf800000; // negative / negative = -1.0
	endcase

	// Calculate division if inputs have different signs
	if(sign != 2'b00 && sign != 2'b11)
		a_div_b = abs_a / abs_b;

	// Set output based on sign and division
	if(sign == 2'b00 || sign == 2'b11)
		r = abs_r;
	else
		r = {sign[1], a_div_b[22:0]} + abs_r[31:23];

end

endmodule

module axi_dmac_reset_manager (
  input clk,
  input resetn,

  input ctrl_pause,
  input ctrl_enable,

  input req_enable,
  output reg req_enabled,

  input dest_clk,
  input dest_ext_resetn,
  input dest_enable,
  output reg dest_enabled,

  input src_clk,
  input src_ext_resetn,
  input src_enable,
  output reg src_enabled
);

  reg [3:0] state = 4'h0;
  reg [10:0] counter = 11'h0;

  assign req_resetn = ~req_enabled;
  assign dest_resetn = ~dest_enabled;
  assign src_resetn = ~src_enabled;

  always @(posedge clk or negedge resetn) begin
    if (~resetn) begin
      state <= 4'h0;
      counter <= 11'h0;
      req_enabled <= 1'b0;
      dest_enabled <= 1'b0;
      src_enabled <= 1'b0;
    end else if (~ctrl_pause) begin
      case (state)
        4'h0: begin
          if (ctrl_enable) begin
            state <= 4'h1;
          end else begin
            req_enabled <= 1'b1;
            dest_enabled <= 1'b1;
            src_enabled <= 1'b1;
          end
        end
        4'h1: begin
          counter <= counter + 1'b1;
          if (counter == 11'h60 || counter == 11'h150 || counter == 11'h185) begin
            req_enabled <= 1'b1;
          end else if (counter == 11'h100 || counter == 11'h110 || counter == 11'h180) begin
            req_enabled <= 1'b0;
          end

          if (counter == 11'h70 || counter == 11'h120 || counter == 11'h170) begin
            dest_enabled <= 1'b1;
          end else if (counter == 11'h80 || counter == 11'h130 || counter == 11'h160) begin
            dest_enabled <= 1'b0;
          end

          if (counter == 11'h90 || counter == 11'h140) begin
            src_enabled <= 1'b1;
          end else if (counter == 11'h190) begin
            src_enabled <= 1'b0;
          end

          if (counter == 11'h1ff) begin
            state <= 4'h2;
            counter <= 11'h0;
          end
        end
        4'h2: begin
          req_enabled <= 1'b0;
          dest_enabled <= 1'b0;
          src_enabled <= 1'b0;
          counter <= counter + 1'b1;
          if (counter == 11'h3ff) begin
            state <= 4'h1;
            counter <= 11'h0;
          end
        end
      endcase
    end
  end

endmodule

module counter16(
