module fifo_async_16x3(I1, wr_clk, I2, rd_clk, I3, I4, I5, I6, Q, O1, O2, O3, O4, O5);

parameter DEPTH = 16;

input [2:0] I1;
input wr_clk;
input [3:0] I2;
input rd_clk;
input [3:0] I3;
input I4;
input I5;
input [3:0] I6;

output [2:0] Q;
output [3:0] O1;
output O2;
output [3:0] O3;
output O4;
output O5;

reg [2:0] Q_reg;
reg [3:0] wr_ptr_reg;
reg [3:0] rd_ptr_reg;
wire [3:0] wr_ptr_next;
wire [3:0] rd_ptr_next;
wire [2:0] Q_next;
wire empty;
wire full;
wire almost_full;

assign Q = Q_reg;
assign O1 = wr_ptr_reg;
assign O2 = empty;
assign O3 = rd_ptr_reg;
assign O4 = full;
assign O5 = almost_full;

// Write pointer logic
always @(posedge wr_clk) begin
    if (I4) begin
        wr_ptr_reg <= 0;
    end else begin
        wr_ptr_reg <= wr_ptr_next;
    end
end

assign wr_ptr_next = (wr_ptr_reg == (DEPTH - 1)) ? 0 : wr_ptr_reg + 1;

// Read pointer logic
always @(posedge rd_clk) begin
    if (I5) begin
        rd_ptr_reg <= 0;
    end else begin
        rd_ptr_reg <= rd_ptr_next;
    end
end

assign rd_ptr_next = (rd_ptr_reg == (DEPTH - 1)) ? 0 : rd_ptr_reg + 1;

// Data logic
always @(posedge wr_clk) begin
    if (wr_ptr_next == rd_ptr_reg) begin
        full <= 1;
    end else begin
        full <= 0;
    end
end

always @(posedge rd_clk) begin
    if (wr_ptr_reg == rd_ptr_reg) begin
        empty <= 1;
    end else begin
        empty <= 0;
    end
end

always @(posedge wr_clk) begin
    if (wr_ptr_next == (DEPTH - 2)) begin
        almost_full <= 1;
    end else begin
        almost_full <= 0;
    end
end

always @(posedge wr_clk) begin
    if (wr_ptr_next == rd_ptr_reg) begin
        Q_reg <= Q_next;
    end
end

assign Q_next = (wr_ptr_next == rd_ptr_reg) ? I1 : Q_reg;

endmodule

module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

    wire [3:0] X1, X2, X3;
    wire C1, C2;

    // First column of XOR gates
    sky130_fd_sc_hd__xor2_1 xor1 (
        .X(X1[0]),
        .A(A[0]),
        .B(B[0]),
        .VPWR(1'b1),
        .VGND(1'b0),
        .VPB(1'b1),
        .VNB(1'b0)
    );
    sky130_fd_sc_hd__xor2_1 xor2 (
        .X(X1[1]),
        .A(A[1]),
        .B(B[1]),
        .VPWR(1'b1),
        .VGND(1'b0),
        .VPB(1'b1),
        .VNB(1'b0)
    );
    sky130_fd_sc_hd__xor2_1 xor3 (
        .X(X1[2]),
        .A(A[2]),
        .B(B[2]),
        .VPWR(1'b1),
        .VGND(1'b0),
        .VPB(1'b1),
        .VNB(1'b0)
    );
    sky130_fd_sc_hd__xor2_1 xor4 (
        .X(X1[3]),
        .A(A[3]),
        .B(B[3]),
        .VPWR(1'b1),
        .VGND(1'b0),
        .VPB(1'b1),
        .VNB(1'b0)
    );

    // Second column of XOR gates
    sky130_fd_sc_hd__xor2_1 xor5 (
        .X(X2[0]),
        .A(X1[0]),
        .B(X1[1]),
        .VPWR(1'b1),
        .VGND(1'b0),
        .VPB(1'b1),
        .VNB(1'b0)
    );
    sky130_fd_sc_hd__xor2_1 xor6 (
        .X(X2[1]),
        .A(X1[2]),
        .B(X1[3]),
        .VPWR(1'b1),
        .VGND(1'b0),
        .VPB(1'b1),
        .VNB(1'b0)
    );

    // Third column of XOR gates
    sky130_fd_sc_hd__xor2_1 xor7 (
        .X(X3[0]),
        .A(X2[0]),
        .B(X2[1]),
        .VPWR(1'b1),
        .VGND(1'b0),
        .VPB(1'b1),
        .VNB(1'b0)
    );

    // Final XOR gate and carry-out
    sky130_fd_sc_hd__xor2_1 xor8 (
        .X(S[0]),
        .A(X3[0]),
        .B(Cin),
        .VPWR(1'b1),
        .VGND(1'b0),
        .VPB(1'b1),
        .VNB(1'b0)
    );
    assign Cout = X2[0] | (X1[2] & X1[3]) | (X1[1] & X1[3]) | (X1[1] & X1[2] & Cin);

    // Carry-in and carry-out for first column
    sky130_fd_sc_hd__xor2_1 xor9 (
        .X(C1),
        .A(A[0]),
        .B(B[0]),
        .VPWR(1'b1),
        .VGND(1'b0),
        .VPB(1'b1),
        .VNB(1'b0)
    );
    assign X2[0] = C1;
    sky130_fd_sc_hd__xor2_1 xor10 (
        .X(C2),
        .A(C1),
        .B(X1[0]),
        .VPWR(1'b1),
        .VGND(1'b0),
        .VPB(1'b1),
        .VNB(1'b0)
    );
    assign X3[1] = C2;

    // Carry-in and carry-out for second column
    sky130_fd_sc_hd__xor2_1 xor11 (
        .X(C1),
        .A(A[1]),
        .B(B[1]),
        .VPWR(1'b1),
        .VGND(1'b0),
        .VPB(1'b1),
        .VNB(1'b0)
    );
    assign X2[1] = C1;
    sky130_fd_sc_hd__xor2_1 xor12 (
        .X(C2),
        .A(C1),
        .B(X1[1]),
        .VPWR(1'b1),
        .VGND(1'b0),
        .VPB(1'b1),
        .VNB(1'b0)
    );
    assign X3[2] = C2;

    // Carry-in and carry-out for third column
    sky130_fd_sc_hd__xor2_1 xor13 (
        .X(C1),
        .A(A[2]),
        .B(B[2]),
        .VPWR(1'b1),
        .VGND(1'b0),
        .VPB(1'b1),
        .VNB(1'b0)
    );
    assign X2[2] = C1;
    sky130_fd_sc_hd__xor2_1 xor14 (
        .X(C2),
        .A(C1),
        .B(X1[2]),
        .VPWR(1'b1),
        .VGND(1'b0),
        .VPB(1'b1),
        .VNB(1'b0)
    );
    assign X3[3] = C2;

    // Carry-in and carry-out for fourth column
    sky130_fd_sc_hd__xor2_1 xor15 (
        .X(C1),
        .A(A[3]),
        .B(B[3]),
        .VPWR(1'b1),
        .VGND(1'b0),
        .VPB(1'b1),
        .VNB(1'b0)
    );
    assign X2[3] = C1;
    assign S[1:3] = X3[1:3];
    sky130_fd_sc_hd__xor2_1 xor16 (
        .X(Cout),
        .A(X3[0]),
        .B(C1),
        .VPWR(1'b1),
        .VGND(1'b0),
        .VPB(1'b1),
        .VNB(1'b0)
    );

endmodule

