module binary_to_bcd (
  input [n-1:0] bin,
  output [3:0] bcd
);

parameter n = 8; // number of bits in the binary number

assign bcd[0] = (bin >= 5'd10) ? 4'd1 : 4'd0;
assign bcd[1] = (bin >= 5'd10) ? (bin >= 5'd50) ? 4'd1 : 4'd0 : (bin >= 5'd5) ? 4'd1 : 4'd0;
assign bcd[2] = (bin >= 5'd10) ? (bin >= 5'd50) ? (bin >= 5'd100) ? 4'd1 : 4'd0 : (bin >= 5'd30) ? 4'd1 : 4'd0 : (bin >= 5'd2) ? 4'd1 : 4'd0;
assign bcd[3] = (bin >= 5'd10) ? (bin >= 5'd50) ? (bin >= 5'd100) ? (bin >= 5'd200) ? 4'd2 : 4'd1 : (bin >= 5'd80) ? 4'd1 : 4'd0 : (bin >= 5'd20) ? 4'd1 : 4'd0 : (bin >= 5'd1) ? 4'd1 : 4'd0;

