module johnson_counter (
    input clk,
    input rst_n,
    output reg [15:0] out_vec
);

    reg [3:0] state;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            state <= 4'b0000;
        end else begin
            case (state)
                4'b0000: state <= 4'b1000;
                4'b1000: state <= 4'b1100;
                4'b1100: state <= 4'b1110;
                4'b1110: state <= 4'b1111;
                4'b1111: state <= 4'b0111;
                4'b0111: state <= 4'b0011;
                4'b0011: state <= 4'b0001;
                4'b0001: state <= 4'b0000;
            endcase
        end
    end

    assign out_vec = {state, state};

endmodule

module random_number_generator (
    input [2:0] in_vec,
    input [15:0] johnson_vec,
    output reg [9:0] out_vec
);

    always @(*) begin
        case ({in_vec, johnson_vec[15:13]})
            3'b000: out_vec = johnson_vec[12:3];
            3'b001: out_vec = johnson_vec[11:2];
            3'b010: out_vec = johnson_vec[10:1];
            3'b011: out_vec = johnson_vec[9:0];
            3'b100: out_vec = johnson_vec[8:7] + johnson_vec[6:5] + johnson_vec[4:3];
            3'b101: out_vec = johnson_vec[7:6] + johnson_vec[5:4] + johnson_vec[3:2];
            3'b110: out_vec = johnson_vec[6:5] + johnson_vec[4:3] + johnson_vec[2:1];
            3'b111: out_vec = johnson_vec[5:4] + johnson_vec[3:2] + johnson_vec[1:0];
        endcase
    end

endmodule

module top_module (
    input clk,
    input rst_n,
    input [2:0] vec,
    output [9:0] outv
);

    johnson_counter jc (
        .clk(clk),
        .rst_n(rst_n),
        .out_vec(out_jc)
    );

    binary_encoder be (
        .in_vec(vec),
        .out_vec(out_be),
        .out0(out0),
        .out1(out1),
        .out2(out2)
    );

    random_number_generator rng (
        .in_vec({out0, out1, out2}),
        .johnson_vec(out_jc),
        .out_vec(outv)
    );

    reg [15:0] out_jc;
    wire [2:0] out_be;
    wire out0, out1, out2;

endmodule

