        compare_mux <= 1;
    end else begin
        compare_mux <= 0;
    end
end

always @(current_state, shift_delay) begin
    if (current_state == Compare && shift_delay < NOS_STGS+1) begin
        compare_enable <= 1;
    end else begin
        compare_enable <= 0;
    end
end

always @(current_state) begin
    if (current_state == DatadeMux) begin
        input_ready <= 1;
    end else begin
        input_ready <= 0;
    end
end

always @(current_state) begin
    if (current_state == Shift || current_state == Idle) begin
        shift_amt_clr <= 1;
    end else begin
        shift_amt_clr <= 0;
    end
end

always @(current_state) begin
    if (current_state == Shift_Dat_ld) begin
        a_ld <= 1;
    end else begin
        a_ld <= 0;
    end
end

always @(current_state, shift_delay) begin
    if (current_state == Compare && shift_delay == NOS_STGS+NOS_KEY+1) begin
        shift_amt_ld <= 1;
    end else begin
        shift_amt_ld <= 0;
    end
end

always @ (current_state, datInReady, shift_delay) begin
    case (current_state)
        Idle: if (datInReady == 1) begin
                next_state = DataInload;
            end else begin
                next_state = Idle;
            end
        DataInload: begin
            datin_clr = 1;
            a_clr = 1;
            next_state = DatadeMux;
        end
        DatadeMux: begin
            next_state = Shift;
        end
        Shift: begin
            shift_amt_ld = 0;
            if (shift_delay >= NOS_STGS+1) begin
                next_state = Shift_Dat_ld;
            end else begin
                next_state = Shift;
            end
        end
        Shift_Dat_ld: begin
            next_state = Compare;
        end
        Compare: begin
            if (shift_delay == NOS_STGS+NOS_KEY+1) begin
                next_state = Shift;
            end else begin
                next_state = Compare;
            end
        end
        default: next_state = current_state;
    endcase
end

endmodule

