module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out
    );

    reg [7:0] shift_reg [1:0];
    reg [7:0] adder_out;
    reg [1:0] counter;
    wire [7:0] shift_reg_out;

    shift_register sr1(
        .clk(clk),
        .rst_n(rst_n),
        .data_in(data_in),
        .data_out(shift_reg[0])
    );

    shift_register sr2(
        .clk(clk),
        .rst_n(rst_n),
        .data_in(shift_reg[0]),
        .data_out(shift_reg[1])
    );

    adder add(
        .in1(shift_reg_out),
        .in2(adder_out),
        .out(adder_out)
    );

    functional_module fm(
        .in1(shift_reg_out),
        .in2(adder_out),
        .out(data_out)
    );

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shift_reg[0] <= 8'b0;
            shift_reg[1] <= 8'b0;
            adder_out <= 8'b0;
            counter <= 2'b0;
            valid_b <= 1'b0;
        end else begin
            if (valid_a && ready_b) begin
                shift_reg[0] <= data_in;
                counter <= counter + 1;
                if (counter == 2'b110) begin
                    valid_b <= 1'b1;
                end
            end

            if (valid_b && ready_a) begin
                counter <= 2'b0;
                valid_b <= 1'b0;
            end
        end
    end

    assign shift_reg_out = shift_reg[1];
    assign ready_a = !valid_b;

endmodule

