module top_module(
    input wire [15:0] in,
    input wire select,
    output wire [7:0] out
);

    wire [7:0] shifter1_upper;
    wire [7:0] shifter1_lower;
    wire [7:0] shifter2_upper;
    wire [7:0] shifter2_lower;
    wire [7:0] adder_out;

    barrel_shifter shifter1(
        .in(in),
        .shift_amount(8),
        .upper(shifter1_upper),
        .lower(shifter1_lower)
    );

    barrel_shifter shifter2(
        .in(in),
        .shift_amount(-8),
        .upper(shifter2_upper),
        .lower(shifter2_lower)
    );

    adder adder(
        .in1(select ? shifter1_upper : shifter2_upper),
        .in2(select ? shifter1_lower : shifter2_lower),
        .out(adder_out)
    );

    assign out = adder_out;

endmodule

