module binary_to_bcd_converter (
    input [3:0] bin_in,
    output [7:0] bcd_out,
    output overflow
);

    assign overflow = (bin_in > 9) ? 1'b1 : 1'b0;

    always @* begin
        case (bin_in)
            4'b0000: bcd_out = 8'b00000000;
            4'b0001: bcd_out = 8'b00000001;
            4'b0010: bcd_out = 8'b00000010;
            4'b0011: bcd_out = 8'b00000011;
            4'b0100: bcd_out = 8'b00000100;
            4'b0101: bcd_out = 8'b00000101;
            4'b0110: bcd_out = 8'b00000110;
            4'b0111: bcd_out = 8'b00000111;
            4'b1000: bcd_out = 8'b00001000;
            4'b1001: bcd_out = 8'b00001001;
            4'b1010: bcd_out = 8'b00010000;
            4'b1011: bcd_out = 8'b00010001;
            4'b1100: bcd_out = 8'b00100000;
            4'b1101: bcd_out = 8'b00100001;
            4'b1110: bcd_out = 8'b00100010;
            4'b1111: bcd_out = 8'b00100011;
            default: bcd_out = 8'b00000000;
        endcase
    end

endmodule

module twos_complement_converter (
    input [3:0] twos_comp_in,
    input rst_n,
    input en,
    output reg [3:0] twos_comp_out
);

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            twos_comp_out <= 4'b0000;
        end else if (en) begin
            twos_comp_out <= ~twos_comp_in + 1;
        end
    end

endmodule

