    input en,
    input [3:0] bin_in,
    output [7:0] bcd_out,
    output overflow,
    output reg [3:0] twos_comp_out,
    output reg [7:0] final_out
);

    binary_to_bcd_converter bcd_converter (
        .bin_in(bin_in),
        .bcd_out(bcd_out),
        .overflow(overflow)
    );

    twos_complement_converter twos_converter (
        .twos_comp_in(bcd_out[3:0]),
