module initiator
  (input  wire        clk,
   input  wire        rst,
   output reg  `REQ   req,
   input  wire `RES   res);

   parameter  name = 1;

   reg [31:0] counter, data;
   reg [31:0] dataExpect;
   reg        dataValid;
   wire       pause = ^counter[1:0];

   always @(posedge clk)
     if (rst) begin
        counter <= name << 16;
        req     <= 0;
        dataValid <= 0;
        dataExpect <= 0;
     end else begin
        dataExpect <= data;
        dataValid <= req`R & ~res`WAIT;
        if (dataValid) begin
           if (dataExpect != res`RD)
             $display("%6d init%d got %x, expected %x !!! BAD!",
                      $time, name, res`RD, dataExpect);
           else
             $display("%6d init%d got %x as expected", $time, name, res`RD);
        end

        if (~res`WAIT) begin
           counter <= counter + 1;
           if (pause) begin
              req`R   <= 0;
           end else begin
              req`R   <= 1;
              req`A   <= counter;
              data    <= counter;
              $display("%6d init%d requests %x", $time, name, counter);
           end
        end
     end
endmodule

module avalon2rcn
(
    input av_clk,
    input av_rst,

    output av_waitrequest,
    input [21:0] av_address,
    input av_write,
    input av_read,
    input [3:0] av_byteenable, 
    input [31:0] av_writedata,
    output [31:0] av_readdata,
    output av_readdatavalid,

    input [68:0] rcn_in,
    output [68:0] rcn_out
);
    parameter MASTER_ID = 6'h3F;

    // Define registers to hold state information
    reg [68:0] rin;
    reg [68:0] rout;
    reg [2:0] next_rd_id;
    reg [2:0] wait_rd_id;
    reg [2:0] next_wr_id;
    reg [2:0] wait_wr_id;

    // Assign the output of the module to the RCN output signal
    assign rcn_out = rout;

    // Define a wire to hold the master ID
    wire [5:0] my_id = MASTER_ID;

    // Define a wire to hold whether the current RCN transaction is a response to this module's request
    wire my_resp = rin[68] && !rin[67] && (rin[65:60] == my_id) && 
                   ((rin[66]) ? (rin[33:32] == wait_wr_id[1:0]) : (rin[33:32] == wait_rd_id[1:0]));

    // Define a wire to hold whether the Avalon protocol is currently waiting for a response
    wire bus_stall = (rin[68] && !my_resp) || ((av_read) ? (next_rd_id == wait_rd_id) : (next_wr_id == wait_wr_id));
    assign av_waitrequest = bus_stall;

    // Define wires to hold the request signal and whether the request is valid
    wire req_valid;
    wire [68:0] req;

    // Define an always block to update the state registers on every clock cycle
    always @ (posedge av_clk or posedge av_rst)
        if (av_rst)
        begin
            rin <= 69'd0;
            rout <= 69'd0;
            next_rd_id <= 3'b000;
            wait_rd_id <= 3'b100;
            next_wr_id <= 3'b000;
            wait_wr_id <= 3'b100;
        end
        else
        begin
            rin <= rcn_in;
            rout <= (req_valid) ? req : (my_resp) ? 69'd0 : rin;
            next_rd_id <= (req_valid && av_read) ? next_rd_id + 3'd1 : next_rd_id;
            wait_rd_id <= (my_resp && !rin[66]) ? wait_rd_id + 3'd1 : wait_rd_id;
            next_wr_id <= (req_valid && av_write) ? next_wr_id + 3'd1 : next_wr_id;
            wait_wr_id <= (my_resp && rin[66]) ? wait_wr_id + 3'd1 : wait_wr_id;
        end

    // Define a wire to hold whether the current request is valid
    assign req_valid = (av_write || av_read) && !bus_stall;

    // Define a wire to hold the sequence number for the current transaction
    wire [1:0] seq = (av_read) ? next_rd_id[1:0] : next_wr_id[1:0];

    // Define a wire to hold the request signal
    assign req = {1'b1, 1'b1, av_write, my_id, av_byteenable, av_address[21:0], seq, av_writedata};

    // Define wires to hold whether the read data is valid and the read data itself
    assign av_readdatavalid = my_resp && !rin[66];
    assign av_readdata = rin[31:0];

endmodule

