module LZW (
  input clk,
  input rst,
  input [7:0] in,
  output [7:0] out
);

  reg [15:0] dictionary [0:65535];
  reg [15:0] next_code;
  reg [7:0] current_string;
  reg [15:0] new_string;
  reg [7:0] output_code;
  reg [7:0] input_code;
  reg compress;
  reg decompress;
  reg [7:0] state;

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      state <= 0;
      next_code <= 256;
      compress <= 0;
      decompress <= 0;
    end else begin
      case (state)
        0: begin
          if (in == 8'h01) begin
            compress <= 1;
            state <= 1;
          end else if (in == 8'h02) begin
            decompress <= 1;
            state <= 2;
          end
        end

        1: begin
          if (compress) begin
            current_string <= in;
            state <= 3;
          end
        end

        2: begin
          if (decompress) begin
            input_code <= in;
            state <= 4;
          end
        end

        3: begin
          new_string <= {current_string, in};
          if (dictionary[new_string] != 0) begin
            current_string <= dictionary[new_string];
          end else begin
            output_code <= current_string;
            dictionary[new_string] <= next_code;
            next_code <= next_code + 1;
            current_string <= in;
          end
        end

        4: begin
          if (input_code < 256) begin
            out <= input_code;
          end else begin
            out <= dictionary[input_code];
          end
          dictionary[next_code] <= {dictionary[input_code], dictionary[input_code][7:0]};
          next_code <= next_code + 1;
        end

      endcase
    end
  end

  assign out = output_code;

endmodule

module top_module (
    input clk,
    input [7:0] d1,
    input [7:0] d2,
    input select,
    output reg [7:0] q,
    output reg error_flag
);

    reg [7:0] shift_reg;
    reg [7:0] dff_out;
    reg parity_bit;

    // Parity Checker
    always @(*) begin
        parity_bit = d1 ^ d2;
        parity_bit = parity_bit ^ (parity_bit >> 4);
        parity_bit = parity_bit ^ (parity_bit >> 2);
        parity_bit = parity_bit ^ (parity_bit >> 1);
        parity_bit = ~parity_bit[0];
    end

    // Control Logic
    always @(posedge clk) begin
        if (select == 1'b0) begin
            // D Flip-Flop
            dff_out <= d1;
            shift_reg <= shift_reg;
        end else begin
            // Shift Register
            dff_out <= dff_out;
            shift_reg <= {shift_reg[6:0], d2};
        end
    end

    // Output Logic
    always @(posedge clk) begin
        if (select == 1'b0) begin
            q <= dff_out;
        end else begin
            q <= shift_reg;
        end
        error_flag <= parity_bit;
    end

endmodule

