module DLLDELD(
	input A, DDRDEL, LOADN, MOVE, DIRECTION,
	output Z, CFLAG
);

	parameter DEL_ADJ = "PLUS";
	parameter DEL_VAL = 0;
	parameter DELAY_SIZE = 4;

	reg [DELAY_SIZE-1:0] delay_line;
	reg [DELAY_SIZE-1:0] delay_line_next;

	assign Z = DDRDEL ? delay_line[DELAY_SIZE-1] : A;

	always @(*) begin
		delay_line_next = delay_line;
		if (LOADN == 0) begin
			delay_line_next[0] = A;
		end
		if (MOVE == 1) begin
			delay_line_next[0] = A;
			CFLAG = 0;
		end
		if (DIRECTION == "PLUS") begin
			if (DEL_ADJ == "PLUS") begin
				delay_line_next = {delay_line[DELAY_SIZE-2:0], delay_line[DELAY_SIZE-1]+DEL_VAL};
			end else begin
				delay_line_next = {delay_line[DELAY_SIZE-2:0], delay_line[DELAY_SIZE-1]-DEL_VAL};
			end
		end else begin
			if (DEL_ADJ == "PLUS") begin
				delay_line_next = {delay_line[DELAY_SIZE-2:0], delay_line[DELAY_SIZE-1]-DEL_VAL};
			end else begin
				delay_line_next = {delay_line[DELAY_SIZE-2:0], delay_line[DELAY_SIZE-1]+DEL_VAL};
			end
		end
		if (delay_line_next[DELAY_SIZE-1] != delay_line[DELAY_SIZE-1]) begin
			CFLAG = 1;
		end
	end

	always @(posedge DDRDEL) begin
		delay_line <= delay_line_next;
	end

endmodule

module barrel_shift_mux(
    input [1023:0] in, // 1024-bit input vector
    input [7:0] sel, // 8-bit select input for the barrel shifter and multiplexer
    output [3:0] out // 4-bit output from the selected input
);

    // Barrel shifter
    wire [1023:0] shifted_in;
    assign shifted_in = (sel[7]) ? {in[1023:768], in[767:0]} :
                      (sel[6]) ? {in[767:512], in[511:0], in[1023:768]} :
                      (sel[5]) ? {in[511:256], in[255:0], in[767:512], in[1023:768]} :
                      (sel[4]) ? {in[255:0], in[767:512], in[1023:256]} :
                      (sel[3]) ? {in[511:0], in[1023:512]} :
                      (sel[2]) ? {in[255:0], in[767:256], in[1023:512]} :
                      (sel[1]) ? {in[511:256], in[1023:768]} :
                                 {in[767:0], in[1023:768]};

    // Multiplexer
    wire [255:0] mux_in;
    assign mux_in = shifted_in[3:0 + (sel[0] * 4) + (sel[1] * 256 * 4) + (sel[2] * 256 * 256 * 4) + (sel[3] * 256 * 256 * 256 * 4)];
    assign out = mux_in[3:0 + (sel[0] * 4)];

endmodule

module BRANCH_PREDICTOR #(
        parameter   ADDRESS_WIDTH       = 32                                ,

        parameter HIGH                  = 1'b1                              ,
        parameter LOW                   = 1'b0
    ) (
        input                               CLK                             ,
        input   [ADDRESS_WIDTH - 1  : 0]    PC                              ,
        input   [ADDRESS_WIDTH - 1  : 0]    PC_EXECUTION                    ,
        input   [ADDRESS_WIDTH - 1  : 0]    PC_PREDICT_LEARN                ,
        input                               PC_PREDICT_LEARN_SELECT         ,
        output  [ADDRESS_WIDTH - 1  : 0]    PC_PREDICTED                    ,
        output                              PC_PREDICTOR_STATUS                   
    );

    reg     [ADDRESS_WIDTH - 1  : 0]    pc_predicted_reg                    ;
    reg                                 pc_predictor_status_reg             ;
    reg     [3:0]                       prediction_counter                  ;

    initial
    begin
        pc_predicted_reg            = 32'b0         ;
        pc_predictor_status_reg     = LOW           ;
        prediction_counter          = 2'b00         ;
    end

    always@(*)
    begin
        if (PC == PC_EXECUTION) begin
            // Prediction was correct
            pc_predictor_status_reg = LOW;
        end
        else begin
            // Prediction was incorrect
            pc_predictor_status_reg = HIGH;
        end

        if (PC_PREDICT_LEARN_SELECT) begin
            // Use PC_PREDICT_LEARN for prediction
            case (prediction_counter)
                2'b00: pc_predicted_reg = PC_PREDICT_LEARN;
                2'b01: pc_predicted_reg = PC + 4;
                2'b10: pc_predicted_reg = PC + 8;
                2'b11: pc_predicted_reg = PC + 12;
            endcase
        end
        else begin
            // Use PC_EXECUTION for prediction
            case (prediction_counter)
                2'b00: pc_predicted_reg = PC_EXECUTION;
                2'b01: pc_predicted_reg = PC + 4;
                2'b10: pc_predicted_reg = PC + 8;
                2'b11: pc_predicted_reg = PC + 12;
            endcase
        end
    end

    always@(posedge CLK)
    begin
        // Update prediction counter based on prediction correctness
        if (PC == PC_EXECUTION) begin
            if (prediction_counter != 2'b11) begin
                prediction_counter <= prediction_counter + 1;
            end
        end
        else begin
            if (prediction_counter != 2'b00) begin
                prediction_counter <= prediction_counter - 1;
            end
        end
    end

    assign PC_PREDICTED             = pc_predicted_reg          ;
    assign PC_PREDICTOR_STATUS      = pc_predictor_status_reg   ;      

endmodule

module one_hot_state_machine (
  input clk,
  input rst,
  output reg [n-1:0] out
);

parameter n = 4; // number of output signals

reg [n-1:0] state;
always @ (posedge clk) begin
  if (rst) begin
    state <= {n{1'b0}} | 1'b1; // reset to default state
  end else begin
    case (state)
      // define states as unique binary codes
      4'b0001: state <= 4'b0010;
      4'b0010: state <= 4'b0100;
      4'b0100: state <= 4'b1000;
      4'b1000: state <= 4'b0001;
      default: state <= {n{1'b0}} | 1'b1; // reset to default state if invalid state
    endcase
  end
end

// connect outputs to flip-flops based on current state
always @ (state) begin
  out = {n{1'b0}};
  out[state] = 1'b1;
end

endmodule

