module booth_multiplier (
    input signed [1:0] A,
    input signed [1:0] B,
    output reg signed [3:0] P,
    output reg F
);

reg signed [2:0] M;
reg signed [1:0] Q;
reg signed [3:0] A_shifted;
reg signed [3:0] P_shifted;

always @(*) begin
    M = {B, 2'b0};
    Q = {A, 1'b0};
    A_shifted = {A, 2'b0};
    P_shifted = {P, 2'b0};
end

always @(posedge clk) begin
    if (Q[0] == 1 && Q[1] == 0) begin
        P_shifted = P_shifted - M;
        Q = {Q[1], Q[0], 1'b0};
    end
    else if (Q[0] == 0 && Q[1] == 1) begin
        P_shifted = P_shifted + M;
        Q = {Q[1], Q[0], 1'b0};
    end
    A_shifted = {A_shifted[2], A_shifted};
    Q = {Q[1], Q[0], A_shifted[0]};
end

always @(*) begin
    P = P_shifted[3:0];
    F = (P_shifted[4] == 1 || P_shifted[5] == 1);
end

endmodule

