wire save_data;

// Instantiate the modules for loading and saving data
load_file load (
    .out(file_data),
    .send(load_data)
);

save_file save (
    .c(data_out),
    .received(received_data)
);

// Define the FSM
always @(posedge clk) begin
    if (rst) begin
        state <= IDLE;
        buffer <= 8'b0;
        bit_counter <= 3'b0;
        send_data <= 1'b0;
        receive_data <= 1'b0;
        received_data <= 1'b0;
    end else begin
        case (state)
            IDLE: begin
                if (send) begin
                    state <= SENDING;
                    buffer <= data;
                    bit_counter <= 3'b0;
                    send_data <= 1'b1;
                end else if (rxd) begin
                    state <= RECEIVING;
                    bit_counter <= 3'b0;
                    receive_data <= 1'b1;
                end
            end
            SENDING: begin
                if (bit_counter == 3'b0) begin
                    txd <= 1'b0;
                end else begin
                    txd <= buffer[0];
                    buffer <= {buffer[6:0], 1'b0};
                end
                bit_counter <= bit_counter + 1;
                if (bit_counter == 3'b100) begin
                    state <= IDLE;
                    send_data <= 1'b0;
                end
            end
            RECEIVING: begin
                if (bit_counter == 3'b0) begin
                    data_out <= 8'b0;
                end else if (bit_counter == 3'b1) begin
                    received_data <= 1'b1;
                end else begin
                    data_out <= {data_out[6:0], rxd};
                end
                bit_counter <= bit_counter + 1;
                if (bit_counter == 3'b100) begin
                    state <= IDLE;
                    receive_data <= 1'b0;
                end
            end
        endcase
    end
end

// Load data from a file
assign load_data = receive_data;
assign buffer = file_data;

// Save data to a file
assign save_data = send_data;
assign received = received_data;

