  end else begin
    case (state)
      RED: begin
        red_light <= 1'b1;
        yellow_light <= 1'b0;
        green_light <= 1'b0;
        if (pedestrian_button) begin
          state <= YELLOW_PED;
        end else begin
          state <= YELLOW;
        end
      end
      YELLOW: begin
        red_light <= 1'b0;
        yellow_light <= 1'b1;
        green_light <= 1'b0;
        state <= GREEN;
      end
      GREEN: begin
        red_light <= 1'b0;
        yellow_light <= 1'b0;
        green_light <= 1'b1;
        if (pedestrian_button) begin
          state <= YELLOW_PED;
        end else begin
          state <= RED;
        end
      end
      YELLOW_PED: begin
        red_light <= 1'b0;
        yellow_light <= 1'b1;
        green_light <= 1'b0;
        state <= RED;
      end
    endcase
  end
end

endmodule

module top_module (
    input clk,
    input [7:0] in1,      // Input to the rising and falling edge detector module
    input [15:0] in2,     // Input to the 16-bit splitter module
    output [15:0] out,    // Output of the combined module
    output edge_detected  // Output of the additional functional module
);

    // Instantiate the rising and falling edge detector module
    edge_detector ed (
        .clk(clk),
        .in(in1),
        .rising_edge_detected(rising_edge_detected),
        .falling_edge_detected(falling_edge_detected)
    );

    // Instantiate the 16-bit splitter module
    splitter sp (
        .in(in2),
        .out1(out1),
        .out2(out2)
    );

    // Concatenate the two 8-bit outputs of the splitter module to form a 16-bit vector
    assign out = {out1, out2};

    // Detect if there is any edge in the input signal
    assign edge_detected = (rising_edge_detected || falling_edge_detected);

    // Declare internal signals
    reg rising_edge_detected;
    reg falling_edge_detected;
    wire [7:0] out1;
    wire [7:0] out2;

endmodule

// Define the rising and falling edge detector module
module edge_detector (
    input clk,
    input [7:0] in,
    output reg rising_edge_detected,
    output reg falling_edge_detected
);

    // Declare internal signals
    reg [7:0] previous_value;

    // Detect rising and falling edges
    always @(posedge clk) begin
        if (in > previous_value) begin
            rising_edge_detected <= 1;
        end else begin
            rising_edge_detected <= 0;
        end

        if (in < previous_value) begin
            falling_edge_detected <= 1;
        end else begin
            falling_edge_detected <= 0;
        end

        previous_value <= in;
    end

endmodule

// Define the 16-bit splitter module
module splitter (
    input [15:0] in,
    output reg [7:0] out1,
    output reg [7:0] out2
);

    // Split the input into two 8-bit outputs
    always @(in) begin
        out1 <= in[7:0];
        out2 <= in[15:8];
    end

endmodule

module top_module (
    input clk,
    input reset,
