    output [7:0] and_out
);

    wire [7:0] mux_out;
    wire [3:0] counter_out_internal;
    wire [7:0] and_out_internal;

    // instantiate modules
    mux_2to1 mux_inst (
        .d1(d1),
        .d2(d2),
        .sel(sel),
        .out(mux_out)
    );

    flip_flops flip_flops_inst (
        .clk(clk),
        .reset(reset),
        .d(mux_out),
        .q(flip_flop_out)
    );

    binary_counter counter_inst (
        .clk(clk),
        .reset(reset),
        .out(counter_out_internal)
    );

    bitwise_and and_inst (
        .in1(flip_flop_out),
        .in2(counter_out_internal),
        .out(and_out_internal)
    );

    // control logic
    always @(posedge clk, posedge reset) begin
        if (reset) begin
            counter_out <= 4'b0;
            and_out <= 8'b0;
        end else begin
            if (sel) begin
                counter_out <= counter_out_internal;
                and_out <= and_out_internal;
            end else begin
                counter_out <= 4'b0;
                and_out <= 8'b0;
            end
        end
    end

endmodule

