module booth_multiplier (
    input [3:0] A,
    input [3:0] B,
    output [7:0] product
);

reg [7:0] partial_product [0:3];
reg [4:0] multiplier;
reg [2:0] counter;
reg sign_bit;
reg [3:0] A_reg;
reg [3:0] B_reg;

assign product = partial_product[3];

always @(*) begin
    A_reg = A;
    B_reg = B;
    multiplier = {2'b0, B_reg};
    counter = 3;
    sign_bit = 0;
    partial_product[0] = {4'b0, A_reg};

    while(counter > 0) begin
        if(multiplier[1:0] == 2'b01) begin
            partial_product[counter] = partial_product[counter-1] + {4'b0, A_reg};
        end else if(multiplier[1:0] == 2'b10) begin
            partial_product[counter] = partial_product[counter-1] - {4'b0, A_reg};
        end
        multiplier = {multiplier[2], multiplier[1], sign_bit};
        sign_bit = multiplier[0];
        counter = counter - 1;
    end
    partial_product[3] = {partial_product[3][7], partial_product[3][7:1]};
end

endmodule

