    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB;
    supply0 VNB;

    assign X = ~A_N & B;

endmodule

module newton_interp(
  input sys_clk,
  input load,
  input next_point,
  input signed [17:0] init,
  input positive,
  input [16:0] q,
  input [16:0] r,
  input [16:0] divisor,
  output signed [17:0] o
);

  reg positive_r;
  reg [16:0] q_r;
  reg [16:0] r_r;
  reg [16:0] divisor_r;
  always @(posedge sys_clk) begin
    if(load) begin
      positive_r <= positive;
      q_r <= q;
      r_r <= r;
      divisor_r <= divisor;
    end
  end

  reg [17:0] err;
  reg correct;
  reg signed [17:0] o_r;
  assign o = o_r;
  always @(posedge sys_clk) begin
    if(load) begin
      err = 18'd0;
      o_r = init;
    end else if(next_point) begin
      err = err + r_r;
      correct = (err[16:0] > {1'b0, divisor_r[16:1]}) & ~err[17];
      if(positive_r) begin
        o_r = o_r + {1'b0, q_r};
        if(correct)
          o_r = o_r + 18'd1;
      end else begin
        o_r = o_r - {1'b0, q_r};
        if(correct)
          o_r = o_r - 18'd1;
      end
      if(correct)
        err = err - {1'b0, divisor_r};
    end
  end
endmodule

module VVI_pacemaker
(
    input wire clk,
    input wire VPulse_eI,
    input wire reset,
    output wire VPace_eO,
    output wire VRefractory_eO,
    output wire VRP_Timer_Timeout_eI,
    output wire VRP_Start_Timer_eO,
    output wire LRI_Timer_Start_eO,
    output wire LRI_Timer_Stop_eO,
    output reg [15:0] VRP_Timeout_Value_O,
    output reg [15:0] LRI_Timeout_Value_O
);

reg [15:0] VRP_Timer_Value;
reg [15:0] LRI_Timer_Value;
reg VRP_Timer_Counting;
reg LRI_Timer_Counting;
reg VRP_Timer_Timeout;
reg LRI_Timer_Timeout;
reg [1:0] state;

parameter IDLE = 2'b00;
parameter WAIT_VRP = 2'b01;
parameter WAIT_LRI = 2'b10;

wire [15:0] VRP_Timeout_Value;
wire [15:0] LRI_Timeout_Value;

assign VRP_Timeout_Value_O = VRP_Timeout_Value;
assign LRI_Timeout_Value_O = LRI_Timeout_Value;

wire VRP_Start_Timer;
wire LRI_Timer_Start;
wire LRI_Timer_Stop;

assign VRP_Start_Timer_eO = VRP_Start_Timer;
assign LRI_Timer_Start_eO = LRI_Timer_Start;
assign LRI_Timer_Stop_eO = LRI_Timer_Stop;
assign VRP_Timer_Timeout_eI = VRP_Timer_Timeout;

reg [15:0] clk_div_value = 0;
reg clk_divd = 0;

always@(posedge clk) begin
    clk_div_value = clk_div_value + 1;
    if(clk_div_value >= 2000) begin
        clk_divd = ~clk_divd;
        clk_div_value = 0;
    end
end

always@(posedge clk_divd) begin
    if(reset) begin
        state <= IDLE;
        VRP_Timer_Value <= 0;
        LRI_Timer_Value <= 0;
        VRP_Timer_Counting <= 0;
        LRI_Timer_Counting <= 0;
        VRP_Timer_Timeout <= 0;
        LRI_Timer_Timeout <= 0;
    end else begin
        case(state)
            IDLE: begin
                VPace_eO <= 0;
                VRefractory_eO <= 0;
                if(VPulse_eI) begin
                    VRP_Timer_Value <= 0;
                    VRP_Timer_Counting <= 1;
                    VRP_Timer_Timeout <= 0;
                    state <= WAIT_VRP;
                end else begin
                    state <= IDLE;
                end
            end
            WAIT_VRP: begin
                VPace_eO <= 0;
                VRefractory_eO <= 0;
                if(VRP_Timer_Timeout) begin
                    LRI_Timer_Value <= 0;
                    LRI_Timer_Counting <= 1;
                    LRI_Timer_Timeout <= 0;
                    state <= WAIT_LRI;
                end else if(VPulse_eI) begin
                    VRP_Timer_Value <= 0;
                    VRP_Timer_Counting <= 1;
                    VRP_Timer_Timeout <= 0;
                    state <= WAIT_VRP;
                end else begin
                    state <= WAIT_VRP;
                end
            end
            WAIT_LRI: begin
                VPace_eO <= 0;
                VRefractory_eO <= 0;
                if(LRI_Timer_Timeout) begin
                    VPace_eO <= 1;
                    state <= IDLE;
                end else if(VPulse_eI) begin
                    VRP_Timer_Value <= 0;
                    VRP_Timer_Counting <= 1;
                    VRP_Timer_Timeout <= 0;
                    state <= WAIT_VRP;
                end else begin
                    state <= WAIT_LRI;
                end
            end
        endcase
    end
end

always@(posedge clk_divd) begin
    if(VRP_Timer_Counting) begin
        VRP_Timer_Value <= VRP_Timer_Value + 1;
        if(VRP_Timer_Value >= VRP_Timeout_Value) begin
            VRP_Timer_Timeout <= 1;
            VRP_Timer_Counting <= 0;
        end
    end
end

always@(posedge clk_divd) begin
    if(LRI_Timer_Counting) begin
        LRI_Timer_Value <= LRI_Timer_Value + 1;
        if(LRI_Timer_Value >= LRI_Timeout_Value) begin
            LRI_Timer_Timeout <= 1;
            LRI_Timer_Counting <= 0;
        end
    end
end

assign VRP_Start_Timer = (state == WAIT_VRP) && (~VRP_Timer_Counting);
assign LRI_Timer_Start = (state == WAIT_LRI) && (~LRI_Timer_Counting);
assign LRI_Timer_Stop = (state == WAIT_LRI) && (LRI_Timer_Counting);

always@(posedge clk_divd) begin
    if(reset) begin
        VRP_Timeout_Value <= 0;
        LRI_Timeout_Value <= 0;
    end else begin
        case(state)
            IDLE: begin
                VRP_Timeout_Value <= 200; // 200 ms
                LRI_Timeout_Value <= 1000; // 1000 ms
            end
            WAIT_VRP: begin
                VRP_Timeout_Value <= 200; // 200 ms
                LRI_Timeout_Value <= 1000; // 1000 ms
            end
            WAIT_LRI: begin
                VRP_Timeout_Value <= 0;
                LRI_Timeout_Value <= 1000; // 1000 ms
            end
        endcase
    end
end

endmodule

module clock_gate(
