module top_module( 
    input wire clk,
    input wire reset,
    input wire [31:0] in,
    input wire select,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo,
    output wire [15:0] out_mux );

    // 16-to-1 MUX
    reg [7:0] mux_in_0;
    reg [7:0] mux_in_1;
    wire [3:0] mux_sel;
    wire [7:0] mux_out;

    mux_16to1 mux_inst (
        .in_0(mux_in_0),
        .in_1(mux_in_1),
        .sel(mux_sel),
        .out(mux_out)
    );

    // 1-to-16 DEMUX
    wire [3:0] demux_sel;
    wire [15:0] demux_out;

    demux_1to16 demux_inst (
        .in(in[7:0]),
        .sel(demux_sel),
        .out(demux_out)
    );

    // Control Logic
    reg mux_enable;
    reg demux_enable;

    always @ (posedge clk) begin
        if (reset) begin
            mux_enable <= 0;
            demux_enable <= 0;
        end else begin
            if (select) begin
                mux_enable <= 1;
                demux_enable <= 0;
            end else begin
                mux_enable <= 0;
                demux_enable <= 1;
            end
        end
    end

    // Output Assignment
    assign out_mux = mux_out;

    always @ (posedge clk) begin
        if (reset) begin
            out_hi <= 0;
            out_lo <= 0;
        end else begin
            if (mux_enable) begin
                mux_in_0 <= in[15:8];
                mux_in_1 <= in[23:16];
                out_hi <= mux_out;
            end else begin
                out_hi <= 0;
            end

            if (demux_enable) begin
                out_lo <= demux_out[demux_sel];
            end else begin
                out_lo <= 0;
            end
        end
    end

endmodule

module mux_16to1(
    input [7:0] in_0,
    input [7:0] in_1,
    input [3:0] sel,
    output reg [7:0] out
);

    always @ (sel) begin
        case(sel)
            4'b0000: out <= in_0;
            4'b0001: out <= in_1;
            // add cases for 14 more inputs
            default: out <= 0;
        endcase
    end

endmodule

module demux_1to16(
    input [7:0] in,
    input [3:0] sel,
    output [15:0] out
);

    assign out = {16{sel == 4'b0000}}; // initialize all bits to 0

    always @ (sel) begin
        case(sel)
            4'b0001: out[0] <= in;
            4'b0010: out[1] <= in;
            // add cases for 14 more outputs
            default: out <= 0;
        endcase
    end

endmodule

module edge_detector (
    input clk,
    input reset,
    input [7:0] in,
    output reg [7:0] out
);

reg [7:0] last_in;

always @(posedge clk) begin
    if (reset) begin
        out <= 8'b0;
        last_in <= 8'b0;
    end else begin
        last_in <= in;
        out <= (in ^ last_in) & in;
    end
end

endmodule

