module top_module (
    input [15:0] in,
    input [3:0] sel,
    input EN,
    input [3:0] A,
    input [3:0] B,
    input [2:0] op,
    output reg [3:0] out,
    output reg valid
);

reg [3:0] mux_out;
reg [3:0] alu_out;

// 16-to-1 multiplexer
always @(*) begin
    case(sel)
        4'd0: mux_out = in[3:0];
        4'd1: mux_out = in[7:4];
        4'd2: mux_out = in[11:8];
        4'd3: mux_out = in[15:12];
        default: mux_out = 4'b0;
    endcase
end

// 4-bit ALU
always @(*) begin
    case(op)
        3'b000: alu_out = A + B;
        3'b001: alu_out = A - B;
        3'b010: alu_out = A & B;
        3'b011: alu_out = A | B;
        3'b100: alu_out = A ^ B;
        default: alu_out = 4'b0;
    endcase
end

// Final output module
always @(*) begin
    if(valid) begin
        out = alu_out;
    end else if(EN) begin
        out = mux_out;
    end else begin
        out = 4'b0;
    end

    valid = (op != 3'b101);
end

endmodule

module data_memory_controller (
  input clk,
  input rst_n,
  input data_rd_en,
  input data_wr_en,
  input [19:0] data_addr,
  output reg [31:0] data_out,
  input [31:0] data_in,
  inout [31:0] dram_dq_in,
  inout [31:0] dram_dq_out,
  output [19:0] dram_addr,
  output [3:0] dram_dqm,
  output dram_we_n,
  output dram_cas_n,
  output dram_ras_n,
  output dram_cs_n,
  output [1:0] dram_ba,
  output dram_clk,
  output dram_cke
);

parameter DATA_WIDTH = 32;
parameter ADDR_WIDTH = 20;
parameter SDRAM_DATA_WIDTH = 32;
parameter SDRAM_ADDR_WIDTH = 20;
parameter SDRAM_DQM_WIDTH = 4;
parameter SDRAM_BA_WIDTH = 2;

reg [SDRAM_DATA_WIDTH-1:0] dram_dq;
reg [SDRAM_DATA_WIDTH-1:0] dram_dq_in;
reg [SDRAM_DATA_WIDTH-1:0] dram_dq_out;
reg [SDRAM_ADDR_WIDTH-1:0] dram_addr;
reg [SDRAM_DQM_WIDTH-1:0] dram_dqm;
reg dram_we_n;
reg dram_cas_n;
reg dram_ras_n;
reg dram_cs_n;
reg [SDRAM_BA_WIDTH-1:0] dram_ba;
reg dram_clk;
reg dram_cke;

reg [DATA_WIDTH-1:0] data_in_reg;

assign dram_dq = &dram_dqm ? {SDRAM_DATA_WIDTH{1'bZ}} : dram_dq_out;
assign dram_dq_in = dram_dq;

always @(posedge clk or negedge rst_n) begin
  if (~rst_n) begin
    data_out <= 0;
    dram_dq_in <= 0;
    dram_dq_out <= 0;
    dram_addr <= 0;
    dram_dqm <= 0;
    dram_we_n <= 1;
    dram_cas_n <= 1;
    dram_ras_n <= 1;
    dram_cs_n <= 1;
    dram_ba <= 0;
    dram_clk <= 0;
    dram_cke <= 0;
    data_in_reg <= 0;
  end else begin
    if (data_rd_en) begin
      data_out <= dram_dq[31:0];
    end else begin
      data_out <= 0;
    end
    if (data_wr_en) begin
      dram_addr <= data_addr;
      dram_dq_in <= data_in;
      dram_dqm <= 4'b1111;
      dram_we_n <= 0;
      dram_cas_n <= 0;
      dram_ras_n <= 0;
      dram_cs_n <= 0;
      dram_ba <= dram_addr[SDRAM_ADDR_WIDTH-1:SDRAM_ADDR_WIDTH-SDRAM_BA_WIDTH];
    end else begin
      dram_dq_in <= 0;
      dram_dqm <= 0;
      dram_we_n <= 1;
      dram_cas_n <= 1;
      dram_ras_n <= 1;
      dram_cs_n <= 1;
      dram_ba <= 0;
    end
    data_in_reg <= data_in;
  end
end

assign dram_addr = data_addr;
assign dram_dqm = 4'b1111;
assign dram_clk = clk;
assign dram_cke = 1'b1;

assign data_out = data_in_reg;

endmodule

module calculator(
    input [7:0] op1,
    input [7:0] op2,
    input [1:0] op_sel,
    output reg [7:0] sum,
    output reg [7:0] diff,
    output reg [7:0] product,
    output reg [7:0] quotient
);

always @(*) begin
    case(op_sel)
        2'b00: begin // addition
            sum = op1 + op2;
            diff = 8'h00;
            product = 8'h00;
            quotient = 8'h00;
        end
        2'b01: begin // subtraction
            sum = 8'h00;
            diff = op1 - op2;
            product = 8'h00;
            quotient = 8'h00;
        end
        2'b10: begin // multiplication
            sum = 8'h00;
            diff = 8'h00;
            product = op1 * op2;
            quotient = 8'h00;
        end
        2'b11: begin // division
            sum = 8'h00;
            diff = 8'h00;
            product = 8'h00;
            quotient = op1 / op2;
        end
    endcase
end

endmodule

