module convolution_module (
    input clk,
    input rst,
    input [63:0] in_data,
    input in_valid,
    input [8:0] kernel [0:8],
    input kernel_valid,
    output [63:0] out_data,
    output out_valid
);

reg [8:0] window [0:8];
reg [63:0] out;
reg out_ready;
reg [3:0] row, col;

// initialize all registers to 0
initial begin
    for (row = 0; row < 9; row = row + 1) begin
        for (col = 0; col < 9; col = col + 1) begin
            window[row][col] = 0;
        end
    end
    out = 0;
    out_ready = 0;
    row = 0;
    col = 0;
end

// read input data and kernel matrix
always @(posedge clk) begin
    if (rst) begin
        for (row = 0; row < 9; row = row + 1) begin
            for (col = 0; col < 9; col = col + 1) begin
                window[row][col] = 0;
            end
        end
        out = 0;
        out_ready = 0;
        row = 0;
        col = 0;
    end else if (in_valid) begin
        // shift window and add new data
        for (row = 0; row < 8; row = row + 1) begin
            for (col = 0; col < 8; col = col + 1) begin
                window[row][col] = window[row+1][col];
            end
            window[row][8] = 0;
        end
        for (col = 0; col < 8; col = col + 1) begin
            window[8][col] = window[7][col+1];
        end
        window[8][8] = in_data;
        // perform convolution
        if (kernel_valid) begin
            out = 0;
            for (row = 0; row < 3; row = row + 1) begin
                for (col = 0; col < 3; col = col + 1) begin
                    out = out + window[row][col]*kernel[row][col];
                end
            end
            out_ready = 1;
        end
    end else begin
        out_ready = 0;
    end
end

// output result
assign out_data = out;
assign out_valid = out_ready;

endmodule

