endmodule

module pulse_generator (
   input clk,
   input data_in,
   output reg pulse_out
);

   // Define the sequence to be detected
   parameter [7:0] SEQ = 8'b10110110;

   // Define the state machine states
   localparam IDLE = 2'b00;
   localparam FOUND_1 = 2'b01;
   localparam FOUND_2 = 2'b10;

   // Define the state machine variables
   reg [1:0] state;
   reg [7:0] data_reg;

   // Initial state
   initial begin
      state = IDLE;
      data_reg = 8'b0;
      pulse_out = 1'b0;
   end

   // State machine
   always @(posedge clk) begin
      case(state)
         IDLE: begin
            if(data_in == SEQ[0]) begin
               data_reg = {data_reg[6:0], data_in};
               state = FOUND_1;
            end else begin
               data_reg = {data_reg[6:0], 1'b0};
               state = IDLE;
            end
         end
         FOUND_1: begin
            if(data_reg == SEQ[1:7]) begin
               state = FOUND_2;
            end else if(data_in == SEQ[0]) begin
               data_reg = {data_reg[6:0], data_in};
               state = FOUND_1;
            end else begin
               data_reg = {data_reg[6:0], 1'b0};
               state = IDLE;
            end
         end
         FOUND_2: begin
            pulse_out = 1'b1;
            state = IDLE;
         end
         default: begin
            state = IDLE;
         end
      endcase
   end

endmodule

module ps2_mouse_nofifo (
    input clk,
    input reset,

    input  [7:0] writedata,   // data to send
    input        write,       // signal to send it
    input        inhibit,
    output [7:0] readdata,    // data read
    output       irq,         // signal data has arrived

    output command_was_sent,
    output error_sending_command,
    output buffer_overrun_error,

    inout ps2_clk,
    inout ps2_dat
  );

  // Internal state variables
  reg [2:0] state;
  reg [7:0] tx_data;
  reg [7:0] rx_data;
  reg       tx_busy;
  reg       rx_busy;
  reg       tx_parity;
  reg       rx_parity;
  reg       rx_error;

  // Unused outputs
  wire start_receiving_data;
  wire wait_for_incoming_data;

  // --------------------------------------------------------------------
  // Internal Modules
  // --------------------------------------------------------------------
  ps2_mouse mouse (
    .clk   (clk),
    .reset (reset),

    .the_command  (tx_data),
    .send_command (tx_busy),

    .received_data    (rx_data),
    .received_data_en (rx_busy),
    .inhibit          (inhibit),

    .command_was_sent              (command_was_sent),
    .error_communication_timed_out (error_sending_command),
    .start_receiving_data          (start_receiving_data),
    .wait_for_incoming_data        (wait_for_incoming_data),

    .ps2_clk (ps2_clk),
    .ps2_dat (ps2_dat)
  );

  // --------------------------------------------------------------------
  // Transmit state machine
  // --------------------------------------------------------------------
  always @(posedge clk, posedge reset) begin
    if (reset) begin
      state      <= 3'b000;
      tx_data    <= 8'h00;
      tx_busy    <= 1'b0;
      tx_parity  <= 1'b0;
    end else begin
      case (state)
        3'b000: begin // Idle
          if (write) begin
            tx_data   <= writedata;
            tx_parity <= ~^tx_data;
            tx_busy   <= 1'b1;
            state     <= 3'b001;
          end
        end
        3'b001: begin // Send Start Bit
          ps2_dat   <= 1'b0;
          state     <= 3'b010;
        end
        3'b010: begin // Send Data Bits
          ps2_dat   <= tx_data[0];
          tx_data   <= {tx_parity, tx_data[7:1]};
          tx_parity <= ~^tx_data;
          if (tx_busy) begin
            state   <= 3'b011;
          end else begin
            state   <= 3'b100;
          end
        end
        3'b011: begin // Wait for Acknowledge
          ps2_dat <= 1'bz;
          if (~ps2_clk && ps2_dat) begin
            tx_busy <= 1'b0;
            state   <= 3'b100;
          end
        end
        3'b100: begin // Send Stop Bit
          ps2_dat <= 1'b1;
          state   <= 3'b000;
        end
      endcase
    end
  end

  // --------------------------------------------------------------------
  // Receive state machine
  // --------------------------------------------------------------------
  always @(posedge clk, posedge reset) begin
    if (reset) begin
      state     <= 3'b000;
      rx_data   <= 8'h00;
      rx_busy   <= 1'b0;
      rx_parity <= 1'b0;
      rx_error  <= 1'b0;
    end else begin
      case (state)
        3'b000: begin // Idle
          if (~inhibit && irq) begin
            state   <= 3'b001;
          end
        end
        3'b001: begin // Wait for Start Bit
          if (~ps2_clk && ~ps2_dat) begin
            rx_data  <= 8'h00;
            rx_parity <= 1'b0;
            rx_busy  <= 1'b1;
            rx_error <= 1'b0;
            state    <= 3'b010;
          end
        end
        3'b010: begin // Receive Data Bits
          rx_data   <= {rx_data[6:0], ps2_dat};
          rx_parity <= rx_parity ^ ps2_dat;
          if (rx_busy) begin
            state   <= 3'b011;
          end else begin
            state   <= 3'b100;
          end
        end
        3'b011: begin // Wait for Stop Bit
          if (~ps2_clk && ps2_dat) begin
            rx_busy <= 1'b0;
            if (rx_parity || rx_error) begin
              buffer_overrun_error <= 1'b0;
            end else begin
              readdata <= rx_data;
              irq      <= 1'b1;
            end
            state   <= 3'b100;
          end
        end
        3'b100: begin // Idle
          state <= 3'b000;
        end
      endcase
    end
  end

  // --------------------------------------------------------------------
  // Continous assignments
  // --------------------------------------------------------------------
  assign buffer_overrun_error = rx_error;

endmodule

module booth_multiplier_16bit (
    input signed [15:0] A,
    input signed [15:0] B,
    output reg signed [31:0] product
);

reg signed [31:0] accumulator;
reg signed [15:0] multiplicand;
reg signed [15:0] multiplier;
reg [4:0] counter;

always @(*) begin
    multiplicand = A;
    multiplier = B;
    accumulator = 0;
    counter = 16;

    while (counter > 0) begin
        if (multiplier[0] == 1 && counter != 1) begin
            accumulator = accumulator + (multiplicand << (counter - 1));
        end else if (multiplier[0] == 0 && counter != 1) begin
            accumulator = accumulator - (multiplicand << (counter - 1));
        end

        multiplier = multiplier >> 1;
        counter = counter - 1;
    end

    product = accumulator;
end

endmodule

module LFSR (
  input clk,
  input rst,
  output reg rand
);

parameter n = 8; // number of bits in the LFSR register

reg [n-1:0] lfsr_reg;
reg [n-1:0] tap_seq;
reg [n-1:0] seed;

// Define the tap sequence and seed value here
initial begin
  tap_seq = {1'b1, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b1, 1'b1}; // tap sequence for an 8-bit LFSR
  seed = {1'b1, 1'b0, 1'b1, 1'b0, 1'b1, 1'b0, 1'b1, 1'b0}; // seed value for the LFSR
  lfsr_reg = seed;
end

always @(posedge clk) begin
  if (rst) begin
    lfsr_reg <= seed;
  end else begin
    lfsr_reg <= {lfsr_reg[n-2:0], lfsr_reg[0] ^ lfsr_reg[tap_seq]};
  end
end

assign rand = lfsr_reg[0];

endmodule

