  output reg [3:0] trap
);

  // Registers
  reg [63:0] r0;
  reg [63:0] r1;
  reg [63:0] r2;
  reg [63:0] r3;
  reg [63:0] r4;
  reg [63:0] r5;
  reg [63:0] r6;
  reg [63:0] r7;
  reg [63:0] r8;
  reg [63:0] r9;
