  reg [63:0] pc;

  // Flags
  reg z_flag;
  reg n_flag;
  reg c_flag;

  // Control signals
  reg [3:0] opcode;
  reg [3:0] funct3;
  reg [6:0] funct7;
  reg [4:0] rs1;
  reg [4:0] rs2;
  reg [4:0] rd;
  reg [11:0] imm12;
  reg [19:0] imm20;
  reg [11:0] imm12_i;
  reg [11:0] imm12_s;
  reg [11:0] imm12_b;
  reg [19:0] imm20_u;
  reg [19:0] imm21_j;
  reg [63:0] alu_result;
  reg [63:0] branch_target;
  reg [63:0] jump_target;
  reg [63:0] mem_addr_a;
  reg [63:0] mem_addr_b;
  reg [63:0] mem_addr_w;
  reg [7:0] mem_data_r;
  reg [7:0] mem_data_w;
  reg mem_read;
  reg mem_write;
  reg [1:0] mem_size;
  reg [1:0] mem_signed;
  reg [2:0] alu_op;
  reg [1:0] alu_signed;
  reg [5:0] csr_num;
  reg [2:0] csr_op;
  reg [63:0] csr_value;
  reg csr_write;
  reg [63:0] trap_cause;
  reg [3:0] trap_code;
  reg [1:0] trap_interrupt;
  reg [1:0] trap_exception;
  reg [3:0] trap_privilege;
  reg [1:0] trap_mcause;

  // Constants
  localparam BR_IF_OPCODE = 8'b1100011;

  // Execute instruction
  always @(posedge clk) begin
    if (reset) begin
      // Reset registers
      r0 <= 0;
      r1 <= 0;
      r2 <= 0;
      r3 <= 0;
      r4 <= 0;
      r5 <= 0;
      r6 <= 0;
      r7 <= 0;
      r8 <= 0;
      r9 <= 0;
      r10 <= 0;
      r11 <= 0;
      r12 <= 0;
      r13 <= 0;
      r14 <= 0;
      r15 <= 0;
      pc <= 0;

      // Reset flags
      z_flag <= 0;
      n_flag <= 0;
      c_flag <= 0;

      // Reset control signals
      opcode <= 0;
      funct3 <= 0;
      funct7 <= 0;
      rs1 <= 0;
      rs2 <= 0;
      rd <= 0;
      imm12 <= 0;
      imm20 <= 0;
      imm12_i <= 0;
      imm12_s <= 0;
      imm12_b <= 0;
      imm20_u <= 0;
      imm21_j <= 0;
      alu_result <= 0;
      branch_target <= 0;
      jump_target <= 0;
      mem_addr_a <= 0;
      mem_addr_b <= 0;
      mem_addr_w <= 0;
      mem_data_r <= 0;
      mem_data_w <= 0;
      mem_read <= 0;
      mem_write <= 0;
      mem_size <= 0;
      mem_signed <= 0;
      alu_op <= 0;
      alu_signed <= 0;
      csr_num <= 0;
      csr_op <= 0;
      csr_value <= 0;
      csr_write <= 0;
      trap_cause <= 0;
      trap_code <= 0;
      trap_interrupt <= 0;
      trap_exception <= 0;
      trap_privilege <= 0;
      trap_mcause <= 0;

      // Reset outputs
      result <= 0;
      result_empty <= 1;
      trap <= 0;
    end else begin
      // Fetch instruction
      mem_addr_a <= pc;
      mem_size <= 2'b10;
      mem_signed <= 2'b00;
      mem_read <= 1;

      // Decode instruction
      opcode <= mem_data_r[6:2];
      funct3 <= mem_data_r[14:12];
      funct7 <= mem_data_r[31:25];
      rs1 <= mem_data_r[19:15];
      rs2 <= mem_data_r[24:20];
      rd <= mem_data_r[11:7];
      imm12 <= mem_data_r[31:20];
      imm20 <= {{11{mem_data_r[31]}}, mem_data_r[31:20]};
      imm12_i <= mem_data_r[31:20];
      imm12_s <= {{5{mem_data_r[31]}}, mem_data_r[31:25], mem_data_r[11:7]};
      imm12_b <= {{6{mem_data_r[31]}}, mem_data_r[31], mem_data_r[7], mem_data_r[30:25], mem_data_r[11:8]};
      imm20_u <= {{12{mem_data_r[31]}}, mem_data_r[31:20]};
      imm21_j <= {{10{mem_data_r[31]}}, mem_data_r[31], mem_data_r[19:12], mem_data_r[20], mem_data_r[30:21]};

      // Execute instruction
      case (opcode)
        BR_IF_OPCODE: begin
          // Branch if condition is true
          if (mem_data_r[rs1] && !z_flag) begin
            pc <= pc + imm12_b;
          end else begin
            pc <= pc + 4;
          end
        end
        default: begin
          // Unsupported instruction
          trap_cause <= 0;
          trap_code <= 0;
          trap_interrupt <= 0;
          trap_exception <= 1;
          trap_privilege <= 3;
          trap_mcause <= 0;
          trap <= 1;
        end
      endcase

      // Write result
      result <= alu_result;
      result_empty <= 0;
    end
  end

endmodule

module ripple_addsub (
    input [3:0] a,
    input [3:0] b,
    input add_sub,
    output reg [3:0] result,
    output overflow
);

    reg [4:0] temp;

    always @(*) begin
        if(add_sub == 1'b1) begin
            temp = {1'b0, a} + {1'b0, b};
            result = temp[3:0];
            if(temp[4] == 1'b1 || result > 7) begin
                overflow = 1'b1;
            end else begin
                overflow = 1'b0;
            end
        end else begin
            temp = {1'b0, a} - {1'b0, b};
            result = temp[3:0];
            if(temp[4] == 1'b1 || result < -8) begin
                overflow = 1'b1;
            end else begin
                overflow = 1'b0;
            end
        end
    end

endmodule

module transmission(
    input enable,
    input clk_in,
    input reset,
    input wire [7:0] din,
    output busy,
    output reg done,
    output reg tx
);

parameter count = 8;

reg [8:0] data = 8'b11111111;
reg [3:0] bitpos = 0;
reg [1:0] state = 2'b00;
reg [31:0] counter = 0;

initial begin
    tx <= 1'b1;
    done = 1'b0;
end

parameter STATE_IDLE = 2'b00;
parameter STATE_START = 2'b01;
parameter STATE_DATA = 2'b10;
parameter STATE_STOP = 2'b11;

always @(posedge clk_in) begin
    if (reset) begin
        tx <= 1'b1;
        state <= STATE_IDLE;
        done <= 1'b0;
        counter <= 0;
        bitpos <= 0;
    end
    else begin
        case (state)
            STATE_IDLE: begin
                done <= 1'b0;
                tx <= 1'b1;
                if (enable) begin
                    state <= STATE_START;
                    data <= {1'h01, din};
                    bitpos <= 0;
                end
            end
            STATE_START: begin
                tx <= 1'b0;
                state <= STATE_DATA;
            end
            STATE_DATA: begin
                if (bitpos <= count) begin
                    counter <= counter + 1;
                    if (counter == 5208) begin
                        tx <= data[bitpos];
                        bitpos <= bitpos + 1;
                        counter <= 0;
                        if (bitpos == count) begin
                            state <= STATE_STOP;
                        end
                    end
                end
            end
            STATE_STOP: begin
                tx <= 1'b1;
                done <= 1'b1;
                state <= STATE_IDLE;
            end
            default: begin
                tx <= 1'b1;
                state <= STATE_IDLE;
            end
        endcase
    end
end

assign busy = (state != STATE_IDLE);

endmodule

module juniversalShiftRegister(
