    input A,
    input B,
    input C,
    input D,
    output [15:0] Y
);

wire [3:0] nA, nB, nC, nD;
wire [15:0] stage1, stage2;

assign nA = ~A;
assign nB = ~B;
assign nC = ~C;
assign nD = ~D;

// Stage 1
// First row of NAND gates
assign stage1[0] = nA & nB & nC & nD;
assign stage1[1] = nA & nB & nC & D;
assign stage1[2] = nA & nB & C & nD;
assign stage1[3] = nA & nB & C & D;
assign stage1[4] = nA & B & nC & nD;
assign stage1[5] = nA & B & nC & D;
assign stage1[6] = nA & B & C & nD;
assign stage1[7] = nA & B & C & D;

// Stage 2
// Second row of NAND gates
assign stage2[0] = stage1[0] & stage1[1] & stage1[2] & stage1[3];
assign stage2[1] = stage1[0] & stage1[1] & stage1[4] & stage1[5];
assign stage2[2] = stage1[0] & stage1[2] & stage1[4] & stage1[6];
assign stage2[3] = stage1[1] & stage1[3] & stage1[5] & stage1[7];
assign stage2[4] = stage1[2] & stage1[3] & stage1[6] & stage1[7];
assign stage2[5] = stage1[4] & stage1[5] & stage1[6] & stage1[7];

// Output
assign Y = stage2;

endmodule

module mux_4to1 (
    input [3:0] in,
    input [1:0] sel,
    output reg out,
    input VPWR,
    input VGND,
    input VPB,
    input VNB
);

    wire [1:0] and_out;
    wire or_out;

    // Implementing the AND2 gates
    sky130_fd_sc_hd__and2 and2_0 (
        .A(in[0]),
        .B(~sel[1]),
        .X(and_out[0]),
        .VPWR(VPWR),
        .VGND(VGND),
        .VPB(VPB),
        .VNB(VNB)
    );

    sky130_fd_sc_hd__and2 and2_1 (
        .A(in[1]),
        .B(~sel[1]),
        .X(and_out[1]),
        .VPWR(VPWR),
        .VGND(VGND),
        .VPB(VPB),
        .VNB(VNB)
    );

    sky130_fd_sc_hd__and2 and2_2 (
        .A(in[2]),
        .B(sel[1]),
        .X(and_out[0]),
        .VPWR(VPWR),
        .VGND(VGND),
        .VPB(VPB),
        .VNB(VNB)
    );

    sky130_fd_sc_hd__and2 and2_3 (
        .A(in[3]),
        .B(sel[1]),
        .X(and_out[1]),
        .VPWR(VPWR),
        .VGND(VGND),
        .VPB(VPB),
        .VNB(VNB)
    );

    // Implementing the OR2 gate
    sky130_fd_sc_hd__or2 or2 (
        .A(and_out[0]),
        .B(and_out[1]),
        .X(or_out),
        .VPWR(VPWR),
        .VGND(VGND),
        .VPB(VPB),
        .VNB(VNB)
    );

    // Assigning the output
    always @(*) begin
        case (sel)
            2'b00: out = in[0];
            2'b01: out = in[1];
            2'b10: out = in[2];
            2'b11: out = in[3];
        endcase
    end

endmodule

module top_module (
    input [31:0] a,
    input [31:0] b,
    input [3:0] ctrl,
    output [31:0] result,
    output carry_out,
    output zero,
    output gt,
    output lt,
    output eq
);

    wire [3:0] cmp_out;
    wire [31:0] alu_out;
    wire alu_carry_out, alu_zero;

    // instantiate the magnitude comparator module
    comparator_4bit cmp (
        .a(a[31:28]),
        .b(b[31:28]),
        .gt(cmp_out[3]),
        .lt(cmp_out[2]),
        .eq(cmp_out[1])
    );

    // instantiate the ALU module
    alu_32bit alu (
        .a(a),
        .b(b),
        .ctrl(ctrl),
        .result(alu_out),
        .carry_out(alu_carry_out),
        .zero(alu_zero)
    );

    // output the result of the selected ALU operation
    assign result = (ctrl == 4'b0000) ? alu_out : // addition
                    (ctrl == 4'b0001) ? alu_out : // subtraction
                    (ctrl == 4'b0010) ? alu_out : // bitwise AND
                    (ctrl == 4'b0011) ? alu_out : // bitwise OR
                    (ctrl == 4'b0100) ? alu_out : // bitwise XOR
                    (ctrl == 4'b0101) ? {alu_out[30:0], 1'b0} : // shift left
                    (ctrl == 4'b0110) ? {1'b0, alu_out[31:1]} : // shift right
                    32'd0; // default to 0

    // output the carry-out for addition
    assign carry_out = (ctrl == 4'b0000) ? alu_carry_out : 1'b0;

    // output the zero flag for comparison operations
    assign zero = (ctrl == 4'b0001) ? alu_zero : cmp_out[1];

    // output the gt, lt, and eq flags from the magnitude comparator
    assign gt = cmp_out[3];
    assign lt = cmp_out[2];
    assign eq = cmp_out[1];

endmodule

