module ripple_carry_adder (
  input [3:0] A,
  input [3:0] B,
  output [3:0] S,
  output carry_out
);

wire [3:0] sum;
wire carry;

assign sum = A + B;
assign carry = (A[3] & B[3]) | (A[2] & B[2]) | (A[1] & B[1]) | (A[0] & B[0]);

assign S = sum;
assign carry_out = carry;

endmodule

module counter (
  input clk,
  input reset,
  input [3:0] A, 
  output [3:0] final_output
);

reg [3:0] counter_value;
wire [3:0] adder_output;
wire carry_out;

dual_edge_triggered_flip_flop dual_edge_triggered_flip_flop_inst (
  .clk(clk),
  .binary_input(counter_value),
  .output_port(counter_value)
);

ripple_carry_adder ripple_carry_adder_inst (
  .A(counter_value),
  .B(4'b0001),
  .S(adder_output),
  .carry_out(carry_out)
);

always @(posedge clk) begin
  if (reset) begin
    counter_value <= 4'b0000;
  end else if (A != 4'b0000) begin
    counter_value <= A;
  end else begin
    counter_value <= adder_output;
  end
end

assign final_output = counter_value;

endmodule

module UniversalCounter8bits (
    input CLOCK, Reset, S1, S0,
    input [7:0] P, BeginCount, EndCount,
    output reg [7:0] Q,
    output reg TerminalCount
);

always @ (posedge CLOCK or posedge Reset) begin
    if (Reset) begin
        Q <= BeginCount;
        TerminalCount <= 0;
    end
    else begin
        case ({S1, S0})
            2'b00: begin // Hold mode
                Q <= Q;
                TerminalCount <= 0;
            end
            2'b01: begin // Count up mode
                if (Q == EndCount) begin
                    Q <= BeginCount;
                    TerminalCount <= 1;
                end
                else begin
                    Q <= Q + 1;
                    TerminalCount <= 0;
                end
            end
            2'b10: begin // Count down mode
                if (Q == BeginCount) begin
                    Q <= EndCount;
                    TerminalCount <= 1;
                end
                else begin
                    Q <= Q - 1;
                    TerminalCount <= 0;
                end
            end
            2'b11: begin // Parallel load mode
                Q <= P;
                TerminalCount <= 0;
            end
        endcase
    end
end

endmodule

