module four_bit_adder(
    input [3:0] a,
    input [3:0] b,
    input cin,
    output [3:0] sum,
    output cout
);

    wire c1, c2, c3;
    wire [3:0] s1, s2, s3;

    // First stage
    full_adder fa1(a[0], b[0], cin, s1[0], c1);
    full_adder fa2(a[1], b[1], c1, s1[1], c2);
    full_adder fa3(a[2], b[2], c2, s1[2], c3);
    full_adder fa4(a[3], b[3], c3, s1[3], cout);

    // Second stage
    full_adder fa5(a[0], b[0], cin, s2[0], c1);
    full_adder fa6(a[1], b[1], c1, s2[1], c2);
    full_adder fa7(a[2], b[2], c2, s2[2], c3);
    full_adder fa8(a[3], b[3], c3, s2[3], cout);

    // Third stage
    full_adder fa9(s1[0], s2[0], cout, s3[0], c1);
    full_adder fa10(s1[1], s2[1], c1, s3[1], c2);
    full_adder fa11(s1[2], s2[2], c2, s3[2], c3);
    full_adder fa12(s1[3], s2[3], c3, s3[3], cout);

    assign sum = s3;

endmodule

