module uartReceiver(
    input clk,
    input reset,
    input rx,
    input baud_rate,
    output reg [7:0] data,
    output reg data_valid
);

// Internal signals
reg [3:0] count;
reg [3:0] bit_count;
reg [7:0] shift_reg;
reg rx_reg;
reg start_bit_detected;
reg stop_bit_detected;
reg baud_tick;

// Baud rate generator
reg [31:0] baud_count;
always @(posedge clk) begin
    if (reset) begin
        baud_count <= 0;
        baud_tick <= 0;
    end else begin
        baud_count <= baud_count + 1;
        if (baud_count == (50000000 / baud_rate) - 1) begin
            baud_count <= 0;
            baud_tick <= 1;
        end else begin
            baud_tick <= 0;
        end
    end
end

// Receiver state machine
parameter IDLE = 2'b00;
parameter START_BIT = 2'b01;
parameter DATA_BITS = 2'b10;
parameter STOP_BIT = 2'b11;
reg [1:0] state;
always @(posedge clk) begin
    if (reset) begin
        state <= IDLE;
        count <= 0;
        bit_count <= 0;
        shift_reg <= 0;
        rx_reg <= 1;
        start_bit_detected <= 0;
        stop_bit_detected <= 0;
        data_valid <= 0;
    end else begin
        case (state)
            IDLE: begin
                if (rx_reg == 0 && baud_tick) begin
                    state <= START_BIT;
                    count <= 0;
                    bit_count <= 0;
                    shift_reg <= 0;
                    start_bit_detected <= 1;
                end else begin
                    state <= IDLE;
                end
            end
            START_BIT: begin
                if (count == 4) begin
                    if (rx_reg == 1) begin
                        state <= DATA_BITS;
                        count <= 0;
                    end else begin
                        state <= IDLE;
                        start_bit_detected <= 0;
                    end
                end else begin
                    count <= count + 1;
                end
            end
            DATA_BITS: begin
                if (count == 8) begin
                    state <= STOP_BIT;
                    count <= 0;
                end else begin
                    if (baud_tick) begin
                        shift_reg <= {shift_reg[6:0], rx_reg};
                        count <= count + 1;
                    end
                end
            end
            STOP_BIT: begin
                if (count == 4) begin
                    if (rx_reg == 1) begin
                        state <= IDLE;
                        stop_bit_detected <= 1;
                        data <= shift_reg;
                        data_valid <= 1;
                    end else begin
                        state <= IDLE;
                        start_bit_detected <= 0;
                    end
                end else begin
                    count <= count + 1;
                end
            end
            default: begin
                state <= IDLE;
            end
        endcase
    end
end

// Input sampling
always @(posedge clk) begin
    if (reset) begin
        rx_reg <= 1;
    end else begin
        if (baud_tick) begin
            rx_reg <= rx;
        end
    end
end

endmodule

module gatedcap (
   inout ld,
   input clk,
   input rst,
   output reg vcap
);

   reg [31:0] count;
   reg [31:0] discharge_count;
   reg [31:0] charge_count;
   reg charging;
   reg discharging;

   assign ld = charging | discharging;

   always @(posedge clk) begin
      if (rst) begin
         vcap <= 0;
         count <= 0;
         discharge_count <= 0;
         charge_count <= 0;
         charging <= 0;
         discharging <= 0;
      end else begin
         if (charging) begin
            if (count == 31'd499999) begin
               count <= 0;
               charging <= 0;
               discharging <= 1;
            end else begin
               count <= count + 1;
            end
         end else if (discharging) begin
            if (vcap == 0) begin
               vcap <= 0;
               count <= 0;
               discharge_count <= 0;
               charge_count <= 0;
               charging <= 0;
               discharging <= 0;
            end else if (discharge_count == 31'd49999) begin
               discharge_count <= 0;
               vcap <= vcap - 1;
            end else begin
               discharge_count <= discharge_count + 1;
            end
         end else if (ld) begin
            vcap <= 0;
            count <= 0;
            discharge_count <= 0;
            charge_count <= 0;
            charging <= 1;
            discharging <= 0;
         end
      end
   end

endmodule

module top_module (
    input clk,          // Clock signal for dual-edge triggered flip-flop
    input reset,        // Asynchronous active-high reset for counter
    input d,            // Input for dual-edge triggered flip-flop
    output q,           // Output for dual-edge triggered flip-flop
    output [3:0] count, // Output for counter
    output [3:0] final  // Output for bitwise OR operation
);

  reg [3:0] count_reg;   // Register for counter
  wire [3:0] count_next; // Next count value
  reg q_reg;             // Register for dual-edge triggered flip-flop output
  wire q_next;           // Next dual-edge triggered flip-flop output
  wire [3:0] or_result;  // Result of bitwise OR operation

  // Counter module
  counter_module counter (
    .clk(clk),
    .reset(reset),
    .count_reg(count_reg),
    .count_next(count_next)
  );

  // Dual-edge triggered flip-flop module
  dual_edge_triggered_flip_flop_module flip_flop (
    .clk(clk),
    .d(d),
    .q_reg(q_reg),
    .q_next(q_next)
  );

  // Bitwise OR module
  bitwise_or_module bitwise_or (
    .input1(count_next),
    .input2(q_next),
    .result(or_result)
  );

  // Assign outputs
  assign count = count_reg;
  assign q = q_reg;
  assign final = or_result;

  // Update registers
  always @(posedge clk) begin
    count_reg <= count_next;
    q_reg <= q_next;
  end

endmodule

// Counter module
module counter_module (
    input clk,
    input reset,
    input [3:0] count_reg,
    output [3:0] count_next
);

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      count_next <= 4'b0000;
    end else begin
      if (count_reg == 4'b1111) begin
        count_next <= 4'b0000;
      end else begin
        count_next <= count_reg + 1;
      end
    end
  end

endmodule

