module dct_sum (
  input   [ 29: 0] dct_buffer,
  input   [  3: 0] dct_count,
  input            test_ending,
  input            test_has_ended
);

  reg [ 29: 0] internal_dct_buffer;
  reg [  3: 0] internal_dct_count;
  reg          reset_buffer;
  reg          reset_count;
  reg          output_sum;
  reg [ 29: 0] sum;

  always @(*) begin
    if (test_ending) begin
      reset_buffer <= 1;
      reset_count <= 1;
      output_sum <= 0;
    end else if (test_has_ended) begin
      output_sum <= 1;
    end else begin
      reset_buffer <= 0;
      reset_count <= 0;
      output_sum <= 0;
    end
  end

  always @(posedge clk) begin
    if (reset_buffer) begin
      internal_dct_buffer <= 0;
    end else if (dct_count != 0) begin
      internal_dct_buffer <= internal_dct_buffer + dct_buffer;
    end

    if (reset_count) begin
      internal_dct_count <= 0;
    end else if (dct_count != 0) begin
      internal_dct_count <= internal_dct_count + dct_count;
    end

    if (output_sum) begin
      sum <= internal_dct_buffer[internal_dct_count-1:0];
    end
  end

endmodule

module FSM (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 4; // number of input signals
parameter m = 2; // number of output signals
parameter s = 8; // number of states in original FSM

reg [2:0] state; // current state
reg [2:0] next_state; // next state

// define the states
parameter S0 = 3'b000;
parameter S1 = 3'b001;
parameter S2 = 3'b010;
parameter S3 = 3'b011;
parameter S4 = 3'b100;
parameter S5 = 3'b101;
parameter S6 = 3'b110;
parameter S7 = 3'b111;

// define the outputs
parameter O0 = 2'b00;
parameter O1 = 2'b01;
parameter O2 = 2'b10;
parameter O3 = 2'b11;

// define the transition conditions
always @ (in) begin
  case (state)
    S0: if (in[0] == 1) next_state = S1; else next_state = S0;
    S1: if (in[1] == 1) next_state = S2; else next_state = S1;
    S2: if (in[2] == 1) next_state = S3; else next_state = S2;
    S3: if (in[3] == 1) next_state = S4; else next_state = S3;
    S4: if (in[0] == 1) next_state = S5; else next_state = S4;
    S5: if (in[1] == 1) next_state = S6; else next_state = S5;
    S6: if (in[2] == 1) next_state = S7; else next_state = S6;
    S7: if (in[3] == 1) next_state = S0; else next_state = S7;
  endcase
end

// define the outputs based on the current state
always @ (state) begin
  case (state)
    S0: out = O0;
    S1: out = O1;
    S2: out = O2;
    S3: out = O3;
    S4: out = O0;
    S5: out = O1;
    S6: out = O2;
    S7: out = O3;
  endcase
end

// update the state
always @ (posedge clk) begin
  state <= next_state;
end

endmodule

module histStretch
#(
    parameter ID = 1,
    parameter NUM_STAGE = 4
)
(
    input wire clk,
    input wire reset,
    input wire ce,
    input wire [31:0] din,
    output wire [31:0] dout
);

reg [31:0] din_buf1;
reg [31:0] din_buf2;
reg [31:0] din_buf3;
reg [31:0] din_buf4;

wire [31:0] din_shifted = din << 16;
wire [31:0] din_scaled = din_shifted * 65535;

wire [31:0] din_buf1_shifted = din_buf1 << 16;
wire [31:0] din_buf1_scaled = din_buf1_shifted * 65535;

wire [31:0] din_buf2_shifted = din_buf2 << 16;
wire [31:0] din_buf2_scaled = din_buf2_shifted * 65535;

wire [31:0] din_buf3_shifted = din_buf3 << 16;
wire [31:0] din_buf3_scaled = din_buf3_shifted * 65535;

wire [31:0] din_buf4_shifted = din_buf4 << 16;
wire [31:0] din_buf4_scaled = din_buf4_shifted * 65535;

wire [31:0] din_scaled_sum = din_scaled + din_buf1_scaled + din_buf2_scaled + din_buf3_scaled + din_buf4_scaled;

wire [31:0] dout_shifted = din_scaled_sum >> 16;
wire [31:0] dout_scaled = dout_shifted * 65535;
wire [31:0] dout_shifted2 = dout_scaled >> 16;

assign dout = dout_shifted2;

always @(posedge clk) begin
    if (reset) begin
        din_buf1 <= 0;
        din_buf2 <= 0;
        din_buf3 <= 0;
        din_buf4 <= 0;
    end else if (ce) begin
        din_buf1 <= din;
        din_buf2 <= din_buf1;
        din_buf3 <= din_buf2;
        din_buf4 <= din_buf3;
    end
end

endmodule

module four_bit_adder(
  input [3:0] A, B,
  input cin,
  output [3:0] sum,
  output cout
);

  wire [3:0] carry;
  wire [3:0] s;

  full_adder fa0(A[0], B[0], cin, s[0], carry[0]);
  full_adder fa1(A[1], B[1], carry[0], s[1], carry[1]);
  full_adder fa2(A[2], B[2], carry[1], s[2], carry[2]);
  full_adder fa3(A[3], B[3], carry[2], s[3], cout);

  assign sum = s;

endmodule

module full_adder(
  input a, b, cin,
  output s, cout
);

  wire c1, c2;

  xor(s, a, b);
  and(c1, a, b);
  and(c2, s, cin);
  or(cout, c1, c2);

endmodule

