module pc_next (
    input clk,
    input reset,
    input [31:2] pc_new,
    input take_branch,
    input pause_in,
    input [25:0] opcode25_0,
    input [1:0] pc_source,
    output reg [31:0] pc_out,
    output reg [31:0] pc_out_plus4
);

    // Define constants
    parameter PC_RESET = 32'h0000_0000;
    parameter FROM_INC4 = 2'b00;
    parameter FROM_OPCODE25_0 = 2'b01;
    parameter FROM_BRANCH = 2'b10;
    parameter FROM_LBRANCH = 2'b11;

    // Define signals
    reg [31:2] pc_next;
    reg [31:2] pc_reg;
    wire [31:2] pc_inc = pc_reg + 1;

    // Assign outputs
    assign pc_out = {pc_reg, 2'b00};
    assign pc_out_plus4 = {pc_inc, 2'b00};

    // Define always block for register
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            pc_reg <= PC_RESET;
        end else begin
            pc_reg <= pc_next;
        end
    end

    // Define always block for next PC value
    always @(*) begin
        case (pc_source)
            FROM_INC4: begin
                pc_next = pc_inc;
            end
            FROM_OPCODE25_0: begin
                pc_next = {pc_reg[31:28], opcode25_0};
            end
            FROM_BRANCH, FROM_LBRANCH: begin
                if (take_branch) begin
                    pc_next = pc_new;
                end else begin
                    pc_next = pc_inc;
                end
            end
            default: begin
                pc_next = pc_inc;
            end
        endcase

        if (pause_in) begin
            pc_next = pc_reg;
        end
    end
endmodule

module top_module(
    input               clk         ,
    input               reset       ,
    input       [99:0]  data_in     ,
    input               load        ,
    input       [1:0]   ena         ,
    input       [7:0]   data_in_acc ,
    input               valid_a     ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out    );

    // Internal signals
    wire [99:0] shifted_data;
    wire [7:0] acc_out;
    wire [99:0] xor_out;
    wire [99:0] shifted_data_xored;
    wire [99:0] data_out_wire;
    wire shift_dir;

    // Instantiate modules
    barrel_shifter barrel_shifter_inst(
        .data_in(data_in),
        .shifted_data(shifted_data),
        .shift_dir(shift_dir),
        .ena(ena)
    );

    accumulator accumulator_inst(
        .clk(clk),
        .reset(reset),
        .load(load),
        .data_in(data_in_acc),
        .data_out(acc_out)
    );

    xor_module xor_module_inst(
        .data_in_1(shifted_data),
        .data_in_2(acc_out),
        .data_out(xor_out)
    );

    barrel_shifter barrel_shifter_inst_2(
        .data_in(xor_out),
        .shifted_data(shifted_data_xored),
        .shift_dir(shift_dir),
        .ena(ena)
    );

    // Valid-Ready handshake
    reg [1:0] state = 2'b00;
    reg valid_a_reg;
    reg ready_a_reg;
    assign ready_a = ready_a_reg;
    assign data_out = data_out_wire;

    always @(posedge clk) begin
        if (reset) begin
            state <= 2'b00;
            valid_b <= 0;
            ready_a_reg <= 0;
            data_out_wire <= 0;
        end else begin
            case (state)
                2'b00: begin // Idle state
                    valid_b <= 0;
                    ready_a_reg <= 0;
                    data_out_wire <= 0;
                    if (valid_a) begin
                        valid_a_reg <= 1;
                        state <= 2'b01;
                    end
                end
                2'b01: begin // Data processing state
                    valid_a_reg <= 0;
                    ready_a_reg <= 1;
                    if (ready_b) begin
                        state <= 2'b10;
                    end
                end
                2'b10: begin // Output data state
                    valid_b <= 1;
                    ready_a_reg <= 0;
                    data_out_wire <= shifted_data_xored;
                    state <= 2'b00;
                end
            endcase
        end
    end

endmodule

module barrel_shifter(
    input       [99:0]  data_in     ,
    output reg  [99:0]  shifted_data,
    output reg          shift_dir   ,
    input       [1:0]   ena
);

    always @(*) begin
        case (ena)
            2'b00: begin // No shift
                shifted_data <= data_in;
                shift_dir <= 0;
            end
            2'b01: begin // Left shift
                shifted_data <= {data_in[98:0], 1'b0};
                shift_dir <= 0;
            end
            2'b10: begin // Right shift
                shifted_data <= {1'b0, data_in[99:1]};
                shift_dir <= 1;
            end
            2'b11: begin // Invalid
                shifted_data <= 0;
                shift_dir <= 0;
            end
        endcase
    end

endmodule

module accumulator(
    input       clk         ,
    input       reset       ,
    input       load        ,
    input       [7:0]   data_in     ,
    output reg  [7:0]   data_out
);

    always @(posedge clk) begin
        if (reset) begin
            data_out <= 0;
        end else begin
            if (load) begin
                data_out <= data_in;
            end else begin
                data_out <= data_out + data_in;
            end
        end
    end

endmodule

module xor_module(
    input       [99:0]  data_in_1   ,
    input       [7:0]   data_in_2   ,
    output reg  [99:0]  data_out
);

    always @(*) begin
        data_out = data_in_1 ^ {92'b0, data_in_2};
    end

endmodule

module FIR_filter(
  input [n-1:0] in,
  input clk,
  input rst,
  output reg out
);

parameter n = 8; // number of input signals
parameter k = 4; // number of filter taps
parameter frac_bits = 8; // number of fractional bits for fixed-point arithmetic

reg [n-1:0] input_reg [0:k-1]; // register array to store input signals
reg [n-1:0] coeff [0:k-1]; // coefficient array for filter taps
reg signed [n+frac_bits-1:0] prod_reg [0:k-1]; // register array to store products of input signals and coefficients
reg signed [n+frac_bits-1:0] sum_reg; // register to store sum of products

integer i, j; // loop counters

always @(posedge clk) begin
  if (rst) begin
    // reset filter to initial state
    for (i = 0; i < k; i = i + 1) begin
      input_reg[i] <= 0;
      coeff[i] <= 0;
      prod_reg[i] <= 0;
    end
    sum_reg <= 0;
  end else begin
    // shift input signals into register array
    for (i = k-1; i > 0; i = i - 1) begin
      input_reg[i] <= input_reg[i-1];
    end
    input_reg[0] <= in;

    // multiply input signals by coefficients and store in product register array
    for (i = 0; i < k; i = i + 1) begin
      prod_reg[i] <= $signed(input_reg[i]) * $signed(coeff[i]);
    end

    // sum products in product register array and store in sum register
    sum_reg <= 0;
    for (i = 0; i < k; i = i + 1) begin
      sum_reg <= sum_reg + prod_reg[i];
    end

    // output filtered signal
    out <= sum_reg[n+frac_bits-1:n] >> frac_bits;
  end
end

endmodule

