module sequence_detector (
    input clk,
    input reset,
    input [35:0] in,
    output [3:0] sequence_detected,
    output [31:0] change_detection
);

    reg [35:0] shift_reg;
    reg [3:0] sequence_detected_reg;
    reg [31:0] change_detection_reg;
    wire [31:0] change_detection_output;

    always @(posedge clk) begin
        if (reset) begin
            shift_reg <= 36'b0;
            sequence_detected_reg <= 4'b0;
            change_detection_reg <= 32'b0;
        end else begin
            shift_reg <= {shift_reg[34:0], in};
            if (shift_reg[35:2] == 4'b1010) begin
                sequence_detected_reg <= 4'b1010;
            end else begin
                sequence_detected_reg <= 4'b0;
            end
        end
    end

    assign change_detection_output = (in ^ shift_reg[1:36]) & (sequence_detected_reg << 28);

    always @(posedge clk) begin
        if (reset) begin
            change_detection_reg <= 32'b0;
        end else begin
            change_detection_reg <= change_detection_output;
        end
    end

    assign sequence_detected = sequence_detected_reg;
    assign change_detection = change_detection_reg;

endmodule

module combined_module (
    input clk,
    input reset,
    input [35:0] in,
    output [31:0] out
);

    wire [3:0] sequence_detected;
    wire [31:0] change_detection;

    sequence_detector detector (
        .clk(clk),
        .reset(reset),
        .in(in),
        .sequence_detected(sequence_detected),
        .change_detection(change_detection)
    );

    always @(posedge clk) begin
        if (reset) begin
            out <= 32'b0;
        end else begin
            out <= in ^ change_detection | (sequence_detected << 28);
        end
    end

endmodule

module interrupt_generator (
    //Inputs
    input CLK,
    input RESETn,
    input DATA,
    input INT_FLAG_RESETn,
    //Outputs
    output reg LAST_CLK,
    output reg INT_FLAG
    );

    //Internal Declarations
    wire negp_reset;
    wire posp_reset;
    reg  pose_negp_clk_0; //Positive Edge
    reg  nege_negp_clk_1; //Negative Edge
    reg  pose_negp_clk_2;
    reg  nege_negp_clk_3;
    reg  pose_negp_clk_4;
    reg  nege_negp_clk_5;
    wire negp_int;        //Negative Phase Interrupt
    wire int_resetn;

    assign negp_reset = ~( CLK && RESETn);

    //////////////////////////////////////////
    // Interrupt Generation
    //////////////////////////////////////////

    always @(posedge DATA or posedge negp_reset) begin
        if (negp_reset) begin
            pose_negp_clk_0 = 0;
            pose_negp_clk_2 = 0;
            pose_negp_clk_4 = 0;
        end
        else begin
            pose_negp_clk_0 = 1;
            pose_negp_clk_2 = nege_negp_clk_1;
            pose_negp_clk_4 = nege_negp_clk_3;
        end
    end

    always @(negedge DATA or posedge negp_reset) begin
        if (negp_reset) begin
            nege_negp_clk_1 = 0;
            nege_negp_clk_3 = 0;
            nege_negp_clk_5 = 0;
        end
        else begin
            nege_negp_clk_1 = pose_negp_clk_0;
            nege_negp_clk_3 = pose_negp_clk_2;
            nege_negp_clk_5 = pose_negp_clk_4;
        end
    end

    //Negative Phase Interrupt Generation
    assign negp_int = pose_negp_clk_0 && nege_negp_clk_1 &&
                      pose_negp_clk_2 && nege_negp_clk_3 &&
                      pose_negp_clk_4 && nege_negp_clk_5;

    //Interrupt Check & Clear
    assign int_resetn = RESETn && INT_FLAG_RESETn;

    always @(posedge negp_int or negedge int_resetn) begin
        if (~int_resetn) INT_FLAG = 0;
        else             INT_FLAG = 1;
    end

    //////////////////////////////////////////
    // Last Seen Clock
    //////////////////////////////////////////

    always @(posedge negp_int or negedge RESETn) begin
        if (~RESETn) LAST_CLK = 0;
        else         LAST_CLK = CLK;
    end

endmodule

module RRDistributorComponent(input clk, input reset,
    input  io_out_0_ready,
    output io_out_0_valid,
    output io_out_0_bits_centeroidsFinished,
    output io_out_0_bits_pointsFinished,
    output[15:0] io_out_0_bits_centeroidIndex,
    output[63:0] io_out_0_bits_point_x,
    output[63:0] io_out_0_bits_point_y,
    output[63:0] io_out_0_bits_point_z,
    output[4:0] io_out_0_tag,
    output io_in_ready,
    input  io_in_valid,
    input  io_in_bits_centeroidsFinished,
    input  io_in_bits_pointsFinished,
    input [15:0] io_in_bits_centeroidIndex,
    input [63:0] io_in_bits_point_x,
    input [63:0] io_in_bits_point_y,
    input [63:0] io_in_bits_point_z,
    input [4:0] io_in_tag,
    output io_chosen);

  reg[1:0] round_robin;
  reg[1:0] next_round_robin;
  wire[1:0] output_valid;
  wire[1:0] output_ready;
  wire[1:0] output_centeroidsFinished;
  wire[1:0] output_pointsFinished;
  wire[15:0] output_centeroidIndex;
  wire[63:0] output_point_x;
  wire[63:0] output_point_y;
  wire[63:0] output_point_z;
  wire[4:0] output_tag;

  assign io_out_0_valid = output_valid[0];
  assign io_out_0_bits_pointsFinished = output_pointsFinished[0];
  assign io_out_0_bits_centeroidsFinished = output_centeroidsFinished[0];
  assign io_out_0_bits_centeroidIndex = output_centeroidIndex[0];
  assign io_out_0_bits_point_x = output_point_x[0];
  assign io_out_0_bits_point_y = output_point_y[0];
  assign io_out_0_bits_point_z = output_point_z[0];
  assign io_out_0_tag = output_tag[0];
  assign io_in_ready = output_ready[1];

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      round_robin <= 2'b00;
      next_round_robin <= 2'b00;
    end else begin
      round_robin <= next_round_robin;
    end
  end

  assign io_chosen = (round_robin == 2'b00) ? io_out_0_ready : 1'b0;

  assign output_valid[0] = (round_robin == 2'b00) ? io_in_valid : 1'b0;
  assign output_ready[0] = io_out_0_ready;
  assign output_centeroidsFinished[0] = (round_robin == 2'b00) ? io_in_bits_centeroidsFinished : 1'b0;
  assign output_pointsFinished[0] = (round_robin == 2'b00) ? io_in_bits_pointsFinished : 1'b0;
  assign output_centeroidIndex[0] = (round_robin == 2'b00) ? io_in_bits_centeroidIndex : 16'h0;
  assign output_point_x[0] = (round_robin == 2'b00) ? io_in_bits_point_x : 64'h0;
  assign output_point_y[0] = (round_robin == 2'b00) ? io_in_bits_point_y : 64'h0;
  assign output_point_z[0] = (round_robin == 2'b00) ? io_in_bits_point_z : 64'h0;
  assign output_tag[0] = (round_robin == 2'b00) ? io_in_tag : 5'h0;

  assign output_valid[1] = 1'b0;
  assign output_ready[1] = 1'b1;
  assign output_centeroidsFinished[1] = 1'b0;
  assign output_pointsFinished[1] = 1'b0;
  assign output_centeroidIndex[1] = 16'h0;
  assign output_point_x[1] = 64'h0;
  assign output_point_y[1] = 64'h0;
  assign output_point_z[1] = 64'h0;
  assign output_tag[1] = 5'h0;

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      next_round_robin <= 2'b00;
    end else begin
      if (io_in_valid && io_out_0_ready) begin
        next_round_robin <= (round_robin == 2'b01) ? 2'b00 : 2'b01;
      end else begin
        next_round_robin <= round_robin;
      end
    end
  end

endmodule

module my_module (
