pippo_div_uu #(
    .z_width(z_width),
    .d_width(d_width)
) divider (
    .clk(clk),
    .ena(ena),
    .z(abs_z),
    .d(abs_d),
    .q(abs_q),
    .s(abs_s),
    .ovf(ovf_internal),
    .div0(div0_internal)
);

assign neg_q = (sign == 2'b10) ? (~abs_q + 1) : abs_q;
assign neg_s = (z[z_width-1] == 1) ? (~abs_s + 1) : abs_s;

assign quotient = (sign == 2'b10) ? neg_q : abs_q;
assign remainder = (z[z_width-1] == 1) ? neg_s : abs_s;

assign q = {sign[1], quotient};
assign s = {sign[1], remainder};

endmodule

