module byte_reverser(
    input [31:0] in,
    output [31:0] out
);

    wire [7:0] byte0 = in[7:0];
    wire [7:0] byte1 = in[15:8];
    wire [7:0] byte2 = in[23:16];
    wire [7:0] byte3 = in[31:24];

    wire [31:0] shifted_byte0 = byte0 << 24;
    wire [31:0] shifted_byte1 = byte1 << 16;
    wire [31:0] shifted_byte2 = byte2 << 8;
    wire [31:0] shifted_byte3 = byte3;

    assign out = shifted_byte0 | shifted_byte1 | shifted_byte2 | shifted_byte3;

endmodule

