module traffic_light_controller (
    input clk,
    input rst,
    input pedestrian_btn,
    output reg red_light,
    output reg yellow_light,
    output reg green_light,
    output reg pedestrian_light
);

    parameter GREEN_TIME = 30;
    parameter YELLOW_TIME = 5;
    parameter RED_TIME = 30;
    parameter PEDESTRIAN_TIME = 10;

    reg [4:0] timer;
    reg [3:0] state;

    always @ (posedge clk) begin
        if (rst) begin
            state <= 4'b0000;
            timer <= 5'b00000;
            red_light <= 1'b1;
            yellow_light <= 1'b0;
            green_light <= 1'b0;
            pedestrian_light <= 1'b0;
        end else begin
            case (state)
                4'b0000: begin // Red light
                    if (timer == RED_TIME) begin
                        state <= 4'b0010;
                        timer <= 5'b00000;
                        red_light <= 1'b0;
                        yellow_light <= 1'b1;
                        green_light <= 1'b0;
                        pedestrian_light <= 1'b0;
                    end else begin
                        timer <= timer + 1;
                    end
                end
                4'b0010: begin // Yellow light
                    if (timer == YELLOW_TIME) begin
                        state <= 4'b0100;
                        timer <= 5'b00000;
                        red_light <= 1'b0;
                        yellow_light <= 1'b0;
                        green_light <= 1'b1;
                        pedestrian_light <= 1'b0;
                    end else begin
                        timer <= timer + 1;
                    end
                end
                4'b0100: begin // Green light
                    if (timer == GREEN_TIME) begin
                        state <= 4'b0000;
                        timer <= 5'b00000;
                        red_light <= 1'b1;
                        yellow_light <= 1'b0;
                        green_light <= 1'b0;
                        pedestrian_light <= 1'b0;
                    end else begin
                        timer <= timer + 1;
                    end
                end
                4'b1000: begin // Pedestrian light
                    if (timer == PEDESTRIAN_TIME) begin
                        state <= 4'b0000;
                        timer <= 5'b00000;
                        red_light <= 1'b1;
                        yellow_light <= 1'b0;
                        green_light <= 1'b0;
                        pedestrian_light <= 1'b0;
                    end else if (timer == PEDESTRIAN_TIME - 1) begin
                        pedestrian_light <= 1'b0;
                    end else begin
                        timer <= timer + 1;
                        pedestrian_light <= 1'b1;
                    end
                end
                default: state <= 4'b0000;
            endcase
        end
    end

    always @ (posedge clk) begin
        if (rst) begin
            state <= 4'b0000;
            timer <= 5'b00000;
            pedestrian_light <= 1'b0;
        end else begin
            case (state)
                4'b0000: begin // Red light
                    if (pedestrian_btn) begin
                        state <= 4'b1000;
                        timer <= 5'b00000;
                        pedestrian_light <= 1'b1;
                    end
                end
                4'b0010: begin // Yellow light
                    if (pedestrian_btn) begin
                        state <= 4'b1000;
                        timer <= 5'b00000;
                        pedestrian_light <= 1'b1;
                    end
                end
                4'b0100: begin // Green light
                    if (pedestrian_btn) begin
                        state <= 4'b1000;
                        timer <= 5'b00000;
                        pedestrian_light <= 1'b1;
                    end
                end
                4'b1000: begin // Pedestrian light
                    if (!pedestrian_btn) begin
                        state <= 4'b0000;
                        timer <= 5'b00000;
                        pedestrian_light <= 1'b0;
                    end
                end
                default: state <= 4'b0000;
            endcase
        end
    end

endmodule

module top_module (
    input clk,
    input reset,
    input [7:0] d,
    input mode_select,
    output [7:0] q
);

    reg [7:0] reg_out;
    reg [2:0] counter_out;
    wire [7:0] func_out;

    // Register with active high synchronous reset
    always @(posedge clk, negedge reset) begin
        if (reset == 1'b0) begin
            reg_out <= 8'b0;
        end else begin
            reg_out <= d;
        end
    end

    // 3-bit counter that counts from 0 to 7
    always @(posedge clk, negedge reset) begin
        if (reset == 1'b0) begin
            counter_out <= 3'b0;
        end else if (counter_out == 3'b111) begin
            counter_out <= 3'b0;
        end else begin
            counter_out <= counter_out + 1;
        end
    end

    // Load counter with register output on reset
    always @(posedge clk, negedge reset) begin
        if (reset == 1'b0) begin
            counter_out <= reg_out[2:0];
        end
    end

    // Functional module that performs XOR or XNOR operation
    xor_xnor_module xor_xnor_inst (
        .a(counter_out),
        .b(reg_out),
        .mode(mode_select),
        .y(func_out)
    );

    // Output the result of the functional module
    assign q = func_out;

endmodule

module xor_xnor_module (
    input [2:0] a,
    input [7:0] b,
    input mode,
    output [7:0] y
);

    always @(*) begin
        if (mode == 1'b0) begin
            y = a ^ b;
        end else begin
            y = ~(a ^ b);
        end
    end

endmodule

module signal_router (
   input rst_l,
   input clk,
   input [39:0] src0_data,
   input [39:0] src1_data,
   input [39:0] src2_data,
   input [39:0] src3_data,
   input [39:0] src4_data,
   input src0_vld,
   input src1_vld,
   input src2_vld,
   input src3_vld,
   input src4_vld,
   input [63:0] creg_dbg_enet_ctrl,
   input [63:0] creg_dbg_enet_idleval,
   input io_trigin,
   output reg [39:0] iob_io_dbg_data,
   output reg iob_io_dbg_en,
   output reg [2:0] iob_io_dbg_ck_p,
   output reg [2:0] iob_io_dbg_ck_n,
   output reg l2_vis_armin,
   output reg iob_clk_tr
);

   wire [3:0] dbg_sel;
   wire [39:0] dbg_idleval;
   wire [39:0] dbg_data;
   wire dbg_en;
   wire dbg_armin_en;
   wire dbg_trigin_en;
   wire iob_io_dbg_ck_p_next;
   wire io_trigin_d1;
   wire io_trigin_d2;
   wire io_trigin_d3;
   wire io_trigin_detected;
   wire iob_clk_tr_a1;
   reg [39:0] mux_data;
   reg mux_vld;

   assign dbg_sel = creg_dbg_enet_ctrl[3:0];
   assign dbg_idleval = creg_dbg_enet_idleval[39:0];
   assign dbg_en = creg_dbg_enet_ctrl[8];
   assign dbg_armin_en = creg_dbg_enet_ctrl[6];
   assign dbg_trigin_en = creg_dbg_enet_ctrl[5];

   always @* begin
      case(dbg_sel)
         4'b0000:  {mux_vld, mux_data} = {src0_vld, src0_data};
         4'b0001:  {mux_vld, mux_data} = {src1_vld, src1_data};
         4'b0010:  {mux_vld, mux_data} = {src2_vld, src2_data};
         4'b0011:  {mux_vld, mux_data} = {src3_vld, src3_data};
         4'b0100:  {mux_vld, mux_data} = {src4_vld, src4_data};
         default:  {mux_vld, mux_data} = {1'b0, 40'b0};
      endcase
   end

   assign dbg_data = mux_vld ? mux_data : dbg_idleval;

   always @(posedge clk) begin
      iob_io_dbg_data <= dbg_data;
      iob_io_dbg_en <= dbg_en;
   end

   always @(posedge clk) begin
      iob_io_dbg_ck_p_next <= ~iob_io_dbg_ck_p[0] & dbg_en;
      iob_io_dbg_ck_p[0] <= iob_io_dbg_ck_p_next;
      iob_io_dbg_ck_p[1] <= iob_io_dbg_ck_p[0];
      iob_io_dbg_ck_p[2] <= iob_io_dbg_ck_p[0];
      iob_io_dbg_ck_n <= ~iob_io_dbg_ck_p;
   end

   always @(posedge clk or negedge rst_l) begin
      if (!rst_l) begin
         l2_vis_armin <= 1'b0;
         iob_clk_tr <= 1'b0;
      end else begin
         io_trigin_d1 <= io_trigin;
         io_trigin_d2 <= io_trigin_d1;
         io_trigin_d3 <= io_trigin_d2;
         io_trigin_detected <= io_trigin_d2 & ~io_trigin_d3;
         l2_vis_armin <= dbg_armin_en & io_trigin_detected;
         iob_clk_tr_a1 <= dbg_trigin_en & io_trigin_detected;
         iob_clk_tr <= iob_clk_tr_a1;
      end
   end

endmodule

