module gray_code_converter (
    input cmp_EQ,
    input cmp_GT,
    input cmp_LT,
    output reg [2:0] gray_code
);

    always @(*) begin
        case ({cmp_GT, cmp_EQ, cmp_LT})
            3'b000: gray_code = 3'b000;
            3'b001: gray_code = 3'b001;
            3'b010: gray_code = 3'b011;
            3'b011: gray_code = 3'b010;
            3'b100: gray_code = 3'b110;
            3'b101: gray_code = 3'b111;
            3'b110: gray_code = 3'b101;
            3'b111: gray_code = 3'b100;
        endcase
    end

endmodule

