module spi_state_machine (
  input clk,
  input rst,
  input mosi,
  input sck,
  input ss,
  output miso
);

  // Define the states
  parameter IDLE = 2'b00;
  parameter SEND = 2'b01;
  parameter RECEIVE = 2'b10;
  parameter DONE = 2'b11;

  // Define the state register and next state logic
  reg [1:0] state, next_state;
  always @ (posedge clk) begin
    if (rst) begin
      state <= IDLE;
    end else begin
      state <= next_state;
    end
  end

  // Define the output register and next output logic
  reg miso_reg, next_miso;
  always @ (posedge clk) begin
    miso_reg <= next_miso;
  end

  // Define the data register and next data logic
  reg [7:0] data_reg, next_data;
  always @ (posedge clk) begin
    data_reg <= next_data;
  end

  // Define the count register and next count logic
  reg [2:0] count_reg, next_count;
  always @ (posedge clk) begin
    count_reg <= next_count;
  end

  // Define the state machine
  always @ (*) begin
    case (state)
      IDLE: begin
        if (ss == 1'b0) begin
          next_state = SEND;
          next_data = 8'h00;
          next_count = 3'b000;
        end else begin
          next_state = IDLE;
          next_data = data_reg;
          next_count = count_reg;
        end
        next_miso = miso_reg;
      end

      SEND: begin
        if (count_reg == 3'b111) begin
          next_state = RECEIVE;
          next_data = 8'h00;
          next_count = 3'b000;
        end else begin
          next_state = SEND;
          next_data = {mosi, data_reg[6:0]};
          next_count = count_reg + 1;
        end
        next_miso = miso_reg;
      end

      RECEIVE: begin
        if (count_reg == 3'b111) begin
          next_state = DONE;
          next_data = data_reg;
          next_count = count_reg;
        end else begin
          next_state = RECEIVE;
          next_data = {1'b0, data_reg[7:1]};
          next_count = count_reg + 1;
        end
        next_miso = miso_reg;
      end

      DONE: begin
        if (ss == 1'b1) begin
          next_state = IDLE;
          next_data = 8'h00;
          next_count = 3'b000;
        end else begin
          next_state = DONE;
          next_data = data_reg;
          next_count = count_reg;
        end
        next_miso = miso_reg;
      end

      default: begin
        next_state = IDLE;
        next_data = 8'h00;
        next_count = 3'b000;
        next_miso = 1'b0;
      end
    endcase
  end

  // Define the output logic
  assign miso = miso_reg;

endmodule

module TestWrapper(
    input clk,
    input reset_l,
    input enable,
    input [9:0] q_var0,
    input [9:0] q_var2,
    input [9:0] q_var4,
    input [9:0] q_var6,
    output reg [63:0] result,
    output reg [63:0] sum
);

reg [63:0] crc = 64'h5aef0c8d_d70a4497;

Test test (
    // Outputs
    .q      (result[2:0]),
    // Inputs
    .clk        (clk),
    .reset_l        (reset_l),
    .enable     (enable),
    .q_var0     (crc[19:10]),
    .q_var2     (crc[29:20]),
    .q_var4     (crc[39:30]),
    .q_var6     (crc[49:40])
    /*AUTOINST*/);

// Test loop
always @ (posedge clk) begin
    if (reset_l == 0) begin
        crc <= 64'h5aef0c8d_d70a4497;
        sum <= 64'h0;
    end else if (enable == 1) begin
        crc <= {crc[62:0], crc[63]^crc[2]^crc[0], q_var0, q_var2, q_var4, q_var6};
        sum <= result ^ {sum[62:0],sum[63]^sum[2]^sum[0]};
    end
    result <= {61'h0, test.q};
end

endmodule

module dut(
  input wire clk,
  input wire reset,
  input wire [15:0] input_signal,
  output reg [3:0] output_signal
);

reg [3:0] count;

always @(posedge clk) begin
  if (reset) begin
    count <= 0;
  end else begin
    if (input_signal == 16'b1111_1111_1111_1111 || input_signal == 16'b0000_0000_0000_0000) begin
      count <= 0;
    end else if (input_signal[15] == 1) begin
      count <= 1;
    end else begin
      count <= count + 1;
    end
  end
end

always @(posedge clk) begin
  if (reset) begin
    output_signal <= 0;
  end else if (input_signal == 16'b1111_1111_1111_1111 || input_signal == 16'b0000_0000_0000_0000) begin
    output_signal <= 0;
  end else if (input_signal[15] == 1) begin
    output_signal <= count;
