module signed_mag_comp (
    input wire [3:0] a, b,
    input wire valid,
    output wire greater_than,
    output wire overflow
);

    wire [3:0] abs_a, abs_b;
    wire [4:0] sum;
    wire carry;

    assign abs_a = (a[3] == 1) ? ~a + 1 : a;
    assign abs_b = (b[3] == 1) ? ~b + 1 : b;

    ripple_adder adder (
        .a(abs_a),
        .b(~abs_b + 1),
        .sum(sum),
        .carry(carry)
    );

    assign greater_than = (a[3] == 1 && b[3] == 0) ? 1 :
                          (a[3] == 0 && b[3] == 1) ? 0 :
                          (a[3] == 1 && b[3] == 1 && sum[4] == 0) ? 1 :
                          (a[3] == 0 && b[3] == 0 && sum[4] == 1) ? 0 :
                          (abs_a > abs_b) ? 1 : 0;

    assign overflow = (a[3] == 1 && b[3] == 1 && sum[4] == 1) ? 1 : 0;

    assign greater_than = (valid == 1) ? greater_than : 0;
    assign overflow = (valid == 1) ? overflow : 0;

endmodule

