module multiplier_4bit (
    input [3:0] A,
    input [3:0] B,
    output reg [7:0] result
);

reg [4:0] multiplier;
reg [5:0] product;
reg [2:0] state;

always @(*) begin
    case (state)
        0: begin
            multiplier <= {1'b0, A};
            product <= {4'b0, B};
            state <= 1;
        end
        1: begin
            if (product[0] == 1) begin
                product <= product - multiplier;
                result <= result + multiplier;
            end
            multiplier <= {multiplier[3:1], multiplier[0]};
            product <= {product[4:1], product[0]};
            state <= (multiplier == 5'b00000) ? 2 : 1;
        end
        2: begin
            state <= 2;
        end
    endcase
end

endmodule

module motor_speed_measurement(
    // Qsys bus interface
    input               rsi_MRST_reset,
    input               csi_MCLK_clk,
    input       [31:0] avs_ctrl_writedata,
    output reg [31:0]  avs_ctrl_readdata,
    input       [3:0]  avs_ctrl_byteenable,
    input       [2:0]  avs_ctrl_address,
    input               avs_ctrl_write,
    input               avs_ctrl_read,
    output              avs_ctrl_waitrequest,

    input               rsi_PWMRST_reset,
    input               csi_PWMCLK_clk,

    // motor speed measurement interface
    input               frequent
    );

    reg [31:0] read_data;
    reg [31:0] gate_frequence;
    reg         reset;
    reg [7:0]   state;
    reg [7:0]   nextstate;
    reg [31:0]  counter_a;
    reg [31:0]  counter_b;
    reg         ready;
    reg [31:0]  tempgate;

    assign avs_ctrl_readdata = read_data;
    assign avs_ctrl_waitrequest = 0;

    always@(posedge csi_MCLK_clk or posedge rsi_MRST_reset) begin
        if(rsi_MRST_reset) begin
            read_data <= 0;
        end
        else if(avs_ctrl_write) begin
            case(avs_ctrl_address)
                1: begin
                    if(avs_ctrl_byteenable[3]) gate_frequence[31:24] <= avs_ctrl_writedata[31:24];
                    if(avs_ctrl_byteenable[2]) gate_frequence[23:16] <= avs_ctrl_writedata[23:16];
                    if(avs_ctrl_byteenable[1]) gate_frequence[15:8] <= avs_ctrl_writedata[15:8];
                    if(avs_ctrl_byteenable[0]) gate_frequence[7:0] <= avs_ctrl_writedata[7:0];
                end
                2: begin
                    if(avs_ctrl_byteenable[0]) reset <= avs_ctrl_writedata[0];
                end
                default:;
            endcase
        end
        else begin
            case(avs_ctrl_address)
                0: read_data <= 32'hEA680003;
                1: read_data <= gate_frequence;
                2: read_data <= {23'b0, ready, 7'b0, reset};
                3: read_data <= counter_a;
                4: read_data <= counter_b;
                default: read_data <= 32'b0;
            endcase
        end
    end

    always@(posedge csi_PWMCLK_clk or posedge rsi_PWMRST_reset) begin
        if(rsi_PWMRST_reset) begin
            state <= 1;
            counter_a <= 0;
            counter_b <= 0;
            ready <= 0;
            tempgate <= 0;
        end
        else if(reset) begin
            state <= 1;
            counter_a <= 0;
            counter_b <= 0;
            ready <= 0;
            tempgate <= 0;
        end
        else begin
            case(state)
                1: begin
                    if(tempgate[31] == 0) begin
                        nextstate <= 2;
                    end
                    else begin
                        nextstate <= 1;
                    end
                end
                2: begin
                    if(tempgate[31] == 1) begin
                        nextstate <= 3;
                    end
                    else begin
                        nextstate <= 2;
                    end
                end
                3: begin
                    if(tempgate[31] == 0) begin
                        nextstate <= 4;
                    end
                    else begin
                        nextstate <= 3;
                    end
                end
                4: begin
                    nextstate <= 4;
                end
                default: nextstate <= 1;
            endcase
        end
    end

    always@(posedge csi_PWMCLK_clk) begin
        if(state != 4) begin
            tempgate <= tempgate + gate_frequence;
        end
    end

    always@(posedge frequent) begin
        if(state != 4) begin
            counter_a <= counter_a + 1;
        end
    end

    always@(posedge csi_PWMCLK_clk) begin
        if(state != 4) begin
            counter_b <= counter_b + 1;
        end
        if(state == 4) begin
            ready <= 1;
        end
        else begin
            ready <= 0;
        end
    end

    assign avs_ctrl_waitrequest = (state != 4);

    assign avs_ctrl_readdata = read_data;

endmodule

