    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output reg [3:0] q);

    // Counter module
    reg [3:0] count;
    always @(posedge clk, posedge reset) begin
        if (reset) begin
            count <= 4'b0000;
        end else if (count == 4'b1111) begin
            count <= 4'b0000;
        end else begin
            count <= count + 1;
        end
    end

    // Multiplexer module
    wire [3:0] mux_out;
    mux_6to1 mux_inst (
