        .data1(data1),
        .data2(data2),
        .data3(data3),
        .data4(data4),
        .data5(data5),
        .out(mux_out)
    );

    // Control logic module
    reg [1:0] active_module;
    always @(posedge clk, posedge reset) begin
        if (reset) begin
            active_module <= 2'b00;
        end else begin
            case (sel)
                3'b000, 3'b001, 3'b010, 3'b011, 3'b100, 3'b101: active_module <= 2'b01; // Counter is active
                3'b110, 3'b111: active_module <= 2'b10; // Multiplexer is active
            endcase
        end
    end

    // Output logic
    always @(posedge clk) begin
        if (active_module == 2'b01) begin
            q <= count;
        end else begin
            q <= mux_out;
        end
    end

