module interrupt_controller (
  input [n-1:0] irq,
  output reg int
);

parameter n = 4; // number of interrupt request signals

reg [n-1:0] priority; // priority level of each interrupt request
reg [n-1:0] pending; // pending interrupt requests
reg [n-1:0] active; // active interrupt requests

always @(*) begin
  // determine the priority level of each interrupt request
  priority[0] = irq[0] ? 1 : 0;
  priority[1] = irq[1] ? 2 : 0;
  priority[2] = irq[2] ? 3 : 0;
  priority[3] = irq[3] ? 4 : 0;

  // determine the pending interrupt requests
  pending = priority & ~active;

  // determine the highest priority interrupt request
  case (pending)
    4'b1000: active = 4'b1000;
    4'b0100: active = 4'b0100;
    4'b0010: active = 4'b0010;
    4'b0001: active = 4'b0001;
    default: active = 4'b0000;
  endcase
end

always @(posedge active) begin
  // generate the interrupt signal when an interrupt request is accepted
  int <= 1;
end

always @(negedge int) begin
  // deactivate the interrupt signal when the interrupt is serviced
  int <= 0;
end

endmodule

