module cla_adder(a, b, c_in, s, g_out, p_out, c_out);
  input [3:0] a, b;
  input c_in;
  output [3:0] s;
  output g_out, p_out, c_out;
  wire [1:0] g, p;
  wire c_out1, c_out2, c_out3;

  // First stage of carry-lookahead adder
  cla_2 cla0 (a[1:0], b[1:0], c_in, g[0], p[0], s[1:0]);
  cla_2 cla1 (a[3:2], b[3:2], c_in, g[1], p[1], s[3:2]);

  // Second stage of carry-lookahead adder
  cla_2 cla2 (s[1:0], b[1:0], p[0], g[0], p[0], s[1:0]);
  cla_2 cla3 (s[3:2], b[3:2], p[1], g[1], p[1], s[3:2]);

  // Third stage of carry-lookahead adder
  cla_2 cla4 (s[1:0], a[1:0], p[0], g[0], p[0], s[1:0]);
  cla_2 cla5 (s[3:2], a[3:2], p[1], g[1], p[1], s[3:2]);

  // Final stage of carry-lookahead adder
  g_p g_p0(g, p, c_in, g_out, p_out, c_out1);
  g_p g_p1(g, p, c_out1, g_out, p_out, c_out2);
  g_p g_p2(g, p, c_out2, g_out, p_out, c_out3);

  assign c_out = c_out3;
