module async_transmitter(
    input clk,
    input TxD_start,
    input [7:0] TxD_data,
    output TxD,
    output TxD_busy
);

// Assert TxD_start for (at least) one clock cycle to start transmission of TxD_data
// TxD_data is latched so that it doesn't have to stay valid while it is being sent

parameter ClkFrequency = 25000000; // 25MHz
parameter Baud = 115200;

generate
    if(ClkFrequency<Baud*8 && (ClkFrequency % Baud!=0)) ASSERTION_ERROR PARAMETER_OUT_OF_RANGE("Frequency incompatible with requested Baud rate");
endgenerate

wire BitTick;
BaudTickGen #(ClkFrequency, Baud) tickgen(.clk(clk), .enable(TxD_busy), .tick(BitTick));

reg [3:0] TxD_state = 0;
wire TxD_ready = (TxD_state==0);
assign TxD_busy = ~TxD_ready;

reg [7:0] TxD_shift = 0;
always @(posedge clk)
begin
    if(TxD_ready & TxD_start)
        TxD_shift <= TxD_data;
    else if(TxD_state[3] & BitTick)
        TxD_shift <= (TxD_shift >> 1);

    case(TxD_state)
        4'b0000: if(TxD_start) TxD_state <= 4'b0100;
        4'b0100: if(BitTick) TxD_state <= 4'b1000;  // start bit
        4'b1000: if(BitTick) TxD_state <= 4'b1001;  // bit 0
        4'b1001: if(BitTick) TxD_state <= 4'b1010;  // bit 1
        4'b1010: if(BitTick) TxD_state <= 4'b1011;  // bit 2
        4'b1011: if(BitTick) TxD_state <= 4'b1100;  // bit 3
        4'b1100: if(BitTick) TxD_state <= 4'b1101;  // bit 4
        4'b1101: if(BitTick) TxD_state <= 4'b1110;  // bit 5
        4'b1110: if(BitTick) TxD_state <= 4'b1111;  // bit 6
        4'b1111: if(BitTick) TxD_state <= 4'b0010;  // bit 7
        4'b0010: if(BitTick) TxD_state <= 4'b0011;  // stop1
        4'b0011: if(BitTick) TxD_state <= 4'b0000;  // stop2
        default: if(BitTick) TxD_state <= 4'b0000;
    endcase
end

assign TxD = (TxD_state<4) | (TxD_state[3] & TxD_shift[0]);  // put together the start, data and stop bits
endmodule

module encryption_module (
    input [31:0] data,
    input [31:0] key,
    output reg [31:0] encrypted_data
);

reg [7:0] D0, D1, D2, D3, K0, K1, K2, K3;
reg [7:0] D0_encrypted, D1_encrypted, D2_encrypted, D3_encrypted;

// Split data into four 8-bit blocks
assign D0 = data[31:24];
assign D1 = data[23:16];
assign D2 = data[15:8];
assign D3 = data[7:0];

// Split key into four 8-bit blocks
assign K0 = key[31:24];
assign K1 = key[23:16];
assign K2 = key[15:8];
assign K3 = key[7:0];

// Encryption algorithm
always @* begin
    D0_encrypted = (D0 ^ K0) << (K0 % 8);
    D1_encrypted = (D1 ^ K1) << (K1 % 8);
    D2_encrypted = (D2 ^ K2) << (K2 % 8);
    D3_encrypted = (D3 ^ K3) << (K3 % 8);

    {D0_encrypted[23:16], D0_encrypted[15:8], D0_encrypted[7:0]} <= {D0_encrypted[15:8], D0_encrypted[7:0], D0_encrypted[23:16]};
    {D1_encrypted[23:16], D1_encrypted[15:8], D1_encrypted[7:0]} <= {D1_encrypted[15:8], D1_encrypted[7:0], D1_encrypted[23:16]};
    {D2_encrypted[23:16], D2_encrypted[15:8], D2_encrypted[7:0]} <= {D2_encrypted[15:8], D2_encrypted[7:0], D2_encrypted[23:16]};
    {D3_encrypted[23:16], D3_encrypted[15:8], D3_encrypted[7:0]} <= {D3_encrypted[15:8], D3_encrypted[7:0], D3_encrypted[23:16]};

    encrypted_data = {D0_encrypted, D1_encrypted, D2_encrypted, D3_encrypted};
end

endmodule

module instruction_decoder(
    input [31:0] instruction_data,
    output reg [3:0] opcode,
    output reg input_type_1,
    output reg [1:0] input_register_selector_1,
    output reg [7:0] input_immediate_1,
    output reg input_type_2,
    output reg [1:0] input_register_selector_2,
    output reg [7:0] input_immediate_2,
    output reg [1:0] output_register_selector
);

    always @*
    begin
        opcode = instruction_data[31:28];
        case(opcode)
            4'b0000: // add
            begin
                input_type_1 = 0;
                input_register_selector_1 = instruction_data[27:26];
                input_type_2 = 0;
                input_register_selector_2 = instruction_data[25:24];
                output_register_selector = instruction_data[23:22];
            end

            4'b0001: // subtract
            begin
                input_type_1 = 0;
                input_register_selector_1 = instruction_data[27:26];
                input_type_2 = 0;
                input_register_selector_2 = instruction_data[25:24];
                output_register_selector = instruction_data[23:22];
            end

            4'b0010: // bitwise and
            begin
                input_type_1 = 0;
                input_register_selector_1 = instruction_data[27:26];
                input_type_2 = 0;
                input_register_selector_2 = instruction_data[25:24];
                output_register_selector = instruction_data[23:22];
            end

            4'b0011: // bitwise or
            begin
                input_type_1 = 0;
                input_register_selector_1 = instruction_data[27:26];
                input_type_2 = 0;
                input_register_selector_2 = instruction_data[25:24];
                output_register_selector = instruction_data[23:22];
            end

            4'b0100: // bitwise xor
            begin
                input_type_1 = 0;
                input_register_selector_1 = instruction_data[27:26];
                input_type_2 = 0;
                input_register_selector_2 = instruction_data[25:24];
                output_register_selector = instruction_data[23:22];
            end

            4'b0101: // shift left
            begin
                input_type_1 = 0;
                input_register_selector_1 = instruction_data[27:26];
                input_type_2 = 1;
                input_immediate_2 = instruction_data[23:16];
                output_register_selector = instruction_data[15:14];
            end

            4'b0110: // shift right
            begin
                input_type_1 = 0;
                input_register_selector_1 = instruction_data[27:26];
                input_type_2 = 1;
                input_immediate_2 = instruction_data[23:16];
                output_register_selector = instruction_data[15:14];
            end

            4'b0111: // load immediate
            begin
                input_type_1 = 1;
                input_immediate_1 = instruction_data[23:16];
                output_register_selector = instruction_data[15:14];
            end

            4'b1000: // load register
            begin
                input_type_1 = 0;
                input_register_selector_1 = instruction_data[27:26];
                output_register_selector = instruction_data[15:14];
            end

            4'b1001: // store register
            begin
                input_type_1 = 0;
                input_register_selector_1 = instruction_data[27:26];
                input_type_2 = 1;
                input_immediate_2 = instruction_data[23:16];
            end

            default: // invalid opcode
            begin
                input_type_1 = 0;
                input_register_selector_1 = 0;
                input_immediate_1 = 0;
                input_type_2 = 0;
                input_register_selector_2 = 0;
                input_immediate_2 = 0;
                output_register_selector = 0;
            end
        endcase
    end

endmodule

