    if (reset) begin
        prev_in <= 4'b0000;
        out <= 4'b0000;
    end else begin
        prev_in <= in;
        out <= 4'b0000;
        if (in[0] != prev_in[0]) out[0] <= 1'b1;
        if (in[1] != prev_in[1]) out[1] <= 1'b1;
        if (in[2] != prev_in[2]) out[2] <= 1'b1;
