  input [7:0] a,
  input [7:0] b,
  output reg [15:0] product,
  output reg greater
);

  always @* begin
    product = 0;
    greater = (a > b) ? 1 : 0;
    for (i = 0; i < 8; i = i + 1) begin
      if (b[i] == 1) begin
        product = product + (a << i);
