module multiplexer #(parameter WIDTH = 1, parameter N = 2)
  (
   input [WIDTH-1:0] ctrl,
   input [WIDTH-1:0] D0,
   input [WIDTH-1:0] D1,
   input [WIDTH-1:0] D2,
   // ...
   input [WIDTH-1:0] DN_1,
   output [WIDTH-1:0] S
  );

  wire [N-1:0] select;
  assign select[0] = ctrl;

  // Generate select signals for each input
  generate
    genvar i;
    for (i = 1; i < N; i = i + 1) begin : gen_select
      assign select[i] = (ctrl == i);
    end
  endgenerate

  // Generate the output
  generate
    genvar i;
    for (i = 0; i < N; i = i + 1) begin : gen_output
      assign S = (select[i]) ? ({WIDTH{1'b0}} | D[i]) : S;
    end
  endgenerate

endmodule

