module tx_fct_send(
			input pclk_tx,
			input send_null_tx,
			input enable_tx,

			input send_fct_now,
			input fct_sent,
			output reg [2:0] fct_flag_p
		  );

	reg [2:0] fct_flag;
	reg clear_reg_fct_flag;

	reg  [2:0] state_fct_send/* synthesis dont_replicate */;
	reg  [2:0] next_state_fct_send/* synthesis dont_replicate */;

	reg  [2:0] state_fct_send_p/* synthesis dont_replicate */;
	reg  [2:0] next_state_fct_send_p/* synthesis dont_replicate */;

always@(*)
begin
	next_state_fct_send = state_fct_send;

	case(state_fct_send)
	3'd0:
	begin
		if(send_fct_now)
		begin
			next_state_fct_send = 3'd1;
		end
		else 
			next_state_fct_send = 3'd0;
	end
	3'd1:
	begin
		next_state_fct_send = 3'd2;
	end
	3'd2:
	begin
		if(send_fct_now)
		begin
			next_state_fct_send = 3'd2;
		end
		else 
		begin
			next_state_fct_send = 3'd0;
		end
	end
	default:
	begin
		next_state_fct_send = 3'd0;
	end
	endcase
end

always@(posedge pclk_tx or negedge enable_tx)
begin
	if(!enable_tx)
	begin
		fct_flag <= 3'd0;
		state_fct_send<= 3'd0;
	end
	else if(send_null_tx)
	begin
		state_fct_send <= next_state_fct_send;

		case(state_fct_send)
		3'd0:
		begin
			if(clear_reg_fct_flag)
			begin
				fct_flag <= 3'd0;
			end
			else 
			begin
				fct_flag <= fct_flag;
			end
		end
		3'd1:
		begin
			fct_flag <= fct_flag + 3'd1;
		end
		3'd2:
		begin
			fct_flag <= fct_flag;
		end
		default:
		begin
			fct_flag <= fct_flag;
		end
		endcase
	end
end




always@(*)
begin
	next_state_fct_send_p = state_fct_send_p;

	case(state_fct_send_p)
	3'd0:
	begin
		next_state_fct_send_p = 3'd2;
	end
	3'd1:
	begin
		if(fct_flag == 3'd7)
		begin
			next_state_fct_send_p = 3'd2;
		end
		else 
			next_state_fct_send_p = 3'd1;
	end
	3'd2:
	begin
		if(fct_sent)
		begin
			next_state_fct_send_p = 3'd3;
		end
		else 
			next_state_fct_send_p = 3'd2;
	end
	3'd3:
	begin
		if(fct_flag_p > 3'd0 && !fct_sent)
		begin
			next_state_fct_send_p = 3'd2;
		end
		else if(fct_flag_p == 3'd0 && !fct_sent)
		begin
			next_state_fct_send_p = 3'd1;
		end
		else
		begin
			next_state_fct_send_p = 3'd3;
		end
	end
	default:
	begin
		next_state_fct_send_p = 3'd0;
	end
	endcase
end

always@(posedge pclk_tx or negedge enable_tx)
begin
	if(!enable_tx)
	begin
		fct_flag_p <= 3'd0;
		state_fct_send_p<= 3'd0;
		clear_reg_fct_flag <=1'b0;
	end
	else if(send_null_tx)
	begin
		state_fct_send_p <= next_state_fct_send_p;

		case(state_fct_send_p)
		3'd0:
		begin
			clear_reg_fct_flag <=1'b0;
			fct_flag_p <= 3'd7;
		end
		3'd1:
		begin
			clear_reg_fct_flag <=1'b0;

			if(fct_flag == 3'd7)
			begin
				fct_flag_p <= 3'd7;
			end
			else 
			begin	
				fct_flag_p <= fct_flag_p;				
			end
		end
		3'd2:
		begin
			clear_reg_fct_flag <=1'b1;

			if(fct_sent)
			begin
				fct_flag_p <= fct_flag_p - 3'd1;
			end
			else 
			begin
				fct_flag_p <= fct_flag_p;
			end
		end
		3'd3:
		begin
			clear_reg_fct_flag <=1'b0;
			fct_flag_p <= fct_flag_p;
		end
		default:
		begin
			fct_flag_p <= fct_flag_p;
		end
		endcase
	end
end

endmodule

module FIFO_image_filter_module (
    clk,
    data,
    ce,
    a,
    q
);

parameter DATA_WIDTH = 12;
parameter ADDR_WIDTH = 2;
parameter DEPTH = 3;

input clk;
input [DATA_WIDTH-1:0] data;
input ce;
input [ADDR_WIDTH-1:0] a;
output reg [DATA_WIDTH-1:0] q;

reg[DATA_WIDTH-1:0] SRL_SIG [0:DEPTH-1];
integer i;

always @ (posedge clk)
begin
    if (ce)
    begin
        for (i=0;i<DEPTH-1;i=i+1)
            SRL_SIG[i+1] <= SRL_SIG[i];
        SRL_SIG[0] <= data;
    end
end

assign q = SRL_SIG[a];

endmodule

module one_hot_mux
    #(parameter C_DATA_WIDTH = 1,
      parameter C_SELECT_WIDTH = 2,
      parameter C_AGGREGATE_WIDTH = C_SELECT_WIDTH*C_DATA_WIDTH
      )
    (
     input [C_SELECT_WIDTH-1:0]    ONE_HOT_SELECT,
     input [C_AGGREGATE_WIDTH-1:0] ONE_HOT_INPUTS,
     output [C_DATA_WIDTH-1:0]     ONE_HOT_OUTPUT);

    genvar                         i;

    wire [C_DATA_WIDTH-1:0]        wOneHotInputs[(1<<C_SELECT_WIDTH):1];
    reg [C_DATA_WIDTH-1:0]         _rOneHotOutput;

    assign ONE_HOT_OUTPUT = _rOneHotOutput;
    generate
        for( i = 0 ; i < C_SELECT_WIDTH; i = i + 1 ) begin : gen_input_array
            assign wOneHotInputs[(1<<i)] = ONE_HOT_INPUTS[C_DATA_WIDTH*i +: C_DATA_WIDTH];
        end
        if(C_SELECT_WIDTH == 1) begin
            always @(*) begin
                _rOneHotOutput = wOneHotInputs[1];
            end
        end else if(C_SELECT_WIDTH == 2) begin
            always @(*) begin
                case(ONE_HOT_SELECT)
                    2'b01: _rOneHotOutput = wOneHotInputs[1];
                    2'b10: _rOneHotOutput = wOneHotInputs[2];
                    default:_rOneHotOutput = wOneHotInputs[1];
                endcase // case (ONE_HOT_SELECT)
            end
        end else if( C_SELECT_WIDTH == 4) begin
            always @(*) begin
                case(ONE_HOT_SELECT)
                    4'b0001: _rOneHotOutput = wOneHotInputs[1];
                    4'b0010: _rOneHotOutput = wOneHotInputs[2];
                    4'b0100: _rOneHotOutput = wOneHotInputs[4];
                    4'b1000: _rOneHotOutput = wOneHotInputs[8];
                    default:_rOneHotOutput = wOneHotInputs[1];
                endcase // case (ONE_HOT_SELECT)
            end
        end else if( C_SELECT_WIDTH == 8) begin
            always @(*) begin
                case(ONE_HOT_SELECT)
                    8'b00000001: _rOneHotOutput = wOneHotInputs[1];
                    8'b00000010: _rOneHotOutput = wOneHotInputs[2];
                    8'b00000100: _rOneHotOutput = wOneHotInputs[4];
                    8'b00001000: _rOneHotOutput = wOneHotInputs[8];
                    8'b00010000: _rOneHotOutput = wOneHotInputs[16];
                    8'b00100000: _rOneHotOutput = wOneHotInputs[32];
                    8'b01000000: _rOneHotOutput = wOneHotInputs[64];
                    8'b10000000: _rOneHotOutput = wOneHotInputs[128];
                    default:_rOneHotOutput = wOneHotInputs[1];
                endcase // case (ONE_HOT_SELECT)
            end
        end 
    endgenerate
endmodule

module carry_select_adder (
  input [n-1:0] A,
  input [n-1:0] B,
  input CIN,
  output [n-1:0] S,
  output COUT
);

parameter n = 4; // number of bits in binary numbers A and B

wire [n:0] P, G, C; // partial sums and carries
wire [n-1:0] S0, S1; // two sets of partial sums
wire C0, C1; // two sets of carries

// precomputation block
ripple_carry_adder #(.n(n)) RCA0 (.A(A), .B(B), .CIN(CIN), .S(S0), .C(C0));
ripple_carry_adder #(.n(n)) RCA1 (.A(A), .B(B), .CIN(~CIN), .S(S1), .C(C1));

// carry-select block
assign P = (CIN) ? S1 : S0;
assign G = (CIN) ? C1 : C0;
ripple_carry_adder #(.n(n+1)) RCA2 (.A(P), .B(G), .CIN(CIN), .S(S), .C(COUT));

endmodule

// ripple-carry adder module
module ripple_carry_adder (
  input [n-1:0] A,
  input [n-1:0] B,
  input CIN,
  output [n-1:0] S,
  output COUT
);

parameter n = 4; // number of bits in binary numbers A and B

wire [n:0] C; // carries

assign {COUT, S} = A + B + CIN;

// generate carries
genvar i;
generate
  for (i = 0; i < n; i = i + 1) begin : GEN
    assign C[i+1] = (A[i] & B[i]) | (A[i] & C[i]) | (B[i] & C[i]);
  end
endgenerate

endmodule

module karnaugh_map(
  input wire A, B, C,
  output reg F
);

  // Minimized Boolean expression: F = A'B' + AB' + BC
  assign F = (~A & ~B) | (A & ~B) | (B & C);

endmodule

module top_module (
    input [31:0] a,
    input [31:0] b,
    input [1:0] shift,
    output reg [31:0] result
);

    // Instantiate float_mult module
    float_mult mult(a, b, mult_result);

    // Instantiate barrel_shifter module
    barrel_shifter shifter(mult_result, shift, shifted_result);

    // Instantiate final functional module
    final_module final(shifted_result, result);

endmodule

module float_mult (
    input [31:0] a,
    input [31:0] b,
    output reg [63:0] result
);

    // Perform floating-point multiplication
    always @* begin
        result = $bitstoreal(a) * $bitstoreal(b);
    end

endmodule

module barrel_shifter (
    input [63:0] input_data,
    input [1:0] shift,
    output reg [63:0] shifted_data
);

    // Perform barrel shifting
    always @* begin
        case (shift)
            2'b00: shifted_data = input_data; // no shift
            2'b01: shifted_data = input_data << 1; // shift left by 1 bit
            2'b10: shifted_data = input_data >> 1; // shift right by 1 bit
            2'b11: shifted_data = input_data >> 2; // shift right by 2 bits
        endcase
    end

endmodule

module final_module (
    input [63:0] input_data,
    output reg [31:0] output_data
);

    // Convert 64-bit floating-point number to 32-bit floating-point number
    always @* begin
        output_data = $realtobits($bitstoreal(input_data[63:32]));
    end

endmodule

module mux_4to1_case (
  input [3:0] a,
  input [3:0] b,
  input [3:0] c,
  input [3:0] d,
  input [1:0] sel,
  output reg [3:0] out
);

always @(*) begin
  case(sel)
    2'b00: out = a;
    2'b01: out = b;
    2'b10: out = c;
    2'b11: out = d;
    default: out = 4'b0000;
  endcase
end

endmodule

module mux4(
    input A0,
    input A1,
    input A2,
    input A3,
    input S0,
    input S1,
    output reg X
);

wire SA, SB, SC, SD, SE, SF, SG, SH;

assign SA = A0 & ~S0 & ~S1;
assign SB = A1 & S0 & ~S1;
assign SC = A2 & ~S0 & S1;
assign SD = A3 & S0 & S1;

assign SE = SA | SB;
assign SF = SC | SD;

assign SG = SE & ~S1;
assign SH = SF & S1;

assign X = SG | SH;

endmodule

module absolute_value (
    input [3:0] a,
    output reg [3:0] abs_val
);

    always @(*) begin
        if (a[3] == 1) begin
            abs_val = ~a + 1;
        end else begin
            abs_val = a;
        end
    end

endmodule

module mux_counter (
    input clk,
    input slowena,
    input reset,
    input sel_b1,
    input sel_b2,
    output reg [3:0] q
);

    wire [3:0] counter_out;
    wire [3:0] constant_value = 4'b0101;
    wire mux_sel;

    // Instantiate the 2-to-1 mux
    mux_2to1 mux_inst (
        .a(counter_out),
        .b(constant_value),
        .sel(mux_sel),
        .out(q)
    );

    // Instantiate the decade counter
    decade_counter counter_inst (
        .clk(clk),
        .reset(reset),
        .slowena(slowena),
        .out(counter_out)
    );

    // Control logic to select between counter output and constant value
    always @ (sel_b1 or sel_b2) begin
        if (sel_b1 == 1'b0 && sel_b2 == 1'b0) begin
            mux_sel = 1'b0;
        end else if (sel_b1 == 1'b0 && sel_b2 == 1'b1) begin
            mux_sel = 1'b1;
        end else if (sel_b1 == 1'b1 && sel_b2 == 1'b0) begin
            mux_sel = 1'b0;
        end else begin
            mux_sel = 1'b1;
        end
    end

endmodule

// 2-to-1 mux module
module mux_2to1 (
    input [3:0] a,
    input [3:0] b,
    input sel,
    output reg [3:0] out
);

    always @ (sel) begin
        if (sel == 1'b0) begin
            out = a;
        end else begin
            out = b;
        end
    end

endmodule

// Decade counter module
module decade_counter (
    input clk,
    input reset,
    input slowena,
    output reg [3:0] out
);

    reg [3:0] count = 4'b0000;

    always @ (posedge clk) begin
        if (reset == 1'b1) begin
            count <= 4'b0000;
        end else if (slowena == 1'b1) begin
            if (count == 4'b1001) begin
                count <= 4'b0000;
            end else begin
                count <= count + 1;
            end
        end
    end

    assign out = count;

endmodule

