     (.clk(clk),.rst(rst),.strobe(set_stb),.addr(set_addr),
      .in(set_data),.out(set_addr_user),.changed(addr_changed) );

   setting_reg #(.my_addr(BASE+1)) sr_1
     (.clk(clk),.rst(rst),.strobe(set_stb),.addr(set_addr),
      .in(set_data),.out(set_data_user),.changed(data_changed) );

   always @(posedge clk)
     if (rst|set_stb_user)
