module arithmetic_operations (
    input clk,
    input clk_en,
    input [31:0] dataa,
    input [31:0] datab,
    input [1:0] n,
    input reset,
    input start,
    output done,
    output reg [31:0] result
);

    wire add_sub;
    wire [5:0] counter_in;
    reg [5:0] counter_out;
    reg [31:0] dataa_regout;
    reg [31:0] datab_regout;
    wire done;
    wire [5:0] load_data;
    wire local_reset_n;
    wire [31:0] result_addsub;
    wire [31:0] result_div;
    wire [31:0] result_mult;

    always @(posedge clk or negedge local_reset_n) begin
        if (local_reset_n == 0) begin
            dataa_regout <= 0;
        end else if (clk_en) begin
            dataa_regout <= dataa;
        end
    end

    always @(posedge clk or negedge local_reset_n) begin
        if (local_reset_n == 0) begin
            datab_regout <= 0;
        end else if (clk_en) begin
            datab_regout <= datab;
        end
    end

    fpoint_hw_qsys_mult_single the_fp_mult (
        .aclr(reset),
        .clk_en(clk_en),
        .clock(clk),
        .dataa(dataa_regout),
        .datab(datab_regout),
        .result(result_mult)
    );

    fpoint_hw_qsys_addsub_single the_fp_addsub (
        .aclr(reset),
        .add_sub(add_sub),
        .clk_en(clk_en),
        .clock(clk),
        .dataa(dataa_regout),
        .datab(datab_regout),
        .result(result_addsub)
    );

    fpoint_hw_qsys_div_single the_fp_div (
        .aclr(reset),
        .clk_en(clk_en),
        .clock(clk),
        .dataa(dataa_regout),
        .datab(datab_regout),
        .result(result_div)
    );

    always @(posedge clk or negedge local_reset_n) begin
        if (local_reset_n == 0) begin
            counter_out <= 6'd33;
        end else if (clk_en) begin
            counter_out <= counter_in;
        end
    end

    assign counter_in = (start == 0) ? counter_out - 1'b1 : load_data;

    assign add_sub = n[0];
    assign local_reset_n = ~reset;
    assign done = clk_en & ~|counter_out & ~start;

    assign load_data = (n == 2) ? 8 : 10;

    always @(*) begin
        case (n)
            2'b00: result = result_mult;
            2'b01: result = result_addsub;
            2'b10: result = result_addsub;
            2'b11: result = result_div;
        endcase
    end

endmodule

