module PRNG (
  input reset,
  input clk,
  input [31:0] seed,
  output reg [31:0] rand,
  output reg valid
);

  reg [31:0] state;

  always @(posedge clk) begin
    if (reset) begin
      state <= seed;
      rand <= 0;
      valid <= 0;
    end else begin
      state <= state * 1664525 + 1013904223;
      rand <= state;
      valid <= 1;
    end
  end

endmodule

module top_module (
    input clk,
