);
    reg [7:0] prev_val;
    always @ (posedge clk) begin
        if (reset) begin
            prev_val <= 8'b0;
        end else begin
            out <= in ^ prev_val;
            prev_val <= in;
        end
    end
endmodule

module crc_module (
    input [63:0] data_in,
    input [7:0] poly,
    output reg [63:0] crc_out
);

    reg [63:0] crc_reg;
    integer i, j;

    always @(*) begin
        crc_reg = 64'hFFFFFFFFFFFFFFFF;
        for (i = 0; i < $size(data_in); i = i + 8) begin
            crc_reg = crc_reg << 8;
            crc_reg[63:56] = crc_reg[63:56] ^ data_in[i+7:i];
            for (j = 7; j >= 0; j = j - 1) begin
                if (crc_reg[63] == 1) begin
                    crc_reg = crc_reg ^ (poly << j);
                end
                crc_reg = crc_reg << 1;
            end
        end
        crc_out = crc_reg;
    end

endmodule

module top_module (
    input clk,
    input reset,
    input [15:0] in,
    output reg [15:0] anyedge,
    output reg [15:0] rising_edge,
    output reg [15:0] final_output
);

reg [15:0] prev_in;
reg [15:0] curr_in;
reg [15:0] next_in;

edge_detector edge_detect(clk, in, anyedge);

always @(posedge clk) begin
    prev_in <= curr_in;
    curr_in <= in;
    next_in <= {in[14:0], 1'b0};

    if (reset) begin
        rising_edge <= 16'b0;
    end else begin
        rising_edge <= (curr_in & ~prev_in) | (curr_in & ~next_in);
    end
end

assign final_output = anyedge | rising_edge;

endmodule

module edge_detector (
    input clk,
    input [15:0] in,
    output reg [15:0] anyedge
);

reg [15:0] prev_in;

always @(posedge clk) begin
    anyedge <= in ^ prev_in;
    prev_in <= in;
end

endmodule

module ForwardControl (
    input rst,
    input [RegAddrWidth-1:0] reg_data_1_addr_ID,
    input [RegAddrWidth-1:0] reg_data_2_addr_ID,

    input [RegAddrWidth-1:0] reg_data_1_addr_EX,
    input [RegAddrWidth-1:0] reg_data_2_addr_EX,
    input [RegAddrWidth-1:0] target_EX,
    input WriteReg_EX,

    input [RegAddrWidth-1:0] reg_data_2_addr_MEM,
    input [RegAddrWidth-1:0] target_MEM,
    input WriteReg_MEM,
    input MemOrAlu_MEM,
    input we_hi_MEM,
    input we_lo_MEM,

    input [RegAddrWidth-1:0] target_WB,
    input WriteReg_WB,
    input we_hi_WB,
    input we_lo_WB,

    output reg [1:0] FWA,
    output reg [1:0] FWB,
    output reg [1:0] FWhi,
    output reg [1:0] FWlo,
    output reg FWLS,
    output reg [1:0] FW_br_A,
    output reg [1:0] FW_br_B
);
    always @(*) begin : proc_forwarding
        if (rst == ~RstEnable) begin
            FWA <= 0;
            FWB <= 0;
            FWhi <= 0;
            FWlo <= 0;
            FWLS <= 0;
            FW_br_A <= 0;
            FW_br_B <= 0;
        end
        else begin
            // branch srcA
            if ((reg_data_1_addr_ID == target_EX) &&
                (WriteReg_EX == WriteEnable) &&
                (target_EX != 0)) begin
                FW_br_A <= FW_br_EX_ALU;
            end
            else if ((reg_data_1_addr_ID == target_MEM) &&
                    (WriteReg_MEM == WriteEnable) &&
                    (target_MEM != 0)) begin
                case (MemOrAlu_MEM)
                    ALU : FW_br_A <= FW_br_MEM_ALU;
                    Mem : FW_br_A <= FW_br_MEM_MEM;
                    default : FW_br_A <= FW_br_Origin;
                endcase
            end
            else begin
                FW_br_A <= FW_br_Origin;
            end

            // branch srcB
            if ((reg_data_2_addr_ID == target_EX) &&
                (WriteReg_EX == WriteEnable) &&
                (target_EX != 0)) begin
                    FW_br_B <= FW_br_EX_ALU;
            end
            else if ((reg_data_2_addr_ID == target_MEM) &&
                (WriteReg_MEM == WriteEnable) &&
                    (target_MEM != 0)) begin
                case (MemOrAlu_MEM)
                    ALU : FW_br_B <= FW_br_MEM_ALU;
                    Mem : FW_br_B <= FW_br_MEM_MEM;
                    default : FW_br_B <= FW_br_Origin;
                endcase
            end
            else begin
                FW_br_B <= FW_br_Origin;
            end

            // stage EX reg_data_1
            if ((reg_data_1_addr_EX == target_MEM) &&
                (WriteReg_MEM == WriteEnable) &&
                (target_MEM != 0)) begin
                FWA <= FWMem;
            end
            else if ((reg_data_1_addr_EX == target_WB) &&
                (WriteReg_WB == WriteEnable) &&
                (target_WB != 0)) begin
                FWA <= FWWB;
            end
            else begin
                FWA <= FWOrigin;
            end

            // stage EX reg_data_2
            if ((reg_data_2_addr_EX == target_MEM) &&
                (WriteReg_MEM == WriteEnable) &&
                (target_MEM != 0)) begin
                FWB <= FWMem;
            end
            else if ((reg_data_2_addr_EX == target_WB) &&
                (WriteReg_WB == WriteEnable) &&
                (target_WB != 0)) begin
                FWB <= FWWB;
            end
            else begin
                FWB <= FWOrigin;
            end

            // stage EX hi
            if (we_hi_MEM == WriteEnable) begin
                FWhi <= FWMem;
            end
            else if (we_hi_WB == WriteEnable) begin
                FWhi <= FWWB;
            end
            else begin
                FWhi <= FWOrigin;
            end

            // stage EX lo
            if (we_lo_MEM == WriteEnable) begin
                FWlo <= FWMem;
            end
            else if (we_lo_WB == WriteEnable) begin
                FWlo <= FWWB;
            end
            else begin
                FWlo <= FWOrigin;
            end

            // stage MEM SW
            if ((reg_data_2_addr_MEM == target_WB) &&
                (WriteReg_WB == WriteEnable) &&
                (target_WB != 0)) begin
                FWLS <= FW_LS_WB;
            end
            else begin
                FWLS <= FW_LS_Origin;
            end
        end
    end
endmodule

