module priority_encoder_decoder(
    input [2:0] sel,
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output reg [3:0] out
);

    reg [5:0] priority;

    always @(*) begin
        priority = {data5 > data4, data4 > data3, data3 > data2, data2 > data1, data1 > data0, 1'b0};
    end

    always @(sel or priority) begin
        case (sel)
            3'b000: out = priority[5:4];
            3'b001: out = priority[3:2];
            3'b010: out = priority[1:0];
            3'b011: out = 4'h0;
            3'b100: out = 4'h1;
            3'b101: out = 4'h2;
            3'b110: out = 4'h3;
            3'b111: out = 4'h4;
        endcase
    end

endmodule

module top_module( 
    input wire [15:0] in,
    input [2:0] sel, 
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo,
    output reg [15:0] final_out
);

    wire [3:0] mux_out;
    wire [7:0] barrel_out_hi, barrel_out_lo;

    priority_encoder_decoder mux(.sel(sel), .data0(data0), .data1(data1), .data2(data2), .data3(data3), .data4(data4), .data5(data5), .out(mux_out));
    barrel_shifter barrel(.in(in), .out_hi(barrel_out_hi), .out_lo(barrel_out_lo));

    always @(mux_out or barrel_out_hi or barrel_out_lo) begin
        final_out = {barrel_out_hi, barrel_out_lo};
        case (mux_out)
            4'h0: begin out_hi = data0; out_lo = 8'h00; end
            4'h1: begin out_hi = data1; out_lo = 8'h00; end
            4'h2: begin out_hi = data2; out_lo = 8'h00; end
            4'h3: begin out_hi = data3; out_lo = 8'h00; end
            4'h4: begin out_hi = data4; out_lo = 8'h00; end
            4'h5: begin out_hi = data5; out_lo = 8'h00; end
            4'h6: begin out_hi = barrel_out_hi; out_lo = barrel_out_lo; end
