module up_down_counter (
    input clk,
    input RST,
    input UP,
    input DOWN,
    input EN,
    output reg [2:0] counter_out
);

    always @(posedge clk or negedge RST) begin
        if (!RST) begin
            counter_out <= 3'b000;
        end else if (EN) begin
            if (UP) begin
                counter_out <= counter_out + 1;
            end else if (DOWN) begin
                counter_out <= counter_out - 1;
            end
        end
        if (counter_out == 3'b100 && UP) begin
            counter_out <= 3'b000;
        end else if (counter_out == 3'b000 && DOWN) begin
            counter_out <= 3'b100;
        end
    end

endmodule

