module adder_subtractor(A, B, C, S);
   input [3:0] A, B;
   input C;
   output [3:0] S;
   wire [3:0] A_inverted;
   wire [3:0] B_inverted;
   wire [3:0] difference;
   wire carry_out;
   full_adder adder_0(.A(A[0]), .B(B[0]), .C_in(C), .S(S[0]), .C_out(carry_out));
   full_adder adder_1(.A(A[1]), .B(B[1]), .C_in(carry_out), .S(S[1]), .C_out(carry_out));
   full_adder adder_2(.A(A[2]), .B(B[2]), .C_in(carry_out), .S(S[2]), .C_out(carry_out));
   full_adder adder_3(.A(A[3]), .B(B[3]), .C_in(carry_out), .S(S[3]), .C_out(carry_out));
   invert_4bit invert_A(.A(A), .S(A_inverted));
   invert_4bit invert_B(.A(B), .S(B_inverted));
   full_adder subtract_0(.A(A[0]), .B(B_inverted[0]), .C_in(C), .S(difference[0]), .C_out(carry_out));
   full_adder subtract_1(.A(A[1]), .B(B_inverted[1]), .C_in(carry_out), .S(difference[1]), .C_out(carry_out));
   full_adder subtract_2(.A(A[2]), .B(B_inverted[2]), .C_in(carry_out), .S(difference[2]), .C_out(carry_out));
   full_adder subtract_3(.A(A[3]), .B(B_inverted[3]), .C_in(carry_out), .S(difference[3]), .C_out(carry_out));
   assign S = (C == 1) ? difference : S;
endmodule

