module cycloneii_crcblock (
    input clk,
    input shiftnld,
    input ldsrc,
    input rst,
    output crcerror,
    output [15:0] regout
);

reg [15:0] shift_reg;
reg [15:0] crc_reg;
reg [3:0] crc_count;
wire [15:0] crc_expected;

assign crc_expected = 16'h800D;

assign crcerror = (crc_reg != crc_expected);

always @(posedge clk or posedge rst) begin
    if (rst) begin
        shift_reg <= 16'h0000;
        crc_reg <= 16'h0000;
        crc_count <= 4'h0;
    end else if (ldsrc) begin
        shift_reg <= 16'h0000;
        crc_reg <= 16'h0000;
        crc_count <= 4'h0;
    end else if (shiftnld) begin
        shift_reg <= {shift_reg[14:0], ldsrc};
        crc_reg <= crc_reg ^ shift_reg;
        crc_count <= crc_count + 1;
        if (crc_count == 4'hF) begin
            crc_reg <= crc_reg ^ crc_expected;
            crc_count <= 4'h0;
        end
    end
end

assign regout = crc_reg;

endmodule

