module reverse_bit_order(
    input [7:0] in,
    output [7:0] out
);

reg [7:0] shift_reg [0:7];
reg [2:0] stage;

always @ (posedge clk) begin
    case (stage)
        0: shift_reg[0] <= in;
        1: shift_reg[1] <= shift_reg[0] >> 1;
        2: shift_reg[2] <= shift_reg[1] >> 1;
        3: shift_reg[3] <= shift_reg[2] >> 1;
        4: shift_reg[4] <= shift_reg[3] >> 1;
        5: shift_reg[5] <= shift_reg[4] >> 1;
        6: shift_reg[6] <= shift_reg[5] >> 1;
        7: shift_reg[7] <= shift_reg[6] >> 1;
    endcase
    stage <= stage + 1;
end

assign out = shift_reg[7];

endmodule

