reg [15:0] threshold;

always @(posedge clk) begin
    if (rst) begin
        count <= 0;
        threshold <= 0;
        pulse <= 0;
    end else if (enable) begin
        count <= count + 1;
        if (count == threshold) begin
            pulse <= ~pulse;
            threshold <= freq - 1;
        end
    end
end

endmodule

module CIC_filter (
  input signed [R-1:0] in,
  input M,
  input N,
  output signed [S-1:0] out
);

parameter R = 16; // number of bits in input signal
parameter S = 16; // number of bits in output signal

// Comb filter
reg signed [R-1:0] comb_out;
always @ (posedge clk) begin
  if (count == M-1) begin
    comb_out <= in;
    count <= 0;
  end else begin
    comb_out <= 0;
    count <= count + 1;
  end
end

// Integrator stages
reg signed [R-1:0] int_out1;
reg signed [R-1:0] int_out2;
reg signed [R-1:0] int_out3;
// ...
always @ (posedge clk) begin
  int_out1 <= int_out1 + comb_out;
  int_out2 <= int_out2 + int_out1;
  int_out3 <= int_out3 + int_out2;
  // ...
end

// Second comb filter
reg signed [S-1:0] comb2_out;
always @ (posedge clk) begin
  if (count2 == M-1) begin
    comb2_out <= int_outN;
    count2 <= 0;
  end else begin
    comb2_out <= 0;
    count2 <= count2 + 1;
  end
end

// Output
reg signed [S-1:0] out_reg;
always @ (posedge clk) begin
  out_reg <= comb2_out;
end
assign out = out_reg;

