module PWM_Analyzer
   (PWM,
    AXI_LITE_GPIO_araddr,
    AXI_LITE_GPIO_arprot,
    AXI_LITE_GPIO_arready,
    AXI_LITE_GPIO_arvalid,
    AXI_LITE_GPIO_awaddr,
    AXI_LITE_GPIO_awprot,
    AXI_LITE_GPIO_awready,
    AXI_LITE_GPIO_awvalid,
    AXI_LITE_GPIO_bready,
    AXI_LITE_GPIO_bresp,
    AXI_LITE_GPIO_bvalid,
    AXI_LITE_GPIO_rdata,
    AXI_LITE_GPIO_rready,
    AXI_LITE_GPIO_rresp,
    AXI_LITE_GPIO_rvalid,
    AXI_LITE_GPIO_wdata,
    AXI_LITE_GPIO_wready,
    AXI_LITE_GPIO_wstrb,
    AXI_LITE_GPIO_wvalid,
    pulse_width,
    s00_axi_aclk,
    s00_axi_aresetn);

  parameter IDLE = 2'b00;
  parameter COUNTING = 2'b01;
  parameter OUTPUT = 2'b10;

  input PWM;
  input [3:0]AXI_LITE_GPIO_araddr;
  input [2:0]AXI_LITE_GPIO_arprot;
  output AXI_LITE_GPIO_arready;
  input AXI_LITE_GPIO_arvalid;
  input [3:0]AXI_LITE_GPIO_awaddr;
  input [2:0]AXI_LITE_GPIO_awprot;
  output AXI_LITE_GPIO_awready;
  input AXI_LITE_GPIO_awvalid;
  input AXI_LITE_GPIO_bready;
  output [1:0]AXI_LITE_GPIO_bresp;
  output AXI_LITE_GPIO_bvalid;
  output [31:0]AXI_LITE_GPIO_rdata;
  input AXI_LITE_GPIO_rready;
  output [1:0]AXI_LITE_GPIO_rresp;
  output AXI_LITE_GPIO_rvalid;
  input [31:0]AXI_LITE_GPIO_wdata;
  output AXI_LITE_GPIO_wready;
  input [3:0]AXI_LITE_GPIO_wstrb;
  input AXI_LITE_GPIO_wvalid;
  output reg [31:0]pulse_width;
  input s00_axi_aclk;
  input s00_axi_aresetn;

  reg [31:0] count;
  reg [31:0] threshold;
  reg [1:0] state;
  wire [31:0] count_out;

  assign AXI_LITE_GPIO_arready = 1;
  assign AXI_LITE_GPIO_awready = 1;
  assign AXI_LITE_GPIO_bresp = 2'b00;
  assign AXI_LITE_GPIO_rdata = pulse_width;
  assign AXI_LITE_GPIO_rresp = 2'b00;

  always @(posedge s00_axi_aclk) begin
    if (!s00_axi_aresetn) begin
      state <= IDLE;
      count <= 0;
      threshold <= 0;
      pulse_width <= 0;
    end else begin
      case (state)
        IDLE: begin
          if (PWM) begin
            state <= COUNTING;
            count <= 0;
          end
        end
        COUNTING: begin
          if (PWM) begin
            count <= count + 1;
          end else begin
            state <= OUTPUT;
            pulse_width <= count;
          end
        end
        OUTPUT: begin
          if (!PWM) begin
            state <= IDLE;
            count <= 0;
            if (pulse_width < threshold) begin
              pulse_width <= 0;
            end
          end
        end
      endcase
    end
  end

  always @(posedge s00_axi_aclk) begin
    if (!s00_axi_aresetn) begin
      threshold <= 0;
    end else begin
      if (AXI_LITE_GPIO_wvalid && AXI_LITE_GPIO_awvalid) begin
        case (AXI_LITE_GPIO_awaddr)
          4'h0: begin
            threshold <= AXI_LITE_GPIO_wdata;
          end
        endcase
      end
    end
  end

endmodule

