    .in({sum_out[15], abs_val.out[15], sum_out[14:0] > abs_val.out[14:0]}),
    .out(max_out)
);

endmodule

// Absolute value module using two's complement representation
module absolute_value (
    input signed [15:0] in,
    output reg [15:0] out
);

always @* begin
    if (in < 0) begin
        out = ~in + 1;
    end
    else begin
        out = in;
    end
end

endmodule

// Priority encoder module to determine max value
module priority_encoder (
    input [2:0] in,
    output reg [7:0] out
);

always @* begin
    case (in)
        3'b000: out = 8'b00000001;
        3'b001: out = 8'b00000010;
        3'b010: out = 8'b00000100;
        3'b011: out = 8'b00001000;
        3'b100: out = 8'b00010000;
        3'b101: out = 8'b00100000;
        3'b110: out = 8'b01000000;
        3'b111: out = 8'b10000000;
        default: out = 8'b00000000;
    endcase
end

endmodule

