module picorv32_pcpi_div (
			  input      clk, resetn,

			  input      pcpi_valid,
			  input [31:0]      pcpi_insn,
			  input [31:0]      pcpi_rs1,
			  input [31:0]      pcpi_rs2,
			  output reg      pcpi_wr,
			  output reg [31:0] pcpi_rd,
			  output reg      pcpi_wait,
			  output reg      pcpi_ready
			  );
   reg                          instr_div, instr_divu, instr_rem, instr_remu;
   wire                         instr_any_div_rem = |{instr_div, instr_divu, instr_rem, instr_remu};

   reg                          pcpi_wait_q;
   wire                         start = pcpi_wait && !pcpi_wait_q;

   always @(posedge clk) begin
      instr_div <= 0;
      instr_divu <= 0;
      instr_rem <= 0;
      instr_remu <= 0;

      if (resetn && pcpi_valid && !pcpi_ready && pcpi_insn[6:0] == 7'b0110011 && pcpi_insn[31:25] == 7'b0000001) begin
         case (pcpi_insn[14:12])
           3'b100: instr_div <= 1;
           3'b101: instr_divu <= 1;
           3'b110: instr_rem <= 1;
           3'b111: instr_remu <= 1;
         endcase
      end

      pcpi_wait <= instr_any_div_rem && resetn;
      pcpi_wait_q <= pcpi_wait && resetn;
   end

   reg [31:0] dividend;
   reg [62:0] divisor;
   reg [31:0] quotient;
   reg [31:0] quotient_msk;
   reg             running;
   reg             outsign;

   always @(posedge clk) begin
      pcpi_ready <= 0;
      pcpi_wr <= 0;
      pcpi_rd <= 'bx;

      if (!resetn) begin
         running <= 0;
      end else
         if (start) begin
            running <= 1;
            dividend <= (instr_div || instr_rem) && pcpi_rs1[31] ? -pcpi_rs1 : pcpi_rs1;
            divisor <= ((instr_div || instr_rem) && pcpi_rs2[31] ? -pcpi_rs2 : pcpi_rs2) << 31;
            outsign <= (instr_div && (pcpi_rs1[31] != pcpi_rs2[31]) && |pcpi_rs2) || (instr_rem && pcpi_rs1[31]);
            quotient <= 0;
            quotient_msk <= 1 << 31;
         end else
            if (!quotient_msk && running) begin
               running <= 0;
               pcpi_ready <= 1;
               pcpi_wr <= 1;
               if (instr_div || instr_divu) begin
                  if (divisor == 0) begin
                     pcpi_wait <= 1;
                  end else begin
                     pcpi_rd <= outsign ? -quotient : quotient;
                  end
               end else begin
                  pcpi_rd <= outsign ? -dividend : dividend;
               end
            end else begin
               if (divisor <= dividend) begin
                  dividend <= dividend - divisor;
                  quotient <= quotient | quotient_msk;
               end
               divisor <= divisor >> 1;
               quotient_msk <= quotient_msk >> 1;
            end
   end
endmodule

module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout
);

    wire [3:0] temp_sum;
    wire temp_carry;

    // Full adder for least significant bit
    full_adder fa0(A[0], B[0], Cin, temp_sum[0], temp_carry);

    // Full adder for second least significant bit
    full_adder fa1(A[1], B[1], temp_carry, temp_sum[1], temp_carry);

    // Full adder for third least significant bit
    full_adder fa2(A[2], B[2], temp_carry, temp_sum[2], temp_carry);

    // Full adder for most significant bit
    full_adder fa3(A[3], B[3], temp_carry, temp_sum[3], Cout);

    assign Sum = temp_sum;

endmodule

module full_adder (
    input A,
    input B,
    input Cin,
    output Sum,
    output Cout
);

    assign Sum = A ^ B ^ Cin;
    assign Cout = (A & B) | (Cin & (A ^ B));

endmodule

module rayinterface (raygroup, raygroupwe, raygroupid, enablenear, rgData, rgAddr, rgWE, rgAddrValid, rgDone, raydata, rayaddr, raywe, rgWriteEnable, rgReadData, globalreset, clk);

    input[1:0] raygroup; 
    input raygroupwe; 
    input[1:0] raygroupid; 
    input enablenear; 
    input[31:0] rgData; 
    input[3:0] rgAddr; 
