    reg[2:0] raywe;
    reg[31:0] rgReadData;

    reg[31:0] rgDatal; 
    reg[3:0] rgAddrl; 
    reg[2:0] rgWEl; 
    reg rgAddrValidl; 

    always @(posedge clk or posedge globalreset)
    begin
       if (globalreset == 1'b1)
       begin
          raydata <= 0;
          rayaddr <= 0;
          raywe <= 0;
          rgReadData <= 0;

          rgDone <= 1'b0 ; 
          rgDatal <= 0;
          rgAddrl <= 0;
          rgWEl <= 0;
          rgAddrValidl <= 1'b0 ; 
       end
       else
       begin
          rgDatal <= rgData ; // Latch interchip signals
          rgAddrl <= rgAddr ; // To Meet Timing
          rgWEl <= rgWE ; 

          rgAddrValidl <= rgAddrValid ; 
          if (rgAddrValidl == 1'b0)
          begin
             rgDone <= 1'b0 ; 
          end 
          if (raygroupwe == 1'b1)
          begin
             raydata[0] <= enablenear ; 
             raydata[31:1] <= 0;
             raywe <= 3'b111 ; 
             rayaddr <= {raygroupid, raygroup} ; 
          end
          else
          begin
            raywe <= 0;
          end
          if (rgWriteEnable == 1'b1)
          begin
            rgData <= raydata;
          end
          else if (rgAddrValidl == 1'b1 & rgDone == 1'b0)
          begin
            rgReadData <= rgDatal;
            rgDone <= 1'b1;
          end 
       end 
    end 
 endmodule

module sky130_fd_sc_ms__sedfxbp (
