module fsm_controller (
    input RST, // synchronous reset signal
    input CLK, // clock signal
    input STM, // start multiplication signal
    output reg ENpH, // enable Rp high
    output reg ENpL, // enable Rp low
    output reg ENa, // enable Ra
    output reg ENr, // enable Rr
    output reg SEL, // select multiplexer
    output reg EOM // end of multiplication
    );

    // define states
    parameter IDLE = 2'd0;
    parameter STATE1 = 2'd1;
    parameter STATE2 = 2'd2;
    parameter STATE3 = 2'd3;

    // define state register and next state logic
    reg [1:0] state, next_state;
    always @* begin
        case(state)
            IDLE: begin
                if (STM) next_state = STATE1;
                else next_state = IDLE;
                ENpH = 0;
                ENpL = 0;
                ENa = 0;
                ENr = 0;
                SEL = 0;
                EOM = 1;
            end
            STATE1: begin
                next_state = STATE2;
                ENpH = 1;
                ENpL = 0;
                ENa = 0;
                ENr = 0;
                SEL = 0;
                EOM = 0;
            end
            STATE2: begin
                next_state = STATE3;
                ENpH = 0;
                ENpL = 1;
                ENa = 1;
                ENr = 0;
                SEL = 0;
                EOM = 0;
            end
            STATE3: begin
                next_state = IDLE;
                ENpH = 0;
                ENpL = 0;
                ENa = 1;
                ENr = 1;
                SEL = 1;
                EOM = 0;
            end
        endcase
    end

    // define synchronous state update
    always @(posedge CLK, posedge RST) begin
        if (RST) state <= IDLE;
        else state <= next_state;
    end

endmodule

module float_adder (
    input [15:0] A,
    input [15:0] B,
    input [1:0] format,
    output [15:0] C
);

    // Define constants for IEEE 754 format
    parameter EXP_SIZE = 4;
    parameter MANT_SIZE = 11;
    parameter EXP_BIAS = 7;
    parameter EXP_MAX = (1 << EXP_SIZE) - 1;
    parameter EXP_MIN = 1 - EXP_BIAS;
    parameter MANT_MAX = (1 << MANT_SIZE) - 1;
    parameter MANT_MIN = 0;
    parameter SIGN_MASK = 16'h8000;
    parameter EXP_MASK = 16'h7C00;
    parameter MANT_MASK = 16'h03FF;
    parameter EXP_SHIFT = MANT_SIZE;
    parameter EXP_OFFSET = EXP_MAX - EXP_BIAS;
    parameter MANT_HIDDEN_BIT = 1 << MANT_SIZE;

    // Extract sign, exponent, and mantissa from A and B
    wire [15:0] A_sign = A & SIGN_MASK;
    wire [15:0] B_sign = B & SIGN_MASK;
    wire [15:0] A_exp = A & EXP_MASK;
    wire [15:0] B_exp = B & EXP_MASK;
    wire [15:0] A_mant = A & MANT_MASK;
    wire [15:0] B_mant = B & MANT_MASK;

    // Determine the larger exponent and shift the smaller mantissa
    wire [15:0] larger_exp;
    wire [15:0] smaller_exp;
    wire [MANT_SIZE+1:0] larger_mant;
    wire [MANT_SIZE+1:0] smaller_mant;
    wire [MANT_SIZE+1:0] shifted_mant;
    wire [MANT_SIZE+2:0] sum_mant;
    wire [1:0] sum_exp;
    wire [15:0] sum_sign;

    assign larger_exp = (A_exp > B_exp) ? A_exp : B_exp;
    assign smaller_exp = (A_exp > B_exp) ? B_exp : A_exp;
    assign larger_mant = (A_exp > B_exp) ? {1'b1, A_mant} : {1'b1, B_mant};
    assign smaller_mant = (A_exp > B_exp) ? {1'b0, B_mant} : {1'b0, A_mant};
    assign shifted_mant = larger_mant >> (larger_exp - smaller_exp);

    // Add the mantissas
    assign sum_mant = shifted_mant + smaller_mant;

    // Check for overflow and underflow
    assign sum_exp = larger_exp - EXP_OFFSET;
    assign sum_sign = (A_sign == B_sign) ? A_sign : ((sum_mant[MANT_SIZE+1] == 1) ? A_sign : B_sign);
    assign sum_mant = (sum_mant[MANT_SIZE+1] == 1) ? (sum_mant >> 1) : sum_mant;

    // Handle special cases
    assign C = (A_exp == EXP_MAX && A_mant != 0) ? A : ((B_exp == EXP_MAX && B_mant != 0) ? B : ((A_exp == EXP_MAX && B_exp == EXP_MAX) ? ((A_sign == B_sign) ? A : 16'h7FFF) : ((A_exp == 0 && A_mant == 0) ? B : ((B_exp == 0 && B_mant == 0) ? A : ((sum_exp == EXP_MIN && sum_mant[MANT_SIZE] == 0) ? ((sum_sign == A_sign) ? {sum_sign, 1'b0, sum_mant[MANT_SIZE-1:0]} : {sum_sign, 1'b1, MANT_MAX}) : ((sum_exp == EXP_MIN && sum_mant[MANT_SIZE] == 1) ? ((sum_sign == A_sign) ? {sum_sign, 1'b0, sum_mant[MANT_SIZE-1:0]} : {sum_sign, 1'b1, MANT_MIN}) : {sum_sign, sum_exp[EXP_SIZE-1:0], sum_mant[MANT_SIZE-1:0]}))))));

endmodule

module HMAC (
  input [len_msg-1:0] msg,
  input [len_key-1:0] key,
  input len_msg,
  input len_key,
  output [hash_size-1:0] hmac
);

parameter hash_size = 256; // hash size in bits

// Define the inner and outer padding keys
parameter block_size = 512; // block size in bits
parameter ipad = 'h36; // inner padding key
parameter opad = 'h5c; // outer padding key

// Define the intermediate signals
wire [block_size-1:0] padded_msg;
wire [block_size-1:0] inner_padded_key;
wire [block_size-1:0] outer_padded_key;
wire [hash_size-1:0] inner_hash;
wire [hash_size-1:0] outer_hash;

// Pad the message with zeros
assign padded_msg = {msg, {1'b0, (block_size - len_msg - 1)}};

// XOR the inner and outer padding keys with the secret key
assign inner_padded_key = key ^ { {ipad, (block_size - len_key)} };
assign outer_padded_key = key ^ { {opad, (block_size - len_key)} };

// Concatenate the padded key with the message
assign inner_concat = {inner_padded_key, padded_msg};
assign outer_concat = {outer_padded_key, inner_hash};

// Hash the concatenated values using the chosen hash function
hash_function hash1(inner_concat, inner_hash);
hash_function hash2(outer_concat, outer_hash);

// Concatenate the results of step 4 and step 5
assign hmac = {outer_hash, inner_hash};

endmodule

