module parity_generator(input [7:0] in, output [8:0] out);
    wire [3:0] sum;
    wire odd_parity;

    // 4-bit ripple carry adder
    ripple_adder adder(.a(in), .b(4'b0000), .sum(sum));

    // XOR gates for odd parity
    assign odd_parity = in[0] ^ in[1] ^ in[2] ^ in[3] ^ in[4] ^ in[5] ^ in[6] ^ in[7];

    // pipeline registers
    reg [7:0] in_reg;
    reg [3:0] sum_reg;
    reg odd_parity_reg;

    always @(posedge clk) begin
        in_reg <= in;
        sum_reg <= sum;
        odd_parity_reg <= odd_parity;
    end

    always @(posedge clk) begin
        out[0] <= in_reg[0];
        out[1] <= in_reg[1];
        out[2] <= in_reg[2];
        out[3] <= in_reg[3];
        out[4] <= in_reg[4];
        out[5] <= in_reg[5];
        out[6] <= in_reg[6];
        out[7] <= in_reg[7];
        out[8] <= odd_parity_reg;
    end

endmodule

