module ripple_adder(a, b, sum);
    input [3:0] a, b;
    output [3:0] sum;
    wire [3:0] carry;

    assign sum = a ^ b ^ carry;
    assign carry = (a & b) | (a & carry) | (b & carry);

endmodule

module usb_tx_data
(
  input c,
  input [7:0] d,
  input dv,
  output [7:0] sie_d,
  output sie_dv
);

  // Define the states
  localparam ST_IDLE   = 4'd0;
  localparam ST_SYNC   = 4'd1;
  localparam ST_DATA   = 4'd2;
  localparam ST_CRC_HI = 4'd3;
  localparam ST_CRC_LO = 4'd4;
  localparam ST_DONE   = 4'd5;

  // Define the control signals
  localparam SW=4, CW=5;
  reg [CW+SW-1:0] ctrl;
  wire [SW-1:0] state;
  wire [SW-1:0] next_state = ctrl[SW+CW-1:CW];

  // Register the state
  r #(SW) state_r
  (
    .c(c),
    .rst(1'b0),
    .en(1'b1),
    .d(next_state),
    .q(state)
  );

  // Delay the data by one clock cycle
  wire [7:0] d_d1;
  d1 #(8) d_d1_r
  (
    .c(c),
    .d(d),
    .q(d_d1)
  );

  // Compute the CRC16 checksum on the fly
  wire [15:0] crc;
  wire crc_dv;
  usb_crc16 usb_crc16_inst
  (
    .c(c),
    .d(d_d1),
    .dv(crc_dv),
    .rst(state == ST_IDLE),
    .crc(crc)
  );

  // Mux the data and the CRC16 checksum
  wire [1:0] sie_d_sel;
  wire [7:0] sie_mux_z;
  gmux #(.DWIDTH(8), .SELWIDTH(2)) sie_d_gmux
  (
    .d({crc, d_d1, 8'b10000000}),
    .sel(sie_d_sel),
    .z(sie_mux_z)
  );
  wire [7:0] sie_d_i = sie_dv_i ? sie_mux_z : 8'h0;

  // Define the state transitions
  always @* begin
    case (state)
      ST_IDLE:
        if (dv)
          ctrl = { ST_SYNC  , 5'b00_00_1 };
        else
          ctrl = { ST_IDLE  , 5'b00_00_0 };
      ST_SYNC:
        ctrl = { ST_DATA  , 5'b00_01_1 };
      ST_DATA:
        if (~dv)
          ctrl = { ST_CRC_LO, 5'b01_01_1 };
        else
          ctrl = { ST_DATA  , 5'b01_01_1 };
      ST_CRC_LO:
        ctrl = { ST_CRC_HI, 5'b00_10_1 };
      ST_CRC_HI:
        ctrl = { ST_DONE  , 5'b00_11_1 };
      ST_DONE:
        ctrl = { ST_IDLE  , 5'b00_11_0 };
      default:
        ctrl = { ST_IDLE  , 5'b00_00_0 };
    endcase
  end

  // Assign the control signals
  wire   sie_dv_i  = ctrl[0];
  assign sie_d_sel = ctrl[2:1];
  assign crc_dv    = ctrl[3];

  // Register the output data and data valid signals
  d1 #(8) sie_d1_d_r
  (
    .c(c),
    .d(sie_d_i),
    .q(sie_d)
  );
  d1 sie_d1_dv_r
  (
    .c(c),
    .d(sie_dv_i),
    .q(sie_dv)
  );

endmodule

// CRC16 module
module usb_crc16
(
  input c,
  input [7:0] d,
  input dv,
  input rst,
  output reg [15:0] crc
);

  // Define the polynomial
  localparam POLY = 16'h8005;

  // Define the state
  reg [15:0] state;

  // Define the next state
  always @* begin
    if (rst)
      state = 16'h0000;
    else if (dv)
      state = state ^ {d, 8'h00};
  end

  // Define the CRC16 calculation
  always @(posedge c) begin
    if (rst)
      crc <= 16'hFFFF;
    else if (dv)
      crc <= crc ^ {d, 8'h00};
    else
      crc <= crc ^ state;
    state <= {state[14:0], 1'b0} ^ (crc[15] ? POLY : 16'h0000);
  end

endmodule

