module LIN_transmitter(
  input clk,
  input rst,
  input [7:0] id,
  input [7:0] data,
  output tx
);

  reg [10:0] bit_counter;
  reg [7:0] checksum;
  reg [7:0] tx_data;
  reg sync_field;
  reg id_field;
  reg parity_field;
  reg data_field;
  reg [3:0] state;

  assign tx = tx_data;

  always @(posedge clk) begin
    if (rst) begin
      bit_counter <= 0;
      checksum <= 0;
      tx_data <= 1'b1;
      sync_field <= 1'b1;
      id_field <= 1'b0;
      parity_field <= 1'b0;
      data_field <= 1'b0;
      state <= 4'b0000;
    end else begin
      case (state)
        4'b0000: begin // Sync field
          if (bit_counter == 10) begin
            bit_counter <= 0;
            sync_field <= 1'b0;
            id_field <= 1'b1;
            state <= 4'b0001;
          end else begin
            bit_counter <= bit_counter + 1;
          end
        end
        4'b0001: begin // ID field
          if (bit_counter == 10) begin
            bit_counter <= 0;
            id_field <= 1'b0;
            parity_field <= 1'b1;
            state <= 4'b0010;
          end else begin
            tx_data <= id[bit_counter];
            checksum <= checksum ^ id[bit_counter];
            bit_counter <= bit_counter + 1;
          end
        end
        4'b0010: begin // Parity field
          if (bit_counter == 10) begin
            bit_counter <= 0;
            parity_field <= 1'b0;
            data_field <= 1'b1;
            state <= 4'b0011;
          end else begin
            tx_data <= parity_field;
            bit_counter <= bit_counter + 1;
          end
        end
        4'b0011: begin // Data field
          if (bit_counter == 10) begin
            bit_counter <= 0;
            data_field <= 1'b0;
            state <= 4'b0000;
          end else begin
            tx_data <= data[bit_counter];
            checksum <= checksum ^ data[bit_counter];
            bit_counter <= bit_counter + 1;
          end
        end
      endcase
    end
  end

endmodule

module LIN_receiver(
  input clk,
  input rst,
  input rx,
  output [7:0] id,
  output [7:0] data
);

  reg [10:0] bit_counter;
  reg [7:0] checksum;
  reg [7:0] rx_data;
  reg sync_field;
  reg id_field;
  reg parity_field;
  reg data_field;
  reg [3:0] state;

  always @(posedge clk) begin
    if (rst) begin
      bit_counter <= 0;
      checksum <= 0;
      rx_data <= 0;
      sync_field <= 1'b0;
      id_field <= 1'b0;
      parity_field <= 1'b0;
      data_field <= 1'b0;
      state <= 4'b0000;
    end else begin
      case (state)
        4'b0000: begin // Sync field
          if (rx == 1'b0) begin
            bit_counter <= 0;
            sync_field <= 1'b1;
            state <= 4'b0001;
          end
        end
        4'b0001: begin // ID field
          if (bit_counter == 10) begin
            bit_counter <= 0;
            id_field <= 1'b1;
            state <= 4'b0010;
          end else begin
            rx_data <= {rx_data[6:0], rx};
            bit_counter <= bit_counter + 1;
          end
        end
        4'b0010: begin // Parity field
          if (bit_counter == 10) begin
            bit_counter <= 0;
            parity_field <= 1'b1;
            state <= 4'b0011;
          end else begin
            rx_data <= {rx_data[6:0], rx};
            bit_counter <= bit_counter + 1;
          end
        end
        4'b0011: begin // Data field
          if (bit_counter == 10) begin
            bit_counter <= 0;
            data_field <= 1'b1;
            state <= 4'b0000;
            if (checksum == rx_data) begin
              id <= rx_data[9:2];
              data <= rx_data[1:0];
            end
          end else begin
            rx_data <= {rx_data[6:0], rx};
            checksum <= checksum ^ rx;
            bit_counter <= bit_counter + 1;
          end
        end
      endcase
    end
  end

endmodule

module sub(
  input [23:0] in,
  output reg out1,
  output reg [4:0] out2
);

  always @(*) begin
    out1 = in[0] ^ in[1] ^ in[2] ^ in[3] ^ in[4] ^ in[5] ^ in[6] ^ in[7] ^ in[8] ^ in[9] ^ in[10] ^ in[11] ^ in[12] ^ in[13] ^ in[14] ^ in[15] ^ in[16] ^ in[17] ^ in[18] ^ in[19] ^ in[20] ^ in[21] ^ in[22] ^ in[23];
    out2 = in[0] ^ in[2] ^ in[4] ^ in[6] ^ in[8] ^ in[10] ^ in[12] ^ in[14] ^ in[16] ^ in[18] ^ in[20] ^ in[22] ? 0 : 1;
    out2 = out2 | (in[1] ^ in[3] ^ in[5] ^ in[7] ^ in[9] ^ in[11] ^ in[13] ^ in[15] ^ in[17] ^ in[19] ^ in[21] ^ in[23] ? 0 : 1) << 1;
    out2 = out2 | (in[0] ^ in[1] ^ in[2] ^ in[3] ^ in[8] ^ in[9] ^ in[10] ^ in[11] ^ in[16] ^ in[17] ^ in[18] ^ in[19] ^ in[20] ^ in[21] ^ in[22] ^ in[23] ? 0 : 1) << 2;
    out2 = out2 | (in[4] ^ in[5] ^ in[6] ^ in[7] ^ in[12] ^ in[13] ^ in[14] ^ in[15] ^ in[20] ^ in[21] ^ in[22] ^ in[23] ? 0 : 1) << 3;
    out2 = out2 | (in[0] ^ in[1] ^ in[4] ^ in[5] ^ in[8] ^ in[9] ^ in[12] ^ in[13] ^ in[16] ^ in[17] ^ in[20] ^ in[21] ? 0 : 1) << 4;
  end

endmodule

module main (
  input clk,
  output reg out1,
  output reg [4:0] out2
);

  integer cyc; 
  reg [63:0] crc;
  reg [63:0] sum;

  sub sub (.in(crc[23:0]), .out1(out1), .out2(out2));

  always @ (posedge clk) begin
    cyc <= cyc + 1;
    crc <= {crc[62:0], crc[63] ^ crc[2] ^ crc[0]};
    sum <= {sum[62:0], sum[63]^sum[2]^sum[0]} ^ {58'h0,out1,out2};
    if (cyc==0) begin
      // Setup
      crc <= 64'h00000000_00000097;
      sum <= 64'h0;
    end
    else if (cyc==90) begin
      if (sum !== 64'hf0afc2bfa78277c5) $stop;
    end
    else if (cyc==99) begin
      $write("*-* All Finished *-*\n");
      $finish;
    end
  end

endmodule

module uart(
    input clk,
    input rst_n,
    input rs232_rx,
    input [2:0] uart_ctl,
    output reg rs232_tx,
    output reg data_ok
);

parameter BAUD_RATE = 9600;
parameter DATA_BITS = 7;
parameter PARITY = 1;
parameter STOP_BITS = 1;

reg [7:0] data_in;
reg [7:0] data_out;
reg data_valid;
reg data_in_sign;
reg data_out_sign;

reg [15:0] baud_counter;
reg [3:0] bit_counter;
reg parity_bit;
reg stop_bit;

assign rs232_tx = data_out[0];
assign data_ok = data_valid;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        baud_counter <= 16'h0000;
        bit_counter <= 4'd0;
        data_in <= 8'd0;
        data_out <= 8'd0;
        data_valid <= 1'b0;
        data_in_sign <= 1'b0;
        data_out_sign <= 1'b0;
        parity_bit <= 1'b0;
        stop_bit <= 1'b0;
    end else begin
        if (uart_ctl == 3'b001) begin // receive mode
            if (baud_counter == 16'h0000) begin
                baud_counter <= 16'hffff;
                if (rs232_rx == 1'b0) begin
                    bit_counter <= 4'd1;
                    data_in <= 8'd0;
                    data_in_sign <= 1'b0;
                end
            end else if (baud_counter[15] == 1'b1) begin
                baud_counter <= baud_counter + (50000000 / BAUD_RATE);
                if (bit_counter < DATA_BITS) begin
                    data_in[bit_counter] <= rs232_rx;
                    data_in_sign <= data_in_sign ^ rs232_rx;
                    bit_counter <= bit_counter + 1;
                end else if (bit_counter == DATA_BITS) begin
                    parity_bit <= PARITY ? ~data_in_sign : data_in_sign;
                    bit_counter <= bit_counter + 1;
                end else if (bit_counter == DATA_BITS + 1) begin
                    if (rs232_rx == parity_bit) begin
                        bit_counter <= bit_counter + 1;
                    end else begin
                        bit_counter <= 4'd0;
                    end
                end else if (bit_counter == DATA_BITS + 2) begin
                    if (rs232_rx == 1'b1) begin
                        stop_bit <= 1'b1;
                    end else begin
                        bit_counter <= 4'd0;
                    end
                end else if (bit_counter == DATA_BITS + 3) begin
                    if (rs232_rx == 1'b1) begin
                        data_valid <= 1'b1;
                        bit_counter <= 4'd0;
                    end else begin
                        bit_counter <= 4'd0;
                    end
                end
            end else begin
                baud_counter <= baud_counter - 1;
            end
        end else if (uart_ctl == 3'b010) begin // transmit mode
            if (baud_counter == 16'h0000) begin
                baud_counter <= 16'hffff;
                if (bit_counter == 0) begin
                    data_out <= 8'd0;
                    data_out_sign <= 1'b0;
                    data_valid <= 1'b0;
                    if (!rs232_rx) begin
                        bit_counter <= 4'd1;
                    end
                end else if (bit_counter <= DATA_BITS) begin
                    data_out[bit_counter - 1] <= data_in[bit_counter - 1];
                    data_out_sign <= data_out_sign ^ data_in[bit_counter - 1];
                    bit_counter <= bit_counter + 1;
                end else if (bit_counter == DATA_BITS + 1) begin
                    parity_bit <= PARITY ? ~data_out_sign : data_out_sign;
                    bit_counter <= bit_counter + 1;
                end else if (bit_counter == DATA_BITS + 2) begin
                    data_out[DATA_BITS] <= parity_bit;
                    bit_counter <= bit_counter + 1;
                end else if (bit_counter == DATA_BITS + 3) begin
                    data_out[DATA_BITS + 1] <= 1'b1;
                    data_valid <= 1'b1;
                    bit_counter <= bit_counter + 1;
                end else if (bit_counter == DATA_BITS + 4) begin
                    if (rs232_rx) begin
                        bit_counter <= 4'd0;
                    end
                end
            end else if (baud_counter[15] == 1'b1) begin
                baud_counter <= baud_counter + (50000000 / BAUD_RATE);
            end else begin
                baud_counter <= baud_counter - 1;
            end
        end
    end
end

endmodule

module combinational_logic (
    X   ,
    A1  ,
    A2  ,
    B1_N
);

    output X   ;
    input  A1  ;
    input  A2  ;
    input  B1_N;

    assign X = (~A1 & A2 & B1_N) | (A1 & ~A2 & B1_N) | (A1 & A2 & ~B1_N);

endmodule

module arithmetic_calculator (
  input clk,
  input reset,
  input signed [31:0] A,
  input signed [31:0] B,
  output reg signed [31:0] Add,
  output reg signed [31:0] Sub,
  output reg signed [31:0] Mul,
  output reg signed [31:0] Div
);

  always @(posedge clk) begin
    if (reset) begin
      Add <= 0;
      Sub <= 0;
      Mul <= 0;
      Div <= 0;
    end else begin
      // Addition
      if ((A > 0) && (B > 0) && (A > (2147483647 - B))) begin
        $display("Overflow occurred during addition");
        Add <= 0;
      end else if ((A < 0) && (B < 0) && (A < (-2147483647 - B))) begin
        $display("Underflow occurred during addition");
        Add <= 0;
      end else begin
        Add <= A + B;
      end

      // Subtraction
      if ((A > 0) && (B < 0) && (A > (2147483647 + B))) begin
        $display("Overflow occurred during subtraction");
        Sub <= 0;
      end else if ((A < 0) && (B > 0) && (A < (-2147483647 + B))) begin
        $display("Underflow occurred during subtraction");
        Sub <= 0;
      end else begin
        Sub <= A - B;
      end

      // Multiplication
      if ((A > 0) && (B > 0) && (A > (2147483647 / B))) begin
        $display("Overflow occurred during multiplication");
        Mul <= 0;
      end else if ((A > 0) && (B < 0) && (B < (-2147483647 / A))) begin
        $display("Underflow occurred during multiplication");
        Mul <= 0;
      end else if ((A < 0) && (B > 0) && (A < (-2147483647 / B))) begin
        $display("Underflow occurred during multiplication");
        Mul <= 0;
      end else if ((A < 0) && (B < 0) && (A < (2147483647 / B))) begin
        $display("Overflow occurred during multiplication");
        Mul <= 0;
      end else begin
        Mul <= A * B;
      end

      // Division
      if (B == 0) begin
        $display("Divide-by-zero error occurred");
        Div <= 0;
      end else if ((A == -2147483648) && (B == -1)) begin
        $display("Overflow occurred during division");
        Div <= 0;
      end else begin
        Div <= A / B;
      end
    end
  end

endmodule

module arbiter(
    input rst,
    input clk,
    input [7:0] push,
    input [63:0] d,
    output [7:0] full,
    output [7:0] almost_full,
    output [7:0] q,
    output valid,
    input stall
);

    parameter WIDTH = 8;
    parameter PORTS = 8;
    parameter FIFO_DEPTH = 32;
    parameter ALMOST_FULL_THRESHOLD = 1;
    parameter PORTS_ADDR_WIDTH = $clog2(PORTS);
    parameter FIFO_DEPTH_ADDR_WIDTH = $clog2(FIFO_DEPTH);

    wire [7:0] almost_empty;
    reg [7:0] pop;
    wire [7:0] empty;
    wire [FIFO_DEPTH_ADDR_WIDTH:0] count[0:PORTS-1];
    wire [WIDTH-1:0] fifo_q[0:PORTS-1];
    reg [WIDTH-1:0] fifo_d[0:PORTS-1];
    integer i, j;
    always @* begin
        for(i = 0; i < PORTS; i = i + 1) begin
            for(j = 0; j < WIDTH; j = j + 1) begin
                fifo_d[i][j] = d[(PORTS - i - 1) * WIDTH + j];
            end
        end
    end

    genvar lane;
    generate
        for(lane = 0; lane < PORTS; lane = lane + 1) begin: fifo_generate
            std_fifo #(
                .DEPTH(FIFO_DEPTH),
                .WIDTH(WIDTH),
                .ALMOST_FULL_COUNT(ALMOST_FULL_THRESHOLD)
            ) fifo(
                .rst(rst),
                .clk(clk),
                .push(push[lane]),
                .pop(pop[lane]),
                .d(fifo_d[lane]),
                .q(fifo_q[lane]),
                .full(full[lane]),
                .empty(empty[lane]),
                .count(count[lane]),
                .almost_empty(almost_empty[lane]),
                .almost_full(almost_full[lane])
            );
        end
    endgenerate

    reg [PORTS_ADDR_WIDTH-1:0] processing, next_processing, prev_processing;
    always @* begin
        pop = 0;
        next_processing = processing;
        if(!empty[processing] && !stall)
            pop[processing] = 1;
        if(almost_empty[processing])
            next_processing = processing + 1;
        if(next_processing == PORTS)
            next_processing = 0;
        if(rst)
            next_processing = 0;
    end

    always @(posedge clk) begin
        processing <= next_processing;
        prev_processing <= processing;
    end

    reg r_valid, r_valid2;
    reg [WIDTH-1:0] r_q;
    always @(posedge clk) begin
        r_q = fifo_q[prev_processing];
        r_valid <= |pop;
        r_valid2 <= r_valid;
    end

    assign q = r_q;
    assign valid = r_valid2;

endmodule

module input_module (
    VPWR,
    VGND,
    VPB,
    VNB
);

    // Module ports
    input VPWR;
    input VGND;
    input VPB;
    input VNB;

    // Internal signals
    wire VPB_valid;
    wire VNB_valid;

    // Ensure VPWR and VGND are always present
    assign VPWR = 1;
    assign VGND = 0;

    // Ensure VPB and VNB are never both high
    assign VPB_valid = (VPB == 1) && (VNB == 0);
    assign VNB_valid = (VNB == 1) && (VPB == 0);

    // If VPB is high, VNB should be low, and vice versa
    assign VPB = VPB_valid;
    assign VNB = VNB_valid;

    // If VPB and VNB are both low, ensure the voltage between them is within a certain range
    assign {VPB, VNB} = ({VPB, VNB} >= 2'b01) ? {VPB, VNB} : 2'b01;
    assign {VPB, VNB} = ({VPB, VNB} <= 2'b10) ? {VPB, VNB} : 2'b10;

endmodule

module priority_encoder_half_adder (
    input [3:0] in,
    input a, b,
    output reg [1:0] pos,
    output reg cout,
    output reg sum,
    output reg [3:0] final_output
);

    // Priority Encoder
    always @(*) begin
        case(in)
            4'b0001: pos = 2'b00;
            4'b0010: pos = 2'b01;
            4'b0100: pos = 2'b10;
            4'b1000: pos = 2'b11;
            default: pos = 2'b00;
        endcase
    end

    // Half Adder
    always @(*) begin
        case({a,b})
            2'b00: begin
                sum = 1'b0;
                cout = 1'b0;
            end
            2'b01: begin
                sum = 1'b1;
                cout = 1'b0;
            end
            2'b10: begin
                sum = 1'b1;
                cout = 1'b0;
            end
            2'b11: begin
                sum = 1'b0;
                cout = 1'b1;
            end
        endcase
    end

    // Final Output
    always @(*) begin
        if(pos[0] == 1'b1) begin
            final_output = in + {1'b0, a, b};
        end
        else begin
            final_output = {1'b0, 1'b0, 1'b0, cout};
        end
    end

endmodule

module priority_mux_shift_reg (
    input clk,
    input rst_n,
    input [1:0] sel, 
    input [7:0] data0,
    input [7:0] data1,
    input [7:0] data2,
    input [7:0] data3,
    input [7:0] data4,
    input [7:0] data5,
    output reg [7:0] mux_out,
    output reg [15:0] final_out
);

reg [7:0] shift_reg;
reg [2:0] shift_cnt;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        shift_reg <= 8'b00000001;
        shift_cnt <= 3'b000;
    end else begin
        shift_reg <= {shift_reg[6:0], shift_reg[7]};
        shift_cnt <= shift_cnt + 1;
        if (shift_cnt == 3) begin
            shift_cnt <= 3'b000;
        end
    end
end

always @(sel or data0 or data1 or data2 or data3 or data4 or data5) begin
    case (sel)
        2'b00: mux_out <= data0;
        2'b01: mux_out <= data1;
        2'b10: mux_out <= data2;
        2'b11: mux_out <= data3;
        default: mux_out <= 8'b0;
    endcase
end

always @(mux_out or shift_reg) begin
    final_out <= {mux_out, shift_reg};
end

endmodule

module sky130_fd_sc_lp__nand2b_lp (
    Y   ,
    A_N ,
    B   ,
    VPWR,
    VGND,
    VPB ,
    VNB
);

    output Y   ;
    input  A_N ;
    input  B   ;
    input  VPWR;
    input  VGND;
    input  VPB ;
    input  VNB ;

    // PMOS transistor network
    nmos n1(Y, A_N, VNB, VGND, VPWR);
    nmos n2(Y, B, VNB, VGND, VPWR);
    pmos p1(Y, A_N, VPB, VPWR, VGND);
    pmos p2(Y, B, VPB, VPWR, VGND);

endmodule

module pmos (out, in1, bulk, vdd, gnd);
    output out;
    input in1;
    input bulk;
    input vdd;
    input gnd;
    assign out = in1 & (bulk | gnd | vdd);
endmodule

module nmos (out, in1, bulk, vdd, gnd);
    output out;
    input in1;
    input bulk;
    input vdd;
    input gnd;
    assign out = ~in1 & ~(bulk | gnd | vdd);
endmodule

module bitwise_or(
    input clock,
    input [`BITS-1:0] a_in,
    input [`BITS-1:0] b_in,
    output [`BITS-1:0] out
);

reg [`BITS-1:0] out;

always @(posedge clock) begin
    out <= a_in | b_in;
end

endmodule

module ripple_carry_adder(
  input [3:0] A,
  input [3:0] B,
  input Cin,
  output [3:0] Sum,
  output Cout
);

  wire [3:0] carry;
  wire [3:0] sum;

  full_adder fa0(A[0], B[0], Cin, sum[0], carry[0]);
  full_adder fa1(A[1], B[1], carry[0], sum[1], carry[1]);
  full_adder fa2(A[2], B[2], carry[1], sum[2], carry[2]);
  full_adder fa3(A[3], B[3], carry[2], sum[3], Cout);

  assign Sum = sum;

endmodule

module full_adder(
  input a,
  input b,
  input cin,
  output sum,
  output cout
);

  assign sum = a ^ b ^ cin;
  assign cout = (a & b) | (a & cin) | (b & cin);

endmodule

module testbench();

  reg [3:0] A;
  reg [3:0] B;
  reg Cin;
  wire [3:0] Sum;
  wire Cout;

  ripple_carry_adder rca(A, B, Cin, Sum, Cout);

  initial begin
    A = 4'b0000;
    B = 4'b0000;
    Cin = 0;
    #1;
    if (Sum !== 4'b0000 || Cout !== 0) begin
      $display("FAILED 1 - Sum: %b, Cout: %b", Sum, Cout);
      $finish;
    end
    A = 4'b0001;
    B = 4'b0001;
    Cin = 0;
    #1;
    if (Sum !== 4'b0010 || Cout !== 0) begin
      $display("FAILED 2 - Sum: %b, Cout: %b", Sum, Cout);
      $finish;
    end
    A = 4'b1111;
    B = 4'b1111;
    Cin = 1;
    #1;
    if (Sum !== 4'b1111 || Cout !== 1) begin
      $display("FAILED 3 - Sum: %b, Cout: %b", Sum, Cout);
      $finish;
    end
    $display("PASSED");
    $finish;
  end

endmodule

module pwm_generator(
    input clk,
    input [6:0] duty_cycle, // 7-bit input for duty cycle percentage (0-100)
    input [15:0] period, // 16-bit input for period in clock cycles
    output reg pwm_out
);

reg [15:0] count; // Counter to track the current position within the period
reg [15:0] high_time; // Counter to track the high time of the PWM signal
reg [6:0] duty_cycle_count; // Counter to track the duty cycle percentage

always @(posedge clk) begin
    // Increment the count
    count <= count + 1;

    // If the count has reached the period, reset it and the high time
    if (count == period) begin
        count <= 0;
        high_time <= 0;
    end

    // If the high time has reached the duty cycle percentage, set the output high
    if (high_time == ((duty_cycle * period) / 100)) begin
        pwm_out <= 1;
    end

    // If the duty cycle count has reached 100, reset it and the high time
    if (duty_cycle_count == 100) begin
        duty_cycle_count <= 0;
        high_time <= 0;
    end

    // If the output is currently high and the high time has reached the end of the period, set the output low
    if (pwm_out && (count == period)) begin
        pwm_out <= 0;
    end

    // If the output is currently high and the high time has reached the duty cycle percentage, increment the duty cycle count
    if (pwm_out && (high_time == ((duty_cycle * period) / 100))) begin
        duty_cycle_count <= duty_cycle_count + 1;
    end

    // If the output is currently low and the high time has not yet reached the duty cycle percentage, increment the high time
    if (!pwm_out && (high_time < ((duty_cycle * period) / 100))) begin
        high_time <= high_time + 1;
    end
end

endmodule

module crc_module (/*AUTOARG*/
   // Inputs
   clk
   );

   input clk;

   integer cyc = 0;
   reg [63:0] crc = 64'h5aef0c8d_d70a4497;

   wire [65:0]	outData;		// From fifo of fifo.v
   wire [15:0] 	inData = crc[15:0];
   wire [1:0] 	inWordPtr = crc[17:16];
   wire		wrEn = crc[20];
   wire [1:0] 	wrPtr = crc[33:32];
   wire [1:0] 	rdPtr = crc[34:33];

   fifo fifo (
	      // Outputs
	      .outData		(outData[65:0]),
	      // Inputs
	      .clk		(clk),
	      .inWordPtr	(inWordPtr[1:0]),
	      .inData		(inData[15:0]),
	      .rdPtr		(rdPtr),
	      .wrPtr		(wrPtr),
	      .wrEn		(wrEn));

   always @ (posedge clk) begin
      cyc <= cyc + 1;
      crc <= {crc[62:0], crc[63] ^ crc[2] ^ crc[0]};
