        q <= 4'b0000;
        pause_count <= 0;
    end else begin
        if (slowena) begin
            next_johnson_q[3] <= johnson_q[2];
            next_johnson_q[2] <= johnson_q[1];
            next_johnson_q[1] <= johnson_q[0];
            next_johnson_q[0] <= ~johnson_q[3] & ~johnson_q[2] & ~johnson_q[1] & ~johnson_q[0];
            johnson_q <= next_johnson_q;
        end

        if (pause) begin
            pause_count <= 1;
        end else if (pause_count > 0) begin
            pause_count <= pause_count + 1;
        end else begin
            q <= johnson_q;
        end
    end
end

endmodule

module top_module (
    input clk,
    input slowena,
    input reset,
    output [3:0] q
);

wire pause;
reg slow_clk;

assign pause = q == 4'b1001;

always @ (posedge clk) begin
    if (reset) begin
        slow_clk <= 1'b0;
    end else begin
        if (slowena) begin
            if (slow_clk) begin
                slow_clk <= 1'b0;
            end else begin
                slow_clk <= 1'b1;
            end
        end
    end
end

decade_counter counter (
    .clk(clk),
    .slowena(slow_clk),
    .reset(reset),
    .pause(pause),
    .q(q)
);

endmodule

module up_down_counter (
    input clk,
    input reset,      // Synchronous active-high reset
    input up_down,    // Control signal to increment or decrement
    output [3:0] q);

    reg [3:0] count;

    always @(posedge clk) begin
        if (reset) begin
            count <= 4'b0;
        end else if (up_down) begin
            count <= (count == 4'b1111) ? 4'b0 : count + 1;
        end else begin
            count <= (count == 4'b0000) ? 4'b1111 : count - 1;
        end
    end

    assign q = count;

endmodule

module transmission_gate_full_adder (
    input a,
    input b,
    input cin,
    output reg sum,
    output reg cout
);

wire t1, t2, t3, t4, t5, t6;

assign t1 = a & b;
assign t2 = a ^ b;
assign t3 = t2 & cin;
assign t4 = t1 | t3;
assign t5 = a & cin;
assign t6 = b & cin;

assign sum = t2 ^ cin;
assign cout = t6 | t5 | t3;

endmodule

module pwm (
    input clk,
    input enable,
    input [31:0] clk_period,
    input [31:0] pwm_period,
    output out
);

    reg clk_out = 1'b0;
    reg [31:0] counter = 32'b0;

    always @(posedge clk) begin
        if (enable == 1'b1) begin
            if (counter < pwm_period) begin
                clk_out <= 1'b1;
                counter <= counter + 32'b1;
            end else begin
                if (counter < (clk_period - 1)) begin
                    clk_out <= 1'b0;
                    counter <= counter + 32'b1;
                end else begin
                    clk_out <= 1'b0;
                    counter <= 32'b0;
                end
            end
        end else begin
            if ((counter > 0) && (counter < pwm_period)) begin
                clk_out <= 1'b1;
                counter <= counter + 32'b1;
            end else begin
                clk_out <= 1'b0;
                counter <= 32'b0;
            end
        end
    end

    assign out = clk_out;

endmodule

module magnitude_comparator_4bit (
    input [3:0] A,
    input [3:0] B,
    output EQ,
    output GT,
    output LT
);

reg [3:0] A_reg, B_reg;
reg [2:0] stage;
wire [3:0] A_next, B_next;
wire EQ_next, GT_next, LT_next;

assign EQ = (stage == 2) ? EQ_next : 1'b0;
assign GT = (stage == 2) ? GT_next : 1'b0;
assign LT = (stage == 2) ? LT_next : 1'b0;

always @(posedge clk) begin
    case(stage)
        0: begin
            A_reg <= A;
            B_reg <= B;
            stage <= 1;
        end
        1: begin
            A_reg <= A_next;
            B_reg <= B_next;
            stage <= 2;
        end
        2: begin
            stage <= 0;
        end
    endcase
end

assign A_next = (A_reg > B_reg) ? A_reg : B_reg;
assign B_next = (A_reg > B_reg) ? B_reg : A_reg;
assign EQ_next = (A_next == B_next) ? 1'b1 : 1'b0;
assign GT_next = (A_next > B_next) ? 1'b1 : 1'b0;
assign LT_next = (A_next < B_next) ? 1'b1 : 1'b0;

endmodule

module MMU_MATCH (
    input USER,
    input READ,
    input WRITE,
    input RMW,
    input [2:0] MCR_FLAGS,
    input [31:0] MVALID,
    input [31:12] VADR_R,
    input [31:16] MMU_VA,
    input [1:0] IVAR,
    output VIRTUELL,
    output MMU_HIT,
    output [31:0] UPDATE,
    output reg PROT_ERROR,
    output CI,
    output SEL_PTB1
);

reg [15:0] maske;
wire adr_space, as_sorte, match, alles_ok;
wire [15:0] val_bits, as_bits;
wire ena_prot;
wire zugriff;

assign zugriff = READ | WRITE;

always @(VADR_R) begin
    case (VADR_R[15:12])
        4'h0 : maske = 16'h0001;
        4'h1 : maske = 16'h0002;
        4'h2 : maske = 16'h0004;
        4'h3 : maske = 16'h0008;
        4'h4 : maske = 16'h0010;
        4'h5 : maske = 16'h0020;
        4'h6 : maske = 16'h0040;
        4'h7 : maske = 16'h0080;
        4'h8 : maske = 16'h0100;
        4'h9 : maske = 16'h0200;
        4'hA : maske = 16'h0400;
        4'hB : maske = 16'h0800;
        4'hC : maske = 16'h1000;
        4'hD : maske = 16'h2000;
        4'hE : maske = 16'h4000;
        4'hF : maske = 16'h8000;
    endcase
end

assign VIRTUELL = USER ? MCR_FLAGS[0] : MCR_FLAGS[1];

assign adr_space = IVAR[1] ? IVAR[0] : (MCR_FLAGS[2] & USER);

assign as_sorte = ((MVALID[31:16] & maske) != 16'h0);

assign match = (VADR_R[31:20] == MMU_VA[31:20]) & (adr_space == as_sorte) & ((MVALID[15:0] & maske) != 16'h0000);

assign alles_ok = match & (~WRITE | MMU_VA[17]) & ~PROT_ERROR;

assign MMU_HIT = zugriff ? (VIRTUELL ? alles_ok : 1'b1) : 1'b0;

assign val_bits = IVAR[1] ? (MVALID[15:0] & (match ? ~maske : 16'hFFFF)) : (MVALID[15:0] | maske);
assign as_bits = IVAR[1] ? MVALID[31:16] : (adr_space ? (MVALID[31:16] | maske) : (MVALID[31:16] & ~maske));

assign UPDATE = {as_bits, val_bits};

assign ena_prot = zugriff & VIRTUELL & match;

always @(ena_prot or MMU_VA or USER or WRITE or RMW) begin
    case ({ena_prot, MMU_VA[19:18]})
        3'b100 : PROT_ERROR = USER | WRITE | RMW;
        3'b101 : PROT_ERROR = USER;
        3'b110 : PROT_ERROR = USER & (WRITE | RMW);
        default : PROT_ERROR = 1'b0;
    endcase
end

assign CI = VIRTUELL & MMU_VA[16];
assign SEL_PTB1 = adr_space;

endmodule

module lfsr_descramble (
    input clk,
    input rst,
    input [DATA_WIDTH-1:0] data_in,
    input data_in_valid,
    output reg [DATA_WIDTH-1:0] data_out
);

parameter LFSR_WIDTH = 58;
parameter LFSR_POLY = 58'h8000000001;
parameter LFSR_INIT = {LFSR_WIDTH{1'b1}};
parameter LFSR_CONFIG = "FIBONACCI";
parameter REVERSE = 1;
parameter DATA_WIDTH = 64;
parameter STYLE = "AUTO";

reg [LFSR_WIDTH-1:0] lfsr_state;
reg [LFSR_WIDTH-1:0] lfsr_poly;
reg [DATA_WIDTH-1:0] data_in_reg;
reg [DATA_WIDTH-1:0] data_out_reg;
reg [DATA_WIDTH-1:0] data_out_reg2;
reg [DATA_WIDTH-1:0] data_out_reg3;
reg [DATA_WIDTH-1:0] data_out_reg4;
reg [DATA_WIDTH-1:0] data_out_reg5;
reg [DATA_WIDTH-1:0] data_out_reg6;
reg [DATA_WIDTH-1:0] data_out_reg7;
reg [DATA_WIDTH-1:0] data_out_reg8;

// initialize LFSR state and polynomial
initial begin
    lfsr_state = LFSR_INIT;
    lfsr_poly = LFSR_POLY;
end

always @(posedge clk) begin
    if (rst) begin
        lfsr_state <= LFSR_INIT;
        data_out_reg <= 0;
        data_out_reg2 <= 0;
        data_out_reg3 <= 0;
        data_out_reg4 <= 0;
        data_out_reg5 <= 0;
        data_out_reg6 <= 0;
        data_out_reg7 <= 0;
        data_out_reg8 <= 0;
    end else begin
        // shift LFSR state
        lfsr_state <= {lfsr_state[LFSR_WIDTH-2:0], lfsr_state[LFSR_WIDTH-1] ^ (LFSR_CONFIG == "FIBONACCI" ? lfsr_state[LFSR_WIDTH-2] : lfsr_state[0])};

        // descramble data
        if (data_in_valid) begin
            data_in_reg <= REVERSE ? {data_in[7:0], data_in[15:8], data_in[23:16], data_in[31:24], data_in[39:32], data_in[47:40], data_in[55:48], data_in[63:56]} : data_in;
            data_out_reg <= data_in_reg ^ {LFSR_CONFIG == "FIBONACCI" ? lfsr_state[LFSR_WIDTH-1] : lfsr_state[0], lfsr_state[LFSR_WIDTH-1:LFSR_WIDTH-2]};
            data_out_reg2 <= data_out_reg ^ {LFSR_CONFIG == "FIBONACCI" ? lfsr_state[LFSR_WIDTH-1] : lfsr_state[0], lfsr_state[LFSR_WIDTH-1:LFSR_WIDTH-2]};
            data_out_reg3 <= data_out_reg2 ^ {LFSR_CONFIG == "FIBONACCI" ? lfsr_state[LFSR_WIDTH-1] : lfsr_state[0], lfsr_state[LFSR_WIDTH-1:LFSR_WIDTH-2]};
            data_out_reg4 <= data_out_reg3 ^ {LFSR_CONFIG == "FIBONACCI" ? lfsr_state[LFSR_WIDTH-1] : lfsr_state[0], lfsr_state[LFSR_WIDTH-1:LFSR_WIDTH-2]};
            data_out_reg5 <= data_out_reg4 ^ {LFSR_CONFIG == "FIBONACCI" ? lfsr_state[LFSR_WIDTH-1] : lfsr_state[0], lfsr_state[LFSR_WIDTH-1:LFSR_WIDTH-2]};
            data_out_reg6 <= data_out_reg5 ^ {LFSR_CONFIG == "FIBONACCI" ? lfsr_state[LFSR_WIDTH-1] : lfsr_state[0], lfsr_state[LFSR_WIDTH-1:LFSR_WIDTH-2]};
            data_out_reg7 <= data_out_reg6 ^ {LFSR_CONFIG == "FIBONACCI" ? lfsr_state[LFSR_WIDTH-1] : lfsr_state[0], lfsr_state[LFSR_WIDTH-1:LFSR_WIDTH-2]};
            data_out_reg8 <= data_out_reg7 ^ {LFSR_CONFIG == "FIBONACCI" ? lfsr_state[LFSR_WIDTH-1] : lfsr_state[0], lfsr_state[LFSR_WIDTH-1:LFSR_WIDTH-2]};
        end
    end
end

assign data_out = REVERSE ? {data_out_reg8[7:0], data_out_reg8[15:8], data_out_reg8[23:16], data_out_reg8[31:24], data_out_reg8[39:32], data_out_reg8[47:40], data_out_reg8[55:48], data_out_reg8[63:56]} : data_out_reg8;

endmodule

