module wb_dsp_slave_registers (
   // Outputs
   wb_dat_o, wb_ack_o, wb_err_o, wb_rty_o, equation0_address_reg,
   equation1_address_reg, equation2_address_reg,
   equation3_address_reg, control_reg, interrupt,
   // Inputs
   wb_clk, wb_rst, wb_adr_i, wb_dat_i, wb_sel_i, wb_we_i, wb_cyc_i,
   wb_stb_i, wb_cti_i, wb_bte_i, status_reg
   ) ;
   parameter dw = 32;
   parameter aw = 8;
   parameter DEBUG = 0;

   input                  wb_clk;
   input                  wb_rst;
   input [aw-1:0]         wb_adr_i;
   input [dw-1:0]         wb_dat_i;
   input [3:0]            wb_sel_i;
   input                  wb_we_i;
   input                  wb_cyc_i;
   input                  wb_stb_i;
   input [2:0]            wb_cti_i;
   input [1:0]            wb_bte_i;
   output reg [dw-1:0]    wb_dat_o;
   output reg             wb_ack_o;
   output reg             wb_err_o;
   output reg             wb_rty_o;

   input [dw-1:0]         status_reg;   
   output reg [dw-1:0]    equation0_address_reg;
   output reg [dw-1:0]    equation1_address_reg;
   output reg [dw-1:0]    equation2_address_reg;
   output reg [dw-1:0]    equation3_address_reg;
   output reg [dw-1:0]    control_reg;
   output reg             interrupt = 0;

   // Register offsets
   parameter EQUATION0_ADDRESS_REG_OFFSET = 8'h00;
   parameter EQUATION1_ADDRESS_REG_OFFSET = 8'h04;
   parameter EQUATION2_ADDRESS_REG_OFFSET = 8'h08;
   parameter EQUATION3_ADDRESS_REG_OFFSET = 8'h0C;
   parameter CONTROL_REG_OFFSET = 8'h10;
   parameter STATUS_REG_OFFSET = 8'h14;

   // Register write logic
   always @(posedge wb_clk) begin
      if (wb_rst) begin
         equation0_address_reg <= 0;
         equation1_address_reg <= 0;
         equation2_address_reg <= 0;
         equation3_address_reg <= 0;
         control_reg <= 0;
      end else begin
         // Clear equation address registers if control_reg[0] is set
         if (control_reg[0]) begin
            equation0_address_reg <= 0;
            equation1_address_reg <= 0;
            equation2_address_reg <= 0;
            equation3_address_reg <= 0;
         end
         // Update equation address registers
         if (wb_cyc_i && wb_stb_i && wb_we_i) begin
            case (wb_adr_i[7:0])
               EQUATION0_ADDRESS_REG_OFFSET: equation0_address_reg[wb_sel_i] <= wb_dat_i;
               EQUATION1_ADDRESS_REG_OFFSET: equation1_address_reg[wb_sel_i] <= wb_dat_i;
               EQUATION2_ADDRESS_REG_OFFSET: equation2_address_reg[wb_sel_i] <= wb_dat_i;
               EQUATION3_ADDRESS_REG_OFFSET: equation3_address_reg[wb_sel_i] <= wb_dat_i;
               CONTROL_REG_OFFSET: control_reg[wb_sel_i] <= wb_dat_i;
            endcase
         end
      end
   end

   // Register read logic
   always @(posedge wb_clk) begin
      if (wb_rst) begin
         wb_dat_o <= 0;
      end else begin
         // Read equation address or control registers
         if (wb_cyc_i && wb_stb_i && ~wb_we_i) begin
            case (wb_adr_i[7:0])
               EQUATION0_ADDRESS_REG_OFFSET: wb_dat_o <= equation0_address_reg;
               EQUATION1_ADDRESS_REG_OFFSET: wb_dat_o <= equation1_address_reg;
               EQUATION2_ADDRESS_REG_OFFSET: wb_dat_o <= equation2_address_reg;
               EQUATION3_ADDRESS_REG_OFFSET: wb_dat_o <= equation3_address_reg;
               CONTROL_REG_OFFSET: control_reg <= wb_dat_o;
            endcase
         end
         // Read status register
         if (wb_cyc_i && wb_stb_i && ~wb_we_i && (wb_adr_i[7:0] == STATUS_REG_OFFSET)) begin
            wb_dat_o <= status_reg;
         end
      end
   end

   // Wishbone signals
   assign wb_ack_o = wb_cyc_i && wb_stb_i && ~wb_we_i;
   assign wb_err_o = 0;
   assign wb_rty_o = 0;

endmodule

module fifo (
  input clk,
  input rst_n,
  input push,
  input pop,
  input [7:0] datain,
  output empty,
  output almost_empty,
  output full,
  output almost_full,
  output error,
  output reg [7:0] dataout
);

  parameter WIDTH = 8;
  parameter DEPTH = 256;
  parameter ADDR_WIDTH = $clog2(DEPTH);

  reg [WIDTH-1:0] mem [0:DEPTH-1];
  reg [ADDR_WIDTH-1:0] head;
  reg [ADDR_WIDTH-1:0] tail;
  reg [ADDR_WIDTH-1:0] count;

  assign empty = (count == 0);
  assign almost_empty = (count <= 4);
  assign full = (count == DEPTH);
  assign almost_full = (count >= DEPTH - 4);

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      head <= 0;
      tail <= 0;
      count <= 0;
      dataout <= 0;
      error <= 0;
    end else begin
      if (push && !pop && !full) begin
        mem[head] <= datain;
        head <= head + 1;
        count <= count + 1;
      end else if (!push && pop && !empty) begin
        dataout <= mem[tail];
        tail <= tail + 1;
        count <= count - 1;
      end else if (push && pop) begin
        error <= 1;
      end
    end
  end

endmodule

module cordic_sine_cosine(clk, rst, en, angle, sin_val, cos_val);

  parameter bitwidth = 16;
  parameter zwidth = 16;
  parameter int_width = 8;
  parameter frac_width = 8;

  input clk;
  input rst;
  input en;
  input signed [bitwidth-1:0] angle;
  output signed [bitwidth-1:0] sin_val;
  output signed [bitwidth-1:0] cos_val;

  wire [bitwidth-1:0] angle_ext = {{(bitwidth-int_width-frac_width){1'b0}}, angle};
  wire [zwidth-1:0] zi = {angle_ext, {(zwidth-bitwidth-int_width-frac_width){1'b0}}};

  wire [bitwidth-1:0] xo;
  wire [bitwidth-1:0] yo;
  wire [zwidth-1:0] zo;

  cordic #(.bitwidth(bitwidth), .zwidth(zwidth)) cordic_inst (
    .clock(clk),
    .reset(rst),
    .enable(en),
    .xi(0),
    .yi(0),
    .zi(zi),
    .xo(xo),
    .yo(yo),
    .zo(zo)
  );

  assign sin_val = yo;
  assign cos_val = xo;

endmodule

module dual_port_RAM (
  input clk,
  input we1, we2,
  input re1, re2,
  input [log2(n)-1:0] addr1, addr2,
  input [m-1:0] data_in1, data_in2,
  output [m-1:0] data_out1, data_out2
);

parameter n = 1024; // size of memory array
parameter m = 8; // width of data bus

// memory array declaration
reg [m-1:0] mem [0:n-1];

// write logic for port 1
always @(posedge clk) begin
  if (we1) begin
    mem[addr1] <= data_in1;
  end
end

// write logic for port 2
always @(posedge clk) begin
  if (we2) begin
    mem[addr2] <= data_in2;
  end
end

// read logic for port 1
assign data_out1 = (re1) ? mem[addr1] : 0;

// read logic for port 2
