endmodule

module binary_search (
  input clk,
  input rst,
  input [31:0] sorted_array,
  input [31:0] target,
  output reg [31:0] index
);

  parameter ARRAY_SIZE = 8;
  parameter LOG2_ARRAY_SIZE = 3;

  reg [31:0] left;
  reg [31:0] right;
  reg [LOG2_ARRAY_SIZE:0] depth;

  always @(posedge clk, posedge rst) begin
    if (rst) begin
      index <= -1;
      left <= 0;
      right <= ARRAY_SIZE - 1;
      depth <= 0;
    end else begin
      if (depth == LOG2_ARRAY_SIZE) begin
        if (sorted_array[left] == target) begin
          index <= left;
        end else if (sorted_array[right] == target) begin
          index <= right;
        end else begin
          index <= -1;
        end
      end else begin
        depth <= depth + 1;
        if (target < sorted_array[(left + right) / 2]) begin
          right <= (left + right) / 2 - 1;
        end else begin
          left <= (left + right) / 2 + 1;
        end
      end
    end
  end

endmodule

module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out
);

reg [7:0] data_reg;
reg [3:0] count_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        data_reg <= 8'b0;
        count_reg <= 4'b0;
        valid_b <= 1'b0;
        data_out <= 10'b0;
    end
    else begin
        if (valid_a) begin
            data_reg <= data_reg + data_in;
            count_reg <= count_reg + 1;
        end
        if (count_reg == 4'b1111) begin
            data_out <= {data_reg, 2'b0};
            valid_b <= 1'b1;
        end
    end
end

assign ready_a = ~valid_b & ready_b;

endmodule

module top_module (
    input clk,
    input reset,
    input enable1, // Enable input for counter 1
    input enable2, // Enable input for counter 2
    output [3:0] q1, // 4-bit output from counter 1
    output [3:0] q2, // 4-bit output from counter 2
    output [3:0] final_output // Result of bitwise OR operation
);

    // Define two 4-bit binary counters with asynchronous reset and enable inputs
    reg [3:0] counter1;
    reg [3:0] counter2;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter1 <= 4'b0;
            counter2 <= 4'b0;
        end else if (enable1) begin
            counter1 <= counter1 + 1;
        end else if (enable2) begin
            counter2 <= counter2 + 1;
        end
    end

    assign q1 = counter1;
    assign q2 = counter2;

    // Define a functional module that takes in both of the 4-bit outputs from the counters
    // and outputs the bitwise OR of the two outputs
    assign final_output = q1 | q2;

endmodule

module dual_port_ram(addr1, addr2, data1, data2, we1, we2, out1, out2, clock);

   parameter addr1_width = 0;
   parameter data1_width = 0;
   parameter addr2_width = 0;
   parameter data2_width = 0;
   parameter mem_depth1 = 1 << addr1_width;
   parameter mem_depth2 = 1 << addr2_width;

   input clock;

   input [addr1_width-1:0] addr1;
   input [data1_width-1:0] data1;
   input we1;
   output reg [data1_width-1:0] out1;

   input [addr2_width-1:0] addr2;
   input [data2_width-1:0] data2;
   input we2;
   output reg [data2_width-1:0] out2;

   reg [data1_width-1:0] Mem1[0:mem_depth1];
   reg [data2_width-1:0] Mem2[0:mem_depth2];

   always @(posedge clock) begin
      if (we1)
         Mem1[addr1] <= data1;
      if (we2)
         Mem2[addr2] <= data2;
      out1 <= Mem1[addr1];
      out2 <= Mem2[addr2];
   end

endmodule

module top_module (
    input [3:0] inputs, // Four binary inputs
    output reg [3:0] ones_comp, // One's complement of highest priority input
    output reg active // Active high output when any input is high
);

reg [1:0] priority; // Priority encoder output
reg [3:0] highest; // Highest priority input
reg [3:0] complement; // One's complement of highest priority input

// Priority encoder
always @* begin
    if (inputs[3]) priority = 2'b11;
    else if (inputs[2]) priority = 2'b10;
    else if (inputs[1]) priority = 2'b01;
    else priority = 2'b00;
end

// Find highest priority input
always @* begin
    case (priority)
        2'b11: highest = inputs[3];
        2'b10: highest = inputs[2];
        2'b01: highest = inputs[1];
        2'b00: highest = inputs[0];
    endcase
end

// One's complement of highest priority input
always @* begin
    complement = ~highest;
end

// Final output
always @* begin
    if (inputs[3] || inputs[2] || inputs[1] || inputs[0]) begin
        ones_comp = complement;
        active = 1'b1;
    end
    else begin
        ones_comp = 4'b0000;
        active = 1'b0;
    end
end

endmodule

