module qpsk_demod (
  clk,
  data_qpsk_i,
  data_qpsk_q,
  data_valid,
  data_output
);

  input             clk;
  input   [15:0]    data_qpsk_i;
  input   [15:0]    data_qpsk_q;
  input             data_valid;
  output  [ 1:0]    data_output;

  wire    [15:0]    filtered_data_i;
  wire    [15:0]    filtered_data_q;
  wire    [ 7:0]    demodulated_data;

  // output logic
  assign data_output = demodulated_data[1:0];

  // PLL
  reg [15:0] phase_est = 0;
  reg [15:0] prev_data_i = 0;
  reg [15:0] prev_data_q = 0;
  reg [1:0]  prev_symbol = 0;
  reg [15:0] error = 0;
  reg [15:0] integrator = 0;
  reg [15:0] loop_filter_out = 0;

  always @(posedge clk) begin
    if (data_valid) begin
      // calculate phase error
      error = {data_qpsk_i, data_qpsk_q} * {prev_data_q, -prev_data_i};
      integrator <= integrator + (error >> 2);
      loop_filter_out <= loop_filter_out + (integrator >> 2);

      // update phase estimate
      phase_est <= phase_est + ((loop_filter_out * 32767) >> 15);

      // demodulate symbol
      casez(phase_est[13:10])
        4'b0000: demodulated_data <= {prev_symbol[0], ~prev_symbol[1]};
        4'b0100: demodulated_data <= {prev_symbol[0], prev_symbol[1]};
        4'b1000: demodulated_data <= {~prev_symbol[0], prev_symbol[1]};
        4'b1100: demodulated_data <= {~prev_symbol[0], ~prev_symbol[1]};
      endcase

      // update state
      prev_data_i <= data_qpsk_i;
      prev_data_q <= data_qpsk_q;
      prev_symbol <= demodulated_data;
    end
  end

  // instantiation
  Raised_Cosine_Receive_Filter i_rx_filter (
    .clk(clk),
    .reset(1'b0),
    .enb_1_1_1(data_valid),
    .In1_re(data_qpsk_i),
    .In1_im(data_qpsk_q),
    .Out1_re(filtered_data_i),
    .Out1_im(filtered_data_q)
  );

endmodule

