module counter(clk, led1, led2, jt_capture, jt_drck, jt_reset, jt_shift, jt_tck, jt_tdi, jt_tdo);
   input clk;
   input jt_capture, jt_drck, jt_reset, jt_shift, jt_tck, jt_tdi;
   output led1;
   output [31:0] led2;
   output jt_tdo;

   reg 	  counter_start = 1'b0;
   reg 	  counter_we = 1'b0;
   reg [31:0] counter = 32'd0;
   reg [31:0] counter_set = 32'd0;
   reg [3:0]  jtag_addr = 4'hF;
   reg [37:0] jtag_data;
   reg 	  jtag_we;
   reg 	  jtag_checksum;

   assign led1 = ~counter_start;
   assign led2 = counter;

   always @(posedge clk)
     begin 
	if (counter_start == 1'b1)
	  counter <= counter + 1;
	if (counter_we == 1'b1)
	  counter <= counter_set;
     end

   BSCAN_SPARTAN6 # (.JTAG_CHAIN(1)) jtag_blk (
					       .CAPTURE(jt_capture),
					       .DRCK(jt_drck),
					       .RESET(jt_reset),
					       .RUNTEST(),
					       .SEL(),
					       .SHIFT(jt_shift),
					       .TCK(jt_tck),
					       .TDI(jt_tdi),
					       .TDO(jt_tdo),
					       .TMS(),
					       .UPDATE()
					       );

   always @ (posedge jt_tck)
     begin
	if (jt_reset == 1'b1)
	  begin
	     jtag_data <= 38'd0;
	  end
	else if (jt_capture == 1'b1)
	  begin
	     jtag_checksum <= 1'b1;
	     jtag_data[37:32] <= 6'd0;
	     jtag_addr <= 4'hF;
	     case (jtag_addr)
	       4'h0: jtag_data[31:0] <= 32'h20120911;
	       4'h1: jtag_data[0] <= counter_start;
	       4'h2: jtag_data[0] <= counter_we;
	       4'h3: jtag_data[31:0] <= counter_set;
	       4'h4: jtag_data[31:0] <= counter;

	       default: jtag_data[31:0] <= 32'habcdef01;
	     endcase
	  end
	else if (jt_shift == 1'b1)
	  begin
	     jtag_data <= {jt_tdi, jtag_data[37:1]};
	     jtag_checksum <= jtag_checksum ^ jt_tdi;
	  end
	else if (jt_drck == 1'b1 & jtag_checksum == 1'b1)
	  begin
	     jtag_addr <= jtag_data[35:32];
	     jtag_we <= jtag_data[36];
	     if (jtag_we)
	       begin
		  case (jtag_addr)
		    4'h1: counter_start <= jtag_data[0];
		    4'h2: counter_we <= jtag_data[0];
		    4'h3: counter_set <= jtag_data[31:0];
		  endcase
	       end
	     jtag_checksum <= 1'b0;
	  end
     end
endmodule

module vending_machine (
  input clk,
  input reset,
  input coin_5,
  input coin_10,
  input coin_25,
  output reg product_dispensed
);

  // Define the states
  localparam IDLE = 2'b00;
  localparam ACCEPTING = 2'b01;
  localparam DISPENSING = 2'b10;

  // Define the current state and the current amount
  reg [1:0] state = IDLE;
  reg [5:0] current_amount = 0;

  // Define the state transition logic
  always @(posedge clk, negedge reset) begin
    if (reset == 1'b0) begin
      state <= IDLE;
      current_amount <= 0;
      product_dispensed <= 0;
    end else begin
      case (state)
        IDLE: begin
          if (coin_5) begin
            current_amount <= current_amount + 5;
            state <= ACCEPTING;
          end else if (coin_10) begin
            current_amount <= current_amount + 10;
            state <= ACCEPTING;
          end else if (coin_25) begin
            current_amount <= current_amount + 25;
            state <= ACCEPTING;
          end
        end
        ACCEPTING: begin
          if (current_amount >= 50) begin
            state <= DISPENSING;
          end else if (coin_5) begin
            current_amount <= current_amount + 5;
          end else if (coin_10) begin
            current_amount <= current_amount + 10;
          end else if (coin_25) begin
            current_amount <= current_amount + 25;
          end else begin
            state <= IDLE;
          end
        end
        DISPENSING: begin
          product_dispensed <= 1;
          state <= IDLE;
          current_amount <= current_amount - 50;
        end
      endcase
    end
  end

endmodule

