module binary_multiplier(
    input [99:0] a, b,
    output [199:0] product
);

reg [199:0] temp_product;
reg [99:0] temp_a;
reg [99:0] temp_b;

integer i, j;

always @(*) begin
    temp_product = 0;
    for (i = 0; i < 100; i = i + 1) begin
        temp_a = (a >> i) & 1;
        for (j = 0; j < 100; j = j + 1) begin
            temp_b = (b >> j) & 1;
            temp_product[i+j] = temp_product[i+j] + (temp_a & temp_b);
        end
    end
end

assign product = temp_product;

endmodule

