module fifo
#(
    parameter C_FIFO_PASSTHROUGH = 0,
    parameter C_FIFO_WIDTH       = 1,
    parameter C_FIFO_DEPTH_X     = 1,
    parameter C_FIFO_DEPTH       = 2**C_FIFO_DEPTH_X
)
(
    input  wire                     clk_i,
    input  wire                     reset_i,
    input  wire                     flush_i,
    output wire                     empty_o,
    output reg                      full_o,
    input  wire                     wr_i,
    input  wire  [C_FIFO_WIDTH-1:0] din_i,
    input  wire                     rd_i,
    output wire  [C_FIFO_WIDTH-1:0] dout_o
);

    reg [C_FIFO_DEPTH_X-1:0] rd_ptr_q;
    reg [C_FIFO_DEPTH_X-1:0] wr_ptr_q;
    reg [C_FIFO_WIDTH-1:0] mem[C_FIFO_DEPTH-1:0];
    reg [C_FIFO_DEPTH_X-1:0] depth;

    assign empty_o = (rd_ptr_q == wr_ptr_q) & ~full_o;

    always @ (posedge clk_i) begin
        if (reset_i) begin
            rd_ptr_q <= 0;
            wr_ptr_q <= 0;
            depth <= 0;
            full_o <= 0;
        end else if (flush_i) begin
            rd_ptr_q <= 0;
            wr_ptr_q <= 0;
            depth <= 0;
            full_o <= 0;
        end else begin
            if (wr_i & ~full_o) begin
                mem[wr_ptr_q] <= din_i;
                wr_ptr_q <= wr_ptr_q + 1;
                depth <= depth + 1;
                full_o <= (depth == C_FIFO_DEPTH);
            end
            if (rd_i & ~empty_o) begin
                dout_o <= mem[rd_ptr_q];
                rd_ptr_q <= rd_ptr_q + 1;
                depth <= depth - 1;
                full_o <= 0;
            end
        end
    end

    assign dout_o = (empty_o & C_FIFO_PASSTHROUGH) ? din_i : mem[rd_ptr_q];

endmodule

module board_interface(
