  // Concurrent connectivity for ports etc.
  //----------------------------------------------------------------
  assign scl_internal = scl_out;
  assign sda_internal = sda_out;

  //----------------------------------------------------------------
  // core instantiations.
  //----------------------------------------------------------------


  //----------------------------------------------------------------
  // reg_update
  // Update functionality for all registers in the core.
  // All registers are positive edge triggered with synchronous
  // active low reset. All registers have write enable.
  //----------------------------------------------------------------
  always @ (posedge clk)
    begin
      if (!reset_n)
        begin
          led_reg <= 8'b0;
          button_reg <= 8'b0;
          uart_reg <= 8'b0;
        end
      else
        begin
          if (hdmi_i2c_data_in) begin
            hdmi_i2c_data_out <= 1'b0;
