module calculator (
   input wire clk,
   input wire reset,
   input wire [3:0] operand1,
   input wire [3:0] operand2,
   input wire operation,
   output reg [3:0] result,
   output reg overflow
   );

   always @(posedge clk) begin
      if (reset) begin
         result <= 4'b0000;
         overflow <= 1'b0;
      end
      else begin
         if (operation == 1'b0) begin
            // Addition
            result <= operand1 + operand2;
         end
         else begin
            // Subtraction
            result <= operand1 - operand2;
         end
         if (result > 4'b1111) begin
            overflow <= 1'b1;
         end
         else begin
            overflow <= 1'b0;
         end
      end
   end

endmodule

