module calculator_4bit(A, B, Sel, Clk, Result, Cout);
input [3:0] A, B;
input Sel, Clk;
output [3:0] Result;
output Cout;

reg [3:0] sum;
reg [3:0] diff;
reg carry;
reg borrow;

always @(posedge Clk) begin
    if (Sel == 0) begin
        // Addition operation
        sum = A + B;
        carry = (sum > 15) ? 1 : 0;
        Result = sum[3:0];
        Cout = carry;
    end else begin
        // Subtraction operation
        diff = A - B;
        borrow = (A < B) ? 1 : 0;
        Result = diff[3:0];
        Cout = borrow;
    end
end

endmodule

module counter(
    input [3:0] reset,
    input [3:0] enable,
    output reg [3:0] count
);

always @(posedge enable or posedge reset) begin
    if (reset == 4'b1111) begin
        count <= 4'b0000;
    end else begin
        count <= count + 1;
    end
end

endmodule

module PhotonBlock2(
	//Inputs
	clock,
	reset,
	enable,

   i_x, 
   i_y, 
   i_z, 

	//Outputs
	o_x,
	o_y,
	o_z
	);

//////////////////////////////////////////////////////////////////////////////
//PARAMETERS
//////////////////////////////////////////////////////////////////////////////
parameter BIT_WIDTH=32;

input				clock;
input				reset;
input				enable;

input	[BIT_WIDTH-1:0]			i_x;
input	i_y;
input	i_z;


output	[BIT_WIDTH-1:0]			o_x;
output	o_y;
output	o_z;

wire				clock;
wire				reset;
wire				enable;

wire	[BIT_WIDTH-1:0]			i_x;
wire	i_y;
wire	i_z;

reg	[BIT_WIDTH-1:0]			o_x;
reg	o_y;
reg	o_z;

always @ (posedge clock)
	if(reset) begin
		o_x		<=	{BIT_WIDTH{1'b0}} ;
		o_y		<=	1'b0;
		o_z		<=	1'b0;
	end else if(enable) begin
		o_x		<=	i_x;
		o_y		<=	i_y;
		o_z		<=	i_z;
	end
endmodule

