module bcd_counter(
    input clk,
    input reset,   // Synchronous active-high reset
    input en,
    output reg [15:0] q
    );

    reg [3:0] state;

    always @(posedge clk, posedge reset) begin
        if (reset) begin
            state <= 4'b0000;
            q <= 16'd0;
        end
        else begin
            case (state)
                4'b0000: begin
                    if (en) begin
                        state <= 4'b0001;
                    end
                end
                4'b0001: begin
                    q <= q + 1;
                    if (q[3:0] == 4'b1010) begin
                        q[3:0] <= 4'b0000;
                        state <= 4'b0010;
                    end
                end
                4'b0010: begin
                    if (en) begin
                        state <= 4'b0011;
                    end
                end
                4'b0011: begin
                    q <= q + 10;
                    if (q[7:4] == 4'b1010) begin
                        q[7:4] <= 4'b0000;
                        state <= 4'b0100;
                    end
                end
                4'b0100: begin
                    if (en) begin
                        state <= 4'b0101;
                    end
                end
                4'b0101: begin
                    q <= q + 100;
                    if (q[11:8] == 4'b1010) begin
                        q[11:8] <= 4'b0000;
                        state <= 4'b0110;
                    end
                end
                4'b0110: begin
                    if (en) begin
                        state <= 4'b0111;
                    end
                end
                4'b0111: begin
                    q <= q + 1000;
                    if (q[15:12] == 4'b1001) begin
                        q[15:12] <= 4'b0000;
                        state <= 4'b0000;
                    end
                end
            endcase
        end
    end

    assign ena = q[15:13];

endmodule

module multiplier (
    input [7:0] a,
    input [7:0] b,
    output [15:0] product
);
    assign product = a * b;
endmodule

module comparator (
    input [7:0] a,
    input [7:0] b,
    output greater
);
    assign greater = (a > b) ? 1 : 0;
endmodule

module functional_module (
    input [7:0] a,
    input [7:0] b,
    output [15:0] result
);
    wire [15:0] product;
    wire greater;

    multiplier m(a, b, product);
    comparator c(a, b, greater);

    assign result = (greater == 1) ? product : (product / b);
endmodule

module top_module (
    input [7:0] a,
    input [7:0] b,
    output [15:0] result
);
    functional_module f(a, b, result);
endmodule

module dual_edge_falling_edge (
    input clk,
    input reset,
    input d,
    input [31:0] in,
    output [31:0] out
);

    // Dual-edge triggered flip-flop
    reg [31:0] dff_out;
    always @(posedge clk, negedge reset) begin
        if (!reset) begin
            dff_out <= 0;
        end else begin
            dff_out <= d;
        end
    end

    // Falling edge detector
    reg [31:0] fed_out;
    always @(posedge clk, negedge reset) begin
        if (!reset) begin
            fed_out <= 0;
        end else if (in[31:1] > in[30:0]) begin
            fed_out <= 32'hFFFFFFFF;
        end else begin
            fed_out <= 0;
        end
    end

    // Additive functional module
    always @(*) begin
        if (dff_out) begin
            out <= fed_out;
        end else begin
            out <= dff_out;
        end
    end

endmodule

