module shift_left_2 (
    input [3:0] A,
    output [3:0] X
);

    wire [3:0] shifted_left;

    // Shift left by 2 bits using bitwise logic gates
    assign shifted_left[3] = A[1] & A[0];
    assign shifted_left[2] = A[0] & (~A[1]);
    assign shifted_left[1] = (~A[2]) & (~A[1]);
    assign shifted_left[0] = (~A[3]) & (~A[2]);

    // Assign output
    assign X = shifted_left;

endmodule

module mult_wrap (
input		ck,
input		rst,

input	[63:0]	i_a, i_b,
input   [8:0]   i_htId,
input           i_vld,

output          o_rdy,
output	[63:0]	o_res,
output  [8:0]   o_htId,
output          o_vld
);

parameter ENTRY_DEPTH = 32; 

// Pipeline FIFO
wire        ef_afull;
wire        ef_pop;
wire        ef_empty;
wire [63:0] ef_a, ef_b;
wire [8:0]  ef_htId;

fifo #(
       .WIDTH(64+64+9),
       .DEPTH(ENTRY_DEPTH),
       .PIPE(1),
       .AFULLCNT(ENTRY_DEPTH - 2)
       ) entry_fifo (
		     .clk(ck),
		     .reset(rst),
		     .push(i_vld),
		     .din({i_a, i_b, i_htId}),
		     .afull(ef_afull),
		     .oclk(ck),
		     .pop(ef_pop),
		     .dout({ef_a, ef_b, ef_htId}),
		     .empty(ef_empty)
		     );

// Multiplier circuit
wire        mult_rdy;
wire [63:0] mult_res;
wire        mult_vld;

mul_64b_dp multiplier (.clk(ck), .a(ef_a), .b(ef_b), .operation_nd(ef_pop), .operation_rfd(mult_rdy), .result(mult_res), .rdy(mult_vld));

// Pipeline stages
reg [8:0]   r_t2_htId, r_t3_htId, r_t4_htId, r_t5_htId, r_t6_htId, r_t7_htId;

always @(posedge ck) begin
 	if (ef_pop) begin
 	 	r_t2_htId <= ef_htId;
 	end else begin
 	 	r_t2_htId <= r_t2_htId;
 	end
 	r_t3_htId <= r_t2_htId;
 	r_t4_htId <= r_t3_htId;
	r_t5_htId <= r_t4_htId;
	r_t6_htId <= r_t5_htId;
	r_t7_htId <= r_t6_htId;
end

// Output signals
assign o_rdy = !ef_afull;
assign o_res = mult_res;
assign o_htId = r_t7_htId;
assign o_vld = mult_vld;

endmodule

module binary_counter (
    input clk,
    input reset,   // Synchronous active-high reset
    input enable, // Active-high enable signal
    output reg [15:0] q
);

reg [3:0] ones_digit;
reg [3:0] tens_digit;
reg [3:0] hundreds_digit;
reg [3:0] thousands_digit;

always @(posedge clk) begin
    if (reset) begin
        ones_digit <= 4'b0000;
        tens_digit <= 4'b0000;
        hundreds_digit <= 4'b0000;
        thousands_digit <= 4'b0000;
        q <= 16'b0000000000000000;
    end else if (enable) begin
        ones_digit <= ones_digit + 1;
        if (ones_digit == 10) begin
            ones_digit <= 4'b0000;
            tens_digit <= tens_digit + 1;
        end
        if (tens_digit == 10) begin
            tens_digit <= 4'b0000;
            hundreds_digit <= hundreds_digit + 1;
        end
        if (hundreds_digit == 10) begin
            hundreds_digit <= 4'b0000;
            thousands_digit <= thousands_digit + 1;
        end
        q <= {thousands_digit, hundreds_digit, tens_digit, ones_digit};
    end
end

endmodule

