module power_ground_module (
    input clk,
    input rst_n,
    input enable,
    output reg VPWR,
    output reg VGND
);

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        VPWR <= 0;
        VGND <= 0;
    end else if (enable) begin
        VPWR <= 1;
        VGND <= 0;
    end else begin
        VPWR <= 0;
        VGND <= 0;
    end
end

endmodule

module reverse_bit_order(
    input [7:0] in,
    output [7:0] out
);

reg [7:0] shift_reg;

always @(*) begin
    shift_reg[0] = in[7];
    shift_reg[1] = in[6];
    shift_reg[2] = in[5];
    shift_reg[3] = in[4];
    shift_reg[4] = in[3];
    shift_reg[5] = in[2];
    shift_reg[6] = in[1];
    shift_reg[7] = in[0];
end

assign out = shift_reg;

endmodule

module full_adder (
    input a,
    input b,
    input cin,
    output sum,
    output cout
);

    assign sum = a ^ b ^ cin;
    assign cout = (a & b) | (a & cin) | (b & cin);

endmodule

module half_adder (
    input a,
    input b,
    output sum,
    output cout
);

    assign sum = a ^ b;
    assign cout = a & b;

endmodule

module top_module (
    input clk,
    input reset,
    input [3:0] a,
    input [3:0] b,
    input cin,
    output [3:0] sum
);

    wire [3:0] fa_sum;
    wire [3:0] ha_sum;
    wire [3:0] ha_cout;
    wire [3:0] fa_cout;

    // Instantiate half adders
    half_adder ha0(a[0], b[0], ha_sum[0], ha_cout[0]);
    half_adder ha1(a[1], b[1], ha_sum[1], ha_cout[1]);
    half_adder ha2(a[2], b[2], ha_sum[2], ha_cout[2]);
    half_adder ha3(a[3], b[3], ha_sum[3], ha_cout[3]);

    // Instantiate full adders
    full_adder fa0(ha_sum[0], cin, ha_cout[0], fa_sum[0], fa_cout[0]);
    full_adder fa1(ha_sum[1], ha_cout[0], ha_cout[1], fa_sum[1], fa_cout[1]);
    full_adder fa2(ha_sum[2], ha_cout[1], ha_cout[2], fa_sum[2], fa_cout[2]);
    full_adder fa3(ha_sum[3], ha_cout[2], fa_cout[3], fa_sum[3], sum[3]);

    assign sum[0] = fa_sum[0];

    // Add clock and reset to all modules
    always @(posedge clk) begin
        if (reset) begin
            ha_sum <= 4'b0;
            ha_cout <= 4'b0;
            fa_sum <= 4'b0;
            fa_cout <= 4'b0;
            sum <= 4'b0;
        end
    end

endmodule

module MAC_tx_addr_add ( 
    Reset,
    Clk,
    MAC_tx_addr_init,
    MAC_tx_addr_rd,
    MAC_tx_addr_data,
    MAC_add_prom_data,
    MAC_add_prom_add,
    MAC_add_prom_wr
);

    input           Reset;
    input           Clk;
    input           MAC_tx_addr_rd;
    input           MAC_tx_addr_init;
    output  [7:0]   MAC_tx_addr_data;
    input   [7:0]   MAC_add_prom_data;
    input   [2:0]   MAC_add_prom_add;
    input           MAC_add_prom_wr;

    // Internal signals
    reg [2:0]       add_rd;
    wire[2:0]       add_wr;
    wire[7:0]       din;
    wire[7:0]       dout;
    wire            wr_en;
    reg             MAC_add_prom_wr_dl1;
    reg             MAC_add_prom_wr_dl2;

    // Write data from CPU to prom
    always @(posedge Clk or posedge Reset) begin
        if (Reset) begin
            MAC_add_prom_wr_dl1 <= 0;
            MAC_add_prom_wr_dl2 <= 0;
        end else begin
            MAC_add_prom_wr_dl1 <= MAC_add_prom_wr;
            MAC_add_prom_wr_dl2 <= MAC_add_prom_wr_dl1;
        end
    end
    assign #2 wr_en = MAC_add_prom_wr_dl1 & !MAC_add_prom_wr_dl2;
    assign #2 add_wr = MAC_add_prom_add;
    assign #2 din = MAC_add_prom_data;

    // Read data from CPU to prom
    always @(posedge Clk or posedge Reset) begin
        if (Reset) begin
            add_rd <= 0;
        end else if (MAC_tx_addr_init) begin
            add_rd <= 0;
        end else if (MAC_tx_addr_rd) begin
            add_rd <= add_rd + 1;
        end
    end
    assign MAC_tx_addr_data = dout;

    // Dual port RAM
    reg [7:0] ram [0:7];
    always @(posedge Clk) begin
        if (wr_en) begin
            ram[add_wr] <= din;
        end
        dout <= ram[add_rd];
    end

endmodule

module sys_mon
(
  DADDR_IN,            // Address bus for the dynamic reconfiguration port
  DCLK_IN,             // Clock input for the dynamic reconfiguration port
  DEN_IN,              // Enable Signal for the dynamic reconfiguration port
  DI_IN,               // Input data bus for the dynamic reconfiguration port
  DWE_IN,              // Write Enable for the dynamic reconfiguration port
  VAUXP12,             // Auxiliary channel 12
  VAUXN12,
  VAUXP13,             // Auxiliary channel 13
  VAUXN13,
  DO_OUT,              // Output data bus for dynamic reconfiguration port
  DRDY_OUT,            // Data ready signal for the dynamic reconfiguration port
  ALARM_OUT,           // OR'ed output of all the Alarms    
  VP_IN,               // Dedicated Analog Input Pair
  VN_IN
);

  input [6:0] DADDR_IN;
  input DCLK_IN;
  input DEN_IN;
  input [15:0] DI_IN;
  input DWE_IN;
  input VAUXP12;
  input VAUXN12;
  input VAUXP13;
  input VAUXN13;
  input VP_IN;
  input VN_IN;

  output reg [15:0] DO_OUT;
  output reg DRDY_OUT;
  output ALARM_OUT;

  reg [15:0] temp_alarm_trigger;
  reg [15:0] vccint_upper_alarm_limit;
  reg [15:0] vccaux_upper_alarm_limit;
  reg [15:0] temp_alarm_ot_upper;
  reg [15:0] temp_alarm_reset;
  reg [15:0] vccint_lower_alarm_limit;
  reg [15:0] vccaux_lower_alarm_limit;
  reg [15:0] temp_alarm_ot_reset;
  reg [15:0] vbram_upper_alarm_limit;
  reg [15:0] vbram_lower_alarm_limit;

  // Initialize alarm thresholds
  initial begin
    temp_alarm_trigger = 16'hb5ed;
    vccint_upper_alarm_limit = 16'h57e4;
    vccaux_upper_alarm_limit = 16'ha147;
    temp_alarm_ot_upper = 16'hca33;
    temp_alarm_reset = 16'ha93a;
    vccint_lower_alarm_limit = 16'h52c6;
    vccaux_lower_alarm_limit = 16'h9555;
    temp_alarm_ot_reset = 16'hae4e;
    vbram_upper_alarm_limit = 16'h5999;
    vbram_lower_alarm_limit = 16'h5111;
  end

  // Initialize alarms
  reg [7:0] alm_int;
  always @* begin
    alm_int = 8'b00000000;
    if (DO_OUT > temp_alarm_trigger) begin
      alm_int[0] = 1'b1;
    end
    if (DO_OUT > vccint_upper_alarm_limit) begin
      alm_int[1] = 1'b1;
    end
    if (DO_OUT > vccaux_upper_alarm_limit) begin
      alm_int[2] = 1'b1;
    end
    if (DO_OUT > temp_alarm_ot_upper) begin
      alm_int[3] = 1'b1;
    end
    if (DO_OUT < vccint_lower_alarm_limit) begin
      alm_int[4] = 1'b1;
    end
    if (DO_OUT < vccaux_lower_alarm_limit) begin
      alm_int[5] = 1'b1;
    end
    if (DO_OUT < temp_alarm_ot_reset) begin
      alm_int[6] = 1'b1;
    end
    if (DO_OUT > vbram_upper_alarm_limit || DO_OUT < vbram_lower_alarm_limit) begin
      alm_int[7] = 1'b1;
    end
  end

  always @(posedge DCLK_IN) begin
    DO_OUT <= 16'h0000;
    DRDY_OUT <= DEN_IN;
    if (DWE_IN) begin
      case (DADDR_IN)
        7'h00: temp_alarm_trigger <= DI_IN;
        7'h01: vccint_upper_alarm_limit <= DI_IN;
        7'h02: vccaux_upper_alarm_limit <= DI_IN;
        7'h03: temp_alarm_ot_upper <= DI_IN;
        7'h04: temp_alarm_reset <= DI_IN;
        7'h05: vccint_lower_alarm_limit <= DI_IN;
        7'h06: vccaux_lower_alarm_limit <= DI_IN;
        7'h07: temp_alarm_ot_reset <= DI_IN;
        7'h08: vbram_upper_alarm_limit <= DI_IN;
        7'h09: vbram_lower_alarm_limit <= DI_IN;
        default: DO_OUT <= 16'h0000;
      endcase
    end
  end

  assign ALARM_OUT = |alm_int;

endmodule

