module input_fifo_wr_logic
   (out,
    full,
    WEA,
    Q,
    v1_reg,
    ram_empty_i_reg,
    ram_empty_i_reg_0,
    ram_empty_i_reg_1,
    ram_empty_i_reg_2,
    ram_empty_i_reg_3,
    srst,
    clk,
    wr_en,
    E,
    \gc0.count_d1_reg[9] ,
    \gc0.count_reg[9] );
  output out;
  output full;
  output [0:0]WEA;
  output [9:0]Q;
  output [4:0]v1_reg;
  output ram_empty_i_reg;
  output ram_empty_i_reg_0;
  output ram_empty_i_reg_1;
  output ram_empty_i_reg_2;
  output ram_empty_i_reg_3;
  input srst;
  input clk;
  input wr_en;
  input [0:0]E;
  input [9:0]\gc0.count_d1_reg[9] ;
  input [9:0]\gc0.count_reg[9] ;

  reg [9:0] fifo[0:1023]; // FIFO with 1024 entries
  reg [9:0] head = 0; // index of the head of the queue
  reg [9:0] tail = 0; // index of the tail of the queue
  reg [4:0] count = 0; // number of elements in the queue
  reg [0:0] full = 0; // whether the FIFO is full
  reg [0:0] empty = 1; // whether the FIFO is empty
  reg [0:0] ram_empty_i_reg = 1; // whether the RAM is empty
  reg [0:0] ram_empty_i_reg_0 = 1; // whether the RAM is empty
  reg [0:0] ram_empty_i_reg_1 = 1; // whether the RAM is empty
  reg [0:0] ram_empty_i_reg_2 = 1; // whether the RAM is empty
  reg [0:0] ram_empty_i_reg_3 = 1; // whether the RAM is empty
  reg [4:0] v1_reg = 0; // value of v1_reg

  always @(posedge clk) begin
    if (srst) begin
      // reset the FIFO and all other signals
      head <= 0;
      tail <= 0;
      count <= 0;
      full <= 0;
      empty <= 1;
      ram_empty_i_reg <= 1;
      ram_empty_i_reg_0 <= 1;
      ram_empty_i_reg_1 <= 1;
      ram_empty_i_reg_2 <= 1;
      ram_empty_i_reg_3 <= 1;
      v1_reg <= 0;
    end else if (wr_en) begin
      // write the value of E to the FIFO
      fifo[tail] <= E;
      tail <= (tail == 1023) ? 0 : tail + 1;
      count <= count + 1;
      empty <= 0;
      ram_empty_i_reg <= 0;
      ram_empty_i_reg_0 <= 0;
      ram_empty_i_reg_1 <= 0;
      ram_empty_i_reg_2 <= 0;
      ram_empty_i_reg_3 <= 0;
      if (count == 1024) begin
        // the FIFO is full
        full <= 1;
      end
    end

    // output the value of the FIFO at the head of the queue
    Q <= fifo[head];

    // set the WEA signal to the index of the next empty slot in the FIFO
    WEA <= (full) ? tail : ((count == 0) ? 0 : ((head == 1023) ? 0 : head + 1));

    // set the ram_empty_i_reg signals to indicate whether the FIFO is empty or not
    ram_empty_i_reg <= empty;
    ram_empty_i_reg_0 <= empty;
    ram_empty_i_reg_1 <= empty;
    ram_empty_i_reg_2 <= empty;
    ram_empty_i_reg_3 <= empty;

    // set the v1_reg signals to a value determined by the current state of the FIFO
    case (count)
      0: v1_reg <= 0;
      1: v1_reg <= 1;
      2: v1_reg <= 2;
      3: v1_reg <= 3;
      default: v1_reg <= 4;
    endcase

    // update the state of the FIFO
    if (wr_en && !full) begin
      if (count == 0) begin
        // the FIFO was empty
        head <= tail;
        empty <= 0;
      end
      count <= count + 1;
      tail <= (tail == 1023) ? 0 : tail + 1;
      if (count == 1024) begin
        // the FIFO is full
        full <= 1;
      end
    end else if (count > 0) begin
      count <= count - 1;
      head <= (head == 1023) ? 0 : head + 1;
      if (count == 1) begin
        // the FIFO is now empty
        empty <= 1;
      end
    end
  end

  // set the output signal to high if the FIFO is full
  assign out = full;

endmodule

