module hysteresis_comparator(
  input Vin,
  input Vref,
  input clk,
  output reg Vout,
  output reg Vhys
);

parameter Vth = 0.1; // threshold voltage
parameter Vh = 0.05; // hysteresis voltage

initial begin
  Vout = 0;
  Vhys = 0;
end

always@(posedge clk) begin
  if(Vin > Vref + Vth) begin
    Vout <= 1;
    Vhys <= 0;
  end else if(Vin < Vref - Vth) begin
    Vout <= 0;
    Vhys <= 1;
  end else if(Vin > Vref - Vh && Vin < Vref + Vh) begin
    Vout <= Vout;
    Vhys <= Vhys;
  end
end

endmodule

