  wire [3:0] C;
  wire [3:0] D;

  assign C[0] = A[0] ^ B[0] ^ Cin;
  assign D[0] = A[0] & B[0] | A[0] & Cin | B[0] & Cin;

  assign C[1] = A[1] ^ B[1] ^ D[0];
  assign D[1] = A[1] & B[1] | A[1] & D[0] | B[1] & D[0];

  assign C[2] = A[2] ^ B[2] ^ D[1];
  assign D[2] = A[2] & B[2] | A[2] & D[1] | B[2] & D[1];

  assign C[3] = A[3] ^ B[3] ^ D[2];
  assign D[3] = A[3] & B[3] | A[3] & D[2] | B[3] & D[2];

  assign S = C;
  assign Cout = D[3];
endmodule

module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    output [3:0] S,
    output C_out
);

    wire [3:0] F1_sum;
    wire [3:0] F2_sum;
    wire [3:0] F3_sum;
    wire [3:0] F4_sum;
    wire F1_carry_out;
    wire F2_carry_out;
    wire F3_carry_out;
    wire F4_carry_out;

    full_adder FA1(
        .a(A[0]),
        .b(B[0]),
        .carry_in(1'b0),
        .sum(F1_sum[0]),
        .carry_out(F1_carry_out)
    );

    full_adder FA2(
        .a(A[1]),
        .b(B[1]),
        .carry_in(F1_carry_out),
        .sum(F2_sum[1]),
        .carry_out(F2_carry_out)
    );

    full_adder FA3(
        .a(A[2]),
        .b(B[2]),
        .carry_in(F2_carry_out),
        .sum(F3_sum[2]),
        .carry_out(F3_carry_out)
    );

    full_adder FA4(
        .a(A[3]),
        .b(B[3]),
        .carry_in(F3_carry_out),
        .sum(F4_sum[3]),
        .carry_out(C_out)
    );

    half_adder HA1(
        .a(F1_sum[0]),
        .b(F2_sum[1]),
        .sum(S[0]),
        .carry_out(F2_carry_out)
    );

    half_adder HA2(
        .a(F2_sum[2]),
        .b(F3_sum[3]),
        .sum(S[2]),
        .carry_out(F3_carry_out)
    );

    half_adder HA3(
        .a(F1_sum[1]),
        .b(F2_sum[2]),
        .sum(S[1]),
        .carry_out(F3_carry_out)
    );

    half_adder HA4(
        .a(F3_sum[2]),
        .b(F4_sum[3]),
        .sum(S[3]),
        .carry_out(C_out)
    );

endmodule

module glitch_filter (
  input wire clk,
  input wire reset,
  input wire [n-1:0] signal_in,
  output reg [n-1:0] signal_out
);

parameter n = 8; // number of bits in the input signal
parameter t = 3; // duration of the glitch filter in clock cycles

reg [n-1:0] shift_register [t-1:0];

integer i;

always @(posedge clk or posedge reset) begin
  if (reset) begin
    signal_out <= 0;
    for (i = 0; i < t; i = i + 1) begin
      shift_register[i] <= 0;
    end
  end else begin
    for (i = 0; i < t-1; i = i + 1) begin
      shift_register[i] <= shift_register[i+1];
    end
    shift_register[t-1] <= signal_in;

    if (shift_register[0] == signal_in) begin
      signal_out <= signal_in;
    end
  end
end

endmodule

module character_fsm (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  output reg walk_left,
  output reg walk_right,
  output reg aaah
);

  // Define states
  parameter WALK_LEFT = 2'b00;
  parameter WALK_RIGHT = 2'b01;
  parameter FALL = 2'b10;

  // Define state register and next state logic
  reg [1:0] state, next_state;
  always @ (posedge clk or negedge areset) begin
    if (areset == 0) begin
      state <= WALK_LEFT;
    end else begin
      state <= next_state;
    end
  end

  // Define output logic
  always @ (*) begin
    case (state)
      WALK_LEFT: begin
        walk_left = 1;
        walk_right = 0;
        aaah = 0;
        if (bump_left == 1) begin
          next_state = WALK_RIGHT;
        end else if (ground == 0) begin
          next_state = FALL;
        end else begin
          next_state = WALK_LEFT;
        end
      end
      WALK_RIGHT: begin
        walk_left = 0;
        walk_right = 1;
        aaah = 0;
        if (bump_right == 1) begin
          next_state = WALK_LEFT;
        end else if (ground == 0) begin
          next_state = FALL;
        end else begin
          next_state = WALK_RIGHT;
        end
      end
      FALL: begin
        walk_left = state[0];
        walk_right = state[1];
        aaah = 1;
        if (ground == 1) begin
          next_state = state;
        end else begin
          next_state = FALL;
        end
      end
    endcase
  end
endmodule

