module top_module ( 
    input wire [15:0] in, 
    input a, 
    input b, 
    output out 
); 

    wire [7:0] lower_byte;
    wire [7:0] upper_byte;
    wire [7:0] module1_out;
    wire [7:0] module2_out;

    // Barrel shifter to split input into upper and lower bytes
    barrel_shifter bs (
        .in(in),
        .shift(a ? 8 : 0),
        .out_lower(lower_byte),
        .out_upper(upper_byte)
    );

    // First given module with lower byte input
    reg_module module1 (
        .clk(b),
        .reset(0),
        .d(lower_byte),
        .q(module1_out)
    );

    // Second given module with upper byte input
    counter_module module2 (
        .clk(b),
        .reset(0),
        .q(module2_out)
    );
    assign module2.reset = a;

    // Functional module with NOR gate operation
    nor_gate nor (
        .a(module1_out),
        .b(module2_out),
        .out(out)
    );

endmodule

