module DEMUX (
  input in,
  input [k-1:0] c,
  output [2**k-1:0] out
);

parameter k = 3; // number of control signals

assign out = {k{1'b0}}; // initialize all output signals to 0

// loop through all possible output signals
genvar i;
generate
  for (i = 0; i < 2**k; i = i + 1) begin : DEMUX_GEN
    // check if the control signals match the current output signal
    if (c == i) begin
      // connect the input signal to the current output signal
      assign out[i] = in;
    end
  end
endgenerate

endmodule

module DAC (
  input [n-1:0] din,
  output analog_out
);

parameter n = 8; // number of digital signals
parameter vref = 1.0; // reference voltage

reg [n-1:0] weighted_resistors;
wire [n-1:0] din_scaled;
wire [n-1:0] din_scaled_inv;

assign din_scaled = din * (vref / ((1 << n) - 1));
assign din_scaled_inv = (~din) * (vref / ((1 << n) - 1));

assign weighted_resistors[0] = 1'b1;
generate
  genvar i;
  for (i = 1; i < n; i = i + 1) begin
    assign weighted_resistors[i] = weighted_resistors[i-1] << 1;
  end
endgenerate

wire weighted_sum;
assign weighted_sum = din_scaled & weighted_resistors | din_scaled_inv & (~weighted_resistors);

assign analog_out = weighted_sum;

endmodule

