    // 4-bit parity generator module
    wire [3:0] parity = {gray[3]^gray[2]^gray[1]^gray[0]};

    // 4-bit Gray code to binary converter module
    wire [3:0] binary = {gray[3], gray[3]^gray[2], gray[3]^gray[2]^gray[1], gray[3]^gray[2]^gray[1]^gray[0]};

    // Functional module to append parity bit
    always @* begin
        if (parity == 1'b1) begin
            binary_parity = {1'b1, binary};
        end else begin
            binary_parity = {1'b0, binary};
        end
    end

endmodule

