module DLL (
  input ref_clk,
  input sam_clk,
  input reset,
  output locked,
  output delay
);

parameter delay_range = 10;
parameter delay_step = 1;
parameter max_error = 0.1;

reg [31:0] delay_reg;
reg locked_reg;
reg [31:0] phase_error_reg;

wire ref_clk_inv;
wire sam_clk_inv;
wire phase_error_sign;
wire phase_error_abs;

assign ref_clk_inv = ~ref_clk;
assign sam_clk_inv = ~sam_clk;

// Phase detector
always @(posedge ref_clk or posedge ref_clk_inv or posedge sam_clk or posedge sam_clk_inv or posedge reset) begin
  if (reset) begin
    phase_error_reg <= 0;
  end else begin
    phase_error_reg <= phase_error_reg + (sam_clk ^ ref_clk) - (sam_clk_inv ^ ref_clk_inv);
  end
end

assign phase_error_sign = (phase_error_reg[31] == 1) ? 1'b1 : 1'b0;
assign phase_error_abs = (phase_error_reg[31] == 1) ? ~phase_error_reg + 1 : phase_error_reg;

// Delay line
always @(posedge ref_clk or posedge reset) begin
  if (reset) begin
    delay_reg <= 0;
  end else begin
    delay_reg <= (phase_error_sign == 1) ? delay_reg - delay_step : delay_reg + delay_step;
  end
end

assign delay = delay_reg;

// Locally generated clock signal
reg [31:0] counter_reg;
wire local_clk;

always @(posedge ref_clk or posedge reset) begin
  if (reset) begin
    counter_reg <= 0;
  end else begin
    counter_reg <= counter_reg + 1;
  end
end

assign local_clk = (counter_reg >= delay_reg) ? 1'b1 : 1'b0;

// Lock detection
always @(posedge ref_clk or posedge reset) begin
  if (reset) begin
    locked_reg <= 0;
  end else begin
    locked_reg <= (phase_error_abs <= max_error) ? 1'b1 : 1'b0;
  end
end

assign locked = locked_reg;

endmodule

module bclk_dll
 (
