module DELAY_LINE
 (
  input  clk_in,
  output clk_out,
  input  delay
 );

  reg [7:0] delay_count;

  always @(posedge clk_in)
    begin
      if (delay_count == delay)
        begin
          clk_out <= 1'b1;
          delay_count <= 0;
        end
      else
        begin
          clk_out <= 1'b0;
          delay_count <= delay_count + 1;
        end
    end

endmodule

