    case(control)
        2'b00: data_out <= {data_in[2:0], 1'b0};
        2'b01: data_out <= {1'b0, data_in[3:1]};
        2'b10: data_out <= {data_in[0], data_in[3:1]};
        default: data_out <= data_in;
    endcase
end

endmodule

