module axis_pulse_generator
(
  input  wire        aclk,
  input  wire        aresetn,

  // Slave side
  output wire        s_axis_tready,
  input  wire [63:0] s_axis_tdata,
  input  wire        s_axis_tvalid,

  // Master side
  input  wire        m_axis_tready,
  output wire [15:0] m_axis_tdata,
  output wire        m_axis_tvalid
);

  reg [31:0] int_cntr_reg, int_cntr_next;
  reg pulse_generated;
  reg [31:0] pulse_duration;
  reg [31:0] pulse_counter;

  wire int_enbl_wire, int_tready_wire, int_tvalid_wire;

  assign int_enbl_wire = |int_cntr_reg;
  assign int_tready_wire = ~int_enbl_wire;
  assign int_tvalid_wire = int_tready_wire & s_axis_tvalid;

  always @(posedge aclk)
  begin
    if(~aresetn)
    begin
      int_cntr_reg <= 32'd0;
      pulse_generated <= 1'b0;
      pulse_duration <= 32'd0;
      pulse_counter <= 32'd0;
    end
    else
    begin
      int_cntr_reg <= int_cntr_next;
    end
  end

  always @*
  begin
    int_cntr_next = int_cntr_reg;

    if(s_axis_tvalid && !pulse_generated)
    begin
      pulse_duration <= s_axis_tdata[63:32];
      pulse_generated <= 1'b1;
      pulse_counter <= pulse_duration;
    end

    if(pulse_generated)
    begin
      if(pulse_counter == 0)
      begin
        pulse_generated <= 1'b0;
      end
      else
      begin
        pulse_counter <= pulse_counter - 1'b1;
      end
    end

    if(int_enbl_wire)
    begin
      int_cntr_next = int_cntr_reg - 1'b1;
    end
  end

  assign s_axis_tready = int_tready_wire;
  assign m_axis_tdata = s_axis_tdata[15:0];
  assign m_axis_tvalid = int_tvalid_wire;

endmodule

module test_sync_gray #(
  // Bit-width of the counter
  parameter DATA_WIDTH = 1,
  // Whether the input and output clock are asynchronous, if set to 0 the
  // synchronizer will be bypassed and out_count will be in_count.
  parameter ASYNC_CLK = 1
)(
  input clk,
  input resetn,
  input [DATA_WIDTH-1:0] in_count,
  output [DATA_WIDTH-1:0] out_count
);

  reg [DATA_WIDTH-1:0] expected_gray_code;
  reg [DATA_WIDTH-1:0] gray_code;
  wire [DATA_WIDTH-1:0] in_count_sync;
  wire [DATA_WIDTH-1:0] out_count_sync;

  // Instantiate the sync_gray module
  sync_gray #(
    .DATA_WIDTH(DATA_WIDTH),
    .ASYNC_CLK(ASYNC_CLK)
  ) gray_sync(
    .in_clk(clk),
    .in_resetn(resetn),
    .in_count(in_count),
    .out_clk(clk),
    .out_resetn(resetn),
    .out_count(out_count_sync)
  );

  // Generate a random binary input count value
  initial begin
    expected_gray_code = $random % (1 << DATA_WIDTH);
    #10;
    in_count = expected_gray_code;
  end

  // Wait for the output count value to stabilize
  always @(posedge clk) begin
    if (resetn == 0) begin
      gray_code <= 'h0;
    end else begin
      gray_code <= out_count_sync;
    end
  end

  // Check that the output count value matches the expected gray code value
  always @(posedge clk) begin
    if (resetn == 0) begin
      out_count <= 'h0;
    end else if (gray_code == expected_gray_code) begin
      out_count <= gray_code;
      $display("Test passed! Input count value: %h, Expected gray code: %h, Output gray code: %h", in_count, expected_gray_code, gray_code);
      $finish;
    end else begin
      out_count <= gray_code;
    end
  end

endmodule

module video_system_cpu_module (
  input clk,
  input [37:0] jdo,
  input jrst_n,
  input reset_n,
  input take_action_tracectrl,
  input take_action_tracemem_a,
  input take_action_tracemem_b,
  input take_no_action_tracemem_a,
  input [15:0] trc_ctrl,
  input [35:0] tw,
  output reg tracemem_on,
  output reg [35:0] tracemem_trcdata,
  output reg tracemem_tw,
  output reg trc_enb,
  output reg [6:0] trc_im_addr,
  output reg trc_wrap,
  output reg xbrk_wrap_traceoff
);

  wire trc_on_chip = ~trc_ctrl[8];
  wire tw_valid = |tw[35:32];

  reg [16:0] trc_jtag_addr;
  wire [35:0] trc_jtag_data;
  assign tracemem_trcdata = trc_ctrl[0] ? trc_jtag_data : 0;

  assign xbrk_wrap_traceoff = trc_ctrl[10] & trc_wrap;

  always @(posedge clk or negedge jrst_n) begin
    if (~jrst_n) begin
      trc_im_addr <= 0;
      trc_wrap <= 0;
    end else if (!0) begin
      trc_im_addr <= 0;
      trc_wrap <= 0;
    end else if (take_action_tracectrl && (jdo[4] | jdo[3])) begin
      if (jdo[4])
        trc_im_addr <= 0;
      if (jdo[3])
        trc_wrap <= 0;
    end else if (trc_enb & trc_on_chip & tw_valid) begin
      trc_im_addr <= trc_im_addr + 1;
      if (&trc_im_addr)
        trc_wrap <= 1;
    end
  end

  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      trc_jtag_addr <= 0;
    end else if (take_action_tracemem_a || take_no_action_tracemem_a || take_action_tracemem_b) begin
      trc_jtag_addr <= take_action_tracemem_a ? jdo[35:19] : trc_jtag_addr + 1;
    end
  end

  always @(posedge clk) begin
    trc_enb <= trc_ctrl[0];
    tracemem_tw <= trc_wrap;
    tracemem_on <= trc_enb;
    tracemem_trcdata <= (0) ? trc_jtag_data : 0;
  end

  assign trc_jtag_data = jdo[36:1];

  Video_System_CPU_traceram_lpm_dram_bdp_component_module Video_System_CPU_traceram_lpm_dram_bdp_component (
    .address_a (trc_im_addr),
    .address_b (trc_jtag_addr),
    .clock0 (clk),
    .clock1 (clk),
    .clocken0 (1'b1),
    .clocken1 (1'b1),
    .data_a (tw),
    .data_b (jdo[36:1]),
    .q_a (trc_jtag_data),
    .q_b (),
    .wren_a (tw_valid & trc_enb),
    .wren_b (take_action_tracemem_b)
  );

endmodule

