module calculator(
    input clk,
    input [7:0] A,
    input [7:0] B,
    input [1:0] operation,
    output reg [15:0] result
);

    reg [15:0] temp;

    always @(posedge clk) begin
        case(operation)
            2'b00: // addition
                temp = {8'b0, A} + {8'b0, B};
            2'b01: // subtraction
                temp = {8'b0, A} - {8'b0, B};
            2'b10: // multiplication
                temp = {16'b0, A} * {16'b0, B};
            2'b11: // division
                temp = {16'b0, A} / {16'b0, B};
        endcase

        result <= temp;
    end
endmodule

module pipelined_dff (
    input clk,
    input reset,
    input [7:0] d,
    output [7:0] q
);

    reg [7:0] q_reg [0:7];
    reg [7:0] d_reg [0:7];

    always @(posedge clk) begin
        q_reg[0] <= (reset) ? 8'h34 : d_reg[0];
        q_reg[1] <= d_reg[0];
        q_reg[2] <= d_reg[1];
        q_reg[3] <= d_reg[2];
        q_reg[4] <= d_reg[3];
        q_reg[5] <= d_reg[4];
        q_reg[6] <= d_reg[5];
        q_reg[7] <= d_reg[6];
    end

    always @(posedge clk) begin
        d_reg[0] <= (reset) ? 8'h34 : d;
        d_reg[1] <= q_reg[0];
        d_reg[2] <= q_reg[1];
        d_reg[3] <= q_reg[2];
        d_reg[4] <= q_reg[3];
        d_reg[5] <= q_reg[4];
        d_reg[6] <= q_reg[5];
        d_reg[7] <= q_reg[6];
    end

    assign q = q_reg[7];

endmodule

