module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

wire [3:0] sum;
wire overflow;

assign sum = A + B + Cin;
assign Cout = (sum > 4'hF) ? 1 : 0;
assign S = (overflow) ? sum[2:0] : sum[3:0];

endmodule

module adder_4bit (
    input [3:0] A,
    input [3:0] B,
    output [3:0] sum
);

    wire c1, c2, c3;

    // 1st bit addition
    full_adder fa1(.a(A[0]), .b(B[0]), .cin(0), .sum(sum[0]), .cout(c1));

    // 2nd bit addition
    full_adder fa2(.a(A[1]), .b(B[1]), .cin(c1), .sum(sum[1]), .cout(c2));

    // 3rd bit addition
    full_adder fa3(.a(A[2]), .b(B[2]), .cin(c2), .sum(sum[2]), .cout(c3));

    // 4th bit addition
    full_adder fa4(.a(A[3]), .b(B[3]), .cin(c3), .sum(sum[3]), .cout(0));

endmodule

module full_adder (
    input a, b, cin,
    output sum, cout
);

    wire s1, c1, c2;

    xor x1(s1, a, b);
    xor x2(sum, s1, cin);
    and a1(c1, s1, cin);
    and a2(c2, a, b);
    or (cout, c1, c2);

endmodule

module bin_to_bcd (
  input [3:0] bin,
  output [3:0] bcd1,
  output [3:0] bcd2,
  output [3:0] bcd3,
  output [3:0] bcd4
);

  reg [7:0] decimal;
  reg [3:0] quotient;
  reg [3:0] remainder;

  always @(*) begin
    decimal = bin[3]*2**3 + bin[2]*2**2 + bin[1]*2**1 + bin[0]*2**0;
    quotient = decimal / 10;
    remainder = decimal % 10;
    bcd1 = remainder;
    bcd2 = quotient % 10;
    bcd3 = (quotient / 10) % 10;
    bcd4 = (quotient / 100) % 10;
  end

endmodule

module lcd_driver (
  input [3:0] data,
  input [1:0] ctrl,
  output [6:0] seg
);

  // Define the 7-bit segment signal as a Boolean function of the 4-bit data signal and the 2-bit control signal
  assign seg[0] = (data[0] & ctrl[0]) | (~data[0] & ctrl[1]);
  assign seg[1] = (data[1] & ctrl[0]) | (~data[1] & ctrl[1]);
  assign seg[2] = (data[2] & ctrl[0]) | (~data[2] & ctrl[1]);
  assign seg[3] = (data[3] & ctrl[0]) | (~data[3] & ctrl[1]);
  assign seg[4] = ctrl[0];
  assign seg[5] = ctrl[1];
  assign seg[6] = 0;

endmodule

module picorv32_axi_adapter (
			     input 	   clk, resetn,

			     // AXI4-lite master memory interface

			     output 	   mem_axi_awvalid,
			     input 	   mem_axi_awready,
			     output [31:0] mem_axi_awaddr,
			     output [ 2:0] mem_axi_awprot,

			     output 	   mem_axi_wvalid,
			     input 	   mem_axi_wready,
			     output [31:0] mem_axi_wdata,
			     output [ 3:0] mem_axi_wstrb,

			     input 	   mem_axi_bvalid,
			     output 	   mem_axi_bready,

			     output 	   mem_axi_arvalid,
			     input 	   mem_axi_arready,
			     output [31:0] mem_axi_araddr,
			     output [ 2:0] mem_axi_arprot,

			     input 	   mem_axi_rvalid,
			     output 	   mem_axi_rready,
			     input [31:0]  mem_axi_rdata,

			     // Native PicoRV32 memory interface

			     input 	   mem_valid,
			     input 	   mem_instr,
			     output 	   mem_ready,
			     input [31:0]  mem_addr,
			     input [31:0]  mem_wdata,
			     input [ 3:0]  mem_wstrb,
			     output [31:0] mem_rdata
			     );
   reg 					   ack_awvalid;
   reg 					   ack_arvalid;
   reg 					   ack_wvalid;
   reg 					   xfer_done;

   assign mem_axi_awvalid = mem_valid && |mem_wstrb && !ack_awvalid;
   assign mem_axi_awaddr = mem_addr;
   assign mem_axi_awprot = 0;

   assign mem_axi_arvalid = mem_valid && !mem_wstrb && !ack_arvalid;
   assign mem_axi_araddr = mem_addr;
   assign mem_axi_arprot = mem_instr ? 3'b100 : 3'b000;

   assign mem_axi_wvalid = mem_valid && |mem_wstrb && !ack_wvalid;
   assign mem_axi_wdata = mem_wdata;
   assign mem_axi_wstrb = mem_wstrb;

   assign mem_ready = mem_axi_bvalid || mem_axi_rvalid;
   assign mem_axi_bready = mem_valid && |mem_wstrb;
   assign mem_axi_rready = mem_valid && !mem_wstrb;
   assign mem_rdata = mem_axi_rdata;

   always @(posedge clk) begin
      if (!resetn) begin
	 ack_awvalid <= 0;
      end else begin
	 xfer_done <= mem_valid && mem_ready;
	 if (mem_axi_awready && mem_axi_awvalid)
	   ack_awvalid <= 1;
	 if (mem_axi_arready && mem_axi_arvalid)
	   ack_arvalid <= 1;
	 if (mem_axi_wready && mem_axi_wvalid)
	   ack_wvalid <= 1;
	 if (xfer_done || !mem_valid) begin
	    ack_awvalid <= 0;
	    ack_arvalid <= 0;
	    ack_wvalid <= 0;
	 end
      end
   end
endmodule

