module graphics(
	clk,
	candraw,
	x,
	y,
	p1_y,
	p2_y,
	ball_on,
	ball_x,
	ball_y,
	red, 
	green, 
	blue,
	vga_blank
	);

	input clk;
	input candraw;
	input ball_on;
	input [10:0] x, y, p1_y, p2_y, ball_x, ball_y;
	output reg [9:0] red, green, blue;
	output vga_blank;

	reg n_vga_blank;
	assign vga_blank = !n_vga_blank;

	always @(posedge clk) begin
		if (candraw) begin
			n_vga_blank <= 1'b0;
			// draw P1 (left) bat
			if (x < 10 && y > p1_y && y < p1_y + 40) begin
					// white bat
					red <= 10'b1111111111;
					green <= 10'b1111111111;
					blue <= 10'b1111111111;
			end
			// draw P2 (right) bat
			else if (x > 630 && y > p2_y && y < p2_y + 40) begin
					// white bat
					red <= 10'b1111111111;
					green <= 10'b1111111111;
					blue <= 10'b1111111111;
			end
			// draw ball
			else if (ball_on && x > ball_x && x < ball_x + 10 && y > ball_y && y < ball_y + 10) begin
					// white ball
					red <= 10'b1111111111;
					green <= 10'b1111111111;
					blue <= 10'b1111111111;
			end
			// black background
			else begin
					red <= 10'b0000000000;
					green <= 10'b0000000000;
					blue <= 10'b0000000000;
			end
		end else begin
			// if we are not in the visible area, we must set the screen blank
			n_vga_blank <= 1'b1;
		end
	end
endmodule

module DataBuffer(
    input wire [7:0] data_in,
    input wire enable_in,
    input wire clk,
    output reg [7:0] data_out,
    output reg enable_out
);

    parameter buffer_size = 8;
    reg [7:0] buffer [0:buffer_size-1];
    reg [2:0] head = 0;
    reg [2:0] tail = 0;
    reg [2:0] num_items = 0;

    always @(posedge clk) begin
        if (enable_in && num_items < buffer_size) begin
            buffer[head] <= data_in;
            head <= head + 1;
            num_items <= num_items + 1;
        end
        enable_out <= (num_items < buffer_size);
        data_out <= buffer[tail];
        if (num_items > 0) begin
            tail <= tail + 1;
            num_items <= num_items - 1;
        end
    end

endmodule

module memory_arbiter (
  input clk,
  input rst,
  input [n-1:0] req,
  input [m-1:0] addr,
  input [m-1:0] we,
  input [m-1:0] data_in,
  output [m-1:0] grant,
  output [m-1:0] data_out
);

parameter n = 4; // number of requestors
parameter m = 2; // number of memory access signals (address, write enable, data in/out)

reg [n-1:0] req_priority; // priority of each requestor
reg [n-1:0] req_granted; // requestor currently granted access
reg [m-1:0] mem_addr; // address of memory access
reg [m-1:0] mem_we; // write enable of memory access
reg [m-1:0] mem_data_in; // data input of memory access
reg [m-1:0] mem_data_out; // data output of memory access
reg [m-1:0] grant_temp; // temporary grant signal

always @ (posedge clk or posedge rst) begin
  if (rst) begin
    req_priority <= 'b0;
    req_granted <= 'b0;
    mem_addr <= 'b0;
    mem_we <= 'b0;
    mem_data_in <= 'b0;
    mem_data_out <= 'b0;
    grant_temp <= 'b0;
  end else begin
    // set priority of each requestor based on request signal and type of request
    for (i = 0; i < n; i = i + 1) begin
      if (req[i]) begin
        if (we[i]) begin
          req_priority[i] <= 2'b10; // write request
        end else begin
          req_priority[i] <= 2'b01; // read request
        end
      end else begin
        req_priority[i] <= 2'b00; // no request
      end
    end

    // select requestor with highest priority
    for (i = 0; i < n; i = i + 1) begin
      if (req_priority[i] > req_priority[req_granted]) begin
        req_granted <= i;
      end
    end

    // generate grant signal for selected requestor
    grant_temp[req_granted] <= 1'b1;

    // forward memory access signals to memory
    mem_addr <= addr[req_granted];
    mem_we <= we[req_granted];
    mem_data_in <= data_in[req_granted];

    // forward data output signal from memory to selected requestor
    data_out[req_granted] <= mem_data_out;

    // forward data input signal from selected requestor to memory
    mem_data_out <= data_in[req_granted];

    // clear grant signal for all requestors except selected requestor
    for (i = 0; i < m; i = i + 1) begin
      if (i != req_granted) begin
        grant_temp[i] <= 1'b0;
      end
    end

    // prioritize write requests over read requests
    for (i = 0; i < n; i = i + 1) begin
      if (req_priority[i] == 2'b10 && i != req_granted) begin
        grant_temp[i] <= 1'b0;
      end
    end

    // update grant signal
    grant <= grant_temp;
  end
end

endmodule

module CDC_synchronizer (
  input data_in,
  input clk_source,
  input clk_dest,
  output reg data_out
);

  reg [1:0] source_ff;
  reg [1:0] dest_ff;

  always @(posedge clk_source) begin
    source_ff <= {source_ff[0], data_in};
  end

  always @(posedge clk_dest) begin
    dest_ff <= {dest_ff[0], source_ff[1]};
  end

  reg [1:0] metastable_ff;

  always @(posedge clk_dest) begin
    if (dest_ff[1] == metastable_ff[0]) begin
      metastable_ff <= {dest_ff[1], dest_ff[1]};
    end else begin
      metastable_ff <= {dest_ff[1], metastable_ff[1]};
    end
  end

  always @(posedge clk_dest) begin
    data_out <= metastable_ff[1];
  end

endmodule

module verilog_module (y,a,b,c,d);
 output y;
 input a;
 input b;
 input c;
 input d;

 reg yi;

  always @(a or b or c or d) begin
   if (((a&b) | (a&c) | (a&d) | (b&c) | (b&d))) 
    begin
      yi <=  1;
    end
    else if (((a==0) & (b==0) & (c==0) & (d==0))) 
    begin
      yi <=  0;
    end
   end
  assign #1 y = yi; 
endmodule

module watchdog_timer (
  input clk,
  input reset,
  input [31:0] timeout,
  output wd_reset
);

  reg [31:0] counter;
  reg wd_reset_reg;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      counter <= 0;
      wd_reset_reg <= 0;
    end
    else begin
      counter <= counter + 1;
      if (counter == timeout) begin
        wd_reset_reg <= 1;
      end
      else begin
        wd_reset_reg <= 0;
      end
    end
  end

  assign wd_reset = wd_reset_reg;

endmodule

module sign_extension (
    input [7:0] in,
    output signed [15:0] out
);
    assign out = {{8{in[7]}}, in};
endmodule

module multiplier (
    input signed [7:0] a,
    input signed [7:0] b,
    output signed [15:0] out
);
    wire signed [15:0] temp;
    assign temp = a * b;
    assign out = temp;
endmodule

module multiplier_16bit (
    input signed [15:0] a,
    input signed [15:0] b,
    output signed [31:0] out
);
    wire signed [15:0] a_low, b_low;
    wire signed [31:0] temp1, temp2, temp3;
    sign_extension se1(.in(a[7:0]), .out(a_low));
    sign_extension se2(.in(b[7:0]), .out(b_low));
    multiplier mul1(.a(a[7:0]), .b(b[7:0]), .out(temp1));
    multiplier mul2(.a(a_low), .b(b_low), .out(temp2));
    multiplier mul3(.a(a[7:0]), .b(b_low), .out(temp3));
    assign out = temp1 + (temp2 << 16) + (temp3 << 8);
endmodule

module priority_encoder (
    input signed [15:0] in1, in2, in3, in4,
    output signed [15:0] max
);
    wire signed [15:0] temp1, temp2, temp3;
    assign temp1 = (in1 > in2) ? in1 : in2;
    assign temp2 = (in3 > in4) ? in3 : in4;
    assign temp3 = (temp1 > temp2) ? temp1 : temp2;
    assign max = temp3;
endmodule

module top_module (
    input signed [15:0] a,
    input signed [15:0] b,
    input [15:0] in1, in2, in3, in4,
    output [15:0] max,
    output signed [15:0] diff
);
    wire signed [31:0] mul_out;
    wire signed [15:0] max_out;
    multiplier_16bit mul(.a(a), .b(b), .out(mul_out));
    priority_encoder pe(.in1(in1), .in2(in2), .in3(in3), .in4(in4), .max(max_out));
    assign diff = mul_out - max_out;
    assign max = max_out;
endmodule

module mux4to1(
