always @ (*)
begin
    case ({S1, S0})
        2'b00: Y = A;
        2'b01: Y = B;
        2'b10: Y = C;
        2'b11: Y = D;
        default: Y = 1'bx;
    endcase
end

endmodule

module top_module (
    input clk,
    input slowena,     // Pause and resume counting signal
    input reset,       // Asynchronous reset
    input [1:0] a,     // 2-bit input for the decoder
    input [1:0] b,     // 2-bit input for the decoder
    output [7:0] q     // 8-bit output from the functional module
);

    // Decoder module
    wire [15:0] dec_out;
    decoder_4to16 dec_inst (
        .in({a,b}),
        .out(dec_out)
    );

    // Counter module
    reg [3:0] count;
    always @(posedge clk or negedge reset) begin
        if (reset == 0) begin
            count <= 0;
        end else if (slowena == 1) begin
            count <= count + 1;
        end
    end

    // Functional module
    wire [3:0] dec_index;
    assign dec_index = dec_out[15:12];
    wire [3:0] count_index;
    assign count_index = count[3:0];
    wire [7:0] add_out;
    adder add_inst (
        .in1(dec_index),
        .in2(count_index),
        .out(add_out)
    );
    assign q = add_out;

endmodule

// 4-to-16 decoder module
module decoder_4to16 (
    input [1:0] in,
    output [15:0] out
);

    assign out = 16'b0000000000000001 << {in[1], in[0]};

endmodule

// 4-bit adder module
module adder (
    input [3:0] in1,
    input [3:0] in2,
    output [7:0] out
);

    assign out = {4'b0, in1} + {4'b0, in2};

endmodule

module axi_hdmi_rx_tpm (
  input           hdmi_clk,
  input           hdmi_sof,
  input           hdmi_de,
  input   [15:0]  hdmi_data,
  output reg      hdmi_tpm_oos
);

  reg     [15:0]  hdmi_tpm_data = 'd0;
  reg             hdmi_tpm_lr_mismatch = 'd0;
  reg             hdmi_tpm_fr_mismatch = 'd0;

  // Limited range
  assign hdmi_tpm_data[15:8] = (hdmi_data[15:8] < 8'h10) ? 8'h10 :
    ((hdmi_data[15:8] > 8'heb) ? 8'heb : hdmi_data[15:8]);
  assign hdmi_tpm_data[ 7:0] = (hdmi_data[ 7:0] < 8'h10) ? 8'h10 :
    ((hdmi_data[ 7:0] > 8'heb) ? 8'heb : hdmi_data[ 7:0]);
  assign hdmi_tpm_lr_mismatch = (hdmi_tpm_data != hdmi_data);

  // Full range
  assign hdmi_tpm_data[15:8] = (hdmi_data[15:8] < 8'h01) ? 8'h01 :
    ((hdmi_data[15:8] > 8'hfe) ? 8'hfe : hdmi_data[15:8]);
  assign hdmi_tpm_data[ 7:0] = (hdmi_data[ 7:0] < 8'h01) ? 8'h01 :
    ((hdmi_data[ 7:0] > 8'hfe) ? 8'hfe : hdmi_data[ 7:0]);
  assign hdmi_tpm_fr_mismatch = (hdmi_tpm_data != hdmi_data);

  always @(posedge hdmi_clk) begin
    if (hdmi_sof == 1'b1) begin
      hdmi_tpm_data <= 16'd0;
      hdmi_tpm_lr_mismatch <= 1'd0;
      hdmi_tpm_fr_mismatch <= 1'd0;
      hdmi_tpm_oos <= 1'b0;
    end else if (hdmi_de == 1'b1) begin
      hdmi_tpm_data <= hdmi_tpm_data + 1'b1;
      hdmi_tpm_oos <= hdmi_tpm_lr_mismatch | hdmi_tpm_fr_mismatch;
    end
  end

endmodule

module debounce_count_up_down (
    input CLK_IN,
    input reset,
    input enb,
    input u,
    input [7:0] count_debounce,
    output reg [7:0] y
);

    reg u_n1;
    reg [7:0] count;
    reg y_reg;
    reg u_n1_next;
    reg [7:0] count_next;
    reg y_reg_next;
    reg [8:0] add_temp_1;

    always @(posedge CLK_IN) begin
        if (reset) begin
            u_n1 <= 1'b0;
            count <= 8'd0;
            y_reg <= 1'b0;
        end else if (enb) begin
            u_n1 <= u_n1_next;
            count <= count_next;
            y_reg <= y_reg_next;
        end
    end

    always @(u, u_n1, count, count_debounce, y_reg) begin
        count_next = count;
        y_reg_next = y_reg;
        if (u == u_n1) begin
            if (count >= count_debounce) begin
                y_reg_next = u;
            end else begin
                add_temp_1 = count + 1;
                if (add_temp_1[8]) begin
                    count_next = 8'b11111111;
                end else begin
                    count_next = add_temp_1[7:0];
                end
            end
        end else begin
            count_next = count - 1 + 2*u;
        end
        u_n1_next = u;
    end

    assign y = y_reg_next;

endmodule

module crossbar_switch (
  input aclk,
  input aresetn_d,
  input mi_arready,
  input mi_rvalid,
  input mi_wready,
  input s_axi_bready,
  input s_axi_wvalid,
  input [1:0] m_atarget_enc,
  input [1:0] m_axi_bvalid,
  input [1:0] m_axi_wready,
  output reg mi_arready_out,
  output reg mi_rvalid_out,
  output reg mi_wready_out,
  output reg s_axi_bready_out,
  output reg s_axi_wvalid_out
);

reg [1:0] m_atarget_enc_reg;
reg [1:0] m_axi_bvalid_reg;
reg [1:0] m_axi_wready_reg;
reg mi_arready_reg;
reg mi_rvalid_reg;
reg mi_wready_reg;
reg s_axi_bready_reg;
reg s_axi_wvalid_reg;

always @(posedge aclk) begin
  if (!aresetn_d) begin
    m_atarget_enc_reg <= 2'b0;
    m_axi_bvalid_reg <= 2'b0;
    m_axi_wready_reg <= 2'b0;
    mi_arready_reg <= 1'b0;
    mi_rvalid_reg <= 1'b0;
    mi_wready_reg <= 1'b0;
    s_axi_bready_reg <= 1'b0;
    s_axi_wvalid_reg <= 1'b0;
  end else begin
    m_atarget_enc_reg <= m_atarget_enc;
    m_axi_bvalid_reg <= m_axi_bvalid;
    m_axi_wready_reg <= m_axi_wready;
    mi_arready_reg <= mi_arready;
    mi_rvalid_reg <= mi_rvalid;
    mi_wready_reg <= mi_wready;
    s_axi_bready_reg <= s_axi_bready;
    s_axi_wvalid_reg <= s_axi_wvalid;
  end
end

// Master 1
assign mi_arready_out = (m_atarget_enc_reg == 2'b00) ? s_axi_wvalid_reg : mi_arready_reg;
assign mi_rvalid_out = (m_atarget_enc_reg == 2'b00) ? s_axi_bready_reg : mi_rvalid_reg;
assign mi_wready_out = (m_atarget_enc_reg == 2'b00) ? s_axi_wvalid_reg : mi_wready_reg;

// Master 2
assign mi_arready_out = (m_atarget_enc_reg == 2'b01) ? s_axi_wvalid_reg : mi_arready_out;
assign mi_rvalid_out = (m_atarget_enc_reg == 2'b01) ? s_axi_bready_reg : mi_rvalid_out;
assign mi_wready_out = (m_atarget_enc_reg == 2'b01) ? s_axi_wvalid_reg : mi_wready_out;

// Slave 1
assign s_axi_bready_out = (m_atarget_enc_reg == 2'b10) ? mi_wready_reg : s_axi_bready_reg;
assign s_axi_wvalid_out = (m_atarget_enc_reg == 2'b10) ? mi_wready_reg : s_axi_wvalid_reg;

// Slave 2
assign s_axi_bready_out = (m_atarget_enc_reg == 2'b11) ? mi_wready_reg : s_axi_bready_out;
assign s_axi_wvalid_out = (m_atarget_enc_reg == 2'b11) ? mi_wready_reg : s_axi_wvalid_out;

endmodule

module top_module (
    input [15:0] A,
    input [15:0] B,
    input sub,
    input cin,
    output [15:0] result,
    output cout,
    output bout
);

    wire [3:0] G, P, C;
    wire [3:0] addsub_out;
    wire [3:0] cin_vec;

    // Instantiate the given modules
    addsub addsub_inst (
        .A(A[3:0]),
        .B(B[3:0]),
        .ctrl(sub),
        .Y(addsub_out)
    );

    addsub addsub_inst2 (
        .A(A[7:4]),
        .B(B[7:4]),
        .ctrl(sub),
        .Y(addsub_out[4:7])
    );

    addsub addsub_inst3 (
        .A(A[11:8]),
        .B(B[11:8]),
        .ctrl(sub),
        .Y(addsub_out[8:11])
    );

    addsub addsub_inst4 (
        .A(A[15:12]),
        .B(B[15:12]),
        .ctrl(sub),
        .Y(addsub_out[12:15])
    );

    cla cla_inst (
        .A(addsub_out),
        .B(cin_vec),
        .G(G),
        .P(P),
        .C(C)
    );

    assign cin_vec = {cin, C[3:1]};

    assign result = {G[3], P[3:0]} + addsub_out + cin_vec;

    assign cout = C[3];

    assign bout = ~C[3] & sub;

endmodule

module addsub (
    input [3:0] A,
    input [3:0] B,
    input ctrl,
    output reg [3:0] Y
);

    always @(*) begin
        if (ctrl == 1) begin
            Y = A - B;
        end else begin
            Y = A + B;
        end
    end

endmodule

module cla (
    input [3:0] A,
    input [3:0] B,
    output [3:0] G,
    output [3:0] P,
    output [3:0] C
);

    assign G = A & B;
    assign P = A ^ B;
    assign C[0] = G[0] | (P[0] & B[0]) | (P[0] & A[0]);
    assign C[1] = G[1] | (P[1] & B[1]) | (P[1] & A[1]) | C[0] & (P[0] | G[0]);
    assign C[2] = G[2] | (P[2] & B[2]) | (P[2] & A[2]) | C[1] & (P[1] | G[1]);
    assign C[3] = G[3] | (P[3] & B[3]) | (P[3] & A[3]) | C[2] & (P[2] | G[2]);

endmodule

module dff_async_set_reset (
    output reg Q,
