module fifo_buffer (
    input clk,
    input resetn,
    input enable,
    output enabled,
    input sync_id,
    output sync_id_ret,
    input [C_ID_WIDTH-1:0] request_id,
    output [C_ID_WIDTH-1:0] response_id,
    input eot,
    input en,
    input [C_DATA_WIDTH-1:0] din,
    output reg overflow,
    input sync,
    input fifo_ready,
    output fifo_valid,
    output [C_DATA_WIDTH-1:0] fifo_data,
    input req_valid,
    output req_ready,
    input [3:0] req_last_burst_length,
    input req_sync_transfer_start
);

parameter C_ID_WIDTH = 3;
parameter C_DATA_WIDTH = 64;
parameter C_LENGTH_WIDTH = 24;

reg [C_DATA_WIDTH-1:0] buffer [0:C_LENGTH_WIDTH-1];
reg [C_ID_WIDTH-1:0] id_buffer [0:C_LENGTH_WIDTH-1];
reg [C_DATA_WIDTH-1:0] output_buffer;
reg [C_ID_WIDTH-1:0] output_id_buffer;
reg [C_LENGTH_WIDTH-1:0] length;
wire [C_LENGTH_WIDTH-1:0] next_length;
reg [C_LENGTH_WIDTH-1:0] next_length_reg;
reg valid = 1'b0;
wire ready;
reg [C_DATA_WIDTH-1:0] buffer_reg = 'h00;
reg buffer_sync = 1'b0;
reg [C_ID_WIDTH-1:0] id_buffer_reg = 'h00;
reg needs_sync = 1'b0;
wire has_sync = ~needs_sync | buffer_sync;
wire sync_valid = valid & has_sync;

assign sync_id_ret = sync_id;

always @(posedge clk)
begin
    if (resetn == 1'b0) begin
        enabled <= 1'b0;
        valid <= 1'b0;
        length <= 0;
        next_length_reg <= 0;
        buffer_sync <= 1'b0;
        needs_sync <= 1'b0;
        overflow <= 1'b0;
    end else begin
        if (enable) begin
            enabled <= 1'b1;
            if (en) begin
                if (length < C_LENGTH_WIDTH) begin
                    buffer[length] <= din;
                    id_buffer[length] <= request_id;
                    length <= length + 1;
                    overflow <= 1'b0;
                end else if (fifo_ready) begin
                    output_buffer <= buffer[0];
                    output_id_buffer <= id_buffer[0];
                    for (i = 0; i < C_LENGTH_WIDTH - 1; i = i + 1) begin
                        buffer[i] <= buffer[i+1];
                        id_buffer[i] <= id_buffer[i+1];
                    end
                    buffer[C_LENGTH_WIDTH-1] <= din;
                    id_buffer[C_LENGTH_WIDTH-1] <= request_id;
                    overflow <= 1'b0;
                end else begin
                    overflow <= 1'b1;
                end
            end else if (ready) begin
                length <= length - 1;
                for (i = 0; i < C_LENGTH_WIDTH - 1; i = i + 1) begin
                    buffer[i] <= buffer[i+1];
                    id_buffer[i] <= id_buffer[i+1];
                end
                buffer[C_LENGTH_WIDTH-1] <= buffer_reg;
                id_buffer[C_LENGTH_WIDTH-1] <= id_buffer_reg;
            end
            buffer_reg <= din;
            buffer_sync <= sync;
            id_buffer_reg <= request_id;
            valid <= 1'b1;
            needs_sync <= req_sync_transfer_start;
        end else begin
            enabled <= 1'b0;
            valid <= 1'b0;
            length <= 0;
            next_length_reg <= 0;
            buffer_sync <= 1'b0;
            needs_sync <= 1'b0;
            overflow <= 1'b0;
        end
    end
end

dmac_data_mover # (
    .C_ID_WIDTH(C_ID_WIDTH),
    .C_DATA_WIDTH(C_DATA_WIDTH),
    .C_DISABLE_WAIT_FOR_ID(0)
) i_data_mover (
    .clk(clk),
    .resetn(resetn),
    .enable(enable),
    .enabled(enabled),
    .sync_id(sync_id),
    .request_id(request_id),
    .response_id(response_id),
    .eot(eot),
    .req_valid(req_valid),
    .req_ready(req_ready),
    .req_last_burst_length(req_last_burst_length),
    .s_axi_ready(ready),
    .s_axi_valid(sync_valid),
    .s_axi_data(output_buffer),
    .s_axi_id(output_id_buffer),
    .m_axi_ready(fifo_ready),
    .m_axi_valid(fifo_valid),
    .m_axi_data(fifo_data),
    .m_axi_id(next_length)
);

always @(posedge clk)
begin
    if (resetn == 1'b0) begin
        next_length_reg <= 0;
    end else begin
        if (req_valid && req_ready) begin
            if (next_length_reg < req_last_burst_length - 1) begin
                next_length_reg <= next_length_reg + 1;
            end else begin
                next_length_reg <= 0;
            end
        end
    end
end

assign next_length = next_length_reg;

endmodule

module bitwise_and(
    input [31:0] a,
    input [31:0] b,
    output [31:0] out
);

    wire [31:0] carry;
    wire [31:0] g;
    wire [31:0] p;

    assign g = a & b;
    assign p = a | b;

    assign carry[0] = g[0];
    assign out[0] = g[0];

    genvar i;
    generate
        for (i = 1; i < 32; i = i + 1) begin
            assign carry[i] = g[i] | (p[i] & carry[i-1]);
            assign out[i] = g[i] ^ (p[i] & carry[i-1]);
        end
    endgenerate

endmodule

