module FFT_IFFT (
  input [n-1:0] in_real,
  input [n-1:0] in_imag,
  output [n-1:0] out_real,
  output [n-1:0] out_imag
);

parameter n = 8; // number of complex input and output samples

reg [n-1:0] mem_real [0:n-1];
reg [n-1:0] mem_imag [0:n-1];

integer i, j, k;
reg [n-1:0] temp_real, temp_imag;
reg [n-1:0] w_real, w_imag;

always @(*) begin
  // Store input samples in memory
  for (i = 0; i < n; i = i + 1) begin
    mem_real[i] = in_real[i];
    mem_imag[i] = in_imag[i];
  end

  // Compute FFT
  for (i = 0; i < $clog2(n); i = i + 1) begin
    for (j = 0; j < n; j = j + (1 << (i + 1))) begin
      for (k = 0; k < (1 << i); k = k + 1) begin
        w_real = $cos(2 * $pi * k / (1 << (i + 1)));
        w_imag = -$sin(2 * $pi * k / (1 << (i + 1)));

        temp_real = mem_real[j + k] - w_real * mem_real[j + k + (1 << i)] - w_imag * mem_imag[j + k + (1 << i)];
        temp_imag = mem_imag[j + k] - w_real * mem_imag[j + k + (1 << i)] + w_imag * mem_real[j + k + (1 << i)];

        mem_real[j + k] = mem_real[j + k] + w_real * mem_real[j + k + (1 << i)] + w_imag * mem_imag[j + k + (1 << i)];
        mem_imag[j + k] = mem_imag[j + k] + w_real * mem_imag[j + k + (1 << i)] - w_imag * mem_real[j + k + (1 << i)];

        mem_real[j + k + (1 << i)] = temp_real;
        mem_imag[j + k + (1 << i)] = temp_imag;
      end
    end
  end

  // Compute IFFT
  for (i = 0; i < n; i = i + 1) begin
    mem_imag[i] = -mem_imag[i];
  end

  for (i = 0; i < $clog2(n); i = i + 1) begin
    for (j = 0; j < n; j = j + (1 << (i + 1))) begin
      for (k = 0; k < (1 << i); k = k + 1) begin
        w_real = $cos(2 * $pi * k / (1 << (i + 1)));
        w_imag = -$sin(2 * $pi * k / (1 << (i + 1)));

        temp_real = mem_real[j + k] - w_real * mem_real[j + k + (1 << i)] - w_imag * mem_imag[j + k + (1 << i)];
        temp_imag = mem_imag[j + k] - w_real * mem_imag[j + k + (1 << i)] + w_imag * mem_real[j + k + (1 << i)];

        mem_real[j + k] = mem_real[j + k] + w_real * mem_real[j + k + (1 << i)] + w_imag * mem_imag[j + k + (1 << i)];
        mem_imag[j + k] = mem_imag[j + k] + w_real * mem_imag[j + k + (1 << i)] - w_imag * mem_real[j + k + (1 << i)];

        mem_real[j + k + (1 << i)] = temp_real;
        mem_imag[j + k + (1 << i)] = temp_imag;
      end
    end
  end

  for (i = 0; i < n; i = i + 1) begin
    mem_real[i] = mem_real[i] / n;
    mem_imag[i] = -mem_imag[i] / n;
  end

  // Output results
  for (i = 0; i < n; i = i + 1) begin
    out_real[i] = mem_real[i];
    out_imag[i] = mem_imag[i];
  end
end

endmodule

module simple_timer(clk, reset_n, start, count_target, count, done);

    parameter COUNT_WIDTH = 32;
    parameter CLK_FREQ = 50_000_000;

    input clk;
    input reset_n;
    input start;
    input [COUNT_WIDTH-1:0] count_target;

    output reg [COUNT_WIDTH-1:0] count;
    output reg done;

    reg [COUNT_WIDTH-1:0] next_count;

    always @(posedge clk, negedge reset_n) begin
        if(!reset_n) begin
            count <= 0;
            done <= 0;
        end
        else if(start) begin
            next_count <= count + 1;
            count <= next_count;
            if(next_count == count_target) begin
                done <= 1;
            end
        end
        else begin
            done <= 0;
        end
    end
endmodule

