module mux (
    input [15:0] in1,  // Input 1 for the multiplexer
    input [15:0] in2,  // Input 2 for the multiplexer
    input select,      // Select input for the multiplexer
    output reg [15:0] y // Selected output from the multiplexer
);

    always @ (in1, in2, select) begin
        if (select == 1'b0) begin
            y = in1;
        end else begin
            y = in2;
        end
    end

endmodule

module bcd_counter (
    input clk,
    input reset,       // Synchronous active-high reset
    input [3:1] ena,   // Enable signals for the upper three digits
    output [15:0] q    // 16-bit binary-coded decimal output from the counter
);

    reg [3:0] count [3:0];
    reg [3:0] bcd [3:0];

    always @ (posedge clk, posedge reset) begin
        if (reset) begin
            count <= 0;
            bcd <= 0;
        end else begin
            count[0] <= count[0] + 1;
            if (count[0] == 10) begin
                count[0] <= 0;
                bcd[0] <= bcd[0] + 1;
            end

            if (ena[1]) begin
                count[1] <= count[1] + 1;
                if (count[1] == 10) begin
                    count[1] <= 0;
                    bcd[1] <= bcd[1] + 1;
                end

                if (ena[2]) begin
                    count[2] <= count[2] + 1;
                    if (count[2] == 10) begin
                        count[2] <= 0;
                        bcd[2] <= bcd[2] + 1;
                    end

                    if (ena[3]) begin
                        count[3] <= count[3] + 1;
                        if (count[3] == 10) begin
                            count[3] <= 0;
                            bcd[3] <= bcd[3] + 1;
                        end
                    end
                end
            end

            q = {bcd[3], bcd[2], bcd[1], bcd[0]};
        end
    end

endmodule

module functional_module (
    input [15:0] in1,  // Input 1 from the multiplexer
    input [15:0] in2,  // Input 2 from the multiplexer
    input [15:0] in3,  // Input from the counter
    output [15:0] y    // 16-bit binary-coded decimal output from the functional module
);

    assign y = in1 + in2 + in3;

endmodule

module arithmetic(
    input clk,
    input rst,
    input ena,
    input [3:0] opc,
    input [15:0] regA,
    input [15:0] regB,
    input [3:0] shift,
    input [3:0] bit,
    input set,
    output [15:0] result,
    output carry,
    output zero,
    output overflow
);

    reg [15:0] temp;
    wire [15:0] shifted;
    wire [15:0] anded;
    wire [15:0] ored;
    wire [15:0] xored;
    wire [15:0] shiftedRegA;
    wire [15:0] shiftedRegB;
    wire [15:0] shiftedResult;
    wire [15:0] shiftedTemp;
    reg [15:0] bitMask;
    wire [15:0] bitResult;
    wire [15:0] andResult;
    reg [15:0] orMask;
    wire [15:0] orResult;
    wire [15:0] xorResult;
    wire [15:0] addResult;
    wire [15:0] subResult;
    wire [15:0] subRegB;
    wire [15:0] notRegB;
    wire [15:0] shiftedNotRegB;
    wire [15:0] shiftedSubRegB;
    wire [15:0] shiftedAddResult;
    wire [15:0] shiftedSubResult;
    wire [15:0] shiftedAndResult;
    wire [15:0] shiftedOrResult;
    wire [15:0] shiftedXorResult;
    wire [15:0] shiftedBitResult;
    reg carryReg;
    reg zeroReg;
    reg overflowReg;

    assign shifted = (shift == 0) ? 16'b0 : (opc[3] == 0) ? {regB[15-shift+1:0],16'b0} : {16'b0,regB[15:shift]};
    assign anded = regA & regB;
    assign ored = regA | regB;
    assign xored = regA ^ regB;
    assign shiftedRegA = (shift == 0) ? regA : (opc[3] == 0) ? {regA[15-shift+1:0],16'b0} : {16'b0,regA[15:shift]};
    assign shiftedRegB = shifted;
    assign shiftedResult = (shift == 0) ? temp : (opc[3] == 0) ? {temp[15-shift+1:0],16'b0} : {16'b0,temp[15:shift]};
    assign shiftedTemp = (shift == 0) ? temp : (opc[3] == 0) ? {temp[15-shift+1:0],16'b0} : {16'b0,temp[15:shift]};
    assign bitMask = (1 << bit);
    assign bitResult = (set == 1) ? (regA | bitMask) : (regA & ~bitMask);
    assign andResult = anded;
    assign orMask = (set == 1) ? bitMask : ~bitMask;
    assign orResult = (regA & orMask) | (set << bit);
    assign xorResult = xored;
    assign addResult = regA + regB;
    assign subRegB = ~regB + 1;
    assign notRegB = ~regB;
    assign shiftedNotRegB = (shift == 0) ? notRegB : (opc[3] == 0) ? {notRegB[15-shift+1:0],16'b0} : {16'b0,notRegB[15:shift]};
    assign shiftedSubRegB = (shift == 0) ? subRegB : (opc[3] == 0) ? {subRegB[15-shift+1:0],16'b0} : {16'b0,subRegB[15:shift]};
    assign shiftedAddResult = (shift == 0) ? addResult : (opc[3] == 0) ? {addResult[15-shift+1:0],16'b0} : {16'b0,addResult[15:shift]};
    assign shiftedSubResult = (shift == 0) ? subResult : (opc[3] == 0) ? {subResult[15-shift+1:0],16'b0} : {16'b0,subResult[15:shift]};
    assign shiftedAndResult = (shift == 0) ? andResult : (opc[3] == 0) ? {andResult[15-shift+1:0],16'b0} : {16'b0,andResult[15:shift]};
    assign shiftedOrResult = (shift == 0) ? orResult : (opc[3] == 0) ? {orResult[15-shift+1:0],16'b0} : {16'b0,orResult[15:shift]};
    assign shiftedXorResult = (shift == 0) ? xorResult : (opc[3] == 0) ? {xorResult[15-shift+1:0],16'b0} : {16'b0,xorResult[15:shift]};
    assign shiftedBitResult = (shift == 0) ? bitResult : (opc[3] == 0) ? {bitResult[15-shift+1:0],16'b0} : {16'b0,bitResult[15:shift]};

    always @(posedge clk) begin
        if (rst == 1) begin
            temp <= 0;
            carryReg <= 0;
            zeroReg <= 0;
            overflowReg <= 0;
        end else if (ena == 1) begin
            case (opc)
                4'b0000: temp <= shiftedResult; // Shift Left Logical
                4'b0001: temp <= shiftedResult; // Shift Right Logical
                4'b0010: temp <= shiftedRegA + shiftedRegB; // Add
                4'b0011: temp <= shiftedRegA - shiftedSubRegB; // Subtract
                4'b0100: temp <= shiftedAndResult; // AND
                4'b0101: temp <= shiftedOrResult; // OR
                4'b0110: temp <= shiftedXorResult; // XOR
                4'b0111: temp <= shiftedBitResult; // Set or Clear Bit
                default: temp <= 0;
            endcase

            carryReg <= (temp[16] == 1);
            zeroReg <= (temp == 0);
            overflowReg <= ((regA[15] == regB[15]) && (regA[15] != temp[15]));
        end
    end

    assign result = temp;
    assign carry = carryReg;
    assign zero = zeroReg;
    assign overflow = overflowReg;

endmodule

module ButtonCount(input clk, input button, output[7:0] segment, output[7:0] digit, output TxD);

