.button_state	(button_state),
.button_up		(button_up),
.button_down	(button_down));

reg[3:0] d0 = 3'd0;
reg[3:0] d1 = 3'd0;
reg[3:0] d2 = 3'd0;
reg[3:0] d3 = 3'd0;
reg[3:0] d4 = 3'd0;
reg[3:0] d5 = 3'd0;
reg[3:0] d6 = 3'd0;
reg[3:0] d7 = 3'd0;

