		d0 = count % 10;
		d1 = (count / 10) % 10;
		d2 = (count / 100) % 10;
		d3 = (count / 1000) % 10;
		d4 = (count / 10000) % 10;
		d5 = (count / 100000) % 10;
		d6 = (count / 1000000) % 10;
		d7 = (count / 10000000) % 10;
		tx_to_send = tx_to_send + 23'd1;
	end
end

