module top_module (
    input clk,
    input reset, // Synchronous active-high reset
    input [7:0] in1, // 8-bit input vector 1
    input [7:0] in2, // 8-bit input vector 2
    output [7:0] xor_out, // 8-bit output of the XOR module
    output [7:0] sum_out, // 8-bit output of the adder module
    output [7:0] and_out // 8-bit output of the functional module
);

    // Instantiate the 8-bit adder module
    adder_module adder(.a(in1), .b(in2), .sum(sum_out));

    // Instantiate the XOR module
    assign xor_out = in1 ^ in2;

    // Instantiate the functional module
    assign and_out = xor_out & sum_out;

    // Synchronous active-high reset
    always @(posedge clk) begin
        if (reset) begin
            xor_out <= 8'b0;
            sum_out <= 8'b0;
            and_out <= 8'b0;
        end
    end

endmodule

// 8-bit adder module
module adder_module (
    input [7:0] a,
    input [7:0] b,
    output reg [7:0] sum
);

    always @(a, b) begin
        sum <= a + b;
    end

endmodule

module xor_gate (
    input clk,
    input [7:0] d,
    input [7:0] e,
    output reg out_case
);

reg [7:0] stored_d;
reg [7:0] stored_e;

bitwise_logic_operation bitwise_d (d, stored_d);
bitwise_logic_operation bitwise_e (e, stored_e);

always @(posedge clk) begin
    stored_d <= d;
    stored_e <= e;
    out_case <= bitwise_d.out ^ bitwise_e.out;
end

endmodule

module videosyncs (
   input wire clk,

   input wire [2:0] rin,
   input wire [2:0] gin,
   input wire [1:0] bin,

   output reg [2:0] rout,
   output reg [2:0] gout,
   output reg [1:0] bout,

   output reg hs,
   output reg vs,

   output wire [10:0] hc,
   output wire [10:0] vc
   );

   /* http://www.abramovbenjamin.net/calc.html */

   // VGA 640x480@60Hz,25MHz
   parameter htotal = 800;
   parameter vtotal = 524;
   parameter hactive = 640;
   parameter vactive = 480;
   parameter hfrontporch = 16;
   parameter hsyncpulse = 96;
   parameter vfrontporch = 11;
   parameter vsyncpulse = 2;
   parameter hsyncpolarity = 0;
   parameter vsyncpolarity = 0;

   reg [10:0] hcont = 0;
   reg [10:0] vcont = 0;
   reg active_area;

    assign hc = hcont;
    assign vc = vcont;

   always @(posedge clk) begin
      if (hcont == htotal-1) begin
         hcont <= 0;
         if (vcont == vtotal-1) begin
            vcont <= 0;
         end
         else begin
            vcont <= vcont + 1;
         end
      end
      else begin
         hcont <= hcont + 1;
      end
   end

   always @* begin
      if (hcont>=0 && hcont<hactive && vcont>=0 && vcont<vactive)
         active_area = 1'b1;
      else
         active_area = 1'b0;
      if (hcont>=(hactive+hfrontporch) && hcont<(hactive+hfrontporch+hsyncpulse))
         hs = ~hsyncpolarity;
      else
         hs = hsyncpolarity;
      if (vcont>=(vactive+vfrontporch) && vcont<(vactive+vfrontporch+vsyncpulse))
         vs = ~vsyncpolarity;
      else
         vs = vsyncpolarity;
    end

   always @* begin
      if (active_area) begin
         gout = gin;
         rout = rin;
         bout = bin;
      end
      else begin
         gout = 3'h00;
         rout = 3'h00;
         bout = 2'h00;
      end
   end
endmodule

