module fsm_pattern_detection (
  input clk,
  input reset,
  input [3:0] in,
  output reg done
);

  parameter IDLE = 2'b00, STATE1 = 2'b01, STATE2 = 2'b10;
  reg [1:0] state;
  reg [3:0] shift_reg;

  always @(posedge clk) begin
    if (reset) begin
      state <= IDLE;
      shift_reg <= 4'b0;
      done <= 0;
    end else begin
      case (state)
        IDLE: begin
          if (in[3] == 1'b1) begin
            shift_reg <= {shift_reg[2:0], in};
            state <= STATE1;
          end
        end
        STATE1: begin
          shift_reg <= {shift_reg[2:0], in};
          if (shift_reg == 4'b1011) begin
            done <= 1;
            state <= IDLE;
          end else begin
            state <= STATE2;
          end
        end
        STATE2: begin
          shift_reg <= {shift_reg[2:0], in};
          if (shift_reg == 4'b1011) begin
            done <= 1;
            state <= IDLE;
          end else begin
            state <= IDLE;
          end
        end
      endcase
    end
  end
endmodule

module UART (
  input clk, reset, rx,
  output tx, rx_done, tx_done
);

parameter CLK_FREQUENCY = 50_000_000; // clock frequency in Hz
parameter BAUD_RATE = 115200; // communication speed in bps
parameter PARITY = "none"; // parity setting (even, odd, or none)
parameter DATA_BITS = 8; // number of data bits
parameter STOP_BITS = 1; // number of stop bits

reg [3:0] state;
reg [7:0] tx_data;
reg [7:0] rx_data;
reg tx_busy;
reg rx_busy;
reg tx_enable;
reg rx_enable;
reg tx_parity;
reg rx_parity;
reg tx_stop;
reg rx_stop;
reg tx_bit_count;
reg rx_bit_count;
reg tx_done;
reg rx_done;

assign tx = tx_data[0];
assign rx_done = rx_busy && (rx_bit_count == DATA_BITS + (PARITY != "none") + STOP_BITS);
assign tx_done = !tx_busy;

always @(posedge clk) begin
  if (reset) begin
    state <= 4'b0000;
    tx_busy <= 0;
    rx_busy <= 0;
    tx_enable <= 0;
    rx_enable <= 0;
    tx_parity <= 0;
    rx_parity <= 0;
    tx_stop <= 0;
    rx_stop <= 0;
    tx_bit_count <= 0;
    rx_bit_count <= 0;
    tx_done <= 0;
    rx_done <= 0;
  end else begin
    case (state)
      4'b0000: begin // IDLE
        if (rx == 0) begin
          rx_busy <= 1;
          rx_enable <= 1;
          rx_bit_count <= 0;
          state <= 4'b0001; // START_BIT
        end else begin
          tx_enable <= 1;
          tx_busy <= 1;
          tx_data <= 8'h55; // send continuous idle state
          state <= 4'b0000;
        end
      end
      4'b0001: begin // START_BIT
        if (rx_enable) begin
          rx_enable <= 0;
          rx_data <= 0;
          state <= 4'b0010; // DATA_BITS
        end
      end
      4'b0010: begin // DATA_BITS
        if (rx_enable) begin
          rx_enable <= 0;
          rx_data <= {rx_data[6:0], rx};
          rx_bit_count <= rx_bit_count + 1;
          if (rx_bit_count == DATA_BITS) begin
            if (PARITY == "none") begin
              state <= 4'b0100; // STOP_BIT
            end else begin
              state <= 4'b0011; // PARITY_BIT
            end
          end
        end
      end
      4'b0011: begin // PARITY_BIT
        if (rx_enable) begin
          rx_enable <= 0;
          rx_parity <= rx;
          rx_bit_count <= rx_bit_count + 1;
          if (rx_bit_count == DATA_BITS + 1) begin
            state <= 4'b0100; // STOP_BIT
          end
        end
      end
      4'b0100: begin // STOP_BIT
        if (rx_enable) begin
          rx_enable <= 0;
          rx_stop <= rx;
          rx_bit_count <= rx_bit_count + 1;
          rx_busy <= 0;
          state <= 4'b0000; // IDLE
        end
      end
      4'b0101: begin // TX_DATA_BITS
        if (tx_enable) begin
          tx_enable <= 0;
          tx_data <= {tx_data[6:0], tx_parity};
          tx_bit_count <= tx_bit_count + 1;
          if (tx_bit_count == DATA_BITS + (PARITY != "none")) begin
            tx_enable <= 1;
            tx_data <= tx_stop;
            state <= 4'b0110; // TX_STOP_BIT
          end
        end
      end
      4'b0110: begin // TX_STOP_BIT
        if (tx_enable) begin
          tx_enable <= 0;
          tx_busy <= 0;
          tx_done <= 1;
          state <= 4'b0000; // IDLE
        end
      end
    endcase
  end
end

always @(posedge clk) begin
  if (reset) begin
    tx_bit_count <= 0;
  end else begin
    if (tx_busy) begin
      if (tx_bit_count == 0) begin
        tx_data <= 8'h00; // start bit
        tx_parity <= (PARITY == "even") ? ^tx_data : &tx_data;
        tx_stop <= (STOP_BITS == 1) ? 1 : 2'b11;
        state <= 4'b0101; // TX_DATA_BITS
      end else begin
        tx_bit_count <= tx_bit_count - 1;
      end
    end
  end
end

always @(posedge clk) begin
  if (reset) begin
    rx_bit_count <= 0;
  end else begin
    if (rx_busy) begin
      if (rx_bit_count == 0) begin
        rx_enable <= 1;
      end else begin
        rx_bit_count <= rx_bit_count - 1;
      end
    end
  end
end

endmodule

module top_module (
    input clk,
    input reset,
    input [7:0] a1,
    input [7:0] b1,
    input [7:0] a2,
    input [7:0] b2,
    output EN,
    output reg [15:0] Y
);

    // Instantiate unsigned multiplier modules
    unsigned_multiplier unsigned_multiplier_1(a1, b1, clk, reset, Y[7:0]);
    unsigned_multiplier unsigned_multiplier_2(a2, b2, clk, reset, Y[15:8]);

    // Instantiate priority encoder module
    priority_encoder priority_encoder(Y, EN);

