module unsigned_multiplier (
    input [7:0] a,
    input [7:0] b,
    input clk,
    input reset,
    output reg [15:0] product
);

    always @(posedge clk) begin
        if (reset) begin
            product <= 0;
        end else begin
            product <= a * b;
        end
    end

endmodule

module priority_encoder (
    input [15:0] inputs,
    output reg EN,
    output reg [2:0] Y
);

    always @(*) begin
        if (inputs == 16'h0000) begin
            EN <= 0;
            Y <= 3'b000;
        end else if (inputs[15:8] > inputs[7:0]) begin
            EN <= 1;
            Y <= inputs[15:8];
        end else begin
            EN <= 1;
            Y <= inputs[7:0];
        end
    end

endmodule

module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input select,     // Select input to choose between counters and multiplexer
    output reg [3:0] out  // 4-bit output from the active module
);

    reg [3:0] counter1 = 4'b0000;   // 4-bit binary counter from 0 through 5
    reg [3:0] counter2 = 4'b0000;   // 4-bit binary counter from 0 through 15
    reg [1:0] select_counter = 2'b00;  // Selects which counter to output
    reg [3:0] mux_out;              // Output from the 4-to-1 multiplexer

    always @(posedge clk) begin
        if (reset) begin
            counter1 <= 4'b0000;
            counter2 <= 4'b0000;
            select_counter <= 2'b00;
            mux_out <= 4'b0000;
        end else begin
            if (select) begin
                // Multiplexer is selected
                select_counter <= 2'b10;
                case (counter2)
                    4'b0000: mux_out <= 4'b0000;
                    4'b0001: mux_out <= 4'b0001;
                    4'b0010: mux_out <= 4'b0010;
                    4'b0011: mux_out <= 4'b0011;
                    4'b0100: mux_out <= 4'b0100;
                    4'b0101: mux_out <= 4'b0101;
                    4'b0110: mux_out <= 4'b0110;
                    4'b0111: mux_out <= 4'b0111;
                    4'b1000: mux_out <= 4'b1000;
                    4'b1001: mux_out <= 4'b1001;
                    4'b1010: mux_out <= 4'b1010;
                    4'b1011: mux_out <= 4'b1011;
                    4'b1100: mux_out <= 4'b1100;
                    4'b1101: mux_out <= 4'b1101;
                    4'b1110: mux_out <= 4'b1110;
                    4'b1111: mux_out <= 4'b1111;
                endcase
            end else begin
                // Counters are selected
                select_counter <= 2'b01;
                case (counter1)
                    4'b0000: out <= 4'b0000;
                    4'b0001: out <= 4'b0001;
                    4'b0010: out <= 4'b0010;
                    4'b0011: out <= 4'b0011;
                    4'b0100: out <= 4'b0100;
                    4'b0101: out <= 4'b0101;
                    4'b0110: out <= 4'b0110;
                    4'b0111: out <= 4'b0111;
                    4'b1000: out <= 4'b1000;
                    4'b1001: out <= 4'b0001;
                    4'b1010: out <= 4'b0010;
                    4'b1011: out <= 4'b0011;
                    4'b1100: out <= 4'b0100;
                    4'b1101: out <= 4'b0101;
                    4'b1110: out <= 4'b0110;
                    4'b1111: out <= 4'b0111;
                endcase
                if (counter1 == 4'b0101) begin
                    counter1 <= 4'b0000;
                    counter2 <= counter2 + 1;
                end else begin
                    counter1 <= counter1 + 1;
                end
            end
        end
    end
endmodule

module gray_code_converter (
    input [2:0] binary_input,
    input select,
    output [2:0] gray_output
);

    wire [2:0] mux1_output;
    wire [2:0] mux2_output;
    wire [7:0] decoder_output;
    wire [2:0] adder_output;

    // Control logic for selecting the multiplexer
    assign mux1_select = select;
    assign mux2_select = ~select;

    // Instantiate the multiplexers
    mux2to1 mux1 (
        .in0(binary_input),
        .in1({binary_input[1], binary_input[0], binary_input[0]}),
        .select(mux1_select),
        .out(mux1_output)
    );

    mux2to1 mux2 (
        .in0({binary_input[2], binary_input[1], binary_input[0]}),
        .in1({binary_input[2], ~binary_input[1], ~binary_input[0]}),
        .select(mux2_select),
        .out(mux2_output)
    );

    // Instantiate the decoder
    decoder3to8 decoder (
        .in(select),
        .out(decoder_output)
    );

    // Instantiate the adder
    assign adder_output = mux1_output + mux2_output;

    // Assign the gray code output
    assign gray_output = adder_output;

endmodule

// 2-to-1 multiplexer module
module mux2to1 (
    input [2:0] in0,
    input [2:0] in1,
    input select,
    output [2:0] out
);

    assign out = select ? in1 : in0;

endmodule

// 3-to-8 decoder module
module decoder3to8 (
    input [2:0] in,
    output [7:0] out
);

    assign out = 8'b00000001 << in;

endmodule

