    input exe2disp_data_wr, // Indicates whether there is data waiting to be transmitted
    input [133:0] exe2disp_data, // Contains the data to be transmitted
    input exe2disp_valid_wr, // Indicates whether the data is valid and ready to be transmitted
    input exe2disp_valid, // Indicates whether the data has been successfully transmitted
    input exe2disp_direction_req, // Indicates whether the data should be transmitted to the up CPU or the down port
    input exe2disp_direction, // Indicates the direction of transmission (0 for up CPU, 1 for down port)
    input up2disp_alf, // Indicates whether the up CPU is ready to receive data
    input down2disp_alf, // Indicates whether the down port is ready to receive data
    output reg disp2exe_alf, // Indicates whether the module is ready to receive data from the execute module
    output reg disp2up_data_wr, // Indicates whether there is data waiting to be transmitted to the up CPU
    output reg [133:0] disp2up_data, // Contains the data to be transmitted to the up CPU
    output reg disp2up_valid_wr, // Indicates whether the data is valid and ready to be transmitted to the up CPU
    output reg disp2up_valid, // Indicates whether the data has been successfully transmitted to the up CPU
    output reg disp2down_data_wr, // Indicates whether there is data waiting to be transmitted to the down port
    output reg [133:0] disp2down_data, // Contains the data to be transmitted to the down port
    output reg disp2down_valid_wr, // Indicates whether the data is valid and ready to be transmitted to the down port
    output reg disp2down_valid // Indicates whether the data has been successfully transmitted to the down port
);

// Intermediate variable declaration
reg [133:0] data_buff; // Buffer to store the data to be transmitted
reg [1:0] disp_state; // State variable to keep track of the transmission state

// Transmit judge
assign disp2up_data = data_buff;
assign disp2down_data = data_buff;
assign disp2up_valid = disp2up_valid_wr;
assign disp2down_valid = disp2down_valid_wr;

// Receive control, controlled by disp2exe_alf
always @(*) begin
    if (exe2disp_direction_req == 1'b1) begin
        if (exe2disp_direction == 1'b0) begin // Request send to up CPU
            disp2exe_alf = up2disp_alf;
        end
        else begin // Request send to down port
            disp2exe_alf = down2disp_alf;
        end
    end
    else begin
        disp2exe_alf = 1'b1; // Don't permit execute send pkt
    end
end

// Packet data transmit
localparam IDLE_S = 2'd0, TRANS_UP_S = 2'd1, TRANS_DOWN_S = 2'd2;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        disp2up_data_wr <= 1'b0;
        disp2up_valid_wr <= 1'b0;
        disp2down_data_wr <= 1'b0;
        disp2down_valid_wr <= 1'b0;
        disp_state <= IDLE_S;
    end
    else begin
        case (disp_state)
            IDLE_S: begin
                if (exe2disp_data_wr) begin // Trans start
                    data_buff <= exe2disp_data;
                    if (exe2disp_direction == 1'b0) begin // Request send to up CPU
                        disp2up_data_wr <= exe2disp_data_wr;
                        disp2up_valid_wr <= exe2disp_valid_wr;
                        disp2down_data_wr <= 1'b0;
                        disp2down_valid_wr <= 1'b0;
                        disp_state <= TRANS_UP_S;
                    end
                    else begin // Request send to down port
                        disp2up_data_wr <= 1'b0;
                        disp2up_valid_wr <= 1'b0;
                        disp2down_data_wr <= exe2disp_data_wr;
                        disp2down_valid_wr <= exe2disp_valid_wr;
                        disp_state <= TRANS_DOWN_S;
                    end
                end
                else begin
                    disp2up_data_wr <= 1'b0;
                    disp2up_valid_wr <= 1'b0;
                    disp2down_data_wr <= 1'b0;
                    disp2down_valid_wr <= 1'b0;
                    disp_state <= IDLE_S;
                end
            end

            TRANS_UP_S: begin
                data_buff <= exe2disp_data;
                disp2up_data_wr <= exe2disp_data_wr;
                disp2up_valid_wr <= exe2disp_valid_wr;
                if (exe2disp_valid_wr) begin // Trans end
                    disp_state <= IDLE_S;
                    disp2up_valid <= 1'b1;
                end
                else begin
                    disp_state <= TRANS_UP_S;
                end
            end

            TRANS_DOWN_S: begin
                data_buff <= exe2disp_data;
                disp2down_data_wr <= exe2disp_data_wr;
                disp2down_valid_wr <= exe2disp_valid_wr;
                if (exe2disp_valid_wr) begin // Trans end
                    disp_state <= IDLE_S;
                    disp2down_valid <= 1'b1;
                end
                else begin
                    disp_state <= TRANS_DOWN_S;
                end
            end

            default: begin
                disp2up_data_wr <= 1'b0;
                disp2up_valid_wr <= 1'b0;
                disp2down_data_wr <= 1'b0;
                disp2down_valid_wr <= 1'b0;
                disp_state <= IDLE_S;
            end
        endcase
    end
end

endmodule

module mux_adder (
    input [3:0] in1,
    input [3:0] in2,
    input [3:0] cin,
    input select,
    input sel_b1,
    input sel_b2,
    output [3:0] out
);

    wire [3:0] mux1_out;
    wire [3:0] mux2_out;
    wire [3:0] adder_out;

    // Multiplexer 1
    mux2to1 mux1 (
        .in0(in1),
        .in1(in2),
        .sel(sel_b1),
        .out(mux1_out)
    );

    // Multiplexer 2
    mux2to1 mux2 (
        .in0(in1),
        .in1(in2),
        .sel(sel_b2),
        .out(mux2_out)
    );

    // Adder
    adder add (
        .a(mux1_out),
        .b(mux2_out),
        .cin(cin),
        .sum(adder_out)
    );

    // Control logic
    always @ (select, sel_b1, sel_b2) begin
        if (select) begin
            out <= adder_out;
        end else begin
            if (sel_b1 && sel_b2) begin
                out <= adder_out;
            end else if (sel_b1) begin
                out <= mux1_out;
            end else if (sel_b2) begin
                out <= mux2_out;
            end else begin
                out <= in1;
            end
        end
    end

endmodule

