reg [15:0] b_low;
wire [15:0] sum_low;
wire carry_in;
wire [31:0] sum_high;

// Instantiate the 16-bit adder module
adder16 adder(
    .a(a_low),
    .b(b_low),
    .sum(sum_low),
    .carry_out(carry_in)
);

// Instantiate the 32-bit XOR gate
xor32 xor_gate(
    .a(b),
    .b({sub, sub, sub, sub, sub, sub, sub, sub, sub, sub, sub, sub, sub, sub, sub, sub, sub, sub, sub, sub, sub, sub, sub, sub, sub, sub, sub, sub, sub, sub, sub, sub}),
    .y(b_low)
);

// Pipeline registers
reg [31:0] a_reg;
reg [31:0] b_reg;
wire [31:0] sum_reg;

// Assign inputs to pipeline registers
always @(posedge clk) begin
    a_reg <= a;
    b_reg <= b;
end

// Assign outputs from pipeline registers
assign sum = sum_reg;

// Pipeline stages
always @(posedge clk) begin
    a_low <= a_reg[15:0];
    b_low <= b_reg[15:0];
    sum_reg[15:0] <= sum_low;
    sum_reg[31:16] <= sum_high;
end

// Generate carry-in signal for subtraction
assign carry_in = sub ? ~b_low[15] : 1'b0;

// Generate high-order bits of sum
assign sum_high = sub ? {32{1'b0}} - {carry_in, b_reg} : {carry_in, a_reg} + {b_reg, 16'h0};

endmodule

