module vending_machine (
  input clk,
  input reset,
  input cancel,
  input dollar,
  input fifty_cents,
  input twenty_five_cents,
  input ten_cents,
  input five_cents,
  output reg dispense,
  output reg change
);

  parameter READY = 2'b00;
  parameter DISPENSE = 2'b01;
  parameter CHANGE = 2'b10;

  reg [1:0] state;
  reg [3:0] coins_inserted;
  reg [3:0] price;
  reg [3:0] change_amount;

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      state <= READY;
      coins_inserted <= 0;
      price <= 0;
      change_amount <= 0;
      dispense <= 0;
      change <= 0;
    end else begin
      case(state)
        READY: begin
          if (dollar) begin
            coins_inserted <= coins_inserted + 100;
          end else if (fifty_cents) begin
            coins_inserted <= coins_inserted + 50;
          end else if (twenty_five_cents) begin
            coins_inserted <= coins_inserted + 25;
          end else if (ten_cents) begin
            coins_inserted <= coins_inserted + 10;
          end else if (five_cents) begin
            coins_inserted <= coins_inserted + 5;
          end

          if (coins_inserted >= price) begin
            state <= DISPENSE;
            change_amount <= coins_inserted - price;
          end
        end

        DISPENSE: begin
          dispense <= 1;
          if (change_amount > 0) begin
            state <= CHANGE;
          end else begin
            state <= READY;
          end
        end

        CHANGE: begin
          change <= 1;
          coins_inserted <= 0;
          state <= READY;
        end
      endcase
    end
  end

  always @(posedge clk) begin
    if (cancel) begin
      coins_inserted <= 0;
      state <= READY;
    end

    case(state)
      READY: begin
        price <= 0;
      end

      DISPENSE: begin
        price <= 0;
        dispense <= 0;
        change_amount <= 0;
      end

      CHANGE: begin
        change <= 0;
      end
    endcase
  end

  always @(coins_inserted) begin
    case(coins_inserted)
      5, 10, 25, 50, 100: begin
        price <= coins_inserted;
      end

      default: begin
        price <= 0;
      end
    endcase
  end

endmodule

