module multiplier (
  input [7:0] in1,
  input [7:0] in2,
  output reg [15:0] out
);

  reg [7:0] a;
  reg [7:0] b;
  reg [15:0] sum;
  reg [3:0] i;

  always @(*) begin
    a = in1;
    b = in2;
    sum = 0;
    for (i = 0; i < 8; i = i + 1) begin
      if (b[0] == 1) begin
        sum = sum + (a << i);
      end
      a = a << 1;
      b = b >> 1;
    end
    out = sum;
  end

endmodule

