module adder4(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout
);

wire [3:0] xor_out;
wire [3:0] and_out;
wire [3:0] or_out;

// Generate sum bits
assign xor_out = A ^ B;
assign Sum = xor_out ^ Cin;

// Generate carry out
assign and_out = A & B;
assign or_out = A | B;
assign Cout = (and_out | (xor_out & Cin)) | (or_out & Cin);

endmodule

module LZW (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 8; // number of input signals
parameter m = 16; // number of output signals

// Define the dictionary
reg [n-1:0] dict [0:2**n-1];
integer dict_size = 256; // initialize with all possible single characters
initial begin
  for (i = 0; i < dict_size; i = i + 1) begin
    dict[i] = i;
  end
end

// LZW compression algorithm
reg [n-1:0] seq;
reg [n-1:0] next_in;
reg [m-1:0] index;
integer i;
always @ (posedge clk) begin
  if (reset) begin
    seq <= 0;
    next_in <= 0;
    index <= 0;
  end else begin
    if (next_in == 0) begin
      seq <= in;
      next_in <= 1;
    end else begin
      if (dict.contains(seq)) begin
        seq <= seq + in;
      end else begin
        dict[dict_size] = seq;
        index = dict.find(seq);
        out <= index;
        dict_size = dict_size + 1;
        seq <= in;
      end
      next_in <= 1;
    end
  end
end

// LZW decompression algorithm
reg [n-1:0] last_seq;
reg [m-1:0] last_index;
always @ (posedge clk) begin
  if (reset) begin
    last_seq <= 0;
    last_index <= 0;
  end else begin
    if (last_index == 0) begin
      last_index <= in;
      out <= dict[last_index];
    end else begin
      if (dict.contains(last_index)) begin
        seq <= dict[last_index];
      end else begin
        seq <= last_seq + last_seq[0];
      end
      out <= seq;
      dict[dict_size] = last_seq + seq[0];
      dict_size = dict_size + 1;
      last_seq <= seq;
      last_index <= in;
    end
  end
end

endmodule

module manchester (
  input data_in,
  input clk,
  output data_out,
  output decoded_data_out
);

  reg data_out_reg;
  reg decoded_data_out_reg;
  reg prev_clk_state;

  always @(posedge clk) begin
    // Manchester Encoding
    data_out_reg <= data_in ^ prev_clk_state;
    prev_clk_state <= ~prev_clk_state;
  end

  always @(posedge prev_clk_state) begin
    // Manchester Decoding
    decoded_data_out_reg <= data_out_reg ^ prev_clk_state;
  end

  assign data_out = data_out_reg;
  assign decoded_data_out = decoded_data_out_reg;

endmodule

module binary_counter (
  input clk,
  input rst,
  output reg [3:0] count,
  output reg max_reached
);

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      count <= 4'b0;
      max_reached <= 1'b0;
    end
    else if (count == 4'b1111) begin
      count <= 4'b0;
      max_reached <= 1'b1;
    end
    else begin
      count <= count + 1;
      max_reached <= 1'b0;
    end
  end

endmodule

