always @(posedge clk or negedge reset) begin
    if (reset == 0) begin
        shift_reg <= 4'b0;
    end else if (load == 1) begin
        shift_reg <= load_value;
    end else begin
        shift_reg <= {shift_reg[2:0], 1'b0};
