module debouncer (
  input in,
  output out
);

  reg [1:0] state;
  reg out_reg;
  reg [31:0] count;

  parameter DELAY = 100000; // 10ms delay

  always @(posedge in or negedge in) begin
    if (state == 2'b00 && in == 1'b1) begin
      state <= 2'b01;
      count <= 0;
    end else if (state == 2'b01 && in == 1'b1) begin
      if (count < DELAY) begin
        count <= count + 1;
      end else begin
        state <= 2'b10;
        out_reg <= 1'b1;
      end
    end else if (state == 2'b10 && in == 1'b0) begin
      state <= 2'b11;
      count <= 0;
    end else if (state == 2'b11 && in == 1'b0) begin
      if (count < DELAY) begin
        count <= count + 1;
      end else begin
        state <= 2'b00;
        out_reg <= 1'b0;
      end
    end else begin
      count <= 0;
    end
  end

  assign out = out_reg;

endmodule

