module parallel_to_serial (
    input clk,
    input reset,
    input [7:0] in,
    output reg serial_out
);
    reg [7:0] shift_reg;
    reg [2:0] counter;

    always @(posedge clk) begin
        if (reset) begin
            shift_reg <= 8'b0;
            counter <= 3'b0;
            serial_out <= 1'b0;
        end else begin
            shift_reg <= {shift_reg[6:0], in};
            counter <= counter + 1;
            if (counter == 3) begin
                serial_out <= shift_reg[7];
                counter <= 0;
            end
        end
    end
endmodule

