    wire serial_out_2;

    barrel_shifter bs (
        .in(in),
        .upper_byte(upper_byte),
        .lower_byte(lower_byte)
    );

    parallel_to_serial pts_1 (
        .clk(clk),
        .reset(reset),
        .in(upper_byte),
        .serial_out(serial_out_1)
    );

    parallel_to_serial pts_2 (
        .clk(clk),
        .reset(reset),
        .in(lower_byte),
        .serial_out(serial_out_2)
    );

    always @(posedge clk) begin
        if (reset) begin
            serial_out <= 16'b0;
        end else begin
            serial_out <= {serial_out[14:0], serial_out_1, serial_out_2};
        end
    end
