module top_module(
    input [15:0] a,
    input [15:0] b,
    input [1:0] op, //Select between addition, subtraction, and bitwise AND
    output [31:0] result
);

wire [15:0] adder_out;
wire [15:0] sub_out;
wire [15:0] and_out;

assign adder_out = a + b;
assign sub_out = a - b;
assign and_out = a & b;

always @(*) begin
    case (op)
        2'b00: result = {16'b0, adder_out}; //Addition
        2'b01: result = {16'b0, sub_out};   //Subtraction
        2'b10: result = {16'b0, and_out};   //Bitwise AND
        default: result = 32'b0;            //Default to zero if invalid op
    endcase
end

endmodule

module top_module (
    input clk,
    input rst,
    input d,
    input [31:0] in,
    output reg [31:0] out
);

    wire [31:0] byte_reversed_out;
    wire [3:0] byte_select;
    wire jk_out;

    // Instantiate the D flip-flop module
    d_ff dff (
        .clk(clk),
        .rst(rst),
        .d(d),
        .q(jk_out)
    );

    // Instantiate the byte-reversing module
    byte_reverser byte_rev (
        .in(in),
        .out(byte_reversed_out)
    );

    // Control logic to select between D flip-flop and byte-reversing module outputs
    mux4 mux (
        .in0(jk_out),
        .in1(byte_reversed_out[7:0]),
        .in2(byte_reversed_out[15:8]),
        .in3(byte_reversed_out[23:16]),
        .sel(byte_select)
    );

    // Byte select logic to determine which byte to output
    assign byte_select = (out[31:24] == 8'b11111111) ? 4'b1000 :
                         (out[23:16] == 8'b11111111) ? 4'b0100 :
                         (out[15:8] == 8'b11111111) ? 4'b0010 :
                         (out[7:0] == 8'b11111111) ? 4'b0001 :
                         4'b0000;

    // Output the byte-reversed value of the selected module's output on the rising edge of the clock
    always @(posedge clk) begin
        if (byte_select == 4'b0000) begin
            out <= jk_out;
        end else begin
            out <= mux.out;
        end
    end

endmodule

module temp_sensor(
    input [6:0] daddr_in,
