module auto_init_rom (
    input clk,
    input reset,
    input clear_error,
    input ack,
    input transfer_complete,
    input [22:0] rom_data,
    output reg [22:0] data_out,
    output reg transfer_data,
    output reg [4:0] rom_address,
    output reg auto_init_complete,
    output reg auto_init_error
);

parameter ROM_SIZE = 50;
parameter AW = 5;
parameter DW = 23;

reg [22:0] rom [0:ROM_SIZE-1];
reg [4:0] addr_reg;
reg [4:0] next_addr_reg;
reg [22:0] data_reg;
reg [22:0] next_data_reg;
reg [1:0] state_reg;
reg [1:0] next_state_reg;
reg error_reg;

localparam STATE_IDLE = 2'b00;
localparam STATE_TRANSFER = 2'b01;
localparam STATE_WAIT_ACK = 2'b10;

assign rom_address = addr_reg;
assign data_out = rom[addr_reg];
assign auto_init_error = error_reg;
assign auto_init_complete = (addr_reg == ROM_SIZE-1);

always @(posedge clk) begin
    if (reset) begin
        state_reg <= STATE_IDLE;
        addr_reg <= 0;
        data_out <= 0;
        transfer_data <= 0;
        error_reg <= 0;
    end else begin
        state_reg <= next_state_reg;
        addr_reg <= next_addr_reg;
        data_out <= next_data_reg;
        transfer_data <= (state_reg == STATE_IDLE);
        error_reg <= clear_error ? 0 : error_reg;
    end
end

always @* begin
    next_state_reg = state_reg;
    next_addr_reg = addr_reg;
    next_data_reg = data_reg;
    case (state_reg)
        STATE_IDLE: begin
            if (transfer_complete) begin
                next_state_reg = STATE_TRANSFER;
                next_addr_reg = 0;
                next_data_reg = rom_data;
            end
        end
        STATE_TRANSFER: begin
            next_state_reg = STATE_WAIT_ACK;
            next_addr_reg = addr_reg + 1;
            next_data_reg = rom_data;
            rom[addr_reg] <= data_reg;
            if (addr_reg == ROM_SIZE-1) begin
                next_state_reg = STATE_IDLE;
            end
        end
        STATE_WAIT_ACK: begin
            if (ack) begin
                next_state_reg = STATE_TRANSFER;
                next_data_reg = rom_data;
            end else if (clear_error) begin
                next_state_reg = STATE_IDLE;
                error_reg = 1;
            end
        end
    endcase
end

endmodule

module mux_decoder(
  input a,
  input b,
  input reset,
  output reg final_output
);

  // MUX implementation using non-clocked always block
  always @ (a, b)
  begin
    if (a == 1'b0)
      final_output = b;
    else
      final_output = a;
  end

  // Decoder implementation using NAND gates and inverters
  wire nand1, nand2, nand3;
  assign nand1 = ~(a & b);
  assign nand2 = ~(a & nand1);
  assign nand3 = ~(b & nand1);
  assign final_output = ~(nand2 & nand3);

  // Synchronous reset to reset final_output to 0
  always @ (posedge reset)
  begin
    final_output <= 1'b0;
  end

endmodule

