module controller_m(
    input clock, reset, start, Zero,
    output Ready, Load_regs, Add_dec
);
parameter S_Idle = 1'b0, S_Mul = 1'b1;

reg state, next_state;

always @(posedge clock, posedge reset)
    if (reset)
        state <= S_Idle;
    else
        state <= next_state;

always @(*)
begin
    case (state)
        S_Idle: next_state = Load_regs ? S_Mul : S_Idle;
        S_Mul: next_state = Add_dec ? S_Idle : S_Mul;
        default: next_state = 1'bx;
    endcase
end

assign Ready = state == S_Idle;
assign Load_regs = Ready & start;
assign Add_dec = (state == S_Mul & ~Zero);

endmodule

module bin_to_gray(
    input [3:0] bin,
    input clr,
    output reg [3:0] gray
);

    always @ (bin, clr) begin
        if (clr == 1'b0) begin
            gray <= 4'b0000;
        end
        else begin
            gray[0] = bin[0];
            gray[1] = bin[0] ^ bin[1];
            gray[2] = bin[1] ^ bin[2];
            gray[3] = bin[2] ^ bin[3];
        end
    end

endmodule

module ALU(clk, control, data_input1, data_input2, data_output, zero);

input clk;
input [3:0] control;
input signed [31:0] data_input1, data_input2;

output reg signed [31:0] data_output;
output reg zero;

always@(posedge clk)

begin
    // R-type Add, Load word, Store word,
    if (control == 4'b0010) begin
        data_output = data_input1 + data_input2;
        zero = 0;
    end

    // R-type Subtract, Branch equal
    else if (control == 4'b0110)
    begin
        data_output = data_input1 - data_input2;
        if (data_output == 0)
            zero = 1;
        else
            zero = 0;
    end

    // And
    else if (control == 4'b0000) begin
        data_output = data_input1 & data_input2;
        zero = 0;
    end

    // Or
    else if (control == 4'b0001) begin
        data_output = data_input1 | data_input2;
        zero = 0;
    end

    // Set less than
    else if (control == 4'b0111) begin
        if (data_input2 < data_input1)
            data_output = 1;
        else
            data_output = 0;
        zero = 0;
    end

    // Nor
    else if (control == 4'b1100) begin
        data_output = ~(data_input1 | data_input2);
        zero =0;
    end

    else
    begin
        data_output = 0;
        zero =0;
    end

end

endmodule

