module rle (
  input clk,
  input rst,
  input din,
  input en,
  output dout
);

  reg [5:0] count; // Counter for consecutive bits
  reg last_bit; // Last bit received
  reg [5:0] encode_count; // Counter for encoding
  reg [5:0] decode_count; // Counter for decoding
  reg [5:0] decode_value; // Value to output during decoding
  wire [5:0] data_out; // Output data

  assign dout = data_out; // Assign output to data_out wire

  always @(posedge clk) begin
    if (rst) begin
      count <= 0;
      last_bit <= 0;
      encode_count <= 0;
      decode_count <= 0;
      decode_value <= 0;
    end else begin
      // Count consecutive bits
      if (din == last_bit) begin
        count <= count + 1;
      end else begin
        count <= 1;
      end

      // Encode or decode data
      if (en == 0) begin // Encoding
        if (count == 4) begin // Four consecutive bits
          encode_count <= encode_count + 1;
          data_out <= {1'b0, encode_count};
          count <= 0;
        end else if (count == 8) begin // Eight consecutive bits
          encode_count <= encode_count + 1;
          data_out <= {1'b1, encode_count};
          count <= 0;
        end else begin // Less than four or eight consecutive bits
          data_out <= din;
        end
      end else begin // Decoding
        if (count == 4) begin // Four consecutive bits
          decode_count <= count;
          count <= 0;
        end else if (count == 8) begin // Eight consecutive bits
          decode_count <= count;
          count <= 0;
        end else if (decode_count > 0) begin // Output decoded value
          decode_value <= {decode_value, din};
          decode_count <= decode_count - 1;
          if (decode_count == 0) begin
            data_out <= decode_value;
            decode_value <= 0;
          end
        end else begin // Output non-consecutive bits
          data_out <= din;
        end
      end

      last_bit <= din; // Store last bit received
    end
  end

endmodule

module LIN_transmitter (
  input [n-1:0] in,
  input start,
  input stop,
  input parity,
  output reg out
);
  parameter n = 8; // number of bits in data payload
  parameter baud = 9600; // baud rate of LIN network
  integer i;
  always @(posedge start) begin
    out = start;
    #baud;
    for (i = 0; i < n; i = i + 1) begin
      out = in[i];
      #baud;
    end
    out = parity;
    #baud;
    out = stop;
    #baud;
  end
endmodule

module LIN_receiver (
  input in,
  output reg [n-1:0] out
);
  parameter n = 8; // number of bits in data payload
  parameter baud = 9600; // baud rate of LIN network
  integer i;
  reg start_received = 0;
  always @(posedge in) begin
    if (!start_received) begin
      start_received = 1;
      #baud;
      for (i = 0; i < n; i = i + 1) begin
        out[i] = in;
        #baud;
      end
      start_received = 0;
    end
  end
endmodule

