wire fifo_empty;

assign next_wr_ptr = wr_ptr + 1;
assign next_rd_ptr = rd_ptr + 1;
assign next_depth = depth + wr_en - rd_en;
assign next_mask = min;

assign wr_en = write & !fifo_full;
assign rd_en = read & !fifo_empty;
assign fifo_full = (depth == 16);
assign fifo_empty = (depth == 0);

always @(posedge wrclk) begin
    if(wr_en) begin
        fifo[wr_ptr] <= din;
        wr_ptr <= next_wr_ptr;
        depth <= next_depth;
        mask <= next_mask;
    end
end

always @(posedge rdclk) begin
    if(rd_en) begin
        dout <= fifo[rd_ptr];
        mout <= mask;
        rd_ptr <= next_rd_ptr;
        depth <= next_depth;
        mask <= next_mask;
    end
end

assign full = fifo_full;
assign empty = fifo_empty;

endmodule

module axis_eth_fcs #
(
    // Width of AXI stream interfaces in bits
    parameter DATA_WIDTH = 8,
    // Propagate tkeep signal
    // If disabled, tkeep assumed to be 1'b1
    parameter KEEP_ENABLE = (DATA_WIDTH>8),
    // tkeep signal width (words per cycle)
    parameter KEEP_WIDTH = (DATA_WIDTH/8)
)
(
    input  wire                   clk,
    input  wire                   rst,

    /*
     * AXI input
     */
    input  wire [DATA_WIDTH-1:0]  s_axis_tdata,
    input  wire [KEEP_WIDTH-1:0]  s_axis_tkeep,
    input  wire                   s_axis_tvalid,
    output wire                   s_axis_tready,
    input  wire                   s_axis_tlast,
    input  wire                   s_axis_tuser,

    /*
     * FCS output
     */
    output wire [31:0]            output_fcs,
    output wire                   output_fcs_valid
);

// bus width assertions
initial begin
    if (KEEP_WIDTH * 8 != DATA_WIDTH) begin
        $error("Error: AXI stream interface requires byte (8-bit) granularity (instance %m)");
        $finish;
    end
end

reg [31:0] crc_state = 32'hFFFFFFFF;
reg [31:0] fcs_reg = 32'h00000000;
reg fcs_valid_reg = 1'b0;

wire [31:0] crc_next[KEEP_WIDTH-1:0];

assign s_axis_tready = 1;
assign output_fcs = fcs_reg;
assign output_fcs_valid = fcs_valid_reg;

generate

    genvar n;

    for (n = 0; n < KEEP_WIDTH; n = n + 1) begin : crc

        lfsr #(
            .LFSR_WIDTH(32),
            .LFSR_POLY(32'h4c11db7),
            .LFSR_CONFIG("GALOIS"),
            .LFSR_FEED_FORWARD(0),
            .REVERSE(1),
            .DATA_WIDTH(DATA_WIDTH/KEEP_WIDTH*(n+1)),
            .STYLE("AUTO")
        )
        eth_crc_inst (
            .data_in(s_axis_tdata[DATA_WIDTH/KEEP_WIDTH*(n+1)-1:0]),
            .state_in(crc_state),
            .data_out(),
            .state_out(crc_next[n])
        );

    end

endgenerate

integer i;

always @(posedge clk) begin
    fcs_valid_reg <= 1'b0;

    if (s_axis_tvalid) begin
        crc_state <= crc_next[KEEP_WIDTH-1];

        if (s_axis_tlast) begin
            crc_state <= 32'hFFFFFFFF;
            if (KEEP_ENABLE) begin
                fcs_reg <= ~crc_next[0];
                for (i = 0; i < KEEP_WIDTH; i = i + 1) begin
                    if (s_axis_tkeep[i]) begin
                        fcs_reg <= ~crc_next[i];
                    end
                end
            end else begin
                fcs_reg <= ~crc_next[KEEP_WIDTH-1];
            end
            fcs_valid_reg <= 1'b1;
        end
    end

    if (rst) begin
        crc_state <= 32'hFFFFFFFF;
        fcs_valid_reg <= 1'b0;
    end
end

endmodule

module calculator(
  input clk,
  input rst,
  input [1:0] op,
  input signed [15:0] a,
  input signed [15:0] b,
  output signed [15:0] result
);

reg [15:0] reg_result;

always @(posedge clk) begin
  if (rst) begin
    reg_result <= 0;
  end else begin
    case (op)
      2'b00: reg_result <= a + b;
      2'b01: reg_result <= a - b;
      2'b10: reg_result <= a * b;
      2'b11: reg_result <= a / b;
    endcase
  end
end

assign result = reg_result;

endmodule

