module CONTROL_UNIT (
  op,
  func,
  z,
  wreg,
  regrt,
  jal,
  m2reg,
  shfit,
  aluimm,
  sext,
  wmem,
  aluc,
  pcsource
);

input wire [5 : 0] op;
input wire [5 : 0] func;
input wire z;
output wire wreg;
output wire regrt;
output wire jal;
output wire m2reg;
output wire shfit;
output wire aluimm;
output wire sext;
output wire wmem;
output wire [3 : 0] aluc;
output wire [1 : 0] pcsource;

  // Define control signals for each instruction
  assign wreg = (op == 6'b101011 || op == 6'b000000) ? 1'b0 : 1'b1;
  assign regrt = (op == 6'b101011 || op == 6'b100011 || op == 6'b101001) ? 1'b1 : 1'b0;
  assign jal = (op == 6'b000011) ? 1'b1 : 1'b0;
  assign m2reg = (op == 6'b100011 || op == 6'b100000 || op == 6'b100010 || op == 6'b101011 || op == 6'b101001) ? 1'b1 : 1'b0;
  assign shfit = (op == 6'b000000) ? 1'b1 : 1'b0;
  assign aluimm = (op == 6'b001000 || op == 6'b001100 || op == 6'b001101 || op == 6'b001110) ? 1'b1 : 1'b0;
  assign sext = (op == 6'b001000 || op == 6'b001100 || op == 6'b001101 || op == 6'b001110 || op == 6'b100011 || op == 6'b100000 || op == 6'b100010 || op == 6'b101011 || op == 6'b101001) ? 1'b1 : 1'b0;
  assign wmem = (op == 6'b101011 || op == 6'b101001) ? 1'b1 : 1'b0;

  // Define ALU control signals
  assign aluc = (op == 6'b000000) ? // R-type
                  (func == 6'b100000 || func == 6'b100010) ? 4'b0010 : // add, sub
                  (func == 6'b100100) ? 4'b0000 : // and
                  (func == 6'b100101) ? 4'b0001 : // or
                  (func == 6'b100110) ? 4'b0101 : // xor
                  (func == 6'b000000) ? 4'b0110 : // sll
                  (func == 6'b000010) ? 4'b0111 : // srl
                  (func == 6'b000011) ? 4'b1000 : // sra
                  4'b0000 // default
              : // I-type
                  (op == 6'b001000 || op == 6'b001100 || op == 6'b001101 || op == 6'b001110) ? 4'b0010 : // addi, andi, ori, xori
                  (op == 6'b100011 || op == 6'b101011) ? 4'b0110 : // lw, sw
                  (op == 6'b000100 || op == 6'b000101) ? 4'b0101 : // beq, bne
                  (op == 6'b001111) ? 4'b0000 : // lui
                  4'b0000; // default

  // Define PC source signals
  assign pcsource = (op == 6'b000010 || op == 6'b000011) ? // j, jal
                      2'b10 :
                    (op == 6'b000100 && z) ? // beq
                      2'b01 :
                    (op == 6'b000101 && !z) ? // bne
                      2'b01 :
                      2'b00; // default

endmodule

