module bram_interface #(
    parameter DATA_WIDTH = 32
)(
    input ready,
    input rstn,
    input clk,
    output reg valid,
    output reg [DATA_WIDTH-1:0] data,
    output reg bram_clk,
    output reg bram_rst,
    output reg bram_en,
    output reg [3:0] bram_we,
    output reg [DATA_WIDTH-1:0] bram_addr,
    input [DATA_WIDTH-1:0] bram_dout,
    output reg [DATA_WIDTH-1:0] bram_din
);

    localparam IDLE = 2'b00;
    localparam S0 = 2'b01;
    localparam S1 = 2'b10;
    localparam WAIT0 = 2'b11;

    reg [1:0] state;
    reg [63:0] counter;
    reg [31:0] temp;

    always @(posedge clk, negedge rstn) begin
        if (~rstn) begin
            state <= IDLE;
            counter <= 0;
            temp <= 0;
            valid <= 0;
            bram_clk <= 0;
            bram_rst <= 1;
            bram_en <= 0;
            bram_we <= 4'b0000;
            bram_addr <= 0;
            bram_din <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (ready) begin
                        state <= S0;
                    end
                end
                S0: begin
                    bram_din <= {counter[31:0], 32'b0};
                    bram_en <= 1;
                    bram_we <= 4'b1111;
                    bram_addr <= bram_addr + 4;
                    state <= S1;
                end
                S1: begin
                    bram_din <= {32'b0, counter[63:32]};
                    bram_en <= 1;
                    bram_we <= 4'b1111;
                    bram_addr <= bram_addr + 4;
                    state <= WAIT0;
                end
                WAIT0: begin
                    if (~ready) begin
                        valid <= 1;
                        state <= IDLE;
                    end
                end
            endcase
            counter <= counter + 1;
            temp <= counter;
            data <= temp[31:0];
            bram_clk <= clk;
            bram_rst <= ~rstn;
        end
    end

endmodule

