module edge_detection(
    input clk,
    input rst_n,
    input signal,
    output reg rise,
    output reg down
);

reg prev_signal;

always @(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        prev_signal <= 1'b0;
        rise <= 1'b0;
        down <= 1'b0;
    end
    else begin
        if(signal && !prev_signal) begin
            rise <= 1'b1;
            down <= 1'b0;
        end
        else if(!signal && prev_signal) begin
            rise <= 1'b0;
            down <= 1'b1;
        end
        else begin
            rise <= 1'b0;
            down <= 1'b0;
        end
        prev_signal <= signal;
    end
end

endmodule

