);

parameter n = 8; // number of input signals

wire [log2(n)-1:0] priority;
assign priority = $onehot0(in);

always @* begin
  case (priority)
    1'b1: out = 1'b0;
    1'b10: out = 1'b1;
    1'b100: out = 2'b01;
    1'b1000: out = 3'b001;
    1'b10000: out = 4'b0001;
    1'b100000: out = 5'b00001;
    1'b1000000: out = 6'b000001;
    1'b10000000: out = 7'b0000001;
    default: out = {log2(n){1'b0}}; // all inputs are zero
  endcase
end

endmodule

