module spi_bus (
    input SBCLKI,
    input SBRWI,
    input SBSTBI,
    input [7:0] SBADRI,
    input [7:0] SBDATI,
    input MI,
    input SI,
    input SCKI,
    input SCSNI,
    output reg [7:0] SBDATO,
    output reg SBACKO,
    output reg SPIIRQ,
    output reg SPIWKUP,
    output reg SO,
    output reg SOE,
    output reg MO,
    output reg MOE,
    output reg SCKO,
    output reg SCKOE,
    output reg [3:0] MCSNO,
    output reg [3:0] MCSNOE
);

parameter BUS_ADDR74 = "0b0000";

reg [7:0] shift_reg;
reg [7:0] data_reg;
reg [7:0] addr_reg;
reg [3:0] cs_reg;
reg [1:0] rw_reg;
reg [2:0] state_reg;

localparam IDLE = 3'b000;
localparam ADDR = 3'b001;
localparam READ = 3'b010;
localparam WRITE = 3'b011;
localparam ACK = 3'b100;

always @(posedge SBCLKI) begin
    // Shift in data
    shift_reg <= {shift_reg[6:0], SBDATI[7]};

    // Update state
    case(state_reg)
        IDLE: begin
            // Check for chip select
            if(SCSNI == 0) begin
                // Update address register
                addr_reg <= SBADRI;

                // Update read/write register
                rw_reg <= SBRWI[0:1];

                // Update chip select register
                cs_reg <= {cs_reg[2:0], 1};

                // Move to address state
                state_reg <= ADDR;
            end
        end

        ADDR: begin
            // Shift in address
            data_reg <= {data_reg[6:0], addr_reg[7]};

            // Check for last bit of address
            if(addr_reg[0] == 1) begin
                // Move to read or write state
                if(rw_reg == 2'b00) begin
                    // Move to read state
                    state_reg <= READ;
                end else begin
                    // Move to write state
                    state_reg <= WRITE;
                end
            end

            // Shift address register
            addr_reg <= {addr_reg[6:0], 0};
        end

        READ: begin
            // Shift in data
            data_reg <= {data_reg[6:0], SI};

            // Check for last bit of data
            if(shift_reg[0] == 1) begin
                // Update data output
                SBDATO <= data_reg;

                // Update acknowledge output
                SBACKO <= 1;

                // Move to idle state
                state_reg <= ACK;
            end
        end

        WRITE: begin
            // Shift out data
            SO <= data_reg[7];

            // Check for last bit of data
            if(shift_reg[0] == 1) begin
                // Move to idle state
                state_reg <= IDLE;
            end

            // Shift data register
            data_reg <= {data_reg[6:0], shift_reg[7]};
        end

        ACK: begin
            // Check for chip select
            if(SCSNI == 1) begin
                // Update chip select register
                cs_reg <= {cs_reg[2:0], 0};

                // Move to idle state
                state_reg <= IDLE;
            end
        end
    endcase
end

always @(negedge SCKI) begin
    // Update multi-chip select outputs
    MCSNO <= cs_reg;

    // Update multi-chip select output enables
    MCSNOE <= {cs_reg[2:0], 1'b1};

    // Update interrupt request output
    SPIIRQ <= 0;

    // Update wakeup output
    SPIWKUP <= 0;

    // Update master output
    MO <= 0;

    // Update master output enable
    MOE <= 0;

    // Update serial clock output
    SCKO <= SCKI;

    // Update serial clock output enable
    SCKOE <= 1;

    // Update serial output enable
    SOE <= 1;

    // Update acknowledge output
    SBACKO <= 0;

    // Update state
    state_reg <= IDLE;
end

endmodule

module floating_point_multiplier (
    input [15:0] float_a,
    input [15:0] float_b,
    output reg [15:0] float_out
);

reg [15:0] mantissa_a, mantissa_b, mantissa_out;
reg [7:0] exponent_a, exponent_b, exponent_out;
reg sign_a, sign_b, sign_out;

// Stage 1: Extract mantissa, exponent, and sign for both inputs
always @(*) begin
    sign_a = float_a[15];
    sign_b = float_b[15];
    exponent_a = float_a[14:7];
    exponent_b = float_b[14:7];
    mantissa_a = {1'b1, float_a[6:0]};
    mantissa_b = {1'b1, float_b[6:0]};
end

// Stage 2: Calculate the sign of the output
always @(*) begin
    sign_out = sign_a ^ sign_b;
end

// Stage 3: Calculate the exponent of the output
always @(*) begin
    exponent_out = exponent_a + exponent_b - 127;
end

// Stage 4: Multiply the mantissas together
always @(*) begin
    mantissa_out = mantissa_a * mantissa_b;
end

// Stage 5: Normalize the mantissa and adjust the exponent accordingly
always @(*) begin
    if (mantissa_out[16]) begin
        exponent_out = exponent_out + 1;
        mantissa_out = mantissa_out >> 1;
    end
end

// Stage 6: Round the mantissa to 16 bits
always @(*) begin
    if (mantissa_out[15] && (mantissa_out[14:0] != 15'hFFFF)) begin
        mantissa_out = mantissa_out + 1;
    end
end

// Stage 7: Pack the result into a 16-bit floating-point number
always @(*) begin
    float_out[15] = sign_out;
    float_out[14:7] = exponent_out;
    float_out[6:0] = mantissa_out[14:8];
end

endmodule

