module oscillator (
  output out
);

parameter type = "ring"; // type of oscillator (ring or relaxation)
parameter n = 5; // number of inverters in the ring oscillator (ignored if type is relaxation)
parameter R = 100; // value of the resistor in the relaxation oscillator (ignored if type is ring)
parameter C = 0.1; // value of the capacitor in the relaxation oscillator (ignored if type is ring)

reg [1:0] state; // state variable for relaxation oscillator
wire [n-1:0] ring_out; // output of ring oscillator

// Ring oscillator implementation
generate
  if (type == "ring") begin : ring_oscillator
    assign ring_out[0] = state[0];
    genvar i;
    for (i = 1; i < n; i = i + 1) begin : inverter_loop
      assign ring_out[i] = ~ring_out[i-1];
    end
    assign out = ring_out[n-1];
  end
endgenerate

// Relaxation oscillator implementation
generate
  if (type == "relaxation") begin : relaxation_oscillator
    always @ (posedge state[1]) begin
      state <= {state[0], ~state[1]};
    end
    assign out = state[0];
  end
endgenerate

// Capacitor charging and discharging
generate
  if (type == "relaxation") begin : capacitor_charging
    reg [31:0] counter;
    reg charging;
    always @ (posedge state[1]) begin
      if (charging) begin
        counter <= counter + 1;
        if (counter == 100) begin
          charging <= 0;
          counter <= 0;
        end
      end else begin
        counter <= counter + 1;
        if (counter == R*C*1000000) begin
          charging <= 1;
          counter <= 0;
        end
      end
    end
  end
endgenerate

// Sawtooth wave generation
generate
  if (type == "relaxation") begin : sawtooth_wave
    always @ (posedge state[1]) begin
      if (charging) begin
        state[0] <= 0;
      end else begin
        state[0] <= 1;
      end
    end
  end
endgenerate

