module LZW (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 8; // number of input signals
parameter m = 12; // number of output signals
parameter w = 8; // number of bits per symbol

// Define the dictionary and codes
reg [w-1:0] dict [0:2**w-1];
reg [w-1:0] code [0:2**w-1];
reg [w-1:0] seq [0:2**w-1];
reg [w-1:0] curr_seq;
reg [w-1:0] next_sym;
reg [w-1:0] prev_seq;
reg [w-1:0] curr_code;
reg [w-1:0] next_seq;
reg [w-1:0] output_code;
reg [w-1:0] input_code;
reg [w-1:0] prev_code;
reg [w-1:0] curr_sym;
reg [w-1:0] next_code;
reg [w-1:0] new_seq;
reg [w-1:0] new_code;
reg [w-1:0] output_seq;
reg [w-1:0] input_seq;
reg [w-1:0] next_sym_seq;
reg [w-1:0] prev_sym_seq;
reg [w-1:0] curr_sym_seq;

// Initialize the dictionary and codes
initial begin
  for (i = 0; i < 2**w; i = i + 1) begin
    dict[i] = i;
    code[i] = i;
    seq[i] = i;
  end
end

// Compressor
always @(*) begin
  curr_seq = in[0:w-1];
  output_code = 0;
  for (i = 1; i < n; i = i + 1) begin
    next_sym = in[i*w:i*w+w-1];
    next_seq = {curr_seq, next_sym};
    if (dict[next_seq] != 0) begin
      curr_seq = next_seq;
    end else begin
      output_code = code[curr_seq];
      dict[next_seq] = 2**w + i - 1;
      code[next_seq] = 2**w + i;
      curr_seq = next_sym;
    end
  end
  output_code = code[curr_seq];
  out = output_code;
end

// Decompressor
always @(*) begin
  curr_code = in[0:w-1];
  output_seq = seq[curr_code];
  prev_code = curr_code;
  for (i = 1; i < m; i = i + 1) begin
    input_code = in[i*w:i*w+w-1];
    if (code[input_code] != 0) begin
      curr_sym = seq[input_code];
      out[i*w:i*w+w-1] = curr_sym;
      next_code = dict[{prev_seq, curr_sym}];
      if (next_code != 0) begin
        prev_seq = prev_sym_seq;
        curr_seq = curr_sym_seq;
        curr_sym_seq = curr_sym;
      end else begin
        prev_seq = prev_sym_seq;
        curr_seq = {curr_sym_seq, curr_sym};
        curr_sym_seq = curr_sym;
        new_seq = {prev_sym_seq, curr_sym_seq};
        new_code = 2**w + i;
        dict[new_seq] = new_code;
        seq[new_code] = new_seq;
        code[new_seq] = new_code;
      end
      prev_code = input_code;
    end else begin
      $display("Error: Invalid code detected.");
      $finish;
    end
  end
end

endmodule

