      if (counter == 8'd10) begin // Arbitrary counter value
        demodulated_data <= data_in ^ carrier_signal; // XOR data with carrier signal
        data_out <= demodulated_data;
        rx_en <= 1'b1;
      end else if (counter == 8'd20) begin // Arbitrary counter value
        demodulated_data <= 8'b0;
        rx_en <= 1'b0;
        counter <= 8'b0;
      end
    end else begin
      demodulated_data <= 8'b0;
      rx_en <= 1'b0;
      counter <= 8'b0;
    end
  end

endmodule

module booth_multiplier (
    input [3:0] A,
    input [3:0] B,
    output [7:0] P
);

reg [7:0] P_reg;
reg [4:0] A_reg, B_reg;
reg [2:0] counter;

always @(*) begin
    P_reg = A_reg * B_reg;
end

always @(posedge clk) begin
    if (reset) begin
        A_reg <= 0;
        B_reg <= 0;
        P_reg <= 0;
        counter <= 0;
    end else begin
        case (counter)
            0: begin
                A_reg <= {1'b0, A};
                B_reg <= {1'b0, B};
            end
            1, 2: begin
                if (B_reg[0] == 1) begin
                    P_reg <= P_reg - A_reg;
                end else begin
                    P_reg <= P_reg + A_reg;
                end
                A_reg <= A_reg << 1;
                B_reg <= B_reg >> 1;
            end
            3: begin
                P <= P_reg[7:0];
            end
        endcase
        counter <= counter + 1;
    end
end

endmodule

