module spi_master (
  input SCLK,
  input MOSI,
  input SS,
  input [7:0] data_in,
  output [7:0] data_out
);

  reg [7:0] shift_reg;
  reg [2:0] state;
  reg ss_active;

  always @(posedge SCLK) begin
    if (SS == 0) begin
      ss_active <= 1;
      state <= 3'b001;
    end else if (ss_active) begin
      case (state)
        3'b001: begin // Send MSB first
          shift_reg <= {data_in[7], shift_reg[7:1]};
          state <= 3'b010;
        end
        3'b010: begin // Shift out data
          data_out <= shift_reg[7];
          shift_reg <= shift_reg[6:0];
          state <= 3'b001;
        end
      endcase
    end else begin
      ss_active <= 0;
      state <= 3'b000;
    end
  end

endmodule

module spi_slave (
  input SCLK,
  input MOSI,
  input SS,
  output [7:0] data_out
);

  reg [7:0] shift_reg;
  reg [2:0] state;
  reg ss_active;

  always @(posedge SCLK) begin
    if (SS == 0) begin
      ss_active <= 1;
      state <= 3'b001;
    end else if (ss_active) begin
      case (state)
        3'b001: begin // Wait for first clock edge
          state <= 3'b010;
        end
        3'b010: begin // Shift in data
          shift_reg <= {MOSI, shift_reg[7:1]};
          state <= 3'b001;
        end
      endcase
    end else begin
      ss_active <= 0;
      state <= 3'b000;
    end
  end

  assign data_out = shift_reg;

endmodule

