input load_sign_ext;
output [WIDTH-1:0] d_loadresult;

reg [WIDTH-1:0] d_loadresult;

always @(d_readdatain or d_address or load_size or load_sign_ext)
begin
    case (load_size)
        2'b11:
        begin
            case (d_address[1:0])
                0: d_loadresult[7:0]=d_readdatain[31:24];
                1: d_loadresult[7:0]=d_readdatain[23:16];
                2: d_loadresult[7:0]=d_readdatain[15:8];
                default: d_loadresult[7:0]=d_readdatain[7:0];
            endcase
            d_loadresult[31:8]={24{load_sign_ext&d_loadresult[7]}};
        end
        2'b01:
        begin
            case (d_address[1])
                0: d_loadresult[15:0]=d_readdatain[31:16];
                default: d_loadresult[15:0]=d_readdatain[15:0];
            endcase
            d_loadresult[31:16]={16{load_sign_ext&d_loadresult[15]}};
        end
        default:
            d_loadresult=d_readdatain;
    endcase
end

endmodule

module SSCG (
  input ref_clk,
  input modulation,
  output spread_clk
);

parameter f_ref = 50e6; // frequency of reference clock signal
parameter f_spread = 0.1; // amount of frequency spread, expressed as a percentage of f_ref
parameter t_spread = 10; // duration of each spread cycle, expressed in units of the reference clock period
parameter t_mod = 100; // duration of each modulation period, expressed in units of the reference clock period

reg [31:0] counter_spread = 0; // counter for spread cycle duration
reg [31:0] counter_mod = 0; // counter for modulation period duration
reg [31:0] counter_period = 0; // counter for overall period duration
reg [31:0] spread_offset = 0; // offset for spread frequency
reg [31:0] spread_period = 0; // period for spread frequency

always @(posedge ref_clk) begin
  // update counters
  counter_spread <= counter_spread + 1;
  counter_mod <= counter_mod + 1;
  counter_period <= counter_period + 1;

  // calculate spread frequency offset
  if (counter_spread >= t_spread) begin
    counter_spread <= 0;
    spread_offset <= $random % (f_ref * f_spread * 2) - (f_ref * f_spread);
  end

  // calculate spread frequency period
  if (counter_mod >= t_mod) begin
    counter_mod <= 0;
    spread_period <= $random % (t_mod * 2) - t_mod;
  end

  // calculate spread frequency
  spread_clk <= ref_clk + spread_offset;

  // adjust spread frequency based on modulation signal
  if (modulation) begin
    spread_clk <= spread_clk + (spread_offset * modulation);
  end

  // adjust spread frequency based on spread period
  if (counter_period >= spread_period) begin
    counter_period <= 0;
    spread_clk <= ref_clk + spread_offset;
  end
end

endmodule

