module FSM (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 4; // number of input signals
parameter m = 2; // number of output signals
parameter s = 8; // number of states

reg [log2(s)-1:0] state; // register to hold current state

// define state encoding
localparam STATE_0 = 3'b000;
localparam STATE_1 = 3'b001;
localparam STATE_2 = 3'b010;
localparam STATE_3 = 3'b011;
localparam STATE_4 = 3'b100;
localparam STATE_5 = 3'b101;
localparam STATE_6 = 3'b110;
localparam STATE_7 = 3'b111;

// define output encoding
localparam OUT_0 = 2'b00;
localparam OUT_1 = 2'b01;
localparam OUT_2 = 2'b10;
localparam OUT_3 = 2'b11;

// define transition rules
always @ (state or in) begin
  case (state)
    STATE_0: begin
      if (in == 4'b0000) state <= STATE_0;
      else if (in == 4'b0001) state <= STATE_1;
      else if (in == 4'b0010) state <= STATE_2;
      else if (in == 4'b0011) state <= STATE_3;
      else if (in == 4'b0100) state <= STATE_4;
      else if (in == 4'b0101) state <= STATE_5;
      else if (in == 4'b0110) state <= STATE_6;
      else if (in == 4'b0111) state <= STATE_7;
    end
    STATE_1: begin
      if (in == 4'b0000) state <= STATE_0;
      else if (in == 4'b0001) state <= STATE_1;
      else if (in == 4'b0010) state <= STATE_2;
      else if (in == 4'b0011) state <= STATE_3;
      else if (in == 4'b0100) state <= STATE_4;
      else if (in == 4'b0101) state <= STATE_5;
      else if (in == 4'b0110) state <= STATE_6;
      else if (in == 4'b0111) state <= STATE_7;
    end
    STATE_2: begin
      if (in == 4'b0000) state <= STATE_0;
      else if (in == 4'b0001) state <= STATE_1;
      else if (in == 4'b0010) state <= STATE_2;
      else if (in == 4'b0011) state <= STATE_3;
      else if (in == 4'b0100) state <= STATE_4;
      else if (in == 4'b0101) state <= STATE_5;
      else if (in == 4'b0110) state <= STATE_6;
      else if (in == 4'b0111) state <= STATE_7;
    end
    STATE_3: begin
      if (in == 4'b0000) state <= STATE_0;
      else if (in == 4'b0001) state <= STATE_1;
      else if (in == 4'b0010) state <= STATE_2;
      else if (in == 4'b0011) state <= STATE_3;
      else if (in == 4'b0100) state <= STATE_4;
      else if (in == 4'b0101) state <= STATE_5;
      else if (in == 4'b0110) state <= STATE_6;
      else if (in == 4'b0111) state <= STATE_7;
    end
    STATE_4: begin
      if (in == 4'b0000) state <= STATE_0;
      else if (in == 4'b0001) state <= STATE_1;
      else if (in == 4'b0010) state <= STATE_2;
      else if (in == 4'b0011) state <= STATE_3;
      else if (in == 4'b0100) state <= STATE_4;
      else if (in == 4'b0101) state <= STATE_5;
      else if (in == 4'b0110) state <= STATE_6;
      else if (in == 4'b0111) state <= STATE_7;
    end
    STATE_5: begin
      if (in == 4'b0000) state <= STATE_0;
      else if (in == 4'b0001) state <= STATE_1;
      else if (in == 4'b0010) state <= STATE_2;
      else if (in == 4'b0011) state <= STATE_3;
      else if (in == 4'b0100) state <= STATE_4;
      else if (in == 4'b0101) state <= STATE_5;
      else if (in == 4'b0110) state <= STATE_6;
      else if (in == 4'b0111) state <= STATE_7;
    end
    STATE_6: begin
      if (in == 4'b0000) state <= STATE_0;
      else if (in == 4'b0001) state <= STATE_1;
      else if (in == 4'b0010) state <= STATE_2;
      else if (in == 4'b0011) state <= STATE_3;
      else if (in == 4'b0100) state <= STATE_4;
      else if (in == 4'b0101) state <= STATE_5;
      else if (in == 4'b0110) state <= STATE_6;
      else if (in == 4'b0111) state <= STATE_7;
    end
    STATE_7: begin
      if (in == 4'b0000) state <= STATE_0;
      else if (in == 4'b0001) state <= STATE_1;
      else if (in == 4'b0010) state <= STATE_2;
      else if (in == 4'b0011) state <= STATE_3;
      else if (in == 4'b0100) state <= STATE_4;
      else if (in == 4'b0101) state <= STATE_5;
      else if (in == 4'b0110) state <= STATE_6;
      else if (in == 4'b0111) state <= STATE_7;
    end
  endcase
end

// define output rules
always @ (state or in) begin
  case (state)
    STATE_0: out <= {OUT_0, OUT_0};
    STATE_1: out <= {OUT_0, OUT_1};
    STATE_2: out <= {OUT_0, OUT_2};
    STATE_3: out <= {OUT_0, OUT_3};
    STATE_4: out <= {OUT_1, OUT_0};
    STATE_5: out <= {OUT_1, OUT_1};
    STATE_6: out <= {OUT_1, OUT_2};
    STATE_7: out <= {OUT_1, OUT_3};
  endcase
end

endmodule

module stack(DataIO, Reset, Push, Pop, 
              SP, Full, Empty, Err); 

  // declare input, output and inout ports
  inout [3:0] DataIO; 
  input Push, Pop, Reset;
  output Full, Empty, Err;
  output [2:0] SP;

  // Declare registers
  reg Full, Empty, Err;
  reg [2:0] SP;
  reg [3:0] Stack [7:0];
  reg [3:0] DataR;

  //Continous assignment of DataIO to DataR register, with delay 0
  wire [3:0]  #(0) DataIO = DataR;

  //Initialize the stack pointer and flags
  initial begin
    SP = 3'b0;
    Full = 0;
    Empty = 1;
    Err = 0;
  end

  always @(posedge Push or posedge Pop or posedge Reset) 
  begin

    if (Push == 1)
    begin
      //WHen the stack is empty
      if (Empty == 1)
      begin
        Stack[SP] = DataIO;
        Empty = 0;
        if (Err == 1)
          Err = 0;
      end
      else if (Full == 1) //When the stack is full
      begin
        Stack[SP] = DataIO;
        Err = 1;
      end
      else
      begin
        SP = SP + 1;
        Stack[SP] = DataIO;
        if (SP == 3'b111)
          Full = 1;
      end
    end


    if (Pop == 1) //if SP indicates the last location but
    begin             // the stack is not empty 
      if ((SP == 3'b000) && (Empty != 1))
      begin
        DataR = Stack[SP];
        Empty = 1;
      end
      else if (Empty == 1) //When the stack is empty
      begin
        DataR = Stack[SP];
        Err = 1;
      end
      else
      begin
        DataR = Stack[SP];
        if (SP != 3'b000)
          SP = SP - 1;
        //if the stack is full
        if (Err == 1)  Err = 0;
        if (Full == 1)  Full = 0;
      end
    end


    if (Reset == 1)
    begin
      DataR = 4'bzzzz;
      SP = 3'b0;
      Full = 0;
      Empty = 1;
      Err = 0;
    end

  end


  always @(negedge Pop)
  begin
    DataR = 4'bzzzz;
  end  


endmodule

module data_transfer(clk, rst, input_data, input_valid, output_data, output_valid);
  input clk, rst, input_valid;
  input [7:0] input_data;
  output [7:0] output_data;
  output output_valid;

  reg [7:0] data_reg;
  reg valid_reg;

  always @(posedge clk) begin
    if (rst) begin
      data_reg <= 0;
      valid_reg <= 0;
    end else if (input_valid) begin
      data_reg <= input_data;
      valid_reg <= 1;
    end else begin
      valid_reg <= 0;
    end
  end

  assign output_data = data_reg;
  assign output_valid = valid_reg;

endmodule

module SyncFIFOMultiByte #(
    parameter dsize = 8,
    parameter fifodepth = 32,
    parameter fifoidx = 5,
    parameter byte_size = 8 // number of bits in a byte
) (
    input wire sCLK,
    input wire sRST_N,
    input wire dCLK,
    input wire sENQ,
    input wire [fifodepth*byte_size-1:0] sDIN,
    input wire sFULL_N,
    output wire dDEQ,
    output wire [fifodepth*byte_size-1:0] dDOUT,
    output wire dEMPTY_N
);

    reg [fifoidx-1:0] wr_ptr;
    reg [fifoidx-1:0] rd_ptr;
    reg [fifoidx-1:0] next_wr_ptr;
    reg [fifoidx-1:0] next_rd_ptr;
    reg [fifodepth*byte_size-1:0] mem [0:fifodepth-1];
    reg [fifodepth-1:0] count;
    reg [fifodepth-1:0] next_count;
    reg [fifodepth-1:0] byte_count;
    reg [fifodepth-1:0] next_byte_count;
    reg [byte_size-1:0] byte_idx;
    reg [byte_size-1:0] next_byte_idx;
    reg [dsize-1:0] data_reg;
    wire [dsize-1:0] data_out;
    reg [dsize-1:0] data_in;
    reg [byte_size-1:0] byte_cnt;
    reg [byte_size-1:0] next_byte_cnt;
    reg [dsize-1:0] data_out_reg;
    reg [byte_size-1:0] byte_cnt_reg;
    reg [fifodepth-1:0] count_reg;
    reg [fifodepth*byte_size-1:0] mem_reg [0:fifodepth-1];
    reg [byte_size-1:0] byte_idx_reg;
    reg [fifoidx-1:0] rd_ptr_reg;
    reg [fifoidx-1:0] wr_ptr_reg;
    reg [fifodepth-1:0] byte_count_reg;

    assign dDOUT = data_out_reg;
    assign dDEQ = ~dEMPTY_N;
    assign dEMPTY_N = (count_reg != 0);

    always @(posedge sCLK) begin
        if (!sRST_N) begin
            wr_ptr <= 0;
            rd_ptr <= 0;
            count <= 0;
            byte_count <= 0;
            byte_idx <= 0;
        end else if (sENQ && sFULL_N) begin
            next_wr_ptr <= wr_ptr + 1;
            next_count <= count + 1;
            next_byte_count <= byte_count + 1;
            next_byte_idx <= byte_idx + 1;
            data_in <= sDIN;
        end else begin
            next_wr_ptr <= wr_ptr;
            next_count <= count;
            next_byte_count <= byte_count;
            next_byte_idx <= byte_idx;
            data_in <= data_in;
        end
    end

    always @(posedge dCLK) begin
        if (!sRST_N) begin
            rd_ptr <= 0;
            byte_cnt <= 0;
        end else if (dDEQ && ~dEMPTY_N) begin
            next_rd_ptr <= rd_ptr + 1;
            next_byte_cnt <= byte_cnt + 1;
        end else begin
            next_rd_ptr <= rd_ptr;
            next_byte_cnt <= byte_cnt;
        end
    end

    always @(posedge sCLK) begin
        wr_ptr <= next_wr_ptr;
        count <= next_count;
        byte_count <= next_byte_count;
        byte_idx <= next_byte_idx;
        byte_cnt_reg <= byte_cnt;
        wr_ptr_reg <= wr_ptr;
        count_reg <= count;
        byte_count_reg <= byte_count;
        byte_idx_reg <= byte_idx;
        if (sENQ && sFULL_N) begin
            mem[wr_ptr][byte_idx*byte_size +: byte_size] <= data_in[byte_idx*byte_size +: byte_size];
            if (byte_count == fifodepth-1) begin
                next_wr_ptr <= wr_ptr;
            end else if (byte_idx == byte_count_reg) begin
                next_wr_ptr <= wr_ptr + 1;
            end
        end
    end

    always @(posedge dCLK) begin
        rd_ptr <= next_rd_ptr;
        byte_cnt <= next_byte_cnt;
        byte_cnt_reg <= byte_cnt;
        rd_ptr_reg <= rd_ptr;
        data_out_reg <= mem_reg[rd_ptr_reg][byte_cnt_reg*byte_size +: byte_size];
        if (~dEMPTY_N && byte_cnt == byte_count_reg) begin
            if (rd_ptr == fifodepth-1) begin
                next_rd_ptr <= 0;
            end else begin
                next_rd_ptr <= rd_ptr + 1;
            end
        end
    end

    always @(posedge sCLK) begin
        if (!sRST_N) begin
            data_reg <= 0;
        end else if (sENQ && sFULL_N) begin
            data_reg <= sDIN;
        end
    end

    always @(posedge dCLK) begin
        data_out <= mem[rd_ptr][0:dsize-1];
        if (~dEMPTY_N && byte_cnt == 0) begin
            mem_reg <= mem;
        end
    end

    always @(posedge dCLK) begin
        if (~dEMPTY_N && byte_cnt == 0) begin
            rd_ptr_reg <= rd_ptr;
            wr_ptr_reg <= wr_ptr;
            byte_count_reg <= byte_count;
            byte_idx_reg <= byte_idx;
        end
    end

endmodule

module complement_concat (
