module write_back_stage(
    input clk,
    input rst,
    input stall,
    input [31:0] me_memdata,
    input [4:0] me_td,
    input me_WREG,
    output reg [31:0] wb_memdata,
    output reg [4:0] wb_td,
    output reg wb_WREG
);

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            wb_memdata <= 0;
            wb_td <= 0;
            wb_WREG <= 0;
        end else if (stall) begin
            wb_memdata <= 0;
            wb_td <= 0;
            wb_WREG <= 0;
        end else begin
            wb_memdata <= me_memdata;
            wb_td <= me_td;
            wb_WREG <= me_WREG;
