    always @(posedge clk or posedge rst) begin
        if (rst) begin
            // reset all registers
            reg_file <= {32{1'b0}};
        end else if (me_WREG) begin
            // write to register file
            reg_file[me_td] <= me_memdata;
        end
    end

    reg [31:0] reg_file [31:0];

endmodule

