);

reg [0:0] reset_state;

always @(*) begin
    case(reset_state)
        2'b00: begin // reset inactive
            if (ext_reset_in) begin
                reset_state <= 2'b01;
            end else if (aux_reset_in && dcm_locked) begin
                reset_state <= 2'b10;
            end
        end
        2'b01: begin // external reset
            bus_struct_reset <= 1'b1;
            peripheral_reset <= 1'b1;
            interconnect_aresetn <= 1'b1;
            peripheral_aresetn <= 1'b1;
            mb_reset <= 1'b1;
            reset_state <= 2'b00;
        end
        2'b10: begin // auxiliary reset
            bus_struct_reset <= 1'b1;
            peripheral_reset <= 1'b1;
            interconnect_aresetn <= 1'b1;
            peripheral_aresetn <= 1'b1;
            mb_reset <= 1'b1;
            if (mb_debug_sys_rst) begin
                mb_reset <= 1'b1;
            end else if (slowest_sync_clk && !mb_reset) begin
                bus_struct_reset <= 1'b0;
                peripheral_reset <= 1'b0;
                interconnect_aresetn <= 1'b0;
                peripheral_aresetn <= 1'b0;
                reset_state <= 2'b00;
            end
        end
    endcase
end

endmodule

