module controller (
  input  wire        clock,
  input  wire        reset,
  input  wire        run,
  input  wire        wrSize,
  input  wire [31:0] config_data,
  input  wire        validIn,
  input  wire [31:0] dataIn,
  input  wire        busy,
  input  wire        arm,
  // outputs...
  output reg         send,
  output reg  [31:0] memoryWrData,
  output reg         memoryRead,
  output reg         memoryWrite,
  output reg         memoryLastWrite
);

reg [15:0] fwd; // Config registers...
reg [15:0] bwd;

reg next_send;
reg next_memoryRead;
reg next_memoryWrite;
reg next_memoryLastWrite;

reg [17:0] counter, next_counter; 
wire [17:0] counter_inc = counter+1'b1;

always @(posedge clock) 
memoryWrData <= dataIn;

//
// Control FSM...
//
localparam [2:0]
  IDLE =     3'h0,
  SAMPLE =   3'h1,
  DELAY =    3'h2,
  READ =     3'h3,
  READWAIT = 3'h4;

reg [2:0] state, next_state; 

initial state = IDLE;
always @(posedge clock, posedge reset) 
if (reset) begin
  state           <= IDLE;
  memoryWrite     <= 1'b0;
  memoryLastWrite <= 1'b0;
  memoryRead      <= 1'b0;
end else begin
  state           <= next_state;
  memoryWrite     <= next_memoryWrite;
  memoryLastWrite <= next_memoryLastWrite;
  memoryRead      <= next_memoryRead;
end

always @(posedge clock)
begin
  counter <= next_counter;
  send    <= next_send;
end

// FSM to control the controller action
always @*
begin
  next_state = state;
  next_counter = counter;
  next_memoryWrite = 1'b0;
  next_memoryLastWrite = 1'b0;
  next_memoryRead = 1'b0;
  next_send = 1'b0;

  case(state)
    IDLE :
      begin
        next_counter = 0;
        next_memoryWrite = 1;
	if (run) next_state = DELAY;
	else if (arm) next_state = SAMPLE;
      end

    // default mode: write data samples to memory
    SAMPLE : 
      begin
        next_counter = 0;
        next_memoryWrite = validIn;
        if (run) next_state = DELAY;
      end

    // keep sampling for 4 * fwd + 4 samples after run condition
    DELAY : 
      begin
	if (validIn)
	  begin
	    next_memoryWrite = 1'b1;
            next_counter = counter_inc;
            if (counter == {fwd,2'b11}) 	// IED - Evaluate only on validIn to make behavior
	      begin				// match between sampling on all-clocks verses occasionally.
		next_memoryLastWrite = 1'b1;	// Added LastWrite flag to simplify write->read memory handling.
		next_counter = 0;
		next_state = READ;
	      end
	  end
      end

    // read back 4 * bwd + 4 samples after DELAY
    // go into wait state after each sample to give transmitter time
    READ : 
      begin
        next_memoryRead = 1'b1;
        next_send = 1'b1;
        if (counter == {bwd,2'b11}) 
	  begin
            next_counter = 0;
            next_state = IDLE;
          end
        else 
	  begin
            next_counter = counter_inc;
            next_state = READWAIT;
          end
      end

    // wait for the transmitter to become ready again
    READWAIT : 
      begin
        if (!busy && !send) next_state = READ;
      end
  endcase
end


//
// Set speed and size registers if indicated...
//
always @(posedge clock) 
if (wrSize) {fwd, bwd} <= config_data[31:0];

endmodule

module top_module (
    input clk,
    input reset,   // Synchronous active-high reset
    input data,    // Input to load the shift register
    output [7:0] q // 8-bit output from the active module
);

    reg [3:0] counter;
    reg [7:0] shift_reg;
    wire xor_out;
    wire shift_en;
    wire load_en;
    wire reset_en;
    wire rotate_dir;

    // Counter module
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 0;
        end else begin
            counter <= counter + 1;
        end
    end

    // Shift register module
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            shift_reg <= 8'h55;
        end else if (load_en) begin
            shift_reg <= data;
        end else if (shift_en) begin
            if (rotate_dir) begin
                shift_reg <= {shift_reg[0], shift_reg[7:1]};
            end else begin
                shift_reg <= {shift_reg[6:0], 1'b0};
            end
        end
    end

    // XOR module
    assign xor_out = shift_reg[counter] ^ counter;

    // Control module
    assign shift_en = (counter != 0);
    assign load_en = data;
    assign reset_en = reset;
    assign rotate_dir = counter[0];

    // Enable module
    always @(posedge clk or posedge reset) begin
        if (reset_en) begin
            shift_reg <= 8'h55;
        end else if (load_en) begin
            shift_reg <= data;
        end else if (shift_en) begin
            if (rotate_dir) begin
                shift_reg <= {shift_reg[0], shift_reg[7:1]};
            end else begin
                shift_reg <= {shift_reg[6:0], 1'b0};
            end
        end
    end

    // Output
    assign q = shift_reg;

endmodule

