module pid (
  input [n-1:0] setpoint,
  input [m-1:0] process_variable,
  output reg [n-1:0] control_output
);
  reg [n-1:0] error;
  reg [n-1:0] integral;
  reg [n-1:0] derivative;

  parameter Kp = 1;
  parameter Ki = 0.1;
  parameter Kd = 0.01;

  always @ (posedge clk) begin
    error <= setpoint - process_variable;
    integral <= integral + error;
    derivative <= error - derivative;
    control_output <= Kp*error + Ki*integral + Kd*derivative;
  end
endmodule
