module multipler (
    input [31:0] A_mul_src1,
    input [31:0] A_mul_src2,
    input clk,
    input reset_n,
    output reg [31:0] A_mul_cell_result
);

reg [15:0] A_mul_cell_result_part_1;
reg [15:0] A_mul_cell_result_part_2;
wire mul_clr = ~reset_n;

altera_mult_add the_altmult_add_part_1 (
    .aclr0 (mul_clr),
    .clock0 (clk),
    .dataa (A_mul_src1[15 : 0]),
    .datab (A_mul_src2[15 : 0]),
    .ena0 (1'b1),
    .result (A_mul_cell_result_part_1)
);

altera_mult_add the_altmult_add_part_2 (
    .aclr0 (mul_clr),
    .clock0 (clk),
    .dataa (A_mul_src1[31 : 16]),
    .datab (A_mul_src2[15 : 0]),
    .ena0 (1'b1),
    .result (A_mul_cell_result_part_2)
);

always @(posedge clk) begin
    if (reset_n == 1'b0) begin
        A_mul_cell_result <= 0;
    end else begin
        A_mul_cell_result <= {A_mul_cell_result_part_1[31 : 16] + A_mul_cell_result_part_2, A_mul_cell_result_part_1[15 : 0]};
    end
end

