module add_sub (
    input [3:0] a,
    input [3:0] b,
    input sub,
    input cin,
    output reg cout,
    output reg overflow,
    output reg [3:0] sum
);

    reg [3:0] temp_sum;
    reg [4:0] temp_carry;

    always @(*) begin
        if (sub) begin
            temp_sum = a - b - cin;
            temp_carry = (a < b) | ((a == b) & cin);
        end else begin
            temp_sum = a + b + cin;
            temp_carry = (temp_sum > 15);
        end
    end

    always @(temp_sum) begin
        if (sub) begin
            overflow = (a[3] & ~b[3] & ~temp_sum[3]) | (~a[3] & b[3] & temp_sum[3]);
        end else begin
            overflow = (a[3] & b[3] & ~temp_sum[3]) | (~a[3] & ~b[3] & temp_sum[3]);
        end
    end

    assign cout = temp_carry[4];
    assign sum = temp_sum;

endmodule

module comparator (
    input [3:0] A,
    input [3:0] B,
    output eq,
    output gt,
    output reg [1:0] priority
);

    assign eq = (A == B);
    assign gt = (A > B);

    always @(*) begin
        if (A[3] > B[3]) begin
            priority = 2'b11;
        end else if (A[2] > B[2]) begin
            priority = 2'b10;
        end else if (A[1] > B[1]) begin
            priority = 2'b01;
        end else begin
            priority = 2'b00;
        end
    end

endmodule

module functional_module (
    input [3:0] add_sub_sum,
    input [1:0] comparator_priority,
    output reg [7:0] result
);

    always @(*) begin
        case (comparator_priority)
            2'b00: result = {4'b0000, add_sub_sum};
            2'b01: result = {3'b000, add_sub_sum[3:0], 1'b1, 4'b0000};
            2'b10: result = {2'b00, add_sub_sum[2:0], 2'b11, 4'b000};
            2'b11: result = {1'b0, add_sub_sum[1:0], 3'b111, 4'b00};
        endcase
    end

endmodule

