module exponent_adder (
    input wire clk,
    input wire rst,
    input wire load_a,
    input wire load_b,
    input wire [11:0] Exp_X,
    input wire [11:0] Exp_Y,
    output wire [12:0] Exp_Add,
    output wire underflow_f
);

    // Declare wires and registers
    wire [12:0] Exp_Add_Verif;
    wire [12:0] U_Limit;
    wire underflow_exp_reg;
    wire carry_out;

    // Add the two exponents and store the result in Exp_Add_Verif
    add_sub_carry_out #(.W(12)) EXP_Add_Reg (
        .op_mode(1'b0),
        .Data_A(Exp_X),
        .Data_B(Exp_Y),
        .Data_S(Exp_Add_Verif),
        .carry_out(carry_out)
    );

    // Register Exp_Add_Verif using a 13-bit register called ExpAdd_Register
    RegisterMult #(.W(13)) ExpAdd_Register (
        .clk(clk),
        .rst(rst),
        .load(load_a),
        .D(Exp_Add_Verif),
        .Q(Exp_Add)
    );

    // Check if the sum of the exponents exceeds the limit
    generate
        if (12 == 8) begin
            assign U_Limit = 13'd127;
        end else begin
            assign U_Limit = 13'd1023;
        end
    endgenerate

    // Set the underflow flag if the sum exceeds the limit
    Comparator_Less #(.W(13)) Exp_unflow_Comparator (
        .Data_A(Exp_Add),
        .Data_B(U_Limit),
        .less(underflow_exp_reg)
    );

    // Register the underflow flag using a 1-bit register called ExpUnderflow_Register
    RegisterMult #(.W(1)) ExpUnderflow_Register (
        .clk(clk),
        .rst(rst),
