module combinational_circuit(
    input wire [7:0] A,
    input wire [7:0] B,
    output wire [7:0] out_nand,
    output wire [7:0] out_or,
    output wire [3:0] out_prod,
    output wire [3:0] out_quot);

    assign out_nand = ~(A & B);
    assign out_or = A | B;

    // Product
    wire [15:0] product = A * B;
    assign out_prod = product[7:4];

    // Quotient
    wire [15:0] quotient;
    assign quotient = (B == 0) ? 0 : A / B;
    assign out_quot = quotient[7:4];

endmodule

module FPComparator(
    input [31:0] operand1,
    input [31:0] operand2,
    output reg result
);

    // Internal registers for operand1
    reg sign1;
    reg [7:0] exp1;
    reg [22:0] frac1;

    // Internal registers for operand2
    reg sign2;
    reg [7:0] exp2;
    reg [22:0] frac2;

    // Decompose operand1
    assign sign1 = operand1[31];
    assign exp1 = operand1[30:23];
    assign frac1 = operand1[22:0];

    // Decompose operand2
    assign sign2 = operand2[31];
    assign exp2 = operand2[30:23];
    assign frac2 = operand2[22:0];

    // Determine if operand1 is NaN
    wire isNan1 = (exp1 == 255) && (frac1 != 0);

    // Determine if operand2 is NaN
    wire isNan2 = (exp2 == 255) && (frac2 != 0);

    // Determine if operand1 is infinity
    wire isInf1 = (exp1 == 255) && (frac1 == 0);

    // Determine if operand2 is infinity
    wire isInf2 = (exp2 == 255) && (frac2 == 0);

    // Determine if operand1 is negative zero
    wire isNegZero1 = (exp1 == 0) && (frac1 == 0) && (sign1 == 1);

    // Determine if operand2 is negative zero
    wire isNegZero2 = (exp2 == 0) && (frac2 == 0) && (sign2 == 1);

    // Determine if operand1 is positive zero
    wire isPosZero1 = (exp1 == 0) && (frac1 == 0) && (sign1 == 0);

    // Determine if operand2 is positive zero
    wire isPosZero2 = (exp2 == 0) && (frac2 == 0) && (sign2 == 0);

    // Determine if operand1 is negative
    wire isNeg1 = (sign1 == 1);

    // Determine if operand2 is negative
    wire isNeg2 = (sign2 == 1);

    // Determine if operand1 is greater than operand2
    always @* begin
        if (isNan1 || isNan2) begin
            result = 0;
        end else if (isInf1 && isInf2) begin
            result = 0;
        end else if (isInf1 && !isNeg1) begin
            result = 1;
        end else if (isInf2 && isNeg2) begin
            result = 1;
        end else if (isInf1) begin
            result = 0;
        end else if (isInf2) begin
            result = 1;
        end else if (isNegZero1 && isPosZero2) begin
            result = 0;
        end else if (isPosZero1 && isNegZero2) begin
            result = 1;
        end else if (isNeg1 && !isNeg2) begin
            result = 0;
        end else if (!isNeg1 && isNeg2) begin
            result = 1;
        end else if (exp1 > exp2) begin
            result = !isNeg1;
        end else if (exp2 > exp1) begin
            result = isNeg1;
        end else if (frac1 > frac2) begin
            result = !isNeg1;
        end else if (frac2 > frac1) begin
            result = isNeg1;
        end else begin
            result = 0;
        end
    end

endmodule

