module barrel_shifter (
    input [15:0] A,
    input [15:0] B,
    input [3:0] S,
    output reg [15:0] Y
);
    always @(*) begin
        case(S)
            4'b0000: Y = A;
            4'b0001: Y = A << 1;
            4'b0010: Y = A << 2;
            4'b0011: Y = A << 3;
            4'b0100: Y = A << 4;
            4'b0101: Y = A << 5;
            4'b0110: Y = A << 6;
            4'b0111: Y = A << 7;
            4'b1000: Y = A << 8;
            4'b1001: Y = A << 9;
            4'b1010: Y = A << 10;
            4'b1011: Y = A << 11;
            4'b1100: Y = A << 12;
            4'b1101: Y = A << 13;
            4'b1110: Y = A << 14;
            4'b1111: Y = A << 15;
        endcase
        Y = Y | (B >> (16 - S));
    end
endmodule

module bcd_code (
    input [3:0] A,
    output reg [3:0] OUT1,
    output reg [3:0] OUT2
);
    always @(*) begin
        case(A)
            4'b0000: begin OUT1 = 4'b0000; OUT2 = 4'b0000; end
            4'b0001: begin OUT1 = 4'b0000; OUT2 = 4'b0001; end
            4'b0010: begin OUT1 = 4'b0000; OUT2 = 4'b0010; end
            4'b0011: begin OUT1 = 4'b0000; OUT2 = 4'b0011; end
            4'b0100: begin OUT1 = 4'b0000; OUT2 = 4'b0100; end
            4'b0101: begin OUT1 = 4'b0000; OUT2 = 4'b0101; end
            4'b0110: begin OUT1 = 4'b0000; OUT2 = 4'b0110; end
            4'b0111: begin OUT1 = 4'b0000; OUT2 = 4'b0111; end
            4'b1000: begin OUT1 = 4'b0001; OUT2 = 4'b0000; end
            4'b1001: begin OUT1 = 4'b0001; OUT2 = 4'b0001; end
            4'b1010: begin OUT1 = 4'b0001; OUT2 = 4'b0010; end
            4'b1011: begin OUT1 = 4'b0001; OUT2 = 4'b0011; end
            4'b1100: begin OUT1 = 4'b0001; OUT2 = 4'b0100; end
            4'b1101: begin OUT1 = 4'b0001; OUT2 = 4'b0101; end
            4'b1110: begin OUT1 = 4'b0001; OUT2 = 4'b0110; end
            4'b1111: begin OUT1 = 4'b0001; OUT2 = 4'b0111; end
        endcase
    end
endmodule

