module calculator (
	input clk,
	input reset,
	input [1:0] op,
	input [7:0] in1,
	input [7:0] in2,
	output reg [7:0] out,
	output reg valid,
	output reg ready
);

reg [7:0] result;
reg division_by_zero;

always @ (posedge clk) begin
	if (reset) begin
		result <= 0;
		valid <= 0;
		ready <= 1;
		division_by_zero <= 0;
	end else if (ready) begin
		case (op)
			2'b00: result <= in1 + in2;
			2'b01: result <= in1 - in2;
			2'b10: result <= in1 * in2;
			2'b11: begin
				if (in2 == 0) begin
					result <= 0;
					division_by_zero <= 1;
				end else begin
					result <= in1 / in2;
					division_by_zero <= 0;
				end
			end
		endcase
		valid <= 1;
		ready <= 0;
	end else begin
		valid <= 0;
		ready <= 1;
	end
end

assign out = result;
assign valid = (op == 2'b00 || op == 2'b01 || op == 2'b10 || (op == 2'b11 && !division_by_zero));
assign ready = !valid;

endmodule

module mojo_top(
    // 50MHz clock input
    input clk,
    // Input from reset button (active low)
    input rst_n,
    // cclk input from AVR, high when AVR is ready
    input cclk,
    // Outputs to the 8 onboard LEDs
    output[7:0]led,
    // AVR SPI connections
    output spi_miso,
    input spi_ss,
    input spi_mosi,
    input spi_sck,
    // AVR ADC channel select
    output [3:0] spi_channel,
    // Serial connections
    input avr_tx, // AVR Tx => FPGA Rx
    output avr_rx, // AVR Rx => FPGA Tx
    input avr_rx_busy // AVR Rx buffer full
    );

wire rst = ~rst_n; // make reset active high
wire [9:0] array; // this is a declaration of the 8-bit wire (I/O line)
// these signals should be high-z when not used
//append _n to wires that are active-low

//The following three lines are constant declarations
//x'yz 
//x - represents the number of bits to use
//y  - represents how to interpret the written number
//		possible values: b(inary), he(x)
//z - represents the value
//Binary :  1,0, Z,X
//				Z - High Impedence - disconnected
//				X - Don't Care - could be anything
assign spi_miso = 1'bz;   //The spi ports are disconnected to prevent board damage from driving them
assign avr_rx = 1'bz;
assign spi_channel = 4'bzzzz;

reg [2:0] adc_channel = 3'b000; //initialize adc_channel to 0

always @(posedge cclk) begin
    if (spi_ss == 1'b0) begin
        spi_miso <= array[7];
        array <= {spi_mosi, array[7:1]};
        spi_channel <= {adc_channel, 2'b00};
    end
end

always @(posedge clk) begin
    if (rst) begin
        led[7:0] <= 8'b00000000;
        adc_channel <= 3'b000;
    end else begin
        led[7] <= rst;
        if (avr_rx_busy == 1'b0) begin
            adc_channel <= avr_rx[3:1];
        end
        case (adc_channel)
            3'b000: led[0] <= array[0];
            3'b001: led[1] <= array[0];
            3'b010: led[2] <= array[0];
            3'b011: led[3] <= array[0];
            3'b100: led[4] <= array[0];
            3'b101: led[5] <= array[0];
            3'b110: led[6] <= array[0];
            3'b111: led[7] <= array[0];
        endcase
    end
end

endmodule

module comparator(A, B, EQ, GT, LT);
input [3:0] A;
input [3:0] B;
output EQ;
output GT;
