module TDC (
  input clk,
  input rst,
  input in,
  output reg [n-1:0] out
);

parameter n = 8; // number of bits in the binary counter

reg [n-1:0] counter;
reg [n-1:0] prev_counter;
reg [1:0] state;

always @(posedge clk) begin
  if (rst) begin
    counter <= 0;
    state <= 2'b00;
  end else begin
    case (state)
      2'b00: begin
        prev_counter <= counter;
        counter <= 0;
        state <= 2'b01;
      end
      2'b01: begin
        counter <= counter + 1;
        if (in) begin
          state <= 2'b10;
        end
      end
      2'b10: begin
        out <= counter;
        counter <= prev_counter;
        state <= 2'b00;
      end
    endcase
  end
end

endmodule

module fsm_16bit_pattern_detection (
  input clk,
  input reset,
  input [15:0] data,
  output reg match
);

  parameter S0 = 2'b00; // Initial state
  parameter S1 = 2'b01; // State for detecting first "1"
  parameter S2 = 2'b10; // State for detecting "0"
  parameter S3 = 2'b11; // State for detecting second "1"

  reg [1:0] state;
  reg [1:0] next_state;

  always @ (posedge clk or posedge reset) begin
    if (reset) begin
      state <= S0;
      match <= 1'b0;
    end else begin
      state <= next_state;
      match <= (state == S3); // Output match signal when in S3 state
    end
  end

  always @ (*) begin
    case (state)
      S0: begin
        if (data[15:0] == 4'b1010)
          next_state = S3;
        else if (data[0] == 1'b1)
          next_state = S1;
        else
          next_state = S0;
      end
      S1: begin
        if (data[0] == 1'b0)
          next_state = S2;
        else if (data[15:1] == 14'b0)
          next_state = S0;
        else
          next_state = S1;
      end
      S2: begin
        if (data[0] == 1'b1)
          next_state = S1;
        else if (data[15:2] == 13'b0)
          next_state = S0;
        else
          next_state = S2;
      end
      S3: begin
        next_state = S0;
      end
    endcase
  end

endmodule

module vending_machine (
  input clk,
  input reset,
  input [3:0] selection,
  input [7:0] payment,
  output reg [3:0] dispensing,
  output reg [7:0] change
);

  // Define the three states
  parameter IDLE = 2'b00;
  parameter SELECTION = 2'b01;
  parameter DISPENSING = 2'b10;

  // Define the state register and initialize it to IDLE
  reg [1:0] state = IDLE;

  // Define the item price and initialize it to 50 cents
  reg [7:0] item_price = 8'd50;

  // Define the amount of money inserted by the user
  reg [7:0] inserted_money = 8'd0;

  always @(posedge clk) begin
    if (reset) begin
      // Reset the state and inserted_money registers
      state <= IDLE;
      inserted_money <= 8'd0;
    end else begin
      case (state)
        IDLE: begin
          // Wait for the user to make a selection
          if (selection != 4'b0000) begin
            // Transition to the SELECTION state and set the item price
            state <= SELECTION;
            item_price <= (selection == 4'b0001) ? 8'd50 : 8'd75;
          end
        end
        SELECTION: begin
          // Wait for the user to insert enough money
          if (inserted_money >= item_price) begin
            // Dispense the item and return change
            dispensing <= selection;
            change <= inserted_money - item_price;
            // Transition to the DISPENSING state
            state <= DISPENSING;
          end else if (payment != 8'd0) begin
            // Add the inserted money to the register
            inserted_money <= inserted_money + payment;
          end
        end
        DISPENSING: begin
          // Wait for the item to finish dispensing
          if (dispensing == 4'b0000) begin
            // Transition back to the IDLE state
            state <= IDLE;
            // Reset the item price and inserted_money registers
            item_price <= 8'd50;
            inserted_money <= 8'd0;
          end
        end
      endcase
    end
  end

endmodule

module add_sub #(parameter DW = 1 // data width
		)
   (
    input [DW-1:0]  a, //first operand
    input [DW-1:0]  b, //second operand
    input 	    opt_sub, //subtraction option
    input 	    cin, //carry in
    output [DW-1:0] sum, //sum output
    output 	    cout, //carry output
    output 	    zero, //zero flag
    output 	    neg, //negative flag
    output 	    overflow //overflow flag
    );

   wire [DW-1:0]   b_sub;

   assign b_sub[DW-1:0] =  {(DW){opt_sub}} ^ b[DW-1:0];

   assign {cout,sum[DW-1:0]}  = a[DW-1:0]     + 
                                b_sub[DW-1:0] + 
                                opt_sub       +
                                cin;

   assign zero = (sum == 0);
   assign neg = (sum[DW-1] == 1);
   assign overflow = (a[DW-1] == b[DW-1] && sum[DW-1] != a[DW-1]);

endmodule

