    output reg [WDTH-1:0] out_data,
    output reg out_nd
  );

  wire rst_n;
  assign rst_n = ~reset;
  reg read_delete;
  wire read_full;
  wire [WDTH-1:0] read_data;
  wire write_error;
  wire read_error;

