    reg [31:0] cnt;
    always @(posedge clk_cog) begin
        if (nres == 1'b1) begin
            cnt <= cnt + 1'b1;
        end
    end

    // Bus enable
    reg ena_bus;
    always @(posedge clk_cog, negedge nres) begin
        if (nres == 1'b0) begin
            ena_bus <= 1'b0;
        end else begin
            ena_bus <= ~ena_bus;
        end
    end

    // Bus select
    reg [7:0] bus_sel;
    always @(posedge clk_cog, negedge nres) begin
        if (nres == 1'b0) begin
            bus_sel <= 8'b0;
        end else if (ena_bus == 1'b1) begin
            bus_sel <= {bus_sel[6:0], ~|bus_sel[6:0]};
        end
    end

    // Cogs
    wire [7:0] bus_r;
    wire [7:0] bus_e;
    wire [7:0] bus_w;
    wire [1:0] bus_s [7:0];
    wire [15:0] bus_a [7:0];
    wire [31:0] bus_d [7:0];
