    wire [31:0] outx [7:0];
    wire [31:0] dirx [7:0];
    wire hub_bus_r = |bus_r;
    wire hub_bus_e = |bus_e;
    wire hub_bus_w = |bus_w;
    wire [1:0] hub_bus_s = bus_s[7] | bus_s[6] | bus_s[5] | bus_s[4] | bus_s[3] | bus_s[2] | bus_s[1] | bus_s[0];
    wire [15:0] hub_bus_a = bus_a[7] | bus_a[6] | bus_a[5] | bus_a[4] | bus_a[3] | bus_a[2] | bus_a[1] | bus_a[0];
    wire [31:0] bus_q;
    wire bus_c;
    wire [7:0] bus_ack;
    wire [7:0] cog_ena;
    wire [7:0] ptr_w;
    wire [27:0] ptr_d;

    genvar i;
    generate
        for (i=0; i<8; i=i+1) begin : coggen
            cog cog_(
                .nres(nres),
                .clk_cog(clk_cog),
                .clk_pll(clk_pll),
                .ena_bus(ena_bus),
                .ptr_w(ptr_w[i]),
                .ptr_d(ptr_d),
                .ena(cog_ena[i]),
                .bus_sel(bus_sel[i]),
                .bus_r(bus_r[i]),
                .bus_e(bus_e[i]),
                .bus_w(bus_w[i]),
                .bus_s(bus_s[i]),
                .bus_a(bus_a[i]),
                .bus_d(bus_d[i]),
                .bus_q(bus_q),
                .bus_c(bus_c),
                .bus_ack(bus_ack[i]),
                .cnt(cnt),
                .pll_in(pll),
                .pll_out(pll[i]),
                .pin_in(pin_in),
                .pin_out(outx[i]),
                .pin_dir(dirx[i])
            );
        end
    endgenerate

    // Hub
    hub hub_(
        .clk_cog(clk_cog),
        .ena_bus(ena_bus),
        .nres(nres),
        .bus_sel(bus_sel),
        .bus_r(hub_bus_r),
        .bus_e(hub_bus_e),
        .bus_w(hub_bus_w),
        .bus_s(hub_bus_s),
        .bus_a(hub_bus_a),
        .bus_d(bus_d),
        .bus_q(bus_q),
        .bus_c(bus_c),
        .bus_ack(bus_ack),
        .cog_ena(cog_ena),
        .ptr_w(ptr_w),
        .ptr_d(ptr_d),
        .cfg(cfg)
    );

    // Pins
    assign pin_out = outx[7] | outx[6] | outx[5] | outx[4] | outx[3] | outx[2] | outx[1] | outx[0];
    assign pin_dir = dirx[7] | dirx[6] | dirx[5] | dirx[4] | dirx[3] | dirx[2] | dirx[1] | dirx[0];
    assign cog_led = cog_ena;

endmodule

