    assign sram_tcm_chipselect_n_out = (next_grant == 1'b0) ? tcs0_tcm_chipselect_n_out : 1'hx;

    // TCS signals
    assign tcs0_grant = (next_grant == 1'b1) ? ack : 1'b0;
    assign tcs0_tcm_data_in = (next_grant == 1'b1) ? sram_tcm_data_in : 16'hx;

