  reg [3:0] shift_reg;

  always @(posedge clk) begin
    if (reset) begin
      state <= S0;
      shift_reg <= 4'b0;
      match <= 1'b0;
    end
    else begin
      case (state)
        S0: begin
          if (data[0] == 1'b0)
            state <= S0;
          else
            state <= S1;
        end
        S1: begin
          shift_reg <= {shift_reg[2:0], data[0]};
          if (shift_reg == 4'b1010)
            state <= S2;
          else
            state <= S1;
        end
        S2: begin
          if (data[0] == 1'b0)
            state <= S3;
          else
            state <= S2;
        end
        S3: begin
          shift_reg <= 4'b0;
          match <= 1'b1;
          state <= S0;
        end
      endcase
    end
  end

endmodule

module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    input CLK,
    input RST,
    output reg [3:0] C
);

    wire [3:0] sum;
    wire [3:0] carry;

    // Full adder implementation
    // The full adder module is instantiated 4 times to create a 4-bit ripple carry adder
    // The carry output of one full adder is connected to the carry input of the next full adder
    // The A and B inputs are connected to the corresponding inputs of the first full adder
    // The sum output of each full adder is connected to the corresponding bit of the sum wire
    // The carry output of the last full adder is the carry output of the entire adder
    sky130_fd_sc_ls__sdfstp_1 fa0 (
        .Q(sum[0]),
        .CLK(CLK),
        .D(A[0] ^ B[0]),
        .SCD(1'b0),
        .SCE(1'b0),
        .SET_B(1'b0),
        .VPWR(1'b0),
        .VGND(1'b0),
        .VPB(1'b0),
        .VNB(1'b0)
    );
    sky130_fd_sc_ls__sdfstp_1 fa1 (
        .Q(sum[1]),
        .CLK(CLK),
        .D(A[1] ^ B[1] ^ carry[0]),
        .SCD(1'b0),
        .SCE(1'b0),
        .SET_B(1'b0),
        .VPWR(1'b0),
        .VGND(1'b0),
        .VPB(1'b0),
        .VNB(1'b0)
    );
    sky130_fd_sc_ls__sdfstp_1 fa2 (
        .Q(sum[2]),
        .CLK(CLK),
        .D(A[2] ^ B[2] ^ carry[1]),
        .SCD(1'b0),
        .SCE(1'b0),
        .SET_B(1'b0),
        .VPWR(1'b0),
        .VGND(1'b0),
        .VPB(1'b0),
        .VNB(1'b0)
    );
    sky130_fd_sc_ls__sdfstp_1 fa3 (
        .Q(sum[3]),
        .CLK(CLK),
        .D(A[3] ^ B[3] ^ carry[2]),
        .SCD(1'b0),
        .SCE(1'b0),
        .SET_B(1'b0),
        .VPWR(1'b0),
        .VGND(1'b0),
        .VPB(1'b0),
        .VNB(1'b0)
    );
    assign carry = {sum[0], sum[1], sum[2], sum[3]} & {A[0], A[1], A[2], A[3], B[0], B[1], B[2], B[3], carry[0], carry[1], carry[2]};

    // Output is updated on the rising edge of the clock signal
    always @(posedge CLK) begin
        if (RST) begin
            C <= 0;
        end else begin
            C <= sum;
        end
    end

endmodule

