module restoring_divider (
    input clk,
    input [7:0] dividend,
    input [7:0] divisor,
    input control,
    output reg [7:0] quotient
);

reg [7:0] remainder;
reg [7:0] divisor_even = 2;
reg [7:0] divisor_odd = 3;
reg [2:0] state = 0;

always @(posedge clk) begin
    case (state)
        0: begin // Load dividend and initialize remainder
            remainder <= dividend;
            quotient <= 0;
            state <= 1;
        end
        1: begin // Check if divisor is zero
            if (divisor == 0) begin
                quotient <= 255; // Set quotient to max value if divisor is zero
                state <= 0;
            end else begin
                state <= 2;
            end
        end
        2: begin // Check if remainder is less than divisor
            if (remainder < divisor) begin
                state <= 4;
            end else begin
                state <= 3;
            end
        end
        3: begin // Subtract divisor from remainder and increment quotient
            remainder <= remainder - divisor;
            quotient <= quotient + 1;
            state <= 2;
        end
        4: begin // Check if control input is high and select divisor accordingly
            if (control == 1) begin
                divisor <= divisor_odd;
            end else begin
                divisor <= divisor_even;
            end
            state <= 5;
        end
        5: begin // Check if quotient is equal to 255
            if (quotient == 255) begin
                state <= 0;
            end else begin
                state <= 2;
            end
        end
    endcase
end

endmodule

