module dma_controller (
    input clk, rst_n,
    input module_select,
    input write_strobe,
    input [1:0] regsel,
    input [7:0] din,
    output [7:0] dout,
    output reg [20:0] dma_addr,
    output reg [7:0] dma_wd,
    input [7:0] dma_rd,
    output reg dma_rnw,
    output reg dma_req,
    input dma_ack,
    input dma_done
);

    reg [2:0] zxrdtgl, zxwrtgl;
    reg zxoldrd, zxoldwr, zxclr;
    wire zxrd, zxwr;
    reg dma_on;

    localparam _HAD = 2'b00;
    localparam _MAD = 2'b01;
    localparam _LAD = 2'b10;
    localparam _CST = 2'b11;

    always @* begin
        case (regsel)
            _HAD: dma_addr[20:16] = din[4:0];
            _MAD: dma_addr[15:8] = din;
            _LAD: dma_addr[7:0] = din;
            _CST: dma_on = din[7];
        endcase
        case (regsel)
            _HAD: dout = {3'b000, dma_addr[20:16]};
            _MAD: dout = dma_addr[15:8];
            _LAD: dout = dma_addr[7:0];
            _CST: dout = {dma_on, 7'bX};
        endcase
    end

    always @(posedge clk, negedge rst_n) begin
        if (!rst_n) begin
            dma_on <= 1'b0;
            dma_addr <= 0;
            dma_wd <= 0;
            dma_rnw <= 1'b0;
        end else begin
            if (module_select && write_strobe) begin
                case (regsel)
                    _HAD: dma_addr[20:16] <= din[4:0];
                    _MAD: dma_addr[15:8] <= din;
                    _LAD: dma_addr[7:0] <= din;
                    _CST: dma_on <= din[7];
                endcase
            end
            if (dma_ack && dma_on) begin
                dma_rnw <= 1'b1;
                dma_addr <= dma_addr + 1;
            end else if (module_select && write_strobe && (regsel == _HAD || regsel == _MAD || regsel == _LAD)) begin
                dma_wd <= din;
            end else if (dma_done) begin
                dma_rnw <= 1'b0;
                dma_addr <= dma_addr + 1;
            end
        end
    end

    always @(posedge clk, negedge rst_n) begin
        if (!rst_n) begin
            zxoldrd <= 1'b0;
            zxoldwr <= 1'b0;
        end else begin
            if (dma_on) begin
                if (zxrdtgl[2] != zxrdtgl[1])
                    zxoldrd <= 1'b1;
                else if (zxclr)
                    zxoldrd <= 1'b0;
                if (zxwrtgl[2] != zxwrtgl[1])
                    zxoldwr <= 1'b1;
                else if (zxclr)
                    zxoldwr <= 1'b0;
            end else begin
                zxoldrd <= 1'b0;
                zxoldwr <= 1'b0;
            end
        end
    end

    always @(posedge clk) begin
        zxrdtgl[2:0] <= {zxrdtgl[1:0], dma_zxread_toggle};
        zxwrtgl[2:0] <= {zxwrtgl[1:0], dma_zxwrite_toggle};
    end

    assign zxrd = (zxrdtgl[2] != zxrdtgl[1]) | zxoldrd;
    assign zxwr = (zxwrtgl[2] != zxwrtgl[1]) | zxoldwr;

endmodule

module LED_UART_CTRL (
    input CLK,
    input RESET,
    input UART_RX,
    input LED_EN,
    input [7:0] UART_DATA,
    output reg [1:0] LED_DATA
);

reg [7:0] uart_reg;
reg rx_started;
reg [2:0] led_data_next;
reg [1:0] led_data_reg;
reg led_en_reg;

always @(posedge CLK) begin
    if (RESET) begin
        uart_reg <= 8'h00;
        rx_started <= 0;
        led_data_next <= 3'b00;
        led_data_reg <= 2'b00;
        led_en_reg <= 0;
    end else begin
        if (!rx_started && !UART_RX) begin
            rx_started <= 1;
            uart_reg <= 8'h00;
        end else if (rx_started) begin
            uart_reg <= {uart_reg[6:0], UART_RX};
            if (uart_reg == 8'h55) begin
                led_en_reg <= 1;
                rx_started <= 0;
                case (uart_reg[2:0])
                    3'b000: led_data_next <= 2'b00;
                    3'b001: led_data_next <= 2'b01;
                    3'b010: led_data_next <= 2'b10;
                    3'b011: led_data_next <= 2'b11;
                    default: led_data_next <= 2'b00;
                endcase
            end
        end
        if (led_en_reg) begin
            led_data_reg <= led_data_next;
            led_en_reg <= 0;
        end
    end
end

assign LED_DATA = led_data_reg;

