module adder_subtractor (A, B, sub, Y);
  input [3:0] A, B;
  input sub;
  output [3:0] Y;
  wire [2:0] S;
  wire [3:0] C;
  wire d, g, p;
  wire [3:0] B_inv;
  wire [3:0] B_neg;

  // invert B
  xor(B_inv[0], B[0], 1'b1);
  xor(B_inv[1], B[1], 1'b1);
  xor(B_inv[2], B[2], 1'b1);
  xor(B_inv[3], B[3], 1'b1);

  // calculate 2's complement of B
  assign S[0] = 1;
  assign S[1] = sub;
  assign S[2] = 0;
  assign {C[0], d, g, p} = alu_cell(A[0], B_inv[0], 1'b1, A[0], B_inv[0], 1'b0, S);
  assign {C[1], d, g, p} = alu_cell(A[1], B_inv[1], C[0], A[1], B_inv[1], g, S);
  assign {C[2], d, g, p} = alu_cell(A[2], B_inv[2], C[1], A[2], B_inv[2], g, S);
  assign {C[3], d, g, p} = alu_cell(A[3], B_inv[3], C[2], A[3], B_inv[3], g, S);
  assign B_neg = {C[3], C[2], C[1], C[0]};

  // calculate sum or difference based on sub
  assign S[0] = sub;
  assign S[1] = 0;
  assign S[2] = 0;
  assign {C[0], d, g, p} = alu_cell(A[0], B[0], 1'b0, A[0], B[0], 1'b0, S);
  assign {C[1], d, g, p} = alu_cell(A[1], B[1], C[0], A[1], B[1], g, S);
  assign {C[2], d, g, p} = alu_cell(A[2], B[2], C[1], A[2], B[2], g, S);
  assign {C[3], d, g, p} = alu_cell(A[3], B[3], C[2], A[3], B[3], g, S);
  assign Y = (sub == 1) ? B_neg : C;

endmodule

module alu_cell (d, g, p, a, b, c, S);
  output d, g, p;
  input a, b, c;
  input [2:0] S;
  reg g,p,d,cint,bint;

  always @(a,b,c,S,p,g) begin 
    bint = S[0] ^ b;
    g = a & bint;
    p = a ^ bint;
    cint = S[1] & c;

  if(S[2]==0)
    begin
      d = p ^ cint;
    end

  else if(S[2]==1)
    begin
      if((S[1]==0) & (S[0]==0)) begin
        d = a | b;
      end
      else if ((S[1]==0) & (S[0]==1)) begin
        d = ~(a|b);
      end
      else if ((S[1]==1) & (S[0]==0)) begin
        d = a&b;
      end
      else
        d = 1;
      end
    end
endmodule

module add_sub_module(
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] sum
);

    wire [31:0] inverted_b;
    wire [31:0] carry;
    wire [31:0] carry_out;

    assign inverted_b = (sub == 1'b1) ? ~b : b;

    generate
        genvar i;
        for (i = 0; i < 32; i = i + 1) begin : carry_lookahead
            assign carry[i] = (a[i] & inverted_b[i]);
        end
    endgenerate

    ripple_carry_adder adder(
        .a(a),
        .b(inverted_b),
        .carry_in(sub),
        .sum(sum),
        .carry_out(carry_out)
    );

    assign sum = (sub == 1'b1) ? (~sum + 1) : sum;

endmodule

module ripple_carry_adder(
    input [31:0] a,
    input [31:0] b,
    input carry_in,
    output [31:0] sum,
    output carry_out
);

    wire [31:0] carry;
    wire [31:0] sum_temp;

    assign sum_temp = a + b + carry_in;
    assign carry = {sum_temp[30:0], sum_temp[31]} ^ {a[30:0], b[30:0], carry_in};

    assign sum = sum_temp;

    assign carry_out = carry[31];

endmodule

module VGACtrl(
    input clk,
    input reset,
    output reg vga_h_sync,
    output reg vga_v_sync,
    output reg inDisplayArea,
    output reg [9:0] CounterX,
    output reg [9:0] CounterY
);

    // Constants for VGA timing
    parameter H_SYNC_PERIOD = 96;
    parameter H_SYNC_PULSE_WIDTH = 16;
    parameter V_SYNC_PERIOD = 8000;
    parameter V_SYNC_PULSE_WIDTH = 2;
    parameter DISPLAY_WIDTH = 640;
    parameter DISPLAY_HEIGHT = 480;

    // Internal signals
    reg [9:0] h_counter;
    reg [9:0] v_counter;

    always @(posedge clk, posedge reset) begin
        if (reset) begin
            // Reset counters and signals
            h_counter <= 0;
            v_counter <= 0;
            vga_h_sync <= 0;
            vga_v_sync <= 0;
            inDisplayArea <= 0;
            CounterX <= 0;
            CounterY <= 0;
        end else begin
            // Update horizontal counter
            if (h_counter == DISPLAY_WIDTH - 1) begin
                h_counter <= 0;
                CounterX <= h_counter;
            end else begin
                h_counter <= h_counter + 1;
                CounterX <= h_counter;
            end

            // Update vertical counter
            if (v_counter == DISPLAY_HEIGHT - 1) begin
                v_counter <= 0;
                CounterY <= v_counter;
            end else begin
                v_counter <= v_counter + 1;
                CounterY <= v_counter;
            end

            // Update sync signals
            if (h_counter >= DISPLAY_WIDTH - H_SYNC_PULSE_WIDTH) begin
                vga_h_sync <= 1;
            end else begin
                vga_h_sync <= 0;
            end

            if (v_counter >= DISPLAY_HEIGHT - V_SYNC_PULSE_WIDTH) begin
                vga_v_sync <= 1;
            end else begin
                vga_v_sync <= 0;
            end

            // Update display area signal
            if (h_counter < DISPLAY_WIDTH && v_counter < DISPLAY_HEIGHT) begin
                inDisplayArea <= 1;
            end else begin
                inDisplayArea <= 0;
            end
        end
    end

endmodule

module BinaryCounter(clk, rst, count);
