      time <= 0;
    end else begin
      time <= time + 1;
    end
  end

endmodule

module priority_encoder_decoder (
    input [3:0] in,
    output w,
    output x,
    output y,
    output z
);

// Priority Encoder
wire [1:0] priority;
assign priority = ({in[3], in[2], in[1], in[0]} != 4'b0000) ? $priority(in) : 2'b00;

// Decoder
assign w = (priority == 2'b00) ? 1'b1 : 1'b0;
assign x = (priority == 2'b01) ? 1'b1 : 1'b0;
assign y = (priority == 2'b10) ? 1'b1 : 1'b0;
assign z = (priority == 2'b11) ? 1'b1 : 1'b0;

endmodule

module dma_request_generator (
    input req_aclk,
    input req_aresetn,

    output [C_ID_WIDTH-1:0] request_id,
    input [C_ID_WIDTH-1:0] response_id,

    input req_valid,
    output reg req_ready,
    input [C_BURSTS_PER_TRANSFER_WIDTH-1:0] req_burst_count,

    input enable,
    input pause,

    output eot
);

parameter C_ID_WIDTH = 3;
parameter C_BURSTS_PER_TRANSFER_WIDTH = 17;

reg [C_BURSTS_PER_TRANSFER_WIDTH-1:0] burst_count = 'h00;
reg [C_ID_WIDTH-1:0] id;
wire [C_ID_WIDTH-1:0] id_next = inc_id(id);

assign eot = burst_count == 'h00;
assign request_id = id;

always @(posedge req_aclk)
begin
    if (req_aresetn == 1'b0) begin
        burst_count <= 'h00;
        id <= 'h0;
        req_ready <= 1'b1;
    end else if (enable == 1'b0) begin
        req_ready <= 1'b1;
    end else begin
        if (req_ready) begin
            if (req_valid && enable) begin
                burst_count <= req_burst_count;
                req_ready <= 1'b0;
            end
        end else if (response_id != id_next && ~pause) begin
            if (eot)
                req_ready <= 1'b1;
            burst_count <= burst_count - 1'b1;
            id <= id_next;
        end
    end
end

endmodule

