module binary_to_bcd (
  input [3:0] binary_num,
  output [3:0] bcd_num,
  output error
);

  reg [3:0] bcd_temp;
  reg [1:0] i;

  always @(*) begin
    if (binary_num > 9) begin
      error = 1;
      bcd_temp = 0;
    end else begin
      error = 0;
      bcd_temp = {1'b0, binary_num};
      for (i = 0; i < 4; i = i + 1) begin
        if (bcd_temp > 4) begin
          bcd_temp = bcd_temp + 3;
        end
        bcd_temp = bcd_temp << 1;
      end
    end
  end

  assign bcd_num = bcd_temp[7:4];

endmodule

