    logic not_B;

    not not_A_inst(.a(A), .y(not_A));
    not not_B_inst(.a(B), .y(not_B));
    nand nand_inst(.a(not_A), .b(not_B), .y(nand_out));
    not not_nand_inst(.a(nand_out), .y(Y));

endmodule

module mealy_state_machine (
  input clk,
  input reset,
  input [2:0] in,
  output reg [1:0] out
);

  reg [1:0] state;

  always @(posedge clk) begin
    if (reset) begin
      state <= 2'b00;
      out <= 2'b00;
    end
    else begin
      case (state)
        2'b00: begin
          if (in == 3'b00x) begin
            state <= 2'b00;
            out <= 2'b00;
          end
          else if (in == 3'b01x) begin
            state <= 2'b01;
            out <= 2'b01;
          end
          else if (in == 3'b10x) begin
            state <= 2'b10;
            out <= 2'b10;
          end
          else if (in == 3'b11x) begin
            state <= 2'b11;
            out <= 2'b11;
          end
        end
        2'b01: begin
          if (in == 3'b0x1) begin
            state <= 2'b00;
            out <= 2'b00;
          end
          else if (in == 3'b1x1) begin
            state <= 2'b01;
            out <= 2'b01;
          end
        end
        2'b10: begin
          if (in == 3'b1xx) begin
            state <= 2'b00;
            out <= 2'b00;
          end
          else if (in == 3'b0xx) begin
            state <= 2'b10;
            out <= 2'b10;
          end
        end
        2'b11: begin
          if (in == 3'b1x0) begin
            state <= 2'b00;
            out <= 2'b00;
          end
          else if (in == 3'b0x0) begin
            state <= 2'b11;
            out <= 2'b11;
          end
        end
      endcase
    end
  end

endmodule

module signed_adder (
    input [7:0] a,
    input [7:0] b,
    output [8:0] sum,
    output overflow
);
    reg [8:0] temp_sum;
    reg overflow;

    always @(*) begin
        temp_sum = a + b;
        if (temp_sum > 255 || temp_sum < -256) begin
            overflow = 1;
        end else begin
            overflow = 0;
        end
    end

    assign sum = temp_sum[8] ? {1'b1, temp_sum[7:0] + 1} : temp_sum;
endmodule

