module top_module (
    input [7:0] a,
    input [7:0] b,
    input enable,
    input clk,
    input reset,
    output [15:0] output_sum
);
    wire [8:0] sum;
    wire overflow;
    wire [3:0] gray_count;
    reg [3:0] bcd_count;

    signed_adder adder_inst (
        .a(a),
        .b(b),
        .sum(sum),
        .overflow(overflow)
    );

    always @(posedge clk) begin
        if (reset) begin
            bcd_count <= 4'b0000;
        end else if (enable) begin
            gray_count <= gray_count + 1;
            if (gray_count == 4'b1000) begin
                bcd_count <= bcd_count + 1;
            end
        end
    end

    gray_to_bcd gray_to_bcd_inst (
        .gray(gray_count),
