module fifo_generator(
    input s_aclk,
    input aresetn,
    input axis_prog_full_thresh,
    input axis_prog_empty_thresh,
    input [7:0] s_axis_tdata,
    input [0:7] s_axis_tstrb,
    input [7:0] s_axis_tkeep,
    input s_axis_tlast,
    input [3:0] s_axis_tid,
    input [3:0] s_axis_tdest,
    input [7:0] s_axis_tuser,
    input s_axis_tvalid,
    output s_axis_tready,
    output [7:0] m_axis_tdata,
    output [0:7] m_axis_tstrb,
    output [7:0] m_axis_tkeep,
    output m_axis_tlast,
    output [3:0] m_axis_tid,
    output [3:0] m_axis_tdest,
    output [7:0] m_axis_tuser,
    output m_axis_tvalid,
    input m_axis_tready
);

parameter depth = 16; // Programmable depth of the FIFO

reg [7:0] fifo[depth-1:0]; // FIFO buffer

reg [depth_bits-1:0] count = 0; // Count of elements in the FIFO
reg [depth_bits-1:0] prog_full_thresh = axis_prog_full_thresh; // Programmable full threshold
reg [depth_bits-1:0] prog_empty_thresh = axis_prog_empty_thresh; // Programmable empty threshold

reg [depth_bits-1:0] underflow_count = 0; // Count of underflow events
reg [depth_bits-1:0] overflow_count = 0; // Count of overflow events

reg [depth_bits-1:0] read_pointer = 0; // Read pointer of the FIFO
reg [depth_bits-1:0] write_pointer = 0; // Write pointer of the FIFO

reg s_axis_tvalid_d1 = 0; // Delayed s_axis_tvalid signal
reg [7:0] s_axis_tdata_d1 = 0; // Delayed s_axis_tdata signal
reg [0:7] s_axis_tstrb_d1 = 0; // Delayed s_axis_tstrb signal
reg [7:0] s_axis_tkeep_d1 = 0; // Delayed s_axis_tkeep signal
reg s_axis_tlast_d1 = 0; // Delayed s_axis_tlast signal
reg [3:0] s_axis_tid_d1 = 0; // Delayed s_axis_tid signal
reg [3:0] s_axis_tdest_d1 = 0; // Delayed s_axis_tdest signal
reg [7:0] s_axis_tuser_d1 = 0; // Delayed s_axis_tuser signal

// Delay the input signals by one clock cycle
always @(posedge s_aclk) begin
    s_axis_tvalid_d1 <= s_axis_tvalid;
    s_axis_tdata_d1 <= s_axis_tdata;
    s_axis_tstrb_d1 <= s_axis_tstrb;
    s_axis_tkeep_d1 <= s_axis_tkeep;
    s_axis_tlast_d1 <= s_axis_tlast;
    s_axis_tid_d1 <= s_axis_tid;
    s_axis_tdest_d1 <= s_axis_tdest;
    s_axis_tuser_d1 <= s_axis_tuser;
end

// Write data to the FIFO
always @(posedge s_aclk) begin
    if (s_axis_tvalid_d1 && s_axis_tready && count < depth) begin
        fifo[write_pointer] <= s_axis_tdata_d1;
        count <= count + 1;
        write_pointer <= write_pointer + 1;
        if (write_pointer == depth) begin
            write_pointer <= 0;
        end
    end
end

// Read data from the FIFO
always @(posedge s_aclk) begin
    if (m_axis_tready && count > 0) begin
        m_axis_tdata <= fifo[read_pointer];
        m_axis_tstrb <= s_axis_tstrb_d1;
        m_axis_tkeep <= s_axis_tkeep_d1;
        m_axis_tlast <= s_axis_tlast_d1;
        m_axis_tid <= s_axis_tid_d1;
        m_axis_tdest <= s_axis_tdest_d1;
        m_axis_tuser <= s_axis_tuser_d1;
        m_axis_tvalid <= 1;
        read_pointer <= read_pointer + 1;
        count <= count - 1;
        if (read_pointer == depth) begin
            read_pointer <= 0;
        end
    end else begin
        m_axis_tvalid <= 0;
    end
end

// Check for underflow and overflow events
always @(posedge s_aclk) begin
    if (s_axis_tvalid_d1 && s_axis_tready && count == 0) begin
        underflow_count <= underflow_count + 1;
    end
    if (s_axis_tvalid_d1 && s_axis_tready && count == depth) begin
        overflow_count <= overflow_count + 1;
    end
end

// Check if the FIFO is full or empty
assign axis_data_count = count;
assign axis_prog_full_thresh = prog_full_thresh;
assign axis_prog_empty_thresh = prog_empty_thresh;
assign axis_underflow = (count == 0) ? 1 : 0;
assign axis_overflow = (count == depth) ? 1 : 0;

// Check if the FIFO is ready to accept input data
assign s_axis_tready = (count < depth) ? 1 : 0;

// Reset the FIFO
always @(posedge s_aclk) begin
    if (!aresetn) begin
        count <= 0;
        read_pointer <= 0;
        write_pointer <= 0;
        underflow_count <= 0;
        overflow_count <= 0;
    end
end

endmodule

