);

parameter DEPTH = 8, ADDRESS_WIDTH = 3, WIDTH=8;

reg [ADDRESS_WIDTH-1:0] write_ptr = 0;
reg [ADDRESS_WIDTH-1:0] read_ptr = 0;

reg [DEPTH-1:0] full = 0;
reg [DEPTH-1:0] empty = 1;

reg [WIDTH-1:0] mem [0:(1<<ADDRESS_WIDTH)-1];

assign Full_out = full;
assign Empty_out = empty;

always @(posedge CLK) begin
    if (RESET) begin
        write_ptr <= 0;
        read_ptr <= 0;
        full <= 0;
        empty <= 1;
    end else if (WEN && !full) begin
        mem[write_ptr] <= Data_in[write_ptr];
        write_ptr <= write_ptr + 1;
        if (write_ptr == DEPTH) begin
            write_ptr <= 0;
        end
        if (write_ptr == read_ptr) begin
            full <= ~full;
        end
        empty <= 0;
    end else if (REN && !empty) begin
        Data_out[read_ptr] <= mem[read_ptr];
        read_ptr <= read_ptr + 1;
        if (read_ptr == DEPTH) begin
            read_ptr <= 0;
        end
        if (read_ptr == write_ptr) begin
            empty <= ~empty;
        end
        full <= 0;
    end
end

