module fft_ifft (
  input [n-1:0] in,
  input start,
  input fft_or_ifft,
  output [n-1:0] out,
  output done
);

parameter n = 8; // number of input and output samples
parameter twiddle_bits = 8; // number of bits used to represent twiddle factors (W values)

// Define twiddle factors
reg signed [twiddle_bits-1:0] twiddle_real [0:n/2-1];
reg signed [twiddle_bits-1:0] twiddle_imag [0:n/2-1];

// Generate twiddle factors
integer k;
generate
  for (k = 0; k < n/2; k = k + 1) begin
    assign twiddle_real[k] = $signed($bitstoreal({1'b0, $signed($itor(k))})*2.0*PI/n);
    assign twiddle_imag[k] = -$signed($bitstoreal({1'b0, $signed($itor(k))})*2.0*PI/n);
  end
endgenerate

// Define butterfly operations
function [2*n-1:0] butterfly;
  input signed [twiddle_bits-1:0] wr, wi, xr, xi;
  begin
    butterfly[0] = xr + (wr*xr - wi*xi);
    butterfly[1] = xi + (wr*xi + wi*xr);
  end
endfunction

// Define FFT operation
function [n-1:0] fft;
  input signed [n-1:0] x;
  integer i, j, k, m;
  reg signed [n-1:0] temp_x [0:n-1];
  reg signed [n-1:0] temp_y [0:n-1];
  reg signed [twiddle_bits-1:0] wr, wi;
  begin
    // Bit-reverse the input samples
    for (i = 0; i < n; i = i + 1) begin
      temp_x[i] = x[($clog2(n)-1):0];
      for (j = $clog2(n)-2; j >= 0; j = j - 1) begin
        temp_x[i] = {temp_x[i], x[i][j]};
      end
    end

    // Perform FFT butterfly operations
    for (m = 1; m < n; m = m*2) begin
      for (k = 0; k < m; k = k + 1) begin
        wr = twiddle_real[k*(n/m/2)];
        wi = twiddle_imag[k*(n/m/2)];
        for (i = k; i < n; i = i + m*2) begin
          j = i + m;
          {temp_y[i], temp_y[j]} = butterfly(wr, wi, temp_x[i], temp_x[j]);
        end
      end
      for (i = 0; i < n; i = i + 1) begin
        temp_x[i] = temp_y[i];
      end
    end

    fft = temp_x;
  end
endfunction

// Define IFFT operation
function [n-1:0] ifft;
  input signed [n-1:0] x;
  integer i, j, k, m;
  reg signed [n-1:0] temp_x [0:n-1];
  reg signed [n-1:0] temp_y [0:n-1];
  reg signed [twiddle_bits-1:0] wr, wi;
  begin
    // Bit-reverse the input samples
    for (i = 0; i < n; i = i + 1) begin
      temp_x[i] = x[($clog2(n)-1):0];
      for (j = $clog2(n)-2; j >= 0; j = j - 1) begin
        temp_x[i] = {temp_x[i], x[i][j]};
      end
    end

    // Perform IFFT butterfly operations
    for (m = 1; m < n; m = m*2) begin
      for (k = 0; k < m; k = k + 1) begin
        wr = twiddle_real[k*(n/m/2)];
        wi = twiddle_imag[k*(n/m/2)];
        for (i = k; i < n; i = i + m*2) begin
          j = i + m;
          {temp_y[i], temp_y[j]} = butterfly(wr, wi, temp_x[i], temp_x[j]);
        end
      end
      for (i = 0; i < n; i = i + 1) begin
        temp_x[i] = temp_y[i];
      end
    end

    // Scale the output samples
    for (i = 0; i < n; i = i + 1) begin
      ifft[i] = temp_x[i]/n;
    end
  end
endfunction

// Define module behavior
reg [n-1:0] x;
reg [n-1:0] y;
reg done_reg;
integer i;
always @(posedge start) begin
  if (fft_or_ifft) begin
    y = ifft(x);
  end else begin
    y = fft(x);
  end
  done_reg = 1;
end

assign out = y;
assign done = done_reg;

endmodule

