  if (reset) begin
    state <= 4'b0000;
    out <= 1'b0;
  end
  else begin
    case (state)
      4'b0000: if (data[7:4] == 4'b1011) state <= 4'b0001;
               else state <= 4'b0000;
      4'b0001: if (data[7:4] == 4'b1011) state <= 4'b0010;
               else state <= 4'b0000;
      4'b0010: if (data[7:4] == 4'b1011) begin
                  state <= 4'b0011;
                  out <= 1'b1;
                end
               else state <= 4'b0000;
      4'b0011: begin
                  state <= 4'b0100;
                  out <= 1'b0;
                end
      4'b0100: state <= 4'b0000;
    endcase
  end
end

