module audio_processing (
  input clk,
  input rst,
  input [15:0] micData,
  input enable,
  output reg start,
  output reg [15:0] d_out
);

  parameter BUFFER_SIZE = 1024;
  parameter LOG2_BUFFER_SIZE = 10;

  reg [15:0] buffer [0:BUFFER_SIZE-1];
  reg [LOG2_BUFFER_SIZE-1:0] buffer_ptr;
  reg [15:0] twiddle_factors [0:BUFFER_SIZE/2-1];

  reg [LOG2_BUFFER_SIZE-1:0] stage;
  reg [LOG2_BUFFER_SIZE-1:0] i;
  reg [LOG2_BUFFER_SIZE-1:0] j;
  reg [LOG2_BUFFER_SIZE-1:0] k;
  reg [15:0] temp;
  reg [15:0] u;
  reg [15:0] t;
  reg [15:0] w;
  reg [15:0] r;
  reg [15:0] c;
  reg [15:0] s;

  reg [15:0] d_in;
  reg [1:0] addr;
  reg wr;
  reg rd;

  assign d_out = buffer[BUFFER_SIZE-1];

  always @(posedge clk) begin
    if (rst) begin
      start <= 0;
      buffer_ptr <= 0;
      stage <= 0;
      i <= 0;
      j <= 0;
      k <= 0;
      d_in <= 0;
      addr <= 0;
      wr <= 0;
      rd <= 0;
    end else begin
      if (enable) begin
        buffer[buffer_ptr] <= micData;
        buffer_ptr <= buffer_ptr + 1;
        if (buffer_ptr == BUFFER_SIZE) begin
          start <= 1;
          buffer_ptr <= 0;
          for (i = 0; i < BUFFER_SIZE/2; i = i + 1) begin
            twiddle_factors[i] <= $realtobits(cos(2*pi*i/BUFFER_SIZE)) & $realtobits(-sin(2*pi*i/BUFFER_SIZE));
          end
          for (stage = LOG2_BUFFER_SIZE-1; stage >= 0; stage = stage - 1) begin
            for (i = 0; i < 2**stage; i = i + 1) begin
              for (j = 0; j < BUFFER_SIZE/2**stage; j = j + 1) begin
                k <= i*BUFFER_SIZE/2**stage + j;
                u <= buffer[k];
                t <= buffer[k + BUFFER_SIZE/2**stage];
                w <= twiddle_factors[j*BUFFER_SIZE/2**stage];
                r <= u + t;
                c <= (u - t) * w;
                s <= $bitsreversal(twiddle_factors[j*BUFFER_SIZE/2**stage]);
                buffer[k] <= r;
                buffer[k + BUFFER_SIZE/2**stage] <= c;
              end
            end
          end
        end else begin
          start <= 0;
        end
      end else begin
        start <= 0;
      end
    end
  end

  always @(posedge clk) begin
    if (rst) begin
      d_in <= 0;
      addr <= 0;
      wr <= 0;
      rd <= 0;
    end else begin
      if (start) begin
        d_in <= 0;
        addr <= 0;
        wr <= 0;
        rd <= 0;
      end else begin
        d_in <= 0;
        addr <= 0;
        wr <= 0;
        rd <= 0;
        case (stage)
          0: begin
            d_in <= buffer[$bitsreversal(i)];
            addr <= 0;
            wr <= 1;
            i <= i + 1;
            if (i == BUFFER_SIZE) begin
              stage <= stage + 1;
              i <= 0;
            end
          end
          default: begin
            d_in <= buffer[$bitsreversal(i)];
            addr <= j;
            wr <= 1;
            i <= i + 1;
            if (i == BUFFER_SIZE/2**stage) begin
              i <= 0;
              j <= j + 1;
              if (j == 2**stage-1) begin
                j <= 0;
                stage <= stage + 1;
              end
            end
          end
        endcase
      end
    end
  end

  always @(posedge clk) begin
    if (rst) begin
      d_out <= 0;
    end else begin
      if (start) begin
        d_out <= 0;
      end else begin
        case (stage)
          0: begin
            rd <= 1;
            if (i == BUFFER_SIZE) begin
              stage <= stage + 1;
              i <= 0;
            end
          end
          default: begin
            rd <= 1;
            if (i == BUFFER_SIZE/2**stage) begin
              i <= 0;
              j <= j + 1;
              if (j == 2**stage-1) begin
                j <= 0;
                stage <= stage + 1;
              end
            end
          end
        endcase
        if (rd) begin
          d_out <= $bitsreversal(d_in);
        end
      end
    end
  end

endmodule

