  wire [99:0] adder_out;
  wire         adder_cout;
  carry_lookahead_adder adder(.a(a), .b(b), .cin(cin), .sum(adder_out), .cout(adder_cout));

  // Edge Detector
  reg  [1:0]  sig_reg;
  wire        sig_edge;
  always @(posedge clk) begin
    sig_reg <= {sig_reg[0], sig};
    sig_edge = (sig_reg[1] ^ sig_reg[0]);
  end

  // Output Logic
  always @(posedge clk) begin
    if (sig_edge && sig_reg[1]) begin
      rise <= 1'b1;
      down <= 1'b0;
