      rise <= 1'b0;
      down <= 1'b1;
    end else begin
      rise <= 1'b0;
      down <= 1'b0;
    end

    if (sig) begin
      sum <= adder_out;
      cout <= adder_cout;
    end else begin
      sum <= 100'b0;
      cout <= 1'b0;
    end
  end

  // Reset Logic
  always @(posedge clk) begin
