module four_bit_adder(
  input [3:0] A,
  input [3:0] B,
  input M,
  output reg [3:0] S
);

  // Local signals
  wire [3:0] sum;
  wire carry;

  // Generate the sum and carry using a full adder
  genvar i;
  generate
    for(i = 0; i < 4; i = i + 1) begin : full_adder
      full_adder fa(
        .A(A[i]),
        .B(B[i]),
        .Cin(i == 0 ? 1'b0 : carry),
        .S(sum[i]),
        .Cout(carry)
      );
    end
  endgenerate

  // Perform unsigned or two's complement addition based on the mode input
  always @(*) begin
    if(M == 0) begin
      S = sum;
    end else begin
      S = sum + (~M + 1);
    end
  end

endmodule

