  if (~reset_n) begin
    state <= IDLE;
    debounce <= 0;
  end else begin
    case (state)
      IDLE: begin
        if (button == 1) begin
          state <= PRESSED;
          debounce <= 1;
        end else begin
          state <= IDLE;
          debounce <= 0;
        end
      end
      PRESSED: begin
        if (button == 1) begin
          state <= PRESSED;
          debounce <= 1;
        end else begin
          state <= DEBOUNCING;
          debounce <= 1;
        end
      end
      DEBOUNCING: begin
        if (button == 1) begin
          state <= PRESSED;
          debounce <= 1;
        end else if (debounce == DEBOUNCE_CYCLES) begin
          state <= IDLE;
          debounce <= 0;
        end else begin
          state <= DEBOUNCING;
          debounce <= debounce + 1;
        end
      end
    endcase
  end
end

endmodule

