module byte_reverser_pipeline(
    input [31:0] in,
    output [31:0] out
);

reg [7:0] byte0, byte1, byte2, byte3;
reg [31:0] shifted_byte0, shifted_byte1, shifted_byte2, shifted_byte3;

// Stage 1: Extract bytes from input
assign byte0 = in[7:0];
assign byte1 = in[15:8];
assign byte2 = in[23:16];
assign byte3 = in[31:24];

// Stage 2: Shift bytes to correct position
always @(*) begin
    shifted_byte0 = byte0 << 24;
    shifted_byte1 = byte1 << 16;
    shifted_byte2 = byte2 << 8;
    shifted_byte3 = byte3;
end

// Stage 3: Select bytes for each position
always @(*) begin
    case (in[1:0])
        2'b00: out = shifted_byte3 | shifted_byte2 | shifted_byte1 | shifted_byte0;
        2'b01: out = shifted_byte2 | shifted_byte3 | shifted_byte0 | shifted_byte1;
        2'b10: out = shifted_byte1 | shifted_byte0 | shifted_byte3 | shifted_byte2;
        2'b11: out = shifted_byte0 | shifted_byte1 | shifted_byte2 | shifted_byte3;
    endcase
end

endmodule

