endmodule

module serial_comm (
	input  clk,
	input  RX,
	output TX,
	output LED1,
	output LED2,
	output LED3,
	output LED4,
	output LED5
);

	parameter integer BAUD_RATE = 9600;
	parameter integer CLOCK_FREQ_HZ = 12000000;
	localparam integer PERIOD = CLOCK_FREQ_HZ / BAUD_RATE;

	rs232_recv #(
		.HALF_PERIOD(PERIOD / 2)
	) recv (
		.clk  (clk ),
		.RX   (RX  ),
		.LED1 (LED1),
		.LED2 (LED2),
		.LED3 (LED3),
		.LED4 (LED4),
		.LED5 (LED5)
	);

	rs232_send #(
		.PERIOD(PERIOD)
	) send (
		.clk  (clk ),
		.TX   (TX  ),
		.LED1 (LED1),
		.LED2 (LED2),
		.LED3 (LED3),
		.LED4 (LED4),
		.LED5 (LED5)
	);

endmodule

module rs232_recv (
	input  clk,
	input  RX,
	output LED1,
	output LED2,
	output LED3,
	output LED4,
	output LED5
);

	reg [7:0] data_reg;
	reg [3:0] bit_count;
	reg start_bit;
	reg stop_bit;

	assign LED1 = start_bit;
	assign LED2 = data_reg[0];
	assign LED3 = data_reg[1];
	assign LED4 = data_reg[2];
	assign LED5 = stop_bit;

	always @(posedge clk) begin
		if (RX == 0 && !start_bit && !bit_count) begin
			start_bit <= 1;
			bit_count <= 1;
		end else if (start_bit && bit_count < 9) begin
			data_reg[bit_count - 1] <= RX;
			bit_count <= bit_count + 1;
		end else if (start_bit && bit_count == 9) begin
			stop_bit <= RX;
			start_bit <= 0;
			bit_count <= 0;
		end
	end

endmodule

module rs232_send (
	input  clk,
	output TX,
	input  LED1,
	input  LED2,
	input  LED3,
	input  LED4,
	input  LED5
);

	reg [7:0] data_reg;
	reg [3:0] bit_count;
	reg start_bit;
	reg stop_bit;

	assign TX = start_bit ? 0 : (bit_count == 9 ? stop_bit : data_reg[bit_count - 1]);

	always @(posedge clk) begin
		if (!start_bit && !bit_count) begin
			start_bit <= 1;
			bit_count <= 1;
			data_reg <= {1'b0, LED4, LED3, LED2, LED1, 1'b0, 1'b0, 1'b0};
		end else if (start_bit && bit_count < 9) begin
			data_reg[bit_count - 1] <= TX;
			bit_count <= bit_count + 1;
		end else if (start_bit && bit_count == 9) begin
			stop_bit <= TX;
			start_bit <= 0;
			bit_count <= 0;
		end
	end

endmodule

module lfsr (Clk, Reset, Seed, Enable, Data, Done);

parameter Tp = 1;

input Clk;
input Reset;
input [15:0] Seed;
input Enable;

output reg [15:0] Data;
output reg Done;

reg [15:0] Lfsr;

always @ (posedge Clk or posedge Reset) begin
  if (Reset) begin
    Lfsr <= #Tp Seed;
    Data <= #Tp 16'h0000;
    Done <= #Tp 1'b0;
  end else if (Enable) begin
    Lfsr <= #Tp {Lfsr[14:0], Lfsr[0] ^ Lfsr[2] ^ Lfsr[3] ^ Lfsr[5]};
    Data <= #Tp Lfsr;
    Done <= #Tp 1'b1;
  end else begin
    Done <= #Tp 1'b0;
  end
end

endmodule

module cyclonev_mac(
  input [ax_width-1:0] ax,
  input [ay_scan_in_width-1:0] ay,
  output [result_a_width-1:0] resulta
);

parameter ax_width = 9;
parameter signed_max = "true";
parameter ay_scan_in_width = 9;
parameter signed_may = "true";
parameter result_a_width = 18;
parameter operation_mode = "M9x9";

reg signed [ax_width-1:0] signed_ax;
reg signed [ay_scan_in_width-1:0] signed_ay;
wire [result_a_width-1:0] signed_resulta;

wire [result_a_width-1:0] unsigned_resulta;
wire [2*result_a_width-1:0] intermediate_result;

assign signed_resulta = resulta;
assign unsigned_resulta = resulta;

always @(*) begin
  if (signed_max) begin
    signed_ax = ax;
  end else begin
    signed_ax = {{ax_width-1{1'b0}}, ax};
  end

  if (signed_may) begin
    signed_ay = ay;
  end else begin
    signed_ay = {{ay_scan_in_width-1{1'b0}}, ay};
  end
end

always @(*) begin
  if (operation_mode == "M9x9") begin
    intermediate_result = signed_ax * signed_ay;
  end else if (operation_mode == "M18x18") begin
    intermediate_result = $signed($signed(signed_ax) * $signed(signed_ay));
  end
end

always @(*) begin
  if (operation_mode == "M9x9") begin
    signed_resulta = signed_resulta + intermediate_result[17:0];
  end else if (operation_mode == "M18x18") begin
    signed_resulta = signed_resulta + intermediate_result[35:18];
  end

  if (signed_resulta >= 0) begin
    unsigned_resulta = signed_resulta;
  end else begin
    unsigned_resulta = ~signed_resulta + 1;
  end

  if (result_a_width < $bits(unsigned_resulta)) begin
    resulta = unsigned_resulta[result_a_width-1:0];
  end else begin
    resulta = {{result_a_width-$bits(unsigned_resulta){1'b0}}, unsigned_resulta};
  end
end

endmodule

module uart_transceiver
   (o_RX_Byte,
    o_RX_Done,
    o_TX_Active,
    o_TX_Done,
    o_TX_Serial,
    i_TX_Load,
    i_Clk,
    i_RX_Serial,
    i_TX_Byte);
  output [7:0]o_RX_Byte;
  output o_RX_Done;
  output o_TX_Active;
  output o_TX_Done;
  output o_TX_Serial;
  input i_TX_Load;
  input i_Clk;
  input i_RX_Serial;
  input [7:0]i_TX_Byte;

  reg [7:0] rx_data;
  reg rx_done;
  reg [7:0] tx_data;
  reg tx_active;
  reg tx_done;
  reg [3:0] tx_state;
  wire i_Clk;
  wire i_RX_Serial;
  wire [7:0]i_TX_Byte;
  wire i_TX_Load;
  wire [7:0]o_RX_Byte;
  wire o_RX_Done;
  wire o_TX_Active;
  wire o_TX_Done;
  wire o_TX_Serial;

  DemoInterconnect_uart_transceiver_0_0_UART_RX uart_rx_inst
       (.i_Clk(i_Clk),
        .i_RX_Serial(i_RX_Serial),
        .o_RX_Byte(o_RX_Byte),
        .o_RX_Done(o_RX_Done));
  DemoInterconnect_uart_transceiver_0_0_UART_TX uart_tx_inst
       (.i_Clk(i_Clk),
        .i_TX_Byte(i_TX_Byte),
        .i_TX_Load(i_TX_Load),
        .o_TX_Active(o_TX_Active),
        .o_TX_Done(o_TX_Done),
        .o_TX_Serial(o_TX_Serial));

  always @(posedge i_Clk) begin
    if (i_RX_Serial == 0 && rx_done == 0) begin
      rx_data <= 0;
      rx_done <= 1;
    end else if (rx_done == 1) begin
      rx_data <= {rx_data[6:0], i_RX_Serial};
      if (rx_data[7] == 1) begin
        o_RX_Byte <= rx_data[6:0];
        rx_done <= 0;
      end
    end

    if (i_TX_Load == 1 && tx_active == 0) begin
      tx_data <= i_TX_Byte;
      tx_active <= 1;
      tx_state <= 0;
    end else if (tx_active == 1) begin
      case (tx_state)
        0: begin
          o_TX_Serial <= 0;
          tx_state <= 1;
        end
        1: begin
          o_TX_Serial <= 1;
          tx_state <= 2;
        end
        2: begin
          o_TX_Serial <= tx_data[0];
          tx_data <= {tx_data[6:0], 0};
          tx_state <= 3;
        end
        3: begin
          o_TX_Serial <= tx_data[0];
          tx_state <= 4;
        end
        4: begin
          o_TX_Serial <= tx_data[0];
          tx_state <= 5;
        end
        5: begin
          o_TX_Serial <= tx_data[0];
          tx_state <= 6;
        end
        6: begin
          o_TX_Serial <= tx_data[0];
          tx_state <= 7;
        end
        7: begin
          o_TX_Serial <= tx_data[0];
          tx_state <= 8;
        end
        8: begin
          o_TX_Serial <= 1;
          tx_active <= 0;
          tx_done <= 1;
          tx_state <= 0;
        end
      endcase
    end else if (tx_done == 1) begin
      o_TX_Serial <= 1;
      tx_done <= 0;
    end

    o_RX_Done <= rx_done;
    o_TX_Active <= tx_active;
    o_TX_Done <= tx_done;
  end
endmodule

