module VCO_interface (
  input Vin,
  input Clk,
  output VCO_out
);

parameter frequency_range = 1000; // Hz
parameter resolution = 0.1; // Hz

reg [31:0] accumulator;
reg [31:0] frequency;
reg [31:0] frequency_scaled;
reg [31:0] frequency_range_scaled;

// Scale the frequency range to match the accumulator size
assign frequency_range_scaled = frequency_range * 2**32 / $realtime;

// Calculate the frequency based on the input voltage
always @ (posedge Clk) begin
  frequency = Vin * frequency_range_scaled;
  frequency_scaled = frequency * resolution;
end

// Generate a sine wave with the calculated frequency
always @ (posedge Clk) begin
  accumulator <= accumulator + frequency_scaled;
  VCO_out <= $sin(accumulator[31:0]);
end

endmodule

module binary_adder(
  input [63:0] A,
  input [63:0] B,
  output [63:0] SUM
);

  wire [32:0] CARRY;
  wire [63:0] FULL_SUM;

  // The first carry is zero
  assign CARRY[0] = 1'b0;

  // Generate the carry chain
  genvar i;
  generate
    for (i = 0; i < 64; i = i + 1) begin : carry_chain
      two_bit_look_ahead op (
        A[i+1:i],
        B[i+1:i],
        CARRY[i],
        FULL_SUM[i+1:i],
        CARRY[i+1]
      );
    end
  endgenerate

  // Generate the full adder chain
  genvar j;
  generate
    for (j = 0; j < 64; j = j + 1) begin : full_adder_chain
      full_adder adder (
        A[j],
        B[j],
        CARRY[j],
        FULL_SUM[j],
        SUM[j]
      );
    end
  endgenerate

endmodule

module two_bit_look_ahead(
  input [1:0] A,
  input [1:0] B,
  input CARRY_IN,
  output [1:0] SUM,
  output CARRY_OUT
);

  assign SUM = A + B + CARRY_IN;
  assign CARRY_OUT = (A[1] & B[1]) | (A[0] & B[1]) | (A[1] & CARRY_IN);

endmodule

module full_adder(
  input A,
  input B,
  input CARRY_IN,
  output SUM,
  output CARRY_OUT
);

  assign SUM = A ^ B ^ CARRY_IN;
  assign CARRY_OUT = (A & B) | (A & CARRY_IN) | (B & CARRY_IN);

endmodule

module up_counter_with_reset_and_load (
    input clk,
    input reset,
    input load,
    output reg [7:0] count
);

    always @(posedge clk) begin
        if (reset) begin
            count <= 0;
        end
        else if (load) begin
            count <= $signed({4'b0, data_in});
        end
        else begin
            count <= count + 1;
        end
    end

endmodule

module up_down_counter_with_load (
    input clk,
    input load,
    input up_down,
    output reg [7:0] count
);

    always @(posedge clk) begin
        if (load) begin
            count <= $signed({4'b0, data_in});
        end
        else if (up_down) begin
            count <= count + 1;
        end
        else begin
            count <= count - 1;
        end
    end

endmodule

