        .clk(clk),
        .reset(reset),
        .load(load),
        .count(count1),
        .data_in(data_in)
    );

    up_down_counter_with_load up_down_counter (
        .clk(clk),
        .load(load),
        .up_down(up_down),
        .count(count2),
        .data_in(data_in)
    );

    summing_module summing (
        .count1(count1),
        .count2(count2),
        .sum(sum)
    );

    assign data_out = sum;

endmodule

