endmodule

module fifo_buffer(rst, wr_clk, rd_clk, din, wr_en, rd_en, dout, full, empty, rd_data_count, wr_data_count, prog_full, prog_empty);

  parameter FIFO_DEPTH = 1024;
  parameter ALMOST_FULL_THRESHOLD = 768;
  parameter ALMOST_EMPTY_THRESHOLD = 256;

  reg [63:0] fifo_mem [FIFO_DEPTH - 1:0];
  reg [9:0] rd_data_count_reg;
  reg [9:0] wr_data_count_reg;
  reg full_reg;
  reg empty_reg;
  reg prog_full_reg;
  reg prog_empty_reg;

  always @(posedge wr_clk) begin
    if (rst) begin
      wr_data_count_reg <= 0;
      rd_data_count_reg <= 0;
      full_reg <= 0;
      empty_reg <= 1;
      prog_full_reg <= 0;
      prog_empty_reg <= 0;
    end else begin
      if (wr_en && !full_reg) begin
        fifo_mem[wr_data_count_reg] <= din;
        wr_data_count_reg <= wr_data_count_reg + 1;
        prog_empty_reg <= (wr_data_count_reg >= ALMOST_EMPTY_THRESHOLD);
        empty_reg <= 0;
      end
      if (rd_en && !empty_reg) begin
        dout <= fifo_mem[rd_data_count_reg];
        rd_data_count_reg <= rd_data_count_reg + 1;
        prog_full_reg <= (FIFO_DEPTH - rd_data_count_reg <= ALMOST_FULL_THRESHOLD);
        full_reg <= 0;
      end
    end
  end

  always @(posedge rd_clk) begin
    if (rst) begin
      wr_data_count_reg <= 0;
      rd_data_count_reg <= 0;
      full_reg <= 0;
      empty_reg <= 1;
      prog_full_reg <= 0;
      prog_empty_reg <= 0;
    end else begin
      if (wr_en && !full_reg) begin
        fifo_mem[wr_data_count_reg] <= din;
        wr_data_count_reg <= wr_data_count_reg + 1;
        prog_empty_reg <= (wr_data_count_reg >= ALMOST_EMPTY_THRESHOLD);
        empty_reg <= 0;
      end
      if (rd_en && !empty_reg) begin
        dout <= fifo_mem[rd_data_count_reg];
        rd_data_count_reg <= rd_data_count_reg + 1;
        prog_full_reg <= (FIFO_DEPTH - rd_data_count_reg <= ALMOST_FULL_THRESHOLD);
        full_reg <= 0;
      end
    end
  end

  assign full = full_reg;
  assign empty = empty_reg;
  assign rd_data_count = rd_data_count_reg;
  assign wr_data_count = FIFO_DEPTH - wr_data_count_reg;
  assign prog_full = prog_full_reg;
  assign prog_empty = prog_empty_reg;

endmodule

module parity_checker (
  input [3:0] data,
  output reg parity
);

  reg [1:0] stage1_data [0:1];
  reg [1:0] stage2_data [0:1];

  always @ (posedge clk) begin
    stage1_data[1] <= stage1_data[0];
    stage1_data[0] <= data;
  end

  assign stage2_data[1] = stage1_data[1] ^ stage1_data[0];
  assign stage2_data[0] = 2'b00;

  always @ (posedge clk) begin
    parity <= stage2_data[1][0] ^ stage2_data[1][1];
  end

endmodule

module PLL (
  input clk_ref,
  input clk_fb,
  output reg clk_out
);

parameter f_ref = 10; // frequency of reference clock signal (MHz)
parameter f_out = 20; // desired frequency of synchronized clock signal (MHz)
parameter N = 2; // multiplication factor
parameter M = 2; // division factor

reg [31:0] phase_accumulator = 0;
reg [31:0] phase_increment = 0;

always @(posedge clk_ref) begin
  phase_accumulator <= phase_accumulator + phase_increment;
end

assign clk_out = phase_accumulator[31];

always @(posedge clk_fb) begin
  phase_increment <= ((N * f_ref) << 32) / (M * f_out);
end

endmodule

module barrel_shifter (
    input [3:0] data,
    input [1:0] shift,
    input shift_right,
    input shift_left,
    input rotate_right,
    input rotate_left,
    output reg [3:0] result
);

reg [3:0] stage1_out;
reg [3:0] stage2_out;

always @(*) begin
    if (shift_right) begin
        stage1_out = {2'b00, data[3:2]};
    end else if (shift_left) begin
        stage1_out = {data[1:0], 2'b00};
    end else if (rotate_right) begin
        stage1_out = {shift[1], data[3:shift[0]]};
    end else if (rotate_left) begin
        stage1_out = {data[shift[1]:0], shift[0]};
    end
end

always @(posedge clk) begin
    stage2_out <= stage1_out;
end

assign result = stage2_out;

endmodule

module binary_counter(
        input clk_i,
        input rst_i,
        output reg [2:0] count_o
    );

    // Define the states of the finite state machine
    parameter [1:0] IDLE = 2'b00;
    parameter [1:0] COUNT = 2'b01;

    // Define the current state of the finite state machine
    reg [1:0] state;

    always @(posedge clk_i, posedge rst_i) begin
        if (rst_i) begin
            // Reset the counter to zero
            state <= IDLE;
            count_o <= 3'b0;
        end
        else begin
            case (state)
                IDLE: begin
                    // Wait for the next clock cycle to start counting
                    state <= COUNT;
                end
                COUNT: begin
                    // Increment the counter and reset it to zero if it reaches its maximum value
                    if (count_o == 3'b111) begin
                        count_o <= 3'b0;
                        state <= IDLE;
                    end
                    else begin
                        count_o <= count_o + 3'b1;
                        state <= COUNT;
                    end
                end
                default: begin
                    // Should never happen
                    state <= IDLE;
                    count_o <= 3'b0;
                end
            endcase
        end
    end
endmodule

module gray_code_state_machine (
  input clk,
  input rst,
  output [n-1:0] out
);

parameter n = 4; // number of output signals

reg [n-1:0] state;
reg [n-1:0] gray_code;

always @ (posedge clk) begin
  if (rst) begin
    state <= 0;
  end else begin
    state <= gray_code;
  end
end

always @* begin
  case (state)
    0: gray_code = 0;
    1: gray_code = 1;
    2: gray_code = 3;
    3: gray_code = 2;
    4: gray_code = 6;
    5: gray_code = 7;
    6: gray_code = 5;
    7: gray_code = 4;
    default: gray_code = 0;
  endcase
end

assign out = gray_code;

endmodule

module ripple_carry_adder(
    input [3:0] A,
    input [3:0] B,
    output [3:0] S,
    output Cout
);
    wire [3:0] C;

    assign C[0] = 1'b0; // Initialize the carry-in to 0

    // Full adder for bit 0
    full_adder FA0(A[0], B[0], C[0], S[0], C[1]);

    // Full adder for bit 1
    full_adder FA1(A[1], B[1], C[1], S[1], C[2]);

    // Full adder for bit 2
    full_adder FA2(A[2], B[2], C[2], S[2], C[3]);

    // Full adder for bit 3
    full_adder FA3(A[3], B[3], C[3], S[3], Cout);

endmodule

module full_adder(
    input A,
    input B,
    input Cin,
    output S,
    output Cout
);
    assign S = A ^ B ^ Cin;
    assign Cout = (A & B) | (A & Cin) | (B & Cin);
endmodule

module uart_tx(
  input                       CLK,
  input                       RST,
  input                       EN,
  input   [DATAWIDTH - 1 : 0] DATA,
  input                       DATARDY,
  output                      READ,
  output                      TX
);

  parameter DATAWIDTH = 8;
  parameter IDLE      = 4'h0;
  parameter START     = 4'h1;
  parameter BIT_TX    = 4'h2;
  parameter STOP      = 4'h3;

  reg       read_reg;
  reg       tx_reg;
  reg [1:0] curr_state;
  reg [1:0] next_state;
  reg [2:0] bit_cnt;

  always @ (posedge CLK) begin
    if(RST == 1) begin
      tx_reg <= 1;
      next_state <= IDLE;
      curr_state <= IDLE;
      bit_cnt <= 3'h0;
    end
    else begin
      case(curr_state)
        IDLE: begin
          tx_reg <= 1'b1;
          if((EN == 1'b1) && (DATARDY == 1'b1)) begin
            read_reg <= 1;
            next_state <= START;
          end
          else begin
            read_reg <= 0;
            next_state <= IDLE;
          end
        end
        START: begin
          tx_reg <= 1'b0;
          read_reg <= 1'b0;
          next_state <= BIT_TX;
        end
        BIT_TX: begin
          tx_reg <= DATA[bit_cnt];
          if(bit_cnt == 3'h7) begin
            bit_cnt <= 3'h0;
            next_state <= STOP;
          end
          else begin
            bit_cnt <= bit_cnt + 1'b1;
            next_state <= BIT_TX;
          end
        end
        STOP: begin
          tx_reg <= 1'b1;
          if(DATARDY == 1'b1) begin
            read_reg <= 1'b1;
            next_state <= START;
          end
          else begin
            next_state <= IDLE;
          end
        end
        default: begin
          tx_reg <= 1'b1;
          next_state <= IDLE;
        end
      endcase
      curr_state <= next_state;
    end
  end


  assign READ = read_reg;
  assign TX = tx_reg;

endmodule

module seq_rec #(
    parameter BASEADDR = 0,
    parameter HIGHADDR = 0,
    parameter ABUSWIDTH = 16,
    parameter MEM_BYTES = 2*1024,
    parameter IN_BITS = 8
) (
    input wire                   BUS_CLK,
    input wire                   BUS_RST,
    input wire  [ABUSWIDTH-1:0]  BUS_ADD,
    inout wire  [7:0]            BUS_DATA,
    input wire                   BUS_RD,
    input wire                   BUS_WR,

    input wire                SEQ_CLK,
    input wire [IN_BITS-1:0]  SEQ_IN,
    input wire                SEQ_EXT_START
);

reg [7:0] mem[MEM_BYTES-1:0];
reg [ABUSWIDTH-1:0] addr_reg;
reg [7:0] data_reg;
reg [1:0] state_reg;
wire [1:0] state_next;

parameter IDLE = 2'b00;
parameter READ = 2'b01;
parameter WRITE = 2'b10;

assign BUS_DATA = (state_reg == READ) ? data_reg : 8'hzz;

assign state_next = (SEQ_EXT_START && (state_reg == IDLE)) ? WRITE :
                    (SEQ_EXT_START && (state_reg == WRITE)) ? READ :
                    state_reg;

always @(posedge SEQ_CLK) begin
    case (state_reg)
        IDLE: begin
            addr_reg <= BUS_ADD;
            data_reg <= SEQ_IN;
        end
        READ: begin
            data_reg <= mem[addr_reg];
        end
        WRITE: begin
            mem[addr_reg] <= SEQ_IN;
        end
    endcase
    state_reg <= state_next;
end

