module encoder (
    input [7:0] in,
    output reg [2:0] out
);

reg [7:0] in_reg;
reg [2:0] out_reg;

always @ (posedge clk) begin
    in_reg <= in;
end

always @ (posedge clk) begin
    out_reg[0] <= in_reg[0] | in_reg[1] | in_reg[3] | in_reg[4] | in_reg[6];
    out_reg[1] <= in_reg[2] | in_reg[3] | in_reg[5] | in_reg[6] | in_reg[7];
    out_reg[2] <= in_reg[4] | in_reg[5] | in_reg[6] | in_reg[7];
end

assign out = out_reg;

endmodule

module full_adder_32(
    input [31:0] A,
    input [31:0] B,
    input [31:0] Cin,
    output [31:0] Sum,
    output Cout
);

    wire [31:0] c;
    wire [31:0] s;

    assign c[0] = Cin;
    genvar i;
    generate
        for (i = 0; i < 31; i = i + 1) begin
            assign s[i] = A[i] ^ B[i] ^ c[i];
            assign c[i+1] = (A[i] & B[i]) | (A[i] & c[i]) | (B[i] & c[i]);
        end
    endgenerate

    assign s[31] = A[31] ^ B[31] ^ c[31];
    assign Cout = (A[31] & B[31]) | (A[31] & c[31]) | (B[31] & c[31]);

    assign Sum = s;

endmodule

module dualRAM(clk, reset, dout1, dout2);

  // Inputs
  input clk;
  input reset;

  // Outputs
  output [7:0] dout1;
  output [7:0] dout2;

  // Instantiate dual port RAM module
  sig1dualRAM ram(clka, ena, wea, addra, dina, clkb, enb, addrb, doutb);

  // Signals for port A
  reg clka;
  reg ena;
  reg wea;
  reg [13:0] addra;
  reg [7:0] dina;

  // Signals for port B
  reg clkb;
  reg enb;
  reg [13:0] addrb;
  wire [7:0] doutb;

  // Initialize signals
  initial begin
    clka = 0;
    ena = 0;
    wea = 0;
    addra = 0;
    dina = 0;
    clkb = 0;
    enb = 0;
    addrb = 0;
  end

  // Write the value 0xFF to address 0x100 using port A
  always @(posedge clk) begin
    if (reset) begin
      clka <= 0;
      ena <= 0;
      wea <= 0;
      addra <= 0;
      dina <= 0;
    end else begin
      clka <= 1;
      ena <= 1;
      wea <= 1;
      addra <= 14'h100;
      dina <= 8'hFF;
    end
  end

  // Read the value from address 0x100 using port B
  always @(posedge clk) begin
    if (reset) begin
      clkb <= 0;
      enb <= 0;
      addrb <= 0;
    end else begin
      clkb <= 1;
      enb <= 1;
      addrb <= 14'h100;
      dout1 <= doutb;
    end
  end

  // Write the value 0x55 to address 0x200 using port A
  always @(posedge clk) begin
    if (reset) begin
      clka <= 0;
      ena <= 0;
      wea <= 0;
      addra <= 0;
      dina <= 0;
    end else begin
      clka <= 1;
      ena <= 1;
      wea <= 1;
      addra <= 14'h200;
      dina <= 8'h55;
    end
  end

  // Read the value from address 0x200 using port B
  always @(posedge clk) begin
    if (reset) begin
      clkb <= 0;
      enb <= 0;
      addrb <= 0;
    end else begin
      clkb <= 1;
      enb <= 1;
      addrb <= 14'h200;
      dout2 <= doutb;
    end
  end

endmodule

module top_module (
