);

// Instantiate the 32-bit signal change detector module
signal_change_detector detector_inst (
    .clk(clk),
    .reset(reset),
    .in(mux_out),
    .out(detector_out)
);

// Perform a bitwise AND operation on the outputs of the multiplexer and detector modules
always @(posedge clk, negedge reset) begin
    if (reset == 0) begin
        out <= 0;
    end else begin
        out <= mux_out & detector_out;
    end
end

// Define internal signals
reg [31:0] mux_out;
reg [31:0] detector_out;

