// Define the 6-to-1 multiplexer module
module mux_6to1 (
    input [2:0] sel,
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output reg [31:0] out
);

always @* begin
    case (sel)
        3'b000: out = data0;
        3'b001: out = data1;
        3'b010: out = data2;
        3'b011: out = data3;
        3'b100: out = data4;
        3'b101: out = data5;
        default: out = 0;
    endcase
end

endmodule

// Define the 32-bit signal change detector module
module signal_change_detector (
    input clk,
    input reset,
    input [31:0] in,
    output reg [31:0] out
);

reg [31:0] prev_in;

always @(posedge clk, negedge reset) begin
    if (reset == 0) begin
        prev_in <= 0;
        out <= 0;
    end else begin
        if (in == 0 && prev_in == 1) begin
            out <= 1;
        end else begin
            out <= 0;
        end
        prev_in <= in;
    end
end

endmodule

