module cla_8(a, b, c_in, g_out, p_out, s, c_out);
  input [7:0] a, b;
  input c_in;
  output g_out, p_out;
  output [7:0] s;
  output c_out;

  wire [1:0] g, p;
  wire [3:0] s0, s1;

  cla_4 cla0 (a[3:0], b[3:0], c_in, g[0], p[0], s0);
  cla_4 cla1 (a[7:4], b[7:4], g[0], g[1], p[1], s1);
  g_p g_p0(g, p, c_in, g_out, p_out, c_out);

  assign s = {s1, s0};
endmodule

module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

    wire c1, c2, c3;

    // First bit
    xor(S[0], A[0], B[0]);
    and(c1, A[0], B[0]);
    xor(S[0], S[0], Cin);
    or(c2, A[0], B[0]);
    and(c3, Cin, c2);
    or(Cout, c1, c3);

    // Second bit
    xor(S[1], A[1], B[1]);
    and(c1, A[1], B[1]);
    xor(S[1], S[1], c2);
    or(c2, A[1], B[1]);
    and(c3, c2, c1);
    or(c2, c3, c1);

    // Third bit
    xor(S[2], A[2], B[2]);
    and(c1, A[2], B[2]);
    xor(S[2], S[2], c2);
    or(c2, A[2], B[2]);
    and(c3, c2, c1);
    or(c2, c3, c1);

    // Fourth bit
    xor(S[3], A[3], B[3]);
    and(c1, A[3], B[3]);
    xor(S[3], S[3], c2);
    or(Cout, Cout, c1);
    or(Cout, Cout, c2);

endmodule

module SERIAL_TO_PARALLEL # (parameter SIZE = 8)
(
    input wire serial_in,
    input wire enable_stp,
    input wire SD_CLK,
    input wire RESET_L,
    output reg reception_complete,
    output reg [SIZE - 1:0] parallel_out
);

reg [8:0] contador;

always @ (posedge SD_CLK or negedge RESET_L) begin
    if (~RESET_L) begin
        parallel_out <= 0;
        reception_complete <= 0;
        contador <= 0;
    end else begin
        if (enable_stp) begin
            if (contador == SIZE) begin
                reception_complete <= 1;
                contador <= 0;
            end else begin
                reception_complete <= 0;
                parallel_out <= {serial_in, parallel_out[SIZE-1:1]};
                contador <= contador + 1;
            end
        end else begin
            parallel_out <= 0;
        end
    end
end //always

endmodule

module vending_machine(
  input clk,
  input reset,
  input [1:0] coin,
  input dispense,
  output reg product_dispensed,
  output reg [3:0] excess_money,
  output reg [3:0] display_message,
  output reg [3:0] product_count
);

reg [3:0] price = 3; // price of the product in cents
reg [3:0] total_money = 0; // total money inserted
reg [3:0] change = 0; // change to be returned
reg [3:0] stock = 10; // number of products available

always @(posedge clk) begin
  if (reset) begin // reset the vending machine
    product_dispensed <= 0;
    excess_money <= 0;
    display_message <= 0;
    product_count <= 10;
    total_money <= 0;
    change <= 0;
    stock <= 10;
  end else begin
    excess_money <= total_money - price; // calculate excess money
    if (excess_money < 0) begin // not enough money inserted
      product_dispensed <= 0;
      change <= total_money;
      total_money <= 0;
    end else begin // enough money inserted
      product_dispensed <= dispense & (stock > 0);
      if (product_dispensed) begin // dispense product
        stock <= stock - 1;
        change <= excess_money;
        total_money <= 0;
      end else begin // return excess money
        change <= excess_money;
        total_money <= 0;
      end
    end
    if (stock == 0) begin // out of stock
      display_message <= "Sold Out!";
    end else begin // display product count
      display_message <= "Prod: " & product_count;
    end
  end
end

always @(posedge clk) begin
  if (reset) begin // reset the total money inserted
    total_money <= 0;
  end else begin // add money to the total money inserted
    total_money <= total_money + {2'b0, coin};
  end
end

endmodule

module factorFinder(
    input [0:31] product,
    input clk,
    output reg [0:15] factorA,
    output reg [0:15] factorB,
    output reg isDone
);

    reg [0:15] nextFactorA;
    reg reset;
    reg nextReset;
    reg isFactor;

    division divider (
        .n(product), 
        .d(factorA), 
        .clk(clk),
        .reset(reset),
        .q(factorB), 
        .isFactor(isFactor), 
        .isDone(isDone)
    );

    initial begin
        nextFactorA = 2;
        nextReset = 0;
    end

    always @(posedge clk) begin
        factorA <= nextFactorA;
        reset <= nextReset;
    end

    always @(*) begin
        if (!isDone) begin
            nextFactorA = factorA;
            nextReset = 1;
        end else begin
            nextFactorA = nextFactorA + 1;
            nextReset = 0;
        end
    end

    assign isDone = isFactor || (factorA == 65535);

endmodule

