module multiplier_16bit (
    input clk,
    input reset,
    input [15:0] data_in1,
    input [15:0] data_in2,
    input enable_pipeline,
    output reg [31:0] product_out
);

reg [15:0] partial_product1;
reg [15:0] partial_product2;
reg [15:0] partial_product3;
reg [15:0] partial_product4;
reg [31:0] accumulator;

always @(posedge clk) begin
    if (reset) begin
        partial_product1 <= 0;
        partial_product2 <= 0;
        partial_product3 <= 0;
        partial_product4 <= 0;
        accumulator <= 0;
        product_out <= 0;
    end else begin
        if (enable_pipeline) begin
            // Pipeline stage 1: Fetch inputs
            partial_product1 <= data_in1;
            partial_product2 <= data_in2;

            // Pipeline stage 2: Partial product generation
            partial_product3 <= partial_product1 * partial_product2;

            // Pipeline stage 3: Addition of partial products
            partial_product4 <= {partial_product3[15:0], 16'b0} + {partial_product3[31:16], 16'b0};

            // Pipeline stage 4: Accumulation of partial products
            accumulator <= accumulator + partial_product4;

            // Pipeline stage 5: Output
            product_out <= accumulator;
        end else begin
            product_out <= data_in1 * data_in2;
        end
    end
end

endmodule

module thermal_mgmt (
  input clk,
  input rst,
  input [7:0] temp,
  input [7:0] target_temp,
  output pwm
);

  // ADC module
  reg [7:0] digital_temp;
  always @ (posedge clk) begin
    digital_temp <= temp;
  end

  // PID controller module
  reg [7:0] error;
  reg [7:0] integral;
  reg [7:0] derivative;
  reg [7:0] prev_error;
  reg [7:0] Kp = 2;
  reg [7:0] Ki = 1;
  reg [7:0] Kd = 1;
  reg [7:0] pwm_duty_cycle;

  always @ (posedge clk) begin
    error <= target_temp - digital_temp;
    integral <= integral + error;
    derivative <= error - prev_error;
    prev_error <= error;
    pwm_duty_cycle <= Kp*error + Ki*integral + Kd*derivative;
  end

  // Fan control
  reg fan_on;
  always @ (posedge clk) begin
    if (error > 0) begin
      fan_on <= 1;
    end else if (error < 0) begin
      fan_on <= 0;
    end
  end

  // PWM output
  reg [7:0] pwm_counter;
  always @ (posedge clk) begin
    if (pwm_counter < pwm_duty_cycle) begin
      pwm <= 1;
    end else begin
      pwm <= 0;
    end
    pwm_counter <= pwm_counter + 1;
  end

endmodule

module mmio_controller(
    input clk, rst,
    input [31:0] addr, data,
    input cs0_, cs3_, cs4_, cs5_, cs6_, cs7_,
    input oe_, we_,
    output reg [7:0] vga_r, vga_g, vga_b,
    output reg vga_hs, vga_vs,
    output reg [31:0] irpts,
    output reg cpu_int, cpu_int_ack,
    output reg uart_TxD,
    output reg spi_ncs, spi_mosi, spi_miso, spi_sclk
);

reg [31:0] rom_data;
rom r(.clock(clk), .address(addr[11:0]), .q(rom_data), .data(data), .wren(~cs0_ & ~we_));
rom_tristate r_ts(.cs_(cs0_), .oe_(oe_), .data_in(rom_data), .data_out(data));

uart_mmio #(2604) uart(.clk(clk), .rst_(rst), .data(data), .addr(addr[7:0]), .cs_(cs3_), .oe_(oe_), .we_(we_), .TxD(uart_TxD));

vga vga(.clk(clk), .data(data), .addr(addr[11:0]), .cs_(cs4_), .oe_(oe_), .we_(we_), .r(vga_r), .g(vga_g), .b(vga_b), .hs(vga_hs), .vs(vga_vs));

spi spi(.clk(clk), .data(data), .rst_(rst), .addr(addr[7:0]), .cs_(cs5_), .oe_(oe_), .we_(we_), .spi_ncs(spi_ncs), .spi_mosi(spi_mosi), .spi_miso(spi_miso), .spi_sclk(spi_sclk));

timer timer(.clk(clk), .data(data), .rst_(rst), .addr(addr[7:0]), .cs_(cs6_), .oe_(oe_), .we_(we_), .interrupt(irpts[0]));

irq_ctrl irq(.clk(clk), .rst_(rst), .data(data), .addr(addr[7:0]), .cs_(cs7_), .oe_(oe_), .we_(we_), .irpts(irpts), .cpu_int(cpu_int), .cpu_int_ack(cpu_int_ack));

endmodule

module booth_multiplier(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   multiplicand,
    input       [7:0]   multiplier  ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [15:0]  product
);

reg [7:0] a_reg;
reg [7:0] s_reg;
reg [3:0] count;
reg [2:0] state;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        a_reg <= 8'b0;
        s_reg <= {multiplier, 1'b0};
        count <= 4'b0;
        state <= 3'b000;
        valid_b <= 1'b0;
        product <= 16'b0;
        ready_a <= 1'b0;
    end else begin
        case (state)
            3'b000: begin
                if (ready_b) begin
                    a_reg <= multiplicand;
                    state <= 3'b001;
                end
            end
            3'b001: begin
                s_reg <= {multiplier, 1'b0};
                state <= 3'b010;
            end
            3'b010: begin
                if (count == 4'b1000) begin
                    state <= 3'b011;
                end else begin
                    if (s_reg[1:0] == 2'b01) begin
                        a_reg <= a_reg + multiplicand;
                    end else if (s_reg[1:0] == 2'b10) begin
                        a_reg <= a_reg - multiplicand;
                    end
                    s_reg <= {s_reg[6:0], s_reg[7]};
                    count <= count + 1;
                end
            end
            3'b011: begin
                product <= {a_reg, s_reg[7]};
                valid_b <= 1'b1;
                state <= 3'b100;
            end
            3'b100: begin
                if (ready_b) begin
                    valid_b <= 1'b0;
                    ready_a <= 1'b1;
                    state <= 3'b101;
                end
            end
            3'b101: begin
                if (~ready_b) begin
                    ready_a <= 1'b0;
                    state <= 3'b000;
                end
            end
        endcase
    end
end

endmodule

module WDT (
  input clk, rst,
  output wdt
);

  parameter t = 10; // timeout period in clock cycles

  reg [31:0] counter;

  always @(posedge clk) begin
    if (rst) begin
      counter <= 0;
    end
    else begin
      counter <= counter + 1;
    end
  end

  assign wdt = (counter >= t) ? 1'b1 : 1'b0;

endmodule

module button_counter (
  input clk,
  input button,
  output reg [2:0] count
);

reg [1:0] state;

always @(posedge clk) begin
  if (button) begin
    count <= count + 1;
    case (state)
      0: state <= 1;
      1: state <= 2;
      2: state <= 3;
      3: state <= 0;
    endcase
  end else begin
    state <= state;
  end
end

endmodule

module fir_filter(clk, new_data_rdy, output_data_ready, din, dout);

    parameter WIDTH = 16;
    parameter COEF0_c = 4;
    parameter COEF1_c = 42;
    parameter COEF2_c = 163;
    parameter COEF3_c = 255;
    parameter COEF4_c = 163;
    parameter COEF5_c = 42;
    parameter COEF6_c = 4;

    input clk;
    input new_data_rdy;
    input signed [WIDTH-1:0] din;
    output signed [28-1:0] dout;
    output output_data_ready;

    reg signed [WIDTH-1:0] n_delay_reg1;
    reg signed [WIDTH-1:0] n_delay_reg2;
    reg signed [WIDTH-1:0] n_delay_reg3;
    reg signed [WIDTH-1:0] n_delay_reg4;
    reg signed [WIDTH-1:0] n_delay_reg5;
    reg signed [WIDTH-1:0] n_delay_reg6;
    reg output_data_ready;

    always @(posedge clk) begin
        if (new_data_rdy == 1'b1) begin
            n_delay_reg1 <= din;
            n_delay_reg2 <= n_delay_reg1;
            n_delay_reg3 <= n_delay_reg2;
            n_delay_reg4 <= n_delay_reg3;
            n_delay_reg5 <= n_delay_reg4;
            n_delay_reg6 <= n_delay_reg5;

            output_data_ready <= 1'b1;
            dout <= (din * COEF0_c) + 
                    (n_delay_reg1 * COEF1_c) + 
                    (n_delay_reg2 * COEF2_c) + 
                    (n_delay_reg3 * COEF3_c) + 
                    (n_delay_reg4 * COEF4_c) + 
                    (n_delay_reg5 * COEF5_c) + 
                    (n_delay_reg6 * COEF6_c);
        end else begin
            output_data_ready <= 1'b0;
        end
    end
endmodule

module flip_flop_with_control (
    input CLK,
    input D,
    input RESET_B,
    input SET_B,
    input CTRL,
    output reg Q,
    output reg Q_N
);

    always @(posedge CLK, negedge CTRL) begin
        if (CTRL) begin
            Q <= D;
            Q_N <= ~D;
        end else begin
            Q <= Q;
            Q_N <= Q_N;
        end
    end

    always @(posedge CLK, negedge RESET_B, negedge SET_B) begin
        if (!RESET_B) begin
            Q <= 1'b0;
            Q_N <= 1'b1;
        end else if (!SET_B) begin
            Q <= 1'b1;
            Q_N <= 1'b0;
        end else begin
            Q <= Q;
            Q_N <= Q_N;
        end
    end

endmodule

