module d_flip_flop (
    input clk,    // Clocks are used in sequential circuits
    input d,
    output reg q );

    // Implementing the D flip-flop using NAND gates
    wire n1, n2, n3, n4;

    assign n1 = ~(d & clk);
    assign n2 = ~(n1 & q);
    assign n3 = ~(n2 & clk);
    assign n4 = ~(n3 & ~q);

    always @(posedge clk) begin
        q <= ~n4;
    end

endmodule

module parity (
  input [n-1:0] in,
  output par_out,
  output err
);

parameter n = 8; // number of input signals

wire [n-1:0] in_and_par; // input and parity bit
wire [n-1:0] in_xor_par; // input xor parity bit
wire [n-1:0] in_count; // count of 1's in input
wire par_count; // count of 1's in input plus parity bit

assign in_and_par = {in, par_out}; // concatenate input and parity bit
assign in_xor_par = in ^ par_out; // xor input and parity bit

// count number of 1's in input
genvar i;
generate
  for (i = 0; i < n; i = i + 1) begin : count_ones
    assign in_count[i] = in[i];
  end
endgenerate

// count number of 1's in input plus parity bit
assign par_count = in_xor_par[n-1];
generate
  for (i = 0; i < n-1; i = i + 1) begin : count_ones
    assign par_count = par_count + in_xor_par[i];
  end
endgenerate

// generate parity bit
assign par_out = ~par_count;

// check parity
assign err = par_count % 2;

endmodule

