wire [7:0] square;
wire [3:0] sum;

multiplier mult_inst (
    .a(in),
    .b(in),
    .p(square)
);

adder add_inst0 (
    .a(square[3:0]),
    .b(square[7:4]),
    .s(sum[0])
);

adder add_inst1 (
    .a(square[4:1]),
    .b({1'b0, square[7:5]}),
    .s(sum[1])
);

adder add_inst2 (
    .a(square[5:2]),
    .b({2'b0, square[7:6]}),
    .s(sum[2])
);

adder add_inst3 (
    .a(square[6:3]),
    .b({3'b0, square[7]}),
    .s(sum[3])
);

assign q = sum;

endmodule

module barrel_shifter(
    input clk,
    input load,
    input [1:0] ena,
    input [99:0] data,
    output reg [99:0] q,
    output reg [99:0] rot_data);

    reg [99:0] shift_reg;

    always @(posedge clk) begin
        if (load) begin
            shift_reg <= data;
        end else if (ena == 2'b01) begin
            shift_reg <= {shift_reg[98:0], shift_reg[99]};
        end else if (ena == 2'b10) begin
            shift_reg <= {shift_reg[1:99], shift_reg[0]};
        end else if (ena == 2'b11) begin
            shift_reg <= {shift_reg[99], shift_reg[98:0], shift_reg[99]};
        end
    end

    assign q = shift_reg;
    assign rot_data = {shift_reg[99], shift_reg[98:0], shift_reg[99]};

endmodule

module xor_module(
    input [99:0] data,
    input [99:0] rot_data,
    output reg [99:0] xor_out);

    always @(*) begin
        xor_out = data ^ rot_data;
    end

endmodule

module top_module(
    input clk,
    input load,
    input [1:0] ena,
    input [99:0] data,
    output reg [99:0] q,
    output reg [99:0] xor_out);

    wire [99:0] rot_data;
    wire [99:0] xor_data;

    barrel_shifter shifter(
        .clk(clk),
        .load(load),
        .ena(ena),
        .data(data),
        .q(q),
        .rot_data(rot_data)
    );

    xor_module xor(
        .data(data),
        .rot_data(rot_data),
        .xor_out(xor_data)
    );

    always @(posedge clk) begin
        if (load) begin
            q <= data;
            xor_out <= 0;
        end else begin
            q <= shifter.q;
            xor_out <= xor_data;
        end
    end

endmodule

module i2c (reset, clock4x, data, load, idle, ack, scl, sda);

   input reset;
   input clock4x;
   input [7:0] data;
   input load;
   output ack;
   output idle;
   output scl;
   output sda;

   reg [7:0] ldata;
   reg ack, idle;
   reg scl;
   reg sdai;

   reg [7:0] state;

   assign sda = sdai ? 1'bZ : 1'b0;

   always @(posedge clock4x)
     if (reset)
       begin
	  state <= 8'h00;
	  ack <= 1'b0;
	  idle <= 1'b1;
       end
     else
       case (state)
	 8'h00: // idle
	   begin
	      scl <= 1'b1;
	      sdai <= 1'b1;
	      ack <= 1'b0;
	      idle <= 1'b1;
	      if (load)
		begin
		   ldata <= data;
		   ack <= 1'b1;
		   state <= 8'h01;
		end
	   end
	 8'h01: // Start
	   begin
	      ack <= 1'b0;
	      idle <= 1'b0;
	      sdai <= 1'b0;
	      state <= 8'h02;
	   end
	 8'h02:
	   begin
	      scl <= 1'b0;
	      state <= 8'h03;
	   end
	 8'h03: // Send bit 7
	   begin
	      ack <= 1'b0;
	      sdai <= ldata[7];
	      state <= 8'h04;
	   end
	 8'h04:
	   begin
	      scl <= 1'b1;
	      state <= 8'h05;
	   end
	 8'h05:
	   begin
	      state <= 8'h06;
	   end
	 8'h06:
	   begin
	      scl <= 1'b0;
	      state <= 8'h07;
	   end
	 8'h07:
	   begin
	      sdai <= ldata[6];
	      state <= 8'h08;
	   end
	 8'h08:
	   begin
	      scl <= 1'b1;
	      state <= 8'h09;
	   end
	 8'h09:
	   begin
	      state <= 8'h0A;
	   end
	 8'h0A:
	   begin
	      scl <= 1'b0;
	      state <= 8'h0B;
	   end
	 8'h0B:
	   begin
	      sdai <= ldata[5];
	      state <= 8'h0C;
	   end
	 8'h0C:
	   begin
	      scl <= 1'b1;
	      state <= 8'h0D;
	   end
	 8'h0D:
	   begin
	      state <= 8'h0E;
	   end
	 8'h0E:
	   begin
	      scl <= 1'b0;
	      state <= 8'h0F;
	   end
	 8'h0F:
	   begin
	      sdai <= ldata[4];
	      state <= 8'h10;
	   end
	 8'h10:
	   begin
	      scl <= 1'b1;
	      state <= 8'h11;
	   end
	 8'h11:
	   begin
	      state <= 8'h12;
	   end
	 8'h12:
	   begin
	      scl <= 1'b0;
	      state <= 8'h13;
	   end
	 8'h13: // Acknowledge bit
	   begin
	      state <= 8'h14;
	   end
	 8'h14:
	   begin
	      scl <= 1'b1;
	      state <= 8'h15;
	   end
	 8'h15:
	   begin
	      state <= 8'h16;
	   end
	 8'h16:
	   begin
	      scl <= 1'b0;
	      if (sda)
		begin
		   ack <= 1'b1;
		   state <= 8'h17;
		end
	      else
		begin
		   ack <= 1'b0;
		   state <= 8'h00;
		end
	   end
	 8'h17:
	   begin
	      sdai <= 1'b0;
	      state <= 8'h18;
	   end
	 8'h18:
	   begin
	      scl <= 1'b1;
	      state <= 8'h19;
	   end
	 8'h19:
	   begin
	      sdai <= 1'b1;
	      state <= 8'h00;
	   end
       endcase

endmodule

module async_fifo
#(
parameter D_WIDTH = 8
)
(
    input wr_clk,
    input rd_clk,
    input [D_WIDTH-1:0] i_data,
    output [D_WIDTH-1:0] o_data,
    input i_push,
    input i_pop,
    output o_full,
    output o_empty
);

reg [2:0] wr_pointer = 3'b000;
reg [2:0] rd_pointer = 3'b000;
reg [2:0] wr_pointer_d1 = 3'b000;
reg [2:0] rd_pointer_d1 = 3'b000;
reg [2:0] wr_pointer_d2 = 3'b000;
reg [2:0] rd_pointer_d2 = 3'b000;

wire [2:0] wr_pointer_rd;
wire [2:0] rd_pointer_wr;

reg [D_WIDTH-1:0] data [0:3];

assign o_data = data[rd_pointer[1:0]];
assign o_full = {~wr_pointer[2], wr_pointer[1:0]} == rd_pointer_wr;
assign o_empty = wr_pointer_rd == rd_pointer;

always @(posedge wr_clk) begin
    if (i_push && !o_full) begin
        wr_pointer <= wr_pointer + 1;
        data[wr_pointer[1:0]] <= i_data;
    end
end

always @(posedge rd_clk) begin
    if (i_pop && !o_empty) begin
        rd_pointer <= rd_pointer + 1;
    end
end

always @(posedge wr_clk) begin
    rd_pointer_d1 <= gray3(rd_pointer);
    rd_pointer_d2 <= rd_pointer_d1;
end

always @(posedge rd_clk) begin
    wr_pointer_d1 <= gray3(wr_pointer);
    wr_pointer_d2 <= wr_pointer_d1;
end

assign wr_pointer_rd = ungray3(wr_pointer_d2);
assign rd_pointer_wr = ungray3(rd_pointer_d2);

function [2:0] gray3;
    input [2:0] binary;
    begin
        case(binary)
            3'b000 : gray3 = 3'b000;
            3'b001 : gray3 = 3'b001;
            3'b010 : gray3 = 3'b011;
            3'b011 : gray3 = 3'b010;
            3'b100 : gray3 = 3'b110;
            3'b101 : gray3 = 3'b111;
            3'b110 : gray3 = 3'b101;
            3'b111 : gray3 = 3'b100;
        endcase
    end
endfunction

function [2:0] ungray3;
    input [2:0] gray;
    begin
        case(gray)
            3'b000 : ungray3 = 3'b000;
            3'b001 : ungray3 = 3'b001;
            3'b011 : ungray3 = 3'b010;
            3'b010 : ungray3 = 3'b011;
            3'b110 : ungray3 = 3'b100;
            3'b111 : ungray3 = 3'b101;
            3'b101 : ungray3 = 3'b110;
            3'b100 : ungray3 = 3'b111;
        endcase
    end
endfunction

endmodule

module video_display_controller(clk, pixclk,
              txtrow, txtcol,
              chrrow, chrcol,
              blank, hsync, vsync, blink);
    input clk;
    output pixclk;
    output [4:0] txtrow;
    output [6:0] txtcol;
    output [3:0] chrrow;
    output [2:0] chrcol;
    output blank;
    output hsync;
    output vsync;
    output reg blink;

    reg pclk;
    reg [9:0] hcnt;
    reg hblank, hsynch;
    reg [9:0] vcnt;
    reg vblank, vsynch;
    reg [5:0] bcnt;

    // Pixel clock
    always @(posedge clk) begin
        pclk <= ~pclk;
    end
    assign pixclk = pclk;

    // Horizontal counter
    always @(posedge clk) begin
        if (pclk == 1) begin
            if (hcnt == 10'd799) begin
                hcnt <= 10'd0;
                hblank <= 1;
            end else begin
                hcnt <= hcnt + 1;
            end
            if (hcnt == 10'd639) begin
                hblank <= 0;
            end
            if (hcnt == 10'd655) begin
                hsynch <= 0;
            end
            if (hcnt == 10'd751) begin
                hsynch <= 1;
            end
        end
    end

    // Vertical counter
    always @(posedge clk) begin
        if (pclk == 1 && hcnt == 10'd799) begin
            if (vcnt == 10'd524) begin
                vcnt <= 10'd0;
                vblank <= 1;
            end else begin
                vcnt <= vcnt + 1;
            end
            if (vcnt == 10'd479) begin
                vblank <= 0;
            end
            if (vcnt == 10'd489) begin
                vsynch <= 0;
            end
            if (vcnt == 10'd491) begin
                vsynch <= 1;
            end
        end
    end

    // Blink counter
    always @(posedge clk) begin
        if (pclk == 1 && hcnt == 10'd799 && vcnt == 10'd524) begin
            if (bcnt == 6'd59) begin
                bcnt <= 6'd0;
                blink <= ~blink;
            end else begin
                bcnt <= bcnt + 1;
            end
        end
    end

    // Text and character positions
    assign txtrow[4:0] = vcnt[8:4];
    assign txtcol[6:0] = hcnt[9:3];
    assign chrrow[3:0] = vcnt[3:0];
    assign chrcol[2:0] = hcnt[2:0];

    // Blanking and sync signals
    assign blank = hblank & vblank;
    assign hsync = hsynch;
    assign vsync = vsynch;

endmodule

module msg_in(
  input clk,
  input rst,
  input start,
  input [31:0] msg_in,
  output reg done,
  output reg [511:0] msg_out
);

  reg [9:0] count;

  always @(posedge clk or negedge rst) begin
    if (!rst) begin
      count <= 0;
      done <= 0;
      msg_out <= 0;
    end else begin
      if (start) begin
        if (count < 17) begin
          count <= count + 1;
        end else begin
          done <= 1;
        end
      end
    end
  end

  always @(count) begin
    case (count)
      1: msg_out[511:480] = msg_in;
      2: msg_out[479:448] = msg_in;
      3: msg_out[447:416] = msg_in;
      4: msg_out[415:384] = msg_in;
      5: msg_out[383:352] = msg_in;
      6: msg_out[351:320] = msg_in;
      7: msg_out[319:288] = msg_in;
      8: msg_out[287:256] = msg_in;
      9: msg_out[255:224] = msg_in;
      10: msg_out[223:192] = msg_in;
      11: msg_out[191:160] = msg_in;
      12: msg_out[159:128] = msg_in;
      13: msg_out[127:96] = msg_in;
      14: msg_out[95:64] = msg_in;
      15: msg_out[63:32] = msg_in;
      16: msg_out[31:0] = msg_in;
      default: msg_out <= msg_out;
    endcase
  end

endmodule

module adder_subtractor(
    input [3:0] A,
    input [3:0] B,
    input ctrl,
    output reg [3:0] S,
    output reg V
);

    always @* begin
        if (ctrl == 1'b0) begin
            S = A + B;
            if (S > 4'b1111) begin
                V = 1'b1;
            end else begin
                V = 1'b0;
            end
        end else begin
            S = A - B;
            if (S < 4'b0000) begin
                V = 1'b1;
            end else begin
                V = 1'b0;
            end
        end
    end

endmodule

module testbench;

    reg [3:0] A;
    reg [3:0] B;
    reg ctrl;
    wire [3:0] S;
    wire V;

    adder_subtractor dut(
        .A(A),
        .B(B),
        .ctrl(ctrl),
        .S(S),
