endmodule

module top_module(
    input [15:0] a,
    input [15:0] b,
    input enable_mult,
    output reg [31:0] product
);

    wire [31:0] temp_product;
    wire [15:0] a_and_b;
    wire [15:0] a_and_b_complement;

    add16 adder1(.a(a), .b(~b), .sum(a_and_b_complement));
    add16 adder2(.a(a_and_b), .b(a_and_b_complement), .sum(temp_product));
    assign a_and_b = enable_mult ? (a & b) : 16'b0;

    always @ (posedge enable_mult) begin
        product <= temp_product;
    end

endmodule

module shift_register(
    input clk,
    input areset,  // async active-high reset to zero
    input load,
    input ena,
    input [3:0] data,
    output reg [3:0] q
);

reg [3:0] q_reg1, q_reg2, q_reg3, q_reg4;

always @(posedge clk or posedge areset) begin
    if (areset) begin
        q_reg1 <= 4'b0;
        q_reg2 <= 4'b0;
        q_reg3 <= 4'b0;
        q_reg4 <= 4'b0;
    end
    else begin
        q_reg1 <= q;
        q_reg2 <= q_reg1;
        q_reg3 <= q_reg2;
        q_reg4 <= q_reg3;
    end
end

reg [1:0] shift_amt;
reg [3:0] shifted_data;

always @(*) begin
    case (shift_amt)
        2'b00: shifted_data = q_reg1;
        2'b01: shifted_data = {q_reg1[0], q_reg2[0:2]};
        2'b10: shifted_data = {q_reg1[0], q_reg2[0], q_reg3[0:1]};
        2'b11: shifted_data = {q_reg1[0], q_reg2[0], q_reg3[0], q_reg4[0]};
    endcase
end

always @(posedge clk or posedge areset) begin
    if (areset) begin
        q <= 4'b0;
        shift_amt <= 2'b00;
    end
    else begin
        if (load) begin
            q <= data;
            shift_amt <= 2'b00;
        end
        else if (ena) begin
            shift_amt <= shift_amt + 1;
            q <= shifted_data;
        end
    end
end

endmodule

module four_bit_multiplier (
  input [3:0] x,
  input [3:0] y,
  output [7:0] product
);

wire [7:0] temp; // temporary 8-bit variable for intermediate calculations

assign temp[0] = x[0] & y; // calculate the first bit of the product
assign temp[1] = x[1] & y;
assign temp[2] = x[2] & y;
assign temp[3] = x[3] & y;

assign temp[4] = {4'b0, x} & {4'b0, y}; // calculate the second byte of the product
assign temp[5] = {3'b0, x} & {5'b0, y};
assign temp[6] = {2'b0, x} & {6'b0, y};
assign temp[7] = {1'b0, x} & {7'b0, y};

assign product = temp; // assign the final product to the output

endmodule

module spi_decoder(
    input spi_clk,
    input nreset,
    input spi_write,
    input [5:0] spi_addr,
    input [7:0] spi_wdata,
    input [31:0] packet_in[31:0],
    output config_write,
    output status_write,
    output user_write,
    output wait_out,
    output write_in,
    output [1:0] datamode_in,
    output [4:0] ctrlmode_in,
    output [31:0] dstaddr_in,
    output [31:0] srcaddr_in,
    output [31:0] data_in,
    output spi_en,
    output irq_en,
    output cpol,
    output cpha,
    output lsbfirst,
    output valid,
    output [7:0] user_regs[31:0],
    output [7:0] spi_status,
    output [63:0] core_data,
    output [63:0] core_regs,
    output [255:0] spi_regs,
    output [7:0] spi_rdata
);

//#####################################
//# SPI DECODE
//#####################################

assign config_write = spi_write & (spi_addr[5:0]==6'h3c);
assign status_write = spi_write & (spi_addr[5:0]==6'h38);
assign user_write = spi_write & (spi_addr[5]);

//#####################################
//# CORE DECODE
//#####################################

assign wait_out = 1'b0;

// Instantiate packet2emesh module
packet2emesh #(
    .AW(32),
    .PW(32)
) pe2 (
    // Outputs
    .write_in(write_in),
    .datamode_in(datamode_in),
    .ctrlmode_in(ctrlmode_in),
    .dstaddr_in(dstaddr_in),
    .srcaddr_in(srcaddr_in),
    .data_in(data_in),
    // Inputs
    .packet_in(packet_in)
);

// Concatenate source address and data for core_data output
assign core_data[63:0] = {srcaddr_in, data_in};

//#####################################
//# CONFIG [0]
//#####################################

reg [7:0] spi_config = 8'b0;

always @ (negedge spi_clk or negedge nreset) begin
    if (!nreset) begin
        spi_config <= 8'b0;
    end else if (config_write) begin
        spi_config <= spi_wdata;
    end
end

assign spi_en = ~spi_config[0];
assign irq_en = spi_config[1];
assign cpol = spi_config[2];
assign cpha = spi_config[3];
assign lsbfirst = spi_config[4];
assign valid = spi_config[5];

//#####################################
//# USER SPACE REGISTERS
//#####################################

reg [7:0] user_regs [31:0];

always @ (negedge spi_clk) begin
    if (user_write) begin
        user_regs[spi_addr[4:0]] <= spi_wdata;
    end
end

//#####################################
//# STATUS [1]
//#####################################

reg [7:0] spi_status = 8'b0;

always @ (posedge spi_clk) begin
    if (access_out) begin
        spi_status <= 8'b0;
    end else if (access_in) begin
        spi_status <= 8'd1;
    end
end

//#####################################
//# RX DATA FOR FETCH
//#####################################

reg [63:0] core_regs = 64'b0;

always @ (posedge spi_clk) begin
    if (access_in) begin
        core_regs <= core_data;
    end
end

//#####################################
//# REGISTER VECTOR (FOR FLEXIBILITY)
//#####################################

reg [255:0] spi_regs = 256'b0;

integer i;

always @* begin
    spi_regs[7:0] = spi_config;
    spi_regs[15:8] = spi_status;
    spi_regs[127:16] = 112'b0;
    spi_regs[191:128] = core_regs;
    spi_regs[255:192] = 64'b0;
    for (i = 0; i < 32; i = i + 1) begin
        spi_regs[256+8*i+:8] = user_regs[i];
    end
end

//#####################################
//# READBACK (TO SPI)
//#####################################

assign spi_rdata = spi_regs[8*spi_addr[5:0]+:8];

endmodule

module adder_4bit (
    input [3:0] A,
    input [3:0] B,
    input CIN,
    output [3:0] S,
    output COUT
);

reg [3:0] sum1, sum2, sum3;
reg [3:0] carry1, carry2, carry3;

assign S = sum3;
assign COUT = carry3;

// Pipeline stage 1
always @(*) begin
    sum1 = A + B;
    carry1 = A[3] & B[3];
end

// Pipeline stage 2
always @(*) begin
    sum2 = sum1 + CIN;
    carry2 = sum1[3] & CIN;
end

// Pipeline stage 3
always @(*) begin
    sum3 = sum2 + carry1;
    carry3 = carry2 | (sum2[3] & carry1);
end

endmodule

module ripple_up_down_adder (
    input clk,
    input reset,      // Synchronous active-high reset
    input [3:0] A,    // Input A to the adder
    input [3:0] B,    // Input B to the adder
    input Cin,        // Carry-in to the adder
    input Up,         // Up input to the counter
    input Down,       // Down input to the counter
    output [3:0] Q,   // Output of the counter
    output [3:0] Sum, // Output of the adder
    output Cout,      // Carry-out of the adder
    output [7:0] out  // Final output of the system
);

  // Define internal signals
  wire [3:0] adder_out;
  wire adder_cout;
  wire [3:0] counter_out;

  // Instantiate the ripple carry adder
  ripple_carry_adder adder (
    .A(A),
    .B(B),
    .Cin(Cin),
    .Sum(adder_out),
    .Cout(adder_cout)
  );

  // Instantiate the up-down counter
  up_down_counter counter (
    .clk(clk),
    .reset(reset),
    .Up(Up),
    .Down(Down),
    .Q(counter_out)
  );

  // Define the functional module that combines the adder and counter outputs
  assign out = {adder_out, counter_out};

  // Assign outputs
  assign Sum = adder_out;
  assign Cout = adder_cout;
  assign Q = counter_out;

endmodule

module HexDisplay(
    input mclk,
    input [15:0] num,
    output reg [7:0] display,
    output reg [3:0] an
);

    reg [3:0] tmp;
    reg [15:0] counter;

    parameter [15:0] MAX_COUNTER = 16'D5_0000;

    initial begin
        an = 4'B0111;
        counter = 0;
    end

    always@(posedge mclk) begin
        counter = counter + 1;
        if (counter == MAX_COUNTER) begin
            an = (an >> 1) + 4'B1000;
            if (an == 4'B1111) begin
                an = 4'B0111;
            end
            counter = 0;
            case(an)
                4'B0111: tmp = num[15:12];
                4'B1011: tmp = num[11:8];
                4'B1101: tmp = num[7:4];
                4'B1110: tmp = num[3:0];
            endcase
            case(tmp)
                4'H0: display = 8'B0000_0011;
                4'H1: display = 8'B1001_1111;
                4'H2: display = 8'B0010_0101;
                4'H3: display = 8'B0000_1101;
                4'H4: display = 8'B1001_1001;
                4'H5: display = 8'B0100_1001;
                4'H6: display = 8'B0100_0001;
                4'H7: display = 8'B0001_1111;
                4'H8: display = 8'B0000_0001;
                4'H9: display = 8'B0000_1001;
                4'Ha: display = 8'B0001_0001;
                4'Hb: display = 8'B1100_0001;
                4'Hc: display = 8'B0110_0011;
                4'Hd: display = 8'B1000_0101;
                4'He: display = 8'B0110_0001;
                4'Hf: display = 8'B0111_0001;
            endcase
        end
    end
endmodule

