module top_module (
  input clk,
  input reset,
  input [7:0] instruction,
  input [2:0] stage,
  input [4:0] rs1,
  input [4:0] rs2,
  input [4:0] rd,
  input [31:0] data1,
  input [31:0] data2,
  input wire [15:0] in,
  output wire [7:0] out_hi,
  output wire [7:0] out_lo,
  output wire [7:0] and_result
);

  // Register file
  reg [31:0] reg_file [0:7];

  // Pipeline registers
  reg [7:0] pc_reg;
  reg [7:0] pc_next;
  reg [7:0] instruction_reg;
  reg [31:0] data1_reg;
  reg [31:0] data2_reg;
  reg [4:0] rs1_reg;
  reg [4:0] rs2_reg;
  reg [4:0] rd_reg;
  reg [2:0] stage_reg;
  reg [7:0] alu_result_reg;

  // Control signals
  wire reg_write_enable;
  wire alu_op;
  wire alu_src;
  wire mem_read_enable;
  wire mem_write_enable;
  wire mem_to_reg;

  // Binary splitter signals
  wire [7:0] out_hi_wire;
  wire [7:0] out_lo_wire;

  // AND module signals
  wire [7:0] and_result_wire;

  // Instantiate pipeline stages
  decode_stage decode_stage_inst(
    .instruction(instruction_reg),
    .rs1(rs1_reg),
    .rs2(rs2_reg),
    .rd(rd_reg),
    .reg_write_enable(reg_write_enable),
    .alu_op(alu_op),
    .alu_src(alu_src),
    .mem_read_enable(mem_read_enable),
    .mem_write_enable(mem_write_enable),
    .mem_to_reg(mem_to_reg),
    .pc_next(pc_next),
    .stage(stage_reg)
  );

  execute_stage execute_stage_inst(
    .rs1_data(data1_reg),
    .rs2_data(data2_reg),
    .imm(instruction_reg[7:0]),
    .alu_op(alu_op),
    .alu_src(alu_src),
    .alu_result(alu_result_reg),
    .mem_read_enable(mem_read_enable),
    .mem_write_enable(mem_write_enable),
    .mem_data(in),
    .mem_addr(alu_result_reg),
    .stage(stage_reg)
  );

  write_back_stage write_back_stage_inst(
    .rd(rd_reg),
    .mem_to_reg(mem_to_reg),
    .mem_data(alu_result_reg),
    .reg_file(reg_file),
    .reg_write_enable(reg_write_enable),
    .stage(stage_reg)
  );

  // Instantiate binary splitter
  binary_splitter binary_splitter_inst(
    .in(in),
    .out_hi(out_hi_wire),
    .out_lo(out_lo_wire)
  );

  // Instantiate AND module
  and_module and_module_inst(
    .in1(alu_result_reg),
    .in2(out_lo_wire),
    .out(and_result_wire)
  );

  // Combinational logic for control signals
  assign reg_write_enable = (stage_reg == 2) ? 1'b1 : 1'b0;
  assign alu_op = instruction_reg[7];
  assign alu_src = instruction_reg[6];
  assign mem_read_enable = (instruction_reg[5] == 1'b1) ? 1'b1 : 1'b0;
  assign mem_write_enable = (instruction_reg[4] == 1'b1) ? 1'b1 : 1'b0;
  assign mem_to_reg = (stage_reg == 2 && instruction_reg[3] == 1'b1) ? 1'b1 : 1'b0;

  // Combinational logic for pipeline registers
  always @ (posedge clk) begin
    if (reset) begin
      pc_reg <= 8'b0;
      instruction_reg <= 8'b0;
      data1_reg <= 32'b0;
      data2_reg <= 32'b0;
      rs1_reg <= 5'b0;
      rs2_reg <= 5'b0;
      rd_reg <= 5'b0;
      stage_reg <= 3'b000;
      alu_result_reg <= 8'b0;
    end else begin
      pc_reg <= pc_next;
      instruction_reg <= instruction;
      data1_reg <= reg_file[rs1_reg];
      data2_reg <= reg_file[rs2_reg];
      rs1_reg <= rs1;
      rs2_reg <= rs2;
      rd_reg <= rd;
      stage_reg <= stage;
      alu_result_reg <= alu_result_wire;
    end
  end

  // Combinational logic for register file
  always @ (posedge clk) begin
    if (reset) begin
      reg_file <= {32{8'b0}};
    end else begin
      if (reg_write_enable) begin
        reg_file[rd_reg] <= (mem_to_reg) ? in : alu_result_reg;
      end
    end
  end

  // Connect binary splitter outputs to output ports
  assign out_hi = out_hi_wire;
  assign out_lo = out_lo_wire;

  // Connect AND module output to output port
  assign and_result = and_result_wire;

endmodule

