    input  A2  ;
    input  B1  ;
    input  C1  ;
    input  D1  ;
    input  VPWR;
    input  VGND;
    input  VPB ;
    input  VNB ;

    wire condition1, condition2, condition3, condition4, condition5, condition6;

    and gate1(condition1, A1, A2);
    nand gate2(condition2, B1, C1);
    and gate3(condition3, D1, VPWR);
    not gate4(condition4, VGND);
    and gate5(condition5, VPB, VNB);
    and gate6(Y, condition1, condition2, condition3, condition4, condition5);

