module top_module (
    input [3:0] A,
    input [3:0] B,
    output [15:0] O
);

    // Magnitude Comparator
    wire EQ, GT, LT;
    assign EQ = (A == B);
    assign GT = (A > B);
    assign LT = (A < B);

    // Priority Encoder
    wire [3:0] I;
    assign I = GT | LT;
    wire [15:0] P;
    priority_encoder_16 priority_encoder_16_inst (
        .I(I),
        .O(P)
    );

    // Functional Module
    wire [3:0] highest_value;
    assign highest_value = (GT) ? A : B;

    // Output
    assign O = (highest_value == A) ? 16'b0000000000000001 :
               (highest_value == B) ? 16'b0000000000000010 :
               P;

endmodule

module priority_encoder_16 (
    input [15:0] I,
    output [15:0] O
);

    wire [15:0] temp;
    assign temp = (I == 16'h0000) ? 16'h0000 :
                  (I[15]) ? 16'h8000 :
                  (I[14]) ? {16'hC000, temp[13:0]} :
                  (I[13]) ? {16'hE000, temp[12:0]} :
                  (I[12]) ? {16'hF000, temp[11:0]} :
                  (I[11]) ? {16'hF800, temp[10:0]} :
                  (I[10]) ? {16'hFC00, temp[9:0]} :
                  (I[9]) ? {16'hFE00, temp[8:0]} :
                  (I[8]) ? {16'hFF00, temp[7:0]} :
                  (I[7]) ? {16'hFF80, temp[6:0]} :
                  (I[6]) ? {16'hFFC0, temp[5:0]} :
                  (I[5]) ? {16'hFFE0, temp[4:0]} :
                  (I[4]) ? {16'hFFF0, temp[3:0]} :
                  (I[3]) ? {16'hFFF8, temp[2:0]} :
                  (I[2]) ? {16'hFFFC, temp[1:0]} :
                  (I[1]) ? {16'hFFFE, temp[0]} :
                  16'hFFFF;
    assign O = temp;

endmodule

module uart_transmitter(
    input clock,
    input reset,
    input [7:0] tx_data,
    input new_tx_data,
    input ce_16,
    output reg ser_out,
    output reg ce_1
);

reg [3:0] count16;
reg [3:0] bit_count;
reg [8:0] data_buf;
reg tx_busy;

always @(posedge clock) begin
    if (reset) begin
        tx_busy <= 1'b0;
        bit_count <= 4'h0;
        data_buf <= 9'b0;
        count16 <= 4'b0;
        ser_out <= 1'b1;
        ce_1 <= 1'b0;
    end
    else begin
        if (~tx_busy & new_tx_data) begin
            tx_busy <= 1'b1;
            data_buf <= {tx_data, 1'b0};
        end
        else if (tx_busy & ce_1) begin
            data_buf <= {1'b1, data_buf[8:1]};
            bit_count <= bit_count + 4'h1;
            if (bit_count == 4'h9) begin
                tx_busy <= 1'b0;
                bit_count <= 4'h0;
            end
        end
        if (tx_busy & ce_16) begin
            count16 <= count16 + 4'b1;
            if (count16 == 4'b1111) begin
                ce_1 <= 1'b1;
                count16 <= 4'b0;
            end
        end
        else begin
            count16 <= 4'b0;
            ce_1 <= 1'b0;
        end
        if (tx_busy) begin
            ser_out <= data_buf[0];
        end
        else begin
            ser_out <= 1'b1;
        end
    end
end

endmodule

