module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [255:0] in, // Input for the 256-to-1 multiplexer
    input [7:0] sel,  // Selection signal for the 256-to-1 multiplexer
    output [3:0] q,   // Output from the 4-bit binary counter
    output [3:0] out  // Final output from the functional module
);

    // 256-to-1 multiplexer
    wire [7:0] mux_sel;
    assign mux_sel = sel;
    wire [7:0] mux_out;
    assign mux_out = in[mux_sel];

    // 4-bit binary counter
    reg [3:0] counter;
    always @(posedge clk) begin
        if (reset) begin
            counter <= 4'b0000;
        end else begin
            counter <= counter + 1;
        end
    end
    assign q = counter;

    // Functional module
    assign out = mux_out & q;

endmodule

module multi_io_module (
  input [3:0] input_a,
  input [3:0] input_b,
  input input_c,
  input input_d,
  input input_e,
  input clk,
  output [3:0] output_a,
  output [3:0] output_b,
  output output_c,
  output output_d,
  output output_e
);

  wire add_sub = input_c ^ input_d;
  wire and_or = input_c & input_d;
  wire greater_than = (input_a >= input_b);
  wire less_than = (input_a < input_b);

  assign output_a = add_sub ? (greater_than ? input_a - input_b : input_a + input_b) : (and_or ? input_a & input_b : input_a | input_b);
  assign output_b = input_b;
  assign output_c = input_e ? ~input_c : ~input_d;
  assign output_d = greater_than;
  assign output_e = less_than;

endmodule

module binary_counter (
    input clk,
    input reset,
    input count_en,
    input [31:0] max_count,
    input [31:0] load_val,
    input load,
    input count_dir,
    output reg [31:0] count_out
);

always @(posedge clk or posedge reset) begin
    if (reset) begin
        count_out <= 0;
    end
    else if (load) begin
        count_out <= load_val;
    end
    else if (count_en) begin
        if (count_dir) begin
            if (count_out == max_count) begin
                count_out <= 0;
            end
            else begin
                count_out <= count_out + 1;
            end
        end
        else begin
            if (count_out == 0) begin
                count_out <= max_count;
            end
            else begin
                count_out <= count_out - 1;
            end
        end
    end
end

endmodule

module binary_counter_tb;

reg clk;
reg reset;
reg count_en;
reg [31:0] max_count;
reg [31:0] load_val;
reg load;
reg count_dir;
wire [31:0] count_out;

binary_counter dut(
    .clk(clk),
    .reset(reset),
    .count_en(count_en),
    .max_count(max_count),
    .load_val(load_val),
    .load(load),
    .count_dir(count_dir),
    .count_out(count_out)
);

integer i;

initial begin
    clk = 0;
    reset = 1;
    count_en = 0;
    max_count = 15;
    load_val = 7;
    load = 0;
    count_dir = 1;

    #10 reset = 0;

    // Count up
    count_dir = 1;
    count_en = 1;

    for (i = 0; i < 20; i = i + 1) begin
        #5 clk = ~clk;
    end

    // Load value
    load = 1;
    load_val = 10;

    #5 load = 0;

    for (i = 0; i < 20; i = i + 1) begin
        #5 clk = ~clk;
    end

    // Count down
    count_dir = 0;

    for (i = 0; i < 20; i = i + 1) begin
        #5 clk = ~clk;
    end

    // Wrap around
    max_count = 5;

    for (i = 0; i < 20; i = i + 1) begin
        #5 clk = ~clk;
    end

    // Load value
    load = 1;
    load_val = 2;

    #5 load = 0;

    for (i = 0; i < 20; i = i + 1) begin
        #5 clk = ~clk;
    end

    // Count up
    count_dir = 1;

    for (i = 0; i < 20; i = i + 1) begin
        #5 clk = ~clk;
    end

    // Wrap around
    max_count = 2;

    for (i = 0; i < 20; i = i + 1) begin
        #5 clk = ~clk;
    end

    // Load value
    load = 1;
    load_val = 1;

    #5 load = 0;

    for (i = 0; i < 20; i = i + 1) begin
        #5 clk = ~clk;
    end

    $finish;
end

endmodule

module uart_transmitter (
  input clk,
  input rst,
  input [7:0] data_in,
  input [15:0] baud_rate,
  output tx
);

reg [15:0] baud_counter;
reg [9:0] shift_reg;
reg busy;

always @(posedge clk or posedge rst) begin
  if (rst) begin
    baud_counter <= 16'b0;
    shift_reg <= 10'b0;
    busy <= 1'b0;
    tx <= 1'b1;
  end else begin
    if (!busy) begin
      busy <= 1'b1;
      shift_reg <= {1'b1, data_in, 1'b0};
    end else begin
      if (baud_counter == baud_rate) begin
        baud_counter <= 16'b0;
        shift_reg <= {shift_reg[8:0], 1'b0};
        if (shift_reg == 10'b0) busy <= 1'b0;
      end else begin
        baud_counter <= baud_counter + 16'b1;
      end
    end
    tx <= shift_reg[0];
  end
end

endmodule

module uart_receiver (
  input clk,
  input rst,
  input rx,
  input [15:0] baud_rate,
  output [7:0] data_out
);

reg [15:0] baud_counter;
reg [9:0] shift_reg;
reg [2:0] state;

parameter IDLE = 3'b000;
parameter START = 3'b001;
parameter DATA = 3'b010;
parameter STOP = 3'b011;

always @(posedge clk or posedge rst) begin
  if (rst) begin
    baud_counter <= 16'b0;
    shift_reg <= 10'b0;
    state <= IDLE;
    data_out <= 8'b0;
  end else begin
    case (state)
      IDLE: begin
        if (!rx) begin
          state <= START;
          baud_counter <= baud_rate / 2;
        end
      end
      START: begin
        if (baud_counter == baud_rate) begin
          baud_counter <= 16'b0;
          if (!rx) state <= DATA;
          else state <= IDLE;
        end else begin
          baud_counter <= baud_counter + 16'b1;
        end
      end
      DATA: begin
        if (baud_counter == baud_rate) begin
          baud_counter <= 16'b0;
          shift_reg <= {shift_reg[8:0], rx};
          if (shift_reg[8]) state <= STOP;
        end else begin
          baud_counter <= baud_counter + 16'b1;
        end
      end
      STOP: begin
        if (baud_counter == baud_rate) begin
          baud_counter <= 16'b0;
          if (rx) begin
            state <= IDLE;
            data_out <= shift_reg[7:0];
          end else begin
            state <= START;
          end
        end else begin
          baud_counter <= baud_counter + 16'b1;
        end
      end
    endcase
  end
end

endmodule

