module shifter (
    // ----- Inputs -------
    clk_i,
    rst_i,
    stall_x,
    direction_x,
    sign_extend_x,
    operand_0_x,
    operand_1_x,
    // ----- Outputs -------
    shifter_result_m
    );

/////////////////////////////////////////////////////
// Inputs
/////////////////////////////////////////////////////

input clk_i;                                // Clock
input rst_i;                                // Reset
input stall_x;                              // Stall instruction in X stage
input direction_x;                          // Direction to shift
input sign_extend_x;                        // Whether shift is arithmetic (1'b1) or logical (1'b0)
input [31:0] operand_0_x;                   // Operand to shift
input [31:0] operand_1_x;                   // Operand that specifies how many bits to shift by

/////////////////////////////////////////////////////
// Outputs
/////////////////////////////////////////////////////

output [31:0] shifter_result_m;             // Result of shift

/////////////////////////////////////////////////////
// Internal nets and registers
/////////////////////////////////////////////////////

reg direction_m;
reg [31:0] left_shift_result;
reg [31:0] right_shift_result;
reg [31:0] left_shift_operand;
wire [31:0] right_shift_operand;
wire fill_value;
wire [31:0] right_shift_in;

integer shift_idx_0;
integer shift_idx_1;

/////////////////////////////////////////////////////
// Combinational Logic
/////////////////////////////////////////////////////

// Select operands - To perform a left shift, we reverse the bits and perform a right shift
always @(*)
begin
    for (shift_idx_0 = 0; shift_idx_0 < 32; shift_idx_0 = shift_idx_0 + 1)
        left_shift_operand[31-shift_idx_0] = operand_0_x[shift_idx_0];
end
assign right_shift_operand = direction_x == 0 ? operand_0_x : left_shift_operand;

// Determine fill value for right shift - Sign bit for arithmetic shift, or zero for logical shift
assign fill_value = (sign_extend_x == 1) && (direction_x == 1)
                      ? operand_0_x[31]
                      : 1'b0;

// Determine bits to shift in for right shift or rotate
assign right_shift_in = {32{fill_value}};

// Reverse bits to get left shift result
always @(*)
begin
    for (shift_idx_1 = 0; shift_idx_1 < 32; shift_idx_1 = shift_idx_1 + 1)
        left_shift_result[31-shift_idx_1] = right_shift_result[shift_idx_1];
end

// Select result
assign shifter_result_m = direction_m == 0 ? left_shift_result : right_shift_result;

/////////////////////////////////////////////////////
// Sequential Logic
/////////////////////////////////////////////////////

// Perform right shift
always @(posedge clk_i, posedge rst_i)
begin
    if (rst_i == 1)
    begin
        right_shift_result <= 32'd0;
        direction_m <= 0;
    end
    else
    begin
        if (stall_x == 0)
        begin
            right_shift_result <= {right_shift_in, right_shift_operand} >> operand_1_x;
            direction_m <= direction_x;
        end
    end
end

endmodule

module system_binary_counter
   (ram_full_fb_i_reg,
    Q,
    wr_pntr_gc_reg,
    rd_pntr_bin_reg,
    E,
    ext_spi_clk,
    AR);
  output ram_full_fb_i_reg;
  output [3:0]Q;
  output [3:0]wr_pntr_gc_reg;
  input [3:0]rd_pntr_bin_reg;
  input [0:0]E;
  input ext_spi_clk;
  input [0:0]AR;

  reg [3:0] Q;
  reg [3:0] wr_pntr_gc_reg;
  reg ram_full_fb_i_reg;
  wire [3:0] plusOp__2;
  wire [3:0] wr_pntr_plus2;
  wire [3:0] wr_pntr_plus3;

  always @(posedge ext_spi_clk) begin
    if (AR) begin
      Q <= 4'b0;
      wr_pntr_gc_reg <= 4'b0;
    end
    else if (E) begin
      Q <= Q + 1;
      wr_pntr_plus2 <= wr_pntr_gc_reg + 2;
      wr_pntr_plus3 <= {wr_pntr_plus2[3], wr_pntr_plus2[2:0]};
      wr_pntr_gc_reg <= (wr_pntr_gc_reg == 4'b1111) ? 4'b0 : wr_pntr_plus3;
      ram_full_fb_i_reg <= (rd_pntr_bin_reg == wr_pntr_gc_reg);
    end
  end

endmodule

