module digital_potentiometer (
  input [n-1:0] ctl,
  input [m-1:0] data,
  input we,
  input cs,
  output out
);

parameter n = 4; // number of control signals
parameter m = 8; // number of data signals
parameter r = 256; // total number of resistance levels

reg [7:0] mem [r-1:0]; // memory for storing resistance levels

reg [n-1:0] addr; // address for selecting resistance level
reg [7:0] res; // current resistance level

assign out = res; // output signal is the current resistance level

// write enable logic
always @ (posedge we) begin
  mem[addr] <= data;
end

// resistance level calculation
always @ (ctl or data) begin
  // calculate address based on control signals
  addr = {ctl[3:2], ctl[1:0]};

  // calculate resistance level based on data signals
  res = mem[addr] * data;
end

// chip select logic
always @ (cs) begin
  if (cs == 0) begin
    // digital potentiometer is enabled
    res = mem[addr] * data;
  end
  else begin
    // digital potentiometer is disabled
    res = 0;
  end
end

endmodule

module calculator(
    input clk,
    input rst,
    input [1:0] op,
    input signed [15:0] a,
    input signed [15:0] b,
    output reg valid,
    output reg error,
    output reg signed [15:0] result
);

reg signed [15:0] temp_result;

always @(posedge clk) begin
    if (rst) begin
        valid <= 0;
        error <= 0;
        result <= 0;
        temp_result <= 0;
    end else begin
        case(op)
            2'b00: temp_result <= a + b; // addition
            2'b01: temp_result <= a - b; // subtraction
            2'b10: temp_result <= a * b; // multiplication
            2'b11: begin                  // division
                if (b == 0) begin
                    error <= 1;
                end else begin
                    temp_result <= a / b;
                end
            end
        endcase

        result <= temp_result;
        valid <= 1;
        error <= 0;
    end
end

endmodule

