            4'b0010: dec = 3'd2;
            4'b0011: dec = 3'd3;
            4'b0100: dec = 3'd4;
            4'b0101: dec = 3'd5;
            4'b0110: dec = 3'd6;
            4'b0111: dec = 3'd7;
            4'b1000: dec = 3'd8;
            4'b1001: dec = 3'd9;
            default: dec = 3'd999;
        endcase
    end

endmodule

