module carry_select_adder(
    input [15:0] a,
    input [15:0] b,
    output [31:0] sum
);

    wire [15:0] s0, s1;
    wire c0, c1;

    adder_16bit adder0(
        .a(a[15:0]),
        .b(b[15:0]),
        .cin(1'b0),
        .sum(s0),
        .cout(c0)
    );

    adder_16bit adder1(
        .a(a[31:16]),
        .b(b[31:16]),
        .cin(1'b0),
        .sum(s1),
        .cout(c1)
    );

    assign sum = {s1, s0};

endmodule

module top_module(
    input [31:0] a,
    input [31:0] b,
    output [31:0] sum
);

    wire [15:0] a_low, b_low;
    wire [31:0] s;

    assign a_low = a[15:0];
    assign b_low = b[15:0];

    carry_select_adder adder(
        .a(a_low),
        .b(b_low),
        .sum(s)
    );

    adder_16bit final_adder(
        .a(s[15:0]),
        .b(s[31:16]),
        .cin(adder.c0 | adder.c1),
        .sum(sum),
        .cout()
    );

endmodule

module ac97_transceiver(
	input sys_clk,
	input sys_rst,
	input ac97_clk,
	input ac97_rst_n,

	/* to codec */
	input ac97_sin,
	output reg ac97_sout,
	output reg ac97_sync,

	/* to system, upstream */
	output up_stb,
	input up_ack,
	output up_sync,
	output up_data,

	/* to system, downstream */
	output down_ready,
	input down_stb,
	input down_sync,
	input down_data
);

/* Upstream */
reg ac97_sin_r;
always @(negedge ac97_clk) ac97_sin_r <= ac97_sin;

reg ac97_syncfb_r;
always @(negedge ac97_clk) ac97_syncfb_r <= ac97_sync;

wire up_empty;
ac97_asfifo #(
	.DATA_WIDTH(2),
	.ADDRESS_WIDTH(6)
) up_fifo (
	.Data_out({up_sync, up_data}),
	.Empty_out(up_empty),
	.ReadEn_in(up_ack),
	.RClk(sys_clk),

	.Data_in({ac97_syncfb_r, ac97_sin_r}),
	.Full_out(),
	.WriteEn_in(1'b1),
	.WClk(~ac97_clk),

	.Clear_in(sys_rst)
);
assign up_stb = ~up_empty;

/* Downstream */

/* Set SOUT and SYNC to 0 during RESET to avoid ATE/Test Mode */
wire ac97_sync_r;
always @(negedge ac97_rst_n, posedge ac97_clk) begin
	if(~ac97_rst_n)
		ac97_sync <= 1'b0;
	else
		ac97_sync <= ac97_sync_r;
end

wire ac97_sout_r;
always @(negedge ac97_rst_n, posedge ac97_clk) begin
	if(~ac97_rst_n)
		ac97_sout <= 1'b0;
	else
		ac97_sout <= ac97_sout_r;
end

wire down_full;
ac97_asfifo #(
	.DATA_WIDTH(2),
	.ADDRESS_WIDTH(6)
) down_fifo (
	.Data_out({ac97_sync_r, ac97_sout_r}),
	.Empty_out(),
	.ReadEn_in(1'b1),
	.RClk(ac97_clk),

	.Data_in({down_sync, down_data}),
	.Full_out(down_full),
	.WriteEn_in(down_stb),
	.WClk(sys_clk),

	.Clear_in(sys_rst)
);
assign down_ready = ~down_full;

endmodule

module tag_manager # (
  parameter TCQ           = 1,
  parameter RAM_ADDR_BITS = 5
)(
  input                     clk,
  input                     reset_n,

  input                     tag_mang_write_en,

  input [2:0]               tag_mang_tc_wr,             //[15:0]
  input [2:0]               tag_mang_attr_wr,           //[15:0]
  input [15:0]              tag_mang_requester_id_wr,   //[15:0]
  input [6:0]               tag_mang_lower_addr_wr,     //[6:0]
  input                     tag_mang_completer_func_wr, //[0:0]
  input [7:0]               tag_mang_tag_wr,            //[7:0]
  input [3:0]               tag_mang_first_be_wr,       //[2:0]

  input                     tag_mang_read_en,         

  output [2:0]              tag_mang_tc_rd,   //[15:0]
  output [2:0]              tag_mang_attr_rd,   //[15:0]
  output [15:0]             tag_mang_requester_id_rd,   //[15:0]
  output [6:0]              tag_mang_lower_addr_rd,     //[6:0]
  output                    tag_mang_completer_func_rd, //[0:0]
  output [7:0]              tag_mang_tag_rd,            //[7:0]
  output [3:0]              tag_mang_first_be_rd      //[2:0]
    );


  reg [RAM_ADDR_BITS-1:0] tag_mang_write_id;      
  reg [RAM_ADDR_BITS-1:0] tag_mang_read_id;        

  always @( posedge clk )
    if  ( !reset_n ) 
      tag_mang_write_id <= #TCQ 1;
    else if ( tag_mang_write_en ) 
      tag_mang_write_id <= #TCQ tag_mang_write_id + 1;   

  always @( posedge clk )
    if  ( !reset_n ) 
      tag_mang_read_id <= #TCQ 0;
    else if ( tag_mang_read_en ) 
      tag_mang_read_id <= #TCQ tag_mang_read_id + 1;


   localparam RAM_WIDTH = 42;

   (* RAM_STYLE="distributed" *)
   reg [RAM_WIDTH-1:0] tag_storage [(2**RAM_ADDR_BITS)-1:0];

   wire [RAM_WIDTH-1:0] completion_data;

   always @(posedge clk)
      if (tag_mang_write_en)
         tag_storage[tag_mang_write_id] <= #TCQ { tag_mang_attr_wr, tag_mang_tc_wr, tag_mang_requester_id_wr, tag_mang_lower_addr_wr, tag_mang_completer_func_wr, tag_mang_tag_wr, tag_mang_first_be_wr};

   assign completion_data = tag_storage[tag_mang_read_id];

   assign tag_mang_attr_rd           = completion_data[41:39];
   assign tag_mang_tc_rd             = completion_data[38:36];
   assign tag_mang_requester_id_rd   = completion_data[35:20];     //[15:0]
   assign tag_mang_lower_addr_rd     = completion_data[19:13];     //[6:0]
   assign tag_mang_completer_func_rd = completion_data[12];        //[0:0]
   assign tag_mang_tag_rd            = completion_data[11:4];      //[7:0]
   assign tag_mang_first_be_rd       = completion_data[3:0];       //[2:0]        

endmodule

module crc_module (
  input clk,
  input [31:0] data_in,
  output reg [15:0] crc_out
);

  reg [15:0] crc_reg = 16'hFFFF;
  reg [31:0] data_reg;
  reg [3:0] i;

  always @(posedge clk) begin
    data_reg <= data_in;
    crc_reg <= crc_reg ^ data_reg;
    for (i = 0; i < 32; i = i + 1) begin
      if (crc_reg[15] == 1) begin
        crc_reg <= {crc_reg[14:0], crc_reg[15]} ^ 16'hA001;
      end else begin
        crc_reg <= {crc_reg[14:0], crc_reg[15]};
      end
    end
    crc_out <= crc_reg;
  end

endmodule

module fp_adder (
    input [15:0] a,
    input [15:0] b,
    input add_sub,
    output reg [15:0] result,
    output isNaN,
    output isInf
);

    reg [15:0] exp_a, exp_b, frac_a, frac_b, frac_res;
    reg sign_a, sign_b, sign_res;
    reg [16:0] exp_res;
    reg [23:0] mant_res;
    reg overflow, underflow;
    reg isNaN_res, isInf_res;

    // Extracting sign, exponent and fraction of input a
    assign sign_a = a[15];
    assign exp_a = a[14:10];
    assign frac_a = a[9:0];

    // Extracting sign, exponent and fraction of input b
    assign sign_b = b[15];
    assign exp_b = b[14:10];
    assign frac_b = b[9:0];

    // Adding/subtracting exponents
    always @(*) begin
        if (add_sub == 1) begin
            exp_res = exp_a + exp_b;
        end else begin
            exp_res = exp_a - exp_b;
        end
    end

    // Adding/subtracting fractions
    always @(*) begin
        if (add_sub == 1) begin
            frac_res = frac_a + frac_b;
        end else begin
            frac_res = frac_a - frac_b;
        end
    end

    // Checking for overflow and underflow
    always @(*) begin
        if (exp_res > 30) begin
            overflow = 1;
        end else begin
            overflow = 0;
        end

        if (exp_res < 1) begin
            underflow = 1;
        end else begin
            underflow = 0;
        end
    end

    // Checking for NaN and infinity
    always @(*) begin
        if (exp_a == 31 && frac_a != 0) begin
            isNaN_res = 1;
        end else if (exp_a == 31 && frac_a == 0) begin
            isInf_res = 1;
        end else if (exp_b == 31 && frac_b != 0) begin
            isNaN_res = 1;
        end else if (exp_b == 31 && frac_b == 0) begin
            isInf_res = 1;
        end else if (exp_res == 31 && frac_res != 0) begin
            isNaN_res = 1;
        end else if (exp_res == 31 && frac_res == 0) begin
            isInf_res = 1;
        end else begin
            isNaN_res = 0;
            isInf_res = 0;
        end
    end

    // Normalizing the result
    always @(*) begin
        if (frac_res[10] == 1) begin
            exp_res = exp_res + 1;
        end
    end

    // Rounding the result
    always @(*) begin
        if (frac_res[9:8] == 2'b11) begin
            mant_res = frac_res[7:0] + 1;
        end else if (frac_res[9:8] == 2'b10) begin
            if (frac_res[7] == 1) begin
                mant_res = frac_res[7:0] + 1;
            end else begin
                mant_res = frac_res[7:0];
            end
        end else if (frac_res[9:8] == 2'b01) begin
            if (frac_res[7] == 1) begin
                mant_res = frac_res[7:0] + 1;
            end else begin
                mant_res = frac_res[7:0];
            end
        end else begin
            mant_res = frac_res[7:0];
        end
    end

    // Setting the sign of the result
    always @(*) begin
        if (add_sub == 1) begin
            if (sign_a == sign_b) begin
                sign_res = sign_a;
            end else begin
                if (exp_a > exp_b) begin
                    sign_res = sign_a;
                end else if (exp_a < exp_b) begin
                    sign_res = sign_b;
                end else begin
                    if (frac_a > frac_b) begin
                        sign_res = sign_a;
                    end else if (frac_a < frac_b) begin
                        sign_res = sign_b;
                    end else begin
                        sign_res = sign_a;
                    end
                end
            end
        end else begin
            sign_res = sign_a;
        end
    end

    // Setting the output result
    always @(*) begin
        if (isNaN_res == 1 || isInf_res == 1) begin
            result = 16'hFFFF;
        end else if (overflow == 1) begin
            result = {sign_res, 5'h1F, 10'h0};
        end else if (underflow == 1) begin
            result = {sign_res, 5'h00, 10'h0};
        end else begin
            result = {sign_res, exp_res, mant_res[22:10]};
        end
    end

    // Setting the flag outputs
    assign isNaN = isNaN_res;
    assign isInf = isInf_res;

endmodule

module d_ff_async_reset (
    input CK,
    input D,
    input RST,
    output Q,
    output QN
);

reg Q;
reg QN;

always @(posedge CK or negedge RST) begin
    if (!RST) begin
        Q <= 0;
        QN <= 1;
    end else begin
        Q <= D;
        QN <= ~D;
    end
end

endmodule

module top_module (
    input [3:0] in,
    output out_and,
    output out_or,
    output out_xor,
    output reg [1:0] pos,
    output [7:0] final_output
);

    wire [3:0] in_not = ~in;
    wire [3:0] in_and = &in;
    wire [3:0] in_or = |in;
    wire [3:0] in_xor = ^in;

    assign out_and = in_and;
    assign out_or = in_or;
    assign out_xor = in_xor;

    wire [3:0] and_not = ~in_and;
    wire [3:0] or_not = ~in_or;
    wire [3:0] xor_not = ~in_xor;

    wire [2:0] and_not_pos = and_not[2:0] == 0 ? 3 : and_not[1:0] == 0 ? 2 : and_not[0] == 0 ? 1 : 0;
    wire [2:0] or_not_pos = or_not[2:0] == 0 ? 3 : or_not[1:0] == 0 ? 2 : or_not[0] == 0 ? 1 : 0;
    wire [2:0] xor_not_pos = xor_not[2:0] == 0 ? 3 : xor_not[1:0] == 0 ? 2 : xor_not[0] == 0 ? 1 : 0;

    wire [7:0] and_not_product = and_not_pos == 0 ? 0 : and_not_pos == 1 ? in[0] : and_not_pos == 2 ? in[1:0] : in[2:0];
    wire [7:0] or_not_product = or_not_pos == 0 ? 0 : or_not_pos == 1 ? in[0] : or_not_pos == 2 ? in[1:0] : in[2:0];
    wire [7:0] xor_not_product = xor_not_pos == 0 ? 0 : xor_not_pos == 1 ? in[0] : xor_not_pos == 2 ? in[1:0] : in[2:0];

    assign final_output = {and_not_product, or_not_product, xor_not_product};

    always @(*) begin
        if (in[0] == 1) pos = 0;
        else if (in[1] == 1) pos = 1;
        else if (in[2] == 1) pos = 2;
        else if (in[3] == 1) pos = 3;
        else pos = 0;
    end

endmodule

module min_finder (
    input [7:0] a, b, c, d,
    output [7:0] min);

    wire [7:0] ab_min, cd_min, global_min;

    // Comparators to find the minimum of a and b, and c and d
    assign ab_min = (a < b) ? a : b;
    assign cd_min = (c < d) ? c : d;

    // Multiplexer to select the minimum of a and b, and c and d
    assign global_min = (ab_min < cd_min) ? ab_min : cd_min;

    // Output the global minimum
    assign min = global_min;

endmodule

