module priority_encoder (
    input [7:0] a, b, c, d,
    output [1:0] sel
);

assign sel = (a <= b) ? 2'b00 :
             (a <= c) ? 2'b01 :
             (a <= d) ? 2'b10 :
                        2'b11 ;

endmodule

