module alu(
	input	[63:0]	inA_i,
	input	[63:0]	inB_i,
	input	cflag_i,
	input	sum_en_i,
	input	and_en_i,
	input	xor_en_i,
	input	invB_en_i,
	input	lsh_en_i,
	input	rsh_en_i,
	input	ltu_en_i,
	input	lts_en_i,
	output	[63:0]	out_o,
	output	cflag_o,
	output	vflag_o,
	output	zflag_o
);

	wire [63:0] b = invB_en_i ? ~inB_i : inB_i;
	wire [63:0] sum = {cflag_i, inA_i} + {cflag_i, b};
	wire [63:0] ands = inA_i & b;
	wire [63:0] xors = inA_i ^ b;
	wire [63:0] lshs = lsh_en_i ? inA_i << inB_i[5:0] : 0;
	wire [63:0] rshs = rsh_en_i ? inA_i >> inB_i[5:0] : 0;

	wire [63:0] isLTU = ltu_en_i ? (inA_i < inB_i) : 0;
	wire [63:0] isLTS = lts_en_i ? ((inA_i[63] ^ inB_i[63]) & ((inA_i[63] ^ sum[63]) | (inB_i[63] ^ sum[63]))) : 0;

	assign out_o = sum_en_i ? sum : (and_en_i ? ands : (xor_en_i ? xors : (lsh_en_i ? lshs : (rsh_en_i ? rshs : (ltu_en_i ? isLTU : isLTS)))));
	assign cflag_o = sum[64];
	assign vflag_o = (inA_i[63] == b[63]) && (out_o[63] != inA_i[63]);
	assign zflag_o = ~(|out_o);

endmodule

module custom_protocol (
    input clk,
    input [31:0] data_in,
    input valid_in,
    input ready_out,
    output [31:0] data_out,
    output valid_out
);

    reg [31:0] data_out_reg;
    reg valid_out_reg;
    reg transmit_data;

    always @(posedge clk) begin
        if (valid_in && ready_out) begin
            data_out_reg <= data_in;
            transmit_data <= 1;
        end else if (ready_out && transmit_data) begin
            data_out_reg <= 'hx;
            transmit_data <= 0;
            valid_out_reg <= 1;
        end else if (valid_out_reg) begin
            valid_out_reg <= 0;
        end
    end

    assign data_out = data_out_reg;
    assign valid_out = valid_out_reg;

endmodule

