module clock_module (
    input areset,
    input inclk0,
    output reg c0,
    output reg locked
);

// Define constants
localparam REF_FREQ = 20_000_000; // Input clock frequency
localparam OUT_FREQ = 400_000_000; // Output clock frequency
localparam MAX_COUNTER = (REF_FREQ / OUT_FREQ) - 1; // Maximum counter value

// Declare internal signals
reg [31:0] counter = 0;
reg [31:0] phase_accumulator = 0;
reg [31:0] phase_increment = 0;
reg [31:0] dco_frequency = 0;
reg [31:0] dco_frequency_prev = 0;
reg [31:0] error_accumulator = 0;
reg [31:0] error_increment = 0;
reg [31:0] error_limit = 0;
reg [31:0] proportional_term = 0;
reg [31:0] integral_term = 0;
reg [31:0] derivative_term = 0;
reg [31:0] loop_filter_output = 0;

// Declare internal parameters
localparam KP = 200_000; // Proportional gain
localparam KI = 2_000; // Integral gain
localparam KD = 0; // Derivative gain
localparam KF = 1_000_000; // Loop filter gain
localparam MAX_ERROR = REF_FREQ / 2; // Maximum error value
localparam MIN_ERROR = -MAX_ERROR; // Minimum error value
localparam ERROR_LIMIT = 10_000; // Error limit for saturation
localparam DCO_MIN = 0; // Minimum DCO frequency value
localparam DCO_MAX = 2_000_000; // Maximum DCO frequency value

// Generate phase accumulator increment value
assign phase_increment = (OUT_FREQ * (1 << 32)) / REF_FREQ;

// Generate error increment value
assign error_increment = phase_accumulator[31] ? (REF_FREQ - OUT_FREQ) : OUT_FREQ;

// Calculate error limit for saturation
always @(*) begin
    if (error_increment > 0) begin
        error_limit = ERROR_LIMIT;
    end else if (error_increment < 0) begin
        error_limit = -ERROR_LIMIT;
    end else begin
        error_limit = 0;
    end
end

// Calculate proportional term
always @(*) begin
    proportional_term = KP * (error_accumulator >> 12);
end

// Calculate integral term
always @(*) begin
    integral_term = KI * (error_accumulator >> 22);
end

// Calculate derivative term
always @(*) begin
    derivative_term = KD * ((dco_frequency - dco_frequency_prev) >> 12);
end

// Calculate loop filter output
always @(*) begin
    loop_filter_output = proportional_term + integral_term + derivative_term;
end

// Limit loop filter output
always @(*) begin
    if (loop_filter_output > DCO_MAX) begin
        loop_filter_output = DCO_MAX;
    end else if (loop_filter_output < DCO_MIN) begin
        loop_filter_output = DCO_MIN;
    end
end

// Calculate DCO frequency
always @(posedge inclk0 or posedge areset) begin
    if (areset) begin
        dco_frequency <= 0;
        dco_frequency_prev <= 0;
    end else begin
        dco_frequency_prev <= dco_frequency;
        dco_frequency <= dco_frequency + loop_filter_output;
    end
end

// Calculate phase accumulator value
always @(posedge inclk0 or posedge areset) begin
    if (areset) begin
        counter <= 0;
        phase_accumulator <= 0;
        error_accumulator <= 0;
    end else begin
        counter <= counter + 1;
        if (counter > MAX_COUNTER) begin
            counter <= 0;
            phase_accumulator <= phase_accumulator + phase_increment;
        end
    end
end

// Calculate error value
always @(posedge inclk0 or posedge areset) begin
    if (areset) begin
        error_accumulator <= 0;
    end else begin
        error_accumulator <= error_accumulator + error_increment - loop_filter_output;
    end
end

// Generate output clock signal
always @(posedge inclk0 or posedge areset) begin
    if (areset) begin
        c0 <= 0;
    end else begin
        if (phase_accumulator[31] != phase_accumulator[30]) begin
            c0 <= ~c0;
        end
    end
end

// Generate locked signal
always @(posedge inclk0 or posedge areset) begin
    if (areset) begin
        locked <= 0;
    end else begin
        locked <= (error_accumulator > MIN_ERROR) && (error_accumulator < MAX_ERROR) && (loop_filter_output > error_limit);
    end
end

endmodule

module lfsr_4bit (
    input CLK,
    output reg Q0,
    output reg Q1,
    output reg Q2,
    output reg Q3
);

reg [3:0] reg_Q;

always @(posedge CLK) begin
    reg_Q <= {reg_Q[2:0], reg_Q[3] ^ reg_Q[2]};
end

assign Q0 = reg_Q[0];
assign Q1 = reg_Q[1];
assign Q2 = reg_Q[2];
assign Q3 = reg_Q[3];

endmodule

module vending_machine (
  input clk,
  input reset,
  input coin,
  input product,
  output reg dispense,
  output reg ready,
  output reg enough_coins,
  output reg out_of_stock
);

  // Define the states
  parameter Idle = 2'b00;
  parameter Ready = 2'b01;
  parameter Dispense = 2'b10;

  // Define the state register and initialize to Idle
  reg [1:0] state = Idle;

  // Define the combinational logic block to determine the next state
  always @ (posedge clk) begin
    if (reset) begin
      state <= Idle;
    end else begin
      case (state)
        Idle: begin
          if (product) begin
            state <= Ready;
          end else begin
            state <= Idle;
          end
        end
        Ready: begin
          if (coin) begin
            state <= Dispense;
          end else begin
            state <= Ready;
          end
        end
        Dispense: begin
          if (product && !out_of_stock) begin
            state <= Idle;
          end else begin
            state <= Idle;
          end
        end
      endcase
    end
  end

  // Define the output signals based on the current state
  always @ (state) begin
    case (state)
      Idle: begin
        dispense <= 0;
        ready <= 1;
        enough_coins <= 0;
        out_of_stock <= 0;
      end
      Ready: begin
        dispense <= 0;
        ready <= 1;
        enough_coins <= 0;
        out_of_stock <= 0;
      end
      Dispense: begin
        dispense <= 1;
        ready <= 0;
        enough_coins <= 1;
        if (out_of_stock) begin
          out_of_stock <= 1;
        end else begin
          out_of_stock <= 0;
        end
      end
    endcase
  end

