module top_module (
    input clk,
    input reset, // Synchronous active-high reset
    input [2:0] select, // Select input to choose between multiplexer and rising edge detector
    input [31:0] in, // 32-bit input for the rising edge detector
    output reg [3:0] out, // 4-bit compressed output
    output [3:0] wxyz // Output ports for the multiplexer
);

    // Rising edge detector
    reg [31:0] prev_in;
    reg [31:0] diff;
    reg [3:0] count;
    always @(posedge clk) begin
        if (reset) begin
            prev_in <= 0;
            diff <= 0;
            count <= 0;
        end else begin
            diff <= in ^ prev_in;
            prev_in <= in;
            if (diff != 0) begin
                count <= $clog2(diff + 1) - 1;
            end
        end
    end

    // Multiplexer
    always @(*) begin
        case (select)
            3'b000: wxyz = {1'b0, 1'b0, 1'b0, 1'b1};
            3'b001: wxyz = {1'b0, 1'b0, 1'b1, 1'b0};
            3'b010: wxyz = {1'b0, 1'b1, 1'b0, 1'b0};
            3'b011: wxyz = {1'b1, 1'b0, 1'b0, 1'b0};
            default: wxyz = {1'b0, 1'b0, 1'b0, 1'b0};
        endcase
    end

    // Control logic
    always @(*) begin
        if (select == 3'b100) begin
            out = count;
        end else begin
            out = wxyz;
        end
    end

endmodule

module MUX (
  input in0,
  input in1,
