module OR4_4input(
    input clk,
    input rst_n,
    output reg X
);

    // Inputs are registered
    reg A;
    reg B;
    reg C;
    reg D;
    reg VPWR;
    reg VGND;
    reg VPB;
    reg VNB;

    // Outputs are wires
    wire Y;

    sky130_fd_sc_ms__or4 dut (.A(A), .B(B), .C(C), .D(D), .VPWR(VPWR), .VGND(VGND), .VPB(VPB), .VNB(VNB), .X(Y));

    always @(posedge clk or negedge rst_n)
    begin
        if (~rst_n) begin
            A    <= 1'bX;
            B    <= 1'bX;
            C    <= 1'bX;
            D    <= 1'bX;
            VGND <= 1'bX;
            VNB  <= 1'bX;
            VPB  <= 1'bX;
            VPWR <= 1'bX;
            X    <= 1'bX;
        end
        else begin
            case ({A,B,C,D})
                4'b0000: begin
                    A    <= 1'b0;
                    X    <= Y;
                end
                4'b0001: begin
                    B    <= 1'b0;
                    X    <= Y;
                end
                4'b0011: begin
                    C    <= 1'b0;
                    X    <= Y;
                end
                4'b0111: begin
                    D    <= 1'b0;
                    X    <= Y;
                end
                4'b1111: begin
                    A    <= 1'b1;
                    B    <= 1'b1;
                    C    <= 1'b1;
                    D    <= 1'b1;
                    X    <= Y;
                end
                default: begin
                    A    <= 1'bx;
                    B    <= 1'bx;
                    C    <= 1'bx;
                    D    <= 1'bx;
                    X    <= 1'bx;
                end
            endcase
            VGND <= 1'bX;
            VNB  <= 1'bX;
            VPB  <= 1'bX;
            VPWR <= 1'bX;
        end
    end

