module edge_priority_encoder (
    input clk,
    input [7:0] in,
    output reg [1:0] pos
);

reg [7:0] prev_in;
reg [7:0] edge_detect;
reg [2:0] priority;

always @(posedge clk) begin
    edge_detect = in ^ prev_in;
    prev_in = in;

    if (edge_detect != 0) begin
        priority[2] = edge_detect[7];
        priority[1] = edge_detect[6] ? ~edge_detect[7] : edge_detect[7:6];
        priority[0] = edge_detect[5] ? ~edge_detect[7:6] : edge_detect[7:5];
        pos = $priority_encoder(priority);
    end
end

endmodule

module priority_encoder (
