module top_module(
    input clk,
    input reset, // Synchronous active-high reset
    input [3:0] in0,
    input [3:0] in1,
    input [3:0] in2,
    input [3:0] in3,
    input select, // Select input to choose between in2 and in3
    output [3:0] out_or_bitwise, // Bitwise OR value of in0 and in1
    output out_or_logical, // Logical OR value of in0 and in1
    output [3:0] out_sum // Sum of out_or_logical and selected value
);

reg [3:0] in0_inv;
reg [3:0] in1_inv;

wire [3:0] bitwise_or_out;
wire [3:0] selected_value;

bitwise_or bitwise_or_inst(
    .a(in0),
    .b(in1),
    .out(bitwise_or_out)
);

or or_inst(
    .a(in0),
    .b(in1),
    .out(out_or_logical)
);

always @(posedge clk) begin
    if (reset) begin
        in0_inv <= 4'b0;
        in1_inv <= 4'b0;
    end else begin
        in0_inv <= ~in0;
        in1_inv <= ~in1;
    end
end

always @(*) begin
    if (select) begin
        selected_value = in3;
    end else begin
        selected_value = in2;
    end
end

assign out_sum = out_or_logical + selected_value;

