module Queue_2048
(
 input 		 clock,
 input 		 reset,
 input [2047:0]  io_enq_bits,
 input 		 io_enq_valid,
 output 	 io_enq_ready,
 output [2047:0] io_deq_bits,
 output 		 io_deq_valid,
 input 		 io_deq_ready
 );
   reg [2047:0] mem [0:2047];
   reg [10:0] head;
   reg [10:0] tail;
   reg [10:0] count;
   wire [10:0] next_head;
   wire [10:0] next_tail;
   wire [10:0] next_count;
   wire 	 full;
   wire 	 empty;

   assign io_enq_ready = !full;
   assign io_deq_valid = !empty;
   assign next_head = (head == 2047) ? 0 : head + 1;
   assign next_tail = (tail == 2047) ? 0 : tail + 1;
   assign next_count = count + io_enq_valid - io_deq_valid;
   assign full = (next_count == 2048);
   assign empty = (next_count == 0);
   assign io_deq_bits = mem[tail];

   always @ (posedge clock) begin
      if (reset) begin
         head <= 0;
         tail <= 0;
         count <= 0;
      end else begin
         if (io_enq_valid && !full) begin
            mem[head] <= io_enq_bits;
            head <= next_head;
            count <= next_count;
         end
         if (io_deq_valid && !empty) begin
            tail <= next_tail;
            count <= next_count;
         end
      end
   end

endmodule

