module digital_clock(
    input wire clk,
    input wire reset,
    input wire set,
    input wire inc,
    output reg [6:0] seg,
    output reg dp
);

reg [3:0] hours = 4'd0;
reg [3:0] minutes = 4'd0;
reg [3:0] seconds = 4'd0;

reg [1:0] digit_select = 2'b00;
reg [3:0] digit_value = 4'd0;

reg [3:0] seg_value = 4'd0;

always @(posedge clk) begin
    if (reset) begin
        hours <= 4'd0;
        minutes <= 4'd0;
        seconds <= 4'd0;
        digit_select <= 2'b00;
        digit_value <= 4'd0;
        seg_value <= 4'd0;
    end else begin
        if (set) begin
            case (digit_select)
                2'b00: digit_value <= hours;
                2'b01: digit_value <= minutes;
                2'b10: digit_value <= seconds;
            endcase
            if (inc) begin
                digit_value <= digit_value + 4'd1;
                if (digit_value == 10) begin
                    digit_value <= 4'd0;
                end
            end else begin
                digit_value <= digit_value - 4'd1;
                if (digit_value == 15) begin
                    digit_value <= 4'd9;
                end
            end
            case (digit_select)
                2'b00: hours <= digit_value;
                2'b01: minutes <= digit_value;
                2'b10: seconds <= digit_value;
            endcase
        end else begin
            if (inc) begin
                seconds <= seconds + 4'd1;
                if (seconds == 60) begin
                    seconds <= 4'd0;
                    minutes <= minutes + 4'd1;
                    if (minutes == 60) begin
                        minutes <= 4'd0;
                        hours <= hours + 4'd1;
                        if (hours == 24) begin
                            hours <= 4'd0;
                        end
                    end
                end
            end
        end
        case (digit_select)
            2'b00: seg_value <= hours;
            2'b01: seg_value <= minutes;
            2'b10: seg_value <= seconds;
        endcase
        case (seg_value)
            4'd0: seg <= 7'b111_1110; // 0
            4'd1: seg <= 7'b011_0000; // 1
            4'd2: seg <= 7'b110_1101; // 2
            4'd3: seg <= 7'b111_1001; // 3
            4'd4: seg <= 7'b011_0011; // 4
            4'd5: seg <= 7'b101_1011; // 5
            4'd6: seg <= 7'b101_1111; // 6
            4'd7: seg <= 7'b111_0000; // 7
            4'd8: seg <= 7'b111_1111; // 8
            4'd9: seg <= 7'b111_1011; // 9
            default: seg <= 7'b111_1111; // blank
        endcase
        dp <= (digit_select == 2'b01); // enable decimal point for minutes
        digit_select <= digit_select + 2'b01;
        if (digit_select == 2'b11) begin
            digit_select <= 2'b00;
        end
    end
end

endmodule

module up_down_counter_priority_encoder (
    input clk,
    input rst,
    input up_down,
    input load,
    input [7:0] I,
    output reg EN,
    output [2:0] Y
);

reg [7:0] count;
reg [7:0] priority;
reg [2:0] highest_priority;

always @(posedge clk or negedge rst) begin
    if (!rst) begin
        count <= 8'd0;
        priority <= 8'd0;
        highest_priority <= 3'd0;
        EN <= 1'b0;
    end else if (load) begin
        count <= I;
        priority <= I;
        highest_priority <= 3'd0;
        EN <= 1'b1;
    end else if (up_down) begin
        count <= count + 1;
        priority <= I & ~count;
        EN <= 1'b1;
    end else begin
        count <= count - 1;
        priority <= I & count;
        EN <= 1'b1;
    end
end

always @(*) begin
    if (priority[7]) begin
        highest_priority <= 3'd7;
    end else if (priority[6]) begin
        highest_priority <= 3'd6;
    end else if (priority[5]) begin
        highest_priority <= 3'd5;
    end else if (priority[4]) begin
        highest_priority <= 3'd4;
    end else if (priority[3]) begin
        highest_priority <= 3'd3;
    end else if (priority[2]) begin
        highest_priority <= 3'd2;
    end else if (priority[1]) begin
        highest_priority <= 3'd1;
    end else if (priority[0]) begin
        highest_priority <= 3'd0;
    end
end

assign Y = highest_priority;

endmodule

module signed_mag_multiplier (
    input signed [15:0] A,
    input signed [15:0] B,
    output signed [31:0] result
);

reg signed [31:0] temp_result;
reg sign;

always @(*) begin
    if (A[15] == 1 && B[15] == 1) begin
        temp_result = ~(A[15:0] * B[15:0]) + 1;
        sign = 0;
    end
    else if (A[15] == 1) begin
        temp_result = -A[15:0] * B[15:0];
        sign = 1;
    end
    else if (B[15] == 1) begin
        temp_result = -B[15:0] * A[15:0];
        sign = 1;
    end
    else begin
        temp_result = A[15:0] * B[15:0];
        sign = 0;
    end
end

assign result = (sign == 1) ? -temp_result : temp_result;

endmodule

module absolute_value (
    input signed [31:0] a,
    output reg signed [31:0] result
);
    always @(*) begin
        if (a < 0) begin
            result = -a;
        end else begin
            result = a;
        end
    end
endmodule

module signed_magnitude_adder (
    input signed [31:0] a,
    input signed [31:0] b,
    output reg signed [31:0] result,
    output reg overflow
);
    always @(*) begin
        if ((a > 0 && b > 0 && (a + b) < 0) || (a < 0 && b < 0 && (a + b) > 0)) begin
            overflow = 1;
        end else begin
            overflow = 0;
        end
        result = a + b;
    end
endmodule

