module top_module (
    input signed [31:0] a,
    input signed [31:0] b,
    output signed [31:0] result,
    output overflow,
    output signed [31:0] max_output
);
    wire signed [31:0] abs_a, abs_b;
    wire signed [31:0] sum;
    wire overflow_flag;

    absolute_value abs_a_module(.a(a), .result(abs_a));
    absolute_value abs_b_module(.a(b), .result(abs_b));
    signed_magnitude_adder adder_module(.a(a), .b(b), .result(sum), .overflow(overflow_flag));
    max_module max_module(.a(abs_a), .b(abs_b), .max_output(max_output));

    assign result = sum;
    assign overflow = overflow_flag;
endmodule

module adder16(
    input [15:0] a,
    input [15:0] b,
    input c,
    output [15:0] sum,
    output cout
);

    wire [15:0] carry;
    full_adder fa0(a[0], b[0], c, sum[0], carry[0]);
    full_adder fa1(a[1], b[1], carry[0], sum[1], carry[1]);
    full_adder fa2(a[2], b[2], carry[1], sum[2], carry[2]);
