module PLL (
  input in_clk,
  input reset,
  input enable,
  output out_clk
);

parameter f_in = 50e6; // frequency of input clock signal
parameter f_out = 100e6; // desired frequency of output clock signal
parameter n = 2; // integer multiplication factor
parameter m = 1; // integer division factor

reg [31:0] phase_accumulator = 0;
reg [31:0] phase_increment = 0;
reg [31:0] control_voltage = 0;
reg [31:0] error_accumulator = 0;
reg [31:0] error = 0;
reg [31:0] loop_filter_output = 0;
reg [31:0] vco_output = 0;
reg locked = 0;

wire in_clk_edge = in_clk ^ ~in_clk;
wire out_clk_edge = vco_output ^ ~vco_output;

assign out_clk = vco_output;

always @(posedge in_clk_edge or posedge reset) begin
  if (reset) begin
    phase_accumulator <= 0;
    control_voltage <= 0;
    error_accumulator <= 0;
    locked <= 0;
  end else if (enable) begin
    error <= phase_accumulator - (phase_increment * n);
    error_accumulator <= error_accumulator + error;
    loop_filter_output <= error_accumulator / (f_in * m);
    control_voltage <= loop_filter_output;
    phase_accumulator <= phase_accumulator + (control_voltage * n);
    if (locked == 0 && abs(error) < (f_in * m / 100)) begin
      locked <= 1;
    end
  end
end

always @(posedge out_clk_edge) begin
  if (locked) begin
    phase_accumulator <= 0;
    error_accumulator <= 0;
  end
end

always @(posedge in_clk_edge) begin
  if (locked) begin
    vco_output <= ~vco_output;
  end
end

endmodule

