module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    output [3:0] S
);

    wire [3:0] C;

    // First bit
    xor #(.N(1)) xor1(S[0], A[0], B[0]);
    and #(.N(1)) and1(C[0], A[0], B[0]);

    // Second bit
    xor #(.N(1)) xor2(S[1], A[1], B[1], C[0]);
    and #(.N(1)) and2(C[1], A[1], B[1]);
    or #(.N(1)) or1(C[1], C[1], and1);

    // Third bit
    xor #(.N(1)) xor3(S[2], A[2], B[2], C[1]);
    and #(.N(1)) and3(C[2], A[2], B[2]);
    or #(.N(1)) or2(C[2], C[2], and2);

    // Fourth bit
    xor #(.N(1)) xor4(S[3], A[3], B[3], C[2]);
    and #(.N(1)) and4(C[3], A[3], B[3]);
    or #(.N(1)) or3(C[3], C[3], and3);

endmodule

module usb_tx_stuff
(
    input c,
    input d,
    input d_empty,
    output d_req,
    output q,
    input q_req,
    output q_empty
);

localparam ST_IDLE  = 4'd0;
localparam ST_READ  = 4'd1;
localparam ST_STUFF = 4'd2;
localparam ST_DONE  = 4'd3;

localparam SW = 4, CW = 5;

reg [CW+SW-1:0] ctrl;
wire [SW-1:0] state;
wire [SW-1:0] next_state = ctrl[SW+CW-1:CW];

r #(SW) state_r
(
    .c(c),
    .rst(1'b0),
    .en(1'b1),
    .d(next_state),
    .q(state)
);

wire [2:0] ones_count;

r #(3, 3'd0) ones_count_r
(
    .c(c),
    .rst(state == ST_IDLE | (q_req & d == 1'b0) | state == ST_STUFF),
    .en(q_req & d == 1'b1),
    .d(ones_count + 1'b1),
    .q(ones_count)
);

wire [2:0] done_cnt;
wire done_cnt_rst;

r #(3) done_cnt_r
(
    .c(c),
    .rst(done_cnt_rst),
    .en(1'b1),
    .d(done_cnt+1'b1),
    .q(done_cnt)
);

wire supress_empty = ctrl[2];

assign d_req = ctrl[0];
assign done_cnt_rst = ctrl[1];

wire nrzi;
wire next_nrzi = (state == ST_STUFF) ? ~nrzi : (d ? nrzi : ~nrzi);

r #(1, 1'b1) nrzi_r
(
    .c(c),
    .rst(state == ST_IDLE),
    .en(state != ST_IDLE & q_req),
    .d(next_nrzi),
    .q(nrzi)
);

assign q = nrzi;
assign q_empty = d_empty & ~supress_empty;

always @* begin
    case (state)
        ST_IDLE:
            if (~d_empty) begin
                ctrl = {ST_READ, 5'b00000};
            end
            else begin
                ctrl = {ST_IDLE, 5'b00000};
            end
        ST_READ:
            if (d_empty) begin
                ctrl = {ST_DONE, 5'b00010};
            end
            else if (q_req) begin
                if (ones_count == 3'd5 & d == 1'b1) begin
                    ctrl = {ST_STUFF, 5'b00110};
                end
                else begin
                    ctrl = {ST_READ, 5'b00011};
                end
            end
            else begin
                ctrl = {ST_READ, 5'b00000};
            end
        ST_STUFF:
            if (d_empty) begin
                ctrl = {ST_DONE, 5'b00011};
            end
            else if (q_req) begin
                ctrl = {ST_READ, 5'b00001};
            end
            else begin
                ctrl = {ST_STUFF, 5'b00100};
            end
        ST_DONE:
            if (done_cnt == 3'h7) begin
                ctrl = {ST_IDLE, 5'b00000};
            end
            else begin
                ctrl = {ST_DONE, 5'b00000};
            end
        default:
            ctrl = {ST_IDLE, 5'b00000};
    endcase
end

endmodule

module three_stage_register(
  input clk,
  input reset,
  input [13:0] e,
  input [31:0] b,
  output reg [13:0] q,
  output reg rb
);

reg [13:0] r_b, r_e, r_c, r_qx;
reg rr_b, rr_e;
wire [13:0] cx;
wire e2;

// Create the register (flip-flop) for the initial/1st stage
always@(posedge clk)
begin
  if(reset)
  begin
    r_b <= 0;
    r_e <= 0;
  end
  else
  begin
    r_e <= e;
    r_b <= b;
  end
end

// Create the register (flip-flop) for the 2nd stage
always@(posedge clk)
begin
  if(reset)
  begin
    r_c <= 0;
    rr_e <= 0;
    rr_b <= 0;
  end
  else
  begin
    r_c <= cx;
    rr_e <= r_e;
    rr_b <= r_b;
  end
end

// Create the register (flip-flop) for the 3rd stage
always@(posedge clk)
begin
  if(reset)
  begin
    r_qx <= 0;
    rb <= 0;
  end
  else
  begin
    r_qx <= cx;
    rb <= rr_b;
    e2 <= rr_e;
  end
end

// Assign value to q
assign q = r_qx;

// Assign value to cx
assign cx = r_c & e2;

// Assign value to rb
always@(posedge clk)
begin
  if(reset)
  begin
    rb <= 0;
  end
  else
  begin
    rb <= rr_b;
  end
end

endmodule

