module MIPS(clk, reset);
    input clk;
    input reset;

    reg [31:0] PC;
    reg [31:0] INST;
    reg [31:0] IM[0:255];
    reg [31:0] regWriteData;
    reg [31:0] readData1;
    reg [31:0] readData2;
    reg [31:0] ALURES;
    reg [31:0] READDATA;
    reg [31:0] DATA;
    reg [31:0] JumpAddr;
    reg [31:0] ADDRES;
    reg [31:0] MUXOUT;
    reg [31:0] nextPC;
    reg [4:0] WRITEREG;
    reg [3:0] ALUCTR;
    reg [31:0] INPUT2;
    reg [31:0] WRITEDATA;
    reg [1:0] ALUOP;
    reg REG_DST;
    reg JUMP;
    reg BRANCH;
    reg MEM_READ;
    reg MEM_TO_REG;
    reg MEM_WRITE;
    reg ALUSRC;
    reg REG_WRITE;

    wire [31:0] pcPlus;
    assign pcPlus = PC + 4;

    wire [31:0] instshift;
    assign instshift = INST[25:0] << 2;

    assign JumpAddr = {pcPlus[31:28],instshift[27:0]};

    wire [31:0] addshift;
    assign addshift = DATA << 2;

    assign ADDRES = pcPlus + addshift;

    assign MUXOUT = BRANCH & ALURES?ADDRES:pcPlus;

    assign nextPC = JUMP?JumpAddr:MUXOUT;

    assign WRITEREG = REG_DST?INST[15:11]:INST[20:16];
    assign INPUT2 = ALUSRC?DATA:readData2;
    assign WRITEDATA = MEM_TO_REG?READDATA:ALURES;

    always @(posedge clk)
        if(reset == 0)
            PC <= 0;
        else
            PC <= nextPC;

    always @ (*)
        INST <= IM[PC >> 2];

    Ctr mainCtr(
        .opCode(INST[31:26]),
        .regDst(REG_DST),
        .aluSrc(ALUSRC),
        .memToReg(MEM_TO_REG),
        .regWrite(REG_WRITE),
        .memRead(MEM_READ),
        .memWrite(MEM_WRITE),
        .branch(BRANCH),
        .aluOp(ALUOP),
        .jump(JUMP)
    );

    register mainregister(
        .clock_in(clk),
        .readReg1(INST[25:21]),
        .readReg2(INST[20:16]),
        .writeReg(WRITEREG),
        .writeData(WRITEDATA),
        .regWrite(REG_WRITE),
        .readData1(readData1),
        .readData2(readData2),
        .rst(reset)
    );

    aluCtr mainAluCtr(
        .aluOp(ALUOP),
        .funct(INST[5:0]),
        .aluCtr(ALUCTR)
    );

    alu mainAlu(
        .input1(readData1),
        .input2(INPUT2),
        .aluCtr(ALUCTR),
        .zero(ALURES == 0),
        .aluRes(ALURES)
    );

    data_memory mainmemory(
        .clock_in(clk),
        .address(ALURES),
        .writeData(readData2),
        .memWrite(MEM_WRITE),
        .memRead(MEM_READ),
        .readData(READDATA)
    );

    signext mainsignext(
        .inst(INST[15:0]),
        .data(DATA)
    );

    initial begin
        $readmemb("inst.txt", IM, 32'b0);
    end

endmodule

