module rotator(
    input clk,
    input load,
    input [1:0] ena,
    input [99:0] data,
    output reg [99:0] q);

    reg [99:0] shift_reg;
    reg [6:0] shift_amt;
    reg [1:0] shift_dir;

    always @(posedge clk) begin
        if (load) begin
            shift_reg <= data;
        end else begin
            shift_dir <= ena;
            case (shift_dir)
                2'b00: shift_amt <= 7'd0;
                2'b01: shift_amt <= {7'd0, ena[0]};
                2'b10: shift_amt <= {ena[0], 7'd0};
                2'b11: shift_amt <= ena;
            endcase
            if (shift_dir == 2'b01) begin
                shift_reg <= {shift_reg[shift_amt - 1:0], shift_reg[99:shift_amt]};
            end else if (shift_dir == 2'b10) begin
                shift_reg <= {shift_reg[99-shift_amt:99], shift_reg[0:99-shift_amt-1]};
            end else if (shift_dir == 2'b11) begin
                shift_reg <= {shift_reg[shift_amt-1:0], shift_reg[99-shift_amt:99]};
            end
        end
    end

    assign q = shift_reg;

endmodule

