module top_module (
    input clk,              // Clock signal
    input rst_n,            // Asynchronous active-low reset
    input [3:0] in0,        // 4-bit input to the multiplexer
    input [3:0] in1,        // 4-bit input to the multiplexer
    input [3:0] in2,        // 4-bit input to the multiplexer
    input [3:0] in3,        // 4-bit input to the multiplexer
    input [1:0] sel,        // 2-bit select input to the multiplexer
    output [3:0] mux_out,   // 4-bit output from the multiplexer
    output [3:0] johnson_out, // 4-bit output from the Johnson counter
    output [3:0] diff_out   // 4-bit output from the functional module
);

reg [3:0] mux_in;

// Priority encoder to select the input signal for the multiplexer
always @(*) begin
    case(sel)
        2'b00: mux_in = in0;
        2'b01: mux_in = in1;
        2'b10: mux_in = in2;
        2'b11: mux_in = in3;
    endcase
end

// 4-to-1 multiplexer
mux4to1 mux(
    .sel(sel),
    .in0(in0),
    .in1(in1),
    .in2(in2),
    .in3(in3),
    .out(mux_out)
);

// Johnson counter
reg [63:0] johnson_reg;
wire [3:0] johnson_out_wire;

always @(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        johnson_reg <= 64'b0;
    end else begin
        johnson_reg <= {johnson_reg[62:0], ~johnson_reg[63]};
    end
end

