        if (load) begin
            q <= data;
        end else begin
            case (ena)
                2'b00: q <= q;
                2'b01: q <= {q[98:0], q[99]};
                2'b10: q <= {q[1:99], q[0]};
                2'b11: q <= {q[1:99], q[0]} ^ {q[98:99], q[0]};
            endcase
        end
    end

    assign q_out = q;

