module comparator (
    input [7:0] A,
    input [7:0] B,
    output reg EQ,
    output reg GT
);

    always @(*) begin
        if (A == B) begin
            EQ = 1;
            GT = 0;
        end else if (A > B) begin
            EQ = 0;
            GT = 1;
        end else begin
            EQ = 0;
            GT = 0;
        end
    end

endmodule

module binary_division (
    input [15:0] dividend,
    input [15:0] divisor,
    output reg [15:0] quotient
);

    reg [15:0] remainder;
    reg [3:0] count;

    always @(posedge clk) begin
        if (count == 0) begin
            remainder = dividend;
            count = 16;
        end else begin
            remainder = {remainder[14:0], dividend[15]};
            dividend = {dividend[14:0], 1'b0};
            if (remainder >= divisor) begin
                remainder = remainder - divisor;
                quotient[count-1] = 1'b1;
            end else begin
                quotient[count-1] = 1'b0;
            end
            count = count - 1;
        end
    end

endmodule

module final_output (
    input EQ,
    input GT,
    input [15:0] quotient,
    output reg result
);

    always @(*) begin
        if ((quotient[0] == 1) && ((quotient[15:1] % 3) == 0)) begin
            result = 1;
        end else begin
            result = 0;
        end
    end

endmodule

