          3'b110: s_axi_rdata[0] <= gpio2_io_i[5];
          3'b111: s_axi_rdata[0] <= gpio2_io_i[6];
        endcase
        s_axi_rvalid <= 1;
      end
    end
  end

  assign gpio_io_o = gpio_io_o_reg;
  assign gpio_io_t = 4'b1111;
  assign gpio2_io_o = gpio2_io_o_reg;
