module my_alu(
    input signed [N-1:0] a,
    input signed [N-1:0] b,
    input [3:0] op,
    output signed [N-1:0] result,
    output carry
);

reg signed [N-1:0] result_reg;
reg carry_reg;

always @* begin
    case(op)
        4'b0000: begin // a + b
            result_reg = a + b;
            carry_reg = (result_reg[N-1] == a[N-1] && result_reg[N-1] == b[N-1]) ? 1 : 0;
        end
        4'b0001: begin // a - b
            result_reg = a - b;
            carry_reg = (result_reg[N-1] == a[N-1] && result_reg[N-1] != b[N-1]) ? 1 : 0;
        end
        4'b0010: begin // a & b
            result_reg = a & b;
            carry_reg = 0;
        end
        4'b0011: begin // a | b
            result_reg = a | b;
            carry_reg = 0;
        end
        4'b0100: begin // a ^ b
            result_reg = a ^ b;
            carry_reg = 0;
        end
        4'b0101: begin // ~a
            result_reg = ~a;
            carry_reg = 0;
        end
        4'b0110: begin // ~b
            result_reg = ~b;
            carry_reg = 0;
        end
        4'b0111: begin // 0
            result_reg = 0;
            carry_reg = 0;
        end
        4'b1000: begin // a << b
            result_reg = a << b;
            carry_reg = (result_reg[N-1] == 1) ? 1 : 0;
        end
        4'b1001: begin // a >> b
            result_reg = a >> b;
            carry_reg = (result_reg[0] == 1) ? 1 : 0;
        end
        4'b1010: begin // a >>> b
            result_reg = $signed({a[N-1], a}) >>> b;
            carry_reg = (result_reg[0] == 1) ? 1 : 0;
        end
        4'b1011: begin // a == b
            result_reg = (a == b) ? 1 : 0;
            carry_reg = 0;
        end
        4'b1100: begin // a != b
            result_reg = (a != b) ? 1 : 0;
            carry_reg = 0;
        end
        4'b1101: begin // a > b
            result_reg = (a > b) ? 1 : 0;
            carry_reg = 0;
        end
        4'b1110: begin // a >= b
            result_reg = (a >= b) ? 1 : 0;
            carry_reg = 0;
        end
        4'b1111: begin // a < b
            result_reg = (a < b) ? 1 : 0;
            carry_reg = 0;
        end
    endcase
end

assign result = result_reg;
assign carry = carry_reg;

endmodule

module vending_machine(
    input reset,
    input coin,
    input dispense,
    output reg item_dispensed,
    output reg change
);

parameter ITEM_PRICE = 4; // price of the item in quarters

reg [1:0] state; // state variable
reg [2:0] count; // count of quarters received

// state definitions
parameter IDLE = 2'b00;
parameter DISPENSE = 2'b01;

always @(posedge clock) begin
    if (reset) begin
        // reset state
        state <= IDLE;
        count <= 0;
        item_dispensed <= 0;
        change <= 0;
    end else begin
        // idle state
        if (state == IDLE) begin
            if (coin) begin
                count <= count + 1;
            end
            if (dispense && count >= ITEM_PRICE) begin
                state <= DISPENSE;
            end
        end
        // dispense state
        else if (state == DISPENSE) begin
            item_dispensed <= 1;
            change <= count - ITEM_PRICE;
            state <= IDLE;
        end
    end
end

endmodule

