module irda_tx (
  input data,
  input clk,
  input rst,
  output tx
);

  reg [3:0] state;
  reg [7:0] count;
  reg [1:0] pulse_count;
  reg tx_reg;

  always @(posedge clk, posedge rst) begin
    if (rst) begin
      state <= 4'b0000;
      count <= 8'd0;
      pulse_count <= 2'd0;
      tx_reg <= 1'b0;
    end else begin
      case (state)
        4'b0000: begin // Start bit
          tx_reg <= 1'b0;
          pulse_count <= 2'd0;
          count <= 8'd0;
          state <= 4'b0001;
        end
        4'b0001: begin // Data bits
          tx_reg <= data;
          pulse_count <= pulse_count + 1;
          if (pulse_count == 2'd1) begin
            count <= count + 1;
            pulse_count <= 2'd0;
          end
          if (count == 8'd7) begin
            count <= 8'd0;
            state <= 4'b0010;
          end
        end
        4'b0010: begin // Stop bit
          tx_reg <= 1'b1;
          pulse_count <= pulse_count + 1;
          if (pulse_count == 2'd1) begin
            pulse_count <= 2'd0;
            state <= 4'b0011;
          end
        end
        4'b0011: begin // Idle state
          tx_reg <= 1'b0;
          pulse_count <= pulse_count + 1;
          if (pulse_count == 2'd3) begin
            pulse_count <= 2'd0;
            state <= 4'b0000;
          end
        end
      endcase
    end
  end

  assign tx = tx_reg;

endmodule

module irda_rx (
  input rx,
  input clk,
  input rst,
  output data
);

  reg [3:0] state;
  reg [7:0] count;
  reg [1:0] pulse_count;
  reg data_reg;

  always @(posedge clk, posedge rst) begin
    if (rst) begin
      state <= 4'b0000;
      count <= 8'd0;
      pulse_count <= 2'd0;
      data_reg <= 1'b0;
    end else begin
      case (state)
        4'b0000: begin // Start bit
          pulse_count <= pulse_count + 1;
          if (rx == 1'b0 && pulse_count == 2'd1) begin
            pulse_count <= 2'd0;
            count <= 8'd0;
            state <= 4'b0001;
          end
        end
        4'b0001: begin // Data bits
          pulse_count <= pulse_count + 1;
          if (pulse_count == 2'd1) begin
            pulse_count <= 2'd0;
            count <= count + 1;
            data_reg <= {data_reg[6:0], rx};
          end
          if (count == 8'd7) begin
            count <= 8'd0;
            state <= 4'b0010;
          end
        end
        4'b0010: begin // Stop bit
          pulse_count <= pulse_count + 1;
          if (rx == 1'b1 && pulse_count == 2'd1) begin
            pulse_count <= 2'd0;
            state <= 4'b0011;
          end
        end
        4'b0011: begin // Idle state
          pulse_count <= pulse_count + 1;
          if (pulse_count == 2'd3) begin
            pulse_count <= 2'd0;
            state <= 4'b0000;
            data <= data_reg;
          end
        end
      endcase
    end
  end

endmodule

