module barrel_shifter(
    input clk,
    input reset,
    input [99:0] in,
    input [1:0] ena,
    input load,
    output [99:0] out);

    reg [99:0] shift_reg;

    always @(posedge clk or posedge reset) begin
        if (reset) shift_reg <= 100'b0;
        else if (load) shift_reg <= in;
        else begin
            case (ena)
                2'b01: shift_reg <= {shift_reg[98:0], shift_reg[99]};
                2'b10: shift_reg <= {shift_reg[0], shift_reg[99:1]};
            endcase
        end
    end

    assign out = shift_reg;

endmodule

