module axi_frame_len_calculator (
    input axi_tvalid,
    input axi_tlast,
    output reg [15:0] frame_len,
    output reg frame_len_valid
);

reg [15:0] count;
reg [15:0] next_count;
reg [15:0] saved_count;
reg [1:0] state;

parameter IDLE = 2'b00;
parameter COUNTING = 2'b01;
parameter OUTPUTTING = 2'b10;

always @(posedge axi_tvalid) begin
    if (!axi_tvalid) begin
        // reset state
        state <= IDLE;
        count <= 0;
        saved_count <= 0;
        frame_len_valid <= 0;
    end else begin
        case (state)
            IDLE: begin
                if (axi_tlast) begin
                    // start counting
                    state <= COUNTING;
                    count <= 0;
                end
            end
            COUNTING: begin
                // increment count
                next_count <= count + 1;
                if (axi_tlast) begin
                    // save count and output
                    saved_count <= next_count;
                    frame_len <= next_count;
                    frame_len_valid <= 1;
                    // go to outputting state
                    state <= OUTPUTTING;
                end else begin
                    // continue counting
                    count <= next_count;
                end
            end
            OUTPUTTING: begin
                // wait for axi_tvalid to go low
                if (!axi_tvalid) begin
                    // reset state
                    state <= IDLE;
                    count <= 0;
                    saved_count <= 0;
                    frame_len_valid <= 0;
                end
            end
        endcase
    end
end

endmodule

module spi_slave_simpler2(clk, cs, mosi, miso, sck, done, din, dout);
	parameter bc=8;	// bit count

	input clk;
	input cs;	// active low
	input mosi;
	output miso;
	input sck;
	output reg done;
	input [bc-1:0] din;
	output reg [bc-1:0] dout;

	reg [bc-1:0] shift_reg;
	reg prev_cs, prev_sck;
	reg mosi_sample;
	reg [7:0] shift_count;

	assign miso = shift_reg[bc-1];

	always @(posedge clk) begin
		if (~cs) begin
			if (prev_cs) begin
				// falling cs edge - start spi transfer
				done <= 0;
				shift_reg[bc-1:0] <= 8'h23; //din[bc-1:0];
				shift_count <= 0;
			end else begin
				if (~prev_sck && sck) begin
					// rising sck edge - sample mosi
					mosi_sample <= mosi;
					if (shift_count == bc-1) begin
						dout <= {shift_reg[bc-2:0], mosi};
						done <= 1;
					end
				end 
				if (prev_sck && ~sck) begin
					// falling sck edge - shift in/out one bit
					shift_reg[bc-1:0] <= {shift_reg[bc-2:0], mosi_sample};
					shift_count <= shift_count + 1;
				end
			end
		end else begin
			done <= 1;
		end
		prev_cs <= cs;
		prev_sck <= sck;
	end
endmodule

