    epsilon = 1;
    for (i = 0; i < 10; i = i + 1) begin
      x_curr = x_next;
      x_next = (x_curr + (in / x_curr)) / 2;
      if ((x_next - x_curr) < epsilon) begin
        out = x_next;
        $display("Square root of %d is %d", in, out);
        $finish;
      end
    end
  end

