module priority_encoder(
    input [7:0] valid,
    input [1:0] pri0, pri1, pri2, pri3,
    input [1:0] pri4, pri5, pri6, pri7,
    output reg [1:0] pri_out
);

    // Set pri_sel based on the number of priority levels required
    parameter pri_sel = 2'd2;

    // Create a priority encoder for each input
    wire [3:0] pri0_out, pri1_out, pri2_out, pri3_out;
    wire [3:0] pri4_out, pri5_out, pri6_out, pri7_out;
    priority_decoder pd0(valid[0], pri0, pri0_out);
    priority_decoder pd1(valid[1], pri1, pri1_out);
    priority_decoder pd2(valid[2], pri2, pri2_out);
    priority_decoder pd3(valid[3], pri3, pri3_out);
    priority_decoder pd4(valid[4], pri4, pri4_out);
    priority_decoder pd5(valid[5], pri5, pri5_out);
    priority_decoder pd6(valid[6], pri6, pri6_out);
    priority_decoder pd7(valid[7], pri7, pri7_out);

    // Combine all priority encoder outputs
    wire [3:0] pri_out_tmp;
    assign pri_out_tmp = pri0_out | pri1_out | pri2_out | pri3_out |
                         pri4_out | pri5_out | pri6_out | pri7_out;

    // Determine the highest priority level
    always @*
    begin
        case (pri_sel)
            2'd0: // 2 priority levels
                begin
                    if (pri_out_tmp[3] || pri_out_tmp[2])
                        pri_out = 2'b11; // highest priority level
                    else
                        pri_out = 2'b00; // lowest priority level
                end
            2'd1: // 4 priority levels
                begin
                    if (pri_out_tmp[3])
                        pri_out = 2'b11; // highest priority level
                    else if (pri_out_tmp[2])
                        pri_out = 2'b10;
                    else if (pri_out_tmp[1])
                        pri_out = 2'b01;
                    else
                        pri_out = 2'b00; // lowest priority level
                end
            default: // 8 priority levels
                begin
                    if (pri_out_tmp[3])
                        pri_out = 2'b11; // highest priority level
                    else if (pri_out_tmp[2])
                        pri_out = 2'b10;
                    else if (pri_out_tmp[1])
                        pri_out = 2'b01;
                    else if (pri_out_tmp[0])
                        pri_out = 2'b00;
                    else if (pri_out_tmp[7])
                        pri_out = 2'b11; // highest priority level
                    else if (pri_out_tmp[6])
                        pri_out = 2'b10;
                    else if (pri_out_tmp[5])
                        pri_out = 2'b01;
                    else
                        pri_out = 2'b00; // lowest priority level
                end
        endcase
    end

endmodule

// Priority decoder module
module priority_decoder(
    input valid,
    input [1:0] pri_in,
    output reg [3:0] pri_out
);

    always @*
    begin
        if (valid)
            case (pri_in)
                2'd0: pri_out = 4'b1000; // highest priority level
                2'd1: pri_out = 4'b0100;
                2'd2: pri_out = 4'b0010;
                2'd3: pri_out = 4'b0001;
            endcase
        else
            pri_out = 4'b0000; // lowest priority level
    end

endmodule

