module four_bit_adder(
input wire [3:0] a,
input wire [3:0] b,
input wire ci,
output reg [3:0] s,
output reg co
);

	// Define internal wires for each bit of the sum and carry
	wire [3:0] sum;
	wire c1, c2, c3;

	// Instantiate four single-bit adders to compute the sum of each bit
	// and the carry-out bit for each bit position
	adder add1(.a(a[0]), .b(b[0]), .ci(ci), .s(sum[0]), .co(c1));
	adder add2(.a(a[1]), .b(b[1]), .ci(c1), .s(sum[1]), .co(c2));
	adder add3(.a(a[2]), .b(b[2]), .ci(c2), .s(sum[2]), .co(c3));
	adder add4(.a(a[3]), .b(b[3]), .ci(c3), .s(sum[3]), .co(co));

	// Assign the sum and carry-out bits to the output ports
	always @ (*)
		s = sum;

endmodule

module top_module( 
    input wire clk,
    input wire reset,
    input wire [15:0] in,
    input wire select,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo,
    output wire [1023:0] out_demux );

    // 256-to-1 demultiplexer
    wire [7:0] demux_out [255:0];
    wire [3:0] demux_sel = in[3:0];
    assign out_demux = {demux_out};

    genvar i;
    generate
        for (i = 0; i < 256; i = i + 1) begin : DEMUX_BLOCK
            assign demux_out[i] = (demux_sel == i) ? in[7:0] : 8'b0;
        end
    endgenerate

    // Multiplexer
    wire [7:0] mux_out;
    wire [11:8] mux_sel = in[11:8];
    assign out_hi = (select) ? 8'b0 : mux_out;
    assign out_lo = (select) ? mux_out : 8'b0;

    assign mux_out = (mux_sel == 8'b0) ? in[15:8] : in[7:0];

    // Control logic
    reg mux_enable;
    reg demux_enable;

    always @ (posedge clk, posedge reset) begin
        if (reset) begin
            mux_enable <= 0;
            demux_enable <= 0;
        end else begin
            mux_enable <= select;
            demux_enable <= ~select;
        end
    end

    // Multiplexer and demultiplexer enable
    assign out_hi = (mux_enable) ? out_hi : 8'b0;
    assign out_lo = (mux_enable) ? out_lo : 8'b0;
    assign out_demux = (demux_enable) ? out_demux : 1024'b0;

