module glitch_filter (
  input wire clk,
  input wire reset,
  input wire [n-1:0] sig_in,
  output wire [n-1:0] sig_out
);

parameter n = 8; // number of bits in the input signal
parameter t = 2; // duration of the glitch (in clock cycles)

reg [n-1:0] delay_line [0:t-1];
reg [n-1:0] sig_out_reg;
integer i;

always @(posedge clk or posedge reset) begin
  if (reset) begin
    for (i = 0; i < t; i = i + 1) begin
      delay_line[i] <= 0;
    end
    sig_out_reg <= 0;
  end else begin
    for (i = t - 1; i > 0; i = i - 1) begin
      delay_line[i] <= delay_line[i - 1];
    end
    delay_line[0] <= sig_in;

    if (sig_in == delay_line[t - 1]) begin
      sig_out_reg <= sig_in;
    end
  end
end

assign sig_out = sig_out_reg;

endmodule

module cordic
#(
    parameter MODE = 1, // 1: sine/cosine, 2: sinh/cosh, 3: sqrt
    parameter PIPELINE_STAGES = 5 // Number of pipeline stages
)
(
    input clk,
    input rst_n,
    input signed [31:0] operand,
    output reg signed [15:0] result_a,
    output reg signed [15:0] result_b
);

localparam PORT_WIDTH = (MODE == 3) ? 32 : 16;
localparam IN_WIDTH = 2 * PORT_WIDTH;
localparam OUT_WIDTH = PORT_WIDTH + 2;

wire signed [PORT_WIDTH-1:0] x [0:PIPELINE_STAGES];
wire signed [PORT_WIDTH-1:0] y [0:PIPELINE_STAGES];
wire signed [PORT_WIDTH-1:0] z [0:PIPELINE_STAGES];

assign x[0] = (MODE == 3) ? {16'd0, operand[31:16]} : {16'd16384, 16'd0};
assign y[0] = (MODE == 3) ? {16'd0, operand[15:0]} : operand[31:16];
assign z[0] = (MODE == 3) ? {16'd0, operand[31:16]} : operand[15:0];

genvar i;
generate
    for (i = 0; i < PIPELINE_STAGES; i = i + 1) begin : stage
        assign x[i+1] = x[i] - (y[i] >> i);
        assign y[i+1] = y[i] + (x[i] >> i);
        assign z[i+1] = z[i] - (MODE == 1 ? (1 << (13 - i)) : (MODE == 2 ? -(1 << (13 - i)) : ((z[i] >> 1) & ~(1 << (31 - i)))));
    end
endgenerate

always @(posedge clk) begin
    if (!rst_n) begin
        result_a <= 0;
        result_b <= 0;
    end else begin
        case (MODE)
            1: begin
                result_a <= y[PIPELINE_STAGES] >> 2;
                result_b <= x[PIPELINE_STAGES] >> 2;
            end
            2: begin
                result_a <= y[PIPELINE_STAGES] >> 2;
                result_b <= x[PIPELINE_STAGES] >> 2;
            end
            3: begin
                result_a <= x[PIPELINE_STAGES] >> 2;
                result_b <= 0;
            end
        endcase
    end
end

endmodule

