module light_control_block (
  input [11:0] ambient_light,
  input enable,
  input [2:0] brightness_level,
  output [11:0] light_output,
  output reg dim_up,
  output reg dim_down
);

  reg [11:0] pwm_counter;
  reg [11:0] pwm_threshold;
  reg [2:0] current_brightness_level;
  reg [2:0] target_brightness_level;
  reg [11:0] current_light_output;

  parameter PWM_PERIOD = 4095; // PWM period for 12-bit resolution

  always @(*) begin
    if (enable) begin
      if (ambient_light > brightness_level) begin
        target_brightness_level = brightness_level;
        dim_up = 0;
        dim_down = 1;
      end else begin
        target_brightness_level = ambient_light;
        dim_up = 1;
        dim_down = 0;
      end
    end else begin
      target_brightness_level = 0;
      dim_up = 0;
      dim_down = 0;
    end
  end

  always @(posedge clk) begin
    if (enable) begin
      if (current_brightness_level < target_brightness_level) begin
        current_brightness_level <= current_brightness_level + 1;
      end else if (current_brightness_level > target_brightness_level) begin
        current_brightness_level <= current_brightness_level - 1;
      end

      pwm_counter <= pwm_counter + 1;
      if (pwm_counter >= PWM_PERIOD) begin
        pwm_counter <= 0;
        pwm_threshold <= current_brightness_level;
      end

      if (pwm_counter < pwm_threshold) begin
        current_light_output <= 4095;
      end else begin
        current_light_output <= 0;
      end
    end else begin
      current_brightness_level <= 0;
      pwm_counter <= 0;
      pwm_threshold <= 0;
      current_light_output <= 0;
    end
  end

  assign light_output = current_light_output;

endmodule

Instruction:
Please act as a professional Verilog designer. Create a module that implements a JK flip-flop with the given truth table. The module should have inputs for J, K, and a clock signal (clk), and an output for Q. The output should be updated on the positive edge of the clock signal. The truth table is as follows: 
// J | K | Q
// 0 | 0 | Qold
// 0 | 1 | 0
// 1 | 0 | 1
// 1 | 1 | ~Qold
To implement this module, use always block triggered by the positive edge of the clock. Inside the always block, use a case statement to handle the different combinations of J and K inputs and update the output Q accordingly.

Response:
module jk_flip_flop (
  input J,
  input K,
  input clk,
  output reg Q
);

  always @(posedge clk) begin
    case ({J,K})
      2'b00: Q <= Q;
      2'b01: Q <= 1'b0;
      2'b10: Q <= 1'b1;
      2'b11: Q <= ~Q;
    endcase
  end

endmodule

