// Magnitude comparator module
module comparator (
    input [3:0] A,
    input [3:0] B,
    output reg EQ,
    output reg GT
);

    always @ (A, B) begin
        if (A == B) begin
            EQ <= 1'b1;
            GT <= 1'b0;
        end else if (A > B) begin
            EQ <= 1'b0;
            GT <= 1'b1;
        end else begin
            EQ <= 1'b0;
            GT <= 1'b0;
        end
    end

endmodule

// 4-to-16 decoder module
module decoder (
    input [3:0] in,
    output [15:0] out
);

    assign out = { ~in[3] & ~in[2] & ~in[1] & ~in[0], // 0000
                   ~in[3] & ~in[2] & ~in[1] & in[0],  // 0001
                   ~in[3] & ~in[2] & in[1] & ~in[0],  // 0010
                   ~in[3] & ~in[2] & in[1] & in[0],   // 0011
                   ~in[3] & in[2] & ~in[1] & ~in[0],  // 0100
                   ~in[3] & in[2] & ~in[1] & in[0],   // 0101
                   ~in[3] & in[2] & in[1] & ~in[0],   // 0110
                   ~in[3] & in[2] & in[1] & in[0],    // 0111
                   in[3] & ~in[2] & ~in[1] & ~in[0],  // 1000
                   in[3] & ~in[2] & ~in[1] & in[0],   // 1001
                   in[3] & ~in[2] & in[1] & ~in[0],   // 1010
                   in[3] & ~in[2] & in[1] & in[0],    // 1011
                   in[3] & in[2] & ~in[1] & ~in[0],   // 1100
                   in[3] & in[2] & ~in[1] & in[0],    // 1101
                   in[3] & in[2] & in[1] & ~in[0],    // 1110
                   in[3] & in[2] & in[1] & in[0]      // 1111
                 };

endmodule

// Functional module
module functional (
    input [15:0] in,
    output reg [3:0] out
);

    always @ (in) begin
        case (in)
            16'b0000000000000001: out <= 4'b0001; // A < B
            16'b0000000000000010: out <= 4'b0010; // A = B
            16'b0000000000000100: out <= 4'b0100; // A > B
            default: out <= 4'b0000; // Invalid input
        endcase
    end

endmodule

module pmsm (npm0, npm1, npm2, npm3, pm0, pm1, pm2, pm3, clk, reset);

   // outputs
   output [3:0] pm0, pm1, pm2, pm3;

   // inputs
   input  	clk, reset;
   input [3:0] 	npm0, npm1, npm2, npm3;

   reg [3:0] 	pm0, pm1, pm2, pm3;
   reg [3:0] 	npm0norm, npm1norm, npm2norm, npm3norm;

   always @ (npm0 or npm1 or npm2 or npm3)
	 begin
	   if ((npm0 <= npm1)&&(npm0 <= npm2)&&(npm0 <= npm3))
	     begin
	       npm0norm <= 0;
	       npm1norm <= npm1-npm0;
	       npm2norm <= npm2-npm0;
	       npm3norm <= npm3-npm0;
	     end
	   else if ((npm1 <= npm0)&&(npm1 <= npm2)&&(npm1 <= npm3))
	     begin
	       npm0norm <= npm0-npm1;
	       npm1norm <= 0;
	       npm2norm <= npm2-npm1;
	       npm3norm <= npm3-npm1;
	     end
	   else if ((npm2 <= npm0)&&(npm2 <= npm1)&&(npm2 <= npm3))
	     begin
	       npm0norm <= npm0-npm2;
	       npm1norm <= npm1-npm2;
	       npm2norm <= 0;
	       npm3norm <= npm3-npm2;
	     end
	   else if ((npm3 <= npm0)&&(npm3 <= npm1)&&(npm3 <= npm2))
	     begin
	       npm0norm <= npm0-npm3;
	       npm1norm <= npm1-npm3;
	       npm2norm <= npm2-npm3;
	       npm3norm <= 0;
	     end
	 end // always @ (npm0 or npm1 or npm2 or npm3)

   always @ (posedge clk)
	 begin
		if (reset)
		  begin
		    pm0 <= 4'd0;
		    pm1 <= 4'd0;
		    pm2 <= 4'd0;
		    pm3 <= 4'd0;
		  end
		else
		  begin
		    pm0 <= npm0norm;
		    pm1 <= npm1norm;
		    pm2 <= npm2norm;
		    pm3 <= npm3norm;
		  end
	 end // always @ (posedge clk)
