reg [2:0] stage;
reg [2:0] reg_addr;
reg [7:0] reg_file [0:7];

always @(*) begin
    case (stage)
        0: begin
            a_reg = A;
            b_reg = B;
            stage = 1;
        end
        1: begin
            reg_addr = 0;
            stage = 2;
        end
        2: begin
            reg_file[reg_addr] = a_reg * b_reg;
            reg_addr = reg_addr + 1;
            if (reg_addr == 8) begin
                stage = 3;
            end
            else begin
                a_reg = reg_file[reg_addr];
            end
        end
        3: begin
            S = reg_file[7];
            stage = 0;
        end
    endcase
end

