  assign O1[3] = D_sync[4] & Q_sync & D_sync[5] & D_sync[6] & ~D_sync[7];
  assign O1[4] = D_sync[5] & D_sync[6] & D_sync[7] & ~Q_sync & ~D_sync[8];
  assign O1[5] = Q_sync & D_sync[6] & D_sync[7] & ~D_sync[5];
