module synchronous_serial_communication(
    input clock,
    input [1:0] speed,
    input [7:0] din,
    input start,
    input sdi,
    output reg bsync,
    output rdy,
    output sck,
    output sdo,
    output reg [7:0] dout
);

    reg [4:0] counter; // governs transmission
    reg [6:0] shiftin; // shifting in data from sdi before emitting it on dout
    reg [7:0] shiftout; // shifting out data to the sdo
    reg [2:0] wcnt; // counter for slow speeds
    wire enable_n; // =1 when transmission in progress
    wire ena_shout_load; // enable load of shiftout register
    wire g_ena; // enables transmission at slower speeds

    // rdy is enable_n
    assign rdy = enable_n;

    // sck is low bit of counter
    assign sck = counter[0];

    // enable_n is high bit of counter
    assign enable_n = counter[4];

    // sdo is high bit of shiftout
    assign sdo = shiftout[7];

    // condition for loading shiftout register
    assign ena_shout_load = (start | sck) & g_ena;

    // initialize internal registers
    initial begin
        counter = 5'b10000;
        shiftout = 8'd0;
        dout = 8'd0;
        bsync = 1'd0;
    end

    // transmission process
    always @(posedge clock) begin
        if (g_ena) begin
            if (start) begin
                counter <= 5'b00000; // enable_n = 0; sck = 0;
                bsync <= 1'b1; // begin bsync pulse
            end else begin
                if (!sck) begin // on the rising edge of sck
                    shiftin[6:0] <= {shiftin[5:0], sdi};
                    if ((&counter[3:1]) && (!enable_n)) begin
                        dout <= {shiftin[6:0], sdi}; // update dout at the last sck rising edge
                    end
                end else begin // on the falling edge of sck
                    bsync <= 1'b0;
                end
                if (!enable_n) begin
                    counter <= counter + 5'd1;
                end
            end
        end
    end

    // shiftout treatment is done so just to save LCELLs in acex1k
    always @(posedge clock) begin
        if (ena_shout_load) begin
            if (start) begin
                shiftout <= din;
            end else begin // sck
                shiftout[7:0] <= {shiftout[6:0], shiftout[0]}; // last bit remains after end of exchange
            end
        end
    end

    // slow speeds - governed by g_ena
    always @(posedge clock) begin
        if (speed != 2'b00) begin
            if (start) begin
                wcnt <= 3'b001;
            end else if (enable_n) begin
                wcnt <= 3'b000;
            end else begin
                wcnt <= wcnt + 3'd1;
            end
        end else begin
            wcnt <= 3'b000;
        end
    end

    // enable transmission at slower speeds
    assign g_ena = (speed == 2'b00) ? 1'b1 :
                   (speed == 2'b01) ? (wcnt[0] == 1'b0) :
                   (speed == 2'b10) ? (wcnt[1:0] == 2'b00) :
                                      (wcnt[2:0] == 3'b000);

endmodule

