module sfifo_31x128 (
    input [30:0] data,
    input wrreq,
    input rdreq,
    input clock,
    input aclr,
    output [30:0] q,
    output full,
    output empty,
    output [6:0] usedw,
    output almost_full
);

    parameter DEPTH = 128;
    parameter WIDTH = 31;

    reg [WIDTH-1:0] mem [DEPTH-1:0];
    reg [6:0] usedw_reg;
    reg full_reg;
    reg empty_reg;
    reg almost_full_reg;

    integer wr_ptr_reg;
    integer rd_ptr_reg;

    always @(posedge clock) begin
        if (aclr) begin
            wr_ptr_reg <= 0;
            rd_ptr_reg <= 0;
            usedw_reg <= 0;
            full_reg <= 0;
            empty_reg <= 1;
            almost_full_reg <= 0;
        end else begin
            if (wrreq && !full_reg) begin
                mem[wr_ptr_reg] <= data;
                wr_ptr_reg <= wr_ptr_reg + 1;
                usedw_reg <= usedw_reg + 1;
                if (wr_ptr_reg == DEPTH-1) wr_ptr_reg <= 0;
                if (usedw_reg == DEPTH) full_reg <= 1;
                if (usedw_reg >= DEPTH-8) almost_full_reg <= 1;
                empty_reg <= 0;
            end
            if (rdreq && !empty_reg) begin
                q <= mem[rd_ptr_reg];
                rd_ptr_reg <= rd_ptr_reg + 1;
                usedw_reg <= usedw_reg - 1;
                if (rd_ptr_reg == DEPTH-1) rd_ptr_reg <= 0;
                if (usedw_reg == 1) empty_reg <= 1;
                if (usedw_reg <= 8) almost_full_reg <= 0;
                full_reg <= 0;
            end
        end
    end

    assign usedw = usedw_reg;
    assign full = full_reg;
    assign empty = empty_reg;
    assign almost_full = almost_full_reg;

endmodule

module DRAMWriter(
    //AXI port
    input wire ACLK,
    input wire ARESETN,
    output reg [31:0] M_AXI_AWADDR,
    input wire M_AXI_AWREADY,
    output wire M_AXI_AWVALID,

    output wire [63:0] M_AXI_WDATA,
    output wire [7:0] M_AXI_WSTRB,
    input wire M_AXI_WREADY,
    output wire M_AXI_WVALID,
    output wire M_AXI_WLAST,

    input wire [1:0] M_AXI_BRESP,
    input wire M_AXI_BVALID,
    output wire M_AXI_BREADY,

    output wire [3:0] M_AXI_AWLEN,
    output wire [1:0] M_AXI_AWSIZE,
    output wire [1:0] M_AXI_AWBURST,

    //Control config
    input wire CONFIG_VALID,
    output wire CONFIG_READY,
    input wire [31:0] CONFIG_START_ADDR,
    input wire [31:0] CONFIG_NBYTES,

    //RAM port
    input wire [63:0] DATA,
    output wire DATA_READY,
    input wire DATA_VALID

);

parameter IDLE = 2'b00, WRITE = 2'b01, RWAIT = 2'b10, BRESP_WAIT = 2'b11;
parameter BRESP_OKAY = 2'b00, BRESP_EXOKAY = 2'b01, BRESP_SLVERR = 2'b10, BRESP_DECERR = 2'b11;

reg [31:0] a_count;
reg a_state;  
assign M_AXI_AWVALID = (a_state == RWAIT);
always @(posedge ACLK) begin
    if (ARESETN == 0) begin
        a_state <= IDLE;
        M_AXI_AWADDR <= 0;
        a_count <= 0;
    end else case(a_state)
        IDLE: begin
            if(CONFIG_VALID) begin
                M_AXI_AWADDR <= CONFIG_START_ADDR;
                a_count <= CONFIG_NBYTES[31:7];
                a_state <= RWAIT;
            end
        end
        RWAIT: begin
            if (M_AXI_AWREADY == 1) begin
                if(a_count - 1 == 0)
                    a_state <= IDLE;
                a_count <= a_count - 1;
                M_AXI_AWADDR <= M_AXI_AWADDR + 128; 
            end
        end
    endcase
end

reg [31:0] b_count;
reg w_state;
reg [3:0] last_count;
reg [1:0] bresp_state;

always @(posedge ACLK) begin
    if (ARESETN == 0) begin
        w_state <= IDLE;
        b_count <= 0;
        last_count <= 4'b1111;
        bresp_state <= BRESP_OKAY;
    end else case(w_state)
        IDLE: begin
            if(CONFIG_VALID) begin
                b_count <= {CONFIG_NBYTES[31:7],7'b0};
                w_state <= WRITE;
            end
        end
        WRITE: begin
            if (M_AXI_WREADY && M_AXI_WVALID) begin
                //use M_AXI_WDATA
                if(b_count - 8 == 0) begin
                    w_state <= IDLE;
                end
                last_count <= last_count - 4'b1;
                b_count <= b_count - 8;
            end
        end
    endcase
end

assign M_AXI_WLAST = last_count == 4'b0000;

assign M_AXI_WVALID = (w_state == WRITE) && DATA_VALID;

assign DATA_READY = (w_state == WRITE) && M_AXI_WREADY;

assign CONFIG_READY = (w_state == IDLE) && (a_state == IDLE);

assign M_AXI_BREADY = 1;

assign M_AXI_WDATA = DATA;

always @(posedge ACLK) begin
    if (ARESETN == 0) begin
        bresp_state <= BRESP_OKAY;
    end else case(bresp_state)
        BRESP_OKAY: begin
            if(M_AXI_BVALID) begin
                if(M_AXI_BRESP != 2'b00) begin
                    bresp_state <= BRESP_SLVERR;
                end else begin
                    if(w_state == WRITE) begin
                        bresp_state <= BRESP_WAIT;
                    end
                end
            end
        end
        BRESP_WAIT: begin
            if(M_AXI_BREADY) begin
                bresp_state <= BRESP_OKAY;
            end
        end
        BRESP_SLVERR: begin
            bresp_state <= BRESP_OKAY;
        end
    endcase
end

assign M_AXI_BRESP = bresp_state;

endmodule

