module t2(
    input [1:0] clks,
    input c0,
    input c1,
    input check,
    output reg o_check
);

    reg [1:0] state;
    parameter S0 = 2'b00, S1 = 2'b01, S2 = 2'b10, S3 = 2'b11;

    always @(posedge clks[1] or posedge clks[0]) begin
        case(state)
            S0: begin
                if(c0 && !c1)
                    state <= S1;
                else if(!c0 && c1)
                    state <= S2;
            end
            S1: begin
                if(c0 && !c1)
                    state <= S3;
                else if(!c0 && !c1)
                    state <= S0;
            end
            S2: begin
                if(!c0 && c1)
                    state <= S3;
                else if(c0 && !c1)
                    state <= S0;
            end
            S3: begin
                if(!c0 && !c1)
                    state <= S2;
                else if(c0 && c1)
                    state <= S1;
            end
        endcase
    end

    always @(posedge clks[1] or posedge clks[0]) begin
        if(state == S3 && check)
            o_check <= 1;
        else
            o_check <= 0;
    end

    initial state <= S0;

endmodule

module sequence_detector (
  input inp,
  output out
);

parameter n = 4; // length of shift register
parameter seq = "0011"; // desired input sequence (binary string)

reg [n-1:0] shift_reg; // shift register

// Define the predefined states that correspond to the desired input sequence
parameter [n-1:0] state_1 = {seq};
parameter [n-1:0] state_2 = {seq[1:n-1], seq[0]};
parameter [n-1:0] state_3 = {seq[2:n-1], seq[0:1]};
parameter [n-1:0] state_4 = {seq[3:n-1], seq[0:2]};

always @(posedge inp) begin
  // Shift the input into the shift register
  shift_reg <= {shift_reg[n-2:0], inp};

  // Compare the current state of the shift register to the predefined states
  if (shift_reg == state_1 || shift_reg == state_2 || shift_reg == state_3 || shift_reg == state_4) begin
    out <= 1; // Output a logic 1 if the current state matches one of the predefined states
  end else begin
    out <= 0; // Output a logic 0 otherwise
  end
end

endmodule

module Clock_Phase_Shifter(
  input clk,
  input [7:0] shift,
  output reg clk_shifted
);

  reg [7:0] delay_count;
  reg [7:0] delay_value;
  reg [7:0] max_delay;

  always @(posedge clk) begin
    if(delay_count < max_delay) begin
      delay_count <= delay_count + 1;
    end else begin
      delay_count <= 0;
    end

    if(delay_count == 0) begin
      clk_shifted <= clk;
    end else begin
      clk_shifted <= delay_value;
    end
  end

  always @(*) begin
    max_delay = (clk / 360) * shift;
    delay_value = #(max_delay / 2) 1'b0;
  end

endmodule

