    input S,
    input R,
    input D,
    input G,
    input E
);
    parameter [0:0] INIT = 1'b0;
    initial Q = INIT;
    always @*
      begin
        if (!R) 
          Q <= 1'b0;
        else if (!S) 
          Q <= 1'b1;
        else if (E && G) 
          Q <= D;
      end
endmodule

module alu (
    input [3:0] A,
    input [3:0] B,
    input [1:0] opcode,
    input shift,
    output [3:0] result
);

reg [3:0] alu_result;
reg [3:0] shifted_result;
reg [3:0] shifted_amount;

always @(*) begin
    case (opcode)
        2'b00: alu_result = A + B;
        2'b01: alu_result = A - B;
        2'b10: alu_result = A & B;
        2'b11: alu_result = A | B;
    endcase
end

always @(posedge shift) begin
    if (shift) begin
        shifted_amount <= B;
        shifted_result <= alu_result << shifted_amount;
    end else begin
        result <= alu_result;
    end
end

endmodule

