module mux2to1(
    input sel,
    input in0,
    input in1,
    output out
);

    wire m0, m1;
    wire [3:0] msel;

    // Build the selection signal for the 4-to-1 multiplexer
    assign msel = {sel, sel};

    // Instantiate the 4-to-1 multiplexer
    sky130_fd_sc_ls__mux_4to1 mux4to1(
        .sel(msel),
        .in0(in0),
        .in1(in1),
        .in2(1'b0),
        .in3(1'b0),
        .out(m0)
    );

    // Invert the selection signal for the 4-to-1 multiplexer
    assign msel = {~sel, ~sel};

    // Instantiate the 4-to-1 multiplexer
    sky130_fd_sc_ls__mux_4to1 mux4to1(
        .sel(msel),
        .in0(1'b0),
        .in1(1'b0),
        .in2(in0),
        .in3(in1),
        .out(m1)
    );

    // Select the appropriate output from the two 4-to-1 multiplexers
    assign out = sel ? m1 : m0;

endmodule

module tiny1_soc(
                 input        clk,
                 input        rst, // external rest button

		 input [7:0]  uart_din,
		 input        uart_valid,
		 output [7:0] uart_out,
		 output       uart_out_ready,

                 output       just_die_already
                 );


   wire [15:0]         for_mem_addr;
   wire [15:0]         for_mem_data_i_ram;
   wire [15:0]         for_mem_data_o;
   wire                for_mem_wr;
   wire                for_mem_re;

   // 16kb ram, one for all of the following:
   //      16x16 virtual registers
   //      16x16 IRQ mode virtual registers
   //      32x16 microcode handlers table
   //      large microcode buffer
   //      and everything else
   ram16k ram(.clk(clk),
              .addr(for_mem_addr[14:1]),
              .data_out(for_mem_data_i_ram),
              .data_in(for_mem_data_o),
              .we(for_mem_wr),
              .re(for_mem_re));

   // May be a memory-mapped I/O instead of a genuine memory access
   wire                mem_wr_from_core;
   wire                mem_re_from_core;

   // Thin UART interface via mmap
   wire                uart_ready;
   wire                irqack;

   wire [15:0]         mem_data_i_for_core;
   wire [15:0]         mem_data_o_from_core;
   wire [15:0]         mem_addr_from_core;

   assign for_mem_addr = mem_addr_from_core;
   assign for_mem_data_o = mem_data_o_from_core;


   tiny1_core cpu(.clk(clk),
                  .rst(rst),

                  .irq(uart_valid),
                  .irqack(irqack),

                  .mem_addr(mem_addr_from_core),
                  .mem_data_o(mem_data_o_from_core),
                  .mem_data_i(mem_data_i_for_core),
                  .ram_data_i(for_mem_data_i_ram),

                  .mem_wr(mem_wr_from_core),
                  .mem_rd(mem_re_from_core));

   reg [15:0]         mem_data_i_mmap;
   wire [15:0]        data_i_mmap_cl;

   wire                mmap;
   assign mmap = mem_addr_from_core[15]; // if bit 15 set, it's mmap io
   assign for_mem_wr = !mmap?mem_wr_from_core:0;
   assign for_mem_re = !mmap?mem_re_from_core:0;

   assign mem_data_i_for_core = mmap?mem_data_i_mmap:for_mem_data_i_ram;


   // IRQ logic:
   //   if uart_valid && !irqack, set IRQ

   // mmap io:
   // Read ports:
   //  IO_UART_VALID  - valid input from UART
   //  IO_UART_DIN    - 8 bits from UART
   //  IO_UART_READY  - 1 if ready to send

   // Write ports:
   //  IO_UART_DOUT   - 8 bits to UART

   parameter IO_UART_VALID = 0;
   parameter IO_UART_DIN = 2;
   parameter IO_UART_READY = 4;
   parameter IO_UART_DOUT = 6;

   parameter IO_HALT = 512;


   wire [10:0]          mmapaddr;

   assign mmapaddr = mem_addr_from_core[10:0];
   assign uart_ready = 1'b1;

   assign data_i_mmap_cl = (mmapaddr == IO_UART_VALID)?{15'b0, uart_valid}:
                           (mmapaddr == IO_UART_DIN)?{8'b0,uart_din}:
                           (mmapaddr == IO_UART_READY)?{15'b0, uart_ready}:16'b0;

   assign uart_out_ready = (mmap && mmapaddr == IO_UART_DOUT && mem_wr_from_core);

   assign just_die_already = (mmap && mmapaddr == IO_HALT && mem_wr_from_core);

   assign uart_out = mem_data_o_from_core[7:0];

   // register the mmap output
   always @(posedge clk)
     begin
        mem_data_i_mmap <= data_i_mmap_cl;
     end


endmodule

module memory_system (
    input  wire clk,

    input  wire rx,
    output wire tx,

    input  wire [15:0] sw,
    output wire [15:0] led
);
    wire rden;
    reg wren;
    wire [9:0] rdaddr;
    wire [9:0] wraddr;
    wire [15:0] di;
    wire [15:0] do;
    ram0 ram(
        .wrclk(clk),
        .di(di),
        .wren(wren),
        .wraddr(wraddr),
        .rdclk(clk),
        .rden(rden),
        .rdaddr(rdaddr),
        .do(do)
    );

    reg [9:0] address_reg;
    reg [15:0] data_reg;
    reg [15:0] out_reg;

    assign rdaddr = address_reg;
    assign wraddr = address_reg;

    wire [1:0] display_mode;
    wire [1:0] input_mode;
    wire we;

    assign display_mode[0] = sw[14];
    assign display_mode[1] = sw[15];

    assign input_mode[0] = sw[12];
    assign input_mode[1] = sw[13];

    assign we = sw[11];
    assign led = out_reg;
    assign di = data_reg;
    assign rden = 1;

    initial begin
        address_reg = 10'b0;
        data_reg = 16'b0;
        out_reg = 16'b0;
    end

    always @ (posedge clk) begin
        if(display_mode == 0) begin
            out_reg <= do;
        end else if(display_mode == 1) begin
            out_reg <= address_reg;
        end else if(display_mode == 2) begin
            out_reg <= data_reg;
        end

        if(we == 1) begin
            if(input_mode == 0) begin
                address_reg <= sw[9:0];
                wren <= 0;
            end else if(input_mode == 1) begin
                data_reg[7:0] <= sw[7:0];
                wren <= 0;
            end else if(input_mode == 2) begin
                data_reg[15:8] <= sw[7:0];
                wren <= 0;
            end else if(input_mode == 3) begin
                wren <= 1;
            end
        end
    end

    assign tx = rx;
endmodule

module edge_detect_mux (
    input clk,
    input reset,
    input [7:0] in,
    output reg [3:0] out,
    output reg [2:0] select,
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5
);

reg [1:0] state;
reg [7:0] prev_in;
reg [3:0] mux_select;

always @(posedge clk) begin
    if (reset) begin
        state <= 2'b00;
        prev_in <= 8'b0;
        mux_select <= 4'b0000;
        select <= 3'b111;
        out <= 4'b0000;
    end else begin
        case (state)
            2'b00: begin
                prev_in <= in;
                state <= 2'b01;
            end
            2'b01: begin
                if (in > prev_in) begin
                    state <= 2'b10;
                    mux_select <= mux_select + 1;
                end else if (in < prev_in) begin
                    state <= 2'b10;
                    mux_select <= mux_select + 1;
                end else begin
                    state <= 2'b00;
                end
                prev_in <= in;
            end
            2'b10: begin
                if (mux_select > 5) begin
                    state <= 2'b00;
                    mux_select <= 4'b0000;
                    select <= 3'b111;
                    out <= 4'b0000;
                end else begin
                    select <= mux_select;
                    case (mux_select)
                        4'b0000: out <= data0;
                        4'b0001: out <= data1;
                        4'b0010: out <= data2;
                        4'b0011: out <= data3;
                        4'b0100: out <= data4;
                        4'b0101: out <= data5;
                        default: out <= 4'b0001;
                    endcase
                    state <= 2'b00;
                end
            end
        endcase
    end
end

endmodule

module D_flip_flop (
    input clk,
    input reset,
    input d,
    output reg q
);

reg s, r;

always @(posedge clk, posedge reset) begin
    if (reset) begin
        s <= 0;
        r <= 1;
        q <= 0;
    end else begin
        s <= d;
        r <= ~d;
        q <= s & q | r & ~q;
    end
end

endmodule

