module sky130_fd_sc_ls__dlymetal6s2s (
    X   ,
    A   ,
    VPWR,
    VGND,
    VPB ,
    VNB
);

    output X   ;
    input  A   ;
    input  VPWR;
    input  VGND;
    input  VPB ;
    input  VNB ;

    reg [7:0] shift_reg;
    reg [7:0] delay;
    reg [7:0] count;

    always @ (posedge VPWR or negedge VGND or posedge VPB or negedge VNB) begin
        delay <= (VPWR - VGND) * (VPB - VNB);
        count <= 0;
    end

    always @ (posedge clk) begin
        if (count < delay) begin
            shift_reg <= {shift_reg[6:0], A};
            count <= count + 1;
        end
    end

    assign X = shift_reg[7];

endmodule

module top_module (
    input clk,
    input pause,
    input reset,
    input a,
    input b,
    output reg [3:0] q,
    output reg out
);

    // Implement XOR gate using behavioral always block
    always @ (a, b) begin
        out = a ^ b;
    end

    // Implement XOR gate using structural implementation using a MUX
    wire mux_sel = pause;
    wire [1:0] mux_in = {q[0], out};
    wire mux_out;
    assign mux_out = mux_sel ? mux_in[1] : mux_in[0];

    // Implement decade counter using Johnson counter and D flip-flop
    reg [3:0] johnson_out;
    always @ (posedge clk, negedge reset) begin
        if (!reset) begin
            johnson_out <= 4'b0001;
        end else begin
            johnson_out <= {johnson_out[2:0], ~johnson_out[3]};
        end
    end

    reg [3:0] dff_out;
    always @ (posedge clk, negedge reset) begin
        if (!reset) begin
            dff_out <= 4'b0000;
        end else if (!pause) begin
            dff_out <= johnson_out;
        end
    end

    // Output the XOR gate output when paused, and the current count value when not paused
    always @ (posedge clk) begin
        if (pause) begin
            q <= dff_out;
        end else begin
            q <= johnson_out;
        end
    end

endmodule

module clock_generator(
    input CLKIN48,
    input IFCLK,
    input MOSI,
    input SS,
    input SCLK,
    output LED,
    output MISO,
    output [7:0] PORT_B,
    output [7:0] PORT_D,
    output RDY0
);

wire clksel, clkgen_rst, clklock; // async
wire fastclk, normalclk, ifclk_int;

wire fifo_valid_out;        // ifclk
wire [15:0] fifo_data_out;  // - " -

IBUFG clk48_ibuf(.I(CLKIN48), .O(normalclk));

OBUF fifo_valid_buf(.I(fifo_valid_out), .O(RDY0));
multi_obuf #(16) fifo_data_buf(.I(fifo_data_out), .O({PORT_D, PORT_B}));

clock_generators clkgen (.clk48(normalclk), .IFCLK(IFCLK),
			 .clkgen_rst(clkgen_rst),
			 .clksel(clksel), .fastclk(fastclk),
			 .ifclk_out(ifclk_int), .clocks_locked(clklock));

wire fifo_reset; // async

wire [15:0] sample_data;  // fast clock domain
wire sample_data_avail;   // - " -
wire fifo_overflow;       // - " -
wire fcd_rst;             // - " -

wire ncd_rst;             // normal clock domain

fifo_generator_v9_3 fifo(.rst(fifo_reset), .wr_clk(fastclk), .rd_clk(ifclk_int),
                         .din(sample_data), .wr_en(sample_data_avail),
                         .rd_en(~SS), .dout(fifo_data_out),
                         .full(), .overflow(fifo_overflow),
                         .empty(), .valid(fifo_valid_out));

// normal clock domain -> fast clock domain
wire acq_enable_ncd, acq_enable_fcd;
wire acq_reset_ncd, acq_reset_fcd;
wire [7:0] clkdiv_ncd, clkdiv_fcd;
wire [15:0] channel_enable_ncd, channel_enable_fcd;

// fast clock domain -> normal clock domain
wire acq_stalled_fcd, acq_stalled_ncd;

synchronizer clklock_sync (.clk(normalclk), .in(clklock), .out(clklock_ncd));

normal_clock_domain ncd(.clk(normalclk), .rst(ncd_rst), .miso(MISO),
			.mosi(MOSI), .ss(SS), .sclk(SCLK), .led_out(LED),
			.acq_enable(acq_enable_ncd), .acq_reset(acq_reset_ncd),
			.clock_select(clksel), .clock_divisor(clkdiv_ncd),
			.channel_enable(channel_enable_ncd),
			.fifo_overflow(acq_stalled_ncd), .clklock(clklock_ncd));

synchronizer acq_enable_sync (.clk(fastclk),
			      .in(acq_enable_ncd), .out(acq_enable_fcd));

synchronizer acq_reset_sync (.clk(fastclk),
			     .in(acq_reset_ncd), .out(acq_reset_fcd));

synchronizer #(8) clkdiv_sync (.clk(fastclk),
			       .in(clkdiv_ncd), .out(clkdiv_fcd));

synchronizer #(16) channel_enable_sync (.clk(fastclk),
					.in(channel_enable_ncd),
					.out(channel_enable_fcd));

synchronizer acq_stalled_sync (.clk(normalclk),
			       .in(acq_stalled_fcd), .out(acq_stalled_ncd));

fast_clock_domain fcd(.clk(fastclk), .rst(fcd_rst), .probe(16'h0000),
		      .sample_data(sample_data),
		      .sample_data_avail(sample_data_avail),
		      .overflow(fifo_overflow),
		      .acq_enable(acq_enable_fcd),
		      .clock_divisor(clkdiv_fcd),
		      .channel_enable(channel_enable_fcd),
		      .stalled(acq_stalled_fcd));

assign fcd_rst = acq_reset_fcd;
assign fifo_reset = acq_reset_fcd;

// Global reset
reset_generator rst_gen (.clk(normalclk), .rst(ncd_rst));
assign clkgen_rst = ncd_rst;

endmodule

module top_module ( 
    input wire [3:0] in,
    input wire [2:0] vec,
    input wire select,
    output wire [2:0] outv,
    output wire o2,
    output wire o1,
    output wire o0
);

    // Instantiate the first module
    and_or_xor_module aox (
        .in1(in[0]),
        .in2(in[1]),
        .in3(in[2]),
        .in4(in[3]),
        .and_out(aox_and_out),
        .or_out(aox_or_out),
        .xor_out(aox_xor_out)
    );

    // Instantiate the functional module
    functional_module func (
        .vec_in(vec),
        .and_in(aox_and_out),
        .vec_out(outv),
        .o2(o2),
        .o1(o1),
        .o0(o0)
    );

    // Select between the two modules based on the select input
    assign {o2, o1, o0, outv} = select ? {vec[2], vec[1], vec[0], 3'b0} : {3'b0, aox_and_out, aox_or_out, aox_xor_out};

endmodule


module and_or_xor_module (
    input wire in1,
    input wire in2,
    input wire in3,
    input wire in4,
    output wire and_out,
    output wire or_out,
    output wire xor_out
);

    assign and_out = in1 & in2 & in3 & in4;
    assign or_out = in1 | in2 | in3 | in4;
    assign xor_out = in1 ^ in2 ^ in3 ^ in4;

endmodule


module functional_module (
    input wire [2:0] vec_in,
    input wire and_in,
    output wire [2:0] vec_out,
    output wire o2,
    output wire o1,
    output wire o0
);

    assign vec_out = vec_in;
    assign {o2, o1, o0} = vec_in;

    and_gate and_inst (
        .in1(and_in),
        .in2(vec_in[0]),
        .out(o0)
    );

endmodule


