module priority_encoder_pipeline (
    input [3:0] in,
    output reg [1:0] pos
);

reg [1:0] stage1_out, stage2_out;

always @ (posedge clk) begin
    stage1_out <= {in[1], in[0]};
    stage2_out <= {in[3], in[2]};
    pos <= 2'b00;
    if (stage2_out[1]) pos <= 2'b11;
    else if (stage2_out[0]) pos <= 2'b10;
    else if (stage1_out[1]) pos <= 2'b01;
    else if (stage1_out[0]) pos <= 2'b00;
end

endmodule

module bcd_counter (
    input clk,
    input reset,   // Synchronous active-high reset
    input [2:0] ena,
    output reg [15:0] q
);

reg [3:0] count;

always @(posedge clk) begin
    if (reset) begin
        count <= 4'b0000;
        q <= 16'b0000000000000000;
    end
    else begin
        if (ena[0])
            count[0] <= count[0] + 1;
        if (ena[1])
            count[1] <= count[1] + 1;
        if (ena[2])
            count[2] <= count[2] + 1;
        count[3] <= count[3] + 1;

        case (count)
            4'b0000: q <= 16'b0000000000000000;
            4'b0001: q <= 16'b0000000000000001;
            4'b0010: q <= 16'b0000000000000010;
            4'b0011: q <= 16'b0000000000000011;
            4'b0100: q <= 16'b0000000000000100;
            4'b0101: q <= 16'b0000000000000101;
            4'b0110: q <= 16'b0000000000000110;
            4'b0111: q <= 16'b0000000000000111;
            4'b1000: q <= 16'b0000000000010000;
            4'b1001: q <= 16'b0000000000010001;
            4'b1010: q <= 16'b0000000000010010;
            4'b1011: q <= 16'b0000000000010011;
            4'b1100: q <= 16'b0000000000010100;
            4'b1101: q <= 16'b0000000000010101;
            4'b1110: q <= 16'b0000000000010110;
            4'b1111: q <= 16'b0000000000010111;
        endcase
    end
end

endmodule

module mux_2to1 (
    input a,
    input b,
    input sel,
    output reg out
);

always @(a, b, sel) begin
    if (sel)
        out <= b;
    else
        out <= a;
end

endmodule

module final_module (
    input [15:0] q,
    input a,
    input b,
    input sel,
    output reg out
);

wire [2:0] ena;
bcd_counter counter(.clk(clk), .reset(reset), .ena(ena), .q(q));
mux_2to1 mux(.a(a), .b(b), .sel(sel), .out_always(out_always));

always @(q, a, b, sel) begin
    if (q[3:0] == 4'b0000 && q[7:4] == 4'b0000 && q[11:8] == 4'b0000 && q[15:12] == 4'b0000)
        out <= 1'b0;
    else if (q[3:0] == 4'b1000 && q[7:4] == 4'b0000 && q[11:8] == 4'b0000 && q[15:12] == 4'b0000)
        out <= a;
    else if (q[3:0] == 4'b0000 && q[7:4] == 4'b1000 && q[11:8] == 4'b0000 && q[15:12] == 4'b0000)
        out <= b;
    else if (q[3:0] == 4'b0000 && q[7:4] == 4'b0000 && q[11:8] == 4'b1000 && q[15:12] == 4'b0000)
        out <= a & b;
    else if (q[3:0] == 4'b0000 && q[7:4] == 4'b0000 && q[11:8] == 4'b0000 && q[15:12] == 4'b1000)
        out <= mux.out;
end

assign ena = {q[3], q[7], q[11]};

endmodule

