module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    input carry_in,
    output [3:0] sum,
    output carry_out
);

reg [3:0] A_reg, B_reg, sum_reg;
reg carry_in_reg, carry_out_reg;

always @(posedge clk) begin
    A_reg <= A;
    B_reg <= B;
    sum_reg <= A_reg + B_reg + carry_in_reg;
    carry_out_reg <= (A_reg[3] & B_reg[3]) | (A_reg[3] & carry_in_reg) | (B_reg[3] & carry_in_reg);
end

assign sum = sum_reg;
assign carry_out = carry_out_reg;

endmodule

module priority_encoder (
    input [7:0] in [0:3],
    output reg [1:0] out);

    always @(*) begin
        case ({in[0]>in[1], in[1]>in[2], in[2]>in[3]})
            3'b000: out = 2'b00;
            3'b001: out = 2'b01;
            3'b011: out = 2'b10;
            3'b111: out = 2'b11;
        endcase
    end
endmodule

