module fifo_15x16 (
    aclr,
    clock,
    data,
    rdreq,
    wrreq,
    almost_full,
    empty,
    full,
    q,
    usedw
);

input aclr;
input clock;
input [15:0] data;
input rdreq;
input wrreq;
output almost_full;
output empty;
output full;
output [15:0] q;
output [3:0] usedw;

reg [15:0] fifo [0:14];
reg [3:0] head, tail;
wire [3:0] usedw = head - tail;
wire [3:0] next_head = head + 1;
wire [3:0] next_tail = tail + 1;
wire [3:0] next_next_tail = tail + 2;
wire [15:0] q = fifo[tail];
wire almost_full = (usedw >= 12);
wire empty = (usedw == 0);
wire full = (usedw == 15);

always @(posedge clock or posedge aclr) begin
    if (aclr) begin
        head <= 0;
        tail <= 0;
        fifo[0] <= 16'h0000;
    end else begin
        if (wrreq && !full) begin
            fifo[next_head] <= data;
            head <= next_head;
        end
        if (rdreq && !empty) begin
            tail <= next_tail;
        end
    end
end

endmodule

module parity_check (
    input clk,
    input reset_n,
    input [7:0] data_in,
    output reg parity_out
);

reg [3:0] parity;

always @ (posedge clk) begin
    if (!reset_n) begin
        parity <= 0;
        parity_out <= 0;
    end
    else begin
        parity <= parity ^ data_in;
        parity_out <= (parity[0] ^ parity[1] ^ parity[2] ^ parity[3]);
    end
end

endmodule

module carry_select_adder(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output C0,
    output C1
);

wire [3:0] S0, S1;
wire C0_0, C0_1, C1_0, C1_1;

// First adder
full_adder FA0(A[0], B[0], Cin, S0[0], C0_0);
full_adder FA1(A[1], B[1], Cin, S0[1], C0_1);
full_adder FA2(A[2], B[2], Cin, S0[2], C1_0);
full_adder FA3(A[3], B[3], Cin, S0[3], C1_1);

// Second adder
full_adder FA4(A[0], B[0], C0_0, S1[0], C0);
full_adder FA5(A[1], B[1], C0_1, S1[1], C1_0);
full_adder FA6(A[2], B[2], C1_1, S1[2], C1_1);
full_adder FA7(A[3], B[3], C1_1, S1[3], C1);

assign S = {S1, S0};

endmodule

module carry_lookahead_adder(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

wire [3:0] P, G;
wire [3:0] C;

// Generate P and G signals
assign P = A ^ B;
assign G = A & B;

// Generate carry chain
assign C[0] = Cin;
assign C[1] = G[0] | (P[0] & C[0]);
assign C[2] = G[1] | (P[1] & C[1]);
assign C[3] = G[2] | (P[2] & C[2]);
assign Cout = G[3] | (P[3] & C[3]);

// Generate sum
assign S = A + B + Cin;

endmodule

