module pipelined_multiplier(
    input [31:0] a,
    input [31:0] b,
    input enable,
    output reg [31:0] result
);

wire [15:0] a_lsb = a[15:0];
wire [15:0] a_msb = a[31:16];
wire [15:0] b_lsb = b[15:0];
wire [15:0] b_msb = b[31:16];

reg [31:0] mul16_1_result;
reg [31:0] mul16_2_result;

mul16 mul16_1(.a(a_lsb), .b(b_lsb), .result(mul16_1_result));
mul16 mul16_2(.a(a_msb), .b(b_msb), .result(mul16_2_result));

always @(posedge clk) begin
    if (enable) begin
        result <= mul16_1_result + (mul16_2_result << 16);
    end
end

endmodule

module DEMUX (
  input in,
  input [n-1:0] sel,
  output [2**n-1:0] out
);

parameter n = 3; // number of select signals

assign out[0] = (sel == 0) ? in : 1'b0; // If all select signals are zero, route input signal to out[0]
assign out[2**n-1] = (sel == (2**n-1)) ? in : 1'b0; // If all select signals are one, route input signal to out[2^n-1]

// For all other combinations of select signals, route input signal to the corresponding output signal
genvar i;
generate
  for (i = 0; i < 2**n; i = i + 1) begin : DEMUX_GEN
    assign out[i] = (sel == i) ? in : 1'b0;
  end
endgenerate

endmodule

module ll8_to_fifo19
  (input clk, input reset, input clear,
   input [7:0] ll_data,
   input ll_sof,
   input ll_eof,
   input ll_src_rdy,
   output ll_dst_rdy,

   output [18:0] f19_data,
   output f19_src_rdy_o,
   input f19_dst_rdy_i );

   // Short FIFO on input to guarantee no deadlock
   wire [7:0] ll_data_int;
   wire       ll_sof_int, ll_eof_int, ll_src_rdy_int, ll_dst_rdy_int;

   ll8_shortfifo head_fifo
     (.clk(clk), .reset(reset), .clear(clear),
      .datain(ll_data), .sof_i(ll_sof), .eof_i(ll_eof),
      .error_i(0), .src_rdy_i(ll_src_rdy), .dst_rdy_o(ll_dst_rdy),
      .dataout(ll_data_int), .sof_o(ll_sof_int), .eof_o(ll_eof_int),
      .error_o(), .src_rdy_o(ll_src_rdy_int), .dst_rdy_i(ll_dst_rdy_int));

   // Actual ll8_to_fifo19 which could deadlock if not connected to a shortfifo
   localparam XFER_EMPTY       = 0;
   localparam XFER_HALF        = 1;
   localparam XFER_HALF_WRITE  = 3;

   wire [18:0] f19_data_int;
   wire        f19_sof_int, f19_eof_int, f19_occ_int, f19_src_rdy_int, f19_dst_rdy_int;

   wire        xfer_out    = f19_src_rdy_int & f19_dst_rdy_int;
   wire        xfer_in 	   = ll_src_rdy_int & ll_dst_rdy_int; 
   reg 	       hold_sof;

   reg [1:0]   state;
   reg [7:0]   hold_reg;

   always @(posedge clk)
     if(ll_src_rdy_int & (state==XFER_EMPTY))
       hold_reg 	      <= ll_data_int;

   always @(posedge clk)
     if(ll_sof_int & (state==XFER_EMPTY))
       hold_sof 	      <= 1;
     else if(xfer_out)
       hold_sof 	      <= 0;

   always @(posedge clk)
     if(reset | clear)
       state 		      <= XFER_EMPTY;
     else
       case(state)
	 XFER_EMPTY :
	   if(ll_src_rdy_int)
	     if(ll_eof_int)
	       state 	      <= XFER_HALF_WRITE;
	     else
	       state 	      <= XFER_HALF;
	 XFER_HALF :
	   if(ll_src_rdy_int & f19_dst_rdy_int)
	       state 	      <= XFER_EMPTY;
         XFER_HALF_WRITE :
	   if(f19_dst_rdy_int)
	     state 	<= XFER_EMPTY;
       endcase // case (state)

   assign ll_dst_rdy_int = (state==XFER_EMPTY) | ((state==XFER_HALF)&f19_dst_rdy_int);
   assign f19_src_rdy_int= (state==XFER_HALF_WRITE) | ((state==XFER_HALF)&ll_src_rdy_int);

   assign f19_sof_int 	 = hold_sof | (ll_sof_int & (state==XFER_HALF));
   assign f19_eof_int 	 = (state == XFER_HALF_WRITE) | ll_eof_int;
   assign f19_occ_int 	 = (state == XFER_HALF_WRITE);

   assign f19_data_int 	 = {f19_occ_int,f19_eof_int,f19_sof_int,hold_reg,ll_data_int};

   // Shortfifo on output to guarantee no deadlock
   fifo_short #(.WIDTH(19)) tail_fifo
     (.clk(clk),.reset(reset),.clear(clear),
      .datain(f19_data_int), .src_rdy_i(f19_src_rdy_int), .dst_rdy_o(f19_dst_rdy_int),
      .dataout(f19_data), .src_rdy_o(f19_src_rdy_o), .dst_rdy_i(f19_dst_rdy_i),
      .space(),.occupied() );


endmodule

module SPIBus(
  // Primary SPI bus.
  input main_nss,
  input main_sck,
  input main_mosi,
  output main_miso,

  // Secondary SPI bus.
  input alt_nss,
  input alt_sck,
  input alt_mosi,
  output alt_miso,

  // Output SPI bus.
  output reg nss,
  output reg sck,
  output reg mosi,
  input miso
);

  // Each bus is granted access when its select is asserted and the other bus'
  // select is not asserted.
  wire alt_bus_enabled = (alt_nss == 'b0) & (main_nss == 'b1);
  wire main_bus_enabled = (alt_nss == 'b1) & (main_nss == 'b0);

  // Multiplex the two SPI buses.
  // nSS should be allowed to assert only if only one bus is asserting it.
  // This avoids undefined behavior when the main bus interrupts the secondary
  // bus.
  always @ (*) begin
