module unsigned_sqrt (
    input [3:0] num,
    output reg [3:0] sqrt
);

reg [3:0] temp;
reg [1:0] i;

always @(*) begin
    temp = 0;
    for (i = 2; i >= 0; i = i - 1) begin
        temp[i+1:0] = temp[i+1:0] | (num[i+1:0] >> (2-i));
        if (temp >= 8) begin
            temp[i+1:0] = temp[i+1:0] - (1 << (2-i));
            sqrt[i] = 1;
        end else begin
            sqrt[i] = 0;
        end
    end
end

