module lfsr_prbs_gen #(
    parameter LFSR_WIDTH = 9,
    parameter LFSR_POLY = 9'h021,
    parameter LFSR_INIT = {LFSR_WIDTH{1'b1}},
    parameter LFSR_CONFIG = "FIBONACCI",
    parameter REVERSE = 0,
    parameter INVERT = 0,
    parameter DATA_WIDTH = 8,
    parameter STYLE = "AUTO"
) (
    input clk,
    input rst,
    input enable,
    output reg [DATA_WIDTH-1:0] data_out
);

reg [LFSR_WIDTH-1:0] lfsr_reg;
reg [LFSR_WIDTH-1:0] lfsr_poly;
reg [DATA_WIDTH-1:0] data_reg;

integer i;

initial begin
    // initialize LFSR and polynomial
    lfsr_reg <= LFSR_INIT;
    lfsr_poly <= LFSR_POLY;
end

always @(posedge clk) begin
    if (rst) begin
        // reset LFSR and data registers
        lfsr_reg <= LFSR_INIT;
        data_reg <= 0;
    end else if (enable) begin
        // shift LFSR
        if (LFSR_CONFIG == "FIBONACCI") begin
            lfsr_reg <= {lfsr_reg[LFSR_WIDTH-2:0], lfsr_reg[LFSR_WIDTH-1] ^ lfsr_reg[LFSR_POLY-1]};
        end else if (LFSR_CONFIG == "GALOIS") begin
            lfsr_reg <= {lfsr_reg[LFSR_WIDTH-2:0], lfsr_reg[0]};
            for (i = 0; i < LFSR_WIDTH-1; i = i + 1) begin
                if (lfsr_reg[LFSR_WIDTH-1]) begin
                    lfsr_reg[i] <= lfsr_reg[i] ^ lfsr_poly[i];
                end
            end
        end

        // generate output data
        if (REVERSE) begin
            data_reg <= {lfsr_reg[LFSR_WIDTH-1:0]} ^ {DATA_WIDTH{1'b1}};
        end else begin
            data_reg <= lfsr_reg[LFSR_WIDTH-1:0];
        end

        if (INVERT) begin
            data_out <= ~data_reg;
        end else begin
            data_out <= data_reg;
        end
    end
end

endmodule

