  output sum,
  output cout
);

  assign sum = a ^ b ^ cin;
  assign cout = (a & b) | (a & cin) | (b & cin);

endmodule

module pcieInterface(
  input  wire        sys_clkp,     // System Clock +
  input  wire        sys_clkn,     // System Clock -
  input  wire        pci_clkp,     // PCIe Clock +
  input  wire        pci_clkn,     // PCIe Clock -
  input  wire        pci_reset_n,  // PCIe Reset
  input  wire [7:0]  pci_rxp,      // PCIe receive lane positive
  input  wire [7:0]  pci_rxn,      // PCIe receive lane negative
  input  wire        pps_in,      // PPS input signal
  output wire [7:0]  pci_txp,     // PCIe transmit lane positive
  output wire [7:0]  pci_txn,     // PCIe transmit lane negative
  output wire [2:0]  led,         // LED control signal
  output wire        pps_out      // PPS output signal
);

reg [7:0] pci_txp_reg;
reg [7:0] pci_txn_reg;
reg [2:0] led_reg;
reg        pps_out_reg;

always @(posedge sys_clkp) begin
  // PPS output signal is synchronized to the system clock
  pps_out_reg <= pps_in;
end

always @(posedge pci_clkp) begin
  if (!pci_reset_n) begin
    // Reset all output signals
    pci_txp_reg <= 8'b0;
    pci_txn_reg <= 8'b0;
    led_reg <= 3'b0;
  end else begin
    // Transmit received data
    pci_txp_reg <= pci_rxp;
    pci_txn_reg <= pci_rxn;

    // Control LEDs based on received data
    case (pci_rxp[2:0])
      3'b000: led_reg <= 3'b000;
      3'b001: led_reg <= 3'b001;
      3'b010: led_reg <= 3'b010;
      3'b011: led_reg <= 3'b011;
      3'b100: led_reg <= 3'b100;
      3'b101: led_reg <= 3'b101;
      3'b110: led_reg <= 3'b110;
      3'b111: led_reg <= 3'b111;
    endcase
  end
end

assign pci_txp = pci_txp_reg;
assign pci_txn = pci_txn_reg;
assign led = led_reg;
assign pps_out = pps_out_reg;

endmodule

module conv_encoder (
  input [k-1:0] in,
  output [n-1:0] out
);

parameter k = 1024; // number of input bits
parameter n = 2048; // number of output bits
parameter r = 8;    // number of parity bits

reg [r-1:0] state;
reg [r-1:0] next_state;
reg [r-1:0] parity;

always @ (in or state) begin
  case (state)
    0: begin
      parity = {in[0],in[1],in[2],in[3],in[4],in[5],in[6],in[7]} ^ {in[1],in[2],in[3],in[4],in[5],in[6],in[7],in[8]};
      next_state = {state[6:0],in[0]};
    end
    1: begin
      parity = {in[1],in[2],in[3],in[4],in[5],in[6],in[7],in[8]} ^ {in[2],in[3],in[4],in[5],in[6],in[7],in[8],in[9]};
      next_state = {state[6:0],in[1]};
    end
    2: begin
      parity = {in[2],in[3],in[4],in[5],in[6],in[7],in[8],in[9]} ^ {in[3],in[4],in[5],in[6],in[7],in[8],in[9],in[10]};
      next_state = {state[6:0],in[2]};
    end
    3: begin
      parity = {in[3],in[4],in[5],in[6],in[7],in[8],in[9],in[10]} ^ {in[4],in[5],in[6],in[7],in[8],in[9],in[10],in[11]};
      next_state = {state[6:0],in[3]};
    end
    4: begin
      parity = {in[4],in[5],in[6],in[7],in[8],in[9],in[10],in[11]} ^ {in[5],in[6],in[7],in[8],in[9],in[10],in[11],in[12]};
      next_state = {state[6:0],in[4]};
    end
    5: begin
      parity = {in[5],in[6],in[7],in[8],in[9],in[10],in[11],in[12]} ^ {in[6],in[7],in[8],in[9],in[10],in[11],in[12],in[13]};
      next_state = {state[6:0],in[5]};
    end
    6: begin
      parity = {in[6],in[7],in[8],in[9],in[10],in[11],in[12],in[13]} ^ {in[7],in[8],in[9],in[10],in[11],in[12],in[13],in[14]};
      next_state = {state[6:0],in[6]};
    end
    7: begin
      parity = {in[7],in[8],in[9],in[10],in[11],in[12],in[13],in[14]} ^ {in[8],in[9],in[10],in[11],in[12],in[13],in[14],in[15]};
      next_state = {state[6:0],in[7]};
    end
  endcase
end

always @ (state) begin
  case (state)
    0: out = {in,parity[0],parity[1],parity[2],parity[3],parity[4],parity[5],parity[6],parity[7]};
    1: out = {parity[0],in,parity[1],parity[2],parity[3],parity[4],parity[5],parity[6],parity[7]};
    2: out = {parity[0],parity[1],in,parity[2],parity[3],parity[4],parity[5],parity[6],parity[7]};
    3: out = {parity[0],parity[1],parity[2],in,parity[3],parity[4],parity[5],parity[6],parity[7]};
    4: out = {parity[0],parity[1],parity[2],parity[3],in,parity[4],parity[5],parity[6],parity[7]};
    5: out = {parity[0],parity[1],parity[2],parity[3],parity[4],in,parity[5],parity[6],parity[7]};
    6: out = {parity[0],parity[1],parity[2],parity[3],parity[4],parity[5],in,parity[6],parity[7]};
    7: out = {parity[0],parity[1],parity[2],parity[3],parity[4],parity[5],parity[6],in,parity[7]};
  endcase
end

always @ (posedge clk) begin
  state <= next_state;
end

endmodule
module interleaver (
  input [n-1:0] in,
  output [n-1:0] out
);

parameter k = 1024; // number of input bits
parameter n = 2048; // number of output bits
parameter r = 8;    // number of parity bits

reg [k-1:0] buffer;

integer i, j, index;

always @ (in) begin
  for (i = 0; i < r; i = i + 1) begin
    index = i * k / r;
    for (j = 0; j < k / r; j = j + 1) begin
      buffer[index + j] = in[i * k / r + j];
    end
  end
end

always @ (buffer) begin
  for (i = 0; i < k; i = i + 1) begin
    index = (i * r) % k + (i * r) / k;
    out[i] = buffer[index];
  end
end

endmodule

module one_hot_state_machine (
  input clk,
  input rst,
  input enable,
  input [n-1:0] in,
  output [n-1:0] state,
  output reg [m-1:0] out
);

parameter n = 4; // number of states
parameter m = 2; // number of output signals

reg [n-1:0] next_state;
reg [n-1:0] current_state;

// define state transitions and output function as Boolean functions of inputs and current state
always @ (posedge clk) begin
  if (rst) begin
    current_state <= 'b0;
  end else if (enable) begin
    current_state <= next_state;
  end
end

always @ (current_state, in) begin
  case (current_state)
    4'b0001: begin // state 1
      if (in == 2'b00) begin
        out <= 2'b00;
        next_state <= 4'b0010;
      end else if (in == 2'b01) begin
        out <= 2'b01;
        next_state <= 4'b0100;
      end else begin
        out <= 2'b00;
        next_state <= 4'b0001;
      end
    end
    4'b0010: begin // state 2
      if (in == 2'b00) begin
        out <= 2'b10;
        next_state <= 4'b1000;
      end else if (in == 2'b01) begin
        out <= 2'b00;
        next_state <= 4'b0001;
      end else begin
        out <= 2'b00;
        next_state <= 4'b0010;
      end
    end
    4'b0100: begin // state 3
      if (in == 2'b00) begin
        out <= 2'b00;
        next_state <= 4'b0001;
      end else if (in == 2'b01) begin
        out <= 2'b10;
        next_state <= 4'b1000;
      end else begin
        out <= 2'b00;
        next_state <= 4'b0100;
      end
    end
    4'b1000: begin // state 4
      if (in == 2'b00) begin
        out <= 2'b01;
        next_state <= 4'b0100;
      end else if (in == 2'b01) begin
        out <= 2'b00;
        next_state <= 4'b0010;
      end else begin
        out <= 2'b00;
        next_state <= 4'b1000;
      end
    end
    default: begin
      out <= 2'b00;
      next_state <= 4'b0001;
    end
  endcase
end

// use one-hot code to represent current state
assign state = {current_state};

endmodule

module uart_rx
#(
  parameter DATA_BITS                = 8,
  parameter STOP_BITS                = 1,
  parameter PARITY_MODE              = 1, // 0 = NONE, 1 = ODD, 2 = EVEN
  parameter BAUD_CLK_OVERSAMPLE_RATE = 16
)
(
  input  wire                 clk,            // System clock
  input  wire                 reset,          // Reset signal
  input  wire                 baud_clk_tick,  // 1 tick per OVERSAMPLE_RATE baud clks
  input  wire                 rx,             // RX transmission wire
  output wire [DATA_BITS-1:0] rx_data,        // Output data
  output wire                 rx_done_tick,   // Output rdy signal
  output wire                 parity_err      // Asserted for one clk on parity error
);

localparam [5:0] STOP_OVERSAMPLE_TICKS = STOP_BITS * BAUD_CLK_OVERSAMPLE_RATE;

// Symbolic state representations.
localparam [4:0] S_IDLE   = 5'h01,
                 S_START  = 5'h02,
                 S_DATA   = 5'h04,
                 S_PARITY = 5'h08,
                 S_STOP   = 5'h10;

// Registers
reg [4:0]           q_state, d_state;
reg [3:0]           q_oversample_tick_cnt, d_oversample_tick_cnt;
reg [DATA_BITS-1:0] q_data, d_data;
reg [2:0]           q_data_bit_idx, d_data_bit_idx;
reg                 q_done_tick, d_done_tick;
reg                 q_parity_err, d_parity_err;
reg                 q_rx;

always @(posedge clk, posedge reset)
  begin
    if (reset)
      begin
        q_state               <= S_IDLE;
        q_oversample_tick_cnt <= 0;
        q_data                <= 0;
        q_data_bit_idx        <= 0;
        q_done_tick           <= 1'b0;
        q_parity_err          <= 1'b0;
        q_rx                  <= 1'b1;
      end
    else
      begin
        q_state               <= d_state;
        q_oversample_tick_cnt <= d_oversample_tick_cnt;
        q_data                <= d_data;
        q_data_bit_idx        <= d_data_bit_idx;
        q_done_tick           <= d_done_tick;
        q_parity_err          <= d_parity_err;
        q_rx                  <= rx;
      end
  end

always @*
  begin
    // Default most state to remain unchanged.
    d_state               = q_state;
    d_data                = q_data;
    d_data_bit_idx        = q_data_bit_idx;

    // Increment the tick counter if the baud_clk counter ticked.
    d_oversample_tick_cnt = (baud_clk_tick) ? q_oversample_tick_cnt + 4'h1 : q_oversample_tick_cnt;

    // Default the done signal and parity err to 0.
    d_done_tick           = 1'b0;
    d_parity_err          = 1'b0;

    case (q_state)
      S_IDLE:
        begin
          // Detect incoming data when rx goes low (start bit).
          if (~q_rx)
            begin
              d_state               = S_START;
              d_oversample_tick_cnt = 0;
            end
        end

      S_START:
        begin
          // Wait for BAUD_CLK_OVERSAMPLE_RATE / 2 ticks to get "centered" in the start bit signal.
          if (baud_clk_tick && (q_oversample_tick_cnt == ((BAUD_CLK_OVERSAMPLE_RATE - 1) / 2)))
            begin
              d_state               = S_DATA;
              d_oversample_tick_cnt = 0;
              d_data_bit_idx        = 0;
            end
        end

      S_DATA:
        begin
          // Every BAUD_CLK_OVERSAMPLE_RATE clocks, sample rx and shift its value into the data reg.
          if (baud_clk_tick && (q_oversample_tick_cnt == (BAUD_CLK_OVERSAMPLE_RATE - 1)))
            begin
              d_data                = { q_rx, q_data[DATA_BITS-1:1] };
              d_oversample_tick_cnt = 0;

              if (q_data_bit_idx == (DATA_BITS - 1))
                begin
                  if (PARITY_MODE == 0)
                    d_state = S_STOP;
                  else
                    d_state = S_PARITY;
                end
              else
                d_data_bit_idx = q_data_bit_idx + 3'h1;
            end
        end

      S_PARITY:
        begin
          if (baud_clk_tick && (q_oversample_tick_cnt == (BAUD_CLK_OVERSAMPLE_RATE - 1)))
            begin
              if (PARITY_MODE == 1)
                d_parity_err = (q_rx != ~^q_data);
              else
                d_parity_err = (q_rx != ^q_data);

              d_state               = S_STOP;
              d_oversample_tick_cnt = 0;
            end
        end

      S_STOP:
        begin
          // Wait for stop bit before returning to idle.  Signal done_tick.
          if (baud_clk_tick && (q_oversample_tick_cnt == STOP_OVERSAMPLE_TICKS - 1))
            begin
              d_state     = S_IDLE;
              d_done_tick = 1'b1;
            end
        end
    endcase
end

assign rx_data      = q_data;
assign rx_done_tick = q_done_tick;
assign parity_err   = q_parity_err;

endmodule

module magnitude_comparator (
    input [3:0] A,
