module queue(
  input clk,
  input rst,
  input [7:0] data_in,
  input enq,
  input deq,
  output [7:0] data_out,
  output [9:0] count,
  output [9:0] head,
  output [9:0] tail
);

  reg [7:0] queue[0:9]; // fixed-size array with a maximum capacity of 10 elements
  reg [9:0] head = 0; // index of the head of the queue
  reg [9:0] tail = 0; // index of the tail of the queue
  reg [9:0] count = 0; // number of elements currently in the queue
  reg [3:0] oldest_index = 0; // index of the oldest element in the queue
  reg [1:0] error = 0; // flag indicating whether an error has occurred

  always @(posedge clk) begin
    if (rst) begin
      head <= 0;
      tail <= 0;
      count <= 0;
      oldest_index <= 0;
      error <= 0;
    end else begin
      if (enq && !deq) begin // add element to queue
        if (count == 10) begin // queue is full, remove oldest element
          queue[oldest_index] <= data_in;
          oldest_index <= (oldest_index + 1) % 10;
          head <= (head + 1) % 10;
          tail <= tail;
        end else begin // add element to queue
          queue[tail] <= data_in;
          tail <= (tail + 1) % 10;
          head <= head;
        end
        count <= count + 1;
      end else if (deq && !enq) begin // remove element from queue
        if (count == 0) begin // queue is empty, throw error
          error <= 1;
        end else begin // remove element from queue
          data_out <= queue[head];
          head <= (head + 1) % 10;
          tail <= tail;
          count <= count - 1;
        end
      end else begin // do nothing
        head <= head;
        tail <= tail;
        count <= count;
      end
    end
  end

endmodule

module barrel_shifter (
    input CLK,
    input SHIFT,
    input [7:0] DATA,
    output reg [7:0] Q
);

reg [7:0] temp;

always @(posedge CLK) begin
    if (SHIFT) begin
        temp[7:1] = DATA[6:0];
        temp[0] = DATA[7];
    end else begin
        temp[6:0] = DATA[7:1];
        temp[7] = DATA[0];
    end
    Q <= temp;
end

endmodule

