module top_module( 
    input [3:0] a, b, // 4-bit inputs for half adder
    input [254:0] in, // 255-bit input for comparator
    output [7:0] out ); // 8-bit output for final result

    // Shift register for counting 1's
    reg [7:0] count = 8'd0;
    reg [254:0] shift_reg = {in, 1'b0};
    integer i;

    // Comparator for counting 1's
    always @(*) begin
        count = 8'd0;
        for (i = 0; i < 255; i = i + 1) begin
            if (shift_reg[i] == 1'b1) begin
                count = count + 1;
            end
        end
    end

    // Half adder for adding a and b
    wire sum = a ^ b;
    wire carry_out = a & b;

    // Final output module
    final_output_module final_output(.count(count), .sum(sum), .carry_out(carry_out), .out(out));

endmodule

module final_output_module(
    input [7:0] count, // 8-bit count from comparator
    input sum, // sum from half adder
    input carry_out, // carry-out from half adder
    output [7:0] out // final output
    );

    assign out = count + {1'b0, 1'b0, 1'b0, 1'b0, carry_out, sum};

endmodule

module gray_code_counter (
