     .count_d1_reg(count_d1_reg),
     .rd_clk(rd_clk),
     .tmp_ram_rd_en(tmp_ram_rd_en),
     .wr_clk(wr_clk));

  reg [WIDTH-1:0] data_in;
  reg [0:0] write_en;
  reg [0:0] reset;

