module bcd_counter (
    input clk,
    input reset,   // Synchronous active-high reset
    input [3:0] ena, // Enable signals for each digit
    output reg [15:0] q // Output of the BCD counter
);

always @(posedge clk) begin
    if (reset) begin
        q <= 0;
    end else begin
        if (ena[0]) begin
            q[3:0] <= q[3:0] + 1;
            if (q[3:0] == 10) begin
                q[3:0] <= 0;
                if (ena[1]) begin
                    q[7:4] <= q[7:4] + 1;
                    if (q[7:4] == 10) begin
                        q[7:4] <= 0;
                        if (ena[2]) begin
                            q[11:8] <= q[11:8] + 1;
                            if (q[11:8] == 10) begin
                                q[11:8] <= 0;
                                if (ena[3]) begin
                                    q[15:12] <= q[15:12] + 1;
                                    if (q[15:12] == 10) begin
                                        q[15:12] <= 0;
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end
end

endmodule

