module carry_select_adder (
  input [n-1:0] a,
  input [n-1:0] b,
  output [n-1:0] sum
);

parameter n = 4; // number of bits in input and output signals

// Define inputs and outputs for carry-lookahead adder
wire [n-1:0] fa_in1, fa_in2, fa_cin, fa_cout, fa_sum;

// Define inputs and outputs for ripple-carry adder
wire [n-1:0] ra_in1, ra_in2, ra_cin, ra_cout, ra_sum;

// Define inputs and outputs for multiplexer
wire [n-1:0] mp_sel, mp_out1, mp_out2;

// Define fast-path and slow-path sets
assign fa_in1 = a & b;
assign fa_in2 = a ^ b;
assign fa_cin = {n{1'b0}};
assign ra_in1 = a & b;
assign ra_in2 = a ^ b;
assign ra_cin = 1'b0;

// Instantiate carry-lookahead adder
carry_lookahead_adder #(.n(n)) fa (
  .in1(fa_in1),
  .in2(fa_in2),
  .cin(fa_cin),
  .cout(fa_cout),
  .sum(fa_sum)
);

// Instantiate ripple-carry adder
ripple_carry_adder #(.n(n)) ra (
  .in1(ra_in1),
  .in2(ra_in2),
  .cin(ra_cin),
  .cout(ra_cout),
  .sum(ra_sum)
);

// Select output using multiplexer
assign mp_sel = fa_cout;
assign mp_out1 = fa_sum;
assign mp_out2 = ra_sum;
mux #(.n(n)) mp (
  .sel(mp_sel),
  .in1(mp_out1),
  .in2(mp_out2),
  .out(sum)
);

endmodule

// Define carry-lookahead adder module
module carry_lookahead_adder #(
  parameter n = 4
) (
  input [n-1:0] in1,
  input [n-1:0] in2,
  input [n-1:0] cin,
  output [n-1:0] cout,
  output [n-1:0] sum
);

wire [n-1:0] p, g;

// Generate carry and sum signals using carry-lookahead logic
generate
  genvar i;
  for (i = 0; i < n; i = i + 1) begin : lookahead
    assign p[i] = in1[i] | in2[i];
    assign g[i] = in1[i] & in2[i];
    if (i == 0) begin
      assign cout[0] = cin[0] & p[0];
      assign sum[0] = in1[0] ^ in2[0] ^ cin[0];
    end else begin
      assign cout[i] = g[i-1] | (p[i-1] & cout[i-1]);
      assign sum[i] = in1[i] ^ in2[i] ^ cout[i-1];
    end
  end
endgenerate

endmodule

// Define ripple-carry adder module
module ripple_carry_adder #(
  parameter n = 4
) (
  input [n-1:0] in1,
  input [n-1:0] in2,
  input [n-1:0] cin,
  output [n-1:0] cout,
  output [n-1:0] sum
);

wire [n-1:0] carry;

// Generate carry and sum signals using ripple-carry logic
generate
  genvar i;
  for (i = 0; i < n; i = i + 1) begin : ripple
    if (i == 0) begin
      assign carry[0] = cin[0];
      assign sum[0] = in1[0] ^ in2[0] ^ cin[0];
    end else begin
      assign carry[i] = (in1[i-1] & in2[i-1]) | (in1[i-1] & carry[i-1]) | (in2[i-1] & carry[i-1]);
      assign sum[i] = in1[i] ^ in2[i] ^ carry[i-1];
    end
  end
endgenerate

assign cout = carry;

endmodule

// Define multiplexer module
module mux #(
  parameter n = 4
) (
  input [n-1:0] sel,
  input [n-1:0] in1,
  input [n-1:0] in2,
  output [n-1:0] out
);

// Select output based on select signal
generate
  genvar i;
  for (i = 0; i < n; i = i + 1) begin : select
    if (sel[i] == 1'b0) begin
      assign out[i] = in1[i];
    end else begin
      assign out[i] = in2[i];
    end
  end
endgenerate

endmodule

