    reg [2:0] next_ptr;
    reg [2:0] next_ptr_tmp;
    reg [2:0] next_read_ptr;
    reg [2:0] next_write_ptr;
    reg write_reset_tmp;
    reg [5:0] data_in_tmp;
    wire [2:0] diff_ptr;

    // Write port 
    always @(posedge clk_in or posedge write_reset) 
    begin
        if(write_reset == 1'b1)
        begin
            for (i=0; i<= 5; i=i+1)
                ram[i] <= 6'b0;
            write_ptr <= 3'b0;
            read_ptr <= 3'b0;
        end
        else begin
            if(we == 1'b1) begin
                ram[write_ptr] <= data_in;
                write_ptr_tmp <= write_ptr + 1;
                if(write_ptr_tmp == read_ptr) begin
                    write_reset_tmp <= 1'b1;
                end else begin
                    write_reset_tmp <= 1'b0;
                end
                write_ptr <= write_ptr_tmp;
            end
        end
    end

    // Read port 
    always @(posedge clk_out or posedge write_reset) 
    begin
        if(write_reset == 1'b1)
        begin
            data_out_tmp <= 6'b0;
            read_ptr <= 3'b0;
            write_ptr <= 3'b0;
        end
        else begin
            if(diff_ptr != 3'b0) begin
                next_ptr_tmp <= read_ptr + 1;
                next_ptr <= (next_ptr_tmp == write_ptr) ? read_ptr : next_ptr_tmp;
                read_ptr <= next_ptr;
            end
            if(diff_ptr == 3'b0 && we == 1'b0) begin
                next_ptr <= read_ptr;
            end
            data_out_tmp <= ram[read_ptr];
        end
    end

    // Synchronize write-reset signal to output clock domain
    always @(posedge clk_in or posedge clk_out) 
    begin
        if(clk_in == 1'b1 && clk_out == 1'b0) begin
            write_reset_tmp <= write_reset;
        end
        if(clk_in == 1'b0 && clk_out == 1'b1) begin
            write_reset <= write_reset_tmp;
        end
    end

    // Synchronize write-enable signal to output clock domain
    always @(posedge clk_in or posedge clk_out) 
    begin
        if(clk_in == 1'b1 && clk_out == 1'b0) begin
            we_tmp <= we;
            data_in_tmp <= data_in;
        end
        if(clk_in == 1'b0 && clk_out == 1'b1) begin
            we <= we_tmp;
            data_in <= data_in_tmp;
        end
    end

    // Calculate difference between write and read pointers
    assign diff_ptr = write_ptr - read_ptr;

    // set output
    assign data_out = data_out_tmp;

endmodule

module IEEE754_Adder
   (clk,
    rst,
    load_i,
    sel_a_i,
    sel_b_i,
    sign_i,
    exp_ieee_i,
    sgf_ieee_i,
    final_result_ieee_o);
  input clk;
  input rst;
  input load_i;
  input sel_a_i;
  input sel_b_i;
  input sign_i;
  input [7:0]exp_ieee_i;
  input [22:0]sgf_ieee_i;
  output [31:0]final_result_ieee_o;

  wire [7:0]Exp_S_mux;
  wire [22:0]Sgf_S_mux;
  wire Sign_S_mux;
  wire [7:0]exp_ieee_i;
  wire [31:0]final_result_ieee_o;
  wire load_i;
  wire overunder;
  wire rst;
  wire sel_a_i;
  wire sel_b_i;
  wire [22:0]sgf_ieee_i;
  wire sign_i;

  // Select the appropriate operand value based on the sel_a_i and sel_b_i inputs.
  Multiplexer_AC Exp_Mux
       (.D0(exp_ieee_i),
        .D1({1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0}),
        .S(Exp_S_mux),
        .ctrl(overunder));
  LUT2 #(
    .INIT(4'hE)) 
    Exp_Mux_i_1
       (.I0(sel_a_i),
        .I1(sel_b_i),
        .O(overunder));

  // If the exponent value is all zeroes, the output should be the same as the non-zero operand value.
  // If the exponent value is all ones, the output should be NaN (not a number).
  assign final_result_ieee_o = (exp_ieee_i == 8'h00 || exp_ieee_i == 8'hFF) ? {exp_ieee_i, sgf_ieee_i} :
                               (exp_ieee_i == 8'hFE && sgf_ieee_i[22] == 1) ? {8'hFF, 23'h7FFFFF} :
                               (exp_ieee_i == 8'hFE && sgf_ieee_i[22] == 0) ? {8'hFF, 23'h800000} :
                               (exp_ieee_i == 8'hFD && sgf_ieee_i[22] == 1) ? {8'hFE, 23'h7FFFFF} :
                               {Exp_S_mux, Sgf_S_mux};

  // Add the two operand values together and normalize the result.
  Multiplexer_AC__parameterized160 Sgf_Mux
       (.D0(sgf_ieee_i),
        .D1({1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0}),
        .S(Sgf_S_mux),
        .ctrl(overunder));
  RegisterAdd__parameterized10 Final_Result_IEEE
       (.D({Sign_S_mux,Exp_S_mux,Sgf_S_mux}),
        .Q(final_result_ieee_o),
        .clk(clk),
        .load(load_i),
        .rst(rst));
  Mux_3x1__parameterized1 Sign_Mux
       (.D0(sign_i),
        .D1(1'b0),
        .D2(1'b0),
        .S(Sign_S_mux),
        .ctrl({sel_a_i,sel_b_i}));
endmodule

