  output [6:0]  HEX1;
  output [6:0]  HEX0;

  wire [7:0]  Y_temp;
  wire [7:0]  A_shifted;
  wire [7:0]  B_shifted;
  wire [7:0]  result;
  wire [7:0]  B_complement;
  wire [7:0]  A_shifted_logical;
  wire [7:0]  A_shifted_arithmetic;
  wire [7:0]  A_shifted_logical_zero;
  wire [7:0]  A_shifted_arithmetic_zero;
  wire [7:0]  A_shifted_logical_max;
  wire [7:0]  A_shifted_arithmetic_min;
  wire [7:0]  A_shifted_arithmetic_max;
  wire [7:0]  A_shifted_arithmetic_overflow;

  assign B_complement = ~B;
  assign A_shifted = (OP == 3'b101) ? {A[B-1:0], {B{1'b0}}} : (OP == 3'b110) ? {{A[7], A[7:1]}, {B{A[7]}}} : A;
  assign B_shifted = (OP == 3'b101) ? A_shifted_logical : (OP == 3'b110) ? A_shifted_arithmetic : B;
  assign A_shifted_logical = {A[B-1:0], {B{1'b0}}};
  assign A_shifted_arithmetic = {{A[7], A[7:1]}, {B{A[7]}}};
  assign A_shifted_logical_zero = {A[7-B+1:0], {B{1'b0}}};
  assign A_shifted_arithmetic_zero = {{A[7], A[7:1]}, {B{A[7]}}};
  assign A_shifted_logical_max = {7'b0, A[7-B+1:0]};
  assign A_shifted_arithmetic_min = {{A[7], 7'b1}, {B{A[7]}}};
  assign A_shifted_arithmetic_max = {{A[7], 7'b0}, {B{A[7]}}};
  assign A_shifted_arithmetic_overflow = (A_shifted_arithmetic == A_shifted_arithmetic_min || A_shifted_arithmetic == A_shifted_arithmetic_max);

  always @* begin
    case (OP)
      3'b000: result = A + B;
      3'b001: result = A + B_complement + 1'b1;
      3'b010: result = A & B;
      3'b011: result = A | B;
      3'b100: result = A ^ B;
      3'b101: result = A_shifted_logical;
      3'b110: result = A_shifted_arithmetic;
      3'b111: result = (A_shifted_arithmetic_overflow) ? (A_shifted_arithmetic_max) : (A_shifted_arithmetic_min);
      default: result = 8'b0;
    endcase
    Y_temp = result;
  end

  assign Y = Y_temp;
  assign C = (OP == 3'b000) ? (Y_temp[8] ? 1'b1 : 1'b0) : (OP == 3'b001) ? (Y_temp[8] ? 1'b0 : 1'b1) : 1'b0;
  assign V = (OP == 3'b000 || OP == 3'b001) ? ((A[7] == B[7] && Y_temp[7] != A[7]) ? 1'b1 : 1'b0) : 1'b0;
  assign N = Y_temp[7];
  assign Z = (Y_temp == 8'b0) ? 1'b1 : 1'b0;

  // SEVEN-SEGMENT DISPLAY DRIVERS

  // replace unused segments with code to disable display
  assign HEX5 = 7'b1111111;
  assign HEX4 = 7'b1111111;
  assign HEX3 = 7'b1111111;
  assign HEX2 = 7'b1111111;
  assign HEX1 = 7'b1111111;
  assign HEX0 = 7'b1111111;

  hex_to_seven_seg upperBitsOfY(
    .B(Y[7:4]),
    .SSEG_L(HEX7)
  );

  hex_to_seven_seg lowerBitsOfY(
    .B(Y[3:0]),
    .SSEG_L(HEX6)
  );

endmodule

