        for (i = 0; i < 4; i = i + 1) begin : adder
            full_adder fa(
                .A(A[i]),
                .B(B[i]),
                .CIN(carry[i]),
                .SUM(SUM[i]),
                .COUT(carry[i+1])
            );
        end
    endgenerate

    assign COUT = carry[4];

endmodule

module full_adder (
    input A,
    input B,
    input CIN,
    output SUM,
    output COUT
);

    assign SUM = A ^ B ^ CIN;
    assign COUT = (A & B) | (A & CIN) | (B & CIN);

endmodule

module MemTextures(a, clk, spo);
  input [7:0] a;
  input clk;
  output [91:0] spo;

  reg [31:0] mem[255:0];

  always @(posedge clk) begin
    spo[3:0] = mem[a][31:24];
    spo[7:4] = mem[a][23:16];
    spo[11:8] = mem[a][15:8];
    spo[15:12] = mem[a][7:0];
    spo[91:16] = {a, mem[a]};
