endmodule

module multiplier_divider(
    input signed [31:0] a,
    input signed [31:0] b,
    input op,
    output reg signed [31:0] result,
    output reg valid
);

always @(*) begin
    if (op == 0) begin
        result = a * b;
        valid = 1;
    end else if (op == 1) begin
        if (b != 0) begin
            result = a / b;
            valid = 1;
        end else begin
            valid = 0;
        end
    end
end

endmodule

module unpack_signed #(parameter N = 64)(
    input [79:0] in,
    output signed [N-1:0] out,
    output [3:0] len
);

    wire [63:0] value;
    wire [5:0] prefix_len;
    wire [5:0] value_len;

    // Extract prefix bits
    assign prefix_len = in[79:70];

    // Extract value bits
    assign value = in[63:0];

    // Determine value length
    assign value_len = $countones(|value);

    // Determine sign bit
    wire sign_bit = in[63];

    // Sign extend value
    wire [N-1:0] signed_value = { {N-value_len-1{sign_bit}}, value };

    // Assign output and length
    assign out = signed_value;
    assign len = prefix_len + value_len;

endmodule

module top_module (
    input [3:0] A,
    input [3:0] B,
    input [2:0] OP,
    input select,
    output reg [3:0] result,
    output eq,
    output gt,
    output lt
);

    wire [3:0] alu_result;
    wire eq_temp, gt_temp, lt_temp;

    alu_module alu_inst (
        .A(A),
        .B(B),
        .OP(OP),
        .result(alu_result)
    );

    comparator_module comparator_inst (
        .A(A),
        .B(B),
        .eq(eq_temp),
        .gt(gt_temp),
        .lt(lt_temp)
    );

    always @(*) begin
        if (select == 1) begin
            eq = eq_temp;
            gt = gt_temp;
            lt = lt_temp;
            result = 4'b0;
        end else begin
            eq = 1'b0;
            gt = 1'b0;
            lt = 1'b0;
            case (OP)
                3'b000: result = A + B;
                3'b001: result = A - B;
                3'b010: result = A & B;
                3'b011: result = A | B;
                3'b100: result = A ^ B;
                3'b101: result = A << 1;
                3'b110: result = A >> 1;
                3'b111: result = ~A;
            endcase
        end
    end

endmodule

module alu_module (
    input [3:0] A,
    input [3:0] B,
    input [2:0] OP,
    output reg [3:0] result
);

    always @(*) begin
        case (OP)
            3'b000: result = A + B;
            3'b001: result = A - B;
            3'b010: result = A & B;
            3'b011: result = A | B;
            3'b100: result = A ^ B;
            3'b101: result = A << 1;
            3'b110: result = A >> 1;
            3'b111: result = ~A;
        endcase
    end

endmodule

module comparator_module (
    input [3:0] A,
    input [3:0] B,
    output reg eq,
    output reg gt,
    output reg lt
);

    always @(*) begin
        if (A == B) begin
            eq = 1'b1;
            gt = 1'b0;
            lt = 1'b0;
        end else if (A > B) begin
            eq = 1'b0;
            gt = 1'b1;
            lt = 1'b0;
        end else begin
            eq = 1'b0;
            gt = 1'b0;
            lt = 1'b1;
        end
    end

endmodule

module ripple_carry_adder_4bit (
  input [3:0] A,
  input [3:0] B,
  input cin,
  output [3:0] S,
  output cout
);

  wire [2:0] c;
  wire [3:0] s;

  full_adder fa0(A[0], B[0], cin, s[0], c[0]);
  full_adder fa1(A[1], B[1], c[0], s[1], c[1]);
  full_adder fa2(A[2], B[2], c[1], s[2], c[2]);
  full_adder fa3(A[3], B[3], c[2], s[3], cout);

  assign S = s;

endmodule

module top_module (
  input [3:0] A,
  input [3:0] B,
  input [3:0] C,
  input [3:0] D,
  output [7:0] S
);

  wire [3:0] s1;
  wire [3:0] s2;
  wire c;

  ripple_carry_adder_4bit rca1(A, B, 0, s1, c);
  ripple_carry_adder_4bit rca2(C, D, c, s2, c);

  full_adder fa(s1[3], s2[3], c, S[7], c);
  assign S[6:0] = s2[2:0];
  assign S[5:0] = s1[2:0];

endmodule

module binary_division(dividend, divisor, clk, resetn, quotient, done);
input [31:0] dividend;
input [31:0] divisor;
input clk;
input resetn;
output [31:0] quotient;
output done;

reg [31:0] quotient;
reg done;
reg [31:0] remainder;
reg sign;

always @ (posedge clk) begin
	if (resetn == 0) begin
		quotient <= 32'b0;
		remainder <= 32'b0;
		sign <= 0;
		done <= 0;
	end else begin
		if (divisor == 0) begin
			quotient <= 32'b0;
			done <= 1;
		end else begin
			if (dividend[31] == 1 && divisor[31] == 0) begin
				sign <= 1;
			end else if (dividend[31] == 0 && divisor[31] == 1) begin
				sign <= 1;
			end else begin
				sign <= 0;
			end
			remainder <= dividend;
			quotient <= 32'b0;
			for (i = 0; i < 32; i = i + 1) begin
				quotient = quotient << 1;
				if (remainder[31] == 1) begin
					remainder = remainder - divisor;
					if (remainder[31] == 0) begin
						quotient[0] = 1;
					end
				end else begin
					quotient[0] = 0;
				end
				remainder = remainder << 1;
			end
			if (sign == 1) begin
				quotient = ~quotient + 1;
			end
			done <= 1;
		end
	end
end

endmodule

