module adder4(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout
);

wire [3:0] temp_sum;
wire [3:0] temp_carry;

// Full adder
assign temp_sum[0] = A[0] ^ B[0] ^ Cin;
assign temp_carry[0] = (A[0] & B[0]) | (Cin & (A[0] ^ B[0]));

assign temp_sum[1] = A[1] ^ B[1] ^ temp_carry[0];
assign temp_carry[1] = (A[1] & B[1]) | (temp_carry[0] & (A[1] ^ B[1]));

assign temp_sum[2] = A[2] ^ B[2] ^ temp_carry[1];
assign temp_carry[2] = (A[2] & B[2]) | (temp_carry[1] & (A[2] ^ B[2]));

assign temp_sum[3] = A[3] ^ B[3] ^ temp_carry[2];
assign Cout = (A[3] & B[3]) | (temp_carry[2] & (A[3] ^ B[3]));

assign Sum = temp_sum;

endmodule

module vending_machine (
  input clk,
  input reset,
  input [1:0] coin,
  input slot1_button,
  input slot2_button,
  input slot3_button,
  output reg item_dispensed,
  output reg [1:0] change_dispensed,
  output reg item_dispensed_slot1,
  output reg item_dispensed_slot2,
  output reg item_dispensed_slot3
);

  // Constants
  parameter CANDY_BAR_COST = 2'd1;
  parameter BAG_OF_CHIPS_COST = 2'd2;
  parameter CAN_OF_SODA_COST = 2'd3;
  parameter NICKEL_VALUE = 2'd1;
  parameter DIME_VALUE = 2'd2;
  parameter QUARTER_VALUE = 2'd3;

  // Vending machine state
  reg [1:0] coins_inserted;
  reg [1:0] coins_required;
  reg [1:0] coins_returned;
  reg [1:0] coins_available;
  reg item_dispensed_slot1_internal;
  reg item_dispensed_slot2_internal;
  reg item_dispensed_slot3_internal;

  // Initialize state
  always @(posedge clk, negedge reset) begin
    if (!reset) begin
      coins_inserted <= 2'b00;
      coins_required <= 2'b00;
      coins_returned <= 2'b00;
      coins_available <= {2'b10, 2'b10, 2'b10};
      item_dispensed <= 1'b0;
      change_dispensed <= 2'b00;
      item_dispensed_slot1 <= 1'b0;
      item_dispensed_slot2 <= 1'b0;
      item_dispensed_slot3 <= 1'b0;
      item_dispensed_slot1_internal <= 1'b0;
      item_dispensed_slot2_internal <= 1'b0;
      item_dispensed_slot3_internal <= 1'b0;
    end
  end

  // Determine coins required for selected item
  always @* begin
    if (slot1_button) begin
      coins_required = CANDY_BAR_COST;
    end else if (slot2_button) begin
      coins_required = BAG_OF_CHIPS_COST;
    end else if (slot3_button) begin
      coins_required = CAN_OF_SODA_COST;
    end else begin
      coins_required = 2'b00;
    end
  end

  // Determine if enough coins have been inserted
  always @* begin
    if (coins_inserted >= coins_required) begin
      item_dispensed = 1'b1;
      coins_returned = coins_inserted - coins_required;
      coins_available = coins_available - coins_inserted;
      coins_inserted = 2'b00;
      if (slot1_button) begin
        item_dispensed_slot1_internal = 1'b1;
      end else if (slot2_button) begin
        item_dispensed_slot2_internal = 1'b1;
      end else if (slot3_button) begin
        item_dispensed_slot3_internal = 1'b1;
      end
    end else begin
      item_dispensed = 1'b0;
      coins_returned = coins_inserted;
      coins_inserted = 2'b00;
    end
  end

  // Determine change to be dispensed
  always @* begin
    if (coins_returned == 2'b00) begin
      change_dispensed = 2'b00;
    end else if (coins_returned == 2'b01) begin
      if (coins_available[QUARTER_VALUE]) begin
        change_dispensed = QUARTER_VALUE;
        coins_available[QUARTER_VALUE] = 1'b0;
      end else if (coins_available[DIME_VALUE]) begin
        change_dispensed = DIME_VALUE;
        coins_available[DIME_VALUE] = 1'b0;
      end else if (coins_available[NICKEL_VALUE]) begin
        change_dispensed = NICKEL_VALUE;
        coins_available[NICKEL_VALUE] = 1'b0;
      end else begin
        change_dispensed = 2'b00;
        coins_returned = 2'b01;
      end
    end else if (coins_returned == 2'b10) begin
      if (coins_available[QUARTER_VALUE]) begin
        change_dispensed = QUARTER_VALUE;
        coins_available[QUARTER_VALUE] = 1'b0;
      end else if (coins_available[DIME_VALUE]) begin
        change_dispensed = DIME_VALUE;
        coins_available[DIME_VALUE] = 1'b0;
      end else begin
        change_dispensed = 2'b00;
        coins_returned = 2'b10;
      end
    end else if (coins_returned == 2'b11) begin
      if (coins_available[QUARTER_VALUE]) begin
        change_dispensed = QUARTER_VALUE;
        coins_available[QUARTER_VALUE] = 1'b0;
      end else begin
        change_dispensed = 2'b00;
        coins_returned = 2'b11;
      end
    end
  end

  // Update item dispensed signals
  always @(posedge clk) begin
    item_dispensed_slot1 <= item_dispensed_slot1_internal;
    item_dispensed_slot2 <= item_dispensed_slot2_internal;
    item_dispensed_slot3 <= item_dispensed_slot3_internal;
    item_dispensed_slot1_internal <= 1'b0;
    item_dispensed_slot2_internal <= 1'b0;
    item_dispensed_slot3_internal <= 1'b0;
  end

endmodule

module counter (
    input clk,
    input reset,
    output reg [3:0] out
);

reg [3:0] stage1_out;
reg [3:0] stage2_out;

always @(posedge clk) begin
    stage1_out <= out + 1;
end

always @(posedge clk) begin
    stage2_out <= stage1_out;
end

always @(posedge clk) begin
    if (reset) begin
        out <= 4'b0;
    end else begin
        out <= stage2_out;
    end
end

endmodule

module jtag_debug_interface (
  input wire clk,
  input wire reset_n,
  input wire tdi,
  input wire [1:0] ir_in,
  input wire [31:0] data_in,
  input wire [31:0] address_in,
  input wire read_write,
  input wire debug_en,
  input wire [3:0] breakpoint_addr,
  input wire [3:0] breakpoint_type,
  input wire [31:0] breakpoint_data,
  output reg tdo,
  output reg [1:0] ir_out,
  output reg [3:0] state_out,
  output reg [31:0] data_out,
  output reg [31:0] address_out,
  output reg read_write_out,
  output reg debug_hit,
  output reg [3:0] breakpoint_hit
);

// JTAG state machine
localparam [3:0] RESET = 4'b0000;
localparam [3:0] IDLE = 4'b0001;
localparam [3:0] DRSELECT = 4'b0010;
localparam [3:0] DRCAPTURE = 4'b0011;
localparam [3:0] DRSHIFT = 4'b0100;
localparam [3:0] DREXIT1 = 4'b0101;
localparam [3:0] DRPAUSE = 4'b0110;
localparam [3:0] DREXIT2 = 4'b0111;
localparam [3:0] DRUPDATE = 4'b1000;
localparam [3:0] IRSELECT = 4'b1001;
localparam [3:0] IRCAPTURE = 4'b1010;
localparam [3:0] IRSHIFT = 4'b1011;
localparam [3:0] IREXIT1 = 4'b1100;
localparam [3:0] IRPAUSE = 4'b1101;
localparam [3:0] IREXIT2 = 4'b1110;
localparam [3:0] IRUPDATE = 4'b1111;

reg [3:0] state;
reg [31:0] shift_reg;
reg [4:0] breakpoint_count;
reg [31:0] breakpoint_address[3:0];
reg [1:0] breakpoint_type[3:0];
reg [31:0] breakpoint_data[3:0];

always @(posedge clk) begin
  if (!reset_n) begin
    state <= RESET;
    ir_out <= 2'b00;
    tdo <= 1'b0;
    state_out <= 4'b0;
    data_out <= 32'h0;
    address_out <= 32'h0;
    read_write_out <= 1'b0;
    debug_hit <= 1'b0;
    breakpoint_hit <= 4'b0000;
    breakpoint_count <= 0;
  end
  else begin
    case (state)
      RESET: begin
        state <= IDLE;
        ir_out <= 2'b00;
        tdo <= 1'b0;
        state_out <= RESET;
      end
      IDLE: begin
        state <= DRSELECT;
        ir_out <= 2'b00;
        tdo <= 1'b0;
        state_out <= IDLE;
      end
      DRSELECT: begin
        state <= DRCAPTURE;
        ir_out <= 2'b10;
        tdo <= 1'b0;
        state_out <= DRSELECT;
      end
      DRCAPTURE: begin
        state <= DRSHIFT;
        ir_out <= 2'b10;
        tdo <= 1'b0;
        state_out <= DRCAPTURE;
      end
      DRSHIFT: begin
        state <= DREXIT1;
        ir_out <= 2'b10;
        tdo <= shift_reg[0];
        shift_reg <= {shift_reg[30:0], tdi};
        state_out <= DRSHIFT;
      end
      DREXIT1: begin
        state <= DRPAUSE;
        ir_out <= 2'b10;
        tdo <= shift_reg[0];
        state_out <= DREXIT1;
      end
      DRPAUSE: begin
        state <= DREXIT2;
        ir_out <= 2'b10;
        tdo <= shift_reg[0];
        state_out <= DRPAUSE;
      end
      DREXIT2: begin
        state <= DRUPDATE;
        ir_out <= 2'b10;
        tdo <= shift_reg[0];
        state_out <= DREXIT2;
      end
      DRUPDATE: begin
        if (debug_en && (breakpoint_count < 4)) begin
          if ((breakpoint_type[breakpoint_count] == 2'b00) && (shift_reg[31:2] == breakpoint_address[breakpoint_count])) begin
            debug_hit <= 1'b1;
            breakpoint_hit[breakpoint_count] <= 1'b1;
          end
          else if ((breakpoint_type[breakpoint_count] == 2'b01) && (shift_reg[31:2] == breakpoint_address[breakpoint_count]) && (shift_reg[1:0] == breakpoint_data[breakpoint_count][1:0])) begin
            debug_hit <= 1'b1;
            breakpoint_hit[breakpoint_count] <= 1'b1;
          end
          else if ((breakpoint_type[breakpoint_count] == 2'b10) && (shift_reg[31:2] == breakpoint_address[breakpoint_count]) && (shift_reg[1:0] == 2'b10)) begin
            debug_hit <= 1'b1;
            breakpoint_hit[breakpoint_count] <= 1'b1;
          end
          else if ((breakpoint_type[breakpoint_count] == 2'b11) && (shift_reg[31:2] == breakpoint_address[breakpoint_count])) begin
            debug_hit <= 1'b1;
            breakpoint_hit[breakpoint_count] <= 1'b1;
          end
          breakpoint_count <= breakpoint_count + 1;
        end
        state <= IRSELECT;
        ir_out <= 2'b00;
        tdo <= shift_reg[0];
        state_out <= DRUPDATE;
      end
      IRSELECT: begin
        state <= IRCAPTURE;
        ir_out <= 2'b01;
        tdo <= shift_reg[0];
        state_out <= IRSELECT;
      end
      IRCAPTURE: begin
        state <= IRSHIFT;
        ir_out <= 2'b01;
        tdo <= 1'b0;
        state_out <= IRCAPTURE;
      end
      IRSHIFT: begin
        state <= IREXIT1;
        ir_out <= 2'b01;
        tdo <= shift_reg[0];
        shift_reg <= {shift_reg[30:0], tdi};
        state_out <= IRSHIFT;
      end
      IREXIT1: begin
        state <= IRPAUSE;
        ir_out <= 2'b01;
        tdo <= shift_reg[0];
        state_out <= IREXIT1;
      end
      IRPAUSE: begin
        state <= IREXIT2;
        ir_out <= 2'b01;
        tdo <= shift_reg[0];
        state_out <= IRPAUSE;
      end
      IREXIT2: begin
        state <= IRUPDATE;
        ir_out <= 2'b01;
        tdo <= shift_reg[0];
        state_out <= IREXIT2;
      end
      IRUPDATE: begin
        if (ir_in == 2'b01) begin // Trace
          data_out <= shift_reg[31:0];
          address_out <= address_in;
          read_write_out <= read_write;
        end
        else if (ir_in == 2'b10) begin // Breakpoint configuration
          breakpoint_address[breakpoint_count] <= address_in;
          breakpoint_type[breakpoint_count] <= breakpoint_type;
          breakpoint_data[breakpoint_count] <= breakpoint_data;
        end
        state <= IDLE;
        ir_out <= 2'b00;
        tdo <= shift_reg[0];
        state_out <= IRUPDATE;
      end
    endcase
  end
end

endmodule

module barrel_shifter (
    input [7:0] in,
    input [2:0] shift_amount,
    input shift_direction,
    output [7:0] out
);

    reg [7:0] shifted;

    always @(*) begin
        case(shift_direction)
            1'b0: shifted = in >> shift_amount;
            1'b1: shifted = in << shift_amount;
        endcase
    end

    assign out = shifted;

endmodule

module adaptive_filter (
  input clk,
  input rst,
  input signed [15:0] x,
  input signed [15:0] d,
  output signed [15:0] y,
  output signed [15:0] w
);

parameter n = 32; // number of filter taps
parameter mu = 0.001; // step size for LMS algorithm
parameter lambda = 0.99; // forgetting factor for RLS algorithm

reg signed [15:0] taps [0:n-1]; // filter taps
reg signed [15:0] e; // error signal
reg signed [15:0] p [0:n-1]; // inverse correlation matrix
reg signed [15:0] k [0:n-1]; // Kalman gain vector
reg signed [15:0] x_delayed [0:n-1]; // delayed input signals
reg signed [15:0] w_new [0:n-1]; // new filter coefficients

integer i;

// initialize filter taps to zero
initial begin
  for (i = 0; i < n; i = i + 1) begin
    taps[i] = 0;
  end
end

// compute delayed input signals
always @(posedge clk) begin
  for (i = n-1; i > 0; i = i - 1) begin
    x_delayed[i] = x_delayed[i-1];
  end
  x_delayed[0] = x;
end

// compute filter output and error signal
always @(posedge clk) begin
  y = 0;
  for (i = 0; i < n; i = i + 1) begin
    y = y + taps[i] * x_delayed[i];
  end
  e = d - y;
end

// update filter coefficients using LMS algorithm
always @(posedge clk) begin
  if (~rst) begin
    for (i = 0; i < n; i = i + 1) begin
      w_new[i] = taps[i] + mu * e * x_delayed[i];
    end
    for (i = 0; i < n; i = i + 1) begin
      taps[i] = w_new[i];
    end
  end
end

// update filter coefficients using RLS algorithm
always @(posedge clk) begin
  if (~rst) begin
    for (i = 0; i < n; i = i + 1) begin
      k[i] = p[i] * x_delayed[i] / (lambda + x_delayed * p * x_delayed);
      w_new[i] = taps[i] + k[i] * e;
      for (j = 0; j < n; j = j + 1) begin
        p[i][j] = (1 / lambda) * (p[i][j] - k[i] * x_delayed[j] * p[i] / (lambda + x_delayed * p * x_delayed));
      end
    end
    for (i = 0; i < n; i = i + 1) begin
      taps[i] = w_new[i];
    end
  end
end

// output filter coefficients
assign w = taps;

endmodule

