module priority_encoder(valid, pri_in, ch_conf, pri_sel, pri_out);

parameter [3:0]	ch_conf = 4'b0000;
parameter [1:0]	pri_sel = 2'd0;

input		valid;
input	[2:0]	pri_in;
output	[7:0]	pri_out;

wire	[7:0]	pri_out;
reg	[7:0]	pri_out_d;
reg	[7:0]	pri_out_d0;
reg	[7:0]	pri_out_d1;
reg	[7:0]	pri_out_d2;

assign pri_out = ch_conf[0] ? pri_out_d : 8'h0;

// Select Configured Priority
always @(pri_sel or pri_out_d0 or pri_out_d1 or  pri_out_d2)
	case(pri_sel)		// synopsys parallel_case full_case
	   2'd0: pri_out_d = pri_out_d0;
	   2'd1: pri_out_d = pri_out_d1;
	   2'd2: pri_out_d = pri_out_d2;
	endcase

// 8 Priority Levels
always @(valid or pri_in)
	if(!valid)		pri_out_d2 = 8'b0000_0001;
	else
	if(pri_in==3'h0)	pri_out_d2 = 8'b0000_0001;
	else
	if(pri_in==3'h1)	pri_out_d2 = 8'b0000_0010;
	else
	if(pri_in==3'h2)	pri_out_d2 = 8'b0000_0100;
	else
	if(pri_in==3'h3)	pri_out_d2 = 8'b0000_1000;
	else
	if(pri_in==3'h4)	pri_out_d2 = 8'b0001_0000;
	else
	if(pri_in==3'h5)	pri_out_d2 = 8'b0010_0000;
	else
	if(pri_in==3'h6)	pri_out_d2 = 8'b0100_0000;
	else			pri_out_d2 = 8'b1000_0000;

// 4 Priority Levels
always @(valid or pri_in)
	if(!valid)		pri_out_d1 = 8'b0000_0001;
	else
	if(pri_in==3'h0)	pri_out_d1 = 8'b0000_0001;
	else
	if(pri_in==3'h1)	pri_out_d1 = 8'b0000_0010;
	else
	if(pri_in==3'h2)	pri_out_d1 = 8'b0000_0100;
	else			pri_out_d1 = 8'b0000_1000;

// 2 Priority Levels
always @(valid or pri_in)
	if(!valid)		pri_out_d0 = 8'b0000_0001;
	else
	if(pri_in==3'h0)	pri_out_d0 = 8'b0000_0001;
	else			pri_out_d0 = 8'b0000_0010;

endmodule

module alu(RST, CLK, ENA, RGA, RGB, RGZ, KEY, OPT);
  input CLK;
  input ENA;
  input [1:0] KEY;
  input [7:0] OPT;
  input [7:0] RGA;
  input [7:0] RGB;
  output [7:0] RGZ;
  input RST;

  // Register for storing the result of the operation
  reg [7:0] result;

  // Perform arithmetic and logical operations based on KEY and OPT
  alu_min aluj (
    .CLK(CLK),
    .ENA(ENA),
    .KEY(KEY),
    .OPT(OPT),
    .RGA(RGA),
    .RGB(RGB),
    .RGZ(result),
    .RST(RST)
  );

  // Output result or 0 based on ENA and RST
  assign RGZ = ENA ? result : (RST ? 8'b0 : RGA);

  // Synchronize the RST signal with the CLK signal
  protection prot (
    .CLK(CLK),
    .ENA(ENA),
    .KEY(KEY),
    .RGA(RGA),
    .RGB(RGB),
    .RGZ(result),
    .RST(RST)
  );
endmodule

// Arithmetic and logical operations module
module alu_min(CLK, ENA, KEY, OPT, RGA, RGB, RGZ, RST);
  input CLK;
  input ENA;
  input [1:0] KEY;
  input [7:0] OPT;
  input [7:0] RGA;
  input [7:0] RGB;
  output [7:0] RGZ;
  input RST;

  // Register for storing the result of the operation
  reg [7:0] result;

  always @(posedge CLK) begin
    if (ENA) begin
      case (KEY)
        2'b00: result = RGA & RGB;
        2'b01: result = RGA | RGB;
        2'b10: result = RGA + RGB;
        2'b11: result = RGA - RGB;
        default: result = 8'b0;
      endcase

      // Perform logical shift left or right based on OPT
      if (OPT[0]) begin
        result = result << 1;
      end else if (OPT[1]) begin
        result = result >> 1;
      end
    end else begin
      // If ENA is low, output RGA
      result = RGA;
    end
  end

  // Output the result
  assign RGZ = result;
endmodule

// Protection module for synchronizing RST signal with CLK signal
module protection(CLK, ENA, KEY, RGA, RGB, RGZ, RST);
  input CLK;
  input ENA;
  input [1:0] KEY;
  input [7:0] RGA;
  input [7:0] RGB;
  output [7:0] RGZ;
  input RST;

  // Register for synchronizing RST signal with CLK signal
  reg sync_rst;

  always @(posedge CLK) begin
    if (RST) begin
      // If RST is high, set sync_rst to 1
      sync_rst <= 1;
    end else begin
      // If RST is low, set sync_rst to 0
      sync_rst <= 0;
    end
  end

  // Output sync_rst when ENA is low
  assign RGZ = ENA ? RGZ : sync_rst ? 8'b0 : RGA;
endmodule

module NFC (
  input [3:0] data_in,
  input [3:0] id_in,
  input clk,
  output [31:0] encoded_out,
  input [31:0] encoded_in,
  output reg [3:0] data_out
);

  // Manchester encoding scheme
  always @(posedge clk) begin
    // Encode data_in
    encoded_out[0] = ~data_in[3];
    encoded_out[1] = data_in[3];
    encoded_out[2] = ~data_in[2];
    encoded_out[3] = data_in[2];
    encoded_out[4] = ~data_in[1];
    encoded_out[5] = data_in[1];
    encoded_out[6] = ~data_in[0];
    encoded_out[7] = data_in[0];

    // Encode id_in
    encoded_out[8] = ~id_in[3];
    encoded_out[9] = id_in[3];
    encoded_out[10] = ~id_in[2];
    encoded_out[11] = id_in[2];
    encoded_out[12] = ~id_in[1];
    encoded_out[13] = id_in[1];
    encoded_out[14] = ~id_in[0];
    encoded_out[15] = id_in[0];

    // Add start and stop bits
    encoded_out[31] = 1;
    encoded_out[30] = 0;
  end

  // Manchester decoding scheme
  always @(posedge clk) begin
    // Check start bit
    if (encoded_in[31] == 1 && encoded_in[30] == 0) begin
      // Decode data_in
      data_out[3] = ~(encoded_in[0] ^ encoded_in[1]);
      data_out[2] = ~(encoded_in[2] ^ encoded_in[3]);
      data_out[1] = ~(encoded_in[4] ^ encoded_in[5]);
      data_out[0] = ~(encoded_in[6] ^ encoded_in[7]);

      // Decode id_in
      if (encoded_in[8] == ~encoded_in[9] && encoded_in[10] == ~encoded_in[11] && encoded_in[12] == ~encoded_in[13] && encoded_in[14] == ~encoded_in[15]) begin
        // Set data_out if id_in matches
        data_out = id_in;
      end
    end
  end

endmodule

module top_multiplexer(
    input sel_b1,
    input sel_b2,
    input [2:0] sel,
    input [5:0] data,
    input a,
    input b,
    output reg [7:0] out_always
);

// 2-to-1 multiplexer
always @*
begin
    if(!sel_b1 && !sel_b2)
    begin
        if(sel == 0)
            out_always = a;
        else
            out_always = b;
    end
end

// 6-to-1 multiplexer using priority encoder and decoder
wire [2:0] encoded_sel;
wire [5:0] decoded_data;

priority_encoder pe(sel, encoded_sel);
decoder dec(encoded_sel, decoded_data);

always @*
begin
    if(sel_b1 || sel_b2)
        out_always = decoded_data[sel];
end

// Bitwise OR gate to combine outputs of 2-to-1 and 6-to-1 multiplexers
always @*
begin
    if(!sel_b1 && !sel_b2)
    begin
        if(sel == 0)
            out_always = a;
        else
            out_always = b;
    end
    else
        out_always = out_always | decoded_data[sel];
end

endmodule

