module sync_load_counter (
    input clk,
    input reset,
    input load,
    input [3:0] L,
    output reg [3:0] count
);

always @(posedge clk, negedge reset) begin
    if (reset == 1) begin
        count <= 0;
    end else if (load == 1) begin
        count <= L;
    end else begin
        count <= count + 1;
    end
end

endmodule

module matrix_mult_4x4 (
    input signed [7:0] A [0:15],
    input signed [7:0] B [0:15],
    output reg signed [15:0] C [0:15]
);

integer i, j, k;
reg signed [15:0] temp;

always @(*) begin
    for (i = 0; i < 4; i = i + 1) begin
        for (j = 0; j < 4; j = j + 1) begin
            temp = 0;
            for (k = 0; k < 4; k = k + 1) begin
                temp = temp + A[i*4+k] * B[k*4+j];
            end
            C[i*4+j] = temp;
        end
    end
end

endmodule

module top_module (
    input clk,
    input reset,
    input load,
    input [3:0] L,
    input signed [7:0] A [0:15],
    input signed [7:0] B [0:15],
    output reg signed [15:0] sum
);

reg signed [15:0] C [0:15];
wire [3:0] count;
sync_load_counter counter (.clk(clk), .reset(reset), .load(load), .L(L), .count(count));
matrix_mult_4x4 multiplier (.A(A), .B(B), .C(C));

always @(posedge clk, negedge reset) begin
    if (reset == 1) begin
        sum <= 0;
    end else begin
        sum <= C[count] + count;
    end
end

endmodule

module adder_subtractor (A, B, C, S);
    input [3:0] A;
    input [3:0] B;
    input C;
    output [3:0] S;

    wire [3:0] A_inv;
    wire [3:0] B_inv;
    wire [3:0] B_neg;
    wire [3:0] sum;
    wire carry;

    // Invert A and B for subtraction
    assign A_inv = ~A;
    assign B_inv = ~B;

    // Calculate B's 2's complement for subtraction
    assign B_neg = B_inv + 1;

    // Calculate sum of A and B
    assign {carry, sum} = A + B;

    // Calculate difference of A and B
    assign {carry, S} = C ? A + B_neg + 1 : sum;

endmodule

module axi_timer
    #(parameter WIDTH = 32, parameter TICK_RATE = 1)
    (input clk, rst, enable, load,
     input [WIDTH-1:0] value,
     output reg [WIDTH-1:0] timer,
     output reg done);

    reg [WIDTH-1:0] load_value;
    reg [WIDTH-1:0] count;

    always @(posedge clk) begin
        if (rst) begin
            count <= 0;
            done <= 0;
        end else if (enable) begin
            if (load) begin
                load_value <= value;
                count <= load_value;
                done <= 0;
            end else if (count > 0) begin
                count <= count - 1;
                done <= 0;
            end else begin
                count <= load_value;
                done <= 1;
            end
        end else begin
            done <= 0;
        end
    end

    assign timer = count;

endmodule

