module d_flip_flop_mux (
    input clk,
    input [7:0] d,
    input sel,
    output reg [7:0] q
);
    reg [7:0] dff1, dff2, dff3, dff4, dff5, dff6, dff7, dff8;
    wire [3:0] sel_mux;
    assign sel_mux = sel[1:0];
    xnor_gate xnor1 (.a(d[0]), .b(d[1]), .y(dff1));
    xnor_gate xnor2 (.a(d[2]), .b(d[3]), .y(dff2));
    xnor_gate xnor3 (.a(d[4]), .b(d[5]), .y(dff3));
    xnor_gate xnor4 (.a(d[6]), .b(d[7]), .y(dff4));
    always @(negedge clk) begin
        dff1 <= dff2;
        dff2 <= dff3;
        dff3 <= dff4;
        dff4 <= dff5;
        dff5 <= dff6;
        dff6 <= dff7;
        dff7 <= dff8;
        dff8 <= sel_mux ? dff4 : dff1;
    end
    assign q = sel[2] ? (sel[1] ? dff8 : dff7) : (sel[1] ? dff6 : dff5);
endmodule

