module top_module (
    input clk,
    input [7:0] d,
    input a,
    input b,
    input sel,
    output [7:0] q
);
    wire xnor_out;
    wire [7:0] dff_out;
    wire [7:0] xor_out;
    xnor_gate xnor (.a(a), .b(b), .y(xnor_out));
    d_flip_flop_mux dff_mux (.clk(clk), .d(d), .sel(sel), .q(dff_out));
    functional_module func_module (.xnor_out(xnor_out), .dff_out(dff_out), .xor_out(xor_out));
    always @(*) begin
        case (sel)
            2'b00: q = xnor_out;
            2'b01: q = dff_out;
            2'b10: q = xor_out;
            default: q = 8'h00;
        endcase
    end
endmodule

module priority_encoder (
    input clk,
    input reset, // Synchronous active-high reset
    input [7:0] in, // 8-bit input to be encoded
    output reg [2:0] out // 3-bit output of the encoded input
);

always @(posedge clk) begin
    if (reset) begin
        out <= 3'b0; // Reset output to 0
    end else begin
        casez(in)
            8'b00000001: out <= 3'b000;
            8'b00000010: out <= 3'b001;
            8'b00000100: out <= 3'b010;
            8'b00001000: out <= 3'b011;
            8'b00010000: out <= 3'b100;
            8'b00100000: out <= 3'b101;
            8'b01000000: out <= 3'b110;
            8'b10000000: out <= 3'b111;
            default: out <= 3'b0; // If no input is high, output 0
        endcase
    end
end

endmodule

module multiplexer (
    input clk,
    input reset, // Synchronous active-high reset
    input [1:0] select, // 2-bit input to select the output
    input [3:0] in, // 4-bit input to be selected
    output reg [3:0] out // 4-bit output selected by the input
);

always @(posedge clk) begin
    if (reset) begin
        out <= 4'b0; // Reset output to 0
    end else begin
        case(select)
            2'b00: out <= in[0:3];
            2'b01: out <= in[4:7];
            2'b10: out <= in[8:11];
            2'b11: out <= in[12:15];
