always @(*) begin
    if (direction == 0) // shift left
        shifted_data = signed_data << shift_amount;
    else // shift right
        shifted_data = signed_data >> shift_amount;
end

always @(*) begin
    if (shifted_data >= 0)
        GTE = 1;
    else
        GTE = 0;
end

