    if (edge_detected) begin
        if (sel_b1) begin
            out_func <= a;
        end else begin
            out_func <= b;
        end
    end else begin
        if (sel_b2) begin
            out_func <= a;
        end else begin
            out_func <= b;
        end
    end
end

