module mux6to1 (
    input [2:0] sel,
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output reg [3:0] out
);

wire [3:0] mux0_out, mux1_out, mux2_out, mux3_out, mux4_out, mux5_out;
wire [3:0] and_out;

// 2-to-1 MUX
assign mux0_out = (sel[0] == 0) ? data0 : data1;
assign mux1_out = (sel[0] == 0) ? data2 : data3;
assign mux2_out = (sel[0] == 0) ? data4 : data5;

// 4-to-1 MUX
assign mux3_out = (sel[1] == 0) ? mux0_out : mux1_out;
assign mux4_out = (sel[1] == 0) ? mux2_out : 4'b0000;

// AND gate
assign and_out = (sel > 5) ? (mux4_out & sel) : 4'b0000;

// Final 2-to-1 MUX
assign out = (sel[2] == 0) ? mux3_out : and_out;

endmodule

module ABorC (Z, A, B, C);
  output Z;
  input A, B, C;
  wire notA, notB, notC, and1, and2, or1;

  // Invert A, B, C
  NOT nA (notA, A);
  NOT nB (notB, B);
  NOT nC (notC, C);

  // A and not B
  AND2 a1 (and1, A, notB);

  // C or A and not B
  OR2 o1 (or1, and1, C);

  // not A and not B and not C
  AND2 a2 (and2, notA, notB);
  AND2 a3 (Z, and2, notC);

  // Final output
  OR2 o2 (Z, o1, a3);

endmodule

module top_module(
    input [31:0] a,
    input [31:0] b,
    input select,
    output [31:0] sum
);

    wire [15:0] a_low, b_low;
    wire carry_in;
    wire [15:0] sum_low;

    // Split the input numbers into high and low halves
    assign a_low = a[15:0];
    assign b_low = b[15:0];

    // Instantiate the 16-bit adder module
    adder16bit adder(
        .a(a_low),
        .b(b_low),
        .carry_in(carry_in),
        .sum(sum_low)
    );

    // Perform addition or subtraction based on select input
    assign carry_in = (select) ? ~b[15] : 1'b0;
    assign sum = (select) ? {~b,1'b1} + a : {sum_low,a[31:16]} + {a_low,b_low};

endmodule

// 16-bit adder module
module adder16bit(
    input [15:0] a,
    input [15:0] b,
    input carry_in,
    output [15:0] sum
);

    wire [15:0] sum_temp;

    assign sum_temp = a + b + carry_in;
    assign sum = sum_temp;

endmodule

module single_cycle(input clk, input enable, output LED1, output reg LED2, LED3);

reg [32:0] cnt = 0;
reg number = 0;
reg start = 0;
reg stop = 0;
reg reset = 0;
wire debug1, debug2;

single_cycle_top sc(number, reset, debug1, debug2);

always @(negedge enable, posedge stop) begin
    if (stop) begin
        start = 0;
    end else begin
        if (!enable) begin
            start = 1;
        end else begin
            start = 0;
        end
    end
end

always @(posedge clk) begin
    cnt <= cnt + 1'b1;
end

always @(posedge cnt[4]) begin      // normal is 21
    if (!start) begin
        number = 0;
        stop = 0;
        reset = 1;
    end else begin
        reset = 0;
        number = ~number;
        if (debug1 && debug2) begin
            stop = 1;
        end
    end
end

always @(debug1, debug2, start) begin
    if (start) begin
        LED2 = ~debug1;
        LED3 = ~debug2;
    end
end

assign LED1 = !number;

endmodule

module up_down_counter (
    input clk,
    input clear,
    input load,
    input up_down,
    input [3:0] data,
    output reg [3:0] count
);

    always @ (posedge clk) begin
        if (clear) begin
            count <= 4'b0;
        end else if (load) begin
            count <= data;
        end else if (up_down) begin
            count <= count + 1;
        end else begin
            count <= count - 1;
        end
    end

endmodule

module turbo_code (
  input [k-1:0] in,
  output [n-1:0] out,
  input [n-1:0] rec,
  output [k-1:0] dec
);

parameter k = 64; // number of input bits
parameter n = 128; // number of output bits
parameter m = 8; // number of memory elements

// Encoder
reg [m-1:0] enc1_state;
reg [m-1:0] enc2_state;
reg [k-1:0] inter_in;
reg [n-1:0] inter_out;
reg [n-1:0] enc1_out;
reg [n-1:0] enc2_out;

// Decoder
reg [m-1:0] dec1_state;
reg [m-1:0] dec2_state;
reg [n-1:0] extrinsic;
reg [n-1:0] dec1_out;
reg [n-1:0] dec2_out;
reg [k-1:0] deinter_out;

// Interleaver/Deinterleaver
reg [log2(n)-1:0] inter_idx;
reg [log2(n)-1:0] deinter_idx;

// Soft-Decision Decoder
reg [n-1:0] extrinsic_abs;
reg [n-1:0] extrinsic_sign;
reg [k-1:0] dec_out;

// RSC Encoder
always @(posedge clk) begin
  // Shift registers
  enc1_state <= {enc1_state[m-2:0], inter_in[k-1]};
  enc2_state <= {enc2_state[m-2:0], inter_in[k-1]};

  // Feedback and output
  enc1_out <= {enc1_out[n/2-1:0], (enc1_state[0] ^ enc1_state[1] ^ inter_in[k-1])};
  enc2_out <= {enc2_out[n/2-1:0], (enc2_state[0] ^ enc2_state[1] ^ inter_in[k-1])};

  // Update states
  enc1_state[1:m-1] <= enc1_state[0:m-2];
  enc2_state[1:m-1] <= enc2_state[0:m-2];
  enc1_state[0] <= enc1_out[n/2-1];
  enc2_state[0] <= enc2_out[n/2-1];
end

// Interleaver
always @(posedge clk) begin
  inter_idx <= (inter_idx + 1) % n;
  inter_in[inter_idx] <= in[inter_idx];
end

// Bitwise XOR
assign out = enc1_out ^ enc2_out;

// Deinterleaver
always @(posedge clk) begin
  deinter_idx <= (deinter_idx + 1) % n;
  deinter_out[deinter_idx] <= rec[deinter_idx];
end

// RSC Decoder
always @(posedge clk) begin
  // Shift registers
  dec1_state <= {dec1_state[m-2:0], extrinsic[0]};
  dec2_state <= {dec2_state[m-2:0], extrinsic[0]};

  // Feedback and output
  dec1_out <= {dec1_out[n/2-1:0], (dec1_state[0] ^ dec1_state[1] ^ extrinsic[0])};
  dec2_out <= {dec2_out[n/2-1:0], (dec2_state[0] ^ dec2_state[1] ^ extrinsic[0])};

  // Update states
  dec1_state[1:m-1] <= dec1_state[0:m-2];
  dec2_state[1:m-1] <= dec2_state[0:m-2];
  dec1_state[0] <= dec1_out[n/2-1];
  dec2_state[0] <= dec2_out[n/2-1];
end

// Extrinsic Information Calculation
always @(posedge clk) begin
  extrinsic <= dec1_out ^ dec2_out ^ {extrinsic[n/2-1:0], extrinsic[n-1:n/2]};
end

// Soft-Decision Decoder
always @(posedge clk) begin
  extrinsic_abs <= abs(extrinsic);
  extrinsic_sign <= (extrinsic < 0) ? -1 : 1;
  dec_out <= {dec_out[k/2-1:0], (extrinsic_abs[n/2-1] < extrinsic_abs[n/2]) ? 0 : 1};
  dec_out <= {dec_out[k/2-1:0], (extrinsic_abs[0] * extrinsic_sign[0] < extrinsic_abs[n/2] * extrinsic_sign[n/2-1]) ? 0 : 1};
  dec_out <= {dec_out[k/2-1:0], (extrinsic_abs[n/2-1] * extrinsic_sign[n/2-1] < extrinsic_abs[n-1] * extrinsic_sign[n-1]) ? 0 : 1};
  dec_out <= {dec_out[k/2-1:0], (extrinsic_abs[0] * extrinsic_sign[0] < extrinsic_abs[n/2-1] * extrinsic_sign[n/2]) ? 0 : 1};
end

// Deinterleaver
always @(posedge clk) begin
  deinter_idx <= (deinter_idx + n - 1) % n;
  dec <= deinter_out[deinter_idx +: k];
end

endmodule

module sky130_fd_sc_ms__sdfbbn (
    Q      ,
    Q_N    ,
    D      ,
    SCD    ,
    SCE    ,
    CLK_N  ,
    SET_B  ,
    RESET_B,
    VPWR   ,
    VGND   ,
    VPB    ,
    VNB
);

    output Q      ;
    output Q_N    ;
    input  D      ;
    input  SCD    ;
    input  SCE    ;
    input  CLK_N  ;
    input  SET_B  ;
    input  RESET_B;
    input  VPWR   ;
    input  VGND   ;
    input  VPB    ;
    input  VNB    ;

    reg Q;
    reg Q_N;
    reg [1:0] state;

    assign Q_N = ~Q;

    always @ (posedge CLK_N) begin
        if (SCE) begin
            Q <= D;
            Q_N <= ~D;
        end
    end

    always @ (posedge CLK_N) begin
        if (SCD) begin
            Q <= 1'b0;
            Q_N <= 1'b1;
        end
    end

    always @ (posedge CLK_N) begin
        if (SET_B == 1'b0) begin
            Q <= 1'b1;
            Q_N <= 1'b0;
        end
    end

    always @ (posedge CLK_N) begin
        if (RESET_B == 1'b0) begin
            Q <= 1'b0;
            Q_N <= 1'b1;
        end
    end

endmodule

