module barrel_shifter (
    input [15:0] A,
    input [3:0] B,
    output reg [15:0] Y
);

reg [15:0] stage1_out;
reg [15:0] stage2_out;
reg [15:0] stage3_out;

always @(*) begin
    if (B > 15) begin
        Y = 0;
    end else if (B < 0) begin
        stage1_out = {16{A[15]}};
        stage2_out = {stage1_out[15:-B], A[-B-1:0]};
        stage3_out = stage2_out;
        Y = stage3_out;
    end else begin
        stage1_out = {A[B-1:0], A[15:B]};
        stage2_out = stage1_out;
        stage3_out = stage2_out;
        Y = stage3_out;
    end
end

endmodule

module and_ctrl (
    input A1,
    input A2,
    input A3,
    input B1,
    input C1,
    input CTRL,
    output Y
);

    wire cond1, cond2, cond3, cond4;

    assign cond1 = (CTRL == 0) && A1 && A2 && A3;
    assign cond2 = (CTRL == 1) && A1 && A2 && A3 && B1 && !C1;
    assign cond3 = (CTRL == 1) && A1 && A2 && A3 && B1 && C1;
    assign cond4 = (CTRL == 1) && A1 && A2 && A3 && !B1 && C1;

    assign Y = cond1 || cond2 || cond3 || cond4;

endmodule

