module decoder_counter (
    input clk,
    input rst,
    input up_down,
    input [3:0] A,
    input [3:0] B,
    input [3:0] C,
    input [3:0] D,
    output [3:0] count,
    output [15:0] Y,
    output reg [3:0] out
);

reg [2:0] counter;
wire [15:0] decoder_out;

// 4-to-16 decoder
decoder dec(
    .A(A),
    .B(B),
    .C(C),
    .D(D),
    .Y(decoder_out)
);

// 3-bit up/down counter
always @(posedge clk or posedge rst) begin
    if (rst) begin
        counter <= 0;
    end else begin
        if (up_down) begin
            counter <= counter + 1;
        end else begin
            counter <= counter - 1;
        end
    end
end

// Output selection
always @(posedge clk) begin
    case (counter)
        3'd0: out <= decoder_out[0];
        3'd1: out <= decoder_out[1];
        3'd2: out <= decoder_out[2];
        3'd3: out <= decoder_out[3];
        3'd4: out <= decoder_out[4];
        3'd5: out <= decoder_out[5];
        3'd6: out <= decoder_out[6];
        3'd7: out <= decoder_out[7];
        3'd8: out <= decoder_out[8];
        3'd9: out <= decoder_out[9];
        3'd10: out <= decoder_out[10];
        3'd11: out <= decoder_out[11];
        3'd12: out <= decoder_out[12];
        3'd13: out <= decoder_out[13];
        3'd14: out <= decoder_out[14];
        3'd15: out <= decoder_out[15];
    endcase
end

assign count = counter;
assign Y = decoder_out;

endmodule

// 4-to-16 decoder module
module decoder (
    input [3:0] A,
    input [3:0] B,
    input [3:0] C,
    input [3:0] D,
    output reg [15:0] Y
);

always @(*) begin
    case ({A, B, C, D})
        4'b0000: Y = 16'b0000000000000001;
        4'b0001: Y = 16'b0000000000000010;
        4'b0010: Y = 16'b0000000000000100;
        4'b0011: Y = 16'b0000000000001000;
        4'b0100: Y = 16'b0000000000010000;
        4'b0101: Y = 16'b0000000000100000;
        4'b0110: Y = 16'b0000000001000000;
        4'b0111: Y = 16'b0000000010000000;
        4'b1000: Y = 16'b0000000100000000;
        4'b1001: Y = 16'b0000001000000000;
        4'b1010: Y = 16'b0000010000000000;
        4'b1011: Y = 16'b0000100000000000;
        4'b1100: Y = 16'b0001000000000000;
        4'b1101: Y = 16'b0010000000000000;
        4'b1110: Y = 16'b0100000000000000;
        4'b1111: Y = 16'b1000000000000000;
    endcase
end

endmodule

module calculator(clk, rst, op, num1, num2, result, valid);

parameter ADD = 2'b00;
parameter SUB = 2'b01;
parameter MUL = 2'b10;
parameter DIV = 2'b11;

input clk, rst;
input [1:0] op;
input [7:0] num1, num2;
output [7:0] result;
output valid;

reg [7:0] result_reg;
reg valid_reg;

always @(posedge clk) begin
    if (rst) begin
        result_reg <= 8'h00;
        valid_reg <= 1'b0;
    end else begin
        case (op)
            ADD: result_reg <= num1 + num2;
            SUB: result_reg <= num1 - num2;
            MUL: result_reg <= num1 * num2;
            DIV: result_reg <= num1 / num2;
        endcase
        valid_reg <= 1'b1;
    end
end

assign result = result_reg;
assign valid = valid_reg;

endmodule

