module DirSum_46014(
   input clk, reset, next,
   input [4:0] i1,
   input [11:0] X0,
                 X1,
                 X2,
                 X3,
   output [11:0] Y0,
                 Y1,
                 Y2,
                 Y3,
   output next_out);

   reg [9:0] i2;
   reg [11:0] sum;

   always @(posedge clk) begin
      if (reset == 1) begin
         i2 <= 0;
      end
      else begin
         if (next == 1)
            i2 <= 0;
         else if (i2 == 1023)
            i2 <= 0;
         else
            i2 <= i2 + 1;
      end
   end

   always @(X0, X1, X2, X3) begin
      sum = X0 + X1 + X2 + X3;
      Y0 = sum + i1;
      Y1 = sum + i1;
      Y2 = sum + i1;
      Y3 = sum + i1;
   end

   assign next_out = (i2 == 1023);

endmodule

