module FP16BMulS0Of2(
  input clk,
  input rst,
  input signed [15:0] arg_0,
  input signed [15:0] arg_1,
  output signed [15:0] ret_1,
  output signed [15:0] ret_2,
  output signed [15:0] ret_3
);

  wire [31:0] product;

  assign product = arg_0 * arg_1;

  always @(posedge clk) begin
    if (rst) begin
      ret_1 <= 0;
      ret_2 <= 0;
      ret_3 <= 0;
    end else begin
      ret_1 <= product[23:16];
      ret_2 <= product[15:8];
      ret_3 <= product[7:0];
    end
  end

endmodule

module FP16BMulS1Of2(
  input clk,
  input rst,
  input signed [7:0] arg_0,
  input signed [7:0] arg_1,
  input signed [8:0] arg_2,
  output signed [15:0] ret_0
);

  reg [15:0] exponent;
  reg [15:0] fraction;
  reg sign;

  always @(posedge clk) begin
    if (rst) begin
      exponent <= 0;
      fraction <= 0;
      sign <= 0;
    end else begin
      sign <= arg_0;
      exponent <= {arg_1[6], arg_1[5:0], arg_2[7:0]};
      fraction <= {1'b1, arg_2[6:0], arg_1[7:0]};
    end
  end

  assign ret_0 = {sign, exponent, fraction};

endmodule

module memory(clk, we, addr, din, dout);

  parameter MEM_SIZE = 4096;
  parameter ADDR_WIDTH = 12;
