    input [7:0] b,
    input [7:0] c,
    output reg [7:0] sum
);

always @(*)
begin
    if(a < b && a < c)
        sum = a + (b < c ? b : c);
    else if(b < a && b < c)
        sum = b + (a < c ? a : c);
    else
        sum = c + (a < b ? a : b);
end

