module seg_disp(
    input clk,
    input [7:0] d1,
    input [7:0] d2,
    input [7:0] d3,
    input [7:0] d4,
    input dp,
    output reg [6:0] seg,
    output reg [3:0] an,
    output reg dp_pin
);

    wire [6:0] seg1;
    wire [6:0] seg2;
    wire [6:0] seg3;
    wire [6:0] seg4;

    reg [2:0] state = 0;

    number_to_seg dd1(d1, seg1);
    number_to_seg dd2(d2, seg2);
    number_to_seg dd3(d3, seg3);
    number_to_seg dd4(d4, seg4);

    wire nd1 = (d1 == 0);
    wire nd2 = (d2 == 0);
    wire nd3 = (d3 == 0);

    always @(posedge clk) begin
        case (state)
            default: state <= 0;
            0: begin
                seg <= seg1;
                an <= nd1 ? 4'b1111 : 4'b0111;
                dp_pin <= dp;
                state <= state + 1;
            end
            1: begin
                seg <= seg2;
                an <= nd1 && nd2 ? 4'b1111 : 4'b1011;
                dp_pin <= dp;
                state <= state + 1;
            end
            2: begin
                seg <= seg3;
                an <= nd1 && nd2 && nd3 ? 4'b1111 : 4'b1101;
                dp_pin <= dp;
                state <= state + 1;
            end
            3: begin
                seg <= seg4;
                an <= 4'b1110;
                dp_pin <= dp;
                state <= 0;
            end
        endcase
    end

endmodule

