    input clk,
    input rstn,
    input rx_req,
    input [135:0] rx_desc,
    input [63:0] rx_data,
    input [7:0] rx_be,
    input rx_dv,
    input rx_dfr,
    output rx_ack,
    output rx_abort,
    output rx_retry,
    output rx_ws,
    output rx_mask,
    input rx_stream_ready,
    output rx_stream_valid,
    output [107:0] rx_stream_data
);

    // FIFO
    wire fifo_empty;
    wire fifo_almostfull;
    wire fifo_wr;
    wire fifo_rd;
    wire [107:0] fifo_wrdata;
    wire [107:0] fifo_rddata;
    altpcierd_icm_fifo #(
        .RAMTYPE("RAM_BLOCK_TYPE=AUTO")
    ) fifo (
        .clock(clk),
        .aclr(~rstn),
        .data(fifo_wrdata),
        .wrreq(fifo_wr),
        .rdreq(fifo_rd & ~fifo_empty),
        .q(fifo_rddata),
        .full(),
        .almost_full(fifo_almostfull),
        .almost_empty(),
        .empty(fifo_empty)
    );

    // Bridge from Core RX port to Streaming I/F
    altpcierd_icm_rxbridge rx_bridge (
        .clk(clk),
        .rstn(rstn),
        .rx_req(rx_req),
        .rx_desc(rx_desc),
        .rx_dv(rx_dv),
        .rx_dfr(rx_dfr),
        .rx_data(rx_data),
        .rx_be(rx_be),
        .rx_ws(rx_ws),
        .rx_ack(rx_ack),
        .rx_abort(rx_abort),
        .rx_retry(rx_retry),
        .rx_mask(rx_mask),
        .stream_ready(~fifo_almostfull),
        .stream_wr(fifo_wr),
        .stream_wrdata(fifo_wrdata)
    );

    // Streaming interface
    reg [107:0] rx_stream_data_reg;
    reg rx_stream_valid_reg;
    reg [7:0] rx_be_reg;
    reg rx_dv_reg;
    reg rx_dfr_reg;
    always @(posedge clk or negedge rstn) begin
        if (~rstn) begin
            rx_stream_data_reg <= 108'h0;
            rx_stream_valid_reg <= 1'b0;
            rx_be_reg <= 8'h0;
            rx_dv_reg <= 1'b0;
            rx_dfr_reg <= 1'b0;
        end else begin
            rx_stream_data_reg <= fifo_rddata;
            rx_stream_valid_reg <= fifo_rd & ~fifo_empty;
            rx_be_reg <= rx_be;
            rx_dv_reg <= rx_dv;
            rx_dfr_reg <= rx_dfr;
        end
    end
    assign rx_stream_data = rx_stream_data_reg[107:0];
    assign rx_stream_valid = rx_stream_valid_reg;
    assign rx_be = rx_be_reg;
    assign rx_dv = rx_dv_reg;
    assign rx_dfr = rx_dfr_reg;

endmodule

module property_checker(
    input clock,
    input reset,
    input [3:0] data,
    output reg property_met
);

reg [2:0] count;

always @(posedge clock or posedge reset) begin
    if (reset) begin
        count <= 3'b0;
        property_met <= 1'b0;
    end else begin
        if (data == 4'b1100) begin
            count <= count + 1;
        end else begin
            count <= 3'b0;
        end

        if (count == 3) begin
            property_met <= 1'b1;
        end else begin
            property_met <= 1'b0;
        end
    end
end

endmodule

