module signed_addition (
    input clk,
    input reset,
    input signed [3:0] a,
    input signed [3:0] b,
    output signed [4:0] sum
);

    wire [3:0] binary_sum;
    wire carry_out;
    wire [4:0] twos_complement_sum;

    full_adder fa0(a[0], b[0], 1'b0, binary_sum[0], carry_out);
    full_adder fa1(a[1], b[1], carry_out, binary_sum[1], carry_out);
    full_adder fa2(a[2], b[2], carry_out, binary_sum[2], carry_out);
    full_adder fa3(a[3], b[3], carry_out, binary_sum[3], carry_out);

    twos_complement tc(binary_sum, twos_complement_sum);

    always @(posedge clk) begin
        if (reset) begin
            binary_sum <= 4'b0;
            carry_out <= 1'b0;
            twos_complement_sum <= 5'b0;
        end else begin
            binary_sum <= {carry_out, binary_sum[2:0]};
            carry_out <= binary_sum[3];
            twos_complement_sum <= {carry_out, twos_complement_sum[3:1]} + twos_complement_sum[0] + {1'b0, a[3:0], b[3:0]};
        end
    end

    assign sum = twos_complement_sum;

endmodule

