module fifo_buffer (
    input clk,
    input nreset,
    input [71:0] packet_in,
    input access_in,
    output io_clk,
    output io_wait,
    output fifo_wait,
    output access_out,
    output [71:0] fifo_packet_out,
    output [7:0] io_valid,
    output [63:0] io_packet
);

    parameter FIFO_DEPTH = 16;
    wire [71:0] fifo_packet_in;
    wire fifo_access_in;
    wire fifo_access_out;
    wire [71:0] fifo_packet_out;
    wire [7:0] valid;
    wire [63:0] data_wide;
    wire [1:0] emesh_cycle;
    wire [4:0] ctrlmode_in;
    wire [AW-1:0] data_in;
    wire [1:0] datamode_in;
    wire [AW-1:0] dstaddr_in;
    wire [AW-1:0] srcaddr_in;
    wire write_in;
    wire wait_out;
    wire emode;
    wire access_out_sync;

    packet2emesh #(.AW(AW), .PW(PW)) p2e (
        .packet_in(packet_in[PW-1:0]),
        // Outputs
        .write_in(write_in),
        .datamode_in(datamode_in[1:0]),
        .ctrlmode_in(ctrlmode_in[4:0]),
        .dstaddr_in(dstaddr_in[AW-1:0]),
        .srcaddr_in(srcaddr_in[AW-1:0]),
        .data_in(data_in[AW-1:0])
    );

    assign data_wide[63:0] = {srcaddr_in[31:0], data_in[31:0]};

    always @(posedge clk) begin
        if (~wait_out & access_in) begin
            fifo_packet_in[71:0] <= {data_wide[63:0], valid[7:0]};
        end
    end

    assign fifo_access_in = access_in | (|emesh_cycle[1:0]);

    oh_fifo_cdc #(.TARGET(TARGET), .DW(72), .DEPTH(FIFO_DEPTH)) fifo (
        .clk_in(clk),
        .clk_out(io_clk),
        .wait_in(io_wait),
        .prog_full(),
        .full(),
        .empty(),
        .wait_out(fifo_wait),
        .access_in(fifo_access_in),
        .packet_in(fifo_packet_in[71:0]),
        .access_out(fifo_access_out),
        .packet_out(fifo_packet_out[71:0]),
        .nreset(nreset)
    );

    assign io_valid[7:0] = {{(8){fifo_access_out}} & fifo_packet_out[7:0]};
    assign io_packet[63:0] = fifo_packet_out[71:8];

    always @(posedge clk) begin
        if (nreset) begin
            access_out_sync <= 1'b0;
        end else begin
            access_out_sync <= access_out;
        end
    end

    always @(posedge clk or negedge nreset) begin
        if (~nreset) begin
            emesh_cycle[1:0] <= 2'b0;
        end else if (emesh_cycle[0] && (AW == 64)) begin
            emesh_cycle[1:0] <= 2'b10;
        end else if (emode & access_in & ~fifo_wait) begin
            emesh_cycle[1:0] <= 2'b01;
        end else begin
            emesh_cycle[1:0] <= 2'b00;
        end
    end

    assign valid[7:0] = (emesh_cycle[0] && (AW == 32)) ? 8'h3F :
                        (emesh_cycle[1] && (AW == 64)) ? 8'h03 :
                        (~emode & datamode_in[1:0] == 2'b00) ? 8'h01 :
                        (~emode & datamode_in[1:0] == 2'b01) ? 8'h03 :
                        (~emode & datamode_in[1:0] == 2'b10) ? 8'h0F :
                        8'hFF;

    always @(posedge clk) begin
        if (fifo_access_out && access_out_sync) begin
            io_wait <= fifo_wait;
        end else begin
            io_wait <= 1'b0;
        end
    end

    always @(posedge clk) begin
        if (fifo_access_out && access_out_sync) begin
            access_out <= fifo_access_out;
        end else begin
            access_out <= 1'b0;
        end
    end

    always @(posedge clk) begin
        if (fifo_access_out && access_out_sync) begin
            fifo_packet_out <= fifo_packet_out;
        end else begin
            fifo_packet_out <= 72'b0;
        end
    end

    always @(posedge clk) begin
        if (fifo_access_out && access_out_sync) begin
            io_valid <= io_valid;
        end else begin
            io_valid <= 8'b0;
        end
    end

    always @(posedge clk) begin
        if (fifo_access_out && access_out_sync) begin
            io_packet <= io_packet;
        end else begin
            io_packet <= 64'b0;
        end
    end

    always @(posedge clk) begin
        if (fifo_access_out && access_out_sync) begin
            io_clk <= fifo_wait;
        end else begin
            io_clk <= 1'b0;
        end
    end

    assign wait_out = fifo_wait | (|emesh_cycle[1:0]);

    always @(posedge clk) begin
        if (nreset) begin
            emode <= 1'b0;
        end else begin
            emode <= ctrlmode_in[1];
        end
    end

endmodule

module top_module (
    input [7:0] in,
    input [31:0] in_32,
    output reg [7:0] out_byte
);

    // Priority Encoder
    wire [2:0] priority;
    assign priority = ~{in, 1'b0} ? 8 - $countones({in, 1'b0}) : 0;

    // Byte Order Reverser
    wire [31:0] reversed;
    assign reversed = {in_32[7:0], in_32[15:8], in_32[23:16], in_32[31:24]};

    // Byte Selector
    always @* begin
        case (priority)
            3: out_byte = reversed[31:24];
            2: out_byte = reversed[23:16];
            1: out_byte = reversed[15:8];
            0: out_byte = reversed[7:0];
            default: out_byte = 8'b0;
        endcase
    end

endmodule

module my_module (
