reg [3:0] count;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        data_reg1 <= 8'b0;
        data_reg2 <= 8'b0;
        count <= 4'b0;
        valid_b <= 1'b0;
        data_out <= 10'b0;
    end else begin
        if (valid_a && ready_b) begin
            data_reg1 <= data_in;
            data_reg2 <= data_reg1;
            count <= count + 1;
            if (count == 4'b111) begin
                data_out <= {data_out[7:0], data_reg2} + data_reg1;
                valid_b <= 1'b1;
                count <= 4'b0;
            end
        end
    end
end

assign ready_a = ~valid_b;

endmodule

