module fsm_vending_machine (
  input clk,
  input reset,
  input [2:0] buttons,
  input coin,
  output reg [6:0] price_display,
  output reg [6:0] money_display,
  output reg [2:0] dispense
);

  // Define the states
  parameter IDLE = 2'b00;
  parameter WAITING_FOR_SELECTION = 2'b01;
  parameter DISPENSING = 2'b10;

  // Define the prices of the items
  parameter ITEM1_PRICE = 7'd25;
  parameter ITEM2_PRICE = 7'd50;
  parameter ITEM3_PRICE = 7'd75;

  // Define the amount of money needed for each item
  parameter ITEM1_MONEY_NEEDED = ITEM1_PRICE;
  parameter ITEM2_MONEY_NEEDED = ITEM2_PRICE;
  parameter ITEM3_MONEY_NEEDED = ITEM3_PRICE;

  // Define the maximum amount of money that can be inserted
  parameter MAX_MONEY_INSERTED = 7'd255;

  // Define the current state and the next state
  reg [1:0] state, next_state;

  // Define the amount of money inserted
  reg [7:0] money_inserted;

  // Define the item selected
  reg [1:0] item_selected;

  // Define the amount of change to be returned
  reg [7:0] change_to_return;

  // Define the coin slot module
  coin_slot coin_slot_inst (
    .clk(clk),
    .reset(reset),
    .coin(coin),
    .money_inserted(money_inserted)
  );

  // Define the 7-segment display module
  seven_segment_display seven_segment_display_inst (
    .value(price_display),
    .display(money_display)
  );

  // Define the change dispenser module
  change_dispenser change_dispenser_inst (
    .money_inserted(money_inserted),
    .change_to_return(change_to_return),
    .dispense(dispense)
  );

  // Define the state machine
  always @(posedge clk, posedge reset) begin
    if (reset) begin
      state <= IDLE;
      money_inserted <= 0;
      item_selected <= 0;
      change_to_return <= 0;
      price_display <= ITEM1_PRICE;
      money_display <= 0;
      dispense <= 0;
    end else begin
      state <= next_state;
    end
  end

  // Define the state transitions and actions
  always @(*) begin
    case (state)
      IDLE: begin
        if (buttons[0]) begin
          next_state = WAITING_FOR_SELECTION;
          item_selected = 1;
          price_display = ITEM1_PRICE;
        end else if (buttons[1]) begin
          next_state = WAITING_FOR_SELECTION;
          item_selected = 2;
          price_display = ITEM2_PRICE;
        end else if (buttons[2]) begin
          next_state = WAITING_FOR_SELECTION;
          item_selected = 3;
          price_display = ITEM3_PRICE;
        end else begin
          next_state = IDLE;
        end
        money_display = 0;
        dispense = 0;
      end

      WAITING_FOR_SELECTION: begin
        if (buttons[0] && item_selected != 1) begin
          next_state = WAITING_FOR_SELECTION;
          item_selected = 1;
          price_display = ITEM1_PRICE;
        end else if (buttons[1] && item_selected != 2) begin
          next_state = WAITING_FOR_SELECTION;
          item_selected = 2;
          price_display = ITEM2_PRICE;
        end else if (buttons[2] && item_selected != 3) begin
          next_state = WAITING_FOR_SELECTION;
          item_selected = 3;
          price_display = ITEM3_PRICE;
        end else if (coin && money_inserted < MAX_MONEY_INSERTED) begin
          next_state = WAITING_FOR_SELECTION;
          money_inserted = money_inserted + 1;
          money_display = money_inserted;
        end else if (money_inserted >= ITEM1_MONEY_NEEDED && item_selected == 1) begin
          next_state = DISPENSING;
          change_to_return = money_inserted - ITEM1_PRICE;
          money_inserted = 0;
          money_display = 0;
          dispense = 1;
        end else if (money_inserted >= ITEM2_MONEY_NEEDED && item_selected == 2) begin
          next_state = DISPENSING;
          change_to_return = money_inserted - ITEM2_PRICE;
          money_inserted = 0;
          money_display = 0;
          dispense = 2;
        end else if (money_inserted >= ITEM3_MONEY_NEEDED && item_selected == 3) begin
          next_state = DISPENSING;
          change_to_return = money_inserted - ITEM3_PRICE;
          money_inserted = 0;
          money_display = 0;
          dispense = 3;
        end else begin
          next_state = WAITING_FOR_SELECTION;
        end
      end

      DISPENSING: begin
        next_state = IDLE;
        money_display = 0;
        dispense = 0;
      end
    endcase
  end

endmodule

// Define the coin slot module
module coin_slot (
  input clk,
  input reset,
  input coin,
  output reg [7:0] money_inserted
);

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      money_inserted <= 0;
    end else begin
      if (coin) begin
        money_inserted <= money_inserted + 1;
