);

reg [7:0] count;

always @(posedge clk) begin
    if (rst) begin
        count <= 0;
    end else if (load) begin
        count <= data_in;
    end else begin
        if (up_down) begin
            count <= count + 1;
        end else begin
            count <= count - 1;
