module moore_4bit_sequence_detection (
  input clk,
  input reset,
  input [3:0] data,
  output reg match
);

  parameter S0 = 2'b00;
  parameter S1 = 2'b01;
  parameter S2 = 2'b10;
  parameter S3 = 2'b11;

  reg [1:0] state;

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      state <= S0;
      match <= 0;
    end
    else begin
      case (state)
        S0: begin
          if (data == 4'b1_011)
            state <= S1;
          else
            state <= S0;
        end
        S1: begin
          if (data == 4'b10_110)
            state <= S2;
          else
            state <= S0;
        end
        S2: begin
          if (data == 4'b01_101)
            state <= S3;
          else
            state <= S0;
        end
        S3: begin
          state <= S0;
          match <= 1;
        end
      endcase
    end
  end

endmodule

