    end

    // Define the state machine for the AXI slave
    always @(posedge out or negedge s_axi_aresetn) begin
        if (!s_axi_aresetn) begin
            s_state <= IDLE;
            s_ready_reg <= 1'b1;
        end else begin
            case (s_state)
                IDLE: begin
                    if (s_axi_wvalid && s_ready_reg) begin
                        s_state <= BUSY;
                        s_ready_reg <= 1'b0;
                    end
                end
                BUSY: begin
                    if (s_valid) begin
                        s_state <= READY;
                        s_ready_reg <= 1'b1;
                    end
                end
                READY: begin
                    if (!s_axi_wvalid) begin
                        s_state <= IDLE;
