    input [7:0] a,
    input [7:0] b,
    input select,
    output reg [7:0] out
);

    always @(select) begin
        if (select == 1'b0) begin
            out = a;
        end else begin
            out = b;
        end
    end

endmodule

module Memory
(
    input clk_i,
    input rst_i,
    input [31:0] addr_i,
    input [255:0] data_i,
    input enable_i,
    input write_i,
    output ack_o,
    output [255:0] data_o
);

    // Memory
    reg [255:0] memory [0:255]; //16KB
    reg [3:0] count;
    reg ack;
    reg ok;
    reg [255:0] data;
    wire [25:0] addr;

    parameter STATE_IDLE = 2'b00,
              STATE_WAIT = 2'b01,
              STATE_ACK  = 2'b10,
              STATE_FINISH = 2'b11;

    reg [1:0] state;

    assign ack_o = ack;
    assign addr = addr_i[31:6];
    assign data_o = data;

    // Controller
    always @(posedge clk_i or negedge rst_i) begin
        if (~rst_i) begin
            count <= 4'b0;
            ok <= 1'b0;
            ack <= 1'b0;
            state <= STATE_IDLE;
        end
        else begin
            case (state)
                STATE_IDLE: begin
                    if (enable_i) begin
                        count <= count + 1;
                        state <= STATE_WAIT;
                    end
                    else begin
                        state <= STATE_IDLE;
                    end
                end
                STATE_WAIT: begin
                    if (count == 4'd6) begin
                        ok <= 1'b1;
                        state <= STATE_ACK;
                    end
                    else begin
                        count <= count + 1;
                        state <= STATE_WAIT;
                    end
                end
                STATE_ACK: begin
                    count <= 4'b0;
                    ok <= 1'b0;
                    ack <= 1'b1;
                    state <= STATE_FINISH;
                end
                STATE_FINISH: begin
                    ack <= 1'b0;
                    state <= STATE_IDLE;
                end
            endcase
        end
    end

    // Read Data
    always @(posedge clk_i) begin
        if (ok && !write_i) begin
            data <= memory[addr];
        end
    end

    // Write Data
    always @(posedge clk_i) begin
        if (ok && write_i) begin
            memory[addr] <= data_i;
        end
    end

endmodule

module fifo_32in_32out_16kb_ram_based (
    input clk,
    input rst,
    input wr_en,
    input rd_en,
    input [31:0] din,
    output [31:0] dout,
    output empty,
    output full,
    output reg [0:0] wr_data_count
);

    // Internal parameters
    parameter ADDR_WIDTH = 14;
    parameter DATA_WIDTH = 32;
    parameter DEPTH = 2**ADDR_WIDTH;

    // Internal signals
    reg [ADDR_WIDTH-1:0] wr_ptr;
    reg [ADDR_WIDTH-1:0] rd_ptr;
    reg [31:0] mem [0:DEPTH-1];
    wire [ADDR_WIDTH-1:0] count;
    wire [ADDR_WIDTH-1:0] next_wr_ptr;
    wire [ADDR_WIDTH-1:0] next_rd_ptr;
    wire [31:0] next_mem [0:DEPTH-1];
    wire wr_en_ff;
    wire rd_en_ff;
    wire wr_ptr_ff;
    wire rd_ptr_ff;
    wire empty_ff;
    wire full_ff;
    wire [31:0] dout_ff;
    wire [ADDR_WIDTH-1:0] count_ff;

    // Register outputs
    assign empty = empty_ff;
    assign full = full_ff;
    assign wr_data_count = count_ff;

    // Write pointer logic
    always @ (posedge clk or posedge rst) begin
        if (rst) begin
            wr_ptr <= 0;
        end else if (wr_en_ff && !full_ff) begin
            wr_ptr <= next_wr_ptr;
        end
    end

    // Read pointer logic
    always @ (posedge clk or posedge rst) begin
        if (rst) begin
            rd_ptr <= 0;
        end else if (rd_en_ff && !empty_ff) begin
            rd_ptr <= next_rd_ptr;
        end
    end

    // Memory write logic
    always @ (posedge clk or posedge rst) begin
        if (rst) begin
            mem <= 0;
        end else if (wr_en_ff && !full_ff) begin
            mem[next_wr_ptr] <= din;
        end
    end

    // Memory read logic
    always @ (posedge clk or posedge rst) begin
        if (rst) begin
            dout <= 0;
        end else if (rd_en_ff && !empty_ff) begin
            dout <= next_mem[rd_ptr];
        end
    end

    // Count logic
    assign count = wr_ptr - rd_ptr;
    assign empty_ff = (count == 0);
    assign full_ff = (count == DEPTH-1);

    // Next write pointer logic
    assign next_wr_ptr = (wr_ptr == DEPTH-1) ? 0 : wr_ptr + 1'b1;

    // Next read pointer logic
    assign next_rd_ptr = (rd_ptr == DEPTH-1) ? 0 : rd_ptr + 1'b1;

    // Next memory write logic
    assign next_mem = mem;
    assign next_mem[next_wr_ptr] = din;

    // Register logic
    dff_sync rst_ff (.d(1'b0), .clk(clk), .rst(rst), .q(wr_en_ff));
    dff_sync wr_en_sync (.d(wr_en), .clk(clk), .rst(rst), .q(wr_en_ff));
    dff_sync rd_en_sync (.d(rd_en), .clk(clk), .rst(rst), .q(rd_en_ff));
    dff_sync wr_ptr_sync (.d(wr_ptr), .clk(clk), .rst(rst), .q(wr_ptr_ff));
    dff_sync rd_ptr_sync (.d(rd_ptr), .clk(clk), .rst(rst), .q(rd_ptr_ff));
    dff_sync empty_sync (.d(empty_ff), .clk(clk), .rst(rst), .q(empty_ff));
    dff_sync full_sync (.d(full_ff), .clk(clk), .rst(rst), .q(full_ff));
    dff_sync dout_sync (.d(dout), .clk(clk), .rst(rst), .q(dout_ff));
    dff_sync count_sync (.d(count), .clk(clk), .rst(rst), .q(count_ff));

endmodule

module OAI21X1 (
	A0, 
	A1, 
	B0, 
	Y);
   input A0;
   input A1;
   input B0;
   output Y;

   wire nor_output;
   wire and_output;

   assign nor_output = ~(A0 | A1);
   assign and_output = nor_output & B0;
   assign Y = and_output;

endmodule

module digital_filter
(
   // ADC
   input                 adc_clk_i       ,  //!< ADC clock
   input                 adc_rstn_i      ,  //!< ADC reset - active low
   input      [ 14-1: 0] adc_dat_i       ,  //!< ADC data
   output reg [ 14-1: 0] adc_dat_o       ,  //!< ADC data

   // configuration
   input      [ 18-1: 0] cfg_aa_i        ,  //!< config AA coefficient
   input      [ 25-1: 0] cfg_bb_i        ,  //!< config BB coefficient
   input      [ 25-1: 0] cfg_kk_i        ,  //!< config KK coefficient
   input      [ 25-1: 0] cfg_pp_i           //!< config PP coefficient
);

// FIR
wire [ 39-1: 0] bb_mult;
wire [ 33-1: 0] r2_sum;
reg  [ 33-1: 0] r1_reg;
reg  [ 23-1: 0] r2_reg;
reg  [ 32-1: 0] r01_reg;
reg  [ 28-1: 0] r02_reg;

assign bb_mult = $signed(adc_dat_i) * $signed(cfg_bb_i);
assign r2_sum  = $signed(r01_reg) + $signed(r1_reg);

always @(posedge adc_clk_i) begin
   if (adc_rstn_i == 1'b0) begin
      r1_reg  <= 33'h0 ;
      r2_reg  <= 23'h0 ;
      r01_reg <= 32'h0 ;
      r02_reg <= 28'h0 ;
   end
   else begin
      r1_reg  <= $signed(r02_reg) - $signed(r01_reg) ;
      r2_reg  <= r2_sum[33-1:10];
      r01_reg <= {adc_dat_i,18'h0};
      r02_reg <= bb_mult[39-2:10];
   end
end

// IIR 1
wire [ 41-1: 0] aa_mult;
wire [ 49-1: 0] r3_sum;
reg  [ 23-1: 0] r3_reg;

assign aa_mult = $signed(r3_reg) * $signed(cfg_aa_i);
assign r3_sum  = $signed({r2_reg,25'h0}) + $signed({r3_reg,25'h0}) - $signed(aa_mult[41-1:0]);

always @(posedge adc_clk_i) begin
   if (adc_rstn_i == 1'b0) begin
      r3_reg  <= 23'h0 ;
   end
   else begin
      r3_reg  <= r3_sum[49-2:25] ;
   end
end

// IIR 2
wire [ 40-1: 0] pp_mult;
wire [ 16-1: 0] r4_sum;
reg  [ 15-1: 0] r4_reg;
reg  [ 15-1: 0] r3_shr;

assign pp_mult = $signed(r4_reg) * $signed(cfg_pp_i);
assign r4_sum  = $signed(r3_shr) + $signed(pp_mult[40-2:16]);

always @(posedge adc_clk_i) begin
   if (adc_rstn_i == 1'b0) begin
      r3_shr <= 15'h0 ;
      r4_reg <= 15'h0 ;
   end
   else begin
      r3_shr <= r3_reg[23-1:8] ;
      r4_reg <= r4_sum[16-2:0] ;
   end
end

// Scaling
wire [ 40-1: 0] kk_mult;
reg  [ 15-1: 0] r4_reg_r;
reg  [ 15-1: 0] r4_reg_rr;
reg  [ 14-1: 0] r5_reg;

assign kk_mult = $signed(r4_reg_rr) * $signed(cfg_kk_i);

always @(posedge adc_clk_i) begin
   if (adc_rstn_i == 1'b0) begin
      r4_reg_r  <= 15'h0 ;
      r4_reg_rr <= 15'h0 ;
      r5_reg    <= 14'h0 ;
   end
   else begin
      r4_reg_r  <= r4_reg   ;
      r4_reg_rr <= r4_reg_r ;

      if ($signed(kk_mult[40-2:24]) > $signed(14'h1FFF))
         r5_reg <= 14'h1FFF ;
      else if ($signed(kk_mult[40-2:24]) < $signed(14'h2000))
         r5_reg <= 14'h2000 ;
      else
         r5_reg <= kk_mult[24+14-1:24];
   end
end

assign adc_dat_o = r5_reg ;

endmodule

module top_module (
    input a,
    input b,
    input clk,
    input reset,
    output [3:0] Q,
    output reg out_comb
);

reg [3:0] johnson_counter;
reg [63:0] shift_register;
wire xor_result;

// XOR gate implementation
always @(*) begin
    xor_result = a ^ b;
end

// Johnson counter implementation
always @(posedge clk, negedge reset) begin
    if (!reset) begin
        johnson_counter <= 4'b0000;
        shift_register <= 64'b0;
    end else begin
        johnson_counter <= {johnson_counter[2:0], johnson_counter[3]} ^ johnson_counter[0];
        shift_register <= {shift_register[62:0], johnson_counter[3]};
    end
end

// Functional module implementation
always @(posedge clk, negedge reset) begin
    if (!reset) begin
        out_comb <= 1'b0;
    end else begin
        out_comb <= xor_result ^ shift_register[3:0];
    end
end

assign Q = johnson_counter;

endmodule

module dff_with_reset_set_and_delay (
  input clk,
  input rst,
  input set,
  input d,
  input te,
  output reg q
);

  reg [1:0] d_delayed;
  always @(posedge clk) begin
    d_delayed <= {d_delayed[0], d};
  end

  always @(posedge clk) begin
    if (rst) begin
      q <= 1'b0;
    end else if (set) begin
      q <= 1'b1;
    end else if (te) begin
      q <= q;
    end else begin
      q <= d_delayed[1];
    end
  end

endmodule

module shift_register(
    input clk,
    input reset,
    input shift,
    input [7:0] data_in,
    output [7:0] data_out
);

reg [7:0] buffer;
reg [2:0] pointer;

always @(posedge clk) begin
    if (reset) begin
        buffer <= 8'b0;
        pointer <= 3'b0;
    end else if (shift) begin
        buffer[pointer] <= data_in;
        pointer <= pointer + 1;
        if (pointer == 3'b100) begin
            pointer <= 3'b0;
        end
    end
end

assign data_out = {buffer[pointer], buffer[(pointer+1)%8], buffer[(pointer+2)%8], buffer[(pointer+3)%8], buffer[(pointer+4)%8], buffer[(pointer+5)%8], buffer[(pointer+6)%8], buffer[(pointer+7)%8]};

endmodule

module dual_port_mem (
  input             clock_a,
  input [31:0]      data_a,
  input             wren_a,
  input [4:0]       address_a,
  input             clock_b,
  input [31:0]      data_b,
  input             wren_b,
  input [4:0]       address_b,
  output reg [31:0] q_a,
  output reg [31:0] q_b
);

  reg [31:0] mem[31:0];

  always @(posedge clock_a) begin
    if (wren_a) begin
      mem[address_a][7:0]   <= data_a[7:0];
      mem[address_a][15:8]  <= data_a[15:8];
      mem[address_a][23:16] <= data_a[23:16];
      mem[address_a][31:24] <= data_a[31:24];
    end

    q_a <= mem[address_a];
  end

  always @(posedge clock_b) begin
    if (wren_b) begin
      mem[address_b][7:0]   <= data_b[7:0];
      mem[address_b][15:8]  <= data_b[15:8];
      mem[address_b][23:16] <= data_b[23:16];
      mem[address_b][31:24] <= data_b[31:24];
    end

    q_b <= mem[address_b];
  end

endmodule

module wishbone_bridge (
    input   wb_clk_i,
    input   wb_rst_i,
    input   [31:0] wb_master_dat_i,
    input   wb_master_ack_i,
    input   wb_master_stb_i,
    input   [31:0] wb_slave_dat_i,
    input   wb_slave_ack_i,
    input   wb_slave_stb_i,
    output  [31:0] wb_master_dat_o,
    output  wb_master_ack_o,
    output  wb_master_stb_o,
    output  [31:0] wb_slave_dat_o,
    output  wb_slave_ack_o,
    output  wb_slave_stb_o
);

reg [31:0] slave_reg;

assign wb_master_dat_o = wb_slave_dat_i;
assign wb_slave_dat_o = slave_reg;

always @(posedge wb_clk_i) begin
    if (wb_rst_i) begin
        slave_reg <= 0;
        wb_master_ack_o <= 0;
        wb_master_stb_o <= 0;
        wb_slave_ack_o <= 0;
        wb_slave_stb_o <= 0;
    end else begin
        if (wb_master_stb_i && wb_master_ack_o == 0) begin
            wb_master_ack_o <= 1;
            wb_master_stb_o <= 1;
            slave_reg <= wb_master_dat_i;
        end else begin
            wb_master_ack_o <= 0;
            wb_master_stb_o <= 0;
        end

        if (wb_slave_stb_i && wb_slave_ack_o == 0) begin
            wb_slave_ack_o <= 1;
            wb_slave_stb_o <= 1;
            wb_slave_dat_o <= slave_reg;
        end else begin
            wb_slave_ack_o <= 0;
            wb_slave_stb_o <= 0;
        end
    end
end

endmodule

