module fsm_bit_pattern_detection (
  input clk,
  input reset,
  input data,
  output reg match
);

  parameter S_RESET = 2'b00, S_1 = 2'b01, S_2 = 2'b10, S_3 = 2'b11;
  reg [1:0] state;
  reg [2:0] shift_reg;

  always @(posedge clk) begin
    if (reset) begin
      state <= S_RESET;
      shift_reg <= 3'b0;
      match <= 0;
    end
    else begin
      case (state)
        S_RESET: begin
          shift_reg <= {shift_reg[1:0], data};
          if (shift_reg == 3'b101) begin
            match <= 1;
            state <= S_RESET;
          end
          else begin
            match <= 0;
            state <= S_1;
          end
        end

        S_1: begin
          shift_reg <= {shift_reg[1:0], data};
          if (shift_reg == 3'b101) begin
            match <= 1;
            state <= S_RESET;
          end
          else begin
            match <= 0;
            state <= S_2;
          end
        end

        S_2: begin
          shift_reg <= {shift_reg[1:0], data};
          if (shift_reg == 3'b101) begin
            match <= 1;
            state <= S_RESET;
          end
          else begin
            match <= 0;
            state <= S_3;
          end
        end

        S_3: begin
          shift_reg <= {shift_reg[1:0], data};
          if (shift_reg == 3'b101) begin
            match <= 1;
            state <= S_RESET;
          end
          else begin
            match <= 0;
            state <= S_1;
          end
        end
      endcase
    end
  end

endmodule

module p2_tb();

    // Inputs
    reg [31:0] A, B, C;
    reg [1:0] op;

    // Outputs
    wire [31:0] Z;

    // Instantiate the alu_32 module
    alu_32 device(Z, op, A, B, C);

    // Integer variables for looping through all possible input combinations
    integer op_i, val_i_A, val_i_B, val_i_C;

    // Initialize simulation
    initial begin
        // Dump waveform to VCD file
        $dumpfile("p2.vcd");
        $dumpvars(0, device);

        // Monitor output in console
        $monitor("op(%b) A=%b B=%b C=%b => %b", op, A, B, C, Z); 

        // Loop through all possible combinations of op, A, B, and C
        for( op_i = 0; op_i <= 'b11; op_i = op_i + 1) begin
            op = op_i[1:0];
            for(val_i_A = 0; val_i_A <= 'b111; val_i_A = val_i_A + 1) begin
                A = {32{val_i_A[2]}};
                for(val_i_B = 0; val_i_B <= 'b111; val_i_B = val_i_B + 1) begin
                    B = {32{val_i_B[1]}};
                    for(val_i_C = 0; val_i_C <= 'b111; val_i_C = val_i_C + 1) begin
                        C = {32{val_i_C[0]}};
                        #10; // Wait for 10 time units before changing input values
                    end
                end
            end
        end
    end

endmodule

module freq_divider (
    input clk, // Clock input
    input reset, // Asynchronous reset input
    output reg out_clk // Output clock signal with half the frequency of the input clock
);

reg Q1, Q2;

always @(posedge clk, negedge reset) begin
    if (!reset) begin
        Q1 <= 0;
        Q2 <= 0;
    end else begin
        Q1 <= ~Q1;
        Q2 <= ~Q2;
    end
end

assign out_clk = Q1 & Q2;

endmodule

module shift_register(
    input clk,
    input reset,
    input serial_in,
    output reg full,
    output [7:0] parallel_out
);

    reg serial_p;
    reg serial_s;
    reg [3:0] state;
    reg [8:0] shift;
    reg [10:0] count;

    assign parallel_out[7:0] = shift[7:0];

    always @(posedge clk) begin
        serial_p <= serial_in;
        serial_s <= serial_p;
    end

    always @(posedge clk) begin
        if (reset == 1) begin
            state <= 4'h0;
            full <= 0;
        end else begin
            if (state == 4'h0) begin
                full <= 0;
                if (serial_s == 0) begin
                    state <= 4'h1;
                    count <= 651;
                end
            end else if (state == 4'h1) begin
                if (count == 0) begin
                    state <= 4'h2;
                    shift[8:0] <= { serial_s, shift[8:1] };
                    count <= 1302;
                end else begin
                    count <= count - 1;
                end
            end else if (state == 4'h2) begin
                if (count == 0) begin
                    state <= 4'h3;
                    shift[8:0] <= { serial_s, shift[8:1] };
                    count <= 1302;
                end else begin
                    count <= count - 1;
                end
            end else if (state == 4'h3) begin
                if (count == 0) begin
                    state <= 4'h4;
                    shift[8:0] <= { serial_s, shift[8:1] };
                    count <= 1302;
                end else begin
                    count <= count - 1;
                end
            end else if (state == 4'h4) begin
                if (count == 0) begin
                    state <= 4'h5;
                    shift[8:0] <= { serial_s, shift[8:1] };
                    count <= 1302;
                end else begin
                    count <= count - 1;
                end
            end else if (state == 4'h5) begin
                if (count == 0) begin
                    state <= 4'h6;
                    shift[8:0] <= { serial_s, shift[8:1] };
                    count <= 1302;
                end else begin
                    count <= count - 1;
                end
            end else if (state == 4'h6) begin
                if (count == 0) begin
                    state <= 4'h7;
                    shift[8:0] <= { serial_s, shift[8:1] };
                    count <= 1302;
                end else begin
                    count <= count - 1;
                end
            end else if (state == 4'h7) begin
                if (count == 0) begin
                    state <= 4'h8;
                    shift[8:0] <= { serial_s, shift[8:1] };
                    count <= 1302;
                end else begin
                    count <= count - 1;
                end
            end else if (state == 4'h8) begin
                if (count == 0) begin
                    state <= 4'h9;
                    shift[8:0] <= { serial_s, shift[8:1] };
                    count <= 1302;
                end else begin
                    count <= count - 1;
                end
            end else if (state == 4'h9) begin
                if (count == 0) begin
                    state <= 4'ha;
                    shift[8:0] <= { serial_s, shift[8:1] };
                    count <= 1302;
                end else begin
                    count <= count - 1;
                end
            end else if (state == 4'ha) begin
                if (count == 0) begin
                    state <= 4'hb;
                    shift[8:0] <= { serial_s, shift[8:1] };
                    count <= 651;
                end else begin
                    count <= count - 1;
                end
            end else if (state == 4'hb) begin
                state <= 4'h0;
                full <= 1;
            end
        end
    end

endmodule

module elevator_car_driver(clear, current_floor, direction, destination, clock);
  output reg [4:0] current_floor; // 0000 to 1010
  output reg [9:0] clear;
  input direction; // 0 down, 1 up
  input [4:0] destination;
  input clock; // Slow clock or implement 2 sec delay here?

  reg [4:0] counter;
  reg [4:0] next_floor;
  reg [1:0] state; // 00: stationary, 01: moving up, 10: moving down
  reg [1:0] next_state;

  // Initialize the elevator car at the ground floor
  initial begin
    current_floor <= 0;
    counter <= 0;
    state <= 0;
    next_floor <= 0;
  end

  always @(posedge clock) begin
    current_floor <= counter;
    state <= next_state;
    counter <= next_floor;
  end

  always @(*) begin
    // Determine the next state based on the current state and user input
    case (state)
      2'b00: // Stationary
        if (destination > current_floor)
          next_state = 2'b01; // Move up
        else if (destination < current_floor)
          next_state = 2'b10; // Move down
        else
          next_state = 2'b00; // Stay stationary
      2'b01: // Moving up
        if (destination > current_floor)
          next_state = 2'b01; // Continue moving up
        else if (destination < current_floor)
          next_state = 2'b10; // Change direction, move down
        else
          next_state = 2'b00; // Arrived at destination floor
      2'b10: // Moving down
        if (destination < current_floor)
          next_state = 2'b10; // Continue moving down
        else if (destination > current_floor)
          next_state = 2'b01; // Change direction, move up
        else
          next_state = 2'b00; // Arrived at destination floor
    endcase
  end

  always @(*) begin
    // Determine the next floor based on the current floor and state
    case (state)
      2'b00: // Stationary
        next_floor = current_floor;
      2'b01: // Moving up
        if (counter == destination)
          next_floor = destination; // Arrived at destination floor
        else
          next_floor = counter + 1; // Move up one floor
      2'b10: // Moving down
        if (counter == destination)
          next_floor = destination; // Arrived at destination floor
        else
          next_floor = counter - 1; // Move down one floor
    endcase
  end

  always @(posedge clock) begin
    // Clear the floor if the elevator has arrived at the destination floor
    if (clear[counter] == 0 && counter == destination && state == 2'b00)
      clear[counter] <= 1;
    else
      clear[counter] <= 0;
  end

endmodule

