module mpres (
    input clk_in,
    output reg D1,
    output reg D2,
    output reg D3,
    output reg D4
);

//-- Numero de bits de los prescalers
parameter N0 = 1;
parameter N1 = 1;
parameter N2 = 2;
parameter N3 = 3;
parameter N4 = 4;

//-- Registros para los prescalers
reg [N0-1:0] prescaler0;
reg [N1-1:0] prescaler1;
reg [N2-1:0] prescaler2;
reg [N3-1:0] prescaler3;
reg [N4-1:0] prescaler4;

//-- Contadores para los prescalers
reg [N0-1:0] count0;
reg [N1-1:0] count1;
reg [N2-1:0] count2;
reg [N3-1:0] count3;
reg [N4-1:0] count4;

//-- Combinar los prescalers
wire [N0+N1-1:0] prescaler01;
wire [N0+N1+N2-1:0] prescaler012;
wire [N0+N1+N2+N3-1:0] prescaler0123;
wire [N0+N1+N2+N3+N4-1:0] prescaler01234;

assign prescaler01 = {prescaler0, prescaler1};
assign prescaler012 = {prescaler01, prescaler2};
assign prescaler0123 = {prescaler012, prescaler3};
assign prescaler01234 = {prescaler0123, prescaler4};

//-- Generar los clocks de salida
always @(posedge clk_in) begin
    count0 <= count0 + 1;
    if (count0 == prescaler0) begin
        count0 <= 0;
        D1 <= ~D1;
    end

    count1 <= count1 + 1;
    if (count1 == prescaler1) begin
        count1 <= 0;
        D1 <= ~D1;
        D2 <= ~D2;
    end

    count2 <= count2 + 1;
    if (count2 == prescaler2) begin
        count2 <= 0;
        D1 <= ~D1;
        D2 <= ~D2;
        D3 <= ~D3;
    end

    count3 <= count3 + 1;
    if (count3 == prescaler3) begin
        count3 <= 0;
        D1 <= ~D1;
        D2 <= ~D2;
        D3 <= ~D3;
        D4 <= ~D4;
    end

    count4 <= count4 + 1;
    if (count4 == prescaler4) begin
        count4 <= 0;
        D1 <= ~D1;
        D2 <= ~D2;
        D3 <= ~D3;
        D4 <= ~D4;
    end
end

//-- Establecer los prescaler valores
initial begin
    prescaler0 = 2**N0;
    prescaler1 = 2**N1;
    prescaler2 = 2**N2;
    prescaler3 = 2**N3;
    prescaler4 = 2**N4;
end

endmodule

module mem_controller (
  input clk,
  input rst,
  input rw,
  input [$clog2(md)-1:0] addr,
  input [dw-1:0] din,
  output [dw-1:0] dout
);

parameter dw = 8; // data width
parameter md = 256; // memory depth
parameter ml = 2; // memory latency

reg [$clog2(md)-1:0] addr_reg;
reg [dw-1:0] dout_reg;
reg [dw-1:0] mem [0:md-1];
reg [1:0] mem_latency;

always @(posedge clk) begin
  if (rst) begin
    addr_reg <= 0;
    dout_reg <= 0;
    mem <= 0;
    mem_latency <= 0;
  end else begin
    if (rw) begin // read operation
      if (mem_latency == ml) begin
        dout_reg <= mem[addr_reg];
      end else begin
        dout_reg <= dout_reg;
        mem_latency <= mem_latency + 1;
      end
    end else begin // write operation
      mem[addr_reg] <= din;
      dout_reg <= dout_reg;
      mem_latency <= 0;
    end
    addr_reg <= addr;
  end
end

assign dout = dout_reg;

endmodule

module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    output [3:0] S,
    output C_out
);

    wire [3:0] C;
    wire [3:0] X;

    // Full adders
    full_adder FA0(A[0], B[0], 0, X[0], C[0]);
    full_adder FA1(A[1], B[1], C[0], X[1], C[1]);
    full_adder FA2(A[2], B[2], C[1], X[2], C[2]);
    full_adder FA3(A[3], B[3], C[2], X[3], C[3]);

    // Half adders
    half_adder HA0(A[0], B[0], S[0], C[0]);
    half_adder HA1(A[1], B[1], S[1], C[1]);
    half_adder HA2(A[2], B[2], S[2], C[2]);
    half_adder HA3(A[3], B[3], S[3], C_out);

endmodule

module full_adder(
    input A,
    input B,
    input C_in,
    output S,
    output C_out
);

    assign S = A ^ B ^ C_in;
    assign C_out = (A & B) | (C_in & (A ^ B));

endmodule

module half_adder(
    input A,
    input B,
    output S,
    output C_out
);

    assign S = A ^ B;
    assign C_out = A & B;

endmodule

