module clock_control
(
    input ena,
    input [3:0] inclk,
    output outclk
);

    // Detect the type of input clock signal
    reg last_clk;
    reg clk_type;
    always @(posedge inclk[0] or negedge inclk[0]) begin
        if (inclk[0] != last_clk) begin
            last_clk <= inclk[0];
            if (inclk[0] == 1'b1) begin
                clk_type <= 1'b1;
            end else begin
                clk_type <= 1'b0;
            end
        end
    end

    // Generate the output clock signal
    always @(posedge inclk[0] or negedge inclk[0]) begin
        if (ena == 1'b1) begin
            if (clk_type == 1'b1) begin
                outclk <= inclk[0];
            end else begin
                outclk <= ~inclk[0];
            end
        end else begin
            outclk <= 1'b0;
        end
    end

endmodule

module boothMultiplier(
  input [3:0] A,
  input [3:0] B,
  output [7:0] Y
);

  wire [7:0] P;
  reg [4:0] i;
  reg [3:0] A_twos_comp, B_twos_comp;
  reg [8:0] Y_twos_comp;

  assign P = {4'b0, A} * {4'b0, B};

  always @(*) begin
    A_twos_comp = (~A) + 1;
    B_twos_comp = (~B) + 1;
    Y_twos_comp = 0;
    for (i = 0; i < 4; i = i + 1) begin
      if (P[1:0] == 2'b01) begin
        Y_twos_comp = Y_twos_comp - {8'b0, B_twos_comp};
      end else if (P[1:0] == 2'b10) begin
        Y_twos_comp = Y_twos_comp + {8'b0, B_twos_comp};
      end
      P = {P[7], P[7:1]};
    end
    Y = {Y_twos_comp[7], Y_twos_comp[7:0]};
  end

endmodule

