    if (!jrst_n) begin
      x2 <= 0;
      tr_clk <= 0;
      tr_data <= 0;
    end else begin
      x2 <= x1;
      tr_clk <= ~phase;
      tr_data <= phase ? tw[17:0] : tw[35:18];
    end
  end

