    output reg [3:0] counter_out);

    reg [3:0] counter;
    reg [3:0] input1_prev;
    reg [3:0] input2_prev;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 4'b0000;
            input1_prev <= 4'b0000;
            input2_prev <= 4'b0000;
        end
        else begin
            counter <= counter + 1;
            if (counter == 4'b1111) begin
                counter <= 4'b0000;
            end

            input1_prev <= input1;
            input2_prev <= input2;
        end
    end

    assign sum = input1 + input2_prev;
    assign counter_out = counter;

endmodule

module top_module (
    input clk,
    input reset,   // Synchronous active-high reset
    input enable,  // Active-high enable signal
    input [15:0] in, // 16-bit input for the barrel shifter
    output reg [15:0] q // 16-bit output after the addition
);

    reg [7:0] out_hi;
    reg [7:0] out_lo;
    reg [3:0] ones_digit;
    reg [3:0] tens_digit;
    reg [3:0] hundreds_digit;
    reg [3:0] thousands_digit;
    reg [15:0] counter_out;

    barrel_shifter bs(
        .in(in),
        .out_hi(out_hi),
        .out_lo(out_lo)
    );

    binary_counter bc(
        .clk(clk),
        .reset(reset),
        .enable(enable),
        .q(counter_out)
    );

    always @ (posedge clk) begin
        if (reset) begin
            ones_digit <= 4'b0;
            tens_digit <= 4'b0;
            hundreds_digit <= 4'b0;
            thousands_digit <= 4'b0;
        end else if (enable) begin
            ones_digit <= ones_digit + 1;
            if (ones_digit == 10) begin
                ones_digit <= 4'b0;
                tens_digit <= tens_digit + 1;
            end
            if (tens_digit == 10) begin
                tens_digit <= 4'b0;
                hundreds_digit <= hundreds_digit + 1;
            end
            if (hundreds_digit == 10) begin
                hundreds_digit <= 4'b0;
                thousands_digit <= thousands_digit + 1;
            end
        end
    end

    adder add(
        .in_1({thousands_digit, hundreds_digit}),
        .in_2({out_hi, out_lo, counter_out[3:0]}),
        .out(q)
    );

endmodule

