module gost89_ecb_decrypt(
  input              clk,
  input              reset,
  input              load_data,
  input      [511:0] sbox,
  input      [255:0] key,
  input      [63:0]  in,
  output reg [63:0]  out,
  output reg         busy
);
  reg  [5:0]  round_num;
  reg  [31:0] n1, n2, round_key;
  wire [31:0] out1, out2;

  // Instantiate the gost89_round module
  gost89_round
    rnd(clk, sbox, round_key, n1, n2, out1, out2);

  // Initialize the module
  initial begin
    busy = 0;
    round_num = 32;
  end

  // Always block for processing data
  always @(posedge clk) begin
    // Load data into the module
    if (load_data) begin
      n1 <= in[63:32];
      n2 <= in[31:0];
      busy <= 1;
      round_num <= 0;
    end

    // Reset the module
    if (reset && !load_data) begin
      busy <= 0;
      round_num <= 32;
    end

    // Process the data
    if (!reset && !load_data) begin
      // Increment the round number
      if (round_num < 32)
        round_num <= round_num + 1;
      // Perform the round operations
      if (round_num > 0 && round_num < 32) begin
        n1 <= out1;
        n2 <= out2;
      end
      // Output the decrypted data
      if (round_num == 32) begin
        out[63:32] = out2;
        out[31:0]  = out1;
        busy <= 0;
      end
    end
  end

  // Always block for selecting the round key
  always @(posedge clk)
    case (round_num)
      0:  round_key <= key[255:224];
      1:  round_key <= key[223:192];
      2:  round_key <= key[191:160];
      3:  round_key <= key[159:128];
      4:  round_key <= key[127:96];
      5:  round_key <= key[95:64];
      6:  round_key <= key[63:32];
      7:  round_key <= key[31:0];
      8:  round_key <= key[31:0];
      9:  round_key <= key[63:32];
      10: round_key <= key[95:64];
      11: round_key <= key[127:96];
      12: round_key <= key[159:128];
      13: round_key <= key[191:160];
      14: round_key <= key[223:192];
      15: round_key <= key[255:224];
      16: round_key <= key[31:0];
      17: round_key <= key[63:32];
      18: round_key <= key[95:64];
      19: round_key <= key[127:96];
      20: round_key <= key[159:128];
      21: round_key <= key[191:160];
      22: round_key <= key[223:192];
      23: round_key <= key[255:224];
      24: round_key <= key[31:0];
      25: round_key <= key[63:32];
      26: round_key <= key[95:64];
      27: round_key <= key[127:96];
      28: round_key <= key[159:128];
      29: round_key <= key[191:160];
      30: round_key <= key[223:192];
      31: round_key <= key[255:224];
    endcase
endmodule

module chatgpt_generate_JC_counter(
  input                clk,
  input                rst_n,
  input  [3:0]         load,
  output reg  [3:0]    Q
);

  reg [63:0] shift_reg;
  reg [3:0]  next_state;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      shift_reg <= 64'b0;
      Q <= 4'b0;
    end
    else begin
      shift_reg <= {shift_reg[62:0], shift_reg[63]};
      if (load != 4'b0) begin
        shift_reg <= {32'b0, load};
        Q <= load;
      end
      else begin
        next_state = {shift_reg[62], shift_reg[63], shift_reg[0], shift_reg[1]} + shift_reg[63:0];
        shift_reg <= {shift_reg[62:0], next_state[3]};
        Q <= next_state[3:0];
      end
    end
  end

endmodule

module cache_memory (
	input [23:0] CVALID,
	input [3:0] IOSEL,
	input [27:4] ADDR,
	input [15:0] TAG0,
	input [15:0] TAG1,
	input [1:0] CFG,
	input WRITE,
	input MMU_HIT,
	input CI,
	input INVAL_L,
	input KDET,
	input ENDRAM,
	input DC_ILO,
	output CA_HIT,
	output [2:0] CA_SET,
	output [23:0] UPDATE,
	output IO_SPACE,
	output USE_CA,
	output WB_ACC,
	output KILL
);

	// Constants
	parameter CACHE_SIZE = 64;
	parameter CACHE_LINE_SIZE = 4096;
	parameter NUM_SETS = 2;
	parameter NUM_LINES_PER_SET = 2;

	// Internal signals
	reg [1:0] set;
	reg [1:0] line;
	reg [23:0] tag;
	reg [23:0] update;
	wire [23:0] addr_tag;
	wire [1:0] addr_set;
	wire [1:0] hit_set;
	wire [1:0] miss_set;
	wire [1:0] replace_set;
	wire [1:0] update_set;
	wire [1:0] update_line;
	wire [23:0] update_tag;
	wire [23:0] update_cvalid;
	wire [23:0] new_cvalid;
	wire [23:0] lastinfo;
	wire [7:0] maske;
	wire select;
	wire clear;
	wire sel_dram;

	// Cache memory
	reg [23:0] cache_mem [NUM_SETS:0][NUM_LINES_PER_SET:0];
	reg [7:0] cvalid_mem [NUM_SETS:0];

	// Compute address tag and set
	assign addr_tag = ADDR[27:4];
	assign addr_set = ADDR[5:4];

	// Compute hit set and miss set
	assign hit_set = {TAG1 == addr_tag, TAG0 == addr_tag};
	assign miss_set = ~hit_set & {cvalid_mem[1], cvalid_mem[0]};

	// Compute replace set
	assign replace_set = select ? ~hit_set : hit_set;

	// Compute update set and line
	assign update_set = select ? replace_set : hit_set;
	assign update_line = select ? 0 : {cache_mem[update_set][1], cache_mem[update_set][0]} == {CVALID[7:0], CVALID[15:8]};

	// Compute update tag
	assign update_tag = update_set ? TAG1 : TAG0;

	// Compute update cvalid
	assign update_cvalid = update_set ? {CVALID[23:16], update_line, CVALID[6:0]} : {update_line, CVALID[23:16], CVALID[6:0]};

	// Compute new cvalid
	assign new_cvalid = INVAL_L ? {CVALID[23:16], 8'h00, CVALID[6:0]} : update_cvalid;

	// Compute select
	assign maske = 8'h01 << (ADDR[6:4] - 3'h0);
	assign select = cvalid_mem[1] & cvalid_mem[0] ? ~(CVALID[23:16] & maske) : ~CVALID[23];

	// Compute clear
	assign clear = INVAL_L | KDET;

	// Compute update
	assign lastinfo = {CVALID[23:16], 8'h00};
	assign update = {lastinfo, new_cvalid[15:8], new_cvalid[7:0]};

	// Compute CA_HIT
	assign CA_HIT = ((cvalid_mem[1] & (addr_set == 2'b10) & (TAG1 == addr_tag)) | (cvalid_mem[0] & (addr_set == 2'b01) & (TAG0 == addr_tag))) & CFG[0] & ~DC_ILO;

	// Compute CA_SET
	assign CA_SET = hit_set ? {addr_set, line} : replace_set;

	// Compute IO_SPACE
	assign sel_dram = IOSEL == 4'b0000 & ENDRAM;
	assign IO_SPACE = ~sel_dram;

	// Compute USE_CA
	assign USE_CA = CFG[0] & ~CFG[1] & ~CI & ~DC_ILO;

	// Compute WB_ACC
	assign WB_ACC = WRITE & MMU_HIT & sel_dram;

	// Compute KILL
	assign KILL = clear & CA_HIT;

	// Update cache memory and cvalid memory
	always @(posedge CLK) begin
		if (CFG[0] && !CI) begin
			if (CA_HIT) begin
				set <= hit_set;
				line <= (set == 2'b10) ? 1 : 0;
			end else begin
				set <= replace_set;
				line <= select ? 1 : 0;
			end
			tag <= update_tag;
			cache_mem[set][line] <= {CVALID[15:0], ADDR[11:0]};
			cvalid_mem[set] <= new_cvalid[23:16];
		end
	end

	// Assign outputs
	assign UPDATE = update;
	assign CA_SET = {set, line};
	assign sel_dram = IOSEL == 4'b0000 & ENDRAM;
	assign IO_SPACE = ~sel_dram;
	assign USE_CA = CFG[0] & ~CFG[1] & ~CI & ~DC_ILO;
	assign WB_ACC = WRITE & MMU_HIT & sel_dram;
	assign KILL = clear & CA_HIT;
endmodule

