module add_sub_overflow (
    input [3:0] A,
    input [3:0] B,
    input Cn,
    output reg [3:0] S,
    output reg V
);

    // Calculate the sum/difference
    always @(*) begin
        if (Cn == 0) begin
            S = A + B;
        end else begin
            S = A - B;
        end
    end

    // Detect overflow
    always @(*) begin
        if (Cn == 0) begin
            if (A[3] & B[3] & ~S[3]) begin
                V = 1;
            end else if (~A[3] & ~B[3] & S[3]) begin
                V = 1;
            end else begin
                V = 0;
            end
        end else begin
            if (A[3] & ~B[3] & ~S[3]) begin
                V = 1;
            end else if (~A[3] & B[3] & S[3]) begin
                V = 1;
            end else begin
                V = 0;
            end
        end
    end

endmodule

module PWM (
  input clock,
  input ctrl,
  input reset,
  input [15:0] period,
  output pwm_out
);

  reg [15:0] count;
  reg pwm_reg;

  always @(posedge clock) begin
    if (reset) begin
      count <= 0;
      pwm_reg <= 0;
    end else begin
      count <= count + 1;
      if (count >= period) begin
        count <= 0;
      end
      if (count < ctrl * period / 100) begin
        pwm_reg <= 1;
      end else begin
        pwm_reg <= 0;
      end
    end
  end

  assign pwm_out = pwm_reg;

endmodule

