module carry_select_adder (
    input [31:0] A,
    input [31:0] B,
    input Cin,
    output [31:0] S,
    output Cout
);

wire [31:0] sum0, sum1;
wire [31:0] carry0, carry1;
wire [31:0] select;

ripple_carry_adder rca0 (
    .A(A),
    .B(B),
    .Cin(Cin),
    .S(sum0),
    .Cout(carry0)
);

ripple_carry_adder rca1 (
    .A(A),
    .B(B),
    .Cin(~Cin),
    .S(sum1),
    .Cout(carry1)
);

assign select = carry1 & {32{Cin}};
assign S = (select & sum1) | (~select & sum0);
assign Cout = select[31];

endmodule

