// 6-to-1 Priority Encoder-Based Multiplexer
module priority_encoder_mux (
    input [2:0] sel,
    input [5:0] data,
    output reg [3:0] out
);

always @(*) begin
    case (sel)
        3'b000: out = data[0];
        3'b001: out = data[1];
        3'b010: out = data[2];
        3'b011: out = data[3];
        3'b100: out = data[4];
        3'b101: out = data[5];
        default: out = 4'b0000;
    endcase
end

endmodule

module binary_adder(S, COUT, A, B, CIN);
    output [3:0] S;
    output COUT;
    input [3:0] A, B;
    input CIN;

    wire [3:0] carry;
    wire [2:0] sum;

    // First Full Adder
    full_adder fa0(.S(sum[0]), .C(carry[0]), .A(A[0]), .B(B[0]), .CIN(CIN));
    // Second Full Adder
    full_adder fa1(.S(sum[1]), .C(carry[1]), .A(A[1]), .B(B[1]), .CIN(carry[0]));
    // Third Full Adder
    full_adder fa2(.S(sum[2]), .C(carry[2]), .A(A[2]), .B(B[2]), .CIN(carry[1]));
    // Fourth Full Adder
    full_adder fa3(.S(sum[3]), .C(COUT), .A(A[3]), .B(B[3]), .CIN(carry[2]));

    assign S = sum;
endmodule

module full_adder(S, C, A, B, CIN);
    output S, C;
    input A, B, CIN;

    wire s1, c1, c2;

    // First Half Adder
    half_adder ha1(.S(s1), .C(c1), .A(A), .B(B));
    // Second Half Adder
    half_adder ha2(.S(S), .C(c2), .A(s1), .B(CIN));
    // Carry Out
    assign C = c1 | c2;
endmodule

module half_adder(S, C, A, B);
    output S, C;
    input A, B;

    // Sum
    xor(S, A, B);
    // Carry
    and(C, A, B);
endmodule

