        .D(D),
        .SEL0(SEL0),
        .SEL1(SEL1),
        .MUX_OUT(mux_out)
    );

    // 4-bit Shift Register with Parallel Load
    shift_reg_4bit shift_reg_inst (
        .data_in(mux_out),
        .load(load),
        .shift_left(shift_left),
        .shift_right(shift_right),
        .shift_reg_out(shift_reg_out)
