module add_sub_32bit (
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] sum
);

    wire [15:0] carry_out1, carry_out2;
    wire [15:0] sum1, sum2;
    wire [31:0] a_inv;

    assign a_inv = (sub) ? ~a : a;

    carry_select_adder_16bit adder1 (
        .a(a_inv[15:0]),
        .b(b[15:0]),
        .cin(1'b0),
        .sub(1'b0),
        .sum(sum1),
        .cout(carry_out1)
    );

    carry_select_adder_16bit adder2 (
        .a(a_inv[31:16]),
        .b(b[31:16]),
        .cin(carry_out1),
        .sub(1'b0),
        .sum(sum2),
        .cout(carry_out2)
    );

    assign sum = {sum2, sum1};

    xor x (
        .a(b),
        .b(sub),
        .y(b_inv)
    );

    assign b_inv = (sub) ? ~b : b;

endmodule

module carry_select_adder_16bit (
    input [15:0] a,
    input [15:0] b,
    input cin,
    input sub,
    output [15:0] sum,
    output cout
);

    wire [15:0] p, g;
    wire [15:0] c1, c2, c3, c4;
    wire [15:0] s1, s2, s3;

    assign p = a ^ b;
    assign g = a & b;

    assign c1 = cin;
    assign c2 = g | (p & c1);
    assign c3 = (g & c1) | (p & (c1 ^ g));
    assign c4 = (c1 & c2) | (p & (c1 ^ c2));

    assign s1 = a ^ b ^ cin;
    assign s2 = p ^ c1;
    assign s3 = c2 ^ c3;

    assign sum = (sub) ? s3 : s2;
    assign cout = (sub) ? ~c4 : c4;

endmodule

