        .in2(sum_addsub),
        .out(sum_func_out)
    );

endmodule

module fifo_buffer (
    input clk,
    input reset,
    input if_read_ce,
    input if_read,
    input if_write_ce,
    input if_write,
    input [DATA_WIDTH-1:0] if_din,
    output if_empty_n,
    output if_full_n,
    output [DATA_WIDTH-1:0] if_dout
);

parameter MEM_STYLE = "auto";
parameter DATA_WIDTH = 32'd8;
parameter ADDR_WIDTH = 32'd1;
parameter DEPTH = 32'd2;

wire [ADDR_WIDTH-1:0] read_ptr, write_ptr, next_write_ptr;
wire [DATA_WIDTH-1:0] read_data;
wire [DEPTH-1:0] count;
wire empty, full;

assign empty = (read_ptr == write_ptr) & ~if_read;
assign full = (count == DEPTH) & ~if_write;

assign if_empty_n = ~empty;
assign if_full_n = ~full;

assign if_dout = read_data;

assign next_write_ptr = write_ptr + 1'b1;

// Memory
genvar i;
generate
if (MEM_STYLE == "distributed") begin : distributed_memory
    reg [DATA_WIDTH-1:0] memory [DEPTH-1:0];
    always @(posedge clk) begin
        if (reset) begin
            for (i = 0; i < DEPTH; i = i + 1) begin
                memory[i] <= 0;
            end
        end else if (if_write & if_write_ce & ~full) begin
            memory[write_ptr] <= if_din;
        end
    end
    always @(posedge clk) begin
        if (reset) begin
            write_ptr <= 0;
        end else if (if_write & if_write_ce & ~full) begin
            write_ptr <= next_write_ptr;
        end
    end
    always @(*) begin
        read_data = memory[read_ptr];
    end
end else if (MEM_STYLE == "block") begin : block_memory
    reg [DATA_WIDTH-1:0] memory [0:DEPTH-1];
    always @(posedge clk) begin
        if (reset) begin
            for (i = 0; i < DEPTH; i = i + 1) begin
                memory[i] <= 0;
            end
        end else if (if_write & if_write_ce & ~full) begin
            memory[write_ptr] <= if_din;
        end
    end
    always @(posedge clk) begin
        if (reset) begin
            write_ptr <= 0;
        end else if (if_write & if_write_ce & ~full) begin
            write_ptr <= next_write_ptr;
        end
    end
    always @(*) begin
        read_data = memory[read_ptr];
    end
end else begin : auto_memory
    reg [DATA_WIDTH-1:0] memory [0:DEPTH-1];
    always @(posedge clk) begin
        if (reset) begin
            for (i = 0; i < DEPTH; i = i + 1) begin
                memory[i] <= 0;
            end
        end else if (if_write & if_write_ce & ~full) begin
            memory[write_ptr] <= if_din;
        end
    end
    always @(posedge clk) begin
        if (reset) begin
            write_ptr <= 0;
        end else if (if_write & if_write_ce & ~full) begin
            write_ptr <= next_write_ptr;
        end
    end
    always @(*) begin
        read_data = memory[read_ptr];
    end
end
endgenerate

// Pointers and Counter
always @(posedge clk) begin
    if (reset) begin
        read_ptr <= 0;
        write_ptr <= 0;
        count <= 0;
    end else begin
        if (if_read & if_read_ce & ~empty) begin
            read_ptr <= read_ptr + 1'b1;
        end
        if (if_write & if_write_ce & ~full) begin
            count <= count + 1'b1;
        end
        if (if_read & if_read_ce & ~empty) begin
            count <= count - 1'b1;
        end
    end
end

endmodule

