module unsigned_multiplier(A, B, CLK, Y);
  input [3:0] A;
  input [3:0] B;
  input CLK;
  output reg [7:0] Y;
  reg [3:0] P;
  reg [2:0] count;
  always @(posedge CLK) begin
    if (count == 0) begin
      P <= 4'b0000;
      Y <= 8'b00000000;
    end else if (count == 1) begin
      if (B[0] == 1) P <= A;
    end else if (count == 2) begin
      if (B[1] == 1) P <= {4'b0000, A} + {A, 4'b0000};
    end else if (count == 3) begin
      if (B[2] == 1) P <= {3'b000, A} + {2'b00, A, 2'b00} + {A, 3'b000};
    end else if (count == 4) begin
      if (B[3] == 1) P <= {2'b0000, A} + {3'b000, A, 1'b0} + {2'b00, A, 2'b00} + {A, 2'b0000};
      Y <= {P, 4'b0000};
    end
    count <= count + 1;
  end
endmodule

module clock_and_power(
    pck0, ck_1356meg, ck_1356megb,
    pwr_lo, pwr_hi, pwr_oe1, pwr_oe2, pwr_oe3, pwr_oe4,
    adc_d, adc_clk,
    ssp_frame, ssp_din, ssp_dout, ssp_clk,
    cross_hi, cross_lo,
    dbg,
    shallow_modulation
);
    input pck0, ck_1356meg, ck_1356megb;
    output pwr_lo, pwr_hi, pwr_oe1, pwr_oe2, pwr_oe3, pwr_oe4;
    input [7:0] adc_d;
    output adc_clk;
    output ssp_frame, ssp_din, ssp_clk;
    input ssp_dout;
    input cross_hi, cross_lo;
    output dbg;
    input shallow_modulation;

    // low frequency outputs, not relevant
    assign pwr_lo = 1'b0;
    assign pwr_oe2 = 1'b0;

    // The high-frequency stuff. For now, for testing, just bring out the carrier,
    // and allow the ARM to modulate it over the SSP.
    reg pwr_hi;
    reg pwr_oe1;
    reg pwr_oe3;
    reg pwr_oe4;

    always @*
    begin
        if(shallow_modulation)
        begin
            pwr_hi = ck_1356megb;
            pwr_oe1 = 1'b0;
            pwr_oe3 = 1'b0;
            pwr_oe4 = ~ssp_dout;
        end
        else
        begin
            pwr_hi = ck_1356megb & ssp_dout;
            pwr_oe1 = 1'b0;
            pwr_oe3 = 1'b0;
            pwr_oe4 = 1'b0;
        end
    end

    // Then just divide the 13.56 MHz clock down to produce appropriate clocks
    // for the synchronous serial port.
    reg [6:0] hi_div_by_128;
    reg [2:0] hi_byte_div;
    reg ssp_clk_div;

    always @(posedge ck_1356meg)
    begin
        hi_div_by_128 <= hi_div_by_128 + 1;
        if(hi_div_by_128 == 7'd0)
            adc_clk <= ~adc_clk;
    end

    always @(negedge adc_clk)
    begin
        hi_byte_div <= hi_byte_div + 1;
        if(hi_byte_div == 3'd3)
            ssp_frame <= 1'b1;
        else
            ssp_frame <= 1'b0;
        ssp_din <= 1'b0;
    end

    always @(posedge adc_clk)
    begin
        ssp_clk_div <= ~ssp_clk_div;
        ssp_clk <= ssp_clk_div;
    end

    // Set unused inputs to 0
    assign ssp_din = 1'b0;
    assign cross_hi = 1'b0;
    assign cross_lo = 1'b0;
    assign dbg = ssp_frame;

    // Set output enables based on pwr_hi
    assign pwr_oe1 = 1'b0;
    assign pwr_oe3 = 1'b0;
    always @*
    begin
        if(pwr_hi)
            pwr_oe4 = 1'b0;
        else
            pwr_oe4 = 1'b1;
    end

endmodule

module MUX4X1 (A, B, C, D, S, Z);
input A, B, C, D, S[1:0];
output Z;

wire Z1, Z2;

// Implement the logic for the MUX4X1 module
// using a combination of AND, OR, and NOT gates
not (S0_not, S[0]);
not (S1_not, S[1]);
and (A_and, A, S0_not, S1_not);
and (B_and, B, S0_not, S[1]);
and (C_and, C, S[0], S1_not);
and (D_and, D, S[0], S[1]);
or (Z1_or, A_and, B_and);
or (Z2_or, C_and, D_and);
or (Z, Z1_or, Z2_or);

endmodule

