module denise_playfields
(
  input  aga,
  input   [8:1] bpldata,         //raw bitplane data in
  input   dblpf,             //double playfield select
  input [2:0] pf2of,        // playfield 2 offset into color table
  input  [6:0] bplcon2,      //bplcon2 (playfields priority)
  output  reg [2:1] nplayfield,  //playfield 1,2 valid data
  output  reg [7:0] plfdata    //playfield data out
);

//local signals
wire pf2pri;            //playfield 2 priority over playfield 1
wire [2:0] pf2p;          //playfield 2 priority code
reg [7:0] pf2of_val;    // playfield 2 offset value

assign pf2pri = bplcon2[6];
assign pf2p = bplcon2[5:3];

always @ (*) begin
  case(pf2of)
    3'd0 : pf2of_val = 8'd0;
    3'd1 : pf2of_val = 8'd2;
    3'd2 : pf2of_val = 8'd4;
    3'd3 : pf2of_val = 8'd8;
    3'd4 : pf2of_val = 8'd16;
    3'd5 : pf2of_val = 8'd32;
    3'd6 : pf2of_val = 8'd64;
    3'd7 : pf2of_val = 8'd128;
  endcase
end

//generate playfield 1,2 data valid signals
always @(*)
begin
  if (dblpf) //dual playfield
  begin
    if (bpldata[7] || bpldata[5] || bpldata[3] || bpldata[1]) //detect data valid for playfield 1
      nplayfield[1] = 1;
    else
      nplayfield[1] = 0;

    if (bpldata[8] || bpldata[6] || bpldata[4] || bpldata[2]) //detect data valid for playfield 2
      nplayfield[2] = 1;
    else
      nplayfield[2] = 0;
  end
  else //single playfield is always playfield 2
  begin
    nplayfield[1] = 0;
    if (bpldata[8:1]!=8'b000000)
      nplayfield[2] = 1;
    else
      nplayfield[2] = 0;
  end
end

//playfield 1 and 2 priority logic
always @(*)
begin
  if (dblpf) //dual playfield
  begin
    if (pf2pri) //playfield 2 (2,4,6) has priority
    begin
      if (nplayfield[2])
        if (aga)
          plfdata[7:0] = {4'b0000,bpldata[8],bpldata[6],bpldata[4],bpldata[2]} + pf2of_val;
        else
          plfdata[7:0] = {4'b0000,1'b1,bpldata[6],bpldata[4],bpldata[2]};
      else if (nplayfield[1])
        plfdata[7:0] = {4'b0000,bpldata[7],bpldata[5],bpldata[3],bpldata[1]};
      else //both planes transparant, select background color
        plfdata[7:0] = 8'b00000000;
    end
    else //playfield 1 (1,3,5) has priority
    begin
      if (nplayfield[1])
        plfdata[7:0] = {4'b0000,bpldata[7],bpldata[5],bpldata[3],bpldata[1]};
      else if (nplayfield[2])
        if (aga)
          plfdata[7:0] = {4'b0000,bpldata[8],bpldata[6],bpldata[4],bpldata[2]} + pf2of_val;
        else
          plfdata[7:0] = {4'b0000,1'b1,bpldata[6],bpldata[4],bpldata[2]};
      else //both planes transparent, select background color
        plfdata[7:0] = 8'b00000000;
    end
  end
  else //normal single playfield (playfield 2 only)
  //OCS/ECS undocumented feature when bpu=5 and pf2pri>5 (Swiv score display)
    if ((pf2p>5) && bpldata[5] && !aga)
      plfdata[7:0] = {8'b00010000};
    else
      plfdata[7:0] = bpldata[8:1];
end

endmodule

module clock_generator (
  input clk_in,
  input rst,
  output reg clk_out
);

  localparam DELAY = 100; // 100 ps delay from clk_in to clk_out
  localparam HALF_PERIOD = 2.5; // half period of clk_out in ns

  reg [15:0] counter = 16'd0;
  reg prev_clk_in = 1'b0;

  always @(posedge clk_in or negedge rst) begin
    if (~rst) begin
      counter <= 16'd0;
      prev_clk_in <= 1'b0;
      clk_out <= 1'b0;
    end else begin
      if (prev_clk_in && ~clk_in) begin
        counter <= counter + 1;
        if (counter == (DELAY / HALF_PERIOD)) begin
          clk_out <= ~clk_out;
          counter <= 16'd0;
        end
      end
      prev_clk_in <= clk_in;
    end
  end

endmodule

module flip_flop_async_set_reset (
    input wire D,
    input wire SET_B,
    input wire RESET_B,
    input wire VPWR,
    input wire VGND,
    input wire VPB,
    input wire VNB,
    output reg Q,
    output reg Q_N
);

    // Define constants for unknown and high impedance values
    localparam UNKNOWN = 1'bx;
    localparam HIGH_IMPEDANCE = 1'bz;

    // Define internal signals
    wire Qn;
    wire Qn_bar;
    wire D_bar;
    wire SET_B_bar;
    wire RESET_B_bar;

    // Connect internal signals
    assign Qn = ~Q;
    assign Qn_bar = ~Qn;
    assign D_bar = ~D;
    assign SET_B_bar = ~SET_B;
    assign RESET_B_bar = ~RESET_B;

    // Define power and bias voltage signals
    wire VPWR_valid = (VPWR != HIGH_IMPEDANCE);
    wire VGND_valid = (VGND != HIGH_IMPEDANCE);
    wire VPB_valid = (VPB != HIGH_IMPEDANCE);
    wire VNB_valid = (VNB != HIGH_IMPEDANCE);

    // Define power and bias voltage levels
    localparam VPWR_level = 1'b1;
    localparam VGND_level = 1'b0;
    localparam VPB_level = 1'b1;
    localparam VNB_level = 1'b0;

    // Ensure power and bias voltages are valid
    assign VPWR = (VPWR_valid) ? VPWR_level : UNKNOWN;
    assign VGND = (VGND_valid) ? VGND_level : UNKNOWN;
    assign VPB = (VPB_valid) ? VPB_level : UNKNOWN;
    assign VNB = (VNB_valid) ? VNB_level : UNKNOWN;

    // Define flip-flop behavior
    always @ (posedge VGND, negedge VPWR, negedge VPB, negedge VNB, negedge SET_B_bar, negedge RESET_B_bar)
    begin
        // Handle asynchronous set and reset inputs
        if (!SET_B_bar)
        begin
            Q <= 1'b1;
            Q_N <= 1'b0;
        end
        else if (!RESET_B_bar)
        begin
            Q <= 1'b0;
            Q_N <= 1'b1;
        end
        // Handle data input
        else
        begin
            Q <= D;
            Q_N <= D_bar;
        end
    end

endmodule

module full_adder (
