module bit_reversal (
    input [31:0] in,
    output [31:0] out
);

wire [7:0] byte0, byte1, byte2, byte3;

shift_reg #(.WIDTH(8), .DEPTH(4)) sr0 (.in(in[7:0]), .out(byte0));
shift_reg #(.WIDTH(8), .DEPTH(4)) sr1 (.in(in[15:8]), .out(byte1));
shift_reg #(.WIDTH(8), .DEPTH(4)) sr2 (.in(in[23:16]), .out(byte2));
shift_reg #(.WIDTH(8), .DEPTH(4)) sr3 (.in(in[31:24]), .out(byte3));

mux #(.WIDTH(8), .DEPTH(4)) mux0 (.in0(byte0), .in1(byte3), .sel(in[1:0]), .out(out[31:24]));
mux #(.WIDTH(8), .DEPTH(4)) mux1 (.in0(byte1), .in1(byte2), .sel(in[1:0]), .out(out[23:16]));
mux #(.WIDTH(8), .DEPTH(4)) mux2 (.in0(out[31:24]), .in1(out[23:16]), .sel(in[3:2]), .out(out[15:8]));
mux #(.WIDTH(8), .DEPTH(4)) mux3 (.in0(out[15:8]), .in1(out[7:0]), .sel(in[3:2]), .out(out[7:0]));

