module priority_encoder (
    input [7:0] in,
    output reg [2:0] pos
);

    // Binary-to-Gray code converter
    wire [7:0] gray_in;
    assign gray_in[0] = in[0];
    assign gray_in[1] = in[0] ^ in[1];
    assign gray_in[2] = in[1] ^ in[2];
    assign gray_in[3] = in[2] ^ in[3];
    assign gray_in[4] = in[3] ^ in[4];
    assign gray_in[5] = in[4] ^ in[5];
    assign gray_in[6] = in[5] ^ in[6];
    assign gray_in[7] = in[6] ^ in[7];

    // Gray-to-binary code converter
    wire [7:0] gray_out;
    assign gray_out[7] = gray_in[7];
    assign gray_out[6] = gray_in[7] ^ gray_in[6];
    assign gray_out[5] = gray_in[6] ^ gray_in[5];
    assign gray_out[4] = gray_in[5] ^ gray_in[4];
    assign gray_out[3] = gray_in[4] ^ gray_in[3];
    assign gray_out[2] = gray_in[3] ^ gray_in[2];
    assign gray_out[1] = gray_in[2] ^ gray_in[1];
    assign gray_out[0] = gray_in[1] ^ gray_in[0];

    // Priority encoder
    always @* begin
        if (in == 0) begin
            pos = 0;
        end else if (gray_out[7] == 1) begin
            pos = 7;
        end else if (gray_out[6] == 1) begin
            pos = 6;
        end else if (gray_out[5] == 1) begin
            pos = 5;
        end else if (gray_out[4] == 1) begin
            pos = 4;
        end else if (gray_out[3] == 1) begin
            pos = 3;
        end else if (gray_out[2] == 1) begin
            pos = 2;
        end else if (gray_out[1] == 1) begin
            pos = 1;
        end else if (gray_out[0] == 1) begin
            pos = 0;
        end
    end

endmodule

module barrel_shifter (
    input [3:0] data_in,
    input [1:0] shift_amount,
    input direction_left,
    output reg [3:0] data_out
);

reg [3:0] shift_reg [1:3];

always @(*) begin
    shift_reg[1] = data_in;
    shift_reg[2] = shift_reg[1] << 1;
    shift_reg[3] = shift_reg[2] << 1;

    if (shift_amount == 2'b00) begin
        data_out = data_in;
    end else if (shift_amount == 2'b01) begin
        data_out = shift_reg[2];
    end else if (shift_amount == 2'b10) begin
        data_out = shift_reg[3];
    end else if (shift_amount == 2'b11) begin
        data_out = direction_left ? shift_reg[3] : shift_reg[1];
    end
end

endmodule

module dispatchu(
  input clk,
  input [15:0] memDat,
  input [15:0] aDat,
  input [15:0] bDat,
  input [15:0] cDat,
  input [31:0] addr,
  output reg [15:0] memOut,
  output reg memWrite,
  output reg [15:0] cOut,
  output reg cWrite,
  output reg [2:0] aSel,
  output reg [2:0] bSel,
  output reg [2:0] cSel,
  output reg [3:0] intOp,
  output reg [2:0] intA,
  output reg [2:0] intB,
  output reg [2:0] intC
);

reg [15:0] memoryArray[15:0]; 
reg [3:0] memSel;
assign memOut=memoryArray[memSel];

always @(posedge clk) begin
  if(memWrite) begin
    memoryArray[addr%16]<=memDat;
  end
  else begin
    memSel<=addr%16;
  end

  case(intOp)
    4'b0000: begin //add
      aSel<=3'b000;
      bSel<=3'b001;
      cSel<=3'b010;
      intA<=3'b000;
      intB<=3'b001;
      intC<=3'b010;
      cWrite<=1'b1;
      cOut<=aDat+bDat;
    end
    4'b0001: begin //subtract
      aSel<=3'b000;
      bSel<=3'b001;
      cSel<=3'b010;
      intA<=3'b000;
      intB<=3'b001;
      intC<=3'b010;
      cWrite<=1'b1;
      cOut<=aDat-bDat;
    end
    4'b0010: begin //multiply
      aSel<=3'b000;
      bSel<=3'b001;
      cSel<=3'b010;
      intA<=3'b000;
      intB<=3'b001;
      intC<=3'b010;
      cWrite<=1'b1;
      cOut<=aDat*bDat;
    end
    4'b0011: begin //divide
      aSel<=3'b000;
      bSel<=3'b001;
      cSel<=3'b010;
      intA<=3'b000;
      intB<=3'b001;
      intC<=3'b010;
      cWrite<=1'b1;
      cOut<=aDat/bDat;
    end
    4'b0100: begin //load from memory
      aSel<=3'b011;
      bSel<=3'b000;
      cSel<=3'b010;
      intA<=3'b000;
      intB<=3'b000;
      intC<=3'b010;
      cWrite<=1'b1;
      cOut<=memOut;
    end
    4'b0101: begin //store to memory
      aSel<=3'b000;
      bSel<=3'b001;
      cSel<=3'b011;
      intA<=3'b000;
      intB<=3'b001;
      intC<=3'b000;
      memWrite<=1'b1;
      memDat<=bDat;
    end
    4'b0110: begin //jump
      aSel<=3'b000;
      bSel<=3'b000;
      cSel<=3'b000;
      intA<=3'b000;
      intB<=3'b000;
      intC<=3'b000;
      cWrite<=1'b0;
      if(aDat==0) begin
        addr<=addr+1;
      end
      else begin
        addr<=bDat;
      end
    end
    4'b0111: begin //jump if equal
      aSel<=3'b000;
      bSel<=3'b001;
      cSel<=3'b000;
      intA<=3'b000;
      intB<=3'b001;
      intC<=3'b000;
      cWrite<=1'b0;
      if(aDat==bDat) begin
        addr<=cDat;
      end
      else begin
        addr<=addr+1;
      end
    end
    4'b1000: begin //jump if not equal
      aSel<=3'b000;
      bSel<=3'b001;
      cSel<=3'b000;
      intA<=3'b000;
      intB<=3'b001;
      intC<=3'b000;
      cWrite<=1'b0;
      if(aDat!=bDat) begin
        addr<=cDat;
      end
      else begin
        addr<=addr+1;
      end
    end
    default: begin //nop
      aSel<=3'b000;
      bSel<=3'b000;
      cSel<=3'b000;
      intA<=3'b000;
      intB<=3'b000;
      intC<=3'b000;
      cWrite<=1'b0;
      addr<=addr+1;
    end
  endcase
end

endmodule

module top_module (
    input [7:0] a,
    input [7:0] b,
    output [7:0] s,
    output overflow
);

wire [8:0] csa_out;
wire [7:0] add_one_out;

carry_select_adder csa_inst (
    .a(a),
    .b(b),
    .c_out(csa_out[8]),
    .s(csa_out[7:0])
);

add_one add_one_inst (
    .a(csa_out[7:0]),
    .s(add_one_out)
);

assign s = add_one_out;
assign overflow = (csa_out[8] != add_one_out[7]);

endmodule

module carry_select_adder (
    input [7:0] a,
    input [7:0] b,
    output [8:0] s,
    output c_out
);

wire [7:0] p;
wire [7:0] g;
wire [7:0] c;

genvar i;
generate
    for (i = 0; i < 8; i = i + 1) begin : gen
        assign p[i] = a[i] ^ b[i];
        assign g[i] = a[i] & b[i];
        assign c[i] = i == 0 ? 1'b0 : g[i-1] | (p[i-1] & c[i-1]);
        assign s[i] = p[i] ^ c[i];
    end
endgenerate

assign s[8] = c[7];
assign c_out = g[7] | (p[7] & c[7]);

endmodule

