module top_module (
    input clk,
    input rst_n,
    input [7:0] in,
    output [7:0] anyedge,
    output reg valid_b,
    output reg [9:0] data_out,
    input [7:0] accum_in,
    input valid_a,
    input ready_b,
    output ready_a
);

// Detects the occurrence of a specific 2-bit pattern: 01 or 10
reg [1:0] state;
reg [7:0] pattern;
reg [7:0] output_reg;
wire pattern_detected;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= 2'b00;
        pattern <= 8'b0;
        output_reg <= 8'b0;
    end else begin
        case (state)
            2'b00: begin // IDLE state
                if (in[1] != in[0]) begin
                    pattern <= {in[1], in[0]};
                    state <= 2'b01;
                end
            end
            2'b01: begin // WAIT_FOR_SECOND state
                if (in[1] == in[0]) begin
                    pattern <= {in[1], in[0]};
                    state <= 2'b00;
                end else if ({in[1], in[0]} == 2'b01 || {in[1], in[0]} == 2'b10) begin
                    pattern <= {in[1], in[0]};
                    state <= 2'b10;
                end
            end
            2'b10: begin // PATTERN_DETECTED state
                output_reg <= 8'b0;
                output_reg[{in[1], in[0]}] <= 1'b1;
                state <= 2'b00;
            end
        endcase
    end
end

assign anyedge = {in[7] ^ in[6], in[6] ^ in[5], in[5] ^ in[4], in[4] ^ in[3], in[3] ^ in[2], in[2] ^ in[1], in[1] ^ in[0], in[0] ^ in[7]};

assign pattern_detected = (state == 2'b10);

// Pipeline architecture with two stages for accumulator module
reg [7:0] accum_reg_1;
reg [7:0] accum_reg_2;
reg [3:0] count;
wire output_valid;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        accum_reg_1 <= 8'b0;
        accum_reg_2 <= 8'b0;
        count <= 4'b0;
    end else begin
        if (count == 4'b0) begin
            accum_reg_1 <= accum_in;
            count <= 4'b1;
        end else if (count == 4'b1) begin
            accum_reg_2 <= accum_in;
            count <= 4'b0;
        end
    end
end

assign output_valid = (count == 4'b0);

// Final output module
assign data_out = output_reg | {8{output_valid}} & {8{accum_reg_1}} & {8{accum_reg_2}};

// Valid-ready two-way handshake mechanism
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        valid_b <= 1'b0;
        ready_a <= 1'b0;
        data_out <= 10'b0;
    end else begin
        if (valid_a && ready_b) begin
            valid_b <= 1'b1;
            ready_a <= 1'b1;
        end else begin
            valid_b <= 1'b0;
            ready_a <= 1'b1;
        end
    end
end

endmodule

