module fifo_memory_block_generator(
    input clk,
    input srst,
    input we,
    input [7:0] din,
    output rd,
    output [7:0] dout
);

    reg [7:0] memory [0:1023];
    reg [9:0] head = 0;
    reg [9:0] tail = 0;
    reg empty = 1;
    reg full = 0;

    always @(posedge clk or negedge srst) begin
        if (!srst) begin
            head <= 0;
            tail <= 0;
            empty <= 1;
            full <= 0;
        end else begin
            if (we && !full) begin
                memory[tail] <= din;
                tail <= tail + 1;
                if (tail == 1024) begin
                    tail <= 0;
                end
                empty <= 0;
                if (tail == head) begin
                    full <= 1;
                end
            end
            if (rd && !empty) begin
                dout <= memory[head];
                head <= head + 1;
                if (head == 1024) begin
                    head <= 0;
                end
                full <= 0;
                if (head == tail) begin
                    empty <= 1;
                end
            end
            if (empty && rd) begin
                dout <= 8'b0;
            end
        end
    end

    assign rd = (!empty);

endmodule

module sha2_sec_ti2_rm0_masked_full_adder_ti(
    input wire i_clk,
    input wire [3:0] i_a,
    input wire [3:0] i_b,
    input wire [3:0] i_c,
    input wire [3:0] i_rnd,
    output reg [3:0] o_q,
    output reg [3:0] o_c
);

    // XOR i_a and i_b
    wire [3:0] x0 = i_a ^ i_b;

    // AND i_c with x0 using SHA-2 security implementation
    wire [3:0] n0;
    sha2_sec_ti2_rm0_ti2_and u0(.i_clk(i_clk), .i_a(x0), .i_b(i_c), .i_rnd(i_rnd[0+:2]), .o_y(n0));

    // AND i_a and i_b using SHA-2 security implementation with second half of i_rnd
    wire [3:0] n1;
    sha2_sec_ti2_rm0_ti2_and u1(.i_clk(i_clk), .i_a(i_a), .i_b(i_b), .i_rnd(i_rnd[2+:2]), .o_y(n1));

    // Store previous values of x0 and i_c in registers
    reg [3:0] x0_l1;
    always @(posedge i_clk) x0_l1 <= x0;

    reg [3:0] c_l1;
    always @(posedge i_clk) c_l1 <= i_c;

    // Calculate output signals
    always @* begin
        o_q = x0_l1 ^ c_l1;
        o_c = n0 ^ n1; 
    end

endmodule

module SN74LS195Agates(Q, P, Q3not, PE, J, K, CP, MR);
    parameter LENGTH = 4;
    input PE, J, K, CP, MR;
    input [LENGTH-1:0] P;
    output [LENGTH-1:0] Q;
    output Q3not;
    wire w1, w2, w3, w4, w5, w6, w7, w8, w9, w10;
    wire w11, w12, w13, w14, w15, w16, w17, w18, w19, w20, w21;
    wire Ki, PEi, CPi;
    wire Clear;

    // Invert K input
    not N1(Ki, K);
    // Invert PE input
    not N2(PEi, PE);
    // Invert CP input
    not N3(CPi, CP);
    // Buffer MR input
    buf B1(Clear, MR);

    // Generate the logic for each bit of the shift register
    and U1(w1, w18, J, PE);
    and U2(w2, PE, K, Q[0]);
    and U3(w3, PEi, P[0]);
    and U4(w4, Q[0], PE);
    and U5(w5, PEi, P[1]);
    and U6(w6, Q[1], PE);
    and U7(w7, PEi, P[2]);
    and U8(w8, Q[2], PE);
    and U9(w9, PEi, P[3]);

    nor U10(w10, w1, w2, w3);
    nor U11(w11, w4, w5);
    nor U12(w12, w6, w7);
    nor U13(w13, w8, w9);

    not U14(w14, w10);
    not U15(w15, w11);
    not U16(w16, w12);
    not U17(w17, w13);

    not U18(w18, Q[0]);
    not U19(Q3not, Q[3]);

    // Implement the 4 JK flip-flops with clear input
    SRffwithClear RS0(w14, w10, CPi, MR, Q[0]);
    SRffwithClear RS1(w15, w11, CPi, MR, Q[1]);
    SRffwithClear RS2(w16, w12, CPi, MR, Q[2]);
    SRffwithClear RS3(w17, w13, CPi, MR, Q[3]);
endmodule

