module gray_code (
    input [3:0] binary_in,
    output reg [5:0] gray_out
);
    always @ (binary_in) begin
        gray_out[0] = binary_in[0];
        gray_out[1] = binary_in[0] ^ binary_in[1];
        gray_out[2] = binary_in[1] ^ binary_in[2];
        gray_out[3] = binary_in[2] ^ binary_in[3];
        gray_out[4] = binary_in[3];
        gray_out[5] = 1'b0;
    end
endmodule

module alu (
    input [3:0] A,
    input [3:0] B,
    input [5:0] control,
    output reg [3:0] result
);
    always @ (A, B, control) begin
        case (control)
            6'b000001: result = A + B;
            6'b000010: result = A - B;
            6'b000100: result = A & B;
            6'b001000: result = A | B;
            default: result = 4'bxxxx;
        endcase
    end
endmodule

module xor_output (
    input [3:0] alu_result,
    input [5:0] gray_code_out,
    output reg [3:0] final_output
);
    always @ (alu_result, gray_code_out) begin
        final_output = alu_result ^ gray_code_out[5:2];
