    reg [3:0] alu_result;

    gray_code gray_code_inst (.binary_in({A,B}), .gray_out(gray_code_out));
    alu alu_inst (.A(A), .B(B), .control(gray_code_out), .result(alu_result));
    xor_output xor_inst (.alu_result(alu_result), .gray_code_out(gray_code_out), .final_output(result));

    always @(posedge clk) begin
        if (reset) begin
            result <= 4'b0;
