        end
    end
endmodule

module barrel_shifter (
    input [15:0] data_in,
    input [3:0] shift_amount,
    output reg [15:0] data_out
);

    always @(*) begin
        if (shift_amount[3] == 1) begin
            data_out = 16'b0;
        end else if (shift_amount[2] == 1) begin
            data_out = {data_in[15:3], data_in[2:0]};
        end else if (shift_amount[1] == 1) begin
            data_out = {data_in[15:2], data_in[1:0]};
        end else if (shift_amount[0] == 1) begin
            data_out = {data_in[15:1], data_in[0]};
        end else begin
            data_out = data_in;
        end
    end

endmodule

