    input [15:0] data_in,
    input [3:0] shift_amount,
    input [3:0] N,
    input clk,
    input reset,
    output reg [3:0] out
);

    reg [15:0] shifted_data;
    reg [3:0] counter_output;
    wire [3:0] bitwise_and;

    barrel_shifter shifter (.data_in(data_in), .shift_amount(shift_amount), .data_out(shifted_data));
    counter counter_inst (.clk(clk), .reset(reset), .N(N), .count(counter_output));
    functional_module func_module (.data_in(shifted_data), .count(counter_output), .out(bitwise_and));

    always @(posedge clk) begin
        if (reset == 1) begin
            out <= 4'b0;
        end else if (select == 1) begin
            out <= counter_output;
        end else begin
            out <= bitwise_and;
        end
    end

endmodule

