module FpuFpD_Mul(
	/* verilator lint_off UNUSED */
	clk,
	enable,
	srca,
	srcb,
	dst
);

input			clk;
input			enable;
input[63:0]		srca;
input[63:0]		srcb;
output[63:0]	dst;

reg sgna;
reg sgnb;
reg sgnc;

reg[12:0] exa;
reg[12:0] exb;
reg[12:0] exc;

`ifdef PRECISE_FMUL
reg[105:0] tFracA;
reg[105:0] tFracB;
reg[105:0] tFracC1;
reg[63:0] tFracC;
`else
reg[63:0] tFracA;
reg[63:0] tFracB;
reg[63:0] tFracC;
`endif

reg[51:0] tFracC2;

//reg[41:0] tFracAL;
//reg[41:0] tFracBL;
//reg[41:0] tFracCL;
//reg[63:0] tFracCL2;

reg[63:0]	tDst;

assign dst = tDst;

always @ (posedge clk)
begin
	if (enable) begin
		sgna=srca[63];
		sgnb=srcb[63];

		exa[10:0]=srca[62:52];
		exb[10:0]=srcb[62:52];
		exa[12:11]=0;
		exb[12:11]=0;

		sgnc=sgna^sgnb;

`ifdef PRECISE_FMUL
		tFracA[105:52]=1;
		tFracB[105:52]=1;
`else
		tFracA[63:52]=1;
		tFracB[63:52]=1;
`endif
		tFracA[51:0]=srca[51:0];
		tFracB[51:0]=srcb[51:0];

`ifdef PRECISE_FMUL
		tFracC1=tFracA*tFracB;
		tFracC=tFracC1[105:42]+64'h3FF;
`else	
//		tFracC=(tFracA>>21)*(tFracB>>21);
		tFracC=
			{21'h0, tFracA[63:21]} *
			{21'h0, tFracB[63:21]};
`endif

		if(tFracC[63])
		begin
			tFracC2[51:0]=tFracC[62:11];
			exc=exa+exb-1022;
		end
		else
		begin
			tFracC2[51:0]=tFracC[61:10];
			exc=exa+exb-1023;
		end

		if(exc[12])
		begin
			tDst=0;
		end
		else
		if(exc[11])
		begin
			tDst[63]=sgnc;
			tDst[62:0]=63'h7FF0_0000_0000_0000;
		end
		else
		begin
			tDst[63]=sgnc;
			tDst[62:52]=exc[10:0];
			tDst[51: 0]=tFracC2[51:0];
		end
	end
end

endmodule

module carry_lookahead_adder (
    input [7:0] a,
    input [7:0] b,
    output [7:0] s,
    output overflow
);

    wire [7:0] p, g;
    wire [8:0] c;

    assign p = a ^ b;
    assign g = a & b;
    assign c[0] = 0;
    assign c[1] = g[0] | (p[0] & c[0]);
    assign c[2] = g[1] | (p[1] & c[1]);
    assign c[3] = g[2] | (p[2] & c[2]);
    assign c[4] = g[3] | (p[3] & c[3]);
    assign c[5] = g[4] | (p[4] & c[4]);
    assign c[6] = g[5] | (p[5] & c[5]);
    assign c[7] = g[6] | (p[6] & c[6]);
    assign c[8] = g[7] | (p[7] & c[7]);

    assign s = p ^ c[7:0];
    assign overflow = (a[7] == b[7]) && (a[7] != s[7]);

endmodule

