    input [31:0] input_array [0:255],
    input [7:0] array_size,
    output reg found,
    output reg [7:0] index
);

    // Declare internal signals
    reg [7:0] low, high, mid;
    reg [31:0] mid_val;
    reg [7:0] i;

    // Initialize variables
    assign found = 0;
    assign index = -1;
    assign mid_val = 0;
    assign i = 0;
    assign low = 0;
    assign high = array_size - 1;

    // Binary search algorithm
    always @(posedge clk) begin
        if (rst) begin
            low <= 0;
            high <= array_size - 1;
            i <= 0;
            index <= -1;
            found <= 0;
        end
        else begin
            if (low > high) begin
                found <= 0;
                index <= -1;
            end
            else begin
                mid <= (low + high) / 2;
                mid_val <= input_array[mid];

                if (mid_val == search_val) begin
                    found <= 1;
                    index <= mid;
                    high <= mid - 1;
                end
                else if (mid_val > search_val) begin
                    high <= mid - 1;
                end
                else begin
                    low <= mid + 1;
                end
            end
        end
    end

endmodule

module reset_module(
  input clk, 
  input reset, 
  input ext_reset_in, 
  input aux_reset_in, 
  input debug_sys_rst, 
  input dcm_locked, 
  output reg mb_reset_out, 
  output reg [0:0] bus_struct_reset_out, 
  output reg [0:0] peripheral_reset_out, 
  output reg [0:0] interconnect_aresetn_out, 
  output reg [0:0] peripheral_aresetn_out
);

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      mb_reset_out <= 1'b1;
      bus_struct_reset_out <= 1'b1;
      peripheral_reset_out <= 1'b1;
      interconnect_aresetn_out <= 1'b1;
      peripheral_aresetn_out <= 1'b1;
    end else begin
      mb_reset_out <= (ext_reset_in | aux_reset_in | debug_sys_rst | dcm_locked);
      bus_struct_reset_out <= bus_struct_reset;
      peripheral_reset_out <= peripheral_reset;
      interconnect_aresetn_out <= interconnect_aresetn;
      peripheral_aresetn_out <= peripheral_aresetn;
    end
  end

endmodule

module stream_separator
  #(
    parameter WDTH = 32,
    parameter ERRORCODE = 32'hDEADBEEF,
    parameter COMBINER_BUFFER_LENGTH = 4,
    parameter LOG_COMBINER_BUFFER_LENGTH = 2,
    parameter MAX_PACKET_LENGTH = 256,
    parameter MSG_LENGTH_WIDTH = 8
    )
   (
    input wire            clk,
    input wire            reset,
    input wire [WDTH-1:0] in_data,
    input wire            in_nd,
    output reg [WDTH-1:0] out_data,
    output reg            out_nd
    );

   // Separate the input stream into a sample stream and a message stream.

   wire [WDTH-1:0]         mid1_data;
   wire [WDTH-1:0]         mid2_data;
   wire [WDTH-1:0]         staged_data;
   wire                    staged_nd;
   wire                    mid_nd;
   wire                    combiner_error;

   wire                    rst_n;
   assign rst_n = ~reset;

   split #(2, 1) split_0
     (.clk(clk),
      .rst_n(rst_n),
      .in_data(in_data),
      .in_nd(in_nd),
      .out_data({mid1_data, mid2_data}),
      .out_nd(mid_nd)
      );

   message_stream_combiner
     #(2, 1, WDTH, COMBINER_BUFFER_LENGTH, LOG_COMBINER_BUFFER_LENGTH,
       MAX_PACKET_LENGTH, MSG_LENGTH_WIDTH)
   message_stream_combiner_0
     (.clk(clk),
      .rst_n(rst_n),
      .in_data({mid1_data, mid2_data}),
      .in_nd({mid_nd, mid_nd}),
      .out_data(staged_data),
      .out_nd(staged_nd),
      .error(combiner_error)
      );

   always @ (posedge clk)
     begin
        if (combiner_error)
          begin
             out_nd <= 1'b1;
             out_data <= ERRORCODE;
          end
        else
          begin
             out_nd <= staged_nd;
             out_data <= staged_data;
          end
     end

endmodule

