  wire [152 : 0] pktFork_iport_put, pktFork_oport0_get, pktFork_oport1_get;
  wire pktFork_EN_iport_put, pktFork_EN_oport0_get, pktFork_EN_oport1_get, pktFork_RDY_iport_put, pktFork_RDY_oport0_get, pktFork_RDY_oport1_get;

