  reg [1 : 0] CASE_pfk_BITS_13_TO_12_0_pfk_BITS_13_TO_12_1_p_ETC__q1;
  wire [13 : 0] x__h110;

  assign RDY_p_put = pktFork_RDY_iport_put;
  assign RDY_s_request_put = pktMerge_RDY_iport0_put;
  assign RDY_s_response_get = pktFork_RDY_oport0_get;
