  assign pktMerge_EN_iport1_put = pktMerge_RDY_iport1_put && pktFork_RDY_oport1_get;
  assign pktMerge_EN_oport_get = 1'b1;

  assign x__h110 = { CASE_pfk_BITS_13_TO_12_0_pfk_BITS_13_TO_12_1_p_ETC__q1, p_put[11:0] };

  always@(p_put) begin
