module mux4to1 (
    Y   ,
    A   ,
    B   ,
    C   ,
    D   ,
    S0  ,
    S1  ,
    VPWR,
    VGND,
    VPB ,
    VNB 
);

    output Y   ;
    input  A   ;
    input  B   ;
    input  C   ;
    input  D   ;
    input  S0  ;
    input  S1  ;
    input  VPWR;
    input  VGND;
    input  VPB ;
    input  VNB ;

    wire sel0;
    wire sel1;

    assign sel0 = ~S0 & ~S1;
    assign sel1 = ~S0 & S1;
    assign sel2 = S0 & ~S1;
    assign sel3 = S0 & S1;

    sky130_fd_sc_hd__nand3 nand1 (.Y(sel0), .A(S0), .B(S1), .C(VGND), .VPWR(VPWR), .VGND(VGND), .VPB(VPB), .VNB(VNB));
    sky130_fd_sc_hd__nand3 nand2 (.Y(sel1), .A(S0), .B(~S1), .C(VGND), .VPWR(VPWR), .VGND(VGND), .VPB(VPB), .VNB(VNB));
    sky130_fd_sc_hd__nand3 nand3 (.Y(sel2), .A(~S0), .B(S1), .C(VGND), .VPWR(VPWR), .VGND(VGND), .VPB(VPB), .VNB(VNB));
    sky130_fd_sc_hd__nand3 nand4 (.Y(sel3), .A(S0), .B(S1), .C(VGND), .VPWR(VPWR), .VGND(VGND), .VPB(VPB), .VNB(VNB));

    assign Y = (sel0 & A) | (sel1 & B) | (sel2 & C) | (sel3 & D);

