module carry_select_adder(
    input [99:0] a, b,
    input cin,
    output cout,
    output [99:0] sum);

    wire [99:0] p, g, c;
    wire [99:0] s0, s1;
    wire c0, c1;

    ripple_carry_adder rca0(.a(a), .b(b), .cin(cin), .c(c0), .s(s0));
    ripple_carry_adder rca1(.a(a), .b(b), .cin(~cin), .c(c1), .s(s1));

    generate
        for (i = 0; i < 100; i = i + 1) begin : gen
            assign p[i] = s0[i] ^ s1[i];
            assign g[i] = s0[i] & s1[i];
            assign c[i] = c0 & c1;
            assign sum[i] = p[i] ^ c[i];
        end
    endgenerate

    assign cout = c[99];

endmodule

module decoder_with_register (
  input clk,
  input reset,
  input [1:0] select,
  input [15:0] data_in,
  output [3:0] decoder_out,
  output reg [15:0] data_out
);

  // 2-to-4 decoder implemented using NAND gates
  wire nand1_out, nand2_out, nand3_out, nand4_out;
  assign nand1_out = ~(select[0] & select[1]);
  assign nand2_out = ~(select[0] & ~select[1]);
  assign nand3_out = ~(~select[0] & select[1]);
  assign nand4_out = ~(~select[0] & ~select[1]);
  assign decoder_out = {nand1_out, nand2_out, nand3_out, nand4_out};

  // 16-bit register with synchronous active-high reset
  always @(posedge clk, posedge reset) begin
    if (reset) begin
      data_out <= 16'h0000;
    end else if (select == 2'b01) begin
      data_out <= data_in;
    end
  end

  // Control logic to select between decoder and register
  always @(*) begin
    if (select == 2'b00) begin
      data_out = {4'b0000, decoder_out};
    end
  end

endmodule

module pixel_writer(
  input clk_i,
  input rst_i,
  input write_i,
  input discard_pixel,
  input zbuffer_enable_i,
  input z_ack_i,
  input fail_z_check,
  output reg write_o,
  output reg ack_o
);

  // State machine states
  parameter wait_state = 2'b00;
  parameter z_read_state = 2'b01;
  parameter write_pixel_state = 2'b10;

  // State machine
  reg [1:0] state;

  always @(posedge clk_i or posedge rst_i)
    // reset, init component
    if(rst_i)
      state <= wait_state;
    // Move in statemachine
    else
      case (state)

        wait_state:
          if(write_i && !discard_pixel)
          begin
            if(zbuffer_enable_i)
              state <= z_read_state;
            else 
              state <= write_pixel_state;
          end

        z_read_state:
          if(z_ack_i)
            state <= fail_z_check ? wait_state : write_pixel_state;

        write_pixel_state:
          if(ack_i)
            state <= wait_state;

      endcase

  // Write and ack signals
  always @(state)
    case (state)

      wait_state:
        begin
          write_o <= 1'b0;
          ack_o <= 1'b0;
        end

      z_read_state:
        begin
          write_o <= 1'b0;
          ack_o <= 1'b0;
        end

      write_pixel_state:
        begin
          write_o <= 1'b1;
          ack_o <= 1'b0;
        end

    endcase

  // Acknowledge signal
  always @(posedge clk_i)
    if(state == write_pixel_state)
      ack_o <= 1'b1;

endmodule

module PLL (
  input ref_clk,
  input ctrl,
  output synth_clk
);

parameter f_ref = 50_000_000; // frequency of the reference clock signal
parameter f_synth = 100_000_000; // desired frequency of the synthesized clock signal
parameter f_vco = 1_000_000_000; // frequency of the voltage-controlled oscillator
parameter N = 10; // programmable divider value for the feedback path
parameter M = 5; // programmable divider value for the reference path

reg [31:0] phase_accumulator = 0;
reg [31:0] feedback_divider = 0;
reg [31:0] reference_divider = 0;

wire [31:0] feedback_signal;
wire [31:0] reference_signal;

wire [31:0] phase_difference;
wire [31:0] filtered_difference;

wire [31:0] vco_output;

assign feedback_signal = vco_output >> N;
assign reference_signal = ref_clk >> M;

assign phase_difference = feedback_signal - reference_signal;

// Phase detector
always @(posedge ref_clk or posedge synth_clk) begin
  if (synth_clk) begin
    phase_accumulator <= phase_accumulator + phase_difference;
  end
end

// Loop filter
always @(posedge ref_clk) begin
  if (ctrl) begin
    filtered_difference <= (filtered_difference + phase_accumulator) >> 1;
  end
end

// VCO frequency divider
always @(posedge ref_clk) begin
  feedback_divider <= feedback_divider + 1;
  if (feedback_divider == N) begin
    feedback_divider <= 0;
  end
end

// Reference frequency divider
always @(posedge ref_clk) begin
  reference_divider <= reference_divider + 1;
  if (reference_divider == M) begin
    reference_divider <= 0;
  end
end

// VCO
always @(posedge ref_clk) begin
  if (ctrl) begin
    vco_output <= vco_output + filtered_difference;
  end
end

// Synthesized clock output
assign synth_clk = vco_output >> N;

endmodule

