localparam S0 = 3'b000;
localparam S1 = 3'b001;
localparam S2 = 3'b010;
localparam S3 = 3'b011;
localparam S4 = 3'b100;
localparam S5 = 3'b101;
localparam S6 = 3'b110;
localparam S7 = 3'b111;

always @(posedge clock) begin
  if (reset) begin
    state <= S0; // initial state
    out_reg <= 0; // reset output
  end else begin
    case (state)
      S0: begin
        if (in[0]) state <= S1;
        else if (in[1]) state <= S2;
        else if (in[2]) state <= S3;
        else if (in[3]) state <= S4;
      end
      S1: begin
        if (in[0]) state <= S1;
        else if (in[1]) state <= S2;
        else if (in[2]) state <= S3;
        else if (in[3]) state <= S5;
      end
      S2: begin
        if (in[0]) state <= S1;
        else if (in[1]) state <= S2;
        else if (in[2]) state <= S6;
        else if (in[3]) state <= S4;
      end
      S3: begin
        if (in[0]) state <= S1;
        else if (in[1]) state <= S7;
        else if (in[2]) state <= S3;
        else if (in[3]) state <= S4;
      end
      S4: begin
        if (in[0]) state <= S1;
        else if (in[1]) state <= S2;
        else if (in[2]) state <= S3;
        else if (in[3]) state <= S4;
      end
      S5: begin
        if (in[0]) state <= S1;
        else if (in[1]) state <= S2;
        else if (in[2]) state <= S3;
        else if (in[3]) state <= S6;
      end
      S6: begin
        if (in[0]) state <= S1;
        else if (in[1]) state <= S2;
        else if (in[2]) state <= S7;
        else if (in[3]) state <= S4;
      end
      S7: begin
        if (in[0]) state <= S1;
        else if (in[1]) state <= S7;
        else if (in[2]) state <= S3;
        else if (in[3]) state <= S4;
      end
    endcase
  end
end

// Output generation
always @(state) begin
  case (state)
    S0: out_reg <= 2'b00;
    S1: out_reg <= 2'b01;
    S2: out_reg <= 2'b10;
    S3: out_reg <= 2'b11;
    S4: out_reg <= 2'b00;
    S5: out_reg <= 2'b01;
    S6: out_reg <= 2'b10;
    S7: out_reg <= 2'b11;
  endcase
end

assign out = out_reg;

endmodule

