module AXI_Master
(
    input axi_clk,
    input axi_rst,
    input [31:0] axi_araddr,
    input axi_arvalid,
    output axi_arready,
    output [31:0] axi_rdata,
    output axi_rvalid,
    input axi_rready,
    input [31:0] axi_awaddr,
    input axi_awvalid,
    output axi_awready,
    input [31:0] axi_wdata,
    input axi_wvalid,
    output axi_wready,
    output [1:0] axi_bresp,
    output axi_bvalid,
    input axi_bready
);

// Internal registers
reg [31:0] addr_reg;
reg [31:0] data_reg;
reg [1:0] resp_reg;
reg [1:0] state_reg;

// Constants
localparam IDLE = 2'b00;
localparam READ = 2'b01;
localparam WRITE = 2'b10;

// Assign default values to output signals
assign axi_arready = 1'b0;
assign axi_rdata = 32'h00000000;
assign axi_rvalid = 1'b0;
assign axi_awready = 1'b0;
assign axi_wready = 1'b0;
assign axi_bresp = 2'b00;
assign axi_bvalid = 1'b0;

// State machine
always @(posedge axi_clk) begin
    if (axi_rst) begin
        state_reg <= IDLE;
        addr_reg <= 32'h00000000;
        data_reg <= 32'h00000000;
        resp_reg <= 2'b00;
    end else begin
        case (state_reg)
            IDLE: begin
                if (axi_arvalid && axi_rready) begin
                    state_reg <= READ;
                    addr_reg <= axi_araddr;
                end else if (axi_awvalid && axi_wready) begin
                    state_reg <= WRITE;
                    addr_reg <= axi_awaddr;
                    data_reg <= axi_wdata;
                end
            end
            READ: begin
                if (axi_rvalid && axi_rready) begin
                    state_reg <= IDLE;
                    resp_reg <= 2'b00;
                end
            end
            WRITE: begin
                if (axi_bvalid && axi_bready) begin
                    state_reg <= IDLE;
                    resp_reg <= axi_bresp;
                end
            end
        endcase
    end
end

// Output logic
always @(posedge axi_clk) begin
    case (state_reg)
        IDLE: begin
            axi_arready <= 1'b1;
            axi_awready <= 1'b1;
            axi_wready <= 1'b1;
            axi_bvalid <= 1'b0;
        end
        READ: begin
            axi_arready <= 1'b0;
            axi_awready <= 1'b0;
            axi_wready <= 1'b0;
            axi_bvalid <= 1'b0;
            axi_rdata <= mem[addr_reg];
            axi_rvalid <= 1'b1;
        end
        WRITE: begin
            axi_arready <= 1'b0;
            axi_awready <= 1'b0;
            axi_wready <= 1'b1;
            axi_bvalid <= 1'b1;
            axi_bresp <= resp_reg;
            mem[addr_reg] <= data_reg;
        end
    endcase
end

// Memory
reg [31:0] mem [0:1023];

endmodule

module rising_edge_counter (
    input clk,
    input reset,
    input start,
    input stop,
    output reg [31:0] count
);

    reg [31:0] count_reg;
    reg prev_clk;

    always @(posedge clk) begin
        if (reset) begin
            count_reg <= 0;
            prev_clk <= 1'b0;
        end else begin
            if (start) begin
                count_reg <= 0;
                prev_clk <= 1'b0;
            end else if (stop) begin
                count <= count_reg;
            end else begin
                if (clk && !prev_clk) begin
                    count_reg <= count_reg + 1;
                end
                prev_clk <= clk;
            end
        end
    end

endmodule

