module lfsr_and (
    input clk,
    input reset,      // Synchronous active-high reset
    output [7:0] rand_val
);

    reg [2:0] lfsr;    // 3-bit LFSR
    reg [3:0] counter; // 4-bit counter

    always @(posedge clk) begin
        if (reset) begin
            lfsr <= 3'b101; // Initialize LFSR with seed value of 0x5
            counter <= 4'b0; // Initialize counter to 0
        end else begin
            // Update LFSR
            lfsr <= {lfsr[1:0], lfsr[2]^lfsr[1]^1};

            // Update counter
            if (counter == 4'b1111) begin
                counter <= 4'b0;
            end else begin
                counter <= counter + 1;
            end
        end
    end

    assign rand_val = lfsr & counter; // Bitwise AND of LFSR and counter

endmodule

