reg [31:0] address_out;
reg [3:0] byte_sel_out;

assign cyc_o = 1'b0;
assign stb_o = 1'b0;
assign cti_o = 3'b000;
assign bte_o = 2'b00;
assign we_o = 1'b0;
assign adr_o = 32'h00000000;
assign sel_o = 4'b0000;
assign sint_o = 1'b0;
assign texture_dat_o = 32'h00000000;
assign texture_data_ack = 1'b0;

always @(posedge clk_i) begin
    if (rst_i) begin
        cyc_o <= 1'b0;
