        address_out <= 32'h00000000;
        byte_sel_out <= 4'b0000;
        texture_dat_o <= 32'h00000000;
        texture_data_ack <= 1'b0;
    end else begin
        if (read_request_i) begin
            cyc_o <= 1'b1;
            stb_o <= 1'b1;
            cti_o <= 3'b000;
            bte_o <= 2'b00;
            we_o <= 1'b0;
