always @(posedge clk) begin
    if (rst) begin
        count_reg1 <= 4'b0;
        count_reg2 <= 4'b0;
    end
    else begin
        count_reg1 <= en ? (up ? count_reg2 + 4'b1 : count_reg2 - 4'b1) : count_reg2;
        count_reg2 <= count_reg1;
    end
end

