module binary_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

    wire [3:0] carry; // carry bits
    wire [3:0] sum;   // sum bits

    // first full adder
    full_adder FA0(
        .A(A[0]),
        .B(B[0]),
        .Cin(Cin),
        .S(sum[0]),
        .Cout(carry[0])
    );

    // second full adder
    full_adder FA1(
        .A(A[1]),
        .B(B[1]),
        .Cin(carry[0]),
        .S(sum[1]),
        .Cout(carry[1])
    );

    // third full adder
    full_adder FA2(
        .A(A[2]),
        .B(B[2]),
        .Cin(carry[1]),
        .S(sum[2]),
        .Cout(carry[2])
    );

    // fourth full adder
    full_adder FA3(
        .A(A[3]),
        .B(B[3]),
        .Cin(carry[2]),
        .S(sum[3]),
        .Cout(Cout)
    );

    assign S = sum;

endmodule

// full adder module
module full_adder (
    input A,
    input B,
    input Cin,
    output S,
    output Cout
);

    assign S = A ^ B ^ Cin;
    assign Cout = (A & B) | (A & Cin) | (B & Cin);

endmodule

