module PLL (
  input ref_clk,
  input in_clk,
  input reset,
  output out_clk
);

parameter n = 8; // number of bits used to represent the frequency divider ratio
parameter m = 6; // number of bits used to represent the phase detector output

// Define input and output signals for the frequency divider, phase detector, charge pump, loop filter, and VCO modules here.

wire [n-1:0] divider_out;
wire [m-1:0] phase_detector_out;
wire [m-1:0] charge_pump_out;
wire [m-1:0] loop_filter_out;
wire vco_out;

// Instantiate frequency divider module
frequency_divider #(.n(n)) divider(
  .clk(in_clk),
  .reset(reset),
  .out(divider_out)
);

// Instantiate phase detector module
phase_detector #(.m(m)) detector(
  .ref_clk(ref_clk),
  .in_clk(divider_out),
  .out(phase_detector_out)
);

// Instantiate charge pump module
charge_pump #(.m(m)) pump(
  .in(phase_detector_out),
  .out(charge_pump_out)
);

// Instantiate loop filter module
loop_filter #(.m(m)) filter(
  .in(charge_pump_out),
  .out(loop_filter_out)
);

// Instantiate VCO module
vco #(.m(m)) oscillator(
  .in(loop_filter_out),
  .out(vco_out)
);

// Assign output of VCO to out_clk
assign out_clk = vco_out;

endmodule

// Define frequency divider module here
module frequency_divider #(
  parameter n = 8
)(
  input clk,
  input reset,
  output reg [n-1:0] out
);

reg [n-1:0] counter;

always @(posedge clk or negedge reset) begin
  if (reset == 0) begin
    counter <= 0;
    out <= 0;
  end else begin
    counter <= counter + 1;
    if (counter == (1 << n) - 1) begin
      counter <= 0;
      out <= ~out;
    end
  end
end

endmodule

// Define phase detector module here
module phase_detector #(
  parameter m = 6
)(
  input ref_clk,
  input in_clk,
  output reg [m-1:0] out
);

reg [m-1:0] counter;

always @(posedge ref_clk or posedge in_clk) begin
  if (ref_clk == 1'b1 && in_clk == 1'b0) begin
    counter <= counter + 1;
  end else if (ref_clk == 1'b0 && in_clk == 1'b1) begin
    counter <= counter - 1;
  end
end

always @(posedge ref_clk) begin
  out <= counter;
end

endmodule

// Define charge pump module here
module charge_pump #(
  parameter m = 6
)(
  input [m-1:0] in,
  output reg [m-1:0] out
);

always @(in) begin
  if (in > 0) begin
    out <= out + 1;
  end else if (in < 0) begin
    out <= out - 1;
  end
end

endmodule

// Define loop filter module here
module loop_filter #(
  parameter m = 6
)(
  input [m-1:0] in,
  output reg [m-1:0] out
);

reg [m-1:0] integrator;

always @(posedge in_clk) begin
  integrator <= integrator + in;
end

always @(posedge in_clk) begin
  out <= integrator >> 2; // divide by 4
end

endmodule

// Define VCO module here
module vco #(
  parameter m = 6
)(
  input [m-1:0] in,
  output reg out
);

reg [m-1:0] counter;

always @(posedge in_clk) begin
  counter <= counter + in;
  out <= counter[m-1];
end

endmodule

module memory#(
    parameter MEM_ADDR_WIDTH = 8                 // Default: 256 words/1 KB
    )(
    input                       clk,
    input                       rst,
    //port A
    input       [MEM_ADDR_WIDTH-1:0] a_addr,     // Address
    input       [31:0]          a_din,      // Data input
    input       [3:0]           a_wr,       // Write/Read
    input                       a_enable,   // Valid operation
    output  reg [31:0]          a_dout,     // Data output
    output  reg                 a_ready,    // Data output ready (valid)
    // port B
    input       [MEM_ADDR_WIDTH-1:0] b_addr,     // Address
    input       [31:0]          b_din,      // Data input
    input       [3:0]           b_wr,       // Write/Read
    input                       b_enable,   // Valid operation
    output  reg [31:0]          b_dout,     // Data output
    output  reg                 b_ready     // Data output ready (valid)
    );

    //--------------------------------------------------------------------------
    // Signal Declaration: reg
    //--------------------------------------------------------------------------
    reg     [31:0]  a_data_out;
    reg     [31:0]  b_data_out;

    //--------------------------------------------------------------------------
    // Set the ready signal
    //--------------------------------------------------------------------------
    always @(posedge clk) begin
        a_ready <= (rst) ? 1'b0 : a_enable;
        b_ready <= (rst) ? 1'b0 : b_enable;
    end

    //--------------------------------------------------------------------------
    // assigment
    //--------------------------------------------------------------------------
    always @(*) begin
        a_dout = (a_ready) ? a_data_out : 32'bz;
        b_dout = (b_ready) ? b_data_out : 32'bz;
    end

    //--------------------------------------------------------------------------
    // inicializar memoria
    //--------------------------------------------------------------------------
    reg [31:0] mem [0:(2**MEM_ADDR_WIDTH)-1];
    initial begin
        $readmemh("mem.hex", mem);
    end

    //--------------------------------------------------------------------------
    // Port A
    //--------------------------------------------------------------------------
    always @(posedge clk) begin
        a_data_out <= mem[a_addr];
        if(a_wr != 4'b0) begin
            a_data_out         <= a_din;
            mem[a_addr][7:0]   <= (a_wr[0] & a_enable) ? a_din[7:0]   : mem[a_addr][7:0];
            mem[a_addr][15:8]  <= (a_wr[1] & a_enable) ? a_din[15:8]  : mem[a_addr][15:8];
            mem[a_addr][23:16] <= (a_wr[2] & a_enable) ? a_din[23:16] : mem[a_addr][23:16];
            mem[a_addr][31:24] <= (a_wr[3] & a_enable) ? a_din[31:24] : mem[a_addr][31:24];
        end
    end

    //--------------------------------------------------------------------------
    // Port B
    //--------------------------------------------------------------------------
    always @(posedge clk) begin
        b_data_out <= mem[b_addr];
        if(b_wr != 4'b0) begin
            b_data_out         <= b_din;
            mem[b_addr][7:0]   <= (b_wr[0] & b_enable) ? b_din[7:0]   : mem[b_addr][7:0];
            mem[b_addr][15:8]  <= (b_wr[1] & b_enable) ? b_din[15:8]  : mem[b_addr][15:8];
            mem[b_addr][23:16] <= (b_wr[2] & b_enable) ? b_din[23:16] : mem[b_addr][23:16];
            mem[b_addr][31:24] <= (b_wr[3] & b_enable) ? b_din[31:24] : mem[b_addr][31:24];
        end
    end
 endmodule

module ic_download(
  input clk,
  input rst,
  input [15:0] rep_flit_ic,
  input v_rep_flit_ic,
  input [1:0] rep_ctrl_ic,
  input [127:0] mem_flits_ic,
  input v_mem_flits_ic,
  output reg [1:0] ic_download_state,
  output reg [127:0] inst_word_ic,
  output reg v_inst_word
);

  reg [127:0] inst_word;
  reg [1:0] ic_download_nstate;
  reg [1:0] ic_download_cstate;
  parameter ic_download_idle = 2'b00;
  parameter ic_download_busy = 2'b01;
  parameter ic_download_rdy = 2'b10;
  assign ic_download_state = ic_download_cstate;
  assign inst_word_ic = inst_word;

  reg v_inst_word;
  reg en_mem_flits_ic;
  reg en_rep_flit_ic;
  reg inc_cnt;
  reg fsm_rst;
  reg [127:0] inst_word_in;

  always @(*) begin
    ic_download_nstate = ic_download_cstate;
    v_inst_word = 1'b0;
    en_mem_flits_ic = 1'b0;
    en_rep_flit_ic = 1'b0;
    inc_cnt = 1'b0;
    fsm_rst = 1'b0;
    inst_word_in = 128'h0000;
    case(ic_download_cstate)
      ic_download_idle:
        begin
          if (v_mem_flits_ic) begin
            ic_download_nstate = ic_download_rdy;
            inst_word_in = mem_flits_ic;
            en_mem_flits_ic = 1'b1;
          end else if (v_rep_flit_ic) begin
            ic_download_nstate = ic_download_busy;
            en_rep_flit_ic = 1'b1;
          end
        end
      ic_download_busy:
        begin
          if (rep_ctrl_ic == 2'b11) begin
            en_rep_flit_ic = 1'b1;
            ic_download_nstate = ic_download_rdy;
          end else if (rep_ctrl_ic == 2'b10) begin
            en_rep_flit_ic = 1'b1;
            inc_cnt = 1'b1;
          end
        end
      ic_download_rdy:
        begin
          v_inst_word = 1'b1;
          ic_download_nstate = ic_download_idle;
          fsm_rst = 1'b1;
        end
    endcase
  end

  reg [2:0] cnt;
  reg [7:0] en_instword;

  always @(*) begin
    case(cnt)
      3'b000: en_instword = 8'b00000001;
      3'b001: en_instword = 8'b00000010;
      3'b010: en_instword = 8'b00000100;
      3'b011: en_instword = 8'b00001000;
      3'b100: en_instword = 8'b00010000;
      3'b101: en_instword = 8'b00100001;
      3'b110: en_instword = 8'b01000001;
      3'b111: en_instword = 8'b10000001;
      default: en_instword = 8'b00000000;
    endcase
  end

  always @(posedge clk) begin
    if (rst || fsm_rst) begin
      inst_word[15:0] <= 16'h0000;
    end else if (en_mem_flits_ic) begin
      inst_word[15:0] <= inst_word_in[15:0];
    end else if (en_rep_flit_ic && en_instword[0]) begin
      inst_word[15:0] <= inst_word_in[15:0];
    end
  end

  always @(posedge clk) begin
    if (rst || fsm_rst) begin
      inst_word[31:16] <= 16'h0000;
    end else if (en_mem_flits_ic) begin
      inst_word[31:16] <= inst_word_in[31:16];
    end else if (en_rep_flit_ic && en_instword[1]) begin
      inst_word[31:16] <= inst_word_in[31:16];
    end
  end

  always @(posedge clk) begin
    if (rst || fsm_rst) begin
      inst_word[47:32] <= 16'h0000;
    end else if (en_mem_flits_ic) begin
      inst_word[47:32] <= inst_word_in[47:32];
    end else if (en_rep_flit_ic && en_instword[2]) begin
      inst_word[47:32] <= inst_word_in[47:32];
    end
  end

  always @(posedge clk) begin
    if (rst || fsm_rst) begin
      inst_word[63:48] <= 16'h0000;
    end else if (en_mem_flits_ic) begin
      inst_word[63:48] <= inst_word_in[63:48];
    end else if (en_rep_flit_ic && en_instword[3]) begin
      inst_word[63:48] <= inst_word_in[63:48];
    end
  end

  always @(posedge clk) begin
    if (rst || fsm_rst) begin
      inst_word[79:64] <= 16'h0000;
    end else if (en_mem_flits_ic) begin
      inst_word[79:64] <= inst_word_in[79:64];
    end else if (en_rep_flit_ic && en_instword[4]) begin
      inst_word[79:64] <= inst_word_in[79:64];
    end
  end

  always @(posedge clk) begin
    if (rst || fsm_rst) begin
      inst_word[95:80] <= 16'h0000;
    end else if (en_mem_flits_ic) begin
      inst_word[95:80] <= inst_word_in[95:80];
    end else if (en_rep_flit_ic && en_instword[5]) begin
      inst_word[95:80] <= inst_word_in[95:80];
    end
  end

  always @(posedge clk) begin
    if (rst || fsm_rst) begin
      inst_word[111:96] <= 16'h0000;
    end else if (en_mem_flits_ic) begin
      inst_word[111:96] <= inst_word_in[111:96];
    end else if (en_rep_flit_ic && en_instword[6]) begin
      inst_word[111:96] <= inst_word_in[111:96];
    end
  end

  always @(posedge clk) begin
    if (rst || fsm_rst) begin
      inst_word[127:112] <= 16'h0000;
    end else if (en_mem_flits_ic) begin
      inst_word[127:112] <= inst_word_in[127:112];
    end else if (en_rep_flit_ic && en_instword[7]) begin
      inst_word[127:112] <= inst_word_in[127:112];
    end
  end

  always @(posedge clk) begin
    if (rst) begin
      ic_download_cstate <= 2'b00;
    end else begin
      ic_download_cstate <= ic_download_nstate;
    end
  end

  always @(posedge clk) begin
    if (rst || fsm_rst) begin
      cnt <= 3'b000;
    end else if (inc_cnt) begin
      cnt <= cnt + 3'b001;
    end
  end

endmodule

