module video_scaler (
    // Inputs
    clk,
    reset,
    stream_in_data,
    stream_in_startofpacket,
    stream_in_endofpacket,
    stream_in_empty,
    stream_in_valid,
    // Outputs
    stream_out_data,
    stream_out_startofpacket,
    stream_out_endofpacket,
    stream_out_empty,
    stream_out_valid
);

parameter DW = 15; // Data width
parameter EW = 0; // Empty width
parameter WIDTH_IN = 640;
parameter HEIGHT_IN = 480;
parameter WIDTH_OUT = WIDTH_IN / 2;
parameter HEIGHT_OUT = HEIGHT_IN / 2;

reg [DW:0] buffer [0:HEIGHT_IN-1][0:WIDTH_IN-1];
reg [DW:0] out_buffer [0:HEIGHT_OUT-1][0:WIDTH_OUT-1];
reg [DW:0] out_data;
reg out_valid;
reg out_startofpacket;
reg out_endofpacket;
reg out_empty;
reg in_ready;
reg out_ready;

integer row, col;
integer out_row, out_col;

always @(posedge clk) begin
    if (reset) begin
        // Reset all signals and buffers
        out_data <= 0;
        out_valid <= 0;
        out_startofpacket <= 0;
        out_endofpacket <= 0;
        out_empty <= 1;
        in_ready <= 1;
        out_ready <= 0;
        for (row = 0; row < HEIGHT_IN; row = row + 1) begin
            for (col = 0; col < WIDTH_IN; col = col + 1) begin
                buffer[row][col] <= 0;
            end
        end
        for (out_row = 0; out_row < HEIGHT_OUT; out_row = out_row + 1) begin
            for (out_col = 0; out_col < WIDTH_OUT; out_col = out_col + 1) begin
                out_buffer[out_row][out_col] <= 0;
            end
        end
    end else begin
        // Shift in new data
        if (stream_in_valid && in_ready) begin
            buffer[HEIGHT_IN-1][WIDTH_IN-1] <= stream_in_data;
            in_ready <= 0;
        end else if (stream_in_valid && !in_ready) begin
            in_ready <= 1;
        end

        // Shift out old data and scale down
        for (row = 0; row < HEIGHT_IN-1; row = row + 1) begin
            for (col = 0; col < WIDTH_IN-1; col = col + 1) begin
                buffer[row][col] <= buffer[row+1][col+1];
            end
        end
        for (out_row = 0; out_row < HEIGHT_OUT; out_row = out_row + 1) begin
            for (out_col = 0; out_col < WIDTH_OUT; out_col = out_col + 1) begin
                out_buffer[out_row][out_col] <= buffer[out_row*2][out_col*2];
            end
        end

        // Output scaled down data
        if (out_ready && !out_valid) begin
            out_data <= out_buffer[0][0];
            out_valid <= 1;
            out_startofpacket <= stream_in_startofpacket;
            out_endofpacket <= stream_in_endofpacket;
            out_empty <= stream_in_empty;
        end else if (out_valid && stream_out_ready) begin
            out_data <= out_buffer[0][0];
            out_startofpacket <= 0;
            out_endofpacket <= 0;
            out_empty <= 1;
            out_valid <= 0;
            out_ready <= 0;
        end else if (out_valid && !stream_out_ready) begin
            out_ready <= 1;
        end
    end
end

assign stream_out_data = out_data;
assign stream_out_startofpacket = out_startofpacket;
assign stream_out_endofpacket = out_endofpacket;
assign stream_out_empty = out_empty;
assign stream_out_valid = out_valid;
