module device_manager(
    input clk,
    input rst_n,
    input dma_req,
    input dma_rnw,
    output dma_ack,
    output dma_end,
    input [20:0] dma_addr,
    input [7:0] dma_wd,
    output [7:0] dma_rd,
    input [3:0] req,
    input [3:0] rnw,
    output [3:0] done,
    output [3:0] ack,
    inout [20:0] addr,
    inout [7:0] wd,
    output reg [7:0] rd
);

reg [3:0] device_sel;
reg [3:0] device_sel_next;
reg [1:0] state;
reg [20:0] dma_addr_reg;
reg [7:0] dma_wd_reg;
wire [3:0] device_busy;

assign dma_ack = (state == 0) && (device_sel_next != 4'b1111);
assign dma_end = (state == 3) && (device_sel != 4'b1111);

always @(posedge clk) begin
    if (!rst_n) begin
        state <= 2'b00;
        device_sel <= 4'b0000;
        device_sel_next <= 4'b0000;
        dma_addr_reg <= 21'h000000;
        dma_wd_reg <= 8'h00;
        rd <= 8'h00;
    end else begin
        case(state)
            2'b00: begin // Idle state
                if (dma_req && !device_busy[device_sel]) begin
                    state <= 2'b01;
                    device_sel_next <= device_sel;
                end else begin
                    device_sel <= device_sel_next;
                end
            end
            2'b01: begin // Request state
                dma_addr_reg <= dma_addr;
                dma_wd_reg <= dma_wd;
                device_sel <= 4'b1111;
                state <= 2'b10;
            end
            2'b10: begin // Access state
                addr[device_sel] <= dma_addr_reg;
                wd[device_sel] <= dma_wd_reg;
                if (rnw[device_sel]) begin // Read operation
                    rd <= dma_rd;
                end
                state <= 2'b11;
            end
            2'b11: begin // Done state
                done[device_sel] <= 1'b1;
                ack[device_sel] <= 1'b1;
                device_sel_next <= device_sel;
                state <= 2'b00;
            end
        endcase
    end
end

assign device_busy = (state != 2'b00) && (state != 2'b11);

endmodule

