module rle (
  input [n-1:0] data_in,
  output [m-1:0] data_out,
  output err
);

parameter n = 16; // number of binary data values
parameter m = 16; // number of binary data values after decoding
parameter k = 4; // maximum count value

reg [k-1:0] count;
reg [n-1:0] prev_data;
reg [m-1:0] decoded_data;
reg [k-1:0] count_index;
reg [1:0] state;

assign err = (count >= (1 << k)) ? 1'b1 : 1'b0;

always @(*) begin
  case (state)
    2'b00: begin // initial state
      prev_data = data_in[0];
      count = 1'b1;
      count_index = 0;
      state = 2'b01;
    end
    2'b01: begin // encoding state
      if (data_in[count_index] == prev_data) begin
        if (count < (1 << k)) begin
          count = count + 1'b1;
        end else begin
          state = 2'b10; // error state
        end
      end else begin
        decoded_data[count_index] = prev_data;
        prev_data = data_in[count_index];
        count = 1'b1;
        count_index = count_index + 1'b1;
        if (count_index == n) begin
          decoded_data[count_index] = prev_data;
          state = 2'b11; // final state
        end else begin
          state = 2'b01;
        end
      end
    end
    2'b10: begin // error state
      decoded_data = 0;
      state = 2'b00;
    end
    2'b11: begin // final state
      data_out = decoded_data;
      state = 2'b00;
    end
  endcase
end

endmodule

module ram_wb_harvard #(parameter AWIDTH=13)
  (input wb_clk_i,
   input wb_rst_i,

   input [AWIDTH-1:0] iwb_adr_i,
   input [31:0] iwb_dat_i,
   output reg [31:0] iwb_dat_o,
   input iwb_we_i,
   output reg iwb_ack_o,
   input iwb_stb_i,
   input [3:0] iwb_sel_i,

   input [AWIDTH-1:0] dwb_adr_i,
   input [31:0] dwb_dat_i,
   output reg [31:0] dwb_dat_o,
   input dwb_we_i,
   output reg dwb_ack_o,
   input dwb_stb_i,
   input [3:0] dwb_sel_i);

   reg [7:0]     ram0 [0:(1<<(AWIDTH-2))-1];
   reg [7:0]     ram1 [0:(1<<(AWIDTH-2))-1];
   reg [7:0]     ram2 [0:(1<<(AWIDTH-2))-1];
   reg [7:0]     ram3 [0:(1<<(AWIDTH-2))-1];

   // Instruction Read Port
   always @(posedge wb_clk_i)
     iwb_ack_o <= iwb_stb_i & ~iwb_ack_o;

   always @(posedge wb_clk_i)
     iwb_dat_o[31:24] <= ram3[iwb_adr_i[AWIDTH-1:2]];
   always @(posedge wb_clk_i)
     iwb_dat_o[23:16] <= ram2[iwb_adr_i[AWIDTH-1:2]];
   always @(posedge wb_clk_i)
     iwb_dat_o[15:8] <= ram1[iwb_adr_i[AWIDTH-1:2]];
   always @(posedge wb_clk_i)
     iwb_dat_o[7:0] <= ram0[iwb_adr_i[AWIDTH-1:2]];

   always @(posedge wb_clk_i)
     if(iwb_we_i & iwb_stb_i & iwb_sel_i[3])
       ram3[iwb_adr_i[AWIDTH-1:2]] <= iwb_dat_i[31:24];
   always @(posedge wb_clk_i)
     if(iwb_we_i & iwb_stb_i & iwb_sel_i[2])
       ram2[iwb_adr_i[AWIDTH-1:2]] <= iwb_dat_i[23:16];
   always @(posedge wb_clk_i)
     if(iwb_we_i & iwb_stb_i & iwb_sel_i[1])
       ram1[iwb_adr_i[AWIDTH-1:2]] <= iwb_dat_i[15:8];
   always @(posedge wb_clk_i)
     if(iwb_we_i & iwb_stb_i & iwb_sel_i[0])
       ram0[iwb_adr_i[AWIDTH-1:2]] <= iwb_dat_i[7:0];

   // Data Port
   always @(posedge wb_clk_i)
     dwb_ack_o <= dwb_stb_i & ~dwb_ack_o;

   always @(posedge wb_clk_i)
     dwb_dat_o[31:24] <= dwb_sel_i[3] ? dwb_dat_i[31:24] : ram3[dwb_adr_i[AWIDTH-1:2]];
   always @(posedge wb_clk_i)
     dwb_dat_o[23:16] <= dwb_sel_i[2] ? dwb_dat_i[23:16] : ram2[dwb_adr_i[AWIDTH-1:2]];
   always @(posedge wb_clk_i)
     dwb_dat_o[15:8] <= dwb_sel_i[1] ? dwb_dat_i[15:8] : ram1[dwb_adr_i[AWIDTH-1:2]];
   always @(posedge wb_clk_i)
     dwb_dat_o[7:0]  <= dwb_sel_i[0] ? dwb_dat_i[7:0] : ram0[dwb_adr_i[AWIDTH-1:2]];

   always @(posedge wb_clk_i)
     if(dwb_we_i & dwb_stb_i & dwb_sel_i[3])
       ram3[dwb_adr_i[AWIDTH-1:2]] <= dwb_dat_i[31:24];
   always @(posedge wb_clk_i)
     if(dwb_we_i & dwb_stb_i & dwb_sel_i[2])
       ram2[dwb_adr_i[AWIDTH-1:2]] <= dwb_dat_i[23:16];
   always @(posedge wb_clk_i)
     if(dwb_we_i & dwb_stb_i & dwb_sel_i[1])
       ram1[dwb_adr_i[AWIDTH-1:2]] <= dwb_dat_i[15:8];
   always @(posedge wb_clk_i)
     if(dwb_we_i & dwb_stb_i & dwb_sel_i[0])
       ram0[dwb_adr_i[AWIDTH-1:2]] <= dwb_dat_i[7:0];

endmodule

module up_down_counter (
    input clk,
    input reset,
    input direction,
    output reg [15:0] count,
    output [3:0] overflows
);

    reg [15:0] max_val = 16'd9999; // Maximum value of the counter
    reg [15:0] min_val = 16'd0000; // Minimum value of the counter
    reg [3:0] overflow_count = 4'b0000; // Counter for number of overflows

    always @(posedge clk) begin
        if (reset) begin
            count <= 16'd0000;
            overflow_count <= 4'b0000;
        end else begin
            if (direction) begin
                if (count == max_val) begin
                    count <= min_val;
                    overflow_count <= overflow_count + 1;
                end else begin
                    count <= count + 1;
                end
            end else begin
                if (count == min_val) begin
                    count <= max_val;
                    overflow_count <= overflow_count + 1;
                end else begin
                    count <= count - 1;
                end
            end
        end
    end

    assign overflows = overflow_count;

endmodule

module SPI_IF_accel( 
    input clk,
    input rst,
    input [6:0] mpu_address,
    input [7:0] mpu_wr_data,
    input mpu_rd_wr_sel,
    input start,
    output busy,
    output SPI_SS_a,
    output SPI_CK_a,
    output SPI_DO_a,
    input SPI_DI_a,
    output [7:0] mpu_rd_data
);

    reg [7:0] mpu_rd_data_buff;
    reg [7:0] SPIstate;
    reg [11:0] counter;
    reg MPUclk;
    reg do_reg;
    reg ss_reg;
    reg ck_reg;
    reg busy_bf;
    reg [4:0] i;
    reg [4:0] j;

    parameter SPI_HALF_CLK = 50;
    parameter SPI_CLK = SPI_HALF_CLK*2;

    wire halfCLKpassed = (counter == SPI_HALF_CLK-1);

    always@(posedge clk) begin
        if(rst) begin
            counter <= 0;
            MPUclk <= 0;
        end
        else begin
            if(start==1) begin
                counter <= 0;       
                MPUclk <= 1;            
            end
            else if(halfCLKpassed) begin            
                counter <= 0;       
                MPUclk <= ~MPUclk;
            end
            else begin
                counter <= counter + 1;
            end
        end
    end

    always @(posedge clk) begin
        if(rst) begin
            SPIstate = 0;
        end
        else begin        
            case(SPIstate)
                0:if(start == 1) SPIstate = 1;
                1:SPIstate = 3;
                3:begin
                    if(i==0 && mpu_rd_wr_sel == 1) SPIstate = 4;
                    if(i==0 && mpu_rd_wr_sel == 0) SPIstate = 5;
                end
                4:if(j==0) SPIstate = 6;
                5:if(j==0) SPIstate = 6;
                6:if(halfCLKpassed) SPIstate = 7;
                7:SPIstate = 0;
            endcase
        end
    end

    always @ (posedge clk) begin 
        if(rst) begin
            do_reg = 0;
            ck_reg = 1;
            ss_reg = 1;
            busy_bf = 0;
            mpu_rd_data_buff = 0;
            i = 16;
            j = 17;
        end
        else begin
            case(SPIstate)
                0:begin
                    do_reg = 0;
                    ss_reg = 1; 
                    busy_bf = 0;
                    i = 16;
                    j = 17;
                end
                1:begin
                    busy_bf = 1;
                    ss_reg = 0;
                end
                3:begin
                    if(halfCLKpassed) begin
                        case (i)
                            16:do_reg = mpu_rd_wr_sel;
                            14:do_reg = mpu_address[6];
                            12:do_reg = mpu_address[5];
                            10:do_reg = mpu_address[4];
                            8: do_reg = mpu_address[3];
                            6: do_reg = mpu_address[2];
                            4: do_reg = mpu_address[1];
                            2: do_reg = mpu_address[0];
                            0: do_reg = 0;
                        endcase
                        if(i!=0) i=i-1;
                    end
                end
                4:begin
                    if(halfCLKpassed) begin
                        case (j)
                            16:mpu_rd_data_buff[7] = SPI_DI_a;
                            14:mpu_rd_data_buff[6] = SPI_DI_a;
                            12:mpu_rd_data_buff[5] = SPI_DI_a;
                            10:mpu_rd_data_buff[4] = SPI_DI_a;
                            8:mpu_rd_data_buff[3] = SPI_DI_a;
                            6:mpu_rd_data_buff[2] = SPI_DI_a;
                            4:mpu_rd_data_buff[1] = SPI_DI_a;
                            2:mpu_rd_data_buff[0] = SPI_DI_a;                       
                        endcase
                        if(j!=0) j=j-1;
                    end
                end    
                5:begin
                    if(halfCLKpassed) begin
                        case (j)
                            16:do_reg = mpu_wr_data[7]; 
                            14:do_reg = mpu_wr_data[6]; 
                            12:do_reg = mpu_wr_data[5]; 
                            10:do_reg = mpu_wr_data[4]; 
                            8:do_reg = mpu_wr_data[3]; 
                            6:do_reg = mpu_wr_data[2]; 
                            4:do_reg = mpu_wr_data[1]; 
                            2:do_reg = mpu_wr_data[0]; 
                            0:do_reg = 0;
                        endcase
                        if(j!=0) j=j-1;
                    end
                end
                6:begin
                    ck_reg =1;
                    do_reg =0;
                    ss_reg = 1;
                end
                7:begin
                end
            endcase
        end
    end

    assign SPI_DO_a = do_reg;
    assign SPI_CK_a = MPUclk | ss_reg;
    assign SPI_SS_a = ss_reg;
    assign busy = busy_bf | start;
    assign mpu_rd_data = mpu_rd_data_buff;

endmodule

