  reg [1:0] state;

  always @(posedge clk) begin
    case (state)
      2'b00: begin // State 0
        state <= 2'b01;
      end
      2'b01: begin // State 1
        gray_reg[3] <= bin_in[3];
        gray_reg[2] <= bin_in[3] ^ bin_in[2];
        gray_reg[1] <= bin_in[2] ^ bin_in[1];
        gray_reg[0] <= bin_in[1] ^ bin_in[0];
        gray_out <= gray_reg;
        state <= 2'b00;
      end
      default: begin
        state <= 2'b00;
      end
    endcase
  end

endmodule

module sqrt_16bit (
    input [15:0] a,
    input ctrl,
    output reg [15:0] b
);

// Pipeline registers
reg [15:0] a_reg1, a_reg2;
reg [15:0] b_reg1, b_reg2;

// Combinational square root algorithm
always @(*) begin
    if (a_reg1[15:14] == 2'b11) // If MSBs are 11, shift right by 2
        a_reg2 = {a_reg1[13:0], 2'b00};
    else if (a_reg1[15:14] == 2'b10) // If MSBs are 10, shift right by 1
        a_reg2 = {a_reg1[14:0], 1'b0};
    else // If MSBs are 00 or 01, shift right by 0
        a_reg2 = a_reg1;

    if (ctrl == 1) // If rounding is required, add 1 to the result
        b_reg2 = b_reg1 + 1;
    else // If rounding is not required, truncate the result
        b_reg2 = b_reg1;
end

// Pipeline stages
always @(posedge clk) begin
    a_reg1 <= a;
    b_reg1 <= 0;
end

always @(posedge clk) begin
    a_reg1 <= a_reg2;
    b_reg1 <= b_reg2;
end

always @(posedge clk) begin
    b_reg1 <= (b_reg2 + a_reg2[b_reg2+3: b_reg2+2]) << 1;
end

always @(posedge clk) begin
    b <= b_reg1[15:0];
end

endmodule

module multiplexer_4to1 (
    input [7:0] data_in0,
    input [7:0] data_in1,
    input [7:0] data_in2,
    input [7:0] data_in3,
    input [1:0] select,
    output reg [7:0] data_out
);

always @(*) begin
    case (select)
        2'b00: data_out = data_in0;
        2'b01: data_out = data_in1;
        2'b10: data_out = data_in2;
        2'b11: data_out = data_in3;
    endcase
end

endmodule

module binary_counter (
   input clk,
   input rst,
   input enable,
   output reg [3:0] count
);

   always @(posedge clk, negedge rst) begin
      if (!rst) begin
         count <= 4'b0;
      end else if (enable) begin
         count <= count + 2;
      end else begin
         count <= count + 1;
      end
      if (count == 4'b1111) begin
         count <= 4'b0;
      end
   end

endmodule

module fsm_rising_edge_counter (
  input clk,
  input in,
  output reg[2:0] count
);

  reg d_last;
  reg[1:0] state;

  parameter IDLE = 2'b00;
  parameter COUNT = 2'b01;

  always @(posedge clk) begin
    case(state)
      IDLE:
        if(in && !d_last) begin
          state <= COUNT;
          count <= 0;
        end
      COUNT:
        if(in && !d_last) begin
          if(count == 4) begin
            state <= IDLE;
          end
          else begin
            count <= count + 1;
          end
        end
        else begin
          state <= IDLE;
        end
    endcase
    d_last <= in;
  end

endmodule

module adder_16bit(
    input clk,
    input reset,
    input [15:0] a,
    input [15:0] b,
    input cin,
    output [15:0] sum,
    output cout
);

reg [15:0] sum_reg;
reg cout_reg;

always @(posedge clk) begin
    if (reset) begin
        sum_reg <= 16'd0;
        cout_reg <= 1'b0;
    end else begin
        sum_reg <= a + b + cin;
        cout_reg <= (sum_reg[16] == 1);
    end
end

assign sum = sum_reg;
assign cout = cout_reg;

endmodule

module soc_system_button_pio (
  // inputs:
  address,
  chipselect,
  clk,
  in_port,
  reset_n,
  write_n,
  writedata,

  // outputs:
  irq,
  readdata
);

  output irq;
  output [31:0] readdata;
  input [1:0] address;
  input chipselect;
  input clk;
  input [1:0] in_port;
  input reset_n;
  input write_n;
  input [31:0] writedata;

  wire clk_en;
  reg [1:0] d1_data_in;
  reg [1:0] d2_data_in;
  wire [1:0] data_in;
  reg [1:0] edge_capture;
  wire edge_capture_wr_strobe;
  wire [1:0] edge_detect;
  wire irq;
  reg [1:0] irq_mask;
  wire [1:0] read_mux_out;
  reg [31:0] readdata;

  assign clk_en = 1;

  // Multiplexer for readdata output
  assign read_mux_out = ({2 {(address == 0)}} & data_in) |
                        ({2 {(address == 2)}} & irq_mask) |
                        ({2 {(address == 3)}} & edge_capture);

  // Register for readdata output
  always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
      readdata <= 0;
    end else if (clk_en) begin
      readdata <= {32'b0 | read_mux_out};
    end
  end

  // Assign data_in to in_port input
  assign data_in = in_port;

  // Register for irq_mask
  always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
      irq_mask <= 0;
    end else if (chipselect && ~write_n && (address == 2)) begin
      irq_mask <= writedata[1:0];
    end
  end

  // Generate irq signal
  assign irq = |(edge_capture & irq_mask);

  // Generate edge_capture_wr_strobe signal
  assign edge_capture_wr_strobe = chipselect && ~write_n && (address == 3);

  // Register for edge_capture[0]
  always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
      edge_capture[0] <= 0;
    end else if (clk_en) begin
      if (edge_capture_wr_strobe && writedata[0]) begin
        edge_capture[0] <= 0;
      end else if (edge_detect[0]) begin
        edge_capture[0] <= ~in_port[0];
      end
    end
  end

  // Register for edge_capture[1]
  always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
      edge_capture[1] <= 0;
    end else if (clk_en) begin
      if (edge_capture_wr_strobe && writedata[1]) begin
        edge_capture[1] <= 0;
      end else if (edge_detect[1]) begin
        edge_capture[1] <= ~in_port[1];
      end
    end
  end

  // Registers for edge_detect
  always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
      d1_data_in <= 0;
      d2_data_in <= 0;
    end else if (clk_en) begin
      d1_data_in <= data_in;
      d2_data_in <= d1_data_in;
    end
  end

  // Generate edge_detect signal
  assign edge_detect = ~d1_data_in & d2_data_in;

endmodule

module calculator(
  input clk,
  input reset,
  input [1:0] op,
  input [7:0] num1,
  input [7:0] num2,
  output reg [7:0] result,
  output reg overflow
);

  reg [15:0] temp_result;

  always @(posedge clk) begin
    if(reset) begin
      result <= 0;
      overflow <= 0;
      temp_result <= 0;
    end else begin
      case(op)
        2'b00: temp_result <= num1 * num2; // multiplication
        2'b01: temp_result <= num1 - num2; // subtraction
        2'b10: temp_result <= num1 + num2; // addition
        2'b11: if(num2 != 0) begin // division
                 temp_result <= num1 / num2;
               end else begin
                 temp_result <= 0;
               end
      endcase

      if(temp_result > 255) begin
        overflow <= 1;
        result <= temp_result[7:0];
      end else begin
        overflow <= 0;
        result <= temp_result[7:0];
      end
    end
  end

endmodule

module dff_rst_set (
