reg q;

always @(posedge clk) begin
    if (rst) begin
        q <= 0;
    end
    else if (set) begin
        q <= 1;
    end
    else begin
        q <= d;
    end
end

assign qn = ~q;

endmodule

module rx_to_fifo(
    input clk,
    input rst,
    input rx_clk,
    input rx_dv,
    input [7:0] rxd,
    output reg [8:0] din,
    output reg full,
    output reg wr_en,
    output reg wr_clk
);

reg [8:0] rom [0:199];
reg [11:0] counter;
reg [2:0] gap_count;

always @(posedge rx_clk) begin
    if (rx_dv) begin
        din <= rom[counter];
        counter <= counter + 1;
    end
end

always @(posedge clk) begin
    if (rst) begin
        counter <= 0;
        gap_count <= 0;
        full <= 0;
        wr_en <= 0;
        wr_clk <= 0;
    end else begin
        if (gap_count < 4'h2) begin
            gap_count <= gap_count + 1;
        end else if (!full && !wr_en) begin
            wr_en <= 1;
            wr_clk <= 1;
        end else if (full && wr_en) begin
            wr_en <= 0;
            wr_clk <= 0;
        end
    end
end

always @(posedge wr_clk) begin
    if (wr_en) begin
        if (counter == 199) begin
            full <= 1;
        end else begin
            full <= 0;
            counter <= counter + 1;
        end
    end
end

initial begin
    $readmemh("phy_rx.hex", rom);
end

endmodule

module FpuFp64_Mul(
	/* verilator lint_off UNUSED */
	clk,
	enable,
	srca,
	srcb,
	dst
);

parameter PRECISE_FMUL = 1;

input			clk;
input			enable;
input[63:0]		srca;
input[63:0]		srcb;
output[63:0]	dst;

reg sgna;
reg sgnb;
reg sgnc;

reg[12:0] exa;
reg[12:0] exb;
reg[12:0] exc;

`ifdef PRECISE_FMUL
reg[105:0] tFracA;
reg[105:0] tFracB;
reg[105:0] tFracC1;
reg[63:0] tFracC;
`else
reg[63:0] tFracA;
reg[63:0] tFracB;
reg[63:0] tFracC;
`endif

reg[51:0] tFracC2;

// Determine the sign of each input number
always @ (srca, srcb)
begin
	sgna=srca[63];
	sgnb=srcb[63];
end

// Extract the exponent of each input number
always @ (srca, srcb)
begin
	exa[10:0]=srca[62:52];
	exb[10:0]=srcb[62:52];
	exa[12:11]=0;
	exb[12:11]=0;
end

// Extract the fraction of each input number
always @ (srca, srcb)
begin
`ifdef PRECISE_FMUL
	tFracA[105:52]=1;
	tFracB[105:52]=1;
`else
	tFracA[63:52]=1;
	tFracB[63:52]=1;
`endif
	tFracA[51:0]=srca[51:0];
	tFracB[51:0]=srcb[51:0];
end

// Multiply the fractions together
always @ (srca, srcb)
begin
`ifdef PRECISE_FMUL
	tFracC1=tFracA*tFracB;
	tFracC=tFracC1[105:42]+64'h3FF;
`else	
	tFracC=(tFracA>>21)*(tFracB>>21);
`endif
end

// Determine the sign of the output number
always @ (sgna, sgnb)
begin
	sgnc=sgna^sgnb;
end

// Determine the exponent of the output number
always @ (exa, exb, tFracC)
begin
	if(tFracC[63])
	begin
		tFracC2[51:0]=tFracC[62:11];
		exc=exa+exb-1022;
	end
	else
	begin
		tFracC2[51:0]=tFracC[61:10];
		exc=exa+exb-1023;
	end
end

// Determine the fraction of the output number
always @ (tFracC)
begin
	tFracC2[51:0]=tFracC[61:10];
end

// Combine the sign, exponent, and fraction to get the output number
always @ (sgnc, exc, tFracC2)
begin
	if(exc[12])
	begin
		tDst=0;
	end
	else
	if(exc[11])
	begin
		tDst[63]=sgnc;
		tDst[62:0]=63'h7FF0_0000_0000_0000;
	end
	else
	begin
		tDst[63]=sgnc;
		tDst[62:52]=exc[10:0];
		tDst[51: 0]=tFracC2[51:0];
	end
end

assign dst = tDst;

endmodule

module PWM (
  input clk,
  input rst,
  input [p-1:0] mod,
  output pwm
);

parameter p = 8; // number of bits used to represent the modulation signal

reg [p-1:0] counter;
reg pwm_reg;

always @(posedge clk or posedge rst) begin
  if (rst) begin
    counter <= 0;
    pwm_reg <= 0;
  end else begin
    counter <= counter + 1;
    if (counter >= 2**p) begin
      counter <= 0;
    end
    if (counter < mod) begin
      pwm_reg <= 1;
    end else begin
      pwm_reg <= 0;
    end
  end
end

assign pwm = pwm_reg;

endmodule

module top_module (
    input [1:0] A, // Input for the decoder module
    input [1:0] B, // Input for the decoder module
    input signed [15:0] M, // Input for the multiplier module
    input signed [15:0] N, // Input for the multiplier module
    output signed [31:0] result // Output from the functional module
);

    // Decoder module
    wire [15:0] decoder_output;
    decoder_4to16 decoder_inst (
        .A(A),
        .B(B),
        .Y(decoder_output)
    );

    // Multiplier module
    wire signed [31:0] multiplier_output;
    multiplier_16bit multiplier_inst (
        .M(M),
        .N(N),
        .P(multiplier_output)
    );

    // Functional module
    wire signed [15:0] selected_output;
    functional_module functional_inst (
        .decoder_output(decoder_output),
        .multiplier_output(multiplier_output),
        .selected_output(selected_output)
    );

    // Output
    assign result = {16'd0, selected_output};

endmodule


module decoder_4to16 (
    input [1:0] A, // Input A
    input [1:0] B, // Input B
