            2'b00: Y = 16'b0000000000000001;
            2'b01: Y = 16'b0000000000000010;
            2'b10: Y = 16'b0000000000000100;
            2'b11: Y = 16'b0000000000001000;
            2'b0001: Y = 16'b0000000000010000;
            2'b0010: Y = 16'b0000000000100000;
            2'b0011: Y = 16'b0000000001000000;
            2'b0100: Y = 16'b0000000010000000;
            2'b0101: Y = 16'b0000000100000000;
            2'b0110: Y = 16'b0000001000000000;
            2'b0111: Y = 16'b0000010000000000;
            2'b1000: Y = 16'b0000100000000000;
            2'b1001: Y = 16'b0001000000000000;
            2'b1010: Y = 16'b0010000000000000;
            2'b1011: Y = 16'b0100000000000000;
            2'b1100: Y = 16'b1000000000000000;
