module functional_module (
    input [15:0] decoder_output, // Input from the decoder module
    input signed [31:0] multiplier_output, // Input from the multiplier module
    output reg signed [15:0] selected_output // Output selected output
);

    always @(*) begin
        case (decoder_output)
            16'b0000000000000001: selected_output = multiplier_output[15:0];
            16'b0000000000000010: selected_output = multiplier_output[31:16];
            16'b0000000000000100: selected_output = multiplier_output[47:32];
            16'b0000000000001000: selected_output = multiplier_output[63:48];
            16'b0000000000010000: selected_output = multiplier_output[79:64];
            16'b0000000000100000: selected_output = multiplier_output[95:80];
            16'b0000000001000000: selected_output = multiplier_output[111:96];
            16'b0000000010000000: selected_output = multiplier_output[127:112];
            16'b0000000100000000: selected_output = multiplier_output[143:128];
            16'b0000001000000000: selected_output = multiplier_output[159:144];
            16'b0000010000000000: selected_output = multiplier_output[175:160];
            16'b0000100000000000: selected_output = multiplier_output[191:176];
            16'b0001000000000000: selected_output = multiplier_output[207:192];
            16'b0010000000000000: selected_output = multiplier_output[223:208];
            16'b0100000000000000: selected_output = multiplier_output[239:224];
            16'b1000000000000000: selected_output = multiplier_output[255:240];
            default: selected_output = 16'd0;
        endcase
    end

