module top_module (
    input clk,
    input reset,       // Synchronous active-high reset
    input [2:0] sel,   // Select input for the multiplexer
    input [3:0] data0, // 4-bit data inputs for the multiplexer
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output [15:0] q    // 16-bit output from the functional module
);

    // 6-to-1 Multiplexer
    wire [2:0] mux_sel;
    wire [3:0] mux_out;

    priority_encoder pe(
        .sel(sel),
        .mux_sel(mux_sel)
    );

    mux_4to1 mux(
        .sel(mux_sel),
        .data0(data0),
        .data1(data1),
        .data2(data2),
        .data3(data3),
        .out(mux_out)
    );

    assign mux_out = (sel > 5) ? 0 : mux_out;

    // BCD Counter
    wire [3:0] digit_en;
    wire [15:0] bcd_out;

    bcd_counter counter(
        .clk(clk),
        .reset(reset),
        .digit_en(digit_en),
        .bcd_out(bcd_out)
    );

    priority_encoder pe2(
        .sel({bcd_out[3], bcd_out[7], bcd_out[11], bcd_out[15]}),
        .mux_sel(digit_en)
    );

    // Functional Module
    wire [15:0] sum;

    adder_mod adder(
        .a(mux_out),
        .b(bcd_out),
        .sum(sum)
    );

    assign q = sum;

endmodule

module mux_4to1 (
    input [2:0] sel,
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    output reg [3:0] out
);

    always @*
    begin
        case(sel)
            3'b000: out = data0;
            3'b001: out = data1;
            3'b010: out = data2;
            3'b011: out = data3;
            default: out = 4'b0;
        endcase
    end

endmodule

module priority_encoder (
    input [2:0] sel,
    output reg [2:0] mux_sel
);

    always @*
    begin
        case(sel)
            3'b000: mux_sel = 3'b000;
            3'b001: mux_sel = 3'b001;
            3'b010: mux_sel = 3'b010;
            3'b011: mux_sel = 3'b011;
            3'b100: mux_sel = 3'b100;
            3'b101: mux_sel = 3'b101;
            3'b110: mux_sel = 3'b101;
            default: mux_sel = 3'b000;
        endcase
    end

endmodule

module bcd_counter (
    input clk,
    input reset,
    input [3:0] digit_en,
    output reg [15:0] bcd_out
);

    reg [3:0] digits [0:3];
    reg [3:0] count = 4'b0000;

    always @(posedge clk)
    begin
        if(reset)
        begin
            digits <= 4'b0000;
            count <= 4'b0000;
        end
        else
        begin
            count <= count + 1;

            if(count == 4'b1001)
            begin
                count <= 4'b0000;
                digits <= digits + 1;
            end
        end
    end

    assign bcd_out = {digit_en[0] ? digits[0] : 4'b0000, digit_en[1] ? digits[1] : 4'b0000, digit_en[2] ? digits[2] : 4'b0000, digit_en[3] ? digits[3] : 4'b0000};

endmodule

module adder_mod (
    input [15:0] a,
    input [15:0] b,
    output reg [15:0] sum
);

    always @*
    begin
        sum = (a + b) % 65536;
    end

endmodule

module add_sub_4bit(
  input [3:0] A,
  input [3:0] B,
  input MODE,
  output [3:0] RESULT,
  output COUT,
  output BOUT
);

  wire [3:0] B_inv;
  wire [3:0] B_neg;
  wire [3:0] C_inv;
  wire [3:0] C_neg;

  assign B_inv = ~B;
  assign B_neg = B_inv + 1;

  assign C_inv = ~MODE;
  assign C_neg = C_inv + 1;

  assign RESULT = A + (B * C_inv) + (B_neg * C_neg);
  assign COUT = (A[3] & B[3]) | (B[3] & ~RESULT[3]) | (A[3] & ~RESULT[3]);
  assign BOUT = (~A[3] & B[3]) | (RESULT[3] & ~B[3]) | (A[3] & RESULT[3]);

endmodule

module ethernet_mac (
    input [63:0] tx_data,
    input tx_valid,
    input tx_start,
    input tx_error,
    input rx_ready,
    input rx_error,
    input clk,
    input rst,
    output tx_done,
    output [63:0] rx_data,
    output rx_valid,
    output rx_start
);

// Internal state definitions
parameter IDLE = 2'b00;
parameter TX_HEADER = 2'b01;
parameter TX_DATA = 2'b10;
parameter TX_TRAILER = 2'b11;
parameter RX_HEADER = 2'b01;
parameter RX_DATA = 2'b10;
parameter RX_TRAILER = 2'b11;

reg [1:0] state;
reg [63:0] tx_frame;
reg [63:0] rx_frame;
reg [6:0] rx_byte_counter;
reg [6:0] tx_byte_counter;
reg [31:0] crc;
reg [31:0] tx_crc;
reg [31:0] rx_crc;
reg tx_done;
reg rx_valid;
reg rx_start;

// Constants
parameter ETH_PREAMBLE = 64'h5555555555555555;
parameter ETH_HEADER = 48'h000000000000 + 16'h0800;
parameter ETH_TRAILER = 32'h00000000;

// Internal signals
wire tx_ready;
wire rx_done;
wire [63:0] rx_data_in;
wire [31:0] rx_crc_in;

// Instantiate Altera TSE MAC PCS/PMA module
tse_mac2 mac (
    .ff_tx_data(tx_frame[63:0]),
    .ff_tx_eop((tx_byte_counter == 63) ? 1'b1 : 1'b0),
    .ff_tx_err(tx_error),
    .ff_tx_sop((tx_byte_counter == 0) ? 1'b1 : 1'b0),
    .ff_tx_wren(tx_valid),
    .ff_tx_clk(clk),
    .ff_rx_rdy(rx_ready),
    .ff_rx_clk(clk),
    .address(8'h00),
    .read(1'b0),
    .writedata(32'h00),
    .write(1'b0),
    .clk(clk),
    .reset(rst),
    .mdio_in(1'b0),
    .rxp(1'b0),
    .ref_clk(1'b0),
    .ff_tx_rdy(tx_ready),
    .ff_rx_data(rx_data_in),
    .ff_rx_dval(rx_done),
    .ff_rx_eop((rx_byte_counter == 63) ? 1'b1 : 1'b0),
    .ff_rx_sop((rx_byte_counter == 0) ? 1'b1 : 1'b0),
    .rx_err(rx_error),
    .readdata(rx_crc_in),
    .waitrequest(1'b0),
    .mdio_out(1'b0),
    .mdio_oen(1'b0),
    .mdc(1'b0),
    .led_an(1'b0),
    .led_char_err(1'b0),
    .led_link(1'b0),
    .led_disp_err(1'b0),
    .led_crs(1'b0),
    .led_col(1'b0),
    .txp(1'b0),
    .rx_recovclkout(1'b0)
);

// State machine
always @(posedge clk, posedge rst) begin
    if (rst) begin
        state <= IDLE;
        tx_byte_counter <= 0;
        rx_byte_counter <= 0;
        crc <= 32'hFFFFFFFF;
        tx_crc <= 32'hFFFFFFFF;
        rx_crc <= 32'hFFFFFFFF;
        tx_done <= 0;
        rx_valid <= 0;
        rx_start <= 0;
    end else begin
        case (state)
            IDLE: begin
                if (tx_start) begin
                    tx_frame <= {ETH_PREAMBLE, ETH_HEADER, tx_data};
                    tx_byte_counter <= 0;
                    tx_crc <= crc;
                    state <= TX_HEADER;
                end else if (rx_ready) begin
                    rx_frame <= {rx_data_in};
                    rx_byte_counter <= 1;
                    rx_crc <= crc;
                    state <= RX_HEADER;
                end
            end
            TX_HEADER: begin
                if (tx_ready) begin
                    tx_frame <= {tx_frame[55:0], crc[31:0]};
                    tx_byte_counter <= tx_byte_counter + 1;
                    crc <= crc << 8;
                    crc[31:24] <= crc[31:24] ^ tx_frame[55];
                    state <= TX_DATA;
                end
            end
            TX_DATA: begin
                if (tx_ready) begin
                    tx_frame <= {tx_frame[55:0], tx_data[(tx_byte_counter+1)*8-1:tx_byte_counter*8]};
                    tx_byte_counter <= tx_byte_counter + 1;
                    crc <= crc << 8;
                    crc[31:24] <= crc[31:24] ^ tx_data[tx_byte_counter*8-1];
                    if (tx_byte_counter == 63) begin
                        tx_frame <= {tx_frame[55:0], tx_crc[31:0], ETH_TRAILER};
                        tx_byte_counter <= 0;
                        tx_crc <= 32'hFFFFFFFF;
                        tx_done <= 1;
                        state <= IDLE;
                    end
                end
            end
            RX_HEADER: begin
                if (rx_done) begin
                    if (rx_frame[47:0] == ETH_HEADER) begin
                        rx_valid <= 1;
                        rx_start <= 1;
                        rx_byte_counter <= 16;
                        crc <= rx_crc_in;
                        state <= RX_DATA;
                    end else begin
                        rx_valid <= 0;
                        rx_start <= 0;
                        state <= IDLE;
                    end
                end
            end
            RX_DATA: begin
                if (rx_done) begin
                    rx_frame <= {rx_frame[55:0], rx_data_in};
                    rx_byte_counter <= rx_byte_counter + 1;
                    crc <= crc << 8;
                    crc[31:24] <= crc[31:24] ^ rx_data_in[7:0];
                    if (rx_byte_counter == 63) begin
                        if (crc == 32'hFFFFFFFF) begin
                            rx_valid <= 1;
                            rx_start <= 0;
                        end else begin
                            rx_valid <= 0;
                            rx_start <= 0;
                        end
                        state <= RX_TRAILER;
                    end
                end
            end
            RX_TRAILER: begin
                if (rx_done) begin
                    if (rx_crc_in == crc) begin
                        rx_valid <= 1;
                    end else begin
                        rx_valid <= 0;
                    end
                    state <= IDLE;
                end
            end
        endcase
    end
end

endmodule

module DAC (
  input [n-1:0] d,
  output reg [7:0] Vout
);

parameter n = 4; // number of digital bits
parameter Vref = 3.3; // reference voltage

reg [n-1:0] Din;
reg [7:0] Vout_reg;

always @(*) begin
  Din = d;
end

always @(*) begin
  case(Din)
    4'b0000: Vout_reg = 8'b00000000;
    4'b0001: Vout_reg = 8'b00000001;
    4'b0010: Vout_reg = 8'b00000011;
    4'b0011: Vout_reg = 8'b00000110;
    4'b0100: Vout_reg = 8'b00001100;
    4'b0101: Vout_reg = 8'b00011000;
    4'b0110: Vout_reg = 8'b00110000;
    4'b0111: Vout_reg = 8'b01100000;
    4'b1000: Vout_reg = 8'b11000000;
    4'b1001: Vout_reg = 8'b11111111;
    default: Vout_reg = 8'b00000000;
  endcase
end

assign Vout = Vout_reg * Vref / 255;

endmodule

module delay_module (
    input A,
    input [3:0] delay_val,
    output reg X
);

reg [3:0] counter;

always @(posedge clk) begin
    if (counter == delay_val) begin
        X <= A;
    end else begin
        X <= X;
    end
    counter <= counter + 1;
end

endmodule

module priority_encoder (
    input [7:0] a, b, c, d, // 4-way minimum circuit input
    output [1:0] min_index // output index of minimum value
);

wire [7:0] ab_min, cd_min;
wire [7:0] ab_eq_cd;
wire [7:0] ac_min, bd_min;
wire [7:0] ac_eq_bd;
wire [7:0] ad_min, bc_min;

assign ab_min = (a < b) ? a : b;
assign cd_min = (c < d) ? c : d;
assign ab_eq_cd = (ab_min == cd_min);
assign ac_min = (a < c) ? a : c;
assign bd_min = (b < d) ? b : d;
assign ac_eq_bd = (ac_min == bd_min);
assign ad_min = (a < d) ? a : d;
assign bc_min = (b < c) ? b : c;

assign min_index = (ad_min <= bc_min) ? 2'b00 :
                  (ac_eq_bd) ? 2'b01 :
                  (ab_eq_cd) ? 2'b10 :
                               2'b11 ;

endmodule

module half_adder (
    input a_in, b_in, cin, // half adder input
    output sum, cout // half adder output
);

wire p, g;

assign p = a_in ^ b_in;
assign g = a_in & b_in;

assign sum = p ^ cin;
assign cout = g | (p & cin);

endmodule

module top_module ( 
    input [7:0] a, b, c, d, // 4-way minimum circuit input
    input cin, a_in, b_in, // half adder input
    output [8:0] final_out // 9-bit output including carry-out and minimum value
);

wire [1:0] min_index;
wire [7:0] min_value;
wire [1:0] min_index_1, min_index_2;
wire [7:0] min_value_1, min_value_2;
wire sum, cout;

priority_encoder pe(
    .a(a),
    .b(b),
    .c(c),
    .d(d),
    .min_index(min_index)
);

assign min_value = (min_index == 2'b00) ? a :
                  (min_index == 2'b01) ? b :
                  (min_index == 2'b10) ? c :
                                        d ;

half_adder ha(
    .a_in(a_in),
    .b_in(b_in),
    .cin(cin),
    .sum(sum),
    .cout(cout)
);

assign final_out = {cout, min_value};

endmodule

module audio_clock_generator (
	input			clk,
	input			reset_n,
	input	[31:0]	cmd_reg1,
	input	[31:0]	cmd_reg2,
	output			mclk,
	output			bclk,
	input			lrclk_clear,
	output			lrclk1,
	output			lrclk2
);

	wire [7:0]		mclk_divisor = cmd_reg1[31:24]; // divide by (n + 1)*2
	wire [7:0]		bclk_divisor = cmd_reg1[23:16]; // divide by (n + 1)*2
	wire [7:0]		lrclk1_divisor = cmd_reg2[15:8]; // divide by (n + 1)*2*16
	wire [7:0]		lrclk2_divisor = cmd_reg2[7:0]; // divide by (n + 1)*2*16

	reg [7:0]		mclk_counter = 0;
	reg 			mclk_tick = 0;
	assign			mclk = mclk_tick;

	reg [7:0]		bclk_counter = 0;
	reg 			bclk_tick = 0;
	assign			bclk = bclk_tick;

	reg [7:0]		lrclk1_counter = 0;
	reg 			lrclk1_tick = 0;
	assign			lrclk1 = lrclk1_tick;

	reg [7:0]		lrclk2_counter = 0;
	reg 			lrclk2_tick = 0;
	assign			lrclk2 = lrclk2_tick;

	always @(posedge clk or negedge reset_n) begin
		if (~reset_n) begin
			mclk_counter <= 0;
			mclk_tick <= 0;
			bclk_counter <= 0;
			bclk_tick <= 0;
			lrclk1_counter <= 0;
			lrclk1_tick <= 0;
			lrclk2_counter <= 0;
			lrclk2_tick <= 0;
		end else begin
			mclk_counter <= mclk_counter + 1;
			if (mclk_counter >= mclk_divisor) begin
				mclk_counter <= 0;
				mclk_tick <= ~mclk_tick;
			end

			bclk_counter <= bclk_counter + 1;
			if (bclk_counter >= bclk_divisor) begin
				bclk_counter <= 0;
				bclk_tick <= ~bclk_tick;
			end

			if (~lrclk_clear) begin
				lrclk1_counter <= 0;
				lrclk1_tick <= 0;
				lrclk2_counter <= 0;
				lrclk2_tick <= 0;
			end else begin
				lrclk1_counter <= lrclk1_counter + 1;
				if (lrclk1_counter >= lrclk1_divisor) begin
					lrclk1_counter <= 0;
					lrclk1_tick <= ~lrclk1_tick;
				end

				lrclk2_counter <= lrclk2_counter + 1;
				if (lrclk2_counter >= lrclk2_divisor) begin
					lrclk2_counter <= 0;
					lrclk2_tick <= ~lrclk2_tick;
				end
			end
		end
	end

endmodule

module calculator (
   input [3:0] A,
   input [3:0] B,
   input [1:0] op,
   output reg [3:0] sum,
   output reg [3:0] diff,
   output reg [3:0] prod,
   output reg [3:0] quot
);

always @* begin
   case (op)
      2'b00: begin // addition
         sum = A + B;
         diff = 4'b0;
         prod = 4'b0;
         quot = 4'b0;
      end
      2'b01: begin // subtraction
         sum = 4'b0;
         diff = A - B;
         prod = 4'b0;
         quot = 4'b0;
      end
      2'b10: begin // multiplication
         sum = 4'b0;
         diff = 4'b0;
         prod = A * B;
         quot = 4'b0;
      end
      2'b11: begin // division
         sum = 4'b0;
         diff = 4'b0;
         prod = 4'b0;
         if (B == 4'b0) // division by zero
            quot = 4'b0;
         else
            quot = A / B;
      end
      default: begin // invalid op
         sum = 4'b0;
         diff = 4'b0;
         prod = 4'b0;
         quot = 4'b0;
      end
   endcase
end

endmodule

module counter_load_out_collaps_free(
  input clk, rst, clk_ena, clk_ena_job, load, 
  input [WIDTH-1:0] dfload,
  output carry,
  output [WIDTH-1:0] dout
);

  parameter MOD_COUNT = 7;
  parameter WIDTH = 8;

  // local signals
  reg [WIDTH-1:0] count;
  reg carry_tmp;
  wire loco = load & clk_ena_job;
  reg [WIDTH-1:0] dout_tmp;

  // assign outputs
  assign carry = carry_tmp;
  assign dout = (clk_ena) ? count : dout_tmp;

  // counter logic
  always @(posedge clk or posedge rst) begin
    if(rst)
      count <= 0;
    else if(clk_ena) begin
      if(load)
        count <= dfload;
      else if(clk_ena_job)
        count <= count + 1;
      if(loco)
        count <= 1;
    end
    dout_tmp <= count;
  end

  // carry logic
  always @(count) begin
    carry_tmp <= (count == MOD_COUNT-1) ? 1 : 0;
  end

endmodule

module reverse_bit_order(
    input [99:0] in,
    output [99:0] out
);

reg [99:0] shift_reg;
wire [99:0] reversed;

assign reversed[0] = shift_reg[99];

genvar i;
generate
    for (i = 1; i < 100; i = i + 1) begin : SHIFT_LOOP
        assign reversed[i] = shift_reg[99-i];
    end
endgenerate

assign out = reversed;

always @(posedge clk) begin
    shift_reg <= {shift_reg[98:0], in[0]};
end

endmodule

module shift_register(
    input clk,
    input areset,  // async active-high reset to zero
    input load,
    input ena,
    input [7:0] data,
    output reg [7:0] q,
    output reg [7:0] parallel_out);

    reg [7:0] shift_reg;
    reg [7:0] parallel_reg;

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            shift_reg <= 8'b0;
            parallel_reg <= 8'b0;
        end
        else begin
            if (ena) begin
                shift_reg <= {shift_reg[6:0], data};
            end
            else if (load) begin
                shift_reg <= data;
            end
            parallel_reg <= shift_reg;
        end
    end

    assign q = shift_reg[7:0];
    assign parallel_out = parallel_reg[7:0];

endmodule

module Hyperbolic (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 4; // number of input signals
parameter m = 3; // number of output signals

function [31:0] sineh;
  input [31:0] x;
  reg [31:0] exp_x, exp_neg_x;
  begin
    exp_x = $exp(x);
    exp_neg_x = $exp(-x);
    sineh = (exp_x - exp_neg_x) / 2;
  end
endfunction

function [31:0] cosh;
  input [31:0] x;
  reg [31:0] exp_x, exp_neg_x;
  begin
    exp_x = $exp(x);
    exp_neg_x = $exp(-x);
    cosh = (exp_x + exp_neg_x) / 2;
  end
endfunction

function [31:0] tanh;
  input [31:0] x;
  reg [31:0] exp_x, exp_neg_x;
  begin
    exp_x = $exp(x);
    exp_neg_x = $exp(-x);
    tanh = (exp_x - exp_neg_x) / (exp_x + exp_neg_x);
  end
endfunction

generate
  genvar i;
  for (i = 0; i < n; i = i + 1) begin : hyperbolic_gen
    assign out[i * m] = sineh(in[i]);
    assign out[i * m + 1] = cosh(in[i]);
    assign out[i * m + 2] = tanh(in[i]);
  end
endgenerate

endmodule

