module vga_generator(
    input wire CLK_24M,
    input wire USR_BTN,
    output wire [2:0] VGA_RGB,
    output wire HSYNC,
    output wire VSYNC
);

    reg [10:0] hzcount;
    reg [10:0] vtcount;
    reg [10:0] pixel_row;
    reg [3:0] pixel_col;
    reg [10:0] line_count;
    reg [10:0] frame_count;
    reg [10:0] pixel_count;
    reg [1:0] color;
    reg [10:0] red_value;
    reg [10:0] green_value;
    reg [10:0] blue_value;

    // Initialize all variables
    initial begin
        hzcount <= 0;
        vtcount <= 0;
        pixel_row <= 0;
        pixel_col <= 0;
        line_count <= 0;
        frame_count <= 0;
        pixel_count <= 0;
        color <= 0;
        red_value <= 0;
        green_value <= 0;
        blue_value <= 0;
    end

    // Generate VGA signals
    always @(posedge CLK_24M) begin
        // Increment hzcount
        if (hzcount < 800) begin
            hzcount <= hzcount + 1;
        end
        // Generate horizontal sync signal
        else if (hzcount == 800) begin
            hzcount <= 0;
            HSYNC <= 1;
        end
        else begin
            HSYNC <= 0;
        end

        // Generate vertical sync signal
        if (vtcount < 525) begin
            vtcount <= vtcount + 1;
            VSYNC <= 0;
        end
        else begin
            vtcount <= 0;
            VSYNC <= 1;
        end

        // Generate VGA_RGB values
        if (hzcount < 640 && vtcount < 480) begin
            // Calculate pixel row and column
            if (pixel_col == 3) begin
                pixel_col <= 0;
                pixel_row <= pixel_row + 1;
            end
            else begin
                pixel_col <= pixel_col + 1;
            end

            // Calculate red value
            if (pixel_col == 0) begin
                red_value <= vtcount[(hzcount / 64) % 11];
            end

            // Set green and blue values to 0
            if (pixel_col == 1) begin
                green_value <= 0;
                blue_value <= 0;
            end

            // Combine color values
            if (pixel_col == 2) begin
                color <= {green_value, blue_value};
                VGA_RGB <= {red_value, color};
            end

            // Increment pixel count
            pixel_count <= pixel_count + 1;

            // Increment line count
            if (pixel_count == 640) begin
                pixel_count <= 0;
                line_count <= line_count + 1;
            end

            // Increment frame count
            if (line_count == 480) begin
                line_count <= 0;
                frame_count <= frame_count + 1;
            end
        end
    end

endmodule

