module top_module (
    input clk,
    input [7:0] a,
    input [7:0] b,
    input select,
    output [7:0] sum
);

    wire [7:0] ripple_sum;
    wire [7:0] full_sum;

    ripple_carry_adder ripple_adder(
        .clk(clk),
        .a(a),
        .b(b),
        .sum(ripple_sum)
    );

    full_adder full_adder0(
        .a(a[0]),
        .b(b[0]),
        .cin(1'b0),
        .sum(full_sum[0]),
        .cout()
    );

    generate
        for (i = 1; i < 8; i = i + 1) begin : gen_full_adder
            full_adder full_adder_i (
                .a(a[i]),
                .b(b[i]),
                .cin(full_sum[i-1]),
                .sum(full_sum[i]),
                .cout()
            );
        end
    endgenerate

    functional_module func_module(
        .select(select),
        .ripple_sum(ripple_sum),
        .full_sum(full_sum),
        .sum(sum)
    );

endmodule

module ripple_carry_adder (
    input clk,
    input [7:0] a,
    input [7:0] b,
    output [7:0] sum
);

    reg [7:0] carry;

    always @(posedge clk) begin
        carry[0] <= a[0] & b[0];
        sum[0] <= a[0] ^ b[0];
        for (i = 1; i < 8; i = i + 1) begin
            carry[i] <= a[i] & b[i] | a[i] & carry[i-1] | b[i] & carry[i-1];
            sum[i] <= a[i] ^ b[i] ^ carry[i-1];
        end
    end

endmodule

