  assign NOT_SEL = ~SEL;
  assign AND1 = A & NOT_SEL;
  assign AND2 = B & SEL;
  assign OR = AND1 | AND2;

  assign Y = OR;

endmodule

module sqrt_calculator (
  input signed [15:0] in,
  output signed [15:0] out
);

  reg signed [15:0] estimate;
  reg signed [15:0] next_estimate;
  reg signed [15:0] numerator;
  reg signed [15:0] denominator;
  reg [3:0] count;

  assign out = estimate;

  initial begin
    estimate = in;
    count = 0;
  end

  always @(*) begin
    numerator = in;
    denominator = estimate;
    next_estimate = (numerator/denominator + denominator)/2;

    if (next_estimate == estimate) begin
      count = count + 1;
    end else begin
      count = 0;
    end

    estimate = next_estimate;
  end

  // Stop the loop after 10 iterations
  // This is an arbitrary number and can be adjusted for different levels of accuracy
  // The loop can also be stopped based on a threshold value for the difference between the current and next estimate
  // or based on the number of significant digits required
  always @(posedge clk) begin
    if (count == 10) begin
      $display("Square root of %d is %d", in, estimate);
      $finish;
    end
  end

endmodule

module top_module (
    input clk,
    input reset, // Synchronous active-high reset
    input d, // Input for the shift register
    output [3:0] q, // Output from the functional module
    output [2:0] shift_register // Output from the shift register
);

    reg [3:0] counter = 4'b0000;
    reg [2:0] shift_reg = 3'b000;
    wire [3:0] sum;

    // Counter module
    always @(posedge clk) begin
        if (reset) begin
            counter <= 4'b0000;
        end else begin
            counter <= counter + 1;
        end
    end

    // Shift register module
    always @(posedge clk) begin
        shift_reg <= {shift_reg[1:0], d};
    end

    // Functional module
    always @(posedge clk) begin
        sum <= counter + shift_reg;
    end

    assign q = sum;
    assign shift_register = shift_reg;

endmodule

module encoder_16to4 (
    input [15:0] I,
    output reg [1:0] A,
    output reg [1:0] B
);

reg [15:0] stage1_reg;
reg [3:0] stage2_reg;
reg [1:0] stage3_reg;

always @(posedge clk) begin
    stage1_reg <= I;
end

always @(posedge clk) begin
    stage2_reg <= {stage1_reg[15], stage1_reg[14], stage1_reg[13], stage1_reg[12], stage1_reg[11], stage1_reg[10], stage1_reg[9], stage1_reg[8], stage1_reg[7], stage1_reg[6], stage1_reg[5], stage1_reg[4], stage1_reg[3], stage1_reg[2], stage1_reg[1], stage1_reg[0]};
end

always @(posedge clk) begin
    case(stage2_reg)
        16'h0001: stage3_reg <= 2'b00;
        16'h0002: stage3_reg <= 2'b01;
        16'h0004: stage3_reg <= 2'b10;
        16'h0008: stage3_reg <= 2'b11;
        default: stage3_reg <= 2'b00;
    endcase
end

always @(posedge clk) begin
    A <= stage3_reg[1];
    B <= stage3_reg[0];
end

endmodule

module shift_register (
    input CLK,
    input SHIFT,
    input LOAD,
    input [15:0] DATA_IN,
    input mode,
    output reg [15:0] DATA_OUT
);

reg [15:0] reg1, reg2, reg3, reg4;

always @(posedge CLK) begin
    if (LOAD) begin
        reg1 <= DATA_IN;
        reg2 <= reg1;
        reg3 <= reg2;
        reg4 <= reg3;
    end else if (SHIFT) begin
        if (mode == 1'b0) begin
            reg1 <= {reg2[14:0], 1'b0};
            reg2 <= {reg3[14:0], 1'b0};
            reg3 <= {reg4[14:0], 1'b0};
            reg4 <= {DATA_OUT[14:0], 1'b0};
        end else begin
            reg1 <= {reg2[14:0], 1'b1};
            reg2 <= {reg3[14:0], 1'b1};
            reg3 <= {reg4[14:0], 1'b1};
            reg4 <= {DATA_OUT[14:0], 1'b1};
        end
    end
end

assign DATA_OUT = reg4;

endmodule

