assign lcd_cs = 1'b1;
assign lcd_rs = 1'b0;
assign lcd_wr = 1'b0;
assign lcd_rd = 1'b0;
assign lcd_bl_ctr = 1'b1;

// Define the signals for the LED display
assign display_number = test_addr + 6'd1;
assign display_addr = display_number - 6'd1;

// Define the signals for the register file display
always @(posedge clk) begin
    if (!resetn) begin
        raddr1 <= 5'd0;
        raddr2 <= 5'd0;
        waddr <= 5'd0;
        wdata <= 32'd0;
    end else begin
        if (input_valid) begin
            case (input_sel)
                2'b00: raddr1 <= input_value[4:0];
                2'b01: raddr2 <= input_value[4:0];
                2'b10: waddr <= input_value[4:0];
                2'b11: wdata <= input_value;
            endcase
        end
    end
end

// Define the signals for the LCD display
always @(posedge clk) begin
    if (!resetn) begin
        display_valid <= 1'b0;
        display_name <= 40'd0;
        display_value <= 32'd0;
    end else begin
        if (display_number > 6'd6 && display_number < 6'd39) begin
            display_valid <= 1'b1;
            display_name[39:16] <= "REG";
            display_name[15:8] <= {4'b0011, 3'b000, test_addr[4]};
