    output y
);

    wire ab, cd, abcd;

    and2 #(.delay(1)) and1 (ab, a, b);
    and2 #(.delay(1)) and2 (cd, c, d);
    and2 #(.delay(1)) and3 (abcd, ab, cd);
    assign y = abcd;

endmodule

module calculator(
    input clk,
    input rst,
    input [7:0] A,
    input [7:0] B,
    output reg [7:0] out_add,
    output reg [7:0] out_sub,
    output reg [7:0] out_mul,
    output reg [7:0] out_div
);

    reg [7:0] result;

    always @(posedge clk) begin
        if(rst) begin
            out_add <= 0;
            out_sub <= 0;
            out_mul <= 0;
            out_div <= 0;
        end
        else begin
            // Addition
            result = A + B;
            out_add <= result;

            // Subtraction
            result = A - B;
            out_sub <= result;

            // Multiplication
            result = A * B;
            out_mul <= result;

            // Division
            if(B == 0) begin
                out_div <= 8'hFF; // Division by zero
            end
            else begin
                result = A / B;
                out_div <= result;
            end
        end
    end
endmodule

module rotator(
    input clk,
    input load,
    input [1:0] ena,
    input [99:0] data,
    output reg [99:0] q);

    reg [99:0] shift_reg;
    reg [5:0] shift_amt;

    always @(posedge clk) begin
        if(load) begin
            shift_reg <= data;
            shift_amt <= 0;
        end else begin
            if(ena == 2'b00) begin
                shift_reg <= shift_reg;
                shift_amt <= shift_amt;
            end else if(ena == 2'b01) begin
                shift_reg <= {shift_reg[98:0], shift_reg[99]};
                shift_amt <= shift_amt + 1;
            end else if(ena == 2'b10) begin
                shift_reg <= {shift_reg[0], shift_reg[99:1]};
                shift_amt <= shift_amt - 1;
            end
        end
    end

    assign q = shift_reg;

endmodule

