module modulo_operator (
  input [31:0] dividend,
  input [31:0] divisor,
  output reg [31:0] remainder
);

always @(*) begin
  if (divisor == 0) begin
    remainder = 0;
  end else begin
    remainder = dividend % divisor;
  end
end

endmodule

module logic_expression(
    input A,
    input B,
    input C,
    input D,
    input E,
    output X
    );

    wire w1, w2, w3, w4, w5, w6, w7, w8, w9, w10, w11, w12;

    assign w1 = ~A & ~B & ~C & D & ~E;
    assign w2 = ~A & ~B & ~C & D & E;
    assign w3 = ~A & ~B & C & ~D & E;
    assign w4 = ~A & ~B & C & D & E;
    assign w5 = ~A & B & ~C & ~D & E;
    assign w6 = ~A & B & ~C & D & E;
    assign w7 = ~A & B & C & ~D & E;
    assign w8 = A & ~B & ~C & ~D & E;
    assign w9 = A & ~B & ~C & D & E;
    assign w10 = A & ~B & C & D & E;
    assign w11 = A & B & C & ~D & E;
    assign w12 = A & B & C & D & E;

    assign X = w1 | w2 | w3 | w4 | w5 | w6 | w7 | w8 | w9 | w10 | w11 | w12;

endmodule

module mux_4to1(
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [1:0] sel,
    output [3:0] result
);

wire [3:0] sel_0, sel_1, sel_2, sel_3;

assign sel_0 = (sel == 2'b00) ? data0 : 4'b0000;
assign sel_1 = (sel == 2'b01) ? data1 : 4'b0000;
assign sel_2 = (sel == 2'b10) ? data2 : 4'b0000;
assign sel_3 = (sel == 2'b11) ? data3 : 4'b0000;

assign result = sel_0 | sel_1 | sel_2 | sel_3;

endmodule

module CountOnes (
    /* Input ports */
    in,
    /* Output ports */
    out
);

input [7:0] in;
output [3:0] out;

integer i;
reg [3:0] count;

always @ (*) begin
    count = 0;
    for (i = 0; i < 8; i = i + 1) begin
        if (in[i] == 1) begin
            count = count + 1;
        end
    end
    out = count;
end

endmodule

module full_adder_4bit(
    input [3:0] A,
    input [3:0] B,
    input CIN,
    output [3:0] SUM,
    output COUT
);

    wire [3:0] sum;
    wire carry1, carry2, carry3;

    sky130_fd_sc_ls__fa fa1(.A(A[0]), .B(B[0]), .CIN(CIN), .SUM(sum[0]), .COUT(carry1));
    sky130_fd_sc_ls__fa fa2(.A(A[1]), .B(B[1]), .CIN(carry1), .SUM(sum[1]), .COUT(carry2));
    sky130_fd_sc_ls__fa fa3(.A(A[2]), .B(B[2]), .CIN(carry2), .SUM(sum[2]), .COUT(carry3));
    sky130_fd_sc_ls__fa fa4(.A(A[3]), .B(B[3]), .CIN(carry3), .SUM(sum[3]), .COUT(COUT));

