module binary_to_bcd_converter (
  input [n-1:0] bin,
  output [(n/4)*8-1:0] bcd
);

parameter n = 16; // number of bits in the binary number

// Define a function to convert a 4-bit binary number to BCD
function [7:0] bin_to_bcd;
  input [3:0] bin_num;
  begin
    case (bin_num)
      4'b0000: bin_to_bcd = 8'b00000001;
      4'b0001: bin_to_bcd = 8'b00000010;
      4'b0010: bin_to_bcd = 8'b00000100;
      4'b0011: bin_to_bcd = 8'b00000110;
      4'b0100: bin_to_bcd = 8'b00001000;
      4'b0101: bin_to_bcd = 8'b00001001;
      4'b0110: bin_to_bcd = 8'b00001100;
      4'b0111: bin_to_bcd = 8'b00001110;
      4'b1000: bin_to_bcd = 8'b00010000;
      4'b1001: bin_to_bcd = 8'b00010001;
      4'b1010: bin_to_bcd = 8'b00010100;
      4'b1011: bin_to_bcd = 8'b00010110;
      4'b1100: bin_to_bcd = 8'b00011000;
      4'b1101: bin_to_bcd = 8'b00011001;
      4'b1110: bin_to_bcd = 8'b00011100;
      4'b1111: bin_to_bcd = 8'b00011110;
      default: bin_to_bcd = 8'b00000000;
    endcase
  end
endfunction

// Define a loop to convert each group of 4 bits to BCD
genvar i;
generate
  for (i = 0; i < n/4; i = i + 1) begin : bcd_conversion
    assign bcd[i*8 + 7:i*8] = bin_to_bcd(bin[i*4 + 3:i*4]);
  end
endgenerate

endmodule

module alt_vipvfr131_common_avalon_mm_slave
  #(parameter
    AV_ADDRESS_WIDTH = 5,
    AV_DATA_WIDTH = 16,
    NO_OUTPUTS = 1,
    NO_INTERRUPTS = 1,  // NO_INTERRUPTS < AV_DATA_WIDTH!!!
    NO_REGISTERS = 4,
    ALLOW_INTERNAL_WRITE = 0) // writing to registers internally allowed or not
  (
  	input   wire                                        rst,
    input   wire                                        clk,

    // control
    input   wire [AV_ADDRESS_WIDTH-1:0]                 av_address,
    input   wire                                        av_read,
    output  reg  [AV_DATA_WIDTH-1:0]                    av_readdata,
    input   wire                                        av_write,
    input   wire [AV_DATA_WIDTH-1:0]                    av_writedata,
    output	   																					av_irq,

    // internal
    output  reg                                         enable,
    input																								clear_enable, // clear go bit from internally
    output  reg  [NO_REGISTERS-1:0]                     triggers,
    output  wire [(AV_DATA_WIDTH * NO_REGISTERS)-1:0]   registers,
    input   wire [(AV_DATA_WIDTH * NO_REGISTERS)-1:0]   registers_in,
    input   wire [NO_REGISTERS-1:0]                     registers_write,
    input   wire [NO_INTERRUPTS-1:0] 										interrupts,
    input   wire [NO_OUTPUTS-1:0]                       stopped);

	wire global_stopped;
	wire clear_interrupts;
	wire [NO_REGISTERS-1:0] triggers_nxt;
	reg  [AV_DATA_WIDTH-1:0] internal_registers[NO_REGISTERS-1:0];
	reg  [AV_DATA_WIDTH-1:0] interrupt_register;
	reg  [NO_INTERRUPTS-1:0] interrupt_enables;

	assign global_stopped = &stopped;
	assign clear_interrupts = av_write && (av_address == 2);  // clear selected interrupts when writing to interrupt register

	// Interrupt register implemenation
	generate
		genvar j;
		for (j = 0; j < AV_DATA_WIDTH; j = j+1) begin : interrupt_reg_loop
			always @(posedge clk or posedge rst)
				if (rst)
      		interrupt_register[j] <= 1'b0;
				else if (j <= NO_INTERRUPTS & j > 0)	
					interrupt_register[j] <= clear_interrupts ? interrupt_register[j] & ~av_writedata[j] :  // clear selected interrupts
																  	 interrupt_enables[j-1] ? interrupt_register[j] | interrupts[j-1] : 1'b0; // write enabled interrupts
		end
	endgenerate

	always @ (posedge clk or posedge rst) begin
    if(rst) begin
      enable <= 1'b0;
      interrupt_enables <= {NO_INTERRUPTS{1'b0}};
      av_readdata <= {AV_DATA_WIDTH{1'b0}};
    end else begin          
      if (clear_enable) begin
      	enable <= 1'b0;
      end
      if(av_write && (av_address == 0)) begin
        enable <= av_writedata[0];
        interrupt_enables <= av_writedata[NO_INTERRUPTS:1];
      end

  		if(av_read) begin
    		case(av_address)
   	  		0: av_readdata <= {{(AV_DATA_WIDTH-NO_INTERRUPTS-1){1'b0}}, interrupt_enables, enable};
      		1: av_readdata <= {{AV_DATA_WIDTH-1{1'b0}}, global_stopped};
       	  2: av_readdata <= {{(AV_DATA_WIDTH-NO_INTERRUPTS-1){1'b0}}, interrupt_register[NO_REGISTERS:1], 1'b0}; // bit 0 unused
       	  default: av_readdata <= internal_registers[av_address - 3];
      	endcase
    	end    
  	end
  end

	// av_irq is high if any of the individual enabled interrupts are high
	assign av_irq = |interrupt_register[NO_REGISTERS:1]; // bit 0 of Interrupt register unused

	// Register implementation
	generate
    genvar i;
    for(i = 0; i < NO_REGISTERS; i = i+1) begin : register_loop
      assign triggers_nxt[i] = (av_write && av_address == i + 3);
      localparam base_address = i * AV_DATA_WIDTH;
      assign registers[base_address + AV_DATA_WIDTH - 1:base_address] = internal_registers[i];

      // registers can be written to from master (av_writedata) or (if ALLOW_INTERNAL_WRITE = 1) from internal side (registers_in)
      always @ (posedge clk or posedge rst) begin
        if(rst) begin
          internal_registers[i] <= {AV_DATA_WIDTH{1'b0}};
          triggers[i] <= 1'b0;
        end else begin
          if(triggers_nxt[i]) begin // master has priority to write into registers
            internal_registers[i] <= av_writedata;
            triggers[i] <= triggers_nxt[i];
          end else if (ALLOW_INTERNAL_WRITE == 1 && registers_write[i]) begin // update from internal side only if master not writing at same time!
        		internal_registers[i] <= registers_in[base_address + AV_DATA_WIDTH - 1:base_address];
        		triggers[i] <= 1'b0; // if triggers[i] is 1 then av_writedata instead of register_in will have been written
          end         
        end
      end
    end
	endgenerate

endmodule

module i2c_master (
  input SCL,
  input SDA,
  input [7:0] ADDR,
  input [7:0] DATA,
  input RD_WR,
  output ACK,
  output BUS_BUSY,
  output [7:0] DATA_OUT
);

  reg [7:0] reg_addr;
  reg [7:0] reg_data;
  reg [2:0] state;
  wire SDA_out;
  reg SDA_reg;
  reg ACK_reg;
  reg BUS_BUSY_reg;

  assign SDA_out = (state == 0 && !BUS_BUSY_reg) ? 1'b0 : SDA_reg;

  always @(posedge SCL) begin
    case (state)
      0: begin // Start condition
        BUS_BUSY_reg <= 1'b1;
        SDA_reg <= 1'b0;
        state <= 1;
      end
      1: begin // Send slave address and read/write control bit
        SDA_reg <= ADDR[7];
        reg_addr <= ADDR;
        state <= 2;
      end
      2: begin // Send data to be transmitted or receive data from slave device
        if (RD_WR) begin // Write operation
          SDA_reg <= DATA[7];
          reg_data <= DATA;
          state <= 3;
        end else begin // Read operation
          SDA_reg <= 1'b1;
          state <= 4;
        end
      end
      3: begin // Send data to be transmitted
        SDA_reg <= reg_data[6];
        reg_data <= reg_data << 1;
        state <= (reg_data == 0) ? 5 : 3;
      end
      4: begin // Receive data from slave device
        reg_data <= {reg_data[6:0], SDA};
        state <= 4;
      end
      5: begin // Generate stop condition
        BUS_BUSY_reg <= 1'b0;
        SDA_reg <= 1'b0;
        state <= 0;
      end
    endcase
  end

  assign ACK = ACK_reg;
  assign BUS_BUSY = BUS_BUSY_reg;
  assign DATA_OUT = reg_data;

  always @(negedge SCL) begin
    if (state == 2 && !RD_WR) begin // Send ACK
      ACK_reg <= 1'b0;
      state <= 4;
    end else if (state == 4 && RD_WR) begin // Receive ACK
      ACK_reg <= ~SDA;
      state <= 3;
    end else begin
      ACK_reg <= 1'b1;
    end
  end

endmodule


module i2c_slave (
  input SCL,
  input SDA,
  output ACK,
  output [7:0] DATA_OUT
);

  reg [7:0] reg_data;
  reg [2:0] state;
  reg SDA_reg;
  reg ACK_reg;

  assign DATA_OUT = reg_data;

  always @(posedge SCL) begin
    if (state == 0 && SDA == 1'b0) begin // Start condition
      state <= 1;
    end else if (state == 1) begin // Receive slave address and read/write control bit
      if (SDA == 1'b1) begin // Read operation
        state <= 3;
      end else begin // Write operation
        state <= 2;
      end
    end else if (state == 2) begin // Receive data from master device
      reg_data <= {reg_data[6:0], SDA};
      state <= 2;
    end else if (state == 3) begin // Send data to master device
      SDA_reg <= reg_data[7];
      reg_data <= reg_data << 1;
      state <= (reg_data == 0) ? 4 : 3;
    end else if (state == 4) begin // Generate ACK
      ACK_reg <= 1'b0;
      state <= 1;
    end
  end

  assign ACK = ACK_reg;

  always @(negedge SCL) begin
    SDA_reg <= (state == 2) ? ACK : SDA;
    ACK_reg <= 1'b1;
  end

endmodule

module fsm_traffic_light_control (
  input clk,
  input reset,
  input pedestrian_button,
  output reg traffic_light,
  output reg pedestrian_light
);

  // define states
  localparam RED = 2'b00;
  localparam GREEN = 2'b01;
  localparam YELLOW = 2'b10;

  // define state register and next state logic
  reg [1:0] state, next_state;
  always @ (posedge clk) begin
    if (reset) begin
      state <= RED;
    end else begin
      state <= next_state;
    end
  end

  // define output logic
  always @ (*) begin
    case (state)
      RED: begin
        traffic_light = 1'b1;
        pedestrian_light = 1'b0;
      end
      GREEN: begin
        traffic_light = 1'b0;
        pedestrian_light = 1'b1;
      end
      YELLOW: begin
        traffic_light = 1'b0;
        pedestrian_light = 1'b1;
      end
    endcase
  end

  // define next state logic
  always @ (*) begin
    case (state)
      RED: begin
        next_state = GREEN;
        if (pedestrian_button) begin
          next_state = YELLOW;
        end
      end
      GREEN: begin
        next_state = YELLOW;
        if (pedestrian_button) begin
          next_state = YELLOW;
        end else if (clk % 30 == 0) begin
          next_state = RED;
        end
      end
      YELLOW: begin
        next_state = RED;
        if (pedestrian_button) begin
          next_state = YELLOW;
        end
      end
    endcase
  end

endmodule

module spi_master (
  input rst,
  input clk,
  input cs,
  input [7:0] din,
  output [7:0] dout
);

  reg [7:0] tx_data;
  reg [7:0] rx_data;
  reg [2:0] state;
  wire sclk;

  assign sclk = clk;

  always @(posedge clk) begin
    if (rst) begin
      state <= 3'b000;
      tx_data <= 8'h00;
      rx_data <= 8'h00;
    end
    else begin
      case (state)
        3'b000: begin //Idle state
          if (!cs) begin
            state <= 3'b001;
            tx_data <= din;
          end
        end
        3'b001: begin //Data transmit state
          dout <= tx_data;
          state <= 3'b010;
        end
        3'b010: begin //Data receive state
          rx_data <= din;
          state <= 3'b011;
        end
        3'b011: begin //Data transmit state
          dout <= 8'h00;
          state <= 3'b000;
        end
      endcase
    end
  end

endmodule

//Slave Block
module spi_slave (
  input rst,
  input clk,
  input cs,
  output [7:0] dout,
  input [7:0] din
);

  reg [7:0] tx_data;
  reg [7:0] rx_data;
  reg [2:0] state;
  wire sclk;

  assign sclk = clk;

  always @(posedge clk) begin
    if (rst) begin
      state <= 3'b000;
      tx_data <= 8'h00;
      rx_data <= 8'h00;
    end
    else begin
      case (state)
        3'b000: begin //Idle state
          if (!cs) begin
            state <= 3'b010;
          end
        end
        3'b001: begin //Data transmit state
          dout <= tx_data;
          state <= 3'b010;
        end
        3'b010: begin //Data receive state
          rx_data <= din;
          state <= 3'b011;
        end
        3'b011: begin //Data transmit state
          tx_data <= rx_data;
          dout <= 8'h00;
          state <= 3'b000;
        end
      endcase
    end
  end

endmodule

