module booth_sequential_multiplier (
    input clk,
    input reset,
    input [7:0] multiplicand,
    input [7:0] multiplier,
    output reg [15:0] product
);

reg [3:0] m;
reg [7:0] a, s;

wire [3:0] multiplier_high;
wire [3:0] multiplicand_high;

Booth_multiplier booth_multiplier(
    .clk(clk),
    .reset(reset),
    .multiplier(multiplier_high),
    .multiplicand(multiplicand_high),
    .m(m)
);

always @(*) begin
    multiplier_high = multiplier[7:4];
    multiplicand_high = multiplicand[7:4];
end

always @(posedge clk) begin
    if (reset) begin
        product <= 0;
        m <= 0;
        a <= 0;
        s <= 0;
    end else begin
        if (m == 0 && s == 0) begin
            a <= 0;
            s <= multiplier[3:0];
        end else if (m == 1 && s == 1) begin
            a <= a + multiplicand[3:0];
            s <= s + multiplier[3:0];
        end else if (m == 2 && s == 2) begin
            a <= a - multiplicand[3:0];
            s <= s - multiplier[3:0];
        end else if (m == 3 && s == 3) begin
            a <= a;
            s <= s;
        end else if (m == 0 && s == 1) begin
            a <= a + multiplicand[3:0];
            s <= s - multiplier[3:0];
        end else if (m == 1 && s == 0) begin
            a <= a - multiplicand[3:0];
            s <= s + multiplier[3:0];
        end else if (m == 2 && s == 1) begin
            a <= a + multiplicand[3:0];
            s <= s + multiplier[3:0];
        end else if (m == 3 && s == 2) begin
            a <= a - multiplicand[3:0];
            s <= s - multiplier[3:0];
        end
        m <= s[0];
        s <= {s[2:0], s[3]};
        product <= {a, s};
    end
end

endmodule

module Booth_multiplier (
    input clk,
    input reset,
    input [3:0] multiplier,
    input [3:0] multiplicand,
    output reg [3:0] m
);

reg [3:0] ac;

always @(posedge clk) begin
    if (reset) begin
        ac <= 0;
        m <= 0;
    end else begin
        case ({ac[3], multiplier}) 
            2'b00_000: ac <= {ac[2:0], multiplicand, 1'b0};
            2'b01_000: ac <= {ac[2:0], multiplicand, 1'b0} - multiplicand;
            2'b10_000: ac <= {ac[2:0], multiplicand, 1'b0} + multiplicand;
            2'b11_000: ac <= {ac[2:0], multiplicand, 1'b0};
        endcase
        m <= ac[3:0];
        ac <= {ac[2:0], ac[3]};
    end
end

endmodule

module multiplier_alu_top (
    input [7:0] A,
    input [7:0] B,
    input [2:0] OP,
    output reg [7:0] final_output
);

    // 8-bit multiplier module
    wire [15:0] mult_result;
    multiplier_8bit mult_inst (
        .A(A),
        .B(B),
        .P(mult_result)
    );

    // 4-bit ALU module
    wire [3:0] alu_result;
    alu_4bit alu_inst (
        .A(mult_result[7:4]),
        .B(A),
        .OP(OP),
        .Y(alu_result)
    );

    // Additive functional module
    always @ (mult_result or alu_result)
    begin
        final_output <= mult_result[15:8] + alu_result;
    end

endmodule

module multiplier_8bit (
    input [7:0] A,
    input [7:0] B,
    output reg [15:0] P
);

    always @ (A or B)
    begin
        P = 0;
        for (i = 0; i < 8; i = i + 1)
        begin
            if (B[i] == 1)
            begin
                P = P + (A << i);
            end
        end
    end

endmodule

module alu_4bit (
    input [3:0] A,
    input [3:0] B,
    input [2:0] OP,
    output reg [3:0] Y
);

    always @ (A or B or OP)
    begin
        case (OP)
            3'b000: Y = A + B; // addition
            3'b001: Y = A - B; // subtraction
            3'b010: Y = A & B; // bitwise AND
            3'b011: Y = A | B; // bitwise OR
            3'b100: Y = A ^ B; // bitwise XOR
            3'b101: Y = A << 1; // arithmetic shift left
            default: Y = 0;
        endcase
    end

endmodule

