module glitch_filter(
    input clk,
    input s_in,
    output reg s_out
);

    reg [1:0] state; // 2-bit state variable
    parameter IDLE = 2'b00, HIGH = 2'b01, LOW = 2'b10;
    // IDLE - initial state
    // HIGH - s_in is high for 4 or more clock cycles
    // LOW - s_in is low for 4 or more clock cycles

    always @(posedge clk) begin
        case(state)
            IDLE: begin
                if(s_in) begin
                    state <= HIGH;
                    s_out <= 1;
                end else begin
                    state <= LOW;
                    s_out <= 0;
                end
            end

            HIGH: begin
                if(s_in) begin
                    s_out <= 1;
                    if(counter_high == 3) begin
                        state <= HIGH;
                    end else begin
                        counter_high <= counter_high + 1;
                        state <= HIGH;
                    end
                end else begin
                    counter_high <= 0;
                    state <= LOW;
                end
            end

            LOW: begin
                if(!s_in) begin
                    s_out <= 0;
                    if(counter_low == 3) begin
                        state <= LOW;
                    end else begin
                        counter_low <= counter_low + 1;
                        state <= LOW;
                    end
                end else begin
                    counter_low <= 0;
                    state <= HIGH;
                end
            end
        endcase
    end

    // reset counters when input signal changes
    always @(posedge clk) begin
        if(s_in != s_in_prev) begin
            counter_low <= 0;
            counter_high <= 0;
        end
        s_in_prev <= s_in;
    end

    // initialize variables
    integer counter_low = 0;
    integer counter_high = 0;
    reg s_in_prev = 0;

endmodule

module FP16RMulS0Of2(
 input 	       clk,
 input 	       rst,
 input [15:0]  arg_0,
 input [15:0]  arg_1,
 output        ret_0,
 output [4:0]  ret_1,
 output [4:0]  ret_2,
 output [11:0] ret_3);

   wire        s0;
   wire        s1;
   wire [4:0]  e0;
   wire [4:0]  e1;
   wire [9:0]  f0;
   wire [9:0]  f1;
   wire [10:0] ff0;
   wire [10:0] ff1;
   wire [21:0] z;
   wire [11:0] zz;

   assign s0 = arg_0[15:15];
   assign s1 = arg_1[15:15];
   assign e0 = arg_0[14:10];
   assign e1 = arg_1[14:10];
   assign f0 = arg_0[9:0];
   assign f1 = arg_1[9:0];

   // sign
   assign ret_0 = s0 ^ s1;
   // exponent
   assign ret_1 = e0;
   assign ret_2 = e1;

   assign ff0 = {(e0 == 0 ? 1'b0 : 1'b1), f0};
   assign ff1 = {(e1 == 0 ? 1'b0 : 1'b1), f1};

   assign z = ff0 * ff1;
   assign zz = z[21:10];

   // fraction
   assign ret_3 = zz;

   // normalize fraction
   assign {zz, ret_1} = (zz[10] == 1'b1) ? {zz[9:0], ret_1 + 1} : {zz[8:0], ret_1};

