module top_module (
    input clk,
    input reset,
    input [31:0] in,
    output rise,
    output down,
    output [1:0] state
);

reg [31:0] in_reg;
reg [31:0] in_delayed;
reg [31:0] in_delayed2;
wire rising_edge;
wire falling_edge;

assign rising_edge = in_delayed & ~in_delayed2;
assign falling_edge = ~in_delayed & in_delayed2;

assign rise = rising_edge;
assign down = falling_edge;

assign state = {in_delayed2, rising_edge | falling_edge};

always @(posedge clk) begin
    if (reset) begin
        in_reg <= 0;
        in_delayed <= 0;
        in_delayed2 <= 0;
    end else begin
        in_reg <= in;
        in_delayed <= in_reg;
        in_delayed2 <= in_delayed;
    end
end

endmodule

module refill_randomizer
  #(parameter BITS=7)
    (
     input clk,
     input rst,
     input full_in,
     output reg full_out
     );

   wire 	    feedback;
   reg 	    full_last;
   wire     full_deasserts;
   reg [BITS-1:0] shift_reg;
   reg [BITS-1:0] count;
   reg 	     delayed_fall;


   always @(posedge clk)
     full_last <= full_in;

   assign    full_deasserts = full_last & ~full_in;

   // LFSR
   always @(posedge clk)
     if (rst)
       shift_reg <= {BITS{1'b1}};
     else
       if (full_deasserts)
	 shift_reg <= {shift_reg[BITS-2:0],feedback};

   assign    feedback = ^(shift_reg & {BITS{1'b1}});

   always @(posedge clk)
     if (rst)
       begin
	  count <= 1;
	  delayed_fall  <= 1;
       end
     else if (full_deasserts)
       begin
	  count <= shift_reg;
	  delayed_fall <= 1;
       end
     else if (count == 1)
       begin
	  count <= 1;
	  delayed_fall <= 0;
       end
     else
       begin
	  count <= count - 1;
	  delayed_fall <= 1;
       end

   // Full_out goes instantly high if full_in does. However its fall is delayed.
   always @(posedge clk)
     if (full_in == 1 || full_last == 1 || delayed_fall == 1)
       full_out <= 1;
     else
       full_out <= 0;

endmodule

