module binary_gcd (
    input [3:0] A,
    input [3:0] B,
    output reg [3:0] GCD
);

reg [3:0] remainder;

always @* begin
    if (A > B) begin
        remainder = B;
        B = A;
        A = remainder;
    end
    while (B != 0) begin
        remainder = A % B;
        A = B;
        B = remainder;
    end
    GCD = A;
end

endmodule

