reg rst1_n, rst2_n, rst_out_n;

always @(posedge clk, negedge rst_in_n) begin
    if (!rst_in_n) begin
        rst_cnt <= 0;
        rst1_n <= 1'b0;
        rst2_n <= 1'b0;
        rst_out_n <= 1'b0;
    end else begin
        rst1_n <= 1'b1;
        rst2_n <= rst1_n;

        if (rst2_n && !rst_cnt[RST_CNT_SIZE]) begin
            rst_cnt <= rst_cnt + 1;
        end

        if (rst_cnt[RST_CNT_SIZE]) begin
            rst_out_n <= 1'b1;
        end
    end
end

endmodule

module axis_register #(
    parameter DATA_WIDTH = 32,
    parameter KEEP_ENABLE = 0,
    parameter KEEP_WIDTH = (DATA_WIDTH/8),
    parameter LAST_ENABLE = 0,
    parameter ID_ENABLE = 0,
    parameter ID_WIDTH = 8,
    parameter DEST_ENABLE = 0,
    parameter DEST_WIDTH = 8,
    parameter USER_ENABLE = 0,
    parameter USER_WIDTH = 1,
    parameter REG_TYPE = 1
)(
    input clk,
    input rst,
    input [DATA_WIDTH-1:0] s_axis_tdata,
    input [KEEP_WIDTH-1:0] s_axis_tkeep,
    input s_axis_tvalid,
    output s_axis_tready,
    input s_axis_tlast,
    input [ID_WIDTH-1:0] s_axis_tid,
    input [DEST_WIDTH-1:0] s_axis_tdest,
    input [USER_WIDTH-1:0] s_axis_tuser,
    output reg [DATA_WIDTH-1:0] m_axis_tdata,
    output reg [KEEP_WIDTH-1:0] m_axis_tkeep,
    output reg m_axis_tvalid,
    input m_axis_tready,
    output reg m_axis_tlast,
    output reg [ID_WIDTH-1:0] m_axis_tid,
    output reg [DEST_WIDTH-1:0] m_axis_tdest,
    output reg [USER_WIDTH-1:0] m_axis_tuser
);

reg [DATA_WIDTH-1:0] data_reg;
reg [KEEP_WIDTH-1:0] keep_reg;
reg last_reg;
reg [ID_WIDTH-1:0] id_reg;
reg [DEST_WIDTH-1:0] dest_reg;
reg [USER_WIDTH-1:0] user_reg;
reg [DATA_WIDTH-1:0] data_reg_async;

always @(posedge clk) begin
    if (rst) begin
        data_reg <= 'h0;
        keep_reg <= 'h0;
        last_reg <= 0;
        id_reg <= 'h0;
        dest_reg <= 'h0;
        user_reg <= 'h0;
        data_reg_async <= 'h0;
        m_axis_tvalid <= 0;
        m_axis_tlast <= 0;
        m_axis_tid <= 'h0;
        m_axis_tdest <= 'h0;
        m_axis_tuser <= 'h0;
    end else begin
        if (REG_TYPE == 1) begin // synchronous register
            data_reg <= s_axis_tdata;
            keep_reg <= s_axis_tkeep;
            last_reg <= s_axis_tlast;
            id_reg <= s_axis_tid;
            dest_reg <= s_axis_tdest;
            user_reg <= s_axis_tuser;
        end else begin // asynchronous register
            data_reg_async <= s_axis_tdata;
            keep_reg <= s_axis_tkeep;
            last_reg <= s_axis_tlast;
            id_reg <= s_axis_tid;
            dest_reg <= s_axis_tdest;
            user_reg <= s_axis_tuser;
        end
    end
end

always @(posedge clk) begin
    if (REG_TYPE == 1) begin // synchronous register
        m_axis_tdata <= data_reg;
    end else begin // asynchronous register
        m_axis_tdata <= data_reg_async;
    end
    m_axis_tkeep <= keep_reg;
    m_axis_tlast <= last_reg;
    m_axis_tid <= id_reg;
    m_axis_tdest <= dest_reg;
    m_axis_tuser <= user_reg;
    s_axis_tready <= m_axis_tready;
end

always @(posedge clk) begin
    if (m_axis_tready && m_axis_tvalid) begin
        data_reg <= m_axis_tdata;
        keep_reg <= m_axis_tkeep;
        last_reg <= m_axis_tlast;
        id_reg <= m_axis_tid;
        dest_reg <= m_axis_tdest;
        user_reg <= m_axis_tuser;
        m_axis_tvalid <= s_axis_tvalid;
    end else begin
        m_axis_tvalid <= s_axis_tvalid && s_axis_tready;
    end
end

endmodule

module udp_outbound_chain_tx
(
  input        c,
  input  [7:0] rxd,
  input        rxdv,
  output [7:0] txd,
  output       txdv
);

  localparam SW = 5, CW = 5;
  reg [CW+SW-1:0] ctrl;
  wire [SW-1:0] state;
  wire [SW-1:0] next_state = ctrl[SW+CW-1:CW];
  r #(SW) state_r
    (.c(c), .rst(1'b0), .en(1'b1), .d(next_state), .q(state));

  localparam ST_IDLE           = 5'h0;
  localparam ST_PROTO_VER      = 5'h1;
  localparam ST_HOP_COUNT_LOW  = 5'h2;
  localparam ST_HOP_COUNT_HIGH = 5'h3;
  localparam ST_PAYLOAD        = 5'h4;
  localparam ST_POSTLUDE       = 5'h5;
  localparam ST_DISCARD        = 5'h6;

  wire rx_cnt_rst;
  wire [10:0] rx_cnt;
  r #(11) rx_cnt_r
    (.c(c), .rst(rx_cnt_rst), .en(1'b1), .d(rx_cnt+1'b1), .q(rx_cnt));
  assign rx_cnt_rst = ctrl[0];

  wire [7:0] rxd_i = state == ST_HOP_COUNT_LOW ? rxd + 1'b1 : rxd;

  wire [7:0] prev_rxd;
  r #(8) prev_rxd_r(.c(c), .rst(1'b0), .en(rxdv), .d(rxd), .q(prev_rxd));

  wire [7:0] rxd_d1, rxd_d2;
  d1 #(8) rxd_d1_r(.c(c), .d(rxd_i ), .q(rxd_d1));
  d1 #(8) rxd_d2_r(.c(c), .d(rxd_d1), .q(rxd_d2));
  wire [15:0] rx_16bit = { rxd, prev_rxd };

  wire [7:0] rx_hop_count;
  r #(8) rx_hop_count_r
    (.c(c), .rst(1'b0), .en(state == ST_PROTO_VER), 
     .d(rxd), .q(rx_hop_count));

  assign txdv = ctrl[1];
  assign txd = rxd_d2;

  always @* begin
    case (state)
      ST_IDLE:
        if (rxdv)                 ctrl = { ST_PROTO_VER     , 5'b00000 };
        else                      ctrl = { ST_IDLE          , 5'b00001 };
      ST_PROTO_VER: 
        if (rxdv)
          if (rx_16bit == 16'h4321)    ctrl = { ST_HOP_COUNT_LOW , 5'b00001 };
          else                         ctrl = { ST_DISCARD       , 5'b00000 };
        else                      ctrl = { ST_PROTO_VER     , 5'b00001 };
      ST_HOP_COUNT_LOW:           
        if (rxdv)                 ctrl = { ST_HOP_COUNT_HIGH, 5'b00011 };
        else                      ctrl = { ST_HOP_COUNT_LOW , 5'b00001 };
      ST_HOP_COUNT_HIGH:          ctrl = { ST_PAYLOAD       , 5'b00011 };
      ST_PAYLOAD:
        if (~rxdv)                ctrl = { ST_POSTLUDE      , 5'b00011 };
        else                      ctrl = { ST_PAYLOAD       , 5'b00010 };
      ST_POSTLUDE:
        if (rx_cnt == 16'h1)      ctrl = { ST_IDLE          , 5'b00000 };
        else                      ctrl = { ST_POSTLUDE      , 5'b00010 };
      ST_DISCARD:
        if (~rxdv)                ctrl = { ST_IDLE          , 5'b00000 };
        else                      ctrl = { ST_DISCARD       , 5'b00000 };
      default:                    ctrl = { ST_IDLE          , 5'b00000 };
    endcase
  end

endmodule

module stratixiv_ddr_delay_chain_s (
        input clk, 
        input [5 : 0] delayctrlin, 
        input [3 : 0] phasectrlin, 
        output delayed_clkout
);

parameter use_phasectrlin = "true";
parameter phase_setting   = 0;
parameter sim_buffer_intrinsic_delay  = 350;
parameter sim_buffer_delay_increment  = 10;
parameter phasectrlin_limit = 7;

// decoded counter
wire [5:0]  delayctrl_bin;

// cell delay
integer     acell_delay;
integer     delay_chain_len;
integer     clk_delay;
// int signals
reg         delayed_clk;

// filtering X/U etc.
wire  [5 : 0] delayctrlin_in;
wire  [3 : 0] phasectrlin_in;
assign delayctrlin_in[0] = (delayctrlin[0] === 1'b1) ? 1'b1 : 1'b0;
assign delayctrlin_in[1] = (delayctrlin[1] === 1'b1) ? 1'b1 : 1'b0;
assign delayctrlin_in[2] = (delayctrlin[2] === 1'b1) ? 1'b1 : 1'b0;
assign delayctrlin_in[3] = (delayctrlin[3] === 1'b1) ? 1'b1 : 1'b0;
assign delayctrlin_in[4] = (delayctrlin[4] === 1'b1) ? 1'b1 : 1'b0;
assign delayctrlin_in[5] = (delayctrlin[5] === 1'b1) ? 1'b1 : 1'b0;
assign phasectrlin_in[0] = (phasectrlin[0] === 1'b1) ? 1'b1 : 1'b0;
assign phasectrlin_in[1] = (phasectrlin[1] === 1'b1) ? 1'b1 : 1'b0;
assign phasectrlin_in[2] = (phasectrlin[2] === 1'b1) ? 1'b1 : 1'b0;
assign phasectrlin_in[3] = (phasectrlin[3] === 1'b1) ? 1'b1 : 1'b0;

stratixiv_ddr_gray_decoder m_delayctrl_in_dec(delayctrlin_in, delayctrl_bin);

always @(*) begin
    // cell
    acell_delay = sim_buffer_intrinsic_delay + delayctrl_bin * sim_buffer_delay_increment;

    // no of cells
    if (use_phasectrlin == "false")
        delay_chain_len = phase_setting;
    else
        delay_chain_len = (phasectrlin_in > phasectrlin_limit) ? 0 : phasectrlin_in;

    // total delay        - added extra 1 ps for resolving racing
    clk_delay = delay_chain_len * acell_delay  + 1;

    if ((use_phasectrlin == "true") && (phasectrlin_in > phasectrlin_limit))
        $display($time, " Warning: DDR phasesetting %m has invalid setting %b", phasectrlin_in);     
end

// delayed clock
always @(posedge clk)
    delayed_clk <= #(clk_delay) ~delayed_clk;  

assign  delayed_clkout = delayed_clk;

endmodule

module LCG (
  input clk,
  input rst,
  input start,
  output reg [31:0] rand
);

parameter a = 1103515245;
parameter c = 12345;
parameter m = 4294967296; // 2^32
parameter seed = 1;

reg [31:0] xn;
reg [31:0] xn_next;
reg [31:0] counter;
reg [31:0] scaled_rand;

always @(posedge clk) begin
  if (rst) begin
    xn <= seed;
    counter <= 0;
    scaled_rand <= 0;
  end
  else if (start) begin
    xn <= xn_next;
    xn_next <= (a * xn + c) % m;
    counter <= counter + 1;
    scaled_rand <= xn_next >> 1; // Scale to range of 0 to 1
  end
end

assign rand = (rst) ? seed >> 1 : scaled_rand;

endmodule

module controllerHdl_Reset_Delay_block
          (
           input CLK_IN,
           input reset,
           input enb_1_2000_0,
           input Reset_1,
           input signed [31:0] In,
           output signed [31:0] Out
          );

  wire signed [31:0] Constant1_out1;
  wire signed [31:0] Reset_Switch1_out1;
  reg signed [31:0] In_Delay_out1;
  wire signed [31:0] Constant_out1;
  wire signed [31:0] Reset_Switch_out1;

  assign Constant1_out1 = 32'sb00000000000000000000000000000000;
  assign Reset_Switch1_out1 = (Reset_1 == 1'b0 ? In : Constant1_out1);

  always @(posedge CLK_IN) begin
    if (reset == 1'b1) begin
      In_Delay_out1 <= 32'sb00000000000000000000000000000000;
    end
    else if (enb_1_2000_0) begin
      In_Delay_out1 <= Reset_Switch1_out1;
    end
  end

  assign Constant_out1 = 32'sb00000000000000000000000000000000;
  assign Reset_Switch_out1 = (Reset_1 == 1'b0 ? In_Delay_out1 : Constant_out1);

  assign Out = Reset_Switch_out1;

endmodule

module Key
(	input clk,
	input rst,

	input left,
	input right,
	input up,
	input down,

	output reg left_key_press,
	output reg right_key_press,
	output reg up_key_press,
	output reg down_key_press
);

	reg [31:0]clk_cnt;
	reg left_key_last;
	reg right_key_last;
	reg up_key_last;
