module top_module(
    input clk,
    input reset,      // Synchronous active-high reset
    input load,
    input [1:0] ena,
    output reg [103:0] q);

    reg [3:0] counter;
    reg [99:0] data;
    reg [99:0] rotated_data;
    reg [6:0] shift_amount;
    wire [103:0] final_output;

    // Binary counter
    always @(posedge clk) begin
        if (reset) begin
            counter <= 4'b0;
        end else if (counter == 4'b1111) begin
            counter <= 4'b0;
        end else begin
            counter <= counter + 1;
        end
    end

    // Rotator
    always @(posedge clk) begin
        if (reset) begin
            data <= 100'b0;
            rotated_data <= 100'b0;
            shift_amount <= 7'b0;
        end else if (load) begin
            data <= q[99:0];
            rotated_data <= data;
            shift_amount <= 7'b0;
        end else if (ena[1:0] == 2'b01) begin // Rotate left
            shift_amount <= {2'b0, ena[0], 4'b0};
            rotated_data <= {data[shift_amount], data[99:shift_amount]};
        end else if (ena[1:0] == 2'b10) begin // Rotate right
            shift_amount <= {2'b0, ena[0], 4'b0};
            rotated_data <= {data[99-shift_amount+1:99], data[0:99-shift_amount]};
        end
    end

    // Functional module
    always @(posedge clk) begin
        final_output <= {rotated_data, counter};
    end

    // Output
    assign q = final_output;

endmodule

