module state_machine(clk, rst_, ena_, rdy_,
    r0_din, r0_dout, r0_we_,
    immed, high);
    input clk;
    input rst_;
    input ena_;
    output rdy_;
    output[7:0] r0_din;
    input[7:0] r0_dout;
    output r0_we_;
    input[3:0] immed;
    input high;

    reg rdy_en;
    assign rdy_ = rdy_en ? 1'b0 : 1'bZ;
    reg r0_din_en;
    assign r0_din = r0_din_en ?
                        high ? {immed, r0_dout[3:0]} : {r0_dout[7:4], immed} :
                        8'bZ;
    reg r0_we_en;
    assign r0_we_ = r0_we_en ? 1'b0 : 1'bZ;
    reg [1:0] state;

    always @(negedge rst_ or posedge clk)
        if(!rst_) begin
            rdy_en <= 1;
            r0_din_en <= 0;
            r0_we_en <= 0;
            state <= 2'b00;
        end else if(!ena_) begin
            rdy_en <= 0;
            r0_din_en <= 1;
            r0_we_en <= 0;
            state <= 2'b01;
        end else if(state == 2'b01) begin
            rdy_en <= 0;
            r0_din_en <= 0;
            r0_we_en <= 1;
            state <= 2'b10;
        end else if(state == 2'b10) begin
            rdy_en <= 1;
            r0_din_en <= 0;
            r0_we_en <= 0;
            state <= 2'b00;
        end else begin
            rdy_en <= 1;
            r0_din_en <= 0;
            r0_we_en <= 0;
            state <= 2'b00;
        end

endmodule

