        if (MODE == 0) begin
            sum <= A + B + carry;
            carry <= (sum[16] == 1) ? 1'b1 : 1'b0;
            Q <= sum[15:0];
        end else begin
            diff <= A - B - carry;
            carry <= (diff[16] == 0) ? 1'b1 : 1'b0;
            Q <= diff[15:0];
        end
    end
end

