module async_fifo (
    aclr,
    data,
    rdclk,
    rdreq,
    wrclk,
    wrreq,
    q,
    wrusedw
);

input aclr;
input [138:0] data;
input rdclk;
input rdreq;
input wrclk;
input wrreq;
output [138:0] q;
output [7:0] wrusedw;

reg [138:0] mem [0:255];
reg [7:0] wr_ptr;
reg [7:0] rd_ptr;
reg [7:0] wr_used_bits;
reg [7:0] rd_used_bits;
wire [7:0] wr_unused_bits;
wire [7:0] rd_unused_bits;
wire [7:0] wr_next_ptr;
wire [7:0] rd_next_ptr;

assign wr_unused_bits = 139 - wr_used_bits;
assign rd_unused_bits = 139 - rd_used_bits;
assign wrusedw = wr_used_bits;

always @(posedge wrclk) begin
    if (wrreq) begin
        mem[wr_ptr][wr_used_bits +: wr_unused_bits] <= data[wr_unused_bits - 1 -: wr_unused_bits];
        mem[wr_ptr][wr_used_bits - 1 -: wr_unused_bits] <= data[wr_used_bits - 1 -: wr_unused_bits];
        wr_ptr <= wr_next_ptr;
        wr_used_bits <= wr_unused_bits;
    end
end

always @(posedge rdclk) begin
    if (rdreq) begin
        q <= mem[rd_ptr];
        rd_ptr <= rd_next_ptr;
        rd_used_bits <= rd_unused_bits;
    end
end

always @(posedge wrclk) begin
    wr_next_ptr <= wr_ptr + 1;
end

always @(posedge rdclk) begin
    rd_next_ptr <= rd_ptr + 1;
end

always @(posedge wrclk or posedge aclr) begin
    if (aclr) begin
        wr_ptr <= 0;
        wr_used_bits <= 0;
    end else if (wrreq && wr_unused_bits == 0) begin
        wr_ptr <= wr_next_ptr;
        wr_used_bits <= 0;
    end
end

always @(posedge rdclk or posedge aclr) begin
    if (aclr) begin
        rd_ptr <= 0;
        rd_used_bits <= 0;
    end else if (rdreq && rd_unused_bits == 0) begin
        rd_ptr <= rd_next_ptr;
        rd_used_bits <= 0;
    end
end

endmodule

module shift_register (
  input CLK,
  input RST,
  input SHIFT,
  input LOAD,
  input [7:0] DATA_IN,
  input DATA_IN_VALID,
  output reg [7:0] DATA_OUT,
  output reg DATA_OUT_VALID
);

  reg [7:0] shift_reg;

  always @(posedge CLK) begin
    if (RST) begin
      shift_reg <= 8'b0;
      DATA_OUT_VALID <= 1'b0;
    end
    else begin
      if (LOAD) begin
        shift_reg <= DATA_IN;
        DATA_OUT_VALID <= DATA_IN_VALID;
      end
      else if (SHIFT) begin
        shift_reg <= {shift_reg[6:0], shift_reg[7]};
        DATA_OUT_VALID <= 1'b1;
      end
      else begin
        DATA_OUT_VALID <= 1'b1;
      end
    end
    DATA_OUT <= shift_reg;
  end

endmodule

