    end else begin
        if (real_speed) begin
            cambio0 <= 5'd2;
            cambio1 <= 5'd4;
        end else begin
            if (uart_speed) begin
                cambio0 <= 5'd4;
                cambio1 <= 5'd8;
            end else begin
                cambio0 <= 5'd7;
                cambio1 <= 5'd15;
            end
        end
    end
end

// Flip-flop for generating ym_pm signal
always @(posedge clk or posedge rst) begin : ym_pm_ff
    if (rst) begin
        div_cnt <= 5'd0;
        ym_pm <= 1'b0;
    end else begin    
        if (div_cnt >= cambio1) begin
            ym_pm <= 1'b1;
            div_cnt <= 5'd0;
        end else begin
            if (div_cnt == cambio0) begin
                ym_pm <= 1'b0;
            end
            div_cnt <= div_cnt + 1'b1;
        end
    end
end

// Flip-flop for generating pm_counter signal
reg ultpm;
always @(posedge clk or posedge rst) begin : pm_counter_ff
    if (rst) begin
        pm_counter <= 32'd0;
        ultpm <= 1'b0;
    end else begin
        ultpm <= ym_pm;
        if (rst_counter) begin
            pm_counter <= 32'd0;
        end else begin
            if (irq_n && ym_pm && !ultpm) begin
                pm_counter <= pm_counter + 1'd1;        
            end
        end
    end
end

endmodule

module buffer (
    X,
    SLEEP,
    A,
    VPWR,
    VGND,
    VPB,
    VNB
);

    // Module ports
    output X;
    input SLEEP;
    input A;
    input VPWR;
    input VGND;
    input VPB;
    input VNB;

    // Local signals
    wire not_sleep;
    wire and_a_vpwr;
    wire pwrgood;
    wire buf_out;

    // Invert the SLEEP signal
    not #(1) not_sleep_inst (not_sleep, SLEEP);

    // AND the A and VPWR signals
    and #(1) and_a_vpwr_inst (and_a_vpwr, A, VPWR);

    // Generate the power good signal
    sky130_fd_sc_hdll__udp_pwrgood_pp$PG$S pwrgood_inst (
        .Y(pwrgood),
        .A(and_a_vpwr),
        .VPWR(VPB),
        .VGND(VNB),
        .S(not_sleep)
    );

    // Buffer the output
    buf #(1) buf_inst (buf_out, pwrgood);

    // Assign the output X
    assign X = (not_sleep & buf_out);

endmodule

module shift_register (
    input [3:0] data_in,
    input load,
    input shift,
    input reset,
    output [3:0] data_out
);

    reg [3:0] register;

    always @(posedge shift) begin
        if (reset) begin
            register <= 4'b0000;
        end else begin
            register <= {register[2:0], register[3]};
        end
    end

    always @(posedge load) begin
        if (load) begin
            register <= data_in;
        end
    end

    assign data_out = register;

endmodule

