module top_module(
    input [1023:0] in_mux,
    input [7:0] sel,
    output [3:0] out_mux,
    input [31:0] in_rev,
    output [31:0] out_rev,
    output reg [7:0] out_final,
    input clk,
    input reset
);

// 256-to-1 multiplexer with barrel shifter
reg [1023:0] shifted_input;
always @(*) begin
    case(sel)
        8'h00: shifted_input = in_mux;
        8'h01: shifted_input = {in_mux[1023:768], in_mux[767:512], in_mux[511:256], in_mux[255:0]};
        8'h02: shifted_input = {in_mux[1023:512], in_mux[511:0]};
        8'h03: shifted_input = {in_mux[1023:640], in_mux[639:384], in_mux[383:128], in_mux[127:0]};
        8'h04: shifted_input = {in_mux[1023:256], in_mux[255:0]};
        8'h05: shifted_input = {in_mux[1023:768], in_mux[767:256], in_mux[255:0]};
        8'h06: shifted_input = {in_mux[1023:512], in_mux[511:0]};
        8'h07: shifted_input = {in_mux[1023:640], in_mux[639:128], in_mux[127:0]};
        8'h08: shifted_input = {in_mux[1023:128], in_mux[127:0]};
        8'h09: shifted_input = {in_mux[1023:768], in_mux[767:128], in_mux[127:0]};
        8'h0A: shifted_input = {in_mux[1023:512], in_mux[511:0]};
        8'h0B: shifted_input = {in_mux[1023:640], in_mux[639:0]};
        8'h0C: shifted_input = {in_mux[1023:384], in_mux[383:0]};
        8'h0D: shifted_input = {in_mux[1023:768], in_mux[767:0]};
        8'h0E: shifted_input = {in_mux[1023:512], in_mux[511:256], in_mux[255:0]};
        8'h0F: shifted_input = {in_mux[1023:640], in_mux[639:0]};
        default: shifted_input = in_mux;
    endcase
end

assign out_mux = shifted_input[3:0];

// bit-reversal module
reg [7:0] byte0, byte1, byte2, byte3;
always @(*) begin
    byte0 = {in_rev[7:0]};
    byte1 = {in_rev[15:8]};
    byte2 = {in_rev[23:16]};
    byte3 = {in_rev[31:24]};
end

reg [7:0] rev_byte0, rev_byte1, rev_byte2, rev_byte3;
always @(*) begin
    rev_byte0 = {byte0[7], byte0[6], byte0[5], byte0[4], byte0[3], byte0[2], byte0[1], byte0[0]};
    rev_byte1 = {byte1[7], byte1[6], byte1[5], byte1[4], byte1[3], byte1[2], byte1[1], byte1[0]};
    rev_byte2 = {byte2[7], byte2[6], byte2[5], byte2[4], byte2[3], byte2[2], byte2[1], byte2[0]};
    rev_byte3 = {byte3[7], byte3[6], byte3[5], byte3[4], byte3[3], byte3[2], byte3[1], byte3[0]};
end

assign out_rev = {rev_byte3, rev_byte2, rev_byte1, rev_byte0};

// functional module
always @(posedge clk, negedge reset) begin
    if(reset) begin
        out_final <= 8'b00000000;
    end else begin
        out_final <= out_mux ^ out_rev;
    end
end

endmodule

module fifo_64in_out_wr_logic
   (full,
    O1,
    O2,
    wr_clk,
    rst_d2,
    wr_en,
    Q,
    RD_PNTR_WR,
    rst_full_gen_i);
  output full;
  output O1;
  output [11:0]O2;
  input wr_clk;
  input rst_d2;
  input wr_en;
  input [63:0]Q;
  input [11:0]RD_PNTR_WR;
  input rst_full_gen_i;

  reg [63:0] fifo [0:7];
  reg [11:0] wr_pntr = 0;
  reg [11:0] rd_pntr = 0;
  reg [11:0] wr_pntr_plus2 = 2;
  wire [11:0] O2 = rd_pntr;
  wire full = (wr_pntr == rd_pntr) && (wr_pntr_plus2 == RD_PNTR_WR);

  always @(posedge wr_clk) begin
    if (rst_d2) begin
      wr_pntr <= 0;
      rd_pntr <= 0;
      wr_pntr_plus2 <= 2;
      fifo <= 0;
    end else if (wr_en && !full) begin
      fifo[wr_pntr] <= Q;
      wr_pntr <= wr_pntr + 1;
      wr_pntr_plus2 <= wr_pntr_plus2 + 2;
    end else if (O1) begin
      rd_pntr <= rd_pntr + 1;
    end
  end

endmodule

module barrel_shifter(
  input [n-1:0] in,
  input [m-1:0] shift_amount,
  output [n-1:0] out
);

parameter n = 8;   // number of bits in input signal
parameter m = 3;   // number of bits in shift amount signal

reg [n-1:0] shifted;  // temporary register to hold shifted value

always @(*) begin
  if (shift_amount > 0) begin
    shifted = {in[shift_amount-1:0], {shift_amount{n-shift_amount}}};
  end else if (shift_amount < 0) begin
    shifted = {{-shift_amount{n+shift_amount}}, in[-shift_amount-1:0]};
  end else begin
    shifted = in;
  end
end

assign out = shifted;

endmodule

