module SPI_FSM(
    Reset_n_i, Clk_i, SPI_FSM_Start, SPI_Transmission_i, MAX6682CS_n_o, SPI_Write_o, SPI_ReadNext_o, SPI_FSM_Done, SPI_Data_i, Byte0, Byte1
);

    // Declare wires for Byte0 and Byte1
    wire [7:0] Byte0;
    wire [7:0] Byte1;

    // Declare wires for MAX6682CS_n_o and SPI_FSM_Wr1
    wire MAX6682CS_n_o;
    wire SPI_FSM_Wr1;

    // Declare wires for internal signals
    wire auto_opt_reduce_cc_126_opt_mux_2101;
    wire auto_opt_reduce_cc_126_opt_mux_2111;
    wire procmux_1864_CMP;
    wire procmux_1865_CMP;
    wire procmux_1866_CMP;
    wire procmux_1869_CMP;

    // Declare module inputs
    input Clk_i;
    input Reset_n_i;
    input [7:0] SPI_Data_i;
    input SPI_FSM_Start;
    input SPI_Transmission_i;

    // Declare module outputs
    output MAX6682CS_n_o;
    output SPI_Write_o;
    output SPI_ReadNext_o;
    output SPI_FSM_Done;
    output [7:0] Byte0;
    output [7:0] Byte1;

    // Declare wires for FSM state encoding
    wire [1:0] SPI_FSM_State_next;
    wire [1:0] SPI_FSM_State;

    // Declare FSM states
    parameter IDLE = 2'b00;
    parameter WRITE = 2'b01;
    parameter READ = 2'b10;
    parameter DONE = 2'b11;

    // Declare FSM state transition table
    assign SPI_FSM_State_next = (SPI_FSM_State == IDLE && SPI_FSM_Start) ? WRITE :
                                (SPI_FSM_State == WRITE) ? READ :
                                (SPI_FSM_State == READ) ? DONE :
                                SPI_FSM_State;

    // Declare FSM state register
    always @(posedge Clk_i or negedge Reset_n_i) begin
        if (~Reset_n_i) begin
            SPI_FSM_State <= IDLE;
        end else begin
            SPI_FSM_State <= SPI_FSM_State_next;
        end
    end

    // Declare FSM output signals
    assign SPI_Write_o = (SPI_FSM_State == WRITE) ? 1'b1 : 1'b0;
    assign SPI_ReadNext_o = (SPI_FSM_State == READ) ? 1'b1 : 1'b0;
    assign SPI_FSM_Done = (SPI_FSM_State == DONE) ? 1'b1 : 1'b0;

    // Declare MAX6682CS_n_o output signal
    assign MAX6682CS_n_o = ~SPI_FSM_Start;

    // Declare Byte0 and Byte1 output signals
    assign Byte0 = (SPI_Transmission_i) ? SPI_Data_i : 8'b0;
    assign Byte1 = (SPI_Transmission_i) ? 8'b0 : SPI_Data_i;

endmodule

module m_rep_upload(
    input clk,
    input rst,
    input [175:0] m_flits_rep,
    input v_m_flits_rep,
    input [3:0] flits_max,
    input en_flits_max,
    input rep_fifo_rdy,
    output reg [15:0] m_flit_out,
    output reg v_m_flit_out,
    output reg [1:0] m_ctrl_out,
    output reg m_rep_upload_state
);

// define states
localparam [1:0] IDLE = 2'b00;
localparam [1:0] WAIT_FOR_FIFO = 2'b01;
localparam [1:0] UPLOAD = 2'b10;

// define parameters
localparam [3:0] MAX_FLITS = 4'b1111;
localparam [15:0] EMPTY_FLIT = 16'h0;

// define registers
reg [175:0] m_flits;
reg [3:0] flits_left;
reg [1:0] state;
reg [15:0] current_flit;
reg [15:0] next_flit;
reg v_next_flit;
reg [3:0] current_flit_number;
reg [3:0] next_flit_number;
reg [15:0] upload_fifo [0:MAX_FLITS-1];
reg [3:0] upload_fifo_head;
reg [3:0] upload_fifo_tail;

// initialize registers
initial begin
    m_flits = 176'h0;
    flits_left = 4'h0;
    state = IDLE;
    current_flit = EMPTY_FLIT;
    next_flit = EMPTY_FLIT;
    v_next_flit = 1'b0;
    current_flit_number = 4'h0;
    next_flit_number = 4'h0;
    upload_fifo_head = 4'h0;
    upload_fifo_tail = 4'h0;
end

// define state machine
always @(posedge clk) begin
    case (state)
        IDLE: begin
            m_ctrl_out = 2'b00;
            m_rep_upload_state = 1'b0;
            if (rst) begin
                m_flits = 176'h0;
                flits_left = 4'h0;
                state = IDLE;
                current_flit = EMPTY_FLIT;
                next_flit = EMPTY_FLIT;
                v_next_flit = 1'b0;
                current_flit_number = 4'h0;
                next_flit_number = 4'h0;
                upload_fifo_head = 4'h0;
                upload_fifo_tail = 4'h0;
            end else if (v_m_flits_rep) begin
                m_flits = m_flits_rep;
                flits_left = en_flits_max ? flits_max : MAX_FLITS;
                state = WAIT_FOR_FIFO;
            end else begin
                state = IDLE;
            end
        end
        WAIT_FOR_FIFO: begin
            m_ctrl_out = 2'b01;
            m_rep_upload_state = 1'b1;
            if (rst) begin
                m_flits = 176'h0;
                flits_left = 4'h0;
                state = IDLE;
                current_flit = EMPTY_FLIT;
                next_flit = EMPTY_FLIT;
                v_next_flit = 1'b0;
                current_flit_number = 4'h0;
                next_flit_number = 4'h0;
                upload_fifo_head = 4'h0;
                upload_fifo_tail = 4'h0;
            end else if (rep_fifo_rdy) begin
                current_flit = m_flits[15:0];
                next_flit = m_flits[31:16];
                v_next_flit = 1'b1;
                current_flit_number = 4'h1;
                next_flit_number = 4'h2;
                flits_left = flits_left - 1;
                if (flits_left == 0) begin
                    state = IDLE;
                end else begin
                    state = UPLOAD;
                end
            end else begin
                state = WAIT_FOR_FIFO;
            end
        end
        UPLOAD: begin
            m_ctrl_out = 2'b10;
            m_rep_upload_state = 1'b1;
            if (rst) begin
                m_flits = 176'h0;
                flits_left = 4'h0;
                state = IDLE;
                current_flit = EMPTY_FLIT;
                next_flit = EMPTY_FLIT;
                v_next_flit = 1'b0;
                current_flit_number = 4'h0;
                next_flit_number = 4'h0;
                upload_fifo_head = 4'h0;
                upload_fifo_tail = 4'h0;
            end else if (rep_fifo_rdy) begin
                if (v_next_flit) begin
                    upload_fifo[upload_fifo_tail] = next_flit;
                    upload_fifo_tail = upload_fifo_tail + 1;
                    next_flit = EMPTY_FLIT;
                    v_next_flit = 1'b0;
                end
                if (upload_fifo_head != upload_fifo_tail) begin
                    m_flit_out = upload_fifo[upload_fifo_head];
                    v_m_flit_out = 1'b1;
                    upload_fifo_head = upload_fifo_head + 1;
                    current_flit_number = current_flit_number + 1;
                    next_flit_number = next_flit_number + 1;
                    if (current_flit_number == 4'hF) begin
                        current_flit = EMPTY_FLIT;
                    end else begin
                        current_flit = m_flits[(current_flit_number+1)*16-1:current_flit_number*16];
                    end
                    if (next_flit_number == 4'hF) begin
                        next_flit = EMPTY_FLIT;
                        v_next_flit = 1'b0;
                    end else begin
                        next_flit = m_flits[(next_flit_number+1)*16-1:next_flit_number*16];
                        v_next_flit = 1'b1;
                    end
                end
                if (flits_left == 0 && upload_fifo_head == upload_fifo_tail) begin
                    state = IDLE;
                end else begin
                    state = UPLOAD;
                end
            end else begin
                state = UPLOAD;
            end
        end
        default: begin
            state = IDLE;
        end
    endcase
end

endmodule

module reverse_bits (
    input  [3:0]  in,
    output [3:0]  out
);

    wire q, q_n;
    wire d = in[0];
    wire g = 1'b1;
    wire vdd = 1'b1;
    wire vss = 1'b0;

    sky130_fd_sc_lp__dlxbn_1 flip_flop_0 (
        .Q     (q),
        .Q_N   (q_n),
        .D     (d),
        .GATE_N(g),
        .VPWR  (vdd),
        .VGND  (vss),
        .VPB   (vss),
        .VNB   (vss)
    );

    wire d_1 = in[1] ^ in[3];
    sky130_fd_sc_lp__dlxbn_1 flip_flop_1 (
        .Q     (q),
        .Q_N   (q_n),
        .D     (d_1),
        .GATE_N(g),
        .VPWR  (vdd),
        .VGND  (vss),
        .VPB   (vss),
        .VNB   (vss)
    );

    wire d_2 = in[2] ^ in[0];
    sky130_fd_sc_lp__dlxbn_1 flip_flop_2 (
        .Q     (q),
        .Q_N   (q_n),
        .D     (d_2),
        .GATE_N(g),
        .VPWR  (vdd),
        .VGND  (vss),
        .VPB   (vss),
        .VNB   (vss)
    );

    wire d_3 = in[3];
    sky130_fd_sc_lp__dlxbn_1 flip_flop_3 (
        .Q     (out[3]),
        .Q_N   (),
        .D     (d_3),
        .GATE_N(g),
        .VPWR  (vdd),
        .VGND  (vss),
        .VPB   (vss),
        .VNB   (vss)
    );

    assign out[0] = q_n;
    assign out[1] = q_n ^ d_1;
    assign out[2] = q_n ^ d_2;

endmodule

module memory_interface (
