        if (rst) begin
            // Reset all internal state and outputs to default values
            mem_data <= 8'b0;
            mem_addr <= 13'b0;
            mem_bank <= 3'b0;
            mem_write_en <= 1'b0;
            state <= IDLE;
        end else begin
            case(state)
                IDLE: begin
                    if (wr_en) begin
                        // Write operation requested - move to ADDR_SETUP state
                        mem_addr <= addr;
                        mem_bank <= addr[2:0];
                        mem_data <= data_in;
                        mem_write_en <= 1'b1;
                        state <= ADDR_SETUP;
                    end else begin
                        // Read operation requested - move to READ_CYCLE state
                        mem_addr <= addr;
                        mem_bank <= addr[2:0];
                        mem_write_en <= 1'b0;
                        state <= ADDR_SETUP;
                    end
                end
                ADDR_SETUP: begin
                    // Address setup time - move to next state
                    mem_cke <= 1'b1;
                    mem_cs_n <= 1'b0;
                    mem_ras_n <= 1'b0;
                    mem_cas_n <= 1'b0;
                    mem_we_n <= 1'b0;
                    mem_reset_n <= 1'b0;
                    state <= (wr_en) ? WRITE_CYCLE : READ_CYCLE;
                end
                READ_CYCLE: begin
                    // Memory read cycle - move to IDLE state
                    mem_cke <= 1'b0;
                    mem_cs_n <= 1'b1;
                    mem_ras_n <= 1'b1;
                    mem_cas_n <= 1'b1;
                    mem_we_n <= 1'b1;
                    mem_reset_n <= 1'b1;
                    data_out <= mem_dq;
                    state <= IDLE;
                end
                WRITE_CYCLE: begin
                    // Memory write cycle - move to IDLE state
                    mem_dq <= mem_data;
                    mem_cke <= 1'b0;
                    mem_cs_n <= 1'b1;
                    mem_ras_n <= 1'b1;
                    mem_cas_n <= 1'b1;
                    mem_we_n <= 1'b1;
                    mem_reset_n <= 1'b1;
                    state <= IDLE;
                end
            endcase
        end
    end

    // Assign memory interface signals
    assign mem_a = mem_addr;
    assign mem_ba = mem_bank;
    assign mem_ck = clk;
    assign mem_ck_n = ~clk;
    assign mem_dqs = 1'b0;
    assign mem_dqs_n = 1'b0;
    assign mem_dm = 1'b0;
    assign mem_odt = 1'b0;
    assign mem_dq = (mem_write_en) ? mem_data : 8'bz;
endmodule

module full_adder(
    input a, b, cin,
    output cout, sum
);
    wire w1, w2, w3;
    transmission_gate tg1(a, cin, w1);
    transmission_gate tg2(a, b, w2);
    transmission_gate tg3(b, cin, w3);
    inverter inv1(w1, w1_inv);
    inverter inv2(w2, w2_inv);
    inverter inv3(w3, w3_inv);
    and_gate and1(w1_inv, w2_inv, w3_inv, cout);
    xor_gate xor1(a, b, w4);
    xor_gate xor2(w4, cin, sum);
endmodule

module bitwise_logic(
    input [2:0] a,
    input [2:0] b,
    output [2:0] out_or,
    output out_logical_or,
    output [5:0] out_not
);
    wire [2:0] xor1_out;
    wire [2:0] inv_out;
    xor_gate xor1(a, b, xor1_out);
    inverter inv1(a, inv_out[0]);
    inverter inv2(b, inv_out[1]);
    inverter inv3(xor1_out, inv_out[2]);
    or_gate or1(xor1_out, out_or);
    and_gate and1(a, b, out_logical_or);
    assign out_not = ~{a, b};
endmodule

