module booth_multiplier (
    input signed [7:0] A,
    input signed [7:0] B,
    input ready,
    output reg valid,
    output reg signed [15:0] product
);

reg signed [7:0] a_reg;
reg signed [7:0] b_reg;
reg signed [7:0] b_neg;
reg signed [15:0] p_reg;
reg [3:0] state;

always @(posedge ready) begin
    if (state == 0) begin
        a_reg <= A;
        b_reg <= B;
        b_neg <= ~B + 1;
        p_reg <= {8'b0, a_reg};
        state <= 1;
    end else if (state == 1) begin
        if (b_reg[0] == 1 && b_reg != 1'b1) begin
            p_reg <= p_reg - b_neg;
            b_reg <= b_reg + 1;
            state <= 2;
        end else begin
            state <= 3;
        end
    end else if (state == 2) begin
        if (p_reg[0] == 1) begin
            p_reg <= p_reg + b_reg;
        end
        if (b_reg[0] == 1 && b_reg != 1'b1) begin
            p_reg <= p_reg - b_neg;
            b_reg <= b_reg + 1;
        end else begin
            state <= 3;
        end
    end else if (state == 3) begin
        product <= p_reg[15:0];
        valid <= 1;
        state <= 0;
    end
end

endmodule

module slaveRxStatusMonitor(
  input [1:0] connectStateIn,
  input resumeDetectedIn,
  input clk,
  input rst,
  output reg resetEventOut,
  output reg [1:0] connectStateOut,
  output reg resumeIntOut
);

  always @ (posedge clk) begin
    if (rst) begin
      resetEventOut <= 0;
      connectStateOut <= connectStateIn;
      resumeIntOut <= 0;
    end else begin
      if (connectStateIn != connectStateOut) begin
        resetEventOut <= 1;
      end else begin
        resetEventOut <= 0;
      end

      connectStateOut <= connectStateIn;

      if (resumeDetectedIn && !resumeIntOut) begin
        resumeIntOut <= 1;
      end else begin
        resumeIntOut <= 0;
      end
    end
  end

endmodule

module top_module (
    input clk,
    input reset, // Synchronous active-high reset
    input [1:0] A,
    input [1:0] B,
    input [7:0] a,
    input [7:0] b,
    input select, // Select input to choose between comparator and adder
    output [7:0] out
);

    wire [2:0] cmp_out;
    wire [10:0] add_out;
    wire overflow;
    wire [7:0] and_out;

    comparator_module cmp_inst (
        .A(A),
        .B(B),
        .out(cmp_out)
    );

    adder_module add_inst (
        .a(a),
        .b(b),
        .out(add_out),
        .overflow(overflow)
    );

    assign and_out = cmp_out & add_out[7:0];

    always @(posedge clk) begin
        if (reset) begin
            out <= 8'b0;
        end else begin
            if (select) begin
                out <= {3'b0, add_out[10:3], overflow};
            end else begin
                out <= {cmp_out, 8'b0};
            end
        end
    end

    assign out[7:0] = and_out;

endmodule

