// Binary tree multiplexer module
module binary_tree_mux(
    input [255:0] in,
    input [7:0] sel,
    output reg [255:0] out
);

always @*
begin
    case (sel)
        8'h00: out = in[0];
        8'h01: out = in[1];
        8'h02: out = in[2];
        8'h03: out = in[3];
        8'h04: out = in[4];
        8'h05: out = in[5];
        8'h06: out = in[6];
        8'h07: out = in[7];
        8'h08: out = {in[0], in[1]};
        8'h09: out = {in[2], in[3]};
        8'h0A: out = {in[4], in[5]};
        8'h0B: out = {in[6], in[7]};
        8'h0C: out = {in[0], in[1], in[2], in[3]};
        8'h0D: out = {in[4], in[5], in[6], in[7]};
        8'h0E: out = {in[0], in[1], in[2], in[3], in[4], in[5], in[6], in[7]};
        default: out = 256'h0;
    endcase
end

endmodule

