module motor_control (
  input ctrl,
  input clk,
  input rst,
  input dir,
  input [7:0] spd,
  input [3:0] step,
  output pwm,
  output fw,
  output rev,
  output step
);

parameter motor_type = "PWM"; // type of the motor (PWM, H-bridge, or stepper)
parameter clk_freq = 50; // frequency of the clock signal
parameter motor_freq = 1000; // frequency of the motor signal (for PWM and H-bridge motors)

reg [7:0] counter;
reg [7:0] duty_cycle;

always @(posedge clk) begin
  if (rst) begin
    counter <= 0;
    duty_cycle <= 0;
  end else if (ctrl) begin
    counter <= counter + 1;
    if (counter == (clk_freq / motor_freq)) begin
      counter <= 0;
      if (motor_type == "PWM" || motor_type == "H-bridge") begin
        pwm <= (duty_cycle > spd) ? 0 : 1;
        duty_cycle <= duty_cycle + 1;
      end else if (motor_type == "stepper") begin
        if (dir) begin
          step <= step << 1;
          if (step == 16) begin
            step <= 1;
          end
        end else begin
          step <= step >> 1;
          if (step == 0) begin
            step <= 8;
          end
        end
      end
    end
  end
end

assign fw = (motor_type == "H-bridge") ? spd : 0;
assign rev = (motor_type == "H-bridge") ? ~spd : 0;

endmodule

