            pipe_data13 <= 8'b0;
            pipe_data14 <= 8'b0;
            pipe_data15 <= 8'b0;
            pipe_data16 <= 8'b0;
            pipe_data17 <= 8'b0;
            pipe_data18 <= 8'b0;
            pipe_data19 <= 8'b0;
            pipe_data20 <= 8'b0;
            state <= IDLE;
            valid_b <= 1'b0;
            data_out <= 10'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (valid_a) begin
                        acc_data <= data_in;
                        counter <= 4'b0;
                        state <= ACCUMULATE;
                    end
                end
                ACCUMULATE: begin
                    if (counter == 4'b1111) begin
                        pipe_data1 <= acc_data;
                        pipe_data2 <= pipe_data1;
                        pipe_data3 <= pipe_data2;
                        pipe_data4 <= pipe_data3;
                        pipe_data5 <= pipe_data4;
                        pipe_data6 <= pipe_data5;
                        pipe_data7 <= pipe_data6;
                        pipe_data8 <= pipe_data7;
