                        pipe_data10 <= pipe_data9;
                        pipe_data11 <= pipe_data10;
                        pipe_data12 <= pipe_data11;
                        pipe_data13 <= pipe_data12;
                        pipe_data14 <= pipe_data13;
                        pipe_data15 <= pipe_data14;
                        pipe_data16 <= pipe_data15;
                        pipe_data17 <= pipe_data16;
                        pipe_data18 <= pipe_data17;
                        pipe_data19 <= pipe_data18;
                        pipe_data20 <= pipe_data19;
                        acc_data <= 8'b0;
                        counter <= 4'b0;
                        state <= OUTPUT;
                    end else begin
                        acc_data <= acc_data + data_in;
                        counter <= counter + 1;
                    end
                end
                OUTPUT: begin
                    data_out <= pipe_data20 + pipe_data19 + pipe_data18 + pipe_data17 + pipe_data16 + pipe_data15 + pipe_data14 + pipe_data13 + pipe_data12 + pipe_data11 + pipe_data10 + pipe_data9 + pipe_data8 + pipe_data7 + pipe_data6 + pipe_data5 + pipe_data4 + pipe_data3 + pipe_data2 + pipe_data1 + acc_data;
