module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [15:0] in1, // First 16-bit input
    input [15:0] in2, // Second 16-bit input
    output reg [15:0] out // 16-bit output of the computed absolute sum
);

    reg [15:0] abs_in1, abs_in2;
    wire [7:0] in1_hi, in1_lo, in2_hi, in2_lo;
    wire [31:0] in1_shifted, in2_shifted;
    wire [31:0] in1_reversed, in2_reversed;
    wire [31:0] abs_sum;

    // Instantiate the barrel_shift_mux module for in1
    barrel_shift_mux mux1 (
        .in(in1),
        .out_hi(in1_hi),
        .out_lo(in1_lo)
    );

    // Instantiate the barrel_shift_mux module for in2
    barrel_shift_mux mux2 (
        .in(in2),
        .out_hi(in2_hi),
        .out_lo(in2_lo)
    );

    // Instantiate the byte_reverser module for in1
    byte_reverser rev1 (
        .in({in1_hi, in1_lo}),
        .out(in1_reversed)
    );

    // Instantiate the byte_reverser module for in2
    byte_reverser rev2 (
        .in({in2_hi, in2_lo}),
        .out(in2_reversed)
    );

    // Compute the absolute value of in1
    always @(*) begin
        if (in1[15] == 1) begin
            abs_in1 = ~in1 + 1;
        end else begin
            abs_in1 = in1;
        end
    end

    // Compute the absolute value of in2
    always @(*) begin
        if (in2[15] == 1) begin
            abs_in2 = ~in2 + 1;
        end else begin
            abs_in2 = in2;
        end
    end

    // Compute the shifted and reversed inputs for in1 and in2
    assign in1_shifted = {in1_hi, in1_lo};
    assign in2_shifted = {in2_hi, in2_lo};
    assign in1_reversed = {in1_lo, in1_hi};
    assign in2_reversed = {in2_lo, in2_hi};

    // Compute the absolute sum of in1 and in2
    always @(*) begin
        if (abs_in1 > abs_in2) begin
            abs_sum = abs_in1 + abs_in2;
        end else begin
            abs_sum = abs_in2 + abs_in1;
        end
    end

    // Reverse the byte order of the absolute sum
    byte_reverser rev_sum (
        .in(abs_sum),
        .out(out)
    );

    // Synchronous active-high reset
    always @(posedge clk) begin
        if (reset) begin
            out <= 0;
        end else begin
            out <= {16{1'b0}} + rev_sum[15:0];
        end
    end

endmodule

