module booth_multiplier (
    input signed [7:0] A,
    input signed [7:0] B,
    input ready,
    output reg valid,
    output reg signed [15:0] product
);

reg signed [7:0] a_reg;
reg signed [7:0] b_reg;
reg signed [7:0] b_neg;
reg [3:0] a_shift_reg;
reg [3:0] b_shift_reg;
reg [3:0] b_shift_reg_neg;
reg [2:0] counter;
reg carry_in;
wire [3:0] sum;
wire carry_out;

ripple_carry_adder rca_inst (
    .A(a_shift_reg),
    .B(b_shift_reg),
    .carry_in(carry_in),
    .sum(sum),
    .carry_out(carry_out)
);

always @(*) begin
    a_reg = A;
    b_reg = B;
    b_neg = -B;
    a_shift_reg = {A[7], A[7], A[7], A};
    b_shift_reg = {B[7], B[7], B[7], B};
    b_shift_reg_neg = {b_neg[7], b_neg[7], b_neg[7], b_neg};
    counter = 3'd4;
    carry_in = 1'b0;
    valid = 1'b0;
end

always @(posedge ready) begin
    if (counter == 3'd0) begin
        product = {sum[3], sum};
        valid = 1'b1;
    end else begin
        if (b_reg[0] == 1'b1 && b_reg[1] == 1'b0) begin
            rca_inst.A <= a_shift_reg;
            rca_inst.B <= b_shift_reg_neg;
            carry_in <= 1'b1;
        end else if (b_reg[0] == 1'b0 && b_reg[1] == 1'b1) begin
            rca_inst.A <= a_shift_reg;
            rca_inst.B <= b_shift_reg;
            carry_in <= 1'b0;
        end else begin
            carry_in <= 1'b0;
        end
        counter <= counter - 1;
        a_shift_reg <= {a_shift_reg[2:0], carry_out};
        b_shift_reg <= {b_shift_reg[2:0], b_reg[0]};
        b_shift_reg_neg <= {b_shift_reg_neg[2:0], b_neg[0]};
    end
end

endmodule

