  empty,
  rd_data_count,
  wr_data_count,
  prog_full
);

input rst;
input wr_clk;
input rd_clk;
input [255 : 0] din;
input wr_en;
input rd_en;
output [63 : 0] dout;
output full;
output empty;
output [11 : 0] rd_data_count;
output [9 : 0] wr_data_count;
output prog_full;

reg [255:0] fifo_mem [0:1023];
reg [11:0] rd_ptr = 0;
reg [11:0] wr_ptr = 0;
reg [63:0] dout_reg = 0;
reg [11:0] rd_data_count_reg = 0;
reg [9:0] wr_data_count_reg = 0;
reg full_reg = 0;
reg empty_reg = 1;
reg prog_full_reg = 0;

always @(posedge wr_clk) begin
  if (rst) begin
    wr_ptr <= 0;
    wr_data_count_reg <= 0;
  end
  else begin
    if (wr_en && !full_reg) begin
      fifo_mem[wr_ptr] <= din;
      wr_ptr <= wr_ptr + 1;
      wr_data_count_reg <= wr_data_count_reg + 1;
    end
  end
end

always @(posedge rd_clk) begin
  if (rst) begin
    rd_ptr <= 0;
    rd_data_count_reg <= 0;
    dout_reg <= 0;
  end
  else begin
    if (rd_en && !empty_reg) begin
      dout_reg <= fifo_mem[rd_ptr][63:0];
      rd_ptr <= rd_ptr + 1;
      rd_data_count_reg <= rd_data_count_reg - 1;
    end
  end
end

assign dout = dout_reg;
assign rd_data_count = rd_data_count_reg;
assign wr_data_count = 1024 - wr_data_count_reg;
assign full = full_reg;
assign empty = empty_reg;
assign prog_full = prog_full_reg;

always @(wr_ptr, rd_ptr, wr_data_count_reg, rd_data_count_reg, prog_full_reg) begin
  full_reg = (wr_ptr == rd_ptr) && (wr_data_count_reg != 0);
  empty_reg = (wr_ptr == rd_ptr) && (rd_data_count_reg == 0);
end

always @(wr_data_count_reg, rd_data_count_reg, prog_full_reg) begin
  if (wr_data_count_reg >= prog_full_reg) begin
    full_reg <= 1;
  end
end

