module top_module (
    input clk,
    input reset, // Synchronous active-high reset
    input [7:0] a, // 8-bit input for the adder
    input [7:0] b, // 8-bit input for the adder
    input [15:0] in, // 16-bit input for the splitter
    input select, // Select input to choose between adder and splitter
    output [7:0] out_hi, // 8-bit output from the splitter
    output [7:0] out_lo, // 8-bit output from the splitter
    output [7:0] final_out // 8-bit final output from the additional functional module
);

// Convert 2's complement numbers to sign-magnitude format
wire [7:0] a_mag = (a[7] == 1) ? (~a + 1) : a;
wire [7:0] b_mag = (b[7] == 1) ? (~b + 1) : b;

// Add the two numbers using the 2's complement adder
wire [8:0] s_mag;
adder_8bit adder_inst (
    .a(a_mag),
    .b(b_mag),
    .s(s_mag)
);

// Convert the sum back to 2's complement format
wire [7:0] s;
assign s = (s_mag[8] == 1) ? (~s_mag[7:0] + 1) : s_mag[7:0];

// Split the 16-bit input into two 8-bit outputs using the splitter
wire [7:0] in_lo = in[7:0];
wire [7:0] in_hi = in[15:8];

// Control logic to select between adder and splitter outputs
wire [7:0] selected_output;
assign selected_output = (select == 1) ? s : in;

// Split the selected output into two 8-bit outputs using the splitter
wire [7:0] selected_lo = selected_output[7:0];
wire [7:0] selected_hi = selected_output[15:8];

// Output the splitter outputs
assign out_lo = (select == 0) ? in_lo : selected_lo;
assign out_hi = (select == 0) ? in_hi : selected_hi;

// Additional functional module to generate final output
wire [7:0] final_output;
my_functional_module functional_inst (
    .in_lo(selected_lo),
    .in_hi(selected_hi),
