module top_module (
  input clk,
  input reset, // Synchronous active-high reset
  input [7:0] d, // 8-bit input for the shift registers
  input select, // Select input to choose between the two shift registers
  output [7:0] q // 8-bit output from the AND operation module
);

  wire [7:0] shift_reg_1_out, shift_reg_2_out;
  wire [2:0] shifted_input;
  wire [7:0] and_output;

  my_shift_register shift_reg_1 (
    .clk(clk),
    .reset(reset),
    .d(d),
    .q(shift_reg_1_out)
  );

  my_shift_register shift_reg_2 (
    .clk(clk),
    .reset(reset),
    .d(d),
    .q(shift_reg_2_out)
  );

  my_shift_control shift_control (
    .select(select),
    .shift_reg_1_out(shift_reg_1_out),
    .shift_reg_2_out(shift_reg_2_out),
    .and_output(and_output)
  );

  my_shift_input_shift shift_input_shift (
    .clk(clk),
    .reset(reset),
    .d(d),
    .q(shifted_input)
  );

  my_and_operation and_op (
    .a(shifted_input),
    .b(and_output),
    .q(q)
  );

endmodule

module my_shift_register (
  input clk,
  input reset, // Synchronous active-high reset
  input [7:0] d, // 8-bit input
  output reg [7:0] q // 8-bit output
);

  always @(posedge clk) begin
    if (reset) begin
      q <= 8'b0;
    end else begin
      q <= {q[6:0], d[0]};
    end
  end

endmodule

module my_shift_control (
  input select,
  input [7:0] shift_reg_1_out,
  input [7:0] shift_reg_2_out,
  output reg [7:0] and_output
);

  always @(*) begin
    if (select) begin
      and_output = shift_reg_1_out & shift_reg_2_out;
    end else begin
      and_output = shift_reg_2_out & shift_reg_1_out;
    end
  end

endmodule

module my_shift_input_shift (
  input clk,
  input reset, // Synchronous active-high reset
  input [7:0] d, // 8-bit input
  output reg [2:0] q // 3-bit output
);

  reg [2:0] shift_reg;

  always @(posedge clk) begin
    if (reset) begin
      shift_reg <= 3'b0;
    end else begin
      shift_reg <= {shift_reg[1:0], d[7]};
    end
  end

  assign q = shift_reg;

endmodule

module my_and_operation (
  input [2:0] a,
  input [7:0] b,
  output reg [7:0] q
);

  always @(*) begin
    q = a & b;
  end

endmodule

