module fifo #(
    parameter DATA_IN_WIDTH = 32,
    parameter DATA_OUT_WIDTH = 8,
    parameter FIFO_DEPTH = 12
)(
    input   wire                            reset,    

    // IN PORT
    input   wire    [DATA_IN_WIDTH-1:0]     data_in,
    input   wire                            data_in_clock,     
    input   wire                            data_in_enable,
    input   wire                            data_in_start,
    input   wire                            data_in_end,

    // OUT PORT
    output  wire    [DATA_OUT_WIDTH-1:0]    data_out,
    input   wire                            data_out_clock,     
    input   wire                            data_out_enable,
    output  wire                            data_out_start,
    output  wire                            data_out_end,

    input   wire                            retry,
    input   wire                            error,
    output  reg     [FIFO_DEPTH-6:0]        frame_count
);

    // Internal parameters
    localparam FIFO_DATA_IN_WIDTH = DATA_IN_WIDTH + 2;
    localparam FIFO_DATA_OUT_WIDTH = DATA_OUT_WIDTH + 2*(DATA_OUT_WIDTH/DATA_IN_WIDTH);
    localparam FIFO_DATA_OUT_MAX_INDEX = FIFO_DATA_OUT_WIDTH - 1;
    localparam START_OFFSET = DATA_IN_WIDTH;
    localparam END_OFFSET = DATA_IN_WIDTH + 1;

    // Internal wires
    wire [(DATA_OUT_WIDTH-1)+(2*(DATA_OUT_WIDTH/DATA_IN_WIDTH)):0]  fifo_data_out;
    wire [FIFO_DATA_IN_WIDTH-1:0]                                   fifo_data_in;
    wire [(DATA_OUT_WIDTH/DATA_IN_WIDTH)-1:0]                       data_out_start_tmp;
    wire [(DATA_OUT_WIDTH/DATA_IN_WIDTH)-1:0]                       data_out_end_tmp;
    wire [FIFO_DEPTH-1:0]                                           data_in_address;
    reg  [FIFO_DEPTH-1:0]                                           data_in_address_tmp;
    wire [FIFO_DEPTH-1:0]                                           data_out_address;
    reg  [FIFO_DEPTH-1:0]                                           data_out_address_tmp;

    // Data output assignments
    assign data_out_start = | data_out_start_tmp;
    assign data_out_end = | data_out_end_tmp;
    assign data_out = fifo_data_out [(DATA_OUT_WIDTH-1)+(2*(DATA_OUT_WIDTH/DATA_IN_WIDTH))-1:0];

    // Data input assignments
    assign fifo_data_in = {data_in, data_in_start, data_in_end};

    // Address assignments
    assign data_in_address = frame_count;
    always @(posedge data_in_start or posedge reset) begin
        if (reset) begin
            data_in_address_tmp <= 0;
        end
        else if (data_in_start) begin
            data_in_address_tmp <= data_in_address;
        end
    end
    assign data_out_address = frame_count - (|data_out_start_tmp);

    // Output data start and end signal assignments
    genvar i;
    generate if (DATA_OUT_WIDTH > DATA_IN_WIDTH) begin
        for (i = 0; i < DATA_OUT_WIDTH/DATA_IN_WIDTH; i = i + 1) begin
            assign data_out_start_tmp[i] = fifo_data_out[FIFO_DATA_OUT_MAX_INDEX-START_OFFSET-i*FIFO_DATA_IN_WIDTH];
            assign data_out_end_tmp[i] = fifo_data_out[FIFO_DATA_OUT_MAX_INDEX-END_OFFSET-i*FIFO_DATA_IN_WIDTH];
        end
    end else begin
        for (i = 0; i < DATA_OUT_WIDTH/DATA_IN_WIDTH; i = i + 1) begin
            assign data_out_start_tmp[i] = fifo_data_out[(i+1)*DATA_IN_WIDTH-1];
            assign data_out_end_tmp[i] = fifo_data_out[i*DATA_IN_WIDTH];
        end
    end endgenerate

    // FIFO module instantiation
    fifo #(
        .DATA_IN_WIDTH (FIFO_DATA_IN_WIDTH),
        .DATA_OUT_WIDTH (FIFO_DATA_OUT_WIDTH),
        .FIFO_DEPTH (FIFO_DEPTH)
    )
    U_fifo (
        .reset(reset),
        .count(),
        // IN PORT
        .data_in(fifo_data_in),
        .data_in_clock(data_in_clock),
        .data_in_enable(data_in_enable),
        .data_in_address(data_in_address),
        .data_in_reset(error),
        .data_in_reset_address(data_in_address_tmp),
        // OUT PORT
        .data_out(fifo_data_out),
        .data_out_clock(data_out_clock),
        .data_out_enable(data_out_enable),
        .data_out_address(data_out_address),
        .data_out_reset(retry),
        .data_out_reset_address(data_out_address_tmp)
    );

    // Frame count counter
    always @(posedge data_in_end or posedge data_out_end or posedge reset) begin
        if (reset) begin
            frame_count <= 0;
        end else if (data_in_end) begin
            frame_count <= frame_count + 1;
        end else if (data_out_end) begin
            frame_count <= frame_count - 1;
        end
    end

endmodule

module combined_module (
    input clk,
    input reset,   // Synchronous active-high reset
    input load,    // Load value into counter when asserted
    input up_down, // Count up or down based on value
    input a, b,    // 2-bit input for the half adder
    output [7:0] q // 8-bit output from the functional module
);

    reg [7:0] counter;
    wire sum, carry_out;

    // Instantiate half adder
    half_adder ha(
        .a(a),
        .b(b),
        .sum(sum),
        .carry_out(carry_out)
    );

    // Instantiate up/down counter
    up_down_counter ud_counter(
        .clk(clk),
        .reset(reset),
        .load(load),
        .up_down(up_down),
        .count_out(counter)
    );

    // Generate 8-bit output
    always @ (posedge clk) begin
        if (carry_out == 1'b0) begin
            q <= {1'b0, sum, counter};
        end else begin
            q <= {1'b0, sum, counter + 1};
        end
    end

endmodule

// Half adder module
module half_adder (
    input a,
    input b,
    output sum,
    output carry_out
);

    assign sum = a ^ b;
    assign carry_out = a & b;

endmodule

// Up/down counter module
module up_down_counter (
    input clk,
    input reset,   // Synchronous active-high reset
    input load,    // Load value into counter when asserted
    input up_down, // Count up or down based on value
    output reg [7:0] count_out
);

    always @ (posedge clk) begin
        if (reset) begin
            count_out <= 8'b0;
        end else if (load) begin
            count_out <= count_in;
        end else if (up_down) begin
            count_out <= count_out + 1;
        end else begin
            count_out <= count_out - 1;
        end
    end

endmodule

module add4bit(
    input [3:0] A,
    input [3:0] B,
    output reg [4:0] SUM
);

always @(*) begin
    SUM = A + B;
    if (SUM > 15) begin
        SUM = SUM + 16;
        SUM[4] = 1;
    end else begin
        SUM[4] = 0;
    end
end

endmodule

module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    input CIN,
    output [3:0] S,
    output COUT
);

    wire [3:0] sum;
    wire carry_out_1;
    wire carry_out_2;

    // First stage of the adder
    full_adder fa1(.A(A[0]), .B(B[0]), .CIN(CIN), .S(sum[0]), .COUT(carry_out_1));
    full_adder fa2(.A(A[1]), .B(B[1]), .CIN(carry_out_1), .S(sum[1]), .COUT(carry_out_2));
    full_adder fa3(.A(A[2]), .B(B[2]), .CIN(carry_out_2), .S(sum[2]), .COUT(COUT));
    full_adder fa4(.A(A[3]), .B(B[3]), .CIN(COUT), .S(sum[3]), .COUT());

    assign S = sum;

endmodule

module full_adder (
    input A,
    input B,
    input CIN,
    output S,
    output COUT
);

    assign S = A ^ B ^ CIN;
    assign COUT = (A & B) | (A & CIN) | (B & CIN);

endmodule

module add_subtract(
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] sum
);

    wire [15:0] carry_out1, carry_out2;
    wire [31:0] a_xor_b;

    assign a_xor_b = sub ? ~b : b;

    carry_select_adder adder1(
        .a(a[15:0]),
        .b(a_xor_b[15:0]),
        .c_in(1'b0),
        .sum(sum[15:0]),
        .c_out(carry_out1)
    );

    carry_select_adder adder2(
        .a(a[31:16]),
        .b(a_xor_b[31:16]),
        .c_in(carry_out1),
        .sum(sum[31:16]),
        .c_out(carry_out2)
    );

endmodule

module bitwise_xor(
    input [31:0] a,
