    output [7:0] final_output
);

    add_subtract add_subtract_inst(
        .a(a),
        .b(b),
        .sub(sub),
        .sum(sum)
    );

    bitwise_xor bitwise_xor_inst(
        .a(sum),
        .b(xor_input),
