module adder (
    input [7:0] A,
    input [7:0] B,
    output [8:0] sum
);

    wire [8:0] temp;
    wire carry;

    full_adder fa0(.a(A[0]), .b(B[0]), .carry_in(0), .sum(temp[0]), .carry_out(carry));
    full_adder fa1(.a(A[1]), .b(B[1]), .carry_in(carry), .sum(temp[1]), .carry_out(carry));
    full_adder fa2(.a(A[2]), .b(B[2]), .carry_in(carry), .sum(temp[2]), .carry_out(carry));
    full_adder fa3(.a(A[3]), .b(B[3]), .carry_in(carry), .sum(temp[3]), .carry_out(carry));
    full_adder fa4(.a(A[4]), .b(B[4]), .carry_in(carry), .sum(temp[4]), .carry_out(carry));
    full_adder fa5(.a(A[5]), .b(B[5]), .carry_in(carry), .sum(temp[5]), .carry_out(carry));
    full_adder fa6(.a(A[6]), .b(B[6]), .carry_in(carry), .sum(temp[6]), .carry_out(carry));
    full_adder fa7(.a(A[7]), .b(B[7]), .carry_in(carry), .sum(temp[7]), .carry_out(carry));
    full_adder fa8(.a(temp[0]), .b(temp[1]), .carry_in(carry), .sum(sum[0]), .carry_out(carry));
    full_adder fa9(.a(temp[2]), .b(temp[3]), .carry_in(carry), .sum(sum[1]), .carry_out(carry));
    full_adder fa10(.a(temp[4]), .b(temp[5]), .carry_in(carry), .sum(sum[2]), .carry_out(carry));
    full_adder fa11(.a(temp[6]), .b(temp[7]), .carry_in(carry), .sum(sum[3]), .carry_out(carry));
    full_adder fa12(.a(sum[0]), .b(sum[1]), .carry_in(carry), .sum(sum[4]), .carry_out(carry));
    full_adder fa13(.a(sum[2]), .b(sum[3]), .carry_in(carry), .sum(sum[5]), .carry_out(carry));
    full_adder fa14(.a(sum[4]), .b(sum[5]), .carry_in(carry), .sum(sum[6]), .carry_out(carry));
    full_adder fa15(.a(carry), .b(sum[6]), .carry_in(0), .sum(sum[7]), .carry_out(carry));
    full_adder fa16(.a(0), .b(carry), .carry_in(0), .sum(sum[8]), .carry_out(carry));

endmodule

