module moore_fsm (
  input clk, // clock signal
  input rst, // reset signal
  output [n-1:0] out // output signals
);

parameter n = 2; // number of output signals
parameter s = 4; // number of states

reg [s-1:0] state_reg; // state register

// Define the transition function
function [s-1:0] transition;
  input [s-1:0] current_state;
  input [n-1:0] inputs;
  begin
    case (current_state)
      s0: if (inputs[0]) transition = s1; else transition = s2;
      s1: if (inputs[1]) transition = s3; else transition = s0;
      s2: if (inputs[0]) transition = s3; else transition = s0;
      s3: if (inputs[1]) transition = s2; else transition = s1;
    endcase
  end
endfunction

// Define the output function
function [n-1:0] output_func;
  input [s-1:0] current_state;
  begin
    case (current_state)
      s0: output_func = 2'b00;
      s1: output_func = 2'b01;
      s2: output_func = 2'b10;
      s3: output_func = 2'b11;
    endcase
  end
endfunction

// Combinational logic to compute the next state and output signals
always @ (posedge clk or posedge rst) begin
  if (rst) begin
    state_reg <= s0;
    out <= 2'b00;
  end else begin
    state_reg <= transition(state_reg, out);
    out <= output_func(state_reg);
  end
end

endmodule

