        counter <= counter + 1;
    end

    if (counter < threshold) begin
        PWM_OUT <= 1'b1;
    end else begin
        PWM_OUT <= 1'b0;
    end
end

always @(*) begin
    threshold = (DUTY_CYCLE * PERIOD) / 100;
end

endmodule

