module calculator(
    input [7:0] A,
    input [7:0] B,
    input [1:0] op,
    input clk,
    input rst,
    output reg [7:0] out,
    output reg valid
);

reg [15:0] mul; // used for multiplication
reg [7:0] div; // used for division
reg [1:0] state; // state machine state

always @(posedge clk, posedge rst) begin
    if (rst) begin
        out <= 0;
        valid <= 0;
        state <= 0;
    end else begin
        case (state)
            0: begin // idle
                out <= 0;
                valid <= 0;
                if (op != 2'b00) // if op is not addition, go to next state
                    state <= 1;
            end
            1: begin // addition or subtraction
                if (op == 2'b00) begin // addition
                    out <= A + B;
                end else begin // subtraction
                    out <= A - B;
                end
                valid <= 1;
                state <= 0;
            end
            2: begin // multiplication
                mul <= A * B;
                state <= 3;
            end
            3: begin // multiplication result
                out <= mul[15:8];
                valid <= 1;
                state <= 4;
            end
            4: begin // multiplication result
                out <= mul[7:0];
                valid <= 1;
                state <= 0;
            end
            5: begin // division
                if (B == 0) begin // divide by zero error
                    out <= 0;
                    valid <= 0;
                    state <= 0;
                end else begin
                    div <= A / B;
                    state <= 6;
                end
            end
            6: begin // division result
                out <= div;
                valid <= 1;
                state <= 0;
            end
        endcase
    end
end

endmodule

module datapath_m(
	input clock, reset,
	input [7:0] dividend, divisor,
	input Load_regs, Dec_div,
	output reg [15:0] QR,
	output Zero
);
reg [7:0] AR, BR;
always @(posedge clock, posedge reset)
	if (reset) begin
		AR <= 8'b0;
		BR <= 8'b0;
		QR <= 16'b0;
	end else if (Load_regs) begin
		AR <= dividend;
		BR <= divisor;
		QR <= 16'b0;
	end else if (Dec_div) begin
		if (AR >= BR) begin
			AR <= AR - BR;
			QR <= QR + 1;
		end
	end

assign Zero = AR == 8'b0;
endmodule

module axi_protocol_converter_v2_1_b2s_wr_cmd_fsm (
///////////////////////////////////////////////////////////////////////////////
// Port Declarations
///////////////////////////////////////////////////////////////////////////////
  input  wire                                 clk           ,
  input  wire                                 reset         ,
  output wire                                 s_awready       ,
  input  wire                                 s_awvalid       ,
  output wire                                 m_awvalid        ,
  input  wire                                 m_awready      ,
  // signal to increment to the next mc transaction
  output wire                                 next          ,
  // signal to the fsm there is another transaction required
  input  wire                                 next_pending  ,
  // Write Data portion has completed or Read FIFO has a slot available (not
  // full)
  output wire                                 b_push        ,
  input  wire                                 b_full        ,
  output wire                                 a_push        ,
  output wire                                 w_valid       ,
  output wire [31:0]                          w_data
);

////////////////////////////////////////////////////////////////////////////////
// Local parameters
////////////////////////////////////////////////////////////////////////////////
// States
localparam SM_IDLE                = 3'b000;
localparam SM_CMD_EN              = 3'b001;
localparam SM_CMD_ACCEPTED        = 3'b010;
localparam SM_DONE_WAIT           = 3'b011;
localparam SM_DATA_TRANSFER       = 3'b100;

////////////////////////////////////////////////////////////////////////////////
// Wires/Reg declarations
////////////////////////////////////////////////////////////////////////////////
reg [2:0]       state;
// synthesis attribute MAX_FANOUT of state is 20;
reg [2:0]       next_state;

////////////////////////////////////////////////////////////////////////////////
// BEGIN RTL
///////////////////////////////////////////////////////////////////////////////


always @(posedge clk) begin
  if (reset) begin
    state <= SM_IDLE;
  end else begin
    state <= next_state;
  end
end

// Next state transitions.
always @( * )
begin
  next_state = state;
  case (state)
    SM_IDLE:
      if (s_awvalid) begin
        next_state = SM_CMD_EN;
      end else
        next_state = state;

    SM_CMD_EN:
      if (m_awready & next_pending)
        next_state = SM_CMD_ACCEPTED;
      else if (m_awready & ~next_pending & b_full)
        next_state = SM_DONE_WAIT;
      else if (m_awready & ~next_pending & ~b_full)
        next_state = SM_IDLE;
      else if (s_awvalid & m_awvalid)
        next_state = SM_DATA_TRANSFER;
      else
        next_state = state;

    SM_CMD_ACCEPTED:
      next_state = SM_CMD_EN;

    SM_DONE_WAIT:
      if (!b_full)
        next_state = SM_IDLE;
      else
        next_state = state;

    SM_DATA_TRANSFER:
      if (m_awready)
        next_state = SM_IDLE;
      else
        next_state = state;

      default:
        next_state = SM_IDLE;
  endcase
end

// Assign outputs based on current state.
assign m_awvalid  = (state == SM_CMD_EN);
assign next    = ((state == SM_CMD_ACCEPTED)
                 | (((state == SM_CMD_EN) | (state == SM_DONE_WAIT) | (state == SM_DATA_TRANSFER)) & (next_state == SM_IDLE))) ;
assign a_push  = (state == SM_IDLE);
assign s_awready = ((state == SM_CMD_EN) | (state == SM_DONE_WAIT) | (state == SM_DATA_TRANSFER)) & (next_state == SM_IDLE);
assign b_push  = ((state == SM_CMD_EN) | (state == SM_DONE_WAIT) | (state == SM_DATA_TRANSFER)) & (next_state == SM_IDLE);

// Data transfer in SM_DATA_TRANSFER state
always @(posedge clk) begin
  if (state == SM_DATA_TRANSFER) begin
    w_valid <= 1'b1;
    w_data <= s_wdata;
  end else begin
    w_valid <= 1'b0;
    w_data <= 32'h0;
  end
end

endmodule

module clkgen
(
	// Main clocks in, depending on board
	input	sys_clk_pad_i,
	// Asynchronous, active low reset in
	input	rst_n_pad_i,
	// Input reset - through a buffer, asynchronous
	output	async_rst_o,

	// Wishbone clock and reset out  
	output	wb_clk_o,
	output	wb_rst_o,

	// Main memory clocks
	output	sdram_clk_o,
	output	sdram_rst_o
);

// First, deal with the asychronous reset
wire	async_rst;
wire	async_rst_n;

assign	async_rst_n  = rst_n_pad_i;
assign	async_rst  = ~async_rst_n;

// Everyone likes active-high reset signals...
assign	async_rst_o = ~async_rst_n;

//
// Declare synchronous reset wires here
//

// An active-low synchronous reset signal (usually a PLL lock signal)
wire   sync_rst_n;

wire   pll_lock;

// Generate PLL for sdram and wishbone clocks
pll pll0 
(
	.areset	(async_rst),
	.inclk0	(sys_clk_pad_i),
	.c0	(sdram_clk_o),
	.c1	(wb_clk_o),
	.locked	(pll_lock)
);

// Generate synchronous reset signal from PLL lock signal
assign sync_rst_n = pll_lock;

// Reset generation for wishbone
reg [15:0]	wb_rst_shr;

always @(posedge wb_clk_o or posedge async_rst)
	if (async_rst)
		wb_rst_shr <= 16'hffff;
	else
		wb_rst_shr <= {wb_rst_shr[14:0], ~(sync_rst_n)};

assign wb_rst_o = wb_rst_shr[15];


// Reset generation for SDRAM controller
reg [15:0]	sdram_rst_shr;

always @(posedge sdram_clk_o or posedge async_rst)
	if (async_rst)
		sdram_rst_shr <= 16'hffff;
	else
		sdram_rst_shr <= {sdram_rst_shr[14:0], ~(sync_rst_n)};

assign sdram_rst_o = sdram_rst_shr[15];

endmodule

module ECC_Memory_Block (
  input [k-1:0] data_in,
  output [n-1:0] data_out
);

parameter k = 8; // number of data bits
parameter n = 12; // number of bits (including redundant bits)

// Calculate the number of redundant bits needed
parameter r = ceil(log2(k+1));

// Define internal signals
wire [r-1:0] parity_bits;
wire [k+r-1:0] encoded_data;
wire [k-1:0] decoded_data;
wire error_detected;

// Generate parity bits using Hamming code algorithm
genvar i;
generate
  for (i = 0; i < r; i = i + 1) begin : parity_gen
    assign parity_bits[i] = ^(data_in & (1 << i) ? 1 : 0);
  end
endgenerate

// Concatenate data with parity bits to create encoded data
assign encoded_data = {data_in, parity_bits};

// Check for errors and correct if necessary
assign error_detected = ^(encoded_data & ((1 << r) - 1));
assign decoded_data = error_detected ? encoded_data ^ (1 << (r - 1 - $ffs(encoded_data & ((1 << r) - 1)))) : data_in;

// Concatenate decoded data with parity bits to create output data
assign data_out = {decoded_data, parity_bits};

endmodule

module afifo_sram (
    input CLK,
    input REN,
    input WEN,
    input RESET,
    input valid_in,
    input [WIDTH-1:0] Data_in,
    output reg [WIDTH-1:0] Data_out,
    output reg Full_out,
    output reg Empty_out
);

parameter DEPTH =256, ADDRESS_WIDTH = 8, WIDTH=8;

reg [ADDRESS_WIDTH-1:0] read_ptr;
reg [ADDRESS_WIDTH-1:0] write_ptr;
wire [ADDRESS_WIDTH-1:0] next_write_ptr;
wire [ADDRESS_WIDTH-1:0] next_read_ptr;
wire [ADDRESS_WIDTH-1:0] mem_addr;
reg [WIDTH-1:0] mem [DEPTH-1:0];
wire [WIDTH-1:0] mem_out;

assign mem_addr = REN ? read_ptr : write_ptr;
assign mem_out = mem[mem_addr];

assign Full_out = (next_write_ptr == read_ptr);
assign Empty_out = (write_ptr == read_ptr);

always @(posedge CLK) begin
    if (RESET) begin
        read_ptr <= 0;
        write_ptr <= 0;
        Full_out <= 0;
        Empty_out <= 1;
        mem <= 0;
    end else begin
        if (WEN && !Full_out) begin
            mem[write_ptr] <= Data_in;
            write_ptr <= next_write_ptr;
        end
        if (REN && !Empty_out && valid_in) begin
            Data_out <= mem_out;
            read_ptr <= next_read_ptr;
        end
        Full_out <= (next_write_ptr == read_ptr);
        Empty_out <= (write_ptr == next_read_ptr);
    end
end

assign next_write_ptr = (write_ptr == DEPTH-1) ? 0 : write_ptr + 1;
assign next_read_ptr = (read_ptr == DEPTH-1) ? 0 : read_ptr + 1;

endmodule

module binary_to_gray (
  input clk,
  input [3:0] binary,
  output reg [3:0] gray,
  output reg match
);

  reg [3:0] next_gray;
  reg [2:0] state;

  always @(posedge clk) begin
    case(state)
      3'b000: begin // State 0 - Initialize
        next_gray <= binary;
        gray <= binary;
        match <= 1'b0;
        state <= 3'b001;
      end
      3'b001: begin // State 1 - Bit 3
        next_gray[3] <= binary[3] ^ binary[2];
        state <= 3'b010;
      end
      3'b010: begin // State 2 - Bit 2
        next_gray[2] <= binary[2] ^ binary[1];
        state <= 3'b011;
      end
      3'b011: begin // State 3 - Bit 1
        next_gray[1] <= binary[1] ^ binary[0];
        state <= 3'b100;
      end
      3'b100: begin // State 4 - Bit 0
        next_gray[0] <= binary[0];
        gray <= next_gray;
        if (next_gray == 4'b0101) begin // Check for match
          match <= 1'b1;
        end else begin
          match <= 1'b0;
        end
        state <= 3'b001;
      end
    endcase
  end

endmodule

module top_module (
    input clk,
    input reset,
    input [7:0] a,
    input [7:0] b,
    output [7:0] abs_sum
);

wire [7:0] abs_a, abs_b;

absolute_value abs_val_a (
    .a(a),
    .abs_a(abs_a)
);

absolute_value abs_val_b (
