    .abs_b(abs_b)
);

abs_sum_module sum_module (
    .abs_a(abs_a),
    .abs_b(abs_b),
    .abs_sum(abs_sum)
);

endmodule

module absolute_value (
    input [7:0] a,
    output [7:0] abs_a
);
    assign abs_a = a[7] ? -a : a;
endmodule

module add_sub_overflow (
    input [7:0] a,
    input [7:0] b,
    input subtract,
    output [7:0] sum,
    output carry
);
    wire [8:0] result;
    assign result = subtract ? a - b : a + b;
    assign sum = result[7:0];
    assign carry = result[8];
endmodule

