module soc_system_led_pio (
  input [1:0] address,
  input chipselect,
  input clk,
  input reset_n,
  input write_n,
  input [31:0] writedata,
  output reg [9:0] out_port,
  output reg [31:0] readdata
);

  reg [9:0] data_out;
  reg [9:0] read_mux_out;

  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      data_out <= 10'b1111;
    end else if (!chipselect) begin
      if (!write_n) begin
        case (address)
          2'b00: data_out[9:0] <= writedata[9:0];
          default: data_out[9:0] <= data_out[9:0];
        endcase
      end else begin
        case (address)
          2'b00: read_mux_out[9:0] <= data_out[9:0];
          default: read_mux_out[9:0] <= 10'b0;
        endcase
      end
    end

    out_port <= data_out;
    readdata <= { 22'b0, read_mux_out };
  end

endmodule

module rs232 (
    input clk,
    input resetn,
    input [3:0] ctrl_wr,
    input ctrl_rd,
    input [15:0] ctrl_addr,
    input [31:0] ctrl_wdat,
    output reg [31:0] ctrl_rdat,
    output reg ctrl_done,
    input rxd,
    output reg txd
);
    parameter integer BAUD_RATE = 115200;
    parameter integer CLOCK_FREQ_HZ = 50000000;
    localparam integer HALF_PERIOD = CLOCK_FREQ_HZ / (2 * BAUD_RATE);

    reg [7:0] send_din;
    wire [7:0] send_dout;
    reg send_shift_in;
    reg send_shift_out;
    wire [7:0] send_used_slots;
    wire [7:0] send_free_slots;

    reg [7:0] recv_din;
    wire [7:0] recv_dout;
    reg recv_shift_in;
    reg recv_shift_out;
    wire [7:0] recv_used_slots;
    wire [7:0] recv_free_slots;

    reg [$clog2(3*HALF_PERIOD):0] rx_cnt;
    reg [3:0] rx_state;
    reg rxd_q;

    always @(posedge clk) begin
        rxd_q <= rxd;
        recv_shift_in <= 0;

        if (!resetn) begin
            rx_state <= 0;
            rx_cnt <= 0;
        end else
        if (rx_cnt) begin
            rx_cnt <= rx_cnt - |1;
        end else
        if (rx_state == 0) begin
            if (rxd_q && !rxd) begin
                rx_state <= rx_state + |1;
                rx_cnt <= 3*HALF_PERIOD;
            end
        end else begin
            recv_din <= {rxd, recv_din[7:1]};
            rx_state <= rx_state + |1;
            rx_cnt <= 2*HALF_PERIOD;

            if (rx_state == 8) begin
                recv_shift_in <= 1;
                rx_state <= 0;
            end
        end
    end

    reg [$clog2(2*HALF_PERIOD):0] tx_cnt;
    reg [3:0] tx_state;
    reg [7:0] tx_byte;

    always @(posedge clk) begin
        send_shift_out <= 0;
        if (!resetn) begin
            txd <= 1;
            tx_state <= 0;
            tx_cnt <= 0;
        end else
        if (tx_cnt) begin
            tx_cnt <= tx_cnt - |1;
        end else
        if (tx_state == 0) begin
            if (|send_used_slots) begin
                txd <= 0;
                send_shift_out <= 1;
                tx_byte <= send_dout;
                tx_cnt <= 2*HALF_PERIOD;
                tx_state <= 1;
            end
        end else begin
            txd <= tx_byte[0];
            tx_byte <= tx_byte[7:1];
            tx_cnt <= 2*HALF_PERIOD;
            tx_state <= tx_state + |1;

            if (tx_state == 9) begin
                txd <= 1;
                tx_state <= 0;
            end
        end
    end

    icosoc_mod_rs232_fifo send_fifo (
        .clk       (clk            ),
        .resetn    (resetn         ),
        .din       (send_din       ),
        .dout      (send_dout      ),
        .shift_in  (send_shift_in  ),
        .shift_out (send_shift_out ),
        .used_slots(send_used_slots),
        .free_slots(send_free_slots)
    );

    icosoc_mod_rs232_fifo recv_fifo (
        .clk       (clk            ),
        .resetn    (resetn         ),
        .din       (recv_din       ),
        .dout      (recv_dout      ),
        .shift_in  (recv_shift_in  ),
        .shift_out (recv_shift_out ),
        .used_slots(recv_used_slots),
        .free_slots(recv_free_slots)
    );

    always @(posedge clk) begin
        ctrl_rdat <= 'bx;
        ctrl_done <= 0;

        recv_shift_out <= 0;
        send_shift_in <= 0;
        send_din <= 'bx;

        // Register file:
        //   0x00 shift data to/from send/recv fifos
        //   0x04 number of unread bytes in recv fifo (read-only)
        //   0x08 number of free bytes in send fifo (read-only)
        if (resetn && !ctrl_done) begin
            if (|ctrl_wr) begin
                if (ctrl_addr == 0) begin
                    send_shift_in <= 1;
                    send_din <= ctrl_wdat;
                end
                ctrl_done <= 1;
            end
            if (ctrl_rd) begin
                if (ctrl_addr == 0) begin
                    recv_shift_out <= 1;
                    ctrl_rdat <= recv_dout;
                end
                if (ctrl_addr == 4) ctrl_rdat <= recv_used_slots;
                if (ctrl_addr == 8) ctrl_rdat <= send_free_slots;
                ctrl_done <= 1;
            end
        end
    end
endmodule

module decoder_3to4_pipeline(
    input a, b, c,
    output reg w, x, y, z
);

reg [2:0] input_reg;
reg [3:0] output_reg;

always @(posedge clk) begin
    input_reg <= {c, b, a};
end

always @(posedge clk) begin
    case(input_reg)
        3'b000: output_reg <= 4'b0001;
        3'b001: output_reg <= 4'b0010;
        3'b010: output_reg <= 4'b0100;
        3'b011: output_reg <= 4'b1000;
        3'b100: output_reg <= 4'b0000;
        3'b101: output_reg <= 4'b0000;
        3'b110: output_reg <= 4'b0000;
        3'b111: output_reg <= 4'b0000;
    endcase
end

always @(posedge clk) begin
    w <= output_reg[0];
    x <= output_reg[1];
    y <= output_reg[2];
    z <= output_reg[3];
end

endmodule

module communication_system (
