  output [39:0] pe_channel_dout,
  output [1:0] pe_diff_pair_dout,
  output r2pe_ack_dout
);

reg [47:0] south_channel_dout_reg;
reg [1:0] south_diff_pair_dout_reg;
reg [47:0] west_channel_dout_reg;
reg [1:0] west_diff_pair_dout_reg;
reg [39:0] pe_channel_dout_reg;
reg [1:0] pe_diff_pair_dout_reg;
