    west_diff_pair_dout_reg <= 2'b0;
    pe_channel_dout_reg <= 40'b0;
    pe_diff_pair_dout_reg <= 2'b0;
    r2pe_ack_dout_reg <= 1'b1;
  end else begin
    case (north_diff_pair_din)
      2'b01: begin
        south_channel_dout_reg <= north_channel_din;
        south_diff_pair_dout_reg <= 2'b01;
      end
      2'b10: begin
