assign west_channel_dout = west_channel_dout_reg;
assign west_diff_pair_dout = west_diff_pair_dout_reg;
assign pe_channel_dout = pe_channel_dout_reg;
assign pe_diff_pair_dout = pe_diff_pair_dout_reg;
