module add_subtract_4bit(
    input [3:0] A,
    input [3:0] B,
    input S,
    output [3:0] Y
);

    wire [3:0] A_inv;
    wire [3:0] B_inv;
    wire [3:0] B_neg;
    wire [3:0] sum;

    // Invert A and B if S = 1 (subtraction)
    xor(S, 1'b1, A_inv);
    xor(S, 1'b1, B_inv);

    // Negate B if S = 1 (subtraction)
    add_subtract_1bit sub1bit(
        .A(B_inv[0]),
        .B(1'b1),
        .S(S),
        .Y(B_neg[0])
    );
    add_subtract_1bit sub1bit1(
        .A(B_inv[1]),
        .B(B_neg[0]),
        .S(S),
        .Y(B_neg[1])
    );
    add_subtract_1bit sub1bit2(
        .A(B_inv[2]),
        .B(B_neg[1]),
        .S(S),
        .Y(B_neg[2])
    );
    add_subtract_1bit sub1bit3(
        .A(B_inv[3]),
        .B(B_neg[2]),
        .S(S),
        .Y(B_neg[3])
    );

    // Calculate sum of A and B (or A and -B if S = 1)
    add_subtract_1bit add1bit0(
        .A(A_inv[0]),
        .B(B_neg[0]),
        .S(S),
        .Y(sum[0])
    );
    add_subtract_1bit add1bit1(
        .A(A_inv[1]),
        .B(B_neg[1]),
        .S(S),
        .Y(sum[1])
    );
    add_subtract_1bit add1bit2(
        .A(A_inv[2]),
        .B(B_neg[2]),
        .S(S),
        .Y(sum[2])
    );
    add_subtract_1bit add1bit3(
        .A(A_inv[3]),
        .B(B_neg[3]),
        .S(S),
        .Y(sum[3])
    );

    // Output sum
    assign Y = sum;

endmodule


module add_subtract_1bit(
    input A,
    input B,
    input S,
    output Y
);

    wire xor_out;
    wire and_out;
    wire or_out;

    // Calculate XOR, AND, and OR of A and B
    xor(xor_out, A, B);
    and(and_out, A, B);
    or(or_out, A, B);

    // Calculate Y based on S input
    assign Y = (S == 1'b0) ? xor_out : ~xor_out + 1'b1;

    // Add carry bit to Y if S = 0 and carry bit exists
    assign Y = (S == 1'b0 && and_out == 1'b1) ? Y + 1'b1 : Y;

endmodule

module d_latch (
