module spi_interface (
    input wire mosi,
    output wire miso,
    input wire sclk,
    input wire ss,
    input wire reset,
    input wire clock,
    output wire rx_interrupt,
    output wire tx_interrupt,
    output wire sdat
);

parameter BidirectMode = 0;
parameter HighSpeedMode = 1;
parameter NumberOfDataBits = 8;
parameter ShiftDir = 0;

reg [NumberOfDataBits-1:0] tx_data;
reg [NumberOfDataBits-1:0] rx_data;

reg [NumberOfDataBits-1:0] shift_reg;
reg [NumberOfDataBits-1:0] rx_shift_reg;

reg [NumberOfDataBits-1:0] bit_count;

reg [NumberOfDataBits-1:0] idle_data;

reg [NumberOfDataBits-1:0] tx_count;
reg [NumberOfDataBits-1:0] rx_count;

reg tx_ready;
reg rx_ready;

reg [1:0] state;

assign sdat = tx_data[NumberOfDataBits-1];

always @(posedge clock) begin
    if (!reset) begin
        tx_ready <= 1'b0;
        rx_ready <= 1'b0;
        state <= 2'b00;
        tx_count <= 0;
        rx_count <= 0;
        bit_count <= 0;
        shift_reg <= 0;
        rx_shift_reg <= 0;
    end else begin
        case (state)
            2'b00: begin // idle state
                if (ss == 1'b0) begin
                    tx_ready <= 1'b1;
                    state <= 2'b01;
                end else begin
                    tx_ready <= 1'b0;
                    state <= 2'b00;
                end
            end
            2'b01: begin // transmit state
                if (tx_ready && ss == 1'b0) begin
                    tx_data <= mosi;
                    tx_count <= 1;
                    tx_ready <= 1'b0;
                    state <= 2'b10;
                end else begin
                    tx_ready <= 1'b0;
                    state <= 2'b01;
                end
            end
            2'b10: begin // shift out state
                if (sclk == 1'b1) begin
                    shift_reg <= {shift_reg[NumberOfDataBits-2:0], tx_data[NumberOfDataBits-1]};
                    bit_count <= bit_count + 1;
                end
                if (bit_count == NumberOfDataBits) begin
                    bit_count <= 0;
                    tx_ready <= 1'b0;
                    state <= 2'b11;
                end
            end
            2'b11: begin // wait for receive state
                if (sclk == 1'b0) begin
                    rx_ready <= 1'b1;
                    state <= 2'b00;
                end
            end
        endcase
    end
end

always @(posedge clock) begin
    if (!reset) begin
        miso <= 1'b0;
    end else begin
        case (state)
            2'b00: begin // idle state
                miso <= 1'b0;
            end
            2'b01: begin // transmit state
                miso <= idle_data[NumberOfDataBits-1];
            end
            2'b10: begin // shift out state
                miso <= shift_reg[NumberOfDataBits-1];
            end
            2'b11: begin // wait for receive state
                miso <= 1'b0;
            end
        endcase
    end
end

always @(posedge clock) begin
    if (!reset) begin
        rx_ready <= 1'b0;
    end else begin
        case (state)
            2'b00: begin // idle state
                rx_ready <= 1'b0;
            end
            2'b01: begin // transmit state
                rx_ready <= 1'b0;
            end
            2'b10: begin // shift out state
                rx_shift_reg <= {rx_shift_reg[NumberOfDataBits-2:0], miso};
                rx_count <= rx_count + 1;
                if (rx_count == NumberOfDataBits) begin
                    rx_count <= 0;
                    rx_ready <= 1'b1;
                    state <= 2'b11;
                end
            end
            2'b11: begin // wait for receive state
                rx_ready <= 1'b0;
            end
        endcase
    end
end

always @(posedge clock) begin
    if (!reset) begin
        idle_data <= {NumberOfDataBits{1'b0}};
    end else begin
        case (ShiftDir)
            1'b0: idle_data <= {NumberOfDataBits{1'b0}};
            1'b1: idle_data <= {NumberOfDataBits{1'b1}};
        endcase
    end
end

assign rx_interrupt = rx_ready;
assign tx_interrupt = tx_ready;

endmodule

