module bitwise_logic (
  input [n-1:0] a,
  input [n-1:0] b,
  input and_en,
  input or_en,
  input xor_en,
  input not_en,
  input inv_en,
  output reg [n-1:0] and_out,
  output reg [n-1:0] or_out,
  output reg [n-1:0] xor_out,
  output reg [n-1:0] not_out
);

parameter n = 4; // number of bits in the input and output signals

// AND operation
always @ (a, b, and_en)
begin
  if (and_en)
    and_out = a & b;
  else
    and_out = 0;
end

// OR operation
always @ (a, b, or_en)
begin
  if (or_en)
    or_out = a | b;
  else
    or_out = 0;
end

// XOR operation
always @ (a, b, xor_en)
begin
  if (xor_en)
    xor_out = a ^ b;
  else
    xor_out = 0;
end

// NOT operation
always @ (a, not_en)
begin
  if (not_en)
  begin
    if (inv_en)
      not_out = ~a;
    else
      not_out = !a;
  end
  else
    not_out = 0;
end

endmodule

module registros_salida( 
	input Write_Strobe,
	input [7:0] Out_Port,
	input [7:0] Port_ID,
	input rst,
	input reset,
	input clk,
	output reg [7:0] Dir,
	output reg [7:0] Dato,
	output reg [3:0] direccion,
	output reg contro_listo,
	output reg contro_lee,
	output reg contro_escribe,
	output reg [2:0]bandera
);

	// Initialize all outputs to their default values
	always @(posedge clk)
	begin
		if (reset)
		begin
			contro_listo <= 1'b0;
			contro_escribe <= 1'b0;
			contro_lee <= 1'b0;
			Dir <= 8'b00000000;
			Dato <= 8'b00000000;
			direccion <= 4'b0000;
			bandera <= 3'b0;
		end
	end

	// Update the outputs when Write_Strobe is high
	always @(posedge clk)
	begin
		if (Write_Strobe)
		begin
			case (Port_ID)
				8'b00000001: // Control Listo
				begin
					if (rst)
						contro_listo <= 1'b0;
					else
					begin
						if (Out_Port == 8'b00000001)
						begin
							contro_listo <= 1'b1;
							contro_lee <= 1'b0;
							contro_escribe <= 1'b0;
						end
						else 
						begin
							contro_listo <= 1'b0;
							contro_lee <= contro_lee;
							contro_escribe <= contro_escribe;
						end
					end
				end
				8'b00000010: // Control Escribe
				begin
					if (rst)
						contro_escribe <= 1'b0;
					else
					begin
						if (Out_Port == 8'b00000001)
						begin
							contro_escribe <= 1'b1;
							contro_lee <= 1'b0;
							contro_listo <= 1'b0;
						end
						else 
						begin
							contro_escribe <= 1'b0;
							contro_lee <= contro_lee;
							contro_listo <= contro_listo;
						end
					end
				end
				8'b00000011: // Control Lee
				begin
					if (rst)
						contro_lee <= 1'b0;
					else
					begin
						if (Out_Port == 8'b00000001)
						begin
							contro_lee <= 1'b1;
							contro_listo <= 1'b0;
							contro_escribe <= 1'b0;
						end
						else 
						begin
							contro_lee <= 1'b0;
							contro_listo <= contro_listo;
							contro_escribe <= contro_escribe;
						end
					end
				end
				8'b00000100: // Dato
				begin
					Dato <= Out_Port;
				end
				8'b00000101: // Dir
				begin
					Dir <= Out_Port;
					if (Out_Port == 8'hf1)
						bandera <= 3'b1;
					else
						bandera <= 3'b0;
				end
				8'b00000110: // Direccion
				begin
					case (Out_Port)
						8'b00000000: direccion <= 4'b0000;
						8'b00000001: direccion <= 4'b0001;
						8'b00000010: direccion <= 4'b0010;
						8'b00000011: direccion <= 4'b0011;
						8'b00000100: direccion <= 4'b0100;
						8'b00000101: direccion <= 4'b0101;
						8'b00000110: direccion <= 4'b0110;
						8'b00000111: direccion <= 4'b0111;
						8'b00001000: direccion <= 4'b1000;
						default: direccion <= direccion;
					endcase
				end
				default: // Do nothing
				begin
					contro_listo <= contro_listo;
					contro_lee <= contro_lee;
					contro_escribe <= contro_escribe;
					direccion <= direccion;
					Dir <= Dir;
					Dato <= Dato;
					bandera <= bandera;
				end
			endcase
		end
	end

	// Reset the control signals when rst is high
	always @(posedge clk)
	begin
		if (rst)
		begin
			contro_listo <= 1'b0;
			contro_lee <= 1'b0;
			contro_escribe <= 1'b0;
		end
	end
endmodule

module DCA_CONTROL ( BCLK, MCLK, BRESET, CUPDATE, DRAM_ACC, CA_SET, HIT_ALL, WRCFG, VADR_R, UPDATE, INVAL_A, WRITE,
                     WCTRL, KILL, WRCRAM0, WRCRAM1, WE_CV, WADR_CV, DAT_CV, INIT_CA_RUN, WRSET0, WRSET1 );

input           BCLK;
input           MCLK;
input           BRESET;
input           CUPDATE;
input           DRAM_ACC;
input           CA_SET;
input           HIT_ALL;
input           WRCFG;
input   [11:7] VADR_R;
input   [23:0] UPDATE;
input           INVAL_A;
input           WRITE;
input    [1:0] WCTRL;
input           KILL;

output          WRCRAM0,WRCRAM1;
output          WE_CV;
output  [4:0]   WADR_CV;
output  [23:0]  DAT_CV;
output          INIT_CA_RUN;
output          WRSET0,WRSET1;

reg     [1:0]   state;
reg     [4:0]   acount;
reg             ca_set_d;

reg             dly_bclk,zero,wr_puls;
reg     [2:0]   count,refer;

wire            countf;

assign WRCRAM0 = (CUPDATE & ~WCTRL[0]) & ~CA_SET;
assign WRCRAM1 = (CUPDATE & ~WCTRL[0]) &  CA_SET;

assign WE_CV   = state[1] | HIT_ALL | (CUPDATE & ~WCTRL[0]) | KILL;
assign WADR_CV = state[1] ? acount : VADR_R;
assign DAT_CV  = state[1] ? 24'h0 : UPDATE;

assign countf  = (acount == 5'h1F);

always @(posedge BCLK)
    casex ({BRESET,INVAL_A,countf,state[1:0]})
        5'b0xx_xx : state <= 2'b01;
        5'b1xx_01 : state <= 2'b10;
        5'b10x_00 : state <= 2'b00;
        5'b11x_00 : state <= 2'b10;
        5'b1x0_10 : state <= 2'b10;
        5'b1x1_10 : state <= 2'b00;
        default   : state <= 2'b0;
    endcase

always @(posedge BCLK) if (!state[1]) acount <= 5'h0; else acount <= acount + 5'h01;

assign INIT_CA_RUN = state[1];

always @(posedge BCLK) if (DRAM_ACC) ca_set_d <= CA_SET;

assign WRSET0 = (~CA_SET & WRITE & HIT_ALL & wr_puls) | (WCTRL[1] & ~ca_set_d);
assign WRSET1 = ( CA_SET & WRITE & HIT_ALL & wr_puls) | (WCTRL[1] &  ca_set_d);

always @(negedge MCLK) dly_bclk <= BCLK;

always @(negedge MCLK) zero <= BCLK & ~dly_bclk;

always @(posedge MCLK) if (zero) count <= 3'd0; else count <= count + 3'd1;

always @(posedge MCLK) refer <= {(count == 3'd7),((count == 3'd5) | (count[1:0] == 2'b10)),(count[2] & ~count[0])};

always @(posedge MCLK) wr_puls <= (count == refer) | WRCFG;

endmodule

module top_module (
    input [7:0] in,
    input clk,
    output reg [9:0] out
);

    // Odd parity bit generator
    reg [7:0] data_in;
    reg parity;
    always @(posedge clk) begin
        data_in <= in;
        parity <= ~(^data_in);
    end

    // Priority encoder
    wire [2:0] position;
    assign position = (in == 8'b00000000) ? 3'b000 : $priority_encoder(in);

    // Final output
    always @(posedge clk) begin
        out[8] <= parity;
        out[7:5] <= position;
        out[4:0] <= 5'b00000;
    end

endmodule

