module binary_display(
    input clk,
    input [3:0] data
);

reg [3:0] prev_data;
reg [3:0] data_count;
reg display_enable;

always@(posedge clk) begin
    if(data == prev_data) begin
        data_count <= data_count + 1;
    end else begin
        data_count <= 0;
    end

    if(data_count == 9) begin
        display_enable <= 1;
        data_count <= 0;
    end else if(data_count == 0) begin
        display_enable <= 0;
    end

    prev_data <= data;
end

integer count = 0;

always@(posedge clk) begin
    if(display_enable) begin
        if(count == 0) begin
            $fdisplay($time, "Binary format: %b", data);
        end

        count <= count + 1;

        if(count == 10) begin
            count <= 0;
        end
    end
end

endmodule

module sram (
              inout  [15:0] SRAM_DQ, 
              input  [17:0] SRAM_ADDR,
              input         SRAM_UB_N,
              input         SRAM_LB_N,
              input         SRAM_WE_N,
              input         SRAM_CE_N,
              input         SRAM_OE_N
             );

reg     [7:0] mem[`MEMSIZEBYTES-1:0];

wire [`MEMBYTEADDRBITS-1:0] byte_addr0 = {SRAM_ADDR, 1'b0};
wire [`MEMBYTEADDRBITS-1:0] byte_addr1 = {SRAM_ADDR, 1'b1};

wire   sram_read = ~SRAM_CE_N & ~SRAM_OE_N;

// DQ tristate control. Only drive if chip selected and output enable active.
assign SRAM_DQ   = {(~sram_read | SRAM_UB_N) ? 8'hzz : mem[byte_addr1], 
                    (~sram_read | SRAM_LB_N) ? 8'hzz : mem[byte_addr0]};

always @(*)
begin
  // Write to memory if chip selected, WE active and one or more 
  // byte enables active.
  if (~SRAM_CE_N & ~SRAM_WE_N)
  begin
    if (~SRAM_LB_N)
      mem[byte_addr0]   = SRAM_DQ [7:0];

    if (~SRAM_UB_N)
      mem[byte_addr1]   = SRAM_DQ [15:8];
  end
end

endmodule

