module binary_tree_adder(
    input [1:0] in, 
    output [1:0] out ); 

    wire [1:0] sum1, sum2; 

    xor_gate x1( .a(in[0]), .b(in[1]), .c(sum1[0]) ); 
    xor_gate x2( .a(sum1[0]), .b(in[0]), .c(sum2[0]) ); 
    xor_gate x3( .a(sum1[0]), .b(in[1]), .c(sum2[1]) ); 
    xor_gate x4( .a(sum2[0]), .b(sum2[1]), .c(out[0]) ); 
    xor_gate x5( .a(sum1[1]), .b(in[0]), .c(out[1]) ); 

endmodule 

module parity_checker(
    input [3:0] in, 
    output out ); 

    wire [1:0] xor_out; 
    wire [1:0] adder_out; 

    xor_gate x1( .a(in[0]), .b(in[1]), .c(xor_out[0]) ); 
    xor_gate x2( .a(in[2]), .b(in[3]), .c(xor_out[1]) ); 

    binary_tree_adder bta( .in(xor_out), .out(adder_out) ); 

    xor_gate x3( .a(adder_out[0]), .b(adder_out[1]), .c(out) ); 

endmodule 

