    wire [7:0] rev_in1, rev_in2, mux_out;
    reverse_bits rb1(.in(in1), .out(rev_in1));
    reverse_bits rb2(.in(in2), .out(rev_in2));
    mux_4to1 mux(.in0(rev_in1), .in1(in1), .in2(rev_in2), .in3(in2), .sel(sel), .out(mux_out));
