module state_machine (
    input clk,
    input reset,
    input [2:0] state_i,
    output reg [2:0] state_r,
    output reg [7:0] ascii_r
);

localparam STATES = 7;

localparam
    IDLE        = 0, // '001
    READ        = 1, // '002
    THINK       = 2, // '004
    SEND        = 3, // '008
    WAIT        = 4, // '040
    GET_ACK     = 5, // '080
    WAIT_REGBUS = 6; // '100

reg [STATES-1:0] state_next;
reg [1:0] delay_count;

always @(posedge clk, posedge reset) begin
    if (reset) begin
        state_r <= state_i;
        ascii_r <= "idle       ";
    end else begin
        state_r <= state_next;
        case (state_r)
            IDLE: begin
                ascii_r <= "idle       ";
                if (clk) begin
                    state_next = READ;
                end
            end
            READ: begin
                ascii_r <= "read       ";
                if (!clk) begin
                    state_next = THINK;
                end
            end
            THINK: begin
                ascii_r <= "think      ";
                if (delay_count == 2) begin
                    state_next = SEND;
                    delay_count <= 0;
                end else begin
                    delay_count <= delay_count + 1;
                    state_next = THINK;
                end
            end
            SEND: begin
                ascii_r <= "send       ";
                if (clk) begin
                    state_next = WAIT;
                end
            end
            WAIT: begin
                ascii_r <= "wait       ";
                if (!clk) begin
                    state_next = GET_ACK;
                end
            end
            GET_ACK: begin
                ascii_r <= "get_ack    ";
                if (delay_count == 1) begin
                    state_next = WAIT_REGBUS;
                    delay_count <= 0;
                end else begin
                    delay_count <= delay_count + 1;
                    state_next = GET_ACK;
                end
            end
            WAIT_REGBUS: begin
                ascii_r <= "wait_regbus";
                if (clk) begin
                    state_next = IDLE;
                end
            end
        endcase
    end
end

endmodule

module fifo_buffer(
  clk,
  rst,
  din,
  wr_en,
  rd_en,
  dout,
  full,
  empty
);

input clk;
input rst;
input [7:0] din;
input wr_en;
input rd_en;
output [7:0] dout;
output full;
output empty;

reg [7:0] buffer [0:15];
reg [3:0] write_ptr;
reg [3:0] read_ptr;
reg full;
reg empty;

always @(posedge clk) begin
    if (rst) begin
        write_ptr <= 0;
        read_ptr <= 0;
        full <= 0;
        empty <= 1;
    end else begin
        if (wr_en && !full) begin
            buffer[write_ptr] <= din;
            write_ptr <= write_ptr + 1;
            if (write_ptr == 16) begin
                write_ptr <= 0;
            end
            if (write_ptr == read_ptr) begin
                full <= 1;
            end
            empty <= 0;
        end
        if (rd_en && !empty) begin
            dout <= buffer[read_ptr];
            read_ptr <= read_ptr + 1;
            if (read_ptr == 16) begin
                read_ptr <= 0;
            end
            if (read_ptr == write_ptr) begin
                empty <= 1;
            end
            full <= 0;
        end
    end
end

endmodule

