module nor_gate(
    input a,
    input b,
    output out
);
    wire nand1, nand2, nand3;

    // Implement NOR gate using NAND gates
    assign nand1 = ~(a & a);
    assign nand2 = ~(b & b);
    assign nand3 = ~(nand1 & nand2);
    assign out = ~(nand3 & nand3);
endmodule

module binary_counter_nor_gate(
    input clk,
    input reset,
    input a,
    input b,
    output out,
    output [3:0] q
);
    wire [3:0] counter;
    wire nor_out;

    // Instantiate 4-bit binary counter
    binary_counter counter_inst(
        .clk(clk),
        .reset(reset),
        .q(q)
    );

    // Instantiate NOR gate
    nor_gate nor_inst(
        .a(a),
        .b(b),
        .out(nor_out)
    );

    // Implement additive functional module
    assign out = nor_out & counter;
endmodule

