module top_module (
    input [7:0] in1, // First 8-bit binary number input
    input [7:0] in2, // Second 8-bit binary number input
    output [7:0] sum, // Output the sum of in1 and in2
    output [8:0] out // Output the parity bit of the sum using the Hamming code algorithm
);

    wire [7:0] adder_out; // Define a wire to store the output of the adder module

    adder adder_inst(.a(in1), .b(in2), .sum(adder_out)); // Instantiate the adder module

    assign sum = adder_out; // Assign the output of the adder module to the sum output port

    // Hamming code algorithm to calculate the parity bit
    wire [8:0] parity;
    assign parity[1] = adder_out[0] ^ adder_out[1] ^ adder_out[3] ^ adder_out[4] ^ adder_out[6];
    assign parity[2] = adder_out[0] ^ adder_out[2] ^ adder_out[3] ^ adder_out[5] ^ adder_out[6];
    assign parity[3] = adder_out[1] ^ adder_out[2] ^ adder_out[3] ^ adder_out[7];
    assign parity[4] = adder_out[4] ^ adder_out[5] ^ adder_out[6] ^ adder_out[7];
    assign out = {adder_out, parity}; // Concatenate the sum and parity bit and assign to the out output port

endmodule

module adder (
    input [7:0] a,
    input [7:0] b,
