  reg [3:0] block_count;
  reg timeout_enable;
  reg multiple_data;
  reg write_read;
  reg ack_out;
  reg [3:0] blocks_out;
  reg idle_out;
  reg strobe_out;
  reg transfer_complete;
  reg write_read_physical;

  always @(posedge CLK) begin
    if (RESET_L == 0) begin
      timeout_counter <= 0;
      block_count <= 0;
      timeout_enable <= 0;
      multiple_data <= 0;
      write_read <= 0;
      ack_out <= 0;
      blocks_out <= 0;
      idle_out <= 1;
      strobe_out <= 0;
      transfer_complete <= 0;
      write_read_physical <= 0;
    end else begin
      if (timeout_enable) begin
        if (timeout_counter < timeout_Reg_Regs_DATA) begin
          timeout_counter <= timeout_counter + 1;
        end else begin
          timeout_counter <= 0;
          timeout_enable <= 0;
          timeout_Phy_DATA <= 1;
        end
      end
      if (new_DAT_DMA_DATA && serial_Ready_Phy_DATA && !timeout_enable && !transfer_complete) begin
        timeout_counter <= 0;
        timeout_enable <= timeout_Enable_Regs_DATA;
        write_read <= writeRead_Regs_DATA;
        block_count <= blockCount_Regs_DATA;
        multiple_data <= multipleData_Regs_DATA;
        write_read_physical <= writeRead_Regs_DATA;
        blocks_out <= blockCount_Regs_DATA;
        idle_out <= 0;
        strobe_out <= 1;
      end
      if (ack_IN_Phy_DATA && !timeout_enable && !transfer_complete) begin
        if (block_count == 0) begin
          transfer_complete <= 1;
          idle_out <= 1;
        end else begin
          block_count <= block_count - 1;
          blocks_out <= block_count - 1;
          strobe_out <= 1;
        end
      end
      if (complete_Phy_DATA && !timeout_enable && !transfer_complete) begin
        idle_out <= 1;
      end
      if (fifo_OK_FIFO_DATA && !timeout_enable && !transfer_complete) begin
        ack_out <= 1;
      end
      timeout_value_DATA_Phy <= timeout_counter;
    end
  end

  assign ack_OUT_DATA_Phy = ack_out;
  assign blocks_DATA_Phy = blocks_out;
  assign multiple_DATA_Phy = multiple_data;
  assign strobe_OUT_DATA_Phy = strobe_out;
