module floating_point_arithmetic (
  input [31:0] a,
  input [31:0] b,
  input [1:0] op,
  output [31:0] result
);

  // Extracting sign, exponent, and mantissa of input a
  wire a_sign = a[31];
  wire [7:0] a_exponent = a[30:23];
  wire [22:0] a_mantissa = a[22:0];

  // Extracting sign, exponent, and mantissa of input b
  wire b_sign = b[31];
  wire [7:0] b_exponent = b[30:23];
  wire [22:0] b_mantissa = b[22:0];

  // Initializing variables for result calculation
  wire [31:0] result_mantissa;
  wire [7:0] result_exponent;
  wire result_sign;

  // Addition operation
  assign result_sign = a_sign ^ b_sign;
  always @* begin
    if (a_exponent > b_exponent) begin
      result_exponent = a_exponent;
      result_mantissa = {1'b1, a_mantissa} + {1'b0, b_mantissa >> (a_exponent - b_exponent)};
    end else begin
      result_exponent = b_exponent;
      result_mantissa = {1'b1, b_mantissa} + {1'b0, a_mantissa >> (b_exponent - a_exponent)};
    end
  end

  // Subtraction operation
  always @* begin
    if (a_exponent > b_exponent) begin
      result_exponent = a_exponent;
      result_mantissa = {1'b1, a_mantissa} - {1'b0, b_mantissa >> (a_exponent - b_exponent)};
    end else begin
      result_exponent = b_exponent;
      result_mantissa = {1'b1, b_mantissa} - {1'b0, a_mantissa >> (b_exponent - a_exponent)};
    end
    if (result_mantissa[23]) begin
      result_mantissa = ~result_mantissa + 1;
      result_sign = ~result_sign;
    end
  end

  // Multiplication operation
  always @* begin
    result_exponent = a_exponent + b_exponent - 127;
    result_mantissa = {a_mantissa[22], a_mantissa} * {b_mantissa[22], b_mantissa};
    if (result_mantissa[23]) begin
      result_mantissa = result_mantissa >> 1;
      result_exponent = result_exponent + 1;
    end
  end

  // Division operation
  always @* begin
    result_exponent = a_exponent - b_exponent + 127;
    result_mantissa = {a_mantissa[22], a_mantissa} / {b_mantissa[22], b_mantissa};
    if (result_mantissa[23]) begin
      result_mantissa = result_mantissa >> 1;
      result_exponent = result_exponent + 1;
    end
  end

  // Formatting result as a 32-bit floating-point number in IEEE 754 format
  assign result = {result_sign, result_exponent, result_mantissa[22:0]};

  // Selecting operation based on op input signal
  always @* begin
    case (op)
      2'b00: result = result; // Addition
      2'b01: result = result; // Subtraction
      2'b10: result = {result[31] ^ (a_sign ^ b_sign), result_exponent, result_mantissa[22:0]}; // Multiplication
      2'b11: result = {result[31] ^ (a_sign ^ b_sign), result_exponent, result_mantissa[22:0]}; // Division
    endcase
  end

endmodule

module control_reg_block (
  input [n-1:0] ctrl,
  output [m-1:0] line
);

parameter n = 4; // number of control signals
parameter m = 8; // number of control lines

reg [n-1:0] control_registers;
wire [m-1:0] control_lines;

// Define the control registers as Boolean functions of the input signals
always @ (ctrl) begin
  control_registers[0] = ctrl[0] & ctrl[1];
  control_registers[1] = ctrl[2] | ctrl[3];
  control_registers[2] = ctrl[0] ^ ctrl[2];
  control_registers[3] = ctrl[1] | ctrl[3];
end

// Define the control lines as Boolean functions of the control registers
assign control_lines[0] = control_registers[0] & control_registers[1];
assign control_lines[1] = control_registers[1] ^ control_registers[2];
assign control_lines[2] = control_registers[2] | control_registers[3];
assign control_lines[3] = control_registers[0] ^ control_registers[3];
assign control_lines[4] = control_registers[1] & control_registers[3];
assign control_lines[5] = control_registers[0] | control_registers[2];
assign control_lines[6] = control_registers[2] & control_registers[3];
assign control_lines[7] = control_registers[0] | control_registers[1];

// Assign the control lines to the output
assign line = control_lines;

endmodule

