                    dc_flit_count <= 2'b00;
                    dc_req_upload_state_reg <= 2'b00;
                    dc_req_upload_state <= 1'b0;
                end
                default: begin
                    dc_flit_reg <= 48'h0;
                    dc_flit_count <= 2'b00;
                    dc_req_upload_state_reg <= 2'b00;
                    dc_req_upload_state <= 1'b0;
                    v_dc_flit_out <= 1'b0;
                    dc_flit_out <= 16'h0;
                end
            endcase
        end
    end
