module signed_mag_comp (
    input signed [3:0] A,
    input signed [3:0] B,
    output reg C
);

reg [3:0] A_abs, B_abs;
reg [3:0] A_sign, B_sign;
reg [3:0] A_mag, B_mag;

wire [3:0] A_mag_reg, B_mag_reg;
wire [3:0] A_sign_reg, B_sign_reg;
wire [3:0] A_abs_reg, B_abs_reg;

assign A_mag_reg = A_mag;
assign B_mag_reg = B_mag;
assign A_sign_reg = A_sign;
assign B_sign_reg = B_sign;
assign A_abs_reg = A_abs;
assign B_abs_reg = B_abs;

// Pipeline Stage 1: Absolute Value Calculation
always @(*) begin
    if (A[3] == 1'b1) begin
        A_abs = ~A + 1;
    end else begin
        A_abs = A;
    end

    if (B[3] == 1'b1) begin
        B_abs = ~B + 1;
    end else begin
        B_abs = B;
    end
end

// Pipeline Stage 2: Sign Calculation
always @(*) begin
    if (A[3] == 1'b1) begin
        A_sign = 1'b1;
    end else begin
        A_sign = 1'b0;
    end

    if (B[3] == 1'b1) begin
        B_sign = 1'b1;
    end else begin
        B_sign = 1'b0;
    end
end

// Pipeline Stage 3: Magnitude Calculation
always @(*) begin
    if (A_abs > B_abs) begin
        A_mag = A_abs;
        B_mag = B_abs;
    end else begin
        A_mag = B_abs;
        B_mag = A_abs;
    end
end

// Pipeline Stage 4: Comparison
always @(posedge clk) begin
    if (A_mag_reg >= B_mag_reg) begin
        C <= 1'b1;
    end else begin
        C <= 1'b0;
    end
end

endmodule

module HazardCheckUnit(IDEXMemRead, IDEXRt, IFIDRs, IFIDRt, PCWrite, IFIDWrite, ctrlSetZero, IDEXRd, IDEXRegWrite, opcode, EXMEMRead, EXMEMRt, clk);

input [4:0] IDEXRt, IFIDRt, IFIDRs, IDEXRd, EXMEMRt;
input IDEXMemRead, IDEXRegWrite, EXMEMRead;
input [5:0] opcode;
input clk;
output reg PCWrite, IFIDWrite, ctrlSetZero;

always @ (posedge clk) begin
    if (opcode == 6'b000100) begin
        if (IDEXMemRead && ((IDEXRt == IFIDRs) || (IDEXRt == IFIDRt))) begin
            PCWrite <= 0;
            IFIDWrite <= 0;
            ctrlSetZero <= 1;
        end
        else if (IDEXRegWrite && ((IDEXRd == IFIDRs) || (IDEXRd == IFIDRt))) begin
            PCWrite <= 0;
            IFIDWrite <= 0;
            ctrlSetZero <= 1;
        end
        else if (EXMEMRead && ((EXMEMRt == IFIDRs) || (EXMEMRt == IFIDRt))) begin
            PCWrite <= 0;
            IFIDWrite <= 0;
            ctrlSetZero <= 1;
        end
        else begin
            PCWrite <= 1;
            IFIDWrite <= 1;
            ctrlSetZero <= 0;
        end
    end
    else begin
        if (IDEXMemRead && ((IDEXRt == IFIDRs) || (IDEXRt == IFIDRt))) begin
            PCWrite <= 0;
            IFIDWrite <= 0;
            ctrlSetZero <= 1;
        end
        else if (IDEXRegWrite && ((IDEXRd == IFIDRs) || (IDEXRd == IFIDRt))) begin
            PCWrite <= 0;
            IFIDWrite <= 0;
            ctrlSetZero <= 1;
        end
        else begin
            PCWrite <= 1;
            IFIDWrite <= 1;
            ctrlSetZero <= 0;
        end
    end
end

endmodule

module DDC (
  input [31:0] in_real,
  input [31:0] in_imag,
  input [31:0] f_shift,
  input [31:0] fs,
  output [31:0] out_real,
  output [31:0] out_imag
);
  reg [31:0] magnitude, phase;

  always @(*) begin
    magnitude = $sqrt(in_real * in_real + in_imag * in_imag);
    phase = $arctan(in_imag, in_real) - 2 * 32'h3F800000 * f_shift / fs;
    out_real = magnitude * $cosh(phase);
    out_imag = magnitude * $sinh(phase);
  end

endmodule

