module single_port_RAM (
  input clk, // clock signal
  input we, // write enable signal
  input [log2depth-1:0] addr, // address signal
  input [width-1:0] din, // input data
  output [width-1:0] dout // output data
);

parameter width = 8; // width of the data
parameter depth = 16; // depth of the memory
parameter log2depth = $clog2(depth); // log2 of the depth for indexing

// define memory array
reg [width-1:0] mem [0:depth-1];

// write data into the memory
always @(posedge clk) begin
  if (we) begin
    mem[addr] <= din;
  end
end

// read data from the memory
always @(posedge clk) begin
  if (!we) begin
    dout <= mem[addr];
  end
end
endmodule

module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output Cout,
    output [3:0] S
);

wire w1, w2, w3, w4, w5;

// Full Adder for bit 0
xor(w1, A[0], B[0]);
xor(S[0], w1, Cin);
and(w2, w1, Cin);
or(Cout, A[0] & B[0], w2);

// Full Adder for bit 1
xor(w3, A[1], B[1]);
xor(S[1], w3, w2);
and(w4, w3, w2);
or(w5, A[1] & B[1], w4);
or(Cout, Cout, w5);

// Full Adder for bit 2
xor(w1, A[2], B[2]);
xor(S[2], w1, w4);
and(w2, w1, w4);
or(w3, A[2] & B[2], w2);
or(Cout, Cout, w3);

// Full Adder for bit 3
xor(w4, A[3], B[3]);
xor(S[3], w4, w2);
and(Cout, w4, w2);

endmodule

module adder_4bit (
    input [3:0] a,
    input [3:0] b,
    input cin,
    output [3:0] sum,
    output cout
);

wire [3:0] sum_temp;
wire c1, c2, c3;

assign sum_temp[0] = a[0] ^ b[0] ^ cin;
assign sum_temp[1] = a[1] ^ b[1] ^ c1;
assign sum_temp[2] = a[2] ^ b[2] ^ c2;
assign sum_temp[3] = a[3] ^ b[3] ^ c3;

assign cout = c3;

assign sum = sum_temp;

assign c1 = (a[0] & b[0]) | (cin & a[0]) | (cin & b[0]);
assign c2 = (a[1] & b[1]) | (c1 & a[1]) | (c1 & b[1]);
assign c3 = (a[2] & b[2]) | (c2 & a[2]) | (c2 & b[2]) | (c1 & c2 & c3);

endmodule

module mux_priority_encoder (
    input [3:0] A, B, C, D,
    input reset,
    output [1:0] out,
    output valid
);
    reg [3:0] priority;
    always @* begin
        if (reset) begin
            priority = 4'b0000;
            out = 2'b00;
            valid = 0;
        end else begin
            if (A > B && A > C && A > D) begin
                priority = 4'b0001;
                out = 2'b00;
                valid = 1;
            end else if (B > A && B > C && B > D) begin
                priority = 4'b0010;
                out = 2'b01;
                valid = 1;
            end else if (C > A && C > B && C > D) begin
                priority = 4'b0100;
                out = 2'b10;
                valid = 1;
            end else if (D > A && D > B && D > C) begin
                priority = 4'b1000;
                out = 2'b11;
                valid = 1;
            end else begin
                priority = 4'b0000;
                out = 2'b00;
                valid = 0;
            end
        end
    end
endmodule

