    parameter IR = 2'b10;
    parameter RESET = 2'b11;

    parameter SHIFT_DR = 2'b00;
    parameter EXIT_DR = 2'b01;
    parameter UPDATE_DR = 2'b10;
    parameter SELECT_DR_SCAN = 2'b11;

    parameter SHIFT_IR = 2'b00;
    parameter EXIT_IR = 2'b01;
    parameter UPDATE_IR = 2'b10;
    parameter SELECT_IR_SCAN = 2'b11;

    reg [1:0] state;
    reg [1:0] dr_state;
    reg [1:0] ir_state;
    reg tdo_reg;

    assign tdo = tdo_reg;

    always @(posedge tck) begin
        if (ntrst) begin
            state <= RESET;
            dr_state <= IDLE;
            ir_state <= IDLE;
            tmsutap <= 1'b0;
            tckutap <= 1'b0;
            tdiutap <= 1'b0;
            shiftuser <= 1'b0;
            clkdruser <= 1'b0;
            updateuser <= 1'b0;
            runidleuser <= 1'b0;
            usr1user <= 1'b0;
        end else begin
            case (state)
                RESET: begin
                    state <= IDLE;
                end
                IDLE: begin
                    if (tms) begin
                        case (tdi)
                            1'b0: begin
                                state <= RESET;
                            end
                            1'b1: begin
                                state <= DR;
                            end
                        endcase
                    end
                end
                DR: begin
                    case (dr_state)
                        IDLE: begin
                            if (tms) begin
                                case (tdi)
                                    1'b0: begin
                                        dr_state <= RESET;
                                    end
                                    1'b1: begin
                                        dr_state <= SHIFT_DR;
                                    end
                                endcase
                            end else begin
                                case (tdi)
                                    1'b0: begin
                                        dr_state <= IDLE;
                                    end
                                    1'b1: begin
                                        tdo_reg <= tdi;
                                        dr_state <= SHIFT_DR;
                                    end
                                endcase
                            end
                        end
                        SHIFT_DR: begin
                            tdo_reg <= tdi;
                            if (tms) begin
                                case (tdi)
                                    1'b0: begin
                                        dr_state <= EXIT_DR;
                                    end
                                    1'b1: begin
                                        dr_state <= SHIFT_DR;
                                    end
                                endcase
                            end else begin
                                case (tdi)
                                    1'b0: begin
                                        dr_state <= EXIT_DR;
                                    end
                                    1'b1: begin
                                        dr_state <= SHIFT_DR;
                                    end
                                endcase
                            end
                        end
                        EXIT_DR: begin
                            if (tms) begin
                                dr_state <= UPDATE_DR;
                            end else begin
                                dr_state <= IDLE;
                            end
                        end
                        UPDATE_DR: begin
                            if (tms) begin
                                dr_state <= SELECT_DR_SCAN;
                            end else begin
                                dr_state <= IDLE;
                            end
                        end
                        SELECT_DR_SCAN: begin
                            if (tms) begin
                                state <= IR;
                                ir_state <= IDLE;
                            end else begin
                                dr_state <= IDLE;
                            end
                        end
                    endcase
                end
                IR: begin
                    case (ir_state)
                        IDLE: begin
                            if (tms) begin
                                case (tdi)
                                    1'b0: begin
                                        ir_state <= RESET;
                                    end
                                    1'b1: begin
                                        ir_state <= SHIFT_IR;
                                    end
                                endcase
                            end else begin
                                case (tdi)
                                    1'b0: begin
                                        ir_state <= IDLE;
                                    end
                                    1'b1: begin
                                        ir_state <= SHIFT_IR;
                                    end
                                endcase
                            end
                        end
                        SHIFT_IR: begin
                            if (tms) begin
                                case (tdi)
                                    1'b0: begin
                                        ir_state <= EXIT_IR;
                                    end
                                    1'b1: begin
                                        ir_state <= SHIFT_IR;
                                    end
                                endcase
                            end else begin
                                case (tdi)
                                    1'b0: begin
                                        ir_state <= EXIT_IR;
                                    end
                                    1'b1: begin
                                        ir_state <= SHIFT_IR;
                                    end
                                endcase
                            end
                        end
                        EXIT_IR: begin
                            if (tms) begin
                                ir_state <= UPDATE_IR;
                            end else begin
                                ir_state <= IDLE;
                            end
                        end
                        UPDATE_IR: begin
                            if (tms) begin
                                ir_state <= SELECT_IR_SCAN;
                            end else begin
                                ir_state <= IDLE;
                            end
                        end
                        SELECT_IR_SCAN: begin
                            if (tms) begin
                                state <= DR;
                                dr_state <= IDLE;
                            end else begin
                                ir_state <= IDLE;
                            end
                        end
                    endcase
                end
            endcase
        end
    end

    assign tmsutap = (state == RESET) ? 1'b1 :
                     (state == IDLE) ? 1'b0 :
                     (state == DR) ? 1'b0 :
                     (state == IR) ? 1'b1 : 1'b0;

    assign tckutap = (state == RESET) ? 1'b0 :
                     (state == IDLE) ? 1'b1 :
                     (state == DR) ? 1'b1 :
                     (state == IR) ? 1'b1 : 1'b0;

    assign tdiutap = (state == RESET) ? 1'b0 :
                     (state == IDLE) ? 1'b0 :
                     (state == DR) ? 1'b1 :
                     (state == IR) ? 1'b1 : 1'b0;

    assign shiftuser = (tdouser) ? 1'b1 : 1'b0;

    assign clkdruser = (dr_state == SHIFT_DR) ? 1'b1 : 1'b0;

    assign updateuser = (updateuser) ? usr1user : 1'b0;

    assign runidleuser = (runidleuser) ? 1'b1 : 1'b0;

    assign usr1user = 1'b0;

