module sigma_delta (
  input Vin,
  input clk,
  input reset,
  output Dout
);

parameter OSR = 128; // oversampling ratio
parameter N = 2; // order of modulator

reg [N-1:0] feedback; // feedback loop
reg [N-1:0] quant_error; // quantization error
reg [N:0] accumulator; // accumulator for noise shaping
reg [N:0] accumulator_prev; // previous value of accumulator

always @(posedge clk) begin
  if (reset) begin
    feedback <= {N{1'b0}};
    quant_error <= {N{1'b0}};
    accumulator <= {N+1{1'b0}};
    accumulator_prev <= {N+1{1'b0}};
  end else begin
    feedback <= {quant_error[N-1:0], feedback[N-1:1]};
    quant_error <= Vin - feedback[N-1];
    accumulator <= accumulator_prev + quant_error - feedback;
    accumulator_prev <= accumulator;
  end
end

assign Dout = accumulator[N] > OSR/2 ? 1'b1 : 1'b0;

endmodule

module sigma_delta_demod (
  input Dout,
  input clk,
  input reset,
  output reg Vout
);

parameter OSR = 128; // oversampling ratio
parameter N = 2; // order of modulator

reg [N:0] accumulator; // accumulator for reconstruction
reg [N:0] accumulator_prev; // previous value of accumulator

always @(posedge clk) begin
  if (reset) begin
    accumulator <= {N+1{1'b0}};
    accumulator_prev <= {N+1{1'b0}};
    Vout <= 0;
  end else begin
    accumulator <= accumulator_prev + (Dout ? 1 : -1);
    accumulator_prev <= accumulator;
    if (accumulator[N] > OSR/2) begin
      Vout <= 1;
    end else begin
      Vout <= 0;
    end
  end
end

endmodule

