    wire [3:0] module2_out;
    wire parity_bit;

    // Instantiate the two given modules
    module1 module1_inst (
        .clk(clk),
        .reset(reset),
        .in(in),
        .out(module1_out)
    );

    module2 module2_inst (
        .clk(clk),
        .reset(reset),
        .in(in),
        .out(module2_out)
    );

    // Compute the parity bit using XOR gates and a full adder
    assign parity_bit = module1_out[0] ^ module1_out[1] ^ module1_out[2] ^ module1_out[3] ^ 
                        module2_out[0] ^ module2_out[1] ^ module2_out[2] ^ module2_out[3];

