module transition_detector (
    input clk,
    input reset,
    input [31:0] in,
    output reg [31:0] out
);

reg [31:0] in_reg1, in_reg2, in_reg3, in_reg4;
reg [31:0] xor1, xor2, xor3;
reg [31:0] dff1, dff2, dff3;

always @(posedge clk, posedge reset) begin
    if (reset) begin
        in_reg1 <= 0;
        in_reg2 <= 0;
        in_reg3 <= 0;
        in_reg4 <= 0;
        xor1 <= 0;
        xor2 <= 0;
        xor3 <= 0;
        dff1 <= 0;
        dff2 <= 0;
        dff3 <= 0;
        out <= 0;
    end else begin
        in_reg1 <= in;
        in_reg2 <= in_reg1;
        in_reg3 <= in_reg2;
        in_reg4 <= in_reg3;

        xor1 <= in_reg1 ^ in_reg2;
        xor2 <= in_reg2 ^ in_reg3;
        xor3 <= in_reg3 ^ in_reg4;

        dff1 <= xor1;
        dff2 <= xor2;
        dff3 <= xor3;

        if (dff1 || dff2 || dff3) begin
            out <= 1;
        end else if (in_reg1) begin
            out <= 0;
        end
    end
end

endmodule

