module top_module(
    input [7:0] in1,
    input [7:0] in2,
    input sel1,
    input sel2,
    input clk,
    input reset,
    output [3:0] out
);

    // Select inputs using 4-to-1 multiplexers
    wire [7:0] selected_input1, selected_input2;
    mux4to1 mux1(.in0(in1), .in1(in2), .sel(sel1), .out(selected_input1));
    mux4to1 mux2(.in0(in1), .in1(in2), .sel(sel2), .out(selected_input2));

    // Concatenate selected inputs to generate 16-bit output
    wire [15:0] concatenated_output;
    assign concatenated_output = {selected_input1, selected_input2};

    // Compute parity bit for 16-bit output using parity generator module
    wire parity_bit;
    parity_generator parity(.in(concatenated_output), .out(parity_bit));

    // Check if number of 1's in each byte of 16-bit output is odd or even using functional module
    wire [3:0] byte_parity;
    byte_parity_checker byte_checker(.in(concatenated_output), .out(byte_parity));

    // Output 4-bit value indicating parity result for each byte
    assign out = byte_parity;

endmodule

// 4-to-1 multiplexer module
module mux4to1(
    input [7:0] in0,
    input [7:0] in1,
    input sel,
    output reg [7:0] out
);

    always @(*) begin
        case(sel)
            2'b00: out = in0;
            2'b01: out = in1;
            2'b10: out = in0;
            2'b11: out = in1;
        endcase
    end

endmodule

// Parity generator module
module parity_generator(
    input [15:0] in,
    output reg parity
);

    always @(in) begin
        parity = ^in;
    end

endmodule

