module byte_parity_checker(
    input [15:0] in,
    output [3:0] out
);

    assign out[0] = ^in[7:0];
    assign out[1] = ^in[15:8];
    assign out[2] = ^in[23:16];
    assign out[3] = ^in[31:24];

endmodule

