module quadrature (
  input in,
  output I,
  output Q
);

  // Define the carrier signals
  parameter frequency = 1000000; // 1 MHz
  parameter sample_rate = 10000000; // 10 MHz
  parameter phase_shift = sample_rate / (4 * frequency);
  reg [31:0] cos_phase = 0;
  reg [31:0] sin_phase = phase_shift;

  // Define the low-pass filters
  parameter filter_coeff = 0.1;
  reg [31:0] I_filtered = 0;
  reg [31:0] Q_filtered = 0;

  // Compute the carrier signals
  always @(posedge clk) begin
    cos_phase <= cos_phase + (2 * $floor(phase_shift * (2**32 / sample_rate)));
    sin_phase <= sin_phase + (2 * $floor(phase_shift * (2**32 / sample_rate)));
  end
  wire cos = $signed($cos(cos_phase[31:0]));
  wire sin = $signed($sin(sin_phase[31:0]));

  // Compute the demodulated signals
  always @(posedge clk) begin
    I_filtered <= (1 - filter_coeff) * I_filtered + filter_coeff * (in * cos);
    Q_filtered <= (1 - filter_coeff) * Q_filtered + filter_coeff * (in * sin);
  end
  assign I = $signed(I_filtered);
  assign Q = $signed(Q_filtered);

  // Compute the modulated signal
  assign out = (I * cos) + (Q * sin);

endmodule

module Adder4bit(
    input [3:0] A,
    input [3:0] B,
    output [3:0] sum
    );

    wire [3:0] carry;
    wire [2:0] carry2;

    //add the least significant bit
    FullAdder fa1 (A[0], B[0], 1'b0, sum[0], carry[0]);

    //add the second least significant bit
    FullAdder fa2 (A[1], B[1], carry[0], sum[1], carry[1]);

    //add the third least significant bit
    FullAdder fa3 (A[2], B[2], carry[1], sum[2], carry[2]);

    //add the most significant bit
    FullAdder fa4 (A[3], B[3], carry[2], sum[3], carry2[2]);

    assign carry2[1:0] = carry[3:2];

    assign carry2[0] = 1'b0;

endmodule

module FullAdder(
    input A,
    input B,
    input Cin,
    output S,
    output Cout
    );

    assign S = A ^ B ^ Cin;
    assign Cout = (A & B) | (Cin & (A ^ B));

endmodule

