module comparator (
    input [3:0] A,
    input [3:0] B,
    output reg [1:0] OUT
);

always @(*) begin
    if (A > B) begin
        OUT = 2'b01;
    end else if (A < B) begin
        OUT = 2'b10;
    end else begin
        OUT = 2'b11;
    end
end

endmodule

module up_down_counter (
    input clk,
    input reset,
    input up_down,
    output reg [2:0] count
);

always @(posedge clk or posedge reset) begin
    if (reset) begin
        count <= 3'b000;
    end else if (up_down) begin
        count <= count + 1;
    end else begin
        count <= count - 1;
    end
end

endmodule

module final_module (
    input [1:0] comparator_output,
    input [2:0] up_down_output,
    input [3:0] A,
    input [3:0] B,
    output reg [4:0] final_output
);

always @(*) begin
    case (comparator_output)
        2'b01: final_output = up_down_output + A;
        2'b10: final_output = up_down_output + B;
        2'b11: final_output = up_down_output;
    endcase
end

endmodule

