module spi_interface (
  input  wire         clk,  // 150 MHz
  input  wire         reset,

  //--------------------------------------------------------------------------
  //------------------------CONTROL INTERFACE---------------------------------
  //--------------------------------------------------------------------------
  input  wire [31:0]  data_out,
  output reg  [31:0]  data_in,
  input  wire [7:0]   read_bits,
  input  wire [7:0]   write_bits,
  input  wire         request_action,
  output wire         busy,

  //--------------------------------------------------------------------------
  //-----------HARDWARE INTERFACE---------------------------------------------
  //--------------------------------------------------------------------------
  output wire         sclk,
  inout  wire         sdio,
  output reg          cs
);

//----------------------------------------------------------------------------
// Parameters
//----------------------------------------------------------------------------
localparam IDLE         = 3'd0,
           DATA_WRITE_0 = 3'd1,
           DATA_WRITE   = 3'd2,
           DATA_READ_0  = 3'd3,
           DATA_READ    = 3'd4;

localparam CLK_DIV = 3;
//----------------------------------------------------------------------------
// Wires
//----------------------------------------------------------------------------
wire update_in;  // Read-in on positive edge of clock
wire update_out; // Write-out on negative edge of clk
wire sdo;

//----------------------------------------------------------------------------
// Registers
//----------------------------------------------------------------------------
reg [CLK_DIV:0] clk_div1;
reg [CLK_DIV:0] clk_div2;

reg [31:0] input_shifter;
reg [31:0] output_shifter;

reg [7:0]   read_bits_reg;
reg [7:0]   write_bits_reg;

reg [8:0] bit_counter;
reg is_writing;
reg busy_int;

reg [2:0] state;

//----------------------------------------------------------------------------
// Assignments
//----------------------------------------------------------------------------
assign update_in  =  clk_div1[CLK_DIV] & ~clk_div2[CLK_DIV]; // posedge serial clock
assign update_out = ~clk_div1[CLK_DIV] &  clk_div2[CLK_DIV]; // negedge serial clock

assign sdo = output_shifter[31];

assign sclk = clk_div2[CLK_DIV] & cs;
assign sdio = is_writing ? sdo : 1'bz;
assign busy = busy_int | request_action;

//----------------------------------------------------------------------------
// Clock Division
//----------------------------------------------------------------------------
always @( posedge clk ) begin
  if ( reset ) begin
    clk_div2 <= 0;
    clk_div1 <= 0;
  end
  else begin
    clk_div2 <= clk_div1;
    clk_div1 <= clk_div1 + 1;
  end
end

//----------------------------------------------------------------------------
// State Machine
//----------------------------------------------------------------------------
always @( posedge clk ) begin
  if ( reset ) begin
    state <= IDLE;
    data_in <= 32'd0;
    busy_int <= 1;
    is_writing <= 0;
    cs <= 0;
  end
  else begin
    case ( state )
      IDLE: begin
        data_in <= 32'd0;
        if ( request_action ) begin
          state <= DATA_WRITE_0;
          busy_int <= 1;
          output_shifter <= data_out;
          input_shifter <= 32'd0;
          write_bits_reg <= write_bits;
          read_bits_reg <= read_bits;
        end
        else begin
          busy_int <= 1'd0;
        end
      end
      DATA_WRITE_0: begin
        if ( update_out ) begin
          state <= DATA_WRITE;
          is_writing <= 1'd1;
          cs <= 1'd1;
          bit_counter <= 9'd1;
        end
      end
      DATA_WRITE: begin
        if ( update_out ) begin
          if ( bit_counter == write_bits_reg ) begin
            state <= DATA_READ_0;
            bit_counter <= 9'd1;
            is_writing <= 0;
          end
          else begin
            bit_counter <= bit_counter + 9'd1;
            output_shifter <= {output_shifter[30:0], 1'd0};
          end
        end
      end
      DATA_READ_0: begin
        if ( update_out ) begin
          state <= DATA_READ;
          is_writing <= 0;
          cs <= 1'd1;
          bit_counter <= 9'd1;
        end
      end
      DATA_READ: begin
        if ( update_in ) begin
          if ( bit_counter == read_bits_reg ) begin
            state <= IDLE;
            busy_int <= 1'd0;
            cs <= 1'd0;
            data_in <= input_shifter;
          end
          else begin
            bit_counter <= bit_counter + 9'd1;
            input_shifter <= {input_shifter[30:0], sdio};
          end
        end
      end
    endcase
  end
end

endmodule

module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

    wire [3:0] sum;
    wire c1, c2, c3;

    FA fa0(.A(A[0]), .B(B[0]), .Cin(Cin), .S(sum[0]), .Cout(c1));
    FA fa1(.A(A[1]), .B(B[1]), .Cin(c1), .S(sum[1]), .Cout(c2));
    FA fa2(.A(A[2]), .B(B[2]), .Cin(c2), .S(sum[2]), .Cout(c3));
    FA fa3(.A(A[3]), .B(B[3]), .Cin(c3), .S(sum[3]), .Cout(Cout));

    assign S = sum;

endmodule

module FA(
    input A,
    input B,
    input Cin,
    output S,
    output Cout
);

    assign S = A ^ B ^ Cin;
    assign Cout = (A & B) | (Cin & (A ^ B));

endmodule

module top_module (
    input [31:0] a,
    input [31:0] b,
    input select,
    output [31:0] sum
);

    wire [31:0] adder1_out;
    wire [31:0] adder2_out;
    wire [1:0] carry_out;

    assign sum = select ? adder2_out : adder1_out;

    carry_select_adder adder1 (
        .a(a),
        .b(b),
        .c_in(1'b0),
        .sum(adder1_out),
        .c_out(carry_out[0])
    );

    carry_lookahead_adder adder2 (
        .a(a),
        .b(b),
        .c_in(1'b0),
        .sum(adder2_out),
        .c_out(carry_out[1])
    );

    control_logic control (
        .select(select),
        .carry_out(carry_out)
    );

endmodule

module carry_select_adder (
    input [31:0] a,
    input [31:0] b,
    input c_in,
    output [31:0] sum,
    output c_out
);

    wire [31:0] sum_intermediate;
    wire [31:0] carry_intermediate;

    generate
        for (i = 0; i < 32; i = i + 4) begin : generate_block
            carry_select_adder_block block (
                .a(a[i+3:i]),
                .b(b[i+3:i]),
                .c_in(c_in),
                .sum(sum_intermediate[i+3:i]),
                .c_out(carry_intermediate[i+3:i])
            );
        end
    endgenerate

    assign sum = sum_intermediate;
    assign c_out = carry_intermediate[31];

endmodule

module carry_select_adder_block (
    input [3:0] a,
    input [3:0] b,
    input c_in,
    output [3:0] sum,
    output c_out
);

    wire [3:0] sum_intermediate;
    wire [3:0] carry_intermediate;

    assign sum_intermediate = a + b + c_in;
    assign c_out = (a[3] & b[3]) | (a[3] & c_in) | (b[3] & c_in);
    assign sum = sum_intermediate + (c_out ? 1 : 0);

endmodule

module carry_lookahead_adder (
    input [31:0] a,
    input [31:0] b,
    input c_in,
    output [31:0] sum,
    output c_out
);

    wire [31:0] p;
    wire [31:0] g;
    wire [31:0] c;

    assign p = a ^ b;
    assign g = a & b;
    assign c[0] = c_in;

    generate
        for (i = 1; i < 32; i = i * 2) begin : generate_block
            assign c[i] = g[i-1] | (p[i-1] & c[i-1]);
        end
    endgenerate

    assign sum = a + b + c;
    assign c_out = c[31];

endmodule

module control_logic (
    input select,
    input [1:0] carry_out,
    output [31:0] control_out
);

    wire [31:0] select1;
    wire [31:0] select2;

    assign select1 = {32{!select}} & carry_out[0];
    assign select2 = {32{select}} & carry_out[1];

    assign control_out = select1 | select2;

endmodule

