    output out_or_logical,
    output [5:0] out_not
);

    // Bitwise-OR module
    wire [2:0] bitwise_or;
    bitwise_or_module bitwise_or_inst(
        .a(a),
        .b(b),
        .out(bitwise_or)
    );

    // Logical-OR module
    wire logical_or;
    logical_or_module logical_or_inst(
        .a(a),
        .b(b),
        .out(logical_or)
    );

    // NOT module
    wire [2:0] not_a;
    wire [2:0] not_b;
    not_module not_a_inst(
        .in(a),
        .out(not_a)
    );
    not_module not_b_inst(
        .in(b),
        .out(not_b)
    );
    assign out_not = {not_a, not_b};

    // 4-to-1 multiplexers
    wire [2:0] mux_a_out;
    wire [2:0] mux_b_out;
    mux4to1_module mux_a_inst(
        .in0(a),
        .in1(not_a),
        .in2(bitwise_or),
        .in3(logical_or),
        .sel(mux_sel[1:0]),
        .out(mux_a_out)
    );
    mux4to1_module mux_b_inst(
        .in0(b),
        .in1(not_b),
        .in2(bitwise_or),
        .in3(logical_or),
        .sel(mux_sel[1:0]),
        .out(mux_b_out)
    );

    // 6-to-1 multiplexer
    mux6to1_module mux_out_inst(
        .in0(out_or_bitwise),
        .in1(out_or_logical),
        .in2(out_not),
        .sel(mux_sel[3]),
        .out({out_or_bitwise, out_or_logical, out_not})
    );

endmodule

