  brightness <= (adc_out * (max_brightness - min_brightness)) >> adc_bits + min_brightness;
end

pwm pwm_inst (
  .clk(clk),
  .in(brightness),
  .out(pwm_out)
);

always @(posedge clk) begin
  // convert adc_out to digital output value
  out <= adc_out >> adc_bits - out_bits;
end

endmodule

module top_module (
    input clk,
    input reset,
    input [31:0] in,
    output [31:0] out
);

    reg [31:0] prev_in;
    reg [31:0] curr_in;
    reg [31:0] out_reg;
    wire [31:0] xor_out;

    d_ff_32bit dff (
        .clk(clk),
        .reset(reset),
        .d(xor_out),
        .q(out_reg)
    );

    xor_32bit xor_gate (
        .a(prev_in),
        .b(curr_in),
        .out(xor_out)
    );

    always @(posedge clk) begin
        prev_in <= curr_in;
        curr_in <= in;
        if (reset) begin
            out_reg <= 0;
        end else if (curr_in != prev_in) begin
            out_reg <= xor_out;
        end
    end

    assign out = out_reg;

endmodule

