module top_module (
    input [3:0] B,
    output reg [1:0] index,
    output reg out
);

    wire [3:0] gray_code;
    wire [15:0] decoder_output;

    binary_to_gray gray_converter (
        .binary(B),
        .gray(gray_code)
    );

    decoder_4to16 decoder (
        .input_code(gray_code),
        .output_code(decoder_output)
    );

    index_module indexer (
        .input_code(decoder_output),
        .index(index)
    );

    always @* begin
        if (decoder_output != 16'b0000000000000000) begin
            out = 1'b1;
        end else begin
            out = 1'b0;
        end
    end

endmodule

