module my_module (
  input CLK,
  input D,
  output Q,
  output Q_N,
  input SCD,
  input SCE,
  input VPWR,
  input VGND
);

  wire buf_Q;
  wire mux_out;
  reg notifier;
  wire D_delayed;
  wire SCD_delayed;
  wire SCE_delayed;
  wire CLK_delayed;
  wire awake;
  wire cond1;
  wire cond2;
  wire cond3;

  assign awake = (VPWR == 1'b1);
  assign cond1 = (SCE_delayed == 1'b0) && awake;
  assign cond2 = (SCE_delayed == 1'b1) && awake;
  assign cond3 = (D_delayed != SCD_delayed) && awake;

  sky130_fd_sc_hs__u_mux_2_1 u_mux_20 (mux_out, D_delayed, SCD_delayed, SCE_delayed);
  sky130_fd_sc_hs__u_df_p_no_pg u_df_p_no_pg0 (buf_Q, mux_out, CLK_delayed, notifier, VPWR, VGND);
  buf buf0 (Q, buf_Q);
  not not0 (Q_N, buf_Q);

  always @(posedge CLK) begin
    CLK_delayed <= CLK;
    D_delayed <= D;
    SCD_delayed <= SCD;
    SCE_delayed <= SCE;
    if (SCD) begin
      notifier <= 1'b0;
    end else if (notifier == 1'b0 && SCE_delayed == 1'b0 && awake) begin
      notifier <= 1'b1;
    end else if (notifier == 1'b1 && SCE_delayed == 1'b1 && awake) begin
      notifier <= 1'b0;
    end
  end

  always @(posedge CLK or negedge VGND) begin
    if (!VGND) begin
      buf_Q <= 1'b0;
    end else if (notifier == 1'b1 && cond1) begin
      buf_Q <= D_delayed;
    end else if (notifier == 1'b1 && cond2) begin
      buf_Q <= SCD_delayed;
    end else if (notifier == 1'b1 && cond3) begin
      buf_Q <= SCD_delayed;
    end
  end

endmodule

