module ripple_carry_adder (
  input [n-1:0] A,
  input [n-1:0] B,
  output [n-1:0] S
);

parameter n = 4; // number of bits in the input and output

wire [n:0] carry;
genvar i;

generate
  for (i = 0; i < n; i = i + 1) begin : adder
    full_adder fa (
      .A(A[i]),
      .B(B[i]),
      .Cin(carry[i]),
      .S(S[i]),
      .Cout(carry[i+1])
    );
  end
endgenerate

assign carry[0] = 1'b0;

endmodule

module sa1099_mixer_and_amplitude (
    input wire clk,
    input wire en_tone,
    input wire en_noise,
    input wire tone,
    input wire noise,
    input wire [3:0] amplitude_l,
    input wire [3:0] amplitude_r,
    output reg [4:0] out_l,
    output reg [4:0] out_r
    );

    reg [4:0] next_out_l, next_out_r;
    always @* begin
        next_out_l = 5'b0000;
        next_out_r = 5'b0000;
        if (en_tone == 1'b1)
            if (tone == 1'b1) begin
                next_out_l = next_out_l + {1'b0, amplitude_l};
                next_out_r = next_out_r + {1'b0, amplitude_r};
            end
        if (en_noise == 1'b1)
            if (noise == 1'b1) begin
                next_out_l = next_out_l + {1'b0, amplitude_l};
                next_out_r = next_out_r + {1'b0, amplitude_r};
            end
    end

    always @(posedge clk) begin
        out_l <= next_out_l;
        out_r <= next_out_r;
    end
endmodule

