module sequential_logic_block (
  input clk,
  input reset,
  input [2:0] x,
  output reg f
);

  parameter state0 = 3'b000;
  parameter state1 = 3'b001;
  parameter state2 = 3'b010;
  parameter state3 = 3'b011;
  parameter state4 = 3'b100;
  parameter state5 = 3'b101;
  parameter state6 = 3'b110;
  parameter state7 = 3'b111;

  reg [2:0] state;
  always @(posedge clk, posedge reset) begin
    if (reset) begin
      state <= state0;
      f <= 1'b0;
    end else begin
      case (state)
        state0: begin
          f <= 1'b0;
          state <= state0;
        end
        state1: begin
          if (x == 3'b001) begin
            f <= 1'b1;
            state <= state2;
          end else begin
            f <= 1'b0;
            state <= state0;
          end
        end
        state2: begin
          if (x == 3'b010) begin
            f <= 1'b1;
            state <= state3;
          end else begin
            f <= 1'b0;
            state <= state0;
          end
        end
        state3: begin
          if (x == 3'b011) begin
            f <= 1'b1;
            state <= state4;
          end else begin
            f <= 1'b0;
            state <= state0;
          end
        end
        state4: begin
          f <= 1'b0;
          state <= state0;
        end
        state5: begin
          if (x == 3'b001) begin
            f <= 1'b1;
            state <= state6;
          end else begin
            f <= 1'b0;
            state <= state0;
          end
        end
        state6: begin
          if (x == 3'b010) begin
            f <= 1'b1;
            state <= state7;
          end else begin
            f <= 1'b0;
            state <= state0;
          end
        end
        state7: begin
          if (x == 3'b011) begin
            f <= 1'b1;
            state <= state0;
          end else begin
            f <= 1'b0;
            state <= state0;
          end
        end
      endcase
    end
  end

endmodule

module spi_controller (
  input spi_clk,
  input spi_adc_csn,
  input spi_ext_csn_0,
  input spi_ext_csn_1,
  input spi_mosi,
  inout spi_adc_sdio,
  inout spi_ext_sdio,
  output spi_miso
);

  // 4 wire

  wire spi_csn_s;
  wire spi_enable_s;
  wire spi_adc_miso_s;
  wire spi_ext_miso_s;

  // 3 wire

  reg [7:0] spi_tx_data;
  reg [7:0] spi_rx_data;
  reg [2:0] spi_device_sel;
  reg spi_tx_en;
  reg spi_rx_en;
  reg spi_read_en;
  reg spi_write_en;
  reg spi_enable;
  reg spi_rd_wr_n;
  reg [5:0] spi_count;
  reg [7:0] spi_miso_out;

  // check on rising edge and change on falling edge

  assign spi_csn_s = spi_adc_csn & spi_ext_csn_0 & spi_ext_csn_1;
  assign spi_enable_s = spi_enable & ~spi_csn_s;

  always @(posedge spi_clk) begin
    if (spi_csn_s == 1'b1) begin
      spi_count <= 6'd0;
      spi_rd_wr_n <= 1'd0;
    end else begin
      spi_count <= spi_count + 1'b1;
      if (spi_count == 6'd0) begin
        spi_rd_wr_n <= spi_mosi;
      end
    end
  end

  always @(negedge spi_clk) begin
    if (spi_csn_s == 1'b1) begin
      spi_enable <= 1'b0;
      spi_device_sel <= 3'd0;
    end else begin
      if (spi_count == 6'd16) begin
        spi_enable <= spi_rd_wr_n;
      end
    end
  end

  always @(*) begin
    if (spi_enable_s == 1'b1) begin
      case (spi_device_sel)
        3'd0: begin // ADC
          spi_tx_en = spi_write_en;
          spi_rx_en = spi_read_en;
          spi_miso_out = spi_adc_miso_s;
        end
        3'd1: begin // External device 0
          spi_tx_en = spi_write_en;
          spi_rx_en = spi_read_en;
          spi_miso_out = spi_ext_miso_s;
        end
        3'd2: begin // External device 1
          spi_tx_en = spi_write_en;
          spi_rx_en = spi_read_en;
          spi_miso_out = spi_ext_miso_s;
        end
        default: begin
          spi_tx_en = 1'b0;
          spi_rx_en = 1'b0;
          spi_miso_out = 8'h00;
        end
      endcase
    end else begin
      spi_tx_en = 1'b0;
      spi_rx_en = 1'b0;
      spi_miso_out = 8'h00;
    end
  end

  always @(posedge spi_clk) begin
    if (spi_enable_s == 1'b1) begin
      if (spi_tx_en == 1'b1) begin
        spi_device_sel <= spi_device_sel;
        spi_tx_data <= spi_mosi;
      end else begin
        spi_device_sel <= spi_device_sel;
        spi_tx_data <= 8'h00;
      end
    end else begin
      spi_device_sel <= spi_device_sel + 1'b1;
      spi_tx_data <= 8'h00;
    end
  end

  always @(negedge spi_clk) begin
    if (spi_enable_s == 1'b1) begin
      if (spi_rx_en == 1'b1) begin
        spi_device_sel <= spi_device_sel;
        spi_rx_data <= spi_miso_out;
      end else begin
        spi_device_sel <= spi_device_sel;
        spi_rx_data <= 8'h00;
      end
    end else begin
      spi_device_sel <= spi_device_sel + 1'b1;
      spi_rx_data <= 8'h00;
    end
  end

  always @(*) begin
    if (spi_enable_s == 1'b1) begin
      if (spi_device_sel == 3'd0) begin // ADC
        if (spi_tx_en == 1'b1) begin
          spi_adc_sdio <= spi_tx_data[7];
        end else if (spi_rx_en == 1'b1) begin
          spi_rx_data[7] <= spi_adc_sdio;
        end
      end else if (spi_device_sel == 3'd1) begin // External device 0
        if (spi_tx_en == 1'b1) begin
          spi_ext_sdio <= spi_tx_data[7];
        end else if (spi_rx_en == 1'b1) begin
          spi_rx_data[7] <= spi_ext_sdio;
        end
      end else if (spi_device_sel == 3'd2) begin // External device 1
        if (spi_tx_en == 1'b1) begin
          spi_ext_sdio <= spi_tx_data[7];
        end else if (spi_rx_en == 1'b1) begin
          spi_rx_data[7] <= spi_ext_sdio;
        end
      end
    end
  end

  assign spi_miso = spi_miso_out;

endmodule

