module LogicAnalyzer(input CLK, input RXD_START, input [7:0] RXD, input TXD_DONE, input [15:0] DATA_IN, 
	output TXD_ENABLE, output [15:0] TXD, output TRIGGERED);

wire RST, WE;
wire [9:0] ADDR;
wire [15:0] RAM_DATA;
wire [15:0] DATA;
