module dct_counter (
  input   [ 29: 0] dct_buffer,
  input   [  3: 0] dct_count,
  input            test_ending,
  input            test_has_ended,
  output  [  3: 0] dct_count_out,
  output           test_complete
);

  reg [29:0] prev_dct_buffer = 0;
  reg [3:0] prev_dct_count = 0;
  reg [3:0] dct_count_out = 0;
  reg test_complete = 0;

  always @ (posedge clk) begin
    if (test_ending && !prev_test_ending) begin
      // Test is ending, set test_complete if dct_count_out is 10
      if (dct_count_out == 10) begin
        test_complete <= 1;
      end
    end

    if (dct_buffer != prev_dct_buffer) begin
      // DCT buffer data has changed, increment dct_count_out
      dct_count_out <= dct_count + 1;
    end

    prev_dct_buffer <= dct_buffer;
    prev_dct_count <= dct_count;
    prev_test_ending <= test_ending;
  end

endmodule

module up_down_counter (
    input clk,
    input reset,
    input load,
    input up_down,
    input [3:0] data_in,
    output reg [3:0] count_out
);

    always @(posedge clk) begin
        if (reset) begin
            count_out <= 4'b0;
        end else if (load) begin
            count_out <= data_in;
        end else if (up_down) begin
            count_out <= count_out + 1;
        end else begin
            count_out <= count_out - 1;
        end
    end

endmodule

