module fifo_buffer (
  input clk,
  input rst,
  input wr_en,
  input rd_en,
  input [7:0] data_in,
  output [7:0] data_out,
  output full,
  output empty
);

  localparam DEPTH = 8;

  reg [7:0] buffer [DEPTH-1:0];
  reg [2:0] wr_ptr;
  reg [2:0] rd_ptr;
  reg full;
  reg empty;

  always @(posedge clk) begin
    if (rst) begin
      wr_ptr <= 0;
      rd_ptr <= 0;
      full <= 0;
      empty <= 1;
    end
    else begin
      if (wr_en && !full) begin
        buffer[wr_ptr] <= data_in;
        wr_ptr <= wr_ptr + 1;
        if (wr_ptr == DEPTH) begin
          wr_ptr <= 0;
        end
        if (wr_ptr == rd_ptr) begin
          full <= 1;
        end
        empty <= 0;
      end
      if (rd_en && !empty) begin
        data_out <= buffer[rd_ptr];
        rd_ptr <= rd_ptr + 1;
        if (rd_ptr == DEPTH) begin
          rd_ptr <= 0;
        end
        if (rd_ptr == wr_ptr) begin
          empty <= 1;
        end
        full <= 0;
      end
    end
  end

endmodule

