module spi_master (
  input clk,
  input cs,
  input mosi,
  output miso,
  output done
);

  reg [7:0] tx_data;
  reg [7:0] rx_data;
  reg [2:0] state;
  wire sclk;

  assign miso = rx_data[0];
  assign sclk = clk;

  always @(posedge sclk) begin
    if (cs == 1'b0) begin
      case (state)
        3'b000: begin
          tx_data <= 8'h55;
          state <= 3'b001;
        end
        3'b001: begin
          tx_data <= 8'hAA;
          state <= 3'b010;
        end
        3'b010: begin
          rx_data <= mosi;
          state <= 3'b011;
        end
        3'b011: begin
          done <= 1'b1;
          state <= 3'b000;
        end
        default: begin
          state <= 3'b000;
        end
      endcase
    end else begin
      done <= 1'b0;
      state <= 3'b000;
    end
  end

endmodule

