  assign mosi = tx_data[0];
  assign sclk = clk;

  always @(posedge sclk) begin
    if (cs == 1'b0) begin
      case (state)
        3'b000: begin
          state <= 3'b001;
        end
        3'b001: begin
          tx_data <= 8'h55;
          state <= 3'b010;
        end
        3'b010: begin
          tx_data <= 8'hAA;
          state <= 3'b011;
        end
        3'b011: begin
          rx_data <= miso;
          state <= 3'b000;
          done <= 1'b1;
        end
        default: begin
          state <= 3'b000;
        end
      endcase
    end else begin
      done <= 1'b0;
      state <= 3'b000;
    end
  end

endmodule

module timing_generator_VGA
(
input wire clk, reset,
output reg hsync, vsync, video_on, p_tick,
output reg [9:0] pixel_x, pixel_y
);

// VGA timing parameters
localparam HD = 640; // horizontal display area
localparam HF = 48; // horizontal front porch
localparam HB = 16; // horizontal back porch
localparam HR = 96; // horizontal sync pulse width
localparam VD = 480; // vertical display area
localparam VF = 10; // vertical front porch
localparam VB = 33; // vertical back porch
localparam VR = 2; // vertical sync pulse width

// horizontal and vertical counters
reg [9:0] h_count, v_count;

// horizontal and vertical sync signals
reg h_sync, v_sync;

// horizontal and vertical sync pulse generators
wire h_pulse = (h_count >= (HD+HB)) && (h_count < (HD+HB+HR));
wire v_pulse = (v_count >= (VD+VB)) && (v_count < (VD+VB+VR));

// visible area detector
wire visible = (h_count < HD) && (v_count < VD);

// horizontal and vertical sync pulse width counters
reg [6:0] h_pulse_count, v_pulse_count;

// generate pixel clock
reg [1:0] pixel_count;
wire pixel_tick = (pixel_count == 2'b11);

// horizontal counter logic
always @(posedge clk, posedge reset) begin
    if (reset) begin
        h_count <= 0;
    end else begin
        if (h_count == (HD+HF+HB+HR-1)) begin
            h_count <= 0;
        end else begin
            h_count <= h_count + 1;
        end
    end
end

// vertical counter logic
always @(posedge clk, posedge reset) begin
    if (reset) begin
        v_count <= 0;
    end else begin
        if (v_count == (VD+VF+VB+VR-1)) begin
            v_count <= 0;
        end else begin
            v_count <= v_count + 1;
        end
    end
end

// horizontal sync pulse width counter logic
always @(posedge clk, posedge reset) begin
    if (reset) begin
        h_pulse_count <= 0;
    end else begin
        if (h_pulse) begin
            if (h_pulse_count == (HR-1)) begin
                h_pulse_count <= 0;
            end else begin
                h_pulse_count <= h_pulse_count + 1;
            end
        end
    end
end

// vertical sync pulse width counter logic
always @(posedge clk, posedge reset) begin
    if (reset) begin
        v_pulse_count <= 0;
    end else begin
        if (v_pulse) begin
            if (v_pulse_count == (VR-1)) begin
                v_pulse_count <= 0;
            end else begin
                v_pulse_count <= v_pulse_count + 1;
            end
        end
    end
end

// horizontal sync pulse generator logic
always @(posedge clk, posedge reset) begin
    if (reset) begin
        h_sync <= 1'b0;
    end else begin
        if (h_pulse) begin
            if (h_pulse_count == (HR-1)) begin
                h_sync <= 1'b1;
            end
        end else begin
            h_sync <= 1'b0;
        end
    end
end

// vertical sync pulse generator logic
always @(posedge clk, posedge reset) begin
    if (reset) begin
        v_sync <= 1'b0;
    end else begin
        if (v_pulse) begin
            if (v_pulse_count == (VR-1)) begin
                v_sync <= 1'b1;
            end
        end else begin
            v_sync <= 1'b0;
        end
    end
end

// visible area detector logic
always @(posedge clk, posedge reset) begin
    if (reset) begin
        video_on <= 1'b0;
    end else begin
        if (h_count < HD && v_count < VD) begin
            video_on <= 1'b1;
        end else begin
            video_on <= 1'b0;
        end
    end
end

// pixel clock generator logic
always @(posedge clk, posedge reset) begin
    if (reset) begin
        pixel_count <= 2'b00;
    end else begin
        if (pixel_tick) begin
            pixel_count <= pixel_count + 1;
        end
    end
end

// assign outputs
assign pixel_x = h_count;
assign pixel_y = v_count;
assign p_tick = pixel_tick;
assign hsync = h_sync;
assign vsync = v_sync;
assign video_on = visible;

endmodule

