module Timer(
    dout,
    din,
    address,
    size,
    read_write,
    enable,
    interrupt,
    reset,
    clk
);
    parameter WORD = 32;
    parameter LOGWORDBYTE = 2;
    parameter ENABLE = 1'b1;
    parameter SETTHENSTART = 2'b00;
    parameter STOPTHENACQUIRE = 2'b01;

    output reg [WORD-1:0] dout;
    input [WORD-1:0] din;
    input [WORD-1:0] address;
    input [LOGWORDBYTE-1:0] size;
    input read_write;
    input enable;
    output reg interrupt;
    input reset;
    input clk;

    reg [WORD-1:0] counter_upper;
    reg [WORD-1:0] counter_lower;
    reg [WORD-1:0] timer_upper;
    reg [WORD-1:0] timer_lower;
    wire set_then_start;
    wire stop_then_acquire;

    reg [(2*WORD)-1:0] counter;
    reg [(2*WORD)-1:0] timer;
    reg [(2*WORD)-1:0] interval;

    // Memory interface (read)
    always @(posedge clk) begin
        if (reset) begin
            dout <= 0;
        end
        else if ((enable == ENABLE) && (read_write == 1'b0)) begin
            case (address)
                2: dout <= counter_upper;
                3: dout <= counter_lower;
                4: dout <= timer_upper;
                5: dout <= timer_lower;
                default: dout <= 0;
            endcase
        end
        else begin
            dout <= 0;
        end
    end

    // Memory interface (write)
    assign set_then_start = ((address == 0) && (enable == ENABLE) && (read_write == 1'b1) && (din == SETTHENSTART));
    assign stop_then_acquire = ((address == 0) && (enable == ENABLE) && (read_write == 1'b1) && (din == STOPTHENACQUIRE));

    always @(posedge clk) begin
        if (reset) begin
            counter_upper <= 0;
            counter_lower <= 0;
            timer_upper <= 0;
            timer_lower <= 0;
        end
        else if ((enable == ENABLE) && (read_write == 1'b1)) begin
            if (address == 2) counter_upper <= din;
            else if (stop_then_acquire) counter_upper <= counter[(2*WORD)-1:WORD];
            else counter_upper <= counter_upper;

            if (address == 3) counter_lower <= din;
            else if (stop_then_acquire) counter_lower <= counter[WORD-1:0];
            else counter_lower <= counter_lower;

            if (address == 4) timer_upper <= din;
            else if (stop_then_acquire) timer_upper <= timer[(2*WORD)-1:WORD];
            else timer_upper <= timer_upper;

            if (address == 5) timer_lower <= din;
            else if (stop_then_acquire) timer_lower <= timer[WORD-1:0];
            else timer_lower <= timer_lower;
        end
    end

    // Back-end
    always @(posedge clk) begin
        if (reset) begin
            counter <= 0;
            timer <= 0;
            interval <= 0;
            interrupt <= 0;
        end
        else if (set_then_start) begin
            counter <= {counter_upper, counter_lower};
            timer <= {timer_upper, timer_lower};
            interval <= {timer_upper, timer_lower};
            interrupt <= 0;
        end
        else if (stop_then_acquire) begin
            counter <= 0;
            timer <= 0;
            interval <= 0;
            interrupt <= 0;
        end
        else if ((timer == 0) && (counter == 0)) begin
            counter <= 0;
            timer <= 0;
            interval <= 0;
            interrupt <= 0;
        end
        else if ((timer == 0) && (counter == 1)) begin
            counter <= 0;
            timer <= 0;
            interval <= 0;
            interrupt <= 1;
        end
        else if (timer == 0) begin
            counter <= counter - 1;
            timer <= interval;
            interval <= interval;
            interrupt <= 1;
        end
        else begin
            counter <= counter;
