module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [3:0] a, b, // Two 4-bit inputs
    input select,     // Select input to choose between adder and subtractor outputs
    output [3:0] out  // 4-bit output from the selected module
);

    // Instantiate the adder and subtractor modules
    four_bit_adder adder(.a(a), .b(b), .sum(add_out));
    four_bit_subtractor subtractor(.a(a), .b(b), .diff(sub_out));

    // Declare internal wires
    wire [3:0] add_out, sub_out;

    // Declare a flip-flop for the reset signal
    reg reset_ff;

    // Synchronous active-high reset
    always @(posedge clk) begin
        if (reset) begin
            reset_ff <= 1;
        end else begin
            reset_ff <= 0;
        end
    end

    // Instantiate the select module
    select_module select_inst(.add_out(add_out), .sub_out(sub_out), .select(select), .out(out));

