module abs_difference_sum (
  input [15:0] input_a,
  input [15:0] input_b,
  output reg [15:0] output_sum
);

  reg [3:0] a_0to3, a_4to7, a_8to11, a_12to15;
  reg [3:0] b_0to3, b_4to7, b_8to11, b_12to15;
  reg [3:0] abs_diff_0to3, abs_diff_4to7, abs_diff_8to11, abs_diff_12to15;
  reg [15:0] abs_diff_sum;

  // Split input vectors into 4-bit vectors
  assign a_0to3 = input_a[3:0];
  assign a_4to7 = input_a[7:4];
  assign a_8to11 = input_a[11:8];
  assign a_12to15 = input_a[15:12];
  assign b_0to3 = input_b[3:0];
  assign b_4to7 = input_b[7:4];
  assign b_8to11 = input_b[11:8];
  assign b_12to15 = input_b[15:12];

  // Calculate absolute difference between each corresponding 4-bit vector
  always @* begin
    abs_diff_0to3 = (a_0to3 > b_0to3) ? (a_0to3 - b_0to3) : (b_0to3 - a_0to3);
    abs_diff_4to7 = (a_4to7 > b_4to7) ? (a_4to7 - b_4to7) : (b_4to7 - a_4to7);
    abs_diff_8to11 = (a_8to11 > b_8to11) ? (a_8to11 - b_8to11) : (b_8to11 - a_8to11);
    abs_diff_12to15 = (a_12to15 > b_12to15) ? (a_12to15 - b_12to15) : (b_12to15 - a_12to15);
  end

  // Calculate sum of absolute differences
  always @* begin
    abs_diff_sum = {abs_diff_12to15, abs_diff_8to11, abs_diff_4to7, abs_diff_0to3};
    output_sum = abs_diff_sum;
  end

endmodule

module up_counter (
  input clk,
  input reset,
  output reg [3:0] count_out
);

reg j, k;

always @(posedge clk or posedge reset) begin
  if (reset) begin
    count_out <= 4'b0000;
    j <= 1'b0;
    k <= 1'b0;
  end
  else begin
    case ({j,k})
      2'b00: begin // Qn-1 = 0, Qn = 0
        count_out <= count_out + 1;
        j <= 1'b1;
      end
      2'b01: begin // Qn-1 = 0, Qn = 1
        j <= 1'b0;
        k <= 1'b1;
      end
      2'b10: begin // Qn-1 = 1, Qn = 0
        j <= 1'b1;
        k <= 1'b0;
      end
      2'b11: begin // Qn-1 = 1, Qn = 1
        j <= 1'b1;
        k <= 1'b1;
      end
    endcase
  end
end

endmodule

module vga_controller(
    input wire clk,
    input wire clr,
    output reg hsync,
    output reg vsync,
    output reg [11:0] hc,
    output reg [11:0] vc,
    output wire vidon
);

/* 1024x768@60MHz */
parameter hpixels = 12'd1344;
parameter vlines  = 12'd806;
parameter hsp   = 12'd136;
parameter hbp   = 12'd160;
parameter hfp   = 12'd24;
parameter vsp   = 12'd6;
parameter vbp   = 12'd29;
parameter vfp   = 12'd3;
/* */

reg vsenable;

initial begin
    hc <= hpixels - hsp - hbp;
    vc <= vlines - vsp - vbp;
    hsync <= 0;
    vsync <= 0;
    vsenable <= 0;
end

always @(posedge clk or posedge clr) begin
    if(clr == 1) begin
        hc <= hpixels - hsp - hbp;
    end else begin
        if(hc == hpixels - 1) begin
            hc <= 0;
            vsenable <= 1;
        end else begin
            hc <= hc + 1'b1;
            vsenable <= 0;
        end
    end
end

always @(*) begin
    if(hpixels - hsp - hbp < hc && hc <= hpixels - hbp) begin
        hsync = 0;
    end else begin
        hsync = 1;
    end
end

always @(posedge clk or posedge clr) begin
    if(clr == 1) begin
        vc <= vlines - vsp - vbp;
    end else if(vsenable == 1) begin
        if(vc == vlines - 1) begin
            vc <= 0;
        end else begin
            vc <= vc + 1'b1;
        end
    end
end

always @(*) begin
    if(vlines - vsp - vbp < vc && vc <= vlines - vbp) begin
        vsync = 0;
    end else begin
        vsync = 1;
    end
end

assign vidon=(hc<hpixels-hfp-hsp-hbp)&&(vc<vlines-vfp-vsp-vbp);

endmodule

module watchdog_timer (
  input clk,
  input rst,
  input [31:0] timeout,
  input event,
  output reg watchdog
);

  reg [31:0] count;
  reg start_timer;

  always @(posedge clk) begin
    if (rst) begin
      count <= 0;
      start_timer <= 0;
      watchdog <= 0;
    end
    else begin
      if (start_timer) begin
        count <= count + 1;
        if (count >= timeout) begin
          watchdog <= 1;
        end
      end
      else begin
        count <= 0;
      end
    end
  end

  always @(posedge clk) begin
    if (rst) begin
      start_timer <= 0;
    end
    else begin
      if (event) begin
        start_timer <= 1;
      end
      else begin
        start_timer <= 0;
      end
    end
  end

endmodule

