module alu (
    input [3:0] A,
    input [3:0] B,
    input [2:0] op,
    output [3:0] P
);

reg [3:0] A_reg, B_reg, P_reg;
reg [1:0] op_reg;
wire [3:0] add_out, sub_out, and_out, or_out;

assign add_out = A_reg + B_reg;
assign sub_out = A_reg - B_reg;
assign and_out = A_reg & B_reg;
assign or_out = A_reg | B_reg;

always @(*) begin
    A_reg <= A;
    B_reg <= B;
    op_reg <= op[2:1];
end

always @(posedge clk) begin
    case(op_reg)
        2'b00: P_reg <= add_out;
        2'b01: P_reg <= sub_out;
        2'b10: P_reg <= and_out;
        2'b11: P_reg <= or_out;
    endcase
end

always @(posedge clk) begin
    if(op[0] == 1) begin
        if(op_reg == 2'b01 && (A[3] == 1 || B[3] == 1)) begin
            P_reg <= $signed(P_reg);
        end else begin
            P_reg <= $unsigned(P_reg);
        end
    end
end

assign P = P_reg;

endmodule

module reset_sync (
  input clk,
  input rst_n,
  output rst
);

parameter delay_cycles = 10; // number of clock cycles to wait after reset

reg rst_synced;
reg [7:0] rst_counter;

always @(posedge clk) begin
  if (!rst_n) begin
    rst_synced <= 1'b0;
    rst_counter <= 8'd0;
  end
  else begin
    if (rst_n && !rst_synced) begin
      rst_counter <= rst_counter + 1;
      if (rst_counter == delay_cycles) begin
        rst_synced <= 1'b1;
      end
    end
    else begin
      rst_synced <= 1'b0;
      rst_counter <= 8'd0;
    end
  end
end

assign rst = rst_synced;

endmodule

