module WcaPortWrite(
  input wire reset,
  input wire port_enable,
  input wire wr_clk,
  input wire wr_en,
  input wire [31:0] wr_in,
  output wire empty,
  output wire full,
  output wire prog_empty,
  output wire prog_full,
  inout [31:0] pifData,
  input wire [(NBITS_ADDR+2):0] portCtrl,
  output wire [1:0] portCmd
);

  parameter ADDR_PORT = 0;
  parameter NBITS_ADDR = 2;
  parameter TEST_PATTERN = 0;

  wire [31:0] dout;
  wire isAddr = (ADDR_PORT == portCtrl[NBITS_ADDR+2:3]);
  wire rd_en = isAddr & portCtrl[1];

  assign portCmd = (isAddr) ? ((prog_full & port_enable) ? 2'b01 : 2'b00) : 2'bzz;

  FiFo512Core32W32R fifo512 (
    .rst(reset),
    .wr_clk(wr_clk),
    .rd_clk(portCtrl[0]),
    .din(wr_in),
    .wr_en(wr_en & port_enable),
