    .full(full),
    .empty(empty),
    .prog_full(prog_full),
    .prog_empty(prog_empty)
  );

  generate
    if (TEST_PATTERN == 1) begin
      assign pifData = (rd_en) ? ctr : 32'bz;
      reg [31:0] ctr;
      always @(posedge portCtrl[0]) begin
        if (reset) ctr <= 32'h0;
        else if (rd_en) ctr <= ctr + 32'h1;
