module flipflop (
    Q      ,
    CLK_N  ,
    D      ,
    SCD    ,
    SCE    ,
    RESET_B,
    VPWR   ,
    VGND   ,
    VPB    ,
    VNB
);

    // Module ports
    output Q      ;
    input  CLK_N  ;
    input  D      ;
    input  SCD    ;
    input  SCE    ;
    input  RESET_B;
    input  VPWR   ;
    input  VGND   ;
    input  VPB    ;
    input  VNB    ;

    // Local signals
    wire buf_Q          ;
    wire RESET          ;
    wire intclk         ;
    wire mux_out        ;
    reg  notifier       ;
    wire D_delayed      ;
    wire SCD_delayed    ;
    wire SCE_delayed    ;
    wire RESET_B_delayed;
    wire CLK_N_delayed  ;
    wire awake          ;
    wire cond0          ;
    wire cond1          ;
    wire cond2          ;
    wire cond3          ;
    wire cond4          ;

    // Delayed signals
    sky130_fd_sc_hd__udp_dff$SR_pp$PG$N dff1 (D_delayed      , D      , intclk, RESET, notifier, VPWR, VGND);
    sky130_fd_sc_hd__udp_dff$SR_pp$PG$N dff2 (SCD_delayed    , SCD    , intclk, RESET, notifier, VPWR, VGND);
    sky130_fd_sc_hd__udp_dff$SR_pp$PG$N dff3 (SCE_delayed    , SCE    , intclk, RESET, notifier, VPWR, VGND);
    sky130_fd_sc_hd__udp_dff$SR_pp$PG$N dff4 (RESET_B_delayed, RESET_B, intclk, RESET, notifier, VPWR, VGND);
    sky130_fd_sc_hd__udp_dff$SR_pp$PG$N dff5 (CLK_N_delayed  , CLK_N  , intclk, RESET, notifier, VPWR, VGND);

    // Inverters
    not not0 (RESET, RESET_B_delayed);
    not not1 (intclk, CLK_N_delayed);

    // Multiplexer
    sky130_fd_sc_hd__udp_mux_2to1 mux_2to1 (mux_out, D_delayed, SCD_delayed, SCE_delayed);

    // Flip-flop
    sky130_fd_sc_hd__udp_dff$PR_pp$PG$N dff0 (buf_Q, mux_out, intclk, RESET, notifier, VPWR, VGND);

    // Buffer
    buf buf0 (Q, buf_Q);

    // Conditions
    assign awake = (VPWR === 1'b1);
    assign cond0 = (awake && (RESET_B_delayed === 1'b1));
    assign cond1 = ((SCE_delayed === 1'b0) && cond0);
    assign cond2 = ((SCE_delayed === 1'b1) && cond0);
    assign cond3 = ((D_delayed !== SCD_delayed) && cond0);
    assign cond4 = (awake && (RESET_B === 1'b1));

endmodule

