  always @(posedge clk) begin
    if (rst) begin
      state <= IDLE;
      addr <= 0;
      len <= 0;
      size <= 0;
      data <= 0;
      burst_cnt <= 0;
      resp_cnt <= 0;
      resp <= 0;
      bresp <= 0;
    end else begin
      case (state)
        IDLE: begin
          if (ARVALID && RREADY) begin
            state <= ADDR;
            addr <= ARADDR;
            len <= ARLEN;
            size <= ARSIZE;
            burst_cnt <= 0;
          end else if (AWVALID && WVALID && AWREADY && WREADY) begin
            state <= DATA;
            addr <= AWADDR;
            len <= AWLEN;
            size <= AWSIZE;
            data <= WDATA;
            burst_cnt <= 0;
          end
        end
        ADDR: begin
          if (RREADY) begin
            state <= DATA;
            data <= $readmemh("mem.hex", addr, size);
            burst_cnt <= 1;
          end
        end
        DATA: begin
          if (RREADY && (burst_cnt < len[1:0])) begin
            addr <= addr + (1 << size);
            data <= $readmemh("mem.hex", addr, size);
            burst_cnt <= burst_cnt + 1;
          end else if (WVALID && WREADY && (burst_cnt < len[1:0])) begin
            addr <= addr + (1 << size);
            data <= WDATA;
            burst_cnt <= burst_cnt + 1;
          end else if ((burst_cnt == len[1:0]) && (resp_cnt == 0)) begin
            state <= RESP;
            resp_cnt <= 1;
            resp <= 0;
            bresp <= 0;
          end
        end
        RESP: begin
          if (RVALID && BREADY) begin
            state <= IDLE;
            resp_cnt <= 0;
          end else if (BVALID && BREADY) begin
            state <= IDLE;
            resp_cnt <= 0;
            resp <= 0;
            bresp <= 0;
          end else if (resp_cnt > 0) begin
            resp_cnt <= resp_cnt + 1;
            if (resp_cnt == 2) begin
              resp_cnt <= 0;
              resp <= 1;
              bresp <= 0;
            end else if (resp_cnt == 4) begin
              resp_cnt <= 0;
              resp <= 0;
              bresp <= 0;
            end
          end
        end
      endcase
    end
  end

endmodule

module dff_with_reset_and_notification (
  input SET,
  input RESET,
  input D,
  input NOTIFIER,
  input VPWR,
  input VGND,
  output reg Q,
  output reg CLK_N,
  output reg NOTIFIER_OUT
);

  // Create a clock
  reg CLK;
  initial begin
    CLK = 1'b0;
  end

  always begin
    #5 CLK = ~CLK;
  end

  // Create a power-on reset
  reg POR;
  initial begin
    POR = 1'b1;
    #100 POR = 1'b0;
  end

  // Create a notification output
  reg [1:0] NOTIFIER_STATE;
  always @(posedge CLK) begin
    case (NOTIFIER_STATE)
      2'd0: begin
        NOTIFIER_OUT <= 1'b0;
        if (NOTIFIER) begin
          NOTIFIER_STATE <= 2'd1;
        end
      end
      2'd1: begin
        NOTIFIER_OUT <= 1'b1;
        if (!NOTIFIER) begin
          NOTIFIER_STATE <= 2'd2;
        end
      end
      2'd2: begin
        NOTIFIER_OUT <= 1'b0;
        NOTIFIER_STATE <= 2'd0;
      end
      default: begin
        NOTIFIER_OUT <= 1'b0;
        NOTIFIER_STATE <= 2'd0;
      end
    endcase
  end

  // Connect the D flip-flop
  sky130_fd_sc_lp__udp_dff$NSR_pp$PG$N dut (
    .SET(SET),
    .RESET(RESET),
    .D(D),
    .NOTIFIER(NOTIFIER),
    .VPWR(VPWR),
    .VGND(VGND),
    .Q(Q),
    .CLK_N(CLK_N),
    .CLK(CLK),
    .POR(POR)
  );

endmodule

