module parity_checker (
  input [7:0] in,
  output reg [8:0] out
);

  wire [3:0] adder_out;
  wire parity_bit;

  assign parity_bit = ^in;

  assign adder_out[0] = in[0] ^ in[1];
  assign adder_out[1] = in[2] ^ in[3];
  assign adder_out[2] = in[4] ^ in[5];
  assign adder_out[3] = in[6] ^ in[7];

  assign out[8] = parity_bit;
  assign out[7:0] = {adder_out, in};

endmodule

module edge_detector (
  input clk,
  input reset,
  input in,
  output reg rise,
  output reg down
);

  reg [1:0] dff_out;

  always @(posedge clk, negedge reset) begin
    if (reset == 0) begin
      dff_out <= 2'b0;
    end else begin
      dff_out <= {dff_out[0], in};
    end
  end

  assign rise = (dff_out[0] == 1) && (dff_out[1] == 0);
  assign down = (dff_out[0] == 0) && (dff_out[1] == 1);

endmodule

