module top_module(
    input clk,
    input load,
    input [1:0] ena,
    input [99:0] data,
    output reg [99:0] rotator_out,
    output reg out
);

    reg [99:0] shift_reg;
    reg [99:0] temp_reg;
    reg [5:0] shift_amt;

    always @(posedge clk) begin
        if(load) begin
            shift_reg <= data;
        end else if(ena == 2'b01) begin
            shift_reg <= {shift_reg[shift_amt-1:0], shift_reg[99:shift_amt]};
        end else if(ena == 2'b10) begin
            shift_reg <= {shift_reg[99-shift_amt:99], shift_reg[0:99-shift_amt-1]};
        end
    end

    always @(*) begin
        case(ena)
            2'b00: shift_amt = 6'd0;
            2'b01: shift_amt = {1'b0, data[4:0]};
            2'b10: shift_amt = {1'b0, ~data[4:0] + 1};
            2'b11: shift_amt = 6'd0;
        endcase
    end

    nor_gate nor_gate_inst(
        .a(shift_reg[0]),
        .b(shift_reg[1]),
        .out(out)
    );

    functional_module functional_module_inst(
        .rotator_out(rotator_out),
        .nor_out(out),
        .final_out(final_out)
    );

endmodule

