module dc_offset_removal #(
  parameter WIDTH = 14, // input and output signal width
  parameter ADDR_WIDTH = 4, // address width of the register file
  parameter ALPHA_SHIFT = 8 // shift amount for filter coefficient
)(
  input clk, // clock signal
  input rst, // reset signal
  input set_stb, // strobe signal indicating that the set_addr and set_data inputs are valid
  input [ADDR_WIDTH-1:0] set_addr, // address of the register to be set
  input [WIDTH-1:0] set_data, // data to be written to the register
  input [WIDTH-1:0] in, // input signal to be processed
  output reg [WIDTH-1:0] out // processed output signal
);

// register file
reg [WIDTH-1:0] regs [0:(1<<ADDR_WIDTH)-1];

// filter coefficient
parameter ALPHA = 2**(-ALPHA_SHIFT);

// state variables
reg [WIDTH-1:0] y; // output signal
reg [WIDTH-1:0] y_prev; // previous output signal

// process input signal
always @(posedge clk) begin
  if (rst) begin
    y <= 0;
    y_prev <= 0;
  end else begin
    // read register if set_stb is high
    if (set_stb) begin
      regs[set_addr] <= set_data;
    end

    // calculate filtered output
    y <= ALPHA * (in - regs[0]) + (1 - ALPHA) * y_prev;
    y_prev <= y;

    // remove DC offset from output
    out <= y - regs[0];
  end
end

endmodule

