wire [n-1:0] shifted;

// generate the shifted signals
genvar i;
generate
  for (i = 0; i < log2(n); i = i + 1) begin : stage
    wire [n-1:0] shifted_stage;
    assign shifted_stage = {in[(n-1) >> i : 0], {i{1'b0}}};
    assign shifted_stage = {shifted_stage[n-1], shifted_stage[n-1:1]};
    assign shifted = (shift[i] == 1'b0) ? shifted_stage : {shifted[n-1], shifted[0:n-2]};
  end
endgenerate

// connect the output to the shifted signals
assign out = (dir == 1'b0) ? shifted : {shifted[n-1], shifted[0:n-2]};

