module mux_select(
    input [3:0] in1_a,
    input [3:0] in2_a,
    input [3:0] in3_a,
    input [3:0] in4_a,
    input sel_a,
    input [3:0] in1_b,
    input [3:0] in2_b,
    input [3:0] in3_b,
    input [3:0] in4_b,
    input sel_b,
    output [3:0] out_always
);

