module LFSR25000(
input Clock,
input Rst,
output reg [15:0] LFSR
);

always@(posedge Clock or posedge Rst) begin
    if(Rst) begin
        LFSR <= 16'hACE1;
    end
    else begin
        LFSR <= {LFSR[0]^LFSR[3]^LFSR[12]^LFSR[15], LFSR[0:14]};
    end
end

endmodule

module KeyPadScanner(
input Rst,
input Clock,
input [3:0] RowDataIn,
output [3:0] ColDataOut,
input LFSRRst,
input LFSRFlg,
output reg [3:0] KeyCode,
output reg KeyReady,
input KeyRead
);

reg [3:0] RowData;
reg [3:0] ColData;
reg [3:0] PrevColData;
reg [3:0] PrevKeyCode;
reg [3:0] DebounceCount;
reg [3:0] PrevDebounceCount;
reg [3:0] PressCount;

always@(posedge Clock or posedge Rst) begin
    if(Rst) begin
        RowData <= 4'b1111;
        ColData <= 4'b1111;
        PrevColData <= 4'b1111;
        KeyCode <= 4'b0000;
        DebounceCount <= 4'b0000;
        PrevDebounceCount <= 4'b0000;
        PressCount <= 4'b0000;
        KeyReady <= 1'b0;
    end
    else begin
        RowData <= RowDataIn;
        PrevColData <= ColData;
        ColData <= {ColData[2:0], ~ColData[3]};
        if(LFSRFlg) begin
            if(KeyRead) begin
                if(KeyCode == PrevKeyCode && DebounceCount != PrevDebounceCount) begin
                    if(DebounceCount == 4'b1111) begin
                        KeyReady <= 1'b1;
                        PressCount <= PressCount + 1;
                        PrevDebounceCount <= DebounceCount;
                    end
                    else begin
                        DebounceCount <= DebounceCount + 1;
                    end
                end
                else begin
                    PrevKeyCode <= KeyCode;
                    KeyCode <= {RowData & ColData};
                    DebounceCount <= 4'b0000;
                end
            end
            else begin
                KeyReady <= 1'b0;
            end
        end
    end
end

assign ColDataOut = ColData;

endmodule

