        4'b1001: DataOut <= 4'b1001;
        4'b1010: DataOut <= 4'b1010;
        4'b1011: DataOut <= 4'b1011;
        4'b1100: DataOut <= 4'b1100;
        4'b1101: DataOut <= 4'b1101;
        4'b1110: DataOut <= 4'b1110;
