module bidirectional_buffer(
  input dir,
  input nOE,
  inout [3:0] A,
  inout [3:0] B,
  output reg [3:0] C
);

  assign A = nOE ? 4'bzzzz : (dir ? 4'bzzzz : B);
  assign B = nOE ? 4'bzzzz : (dir ? A : 4'bzzzz);
  assign #10 B = nOE ? 4'bzzzz : (dir ? A : B);

  always @ (posedge dir or posedge nOE) begin
    if (nOE) begin
      A <= 4'bzzzz;
      B <= 4'bzzzz;
    end else if (dir) begin
      A <= B;
    end else begin
      B <= A;
    end
  end

  assign #100 C = A;

endmodule

