module chatgpt_generate_edge_detect(
  input               clk,
  input               rst_n,
  input               a,
  output reg          rise,
  output reg          down
);

  // Define the states for the state machine
  localparam IDLE = 2'b00;
  localparam RISING = 2'b01;
  localparam FALLING = 2'b10;

  // Define the current state and next state variables
  reg [1:0] state, next_state;

  // Define the rising and falling edge detection variables
  reg a_prev;
  reg a_curr;

  // Assign the initial state
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state <= IDLE;
    end else begin
      state <= next_state;
    end
  end

  // Define the state machine transitions and outputs
  always @(*) begin
    case (state)
      IDLE: begin
        if (a_curr && !a_prev) begin
          next_state = RISING;
          rise = 1'b1;
          down = 1'b0;
        end else if (!a_curr && a_prev) begin
          next_state = FALLING;
          rise = 1'b0;
          down = 1'b1;
        end else begin
          next_state = IDLE;
          rise = 1'b0;
          down = 1'b0;
        end
      end
      RISING: begin
        next_state = IDLE;
        rise = 1'b0;
        down = 1'b0;
      end
      FALLING: begin
        next_state = IDLE;
        rise = 1'b0;
        down = 1'b0;
      end
      default: begin
        next_state = IDLE;
        rise = 1'b0;
        down = 1'b0;
      end
    endcase
  end

  // Update the edge detection variables
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      a_prev <= 1'b0;
      a_curr <= 1'b0;
    end else begin
      a_prev <= a_curr;
      a_curr <= a;
    end
  end

endmodule

module i64ToRecF32 (
    input [(`floatControlWidth - 1):0] control,
    input [63:0] in,
    input [2:0] roundingMode,
    output [32:0] out,
    output [4:0] exceptionFlags
);

    // Define constants for IEEE 754 single-precision format
    parameter EXP_WIDTH = 8;
    parameter SIG_WIDTH = 23;
    parameter BIAS = 127;

    // Define constants for input integer format
    parameter INT_WIDTH = 64;
    parameter FRAC_WIDTH = 63;
    parameter SIGN_WIDTH = 1;
    parameter INT_MAX = 2**(INT_WIDTH-1) - 1;
    parameter INT_MIN = -2**(INT_WIDTH-1);

    // Define constants for exception flags
    parameter INEXACT = 1;
    parameter UNDERFLOW = 2;
    parameter OVERFLOW = 4;
    parameter INVALID_OP = 8;
    parameter INPUT_DENORMAL = 16;

    // Define local variables
    reg [SIG_WIDTH:0] sig;
    reg [EXP_WIDTH:0] exp;
    reg sign;
    reg inexact;
    reg underflow;
    reg overflow;
    reg invalid_op;
    reg input_denormal;
    reg [FRAC_WIDTH:0] frac;
    reg [INT_WIDTH-1:0] abs_in;
    reg [EXP_WIDTH:0] unbiased_exp;
    reg [SIG_WIDTH:0] rounded_sig;
    reg [31:0] out_int;
    reg [4:0] exc_flags;

    // Extract sign bit and absolute value of input
    assign sign = in[63];
    assign abs_in = (sign) ? (~in + 1) : in;

    // Check for input denormal
    always @* begin
        if (abs_in == 0) begin
            input_denormal = 1;
        end else begin
            input_denormal = 0;
        end
    end

    // Determine unbiased exponent and fraction of input
    always @* begin
        if (abs_in == 0) begin
            unbiased_exp = 0;
            frac = 0;
        end else if (abs_in >= 2**(EXP_WIDTH+SIG_WIDTH)) begin
            unbiased_exp = 2**EXP_WIDTH - 1;
            frac = 0;
            overflow = 1;
        end else begin
            // Compute unbiased exponent
            unbiased_exp = EXP_WIDTH + BIAS - 1;
            while (abs_in < 2**(EXP_WIDTH+SIG_WIDTH-1)) begin
                unbiased_exp = unbiased_exp - 1;
                abs_in = abs_in << 1;
            end
            while (abs_in >= 2**(EXP_WIDTH+SIG_WIDTH)) begin
                unbiased_exp = unbiased_exp + 1;
                abs_in = abs_in >> 1;
            end
            // Compute fraction
            frac = abs_in[FRAC_WIDTH-1:0];
        end
    end

    // Round fraction according to specified rounding mode
    always @* begin
        case (roundingMode)
            3'b000: begin // Round to nearest
                if (frac[SIG_WIDTH] == 1 && (frac[SIG_WIDTH-1:0] != {SIG_WIDTH-1{1'b0}} || frac[0] == 1)) begin
                    // Tie-breaking: round to even
                    frac = frac + 1;
                    if (frac[SIG_WIDTH] == 1) begin
                        frac[SIG_WIDTH-1:0] = frac[SIG_WIDTH-1:0] ^ {SIG_WIDTH-1{1'b1}};
                    end
                end
            end
            3'b001: begin // Round towards positive infinity
                if (frac != {SIG_WIDTH{1'b0}} || unbiased_exp == 2**EXP_WIDTH-1) begin
                    frac = frac + 1;
                end
            end
            3'b010: begin // Round towards negative infinity
                if (frac != {SIG_WIDTH{1'b0}} || unbiased_exp == 2**EXP_WIDTH-1) begin
                    frac = frac;
                end
            end
            3'b011: begin // Round towards zero
                frac = frac;
            end
        endcase
    end

    // Check for overflow and underflow
    always @* begin
        if (unbiased_exp == 2**EXP_WIDTH-1 && frac != {SIG_WIDTH{1'b0}}) begin
            overflow = 1;
        end else if (unbiased_exp == 0 && frac[SIG_WIDTH-1:0] == {SIG_WIDTH-1{1'b0}}) begin
            underflow = 1;
        end
    end

    // Compute final exponent and significand
    always @* begin
        if (overflow) begin
            exp = 2**EXP_WIDTH - 1;
            sig = 0;
        end else if (underflow) begin
            exp = 0;
            sig = frac[SIG_WIDTH-2:0];
        end else begin
            exp = unbiased_exp;
            sig = frac[SIG_WIDTH-2:0];
        end
    end

    // Set exception flags
    always @* begin
        if (inexact) begin
            exc_flags = exc_flags | INEXACT;
        end
        if (underflow) begin
            exc_flags = exc_flags | UNDERFLOW;
        end
        if (overflow) begin
            exc_flags = exc_flags | OVERFLOW;
        end
        if (invalid_op) begin
            exc_flags = exc_flags | INVALID_OP;
        end
        if (input_denormal) begin
            exc_flags = exc_flags | INPUT_DENORMAL;
        end
    end

    // Convert exponent and significand to output format
    always @* begin
        out_int = {sign, exp[EXP_WIDTH-1:0] + BIAS, sig};
    end

    // Convert output integer to floating-point format
    iNToRecFN#(32, EXP_WIDTH, SIG_WIDTH)
        iNToRecFN(control, 0, out_int, roundingMode, out, exceptionFlags);

endmodule

