module tone_generator (
  input [15:0] freq,
  input [15:0] duration,
  output [15:0] wave
);

parameter waveform_type = 2'b01; // sine waveform

reg [15:0] counter;
reg [15:0] sine_wave;
reg [15:0] square_wave;
reg [15:0] dtmf_wave;
reg [1:0] wave_type;

// Generate sine wave
always @ (posedge clk) begin
  sine_wave <= sin(2 * $pi * freq * counter / 1000000) * 32767;
end

// Generate square wave
always @ (posedge clk) begin
  if (counter < 1000000 / (2 * freq)) begin
    square_wave <= 32767;
  end else begin
    square_wave <= -32767;
  end
end

// Generate DTMF wave
always @ (posedge clk) begin
  case (counter % (1000000 / freq))
    0: dtmf_wave <= 16383;
    1000000 / (2 * freq): dtmf_wave <= 16383;
    1000000 / freq: dtmf_wave <= -16383;
    1000000 / (2 * freq) + 1000000 / freq: dtmf_wave <= -16383;
    default: dtmf_wave <= 0;
  endcase
end

// Counter for duration
always @ (posedge clk) begin
  if (counter == duration) begin
    counter <= 0;
  end else begin
    counter <= counter + 1;
  end
end

// Multiplexer to select waveform type
always @ (wave_type, sine_wave, square_wave, dtmf_wave) begin
  case (wave_type)
    2'b00: wave <= dtmf_wave;
    2'b01: wave <= sine_wave;
    2'b10: wave <= square_wave;
    default: wave <= 0;
  endcase
end

endmodule

