module IntController (
  input [n-1:0] irq,
  input ien,
  output reg [n-1:0] ack,
  output reg int
);

parameter n = 4; // number of interrupt sources
parameter [n-1:0] p = 4'h3; // priority of each interrupt source (0 is highest priority)

integer i;
reg [n-1:0] priority_mask;
reg [n-1:0] highest_priority_irq;

always @(*) begin
  int = 1'b0;
  ack = {n{1'b0}};
  priority_mask = {n{1'b1}};
  highest_priority_irq = {n{1'b0}};

  for (i = 0; i < n; i = i + 1) begin
    if (irq[i] && ien) begin
      if (p[i] < priority_mask) begin
        priority_mask = p[i];
        highest_priority_irq = 1 << i;
      end
    end
  end

  if (priority_mask != {n{1'b1}}) begin
    int = 1'b1;
    ack = highest_priority_irq;
  end
end

endmodule

module sd_crc_16(BITVAL, ENABLE, BITSTRB, CLEAR, CRC);
   input        BITVAL;                            // Next input bit
   input        ENABLE;                            // Enable calculation
   input        BITSTRB;                           // Current bit valid (Clock)
   input        CLEAR;                             // Init CRC value
   output [15:0] CRC;                               // Current output CRC value

   reg    [15:0] CRC;                               // We need output registers
   wire         inv;

   assign inv = BITVAL ^ CRC[15];                   // XOR required?

   always @(posedge BITSTRB or posedge CLEAR) begin
      if (CLEAR) begin
         CRC <= 0;                                  // Init before calculation
         end
      else begin
         if (ENABLE == 1) begin
             CRC[15] <= CRC[14];
             CRC[14] <= CRC[13];
             CRC[13] <= CRC[12];
             CRC[12] <= CRC[11] ^ inv;
             CRC[11] <= CRC[10];
             CRC[10] <= CRC[9];
             CRC[9] <= CRC[8];
             CRC[8] <= CRC[7];
             CRC[7] <= CRC[6];
             CRC[6] <= CRC[5];
             CRC[5] <= CRC[4] ^ inv;
             CRC[4] <= CRC[3];
             CRC[3] <= CRC[2];
             CRC[2] <= CRC[1];
             CRC[1] <= CRC[0];
             CRC[0] <= inv;
             end
         end
      end

endmodule

module manchester (
  input binary_in,
  output reg manchester_out,
  output reg binary_out
);

parameter f = 1000000; // frequency of the clock signal

reg clock = 0;
reg prev_binary_in = 0;

always #((1/f)/2) clock = ~clock; // generate clock signal

always @(posedge clock) begin
  // Manchester encoder
  if (binary_in == 0) begin
    manchester_out <= 1;
  end else begin
    manchester_out <= 0;
  end

  // Manchester decoder
  if (prev_binary_in == 1 && binary_in == 0) begin
    binary_out <= 1;
  end else if (prev_binary_in == 0 && binary_in == 1) begin
    binary_out <= 0;
  end

  prev_binary_in <= binary_in;
end

endmodule

