  //---------------------------HW INTERFACE-----------------------------------
  //--------------------------------------------------------------------------
  input  wire        adc_fco,
  input  wire        adc_dco,
  input  wire        adc_dat_a,
  input  wire        adc_dat_b,
  input  wire        adc_dat_c,
