module SecondOrderLPF #(
    parameter K0_SHIFT = 8, ///< K0 filter term = 2^-K0_SHIFT
    parameter K1_SHIFT = 8, ///< K1 filter term = 2^-K1_SHIFT
    parameter WIDTH = 16,   ///< Width of data path
    parameter CLAMP = 1     ///< Set to 1 to clamp the accumulators
)
(
    input clk,                        ///< System clock
    input rst,                        ///< Reset, synchronous & active high
    input en,                         ///< Filter strobe
    input  signed [WIDTH-1:0] dataIn, ///< Filter input
    output signed [WIDTH-1:0] dataOut ///< Filter output
);

reg signed [WIDTH+K0_SHIFT-1:0] acc0;
reg signed [WIDTH+K1_SHIFT-1:0] acc1;
reg signed [WIDTH+1:0] forwardIn;

wire signed [WIDTH-1:0] acc0Out;
wire signed [WIDTH+K0_SHIFT:0] acc0In;
wire signed [WIDTH+K1_SHIFT:0] acc1In;

assign acc0In = acc0 + forwardIn;
assign acc1In = acc1 + acc0Out;

always @(posedge clk) begin
    if (rst) begin
        forwardIn <= 'd0;
        acc0      <= 'd0;
        acc1      <= 'd0;
    end
    else if (en) begin
        forwardIn <= dataIn - acc0Out - dataOut;
        if (CLAMP) begin
            acc0 <= (^acc0In[WIDTH+K0_SHIFT-:2])
                  ? {acc0In[WIDTH+K0_SHIFT], {(WIDTH+K0_SHIFT-1){acc0In[WIDTH+K0_SHIFT-1]}}}
                  : acc0In;
            acc1 <= (^acc1In[WIDTH+K1_SHIFT-:2])
                  ? {acc1In[WIDTH+K1_SHIFT], {(WIDTH+K1_SHIFT-1){acc1In[WIDTH+K1_SHIFT-1]}}}
                  : acc1In;
        end
        else begin
            acc0 <= acc0In;
            acc1 <= acc1In;
        end
    end
end

assign acc0Out = acc0 >>> K0_SHIFT;
assign dataOut = acc1 >>> K1_SHIFT;

// Filter coefficients
parameter signed [WIDTH-1:0] b0 = 1;
parameter signed [WIDTH-1:0] b1 = -2;
parameter signed [WIDTH-1:0] b2 = 1;
parameter signed [WIDTH-1:0] a1 = -1;
parameter signed [WIDTH-1:0] a2 = 0.5;

// Calculate the feedback and feedforward terms
reg signed [WIDTH-1:0] feedback;
reg signed [WIDTH-1:0] feedforward;

always @(*) begin
    feedback = -(a1 * acc0Out) - (a2 * acc1Out);
    feedforward = (b0 * forwardIn) + (b1 * acc0Out) + (b2 * acc1Out);
end

assign acc0In = acc0 + feedforward;
assign acc1In = acc1 + feedback;

endmodule

module top_module (
    input clk,
    input reset,
    input [31:0] a,
    output [31:0] result
);

    wire [31:0] shift_out;
    wire [31:0] addsub_out;
    wire [31:0] shift_complement;
    wire [31:0] function_out;

    addsub_module addsub_inst (
        .a(a),
        .b(shift_out),
        .sub(0),
        .sum(addsub_out)
    );

    shift_register_module shift_inst (
        .clk(clk),
        .data_in(addsub_out),
        .data_out(shift_out)
    );

    assign shift_complement = ~shift_out;

    function_module function_inst (
        .addsub_out(addsub_out),
        .shift_complement(shift_complement),
        .result(function_out)
    );

    assign result = function_out;

endmodule

module addsub_module (
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] sum
);

    assign sum = sub ? a - b : a + b;

endmodule

module shift_register_module (
    input clk,
    input [31:0] data_in,
    output [31:0] data_out
);

    reg [31:0] shift_reg;

    always @(posedge clk) begin
        shift_reg <= {shift_reg[30:0], data_in[0]};
    end

    assign data_out = shift_reg;

endmodule

module function_module (
    input [31:0] addsub_out,
    input [31:0] shift_complement,
    output [31:0] result
);

    assign result = addsub_out * shift_complement;

endmodule

module toggle_module (
   input clk,
   input toggle,
   input [7:0] cyc_copy,
   output reg toggle_up
);

   reg [7:0] cyc_count;
   reg [7:0] cyc_copy_reg;
   reg toggle_internal;

   always @(posedge clk) begin
      toggle_internal <= toggle;
   end

   always @(posedge clk) begin
      if (toggle_internal != toggle) begin
         cyc_count <= 0;
      end else begin
         cyc_count <= cyc_count + 1;
      end
   end

   always @(posedge clk) begin
      if (cyc_count == cyc_copy_reg) begin
         toggle_up <= ~toggle_up;
         cyc_count <= 0;
         cyc_copy_reg <= cyc_copy;
      end else begin
         cyc_copy_reg <= cyc_copy;
      end
   end

endmodule

module max_4bit (
    A,
    B,
    C,
    X
);

    output [3:0] X;
    input  [3:0] A;
    input  [3:0] B;
    input  [3:0] C;

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;

    wire [3:0] max_value;

    // Determine the maximum value among A, B, and C
    assign max_value = (A >= B) ? ((A >= C) ? A : C) : ((B >= C) ? B : C);

    // Determine if there are any ties
    wire is_tie_A_B = (A == B);
    wire is_tie_A_C = (A == C);
    wire is_tie_B_C = (B == C);

    // Determine the final output value based on the maximum value and any ties
    assign X = (max_value == A) ? (is_tie_A_B || is_tie_A_C) ? max_value : A :
              (max_value == B) ? (is_tie_A_B || is_tie_B_C) ? max_value : B :
                                 (is_tie_A_C || is_tie_B_C) ? max_value : C;

endmodule

module pipelined_bitwise_operations(
    input [3:0] in1,
    input [3:0] in2,
    input [3:0] in3,
    input [3:0] in4,
    output reg [3:0] out_and,
    output reg [3:0] out_or,
    output reg [3:0] out_xor
);

reg [3:0] and1, and2, and3;
reg [3:0] or1, or2, or3;
reg [3:0] xor1, xor2, xor3;

always @(*) begin
    and1 = in1 & in2;
    or1 = in1 | in2;
    xor1 = in1 ^ in2;

    and2 = and1 & in3;
    or2 = or1 | in3;
    xor2 = xor1 ^ in3;

    and3 = and2 & in4;
    or3 = or2 | in4;
    xor3 = xor2 ^ in4;
end

assign out_and = and3;
assign out_or = or3;
assign out_xor = xor3;

endmodule

