 NOR2 XIL_NOR2_1 (.I0(IN1), .I1(IN2), .O(n1));
 NOR2 XIL_NOR2_2 (.I0(IN3), .I1(IN4), .O(n2));
 NOR2 XIL_NOR2_3 (.I0(n1), .I1(n2), .O(n3));
