module top_module(
    input a,
    input b,
    input sel_b1,
    input sel_b2,
    input [15:0] a_mult,
    input [15:0] b_mult,
    input enable_mult,
    input select,
    output reg [31:0] product,
    output reg out_always
);

    // Multiplexer
    wire mux_out = ((~sel_b1 & ~sel_b2) & a) | ((~sel_b1 & sel_b2) & b);

    // Multiplier
    wire [31:0] adder_out1, adder_out2;
    wire [31:0] and_out;
    wire mult_enable = enable_mult & select;
    adder adder1(.a(a_mult), .b(0), .cin(0), .s(adder_out1), .cout());
    adder adder2(.a(b_mult), .b(0), .cin(0), .s(adder_out2), .cout());
    assign and_out = a_mult & b_mult;
    assign product = mult_enable ? {adder_out1, adder_out2} : {32{1'b0}};

    // Control Logic
    assign out_always = select ? product[31] : mux_out;

endmodule

module adder(
    input [15:0] a,
    input [15:0] b,
    input cin,
    output [15:0] s,
    output cout
);

    assign s = a + b + cin;
    assign cout = (s[16] == 1'b1);

endmodule

module top_module(
    input               clk         ,   
    input               rst_n       ,
    input       [31:0]  a_in        ,
    input       [31:0]  b_in        ,
    input       [7:0]   data_in     ,
    input               select      ,
    input               valid_a     ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out    ,
    output  reg [31:0]  sum_out
);

// Accumulator module
reg [7:0] accumulator;
reg [2:0] count;
reg [7:0] temp_sum;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        accumulator <= 0;
        count <= 0;
        temp_sum <= 0;
    end
    else begin
        if (valid_a) begin
            accumulator <= accumulator + data_in;
            count <= count + 1;
            if (count == 7) begin
                temp_sum <= accumulator;
                accumulator <= 0;
                count <= 0;
            end
        end
    end
end

// Adder/Subtractor module
wire [31:0] a;
wire [31:0] b;
wire [31:0] result;

assign a = select ? a_in : b_in;
assign b = select ? b_in : a_in;

adder_subtractor add_sub(
    .clk(clk),
    .a(a),
    .b(b),
    .select(select),
    .valid_a(valid_a),
    .ready_b(ready_b),
    .valid_b(valid_b),
    .sum_out(result)
);

// Output module
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        data_out <= 0;
        sum_out <= 0;
    end
    else begin
        if (valid_b) begin
            data_out <= 10'b0000000001;
            sum_out <= result;
        end
        else begin
            data_out <= 10'b0000000000;
            sum_out <= temp_sum;
        end
    end
end

// Handshake module
handshake_module handshake(
    .clk(clk),
    .rst_n(rst_n),
    .valid_in(valid_b),
    .ready_in(ready_b),
    .valid_out(valid_a),
    .ready_out(ready_a)
);

endmodule

module shift_counter_adder (
    input clk,
    input reset,
    input [3:0] shift_in,
    input shift_load,
    input up_down,
    input count_enable,
    output reg [3:0] count,
    output max_reached,
    output [7:0] result
);

reg [3:0] shift_reg;
reg [3:0] count_reg;

always @(posedge clk) begin
    if (reset) begin
        shift_reg <= 0;
        count_reg <= 0;
    end else begin
        if (shift_load) begin
            shift_reg <= shift_in;
        end else begin
            shift_reg <= {shift_reg[2:0], shift_reg[3]};
        end

        if (count_enable) begin
            if (up_down) begin
                if (count_reg == 4'b1111) begin
                    count_reg <= 4'b0000;
                    max_reached <= 1;
                end else begin
                    count_reg <= count_reg + 1;
                    max_reached <= 0;
                end
            end else begin
                if (count_reg == 4'b0000) begin
                    count_reg <= 4'b1111;
                    max_reached <= 1;
                end else begin
                    count_reg <= count_reg - 1;
                    max_reached <= 0;
                end
            end
        end
    end
end

assign result = shift_reg + count_reg;

endmodule

module hpdmc_ctlif #(
	parameter csr_addr = 1'b0
) (
	input sys_clk,
	input sys_rst,

	input      [ 2:0] csr_a,
	input             csr_we,
	input      [15:0] csr_di,
	output reg [15:0] csr_do,

	output reg bypass,
	output reg sdram_rst,

	output reg        sdram_cke,
	output reg        sdram_cs_n,
	output reg        sdram_we_n,
	output reg        sdram_cas_n,
	output reg        sdram_ras_n,
	output reg [11:0] sdram_adr,
	output     [ 1:0] sdram_ba,

	/* Clocks we must wait following a PRECHARGE command (usually tRP). */
	output reg [2:0] tim_rp,
	/* Clocks we must wait following an ACTIVATE command (usually tRCD). */
	output reg [2:0] tim_rcd,
	/* CAS latency, 0 = 2 */
	output reg tim_cas,
	/* Auto-refresh period (usually tREFI). */
	output reg [10:0] tim_refi,
	/* Clocks we must wait following an AUTO REFRESH command (usually tRFC). */
	output reg [3:0] tim_rfc,
	/* Clocks we must wait following the last word written to the SDRAM (usually tWR). */
	output reg [1:0] tim_wr
);

wire csr_selected = csr_a[2] == csr_addr;

// We assume sdram_ba will be always zero, so we can truncate the bus to 16 bits
assign sdram_ba = 2'b00;

always @(posedge sys_clk) begin
	if(sys_rst) begin
		csr_do <= 32'd0;

		bypass <= 1'b1;
		sdram_rst <= 1'b1;

		sdram_cke <= 1'b0;
		sdram_adr <= 13'd0;

		tim_rp <= 3'd2;
		tim_rcd <= 3'd2;
		tim_cas <= 1'b0;
		tim_refi <= 11'd740;
		tim_rfc <= 4'd8;
		tim_wr <= 2'd2;
	end else begin
		sdram_cs_n <= 1'b1;
		sdram_we_n <= 1'b1;
		sdram_cas_n <= 1'b1;
		sdram_ras_n <= 1'b1;

		csr_do <= 32'd0;
		if(csr_selected) begin
			if(csr_we) begin
				case(csr_a[1:0])
					2'b00: begin
						bypass <= csr_di[0];
						sdram_rst <= csr_di[1];
						sdram_cke <= csr_di[2];
					end
					2'b01: begin
						sdram_cs_n <= ~csr_di[0];
						sdram_we_n <= ~csr_di[1];
						sdram_cas_n <= ~csr_di[2];
						sdram_ras_n <= ~csr_di[3];
						sdram_adr <= csr_di[15:4];
					end
					2'b10: begin
						tim_rp <= csr_di[2:0];
						tim_rcd <= csr_di[5:3];
						tim_cas <= csr_di[6];
						tim_rfc <= csr_di[10:7];
						tim_wr <= csr_di[12:11];
					end
          2'b11: begin
						tim_refi <= csr_di[10:0];
          end
				endcase
			end
			case(csr_a[1:0])
				2'b00: csr_do <= {sdram_cke, sdram_rst, bypass};
				2'b01: csr_do <= {sdram_adr, 4'h0};
				2'b10: csr_do <= {tim_wr, tim_rfc, tim_cas, tim_rcd, tim_rp};
        2'b11: csr_do <= {5'd0, tim_refi};
			endcase
		end
	end
end

// --------------------------------------------------------------------
endmodule

module sigma_delta (
  input clk,
  input rst,
  input [15:0] vin,
  output reg sdout
);

  parameter n = 16; // number of bits in binary data stream
  parameter f = 1000000; // sampling frequency of analog input signal
  parameter fs = 100000000; // sampling frequency of binary data stream

  reg [n-1:0] quantized_signal;
  reg [n-1:0] feedback_signal;
  reg [n-1:0] delta_signal;
  reg [n-1:0] oversampled_signal;
  reg [31:0] accumulator;

  always @(posedge clk) begin
    if (rst) begin
      quantized_signal <= 0;
      feedback_signal <= 0;
      delta_signal <= 0;
      oversampled_signal <= 0;
      accumulator <= 0;
      sdout <= 0;
    end else begin
      oversampled_signal <= {vin, oversampled_signal[n-1:0]};
      delta_signal <= oversampled_signal - feedback_signal;
      quantized_signal <= delta_signal >= 0;
      feedback_signal <= quantized_signal ? feedback_signal + delta_signal : feedback_signal - delta_signal;
      accumulator <= accumulator + quantized_signal - (fs/f);
      if (accumulator[n] == 1) begin
        sdout <= ~sdout;
        accumulator <= accumulator - (1 << n);
      end
    end
  end
endmodule

module sigma_delta_demod (
  input clk,
  input rst,
  input [15:0] sdin,
  output reg [15:0] vout
);

  parameter n = 16; // number of bits in binary data stream
  parameter f = 1000000; // sampling frequency of analog input signal
  parameter fs = 100000000; // sampling frequency of binary data stream

  reg [n-1:0] quantized_signal;
  reg [n-1:0] feedback_signal;
  reg [n-1:0] delta_signal;
  reg [n-1:0] oversampled_signal;
  reg [31:0] accumulator;

  always @(posedge clk) begin
    if (rst) begin
      quantized_signal <= 0;
      feedback_signal <= 0;
      delta_signal <= 0;
      oversampled_signal <= 0;
      accumulator <= 0;
      vout <= 0;
    end else begin
      quantized_signal <= sdin[0];
      feedback_signal <= quantized_signal ? feedback_signal + delta_signal : feedback_signal - delta_signal;
      delta_signal <= quantized_signal ? delta_signal + feedback_signal : delta_signal - feedback_signal;
      accumulator <= accumulator + delta_signal + (f/fs);
      if (accumulator[n] == 1) begin
        vout <= accumulator[n-1:0];
        accumulator <= accumulator - (1 << n);
      end
      sdin <= {sdin[n-1:1], sdout};
    end
  end
endmodule

module dex_smdisp
(
 input     de_clk,
 input     de_rstn,
 input     d_busy,
 input     cmdrdy,
 input     pcbusy,
 input     line_actv_1,
 input     blt_actv_1,
 input     noop_actv_2,

 output reg    goline,
 output reg    goblt,
 output reg    d_cmdack,
 output reg    d_cmdcpyclr,
 output reg    load_actvn,
 // For test only.
 output reg    [1:0] d_cs
 );

/****************************************************************/
/*          DEFINE PARAMETERS         */
/****************************************************************/
/* define state parameters */
parameter
    IDLE=2'b00,
    DECODE=2'b01,
    BUSY=2'b10;

/* define internal wires and make assignments */
reg [1:0] d_ns;

/* create the state register */
always @(posedge de_clk or negedge de_rstn) 
    begin
        if(!de_rstn) d_cs <= 2'b0;
        else d_cs <= d_ns;
    end

reg igoblt;
reg igoline;
always @(posedge de_clk) goline <= igoline;
always @(posedge de_clk) goblt <= igoblt;

always @* begin
        d_cmdack=1'b0;
        d_cmdcpyclr=1'b0;
        load_actvn=1'b1;
        igoline=1'b0;
        igoblt=1'b0;
        case(d_cs)
            IDLE:   if(!cmdrdy || pcbusy) d_ns=IDLE;
                    else begin
                        load_actvn=1'b0;
                        d_cmdack=1'b1;
                        d_ns=DECODE;
                        if(line_actv_1) igoline=1'b1;
                        if(blt_actv_1)  igoblt=1'b1;
                    end

            DECODE: d_ns=BUSY;

            BUSY:   begin
                    if((noop_actv_2) || !d_busy)
                        begin
                        d_ns=IDLE;
                        d_cmdcpyclr=1'b1;
                        end
                    else d_ns=BUSY;
                    end
            default: begin
                        d_ns=IDLE;
                        d_cmdcpyclr=1'b0;
                        load_actvn=1'b1;
                        d_cmdack=1'b0;
                    end
        endcase
    end

endmodule

module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out
);

reg [7:0] acc_reg;
reg [2:0] count;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        acc_reg <= 8'b0;
        count <= 3'b0;
        valid_b <= 1'b0;
        data_out <= 10'b0;
    end else begin
        if (valid_a && ready_b) begin
            acc_reg <= acc_reg + data_in;
            count <= count + 1;
            if (count == 3'b111) begin
                count <= 3'b0;
                valid_b <= 1'b1;
                data_out <= {acc_reg[7], acc_reg} + ({acc_reg[7], acc_reg} >> 1) + ({acc_reg[7], acc_reg} >> 2);
            end
        end
    end
end

assign ready_a = ~valid_b;

endmodule

module functional_module(
    input [9:0]   accumulation,
    input [7:0]   data_in,
    output        final_output
);

reg [9:0] final_out_reg;

always @(*) begin
    final_out_reg = accumulation + data_in;
end

assign final_output = final_out_reg;

