module ripple_carry_adder (
	input [3:0] A,
	input [3:0] B,
	input C_in,
	input clk,
	output [3:0] S,
	output C_out
);

	reg [3:0] S_reg;
	reg C_out_reg;

	always @(posedge clk) begin
		// calculate the sum of A, B, and C_in
		S_reg <= A + B + C_in;

		// calculate the carry-out bit
		C_out_reg <= ((A[3] & B[3]) | (A[3] & C_in) | (B[3] & C_in));

		// assign outputs
		S <= S_reg;
		C_out <= C_out_reg;
	end

endmodule

module xor4 (
    X,
    A,
    B,
    C,
    D
);

    output X;
    input  A;
    input  B;
    input  C;
    input  D;

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire AB, CD, ABCD;

    sky130_fd_sc_hd__xor2_4 xor_AB (
        .X(AB),
        .A(A),
        .B(B)
    );

    sky130_fd_sc_hd__xor2_4 xor_CD (
        .X(CD),
        .A(C),
        .B(D)
    );

    sky130_fd_sc_hd__xor2_4 xor_ABCD (
        .X(ABCD),
        .A(AB),
        .B(CD)
    );

    assign X = ABCD;

endmodule

module ripple_carry_adder(
  input [3:0] A,
  input [3:0] B,
  input Cin,
  output [3:0] Sum,
  output Cout
);
  wire [3:0] C;
  assign C[0] = Cin;
  assign C[1] = (A[0] & B[0]) | (A[0] & C[0]) | (B[0] & C[0]);
  assign C[2] = (A[1] & B[1]) | (A[1] & C[1]) | (B[1] & C[1]);
  assign C[3] = (A[2] & B[2]) | (A[2] & C[2]) | (B[2] & C[2]);
  assign Cout = (A[3] & B[3]) | (A[3] & C[3]) | (B[3] & C[3]);
  assign Sum = A + B + Cin;
endmodule

module adc_readout
(
	input clk,
	input sync,
	input reset,

	input  [1:0]avs_ctrl_address,
	input  avs_ctrl_write,
	input  [15:0]avs_ctrl_writedata,
	input  avs_ctrl_read,
	output [15:0]avs_ctrl_readdata,

	input run,

	input trig1,
	input trig2,
	input tin,
	input tout,

	// ADC port
	input [11:0]adc_data,
	input adc_or,

	// FIFO port
	output write,
	output [15:0]writedata,

	output [5:0]TP
);

	// control registers
	reg single;
	reg cont;
	reg [1:0]ssel;
	reg psel;
	reg [5:0]sdel;
	reg [5:0]pdel;
	reg [15:0]len;
	wire [15:0]size;

	// state registers
	reg start;
	reg stop;
	reg running;

	// control register logic
	always @(posedge clk or posedge reset)
	begin
		if (reset)
		begin
			single <= 0;
			cont   <= 0;
			ssel   <= 0;
			psel   <= 0;
			sdel   <= 0;
			pdel   <= 0;
			len    <= 0;
		end
		else if (avs_ctrl_write)
		begin
			if (avs_ctrl_address == 0)
			begin
				cont <= avs_ctrl_writedata[0];
				if (!(start || running)) single <= avs_ctrl_writedata[1];
			end
			if (avs_ctrl_address == 1) { ssel, sdel } <=
				{ avs_ctrl_writedata[15:14], avs_ctrl_writedata[5:0] };
			if (avs_ctrl_address == 2) { psel, pdel } <=
				{ avs_ctrl_writedata[15:14], avs_ctrl_writedata[5:0] };
			if (avs_ctrl_address == 3) len <= avs_ctrl_writedata;
		end
		else if (start) single <= 0;
	end

	// control register read logic
	assign avs_ctrl_readdata = (avs_ctrl_address == 3) ?
		size : {13'h0000, running, single, cont};

	// start select
	reg s;
	always @(*)
	begin
		case (ssel)
			0: s <= 0;
			1: s <= trig1;
			2: s <= trig2;
			3: s <= tin;
		endcase
	end

	// start delay
	wire s_gated = s && run && (cont || single);
	adc_delay sdelay(clk, reset, sync, sdel, s_gated, start);

	// stop delay
	wire p_gated = tout && psel;
	adc_delay pdelay(clk, reset, sync, pdel, p_gated, stop);

	// burst generator
	reg start_reg;
	wire [12:0]adc_reg = { adc_or, adc_data };

	always @(posedge clk or posedge reset)
	begin
		if (reset)
		begin
			start_reg <= 0;
		end
		else if (sync)
		begin
			start_reg <= start;
		end
	end

	// timeout logic
	adc_timeout tocnt(clk, reset, sync, len, size, start, stop, running);

	// FIFO write logic
	assign write = running && sync;
	assign writedata = { start_reg, stop, 1'b0, adc_reg };

	// test point output
	assign TP = {s, s_gated, start, p_gated, run, running};

endmodule

// start delay module
module adc_delay(clk, reset, sync, delay, gated, start);

	input clk;
	input reset;
	input sync;
	input [5:0] delay;
	input gated;
	output reg start;

	reg [5:0] count;

	always @(posedge clk or posedge reset)
	begin
		if (reset)
		begin
			count <= 0;
			start <= 0;
		end
		else if (sync)
		begin
			if (gated)
			begin
				if (count < delay)
				begin
					count <= count + 1;
				end
				else
				begin
					count <= 0;
					start <= 1;
				end
			end
			else
			begin
				count <= 0;
				start <= 0;
			end
		end
	end

endmodule

// timeout module
module adc_timeout(clk, reset, sync, len, size, start, stop, running);

	input clk;
	input reset;
	input sync;
	input [15:0] len;
	output reg [15:0] size;
	input start;
	input stop;
	output reg running;

	reg [15:0] count;

	always @(posedge clk or posedge reset)
	begin
		if (reset)
		begin
			count <= 0;
			running <= 0;
			size <= 0;
		end
		else if (sync)
		begin
			if (start)
			begin
				count <= 0;
				running <= 1;
			end
			else if (running)
			begin
				count <= count + 1;
				if (count == len)
				begin
					running <= 0;
					size <= count;
				end
			end
			else if (stop)
			begin
				count <= 0;
			end
			else
			begin
				count <= 0;
				size <= 0;
			end
		end
	end

endmodule

module multiplier(
    input clk,
    input [12:0] A,
    input [12:0] B,
    output [26:0] Y,
    output [26:0] Z
);

reg [25:0] Y_reg;
reg [25:0] Z_reg;
reg [12:0] A_reg;
reg [12:0] B_reg;
reg [10:0] i;

always @(posedge clk) begin
    A_reg <= A;
    B_reg <= B;
    if(i == 0) begin
        Y_reg <= 0;
        Z_reg <= 0;
    end
    else begin
        if(B_reg[0] == 1) begin
            Y_reg <= Y_reg + (A_reg << (i-1));
            Z_reg <= Z_reg + ((~A_reg + 1) << (i-1));
        end
    end
    i <= i + 1;
end

assign Y = Y_reg;
assign Z = Z_reg;

endmodule

module memory_module (
  input [7:0] address,
  input [3:0] byteenable,
  input clock,
  input [31:0] data,
  input wren,
  output reg [31:0] q
);

  wire [31:0] ram_q;
  assign q = ram_q;

  reg [31:0] memory_array [0:255];

  always @(posedge clock) begin
    if (wren) begin
      case (byteenable)
        4'b0001: memory_array[address][7:0] = data[7:0];
        4'b0010: memory_array[address][15:8] = data[15:8];
        4'b0100: memory_array[address][23:16] = data[23:16];
        4'b1000: memory_array[address][31:24] = data[31:24];
        4'b0011: memory_array[address][15:0] = data[15:0];
        4'b0101: memory_array[address][23:0] = data[23:0];
        4'b0111: memory_array[address][31:0] = data[31:0];
        default: memory_array[address][31:0] = data[31:0];
      endcase
    end else begin
      case (byteenable)
        4'b0001: ram_q <= memory_array[address][7:0];
        4'b0010: ram_q <= memory_array[address][15:8];
        4'b0100: ram_q <= memory_array[address][23:16];
        4'b1000: ram_q <= memory_array[address][31:24];
        4'b0011: ram_q <= memory_array[address][15:0];
        4'b0101: ram_q <= memory_array[address][23:0];
        4'b0111: ram_q <= memory_array[address][31:0];
        default: ram_q <= memory_array[address][31:0];
      endcase
    end
  end

endmodule

module small_fifo
  #(parameter WIDTH = 8,
    parameter MAX_DEPTH_BITS = 3,
    parameter PROG_FULL_THRESHOLD = 2**MAX_DEPTH_BITS - 1)
  (
   input [WIDTH-1:0] din,     // Data in
   input          wr_en,   // Write enable
   input          rd_en,   // Read enable
   output [WIDTH-1:0] dout,    // Data out
   output         full,        // Full signal
   output         nearly_full, // Nearly full signal
   output         prog_full,   // Programmable full signal
   output         empty,       // Empty signal
   input          reset,       // Reset signal
   input          clk          // Clock signal
   );

  reg [MAX_DEPTH_BITS-1:0] count;
  reg [MAX_DEPTH_BITS-1:0] prog_full_threshold;

  parameter MAX_DEPTH = 2**MAX_DEPTH_BITS;
  parameter EMPTY_COUNT = 0;
  parameter FULL_COUNT = MAX_DEPTH-1;
  parameter PROG_FULL_COUNT = PROG_FULL_THRESHOLD;

  reg [WIDTH-1:0] mem [0:MAX_DEPTH-1];
  reg wr_ptr, rd_ptr, wr_en_nxt, rd_en_nxt, empty_nxt, full_nxt;

  assign nearly_full = (count >= PROG_FULL_THRESHOLD);

  always @(posedge clk) begin
    if (reset) begin
      wr_ptr <= 1'b0;
      rd_ptr <= 1'b0;
      wr_en_nxt <= 1'b0;
      rd_en_nxt <= 1'b0;
      empty_nxt <= 1'b1;
      full_nxt <= 1'b0;
      count <= EMPTY_COUNT;
    end
    else begin
      wr_ptr <= wr_ptr + wr_en_nxt;
      rd_ptr <= rd_ptr + rd_en_nxt;
      empty_nxt <= (count == EMPTY_COUNT);
      full_nxt <= (count == FULL_COUNT);
      count <= count + wr_en_nxt - rd_en_nxt;
    end
  end

  always @(posedge clk) begin
    if (reset) begin
      prog_full_threshold <= PROG_FULL_THRESHOLD;
    end
    else begin
      prog_full_threshold <= PROG_FULL_THRESHOLD;
    end
  end

  always @(posedge clk) begin
    if (reset) begin
      wr_en_nxt <= 1'b0;
      rd_en_nxt <= 1'b0;
    end
    else begin
      wr_en_nxt <= wr_en & ~full_nxt;
      rd_en_nxt <= rd_en & ~empty_nxt;
    end
  end

  assign full = full_nxt;
  assign prog_full = (count >= prog_full_threshold);
  assign empty = empty_nxt;

  always @(posedge clk) begin
    if (reset) begin
      dout <= 0;
    end
    else begin
      dout <= mem[rd_ptr];
    end
  end

  always @(posedge clk) begin
    if (reset) begin
      mem[wr_ptr] <= 0;
    end
    else begin
      mem[wr_ptr] <= din;
    end
  end

endmodule

module fifo
  #(parameter WIDTH = 8,
    parameter MAX_DEPTH_BITS = 3,
    parameter PROG_FULL_THRESHOLD = 2**MAX_DEPTH_BITS - 1)
  (
   input [WIDTH-1:0] din,     // Data in
   input          wr_en,   // Write enable
   input          rd_en,   // Read the next word
   output [WIDTH-1:0] dout,    // Data out
   output         full,        // Full signal
   output         nearly_full, // Nearly full signal
   output         prog_full,   // Programmable full signal
   output reg     empty,       // Empty signal
   input          reset,       // Reset signal
   input          clk          // Clock signal
   );

  reg  fifo_rd_en, empty_nxt;

  small_fifo
    #(.WIDTH (WIDTH),
      .MAX_DEPTH_BITS (MAX_DEPTH_BITS),
      .PROG_FULL_THRESHOLD (PROG_FULL_THRESHOLD))
    fifo
    (.din           (din),
     .wr_en         (wr_en),
     .rd_en         (fifo_rd_en),
     .dout          (dout),
     .full          (full),
     .nearly_full   (nearly_full),
     .prog_full     (prog_full),
     .empty         (fifo_empty),
     .reset         (reset),
     .clk           (clk)
     );

  always @(*) begin
    empty_nxt  = empty;
    fifo_rd_en = 0;
    case (empty)
      1'b1: begin
        if(!fifo_empty) begin
          fifo_rd_en = 1;
          empty_nxt  = 0;
        end
      end

      1'b0: begin
        if(rd_en) begin
          if(fifo_empty) begin
            empty_nxt = 1;
          end
          else begin
            fifo_rd_en = 1;
          end
        end
      end
    endcase // case(empty)
  end // always @ (*)

  always @(posedge clk) begin
    if(reset) begin
      empty <= 1'b1;
    end
    else begin
      empty <= empty_nxt;
    end
  end

  // synthesis translate_off
  always @(posedge clk)
  begin
    if (wr_en && full) begin
      $display("%t ERROR: Attempt to write to full FIFO: %m", $time);
    end
    if (rd_en && empty) begin
      $display("%t ERROR: Attempt to read an empty FIFO: %m", $time);
    end
  end // always @ (posedge clk)
  // synthesis translate_on

endmodule

module traffic_light_controller(
  input clk,
  input reset,
  input go,
  output reg red_led,
  output reg yellow_led,
  output reg green_led
);

// FSM states
localparam RED = 2'b00;
localparam RED_YELLOW = 2'b01;
localparam GREEN = 2'b10;
localparam YELLOW = 2'b11;

// FSM state register
reg [1:0] state;

// Counter for state duration
reg [2:0] counter;

// Default values
assign red_led = 1'b1;
assign yellow_led = 1'b0;
assign green_led = 1'b0;

// FSM logic
always @(posedge clk) begin
  if (reset) begin
    state <= RED;
    counter <= 3'b000;
  end else if (go) begin
    case (state)
      RED: begin
        if (counter == 3'b100) begin
          state <= RED_YELLOW;
          counter <= 3'b000;
        end else begin
          counter <= counter + 1;
        end
      end
      RED_YELLOW: begin
        if (counter == 3'b10) begin
          state <= GREEN;
          counter <= 3'b000;
        end else begin
          counter <= counter + 1;
        end
      end
      GREEN: begin
        if (counter == 3'b100) begin
          state <= YELLOW;
          counter <= 3'b000;
        end else begin
          counter <= counter + 1;
        end
      end
      YELLOW: begin
        if (counter == 3'b10) begin
          state <= RED;
          counter <= 3'b000;
        end else begin
          counter <= counter + 1;
        end
      end
      default: state <= RED;
    endcase
  end
end

// Output logic
always @(state) begin
  case (state)
    RED: begin
      red_led = 1'b1;
      yellow_led = 1'b0;
      green_led = 1'b0;
    end
    RED_YELLOW: begin
      red_led = 1'b1;
      yellow_led = 1'b1;
      green_led = 1'b0;
    end
    GREEN: begin
      red_led = 1'b0;
      yellow_led = 1'b0;
      green_led = 1'b1;
    end
    YELLOW: begin
      red_led = 1'b0;
      yellow_led = 1'b1;
