        if (~reset_n) begin
            readdata <= 0;
        end else if (chipselect && write_n == 0) begin
            case (address)
                0: bidir_port_internal <= writedata;
                1: data_dir_internal <= writedata;
            endcase
        end else begin
            case (address)
                0: bidir_port_internal <= data_out_internal;
                1: bidir_port_internal <= data_dir_internal;
            endcase
        end
