module carry_select_adder (
    input [15:0] A, B,
    input Cin,
    output [15:0] S,
    output Cout
);

wire [7:0] G, P;
wire [7:0] C1, C2, C3;

genvar i;
generate
    for (i = 0; i < 8; i = i + 1) begin : gen
        assign G[i] = A[i] & B[i];
        assign P[i] = A[i] ^ B[i];
        assign C1[i] = (i == 0) ? Cin : (G[i-1] | (P[i-1] & C1[i-1]));
        assign C2[i] = G[i] | (P[i] & C1[i]);
        assign C3[i] = (P[i] & G[i-1]) | (P[i] & P[i-1] & C1[i-1]);
    end
endgenerate

assign S = A + B + Cin;
assign Cout = (C3[7] == 1) ? C2[7] : C1[7];

endmodule

module NIOS_SYSTEMV3_JTAG_UART_sim_scfifo_w (
  // inputs:
  clk,
  fifo_wdata,
  fifo_wr,

  // outputs:
  fifo_FF,
  r_dat,
  wfifo_empty,
  wfifo_used
);

  output fifo_FF;
  output [7:0] r_dat;
  output wfifo_empty;
  output [5:0] wfifo_used;
  input clk;
  input [7:0] fifo_wdata;
  input fifo_wr;

  reg [7:0] fifo [63:0];
  reg [5:0] wfifo_used_reg;
  wire fifo_FF;
  wire wfifo_empty;

  // Write to FIFO
  always @(posedge clk) begin
    if (fifo_wr && !fifo_FF) begin
      fifo[wfifo_used_reg] <= fifo_wdata;
      wfifo_used_reg <= wfifo_used_reg + 1;
    end
  end

  // Read from FIFO
  always @(*) begin
    if (wfifo_used_reg == 0) begin
      r_dat = 8'b0;
      wfifo_empty = 1'b1;
    end else begin
      r_dat = fifo[0];
      wfifo_empty = 1'b0;
    end

    if (wfifo_used_reg == 64) begin
      fifo_FF = 1'b1;
    end else begin
      fifo_FF = 1'b0;
    end
  end

  // Update wfifo_used
  always @(*) begin
    wfifo_used = wfifo_used_reg;
  end

endmodule

module cluster_header (
   // Outputs
   dbginit_l, cluster_grst_l, rclk, so, 
   // Inputs
   gclk, cluster_cken, arst_l, grst_l, adbginit_l, gdbginit_l, si, se
);

  // internal signals
  wire [1:0] state;
  wire [1:0] next_state;
  reg [1:0] state_reg;
  reg [1:0] next_state_reg;
  wire [1:0] state_next;
  wire [1:0] state_reg_next;

  // state machine
  always @(posedge gclk) begin
    state_reg <= next_state_reg;
    state <= state_next;
  end

  always @(*) begin
    next_state = state;
    state_next = state_reg;

    case (state)
      2'b00: begin // idle
        if (!grst_l && !arst_l) begin
          next_state = 2'b01; // reset
        end else if (cluster_cken) begin
          next_state = 2'b10; // active
        end
      end

      2'b01: begin // reset
        if (grst_l && arst_l) begin
          next_state = 2'b00; // idle
        end
      end

      2'b10: begin // active
        if (!cluster_cken) begin
          next_state = 2'b00; // idle
        end
      end
    endcase
  end

  // output logic
  assign cluster_grst_l = state == 2'b01 ? 1'b0 : 1'b1;
  assign dbginit_l = state == 2'b10 ? gdbginit_l : 1'b0;
  assign rclk = gclk;
  assign so = state == 2'b10 ? si : 1'b0;

  // internal signals
  wire [1:0] state_reg_next;
  wire [1:0] state_next;

endmodule

module flip_flop (
    Q      ,
    Q_N    ,
    D      ,
    SCD    ,
    SCE    ,
    CLK    ,
    SET_B  ,
    RESET_B,
    VPWR   ,
    VGND   ,
    VPB    ,
    VNB
);

    output Q      ;
    output Q_N    ;
    input  D      ;
    input  SCD    ;
    input  SCE    ;
    input  CLK    ;
    input  SET_B  ;
    input  RESET_B;
    input  VPWR   ;
    input  VGND   ;
    input  VPB    ;
    input  VNB    ;

    reg Q;
    wire Q_N;

    assign Q_N = ~Q;

    always @ (posedge CLK) begin
        if (SCE) begin
            Q <= D;
        end
    end

    always @ (posedge CLK) begin
        if (SCD) begin
            Q <= 0;
        end
    end

    always @ (SET_B or RESET_B) begin
        if (~SET_B) begin
            Q <= 1;
        end else if (~RESET_B) begin
            Q <= 0;
        end
    end

endmodule

