  // Synchronize input signal
  always @(posedge clk) begin
    if (rst) begin
      Q_sync <= 4'b0;
    end else begin
      Q_sync <= Q;
    end
  end

  // Output synchronized signal
  always @(posedge clk) begin
    if (rst_sync) begin
      D <= 4'b0;
    end else begin
      D <= Q_sync;
    end
  end

endmodule

module interrupt_controller (
  input [n-1:0] irq,
  input [n-1:0] pri,
  output reg [n-1:0] int
);

parameter n = 4; // number of interrupt request signals (and associated priority signals)

integer i, highest_priority_irq;
reg [n-1:0] highest_priority;

always @(*) begin
  highest_priority_irq = 0;
  highest_priority = pri[0];

  for (i = 1; i < n; i = i + 1) begin
    if (irq[i] && ((pri[i] > highest_priority) || (pri[i] == highest_priority && i < highest_priority_irq))) begin
      highest_priority_irq = i;
      highest_priority = pri[i];
    end
  end

  int = 0;
  if (irq[highest_priority_irq]) begin
    int[highest_priority_irq] = 1;
  end
end

endmodule

