module my_d_latch (
    input D,
    input GATE,
    output reg Q
);

    // Local signals
    wire buf_Q       ;
    wire GATE_delayed;
    wire D_delayed   ;
    reg  notifier    ;
    wire awake       ;

    // Instantiate the sky130_fd_sc_hd__udp_dlatch$P_pp$PG$N module
    sky130_fd_sc_hd__udp_dlatch$P_pp$PG$N dlatch0 (
        .Q(buf_Q),
        .D(D_delayed),
        .GATE(GATE_delayed),
        .notifier(notifier),
        .VPWR(VPWR),
        .VGND(VGND)
    );

    // Instantiate the buf module
    buf buf0 (
        .in(buf_Q),
        .out(Q)
    );

    // Delay the GATE and D inputs by one clock cycle
    always @(posedge VPWR) begin
        GATE_delayed <= GATE;
        D_delayed <= D;
    end

    // Set the notifier to 1 when GATE is high
    always @(posedge VPWR) begin
        if (GATE == 1'b1) begin
            notifier <= 1'b1;
        end
    end

    // Set the notifier to 0 when GATE is low
    always @(posedge VPWR) begin
        if (GATE == 1'b0) begin
            notifier <= 1'b0;
        end
    end

    // Ensure that the circuit is only active when awake is high
    assign awake = ( VPWR === 1'b1 );
    assign GATE_delayed = (awake == 1'b1) ? GATE_delayed : 1'b0;
    assign D_delayed = (awake == 1'b1) ? D_delayed : 1'b0;

    // Set the initial value of Q to 0
    initial begin
        Q <= 1'b0;
    end

endmodule

