module sky130_fd_sc_lp__a2bb2o (
    output reg [1:0] X,
    input [1:0] A1_N,
    input [1:0] A2_N,
    input [1:0] B1,
    input [1:0] B2
);

    wire [2:0] sum;
    wire carry;

    // Generate sum and carry using full adder
    full_adder fa1(.sum(sum[0]), .carry(carry), .a(A1_N[0]), .b(B1[0]), .cin(1'b0));
    full_adder fa2(.sum(sum[1]), .carry(carry), .a(A1_N[1]), .b(B1[1]), .cin(carry));
    full_adder fa3(.sum(sum[2]), .carry(X[1]), .a(A2_N[1]), .b(B2[1]), .cin(carry));

    // Generate two's complement of B2
    wire [1:0] B2_N;
    assign B2_N[0] = ~B2[0] + 1'b1;
    assign B2_N[1] = ~B2[1] + (B2[0] == 1'b0);

    // Generate two's complement of sum
    wire [2:0] sum_N;
    assign sum_N[0] = ~sum[0] + 1'b1;
    assign sum_N[1] = ~sum[1] + (sum[0] == 1'b0);
    assign sum_N[2] = ~sum[2] + (sum[1] == 1'b0 && sum[0] == 1'b0);

    // Select between sum and two's complement of B2 based on A2_N
    mux2 #(2) mux1(.out(X), .in0(sum), .in1(B2_N), .sel(A2_N[1]));

    // Select between X and two's complement of sum based on A2_N
    mux2 #(2) mux2(.out(X), .in0(X), .in1(sum_N), .sel(A2_N[1]));

endmodule


