module watchdog_timer (
  input clk,
  input rst,
  output en,
  output to
);

  parameter t = 100; // timeout period in clock cycles

  reg [7:0] counter;
  reg timeout;

  always @(posedge clk) begin
    if (rst) begin
      counter <= 0;
      timeout <= 0;
      en <= 1;
    end
    else begin
      counter <= counter + 1;
      if (counter == t) begin
        timeout <= 1;
        en <= 0;
      end
    end
  end

  always @(posedge clk) begin
    if (rst) begin
      timeout <= 0;
    end
    else begin
      if (counter == t) begin
        timeout <= 1;
      end
      else begin
        timeout <= 0;
      end
    end
  end

  assign to = timeout;

endmodule

