module full_adder (A, B, Ci, Co, S);
  input A, B, Ci;
  output S, Co;
  wire n1, n2, n3;

  XOR2_X1 U1 (.A(A), .B(B), .ZN(n1));
  XOR2_X1 U2 (.A(n1), .B(Ci), .ZN(S));
