reg [aw-1:0]    addr_reg;		

//
// boot flash
//
initial begin
	$readmemh("boot_binary.dat", mem);
end

//
// read access
//

// memory read address register for synchronous access
always @(posedge clk) begin
    if (ce)
        addr_reg <=  addr;
end

// Data output 
assign doq = oe ? mem[addr_reg] : 'bz;

