module traffic_light_controller(
  input clk,
  input reset,
  output reg red,
  output reg yellow,
  output reg green
);

parameter GREEN_TIME = 20;
parameter YELLOW_TIME = 3;
parameter RED_TIME = 15;

reg [5:0] counter;

always @(posedge clk) begin
  if (reset) begin
    counter <= 0;
    red <= 0;
    yellow <= 0;
    green <= 1;
  end else begin
    counter <= counter + 1;
    case (counter)
      GREEN_TIME - 1: begin
        green <= 0;
        yellow <= 1;
      end
      GREEN_TIME + YELLOW_TIME - 1: begin
        yellow <= 0;
        red <= 1;
      end
      GREEN_TIME + YELLOW_TIME + RED_TIME - 1: begin
        red <= 0;
        green <= 1;
        counter <= 0;
      end
    endcase
  end
end

assign red = (counter >= GREEN_TIME + YELLOW_TIME);
assign yellow = (counter >= GREEN_TIME && counter < GREEN_TIME + YELLOW_TIME);
assign green = (counter < GREEN_TIME);

endmodule

module and2b (
    X   ,
    A_N ,
    B   ,
    VPWR,
    VGND,
    VPB ,
    VNB
);

    output X   ;
    input  A_N ;
    input  B   ;
    input  VPWR;
    input  VGND;
    input  VPB ;
    input  VNB ;

    // Input buffers
    bufif1 buf_A_N (A, A_N, VPB, VNB, VPWR, VGND);
    bufif1 buf_B   (B, VGND, VPB, VNB, VPWR, VGND);

    // Power clamp
    assign A = (A_N == 1'b1) ? VGND : A;
    assign B = (B == 1'b1) ? VPWR : B;

    // AND gate
    sky130_fd_sc_ls__and2b and_gate (
        .A(A),
        .B(B),
        .Y(X)
    );

    // Supply clamp
    assign X = (X > VPWR) ? VPWR : X;

endmodule

module RAM(
    input clk,
    input ram_full_fb_i_reg,
    input tmp_ram_rd_en,
    input [11:0] Q,
    input [8:0] din,
    output [8:0] dout
);

    wire [8:0] ram[0:2047];
    reg [8:0] dout_reg;

    // Write operation
    always @(posedge clk) begin
        if (!ram_full_fb_i_reg && tmp_ram_rd_en) begin
            ram[Q[11:2]][Q[1:0]] <= din;
        end
    end

    // Read operation
