module priority_encoder (
    input [3:0] in, // 4-bit input
    output [1:0] out // 2-bit output
    );

    // Binary-to-Gray code converter
    wire [3:0] gray_in = in ^ (in >> 1);

    // Priority encoder logic
    assign out = (gray_in[3]) ? 2'b11 :
                 (gray_in[2]) ? 2'b10 :
                 (gray_in[1]) ? 2'b01 :
                 (gray_in[0]) ? 2'b00 : 2'b00;

endmodule

module ripple_carry_adder (
    input [31:0] a, // 32-bit input
    input [31:0] b, // 32-bit input
    input [1:0] sel, // 2-bit select input from priority encoder
    output [31:0] sum // 32-bit output
    );

    // Ripple carry adder logic
    wire [31:0] carry;
    assign sum = (sel == 2'b00) ? a + b :
                 (sel == 2'b01) ? a :
                 (sel == 2'b10) ? b : 32'h0;
    assign carry[0] = a[0] & b[0];
    genvar i;
    generate
        for (i = 1; i < 32; i = i + 1) begin : adder_loop
            assign carry[i] = (a[i] & b[i]) | (a[i] & carry[i-1]) | (b[i] & carry[i-1]);
            assign sum[i] = a[i] ^ b[i] ^ carry[i-1];
        end
    endgenerate

endmodule

module top_module (
    input [3:0] in, // 4-bit input for priority encoder
    input [31:0] a, // 32-bit input for adder
    input [31:0] b, // 32-bit input for adder
    output [31:0] sum // 32-bit output from adder
    ); 

    wire [1:0] sel;
    priority_encoder pe(.in(in), .out(sel));
    ripple_carry_adder rca(.a(a), .b(b), .sel(sel), .sum(sum));

endmodule

module synchronizer(
