module dff_async_reset_set (
    input D,
    input RESET_B,
    input SET_B,
    input CLK,
    output Q
);

    reg Q_int;

    always @(posedge CLK or negedge RESET_B or negedge SET_B)
    begin
        if (!RESET_B) // Asynchronous reset
            Q_int <= 1'b0;
        else if (!SET_B) // Asynchronous set
            Q_int <= 1'b1;
        else // Synchronous logic
            Q_int <= D;
    end

    assign Q = Q_int;

endmodule

module adder4 (
    input [3:0] A,
    input [3:0] B,
    input C_in,
    output [3:0] S,
    output C_out
);

    wire [3:0] X, Y, Z;
    wire [2:0] C;

    // Full adder
    assign X = A ^ B;
    assign Y = A & B;
    assign Z = C_in & X;
    assign S = X ^ C_in;
    assign C[0] = Y | Z;

    // Half adder
    assign X = S[1] ^ B[1];
    assign Y = S[1] & B[1];
    assign Z = C[0] & X;
    assign S[1] = X ^ C[0];
    assign C[1] = Y | Z;

    assign X = S[2] ^ B[2];
    assign Y = S[2] & B[2];
    assign Z = C[1] & X;
    assign S[2] = X ^ C[1];
    assign C[2] = Y | Z;

    assign X = S[3] ^ B[3];
    assign Y = S[3] & B[3];
    assign Z = C[2] & X;
    assign S[3] = X ^ C[2];
    assign C_out = Y | Z;

endmodule

module I2C_Slave(
    input SBCLKI,
    input SBRWI,
    input SBSTBI,
    input [7:0] SBADRI,
    input [7:0] SBDATI,
    output reg [7:0] SBDATO,
    output reg SBACKO,
    output reg I2CIRQ,
    output I2CWKUP,
    output SCLO,
    output SCLOE,
    output SDAO,
    output SDAOE
);

parameter I2C_SLAVE_INIT_ADDR = 9'b1111100001;
parameter BUS_ADDR74 = 4'b0001;

reg [7:0] i2c_address;
reg [7:0] i2c_data;
reg i2c_busy;
reg i2c_ack;
reg i2c_irq;
reg i2c_wakeup;
reg scl;
reg sda;

assign SBDATO = i2c_data;
assign SBACKO = i2c_ack;
assign I2CIRQ = i2c_irq;
assign I2CWKUP = i2c_wakeup;
assign SCLO = scl;
assign SDAO = sda;
assign SCLOE = 1;
assign SDAOE = 1;

always @(posedge SBCLKI) begin
    if(SBSTBI && !i2c_busy) begin
        i2c_address <= SBADRI;
        i2c_busy <= 1;
    end else if(SBRWI && i2c_busy) begin
        i2c_data <= SBDATI;
        i2c_ack <= 1;
        i2c_irq <= 1;
        i2c_wakeup <= 1;
        i2c_busy <= 0;
    end else if(!SBRWI && i2c_busy) begin
        i2c_ack <= 1;
        i2c_irq <= 1;
        i2c_wakeup <= 1;
        i2c_busy <= 0;
    end else if(!SBSTBI && !SBRWI && !i2c_busy) begin
        i2c_data <= 0;
        i2c_ack <= 0;
        i2c_irq <= 0;
        i2c_wakeup <= 0;
    end
end

always @(posedge SBCLKI) begin
    if(SBSTBI && SBADRI == I2C_SLAVE_INIT_ADDR) begin
        scl <= 0;
        sda <= 0;
    end else if(SBSTBI && SBADRI == i2c_address && SBRWI) begin
        scl <= 0;
        sda <= 0;
    end else if(SBSTBI && SBADRI == i2c_address && !SBRWI) begin
        scl <= 0;
        sda <= 1;
    end else if(!SBSTBI && SBADRI == i2c_address && !SBRWI) begin
        scl <= 1;
        sda <= 1;
    end else if(!SBSTBI && SBADRI == i2c_address && SBRWI) begin
        scl <= 1;
        sda <= 0;
    end else begin
        scl <= 1;
        sda <= 1;
    end
end

endmodule

module xor_8bit_binary (
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] a,    // 8-bit input a
    input [7:0] b,    // 8-bit input b
    input enable,     // Enable input for the XOR operation
    output reg [7:0] x // 8-bit output for the XOR operation
);

    // Internal wires and registers
    wire [7:0] p, g;
    reg [7:0] c;

    // Carry-lookahead adder architecture
    assign p = a ^ b;
    assign g = a & b;
    always @ (posedge clk) begin
        if (reset) begin
            c <= 8'b00000000;
            x <= 8'b00000000;
        end else begin
            if (enable) begin
                c <= g | (p & c);
                x <= p ^ c;
            end else begin
                x <= 8'b00000000;
            end
        end
    end

endmodule

module Mult16x16
(
 input wire clk,
 input wire [15:0] A,
 input wire [15:0] B,
 output wire [31:0] Result
);

wire [17:0] wResInt1,wResInt2,wResInt3,wResInt4,wResInt5,wResInt6,wResInt7,wResInt8;

// 8 LUT modules for computing partial products
LUT # ( 16 ) LUT1
(
	.A(A),
	.B(B[1:0]),
	.Result(wResInt1)
);

LUT # ( 16 ) LUT2
(
	.A(A),
	.B(B[3:2]),
	.Result(wResInt2)
);

LUT # ( 16 ) LUT3
(
	.A(A),
	.B(B[5:4]),
	.Result(wResInt3)
);

LUT # ( 16 ) LUT4
(
	.A(A),
	.B(B[7:6]),
	.Result(wResInt4)
);

LUT # ( 16 ) LUT5
(
	.A(A),
	.B(B[9:8]),
	.Result(wResInt5)
);

LUT # ( 16 ) LUT6
(
	.A(A),
	.B(B[11:10]),
	.Result(wResInt6)
);

LUT # ( 16 ) LUT7
(
	.A(A),
	.B(B[13:12]),
	.Result(wResInt7)
);

LUT # ( 16 ) LUT8
(
	.A(A),
	.B(B[15:14]),
	.Result(wResInt8)
);

// 8 adders for summing partial products
wire [31:0] wSum1, wSum2, wSum3, wSum4, wSum5, wSum6, wSum7, wSum8;

FullAdder FA1(
	.A(wResInt1),
	.B({wResInt2,1'b0}),
	.Cin(1'b0),
	.Sum(wSum1),
	.Cout()
);

FullAdder FA2(
	.A(wResInt3),
	.B({wResInt4,1'b0}),
	.Cin(1'b0),
	.Sum(wSum2),
	.Cout()
);

FullAdder FA3(
	.A(wResInt5),
	.B({wResInt6,1'b0}),
	.Cin(1'b0),
	.Sum(wSum3),
	.Cout()
);

FullAdder FA4(
	.A(wResInt7),
	.B({wResInt8,1'b0}),
	.Cin(1'b0),
	.Sum(wSum4),
	.Cout()
);

FullAdder FA5(
	.A(wSum1),
	.B({wSum2,2'b0}),
	.Cin(1'b0),
	.Sum(wSum5),
	.Cout()
);

FullAdder FA6(
	.A(wSum3),
	.B({wSum4,2'b0}),
	.Cin(1'b0),
	.Sum(wSum6),
	.Cout()
);

FullAdder FA7(
	.A(wSum5),
	.B({wSum6,4'b0}),
	.Cin(1'b0),
	.Sum(wSum7),
	.Cout()
);

FullAdder FA8(
	.A(wSum7),
	.B(16'b0),
	.Cin(1'b0),
	.Sum(Result),
	.Cout()
);

// clock divider for generating a slower clock signal
reg [24:0] clk_div;
always @(posedge clk) begin
    if (clk_div == 499999) begin
        clk_div <= 0;
    end else begin
        clk_div <= clk_div + 1;
    end
end

endmodule

module sky130_fd_sc_ms__o311a(
    input A1, A2, A3, B1, C1, VPWR, VGND, VPB, VNB,
    output X
);

    reg [3:0] state;
    parameter START = 4'b0000;
    parameter A1_0 = 4'b0001;
    parameter A2_0 = 4'b0010;
    parameter A3_0 = 4'b0011;
    parameter B1_0 = 4'b0100;
    parameter C1_0 = 4'b0101;
    parameter VGND_0 = 4'b0110;
    parameter VNB_0 = 4'b0111;
    parameter VPB_0 = 4'b1000;
    parameter VPWR_0 = 4'b1001;
    parameter A1_1 = 4'b1010;
    parameter A2_1 = 4'b1011;
    parameter A3_1 = 4'b1100;
    parameter B1_1 = 4'b1101;
    parameter C1_1 = 4'b1110;
    parameter VGND_1 = 4'b1111;

    always @(*) begin
        case (state)
            START: begin
                if (A1 == 1'b0) state <= A1_0;
            end
            A1_0: begin
                if (A2 == 1'b0) state <= A2_0;
            end
            A2_0: begin
                if (A3 == 1'b0) state <= A3_0;
            end
            A3_0: begin
                if (B1 == 1'b0) state <= B1_0;
            end
            B1_0: begin
                if (C1 == 1'b0) state <= C1_0;
            end
            C1_0: begin
                if (VGND == 1'b0) state <= VGND_0;
            end
            VGND_0: begin
                if (VNB == 1'b0) state <= VNB_0;
            end
            VNB_0: begin
                if (VPB == 1'b0) state <= VPB_0;
            end
            VPB_0: begin
                if (VPWR == 1'b0) state <= VPWR_0;
            end
            VPWR_0: begin
                if (A1 == 1'b1) state <= A1_1;
            end
            A1_1: begin
                if (A2 == 1'b1) state <= A2_1;
            end
            A2_1: begin
                if (A3 == 1'b1) state <= A3_1;
            end
            A3_1: begin
                if (B1 == 1'b1) state <= B1_1;
            end
            B1_1: begin
                if (C1 == 1'b1) state <= C1_1;
            end
            C1_1: begin
                if (VGND == 1'b1) state <= VGND_1;
            end
            VGND_1: begin
                if (X == 1'b1) state <= START;
                else if (VNB == 1'b1) state <= VNB_0;
            end
        endcase
    end

    assign X = (state == VPWR_0);

endmodule

