module quadcopter_voting_system (
    input clk,
    input reset,
    input [7:0] in,
    input [1:0] select,
    output reg [3:0] out
);

    // Priority Encoder
    wire [7:0] in_priority;
    assign in_priority = ~in;
    wire [2:0] priority;
    priority_encoder pe(
        .in(in_priority),
        .out(priority)
    );

    // Decoder
    wire [3:0] decoder_out;
    decoder_2to4 dec(
        .in(select),
        .out(decoder_out)
    );

    // Motor Selection
    always @(posedge clk) begin
        if (reset) begin
            out <= 4'b0000;
        end else begin
            case (priority)
                3'b000: out <= 4'b0001;
                3'b001: out <= 4'b0010;
                3'b010: out <= 4'b0100;
                3'b011: out <= 4'b1000;
                default: out <= 4'b0000;
            endcase
        end
    end

    // Functional Module
    function [3:0] motor_select;
        input [2:0] priority;
        input [1:0] select;
        begin
            case (priority)
                3'b000: motor_select = 4'b0001;
                3'b001: motor_select = 4'b0010;
                3'b010: motor_select = 4'b0100;
                3'b011: motor_select = 4'b1000;
                default: motor_select = 4'b0000;
            endcase
            if (select == 2'b00) begin
                motor_select = motor_select & 4'b1110;
            end else if (select == 2'b01) begin
                motor_select = motor_select & 4'b1101;
            end else if (select == 2'b10) begin
                motor_select = motor_select & 4'b1011;
            end else if (select == 2'b11) begin
                motor_select = motor_select & 4'b0111;
            end
        end
    endfunction

    // Output
    assign out = motor_select(priority, select);

endmodule

module priority_encoder (
    input [7:0] in,
