module circ_buffer #
  (
   parameter TCQ = 100,
   parameter BUF_DEPTH  = 5,   // valid values are 5, 6, 7, and 8
   parameter DATA_WIDTH = 1
   )
  (
   output[DATA_WIDTH-1:0] rdata,
   input [DATA_WIDTH-1:0] wdata,
   input                  rclk,
   input                  wclk,
   input                  rst
   );

  //***************************************************************************
  // Local parameters
  //***************************************************************************

  localparam SHFTR_MSB = (BUF_DEPTH-1)/2;

  //***************************************************************************
  // Internal signals
  //***************************************************************************

  reg               SyncResetRd;
  reg [SHFTR_MSB:0] RdCEshftr;
  reg [2:0]         RdAdrsCntr;

  reg               SyncResetWt;
  reg               WtAdrsCntr_ce;
  reg [2:0]         WtAdrsCntr;

  //***************************************************************************
  // read domain registers
  //***************************************************************************

  always @(posedge rclk or posedge rst)
    if (rst) SyncResetRd <= #TCQ 1'b1;
    else     SyncResetRd <= #TCQ 1'b0;

  always @(posedge rclk or posedge SyncResetRd)
  begin
    if (SyncResetRd)
    begin
      RdCEshftr  <= #TCQ 'b0;
      RdAdrsCntr <= #TCQ 'b0;
    end
    else
    begin
      RdCEshftr  <= #TCQ {RdCEshftr[SHFTR_MSB-1:0], WtAdrsCntr_ce};

      if(RdCEshftr[SHFTR_MSB])
      begin
        if(RdAdrsCntr == (BUF_DEPTH-1)) RdAdrsCntr <= #TCQ 'b0;
        else                            RdAdrsCntr <= #TCQ RdAdrsCntr + 1;
      end
    end
  end

  //***************************************************************************
  // write domain registers
  //***************************************************************************

  always @(posedge wclk or posedge SyncResetRd)
    if (SyncResetRd) SyncResetWt <= #TCQ 1'b1;
    else             SyncResetWt <= #TCQ 1'b0;

  always @(posedge wclk or posedge SyncResetWt)
  begin
    if (SyncResetWt)
    begin
      WtAdrsCntr_ce <= #TCQ 1'b0;
      WtAdrsCntr    <= #TCQ  'b0;
    end
    else
    begin
      WtAdrsCntr_ce <= #TCQ 1'b1;

      if(WtAdrsCntr_ce)
      begin
        if(WtAdrsCntr == (BUF_DEPTH-1)) WtAdrsCntr <= #TCQ 'b0;
        else                            WtAdrsCntr <= #TCQ WtAdrsCntr + 1;
      end
    end
  end

  //***************************************************************************
  // instantiate one RAM64X1D for each data bit
  //***************************************************************************

  genvar i;
  generate
    for(i = 0; i < DATA_WIDTH; i = i+1) begin: gen_ram
      RAM64X1D #
      (
        .INIT (64'h0000000000000000)
      )
      u_RAM64X1D
      (.DPO         (rdata[i]),
       .SPO         (),
       .A0          (WtAdrsCntr[0]),
       .A1          (WtAdrsCntr[1]),
       .A2          (WtAdrsCntr[2]),
       .A3          (1'b0),
       .A4          (1'b0),
       .A5          (1'b0),
       .D           (wdata[i]),
       .DPRA0       (RdAdrsCntr[0]),
       .DPRA1       (RdAdrsCntr[1]),
       .DPRA2       (RdAdrsCntr[2]),
       .DPRA3       (1'b0),
       .DPRA4       (1'b0),
       .DPRA5       (1'b0),
       .WCLK        (wclk),
       .WE          (1'b1)
      );
    end
  endgenerate

endmodule

module sr_dff(
    output reg Q,
    input D,
    input C,
    input E,
    input R,
    input S
);
    parameter [0:0] INIT = 1'b0;
    initial Q = INIT;

        always @(negedge C or negedge S or negedge R)
          if (!R)
            Q <= 1'b0;
          else if (!S)
            Q <= 1'b1;
          else if (E)
            Q <= D;

endmodule

module binary_divider(divident, divisor, quotient);

input wire [31:0] divident;
input wire [31:0] divisor;
output reg [31:0] quotient;

reg [47:0] tmpDivident;
reg [23:0] tmpDivisor;
reg [25:0] tmpQuotient;
reg [25:0] remainder;
reg [8:0] exponent;
reg [8:0] tmp;

integer i;

always @(divident or divisor)
begin
    quotient = 0;
    remainder = 0;
    tmpDivident = {1, divident[22:0], 24'b0};
    tmpDivisor = {1, divisor[22:0]};
    exponent = divident[30:23] + 128 - divisor[30:23];
    tmpQuotient = 0;

    tmp = divident[30:23] + 127;
    if (tmp < divisor[30:23])
    begin
        quotient = 0;
    end
    else if (tmp - divisor[30:23] > 254)
    begin
        quotient = {divident[31]^divisor[31], 8'b1, 23'b0};
    end
    else if (divident == 0 || divisor[30:23] - 255 == 0)
    begin
        quotient = 0;
    end
    else if (divident[30:23] == 255)
    begin
        quotient = divident;
    end
    else if (divisor == 0)
    begin
        quotient = {divident[31], 8'b1, 23'b0};
    end
    else
    begin
        for (i = 48; i > 0; i = i - 1)
        begin
            remainder = {remainder[25:0], tmpDivident[i-1]};
            tmpQuotient = tmpQuotient << 1;
            if (remainder >= tmpDivisor)
            begin
                tmpQuotient = tmpQuotient + 1;
                remainder = remainder - tmpDivisor;
            end
        end

        for (i = 3; i > 0; i = i - 1)
        begin
            if (tmpQuotient[25] != 1)
            begin
                tmpQuotient = tmpQuotient << 1;
                exponent = exponent - 1;
            end
        end

        quotient = {divident[31]^divisor[31], exponent[7:0], tmpQuotient[24:2]};
    end
end

endmodule

module top_module (
    input clk,
    input up_down,
    input load,
    input en,
    input [3:0] data_in,
    output [3:0] final_output
);

