module up_down_counter_4bit (
    input clk,
    input up_down,
    input load,
    input en,
    input [3:0] data_in,
    output reg [3:0] out
);
always @(posedge clk) begin
    if (en) begin
        if (load) begin
            out <= data_in;
        end else begin
            if (up_down) begin
                out <= out + 1;
            end else begin
                out <= out - 1;
            end
        end
    end
end
endmodule

module binary_to_gray_4bit (
    input [3:0] B,
    output reg [3:0] G
);
always @(*) begin
    G[3] = B[3];
    G[2] = B[3] ^ B[2];
    G[1] = B[2] ^ B[1];
    G[0] = B[1] ^ B[0];
end
