wire transition_detected;

input_vector_transition_detector ivtd (
    .clk(clk),
    .reset(reset),
    .in(in),
    .transition_detected(transition_detected)
);

barrel_shifter bs (
    .clk(clk),
    .reset(reset),
    .load(load),
    .ena(ena),
    .data(data),
    .q(barrel_shifter_q)
);

always @(posedge clk, posedge reset) begin
    if (reset) begin
        q <= 0;
    end else begin
        if (select) begin
            q <= barrel_shifter_q;
        end else begin
            if (transition_detected) begin
                q <= 0;
            end
        end
    end
end

endmodule

