module signed_mag_adder_decoder (
    input [15:0] A,
    input [15:0] B,
    output reg [15:0] sum,
    input [3:0] in,
    output [15:0] out
);

    wire [15:0] add_result;
    wire [15:0] complement_out;

    // 16-bit signed magnitude adder
    assign add_result = A + B;
    assign sum = (add_result[15] == 1) ? -add_result : add_result;

    // 4-to-16 decoder with active-low outputs
    assign out = ~{in[3], in[2], in[1], in[0]};

    // Complement of decoder output
    assign complement_out = ~out;

endmodule

module priority_encoder( 
    input [254:0] in,
    output [7:0] out );

    reg [7:0] index;
    integer i;

    always @(*) begin
        index = 8'b00000000;
        for(i = 254; i >= 0; i = i - 1) begin
            if(in[i] == 1'b1) begin
                index = i;
            end
        end
    end

    assign out = index;

endmodule

module top_module (
    input clk,
    input signed [31:0] a,
    input signed [31:0] b,
    input [7:0] input1,
    input [7:0] input2,
    input control,
    output [1:0] result,
    output signed [31:0] sum
);

    wire signed [15:0] mul8_out;
    wire and_gate_out;
    wire or_gate_out;

    mul8 mul8_inst (
        .a(input1),
        .b(input2),
        .product(mul8_out)
    );

    and_gate and_gate_inst (
        .a(input1[0] & input2[0]),
        .b(input1[1] & input2[1]),
        .out(and_gate_out)
    );

    always @ (posedge clk) begin
        case (control)
            0: result <= {and_gate_out, 1'b0};
            1: result <= {or_gate_out, 1'b0};
        endcase
        or_gate_out <= input1 | input2;
        sum <= a + b + {16'd0, mul8_out};
    end

endmodule

