module scratchpad_memory_block (
  input clk,
  input rst,
  input wr_en,
  input rd_en,
  input [log2(depth)-1:0] addr,
  input [width-1:0] data_in,
  output [width-1:0] data_out
);

parameter depth = 1024; // depth of the scratchpad memory block
parameter width = 32; // width of each memory location in bits

// dual-port RAM with separate read and write ports
reg [width-1:0] memory [0:depth-1];

// write data to memory block at specified address
always @(posedge clk) begin
  if (wr_en) begin
    memory[addr] <= data_in;
  end
end

// read data from memory block at specified address
assign data_out = rd_en ? memory[addr] : 0;

// reset memory block to zero
always @(posedge clk) begin
  if (rst) begin
    for (i = 0; i < depth; i = i + 1) begin
      memory[i] <= 0;
    end
  end
end

endmodule

module fifo_queue (
    input clk,
    input reset,
    input enq,
    input deq,
    output reg full,
    output reg empty,
    output reg [7:0] data_out
);

reg [7:0] queue [0:7];
reg [2:0] head;
reg [2:0] tail;

always @(posedge clk or negedge reset) begin
    if (reset == 0) begin
        head <= 0;
        tail <= 0;
        full <= 0;
        empty <= 1;
    end else begin
        if (enq == 1 && full == 0) begin
            queue[head] <= data_in;
            head <= head + 1;
            if (head == 8) begin
                head <= 0;
            end
            if (head == tail) begin
                full <= 1;
            end
            empty <= 0;
        end
        if (deq == 1 && empty == 0) begin
            data_out <= queue[tail];
            queue[tail] <= 0;
            tail <= tail + 1;
            if (tail == 8) begin
                tail <= 0;
            end
            if (tail == head) begin
                empty <= 1;
            end
            full <= 0;
        end
    end
end

endmodule

module uart_tx #
(
    parameter DATA_WIDTH = 8
)
(
    input  wire                   clk,
    input  wire                   rst,

    /*
     * AXI input
     */
    input  wire [DATA_WIDTH-1:0]  input_axis_tdata,
    input  wire                   input_axis_tvalid,
    output wire                   input_axis_tready,

    /*
     * UART interface
     */
    output wire                   txd,

    /*
     * Status
     */
    output wire                   busy,

    /*
     * Configuration
     */
    input  wire [3:0]            uart_data_width,
    input  wire [1:0]            uart_bits,
    input  wire [1:0]            uart_parity,
    input  wire [1:0]            uart_stopbit,
    input  wire [15:0]            prescale
);

reg input_axis_tready_reg = 0;

reg txd_reg = 1;

reg busy_reg = 0;

reg [DATA_WIDTH+2:0] data_reg = 0;
reg [18:0] prescale_reg = 0;
reg [3:0] bit_cnt = 0;

assign input_axis_tready = input_axis_tready_reg;
assign txd = txd_reg;

assign busy = busy_reg;

genvar idx;
wire parity;
wire [DATA_WIDTH-1:0] bitmask_parity;
wire [DATA_WIDTH-1:0] bitmask_parity_reversed;
assign bitmask_parity = ~((1<<uart_bits) - 1);
generate
    for(idx = 0; idx < DATA_WIDTH; idx = idx + 1) begin : PROCESS_REVERSE_BITS
        assign bitmask_parity_reversed[idx] = bitmask_parity[DATA_WIDTH-idx-1];
    end
endgenerate
assign parity = (^(input_axis_tdata & bitmask_parity_reversed)) ^ uart_parity[1];

always @(posedge clk) begin
    if (rst) begin
        input_axis_tready_reg <= 0;
        txd_reg <= 1;
        prescale_reg <= 0;
        bit_cnt <= 0;
        busy_reg <= 0;
    end else begin
        if (prescale_reg > 0) begin
            input_axis_tready_reg <= 0;
            prescale_reg <= prescale_reg - 1;
        end else if (bit_cnt == 0) begin
            input_axis_tready_reg <= 1;
            busy_reg <= 0;

            if (input_axis_tvalid) begin
                input_axis_tready_reg <= ~input_axis_tready_reg;
                prescale_reg <= (prescale << 3)-1;
                bit_cnt <= uart_data_width+(uart_stopbit?2:1);
                if(uart_parity == 2'b00)
                case(uart_bits)
                    2'b00: data_reg <= {3'b111, input_axis_tdata};
                    2'b01: data_reg <= {4'b1111, input_axis_tdata[DATA_WIDTH-2:0]};
                    2'b10: data_reg <= {5'b11111, input_axis_tdata[DATA_WIDTH-3:0]};
                    2'b11: data_reg <= {6'b111111, input_axis_tdata[DATA_WIDTH-4:0]};
                endcase
                else
                case(uart_bits)
                    2'b00: data_reg <= {2'b11, parity, input_axis_tdata};
                    2'b01: data_reg <= {3'b111, parity, input_axis_tdata[DATA_WIDTH-2:0]};
                    2'b10: data_reg <= {4'b1111, parity, input_axis_tdata[DATA_WIDTH-3:0]};
                    2'b11: data_reg <= {5'b11111, parity, input_axis_tdata[DATA_WIDTH-4:0]};
                endcase
                //data_reg <= {2'b11, parity, input_axis_tdata};
                txd_reg <= 0;
                busy_reg <= 1;
            end
        end else begin
            if (bit_cnt > 1) begin
                bit_cnt <= bit_cnt - 1;
                if (bit_cnt == 2 && uart_stopbit[1] == 1'b1) prescale_reg <= (prescale << 2)-1;
                else prescale_reg <= (prescale << 3)-1;
                {data_reg, txd_reg} <= {1'b0, data_reg};
            end else if (bit_cnt == 1) begin
                bit_cnt <= bit_cnt - 1;
                prescale_reg <= (prescale << 3);
                txd_reg <= 1;
            end
        end
    end
end

endmodule

module Encoder(
    input Run,
    input R1in,
    input R1out,
    input R2in,
    input R2out,
    input Add,
    input Sub,
    input Mul,
    input Div,
    input SelectY,
    input Yin,
    input Zin,
    output reg Zout,
    output reg End,
    output reg [15:0] T,
    output reg [3:0] Ins
);

always @ (posedge Run) begin
    // Reset instruction code
    Ins <= 4'b0;

    // Encode arithmetic operation
    if (Add) begin
        Ins[2:0] <= 3'b001;
    end else if (Sub) begin
        Ins[2:0] <= 3'b010;
    end else if (Mul) begin
        Ins[2:0] <= 3'b011;
    end else if (Div) begin
        Ins[2:0] <= 3'b100;
    end

    // Encode register load
    if (R1in) begin
        Ins <= 4'b101;
    end else if (R2in) begin
        Ins <= 4'b110;
    end

    // Encode select Y
    if (SelectY) begin
        Ins <= 4'b111;
    end

    // Set end signal
    End <= 1'b1;
end

always @ (posedge Run) begin
    // Reset counter
    T <= 16'd0;
end

always @ (posedge Run) begin
    // Perform arithmetic operation
    if (Add) begin
        R1out <= R1in + R2in;
    end else if (Sub) begin
        R1out <= R1in - R2in;
    end else if (Mul) begin
        Zout <= Zin * Yin;
    end else if (Div) begin
        R1out <= R1in / R2in;
    end
end

always @ (posedge Run) begin
    // Set output register values
    if (R1in) begin
        R1out <= R1in;
    end else if (R2in) begin
        R2out <= R2in;
    end
end

always @ (posedge Run) begin
    // Set Y input
    if (SelectY) begin
        Yin <= Yin;
    end else begin
        Yin <= Zout;
    end
end

always @ (posedge Run) begin
    // Increment counter
    T <= T + 1;
end

endmodule

module signed_mag_comparator (
    input signed [3:0] A,
    input signed [3:0] B,
    output eq,
    output lt,
    output gt
);

reg signed [3:0] A_reg, B_reg;
reg eq_reg, lt_reg, gt_reg;

always @(posedge clk) begin
    A_reg <= A;
    B_reg <= B;
end

always @(posedge clk) begin
    if (A_reg == B_reg) begin
        eq_reg <= 1'b1;
        lt_reg <= 1'b0;
        gt_reg <= 1'b0;
    end else if (A_reg < B_reg) begin
        eq_reg <= 1'b0;
        lt_reg <= 1'b1;
        gt_reg <= 1'b0;
    end else begin
        eq_reg <= 1'b0;
        lt_reg <= 1'b0;
        gt_reg <= 1'b1;
    end
end

assign eq = eq_reg;
assign lt = lt_reg;
assign gt = gt_reg;

endmodule

