module KeyboardReader (
    input wire rst,
    input wire clk,
    inout wire ps2CLK,
    inout wire ps2DATA,
    output reg[8:0] pressedKey,
    output reg pressed
    );

wire[7:0] readData;
wire update;
reg update_prev;
reg breakSig = 0;
reg extended = 0;

PS2_Controller ps2 (
    .reset (rst),
    .CLOCK_50 (clk),
    .PS2_CLK(ps2CLK),
    .PS2_DAT(ps2DATA),
    .received_data(readData),
    .received_data_en(update)
    );

always @ (posedge clk) begin
    update_prev <= update;
end

always @ (posedge clk) begin
    if (pressed)
        pressed <= 0;
    if (rst) begin
        breakSig <= 0;
        extended <= 0;
        pressed <= 0;
        pressedKey <= 9'b0;
    end else if (update_prev && !update) begin
        if (readData == 8'hF0) begin
            breakSig <= 1;
        end else if (readData == 8'hE0) begin
            extended <= 1;
        end else if (breakSig) begin
            breakSig <= 0;
            extended <= 0;
        end else begin
            pressedKey <= {extended, readData};
            pressed <= 1;
            breakSig <= 0;
            extended <= 0;
        end
    end
end

endmodule

module TurboCode (
  input [k-1:0] in,
  output [n-1:0] out
);

parameter k = 1024; // number of input data bits
parameter n = 2048; // number of encoded bits
parameter m = 16;   // number of parity bits
parameter L = 8;    // number of iterations by the decoder

// Generator polynomials for the two convolutional encoders
reg [m-1:0] g1 = 16'hb8d9;
reg [m-1:0] g2 = 16'h6d57;

// Interleaver
integer i;
reg [k-1:0] interleaved;
always @(in) begin
  for (i = 0; i < k; i = i + 1) begin
    interleaved[i] = in[((i * 17) + 3) % k];
  end
end

// Encoder
reg [n/2-1:0] encoded1, encoded2;
TurboEncoder encoder1 (
  .in(in),
  .out(encoded1),
  .g1(g1),
  .g2(g2)
);

TurboEncoder encoder2 (
  .in(interleaved),
  .out(encoded2),
  .g1(g1),
  .g2(g2)
);

// Concatenate and interleave the encoded streams
genvar j;
generate
  for (j = 0; j < n/2; j = j + 1) begin
    assign out[2*j] = encoded1[j];
    assign out[2*j+1] = encoded2[j];
  end
endgenerate

// Decoder
reg [k-1:0] decoded;
TurboDecoder decoder (
  .in(out),
  .out(decoded),
  .g1(g1),
  .g2(g2),
  .L(L)
);

endmodule

