module counter_load_down_2(
  input clk, 
  input rst,
  input srst,  // синхронный сброс 
  input clk_ena,
  input load,  // загрузить ноль
  input [WIDTH-1:0] dfload,  // data for loading
  output carry  // перенесо счетчика
);
  parameter MOD_COUNT = 4;
  parameter WIDTH = 4;

  reg [WIDTH-1:0] count;  // накопитель
  reg carry_tmp;

  always @(posedge clk or posedge rst) begin
    if(rst) begin
      count <= 0;
      carry_tmp <= 0;
    end
    else if(clk_ena) begin
      if(srst) begin
        count <= 0;
        carry_tmp <= 0;
      end
      else if(load) begin  // синхронная загрузка посути
        count <= dfload;
        carry_tmp <= 0;
      end
      else begin
        if(count == 0) begin
          count <= MOD_COUNT-1;
          carry_tmp <= 1;
        end
        else begin
          count <= count-1;
          carry_tmp <= 0;
        end
      end
    end
  end

  assign carry = carry_tmp;

endmodule

