module ad_ss_422to444 (
  // 422 inputs
  clk,
  s422_de,
  s422_sync,
  s422_data,
  // 444 outputs
  s444_sync,
  s444_data);
  // parameters
  parameter   Cr_Cb_N = 0;
  parameter   DELAY_DATA_WIDTH = 16;
  localparam  DW = DELAY_DATA_WIDTH - 1;
  // 422 inputs
  input           clk;
  input           s422_de;
  input   [DW:0]  s422_sync;
  input   [15:0]  s422_data;
  // 444 inputs
  output  [DW:0]  s444_sync;
  output  [23:0]  s444_data;
  // internal registers
  reg             cr_cb_sel = 'd0;
  reg             s422_de_d = 'd0;
  reg     [DW:0]  s422_sync_d = 'd0;
  reg             s422_de_2d = 'd0;
  reg      [7:0]  s422_Y_d;
  reg      [7:0]  s422_CbCr_d;
  reg      [7:0]  s422_CbCr_2d;
  reg     [DW:0]  s444_sync = 'd0;
  reg     [23:0]  s444_data = 'd0;
  reg     [ 8:0]  s422_CbCr_avg;
  // internal wires
  wire    [ 7:0]  s422_Y;
  wire    [ 7:0]  s422_CbCr;
  // Input format is 
  // [15:8] Cb/Cr
  // [ 7:0] Y
  //
  // Output format is
  // [23:15] Cr
  // [16: 8] Y
  // [ 7: 0] Cb
  assign s422_Y = s422_data[7:0];
  assign s422_CbCr = s422_data[15:8];
  // first data on de assertion is cb (0x0), then cr (0x1).
  // previous data is held when not current
  always @(posedge clk) begin
    if (s422_de_d == 1'b1) begin
      cr_cb_sel <= ~cr_cb_sel;
    end else begin
      cr_cb_sel <= Cr_Cb_N;
    end
  end
  // pipe line stages
  always @(posedge clk) begin
    s422_de_d <= s422_de;
    s422_sync_d <= s422_sync;
    s422_de_2d <= s422_de_d;
	s422_Y_d <= s422_Y;
	s422_CbCr_d <= s422_CbCr;
	s422_CbCr_2d <= s422_CbCr_d;
  end
  // If both the left and the right sample are valid do the average, otherwise
  // use the only valid.
  always @(s422_de_2d, s422_de, s422_CbCr, s422_CbCr_2d)
  begin
		if (s422_de == 1'b1 && s422_de_2d)
			s422_CbCr_avg <= s422_CbCr + s422_CbCr_2d;
		else if (s422_de == 1'b1)
			s422_CbCr_avg <= {s422_CbCr, 1'b0};
		else
			s422_CbCr_avg <= {s422_CbCr_2d, 1'b0};
  end
  // 444 outputs
  always @(posedge clk) begin
    s444_sync <= s422_sync_d;
    s444_data[15:8] <= s422_Y_d;
	if (cr_cb_sel) begin
		s444_data[23:16] <= s422_CbCr_d;
		s444_data[ 7: 0] <= s422_CbCr_avg[8:1];
	end else begin
		s444_data[23:16] <= s422_CbCr_avg[8:1];
		s444_data[ 7: 0] <= s422_CbCr_d;
	end
  end
endmodule

module top_module (
    input CLK,
    input RESET,
    input SHIFT,
    input LOAD,
    input [3:0] DATA,
    input [3:0] D,
    output reg [3:0] Q
);

reg [3:0] shift_reg;
reg [3:0] counter;
wire [3:0] xor_out;

// Shift register module
always @(posedge CLK) begin
    if(RESET) begin
        shift_reg <= 4'b0000;
    end
    else if(SHIFT) begin
        shift_reg <= {shift_reg[2:0], counter[0]};
    end
end

// Synchronous counter module
always @(posedge CLK) begin
    if(RESET) begin
        counter <= 4'b0000;
    end
    else if(LOAD) begin
        counter <= DATA;
    end
    else begin
        counter <= counter + 1;
    end
end

// XOR module
assign xor_out = shift_reg ^ counter;

// Output
always @(posedge CLK) begin
    if(RESET) begin
        Q <= 4'b0000;
    end
    else begin
        Q <= counter;
    end
end

endmodule

module salsa (clk, feedback, B, Bx, Bo, X0out, X1out, Xaddr);

// Latency 9 clock cycles (4 col steps + 4 row + 1 sync), hence 4 salsa iterations in 36 cycles

input clk;
input feedback;
input [511:0]B;
input [511:0]Bx;
output [511:0]Bo;
output [511:0]X0out;	// Pipelined B
output [511:0]X1out;	// Pipelined Bx
output [9:0]Xaddr;		// Address

wire [511:0]xx;			// Initial xor
wire [511:0]xxd9;		// Delayed 9 cycles

wire [511:0]xr;			// Output of salsa core
reg [511:0]xrd;			// Feedback ( 9th latency step to maintain sync with ram access)
reg [511:0]xrd2;		// Feedback (10th latency step to maintain sync with ram access)

wire [9:0]addr;			// Address from salsa
reg [9:0]xxd7_addr;

// X0/X1 delays ... just to check timing, probably need to use a ram location to reduce routing congestion

reg [511:0]x0d1;
reg [511:0]x0d2;
reg [511:0]x0d3;
reg [511:0]x0d4;
reg [511:0]x0d5;
reg [511:0]x0d6;
reg [511:0]x0d7;
reg [511:0]x0d8;
reg [511:0]x0d9;

reg [511:0]x1d1;
reg [511:0]x1d2;
reg [511:0]x1d3;
reg [511:0]x1d4;
reg [511:0]x1d5;
reg [511:0]x1d6;
reg [511:0]x1d7;
reg [511:0]x1d8;
reg [511:0]x1d9;

assign X0out = x0d9;
assign X1out = x1d9;

salsa_core salsa1 (clk, feedback ? xrd2 : xx, xr, addr);

always @ (posedge clk)
begin
	xrd <= xr;
	xrd2 <= xrd;

	x0d1 <= B;
	x0d2 <= x0d1;
	x0d3 <= x0d2;
	x0d4 <= x0d3;
	x0d5 <= x0d4;
	x0d6 <= x0d5;
	x0d7 <= x0d6;
	x0d8 <= x0d7;
	x0d9 <= x0d8;

	x1d1 <= Bx;
	x1d2 <= x1d1;
	x1d3 <= x1d2;
	x1d4 <= x1d3;
	x1d5 <= x1d4;
	x1d6 <= x1d5;
	x1d7 <= x1d6;
	x1d8 <= x1d7;
	x1d9 <= x1d8;

	xxd7_addr <= x0d6[9:0] ^ x1d6[9:0];
end

genvar i;
generate
	for (i = 0; i < 16; i = i + 1) begin : XX
		// Initial XOR. NB this adds to the propagation delay of the first salsa, may want register it.
		assign xx[`IDX(i)] = B[`IDX(i)] ^ Bx[`IDX(i)];
		assign xxd9[`IDX(i)] = x0d9[`IDX(i)] ^ x1d9[`IDX(i)];		// Could do one cycle early (in reg) to save an xor delay
		// Final sum. NB Ouptut is at 8 cycle latency.
		assign Bo[`IDX(i)] = xxd9[`IDX(i)] + xrd[`IDX(i)];
	end
endgenerate

assign Xaddr = xxd7_addr + addr;

endmodule

module BSCAN_SPARTAN6 (CAPTURE, DRCK, RESET, RUNTEST, SEL, SHIFT, TCK, TDI, TMS, UPDATE, TDO);

    output CAPTURE, DRCK, RESET, RUNTEST, SEL, SHIFT, TCK, TDI, TMS, UPDATE;

    input TDO;

    reg SEL_zd;

    parameter integer JTAG_CHAIN = 1;

    pulldown (DRCK);
    pulldown (RESET);
    pulldown (SEL);
    pulldown (SHIFT);
    pulldown (TDI);
    pulldown (UPDATE);

//--####################################################################
//--#####                        Initialization                      ###
//--####################################################################
    initial begin
	if ((JTAG_CHAIN != 1) && (JTAG_CHAIN != 2) && (JTAG_CHAIN != 3) && (JTAG_CHAIN != 4)) begin
            $display("Attribute Syntax Error : The attribute JTAG_CHAIN on BSCAN_SPARTAN6 instance %m is set to %d.  Legal values for this attribute are 1, 2, 3 or 4.", JTAG_CHAIN);
            $finish;
        end

    end
//--####################################################################
//--#####                          Jtag_select                       ###
//--####################################################################
   always@(glbl.JTAG_SEL1_GLBL or glbl.JTAG_SEL2_GLBL or glbl.JTAG_SEL3_GLBL or glbl.JTAG_SEL4_GLBL) begin
      if (JTAG_CHAIN == 1)      SEL_zd = glbl.JTAG_SEL1_GLBL;
      else if (JTAG_CHAIN == 2) SEL_zd = glbl.JTAG_SEL2_GLBL;
      else if (JTAG_CHAIN == 3) SEL_zd = glbl.JTAG_SEL3_GLBL; 
      else if (JTAG_CHAIN == 4) SEL_zd = glbl.JTAG_SEL4_GLBL;
   end
//--####################################################################
//--#####                           USER_TDO                         ###
//--####################################################################
   always@(TDO) begin
      if (JTAG_CHAIN == 1)      glbl.JTAG_USER_TDO1_GLBL = TDO;
      else if (JTAG_CHAIN == 2) glbl.JTAG_USER_TDO2_GLBL = TDO;
      else if (JTAG_CHAIN == 3) glbl.JTAG_USER_TDO3_GLBL = TDO;
      else if (JTAG_CHAIN == 4) glbl.JTAG_USER_TDO4_GLBL = TDO;
   end
//--####################################################################
//--#####                            Output                          ###
//--####################################################################

assign CAPTURE = glbl.JTAG_CAPTURE_GLBL; 
assign #5 DRCK    = ((SEL_zd & !glbl.JTAG_SHIFT_GLBL & !glbl.JTAG_CAPTURE_GLBL)
                                           ||                            
                     (SEL_zd & glbl.JTAG_SHIFT_GLBL   & glbl.JTAG_TCK_GLBL)
                                           ||
                     (SEL_zd & glbl.JTAG_CAPTURE_GLBL &  glbl.JTAG_TCK_GLBL));

assign RESET   = glbl.JTAG_RESET_GLBL;
assign RUNTEST = glbl.JTAG_RUNTEST_GLBL;
assign SEL     = SEL_zd;
assign SHIFT   = glbl.JTAG_SHIFT_GLBL;
assign TDI     = glbl.JTAG_TDI_GLBL;
assign TCK     = glbl.JTAG_TCK_GLBL;
assign TMS     = glbl.JTAG_TMS_GLBL;
