module combinational_logic (
    input [7:0] in,
    output reg [3:0] out
);

    always @* begin
        case(in)
            8'b00000000: out = 4'b0000;
            8'b00000001: out = 4'b0001;
            8'b00000010: out = 4'b0010;
            8'b00000011: out = 4'b0011;
            8'b00000100: out = 4'b0100;
            8'b00000101: out = 4'b0101;
            8'b00000110: out = 4'b0110;
            8'b00000111: out = 4'b0111;
            8'b00001000: out = 4'b1000;
            8'b00001001: out = 4'b1001;
            8'b00001010: out = 4'b0000;
            8'b00001011: out = 4'b0001;
            8'b00001100: out = 4'b0010;
            8'b00001101: out = 4'b0011;
            8'b00001110: out = 4'b0100;
            8'b00001111: out = 4'b0101;
            default: out = 4'b0000;
        endcase
    end

endmodule

module binary_counter (
    input clk,
    input reset,   // Synchronous active-high reset
    input [3:0] enable,
    output reg [3:0] q,
    output reg [15:0] counter_q
);

    always @(posedge clk) begin
        if (reset) begin
            q <= 4'b0000;
            counter_q <= 16'b0000000000000000;
        end
        else if (enable == 4'b1111) begin
            q <= q + 1;
            counter_q <= counter_q + 1;
        end
    end

endmodule

module functional_module (
    input [7:0] in,
    input [15:0] counter_q,
    output [7:0] out
);

    assign out = in + counter_q[7:0];

endmodule

module top_module (
    input clk,
    input reset,   // Synchronous active-high reset
    input [7:0] in,
    output [7:0] out,
    output [3:0] counter_out,
    output [15:0] counter_q,
    output [7:0] final_out
);

    wire [3:0] enable;
    wire [7:0] functional_out;

    combinational_logic CL(in, enable);
    binary_counter BC(clk, reset, enable, counter_out, counter_q);
    functional_module FM(in, counter_q, functional_out);

    assign out = functional_out;
    assign final_out = functional_out;

endmodule

module testbench;

    reg reset;
    reg wenb;
    reg [7:0] in_data;
    reg clk;
    wire [7:0] reg_0x38;

    r_RX_BUF_OBJ2_BYTE_0 dut (
        .reset(reset),
        .wenb(wenb),
        .in_data(in_data),
        .clk(clk),
        .reg_0x38(reg_0x38)
    );

    initial begin
        // Initialize inputs
        reset = 1'b1;
        wenb = 1'b0;
        in_data = 8'h00;
        clk = 1'b0;

        // Wait for 5 clock cycles
        #5;

        // De-assert reset
        reset = 1'b0;

        // Wait for 5 clock cycles
        #5;

        // Test case 1: On reset, the output register is set to 0x00
        if (reg_0x38 !== 8'h00) begin
            $display("Test case 1 failed: reg_0x38 = %h", reg_0x38);
            $finish;
        end

        // Test case 2: When wenb is not active, the output register is set to the value of in_data
        in_data = 8'h55;
        wenb = 1'b0;
        #1;
        if (reg_0x38 !== 8'h55) begin
            $display("Test case 2 failed: reg_0x38 = %h", reg_0x38);
            $finish;
        end

        // Test case 3: When wenb is active, the output register remains unchanged
        wenb = 1'b1;
        #1;
        if (reg_0x38 !== 8'h55) begin
            $display("Test case 3 failed: reg_0x38 = %h", reg_0x38);
            $finish;
        end

        // Test passed
        $display("All tests passed");
        $finish;
    end

    always #5 clk = ~clk;

endmodule

