module communication_system (
  input activate_0r,
  output activate_0a,
  output activateOut_0r,
  input activateOut_0a,
  output activateOut_1r,
  input activateOut_1a
);

  wire [1:0] acks_0n;
  C2 I0 (activate_0a, acks_0n[0], acks_0n[1]);
  telem I1 (activate_0r, acks_0n[0], activateOut_0r, activateOut_0a);
  telem I2 (activate_0r, acks_0n[1], activateOut_1r, activateOut_1a);

endmodule

module C2 (activate, ack0, ack1);
  output ack0;
  output ack1;
  input activate;
  reg [1:0] state = 2'b00;
  always @ (posedge activate) begin
    case (state)
      2'b00: begin
        ack0 <= 1;
        state <= 2'b01;
      end
      2'b01: begin
        ack1 <= 1;
        state <= 2'b10;
      end
      2'b10: begin
        ack0 <= 0;
        ack1 <= 0;
        state <= 2'b00;
      end
    endcase
  end
endmodule

module telem (activate_in, ack_in, activateOut, ackOut);
  input activate_in;
  input ack_in;
  output activateOut;
  output ackOut;
  reg [1:0] state = 2'b00;
  always @ (posedge activate_in) begin
    case (state)
      2'b00: begin
        activateOut <= 1;
        state <= 2'b01;
      end
      2'b01: begin
        if (ack_in) begin
          ackOut <= 1;
          state <= 2'b10;
        end
      end
      2'b10: begin
        activateOut <= 0;
        ackOut <= 0;
        state <= 2'b00;
      end
    endcase
  end
endmodule

module xor_detector(
  input clk,
  input reset,
  input in_1,
  input in_2,
  output out_xor_comb,
  output out_xor_seq
);

  reg prev_in_1;
  reg prev_in_2;
  reg out_seq_reg;

  assign out_xor_comb = in_1 ^ in_2;

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      prev_in_1 <= 1'b0;
      prev_in_2 <= 1'b0;
      out_seq_reg <= 1'b0;
    end else begin
      if (in_1 != prev_in_1 || in_2 != prev_in_2) begin
        out_seq_reg <= in_1 ^ in_2;
      end
      prev_in_1 <= in_1;
      prev_in_2 <= in_2;
    end
  end

  assign out_xor_seq = out_seq_reg;

endmodule

module anyedge (
    input wire clk,
    input wire reset,
    input wire in,
    output wire out
);

reg last_in;

