module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out
);
    reg [9:0] acc;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            acc <= 10'b0;
            valid_b <= 1'b0;
        end else begin
            if (valid_a && ready_b) begin
                acc <= acc + data_in;
                valid_b <= 1'b1;
            end else begin
                valid_b <= 1'b0;
            end
        end
    end

    assign ready_a = ready_b;
    assign data_out = acc;

endmodule

module add_sub_4bit(
