    wire s0, s1, s2, s3;

    FA1 fa1_0(.a(A[0]), .b(B[0]), .cin(Cin), .sum(s0), .cout(c1));
    FA1 fa1_1(.a(A[1]), .b(B[1]), .cin(c1), .sum(s1), .cout(c2));
    FA1 fa1_2(.a(A[2]), .b(B[2]), .cin(c2), .sum(s2), .cout(c3));
    FA1 fa1_3(.a(A[3]), .b(B[3]), .cin(c3), .sum(s3), .cout(Cout));

    assign S = Sub ? {~s3, ~s2, ~s1, ~s0} + 4'b1 : {s3, s2, s1, s0} + Cin;

endmodule

