reg [3:0] ram [0:7];

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        read_data <= 4'b0;
    end else begin
        if (read_en) begin
            read_data <= ram[read_addr];
        end
        if (write_en) begin
            ram[write_addr] <= write_data;
