module calculator(clk, reset, A, B, operation, result, done);
    input clk, reset;
    input [7:0] A, B;
    input [1:0] operation;
    output reg [7:0] result;
    output reg done;

    reg [15:0] product;
    reg [15:0] dividend;
    reg [7:0] quotient;
    reg [3:0] counter;
    reg [1:0] state;

    parameter ADD = 2'b00;
    parameter SUB = 2'b01;
    parameter MUL = 2'b10;
    parameter DIV = 2'b11;

    always @(posedge clk) begin
        if (reset) begin
            result <= 8'b0;
            done <= 1'b0;
            counter <= 4'd0;
            state <= 2'b00;
        end
        else begin
            case (state)
                2'b00: begin // Addition
                    result <= A + B;
                    done <= 1'b1;
                    state <= 2'b00;
                end

                2'b01: begin // Subtraction
                    result <= A - B;
                    done <= 1'b1;
                    state <= 2'b00;
                end

                2'b10: begin // Multiplication
                    if (counter == 0) begin
                        product <= A * B;
                        counter <= 4'd1;
                    end
                    else if (counter < 5) begin
                        product <= {product[13:0], 2'b0};
                        counter <= counter + 1;
                    end
                    else begin
                        result <= product[15:8];
                        done <= 1'b1;
                        state <= 2'b00;
                    end
                end

                2'b11: begin // Division
                    if (counter == 0) begin
                        dividend <= {A, 8'b0};
                        quotient <= 8'b0;
                        counter <= 4'd1;
                    end
                    else if (counter < 9) begin
                        dividend <= {dividend[14:0], B[7]};
                        quotient <= {quotient[6:0], dividend[15]} << 1;
                        counter <= counter + 1;
                    end
                    else begin
                        result <= quotient[7:0];
                        done <= 1'b1;
                        state <= 2'b00;
                    end
                end
            endcase

            if (operation == ADD)
                state <= 2'b00;
            else if (operation == SUB)
                state <= 2'b01;
            else if (operation == MUL)
                state <= 2'b10;
            else if (operation == DIV)
                state <= 2'b11;
        end
    end
endmodule

