module counter (
    input clock,
    input reset,
    input enable,
    input capture,
    input upCnt,
    input downCnt,
    input up_ndown,
    input [15:0] count,
    output reg comp,
    output reg tc,
    output reg interrupt
);

parameter CaptureMode = 0;
parameter ClockMode = 3;
parameter CompareMode = 1;
parameter CompareStatusEdgeSense = 1;
parameter EnableMode = 0;
parameter ReloadOnCapture = 0;
parameter ReloadOnCompare = 0;
parameter ReloadOnOverUnder = 1;
parameter ReloadOnReset = 1;
parameter Resolution = 16;
parameter RunMode = 0;
parameter UseInterrupt = 1;

reg [15:0] counter;
reg [15:0] prev_count;
reg [15:0] reload_value;
reg [1:0] mode;
reg [1:0] prev_mode;
reg capture_edge;
reg comp_edge;
reg [1:0] up_down;
wire [15:0] next_count;

assign next_count = (up_down == 2'b01) ? counter + 1 : (up_down == 2'b10) ? counter - 1 : counter;

always @(posedge clock) begin
    if (reset) begin
        counter <= 0;
        mode <= RunMode;
        prev_mode <= RunMode;
    end else begin
        prev_mode <= mode;
        if (mode == CaptureMode) begin
            if (capture_edge) begin
                counter <= reload_value;
                capture_edge <= 0;
                mode <= prev_mode;
            end
        end else if (mode == ClockMode) begin
            counter <= next_count;
        end else if (mode == CompareMode) begin
            if (comp_edge) begin
                counter <= reload_value;
                comp_edge <= 0;
                mode <= prev_mode;
            end else begin
                counter <= next_count;
            end
        end else if (mode == EnableMode) begin
            if (enable) begin
                counter <= next_count;
            end
        end else begin // Reload modes
            if ((counter == 0 && up_down == 2'b10) || (counter == 2**Resolution-1 && up_down == 2'b01)) begin
                counter <= reload_value;
            end else begin
                counter <= next_count;
            end
        end
        if (counter == 2**Resolution-1) begin
            tc <= 1;
        end else begin
            tc <= 0;
        end
        if (counter == reload_value && mode == CompareMode) begin
            comp <= CompareStatusEdgeSense;
        end else begin
            comp <= 0;
        end
        if (comp || tc) begin
            interrupt <= UseInterrupt;
        end else begin
            interrupt <= 0;
        end
    end
end

always @(posedge clock) begin
    if (capture) begin
        capture_edge <= 1;
        reload_value <= count;
        mode <= CaptureMode;
    end else if (upCnt) begin
        up_down <= 2'b01;
        mode <= prev_mode;
    end else if (downCnt) begin
        up_down <= 2'b10;
        mode <= prev_mode;
    end else if (up_ndown) begin
        up_down <= 2'b01;
    end else begin
        up_down <= 2'b10;
    end
    prev_count <= counter;
end

endmodule

module top_module (
    input [3:0] in,
    output reg [3:0] out
);

    // Binary to Gray Code Converter
    wire [3:0] gray_in = in ^ (in >> 1);

    // Binary to One-Hot Decoder
    wire [3:0] one_hot;
    assign one_hot = (gray_in == 4'b0001) ? 4'b0001 :
                     (gray_in == 4'b0010) ? 4'b0010 :
                     (gray_in == 4'b0100) ? 4'b0100 :
                     (gray_in == 4'b1000) ? 4'b1000 :
                                           4'b0000 ;

    // Priority Encoder
    wire [1:0] priority;
    assign priority = (one_hot[3]) ? 2'b11 :
                      (one_hot[2]) ? 2'b10 :
                      (one_hot[1]) ? 2'b01 :
                      (one_hot[0]) ? 2'b00 :
                                     2'b00 ;

    // 2-to-4 Decoder
    always @(*) begin
        case (priority)
            2'b00: out = 4'b0001;
            2'b01: out = 4'b0010;
            2'b10: out = 4'b0100;
            2'b11: out = 4'b1000;
        endcase
    end

endmodule

