    if (ena[0] == 1'b1) begin
        if (ena[1] == 1'b1) begin
            shift_reg <= data;
        end else begin
            shift_reg <= {shift_reg[98:0], shift_reg[99]};
        end
    end
end

always @(*) begin
    case (control)
        2'b00: q = shift_reg;
        2'b01: q = {1'b0, rise};
        2'b10: q = {1'b0, down};
        2'b11: q = shift_reg & {1'b0, rise};
    endcase
end

endmodule

module edge_detector(
    input clk,
    input reset,
    input a,
    input control,
    output reg rise,
    output reg down
);

reg [1:0] state;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        state <= 2'b00;
        rise <= 1'b0;
        down <= 1'b0;
    end else begin
        case (state)
            2'b00: begin
                if (a == 1'b1) begin
                    state <= 2'b01;
                end else begin
                    state <= 2'b00;
                end
            end
            2'b01: begin
                if (a == 1'b1) begin
                    state <= 2'b10;
                    rise <= 1'b1;
                end else begin
                    state <= 2'b01;
                end
            end
            2'b10: begin
                if (a == 1'b0) begin
                    state <= 2'b11;
                end else begin
                    state <= 2'b10;
                end
            end
            2'b11: begin
                if (a == 1'b0) begin
                    state <= 2'b00;
                    down <= 1'b1;
                end else begin
                    state <= 2'b11;
                end
            end
        endcase
    end
end

endmodule

