     input          reset,     // Reset
     input          clk,       // Clock

     output reg [WIDTH-1:0]  dout,    // Data out
     output         full,             // FIFO full
     output         nearly_full,      // FIFO nearly full
     output         prog_full,       // FIFO programmatically full
     output         empty            // FIFO empty
     );

    localparam MAX_DEPTH = 2 ** MAX_DEPTH_BITS;

    reg [WIDTH-1:0] queue [MAX_DEPTH - 1 : 0];
    reg [MAX_DEPTH_BITS - 1 : 0] rd_ptr;
    reg [MAX_DEPTH_BITS - 1 : 0] wr_ptr;
    reg [MAX_DEPTH_BITS : 0] depth;

    // Sample the data
    always @(posedge clk)
    begin
        if (wr_en && !full) 
            queue[wr_ptr] <= din;
        if (rd_en && !empty)
            dout <= queue[rd_ptr];
    end

    always @(posedge clk)
    begin
        if (reset) begin
            rd_ptr <= 'h0;
            wr_ptr <= 'h0;
            depth  <= 'h0;
        end
        else begin
            if (wr_en && !rd_en && !full) wr_ptr <= wr_ptr + 'h1;
            if (rd_en && !wr_en && !empty) rd_ptr <= rd_ptr + 'h1;
            if (wr_en && !rd_en && !full) depth <= depth + 'h1;
            if (rd_en && !wr_en && !empty) depth <= depth - 'h1;
        end
    end

    assign full = depth == MAX_DEPTH;
    assign nearly_full = depth >= MAX_DEPTH - 1;
    assign prog_full = depth >= PROG_FULL_THRESHOLD;
    assign empty = depth == 'h0;

    always @(posedge clk)
    begin
        if (wr_en && full && !rd_en)
            $display($time, " ERROR: Attempt to write to full FIFO: %m");
        if (rd_en && empty)
            $display($time, " ERROR: Attempt to read an empty FIFO: %m");
    end

endmodule

