    input wire [7:0] in_2,
    input wire [7:0] in_3,
    output wire [7:0] out
);
    wire [7:0] min_0_1;
    wire [7:0] min_2_3;
    wire [7:0] min_all;

    assign min_0_1 = (in_0 < in_1) ? in_0 : in_1;
    assign min_2_3 = (in_2 < in_3) ? in_2 : in_3;
