module top_module (
    input wire [15:0] in,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo,
    output wire [7:0] final_output
);
    wire [7:0] split_out_hi;
    wire [7:0] split_out_lo;
    wire [7:0] min_val;

    split_module split_inst (
        .in(in),
        .out_hi(split_out_hi),
        .out_lo(split_out_lo)
    );

    four_way_minimum min_inst (
        .in_0(split_out_hi),
        .in_1(split_out_lo),
        .in_2({4'b0, split_out_hi}),
        .in_3({4'b0, split_out_lo}),
        .out(min_val)
    );

    functional_module func_inst (
        .in_0(split_out_hi),
        .in_1(split_out_lo),
        .min_val(min_val),
        .final_output(final_output)
    );

    assign out_hi = split_out_hi;
    assign out_lo = split_out_lo;
endmodule

