module bcd_counter (
    input clk,
    input reset,   // Synchronous active-high reset
    output [3:1] ena,  // enable signal for each of the upper three digits
    output [15:0] q    // 16-bit binary-coded decimal value
);

    // Internal signals
    reg [31:0] count;
    reg [3:0] digit[0:3];
    wire [3:0] bcd[0:3];
    wire [6:0] seg[0:3];
    wire [31:0] next_count;
    wire [31:0] add_result;
    wire cmp_result;

    // Instantiate modules
    adder adder_inst(.a(count), .b(1), .cin(0), .s(add_result), .cout());
    comparator cmp_inst(.a(count), .b(9999), .eq(cmp_result));
    mux mux_inst(.in(digit), .sel(bcd), .out(q));
    decoder decoder_inst(.in(bcd), .out(seg));

    // Assign enable signals
    assign ena[3] = 1;
    assign ena[2] = (count >= 1000);
    assign ena[1] = (count >= 100);

    // Increment count on clock edge
    always @(posedge clk) begin
        if (reset) begin
            count <= 0;
            digit <= 0;
        end else begin
            if (cmp_result) begin
                count <= 0;
                digit <= 0;
            end else begin
                adder_inst.a <= count;
                adder_inst.b <= 1;
                adder_inst.cin <= 0;
                next_count <= add_result;
                if (digit[0] == 9) begin
                    digit[0] <= 0;
                    if (digit[1] == 9) begin
                        digit[1] <= 0;
                        if (digit[2] == 9) begin
                            digit[2] <= 0;
                            digit[3] <= digit[3] + 1;
                        end else begin
                            digit[2] <= digit[2] + 1;
                        end
                    end else begin
                        digit[1] <= digit[1] + 1;
                    end
                end else begin
                    digit[0] <= digit[0] + 1;
                end
            end
        end
    end

    // Convert binary to BCD
    always @* begin
        bcd[0] = digit[0] + (digit[0] >= 5 ? 3 : 0);
        bcd[1] = digit[1] + (digit[1] >= 5 ? 3 : 0);
        bcd[2] = digit[2] + (digit[2] >= 5 ? 3 : 0);
        bcd[3] = digit[3] + (digit[3] >= 5 ? 3 : 0);
    end

endmodule

// 32-bit adder module
module adder (
    input [31:0] a,
    input [31:0] b,
    input cin,
    output [31:0] s,
    output cout
);
    assign {cout,s} = a + b + cin;
endmodule

// 32-bit comparator module
module comparator (
    input [31:0] a,
    input [31:0] b,
    output eq
);
    assign eq = (a == b);
endmodule

// 4-to-1 multiplexer module
module mux (
    input [3:0] in[0:3],
    input [3:0] sel,
    output reg [3:0] out
);
    always @* begin
        case (sel)
            4'b0000: out = in[0];
            4'b0001: out = in[1];
            4'b0010: out = in[2];
            4'b0011: out = in[3];
            default: out = 0;
        endcase
    end
endmodule

// BCD to 7-segment decoder module
module decoder (
    input [3:0] in[0:3],
    output [6:0] out[0:3]
);
    assign out[0] = (in[0] == 0) ? 7'b1000000 :
                    (in[0] == 1) ? 7'b1111001 :
                    (in[0] == 2) ? 7'b0100100 :
                    (in[0] == 3) ? 7'b0110000 :
                    (in[0] == 4) ? 7'b0011001 :
                    (in[0] == 5) ? 7'b0010010 :
                    (in[0] == 6) ? 7'b0000010 :
                    (in[0] == 7) ? 7'b1111000 :
                    (in[0] == 8) ? 7'b0000000 :
                                   7'b0010000 ;
    assign out[1] = (in[1] == 0) ? 7'b1000000 :
                    (in[1] == 1) ? 7'b1111001 :
                    (in[1] == 2) ? 7'b0100100 :
                    (in[1] == 3) ? 7'b0110000 :
                    (in[1] == 4) ? 7'b0011001 :
                    (in[1] == 5) ? 7'b0010010 :
                    (in[1] == 6) ? 7'b0000010 :
                    (in[1] == 7) ? 7'b1111000 :
                    (in[1] == 8) ? 7'b0000000 :
                                   7'b0010000 ;
    assign out[2] = (in[2] == 0) ? 7'b1000000 :
                    (in[2] == 1) ? 7'b1111001 :
                    (in[2] == 2) ? 7'b0100100 :
                    (in[2] == 3) ? 7'b0110000 :
                    (in[2] == 4) ? 7'b0011001 :
                    (in[2] == 5) ? 7'b0010010 :
                    (in[2] == 6) ? 7'b0000010 :
                    (in[2] == 7) ? 7'b1111000 :
                    (in[2] == 8) ? 7'b0000000 :
                                   7'b0010000 ;
    assign out[3] = (in[3] == 0) ? 7'b1000000 :
                    (in[3] == 1) ? 7'b1111001 :
                    (in[3] == 2) ? 7'b0100100 :
                    (in[3] == 3) ? 7'b0110000 :
                    (in[3] == 4) ? 7'b0011001 :
                    (in[3] == 5) ? 7'b0010010 :
                    (in[3] == 6) ? 7'b0000010 :
                    (in[3] == 7) ? 7'b1111000 :
                    (in[3] == 8) ? 7'b0000000 :
                                   7'b0010000 ;
endmodule

module top_module (
    input [15:0] a, // Input for the multiplier and adder modules
    input [15:0] b, // Input for the multiplier module
    input sub, // Input for the adder module
    output [31:0] mult_output, // Output from the multiplier module
    output [15:0] sum_output, // Output from the adder module
    output xor_output // Output from the functional module
);

wire [31:0] mult_result;
wire [15:0] add_result;
wire [31:0] xor_result;

multiplier mult_inst (
    .a(a),
    .b(b),
    .product(mult_result)
);

adder add_inst (
    .a(a),
    .b(b),
    .sub(sub),
    .sum(add_result)
);

functional_module func_inst (
    .mult_input(mult_result),
    .add_input(add_result),
    .xor_output(xor_result)
);

assign mult_output = mult_result;
assign sum_output = add_result;
assign xor_output = xor_result[0];

endmodule

module multiplier (
    input [15:0] a,
    input [15:0] b,
    output [31:0] product
);

integer i;
reg [31:0] temp_product;

always @(*) begin
    temp_product = 0;
    for (i = 0; i < 16; i = i + 1) begin
        if (b[i]) begin
            temp_product = temp_product + (a << i);
        end
    end
end

assign product = temp_product;

endmodule

module adder (
    input [15:0] a,
    input [15:0] b,
    input sub,
    output [15:0] sum
);

wire [15:0] b_xor;

assign b_xor = sub ? b ^ 16'hFFFF : b;

adder16 add_inst (
    .a(a),
    .b(b_xor),
    .sum(sum)
);

endmodule

module adder16 (
    input [15:0] a,
    input [15:0] b,
    output [15:0] sum
);

assign sum = a + b;

endmodule

module functional_module (
    input [31:0] mult_input,
    input [15:0] add_input,
    output [31:0] xor_output
);

assign xor_output = mult_input ^ {16'b0, add_input};

endmodule

module ones_complement (
    input [7:0] in,
    output reg [7:0] out
);

reg [7:0] stage1_out;
reg [7:0] stage2_out;

// Stage 1: Invert the input using a constant value generator
always @(*) begin
    stage1_out = ~in;
end

// Stage 2: Add the inverted input to the original input
always @(posedge clk) begin
    stage2_out <= stage1_out + in;
end

// Output the result
assign out = stage2_out;

endmodule

module xnor_pipeline(
    input a,
    input b,
    output out
);

    // Pipeline registers
    reg p1, p2, p3, p4;

    // Stage 1
    assign p1 = ~(a & b);

    // Stage 2
    assign p2 = ~(p1 & p1);

    // Stage 3
    assign p3 = ~(p2 & p2);

    // Stage 4
    assign p4 = ~(p3 & p3);

    // Output
    assign out = ~(p4 & p4);

endmodule

module SSCG (
  input ref_clk,
  input [7:0] mod_rate,
  input rst,
  output reg ssc_clk
);

  reg [7:0] lfsr;
  reg [7:0] seed = 8'hFF; // unique seed value for each instance
  reg [7:0] mod_counter = 0;

  always @(posedge ref_clk or posedge rst) begin
    if (rst) begin
      lfsr <= seed;
      mod_counter <= 0;
      ssc_clk <= 1'b0;
    end else begin
      lfsr <= {lfsr[6:0], lfsr[7]^lfsr[2]^lfsr[1]^lfsr[0]};
      mod_counter <= mod_counter + 1;
      if (mod_counter == mod_rate) begin
        ssc_clk <= ~ssc_clk;
        mod_counter <= 0;
      end
    end
  end

endmodule

module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    output [4:0] C
);

wire [3:0] sum;
wire carry_out;

assign sum = A + B;
assign carry_out = (sum[3] & A[3]) | (sum[3] & B[3]) | (A[3] & B[3]);

assign C[3:0] = sum;
assign C[4] = carry_out;

endmodule

module sync_reset_counter(
    input clk,
    input rst,
    output reg [3:0] count
);

always @(posedge clk or negedge rst) begin
    if(!rst) begin
        count <= 4'b0;
    end else begin
        count <= count + 1;
    end
end

endmodule

module single_module (T, C, E, Q);
	input T, C, E;
	output wire Q;

	wire xorout;

	assign xorout = T ^ Q;

	always @ (posedge C) begin
		if (E) begin
			Q <= xorout;
		end
	end
endmodule

module counter (
    input clk,
    input rst,
    input en,
    input up,
    output reg [3:0] count
);

reg [3:0] count_reg1, count_reg2;

always @(posedge clk) begin
    if (rst) begin
        count_reg1 <= 4'b0;
        count_reg2 <= 4'b0;
    end
    else if (en) begin
        count_reg1 <= up ? count_reg2 + 4'b1 : count_reg2 - 4'b1;
        count_reg2 <= count_reg1;
    end
end

assign count = count_reg2;

endmodule

module arithmetic_operations (
  input [7:0] input1,
  input [7:0] input2,
  output reg [15:0] add_output,
  output reg [15:0] sub_output,
  output reg [15:0] mul_output
);

  always @ (input1 or input2) begin
    add_output <= input1 + input2;
    sub_output <= input1 - input2;
    mul_output <= input1 * input2;
  end

endmodule

module d_ff_scd_sce (
