module cart (
  input              clk_in,           // system clock signal

  // Mapper config data.
  input       [39:0] cfg_in,           // cartridge config (from iNES header)
  input              cfg_upd_in,       // pulse signal on cfg_in update

  // PRG-ROM interface.
  input              prg_nce_in,       // prg-rom chip enable (active low)
  input       [14:0] prg_a_in,         // prg-rom address
  input              prg_r_nw_in,      // prg-rom read/write select
  input       [ 7:0] prg_d_in,         // prg-rom data in
  output reg  [ 7:0] prg_d_out,        // prg-rom data out

  // CHR-ROM interface.
  input       [13:0] chr_a_in,         // chr-rom address
  input              chr_r_nw_in,      // chr-rom read/write select
  input       [ 7:0] chr_d_in,         // chr-rom data in
  output reg  [ 7:0] chr_d_out,        // chr-rom data out
  output reg         ciram_nce_out,    // vram chip enable (active low)
  output reg         ciram_a10_out     // vram a10 value (controls mirroring)
);

reg        prgrom_bram_we;
reg [14:0] prgrom_bram_a;
reg [7:0]  prgrom_bram_dout;

// Block ram instance for PRG-ROM memory range (0x8000 - 0xFFFF).  Will eventually be
// replaced with SRAM.
single_port_ram_sync #(
  .ADDR_WIDTH   (15                   ),
  .DATA_WIDTH   (8                    ))
prgrom_bram     (
  .clk          (clk_in               ),
  .we           (prgrom_bram_we       ),
  .addr_a       (prgrom_bram_a        ),
  .din_a        (prg_d_in             ),
  .dout_a       (prgrom_bram_dout     )
);

always @(posedge clk_in) begin
    if (~prg_nce_in) begin
        if (~prg_r_nw_in) begin
            prg_d_out <= prgrom_bram_dout;
        end else begin
            prgrom_bram_dout <= prg_d_in;
        end
        prgrom_bram_we <= ~prg_r_nw_in;
        prgrom_bram_a <= (cfg_in[33]) ? prg_a_in[14:0] : { 1'b0, prg_a_in[13:0] };
    end else begin
        prg_d_out <= 8'h00;
    end
end

reg       chrrom_pat_bram_we;
reg [7:0] chrrom_pat_bram_dout;

// Block ram instance for "CHR Pattern Table" memory range (0x0000 - 0x1FFF).
single_port_ram_sync #(
  .ADDR_WIDTH   (13                   ),
  .DATA_WIDTH   (8                    ))
chrrom_pat_bram (
  .clk          (clk_in               ),
  .we           (chrrom_pat_bram_we   ),
  .addr_a       (chr_a_in[12:0]       ),
  .din_a        (chr_d_in             ),
  .dout_a       (chrrom_pat_bram_dout )
);

always @(posedge clk_in) begin
    ciram_nce_out <= ~chr_a_in[13];
    ciram_a10_out <= (cfg_in[16]) ? chr_a_in[10] : chr_a_in[11];
    if (ciram_nce_out) begin
        if (~chr_r_nw_in) begin
            chr_d_out <= chrrom_pat_bram_dout;
        end else begin
            chrrom_pat_bram_dout <= chr_d_in;
        end
        chrrom_pat_bram_we <= ~chr_r_nw_in;
    end else begin
        chr_d_out <= 8'h00;
    end
end

endmodule

