module dual_edge_ff (
    input d,
    input clk,
    output reg q
);

reg q_ff;

always @ (posedge clk, negedge clk) begin
    if (~clk) begin
        q_ff <= d;
    end else begin
        q_ff <= q_ff;
    end
end

assign q = q_ff;

endmodule

