module timer(
    input clk,
    input rst,
    input start,
    input load,
    input [31:0] value,
    output reg done,
    output reg [31:0] out
);

// Instantiate the check_10us module to set the time unit and time precision
check_10us check_10us_inst();

// Define the internal signals
reg [31:0] count;
reg [31:0] load_value;
reg [1:0] state;

// Define the states
parameter IDLE = 2'b00;
parameter COUNTING = 2'b01;
parameter LOADING = 2'b10;

// Initialize the signals and state
initial begin
    count = value;
    load_value = value;
    state = IDLE;
    done = 0;
    out = count;
end

// Define the state machine
always @(posedge clk, posedge rst) begin
    if (rst) begin
        count <= value;
        load_value <= value;
        state <= IDLE;
        done <= 0;
        out <= count;
    end else begin
        case (state)
            IDLE: begin
                if (load) begin
                    load_value <= value;
                    state <= LOADING;
                end else if (start) begin
                    count <= value;
                    state <= COUNTING;
                end
            end
            COUNTING: begin
                if (count == 0) begin
                    done <= 1;
                    state <= IDLE;
                end else begin
                    count <= count - 1;
                    out <= count;
                end
            end
            LOADING: begin
                count <= load_value;
                state <= IDLE;
            end
        endcase
    end
end

endmodule

module PWM (
  input clk, // clock signal
  input [7:0] ctrl, // control signal
  output reg pwm // pulse signal with variable duty cycle
);

parameter freq = 50000000; // frequency of the clock signal
parameter res = 8; // resolution of the PWM signal
parameter max_duty = 100; // maximum duty cycle of the PWM signal

reg [res-1:0] counter;
reg [7:0] duty_cycle;

always @(posedge clk) begin
  if (counter == 0) begin
    pwm <= 1;
    counter <= res-1;
  end else begin
    if (counter == duty_cycle) begin
      pwm <= 0;
    end
    counter <= counter - 1;
  end
end

always @(posedge clk) begin
  duty_cycle <= (ctrl * max_duty) / 255;
end

endmodule

module mux_32bit (
    aclr,
    address_a,
    address_b,
    rden_a,
    rden_b,
    data_a,
    data_b
);

input aclr;
input [1:0] address_a;
input [1:0] address_b;
input rden_a;
input rden_b;
output reg [31:0] data_a;
output reg [31:0] data_b;

always @ (posedge aclr or posedge rden_a or posedge rden_b or posedge address_a or posedge address_b) begin
    if (aclr) begin
        data_a <= 0;
        data_b <= 0;
    end else if (rden_a) begin
        case (address_a)
            2'b00: data_a <= 32'h00000001;
            2'b01: data_a <= 32'h00000010;
            2'b10: data_a <= 32'h00000100;
            2'b11: data_a <= 32'h00001000;
            default: data_a <= 0;
        endcase
    end else if (rden_b) begin
        case (address_b)
            2'b00: data_b <= 32'h00010000;
            2'b01: data_b <= 32'h00100000;
            2'b10: data_b <= 32'h01000000;
            2'b11: data_b <= 32'h10000000;
            default: data_b <= 0;
        endcase
    end
end

endmodule

