module alu_4bit (
    input [3:0] A,
    input [3:0] B,
    input [2:0] opcode,
    output [3:0] out,
    output zero
);

reg [3:0] result;

always @(*) begin
    case (opcode)
        3'b000: result = A + B;
        3'b001: result = A - B;
        3'b010: result = A & B;
        3'b011: result = A | B;
        3'b100: result = A ^ B;
        default: result = 4'b0000;
    endcase
end

assign out = result;
assign zero = (result == 4'b0000);

endmodule

