module rising_edge_detector (
    input clk, // Clock input
    input reset, // Active high synchronous reset
    input in, // Input bit
    output reg out // Output bit
);

reg prev_in;

always @(posedge clk) begin
    if (reset) begin
        out <= 1'b0;
        prev_in <= 1'b0;
    end else begin
        if (in && !prev_in) begin
            out <= 1'b1;
        end else begin
            out <= 1'b0;
        end
        prev_in <= in;
    end
end

endmodule

