module BasicVendingMachine(
	input [2:0] KeyPad,
	input [1:0] Mode,
	input CLK,
	input RESET,
	output reg [7:0] Credit,
	output reg [5:0] Coins
);

	reg [7:0] credit_reg;
	reg [5:0] coins_reg;
	reg [2:0] product_price;

	initial begin
		credit_reg = 0;
		coins_reg = 0;
		product_price[0] = 10;
		product_price[1] = 13;
		product_price[2] = 15;
		product_price[3] = 20;
		product_price[4] = 25;
		product_price[5] = 30;
		product_price[6] = 75;
	end

	always @(posedge CLK) begin
		if (RESET) begin
			credit_reg <= 0;
			coins_reg <= 0;
		end
		else begin
			case (Mode)
				2'b00: // DO-NOTHING MODE
					begin
						// do nothing
					end
				2'b01: // MONEY-DEPOSIT MODE
					begin
						case (KeyPad)
							3'b001: // 2TL
								begin
									credit_reg <= credit_reg + 2;
								end
							3'b010: // 5TL
								begin
									credit_reg <= credit_reg + 5;
								end
							3'b011: // 10TL
								begin
									credit_reg <= credit_reg + 10;
								end
							3'b100: // 20TL
								begin
									credit_reg <= credit_reg + 20;
								end
							3'b101: // 50TL
								begin
									credit_reg <= credit_reg + 50;
								end
							3'b110: // 100TL
								begin
									credit_reg <= credit_reg + 100;
								end
							3'b111: // 200TL
								begin
									credit_reg <= credit_reg + 200;
								end
						endcase
					end
				2'b10: // PRODUCT-RECEIVE MODE
					begin
						case (KeyPad)
							3'b001: // Cola
								begin
									if (credit_reg >= product_price[0]) begin
										credit_reg <= credit_reg - product_price[0];
										coins_reg <= coins_reg + 2'b10;
									end
								end
							3'b010: // Water
								begin
									if (credit_reg >= product_price[1]) begin
										credit_reg <= credit_reg - product_price[1];
										coins_reg <= coins_reg + 2'b10;
									end
								end
							3'b011: // Chips
								begin
									if (credit_reg >= product_price[2]) begin
										credit_reg <= credit_reg - product_price[2];
										coins_reg <= coins_reg + 2'b10;
									end
								end
							3'b100: // Chocolate
								begin
									if (credit_reg >= product_price[3]) begin
										credit_reg <= credit_reg - product_price[3];
										coins_reg <= coins_reg + 2'b10;
									end
								end
							3'b101: // Sandwich
								begin
									if (credit_reg >= product_price[4]) begin
										credit_reg <= credit_reg - product_price[4];
										coins_reg <= coins_reg + 2'b10;
									end
								end
							3'b110: // Candy
								begin
									if (credit_reg >= product_price[5]) begin
										credit_reg <= credit_reg - product_price[5];
										coins_reg <= coins_reg + 2'b10;
									end
								end
							3'b111: // Cracker
								begin
									if (credit_reg >= product_price[6]) begin
										credit_reg <= credit_reg - product_price[6];
										coins_reg <= coins_reg + 2'b10;
									end
								end
						endcase
					end
				2'b11: // RETURN-REMAINDER MODE
					begin
						if (credit_reg > 0) begin
							if (credit_reg >= 10) begin
								credit_reg <= credit_reg - 10;
								coins_reg <= coins_reg + 2'b1000;
							end
							else if (credit_reg >= 5) begin
								credit_reg <= credit_reg - 5;
								coins_reg <= coins_reg + 2'b100;
							end
							else if (credit_reg >= 2) begin
								credit_reg <= credit_reg - 2;
								coins_reg <= coins_reg + 2'b10;
							end
						end
					end
			endcase
		end
	end

	assign Credit = credit_reg;
	assign Coins = coins_reg;

endmodule

module pc_reg(
  input wire clk,
  input wire rst,
  input wire [5:0] stall,
  input wire flush,
  input wire [31:0] new_pc,
  input wire branch_flag_i,
  input wire [31:0] branch_target_address_i,
  output reg [31:0] pc,
  output reg ce
);

  // Registers to store the pipeline stage values
  reg [31:0] pc_reg;
  reg [31:0] pc_next;

  // Combinational logic to compute the next value of the PC register
  always @(*) begin
    if (flush) begin
      pc_next = new_pc;
    end else if (stall[0] == 0) begin
      if (branch_flag_i) begin
        pc_next = branch_target_address_i;
      end else begin
        pc_next = pc_reg + 4;
      end
    end else begin
      pc_next = pc_reg;
    end
  end

  // Registers to store the control signals
  reg ce_reg;
  reg ce_next;

  // Sequential logic to update the PC register and control signals
  always @(posedge clk) begin
    if (rst) begin
      pc_reg <= 0;
      ce_reg <= 0;
    end else begin
      pc_reg <= pc_next;
      ce_reg <= ce_next;
    end
  end

  // Combinational logic to compute the next value of the control signals
  always @(*) begin
    ce_next = (stall == 0) ? 1 : 0;
  end

  // Assign outputs
  assign pc = pc_reg;
  assign ce = ce_reg;

endmodule

