module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input select,     // Select input to choose between multiplexers
    input [3:0] a,    // 4-bit input for the first multiplexer
    input [3:0] b,    // 4-bit input for the first multiplexer
    input [3:0] c,    // 4-bit input for the second multiplexer
    input [3:0] d,    // 4-bit input for the second multiplexer
    output [3:0] out  // 4-bit output from the functional module
);

reg [3:0] mux1_out, mux2_out, diff_out;

// First multiplexer
mux4 mux1 (
    .a(a),
    .b(b),
    .s(select),
    .y(mux1_out)
);

// Second multiplexer
mux4 mux2 (
    .a(c),
    .b(d),
    .s(select),
    .y(mux2_out)
);

// Calculate difference between inputs selected by second multiplexer
always @ (posedge clk) begin
    if (reset) begin
        diff_out <= 4'b0;
    end else begin
        case (select)
            1'b0: diff_out <= c - d;
            1'b1: diff_out <= d - c;
        endcase
    end
end

// Add outputs of both multiplexers and the difference
always @ (posedge clk) begin
    if (reset) begin
        out <= 4'b0;
    end else begin
        out <= mux1_out + mux2_out + diff_out;
    end
end

endmodule

// 4-to-1 multiplexer
module mux4 (
    input [3:0] a,
    input [3:0] b,
    input s,
    output reg [3:0] y
);

always @ (a, b, s) begin
    case (s)
        2'b00: y <= a;
        2'b01: y <= b;
        2'b10: y <= 4'b0;
        2'b11: y <= 4'b1;
    endcase
end

endmodule

module debounce_module (sda_i, s_axi_aclk, scndry_out, detect_stop_b_reg);
