module bit_rotator_pipeline(
    input clk,
    input load,
    input [1:0] ena,
    input [99:0] data,
    output reg [99:0] q);

    reg [99:0] reg1, reg2, reg3;

    always @(posedge clk) begin
        if (load) begin
            reg1 <= data;
            reg2 <= reg1;
            reg3 <= reg2;
        end else begin
            case (ena)
                2'b00: begin
                    reg1 <= {reg1[98:0], reg1[99]};
                    reg2 <= {reg2[98:0], reg2[99]};
                    reg3 <= {reg3[98:0], reg3[99]};
                end
                2'b01: begin
                    reg1 <= {reg1[99], reg1[0:98]};
                    reg2 <= {reg2[99], reg2[0:98]};
                    reg3 <= {reg3[99], reg3[0:98]};
                end
                2'b10: begin
                    reg1 <= {reg1[1:99], reg1[0]};
                    reg2 <= {reg2[1:99], reg2[0]};
                    reg3 <= {reg3[1:99], reg3[0]};
                end
                2'b11: begin
                    reg1 <= {reg1[0], reg1[99:1]};
                    reg2 <= {reg2[0], reg2[99:1]};
                    reg3 <= {reg3[0], reg3[99:1]};
                end
            endcase
        end
    end

    assign q = reg3;

endmodule

module sd_controller (
  input clk,
  input rst,
  input [47:0] cmd,
  input [511:0] dat_i,
  input dat_o_en,
  input dat_o_rd,
  output [511:0] dat_o,
  output cmd_busy
);

  // Define states
  parameter IDLE_STATE = 2'b00;
  parameter SEND_IF_COND_STATE = 2'b01;
  parameter READ_SINGLE_BLOCK_STATE = 2'b10;
  parameter WRITE_SINGLE_BLOCK_STATE = 2'b11;

  // Define command codes
  parameter CMD0 = 6'b000000;
  parameter CMD8 = 6'b000010;
  parameter CMD17 = 6'b010001;
  parameter CMD24 = 6'b011000;

  // Define internal signals
  reg [1:0] state;
  reg [47:0] cmd_reg;
  reg [511:0] dat_o_reg;
  reg cmd_busy_reg;
  reg dat_o_en_reg;
  reg dat_o_rd_reg;
  reg [7:0] crc_reg;

  // Define constants
  parameter CMD_RESP_TIMEOUT = 100;
  parameter DATA_RESP_TIMEOUT = 100;

  // Define state machine
  always @(posedge clk) begin
    if (rst) begin
      state <= IDLE_STATE;
      cmd_reg <= 0;
      dat_o_reg <= 0;
      cmd_busy_reg <= 0;
      dat_o_en_reg <= 0;
      dat_o_rd_reg <= 0;
      crc_reg <= 0;
    end else begin
      case (state)
        IDLE_STATE: begin
          if (cmd != CMD0) begin
            state <= SEND_IF_COND_STATE;
          end
        end
        SEND_IF_COND_STATE: begin
          if (cmd == CMD8) begin
            state <= READ_SINGLE_BLOCK_STATE;
          end
        end
        READ_SINGLE_BLOCK_STATE: begin
          if (cmd == CMD24) begin
            state <= WRITE_SINGLE_BLOCK_STATE;
          end
        end
        WRITE_SINGLE_BLOCK_STATE: begin
          state <= IDLE_STATE;
        end
      endcase
    end
  end

  // Define command response logic
  always @(posedge clk) begin
    if (rst) begin
      cmd_busy_reg <= 0;
    end else begin
      case (state)
        IDLE_STATE: begin
          cmd_busy_reg <= 0;
        end
        SEND_IF_COND_STATE: begin
          cmd_busy_reg <= 1;
          // Wait for response
          #CMD_RESP_TIMEOUT;
          cmd_busy_reg <= 0;
        end
        READ_SINGLE_BLOCK_STATE: begin
          cmd_busy_reg <= 1;
          // Wait for response
          #CMD_RESP_TIMEOUT;
          cmd_busy_reg <= 0;
        end
        WRITE_SINGLE_BLOCK_STATE: begin
          cmd_busy_reg <= 1;
          // Wait for response
          #CMD_RESP_TIMEOUT;
          cmd_busy_reg <= 0;
        end
      endcase
    end
  end

  // Define data response logic
  always @(posedge clk) begin
    if (rst) begin
      dat_o_en_reg <= 0;
      dat_o_rd_reg <= 0;
    end else begin
      case (state)
        IDLE_STATE: begin
          dat_o_en_reg <= 0;
          dat_o_rd_reg <= 0;
        end
        SEND_IF_COND_STATE: begin
          dat_o_en_reg <= 0;
          dat_o_rd_reg <= 0;
        end
        READ_SINGLE_BLOCK_STATE: begin
          dat_o_en_reg <= 1;
          dat_o_rd_reg <= 1;
          // Wait for response
          #DATA_RESP_TIMEOUT;
          dat_o_en_reg <= 0;
          dat_o_rd_reg <= 0;
        end
        WRITE_SINGLE_BLOCK_STATE: begin
          dat_o_en_reg <= 1;
          dat_o_rd_reg <= 0;
          // Wait for response
          #DATA_RESP_TIMEOUT;
          dat_o_en_reg <= 0;
          dat_o_rd_reg <= 0;
        end
      endcase
    end
  end

  // Define output logic
  assign dat_o = dat_o_reg;
  assign cmd_busy = cmd_busy_reg;

  // Define command and data register logic
  always @(posedge clk) begin
    if (rst) begin
      cmd_reg <= 0;
      dat_o_reg <= 0;
      crc_reg <= 0;
    end else begin
      if (cmd_busy_reg) begin
        // Handle command response
        case (state)
          SEND_IF_COND_STATE: begin
            // Send response
            cmd_reg <= {8'h01, 8'haa, 8'h87, 8'h00, 8'h00, 8'h01, 8'h00, 8'h7f};
          end
          READ_SINGLE_BLOCK_STATE: begin
            // Read data
            dat_o_reg <= dat_i;
          end
          WRITE_SINGLE_BLOCK_STATE: begin
            // Write data
            dat_o_reg <= dat_i;
          end
        endcase
      end else begin
        // Handle command and data transfer
        case (state)
          IDLE_STATE: begin
            cmd_reg <= cmd;
          end
          SEND_IF_COND_STATE: begin
            cmd_reg <= {CMD8, 8'h00, 8'h00, 8'h01, 8'haa, 8'h87};
          end
          READ_SINGLE_BLOCK_STATE: begin
            cmd_reg <= {CMD17, cmd[31:0], 8'h00, 8'h00, 8'h00, 8'h00, 8'h01, 8'h00};
          end
          WRITE_SINGLE_BLOCK_STATE: begin
            cmd_reg <= {CMD24, cmd[31:0], 8'h00, 8'h00, 8'h00, 8'h00, 8'h01, 8'h00};
            dat_o_reg <= dat_i;
          end
        endcase
      end
    end
  end

endmodule

module mem_interface(
    input clock,
    input reset,
    input [13:0] pixCellIx,
    output reg [31:0] cellData,
    input [15:0] fontGlyph,
    output reg [63:0] fontData,
    input [31:0] busAddr,
    inout [31:0] busData,
    input busOE,
    input busWR,
    output reg busOK
);

reg [13:0] tPixCellIx;
reg [15:0] tFontGlyph;
reg [31:0] tBusData;
reg [63:0] tFontData1;
reg [63:0] tFontData2;
reg [31:0] scrRegCtrl[7:0];
reg [31:0] tCell1;
reg [31:0] tNextCell1;
reg [63:0] fontMem[255:0];
reg [63:0] fontGfx1Mem[127:0];
reg [63:0] fontGfx2Mem[127:0];
reg [31:0] scrCell1[0:1023];
wire tBusCSel;

assign fontData = tFontData1;
assign busData = (busOE && tBusCSel) ? tBusData : 32'hZZZZ_ZZZZ;
assign busOK = (busOE && tBusCSel) ? busOK : 1'bZ;

always @(posedge clock) begin
    if (reset) begin
        tPixCellIx <= 0;
        tFontGlyph <= 0;
        tCell1 <= 0;
        tNextCell1 <= 0;
        tFontData1 <= 0;
        tFontData2 <= 0;
        busOK <= 0;
        tBusData <= 0;
    end else begin
        tPixCellIx <= pixCellIx;
        tFontGlyph <= fontGlyph;
        tCell1 <= scrCell1[tPixCellIx[9:0]];
        tNextCell1 <= tCell1;
        tFontData1 <= tFontData2;
        if (tBusCSel && busOE) begin
            tPixCellIx <= busAddr[15:2];
            if (busAddr[15:8] == 8'hFF) begin
                busOK <= 1;
                case (busAddr[6:2])
                    0: tBusData = scrRegCtrl[0];
                    1: tBusData = scrRegCtrl[1];
                    2: tBusData = scrRegCtrl[2];
                    3: tBusData = scrRegCtrl[3];
                    4: tBusData = scrRegCtrl[4];
                    5: tBusData = scrRegCtrl[5];
                    6: tBusData = scrRegCtrl[6];
                    7: tBusData = scrRegCtrl[7];
                    8: tBusData = {18'h0, pixCellIx};
                    default: tBusData = 0;
                endcase
            end else begin
                tBusData <= tCell1;
                busOK <= (tPixCellIx == busAddr[15:2]);
            end
        end
        if (tBusCSel && busWR && !busOE) begin
            if (busAddr[15:8] == 8'hFF) begin
                scrRegCtrl[busAddr[4:2]] <= busData;
            end else begin
                scrCell1[busAddr[11:2]] <= busData;
            end
        end
    end
end

always @(*) begin
    tBusCSel = (busAddr[31:16] == 16'h0080);
    tFontData2 = fontMem[tFontGlyph[7:0]];
    case (tFontGlyph[9:7])
        3'b000: tFontData2 = tFontData2;
        3'b001: tFontData2 = tFontData2;
        3'b010: tFontData2 = fontGfx2Mem[tFontGlyph[6:0]];
        3'b011: tFontData2 = fontGfx1Mem[tFontGlyph[6:0]];
        default: tFontData2 = tFontData2;
    endcase
end

initial begin
    $readmemh("fontmem.txt", fontMem);
    $readmemh("gfxfont0.txt", fontGfx1Mem);
    $readmemh("gfxfont1.txt", fontGfx2Mem);
    $readmemh("scrmem.txt", scrCell1);
end

endmodule

module mealy_sm (
  input clk,
  input reset,
  input i,
  input j,
  input k,
  output reg out1,
  output reg out2
);

  // Define state types
  parameter IDLE = 2'b00;
  parameter STATE1 = 2'b01;
  parameter STATE2 = 2'b10;

  // Define state register and output registers
  reg [1:0] state, next_state;
  reg next_out1, next_out2;

  // Synchronous reset to IDLE
  always @(posedge clk) begin
    if (reset) begin
      state <= IDLE;
      out1 <= 0;
      out2 <= 0;
    end
    else begin
      state <= next_state;
      out1 <= next_out1;
      out2 <= next_out2;
    end
  end

  // Define next state and output logic
  always @(*) begin
    case (state)
      IDLE: begin
        if (i) begin
          next_state = STATE1;
          next_out1 = 0;
          next_out2 = 0;
        end
        else begin
          next_state = IDLE;
          next_out1 = 0;
          next_out2 = 0;
        end
      end
      STATE1: begin
        if (j) begin
          next_state = STATE2;
          next_out1 = 1;
          next_out2 = 0;
        end
        else begin
          next_state = STATE1;
          next_out1 = 1;
          next_out2 = 0;
        end
      end
      STATE2: begin
        if (k) begin
          next_state = IDLE;
          next_out1 = 0;
          next_out2 = 1;
        end
        else begin
          next_state = STATE2;
          next_out1 = 0;
          next_out2 = 1;
        end
      end
    endcase
  end

endmodule

