module top_module ( 
    input clk, 
    input reset,      // Synchronous active-high reset
    input a,          // Input signal to the first XOR gate
    input b,          // Input signal to the first XOR gate
    input c,          // Input signal to the second XOR gate
    input d,          // Input signal to the second XOR gate
    input control,    // Control signal for the tri-state buffer
    output reg [3:0] q // 4-bit output from the system
);

// XOR gates
xor_gate x1(.a(a), .b(b), .out(x1_out));
xor_gate x2(.a(c), .b(d), .out(x2_out));

// Tri-state buffer
assign tri_out = control ? 1'bz : (x1_out ^ x2_out);

// 4-bit counter
counter_4bit counter(.clk(clk), .reset(reset), .out(counter_out));

// Adder
assign q = tri_out + counter_out;

endmodule

