module xor_bit_count (
    input [15:0] a,
    input [15:0] b,
    output reg [7:0] out
);

wire [15:0] xor_out;
reg [15:0] shift_reg;
wire [15:0] cmp_out;
wire [3:0] adder_out;

// Instantiate XOR gate
xor_gate xor_inst (
    .a(a),
    .b(b),
    .out(xor_out)
);

// Shift register
always @ (posedge clk) begin
    shift_reg <= {shift_reg[14:0], xor_out};
end

// Comparator
comparator cmp_inst (
    .a(shift_reg),
    .b(16'h0001),
    .out(cmp_out)
);

// Adder
adder add_inst (
    .a(cmp_out),
    .b({cmp_out[0], cmp_out[1], cmp_out[2], cmp_out[3], cmp_out[4], cmp_out[5], cmp_out[6], cmp_out[7]}),
    .out(adder_out)
);

// Output
assign out = adder_out;

endmodule

