module multi_master_interface (
    read_request_o,
    addr_o,
    sel_o,
    dat_i,
    ack_i,
    m0_read_request_i,
    m0_addr_i,
    m0_sel_i,
    m0_dat_o,
    m0_ack_o,
    m1_read_request_i,
    m1_addr_i,
    m1_sel_i,
    m1_dat_o,
    m1_ack_o,
    m2_read_request_i,
    m2_addr_i,
    m2_sel_i,
    m2_dat_o,
    m2_ack_o
);

    input m0_read_request_i;
    input [31:0] m0_addr_i;
    input [3:0] m0_sel_i;
    output [31:0] m0_dat_o;
    output m0_ack_o;

    input m1_read_request_i;
    input [31:0] m1_addr_i;
    input [3:0] m1_sel_i;
    output [31:0] m1_dat_o;
    output m1_ack_o;

    input m2_read_request_i;
    input [31:0] m2_addr_i;
    input [3:0] m2_sel_i;
    output [31:0] m2_dat_o;
    output m2_ack_o;

    input [31:0] dat_i;
    input ack_i;
    output read_request_o;
    output [31:0] addr_o;
    output [3:0] sel_o;
    output [31:0] dat_o;
    output ack_o;

    reg read_request_o;
    reg [31:0] addr_o;
    reg [3:0] sel_o;
    reg [31:0] dat_o;
    reg ack_o;

    wire [31:0] mem [0:1023];

    // Master clip
    assign m0_dat_o = mem[m0_addr_i];
    always @(posedge m0_read_request_i) begin
        read_request_o <= 1'b1;
        addr_o <= m0_addr_i;
        sel_o <= m0_sel_i;
        dat_o <= mem[m0_addr_i];
        ack_o <= 1'b1;
        m0_ack_o <= 1'b1;
    end

    // Fragment processor
    assign m1_dat_o = mem[m1_addr_i];
    always @(posedge m1_read_request_i) begin
        read_request_o <= 1'b1;
        addr_o <= m1_addr_i;
        sel_o <= m1_sel_i;
        dat_o <= mem[m1_addr_i];
        ack_o <= 1'b1;
        m1_ack_o <= 1'b1;
    end

    // Blender
    assign m2_dat_o = mem[m2_addr_i];
    always @(posedge m2_read_request_i) begin
        read_request_o <= 1'b1;
        addr_o <= m2_addr_i;
        sel_o <= m2_sel_i;
        dat_o <= mem[m2_addr_i];
        ack_o <= 1'b1;
        m2_ack_o <= 1'b1;
    end

    // Slave device
    always @(posedge read_request_o) begin
        addr_o <= addr_o;
        sel_o <= sel_o;
        dat_o <= mem[addr_o];
        ack_o <= 1'b1;
    end

    always @(posedge ack_i) begin
        mem[addr_o] <= dat_i;
        read_request_o <= 1'b0;
        addr_o <= 0;
        sel_o <= 0;
        dat_o <= 0;
        ack_o <= 0;
    end

endmodule

