module edge_detection (
    input clk,
    input reset,
    input [3:0] data,
    output reg rising_edge,
    output reg falling_edge
);

reg [3:0] prev_data;
reg [15:0] counter;

always @(posedge clk) begin
    if (reset) begin
        prev_data <= 0;
        counter <= 0;
        rising_edge <= 0;
        falling_edge <= 0;
    end else begin
        if (data > prev_data) begin
            counter <= counter + 1;
            if (counter == 2) begin
                rising_edge <= 1;
                counter <= 0;
            end
        end else if (data < prev_data) begin
            counter <= counter + 1;
            if (counter == 2) begin
                falling_edge <= 1;
                counter <= 0;
            end
        end else begin
            counter <= 0;
        end
        prev_data <= data;
    end
end

endmodule

