module data_control (
    output Q,
    input CLK_N,
    input D,
    input SCD,
    input SCE,
    input RESET_B
);

    reg [1:0] state;
    reg [1:0] next_state;
    reg stored_data;
    assign Q = stored_data;

    always @(posedge CLK_N) begin
        state <= next_state;
    end

    always @(*) begin
        case (state)
            2'b00: begin // reset state
                next_state = 2'b00;
                stored_data = 1'b0;
            end
            2'b01: begin // pass through state
                next_state = 2'b01;
                stored_data = D;
            end
            2'b10: begin // store state
                next_state = 2'b10;
                stored_data = stored_data;
            end
            2'b11: begin // output state
                next_state = 2'b11;
                stored_data = stored_data;
            end
            default: begin
                next_state = 2'b00;
                stored_data = 1'b0;
            end
        endcase
    end

    always @(*) begin
        case (state)
            2'b00: begin // reset state
                if (!RESET_B) begin
                    next_state = 2'b00;
                end
                else if (SCD) begin
                    next_state = 2'b10;
                end
                else begin
                    next_state = 2'b01;
                end
            end
            2'b01: begin // pass through state
                if (!RESET_B) begin
                    next_state = 2'b00;
                end
                else if (SCD) begin
                    next_state = 2'b10;
                end
                else begin
                    next_state = 2'b01;
                end
            end
            2'b10: begin // store state
                if (!RESET_B) begin
                    next_state = 2'b00;
                end
                else if (!SCD) begin
                    next_state = 2'b01;
                end
                else begin
                    next_state = 2'b10;
                end
            end
            2'b11: begin // output state
                if (!RESET_B) begin
                    next_state = 2'b00;
                end
                else if (!SCE) begin
                    next_state = 2'b01;
                end
                else begin
                    next_state = 2'b11;
                end
            end
            default: begin
                next_state = 2'b00;
            end
        endcase
    end

endmodule

module ps2_kb_to_host (
    input wire clk,          // se recomienda 1 MHz <= clk <= 600 MHz
    input wire ps2clk_ext,
    input wire ps2data_ext,
    output wire [7:0] data,
    output wire busy,
    output wire error
    );

    // States for the state machine
    parameter IDLE = 2'b00, START = 2'b01, DATA = 2'b10, PARITY = 2'b11;

    // Internal signals
    reg [2:0] state;
    reg [7:0] shiftreg;
    reg [2:0] cntbits;
    reg [7:0] rdata;
    wire paritycalculated;
    reg [15:0] timeoutcnt;

    // Outputs
    assign busy = (state != IDLE);
    assign error = (timeoutcnt == 16'hFFFF);
    assign data = rdata;

    // Synchronize PS2CLK and PS2DATA signals
    reg [1:0] ps2clk_synchr;
    reg [1:0] ps2dat_synchr;
    wire ps2clk = ps2clk_synchr[1];
    wire ps2data_in = ps2dat_synchr[1];
    always @(posedge clk) begin
        ps2clk_synchr[0] <= ps2clk_ext;
        ps2clk_synchr[1] <= ps2clk_synchr[0];
        ps2dat_synchr[0] <= ps2data_ext;
        ps2dat_synchr[1] <= ps2dat_synchr[0];
    end

    // Detect falling edges of PS2CLK
    reg [15:0] edgedetect = 16'h0000;
    always @(posedge clk) begin
        edgedetect <= {edgedetect[14:0], ps2clk};
    end
    wire ps2clknedge = (edgedetect == 16'hF000)? 1'b1 : 1'b0;

    // State machine for decoding PS/2 packets
    always @(posedge clk) begin
        if (ps2clknedge) begin
            case (state)
                IDLE: begin
                    if (~ps2data_in) begin
                        state <= START;
                        cntbits <= 0;
                        shiftreg <= ps2data_in;
                        timeoutcnt <= 0;
                    end
                end
                START: begin
                    shiftreg <= {shiftreg[6:0], ps2data_in};
                    cntbits <= cntbits + 1;
                    if (cntbits == 8) begin
                        state <= PARITY;
                        cntbits <= 0;
                        rdata <= shiftreg;
                    end
                end
                DATA: begin
                    shiftreg <= {shiftreg[6:0], ps2data_in};
                    cntbits <= cntbits + 1;
                    if (cntbits == 8) begin
                        state <= PARITY;
                        cntbits <= 0;
                        rdata <= shiftreg;
                    end
                end
                PARITY: begin
                    paritycalculated = ~(^rdata);
                    if (paritycalculated == ps2data_in) begin
                        state <= IDLE;
                        timeoutcnt <= 0;
                    end else begin
                        state <= START;
                        cntbits <= 0;
                        shiftreg <= ps2data_in;
                    end
                end
                default: begin
                    state <= IDLE;
                    timeoutcnt <= 0;
                end
            endcase
        end else begin
            timeoutcnt <= timeoutcnt + 1;
        end
    end

endmodule

module top_module (
    input clk,
    input reset,
    input [31:0] in,
    input select,
    output [31:0] out,
    output [0:0] high_input
);

    reg [31:0] reg_out;
    wire [31:0] shifted_in;
    wire [0:0] greater_than_100;

    // Register with active low synchronous reset
    always @(posedge clk, negedge reset) begin
        if (!reset) begin
            reg_out <= 0;
        end else begin
            reg_out <= select ? shifted_in : in;
        end
    end

    // Logical shift right by 4 bits
    assign shifted_in = in >> 4;

    // Check if input is greater than or equal to 100
    assign greater_than_100 = in >= 100;

    // Output
    assign out = reg_out;
    assign high_input = greater_than_100;

endmodule

