module crc (
  input [n-1:0] data_in,
  input [m-1:0] crc_in,
  output [m-1:0] crc_out,
  output error
);

parameter n = 8; // number of input data bits
parameter m = 4; // number of CRC bits
parameter poly = 4'h3; // CRC polynomial

reg [n+m-1:0] reg_crc;
reg [n-1:0] reg_data;
reg [m-1:0] reg_remainder;

integer i, j;

always @(posedge clk) begin
  // CRC generator
  reg_crc[n+m-1:0] = {reg_data, reg_remainder};
  for (i = 0; i < n; i = i + 1) begin
    if (reg_crc[i] == 1'b1) begin
      for (j = 0; j < m; j = j + 1) begin
        reg_crc[i+j] = reg_crc[i+j] ^ poly[j];
      end
    end
  end
  reg_remainder = reg_crc[n-1:0];

  // CRC checker
  reg_crc[n+m-1:0] = {data_in, crc_in};
  for (i = 0; i < n; i = i + 1) begin
    if (reg_crc[i] == 1'b1) begin
      for (j = 0; j < m; j = j + 1) begin
        reg_crc[i+j] = reg_crc[i+j] ^ poly[j];
      end
    end
  end
  if (reg_crc[n+m-1:0] == 0) begin
    error = 1'b0; // data is error-free
  end else begin
    error = 1'b1; // data contains errors
  end
end

assign crc_out = reg_remainder;

endmodule

