module shift_register (
    input clk,
    input areset,
    input load,
    input ena,
    input [3:0] data,
    output reg [3:0] q
);

reg [3:0] counter;

always @(posedge clk or negedge areset) begin
    if (areset == 0) begin
        q <= 0;
        counter <= 0;
    end
    else if (load) begin
        q <= data;
        counter <= 0;
    end
    else if (ena) begin
        if (counter == 3) begin
            q <= {q[2:0], 1'b0};
            counter <= 0;
        end
        else begin
            q <= {q[2:0], q[3]};
            counter <= counter + 1;
        end
    end
end

