module PLL_MODULE (
  input clk_in,
  input reset,
  input lock_enable,
  output reg clk_out_1,
  output reg clk_out_2,
  output reg locked
);

  parameter integer multiplier = 2; // Frequency multiplication factor for the output clock signals
  parameter integer lock_threshold = 5; // Threshold for the PLL to lock onto the input clock signal

  reg [31:0] phase_accumulator_1;
  reg [31:0] phase_accumulator_2;
  reg [31:0] phase_increment_1;
  reg [31:0] phase_increment_2;
  reg [31:0] phase_error_1;
  reg [31:0] phase_error_2;
  reg [31:0] phase_error_accumulator_1;
  reg [31:0] phase_error_accumulator_2;
  reg [31:0] phase_error_accumulator_threshold_1;
  reg [31:0] phase_error_accumulator_threshold_2;
  reg [31:0] phase_error_accumulator_increment_1;
  reg [31:0] phase_error_accumulator_increment_2;

  always @ (posedge clk_in or posedge reset) begin
    if (reset) begin
      phase_accumulator_1 <= 0;
      phase_accumulator_2 <= 0;
      phase_increment_1 <= 0;
      phase_increment_2 <= 0;
      phase_error_1 <= 0;
      phase_error_2 <= 0;
      phase_error_accumulator_1 <= 0;
      phase_error_accumulator_2 <= 0;
      phase_error_accumulator_threshold_1 <= 0;
      phase_error_accumulator_threshold_2 <= 0;
      phase_error_accumulator_increment_1 <= 0;
      phase_error_accumulator_increment_2 <= 0;
      clk_out_1 <= 0;
      clk_out_2 <= 0;
      locked <= 0;
    end else begin
      // Calculate phase error
      phase_error_1 <= phase_accumulator_1 - (phase_accumulator_2 * multiplier);
      phase_error_2 <= phase_accumulator_2 - (phase_accumulator_1 / multiplier);

      // Update phase error accumulators
      phase_error_accumulator_1 <= phase_error_accumulator_1 + phase_error_1;
      phase_error_accumulator_2 <= phase_error_accumulator_2 + phase_error_2;

      // Determine if phase error accumulator thresholds have been exceeded
      if (phase_error_accumulator_1 >= phase_error_accumulator_threshold_1) begin
        phase_error_accumulator_1 <= phase_error_accumulator_1 - phase_error_accumulator_threshold_1;
        phase_increment_1 <= phase_increment_1 + phase_error_accumulator_increment_1;
      end
      if (phase_error_accumulator_2 >= phase_error_accumulator_threshold_2) begin
        phase_error_accumulator_2 <= phase_error_accumulator_2 - phase_error_accumulator_threshold_2;
        phase_increment_2 <= phase_increment_2 + phase_error_accumulator_increment_2;
      end

      // Update phase accumulators
      phase_accumulator_1 <= phase_accumulator_1 + phase_increment_1;
      phase_accumulator_2 <= phase_accumulator_2 + phase_increment_2;

      // Generate output clock signals
      if (phase_accumulator_1 >= (1 << 31)) begin
        clk_out_1 <= ~clk_out_1;
        phase_accumulator_1 <= phase_accumulator_1 - (1 << 31);
      end
      if (phase_accumulator_2 >= (1 << 31)) begin
        clk_out_2 <= ~clk_out_2;
        phase_accumulator_2 <= phase_accumulator_2 - (1 << 31);
      end

      // Determine if PLL has locked onto input clock signal
      if (lock_enable) begin
        if (abs(phase_error_1) < lock_threshold && abs(phase_error_2) < lock_threshold) begin
          locked <= 1;
        end else begin
          locked <= 0;
        end
      end
    end
  end

endmodule

module sync_module (
    input clk1,
    input rst1,
    input data1,
    input valid1,
    output reg ready1,
    input clk2,
    input rst2,
    output reg data2,
    output reg valid2,
    input ready2
);

reg [1:0] state;

always @(posedge clk1, posedge rst1) begin
    if (rst1) begin
        state <= 2'b0;
        ready1 <= 1'b0;
    end else begin
        case (state)
            2'b00: begin // wait for ready2
                if (ready2) begin
                    state <= 2'b01;
                    ready1 <= 1'b1;
                end
            end
            2'b01: begin // transfer data1 to data2
                data2 <= data1;
                valid2 <= valid1;
                state <= 2'b10;
            end
            2'b10: begin // wait for clk2
                if (clk2) begin
                    state <= 2'b00;
                    ready1 <= 1'b0;
                end
            end
        endcase
    end
end

always @(posedge clk2, posedge rst2) begin
    if (rst2) begin
        data2 <= 1'b0;
        valid2 <= 1'b0;
    end else begin
        if (valid2 && ready2) begin
            valid2 <= 1'b0;
        end else if (!valid2 && ready2) begin
            valid2 <= 1'b1;
        end
    end
end

endmodule

module LCB (
  input wire ain,
  input wire din,
  output wire aout,
  output wire dout
);

  // ADC module
  reg [9:0] adc_out;
  always @(ain) begin
    adc_out = ain * 1023;
  end

  // Debounce module
  reg [3:0] debounce_counter;
  reg debounced_din;
  always @(posedge din or negedge din) begin
    debounce_counter <= debounce_counter + 1;
    if (debounce_counter == 4'hF) begin
      debounce_counter <= 4'h0;
      debounced_din <= din;
    end
  end

  // Comparator module
  reg threshold = 512; // 50% of the maximum ADC value
  reg light_on;
  always @(adc_out) begin
    light_on = (adc_out > threshold) ? 1 : 0;
  end

  // PWM module
  reg [9:0] pwm_counter;
  reg pwm_out;
  always @(posedge light_on) begin
    pwm_counter <= pwm_counter + 1;
    pwm_out <= (pwm_counter < (adc_out * 9 / 10)) ? 1 : 0;
  end

  // Output connections
  assign aout = pwm_out;
  assign dout = light_on && debounced_din;

endmodule

