module top_module (
    input [3:0] A,
    input [3:0] B,
    input [1:0] SEL,
    output [15:0] OUT
);

    wire [15:0] decoder_out_A;
    wire [15:0] decoder_out_B;
    wire [2:0] comparator_out;
    wire [3:0] and_out;

    decoder_4to16 decoder_A (
        .in(A),
        .out(decoder_out_A)
    );

    decoder_4to16 decoder_B (
        .in(B),
        .out(decoder_out_B)
    );

    magnitude_comparator comparator (
        .A(A),
        .B(B),
        .less_than(comparator_out[0]),
        .equal_to(comparator_out[1]),
        .greater_than(comparator_out[2])
    );

    and_gate and (
        .A(A),
        .B(B),
        .out(and_out)
    );

    always @(*) begin
        case (SEL)
            2'b00: OUT = decoder_out_A | decoder_out_B;
            2'b01: OUT = decoder_out_B | decoder_out_A;
            2'b10: OUT = {comparator_out, 1'b0};
            2'b11: OUT = and_out ^ (A & B);
            default: OUT = 16'b0;
        endcase
    end

endmodule

module decoder_4to16 (
    input [3:0] in,
    output [15:0] out
);

    assign out = 16'b0;
    assign out[in] = 1'b1;

endmodule

module magnitude_comparator (
    input [3:0] A,
    input [3:0] B,
    output less_than,
    output equal_to,
    output greater_than
);

    assign less_than = (A < B);
    assign equal_to = (A == B);
    assign greater_than = (A > B);

endmodule

module and_gate (
    input [3:0] A,
