);

always @(*) begin
    case (sel)
        2'b00: out = in[0];
        2'b01: out = in[1];
        2'b10: out = in[2];
        2'b11: out = in[3];
    endcase
end

endmodule

module top_module(
    input [31:0] a,
    input [31:0] b,
    input sel,
    output [31:0] sum
);

wire [7:0] adder1_out;
wire [7:0] adder2_out;
wire [15:0] adder3_out;
wire [3:0] mux_out;

mux_3_4 mux_inst(
    .a(a[7]),
    .b(a[15]),
    .c(a[23]),
    .sel({sel, a[31]}),
    .y(mux_out)
);

add_8 adder1_inst(
    .a(a[0:7]),
    .b(b[0:7]),
    .sum(adder1_out)
);

add_8 adder2_inst(
    .a(a[8:15]),
    .b(b[8:15]),
    .sum(adder2_out)
);

add_16 adder3_inst(
    .a(a[16:31]),
    .b(b[16:31]),
    .sum(adder3_out)
);

assign sum = sel ? {mux_out, a[31]} + b : a + b;

endmodule

