module pixel_processing(clk, in_blank, in_hsync, in_vsync, in_red, in_green, in_blue, is_interlaced, is_second_field, audio_channel, audio_de, audio_sample, switches, out_blank, out_hsync, out_vsync, out_red, out_green, out_blue);
  input [2:0] audio_channel;
  input audio_de;
  input [23:0] audio_sample;
  input clk;
  input in_blank;
  input [7:0] in_blue;
  input [7:0] in_green;
  input in_hsync;
  input [7:0] in_red;
  input in_vsync;
  input is_interlaced;
  input is_second_field;
  output out_blank;
  output [7:0] out_blue;
  output [7:0] out_green;
  output out_hsync;
  output [7:0] out_red;
  output out_vsync;
  input [7:0] switches;

  reg [7:0] red_reg;
  reg [7:0] green_reg;
  reg [7:0] blue_reg;
  reg blank_reg;
  reg hsync_reg;
  reg vsync_reg;

  always @(posedge clk) begin
    if (in_blank) begin
      blank_reg <= 1;
      red_reg <= 8'h00;
      green_reg <= 8'h00;
      blue_reg <= 8'h00;
    end else begin
      blank_reg <= 0;
      red_reg <= in_red;
      green_reg <= in_green;
      blue_reg <= in_blue;
    end

    if (in_hsync) begin
      hsync_reg <= 1;
    end else begin
      hsync_reg <= 0;
    end

    if (in_vsync) begin
      vsync_reg <= 1;
    end else begin
      vsync_reg <= 0;
    end
  end

  assign out_blank = blank_reg;
  assign out_hsync = hsync_reg;
  assign out_vsync = vsync_reg;

  always @(posedge clk) begin
    if (audio_de) begin
      case (audio_channel)
        3'b001: out_blue <= audio_sample[23:16];
        3'b010: out_green <= audio_sample[23:16];
        3'b100: out_red <= audio_sample[23:16];
      endcase
    end else begin
      out_blue <= blue_reg;
      out_green <= green_reg;
      out_red <= red_reg;
    end
  end

  assign out_blue = switches[0] ? ~out_blue : out_blue;
  assign out_green = switches[1] ? ~out_green : out_green;
  assign out_red = switches[2] ? ~out_red : out_red;

  assign out_blue = switches[3] ? 8'h00 : out_blue;
  assign out_green = switches[4] ? 8'h00 : out_green;
  assign out_red = switches[5] ? 8'h00 : out_red;

  assign out_blue = switches[6] ? 8'hff : out_blue;
  assign out_green = switches[7] ? 8'hff : out_green;
  assign out_red = switches[8] ? 8'hff : out_red;

endmodule

module clock_phase_shifter (
  input clk_in,
  input signed [31:0] phase_shift,
  output clk_out
);

  reg delayed_clk;
  reg [31:0] delay_count = 0;

  always @(posedge clk_in) begin
    if (phase_shift > 0) begin
      if (delay_count < phase_shift) begin
        delay_count <= delay_count + 1;
        delayed_clk <= 0;
      end else begin
        delayed_clk <= 1;
      end
    end else if (phase_shift < 0) begin
      if (delay_count < -phase_shift) begin
        delay_count <= delay_count + 1;
        delayed_clk <= 1;
      end else begin
        delayed_clk <= 0;
      end
    end else begin
      delayed_clk <= clk_in;
    end
  end

  assign clk_out = delayed_clk ? delayed_clk : clk_in;

endmodule

module matrix_multiplier (
  input clk,
  input rst,
  input start,
  input [15:0] matrix_a,
  input [15:0] matrix_b,
  output [15:0] result,
  output done
);

  reg [15:0] a[0:3][0:3];
  reg [15:0] b[0:3][0:3];
  reg [15:0] c[0:3][0:3];
  reg [3:0] i, j, k;
  reg [3:0] count;
  reg done_reg;

  always @(*) begin
    for (i = 0; i < 4; i = i + 1) begin
      for (j = 0; j < 4; j = j + 1) begin
        a[i][j] = matrix_a[(i * 4) + j];
        b[i][j] = matrix_b[(i * 4) + j];
      end
    end
  end

  always @(posedge clk) begin
    if (rst) begin
      count <= 0;
      done_reg <= 0;
      for (i = 0; i < 4; i = i + 1) begin
        for (j = 0; j < 4; j = j + 1) begin
          c[i][j] <= 0;
        end
      end
    end else begin
      if (start && !done_reg) begin
        if (count < 4) begin
          for (k = 0; k < 4; k = k + 1) begin
            c[i][j] <= c[i][j] + (a[i][k] * b[k][j]);
          end
          if (j == 3) begin
            j <= 0;
            i <= i + 1;
          end else begin
            j <= j + 1;
          end
        end else begin
          done_reg <= 1;
        end
        count <= count + 1;
      end
    end
  end

  assign done = done_reg;
  assign result = {c[0][0], c[0][1], c[0][2], c[0][3], c[1][0], c[1][1], c[1][2], c[1][3], c[2][0], c[2][1], c[2][2], c[2][3], c[3][0], c[3][1], c[3][2], c[3][3]};

endmodule

module twos_complement_adder (
  input clk,
  input reset,
  input signed [3:0] A,
  input signed [3:0] B,
  output reg signed [4:0] C,
  output reg overflow
);

reg signed [3:0] sum;
reg carry;

always @(posedge clk, posedge reset) begin
  if (reset) begin
    sum <= 4'b0;
    carry <= 1'b0;
    C <= 5'b0;
    overflow <= 1'b0;
  end else begin
    sum <= A + B + carry;
    carry <= (sum[4] == 1);
    C <= {carry, sum};
    overflow <= ((A[3] == B[3]) && (A[3] != C[4]));
  end
end

endmodule

module nand4 (
  output Y,
  input A,
  input B,
  input C,
  input D,
  input VPWR,
  input VGND,
  input VPB,
  input VNB
);

  wire w1, w2, w3, w4, w5, w6, w7;

  assign w1 = ~(A & B);
  assign w2 = ~(C & D);
  assign w3 = ~(w1 & w2);
  assign w4 = ~(w3 & VPB);
  assign w5 = ~(w3 & VNB);
  assign w6 = ~(w4 & VGND);
  assign w7 = ~(w5 & VPWR);
  assign Y = ~(w6 & w7);

endmodule

module mux2x4(data0, data1, data2, data3, selectInput, out);

    output reg [1:0] out;
    input [1:0] data0, data1, data2, data3;
    input [1:0] selectInput;

    always @* begin
        case (selectInput)
            2'b00: out = data0;
            2'b01: out = data1;
            2'b10: out = data2;
            2'b11: out = data3;
            default: out = 2'b00;
        endcase
    end

