module clock_gen (
  input rst,
  input en,
  input [15:0] freq,
  input [15:0] duty,
  output reg clk
);

  reg [31:0] counter;
  reg [15:0] threshold;

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      clk <= 1'b0;
      counter <= 0;
    end else if (en) begin
      if (counter == threshold) begin
        clk <= ~clk;
        counter <= 0;
      end else begin
        counter <= counter + 1;
      end
    end
  end

  always @(*) begin
    threshold = (50000000 / (2 * freq)) - 1;
  end

  always @(*) begin
    clk = (counter < (threshold * (duty / 65536))) ? 1'b1 : 1'b0;
  end

endmodule

module parity_checker(
  input [3:0] data_in,
  input rst,
  input en,
  input clk,
  output even_parity,
  output odd_parity
);

  reg [1:0] parity;
  reg [3:0] last_data_in;

  always @(posedge clk) begin
    if (rst == 0) begin
      parity <= 2'b0;
      last_data_in <= 4'b0;
    end else if (en == 1) begin
      parity[0] <= data_in[0] ^ data_in[1] ^ data_in[2] ^ data_in[3];
      parity[1] <= ~parity[0];
      last_data_in <= data_in;
    end
  end

  assign even_parity = parity[0];
  assign odd_parity = parity[1];

endmodule

