module phase_detector (
  input ref_clk,
  input data_in,
  output reg [7:0] control_voltage
);

always @(posedge ref_clk) begin
  if (data_in > ref_clk) begin
    control_voltage <= control_voltage + delay_step;
  end else begin
    control_voltage <= control_voltage - delay_step;
  end
end

endmodule

module low_pass_filter (
  input clk,
  input [7:0] input_voltage,
  output reg [7:0] output_voltage
);

reg [7:0] filtered_voltage;

always @(posedge clk) begin
  filtered_voltage <= (1 - filter_coeff) * filtered_voltage + filter_coeff * input_voltage;
end

assign output_voltage = filtered_voltage;

endmodule

