module up_down_counter (
    input clk,
    input reset,
    input slowena,
    input up_down,
    output reg [3:0] count
);

reg [3:0] next_count;

always @(posedge clk or negedge reset) begin
    if (reset == 0) begin
        count <= 0;
    end
    else if (slowena == 1) begin
        count <= count;
    end
    else begin
        if (up_down == 1) begin
            next_count = count + 1;
        end
        else begin
            next_count = count - 1;
        end

        if (next_count == 4'b0000 || next_count == 4'b1111) begin
            count <= 4'b0000;
        end
        else begin
            count <= next_count;
        end
    end
end

endmodule

