module Modulo (
  input [31:0] x,
  input [31:0] y,
  output [31:0] remainder
);

  // If y is 0, return 0 as the remainder
  // This is not strictly necessary, but it prevents divide-by-zero errors
  // and makes the behavior of the module more predictable
  assign remainder = (y == 0) ? 0 : x % y;

  // If y is not 0, calculate the remainder using the optimized method
  // described in the problem statement
  always @(*) begin
    if (y != 0) begin
      remainder = x - (x / y) * y;
    end
  end

endmodule

