module akiko
(
	input	clk,
	input	reset,
	input	[23:1] address_in,
	input	[15:0] data_in,
	output	[15:0] data_out,
	input	rd,
	input	sel_akiko	// $B8xxxx
);

//0xb80038 - just the one register, but 32-bits wide.
reg [127:0] shifter;
reg [6:0] wrpointer;
wire sel;

// address decoding
assign sel = sel_akiko && address_in[7:1]==8'b0011_100; // 0x38

always @(posedge clk)
	if (reset)
		wrpointer <= 0;
	else if (!rd && sel)	// write to C2P reg...
	begin
		case(wrpointer)
			0	: shifter[127:112] <= data_in[15:0];
			1	: shifter[111:96] <= data_in[15:0];
			2	: shifter[95:80] <= data_in[15:0];
			3	: shifter[79:64] <= data_in[15:0];
			4	: shifter[63:48] <= data_in[15:0];
			5	: shifter[47:32] <= data_in[15:0];
			6	: shifter[31:16] <= data_in[15:0];
			7  : shifter[15:0] <= data_in[15:0];
		endcase
		wrpointer <= wrpointer + 1;
	end
   else if (rd && sel)	// read from C2P reg
	begin
		shifter[127:0] <= {shifter[126:0],1'b0};
		wrpointer <= 0;
	end

	assign data_out[15:0] = sel_akiko && rd ? {shifter[127],shifter[119],shifter[111],shifter[103],shifter[95],shifter[87],
		shifter[79],shifter[71],shifter[63],shifter[55],shifter[47],shifter[39],shifter[31],
		shifter[23],shifter[15],shifter[7]} : 16'b0 ;

endmodule

module uart_tx(
               input               clk_i,
               input [7:0]         rx_i,
               input               rx_i_v,
               output              tx_o,
               output              tx_o_v
               );

    localparam ST_IDLE   = 3'd0;
    localparam ST_START  = 3'd1;
    localparam ST_DATA   = 3'd2;
    localparam ST_STOP   = 3'd3;

    reg [2:0]                   state = ST_IDLE;
    reg [2:0]                   tx_ctr = 0;

    reg [7:0]                   s_rx = 0;
    reg                         s_tx = 1;


    always @ (posedge clk_i)
    begin
        case (state)

            ST_IDLE :
                if (rx_i_v)
                    state <= ST_START;

            ST_START :
                state <= ST_DATA;

            ST_DATA :
                if (tx_ctr == 7)
                    state <= ST_STOP;

            ST_STOP :
                state <= ST_IDLE;

        endcase
    end // always @ (posedge clk_i)

    always @ (posedge clk_i)
    begin
        if (state == ST_DATA)
        begin
            tx_ctr <= tx_ctr + 1;
        end
        else
        begin
            tx_ctr <= 0;
        end
    end // always @ (posedge state)

    always @ (posedge clk_i)
    begin
        if (state == ST_START)
        begin
            s_rx <= rx_i;
        end
        else if (state == ST_DATA)
        begin
            s_rx <= s_rx >> 1;
        end
    end

    assign tx_o_v = (state == ST_IDLE) ? 0 : 1;

    always @ *
    begin
        if (state == ST_START)
        begin
            s_tx = 0;
        end
        else if (state == ST_DATA)
        begin
            s_tx = s_rx[0];
        end
        else if (state == ST_STOP)
        begin
            s_tx = 1;
        end
    end // always @ *

    assign tx_o = s_tx;


endmodule

