    input clk,
    input reset, // Synchronous active-high reset
    input d, // 1-bit input for the shift register
    input [3:0] in, // 4-bit input for the 4-to-2 encoder
    input select, // Select input to choose between register and functional module
    output [3:0] q // 4-bit output from the active module
);

    // Shift register
    reg [2:0] shift_reg;
    always @(posedge clk) begin
        if (reset) begin
            shift_reg <= 0;
        end else begin
            shift_reg <= {shift_reg[1:0], d};
        end
    end

    // 4-to-2 encoder
    wire [1:0] encoder_out;
    assign encoder_out[0] = ~(in[0] | in[1] | in[2] | in[3]);
    assign encoder_out[1] = ~(in[0] | in[1] | in[2] | ~in[3]);

    // Functional module
    reg [3:0] func_out;
    always @(posedge clk) begin
        if (reset) begin
            func_out <= 4'b0;
        end else begin
            if (encoder_out == 2'b00) begin
                func_out <= shift_reg;
            end else begin
                func_out <= shift_reg + encoder_out;
            end
        end
    end

    // Output selection
    always @(*) begin
        if (select) begin
            q = func_out;
        end else begin
            q = shift_reg;
        end
    end

endmodule

module booth_multiplier (
    input [7:0] a,
    input [7:0] b,
    output reg [15:0] product
);

reg [7:0] a_reg, b_reg;
reg [3:0] count;
reg [15:0] sum;

always @ (a or b) begin
    a_reg <= a;
    b_reg <= b;
    count <= 4'd0;
    sum <= {8'd0, a_reg};
end

always @ (posedge clk) begin
    if (count < 4'd7) begin
        if (b_reg[0] == 1 && sum[0] == 0) begin
            sum <= sum - a_reg;
        end
        else if (b_reg[0] == 0 && sum[0] == 1) begin
            sum <= sum + a_reg;
        end
        if (sum[0] == 1) begin
            b_reg <= {1'b0, b_reg[7:1]};
        end
        else begin
            b_reg <= {b_reg[7], b_reg[7:1]};
        end
        sum <= {sum[15], sum[15:1]};
        count <= count + 1;
    end
    else begin
        product <= sum;
    end
end

endmodule

module dual_edge_ff (
    input clk,
    input d,
    output reg q
);
    reg prev_clk;

    always @(posedge clk or negedge clk) begin
        if (clk == 1 && prev_clk == 0) begin
            q <= d;
        end
        prev_clk <= clk;
    end
endmodule

module binary_counter (
    input clk,
    input reset,
    input load,
    input [3:0] load_value,
    output reg [3:0] count
);
    always @(posedge clk or negedge reset) begin
        if (reset == 1) begin
            count <= 4'b1000;
        end else if (load == 1) begin
            count <= load_value;
        end else begin
            count <= count + 1;
        end
    end
endmodule

module functional_module (
    input [7:0] in_data,
    input [3:0] in_count,
    output reg [7:0] out_data
);
    always @(in_data, in_count) begin
        case (in_count)
            4'b0000: out_data <= in_data + 8;
            4'b0001: out_data <= in_data + 9;
            4'b0010: out_data <= in_data + 10;
            4'b0011: out_data <= in_data + 11;
            4'b0100: out_data <= in_data + 12;
            4'b0101: out_data <= in_data + 13;
            4'b0110: out_data <= in_data + 14;
            4'b0111: out_data <= in_data + 15;
            4'b1000: out_data <= in_data;
            4'b1001: out_data <= in_data + 1;
            4'b1010: out_data <= in_data + 2;
            4'b1011: out_data <= in_data + 3;
            4'b1100: out_data <= in_data + 4;
            4'b1101: out_data <= in_data + 5;
            4'b1110: out_data <= in_data + 6;
            4'b1111: out_data <= in_data + 7;
        endcase
    end
endmodule

module top_module (
    input clk,
    input reset,
    input load,
    input [3:0] load_value,
    input d,
    output [7:0] q
);
    wire [3:0] count;
    wire ff_out;

    dual_edge_ff ff (.clk(clk), .d(d), .q(ff_out));
    binary_counter counter (.clk(clk), .reset(reset), .load(load), .load_value(load_value), .count(count));
    functional_module func (.in_data(ff_out), .in_count(count), .out_data(q));
endmodule

