    end
end

// carry out bit processing
always @ (posedge clk) begin
    if (ce) begin
        faccout0_co0_reg <= faccout0_co0;
        faccout1_co1_reg <= faccout1_co1;
    end
end

// small adder generation 
convolve_kernel_adEe_AddSubnS_0_fadder u0 (
