    full_adder fa1 (.a(A[1]), .b(B[1]), .c_in(C[0]), .s(S[1]), .c_out(C[1]));
    full_adder fa2 (.a(A[2]), .b(B[2]), .c_in(C[1]), .s(S[2]), .c_out(C[2]));
