module split_halfword(
    input wire [15:0] in,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo
);

    wire [7:0] shifted_in = in >> 8; // Shift input right by 8 bits
    wire [1:0] select = in[8:7];     // Select either upper or lower byte

    // Multiplexer to select either upper or lower byte
    assign out_hi = select == 2'b10 ? shifted_in : in[7:0];
    assign out_lo = select == 2'b01 ? shifted_in : in[7:0];

endmodule

