module keypad_scanner (
    input [3:0] row, // Input lines connected to the rows of the keypad
    output reg [3:0] col, // Output lines connected to the columns of the keypad
    output reg [1:0] key_pressed // 2-bit signal representing the pressed key
);

    always @(*) begin
        case (row)
            4'b0111: begin
                col = 4'b1110;
                key_pressed = 2'b00;
            end
            4'b1011: begin
                col = 4'b1101;
                key_pressed = 2'b01;
            end
            4'b1101: begin
                col = 4'b1011;
                key_pressed = 2'b10;
            end
            4'b1110: begin
                col = 4'b0111;
                key_pressed = 2'b11;
            end
            default: begin
                col = 4'b1111;
                key_pressed = 2'b00;
            end
        endcase
    end

endmodule

module priority_encoder (
    input [3:0] inputs, // Input signals to be encoded
    output reg [1:0] encoded // 2-bit signal representing the highest priority input
);

    always @(*) begin
        casez (inputs)
            4'bxxxx: encoded = 2'b00; // No input is active
            4'b1000: encoded = 2'b00; // Input 0 has highest priority
            4'b0100: encoded = 2'b01; // Input 1 has highest priority
            4'b0010: encoded = 2'b10; // Input 2 has highest priority
            4'b0001: encoded = 2'b11; // Input 3 has highest priority
            default: encoded = 2'b00; // Multiple inputs are active
        endcase
    end

endmodule

module multiplexer (
    input [3:0] A, B, C, D, // Input signals to be selected
    input [1:0] select, // 2-bit signal representing the selected input
    output reg [3:0] Y, // Output of the selected input signal
    output reg EN // Output signal indicating if any input is selected
);

    always @(*) begin
        case (select)
            2'b00: begin
                Y = A;
                EN = 1'b1;
            end
            2'b01: begin
                Y = B;
                EN = 1'b1;
            end
            2'b10: begin
                Y = C;
                EN = 1'b1;
            end
            2'b11: begin
                Y = D;
                EN = 1'b1;
            end
            default: begin
