module NIOS_SYSTEMV3_NIOS_CPU_nios2_oci_dtrace (
    // inputs:
    clk,
    cpu_d_address,
    cpu_d_read,
    cpu_d_readdata,
    cpu_d_wait,
    cpu_d_write,
    cpu_d_writedata,
    jrst_n,
    trc_ctrl,

    // outputs:
    atm,
    dtm
);

    output [35:0] atm;
    output [35:0] dtm;
    input clk;
    input [21:0] cpu_d_address;
    input cpu_d_read;
    input [31:0] cpu_d_readdata;
    input cpu_d_wait;
    input cpu_d_write;
    input [31:0] cpu_d_writedata;
    input jrst_n;
    input [15:0] trc_ctrl;

    reg [35:0] atm;
    wire [31:0] cpu_d_address_0_padded;
    wire [31:0] cpu_d_readdata_0_padded;
    wire [31:0] cpu_d_writedata_0_padded;
    reg [35:0] dtm;
    wire record_load_addr;
    wire record_load_data;
    wire record_store_addr;
    wire record_store_data;
    wire [3:0] td_mode_trc_ctrl;

    assign cpu_d_writedata_0_padded = {cpu_d_writedata, 32'b0};
    assign cpu_d_readdata_0_padded = {cpu_d_readdata, 32'b0};
    assign cpu_d_address_0_padded = {cpu_d_address, 32'b0};

    NIOS_SYSTEMV3_NIOS_CPU_nios2_oci_td_mode NIOS_SYSTEMV3_NIOS_CPU_nios2_oci_trc_ctrl_td_mode (
        .ctrl(trc_ctrl[8:0]),
        .td_mode(td_mode_trc_ctrl)
    );

    assign {record_load_addr, record_store_addr, record_load_data, record_store_data} = td_mode_trc_ctrl;

    always @(posedge clk or negedge jrst_n) begin
        if (~jrst_n) begin
            atm <= 0;
            dtm <= 0;
        end else if (cpu_d_write & ~cpu_d_wait & record_store_addr) begin
            atm <= {4'b0101, cpu_d_address_0_padded};
        end else if (cpu_d_read & ~cpu_d_wait & record_load_addr) begin
            atm <= {4'b0100, cpu_d_address_0_padded};
        end else begin
            atm <= {4'b0000, cpu_d_address_0_padded};
        end

        if (cpu_d_write & ~cpu_d_wait & record_store_data) begin
            dtm <= {4'b0111, cpu_d_writedata_0_padded};
        end else if (cpu_d_read & ~cpu_d_wait & record_load_data) begin
            dtm <= {4'b0110, cpu_d_readdata_0_padded};
        end else begin
            dtm <= {4'b0000, cpu_d_readdata_0_padded};
        end
    end

endmodule

module vending_machine (
  input clk,
  input reset,
  input [3:0] coin_in,
  input [1:0] product_sel,
  input dispense,
  output reg [1:0] product_disp,
  output reg [3:0] coin_out,
  output reg [3:0] coin_disp
);

  // Define states for the FSM
  localparam IDLE = 2'd0;
  localparam PRODUCT_SELECTED = 2'd1;
  localparam MONEY_INSERTED = 2'd2;
  localparam DISPENSE_PRODUCT = 2'd3;
  localparam DISPENSE_CHANGE = 2'd4;

  // Define constants for product costs
  localparam PRODUCT_A_COST = 4'd25;
  localparam PRODUCT_B_COST = 4'd50;
  localparam PRODUCT_C_COST = 4'd75;

  // Define variables for the FSM
  reg [1:0] state;
  reg [3:0] money_inserted;
  reg [3:0] change;

  // Define outputs for the display
  reg [1:0] display_product;
  reg [3:0] display_money;

  // Define internal wires
  wire enough_money = (state == MONEY_INSERTED) && (money_inserted >= product_cost);
  wire not_enough_money = (state == MONEY_INSERTED) && (money_inserted < product_cost);

  // Define internal parameters
  parameter product_cost = (product_sel == 2'd0) ? PRODUCT_A_COST : (product_sel == 2'd1) ? PRODUCT_B_COST : PRODUCT_C_COST;

  // Define the FSM
  always @(posedge clk, posedge reset) begin
    if (reset) begin
      state <= IDLE;
      money_inserted <= 0;
      change <= 0;
      display_product <= 0;
      display_money <= 0;
    end else begin
      case (state)
        IDLE: begin
          if (product_sel != 2'd3) begin
            state <= PRODUCT_SELECTED;
            display_product <= product_sel;
          end
        end
        PRODUCT_SELECTED: begin
          if (coin_in != 4'b0000) begin
            state <= MONEY_INSERTED;
            money_inserted <= coin_in;
            display_money <= coin_in;
          end else if (dispense) begin
            state <= IDLE;
            display_product <= 0;
          end
        end
        MONEY_INSERTED: begin
          if (enough_money) begin
            state <= DISPENSE_PRODUCT;
            change <= money_inserted - product_cost;
            display_money <= 0;
          end else if (not_enough_money) begin
            state <= DISPENSE_CHANGE;
            coin_disp <= money_inserted;
            display_money <= 0;
          end else if (dispense) begin
            state <= IDLE;
            coin_disp <= money_inserted;
            display_money <= 0;
          end
        end
        DISPENSE_PRODUCT: begin
          state <= IDLE;
          product_disp <= product_sel;
          coin_out <= change;
          display_product <= 0;
        end
        DISPENSE_CHANGE: begin
          state <= IDLE;
          coin_out <= coin_disp;
          display_product <= 0;
        end
      endcase
    end
  end

endmodule

