module jtag_uart_sim_fifo (
  input clk,
  input fifo_rd,
  input rst_n,
  output fifo_EF,
  output reg [7:0] fifo_rdata,
  output rfifo_full,
  output reg [5:0] rfifo_used
);

  // Constants
  parameter FIFO_DEPTH = 64;

  // Internal signals
  reg [7:0] fifo_data [0:FIFO_DEPTH-1];
  reg [5:0] fifo_head;
  reg [5:0] fifo_tail;
  reg [5:0] fifo_count;

  // Outputs
  assign fifo_EF = (fifo_count == 0);
  assign rfifo_full = (fifo_count == FIFO_DEPTH);
  assign rfifo_used = fifo_count;

  // Read data from FIFO
  always @(posedge clk) begin
    if (rst_n == 0) begin
      fifo_rdata <= 8'b0;
      fifo_head <= 6'b0;
      fifo_tail <= 6'b0;
      fifo_count <= 6'b0;
    end else if (fifo_rd && fifo_count > 0) begin
      fifo_rdata <= fifo_data[fifo_head];
      fifo_head <= fifo_head + 1;
      fifo_count <= fifo_count - 1;
    end
  end

  // Write data to FIFO
  always @(posedge clk) begin
    if (rst_n == 0) begin
      fifo_head <= 6'b0;
      fifo_tail <= 6'b0;
      fifo_count <= 6'b0;
    end else if (!fifo_rd && fifo_count < FIFO_DEPTH) begin
      fifo_data[fifo_tail] <= fifo_rdata;
      fifo_tail <= fifo_tail + 1;
      fifo_count <= fifo_count + 1;
    end
  end

endmodule

module barrel_shifter(
    input               clk         ,
    input               reset       ,
    input       [99:0]  data_in     ,
    input               load        ,
    input       [1:0]   ena         ,
    output reg  [99:0]  data_out    );

    always @(posedge clk) begin
        if (reset) begin
            data_out <= 100'b0;
        end else begin
            if (load) begin
                data_out <= data_in;
            end else begin
                case (ena)
                    2'b00: data_out <= {data_out[98:0], data_out[99]};
                    2'b01: data_out <= {data_out[0], data_out[99:1]};
                    2'b10: data_out <= {data_out[1:99], data_out[0]};
                    2'b11: data_out <= {data_out[99], data_out[98:0]};
                endcase
            end
        end
    end
endmodule

module accumulator(
    input               clk         ,
    input               reset       ,
    input       [7:0]   data_in     ,
    input               valid_in    ,
    output              ready_out   ,
    output reg [9:0]    data_out    );

    reg [9:0] count;
    reg [9:0] sum;

    always @(posedge clk) begin
        if (reset) begin
            count <= 10'b0;
            sum <= 10'b0;
            data_out <= 10'b0;
        end else begin
            if (valid_in) begin
                count <= count + 1;
                sum <= sum + data_in;
                if (count == 10'b111) begin
                    data_out <= sum;
                    count <= 10'b0;
                    sum <= 10'b0;
                end
            end
        end
    end

    assign ready_out = (count == 10'b0);
endmodule

