    input       [7:0]   data_in_acc ,
    input               valid_a     ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out    );

    wire [99:0] shifted_data;
    wire [9:0] accumulated_data;

    barrel_shifter shifter(
        .clk(clk),
        .reset(reset),
        .data_in(data_in),
        .load(load),
        .ena(ena),
        .data_out(shifted_data)
    );

    accumulator acc(
        .clk(clk),
        .reset(reset),
        .data_in(data_in_acc),
        .valid_in(valid_a),
        .ready_out(ready_b),
        .data_out(accumulated_data)
    );

    or_module or_gate(
        .data_in_1(shifted_data),
        .data_in_2(accumulated_data),
