    );

    assign ready_a = !valid_b;
    always @(posedge clk) begin
        if (reset) begin
            valid_b <= 1'b0;
        end else begin
            if (valid_a && ready_a) begin
                valid_b <= 1'b1;
            end else if (ready_b) begin
                valid_b <= 1'b0;
            end
        end
    end
endmodule

module shift_register (
    input clk,
