    end
    else begin
        Q_reg1 <= Load ? {B, A, Q} : {Q_reg2[1:0], Q_reg1[2]};
        Q_reg2 <= {Q_reg3[0], Q_reg2[2:1]};
        Q_reg3 <= {Q_reg3[2], Q_reg2[0], Q_reg1[1]};
    end
end

assign Q = Q_reg3;

endmodule

module signed_division
#(
    parameter in0_WIDTH = 32,
    parameter in1_WIDTH = 32,
    parameter out_WIDTH = 32
)
(
    input clk,
    input reset,
    input ce,
    input signed [in0_WIDTH-1:0] dividend,
    input signed [in1_WIDTH-1:0] divisor,
    output reg signed [out_WIDTH-1:0] quot,
    output reg signed [out_WIDTH-1:0] remd
);

// Internal signals
reg signed [in0_WIDTH-1:0] dividend0;
reg signed [in1_WIDTH-1:0] divisor0;
wire signed [in0_WIDTH-1:0] dividend_u;
wire signed [in1_WIDTH-1:0] divisor_u;
wire signed [out_WIDTH-1:0] quot_u;
wire signed [out_WIDTH-1:0] remd_u;
wire [1:0] sign_i;
wire [1:0] sign_o;

// Instantiate hls_contrast_strefYi_div_u module
hls_contrast_strefYi_div_u #(
    .in0_WIDTH (in0_WIDTH),
    .in1_WIDTH (in1_WIDTH),
    .out_WIDTH (out_WIDTH)
) hls_contrast_strefYi_div_u_0 (
    .clk (clk),
    .reset (reset),
    .ce (ce),
    .dividend (dividend_u),
    .divisor (divisor_u),
    .sign_i (sign_i),
    .sign_o (sign_o),
    .quot (quot_u),
    .remd (remd_u)
);

// Assign sign input signal
assign sign_i = {dividend0[in0_WIDTH-1] ^ divisor0[in1_WIDTH-1], dividend0[in0_WIDTH-1]};

// Assign unsigned input signals
assign dividend_u = dividend0[in0_WIDTH-1] ? ~dividend0[in0_WIDTH-1:0] + 1'b1 : dividend0[in0_WIDTH-1:0];
assign divisor_u = divisor0[in1_WIDTH-1] ? ~divisor0[in1_WIDTH-1:0] + 1'b1 : divisor0[in1_WIDTH-1:0];

// Assign output signals with proper sign
always @(posedge clk) begin
    if (ce) begin
        dividend0 <= dividend;
        divisor0 <= divisor;
    end
end

always @(posedge clk) begin
    if (ce) begin
        if (sign_o[1])
            quot <= ~quot_u + 1'b1;
        else
            quot <= quot_u;
    end
end

always @(posedge clk) begin
    if (ce) begin
        if (sign_o[0])
            remd <= ~remd_u + 1'b1;
        else
            remd <= remd_u;
    end
end

// Determine sign of output signals
always @(*) begin
    if (sign_i[0]) begin
        if (sign_i[1])
            sign_o <= 2'b11; // Both inputs negative
        else
            sign_o <= 2'b10; // Dividend negative
    end else begin
        if (sign_i[1])
            sign_o <= 2'b01; // Divisor negative
        else
            sign_o <= 2'b00; // Both inputs positive
    end
end

endmodule

