   always @ (posedge clk)
     if(~frame)
       cycle[3:0] <= 'b0;
     else
       cycle[3:0] <=  cycle[3:0]+1'b1;

   //Rising edge sampling
   always @ (posedge clk)
     if(frame)
       case (cycle)
