module top_module (
    input clk,
    input [19:0] in,
    input load,
    input [1:0] ena,
    input [99:0] data,
    output reg [9:0] out
);

    // Half-word splitter
    wire [9:0] in_0, in_1;
    wire [1:0] sel;
    wire [4:0] dec;
    mux_2to1 #(.WIDTH(10)) mux_0 (.in0(in[9:0]), .in1(in[19:10]), .sel(sel), .out(in_0));
    mux_2to1 #(.WIDTH(10)) mux_1 (.in0(in[9:0]), .in1(in[19:10]), .sel(~sel), .out(in_1));
    decoder #(.WIDTH(2)) dec_0 (.in(sel), .out(dec));

    // 100-bit rotator
    reg [99:0] shift_reg;
    always @(posedge clk) begin
        if (load) begin
            shift_reg <= data;
        end else if (ena == 2'b01) begin
            shift_reg <= {shift_reg[1:0], shift_reg[99:2]};
        end else if (ena == 2'b10) begin
            shift_reg <= {shift_reg[98:0], shift_reg[99:99]};
        end
    end

    // Functional module
    wire [9:0] and_out;
    assign and_out = in_0 & in_1 & shift_reg[99:90];
    assign out = and_out;

endmodule

