module SPI_master (
  input clk,
  input cs,
  input data_in,
  output reg data_out
);

reg [7:0] tx_data;
reg [7:0] rx_data;
reg [2:0] state;

parameter IDLE = 3'b000;
parameter SEND = 3'b001;
parameter RECV = 3'b010;

always @(posedge clk) begin
  if (cs == 1'b0) begin
    case (state)
      IDLE: begin
        tx_data <= data_in;
        state <= SEND;
      end
      SEND: begin
        data_out <= tx_data[7];
        tx_data <= {tx_data[6:0], 1'b0};
        if (tx_data == 8'h00) begin
          state <= RECV;
        end
      end
      RECV: begin
        rx_data <= {rx_data[6:0], data_in};
        data_out <= rx_data[7];
        if (rx_data == 8'h00) begin
          state <= IDLE;
        end
      end
    endcase
  end else begin
    state <= IDLE;
    data_out <= 1'b0;
    tx_data <= 8'h00;
    rx_data <= 8'h00;
  end
end

endmodule

