parameter IDLE = 3'b000;
parameter RECV = 3'b001;
parameter SEND = 3'b010;

always @(posedge clk) begin
  if (cs == 1'b0) begin
    case (state)
      IDLE: begin
        data_out <= 1'b0;
        state <= RECV;
      end
      RECV: begin
        rx_data <= {rx_data[6:0], data_in};
        if (rx_data == 8'hFF) begin
