        end
      end
      SEND: begin
        data_out <= tx_data[7];
        tx_data <= {tx_data[6:0], 1'b0};
        if (tx_data == 8'h00) begin
          state <= IDLE;
        end
      end
    endcase
  end else begin
    state <= IDLE;
    data_out <= 1'b0;
    tx_data <= 8'h00;
    rx_data <= 8'h00;
  end
end

