    input EN,
    output [3:0] q
);

    reg [2:0] count;
    wire [3:0] mux_out;
    wire [3:0] sum;

    up_counter counter(clk, reset, count);
    mux_4to1 mux(IN, SEL, mux_out, EN);
    adder add(mux_out, count, sum);

