module up_counter (
    input clk,
    input reset,
    output reg [2:0] q
);

    always @(posedge clk, negedge reset) begin
        if (!reset) begin
            q <= 3'b0;
        end else begin
            q <= q + 1;
        end
    end

endmodule

module mux_4to1 (
    input [3:0] IN,
    input [1:0] SEL,
    output reg [3:0] q,
    input EN
);

    always @(SEL or IN or EN) begin
        case (SEL)
            2'b00: q <= EN ? IN[0] : 4'bz;
            2'b01: q <= EN ? IN[1] : 4'bz;
            2'b10: q <= EN ? IN[2] : 4'bz;
            2'b11: q <= EN ? IN[3] : 4'bz;
        endcase
    end

endmodule

module adder (
    input [3:0] a,
    input [3:0] b,
    output reg [3:0] q
);

    always @(a or b) begin
        q <= a + b;
    end

endmodule

module main;
   wire [1:0] out;
   reg [3:0] in;

   always @* begin
      case(in)
         4'b0000, 4'b0010, 4'b0100: out = 2'b00;
         4'b0001, 4'b0011, 4'b0101: out = 2'b01;
         4'b0110, 4'b1000, 4'b1010: out = 2'b10;
         4'b0111, 4'b1001, 4'b1011: out = 2'b11;
