module HRnode (
  input clk, rst,

  input `control_w port0_i, port1_i, port0_local_i, port1_local_i,
  output `control_w port0_o, port1_o, port0_local_o, port1_local_o,

  output `control_w portl0_ack, portl1_ack
  );

  reg [143:0] port0_data, port1_data, port0_local_data, port1_local_data;
  reg port0_valid, port1_valid, port0_local_valid, port1_local_valid;
  reg [143:0] portl0_data, portl1_data;
  reg portl0_valid, portl1_valid;

  assign port0_o = port0_data;
  assign port1_o = port1_data;
  assign port0_local_o = port0_local_data;
  assign port1_local_o = port1_local_data;

  assign portl0_ack = portl0_valid;
  assign portl1_ack = portl1_valid;

  always @(posedge clk) begin
    if (rst) begin
      port0_data <= 144'h0;
      port1_data <= 144'h0;
      port0_local_data <= 144'h0;
      port1_local_data <= 144'h0;
      port0_valid <= 1'b0;
      port1_valid <= 1'b0;
      port0_local_valid <= 1'b0;
      port1_local_valid <= 1'b0;
      portl0_data <= 144'h0;
      portl1_data <= 144'h0;
      portl0_valid <= 1'b0;
      portl1_valid <= 1'b0;
    end else begin
      if (port0_valid == 1'b0 && port0_i != 144'h0) begin
        port0_data <= port0_i;
        port0_valid <= 1'b1;
      end else if (port0_valid == 1'b1 && port0_local_valid == 1'b0 && port0_local_i != 144'h0) begin
        port0_local_data <= port0_local_i;
        port0_local_valid <= 1'b1;
        port0_valid <= 1'b0;
        portl0_data <= port0_data;
        portl0_valid <= 1'b1;
      end else if (port1_valid == 1'b0 && port1_i != 144'h0) begin
        port1_data <= port1_i;
        port1_valid <= 1'b1;
      end else if (port1_valid == 1'b1 && port1_local_valid == 1'b0 && port1_local_i != 144'h0) begin
        port1_local_data <= port1_local_i;
        port1_local_valid <= 1'b1;
        port1_valid <= 1'b0;
        portl1_data <= port1_data;
        portl1_valid <= 1'b1;
      end else if (port0_local_valid == 1'b1 && portl0_valid == 1'b1) begin
        port0_local_valid <= 1'b0;
        portl0_valid <= 1'b0;
      end else if (port1_local_valid == 1'b1 && portl1_valid == 1'b1) begin
        port1_local_valid <= 1'b0;
        portl1_valid <= 1'b0;
      end
    end
  end

endmodule

