module memory_access(
  input clk,
  input [16:0] mrdata_s,
  input [16:0] mwaddr,
  input [16:0] mraddr,
  input win_ready,
  input win_valid,
  output reg [5:0] maddrdiff,
  output reg adc_ready,
  output reg mrd,
  output reg mrvalid,
  output reg [16:0] mrdata,
  output reg win_valid,
  output reg [15:0] win_data,
  output reg win_last
);

  reg mrd_s;
  reg [17:0] maddrdiff_s;
  reg mxfer_s;
  reg [1:0] mwcnt = 2'd0;
  reg [1:0] mrcnt = 2'd0;
  reg [16:0] mdata_0 = 17'd0;
  reg [16:0] mdata_1 = 17'd0;
  reg [16:0] mdata_2 = 17'd0;
  reg [16:0] mdata_3 = 17'd0;
  reg mvalid_0 = 1'b0;
  reg mvalid_1 = 1'b0;
  reg mvalid_2 = 1'b0;
  reg mvalid_3 = 1'b0;

  assign mrd_s = (mwaddr == mraddr) ? 1'b0 : win_ready;
  assign maddrdiff_s = {1'b1, mwaddr} - mraddr;
  assign mxfer_s = win_ready | ~win_valid;

  always @(posedge clk) begin
    maddrdiff <= maddrdiff_s[5:0];
    if (maddrdiff >= 32) begin
      adc_ready <= 1'b0;
    end else if (maddrdiff <= 20) begin
      adc_ready <= 1'b1;
    end
  end

  always @(posedge clk) begin
    if (mrd_s == 1'b1) begin
      mraddr <= mraddr + 1'b1;
    end
    mrd <= mrd_s;
    mrvalid <= mrd;
    mrdata <= mrdata_s;
  end

  always @(posedge clk) begin
    if (mrvalid == 1'b1) begin
      mwcnt <= mwcnt + 1'b1;
    end
    if ((mwcnt == 2'd0) && (mrvalid == 1'b1)) begin
      mvalid_0 <= 1'b1;
      mdata_0 <= mrdata;
    end else if ((mrcnt == 2'd0) && (mxfer_s == 1'b1)) begin
      mvalid_0 <= 1'b0;
      mdata_0 <= 17'd0;
    end
    if ((mwcnt == 2'd1) && (mrvalid == 1'b1)) begin
      mvalid_1 <= 1'b1;
      mdata_1 <= mrdata;
    end else if ((mrcnt == 2'd1) && (mxfer_s == 1'b1)) begin
      mvalid_1 <= 1'b0;
      mdata_1 <= 17'd0;
    end
    if ((mwcnt == 2'd2) && (mrvalid == 1'b1)) begin
      mvalid_2 <= 1'b1;
      mdata_2 <= mrdata;
    end else if ((mrcnt == 2'd2) && (mxfer_s == 1'b1)) begin
      mvalid_2 <= 1'b0;
      mdata_2 <= 17'd0;
    end
    if ((mwcnt == 2'd3) && (mrvalid == 1'b1)) begin
      mvalid_3 <= 1'b1;
      mdata_3 <= mrdata;
    end else if ((mrcnt == 2'd3) && (mxfer_s == 1'b1)) begin
      mvalid_3 <= 1'b0;
      mdata_3 <= 17'd0;
    end
    if ((mrcnt != mwcnt) && (win_ready == 1'b1)) begin
      mrcnt <= mrcnt + 1'b1;
    end
    if ((win_valid == 1'b0) || (win_ready == 1'b1)) begin
      case (mrcnt)
        2'd3: begin
          win_valid <= mvalid_3;
          win_data <= mdata_3[15:0];
          win_last <= mdata_3[16] & mvalid_3;
        end
        2'd2: begin
          win_valid <= mvalid_2;
          win_data <= mdata_2[15:0];
          win_last <= mdata_2[16] & mvalid_2;
        end
        2'd1: begin
          win_valid <= mvalid_1;
          win_data <= mdata_1[15:0];
          win_last <= mdata_1[16] & mvalid_1;
        end
        default: begin
          win_valid <= mvalid_0;
          win_data <= mdata_0[15:0];
          win_last <= mdata_0[16] & mvalid_0;
        end
      endcase
    end
  end

endmodule

module lifo_memory (
  input clk,
  input rst,
  input wr_en,
  input [7:0] data_in,
  output reg [7:0] data_out
);

parameter depth = 8; // depth of the LIFO memory block

reg [7:0] stack [depth-1:0];
reg [3:0] top;

always @(posedge clk) begin
  if (rst) begin
    top <= 0;
  end else if (wr_en) begin
    stack[top] <= data_in;
    top <= top + 1;
  end else if (top > 0) begin
    top <= top - 1;
  end
end

assign data_out = stack[top];

endmodule

module memory_wb(
    input clk,
    input rst,
    input wire d_read_en,
    input wire d_write_en,
    input wire [31:0] d_addr,
    input wire [31:0] d_write_data,
    input wbm_done_pls_i,
    input [31:0] wbm_dat_i,
    input wbm_ack_i,
    output reg done_o,
    output reg [31:0] d_data_out,
    output reg [31:0] wbm_dat_o,
    output reg wbm_we_o,
    output [3:0] wbm_sel_o,
    output reg [31:0] wbm_adr_o,
    output reg wbm_cyc_o,
    output reg wbm_stb_o
);

    reg [1:0] state_r;
    reg rd_r, wr_r;
    reg [31:0] mem [0:1023];

    assign wbm_sel_o = 4'b1111;

    localparam IDLE      = 0;
    localparam WRITE_ACK = 1;
    localparam READ_ACK  = 2;
    localparam DONE_PLS  = 3;

    always@(posedge clk, posedge rst) 
        if(rst) begin
             state_r    <= IDLE;
             done_o     <= 1'b0;
             wbm_adr_o <= 0;
             wbm_dat_o  <= 0;
             wbm_we_o   <= 1'b0;
             wbm_stb_o  <= 1'b0;
             wbm_cyc_o  <= 1'b0;
             d_data_out <= 0;
             rd_r <= 0;
             wr_r <= 0;
        end else begin
            rd_r <= d_read_en;
            wr_r <= d_write_en;
            done_o <= 1'b0;
            case(state_r) 
                IDLE: 
                    if(d_write_en && !wr_r) begin
                         mem[d_addr] <= d_write_data;
                         wbm_adr_o <= d_addr;
                         wbm_dat_o  <= 0;
                         wbm_we_o   <= 1'b1;
                         wbm_stb_o  <= 1'b1;
                         wbm_cyc_o  <= 1'b1;
                         state_r    <= WRITE_ACK;
                    end else if (d_read_en && !rd_r) begin
                         d_data_out <= mem[d_addr];
                         wbm_adr_o <= d_addr;
                         wbm_dat_o  <= 0;
                         wbm_we_o   <= 1'b0;
                         wbm_stb_o  <= 1'b1;
                         wbm_cyc_o  <= 1'b1;
                         state_r <= READ_ACK;
                    end else if (wbm_done_pls_i) begin
                         done_o  <= 1'b1;
                         state_r <= DONE_PLS;
                    end
                WRITE_ACK: 
                    if(wbm_ack_i) begin
                        wbm_we_o   <= 1'b0;
                        wbm_stb_o  <= 1'b0;
                        wbm_cyc_o  <= 1'b0;
                        done_o     <= 1'b1;
                        state_r    <= IDLE;
                    end
                READ_ACK:
                    if(wbm_ack_i) begin
                         wbm_stb_o  <= 1'b0;
                         wbm_cyc_o  <= 1'b0;
                         done_o     <= 1'b1;
                         state_r    <= IDLE;
                    end
                DONE_PLS: 
                    if(!wbm_done_pls_i)
                         state_r <= IDLE;

            endcase
        end
endmodule

