module sum_module (
    input clk,
    input rst,
    input [31:0] in,
    input in_valid,
    output reg [31:0] out,
    output reg out_valid
);

reg [31:0] sum;
reg [31:0] count;

always @(posedge clk) begin
    if (rst) begin
        sum <= 0;
        count <= 0;
        out_valid <= 0;
    end else if (in_valid) begin
        sum <= sum + in;
        count <= count + 1;
    end else if (count > 0) begin
        out <= sum;
        out_valid <= 1;
        sum <= 0;
        count <= 0;
    end else begin
        out_valid <= 0;
    end
end

endmodule

module profibus_master (
  input clk,
  input reset,
  input [7:0] tx_data,
  input tx_valid,
  output [7:0] rx_data,
  output rx_valid,
  output tx_ready
);

  reg [7:0] tx_data_reg;
  reg tx_valid_reg;
  reg [7:0] rx_data_reg;
  reg rx_valid_reg;
  reg tx_ready_reg;
  reg [1:0] state;

  always @(posedge clk) begin
    if (reset) begin
      state <= 2'b00;
      tx_data_reg <= 8'b0;
      tx_valid_reg <= 1'b0;
      rx_data_reg <= 8'b0;
      rx_valid_reg <= 1'b0;
      tx_ready_reg <= 1'b0;
    end else begin
      case (state)
        2'b00: begin // Idle state
          if (tx_valid) begin
            tx_data_reg <= tx_data;
            tx_valid_reg <= 1'b1;
            tx_ready_reg <= 1'b0;
            state <= 2'b01;
          end
        end
        2'b01: begin // Transmit state
          if (tx_ready) begin
            tx_valid_reg <= 1'b0;
            tx_ready_reg <= 1'b0;
            state <= 2'b10;
          end
        end
        2'b10: begin // Receive state
          rx_valid_reg <= 1'b1;
          rx_data_reg <= rx_data;
          tx_ready_reg <= 1'b1;
          state <= 2'b00;
        end
      endcase
    end
  end

  assign rx_data = rx_data_reg;
  assign rx_valid = rx_valid_reg;
  assign tx_ready = tx_ready_reg;
  assign tx_data = tx_data_reg;
  assign tx_valid = tx_valid_reg;

endmodule


