module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout
);

reg [3:0] S1, S2, S3;
reg C1, C2, C3;

assign Sum = S3;
assign Cout = C3;

// Stage 1
full_adder FA1(A[0], B[0], Cin, S1[0], C1);

// Stage 2
full_adder FA2(A[1], B[1], C1, S2[1], C2);
half_adder HA1(A[0], B[0], S1[0]);

// Stage 3
full_adder FA3(A[2], B[2], C2, S3[2], C3);
half_adder HA2(A[1], B[1], S2[1]);
half_adder HA3(A[0], B[0], S1[0]);

// Stage 4
full_adder FA4(A[3], B[3], C3, S3[3], Cout);
half_adder HA4(A[2], B[2], S3[2]);
half_adder HA5(A[1], B[1], S2[1]);
half_adder HA6(A[0], B[0], S1[0]);

endmodule

