module UART_transmitter (
  input clk,
  input rst,
  input [7:0] data_in,
  input start_bit,
  input stop_bit,
  input parity_bit,
  output reg serial_out
);

parameter baud_rate = 9600;
parameter bit_time = $floor((1.0/baud_rate)*1000000000); // Time for each bit in nanoseconds

reg [3:0] state = 0;
reg [7:0] data_reg;
reg [3:0] bit_count = 0;
reg parity_reg;
reg stop_reg;

always @(posedge clk) begin
  if (rst) begin
    state <= 0;
    bit_count <= 0;
    parity_reg <= 0;
    stop_reg <= 1;
    data_reg <= 0;
    serial_out <= 1;
  end else begin
    case (state)
      0: begin // Idle state, waiting for start bit
        if (!start_bit) begin
          state <= 1;
          bit_count <= 0;
          parity_reg <= parity_bit;
          stop_reg <= stop_bit;
          data_reg <= data_in;
          serial_out <= 0;
        end
      end
      1: begin // Transmitting data
        if (bit_count < 8) begin
          serial_out <= data_reg[bit_count];
          parity_reg <= parity_reg ^ data_reg[bit_count];
          bit_count <= bit_count + 1;
        end else if (bit_count == 8) begin // Transmitting parity bit
          serial_out <= parity_reg;
          bit_count <= bit_count + 1;
        end else if (bit_count == 9) begin // Transmitting stop bit
          serial_out <= stop_reg;
          bit_count <= 0;
          state <= 0;
        end
      end
    endcase
  end
end

endmodule
module UART_receiver (
  input clk,
  input rst,
  input serial_in,
  output reg [7:0] data_out,
  output reg start_detected,
  output reg stop_detected,
  output reg parity_error
);

parameter baud_rate = 9600;
parameter bit_time = $floor((1.0/baud_rate)*1000000000); // Time for each bit in nanoseconds

reg [3:0] state = 0;
reg [7:0] data_reg;
reg [3:0] bit_count = 0;
reg parity_reg;
reg stop_reg;

always @(posedge clk) begin
  if (rst) begin
    state <= 0;
    bit_count <= 0;
    parity_reg <= 0;
    stop_reg <= 1;
    data_reg <= 0;
    start_detected <= 0;
    stop_detected <= 0;
    parity_error <= 0;
  end else begin
    case (state)
      0: begin // Idle state, waiting for start bit
        if (!serial_in) begin
          state <= 1;
          bit_count <= 0;
          parity_reg <= 0;
          stop_reg <= 1;
          data_reg <= 0;
          start_detected <= 1;
        end
      end
      1: begin // Receiving data
        if (bit_count < 8) begin
          data_reg[bit_count] <= serial_in;
          parity_reg <= parity_reg ^ serial_in;
          bit_count <= bit_count + 1;
        end else if (bit_count == 8) begin // Receiving parity bit
          parity_error <= (parity_reg != serial_in);
          bit_count <= bit_count + 1;
        end else if (bit_count == 9) begin // Receiving stop bit
          stop_detected <= (serial_in != stop_reg);
          bit_count <= 0;
          state <= 0;
          data_out <= data_reg;
        end
      end
    endcase
  end
end

endmodule

module binary_subtractor (
    input [7:0] a,
    input [7:0] b,
    output [8:0] diff
);

    wire [7:0] b_not;
    wire [8:0] sum;

    // Bitwise NOT operation on b
    assign b_not = ~b;

    // Binary adder module
    adder adder_inst (
        .a(a),
        .b(b_not),
        .sum(sum)
    );

    // Bitwise AND operation on a and b_not
    assign diff = {1'b0, a} & {1'b0, b_not};

endmodule

module adder (
    input [7:0] a,
    input [7:0] b,
    output [8:0] sum
);

    wire [7:0] carry;
    assign carry = {1'b0, a} + {1'b0, b};

    assign sum = carry + 1'b0;

endmodule

