module PRNG (
  input clk,
  input rst,
  input [w-1:0] seed,
  output reg [w-1:0] rand
);

parameter w = 8; // width of the output value (in bits)

reg [w-1:0] lfsr; // linear feedback shift register

always @ (posedge clk) begin
  if (rst) begin
    lfsr <= 0;
    rand <= 0;
  end else begin
    // generate the next pseudo-random number using the LFSR
    lfsr[w-1:1] <= lfsr[w-2:0];
    lfsr[0] <= lfsr[w-1] ^ lfsr[w-2] ^ seed[w-1] ^ seed[w-2];
    rand <= lfsr;
  end
end

endmodule

module UART (
    input rst,
    // IO ports
    input clk,
    input rx,
    output tx,
    // Tx data port
    input tx_data_ready,
    input [7:0] tx_data,
    output tx_data_accepted,
    // Rx data port
    output [7:0] rx_data,
    output rx_data_ready,
    output rx_framing_error
);
    // COUNTER*OVERSAMPLE == effective baud rate.
    //
    // So given a 100 MHz clock (100000000), an 8x oversample and a counter
    // of 25, (100000000/(8*25)) => 500000 baud.
    //
    // BAUDGEN generates an edge COUNTER clock cycles.
    // Two BAUDGEN's are used, one for the Tx which is at the baudrate, and
    // one for the Rx which is at OVERSAMPLE times the baudrate.
    parameter COUNTER = 25;
    parameter OVERSAMPLE = 8;

    wire tx_baud_edge;
    wire rx_baud_edge;

    BAUDGEN #(.COUNTER(COUNTER*OVERSAMPLE)) tx_baud (
        .clk(clk),
        .rst(rst),
        .baud_edge(tx_baud_edge)
    );

    UART_TX tx_gen(
        .rst(rst),
        .clk(clk),
        .baud_edge(tx_baud_edge),
        .data_ready(tx_data_ready),
        .data(tx_data),
        .tx(tx),
        .data_accepted(tx_data_accepted)
    );

    BAUDGEN #(.COUNTER(COUNTER)) rx_baud (
        .clk(clk),
        .rst(rst),
        .baud_edge(rx_baud_edge)
    );

    UART_RX rx_gen(
        .rst(rst),
        .clk(clk),
        .baud_edge(rx_baud_edge),
        .rx(rx),
        .data(rx_data),
        .data_ready(rx_data_ready),
        .framing_error(rx_framing_error)
    );
endmodule

module BAUDGEN #(
    parameter COUNTER = 25
) (
    input clk,
    input rst,
    output reg baud_edge
);
    reg [31:0] counter = 0;

    always @(posedge clk or negedge rst) begin
        if (!rst) begin
            counter <= 0;
            baud_edge <= 0;
        end else begin
            counter <= counter + 1;
            if (counter == COUNTER) begin
                baud_edge <= 1;
                counter <= 0;
            end else begin
                baud_edge <= 0;
            end
        end
    end
endmodule

module UART_TX (
    input rst,
    input clk,
    input baud_edge,
    input data_ready,
    input [7:0] data,
    output reg tx,
    output reg data_accepted
);
    reg [7:0] tx_data = 0;
    reg [3:0] bit_count = 0;
    reg tx_active = 0;

    always @(posedge clk or negedge rst) begin
        if (!rst) begin
            tx_data <= 0;
            bit_count <= 0;
            tx_active <= 0;
            tx <= 1;
            data_accepted <= 0;
        end else begin
            if (data_ready && !tx_active) begin
                tx_data <= data;
                bit_count <= 0;
                tx_active <= 1;
                tx <= 0;
                data_accepted <= 1;
            end else if (tx_active && baud_edge) begin
                tx <= tx_data[bit_count];
                bit_count <= bit_count + 1;
                if (bit_count == 8) begin
                    tx_active <= 0;
                    data_accepted <= 0;
                end
            end else begin
                tx <= 1;
            end
        end
    end
endmodule

module UART_RX (
    input rst,
    input clk,
    input baud_edge,
    input rx,
    output reg [7:0] data,
    output reg data_ready,
    output reg framing_error
);
    reg [7:0] rx_data = 0;
    reg [3:0] bit_count = 0;
    reg rx_active = 0;
    reg start_bit = 0;

    always @(posedge clk or negedge rst) begin
        if (!rst) begin
            rx_data <= 0;
            bit_count <= 0;
            rx_active <= 0;
            start_bit <= 0;
            data_ready <= 0;
            framing_error <= 0;
        end else begin
            if (!rx_active && !rx) begin
                start_bit <= 1;
                bit_count <= 0;
                rx_active <= 1;
            end else if (rx_active && baud_edge) begin
                rx_data[bit_count] <= rx;
                bit_count <= bit_count + 1;
                if (bit_count == 8) begin
                    rx_active <= 0;
                    start_bit <= 0;
                    data <= rx_data;
                    data_ready <= 1;
                end
            end else if (!rx_active && start_bit && rx) begin
                framing_error <= 1;
                start_bit <= 0;
            end
        end
    end
endmodule

