            end else if (pwm_out == 1'b0 && comparator_out == 1'b1) begin
                pwm_out <= 1'b1;
            end
        end
    end

endmodule

module LZW (
  input [7:0] data_in,
  output [7:0] data_out
);

parameter n = 12; // number of bits used to represent each code
parameter m = 4096; // maximum number of codes that can be used

reg [n-1:0] dict_code [0:m-1]; // dictionary codes
reg [7:0] dict_string [0:m-1]; // dictionary strings
reg [n-1:0] next_code; // next available code
reg [n-1:0] current_code; // current code being processed
reg [7:0] current_string [0:n-1]; // current string being processed
reg [n-1:0] previous_code; // previous code processed
reg [7:0] output_string [0:255]; // output string
reg [7:0] output_char; // output character
reg [n-1:0] dict_size; // current size of dictionary
reg [7:0] input_char; // input character
reg [n-1:0] i; // loop counter

// initialize dictionary with single character strings
initial begin
  for (i = 0; i < 256; i = i + 1) begin
    dict_code[i] = i;
    dict_string[i] = i;
  end
  dict_size = 256;
  next_code = 256;
end

// compression logic
always @(posedge clk) begin
  // read input character
  input_char = data_in;
  // check if current string + input character is in dictionary
  if (dict_code[current_code + input_char] != 0) begin
    // add input character to current string
    current_string[n-1] = input_char;
    // update current code
    current_code = dict_code[current_code + input_char];
  end else begin
    // output previous code
    data_out = previous_code;
    // add current string + input character to dictionary
    dict_code[current_code + input_char] = next_code;
    dict_string[next_code] = current_string;
    next_code = next_code + 1;
    // start new string with input character
    current_string[n-1] = input_char;
    current_code = input_char;
  end
  // check if dictionary is full
  if (next_code == m) begin
    // reset dictionary
    for (i = 0; i < 256; i = i + 1) begin
      dict_code[i] = i;
      dict_string[i] = i;
    end
    dict_size = 256;
    next_code = 256;
  end
end

// decompression logic
always @(posedge clk) begin
  // read input code
  current_code = data_in;
  // check if code is in dictionary
  if (dict_string[current_code] != 0) begin
    // output string
    output_string = dict_string[current_code];
    for (i = 0; i < n-1; i = i + 1) begin
      output_char = output_string[i];
      data_out = output_char;
    end
    // add previous string + first character of current string to dictionary
    current_string[0] = output_string[0];
    current_string[1:n-1] = dict_string[previous_code];
    dict_code[next_code] = previous_code;
    dict_string[next_code] = current_string;
    next_code = next_code + 1;
    // update previous code
    previous_code = current_code;
  end else begin
    // output previous string + first character of current string
    current_string[0] = dict_string[previous_code][0];
    current_string[1:n-1] = dict_string[previous_code];
    for (i = 0; i < n-1; i = i + 1) begin
      output_char = current_string[i];
      data_out = output_char;
    end
    // add previous string + first character of current string to dictionary
    dict_code[next_code] = previous_code;
    dict_string[next_code] = current_string;
    next_code = next_code + 1;
    // update previous code
    previous_code = current_code;
  end
  // check if dictionary is full
  if (next_code == m) begin
    // reset dictionary
    for (i = 0; i < 256; i = i + 1) begin
      dict_code[i] = i;
      dict_string[i] = i;
    end
    dict_size = 256;
    next_code = 256;
  end
end

endmodule

module adder_4bit (
    input [3:0] A,
    input [3:0] B,
    input sel,
    input rst,
    output [3:0] C
);

    reg [3:0] sum;
    reg [3:0] xor;

    always @(*) begin
        if (sel == 1) begin
            xor = A ^ B;
            sum = 4'b0;
        end else begin
            sum = A + B;
            xor = 4'b0;
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            C <= 4'b0;
        end else begin
            if (sel == 1) begin
                C <= xor;
            end else begin
                C <= sum;
            end
        end
    end

endmodule

module non_restoring_divider (
    input signed [3:0] dividend,
    input signed [3:0] divisor,
    output reg signed [3:0] quotient,
    output reg signed [3:0] remainder
);

reg signed [3:0] dividend_reg;
reg signed [3:0] divisor_reg;
reg signed [3:0] quotient_reg;
reg signed [3:0] remainder_reg;
reg [2:0] count;

always @(*) begin
    dividend_reg = dividend;
    divisor_reg = divisor;
    quotient_reg = 0;
    remainder_reg = 0;
    count = 3;

    if (divisor_reg == 0) begin
        quotient_reg = 4'bX;
        remainder_reg = 4'bX;
    end
    else begin
        if (dividend_reg < 0) begin
            dividend_reg = -dividend_reg;
            remainder_reg = -dividend_reg;
        end
        if (divisor_reg < 0) begin
            divisor_reg = -divisor_reg;
            quotient_reg[3] = 1;
        end

        while (count >= 0) begin
            remainder_reg = remainder_reg << 1;
            remainder_reg[0] = dividend_reg[3];
            dividend_reg = dividend_reg << 1;
            remainder_reg = remainder_reg - divisor_reg;

            if (remainder_reg < 0) begin
                quotient_reg[count] = 0;
                remainder_reg = remainder_reg + divisor_reg;
            end
            else begin
                quotient_reg[count] = 1;
            end

            count = count - 1;
        end

        if ((dividend < 0) ^ (divisor < 0)) begin
            quotient_reg = -quotient_reg;
            remainder_reg = -remainder_reg;
        end
    end

    quotient = quotient_reg;
    remainder = remainder_reg;
end

endmodule

module pulse_generator (
  input trigger,
  input clock,
  input reset,
  output pulse
);

parameter pulse_duration = 10; // pulse duration in clock cycles
parameter pulse_frequency = 1; // pulse frequency in Hz
parameter pulse_duty_cycle = 50; // pulse duty cycle in percent

reg [31:0] pulse_counter;
reg [31:0] pulse_duration_counter;
reg astable_mode;
reg monostable_mode;

always @(posedge clock) begin
  if (reset) begin
    pulse_counter <= 0;
    pulse_duration_counter <= 0;
    astable_mode <= 0;
    monostable_mode <= 0;
    pulse <= 0;
  end else begin
    if (trigger) begin
      pulse_duration_counter <= pulse_duration;
      monostable_mode <= 1;
    end
    if (pulse_duration_counter > 0) begin
      pulse <= 1;
      pulse_duration_counter <= pulse_duration_counter - 1;
    end else begin
      pulse <= 0;
      monostable_mode <= 0;
    end
    if (astable_mode) begin
      if (pulse_counter < (pulse_frequency * 2)) begin
        if (pulse_counter < (pulse_frequency * pulse_duty_cycle / 100)) begin
          pulse <= 1;
        end else begin
          pulse <= 0;
        end
        pulse_counter <= pulse_counter + 1;
      end else begin
        pulse_counter <= 0;
      end
    end
  end
end

always @(posedge clock) begin
  if (reset) begin
    pulse_counter <= 0;
    pulse_duration_counter <= 0;
    astable_mode <= 0;
    monostable_mode <= 0;
    pulse <= 0;
  end else begin
    if (!monostable_mode && !astable_mode) begin
      pulse_counter <= 0;
    end
    if (!monostable_mode && trigger) begin
      astable_mode <= 1;
    end
  end
end

endmodule

