module add_sub_module (
    input clk,
    input reset,       // Synchronous active-high reset
    input [3:0] a,     // 4-bit input for the first binary number
    input [3:0] b,     // 4-bit input for the second binary number
    input control,     // Control signal, 0 for addition and 1 for subtraction
    output [7:0] q     // 8-bit output from the active module
);

    reg [3:0] sum;     // 4-bit register to store the sum or difference
    wire carry_in;     // Carry input for the full adder or full subtractor
    wire carry_out;    // Carry output from the full adder or full subtractor

    // Instantiate the full adder and full subtractor
    full_adder fa(sum[0], a[0], b[0], carry_in, carry_out);
    full_subtractor fs(sum[0], a[0], b[0], carry_in, carry_out);

    // Connect the carry chain for the remaining bits
    genvar i;
    generate
        for (i = 1; i < 4; i = i + 1) begin : carry_chain
            full_adder fa(sum[i], a[i], b[i], carry_in, carry_out);
            full_subtractor fs(sum[i], a[i], b[i], carry_in, carry_out);
            assign carry_in = control ? ~carry_out : carry_out;
        end
    endgenerate

    // Output the result based on the control signal
    assign q = control ? {1'b0, sum} : {1'b0, sum + 1};

    // Parity checker to determine the reset value of the output register
    wire [7:0] parity_check = q ^ (q >> 1);
    wire parity = parity_check[0] ^ parity_check[1] ^ parity_check[2] ^ parity_check[3] ^ parity_check[4] ^ parity_check[5] ^ parity_check[6] ^ parity_check[7];
    reg [7:0] output_reg;
    always @(posedge clk) begin
        if (reset) begin
            output_reg <= parity ? 8'h01 : 8'hFF;
        end else begin
            output_reg <= q;
        end
    end

endmodule

// Full Adder module
module full_adder (
    output reg sum,
    input a,
    input b,
    input carry_in,
    output wire carry_out
);

    assign carry_out = (a & b) | (carry_in & a) | (carry_in & b);
    always @(a, b, carry_in) begin
        sum <= a ^ b ^ carry_in;
    end

endmodule

// Full Subtractor module
module full_subtractor (
    output reg diff,
    input a,
    input b,
    input borrow_in,
    output wire borrow_out
);

    assign borrow_out = (~a & b) | ((~a | b) & borrow_in);
    always @(a, b, borrow_in) begin
        diff <= a ^ b ^ borrow_in;
    end

endmodule

