module video_sys_jtag_uart_0_log_module (
    input clk,
    input [7:0] data,
    input strobe,
    input valid
);

    reg [31:0] text_handle; // for $fopen
    reg [7:0] last_data;
    reg [1:0] last_state;
    localparam IDLE = 2'b00, WRITE_ASCII = 2'b01, WRITE_BINARY = 2'b10;

    initial text_handle = $fopen ("video_sys_jtag_uart_0_output_stream.dat", "w");

    always @(posedge clk) begin
        if (valid && strobe) begin
            last_data <= data;
            last_state <= WRITE_ASCII;
            $fwrite (text_handle, "%b\n", data);
            $write("%c", ((data == 8'h0d) ? 8'h0a : data));
            $fflush (text_handle);
        end else if (last_state == WRITE_ASCII) begin
            last_state <= WRITE_BINARY;
            $write(" (");
        end else if (last_state == WRITE_BINARY) begin
            last_state <= IDLE;
            $write("%b", last_data);
            $write(")\n");
        end
    end

endmodule

module memory_testing_block (
  input [n-1:0] address,
  input [m-1:0] data,
  output pass
);

parameter k = 16; // number of memory locations
parameter w = 8; // number of bits per memory location

reg [w-1:0] memory [k-1:0];

// Read operation
always @ (address)
  data <= memory[address];

// Write operation
always @ (address, data)
  memory[address] <= data;

// Test operation
integer i;
initial begin
  pass <= 1;
  for (i = 0; i < k; i = i + 1) begin
    memory[i] <= i; // Write test pattern to memory location
    if (memory[i] != i) begin // Read back and verify test pattern
      pass <= 0;
      $display("Memory test failed at location %d", i);
    end
  end
end

endmodule

