module up_down_counter (
    input clk,
    input areset,
    input load,
    input up_down,
    input count_enable,
    output reg [3:0] count,
    output max_reached
);

reg [3:0] count_reg1, count_reg2;
reg max_reached_reg1, max_reached_reg2;

always @(posedge clk or negedge areset) begin
    if (areset == 0) begin
        count_reg1 <= 4'b0;
        count_reg2 <= 4'b0;
        max_reached_reg1 <= 1'b0;
        max_reached_reg2 <= 1'b0;
    end else begin
        if (load) begin
            count_reg1 <= count_enable ? count : count_reg1;
            count_reg2 <= count_reg1;
            max_reached_reg1 <= (up_down && count_reg1 == 4'b1111) || (!up_down && count_reg1 == 4'b0000) ? 1'b1 : 1'b0;
            max_reached_reg2 <= max_reached_reg1;
        end else if (count_enable) begin
            count_reg1 <= up_down ? count_reg2 + 4'b1 : count_reg2 - 4'b1;
            count_reg2 <= count_reg1;
            max_reached_reg1 <= (up_down && count_reg1 == 4'b1111) || (!up_down && count_reg1 == 4'b0000) ? 1'b1 : 1'b0;
            max_reached_reg2 <= max_reached_reg1;
        end
    end
end

assign count = count_reg2;
assign max_reached = max_reached_reg2;

endmodule

