  input wrclock,
  input wren,
  output reg [7:0] q
);

  reg [7:0] mem_array [4194303:0];
  reg [21:0] read_address;

  // Load initial contents of memory array from file
  initial $readmemh("cfi_flash_0.dat", mem_array);

  // Data read is asynchronous
  always @ (rdaddress) begin
    read_address <= rdaddress;
  end

  // Write data on rising edge of wrclock when wren is asserted
  always @ (posedge wrclock) begin
    if (wren) begin
      mem_array[wraddress] <= data;
    end
  end

  // Output data on rdclken
  always @ (posedge rdclken) begin
    q <= mem_array[read_address];
  end

endmodule

