  if (rst) begin
    wr_ptr <= 0;
    rd_ptr <= 0;
  end
  else begin
    wr_ptr <= next_wr_ptr;
    rd_ptr <= next_rd_ptr;
    if (wen) buffer[wr_ptr] <= din;
  end
