module binary_tree_mux(
  input [255:0] in,
  input [7:0] sel,
  output reg out
);

  reg [255:0] temp_in [0:7];
  reg [255:0] temp_out [0:3];

  integer i, j;

  always @(*)
  begin
    for(i=0; i<8; i=i+1)
      temp_in[i] = in[(i*32+31):i*32];
  end

  always @(*)
  begin
    for(i=0; i<4; i=i+1)
    begin
      j = i*2;
      if(sel[7-i] == 0)
        temp_out[i] = temp_in[j];
      else
        temp_out[i] = temp_in[j+1];
    end
  end

  always @(*)
