module edge_detect_and_counter (
  input               clk,
  input               rst_n,
  input               a,
  output reg          rise,
  output reg          down,
  output reg [1:0]    counter_out
);

  reg a_prev;
  reg [1:0] count;

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      a_prev <= 1'b0;
      count <= 2'b0;
      rise <= 1'b0;
      down <= 1'b0;
      counter_out <= 2'b0;
    end
    else begin
      a_prev <= a;
      if (a && ~a_prev) begin
        rise <= 1'b1;
        down <= 1'b0;
        count <= 2'b0;
      end
      else if (~a && a_prev) begin
        rise <= 1'b0;
        down <= 1'b1;
      end
      else begin
        rise <= 1'b0;
        down <= 1'b0;
        if (rise) begin
          count <= count + 1;
          if (count == 2'b11) begin
            count <= 2'b0;
          end
        end
      end
      counter_out <= count;
    end
  end

endmodule

