module MemoryModule
(
  input         clk,
  input         reset,

  input         mem_req_valid,
  output        mem_req_ready,
  input         mem_req_rw,
  input  [19:0] mem_req_addr,
  input  [15:0] mem_req_tag,

  input         mem_req_data_valid,
  output        mem_req_data_ready,
  input  [31:0] mem_req_data_bits,
  input  [3:0]  mem_req_data_mask,

  output reg    mem_resp_valid,
  output reg  [31:0] mem_resp_data,
  output reg  [15:0] mem_resp_tag
);

  localparam DATA_CYCLES = 4;
  localparam DEPTH = 2*512*512;

  reg [1:0] cnt;
  reg [15:0] tag;
  reg state_busy, state_rw;
  reg [19:0] addr;

  reg [31:0] ram [DEPTH-1:0];
  wire do_write = mem_req_data_valid && mem_req_data_ready;
  wire [18:0] ram_addr = state_busy ? ( do_write ? addr[18:0] :  {addr[17:2], cnt} ) : {mem_req_addr[17:2], cnt};
  wire do_read = mem_req_valid && mem_req_ready && !mem_req_rw || state_busy && !state_rw;

  initial
  begin : zero
    integer i;
    for (i = 0; i < DEPTH; i = i+1)
      ram[i] = 32'h00000000;
  end

  wire [31:0] masked_din;

  generate
    genvar i;
    for(i = 0; i < 32; i=i+1) begin : byte_mask
      assign masked_din[i] = mem_req_data_mask[i/8] ? mem_req_data_bits[i] : ram[ram_addr][i];
    end
  endgenerate

  always @(posedge clk)
  begin
    if (reset)
      state_busy <= 1'b0;
    else if ((do_read && cnt == DATA_CYCLES-1 || do_write))
      state_busy <= 1'b0;
    else if (mem_req_valid && mem_req_ready)
      state_busy <= 1'b1;

    if (!state_busy && mem_req_valid)
    begin
      state_rw <= mem_req_rw;
      tag <= mem_req_tag;
      addr <= mem_req_addr;
    end

    if (reset)
      cnt <= 2'b0;
    else if(do_read)
      cnt <= cnt + 2'b1;

    if (do_write)
      ram[ram_addr] <= masked_din;
    else
      mem_resp_data <= ram[ram_addr];

    if (reset)
      mem_resp_valid <= 1'b0;
    else
      mem_resp_valid <= do_read;

    mem_resp_tag <= state_busy ? tag : mem_req_tag;
  end

  assign mem_req_ready = !state_busy;
  assign mem_req_data_ready = state_busy && state_rw;

endmodule

