module i2s_transmitter #
(
    parameter DATA_WIDTH = 16,
    parameter MCLK_DIV = 2,
    parameter FS = 128
)
(
    input clk,
    input signed [DATA_WIDTH-1:0] left_chan,
    input signed [DATA_WIDTH-1:0] right_chan,
    output reg sdata,
    output reg mck,
    output reg sck,
    output reg lrclk
);

reg [DATA_WIDTH-1:0] left_data;
reg [DATA_WIDTH-1:0] right_data;
reg [MCLK_DIV-1:0] mclk_div;
reg [7:0] bit_counter;
reg [1:0] word_counter;

always @(posedge clk) begin
    if (mclk_div == 0) begin
        mck <= ~mck;
        mclk_div <= MCLK_DIV-1;
    end
    else begin
        mclk_div <= mclk_div - 1;
    end

    if (bit_counter == 0) begin
        sck <= ~sck;
    end

    if (word_counter == 0) begin
        lrclk <= ~lrclk;
        left_data <= left_chan;
        right_data <= right_chan;
    end

    if (bit_counter < DATA_WIDTH) begin
        sdata <= {left_data[DATA_WIDTH-1-bit_counter], right_data[DATA_WIDTH-1-bit_counter]};
        bit_counter <= bit_counter + 1;
    end
    else begin
        bit_counter <= 0;
        word_counter <= word_counter + 1;
    end

    if (word_counter == FS-1) begin
        word_counter <= 0;
    end
end

endmodule

