module fft (
    input [7:0] X_real [7:0],
    input [7:0] X_imag [7:0],
    output [7:0] Y [7:0]
);

    // Declare internal wires and registers
    wire [7:0] W_real [7:0];
    wire [7:0] W_imag [7:0];
    wire [7:0] U_real [7:0];
    wire [7:0] U_imag [7:0];
    wire [7:0] V_real [7:0];
    wire [7:0] V_imag [7:0];
    wire [7:0] Y_real [7:0];
    wire [7:0] Y_imag [7:0];
    reg [7:0] X_real_shift [7:0];
    reg [7:0] X_imag_shift [7:0];
    reg [7:0] Y_mag [7:0];
    integer i, j, k, L, m, n;
    shift_register sr (
        .D0(X_real_shift[0]), .D1(X_real_shift[1]), .D2(X_real_shift[2]), .D3(X_real_shift[3]),
        .D4(X_real_shift[4]), .D5(X_real_shift[5]), .D6(X_real_shift[6]), .D7(X_real_shift[7]),
        .D8(X_imag_shift[0]), .D9(X_imag_shift[1]), .D10(X_imag_shift[2]), .D11(X_imag_shift[3]),
        .D12(X_imag_shift[4]), .D13(X_imag_shift[5]), .D14(X_imag_shift[6]), .D15(X_imag_shift[7]),
        .LOAD(LOAD), .RESET(RESET),
        .Q0(U_real[0]), .Q1(U_real[1]), .Q2(U_real[2]), .Q3(U_real[3]),
        .Q4(U_imag[0]), .Q5(U_imag[1]), .Q6(U_imag[2]), .Q7(U_imag[3])
    );

    // Generate twiddle factors
    generate
        for (i = 0; i < 8; i = i + 1) begin : twiddle_factors
            assign W_real[i] = $signed($cos((2 * $pi * i) / 8) * 128);
            assign W_imag[i] = $signed(-$sin((2 * $pi * i) / 8) * 128);
        end
    endgenerate

    // Perform radix-2 FFT using Cooley-Tukey algorithm
    generate
        for (L = 1; L <= 4; L = L * 2) begin : stages
            for (j = 0; j < L; j = j + 1) begin : groups
                for (k = j; k < 8; k = k + 2 * L) begin : butterflies
                    assign m = k + L;
                    assign n = k + 2 * L;
                    assign {U_real[k], U_imag[k]} = {X_real_shift[k], X_imag_shift[k]};
                    assign {U_real[m], U_imag[m]} = {X_real_shift[m], X_imag_shift[m]};
                    assign {V_real[k], V_imag[k]} = {U_real[k] + U_real[m], U_imag[k] + U_imag[m]};
                    assign {V_real[m], V_imag[m]} = {($signed(U_real[k]) - $signed(U_real[m])) * W_real[j] - ($signed(U_imag[k]) - $signed(U_imag[m])) * W_imag[j], ($signed(U_real[k]) - $signed(U_real[m])) * W_imag[j] + ($signed(U_imag[k]) - $signed(U_imag[m])) * W_real[j]};
                    assign {Y_real[k], Y_imag[k]} = {V_real[k], V_imag[k]};
                    assign {Y_real[m], Y_imag[m]} = {V_real[m], V_imag[m]};
                end
            end
            assign {X_real_shift, X_imag_shift} = {Y_real, Y_imag};
        end
    endgenerate

    // Compute magnitude of each complex number
    generate
        for (i = 0; i < 8; i = i + 1) begin : magnitude
            assign Y_mag[i] = $sqrt(Y_real[i] ** 2 + Y_imag[i] ** 2);
        end
    endgenerate

    // Assign output
    assign Y = Y_mag;

endmodule

