module binary_adder (
    Y   ,
    A,
    B
);

    output [1:0] Y;
    input  [1:0] A;
    input  [1:0] B;

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire carry;
    sky130_fd_sc_ms__o2bb2ai adder1 (
        .Y(Y[0]),
        .A1_N(A[0]),
        .A2_N(B[0]),
        .B1(carry),
        .B2(1'b0)
    );
    sky130_fd_sc_ms__o2bb2ai adder2 (
        .Y(Y[1]),
        .A1_N(A[1]),
        .A2_N(B[1]),
        .B1(carry),
        .B2(1'b0)
    );
    assign carry = (A[0] & B[0]) | (A[0] & carry) | (B[0] & carry);

    always @(*) begin
        if (A[1] == 0 && B[1] == 0) begin
            Y[1] = carry;
        end else if (A[1] == 0 && B[1] == 1) begin
            if (carry == 0) begin
                Y[1] = 1'b1;
            end else begin
                $display("Error: Binary addition overflow");
            end
        end else if (A[1] == 1 && B[1] == 0) begin
            if (carry == 0) begin
                Y[1] = 1'b1;
            end else begin
                $display("Error: Binary addition overflow");
            end
        end else begin // A[1] == 1 && B[1] == 1
            if (carry == 0) begin
                $display("Error: Binary addition overflow");
            end else begin
                Y[1] = 1'b0;
            end
        end
    end

endmodule

