module RIPPLEADD_64 (A, B, Cin, S, Cout);
input [63:0] A, B;
input Cin;
output [63:0] S;
output Cout;

wire [63:0] C;
assign C[0] = Cin;
genvar i;
generate
    for (i = 0; i < 64; i = i + 1) begin : full_adder
        FULLADDER_1BIT FA(
            .A(A[i]),
            .B(B[i]),
            .Cin(C[i]),
            .S(S[i]),
            .Cout(C[i+1])
        );
    end
endgenerate
assign Cout = C[64];

endmodule

module FULLADDER_1BIT (A, B, Cin, S, Cout);
input A, B, Cin;
output S, Cout;

assign S = A ^ B ^ Cin;
assign Cout = (A & B) | (Cin & (A ^ B));

endmodule

module AXIProtocolConverter(
    input wire aclk,
    input wire incr_next_pending,
    input wire wrap_next_pending,
    input wire sel_first_i,
    input wire [51:0] m_payload_i_reg,
    input wire [11:0] axaddr_incr,
    input wire [2:0] D,
    input wire [3:0] axaddr_offset_r_reg,
    input wire [1:0] state_reg,
    input wire [3:0] wrap_second_len_r_reg,
    input wire [0:0] axlen_cnt_reg,
    output reg next_pending_r_reg,
    output reg sel_first,
    output reg sel_first_reg_0,
    output reg sel_first_0,
    output reg sel_first_reg,
    output reg next_pending_r_reg_0,
    output reg next_pending_r_reg_1,
    output reg [11:0] m_axi_awaddr,
    output reg [3:0] S,
    output reg [3:0] wrap_second_len_r_reg_0,
    output reg [3:0] axaddr_offset_r_reg_0,
    output reg E,
    output reg [23:0] Q,
    output reg [3:0] axaddr_offset_r_reg_1,
    output reg [0:0] state_reg_0,
    output reg [0:0] state_reg_1_0,
    output reg [0:0] axlen_cnt_reg_0
);

reg [0:0] axlen_cnt_reg_0_next;
reg [3:0] axaddr_offset_r_reg_1_next;

always @(posedge aclk) begin
    // Update axlen_cnt_reg_0
    axlen_cnt_reg_0 <= axlen_cnt_reg_0_next;

    // Update next_pending_r_reg
    next_pending_r_reg <= wrap_next_pending || incr_next_pending;

    // Update sel_first
    sel_first <= sel_first_i;

    // Update sel_first_reg_0
    sel_first_reg_0 <= sel_first_i;

    // Update sel_first_0
    sel_first_0 <= sel_first_i;

    // Update sel_first_reg
    sel_first_reg <= sel_first_i;

    // Update next_pending_r_reg_0
    next_pending_r_reg_0 <= wrap_next_pending || incr_next_pending;

    // Update next_pending_r_reg_1
    next_pending_r_reg_1 <= wrap_next_pending || incr_next_pending;

    // Update m_axi_awaddr
    m_axi_awaddr <= axaddr_offset_r_reg + axaddr_incr;

    // Update S
    case(state_reg)
        0: S <= 1;
        1: S <= 2;
        2: S <= 3;
        3: S <= 0;
    endcase

    // Update wrap_second_len_r_reg_0
    wrap_second_len_r_reg_0 <= wrap_second_len_r_reg;

    // Update axaddr_offset_r_reg_0
    axaddr_offset_r_reg_0 <= axaddr_offset_r_reg;

    // Update E
    E <= D == 2'b10;

    // Update Q
    Q <= {axlen_cnt_reg, axlen_cnt_reg_0, wrap_second_len_r_reg};

    // Update axaddr_offset_r_reg_1
    axaddr_offset_r_reg_1 <= axaddr_offset_r_reg_1_next;

    // Update state_reg_0
    state_reg_0 <= state_reg[1];

    // Update state_reg_1_0
    state_reg_1_0 <= state_reg[0];

    // Update axlen_cnt_reg_0_next
    case(state_reg)
        0: axlen_cnt_reg_0_next <= 0;
        1: axlen_cnt_reg_0_next <= wrap_second_len_r_reg;
        2: axlen_cnt_reg_0_next <= 0;
        3: axlen_cnt_reg_0_next <= axlen_cnt_reg;
    endcase

    // Update axaddr_offset_r_reg_1_next
    axaddr_offset_r_reg_1_next <= axaddr_offset_r_reg + axaddr_incr;
end

endmodule

