module fpga_module(
    input wire clk_in,
    input wire reset_in,
    input wire [6:0] chanAddr_in,
    input wire [7:0] h2fData_in,
    input wire h2fValid_in,
    output wire h2fReady_out,
    output wire [7:0] f2hData_out,
    output wire f2hValid_out,
    input wire f2hReady_in,
    output wire [7:0] sseg_out,
    output wire [3:0] anode_out,
    output wire [7:0] led_out,
    input wire [7:0] sw_in
);

    reg [7:0] reg0 = 8'h00;
    reg [15:0] checksum = 16'h0000;
    wire [15:0] checksum_next;
    wire [7:0] reg0_next;
    wire [3:0] flags;

    // Infer registers
    always @(posedge clk_in) begin
        if (reset_in == 1'b1) begin
            reg0 <= 8'h00;
            checksum <= 16'h0000;
        end
        else begin
            reg0 <= reg0_next;
            checksum <= checksum_next;
        end
    end

    // Drive register inputs for each channel when the host is writing
    assign reg0_next =
        (chanAddr_in == 7'b0000000 && h2fValid_in == 1'b1) ? h2fData_in :
        reg0;
    assign checksum_next =
        (chanAddr_in == 7'b0000000 && h2fValid_in == 1'b1) ?
            checksum + h2fData_in :
        (chanAddr_in == 7'b0000001 && h2fValid_in == 1'b1) ?
            {h2fData_in, checksum[7:0]} :
        (chanAddr_in == 7'b0000010 && h2fValid_in == 1'b1) ?
            {checksum[15:8], h2fData_in} :
        checksum;

    // Select values to return for each channel when the host is reading
    assign f2hData_out =
        (chanAddr_in == 7'b0000000) ? sw_in :
        (chanAddr_in == 7'b0000001) ? checksum[15:8] :
        (chanAddr_in == 7'b0000010) ? checksum[7:0] :
        8'h00;

    // Assert that there's always data for reading, and always room for writing
    assign f2hValid_out = 1'b1;
    assign h2fReady_out = 1'b1;

    // LEDs and 7-seg display
    assign led_out = reg0;
    assign flags = {3'b00, f2hReady_in, reset_in};
    seven_seg seven_seg(
        .clk_in(clk_in),
        .data_in(checksum),
        .dots_in(flags),
        .segs_out(sseg_out),
        .anodes_out(anode_out)
    );
endmodule

module Mult4x4
(
 input wire [3:0] A,
 input wire [3:0] B,
 output wire [7:0] Result
);

wire [5:0] wResInt1,wResInt2;

LUT # ( 4 ) LUT1
(
	.A(A),
	.B(B[1:0]),
	.Result(wResInt1)
);

LUT # ( 4 ) LUT2
(
	.A(A),
	.B(B[3:2]),
	.Result(wResInt2)
);

