module top_module (
    input [7:0] in,
    output reg out
);

    // NOT gate implementation using NAND gates
    wire nand_out;
    assign nand_out = ~(in & in);

    // Binary-to-Gray code conversion
    wire [7:0] gray_in;
    assign gray_in[0] = in[0];
    assign gray_in[1] = in[0] ^ in[1];
    assign gray_in[2] = in[1] ^ in[2];
    assign gray_in[3] = in[2] ^ in[3];
    assign gray_in[4] = in[3] ^ in[4];
    assign gray_in[5] = in[4] ^ in[5];
    assign gray_in[6] = in[5] ^ in[6];
    assign gray_in[7] = in[6] ^ in[7];

    // Gray-to-binary code conversion
    wire [7:0] gray_out;
    assign gray_out[7] = gray_in[7];
    assign gray_out[6] = gray_out[7] ^ gray_in[6];
    assign gray_out[5] = gray_out[6] ^ gray_in[5];
    assign gray_out[4] = gray_out[5] ^ gray_in[4];
    assign gray_out[3] = gray_out[4] ^ gray_in[3];
    assign gray_out[2] = gray_out[3] ^ gray_in[2];
    assign gray_out[1] = gray_out[2] ^ gray_in[1];
    assign gray_out[0] = gray_out[1] ^ gray_in[0];

    // Priority encoder
    wire [2:0] priority;
    assign priority = gray_out[7:5] > gray_out[4:2] ? (gray_out[7:5] > gray_out[1:0] ? 3 : 2) : (gray_out[4:2] > gray_out[1:0] ? 1 : 0);

    // Final output
    always @(*) begin
        if (in == 0) begin
            out = 0;
        end else begin
            case (priority)
                0: out = nand_out[7];
                1: out = nand_out[6];
                2: out = nand_out[5];
                3: out = nand_out[4];
            endcase
        end
    end

endmodule

