		end else if (S == 1'b1) begin
			Q <= 1'b1;
		end else begin
			Q <= D;
		end
	end

`ifdef ICE40_HX
	specify
		$setup(D, negedge C, 21);
		$setup(R, negedge C, 9);
		$hold(Q, negedge C, 10);
	endspecify
`endif

`ifdef ICE40_LP
	specify
		$setup(D, negedge C, 33);
		$setup(R, negedge C, 15);
		$hold(Q, negedge C, 15);
	endspecify
`endif

`ifdef ICE40_U
	specify
		$setup(D, negedge C, 45);
		$setup(R, negedge C, 21);
		$hold(Q, negedge C, 20);
	endspecify
`endif

endmodule

module karnaugh_map(
  input wire A, B, C, D, E,
  output reg F
);

  parameter ONE = 1'b1;
  parameter ZERO = 1'b0;

  always @* begin
    case({A, B, C, D})
      4'b0000: F = E ? ONE : ZERO;
      4'b0001: F = E ? ONE : ZERO;
      4'b0011: F = E ? ZERO : ONE;
      4'b0010: F = E ? ZERO : ONE;
      4'b0110: F = E ? ONE : ZERO;
      4'b0111: F = E ? ONE : ZERO;
      4'b0101: F = E ? ZERO : ONE;
      4'b0100: F = E ? ZERO : ONE;
      default: F = ZERO;
    endcase
  end

endmodule

module gfx_wbm_write(
  // WB signals
  input         clk_i,
  input         rst_i,
  output        cyc_o,
  output        stb_o,
  output [2:0]  cti_o,
  output [1:0]  bte_o,
  output        we_o,
  output [31:0] adr_o,
  output [3:0]  sel_o,
  input         ack_i,
  input         err_i,
  input [31:0]  dat_o,
  output        sint_o,
  // Control signals
  input         write_i,
  output        ack_o,
  input [31:0]  render_addr_i,
  input [3:0]   render_sel_i,
  input [31:0]  render_dat_i
);

  reg [1:0] state;
  reg [31:0] wb_addr;
  reg [3:0] wb_sel;
  reg [31:0] wb_data;
  reg wb_write;

  assign cyc_o = (state == 0);
  assign stb_o = (state == 0);
  assign cti_o = (state == 0) ? 3'b001 : 3'b000;
  assign bte_o = (state == 0) ? 2'b00 : 2'b11;
  assign we_o = wb_write;
  assign adr_o = wb_addr;
  assign sel_o = wb_sel;

  always @(posedge clk_i) begin
    if (rst_i) begin
      state <= 2'b00;
      wb_write <= 0;
      ack_o <= 0;
      wb_addr <= 0;
      wb_sel <= 0;
      wb_data <= 0;
    end else begin
      case (state)
        2'b00: begin // Idle
          if (write_i) begin
            wb_write <= 1;
            wb_addr <= render_addr_i;
            wb_sel <= render_sel_i;
            wb_data <= render_dat_i;
            state <= 2'b01;
          end
        end
        2'b01: begin // Write
          if (ack_i) begin
            ack_o <= 1;
            wb_write <= 0;
            state <= 2'b00;
          end else if (err_i) begin
            state <= 2'b10;
          end
        end
        2'b10: begin // Error
          if (ack_i) begin
            state <= 2'b00;
          end
        end
      endcase
    end
  end

endmodule

module EchoCancellation (
  input signed [n-1:0] in,
  input signed [m-1:0] fb,
  output signed [n-1:0] out
);

parameter n = 4; // number of input and output signals
parameter m = 3; // number of feedback signals

reg signed [m-1:0] fb_delayed [0:n-1];
reg signed [m-1:0] fb_filtered [0:n-1];

// Delay line
always @(posedge clk) begin
  for (i = 0; i < n; i = i + 1) begin
    fb_delayed[i] <= {fb_delayed[i][m-2:0], fb[i]};
  end
end

// Filter
always @(posedge clk) begin
  for (i = 0; i < n; i = i + 1) begin
    fb_filtered[i] <= (fb_delayed[i][0] + fb_delayed[i][1] + fb_delayed[i][2])/3;
  end
end

// Subtraction
always @(posedge clk) begin
  for (i = 0; i < n; i = i + 1) begin
    out[i] <= in[i] - fb_filtered[i];
  end
end

endmodule

module multiplier (
  input [3:0] a,
  input [3:0] b,
  input clk,
  output [7:0] result,
  output done
);

  reg [7:0] partial_products;
  reg [2:0] state;
  reg done_reg;

  always @(posedge clk) begin
    case (state)
      2'b00: begin // idle
        if (done_reg) begin
          state <= 2'b01; // multiply
        end
      end
      2'b01: begin // multiply
        partial_products <= {a, 4'b0} * {b, 4'b0};
        state <= 2'b10; // sum
      end
      2'b10: begin // sum
        result <= partial_products[7:0] + partial_products[15:8];
        done_reg <= 1;
        state <= 2'b00; // idle
      end
    endcase
  end

  assign done = done_reg;

endmodule

module traffic_light(
    input clk,
    input rst,
    output reg red,
    output reg yellow,
    output reg green
);

// Define the states of the state machine
parameter STATE_RED = 2'b00;
parameter STATE_YELLOW = 2'b01;
parameter STATE_GREEN = 2'b10;

// Define the state and counter variables
reg [1:0] state;
reg [5:0] counter;

// Initialize the state and counter variables
initial begin
    state = STATE_RED;
    counter = 0;
end

// Define the state machine
always @(posedge clk, posedge rst) begin
    if (rst) begin
        state <= STATE_RED;
        counter <= 0;
    end else begin
        case (state)
            STATE_RED: begin
                red <= 1;
                yellow <= 0;
                green <= 0;
                counter <= counter + 1;
                if (counter == 20) begin
                    state <= STATE_YELLOW;
                    counter <= 0;
                end
            end
            STATE_YELLOW: begin
                red <= 0;
                yellow <= 1;
                green <= 0;
                counter <= counter + 1;
                if (counter == 5) begin
                    state <= STATE_GREEN;
                    counter <= 0;
                end
            end
            STATE_GREEN: begin
                red <= 0;
                yellow <= 0;
                green <= 1;
                counter <= counter + 1;
                if (counter == 15) begin
                    state <= STATE_RED;
                    counter <= 0;
                end
            end
        endcase
    end
end

endmodule

module hazard_control_unit(
    input INSTRUCTION_CACHE_READY,
    input DATA_CACHE_READY,
    input PC_MISPREDICTED,
    input [4:0] RS1_ADDRESS_EXECUTION,
    input [4:0] RS2_ADDRESS_EXECUTION,
    input [2:0] DATA_CACHE_LOAD_DM1,
    input [4:0] RD_ADDRESS_DM1,
    input [2:0] DATA_CACHE_LOAD_DM2,
    input [4:0] RD_ADDRESS_DM2,
    input [2:0] DATA_CACHE_LOAD_DM3,
    input [4:0] RD_ADDRESS_DM3,
    output CLEAR_INSTRUCTION_FETCH_STAGE,
    output CLEAR_DECODING_STAGE,
    output CLEAR_EXECUTION_STAGE,
    output STALL_PROGRAME_COUNTER_STAGE,
    output STALL_INSTRUCTION_CACHE,
    output STALL_INSTRUCTION_FETCH_STAGE,
    output STALL_DECODING_STAGE,
    output STALL_EXECUTION_STAGE,
    output STALL_DATA_MEMORY_STAGE
    );

    reg CLEAR_INSTRUCTION_FETCH_STAGE_reg;
    reg CLEAR_DECODING_STAGE_reg;
    reg CLEAR_EXECUTION_STAGE_reg;
    reg STALL_PROGRAME_COUNTER_STAGE_reg;
    reg STALL_INSTRUCTION_CACHE_reg;
    reg STALL_INSTRUCTION_FETCH_STAGE_reg;
    reg STALL_DECODING_STAGE_reg;
    reg STALL_EXECUTION_STAGE_reg;
    reg STALL_DATA_MEMORY_STAGE_reg;

    always @(*) begin
        CLEAR_INSTRUCTION_FETCH_STAGE_reg = 0;
        CLEAR_DECODING_STAGE_reg = 0;
        CLEAR_EXECUTION_STAGE_reg = 0;
        STALL_PROGRAME_COUNTER_STAGE_reg = 0;
        STALL_INSTRUCTION_CACHE_reg = 0;
        STALL_INSTRUCTION_FETCH_STAGE_reg = 0;
        STALL_DECODING_STAGE_reg = 0;
        STALL_EXECUTION_STAGE_reg = 0;
        STALL_DATA_MEMORY_STAGE_reg = 0;

        // Handle branch misprediction
        if (PC_MISPREDICTED) begin
            CLEAR_INSTRUCTION_FETCH_STAGE_reg = 1;
            CLEAR_DECODING_STAGE_reg = 1;
        end

        // Handle data hazards
        if (((RS1_ADDRESS_EXECUTION == RD_ADDRESS_DM1) || (RS2_ADDRESS_EXECUTION == RD_ADDRESS_DM1)) && (DATA_CACHE_LOAD_DM1 != 3'b000)) begin
            CLEAR_DECODING_STAGE_reg = 0;
            CLEAR_EXECUTION_STAGE_reg = 1;
            STALL_PROGRAME_COUNTER_STAGE_reg = 1;
            STALL_INSTRUCTION_CACHE_reg = 1;
            STALL_INSTRUCTION_FETCH_STAGE_reg = 1;
            STALL_DECODING_STAGE_reg = 1;
            STALL_EXECUTION_STAGE_reg = 1;
        end
        else if (((RS1_ADDRESS_EXECUTION == RD_ADDRESS_DM2) || (RS2_ADDRESS_EXECUTION == RD_ADDRESS_DM2)) && (DATA_CACHE_LOAD_DM2 != 3'b000)) begin
            CLEAR_DECODING_STAGE_reg = 0;
            CLEAR_EXECUTION_STAGE_reg = 1;
            STALL_PROGRAME_COUNTER_STAGE_reg = 1;
            STALL_INSTRUCTION_CACHE_reg = 1;
            STALL_INSTRUCTION_FETCH_STAGE_reg = 1;
            STALL_DECODING_STAGE_reg = 1;
            STALL_EXECUTION_STAGE_reg = 1;
        end
        else if (((RS1_ADDRESS_EXECUTION == RD_ADDRESS_DM3) || (RS2_ADDRESS_EXECUTION == RD_ADDRESS_DM3)) && (DATA_CACHE_LOAD_DM3 != 3'b000)) begin
            CLEAR_DECODING_STAGE_reg = 0;
            CLEAR_EXECUTION_STAGE_reg = 1;
            STALL_PROGRAME_COUNTER_STAGE_reg = 1;
            STALL_INSTRUCTION_CACHE_reg = 1;
            STALL_INSTRUCTION_FETCH_STAGE_reg = 1;
            STALL_DECODING_STAGE_reg = 1;
            STALL_EXECUTION_STAGE_reg = 1;
        end
        else if (INSTRUCTION_CACHE_READY == 0) begin
            CLEAR_DECODING_STAGE_reg = 1;
            CLEAR_EXECUTION_STAGE_reg = 0;
            STALL_PROGRAME_COUNTER_STAGE_reg = 1;
            STALL_INSTRUCTION_CACHE_reg = 0;
            STALL_INSTRUCTION_FETCH_STAGE_reg = 1;
            STALL_DECODING_STAGE_reg = 1;
            STALL_EXECUTION_STAGE_reg = 0;
        end
    end

    assign CLEAR_INSTRUCTION_FETCH_STAGE = CLEAR_INSTRUCTION_FETCH_STAGE_reg;
    assign CLEAR_DECODING_STAGE = CLEAR_DECODING_STAGE_reg;
    assign CLEAR_EXECUTION_STAGE = CLEAR_EXECUTION_STAGE_reg;
    assign STALL_PROGRAME_COUNTER_STAGE = STALL_PROGRAME_COUNTER_STAGE_reg;
    assign STALL_INSTRUCTION_CACHE = STALL_INSTRUCTION_CACHE_reg;
    assign STALL_INSTRUCTION_FETCH_STAGE = STALL_INSTRUCTION_FETCH_STAGE_reg;
    assign STALL_DECODING_STAGE = STALL_DECODING_STAGE_reg;
    assign STALL_EXECUTION_STAGE = STALL_EXECUTION_STAGE_reg;
    assign STALL_DATA_MEMORY_STAGE = STALL_DATA_MEMORY_STAGE_reg;

endmodule

module full_adder(
    input A, B, Cin,
    output Sum, Cout
    );
    assign Sum = A ^ B ^ Cin;
    assign Cout = (A & B) | (A & Cin) | (B & Cin);
endmodule

module adder_4bit(
    input [3:0] A, B,
    input Cin,
    output [3:0] Sum,
    output Cout
    );
    wire [3:0] S;
    wire C1, C2, C3;
    full_adder FA1(.A(A[0]), .B(B[0]), .Cin(Cin), .Sum(S[0]), .Cout(C1));
    full_adder FA2(.A(A[1]), .B(B[1]), .Cin(C1), .Sum(S[1]), .Cout(C2));
    full_adder FA3(.A(A[2]), .B(B[2]), .Cin(C2), .Sum(S[2]), .Cout(C3));
    full_adder FA4(.A(A[3]), .B(B[3]), .Cin(C3), .Sum(S[3]), .Cout(Cout));
    assign Sum = S;
endmodule

module jt12_pg_sum (
    input       [ 3:0]  mul,        
    input       [19:0]  phase_in,
    input               pg_rst,
    input signed [5:0]  detune_signed,
    input       [16:0]  phinc_pure,

    output reg  [19:0]  phase_out,
    output reg  [ 9:0]  phase_op
);

reg [16:0] phinc_premul; 
reg [19:0] phinc_mul;

always @(*) begin
    phinc_premul = phinc_pure + {{11{detune_signed[5]}},detune_signed};
    phinc_mul    = ( mul==4'd0 ) ? {4'b0,phinc_premul[16:1]} : ({3'd0,phinc_premul} * mul);

    phase_out   = pg_rst ? 20'd0 : (phase_in + { phinc_mul});
    phase_op    = phase_out[19:10];
end

endmodule

