module bin2gray (
  input [3:0] binary,
  input sel0,
  input sel1,
  input sel2,
  output [3:0] gray
);

  // Standard binary to Gray code conversion algorithm
  assign gray[0] = binary[0] ^ ((sel0 & binary[1]) ^ ((sel0 | sel1) & binary[2]) ^ ((sel0 | sel1 | sel2) & binary[3]));
  assign gray[1] = binary[1] ^ ((sel0 & binary[2]) ^ ((sel0 | sel1) & binary[3]));
  assign gray[2] = binary[2] ^ ((sel0 & binary[3]) ^ ((sel0 | sel1) & binary[1]));
  assign gray[3] = binary[3] ^ ((sel0 & binary[2]) ^ ((sel0 | sel1) & binary[1]) ^ ((sel0 | sel1 | sel2) & binary[0]));

  // Reflected binary to Gray code conversion algorithm
  assign gray[0] = binary[0] ^ binary[1];
  assign gray[1] = binary[1] ^ binary[2];
  assign gray[2] = binary[2] ^ binary[3];
  assign gray[3] = binary[3];

  // Balanced ternary to Gray code conversion algorithm
  assign gray[0] = ~(sel2 & (binary[0] ^ binary[1])) & (binary[0] ^ binary[1]);
  assign gray[1] = ~(sel2 & (binary[1] ^ binary[2])) & (binary[1] ^ binary[2]);
  assign gray[2] = ~(sel2 & (binary[2] ^ binary[3])) & (binary[2] ^ binary[3]);
  assign gray[3] = ~(sel2 & (binary[0] ^ binary[3])) & (binary[0] ^ binary[3]);

endmodule

module adder_module (
    input [7:0] a,
    input [7:0] b,
    output [7:0] s,
    output carry_out
);
    wire [7:0] sum;
    wire [7:0] carry_sum;
    wire [7:0] carry_carry;
    wire [7:0] carry_diff;
    wire [7:0] diff;
    wire [7:0] borrow_diff;
    wire [7:0] borrow_borrow;
    wire [7:0] borrow_carry;
    wire [7:0] borrow_sum;
    wire [7:0] borrow_borrow_sum;
    wire [7:0] borrow_carry_sum;
    wire [7:0] carry_borrow_sum;

    assign sum = a + b;
    assign diff = a - b;

    assign carry_sum = {1'b0, a} + {1'b0, b};
    assign carry_carry = {1'b0, carry_sum} + {1'b0, carry_sum};
    assign carry_diff = {1'b0, a} + {1'b1, ~b} + 1'b1;

    assign borrow_diff = {1'b0, a} + {1'b1, ~b};
    assign borrow_borrow = {1'b0, ~a} + {1'b1, b} + 1'b1;
    assign borrow_carry = {1'b0, ~a} + {1'b0, carry_sum} + 1'b1;

    assign borrow_sum = {1'b0, a} + {1'b1, ~b} + 1'b1;
    assign borrow_borrow_sum = {1'b0, ~a} + {1'b1, b} + {1'b1, borrow_sum};
    assign borrow_carry_sum = {1'b0, ~a} + {1'b0, carry_sum} + {1'b1, borrow_sum};
    assign carry_borrow_sum = {1'b0, carry_sum} + {1'b1, ~borrow_sum} + 1'b1;

    assign s = in[0] ? diff : sum;
    assign carry_out = in[0] ? borrow_diff[8] : carry_sum[8];

endmodule

module priority_encoder_module (
    input [3:0] in,
    output [3:0] out
);
    wire [15:0] temp;
    wire [3:0] gray;

    assign temp = {in, 4'b0000};
    assign gray = {temp[4] ^ temp[3], temp[3] ^ temp[2], temp[2] ^ temp[1], temp[1] ^ temp[0]};

    assign out = (gray[3]) ? 4'b1110 : (gray[2]) ? 4'b1100 : (gray[1]) ? 4'b1000 : (gray[0]) ? 4'b0001 : 4'b0000;

endmodule

module top_module (
    input [7:0] a,
    input [7:0] b,
    input [3:0] in,
    output [7:0] s,
    output reg overflow,
    output [7:0] final_output
);
    wire [3:0] priority;
    wire [7:0] add_result;
    wire carry_out;

    adder_module adder_inst (
        .a(a),
        .b(b),
        .s(add_result),
        .carry_out(carry_out)
    );

    priority_encoder_module priority_inst (
        .in(in),
        .out(priority)
    );

    assign final_output = add_result + priority;
    assign overflow = (final_output[7] != add_result[7]) ? 1'b1 : 1'b0;

endmodule

module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input select,     // Select input to choose between register and counter
    output reg [7:0] reg_out, // 8-bit output from the register
    output [3:0] count_out,  // 4-bit output from the counter
    output [7:0] final_out   // 8-bit output from the functional module
);

reg [7:0] reg_data;
wire [3:0] count_data;
wire [7:0] adder_out;

register_module reg_inst (
    .clk(clk),
    .reset(reset),
    .d(reg_data),
    .q(reg_out)
);

counter_module count_inst (
    .clk(clk),
    .reset(reset),
    .q(count_data)
);

assign adder_out = reg_out + count_data;

functional_module func_inst (
    .reg_out(reg_out),
    .count_out(count_data),
    .final_out(adder_out)
);

always @(posedge clk) begin
    if (reset) begin
        reg_data <= 8'b0;
        count_out <= 4'b0;
    end else begin
        if (select) begin
            reg_data <= reg_data + 1;
        end else begin
            count_out <= count_out + 1;
        end
    end
end

endmodule

