endmodule

module SRAMtester (clk, adx, WrEn, data, out);
  output reg [10:0] adx;
  inout [15:0] data;
  output reg clk, WrEn;
  output reg [15:0] out;
  parameter d = 20;

  // generate a clock
  always #(d/2) clk = ~clk;

  assign data = WrEn ? 16'bZ : out;

  initial // Response
  begin
    $display("clk \t WrEn \t adx \t\t data \t\t out Time ");
    #d;
    clk = 0;
  end

  reg [31:0] i;
  initial // Stimulus
  begin
    $monitor("%b \t %b \t %b \t %b", clk, WrEn, adx, data, $time);
    WrEn = 1; adx = 0; out = 0;
    #(10*d)
    WrEn = 0;
    for(i = 0; i < 128; i = i + 1) begin
      adx = i;
      out = 127 - i;
      #d;
    end
    WrEn = 1;
    for(i = 0; i < 128; i = i + 1) begin
      adx = i;
      #d;
      out = data;
    end
    #(2*d); // end bias
    $stop; 
    $finish;
  end

endmodule

