        rd_addr <= rd_addr + 1;
        count <= count - 1;
        wr_full <= 1'b0;
        if (count == 5'b0)
          rd_empty <= 1'b1;
      end
    end
  end

  reg [15:0] mem [31:0];

  assign rd_data = mem[rd_addr];
  assign wr_full = (count == 5'b11111);

  always @ (posedge clk) begin
    if (wr_en)
      mem[wr_addr] <= wr_data;
  end

