wire [2:0] comb_out;
wire [7:0] xor_out;

combinational_circuit comb(.in(in), .and_out(comb_out[0]), .or_out(comb_out[1]), .xor_out(comb_out[2]));
top_module top(.in_16(in_16), .upper_byte(upper_byte), .lower_byte(lower_byte));

assign xor_out = {8{comb_out[2]}} ^ upper_byte;

always @(posedge clk) begin
    if (reset) begin
        final_out <= 8'b0;
    end else begin
        final_out <= xor_out & lower_byte;
    end
end

endmodule

module mux6to1_pipeline (
    input [2:0] sel,
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output reg [3:0] out
);

reg [3:0] and_out;
reg [3:0] stage1_out;
reg [3:0] stage2_out;

always @(*) begin
    case(sel)
        3'b000: stage1_out = data0;
        3'b001: stage1_out = data1;
        3'b010: stage1_out = data2;
        3'b011: stage1_out = data3;
        3'b100: stage1_out = data4;
        3'b101: stage1_out = data5;
        3'b110, 3'b111: stage1_out = {data0[1:0], data1[1:0], data2[1:0], data3[1:0], data4[1:0], data5[1:0]};
    endcase
end

always @(posedge clk) begin
    stage2_out <= stage1_out;
end

always @(posedge clk) begin
    and_out <= {stage2_out[1:0], stage2_out[3:2], stage2_out[5:4]} & 3'b11;
end

always @(posedge clk) begin
    if(sel == 3'b110 || sel == 3'b111) begin
        out <= and_out;
    end else begin
        out <= stage2_out;
    end
end

endmodule

module lpm_fifo_dc (
    input [lpm_width-1:0] data,
    input rdclock,
    input wrclock,
    input aclr,
    input rdreq,
    input wrreq,
    output rdfull,
    output wrfull,
    output rdempty,
    output wrempty,
    output [lpm_widthu-1:0] rdusedw,
    output [lpm_widthu-1:0] wrusedw,
    output [lpm_width-1:0] q
);
    parameter lpm_width = 1;
    parameter lpm_widthu = 1;
    parameter lpm_numwords = 2;
    parameter lpm_showahead = "OFF";
    parameter underflow_checking = "ON";
    parameter overflow_checking = "ON";
    parameter lpm_hint = "";
    parameter lpm_type = "lpm_fifo_dc";

    parameter delay_rdusedw = 1;
    parameter delay_wrusedw = 1;
    parameter rdsync_delaypipe = 3;
    parameter wrsync_delaypipe = 3;

    reg [lpm_width-1:0] fifo [lpm_numwords-1:0];
    reg [lpm_widthu-1:0] usedw_rd;
    reg [lpm_widthu-1:0] usedw_wr;
    reg [lpm_numwords-1:0] full_rd;
    reg [lpm_numwords-1:0] full_wr;
    reg [lpm_numwords-1:0] empty_rd;
    reg [lpm_numwords-1:0] empty_wr;
    reg [lpm_widthu-1:0] usedw_rd_next;
    reg [lpm_widthu-1:0] usedw_wr_next;
    reg [lpm_numwords-1:0] full_rd_next;
    reg [lpm_numwords-1:0] full_wr_next;
    reg [lpm_numwords-1:0] empty_rd_next;
    reg [lpm_numwords-1:0] empty_wr_next;
    reg [lpm_width-1:0] q_next;
    reg [lpm_width-1:0] data_next;

    always @(posedge rdclock) begin
        if (aclr) begin
            usedw_rd <= 0;
            full_rd <= 0;
            empty_rd <= lpm_numwords;
        end else if (rdreq && !rdfull) begin
            usedw_rd <= usedw_rd_next;
            full_rd <= full_rd_next;
            empty_rd <= empty_rd_next;
            q <= q_next;
        end
    end

    always @(posedge wrclock) begin
        if (aclr) begin
            usedw_wr <= 0;
            full_wr <= 0;
            empty_wr <= lpm_numwords;
        end else if (wrreq && !wrfull) begin
            usedw_wr <= usedw_wr_next;
            full_wr <= full_wr_next;
            empty_wr <= empty_wr_next;
            fifo[usedw_wr +: 1] <= data;
        end
    end

    always @* begin
        usedw_rd_next = usedw_rd;
        full_rd_next = full_rd;
        empty_rd_next = empty_rd;
        q_next = q;
        if (rdreq && !rdfull) begin
            usedw_rd_next = usedw_rd + 1;
            full_rd_next = full_rd;
            empty_rd_next = empty_rd - 1;
            q_next = fifo[usedw_rd];
        end
    end

    always @* begin
        usedw_wr_next = usedw_wr;
        full_wr_next = full_wr;
        empty_wr_next = empty_wr;
        if (wrreq && !wrfull) begin
            usedw_wr_next = usedw_wr + 1;
            full_wr_next = full_wr;
            empty_wr_next = empty_wr - 1;
        end
    end

    assign rdfull = full_rd[lpm_numwords-1];
    assign wrfull = full_wr[lpm_numwords-1];
    assign rdempty = empty_rd[lpm_numwords-1];
    assign wrempty = empty_wr[lpm_numwords-1];
    assign rdusedw = usedw_rd;
    assign wrusedw = usedw_wr;

endmodule

