module interrupt(
	input clock,

	input IEN_d,
	input IOF_d,
	input RTI_d,
	input branch_d,
	input IRQ,
	input [11:0] PC,

	output reg branch_ISR,
	output reg [11:0] ISR_adr
	);

	reg [11:0] return_adr;

	reg IEN_reg;
	reg IRQ_reg;
	reg I;

	initial begin
		IEN_reg = 0;
		return_adr = 0;
	end

	always @(posedge clock) begin
		if (IEN_d == 1)
			IEN_reg = 1;
		if (IOF_d == 1)
			IEN_reg = 0;

		if (I == 1) begin
			IEN_reg = 0;
			return_adr = PC;
		end

		IRQ_reg = IRQ;
	end

	always @(*) begin
		I <= IEN_reg & IRQ_reg & ~branch_d;
		if (I == 1) begin
			branch_ISR <= 1;
			ISR_adr <= 12'h1;
		end
		else if (RTI_d == 1) begin
			branch_ISR <= 1;
			ISR_adr <= return_adr;
		end
		else begin
			branch_ISR <= 0;
			ISR_adr <= 0;
		end
	end

endmodule

module barrel_shifter (
    input [7:0] data_in,
    input [2:0] shift_amt,
    input direction,
    output [7:0] shifted_data
);

    reg [7:0] shifted_out;

    always @(*) begin
        if (direction == 1'b0) begin // Left shift
            if (shift_amt == 3'b000) shifted_out = data_in;
            else if (shift_amt == 3'b001) shifted_out = {data_in[6:0], 1'b0};
            else if (shift_amt == 3'b010) shifted_out = {data_in[5:0], 2'b00};
            else if (shift_amt == 3'b011) shifted_out = {data_in[4:0], 3'b000};
            else if (shift_amt == 3'b100) shifted_out = {data_in[3:0], 4'b0000};
            else if (shift_amt == 3'b101) shifted_out = {data_in[2:0], 5'b00000};
            else if (shift_amt == 3'b110) shifted_out = {data_in[1:0], 6'b000000};
            else if (shift_amt == 3'b111) shifted_out = {data_in[0], 7'b0000000};
        end
        else begin // Right shift
            if (shift_amt == 3'b000) shifted_out = data_in;
            else if (shift_amt == 3'b001) shifted_out = {1'b0, data_in[7:1]};
            else if (shift_amt == 3'b010) shifted_out = {2'b00, data_in[7:2]};
            else if (shift_amt == 3'b011) shifted_out = {3'b000, data_in[7:3]};
            else if (shift_amt == 3'b100) shifted_out = {4'b0000, data_in[7:4]};
            else if (shift_amt == 3'b101) shifted_out = {5'b00000, data_in[7:5]};
            else if (shift_amt == 3'b110) shifted_out = {6'b000000, data_in[7:6]};
            else if (shift_amt == 3'b111) shifted_out = {7'b0000000, data_in[7]};
        end

        if (direction == 1'b0) begin // Circular left shift
            shifted_data = shifted_out << shift_amt;
            shifted_data[7:8-shift_amt] = shifted_out[8-shift_amt:7];
        end
        else begin // Circular right shift
            shifted_data = shifted_out >> shift_amt;
            shifted_data[8-shift_amt:7] = shifted_out[7:8-shift_amt];
        end
    end

endmodule

module calculator(
    input [7:0] a,
    input [7:0] b,
    input [1:0] op,
    output reg [7:0] sum,
    output reg [7:0] diff,
    output reg [7:0] prod,
    output reg [7:0] quot
    );

reg [7:0] a_abs;
reg [7:0] b_abs;
reg [7:0] prod_tmp;

always @(*) begin
    if (a[7] == 1'b1) a_abs = ~a + 1;
    else a_abs = a;
    if (b[7] == 1'b1) b_abs = ~b + 1;
    else b_abs = b;
end

always @(a, b, op) begin
    case (op)
        2'b00: begin // addition
            if (a[7] == b[7]) begin
                sum = a + b;
                if (sum[7] != a[7]) begin // overflow
                    if (a[7] == 1'b1) sum = 8'h7f;
                    else sum = 8'h80;
                end
            end
            else begin
                diff = a - b;
                if (diff[7] != a[7]) begin // overflow
                    if (a[7] == 1'b1) diff = 8'h7f;
                    else diff = 8'h80;
                end
            end
        end
        2'b01: begin // subtraction
            diff = a - b;
            if (a[7] != b[7]) begin
                sum = a + b;
                if (sum[7] != a[7]) begin // overflow
                    if (a[7] == 1'b1) sum = 8'h7f;
                    else sum = 8'h80;
                end
            end
            else if (diff[7] != a[7]) begin // overflow
                if (a[7] == 1'b1) diff = 8'h7f;
                else diff = 8'h80;
            end
        end
        2'b10: begin // multiplication
            prod_tmp = a_abs * b_abs;
            if (a[7] != b[7]) prod = ~prod_tmp + 1;
            else prod = prod_tmp;
            if (prod[7] != a[7]) begin // overflow
                if (a[7] == 1'b1) prod = 8'h7f;
                else prod = 8'h80;
            end
        end
        2'b11: begin // division
            if (b == 8'h00) begin // division by zero
                if (a[7] == 1'b1) begin
                    quot = 8'h7f;
                    diff = 8'h80;
                end
                else begin
                    quot = 8'h00;
                    diff = 8'h01;
                end
            end
            else begin
                quot = a_abs / b_abs;
                if (a[7] != b[7]) quot = ~quot + 1;
                diff = a_abs % b_abs;
                if (a[7] == 1'b1) diff = ~diff + 1;
            end
        end
    endcase
end

endmodule

