  // First 8-bit addition
  cla_8 cla0 (a[7:0], b[7:0], c_in, g[0], p[0], s[7:0]);

  // Second 8-bit addition
  cla_8 cla1 (a[15:8], b[15:8], c_out, g[1], p[1], s[15:8]);

  // Final carry-out calculation
  g_p g_p0(g, p, c_in, g_out, p_out, c_out);

endmodule

