    output reg ack2,
    output reg [7:0] dataout
);

    reg [1:0] state;
    reg [7:0] data_reg;

    parameter IDLE = 2'b00, GRANT1 = 2'b01, GRANT2 = 2'b10;
    parameter REQ1 = 1'b1, REQ2 = 1'b0;

    always @ (posedge req1 or posedge req2 or negedge rst_async_n) begin
        if (~rst_async_n) begin
            state <= IDLE;
            ack1 <= 1'b0;
            ack2 <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (req1 && ~req2) begin
                        state <= GRANT1;
                        data_reg <= datain1;
                    end else if (~req1 && req2) begin
                        state <= GRANT2;
                        data_reg <= datain2;
                    end
                end
                GRANT1: begin
                    ack1 <= 1'b1;
                    ack2 <= 1'b0;
                    dataout <= data_reg;
                    state <= IDLE;
                end
                GRANT2: begin
                    ack1 <= 1'b0;
                    ack2 <= 1'b1;
                    dataout <= data_reg;
                    state <= IDLE;
                end
            endcase
        end
    end
