module intermediator (
    input clk,
    input rst,
    input wr0,
    input [LOG2_INTERMEDIATOR_DEPTH - 1:0] row0,
    input [65:0] v0,
    input wr1,
    input [LOG2_INTERMEDIATOR_DEPTH - 1:0] row1,
    input [65:0] v1,
    output wire push_to_adder,
    output wire [LOG2_INTERMEDIATOR_DEPTH - 1:0] row_to_adder,
    output wire [65:0] v0_to_adder,
    output wire [65:0] v1_to_adder,
    output wire push_to_y,
    output wire [65:0] v_to_y,
    output reg eof
);

parameter INTERMEDIATOR_DEPTH = 1024;
parameter LOG2_INTERMEDIATOR_DEPTH = log2(INTERMEDIATOR_DEPTH - 1);

reg [65:0] memory [0:INTERMEDIATOR_DEPTH-1];

reg [LOG2_INTERMEDIATOR_DEPTH - 1:0] read_address0;
reg [LOG2_INTERMEDIATOR_DEPTH - 1:0] read_address1;

assign push_to_adder = (wr0 || wr1) && (read_address0 != read_address1);
assign row_to_adder = push_to_adder ? ((read_address0 < read_address1) ? read_address0 : read_address1) : 0;
assign v0_to_adder = push_to_adder ? memory[row_to_adder][65:0] : 0;
assign v1_to_adder = push_to_adder ? memory[row_to_adder][65:0] : 0;

assign push_to_y = wr0 || wr1;
assign v_to_y = memory[read_address0][65:0];

always @(posedge clk) begin
    if (rst) begin
        read_address0 <= 0;
        read_address1 <= 0;
        eof <= 0;
    end else begin
        if (wr0) begin
            memory[row0][65:0] <= v0;
        end
        if (wr1) begin
            memory[row1][65:0] <= v1;
        end
        if (push_to_adder) begin
            memory[row_to_adder][65:0] <= v0_to_adder + v1_to_adder;
        end
        if (push_to_y) begin
            read_address0 <= read_address0 + 1;
            if (read_address0 == read_address1) begin
                eof <= 1;
            end
        end
    end
end

endmodule

module mux6to1_pipeline (
    input [2:0] sel,
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output reg [3:0] out
);

reg [3:0] stage1_out0, stage1_out1, stage1_out2, stage1_out3, stage1_out4, stage1_out5;
reg [3:0] stage2_out0, stage2_out1, stage2_out2, stage2_out3;
reg [3:0] stage3_out0, stage3_out1;
reg [3:0] stage4_out;

// Stage 1
assign stage1_out0 = (sel[0] == 0) ? data0 : data1;
assign stage1_out1 = (sel[0] == 0) ? data2 : data3;
assign stage1_out2 = (sel[0] == 0) ? data4 : data5;
assign stage1_out3 = (sel[0] == 1) ? data0 : data1;
assign stage1_out4 = (sel[0] == 1) ? data2 : data3;
assign stage1_out5 = (sel[0] == 1) ? data4 : data5;

// Stage 2
assign stage2_out0 = (sel[1] == 0) ? stage1_out0 : stage1_out1;
assign stage2_out1 = (sel[1] == 0) ? stage1_out2 : stage1_out3;
assign stage2_out2 = (sel[1] == 1) ? stage1_out0 : stage1_out1;
assign stage2_out3 = (sel[1] == 1) ? stage1_out2 : stage1_out3;

// Stage 3
assign stage3_out0 = (sel[2] == 0) ? stage2_out0 : stage2_out1;
assign stage3_out1 = (sel[2] == 1) ? stage2_out2 : stage2_out3;

// Stage 4
assign stage4_out = (sel[2] == 0) ? stage3_out0 : stage3_out1;

always @(*) begin
    out = stage4_out;
end

endmodule

module PRNG (
  input clk,
  input [n-1:0] seed,
  output reg [31:0] rand
);

parameter n = 32; // number of bits in the seed value

reg [n-1:0] state; // state of PRNG

initial begin
  // initialize state of PRNG
  state = seed;
end

// generate new pseudo-random number on each rising edge of clock
always @(posedge clk) begin
  // compute next state of PRNG
  state = state ^ (state << 13);
  state = state ^ (state >> 17);
  state = state ^ (state << 5);

  // compute output pseudo-random number
  rand = state[31:0];
end

endmodule

module top_module (
    input clk,
