    input [7:0] data_in_1,
    input [7:0] data_in_2,
    input control_signal,
    output reg ready_out,
    output reg [15:0] result_out
);

reg [7:0] add_result;
reg [15:0] mult_result;

always @(posedge clk) begin
    if (reset) begin
        ready_out <= 0;
        result_out <= 0;
        add_result <= 0;
        mult_result <= 0;
    end else begin
        if (control_signal) begin
            // Addition operation
            add_result <= data_in_1 + data_in_2;
            result_out <= {8'b0, add_result};
        end else begin
            // Multiplication operation
            mult_result <= data_in_1 * data_in_2;
            result_out <= mult_result;
        end
        ready_out <= 1;
    end
end

endmodule

module uart_receiver(
	input clk,
	input reset_n,
	input rx,
	input start,
	output reg data_valid,
	output reg [7:0] data
);

parameter BAUD_RATE = 9600; // baud rate in bits per second
parameter BIT_TIME = 50000/BAUD_RATE; // duration of one bit in clock cycles

reg [3:0] state; // state machine variable
reg [7:0] shift_reg; // shift register for storing received data
reg parity; // parity bit
reg stop_bit; // stop bit
reg bit_count; // counter for tracking number of bits received

always @(posedge clk or negedge reset_n) begin
	if (~reset_n) begin
		state <= 4'd0;
		data_valid <= 1'b0;
		data <= 8'h00;
		shift_reg <= 8'h00;
		parity <= 1'b0;
		stop_bit <= 1'b0;
		bit_count <= 4'd0;
	end
	else begin
		case (state)
			4'd0: begin // wait for start bit
				if (start & ~rx) begin
					state <= 4'd1;
					bit_count <= 4'd0;
					shift_reg <= 8'h00;
					parity <= 1'b0;
					stop_bit <= 1'b0;
				end
			end
			4'd1: begin // receive data bits
				if (bit_count < 8) begin
					shift_reg[bit_count] <= rx;
					parity <= parity ^ rx;
					bit_count <= bit_count + 1;
				end
				else begin
					state <= 4'd2;
					bit_count <= 4'd0;
				end
			end
			4'd2: begin // receive parity bit
				if (bit_count == 0) begin
					if (rx == parity) begin
						state <= 4'd3;
					end
					else begin
						state <= 4'd0;
					end
				end
				bit_count <= bit_count + 1;
			end
			4'd3: begin // receive stop bit
				if (bit_count == 0) begin
					if (rx == 1'b1) begin
						stop_bit <= 1'b1;
						state <= 4'd4;
					end
					else begin
						state <= 4'd0;
					end
				end
				bit_count <= bit_count + 1;
			end
			4'd4: begin // output received data
				data_valid <= 1'b1;
				data <= shift_reg;
				if (stop_bit) begin
					state <= 4'd0;
				end
			end
		endcase
	end
end

endmodule

