module video_sys_jtag_uart_0_drom_module (
    // inputs:
    clk,
    incr_addr,
    reset_n,

    // outputs:
    new_rom,
    num_bytes,
    q,
    safe
);

parameter POLL_RATE = 100;

output new_rom;
output [31:0] num_bytes;
output [7:0] q;
output safe;
input clk;
input incr_addr;
input reset_n;

reg [11:0] address;
reg d1_pre;
reg d2_pre;
reg d3_pre;
reg d4_pre;
reg d5_pre;
reg d6_pre;
reg d7_pre;
reg d8_pre;
reg d9_pre;
reg [7:0] mem_array [2047:0];
reg [31:0] mutex [1:0];
reg new_rom;
wire [31:0] num_bytes;
reg pre;
wire [7:0] q;
wire safe;

reg [31:0] poll_count;
reg [31:0] mutex_handle;
reg safe_delay;

assign q = mem_array[address];
assign num_bytes = mutex[1];
assign safe = (address < mutex[1]);

always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
        d1_pre <= 0;
        d2_pre <= 0;
        d3_pre <= 0;
        d4_pre <= 0;
        d5_pre <= 0;
        d6_pre <= 0;
        d7_pre <= 0;
        d8_pre <= 0;
        d9_pre <= 0;
        new_rom <= 0;
    end else begin
        d1_pre <= pre;
        d2_pre <= d1_pre;
        d3_pre <= d2_pre;
        d4_pre <= d3_pre;
        d5_pre <= d4_pre;
        d6_pre <= d5_pre;
        d7_pre <= d6_pre;
        d8_pre <= d7_pre;
        d9_pre <= d8_pre;
        new_rom <= d9_pre;
    end
end

always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
        address <= 0;
        mem_array[0] <= 0;
        mutex[0] <= 0;
        mutex[1] <= 0;
        pre <= 0;
        poll_count <= 0;
        mutex_handle <= 0;
        safe_delay <= 0;
    end else begin
        pre <= 0;
        if (incr_addr && safe) begin
            address <= address + 1;
        end
        if (poll_count < POLL_RATE) begin
            poll_count <= poll_count + 1;
        end else begin
            poll_count <= 0;
            if (mutex_handle) begin
                $readmemh("video_sys_jtag_uart_0_input_mutex.dat", mutex);
            end
            if (mutex[0] && !safe) begin
                mutex[1] <= mutex[0];
                $readmemb("video_sys_jtag_uart_0_input_stream.dat", mem_array);
                address <= 0;
                pre <= -1;
            end
        end
        if (reset_n == 1) begin
            if (mutex[0] && !safe && safe_delay) begin
                if (interactive) begin
                    mutex_handle = $fopen("video_sys_jtag_uart_0_input_mutex.dat");
                    $fdisplay(mutex_handle, "0");
                    $fclose(mutex_handle);
                end else begin
                    wait(!reset_n);
                end
            end
        end
    end
end

always @(posedge clk or negedge reset_n) begin
    if (reset_n == 1) begin
        if (mutex[0] && !safe && safe_delay) begin
            if (interactive) begin
                mutex_handle = $fopen("video_sys_jtag_uart_0_input_mutex.dat");
                $fdisplay(mutex_handle, "0");
                $fclose(mutex_handle);
            end else begin
                wait(!reset_n);
            end
        end
        safe_delay <= safe;
    end else begin
        safe_delay <= 0;
    end
end

endmodule

module binary_to_gray(
  input [2:0] bin,
  output [2:0] gray
);

  wire x1, x2, x3, x4, x5, x6;

  // XOR gates
  xor(x1, bin[2], bin[1]);
  xor(x2, bin[1], bin[0]);
  xor(x3, bin[2], x1);
  xor(x4, bin[1], x2);
  xor(x5, bin[0], x4);

  // AND gates
  and(x6, x3, x5);

  assign gray = {x6, x5, x4};

endmodule

