module vga_controller(input clk, input rst, input clk25mhz, input [7:0] vmem_data, output [19:0] vmem_addr, output scan, output hsync, output vsync, output [3:0] rgb);

    // Define VGA timing parameters
    parameter hlen = 640;
    parameter hpulse = 96;
    parameter hfp = 16;
    parameter hbp = 48;
    parameter vlen = 480;
    parameter vfp = 10;
    parameter vbp = 33;
    parameter vpulse = 2;

    // Define VGA timing constants
    parameter hlen1 = hlen + hpulse + hfp + hbp;
    parameter vlen1 = vlen + vpulse + vfp + vbp;

    // Define FIFO parameters
    parameter FIFO_DEPTH = 16;

    // Define VGA state variables
    reg [9:0] hcounter;
    reg [9:0] vcounter;
    reg ready;
    wire visible;

    // Define FIFO state variables
    reg [7:0] fifo_in;
    wire [7:0] fifo_out;
    reg fifo_en;
    reg fifo_rd;
    wire fifo_full;
    wire fifo_empty;

    // Define video memory state variables
    reg [19:0] vmpos;

    // Define output signal generators
    assign hsync = ~((hcounter > hlen+hfp) & (hcounter < hlen+hfp+hpulse));
    assign vsync = ~((vcounter > vlen+vfp) & (vcounter < vlen+vfp+vpulse));
    assign scan = vcounter == 0;
    assign visible = (hcounter < hlen)&&(vcounter < vlen);

    // Define FIFO
    smallfifo1 fifo1(.rst(rst), .clk_in(clk), .fifo_in(fifo_in), .fifo_en(fifo_en), .fifo_full(fifo_full), .clk_out(clk25mhz), .fifo_out(fifo_out), .fifo_empty(fifo_empty), .fifo_rd(fifo_rd));

    // Feed FIFO with video memory data
    always @(posedge clk) begin
        if (!rst) begin
            fifo_en <= 0;
            vmpos <= 0;
        end else begin
            if (!fifo_full && !fifo_en) begin
                if (vmpos < (hlen*vlen/2 - 1)) begin
                    vmpos <= vmpos + 1;
                end else begin
                    vmpos <= 0;
                end
                fifo_en <= 1;
            end else begin
                fifo_en <= 0;
            end
        end
    end

    // Generate VGA output signals
    always @(posedge clk25mhz) begin
        if (!rst || !ready) begin
            vcounter <= 0;
            hcounter <= 0;
        end else begin
            if (hcounter >= hlen1-1) begin
                hcounter <= 0;
                if (vcounter >= vlen1-1) begin
                    vcounter <= 0;
                end else begin
                    vcounter <= vcounter + 1;
                end
            end else begin
                hcounter <= hcounter + 1;
            end
        end
    end

    // Read from FIFO and output RGB signal
    reg [7:0] out_current;
    reg [7:0] out_next;
    wire [3:0] nextbit;
    assign nextbit = out_current[7:4];
    assign rgb = visible ? nextbit : 4'b0;
    reg [1:0] bitcount;

    always @(posedge clk25mhz) begin
        if (!rst) begin
            bitcount <= 0;
            out_current <= 0;
            out_next <= 0;
            ready <= 0;
            fifo_rd <= 0;
        end else begin
            if (!ready) begin
                if (fifo_rd) begin
                    fifo_rd <= 0;
                    out_current <= fifo_out;
                    ready <= 1;
                    bitcount <= 0;
                end else begin
                    fifo_rd <= 1;
                end
            end else begin
                if (visible) begin
                    if (bitcount == 0) begin
                        bitcount <= 1;
                        out_current <= out_current << 4;
                        fifo_rd <= 1;
                    end else begin
                        fifo_rd <= 0;
                        out_current <= out_next;
                        out_next <= fifo_out;
                        bitcount <= 0;
                    end
                end else begin
                    fifo_rd <= 0;
                    bitcount <= 0;
                end
            end
        end
    end

    // Assign video memory address
    assign vmem_addr = vmpos;

    // Assign FIFO input
    assign fifo_in = vmem_data;

endmodule

