            end else if ((address == 4) && begintransfer && write && writedata[0]) begin
                time_counter_enable_0 <= 1'b0;
            end
        end
    end

    // Counter 1 - Time
    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            time_counter_1 <= 64'd0;
        end else if ((time_counter_enable_1 & global_enable) | global_reset) begin
            if (global_reset) begin
                time_counter_1 <= 64'd0;
            end else begin
                time_counter_1 <= time_counter_1 + 1;
            end
        end
    end

    // Counter 1 - Event
    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            event_counter_1 <= 64'd0;
        end else if ((address == 5) && begintransfer && write) begin
            event_counter_1 <= event_counter_1 + 1;
        end
    end

    // Counter 1 - Time Enable
    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            time_counter_enable_1 <= 1'b0;
        end else if (clk_en) begin
            if ((address == 1) && begintransfer && write) begin
                time_counter_enable_1 <= 1'b1;
            end else if ((address == 5) && begintransfer && write && writedata[0]) begin
                time_counter_enable_1 <= 1'b0;
            end
        end
    end

    assign global_enable = time_counter_enable_0 | time_counter_enable_1;
    assign global_reset = (address == 7) && begintransfer && write && writedata[0];

    assign readdata = (address == 0) ? time_counter_0[31:0] :
                     (address == 1) ? time_counter_0[63:32] :
                     (address == 2) ? event_counter_0[63:0] :
                     (address == 4) ? time_counter_1[31:0] :
                     (address == 5) ? time_counter_1[63:32] :
                     (address == 6) ? event_counter_1[63:0] :
                     32'd0;

endmodule

module rotator (
    input clk,
    input reset,
    input load,
    input [1:0] direction,
    input [99:0] data_in,
    output [99:0] data_out
);

