always @(posedge clk) begin
    if (reset) begin
        shift_reg <= 100'b0;
    end else if (load) begin
        shift_reg <= data_in;
    end else begin
        case (direction)
            2'b00: shift_reg <= {shift_reg[98:0], shift_reg[99]};
            2'b01: shift_reg <= {shift_reg[99], shift_reg[98:0]};
            2'b10: shift_reg <= {shift_reg[1:99], shift_reg[0]};
            2'b11: shift_reg <= {shift_reg[0], shift_reg[1:99]};
        endcase
    end
end

assign data_out = shift_reg;

endmodule

