module i2c_master_fsm (
  input clk,
  input rst,
  input scl,
  input sda,
  output reg sda_out,
  output reg [2:0] state,
  output reg [7:0] addr_reg,
  output reg [7:0] data_reg,
  input wr_en,
  input rd_en,
  input [7:0] addr,
  input [7:0] data_in
);

  parameter IDLE = 0;
  parameter START = 1;
  parameter ADDR = 2;
  parameter DATA = 3;
  parameter STOP = 4;

  always @(posedge clk) begin
    if (rst) begin
      state <= IDLE;
      addr_reg <= 8'b0;
      data_reg <= 8'b0;
      sda_out <= 1'bZ;
    end else begin
      case (state)
        IDLE: begin
          if (wr_en || rd_en) begin
            state <= START;
            sda_out <= 1'b0;
          end
        end
        START: begin
          if (scl && !sda) begin
            state <= ADDR;
            addr_reg <= addr;
            sda_out <= 1'b0;
          end
        end
        ADDR: begin
          if (scl && !sda) begin
            if (wr_en) begin
              state <= DATA;
              data_reg <= data_in;
              sda_out <= 1'b0;
            end else if (rd_en) begin
              state <= START;
              sda_out <= 1'b1;
            end
          end
        end
        DATA: begin
          if (scl && !sda) begin
            state <= STOP;
            sda_out <= 1'b1;
          end
        end
        STOP: begin
          if (!scl && sda) begin
            state <= IDLE;
            sda_out <= 1'b1;
          end
        end
      endcase
    end
  end

endmodule

module i2c_master_ctrl (
  input clk,
  input rst,
  input scl,
  input sda,
  output reg sda_out,
  output reg [2:0] state,
  output reg [7:0] addr_reg,
  output reg [7:0] data_reg,
  input wr_en,
  input rd_en,
  input [7:0] addr,
  input [7:0] data_in
);

  always @(posedge clk) begin
    if (rst) begin
      sda_out <= 1'bZ;
    end else begin
      case (state)
        IDLE: begin
          sda_out <= 1'bZ;
        end
        START: begin
          sda_out <= 1'b0;
        end
        ADDR: begin
          sda_out <= addr_reg[7];
          addr_reg <= {addr_reg[6:0], 1'b0};
        end
        DATA: begin
          sda_out <= data_reg[7];
          data_reg <= {data_reg[6:0], 1'b0};
        end
        STOP: begin
          sda_out <= 1'b1;
        end
      endcase
    end
  end

endmodule

module i2c_slave_fsm (
  input clk,
  input rst,
  input scl,
  input sda,
  output reg sda_out,
  output reg [2:0] state,
  output reg [7:0] addr_reg,
  output reg [7:0] data_reg,
  input wr_en,
  input rd_en,
  input [7:0] addr,
  input [7:0] data_in
);

  parameter IDLE = 0;
  parameter ADDR = 1;
  parameter DATA = 2;

  always @(posedge clk) begin
    if (rst) begin
      state <= IDLE;
      addr_reg <= 8'b0;
      data_reg <= 8'b0;
      sda_out <= 1'bZ;
    end else begin
      case (state)
        IDLE: begin
          if (scl && !sda) begin
            state <= ADDR;
            sda_out <= 1'b0;
          end
        end
        ADDR: begin
          if (scl && !sda) begin
            if (sda_in) begin
              addr_reg <= 8'b0;
              state <= IDLE;
              sda_out <= 1'b1;
            end else if (addr_reg == addr) begin
              if (wr_en) begin
                state <= DATA;
                sda_out <= 1'b0;
              end else if (rd_en) begin
                data_reg <= 8'b0;
                state <= DATA;
                sda_out <= 1'b1;
              end
            end else begin
              addr_reg <= 8'b0;
              state <= IDLE;
              sda_out <= 1'b1;
            end
          end else if (!scl && sda) begin
            addr_reg <= {addr_reg[6:0], sda_in};
          end
        end
        DATA: begin
          if (scl && !sda) begin
            if (wr_en) begin
              data_reg <= data_in;
              state <= ADDR;
              sda_out <= 1'b1;
            end else if (rd_en) begin
              sda_out <= data_reg[7];
              data_reg <= {data_reg[6:0], 1'b0};
            end
          end else if (!scl && sda) begin
            data_reg <= {data_reg[6:0], sda_in};
          end
        end
      endcase
    end
  end

endmodule

