module forward_mem_stage(mem_wb_op, mem_wb_regA, mem_wb_regC, ex_mem_op, ex_mem_regA, mem_wb_CCR_write, ex_mem_CCR_write, F3);

    parameter ADD = 6'b000000;
    parameter NDU = 6'b001000;
    parameter ADC = 6'b000010;
    parameter ADZ = 6'b000001;
    parameter NDC = 6'b001010;
    parameter NDZ = 6'b001001;
    parameter LHI = 4'b0011;
    parameter LW  = 4'b0100;
    parameter SW  = 4'b0101;
    parameter LM  = 4'b0110;
    parameter SM  = 4'b0111;
    parameter BEQ = 4'b1100;
    parameter JAL = 4'b1000;
    parameter JLR = 4'b1001;

    input [2:0] mem_wb_regA, mem_wb_regC, ex_mem_regA;
    input [5:0] mem_wb_op, ex_mem_op;
    input mem_wb_CCR_write, ex_mem_CCR_write;
    output reg [1:0] F3;

    always @(*)
    begin
        if (ex_mem_op[5:2] == SW)
        begin
            if ((ex_mem_regA == mem_wb_regC) && (mem_wb_op == ADD || mem_wb_op == NDU || mem_wb_op == ADC || mem_wb_op == ADZ || mem_wb_op == NDC || mem_wb_op == NDZ) && (mem_wb_CCR_write == 1'b0))
                F3 = 2'd1; // Store word and previous operation was ADD, NDU, ADC, ADZ, NDC, or NDZ and no write to CCR
            else if ((ex_mem_regA == mem_wb_regA) && (mem_wb_op[5:2] == LW))
                F3 = 2'd2; // Not store word but previous operation was LW and register values match
            else
                F3 = 2'b0; // No match
        end
        else
            F3 = 2'b0; // Not store word
    end

endmodule

module tone_generator (
  input clk,
  input rst,
  input [1:0] tone_sel,
  input [7:0] freq1,
  input [7:0] freq2,
  input [15:0] duration,
  output tone_out
);

  reg [15:0] count;
  reg [7:0] sine_table [0:255];
  reg [7:0] square_wave;
  reg [7:0] dtmf_tone1;
  reg [7:0] dtmf_tone2;
  reg [7:0] mixer_out;
  reg [7:0] tone_sel_reg;
  reg [7:0] freq1_reg;
  reg [7:0] freq2_reg;
  reg [15:0] duration_reg;

  always @(posedge clk) begin
    if (rst) begin
      count <= 0;
      tone_sel_reg <= 0;
      freq1_reg <= 0;
      freq2_reg <= 0;
      duration_reg <= 0;
    end else begin
      count <= count + 1;
      tone_sel_reg <= tone_sel;
      freq1_reg <= freq1;
      freq2_reg <= freq2;
      duration_reg <= duration;
    end
  end

  always @(posedge clk) begin
    if (rst) begin
      sine_table <= 256'h0;
      square_wave <= 0;
      dtmf_tone1 <= 0;
      dtmf_tone2 <= 0;
      mixer_out <= 0;
    end else begin
      case (tone_sel_reg)
        2'b00: begin // DTMF signal
          dtmf_tone1 <= sine_table[freq1_reg];
          dtmf_tone2 <= sine_table[freq2_reg];
          mixer_out <= dtmf_tone1 + dtmf_tone2;
        end
        2'b01: begin // Sine wave
          mixer_out <= sine_table[freq1_reg];
        end
        2'b10: begin // Square wave
          square_wave <= square_wave + 1;
          if (square_wave >= (256/freq1_reg)/2) begin
            square_wave <= 0;
          end
          mixer_out <= square_wave;
        end
        default: begin
          mixer_out <= 0;
        end
      endcase
      if (count >= duration_reg) begin
        mixer_out <= 0;
      end
    end
  end

  always @(posedge clk) begin
    if (rst) begin
      tone_out <= 0;
    end else begin
      tone_out <= mixer_out;
    end
  end

  // Generate sine wave lookup table
  integer i;
  initial begin
    for (i = 0; i < 256; i = i + 1) begin
      sine_table[i] = $sin(2 * $pi * i / 256);
    end
  end

endmodule

module top_module(
    input clk,
    input reset,
    input select,
    input [3:0] binary_input1,
    input [3:0] binary_input2,
    input [3:0] BCD_input1,
    input [3:0] BCD_input2,
    output [3:0] BCD_output1,
    output [3:0] BCD_output2,
    output final_output
);

// Instantiate the two given modules
binary_bcd_converter binary_bcd_converter_inst(
    .binary_input1(binary_input1),
    .binary_input2(binary_input2),
    .BCD_output1(BCD_output1),
    .BCD_output2(BCD_output2)
);

bcd_binary_converter bcd_binary_converter_inst(
    .BCD_input1(BCD_input1),
    .BCD_input2(BCD_input2),
    .binary_output1(binary_input1),
    .binary_output2(binary_input2)
);

// Define the combinational circuit for XOR, NAND, and NOR operations
wire [15:0] xor_nand_nor_output;
assign xor_nand_nor_output = {binary_input1 ^ binary_input2, ~(binary_input1 & binary_input2), ~(binary_input1 | binary_input2)};

// Define the functional module to calculate the final output
wire [3:0] BCD_and_output;
assign BCD_and_output = BCD_output1 & BCD_output2;
wire [3:0] xor_nand_nor_output_mux;
assign xor_nand_nor_output_mux = select ? xor_nand_nor_output[15:12] : xor_nand_nor_output[11:8];
wire [3:0] final_output_mux;
assign final_output_mux = select ? BCD_and_output : xor_nand_nor_output_mux;
assign final_output = final_output_mux[3];

// Define the control logic to select the active module
reg [1:0] active_module;
always @(posedge clk) begin
    if (reset) begin
        active_module <= 2'b00;
    end else begin
        active_module <= select ? 2'b01 : 2'b10;
    end
end

// Define the multiplexers to select the output of the active module
wire [3:0] BCD_output_mux;
wire [3:0] binary_output_mux;
assign BCD_output_mux = active_module[1] ? BCD_output2 : BCD_output1;
assign binary_output_mux = active_module[1] ? binary_input2 : binary_input1;

// Connect the active module output to the functional module input
wire [3:0] active_module_output;
assign active_module_output = active_module[0] ? binary_output_mux : BCD_output_mux;

endmodule

