module binary_to_bcd_converter (
    input [3:0] A,
    output reg [3:0] B,
    output reg [3:0] C
);

// Instantiate the larger_number module to compare A to 5
wire larger;
larger_number ln(
    .num1(A),
    .num2(4'b0101),
    .larger(larger)
);

// Output BCD digits based on the comparison result
always @(*) begin
    if (larger) begin
        // A is greater than or equal to 5, so B represents the most significant digit
        B = {A[3], A[2], A[1], A[0]} - 5'b0010;
        C = {A[3], A[2], A[1], A[0]} % 5'b0010;
    end else begin
        // A is less than 5, so C represents the most significant digit
        B = {A[3], A[2], A[1], A[0]} % 5'b0010;
        C = {A[3], A[2], A[1], A[0]};
    end
end

endmodule

