module sequence_detector(
  input in,
  output out
);

parameter n = 3; // number of bits in the sequence to be detected
parameter sequence = 3'b101; // the sequence of bits to be detected

// state definition
localparam S0 = 2'b00;
localparam S1 = 2'b01;
localparam S2 = 2'b10;
localparam S3 = 2'b11;

// state register
reg [1:0] state;

// state transition
always @(state or in) begin
  case(state)
    S0: if(in == 1'b1) state <= S1; else state <= S0;
    S1: if(in == 1'b0) state <= S0; else state <= S2;
    S2: if(in == 1'b1) state <= S3; else state <= S0;
    S3: if(in == 1'b0) state <= S0; else state <= S3;
  endcase
end

// output function
always @(state) begin
  if(state == S3) out = 1'b1;
  else out = 1'b0;
end

endmodule

module fourBitAdder(
    input [3:0] A, B,
    input Rst,
    output reg [3:0] S,
    output reg Cout
);

always @(*) begin
    if(Rst) begin
        S <= 4'b0;
        Cout <= 1'b0;
    end else begin
        S <= A + B;
        Cout <= (A[3] & B[3]) | (A[2] & B[2]) | (A[1] & B[1]) | (A[0] & B[0]);
    end
end

endmodule

module binary_counter
#(
