    always @(posedge clk or negedge rst) begin
        if (!rst) begin
            counter <= 0;
        end else if (load) begin
            counter <= data;
        end else if (en) begin
            counter <= counter + 1;
        end
    end

    assign count = counter;

endmodule

module soc_system_led_pio (
