module edge_detection (
    input clk,
    input signal,
    output reg rise,
    output reg down
);

reg prev_signal;

always @(posedge clk) begin
    if (signal == 1 && prev_signal == 0) begin
        rise <= 1;
    end else begin
        rise <= 0;
    end

    if (signal == 0 && prev_signal == 1) begin
        down <= 1;
    end else begin
        down <= 0;
    end

    prev_signal <= signal;
end

endmodule

