module top_module( 
    input [255:0] in,
    input [7:0] sel,
    output out );

    wire [255:0] level1 [0:127];
    wire [255:0] level2 [0:63];
    wire [255:0] level3 [0:31];
    wire [255:0] level4 [0:15];
    wire [255:0] level5 [0:7];
    wire [255:0] level6 [0:3];
    wire [255:0] level7 [0:1];

    assign level1[0] = in;

    genvar i;
    generate
        for (i = 0; i < 128; i = i + 1) begin : level1_gen
            assign level1[i*2] = level2[i];
            assign level1[i*2+1] = level2[i];
        end

        for (i = 0; i < 64; i = i + 1) begin : level2_gen
            assign level2[i*2] = level3[i];
            assign level2[i*2+1] = level3[i];
        end

        for (i = 0; i < 32; i = i + 1) begin : level3_gen
            assign level3[i*2] = level4[i];
            assign level3[i*2+1] = level4[i];
        end

        for (i = 0; i < 16; i = i + 1) begin : level4_gen
            assign level4[i*2] = level5[i];
            assign level4[i*2+1] = level5[i];
        end

        for (i = 0; i < 8; i = i + 1) begin : level5_gen
            assign level5[i*2] = level6[i];
            assign level5[i*2+1] = level6[i];
        end

        for (i = 0; i < 4; i = i + 1) begin : level6_gen
            assign level6[i*2] = level7[i];
            assign level6[i*2+1] = level7[i];
        end

        assign level7[0] = sel[7] ? level1[1] : level1[0];
        assign level7[1] = sel[7] ? level1[3] : level1[2];
    endgenerate

    assign out = sel[6] ? level7[1] : level7[0];

endmodule

module sample_counter
    #(parameter
        NUMBER_OF_COLOUR_PLANES = 0,
        COLOUR_PLANES_ARE_IN_PARALLEL = 0,
        LOG2_NUMBER_OF_COLOUR_PLANES = 0)
    (
    input wire rst,
    input wire clk, 
    input wire sclr,

    input wire count_cycle,
    input wire hd_sdn,

    output wire count_sample,
    output wire start_of_sample,
    output wire [LOG2_NUMBER_OF_COLOUR_PLANES-1:0] sample_ticks);

    wire [LOG2_NUMBER_OF_COLOUR_PLANES-1:0] tick_count;
    wire new_sample;
    reg [LOG2_NUMBER_OF_COLOUR_PLANES-1:0] count_valids;
    reg [LOG2_NUMBER_OF_COLOUR_PLANES-1:0] tick_count_valids;
    reg [LOG2_NUMBER_OF_COLOUR_PLANES-1:0] tick_count_reset;
    reg [LOG2_NUMBER_OF_COLOUR_PLANES-1:0] tick_count_valids_reset;

    assign new_sample = count_valids == (NUMBER_OF_COLOUR_PLANES - 1);

    always @ (posedge rst or posedge clk) begin
        if(rst) begin
            count_valids <= {LOG2_NUMBER_OF_COLOUR_PLANES{1'b0}};
            tick_count_valids_reset <= {LOG2_NUMBER_OF_COLOUR_PLANES{1'b0}};
            tick_count_reset <= {LOG2_NUMBER_OF_COLOUR_PLANES{1'b0}};
        end else begin
            if(sclr) begin
                count_valids <= {{LOG2_NUMBER_OF_COLOUR_PLANES-1{1'b0}}, count_cycle};
                tick_count_valids_reset <= {LOG2_NUMBER_OF_COLOUR_PLANES{1'b0}};
                tick_count_reset <= {LOG2_NUMBER_OF_COLOUR_PLANES{1'b0}};
            end else begin
                if(COLOUR_PLANES_ARE_IN_PARALLEL) begin
                    count_valids <= (count_cycle) ? (new_sample) ? {LOG2_NUMBER_OF_COLOUR_PLANES{1'b0}} : count_valids + 1 : count_valids;
                end else begin
                    count_valids <= (count_cycle) ? (hd_sdn) ? {LOG2_NUMBER_OF_COLOUR_PLANES{1'b0}} : count_valids + 1 : count_valids;
                end
                tick_count_valids_reset <= (new_sample) ? {LOG2_NUMBER_OF_COLOUR_PLANES{1'b0}} : tick_count_valids_reset;
                tick_count_reset <= (new_sample) ? tick_count : tick_count_reset;
            end
        end
    end

    always @ (posedge clk) begin
        tick_count <= (hd_sdn) ? {LOG2_NUMBER_OF_COLOUR_PLANES{1'b0}} : tick_count + 1;
        tick_count_valids <= (hd_sdn) ? tick_count_reset : tick_count_valids + tick_count_valids_reset;
    end

    assign count_sample = (NUMBER_OF_COLOUR_PLANES == 1) ? count_cycle : tick_count_valids;
    assign start_of_sample = (NUMBER_OF_COLOUR_PLANES == 1) ? 1'b1 : (count_valids == {LOG2_NUMBER_OF_COLOUR_PLANES{1'b0}});
    assign sample_ticks = (NUMBER_OF_COLOUR_PLANES == 1) ? 1'b0 : tick_count_valids;

endmodule

module ECC_memory_block (
  input [n-1:0] data_in,
  input we,
  output [n-1:0] data_out,
  output re
);

parameter n = 8; // number of bits in the data word
parameter k = 4; // number of parity bits used for error detection and correction

reg [n+k-1:0] memory_block;
reg [n-1:0] corrected_data;
reg read_enable;

// Hamming code encoding function
function [n+k-1:0] hamming_encode;
  input [n-1:0] data;
  integer i, j, parity_pos;
  begin
    for (i = 0; i < n; i = i + 1) begin
      hamming_encode[i+k] = data[i];
    end
    for (i = 0; i < k; i = i + 1) begin
      parity_pos = 2 ** i;
      hamming_encode[parity_pos - 1] = 0;
      for (j = 0; j < n+k; j = j + 1) begin
        if ((j + 1) & parity_pos) begin
          hamming_encode[parity_pos - 1] = hamming_encode[parity_pos - 1] ^ hamming_encode[j];
        end
      end
    end
  end
endfunction

// Hamming code decoding and error correction function
function [n-1:0] hamming_decode;
  input [n+k-1:0] encoded_data;
  integer i, j, parity_pos, error_pos;
  reg [n+k-1:0] corrected_encoded_data;
  begin
    error_pos = 0;
    for (i = 0; i < k; i = i + 1) begin
      parity_pos = 2 ** i;
      for (j = 0; j < n+k; j = j + 1) begin
        if ((j + 1) & parity_pos) begin
          if (encoded_data[j]) begin
            error_pos = error_pos ^ (j + 1);
          end
        end
      end
    end
    corrected_encoded_data = encoded_data;
    if (error_pos) begin
      corrected_encoded_data[error_pos - 1] = ~corrected_encoded_data[error_pos - 1];
    end
    for (i = 0; i < n; i = i + 1) begin
      hamming_decode[i] = corrected_encoded_data[i+k];
    end
  end
endfunction

// Write operation
always @(posedge we) begin
  memory_block <= hamming_encode(data_in);
end

// Read operation
always @(posedge re) begin
  corrected_data <= hamming_decode(memory_block);
end

// Output signals
assign data_out = corrected_data;
assign re = read_enable;

endmodule

