);

  reg [3:0] counter = 4'd0;

  always @(posedge clk, negedge reset_n) begin
    if (!reset_n) begin
      counter <= 4'd0;
    end else if (counter == 4'd9) begin
      counter <= 4'd0;
    end else begin
      counter <= counter + 1;
    end
  end

  assign count = counter;

endmodule

module my_module(
    input dataa,
    input clk,
    input aclr,
    input ena,
    input devclrn,
    input devpor,
    output reg dataout
);

parameter output_clock = "none";

reg [1:0] state;

initial begin
    state = 2'b00;
end

always @(posedge clk or negedge aclr) begin
    if (!aclr) begin
        state <= 2'b00;
        dataout <= 1'b0;
    end
    else begin
        case (state)
            2'b00: begin
                if (ena) begin
                    dataout <= dataa;
                    state <= 2'b01;
                end
                else begin
                    dataout <= 1'b0;
                end
            end
            2'b01: begin
                if (output_clock != "none") begin
                    state <= 2'b10;
                end
                else begin
                    state <= 2'b00;
                end
            end
            2'b10: begin
                dataout <= dataa;
                state <= 2'b11;
            end
            2'b11: begin
                dataout <= 1'b0;
                state <= 2'b00;
            end
        endcase
    end
end

endmodule

module fsm_6bit_sequence_detection (
  input clk,
  input reset,
  input data,
  input ack,
  output reg match
);
  parameter IDLE = 2'b00, S1 = 2'b01, S2 = 2'b10, DONE = 2'b11;
  reg [1:0] state, next_state;
  reg [5:0] shift_reg;
  assign match = (state == DONE);

  always @(posedge clk) begin
    if (reset) begin
      state <= IDLE;
      shift_reg <= 6'b0;
    end
    else begin
      state <= next_state;
      shift_reg <= {shift_reg[4:0], data};
    end
  end

  always @(*) begin
    case(state)
      IDLE: begin
        if (shift_reg == 6'b101010)
          next_state = S1;
        else
          next_state = IDLE;
      end

      S1: begin
        if (shift_reg == 6'b101010)
          next_state = S1;
        else
          next_state = S2;
      end

      S2: begin
        if (shift_reg == 6'b101010)
          next_state = S1;
        else
          next_state = IDLE;
      end

      DONE: begin
        if (ack)
          next_state = IDLE;
        else
          next_state = DONE;
      end
    endcase
  end

endmodule

module mux4_to_1_sync_reset(
    input wire [3:0] in0,
    input wire [3:0] in1,
    input wire [3:0] in2,
    input wire [3:0] in3,
    input wire [1:0] select,
    input wire clk,
    input wire reset,
    output reg [3:0] out
);

// Define states
localparam IDLE = 2'b00;
localparam SELECT_0 = 2'b01;
localparam SELECT_1 = 2'b10;
localparam SELECT_2 = 2'b11;
localparam SELECT_3 = 2'b100;

// Define state register and next state logic
reg [2:0] state;
always @(posedge clk, posedge reset) begin
    if (reset) begin
        state <= IDLE;
    end else begin
        case (state)
            IDLE: begin
                if (select == 2'b00) begin
                    state <= IDLE;
                end else if (select == 2'b01) begin
                    state <= SELECT_0;
                end else if (select == 2'b10) begin
                    state <= SELECT_1;
                end else if (select == 2'b11) begin
                    state <= SELECT_2;
                end else if (select == 2'b100) begin
                    state <= SELECT_3;
                end
            end
            SELECT_0: begin
                if (select == 2'b00) begin
                    state <= IDLE;
                end else if (select == 2'b01) begin
                    state <= SELECT_0;
                end else if (select == 2'b10) begin
                    state <= SELECT_1;
                end else if (select == 2'b11) begin
                    state <= SELECT_2;
                end else if (select == 2'b100) begin
                    state <= SELECT_3;
                end
            end
            SELECT_1: begin
                if (select == 2'b00) begin
                    state <= IDLE;
                end else if (select == 2'b01) begin
                    state <= SELECT_0;
                end else if (select == 2'b10) begin
                    state <= SELECT_1;
                end else if (select == 2'b11) begin
                    state <= SELECT_2;
                end else if (select == 2'b100) begin
                    state <= SELECT_3;
                end
            end
            SELECT_2: begin
                if (select == 2'b00) begin
                    state <= IDLE;
                end else if (select == 2'b01) begin
                    state <= SELECT_0;
                end else if (select == 2'b10) begin
                    state <= SELECT_1;
                end else if (select == 2'b11) begin
                    state <= SELECT_2;
                end else if (select == 2'b100) begin
                    state <= SELECT_3;
                end
            end
            SELECT_3: begin
                if (select == 2'b00) begin
                    state <= IDLE;
                end else if (select == 2'b01) begin
                    state <= SELECT_0;
                end else if (select == 2'b10) begin
                    state <= SELECT_1;
                end else if (select == 2'b11) begin
                    state <= SELECT_2;
                end else if (select == 2'b100) begin
                    state <= SELECT_3;
                end
            end
        endcase
    end
end

// Define output logic
always @(state, in0, in1, in2, in3) begin
    case (state)
        IDLE: begin
            out <= 4'b0000;
        end
        SELECT_0: begin
            out <= in0;
        end
        SELECT_1: begin
            out <= in1;
        end
        SELECT_2: begin
            out <= in2;
        end
        SELECT_3: begin
            out <= in3;
        end
    endcase
end

endmodule

module frequency_synthesizer (
  input ref_clk,
  input ctrl,
  input [11:0] freq_word,
  input [15:0] phase_acc,
  output reg [15:0] out
);

parameter pll_mult = 10;
parameter pll_div = 1;
parameter clk_freq = 50e6;
parameter dds_clk_freq = 100e6;

reg [15:0] phase_accumulator;
reg [15:0] dds_clk_divider;
reg [15:0] pll_clk_divider;

always @(posedge ref_clk) begin
  if (ctrl == 1'b0) begin // PLL mode
    pll_clk_divider <= pll_clk_divider + 1;
    if (pll_clk_divider == pll_div) begin
      pll_clk_divider <= 0;
      out <= out + 1;
    end
  end else begin // DDS mode
    dds_clk_divider <= dds_clk_divider + 1;
    if (dds_clk_divider == freq_word) begin
      dds_clk_divider <= 0;
      phase_accumulator <= phase_accumulator + 1;
      out <= $sin(phase_accumulator);
    end
  end
end

always @(posedge ref_clk) begin
  if (ctrl == 1'b0) begin // PLL mode
    out <= $sin(pll_clk_divider * pll_mult);
  end
end

endmodule

