module priority_encoder (
    input [7:0] a, b, c, d, // 8-bit inputs for the minimum circuit
    output [1:0] min_index // 2-bit output indicating the index of the minimum input
);

    wire [7:0] ab_min, cd_min, abcd_min; // Wires to hold the minimum values

    // Compare a and b to find the minimum of the two
    assign ab_min = (a < b) ? a : b;

    // Compare c and d to find the minimum of the two
    assign cd_min = (c < d) ? c : d;

    // Compare the minimum of a and b with the minimum of c and d to find the overall minimum
    assign abcd_min = (ab_min < cd_min) ? ab_min : cd_min;

    // Determine which input is the minimum and output its index
    assign min_index = ({a,b,c,d} == 8'b0000_0000) ? 2'b00 :
                      ({a,b,c,d} == 8'b1111_1111) ? 2'b11 :
                      ({a,b,c,d} == {abcd_min, abcd_min, abcd_min, abcd_min}) ? 2'b00 :
                      ({a,b,c,d} == {a, abcd_min, abcd_min, abcd_min}) ? 2'b01 :
                      ({a,b,c,d} == {a, b, abcd_min, abcd_min}) ? 2'b10 :
                      2'b11;

endmodule

module carry_lookahead_adder (
    input [7:0] a, b, // 8-bit inputs for the carry-lookahead adder
    output [7:0] s, // 8-bit output from the carry-lookahead adder
    output overflow // Output indicating signed overflow
);

    wire [7:0] g, p, c; // Wires to hold the generate, propagate, and carry signals
    wire [8:0] c_in; // Wire to hold the carry input to each stage

    // Generate and propagate signals for each bit
    assign g = a & b;
    assign p = a ^ b;

    // Calculate the carry input to each stage
    assign c_in[0] = 1'b0;
    assign c_in[1:8] = g[0:7] | (p[0:7] & c_in[0:7]);

    // Calculate the carry output from each stage
    assign c[0] = c_in[0];
    assign c[1] = g[0] | (p[0] & c_in[0]);
    assign c[2] = g[1] | (p[1] & c_in[1]);
    assign c[3] = g[2] | (p[2] & c_in[2]);
    assign c[4] = g[3] | (p[3] & c_in[3]);
    assign c[5] = g[4] | (p[4] & c_in[4]);
    assign c[6] = g[5] | (p[5] & c_in[5]);
    assign c[7] = g[6] | (p[6] & c_in[6]);
    assign c[8] = g[7] | (p[7] & c_in[7]);

    // Calculate the sum output
    assign s = a + b + c_in[0:7];

    // Check for signed overflow
    assign overflow = (a[7] == b[7] && s[7] != a[7]) ? 1'b1 : 1'b0;

endmodule

module top_module (
    input [7:0] a, b, c, d, // 8-bit inputs for the minimum circuit
    input [7:0] a2, b2, // 8-bit inputs for the carry-lookahead adder
    output [7:0] min, // 8-bit output from the minimum circuit
    output [7:0] s, // 8-bit output from the carry-lookahead adder
    output overflow // Output indicating signed overflow
);

    wire [1:0] min_index; // Wire to hold the index of the minimum input

    // Instantiate the priority encoder module to find the minimum input
    priority_encoder pe (
        .a(a),
        .b(b),
        .c(c),
        .d(d),
        .min_index(min_index)
    );

    // Instantiate the carry-lookahead adder module to add the two 2's complement numbers
    carry_lookahead_adder cla (
        .a(a2),
        .b(b2),
        .s(s),
        .overflow(overflow)
    );

    // Output the minimum value based on the index of the minimum input
    assign min = (min_index == 2'b00) ? a :
                 (min_index == 2'b01) ? b :
                 (min_index == 2'b10) ? c :
                 d;

endmodule

