module Ethernet_MAC (
  input clk,
  input reset,
  input start,
  input [7:0] data_in,
  input [47:0] dest_addr,
  input [47:0] src_addr,
  input [15:0] length,
  output reg [7:0] txd,
  output reg tx_en,
  output reg tx_done,
  input [7:0] rxd,
  input rx_en,
  output reg [7:0] data_out,
  output reg valid,
  output reg [47:0] dest_addr,
  output reg [47:0] src_addr,
  output reg [15:0] length
);

// Transmitter block
reg [7:0] preamble = 8'h55;
reg [7:0] sfd = 8'hD5;
reg [47:0] dest_mac;
reg [47:0] src_mac;
reg [15:0] frame_length;
reg [7:0] crc [3:0];
reg [7:0] data [1517:0];
reg [7:0] pad [46:0];
reg [7:0] pad_crc [3:0];
reg [7:0] tx_state = 0;
reg [7:0] bit_count = 0;
reg [7:0] byte_count = 0;
reg [7:0] data_index = 0;
reg [7:0] crc_index = 0;

always @(posedge clk) begin
  if (reset) begin
    tx_state <= 0;
    tx_en <= 0;
    tx_done <= 0;
    bit_count <= 0;
    byte_count <= 0;
    data_index <= 0;
    crc_index <= 0;
  end else begin
    case (tx_state)
      0: begin // Idle state
        if (start) begin
          dest_mac <= dest_addr;
          src_mac <= src_addr;
          frame_length <= length;
          data[0:7] <= preamble;
          data[8:15] <= sfd;
          data[16:63] <= dest_mac;
          data[64:111] <= src_mac;
          data[112:127] <= frame_length;
          data_index <= 128;
          tx_state <= 1;
        end
      end
      1: begin // Data state
        if (byte_count < frame_length) begin
          data[data_index:data_index+7] <= data_in;
          data_index <= data_index + 8;
          byte_count <= byte_count + 1;
        end else begin
          tx_state <= 2;
        end
      end
      2: begin // Pad state
        if (byte_count < 46) begin
          data[data_index:data_index+7] <= 8'h00;
          data_index <= data_index + 8;
          byte_count <= byte_count + 1;
        end else begin
          tx_state <= 3;
        end
      end
      3: begin // CRC state
        if (crc_index < 4) begin
          crc[crc_index] <= 8'h00;
          crc_index <= crc_index + 1;
        end else begin
          tx_state <= 4;
        end
      end
      4: begin // Pad CRC state
        if (byte_count < 60) begin
          pad[byte_count-46] <= 8'h00;
          byte_count <= byte_count + 1;
        end else if (crc_index < 8) begin
          pad_crc[crc_index-4] <= 8'h00;
          crc_index <= crc_index + 1;
        end else begin
          tx_state <= 5;
        end
      end
      5: begin // Transmit state
        if (bit_count < (byte_count + 4) * 8) begin
          txd <= data[bit_count:bit_count];
          bit_count <= bit_count + 1;
          tx_en <= 1;
        end else begin
          tx_en <= 0;
          tx_done <= 1;
          tx_state <= 0;
        end
      end
    endcase
  end
end

// Receiver block
reg [7:0] rx_state = 0;
reg [7:0] rx_bit_count = 0;
reg [7:0] rx_byte_count = 0;
reg [7:0] rx_data_index = 0;
reg [7:0] rx_crc_index = 0;
reg [7:0] rx_crc [3:0];
reg [7:0] rx_data [1517:0];

always @(posedge clk) begin
  if (reset) begin
    rx_state <= 0;
    rx_bit_count <= 0;
    rx_byte_count <= 0;
    rx_data_index <= 0;
    rx_crc_index <= 0;
  end else begin
    case (rx_state)
      0: begin // Idle state
        if (rx_en) begin
          rx_state <= 1;
        end
      end
      1: begin // Preamble state
        if (rxd == 8'h55) begin
          rx_byte_count <= 1;
          rx_state <= 2;
        end else begin
          rx_state <= 0;
        end
      end
      2: begin // SFD state
        if (rxd == 8'hD5) begin
          rx_state <= 3;
        end else begin
          rx_state <= 0;
        end
      end
      3: begin // Destination MAC state
        rx_data[0:47] <= rxd;
        rx_data_index <= 48;
        rx_state <= 4;
      end
      4: begin // Source MAC state
        rx_data[48:95] <= rxd;
        rx_data_index <= 96;
        rx_state <= 5;
      end
      5: begin // Length state
        rx_data[96:111] <= rxd;
        rx_data_index <= 112;
        rx_state <= 6;
      end
      6: begin // Data state
        if (rx_byte_count < rx_data[96:111]) begin
          rx_data[rx_data_index:rx_data_index+7] <= rxd;
          rx_data_index <= rx_data_index + 8;
          rx_byte_count <= rx_byte_count + 1;
        end else begin
          rx_state <= 7;
        end
      end
      7: begin // CRC state
        if (rx_crc_index < 4) begin
          rx_crc[rx_crc_index] <= rxd;
          rx_crc_index <= rx_crc_index + 1;
        end else begin
          rx_state <= 8;
        end
      end
      8: begin // Check CRC state
        // TODO: Implement CRC check
        valid <= 1;
        dest_addr <= rx_data[0:47];
        src_addr <= rx_data[48:95];
        length <= rx_data[96:111];
        data_out <= rx_data[112:112+rx_data[96:111]*8-1];
        rx_state <= 0;
      end
    endcase
  end
end

endmodule

