module ConvolutionalEncoderViterbiDecoder (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 4; // number of input bits
parameter m = 6; // number of output bits
parameter k = 3; // constraint length of the encoder
parameter g = 3'b101; // generator polynomial

reg [k-1:0] shift_reg [n-1:0];
wire [m-1:0] encoded;

// convolutional encoder
genvar i;
generate
  for (i = 0; i < n; i = i + 1) begin: encoder
    always @(posedge clk) begin
      shift_reg[i][0] <= in[i];
      shift_reg[i][1] <= shift_reg[i][0];
      shift_reg[i][2] <= shift_reg[i][1];
    end
    assign encoded[i*2:i*2+1] = {shift_reg[i][0], shift_reg[i][1], shift_reg[i][2]} ^ g;
  end
endgenerate

// Viterbi decoder
reg [1:0] state [0:2**k-1];
reg [1:0] next_state [0:2**k-1][0:1];
reg [k-1:0] input_history [0:2**k-1][0:k-1];
reg [k-1:0] output_history [0:2**k-1][0:k-1];
reg [k-1:0] path_history [0:2**k-1][0:k-1];
reg [k-1:0] survivor_path [0:2**k-1];
reg [k-1:0] next_survivor_path [0:2**k-1];
reg [m-1:0] decoded;

// initialize state machine
initial begin
  state[0] = 2'b00;
  state[1] = 2'b01;
  state[2] = 2'b10;
  state[3] = 2'b11;
end

// define transition functions
generate
  for (i = 0; i < 2**k; i = i + 1) begin: transition
    always @(posedge clk) begin
      input_history[i][0] <= encoded[i*2];
      input_history[i][1] <= encoded[i*2+1];
      output_history[i][0] <= state[i][0];
      output_history[i][1] <= state[i][1];
      path_history[i][0] <= survivor_path[i] ^ output_history[i][0];
      path_history[i][1] <= survivor_path[i] ^ output_history[i][1];
      next_survivor_path[i] <= {path_history[i][0], path_history[i][1]};
      next_state[i][0] <= {state[i][1], encoded[i*2]};
      next_state[i][1] <= {state[i][1], encoded[i*2+1]};
    end
  end
endgenerate

// update state machine
always @(posedge clk) begin
  for (i = 0; i < 2**k; i = i + 1) begin
    state[i] <= next_state[i][decoded];
    survivor_path[i] <= next_survivor_path[i];
  end
end

// decode output bits
generate
  for (i = 0; i < m/2; i = i + 1) begin: decoder
    always @(posedge clk) begin
      decoded <= {state[0][1], state[1][1], state[2][1], state[3][1]};
    end
    assign out[i*2:i*2+1] = decoded;
  end
endgenerate

endmodule

