	// Parameters
	parameter depth = 9;
	parameter width = 8;

	// Inputs
	reg clk;
	reg [depth-1:0] a;
	reg we;
	reg [width-1:0] di;
	reg [depth-1:0] a2;
	reg we2;
	reg [width-1:0] di2;

	// Outputs
	wire [width-1:0] do;
	wire [width-1:0] do2;

	// Instantiate the dmx_dpram module
	dmx_dpram #(.depth(depth), .width(width)) dut (
		.clk(clk),
		.a(a),
		.we(we),
		.di(di),
		.do(do),
		.a2(a2),
		.we2(we2),
		.di2(di2),
		.do2(do2)
	);

	// Clock generation
	always #5 clk = ~clk;

	// Initialize the inputs
	initial begin
		clk = 0;
		a = 0;
		we = 1;
		di = 8'b10101010;
		a2 = 10;
		we2 = 1;
		di2 = 8'b01010101;

		#10; // Wait for two clock cycles

		// Read the data from the first RAM port and compare it with the expected value
		if (do !== 8'haa) $display("ERROR: do = %h, expected 0xaa", do);

		// Read the data from the second RAM port and compare it with the expected value
		if (do2 !== 8'h00) $display("ERROR: do2 = %h, expected 0x00", do2);

		// Write data to the first RAM port
		a = 1;
		we = 1;
