module hamming_distance_module (
    input clk,
    input reset,
    input [7:0] in,
    output reg [7:0] out
);

    reg [7:0] reference = 8'b10101010; // Reference value for Hamming distance calculation
    reg [7:0] shift_reg = 8'b00000000; // Shift register for input manipulation
    wire [7:0] comparator_out; // Output from comparator module
    wire [3:0] hamming_distance; // Output from Hamming distance calculation module
    wire [7:0] binary_out; // Output from binary conversion module

    // Comparator module
    // Compares the current bit with the reference value bit by bit
    // Outputs 1 if the bits differ, 0 if they are the same
    // Uses bitwise XOR operator to compare bits
    // Shifts the reference value to the right each clock cycle
    // Shifts the input value into the shift register each clock cycle
    // Outputs the result of the comparison to the Hamming distance calculation module
    always @(posedge clk) begin
        comparator_out[0] = (shift_reg[0] ^ reference[0]);
        comparator_out[1] = (shift_reg[1] ^ reference[1]);
        comparator_out[2] = (shift_reg[2] ^ reference[2]);
        comparator_out[3] = (shift_reg[3] ^ reference[3]);
        comparator_out[4] = (shift_reg[4] ^ reference[4]);
        comparator_out[5] = (shift_reg[5] ^ reference[5]);
        comparator_out[6] = (shift_reg[6] ^ reference[6]);
        comparator_out[7] = (shift_reg[7] ^ reference[7]);

        reference = {reference[6:0], 1'b0};
        shift_reg = {shift_reg[6:0], in};
    end

    // Hamming distance calculation module
    // Counts the number of positions where the input bit and reference bit differ
    // Outputs the Hamming distance as a 4-bit binary number
    // Uses a series of multiplexers and adders to calculate the Hamming distance
    // Each multiplexer selects either the input or the reference bit based on the output of the comparator module
    // The adders sum the outputs of the multiplexers to calculate the Hamming distance
    assign hamming_distance[0] = comparator_out[0];
    assign hamming_distance[1] = comparator_out[1] ^ comparator_out[0];
    assign hamming_distance[2] = comparator_out[2] ^ comparator_out[1] ^ comparator_out[0];
    assign hamming_distance[3] = comparator_out[3] ^ comparator_out[2] ^ comparator_out[1] ^ comparator_out[0];

    // Binary conversion module
    // Converts the 4-bit Hamming distance to an 8-bit binary number
    // Uses a series of multiplexers to select the appropriate binary value for each Hamming distance value
    assign binary_out[0] = 1'b0;
    assign binary_out[1] = hamming_distance[3];
    assign binary_out[2] = hamming_distance[2];
    assign binary_out[3] = 1'b0;
    assign binary_out[4] = hamming_distance[1];
    assign binary_out[5] = 1'b0;
    assign binary_out[6] = 1'b0;
    assign binary_out[7] = hamming_distance[0];

    // Output register with active high synchronous reset
    // Resets to 0 on reset signal
    always @(posedge clk) begin
        if (reset) begin
            out <= 8'b00000000;
        end else begin
            out <= binary_out;
        end
    end

endmodule

