    input fastclk,
    input reset_l
);

    reg [31:0] current_time_reg;
    reg [31:0] prev_time_reg;
    reg [31:0] time_diff_reg;
    reg [31:0] fastclk_count;

    always @(posedge clk) begin
        if (!reset_l) begin
            current_time_reg <= 0;
            prev_time_reg <= 0;
            time_diff_reg <= 0;
            fastclk_count <= 0;
        end else begin
            current_time_reg <= $time;
            time_diff_reg <= current_time_reg - prev_time_reg;
            prev_time_reg <= current_time_reg;
        end
    end

    always @(posedge fastclk) begin
        if (time_diff_reg != 0) begin
            fastclk_count <= fastclk_count + 1;
        end
        if (fastclk_count == 1) begin
            $display("[%0t] Hello, world!", current_time_reg);
            fastclk_count <= 0;
        end
    end

endmodule

module cpu (
    input CLK,
    input RESET,
    input [7:0] INSTR,
    input [7:0] DATA,
    output reg [7:0] OUT,
    output reg FLAG
);

reg [7:0] temp;

always @(posedge CLK) begin
    if (RESET) begin
        OUT <= 8'h00;
        FLAG <= 1;
    end else begin
        case (INSTR)
            8'h00: begin // NOP
                // Do nothing
            end
            8'h01: begin // ADD
                temp = OUT + DATA;
                OUT <= temp;
                FLAG <= 1;
            end
            8'h02: begin // SUB
                temp = OUT - DATA;
                OUT <= temp;
                FLAG <= 1;
            end
            8'h03: begin // MOV
                OUT <= DATA;
                FLAG <= 1;
            end
            8'h04: begin // CMP
                if (OUT == DATA) begin
                    FLAG <= 1;
                end else begin
                    FLAG <= 0;
                end
            end
            8'h05: begin // HLT
                // Do nothing
            end
        endcase
    end
end

endmodule

module decoder_3to8 (
    input A,
    input B,
    input C,
    output reg Y0,
    output reg Y1,
    output reg Y2,
    output reg Y3,
    output reg Y4,
    output reg Y5,
    output reg Y6,
    output reg Y7
);

always @(*) begin
    case ({A,B,C})
        3'b000: begin
            Y0 <= 0;
            Y1 <= 1;
            Y2 <= 1;
            Y3 <= 1;
            Y4 <= 1;
            Y5 <= 1;
            Y6 <= 1;
            Y7 <= 1;
        end
        3'b001: begin
            Y0 <= 1;
            Y1 <= 0;
            Y2 <= 1;
            Y3 <= 1;
            Y4 <= 1;
            Y5 <= 1;
            Y6 <= 1;
            Y7 <= 1;
        end
        3'b010: begin
            Y0 <= 1;
            Y1 <= 1;
            Y2 <= 0;
            Y3 <= 1;
            Y4 <= 1;
            Y5 <= 1;
            Y6 <= 1;
            Y7 <= 1;
        end
        3'b011: begin
            Y0 <= 1;
            Y1 <= 1;
            Y2 <= 1;
            Y3 <= 0;
            Y4 <= 1;
            Y5 <= 1;
            Y6 <= 1;
            Y7 <= 1;
        end
        3'b100: begin
            Y0 <= 1;
            Y1 <= 1;
            Y2 <= 1;
            Y3 <= 1;
            Y4 <= 0;
            Y5 <= 1;
            Y6 <= 1;
            Y7 <= 1;
        end
        3'b101: begin
            Y0 <= 1;
            Y1 <= 1;
            Y2 <= 1;
            Y3 <= 1;
            Y4 <= 1;
            Y5 <= 0;
            Y6 <= 1;
            Y7 <= 1;
        end
        3'b110: begin
            Y0 <= 1;
            Y1 <= 1;
            Y2 <= 1;
            Y3 <= 1;
            Y4 <= 1;
            Y5 <= 1;
            Y6 <= 0;
            Y7 <= 1;
        end
        3'b111: begin
            Y0 <= 1;
            Y1 <= 1;
            Y2 <= 1;
            Y3 <= 1;
            Y4 <= 1;
            Y5 <= 1;
            Y6 <= 1;
            Y7 <= 0;
        end
    endcase
end

endmodule

module barrel_shift_dff (
    input clk,
    input reset,
    input [99:0] data,
    input d,
    input select,
    input load,
    input [1:0] ena,
    output reg [7:0] q
);

reg [7:0] shifted_data;
reg [7:0] dff_output;

always @ (posedge clk) begin
    if (reset) begin
        shifted_data <= 8'b0;
        dff_output <= 1'b0;
    end else begin
        if (select) begin
            if (load) begin
                dff_output <= d;
            end
            q <= dff_output;
        end else begin
            case (ena)
                2'b01: shifted_data <= {data[98:0], 1'b0};
                2'b10: shifted_data <= {1'b0, data[99:1]};
                default: shifted_data <= data[99:92];
            endcase
            q <= shifted_data;
        end
    end
end

endmodule

module TemperatureMonitor(
    input wire DCLK_IN,
    input wire [15:0] DI_IN,
    input wire DWE_IN,
    input wire DEN_IN,
    input wire VP_IN,
    input wire VN_IN,
    output reg DRDY_OUT,
    output reg [15:0] DO_OUT,
    input wire [6:0] DADDR_IN
    );

    reg [15:0] temperature;
    reg [15:0] data_reg;
    reg [1:0] state;
    reg [3:0] counter;

    always @(posedge DCLK_IN) begin
        if (DEN_IN) begin
            case (state)
                2'b00: begin
                    data_reg <= DI_IN;
                    state <= 2'b01;
                    counter <= 4'd0;
                end
                2'b01: begin
                    counter <= counter + 1;
                    if (counter == 4'd7) begin
                        state <= 2'b10;
                        counter <= 4'd0;
                    end
                end
                2'b10: begin
                    temperature <= {data_reg[11:0], DI_IN[3:0]};
                    state <= 2'b00;
                    DRDY_OUT <= 1'b1;
                end
            endcase
        end else if (DWE_IN) begin
            case (DADDR_IN)
                7'h00: begin
                    DO_OUT <= temperature;
                    DRDY_OUT <= 1'b0;
                end
                default: begin
                    DO_OUT <= 16'h0000;
                    DRDY_OUT <= 1'b0;
                end
            endcase
        end
    end

endmodule

module rng(reset, rnreset, rngbitin, rngbitinclk, rngbitoutclk, rngbitout, rngdone, handle);
input reset, rnreset, rngbitoutclk;
input rngbitin, rngbitinclk;
output rngbitout, rngdone;
output [15:0] handle;

reg [15:0] rn;
reg [3:0] bitoutcounter;

assign handle[15:0] = rn[15:0];
assign rngbitout    = rn[bitoutcounter];

assign rngdone   = (bitoutcounter == 0);
reg    initialized;

always @ (posedge rngbitoutclk or posedge reset) begin
  if (reset) begin
    bitoutcounter <= 0;
    initialized   <= 0;
  end else if (!initialized) begin
    initialized   <= 1;
    bitoutcounter <= 15;
  end else if (!rngdone) begin
    bitoutcounter <= bitoutcounter - 4'd1;
  end else begin
  end // ~reset
end // always

always @ (posedge rngbitinclk or posedge rnreset) begin
  if (rnreset) begin
    rn <= 16'h0000;
  end else begin
    rn[0]  <= rngbitin ^ rn[15];
    rn[1]  <= rn[0];
    rn[2]  <= rn[1];
    rn[3]  <= rn[2];
    rn[4]  <= rn[3];
    rn[5]  <= rn[4] ^ rngbitin ^ rn[15];
    rn[6]  <= rn[5];
    rn[7]  <= rn[6];
    rn[8]  <= rn[7];
    rn[9]  <= rn[8];
    rn[10] <= rn[9];
    rn[11] <= rn[10];
    rn[12] <= rn[11] ^ rngbitin ^ rn[15];
    rn[13] <= rn[12];
    rn[14] <= rn[13];
    rn[15] <= rn[14];
  end // ~rnreset
end // always

endmodule

