module lo_simulate(
    pck0, ck_1356meg, ck_1356megb,
    pwr_lo, pwr_hi, pwr_oe1, pwr_oe2, pwr_oe3, pwr_oe4,
    adc_d, adc_clk,
    ssp_frame, ssp_din, ssp_dout, ssp_clk,
    cross_hi, cross_lo,
    dbg,
    divisor
);
    input pck0, ck_1356meg, ck_1356megb;
    output pwr_lo, pwr_hi, pwr_oe1, pwr_oe2, pwr_oe3, pwr_oe4;
    input [7:0] adc_d;
    output adc_clk;
    input ssp_dout;
    output ssp_frame, ssp_din, ssp_clk;
    input cross_hi, cross_lo;
    output dbg;
    input [7:0] divisor;

    reg [7:0] pck_divider;
    reg clk_state;
    reg is_high;
    reg is_low;
    reg output_state;

    assign pwr_oe3 = 1'b0;
    assign pwr_oe1 = ssp_dout;
    assign pwr_oe2 = ssp_dout;
    assign pwr_oe4 = ssp_dout;
    assign ssp_clk = cross_lo;
    assign pwr_lo = 1'b0;
    assign pwr_hi = 1'b0;
    assign dbg = ssp_frame;

    always @(posedge pck0) begin
        if (pck_divider == divisor[7:0]) begin
            pck_divider <= 8'd0;
            clk_state <= ~clk_state;
        end else begin
            pck_divider <= pck_divider + 1;
        end
    end

    assign adc_clk = ~clk_state;

    always @(posedge pck0) begin
        if ((pck_divider == 8'd7) && !clk_state) begin
            is_high <= (adc_d >= 8'd200);
            is_low <= (adc_d <= 8'd64);
        end
    end

    always @(posedge is_high or posedge is_low) begin
        if (is_high) begin
            output_state <= 1'd1;
        end else if (is_low) begin
            output_state <= 1'd0;
        end
    end

    assign ssp_frame = output_state;
    assign ssp_din = ssp_dout;

endmodule

module led_controller (
    input  wire       clk,
    input  wire       reset_n,
    input  wire [3:0] sw,
    input  wire [3:0] btn,
    output wire       led0_r,
    output wire       led0_g,
    output wire       led0_b,
    output wire       led1_r,
    output wire       led1_g,
    output wire       led1_b,
    output wire       led2_r,
    output wire       led2_g,
    output wire       led2_b,
    output wire       led3_r,
    output wire       led3_g,
    output wire       led3_b,
    output wire       led4,
    output wire       led5,
    output wire       led6,
    output wire       led7
);

reg [3:0] led_val;

always @ (posedge clk) begin
    if (~reset_n) begin
        led_val <= 0;
        led0_r <= 0;
        led0_g <= 0;
        led0_b <= 0;
        led1_r <= 0;
        led1_g <= 0;
        led1_b <= 0;
        led2_r <= 0;
        led2_g <= 0;
        led2_b <= 0;
        led3_r <= 0;
        led3_g <= 0;
        led3_b <= 0;
        led4 <= 0;
        led5 <= 0;
        led6 <= 0;
        led7 <= 0;
    end else begin
        case(btn)
            4'b0001: led_val <= sw;
            4'b0010: led_val <= {sw[0], sw[1], sw[2], sw[3]};
            4'b0100: led_val <= {sw[2:0], sw[3]};
            4'b1000: led_val <= {sw[3], sw[2:0]};
            default: led_val <= led_val;
        endcase

        led0_r <= led_val[0];
        led0_g <= led_val[1];
        led0_b <= led_val[2];
        led1_r <= led_val[0];
        led1_g <= led_val[1];
        led1_b <= led_val[2];
        led2_r <= led_val[0];
        led2_g <= led_val[1];
        led2_b <= led_val[2];
        led3_r <= led_val[0];
        led3_g <= led_val[1];
        led3_b <= led_val[2];
        led4 <= led_val[3];
        led5 <= led_val[2];
        led6 <= led_val[1];
        led7 <= led_val[0];
    end
end

endmodule

module rotator(
    input clk,
    input load,
    input [1:0] ena,
    input [99:0] data,
    output reg [99:0] q
);

reg [99:0] shift_reg [2:0];
reg [1:0] ena_reg;
reg [99:0] load_data;

always @(posedge clk) begin
    ena_reg <= ena;
    if (load) begin
        load_data <= data;
    end
end

always @(posedge clk) begin
    if (ena_reg == 2'b01) begin // right shift
        shift_reg[0] <= {shift_reg[1][99], shift_reg[1][99:1]};
        shift_reg[1] <= {shift_reg[2][99], shift_reg[2][99:1]};
        shift_reg[2] <= {shift_reg[2][99], shift_reg[2][99:1]};
        shift_reg[2][0] <= shift_reg[1][99];
    end else if (ena_reg == 2'b10) begin // left shift
        shift_reg[0] <= {shift_reg[0][98:0], shift_reg[1][0]};
        shift_reg[1] <= {shift_reg[1][98:0], shift_reg[2][0]};
        shift_reg[2] <= {shift_reg[1][0], shift_reg[2][98:0]};
    end else begin // no shift
        shift_reg[0] <= shift_reg[0];
        shift_reg[1] <= shift_reg[1];
        shift_reg[2] <= shift_reg[2];
    end

    if (load) begin
        shift_reg[0] <= load_data;
        shift_reg[1] <= 0;
        shift_reg[2] <= 0;
    end

    q <= shift_reg[0];
end

endmodule

module binary_counter (clk, reset, count);

input clk, reset;
output [3:0] count;

reg [3:0] count;

always @(posedge clk or negedge reset) begin
    if (!reset) begin
        count <= 4'd0;
    end else begin
        count <= count + 4'd1;
    end
end

endmodule

module top_module (
    input CLK,
    input RST,
    input LD,
    input [3:0] D,
    input select,
    output reg [7:0] OUT
);

reg [3:0] shift_reg;
reg [7:0] shifted_value;

barrel_shifter bs(
    .in(shift_reg),
    .out(shifted_value),
    .select(select)
);

always @(posedge CLK) begin
    if (RST) begin
        shift_reg <= 4'b0;
    end else if (LD) begin
        shift_reg <= D;
    end else begin
        shift_reg <= {shift_reg[2:0], shifted_value[0]};
    end
end

assign OUT = shifted_value | shift_reg;

endmodule

module barrel_shifter (
    input [3:0] in,
    output reg [7:0] out,
    input select
);

always @(*) begin
    case (select)
        1'b0: out = {in, 4'b0};
        1'b1: out = {4'b0, in};
    endcase
end

endmodule

