module fsm (
    input in,
    output out
);

    parameter s0 = 3'b000, s1 = 3'b001, s2 = 3'b010, s3 = 3'b011, s4 = 3'b100, s5 = 3'b101;
    reg [2:0] currentState, nextState;

    always @ (currentState or in) begin
        case (currentState)
            s0: if (in == 1'b0) nextState = s1; else nextState = s5;
            s1: if (in == 1'b0) nextState = s2; else nextState = s5;
            s2: if (in == 1'b0) nextState = s3; else nextState = s5;
            s3: if (in == 1'b0) nextState = s4; else nextState = s5;
            s4: if (in == 1'b0) nextState = s5; else nextState = s5;
            s5: nextState = s5;
        endcase
    end

    always @ (posedge clk) begin
        currentState <= nextState;
    end

    assign out = (currentState == s5);

endmodule

module booth_multiplier (
    input [3:0] A,
    input [3:0] B,
    output [7:0] P
);

reg [7:0] P_reg;
reg [3:0] A_reg, B_reg;
reg [2:0] count;

always @(posedge clk) begin
    if (reset) begin
        P_reg <= 8'b0;
        A_reg <= 4'b0;
        B_reg <= 4'b0;
        count <= 3'b0;
    end else begin
        P_reg <= {P_reg[6:0], P_reg[7]};
        case (count)
            3'b000: begin
                A_reg <= A;
                B_reg <= {B[3], B};
            end
            3'b001, 3'b010: begin
                if (B_reg[0] == 1) begin
                    P_reg <= P_reg + (A_reg << count);
                end
                B_reg <= {B_reg[3], B_reg};
            end
            3'b011: begin
                if (B_reg[0] == 0) begin
                    P_reg <= P_reg + (A_reg << count);
                end
                B_reg <= {B_reg[3], B_reg};
            end
            3'b100: begin
                if (B_reg[0] == 1) begin
                    P_reg <= P_reg + (A_reg << count);
                end
                B_reg <= {B_reg[3], B_reg};
            end
        endcase
        count <= count + 1;
    end
end

assign P = P_reg;

endmodule

