always @(posedge clk) begin
  if (en) begin
    counter <= counter + 1;
    if (counter == fosc/fclk/2 - 1) begin
      toggle <= ~toggle;
      counter <= 0;
    end
  end
end

always @(posedge clk) begin
  if (en) begin
    clk <= toggle;
  end
end

