module top_module (
    input [7:0] in, // 8-bit data input port
    input sel_a1, // Select input for the 2-to-1 mux
    input sel_a2, // Select input for the 2-to-1 mux
    input clk, // Clock input
    output reg [8:0] out // 9-bit output with parity bit added
);

// Declare internal signals
reg [7:0] mux_out;
reg parity_bit;

// Define state machine states
parameter IDLE = 2'b00;
parameter MUX_SELECT_A = 2'b01;
parameter MUX_SELECT_B = 2'b10;
parameter PARITY_GENERATE = 2'b11;

// Define state machine inputs
reg [1:0] state;
reg [1:0] next_state;

// Define state machine outputs
reg mux_sel;

// Define state machine transitions and outputs
always @(posedge clk) begin
    state <= next_state;
    case (state)
        IDLE:
            begin
                mux_sel <= 0;
                next_state <= sel_a1 ? MUX_SELECT_A : MUX_SELECT_B;
            end
        MUX_SELECT_A:
            begin
                mux_sel <= 1;
                next_state <= MUX_SELECT_B;
            end
        MUX_SELECT_B:
            begin
                mux_sel <= 0;
                next_state <= PARITY_GENERATE;
            end
        PARITY_GENERATE:
            begin
                mux_sel <= 0;
                next_state <= IDLE;
            end
    endcase
end

// Define state machine actions
always @(state) begin
    case (state)
        IDLE:
            begin
                mux_out <= 0;
                parity_bit <= 0;
            end
        MUX_SELECT_A:
            begin
                mux_out <= sel_a2 ? in : 0;
            end
        MUX_SELECT_B:
            begin
                mux_out <= sel_a2 ? 0 : in;
            end
        PARITY_GENERATE:
            begin
                mux_out <= 0;
                parity_bit <= ~^out;
            end
    endcase
end

// Assign output
assign out = {mux_out, parity_bit};

endmodule

