module Debouncer (
    input CLK,
    input IN,
    output reg OUT
);

reg [15:0] count = 0;
reg [1:0] state = 2'b11;

always @(posedge CLK) begin
    case (state)
        2'b00: begin
            // Waiting for switch to stabilize in the pressed state
            if (IN == 1) begin
                state <= 2'b01;
                count <= 0;
            end
        end
        2'b01: begin
            // Switch is pressed, waiting for debounce time
            if (count == 200) begin
                state <= 2'b10;
                count <= 0;
            end else begin
                count <= count + 1;
            end
        end
        2'b10: begin
            // Switch is still pressed, generating output pulse
            OUT <= 1;
            if (count == 1) begin
                state <= 2'b11;
                count <= 0;
                OUT <= 0;
            end else begin
                count <= count + 1;
            end
        end
        2'b11: begin
            // Waiting for switch to stabilize in the released state
            if (IN == 0) begin
                state <= 2'b00;
                count <= 0;
            end
        end
    endcase
end

endmodule

