reg [7:0] charging_counter;

always @(posedge clk or posedge rst) begin
  if (rst) begin
    charging <= 0;
    charging_counter <= 0;
  end else begin
    if (battery_voltage < max_voltage && input_voltage > battery_voltage) begin
      charging <= 1;
      charging_counter <= charging_counter + 1;
    end else begin
      charging <= 0;
      charging_counter <= 0;
    end
  end
end

assign charging_current = charging ? charge_current : 0;
assign battery_status = charging ? 1 : 0;

