module led_flasher (
  input clk,
  input LED_flash,
  output reg LED_out
);

  // Parameters
  parameter HIGH_PERIOD = 600;
  parameter LOW_PERIOD = 600;
  parameter s_reset = 2'd0;
  parameter s_off = 2'd1;
  parameter s_on = 2'd2;

  // Signals & Registers
  reg [15:0] cnt = 0;
  reg [1:0] state = s_reset;

  // State Machine
  always @(posedge clk) begin
    case (state)
      s_reset:
        begin
          cnt <= 0;
          if (LED_flash)
            state <= s_on;
        end

      s_off:
        begin
          cnt <= cnt + 1;
          LED_out <= 0;
          if (cnt == LOW_PERIOD && LED_flash)
            state <= s_on;
          else if (!LED_flash)
            state <= s_reset;
        end

      s_on:
        begin
          cnt <= cnt + 1;
          LED_out <= 1;
          if (cnt == HIGH_PERIOD && LED_flash)
            state <= s_off;
          else if (!LED_flash)
            state <= s_reset;
        end
    endcase
  end

endmodule

