module fifo_cdc(/*AUTOARG*/
   // Outputs
   wait_out, access_out, packet_out,
   // Inputs
   clk_in, clk_out, nreset, access_in, packet_in, wait_in
   );

   parameter DW = 104;
   parameter DEPTH = 16;

   //clock, reset
   input             clk_in;
   input 	     clk_out;   
   input             nreset;
   output reg 	     wait_out;

   //Stimulus Driven Transaction
   input 	     access_in;
   input [DW-1:0]    packet_in;
   input 	     wait_in;

   //DUT driven transactoin
   output reg 	     access_out;
   output [DW-1:0]   packet_out;

   /*AUTOINPUT*/
   /*AUTOOUTPUT*/
   /*AUTOWIRE*/

   reg [DEPTH-1:0] fifo_wr_ptr = 0;
   reg [DEPTH-1:0] fifo_rd_ptr = 0;
   reg [DW-1:0] fifo [0:DEPTH-1];
   reg [DW-1:0] fifo_out;
   reg fifo_empty = 1'b1;
   reg fifo_full = 1'b0;

   always @(posedge clk_in) begin
      if (nreset == 1'b0) begin
         fifo_wr_ptr <= 0;
         fifo_rd_ptr <= 0;
         fifo_empty <= 1'b1;
         fifo_full <= 1'b0;
         wait_out <= 1'b0;
         access_out <= 1'b0;
      end else if (access_in == 1'b1 && fifo_full == 1'b0 && wait_in == 1'b0) begin
         fifo[fifo_wr_ptr] <= packet_in;
         fifo_wr_ptr <= fifo_wr_ptr + 1;
         if (fifo_wr_ptr == DEPTH) begin
            fifo_wr_ptr <= 0;
         end
         fifo_empty <= 1'b0;
         if (fifo_wr_ptr == fifo_rd_ptr) begin
            fifo_full <= 1'b1;
         end
      end else if (access_out == 1'b1) begin
         fifo_out <= fifo[fifo_rd_ptr];
         fifo_rd_ptr <= fifo_rd_ptr + 1;
         if (fifo_rd_ptr == DEPTH) begin
            fifo_rd_ptr <= 0;
         end
         fifo_full <= 1'b0;
         if (fifo_rd_ptr == fifo_wr_ptr) begin
            fifo_empty <= 1'b1;
         end
      end
   end

   always @(posedge clk_out) begin
      if (nreset == 1'b0) begin
         access_out <= 1'b0;
         packet_out <= 0;
      end else if (fifo_empty == 1'b0) begin
         access_out <= 1'b1;
         packet_out <= fifo_out;
      end else begin
         access_out <= 1'b0;
         packet_out <= 0;
      end
      wait_out <= fifo_full;
   end

endmodule

module mult8bit(
  input [7:0] A,
  input [7:0] B,
  output reg [15:0] result
);

  reg [7:0] temp;
  integer i, j;

  always @* begin
    result = 0;
    for (i = 0; i < 8; i = i + 1) begin
      temp = 0;
      for (j = 0; j < 8; j = j + 1) begin
        if ((B[j] == 1) && (A[i] == 1)) begin
          temp = temp + (1 << (i + j));
        end
      end
      result = result + temp;
    end
  end

endmodule

