module trafficLightController (
  input wire clk,
  input wire clr,
  output reg [5:0] lights
);

  reg [2:0] state;
  reg [3:0] count;
  parameter S0 = 3'b000, S1 = 3'b001, S2 = 3'b010, // states
            S3 = 3'b011, S4 = 3'b100, S5 = 3'b101;
  parameter SEC5 = 4'b0101, SEC1 = 4'b0001; // delays

  always @(posedge clk or posedge clr) begin
    if (clr == 1) begin
      state = S0;
      count = 0;
    end else begin
      case(state)
        S0: if(count < SEC5) begin
              state = S0;
              count = count + 1'b1;
            end else begin
              state = S1;
              count = 0;
            end
        S1: if(count < SEC1) begin
              state = S1;
              count = count + 1'b1;
            end else begin
              state = S2;
              count = 0;
            end
        S2: if(count < SEC1) begin
              state = S2;
              count = count + 1'b1;
            end else begin
              state = S3;
              count = 0;
            end 
        S3: if(count < SEC5) begin
              state = S3;
              count = count + 1'b1;
            end else begin
              state = S4;
              count = 0;
            end
        S4: if(count < SEC1) begin
              state = S4;
              count = count + 1'b1;
            end else begin
              state = S5;
              count = 0;
            end
        S5: if(count < SEC1) begin
              state = S5;
              count = count + 1'b1;
            end else begin
              state = S0;
              count = 0;
            end
        default: state = S0;
      endcase
    end
  end

  always @(*) begin
    case(state)
      S0: lights = 6'b100001;
      S1: lights = 6'b100010;
      S2: lights = 6'b100100;
      S3: lights = 6'b001100;
      S4: lights = 6'b010100;
      S5: lights = 6'b100100;
      default: lights = 6'b100001;
    endcase
  end

endmodule

module splitter #(
  parameter NUM_SLAVES = 2
) (
  output reg [NUM_SLAVES-1:0] m_ready_d,
  input aresetn_d,
  input aa_grant_rnw,
  input m_valid_i,
  input s_axi_arready_i_reg,
  input m_valid_i_reg,
  input aclk
);

  parameter LUT_INIT_0 = 64'h0000000000AA002A;
  parameter LUT_INIT_1 = 64'hAA00AA8000000000;

  reg [NUM_SLAVES-1:0] m_ready_d_reg;
  reg [NUM_SLAVES-1:0] m_valid_i_reg_reg;
  reg [NUM_SLAVES-1:0] holding_data;
  reg [NUM_SLAVES-1:0] holding_valid;
  reg [NUM_SLAVES-1:0] holding_arready;
  reg [NUM_SLAVES-1:0] holding_grant;
  reg [NUM_SLAVES-1:0] holding_rnw;

  wire [NUM_SLAVES-1:0] m_ready_d_lut;
  wire [NUM_SLAVES-1:0] m_ready_d_lut_n;
  wire [NUM_SLAVES-1:0] m_ready_d_lut_n_reg;
  wire [NUM_SLAVES-1:0] m_ready_d_lut_n_reg_reg;

  assign m_ready_d = m_ready_d_reg;

  // LUTs for m_ready_d
  generate
    genvar i;
    for (i = 0; i < NUM_SLAVES; i = i + 1) begin : lut_block
      LUT6 #(
        .INIT(i == 0 ? LUT_INIT_0 : LUT_INIT_1)
      ) lut (
        .I0(aresetn_d),
        .I1(aa_grant_rnw),
        .I2(m_valid_i),
        .I3(m_ready_d_lut_n[i]),
        .I4(s_axi_arready_i_reg),
        .I5(m_valid_i_reg_reg[i]),
        .O(m_ready_d_lut[i])
      );
    end
  endgenerate

  // Register for m_ready_d_lut_n
  always @(posedge aclk) begin
    m_ready_d_lut_n_reg <= m_ready_d_lut_n;
    m_ready_d_lut_n_reg_reg <= m_ready_d_lut_n_reg;
  end

  // Holding data and valid signals
  always @(posedge aclk) begin
    if (~aresetn_d) begin
      holding_data <= {NUM_SLAVES{1'b0}};
      holding_valid <= {NUM_SLAVES{1'b0}};
      holding_arready <= {NUM_SLAVES{1'b0}};
      holding_grant <= {NUM_SLAVES{1'b0}};
      holding_rnw <= {NUM_SLAVES{1'b0}};
    end else begin
      if (m_valid_i && m_ready_d == {NUM_SLAVES{1'b1}}) begin
        holding_data <= {NUM_SLAVES{m_valid_i_reg}};
        holding_valid <= {NUM_SLAVES{1'b1}};
        holding_arready <= {NUM_SLAVES{s_axi_arready_i_reg}};
        holding_grant <= {NUM_SLAVES{aa_grant_rnw}};
        holding_rnw <= {NUM_SLAVES{aa_grant_rnw}};
      end else begin
        holding_data <= holding_data;
        holding_valid <= holding_valid;
        holding_arready <= holding_arready;
        holding_grant <= holding_grant;
        holding_rnw <= holding_rnw;
      end
    end
  end

  // Register for m_valid_i_reg
  always @(posedge aclk) begin
    if (~aresetn_d) begin
      m_valid_i_reg_reg <= {NUM_SLAVES{1'b0}};
    end else begin
      m_valid_i_reg_reg <= holding_valid;
    end
  end

  // Update m_ready_d_reg
  always @(posedge aclk) begin
    if (~aresetn_d) begin
      m_ready_d_reg <= {NUM_SLAVES{1'b0}};
    end else begin
      m_ready_d_reg <= m_ready_d_lut_n_reg_reg & ~holding_arready;
    end
  end

  // Update m_ready_d_lut_n
  always @(posedge aclk) begin
    if (~aresetn_d) begin
      m_ready_d_lut_n <= {NUM_SLAVES{1'b0}};
    end else begin
      m_ready_d_lut_n <= m_ready_d_lut & ~holding_arready;
    end
  end

  // Data output to slaves
  generate
    genvar i;
    for (i = 0; i < NUM_SLAVES; i = i + 1) begin : slave_block
      assign m_ready_d_lut_n[i] = m_ready_d_lut_n_reg_reg[i] | holding_arready[i];
      assign s_axi_arready_i_reg = m_ready_d_lut_n_reg_reg[i] & ~holding_arready[i];
      assign m_valid_i_reg = m_valid_i_reg_reg[i];
      assign aa_grant_rnw = holding_grant[i];
      assign m_ready_d_lut_n_reg[i] = m_ready_d_lut_n[i];
      assign m_ready_d_lut_n_reg_reg[i] = m_ready_d_lut_n_reg[i];
      assign holding_data[i] = s_axi_arready_i_reg ? 0 : holding_data[i];
    end
  endgenerate

endmodule

module adder(
    input clk, reset, enable,
    input [3:0] A, B,
    output [3:0] S,
    output Cout
);
    reg [3:0] S_reg; // register for storing the sum
    reg Cout_reg; // register for storing the carry-out
    wire [3:0] A_reg, B_reg; // registers for storing the inputs

    always @(posedge clk) begin
        if (reset) begin
            S_reg <= 4'b0;
            Cout_reg <= 1'b0;
            A_reg <= A;
            B_reg <= B;
        end
        else if (enable) begin
            S_reg <= A_reg + B_reg;
            Cout_reg <= (A_reg[3] & B_reg[3]) | (A_reg[3] & ~S_reg[3]) | (B_reg[3] & ~S_reg[3]);
            A_reg <= A;
            B_reg <= B;
        end
    end

    assign S = S_reg;
    assign Cout = Cout_reg;

endmodule

module counter_4bit (
