module ad_mac_1 (

  clk,

  // inputs

  data_s0,
  data_s1,
  data_s2,
  data_s3,
  data_s4,
  data_s5,
  coefficients,

  // outputs

  mac_data_0,
  mac_data_1);

  input           clk;
  input   [15:0]  data_s0;
  input   [15:0]  data_s1;
  input   [15:0]  data_s2;
  input   [15:0]  data_s3;
  input   [15:0]  data_s4;
  input   [15:0]  data_s5;
  input   [3:0]   coefficients;

  output  [15:0]  mac_data_0;
  output  [15:0]  mac_data_1;

  // internal registers

  reg     [15:0]  mac_data_0_reg = 'd0;
  reg     [15:0]  mac_data_1_reg = 'd0;

  // multiply and accumulate

  always @(posedge clk) begin
    mac_data_0_reg <= ((data_s0 * coefficients[0]) +
                       (data_s1 * coefficients[1]) +
                       (data_s2 * coefficients[2]) +
                       (data_s3 * coefficients[3])) >> 4;
    mac_data_1_reg <= ((data_s1 * coefficients[0]) +
                       (data_s2 * coefficients[1]) +
                       (data_s3 * coefficients[2]) +
                       (data_s4 * coefficients[3])) >> 4;
  end

  assign mac_data_0 = mac_data_0_reg;
  assign mac_data_1 = mac_data_1_reg;

endmodule

module booth_multiplier (
    input clk,
    input reset,
    input [3:0] a,
    input [3:0] b,
    output reg [7:0] product
);

reg [4:0] a_reg;
reg [4:0] b_reg;
reg [9:0] product_reg;
reg [2:0] count;

always @(posedge clk or negedge reset) begin
    if (reset == 0) begin
        a_reg <= 0;
        b_reg <= 0;
        product_reg <= 0;
        count <= 0;
    end else begin
        a_reg <= {a, 1'b0};
        b_reg <= {b, 1'b0};
        count <= 3;
    end
end

always @(posedge clk or negedge reset) begin
    if (reset == 0) begin
        product_reg <= 0;
    end else begin
        case (count)
            3: begin
                if (b_reg[3:2] == 2'b01) begin
                    product_reg <= product_reg + (a_reg << 1);
                end else if (b_reg[3:2] == 2'b10) begin
                    product_reg <= product_reg + (a_reg << 2);
                end
                count <= 2;
            end
            2: begin
                if (b_reg[2:1] == 2'b01) begin
                    product_reg <= product_reg + (a_reg << 1);
                end else if (b_reg[2:1] == 2'b10) begin
                    product_reg <= product_reg + (a_reg << 2);
                end
                count <= 1;
            end
            1: begin
                if (b_reg[1:0] == 2'b01) begin
                    product_reg <= product_reg + (a_reg << 1);
                end else if (b_reg[1:0] == 2'b10) begin
                    product_reg <= product_reg + (a_reg << 2);
                end
                count <= 0;
            end
            0: begin
                product <= product_reg[7:0];
            end
        endcase
    end
end

endmodule

