module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] d1,   // Input for multiplexer
    input [7:0] d2,   // Input for multiplexer
    input sel,        // Select input for multiplexer
    output [7:0] q    // Output from functional module
);

    // Counter module
    reg [3:0] count;
    always @(posedge clk) begin
        if (reset) begin
            count <= 4'b0000;
        end else begin
            count <= count + 1;
        end
    end

    // Multiplexer module
    wire [7:0] mux_out;
    mux_2to1 mux_inst (
        .a(d1),
        .b(d2),
        .sel(sel),
        .out(mux_out)
    );

    // Functional module
    wire [7:0] sum;
    assign sum = count + mux_out;

    // Output
    assign q = sum;

endmodule

// 2-to-1 multiplexer module
module mux_2to1 (
    input [7:0] a,
    input [7:0] b,
    input sel,
    output reg [7:0] out
);
    always @(*) begin
        if (sel) begin
            out = b;
        end else begin
            out = a;
        end
    end
endmodule

module lf_edge_detect(
    input clk,
    input [7:0] adc_d,
    input [7:0] lf_ed_threshold,
    output [7:0] max,
    output [7:0] min,
    output [7:0] high_threshold,
    output [7:0] highz_threshold,
    output [7:0] lowz_threshold,
    output [7:0] low_threshold,
    output edge_state,
    output edge_toggle
);

    // Define constants
    parameter THRESHOLD_DIFF = 8;
    parameter HIGHZ_DIFF = 16;
    parameter TRIGGER_DIFF = 4;

    // Define internal signals
    reg is_high = 0;
    reg is_low = 0;
    reg is_zero = 0;
    reg output_edge = 0;
    reg output_state = 0;
    reg trigger_enabled = 1;
    wire enabled =
        (high_threshold > highz_threshold) &
        (highz_threshold > lowz_threshold) &
        (lowz_threshold > low_threshold) &
        ((high_threshold - highz_threshold) > THRESHOLD_DIFF) &
        ((highz_threshold - lowz_threshold) > HIGHZ_DIFF) &
        ((lowz_threshold - low_threshold) > THRESHOLD_DIFF);

    // Instantiate min_max_tracker module
    min_max_tracker tracker(clk, adc_d, lf_ed_threshold, min, max);

    // Calculate thresholds
    assign high_threshold = (max + min) / 2 + (max - min) / 4;
    assign highz_threshold = (max + min) / 2 + (max - min) / 8;
    assign lowz_threshold = (max + min) / 2 - (max - min) / 8;
    assign low_threshold = (max + min) / 2 - (max - min) / 4;

    // Detect edges
    always @(posedge clk) begin
        is_high <= (adc_d >= high_threshold);
        is_low <= (adc_d <= low_threshold);
        is_zero <= ((adc_d > lowz_threshold) & (adc_d < highz_threshold));
        if (enabled) begin
            if (trigger_enabled & (is_high | is_low)) begin
                output_edge <= ~output_edge;
                output_state <= is_high;
                trigger_enabled <= 0;
            end else if (trigger_enabled & is_zero) begin
                output_state <= output_state;
            end else
                trigger_enabled <= trigger_enabled | is_zero;
        end
    end

    // Output signals
    assign edge_state = output_state;
    assign edge_toggle = output_edge;

endmodule

