module transition_detector (
    input clk,
    input reset,
    input [31:0] in,
    output [31:0] out
);

    reg [31:0] prev_in;
    reg [31:0] transition_detected;

    parameter IDLE = 2'b00;
    parameter DETECT_TRANSITION = 2'b01;

    reg [1:0] state;

    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            prev_in <= 0;
            transition_detected <= 0;
        end
        else begin
            case (state)
                IDLE: begin
                    prev_in <= in;
                    state <= DETECT_TRANSITION;
                end
                DETECT_TRANSITION: begin
                    if (in != prev_in) begin
                        transition_detected <= transition_detected | (prev_in ^ in);
                    end
                    prev_in <= in;
                    state <= DETECT_TRANSITION;
                end
                default: begin
                    state <= IDLE;
                    prev_in <= 0;
                    transition_detected <= 0;
                end
            endcase
        end
    end

    assign out = transition_detected;

endmodule

