module spi_ctrl(
    input clk,
    input rst_n,
    input miso,
    input mode_select_CPHA,
    input mode_select_CPOL,
    input spi_tx_en,
    input spi_rx_en,
    output sck,
    output mosi,
    output cs_n,
    output receive_status
);

wire spi_over;
wire receive_status;

reg spi_clk;
reg cs_n;
reg [7:0] clk_count;
reg [7:0] rst_count;
reg rst_flag;

// Calculate the SPI clock frequency
parameter SPI_CLK_FREQ = clk / 100 / 3;

// Counter for the number of clock cycles
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        clk_count <= 8'h0;
        spi_clk <= 1'b0;
    end else begin
        if (clk_count < SPI_CLK_FREQ) begin
            clk_count <= clk_count + 1'b1;
        end else begin
            clk_count <= 8'h0;
            spi_clk <= ~spi_clk;
        end
    end
end

// Chip select signal
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cs_n <= 1'b1;
    end else begin
        if (spi_over || ((spi_tx_en == 1'b0) && (spi_rx_en == 1'b0))) begin
            cs_n <= 1'b1;
        end else begin
            cs_n <= 1'b0;
        end
    end
end

// Reset flag
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        rst_flag <= 1'b0;
        rst_count <= 'h0;
    end else begin
        if (rst_count < 8'd20) begin
            rst_count <= rst_count + 1'b1;
        end else begin
            rst_flag <= 1'b1;
        end
    end
end

// SPI master module
spi_master spi_master_instance(
    .clk(spi_clk),
    .rst_n(rst_flag),
    .spi_miso(miso),
    .spi_mosi(mosi),
    .spi_clk(sck),
    .spi_tx_en(spi_tx_en),
    .spi_over(spi_over),
    .spi_rx_en(spi_rx_en),
    .mode_select_CPHA(mode_select_CPHA),
    .mode_select_CPOL(mode_select_CPOL),
    .receive_status(receive_status)
);

endmodule

module pll1 (
    inclk0,
    c0,
    c1,
    locked);

    input       inclk0;
    output      c0;
    output      c1;
    output      locked;

    wire        up;
    wire        down;
    wire        phase_error;
    wire        vco_out;
    reg         locked_reg;
    reg         up_reg;
    reg         down_reg;
    reg         phase_error_reg;
    reg         ictrl_reg;
    reg         ctrl_reg;

    // Phase detector (XOR gate)
    assign phase_error = inclk0 ^ vco_out;

    // Charge pump
    always @ (posedge inclk0) begin
        if (phase_error && !locked_reg) begin
            if (phase_error_reg) begin
                ictrl_reg <= ictrl_reg + 1;
            end else begin
                ictrl_reg <= ictrl_reg - 1;
            end
        end else begin
            ictrl_reg <= 0;
        end
        phase_error_reg <= phase_error;
    end

    // Loop filter (RC filter)
    parameter RC = 1; // Time constant in microseconds
    reg [15:0] filt_reg;
    always @ (posedge inclk0) begin
        filt_reg <= filt_reg + ictrl_reg - (filt_reg >> RC);
    end

    // Voltage-controlled oscillator (VCO)
    parameter F_MIN = 80; // Minimum frequency in MHz
    parameter F_MAX = 320; // Maximum frequency in MHz
    parameter K_VCO = 100; // VCO gain in MHz/V
    reg [15:0] n_reg;
    always @ (posedge inclk0) begin
        n_reg <= n_reg + ((filt_reg * K_VCO) >> 16);
    end
    assign vco_out = n_reg[15];

    // Frequency divider
    reg [1:0] div_reg;
    always @ (posedge vco_out) begin
        div_reg <= div_reg + 1;
    end

    // Output signals
    assign c0 = div_reg[0] ? 1'b0 : 1'b1;
    assign c1 = div_reg[1] ? 1'b0 : 1'b1;
    assign locked = locked_reg;

    // Control logic
    always @ (posedge inclk0) begin
        if (phase_error && !locked_reg) begin
            if (up_reg) begin
                ctrl_reg <= ctrl_reg + 1;
            end else begin
                ctrl_reg <= ctrl_reg - 1;
            end
        end else begin
            ctrl_reg <= 0;
        end
        up_reg <= (ctrl_reg >= 64);
        down_reg <= (ctrl_reg <= -64);
        locked_reg <= (ctrl_reg >= -64 && ctrl_reg <= 64);
    end

    // Debug signals
    // assign debug1 = phase_error;
    // assign debug2 = ictrl_reg;
    // assign debug3 = filt_reg;
    // assign debug4 = n_reg;
    // assign debug5 = div_reg;
    // assign debug6 = ctrl_reg;

endmodule

module delay_block (
  input clk,
  input in,
  input [7:0] delay,
  output reg out
);

reg [7:0] counter;

always @(posedge clk) begin
  if (in != counter[7:0]) begin
    counter <= 0;
    out <= 0;
  end
  else if (counter == delay) begin
    out <= in;
  end
  counter <= counter + 1;
end

endmodule

module alu(
    output zero,
    output [31:0] aluRes,
    input [31:0] input1,
    input [31:0] input2,
    input [3:0] aluCtr
    );
    reg zero;
    reg [31:0] aluRes;

    always @ (input1 or input2 or aluCtr)
    begin
        case (aluCtr)
            4'b0010: // Addition
                begin
                    aluRes = input1 + input2;
                    zero = (aluRes == 0) ? 1 : 0;
                end
            4'b0110: // Subtraction
                begin
                    aluRes = input1 - input2;
                    zero = (aluRes == 0) ? 1 : 0;
                end
            4'b0000: // Bitwise AND
                begin
                    aluRes = input1 & input2;
                    zero = (aluRes == 0) ? 1 : 0;
                end
            4'b0001: // Bitwise OR
                begin
                    aluRes = input1 | input2;
                    zero = (aluRes == 0) ? 1 : 0;
                end
            4'b0111: // Set Less Than
                begin
                    aluRes = (input1 < input2) ? 1 : 0;
                    zero = (aluRes == 0) ? 1 : 0;
                end
            4'b1100: // Bitwise NOR
                begin
                    aluRes = ~(input1 | input2);
                    zero = (aluRes == 0) ? 1 : 0;
                end
            default:
                begin
                    aluRes = 0;
                    zero = 1;
                end
        endcase
    end
endmodule

module floating_point_adder (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] c
);

    // Define constants for IEEE 754 single-precision format
    parameter EXPONENT_WIDTH = 8;
    parameter MANTISSA_WIDTH = 23;
    parameter BIAS = 127;
    parameter EXPONENT_MASK = {EXPONENT_WIDTH{1'b1}};
    parameter MANTISSA_MASK = {MANTISSA_WIDTH{1'b1}};
    parameter SIGN_MASK = 32'h80000000;

    // Define variables for input and output
    reg [31:0] a_sign, b_sign, a_exponent, b_exponent, a_mantissa, b_mantissa;
    reg [31:0] c_sign, c_exponent, c_mantissa;
    reg [1:0] rounding_bits;
    reg overflow, underflow, invalid;

    // Extract sign, exponent, and mantissa from input a
    assign a_sign = a[31];
    assign a_exponent = a[30:23];
    assign a_mantissa = a[22:0];

    // Extract sign, exponent, and mantissa from input b
    assign b_sign = b[31];
    assign b_exponent = b[30:23];
    assign b_mantissa = b[22:0];

    // Initialize output to zero
    always @(posedge clk) begin
        if (rst) begin
            c <= 32'h00000000;
        end
    end

    // Check for special cases
    always @(posedge clk) begin
        if (rst) begin
            overflow <= 0;
            underflow <= 0;
            invalid <= 0;
        end else begin
            if (a_exponent == EXPONENT_MASK && a_mantissa != 0) begin
                invalid <= 1;
            end else if (b_exponent == EXPONENT_MASK && b_mantissa != 0) begin
                invalid <= 1;
            end else if (a_exponent == EXPONENT_MASK && b_exponent == EXPONENT_MASK) begin
                if (a_sign != b_sign) begin
                    invalid <= 1;
                end else begin
                    overflow <= 1;
                end
            end else if (a_exponent == EXPONENT_MASK || b_exponent == EXPONENT_MASK) begin
                c_sign <= a_sign;
                c_exponent <= EXPONENT_MASK;
                c_mantissa <= 0;
            end else if (a_exponent > b_exponent + MANTISSA_WIDTH) begin
                c_sign <= a_sign;
                c_exponent <= a_exponent;
                c_mantissa <= a_mantissa;
                overflow <= 1;
            end else if (b_exponent > a_exponent + MANTISSA_WIDTH) begin
                c_sign <= b_sign;
                c_exponent <= b_exponent;
                c_mantissa <= b_mantissa;
                overflow <= 1;
            end else begin
                c_sign <= a_sign;
                c_exponent <= a_exponent;
                c_mantissa <= a_mantissa;
            end
        end
    end

    // Perform addition
    always @(posedge clk) begin
        if (rst) begin
            rounding_bits <= 2'b00;
        end else begin
            if (a_exponent == EXPONENT_MASK || b_exponent == EXPONENT_MASK) begin
                // Do nothing, special case already handled
            end else if (a_exponent > b_exponent) begin
                // Shift b mantissa right to align exponents
                b_mantissa = {1'b1, b_mantissa} >> (a_exponent - b_exponent);
            end else if (b_exponent > a_exponent) begin
                // Shift a mantissa right to align exponents
                a_mantissa = {1'b1, a_mantissa} >> (b_exponent - a_exponent);
                a_exponent = b_exponent;
            end

            // Add mantissas
            {rounding_bits, c_mantissa} = a_mantissa + b_mantissa;

            // Check for overflow
            if (c_mantissa[MANTISSA_WIDTH+1]) begin
                c_mantissa = c_mantissa >> 1;
                c_exponent = c_exponent + 1;
                if (c_exponent == EXPONENT_MASK) begin
                    overflow <= 1;
                    c_exponent = c_exponent - 1;
                end
            end

            // Check for underflow
            if (c_exponent < 1) begin
                underflow <= 1;
                c_mantissa = 0;
                c_exponent = 0;
            end

            // Normalize result
            while (c_mantissa[MANTISSA_WIDTH] == 0 && c_exponent > 0) begin
                c_mantissa = {c_mantissa[MANTISSA_WIDTH-1:0], 1'b0};
                c_exponent = c_exponent - 1;
            end
        end
    end

    // Handle special cases
    always @(posedge clk) begin
        if (rst) begin
            c_sign <= 0;
        end else begin
            if (invalid) begin
                c_sign <= 0;
                c_exponent <= EXPONENT_MASK;
                c_mantissa <= 32'h400000;
            end else if (overflow) begin
                c_sign <= a_sign;
                c_exponent <= EXPONENT_MASK;
                c_mantissa <= 0;
            end else if (underflow) begin
                c_sign <= a_sign;
                c_exponent <= 0;
                c_mantissa <= 0;
            end else begin
                c_sign <= a_sign;
                c_exponent <= c_exponent + BIAS;
                c_mantissa <= c_mantissa[MANTISSA_WIDTH-1:MANTISSA_WIDTH-1-22];
            end
        end
    end

    // Add sign bit to output
    always @(posedge clk) begin
        if (rst) begin
            c <= 32'h00000000;
        end else begin
            c <= {c_sign, c_exponent, c_mantissa};
        end
    end

endmodule

module shift_reg_alu (
    input clk,
    input reset,
    input [7:0] in,
    output reg [8:0] out,
    output reg error
);

    // Shift register
    reg [7:0] shift_reg;
    always @(posedge clk, negedge reset) begin
        if (reset == 0) begin
            shift_reg <= 8'b0;
        end else begin
            shift_reg <= {shift_reg[6:0], in[7]};
        end
    end

    // Arithmetic logic unit
    parameter [7:0] constant_value = 8'hAA;
    reg [7:0] alu_out;
    always @(*) begin
        alu_out = shift_reg ^ constant_value;
    end

    // Dual-edge triggered flip-flop
    reg [8:0] dff_out;
    wire parity;
    parity_generator parity_gen (
        .in(alu_out),
        .out(parity)
    );
    always @(posedge clk, negedge reset) begin
        if (reset == 0) begin
            dff_out <= 9'b0;
        end else begin
            dff_out <= {parity, alu_out};
        end
    end

    // Error signal
    assign error = ~(dff_out[8] & dff_out[0]);

    // Output
    assign out = dff_out;

endmodule

module parity_generator (
    input [7:0] in,
    output reg parity
);

    always @(*) begin
        parity = ^in;
    end

endmodule

