    input L, // Load input for the selected shift register
    output reg [19:0] out // Output of the bitwise OR operation
);

wire [3:0] Q0;
wire [15:0] Q1;

shift_register #(.N(4)) sr0 (
    .clk(clk),
    .reset(reset),
    .D(D0),
    .L(L & ~select),
    .Q(Q0)
);

shift_register #(.N(16)) sr1 (
    .clk(clk),
    .reset(reset),
    .D(D1),
    .L(L & select),
    .Q(Q1)
);

assign out = {Q1, Q0} | 20'h0;

endmodule

