module digital_lock(
    input clk,
    input reset,      // Synchronous active-high reset
    input [3:0] code,
    output unlock
);

    // Define the state machine states
    parameter IDLE = 2'b00;
    parameter COUNTING = 2'b01;
    parameter COMPARING = 2'b10;
    parameter UNLOCKED = 2'b11;

    // Define the state machine inputs
    reg [1:0] state;
    reg [3:0] count;
    reg [3:0] compare;
    reg sub;
    wire [3:0] sum;

    // Instantiate the adder modules
    ripple_adder adder1(.a(count), .b(4'b1), .cin(1'b0), .s(sum[0]), .cout(carry1));
    ripple_adder adder2(.a(sum), .b(compare), .cin(sub), .s(sum), .cout(carry2));

    // Instantiate the comparator module
    comparator cmp(.a(count), .b(compare), .sub(sub));

    // Define the unlock output
    assign unlock = (state == UNLOCKED);

    // Define the state machine
    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            count <= 4'b0;
            compare <= code;
            sub <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (count == 4'b0) begin
                        state <= COUNTING;
                    end else begin
                        count <= count - 1;
                    end
                end
                COUNTING: begin
                    if (count == 4'b1001) begin
                        state <= COMPARING;
                    end else begin
                        count <= count + 1;
                    end
                end
                COMPARING: begin
                    sub <= 1'b1;
                    if (cmp.eq) begin
                        state <= UNLOCKED;
                    end else begin
                        state <= COUNTING;
                    end
                end
                UNLOCKED: begin
                    state <= IDLE;
                    count <= 4'b0;
                    compare <= code;
                    sub <= 1'b0;
                end
            endcase
        end
    end

endmodule

// Define the ripple carry adder module
module ripple_adder(
    input [3:0] a,
    input [3:0] b,
    input cin,
    output [3:0] s,
    output cout
);

    wire [3:0] sum;
    wire [3:0] carry;

    assign sum = a ^ b ^ cin;
    assign carry = (a & b) | (a & cin) | (b & cin);

    assign s = sum;
    assign cout = carry;

endmodule

// Define the comparator module
module comparator(
    input [3:0] a,
    input [3:0] b,
    input sub,
    output eq
);

    wire [3:0] diff;

    assign diff = (sub) ? (a - b) : (a + b);

    assign eq = (diff == 4'b0);

endmodule

module lookup_9bit(
    clk,
    reset,
    set_valid,
    set_data,
    read_valid,
    read_addr,
    data_out_valid,
    data_out,

    key_valid,
    key,
    bv,
    stage_enable
);

    input clk;
    input reset;
    input set_valid;
    input [44:0] set_data;
    input read_valid;
    input [8:0] read_addr;
    input key_valid;
    input [8:0] key;
    output [35:0] bv;
    output data_out_valid;
    output [35:0] data_out;
    output stage_enable;

    reg data_out_valid;
    reg [35:0] data_out;
    wire [35:0] bv;
    reg stage_enable;

    reg [8:0] address_b;
    reg rden_b;
    reg wren_b;
    reg [35:0] data_b;
    wire [35:0] q_b;

    reg [3:0] set_state;
    parameter idle = 4'd0,
              read_wait_1 = 4'd1,
              read_wait_2 = 4'd2,
              read_ram = 4'd3;

    always @ (posedge clk or negedge reset) begin
        if (!reset) begin
            stage_enable <= 1'b0;
        end else begin
            if (key_valid == 1'b1) begin
                stage_enable <= 1'b1;
            end else begin
                stage_enable <= 1'b0;
            end
        end
    end

    always @ (posedge clk or negedge reset) begin
        if (!reset) begin
            set_state <= idle;
            data_out <= 36'b0;
            data_out_valid <= 1'b0;
            address_b <= 9'b0;
            rden_b <= 1'b0;
            data_b <= 36'b0;
        end else begin
            case (set_state)
                idle: begin
                    data_out_valid <= 1'b0;
                    if (set_valid == 1'b1) begin
                        set_state <= idle;
                        wren_b <= 1'b1;
                        address_b <= set_data[44:36];
                        data_b <= set_data[35:0];
                    end else if (read_valid == 1'b1) begin
                        set_state <= read_wait_1;
                        wren_b <= 1'b0;
                        rden_b <= 1'b1;
                        address_b <= read_addr;
                    end else begin
                        wren_b <= 1'b0;
                    end
                end
                read_wait_1: begin
                    rden_b <= 1'b0;
                    set_state <= read_wait_2;
                end
                read_wait_2: begin
                    set_state <= read_ram;
                end
                read_ram: begin
                    data_out_valid <= 1'b1;
                    data_out <= q_b;
                    set_state <= idle;
                end
                default: begin
                    set_state <= idle;
                end
            endcase
        end
    end

    ram_36_512 ram_1(
        .address_a(key),
        .address_b(address_b),
        .clock(clk),
        .data_a(36'b0),
        .data_b(data_b),
        .rden_a(key_valid),
        .rden_b(rden_b),
        .wren_a(1'b0),
        .wren_b(wren_b),
        .q_a(bv),
        .q_b(q_b)
    );

endmodule

module ram_36_512(
    address_a,
    address_b,
    clock,
    data_a,
    data_b,
    rden_a,
    rden_b,
    wren_a,
    wren_b,
    q_a,
    q_b
);

    parameter WIDTH = 36;
