module traffic_control(
  input clk,
  input reset,
  input [3:0] ns_sensor,
  input [3:0] ew_sensor,
  output reg ns_green,
  output reg ew_green
);

  // Define state variables
  reg [3:0] ns_count;
  reg [3:0] ew_count;
  reg [1:0] state;

  // Define constants
  localparam NORTH_SOUTH = 2'b00;
  localparam EAST_WEST = 2'b01;
  localparam CHANGE_NS = 4'd10;
  localparam CHANGE_EW = 4'd20;

  // Initialize state variables
  initial begin
    ns_count = 0;
    ew_count = 0;
    state = NORTH_SOUTH;
    ns_green = 1;
    ew_green = 0;
  end

  // State machine to control traffic lights
  always @(posedge clk) begin
    if (reset) begin
      ns_count <= 0;
      ew_count <= 0;
      state <= NORTH_SOUTH;
      ns_green <= 1;
      ew_green <= 0;
    end else begin
      case (state)
        NORTH_SOUTH: begin
          ns_count <= ns_count + 1;
          if (ns_sensor != 0) begin
            state <= EAST_WEST;
            ew_count <= 0;
            ns_green <= 0;
            ew_green <= 1;
          end else if (ns_count >= CHANGE_NS) begin
            state <= EAST_WEST;
            ew_count <= 0;
            ns_count <= 0;
            ns_green <= 0;
            ew_green <= 1;
          end
        end
        EAST_WEST: begin
          ew_count <= ew_count + 1;
          if (ew_sensor != 0) begin
            state <= NORTH_SOUTH;
            ns_count <= 0;
            ew_green <= 0;
            ns_green <= 1;
          end else if (ew_count >= CHANGE_EW) begin
            state <= NORTH_SOUTH;
            ns_count <= 0;
            ew_count <= 0;
            ew_green <= 0;
            ns_green <= 1;
          end
        end
      endcase
    end
  end
endmodule

