module SSCG (
  input clk_in,
  input rst,
  input enable,
  input spread,
  output reg clk_out
);

parameter f_nom = 50_000_000; // nominal frequency
parameter f_spread = 100_000; // frequency spread range
parameter mod_depth = 50; // modulation depth

reg [31:0] phase_accumulator;
reg [31:0] phase_increment;
reg [31:0] sine_table [0:255];
reg [7:0] index;
reg [31:0] modulator;
reg [31:0] modulated_clk;

always @ (posedge clk_in or posedge rst) begin
  if (rst) begin
    phase_accumulator <= 0;
    clk_out <= 0;
  end else if (enable) begin
    phase_increment <= ((f_nom + (f_spread/2)) * 2**32) / $realtime;
    index <= phase_accumulator[31:24];
    modulator <= (mod_depth * spread) / 100;
    modulated_clk <= clk_in + ((sine_table[index] * modulator) / 100);
    clk_out <= modulated_clk[31];
    phase_accumulator <= phase_accumulator + phase_increment;
  end else begin
    clk_out <= 0;
  end
end

// Generate sine table
integer i;
initial begin
  for (i = 0; i < 256; i = i + 1) begin
    sine_table[i] = $sin(2 * $pi * i / 256);
  end
end

endmodule

module top_module (
    input clk,
    input [7:0] d,
    output out
);

reg [7:0] q;
wire not_q;
wire [7:0] and_input;
wire and_output;

// Implement 8 D flip-flops
always @(posedge clk) begin
    q[0] <= d;
    q[1] <= q[0];
    q[2] <= q[1];
    q[3] <= q[2];
    q[4] <= q[3];
    q[5] <= q[4];
    q[6] <= q[5];
    q[7] <= q[6];
end

// Implement NOT gate
assign not_q = ~q[7];

// Implement AND gate
assign and_input = {not_q, q[7]};
assign and_output = and(and_input);

// Output
assign out = and_output;

endmodule

module prefix_propagator(Double, Negate, Single, Y, PP, Sign);
  input Double;
  input Negate;
  input Single;
  input [7:0] Y;
  output [8:0] PP;
  output Sign;

  wire [7:0] Y_doubled;
  wire [7:0] Y_negated;
  wire [7:0] Y_processed;
  wire [8:0] PP_processed;
  wire [8:0] PP_reduced;

  // Double Y if Double is set
  assign Y_doubled = Double ? Y << 1 : Y;

  // Negate Y if Negate is set
  assign Y_negated = Negate ? ~Y + 1 : Y;

  // Select the input to be processed based on Single
  assign Y_processed = Single ? {8'b0, Y[7]} : Y_negated;

  // Generate the prefix propagator
  wordlib8__PPGen_1bit PPGen_1b_0(.Double(Double), .Negate(Negate), 
      .Single(Single), .Yi(Y_processed[7]), .Yi_m1(1'b0), .PPi(PP_processed[0]));
  wordlib8__PPGen_1bit PPGen_1b_1(.Double(Double), .Negate(Negate), 
      .Single(Single), .Yi(Y_processed[6]), .Yi_m1(PP_processed[0]), .PPi(PP_processed[1]));
  wordlib8__PPGen_1bit PPGen_1b_2(.Double(Double), .Negate(Negate), 
      .Single(Single), .Yi(Y_processed[5]), .Yi_m1(PP_processed[1]), .PPi(PP_processed[2]));
  wordlib8__PPGen_1bit PPGen_1b_3(.Double(Double), .Negate(Negate), 
      .Single(Single), .Yi(Y_processed[4]), .Yi_m1(PP_processed[2]), .PPi(PP_processed[3]));
  wordlib8__PPGen_1bit PPGen_1b_4(.Double(Double), .Negate(Negate), 
      .Single(Single), .Yi(Y_processed[3]), .Yi_m1(PP_processed[3]), .PPi(PP_processed[4]));
  wordlib8__PPGen_1bit PPGen_1b_5(.Double(Double), .Negate(Negate), 
      .Single(Single), .Yi(Y_processed[2]), .Yi_m1(PP_processed[4]), .PPi(PP_processed[5]));
  wordlib8__PPGen_1bit PPGen_1b_6(.Double(Double), .Negate(Negate), 
      .Single(Single), .Yi(Y_processed[1]), .Yi_m1(PP_processed[5]), .PPi(PP_processed[6]));
  wordlib8__PPGen_1bit PPGen_1b_7(.Double(Double), .Negate(Negate), 
      .Single(Single), .Yi(Y_processed[0]), .Yi_m1(PP_processed[6]), .PPi(PP_processed[7]));

  // Reduce the prefix propagator
  wordlib8__NAND8_reducer NAND8_re_0(.inY(PP_processed[0:7]), .reduced_AND(PP_reduced[0]));
  wordlib8__NAND8_reducer NAND8_re_1(.inY(PP_processed[1:7]), .reduced_AND(PP_reduced[1]));
  wordlib8__NAND8_reducer NAND8_re_2(.inY(PP_processed[2:7]), .reduced_AND(PP_reduced[2]));
  wordlib8__NAND8_reducer NAND8_re_3(.inY(PP_processed[3:7]), .reduced_AND(PP_reduced[3]));
  wordlib8__NAND8_reducer NAND8_re_4(.inY(PP_processed[4:7]), .reduced_AND(PP_reduced[4]));
  wordlib8__NAND8_reducer NAND8_re_5(.inY(PP_processed[5:7]), .reduced_AND(PP_reduced[5]));
  wordlib8__NAND8_reducer NAND8_re_6(.inY(PP_processed[6:7]), .reduced_AND(PP_reduced[6]));
  wordlib8__NAND8_reducer NAND8_re_7(.inY(PP_processed[7:7]), .reduced_AND(PP_reduced[7]));

  // Perform the full addition
  wire [8:0] PP_full_adder;
  wordlib8__HalfAdder HalfAdde_0(.A(PP_reduced[0]), .Cin(1'b0), .Cout(PP_full_adder[1]), 
      .Sum(PP_full_adder[0]));
  wordlib8__HalfAdder HalfAdde_1(.A(PP_reduced[1]), .Cin(PP_full_adder[1]), .Cout(PP_full_adder[2]), 
      .Sum(PP_full_adder[1]));
  wordlib8__HalfAdder HalfAdde_2(.A(PP_reduced[2]), .Cin(PP_full_adder[2]), .Cout(PP_full_adder[3]), 
      .Sum(PP_full_adder[2]));
  wordlib8__HalfAdder HalfAdde_3(.A(PP_reduced[3]), .Cin(PP_full_adder[3]), .Cout(PP_full_adder[4]), 
      .Sum(PP_full_adder[3]));
  wordlib8__HalfAdder HalfAdde_4(.A(PP_reduced[4]), .Cin(PP_full_adder[4]), .Cout(PP_full_adder[5]), 
      .Sum(PP_full_adder[4]));
  wordlib8__HalfAdder HalfAdde_5(.A(PP_reduced[5]), .Cin(PP_full_adder[5]), .Cout(PP_full_adder[6]), 
      .Sum(PP_full_adder[5]));
  wordlib8__HalfAdder HalfAdde_6(.A(PP_reduced[6]), .Cin(PP_full_adder[6]), .Cout(PP_full_adder[7]), 
      .Sum(PP_full_adder[6]));
  wordlib8__HalfAdder HalfAdde_7(.A(PP_reduced[7]), .Cin(PP_full_adder[7]), .Cout(Sign), 
      .Sum(PP_full_adder[7]));
  wordlib8__HalfAdder HalfAdde_8(.A(0), .Cin(Double), .Cout(PP_full_adder[8]), 
      .Sum(PP_full_adder[8]));

  // Assign the final output
  assign PP = {PP_full_adder[8], PP_full_adder[7:0]};

endmodule

module ripple_shift_and (
    input clk,
    input [15:0] A,
    input [15:0] B,
    input [3:0] data_in,
    input load,
    input shift_enable,
    output reg [15:0] sum,
    output overflow,
    output reg [3:0] data_out
);

    // 16-bit ripple carry adder
    wire [15:0] adder_out;
    wire carry_out;
    ripple_adder adder(.A(A), .B(B), .sum(adder_out), .carry_out(carry_out));

    // 4-bit shift register with parallel load and shift enable
    reg [3:0] shift_reg;
    always @(posedge clk) begin
        if (load) begin
            shift_reg <= data_in;
        end else if (shift_enable) begin
            shift_reg <= {shift_reg[2:0], 1'b0};
        end
    end
    assign data_out = shift_reg;

    // Bitwise AND of LSBs
    wire and_out;
    assign and_out = (sum[0] & data_out[0]);

    // 16-bit output representing the sum of operands A and B
    always @(posedge clk) begin
        if (carry_out) begin
            overflow <= 1'b1;
        end else begin
            overflow <= 1'b0;
        end
        sum <= adder_out;
    end

endmodule

module ripple_adder (
    input [15:0] A,
    input [15:0] B,
    output reg [15:0] sum,
    output carry_out
);

    reg [15:0] temp_sum;
    reg carry;

    always @(A or B or carry) begin
        temp_sum = A + B + carry;
        carry = (temp_sum[16] == 1'b1);
        sum = temp_sum[15:0];
    end

    assign carry_out = carry;

endmodule

module top_module ( 
  input clk, 
  input areset, // async active-high reset to zero 
  input load, 
  input ena, 
  input [3:0] data, // 4-bit input for the shift register 
  input [7:0] instruction, // 8-bit instruction set for the pipeline 
  input [2:0] stage, 
  input [4:0] rs1, 
  input [4:0] rs2, 
  input [4:0] rd, 
  input [31:0] data1, 
  input [31:0] data2, 
  input select, // Select input to choose between shift register and pipeline 
  output reg [3:0] shift_q, // 4-bit output from the shift register 
  output reg [31:0] func_q // 32-bit output from the functional module 
);

// Shift Register Module
reg [3:0] shift_reg;
always @(posedge clk, negedge areset) begin
  if (!areset) begin
    shift_reg <= 4'b0;
  end else begin
    if (load) begin
      shift_reg <= data;
    end else if (ena) begin
      shift_reg <= {shift_reg[2:0], shift_reg[3]};
    end
  end
end
assign shift_q = shift_reg;

// Pipeline Module
reg [7:0] instr_reg;
reg [4:0] rs1_reg, rs2_reg, rd_reg;
reg [31:0] data1_reg, data2_reg;
reg [31:0] alu_out_reg;
always @(posedge clk) begin
  if (stage == 0) begin // Instruction Fetch
    instr_reg <= instruction;
  end else if (stage == 1) begin // Instruction Decode
    rs1_reg <= rs1;
    rs2_reg <= rs2;
    rd_reg <= rd;
  end else if (stage == 2) begin // Execution Stage
    data1_reg <= data1;
    data2_reg <= data2;
    case (instr_reg[7:5])
      3'b000: alu_out_reg <= data1_reg + data2_reg; // ADD
      3'b001: alu_out_reg <= data1_reg - data2_reg; // SUB
      3'b010: alu_out_reg <= data1_reg & data2_reg; // AND
      3'b011: alu_out_reg <= ~(data1_reg & data2_reg); // NAND
      default: alu_out_reg <= 32'b0;
    endcase
  end
end

// Functional Module
reg [31:0] and_out;
always @(*) begin
  and_out = shift_reg & alu_out_reg;
end
assign func_q = (select) ? alu_out_reg : and_out;

endmodule

module sky130_fd_sc_ls__clkdlyinv3sd3 (
    input A,
    input VPWR,
    input VGND,
    input VPB,
    input VNB,
    output Y
);

    wire inv1_out;
    wire inv2_out;
    wire inv3_out;
    wire inv4_out;

    assign inv1_out = ~VGND;
    assign inv2_out = ~VNB;
    assign inv3_out = ~VPB;
    assign inv4_out = ~VPWR;

    assign Y = (A & inv1_out & inv2_out & inv3_out & inv4_out);

endmodule

module special_and_gate (
    input A,
    input B,
    output X
);

    // Module supplies
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    // Local signals
    wire A_N;
    wire not0_out;
    wire and0_out_X;

    // Invert input A
    not not0 (not0_out, A);
    assign A_N = ~A;

    // AND gate with special requirement
    and and0 (and0_out_X, not0_out, B);
    assign X = (A == 1'b1) ? and0_out_X : ~and0_out_X;

endmodule

module UART(
    input Clk,
    input Reset,
    input Rx,
    output Tx,
    output reg [15:0] LEDs
);

// Receiver module
reg [7:0] userData[0:99];
reg [7:0] sizeOfData;
reg [7:0] charCount;
reg doneReceiving;

wire Rx_Ready;
reg Rx_Ack;
wire [7:0] Rx_Data;

always @(posedge Clk) begin
    if (Reset) begin
        Rx_Ack <= 0;
        charCount <= 0;
        doneReceiving <= 0;
    end
    else begin
        if (Rx_Ready && !doneReceiving) begin
            if (charCount == 0) begin
                sizeOfData <= Rx_Data;
            end
            else begin
                userData[charCount-1] <= Rx_Data;
            end
            charCount <= charCount + 1;
            Rx_Ack <= 1;
            if (charCount == sizeOfData) begin
                doneReceiving <= 1;
            end
        end
        else if (~Rx_Ready) begin
            Rx_Ack <= 0;
        end
    end
end

// Transmitter module
reg [7:0] txData;
reg [7:0] txDataIndex;
reg txDataIndexLocked;
reg txSend;
wire txBusy;

always @(posedge Clk) begin
    if (Reset) begin
        txData <= 0;
        txDataIndex <= 0;
        txDataIndexLocked <= 1;
        txSend <= 0;
    end
    else begin
        if (doneReceiving && !txBusy && txDataIndex < sizeOfData) begin
            txData <= userData[txDataIndex];
            txDataIndexLocked <= 0;
            txSend <= 1;
        end
        else if (doneReceiving && txDataIndexLocked == 0) begin
            txDataIndex <= txDataIndex + 1;
            txDataIndexLocked <= 1;
            txSend <= 0;
        end
    end
end

UART_Sender #(14, 14'd9999) sender(
    Clk,
    Reset,
    txData,
    txSend,
    txBusy,
    Tx
);

UART_Receiver #(14, 14'd9999) receiver(
    Clk,
    Reset,
    Rx_Data,
    Rx_Ready,
    Rx_Ack,
    Rx
);

always @(*) begin
    LEDs <= userData[2];
end

endmodule

