module FlipFlop (
  input clk,
  input rst,
  input d,
  input j,
  input k,
  input t,
  input s,
  input r,
  output reg q,
  output reg q_n
);

parameter type = "D"; // type of flip-flop (D, JK, T, or SR) 

always @(posedge clk or negedge rst) begin
  if (~rst) begin
    q <= 1'b0;
    q_n <= 1'b1;
  end else begin
    case (type)
      "D": begin
        q <= d;
        q_n <= ~d;
      end
      "JK": begin
        if (j && ~k) begin
          q <= 1'b1;
          q_n <= 1'b0;
        end else if (~j && k) begin
          q <= 1'b0;
          q_n <= 1'b1;
        end else if (j && k) begin
          q <= ~q;
          q_n <= q;
        end
      end
      "T": begin
        if (t) begin
          q <= ~q;
          q_n <= q;
        end
      end
      "SR": begin
        if (s && ~r) begin
          q <= 1'b1;
          q_n <= 1'b0;
        end else if (~s && r) begin
          q <= 1'b0;
          q_n <= 1'b1;
        end else if (s && r) begin
          q <= 1'bx;
          q_n <= 1'bx;
        end
      end
    endcase
  end
end

endmodule

