module Fletcher (
  input [n-1:0] in,
  output reg [15:0] checksum
);

parameter n = 32; // number of input signals
parameter k = 8; // size of each block (in bits)

reg [k-1:0] block [0:n/k-1]; // divide input data into blocks of size k
reg [15:0] sum1 = 0; // initialize sum1 to 0
reg [15:0] sum2 = 0; // initialize sum2 to 0

integer i, j;

always @(*) begin
  // calculate checksum for each block
  for (i = 0; i < n/k; i = i + 1) begin
    sum1 = sum1 + block[i];
    sum2 = sum2 + sum1;
  end

  // add checksum values to generate final checksum value
  checksum = (sum2 << 8) | sum1;
end

// assign input signals to blocks
always @(*) begin
  for (i = 0; i < n/k; i = i + 1) begin
    block[i] = {in[(i+1)*k-1:i*k]};
  end
end

endmodule

