module dht11_driver(
  input clk,
  input rst_n,
  input start,
  input data_io,
  output reg [7:0] humidity,
  output reg [7:0] temperature,
  output reg valid
);

  // State machine states
  parameter IDLE = 2'b00;
  parameter START = 2'b01;
  parameter DATA = 2'b10;
  parameter ERROR = 2'b11;

  // State machine signals
  reg [1:0] state;
  reg [1:0] bit_count;
  reg [7:0] data_buffer;
  reg [7:0] checksum;
  reg [7:0] last_humidity;
  reg [7:0] last_temperature;
  reg [7:0] current_humidity;
  reg [7:0] current_temperature;
  reg [7:0] bit_timer;
  reg [7:0] pulse_timer;
  reg [7:0] error_count;

  // Initialize state machine
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state <= IDLE;
      bit_count <= 0;
      data_buffer <= 0;
      checksum <= 0;
      last_humidity <= 0;
      last_temperature <= 0;
      current_humidity <= 0;
      current_temperature <= 0;
      bit_timer <= 0;
      pulse_timer <= 0;
      error_count <= 0;
      valid <= 0;
    end else begin
      case(state)
        IDLE: begin
          if (start) begin
            state <= START;
            bit_count <= 0;
            data_buffer <= 0;
            checksum <= 0;
            bit_timer <= 0;
            pulse_timer <= 0;
            error_count <= 0;
            valid <= 0;
          end
        end
        START: begin
          if (bit_timer == 80) begin
            bit_timer <= 0;
            pulse_timer <= 0;
            state <= DATA;
          end else if (pulse_timer == 30) begin
            bit_timer <= bit_timer + 1;
            pulse_timer <= 0;
            if (data_io) begin
              state <= ERROR;
              error_count <= error_count + 1;
            end
          end else begin
            pulse_timer <= pulse_timer + 1;
          end
        end
        DATA: begin
          if (bit_count == 40) begin
            bit_count <= 0;
            if (checksum == data_buffer[7:0]) begin
              last_humidity <= current_humidity;
              last_temperature <= current_temperature;
              current_humidity <= data_buffer[23:8];
              current_temperature <= data_buffer[39:24];
              valid <= 1;
            end else begin
              state <= ERROR;
              error_count <= error_count + 1;
            end
          end else if (pulse_timer == 50) begin
            bit_timer <= bit_timer + 1;
            pulse_timer <= 0;
            if (data_io) begin
              data_buffer[39-bit_count] <= 1;
              bit_count <= bit_count + 1;
              checksum <= checksum + data_buffer[39-bit_count];
            end else begin
              data_buffer[39-bit_count] <= 0;
              bit_count <= bit_count + 1;
            end
          end else begin
            pulse_timer <= pulse_timer + 1;
          end
        end
        ERROR: begin
          if (pulse_timer == 50) begin
            pulse_timer <= 0;
            if (error_count == 10) begin
              state <= IDLE;
              valid <= 0;
            end else begin
              state <= START;
              bit_count <= 0;
              data_buffer <= 0;
              checksum <= 0;
              bit_timer <= 0;
              pulse_timer <= 0;
              error_count <= error_count + 1;
              valid <= 0;
            end
          end else begin
            pulse_timer <= pulse_timer + 1;
          end
        end
      endcase
    end
  end

  // Output temperature and humidity values
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      humidity <= 0;
      temperature <= 0;
    end else begin
      if (valid) begin
        humidity <= current_humidity;
        temperature <= current_temperature;
      end else begin
        humidity <= last_humidity;
        temperature <= last_temperature;
      end
    end
  end

endmodule

