          tx_buffer <= tx_message;
          tx_enable <= 1'b1;
          state <= RX_RESPONSE;
        end
      end
      RX_RESPONSE: begin
        if (rx_valid) begin
          rx_buffer <= rx_data;
          rx_enable <= 1'b1;
          state <= RX_RESPONSE;
