          state <= IDLE;
        end
        if (timeout_count == TIMEOUT) begin
          state <= IDLE;
        end
      end
    endcase
    if (tx_enable) begin
      tx_count <= tx_count + 1;
      if (tx_count == 8'h08) begin
        tx_ready <= 1'b1;
        tx_enable <= 1'b0;
        tx_count <= 8'h00;
      end
    end else begin
      tx_ready <= 1'b0;
