							branch = 1;
						end else branch = 0;
						SEL1: if ($signed(dinA) >= 0) begin// BGEZ
							branch = 1;
						end else branch = 0;
					endcase
				end
				default: branch = 0;
			endcase
		end else branch = 0;
	end

