    input reset,
    input [49:0] in,
    input select,
    input load,
    input enable,
    output reg [49:0] q
);

    reg [49:0] rotator_out;
    reg [49:0] comb_out;
    reg [49:0] sub_out;
    reg [49:0] in_reg;
    reg [49:0] rotator_in;

    always @(posedge clk) begin
        if (reset) begin
            in_reg <= 50'b0;
            q <= 50'b0;
            rotator_in <= 50'b0;
        end else begin
            if (load) begin
                in_reg <= in;
            end
            if (enable) begin
                if (select) begin
                    rotator_in <= {in_reg[0], in_reg};
                end else begin
                    rotator_in <= {in_reg[49:1]};
                end
                comb_out <= ~(in_reg[0] | in_reg[1] | in_reg[2] | in_reg[3]);
                rotator_out <= rotator_in;
                sub_out <= comb_out - rotator_out;
                q <= sub_out;
            end
        end
    end

endmodule

module SSCG (
  input ref_clk,
  input modulation,
  output ssc_clk
);

parameter f_clk = 50; // frequency of reference clock signal (in MHz)
parameter f_spread = 10; // amount of frequency spread (in %)
parameter f_mod = 1; // frequency of modulation signal (in MHz)

reg [31:0] phase_accumulator = 0;
reg [31:0] phase_increment = 0;
reg [31:0] modulator = 0;
reg [31:0] frequency_modulation = 0;
reg [31:0] ssc_frequency = 0;

always @(posedge ref_clk or posedge modulation) begin
  if (modulation) begin
    modulator <= modulator + 1;
    frequency_modulation <= (f_spread * f_clk * modulation) / (2 * f_mod);
    phase_increment <= frequency_modulation / (2 * 3.14159);
  end
  phase_accumulator <= phase_accumulator + phase_increment;
  ssc_frequency <= f_clk + (f_spread * f_clk * sin(phase_accumulator)) / 200;
end

assign ssc_clk = ssc_frequency;

endmodule

module bv_count(
    reset,
    clk,
    bv_valid,
    bv,
    count,
    bv_out_valid,
    bv_out,
    count_out
);

parameter width       = 64;
parameter width_count = 6;
parameter stage       = 1;
parameter range_end   = 1;

input reset;
input clk;
input bv_valid;
input [width-1:0] bv;
input [width_count-1:0] count;

output  reg bv_out_valid;
output  reg [width-1:0] bv_out;
output  reg [width_count-1:0] count_out;

always @ (posedge clk) begin
    if (reset) begin
        bv_out_valid <= 1'b0;
        bv_out <= {width{1'b0}};
        count_out <= {width_count{1'b0}};
    end
    else if (bv_valid) begin
        bv_out_valid <= 1'b1;
        if (bv[range_end-1:0] != 0) begin
            bv_out <= bv;
            count_out <= count;
        end
        else begin
            bv_out <= bv >> range_end;
            count_out <= count + range_end;
        end
    end
    else begin
        bv_out_valid <= 1'b0;
        bv_out <= {width{1'b0}};
        count_out <= {width_count{1'b0}};
    end
end

endmodule

