module RegisterMult (clk, rst, load, D, Q);
  input clk, rst, load, D;
  output Q;
  wire n1, n2, n4;

  DFFRX2TS Q_reg_0_ (.D(n4), .CK(clk), .RN(n2), .Q(Q));
  INVX2TS U2 (.A(load), .Y(n1));
  AO22X1TS U3 (.A0(Q), .A1(n1), .B0(load), .B1(D), .Y(n4));
  INVX2TS U4 (.A(rst), .Y(n2));

  always @(posedge clk) begin
