module barrel_shifter (
    input CLK,
    input SHIFT,
    input [7:0] DATA,
    output reg [7:0] Q
);

reg [7:0] stage1, stage2, stage3;

always @(posedge CLK) begin
    if (SHIFT) begin
        stage1 <= DATA << 1;
        stage2 <= stage1 << 1;
        stage3 <= stage2 << 1;
    end else begin
        stage1 <= DATA >> 1;
        stage2 <= stage1 >> 1;
        stage3 <= stage2 >> 1;
    end
end

assign Q = SHIFT ? stage1 : stage3;

endmodule

