module subfxp(a, b, q, clk);

   parameter width = 16, cycles=1;

   input signed [width-1:0]  a, b;
   input                     clk;   
   output signed [width-1:0] q;
   reg signed [width-1:0]    res[cycles-1:0];

   assign                    q = res[cycles-1];

   integer                   i;   

   always @(posedge clk) begin
     res[0] <= a-b;
      for (i=1; i < cycles; i = i+1)
        res[i] <= res[i-1] >> 1;

   end

endmodule

module parity_checker (
    input [7:0] in, // 8-bit input
    output reg parity // 1 if odd number of 1's, 0 if even number of 1's
);
    always @(*) begin
        parity = ^in; // XOR all bits to get parity
    end
endmodule

module decoder (
    input [7:0] in, // 8-bit input
    output reg [15:0] out // 16 outputs, one for each 4-bit value
);
    always @(*) begin
        case (in[3:0])
            4'b0000: out[0] = 1;
            4'b0001: out[1] = 1;
            4'b0010: out[2] = 1;
            4'b0011: out[3] = 1;
            4'b0100: out[4] = 1;
            4'b0101: out[5] = 1;
            4'b0110: out[6] = 1;
            4'b0111: out[7] = 1;
            4'b1000: out[8] = 1;
            4'b1001: out[9] = 1;
            4'b1010: out[10] = 1;
            4'b1011: out[11] = 1;
            4'b1100: out[12] = 1;
            4'b1101: out[13] = 1;
            4'b1110: out[14] = 1;
            4'b1111: out[15] = 1;
        endcase
    end
endmodule

module control_logic (
    input select, // Select input to choose between parity checker and decoder
    input [7:0] in, // 8-bit input
    output reg [3:0] out // 4-bit output based on the rules above
);
    wire parity;
    wire [15:0] decoder_out;

    parity_checker parity_checker_inst (
        .in(in),
        .parity(parity)
    );

    decoder decoder_inst (
        .in(in),
        .out(decoder_out)
    );

    always @(*) begin
        if (select == 0) begin // Parity checker is selected
            if (parity == 0) begin // Even number of 1's
                if ((in[3:0] % 4) == 0) begin // Multiple of 4
                    out = 4'b0000;
                end else begin // Not a multiple of 4
                    out = 4'b0001;
                end
            end else begin // Odd number of 1's
                if ((in[3:0] % 4) == 0) begin // Multiple of 4
                    out = 4'b1110;
                end else begin // Not a multiple of 4
                    out = 4'b1111;
                end
            end
        end else begin // Decoder is selected
            case (decoder_out)
                16'h0001: out = 4'b0001;
                16'h0010: out = 4'b0010;
                16'h0011: out = 4'b0011;
                16'h0100: out = 4'b0100;
                16'h0101: out = 4'b0101;
                16'h0110: out = 4'b0110;
                16'h0111: out = 4'b0111;
                16'h1000: out = 4'b1000;
                16'h1001: out = 4'b1001;
                16'h1010: out = 4'b1010;
                16'h1011: out = 4'b1011;
                16'h1100: out = 4'b1100;
                16'h1101: out = 4'b1101;
                16'h1110: out = 4'b1110;
                16'h1111: out = 4'b1111;
                default: out = 4'b0000;
            endcase
        end
    end
endmodule

module top_module (
    input clk,
    input reset, // Synchronous active-high reset
    input [7:0] in, // 8-bit input
    input select, // Select input to choose between parity checker and decoder
    output [3:0] out // 4-bit output based on the rules above
);
    reg [3:0] out_reg;
    control_logic control_logic_inst (
        .select(select),
        .in(in),
        .out(out_reg)
    );

    always @(posedge clk) begin
        if (reset) begin
            out_reg <= 4'b0000;
        end else begin
            out_reg <= control_logic_inst.out;
        end
    end

    assign out = out_reg;
endmodule

module my_module (
