    input B1;

    assign X = ((A1 & ~A2) | (A2 & ~A1 & A3 & ~B1) | (~A1 & ~A2 & ~A3 & B1)) ? 1'b1 : 1'b0;

endmodule

module c_rr_arbiter_base
  (mask, req, gnt);

   // number of input ports
   parameter num_ports = 32;

   // priority mask
   input [0:num_ports-1] mask;

   // vector of requests
   input [0:num_ports-1] req;

   // vector of grants
   output [0:num_ports-1] gnt;
   wire [0:num_ports-1]   gnt;

   // separate qualified and unqualified requests
   wire [0:num_ports-1]   req_qual;
   assign req_qual = req & mask;

   wire [0:num_ports-1]   req_unqual;
   assign req_unqual = req & ~mask;

   // generate grants for qualified requests
   wire [0:num_ports-1]   gnt_qual;
   gen_grants
     #(.width(num_ports))
   grant_qual_gen
     (.req(req_qual),
      .gnt(gnt_qual));

   // generate grants for unqualified requests
   wire [0:num_ports-1]   gnt_unqual;
   gen_grants
     #(.width(num_ports))
   grant_unqual_gen
     (.req(req_unqual),
      .gnt(gnt_unqual));

   // combine qualified and unqualified grants
   assign gnt = (|req_qual) ? gnt_qual : gnt_unqual;

endmodule

module gen_grants
  #(parameter width = 32)
  (req, gnt);

  input [0:width-1] req;
  output [0:width-1] gnt;

  reg [0:width-1] req_fifo;
  reg [0:width-1] gnt_fifo;
  reg [0:width-1] gnt_mask;
  reg [0:width-1] req_mask;
  integer i;

  always @(*) begin
    // initialize request and grant masks
    req_mask = req;
    gnt_mask = 0;

    // generate grants for qualified requests
    for (i = 0; i < width; i = i + 1) begin
      if (req_mask[i]) begin
        gnt_mask[i] = 1;
        req_mask[i] = 0;
      end
    end

    // generate grants for unqualified requests
    for (i = 0; i < width; i = i + 1) begin
      if (req_mask[i]) begin
        gnt_mask[i] = 1;
        req_mask[i] = 0;
      end
    end

    // update request and grant FIFOs
    req_fifo = req;
    gnt_fifo = gnt_mask;

    // generate grants from grant FIFO
    gnt = gnt_fifo & req;
  end

endmodule

module synchronizer (
  input data_in,
  input clk_in,
  output reg data_out,
  output reg clk_out
);

  // Define parameters and input/output widths as necessary
  parameter SYNC_DELAY = 2; // Number of cycles to delay the synchronized output
  parameter META_THRESHOLD = 3; // Number of cycles to wait for metastability to settle

  reg [1:0] sync_state; // State variable for the synchronizer
  reg [1:0] meta_count; // Counter for metastability detection

  always @(posedge clk_in) begin
    // First flip-flop
    sync_state[0] <= data_in;
    meta_count[0] <= 0;
  end

  always @(posedge clk_in) begin
    // Second flip-flop
    sync_state[1] <= sync_state[0];
    meta_count[1] <= meta_count[0];
  end

  always @(posedge clk_in) begin
    // Metastability detection
    if (sync_state[1] != sync_state[0]) begin
      meta_count[0] <= meta_count[1] + 1;
    end else begin
      meta_count[0] <= 0;
    end
  end

  always @(posedge clk_in) begin
    // Generate synchronized clock signal
    if (meta_count[1] >= META_THRESHOLD) begin
      clk_out <= ~clk_out;
    end else begin
      clk_out <= clk_in;
    end
  end

  always @(posedge clk_in) begin
    // Generate synchronized data signal
    if (meta_count[1] >= META_THRESHOLD + SYNC_DELAY) begin
      data_out <= sync_state[1];
    end
  end

endmodule

