module roundfunc(clk, li, ri, lo, ro, k);
input clk;
input [1:32] li, ri;
input [1:48] k;
output [1:32] lo, ro;

wire [1:48] e;
wire [1:6] b1x, b2x, b3x, b4x, b5x, b6x, b7x, b8x;
wire [1:4] so1x, so2x, so3x, so4x, so5x, so6x, so7x, so8x;
wire [1:32] ppo;

// Perform an expansion permutation on the ri vector, producing a 48-bit vector e.
xp xp(ri, e);

// Perform an XOR operation between the expanded ri vector and the 48-bit key k, producing eight 6-bit vectors, b1x through b8x.
desxor1 desxor1(e, b1x, b2x, b3x, b4x, b5x, b6x, b7x, b8x, k);

// Perform eight S-box substitutions on the eight 6-bit vectors, producing eight 4-bit vectors, so1x through so8x.
s1 s1(clk, b1x, so1x);
s2 s2(clk, b2x, so2x);
s3 s3(clk, b3x, so3x);
s4 s4(clk, b4x, so4x);
s5 s5(clk, b5x, so5x);
s6 s6(clk, b6x, so6x);
s7 s7(clk, b7x, so7x);
s8 s8(clk, b8x, so8x);

// Perform a permutation on the eight 4-bit vectors, producing a 32-bit vector ppo.
pp pp(so1x, so2x, so3x, so4x, so5x, so6x, so7x, so8x, ppo);

// Perform an XOR operation between the li vector and the ppo vector, producing the ro vector.
desxor2 desxor2(ppo, li, ro);

// Assign the value of ri to lo.
assign lo = ri;

endmodule

