module signed_multiplier (
    input signed [15:0] A,
    input signed [15:0] B,
    output signed [31:0] P
);
    reg signed [31:0] P_reg;
    reg signed [15:0] A_reg;
    reg signed [15:0] B_reg;
    reg [1:0] state;

    always @(*) begin
        case(state)
            2'b00: P_reg = 0;
            2'b01, 2'b10: P_reg = {P_reg[31], P_reg[31:1]}; //arithmetic shift right
            2'b11: P_reg = {P_reg[31], P_reg[31:1] - A_reg};
        endcase
    end

    always @(A, B) begin
        A_reg = A;
        B_reg = B;
        state = 2'b00;
    end

    always @(posedge clk) begin
        case(state)
            2'b00: begin
                if(B_reg[0] == 1) begin
                    P_reg = -A_reg;
                end
                state = 2'b01;
            end
            2'b01: begin
                if(shift_amount == 0) begin
                    state = 2'b11;
                end else begin
                    state = 2'b10;
                end
            end
            2'b10: begin
                if(shift_direction == 1) begin
                    P_reg = {P_reg[31:shift_amount], P_reg[shift_amount-1:0]};
                end else begin
                    P_reg = {P_reg[shift_amount-1:0], P_reg[31-shift_amount+1:0]};
                end
                state = 2'b11;
            end
        endcase
    end

    assign P = P_reg;
endmodule
module barrel_shifter (
    input [7:0] data_in,
    input [2:0] shift_amount,
    input shift_direction,
    output [7:0] data_out
);
    reg [7:0] data_out_reg;

    always @(*) begin
        if(shift_direction == 1) begin
            data_out_reg = {data_in[7:shift_amount], {shift_amount{1'b0}}};
        end else begin
            data_out_reg = {{shift_amount{1'b0}}, data_in[7-shift_amount:0]};
        end
    end

    assign data_out = data_out_reg;
endmodule
module abs_difference (
    input signed [15:0] A,
    input signed [15:0] B,
    input signed [31:0] P,
    input [7:0] shift_amount,
    input shift_direction,
    output logic threshold_met
);
    reg signed [31:0] shifted_P;
    reg signed [31:0] A_times_B;

    signed_multiplier multiplier(.A(A), .B(B), .P(A_times_B));
    barrel_shifter shifter(.data_in(A_times_B), .shift_amount(shift_amount), .shift_direction(shift_direction), .data_out(shifted_P));

    always @(*) begin
        if(shifted_P >= A_times_B) begin
            threshold_met = (shifted_P - A_times_B) <= 100;
        end else begin
            threshold_met = (A_times_B - shifted_P) <= 100;
        end
    end
endmodule
module top_module (
    input signed [15:0] A,
    input signed [15:0] B,
    input [7:0] shift_amount,
    input shift_direction,
    output logic threshold_met
);
    reg signed [31:0] P;

    signed_multiplier multiplier(.A(A), .B(B), .P(P));
    barrel_shifter shifter(.data_in(P), .shift_amount(shift_amount), .shift_direction(shift_direction), .data_out(P));
    abs_difference difference(.A(A), .B(B), .P(P), .shift_amount(shift_amount), .shift_direction(shift_direction), .threshold_met(threshold_met));
endmodule

module DataPath(input clk, reset, ir_write, B_write, pc_src, pc_write, mem_src, mem_write, stack_src, tos, push, pop, output reg  z, output [2:0] inst_op);

	//pc & inst Memory
	reg  [4:0] pc, next_pc;
	reg  [7:0] IR, B_reg;
	assign inst_op = IR[7:5];

	//data memory
	reg  [4:0] 	mem_addr;
	reg  [7:0] mem_write_data;
	wire [7:0] mem_out_data;

	//stack
	reg  [7:0] stack_in;
	wire [7:0] stack_out;

	//ALU
	reg [7:0] alu_A, alu_B;
	wire [7:0] alu_out;
	reg  [7:0] alu_reg;

	//Modules
	DataMem data_mem (clk, mem_write, mem_addr , mem_write_data, mem_out_data);
	Stack 	stack(clk, tos, push,pop, stack_in, stack_out);
	ALU 	alu(inst_op , alu_A, alu_B, alu_out); 



	always @(*) begin //calculate the new pc
		//PC
		case(pc_src)
			1'b0: next_pc <= IR[4:0];
			1'b1: next_pc <= pc + 1;
		endcase

		//Stack
		case(stack_src)
			1'b0: stack_in <= mem_out_data;
			1'b1: stack_in <= alu_reg;
		endcase
		//z
		if(stack_out == 8'b0)
			z = 1'b1;
		else z = 1'b0;
		//ALU
		alu_A <= stack_out;
		alu_B <= B_reg;


		//Data Memory
		case(mem_src)
			1'b0: mem_addr <= IR[4:0];
			1'b1: mem_addr <= pc;
		endcase
		mem_write_data <= stack_out;
	end

	always @(posedge clk)begin //set new values to registers
		if(reset == 1'b0)
		begin
			if(pc_write)
				pc = next_pc;
			if(ir_write)
				IR <= mem_out_data;
			if(B_write)
				B_reg <= stack_out;
			alu_reg <= alu_out;
		end
		else begin
			{pc,IR, B_reg} = 0;
			alu_reg = 8'b0;
		end
	end
endmodule

module t (
   // Inputs
   input clk
   );

   reg prev_clk;
   reg [31:0] counter;

   always @(posedge clk) begin
