module top_module(
    input [31:0] a,
    input [31:0] b,
    input div,
    output [31:0] result
);

    reg [31:0] quotient;
    reg [31:0] remainder;
    reg [63:0] product;
    reg [4:0] shift;
    wire [31:0] shift_register_out;
    wire [63:0] multiplier_out;
    wire [31:0] final_out;

    booth_multiplier booth(
        .multiplicand(a),
        .multiplier(b),
        .product(product)
    );

    shift_register shift_reg(
        .dividend(a),
        .divisor(b),
        .shift(shift),
        .quotient(quotient),
        .remainder(remainder)
    );

    functional_module func(
        .multiplier_out(multiplier_out),
        .shift_register_out(shift_register_out),
        .div(div),
        .final_out(final_out)
    );

    and_gate and1(
        .a(a),
        .b(b),
        .out(multiplier_out[31:0])
    );

    and_gate and2(
        .a(a),
        .b(~b),
        .out(multiplier_out[63:32])
    );

    always @(*) begin
        if(div == 0) begin
            product = a * b;
            result = product[31:0];
        end else begin
            shift = 0;
            quotient = 0;
            remainder = a;
            while(shift < 32) begin
                if(remainder[31] == 1) begin
                    remainder = remainder - b;
                    quotient = quotient + (1 << shift);
                end
                remainder = remainder << 1;
                shift = shift + 1;
            end
            final_out = quotient;
            result = final_out;
        end
    end

endmodule

module booth_multiplier (
    input [31:0] multiplicand,
    input [31:0] multiplier,
    output reg [63:0] product
);

    reg [31:0] a;
    reg [31:0] s;
    reg [31:0] p;
    reg [1:0] state;

    always @(posedge clk) begin
        case(state)
            2'b00: begin
                a <= multiplicand;
                s <= (multiplier[31] == 1) ? ~{31'b0, multiplier} + 1 : {32'b0, multiplier};
                state <= 2'b01;
            end
            2'b01: begin
                if(s[0] == 1) begin
                    p <= a - s;
                    state <= 2'b10;
                end else begin
                    p <= a;
                    state <= 2'b10;
                end
            end
            2'b10: begin
                p <= p >> 1;
                s <= s >> 1;
                state <= (state == 2'b10 && s[0] == 1) ? 2'b01 : state;
            end
        endcase
    end

    assign product = {p, a};

endmodule

module shift_register (
    input [31:0] dividend,
    input [31:0] divisor,
    input [4:0] shift,
    output reg [31:0] quotient,
    output reg [31:0] remainder
);

    reg [31:0] reg_dividend;
    reg [31:0] reg_divisor;
    reg [31:0] reg_quotient;
    reg [31:0] reg_remainder;

    always @(posedge clk) begin
        if(shift == 0) begin
            reg_dividend <= dividend;
            reg_divisor <= divisor;
            reg_quotient <= 0;
            reg_remainder <= dividend;
        end else begin
            reg_dividend <= reg_dividend << 1;
            reg_divisor <= reg_divisor << 1;
            reg_quotient <= reg_quotient << 1;
            if(reg_remainder >= reg_divisor) begin
                reg_remainder <= reg_remainder - reg_divisor;
                reg_quotient <= reg_quotient + 1;
            end
        end
    end

    assign quotient = reg_quotient;
    assign remainder = reg_remainder;

endmodule

