module four_bit_adder(
  input [3:0] A,
  input [3:0] B,
  input Cin,
  output [3:0] S,
  output Cout
);

  wire [3:0] sum;
  wire [3:0] carry;

  // First bit of sum and carry
  full_adder fa0(A[0], B[0], Cin, sum[0], carry[0]);

  // Subsequent bits of sum and carry
  full_adder fa1(A[1], B[1], carry[0], sum[1], carry[1]);
  full_adder fa2(A[2], B[2], carry[1], sum[2], carry[2]);
  full_adder fa3(A[3], B[3], carry[2], sum[3], Cout);

  assign S = sum;

endmodule

module full_adder(
  input A,
  input B,
  input Cin,
  output S,
  output Cout
);

  wire s1, s2, c1, c2;

  // First stage
  xor(s1, A, B);
  xor(S, s1, Cin);

  // Second stage
  and(c1, A, B);
  and(c2, s1, Cin);
  or(Cout, c1, c2);

endmodule

module pipelined_adder (
    input clk,
    input rst,
    input [7:0] a,
    input [7:0] b,
    output reg [7:0] s,
    output reg overflow
);

reg [7:0] a_reg, b_reg, s_reg;
reg [8:0] carry;

always @(posedge clk) begin
    if (rst) begin
        a_reg <= 8'b0;
        b_reg <= 8'b0;
        s_reg <= 8'b0;
        carry <= 9'b0;
        overflow <= 1'b0;
    end
    else begin
        a_reg <= a;
        b_reg <= b;
        s_reg <= s;
        carry <= {1'b0, carry[8:1]};
        s <= s_reg;
        overflow <= (a_reg[7] == b_reg[7] && s_reg[7] != a_reg[7]);
    end
end

always @(posedge clk) begin
    if (!rst) begin
        s_reg <= s_reg + a_reg + b_reg + carry;
    end
end

endmodule

