module uart_rx
(
    input clk,
    input reset,
    input rx,
    output reg [7:0] data,
    output reg valid
);

reg [3:0] state;
reg [2:0] bit_count;
reg parity;
reg [15:0] shift_reg;

parameter IDLE = 2'b00;
parameter START = 2'b01;
parameter DATA = 2'b10;
parameter PARITY = 2'b11;

// state machine
always @(posedge clk, posedge reset) begin
    if (reset) begin
        state <= IDLE;
        bit_count <= 0;
        shift_reg <= 0;
        parity <= 1;
        valid <= 0;
    end else begin
        case (state)
            IDLE: begin
                if (!rx) begin
                    state <= START;
                    bit_count <= 0;
                    shift_reg <= 0;
                    parity <= 1;
                    valid <= 0;
                end
            end
            START: begin
                shift_reg <= {shift_reg[6:0], rx};
                bit_count <= bit_count + 1;
                state <= DATA;
            end
            DATA: begin
                shift_reg <= {shift_reg[6:0], rx};
                bit_count <= bit_count + 1;
                parity <= parity ^ rx;
                if (bit_count == 8) begin
                    state <= PARITY;
                    bit_count <= 0;
                end
            end
            PARITY: begin
                shift_reg <= {shift_reg[6:0], rx};
                bit_count <= bit_count + 1;
                if (parity == rx) begin
                    data <= shift_reg[7:0];
                    valid <= 1;
                end else begin
                    valid <= 0;
                end
                state <= IDLE;
            end
        endcase
    end
end

endmodule

module barrel_shifter (
    input [31:0] data_in,
    input [4:0] shift_amount,
    output reg [31:0] data_out
);

    always @(*) begin
        if (shift_amount >= 0) begin
            data_out = data_in << shift_amount;
        end else begin
            data_out = data_in >> abs(shift_amount);
        end
    end

endmodule

module logic_module (
    A,
    B,
    C,
    D,
    E,
    F,
    G,
    H,
    X
);

    input A;
    input B;
    input C;
    input D;
    input E;
    input F;
    input G;
    input H;
    output X;

    wire and0_out;
    wire or0_out;
    wire and1_out;
    wire or1_out;

    and and0 (and0_out, A, B);
    or or0 (or0_out, C, D);
    and and1 (and1_out, E, F);
    or or1 (or1_out, G, H);

    assign X = (and0_out || or0_out || !and1_out || !or1_out);

endmodule

module shift_register (
  input [n-1:0] in,
  input shift,
  output [m-1:0] out
);

parameter m = 8; // number of output signals

// Serial Shift Register
reg [m-1:0] serial_reg;
always @(posedge shift) begin
  if (shift) begin
    serial_reg <= {serial_reg[m-2:0], in[0]};
  end else begin
    serial_reg <= {in[m-1], serial_reg[m-1:1]};
  end
end
assign out = serial_reg;

// Parallel Shift Register
reg [m-1:0] parallel_reg;
always @(posedge shift) begin
  if (shift) begin
    parallel_reg <= in;
  end else begin
    parallel_reg <= {parallel_reg[m-2:0], in[0]};
  end
end
assign out = parallel_reg;

// Left Shift Register
reg [m-1:0] left_reg;
always @(posedge shift) begin
  left_reg <= {left_reg[m-2:0], in[0]};
end
assign out = left_reg;

// Right Shift Register
reg [m-1:0] right_reg;
always @(posedge shift) begin
  right_reg <= {in[m-1], right_reg[m-1:1]};
end
assign out = right_reg;

endmodule

module binary_to_bcd(
    input wire clk,
    input wire reset,
    input wire [7:0] binary_in,
    output wire [9:0] bcd_out
);

    wire [2:0] bcd_hundreds;
    wire [3:0] bcd_tens;
    wire [3:0] bcd_ones;

    assign bcd_hundreds = {
        {3{binary_in[7]}},
        {3{binary_in[6]}},
        {3{binary_in[5]}}
    };

    assign bcd_tens = {
        {2{binary_in[4]}},
        {4{1'b0}}
    } + (binary_in[4] ? 3'd10 : 3'd0);

    assign bcd_ones = {
        {2{binary_in[3]}},
        {4{1'b0}}
    } + (binary_in[3] ? 3'd10 : 3'd0);

    assign bcd_out = {bcd_hundreds, bcd_tens[3:0], bcd_ones[3:0]};

endmodule

