    VPB    ,
    VNB
);

    output Q;
    input RESET_B;
    input D;
    input GATE;
    input VPWR;
    input VGND;
    input VPB;
    input VNB;

    wire Q_int;
    sky130_fd_sc_ms__dlrtp_2 base (
        .Q(Q_int),
        .RESET_B(RESET_B),
        .D(D),
        .GATE(GATE),
        .VPWR(VPWR),
        .VGND(VGND),
        .VPB(VPB),
        .VNB(VNB)
    );

    assign Q = GATE ? Q_int : 1'b0;

endmodule

module fixed_point_multiplier_adder (
    input CLK,
    input [15:0] A, B, C, D,
    output [31:0] O,
    output CO // Currently unused, left in case we want to support signed operations in the future.
);

    parameter [0:0] A_REG = 0;
    parameter [0:0] B_REG = 0;
    parameter [0:0] C_REG = 0;
    parameter [0:0] D_REG = 0;
    parameter [0:0] ENABLE_DSP = 0;
    parameter [0:0] A_SIGNED = 0;
    parameter [0:0] B_SIGNED = 0;

    wire [15:0] iA, iB, iC, iD;
    wire [31:0] iF, iJ, iK, iG;

    // Regs C and A, currently unused
    reg [15:0] rC, rA;

    assign iC = C_REG ? rC : C;
    assign iA = A_REG ? rA : A;

    // Regs B and D, currently unused
    reg [15:0] rB, rD;

    assign iB = B_REG ? rB : B;
    assign iD = D_REG ? rD : D;

    // Multiplier Stage
    wire [31:0] p_Ah_Bh, p_Al_Bh, p_Ah_Bl, p_Al_Bl;
    wire [31:0] Ah, Al, Bh, Bl;
    assign Ah = {A_SIGNED ? {16{iA[15]}} : 16'b0, iA[15: 0]};
    assign Al = {16'b0, iA[ 7: 0]};
    assign Bh = {B_SIGNED ? {16{iB[15]}} : 16'b0, iB[15: 0]};
    assign Bl = {16'b0, iB[ 7: 0]};
    assign p_Ah_Bh = Ah * Bh; // F
    assign p_Al_Bh = {16'b0, Al[7:0]} * Bh; // J
    assign p_Ah_Bl = Ah * {16'b0, Bl[7:0]}; // K
    assign p_Al_Bl = Al * Bl; // G

    assign iF = p_Ah_Bh;
    assign iJ = p_Al_Bh;

    assign iK = p_Ah_Bl;
    assign iG = p_Al_Bl;

    // Adder Stage
    wire [39:0] iK_e = {A_SIGNED ? {16{iK[31]}} : 16'b0, iK};
    wire [39:0] iJ_e = {B_SIGNED ? {16{iJ[31]}} : 16'b0, iJ};
    assign O = ENABLE_DSP ? iG + (iK_e << 16) + (iJ_e << 16) + (iF << 32) : iA + iC;

endmodule

module d_ff_async_reset_set (
    input clk,
    input d,
    input reset,
    input set,
    output reg q,
    output reg q_n
);

    always @(posedge clk) begin
        if (reset) begin
            q <= 1'b0;
            q_n <= 1'b1;
        end else if (set) begin
            q <= 1'b1;
            q_n <= 1'b0;
        end else begin
            q <= d;
            q_n <= ~d;
        end
    end

endmodule

module blk_mem_gen_v8_3_5_softecc_output_reg_stage
  #(parameter C_DATA_WIDTH          = 32,
    parameter C_ADDRB_WIDTH         = 10,
    parameter C_HAS_SOFTECC_OUTPUT_REGS_B= 0,
    parameter C_USE_SOFTECC         = 0,
    parameter FLOP_DELAY            = 100
  )
  (
   input                         CLK,
   input      [C_DATA_WIDTH-1:0] DIN,
   output reg [C_DATA_WIDTH-1:0] DOUT,
   input                         SBITERR_IN,
   input                         DBITERR_IN,
   output reg                    SBITERR,
   output reg                    DBITERR,
   input      [C_ADDRB_WIDTH-1:0]             RDADDRECC_IN,
   output reg [C_ADDRB_WIDTH-1:0]             RDADDRECC
);

//******************************
// Port and Generic Definitions
//******************************
  //////////////////////////////////////////////////////////////////////////
  // Generic Definitions
  //////////////////////////////////////////////////////////////////////////
  // C_DATA_WIDTH                  : Memory write/read width
  // C_ADDRB_WIDTH                 : Width of the ADDRB input port
  // C_HAS_SOFTECC_OUTPUT_REGS_B   : Designates the use of a register at the output 
  //                                 of the RAM primitive
  // C_USE_SOFTECC                 : Determines if the Soft ECC feature is used or
  //                                 not. Only applicable Spartan-6
  // FLOP_DELAY                    : Constant delay for register assignments
  //////////////////////////////////////////////////////////////////////////
  // Port Definitions
  //////////////////////////////////////////////////////////////////////////
  // CLK    : Clock to synchronize all read and write operations
  // DIN    : Data input to the Output stage.
  // DOUT   : Final Data output
  // SBITERR_IN    : SBITERR input signal to the Output stage.
  // SBITERR       : Final SBITERR Output signal.
  // DBITERR_IN    : DBITERR input signal to the Output stage.
  // DBITERR       : Final DBITERR Output signal.
  // RDADDRECC_IN  : RDADDRECC input signal to the Output stage.
  // RDADDRECC     : Final RDADDRECC Output signal.
  //////////////////////////////////////////////////////////////////////////

  reg [C_DATA_WIDTH-1:0]           dout_i       = 0;
  reg                              sbiterr_i    = 0;
  reg                              dbiterr_i    = 0;
  reg [C_ADDRB_WIDTH-1:0]          rdaddrecc_i  = 0;

 //***********************************************
 // NO OUTPUT REGISTERS.
 //***********************************************
  generate if (C_HAS_SOFTECC_OUTPUT_REGS_B==0) begin : no_output_stage
    always @* begin
      DOUT = DIN;
      RDADDRECC = RDADDRECC_IN;
      SBITERR = SBITERR_IN;
      DBITERR = DBITERR_IN;
    end
  end
  endgenerate

 //***********************************************
 // WITH OUTPUT REGISTERS.
 //***********************************************
  generate if (C_HAS_SOFTECC_OUTPUT_REGS_B==1) begin : has_output_stage
      always @(posedge CLK) begin
      dout_i <= #FLOP_DELAY DIN;
      rdaddrecc_i <= #FLOP_DELAY RDADDRECC_IN;
      sbiterr_i <= #FLOP_DELAY SBITERR_IN;
      dbiterr_i <= #FLOP_DELAY DBITERR_IN;
      end

      always @* begin
      DOUT = dout_i;
      RDADDRECC = rdaddrecc_i;
      SBITERR = sbiterr_i;
      DBITERR = dbiterr_i;
      end //end always
      end //end in_or_out_stage generate statement
 endgenerate

endmodule

module MUX21 (A, B, Sel, Z);
input A;
input B;
input Sel;
output Z;

  reg Z;

  always @ (A, B, Sel)
    begin
      if (Sel == 0)
        Z = A;
      else
        Z = B;
    end

endmodule

module delay_gate (
  input clk,
  input data,
  output delayed_data
);

  parameter DELAY = 1;
  reg [DELAY-1:0] data_buffer;
  reg [DELAY-1:0] delayed_data_buffer;
  reg [DELAY-1:0] delay_counter;

  always @(posedge clk) begin
    delay_counter <= delay_counter + 1;
    if (delay_counter == DELAY) begin
      delayed_data_buffer <= data_buffer;
    end
    data_buffer <= data;
  end

  assign delayed_data = delayed_data_buffer[DELAY-1];

endmodule

module buffer (
  input I,
  output reg O,
  input CE,
  input R
);

  reg [1:0] q;
  wire d = (R) ? 1'b0 : q[0];

  always @(posedge CE) begin
    if (R) begin
      q <= 2'b0;
      O <= 1'b0;
    end
    else begin
      q <= {q[0], I};
      O <= q[1];
    end
  end

endmodule

module sky130_fd_sc_ms__tapvpwrvgnd (input wire VPWR, VGND, VPB, VNB);

    wire [1:0] state;
    assign state = {VNB, VGND};

    always @(*) begin
        case(state)
            2'b00: begin
                VPB = 1'b1;
                VPWR = 1'bx;
            end
            2'b01: begin
                VPB = 1'bx;
                VPWR = 1'b0;
            end
            2'b10: begin
                VPB = 1'b0;
                VPWR = 1'bx;
            end
            2'b11: begin
                VPB = 1'bx;
                VPWR = 1'b1;
            end
            default: begin
                VPB = 1'bx;
                VPWR = 1'bx;
            end
        endcase
    end

    always @(posedge VGND) begin
        VNB <= 1'b0;
    end

    always @(posedge VNB) begin
        VGND <= 1'b1;
    end

    always @(posedge VPB) begin
        VPWR <= 1'b0;
    end

    always @(posedge VPWR) begin
        VPB <= 1'b1;
    end

endmodule

module KeyEncoder(
    input [3:0] Columns,
    input [3:0] Rows,
    input Clock,
    input Reset,
    output reg [3:0] OnesDigit,
    output reg [3:0] TensDigit,
    output reg Found
);

    parameter NoKey = 9'd0;
    parameter key1 = 9'b100000001;
    parameter key2 = 9'b100000010;
    parameter key3 = 9'b100000011;
    parameter key4 = 9'b100000100;
    parameter key5 = 9'b100000101;
    parameter key6 = 9'b100000110;
    parameter key7 = 9'b100000111;
    parameter key8 = 9'b100001000;
    parameter key9 = 9'b100001001;
    parameter keyA = 9'b100010000;
    parameter keyB = 9'b100010001;
    parameter keyC = 9'b100010010;
    parameter keyD = 9'b100010011;
    parameter keyStar = 9'b100010100;
    parameter key0 = 9'b100010101;
    parameter keyPound = 9'b100010110;

    always @(posedge Clock or posedge Reset) begin
        if (Reset == 1) begin
            Found <= 0;
            TensDigit <= NoKey;
            OnesDigit <= NoKey;
        end else begin
            case ({Columns, Rows})
                8'b01110111: begin
                    Found <= 1;
                    TensDigit <= key1[8:5];
                    OnesDigit <= key1[4:1];
                end
                8'b10110111: begin
                    Found <= 1;
                    TensDigit <= key2[8:5];
                    OnesDigit <= key2[4:1];
                end
                8'b11010111: begin
                    Found <= 1;
                    TensDigit <= key3[8:5];
                    OnesDigit <= key3[4:1];
                end
                8'b01111011: begin
                    Found <= 1;
                    TensDigit <= key4[8:5];
                    OnesDigit <= key4[4:1];
                end
                8'b10111011: begin
                    Found <= 1;
                    TensDigit <= key5[8:5];
                    OnesDigit <= key5[4:1];
                end
                8'b11011011: begin
                    Found <= 1;
                    TensDigit <= key6[8:5];
                    OnesDigit <= key6[4:1];
                end
                8'b01111101: begin
                    Found <= 1;
                    TensDigit <= key7[8:5];
                    OnesDigit <= key7[4:1];
                end
                8'b10111101: begin
                    Found <= 1;
                    TensDigit <= key8[8:5];
                    OnesDigit <= key8[4:1];
                end
                8'b11011101: begin
                    Found <= 1;
                    TensDigit <= key9[8:5];
                    OnesDigit <= key9[4:1];
                end
                8'b11100111: begin
                    Found <= 1;
                    TensDigit <= keyA[8:5];
                    OnesDigit <= keyA[4:1];
                end
                8'b11101011: begin
                    Found <= 1;
                    TensDigit <= keyB[8:5];
                    OnesDigit <= keyB[4:1];
                end
                8'b11101101: begin
                    Found <= 1;
                    TensDigit <= keyC[8:5];
                    OnesDigit <= keyC[4:1];
                end
                8'b11101110: begin
                    Found <= 1;
                    TensDigit <= keyD[8:5];
                    OnesDigit <= keyD[4:1];
                end
                8'b01111110: begin
                    Found <= 1;
                    TensDigit <= keyStar[8:5];
                    OnesDigit <= keyStar[4:1];
                end
                8'b10111110: begin
                    Found <= 1;
                    TensDigit <= key0[8:5];
                    OnesDigit <= key0[4:1];
                end
                8'b11011110: begin
                    Found <= 1;
                    TensDigit <= keyPound[8:5];
                    OnesDigit <= keyPound[4:1];
                end
                default: begin
                    Found <= 0;
                    TensDigit <= NoKey;
                    OnesDigit <= NoKey;
                end
            endcase
        end
    end

endmodule

module multiplier (
    input clk,
    input reset,
    input signed [7:0] multiplier,
    input signed [7:0] multiplicand,
    output signed [15:0] product,
    output reg done
);

    reg signed [15:0] partial_product;
    reg [3:0] bit_counter;
    reg signed [15:0] sum;

    always @(posedge clk) begin
        if (reset) begin
            bit_counter <= 0;
            partial_product <= 0;
            sum <= 0;
            done <= 0;
        end else begin
            if (bit_counter == 0) begin
                partial_product <= multiplicand;
            end else begin
                partial_product <= {partial_product[14:0], partial_product[15]} << 1;
            end

            if (multiplier[bit_counter]) begin
                sum <= sum + partial_product;
            end

            bit_counter <= bit_counter + 1;

            if (bit_counter == 8) begin
                product <= sum;
                done <= 1;
            end
        end
    end

endmodule

module ECC (
  input [p-1:0] p,
  input [n-1:0] a,
  input [n-1:0] b,
  input [n-1:0] Px,
  input [n-1:0] Py,
  input [n-1:0] Qx,
  input [n-1:0] Qy,
  output [n-1:0] Rx,
  output [n-1:0] Ry,
  output [n-1:0] Sx,
  output [n-1:0] Sy
);

parameter n = 8; // number of bits for the coordinates
parameter p = 256; // prime number that defines the finite field
parameter a = 1; // coefficient a of the elliptic curve
parameter b = 2; // coefficient b of the elliptic curve

// coordinates of point P on the elliptic curve
parameter Px = "00000001";
parameter Py = "00000010";

// coordinates of point Q on the elliptic curve
parameter Qx = "00000011";
parameter Qy = "00000001";

// calculate point R = P + Q
wire [n-1:0] x1 = Px;
wire [n-1:0] y1 = Py;
wire [n-1:0] x2 = Qx;
wire [n-1:0] y2 = Qy;

wire [n-1:0] x3;
wire [n-1:0] y3;

wire [n-1:0] m;
wire [n-1:0] m2;
wire [n-1:0] x1x2;
wire [n-1:0] x3x1;
wire [n-1:0] y3y1;

assign x1x2 = x1 + x2;
assign m = (y2 - y1) * (x2 - x1x2)^(p-2);
assign m2 = m^2;
assign x3 = m2 - x1x2 - a;
assign x3x1 = x3 - x1;
assign y3 = m * x1x2 - m * x3 - y1;
assign y3y1 = y3 - y1;

assign Rx = x3;
assign Ry = y3;

// calculate point S = P - Q
wire [n-1:0] Qy_neg = ~Qy + 1;
wire [n-1:0] Qx_neg = Qx;
wire [n-1:0] Sx;
wire [n-1:0] Sy;

assign Sy = y1 + Qy_neg;
assign Sx = x1 + Qx_neg;

endmodule

module LED_driver (
  input [n-1:0] data,
  output reg [m-1:0] led
);

parameter n = 8; // number of bits in data
parameter m = 4; // number of LED lights

// define PWM parameters
parameter T = 100; // PWM period (in clock cycles)
parameter D_max = 2**n - 1; // maximum duty cycle (i.e., maximum brightness)

// define internal counters
reg [n-1:0] count;
reg [n-1:0] duty;

// generate PWM pulses
always @ (posedge clk) begin
  if (count == T) begin
    count <= 0;
  end else begin
    count <= count + 1;
  end

  for (i = 0; i < m; i = i + 1) begin
    if (data[i] > duty[i]) begin
      led[i] <= 1;
    end else begin
      led[i] <= 0;
    end
  end

  for (i = 0; i < m; i = i + 1) begin
    if (duty[i] < D_max) begin
      duty[i] <= duty[i] + 1;
    end else begin
      duty[i] <= 0;
    end
  end
end

endmodule

module counter_4bit(clk, rst, q);

input clk, rst;
output reg [3:0] q;

always @(posedge clk) begin
	if (rst == 1'b1) // Synchronous reset
		q <= 4'b0;
	else if (q == 4'b1111) // Counter rolls over to 0
		q <= 4'b0;
	else
		q <= q + 1; // Counter increments
end

endmodule

