module spi (
    // Serial pad signal
    output reg sclk,
    input      miso,
    output reg mosi,
    output reg ss,

    // Wishbone slave interface
    input            wb_clk_i,
    input            wb_rst_i,
    input      [8:0] wb_dat_i,
    output reg [7:0] wb_dat_o,
    input            wb_we_i,
    input      [1:0] wb_sel_i,
    input            wb_stb_i,
    input            wb_cyc_i,
    output reg       wb_ack_o
  );

  // Registers and nets
  wire       op;
  wire       start;
  wire       send;
  reg  [7:0] tr;
  reg        st;
  reg  [7:0] sft;
  reg  [1:0] clk_div;

  // Continuous assignments
  assign op     = wb_stb_i & wb_cyc_i;
  assign start  = !st & op;
  assign send   = start & wb_we_i & wb_sel_i[0];

  // Behaviour
  // mosi
  always @(posedge wb_clk_i)
    mosi <= wb_rst_i ? 1'b1
      : (clk_div==2'b10 ? (send ? wb_dat_i[7] : tr[7]) : mosi);

  // tr
  always @(posedge wb_clk_i)
    tr <= wb_rst_i ? 8'hff
        : (clk_div==2'b10 ? { (send ?
            wb_dat_i[6:0] : tr[6:0]), 1'b1 } : tr);

  // wb_ack_o
  always @(posedge wb_clk_i)
    wb_ack_o <= wb_rst_i ? 1'b0
      : (wb_ack_o ? 1'b0 : (sft[0] && clk_div==2'b00));

  // sft
  always @(posedge wb_clk_i)
    sft <= wb_rst_i ? 8'h0
      : (clk_div==2'b10 ? { start, sft[7:1] } : sft);

  // st
  always @(posedge wb_clk_i)
    st <= wb_rst_i ? 1'b0 : (st ? !sft[0] : op && clk_div==2'b10);

  // wb_dat_o
  always @(posedge wb_clk_i)
    wb_dat_o <= wb_rst_i ? 8'h0
      : ((op && clk_div==2'b0) ?
        { wb_dat_o[6:0], miso } : wb_dat_o);

  // sclk
  always @(posedge wb_clk_i)
    sclk <= wb_rst_i ? 1'b1
      : (clk_div[0] ? sclk : !(op & clk_div[1]));

  // ss
  always @(negedge wb_clk_i)
    ss <= wb_rst_i ? 1'b1
        : ((op & wb_we_i & wb_sel_i[1]) ? wb_dat_i[8] : ss);

  // clk_div
  always @(posedge wb_clk_i) clk_div <= clk_div - 2'd1;
endmodule

module axis_scaler #
(
  parameter integer AXIS_TDATA_WIDTH = 14
)
(
  // System signals
  input  wire                        aclk,
  input  wire                        aresetn,

  input  wire signed  [AXIS_TDATA_WIDTH-1:0]   cfg_data,

    // Slave side
  input wire signed [AXIS_TDATA_WIDTH-1:0] s_axis_tdata,
  input wire                        s_axis_tvalid,
  output wire                       s_axis_tready,

    // Master side
  input  wire                        m_axis_tready,
  output wire signed [AXIS_TDATA_WIDTH-1:0] m_axis_tdata,
  output wire                        m_axis_tvalid

);

// Registers to store the input data and the multiplied data
reg signed [AXIS_TDATA_WIDTH-1:0] s_axis_tdata_reg, s_axis_tdata_next;
reg [AXIS_TDATA_WIDTH*2-1:0] int_data_reg, int_data_next;

// Multiply the input data by the scaling factor when s_axis_tvalid and m_axis_tready are both high
wire multiply = s_axis_tvalid & m_axis_tready;

// Clock edge sensitive process
always @(posedge aclk)
begin
    // Asynchronous reset
    if(~aresetn)
    begin
        s_axis_tdata_reg <= 0;
        s_axis_tdata_next <= 0;
        int_data_reg <= 0;
        int_data_next <= 0;
    end
    // Multiply the input data by the scaling factor when s_axis_tvalid and m_axis_tready are both high
    else
    begin
        if(multiply)
        begin
            s_axis_tdata_reg <= s_axis_tdata;
            s_axis_tdata_next <= s_axis_tdata_reg;
            int_data_reg <= s_axis_tdata_next*cfg_data;
            int_data_next <= int_data_reg; 
        end
    end
end

// Output signals
assign s_axis_tready = m_axis_tready;
assign m_axis_tvalid = s_axis_tvalid;

// Scale down the multiplied data by a factor of 2^(AXIS_TDATA_WIDTH-2)
assign m_axis_tdata = int_data_next[AXIS_TDATA_WIDTH*2-3:AXIS_TDATA_WIDTH-2];

endmodule

module clock_generator (
    // Inputs
    input io_pwron_rst_l,
    input [2:0] sel,
    input testmode_l,
    input sysclk,
    input divbypclk,
    input byp_mult_sel_l,
    input nstepsel,
    input jtag_clock_dr,
    input capture_l,
    input bypmode,
    // Outputs
    output clkout,
    output sysclk_sel
);

// Internal signals
wire force_altclk_l;
wire altclk_sync_l;
wire tck_sync;
wire bypclk_sync_pre;
wire bypclk_sync;
wire tck_sync_pre;
wire force_alt_clk_sync;
wire mult_sel;

wire nstep_clock_dr;
wire clock_dr;
wire altclk_sync_l_bar;
wire sysclk_sel_bar;

// Clock gating
ctu_and2 u_capture_l_gated (.a (jtag_clock_dr), .b(capture_l), .z(nstep_clock_dr));

// Multiplexer for selecting clock source
ctu_mux21 u_jtag_clock_mux_gated( .z(clock_dr), .s(testmode_l), .d0(jtag_clock_dr), .d1(nstep_clock_dr));

// Synchronizers for clock signals
ctu_clksel_async_synchronizer u_mult_sel_clk(
    .presyncdata(mult_sel),
    .syncdata (force_alt_clk_sync),
    .arst_l(io_pwron_rst_l),
    .aset_l(1'b1),
    .clk (sysclk)
);

ctu_clksel_async_synchronizer u_byp_mult_sel_sync(
    .presyncdata(altclk_sync_pre),
    .syncdata (altclk_sync_l),
    .arst_l(io_pwron_rst_l),
    .aset_l(1'b1),
    .clk (divbypclk)
);

ctu_clksel_async_synchronizer u_bypclk_sync(
    .presyncdata(bypclk_sync_pre),
    .syncdata (bypclk_sync),
    .aset_l(io_pwron_rst_l),
    .arst_l(1'b1),
    .clk(divbypclk)
);

ctu_clksel_async_synchronizer u_tck_sync(
    .presyncdata(tck_sync_pre),
    .syncdata (tck_sync),
    .arst_l(io_pwron_rst_l),
    .aset_l(1'b1),
    .clk(jtag_clock_dr)
