module parity (
  input [n-1:0] data,
  input ctrl,
  output p,
  output status
);

parameter n = 8; // number of data bits

reg parity_bit;
reg [n-1:0] data_with_parity;
wire [n:0] ones_count;
wire even_parity;
wire odd_parity;

// Generate parity bit
assign ones_count = {1'b0, data} + {data, 1'b0};
assign even_parity = (ones_count % 2 == 0);
assign odd_parity = (ones_count % 2 == 1);

always @(*) begin
  if (ctrl == 0) begin
    parity_bit = even_parity;
  end else begin
    parity_bit = odd_parity;
  end
end

// Add parity bit to data
assign data_with_parity = {data, parity_bit};

// Check parity bit at receiver
assign ones_count = {1'b0, data_with_parity} + {data_with_parity, 1'b0};
assign status = (ctrl == 0 && ones_count % 2 == 1) || (ctrl == 1 && ones_count % 2 == 0);

assign p = parity_bit;

endmodule

module digital_clock(
    input clk_i,
    input rst_i,
    input hours_btn_i,
    input mins_btn_i,
    output reg [3:0] digits_o
);

reg [3:0] hours;
reg [3:0] mins;
reg [1:0] state;

parameter S_IDLE = 2'b00;
parameter S_HOURS = 2'b01;
parameter S_MINS = 2'b10;

always @(posedge clk_i, posedge rst_i) begin
    if (rst_i) begin
        hours <= 4'b0000;
        mins <= 4'b0000;
        state <= S_IDLE;
    end else begin
        case (state)
            S_IDLE: begin
                digits_o <= {4'b0000, 4'b0000};
                if (hours_btn_i) begin
                    state <= S_HOURS;
                end else if (mins_btn_i) begin
                    state <= S_MINS;
                end
            end
            S_HOURS: begin
                if (mins_btn_i) begin
                    hours <= hours + 1;
                end
                digits_o <= {4'b0000, hours};
                if (!hours_btn_i) begin
                    state <= S_IDLE;
                end
            end
            S_MINS: begin
                if (mins_btn_i) begin
                    mins <= mins + 1;
                end
                digits_o <= {4'b0000, mins};
                if (!mins_btn_i) begin
                    state <= S_IDLE;
                end
            end
        endcase
    end
end

endmodule

module binary_counter (
  input clk,
  input reset,
  output reg [3:0] count,
  output reg done,
  output reg overflow
);

  parameter IDLE = 2'b00, COUNTING = 2'b01, RESET = 2'b10;
  reg [1:0] state, next_state;

  always @(posedge clk) begin
    if (reset) begin
      count <= 4'b0;
      done <= 1'b0;
      overflow <= 1'b0;
      state <= RESET;
    end
    else begin
      state <= next_state;
      case (state)
        IDLE: begin
          count <= 4'b0;
          done <= 1'b0;
          overflow <= 1'b0;
          if (clk) next_state <= COUNTING;
          else next_state <= IDLE;
        end
        COUNTING: begin
          if (count == 4'b1001) begin
            done <= 1'b1;
            next_state <= IDLE;
          end
          else begin
            count <= count + 1;
            next_state <= COUNTING;
          end
        end
        RESET: begin
          count <= 4'b0;
          done <= 1'b0;
          overflow <= 1'b0;
          if (reset) next_state <= RESET;
          else next_state <= COUNTING;
        end
        default: next_state <= IDLE;
      endcase
      if (count == 4'b1001) overflow <= 1'b1;
      else overflow <= 1'b0;
    end
  end
endmodule

