module binary_to_gray (
    input [3:0] binary,
    output [3:0] gray
);

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;

    // Intermediate signals
    wire [3:0] xor_out;
    wire [3:0] and_out;
    wire [3:0] not_out;

    // XOR gates
    xor #(.N(2)) xor_1 (.A(binary[0]), .B(binary[1]), .Y(xor_out[1]));
    xor #(.N(2)) xor_2 (.A(binary[2]), .B(binary[3]), .Y(xor_out[3]));

    xor #(.N(2)) xor_3 (.A(xor_out[1]), .B(xor_out[3]), .Y(xor_out[2]));
    xor #(.N(2)) xor_4 (.A(binary[1]), .B(binary[2]), .Y(xor_out[0]));

    // AND gates
    and #(.N(2)) and_1 (.A(binary[0]), .B(binary[1]), .Y(and_out[1]));
    and #(.N(2)) and_2 (.A(binary[2]), .B(binary[3]), .Y(and_out[3]));

    and #(.N(2)) and_3 (.A(xor_out[1]), .B(xor_out[3]), .Y(and_out[2]));
    and #(.N(2)) and_4 (.A(binary[1]), .B(binary[2]), .Y(and_out[0]));

    // NOT gates
    not not_1 (.A(binary[0]), .Y(not_out[0]));
    not not_2 (.A(binary[1]), .Y(not_out[1]));
    not not_3 (.A(binary[2]), .Y(not_out[2]));
    not not_4 (.A(binary[3]), .Y(not_out[3]));

    // Gray code output
    assign gray[0] = binary[0];
    assign gray[1] = xor_out[1];
    assign gray[2] = xor_out[2];
    assign gray[3] = xor_out[3];

endmodule

