module top_module( 
    input wire clk,
    input wire reset,
    input wire [255:0] in,
    input wire [7:0] sel,
    output wire [7:0] out );

    // 256-to-1 Multiplexer using Binary Tree and Priority Encoder
    wire [7:0] mux_out;
    wire [7:0] mux_tree_out [7:0];
    wire [7:0] mux_priority_out;
    assign mux_priority_out = mux_tree_out[sel[7]];
    priority_encoder_8to3 priority_encoder(
        .in(sel[6:0]),
        .out(mux_priority_out)
    );
    genvar i;
    generate
        for (i = 0; i < 8; i = i + 1) begin : mux_tree
            if (i == 0) begin
                assign mux_tree_out[i] = in[0];
            end else begin
                assign mux_tree_out[i] = (i < sel) ? mux_tree_out[(i << 1) + 1] : mux_tree_out[i << 1];
            end
        end
    endgenerate
    assign mux_out = mux_priority_out;

    // Byte Splitter
    wire [7:0] upper_byte;
    wire [7:0] lower_byte;
    byte_splitter upper_splitter(
        .in(in[255:128]),
        .out(upper_byte)
    );
    byte_splitter lower_splitter(
        .in(in[127:0]),
        .out(lower_byte)
    );

    // Functional Module
    wire [7:0] and_out;
    bitwise_and and_gate(
        .a(mux_out),
        .b(upper_byte),
        .out(and_out)
    );

    // Output
    assign out = and_out;

endmodule

