module modbus_master (
  input clk,
  input reset,
  input start,
  input [7:0] slave_addr,
  input [7:0] function_code,
  input [15:0] data,
  output reg done,
  output reg [15:0] response
);

  // Internal registers
  reg [7:0] mb_address;
  reg [7:0] mb_function;
  reg [15:0] mb_data;
  reg [7:0] mb_crc_lo;
  reg [7:0] mb_crc_hi;
  reg [7:0] mb_state;
  reg [7:0] mb_byte_count;
  reg [7:0] mb_response_count;
  reg [7:0] mb_response_data [255:0];
  reg [7:0] mb_request_count;
  reg [7:0] mb_request_data [255:0];
  reg [7:0] mb_request_index;
  reg [7:0] mb_response_index;

  // Constants
  parameter IDLE = 8'h00;
  parameter SEND_ADDRESS = 8'h01;
  parameter SEND_FUNCTION = 8'h02;
  parameter SEND_DATA = 8'h03;
  parameter SEND_CRC = 8'h04;
  parameter WAIT_RESPONSE = 8'h05;
  parameter RECEIVE_DATA = 8'h06;
  parameter RECEIVE_CRC = 8'h07;

  // State machine
  always @(posedge clk) begin
    if (reset) begin
      mb_state <= IDLE;
      mb_request_count <= 0;
      mb_response_count <= 0;
      mb_request_index <= 0;
      mb_response_index <= 0;
      done <= 0;
    end else begin
      case (mb_state)
        IDLE: begin
          if (start) begin
            mb_address <= slave_addr;
            mb_function <= function_code;
            mb_data <= data;
            mb_crc_lo <= 8'hFF;
            mb_crc_hi <= 8'hFF;
            mb_byte_count <= 0;
            mb_response_count <= 0;
            mb_request_count <= 0;
            mb_request_index <= 0;
            mb_response_index <= 0;
            done <= 0;
            mb_state <= SEND_ADDRESS;
          end
        end
        SEND_ADDRESS: begin
          mb_request_data[mb_request_count] <= mb_address;
          mb_crc_lo <= mb_crc_lo ^ mb_address;
          mb_crc_hi <= mb_crc_hi ^ mb_address;
          mb_request_count <= mb_request_count + 1;
          mb_state <= SEND_FUNCTION;
        end
        SEND_FUNCTION: begin
          mb_request_data[mb_request_count] <= mb_function;
          mb_crc_lo <= mb_crc_lo ^ mb_function;
          mb_crc_hi <= mb_crc_hi ^ mb_function;
          mb_request_count <= mb_request_count + 1;
          mb_state <= SEND_DATA;
        end
        SEND_DATA: begin
          if (mb_byte_count == 0) begin
            mb_request_data[mb_request_count] <= 0;
            mb_crc_lo <= mb_crc_lo ^ 0;
            mb_crc_hi <= mb_crc_hi ^ 0;
            mb_request_count <= mb_request_count + 1;
            mb_state <= SEND_CRC;
          end else begin
            mb_request_data[mb_request_count] <= mb_data[mb_byte_count-1:mb_byte_count-8];
            mb_crc_lo <= mb_crc_lo ^ mb_data[mb_byte_count-1:mb_byte_count-8];
            mb_crc_hi <= mb_crc_hi ^ mb_data[mb_byte_count-1:mb_byte_count-8];
            mb_request_count <= mb_request_count + 1;
            mb_byte_count <= mb_byte_count - 8;
          end
        end
        SEND_CRC: begin
          mb_request_data[mb_request_count] <= mb_crc_lo;
          mb_request_count <= mb_request_count + 1;
          mb_request_data[mb_request_count] <= mb_crc_hi;
          mb_request_count <= mb_request_count + 1;
          mb_state <= WAIT_RESPONSE;
        end
        WAIT_RESPONSE: begin
          if (mb_response_count > 0) begin
            mb_response_index <= 0;
            mb_state <= RECEIVE_DATA;
          end
        end
        RECEIVE_DATA: begin
          if (mb_response_index < mb_response_count) begin
            mb_response_data[mb_response_index] <= mb_request_data[mb_response_index];
            mb_response_index <= mb_response_index + 1;
          end else begin
            mb_state <= RECEIVE_CRC;
          end
        end
        RECEIVE_CRC: begin
          if (mb_response_index < mb_response_count + 2) begin
            mb_response_data[mb_response_index] <= mb_request_data[mb_response_index];
            mb_response_index <= mb_response_index + 1;
          end else begin
            response <= mb_response_data[1:mb_response_count];
            done <= 1;
            mb_state <= IDLE;
          end
        end
      endcase
    end
  end

endmodule

module modbus_slave (
  input clk,
  input reset,
  input request,
  input [7:0] address,
  input [7:0] function_code,
  input [15:0] data,
  output reg done,
  output reg [15:0] response
);

  // Internal registers
  reg [7:0] mb_address;
  reg [7:0] mb_function;
  reg [15:0] mb_data;
  reg [7:0] mb_crc_lo;
  reg [7:0] mb_crc_hi;
  reg [7:0] mb_state;
  reg [7:0] mb_byte_count;
  reg [7:0] mb_response_count;
  reg [7:0] mb_response_data [255:0];
  reg [7:0] mb_request_count;
  reg [7:0] mb_request_data [255:0];
  reg [7:0] mb_request_index;
  reg [7:0] mb_response_index;

  // Constants
  parameter IDLE = 8'h00;
  parameter RECEIVE_ADDRESS = 8'h01;
  parameter RECEIVE_FUNCTION = 8'h02;
  parameter RECEIVE_DATA = 8'h03;
  parameter RECEIVE_CRC = 8'h04;
  parameter SEND_RESPONSE = 8'h05;

  // State machine
  always @(posedge clk) begin
    if (reset) begin
      mb_state <= IDLE;
      mb_request_count <= 0;
      mb_response_count <= 0;
      mb_request_index <= 0;
      mb_response_index <= 0;
      done <= 0;
    end else begin
      case (mb_state)
        IDLE: begin
          if (request) begin
            mb_address <= address;
            mb_function <= function_code;
            mb_data <= data;
            mb_crc_lo <= 8'hFF;
            mb_crc_hi <= 8'hFF;
            mb_byte_count <= 0;
            mb_response_count <= 0;
            mb_request_count <= 0;
            mb_request_index <= 0;
            mb_response_index <= 0;
            done <= 0;
            mb_state <= RECEIVE_ADDRESS;
          end
        end
        RECEIVE_ADDRESS: begin
          mb_request_data[mb_request_count] <= mb_address;
          mb_crc_lo <= mb_crc_lo ^ mb_address;
          mb_crc_hi <= mb_crc_hi ^ mb_address;
          mb_request_count <= mb_request_count + 1;
          mb_state <= RECEIVE_FUNCTION;
        end
        RECEIVE_FUNCTION: begin
          mb_request_data[mb_request_count] <= mb_function;
          mb_crc_lo <= mb_crc_lo ^ mb_function;
          mb_crc_hi <= mb_crc_hi ^ mb_function;
          mb_request_count <= mb_request_count + 1;
          mb_state <= RECEIVE_DATA;
        end
        RECEIVE_DATA: begin
          if (mb_byte_count == 0) begin
            mb_request_data[mb_request_count] <= 0;
            mb_crc_lo <= mb_crc_lo ^ 0;
            mb_crc_hi <= mb_crc_hi ^ 0;
            mb_request_count <= mb_request_count + 1;
            mb_state <= RECEIVE_CRC;
          end else begin
            mb_request_data[mb_request_count] <= mb_data[mb_byte_count-1:mb_byte_count-8];
            mb_crc_lo <= mb_crc_lo ^ mb_data[mb_byte_count-1:mb_byte_count-8];
            mb_crc_hi <= mb_crc_hi ^ mb_data[mb_byte_count-1:mb_byte_count-8];
            mb_request_count <= mb_request_count + 1;
            mb_byte_count <= mb_byte_count - 8;
          end
        end
        RECEIVE_CRC: begin
          mb_request_data[mb_request_count] <= mb_crc_lo;
          mb_request_count <= mb_request_count + 1;
          mb_request_data[mb_request_count] <= mb_crc_hi;
          mb_request_count <= mb_request_count + 1;
          mb_response_count <= mb_request_count;
          mb_response_index <= 0;
          mb_state <= SEND_RESPONSE;
        end
        SEND_RESPONSE: begin
          if (mb_response_index < mb_response_count) begin
            response <= mb_request_data[mb_response_index];
            mb_response_index <= mb_response_index + 1;
          end else begin
            done <= 1;
            mb_state <= IDLE;
          end
        end
      endcase
    end
  end

endmodule

module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input d,          // Input for the shift register
    input pause,      // Input to pause the counter
    input resume,     // Input to resume the counter
    output reg [3:0] q    // Output from the decade counter
);

    reg [2:0] shift_reg;
    reg [4:0] sum;
    reg counter_enable;

    // Shift register
    always @(posedge clk) begin
        if (reset) begin
            shift_reg <= 0;
        end else begin
            shift_reg <= {shift_reg[1:0], d};
        end
    end

    // Decade counter
    always @(posedge clk) begin
        if (reset) begin
            q <= 0;
        end else if (counter_enable) begin
            q <= q + 1;
        end
    end

    // Functional module
    always @(posedge clk) begin
        if (reset) begin
            sum <= 0;
        end else begin
            sum <= shift_reg + q;
        end
    end

    // Control module
    always @(posedge clk) begin
        if (reset) begin
            counter_enable <= 1;
        end else if (sum >= 12) begin
            counter_enable <= 0;
        end else if (pause) begin
            counter_enable <= 0;
        end else if (resume) begin
            counter_enable <= 1;
        end
    end

endmodule

module counter(clk, reset, enable, count);

    input clk, reset, enable;
    output reg [7:0] count;

    // q is the counter, plus the imaginary bit
    reg q [8-1:-1];

    // no_ones_below[x] = 1 iff there are no 1's in q below q[x]
    reg no_ones_below [8-1:-1];

    // q_msb is a modification to make the msb logic work
    reg q_msb;

    integer i, j, k;

    always @ (posedge reset or posedge clk)
    begin
        if (reset)
        begin
            // Resetting involves setting the imaginary bit to 1
            q[-1] <= 1;
            for (i = 0; i <= 8-1; i = i + 1)
                q[i] <= 0;
        end
        else if (enable)
        begin
            // Toggle the imaginary bit
            q[-1] <= ~q[-1];

            for (i = 0; i < 8-1; i = i + 1)
            begin
                // Flip q[i] if lower bits are a 1 followed by all 0's
                q[i] <= q[i] ^ (q[i-1] & no_ones_below[i-1]);
            end

            q[8-1] <= q[8-1] ^ (q_msb & no_ones_below[8-2]);
        end
    end

    always @(*)
    begin
        // There are never any 1's beneath the lowest bit
        no_ones_below[-1] <= 1;

        for (j = 0; j < 8-1; j = j + 1)
            no_ones_below[j] <= no_ones_below[j-1] & ~q[j-1];

        q_msb <= q[8-1] | q[8-2];

        // Copy over everything but the imaginary bit
        for (k = 0; k < 8; k = k + 1)
            count[k] <= q[k];
    end

endmodule

module lin_transmitter (
  input clk,
  input reset,
  input [7:0] data,
  output tx
);

  reg [3:0] state;
  reg [7:0] sync_byte = 8'h55;
  reg [7:0] checksum;
  reg [7:0] data_out;
  reg [3:0] bit_count;
  reg tx_reg;

  assign tx = tx_reg;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      state <= 4'b0000;
      bit_count <= 4'b0000;
      checksum <= 8'h00;
      data_out <= data;
      tx_reg <= 1'b1;
    end else begin
      case (state)
        4'b0000: begin
          tx_reg <= 1'b0;
          state <= 4'b0001;
        end
        4'b0001: begin
          tx_reg <= 1'b1;
          state <= 4'b0010;
        end
        4'b0010: begin
          tx_reg <= sync_byte[0];
          sync_byte <= {sync_byte[6:0], sync_byte[7]};
          bit_count <= bit_count + 1;
          if (bit_count == 4'b1000) begin
            state <= 4'b0011;
            bit_count <= 4'b0000;
          end
        end
        4'b0011: begin
          tx_reg <= data_out[0];
          data_out <= {data_out[6:0], data_out[7]};
          checksum <= checksum ^ data_out[7];
          bit_count <= bit_count + 1;
          if (bit_count == 4'b1000) begin
            state <= 4'b0100;
            bit_count <= 4'b0000;
          end
        end
        4'b0100: begin
          tx_reg <= checksum[0];
          checksum <= {checksum[6:0], checksum[7]};
          bit_count <= bit_count + 1;
          if (bit_count == 4'b1000) begin
            state <= 4'b0000;
            bit_count <= 4'b0000;
          end
        end
      endcase
    end
  end
endmodule

module lin_receiver (
  input clk,
  input reset,
  input rx,
  output [7:0] data
);

  reg [3:0] state;
  reg [7:0] sync_byte = 8'h55;
  reg [7:0] checksum;
  reg [7:0] data_in;
  reg [3:0] bit_count;
  reg [7:0] data_reg;

  assign data = data_reg;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      state <= 4'b0000;
      bit_count <= 4'b0000;
      checksum <= 8'h00;
      data_in <= 8'h00;
    end else begin
      case (state)
        4'b0000: begin
          if (rx == 1'b0) begin
            state <= 4'b0001;
          end
        end
        4'b0001: begin
          if (rx == 1'b1) begin
            state <= 4'b0010;
          end
        end
        4'b0010: begin
          sync_byte <= {sync_byte[6:0], rx};
          bit_count <= bit_count + 1;
          if (bit_count == 4'b1000) begin
            state <= 4'b0011;
            bit_count <= 4'b0000;
          end
        end
        4'b0011: begin
          data_in <= {data_in[6:0], rx};
          checksum <= checksum ^ rx;
          bit_count <= bit_count + 1;
          if (bit_count == 4'b1000) begin
            state <= 4'b0100;
            bit_count <= 4'b0000;
          end
        end
        4'b0100: begin
          checksum <= {checksum[6:0], rx};
          bit_count <= bit_count + 1;
          if (bit_count == 4'b1000) begin
            if (checksum == 8'h00) begin
              data_reg <= data_in;
            end
            state <= 4'b0000;
            bit_count <= 4'b0000;
          end
        end
      endcase
    end
  end
endmodule

module final_result (
    input wire clk,
    input wire rst,
    input wire load_i,
    input wire sel_a_i,
    input wire sel_b_i,
    input wire sign_i,
    input wire [7:0] exp_ieee_i,
    input wire [22:0] sgf_ieee_i,
    output reg [31:0] final_result_ieee_o
);

// Declare signals
reg [22:0] sgf_s_mux;
reg [7:0] exp_s_mux;
reg sign_s_mux;
reg [7:0] exp_mux_d1;
reg [22:0] sgf_mux_d1;
reg overunder;

// Assign overunder signal
assign overunder = sel_a_i | sel_b_i;

// Mux for sign signal
mux_3x1 #(.W(1)) sign_mux (
    .ctrl({sel_a_i, sel_b_i}),
    .d0(sign_i),
    .d1(1'b1),
    .d2(1'b0),
    .s(sign_s_mux)
);

// Mux for exponent signal
mux_ac #(.W(8)) exp_mux (
    .ctrl(overunder), 
    .d0(exp_ieee_i), 
    .d1(exp_mux_d1), 
    .s(exp_s_mux)
);

// Mux for significand signal
mux_ac #(.W(23)) sgf_mux (
    .ctrl(overunder), 
    .d0(sgf_ieee_i), 
    .d1(sgf_mux_d1), 
    .s(sgf_s_mux)
);

// Assign values to mux_d1 signals
generate
if (32 == 32) begin
    assign exp_mux_d1 = 8'hff;
    assign sgf_mux_d1 = 23'd0;
end
else begin
    assign exp_mux_d1 = 11'hfff;
    assign sgf_mux_d1 = 52'd0;
end
endgenerate

// Register for final result
register_add #(.W(32)) final_result_ieee (
    .clk(clk), 
    .rst(rst), 
    .load(load_i), 
    .d({sign_s_mux, exp_s_mux, sgf_s_mux}), 
    .q(final_result_ieee_o)
);

endmodule

module Interconnect_jtag_axi_0_0_wr_bin_cntr_6 (
  output ram_full_i_reg,
  output [7:0] WR_PNTR,
  input ram_full_fb_i_reg,
  input rx_fifo_wr_en,
  input [7:0] RD_PNTR_WR,
