  input aclk
);

  // Define constants
  parameter FIFO_DEPTH = 256;
  parameter FIFO_WIDTH = 8;
  parameter WR_BIN_CNTR_WIDTH = 6;
  parameter RD_BIN_CNTR_WIDTH = 8;

  // Define wires
  wire [FIFO_WIDTH-1:0] fifo_data_out;
  wire [FIFO_WIDTH-1:0] fifo_data_in;
  wire fifo_full;
  wire fifo_empty;
  wire [WR_BIN_CNTR_WIDTH-1:0] wr_bin_cntr;
  wire [RD_BIN_CNTR_WIDTH-1:0] rd_bin_cntr;

  // Instantiate FIFO buffer
  fifo #(
    .DEPTH(FIFO_DEPTH),
    .WIDTH(FIFO_WIDTH)
  ) fifo_inst (
    .clk(aclk),
    .data_out(fifo_data_out),
    .data_in(fifo_data_in),
    .full(fifo_full),
