module parity_generator (
    input clk,
    input reset,
    input [7:0] in,
    output reg parity
);

reg [7:0] shift_reg;
reg [7:0] next_shift_reg;
reg [7:0] shift_reg_pipe[2:0];

integer i;

always @(posedge clk) begin
    if (reset) begin
        shift_reg <= 8'b0;
        parity <= 1'b0;
    end else begin
        shift_reg <= in;
        next_shift_reg[7] <= shift_reg[6] ^ shift_reg[5] ^ shift_reg[4] ^ shift_reg[3] ^ shift_reg[2] ^ shift_reg[1] ^ shift_reg[0] ^ in[7];
        next_shift_reg[6] <= shift_reg[5] ^ shift_reg[4] ^ shift_reg[3] ^ shift_reg[2] ^ shift_reg[1] ^ shift_reg[0] ^ in[7];
        next_shift_reg[5] <= shift_reg[4] ^ shift_reg[3] ^ shift_reg[2] ^ shift_reg[1] ^ shift_reg[0] ^ in[7];
        next_shift_reg[4] <= shift_reg[3] ^ shift_reg[2] ^ shift_reg[1] ^ shift_reg[0] ^ in[7];
        next_shift_reg[3] <= shift_reg[2] ^ shift_reg[1] ^ shift_reg[0] ^ in[7];
        next_shift_reg[2] <= shift_reg[1] ^ shift_reg[0] ^ in[7];
        next_shift_reg[1] <= shift_reg[0] ^ in[7];
        next_shift_reg[0] <= in[7];
        shift_reg <= next_shift_reg;
        shift_reg_pipe[0] <= shift_reg_pipe[1];
        shift_reg_pipe[1] <= shift_reg_pipe[2];
        shift_reg_pipe[2] <= shift_reg;
        parity <= shift_reg_pipe[0][7] ^ shift_reg_pipe[1][7] ^ shift_reg_pipe[2][7];
    end
end

endmodule

module top_module (
    input [7:0] in,
    output parity
);

reg clk;
reg reset;

parity_generator parity_gen (
    .clk(clk),
    .reset(reset),
    .in(in),
    .parity(parity)
);

initial begin
    clk = 1'b0;
    reset = 1'b1;
    #10 reset = 1'b0;
end

always #5 clk = ~clk;

endmodule

module unsigned_multiplier (
    input [3:0] A,
    input [3:0] B,
    output reg [7:0] product
);

reg [3:0] A_reg;
reg [3:0] B_reg;
reg [7:0] partial_product1;
reg [7:0] partial_product2;

always @(posedge clk) begin
    A_reg <= A;
    B_reg <= B;
    partial_product1 <= A_reg * B_reg;
end

always @(posedge clk) begin
    partial_product2 <= {partial_product1[3:0], 4'b0} + (A_reg * B_reg << 4);
    product <= partial_product2;
end

endmodule

module booth_multiplier_bcd (
    input signed [7:0] A,
    input signed [7:0] B,
    input ready,
    output reg [3:0] BCD_HI,
    output reg [3:0] BCD_LO
); 

reg [15:0] product;
reg valid;
reg [3:0] BCD_HI_reg;
reg [3:0] BCD_LO_reg;
reg [3:0] BCD_HI_next;
reg [3:0] BCD_LO_next;
reg [3:0] BCD_HI_temp;
reg [3:0] BCD_LO_temp;
reg [3:0] BCD_HI_final;
reg [3:0] BCD_LO_final;
reg [15:0] BCD_temp;
reg [3:0] count;
reg [3:0] select;

always @ (posedge ready) begin
    product <= A * B;
    valid <= 1;
    BCD_HI_reg <= 0;
    BCD_LO_reg <= 0;
    BCD_HI_next <= 0;
    BCD_LO_next <= 0;
    BCD_HI_temp <= 0;
    BCD_LO_temp <= 0;
    BCD_HI_final <= 0;
    BCD_LO_final <= 0;
    BCD_temp <= product;
    count <= 0;
    select <= 0;
end

always @ (posedge ready) begin
    if (valid == 1) begin
        select <= 1;
    end
end

always @ (posedge ready) begin
    if (select == 1) begin
        BCD_HI_temp <= 0;
        BCD_LO_temp <= 0;
        BCD_HI_next <= 0;
        BCD_LO_next <= 0;
        BCD_HI_final <= 0;
        BCD_LO_final <= 0;
        count <= 0;
        BCD_temp <= product;
        while (BCD_temp > 0) begin
            if (count < 4) begin
                BCD_LO_temp <= BCD_temp % 10;
                BCD_temp <= BCD_temp / 10;
                BCD_LO_next <= BCD_LO_temp << (4 * count);
                BCD_LO_final <= BCD_LO_final | BCD_LO_next;
            end
            else begin
                BCD_HI_temp <= BCD_temp % 10;
                BCD_temp <= BCD_temp / 10;
                BCD_HI_next <= BCD_HI_temp << (4 * (count - 4));
                BCD_HI_final <= BCD_HI_final | BCD_HI_next;
            end
            count <= count + 1;
        end
    end
end

assign BCD_HI = (select == 0) ? 0 : BCD_HI_final;
assign BCD_LO = (select == 0) ? 0 : BCD_LO_final;

endmodule

module top_module(
    input [3:0] a,
    input [3:0] b,
    input sel_b1,
    input sel_b2,
    output [3:0] out_always,
    output [3:0] out_and,
    output [3:0] out_or,
    output [3:0] out_xor
);

    wire [3:0] mux1_out;
    wire [3:0] mux2_out;
    wire [3:0] adder_out;
    wire [3:0] and_out;
    wire [3:0] or_out;
    wire [3:0] xor_out;

    // 2-to-1 multiplexers
    mux2to1 mux1(.a(a), .b(b), .sel(sel_b1), .out(mux1_out));
    mux2to1 mux2(.a(a), .b(b), .sel(sel_b2), .out(mux2_out));

    // 4-bit adder
    adder add(.a(mux1_out), .b(mux2_out), .out(adder_out));

    // Bitwise AND, OR, and XOR
    assign and_out = a & b;
    assign or_out = a | b;
    assign xor_out = a ^ b;

    // Output selection
    always @(*) begin
        if (sel_b1 == 1 && sel_b2 == 1) begin
            out_and = and_out;
            out_or = or_out;
            out_xor = xor_out;
        end else if (sel_b1 == 0 && sel_b2 == 0) begin
            out_always = adder_out;
        end else begin
            out_always = sel_b1 ? mux2_out : mux1_out;
        end
    end

endmodule

module mux2to1(
    input [3:0] a,
    input [3:0] b,
    input sel,
    output [3:0] out
);

    assign out = sel ? b : a;

endmodule

module adder(
    input [3:0] a,
    input [3:0] b,
    output [3:0] out
);

    assign out = a + b;

endmodule

module binary_to_gray_converter (
  input [3:0] binary_in,
  output [3:0] gray_out
);

  reg [3:0] gray_temp;

  always @ (binary_in) begin
    case (binary_in)
      4'b0000: gray_temp = 4'b0000;
      4'b0001: gray_temp = 4'b0001;
      4'b0010: gray_temp = 4'b0011;
      4'b0011: gray_temp = 4'b0010;
      4'b0100: gray_temp = 4'b0110;
      4'b0101: gray_temp = 4'b0111;
      4'b0110: gray_temp = 4'b0101;
      4'b0111: gray_temp = 4'b0100;
      4'b1000: gray_temp = 4'b1100;
      4'b1001: gray_temp = 4'b1101;
      4'b1010: gray_temp = 4'b1111;
      4'b1011: gray_temp = 4'b1110;
      4'b1100: gray_temp = 4'b1010;
      4'b1101: gray_temp = 4'b1011;
      4'b1110: gray_temp = 4'b1001;
      4'b1111: gray_temp = 4'b1000;
    endcase
    gray_out <= gray_temp;
  end

endmodule

module digital_clock (
  input clk_in,
  input rst,
  input en,
  output reg clk_out,
  output reg clk_out_b
);

reg [2:0] counter;

always @(posedge clk_in or posedge rst) begin
  if (rst) begin
    counter <= 3'b0;
    clk_out <= 1'b0;
    clk_out_b <= 1'b0;
  end else begin
    if (en) begin
      counter <= counter + 1;
      if (counter == 3'b011) begin
        clk_out <= ~clk_out;
      end
      if (counter == 3'b010) begin
        clk_out_b <= ~clk_out_b;
      end
    end
  end
end

endmodule

module top_module (
    input clk,                 // Clock
    input rst_n,               // Synchronous active-low reset
    input [7:0] data_in,       // 8-bit input data
    output reg [7:0] q         // 8-bit output data
);

    // Internal signals
    wire [23:0] shift_out;
    wire [9:0] accu_out;
    reg [7:0] shift_in;
    reg valid_a;
    wire ready_a;
    reg ready_b;

    // Instantiate modules
    shift_register shift_reg (
        .clk(clk),
        .d(shift_in),
        .q(shift_out)
    );

    accu accumulator (
        .clk(clk),
        .rst_n(rst_n),
        .data_in(shift_out[7:0]),
        .valid_a(valid_a),
        .ready_b(ready_b),
        .ready_a(ready_a),
        .valid_b(),
        .data_out(accu_out)
    );

    // Assign shift_in
    always @ (posedge clk) begin
        if (!rst_n) begin
            shift_in <= 8'b0;
        end else begin
            shift_in <= data_in;
        end
    end

    // Assign valid_a and ready_b
    always @ (posedge clk) begin
        if (!rst_n) begin
            valid_a <= 1'b0;
            ready_b <= 1'b0;
        end else begin
            valid_a <= 1'b1;
            ready_b <= ready_a;
        end
    end

    // Assign q
    always @ (posedge clk) begin
        if (!rst_n) begin
            q <= 8'b0;
        end else begin
            q <= accu_out[9:2];
        end
    end

endmodule

module shift_register (
    input clk,         // Clock
    input [7:0] d,     // 8-bit input data
    output [23:0] q    // 24-bit output data
);
    reg [23:0] shift_reg;

    always @ (posedge clk) begin
        shift_reg <= {shift_reg[15:0], d};
    end

    assign q = shift_reg;

endmodule

module accu(
    input clk,          // Clock
    input rst_n,        // Synchronous active-low reset
    input [7:0] data_in,// 8-bit input data
    input valid_a,      // Valid signal for input data
    input ready_b,      // Ready signal from downstream module
    output ready_a,     // Ready signal for input data
    output reg valid_b, // Valid signal for output data
    output reg [9:0] data_out // 10-bit output data
);
    reg [31:0] accu_reg;
    reg [1:0] count;

    always @ (posedge clk) begin
        if (!rst_n) begin
            accu_reg <= 32'b0;
            count <= 2'b0;
            valid_b <= 1'b0;
        end else begin
            if (valid_a && ready_b) begin
                accu_reg <= accu_reg + data_in;
                count <= count + 1;
                if (count == 2) begin
                    valid_b <= 1'b1;
                    data_out <= accu_reg[31:22];
                    accu_reg <= accu_reg[21:0];
                    count <= 2'b0;
                end
            end
        end
