module glitch_free_clock_mux (
  input [n-1:0] clk,
  input [n-2:0] sel,
  input rst,
  output clk_out
);

parameter n = 4; // number of input clock signals

reg [n-2:0] sel_sync; // synchronized select signals
reg [n-1:0] clk_sync; // synchronized input clock signals
reg glitch_filtered; // glitch-filtered clock signal

// D flip-flops for synchronizing input clock signals
always @(posedge clk[0] or negedge rst) begin
  if (~rst) begin
    clk_sync <= 0;
  end else begin
    clk_sync <= {clk_sync[0], clk[1:n-1]};
  end
end

// D flip-flops for synchronizing select signals
always @(posedge clk[0] or negedge rst) begin
  if (~rst) begin
    sel_sync <= 0;
  end else begin
    sel_sync <= {sel_sync[0], sel};
  end
end

// AND gates for generating select signals
genvar i;
generate
  for (i = 0; i < n-1; i = i+1) begin : and_gate
    assign sel_sync[i] = sel_sync[i] & sel_sync[i+1];
  end
endgenerate

// Glitch filter for removing glitches from selected clock signal
always @(posedge clk[0] or negedge rst) begin
  if (~rst) begin
    glitch_filtered <= 0;
  end else begin
    glitch_filtered <= sel_sync[0];
  end
end

// D flip-flop for synchronizing output clock signal
always @(posedge clk[0] or negedge rst) begin
  if (~rst) begin
    clk_out <= 0;
  end else begin
    clk_out <= glitch_filtered;
  end
end

endmodule

