module SRL_FIFO #(parameter                    FIFO_SIZE  = 4,   // size in log scale, 4 for 16 entry
                  parameter                    FIFO_WIDTH = 64)  // fifo width in bit
                 (input  wire                  CLK,
                  input  wire                  RST,
                  input  wire                  enq,
                  input  wire                  deq,
                  input  wire [FIFO_WIDTH-1:0] din,
                  output wire [FIFO_WIDTH-1:0] dot,
                  output wire                  emp,
                  output wire                  full,
                  output reg  [FIFO_SIZE:0]    cnt);

  reg  [FIFO_SIZE-1:0]  head;
  reg  [FIFO_WIDTH-1:0] mem [(1<<FIFO_SIZE)-1:0];

  assign emp  = (cnt==0);
  assign full = (cnt==(1<<FIFO_SIZE));
  assign dot  = mem[head];

  always @(posedge CLK) begin
    if (RST) begin
      cnt  <= 0;
      head <= {(FIFO_SIZE){1'b1}};
    end else begin
      case ({enq, deq})
        2'b01: begin cnt <= cnt - 1; head <= head - 1; end
        2'b10: begin cnt <= cnt + 1; head <= head + 1; end
      endcase
    end
  end

  integer i;
  always @(posedge CLK) begin
    if (enq) begin
      mem[0] <= din;
      for (i=1; i<(1<<FIFO_SIZE); i=i+1) mem[i] <= mem[i-1];
    end
  end

endmodule

module glitch_filter (
  input signal_in,
  output signal_out
);

parameter glitch_duration = 4; // minimum pulse duration

reg [glitch_duration-1:0] delay_line;
reg filtered_signal;

always @(posedge signal_in) begin
  delay_line <= {delay_line[glitch_duration-2:0], signal_in};
  if (delay_line[0] == 1'b1 && delay_line[glitch_duration-1] == 1'b0) begin
    filtered_signal <= delay_line[glitch_duration-2];
  end else begin
    filtered_signal <= signal_in;
  end
end

assign signal_out = filtered_signal;

endmodule

module crc16(clk, rst, en, din, dout);

input clk, rst, en;
input [7:0] din;
output [15:0] dout;

reg [15:0] crc;
reg [7:0] data;
reg [7:0] i;

always @(posedge clk) begin
    if (rst) begin
        crc <= 16'h0000;
        i <= 0;
    end
    else if (en) begin
        data <= din;
        for (i = 0; i < 8; i = i + 1) begin
            if ((crc & 16'h8000) == 16'h8000) begin
                crc <= (crc << 1) ^ 16'h1021;
            end
            else begin
                crc <= crc << 1;
            end
            if ((data & 1) == 1) begin
                crc <= crc ^ 16'h8005;
            end
            data <= data >> 1;
        end
    end
end

assign dout = crc;

endmodule

