module pulse_generator(
    input clk,
    input reset,
    input in,
    output p,
    output reg l
);

    reg [18:0] r;
    reg [1:0] state;
    parameter IDLE = 2'b00, COUNTING = 2'b01, PULSE = 2'b10;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            r <= 0;
            l <= 0;
            state <= IDLE;
        end else begin
            case(state)
                IDLE: begin
                    if (in) begin
                        state <= COUNTING;
                        r <= 0;
                        l <= 1;
                    end else begin
                        l <= 0;
                    end
                end
                COUNTING: begin
                    if (r == 250000) begin
                        state <= PULSE;
                        r <= 0;
                        p <= 1;
                    end else begin
                        r <= r + 1;
                        l <= 1;
                        p <= 0;
                    end
                end
                PULSE: begin
                    if (in) begin
                        state <= COUNTING;
                        r <= 0;
                        p <= 0;
                        l <= 1;
                    end else begin
                        l <= 0;
                        p <= 1;
                    end
                end
            endcase
        end
    end

endmodule

module video_generator(
  input PixelClk,
  input PixelClk2,
  input [8:0] BufferAddr,
  input [15:0] BufferData,
  input BufferWrite,
  input [7:0] PalAddr,
  input [31:0] PalData,
  input PalWrite,
  input [5:0] XOffsetData,
  input [9:0] YOffsetData,
  input OffsetWrite,
  output reg [7:0] Red,
  output reg [7:0] Green,
  output reg [7:0] Blue,
  output reg HSync,
  output reg VSync,
  output reg VideoEnable,
  output reg [10:0] GetRow,
  output reg StartBuffer
);

  `define H_SYNC_START     32
  `define H_SYNC_STOP      129
  `define H_VIDEO_START    258
  `define H_VIDEO_STOP     1217
  `define V_SYNC_START     1
  `define V_SYNC_STOP      4
  `define V_VIDEO_START    20
  `define V_VIDEO_STOP     559

  integer Row;
  integer Col;
  reg [23:0] Pixel;
  wire [31:0] RowBufOut;
  wire [31:0] PaletteOut;
  reg [9:0] ReadBufAddr;
  reg [5:0] XOffset;
  reg [9:0] YOffset;

  initial begin
    Row = 0;
    Col = 0;
    HSync = 0;
    VSync = 0;
    VideoEnable = 0;
    GetRow = 11'h000;
    StartBuffer = 0;
    Pixel = 24'h000000;
    ReadBufAddr = 10'h000;
    Red = 8'h00;
    Green = 8'h00;
    Blue = 8'h00;
    XOffset = 0;
    YOffset = 0;
  end

  always @(posedge PixelClk2) begin
    if (OffsetWrite == 1) begin
      XOffset = XOffsetData;
      YOffset = YOffsetData;
    end
  end

  always @(negedge PixelClk2) begin
    Pixel = PaletteOut[23:0];
    ReadBufAddr = ((Col < (`H_VIDEO_START - 2)) ? 10'h000 : (Col - (`H_VIDEO_START - 2))) + XOffset;
  end

  always @(posedge PixelClk) begin
    if ((StartBuffer == 1) && (BufferWrite == 1))
      StartBuffer = 0;
    if (Col < `H_VIDEO_STOP)
      Col = Col + 1;
    else begin
      Col = 0;
      if (Row < `V_VIDEO_STOP) begin
        Row = Row + 1;
        if (Row >= `V_VIDEO_START) begin
          GetRow = (Row - `V_VIDEO_START) + YOffset;
          StartBuffer = 1;
        end
      end
      else
        Row = 0;
    end
    HSync = ((Col < `H_SYNC_START) || (Col > `H_SYNC_STOP)) ? 0 : 1;
    VSync = ((Row < `V_SYNC_START) || (Row > `V_SYNC_STOP)) ? 0 : 1;
    if ((Col < `H_VIDEO_START) || (Row < `V_VIDEO_START)) begin
