module Calculator(input [31:0] num1, input [31:0] num2, output reg [31:0] result, output reg [31:0] quotient, output reg [31:0] remainder, output reg overflow);

  reg [32:0] temp; // Temporary register for multiplication and division
  reg [63:0] temp64; // Temporary register for signed multiplication
  reg [31:0] abs_num1, abs_num2; // Absolute values of num1 and num2
  reg [31:0] sign_num1, sign_num2; // Sign bits of num1 and num2
  reg [31:0] sign_result; // Sign bit of the result
  reg [31:0] abs_result; // Absolute value of the result
  reg [31:0] abs_quotient; // Absolute value of the quotient
  reg [31:0] abs_remainder; // Absolute value of the remainder
  reg [31:0] abs_temp; // Absolute value of the temporary register
  reg [31:0] abs_temp64; // Absolute value of the temporary 64-bit register
  reg [31:0] abs_num1_shifted; // Absolute value of num1 shifted for division
  reg [31:0] abs_quotient_shifted; // Absolute value of the quotient shifted for division
  reg [31:0] i; // Loop counter

  // Determine the sign of num1 and num2
  assign sign_num1 = num1[31];
  assign sign_num2 = num2[31];

  // Determine the absolute value of num1 and num2
  assign abs_num1 = (sign_num1) ? (~num1 + 1) : num1;
  assign abs_num2 = (sign_num2) ? (~num2 + 1) : num2;

  // Addition
  always @(*) begin
    if (sign_num1 == sign_num2) begin
      temp = abs_num1 + abs_num2;
      sign_result = sign_num1;
      if (temp[32]) begin
        overflow = 1;
        result = 0;
      end
      else begin
        overflow = 0;
        result = (sign_num1) ? (~temp + 1) : temp[31:0];
      end
    end
    else begin
      temp = abs_num1 - abs_num2;
      if (temp[32]) begin
        overflow = 1;
        result = 0;
      end
      else begin
        overflow = 0;
        sign_result = (temp[31]) ? 1 : 0;
        result = (sign_result) ? (~temp + 1) : temp[31:0];
      end
    end
  end

  // Subtraction
  always @(*) begin
    if (sign_num1 != sign_num2) begin
      temp = abs_num1 + abs_num2;
      sign_result = sign_num1;
      if (temp[32]) begin
        overflow = 1;
        result = 0;
      end
      else begin
        overflow = 0;
        result = (sign_num1) ? (~temp + 1) : temp[31:0];
      end
    end
    else begin
      temp = abs_num1 - abs_num2;
      if (temp[32]) begin
        overflow = 1;
        result = 0;
      end
      else begin
        overflow = 0;
        sign_result = (temp[31]) ? 1 : 0;
        result = (sign_result) ? (~temp + 1) : temp[31:0];
      end
    end
  end

  // Multiplication
  always @(*) begin
    temp64 = abs_num1 * abs_num2;
    if (temp64[63]) begin
      overflow = 1;
      result = 0;
    end
    else begin
      overflow = 0;
      abs_result = temp64[31:0];
      sign_result = (sign_num1 != sign_num2) ? 1 : 0;
      result = (sign_result) ? (~abs_result + 1) : abs_result;
    end
  end

  // Division
  always @(*) begin
    if (abs_num2 == 0) begin
      overflow = 1;
      result = 0;
      quotient = 0;
      remainder = 0;
    end
    else begin
      abs_num1_shifted = abs_num1;
      abs_quotient_shifted = 0;
      for (i = 31; i >= 0; i = i - 1) begin
        abs_temp = abs_num1_shifted - (abs_num2 << i);
        if (abs_temp >= 0) begin
          abs_num1_shifted = abs_temp;
          abs_quotient_shifted = abs_quotient_shifted | (1 << i);
        end
      end
      abs_quotient = abs_quotient_shifted;
      abs_remainder = abs_num1_shifted;
      sign_result = (sign_num1 != sign_num2) ? 1 : 0;
      quotient = (sign_result) ? (~abs_quotient + 1) : abs_quotient;
      remainder = (sign_num1) ? (~abs_remainder + 1) : abs_remainder;
    end
  end

endmodule

