module vending_machine (
    input clk,
    input reset,
    input [1:0] coin,
    input [1:0] product_sel,
    input dispense,
    output reg product_dispensed,
    output reg [7:0] product_price,
    output reg [7:0] change
);

    parameter IDLE = 3'b000;
    parameter Q1 = 3'b001;
    parameter DOLLAR = 3'b010;
    parameter SODA = 3'b011;
    parameter WATER = 3'b100;
    parameter CHIPS = 3'b101;
    parameter CANDY = 3'b110;
    parameter DISPENSE = 3'b111;

    reg [2:0] state, next_state;
    reg [7:0] balance;

    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            product_dispensed <= 0;
            product_price <= 0;
            change <= 0;
            balance <= 0;
        end else begin
            state <= next_state;
            case(state)
                IDLE: begin
                    if (coin == 2'b01) begin
                        next_state = Q1;
                        balance = 25;
                    end else if (coin == 2'b10) begin
                        next_state = DOLLAR;
                        balance = 100;
                    end else begin
                        next_state = IDLE;
                    end
                end
                Q1: begin
                    if (coin == 2'b01) begin
                        next_state = DOLLAR;
                        balance = 100;
                    end else if (coin == 2'b10) begin
                        next_state = Q1;
                        balance = balance + 25;
                    end else begin
                        next_state = Q1;
                    end
                end
                DOLLAR: begin
                    if (product_sel == 2'b00) begin
                        next_state = SODA;
                        product_price = 50;
                    end else if (product_sel == 2'b01) begin
                        next_state = WATER;
                        product_price = 75;
                    end else if (product_sel == 2'b10) begin
                        next_state = CHIPS;
                        product_price = 100;
                    end else if (product_sel == 2'b11) begin
                        next_state = CANDY;
                        product_price = 25;
                    end else begin
                        next_state = DOLLAR;
                    end
                end
                SODA: begin
                    if (dispense) begin
                        next_state = DISPENSE;
                        product_dispensed = 1;
                        change = balance - product_price;
                        balance = 0;
                    end else begin
                        next_state = SODA;
                    end
                end
                WATER: begin
                    if (dispense) begin
                        next_state = DISPENSE;
                        product_dispensed = 1;
                        change = balance - product_price;
                        balance = 0;
                    end else begin
                        next_state = WATER;
                    end
                end
                CHIPS: begin
                    if (dispense) begin
                        next_state = DISPENSE;
                        product_dispensed = 1;
                        change = balance - product_price;
                        balance = 0;
                    end else begin
                        next_state = CHIPS;
                    end
                end
                CANDY: begin
                    if (dispense) begin
                        next_state = DISPENSE;
                        product_dispensed = 1;
                        change = balance - product_price;
                        balance = 0;
                    end else begin
                        next_state = CANDY;
                    end
                end
                DISPENSE: begin
                    next_state = IDLE;
                    product_dispensed = 0;
                    product_price = 0;
                end
            endcase
        end
    end

endmodule

