module multiplier_16bit (
  input clk,
  input reset, // Synchronous active-high reset
  input [7:0] a,
  input [7:0] b,
  output [15:0] product
);

  wire [7:0] a_lsb = a[3:0];
  wire [7:0] a_msb = a[7:4];
  wire [7:0] b_lsb = b[3:0];
  wire [7:0] b_msb = b[7:4];

  wire [7:0] adder1_out;
  wire [7:0] adder2_out;

  wire carry1;
  wire carry2;

  // Instantiate two 8-bit adder modules
  adder_8bit adder1(.clk(clk), .reset(reset), .a(a_lsb), .b(b_lsb), .carry_in(1'b0), .sum(adder1_out), .carry_out(carry1));
  adder_8bit adder2(.clk(clk), .reset(reset), .a(a_msb), .b(b_msb), .carry_in(carry1), .sum(adder2_out), .carry_out(carry2));

  // Multiplexers to select the correct bits for each adder input
  wire [7:0] a_lsb_sel;
  wire [7:0] a_msb_sel;
  wire [7:0] b_lsb_sel;
  wire [7:0] b_msb_sel;

  assign a_lsb_sel = {4'b0000, a_lsb};
  assign a_msb_sel = {4'b0000, a_msb};
  assign b_lsb_sel = {4'b0000, b_lsb};
  assign b_msb_sel = {4'b0000, b_msb};

  // Multiplexers to select the correct adder output bits for the final product
  wire [7:0] p1_sel;
  wire [7:0] p2_sel;
  wire [7:0] p3_sel;
  wire [7:0] p4_sel;

  assign p1_sel = {4'b0000, adder1_out};
  assign p2_sel = {4'b0000, adder2_out};
  assign p3_sel = {4'b0000, adder1_out};
  assign p4_sel = {4'b0000, adder2_out};

  // Final product calculation
  assign product = {p1_sel, p2_sel, p3_sel, p4_sel};

endmodule

// 8-bit adder module with active-high synchronous reset
module adder_8bit (
  input clk,
  input reset, // Synchronous active-high reset
  input [7:0] a,
  input [7:0] b,
  input carry_in,
  output [7:0] sum,
  output carry_out
);

  reg [7:0] sum_reg;
  reg carry_out_reg;

  always @(posedge clk) begin
    if (reset) begin
      sum_reg <= 8'b0;
      carry_out_reg <= 1'b0;
    end else begin
      {carry_out_reg, sum_reg} <= a + b + carry_in;
    end
  end

  assign sum = sum_reg;
  assign carry_out = carry_out_reg;

endmodule

module top_module (
  input               clk,
  input               reset,
  input               a,
  output              red,
  output              yellow,
  output              green
);

  // Implement the NOR gate using NAND gates
  wire nand_out;
  assign nand_out = ~(a & a);
  wire nor_out;
  assign nor_out = ~(nand_out);

  // Implement the DLL-based edge detection module
  reg [1:0] delay_reg;
  wire rise;
  wire down;
  dll_edge_detector edge_detector (
    .clk(clk),
    .reset(reset),
    .data(a),
    .delay(delay_reg[1:0]),
    .rise(rise),
    .down(down)
  );

  // Implement the final output signal that controls the traffic light
  assign red = (nor_out & down);
  assign yellow = ~(nor_out);
  assign green = (nor_out & rise);

