// DLL-based edge detection module
module dll_edge_detector (
  input               clk,
  input               reset,
  input               data,
  input [1:0]         delay,
  output              rise,
  output              down
);

  reg [1:0] delay_reg;
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      delay_reg <= 2'b00;
    end else begin
      delay_reg <= {delay_reg[0], data};
    end
  end

  assign rise = (delay_reg[1] & ~delay_reg[0]);
  assign down = (~delay_reg[1] & delay_reg[0]);

endmodule

