    assign rising_edge = (shift_reg ^ {shift_reg[0], shift_reg[7:1]}) & {shift_reg[0], shift_reg[7:1]};

endmodule

module functional_module (
    input [7:0] upper_byte, // 8-bit input vector for the upper byte
    input [7:0] lower_byte, // 8-bit input vector for the lower byte
    input select, // Select input to choose between upper and lower byte
    output [7:0] anyedge // Output vector from the functional module
);

    assign anyedge = select ? rising_edge_detector_inst.rising_edge : upper_byte;
    assign anyedge = select ? rising_edge_detector_inst.rising_edge : lower_byte;

endmodule

module Arbiter (
  input [n-1:0] in,
  output reg out
);

parameter n = 4; // number of input signals
parameter p = 2; // number of priority levels

// Define the priority levels
// Each priority level is associated with a set of input signals
parameter [n-1:0] priority_0 = 4'b1100; // input signals with priority 0
parameter [n-1:0] priority_1 = 4'b0011; // input signals with priority 1

// Define the priority rules
// If two or more input signals have the same priority, use round-robin
reg [1:0] round_robin = 2'b00;

always @(*) begin
  if (priority_0 & in) begin
    case (round_robin)
      2'b00: out = in[0];
      2'b01: out = in[1];
      2'b10: out = in[2];
      2'b11: out = in[3];
    endcase
    round_robin = round_robin + 1;
  end else if (priority_1 & in) begin
    case (round_robin)
      2'b00: out = in[0];
      2'b01: out = in[1];
      2'b10: out = in[2];
      2'b11: out = in[3];
    endcase
    round_robin = round_robin + 1;
  end else begin
    out = 1'b0;
  end
end

endmodule

module decoder (
    input [7:0] in,
    output [15:0] out
);

// First stage of pipeline
reg [3:0] stage1_out;
always @ (in) begin
    case (in[7:6])
        2'b00: stage1_out = 4'b0001;
        2'b01: stage1_out = 4'b0010;
        2'b10: stage1_out = 4'b0100;
        2'b11: stage1_out = 4'b1000;
    endcase
end

// Second stage of pipeline
reg [3:0] stage2_out;
always @ (in) begin
    case (in[5:4])
        2'b00: stage2_out = 4'b0001;
        2'b01: stage2_out = 4'b0010;
        2'b10: stage2_out = 4'b0100;
        2'b11: stage2_out = 4'b1000;
    endcase
end

// Third stage of pipeline
reg [7:0] stage3_out;
always @ (in) begin
    case (in[3:0])
        4'b0000: stage3_out = 8'b00000001;
        4'b0001: stage3_out = 8'b00000010;
        4'b0010: stage3_out = 8'b00000100;
        4'b0011: stage3_out = 8'b00001000;
        4'b0100: stage3_out = 8'b00010000;
        4'b0101: stage3_out = 8'b00100000;
        4'b0110: stage3_out = 8'b01000000;
        4'b0111: stage3_out = 8'b10000000;
        4'b1000: stage3_out = 8'b00000000;
        4'b1001: stage3_out = 8'b00000000;
        4'b1010: stage3_out = 8'b00000000;
        4'b1011: stage3_out = 8'b00000000;
        4'b1100: stage3_out = 8'b00000000;
        4'b1101: stage3_out = 8'b00000000;
        4'b1110: stage3_out = 8'b00000000;
        4'b1111: stage3_out = 8'b00000000;
    endcase
end

// Output stage
always @ (in) begin
    out[0] = stage1_out[0] & stage2_out[0] & stage3_out[0];
    out[1] = stage1_out[0] & stage2_out[0] & stage3_out[1];
    out[2] = stage1_out[0] & stage2_out[0] & stage3_out[2];
    out[3] = stage1_out[0] & stage2_out[0] & stage3_out[3];
    out[4] = stage1_out[0] & stage2_out[0] & stage3_out[4];
    out[5] = stage1_out[0] & stage2_out[0] & stage3_out[5];
    out[6] = stage1_out[0] & stage2_out[0] & stage3_out[6];
    out[7] = stage1_out[0] & stage2_out[0] & stage3_out[7];
    out[8] = stage1_out[1] & stage2_out[1] & stage3_out[0];
    out[9] = stage1_out[1] & stage2_out[1] & stage3_out[1];
    out[10] = stage1_out[1] & stage2_out[1] & stage3_out[2];
    out[11] = stage1_out[1] & stage2_out[1] & stage3_out[3];
    out[12] = stage1_out[1] & stage2_out[1] & stage3_out[4];
    out[13] = stage1_out[1] & stage2_out[1] & stage3_out[5];
    out[14] = stage1_out[1] & stage2_out[1] & stage3_out[6];
    out[15] = stage1_out[1] & stage2_out[1] & stage3_out[7];
end

endmodule

module operation (
    input [10*9-1:0] data_bus,
    input clk,
    input rst,
    input refresh,
    output reg [10-1:0] out
);

reg [9:0] pixel[2:0][2:0];
reg [1:0] tag;

integer i, j, k;

always @(posedge clk) begin
    if (rst | refresh) begin
        tag <= 0;
        for (i = 0; i < 3; i = i + 1) begin
            for (j = 0; j < 3; j = j + 1) begin
                pixel[i][j] <= 0;
            end
        end
    end
    else begin
        for (i = 0; i < 3; i = i + 1) begin
            for (j = 0; j < 3; j = j + 1) begin
                pixel[i][j] <= data_bus[(i*3+j)*10+9: (i*3+j)*10];
            end
        end
        tag <= pixel[1][1][1:0];
        if (tag == 2'd0) begin
            out <= {tag, pixel[1][1][7:0]};
        end
        else if (tag == 2'd1 || tag == 2'd2) begin
            out <= {tag, {(($unsigned(pixel[0][0])+pixel[0][1]+pixel[0][2]+
                            pixel[1][0]+pixel[1][1]+pixel[1][2]+
                            pixel[2][0]+pixel[2][1]+pixel[2][2])/9)}};
        end
        else if (tag == 2'd3) begin
            out <= {2'd0, pixel[1][1][7:0]};
        end
    end
end

endmodule

module control_unit(
    input [1:0] ctrl,
    input [3:0] data_in,
    input load,
    input clk,
    output reg [3:0] data_out,
    output reg valid
);

reg [3:0] reg_data;

always @(posedge clk) begin
    if (load) begin
        reg_data <= data_in;
    end else begin
        case(ctrl)
            2'b00: begin
                data_out <= reg_data;
                valid <= 1'b1;
            end
            2'b01: begin
                data_out <= ~reg_data;
                valid <= 1'b1;
            end
            2'b10: begin
                data_out <= data_in;
                valid <= 1'b1;
            end
            2'b11: begin
                data_out <= ~data_in;
                valid <= 1'b1;
            end
            default: begin
                data_out <= 4'b0;
                valid <= 1'b0;
            end
        endcase
    end
end

initial begin
    reg_data = 4'b0;
end

endmodule

module min_module (
    input [7:0] a, b, c, d, // Inputs to find minimum
    output reg [7:0] min // Output minimum value
);

reg [7:0] ab_min, cd_min, abcd_min;

assign ab_min = (a < b) ? a : b;
assign cd_min = (c < d) ? c : d;
assign abcd_min = (ab_min < cd_min) ? ab_min : cd_min;

always @(*) begin
    min = abcd_min;
end

endmodule

module add_module (
    input [7:0] x, y, // Inputs to add
    output reg [7:0] sum, // Output sum
    output reg overflow // Output overflow
);

wire [7:0] x_plus_y, x_minus_y, y_minus_x;

assign x_plus_y = x + y;
assign x_minus_y = x - y;
assign y_minus_x = y - x;

always @(*) begin
    if (x[7] == y[7] && x[7] != x_plus_y[7]) begin
        overflow = 1;
        sum = (x[7] == 1) ? -128 : 127;
    end else if (x[7] == 1 && y[7] == 1) begin
        overflow = (x_minus_y[7] == 0) ? 1 : 0;
        sum = x_minus_y;
    end else if (x[7] == 0 && y[7] == 0) begin
        overflow = (x_plus_y[7] == 1) ? 1 : 0;
        sum = x_plus_y;
    end else begin
        overflow = 0;
        sum = x_plus_y;
    end
end

endmodule

module top_module (
    input [7:0] a, b, c, d, // Inputs to the minimum module
    input [7:0] x, y, // Inputs to the addition module
    input select, // Selects which module to use as input to the functional module
    output [7:0] sum, // Output of the functional module
    output overflow // Output of the addition module indicating overflow
);

wire [7:0] min_out, add_out;

min_module min_inst (
    .a(a),
    .b(b),
    .c(c),
    .d(d),
    .min(min_out)
);

add_module add_inst (
    .x(x),
    .y(y),
    .sum(add_out),
    .overflow(overflow)
);

always @(*) begin
    if (select == 1'b1 && overflow == 1'b0) begin
        sum = add_out;
    end else begin
        sum = min_out;
    end
end

endmodule

