module fsm_3bit_pattern_detection (
  input clk,
  input reset,
  input [9:0] data,
  output reg match
);

  parameter IDLE = 2'b00;
  parameter MATCH1 = 2'b01;
  parameter MATCH2 = 2'b10;
  parameter MATCH3 = 2'b11;

  reg [1:0] state;
  reg [2:0] pattern;

  always @(posedge clk) begin
    if (reset) begin
      state <= IDLE;
      pattern <= 3'b0;
      match <= 1'b0;
    end
    else begin
      case (state)
        IDLE: begin
          if (data[9:7] == 3'b001) begin
            state <= MATCH1;
            pattern <= 3'b001;
            match <= 1'b1;
          end
          else begin
            state <= IDLE;
            pattern <= 3'b0;
            match <= 1'b0;
          end
        end
        MATCH1: begin
          if (data[9:7] == 3'b010 && pattern == 3'b001) begin
            state <= MATCH2;
            pattern <= 3'b010;
          end
          else begin
            state <= IDLE;
            pattern <= 3'b0;
            match <= 1'b0;
          end
        end
        MATCH2: begin
          if (data[9:7] == 3'b011 && pattern == 3'b010) begin
            state <= MATCH3;
            pattern <= 3'b011;
          end
          else begin
            state <= IDLE;
            pattern <= 3'b0;
            match <= 1'b0;
          end
        end
        MATCH3: begin
          state <= IDLE;
          pattern <= 3'b0;
          match <= 1'b0;
        end
      endcase
    end
  end

endmodule

module selection_vector (
