module top_module (
    input wire clk,
    input wire reset,
    input wire [2:0] input1_vec,
    output wire [2:0] input1_outv,
    output wire input1_o2,
    output wire input1_o1,
    output wire input1_o0,
    input wire [2:0] input2_a,
    input wire [2:0] input2_b,
    output wire [2:0] out_final
);

    reg [2:0] not_output;
    reg [2:0] out_xor;
    reg [2:0] out_and;
    reg [2:0] out_or;

    assign input1_outv = input1_vec;

    assign input1_o2 = input1_vec[2];
    assign input1_o1 = input1_vec[1];
    assign input1_o0 = input1_vec[0];

    always @(posedge clk) begin
        if (reset) begin
            not_output <= 3'b000;
            out_xor <= 3'b000;
            out_and <= 3'b000;
            out_or <= 3'b000;
        end else begin
            not_output <= ~{input2_a[2], input2_a[1], input2_a[0]};
            out_xor <= input2_a ^ input2_b;
            out_and <= input2_a & input2_b;
            out_or <= input2_a | input2_b;
        end
    end

    assign out_final = (input1_o2) ? not_output :
                       (input1_o1) ? out_xor :
                       (input1_o0) ? out_or :
                       out_and;

endmodule

module uart(
   input wire clk,
   input wire resetq,

   output wire uart_busy,       // High means UART is transmitting
   output reg uart_tx,          // UART transmit wire

   input wire uart_wr_i,        // Raise to transmit byte
   input wire [7:0] uart_dat_i
);

  reg [3:0] bitcount;           // 0 means idle, so this is a 1-based counter
  reg [8:0] shifter;

  assign uart_busy = |bitcount;
  wire sending = |bitcount;

  wire ser_clk;

  baudgen _baudgen(
    .clk(clk),
    .ser_clk(ser_clk));

  always @(negedge resetq or posedge clk)
  begin
    if (!resetq) begin
      uart_tx <= 1;
      bitcount <= 0;
      shifter <= 0;
    end else begin
      if (uart_wr_i) begin
        shifter <= { 1'b0, uart_dat_i, 1'b1 };
        bitcount <= 10;    // 1 start, 8 data, 1 stop
      end else if (ser_clk & sending) begin
        uart_tx <= shifter[0];
        shifter <= { shifter[7:1], 1'b1 };
        bitcount <= bitcount - 1;
      end else if (!sending) begin
        uart_tx <= 1;
      end
    end
  end

endmodule

module fifo (
    input clk,
    input rst,
    input wr_en,
    input [3:0] wr_data,
    input rd_en,
    output [3:0] rd_data,
    output full,
    output empty
);

reg [3:0] fifo [0:3];
reg [1:0] wr_ptr;
reg [1:0] rd_ptr;
wire [1:0] next_wr_ptr;
wire [1:0] next_rd_ptr;

assign full = (next_wr_ptr == rd_ptr);
assign empty = (wr_ptr == rd_ptr);

// Write pointer logic
always @ (posedge clk) begin
    if (rst) begin
        wr_ptr <= 2'b00;
    end else if (wr_en && !full) begin
        wr_ptr <= next_wr_ptr;
    end
end

assign next_wr_ptr = (wr_ptr == 2'b11) ? 2'b00 : wr_ptr + 1;

// Read pointer logic
always @ (posedge clk) begin
    if (rst) begin
        rd_ptr <= 2'b00;
    end else if (rd_en && !empty) begin
        rd_ptr <= next_rd_ptr;
    end
end

assign next_rd_ptr = (rd_ptr == 2'b11) ? 2'b00 : rd_ptr + 1;

// FIFO memory
always @ (posedge clk) begin
    if (rst) begin
        fifo <= 0;
    end else if (wr_en && !full) begin
        fifo[wr_ptr] <= wr_data;
    end
end

assign rd_data = fifo[rd_ptr];

endmodule

module top_module (
