module gray_converter (
    input [3:0] binary_in,
    input gray_ctrl,
    input rst_n,
    output reg [3:0] gray_out
);

    always @ (posedge rst_n or posedge gray_ctrl or posedge binary_in) begin
        if(!rst_n) begin
            gray_out <= 4'b0000;
        end else if(gray_ctrl) begin
            gray_out <= binary_in ^ (binary_in >> 1);
        end else begin
            gray_out <= {gray_out[2:0], 1'b0} ^ (gray_out & 1'b1111);
        end
    end

endmodule

