module shift_register(
    input clk,
    input areset,  // async active-high reset to zero
    input load,
    input ena,
    input [3:0] data,
    output reg [3:0] q);

    reg [3:0] shift_reg;
    wire [3:0] shifted_output;

    // Shift register
    always @(posedge clk or negedge areset) begin
        if (areset == 0) begin
            shift_reg <= 4'b0;
        end else if (ena == 1) begin
            shift_reg <= {shift_reg[2:0], shift_reg[3]};
        end
    end

    // Multiplexer
    assign shifted_output = {shift_reg[2:0], shift_reg[3]};
    always @(posedge clk or negedge areset) begin
        if (areset == 0) begin
            q <= 4'b0;
        end else if (load == 1 && ena == 1) begin
            q <= data;
        end else if (load == 0 && ena == 1) begin
            q <= shifted_output;
        end
    end

endmodule

