module async_reset_release (
  input reset, // asynchronous reset signal
  input clk, // clock signal
  input enable, // enable signal
  output out // output signal
);

parameter delay = 10; // delay time in clock cycles

reg [7:0] counter; // counter to count delay time

always @(posedge clk or negedge reset) begin
  if (reset == 1'b0) begin // reset is active
    out <= 1'b0;
    counter <= 0;
  end else begin // reset is released
    if (counter < delay) begin // delay period
      out <= 1'b0;
      counter <= counter + 1;
    end else begin // delay period is over
      out <= enable;
    end
  end
end

endmodule

