module CLKSKW(
	input CLKI,
	input [3:0] SKW,
	input RST,
	output reg CLKO
);

	reg [3:0] delay_reg;

	always @(posedge CLKI or posedge RST) begin
		if (RST) begin
			CLKO <= 1'b0;
			delay_reg <= 4'b0;
		end
		else begin
			delay_reg <= {delay_reg[2:0], CLKI};
			if (SKW[3]) begin
				CLKO <= delay_reg[SKW[2:0]] & ~delay_reg[SKW[2:0]-1];
			end
			else begin
				CLKO <= delay_reg[SKW[2:0]] & ~delay_reg[SKW[2:0]+1];
			end
		end
	end

endmodule

module bin2bcd (
    input [4:0] BIN,
    output reg [3:0] BCD0,
    output reg [3:0] BCD1
);

reg [3:0] bcd0_reg, bcd1_reg;
reg [4:0] shift_reg;

always @(*) begin
    shift_reg = {BIN, 1'b0};
end

always @(posedge clk) begin
    bcd0_reg <= 4'b0000;
    bcd1_reg <= 4'b0000;

    for (i = 0; i < 5; i = i + 1) begin
        if (shift_reg[3:0] >= 5) begin
            bcd0_reg = bcd0_reg + 1;
        end

        if (bcd0_reg[3]) begin
            bcd0_reg = bcd0_reg + 3;
        end

        if (bcd1_reg[3]) begin
            bcd1_reg = bcd1_reg + 3;
        end

        bcd0_reg = bcd0_reg << 1;
        bcd1_reg = bcd1_reg << 1;
        bcd0_reg[0] = shift_reg[4];
        bcd1_reg[0] = bcd0_reg[3];
        shift_reg = shift_reg << 1;
    end

    BCD0 <= bcd0_reg;
    BCD1 <= bcd1_reg;
end

endmodule

