module VAD (
  input audio_in,
  output speech_detected
);

parameter fs = 16000; // sampling frequency of the audio signal

reg [15:0] audio_buffer [0:fs-1];
reg [15:0] energy_sum;
reg [15:0] threshold;
reg speech_detected_reg;

integer i;

always @(posedge clk) begin
  // Shift the audio buffer
  for (i = fs-1; i > 0; i = i - 1) begin
    audio_buffer[i] <= audio_buffer[i-1];
  end
  audio_buffer[0] <= audio_in;

  // Calculate the energy of the audio buffer
  energy_sum <= 0;
  for (i = 0; i < fs; i = i + 1) begin
    energy_sum <= energy_sum + audio_buffer[i] * audio_buffer[i];
  end

  // Calculate the threshold
  threshold <= energy_sum / fs;

  // Detect speech
  if (energy_sum > threshold) begin
    speech_detected_reg <= 1;
  end else begin
    speech_detected_reg <= 0;
  end
end

assign speech_detected = speech_detected_reg;

endmodule

module vending_machine(giro, entrada, saida, metais, ledVerde, ledVermelho, display, clock);

input giro, entrada, saida, metais, clock;
output reg [1:0] ledVerde, ledVermelho;
output reg [6:0] display;

localparam A = 3'b000, B = 3'b001, C = 3'b010, D = 3'b011, E = 3'b100;

reg [2:0] estado;
reg [3:0] tmp;

always @(posedge clock) begin
    tmp = {giro, entrada, saida, metais};

    case(estado)
        A: begin
            ledVerde = 2'b00;
            ledVermelho = 2'b00;
            display = 7'b1111001;

            if(tmp == 4'b1100)
                estado = B;
            else if(tmp == 4'b1101 || tmp == 4'b1111)
                estado = C;
            else if(tmp == 4'b1110)
                estado = D;
            else if(tmp == 4'b1010)
                estado = E;
        end

        B: begin
            ledVerde = 2'b01;
            ledVermelho = 2'b00;
            display = 7'b0100100;

            if(tmp == 4'b0000 || tmp == 4'b1000)
                estado = A;
            else if(tmp == 4'b1101)
                estado = C;
            else if(tmp == 4'b1110 || tmp == 4'b1111)
                estado = D;
            else if(tmp == 4'b1010 || tmp == 4'b1011)
                estado = E;
        end

        C: begin
            ledVerde = 2'b00;
            ledVermelho = 2'b01;
            display = 7'b0110000;

            if(tmp == 4'b0100 || tmp == 4'b1100)
                estado = B;
            else if(tmp == 4'b0000 || tmp == 4'b1000)
                estado = A;
            else if(tmp == 4'b0110 || tmp == 4'b1110)
                estado = D;
            else if(tmp == 4'b1010)
                estado = E;
        end

        D: begin
            ledVerde = 2'b10;
            ledVermelho = 2'b10;
            display = 7'b0011001;

            if(tmp == 4'b0111 || tmp == 4'b1111)
                estado = C;
            else if(tmp == 4'b1100)
                estado = B;
            else if(tmp == 4'b1010)
                estado = E;
            else if(tmp == 4'b0000 || tmp == 4'b1000)
                estado = A;
        end

        E: begin
            ledVerde = 2'b00;
            ledVermelho = 2'b00;
            display = 7'b0010010;

            if(tmp == 4'b0000 || tmp == 4'b1000)
                estado = A;
            else if(tmp == 4'b0110 || tmp == 4'b1110)
                estado = D;
            else if(tmp == 4'b1100)
                estado = B;
            else if(tmp == 4'b1101)
                estado = C;
        end

        default: estado = A;
    endcase
end

endmodule

