            case(csr_a[0])
                1'b0: csr_do <= rx_data;
                1'b1: csr_do <= divisor;
            endcase
            if(csr_we) begin
                if(csr_a[0] == 1'b1)
                    divisor <= csr_di[15:0];
            end
        end
    end
end

