module float_arithmetic (
  input [31:0] A,
  input [31:0] B,
  input sel_addsub,
  input sel_muldiv,
  output [31:0] out_result,
  output out_overflow
);

  // Define IEEE 754 format for single-precision floating-point numbers
  parameter EXP_WIDTH = 8;
  parameter FRAC_WIDTH = 23;
  parameter BIAS = 127;
  parameter EXP_MASK = {{(EXP_WIDTH-1){1'b1}}, 1'b0};
  parameter FRAC_MASK = {{(FRAC_WIDTH-1){1'b1}}, 1'b0};

  // Split A and B into sign, exponent, and fraction components
  wire [31:0] A_sign = A[31];
  wire [7:0] A_exp = A[30:23];
  wire [22:0] A_frac = A[22:0];
  wire [31:0] B_sign = B[31];
  wire [7:0] B_exp = B[30:23];
  wire [22:0] B_frac = B[22:0];

  // Calculate the exponent and fraction for the result
  wire [7:0] result_exp;
  wire [23:0] result_frac;
  wire result_sign;

  // Perform addition or subtraction based on sel_addsub
  wire [7:0] addsub_exp;
  wire [23:0] addsub_frac;
  wire addsub_sign;
  assign addsub_sign = sel_addsub ? ~B_sign : B_sign;
  assign addsub_exp = A_exp > B_exp ? A_exp : B_exp;
  assign addsub_frac = A_exp > B_exp ? {A_frac, 1'b0} + {B_frac, {A_exp-B_exp-1{1'b0}}, 1'b0} : {B_frac, 1'b0} + {A_frac, {B_exp-A_exp-1{1'b0}}, 1'b0};

  // Perform multiplication or division based on sel_muldiv
  wire [7:0] muldiv_exp;
  wire [23:0] muldiv_frac;
  wire muldiv_sign;
  assign muldiv_sign = A_sign ^ B_sign;
  assign muldiv_exp = A_exp + B_exp - BIAS;
  assign muldiv_frac = A_frac * B_frac;

  // Select the correct result based on sel_addsub and sel_muldiv
  assign result_sign = sel_muldiv ? muldiv_sign : addsub_sign;
  assign result_exp = sel_muldiv ? muldiv_exp : addsub_exp;
  assign result_frac = sel_muldiv ? muldiv_frac : addsub_frac;

  // Round the result to the nearest representable floating-point number
  wire [24:0] round_frac;
  assign round_frac = result_frac[23:1] + (result_frac[0] & (result_frac[1] | result_frac[2]));
  wire [8:0] round_exp;
  assign round_exp = result_exp + (round_frac[24] & ((round_frac[23:0] == FRAC_MASK) ? 1'b1 : 1'b0));
  assign out_result = {result_sign, round_exp[7:0], round_frac[22:0]};

  // Check if the result overflows the range of representable floating-point numbers
  wire overflow_exp;
  assign overflow_exp = (result_exp == EXP_MASK) ? 1'b1 : (result_exp == 0) ? 1'b0 : (result_exp == EXP_MASK-1) ? (round_frac[24] & (round_frac[23:0] != FRAC_MASK)) : 1'b0;
  wire overflow_frac;
  assign overflow_frac = (result_exp == EXP_MASK) ? 1'b0 : (result_exp == 0) ? (result_frac != 0) : (result_exp == EXP_MASK-1) ? (round_frac[24] & (round_frac[23:0] == FRAC_MASK)) : 1'b0;
  assign out_overflow = overflow_exp | overflow_frac;

endmodule

Instruction:
Please act as a professional Verilog designer. Implement a Mealy state machine with three states, three inputs, and one output. The state machine detects a specific 3-bit pattern in the input sequence and outputs a '1' when the pattern is detected. The pattern starts with '1' and ends with '0'. Reset is an active-high synchronous reset to state IDLE. The state transitions are as follows:
// IDLE (out=0) --i=1--> STATE1
// STATE1 (out=0) --i=1--> STATE2
// STATE2 (out=0) --i=0--> IDLE
// STATE2 (out=1) --i=1--> STATE1
Please describe how to implement the target module within 100 words to help students finish this Verilog task more easily.

Response:
module mealy_3bit_sequence_detection (
  input clk,
  input reset,
  input i,
  output reg out
);

  // Define the states
  parameter IDLE = 2'b00;
  parameter STATE1 = 2'b01;
  parameter STATE2 = 2'b10;

  // Define the state register
  reg [1:0] state;

  // Define the output register
  reg out_reg;

  // Synchronous reset to IDLE state
  always @(posedge clk) begin
    if (reset) begin
      state <= IDLE;
      out_reg <= 1'b0;
    end else begin
      case (state)
        IDLE: begin
          if (i) begin
            state <= STATE1;
          end else begin
            state <= IDLE;
          end
        end
        STATE1: begin
          if (i) begin
            state <= STATE2;
          end else begin
            state <= IDLE;
          end
        end
        STATE2: begin
          if (i) begin
            state <= STATE1;
            out_reg <= 1'b0;
          end else begin
            state <= IDLE;
            if (out_reg) begin
              out <= 1'b1;
            end
          end
        end
      endcase
    end
  end

  // Output register
  always @(posedge clk) begin
    if (reset) begin
      out <= 1'b0;
    end else begin
      out <= out_reg;
    end
  end

endmodule

module barrelshifter (
  input [n-1:0] in,
  input [log2(n)-1:0] sel,
  input [1:0] dir,
  output [n-1:0] out
);

parameter n = 8; // number of bits in the input and output signals

wire [n-1:0] shifted;

// Shift left by sel bits
assign shifted = (dir == 2'b00) ? (in << sel) :
                 // Shift right by sel bits
                 (dir == 2'b01) ? (in >> sel) :
                 // Rotate left by sel bits
                 (dir == 2'b10) ? ({in[sel-1:0], in[n-1:sel]}) :
                 // Rotate right by sel bits
                 ({in[n-sel-1:n-1], in[0:n-sel-1]});

assign out = shifted;

endmodule

module signed_divider (
    input signed [15:0] A,
    input signed [15:0] B,
    input clk,
    input reset,
    output reg signed [15:0] Q,
    output reg overflow_or_divide_by_zero
);

reg signed [15:0] dividend_reg;
reg signed [15:0] divisor_reg;
reg signed [15:0] remainder_reg;
reg signed [15:0] quotient_reg;
reg signed [15:0] subtractor_reg;
reg [3:0] state_reg;
reg [3:0] next_state;
reg [3:0] next_subtractor;
reg [3:0] next_quotient;
reg [3:0] next_remainder;
reg [3:0] next_divisor;
reg [3:0] next_dividend;
reg [3:0] next_state;

always @ (posedge clk) begin
    if (reset) begin
        dividend_reg <= 0;
        divisor_reg <= 0;
        remainder_reg <= 0;
        quotient_reg <= 0;
        subtractor_reg <= 0;
        state_reg <= 0;
        overflow_or_divide_by_zero <= 0;
    end else begin
        dividend_reg <= dividend_reg;
        divisor_reg <= divisor_reg;
        remainder_reg <= next_remainder;
        quotient_reg <= next_quotient;
        subtractor_reg <= next_subtractor;
        state_reg <= next_state;
        overflow_or_divide_by_zero <= overflow_or_divide_by_zero;
    end
end

always @* begin
    case (state_reg)
        0: begin
            if (B == 0) begin
                next_state = 0;
                next_dividend = A;
                next_divisor = B;
                next_remainder = 0;
                next_quotient = 0;
                next_subtractor = 0;
                overflow_or_divide_by_zero = 1;
            end else begin
                next_state = 1;
                next_dividend = A;
                next_divisor = B;
                next_remainder = A;
                next_quotient = 0;
                next_subtractor = 0;
                overflow_or_divide_by_zero = 0;
            end
        end
        1: begin
            next_state = 2;
            next_dividend = dividend_reg;
            next_divisor = divisor_reg;
            next_remainder = remainder_reg;
            next_quotient = quotient_reg;
            next_subtractor = subtractor_reg;
            overflow_or_divide_by_zero = overflow_or_divide_by_zero;
        end
        2: begin
            next_state = 3;
            next_dividend = dividend_reg;
            next_divisor = divisor_reg;
            next_remainder = remainder_reg;
            next_quotient = quotient_reg;
            next_subtractor = subtractor_reg;
            overflow_or_divide_by_zero = overflow_or_divide_by_zero;
        end
        3: begin
            if (remainder_reg[15] == 1) begin
                next_state = 4;
                next_dividend = dividend_reg;
                next_divisor = divisor_reg;
                next_remainder = remainder_reg;
                next_quotient = quotient_reg;
                next_subtractor = subtractor_reg;
                overflow_or_divide_by_zero = overflow_or_divide_by_zero;
            end else begin
                next_state = 5;
                next_dividend = dividend_reg;
                next_divisor = divisor_reg;
                next_remainder = remainder_reg;
                next_quotient = quotient_reg;
                next_subtractor = subtractor_reg;
                overflow_or_divide_by_zero = overflow_or_divide_by_zero;
            end
        end
        4: begin
            next_state = 5;
            next_dividend = dividend_reg;
            next_divisor = divisor_reg;
            next_remainder = remainder_reg + divisor_reg;
            next_quotient = quotient_reg;
            next_subtractor = subtractor_reg;
            overflow_or_divide_by_zero = overflow_or_divide_by_zero;
        end
        5: begin
            next_state = 6;
            next_dividend = dividend_reg;
            next_divisor = divisor_reg;
            next_remainder = remainder_reg << 1;
            next_quotient = quotient_reg << 1;
            next_subtractor = subtractor_reg;
            overflow_or_divide_by_zero = overflow_or_divide_by_zero;
        end
        6: begin
            if (subtractor_reg[15] == 1) begin
                next_state = 7;
                next_dividend = dividend_reg;
                next_divisor = divisor_reg;
                next_remainder = remainder_reg;
                next_quotient = quotient_reg;
                next_subtractor = subtractor_reg - divisor_reg;
                overflow_or_divide_by_zero = overflow_or_divide_by_zero;
            end else begin
                next_state = 7;
                next_dividend = dividend_reg;
                next_divisor = divisor_reg;
                next_remainder = remainder_reg;
                next_quotient = quotient_reg + 1;
                next_subtractor = subtractor_reg;
                overflow_or_divide_by_zero = overflow_or_divide_by_zero;
            end
        end
        7: begin
            next_state = 2;
            next_dividend = dividend_reg;
            next_divisor = divisor_reg;
            next_remainder = remainder_reg;
            next_quotient = quotient_reg;
            next_subtractor = subtractor_reg;
            overflow_or_divide_by_zero = overflow_or_divide_by_zero;
        end
        default: begin
            next_state = 0;
            next_dividend = 0;
            next_divisor = 0;
            next_remainder = 0;
            next_quotient = 0;
            next_subtractor = 0;
            overflow_or_divide_by_zero = 0;
        end
    endcase
end

assign Q = quotient_reg;

endmodule

module SB_DFFESR (output Q, input C, E, R, D);

	reg Q_next;
	always @*
		if (R)
			Q_next = 0;
		else if (E)
			Q_next = D;
		else
			Q_next = Q;

	always @(posedge C)
		Q <= Q_next;

endmodule

module i2c_opencores
(
