module top_module (
    input clk,
    input reset,
    input [7:0] data_in,
    input valid_in,
    output reg ready_out,
    output reg [9:0] accu_out
);

reg [7:0] parity_bit;
reg [9:0] accumulator;

always @(posedge clk) begin
    if (reset) begin
        parity_bit <= 1'b0;
        accumulator <= 10'b0;
        ready_out <= 1'b0;
    end else begin
        if (valid_in) begin
            parity_bit <= ^data_in;
            accumulator <= accumulator + {1'b0, parity_bit};
            ready_out <= 1'b1;
        end else begin
            ready_out <= 1'b0;
        end
    end
end

assign accu_out = ready_out ? accumulator : {1'b0, parity_bit};

endmodule

module d_latch_reset (
    input  wire        D,
    input  wire        GATE_N,
    input  wire        RESET_B,
    input  wire        VPWR,
    output reg         Q
);

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;

    always @ (posedge GATE_N) begin
        if (RESET_B == 0) begin
            Q <= 0;
        end else begin
            Q <= D;
        end
    end

endmodule

module fifo_buffer #
(
  parameter MEM_STYLE = "block",
            DATA_WIDTH = 8,
            ADDR_WIDTH = 15,
            DEPTH      = 20000
)
(
  input clk, reset,
  output if_full_n,
  input if_write_ce, if_write,
  input [DATA_WIDTH-1:0] if_din,
  output if_empty_n,
  input if_read_ce, if_read,
  output [DATA_WIDTH-1:0] if_dout
);

  // Declare local signals
  reg [DATA_WIDTH-1:0] mem [0:DEPTH-1];
  reg [DATA_WIDTH-1:0] q_buf = 1'b0;
  reg [ADDR_WIDTH-1:0] waddr = 1'b0;
  reg [ADDR_WIDTH-1:0] raddr = 1'b0;
  wire [ADDR_WIDTH-1:0] wnext;
  wire [ADDR_WIDTH-1:0] rnext;
  wire push, pop;
  reg [ADDR_WIDTH-1:0] usedw = 1'b0;
  reg full_n = 1'b1;
  reg empty_n = 1'b0;
  reg [DATA_WIDTH-1:0] q_tmp = 1'b0;
  reg show_ahead = 1'b0;
  reg [DATA_WIDTH-1:0] dout_buf = 1'b0;
  reg dout_valid = 1'b0;

  // Determine memory style
  (* ram_style = MEM_STYLE *)
  reg [DATA_WIDTH-1:0] mem [0:DEPTH-1];

  // Assign output signals
  assign if_full_n  = full_n;
  assign if_empty_n = dout_valid;
  assign if_dout    = dout_buf;

  // Determine whether to push or pop
  assign push       = full_n & if_write_ce & if_write;
  assign pop        = empty_n & if_read_ce & (~dout_valid | if_read);

  // Determine next write and read addresses
  assign wnext      = !push                ? waddr :
                      (waddr == DEPTH - 1) ? 1'b0  :
                      waddr + 1'b1;
  assign rnext      = !pop                 ? raddr :
                      (raddr == DEPTH - 1) ? 1'b0  :
                      raddr + 1'b1;

  // Write to waddr
  always @(posedge clk) begin
    if (reset == 1'b1)
      waddr <= 1'b0;
    else
      waddr <= wnext;
  end

  // Read from raddr
  always @(posedge clk) begin
    if (reset == 1'b1)
      raddr <= 1'b0;
    else
      raddr <= rnext;
  end

  // Determine how much memory is used
  always @(posedge clk) begin
    if (reset == 1'b1)
      usedw <= 1'b0;
    else if (push & ~pop)
      usedw <= usedw + 1'b1;
    else if (~push & pop)
      usedw <= usedw - 1'b1;
  end

  // Determine if FIFO is full
  always @(posedge clk) begin
    if (reset == 1'b1)
      full_n <= 1'b1;
    else if (push & ~pop)
      full_n <= (usedw != DEPTH - 1);
    else if (~push & pop)
      full_n <= 1'b1;
  end

  // Determine if FIFO is empty
  always @(posedge clk) begin
    if (reset == 1'b1)
      empty_n <= 1'b0;
    else if (push & ~pop)
      empty_n <= 1'b1;
    else if (~push & pop)
      empty_n <= (usedw != 1'b1);
  end

  // Write data to memory
  always @(posedge clk) begin
    if (push)
      mem[waddr] <= if_din;
  end

  // Read data from memory
  always @(posedge clk) begin
    q_buf <= mem[rnext];
  end

  // Store data temporarily in q_tmp
  always @(posedge clk) begin
    if (reset == 1'b1)
      q_tmp <= 1'b0;
    else if (push)
      q_tmp <= if_din;
  end

  // Determine if there is data to be shown ahead
  always @(posedge clk) begin
    if (reset == 1'b1)
      show_ahead <= 1'b0;
    else if (push && usedw == pop)
      show_ahead <= 1'b1;
    else
      show_ahead <= 1'b0;
  end

  // Store data to be read in dout_buf
  always @(posedge clk) begin
    if (reset == 1'b1)
      dout_buf <= 1'b0;
    else if (pop)
      dout_buf <= show_ahead? q_tmp : q_buf;
  end

  // Determine if data is valid
  always @(posedge clk) begin
    if (reset == 1'b1)
      dout_valid <= 1'b0;
    else if (pop)
      dout_valid <= 1'b1;
    else if (if_read_ce & if_read)
      dout_valid <= 1'b0;
  end

endmodule

