module ControlUnit(
    output reg IR_CU,
    output reg RFLOAD,
    output reg PCLOAD,
    output reg SRLOAD,
    output reg SRENABLED,
    output reg ALUSTORE,
    output reg MFA,
    output reg WORD_BYTE,
    output reg READ_WRITE,
    output reg IRLOAD,
    output reg MBRLOAD,
    output reg MBRSTORE,
    output reg MARLOAD,
    output reg [4:0] opcode,
    output reg [3:0] CU,
    input MFC,
    input Reset,
    input Clk,
    input [31:0] IR,
    input [3:0] SR
);

// Opcode decoding
assign opcode = IR[27:23];

// Control signals for Register File
always @(*) begin
    case(opcode)
        5'b00000: begin // Data Processing
            RFLOAD = 1;
            ALUSTORE = 1;
        end
        5'b00001: begin // Data Processing Immediate
            RFLOAD = 1;
            ALUSTORE = 1;
        end
        5'b00010: begin // Load/Store Immediate Offset
            RFLOAD = 1;
        end
        5'b00011: begin // Load/Store Register Offset
            RFLOAD = 1;
        end
        5'b00100: begin // Load/Store Multiple
            RFLOAD = 1;
        end
        5'b00101: begin // Branch and Branch with Link
            // No Register File operations
        end
        default: begin
            RFLOAD = 0;
            ALUSTORE = 0;
        end
    endcase
end

// Control signals for Memory
always @(*) begin
    case(opcode)
        5'b00010: begin // Load/Store Immediate Offset
            MFA = 1;
            WORD_BYTE = 1;
            if(IR[22] == 1) begin // Load
                READ_WRITE = 1;
                MBRLOAD = 1;
            end else begin // Store
                READ_WRITE = 0;
                MBRSTORE = 1;
            end
        end
        5'b00011: begin // Load/Store Register Offset
            MFA = 1;
            WORD_BYTE = 1;
            if(IR[22] == 1) begin // Load
                READ_WRITE = 1;
                MBRLOAD = 1;
            end else begin // Store
                READ_WRITE = 0;
                MBRSTORE = 1;
            end
        end
        5'b00100: begin // Load/Store Multiple
            MFA = 1;
            WORD_BYTE = 1;
            if(IR[22] == 1) begin // Load
                READ_WRITE = 1;
                MBRLOAD = 1;
            end else begin // Store
                READ_WRITE = 0;
                MBRSTORE = 1;
            end
        end
        default: begin
            MFA = 0;
            WORD_BYTE = 0;
            READ_WRITE = 0;
            MBRLOAD = 0;
            MBRSTORE = 0;
        end
    endcase
end

// Control signals for Program Counter
always @(*) begin
    case(opcode)
        5'b00101: begin // Branch and Branch with Link
            PCLOAD = 1;
        end
        default: begin
            PCLOAD = 0;
        end
    endcase
end

// Control signals for Status Register
always @(*) begin
    SRLOAD = 0;
    SRENABLED = 0;
end

// Control signals for Instruction Register
always @(*) begin
    IR_CU = 1;
    IRLOAD = 0;
end

// Control signals for Control Unit
always @(*) begin
    CU = 0;
end

// Control signals for Memory Address Register
always @(*) begin
    MARLOAD = 0;
end

endmodule

