module top_module (
    input a,
    input b,
    input c,
    output reg out
);

    wire nand1_out;
    wire nand2_out;
    wire nand3_out;

    // AND gate behavioral model
    assign nand1_out = ~(a & b);

    // 2-input XOR gate designed using only NAND gates
    assign nand2_out = ~(a & ~(c));
    assign nand3_out = ~(~(c) & b);
    assign out = ~(nand2_out & nand3_out);

endmodule

module binary_adder (
    input [3:0] a,b,c,d,e,f,g,h,i,
    output reg [2:0] x,y,z,
    output reg ovf );

    reg [3:0] xor1, xor2, sum;

    always @(*) begin
        xor1 = {a,b,c,d} ^ e;
        xor2 = {f,g,h,i} ^ e;
        sum = xor1 + xor2 + e;
        x = sum[0];
        y = sum[1];
        z = sum[2];
        ovf = sum[3];
    end

endmodule

module halves_sum(
    input [31:0] in,
    output reg [15:0] out
);

    always @(*) begin
        out = (in[31:16] + in[15:0]);
