module addictive_control_logic_module (
    input [31:0] in1,
    input in2,
    input select,
    output [31:0] out
);

wire [31:0] byte_swapped_output;
wire not_gate_output;

byte_swapping_module byte_swapper(.in(in1), .out(byte_swapped_output));
not_gate_module not_gater(.in(in2), .out(not_gate_output));
xor_module xor_gate(.in1(byte_swapped_output), .in2(not_gate_output), .out(out));

always @(posedge clk) begin
    if (reset) begin
        out <= 0;
    end else begin
        if (select) begin
            out <= not_gate_output;
        end else begin
            out <= byte_swapped_output;
        end
    end
end

endmodule

