    input reset,
    input parallel_load,
    input shift,
    input [3:0] input_data,
    input [1:0] shift_amount,
    output [3:0] final_output
);

wire [3:0] barrel_shift_out;
wire [3:0] shift_left_out;

barrel_shifter bs (
    .data_in(input_data),
    .shift_amt(shift_amount),
    .data_out(barrel_shift_out)
);

shift_left_register slr (
