module barrel_shifter (
    input [3:0] data_in,
    input [1:0] shift_amt,
    output [3:0] data_out
);

assign data_out = (shift_amt == 2'b00) ? data_in :
                  (shift_amt == 2'b01) ? {data_in[2:0], data_in[3]} :
                  (shift_amt == 2'b10) ? {data_in[1:0], data_in[3:2]} :
                                         {data_in[0], data_in[3:1]};

endmodule

module shift_left_register (
    input clk,
    input reset,
    input parallel_load,
    input shift,
    input [3:0] input_data,
    output reg [3:0] output_data
);

always @(posedge clk or posedge reset) begin
    if (reset) begin
        output_data <= 4'b0000;
    end else if (parallel_load) begin
        output_data <= input_data;
    end else if (shift) begin
        output_data <= {output_data[2:0], 1'b0};
    end
end

endmodule

