module adc08d1020_serial(
    output wire sclk, // typical 15MHz, limit 19MHz
    output reg sdata,
    output reg scs,
    input wire [15:0] w_data,
    input wire [3:0] w_addr,
    input wire commit,
    output wire busy,
    input wire clk12p5
);

    reg [15:0] l_data;
    reg [3:0] l_addr;
    reg l_commit;
    reg l_busy;

    reg [5:0] cycle;
    reg [31:0] shifter;
    reg commit_d;
    reg commit_pulse; // get the rising edge only of commit

    assign busy = l_busy;

    // register i2c bus signals into local clock domain to ease timing
    always @(posedge clk12p5) begin
        l_data <= w_data;
        l_addr <= w_addr;
        l_commit <= commit;

        // busy whenever the cycle counter isn't at 0
        l_busy <= (cycle[5:0] != 6'b0);
    end

    // turn commit into a locally timed pulse
    always @(posedge clk12p5) begin
        commit_d <= l_commit;
        commit_pulse <= !commit_d && l_commit;
    end

    // forward the clock net
    ODDR2 sclk_oddr2 (
        .D0(1'b1),
        .D1(1'b0),
        .C0(clk12p5),
        .C1(!clk12p5),
        .CE(1'b1),
        .R(1'b0),
        .S(1'b0),
        .Q(sclk)
    );

    // main shifter logic
    always @(posedge clk12p5) begin
        if (commit_pulse && (cycle[5:0] == 6'b0)) begin
            shifter[31:0] <= {12'b0000_0000_0001, l_addr[3:0], l_data[15:0]};
            cycle[5:0] <= 6'b10_0000;
        end else if (cycle[5:0] != 6'b0) begin
            cycle[5:0] <= cycle[5:0] - 6'b1;
            shifter[31:0] <= {shifter[30:0], 1'b0};
        end else begin
            cycle[5:0] <= 6'b0;
            shifter[31:0] <= 32'b0;
        end
    end

    // output stage logic
    always @(posedge clk12p5) begin
        sdata <= shifter[31];
        scs <= !(cycle[5:0] != 6'b0);
    end

endmodule

module mealy_state_machine (
  input clk,
  input reset,
  input data_in,
  input enable,
  output reg data_out,
  output reg valid_out
);

  // Define the states using one-hot encoding
  parameter S0 = 4'b0001;
  parameter S1 = 4'b0010;
  parameter S2 = 4'b0100;
  parameter S3 = 4'b1000;

  // Define the state register and next state logic
  reg [3:0] state, next_state;
  always @(posedge clk, posedge reset) begin
    if (reset) begin
      state <= S0;
    end else begin
      state <= next_state;
    end
  end

  // Define the output logic
  always @(*) begin
    case(state)
      S0: begin
        if (data_in) begin
          next_state = S0;
          data_out = 0;
        end else if (enable) begin
          next_state = S1;
          data_out = 0;
        end
      end
      S1: begin
        if (data_in) begin
          next_state = S0;
          data_out = 0;
        end else if (enable) begin
          next_state = S2;
          data_out = 0;
        end
      end
      S2: begin
        if (data_in) begin
          next_state = S0;
          data_out = 1;
        end else if (enable) begin
          next_state = S3;
          data_out = 0;
        end
      end
      S3: begin
        if (data_in) begin
          next_state = S0;
          data_out = 0;
        end else if (enable) begin
          next_state = S0;
          data_out = 0;
        end
      end
    endcase

    // Define the valid output signal
    if (state == S2 && data_in) begin
      valid_out = 1;
    end else begin
      valid_out = 0;
    end
  end

endmodule

module booth_multiplier(
    input clk,
    input rst,
    input start,
    input [7:0] a,
    input [7:0] b,
    output reg done,
    output reg [15:0] result
);

    reg [7:0] m;
    reg [7:0] q;
    reg [4:0] i;
    reg [8:0] ac;

    always @(posedge clk) begin
        if (rst) begin
            done <= 0;
            result <= 0;
            m <= 0;
            q <= 0;
            i <= 0;
            ac <= 0;
        end else begin
            if (start) begin
                done <= 0;
                result <= 0;
                m <= b;
                q <= a;
                i <= 4;
                ac <= {q, 8'b0};
            end else if (!done) begin
                if (ac[0:1] == 2'b01) begin
                    ac <= ac + m;
                end else if (ac[0:1] == 2'b10) begin
                    ac <= ac - m;
                end

                if (ac[0]) begin
                    q <= {q[6:0], 1'b1};
                    ac <= ac + m;
                end else if (ac[1]) begin
                    q <= {q[6:0], 1'b0};
                    ac <= ac - m;
                end else begin
                    q <= {q[6:0], 1'b0};
                end

                i <= i - 1;

                if (i == 0) begin
                    done <= 1;
                    result <= ac[15:0];
                end
            end
        end
    end

endmodule

module BoothAlgorithm (
    input clk,
    input start,
    input [3:0] x,
    input [5:0] y,
    output reg [9:0] ans,
    output reg ready
);

reg [5:0] y_reg;
reg [2:0] y_group;
reg [3:0] x_reg;
reg [4:0] partial_product;
reg [9:0] ans_reg;
reg [2:0] state;

always @(posedge clk) begin
    if (start) begin
        y_reg <= y;
        x_reg <= x;
        state <= 0;
        ans_reg <= 0;
        ready <= 0;
    end else begin
        case (state)
            0: begin
                y_group <= {y_reg[5], y_reg[4], y_reg[3]};
                state <= 1;
            end
            1: begin
                case (y_group)
                    3'b000: begin
                        partial_product <= 0;
                        state <= 2;
                    end
                    3'b001: begin
                        partial_product <= {x_reg, 2'b0};
                        state <= 2;
                    end
                    3'b010: begin
                        partial_product <= {x_reg, 2'b0} - x_reg;
                        state <= 2;
                    end
                    3'b011: begin
                        partial_product <= -x_reg;
                        state <= 2;
                    end
                    3'b100: begin
                        partial_product <= -{x_reg, 2'b0};
                        state <= 2;
                    end
                    3'b101: begin
                        partial_product <= {x_reg, 2'b0} - -x_reg;
                        state <= 2;
                    end
                    3'b110: begin
                        partial_product <= x_reg;
                        state <= 2;
                    end
                    3'b111: begin
                        partial_product <= 0;
                        state <= 2;
                    end
                endcase
            end
            2: begin
                ans_reg <= ans_reg + partial_product;
                y_reg <= {y_reg[4:0], y_reg[5]};
                state <= 0;
                if (y_reg == 6'b0) begin
                    ans <= ans_reg;
                    ready <= 1;
                end
            end
        endcase
    end
end

endmodule

module countdown_timer (
    input clk,
    input reset,           // Synchronous active-high reset for BCD counter
    input [3:0] in,        // Input for the priority encoder
    output reg [1:0] pos,  // Output of the priority encoder
    output [3:1] ena,      // Enable signals for the upper three digits of the BCD counter
    output reg zero_flag,  // Output flag indicating countdown has completed
    output reg [15:0] q    // Output of the BCD counter
);

reg [3:0] count;

always @(posedge clk) begin
    if (reset) begin
        count <= 4'b1001;
        q <= 16'b1001100110011001;
        ena <= 3'b111;
        pos <= 2'b00;
        zero_flag <= 1'b0;
    end else begin
        if (count == 4'b0000) begin
            zero_flag <= 1'b1;
            ena <= 3'b000;
        end else begin
            zero_flag <= 1'b0;
            ena <= {3{pos == 2'b11}} & {2{pos != 2'b11}};
            q <= {q[15:4], count};
            case (in)
                4'b1000: pos <= 2'b11;
                4'b0100: pos <= 2'b10;
                4'b0010: pos <= 2'b01;
                4'b0001: pos <= 2'b00;
                default: pos <= 2'b00;
            endcase
            if (ena[1]) count[3] <= ~|count[2:0];
            if (ena[2]) count[2] <= ~|count[1:0];
            if (ena[3]) count[1] <= ~|count[0];
            count[0] <= ~count[0];
        end
    end
end

endmodule

module communication_module (
  input clk,
  input data,
  input ready0,
  input ready1,
  input clk2_i,
  input data2_i,
  input ready2_0,
  input ready2_1,
  input clk_i,
  input data_i,
  output ready2_0_o,
  output ready2_1_o
);

  reg data_out;
  reg ready0_out;
  reg ready1_out;

  always @(posedge clk) begin
    if (ready2_1 && ready0) begin
      data_out <= data;
      ready1_out <= 1'b0;
      ready2_0_o <= 1'b0;
    end else if (ready2_1 && !ready0) begin
      ready1_out <= 1'b1;
      ready2_0_o <= 1'b1;
    end else if (!ready2_1 && ready0) begin
      ready1_out <= 1'b1;
      ready2_0_o <= 1'b1;
    end else begin
      ready1_out <= 1'b0;
      ready2_0_o <= 1'b0;
    end

    if (ready2_0 && !ready1) begin
      ready0_out <= 1'b1;
      ready2_1_o <= 1'b1;
    end else if (!ready2_0 && ready1) begin
      ready0_out <= 1'b0;
      ready2_1_o <= 1'b0;
    end

  end

  assign data_out = data_i;
  assign ready0_out = ready2_0;

endmodule

module servo_control (
  input [N-1:0] dpos,
  input [N-1:0] cpos,
  output [M-1:0] ctrl
);

parameter N = 8; // width of desired position and current position signals
parameter M = 8; // width of control signal

reg [M-1:0] pwm;
reg [M-1:0] pwm_counter;
reg [M-1:0] error;
reg [M-1:0] prev_error;
reg [M-1:0] integral;
reg [M-1:0] derivative;

parameter Kp = 1; // proportional gain
parameter Ki = 0.1; // integral gain
parameter Kd = 0.01; // derivative gain

always @ (posedge clk) begin
  error <= dpos - cpos;
  integral <= integral + error;
  derivative <= error - prev_error;
  prev_error <= error;
  pwm <= Kp*error + Ki*integral + Kd*derivative;
end

always @ (posedge clk) begin
  if (pwm_counter >= pwm) begin
    ctrl <= 1;
    pwm_counter <= 0;
  end else begin
    ctrl <= 0;
    pwm_counter <= pwm_counter + 1;
  end
end

endmodule

module traffic_light_controller (
  input [1:0] state,
  input clock,
  output [1:0] next_state,
  output green,
  output yellow,
  output red
);

  // Define the states
  parameter GREEN = 2'b00;
  parameter YELLOW = 2'b01;
  parameter RED = 2'b10;

  // Define the timing constants
  parameter GREEN_TIME = 4;
  parameter YELLOW_TIME = 1;
  parameter RED_TIME = 3;

  // Define the state register
  reg [1:0] current_state;

  // Define the state transition logic
  always @(posedge clock) begin
    case (current_state)
      GREEN: begin
        if (green_time_counter < GREEN_TIME) begin
          green <= 1;
          yellow <= 0;
          red <= 0;
          green_time_counter <= green_time_counter + 1;
        end else if (yellow_time_counter < YELLOW_TIME) begin
          green <= 0;
          yellow <= 1;
          red <= 0;
          yellow_time_counter <= yellow_time_counter + 1;
        end else begin
          green <= 0;
          yellow <= 0;
          red <= 1;
          current_state <= RED;
          green_time_counter <= 0;
          yellow_time_counter <= 0;
        end
      end

      YELLOW: begin
        if (yellow_time_counter < YELLOW_TIME) begin
          green <= 0;
          yellow <= 1;
          red <= 0;
          yellow_time_counter <= yellow_time_counter + 1;
        end else begin
          green <= 0;
          yellow <= 0;
          red <= 1;
          current_state <= RED;
          yellow_time_counter <= 0;
        end
      end

      RED: begin
        if (red_time_counter < RED_TIME) begin
          green <= 0;
          yellow <= 0;
          red <= 1;
          red_time_counter <= red_time_counter + 1;
        end else begin
          green <= 1;
          yellow <= 0;
          red <= 0;
          current_state <= GREEN;
          red_time_counter <= 0;
        end
      end
    endcase
  end

  // Define the state update logic
  always @(current_state) begin
    case (current_state)
      GREEN: next_state <= YELLOW;
      YELLOW: next_state <= RED;
      RED: next_state <= GREEN;
    endcase
  end

  // Initialize the state register and counters
  initial begin
    current_state <= GREEN;
    green_time_counter <= 0;
    yellow_time_counter <= 0;
    red_time_counter <= 0;
  end

endmodule

module spi_master (
  input clk,
  input reset,
  input [7:0] mosi,
  input cs,
  input sclk,
  output [7:0] miso
);

  reg [7:0] tx_data;
  reg [7:0] rx_data;
  reg [2:0] state;
  reg cs_n;
  reg sclk_prev;

  always @(posedge clk) begin
    if (reset) begin
      state <= 3'b000;
      cs_n <= 1'b1;
      sclk_prev <= 1'b1;
      tx_data <= 8'h00;
      rx_data <= 8'h00;
    end
    else begin
      case (state)
        3'b000: begin // Idle state
          if (!cs) begin
            state <= 3'b001;
            cs_n <= 1'b0;
          end
        end
        3'b001: begin // Transmit state
          if (sclk_prev && !sclk) begin
            miso <= rx_data;
            rx_data <= {rx_data[6:0], mosi};
          end
          if (!cs) begin
            state <= 3'b010;
            tx_data <= 8'h00;
          end
        end
        3'b010: begin // Receive state
          if (sclk_prev && !sclk) begin
            miso <= rx_data;
            rx_data <= {rx_data[6:0], mosi};
          end
          if (!cs) begin
            state <= 3'b001;
            tx_data <= tx_data + 1;
          end
        end
      endcase
      sclk_prev <= sclk;
    end
  end

endmodule

module spi_slave (
  input clk,
  input reset,
  input [7:0] mosi,
  input cs,
  input sclk,
  output [7:0] miso
);

  reg [7:0] tx_data;
  reg [7:0] rx_data;
  reg [2:0] state;
  reg cs_n;
  reg sclk_prev;

  always @(posedge clk) begin
    if (reset) begin
      state <= 3'b000;
      cs_n <= 1'b1;
      sclk_prev <= 1'b1;
      tx_data <= 8'h00;
      rx_data <= 8'h00;
    end
    else begin
      case (state)
        3'b000: begin // Idle state
          if (!cs_n) begin
            state <= 3'b001;
            cs_n <= 1'b0;
          end
        end
        3'b001: begin // Receive state
          if (sclk_prev && !sclk) begin
            miso <= rx_data;
            rx_data <= {rx_data[6:0], mosi};
          end
          if (cs_n) begin
            state <= 3'b010;
            tx_data <= 8'h00;
          end
        end
        3'b010: begin // Transmit state
          if (sclk_prev && !sclk) begin
            miso <= rx_data;
            rx_data <= {rx_data[6:0], tx_data};
          end
          if (!cs_n) begin
            state <= 3'b001;
            tx_data <= tx_data + 1;
          end
        end
      endcase
      sclk_prev <= sclk;
    end
  end

endmodule

module edge_detector (
    input clk,
    input [7:0] in,
    output [7:0] anyedge
);

reg [7:0] shift_reg;
reg [7:0] prev_in;

always @(posedge clk) begin
    prev_in <= in;
    shift_reg <= {shift_reg[6:0], prev_in[7]};
end

assign anyedge = (shift_reg ^ prev_in) & prev_in;

endmodule

