module fast_clock_domain(
    input clk,
    input rst,
    input [15:0] probe,
    output [15:0] sample_data,
    output sample_data_avail,
    input overflow,
    input acq_enable,
    input [7:0] clock_divisor,
    input [15:0] channel_enable,
    output stalled
);

   wire sample_tick;
   reg 	stalled_d, stalled_q;

   // Clock divider module
   clock_divider ckd(clk, rst, acq_enable, clock_divisor, sample_tick);

   // Channel module
   genvar i;
   generate
      for (i=0; i<16; i=i+1) begin : CHANNEL

	 wire probe_synced;
	 wire [15:0] chandata_parallel;
	 wire chandata_parallel_ready;

	 // Synchronizer module
	 synchronizer probe_sync(clk, probe[i], probe_synced);

	 // Serial to parallel module
	 serial_to_parallel s2p(.clk(clk), .rst(rst), .tick(sample_tick),
				.enable(acq_enable & channel_enable[i]),
				.in(probe_synced), .out(chandata_parallel),
				.ready(chandata_parallel_ready));

	 // Latch module
	 reg [15:0] latch_d, latch_q;
	 reg 	    valid_d, valid_q;
	 wire [15:0] latch_chain;
	 wire 	     valid_chain;

	 always @(*) begin
	    if(acq_enable) begin
	       if (chandata_parallel_ready) begin
		  latch_d = chandata_parallel;
		  valid_d = 1'b1;
	       end else begin
		  latch_d = latch_chain;
		  valid_d = valid_chain;
	       end
	    end else begin
	       latch_d = 16'h0000;
	       valid_d = 1'b0;
	    end
	 end

	 always @(posedge clk) begin
	    if (rst) begin
	       latch_q <= 16'h0000;
	       valid_q <= 1'b0;
	    end else begin
	       latch_q <= latch_d;
	       valid_q <= valid_d;
	    end
	 end

      end
   endgenerate

   // Channel chaining module
   generate
      for (i=1; i<16; i=i+1) begin : CHAINING
	 assign CHANNEL[i-1].latch_chain = CHANNEL[i].latch_q;
	 assign CHANNEL[i-1].valid_chain = CHANNEL[i].valid_q;
      end
   endgenerate
   assign CHANNEL[15].latch_chain = 16'h0000;
   assign CHANNEL[15].valid_chain = 1'b0;

   // Stall output if overflow detected
   always @(*) begin
      stalled_d = stalled_q | overflow;
   end
   always @(posedge clk) begin
      if (rst) begin
	 stalled_q <= 1'b0;
      end else begin
	 stalled_q <= stalled_d;
      end
   end

   // Output signals
   assign sample_data = CHANNEL[0].latch_q;
   assign sample_data_avail = CHANNEL[0].valid_q && !stalled && !overflow;
   assign stalled = stalled_q;

endmodule

module debounce_clk (
    inclk0,
    c0
);

input inclk0;
output c0;

reg [1:0] state;
wire inclk0_synced;
wire inclk0_synced_prev;
wire inclk0_synced_next;
wire inclk0_synced_next_next;
wire inclk0_synced_prev_prev;
wire c0_pulse;

// Synchronize input clock signal
always @(posedge inclk0) begin
    inclk0_synced_prev_prev <= inclk0_synced_prev;
    inclk0_synced_prev <= inclk0_synced;
    inclk0_synced <= inclk0;
    inclk0_synced_next <= inclk0_synced_prev;
    inclk0_synced_next_next <= inclk0_synced_prev_prev;
end

// Determine when to output a pulse
always @(posedge inclk0_synced or negedge inclk0_synced) begin
    if (inclk0_synced == inclk0_synced_prev && inclk0_synced_prev == inclk0_synced_prev_prev && inclk0_synced_prev_prev == inclk0_synced_next && inclk0_synced_next == inclk0_synced_next_next) begin
        c0_pulse <= 1;
    end else begin
        c0_pulse <= 0;
    end
end

// Generate output clock signal
always @(posedge inclk0_synced) begin
    if (state == 2'b00) begin
        state <= 2'b01;
        c0 <= 0;
    end else if (state == 2'b01) begin
        state <= 2'b10;
        c0 <= 1;
    end else if (state == 2'b10) begin
        state <= 2'b11;
        c0 <= 1;
    end else if (state == 2'b11) begin
        if (c0_pulse) begin
            state <= 2'b00;
            c0 <= 0;
        end else begin
            state <= 2'b10;
            c0 <= 1;
        end
    end
end

endmodule

module modbus_slave(
  input modbus_clk,
  input modbus_rst,
  input modbus_rx,
  input [7:0] modbus_addr,
  input modbus_req,
  input [15:0] modbus_data,
  output reg modbus_tx,
  output reg modbus_resp,
  output reg [15:0] modbus_out
);

  // Define Modbus function codes
  localparam READ_COILS = 1;
  localparam READ_INPUTS = 2;
  localparam READ_HOLD_REGS = 3;
  localparam READ_INPUT_REGS = 4;
  localparam WRITE_COIL = 5;
  localparam WRITE_HOLD_REG = 6;

  // Define Modbus response codes
  localparam RESP_OK = 0;
  localparam RESP_EXC_FUNC = 1;
  localparam RESP_EXC_ADDR = 2;
  localparam RESP_EXC_VALUE = 3;

  // Define internal registers
  reg [15:0] coils;
  reg [15:0] inputs;
  reg [15:0] hold_regs;
  reg [15:0] input_regs;

  // Define internal variables
  reg [15:0] addr;
  reg [15:0] data;
  reg [7:0] func;
  reg [7:0] resp_code;

  // Initialize internal registers
  initial begin
    coils = 16'h0000;
    inputs = 16'h0000;
    hold_regs = 16'h0000;
    input_regs = 16'h0000;
  end

  // Modbus slave block
  always @(posedge modbus_clk) begin
    if (modbus_rst) begin
      modbus_tx <= 1'b0;
      modbus_resp <= 1'b0;
      modbus_out <= 16'h0000;
      addr <= 16'h0000;
      data <= 16'h0000;
      func <= 8'h00;
      resp_code <= RESP_OK;
    end else begin
      if (modbus_rx) begin
        // Decode Modbus request
        case (func)
          READ_COILS: begin
            if ((addr + data) > 16'h0010) begin
              resp_code <= RESP_EXC_ADDR;
            end else begin
              modbus_out <= coils[(addr + data - 1):addr];
              resp_code <= RESP_OK;
            end
          end
          READ_INPUTS: begin
            if ((addr + data) > 16'h0010) begin
              resp_code <= RESP_EXC_ADDR;
            end else begin
              modbus_out <= inputs[(addr + data - 1):addr];
              resp_code <= RESP_OK;
            end
          end
          READ_HOLD_REGS: begin
            if ((addr + data) > 16'h0010) begin
              resp_code <= RESP_EXC_ADDR;
            end else begin
              modbus_out <= hold_regs[(addr + data - 1):addr];
              resp_code <= RESP_OK;
            end
          end
          READ_INPUT_REGS: begin
            if ((addr + data) > 16'h0010) begin
              resp_code <= RESP_EXC_ADDR;
            end else begin
              modbus_out <= input_regs[(addr + data - 1):addr];
              resp_code <= RESP_OK;
            end
          end
          WRITE_COIL: begin
            if ((addr + data) > 16'h0010) begin
              resp_code <= RESP_EXC_ADDR;
            end else if ((data != 16'h0000) && (data != 16'hFF00)) begin
              resp_code <= RESP_EXC_VALUE;
            end else begin
              coils[addr] <= (data == 16'hFF00);
              resp_code <= RESP_OK;
            end
          end
          WRITE_HOLD_REG: begin
            if ((addr + data) > 16'h0010) begin
              resp_code <= RESP_EXC_ADDR;
            end else begin
              hold_regs[addr] <= data;
              resp_code <= RESP_OK;
            end
          end
          default: begin
            resp_code <= RESP_EXC_FUNC;
          end
        endcase
        modbus_resp <= 1'b1;
      end else if (modbus_req) begin
        // Respond to Modbus request
        modbus_tx <= 1'b1;
        modbus_out <= modbus_data;
        addr <= modbus_data[15:0];
        data <= modbus_data[31:16];
        func <= modbus_data[7:0];
        modbus_resp <= 1'b0;
        case (resp_code)
          RESP_OK: begin
            modbus_resp <= 1'b1;
          end
          RESP_EXC_FUNC: begin
            modbus_out <= func;
          end
          RESP_EXC_ADDR: begin
            modbus_out <= (resp_code << 8);
          end
          RESP_EXC_VALUE: begin
            modbus_out <= (resp_code << 8);
          end
        endcase
      end else begin
        // Idle state
        modbus_tx <= 1'b0;
        modbus_resp <= 1'b0;
        modbus_out <= 16'h0000;
        addr <= 16'h0000;
        data <= 16'h0000;
        func <= 8'h00;
        resp_code <= RESP_OK;
      end
    end
  end

endmodule

module top_module (
    input clk,
    input [3:0] a,
    input [3:0] b,
    output reg [3:0] sum,
    output reg [3:0] diff
);

reg [3:0] shifted_input;
reg [3:0] shifted_sum;
reg [3:0] shifted_diff;
reg [3:0] rising_edge_detected;

// Rising edge detector using shift register and comparator
reg [3:0] shift_reg = 4'b0000;
always @(posedge clk) begin
    shift_reg <= {shift_reg[2:0], a[0]};
    if (shift_reg == 4'b0001) begin
        rising_edge_detected <= 1;
    end else begin
        rising_edge_detected <= 0;
    end
end

// Full adder using carry-select adder technique
wire [3:0] sum_ripple1;
wire [3:0] sum_ripple2;
wire [3:0] carry_ripple1;
wire [3:0] carry_ripple2;
wire [3:0] carry_select;
wire [1:0] mux_sel = a[3:2];
assign {sum_ripple1, carry_ripple1} = a + b;
assign {sum_ripple2, carry_ripple2} = {sum_ripple1[2:0], 1'b0} + {b[3:1], 1'b0};
assign carry_select = {carry_ripple1[3], carry_ripple2[2]};
assign sum = (mux_sel == 2'b00) ? sum_ripple1 : ((mux_sel == 2'b01) ? sum_ripple2 : a + b - 1);

// Barrel shifter to shift one of the input values by 2 bits to the left
always @(*) begin
    shifted_input = {a[1:0], 2'b00};
end

// Output sum of shifted input and other input when rising edge is detected
always @(posedge clk) begin
    if (rising_edge_detected) begin
        shifted_sum <= shifted_input + b;
        shifted_diff <= shifted_input - b;
    end
end

// Bitwise XOR operation on output sums
always @(*) begin
    diff = shifted_diff ^ shifted_sum;
end

endmodule

module adder(
    input [3:0] A,
    input [3:0] B,
    output reg [3:0] Sum
);

reg carry;

always @ (A or B)
begin
    Sum[0] = A[0] ^ B[0];
    carry = A[0] & B[0];

    Sum[1] = A[1] ^ B[1] ^ carry;
    carry = (A[1] & B[1]) | (A[1] & carry) | (B[1] & carry);

    Sum[2] = A[2] ^ B[2] ^ carry;
    carry = (A[2] & B[2]) | (A[2] & carry) | (B[2] & carry);

    Sum[3] = A[3] ^ B[3] ^ carry;
end

endmodule

module counter_3bit (
  input clk,
  input reset,
  input load,
  input [2:0] input_value,
  output reg [2:0] count
);

  always @ (posedge clk or negedge reset) begin
    if (!reset) begin
      count <= 3'b0;
    end else if (load) begin
      count <= input_value;
    end else if (count == 3'b111) begin
      count <= 3'b0;
    end else begin
      count <= count + 1;
    end
  end

endmodule

