module assert_change_assume (
  input clk,
  input reset_n,
  input start_event,
  input [width-1:0] test_expr,
  input window,
  input ignore_new_start,
  input reset_on_new_start,
  input error_on_new_start,
  input xzcheck_enable,
  output reg assert
);

  parameter width = 8;
  parameter num_cks = 2;

  reg [width-1:0] prev_test_expr;
  reg [num_cks-1:0] window_counter;
  reg [num_cks-1:0] start_event_counter;
  reg [num_cks-1:0] reset_on_new_start_counter;
  reg [num_cks-1:0] error_on_new_start_counter;
  reg [num_cks-1:0] xzcheck_counter;
  reg [num_cks-1:0] xzcheck_flag;

  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      prev_test_expr <= 'bx;
      window_counter <= 0;
      start_event_counter <= 0;
      reset_on_new_start_counter <= 0;
      error_on_new_start_counter <= 0;
      xzcheck_counter <= 0;
      xzcheck_flag <= 0;
      assert <= 0;
    end else begin
      if (start_event) begin
        start_event_counter <= window;
        if (reset_on_new_start) begin
          reset_on_new_start_counter <= window;
        end
        if (error_on_new_start) begin
          error_on_new_start_counter <= window;
        end
      end
      if (ignore_new_start && start_event_counter > 0) begin
        start_event_counter <= start_event_counter - 1;
      end
      if (reset_on_new_start_counter > 0) begin
        reset_on_new_start_counter <= reset_on_new_start_counter - 1;
        window_counter <= window;
      end
      if (error_on_new_start_counter > 0) begin
        error_on_new_start_counter <= error_on_new_start_counter - 1;
        assert <= 0;
      end
      if (xzcheck_enable) begin
        if (test_expr === 'bx || test_expr === 'bz) begin
          xzcheck_counter <= window;
          xzcheck_flag <= 1;
        end else begin
          xzcheck_counter <= 0;
          xzcheck_flag <= 0;
        end
      end
      if (window_counter > 0) begin
        window_counter <= window_counter - 1;
        if (window_counter == 0) begin
          if (test_expr !== prev_test_expr && (!xzcheck_enable || !xzcheck_flag)) begin
            assert <= 1;
          end
        end
      end
      prev_test_expr <= test_expr;
    end
  end

endmodule

module ultrasonic #( parameter N = 16 , CONSTANT = 20'd588 ) ( 
    input clk,
    input signal,
    input rst_n,
    output reg [N-1:0] value , 
    output reg done 
    );

    reg [1:0]	state ;
    reg [N-1:0] count_1 ;

    // El modulo tiene 3 estados, el primero mantiene los valores en cero y se llega a el por medio del rst_n
    // El segundo estado inicia cuando el ultrasónico recibe la señal del modulo fisico y cuenta la duración
    // El tercer estado inicia cuando la señal del físico se apaga, enviando un "Done" al controlador
    // El rst_n devuelve al estado inicia el módulo

    // States assignation 
    parameter S0 = 2'b00 ;
    parameter S1 = 2'b01 ;
    parameter S2 = 2'b10 ;

    // Nextstate logic
    always @ ( negedge clk ) 
        if ( ~rst_n )
            state <= S0 ;
        else
            case ( state ) 
                S0 : 
                    if ( signal )
                        state <= S1 ;
                    else 
                        state <= S0 ;
                S1 :
                    if ( ~signal )
                        state <= S2 ;
                    else
                        state <= S1 ;
            endcase

    // State logic 
    always @( posedge clk )
        case ( state ) 
            S0 : begin
                count_1 <= 0 ;
                value <= 0 ;
                done <= 0 ;
            end S1 : begin
                if ( CONSTANT == count_1 ) begin
                    count_1 <= 1 ;
                    value <= value + 1'b1 ;
                    done <= 0 ; 
                end else begin  
                    count_1 <= count_1 + 1'b1 ;
                    value <= value ;
                    done <= 0 ;
                end
            end S2 : begin
                count_1 <= 0 ;
                value <= value ;
                done <= 1 ;
            end
        endcase

endmodule

module aceusb_access(
	/* Control */
	input ace_clkin,
	input rst,
	input [5:0] a,
	input [15:0] di,
	output reg [15:0] do,
	input read,
	input write,
	output reg ack,

	/* SystemACE/USB interface */
	output [6:0] aceusb_a,
	inout [15:0] aceusb_d,
	output reg aceusb_oe_n,
	output reg aceusb_we_n,

	output reg ace_mpce_n,
	input ace_mpirq,

	output usb_cs_n,
	output usb_hpi_reset_n,
	input usb_hpi_int
);

/* USB is not supported yet. Disable the chip. */
assign usb_cs_n = 1'b1;
assign usb_hpi_reset_n = 1'b1;

/* 16-bit mode only */
assign aceusb_a = {a, 1'b0};

reg d_drive;
assign aceusb_d = d_drive ? di : 16'hzz;

reg d_drive_r;
reg aceusb_oe_n_r;
reg aceusb_we_n_r;
reg ace_mpce_n_r;
always @(posedge ace_clkin) begin
	d_drive <= d_drive_r;
	aceusb_oe_n <= aceusb_oe_n_r;
	aceusb_we_n <= aceusb_we_n_r;
	ace_mpce_n <= ace_mpce_n_r;
end

reg d_in_sample;
always @(posedge ace_clkin)
	if(d_in_sample)
		do <= aceusb_d;

reg [2:0] state;
reg [2:0] next_state;

localparam
	IDLE = 3'd0,
	READ = 3'd1,
	READ1 = 3'd2,
	READ2 = 3'd3,
	WRITE = 3'd4,
	ACK = 3'd5;

always @(posedge ace_clkin) begin
	if(rst)
		state <= IDLE;
	else
		state <= next_state;
end

always @(*) begin
	d_drive_r = 1'b0;
	aceusb_oe_n_r = 1'b1;
	aceusb_we_n_r = 1'b1;
	ace_mpce_n_r = 1'b1;
	d_in_sample = 1'b0;
	ack = 1'b0;

	next_state = state;

	case(state)
		IDLE: begin
			if(read) begin
				ace_mpce_n_r = 1'b0;
				next_state = READ;
			end
			if(write) begin
				ace_mpce_n_r = 1'b0;
				next_state = WRITE;
			end
		end

		READ: begin
			ace_mpce_n_r = 1'b0;
			next_state = READ1;
		end
		READ1: begin
			ace_mpce_n_r = 1'b0;
			aceusb_oe_n_r = 1'b0;
			next_state = READ2;
		end
		READ2: begin
			d_in_sample = 1'b1;
			next_state = ACK;
		end

		WRITE: begin
			d_drive_r = 1'b1;
			ace_mpce_n_r = 1'b0;
			aceusb_we_n_r = 1'b0;
			next_state = ACK;
		end

		ACK: begin
			ack = 1'b1;
			next_state = IDLE;
		end
	endcase
end

endmodule

module and_gate_enable(
    output Y,
    input A1,
    input A2,
    input A3,
