module tone_detection_generation (
  input clk,
  input reset,
  input in,
  input tone_freq,
  output out,
  output tone_detected
);

parameter sampling_freq = 100000; // sampling frequency of input signal
parameter tone_threshold = 0.5; // threshold value for detecting tone frequency

// define bandpass filter coefficients
parameter [15:0] b0 = 16'h0000;
parameter [15:0] b1 = 16'h0000;
parameter [15:0] b2 = 16'h0000;
parameter [15:0] a1 = 16'h0000;
parameter [15:0] a2 = 16'h0000;

// define second bandpass filter coefficients
parameter [15:0] b0_tone = 16'h0000;
parameter [15:0] b1_tone = 16'h0000;
parameter [15:0] b2_tone = 16'h0000;
parameter [15:0] a1_tone = 16'h0000;
parameter [15:0] a2_tone = 16'h0000;

// other parameter declarations, if needed

reg [15:0] x1, x2, y1, y2, x1_tone, x2_tone, y1_tone, y2_tone;
reg [15:0] tone_amp;
reg tone_detected_reg;

always @(posedge clk) begin
  if (reset) begin
    x1 <= 0;
    x2 <= 0;
    y1 <= 0;
    y2 <= 0;
    x1_tone <= 0;
    x2_tone <= 0;
    y1_tone <= 0;
    y2_tone <= 0;
    tone_detected_reg <= 0;
    tone_amp <= 0;
  end else begin
    // bandpass filter to detect tone frequency
    x2 <= x1;
    x1 <= in;
    y2 <= y1;
    y1 <= (b0*x1 + b1*x2 + b2*x2 - a1*y2 - a2*y2) >> 16;

    // peak detector to detect peak value of filtered signal
    if (y1 > tone_amp) begin
      tone_amp <= y1;
    end else if (y1 < tone_amp*0.9) begin
      if (tone_amp > tone_threshold) begin
        tone_detected_reg <= 1;
      end else begin
        tone_detected_reg <= 0;
      end
      tone_amp <= 0;
    end

    // bandpass filter to generate tone frequency
    x2_tone <= x1_tone;
    x1_tone <= tone_amp*sin(2*3.141592*tone_freq/sampling_freq) + in;
    y2_tone <= y1_tone;
    y1_tone <= (b0_tone*x1_tone + b1_tone*x2_tone + b2_tone*x2_tone - a1_tone*y2_tone - a2_tone*y2_tone) >> 16;

    // output signal with detected and generated tone
    out <= y1_tone;
    tone_detected <= tone_detected_reg;
  end
end

endmodule

module clock_with_programmable_alarm (
  input clk,
  input reset,
  input [1:0] set_time, // 2-bit input for setting hours (00-23) and minutes (00-59)
  input [1:0] set_alarm, // 2-bit input for setting alarm hours (00-23) and minutes (00-59)
  input alarm_enable, // 1-bit input for enabling/disabling the alarm
  output reg [1:0] hh, // 2-bit output for displaying hours (00-23)
  output reg [1:0] mm, // 2-bit output for displaying minutes (00-59)
  output reg [1:0] ss, // 2-bit output for displaying seconds (00-59)
  output reg alarm_enabled // 1-bit output for indicating whether the alarm is currently enabled or disabled
);

reg [1:0] hours = 2'b0; // initialize hours to 00
reg [1:0] minutes = 2'b0; // initialize minutes to 00
reg [1:0] seconds = 2'b0; // initialize seconds to 00
reg [1:0] alarm_hours = 2'b0; // initialize alarm hours to 00
reg [1:0] alarm_minutes = 2'b0; // initialize alarm minutes to 00
reg alarm_triggered = 1'b0; // initialize alarm_triggered to 0

always @(posedge clk) begin
  if (reset) begin
    hours <= 2'b0;
    minutes <= 2'b0;
    seconds <= 2'b0;
    alarm_hours <= 2'b0;
    alarm_minutes <= 2'b0;
    alarm_triggered <= 1'b0;
    alarm_enabled <= 1'b0;
  end else begin
    // Update seconds
    if (seconds == 5'b10011) begin
      seconds <= 5'b0;
      // Update minutes
      if (minutes == 5'b10011) begin
        minutes <= 5'b0;
        // Update hours
        if (hours == 2'b1011) begin
          hours <= 2'b0;
        end else begin
          hours <= hours + 1;
        end
      end else begin
        minutes <= minutes + 1;
      end
    end else begin
      seconds <= seconds + 1;
    end

    // Check if alarm is triggered
    if (hours == alarm_hours && minutes == alarm_minutes && alarm_enabled) begin
      alarm_triggered <= 1'b1;
    end else begin
      alarm_triggered <= 1'b0;
    end
  end
end

always @(set_time, set_alarm) begin
  hours <= set_time[1:0];
  minutes <= set_time[3:2];
  alarm_hours <= set_alarm[1:0];
  alarm_minutes <= set_alarm[3:2];
end

always @(alarm_enable) begin
  alarm_enabled <= alarm_enable;
end

assign hh = hours;
assign mm = minutes;
assign ss = seconds;

endmodule

