module fp_adder_pipeline (
  input clk,
  input reset,
  input [31:0] A,
  input [31:0] B,
  output reg [31:0] Y
);

  // Stage 1: Sign and exponent alignment
  reg [30:0] exp_diff;
  reg [31:0] A_mantissa, B_mantissa, A_aligned, B_aligned;
  reg A_sign, B_sign, Y_sign;
  reg [7:0] A_exponent, B_exponent, Y_exponent;
  always @(posedge clk) begin
    if (reset) begin
      A_aligned <= 0;
      B_aligned <= 0;
      exp_diff <= 0;
      A_sign <= 0;
      B_sign <= 0;
      Y_sign <= 0;
      A_exponent <= 0;
      B_exponent <= 0;
      Y_exponent <= 0;
    end else begin
      A_mantissa <= A[22:0];
      B_mantissa <= B[22:0];
      A_sign <= A[31];
      B_sign <= B[31];
      A_exponent <= A[30:23];
      B_exponent <= B[30:23];
      exp_diff <= A_exponent - B_exponent;
      if (exp_diff > 0) begin
        A_aligned <= {1'b1, A_mantissa} << exp_diff;
        B_aligned <= {1'b0, B_mantissa};
        Y_exponent <= A_exponent;
        Y_sign <= A_sign;
      end else begin
        A_aligned <= {1'b0, A_mantissa};
        B_aligned <= {1'b1, B_mantissa} << -exp_diff;
        Y_exponent <= B_exponent;
        Y_sign <= B_sign;
      end
    end
  end

  // Stage 2: Mantissa addition
  reg [24:0] Y_mantissa;
  reg carry;
  always @(posedge clk) begin
    if (reset) begin
      Y_mantissa <= 0;
      carry <= 0;
    end else begin
      {carry, Y_mantissa} <= A_aligned[23:0] + B_aligned[23:0] + carry;
    end
  end

  // Stage 3: Normalization
  reg [6:0] shift_amount;
  always @(posedge clk) begin
    if (reset) begin
      shift_amount <= 0;
    end else begin
      if (Y_mantissa[24]) begin
        Y_mantissa <= Y_mantissa >> 1;
        Y_exponent <= Y_exponent + 1;
        shift_amount <= shift_amount + 1;
      end
    end
  end

  // Stage 4: Rounding
  always @(posedge clk) begin
    if (reset) begin
      Y[31] <= 0;
      Y[30:23] <= 0;
      Y[22:0] <= 0;
    end else begin
      if (Y_mantissa[23] && (Y_mantissa[22:0] != 7'h7f)) begin
        Y_mantissa <= Y_mantissa + 1;
        if (Y_mantissa[24]) begin
          Y_mantissa <= Y_mantissa >> 1;
          Y_exponent <= Y_exponent + 1;
          shift_amount <= shift_amount + 1;
        end
      end
      Y[31] <= Y_sign;
      Y[30:23] <= Y_exponent;
      Y[22:0] <= Y_mantissa[22:0];
    end
  end

  // Stage 5: Output
  assign Y = (A[30:0] == 8'h7f) ? A :
             (B[30:0] == 8'h7f) ? B :
             (A[30:0] == 8'h00) ? B :
             (B[30:0] == 8'h00) ? A :
             (A[30:0] == 8'h7f && A[22:0] != 0) ? A :
             (B[30:0] == 8'h7f && B[22:0] != 0) ? B :
             (A[30:0] == 8'h00 && A[22:0] != 0) ? B :
             (B[30:0] == 8'h00 && B[22:0] != 0) ? A :
             (A[30:0] == 8'h7f && B[30:0] == 8'h7f) ? A :
             (A[30:0] == 8'h00 && B[30:0] == 8'h00) ? A :
             (Y_exponent == 8'hff) ? {1'b1, 8'hff, 23'h0} :
             (shift_amount >= 23) ? {Y_sign, 8'h00, 23'h0} :
             {Y_sign, Y_exponent, Y_mantissa << shift_amount};

endmodule

