module mux4to1(D0, D1, D2, D3, S0, S1, Y);
   input D0, D1, D2, D3, S0, S1;
   output Y;

   wire notS0, notS1, notS0andS1, S0andnotS1, notS0andnotS1;

   //inverting select signals
   assign notS0 = ~S0;
   assign notS1 = ~S1;

   //creating intermediate signals for output
   assign notS0andS1 = notS0 & S1;
   assign S0andnotS1 = S0 & notS1;
   assign notS0andnotS1 = notS0 & notS1;

   //multiplexer output
   assign Y = D0 & notS0andnotS1 |
               D1 & S0andnotS1 |
               D2 & notS0andS1 |
               D3 & S0andS1;
endmodule

module system_io (
  input [1:0] address,
  input chipselect,
  input clk,
  input [3:0] in_port,
  input reset_n,
  input write_n,
  input [31:0] writedata,
  output irq,
  output [31:0] readdata
);

  wire clk_en;
  reg [3:0] d1_data_in;
  reg [3:0] d2_data_in;
  wire [3:0] data_in;
  reg [3:0] edge_capture;
  wire edge_capture_wr_strobe;
  wire [3:0] edge_detect;
  wire irq;
  reg [3:0] irq_mask;
  wire [3:0] read_mux_out;

  assign clk_en = 1;

  assign read_mux_out = ({4 {(address == 0)}} & data_in) |
                        ({4 {(address == 2)}} & irq_mask) |
                        ({4 {(address == 3)}} & edge_capture);

  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      readdata <= 0;
    end else if (clk_en) begin
      readdata <= {32'b0, read_mux_out};
    end
  end

  assign data_in = in_port;

  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      irq_mask <= 0;
    end else if (chipselect && ~write_n && (address == 2)) begin
      irq_mask <= writedata[3:0];
    end
  end

  assign irq = |(edge_capture & irq_mask);
  assign edge_capture_wr_strobe = chipselect && ~write_n && (address == 3);

  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      edge_capture <= 0;
    end else if (clk_en) begin
      if (edge_capture_wr_strobe && writedata[0]) begin
        edge_capture[0] <= 0;
      end else if (edge_detect[0]) begin
        edge_capture[0] <= -1;
      end
    end
  end

  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      edge_capture <= 0;
    end else if (clk_en) begin
      if (edge_capture_wr_strobe && writedata[1]) begin
        edge_capture[1] <= 0;
      end else if (edge_detect[1]) begin
        edge_capture[1] <= -1;
      end
    end
  end

  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      edge_capture <= 0;
    end else if (clk_en) begin
      if (edge_capture_wr_strobe && writedata[2]) begin
        edge_capture[2] <= 0;
      end else if (edge_detect[2]) begin
        edge_capture[2] <= -1;
      end
    end
  end

  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      edge_capture <= 0;
    end else if (clk_en) begin
      if (edge_capture_wr_strobe && writedata[3]) begin
        edge_capture[3] <= 0;
      end else if (edge_detect[3]) begin
        edge_capture[3] <= -1;
      end
    end
  end

  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      d1_data_in <= 0;
      d2_data_in <= 0;
    end else if (clk_en) begin
      d1_data_in <= data_in;
      d2_data_in <= d1_data_in;
    end
  end

  assign edge_detect = d1_data_in ^ d2_data_in;

endmodule

module shift_register (
    input [3:0] D,
    input LD,
    input SH,
    output reg [3:0] Q
);
    reg [3:0] stage1, stage2, stage3, stage4;

    always @(posedge clk) begin
        if (LD) begin
            stage1 <= D;
            stage2 <= stage1;
            stage3 <= stage2;
            stage4 <= stage3;
        end
        else if (SH) begin
            stage1 <= stage2;
            stage2 <= stage3;
            stage3 <= stage4;
            stage4 <= 4'b0000;
        end
        else begin
            stage1 <= stage1;
            stage2 <= stage1;
            stage3 <= stage2;
            stage4 <= stage3;
        end
    end

    assign Q = stage1;

endmodule

module interface_module(
    input wire D,
    input wire VPWR,
    input wire VGND,
    input wire VPB,
    input wire VNB,
    output wire Q,
    output wire Q_N,
    input wire GATE
);

    reg [4:0] count;
    reg [4:0] state;

    always @(posedge GATE) begin
        count <= count + 1;
        case (state)
            0: begin
                if (count == 4'd20) begin
                    D <= 1'b0;
                    state <= 1;
                end
            end
            1: begin
                if (count == 4'd40) begin
                    VGND <= 1'b0;
                    state <= 2;
                end
            end
            2: begin
                if (count == 4'd60) begin
                    VNB <= 1'b0;
                    state <= 3;
                end
            end
            3: begin
                if (count == 4'd80) begin
                    VPB <= 1'b0;
                    state <= 4;
                end
            end
            4: begin
                if (count == 4'd100) begin
                    VPWR <= 1'b0;
                    state <= 5;
                end
            end
            5: begin
                if (count == 4'd120) begin
                    D <= 1'b1;
                    state <= 6;
                end
            end
            6: begin
                if (count == 4'd140) begin
                    VGND <= 1'b1;
                    state <= 7;
                end
            end
            7: begin
                if (count == 4'd160) begin
                    VNB <= 1'b1;
                    state <= 8;
                end
            end
            8: begin
                if (count == 4'd180) begin
                    VPB <= 1'b1;
                    state <= 9;
                end
            end
            9: begin
                if (count == 4'd200) begin
                    VPWR <= 1'b1;
                    state <= 10;
                end
            end
            10: begin
                if (count == 4'd220) begin
                    D <= 1'b0;
                    state <= 11;
                end
            end
            11: begin
                if (count == 4'd240) begin
                    VGND <= 1'b0;
                    state <= 12;
                end
            end
            12: begin
                if (count == 4'd260) begin
                    VNB <= 1'b0;
                    state <= 13;
                end
            end
            13: begin
                if (count == 4'd280) begin
                    VPB <= 1'b0;
                    state <= 14;
                end
            end
            14: begin
                if (count == 4'd300) begin
                    VPWR <= 1'b0;
                    state <= 15;
                end
            end
            15: begin
                if (count == 4'd320) begin
                    VPWR <= 1'bx;
                    state <= 16;
                end
            end
            16: begin
                if (count == 4'd340) begin
                    VPB <= 1'bx;
                    state <= 17;
                end
            end
            17: begin
                if (count == 4'd360) begin
                    VNB <= 1'bx;
                    state <= 18;
                end
            end
            18: begin
                if (count == 4'd380) begin
                    VGND <= 1'bx;
                    state <= 19;
                end
            end
            19: begin
                if (count == 4'd400) begin
                    D <= 1'b1;
                    state <= 20;
                end
            end
            20: begin
                if (count == 4'd420) begin
                    VPWR <= 1'bx;
                    VPB <= 1'bx;
                    VNB <= 1'bx;
                    VGND <= 1'bx;
                    state <= 21;
                end
            end
            21: begin
                if (count == 4'd440) begin
                    D <= 1'bx;
                    state <= 22;
                end
            end
            22: begin
                if (count == 4'd500) begin
                    $finish;
                end
            end
        endcase
    end

    sky130_fd_sc_ls__dlxbp dut (.D(D), .VPWR(VPWR), .VGND(VGND), .VPB(VPB), .VNB(VNB), .Q(Q), .Q_N(Q_N), .GATE(GATE));

endmodule

