module memory(input clk,
              input rst,
              input [31:0] addr_a,
              input [31:0] addr_b,
              input [31:0] data_b_in,
              input [31:0] data_b_we,
              output reg [31:0] data_a,
              output reg [31:0] data_b,
              output reg strobe_b);

   parameter RAM_DEPTH = 1024;
   parameter INIT_FILE = "";

   reg [31:0] mem [0:RAM_DEPTH-1];

   initial begin
      if (INIT_FILE != "")
         $readmemh(INIT_FILE, mem);
   end

   always @(posedge clk) begin
      if (rst) begin
         data_a <= 0;
         data_b <= 0;
         strobe_b <= 0;
      end
      else begin
         if (data_b_we & (addr_b[31:16] == 0)) begin
            mem[addr_b] <= data_b_in;
         end
         data_a <= mem[addr_a];
         data_b <= mem[addr_b];
         strobe_b <= (addr_b[31:16] == 0) ? data_b_we : 0;
      end
   end

endmodule

module decoder (
    input enable,
    input [1:0] in,
    output reg [3:0] out
);

reg [1:0] stage1_out;
reg [3:0] stage2_out;

always @ (posedge enable) begin
    stage1_out <= in;
end

always @ (posedge enable) begin
    case (stage1_out)
        2'b00: stage2_out <= 4'b0001;
        2'b01: stage2_out <= 4'b0010;
        2'b10: stage2_out <= 4'b0100;
        2'b11: stage2_out <= 4'b1000;
        default: stage2_out <= 4'b0000;
    endcase
end

assign out = stage2_out;

endmodule

