module top_module(
    input wire [7:0] in,
    input wire control,
    output wire out
);

wire [7:0] right_shift_out;
wire [7:0] left_shift_out;
wire [7:0] combined_out;
wire select;

// instantiate the two barrel shifters
barrel_shifter_right right_shift(
    .in(in),
    .out(right_shift_out)
);

barrel_shifter_left left_shift(
    .in(in),
    .out(left_shift_out)
);

// instantiate the XOR gate to combine the outputs of the shifters
assign combined_out = right_shift_out ^ left_shift_out;

// instantiate the select module to choose which shifter output to use
select_module select_inst(
    .in1(right_shift_out),
    .in2(left_shift_out),
    .out(combined_out),
    .select(select)
);

// instantiate the AND gate to produce the final output
and_gate and_inst(
    .in(combined_out),
    .control(control),
    .out(out)
);

endmodule

