module my_module (
  input clk,
  input [24:0] cpu_d_address,
  input cpu_d_read,
  input [31:0] cpu_d_readdata,
  input cpu_d_wait,
  input cpu_d_write,
  input [31:0] cpu_d_writedata,
  input jrst_n,
  input [15:0] trc_ctrl,
  output reg [35:0] atm,
  output reg [35:0] dtm
);

  reg [35:0] atm_reg;
  reg [35:0] dtm_reg;
  wire [31:0] cpu_d_address_0_padded;
  wire [31:0] cpu_d_readdata_0_padded;
  wire [31:0] cpu_d_writedata_0_padded;
  wire record_load_addr;
  wire record_store_addr;
  wire record_load_data;
  wire record_store_data;
  wire [3:0] td_mode_trc_ctrl;

  assign cpu_d_address_0_padded = {cpu_d_address, 1'b0};
  assign cpu_d_readdata_0_padded = {cpu_d_readdata, 1'b0};
  assign cpu_d_writedata_0_padded = {cpu_d_writedata, 1'b0};

  mi_nios_cpu_nios2_oci_td_mode mi_nios_cpu_nios2_oci_trc_ctrl_td_mode (
    .ctrl(trc_ctrl[8:0]),
    .td_mode(td_mode_trc_ctrl)
  );
  assign {record_load_addr, record_store_addr, record_load_data, record_store_data} = td_mode_trc_ctrl;

  always @(posedge clk or negedge jrst_n) begin
    if (~jrst_n) begin
      atm_reg <= 0;
      dtm_reg <= 0;
    end else begin
      if (cpu_d_write & ~cpu_d_wait & record_store_addr) begin
        atm_reg <= {4'b0101, cpu_d_address_0_padded};
      end else if (cpu_d_read & ~cpu_d_wait & record_load_addr) begin
        atm_reg <= {4'b0100, cpu_d_address_0_padded};
      end else begin
        atm_reg <= {4'b0000, cpu_d_address_0_padded};
      end

      if (cpu_d_write & ~cpu_d_wait & record_store_data) begin
        dtm_reg <= {4'b0111, cpu_d_writedata_0_padded};
      end else if (cpu_d_read & ~cpu_d_wait & record_load_data) begin
        dtm_reg <= {4'b0110, cpu_d_readdata_0_padded};
      end else begin
        dtm_reg <= {4'b0000, cpu_d_readdata_0_padded};
      end
    end
  end

  assign atm = atm_reg;
  assign dtm = dtm_reg;

endmodule

module sky130_fd_sc_hdll__a21o (
