module alu(
    input [31:0] A,
    input [31:0] B,
    input [2:0] ALU_operation,
    output [31:0] res,
    output zero,
    output reg overflow
);

    wire [31:0] res_and, res_or, res_add, res_sub, res_nor, res_slt, res_xor;
    reg [31:0] res_op;
    parameter one = 32'h00000001, zero_0 = 32'h00000000;

    assign res_and = A & B;
    assign res_or = A | B;
    assign res_add = A + B;
    assign res_sub = A - B;
    assign res_nor = ~(A | B);
    assign res_slt = (A < B) ? one : zero_0;
    assign res_xor = A ^ B;
    assign res = res_op[31:0];

    always @(*) begin
        overflow = 0;
        case(ALU_operation)
            3'b000: res_op = res_and;
            3'b001: res_op = res_or;
            3'b010: begin
                        res_op = res_add;
                        if ((A[31:31] & B[31:31] & ~res_op[31:31]) | (~A[31:31] & ~B[31:31] & res_op[31:31]))
                            overflow = 1;
                    end
            3'b110: begin
                        res_op = res_sub;
                        if ((A[31:31] & ~B[31:31] & ~res_op[31:31]) | (~A[31:31] & B[31:31] & res_op[31:31]))
                            overflow = 1;
                    end
            3'b100: res_op = res_nor;
            3'b111: res_op = res_slt;
            3'b101: res_op = A >> 1;
            3'b011: res_op = res_xor;
            default: res_op = 32'hxxxxxxxx;
        endcase
    end

    assign zero = (res == 0) ? 1 : 0;

endmodule

module fx2_to_bus
#(
    parameter                   WIDTH = 16 // 16 bit bus from FX2
) (
    input wire [WIDTH-1:0]      ADD,
    input wire                  RD_B, // neg active, two clock cycles
    input wire                  WR_B, // neg active

    input wire                  BUS_CLK, // FCLK
    output wire [WIDTH-1:0]     BUS_ADD,
    output wire                 BUS_RD,
    output wire                 BUS_WR,
    output wire                 CS_FPGA
);

// remove offset from FX2
assign BUS_ADD = ADD - 16'h4000;

// chip select FPGA
