// generate read strobe which one clock cycle long
// this is very important to prevent corrupted data
reg RD_B_FF;
always @ (posedge BUS_CLK) begin
    RD_B_FF <= RD_B;
end
assign BUS_RD = ~RD_B & RD_B_FF;

assign BUS_WR = ~WR_B;

endmodule

