     endcase

//clock divider 
always  @ (posedge clk)
   begin
	clkdiv <= clkdiv + 20'b1;
    end 

endmodule

module booth_multiplier (
    input signed [7:0] a,
    input signed [7:0] b,
    input [1:0] sel,
    input en,
    output signed [15:0] prod
);

    wire [15:0] temp_prod;
    wire [7:0] temp_a;
    wire [7:0] temp_b;
    wire [8:0] booth_array;

    // 4-to-16 decoder with active-low outputs
    decoder_4to16 dec (
        .in(sel),
        .en(en),
        .out({temp_a, ~temp_a, temp_b, ~temp_b, temp_a, ~temp_a, temp_b, ~temp_b, temp_a, ~temp_a, temp_b, ~temp_b, temp_a, ~temp_a, temp_b, ~temp_b})
    );

    // Booth's algorithm implementation
    booth_multiplier_impl booth (
        .a(temp_a),
        .b(temp_b),
        .booth_array(booth_array),
        .temp_prod(temp_prod)
    );

    assign prod = temp_prod;

    // assign inputs based on select input
    assign temp_a = (sel == 2'b00) ? a : -a;
    assign temp_b = (sel == 2'b01) ? b : -b;

endmodule

module decoder_4to16 (
    input [1:0] in,
    input en,
    output [15:0] out
);

    assign out = (en) ? ~(1 << (in * 4)) : 16'hFFFF;

endmodule

module booth_multiplier_impl (
    input signed [7:0] a,
    input signed [7:0] b,
    output reg signed [15:0] temp_prod,
    output reg [8:0] booth_array
);

    always @(*) begin
        booth_array[8] = 1'b0;
        booth_array[7:0] = {b, 1'b0};
    end

    always @(posedge booth_array[0]) begin
        if (booth_array[1] == 1'b0) begin
            temp_prod <= temp_prod + a;
        end else begin
            temp_prod <= temp_prod - a;
        end

        if (temp_prod[15] == 1'b1) begin
            temp_prod <= temp_prod - {b, 1'b0};
        end else begin
            temp_prod <= temp_prod + {b, 1'b0};
        end

        booth_array <= {booth_array[7:0], booth_array[8]};
    end

endmodule

module Async_Reset_Release (
  input reset,
  input clk,
  input [7:0] delay,
  output reg reset_release
);

  reg [7:0] counter;

  always @(posedge clk) begin
