module i2c_state_machine (
  input SCL,
  input SDA,
  input i_reset,
  output o_busy,
  output o_error,
  output [7:0] o_data
);

parameter clock_freq = 100000000; // 100 MHz
parameter bit_rate = 100000; // 100 kHz

reg [7:0] data_reg;
reg [2:0] state_reg;
reg ack_reg;
reg start_reg;
reg stop_reg;
reg bit_reg;
reg byte_reg;
reg timeout_reg;

wire SDA_out;
assign o_data = data_reg;
assign o_busy = (state_reg != 0);
assign o_error = timeout_reg;

localparam IDLE = 0;
localparam START = 1;
localparam ADDR = 2;
localparam ACK = 3;
localparam DATA = 4;
localparam READ = 5;
localparam STOP = 6;

always @(posedge SCL or posedge i_reset) begin
  if (i_reset) begin
    state_reg <= IDLE;
    start_reg <= 0;
    stop_reg <= 0;
    bit_reg <= 0;
    byte_reg <= 0;
    timeout_reg <= 0;
    ack_reg <= 0;
    data_reg <= 0;
  end else begin
    case (state_reg)
      IDLE: begin
        if (!SCL && SDA) begin
          start_reg <= 1;
          state_reg <= START;
        end
      end
      START: begin
        if (SCL && start_reg) begin
          start_reg <= 0;
          SDA_out <= 0;
          state_reg <= ADDR;
        end
      end
      ADDR: begin
        if (SCL && !bit_reg) begin
          bit_reg <= 1;
          SDA_out <= (byte_reg[7] == 1);
        end else if (SCL && bit_reg) begin
          bit_reg <= 0;
          byte_reg <= byte_reg << 1;
          if (SDA) byte_reg[0] <= 1;
          if (bit_reg == 7) begin
            SDA_out <= 1;
            state_reg <= ACK;
          end
        end
      end
      ACK: begin
        if (SCL) begin
          ack_reg <= SDA;
          if (ack_reg == 0) begin
            if (byte_reg[7] == 1) begin
              state_reg <= READ;
            end else begin
              state_reg <= DATA;
            end
          end else begin
            timeout_reg <= 1;
            state_reg <= IDLE;
          end
        end
      end
      DATA: begin
        if (SCL && !bit_reg) begin
          bit_reg <= 1;
          SDA_out <= (data_reg[7] == 1);
        end else if (SCL && bit_reg) begin
          bit_reg <= 0;
          data_reg <= data_reg << 1;
          if (SDA) data_reg[0] <= 1;
          if (bit_reg == 7) begin
            SDA_out <= 1;
            state_reg <= ACK;
          end
        end
      end
      READ: begin
        if (SCL && !bit_reg) begin
          bit_reg <= 1;
          SDA_out <= 1;
        end else if (SCL && bit_reg) begin
          bit_reg <= 0;
          data_reg <= data_reg << 1;
          if (SDA) data_reg[0] <= 1;
          if (bit_reg == 7) begin
            SDA_out <= 0;
            state_reg <= ACK;
          end
        end
      end
      STOP: begin
        if (SCL && stop_reg) begin
          stop_reg <= 0;
          SDA_out <= 1;
          state_reg <= IDLE;
        end
      end
    endcase
  end
end

always @(posedge SCL or posedge i_reset) begin
  if (i_reset) begin
    timeout_reg <= 0;
  end else begin
    if (SCL) begin
      timeout_reg <= 0;
    end else if (timeout_reg == 0) begin
      timeout_reg <= 1;
    end
  end
end

always @(posedge SCL or posedge i_reset) begin
  if (i_reset) begin
    byte_reg <= 0;
  end else begin
    if (state_reg == START || state_reg == ADDR) begin
      byte_reg <= 0;
    end
  end
end

always @(posedge SCL or posedge i_reset) begin
  if (i_reset) begin
    data_reg <= 0;
  end else begin
    if (state_reg == DATA || state_reg == READ) begin
      data_reg <= 0;
    end
  end
end

always @(posedge SCL or posedge i_reset) begin
  if (i_reset) begin
    stop_reg <= 0;
  end else begin
    if (state_reg == DATA || state_reg == READ) begin
      stop_reg <= 0;
