            comparison_result = 3'b001;
        end else if (a < b) begin
            comparison_result = 3'b010;
        end else begin
            comparison_result = 3'b100;
        end
    end

endmodule

module and_xnor_inv ( a, b, g_out, p_out );
  input a, b;
  output g_out, p_out;
  wire   n3;

  // Inverter
  not U1 ( .A(a), .ZN(n3) );

  // AND gate
  and U2 ( .A1(a), .A2(b), .ZN(g_out) );

  // XNOR gate
  xnor U3 ( .A(n3), .B(b), .ZN(p_out) );
endmodule

