module vga_to_rgb
   (clk_25,
    xaddr,
    yaddr,
    rgb);
  input clk_25;
  input [9:0]xaddr;
  input [9:0]yaddr;
  output [23:0]rgb;

  wire clk_25;
  wire [23:0]rgb_temp ;
  wire [9:0]xaddr;
  wire [9:0]yaddr;

  assign rgb[23:16] = rgb_temp[23:16];
  assign rgb[15:8] = rgb_temp[15:8];
  assign rgb[7:0] = rgb_temp[7:0];

  reg [2:0] state;
  reg [4:0] r_count;
  reg [5:0] g_count;
  reg [4:0] b_count;
  reg [4:0] r_data;
  reg [5:0] g_data;
  reg [4:0] b_data;

  always @(posedge clk_25) begin
    case (state)
      0: begin
        r_count <= 0;
        g_count <= 0;
        b_count <= 0;
        r_data <= 0;
        g_data <= 0;
        b_data <= 0;
        state <= 1;
      end
      1: begin
        if (xaddr >= 640) begin
          state <= 0;
        end else begin
          r_data <= {r_data[3:0], rgb_temp[4]};
          g_data <= {g_data[4:0], rgb_temp[10:5]};
          b_data <= {b_data[3:0], rgb_temp[15:11]};
          if (r_count == 7) begin
            rgb_temp[23:16] <= {rgb_temp[23:16], r_data};
            r_count <= 0;
          end else begin
            r_count <= r_count + 1;
          end
          if (g_count == 3) begin
            rgb_temp[15:8] <= {rgb_temp[15:8], g_data};
            g_count <= 0;
          end else begin
            g_count <= g_count + 1;
          end
          if (b_count == 7) begin
            rgb_temp[7:0] <= {rgb_temp[7:0], b_data};
            b_count <= 0;
          end else begin
            b_count <= b_count + 1;
          end
          xaddr <= xaddr + 1;
        end
      end
    endcase
  end
endmodule

module gray_to_binary_decoder (
  input [width-1:0] gin,
  output [width-1:0] bout
);
  reg [width-1:0] breg;
  integer i;

  assign bout = breg;

  always @ (gin) begin
    breg[width-1] = gin[width-1];
    for (i = width-2; i >= 0; i = i - 1)
      breg[i] = gin[i] ^ breg[i+1];
  end
endmodule

module piso_shift_register (
    input clk, reset_n, load_a, load_b, shift,
    input [7:0] par_in_a, par_in_b,
    output reg ser_out
);

reg [7:0] shift_reg;

always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
        shift_reg <= 8'b0;
        ser_out <= 1'b0;
    end
    else begin
        if (load_a) begin
            shift_reg <= par_in_a;
        end
        else if (load_b) begin
            shift_reg <= par_in_b;
        end
        else if (shift) begin
            shift_reg <= {shift_reg[6:0], shift_reg[7]};
            ser_out <= shift_reg[0];
        end
    end
end

endmodule

module vending_machine_controller(
    input clk,
    input reset,
    input [1:0] coin,
    input [1:0] button,
    output reg dispense,
    output reg [1:0] product,
    output reg [3:0] display
);

parameter PRODUCT_1_PRICE = 4'd10;
parameter PRODUCT_2_PRICE = 4'd15;
parameter PRODUCT_3_PRICE = 4'd20;
parameter PRODUCT_4_PRICE = 4'd25;

parameter NICKEL_VALUE = 4'd1;
parameter DIME_VALUE = 4'd2;
parameter QUARTER_VALUE = 4'd5;

reg [3:0] money_inserted;
reg [3:0] product_price;
reg [1:0] selected_product;

always @(*) begin
    case (button)
        2'b00: selected_product = 2'b00;
        2'b01: selected_product = 2'b01;
        2'b10: selected_product = 2'b10;
        2'b11: selected_product = 2'b11;
    endcase
end

always @(posedge clk) begin
    if (reset) begin
        money_inserted <= 4'd0;
        product_price <= 4'd0;
        dispense <= 1'b0;
        product <= 2'b00;
        display <= 4'd0;
    end else begin
        case (selected_product)
            2'b01: product_price <= PRODUCT_1_PRICE;
            2'b10: product_price <= PRODUCT_2_PRICE;
            2'b11: product_price <= PRODUCT_3_PRICE;
            default: product_price <= PRODUCT_4_PRICE;
        endcase

        case (coin)
            2'b01: money_inserted <= money_inserted + NICKEL_VALUE;
            2'b10: money_inserted <= money_inserted + DIME_VALUE;
            2'b11: money_inserted <= money_inserted + QUARTER_VALUE;
        endcase

        display <= money_inserted;

        if (money_inserted >= product_price) begin
            dispense <= 1'b1;
            product <= selected_product;
            money_inserted <= money_inserted - product_price;
            display <= 4'd0;
        end else begin
            dispense <= 1'b0;
            product <= 2'b00;
        end
    end
end

endmodule

module flow_led
#(parameter LEN = 5, NUM = 5)
(
    input power,
    input sig_ring,
    input sig_step,
    output reg [(NUM-1):0] alarm_light
);

    reg [31:0] count;

    // 1: representation for ring on
    // 0: representaion for ring off
    reg alarm;

    initial begin
        alarm <= 0;
        count <= 0;
        alarm_light <= 0;
    end

    always @(posedge sig_step) begin
        if (power) begin
            if (sig_ring) begin
                count = 0;
                alarm = 1;
                alarm_light = 1;
            end else begin
                if (alarm == 1) begin
                    count = count + 1;
                    alarm_light = alarm_light * 2 ? alarm_light * 2 : 1;
                end
                if (count == LEN) begin
                    count = 0;
                    alarm = 0;
                    alarm_light = 0;
                end
            end
        end else begin
            count = 0;
            alarm = 0;
            alarm_light = 0;
        end
    end

endmodule

module fifo_64in_out_blk_mem_gen
   (dout,
    wr_clk,
    rd_clk,
    I1,
    tmp_ram_rd_en,
    Q,
    O2,
    O1,
    din);
  output [63:0]dout;
  input wr_clk;
  input rd_clk;
  input I1;
  input tmp_ram_rd_en;
  input [0:0]Q;
  input [11:0]O2;
  input [11:0]O1;
  input [63:0]din;

  wire [7:0] data [0:7];
  reg [2:0] read_address;
  reg [2:0] write_address;
  reg [2:0] num_entries;
  reg [2:0] next_write_address;
  reg [2:0] next_num_entries;
  reg [7:0] read_data;
  reg [7:0] write_data;
  reg write_enable;
  reg read_enable;

  // Write logic
  always @(posedge wr_clk) begin
    if (I1 && (num_entries < 8)) begin
      data[write_address] <= din[7:0];
      next_write_address <= write_address + 1;
      next_num_entries <= num_entries + 1;
      write_enable <= 1;
    end else begin
      write_enable <= 0;
    end
  end

  // Read logic
  always @(posedge rd_clk) begin
    if (tmp_ram_rd_en && (num_entries > 0)) begin
      read_data <= data[Q];
      next_num_entries <= num_entries - 1;
      read_enable <= 1;
    end else begin
      read_enable <= 0;
    end
  end

  // Update state
  always @(*) begin
    if (write_enable) begin
      write_address <= next_write_address;
      num_entries <= next_num_entries;
    end
  end

  // Output data
  assign dout = {56'h0, read_data};

endmodule

module ripple_carry_adder(A, B, C_in, S, C_out);
  input [3:0] A, B;
  input C_in;
  output [3:0] S;
  output C_out;

  wire [3:0] sum;
  wire [3:0] carry;

  assign sum = A + B + C_in;
  assign carry = (A & B) | (C_in & (A | B));

  assign S = sum;
  assign C_out = carry[3];

endmodule

