module rotator(
    input clk,
    input load,
    input [1:0] ena,
    input [99:0] data,
    output reg [99:0] q,
    output reg [99:0] q_out);

    reg [99:0] shift_reg;
    reg [4:0] shift_amt;

    always @ (posedge clk) begin
        if (load) begin
            shift_reg <= data;
            shift_amt <= 0;
        end else if (ena == 2'b01) begin
            shift_reg <= {shift_reg[0], shift_reg[99:1]};
            shift_amt <= shift_amt + 1;
        end else if (ena == 2'b10) begin
            shift_reg <= {shift_reg[99], shift_reg[98:0]};
            shift_amt <= shift_amt - 1;
        end
    end

    assign q = shift_reg;
    assign q_out = (ena == 2'b01) ? {shift_reg[0], shift_reg[99:1]} :
                   (ena == 2'b10) ? {shift_reg[99], shift_reg[98:0]} :
                   shift_reg;

endmodule

module synchronized_data_module (
    Q,
    CLK,
    D,
    RESET_B,
    VPWR,
    VGND,
    VPB,
    VNB
);

    output Q;
    input CLK, D, RESET_B, VPWR, VGND, VPB, VNB;

    reg Q;

    // Synchronize the data input with the system clock
    always @(posedge CLK or negedge RESET_B) begin
        if (~RESET_B) begin
            Q <= 1'b0; // Reset to default value
        end else begin
            Q <= D;
        end
    end

endmodule

module decoder_4to2 (
    VPWR,
    VGND,
    VPB ,
    VNB ,
    in,
    out,
    reset
);

    // Module ports
    input VPWR;
    input VGND;
    input VPB ;
    input VNB ;
    input [3:0] in;
    output reg [1:0] out;
    input reset;

    // Reset behavior
    always @ (posedge reset) begin
        out <= 2'b11;
    end

    // Decoder logic
    always @ (*) begin
        case (in)
            4'b0001: out <= 2'b10;
            4'b0010: out <= 2'b01;
            4'b0100: out <= 2'b00;
            4'b1000: out <= 2'b00;
            default: out <= 2'b11;
        endcase
    end

endmodule

module shift_reg_decoder(
    input clk,
    input d,
    input [255:0] in,
    input [7:0] sel,
    output [7:0] out
);

    reg [2:0] shift_reg;
    wire [15:0] decoder_out;

    // Shift register implementation using D flip-flop and multiplexer
    always @(posedge clk) begin
        shift_reg <= {shift_reg[1:0], d};
    end

    assign decoder_out = (sel == 8'h00) ? in[255:240] :
                         (sel == 8'h01) ? in[239:224] :
                         (sel == 8'h02) ? in[223:208] :
                         (sel == 8'h03) ? in[207:192] :
                         (sel == 8'h04) ? in[191:176] :
                         (sel == 8'h05) ? in[175:160] :
                         (sel == 8'h06) ? in[159:144] :
                         (sel == 8'h07) ? in[143:128] :
                         (sel == 8'h08) ? in[127:112] :
                         (sel == 8'h09) ? in[111:96] :
                         (sel == 8'h0A) ? in[95:80] :
                         (sel == 8'h0B) ? in[79:64] :
                         (sel == 8'h0C) ? in[63:48] :
                         (sel == 8'h0D) ? in[47:32] :
                         (sel == 8'h0E) ? in[31:16] :
                                          in[15:0];

    // Functional module to select bits from shift register based on decoder output
    always @(*) begin
        case(decoder_out)
            16'h0001: out = {shift_reg[2], shift_reg[1], shift_reg[0], 5'b0};
            16'h0002: out = {shift_reg[2], shift_reg[1], 5'b0, shift_reg[0]};
            16'h0004: out = {shift_reg[2], 5'b0, shift_reg[1], shift_reg[0]};
            16'h0008: out = {5'b0, shift_reg[2], shift_reg[1], shift_reg[0]};
            16'h0010: out = {shift_reg[1], shift_reg[0], shift_reg[2], 5'b0};
            16'h0020: out = {shift_reg[1], shift_reg[0], 5'b0, shift_reg[2]};
            16'h0040: out = {shift_reg[1], 5'b0, shift_reg[0], shift_reg[2]};
            16'h0080: out = {5'b0, shift_reg[1], shift_reg[0], shift_reg[2]};
            default: out = 8'b0;
        endcase
    end

endmodule

module restoring_divider (
    input clk,
    input reset,
    input [3:0] dividend,
    input [3:0] divisor,
    output reg [3:0] quotient,
    output reg [3:0] remainder,
    output reg done
);

reg [7:0] dividend_reg;
reg [7:0] divisor_reg;
reg [7:0] quotient_reg;
reg [7:0] remainder_reg;
reg [2:0] count;
reg [1:0] state;

parameter idle = 2'b00;
parameter divide = 2'b01;
parameter subtract = 2'b10;

always @(posedge clk) begin
    if (reset) begin
        count <= 0;
        state <= idle;
        done <= 0;
    end else begin
        case (state)
            idle: begin
                dividend_reg <= {dividend, 4'b0};
                divisor_reg <= {divisor, 4'b0};
                quotient_reg <= 0;
                remainder_reg <= 0;
                count <= 0;
                state <= divide;
            end
            divide: begin
                quotient_reg[count] <= 1;
                remainder_reg <= dividend_reg;
                state <= subtract;
            end
            subtract: begin
                if (remainder_reg >= divisor_reg) begin
                    remainder_reg <= remainder_reg - divisor_reg;
                    quotient_reg[count] <= 0;
                end
                count <= count + 1;
                if (count == 4) begin
                    quotient <= quotient_reg[3:0];
                    remainder <= remainder_reg[3:0];
                    done <= 1;
                    state <= idle;
                end else begin
                    state <= divide;
                end
            end
        endcase
    end
end

endmodule

module bcd_converter (
    input [3:0] binary,
    output [3:0] bcd_high,
    output [3:0] bcd_low
);

always @(*) begin
    case (binary)
        4'b0000: begin
            bcd_high = 4'b0000;
            bcd_low = 4'b0000;
