module bcd_adder (
    input [3:0] bcd_a_high,
    input [3:0] bcd_a_low,
    input [3:0] bcd_b_high,
    input [3:0] bcd_b_low,
    output [3:0] bcd_sum_high,
    output [3:0] bcd_sum_low
);

reg [3:0] sum_high;
reg [3:0] sum_low;
reg [3:0] carry;

always @(*) begin
    sum_low = bcd_a_low + bcd_b_low;
    if (sum_low > 9) begin
        carry[0] = 1;
        sum_low = sum_low - 10;
    end else begin
        carry[0] = 0;
    end
    sum_high = bcd_a_high + bcd_b_high + carry;
    if (sum_high > 9) begin
        bcd_sum_high = 4'b0000;
        bcd_sum_low = 4'b0000;
    end else begin
        bcd_sum_high = sum_high;
        bcd_sum_low = sum_low;
    end
end

