reg [15:0] quantizer;
reg [15:0] error;

always @(posedge c_mod) begin
  integrator <= integrator + error;
  if (mod_bit) begin
    if (invert) begin
      error <= (d ^ {16{1'b1}}) - quantizer;
    end else begin
      error <= d - quantizer;
    end
  end else begin
    error <= d - quantizer;
  end
end

always @(posedge c) begin
  if (integrator[15]) begin
    quantizer <= {16{1'b1}};
  end else begin
    quantizer <= {16{1'b0}};
  end
  sd_d <= integrator[15:0];
  sd_dv <= 1'b1;
end

