module pipeline_stage (
  input signed [31:0] partial_remainder,
  input signed [31:0] partial_quotient,
  input signed [31:0] divisor,
  input signed_div,
  output signed [31:0] next_partial_remainder,
  output signed [31:0] next_partial_quotient
);

  wire signed [31:0] neg_divisor = -divisor; // negate divisor for restoring algorithm

  // calculate the quotient digit and remainder for this stage
  wire signed [31:0] dividend_digit = {partial_remainder, partial_quotient};
  wire signed [31:0] quotient_digit;
  wire signed [31:0] remainder_digit;
  assign {quotient_digit, remainder_digit} = signed_div ? dividend_digit / neg_divisor : dividend_digit / divisor;

  // calculate the next partial remainder and partial quotient
  wire signed [31:0] restored_remainder = signed_div ? remainder_digit - (dividend_digit < 0 ? neg_divisor : divisor) : remainder_digit;
  assign next_partial_remainder = restored_remainder >> 1;
  assign next_partial_quotient = quotient_digit << 1;

endmodule
module pipelined_divider (
  input signed [31:0] dividend,
  input signed [31:0] divisor,
  input clk,
  input rst,
  output signed [31:0] quotient,
  output signed [31:0] remainder
);

parameter k = 4; // number of pipeline stages
parameter signed_div = 1; // signed division

  reg signed [31:0] partial_remainder [0:k-1]; // partial remainder for each stage
  reg signed [31:0] partial_quotient [0:k-1]; // partial quotient for each stage

  // instantiate pipeline stages
  pipeline_stage stages [0:k-1](
    .partial_remainder(partial_remainder[k-2:0]),
    .partial_quotient(partial_quotient[k-2:0]),
    .divisor(divisor),
    .signed_div(signed_div),
    .next_partial_remainder(partial_remainder[k-1]),
    .next_partial_quotient(partial_quotient[k-1])
  );

  always @(posedge clk) begin
    if (rst) begin
      // reset partial remainder and quotient to zero
      partial_remainder <= {k{1'b0}};
      partial_quotient <= {k{1'b0}};
      quotient <= 0;
      remainder <= 0;
    end else begin
      // shift partial remainder and quotient to next stage
      partial_remainder <= {partial_remainder[k-2:0], stages[k-1].next_partial_remainder};
      partial_quotient <= {partial_quotient[k-2:0], stages[k-1].next_partial_quotient};

      if ($signed(partial_quotient[k-1]) != 0) begin
        // division completed, set final quotient and remainder
        quotient <= partial_quotient[k-1];
        remainder <= partial_remainder[k-1];
      end
    end
  end

endmodule

