module matrix_multiplier(
    input clk,
    input reset,
    input [15:0] matrix_a,
    input [15:0] matrix_b,
    input load_a,
    input load_b,
    output reg [15:0] matrix_out,
    output reg ready
);

reg [15:0] a_reg, b_reg;
reg [3:0] a_row, b_col;
reg [31:0] sum;
reg [1:0] state;

always @(posedge clk) begin
    if(reset) begin
        a_reg <= 0;
        b_reg <= 0;
        a_row <= 0;
        b_col <= 0;
        sum <= 0;
        state <= 2'b00;
        ready <= 0;
    end else begin
        case(state)
            2'b00: begin // Wait for both matrices to be loaded
                if(load_a && load_b) begin
                    a_reg <= matrix_a;
                    b_reg <= matrix_b;
                    a_row <= 0;
                    b_col <= 0;
                    sum <= 0;
                    state <= 2'b01;
                end else begin
                    ready <= 1;
                end
            end
            2'b01: begin // Multiply current element and add to sum
                sum <= sum + a_reg[a_row*4+b_col]*b_reg[b_col*4+a_row];
                if(b_col == 3) begin
                    b_col <= 0;
                    if(a_row == 3) begin
                        matrix_out <= sum;
                        sum <= 0;
                        state <= 2'b00;
                    end else begin
                        a_row <= a_row + 1;
                        b_col <= 0;
                    end
                end else begin
                    b_col <= b_col + 1;
                end
            end
        endcase
    end
end

endmodule

