    input [7:0] in1,  // Second input to the 4-to-1 multiplexer
    input [7:0] in2,  // Third input to the 4-to-1 multiplexer
    input [7:0] in3,  // Fourth input to the 4-to-1 multiplexer
    input [1:0] sel,  // 2-bit select input to the 4-to-1 multiplexer
    input en,         // 1-bit enable input to the 4-to-1 multiplexer
    input enable,     // 1-bit asynchronous enable input to the counter module
    output [7:0] out  // 8-bit output from the functional module
);

// Instantiate the 4-to-1 multiplexer module
