module MMU (
  input [n-1:0] v_addr,
  input rw,
  input [m-1:0] data_in,
  input cs,
  input [2^n-1:0] mem_map,
  output reg [m-1:0] p_addr,
  output reg [m-1:0] data_out
);

parameter n = 16; // number of bits in virtual address
parameter m = 32; // number of bits in physical address and data

reg [m-1:0] phys_addr [2**n-1:0];

// Generate physical address table
integer i;
always @(*) begin
  for (i = 0; i < 2**n; i = i + 1) begin
    if (cs) begin
      phys_addr[i] = mem_map[v_addr];
    end else begin
      phys_addr[i] = v_addr;
    end
  end
end

// Select physical address and data
always @(*) begin
  if (rw) begin // write operation
    p_addr = phys_addr[v_addr];
    phys_addr[v_addr] = data_in;
    data_out = 0;
  end else begin // read operation
    p_addr = phys_addr[v_addr];
    data_out = phys_addr[v_addr];
  end
end

endmodule

