module PLL (
  input ref_clk,
  input fb_clk,
  input ctrl,
  input reset,
  output reg clk_out
);

parameter M = 2; // multiplication factor
parameter N = 1; // division factor
parameter F = 100; // frequency of the synchronized clock signal

reg [31:0] phase_accumulator;
reg [31:0] phase_increment;
reg [31:0] phase_difference;
reg [1:0] charge_pump_output;
reg [1:0] charge_pump_input;
reg [1:0] phase_detector_output;
reg [1:0] phase_detector_input;

always @(posedge ref_clk or posedge reset) begin
  if (reset) begin
    phase_accumulator <= 0;
    phase_increment <= 0;
    phase_difference <= 0;
    charge_pump_output <= 0;
    charge_pump_input <= 0;
    phase_detector_output <= 0;
    phase_detector_input <= 0;
  end else begin
    phase_increment <= ((M * 2**32) / (N * F));
    phase_accumulator <= phase_accumulator + phase_increment;
    phase_difference <= phase_accumulator - (fb_clk * 2**32 / ref_clk);
    phase_detector_input <= {phase_difference[31], phase_difference[0]};
  end
end

always @(posedge ctrl) begin
  if (phase_difference[31]) begin
    charge_pump_input <= 2'b10;
  end else if (phase_difference[0]) begin
    charge_pump_input <= 2'b01;
  end else begin
    charge_pump_input <= 2'b00;
  end
end

always @(posedge ref_clk or posedge reset) begin
  if (reset) begin
    phase_detector_output <= 0;
  end else begin
    phase_detector_output <= phase_detector_input;
  end
end

always @(posedge ctrl) begin
  case (charge_pump_input)
    2'b10: charge_pump_output <= charge_pump_output - 2'b01;
    2'b01: charge_pump_output <= charge_pump_output + 2'b01;
    2'b00: charge_pump_output <= charge_pump_output;
  endcase
end

always @(posedge ref_clk or posedge reset) begin
  if (reset) begin
    clk_out <= 0;
  end else begin
    if (charge_pump_output[1]) begin
      clk_out <= ~clk_out;
    end
  end
end

endmodule

module data_queue(
    input clk, rst, we_i, tx_pop_i,
    input [31:0] data_i, addr_i,
    output reg [31:0] data_o,
    output reg tx_ack_o,
    output reg [5:0] queued_ff
);

parameter Q_SIZE = 64;
reg [31:0] queue [0:Q_SIZE-1];
reg [5:0] head = 0;
reg [5:0] tail = 0;

always @(posedge clk) begin
    if (rst) begin
        head <= 0;
        tail <= 0;
        tx_ack_o <= 0;
        queued_ff <= 0;
    end else if (we_i) begin
        queue[addr_i] <= data_i;
        queued_ff <= queued_ff + 1;
    end else if (tx_pop_i) begin
        data_o <= queue[tail];
        tx_ack_o <= 1;
        queued_ff <= queued_ff - 1;
        tail <= (tail == Q_SIZE-1) ? 0 : tail + 1;
    end else begin
        tx_ack_o <= 0;
    end
end

endmodule

module EchoCancellation (
  input signed [15:0] in1, // original audio signal
  input signed [15:0] in2, // echoed audio signal
  output signed [15:0] out // filtered audio signal
);

parameter Fs = 8000; // sampling frequency in Hz
parameter Taps = 128; // number of filter taps
parameter Mu = 0.0001; // step size for adaptive filter algorithm

reg signed [15:0] delay_line [0:Taps-1]; // delay line for echoed audio signal
reg signed [15:0] filter_taps [0:Taps-1]; // filter taps for adaptive filter algorithm
reg signed [15:0] estimated_echo; // estimated echo signal

integer i;

always @(in2) begin
  // shift delay line and add new sample
  for (i = Taps-1; i > 0; i = i - 1) begin
    delay_line[i] <= delay_line[i-1];
  end
  delay_line[0] <= in2;

  // compute estimated echo signal
  estimated_echo = 0;
  for (i = 0; i < Taps; i = i + 1) begin
    estimated_echo = estimated_echo + filter_taps[i] * delay_line[i];
  end

  // subtract estimated echo signal from echoed audio signal to obtain filtered audio signal
  out = in2 - estimated_echo;

  // update filter taps using LMS algorithm
  for (i = 0; i < Taps; i = i + 1) begin
    filter_taps[i] = filter_taps[i] - Mu * (out - in1) * delay_line[i];
  end
end

endmodule

