  input reset,
  input chipselect,
  input write,
  input [11:0] address,
  input [3:0] byteenable,
  input [31:0] writedata,
  output reg [31:0] readdata
);

  parameter INIT_FILE = "ram.hex";
  parameter BYTE_SIZE = 8;
  parameter WORDS = 4096;
  parameter WIDTH = 32;
  parameter ADDR_WIDTH = $clog2(WORDS);
  parameter BYTE_WIDTH = WIDTH / BYTE_SIZE;

  reg [WIDTH-1:0] mem [0:WORDS-1];
  integer i;

  initial begin
    $readmemh(INIT_FILE, mem);
  end

  always @(posedge clk) begin
    if (reset) begin
      readdata <= 0;
    end else if (chipselect) begin
      if (write) begin
        for (i = 0; i < BYTE_WIDTH; i = i + 1) begin
          if (byteenable[i]) begin
            mem[address][BYTE_SIZE*(i+1)-1:BYTE_SIZE*i] <= writedata[BYTE_SIZE*(i+1)-1:BYTE_SIZE*i];
          end
        end
      end else begin
        readdata <= mem[address];
      end
    end
  end

endmodule

