module seven_seg_pio (
  // inputs:
  address,
  chipselect,
  clk,
  reset_n,
  write_n,
  writedata,

  // outputs:
  out_port,
  readdata
);

  output [15:0] out_port;
  output [31:0] readdata;
  input [1:0] address;
  input chipselect;
  input clk;
  input reset_n;
  input write_n;
  input [31:0] writedata;

  wire clk_en;
  reg [15:0] data_out;
  reg [3:0] seg_data;
  wire [15:0] out_port;
  wire [15:0] read_mux_out;
  wire [31:0] readdata;

  assign clk_en = 1;

  // Define the 7-segment display values for digits 0-9 and letters A-F
  always @*
    begin
      case (data_out[3:0])
        4'h0: seg_data = 7'b1000000; // 0
        4'h1: seg_data = 7'b1111001; // 1
        4'h2: seg_data = 7'b0100100; // 2
        4'h3: seg_data = 7'b0110000; // 3
        4'h4: seg_data = 7'b0011001; // 4
        4'h5: seg_data = 7'b0010010; // 5
        4'h6: seg_data = 7'b0000010; // 6
        4'h7: seg_data = 7'b1111000; // 7
        4'h8: seg_data = 7'b0000000; // 8
        4'h9: seg_data = 7'b0011000; // 9
        4'ha: seg_data = 7'b0001000; // A
        4'hb: seg_data = 7'b0000011; // b
        4'hc: seg_data = 7'b1000110; // C
        4'hd: seg_data = 7'b0100001; // d
        4'he: seg_data = 7'b0000110; // E
        4'hf: seg_data = 7'b0001110; // F
        default: seg_data = 7'b1111111; // blank
      endcase
    end

  // Mux to select between read and write data
  assign read_mux_out = {16 {(address == 0)}} & data_out;

  // Write data to internal register when chipselect and write_n are high and address is 0
  always @(posedge clk or negedge reset_n)
    begin
      if (reset_n == 0)
        data_out <= 0;
      else if (chipselect && ~write_n && (address == 0))
        data_out <= writedata[15:0];
    end

  // Assign the output port to the 7-segment display
  assign out_port = seg_data;

  // Read data from internal register when chipselect and write_n are high and address is 0
  assign readdata = {{{32-16}{1'b0}}, read_mux_out};

endmodule

module checksum (
  input [7:0] data_in,
  input reset,
  output [15:0] checksum_out,
  output valid
);

  reg [15:0] checksum_reg;
  reg valid_reg;

  always @(posedge clk) begin
    if (reset) begin
      checksum_reg <= 16'h0000;
      valid_reg <= 1'b0;
    end else begin
      checksum_reg <= ~(checksum_reg + data_in);
      valid_reg <= (checksum_reg == checksum_out);
    end
  end

  assign checksum_out = checksum_reg;
  assign valid = valid_reg;

endmodule

