module parity_mux (
    input [7:0] in0,
    input [7:0] in1,
    input sel,
    output reg [8:0] out
);

    // 8-bit odd parity checker
    wire [7:0] in_xor = in0 ^ in1;
    wire odd_parity = ^in_xor;

    // 2-to-1 multiplexer
    always @(*) begin
        if (sel == 1'b0) begin
            out[8:1] = in0;
        end else begin
            out[8:1] = in1;
        end
    end

    // Parity bit computation
    always @(*) begin
        if (odd_parity == 1'b1) begin
            out[0] = 1'b1;
        end else begin
            out[0] = 1'b0;
        end
    end

endmodule

