module adder4bit(A, B, Cin, S, Cout);

input [3:0] A;
input [3:0] B;
input Cin;
output [3:0] S;
output Cout;

wire [3:0] X;
wire [3:0] Y;
wire [3:0] Z;

// Generate sum bits
xor X0(A[0], B[0], Cin);
xor X1(A[1], B[1], X0);
xor X2(A[2], B[2], X1);
xor X3(A[3], B[3], X2);

assign S = {X3, X2, X1, X0};

// Generate carry-out bit
and Y0(A[0], B[0]);
and Y1(A[1], B[1], X0);
and Y2(A[2], B[2], X1);
and Y3(A[3], B[3], X2);

or Z0(Y0, Y1, Y2, Y3, Cin);

assign Cout = Z0;

endmodule

