module PLL (
  input ref,
  input fb,
  input rst,
  output clk,
  output locked
);

parameter mult = 2; // frequency multiplication factor
parameter phase_offset = 0; // phase offset value

reg [31:0] phase_accumulator;
reg locked_reg;
wire locked;

assign locked = locked_reg;

always @(posedge ref or posedge rst) begin
  if (rst) begin
    phase_accumulator <= 0;
    locked_reg <= 0;
  end else begin
    phase_accumulator <= phase_accumulator + mult;
    if (phase_accumulator >= 2**32 - 1) begin
      phase_accumulator <= phase_accumulator - 2**32;
    end
    if (fb) begin
      locked_reg <= 1;
    end else begin
      locked_reg <= 0;
    end
  end
end

assign clk = (phase_accumulator[31]) ? ~ref : ref;
assign clk = (phase_accumulator[31]) ? ~clk : clk;
assign clk = (phase_accumulator[30:0] >= 2**(32-1-phase_offset)) ? ~clk : clk;

endmodule

module freq_divider (
  input wire clk_in,
  output wire clk_out
);

  //-- Valor por defecto del divisor
  //-- Como en la iCEstick el reloj es de 12MHz, ponermos un valor de 12M
  //-- para obtener una frecuencia de salida de 1Hz
  parameter M = 12;

  //-- Numero de bits para almacenar el divisor
  //-- Se calculan con la funcion de verilog $clog2, que nos devuelve el
  //-- numero de bits necesarios para representar el numero M
  //-- Es un parametro local, que no se puede modificar al instanciar
  localparam N = $clog2(M);

  //-- Registro para implementar el contador modulo M
  reg [N-1:0] divcounter = 0;

  //-- Contador módulo M
  always @(posedge clk_in)
    if (divcounter == M - 1)
      divcounter <= 0;
    else
      divcounter <= divcounter + 1;

  //-- Sacar el bit mas significativo por clk_out
  assign clk_out = divcounter[N-1];

endmodule

module simple_calculator(
  input clk,
  input reset,
  input [1:0] opcode,
  input [7:0] operand1,
  input [7:0] operand2,
  output reg [7:0] result,
  output reg overflow
);

  reg [15:0] temp; // temporary register for multiplication and division
  always @(posedge clk) begin
    if (reset) begin
      result <= 8'd0;
      overflow <= 1'b0;
    end else begin
      case (opcode)
        2'b00: begin // addition
          temp <= operand1 + operand2;
          if (temp > 8'd255) begin
            overflow <= 1'b1;
            result <= temp[7:0];
          end else begin
            overflow <= 1'b0;
            result <= temp[7:0];
          end
        end
        2'b01: begin // subtraction
          temp <= operand1 - operand2;
          if (temp < 0) begin
            overflow <= 1'b1;
            result <= temp[7:0];
          end else begin
            overflow <= 1'b0;
            result <= temp[7:0];
          end
        end
        2'b10: begin // multiplication
          temp <= operand1 * operand2;
          if (temp > 8'd255) begin
            overflow <= 1'b1;
            result <= temp[7:0];
          end else begin
            overflow <= 1'b0;
            result <= temp[7:0];
          end
        end
        2'b11: begin // division
          if (operand2 == 8'd0) begin
            overflow <= 1'b1;
            result <= 8'd0;
          end else begin
            temp <= operand1 / operand2;
            if (temp > 8'd255) begin
              overflow <= 1'b1;
              result <= temp[7:0];
            end else begin
              overflow <= 1'b0;
              result <= temp[7:0];
            end
          end
        end
      endcase
    end
  end

endmodule

