    output reg [4:0] out
);

reg [3:0] in_reg;
reg [4:0] out_reg;
reg [3:0] neg_in_reg;
reg [4:0] neg_out_reg;

always @ (posedge clk) begin
    in_reg <= in;
    neg_in_reg <= ~in_reg + 1;
end

always @ (posedge clk) begin
    if (in_reg[3] == 1) begin
        out_reg <= {1'b1, ~in_reg + 1};
    end else begin
        out_reg <= {1'b0, in_reg};
    end
end

always @ (posedge clk) begin
    if (neg_in_reg[3] == 1) begin
        neg_out_reg <= {1'b1, ~neg_in_reg + 1};
    end else begin
        neg_out_reg <= {1'b0, neg_in_reg};
    end
end

assign out = (in_reg[3] == 1) ? neg_out_reg : out_reg;

endmodule

