module fifo_scfifo (
  input clk,
  input rst_n,
  input fifo_clear,
  input fifo_rd,
  input [7:0] t_dat,
  input wr_rfifo,
  output fifo_EF,
  output [7:0] fifo_rdata,
  output rfifo_full,
  output [5:0] rfifo_used
);

  wire [7:0] fifo_data [63:0]; // FIFO buffer data
  wire [5:0] fifo_used; // Number of words currently stored in the FIFO buffer
  wire fifo_full; // FIFO buffer is full flag
  wire fifo_empty; // FIFO buffer is empty flag
  reg [5:0] rfifo_used; // Registered number of words currently stored in the FIFO buffer
  reg [7:0] fifo_rdata_reg; // Registered output data from the FIFO buffer
  reg [5:0] wr_ptr; // FIFO buffer write pointer
  reg [5:0] rd_ptr; // FIFO buffer read pointer
  reg [5:0] next_wr_ptr; // Next write pointer
  reg [5:0] next_rd_ptr; // Next read pointer
  reg [7:0] t_dat_reg; // Registered input data
  reg [1:0] state; // FSM state

  // Constants
  localparam IDLE = 2'b00;
  localparam WRITE = 2'b01;
  localparam READ = 2'b10;

  // FSM
  always @ (posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      state <= IDLE;
      wr_ptr <= 6'b0;
      rd_ptr <= 6'b0;
      next_wr_ptr <= 6'b0;
      next_rd_ptr <= 6'b0;
      t_dat_reg <= 8'b0;
      fifo_rdata_reg <= 8'b0;
      rfifo_used <= 6'b0;
    end else begin
      case (state)
        IDLE: begin
          if (fifo_clear) begin
            wr_ptr <= 6'b0;
            rd_ptr <= 6'b0;
            next_wr_ptr <= 6'b0;
            next_rd_ptr <= 6'b0;
            fifo_rdata_reg <= 8'b0;
            rfifo_used <= 6'b0;
          end else if (wr_rfifo) begin
            next_wr_ptr <= wr_ptr + 1;
            state <= WRITE;
          end else if (fifo_rd) begin
            next_rd_ptr <= rd_ptr + 1;
            state <= READ;
          end
        end
        WRITE: begin
          fifo_data[wr_ptr] <= t_dat_reg;
          wr_ptr <= next_wr_ptr;
          state <= IDLE;
        end
        READ: begin
          fifo_rdata_reg <= fifo_data[rd_ptr];
          rd_ptr <= next_rd_ptr;
          state <= IDLE;
        end
      endcase
      t_dat_reg <= t_dat;
      fifo_empty = (wr_ptr == rd_ptr);
      fifo_full = (wr_ptr == rd_ptr + 1'b1) || (wr_ptr == 6'b0 && rd_ptr == 6'd63);
      fifo_EF = fifo_empty;
      fifo_rdata = fifo_rdata_reg;
      rfifo_full = fifo_full;
      rfifo_used = rfifo_used + (wr_rfifo && ~fifo_full) - (fifo_rd && fifo_empty);
    end
  end

endmodule

