module CDR (
  input data_in,
  input clk_ref,
  output data_out,
  output clk_out
);

parameter bit_rate = 1e6; // bit rate of the input data stream
parameter clk_freq = 100e6; // frequency of the reference clock signal

reg data_in_reg;
reg clk_out_reg;

wire data_in_edge;
wire clk_ref_edge;

assign data_in_edge = data_in_reg ^ data_in;
assign clk_ref_edge = clk_ref_reg ^ clk_ref;

always @(posedge clk_ref) begin
  if (data_in_edge) begin
    clk_out_reg <= ~clk_out_reg;
  end
end

always @(posedge clk_ref_edge) begin
  data_in_reg <= data_in;
end

assign data_out = data_in_reg;
assign clk_out = clk_out_reg;

endmodule

