input [15 : 0] din;
input wr_en;
input rd_en;
output [15 : 0] dout;
output full;
output empty;
output [9 : 0] rd_data_count;
output [9 : 0] wr_data_count;

reg [15:0] fifo[0:1023];
reg [9:0] rd_ptr;
reg [9:0] wr_ptr;
reg [9:0] rd_count;
reg [9:0] wr_count;

always @(posedge wr_clk or posedge wr_rst) begin
  if (wr_rst) begin
    wr_ptr <= 0;
    wr_count <= 1024;
  end else if (wr_en && wr_count > 0) begin
    fifo[wr_ptr] <= din;
    wr_ptr <= wr_ptr + 1;
    wr_count <= wr_count - 1;
  end
end

always @(posedge rd_clk or posedge rd_rst) begin
  if (rd_rst) begin
    rd_ptr <= 0;
    rd_count <= 0;
  end else if (rd_en && rd_count > 0) begin
    dout <= fifo[rd_ptr];
    rd_ptr <= rd_ptr + 1;
    rd_count <= rd_count - 1;
  end
end

assign full = wr_count == 0;
assign empty = rd_count == 0;
assign rd_data_count = rd_count;
assign wr_data_count = wr_count;

endmodule

