    input select,
    output wire [15:0] out ); 

    reg [7:0] upper;
    reg [3:0] counter;
    wire [7:0] lower;
    wire enable_reg, enable_counter;

    // Decoder
    assign enable_reg = ~select;
    assign enable_counter = select;

    // Multiplexer
    mux8to1 mux_lower(
        .in0(in[7:0]),
        .in1(in[15:8]),
        .sel(select),
        .out(lower)
    );

    // Control Logic
    always @(*) begin
        if (enable_reg) begin
            upper <= in[15:8];
        end
        else if (enable_counter) begin
            if (counter == 15) begin
                counter <= 0;
            end
            else begin
                counter <= counter + 1;
            end
        end
    end

    // Output
    assign out = {upper, counter};

