module altpcierd_tx_ecrc_64 (
    input clk,
    input [63:0] data,
    input datavalid,
    input [2:0] empty,
    input endofpacket,
    input reset_n,
    input startofpacket,
    output [31:0] checksum,
    output crcvalid
);

    // state definitions
    localparam IDLE = 2'b00;
    localparam START = 2'b01;
    localparam DATA = 2'b10;
    localparam END = 2'b11;

    // register definitions
    reg [1:0] state = IDLE;
    reg [63:0] packet_data;
    reg [2:0] packet_empty;
    reg packet_eop;
    reg packet_sop;
    reg [31:0] crc;
    reg [5:0] data_words_received;
    reg [2:0] empty_slots_received;
    reg crc_valid;

    // instantiate the altpcierd_tx_ecrc_64_altcrc module
    altpcierd_tx_ecrc_64_altcrc altpcierd_tx_ecrc_64_altcrc_inst (
        .clk(clk),
        .data(packet_data),
        .datavalid(datavalid),
        .empty(packet_empty),
        .endofpacket(packet_eop),
        .reset_n(reset_n),
        .startofpacket(packet_sop),
        .checksum(crc),
        .crcvalid(crc_valid)
    );

    always @(posedge clk) begin
        if (!reset_n) begin
            // reset state machine and registers
            state <= IDLE;
            packet_data <= 0;
            packet_empty <= 0;
            packet_eop <= 0;
            packet_sop <= 0;
            crc <= 0;
            data_words_received <= 0;
            empty_slots_received <= 0;
            crc_valid <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (startofpacket) begin
                        // initialize packet variables
                        packet_data <= data;
                        packet_empty <= empty;
                        packet_eop <= endofpacket;
                        packet_sop <= startofpacket;
                        data_words_received <= 1;
                        empty_slots_received <= empty;
                        crc <= 0;
                        // move to the next state
                        state <= DATA;
                    end else begin
                        // stay in IDLE state
                        state <= IDLE;
                    end
                end
                START: begin
                    // not used in this implementation
                    state <= IDLE;
                end
                DATA: begin
                    if (datavalid) begin
                        packet_data <= {packet_data[31:0], data[31:0]};
                        packet_empty <= {packet_empty[1:0], empty[0]};
                        data_words_received <= data_words_received + 1;
                        empty_slots_received <= {empty_slots_received[1:0], empty[0]};
                        if (data_words_received == 8) begin
                            // move to the next state
                            state <= END;
                        end else begin
                            // stay in DATA state
                            state <= DATA;
                        end
                    end else begin
                        // stay in DATA state
                        state <= DATA;
                    end
                end
                END: begin
                    if (endofpacket) begin
                        // calculate the checksum
                        crc <= altpcierd_tx_ecrc_64_altcrc_inst.checksum;
                        crc_valid <= altpcierd_tx_ecrc_64_altcrc_inst.crcvalid;
                        // move to the next state
                        state <= IDLE;
                    end else begin
                        // stay in END state
                        state <= END;
                    end
                end
            endcase
        end
    end

    // assign outputs
    assign checksum = crc;
    assign crcvalid = crc_valid;

endmodule

module ripple_carry_adder(
