module top_module( 
    input [99:0] a, b,
    input cin,
    output cout,
    output [99:0] sum );

    wire [95:0] g, p, c;
    wire [3:0] a_last, b_last;
    wire c_last;

    // Carry-lookahead adder for the first 96 bits
    cla_adder_96bit cla_adder(
        .a(a[95:0]),
        .b(b[95:0]),
        .g(g),
        .p(p),
        .c(c)
    );

    // Full-adder module for the last 4 bits
    full_adder_4bit full_adder(
        .a(a_last),
        .b(b_last),
        .cin(c[95]),
        .sum(sum[3:0]),
        .cout(c_last)
    );

    // Connect the last 4 bits to the inputs of the full-adder
    assign a_last = a[99:96];
    assign b_last = b[99:96];

    // Connect the carry-out of the full-adder to the output carry
    assign cout = c_last;

    // Connect the outputs of the carry-lookahead adder to the remaining bits of the output sum
    assign sum[99:96] = a[99:96] + b[99:96] + c[96];
    assign sum[95:0] = g + (p & {c[95], c[95], c[95], c[95]}) + a[95:0] + b[95:0] + (c[95] & p);

endmodule

module calculator(input [7:0] num1, num2, input control, output [7:0] result, output carry);
    reg [8:0] temp;

    always @(*) begin
        if (control == 1'b0) begin  // addition operation
            temp = num1 + num2;
            carry = temp[8];
            result = temp[7:0];
        end
        else begin  // subtraction operation
            temp = num1 - num2;
            carry = temp[8];
            result = temp[7:0];
        end
    end
endmodule

