module binary_search(
    input clk,
    input rst,
    input [31:0] sorted_array[31:0],
    input [31:0] target,
    output reg [4:0] index
);

reg [4:0] left; // left index of the search range
reg [4:0] right; // right index of the search range
reg [4:0] mid; // middle index of the search range

always @(posedge clk) begin
    if (rst) begin
        index <= -1;
        left <= 0;
        right <= 31;
    end else begin
        if (left > right) begin // target not found
            index <= -1;
        end else begin
            mid <= (left + right) / 2;
            if (sorted_array[mid] == target) begin // target found
                index <= mid;
            end else if (sorted_array[mid] > target) begin // target in left half
                right <= mid - 1;
            end else begin // target in right half
                left <= mid + 1;
            end
        end
    end
end

