module UART_Tx(
    input CLK,
    input [7:0] D,
    input WR,
    input RST,
    output reg TX,
    output reg TXE
);

parameter BAUD_RATE = 9600;
parameter CLOCK_FREQ = 50_000_000;

reg [3:0] bit_counter;
reg [7:0] data_reg;
reg parity_bit;
reg start_bit;
reg stop_bit;

reg [31:0] baud_counter;
parameter BAUD_TICKS = CLOCK_FREQ / BAUD_RATE;

always @(posedge CLK) begin
    if (RST) begin
        baud_counter <= 0;
        bit_counter <= 0;
        TX <= 1;
        TXE <= 1;
    end else begin
        // Increment baud counter
        baud_counter <= baud_counter + 1;

        // If we have counted enough ticks for the current baud rate
        if (baud_counter == BAUD_TICKS) begin
            // Reset baud counter
            baud_counter <= 0;

            // If we are not currently transmitting data
            if (TXE) begin
                // If we have new data to transmit
                if (WR) begin
                    // Load data into data register
                    data_reg <= D;

                    // Reset parity bit
                    parity_bit <= 0;

                    // Set start bit
                    start_bit <= 0;

                    // Clear stop bit
                    stop_bit <= 1;

                    // Set bit counter to 0
                    bit_counter <= 0;

                    // Indicate that we are transmitting data
                    TXE <= 0;
                end
            end else begin
                // If we are currently transmitting data
                if (bit_counter < 10) begin
                    // If we are transmitting a start bit
                    if (bit_counter == 0) begin
                        TX <= start_bit;
                    // If we are transmitting a data bit
                    end else if (bit_counter < 9) begin
                        TX <= data_reg[bit_counter - 1];
                        parity_bit <= parity_bit ^ data_reg[bit_counter - 1];
                    // If we are transmitting a parity bit
                    end else if (bit_counter == 9) begin
                        TX <= parity_bit;
                    // If we are transmitting a stop bit
                    end else begin
                        TX <= stop_bit;
                        TXE <= 1;
                    end

                    // Increment bit counter
                    bit_counter <= bit_counter + 1;
                end
            end
        end
    end
end

endmodule

