module FSM (
  input [n-1:0] in,
  output reg [m-1:0] out
);

parameter n = 4; // number of input signals
parameter m = 2; // number of output signals
parameter s = 8; // number of states in the FSM
parameter c = 3; // number of bits required to represent the state codes

reg [c-1:0] current_state, next_state;

// State encoding
localparam [c-1:0] S0 = 3'b000,
                   S1 = 3'b001,
                   S2 = 3'b011,
                   S3 = 3'b010,
                   S4 = 3'b110,
                   S5 = 3'b111,
                   S6 = 3'b101,
                   S7 = 3'b100;

// State transition rules
always @(*) begin
  case (current_state)
    S0: next_state = in[0] ? S1 : S0;
    S1: next_state = in[1] ? S2 : S0;
    S2: next_state = in[2] ? S3 : S1;
    S3: next_state = in[3] ? S4 : S2;
    S4: next_state = in[0] ? S5 : S3;
    S5: next_state = in[1] ? S6 : S4;
    S6: next_state = in[2] ? S7 : S5;
    S7: next_state = in[3] ? S0 : S6;
    default: next_state = S0;
  endcase
end

// Output rules
always @(*) begin
  case (current_state)
    S0: out = 2'b00;
    S1: out = 2'b01;
    S2: out = 2'b10;
    S3: out = 2'b11;
    S4: out = 2'b00;
    S5: out = 2'b01;
    S6: out = 2'b10;
    S7: out = 2'b11;
    default: out = 2'b00;
  endcase
end

// State register
always @(posedge clk) begin
  current_state <= next_state;
end

endmodule

module MAC_REG_ACC(
    input               clk,
    input               reset,
    input               waitrequest,
    input       [31:0]  readdata,

    output reg  [7:0]   address,
    output reg          write,
    output reg          read,
    output reg  [31:0]  writedata
);

    reg         [2:0]   reg_count;
    reg         [3:0]   count;
    reg         [1:0]   current_state;
    parameter   idle_s      =   2'b00,
                wait_clk_s  =   2'b01,
                write_s     =   2'b10,  
                wait_s      =   2'b11;

    always@(posedge clk or negedge reset) begin
        if(!reset) begin
            address     <= 8'b0;
            write       <= 1'b0;
            read        <= 1'b0;
            writedata   <= 32'b0;
            reg_count   <= 3'b0;
            count       <= 4'b0;
            current_state   <= wait_clk_s;
        end 
        else begin
            case(current_state)
                wait_clk_s: begin
                    reg_count   <= 3'b0;
                    count       <= count + 1'b1;
                    if(count[3] == 1'b1) begin
                        current_state   <= idle_s;
                    end
                    else begin
                        current_state   <= wait_clk_s;
                    end
                end
                idle_s: begin
                    address     <= 8'b0;
                    write       <= 1'b0;
                    read        <= 1'b0;
                    writedata   <= 32'b0;
                    count       <= 4'b0;
                    if(reg_count < 3'd4) begin
                        reg_count       <= reg_count + 3'b1;
                        current_state   <= write_s;
                    end
                    else begin                        
                        current_state   <= idle_s;
                    end
                end
                write_s: begin

                    current_state   <= wait_s;
                    case(reg_count)
                        3'd1: begin
                            address     <= 8'h2;
                            write       <= 1'b1;
                            writedata   <= 32'h1000093;
                        end
                        3'd2: begin
                            address     <= 8'he;
                            write       <= 1'b1;
                            writedata   <= 32'h4;
                        end
                        3'd3: begin
                            address     <= 8'h94;
                            write       <= 1'b1;
                            writedata   <= 32'h7;
                        end
                        default: begin
                            address     <= 8'h2;
                            writedata   <= 32'h1000093; 
                        end
                    endcase
                end
                wait_s: begin
                    write   <= 1'b1;
                    if(waitrequest == 1'b0) begin
                        current_state   <= idle_s;
                        write           <= 1'b1;
                    end
                    else begin
                        current_state   <= wait_s;
                    end
                end
            endcase
        end 
    end 

endmodule

