module square_wave (
    input clk,
    input reset,
    output reg out
);
reg [31:0] counter;
always @ (posedge clk, posedge reset) begin
    if (reset) begin
        counter <= 0;
        out <= 0;
    end else begin
        counter <= counter + 1;
        if (counter == 100000000) begin
            counter <= 0;
            out <= ~out;
        end
    end
end
