module PLL (
  input clk_ref,
  input clk_in,
  output reg clk_out
);

parameter k = 4; // multiplication factor
parameter n = 2; // division factor
parameter f_vco = 64; // frequency of VCO

// calculate frequency of reference clock
parameter f_ref = 50; // in MHz

// calculate frequency of input clock
parameter f_in = 200; // in MHz

// calculate frequency of output clock
parameter f_out = f_vco/n; // in MHz

// define phase detector module
reg pd_last_clk_ref;
reg pd_last_clk_in;
reg pd_out;
always @(posedge clk_ref or posedge clk_in) begin
  pd_last_clk_ref <= clk_ref;
  pd_last_clk_in <= clk_in;
  pd_out <= ~(pd_last_clk_ref ^ pd_last_clk_in);
end

// define charge pump module
reg cp_last_pd_out;
reg cp_out;
always @(posedge clk_ref) begin
  cp_last_pd_out <= pd_out;
  if (pd_out) begin
    cp_out <= cp_last_pd_out + 1;
  end else begin
    cp_out <= cp_last_pd_out - 1;
  end
end

// define loop filter module
reg lf_last_cp_out;
reg [7:0] lf_out;
always @(posedge clk_ref) begin
  lf_last_cp_out <= cp_out;
  lf_out <= lf_last_cp_out + cp_out;
end

// define voltage-controlled oscillator module
reg vco_last_lf_out;
reg vco_out;
always @(posedge clk_ref) begin
  vco_last_lf_out <= lf_out;
  vco_out <= vco_last_lf_out + f_vco;
end

// define frequency divider module
reg [1:0] fd_count;
reg fd_out;
always @(posedge vco_out) begin
  fd_count <= fd_count + 1;
  if (fd_count == n) begin
    fd_count <= 0;
    fd_out <= ~fd_out;
  end
end

// define output buffer module
always @(posedge clk_ref) begin
  clk_out <= fd_out;
end

// implement PLL functionality using the above modules
// ...
assign clk_in_div = clk_in / n;
assign vco_in = clk_in_div * k;
// ...
endmodule

module adder_8bit (
    input [7:0] A,
    input [7:0] B,
    input CI,
    output [8:0] SUM,
    output COUT_N
);

    wire [7:0] temp_sum;
    wire temp_carry;

    // Add A and B
    assign temp_sum = A + B;

    // If CI is high, add 1 to the sum
    assign temp_sum = (CI == 1'b1) ? temp_sum + 1 : temp_sum;

    // Check if there is a carry-out
    assign temp_carry = (CI == 1'b1) ? (temp_sum[8] | A[7] | B[7]) : (temp_sum[8] & A[7] & B[7]);

    // Output the sum and carry-out
    assign SUM = temp_sum;
    assign COUT_N = ~temp_carry;

endmodule

