module prescaler(ins_o, ins_i, icm_i, rst_i, clk_i);
  output ins_o;
  input ins_i;
  input [2:0] icm_i;
  input rst_i;
  input clk_i;

  reg ins_o;
  reg next_ins_o_reg;
  reg [4:0] threshold_reg;
  reg [4:0] next_counter_reg;
  reg [4:0] counter_reg;

  // Determine the threshold value based on icm_i
  always @ (icm_i) begin
    case (icm_i)
      3'b001, 3'b010, 3'b011: threshold_reg = 5;
      3'b100, 3'b101: threshold_reg = 10;
      default: threshold_reg = 0;
    endcase
  end

  // Update next_ins_o_reg and next_counter_reg based on ins_i and the current counter value
  always @ (threshold_reg or counter_reg or ins_i) begin
    if (counter_reg == threshold_reg) begin
      next_ins_o_reg = 0;
      next_counter_reg = 0;
    end else if (ins_i) begin
      next_ins_o_reg = 1;
      next_counter_reg = counter_reg + 1;
    end
  end

  // Update ins_o and counter_reg on the positive edge of clk_i or rst_i
  always @ (posedge clk_i or posedge rst_i) begin
    if (!rst_i && clk_i) begin
      counter_reg <= next_counter_reg;
      ins_o <= next_ins_o_reg;
    end else begin
      counter_reg <= 0;
      ins_o <= 0;
    end
  end

endmodule

