module memory (
    input clk,
    input rst_n,
    input [17:0] address,
    input write,
    input read,
    input [35:0] writedata,
    output reg [35:0] readdata,
    output reg waitrequest
);

    reg [35:0] mem[0:16383];
    reg [35:0] readdata_reg;
    reg waitrequest_reg;
    reg [17:0] address_reg;
    reg write_reg;
    reg read_reg;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            readdata_reg <= 0;
            waitrequest_reg <= 0;
            address_reg <= 0;
            write_reg <= 0;
            read_reg <= 0;
        end else begin
            readdata_reg <= mem[address_reg];
            waitrequest_reg <= 0;
            if (write_reg) begin
                mem[address_reg] <= writedata;
                waitrequest_reg <= 1;
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            address_reg <= 0;
            write_reg <= 0;
            read_reg <= 0;
        end else begin
            if (read) begin
                address_reg <= address;
                read_reg <= 1;
            end
            if (write) begin
                address_reg <= address;
                write_reg <= 1;
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            readdata <= 0;
            waitrequest <= 0;
        end else begin
            readdata <= readdata_reg;
            waitrequest <= waitrequest_reg;
        end
    end

endmodule

module ALTSQRT_component (
    clk,
    ena,
    radical,
    q,
    remainder
);

input clk;
input ena;
input [42:0] radical;
output [21:0] q;
output [22:0] remainder;

wire [21:0] sub_wire0;
wire [22:0] sub_wire1;

wire [42:0] x;
wire [21:0] y;
wire [21:0] y_next;
wire [42:0] r;
wire [42:0] r_next;
wire [21:0] q_next;
wire [42:0] x_next;
wire [22:0] remainder_next;

assign x = radical;
assign y = {11'b0, 11'b1, 11'b0, 11'b1, 11'b0, 11'b1, 11'b0, 11'b1, 11'b0, 11'b1, 11'b0};
assign r = {21'b0, radical};

assign q = sub_wire0[21:0];
assign remainder = sub_wire1[22:0];

assign q_next = {21'b0, y[42:32]};
assign x_next = {r[42:22], y[31:0]};
assign y_next = y + q_next;
assign r_next = r - x_next * q_next;

always @(posedge clk) begin
    if (ena) begin
        sub_wire0 <= q_next;
        sub_wire1 <= remainder_next;
    end
end

genvar i;
generate
    for (i = 0; i < 5; i = i + 1) begin
        always @(posedge clk) begin
            if (ena) begin
                q_next <= {q_next[20:0], 1'b0};
                remainder_next <= {remainder_next[21:0], 1'b0};
                if (r_next[42]) begin
                    q_next[0] <= 1'b0;
                    r_next <= r_next + x_next;
                end else begin
                    q_next[0] <= 1'b1;
                end
                x_next <= {x_next[41:0], 1'b0};
                y_next <= {y_next[20:0], 1'b0};
            end
        end
    end
endgenerate

endmodule

module VAD (
