module division(
    input           clk,            // clock
    input           rst,            // reset
    input           op_divs,        // 1 for signed operation
    input           op_divu,        // 1 for unsigned operation
    input   [31:0]  dividend,       //
    input   [31:0]  divisor,        //
    output  [31:0]  quotient,       //
    output  [31:0]  remainder,      //
    output          stall           // 1 while calculating
    );

    //--------------------------------------------------------------------------
    // Signal Declaration: reg
    //--------------------------------------------------------------------------
    reg             active;             // 1 while running
    reg             neg_result;         // 1 if the result will be negative
    reg     [4:0]   cycle;              // number of cycles needed.

    reg     [31:0]  result;             // Store the result.
    reg     [31:0]  denominator;        // divisor
    reg     [31:0]  residual;           // current remainder

    //--------------------------------------------------------------------------
    // Signal Declaration: wire
    //--------------------------------------------------------------------------
    wire    [32:0]  partial_sub;        //

    //--------------------------------------------------------------------------
    // assigments
    //--------------------------------------------------------------------------
    assign quotient    = !neg_result ? result : -result;
    assign remainder   = residual;
    assign stall       = active;
    assign partial_sub = {residual[30:0], result[31]} - denominator;    // calculate the current digit

    //--------------------------------------------------------------------------
    // State Machine. This needs 32 cycles to calcule the result.
    // The result is loaded after 34 cycles
    // The first cycle is setup.
    //--------------------------------------------------------------------------
    always @(posedge clk) begin
        if (rst) begin
            active      <= 1'b0;
            neg_result  <= 1'b0;
            cycle       <= 5'b0;
            result      <= 32'b0;
            denominator <= 32'b0;
            residual    <= 32'b0;
        end
        else begin
            if(op_divs) begin
                // Signed division.
                cycle       <= 5'd31;
                result      <= (dividend[31] == 1'b0) ? dividend : -dividend;
                denominator <= (divisor[31] == 1'b0) ? divisor : -divisor;
                residual    <= 32'b0;
                neg_result  <= dividend[31] ^ divisor[31];
                active      <= 1'b1;
            end
            else if (op_divu) begin
                // Unsigned division.
                cycle       <= 5'd31;
                result      <= dividend;
                denominator <= divisor;
                residual    <= 32'b0;
                neg_result  <= 1'b0;
                active      <= 1'b1;
            end
            else if (active) begin
                // run a iteration
                if(partial_sub[32] == 1'b0) begin
                    residual <= partial_sub[31:0];
                    result   <= {result[30:0], 1'b1};
                end
                else begin
                    residual <= {residual[30:0], result[31]};
                    result   <= {result[30:0], 1'b0};
                end

                if (cycle == 5'b0) begin
                    active <= 1'b0;
                end

                cycle <= cycle - 5'd1;
            end
        end
    end
endmodule

module ui32ToRecF16 (
    input [(`floatControlWidth - 1):0] control,
    input [31:0] in,
    input [2:0] roundingMode,
    output [16:0] out,
    output [4:0] exceptionFlags
);

    // Constants for IEEE 754-2008 format
    parameter EXP_WIDTH = 5;
    parameter SIG_WIDTH = 11;
    parameter BIAS = 15;
    parameter EXP_MAX = 31;
    parameter EXP_MIN = -14;
    parameter SIG_MAX = (1 << SIG_WIDTH) - 1;
    parameter SIG_MSB = (1 << (SIG_WIDTH - 1));
    parameter QNAN_BIT = (1 << (SIG_WIDTH - 2));
    parameter SNAN_BIT = (1 << (SIG_WIDTH - 3));
    parameter INFINITY = {EXP_MAX, {SIG_WIDTH{1'b0}}};
    parameter NEG_INFINITY = {EXP_MAX, {SIG_WIDTH{1'b0}}, 1'b1};
    parameter QNAN = {EXP_MAX, {SIG_WIDTH-1{1'b1}}, 1'b0};
    parameter SNAN = {EXP_MAX, {SIG_WIDTH-1{1'b1}}, 1'b1};

    // Internal signals
    wire [31:0] absIn = (in[31]) ? (~in + 1) : in;
    wire [EXP_WIDTH-1:0] expIn = $clog2(absIn) + BIAS - 1;
    wire [SIG_WIDTH-1:0] sigIn = absIn >> (31 - expIn);
    wire [SIG_WIDTH-1:0] sigOut;
    wire [EXP_WIDTH-1:0] expOut;
    wire [3:0] exceptionFlagsInt;
    wire isZero = (in == 0);
    wire isInf = (absIn == INFINITY);
    wire isNegInf = (absIn == NEG_INFINITY);
    wire isQNaN = ((absIn > INFINITY) && (sigIn[SIG_WIDTH-2] == 1'b1));
    wire isSNaN = ((absIn > INFINITY) && (sigIn[SIG_WIDTH-2:SIG_WIDTH-3] == 2'b01));
    wire isDenorm = (expIn <= 0);

    // Rounding modes
    wire [2:0] roundDir;
    assign roundDir = (control[7:6] == 2'b00) ? 3'b000 : 
                      (control[7:6] == 2'b01) ? 3'b100 :
                      (control[7:6] == 2'b10) ? 3'b001 : 3'b010;
    wire roundTiesToAway = (control[14:12] == 3'b101);
    wire roundTiesToEven = (control[14:12] == 3'b100);

    // Exception flags
    assign exceptionFlagsInt[3] = (expIn > EXP_MAX) || isInf;
    assign exceptionFlagsInt[2] = (expIn < EXP_MIN) && !isZero && !isDenorm;
    assign exceptionFlagsInt[1] = (roundTiesToAway && (sigIn[SIG_WIDTH-2:0] == SIG_MSB)) || 
                                  (roundTiesToEven && (sigIn[SIG_WIDTH-2:0] == SIG_MSB) && (sigIn[SIG_WIDTH-3] ^ roundDir[0]));
    assign exceptionFlagsInt[0] = isDenorm;
    assign exceptionFlagsInt[4] = isQNaN || isSNaN || (control[14:12] > 3'b100);

    // Handle special cases
    assign sigOut = (isInf || isNegInf) ? {SIG_WIDTH{1'b0}} :
                    isQNaN ? QNAN :
                    isSNaN ? SNAN :
                    (isZero || isDenorm) ? {1'b0, sigIn[SIG_WIDTH-2:0]} : 
                    {sigIn[SIG_WIDTH-2], sigIn[SIG_WIDTH-4:0]};
    assign expOut = (isInf || isNegInf) ? {EXP_WIDTH{1'b1}} :
                    isZero ? {EXP_WIDTH{1'b0}} :
                    isDenorm ? {1'b0, expIn + 1} :
                    {expIn, {SIG_WIDTH-1{1'b0}}};

    // Perform rounding
    wire roundUp = (roundDir == 3'b001) || (roundDir == 3'b000 && sigIn[SIG_WIDTH-2] && (sigIn[SIG_WIDTH-3:0] != 0));
    wire roundDown = (roundDir == 3'b010) || (roundDir == 3'b000 && !sigIn[SIG_WIDTH-2]);
    wire roundZero = (roundDir == 3'b100) || (roundDir == 3'b000 && sigIn[SIG_WIDTH-2:0] == 0);
    wire [SIG_WIDTH-1:0] sigOutRounded = (roundUp && !roundTiesToEven) ? sigOut + 1 :
                                          (roundDown && !roundTiesToEven) ? sigOut - 1 :
                                          (roundUp && roundTiesToEven && sigOut[SIG_WIDTH-1:0] != SIG_MAX) ? sigOut + 1 :
                                          (roundDown && roundTiesToEven && sigOut[SIG_WIDTH-1:0] != SIG_MAX) ? sigOut - 1 :
                                          sigOut;

    // Output signals
    assign out = {sigOutRounded[SIG_WIDTH-1], expOut[EXP_WIDTH-2:0], sigOutRounded[SIG_WIDTH-2:0]};
    assign exceptionFlags = {exceptionFlagsInt[4], exceptionFlagsInt[2:0], exceptionFlagsInt[1]};

endmodule

module barrel_shifter (
  input clk,
  input reset,
  input [31:0] data,
  input [4:0] amount,
  input dir,
  input load,
  output reg [31:0] q
);

  reg [31:0] shift_reg;
  reg [4:0] shift_amount;

  always @(posedge clk) begin
    if (reset) begin
      shift_reg <= 0;
      shift_amount <= 0;
    end else begin
      if (load) begin
        shift_reg <= data;
        shift_amount <= 0;
      end else if (dir == 0) begin
        shift_reg <= {shift_reg[amount-1:0], shift_reg[31:amount]};
        shift_amount <= amount;
      end else begin
        shift_reg <= {shift_reg[31], shift_reg[31:amount]};
        shift_amount <= amount;
      end
    end
  end

  assign q = shift_reg;

endmodule

module uart_state_machine (
  input clk,
  input rst,
  input rx,
  input tx_en,
  input [7:0] tx_data,
  output reg rx_data,
  output reg tx_busy
);

  // Define states of the state machine
  parameter IDLE = 2'b00;
  parameter START_BIT = 2'b01;
  parameter DATA_BITS = 2'b10;
  parameter PARITY_BIT = 2'b11;

  // Define variables for the state machine
  reg [1:0] state;
  reg [3:0] bit_count;
  reg [7:0] shift_reg;
  reg parity_bit;
  reg tx_bit_count;
  reg [7:0] tx_shift_reg;
  reg tx_start_bit;
  reg [1:0] tx_state;

  // Initialize variables
  always @ (posedge rst) begin
    state <= IDLE;
    bit_count <= 0;
    shift_reg <= 0;
    parity_bit <= 0;
    tx_bit_count <= 0;
    tx_shift_reg <= 0;
    tx_start_bit <= 1;
    tx_state <= IDLE;
    rx_data <= 0;
    tx_busy <= 0;
  end

  // Receive data state machine
  always @ (posedge clk) begin
    case (state)
      IDLE: begin
        if (!rx) begin
          state <= START_BIT;
          bit_count <= 0;
          shift_reg <= 0;
          parity_bit <= 0;
        end
      end
      START_BIT: begin
        if (rx) begin
          state <= IDLE;
        end else begin
          bit_count <= bit_count + 1;
          shift_reg <= {shift_reg[6:0], rx};
          if (bit_count == 7) begin
            state <= PARITY_BIT;
          end else begin
            state <= DATA_BITS;
          end
        end
      end
      DATA_BITS: begin
        bit_count <= bit_count + 1;
        shift_reg <= {shift_reg[6:0], rx};
        if (bit_count == 7) begin
          state <= PARITY_BIT;
        end
      end
      PARITY_BIT: begin
        bit_count <= bit_count + 1;
        parity_bit <= rx;
        if (bit_count == 8) begin
          if (rx == ~^shift_reg[7:0]) begin
            rx_data <= shift_reg[6:0];
          end
          state <= IDLE;
        end
      end
    endcase
  end

  // Transmit data state machine
  always @ (posedge clk) begin
    if (tx_en && !tx_busy) begin
      tx_busy <= 1;
      tx_state <= START_BIT;
      tx_bit_count <= 0;
      tx_shift_reg <= {tx_data, ~^tx_data};
      tx_start_bit <= 0;
    end else if (tx_busy) begin
      case (tx_state)
        START_BIT: begin
          if (tx_start_bit) begin
            tx_start_bit <= 0;
          end else begin
            tx_state <= DATA_BITS;
            tx_bit_count <= 0;
          end
        end
        DATA_BITS: begin
          tx_bit_count <= tx_bit_count + 1;
          if (tx_bit_count == 8) begin
            tx_state <= PARITY_BIT;
          end else begin
            tx_shift_reg <= {tx_shift_reg[6:0], tx_shift_reg[7]};
          end
        end
        PARITY_BIT: begin
          tx_bit_count <= tx_bit_count + 1;
          if (tx_bit_count == 9) begin
            tx_state <= START_BIT;
            tx_busy <= 0;
          end
        end
      endcase
    end
  end

endmodule

