module float_arithmetic (
  input [31:0] A,
  input [31:0] B,
  input [1:0] opcode,
  output reg [31:0] result
);

  // Constants
  parameter EXPONENT_BIAS = 127;
  parameter MANTISSA_WIDTH = 23;
  parameter EXPONENT_WIDTH = 8;
  parameter SIGN_BIT = 31;
  parameter EXPONENT_BIT = 30;
  parameter MANTISSA_BIT = 22;
  parameter ROUND_BIT = 22;
  parameter STICKY_BIT = 21;
  parameter GUARD_BIT = 20;
  parameter ROUND_MODE = 2'b00; // Round to nearest

  // Inputs
  reg [31:0] a_mantissa;
  reg [7:0] a_exponent;
  reg a_sign;
  reg [31:0] b_mantissa;
  reg [7:0] b_exponent;
  reg b_sign;

  // Outputs
  reg [31:0] result_mantissa;
  reg [7:0] result_exponent;
  reg result_sign;

  // Internal signals
  wire [31:0] a_extended;
  wire [31:0] b_extended;
  wire [31:0] result_extended;
  wire [31:0] shifted_mantissa;
  wire [31:0] sticky_bits;
  wire [31:0] guard_bits;
  wire [31:0] round_bits;
  wire [31:0] round_mask;
  wire [31:0] round_threshold;
  wire [31:0] round_up;
  wire [31:0] round_down;
  wire [31:0] round_nearest;
  wire [31:0] round_zero;

  // Parse inputs as floating-point numbers
  assign a_sign = A[SIGN_BIT];
  assign a_exponent = A[EXPONENT_BIT:EXPONENT_BIT-EXPONENT_WIDTH+1] - EXPONENT_BIAS;
  assign a_mantissa = {1'b1, A[MANTISSA_BIT-1:0]};
  assign b_sign = B[SIGN_BIT];
  assign b_exponent = B[EXPONENT_BIT:EXPONENT_BIT-EXPONENT_WIDTH+1] - EXPONENT_BIAS;
  assign b_mantissa = {1'b1, B[MANTISSA_BIT-1:0]};

  // Extend mantissas to 64 bits
  assign a_extended = {32'd0, a_mantissa};
  assign b_extended = {32'd0, b_mantissa};

  // Perform operation based on opcode
  always @(*) begin
    case (opcode)
      2'b00: // Addition
        begin
          if (a_exponent > b_exponent) begin
            shifted_mantissa = b_extended >> (a_exponent - b_exponent);
            result_exponent = a_exponent;
          end else begin
            shifted_mantissa = a_extended >> (b_exponent - a_exponent);
            result_exponent = b_exponent;
          end
          if (a_sign == b_sign) begin
            result_mantissa = a_extended + b_extended;
            result_sign = a_sign;
          end else begin
            result_mantissa = a_extended - b_extended;
            result_sign = (result_mantissa[SIGN_BIT] == 1) ? ~a_sign : a_sign;
          end
        end
      2'b01: // Subtraction
        begin
          if (a_exponent > b_exponent) begin
            shifted_mantissa = b_extended >> (a_exponent - b_exponent);
            result_exponent = a_exponent;
          end else begin
            shifted_mantissa = a_extended >> (b_exponent - a_exponent);
            result_exponent = b_exponent;
          end
          if (a_sign != b_sign) begin
            result_mantissa = a_extended + b_extended;
            result_sign = a_sign;
          end else begin
            result_mantissa = a_extended - b_extended;
            result_sign = (result_mantissa[SIGN_BIT] == 1) ? ~a_sign : a_sign;
          end
        end
      2'b10: // Multiplication
        begin
          result_mantissa = a_mantissa * b_mantissa;
          result_exponent = a_exponent + b_exponent - EXPONENT_BIAS;
          result_sign = a_sign ^ b_sign;
        end
      2'b11: // Division
        begin
          result_mantissa = a_mantissa / b_mantissa;
          result_exponent = a_exponent - b_exponent + EXPONENT_BIAS;
          result_sign = a_sign ^ b_sign;
        end
      default:
        begin
          result_mantissa = 32'd0;
          result_exponent = 8'd0;
          result_sign = 1'b0;
        end
    endcase
  end

  // Normalize result and handle special cases
  always @(*) begin
    if (result_mantissa[MANTISSA_WIDTH+1] == 1) begin
      result_mantissa = result_mantissa >> 1;
      result_exponent = result_exponent + 1;
    end
    if (result_exponent == 0) begin
      result_mantissa = 32'd0;
      result_exponent = 8'd0;
      result_sign = 1'b0;
    end
    if (result_exponent == 255) begin
      if (result_mantissa != 32'd0) begin
        result_mantissa = 32'd0;
        result_exponent = 8'd255;
        result_sign = 1'b0;
      end else begin
        result_exponent = 8'd255;
      end
    end
  end

  // Round result according to rounding mode
  assign sticky_bits = (result_mantissa[ROUND_BIT-1:0] != 0);
  assign guard_bits = result_mantissa[GUARD_BIT];
  assign round_bits = result_mantissa[ROUND_BIT+1:MANTISSA_WIDTH];
  assign round_mask = {1'b1, {MANTISSA_WIDTH-ROUND_BIT-1{1'b0}}, 1'b1};
  assign round_threshold = {1'b1, {MANTISSA_WIDTH-ROUND_BIT-2{1'b0}}, 1'b1, 1'b0};
  assign round_up = result_mantissa + round_mask;
  assign round_down = result_mantissa;
  assign round_nearest = (round_bits > round_threshold) ? round_up : round_down;
  assign round_zero = {1'b0, {MANTISSA_WIDTH-1{1'b0}}};
  always @(*) begin
    case (ROUND_MODE)
      2'b00: result_mantissa = round_nearest[MANTISSA_WIDTH-1:0];
      2'b01: result_mantissa = round_zero[MANTISSA_WIDTH-1:0];
      2'b10: result_mantissa = round_up[MANTISSA_WIDTH-1:0];
      2'b11: result_mantissa = round_down[MANTISSA_WIDTH-1:0];
    endcase
    if (result_mantissa[MANTISSA_WIDTH+1] == 1) begin
      result_mantissa = result_mantissa >> 1;
      result_exponent = result_exponent + 1;
    end
    if (result_exponent == 0) begin
      result_mantissa = 32'd0;
      result_exponent = 8'd0;
      result_sign = 1'b0;
    end
    if (result_exponent == 255) begin
      if (result_mantissa != 32'd0) begin
        result_mantissa = 32'd0;
        result_exponent = 8'd255;
        result_sign = 1'b0;
      end else begin
        result_exponent = 8'd255;
      end
    end
  end

  // Output result as floating-point number
  assign result[SIGN_BIT] = result_sign;
  assign result[EXPONENT_BIT:EXPONENT_BIT-EXPONENT_WIDTH+1] = result_exponent + EXPONENT_BIAS;
  assign result[MANTISSA_BIT-1:0] = result_mantissa[MANTISSA_WIDTH-1:0];

endmodule

