                dp_out <= 0;
                disp_hours <= 4'b1111;
                disp_mins <= 4'b1111;
                disp_secs <= 4'b1111;
            end else begin
                dp_out <= 1;
            end
            seg_count <= seg_count + 1;
            if (seg_count == 3) begin
                seg_count <= 0;
                if (blink == 1) begin
                    hours <= hours_in;
                    mins <= mins_in;
                    secs <= secs_in;
                end else begin
                    if (secs == 59) begin
                        if (mins == 59) begin
                            hours <= hours + 1;
                            mins <= 0;
                        end else begin
                            mins <= mins + 1;
                        end
                        secs <= 0;
                    end else begin
                        secs <= secs + 1;
                    end
                end
                blink <= ~blink;
            end
        end
    end
end

endmodule

module lfsr_count255(
                     input i_sys_clk,
                     input i_sys_rst,
                     output reg o_lfsr_256_done);

    reg [7:0]                   lfsr_reg_i;
    wire                        lfsr_d0_i,lfsr_256_equal_i;

    // Feedback polynomial: x^7 + x^5 + x^4 + x^3 + 1
    xnor(lfsr_d0_i,lfsr_reg_i[7],lfsr_reg_i[5],lfsr_reg_i[4],lfsr_reg_i[3]);
    assign lfsr_256_equal_i = (lfsr_reg_i == 8'hFF);

    always @(posedge i_sys_clk,posedge i_sys_rst) begin
        if(i_sys_rst) begin
            lfsr_reg_i <= 0;
            o_lfsr_256_done <= 0;
        end
        else begin
            lfsr_reg_i <= lfsr_256_equal_i ? 8'h0 : {lfsr_reg_i[6:0],lfsr_d0_i};
            o_lfsr_256_done <= lfsr_256_equal_i;
        end
    end
endmodule

module fifo (
  input clk,
  input reset,
  input write_enable,
  input [7:0] write_data,
  input read_enable,
  output [7:0] read_data,
  output empty,
  output full
);

  reg [7:0] mem [63:0];
  reg [5:0] head = 0;
  reg [5:0] tail = 0;
  reg [5:0] count = 0;

  always @(posedge clk) begin
    if (reset) begin
      head <= 0;
      tail <= 0;
      count <= 0;
    end else begin
      if (write_enable && count < 64) begin
        mem[head] <= write_data;
        head <= head + 1;
        count <= count + 1;
      end
      if (read_enable && count > 0) begin
        read_data <= mem[tail];
        tail <= tail + 1;
        count <= count - 1;
      end
    end
  end

  assign empty = (count == 0);
  assign full = (count == 64);

endmodule

module sw_leds (
    // Wishbone slave interface
    input         wb_clk_i,
    input         wb_rst_i,
    input         wb_adr_i,
    output [15:0] wb_dat_o,
    input  [15:0] wb_dat_i,
    input  [ 1:0] wb_sel_i,
    input         wb_we_i,
    input         wb_stb_i,
    input         wb_cyc_i,
    output        wb_ack_o,

    // GPIO inputs/outputs
    output reg [13:0] leds_,
    input      [ 7:0] sw_,
    input             pb_,
    input             tick,
    output reg        nmi_pb
  );

  // Registers and nets
  wire op;
  reg tick_old;
  reg tick1;
  reg nmi_pb_pressed;
  reg [2:0] nmi_cnt;

  // Continuous assignments
  assign op       = wb_cyc_i & wb_stb_i;
  assign wb_ack_o = op;
  assign wb_dat_o = wb_adr_i ? { 2'b00, leds_ }
                             : { 8'h00, sw_ };

  // Behaviour
  always @(posedge wb_clk_i)
    leds_ <= wb_rst_i ? 14'h0
      : ((op & wb_we_i & wb_adr_i) ? wb_dat_i[13:0] : leds_);

  always @(sw_)
    leds_ <= sw_;

  always @(posedge wb_clk_i)
  begin
    tick_old <= tick;
    tick1 <= tick & ~tick_old;
  end

  always @(posedge wb_clk_i)
    nmi_pb_pressed <= !pb_;

  always @(posedge wb_clk_i)
  begin
    if (wb_rst_i)
    begin
      nmi_pb <= 1'b0;
      nmi_cnt <= 3'b111;
    end
    else
    begin
      if (nmi_cnt == 3'b111)
      begin
        if (nmi_pb_pressed != nmi_pb)
        begin
          nmi_pb <= nmi_pb_pressed;
          nmi_cnt <= nmi_cnt + 3'b001; // nmi_cnt <= 3'b000;
        end
      end
      else if (tick1)
        nmi_cnt <= nmi_cnt + 3'b001;
    end
  end

endmodule

module magnitude_comparator_decoder (
    input [3:0] a,
    input [3:0] b,
    output reg gt,
    output reg lt,
    output reg eq,
    input enable,
    input [1:0] select,
    input invert,
    output reg [7:0] out
);

    // 4-bit magnitude comparator module
    assign gt = (a > b);
    assign lt = (a < b);
    assign eq = (a == b);

    // 3-to-8 decoder module
    reg [7:0] decoder_out;
    always @ (enable or select) begin
        case (select)
            2'b00: decoder_out = 8'b00000001;
            2'b01: decoder_out = 8'b00000010;
            2'b10: decoder_out = 8'b00000100;
            2'b11: decoder_out = 8'b00001000;
        endcase
        if (invert) decoder_out = ~decoder_out;
    end

    // Functional module
    always @ (gt or lt or eq or decoder_out) begin
        out = (gt & decoder_out) | (lt & ~decoder_out) | (eq & enable);
    end

endmodule

module Multiplexer(input ctrl, input [0:0]D0, input [0:0]D1, output [0:0]S);

  wire [0:0]S;
  wire [2:0]lut;

  assign lut[0] = D1;
  assign lut[1] = ctrl;
  assign lut[2] = D0;

  LUT3 #(
    .INIT(8'hB8)
  ) mux_lut (
    .I0(lut[0]),
    .I1(lut[1]),
    .I2(lut[2]),
    .O(S)
  );

endmodule

module adder(
    input wire clk,
    input wire reset_n,
    input wire [7:0] a,
    input wire [7:0] b,
    output wire [7:0] sum,
    output wire carry
);

    reg [8:0] temp_sum;

    always @ (posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            temp_sum <= 0;
            carry <= 0;
        end else begin
            temp_sum <= a + b;
            carry <= temp_sum[8];
        end
    end

    assign sum = temp_sum[7:0];

endmodule

module clock_gate_D_ff_en_W32_0_6 (CLK, EN, TE, ENCLK);
  input CLK, EN, TE;
  output ENCLK;

  reg [1:0] stage1, stage2;

  always @(posedge CLK) begin
    if (EN) begin
      stage1 <= TE ? 1'b1 : 1'b0;
      stage2 <= stage1;
    end
  end

  assign ENCLK = stage2 & CLK;

endmodule

module transmitter(
    input clk_i,
    input reset_i,
    input [SRW:0] dat_i,
    input we_i,
    input [BW:0] bits_i,
    input [BRW:0] baud_i,
    input [2:0] txcmod_i,
    output txd_o,
    output txc_o,
    output not_full_o,
    output empty_o,
    output idle_o
);

    parameter SHIFT_REG_WIDTH = 16;
    parameter BITS_WIDTH = 5;
    parameter BAUD_RATE_WIDTH = 32;
    parameter DEPTH_BITS = 4;
    parameter DATA_BITS = SHIFT_REG_WIDTH;

    parameter BW = BITS_WIDTH - 1;
    parameter BRW = BAUD_RATE_WIDTH - 1;
    parameter SRW = SHIFT_REG_WIDTH - 1;

    wire txc;
    assign txc_o = (txc & txcmod_i[2]) ^ txcmod_i[0];
    wire [SRW:0] txq_dat;
    wire txq_en, txq_pop, txq_oe, txq_full, txq_empty;
    wire txq_idle;

    assign txq_en = txq_idle & ~txq_empty;
    assign txq_oe = txq_en;
    assign txq_pop = txq_en;
    assign empty_o = txq_empty;
    assign not_full_o = ~txq_full;
    assign idle_o = txq_idle;

    queue #(
        .DEPTH_BITS(DEPTH_BITS),
        .DATA_BITS(DATA_BITS)
    ) q (
        .clk_i(clk_i),
        .reset_i(reset_i),
        .dat_i(dat_i),
        .push_i(we_i),
        .pop_i(txq_pop),
        .oe_i(txq_oe),
        .dat_o(txq_dat),
        .full_o(txq_full),
        .empty_o(txq_empty)
    );

    sia_transmitter #(
        .SHIFT_REG_WIDTH(SHIFT_REG_WIDTH),
        .BAUD_RATE_WIDTH(BAUD_RATE_WIDTH),
        .BITS_WIDTH(BITS_WIDTH)
    ) t (
        .clk_i(clk_i),
        .reset_i(reset_i),
        .rxd_i(1'b1),
        .dat_i(txq_dat),
        .txreg_we_i(txq_en),
        .txreg_oe_i(1'b0),
        .txbaud_i(baud_i),
        .bits_i(bits_i),
        .txd_o(txd_o),
        .txc_o(txc),
        .idle_o(txq_idle),
        .brg_o(),
        .bits_o(),
        .dat_o()
    );
endmodule

module fifo_128_49 (
    aclr,
    clock,
    data,
    rdreq,
    wrreq,
    empty,
    q,
    usedw
);

input aclr;
input clock;
input [48:0] data;
input rdreq;
input wrreq;
output empty;
output [48:0] q;
output [7:0] usedw;

reg [48:0] fifo [0:127];
reg [6:0] head = 0;
reg [6:0] tail = 0;
reg [7:0] count = 0;
wire full = (count == 128);

assign empty = (count == 0);
assign usedw = count;

always @(posedge clock) begin
    if (aclr) begin
        head <= 0;
        tail <= 0;
        count <= 0;
    end else if (wrreq && !full) begin
        fifo[tail] <= data;
        tail <= (tail == 127) ? 0 : tail + 1;
        count <= count + 1;
    end else if (rdreq && !empty) begin
        q <= fifo[head];
        head <= (head == 127) ? 0 : head + 1;
        count <= count - 1;
    end else begin
        q <= 0;
    end
end

endmodule

module calculator (
  input clk,
  input reset,      // Synchronous active-high reset
  input [3:0] A,    // 4-bit input A
  input [3:0] B,    // 4-bit input B
  input [1:0] select, // Select input to choose between addition, subtraction, multiplication, and division
  output [3:0] result // 4-bit output
);

  // Internal signals
  reg [3:0] add_out;
  reg [3:0] sub_out;
  reg [7:0] mul_out;
  reg [3:0] div_out;
  reg [1:0] operation;

  // Instantiate adders, subtractors, multiplier, and divider
  adder add(A, B, add_out);
  subtractor sub(A, B, sub_out);
  multiplier mul(A, B, mul_out);
  divider div(A, B, div_out);

  // Control logic to determine operation
  always @ (posedge clk) begin
    if (reset) begin
      operation <= 2'b00; // Default to addition
    end else begin
      case (select)
        2'b00: operation <= 2'b00; // Addition
        2'b01: operation <= 2'b01; // Subtraction
        2'b10: operation <= 2'b10; // Multiplication
        2'b11: operation <= 2'b11; // Division
      endcase
    end
  end

  // Output result based on selected operation
  always @ (posedge clk) begin
    if (reset) begin
      result <= 4'b0000; // Default to 0
    end else begin
      case (operation)
        2'b00: result <= add_out; // Addition
        2'b01: result <= sub_out; // Subtraction
        2'b10: result <= mul_out[7:4]; // Multiplication
        2'b11: result <= div_out; // Division
      endcase
    end
  end

endmodule

// Adder module
module adder (
  input [3:0] A,
