    .en_funcion(en_funcion),
    .reg_a_d(reg_a_d), 		
    .reg_cs(reg_cs), 
    .reg_wr(reg_wr), 
    .reg_rd(reg_rd), 
    .out_direccion_dato(direccion_dato), 
    .flag_done(fin_lectura_escritura)
);

// Enable signal for the signal control RTC generator module
always@(posedge clk) begin
    if(port_id == 8'h0E) en_funcion <= 1'b1;
    else en_funcion <= 1'b0;
end

// Sequential logic for address and data signals
always@(negedge clk, posedge reset) begin
    if (reset) begin
        addr_RAM <= 8'h0;
        dato_escribir <= 8'h0;
        escribir_leer <= 1'b0;
    end
    else begin
        addr_RAM <= reg_addr_RAM;
        dato_escribir <= reg_dato_escribir;
        escribir_leer <= reg_escribir_leer;
    end
end

// Combinational logic for port_id
always@* begin
    if (write_strobe == 1'b1 || k_write_strobe == 1'b1) begin
        case (port_id)
            8'h00: begin // Update address
                reg_addr_RAM = in_dato;
                reg_dato_escribir = dato_escribir; 
                reg_escribir_leer = escribir_leer;
            end
            8'h01: begin // Update data
                reg_dato_escribir = in_dato;
                reg_addr_RAM = addr_RAM;
                reg_escribir_leer = escribir_leer;
            end
            8'h0E: begin // Start RTC sequence
                reg_addr_RAM = addr_RAM;
                reg_dato_escribir = dato_escribir;
                reg_escribir_leer = in_dato[0];
            end
            default: begin
                reg_addr_RAM = addr_RAM;
                reg_dato_escribir = dato_escribir;
                reg_escribir_leer = escribir_leer;
            end
        endcase	
    end
    else begin
        reg_addr_RAM = addr_RAM;
        reg_dato_escribir = dato_escribir;
        reg_escribir_leer = escribir_leer;
    end
end

// State machine for flag_done signal
always @ (negedge clk, posedge reset) begin 
    if (reset) state_reg_flag <= 1'b0;
    else state_reg_flag <= state_next_flag;
end

always@* begin
    state_next_flag = state_reg_flag;
    case (state_reg_flag)
        1'b0: begin
            flag_done = 8'h00;
            if (fin_lectura_escritura == 1) state_next_flag = 1'b1;
            else state_next_flag = 1'b0;
        end
        1'b1: begin
            flag_done = 8'h01;
            if(port_id == 8'h0F && read_strobe == 1)  state_next_flag = 1'b0;
            else  state_next_flag = 1'b1; 		
        end
    endcase
end

endmodule

module datapath(
    input clk,
    input [2:0] readnum,
    input vsel,
    input loada,
    input loadb,
    input [1:0] shift,
    input asel,
    input bsel,
    input [1:0] ALUop,
    input loadc,
    input loads,
    input [2:0] writenum,
    input write,
    input [15:0] datapath_in,
    output reg [15:0] datapath_out,
    output reg status
);

reg [15:0] regfile [2:0]; // 3 registers, each 16 bits wide
reg [15:0] A, B, C; // 16-bit inputs to the ALU
reg [3:0] shift_amt; // amount to shift B by
reg [15:0] ALUout; // output of the ALU
reg carry_out, overflow; // flags for the status register

always @(posedge clk) begin
    // read from register
    if (loada) A <= regfile[readnum];
    if (loadb) B <= regfile[readnum];

    // shift B
    case (shift)
        2'b00: shift_amt <= 1;
        2'b01: shift_amt <= 4;
        2'b10: shift_amt <= 8;
        2'b11: shift_amt <= 16;
    endcase
    B <= {B[shift_amt-1:0], {shift_amt{1'b0}}};

    // perform ALU operation
    case (ALUop)
        2'b00: ALUout <= A + B;
        2'b01: ALUout <= A - B;
        2'b10: ALUout <= A & B;
        2'b11: ALUout <= A | B;
    endcase
    carry_out <= ALUout[16];
    overflow <= (A[15] == B[15] && ALUout[15] != A[15]);

    // load output into C
    if (loadc) C <= ALUout;

    // write to register
    if (write && vsel) regfile[writenum] <= datapath_in;

    // set output
    if (asel) datapath_out <= A;
    else if (bsel) datapath_out <= B;
    else datapath_out <= ALUout;

    // set status register
    if (loads) status <= carry_out || overflow;
end

endmodule

module spi_master(
    input clk,
