    output reg sm_rd_cs_n_256,
    output reg spi_receive_rd_status_256
);

reg spi_tx_en;
reg spi_rx_en;

spi_ctrl_reduced #(.DATA_LENGTH(256)) spi_ctrl_reduced_instance_256(
