        sm_rd_mosi_256 <= 1'b0;
        sm_rd_sck_256 <= 1'b0;
    end else begin
        if (mode_rd_select_256) begin
            // custom mode
            if (spi_rx_rd_en_256) begin
                sm_rd_mosi_256 <= spi_receive_rd_status_256;
            end
            if (spi_tx_rd_en_256) begin
                spi_tx_en <= 1'b1;
            end
        end else begin
            // standard SPI mode
            if (spi_rx_rd_en_256) begin
                spi_tx_en <= 1'b0;
                sm_rd_mosi_256 <= 1'b0;
            end
            if (spi_tx_rd_en_256) begin
                spi_tx_en <= 1'b1;
