module up_counter(CLK, EN, TE, ENCLK);
    input CLK, EN, TE;
    output ENCLK;

    reg [3:0] count;
    wire [3:0] next_count;

    TLATNTSCAX2TS latch (.E(EN), .SE(TE), .CK(CLK), .ECK(ENCLK));

    always @(posedge ENCLK) begin
        if (EN) begin
            if (TE) begin
                if (count == 4'h0) begin
                    next_count = 4'hF;
                end else begin
                    next_count = count - 1;
                end
            end else begin
                if (count == 4'hF) begin
                    next_count = 4'h0;
                end else begin
                    next_count = count + 1;
                end
            end
        end else begin
            next_count = count;
        end
    end

    always @(posedge ENCLK) begin
        count <= next_count;
    end
endmodule

module ripple_carry_adder(
    input [3:0] A,
    input [3:0] B,
    output [3:0] S,
    output C_out
);

    wire [3:0] sum;
    wire [3:0] carry;

    // Full adder for LSB
    full_adder FA0(.a(A[0]), .b(B[0]), .c_in(1'b0), .sum(sum[0]), .c_out(carry[0]));

    // Full adder for second bit
    full_adder FA1(.a(A[1]), .b(B[1]), .c_in(carry[0]), .sum(sum[1]), .c_out(carry[1]));

    // Full adder for third bit
    full_adder FA2(.a(A[2]), .b(B[2]), .c_in(carry[1]), .sum(sum[2]), .c_out(carry[2]));

    // Full adder for MSB
    full_adder FA3(.a(A[3]), .b(B[3]), .c_in(carry[2]), .sum(sum[3]), .c_out(C_out));

    assign S = sum;

endmodule

module full_adder(
    input a,
    input b,
    input c_in,
    output sum,
    output c_out
);

    assign sum = a ^ b ^ c_in;
    assign c_out = (a & b) | (c_in & (a ^ b));

endmodule

module baud_rate_generator(
    input clk, rst_n, bps_start,
    output reg clk_baud
);

parameter BAUD_RATE = 9600;

reg [31:0] counter;
reg toggle;

always @(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        counter <= 0;
        toggle <= 0;
    end
    else if(bps_start) begin
        counter <= counter + 1;
        if(counter == ($freq / (BAUD_RATE * 2))) begin
            toggle <= ~toggle;
            counter <= 0;
        end
    end
end

assign clk_baud = toggle;

endmodule

