module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [31:0] in,  // 32-bit input for the byte-order-reversing circuit
    input [1:0] select,  // Select input to choose between the byte-order-reversing circuit and the three-way comparator
    output out_gt,    // Output of the greater than comparison
    output out_lt,    // Output of the less than comparison
    output out_eq,    // Output of the equal to comparison
    output [31:0] out_reversed   // Output of the byte-order-reversing circuit
);

reg [31:0] reversed;
wire [7:0] a, b, c;
wire gt, lt, eq;

// Byte-order-reversing circuit
always @ (posedge clk) begin
    if (reset) begin
        reversed <= 0;
    end else if (select == 2'b00) begin
        reversed <= {in[7:0], in[15:8], in[23:16], in[31:24]};
    end
end

// Three-way comparator
assign a = in[7:0];
assign b = in[15:8];
assign c = in[23:16];
assign gt = (a > b) && (a > c);
assign lt = (a < b) && (a < c);
assign eq = (a == b) && (a == c);

// Bitwise AND
assign out_reversed = (select == 2'b10) ? (a & b & c) : out_reversed;

// Bitwise OR
assign out_reversed = (select == 2'b11) ? (a | b | c) : out_reversed;

// Output
assign out_gt = (select == 2'b01) ? gt : 1'b0;
assign out_lt = (select == 2'b01) ? lt : 1'b0;
assign out_eq = (select == 2'b01) ? eq : 1'b0;
assign out_reversed = (select == 2'b00) ? reversed : out_reversed;

endmodule

