module top_module (
    input clk,
    input rst_n,
    input cin,
    input select,
    input [7:0] A,
    input [7:0] B,
    output reg [8:0] sum,
    output reg cout
);

    reg [3:0] lower_A;
    reg [3:0] lower_B;
    reg [3:0] lower_sum;
    reg lower_cout;

    wire [3:0] upper_A;
    wire [3:0] upper_B;
    wire [3:0] upper_sum;
    wire upper_cout;

    binary_adder lower_adder (
        .A(lower_A),
        .B(lower_B),
        .cin(cin),
        .sum(lower_sum),
        .cout(lower_cout)
    );

    binary_ripple_adder upper_adder (
        .A(upper_A),
        .B(upper_B),
        .cin(lower_cout),
        .sum(upper_sum),
        .cout(upper_cout)
    );

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sum <= 9'b0;
            cout <= 1'b0;
            lower_A <= 4'b0;
            lower_B <= 4'b0;
            lower_sum <= 4'b0;
            lower_cout <= 1'b0;
        end else begin
            if (select) begin
                lower_A <= A[3:0];
                lower_B <= B[3:0];
                lower_sum <= sum[3:0];
                lower_cout <= cout;
            end else begin
                upper_A <= A[7:4];
                upper_B <= B[7:4];
                upper_sum <= sum[7:4];
                upper_cout <= cout;
            end

            if (select) begin
                sum <= {upper_sum, lower_sum};
                cout <= upper_cout;
            end else begin
                sum <= {upper_sum, lower_sum};
                cout <= lower_cout;
            end
        end
    end

endmodule

