module hamming_parity_priority (
    input [7:0] in,
    output [8:0] out
);

    // Hamming code-based parity generator
    wire [3:0] parity;
    assign parity[0] = in[0] ^ in[1] ^ in[3];
    assign parity[1] = in[0] ^ in[2] ^ in[3];
    assign parity[2] = in[1] ^ in[2] ^ in[3];
    assign parity[3] = in[0] ^ in[1] ^ in[2] ^ in[3];
    wire parity_bit = parity[3];

    // Priority encoder
    wire [2:0] position;
    assign position = (in[0]) ? 0 : (in[1]) ? 1 : (in[2]) ? 2 : (in[3]) ? 3 : (in[4]) ? 4 : (in[5]) ? 5 : (in[6]) ? 6 : (in[7]) ? 7 : 8;

    // Output
    assign out[8] = parity_bit;
    assign out[7:0] = (position == 8) ? 0 : (1 << position);

endmodule

module final_output (
    input [8:0] in,
    output [7:0] out
);

    wire [7:0] shifted_in = (in[8] == 1) ? (in[7:0] | (1 << (in[6:0]))) : in[7:0];
    assign out = shifted_in;

endmodule

