    input [7:0] in,
    output [8:0] out
);

    wire [8:0] intermediate_out;
    hamming_parity_priority hpp(in, intermediate_out);
    final_output fo(intermediate_out, out);

endmodule

module calculator(
    input [127:0] r_A,
    input [127:0] r_B,
    input [1:0] c_ww,
    input [4:0] a_op,
    output [127:0] res
);

    reg [127:0] temp_res;
    reg [127:0] temp_r_A;
    reg [127:0] temp_r_B;

    always @(*)
    begin
        case(c_ww)
            2'b00: temp_r_A = r_A[7:0];
            2'b01: temp_r_A = r_A[15:0];
            2'b10: temp_r_A = r_A[31:0];
            2'b11: temp_r_A = r_A[63:0];
            default: temp_r_A = r_A;
        endcase

        case(c_ww)
            2'b00: temp_r_B = r_B[7:0];
            2'b01: temp_r_B = r_B[15:0];
            2'b10: temp_r_B = r_B[31:0];
            2'b11: temp_r_B = r_B[63:0];
            default: temp_r_B = r_B;
        endcase

        case(a_op)
            5'b00001: temp_res = temp_r_A & temp_r_B;
            5'b00010: temp_res = temp_r_A | temp_r_B;
            5'b00011: temp_res = temp_r_A ^ temp_r_B;
            5'b00100: temp_res = temp_r_A + temp_r_B;
            5'b00101: temp_res = temp_r_A - temp_r_B;
            5'b00110: temp_res = temp_r_A * temp_r_B;
            5'b00111: temp_res = $signed(temp_r_A) * $signed(temp_r_B);
            5'b01000: temp_res = temp_r_A * temp_r_B;
            5'b01001: temp_res = $signed(temp_r_A) * $signed(temp_r_B);
            default: temp_res = 128'h0;
        endcase

        res = temp_res;
    end

endmodule

