    reg [2:0] phase_transfer_counter;
    reg delayed_data;
    reg dff1t_reg;
    reg dff2t_reg1;
    reg dff2t_reg2;
    reg dffphasetransfer_reg;

    always @(posedge clk or negedge areset) begin
        if(!areset) begin
            delay_counter <= 0;
