module spi_interface (
  input spi_csn_0,
  input spi_csn_1,
  input spi_clk,
  input spi_mosi,
  inout spi_sdio,
  output spi_miso,
  output spi_dirn
);

  // Internal registers and signals
  reg [5:0] spi_count = 6'b0;
  reg spi_rd_wr_n = 1'b0;
  reg spi_enable = 1'b0;
  wire spi_csn_s = spi_csn_0 & spi_csn_1;
  wire spi_enable_s = spi_enable & ~spi_csn_s;

  // Assign signals
  assign spi_dirn = ~spi_enable_s;
  assign spi_miso = spi_enable_s ? spi_mosi : 1'bz;

  // Count bits and sample MOSI
  always @(posedge spi_clk or posedge spi_csn_s) begin
    if (spi_csn_s) begin
      spi_count <= 6'b0;
      spi_rd_wr_n <= 1'b0;
    end else begin
      spi_count <= spi_count + 1'b1;
      if (spi_count == 6'b0) begin
        spi_rd_wr_n <= spi_mosi;
      end
    end
  end

  // Enable SPI interface and control direction
  always @(negedge spi_clk or posedge spi_csn_s) begin
    if (spi_csn_s) begin
      spi_enable <= 1'b0;
    end else begin
      if (spi_count == 6'b10000) begin
        spi_enable <= spi_rd_wr_n;
      end
    end
  end

  // IO buffer
  IOBUF iobuf_sdio (
    .T(spi_enable_s),
    .I(spi_mosi),
    .O(spi_miso),
    .IO(spi_sdio)
  );

endmodule

