module contador_AD_MES_2dig
(
input wire clk,
input wire reset,
input wire [3:0] en_count,
input wire enUP,
input wire enDOWN,
output wire [7:0] data_MES
);

localparam N = 4; // Para definir el número de bits del contador (hasta 12->4 bits)
//Declaración de señales
reg [N-1:0] q_act, q_next;
wire [N-1:0] count_data;
reg [3:0] digit1, digit0;

//Descripción del comportamiento
always@(posedge clk, posedge reset)
begin	

	if(reset)
	begin
		q_act <= 4'b0;
	end

	else
	begin
		q_act <= q_next;
	end
end


//Lógica de salida

always@*
begin

	if (en_count == 5)
	begin
		if (enUP)
		begin
			if (q_act >= 4'd11) q_next = 4'd0;
			else q_next = q_act + 4'd1;
		end

		else if (enDOWN)
		begin
			if (q_act == 4'd0) q_next = 4'd11;
			else q_next = q_act - 4'd1;
		end
		else q_next = q_act;
	end
	else q_next = q_act;

end

assign count_data = q_act + 1'b1;//Suma 1 a todas las cuentas de 0->11 a 1->12

//Decodificación BCD (2 dígitos)

always@*
begin
case(count_data)

8'd1: begin digit1 = 4'b0000; digit0 = 4'b0001; end
8'd2: begin digit1 = 4'b0000; digit0 = 4'b0010; end
8'd3: begin digit1 = 4'b0000; digit0 = 4'b0011; end
8'd4: begin digit1 = 4'b0000; digit0 = 4'b0100; end
8'd5: begin digit1 = 4'b0000; digit0 = 4'b0101; end
8'd6: begin digit1 = 4'b0000; digit0 = 4'b0110; end
8'd7: begin digit1 = 4'b0000; digit0 = 4'b0111; end
8'd8: begin digit1 = 4'b0000; digit0 = 4'b1000; end
8'd9: begin digit1 = 4'b0000; digit0 = 4'b1001; end

8'd10: begin digit1 = 4'b0001; digit0 = 4'b0000; end
8'd11: begin digit1 = 4'b0001; digit0 = 4'b0001; end
8'd12: begin digit1 = 4'b0001; digit0 = 4'b0010; end

default:  begin digit1 = 0; digit0 = 0; end
endcase
end

assign data_MES = {digit1,digit0};

endmodule

module CIC (
  input [n-1:0] in,
  input rst,
  output [m-1:0] out
);

parameter n = 1;  // number of input signals
parameter m = 1;  // number of output signals
parameter R = 2;  // decimation/interpolation ratio
parameter M = 2;  // number of stages
parameter N = R**M;  // number of samples per stage

wire [N-1:0] integrator_out;
wire [N-1:0] comb_filter_out;
reg [N-1:0] delay_reg;

// Instantiate integrator and comb filter modules
integrator #(.N(N)) integrator_inst (.in(in), .out(integrator_out));
comb_filter #(.N(N), .M(M)) comb_filter_inst (.in(integrator_out), .out(comb_filter_out));

// Implement delay register
always @(posedge clk) begin
  if (rst) begin
    delay_reg <= 0;
  end else begin
    delay_reg <= comb_filter_out;
  end
end

// Implement final comb filter
always @(posedge clk) begin
  if (rst) begin
    out <= 0;
  end else begin
    out <= comb_filter_out - delay_reg;
  end
end

endmodule

module integrator (
  input [N-1:0] in,
  output reg out
);

parameter N = 4;  // number of samples per stage

// Implement integrator function
always @(in) begin
  out <= $signed($sum(in));
end

endmodule

module comb_filter (
  input [N-1:0] in,
  output reg out
);

parameter N = 4;  // number of samples per stage
parameter M = 2;  // number of stages

// Implement comb filter function
always @(in) begin
  out <= in - $signed({M{in[N-1]}});
end

endmodule

module top_module(
    input signed [31:0] a,
    input signed [31:0] b,
    output signed [31:0] product
);

    wire signed [31:0] stage1_out;
    wire signed [31:0] stage2_out;
    wire signed [31:0] stage3_out;
    wire signed [31:0] stage4_out;

    // instantiate four 8-bit multiplication modules
    mult8bit mult1(.a(a[7:0]), .b(b[7:0]), .product(stage1_out[7:0]));
    mult8bit mult2(.a(a[15:8]), .b(b[15:8]), .product(stage2_out[15:8]));
    mult8bit mult3(.a(a[23:16]), .b(b[23:16]), .product(stage3_out[23:16]));
    mult8bit mult4(.a(a[31:24]), .b(b[31:24]), .product(stage4_out[31:24]));

    // pipeline structure
    reg signed [31:0] stage1_reg;
    reg signed [31:0] stage2_reg;
    reg signed [31:0] stage3_reg;
    reg signed [31:0] stage4_reg;

    always @(*) begin
        stage1_reg = stage1_out;
    end

    always @(*) begin
        stage2_reg = stage2_out;
    end

    always @(*) begin
        stage3_reg = stage3_out;
    end

    always @(*) begin
        stage4_reg = stage4_out;
    end

    assign product = stage4_reg;

