module priority_encoder (
    input [7:0] in,
    output reg [2:0] out
);
    always @* begin
        case (in)
            8'b00000001: out = 0;
            8'b00000010: out = 1;
            8'b00000100: out = 2;
            8'b00001000: out = 3;
            8'b00010000: out = 4;
            8'b00100000: out = 5;
            8'b01000000: out = 6;
            8'b10000000: out = 7;
            default: out = 3'b111;
        endcase
    end
endmodule

module binary_tree_adder (
    input [255:0] in,
    output reg [8:0] out
);
    reg [8:0] temp [0:255];
    integer i, j, k;

    always @* begin
        for (i = 0; i < 256; i = i + 1) begin
            temp[i] = in[i];
        end

        for (i = 0; i < 8; i = i + 1) begin
            for (j = 0; j < 2 ** (8 - i - 1); j = j + 1) begin
                k = j * 2 ** i;
                temp[k + 2 ** i - 1] = temp[k + 2 ** i - 1] + temp[k + 2 ** (i - 1) - 1];
            end
        end

        out = temp[255];
    end
endmodule

module combined_module (
    input [7:0] in,
    output reg [10:0] out
);
    wire [2:0] priority_out;
    wire [255:0] shifted_in;
    wire [8:0] adder_out;

    priority_encoder priority_encoder_inst (
        .in(in),
        .out(priority_out)
    );

    assign shifted_in = {in[priority_out[2]:0], 8'b0};

    binary_tree_adder binary_tree_adder_inst (
        .in(shifted_in),
        .out(adder_out)
    );

    always @* begin
        out = {priority_out, adder_out};
    end
endmodule

