assign ram0bankx_enable = (SNES_ADDR[23:16] == 8'hC8);
assign ram0linear_enable = ram0_linear & (SNES_ADDR[22] | SNES_ADDR[15]);
assign ram0_enable = ram0linear_enable | ram0bank0_enable | ram0bankx_enable;
