module top_module (
    input clk,
    input reset,
    input [3:0] B,
    input [2:0] shift_amount,
    output [7:0] data_out
);

    reg [3:0] next_num;
    wire [7:0] shifted_num;

    next_binary_number next_num_module(
        .B(B),
        .N(next_num)
    );

    barrel_shifter barrel_shifter_module(
        .data_in({next_num, 4'b0}),
        .shift_amount(shift_amount),
