module fsm_sequence_detection (
  input clk,
  input reset,
  input data,
  output reg match
);

reg [1:0] state;

parameter IDLE = 2'b00;
parameter STATE1 = 2'b01;
parameter STATE2 = 2'b10;

always @(posedge clk) begin
  if (reset) begin
    state <= IDLE;
    match <= 0;
  end
  else begin
    case (state)
      IDLE: begin
        if (data == 1) begin
          state <= STATE1;
        end
        else begin
          state <= IDLE;
        end
      end
      STATE1: begin
        if (data == 0) begin
          state <= STATE2;
        end
        else begin
          state <= IDLE;
        end
      end
      STATE2: begin
        if (data == 1) begin
          state <= IDLE;
          match <= 1;
        end
        else begin
          state <= IDLE;
        end
      end
    endcase
  end
end

endmodule

