module shift_register_and_binary_counter (
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] d,    // 8-bit input for the shift register
    output [7:0] q,   // 8-bit output from the shift register
    output reg [3:0] count_out, // 4-bit output from the binary counter
    input select      // Select input to choose active module
);

    reg [7:0] shift_reg;    // 8-bit shift register
    reg [3:0] binary_count; // 4-bit binary counter
    reg active_module;      // 1-bit flag to indicate active module

    // Shift register with ring counter architecture
    always @(posedge clk) begin
        if (reset) begin
            shift_reg <= 8'b0;
        end else begin
            shift_reg <= {shift_reg[6:0], d};
        end
    end

    // Binary counter with synchronous reset
    always @(posedge clk) begin
        if (reset) begin
            binary_count <= 4'b0;
        end else begin
            binary_count <= binary_count + 1;
        end
    end

    // Control logic to select active module
    always @(select) begin
        if (select) begin
            active_module <= 1'b1; // Binary counter is active
        end else begin
            active_module <= 1'b0; // Shift register is active
        end
    end

    // Output sum of active module and other module
    always @(posedge clk) begin
        if (reset) begin
            count_out <= 4'b0;
            q <= 8'b0;
        end else begin
            if (active_module) begin
                count_out <= binary_count;
                q <= {8{1'b0}} + binary_count;
            end else begin
                count_out <= 4'b0;
                q <= shift_reg;
            end
        end
    end

endmodule

