        else if ({iY_Cont[0], iX_Cont[0]} == 2'b01) begin
            mCCD_R <= mDATAd_1;
            mCCD_G <= mDATAd_0 + mDATA_1;
            mCCD_B <= mDATA_0;
        end
    end
end

