module top_module (
    input clk,
    input reset,   // Synchronous active-high reset
    input [7:0] a, b, c, d,  // Input numbers for the priority encoder
    output [15:0] q);  // Output representing the concatenation of the BCD counter output and the minimum value

    wire [7:0] min_val;
    wire [3:0] bcd_out;
    wire [12:0] counter_out;
    wire [3:0] enable;

    priority_encoder pe_inst (
        .a(a),
        .b(b),
        .c(c),
        .d(d),
        .out(min_val)
    );

    bcd_counter bcd_inst (
        .clk(clk),
        .reset(reset),
        .out(bcd_out),
        .counter_out(counter_out),
        .enable(enable)
    );

    final_output final_inst (
        .min_val(min_val),
        .bcd_out(bcd_out),
        .q(q)
    );

    control_logic control_inst (
        .clk(clk),
        .reset(reset),
        .enable(enable)
    );

endmodule

module priority_encoder (
    input [7:0] a, b, c, d,
    output [7:0] out
);

    assign out = (a < b) ? ((a < c) ? ((a < d) ? a : d) : ((c < d) ? c : d)) : ((b < c) ? ((b < d) ? b : d) : ((c < d) ? c : d));

endmodule

module bcd_counter (
    input clk,
    input reset,
    output reg [3:0] out,
    output reg [12:0] counter_out,
    input [3:0] enable
);

    reg [3:0] digit0;
    reg [3:0] digit1;
    reg [3:0] digit2;
    reg [3:0] digit3;

    always @(posedge clk) begin
        if (reset) begin
            digit0 <= 4'b0000;
            digit1 <= 4'b0000;
            digit2 <= 4'b0000;
            digit3 <= 4'b0000;
            counter_out <= 13'b0000000000000;
        end else if (enable[0]) begin
            digit0 <= digit0 + 1;
            if (digit0 == 10) begin
                digit0 <= 4'b0000;
                digit1 <= digit1 + 1;
                if (digit1 == 10) begin
                    digit1 <= 4'b0000;
                    digit2 <= digit2 + 1;
                    if (digit2 == 10) begin
                        digit2 <= 4'b0000;
                        digit3 <= digit3 + 1;
                        if (digit3 == 10) begin
                            digit3 <= 4'b0000;
                        end
                    end
                end
            end
            counter_out <= counter_out + 1;
        end else begin
            counter_out <= counter_out;
        end
    end

    assign out = {digit3, digit2, digit1, digit0};

endmodule

module final_output (
    input [7:0] min_val,
    input [3:0] bcd_out,
    output [15:0] q
);

    assign q = {bcd_out, min_val};

endmodule

module control_logic (
    input clk,
    input reset,
    output reg [3:0] enable
);

    reg [1:0] state;

    always @(posedge clk) begin
        if (reset) begin
            state <= 2'b00;
            enable <= 4'b0000;
        end else begin
            case (state)
                2'b00: begin
                    state <= 2'b01;
                    enable <= 4'b0001;
                end
                2'b01: begin
                    state <= 2'b10;
                    enable <= 4'b1110;
                end
                2'b10: begin
                    state <= 2'b11;
                    enable <= 4'b0000;
                end
                2'b11: begin
                    state <= 2'b00;
                    enable <= 4'b0001;
                end
            endcase
        end
    end

endmodule

