module range_entity(
    input [3:0] left_asc,
    input [3:0] right_asc,
    input [3:0] left_dsc,
    input [3:0] right_dsc,
    output reg [4:0] pow_left,
    output reg [1:0] rem_left,
    output reg [3:0] ascending [0:3],
    output reg [3:0] descending [0:3],
    output reg [3:0] ascending_rev [0:3],
    output reg [3:0] descending_rev [0:3]
);

reg [3:0] i;

// calculate pow_left
always @(*) begin
    pow_left = 2**(left_asc - 1);
end

// calculate rem_left
always @(*) begin
    rem_left = left_asc % 4;
end

// calculate ascending
always @(*) begin
    for (i = 0; i <= (right_asc - left_asc); i = i + 1) begin
        ascending[i] = (2**i) * left_asc;
    end
end

// calculate descending
always @(*) begin
    for (i = 0; i <= (left_dsc - right_dsc); i = i + 1) begin
        descending[i] = (3**i) * left_dsc;
    end
end

// calculate ascending_rev
always @(*) begin
    for (i = 0; i <= (right_asc - left_asc); i = i + 1) begin
        ascending_rev[i] = (2**(right_asc - left_asc - i)) * right_asc;
    end
end

// calculate descending_rev
always @(*) begin
    for (i = 0; i <= (left_dsc - right_dsc); i = i + 1) begin
        descending_rev[i] = (5**(left_dsc - right_dsc - i)) * right_dsc;
    end
end

endmodule

