module barrel_shifter (
    input [15:0] A,
    input [15:0] B,
    input [3:0] SHIFT,
    output reg [15:0] S
);

reg [15:0] stage1_out;
reg [15:0] stage2_out;

always @(*) begin
    case (SHIFT)
        4'b0000: stage1_out = A;
        4'b0001: stage1_out = A << 1;
        4'b0010: stage1_out = A << 2;
        4'b0011: stage1_out = A << 3;
        4'b0100: stage1_out = A << 4;
        4'b0101: stage1_out = A << 5;
        4'b0110: stage1_out = A << 6;
        4'b0111: stage1_out = A << 7;
        4'b1000: stage1_out = A << 8;
        4'b1001: stage1_out = A << 9;
        4'b1010: stage1_out = A << 10;
        4'b1011: stage1_out = A << 11;
        4'b1100: stage1_out = A << 12;
        4'b1101: stage1_out = A << 13;
        4'b1110: stage1_out = A << 14;
        4'b1111: stage1_out = A << 15;
        default: stage1_out = A;
    endcase
end

always @(*) begin
    if (SHIFT[3] == 1) begin
        stage2_out = B >> 8;
    end else begin
        stage2_out = stage1_out;
    end
end

always @(posedge clk) begin
    S <= stage2_out;
end

endmodule

module UART_Transceiver (
    input i_Clk,
    input i_RX_Serial,
    input [7:0] i_TX_Byte,
    input i_TX_Load,
    output reg [7:0] o_RX_Byte,
    output reg o_RX_Done,
    output reg o_TX_Active,
    output reg o_TX_Done,
    output reg o_TX_Serial
);

parameter BAUD_RATE = 115200;
parameter CLK_FREQ = 50000000;

reg [2:0] state;
reg [7:0] shift_reg;
reg [3:0] bit_count;
reg [31:0] baud_counter;

assign o_TX_Serial = shift_reg[0];

always @(posedge i_Clk) begin
    // Receiver state machine
    case (state)
        3'b000: begin // Wait for start bit
            if (!i_RX_Serial) begin
                state <= 3'b001;
                bit_count <= 4'b0000;
                baud_counter <= 0;
            end
        end
        3'b001: begin // Receive data bits
            if (baud_counter == (CLK_FREQ / BAUD_RATE) - 1) begin
                baud_counter <= 0;
                shift_reg <= {shift_reg[6:0], i_RX_Serial};
                bit_count <= bit_count + 1;
                if (bit_count == 4'b1000) begin
                    state <= 3'b010;
                    o_RX_Byte <= shift_reg[7:0];
                end
            end else begin
                baud_counter <= baud_counter + 1;
            end
        end
        3'b010: begin // Wait for stop bit
            if (baud_counter == (CLK_FREQ / BAUD_RATE) - 1) begin
                baud_counter <= 0;
                o_RX_Done <= 1;
                state <= 3'b000;
            end else begin
                baud_counter <= baud_counter + 1;
            end
        end
    endcase

    // Transmitter state machine
    if (i_TX_Load) begin
        shift_reg <= i_TX_Byte;
        bit_count <= 4'b0000;
        o_TX_Active <= 1;
        o_TX_Done <= 0;
        state <= 3'b100;
    end else begin
        case (state)
            3'b100: begin // Transmit start bit
                if (baud_counter == (CLK_FREQ / BAUD_RATE) - 1) begin
                    baud_counter <= 0;
                    o_TX_Serial <= 0;
                    state <= 3'b101;
                end else begin
                    baud_counter <= baud_counter + 1;
                end
            end
            3'b101: begin // Transmit data bits
                if (baud_counter == (CLK_FREQ / BAUD_RATE) - 1) begin
                    baud_counter <= 0;
                    shift_reg <= {shift_reg[6:0], 1'b0};
                    bit_count <= bit_count + 1;
                    if (bit_count == 4'b1000) begin
                        state <= 3'b110;
                    end
                end else begin
                    baud_counter <= baud_counter + 1;
                end
            end
            3'b110: begin // Transmit stop bit
                if (baud_counter == (CLK_FREQ / BAUD_RATE) - 1) begin
                    baud_counter <= 0;
                    o_TX_Serial <= 1;
                    o_TX_Active <= 0;
                    o_TX_Done <= 1;
                    state <= 3'b000;
                end else begin
                    baud_counter <= baud_counter + 1;
                end
            end
        endcase
    end
end

endmodule

