module tlb (
    // Clock and reset
    input clk,
    input rst,

    // Virtual address input
    input [31:0] vaddr,

    // TLB enable signal
    input tlb_en,

    // SPR access signals
    input spr_cs,
    input spr_write,
    input [31:0] spr_addr,
    input [31:0] spr_dat_i,
    output [31:0] spr_dat_o,

    // Output signals
    output hit,
    output [31:0] ppn,
    output uwe,
    output ure,
    output swe,
    output sre,
    output ci
);

// Constants
parameter TLB_SIZE = 64;
parameter DTLB_TAG_WIDTH = 19;
parameter DTLB_INDX_WIDTH = 6;
parameter DTLB_INDXW = 1 << DTLB_INDX_WIDTH;
parameter DTLB_TAGW = 1 << (DTLB_TAG_WIDTH - 3);
parameter DTLB_DTAGW = 1 << (DTLB_TAG_WIDTH - 2);
parameter DTLBMRW = DTLB_TAG_WIDTH + 1;
parameter DTLBTRW = 19 + 5 + 5 + 5 + 5 + 1;
parameter DMMU_PS = 22;

// Internal wires and regs
wire [DTLB_TAG_WIDTH-1:0] vpn;
wire v;
wire [DTLB_INDXW-1:0] tlb_index;
wire tlb_mr_en;
wire tlb_mr_we;
wire [DTLBMRW-1:0] tlb_mr_ram_in;
wire [DTLBMRW-1:0] tlb_mr_ram_out;
wire tlb_tr_en;
wire tlb_tr_we;
wire [DTLBTRW-1:0] tlb_tr_ram_in;
wire [DTLBTRW-1:0] tlb_tr_ram_out;

// Enable for Match registers
assign tlb_mr_en = tlb_en | (spr_cs & !spr_addr[DTLB_TAG_WIDTH+DTLB_INDX_WIDTH-1:DTLB_INDX_WIDTH]);

// Write enable for Match registers
assign tlb_mr_we = spr_cs & spr_write & !spr_addr[DTLB_TAG_WIDTH+DTLB_INDX_WIDTH-1:DTLB_INDX_WIDTH];

// Enable for Translate registers
assign tlb_tr_en = tlb_en | (spr_cs & spr_addr[DTLB_TAG_WIDTH+DTLB_INDX_WIDTH-1:DTLB_INDX_WIDTH]);

// Write enable for Translate registers
assign tlb_tr_we = spr_cs & spr_write & spr_addr[DTLB_TAG_WIDTH+DTLB_INDX_WIDTH-1:DTLB_INDX_WIDTH];

// Output to SPRS unit
assign spr_dat_o = (spr_cs & !spr_write & !spr_addr[DTLB_TAG_WIDTH+DTLB_INDX_WIDTH-1:DTLB_INDX_WIDTH]) ?
            {vpn, tlb_index & {DTLB_INDXW{v}}, {DTLB_TAGW-7{1'b0}}, 1'b0, 5'b00000, v} :
        (spr_cs & !spr_write & spr_addr[DTLB_TAG_WIDTH+DTLB_INDX_WIDTH-1:DTLB_INDX_WIDTH]) ?
            {ppn, {DMMU_PS-10{1'b0}}, swe, sre, uwe, ure, {4{1'b0}}, ci, 1'b0} :
            32'h00000000;

// Assign outputs from Match registers
assign {vpn, v} = tlb_mr_ram_out;

// Assign to Match registers inputs
assign tlb_mr_ram_in = {spr_dat_i[DTLB_TAG_WIDTH-1:0], spr_dat_i[DTLB_TAG_WIDTH]};

// Assign outputs from Translate registers
assign {ppn, swe, sre, uwe, ure, ci} = tlb_tr_ram_out;

// Assign to Translate registers inputs
assign tlb_tr_ram_in = {spr_dat_i[31:DMMU_PS],
            spr_dat_i[DTLBTRW-5],
            spr_dat_i[DTLBTRW-10:DTLBTRW-6],
            spr_dat_i[DTLBTRW-15:DTLBTRW-11],
            spr_dat_i[DTLBTRW-20:DTLBTRW-16],
            spr_dat_i[DTLBTRW-1]};

// Generate hit
assign hit = (vpn == vaddr[DTLB_TAG_WIDTH-1:0]) & v;

// TLB index is normally vaddr[18:13]. If it is SPR access then index is
// spr_addr[5:0].
assign tlb_index = spr_cs ? spr_addr[DTLB_INDX_WIDTH-1:0] : vaddr[DTLB_INDX_WIDTH+DTLB_TAG_WIDTH-1:DTLB_INDX_WIDTH];

// Instantiation of DTLB Match Registers
or1200_spram_64x20 dtlb_mr_ram(
    .clk(clk),
    .rst(rst),
    .ce(tlb_mr_en),
    .we(tlb_mr_we),
    .oe(1'b1),
    .addr(tlb_index),
    .di(tlb_mr_ram_in),
    .doq(tlb_mr_ram_out)
);

// Instantiation of DTLB Translate Registers
or1200_spram_64x24 dtlb_tr_ram(
    .clk(clk),
    .rst(rst),
    .ce(tlb_tr_en),
    .we(tlb_tr_we),
    .oe(1'b1),
    .addr(tlb_index),
    .di(tlb_tr_ram_in),
    .doq(tlb_tr_ram_out)
);

// Extract physical page number from TLB output
assign ppn = {tlb_tr_ram_out[18:0], 10'b0};

// Extract protection bits from TLB output
assign uwe = tlb_tr_ram_out[23];
assign ure = tlb_tr_ram_out[22];
assign swe = tlb_tr_ram_out[21];
assign sre = tlb_tr_ram_out[20];

// Extract cache inhibit bit from TLB output
assign ci = tlb_tr_ram_out[19];

endmodule

module LZW (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 8; // width of input data
parameter m = 12; // width of compressed data
parameter k = 256; // maximum size of dictionary

// Define dictionary and codes
reg [n-1:0] dict [0:k-1];
reg [m-1:0] codes [0:k-1];
reg [n-1:0] curr_str;
reg [m-1:0] curr_code;
reg [m-1:0] prev_code;
reg [n-1:0] prev_str;
reg [m-1:0] next_code = k+1;
reg [m-1:0] max_code = (1 << m) - 1;
reg [m-1:0] clear_code = k;
reg [m-1:0] end_code = k+1;
reg [m-1:0] bit_buffer;
reg [4:0] bit_count;
reg [m-1:0] out_code;

// Compress input data
always @(in) begin
  curr_str = {prev_str, in};
  if (dict[curr_str] != 0) begin
    prev_str = curr_str;
    prev_code = dict[curr_str];
  end else begin
    codes[next_code] = prev_code;
    dict[curr_str] = next_code;
    next_code = next_code + 1;
    if (next_code > max_code) begin
      out_code = clear_code;
      bit_buffer = out_code;
      bit_count = m;
      next_code = k+2;
      dict = 0;
    end else begin
      prev_str = in;
      prev_code = dict[prev_str];
    end
  end
  if (next_code > k+1) begin
    out_code = prev_code;
    bit_buffer = {bit_buffer, out_code};
    bit_count = bit_count + m;
  end
  if (bit_count >= m) begin
    out = bit_buffer >> (bit_count - m);
    bit_count = bit_count - m;
  end
end

// Decompress compressed data
always @(out) begin
  if (out == clear_code) begin
    dict = 0;
    next_code = k+2;
    prev_code = clear_code;
    prev_str = 0;
  end else if (out == end_code) begin
    // End of compressed data
  end else begin
    if (out < next_code) begin
      curr_code = out;
      while (curr_code > k+1) begin
        codes[curr_code] = {dict[curr_code], codes[curr_code]};
        curr_code = codes[curr_code][0];
      end
      curr_str = codes[curr_code];
      codes[next_code] = {prev_str, curr_str};
      dict[next_code] = codes[next_code];
      next_code = next_code + 1;
      prev_str = curr_str;
      prev_code = curr_code;
    end else begin
      curr_str = {prev_str, prev_str[0]};
      codes[next_code] = {prev_str, curr_str};
      dict[next_code] = codes[next_code];
      next_code = next_code + 1;
      prev_str = curr_str;
      prev_code = out;
    end
  end
end

endmodule

module ad9361_1t1r
(
    AD9361_RX_Frame_P,
    AD9361_RX_Frame_N,
    AD9361_DATA_CLK_P,
    AD9361_DATA_CLK_N,
    AD9361_RX_DATA_P,
    AD9361_RX_DATA_N,
    AD9361_TX_Frame_P,
    AD9361_TX_Frame_N,
    AD9361_FB_CLK_P,
    AD9361_FB_CLK_N,
    AD9361_TX_DATA_P,
    AD9361_TX_DATA_N,
    clk,
    rst,
    rx_I,
    rx_Q,
    tx_I,
    tx_Q,
    rx_ce,
    tx_ce
);

input  AD9361_RX_Frame_P;
input  AD9361_RX_Frame_N;
input  AD9361_DATA_CLK_P;
input  AD9361_DATA_CLK_N;
input  [5:0]AD9361_RX_DATA_P;
input  [5:0]AD9361_RX_DATA_N;

output AD9361_TX_Frame_P;
output AD9361_TX_Frame_N;
output AD9361_FB_CLK_P;
output AD9361_FB_CLK_N;
output [5:0]AD9361_TX_DATA_P;
output [5:0]AD9361_TX_DATA_N;

output clk;
input  rst;
output reg [11:0]rx_I;
output reg [11:0]rx_Q;
input  [11:0]tx_I;
input  [11:0]tx_Q;
output reg rx_ce;
output reg tx_ce;

wire clk_out;
wire [13:0]rx;

reg [13:0]rx_h;
reg [13:0]tx;
reg [11:0]tx_I_reg;
reg [11:0]tx_Q_reg;

ddr_rx rx_if (
  .data_in_from_pins_p({AD9361_RX_Frame_P,AD9361_RX_DATA_P}),
  .data_in_from_pins_n({AD9361_RX_Frame_N,AD9361_RX_DATA_N}),
  .clk_in_p(AD9361_DATA_CLK_P),
  .clk_in_n(AD9361_DATA_CLK_N),
  .io_reset(rst),
  .clk_out(clk_out),
  .data_in_to_device(rx)
);

ddr_tx tx_if (
  .data_out_to_pins_p({AD9361_TX_Frame_P,AD9361_TX_DATA_P}),
  .data_out_to_pins_n({AD9361_TX_Frame_N,AD9361_TX_DATA_N}),
  .clk_in(clk_out),
  .data_out_from_device(tx),
  .clk_reset(rst),
  .io_reset(rst),
  .clk_to_pins_p(AD9361_FB_CLK_P),
  .clk_to_pins_n(AD9361_FB_CLK_N)
);

always @(posedge clk_out or posedge rst) begin
    if (rst) begin
        rx_h <= 14'h0;
        rx_I <= 12'h0;
        rx_Q <= 12'h0;
        rx_ce <= 1'b0;
    end
    else if (rx[13]==1'b1) begin
        rx_ce <= 1'b1;
        rx_h <= rx;
    end
    else if(rx_ce==1'b1) begin
        rx_ce <= 1'b0;
        rx_I[11:6] = rx_h[5:0];
        rx_Q[11:6] = rx_h[12:7];
        rx_I[5:0]  = rx[5:0];
        rx_Q[5:0]  = rx[12:7];
    end
end

assign clk = clk_out;

always @(posedge clk_out or posedge rst) begin
    if (rst) begin
        tx_ce    <= 1'b0;
        tx       <= 14'h0;
        tx_I_reg <= 12'h0;
        tx_Q_reg <= 12'h0;
    end
    else if (tx_ce==0'b1) begin
        tx_ce    <= 1'b1;
        tx_I_reg <= tx_I;
        tx_Q_reg <= tx_Q;
        tx[5:0]  <= tx_I[11:6];
        tx[12:7] <= tx_Q[11:6];
        tx[6]    <= 1'b1;
        tx[13]   <= 1'b1;
    end
    else begin
        tx_ce    <= 1'b0;
        tx[5:0]  <= tx_I_reg[5:0];
        tx[12:7] <= tx_Q_reg[5:0];
        tx[6]    <= 1'b0;
        tx[13]   <= 1'b0;
    end
end

endmodule

module traffic_light_control (
  input clk,
  input reset,
  output reg red,
  output reg yellow,
  output reg green
);

  parameter GREEN_TIME = 30;
  parameter YELLOW_TIME = 5;
  parameter RED_TIME = 25;

  reg [3:0] state;
  reg [5:0] counter;

  always @(posedge clk) begin
    if (reset) begin
      state <= 3'b001;
      counter <= 0;
    end else begin
      case (state)
        3'b001: begin // Green state
          green <= 1;
          yellow <= 0;
          red <= 0;
          if (counter == GREEN_TIME * 2) begin
            state <= 3'b010;
            counter <= 0;
          end else begin
            counter <= counter + 1;
          end
        end
        3'b010: begin // Yellow state
          green <= 0;
          yellow <= 1;
          red <= 0;
          if (counter == YELLOW_TIME * 2) begin
            state <= 3'b100;
            counter <= 0;
          end else begin
            counter <= counter + 1;
          end
        end
        3'b100: begin // Red state
          green <= 0;
          yellow <= 0;
          red <= 1;
          if (counter == RED_TIME * 2) begin
            state <= 3'b001;
            counter <= 0;
          end else begin
            counter <= counter + 1;
          end
        end
      endcase
    end
  end

endmodule

