module priority_encoder (
    input [3:0] in,
    output reg [1:0] pos,
    output xor_out
);
    wire [3:0] in_inv;
    wire [3:0] in_xor;
    wire [2:0] pos_inv;

    xor_gate xg0 (.a(in[0]), .b(in[1]), .xor_out(in_xor[0]));
    xor_gate xg1 (.a(in[2]), .b(in[3]), .xor_out(in_xor[1]));
    xor_gate xg2 (.a(in_xor[0]), .b(in_xor[1]), .xor_out(xor_out));

    assign in_inv = ~in;
    assign pos_inv = {in_inv[0], in_inv[1], in_inv[2]};

    always @* begin
        if (in[0])
            pos = 0;
        else if (in[1])
            pos = 1;
        else if (in[2])
            pos = 2;
        else if (in[3])
            pos = 3;
        else
            pos = 0;
    end

    always @* begin
        if (pos_inv[0])
            pos = 1;
        else if (pos_inv[1])
            pos = 2;
        else if (pos_inv[2])
            pos = 3;
    end
endmodule

