module trapezoidal_integration(
    input [15:0] a,
    input [15:0] dt,
    input enable,
    input rst,
    input clk,
    output reg [31:0] v,
    output reg busy
);

    // State machine states
    localparam IDLE = 2'b00,
               CALCULATE_AREA = 2'b01,
               UPDATE_VALUE = 2'b10;

    // State machine registers
    reg [1:0] state, next_state;

    // Registers to store current and previous values
    reg [15:0] curr_val, prev_val;
    reg [31:0] area, prev_area;

    // Register to keep track of time
    reg [15:0] time;

    // Register to keep track of whether the integration is enabled
    reg enabled;

    // Reset signal
    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            curr_val <= 0;
            prev_val <= 0;
            area <= 0;
            prev_area <= 0;
            time <= 0;
            enabled <= 0;
            busy <= 0;
            v <= 0;
        end
        else begin
            state <= next_state;
        end
    end

    // State machine
    always @(*) begin
        case (state)
            IDLE: begin
                if (enable) begin
                    next_state <= CALCULATE_AREA;
                    enabled <= 1;
                    busy <= 1;
                end
                else begin
                    next_state <= IDLE;
                    enabled <= 0;
                    busy <= 0;
                end
            end

            CALCULATE_AREA: begin
                curr_val <= a;
                area <= (prev_val + curr_val)*dt/2 + prev_area;
                time <= time + dt;

                if (enabled) begin
                    next_state <= UPDATE_VALUE;
                    busy <= 1;
                end
                else begin
                    next_state <= IDLE;
                    busy <= 0;
                end
            end

            UPDATE_VALUE: begin
                prev_val <= curr_val;
                prev_area <= area;

                if (enabled) begin
                    next_state <= CALCULATE_AREA;
                    busy <= 1;
                end
                else begin
                    next_state <= IDLE;
                    busy <= 0;
                end
            end

            default: begin
                next_state <= IDLE;
            end
        endcase
    end

    // Output register
    always @(posedge clk) begin
        if (rst) begin
            v <= 0;
        end
        else begin
            v <= area;
        end
    end

endmodule

