module linescanner_image_capture_unit (
    input enable,
    input [7:0] data,
    input rst_cvc,
    input rst_cds,
    input sample,
    input end_adc,
    input lval,
    input pixel_clock,
    input main_clock_source,
    input n_reset,
    input load_pulse,
    output reg [7:0] pixel_data,
    output reg pixel_captured,
    output reg main_clock
);

reg [7:0] line_data;
reg [7:0] pixel_buffer;
reg [7:0] pixel_count;
reg [7:0] line_count;

reg sample_flag;
reg adc_flag;
reg sample_done;
reg adc_done;
reg line_done;

wire pixel_clock_div;
wire pixel_clock_rising;
wire pixel_clock_falling;
wire main_clock_div;

assign pixel_clock_div = pixel_clock_rising;
assign main_clock = main_clock_div;

always @(posedge pixel_clock_div) begin
    if (enable) begin
        if (sample_done) begin
            if (adc_done) begin
                if (line_done) begin
                    line_count <= 0;
                    line_data <= 0;
                    line_done <= 0;
                end else begin
                    line_count <= line_count + 1;
                    line_data <= {line_data[6:0], pixel_buffer};
                    if (line_count == 7) begin
                        pixel_data <= line_data;
                        pixel_captured <= 1;
                        line_done <= 1;
                    end
                end
            end else begin
                adc_flag <= 1;
                adc_done <= 0;
            end
        end else begin
            sample_flag <= 1;
            sample_done <= 0;
        end
    end
end

always @(posedge main_clock_div) begin
    if (n_reset) begin
        main_clock_div <= 0;
    end else begin
        main_clock_div <= ~main_clock_div;
    end
end

always @(posedge pixel_clock) begin
    if (sample_flag) begin
        pixel_buffer <= data;
        pixel_count <= 0;
        sample_flag <= 0;
        adc_flag <= 0;
    end else begin
        if (adc_flag) begin
            pixel_count <= pixel_count + 1;
            if (pixel_count == 7) begin
                adc_done <= 1;
            end
        end
    end
end

always @(posedge pixel_clock) begin
    pixel_clock_rising <= ~pixel_clock_falling;
    pixel_clock_falling <= ~pixel_clock_rising;
end

always @(negedge rst_cds) begin
    sample_done <= 1;
end

always @(negedge sample) begin
    sample_done <= 1;
end

always @(negedge end_adc) begin
    adc_done <= 1;
end

always @(posedge load_pulse) begin
    if (lval) begin
        pixel_buffer <= data;
        pixel_count <= 0;
        sample_done <= 1;
        adc_done <= 1;
        line_done <= 1;
    end
end

endmodule

module controlTransmitter (Complete, NullString, NullDataChar, Generated, LoadString, CompareString, LoadNextChar, GenerateData, SendData, Reset, clk);

	input Complete, NullString, NullDataChar, clk, Reset, Generated;
	output reg LoadString, CompareString, LoadNextChar, GenerateData, SendData;

	reg [2:0] current_state;
	reg [2:0] next_state;

	parameter Standby=3'b000, LoadingString=3'b001, ComparingString=3'b010, LoadingChar=3'b011;
	parameter GeneratingData=3'b100, SendingData=3'b101;

always @(Complete, NullString, NullDataChar, current_state, Reset, Generated)begin

	if (Reset)begin
		next_state <= Standby;
		LoadString<=0;
		CompareString<=0;
		LoadNextChar<=0;
		GenerateData<=0;
		SendData<=0;
	end

	else begin
		case (current_state)
			Standby: begin
				if (Complete==1'b0) begin
					LoadString<=0;
					CompareString<=0;
					LoadNextChar<=0;
					GenerateData<=0;
					SendData<=0;
					next_state <= Standby;
				end
				else begin
					next_state <= LoadingString;
					LoadString<=0;
					CompareString<=0;
					LoadNextChar<=0;
					GenerateData<=0;
					SendData<=0;
					end
			end
			LoadingString: begin
				LoadString<=1;
				CompareString<=0;
				LoadNextChar<=0;
				GenerateData<=0;
				SendData<=0;
				next_state<=ComparingString;
			end
			ComparingString: begin
				LoadString<=0;
				CompareString<=1;
				LoadNextChar<=0;
				GenerateData<=0;
				SendData<=0;
				if (NullString==1'b1)next_state<=Standby;
				else next_state<=LoadingChar;
			end	
			LoadingChar: begin
				LoadString<=0;
				CompareString<=0;
				LoadNextChar<=1;
				GenerateData<=0;
				SendData<=0;
				next_state<=GeneratingData;

			end
			GeneratingData: begin
				LoadString<=0;
				CompareString<=0;
				LoadNextChar<=0;
				GenerateData<=1;
				SendData<=0;
				if (Generated)next_state <= SendingData;
				else next_state <= GeneratingData;

			end
			SendingData: begin
				LoadString<=0;
				CompareString<=0;
				LoadNextChar<=0;
				GenerateData<=0;
				SendData<=1;

				if (NullDataChar == 1)next_state <= ComparingString;
				else next_state <= SendingData;
			end			
			default: begin
				LoadString<=0;
					CompareString<=0;
					LoadNextChar<=0;
					GenerateData<=0;
					SendData<=0;
				next_state <= Standby;
			end
		endcase
	end
end

	always @(negedge clk) begin
		current_state <= next_state;
	end
endmodule

