module edge_detection (
    input clk,
    input reset,   // Synchronous active-high reset
    input a,       // 1-bit signal for edge detection
    output rise,   // Output for rising edge detection
    output down    // Output for falling edge detection
);

    // State machine states
    parameter IDLE = 2'b00;
    parameter RISE_DETECT = 2'b01;
    parameter DOWN_DETECT = 2'b10;

    // State machine signals
    reg [1:0] state, next_state;

    // Edge detection signals
    reg a_prev;

    // Output signals
    assign rise = (state == RISE_DETECT);
    assign down = (state == DOWN_DETECT);

    // State machine logic
    always @(posedge clk, posedge reset) begin
        if (reset) begin
            state <= IDLE;
            a_prev <= 1'b0;
        end else begin
            state <= next_state;
            a_prev <= a;
        end
    end

    always @* begin
        case (state)
            IDLE: begin
                if (a == 1'b1 && a_prev == 1'b0) begin
                    next_state = RISE_DETECT;
                end else if (a == 1'b0 && a_prev == 1'b1) begin
                    next_state = DOWN_DETECT;
                end else begin
                    next_state = IDLE;
                end
            end
            RISE_DETECT: begin
                next_state = IDLE;
            end
            DOWN_DETECT: begin
                next_state = IDLE;
            end
        endcase
    end

endmodule

module bcd_counter (
    input clk,
    input reset,   // Synchronous active-high reset
    input [3:1] ena,    // Enable signals for each digit
    output reg [15:0] q  // BCD counter output
);

    // Counter signals
    reg [3:0] cnt0, cnt1, cnt2, cnt3;

    // Output signals
    assign q = {cnt3, cnt2, cnt1, cnt0};

    // Counter logic
    always @(posedge clk, posedge reset) begin
        if (reset) begin
            cnt0 <= 4'd0;
            cnt1 <= 4'd0;
            cnt2 <= 4'd0;
            cnt3 <= 4'd0;
        end else begin
            if (ena[1]) begin
                cnt0 <= cnt0 + 1;
                if (cnt0 == 4'd9) begin
                    cnt0 <= 4'd0;
                    if (ena[2]) begin
                        cnt1 <= cnt1 + 1;
                        if (cnt1 == 4'd9) begin
                            cnt1 <= 4'd0;
                            if (ena[3]) begin
                                cnt2 <= cnt2 + 1;
                                if (cnt2 == 4'd9) begin
                                    cnt2 <= 4'd0;
                                    cnt3 <= cnt3 + 1;
                                end
                            end
                        end
                    end
                end
            end
        end
    end

endmodule

module functional_module (
    input [15:0] bcd_counter_out,  // BCD counter output
    input rise,   // Rising edge detection signal
    input down,   // Falling edge detection signal
    output reg [7:0] out   // Functional module output
);

    always @* begin
        if (rise) begin
            out <= bcd_counter_out[7:0];
        end else if (down) begin
            out <= ~bcd_counter_out[7:0];
        end else begin
            out <= 8'd0;
        end
    end

endmodule

