module top_module (
    input clk, 
    input reset, 
    input [2:0] A, B, 
    input select, 
    output reg [2:0] Q
);

    // Instantiate the 3-bit adder module
    adder_3bit adder_inst (
        .A(A),
        .B(B),
        .Cin(1'b0),
        .Sum(Q)
    );

    // Instantiate the 3-bit register module with active high synchronous reset
    reg_3bit_reset reg_inst (
        .clk(clk),
        .reset(reset),
        .data_in(3'b00000100),
        .data_out(Q)
    );

    // Define the control logic to choose between adder and register output
    always @ (posedge clk) begin
        if (reset) begin
            Q <= 3'b000;
        end else begin
            if (select) begin
                Q <= Q;
            end else begin
                Q <= Q + A + B;
            end
        end
    end

endmodule

// Define the 3-bit adder module
module adder_3bit (
    input [2:0] A, B, 
    input Cin, 
    output reg [2:0] Sum
);

    always @ (*) begin
        Sum = A + B + Cin;
    end

endmodule

