module reg_3bit_reset (
    input clk, 
    input reset, 
    input [2:0] data_in, 
    output reg [2:0] data_out
);

    always @ (posedge clk) begin
        if (reset) begin
            data_out <= 3'b000;
        end else begin
            data_out <= data_in;
        end
    end

endmodule

module counter(clk, reset, count);
  input clk, reset;
  output reg [1:0] count;

  always @(posedge clk) begin
    if (reset) begin
      count <= 2'b0;
    end else begin
      count <= count + 1;
    end
  end

  // Wrap around from 3 to 0
  assign count = (count == 2'b11) ? 2'b0 : count;
endmodule

module CLKDIVF(
	input CLKI, RST, ALIGNWD,
	output CDIVX
);
	parameter GSR = "DISABLED";
	parameter DIV = "2.0";

	reg [1:0] count;
	reg [1:0] div_factor;
	reg out_reg;

	always @(posedge CLKI or posedge RST) begin
		if(RST) begin
			count <= 2'b00;
			out_reg <= 1'b0;
		end
		else begin
			if(GSR == "ENABLED" && ALIGNWD == 1'b0) begin
				count <= 2'b00;
				out_reg <= 1'b0;
			end
			else begin
				count <= count + 1;
				if(count == div_factor) begin
					count <= 2'b00;
					out_reg <= ~out_reg;
				end
			end
		end
	end

	assign CDIVX = out_reg;

	// Set div_factor based on DIV parameter
	initial begin
		case(DIV)
			"2.0": div_factor = 2'b01;
			"4.0": div_factor = 2'b10;
			"8.0": div_factor = 2'b11;
			default: div_factor = 2'b01;
		endcase
	end
endmodule

module binary_to_gray (
    input clk,
    input reset,          // Synchronous active-high reset
    output reg [3:0] gray
);

reg [3:0] counter;
wire [3:0] shifted_counter;
wire select;

// Binary counter
always @(posedge clk) begin
    if (reset) begin
        counter <= 4'b0000;
    end else begin
        counter <= counter + 1;
    end
end

// Right shift counter and XOR with counter
assign shifted_counter = {counter[2:0], 1'b0};
assign select = counter[3];

// 2-to-1 multiplexer
always @(select or counter) begin
    if (select) begin
        gray <= shifted_counter ^ counter;
    end else begin
        gray <= counter;
    end
end

endmodule

