module adder4bit (A, B, Cin, Sel, Sum, Cout);

  input [3:0] A, B;
  input Cin, Sel;
  output [3:0] Sum;
  output Cout;

  wire [3:0] C;

  // Unsigned addition
  assign {Cout, Sum} = Cin + A + B;

  // Two's complement addition
  assign {Cout, Sum} = Cin + A + (~B) + 1'b1;

  // Select the appropriate addition based on Sel
  assign {Cout, Sum} = Sel ? {Cout, Sum} : {C[3], C[2], C[1], C[0]};

endmodule

module consecutive_ones (
  input clk,
  input reset,
  input [15:0] data,
  output reg [3:0] count
);

reg [3:0] state;
reg [3:0] count_reg;

always @(posedge clk) begin
  if (reset) begin
    state <= 4'b0000;
    count_reg <= 4'b0000;
  end
  else begin
    case (state)
      4'b0000: begin
        if (data[15]) begin
          state <= 4'b0001;
          count_reg <= 4'b0001;
        end
        else begin
          state <= 4'b0000;
          count_reg <= 4'b0000;
        end
      end
      4'b0001: begin
        if (data[15]) begin
          state <= 4'b0010;
          count_reg <= 4'b0010;
        end
        else begin
          state <= 4'b0000;
          count_reg <= 4'b0001;
        end
      end
      4'b0010: begin
        if (data[15]) begin
          state <= 4'b0011;
          count_reg <= 4'b0011;
        end
        else begin
          state <= 4'b0000;
          count_reg <= 4'b0010;
        end
      end
      4'b0011: begin
        if (data[15]) begin
          state <= 4'b0100;
          count_reg <= 4'b0100;
        end
        else begin
          state <= 4'b0000;
          count_reg <= 4'b0011;
        end
      end
      4'b0100: begin
        if (data[15]) begin
          state <= 4'b0101;
          count_reg <= 4'b0101;
        end
        else begin
          state <= 4'b0000;
          count_reg <= 4'b0100;
        end
      end
      4'b0101: begin
        if (data[15]) begin
          state <= 4'b0110;
          count_reg <= 4'b0110;
        end
        else begin
          state <= 4'b0000;
          count_reg <= 4'b0101;
        end
      end
      4'b0110: begin
        if (data[15]) begin
          state <= 4'b0111;
          count_reg <= 4'b0111;
        end
        else begin
          state <= 4'b0000;
          count_reg <= 4'b0110;
        end
      end
      4'b0111: begin
        if (data[15]) begin
          state <= 4'b1000;
          count_reg <= 4'b1000;
        end
        else begin
          state <= 4'b0000;
          count_reg <= 4'b0111;
        end
      end
      4'b1000: begin
        if (data[15]) begin
          state <= 4'b1001;
          count_reg <= 4'b1001;
        end
        else begin
          state <= 4'b0000;
          count_reg <= 4'b1000;
        end
      end
      4'b1001: begin
        if (data[15]) begin
          state <= 4'b1010;
          count_reg <= 4'b1010;
        end
        else begin
          state <= 4'b0000;
          count_reg <= 4'b1001;
        end
      end
      4'b1010: begin
        if (data[15]) begin
          state <= 4'b1011;
          count_reg <= 4'b1011;
        end
        else begin
          state <= 4'b0000;
          count_reg <= 4'b1010;
        end
      end
      4'b1011: begin
        if (data[15]) begin
          state <= 4'b1100;
          count_reg <= 4'b1100;
        end
        else begin
          state <= 4'b0000;
          count_reg <= 4'b1011;
        end
      end
      4'b1100: begin
        if (data[15]) begin
          state <= 4'b1101;
          count_reg <= 4'b1101;
        end
        else begin
          state <= 4'b0000;
          count_reg <= 4'b1100;
        end
      end
      4'b1101: begin
        if (data[15]) begin
          state <= 4'b1110;
          count_reg <= 4'b1110;
        end
        else begin
          state <= 4'b0000;
          count_reg <= 4'b1101;
        end
      end
      4'b1110: begin
        if (data[15]) begin
          state <= 4'b1111;
          count_reg <= 4'b1111;
        end
        else begin
          state <= 4'b0000;
          count_reg <= 4'b1110;
        end
      end
      4'b1111: begin
        state <= 4'b0000;
        count_reg <= 4'b1111;
      end
      default: begin
        state <= 4'b0000;
        count_reg <= 4'b0000;
      end
    endcase
  end
end

assign count = count_reg;

endmodule

