module prbs_generator (
  input                      clk_i,          // input clock
  input                      clk_en_i,       // clock enable 
  input                      rst_i,          // synchronous reset
  input [63:0]               prbs_seed_i,    // initial LFSR seed
  input                      phy_if_empty,   // IN_FIFO empty flag
  input                      prbs_rdlvl_start, // PRBS read leveling start
  output reg [63:0]          prbs_o          // generated pseudo random data
);

  // Number of internal clock cycles before the PRBS sequence will repeat
  localparam PRBS_SEQ_LEN_CYCLES = 128;
  localparam PRBS_SEQ_LEN_CYCLES_BITS = $clog2(PRBS_SEQ_LEN_CYCLES);

  reg                                 phy_if_empty_r;
  reg                                 reseed_prbs_r;
  reg [PRBS_SEQ_LEN_CYCLES_BITS-1:0]  sample_cnt_r;
  reg [63:1]                          lfsr_q;

  //***************************************************************************
  always @(posedge clk_i) begin
    phy_if_empty_r <= phy_if_empty;
  end

  //***************************************************************************
  // Generate PRBS reset signal to ensure that PRBS sequence repeats after
  // every 2**PRBS_WIDTH samples. Basically what happens is that we let the
  // LFSR run for an extra cycle after "truly PRBS" 2**PRBS_WIDTH - 1
  // samples have past. Once that extra cycle is finished, we reseed the LFSR
  always @(posedge clk_i)
  begin
    if (rst_i || ~clk_en_i) begin
      sample_cnt_r    <= 'b0;
      reseed_prbs_r   <= 1'b0;
    end else if (clk_en_i && (~phy_if_empty_r || ~prbs_rdlvl_start)) begin
      // The rollver count should always be [(power of 2) - 1]
      sample_cnt_r    <= sample_cnt_r + 1;
      // Assert PRBS reset signal so that it is simultaneously with the
      // last sample of the sequence
      if (sample_cnt_r == PRBS_SEQ_LEN_CYCLES - 2)
        reseed_prbs_r <= 1'b1;
      else
        reseed_prbs_r <= 1'b0;
    end
  end

  always @ (posedge clk_i)
  begin
    if ((reseed_prbs_r && clk_en_i) || rst_i || ~clk_en_i) begin
      lfsr_q[4:1]          <= prbs_seed_i[3:0] | 4'h5;
      lfsr_q[63:5]         <= prbs_seed_i[63:4];
    end
    else if (clk_en_i && (~phy_if_empty_r || ~prbs_rdlvl_start)) begin
      lfsr_q[63:31] <= lfsr_q[62:30];
      lfsr_q[30]    <= lfsr_q[16] ^ lfsr_q[13] ^ lfsr_q[5]  ^ lfsr_q[1];
      lfsr_q[29:9]  <= lfsr_q[28:8];
      lfsr_q[8]     <= lfsr_q[32] ^ lfsr_q[7];
      lfsr_q[7]     <= lfsr_q[32] ^ lfsr_q[6];
      lfsr_q[6:4]   <= lfsr_q[5:3];
      lfsr_q[3]     <= lfsr_q[32] ^ lfsr_q[2];
      lfsr_q[2]     <= lfsr_q[1] ;
      lfsr_q[1]     <= lfsr_q[32];
    end
  end

  always @ (lfsr_q[63:1]) begin
    prbs_o = lfsr_q[63:1];
  end

endmodule

module vending_machine(
  input button_cola,
  input button_water,
  input button_juice,
  output reg [2:0] dispense,
  output reg [3:0] display
);

  reg [3:0] drinks_remaining = 10;
  reg [2:0] priority = 3'b001;

  always @(*) begin
    if (button_cola && drinks_remaining[2:2]) begin
      dispense = 3'b001;
      drinks_remaining[2:2] = drinks_remaining[2:2] - 1;
      priority = 3'b001;
    end else if (button_water && drinks_remaining[1:1]) begin
      dispense = 3'b010;
      drinks_remaining[1:1] = drinks_remaining[1:1] - 1;
      priority = 3'b010;
    end else if (button_juice && drinks_remaining[0:0]) begin
      dispense = 3'b100;
      drinks_remaining[0:0] = drinks_remaining[0:0] - 1;
      priority = 3'b100;
    end else begin
      dispense = priority;
    end
    display = {drinks_remaining[2:2], drinks_remaining[1:1], drinks_remaining[0:0], 3'b0};
  end

endmodule

module shift_add (
    input CLK, RESET,
    input [3:0] A,
    input LOAD,
    output [7:0] Q,
    output Q7,
    output [4:0] result
);

reg [3:0] adder_out;
reg [7:0] shift_reg;

adder adder_inst (
    .A(A),
    .B(4'b0011),
    .Cout(),
    .S(adder_out)
);

always @ (posedge CLK) begin
    if (RESET) begin
        shift_reg <= 8'b0;
    end else begin
        if (LOAD) begin
            shift_reg <= {adder_out, 1'b0};
        end else begin
