module decade_counter_register_shifter(clk, slowena, reset, load, ena, d, sum);

  input clk, slowena, reset, load;
  input [1:0] ena;
  input [3:0] d;
  output reg [7:0] sum;

  reg [3:0] counter;
  reg [99:0] register;

  // Decade counter implementation
  always @(posedge clk or negedge reset) begin
    if (reset == 0) begin
      counter <= 0;
    end else if (slowena == 1) begin
      counter <= counter;
    end else begin
      counter <= counter + 1;
    end
  end

  // Register shifter implementation
  always @(posedge clk) begin
    if (load == 1) begin
      register <= d;
    end else if (ena == 2'b01) begin
      register <= {register[98:0], 1'b0};
    end else if (ena == 2'b10) begin
      register <= {1'b0, register[99:1]};
    end else begin
      register <= register;
    end
  end

  // Functional module implementation
  always @(posedge clk) begin
    sum <= counter + register[7:0];
  end

endmodule

module booth_multiplier (
    input i_clk,
    input i_core_stall,
    input [31:0] i_a_in,
    input [31:0] i_b_in,
    input [1:0] i_function,
    input i_execute,
    output reg [31:0] o_out,
    output reg [1:0] o_flags,
    output reg o_done
);

    // Booth's algorithm requires a 34-bit adder
    wire [33:0] multiplier;
    wire [33:0] multiplier_bar;
    wire [33:0] sum;
    wire [33:0] sum34_b;

    // Accumulation requires a 33-bit adder
    wire [32:0] sum_acc1;

    // Counter for multiplication state
    reg [5:0] count = 6'd0;
    reg [5:0] count_nxt;

    // Product register
    reg [67:0] product = 68'd0;
    reg [67:0] product_nxt;

    // Flags register
    reg [1:0] flags_nxt;

    // Enable and accumulate signals from i_function
    assign enable = i_function[0];
    assign accumulate = i_function[1];

    // Booth's algorithm
    assign multiplier = {2'd0, i_a_in};
    assign multiplier_bar = ~{2'd0, i_a_in} + 34'd1;
    assign sum34_b = product[1:0] == 2'b01 ? multiplier :
                    product[1:0] == 2'b10 ? multiplier_bar :
                                            34'd0;
    assign sum = product[67:34] + sum34_b;

    // Accumulation
    assign sum_acc1 = {1'd0, product[32:1]} + {1'd0, i_a_in};

    // Update flags
    always @(*) begin
        flags_nxt = {product[32], product[32:1] == 32'd0};
    end

    // Update product, count, and o_done
    always @(posedge i_clk) begin
        if (!i_core_stall) begin
            if (count == 6'd0) begin
                if (i_execute) begin
                    count_nxt = 6'd1;
                    product_nxt = {33'd0, 1'd0, i_b_in, 1'd0};
                end else begin
                    count_nxt = 6'd0;
                    product_nxt = product;
                end
            end else if (count <= 6'd33) begin
                count_nxt = count + 1'd1;
                product_nxt = {sum[33], sum, product[33:1]};
            end else if (count == 6'd34 && accumulate) begin
                count_nxt = 6'd0;
                product_nxt = {product[64:33], sum_acc1[31:0], 1'd0};
            end else begin
                count_nxt = count + 1'd1;
                product_nxt = product;
            end
            count <= count_nxt;
            product <= product_nxt;
            o_done <= count == 6'd31;
        end
    end

    // Update outputs
    assign o_out = product[32:1];
    assign o_flags = flags_nxt;

endmodule

