            shiftedData <= rdData1 << shiftAmt;
            result <= shiftedData;
        end

        // Shift right logical
        if (opCode == 4'b0101) begin
            shiftedData <= rdData1 >> shiftAmt;
            result <= shiftedData;
        end

        // Shift right arithmetic
        if (opCode == 4'b0110) begin
            shiftedData <= {shiftMask, rdData1[31:shiftAmt]};
            result <= shiftedData;
        end

        // Compare less than
        if (opCode == 4'b0111) begin
            result <= (rdData1 < rdData2) ? 1 : 0;
        end

        // Compare greater than
