module stepgen(
    input clk, reset,
    input [4:0] vel,
    input dir,
    output reg step,
    output reg dir_out,
    output reg [19:0] pos
);

// Constants
parameter IDLE = 2'b00;
parameter ACCELERATING = 2'b01;
parameter CONSTANT_VELOCITY = 2'b10;
parameter DECELERATING = 2'b11;
parameter MAX_VELOCITY = 16;
parameter MAX_POSITION = 1048575;

// State variables
reg [1:0] state;
reg [4:0] velocity;
reg [19:0] position;
reg [3:0] timer;
reg pbit;

// Output signals
assign dir_out = dir;
assign pos = position;

always @(posedge clk) begin
    if (reset) begin
        state <= IDLE;
        velocity <= 0;
        position <= 0;
        timer <= 0;
        pbit <= 0;
        step <= 0;
    end else begin
        case (state)
            IDLE: begin
                step <= 0;
                if (vel != 0) begin
                    state <= ACCELERATING;
                    velocity <= 1;
                    pbit <= 0;
                    timer <= MAX_VELOCITY - 1;
                end
            end
            ACCELERATING: begin
                if (timer == 0) begin
                    if (velocity < MAX_VELOCITY) begin
                        velocity <= velocity + 1;
                        timer <= MAX_VELOCITY - velocity - 1;
                    end else begin
                        state <= CONSTANT_VELOCITY;
                        timer <= MAX_VELOCITY - 1;
                    end
                end else begin
                    timer <= timer - 1;
                end
                if (pbit == 0 && timer == 0) begin
                    step <= 1;
                    position <= position + (dir ? 1 : -1);
                    pbit <= 1;
                end else if (pbit == 1 && timer == 0) begin
                    step <= 0;
                    pbit <= 0;
                end
            end
            CONSTANT_VELOCITY: begin
                if (vel == 0) begin
                    state <= DECELERATING;
                    timer <= velocity - 1;
                end
                if (pbit == 0 && timer == 0) begin
                    step <= 1;
                    position <= position + (dir ? 1 : -1);
                    pbit <= 1;
                end else if (pbit == 1 && timer == 0) begin
                    step <= 0;
                    pbit <= 0;
                end
            end
            DECELERATING: begin
                if (timer == 0) begin
                    if (velocity > 1) begin
                        velocity <= velocity - 1;
                        timer <= velocity - 1;
                    end else begin
                        state <= STOPPED;
                    end
                end else begin
                    timer <= timer - 1;
                end
                if (pbit == 0 && timer == 0) begin
                    step <= 1;
                    position <= position + (dir ? 1 : -1);
                    pbit <= 1;
                end else if (pbit == 1 && timer == 0) begin
                    step <= 0;
                    pbit <= 0;
                end
            end
            STOPPED: begin
                step <= 0;
                velocity <= 0;
                position <= 0;
                timer <= 0;
                pbit <= 0;
                if (vel != 0) begin
                    state <= ACCELERATING;
                    velocity <= 1;
                    pbit <= 0;
                    timer <= MAX_VELOCITY - 1;
                end
            end
        endcase
    end
end

endmodule

