module mux_2to1(
    input  A,
    input  B,
    input  S,
    output Y
);
    wire not_A;
    wire not_B;
    wire and_out;

    inverter inv_A(not_A, A);
    inverter inv_B(not_B, B);
    and_gate and1(not_A, S, and_out);
    and_gate and2(not_B, ~S, and_out);
    inverter inv_out(Y, and_out);
endmodule

module comparator_mux (
    input [1:0] comp_in1, // 2-bit input for the comparator
    input [1:0] comp_in2, // 2-bit input for the comparator
    input [7:0] mux_in, // 4 2-bit inputs for the multiplexer
    input [1:0] select, // 2-bit select input for the multiplexer
    input control, // Control input to choose between the comparator and the multiplexer
    output [1:0] out // 2-bit output from the selected module
);

    // Comparator module
    wire [1:0] comp_out;
    comparator comp(
        .in1(comp_in1),
        .in2(comp_in2),
        .out(comp_out)
    );

    // Multiplexer module
    wire [1:0] mux_out;
    mux4to1 mux(
        .in0(mux_in[1:0]),
        .in1(mux_in[3:2]),
        .in2(mux_in[5:4]),
        .in3(mux_in[7:6]),
        .sel(select),
        .out(mux_out)
    );

    // Output selection based on control input
    assign out = control ? mux_out : comp_out;

endmodule

// Comparator module
module comparator (
    input [1:0] in1, // 2-bit input 1
    input [1:0] in2, // 2-bit input 2
    output [1:0] out // 2-bit output
);

    assign out[0] = (in1[0] > in2[0]) ? 1'b1 : 1'b0;
    assign out[1] = (in1[1] > in2[1]) ? 1'b1 : 1'b0;
    assign out = (in1 == in2) ? 2'b11 : out;

endmodule

// 4-to-1 Multiplexer module
module mux4to1 (
    input [1:0] in0, // 2-bit input 0
    input [1:0] in1, // 2-bit input 1
    input [1:0] in2, // 2-bit input 2
    input [1:0] in3, // 2-bit input 3
    input [1:0] sel, // 2-bit select input
    output [1:0] out // 2-bit output
);

    assign out = (sel == 2'b00) ? in0 :
                 (sel == 2'b01) ? in1 :
                 (sel == 2'b10) ? in2 :
                                  in3;

endmodule

module comparator_pipeline(
    input [3:0] a,
    input [3:0] b,
    input clk,
    output reg equal
);

reg [1:0] stage1_result [3:0];
reg stage2_result;

always @(posedge clk) begin
    stage1_result[0] <= {a[0] == b[0], a[1] == b[1]};
    stage1_result[1] <= {a[2] == b[2], a[3] == b[3]};
    stage1_result[2] <= {stage1_result[0][1], stage1_result[1][1]};
    stage1_result[3] <= {stage1_result[0][0], stage1_result[1][0]};

    stage2_result <= stage1_result[2] == 2'b11 && stage1_result[3] == 2'b11;
end

assign equal = stage2_result;

endmodule

