module fifo_32_to_8 #(
    parameter DEPTH = 1024*4
)(
    input wire CLK,
    input wire RST,
    input wire WRITE,
    input wire READ,
    input wire [31:0] DATA_IN,
    output wire FULL,
    output wire EMPTY,
    output wire [7:0] DATA_OUT
);

reg [1:0] byte_cnt;
wire FIFO_EMPTY, READ_FIFO;
wire [31:0] FIFO_DATA_OUT;

assign EMPTY = byte_cnt==0 & FIFO_EMPTY;
assign READ_FIFO = (byte_cnt==0 & !FIFO_EMPTY && READ);

gerneric_fifo #(.DATA_SIZE(32), .DEPTH(DEPTH))  fifo_i
(
    .clk(CLK),
    .reset(RST),
    .write(WRITE),
    .read(READ_FIFO),
    .data_in(DATA_IN),
    .full(FULL),
    .empty(FIFO_EMPTY),
    .data_out(FIFO_DATA_OUT), .size()
);

always@(posedge CLK)
    if(RST)
        byte_cnt <= 0;
    else if (READ)
        byte_cnt <= byte_cnt + 1;

reg [31:0] DATA_BUF;
always@(posedge CLK)
    if(READ_FIFO)
        DATA_BUF <= FIFO_DATA_OUT;

wire [7:0] FIFO_DATA_OUT_BYTE [3:0];
assign FIFO_DATA_OUT_BYTE[0] = FIFO_DATA_OUT[7:0];
assign FIFO_DATA_OUT_BYTE[1] = DATA_BUF[15:8];
assign FIFO_DATA_OUT_BYTE[2] = DATA_BUF[23:16];
assign FIFO_DATA_OUT_BYTE[3] = DATA_BUF[31:24];
assign DATA_OUT = FIFO_DATA_OUT_BYTE[byte_cnt];

endmodule

module playback_driver (
    input clk,
    input rst,
    input [31:0] data_in,
    output reg [31:0] data_out
);

reg [31:0] playback_data;
reg [31:0] playback_ptr;

`ifdef DUMP_ON
    initial begin
        if($test$plusargs("dump"))
            $fsdbDumpvars(0, playback_driver);
    end
`endif

always @(posedge clk) begin
    if (rst) begin
        playback_ptr <= 0;
        data_out <= 0;
    end else begin
        playback_data <= data_in[playback_ptr];
        data_out <= playback_data;
        playback_ptr <= playback_ptr + 1;
    end
end

endmodule

module comparator (
  input [3:0] A,
  input [3:0] B,
  input [1:0] op,
  output reg eq
);

  always @ (A, B, op) begin
    case(op)
      2'b00: eq = (A == B);
      2'b01: eq = (A > B);
      2'b10: eq = (A < B);
      2'b11: eq = (A != B);
      default: eq = 0;
    endcase
  end

endmodule

module barrel_shifter (
  input [n-1:0] in,
  input [log2_n-1:0] ctrl,
  output [n-1:0] out
);

parameter n = 8; // number of bits in the binary number
parameter log2_n = 3; // number of control signals required

assign out = (ctrl >= 0) ? (in << ctrl) : (in >> -ctrl);

endmodule

module digital_potentiometer (
  input [n-1:0] in,
  input clk,
  input rst,
  output reg out,
  output reg done
);

parameter n = 8; // number of digital inputs
parameter rmax = 100; // maximum resistance
parameter rstep = 1; // resistance step size
parameter steps = rmax / rstep; // total number of steps

reg [n-1:0] count; // counter to keep track of the current step
reg [7:0] resistance; // current resistance value

always @(posedge clk) begin
  if (rst) begin
    count <= 0;
    resistance <= 0;
    out <= 0;
    done <= 0;
  end else begin
    // update the count based on the input signals
    count <= in;

    // compute the resistance based on the current step
    resistance <= count * rstep;

    // update the analog output
    out <= resistance;

    // set the done signal high when the potentiometer has finished adjusting its resistance
    if (count == steps) begin
      done <= 1;
    end else begin
      done <= 0;
    end
  end
end

endmodule

module comparator (
  input [n-1:0] in1,
  input [n-1:0] in2,
  output eq,
  output gt,
  output lt
);

parameter n = 8; // number of bits in input signals

wire [n-1:0] xor_out;
wire [n-1:0] and_out1;
wire [n-1:0] and_out2;

assign xor_out = in1 ^ in2;
assign and_out1 = in1 & xor_out;
assign and_out2 = in2 & xor_out;

assign eq = ~|xor_out;
assign gt = |and_out1;
assign lt = |and_out2;

endmodule

module top_module( 
