module Clk_Wizard 
 (
  // Clock out ports
  output        VGA_clock,
  output        Main_clock,
  // Status and control signals
  input         resetn,
  output        locked,
 // Clock in ports
  input         Clock_Board
 );

  wire clk_25MHz;
  wire clk_100MHz;
  wire locked_int;

  Clk_Wizard_clk_wiz inst
  (
  // Clock out ports  
  .VGA_clock(clk_25MHz),
  .Main_clock(clk_100MHz),
  // Status and control signals               
  .resetn(resetn), 
  .locked(locked_int),
 // Clock in ports
  .Clock_Board(Clock_Board)
  );

  // Divide Clock_Board to generate 25MHz clock
  reg [23:0] counter_25MHz = 0;
  always @(posedge clk_25MHz or negedge resetn) begin
    if (~resetn) begin
      counter_25MHz <= 0;
    end else begin
      counter_25MHz <= counter_25MHz + 1;
    end
  end

  assign VGA_clock = clk_25MHz;

  // Divide 25MHz clock to generate 100MHz clock
  reg [7:0] counter_100MHz = 0;
  always @(posedge clk_25MHz or negedge resetn) begin
    if (~resetn) begin
      counter_100MHz <= 0;
    end else begin
      if (counter_25MHz == 0) begin
        counter_100MHz <= counter_100MHz + 1;
      end
    end
  end

  assign Main_clock = (counter_100MHz == 0) ? 1'b1 : 1'b0;

  // Generate locked signal
  reg locked_reg = 0;
  always @(posedge clk_100MHz or negedge resetn) begin
    if (~resetn) begin
      locked_reg <= 0;
    end else begin
      locked_reg <= locked_int;
    end
  end

  assign locked = locked_reg;

endmodule

module fifo(clk, rst, en, mode, din, we, dout, re, status, full, empty);

parameter DEPTH = 16;
parameter WIDTH = 32;

input clk, rst, en, we, re;
input [1:0] mode;
input [WIDTH-1:0] din;
output [WIDTH-1:0] dout;
output [1:0] status;
output full, empty;

reg [WIDTH-1:0] mem [0:DEPTH-1];
reg [4:0] wp, rp;
reg [1:0] status_reg;
reg [WIDTH-1:0] dout_reg;
reg empty_reg;

assign full = (wp == rp) && !empty_reg;
assign empty = (wp == rp) && empty_reg;

// write pointer logic
always @(posedge clk) begin
    if (rst) begin
        wp <= 0;
    end
    else if (en && we && !full) begin
        wp <= wp + 1;
    end
end

// read pointer logic
always @(posedge clk) begin
    if (rst) begin
        rp <= 0;
    end
    else if (en && re && !empty) begin
        rp <= rp + 1;
    end
end

// status logic
always @(posedge clk) begin
    if (rst) begin
        status_reg <= 2'b00;
    end
    else begin
        if (full) begin
            status_reg <= 2'b10;
        end
        else if (empty) begin
            status_reg <= 2'b00;
        end
        else begin
            status_reg <= 2'b01;
        end
    end
end

// empty logic
always @(posedge clk) begin
    if (rst) begin
        empty_reg <= 1'b1;
    end
    else if (en && we && !full) begin
        empty_reg <= 1'b0;
    end
    else if (en && re && empty) begin
        empty_reg <= 1'b1;
    end
end

// data output logic
always @(posedge clk) begin
    if (rst) begin
        dout_reg <= 0;
    end
    else if (en && re && !empty) begin
        case (mode)
            2'b00: dout_reg <= {16'h0, mem[rp][15:0]};
            2'b01: dout_reg <= {mem[rp][17:0], 2'h0};
            2'b10: dout_reg <= mem[rp];
            default: dout_reg <= 0;
        endcase
    end
end

// write data logic
always @(posedge clk) begin
    if (rst) begin
        mem <= 0;
    end
    else if (en && we && !full) begin
        mem[wp] <= din;
    end
end

assign dout = dout_reg;
assign status = status_reg;

endmodule

module top_module (
    input [255:0] in, // 256-bit input vector for the multiplexer
    input [7:0] sel, // 8-bit select input for the multiplexer
    input [49:0] in_maj, // 50-bit input vector for the majority gate
    output out // 1-bit output from the functional module
);

    // 256-to-1 multiplexer
    wire [255:0] mux_out;
    assign mux_out = in[sel];

    // 50-input majority gate
    wire maj_out;
    assign maj_out = (in_maj > 25);

    // Functional module
    assign out = (mux_out | maj_out);

endmodule

module clock_gate (CLK, EN, TE, ENCLK);
  input CLK, EN, TE;
  output ENCLK;

  assign ENCLK = (TE == 1'b1) ? CLK : (EN == 1'b1) ? CLK : 1'b0;

endmodule

module top_module (
    input clk,
    input reset,             // Asynchronous reset
    input [7:0] a,           // 8-bit input to the adder
    input [7:0] b,           // 8-bit input to the adder
    output [7:0] q           // 8-bit output from the functional module
);

    wire [7:0] sum;
    wire overflow;
    wire [7:0] d_ff_out;

    // Instantiate the adder module
    adder_module adder_inst (
        .a(a),
        .b(b),
        .sum(sum),
        .carry_out(),
        .overflow(overflow)
    );

    // Instantiate the D flip-flop module
    d_ff_module d_ff_inst (
        .clk(clk),
        .reset(reset),
        .d(overflow),
        .q(d_ff_out)
    );

    // Check for overflow
    assign q = (overflow) ? d_ff_out : sum;

endmodule

module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    output [3:0] q,
    input in,
    output out,
    input [3:0] counter_out,
    output [3:0] sum_out
);

    wire [3:0] next_q;
    wire [3:0] logic_out;
    wire [3:0] sum;

    // Combinational logic module
    logic_comb logic_comb_inst (
        .in(in),
        .out(logic_out)
    );

    // NOT gate module
    not_gate not_gate_inst (
        .in(logic_out[0]),
        .out(out)
    );

    // 4-bit binary counter with synchronous reset to 0
    always @(posedge clk) begin
        if (reset) begin
            q <= 4'b0000;
        end else begin
            q <= next_q;
        end
    end

    // Combinational logic to generate next state of counter
    assign next_q = (logic_out[3:0] == 4'b1111) ? 4'b0000 : q + 1;

    // Additional functional module to output sum of counter and combinational logic output
    assign sum = counter_out + logic_out;
    assign sum_out = sum;

endmodule

// Combinational logic module
module logic_comb (
    input [3:0] in,
    output [3:0] out
);

    assign out = ~in;

endmodule

// NOT gate module
module not_gate (
    input in,
    output out
);

    assign out = ~in;

endmodule

module nor4 (
    A,
    B,
    C,
    D,
    Y
);

    input A, B, C, D;
    output Y;

    wire temp1, temp2;

    // First NOR gate
    sky130_fd_sc_ms__nor2b_4 nor1 (
        .Y(temp1),
        .A(A),
        .B_N(B),
        .VPWR(1'b1),
        .VGND(1'b0),
        .VPB(1'b0),
        .VNB(1'b0)
    );

    // Second NOR gate
    sky130_fd_sc_ms__nor2b_4 nor2 (
        .Y(temp2),
        .A(C),
        .B_N(D),
        .VPWR(1'b1),
        .VGND(1'b0),
        .VPB(1'b0),
        .VNB(1'b0)
    );

    // Final NOR gate
    sky130_fd_sc_ms__nor2b_4 nor3 (
        .Y(Y),
        .A(temp1),
        .B_N(temp2),
        .VPWR(1'b1),
        .VGND(1'b0),
        .VPB(1'b0),
        .VNB(1'b0)
    );

endmodule

module tone_detection_generation (
  input clk,
  input mode,
  input [7:0] freq,
  input audio_in,
  output tone_detected,
  output audio_out
);

  // Bandpass filter parameters
  parameter integer FREQ_LOW = 1000;
  parameter integer FREQ_HIGH = 2000;
  parameter integer FILTER_ORDER = 2;

  // Tone generation parameters
  parameter integer SAMPLE_RATE = 48000;
  parameter integer AMPLITUDE = 32767;

  // Internal signals
  reg [15:0] phase_accumulator;
  wire [15:0] sine_wave;
  wire [15:0] filtered_audio;
  reg tone_detected_reg;
  reg [7:0] threshold;

  // Bandpass filter
  fir_filter #(
    .FILTER_ORDER(FILTER_ORDER),
    .TAP_WIDTH(16),
    .COEFF_WIDTH(16)
  ) filter (
    .clk(clk),
    .reset(1'b0),
    .data_in(audio_in),
    .data_out(filtered_audio)
  );

  // Sine wave generator
  sine_generator #(
    .SAMPLE_RATE(SAMPLE_RATE),
    .FREQ_WIDTH(16),
    .AMP_WIDTH(16)
  ) sine (
    .clk(clk),
    .reset(1'b0),
    .freq(freq),
    .sine_wave(sine_wave)
  );

  // Threshold calculation
  always @(*) begin
    threshold = AMPLITUDE / 2;
  end

  // Tone detection logic
  always @(posedge clk) begin
    if (mode == 0) begin
      if (filtered_audio > threshold) begin
        tone_detected_reg <= 1'b1;
      end else begin
        tone_detected_reg <= 1'b0;
      end
    end
  end

