module phase_detector (
  input ref_clk,
  input clk,
  output out,
  input threshold
);
  reg ref_clk_last;
  reg clk_last;
  reg [1:0] phase_diff;

  always @(posedge ref_clk or posedge clk) begin
    if (ref_clk_last == 1'b0 && ref_clk == 1'b1) begin
      phase_diff <= phase_diff + 2'b01;
    end
    if (clk_last == 1'b0 && clk == 1'b1) begin
      phase_diff <= phase_diff + 2'b10;
    end
    ref_clk_last <= ref_clk;
    clk_last <= clk;
  end

  assign out = (phase_diff > threshold) ? 1'b1 : 1'b0;

endmodule

module delay_line (
  input [DELAY_LINE_LENGTH-1:0] in,
