module shift_register (
    input clk,
    input reset,   // Synchronous active-high reset
    input [3:0] in, // 4-bit input for the shift register
    output [3:0] out // 4-bit output from the shift register
);

    reg [3:0] reg_data; // Internal register to store the data
    reg [2:0] count; // Internal counter to keep track of clock cycles

    always @(posedge clk) begin
        if (reset) begin
            reg_data <= 4'b0;
            count <= 3'b0;
        end else begin
            if (count == 3'b111) begin
                reg_data <= in;
            end else begin
                reg_data <= {reg_data[2:0], reg_data[3]};
            end
            count <= count + 1;
        end
    end

    assign out = reg_data;

endmodule

