// Priority encoder module
module priority_encoder (
    output reg [3:0] priority,
    input [7:0] a, b, c, d);

    always @*
    begin
        priority = 4'b0000;
        if (a < b && a < c && a < d)
            priority = 4'b0001;
        else if (b < c && b < d)
            priority = 4'b0010;
        else if (c < d)
            priority = 4'b0100;
        else
            priority = 4'b1000;
    end

endmodule

