    wire [2:0] gray_code;
    wire [2:0] binary_code;
    priority_encoder pe(.in(in), .gray_code(gray_code));
    gray_to_binary gtob(.gray_code(gray_code), .binary_code(binary_code));

    // LED display
    always @(*) begin
        case (binary_code)
            3'b000: led_out = 3'b000;
            3'b001: led_out = 3'b001;
            3'b010: led_out = 3'b010;
            3'b011: led_out = 3'b011;
            3'b100: led_out = 3'b100;
            3'b101: led_out = 3'b101;
            3'b110: led_out = 3'b110;
            3'b111: led_out = 3'b111;
        endcase
    end

    // Functional module
    always @(*) begin
        final_out = counter | binary_code;
    end

endmodule

// Priority encoder
module priority_encoder (
    input [7:0] in,
    output [2:0] gray_code
);
    assign gray_code = ~in[7:5] ^ {in[4], in[3], in[2], in[1]};
endmodule

// Gray-to-binary converter
module gray_to_binary (
    input [2:0] gray_code,
    output [2:0] binary_code
);
    assign binary_code[2] = gray_code[2];
    assign binary_code[1] = binary_code[2] ^ gray_code[1];
    assign binary_code[0] = binary_code[1] ^ gray_code[0];
endmodule

