module QuadratureCounter(
    input clock,
    input reset_l,
    input A,
    input B,
    output reg [31:0] CurrentCount,
    output reg Direction
);

reg A_prev;
reg B_prev;
reg [1:0] state;

always @(posedge clock or negedge reset_l) begin
    if (~reset_l) begin
        CurrentCount <= 32'h80000000;
        Direction <= 1'b0;
        state <= 2'b00;
    end else begin
        case (state)
            2'b00: begin
                if (A_prev == 1'b0 && A == 1'b1) begin
                    state <= 2'b01;
                end else if (B_prev == 1'b0 && B == 1'b1) begin
                    state <= 2'b10;
                end
            end
            2'b01: begin
                if (B_prev == 1'b0 && B == 1'b1) begin
                    CurrentCount <= CurrentCount + 1;
                    Direction <= 1'b1;
                    state <= 2'b11;
                end else if (A_prev == 1'b1 && A == 1'b0) begin
                    CurrentCount <= CurrentCount - 1;
                    Direction <= 1'b0;
                    state <= 2'b11;
                end else begin
                    state <= 2'b00;
                end
            end
            2'b10: begin
                if (A_prev == 1'b0 && A == 1'b1) begin
                    CurrentCount <= CurrentCount - 1;
                    Direction <= 1'b0;
                    state <= 2'b11;
                end else if (B_prev == 1'b1 && B == 1'b0) begin
                    CurrentCount <= CurrentCount + 1;
                    Direction <= 1'b1;
                    state <= 2'b11;
                end else begin
                    state <= 2'b00;
                end
            end
            2'b11: begin
                if (A_prev == 1'b1 && A == 1'b0) begin
                    state <= 2'b10;
                end else if (B_prev == 1'b0 && B == 1'b1) begin
                    state <= 2'b01;
                end
            end
        endcase
    end
    A_prev <= A;
    B_prev <= B;
end

endmodule

