    input a1, b1, a2, b2, // 4 input bits for the two binary numbers
    input select, // Select input to choose between carry-out of first half adder and second half adder
    output [1:0] sum // 2-bit output for the sum of the two binary numbers
);

    wire carry1, carry2;
    wire sum1, sum2;

    binary_adder adder1(a1, b1, 1'b0, sum1, carry1);
    binary_adder adder2(a2, b2, 1'b0, sum2, carry2);

    assign sum = {select ? carry2 : carry1, sum1} + sum2;

endmodule

module bcd_counter(
    input clk,
    input reset,
    output reg [3:1] ena,
    output reg [15:0] q
);

reg [3:0] count [3:1]; // 4-bit counter for each digit
reg [3:0] mux_out [3:1]; // 4-bit output of each digit's multiplexer
reg [1:0] digit_sel; // 2-bit select signal for the multiplexers
reg [15:0] add_out; // 16-bit output of the functional module

// Multiplexers for each digit
mux4to1 mux0(.in0(count[1]), .in1(count[1]+1), .in2(count[1]+2), .in3(count[1]+3), .sel(digit_sel), .out(mux_out[1]));
mux4to1 mux1(.in0(count[2]), .in1(count[2]+1), .in2(count[2]+2), .in3(count[2]+3), .sel(digit_sel), .out(mux_out[2]));
mux4to1 mux2(.in0(count[3]), .in1(count[3]+1), .in2(count[3]+2), .in3(count[3]+3), .sel(digit_sel), .out(mux_out[3]));

// D flip-flops for each digit
always @(posedge clk, posedge reset) begin
    if (reset) begin
        count[1] <= 4'b0000;
        count[2] <= 4'b0000;
        count[3] <= 4'b0000;
        digit_sel <= 2'b00;
    end else begin
        if (ena[1]) count[1] <= count[1] + 1;
        if (ena[2]) count[2] <= count[2] + 1;
        if (ena[3]) count[3] <= count[3] + 1;
        digit_sel <= digit_sel + 1;
    end
end

// Functional module
always @(*) begin
    if (A > B) begin
        add_out = {mux_out[3], mux_out[2], mux_out[1]};
    end else begin
        add_out = {count[3], count[2], count[1]};
    end
end

// Output signals
assign q = add_out;
assign ena = {1'b0, ena[3:1]};

endmodule

module ir_rcv (
    input clk50,
    input reset_n,
    input ir_rx,
    output reg [31:0] ir_code,
    output reg ir_code_ack
);

// Define constants
parameter LEADCODE_LO_THOLD     = 230000;  //4.60ms
parameter LEADCODE_HI_THOLD     = 210000;  //4.20ms
parameter LEADCODE_HI_RPT_THOLD = 105000;  //2.1ms
parameter RPT_RELEASE_THOLD     = 6000000; //120ms
parameter BIT_ONE_THOLD         = 41500;   //0.83ms
parameter BIT_DETECT_THOLD      = 20000;   //0.4ms
parameter IDLE_THOLD            = 262143;  //5.24ms

// Define states
parameter STATE_IDLE      = 2'b00;
parameter STATE_LEADVERIFY = 2'b01;
parameter STATE_DATARCV    = 2'b10;

// Define state variables
reg [1:0] state;            // 3 states
reg [31:0] databuf;         // temp. buffer
reg [5:0] bits_detected;    // max. 63, effectively between 0 and 33
reg [17:0] act_cnt;         // max. 5.2ms
reg [17:0] leadvrf_cnt;     // max. 5.2ms
reg [17:0] datarcv_cnt;     // max. 5.2ms
reg [22:0] rpt_cnt;         // max. 166ms

// Activity when signal is low
always @(posedge clk50 or negedge reset_n)
begin
    if (!reset_n)
        act_cnt <= 0;
    else
    begin
        if ((state == STATE_IDLE) & (~ir_rx))
            act_cnt <= act_cnt + 1'b1;
        else
            act_cnt <= 0;
    end
end

// Lead code verify counter
always @(posedge clk50 or negedge reset_n)
begin
    if (!reset_n)
        leadvrf_cnt <= 0;
    else
    begin
        if ((state == STATE_LEADVERIFY) & ir_rx)
            leadvrf_cnt <= leadvrf_cnt + 1'b1;
        else
            leadvrf_cnt <= 0;
    end
end

// '0' and '1' are differentiated by high phase duration preceded by constant length low phase
always @(posedge clk50 or negedge reset_n)
begin
    if (!reset_n)
    begin
        datarcv_cnt <= 0;
        bits_detected <= 0;
        databuf <= 0;
    end
    else
    begin
        if (state == STATE_DATARCV)
        begin
            if (ir_rx)
                datarcv_cnt <= datarcv_cnt + 1'b1;
            else
                datarcv_cnt <= 0;

            if (datarcv_cnt == BIT_DETECT_THOLD)
                bits_detected <= bits_detected + 1'b1;

            if (datarcv_cnt == BIT_ONE_THOLD)
                databuf[32-bits_detected] <= 1'b1;
        end
        else
        begin
            datarcv_cnt <= 0;
            bits_detected <= 0;
            databuf <= 0;
        end
    end
end

// Read and validate data after 32 bits detected (last bit may change to '1' at any time)
always @(posedge clk50 or negedge reset_n)
begin
    if (!reset_n)
    begin
        ir_code_ack <= 1'b0;
        ir_code <= 32'h00000000;
    end
    else
    begin
        if ((bits_detected == 32) & (databuf[15:8] == ~databuf[7:0]))
        begin
            ir_code <= databuf;
            ir_code_ack <= 1'b1;
        end
        else if (rpt_cnt >= RPT_RELEASE_THOLD)
        begin
            ir_code <= 32'h00000000;
            ir_code_ack <= 1'b0;
        end
        else
            ir_code_ack <= 1'b0;
    end
end

// State machine
always @(posedge clk50 or negedge reset_n)
begin
    if (!reset_n)
    begin
        state <= STATE_IDLE;
        rpt_cnt <= 0;
    end
    else
    begin
        rpt_cnt <= rpt_cnt + 1'b1;

        case (state)
            STATE_IDLE:
                if (act_cnt >= LEADCODE_LO_THOLD)
                    state <= STATE_LEADVERIFY;
            STATE_LEADVERIFY:
            begin
                if (leadvrf_cnt == LEADCODE_HI_RPT_THOLD)
                    rpt_cnt <= 0;
                if (leadvrf_cnt >= LEADCODE_HI_THOLD)
                    state <= STATE_DATARCV;
            end
            STATE_DATARCV:
                if ((datarcv_cnt >= IDLE_THOLD) | (bits_detected >= 33))
                    state <= STATE_IDLE;
            default:
                state <= STATE_IDLE;
        endcase
    end
end

endmodule

