    concat_16bit concat(
        .in_hi(in_hi),
        .in_lo(in_lo),
        .out(concat_output)
    );

    // XOR gate
    assign xor_output = in_hi ^ in_lo;

    // Additive functional module
    assign final_output = (xor_output * concat_output) + concat_output;

endmodule

