(
    input clk_i,
    input rst_i,
    input mode_load_pulse,
    input [3:0] bl_mode_reg,
    input [7:0] fixed_bl_i,
    input [7:0] bram_bl_i,
    input [1:0] data_mode_i
);

parameter TCQ = 1;
parameter BL_WIDTH = 8;
parameter FAMILY = "VIRTEX6";
parameter CMD_PATTERN = "CGEN_PRBS";

reg [BL_WIDTH-1:0] bl_out;
wire [BL_WIDTH-1:0] prbs_bl;
reg [5:0] prbs_brlen;

// the number of burst length to rd_data_gen, wr_data_gen  and mcb_flow_control_v6.
// The mcb_flow_control takes the base address of the first burst and the bl value,
// it automatically increment the next consecutive address of the back-to-back commands
// until the burst counts decrement to 0.
always @ (posedge clk_i) begin
   if (mode_load_pulse || rst_i[3])
        bl_out <= #TCQ    fixed_bl_i ;
   else if (cmd_clk_en) begin
     case({bl_mode_reg})
         0:  begin
                 bl_out[5:0] <= #TCQ  bram_bl_i  ;
                 bl_out[BL_WIDTH-1:6] <= #TCQ  'b0  ;

             end
         1: if (data_mode_i == 4)
                bl_out <= #TCQ  10'd8 ;
            else
                bl_out <= #TCQ  fixed_bl_i ;
         2: bl_out <= #TCQ  prbs_brlen;
         3: bl_out <= #TCQ  fixed_bl_i;
         default : begin
                    bl_out[5:0] <= #TCQ    6'h1;
                    bl_out[BL_WIDTH - 1:6] <= #TCQ  'b0;

                   end
     endcase
   end
end

generate
if (CMD_PATTERN == "CGEN_PRBS" || CMD_PATTERN == "CGEN_ALL" ) 
   begin: gen_prbs_bl
       cmd_prbs_gen #
          (
        .TCQ               (TCQ),      
        .FAMILY      (FAMILY),
        .PRBS_CMD    ("BLEN"),
        .ADDR_WIDTH  (32),
        .SEED_WIDTH  (15),
        .PRBS_WIDTH  (20)
       )
       bl_prbs_gen
      (
       .clk_i             (clk_i),
       .clk_en            (cmd_clk_en),
       .prbs_seed_init    (load_seed_i),
       .prbs_seed_i       (cmd_seed_i[16:2]),
       .prbs_o            (prbs_bl)
      );

    always @ (prbs_bl)
     if (FAMILY == "SPARTAN6" || FAMILY == "MCB")  // supports 1 throug 64
       prbs_brlen[5:0]  =  (prbs_bl[5:1] == 5'b00000) ? 6'b000010: {prbs_bl[5:1],1'b0};
     else // VIRTEX6 only supports 1 or 2 burst on user ports
       prbs_brlen =  (prbs_bl[BL_WIDTH-1:1] == 5'b00000) ? {{BL_WIDTH-2{1'b0}},2'b10}: {prbs_bl[BL_WIDTH-1:1],1'b0};


  end
 else
    begin: no_gen_prbs_bl
       assign prbs_bl = 'b0;
    end

endgenerate

endmodule

module clk_193MHz(clk_100MHz, clk_193MHz, locked);
  input clk_100MHz;
  output clk_193MHz;
  output locked;

  reg [8:0] counter = 0;
  reg locked_reg = 0;
  wire clk_1Hz;

  assign clk_1Hz = counter == 99;

  always @(posedge clk_100MHz) begin
    if (counter == 99) begin
      counter <= 0;
      clk_193MHz <= ~clk_193MHz;
    end else begin
      counter <= counter + 1;
    end
  end

  always @(posedge clk_100MHz) begin
    if (clk_193MHz && !locked_reg) begin
      locked_reg <= 1;
      locked <= 1;
    end else if (!clk_193MHz && locked_reg) begin
      locked_reg <= 0;
      locked <= 0;
    end
  end

endmodule

module top_module( 
    input a, 
    input b, 
    input [99:0] in,
    output [7:0] out
);

    // Implement NOR gate using NAND gates
    wire nand1, nand2, nor;
    assign nand1 = ~(a & b);
    assign nand2 = ~(nand1 & nand1);
    assign nor = ~(nand2 & nand2);

    // Implement bit reversal using shift register and multiplexer
    reg [99:0] shift_reg;
    wire [99:0] reversed;
    assign reversed = {shift_reg[99], shift_reg[98:0]};
    always @(posedge clk) begin
        shift_reg <= {shift_reg[98:0], in[99]};
    end

    // Perform bitwise AND operation on NOR gate output and 8 most significant bits of reversed input
    assign out = nor & reversed[99:92];

endmodule

