module multiplier_block (
    i_data0,
    o_data0
);

  // Port mode declarations:
  input   [31:0] i_data0;
  output  [31:0] o_data0;

  //Multipliers:
  wire [31:0] w1;
  wire [31:0] w4;
  wire [31:0] w5;
  wire [31:0] w10240;
  wire [31:0] w10241;

  assign w1 = i_data0;
  assign w4 = w1 << 2;
  assign w5 = w1 + w4;
  assign w10240 = w5 << 11;
  assign w10241 = w1 + w10240;

  assign o_data0 = w10241;

  //multiplier_block area estimate = 2714.34246185294;
endmodule

module Counter (
    input wire Clock,
    input wire Reset,
    input wire Enable,
    input wire [3:0] CountTo,
    output reg [3:0] CountValue,
    output reg CountFinished
);

    wire [3:0] nextCountValue;

    FFD #(.SIZE(4)) ffd (
        .Clock(Clock),
        .Reset(Reset),
        .Enable(Enable),
        .D(nextCountValue),
        .Q(CountValue)
    );

    always @(*) begin
        if (CountValue == CountTo) begin
            CountFinished = 1;
            nextCountValue = 0;
        end else begin
            CountFinished = 0;
            nextCountValue = CountValue + 1;
        end
    end

endmodule

module IF_M(
		input [0:0] clka,
		input [0:0] rst,
		output [31:0] Inst_code
    );
	wire [31:0] douta;
	wire [5:0] addra;
	reg [31:0] PC;
	wire [31:0] PC_new;

	IROM Inst_addr (
	  .clka(clka), // input clka
	  .addra(addra), // input [5 : 0] addra
	  .douta(douta) // output [31 : 0] douta
	);
	assign PC_new = PC + 4;
	assign Inst_code = douta;
	assign addra = PC[7:2];
	always@(posedge clka or posedge rst)
	begin
		if(rst)
			begin
				PC[31:0]<=32'd0;
			end
		else
			begin
				PC<=PC_new;
			end
	end
endmodule

