module AN_encoder_decoder (
  input [n-1:0] symbols,
  input [n-1:0] probabilities,
  input [31:0] low,
  input [31:0] high,
  output [31:0] code,
  output [n-1:0] low_range,
  output [n-1:0] high_range,
  output [n-1:0] decoded_symbols
);

parameter n = 8; // number of symbols

// calculate probability ranges
reg [31:0] prob_range [n-1:0];
reg [31:0] total_range;
reg [31:0] temp_range;
integer i;
always @* begin
  total_range = high - low + 1;
  temp_range = 0;
  for (i = 0; i < n; i = i + 1) begin
    prob_range[i] = (probabilities[i] * total_range) >> 16;
    low_range[i] = temp_range + low;
    high_range[i] = temp_range + prob_range[i] + low - 1;
    temp_range = temp_range + prob_range[i];
  end
end

// encode input symbols
reg [31:0] new_low;
reg [31:0] new_high;
integer j;
always @* begin
  new_low = low;
  new_high = high;
  for (j = 0; j < n; j = j + 1) begin
    if (symbols[j] == 1) begin
      new_low = new_low + prob_range[j] + 1;
      new_high = new_low + prob_range[j+1] - 1;
    end else begin
      new_high = new_high - prob_range[j] - 1;
      new_low = new_high - prob_range[j+1] + 1;
    end
  end
  code = new_low;
end

// decode input code
reg [31:0] new_code;
reg [31:0] symbol_range;
integer k;
always @* begin
  new_code = code;
  for (k = 0; k < n; k = k + 1) begin
    symbol_range = ((new_code - low) * 65536) / total_range;
    if (symbol_range >= prob_range[k]) begin
      decoded_symbols[k] = 1;
      new_code = new_code - prob_range[k];
    end else begin
      decoded_symbols[k] = 0;
    end
  end
end

endmodule

