module gray_send
  #(parameter WIDTH = 8)
    (input clk_in, input [WIDTH-1:0] addr_in,
     input clk_out, output reg [WIDTH-1:0] addr_out);

   reg [WIDTH-1:0] gray_clkin, gray_clkout, gray_clkout_d1;
   wire [WIDTH-1:0] gray, bin;

   // instantiate bin2gray and gray2bin modules
   bin2gray #(.WIDTH(WIDTH)) b2g (.bin(addr_in), .gray(gray) );
   gray2bin #(.WIDTH(WIDTH)) g2b (.gray(gray_clkout_d1), .bin(bin) );

   // sample input address on rising edge of clk_in
   always @(posedge clk_in)
     gray_clkin <= gray;

   // encode input address and output on rising edge of clk_out
   always @(posedge clk_out)
     gray_clkout <= gray_clkin;

   // delay output address by one clock cycle
   always @(posedge clk_out)
     gray_clkout_d1 <= gray_clkout;

   // convert gray code encoded address to binary and output on rising edge of clk_out
   always @(posedge clk_out)
     addr_out <= bin;

endmodule

