module small_fifo
    #(parameter WIDTH = 16,
      parameter MAX_DEPTH_BITS = 3,
      parameter PROG_FULL_THRESHOLD = 2**MAX_DEPTH_BITS - 1
      )
    (

     input [WIDTH-1:0] din,     // Data in
     input          wr_en,   // Write enable

     input          rd_en,   // Read the next word

     output reg [WIDTH-1:0]  dout,    // Data out
     output         full,
     output         nearly_full,
     output         prog_full,
     output         empty,
     output         nearly_empty,

     input          reset,
     input          clk
     );


parameter MAX_DEPTH        = 2 ** MAX_DEPTH_BITS;

reg [WIDTH-1:0] queue [MAX_DEPTH - 1 : 0];
reg [MAX_DEPTH_BITS - 1 : 0] rd_ptr;
reg [MAX_DEPTH_BITS - 1 : 0] wr_ptr;
reg [MAX_DEPTH_BITS : 0] depth;

// Sample the data
always @(posedge clk)
begin
   if (wr_en && ~full)
      queue[wr_ptr] <= din;
   if (rd_en && ~empty)
      dout <= queue[rd_ptr];
end

always @(posedge clk)
begin
   if (reset) begin
      rd_ptr <= 'h0;
      wr_ptr <= 'h0;
      depth  <= 'h0;
   end
   else begin
      if (wr_en && ~full) wr_ptr <= wr_ptr + 'h1;
      if (rd_en && ~empty) rd_ptr <= rd_ptr + 'h1;
      if (wr_en && ~rd_en && ~full) depth <= depth + 'h1;
      else if (rd_en && ~wr_en && ~empty) depth <= depth - 'h1;
   end
end

assign full = depth == MAX_DEPTH;
assign nearly_full = depth >= MAX_DEPTH-1;
assign empty = depth == 'h0;
assign nearly_empty = depth <= 'h1;

// synthesis translate_off
always @(posedge clk)
begin
   if (wr_en && full)
      $display($time, " ERROR: Attempt to write to full FIFO: %m");
   if (rd_en && empty)
      $display($time, " ERROR: Attempt to read an empty FIFO: %m");
end
// synthesis translate_on

endmodule

module Profibus (
  input clk,
  input rst,
  input [7:0] din_master,
  input [7:0] din_slave,
  output reg [7:0] dout_master,
  output reg [7:0] dout_slave,
  output reg status_master,
  output reg status_slave
);

  // Define communication protocol between master and slave
  reg [1:0] state_master;
  reg [1:0] state_slave;
  parameter IDLE = 2'b00;
  parameter SEND_CMD = 2'b01;
  parameter RECEIVE_DATA = 2'b10;
  parameter SEND_DATA = 2'b01;
  parameter RECEIVE_CMD = 2'b10;

  // Define communication lines between master and slave
  reg [7:0] cmd_master;
  reg [7:0] cmd_slave;
  reg [7:0] data_master;
  reg [7:0] data_slave;

  // Initialize status signals to indicate idle state
  assign status_master = (state_master == IDLE) ? 1'b1 : 1'b0;
  assign status_slave = (state_slave == IDLE) ? 1'b1 : 1'b0;

  // Master block
  always @(posedge clk) begin
    if (rst) begin
      state_master <= IDLE;
      dout_master <= 8'b0;
    end else begin
      case (state_master)
        IDLE: begin
          if (din_master != 8'b0) begin
            cmd_master <= din_master;
            state_master <= SEND_CMD;
          end
        end
        SEND_CMD: begin
          dout_slave <= cmd_master;
          state_master <= RECEIVE_DATA;
        end
        RECEIVE_DATA: begin
          if (din_master != 8'b0) begin
            data_master <= din_master;
            state_master <= SEND_DATA;
          end
        end
        SEND_DATA: begin
          dout_slave <= data_master;
          state_master <= IDLE;
        end
      endcase
    end
  end

  // Slave block
  always @(posedge clk) begin
    if (rst) begin
      state_slave <= IDLE;
      dout_slave <= 8'b0;
    end else begin
      case (state_slave)
        IDLE: begin
          if (din_slave != 8'b0) begin
            cmd_slave <= din_slave;
            state_slave <= RECEIVE_CMD;
          end
        end
        RECEIVE_CMD: begin
          if (din_slave != 8'b0) begin
            data_slave <= din_slave;
            state_slave <= SEND_DATA;
          end
        end
        SEND_DATA: begin
          dout_master <= data_slave;
          state_slave <= IDLE;
        end
      endcase
    end
  end

endmodule

