module clk_generator(
    input clk,
    input clk_ena,
    input rstn,
    output reg clk_out
);

parameter BAUDRATE = 8;
parameter M2 = 4;

reg [log2(BAUDRATE)-1:0] divcounter = 0;

// Counter
always @(posedge clk or negedge rstn) begin
    if (!rstn) begin
        divcounter <= 0;
    end
    else if (clk_ena) begin
        divcounter <= (divcounter == BAUDRATE - 1) ? 0 : divcounter + 1;
    end
    else begin
        divcounter <= BAUDRATE - 1;
    end
end

// Output
always @(posedge clk) begin
    clk_out <= (divcounter == M2) ? clk_ena : 0;
end

endmodule

module bcd_counter (
    input clk,
    input reset,   // Synchronous active-high reset
    output [3:1] ena,
    output [15:0] q);

    reg [15:0] count;
    wire [3:0] bcd_count;
    wire [3:0] bcd_count_next;

    // Instantiate the multiplexers and decoders
    mux4to1 mux0 (count[3:0], bcd_count[0], bcd_count[1], bcd_count[2], bcd_count[3]);
    mux4to1 mux1 (count[7:4], bcd_count[4], bcd_count[5], bcd_count[6], bcd_count[7]);
    mux4to1 mux2 (count[11:8], bcd_count[8], bcd_count[9], bcd_count[10], bcd_count[11]);
    mux4to1 mux3 (count[15:12], bcd_count[12], bcd_count[13], bcd_count[14], bcd_count[15]);
    decoder3to8 dec0 (bcd_count[2:0], ena);

    // Assign the output
    assign q = {bcd_count[15:12], bcd_count[11:8], bcd_count[7:4], bcd_count[3:0]};

    // Increment the counter on the rising edge of the clock
    always @(posedge clk) begin
        if (reset) begin
            count <= 0;
        end else begin
            count <= count + 1;
        end
    end

    // Determine the next BCD count based on the current binary count
    always @* begin
        case (count[3:0])
            4'b0000: bcd_count_next = 4'b0000;
            4'b0001: bcd_count_next = 4'b0001;
            4'b0010: bcd_count_next = 4'b0010;
            4'b0011: bcd_count_next = 4'b0011;
            4'b0100: bcd_count_next = 4'b0100;
            4'b0101: bcd_count_next = 4'b0101;
            4'b0110: bcd_count_next = 4'b0110;
            4'b0111: bcd_count_next = 4'b0111;
            4'b1000: bcd_count_next = 4'b1000;
            4'b1001: bcd_count_next = 4'b0000;
            default: bcd_count_next = 4'b0000;
        endcase

        case (count[7:4])
            4'b0000: bcd_count_next = {bcd_count_next, 4'b0000};
            4'b0001: bcd_count_next = {bcd_count_next, 4'b0001};
            4'b0010: bcd_count_next = {bcd_count_next, 4'b0010};
            4'b0011: bcd_count_next = {bcd_count_next, 4'b0011};
            4'b0100: bcd_count_next = {bcd_count_next, 4'b0100};
            4'b0101: bcd_count_next = {bcd_count_next, 4'b0101};
            4'b0110: bcd_count_next = {bcd_count_next, 4'b0110};
            4'b0111: bcd_count_next = {bcd_count_next, 4'b0111};
            4'b1000: bcd_count_next = {bcd_count_next, 4'b1000};
            4'b1001: bcd_count_next = {bcd_count_next, 4'b0000};
            default: bcd_count_next = {bcd_count_next, 4'b0000};
        endcase

        case (count[11:8])
            4'b0000: bcd_count_next = {bcd_count_next, 4'b0000};
            4'b0001: bcd_count_next = {bcd_count_next, 4'b0001};
            4'b0010: bcd_count_next = {bcd_count_next, 4'b0010};
            4'b0011: bcd_count_next = {bcd_count_next, 4'b0011};
            4'b0100: bcd_count_next = {bcd_count_next, 4'b0100};
            4'b0101: bcd_count_next = {bcd_count_next, 4'b0101};
            4'b0110: bcd_count_next = {bcd_count_next, 4'b0110};
            4'b0111: bcd_count_next = {bcd_count_next, 4'b0111};
            4'b1000: bcd_count_next = {bcd_count_next, 4'b1000};
            4'b1001: bcd_count_next = {bcd_count_next, 4'b0000};
            default: bcd_count_next = {bcd_count_next, 4'b0000};
        endcase

        case (count[15:12])
            4'b0000: bcd_count_next = {bcd_count_next, 4'b0000};
            4'b0001: bcd_count_next = {bcd_count_next, 4'b0001};
            4'b0010: bcd_count_next = {bcd_count_next, 4'b0010};
            4'b0011: bcd_count_next = {bcd_count_next, 4'b0011};
            4'b0100: bcd_count_next = {bcd_count_next, 4'b0100};
            4'b0101: bcd_count_next = {bcd_count_next, 4'b0101};
            4'b0110: bcd_count_next = {bcd_count_next, 4'b0110};
            4'b0111: bcd_count_next = {bcd_count_next, 4'b0111};
            4'b1000: bcd_count_next = {bcd_count_next, 4'b1000};
            4'b1001: bcd_count_next = {bcd_count_next, 4'b0000};
            default: bcd_count_next = {bcd_count_next, 4'b0000};
        endcase
    end

    // Update the BCD count on the rising edge of the clock
    always @(posedge clk) begin
        if (reset) begin
            bcd_count <= 4'b0000;
        end else begin
            bcd_count <= bcd_count_next;
        end
    end

endmodule

