reg [1:0] stage;

always @(posedge clk) begin
    case (stage)
        0: begin
            A_reg <= A;
            B_reg <= B;
            case (OP)
                3'b000: Y_reg <= A_reg + B_reg;
                3'b001: Y_reg <= A_reg - B_reg;
                3'b010: Y_reg <= A_reg & B_reg;
                3'b011: Y_reg <= A_reg | B_reg;
                3'b100: Y_reg <= A_reg ^ B_reg;
            endcase
            stage <= 1;
        end
        1: begin
            Y <= Y_reg;
            stage <= 0;
        end
    endcase
end

endmodule

