module rotator (
    input clk,
    input load,       // Synchronous load
    input left_en,    // Left rotate enable
    input right_en,   // Right rotate enable
    input [49:0] data,// 50-bit input
    output reg [49:0] out_data // 50-bit output
);

always @(posedge clk) begin
    if (load) begin
        out_data <= data;
    end else if (left_en) begin
        out_data <= {out_data[47:0], out_data[49:48]};
    end else if (right_en) begin
        out_data <= {out_data[1:0], out_data[49:2]};
    end
end

endmodule

