module shift_register(
    input clk,
    input areset,
    input load,
    input ena,
    input [3:0] in_data,
    output reg [3:0] out_data
);

reg [1:0] counter;

always @(posedge clk or negedge areset) begin
    if (areset == 0) begin
        counter <= 0;
        out_data <= 0;
    end else begin
        if (load == 1) begin
            out_data <= in_data;
        end else if (ena == 1) begin
            case (counter)
                0: out_data <= {out_data[2:0], out_data[3]};
                1: out_data <= {out_data[1:0], out_data[3:2]};
            endcase
            counter <= counter + 1;
        end
    end
end

endmodule

