module fifo #(
  parameter width = 8, // width of the data bus
  parameter depth = 16 // depth of the FIFO
)(
  input clk, // clock
  input reset, // reset
  input write_en, // write enable
  input [width-1:0] write_data, // data to be written
  input read_en, // read enable
  output reg [width-1:0] read_data, // data that is read
  output reg empty, // FIFO empty flag
  output reg full, // FIFO full flag
  output reg error // error flag
);

  reg [width-1:0] mem [depth-1:0]; // memory array
  reg [log2(depth)-1:0] head = 0; // head pointer
  reg [log2(depth)-1:0] tail = 0; // tail pointer
  reg [log2(depth)-1:0] count = 0; // element count

  // initialize flags
  always @ (posedge clk, posedge reset) begin
    if (reset) begin
      empty <= 1'b1;
      full <= 1'b0;
      error <= 1'b0;
    end else begin
      empty <= (count == 0);
      full <= (count == depth);
    end
  end

  // write operation
  always @ (posedge clk) begin
    if (reset) begin
      head <= 0;
      tail <= 0;
      count <= 0;
    end else begin
      if (write_en && !full) begin
        mem[head] <= write_data;
        head <= head + 1;
        count <= count + 1;
      end
    end
  end

  // read operation
  always @ (posedge clk) begin
    if (reset) begin
      read_data <= 0;
    end else begin
      if (read_en && !empty) begin
        read_data <= mem[tail];
        tail <= tail + 1;
        count <= count - 1;
      end
    end
  end

  // error detection and correction
  always @ (posedge clk) begin
    if (reset) begin
      error <= 1'b0;
    end else begin
      if (count > depth) begin
        error <= 1'b1;
        count <= depth;
        tail <= head - depth;
      end
      if (count < 0) begin
        error <= 1'b1;
        count <= 0;
        head <= tail + depth;
      end
    end
  end

endmodule

