module alu_behav_new
    ( output [15:0] Y,
      output [15:0] flags,
      input [15:0] A,
      input [15:0] B,
      input [3:0] sel
    );


     reg [15:0] outreg;
     reg [15:0] flagreg;

     reg carry;
     reg overflow;

     always @(A, B, sel) begin

        flagreg = 0;
        carry = 0;
        overflow = 0;

        case(sel)
            4'b0011: begin                       // XOR
                            outreg = A ^ B;
                        end
            4'b0001: begin                       // AND
                            outreg = A & B;
                        end
            4'b0010: begin                       // OR
                            outreg = A | B;
                        end
            4'b0101: begin                       // ADD
                            {carry, outreg} = A + B;
                            overflow = (($signed(A) >= 0 && $signed(B) >= 0 && $signed(outreg) < 0) || ($signed(A) < 0 && $signed(B) < 0 && $signed(outreg) >= 0)) ? 1'b1 : 1'b0;
                        end
            4'b1001, 
            4'b1011: begin                       // SUB or CMP
                            {carry, outreg} = A + ~B + 1'b1;
                            overflow = (($signed(A) >= 0 && $signed(B) < 0 && $signed(outreg) < 0) || ($signed(A) < 0 && $signed(B) >= 0 && $signed(outreg) >= 0)) ? 1'b1 : 1'b0;
                        end
            4'b1101: begin                       // Shift left by 1 bit
                            outreg = {B[14:0], 1'b0};
                        end
            4'b1111: begin                       // Load Upper
                            outreg = { B[7:0], B[15:8] };
                        end

            default: begin 
                            outreg = A;            // Do nothing 
                            flagreg = 0;
                        end

        endcase

        flagreg[0] = carry;    // Carry set by ADD and SUB only.
        flagreg[2] = (A < B) && (sel == 4'b1011);    // Low Flag set by CMP only.
        flagreg[5] = overflow; // Overflow set by ADD and SUB only.
        flagreg[6] = (outreg == 16'b0) && (sel == 4'b1011); // Zero Flag set by CMP only.
        flagreg[7] = outreg[15] && (sel == 4'b1011); // Negative (Sign) Flag set by CMP only.

        if(sel == 4'b1011) begin
            outreg = A;
        end

     end

     assign Y = outreg;
     assign flags = flagreg;

endmodule

module FSM (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 4; // number of input signals
parameter m = 2; // number of output signals
parameter s = 8; // number of states

reg [2:0] state; // register to hold current state

// define states and their associated output signals
parameter S0 = 3'b000;
parameter S1 = 3'b001;
parameter S2 = 3'b010;
parameter S3 = 3'b011;
parameter S4 = 3'b100;
parameter S5 = 3'b101;
parameter S6 = 3'b110;
parameter S7 = 3'b111;

// define output signals for each state
assign out[0] = (state == S0 || state == S1 || state == S2 || state == S3) ? 1'b1 : 1'b0;
assign out[1] = (state == S4 || state == S5 || state == S6 || state == S7) ? 1'b1 : 1'b0;

// define transitions between states based on input signals
always @(*) begin
  case(state)
    S0: state = (in[0] == 1'b1) ? S1 : S0;
    S1: state = (in[1] == 1'b1) ? S3 : S2;
    S2: state = (in[2] == 1'b1) ? S3 : S1;
    S3: state = (in[3] == 1'b1) ? S4 : S0;
    S4: state = (in[0] == 1'b1) ? S5 : S4;
    S5: state = (in[1] == 1'b1) ? S7 : S6;
    S6: state = (in[2] == 1'b1) ? S7 : S5;
    S7: state = (in[3] == 1'b1) ? S0 : S4;
  endcase
end

endmodule

