module mux_6to1 (
    input [2:0] sel,
    input [5:0] data,
    output reg [3:0] out
);

    // Priority Encoder
    wire [2:0] encoded_sel;
    assign encoded_sel = ~sel ? 3'b111 : {~sel[2], ~sel[1], ~sel[0]};

    // Decoder
    reg [5:0] decoded_data;
    always @* begin
        case(encoded_sel)
            3'b001: decoded_data = data[3:0];
            3'b010: decoded_data = data[7:4];
            3'b100: decoded_data = data[11:8];
            3'b000: decoded_data = data[15:12];
            3'b011: decoded_data = data[19:16];
            3'b101: decoded_data = data[23:20];
            default: decoded_data = 4'b0000;
        endcase
    end

    // Output
    always @* begin
        if (sel < 6) begin
            out = decoded_data;
        end else begin
            out = 4'b0000;
        end
    end

endmodule

module reverse_byte_ordering(
    input [31:0] in,
    output reg [31:0] out
);
    always @(*) begin
        out[31:24] = in[7:0];
        out[23:16] = in[15:8];
        out[15:8] = in[23:16];
        out[7:0] = in[31:24];
    end
endmodule

module nand_gate(
    input a,
    input b,
    output reg out
);
    always @(a, b) begin
        out = ~(a & b);
    end
endmodule

module bitwise_or(
    input [31:0] in1,
    input [31:0] in2,
    output reg [31:0] out
);
    always @(in1, in2) begin
        out = in1 | in2;
    end
endmodule

module top_module( 
    input [31:0] in1,
    input [31:0] in2,
    output wire out
); 
    wire [31:0] rev_in1, rev_in2;
    wire nand_out1, nand_out2, nand_out3;

    reverse_byte_ordering rbo1(.in(in1), .out(rev_in1));
    reverse_byte_ordering rbo2(.in(in2), .out(rev_in2));

    nand_gate ng1(.a(rev_in1[0]), .b(rev_in2[0]), .out(nand_out1));
    nand_gate ng2(.a(rev_in1[1]), .b(rev_in2[1]), .out(nand_out2));
    nand_gate ng3(.a(nand_out1), .b(nand_out2), .out(nand_out3));

    bitwise_or bo(.in1(rev_in1), .in2(rev_in2), .out(out));

    assign out = nand_out3;
endmodule

module calculator(
  input [7:0] num1,
  input [7:0] num2,
  input [1:0] operation,
  output [7:0] result,
  output negative
);

  reg [15:0] temp_result;
  reg signed [7:0] signed_result;

  always @* begin
    case(operation)
      2'b00: temp_result = num1 + num2; // Addition
      2'b01: temp_result = num1 - num2; // Subtraction
      2'b10: temp_result = num1 * num2; // Multiplication
      2'b11: temp_result = num1 / num2; // Division
    endcase

    signed_result = temp_result[7:0];
    result = signed_result;

    if(signed_result < 0) begin
      negative = 1;
    end
    else begin
      negative = 0;
    end
  end

endmodule

module UART (
    input rx_clk,
    input rx_data,
    input tx_clk,
    output reg tx_data,
    output reg rx_interrupt,
    output reg tx_interrupt,
    output reg tx,
    output reg tx_en,
    output reg rts_n,
    input reset,
    input cts_n,
    input clock,
    input rx
);

    parameter Address1 = 0;
    parameter Address2 = 0;
    parameter EnIntRXInterrupt = 0;
    parameter EnIntTXInterrupt = 0;
    parameter FlowControl = 0;
    parameter HalfDuplexEn = 0;
    parameter HwTXEnSignal = 1;
    parameter NumDataBits = 8;
    parameter NumStopBits = 1;
    parameter ParityType = 0;
    parameter RXEnable = 1;
    parameter TXEnable = 0;

    reg [NumDataBits-1:0] data_reg;
    reg [3:0] state_reg;
    reg [2:0] bit_count_reg;
    reg [1:0] stop_bit_count_reg;
    reg parity_reg;
    reg tx_busy_reg;

    always @(posedge rx_clk) begin
        if (reset) begin
            state_reg <= 4'b0000;
            bit_count_reg <= 3'b000;
            stop_bit_count_reg <= 2'b00;
            parity_reg <= 1'b0;
            rx_interrupt <= 1'b0;
        end else begin
            case (state_reg)
                4'b0000: begin // idle state
                    if (!rx) begin
                        state_reg <= 4'b0001;
                        bit_count_reg <= 3'b000;
                        stop_bit_count_reg <= 2'b00;
                        parity_reg <= 1'b0;
                    end
                end
                4'b0001: begin // start bit received
                    data_reg[0] <= rx_data;
                    state_reg <= 4'b0010;
                end
                4'b0010: begin // data bits received
                    data_reg[bit_count_reg] <= rx_data;
                    bit_count_reg <= bit_count_reg + 1;
                    parity_reg <= parity_reg ^ rx_data;
                    if (bit_count_reg == NumDataBits-1) begin
                        state_reg <= 4'b0011;
                        bit_count_reg <= 3'b000;
                        stop_bit_count_reg <= 2'b00;
                    end
                end
                4'b0011: begin // parity bit received
                    if (ParityType == 1) begin
                        if (rx_data != parity_reg) begin
                            state_reg <= 4'b0000;
                            rx_interrupt <= 1'b1;
                        end else begin
                            state_reg <= 4'b0100;
                            stop_bit_count_reg <= 2'b00;
                        end
                    end else begin
                        state_reg <= 4'b0100;
                        stop_bit_count_reg <= 2'b00;
                    end
                end
                4'b0100: begin // stop bits received
                    stop_bit_count_reg <= stop_bit_count_reg + 1;
                    if (stop_bit_count_reg == NumStopBits) begin
                        state_reg <= 4'b0000;
                        rx_interrupt <= 1'b1;
                    end
                end
            endcase
        end
    end

    always @(posedge tx_clk) begin
        if (reset) begin
            state_reg <= 4'b0000;
            bit_count_reg <= 3'b000;
            stop_bit_count_reg <= 2'b00;
            tx_busy_reg <= 1'b0;
            tx_interrupt <= 1'b0;
        end else begin
            case (state_reg)
                4'b0000: begin // idle state
                    if (TXEnable && tx_en && !tx_busy_reg) begin
                        state_reg <= 4'b0001;
                        bit_count_reg <= 3'b000;
                        stop_bit_count_reg <= 2'b00;
                        tx_data <= 1'b0;
                        tx_busy_reg <= 1'b1;
                    end
                end
                4'b0001: begin // start bit transmitted
                    tx_data <= 1'b0;
                    state_reg <= 4'b0010;
                end
                4'b0010: begin // data bits transmitted
                    tx_data <= data_reg[bit_count_reg];
                    bit_count_reg <= bit_count_reg + 1;
                    if (bit_count_reg == NumDataBits-1) begin
                        state_reg <= 4'b0011;
                        bit_count_reg <= 3'b000;
                        stop_bit_count_reg <= 2'b00;
                    end
                end
                4'b0011: begin // parity bit transmitted
                    if (ParityType == 1) begin
                        tx_data <= parity_reg;
                        state_reg <= 4'b0100;
                        stop_bit_count_reg <= 2'b00;
                    end else begin
                        state_reg <= 4'b0100;
                        stop_bit_count_reg <= 2'b00;
                    end
                end
                4'b0100: begin // stop bits transmitted
                    tx_data <= 1'b1;
                    stop_bit_count_reg <= stop_bit_count_reg + 1;
                    if (stop_bit_count_reg == NumStopBits) begin
                        state_reg <= 4'b0000;
                        tx_busy_reg <= 1'b0;
                        tx_interrupt <= 1'b1;
                    end
                end
            endcase
        end
    end

    assign rx_clk = clock;
    assign tx_clk = clock;
    assign tx = tx_busy_reg;
    assign rts_n = 1'b1;

endmodule

