reg pwm_out;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        counter <= 16'b0;
        pwm_out <= 1'b0;
    end else begin
        if (counter < period - 1) begin
            counter <= counter + 1;
        end else begin
            counter <= 16'b0;
        end

        if (counter < duty_cycle) begin
            pwm_out <= 1'b1;
        end else begin
            pwm_out <= 1'b0;
        end
    end
end

