  reg [3:0] reset_counter;
  wire [7:0] mux_output;

  assign data_out = mux_output;

  always @(posedge clk, negedge reset) begin
    if (!reset) begin
      reg_data <= 8'b0;
      reset_counter <= 4'b0;
    end else begin
      reg_data <= reg_data;
      reset_counter <= reset_counter + 1;
    end
