module ADC (
  input clk,
  input start,
  input [7:0] analog_in,
  output reg [7:0] digital_out
);

  reg [7:0] approx_val;
  reg [7:0] comp_val;
  reg [2:0] bit_num;

  always @(posedge clk) begin
    if (start) begin
      bit_num <= 2'b00;
      approx_val <= 8'b00000000;
      comp_val <= {1'b1, approx_val[6:0]};
    end else begin
      if (bit_num < 3) begin
        if (analog_in > comp_val) begin
          approx_val[bit_num+1] <= 1'b1;
        end else begin
          approx_val[bit_num+1] <= 1'b0;
        end
        bit_num <= bit_num + 1;
        comp_val <= {comp_val[7:1], approx_val[bit_num], 1'b0};
      end else begin
        digital_out <= approx_val;
      end
    end
  end

endmodule

