module top_module (
    input [7:0] a, b, // 8-bit 2's complement inputs
    input [7:0] a1, b1, c1, d1, // 4 unsigned 8-bit binary inputs
    output [7:0] s, // 8-bit 2's complement sum output
    output [7:0] min // 8-bit minimum value output
);

    // Carry-lookahead adder to add two 8-bit 2's complement numbers
    wire [8:0] sum;
    wire [8:0] carry;
    cla_adder adder(.a(a), .b(b), .sum(sum), .carry(carry));

    // Priority encoder to determine the highest priority input value among the four unsigned 8-bit binary numbers
    wire [1:0] priority;
    priority_encoder encoder(.a({a1, b1, c1, d1}), .priority(priority));

    // 2-to-1 multiplexer to compare the highest priority input value with the sum of the two 8-bit 2's complement numbers
    wire [7:0] min_value;
    wire [7:0] highest_priority_value;
    assign highest_priority_value = (priority == 2'b00) ? a1 :
                                    (priority == 2'b01) ? b1 :
                                    (priority == 2'b10) ? c1 :
                                    (priority == 2'b11) ? d1 : 8'b0;
    assign min_value = (highest_priority_value < sum) ? highest_priority_value : sum;

    // Output the sum and minimum value
    assign s = sum[7:0];
    assign min = min_value;

endmodule

// Carry-lookahead adder module
module cla_adder (
    input [7:0] a, b, // 8-bit 2's complement inputs
    output [8:0] sum, // 9-bit sum output
    output [8:0] carry // 9-bit carry output
);

    wire [7:0] g;
    wire [7:0] p;
    wire [7:0] c;

    // Generate and propagate signals
    gen_propagate gen_propagate(.a(a), .b(b), .g(g), .p(p));

    // Carry signals
    assign c[0] = 1'b0;
    assign c[1] = g[0] | (p[0] & c[0]);
    assign c[2] = g[1] | (p[1] & c[1]);
    assign c[3] = g[2] | (p[2] & c[2]);
    assign c[4] = g[3] | (p[3] & c[3]);
    assign c[5] = g[4] | (p[4] & c[4]);
    assign c[6] = g[5] | (p[5] & c[5]);
    assign c[7] = g[6] | (p[6] & c[6]);
    assign c[8] = g[7] | (p[7] & c[7]);

    // Sum signals
    assign sum[0] = a[0] ^ b[0] ^ c[0];
    assign sum[1] = a[1] ^ b[1] ^ c[1];
    assign sum[2] = a[2] ^ b[2] ^ c[2];
    assign sum[3] = a[3] ^ b[3] ^ c[3];
    assign sum[4] = a[4] ^ b[4] ^ c[4];
    assign sum[5] = a[5] ^ b[5] ^ c[5];
    assign sum[6] = a[6] ^ b[6] ^ c[6];
    assign sum[7] = a[7] ^ b[7] ^ c[7];
    assign sum[8] = c[8];

    // Carry output
    assign carry = c;

endmodule

// Generate and propagate module
module gen_propagate (
    input [7:0] a, b, // 8-bit 2's complement inputs
    output [7:0] g, // 8-bit generate output
    output [7:0] p // 8-bit propagate output
);

    assign g[0] = a[0] & b[0];
    assign p[0] = a[0] | b[0];
    assign g[1] = a[1] & b[1] | g[0] & p[0];
    assign p[1] = a[1] | b[1];
    assign g[2] = a[2] & b[2] | g[1] & p[1];
    assign p[2] = a[2] | b[2];
    assign g[3] = a[3] & b[3] | g[2] & p[2];
    assign p[3] = a[3] | b[3];
    assign g[4] = a[4] & b[4] | g[3] & p[3];
    assign p[4] = a[4] | b[4];
    assign g[5] = a[5] & b[5] | g[4] & p[4];
    assign p[5] = a[5] | b[5];
    assign g[6] = a[6] & b[6] | g[5] & p[5];
    assign p[6] = a[6] | b[6];
    assign g[7] = a[7] & b[7] | g[6] & p[6];
    assign p[7] = a[7] | b[7];

endmodule

// Priority encoder module
module priority_encoder (
    input [31:0] a, // 4 unsigned 8-bit binary inputs
    output reg [1:0] priority // 2-bit priority output
);

    always @(*) begin
        if (a[7:0] < a[15:8] && a[7:0] < a[23:16] && a[7:0] < a[31:24])
            priority = 2'b00;
        else if (a[15:8] < a[7:0] && a[15:8] < a[23:16] && a[15:8] < a[31:24])
            priority = 2'b01;
        else if (a[23:16] < a[7:0] && a[23:16] < a[15:8] && a[23:16] < a[31:24])
            priority = 2'b10;
        else
            priority = 2'b11;
    end

endmodule

