module single_port_memory
#(parameter DATA_WIDTH=16, parameter ADDR_WIDTH=4)
(
   input [(DATA_WIDTH-1):0] data,
   input [(ADDR_WIDTH-1):0] addr,
   input we, clk,
   output reg [(DATA_WIDTH-1):0] q
);

   // Declare the RAM variable
   reg [DATA_WIDTH-1:0] ram[2**ADDR_WIDTH-1:0];

   // Variable to hold the registered read address
   reg [ADDR_WIDTH-1:0] addr_reg;

   // Specify the initial contents. Use the $readmemb system task to initialize the RAM variable from a text file.
   initial 
   begin : INIT
      $readmemb("C:/altera/16.0/myProjects/PHYctrl_100Mbps/ram_init1_and.txt", ram);
   end 

   always @ (posedge clk)
   begin
      // Write
      if (we)
         ram[addr] <= data;

      addr_reg <= addr;
   end

   // Continuous assignment implies read returns NEW data.
   // This is the natural behavior of the TriMatrix memory blocks in Single Port mode.  
   assign q = ram[addr_reg];

endmodule

module transition_detector (
    input clk,
    input reset,
    input [31:0] in,
    output reg out
);

reg [31:0] in_reg;
reg [31:0] in_reg_prev;
reg [31:0] in_xor;

always @(posedge clk, posedge reset) begin
    if (reset) begin
        in_reg <= 0;
        in_reg_prev <= 0;
        in_xor <= 0;
        out <= 0;
    end else begin
        in_reg <= in;
        in_reg_prev <= in_reg;
        in_xor <= in_reg ^ in_reg_prev;
        if (in_xor != 0) begin
            out <= 1;
        end
    end
end

endmodule

