always @(posedge enable, negedge reset) begin
  if (!reset) begin
    out_data <= 4'b0000;
  end else if (enable) begin
    case (in_data)
      2'b00: out_data <= 4'b0001;
      2'b01: out_data <= 4'b0010;
      2'b10: out_data <= 4'b0100;
      2'b11: out_data <= 4'b1000;
      default: out_data <= 4'b0000;
    endcase
  end
end

endmodule

