module stratixv_dll_offset_ctrl (
    input clk,
    input [6:0] offsetdelayctrlin,
    input [6:0] offset,
    input addnsub,
    input aload,
    output [6:0] offsetctrlout,
    output [6:0] offsettestout
);

    parameter use_offset = "false";
    parameter static_offset = 0;
    parameter use_pvt_compensation = "false";

    reg [6:0] delay;
    reg [6:0] offset_value;
    reg [6:0] compensated_offset;
    reg [6:0] offset_ctrl_out;
    reg [6:0] offset_test_out;

    always @(posedge clk) begin
        if (aload) begin
            delay <= offsetdelayctrlin;
        end else begin
            if (use_offset == "true" && static_offset == 0) begin
                if (addnsub) begin
                    delay <= offsetdelayctrlin + offset_value;
                end else begin
                    delay <= offsetdelayctrlin - offset_value;
                end
            end else if (static_offset != 0) begin
                delay <= offsetdelayctrlin + static_offset;
            end else begin
                delay <= offsetdelayctrlin;
            end
        end

        if (use_pvt_compensation == "true") begin
            compensated_offset <= offset_value + (delay[6] ? 7'b1111111 : 7'b0);
            offset_ctrl_out <= delay;
            offset_test_out <= compensated_offset + delay;
        end else begin
            offset_ctrl_out <= delay;
            offset_test_out <= delay + offset_value;
        end
    end

    always @(offset) begin
        offset_value <= offset;
    end

    assign offsetctrlout = offset_ctrl_out;
    assign offsettestout = offset_test_out;

endmodule

module DmaController(input clk, input ce, input reset,
                     input odd_cycle,               // Current cycle even or odd?
                     input sprite_trigger,          // Sprite DMA trigger?
                     input dmc_trigger,             // DMC DMA trigger?
                     input cpu_read,                // CPU is in a read cycle?
                     input [7:0] data_from_cpu,     // Data written by CPU?
                     input [7:0] data_from_ram,     // Data read from RAM?
                     input [15:0] dmc_dma_addr,     // DMC DMA Address
                     output [15:0] aout,            // Address to access
                     output aout_enable,            // DMA controller wants bus control
                     output read,                   // 1 = read, 0 = write
                     output [7:0] data_to_ram,      // Value to write to RAM
                     output dmc_ack,                // ACK the DMC DMA
                     output pause_cpu);             // CPU is paused
  reg dmc_state;
  reg [1:0] spr_state;
  reg [7:0] sprite_dma_lastval;
  reg [15:0] sprite_dma_addr;     // sprite dma source addr
  wire [8:0] new_sprite_dma_addr = sprite_dma_addr[7:0] + 8'h01;
  always @(posedge clk) if (reset) begin
    dmc_state <= 0;
    spr_state <= 0;    
    sprite_dma_lastval <= 0;
    sprite_dma_addr <= 0;
  end else if (ce) begin
    if (dmc_state == 0 && dmc_trigger && cpu_read && !odd_cycle) dmc_state <= 1;
    if (dmc_state == 1 && !odd_cycle) dmc_state <= 0;

    if (sprite_trigger) begin sprite_dma_addr <= {data_from_cpu, 8'h00}; spr_state <= 1; end
    if (spr_state == 1 && cpu_read && odd_cycle) spr_state <= 3;
    if (spr_state[1] && !odd_cycle && dmc_state == 1) spr_state <= 1;
    if (spr_state[1] && odd_cycle) sprite_dma_addr[7:0] <= new_sprite_dma_addr[7:0];
    if (spr_state[1] && odd_cycle && new_sprite_dma_addr[8]) spr_state <= 0;
    if (spr_state[1]) sprite_dma_lastval <= data_from_ram;
  end
  assign pause_cpu = (spr_state[0] || dmc_trigger) && cpu_read;
  assign dmc_ack   = (dmc_state == 1 && !odd_cycle);
  assign aout_enable = dmc_ack || spr_state[1];
  assign read = !odd_cycle;
  assign data_to_ram = sprite_dma_lastval;
  assign aout = dmc_ack ? dmc_dma_addr : !odd_cycle ? sprite_dma_addr : 16'h2004;
endmodule

module bitwise_operations (
  input wire [7:0] in1,
  input wire [7:0] in2,
  input wire mode,
  output wire [7:0] out_and,
  output wire [7:0] out_or,
  output wire [7:0] out_xor,
  output wire [7:0] gray_code
);

  // Binary to Gray code converter
  assign gray_code = in1 ^ (in1 >> 1);

  // Multiplexer for selecting the operation
  wire [7:0] mux_out;
  assign mux_out = (mode) ? (in1 & in2) : ((mode) ? (in1 | in2) : (in1 ^ in2));

  // Full adder for performing the selected operation
  wire [7:0] and_out, or_out, xor_out;
  wire carry_in;
  assign carry_in = 1'b0;
  genvar i;
  generate
    for (i = 0; i < 8; i = i + 1) begin : full_adder_loop
      full_adder fa(
        .a(in1[i]),
        .b(in2[i]),
        .cin(carry_in),
        .sum(mux_out[i]),
        .cout(carry_in)
      );
      assign and_out[i] = in1[i] & in2[i];
      assign or_out[i] = in1[i] | in2[i];
      assign xor_out[i] = in1[i] ^ in2[i];
    end
  endgenerate

  // Output the selected operation
  assign out_and = and_out;
  assign out_or = or_out;
  assign out_xor = xor_out;

