module fsm(
    input clk,
    input rst,
    input rxd,
    output [7:0] data,
    output received
    );

    localparam IDLE = 2'b00;
    localparam RECV = 2'b01;
    localparam DONE = 2'b10;

    reg [1:0] state = IDLE;
    reg [7:0] tmp_data = 8'b0;
    reg tmp_received = 1'b0;
    reg [2:0] index;
    reg [1:0] rxd_hist = 2'b11;

    always @(posedge clk)
    begin
        if (rst)
        begin
            tmp_data = 8'b0;
            tmp_received = 1'b0;
            rxd_hist = 2'b11;
            state = IDLE;
        end

        case(state)
        IDLE:
            if(rxd_hist == 2'b11 && rxd == 1'b0)
            begin
                rxd_hist = 2'b10;
                state = RECV;
                index = 3'b000;
            end
        RECV:
            begin
                tmp_data[index] = rxd;
                index = index + 1;
                if (index == 3'b100)
                begin
                    tmp_received = 1'b1;
                    state = DONE;
                    index = 3'b000;
                end
            end
        DONE:
            begin
                tmp_received = 1'b0;
                data = tmp_data;
                tmp_data = 8'b0;
                state = IDLE;
            end
        endcase

        if (state == IDLE) rxd_hist = {rxd_hist[0], rxd};
    end

    assign received = tmp_received;

endmodule

