        .iomem_wdata(iomem_wdata),
        .iomem_rdata(iomem_rdata)
    );

    // External memory interface
    always @(posedge clk_buf) begin
        if (!resetn) begin
            iomem_ready <= 0;
            iomem_rdata <= 0;
