                if (iomem_wstrb[0]) gpio[7:0] <= iomem_wdata[7:0];
                if (iomem_wstrb[1]) gpio[15:8] <= iomem_wdata[15:8];
            end else begin
                iomem_ready <= 0;
            end
        end
    end

    // Update LEDs from switches
    always @(posedge clk_buf) begin
        if (!resetn) begin
            gpio <= 0;
        end else begin
            gpio[15:0] <= sw;
        end
    end

