module fifo(clk, rst, clr,  din, we, dout, re, full, empty);

parameter DW = 8;           // data width
parameter DEPTH = 4;        // depth of the FIFO

input		clk, rst;
input		clr;
input   [DW-1:0]	din;
input		we;             // write enable
output  [DW-1:0]	dout;
input		re;             // read enable
output		full, empty;

reg     [DW-1:0]	mem[0:DEPTH-1];
reg     [1:0]   wp;         // write pointer
reg     [1:0]   rp;         // read pointer
wire    [1:0]   wp_p1;      // write pointer + 1
wire    [1:0]   rp_p1;      // read pointer + 1
wire		full, empty;

always @(posedge clk or negedge rst)
    if(!rst) wp <= 2'h0;
    else if(clr) wp <= 2'h0;
    else if(we && !full) wp <= wp_p1;

assign wp_p1 = wp + 2'h1;

always @(posedge clk or negedge rst)
    if(!rst) rp <= 2'h0;
    else if(clr) rp <= 2'h0;
    else if(re && !empty) rp <= rp_p1;

assign rp_p1 = rp + 2'h1;

// Fifo Output
assign  dout = mem[ rp ];

// Fifo Input
always @(posedge clk)
    if(we && !full) mem[ wp ] <= din;

// Status
assign empty = (wp == rp);
assign full  = ((wp_p1 == rp) && we);

endmodule

