module PLL (
  input ref_clk,
  input fb_clk,
  output clk,
  output phase_diff
);

parameter N = 2; // multiplication factor
parameter M = 1; // division factor

reg [31:0] phase_accumulator = 0;
reg locked = 0;

// Frequency multiplication function
function [31:0] freq_mult;
  input [31:0] freq_in;
  begin
    freq_mult = freq_in * N;
  end
endfunction

// Frequency division function
function [31:0] freq_div;
  input [31:0] freq_in;
  begin
    freq_div = freq_in / M;
  end
endfunction

// Phase detector function
function [31:0] phase_detector;
  input [31:0] freq_in1, freq_in2;
  begin
    phase_detector = freq_in1 - freq_in2;
  end
endfunction

// Implementation of the PLL circuit
always @(posedge ref_clk or posedge fb_clk) begin
  // Multiply the reference clock signal by N
  phase_accumulator <= phase_accumulator + freq_mult(ref_clk);

  // Divide the output of the frequency multiplier by M
  if (phase_accumulator >= freq_div(fb_clk)) begin
    phase_accumulator <= phase_accumulator - freq_div(fb_clk);
    locked <= 1;
  end else begin
    locked <= 0;
  end

  // Compare the phase of the locked clock signal with the phase of the feedback clock signal
  phase_diff <= phase_detector(phase_accumulator, freq_div(fb_clk));

  // Generate the locked clock signal
  clk <= locked;
end

endmodule

module sum_threshold (
  input [31:0] in_word,
  input [15:0] threshold,
  output reg [15:0] out_word,
  output reg threshold_exceeded
);

  reg [15:0] upper_half;
  reg [15:0] lower_half;
  reg [15:0] sum;

  // Split input word into upper and lower halves
  assign upper_half = in_word[31:16];
  assign lower_half = in_word[15:0];

  // Calculate sum of upper and lower halves
  always @* begin
    sum = upper_half + lower_half;
  end

  // Compare sum to threshold value
  always @* begin
    if (sum > threshold) begin
      threshold_exceeded = 1;
    end else begin
      threshold_exceeded = 0;
    end
  end

  // Assign output word to sum
  assign out_word = sum;

endmodule

