endmodule
module encoder (
  input [k-1:0] in,
  output [n-1:0] out
);

parameter k = 128;
parameter n = 256;
parameter m = 8;

reg [k-1:0] data_bits;
reg [n-1:0] encoded_bits;

// Recursive Systematic Convolutional Code with generator polynomial 13/15
reg [m-1:0] state_reg;
reg [m-1:0] next_state_reg;
reg [1:0] output_reg;
reg [1:0] next_output_reg;

// Puncturing
parameter [3:0] puncture_pattern = 4'b1010; // Discard every other parity bit
reg [3:0] puncture_counter = 4'b0000;
reg [1:0] puncture_mask = 2'b11;

always @(posedge clk) begin
  data_bits <= in;
end

always @(posedge clk) begin
  state_reg <= {state_reg[m-2:0], data_bits[k-1], data_bits[k-2]};
  next_state_reg[0] = state_reg[m-1] ^ state_reg[m-2] ^ data_bits[k-1];
  next_state_reg[1] = state_reg[m-1] ^ state_reg[m-2] ^ data_bits[k-2];
  next_state_reg[m-1:2] = state_reg[m-3:0];

  output_reg[0] = state_reg[m-1] ^ state_reg[m-2] ^ state_reg[m-3] ^ state_reg[m-4] ^ data_bits[k-1] ^ data_bits[k-2];
  output_reg[1] = state_reg[m-1] ^ state_reg[m-3] ^ state_reg[m-4] ^ data_bits[k-1];

  next_output_reg[0] = next_state_reg[m-1] ^ next_state_reg[m-2] ^ next_state_reg[m-3] ^ next_state_reg[m-4] ^ data_bits[k-1] ^ data_bits[k-2];
  next_output_reg[1] = next_state_reg[m-1] ^ next_state_reg[m-3] ^ next_state_reg[m-4] ^ data_bits[k-1];

  if (puncture_counter == puncture_pattern) begin
    encoded_bits[n-1] <= 0;
    puncture_mask <= ~puncture_mask;
  end else begin
    encoded_bits[n-1] <= output_reg[puncture_mask];
  end

  puncture_counter <= puncture_counter + 1;
  state_reg <= next_state_reg;
  output_reg <= next_output_reg;
  encoded_bits[n-2:0] <= {output_reg[puncture_mask], encoded_bits[n-2:1]};
end

endmodule

