module increment_signed(A, CI, Z);
  input signed [15:0] A;
  input CI;
  output signed [16:0] Z;

  wire signed [15:0] A_abs;
  wire signed [15:0] A_abs_inverted;
  wire [16:0] Z_abs;
  wire [16:0] Z_abs_inverted;
  wire CO;

  // Convert A to its absolute value
  assign A_abs = (A < 0) ? (~A + 1) : A;

  // Set the carry-in signal based on the sign of A
  assign CO = (A < 0) ? 1'b1 : CI;

  // Increment the absolute value of A by 1
  ripple_carry_adder_16bit rca(.A(A_abs), .B(16'b1), .CI(CO), .S(Z_abs));

  // Convert the result back to its signed form
  assign Z_abs_inverted = (Z_abs == 17'b0) ? 17'b0 : (~Z_abs + 1);
  assign Z = (A < 0) ? Z_abs_inverted : Z_abs;

endmodule

// 16-bit ripple carry adder module
module ripple_carry_adder_16bit(A, B, CI, S);
  input signed [15:0] A;
  input signed [15:0] B;
  input CI;
  output signed [16:0] S;

  wire [15:0] S_15_0;
  wire [15:0] C_15_0;
  wire C_16;

  // Generate the sum and carry bits for each bit position
  genvar i;
  generate
    for (i = 0; i < 16; i = i + 1) begin : gen_adder
      full_adder fa(.A(A[i]), .B(B[i]), .CI(CI), .CO(C_15_0[i]), .S(S_15_0[i]));
      assign CI = C_15_0[i];
    end
  endgenerate

  // Propagate the carry bit to the most significant bit
  assign C_16 = C_15_0[15];

  // Combine the sum and carry bits to form the final result
  assign S = {C_16, S_15_0};

endmodule

