module matrix_multiplier (
    input clk,
    input reset,
    input signed [15:0] A [0:0],
    input signed [15:0] B [0:0],
    output signed [31:0] C [0:0]
);

parameter M = 1;
parameter N = 1;
parameter P = 1;

localparam BITS = 16;
localparam BITS_2 = BITS * 2;

reg [BITS_2-1:0] C_reg [0:M-1][0:P-1];
reg [BITS-1:0] A_reg [0:M-1][0:N-1], B_reg [0:N-1][0:P-1];
reg [BITS_2-1:0] C_temp [0:M-1][0:P-1];

integer i, j, k;
always @ (posedge clk) begin
    if (reset) begin
        for (i = 0; i < M; i = i + 1) begin
            for (j = 0; j < P; j = j + 1) begin
                C_reg[i][j] <= 0;
            end
        end
    end else begin
        for (i = 0; i < M; i = i + 1) begin
            for (j = 0; j < P; j = j + 1) begin
                C_temp[i][j] = 0;
                for (k = 0; k < N; k = k + 1) begin
                    C_temp[i][j] = C_temp[i][j] + A_reg[i][k] * B_reg[k][j];
                end
            end
        end
        for (i = 0; i < M; i = i + 1) begin
            for (j = 0; j < P; j = j + 1) begin
                C_reg[i][j] <= C_temp[i][j];
            end
        end
    end
end

assign C = C_reg;

always @ (posedge clk) begin
    if (reset) begin
        for (i = 0; i < M; i = i + 1) begin
            for (j = 0; j < N; j = j + 1) begin
                A_reg[i][j] <= 0;
            end
        end
        for (i = 0; i < N; i = i + 1) begin
            for (j = 0; j < P; j = j + 1) begin
                B_reg[i][j] <= 0;
            end
        end
    end else begin
        for (i = 0; i < M; i = i + 1) begin
            for (j = 0; j < N; j = j + 1) begin
                A_reg[i][j] <= A[i][j];
            end
        end
        for (i = 0; i < N; i = i + 1) begin
            for (j = 0; j < P; j = j + 1) begin
                B_reg[i][j] <= B[i][j];
            end
        end
    end
end

endmodule

