    input MBC_ISOLATE,

    // Layer Ctrl --> MBus Ctrl
    input [`MBUS_ADDR_WIDTH-1:0] TX_ADDR_uniso, 
    input [`MBUS_DATA_WIDTH-1:0] TX_DATA_uniso, 
    input TX_PEND_uniso, 
    input TX_REQ_uniso, 
