            LRC_SLEEP      = LRC_SLEEP_uniso;
            LRC_CLKENB     = LRC_CLKENB_uniso;
            LRC_RESET      = LRC_RESET_uniso;
            LRC_ISOLATE    = LRC_ISOLATE_uniso;
            TX_ADDR        = TX_ADDR_uniso;
