module add_sub (
    input [3:0] a,
    input [3:0] b,
    input sub,
    input cin,
    output reg cout,
    output reg overflow,
    output reg [3:0] sum
);

    reg [4:0] temp_sum;
    reg [4:0] temp_a;
    reg [4:0] temp_b;
    reg temp_sub;

    always @(*) begin
        temp_a = {1'b0, a};
        temp_b = {1'b0, b};
        temp_sub = sub;
        if (cin) temp_sum[0] = 1'b1;
        else temp_sum[0] = 1'b0;
        if (temp_sub) begin
            temp_b = ~temp_b + 1;
        end
        temp_sum = temp_a + temp_b + cin;
        if (temp_sum[4] != temp_sum[3]) overflow = 1'b1;
        else overflow = 1'b0;
        sum = temp_sum[3:0];
        cout = temp_sum[4];
    end

endmodule

module xlr8_float_add1 (
    input  wire        clk,    //    clk.clk
    input  wire        areset, // areset.reset
    input  wire [0:0]  en,     //     en.en
    input  wire [31:0] a,      //      a.a
    input  wire [31:0] b,      //      b.b
    output wire [31:0] q       //      q.q
);

    // Extracting sign, exponent, and mantissa from input a
    wire a_sign = a[31];
    wire a_exponent = a[30:23];
    wire a_mantissa = a[22:0];

    // Extracting sign, exponent, and mantissa from input b
    wire b_sign = b[31];
    wire b_exponent = b[30:23];
    wire b_mantissa = b[22:0];

    // Initializing variables for the result
    wire [31:0] result;
    wire result_sign;
    wire result_exponent;
    wire result_mantissa;

    // Performing the addition operation only when enable input is asserted
    always @(posedge clk, negedge areset) begin
        if (!areset) begin
            result <= 32'h0;
        end else if (en) begin
            // Performing the addition operation according to IEEE 754 standard
            if (a_exponent > b_exponent) begin
                result_exponent = a_exponent;
                a_mantissa = {1'b1, a_mantissa};
                b_mantissa = {1'b0, b_mantissa};
                b_mantissa = b_mantissa >> (a_exponent - b_exponent);
            end else begin
                result_exponent = b_exponent;
                b_mantissa = {1'b1, b_mantissa};
                a_mantissa = {1'b0, a_mantissa};
                a_mantissa = a_mantissa >> (b_exponent - a_exponent);
            end
            result_mantissa = a_mantissa + b_mantissa;
            if (result_mantissa[24]) begin
                result_exponent = result_exponent + 1;
                result_mantissa = result_mantissa >> 1;
            end
            result_sign = a_sign;
            if (result_mantissa[23]) begin
                result_mantissa = result_mantissa >> 1;
                result_mantissa[22:0] = result_mantissa[22:0] + 1;
                if (result_mantissa[23] && result_exponent == 0) begin
                    result_exponent = result_exponent + 1;
                end
            end
            result[31] = result_sign;
            result[30:23] = result_exponent;
            result[22:0] = result_mantissa[22:0];
        end
    end

    assign q = result;

endmodule

module top_module (
    input clk,
    input reset,
    input [3:0] A,
    input [3:0] B,
    input [31:0] data_in,
    input [4:0] shift_amt,
    input select, // Select input to choose between addition and shifting
    output [31:0] result
);

    wire [3:0] adder_out;
    wire [31:0] shifted_out;
    wire mode_select;

    // Instantiate the ripple carry adder module
    ripple_carry_adder adder_inst (
        .clk(clk),
        .reset(reset),
        .A(A),
        .B(B),
        .sum(adder_out)
    );

    // Instantiate the barrel shifter module
    barrel_shifter shifter_inst (
        .data_in(adder_out),
        .shift_amt(shift_amt),
        .shifted_out(shifted_out)
    );

    // Control logic to select between addition and shifting modes
    assign mode_select = select;

    // Output the result based on the selected mode
    always @(*) begin
        if (mode_select == 0) begin
            result = adder_out;
        end else begin
            result = shifted_out;
        end
    end

endmodule

// Ripple carry adder module
module ripple_carry_adder (
    input clk,
    input reset,
    input [3:0] A,
    input [3:0] B,
    output reg [3:0] sum
);

    always @(posedge clk, posedge reset) begin
        if (reset) begin
            sum <= 4'b0;
        end else begin
            sum <= A + B;
        end
    end

endmodule

// Barrel shifter module
module barrel_shifter (
    input [31:0] data_in,
    input [4:0] shift_amt,
    output [31:0] shifted_out
);

    assign shifted_out = (shift_amt[4]) ? {32{data_in[31]}} :
                        (shift_amt[3]) ? {data_in[31], data_in[31:1]} :
                        (shift_amt[2]) ? {data_in[31:2], data_in[1:0]} :
                        (shift_amt[1]) ? {data_in[31:3], data_in[2:0]} :
                        {data_in[31:4], data_in[3:0]};

endmodule

module priority_encoder_mux (
    input [7:0] a, b, c, d,
    output reg [7:0] min_value );

    always @(*) begin
        if (a <= b && a <= c && a <= d) begin
            min_value = a;
        end else if (b <= a && b <= c && b <= d) begin
            min_value = b;
        end else if (c <= a && c <= b && c <= d) begin
            min_value = c;
        end else begin
            min_value = d;
        end
    end

endmodule

module d_flip_flop (
    input clk,
    input d,
    output reg q );

    reg j, k;

    always @(posedge clk) begin
        j <= d;
        k <= ~d;
        q <= j ^ (q & k);
    end

endmodule

module final_module (
    input [7:0] min_value,
    input d,
    output reg [7:0] final_output );

    always @(min_value or d) begin
        if (d == 1) begin
            final_output = d;
        end else begin
            final_output = min_value;
        end
    end

endmodule

module top_module (
    input clk,
    input reset,
    input [7:0] a, b, c, d,
    output reg q );

    wire [7:0] min_value;
    wire [7:0] final_output;

    priority_encoder_mux pem (
        .a(a),
        .b(b),
        .c(c),
        .d(d),
        .min_value(min_value)
    );

    d_flip_flop dff (
        .clk(clk),
        .d(q),
        .q(q)
    );

    final_module fm (
        .min_value(min_value),
        .d(q),
        .final_output(final_output)
    );

    always @(posedge clk) begin
        if (reset) begin
            q <= 0;
        end else begin
            q <= final_output;
        end
    end

endmodule

module nand_mux_4to1 (
    input [3:0] A,
    input [1:0] S,
    output reg out
);

reg [3:0] stage1_out;
reg [3:0] stage2_out;

// Stage 1
assign stage1_out[0] = ~(A[0] & S[0]);
assign stage1_out[1] = ~(A[1] & S[0]);
assign stage1_out[2] = ~(A[2] & S[0]);
assign stage1_out[3] = ~(A[3] & S[0]);

// Stage 2
assign stage2_out[0] = ~(stage1_out[0] & S[1]);
assign stage2_out[1] = ~(stage1_out[1] & S[1]);
assign stage2_out[2] = ~(stage1_out[2] & S[1]);
assign stage2_out[3] = ~(stage1_out[3] & S[1]);

// Output
assign out = stage2_out[0] & stage2_out[1] & stage2_out[2] & stage2_out[3];

endmodule

