module Modulo (
  input [n-1:0] a,
  input [n-1:0] b,
  output [n-1:0] rem
);

parameter n = 4; // number of bits in input signals

reg [n-1:0] dividend;
reg [n-1:0] divisor;
reg [n-1:0] quotient;
reg [n-1:0] remainder;

always @(*) begin
  dividend = a;
  divisor = b;

  // Perform division operation
  quotient = 0;
  while (dividend >= divisor) begin
    dividend = dividend - divisor;
    quotient = quotient + 1;
  end

  // Compute remainder using modulo operator
  remainder = dividend;
end

assign rem = remainder;

endmodule

