module bcd_counter (
    input clk,
    input reset,
    output reg [3:1] ena,
    output reg [15:0] q
);

    // Define states
    parameter IDLE = 2'b00;
    parameter INC_ONES = 2'b01;
    parameter INC_TENS = 2'b10;
    parameter INC_HUNDREDS = 2'b11;

    // Define current state and next state
    reg [1:0] state, next_state;

    // Define counter for ones, tens, and hundreds digits
    reg [3:0] ones, tens, hundreds;

    // Define enable signal for each digit
    reg ena_ones, ena_tens, ena_hundreds;

    // Assign initial values
    assign q = {hundreds, tens, ones};
    assign ena = {ena_hundreds, ena_tens, ena_ones};

    // Define state transition and output logic
    always @(posedge clk, posedge reset) begin
        if (reset) begin
            state <= IDLE;
            ones <= 0;
            tens <= 0;
            hundreds <= 0;
            ena_ones <= 0;
            ena_tens <= 0;
            ena_hundreds <= 0;
        end
        else begin
            state <= next_state;
            ones <= ones + 1;
            case (state)
                IDLE: begin
                    ena_ones <= 0;
                    ena_tens <= 0;
                    ena_hundreds <= 0;
                    next_state <= IDLE;
                end
                INC_ONES: begin
                    ena_ones <= 1;
                    ena_tens <= 0;
                    ena_hundreds <= 0;
                    if (ones == 9) begin
                        next_state <= INC_TENS;
                        ones <= 0;
                    end
                    else begin
                        next_state <= INC_ONES;
                    end
                end
                INC_TENS: begin
                    ena_ones <= 0;
                    ena_tens <= 1;
                    ena_hundreds <= 0;
                    if (tens == 9) begin
                        next_state <= INC_HUNDREDS;
                        tens <= 0;
                    end
                    else begin
                        next_state <= INC_TENS;
                    end
                end
                INC_HUNDREDS: begin
                    ena_ones <= 0;
                    ena_tens <= 0;
                    ena_hundreds <= 1;
                    if (hundreds == 9) begin
                        next_state <= IDLE;
                        hundreds <= 0;
                    end
                    else begin
                        next_state <= INC_HUNDREDS;
                    end
                end
            endcase
        end
    end

endmodule

