    if(!rst_n) begin
        count <= 0;
        pulse <= 0;
        done <= 0;
    end
    else begin
        if(count < duration) begin
            count <= count + 1;
            pulse <= 1;
            done <= 0;
        end
        else begin
            count <= 0;
            pulse <= 0;
            done <= 1;
        end
    end
end

