    2'b00: begin
      q_int <= data;
      q_bar_int <= ~data;
      state <= 2'b01;
    end
    2'b10: begin
      q_int <= data;
      q_bar_int <= ~data;
      state <= 2'b11;
    end
    default: state <= 2'b00;
  endcase
