module barrel_shifter (
  input clk,
  input reset,            // Synchronous active-high reset
  input load,             // Synchronous load
  input left_enable,      // Enable for left shift
  input right_enable,     // Enable for right shift
  input [4:0] shift_amt,  // Number of bits to shift
  input [3:0] in,         // Input to be shifted
  output [7:0] out        // Output after shifting
);

reg [7:0] shift_reg;

always @(posedge clk) begin
  if (reset) begin
    shift_reg <= 8'b0;
  end else if (load) begin
    shift_reg <= {in, 4'b0};
  end else if (left_enable) begin
    shift_reg <= {shift_reg[3:0], shift_reg[7:4]};
  end else if (right_enable) begin
    shift_reg <= {shift_reg[7:4], shift_reg[3:0]};
  end else begin
    shift_reg <= shift_reg;
  end
end

assign out = shift_reg;

endmodule

