  output [0:0]Res;

  wire [0:0]not_Op1;
  wire [0:0]not_Op2;
  wire [0:0]and_result;
  wire [0:0]or_result;
  wire [0:0]not_and_result;

  assign not_Op1 = ~Op1;
  assign not_Op2 = ~Op2;
  assign and_result = Op1 & Op2;
  assign or_result = Op1 | Op2;
  assign not_and_result = ~(Op1 & Op2);

  assign Res = (not_Op1 & Op2) | (Op1 & not_Op2) | not_and_result;

endmodule

module rotator(
    input clk,
    input [99:0] data,
    input [4:0] rot_amt,
    input load,
    input left_en,
    input right_en,
    output reg [99:0] q
);

reg [99:0] temp;
reg [99:0] shifted_data;

always @(posedge clk) begin
    if (load) begin
        temp <= data;
    end else begin
        if (left_en) begin
            shifted_data = {temp[rot_amt-1:0], temp[99:rot_amt]};
        end else if (right_en) begin
            shifted_data = {temp[(100-rot_amt-1):99], temp[0:(100-rot_amt-1)]};
        end else begin
            shifted_data = temp;
        end
        temp <= shifted_data;
    end
end

assign q = temp;

endmodule

module byte_reorder(
    input [31:0] in,
    output reg [15:0] out
);

    always @(*) begin
        out[15:8] = in[7:0];
        out[7:0] = in[15:8];
    end

endmodule

module subtractor(
    input [15:0] in1,
    input [15:0] in2,
    output reg [15:0] out
);

    always @(*) begin
        out = in1 - in2;
    end

endmodule

module control_logic(
    input select,
    input [31:0] in,
    input [15:0] in1,
    input [15:0] in2,
    output reg [15:0] out,
    output reg [15:0] byte_reorder_out,
    output reg [1:0] control
);

    wire [15:0] subtractor_out;
    wire [15:0] byte_reorder_out_internal;

    byte_reorder byte_reorder_inst(
        .in(in),
        .out(byte_reorder_out_internal)
    );

    subtractor subtractor_inst(
        .in1(in1),
        .in2(in2),
        .out(subtractor_out)
    );

    always @(*) begin
        if (select == 1'b0) begin
            out = subtractor_out;
            byte_reorder_out = 16'b0;
            control = 2'b01;
        end else begin
            out = 16'b0;
            byte_reorder_out = byte_reorder_out_internal;
            control = 2'b10;
        end
    end

endmodule

module top_module( 
    input clk,
    input reset,
    input [15:0] in1,
    input [15:0] in2,
    input select,
    input [31:0] in,
    output reg led
);

    wire [15:0] subtractor_out;
    wire [15:0] byte_reorder_out;
    wire [1:0] control;

    control_logic control_logic_inst(
        .select(select),
        .in(in),
        .in1(in1),
        .in2(in2),
        .out(subtractor_out),
        .byte_reorder_out(byte_reorder_out),
        .control(control)
    );

    assign led = (control == 2'b01 && subtractor_out > 16'h7FFF) || (control == 2'b10 && byte_reorder_out > 16'h7FFF);

endmodule

module CDC_synchronizer (
  input Din,
  input Clk_src,
  input Clk_dst,
  input Rst,
  output reg Dout
);

  reg [1:0] ff1;
  reg [1:0] ff2;
  reg pulse;

  always @(posedge Clk_src or negedge Rst) begin
    if (!Rst) begin
      ff1 <= 2'b0;
    end
    else begin
      ff1 <= {ff1[0], Din};
    end
  end

  always @(posedge Clk_dst or negedge Rst) begin
    if (!Rst) begin
      ff2 <= 2'b0;
      pulse <= 1'b0;
    end
    else begin
      ff2 <= {ff2[0], ff1[1]};
      pulse <= 1'b1;
    end
  end

  always @(posedge Clk_dst or negedge Rst) begin
    if (!Rst) begin
      Dout <= 1'b0;
    end
    else begin
      if (pulse) begin
        Dout <= ff2[1];
      end
    end
  end

endmodule

module uart_tx_buffer(
    input clk,
    input rst,
    input dataReady,
    input [7:0] data,
    input txBusy,
    output reg txStart,
    output reg [7:0] txData,
    output reg empty,
    output reg full
);

    parameter BUFFER_DEPTH = 64;
    parameter BUFFER_DEPTH_LOG2 = 6;

    reg [BUFFER_DEPTH_LOG2 - 1:0] wr_ptr;
    reg [BUFFER_DEPTH_LOG2 - 1:0] rd_ptr;
    reg [BUFFER_DEPTH_LOG2 - 1:0] fifo_count;
    reg [7:0] buffer [0:BUFFER_DEPTH-1];

    assign empty = (fifo_count == 0);
    assign full = (fifo_count == BUFFER_DEPTH);

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            txStart <= 0;
            txData <= 0;
            wr_ptr <= 0;
            rd_ptr <= 0;
            fifo_count <= 0;
        end else begin
            if (dataReady && !full) begin
                buffer[wr_ptr] <= data;
                wr_ptr <= wr_ptr + 1;
                fifo_count <= fifo_count + 1;
            end
            if (!txBusy && !empty) begin
                txStart <= 1;
                txData <= buffer[rd_ptr];
                rd_ptr <= rd_ptr + 1;
                fifo_count <= fifo_count - 1;
            end
        end
    end

endmodule

module fifo (
    input clk,
    input wr_en,
    input rd_en,
    input [7:0] data_in,
    output reg [7:0] data_out,
    output reg empty,
    output reg full,
    output reg [5:0] count
);

    reg [7:0] mem [63:0];
    reg [5:0] head = 6'd0;
    reg [5:0] tail = 6'd0;
    reg [5:0] next_tail;
    reg [5:0] next_head;
    reg [5:0] count_reg = 6'd0;

    // Write logic
    always @(posedge clk) begin
        if (wr_en && !full) begin
            mem[tail] <= data_in;
            next_tail = tail + 6'd1;
            if (next_tail == 6'd64) begin
                next_tail = 6'd0;
            end
        end
    end

    // Read logic
    always @(posedge clk) begin
        if (rd_en && !empty) begin
            data_out <= mem[head];
            next_head = head + 6'd1;
            if (next_head == 6'd64) begin
                next_head = 6'd0;
            end
        end
    end

    // Update head and tail pointers
    always @(posedge clk) begin
        if (wr_en && !full) begin
            tail <= next_tail;
            count_reg <= count_reg + 6'd1;
        end
        if (rd_en && !empty) begin
            head <= next_head;
            count_reg <= count_reg - 6'd1;
        end
    end

    // Update empty, full, and count signals
    always @(posedge clk) begin
        empty <= (head == tail) && (count_reg == 6'd0);
        full <= (head == tail) && (count_reg == 6'd64);
        count <= count_reg;
    end

endmodule

module bit_shift #(
    parameter integer N = 2,
    parameter integer M = 2
) (
    input [7:0] din,
    output [M-1:0] dout
);
    wire [2*M-1:0] mask = {M{1'b1}};
    assign dout = (mask << din[N-1:0]) >> M;
endmodule

module edge_detection (
    input clk,
    input reset,
    input [7:0] in_vec,
    output [7:0] out_vec
);
    reg [7:0] prev_vec;
    reg [7:0] curr_vec;

    always @(posedge clk, posedge reset) begin
        if (reset) begin
            prev_vec <= 8'b0;
            curr_vec <= 8'b0;
        end else begin
            prev_vec <= curr_vec;
            curr_vec <= in_vec;
        end
    end

    assign out_vec = prev_vec ^ curr_vec;

endmodule

module transition_capture (
    input clk,
    input reset,
    input [31:0] in_vec,
    output [31:0] out_vec
);
    reg [31:0] prev_vec;
    reg [31:0] curr_vec;

    always @(posedge clk, posedge reset) begin
        if (reset) begin
            prev_vec <= 32'b0;
            curr_vec <= 32'b0;
        end else begin
            prev_vec <= curr_vec;
            curr_vec <= in_vec;
        end
    end

    assign out_vec = (prev_vec & ~curr_vec);

endmodule

module bitwise_or (
    input [7:0] in_1,
    input [31:0] in_2,
    output [31:0] out
);
    assign out = {32{1'b0}} | {in_1, in_2};
endmodule

module top_module (
    input clk,
    input reset,
    input [7:0] in_1,
    input [31:0] in_2,
    output [7:0] out_1,
    output [31:0] out_2,
    output [31:0] final_out
);
    wire [7:0] edge_out;
    wire [31:0] trans_out;

    edge_detection edge_detect (
        .clk(clk),
        .reset(reset),
        .in_vec(in_1),
        .out_vec(edge_out)
    );

    transition_capture trans_capture (
        .clk(clk),
        .reset(reset),
        .in_vec(in_2),
        .out_vec(trans_out)
    );

    bitwise_or bit_or (
        .in_1(edge_out),
        .in_2(trans_out),
        .out(final_out)
    );

    assign out_1 = edge_out;
    assign out_2 = trans_out;

endmodule

module dff_mux (
    input clk,
    input [7:0] d,
    input [2:0] sel,
    output [7:0] q
);

reg [7:0] q_int;
reg [7:0] d_int;

always @(negedge clk) begin
    q_int <= d_int;
    d_int <= d;
end

always @(*) begin
    case (sel)
        3'b000: q = q_int[0];
        3'b001: q = q_int[1];
        3'b010: q = q_int[2];
        3'b011: q = q_int[3];
        3'b100: q = q_int[4];
        3'b101: q = q_int[5];
        3'b110: q = q_int[6];
        3'b111: q = q_int[7];
    endcase
end

endmodule

module top_module (
    input clk,
    input [7:0] d,
    output [7:0] q
);

wire [2:0] sel;
reg [7:0] d_int;

dff_mux mux_inst (
    .clk(clk),
    .d(d_int),
    .sel(sel),
    .q(q)
);

always @(posedge clk) begin
    d_int <= d;
end

endmodule

module ripple_carry_adder (
    input signed [3:0] A,
    input signed [3:0] B,
    output signed [3:0] sum,
    output carry_out
);

    wire [3:0] carry;

    assign sum = A + B;

    assign carry[0] = A[0] & B[0];
    assign carry[1] = (A[1] & B[1]) | (A[1] & carry[0]) | (B[1] & carry[0]);
    assign carry[2] = (A[2] & B[2]) | (A[2] & carry[1]) | (B[2] & carry[1]);
    assign carry[3] = (A[3] & B[3]) | (A[3] & carry[2]) | (B[3] & carry[2]);

    assign carry_out = carry[3];

endmodule

module binary_counter (
    input clk,
    input reset,
    output reg [3:0] count
);

    reg [3:0] next_count;
    reg [3:0] curr_count;

    always @ (posedge clk) begin
        if (reset) begin
            curr_count <= 4'b0000;
            count <= curr_count;
        end else begin
            next_count <= curr_count + 4'b0001;
            curr_count <= next_count;
            count <= curr_count;
        end
    end

endmodule

module flip_flop (
    Q      ,
    Q_N    ,
    D      ,
    SCD    ,
    SCE    ,
    CLK_N  ,
    SET_B  ,
    RESET_B
);

    output Q      ;
    output Q_N    ;
    input  D      ;
    input  SCD    ;
    input  SCE    ;
    input  CLK_N  ;
    input  SET_B  ;
    input  RESET_B;

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;

    reg Q;
    reg Q_N;

    always @(negedge CLK_N) begin
        if (SCD == 1'b1) begin
            Q <= 1'b0;
            Q_N <= 1'b1;
        end
        else if (SCE == 1'b1) begin
            Q <= 1'b1;
            Q_N <= 1'b0;
        end
        else if (SET_B == 1'b0) begin
            Q <= 1'b1;
            Q_N <= 1'b0;
        end
        else if (RESET_B == 1'b0) begin
            Q <= 1'b0;
            Q_N <= 1'b1;
        end
        else begin
            Q <= D;
            Q_N <= ~D;
        end
    end

endmodule

module vga_monitor #(
  parameter VGA   = 1,              // SVGA or VGA mode
  parameter IRW   = 4,              // input red   width
  parameter IGW   = 4,              // input green width
  parameter IBW   = 4,              // input blue  width
  parameter ODW   = 8,              // output width
  parameter DLY   = 3,              // delay of output active
  parameter COR   = "RGB",          // color order (RGB or BGR)
  parameter FNW   = 32,             // filename string width
  parameter FEX   = "hex",          // filename extension
  parameter FILE  = ""              // filename (without extension!)
)(
  // system
  input  wire           clk,        // clock
  // status
  input  wire           oa,         // vga output active
  input  wire [  7-1:0] f_cnt,      // frame counter (resets for every second)
  input  wire           f_start,    // frame start
  // vga data
  input  wire [IRW-1:0] r_in,     
  input  wire [IGW-1:0] g_in,
  input  wire [IBW-1:0] b_in
);


////////////////////////////////////////
// internal variables
////////////////////////////////////////

/* filename */
reg [8*FNW-1:0] filename;
/* file pointer */
integer         fp = 0;
/* enabled */
reg             en;
/* vga oa reg */
reg [DLY-1:0]   oa_r;
wire [DLY :0]   oa_w;
wire            oa_out;


////////////////////////////////////////
// initial values
////////////////////////////////////////
initial begin
  en = 0;
end


////////////////////////////////////////
// tasks
////////////////////////////////////////

/* start monitor */
task start;
begin
  en = 1;
end
endtask

/* stop monitor */
task stop;
begin
  en = 0;
end
endtask


////////////////////////////////////////
// logging
////////////////////////////////////////

/* open and close file */
always @ (posedge clk)
begin
  if (en) begin    
    if (f_start) begin
      if (fp) $fclose(fp);
      $sformat(filename, "%s_%1d.%s", FILE, f_cnt, FEX);
      fp = $fopen(filename, "w");
    end
  end else begin
    if (fp) $fclose(fp); 
  end
end

/* register vga output active */
always @ (posedge clk) oa_r <= #1 {oa_r[DLY-2:0], oa};
assign oa_w = {oa_r, oa};
assign oa_out = oa_w[DLY];

/* log data to file */
always @ (posedge clk)
begin
  if (en) begin
    if (oa_out) begin
      if (COR == "RGB") $fwrite(fp, "%02x%02x%02x\n", {r_in, {(8-IRW){1'h0}}}, {g_in, {(8-IGW){1'h0}}}, {b_in, {(8-IBW){1'h0}}});
      else              $fwrite(fp, "%02x%02x%02x\n", {b_in, {(8-IBW){1'h0}}}, {g_in, {(8-IGW){1'h0}}}, {r_in, {(8-IRW){1'h0}}});
    end
  end
end


endmodule

module profibus_master (
  input clk,
  input reset,
  input tx_en,
  input [7:0] tx_data,
  output tx_busy,
  output reg tx_complete,
  output [7:0] rx_data,
  input rx_complete,
  output reg rx_en
);

  // Define states for the state machine
  parameter IDLE = 0;
  parameter TX_START = 1;
  parameter TX_DATA = 2;
  parameter RX_START = 3;
  parameter RX_DATA = 4;

  // Define variables for the state machine
  reg [2:0] state;
  reg [7:0] tx_buffer;
  reg [7:0] rx_buffer;
  reg tx_busy_int;
  reg rx_en_int;

  // Define timing parameters
  parameter BIT_TIME = 10; // 10 clock cycles per bit
  parameter START_DELAY = 5; // 5 bit times before start bit
  parameter STOP_DELAY = 2; // 2 bit times after stop bit

  // Define counter for timing
  reg [3:0] bit_counter;

  // Define output signals
  assign tx_busy = tx_busy_int;
  assign rx_en = rx_en_int;

  always @(posedge clk) begin
    if (reset) begin
      state <= IDLE;
      tx_busy_int <= 0;
      tx_complete <= 0;
      rx_complete <= 0;
      rx_en_int <= 0;
      bit_counter <= 0;
    end
    else begin
      case (state)
        IDLE: begin
          if (tx_en) begin
            tx_buffer <= tx_data;
            tx_busy_int <= 1;
            state <= TX_START;
          end
          else if (rx_complete) begin
            rx_data <= rx_buffer;
            rx_complete <= 0;
          end
        end
        TX_START: begin
          if (bit_counter == 0) begin
            tx_en_int <= 0;
            rx_en_int <= 1;
          end
          else if (bit_counter == START_DELAY) begin
            tx_en_int <= 1;
            rx_en_int <= 0;
            bit_counter <= 0;
            state <= TX_DATA;
          end
        end
        TX_DATA: begin
          if (bit_counter == 0) begin
            tx_en_int <= 0;
            rx_en_int <= 1;
            tx_buffer <= {1'b0, tx_buffer[7:1]};
            bit_counter <= 1;
          end
          else if (bit_counter == BIT_TIME) begin
            tx_en_int <= 1;
            rx_en_int <= 0;
            bit_counter <= 0;
            if (tx_buffer == 0) begin
              state <= RX_START;
            end
            else begin
              state <= TX_DATA;
            end
          end
        end
        RX_START: begin
          if (bit_counter == 0) begin
            tx_en_int <= 0;
            rx_en_int <= 1;
          end
          else if (bit_counter == START_DELAY) begin
            tx_en_int <= 1;
            rx_en_int <= 0;
            bit_counter <= 0;
            state <= RX_DATA;
          end
        end
        RX_DATA: begin
          if (bit_counter == 0) begin
            tx_en_int <= 0;
            rx_en_int <= 1;
            rx_buffer <= {rx_buffer[6:0], rx_en_int};
            bit_counter <= 1;
          end
          else if (bit_counter == BIT_TIME) begin
            tx_en_int <= 1;
            rx_en_int <= 0;
            bit_counter <= 0;
            if (rx_buffer[7]) begin
              rx_complete <= 1;
              state <= IDLE;
            end
            else begin
              state <= RX_DATA;
            end
          end
        end
      endcase
      if (tx_busy_int && state == IDLE) begin
        tx_busy_int <= 0;
        tx_complete <= 1;
      end
      bit_counter <= bit_counter + 1;
    end
  end

endmodule

module profibus_slave (
  input clk,
  input reset,
  input [7:0] tx_data,
  output tx_busy,
  output reg tx_complete,
  output [7:0] rx_data,
  input rx_en,
  output reg rx_complete
);

  // Define states for the state machine
  parameter IDLE = 0;
  parameter TX_START = 1;
  parameter TX_DATA = 2;
  parameter RX_START = 3;
  parameter RX_DATA = 4;

  // Define variables for the state machine
  reg [2:0] state;
  reg [7:0] tx_buffer;
  reg [7:0] rx_buffer;
