  parameter STOP_DELAY = 2; // 2 bit times after stop bit

  // Define counter for timing
  reg [3:0] bit_counter;

  // Define output signals
  assign tx_busy = tx_busy_int;
  assign rx_data = rx_buffer;

  always @(posedge clk) begin
    if (reset) begin
      state <= IDLE;
      tx_busy_int <= 0;
      tx_complete <= 0;
      rx_complete <= 0;
      rx_buffer <= 0;
      bit_counter <= 0;
    end
    else begin
      case (state)
        IDLE: begin
          if (rx_en) begin
