            tx_en_int <= 0;
            rx_en_int <= 1;
            tx_buffer <= {1'b0, tx_buffer[7:1]};
            bit_counter <= 1;
          end
          else if (bit_counter == BIT_TIME) begin
            tx_en_int <= 1;
            rx_en_int <= 0;
            bit_counter <= 0;
            if (tx_buffer == 0) begin
              state <= RX_START;
            end
            else begin
              state <= TX_DATA;
            end
          end
        end
        RX_START: begin
          if (bit_counter == 0) begin
            tx_en_int <= 0;
            rx_en_int <= 1;
          end
          else if (bit_counter == START_DELAY) begin
            tx_en_int <= 1;
            rx_en_int <= 0;
            bit_counter <= 0;
            state <= RX_DATA;
          end
        end
        RX_DATA: begin
          if (bit_counter == 0) begin
            tx_en_int <= 0;
            rx_en_int <= 1;
            rx_buffer <= {rx_buffer[6:0], rx_en_int};
            bit_counter <= 1;
          end
          else if (bit_counter == BIT_TIME) begin
            tx_en_int <= 1;
            rx_en_int <= 0;
            bit_counter <= 0;
            if (rx_buffer[7]) begin
              rx_complete <= 1;
              state <= IDLE;
            end
            else begin
              state <= RX_DATA;
            end
          end
        end
      endcase
      if (tx_busy_int && state == IDLE) begin
        tx_busy_int <= 0;
        tx_complete <= 1;
      end
      bit_counter <= bit_counter + 1;
    end
  end

endmodule

module relay_decode(
    input clk,
    input reset,
    input mode,
    input data_in,
    output reg [3:0] data_out,
    output reg data_available
);

    parameter DATA_SIZE = 64;

    localparam IDLE = 2'b00, START = 2'b01, DATA = 2'b10, STOP = 2'b11;

    reg [6:0] one_counter;
    reg [6:0] zero_counter;
    reg [1:0] state;
    reg [0:0] receiving;

    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            receiving <= 1'b0;
            one_counter <= 7'b0;
            zero_counter <= 7'b0;
            data_out <= 4'h0;
            data_available <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (data_in == 1'b1) begin
                        state <= START;
                    end
                end
                START: begin
                    if (data_in == 1'b0) begin
                        state <= DATA;
                        receiving <= 1'b1;
                    end else begin
                        state <= IDLE;
                    end
                end
                DATA: begin
                    if (one_counter + zero_counter == DATA_SIZE) begin
                        if (one_counter > zero_counter) begin
                            data_out <= (mode ? 4'hf : 4'hc);
                        end else begin
                            data_out <= 4'h0;
                        end
                        data_available <= 1'b1;
                        state <= STOP;
                    end else begin
                        if (receiving) begin
                            one_counter <= one_counter + data_in;
                            zero_counter <= zero_counter + (~data_in);
                        end
                    end
                end
                STOP: begin
                    if (data_in == 1'b1) begin
                        state <= IDLE;
                        receiving <= 1'b0;
                        one_counter <= 7'b0;
                        zero_counter <= 7'b0;
                        data_out <= 4'h0;
                        data_available <= 1'b0;
                    end
                end
            endcase
        end
    end

endmodule

