module wishbone_uart(
    input CLK,
    input RST,
    input WB_CLK_I,
    input WB_RST_I,
    input WB_CYC_I,
    input WB_STB_I,
    input WB_WE_I,
    input [3:0] WB_SEL_I,
    input [31:0] WB_DAT_I,
    input UART_RX,
    output WB_ACK_O,
    output [31:0] WB_DAT_O,
    output UART_TX
    );

    // Internal signals
    reg [31:0] wb_data;
    reg wb_ack;
    reg uart_tx;
    reg [1:0] state;

    // Constants
    parameter IDLE = 2'b00;
    parameter READ_WB = 2'b01;
    parameter WRITE_WB = 2'b10;

    // Wishbone interface
    always @(posedge WB_CLK_I) begin
        if (WB_RST_I) begin
            state <= IDLE;
            wb_ack <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (WB_CYC_I && WB_STB_I && !WB_WE_I) begin
                        state <= READ_WB;
                        wb_ack <= 0;
                    end else if (WB_CYC_I && WB_STB_I && WB_WE_I) begin
                        state <= WRITE_WB;
                        wb_ack <= 0;
                    end
                end
                READ_WB: begin
                    WB_DAT_O <= wb_data;
                    wb_ack <= 1;
                    state <= IDLE;
                end
                WRITE_WB: begin
                    wb_data <= WB_DAT_I;
                    wb_ack <= 1;
                    state <= IDLE;
                end
                default: state <= IDLE;
            endcase
        end
    end

    // UART interface
    always @(posedge CLK) begin
        if (RST) begin
            state <= IDLE;
            wb_ack <= 0;
            uart_tx <= 1;
        end else begin
            case (state)
                IDLE: begin
                    if (UART_RX) begin
                        wb_data <= 0;
                        state <= READ_WB;
                    end else begin
                        wb_ack <= 0;
                        uart_tx <= 1;
                    end
                end
                READ_WB: begin
                    wb_data <= wb_data << 8 | UART_RX;
                    if (wb_data[31:24] == 8'h55) begin
                        state <= WRITE_WB;
                        wb_ack <= 0;
                    end
                end
                WRITE_WB: begin
                    UART_TX <= wb_data[7:0];
                    uart_tx <= 0;
                    if (wb_ack) begin
                        state <= IDLE;
                        wb_ack <= 0;
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end

endmodule

