module parity_flipflop (
    input clk,
    input reset,
    input [7:0] in,
    output reg [8:0] out,
    output reg error
);

    // Parity generator module
    wire [0:0] parity;
    parity_generator parity_gen (
        .in(in),
        .parity(parity)
    );

    // Dual-edge triggered flip-flop module
    reg [0:0] d;
    always @(posedge clk, negedge reset) begin
        if (~reset) begin
            d <= 1'b0;
        end else begin
            d <= parity;
        end
    end

    // Output byte with parity bit added as MSB
    always @(posedge clk, negedge reset) begin
        if (~reset) begin
            out <= 9'b0;
        end else begin
            out <= {d, in};
        end
    end

    // Error signal generation module
    always @(posedge clk, negedge reset) begin
        if (~reset) begin
            error <= 1'b0;
        end else begin
            error <= ~(d & parity);
        end
    end

endmodule

