module axis_frame_join_4(
    input clk,
    input rst,
    input [7:0] input_0_axis_tdata,
    input input_0_axis_tvalid,
    output input_0_axis_tready,
    input input_0_axis_tlast,
    input input_0_axis_tuser,
    input [7:0] input_1_axis_tdata,
    input input_1_axis_tvalid,
    output input_1_axis_tready,
    input input_1_axis_tlast,
    input input_1_axis_tuser,
    input [7:0] input_2_axis_tdata,
    input input_2_axis_tvalid,
    output input_2_axis_tready,
    input input_2_axis_tlast,
    input input_2_axis_tuser,
    input [7:0] input_3_axis_tdata,
    input input_3_axis_tvalid,
    output input_3_axis_tready,
    input input_3_axis_tlast,
    input input_3_axis_tuser,
    output [7:0] output_axis_tdata,
    output output_axis_tvalid,
    input output_axis_tready,
    output output_axis_tlast,
    output output_axis_tuser,
    output busy
);

reg [7:0] data_out;
reg output_axis_tvalid_reg;
reg output_axis_tlast_reg;
reg busy_reg;
reg [1:0] state;
reg [1:0] input_valid;
reg [1:0] input_last;
reg [7:0] input_data [0:3];
reg input_tuser [0:3];
reg tag [0:3];
reg [1:0] input_ready [0:3];

// Initialize variables
initial begin
    state <= 2'b00;
    input_valid <= 2'b00;
    input_last <= 2'b00;
    busy_reg <= 1'b0;
end

// Assign input signals
assign input_0_axis_tready = input_ready[0];
assign input_1_axis_tready = input_ready[1];
assign input_2_axis_tready = input_ready[2];
assign input_3_axis_tready = input_ready[3];

// State machine
always @(posedge clk) begin
    case (state)
        // Wait for valid data on all inputs
        2'b00: begin
            if (input_0_axis_tvalid && input_1_axis_tvalid && input_2_axis_tvalid && input_3_axis_tvalid) begin
                state <= 2'b01;
                input_valid <= {input_3_axis_tvalid, input_2_axis_tvalid, input_1_axis_tvalid, input_0_axis_tvalid};
                input_last <= {input_3_axis_tlast, input_2_axis_tlast, input_1_axis_tlast, input_0_axis_tlast};
                input_data[0] <= input_0_axis_tdata;
                input_data[1] <= input_1_axis_tdata;
                input_data[2] <= input_2_axis_tdata;
                input_data[3] <= input_3_axis_tdata;
                input_tuser[0] <= input_0_axis_tuser;
                input_tuser[1] <= input_1_axis_tuser;
                input_tuser[2] <= input_2_axis_tuser;
                input_tuser[3] <= input_3_axis_tuser;
                input_ready[0] <= 1'b1;
                input_ready[1] <= 1'b1;
                input_ready[2] <= 1'b1;
                input_ready[3] <= 1'b1;
            end
        end
        // Wait for output ready signal
        2'b01: begin
            if (output_axis_tready) begin
                state <= 2'b10;
                data_out <= input_data[input_valid[1:0]];
                tag[input_valid[1:0]] <= output_axis_tuser;
                output_axis_tvalid_reg <= 1'b1;
                output_axis_tlast_reg <= input_last[input_valid[1:0]];
                input_ready[input_valid[1:0]] <= 1'b0;
            end
        end
        // Wait for output valid signal to de-assert
        2'b10: begin
            if (!output_axis_tvalid_reg) begin
                state <= 2'b00;
                busy_reg <= 1'b0;
                input_ready[input_valid[1:0]] <= 1'b1;
            end
        end
    endcase
end

// Assign output signals
assign output_axis_tdata = data_out;
assign output_axis_tvalid = output_axis_tvalid_reg;
assign output_axis_tlast = output_axis_tlast_reg;
assign output_axis_tuser = tag[input_valid[1:0]];
assign busy = busy_reg;

// Set busy signal
always @(posedge clk) begin
    if (state != 2'b00) begin
        busy_reg <= 1'b1;
    end
end

// Reset logic
always @(posedge clk) begin
    if (rst) begin
        state <= 2'b00;
        input_valid <= 2'b00;
        input_last <= 2'b00;
        input_ready[0] <= 1'b1;
        input_ready[1] <= 1'b1;
        input_ready[2] <= 1'b1;
        input_ready[3] <= 1'b1;
        busy_reg <= 1'b0;
    end
end

endmodule

module d_ff_jk_pipeline (
    input clk,    // Clocks are used in sequential circuits
    input d,
    input aset,
    input areset,
    output reg q );

    reg j, k, q1, q2;

    // Pipeline stage 1
    always @(posedge clk) begin
        j <= ~d & ~q2;
        k <= d & ~q2;
        q1 <= j & q2 | ~k & q2;
    end

    // Pipeline stage 2
    always @(posedge clk) begin
        q2 <= aset ? 1'b1 : areset ? 1'b0 : q1;
    end

    // Output stage
    always @(posedge clk) begin
        q <= q2;
    end

