module MIO_BUS( input wire clk, input wire rst,
	input wire [3:0] BTN,
	input wire [7:0]SW,
	input wire mem_w,
	input wire [31:0] Cpu_data2bus,
	input wire [31:0] addr_bus, //data from CPU
	input wire [31:0] ram_data_out,
	input wire [7:0] led_out,
	input wire [31:0] counter_out,
	input wire counter0_out,
	input wire counter1_out,
	input wire counter2_out,
	output reg [31:0] Cpu_data4bus, //write to CPU
	output reg [31:0] ram_data_in, //from CPU write to Memory
	output reg [9: 0] ram_addr, //Memory Address signals
	output reg data_ram_we, 
	output reg GPIOf0000000_we,
	output reg GPIOe0000000_we,
	output reg counter_we,
	output reg [31: 0] Peripheral_in
);

	reg [7:0] led_in;

	always @(*) begin
		data_ram_we = 0;
		counter_we = 0;
		GPIOe0000000_we = 0;
		GPIOf0000000_we = 0;
		ram_addr = 10'h0;
		ram_data_in = 32'h0;
		Peripheral_in = 32'h0;
		Cpu_data4bus = 32'h0;
		case(addr_bus[31:28])
			4'h0: begin
				data_ram_we = mem_w	;
				ram_addr = addr_bus[11:2];
				ram_data_in = Cpu_data2bus;
				Cpu_data4bus = ram_data_out;
			end
			4'he: begin
				GPIOf0000000_we = mem_w;
				Peripheral_in = Cpu_data2bus;
				Cpu_data4bus = counter_out;
			end
			4'hf: begin
				if(addr_bus[2]) begin
					counter_we = mem_w;
					Peripheral_in = Cpu_data2bus;
					Cpu_data4bus = counter_out;
				end else begin
					GPIOf0000000_we = mem_w;
					Peripheral_in = Cpu_data2bus;
					Cpu_data4bus = {counter0_out, counter1_out, counter2_out, 9'h00, led_out, BTN, SW};
				end
			end
		endcase
	end
endmodule

module adder_4bit_carry (sum, cout, a, b, cin);
    output [3:0] sum;
    output cout;
    input [3:0] a;
    input [3:0] b;
    input cin;

    wire [3:0] temp_sum;
    wire [4:0] temp_carry;

    // Full Adder
    assign temp_carry[0] = cin;
    assign {temp_carry[1], temp_sum[0]} = a[0] + b[0] + temp_carry[0];
    assign {temp_carry[2], temp_sum[1]} = a[1] + b[1] + temp_carry[1];
    assign {temp_carry[3], temp_sum[2]} = a[2] + b[2] + temp_carry[2];
    assign {temp_carry[4], temp_sum[3]} = a[3] + b[3] + temp_carry[3];

    assign sum = temp_sum;
    assign cout = temp_carry[4];
endmodule

module log_exp (
  input [15:0] x,
  output reg [31:0] ln_x,
  output reg [31:0] exp_x
);

  reg [31:0] ln_sum, exp_sum;
  reg [15:0] i;
  reg [31:0] x_pow_i, fact_i;

  always @(*) begin
    if (x == 0) begin
      ln_x = 0;
      exp_x = 1;
    end
    else if (x < 0) begin
      ln_x = -1;
      exp_x = 0;
    end
    else begin
      // Compute natural logarithm using Taylor series expansion
      ln_sum = 0;
      x_pow_i = x - 1;
      fact_i = 1;
      for (i = 1; i <= 10; i = i + 1) begin
        ln_sum = ln_sum + (x_pow_i / i) * fact_i;
        x_pow_i = x_pow_i * (x - 1);
        fact_i = fact_i * i;
      end
      ln_x = ln_sum;

      // Compute exponential function using Taylor series expansion
      exp_sum = 1;
      x_pow_i = 1;
      fact_i = 1;
      for (i = 1; i <= 10; i = i + 1) begin
        exp_sum = exp_sum + (x_pow_i / fact_i);
        x_pow_i = x_pow_i * x;
        fact_i = fact_i * i;
      end
      exp_x = exp_sum;
    end
  end

endmodule

module lfsr (
    input clk,
    input rst,
    input [1:0] config,
    input [7:0] feed_forward,
    input [7:0] data_in,
    input [7:0] state_in,
    output [7:0] data_out,
    output [7:0] state_out
);

parameter LFSR_WIDTH = 8;

reg [LFSR_WIDTH-1:0] state;
wire feedback;

assign feedback = (config == 0) ? (state[LFSR_WIDTH-1] ^ state[LFSR_WIDTH-2]) :
                  (config == 1) ? (state[LFSR_WIDTH-1] & state[feed_forward]) :
                                  ((state[LFSR_WIDTH-1] ^ state[LFSR_WIDTH-2]) ^ data_in);

assign data_out = (config == 2) ? state[0] : 0;
assign state_out = state;

always @(posedge clk) begin
    if (rst) begin
        state <= state_in;
    end else begin
        state <= {feedback, state[LFSR_WIDTH-1:1]};
    end
end

endmodule

module clock_generator (
  input CLK_IN, // input clock signal
  input RST_N, // reset signal
  output reg CLK_OUT // output clock signal
);

  reg [31:0] cntr; // counter
  parameter upper = 100; // maximum value of the counter
  parameter offset = 10; // initial value of the counter
  parameter nexttick = 50; // counter value at which to generate the output clock signal

  always @(posedge CLK_IN or negedge RST_N) begin
    if (!RST_N) begin
      // reset the counter to the initial value
      cntr <= upper - offset;
      CLK_OUT <= 0;
    end else begin
      // increment the counter
      if (cntr < upper) begin
        cntr <= cntr + 1;
      end else begin
        cntr <= 0;
      end

      // generate the output clock signal
      if (cntr == nexttick) begin
        CLK_OUT <= ~CLK_OUT;
      end
    end
  end

endmodule

module pwm_generator(
    input Clk,
    input Reset,
    input [3:0] DutyCycle,
    output reg PWM
);

reg [15:0] counter;

always @(posedge Clk) begin
    if (Reset) begin
        counter <= 0;
        PWM <= 0;
    end else begin
        counter <= counter + 1;
        if (counter == 16000) begin
            counter <= 0;
            PWM <= (counter < DutyCycle);
        end
    end
end

endmodule

module sevenseg(seg0, seg1, seg2, seg3, seg4, seg5, seg6, seg7, score_p1, score_p2, winner);
	input [3:0] score_p1, score_p2;								
	input [1:0] winner;												// 0 = none, 1 = P1, 2 = P2
	output [6:0] seg0, seg1, seg2, seg3, seg4, seg5, seg6, seg7;

	reg [6:0] seg0, seg1, seg2, seg3, seg4, seg5, seg6, seg7;

	always @ (score_p1 or winner) begin

		if (winner > 0) begin
			// Show the winner on HEX7 and HEX6 (i.e. P1 or P2)
			seg7 = 7'b0001100;				// P
			case (winner)
				2'h1: seg6 = 7'b1111001;	// 1
				2'h2: seg6 = 7'b0100100;	// 2
				default: seg6 = 7'b1111111;
			endcase
		end
		else begin
			seg7 = 7'b1111111;
			case (score_p1)
					4'h0: seg6 = 7'b1000000;
					4'h1: seg6 = 7'b1111001; 
					4'h2: seg6 = 7'b0100100; 
					4'h3: seg6 = 7'b0110000; 
					4'h4: seg6 = 7'b0011001; 	
					4'h5: seg6 = 7'b0010010; 
					4'h6: seg6 = 7'b0000010; 
					4'h7: seg6 = 7'b1111000; 
					4'h8: seg6 = 7'b0000000; 
					4'h9: seg6 = 7'b0011000; 
					default: seg6 = 7'b1111111; 
			endcase
		end
	end

	always @ (score_p2 or winner) begin
		if (winner > 0) begin
			// Unused; blank out
			seg5 = 7'b1111111;
			seg4 = 7'b1111111;
		end
		else begin
			seg5 = 7'b1111111;
			case (score_p2)
					4'h0: seg4 = 7'b1000000; 
					4'h1: seg4 = 7'b1111001; 
					4'h2: seg4 = 7'b0100100; 
					4'h3: seg4 = 7'b0110000; 
					4'h4: seg4 = 7'b0011001; 	
					4'h5: seg4 = 7'b0010010; 
					4'h6: seg4 = 7'b0000010; 
					4'h7: seg4 = 7'b1111000; 
					4'h8: seg4 = 7'b0000000; 
					4'h9: seg4 = 7'b0011000; 
					default: seg4 = 7'b1111111; 
			endcase
		end
	end

	// Blank out unused displays
	always begin
		seg3 = 7'b1111111;
		seg2 = 7'b1111111;
		seg1 = 7'b1111111;
		seg0 = 7'b1111111;
	end

endmodule

module up_counter(clk, rst, count, overflow);
    input clk, rst;
    output [3:0] count;
    output overflow;
    reg [3:0] count;

    always @(posedge clk, posedge rst)
    begin
        if (rst)
            count <= 4'b0;
        else if (count == 4'hf)
            count <= 4'b0;
        else
            count <= count + 1;
    end

    assign overflow = (count == 4'hf);
endmodule

module twos_complement (
    input [3:0] in,
    output reg [3:0] out
);

// Flip all bits in the input
wire [3:0] flipped_in = ~in;

// Add 1 to the flipped input
wire [3:0] one = 1;
wire [3:0] added_in = flipped_in + one;

// Assign the output to the added input
assign out = added_in;

endmodule

