module check_tu (
  input clk,
  input reset,
  input [31:0] module_to_check_timeunit,
  output reg valid_timeunit
);

  reg [31:0] counter;

  always @(posedge clk) begin
    if (reset) begin
      valid_timeunit <= 0;
      counter <= 0;
    end else begin
      if (module_to_check_timeunit >= 10000) begin
        valid_timeunit <= 1;
      end else begin
        valid_timeunit <= 0;
      end
      counter <= counter + 1;
    end
  end

endmodule

module combinational_circuit(
    input [3:0] in,
    output out_and,
    output out_or,
    output out_xor
);

wire [1:0] mux_out_and;
wire [1:0] mux_out_or;
wire [1:0] mux_out_xor;

assign mux_out_and[0] = in[0] & in[1];
assign mux_out_and[1] = in[2] & in[3];

assign mux_out_or[0] = in[0] | in[1];
assign mux_out_or[1] = in[2] | in[3];

assign mux_out_xor[0] = in[0] ^ in[1];
assign mux_out_xor[1] = in[2] ^ in[3];

assign out_and = mux_out_and[0] & mux_out_and[1];
assign out_or = mux_out_or[0] | mux_out_or[1];
assign out_xor = mux_out_xor[0] ^ mux_out_xor[1];

endmodule

