module bcd_counter (
    input clk,
    input reset,
    input [3:1] ena,
    output reg [3:0] count
);

always @(posedge clk) begin
    if (reset) begin
        count <= 4'b0000;
    end else begin
        if (ena[0]) begin
            if (count[0] == 4'b1001) begin
                count[0] <= 4'b0000;
                if (ena[1]) begin
                    if (count[1] == 4'b1001) begin
                        count[1] <= 4'b0000;
                        if (ena[2]) begin
                            if (count[2] == 4'b1001) begin
                                count[2] <= 4'b0000;
                                if (count[3] == 4'b1001) begin
                                    count[3] <= 4'b0000;
                                end else begin
                                    count[3] <= count[3] + 1;
                                end
                            end else begin
                                count[2] <= count[2] + 1;
                            end
                        end
                    end else begin
                        count[1] <= count[1] + 1;
                    end
                end
            end else begin
                count[0] <= count[0] + 1;
            end
        end
    end
end

endmodule

