    case (addr)
      4'h0: begin s = (cs && wr) ? 3'b001 : 3'b000; end //din_uart
      4'h2: begin s = (cs && rd) ? 3'b010 : 3'b000; end //busy
      4'h4: begin s = (cs && rd) ? 3'b100 : 3'b000; end //done
