    input aresetn,
    input [31:0] s_axis_0_tdata,
    input [31:0] s_axis_1_tdata,
    input [31:0] s_axis_2_tdata,
    input s_axis_0_tvalid,
    input s_axis_1_tvalid,
    input s_axis_2_tvalid,
    output reg s_axis_0_tready,
    output reg s_axis_1_tready,
    output reg s_axis_2_tready,
    output reg [31:0] m_axis_0_tdata,
    output reg [31:0] m_axis_1_tdata,
    output reg m_axis_0_tvalid,
    output reg m_axis_1_tvalid,
    input m_axis_0_tready,
    input m_axis_1_tready
);

// internal signals
reg [31:0] buffer_0;
reg [31:0] buffer_1;
reg [31:0] buffer_2;
reg [31:0] buffer_0_next;
reg [31:0] buffer_1_next;
reg [31:0] buffer_2_next;
reg [1:0] route_0;
reg [1:0] route_1;
reg [1:0] route_2;
reg [1:0] route_0_next;
reg [1:0] route_1_next;
reg [1:0] route_2_next;
reg [1:0] current_route;
reg [1:0] next_route;

// initialize buffers and routes to zero
initial begin
    buffer_0 = 0;
    buffer_1 = 0;
    buffer_2 = 0;
    route_0 = 0;
    route_1 = 0;
    route_2 = 0;
end

// compute next routes
always @(*) begin
    route_0_next = (m_axis_0_tready && s_axis_0_tvalid) ? 1 :
                   (m_axis_1_tready && s_axis_0_tvalid) ? 2 :
                   route_0;
    route_1_next = (m_axis_0_tready && s_axis_1_tvalid) ? 1 :
                   (m_axis_1_tready && s_axis_1_tvalid) ? 2 :
                   route_1;
    route_2_next = (m_axis_0_tready && s_axis_2_tvalid) ? 1 :
                   (m_axis_1_tready && s_axis_2_tvalid) ? 2 :
                   route_2;
end

// compute next buffers
always @(*) begin
    buffer_0_next = (route_0_next == 1) ? s_axis_0_tdata :
                    (route_0_next == 2) ? s_axis_1_tdata :
                                         s_axis_2_tdata;
    buffer_1_next = (route_1_next == 1) ? s_axis_0_tdata :
                    (route_1_next == 2) ? s_axis_1_tdata :
                                         s_axis_2_tdata;
    buffer_2_next = (route_2_next == 1) ? s_axis_0_tdata :
                    (route_2_next == 2) ? s_axis_1_tdata :
                                         s_axis_2_tdata;
end

// compute next routes and buffers
always @(posedge aclk) begin
    if (!aresetn) begin
        route_0 <= 0;
        route_1 <= 0;
        route_2 <= 0;
        buffer_0 <= 0;
        buffer_1 <= 0;
        buffer_2 <= 0;
    end else begin
        route_0 <= route_0_next;
        route_1 <= route_1_next;
        route_2 <= route_2_next;
        buffer_0 <= buffer_0_next;
        buffer_1 <= buffer_1_next;
        buffer_2 <= buffer_2_next;
    end
end

// compute current route
always @(*) begin
    current_route = (m_axis_0_tvalid && m_axis_0_tready) ? next_route :
                     m_axis_0_tvalid ? current_route :
                     (m_axis_1_tvalid && m_axis_1_tready) ? next_route :
                     m_axis_1_tvalid ? current_route :
                     (route_0 == current_route) ? 0 :
                     (route_1 == current_route) ? 1 :
                                                  2;
end

// compute next route
always @(*) begin
    next_route = (current_route == 0) ? route_1 :
                 (current_route == 1) ? route_2 :
                                          route_0;
end

// assign outputs
assign s_axis_0_tready = (current_route == 0) && !m_axis_0_tvalid;
assign s_axis_1_tready = (current_route == 1) && !m_axis_0_tvalid;
assign s_axis_2_tready = (current_route == 2) && !m_axis_0_tvalid;
assign m_axis_0_tdata = (current_route == 0) ? buffer_0 :
                        (current_route == 1) ? buffer_1 :
                                               buffer_2;
assign m_axis_1_tdata = (current_route == 0) ? buffer_1 :
                        (current_route == 1) ? buffer_2 :
                                               buffer_0;
assign m_axis_0_tvalid = (current_route == 0) && (s_axis_0_tvalid || s_axis_1_tvalid || s_axis_2_tvalid);
assign m_axis_1_tvalid = (current_route == 1) && (s_axis_0_tvalid || s_axis_1_tvalid || s_axis_2_tvalid);

endmodule

module top_module (
    input [1:0] a,
    input [49:0] in,
    output reg [5:0] out
);

    wire xor_out;
    wire [2:0] comb_out;

    xor_gate xor_inst (
        .a(a[0]),
        .b(a[1]),
        .out_lut(xor_out)
    );

    comb_circuit_50_input comb_inst (
        .in(in),
        .out_nand(comb_out[0]),
        .out_nor(comb_out[1]),
        .out_xnor(comb_out[2])
    );

    always @(*) begin
        out[0] = xor_out;
        out[1] = comb_out[0];
        out[2] = comb_out[1];
        out[3] = comb_out[2];
        out[4] = 0;
        out[5] = 0;
    end

endmodule

module xor_gate (
    input a,
    input b,
    output reg out_lut
);

    always @(*) begin
        case ({a,b})
            2'b00: out_lut = 1'b0;
            2'b01: out_lut = 1'b1;
            2'b10: out_lut = 1'b1;
            2'b11: out_lut = 1'b0;
        endcase
    end

endmodule

module comb_circuit_50_input (
    input [49:0] in,
    output reg out_nand,
    output reg out_nor,
    output reg out_xnor
);

    assign out_nand = ~(&in);
    assign out_nor = ~(|in);
    assign out_xnor = ~(^in);

endmodule

module tracking_camera_system_jtag_uart_0_drom_module (
  // inputs:
  clk,
  incr_addr,
  reset_n,

  // outputs:
  new_rom,
  num_bytes,
  q,
  safe
);

  parameter POLL_RATE = 100;

  output new_rom;
  output [31:0] num_bytes;
  output [7:0] q;
  output safe;
  input clk;
  input incr_addr;
  input reset_n;

  reg [11:0] address;
  reg d1_pre;
  reg d2_pre;
  reg d3_pre;
  reg d4_pre;
  reg d5_pre;
  reg d6_pre;
  reg d7_pre;
  reg d8_pre;
  reg d9_pre;
  reg [7:0] mem_array[2047:0];
  reg [31:0] mutex[1:0];
  reg new_rom;
  wire [31:0] num_bytes;
  reg pre;
  wire [7:0] q;
  wire safe;

  //synthesis translate_off
  ////////////////// SIMULATION-ONLY CONTENTS
  assign q = (mutex[0] && !safe) ? mem_array[address] : 8'b0;
  always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
      d1_pre <= 0;
      d2_pre <= 0;
      d3_pre <= 0;
      d4_pre <= 0;
      d5_pre <= 0;
      d6_pre <= 0;
      d7_pre <= 0;
      d8_pre <= 0;
      d9_pre <= 0;
      new_rom <= 0;
    end else begin
      d1_pre <= pre;
      d2_pre <= d1_pre;
      d3_pre <= d2_pre;
      d4_pre <= d3_pre;
      d5_pre <= d4_pre;
      d6_pre <= d5_pre;
      d7_pre <= d6_pre;
      d8_pre <= d7_pre;
      d9_pre <= d8_pre;
      new_rom <= d9_pre;
    end
  end

  assign num_bytes = (mutex[0] && !safe) ? mutex[1] : 32'b0;

  reg safe_delay;
  reg [31:0] poll_count;
  reg [31:0] mutex_handle;
  wire interactive = 1'b1;
  assign safe = (address < mutex[1]);

  initial poll_count = POLL_RATE;

  always @(posedge clk or negedge reset_n) begin
    if (reset_n !== 1) begin
      safe_delay <= 0;
    end else begin
      safe_delay <= safe;
    end
  end // safe_delay

  always @(posedge clk or negedge reset_n) begin
    if (reset_n !== 1) begin
      address <= 0;
      mem_array[0] <= 0;
      mutex[0] <= 0;
      mutex[1] <= 0;
      pre <= 0;
    end else begin
      pre <= 0;
      if (incr_addr && safe) begin
        address <= address + 1;
      end
      if (mutex[0] && !safe && safe_delay) begin
        if (interactive) begin
          mutex_handle = $fopen("tracking_camera_system_jtag_uart_0_input_mutex.dat");
          $fdisplay(mutex_handle, "0");
          $fclose(mutex_handle);
        end else begin
          wait (!reset_n);
        end
        mutex[0] <= 0;
        safe <= 1;
      end
      if (poll_count < POLL_RATE) begin
        poll_count <= poll_count + 1;
      end else begin
        poll_count <= 0;
        if (mutex_handle) begin
          $readmemh("tracking_camera_system_jtag_uart_0_input_mutex.dat", mutex);
        end
        if (mutex[0] && !safe) begin
          mutex[1] <= mutex[0];
          $readmemb("tracking_camera_system_jtag_uart_0_input_stream.dat", mem_array);
          address <= 0;
          pre <= -1;
          new_rom <= 1;
        end
      end
    end
  end

  ////////////////// END SIMULATION-ONLY CONTENTS

  //synthesis translate_on

endmodule

module top_module(
    input [31:0] a,
    input [31:0] b,
    input op,
    output [31:0] result
);

    wire [15:0] and_out;
    wire [31:0] or_out;

    and_gate_16bit and1(
        .a(a[15:0]),
        .b(b[15:0]),
        .out(and_out[0])
    );
    and_gate_16bit and2(
        .a(a[31:16]),
        .b(b[31:16]),
        .out(and_out[1])
    );
    and_gate_16bit and3(
        .a(a[47:32]),
        .b(b[47:32]),
        .out(and_out[2])
    );
    and_gate_16bit and4(
        .a(a[63:48]),
        .b(b[63:48]),
        .out(and_out[3])
    );

    or_gate_32bit or1(
        .a(and_out),
        .out(or_out)
    );

    bitwise_op functional_module(
        .a(a),
        .b(b),
        .op(op),
        .or_out(or_out),
        .result(result)
    );

endmodule

module and_gate_16bit(
    input [15:0] a,
    input [15:0] b,
    output out
);

    assign out = a & b;

endmodule

module or_gate_32bit(
    input [31:0] a,
    output [31:0] out
);

    assign out = |a;

endmodule

module bitwise_op(
    input [31:0] a,
    input [31:0] b,
    input op,
    input [31:0] or_out,
    output [31:0] result
);

    assign result = (op == 0) ? (a & b) : or_out;

endmodule

module adder_4bit (
    input [3:0] a,
    input [3:0] b,
    input cin,
    output reg [3:0] sum,
    output reg cout
);

    wire c0, c1, c2;

    // First bit
    sky130_fd_sc_ls__xor2_1 xor1_0 (.a(a[0]), .b(b[0]), .O(sum[0]));
    sky130_fd_sc_ls__and2_1 and1_0 (.a(a[0]), .b(b[0]), .O(c0));
    sky130_fd_sc_ls__and2_1 and2_0 (.a(a[0]), .b(cin), .O(c1));
    sky130_fd_sc_ls__and2_1 and3_0 (.a(b[0]), .b(cin), .O(c2));
    sky130_fd_sc_ls__or3_1 or1_0 (.a(c0), .b(c1), .c(c2), .O(cout));

    // Second bit
    sky130_fd_sc_ls__xor2_1 xor1_1 (.a(a[1]), .b(b[1]), .O(sum[1]));
    sky130_fd_sc_ls__and2_1 and1_1 (.a(a[1]), .b(b[1]), .O(c0));
    sky130_fd_sc_ls__or2_1 or1_1 (.a(c0), .b(cout), .O(cout));

    // Third bit
    sky130_fd_sc_ls__xor2_1 xor1_2 (.a(a[2]), .b(b[2]), .O(sum[2]));
    sky130_fd_sc_ls__and2_1 and1_2 (.a(a[2]), .b(b[2]), .O(c0));
    sky130_fd_sc_ls__or2_1 or1_2 (.a(c0), .b(cout), .O(cout));

    // Fourth bit
    sky130_fd_sc_ls__xor2_1 xor1_3 (.a(a[3]), .b(b[3]), .O(sum[3]));
    sky130_fd_sc_ls__and2_1 and1_3 (.a(a[3]), .b(b[3]), .O(c0));
    sky130_fd_sc_ls__or2_1 or1_3 (.a(c0), .b(cout), .O(cout));

endmodule

module counter (
    input clk,
    input reset,
    output reg [3:0] count
);
    always @(posedge clk) begin
        if (reset) begin
            count <= 4'b0000;
        end else begin
            count <= count + 1;
        end
    end
endmodule

module combinational_circuit (
    input [3:0] in,
    output reg [2:0] out
);
    always @(*) begin
        out[0] = in[0] & in[1] & in[2] & in[3];
        out[1] = in[0] | in[1] | in[2] | in[3];
        out[2] = in[0] ^ in[1] ^ in[2] ^ in[3];
    end
endmodule

module functional_module (
    input [2:0] in,
    output reg [15:0] out
);
    always @(*) begin
        out = {16{1'b0}};
        out[in] = 1'b1;
    end
endmodule

module addictive_control_logic (
    input [3:0] in,
    input select,
    output [15:0] out
);
    wire [2:0] combinational_out;
    wire [3:0] counter_out;
    counter counter_inst (
        .clk(clk),
        .reset(reset),
        .count(counter_out)
    );
    combinational_circuit combinational_inst (
        .in(counter_out),
        .out(combinational_out)
    );
    functional_module functional_inst (
        .in(combinational_out),
        .out(out)
    );
    always @(*) begin
        if (select) begin
            out = functional_inst.out;
        end else begin
            out = counter_inst.count;
        end
    end
endmodule

