module barrel_shifter (
  input [n-1:0] in,
  input [log2(n)-1:0] ctl,
  input dir,
  output [n-1:0] out
);

parameter n = 8; // number of bits in the binary number

wire [n-1:0] shifted;

// Left shift
assign shifted = (dir == 0) ? (in << ctl) : (in >> ctl);

// Right shift
assign shifted = (dir == 1) ? (in >> ctl) : (in << ctl);

// Circular shift
assign shifted = {in[(n-ctl):n-1], in[0:n-ctl-1]} ;

assign out = shifted;

endmodule

module adder_4bit_with_cin (
  input [3:0] a,
  input [3:0] b,
  input cin,
  output reg [3:0] out,
  output reg cout
);

  always @(*) begin
    out[0] = a[0] ^ b[0] ^ cin;
    out[1] = a[1] ^ b[1] ^ (a[0] & b[0]) | (a[0] ^ b[0]) & cin;
    out[2] = a[2] ^ b[2] ^ (a[1] & b[1]) | (a[1] ^ b[1]) & (a[0] | b[0]) | (a[0] & b[0] & cin);
    out[3] = a[3] ^ b[3] ^ (a[2] & b[2]) | (a[2] ^ b[2]) & (a[1] | b[1]) | (a[1] & b[1] & (a[0] | b[0])) | (a[0] & b[0] & cin);
    if (out > 4'b1111) begin
      out = out[3:0];
      cout = 1;
    end
    else begin
      cout = 0;
    end
  end

endmodule

module ram(
  input clk,
  input enable,
  input write_enable,
  input [ADDRESS_WIDTH-1 : 0] addr,
  input [WIDTH-1 : 0] data_in,
