  parameter ADDRESS_WIDTH = 4;
  parameter WIDTH = 8;
  parameter MEMORY_SIZE = 1 << ADDRESS_WIDTH;
  reg [WIDTH-1 : 0] mem [0 : MEMORY_SIZE-1];

  initial begin
    $readmemb("prog_fib.list", mem);
  end

  assign data_out = (enable) ? mem[addr] : {WIDTH{1'b0}};

  always @(posedge clk) begin
