    end
  end
endmodule

module clk_gen (
    input wire  clk_ref, 
    input wire  reset_sw, 
    output wire clk,       
    output wire clk_n,      
    output wire chip_reset 
);

    wire        locked;    
    wire        dcm_reset; 

    assign locked     = 1'b1;
    assign dcm_reset  = (reset_sw == 1'b1) ? 1'b0 : 1'b1;
    assign chip_reset = ((reset_sw == 1'b1) || (locked == 1'b0)) ?
                            1'b1 : 1'b0;

    // Xilinx DCM (Digital Clock Manager)
    xilinx_dcm #(
        .CLKIN_PERIOD(10.0),    // Input clock period (ns)
        .CLKFX_DIVIDE(2),       // Feedback clock divide ratio
        .CLKFX_MULTIPLY(4),     // Feedback clock multiply ratio
        .CLKFX_PHASE(0.0),      // Feedback clock phase shift (degrees)
        .CLKFXDV_DIVIDE(2),     // Feedback clock duty cycle adjust divide ratio
        .CLKFXDV_PHASE(0.0),    // Feedback clock duty cycle adjust phase shift (degrees)
        .CLKDV_DIVIDE(2),       // Output clock divide ratio
        .CLKDV_PHASE(0.0),      // Output clock phase shift (degrees)
        .CLKFX_MD_MAX(1.0),     // Maximum frequency deviation of feedback clock (ppm)
        .CLKFX_MD_MIN(-1.0),    // Minimum frequency deviation of feedback clock (ppm)
        .CLK_MD_MAX(1.0),       // Maximum frequency deviation of output clock (ppm)
        .CLK_MD_MIN(-1.0),      // Minimum frequency deviation of output clock (ppm)
        .STARTUP_WAIT("FALSE")  // Wait for DCM to lock before releasing reset
    ) xdc (
        .CLKIN(clk_ref),
        .RST(dcm_reset),
        .CLKFX(clk),
        .CLKFX180(clk_n),
        .LOCKED(locked)
    );

endmodule

module VCO_interface (
  input clk, // reference clock signal
  input [7:0] V_ctrl, // voltage control signal
  output reg vco // VCO signal
);

parameter f_clk = 50_000_000; // frequency of the reference clock signal
parameter V_min = 0; // minimum voltage of the voltage control signal
parameter V_max = 255; // maximum voltage of the voltage control signal
parameter f_min = 1_000_000; // minimum frequency of the VCO signal
parameter f_max = 10_000_000; // maximum frequency of the VCO signal

reg [31:0] count = 0;
reg [31:0] divider = 0;
reg [31:0] width = f_clk / (2 * f_max);

always @(posedge clk) begin
  count <= count + 1;
  if (count >= divider) begin
    vco <= ~vco;
    count <= 0;
  end
end

always @(*) begin
  divider = (f_clk * (V_ctrl - ((V_min + V_max) / 2)) * (f_max - f_min)) / ((V_max - V_min) * f_min * f_max);
end

endmodule

module nand4 (
    Y,
    A,
    B,
    C,
    D
);

    output Y;
    input A;
    input B;
    input C;
    input D;

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB;
