    );

    sky130_fd_sc_lp__nand2b nand3 (
        .Y(W3),
        .A_N(W1),
        .B_N(W2)
    );

    assign Y = W3;

endmodule

module UART(
    clk_x4,
    rst_x,

    i_rx,
    o_tx,

    i_data,
    i_valid,

    o_busy,
    o_data,
    o_valid,
    o_tx_error,
    o_rx_error);

  input        clk_x4;
  input        rst_x;

  input        i_rx;
  output       o_tx;

  input  [7:0] i_data;
  input        i_valid;

  output       o_busy;
  output [7:0] o_data;
  output       o_valid;
  output       o_tx_error;
  output       o_rx_error;

  wire         w_rx_data;
  wire         w_rx_error;
  wire         w_tx_error;

  reg    [7:0] r_tx_data;
  reg          r_tx_start;
  reg          r_tx_done;
  reg    [3:0] r_tx_count;
  reg          r_tx_error;

  reg    [7:0] r_rx_data;
  reg          r_rx_start;
  reg          r_rx_done;
  reg    [3:0] r_rx_count;
  reg          r_rx_error;

  localparam S_IDLE     = 2'b00;
  localparam S_START    = 2'b01;
  localparam S_DATA     = 2'b10;
  localparam S_STOP     = 2'b11;

  reg    [1:0] r_state;

  assign o_busy = (r_state != S_IDLE);

  always @ (posedge clk_x4 or negedge rst_x) begin
    if (!rst_x) begin
      r_tx_data  <= 8'h00;
      r_tx_start <= 1'b0;
      r_tx_done  <= 1'b0;
      r_tx_count <= 4'd0;
      r_tx_error <= 1'b0;
    end else begin
      if (r_tx_done) begin
        r_tx_start <= 1'b0;
      end else if (i_valid && !r_tx_start) begin
        r_tx_data  <= i_data;
        r_tx_start <= 1'b1;
        r_tx_count <= 4'd0;
      end else if (r_tx_start) begin
        case (r_tx_count)
          4'd0: begin
            o_tx <= 1'b0;
            r_tx_count <= r_tx_count + 1;
          end
          4'd1: begin
            o_tx <= r_tx_data[0];
            r_tx_count <= r_tx_count + 1;
          end
          4'd2: begin
            o_tx <= r_tx_data[1];
            r_tx_count <= r_tx_count + 1;
          end
          4'd3: begin
            o_tx <= r_tx_data[2];
            r_tx_count <= r_tx_count + 1;
          end
          4'd4: begin
            o_tx <= r_tx_data[3];
            r_tx_count <= r_tx_count + 1;
          end
          4'd5: begin
            o_tx <= r_tx_data[4];
            r_tx_count <= r_tx_count + 1;
          end
          4'd6: begin
            o_tx <= r_tx_data[5];
            r_tx_count <= r_tx_count + 1;
          end
          4'd7: begin
            o_tx <= r_tx_data[6];
            r_tx_count <= r_tx_count + 1;
          end
          4'd8: begin
            o_tx <= r_tx_data[7];
            r_tx_count <= r_tx_count + 1;
          end
          4'd9: begin
            o_tx <= 1'b1;
            r_tx_done <= 1'b1;
          end
        endcase
      end
    end
  end

  always @ (posedge clk_x4 or negedge rst_x) begin
    if (!rst_x) begin
      r_rx_data  <= 8'h00;
      r_rx_start <= 1'b0;
      r_rx_done  <= 1'b0;
      r_rx_count <= 4'd0;
      r_rx_error <= 1'b0;
    end else begin
      case (r_state)
        S_IDLE: begin
          if (!i_rx) begin
            r_rx_start <= 1'b1;
            r_rx_count <= 4'd0;
            r_state <= S_START;
          end
        end
        S_START: begin
          if (i_rx) begin
            r_rx_error <= 1'b1;
            r_state <= S_IDLE;
          end else if (r_rx_count == 4'd0) begin
            r_rx_count <= r_rx_count + 1;
          end else begin
            r_rx_data <= {i_rx, r_rx_data[7:1]};
            r_rx_count <= r_rx_count + 1;
            r_state <= S_DATA;
          end
        end
        S_DATA: begin
          if (r_rx_count == 4'd7) begin
            r_rx_count <= r_rx_count + 1;
            r_state <= S_STOP;
          end else begin
            r_rx_data <= {i_rx, r_rx_data[7:1]};
            r_rx_count <= r_rx_count + 1;
          end
        end
        S_STOP: begin
          if (i_rx) begin
            r_rx_error <= 1'b1;
            r_state <= S_IDLE;
          end else begin
            r_rx_done <= 1'b1;
            r_state <= S_IDLE;
          end
        end
      endcase
    end
  end

  always @ (posedge clk_x4 or negedge rst_x) begin
    if (!rst_x) begin
      r_state <= S_IDLE;
      o_data <= 8'h00;
      o_valid <= 1'b0;
      o_rx_error <= 1'b0;
    end else begin
      case (r_state)
        S_IDLE: begin
          o_data <= r_rx_data;
          o_valid <= r_rx_done;
          o_rx_error <= r_rx_error;
          if (i_valid) begin
            r_state <= S_START;
          end
        end
        S_START: begin
          o_data <= 8'h00;
          o_valid <= 1'b0;
          o_rx_error <= 1'b0;
          if (r_tx_done) begin
            r_state <= S_IDLE;
          end else if (w_tx_error) begin
            r_tx_error <= 1'b1;
            r_state <= S_IDLE;
          end else begin
            r_state <= S_DATA;
          end
        end
        S_DATA: begin
          o_data <= 8'h00;
          o_valid <= 1'b0;
          o_rx_error <= 1'b0;
          if (r_tx_done) begin
            r_state <= S_IDLE;
          end else if (w_tx_error) begin
            r_tx_error <= 1'b1;
            r_state <= S_IDLE;
          end else if (r_tx_count == 4'd0) begin
            r_state <= S_START;
          end else begin
            r_state <= S_DATA;
          end
        end
      endcase
    end
  end

  assign o_tx_error = r_tx_error | w_rx_error;

endmodule

module pulse_generator(
    input wire clk,
    input wire rst,
    input wire en,
    input wire [31:0] freq,
    input wire [31:0] duty_cycle,
    output reg pulse
);

reg [31:0] count = 0;
reg [31:0] period = 0;
reg [31:0] high_time = 0;
reg [31:0] low_time = 0;
reg [1:0] state = 0;

always @(posedge clk) begin
    if (rst) begin
        pulse <= 0;
        count <= 0;
        period <= 0;
        high_time <= 0;
        low_time <= 0;
        state <= 0;
    end else if (en) begin
        case (state)
            0: begin
                pulse <= 0;
                period <= freq - 1;
                high_time <= (duty_cycle * freq) >> 32;
                low_time <= period - high_time;
                state <= 1;
            end
            1: begin
                if (count < high_time) begin
                    pulse <= 1;
                end else if (count < period) begin
                    pulse <= 0;
                end else begin
                    count <= 0;
                    state <= 0;
                end
            end
        endcase
        count <= count + 1;
    end
end

endmodule

module gen_pulse_tst;

    // Inputs
