module rotator_parity (
    input clk,
    input reset,
    input [99:0] data,
    input select,
    input ena,
    output [7:0] parity
);

    wire [99:0] rotator_out;
    wire [7:0] rotator_parity_out;
    wire [7:0] parity_out;

    rotator rotator_inst (
        .clk(clk),
        .reset(reset),
        .data(data),
        .ena(ena),
        .out(rotator_out),
        .out_parity(rotator_parity_out)
    );

    parity parity_inst (
