module rotator (
    input clk,
    input reset,
    input [99:0] data,
    input ena,
    output [99:0] out,
    output [7:0] out_parity
);

    reg [99:0] shift_reg;
    reg [7:0] parity_reg;
    wire shifted_in;
    wire [99:0] shifted_out;

    assign shifted_in = (ena == 2'b01) ? shift_reg[99] : shift_reg[0];

    always @(posedge clk) begin
        if (reset) begin
            shift_reg <= 100'b0;
            parity_reg <= 8'b0;
        end else begin
            if (ena == 2'b01) begin
                shift_reg <= {shifted_in, shift_reg[99:1]};
            end else if (ena == 2'b10) begin
                shift_reg <= {shift_reg[98:0], shifted_in};
            end
            parity_reg <= ^shift_reg[7:0];
        end
    end

    assign out = shift_reg;
    assign out_parity = parity_reg;

endmodule

