module UART_transceiver(
    input i_Clk, 
    input i_RX_Serial, 
    input i_TX_Load, 
    input [7:0] i_TX_Byte,
    output o_RX_Done, 
    output [7:0] o_RX_Byte, 
    output o_TX_Active, 
    output o_TX_Serial, 
    output o_TX_Done
);

    // Define internal signals
    reg [7:0] rx_reg;
    reg [7:0] tx_reg;
    reg tx_active;
    reg rx_done;
    reg tx_done;
    reg [2:0] bit_count;
    reg [3:0] state;
    wire rx_serial_in;

    // Instantiate clock generator module
    clk_generator clk_gen(
        .i_Clk(i_Clk),
        .o_Clk_12MHz(i_Clk_12MHz)
    );

    // Instantiate UART receiver module
    uart_receiver rx(
        .i_Clk_12MHz(i_Clk_12MHz),
        .i_Serial_In(i_RX_Serial),
        .o_Data_Out(rx_reg),
        .o_Done(rx_done),
        .o_Serial_Out(rx_serial_in)
    );

    // Instantiate UART transmitter module
    uart_transmitter tx(
        .i_Clk_12MHz(i_Clk_12MHz),
        .i_Load(i_TX_Load),
        .i_Data_In(i_TX_Byte),
        .o_Active(tx_active),
        .o_Done(tx_done),
        .o_Serial_Out(o_TX_Serial)
    );

    always @(posedge i_Clk_12MHz) begin
        // Update internal state machine
        case(state)
            0: begin // Wait for start bit
                if(!rx_serial_in) begin
                    bit_count <= 0;
                    state <= 1;
                end
            end
            1: begin // Read data bits
                if(bit_count < 8) begin
                    rx_reg[bit_count] <= rx_serial_in;
                    bit_count <= bit_count + 1;
                end else begin
                    state <= 2;
                end
            end
            2: begin // Wait for stop bit
                if(rx_serial_in) begin
                    o_RX_Byte <= rx_reg;
                    rx_done <= 1;
                    state <= 0;
                end
            end
        endcase

        // Update transmitter
        if(tx_active) begin
            if(bit_count < 10) begin
                if(bit_count == 0) begin
                    o_TX_Serial <= 0;
                end else if(bit_count < 9) begin
                    o_TX_Serial <= tx_reg[bit_count-1];
                end else begin
                    o_TX_Serial <= 1;
                    tx_done <= 1;
                end
                bit_count <= bit_count + 1;
            end else begin
                bit_count <= 0;
                tx_active <= 0;
            end
        end else if(tx_done) begin
            tx_done <= 0;
        end else if(i_TX_Load) begin
            tx_reg <= i_TX_Byte;
            tx_active <= 1;
            bit_count <= 0;
        end

        // Reset receiver
        if(rx_done) begin
            rx_done <= 0;
        end
    end

    // Set output signals
    assign o_RX_Done = rx_done;
    assign o_TX_Active = tx_active;
    assign o_TX_Done = tx_done;
endmodule

module clk_generator(
    input i_Clk,
    output reg o_Clk_12MHz
);

    // Define internal signals
    reg [23:0] counter;

    always @(posedge i_Clk) begin
        // Generate 12 MHz clock signal
        if(counter == 119) begin
            o_Clk_12MHz <= ~o_Clk_12MHz;
            counter <= 0;
        end else begin
            counter <= counter + 1;
        end
    end
endmodule

module uart_receiver(
    input i_Clk_12MHz,
    input i_Serial_In,
    output reg [7:0] o_Data_Out,
    output reg o_Done,
    output reg o_Serial_Out
);

    // Define internal signals
    reg [2:0] bit_count;
    reg [3:0] state;
    wire serial_in;

    always @(posedge i_Clk_12MHz) begin
        // Sample serial input
        serial_in <= i_Serial_In;

        // Update internal state machine
        case(state)
            0: begin // Wait for start bit
                if(!serial_in) begin
                    bit_count <= 0;
                    state <= 1;
                end
            end
            1: begin // Read data bits
                if(bit_count < 8) begin
                    o_Data_Out[bit_count] <= serial_in;
                    bit_count <= bit_count + 1;
                end else begin
                    state <= 2;
                end
            end
            2: begin // Wait for stop bit
                if(serial_in) begin
                    o_Done <= 1;
                    state <= 0;
                end
            end
        endcase

        // Set output signals
        o_Serial_Out <= 1;
    end
endmodule

module uart_transmitter(
    input i_Clk_12MHz,
    input i_Load,
    input [7:0] i_Data_In,
    output reg o_Active,
    output reg o_Done,
    output reg o_Serial_Out
);

    // Define internal signals
    reg [2:0] bit_count;
    reg [3:0] state;
    reg [7:0] data_reg;

    always @(posedge i_Clk_12MHz) begin
        // Update internal state machine
        case(state)
            0: begin // Wait for load signal
                if(i_Load) begin
                    data_reg <= i_Data_In;
                    o_Active <= 1;
                    bit_count <= 0;
                    state <= 1;
                end
            end
            1: begin // Transmit data bits
                if(bit_count < 8) begin
                    o_Serial_Out <= data_reg[bit_count];
                    bit_count <= bit_count + 1;
                end else begin
                    state <= 2;
                end
            end
            2: begin // Transmit stop bit
                o_Serial_Out <= 1;
                bit_count <= bit_count + 1;
                if(bit_count == 10) begin
                    o_Active <= 0;
                    o_Done <= 1;
                    state <= 0;
                end
            end
        endcase
    end
endmodule

module spi_master (
  input clk,
  input reset,
  input [7:0] data_out,
  input ss,
  output [7:0] data_in
);

  reg [7:0] tx_data;
  reg [7:0] rx_data;
  reg shift_enable;
  reg [2:0] shift_count;

  always @(posedge clk) begin
    if (reset) begin
      shift_enable <= 0;
      shift_count <= 0;
      tx_data <= 0;
      rx_data <= 0;
    end else begin
      if (shift_enable) begin
        shift_count <= shift_count + 1;
        if (shift_count == 8) begin
          shift_enable <= 0;
          shift_count <= 0;
          rx_data <= data_in;
        end
      end else begin
        if (ss == 0) begin
          shift_enable <= 1;
          tx_data <= data_out;
        end
      end
    end
  end

  assign data_in = rx_data;

endmodule

