wire [8:0] sum;
wire msb_in_a, msb_in_b, msb_out;
assign msb_in_a = a[7];
assign msb_in_b = b[7];

array_multiplier am (
    .a(a),
    .b(b),
    .product(product)
);

assign sum = product[7:0] + product[15:8];

assign s = sum[7:0];
assign msb_out = sum[8];

assign overflow = (msb_in_a == msb_in_b) && (msb_in_a != msb_out);

overflow_detector od (
    .overflow(overflow),
    .sum(sum),
    .final_output(final_output)
);

endmodule

