module carry_select_adder (
    input [15:0] A, B,
    input Cin,
    output [15:0] S,
    output Cout
);

    wire [15:0] P, G, C0, C1, S0, S1;

    assign P = A + B;
    assign G = A & B;

    assign C0 = Cin ? ~G : G;
    assign C1 = Cin ? ~P : P;

    assign S0 = C0 + {16{1'b0}};
    assign S1 = C1 + {16{1'b0}};

    assign S = (Cin) ? S1 : S0;
    assign Cout = (Cin) ? C1[16] : C0[16];

endmodule

