        product <= product + (a * b);
        stage <= 15;
    end
    else if (stage == 15) begin
        a <= a >> 1;
        b <= b << 1;
        product <= product + (a * b);
        out <= product;
        stage <= 0;
    end
end

endmodule

module matrix_vector_multiply #(
    parameter M = 4,
    parameter N = 4
) (
    input clk,
    input start,
    input [M*N-1:0] matrix_in,
    input [N-1:0] vector_in,
    output [M-1:0] result_out
);

    reg [M-1:0] result_reg [N-1:0];
    reg [M-1:0] temp_reg;
    reg [N-1:0] vector_reg;

    integer i, j;

    always @(posedge clk) begin
        if (start) begin
            // initialize registers
            for (i = 0; i < N; i = i + 1) begin
                for (j = 0; j < M; j = j + 1) begin
                    result_reg[i][j] <= 0;
                end
            end
            vector_reg <= vector_in;
        end else begin
            // perform matrix-vector multiplication
            for (i = 0; i < N; i = i + 1) begin
                for (j = 0; j < M; j = j + 1) begin
                    temp_reg[j] <= matrix_in[i*M+j] * vector_reg[i];
                end
                result_reg[i] <= result_reg[i] + temp_reg;
            end
        end
    end

    assign result_out = result_reg[N-1];

endmodule

module pipeline_module (
    input wire [2:0] vec,
    output wire [2:0] outv,
    output wire o2,
    output wire o1,
    output wire o0
