module CDR (
  input wire [n-1:0] data_in,
  output wire clk_out,
  output reg [n-1:0] data_out
);

parameter n = 8; // number of bits in the serial data stream
parameter clk_freq = 100_000_000; // frequency of the recovered clock signal

// PLL instance
wire pll_clk;
wire pll_locked;
wire pll_reset;

pll pll_inst (
  .clk_in(data_in[n-1]),
  .clk_out(pll_clk),
  .locked(pll_locked),
  .reset(pll_reset)
);

// Clock and data recovery logic
reg [n-1:0] shift_reg;
reg [n-1:0] data_buffer;
reg sample_clk;

always @(posedge pll_clk or posedge pll_reset) begin
  if (pll_reset) begin
    sample_clk <= 1'b0;
  end else begin
    sample_clk <= ~sample_clk;
  end
end

always @(posedge sample_clk or posedge pll_reset) begin
  if (pll_reset) begin
    shift_reg <= {n{1'b0}};
    data_buffer <= {n{1'b0}};
  end else begin
    shift_reg <= {data_in, shift_reg[n-1:1]};
    if (pll_locked) begin
      data_buffer <= shift_reg;
    end
  end
end

assign clk_out = pll_clk;
assign data_out = data_buffer;

endmodule

