reg [4:0] count;
reg signed [15:0] a_shifted;
reg signed [15:0] b_shifted;
reg signed [15:0] b_neg;
reg signed [31:0] sum;

always @(*) begin
    if (signed_ctrl) begin
        b_neg = ~b + 1;
        b_shifted = {b_neg[15], b_neg};
    end else begin
        b_shifted = {b[15], b};
    end
    a_shifted = {a[15], a};
    product = a_shifted * b_shifted;
end

