module wb_ram_xilinx_bank (
   // Outputs
   dout,
   // Inputs
   clk, rst, we, din, waddr, raddr, bank_select
   ) ;

   parameter RAM_DEPTH = 8192;
   parameter RAM_WIDTH = 32;

   input clk;
   input rst;
   input [3:0] we;
   input [31:0] din;
   input [12:0] waddr;
   input [12:0] raddr;
   input bank_select;
   output [31:0] dout;

   reg [31:0] ram [0:RAM_DEPTH-1];

   integer i;

   initial begin
      for (i = 0; i < RAM_DEPTH; i = i + 1) begin
         ram[i] = 0;
      end
   end

   always @(posedge clk) begin
      if (rst) begin
         for (i = 0; i < RAM_DEPTH; i = i + 1) begin
            ram[i] = 0;
         end
      end
      else begin
         if (we[0]) begin
            ram[waddr] <= din;
         end
         if (we[1]) begin
            ram[waddr+1] <= din;
         end
         if (we[2]) begin
            ram[waddr+2] <= din;
         end
         if (we[3]) begin
            ram[waddr+3] <= din;
         end
      end
   end

   assign dout = bank_select ? ram[raddr + 4096] : ram[raddr];

endmodule

