  if (~rst) begin
    data_dst <= 1'b0;
    sync_pulse <= 1'b0;
  end else begin
    data_dst <= data_src;
    sync_pulse <= 1'b1;
  end
end

always @(posedge clk_dst, negedge rst) begin
  if (~rst) begin
    data_sync <= 1'b0;
  end else begin
    data_sync <= data_dst;
  end
end

endmodule

module RoundModeLogic (Phi,
                  OprRoundMode,
                  LoadOprs,
                  notAbortWB,
                  CMPDecoded, CMPEDecoded,
                  RomSetRModeMinus,
                  RModeMinus,
                  U_RoundingMode);

input Phi;
input [1:0] OprRoundMode;
input LoadOprs,
      notAbortWB,
      CMPDecoded, CMPEDecoded,
      RomSetRModeMinus;

output RModeMinus;
output [1:0] U_RoundingMode;

/* In addition to being the rounding mode this latch is also used in
   the compares to signal between the two different types Invalid/Vailid
   on unordered. This is TACKY but saves a lot of code
   Additional inputs CMPE and CMP distinguish between the two types
   It isnt a big problem because RMode is part of the instruction not
   ME_ROM and so no timing problems will occur */
wire [1:0] notModifiedRMode, notRoundingMode, RoundingMode;

ME_INVA cmpbits  (CMPDecoded, notCMPDecoded);
ME_AND2 rmcmp1   (OprRoundMode[1], notCMPDecoded, CMPRMode1);
ME_AND2_B fgf    (RomSetRModeMinus, notAbortWB, RModeFromMinus);
ME_NOR3 rmcmpe1  (CMPRMode1, CMPEDecoded, RModeFromMinus, notModifiedRMode[1]);
ME_NOR3 rmcmpe0  (OprRoundMode[0], CMPEDecoded,    RModeFromMinus, notModifiedRMode[0]);

/* RoundingMode is latched from status register at the begining of
   a new instruction. It is transient therefore. */

ME_OR2_B fgfo (RModeFromMinus, LoadOprs, RMLatchEnable);

ME_NMUX2B rm0m (RMLatchEnable, notRoundingMode[0], notModifiedRMode[0], U_RoundingMode[0]);
ME_FD1    rm0f (Phi, U_RoundingMode[0], RoundingMode[0], notRoundingMode[0]);
ME_NMUX2B rm1m (RMLatchEnable, notRoundingMode[1], notModifiedRMode[1], U_RoundingMode[1]);
ME_FD1    rm1f (Phi, U_RoundingMode[1], RoundingMode[1], notRoundingMode[1]);

ME_AND2 rmc (RoundingMode[0], RoundingMode[1], RModeMinus); 

endmodule

module KeyboardDecoder(
    output reg [511:0] key_down,
    output wire [8:0] last_change,
    output reg key_valid,
    inout wire PS2_DATA,
    inout wire PS2_CLK,
    input wire rst,
    input wire clk
);

    parameter [1:0] INIT          = 2'b00;
    parameter [1:0] WAIT_FOR_SIGNAL = 2'b01;
    parameter [1:0] GET_SIGNAL_DOWN = 2'b10;
    parameter [1:0] WAIT_RELEASE    = 2'b11;

    parameter [7:0] IS_INIT        = 8'hAA;
    parameter [7:0] IS_EXTEND      = 8'hE0;
    parameter [7:0] IS_BREAK       = 8'hF0;

    reg [9:0] key;      // key = {been_extend, been_break, key_in}
    reg [1:0] state;
    reg been_ready, been_extend, been_break;

    wire [7:0] key_in;
    wire is_extend;
    wire is_break;
    wire valid;
    wire err;

    wire [511:0] key_decode = 1 << last_change;
    assign last_change = {key[9], key[7:0]};

    KeyboardCtrl_0 inst (
        .key_in(key_in),
        .is_extend(is_extend),
        .is_break(is_break),
        .valid(valid),
        .err(err),
        .PS2_DATA(PS2_DATA),
        .PS2_CLK(PS2_CLK),
        .rst(rst),
        .clk(clk)
    );

    always @ (posedge clk, posedge rst) begin
        if (rst) begin
            state <= INIT;
            been_ready  <= 1'b0;
            been_extend <= 1'b0;
            been_break  <= 1'b0;
            key <= 10'b0_0_0000_0000;
        end else begin
            state <= state;
            been_ready  <= been_ready;
            been_extend <= (is_extend) ? 1'b1 : been_extend;
            been_break  <= (is_break ) ? 1'b1 : been_break;
            key <= key;
            case (state)
                INIT : begin
                        if (key_in == IS_INIT) begin
                            state <= WAIT_FOR_SIGNAL;
                            been_ready  <= 1'b0;
                            been_extend <= 1'b0;
                            been_break  <= 1'b0;
                            key <= 10'b0_0_0000_0000;
                        end else begin
                            state <= INIT;
                        end
                    end
                WAIT_FOR_SIGNAL : begin
                        if (valid == 0) begin
                            state <= WAIT_FOR_SIGNAL;
                            been_ready <= 1'b0;
                        end else begin
                            state <= GET_SIGNAL_DOWN;
                        end
                    end
                GET_SIGNAL_DOWN : begin
                        state <= WAIT_RELEASE;
                        key <= {been_extend, been_break, key_in};
                        been_ready  <= 1'b1;
                    end
                WAIT_RELEASE : begin
                        if (valid == 1) begin
                            state <= WAIT_RELEASE;
                        end else begin
                            state <= WAIT_FOR_SIGNAL;
                            been_extend <= 1'b0;
                            been_break  <= 1'b0;
                        end
                    end
                default : begin
                        state <= INIT;
                        been_ready  <= 1'b0;
                        been_extend <= 1'b0;
                        been_break  <= 1'b0;
                        key <= 10'b0_0_0000_0000;
                    end
            endcase
        end
    end

    always @ (posedge clk, posedge rst) begin
        if (rst) begin
            key_valid <= 1'b0;
            key_down <= 511'b0;
        end else if (key_decode[last_change] && been_ready) begin
            key_valid <= 1'b1;
            if (key[8] == 0) begin
                key_down <= key_down | key_decode;
            end else begin
                key_down <= key_down & (~key_decode);
            end
        end else begin
            key_valid <= 1'b0;
            key_down <= key_down;
        end
    end

endmodule

module fifo_module (
    input wire rclk, wclk, rrst_n, wrst_n, rinc, winc,
    input wire [7:0] din,
    output wire [7:0] dout,
    output reg rempty, wfull
);

parameter DEPTH = 16;
parameter ADDR_WIDTH = $clog2(DEPTH);

reg [ADDR_WIDTH-1:0] rptr, wptr;
reg [7:0] memory [DEPTH-1:0];

wire [ADDR_WIDTH-1:0] gray_rptr, gray_wptr;
assign gray_rptr = rptr ^ (rptr >> 1);
assign gray_wptr = wptr ^ (wptr >> 1);

assign dout = memory[gray_rptr];

always @(posedge rclk or negedge rrst_n) begin
    if (!rrst_n) begin
        rempty <= 1'b1;
        rptr <= 0;
    end else if (rinc && !rempty) begin
        rptr <= gray_rptr + 1;
        rempty <= (gray_wptr == gray_rptr + 1);
    end
end

always @(posedge wclk or negedge wrst_n) begin
    if (!wrst_n) begin
        wptr <= 0;
        wfull <= 1'b0;
    end else if (winc && !wfull) begin
        wptr <= gray_wptr + 1;
        memory[gray_wptr] <= din;
        wfull <= (gray_wptr == gray_rptr);
    end
end

endmodule

