module comparator #
(
parameter ERROR_COUNT = 8,
parameter ERROR_HOLD  = 2500000
)
(
input  wire CLK,
input  wire RST,

input  wire I_DAT_REF,
input  wire I_DAT_IOB,

output wire O_ERROR
);

// ============================================================================
// Data latch
reg [2:0] i_dat_ref_sr;
reg [2:0] i_dat_iob_sr;

always @(posedge CLK)
    i_dat_ref_sr <= (i_dat_ref_sr << 1) | I_DAT_REF;
always @(posedge CLK)
    i_dat_iob_sr <= (i_dat_iob_sr << 1) | I_DAT_IOB;

wire i_dat_ref = i_dat_ref_sr[2];
wire i_dat_iob = i_dat_iob_sr[2];

// ============================================================================
// Shift register for reference data, shift strobe generator.
reg  [31:0] sreg;
reg  [ 4:0] sreg_sel;
wire        sreg_dat;
reg         sreg_sh;

always @(posedge CLK)
    sreg <= (sreg << 1) | i_dat_ref;

always @(posedge CLK)
    if (RST)
        sreg_sel <= 0;
    else if(sreg_sh)
        sreg_sel <= sreg_sel + 1;

assign sreg_dat = sreg[sreg_sel];

// ============================================================================
// Comparator and error counter
wire        cmp_err;
reg  [31:0] err_cnt;

assign cmp_err = sreg_dat ^ i_dat_iob;

always @(posedge CLK)
    if (RST)
        err_cnt <= 0;
    else if(sreg_sh)
        err_cnt <= 0;
    else if(cmp_err)
        err_cnt <= err_cnt + 1;

always @(posedge CLK)
    if (RST)
        sreg_sh <= 0;
    else if(~sreg_sh && (err_cnt == ERROR_COUNT))
        sreg_sh <= 1;
    else
        sreg_sh <= 0;

// ============================================================================
// Output generator
reg [24:0] o_cnt;

always @(posedge CLK)
    if (RST)
        o_cnt <= -1;
    else if (cmp_err)
        o_cnt <= ERROR_HOLD - 2;
    else if (~o_cnt[24])
        o_cnt <= o_cnt - 1;

assign O_ERROR = !o_cnt[24];

endmodule

module four_bit_adder(
  input [3:0] A,
  input [3:0] B,
  output [3:0] S,
  output Cout
);

  wire [3:0] C;

  assign S = A + B;
  assign Cout = C[3];

  ripple_carry_adder rca(
    .A(A),
    .B(B),
    .Cin(1'b0),
    .S(S),
    .C(C)
  );

endmodule

module ripple_carry_adder(
  input [3:0] A,
  input [3:0] B,
  input Cin,
  output [3:0] S,
  output [3:0] C
);

  wire [3:0] X;
  wire [3:0] Y;

  assign X = A ^ B;
  assign Y = A & B;

  assign S = X ^ Cin;
  assign C[0] = Y | (X & Cin);

  genvar i;

  generate
    for (i = 1; i < 4; i = i + 1) begin : ripple_carry_adder_loop
      assign X[i] = S[i-1] ^ Y[i-1];
      assign Y[i] = S[i-1] & Y[i-1];

      assign S[i] = X[i] ^ C[i-1];
      assign C[i] = Y[i] | (X[i] & C[i-1]);
    end
  endgenerate

endmodule

module IR_comm (
  input clk, rst, mode,
  input [n-1:0] data_in,
  output reg ir_out,
  output [n-1:0] data_out
);

parameter n = 8; // number of bits in the data signal
parameter m = 50; // frequency of the clock signal
parameter p = 38; // carrier frequency of the modulated infrared signal

reg [n-1:0] data_reg;
reg [n-1:0] data_out_reg;
reg [1:0] state;
reg [31:0] counter;
reg [31:0] bit_counter;
reg [31:0] pulse_counter;
reg [31:0] pulse_length;
reg [31:0] bit_length;
reg [1:0] pulse_state;
reg [1:0] bit_state;

wire clk_div;
wire pulse;
wire bit;

assign clk_div = (counter == (m/2)-1);
assign pulse = (pulse_counter == pulse_length);
assign bit = (bit_counter == bit_length);

always @(posedge clk or posedge rst) begin
  if (rst) begin
    state <= 2'b00;
    counter <= 0;
    data_reg <= 0;
    data_out_reg <= 0;
    pulse_counter <= 0;
    bit_counter <= 0;
    pulse_length <= 0;
    bit_length <= 0;
    pulse_state <= 2'b00;
    bit_state <= 2'b00;
  end else begin
    counter <= counter + 1;
    case (state)
      2'b00: begin // idle
        ir_out <= 1'b0;
        if (mode == 1'b1) begin
          state <= 2'b01;
        end
      end
      2'b01: begin // transmit
        case (pulse_state)
          2'b00: begin // pulse off
            if (clk_div) begin
              pulse_counter <= pulse_counter + 1;
              if (pulse) begin
                pulse_state <= 2'b01;
                pulse_counter <= 0;
              end
            end
          end
          2'b01: begin // pulse on
            if (clk_div) begin
              pulse_counter <= pulse_counter + 1;
              if (!pulse) begin
                pulse_state <= 2'b00;
                pulse_counter <= 0;
                if (bit_counter == n) begin
                  state <= 2'b00;
                  bit_counter <= 0;
                end else begin
                  bit_state <= 2'b00;
                end
              end
            end
          end
        endcase
        case (bit_state)
          2'b00: begin // bit start
            if (pulse_state == 2'b00) begin
              bit_length <= m/p;
              bit_counter <= bit_counter + 1;
              bit_state <= 2'b01;
              data_reg <= {data_in[n-1], data_in};
              data_out_reg <= data_in;
            end
          end
          2'b01: begin // bit data
            if (bit) begin
              ir_out <= data_reg[0];
              data_reg <= {data_reg[n-2:0], 1'b0};
              bit_state <= 2'b10;
            end
          end
          2'b10: begin // bit end
            if (bit) begin
              ir_out <= 1'b0;
              bit_state <= 2'b00;
            end
          end
        endcase
      end
      2'b10: begin // receive
        // TODO: implement receiver block
      end
    endcase
  end
end

assign data_out = data_out_reg;

endmodule

module ripple_carry_adder (
    input [3:0] in0,
    input [3:0] in1,
    input carry_in,
    output reg [3:0] sum,
    output reg carry_out
);

reg [3:0] stage1_sum;
reg stage1_carry;

reg [3:0] stage2_sum;
reg stage2_carry;

reg [3:0] stage3_sum;
reg stage3_carry;

// Stage 1
full_adder fa1(in0[0], in1[0], carry_in, stage1_sum[0], stage1_carry);

// Stage 2
full_adder fa2(in0[1], in1[1], stage1_carry, stage2_sum[1], stage2_carry);

// Stage 3
full_adder fa3(in0[2], in1[2], stage2_carry, stage3_sum[2], stage3_carry);

// Stage 4
full_adder fa4(in0[3], in1[3], stage3_carry, sum[3], carry_out);

assign sum[0] = stage1_sum[0];
assign sum[1] = stage2_sum[1];
assign sum[2] = stage3_sum[2];

endmodule

module full_adder (
    input a,
    input b,
    input carry_in,
    output reg sum,
    output reg carry_out
);

always @(*) begin
    sum = a ^ b ^ carry_in;
    carry_out = (a & b) | (a & carry_in) | (b & carry_in);
end

endmodule

module CDR (
  input data_in,
  input ref_clk,
  output clk_out,
  output data_out
);

  // Define PLL parameters
  parameter integer N = 10; // PLL divider
  parameter integer M = 100; // PLL multiplier
  parameter integer C = 10; // PLL loop filter coefficient

  // Define internal signals
  reg pll_clk;
  reg [N-1:0] pll_counter;
  reg [31:0] phase_accumulator;
  wire [31:0] phase_increment;
  wire [31:0] phase_error;
  wire [31:0] loop_filter_output;

  // Generate phase increment
  assign phase_increment = (ref_clk * M) / (1 << N);

  // Calculate phase error
  assign phase_error = phase_accumulator - (data_in * (1 << 31));

  // Calculate loop filter output
  assign loop_filter_output = phase_error * C;

  // Update phase accumulator
  always @(posedge pll_clk) begin
    phase_accumulator <= phase_accumulator + phase_increment + loop_filter_output;
  end

  // Generate recovered clock
  always @(posedge pll_clk) begin
    if (pll_counter == (N-1)) begin
      pll_counter <= 0;
      clk_out <= ~clk_out;
    end else begin
      pll_counter <= pll_counter + 1;
    end
  end

  // Generate recovered data
  always @(posedge clk_out) begin
    data_out <= data_in;
  end

  // Initialize internal signals
  initial begin
    pll_clk <= 0;
    pll_counter <= 0;
    phase_accumulator <= 0;
  end

  // Generate PLL clock
  always @(posedge ref_clk) begin
    pll_clk <= ~pll_clk;
  end

endmodule

