module top_module (
    input up_down,
    input reset,
    input count_up_clk,
    input count_down_clk,
    input [3:0] A,
    input [3:0] B,
    output reg [7:0] Y
);

reg [3:0] count_reg;
reg [3:0] A_reg;
reg [3:0] B_reg;
reg [2:0] booth_reg;

always @(posedge count_up_clk or posedge count_down_clk) begin
    if (reset) begin
        count_reg <= 4'b0000;
        A_reg <= A;
        B_reg <= B;
        booth_reg <= 3'b000;
    end else begin
        if (up_down) begin
            count_reg <= count_reg + 1;
        end else begin
            count_reg <= count_reg - 1;
        end
    end
end

always @(posedge count_up_clk or posedge count_down_clk) begin
    if (reset) begin
        Y <= 8'b00000000;
    end else begin
        if (booth_reg == 3'b000) begin
            Y <= {1'b0, Y[7:1]};
        end else if (booth_reg == 3'b001 || booth_reg == 3'b111) begin
            Y <= Y + (A_reg << 4);
        end else if (booth_reg == 3'b010 || booth_reg == 3'b110) begin
            Y <= Y + (A_reg << 3);
        end else if (booth_reg == 3'b100 || booth_reg == 3'b101) begin
