module magnitude_comparator_selector (
    input [3:0] a,
    input [3:0] b,
    input [1:0] select,
    output reg [2:0] comparison_result,
    output reg [1:0] selected_input
);

    always @ (a or b or select) begin
        if (select == 2'b00) begin
            comparison_result = (a > b) ? 3'b001 : (a < b) ? 3'b010 : 3'b000;
            selected_input = 2'b00;
        end
        else if (select == 2'b01) begin
            comparison_result = (a > b) ? 3'b010 : (a < b) ? 3'b001 : 3'b000;
            selected_input = 2'b01;
        end
    end

endmodule

module final_output (
    input [3:0] binary_adder_output,
    input [2:0] comparison_result,
    input [3:0] a,
    input [3:0] b,
    output reg [3:0] result
);

    always @ (binary_adder_output or comparison_result or a or b) begin
        case (comparison_result)
            3'b000: result = binary_adder_output;
            3'b001: result = b;
            3'b010: result = a;
            3'b011: result = 4'b1111;
            3'b100: result = 4'b0000;
            3'b101: result = ~binary_adder_output;
            3'b110: result = binary_adder_output & b;
            3'b111: result = binary_adder_output | a;
        endcase
    end

endmodule

