module byte_pattern_detection (
    input clk,
    input reset,            // Synchronous reset
    input [7:0] d,
    output [7:0] q,
    output reg pattern_detected,
    output [7:0] final_output );

    reg [7:0] shift_reg;
    reg [7:0] pattern = 8'b10101010; // Pattern to detect
    reg [7:0] output_reg;

    reg [2:0] state = 3'b000; // State machine

    always @(negedge clk) begin
        if (reset) begin
            shift_reg <= 8'b0;
            state <= 3'b000;
            pattern_detected <= 1'b0;
            output_reg <= 8'b0;
        end
        else begin
            shift_reg <= {shift_reg[6:0], d};

            case (state)
                3'b000: begin // Idle state
                    if (shift_reg == pattern) begin
                        state <= 3'b001;
                    end
                end
                3'b001: begin // Pattern detected
                    pattern_detected <= 1'b1;
                    output_reg <= shift_reg;
                    state <= 3'b010;
                end
                3'b010: begin // Output final value
                    final_output <= output_reg;
                    state <= 3'b011;
                end
                3'b011: begin // Wait for reset
                    if (reset) begin
                        state <= 3'b000;
                        pattern_detected <= 1'b0;
                        output_reg <= 8'b0;
                    end
                end
            endcase
        end
    end

    assign q = shift_reg;

endmodule

