module sfifo_nto8 (
        clk         ,   // clock
        ce          ,   // clock enable
        nrst        ,   // asyn reset
        reset       ,   // sync reset
        din         ,   // data input
        dout        ,   // data output
        rd          ,   // read
        wr          ,   // write
        full        ,   // fifo full
        empty       ,   // fifo empty
        nsin        ,   // num of shift in (bits)
        nsout           // num of shift out (bits)
        ) ;

input           clk ;
input           ce ;
input           nrst ;
input           reset ;
input   [7:0]   din ;
output  [7:0]   dout ;
input           rd ;
input           wr ;
output          full ;
output          empty ;
input   [3:0]   nsin ;
input   [3:0]   nsout ;

//=========================================
// Internal signal
//=========================================
reg     [23:0]  buffer ;        // 24-bit buffer
reg     [5:0]   cnt ;           // counter to record num of bits loaded into buffer
wire    [31:0]  shift_out ;
wire    [31:0]  shift_in ;
wire    [5:0]   space_left ;

//=========================================
// Main RTL
//=========================================
assign dout = shift_out [31:24] ;
assign full = (cnt + nsin) > 24 ;
assign empty = cnt < nsout ;

always @ (posedge clk or negedge nrst)
  if (~nrst)
    cnt <= 0 ;
  else if (ce)
  begin
    if (reset)
      cnt <= 0 ;
    else
    begin
      if (wr & rd)
        cnt <= cnt + nsin - nsout ;
      if (wr & ~rd)
        cnt <= cnt + nsin ;
      if (~wr & rd)
        cnt <= cnt - nsout ;
    end
  end

assign shift_out = {8'h0, buffer} << nsout ;  
assign space_left = rd ? 24 -cnt + nsout : 24 -cnt ;  
assign shift_in = {24'h0, din} << space_left ;

always @ (posedge clk or negedge nrst)
  if (~nrst)
    buffer <= 0 ;
  else if (ce)
  begin
    if (reset)
      buffer <= 0 ;
    else
    begin
      if (wr & rd)
        buffer <= shift_out [23:0] | shift_in [31:8] ;
      if (wr & ~rd)
        buffer <= buffer | shift_in [31:8] ;
      if (~wr & rd)
        buffer <= shift_out [23:0] ;
    end
  end  

endmodule

module zap_wb_merger (
    input wire i_clk,   
    input wire i_reset,
    input wire i_c_wb_stb,
    input wire i_c_wb_cyc,
    input wire i_c_wb_wen,
    input wire [3:0] i_c_wb_sel,
    input wire [31:0] i_c_wb_dat,
    input wire [31:0] i_c_wb_adr,
    input wire [2:0] i_c_wb_cti,
    output reg o_c_wb_ack,
    input wire i_d_wb_stb,
    input wire i_d_wb_cyc,
    input wire i_d_wb_wen,
    input wire [3:0] i_d_wb_sel,
    input wire [31:0] i_d_wb_dat,
    input wire [31:0] i_d_wb_adr,
    input wire [2:0] i_d_wb_cti,
    output reg o_d_wb_ack,
    output reg o_wb_cyc,
    output reg o_wb_stb,
    output reg o_wb_wen,
    output reg [3:0] o_wb_sel,
    output reg [31:0] o_wb_dat,
    output reg [31:0] o_wb_adr,
    output reg [2:0] o_wb_cti,
    input wire i_wb_ack
);

localparam CODE = 1'd0;
localparam DATA = 1'd1;

reg sel_ff, sel_nxt;

always @ (posedge i_clk)
begin
    if (i_reset)
        sel_ff <= CODE;
    else
        sel_ff <= sel_nxt;
end

always @*
begin
    if (sel_ff == CODE)
    begin
        o_c_wb_ack = i_wb_ack;
        o_d_wb_ack = 1'd0;
    end
    else
    begin
        o_d_wb_ack = i_wb_ack;
        o_c_wb_ack = 1'd0;
    end
end

always @*
begin
    sel_nxt = sel_ff;

    case(sel_ff)
        CODE:
        begin
            if (i_wb_ack && (o_wb_cti == CTI_CLASSIC || o_wb_cti == CTI_EOB) && i_d_wb_stb)
                sel_nxt = DATA;
            else if (!i_c_wb_stb && i_d_wb_stb)
                sel_nxt = DATA;
            else
                sel_nxt = sel_ff;
        end

        DATA:
        begin
            if (i_wb_ack && (o_wb_cti == CTI_CLASSIC || o_wb_cti == CTI_EOB) && i_c_wb_stb)
                sel_nxt = CODE;
            else if (i_c_wb_stb && !i_d_wb_stb)
                sel_nxt = CODE;
            else
                sel_nxt = sel_ff;
        end
    endcase
end

always @ (posedge i_clk)
begin
    if (i_reset)
    begin
        o_wb_cyc <= 0;
        o_wb_stb <= 0;
        o_wb_wen <= 0;
        o_wb_sel <= 0;
        o_wb_dat <= 0;                                
        o_wb_adr <= 0;
        o_wb_cti <= 0;
    end
    else if (sel_nxt == CODE)
    begin
        o_wb_cyc <= i_c_wb_cyc;
        o_wb_stb <= i_c_wb_stb;
        o_wb_wen <= i_c_wb_wen;
        o_wb_sel <= i_c_wb_sel;
        o_wb_dat <= i_c_wb_dat;                                
        o_wb_adr <= i_c_wb_adr;
        o_wb_cti <= i_c_wb_cti;               
    end
    else
    begin
        o_wb_cyc <= i_d_wb_cyc;
        o_wb_stb <= i_d_wb_stb;
        o_wb_wen <= i_d_wb_wen;
        o_wb_sel <= i_d_wb_sel;
        o_wb_dat <= i_d_wb_dat;                                
        o_wb_adr <= i_d_wb_adr;
        o_wb_cti <= i_d_wb_cti; 
    end
end

endmodule

module pace_catcher
(
  clk_fast,
  clk_slow,
  signal_i,
  signal_o
);

  //////////// INPUTS & OUTPUTS ////////////
  input clk_fast;
  input clk_slow;
  input signal_i;
  output signal_o;

  //////////// PARAMETERS ////////////
  parameter COUNT = 15; // with clk of 1.5kHz corresponds to 10ms width

  parameter s_idle = 0;
  parameter s_out = 1;

  //////////// SIGNALS & REGS ////////////
  reg[15:0] cnt = 0;
  reg state = 0;

  //////////// LOGIC ////////////

  // runs at fast clock to catch input signal
  always @(posedge clk_fast) begin
    case(state)
      s_idle:
      begin
        state <= (signal_i) ? s_out : s_idle;
      end
      s_out:
      begin
        state <= (cnt >= COUNT) ? s_idle : s_out;
      end
    endcase
  end

  // runs at slow clock to increment slowly
  always @(posedge clk_slow) begin
    if (state == s_out) cnt <= cnt + 8'b1;
    else if (state == s_idle) cnt  <= 8'b0;
  end

  //////////// OUTPUT ASSIGNS ////////////
  assign signal_o = (state == s_out);

endmodule

module rotator(
    input clk,
    input load,
    input [1:0] ena,
    input [99:0] data,
    output reg [99:0] q
);

reg [99:0] reg1, reg2, reg3;

always @(posedge clk) begin
    if(load) begin
        reg1 <= data;
        reg2 <= reg1;
        reg3 <= reg2;
        q <= reg3;
    end else begin
        case(ena)
            2'b00: begin
                reg1 <= {reg1[98:0], reg1[99]};
                reg2 <= {reg2[98:0], reg2[99]};
                reg3 <= {reg3[98:0], reg3[99]};
                q <= reg3;
            end
            2'b01: begin
                reg1 <= {reg1[1:99], reg1[0]};
                reg2 <= {reg2[1:99], reg2[0]};
                reg3 <= {reg3[1:99], reg3[0]};
                q <= reg3;
            end
            2'b10: begin
                reg1 <= {reg1[1:99], reg1[0]};
                reg2 <= {reg2[1:99], reg2[0]};
                reg3 <= {reg3[1:99], reg3[0]};
                q <= reg3;
            end
            2'b11: begin
                reg1 <= {reg1[98:0], reg1[99]};
                reg2 <= {reg2[98:0], reg2[99]};
                reg3 <= {reg3[98:0], reg3[99]};
                q <= reg3;
            end
        endcase
    end
end

endmodule

module greater_than (
    input [7:0] A,
    input [7:0] B,
    input [7:0] C,
    output Y
);

    assign Y = (A >= B) && (C < B);

endmodule

module ID_EX(
input Clk,
input stall,
input flush,
input [31:0]PC_4_ID,
input [5:0]op_ID,
input [2:0]Condition_ID,
input Branch_ID,
input MemWrite_ID,
input RegWrite_ID,
input MemRead_ID,
input Jump_ID,
input [1:0] ExResultSrc_ID,
input ALUSrcA_ID,
input ALUSrcB_ID,
input [3:0]ALUop_ID,
input [1:0]regdst_ID,
input ShiftAmountSrc_ID,
input [1:0]ShiftOp_ID,
input [31:0]A_in_ID,
input [31:0]B_in_ID,
input [4:0]Rs_ID,
input [4:0]Rt_ID,
input [4:0]Rd_ID,
input [31:0]Immediate32_ID,
input [4:0]Shamt_ID,
input loaduse_in,
output reg [31:0]PC_4_EX,
output reg [5:0]op_EX,
output reg [2:0]Condition_EX,
output reg Branch_EX,
output reg MemWrite_EX,
output reg RegWrite_EX,
output reg MemRead_EX,
output reg Jump_EX,
output reg [1:0]ExResultSrc_EX,
output reg ALUSrcA_EX,
output reg ALUSrcB_EX,
output reg [3:0]ALUop_EX,
output reg [1:0]regdst_EX,
output reg ShiftAmountSrc_EX,
output reg [1:0]ShiftOp_EX,
output reg [31:0]A_in_EX,
output reg [31:0]B_in_EX,
output reg [4:0]Rs_EX,
output reg [4:0]Rt_EX,
output reg [4:0]Rd_EX,
output reg [31:0]Immediate32_EX,
output reg [4:0]Shamt_EX,
output reg loaduse_out
);

// Initialize all outputs to zero
initial
begin
PC_4_EX=32'b0;
op_EX=6'b0;
Condition_EX=3'b0;
Branch_EX=0;
MemWrite_EX=0;
RegWrite_EX=0;
MemRead_EX=0;
Jump_EX=0;
ExResultSrc_EX=2'b0;
ALUSrcA_EX=0;
ALUSrcB_EX=0;
ALUop_EX=4'b0;
regdst_EX=2'b0;
ShiftAmountSrc_EX=0;
ShiftOp_EX=2'b0;
A_in_EX=32'b0;
B_in_EX=32'b0;
Rs_EX=5'b0;
Rt_EX=5'b0;
Rd_EX=5'b0;
Immediate32_EX=32'b0;
Shamt_EX=5'b0;
loaduse_out = 0;
end

// On each clock cycle, forward inputs to outputs
always @(negedge Clk)begin
    loaduse_out <= loaduse_in;
    if(flush)begin
        // If flush signal is set, reset all outputs to zero to avoid errors
        PC_4_EX=32'b0;
        op_EX=6'b0;
        Condition_EX=3'b0;
        Branch_EX=0;
        MemWrite_EX=0;
        RegWrite_EX=0;
        MemRead_EX=0;
        Jump_EX=0;
        ExResultSrc_EX=2'b0;
        ALUSrcA_EX=0;
        ALUSrcB_EX=0;
        ALUop_EX=4'b0;
        regdst_EX=2'b0;
        ShiftAmountSrc_EX=0;
        ShiftOp_EX=2'b0;
        A_in_EX=32'b0;
        B_in_EX=32'b0;
        Rs_EX=5'b0;
        Rt_EX=5'b0;
        Rd_EX=5'b0;
        Immediate32_EX=32'b0;
        Shamt_EX=5'b0;
    end
    else if(!stall)begin
        // If not stalled, forward inputs to outputs
        PC_4_EX <= PC_4_ID;
        op_EX <= op_ID;
        Condition_EX <= Condition_ID;
        Branch_EX <= Branch_ID;
        MemWrite_EX <= MemWrite_ID;
        RegWrite_EX <= RegWrite_ID;
        MemRead_EX <= MemRead_ID;
        Jump_EX <= Jump_ID;
        ExResultSrc_EX <= ExResultSrc_ID;
        ALUSrcA_EX <= ALUSrcA_ID;
        ALUSrcB_EX <= ALUSrcB_ID;
        ALUop_EX <= ALUop_ID;
        regdst_EX <= regdst_ID;
        ShiftAmountSrc_EX <= ShiftAmountSrc_ID;
        ShiftOp_EX <= ShiftOp_ID;
        A_in_EX <= A_in_ID;
        B_in_EX <= B_in_ID;
        Rs_EX <= Rs_ID;
        Rt_EX <= Rt_ID;
        Rd_EX <= Rd_ID;
        Immediate32_EX <= Immediate32_ID;
        Shamt_EX <= Shamt_ID;
    end
    // If stalled, do nothing and hold current values
end

endmodule

module four_bit_adder (
    a,
    b,
    cin,
    sum,
    cout
);

    input [3:0] a, b;
    input cin;
    output [3:0] sum;
    output cout;

    wire [3:0] temp_sum;
    wire [4:0] temp_cout;

    assign temp_sum = a + b + cin;
    assign temp_cout = {1'b0, temp_sum} + {1'b0, ~a, 1'b1} + {1'b0, ~b, 1'b1} + {1'b0, ~cin, 1'b1};

    assign sum = temp_sum;
    assign cout = temp_cout[4];

endmodule

module binary_decoder (
    input wire [2:0] in_vec,
    output wire o2,
    output wire o1,
    output wire o0
);

    assign o2 = in_vec[2];
    assign o1 = in_vec[1];
    assign o0 = in_vec[0];

endmodule

module binary_mux (
    input wire [2:0] in_vec,
    output wire [2:0] out_vec,
    input wire sel
);

    assign out_vec = (sel == 1'b0) ? in_vec : 3'b000;

endmodule

module top_module (
    input wire [2:0] vec,
    output wire [2:0] outv,
    output wire o2,
    output wire o1,
    output wire o0
);

    wire [2:0] mux_out;
    wire dec_o2, dec_o1, dec_o0;

    binary_mux mux_inst (
        .in_vec(vec),
        .out_vec(mux_out),
        .sel(1'b1)
    );

    binary_decoder dec_inst (
        .in_vec(vec),
        .o2(dec_o2),
        .o1(dec_o1),
        .o0(dec_o0)
    );

    assign outv = mux_out;

    assign o2 = (mux_out == 3'b000) ? dec_o2 : 1'b0;
    assign o1 = (mux_out == 3'b000) ? dec_o1 : 1'b0;
    assign o0 = (mux_out == 3'b000) ? dec_o0 : 1'b0;

endmodule

module binary_counter(
  input clk, 
  input rst, 
  output reg [3:0] count
);

  always @ (posedge clk or posedge rst) begin
    if (rst) begin
      count <= 4'b0000;
    end else begin
      count <= count + 1;
    end
  end

endmodule

module pcie_data_sender #(parameter C_PCI_DATA_WIDTH = 128, INPUT_DATA_WIDTH = 8, NUM_PES = 8) (
        input clk,
        input rst,

        //Collector Interface
        output coll_ready,
        input coll_data_valid,
        input[INPUT_DATA_WIDTH - 1:0] coll_data,

        //RIFFA TX Interface
        output CHNL_TX, 
        input CHNL_TX_ACK, 
        output CHNL_TX_LAST, 
        output[`SIG_CHNL_LENGTH_W - 1:0] CHNL_TX_LEN, 
        output[30:0] CHNL_TX_OFF, 
        output[C_PCI_DATA_WIDTH - 1:0] CHNL_TX_DATA, 
        output reg CHNL_TX_DATA_VALID, 
        input CHNL_TX_DATA_REN,

        input[`SIG_CHNL_LENGTH_W - 1:0] dna_len,
        output idle,
        input en
    );

    localparam DATA_PER_TX = C_PCI_DATA_WIDTH/INPUT_DATA_WIDTH; //number of data chunks that can fit with in C_PCI_DATA_WIDTH
    parameter IT_BITS = $clog2(DATA_PER_TX);


    reg state = STATE_IDLE;
    localparam STATE_IDLE = 1'b0;
    localparam STATE_SENDING = 1'b1;

    reg[`SIG_CHNL_LENGTH_W - 1:0] dna_len_r, send_len;

    reg tx_issued;
    //state transition logic
    always@(posedge clk) begin
        if(rst) begin
            state <= STATE_IDLE;
            dna_len_r <= 0;
            send_len <= 0;
        end
        else begin
            case(state)
                STATE_IDLE: begin
                    if(en) begin
                        dna_len_r <= (dna_len - NUM_PES)*NUM_PES >> 7 /*to 128-bit chunks*/ ; // excluding reference dna reads
                        send_len <= (dna_len - NUM_PES)*NUM_PES >> 5/*to 32-bit words*/; // excluding reference dna reads
                        state <= STATE_SENDING;
                    end
                end //STATE_IDLE
                STATE_SENDING: begin
                    if(tx_issued) begin
                        dna_len_r <= dna_len_r - 1;

                        if(dna_len_r == 1) begin
                            state <= STATE_IDLE;
                        end
                    end
                end //STATE_SENDING

            endcase
        end
    end

    assign idle = (state == STATE_IDLE);


    //Register Input Data
    reg[INPUT_DATA_WIDTH - 1:0] data_r;
    reg data_valid_r;
    wire fetch_input = coll_ready;

    always@(posedge clk) begin
        if(rst) begin
            data_r <= 0;
            data_valid_r <= 0;
        end
        else begin
            if(fetch_input) begin
                data_r <= coll_data;
                data_valid_r <= coll_data_valid;
            end
        end
    end

    //Put data chuck in tx buffer
    reg[IT_BITS - 1:0] iter = 0;
    reg[C_PCI_DATA_WIDTH - 1:0] tx_buffer;
    reg tx_buffer_valid = 0;

    always@(posedge clk) begin
        if(rst) begin
            tx_buffer <= 0;
            tx_buffer_valid <= 0;
        end
        else begin
            if(data_valid_r && coll_ready) begin
                tx_buffer[iter*INPUT_DATA_WIDTH +:INPUT_DATA_WIDTH] <= data_r;
                iter <= iter + 1'b1;

                tx_buffer_valid <= &iter;
            end
            else if(tx_issued) begin
                tx_buffer_valid <= 1'b0;
            end
        end
    end

    //TODO: consider adding one more register stage for better timing

    //Send tx buffer to RIFFA
    assign CHNL_TX_LEN = send_len; //C_PCI_DATA_WIDTH/32;
    assign CHNL_TX_LAST = 1'b1; //(dna_len_r == 1);
    assign CHNL_TX_OFF = 0;
    assign CHNL_TX_DATA = tx_buffer;
    assign CHNL_TX = (state == STATE_SENDING);

    always@* begin
        tx_issued = 1'b0;
        CHNL_TX_DATA_VALID = 1'b0;

        if(state == STATE_SENDING) begin
            if(tx_buffer_valid) begin
                CHNL_TX_DATA_VALID = 1'b1;

                if(CHNL_TX_DATA_REN) begin
                    tx_issued = 1'b1;
                end
            end //tx_buffer_valid
        end
    end

    assign coll_ready = ~tx_buffer_valid || (tx_buffer_valid && tx_issued);

endmodule

module uart_tx
   #(
     parameter DBIT = 8,     // # data bits
               SB_tck = 16  // # tcks for stop bits
   )
   (
    input wire clk, reset,
    input wire tx_start, s_tck,
    input wire [7:0] din,
    output reg tx_done_tck,
    output wire tx
   );


   localparam [1:0]init_state  = 2'b00,start = 2'b01,data  = 2'b10,stop  = 2'b11;


   reg [1:0] state, state_next;
   reg [3:0] s, s_next;
   reg [2:0] n, n_next;
   reg [7:0] b, b_next;
   reg tx_reg, tx_next;


   always @(posedge clk)
      if (reset)
         begin
            state <= init_state;
            s <= 0;
            n <= 0;
            b <= 0;
            tx_reg <= 1'b1;
         end
      else
         begin
            state <= state_next;
            s <= s_next;
            n <= n_next;
            b <= b_next;
            tx_reg <= tx_next;
         end


   always @*
   begin
      state_next = state;
      tx_done_tck = 1'b0;
      s_next = s;
      n_next = n;
      b_next = b;
      tx_next = tx_reg ;
      if(state==init_state)
            begin
               tx_next = 1'b1;
               if (tx_start)
                  begin
                     state_next = start;
                     s_next = 0;
                     b_next = din;
                  end
            end
        else if(state==start)
            begin
               tx_next = 1'b0;
               if (s_tck)
                  if (s==15)
                     begin
                        state_next = data;
                        s_next = 0;
                        n_next = 0;
                     end
                  else
                     s_next = s + 1;
            end
         else if(state==data)
            begin
               tx_next = b[0];
               if (s_tck)
                  if (s==15)
                     begin
                        s_next = 0;
                        b_next = b >> 1;
                        if (n==(DBIT-1))
                           state_next = stop ;
                        else
                           n_next = n + 1;
                     end
                  else
                     s_next = s + 1;
            end
         else if(state==stop)
            begin
               tx_next = 1'b1;
               if (s_tck)
                  if (s==(SB_tck-1))
                     begin
                        state_next = init_state;
                        tx_done_tck = 1'b1;
                     end
                  else
                     s_next = s + 1;
            end
   end

   assign tx = tx_reg;

endmodule

module Reg_4bit
   (IN,
    LD,
    SET,
    CLR,
    CLK,
    OUT);
  input [3:0] IN;
  input LD;
  input SET;
  input CLR;
  input CLK;
  output [3:0] OUT;

  reg [3:0] reg_out;

  always @(posedge CLK or posedge CLR or posedge SET)
  begin
    if (CLR) // Asynchronous clear
      reg_out <= 4'b0;
    else if (SET) // Synchronous set
      reg_out <= 4'b1111;
    else if (LD) // Synchronous load
      reg_out <= IN;
  end

  assign OUT = reg_out;

endmodule

module top_module (
    input clk,
    input reset,       // Synchronous active-high reset
    input set_time,    // Input for setting the time
    output [6:0] seg_a, // 7-segment display output for segment A
    output [6:0] seg_b, // 7-segment display output for segment B
    output [6:0] seg_c, // 7-segment display output for segment C
    output [6:0] seg_d, // 7-segment display output for segment D
    output [3:0] dig    // Output for selecting the active digit on the 7-segment display
);

wire [15:0] counter_out;
wire [6:0] mux_out;
wire [15:0] set_time_out;

bcd_counter counter(clk, reset, counter_out);
mux mux_inst(counter_out[3:0], set_time_out[3:0], set_time, mux_out);
functional_module func_inst(mux_out, counter_out, seg_a, seg_b, seg_c, seg_d, dig);

always @(posedge clk) begin
    if (reset) begin
        set_time_out <= 16'b0;
    end else if (set_time) begin
        set_time_out <= {12'b0, set_time};
    end else begin
        if (counter_out == 16'd9999) begin
            set_time_out <= 16'b0;
        end else begin
            set_time_out <= set_time_out + 1;
        end
    end
end

endmodule

module mux (
    input [6:0] in1,   // Input 1 for the multiplexer
    input [6:0] in2,   // Input 2 for the multiplexer
    input select,      // Select input for the multiplexer
    output reg [6:0] y  // Selected output from the multiplexer
);

always @(select or in1 or in2) begin
    if (select) begin
        y <= in2;
    end else begin
        y <= in1;
    end
end

endmodule

module bcd_counter (
    input clk,
    input reset,       // Synchronous active-high reset
    output [15:0] q    // 16-bit binary-coded decimal output from the counter
);

reg [15:0] count;

always @(posedge clk) begin
    if (reset) begin
        count <= 16'b0;
    end else if (count == 16'd9999) begin
        count <= 16'b0;
    end else begin
        count <= count + 1;
    end
end

assign q = count;

endmodule

