module edge_detect_pipeline (
  input               clk,
  input               rst_n,
  input               a,
  output reg          rise,
  output reg          down
);

  reg [1:0]           a_reg [2:0];
  reg [1:0]           diff_reg [1:0];

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      a_reg <= 2'b0;
      diff_reg <= 2'b0;
      rise <= 1'b0;
      down <= 1'b0;
    end else begin
      a_reg[0] <= a;
      a_reg[1] <= a_reg[0];
      a_reg[2] <= a_reg[1];

      diff_reg[0] <= a_reg[1] ^ a_reg[2];
      diff_reg[1] <= a_reg[0] ^ a_reg[1];

      rise <= diff_reg[1][1] & ~diff_reg[1][0];
      down <= diff_reg[0][1] & ~diff_reg[0][0];
    end
  end

endmodule

module four_in_one_out (
    input A1,
    input A2,
    input B1,
    input B2,
    output X
);

    wire [3:0] sum;
    assign sum = A1 + A2 + B1 + B2;

    assign X = (A1 == 1) ? (sum[1:0] + B1 + B2) : sum[3:0];

endmodule

module bitwise_or_diff (A, B, Y);

parameter A_SIGNED = 0;
parameter B_SIGNED = 0;
parameter A_WIDTH = 1;
parameter B_WIDTH = 1;
parameter Y_WIDTH = 1;

localparam WIDTH = A_WIDTH > B_WIDTH ? A_WIDTH : B_WIDTH;

input [A_WIDTH-1:0] A;
input [B_WIDTH-1:0] B;
output [Y_WIDTH-1:0] Y;

wire [WIDTH-1:0] A_buf, B_buf, diff_buf;
wire [WIDTH-1:0] abs_diff_buf;
wire carry, carry_sign;

\$pos #(.A_SIGNED(A_SIGNED), .A_WIDTH(A_WIDTH), .Y_WIDTH(WIDTH)) A_conv (.A(A), .Y(A_buf));
\$pos #(.A_SIGNED(B_SIGNED), .A_WIDTH(B_WIDTH), .Y_WIDTH(WIDTH)) B_conv (.A(B), .Y(B_buf));

assign diff_buf = A_buf - B_buf;
assign abs_diff_buf = (diff_buf < 0) ? -diff_buf : diff_buf;
assign Y = |abs_diff_buf;

endmodule

module EchoCancellation (
  input [n-1:0] in,
  input [m-1:0] ref,
  input reset,
  output [n-1:0] out
);

parameter n = 4; // number of input and output signals
parameter m = 2; // number of reference signals
parameter k = 16; // length of the echo

reg [n-1:0] delay_line [k-1:0]; // delay line to store previous samples of input signal
reg [n-1:0] echo; // echo signal
reg [n-1:0] corr; // correlation signal
reg [n-1:0] out_reg; // output signal register

integer i, j;

always @(posedge clk) begin
  if (reset) begin
    for (i = 0; i < k; i = i + 1) begin
      delay_line[i] <= 0;
    end
    echo <= 0;
    corr <= 0;
    out_reg <= 0;
  end else begin
