    corr <= 0;
    for (i = 0; i < m; i = i + 1) begin
      for (j = 0; j < k; j = j + 1) begin
        corr <= corr + ref[i] * delay_line[j];
      end
    end

    // calculate echo signal
    echo <= corr / (m * k);

    // subtract echo from input signal to generate output signal
    out_reg <= in - echo;
  end
end

