module digital_lock (
  input clk,                 // Clock input
  input reset,               // Synchronous active-high reset
  input [3:0] password,      // 4-bit input for password setting
  input [3:0] input_password,// 4-bit input for password input
  output reg lock_state      // 1-bit output for lock state
);

  // Define state machine states
  parameter IDLE = 2'b00;
  parameter SET_PASSWORD = 2'b01;
  parameter ENTER_PASSWORD = 2'b10;

  // Define counter parameters
  parameter MAX_ATTEMPTS = 3;
  parameter COUNTER_WIDTH = 2;

  // Define state machine signals
  reg [1:0] state;
  reg [3:0] stored_password;
  reg [COUNTER_WIDTH-1:0] attempts;

  // State machine logic
  always @(posedge clk, posedge reset) begin
    if (reset) begin
      state <= IDLE;
      stored_password <= 4'b0000;
      attempts <= 0;
      lock_state <= 1'b1;
    end else begin
      case (state)
        IDLE: begin
          if (password != 4'b0000) begin
            state <= SET_PASSWORD;
          end else if (input_password != 4'b0000) begin
            state <= ENTER_PASSWORD;
          end
        end
        SET_PASSWORD: begin
          stored_password <= password;
          state <= IDLE;
        end
        ENTER_PASSWORD: begin
          if (input_password == stored_password) begin
            state <= IDLE;
            attempts <= 0;
            lock_state <= 1'b0;
          end else begin
            attempts <= attempts + 1;
            if (attempts == MAX_ATTEMPTS) begin
              state <= IDLE;
              attempts <= 0;
              lock_state <= 1'b1;
            end
          end
        end
      endcase
    end
  end

endmodule

