module mac_tb;

    // Parameters
    parameter INTERMEDIATOR_DEPTH = 1024; // Depth of the intermediate register
    parameter LOG2_INTERMEDIATOR_DEPTH = log2(INTERMEDIATOR_DEPTH - 1); // Log2 of the intermediate register depth
    parameter MATRIX_FILENAME = "../../src/tmp/cant/cant.mtx"; // Filename of the Matrix Market file

    // Inputs
    reg clk, rst, wr;
    reg [LOG2_INTERMEDIATOR_DEPTH - 1:0] row;
    reg [63:0] v0, v1;

    // Outputs
    wire push_out;
    wire [63:0] v_out;

    // Control signals
    reg eof;
    wire stall;
    reg stall_out;

    // Instantiate the MAC module
    mac #(INTERMEDIATOR_DEPTH) dut(clk, rst, wr, row, v0, v1, push_out, v_out, eof, stall, stall_out);

    // Clock generation
    initial begin
        clk = 0;
        forever #5 clk = !clk;
    end

    // Read matrix data from file
    reg [63:0] floats [0:10000000];
    reg [63:0] row_index [0:10000000];
    reg [63:0] col_index [0:10000000];
    integer file;
    integer bufferSize = 100;
    reg [100 * 8 - 1:0] string;
    integer M, N, nnz;
    integer r;
    integer i = 0;
    integer tmp1, tmp2;
    real tmp3;
    initial begin
        $readmemh("floats.hex", floats);
        $readmemh("row.hex", row_index);
        $readmemh("col.hex", col_index);
        file = $fopen(MATRIX_FILENAME, "r");
        r = $fgets(string, file);
        r = $fscanf(file, "%d%d%d", M, N, nnz);
        for(i = 0; i < nnz; i = i + 1) begin
            $fscanf(file, "%d%d%f", tmp1, tmp2, tmp3);
            row_index[i] = tmp1 - 1;
            col_index[i] = tmp2 - 1;
            floats[i] = $realtobits(tmp3);
        end
    end

    // Write matrix data to MAC module
    integer stall_count = 0;
    integer out_count;
    initial begin
        rst = 1;
        wr = 0;
        row = 0;
        v0 = 0;
        v1 = 0;
        eof = 0;
        stall_out = 0;
        #1000 rst = 0;
        #100;
        for(i = 0; i < nnz; i = i + 1) begin
            while(stall) begin
                stall_count = stall_count + 1;
                wr = 0;
                #10;
            end
            wr = 1;
            row = row_index[i];
            v0 = floats[i];
            v1 = floats[col_index[i]];
            #10;
        end
        wr = 0;
        #10000 eof = 1;
        #10 eof = 0;
    end

    // Output monitoring
    always @(posedge clk) begin
        if(out_count == M) begin
            $display("reached the end");
            $display("Output count: %d", out_count);
            $display("Stall count: %d", stall_count);
            $finish;
        end
        if(push_out) begin
            out_count = out_count + 1;
        end
    end

endmodule

