module ring_oscillator (
  input [n-1:0] in,
  output out
);

parameter n = 4; // number of input signals
parameter p = 3; // number of inverters in the ring oscillator

wire [p-1:0] inv_out;
wire [p-1:0] buf_out;

genvar i;

generate
  // Define p inverters in a loop
  for (i = 0; i < p; i = i + 1) begin : inv_loop
    not inv (
      .in (buf_out[i]),
      .out (inv_out[i])
    );
  end

  // Define n buffers to drive the inverters
  for (i = 0; i < n; i = i + 1) begin : buf_loop
    buf (
      .in (in[i]),
      .out (buf_out[i])
    );
  end
