module data_forwarding_unit (
    input [4:0] ra_i,
    input [4:0] rb_i,
    input [31:0] ra_regval_i,
    input [31:0] rb_regval_i,
    input [4:0] rd_ex_i,
    input [4:0] rd_wb_i,
    input load_pending_i,
    input [4:0] rd_load_i,
    input mult_ex_i,
    input [31:0] result_ex_i,
    input [31:0] result_wb_i,
    output reg [31:0] result_ra_o,
    output reg [31:0] result_rb_o,
    output reg resolved_o,
    output reg stall_o
);

always @ (*) begin
    result_ra_o = ra_regval_i;
    result_rb_o = rb_regval_i;
    stall_o = 1'b0;
    resolved_o = 1'b0;

    // RA forwarding
    if (ra_i != 5'b00000) begin
        // RA from load
        if (ra_i == rd_load_i && load_pending_i) begin
            stall_o = 1'b1;
        end
        // RA from PC-4 (exec)
        else if (ra_i == rd_ex_i) begin
            if (mult_ex_i) begin
                stall_o = 1'b1;
            end
            else begin
                result_ra_o = result_ex_i;
                resolved_o = 1'b1;
            end
        end
        // RA from PC-8 (writeback)
        else if (ra_i == rd_wb_i) begin
            result_ra_o = result_wb_i;
            resolved_o = 1'b1;
        end
    end

    // RB forwarding
    if (rb_i != 5'b00000) begin
        // RB from load
        if (rb_i == rd_load_i && load_pending_i) begin
            stall_o = 1'b1;
        end
        // RB from PC-4 (exec)
        else if (rb_i == rd_ex_i) begin
            if (mult_ex_i) begin
                stall_o = 1'b1;
            end
            else begin
                result_rb_o = result_ex_i;
                resolved_o = 1'b1;
            end
        end
        // RB from PC-8 (writeback)
        else if (rb_i == rd_wb_i) begin
            result_rb_o = result_wb_i;
            resolved_o = 1'b1;
        end
    end
end

endmodule

module sync_fifo #(
    parameter DATA_WIDTH = 64,
    parameter LOCAL_FIFO_DEPTH = 256
) (
    input clock,
    input aclr,
    input [DATA_WIDTH-1:0] data,
    input rdreq,
    input wrreq,
    output almost_full,
    output almost_empty,
    output empty,
    output full,
    output [DATA_WIDTH-1:0] q,
    output [($clog2(LOCAL_FIFO_DEPTH)-1):0] usedw
);

localparam ADDR_WIDTH = $clog2(LOCAL_FIFO_DEPTH);
reg [ADDR_WIDTH-1:0] wr_ptr;
reg [ADDR_WIDTH-1:0] rd_ptr;
reg [ADDR_WIDTH-1:0] next_wr_ptr;
reg [ADDR_WIDTH-1:0] next_rd_ptr;
reg [DATA_WIDTH-1:0] fifo [LOCAL_FIFO_DEPTH-1:0];
reg [DATA_WIDTH-1:0] q_reg;
reg [($clog2(LOCAL_FIFO_DEPTH)-1):0] usedw_reg;
wire [($clog2(LOCAL_FIFO_DEPTH)-1):0] usedw = usedw_reg;
reg empty_reg;
reg full_reg;
wire empty = empty_reg;
wire full = full_reg;
wire almost_empty = (usedw_reg <= (LOCAL_FIFO_DEPTH >> 2));
wire almost_full = (usedw_reg >= (LOCAL_FIFO_DEPTH - (LOCAL_FIFO_DEPTH >> 2)));

always @(posedge clock) begin
    if (aclr) begin
        wr_ptr <= 0;
        rd_ptr <= 0;
        empty_reg <= 1;
        full_reg <= 0;
        q_reg <= 0;
        usedw_reg <= 0;
    end else begin
        wr_ptr <= next_wr_ptr;
        rd_ptr <= next_rd_ptr;
        empty_reg <= (usedw_reg == 0);
        full_reg <= (usedw_reg == LOCAL_FIFO_DEPTH);
        q_reg <= fifo[rd_ptr];
        usedw_reg <= (wr_ptr >= rd_ptr) ? (wr_ptr - rd_ptr) : (wr_ptr + LOCAL_FIFO_DEPTH - rd_ptr);
    end
end

always @* begin
    next_wr_ptr = wr_ptr;
    next_rd_ptr = rd_ptr;
    if (wrreq && !full_reg) begin
        next_wr_ptr = (wr_ptr == LOCAL_FIFO_DEPTH-1) ? 0 : wr_ptr + 1;
        fifo[wr_ptr] = data;
    end
    if (rdreq && !empty_reg) begin
        next_rd_ptr = (rd_ptr == LOCAL_FIFO_DEPTH-1) ? 0 : rd_ptr + 1;
    end
end

assign q = q_reg;
assign usedw = usedw_reg;
assign empty = empty_reg;
assign full = full_reg;
assign almost_empty = almost_empty;
assign almost_full = almost_full;

endmodule

module avalanche_entropy(
                         input wire           clk,
                         input wire           reset_n,

                         input wire           noise,

                         input wire           cs,
                         input wire           we,
                         input wire  [7 : 0]  address,
                         input wire  [31 : 0] write_data,
                         output wire [31 : 0] read_data,
                         output wire          error,

                         input wire           discard,
                         input wire           test_mode,
                         output wire          security_error,

                         output wire          entropy_enabled,
                         output wire [31 : 0] entropy_data,
                         output wire          entropy_valid,
                         input wire           entropy_ack,

                         output wire [7 : 0]  debug,
                         input wire           debug_update
                        );


  //----------------------------------------------------------------
  // Concurrent connectivity for ports etc.
  //----------------------------------------------------------------
  reg [31:0] memory [255:0];
  reg [31:0] entropy_value;
  reg [31:0] debug_value;
  reg entropy_valid_internal;
  reg [7:0] debug_value_internal;

  assign read_data      = cs & ~we ? memory[address] : 32'h00000000;
  assign error          = 0;

  always @(posedge clk) begin
    if (reset_n == 0) begin
      entropy_enabled <= 0;
      entropy_value <= 0;
      entropy_valid_internal <= 0;
      debug_value_internal <= 0;
    end else begin
      if (cs == 0 && we == 1) begin
        memory[address] <= write_data;
      end else if (cs == 0 && we == 0) begin
        read_data <= memory[address];
      end

      if (discard == 1) begin
        entropy_value <= 0;
      end

      if (test_mode == 1 && entropy_value != 0) begin
        security_error <= 1;
      end else begin
        security_error <= 0;
      end

      if (entropy_ack == 1) begin
        entropy_value <= entropy_value + noise;
        entropy_valid_internal <= 1;
      end else begin
        entropy_valid_internal <= 0;
      end

      if (debug_update == 1) begin
        debug_value_internal <= 8'haa;
      end

      entropy_valid <= entropy_valid_internal;
      entropy_data <= entropy_value;
      debug <= debug_value_internal;
      entropy_enabled <= 1;
    end
  end

endmodule

