module full_adder (
  input A,
  input B,
  input Cin,
  output S,
  output Cout
);
  wire sum, carry1, carry2;

  xor (sum, A, B, Cin);
  and (carry1, A, B);
  and (carry2, A, Cin);
  or (Cout, carry1, carry2);

  assign S = sum;
endmodule

module ripple_adder (
  input [3:0] A,
  input [3:0] B,
  output [3:0] S,
  output Cout
);
  wire c1, c2, c3;

  full_adder FA0 (.A(A[0]), .B(B[0]), .Cin(1'b0), .S(S[0]), .Cout(c1));
  full_adder FA1 (.A(A[1]), .B(B[1]), .Cin(c1), .S(S[1]), .Cout(c2));
  full_adder FA2 (.A(A[2]), .B(B[2]), .Cin(c2), .S(S[2]), .Cout(c3));
  full_adder FA3 (.A(A[3]), .B(B[3]), .Cin(c3), .S(S[3]), .Cout(Cout));

endmodule

