	input mode_inv7b;

	input load;
	input clr_sum;

	output reg ready;

	output reg [15:0] sum_out;

	wire [5:0] add_data;
	wire [6:0] sum_unreg;
	reg [6:0] sum_reg;
	reg [7:0] shifter;
	reg [5:0] adder;
	wire   mul_out;

	reg [3:0] counter;

	reg clr_sum_reg;
	wire [1:0] temp_sum;
	wire carry_in;
	wire old_data_in;
	reg old_carry;

	// control section
	//
	always @(posedge clock)
	begin

		if( load )
			ready <= 1'b0;

		if( counter[3:0] == 4'd15 )
			ready <= 1'b1;

		if( load )
			counter <= 4'd0;
		else
			counter <= counter + 4'd1;

	end

	// serial multiplier section
	//
	assign add_data = ( shifter[0] ) ? adder : 6'd0; // data to be added controlled by LSB of shifter

	assign sum_unreg[6:0] = sum_reg[6:1] + add_data[5:0]; // sum of two values

	assign mul_out = sum_unreg[0];

	always @(posedge clock)
	begin

		if( !load ) // normal addition
		begin
			sum_reg[6:0] <= sum_unreg[6:0];
			shifter[6:0] <= shifter[7:1];
		end

		else // load==1

		begin
			sum_reg[6:0] <= 7'd0;

			shifter[7]   <= ~(mode_inv7b^dat_in[7]);   // convert to signed data (we need signed result), invert 7th bit if needed
			shifter[6:0] <=  dat_in[6:0];

			adder <= vol_in;

		end
	end

	// serial adder section
	//
	always @(posedge clock)
	begin
		if( load )
			clr_sum_reg <= clr_sum;
	end

	assign carry_in = (counter==4'd0) ? 1'b0 : old_carry;

	assign old_data_in = (clr_sum_reg) ? 1'b0 : sum_out[0];

	assign temp_sum[1:0] = carry_in + mul_out + old_data_in;

	always @(posedge clock)
	begin
		if( !ready )
		begin
			sum_out[15:0] <= { temp_sum[0], sum_out[15:1] };
			old_carry <= temp_sum[1];
		end
	end
endmodule

module priority_encoder (
    input [3:0] in,
    output reg [1:0] pos
);

reg [3:0] gray_in;
reg [1:0] pos_reg;

// Binary to Gray code converter
always @ (in) begin
    gray_in[0] = in[0];
    gray_in[1] = in[0] ^ in[1];
    gray_in[2] = in[1] ^ in[2];
    gray_in[3] = in[2] ^ in[3];
end

// Priority encoder
always @ (posedge clk) begin
    pos_reg <= 2'b00;
    if (gray_in[3] == 1) begin
        pos_reg <= 2'b11;
    end else if (gray_in[2] == 1) begin
        pos_reg <= 2'b10;
    end else if (gray_in[1] == 1) begin
        pos_reg <= 2'b01;
    end else if (gray_in[0] == 1) begin
        pos_reg <= 2'b00;
    end
end

// Output register
always @ (posedge clk) begin
    pos <= pos_reg;
end

endmodule

// Pipeline structure
module pipeline (
    input [3:0] in,
    output reg [1:0] pos
);

wire [1:0] pos1;
wire [1:0] pos2;

priority_encoder pe1(.in(in), .pos(pos1));
priority_encoder pe2(.in(pos1), .pos(pos2));

assign pos = pos2;

endmodule

// Top module
module top_module (
    input [3:0] in,
    output reg [1:0] pos
);

pipeline p(.in(in), .pos(pos));

endmodule

