module mealy_state_machine (
  input clk,
  input reset,
  input a,
  input b,
  input c,
  output reg out1,
  output reg out2
);

  // Define the states
  parameter S0 = 2'b00;
  parameter S1 = 2'b01;
  parameter S2 = 2'b10;
  parameter S3 = 2'b11;

  // Define the state register
  reg [1:0] state;

  // Define the next state logic
  always @(posedge clk) begin
    if (reset) begin
      state <= S0;
    end else begin
      case (state)
        S0: begin
          if (a) begin
            state <= S2;
          end else begin
            state <= S1;
          end
        end
        S1: begin
          if (b) begin
            state <= S3;
          end else begin
            state <= S0;
          end
        end
        S2: begin
          if (c) begin
            state <= S0;
          end else begin
            state <= S3;
          end
        end
        S3: begin
          if (reset) begin
            state <= S0;
          end else begin
            state <= S3;
          end
        end
      endcase
    end
  end

  // Define the output logic
  always @(state, a, b, c) begin
    case (state)
      S0: begin
        out1 <= 1'b0;
        out2 <= 1'b0;
      end
      S1: begin
        out1 <= 1'b0;
        out2 <= 1'b1;
      end
      S2: begin
        out1 <= 1'b1;
        out2 <= 1'b0;
      end
      S3: begin
        out1 <= 1'b1;
        out2 <= 1'b1;
      end
    endcase
  end

endmodule

module MemoryInterface
    (DDR_addr,
    DDR_ba,
    DDR_cas_n,
    DDR_ck_n,
    DDR_ck_p,
    DDR_cke,
    DDR_cs_n,
    DDR_dm,
    DDR_dq,
    DDR_dqs_n,
    DDR_dqs_p,
    DDR_odt,
    DDR_ras_n,
    DDR_reset_n,
    DDR_we_n,
    IO_NAND_CH0_DQ,
    IO_NAND_CH0_DQS_N,
    IO_NAND_CH0_DQS_P,
    IO_NAND_CH1_DQ,
    IO_NAND_CH1_DQS_N,
    IO_NAND_CH1_DQS_P,
    I_NAND_CH0_RB,
    I_NAND_CH1_RB,
    pcie_perst_n,
    pcie_ref_clk_n,
    pcie_ref_clk_p,
    pcie_rx_n,
    pcie_rx_p,
    pcie_tx_n,
    pcie_tx_p,
    O_DEBUG);
    input [14:0] DDR_addr;
    input [2:0] DDR_ba;
    input DDR_cas_n;
    input DDR_ck_n;
    input DDR_ck_p;
    input DDR_cke;
    input DDR_cs_n;
    input [3:0] DDR_dm;
    inout [31:0] DDR_dq;
    input [3:0] DDR_dqs_n;
    input [3:0] DDR_dqs_p;
    input DDR_odt;
    input DDR_ras_n;
    input DDR_reset_n;
    input DDR_we_n;
    inout [7:0] IO_NAND_CH0_DQ;
    input IO_NAND_CH0_DQS_N;
    input IO_NAND_CH0_DQS_P;
    inout [7:0] IO_NAND_CH1_DQ;
    input IO_NAND_CH1_DQS_N;
    input IO_NAND_CH1_DQS_P;
    input [7:0] I_NAND_CH0_RB;
    input [7:0] I_NAND_CH1_RB;
    input pcie_perst_n;
    input pcie_ref_clk_n;
    input pcie_ref_clk_p;
    input [7:0] pcie_rx_n;
    input [7:0] pcie_rx_p;
    output [7:0] pcie_tx_n;
    output [7:0] pcie_tx_p;
    output [31:0] O_DEBUG;

    // DDR memory interface
    reg [31:0] DDR_data;
    always @ (posedge DDR_ck_p)
    begin
        if (DDR_reset_n == 1'b0)
            DDR_data <= 32'b0;
        else if (DDR_cke == 1'b0)
            DDR_data <= DDR_dq;
    end

    assign DDR_dq = (DDR_cs_n == 1'b0) ? DDR_data : 32'bZ;

    // NAND flash memory interface
    reg [7:0] NAND_CH0_data;
    reg [7:0] NAND_CH1_data;
    always @ (posedge IO_NAND_CH0_DQS_P)
    begin
        if (IO_NAND_CH0_DQS_N == 1'b0 && IO_NAND_CH0_DQS_P == 1'b1)
            NAND_CH0_data <= IO_NAND_CH0_DQ;
    end

    always @ (posedge IO_NAND_CH1_DQS_P)
    begin
        if (IO_NAND_CH1_DQS_N == 1'b0 && IO_NAND_CH1_DQS_P == 1'b1)
            NAND_CH1_data <= IO_NAND_CH1_DQ;
    end

    assign IO_NAND_CH0_DQ = (I_NAND_CH0_RB == 8'b00000000) ? NAND_CH0_data : 8'bz;
    assign IO_NAND_CH1_DQ = (I_NAND_CH1_RB == 8'b00000000) ? NAND_CH1_data : 8'bz;

    // PCIe interface
    reg [7:0] pcie_tx_data;
    always @ (posedge pcie_ref_clk_p)
    begin
        if (pcie_perst_n == 1'b0)
            pcie_tx_data <= 8'b0;
        else if (pcie_tx_data != pcie_rx_n && pcie_tx_data != pcie_rx_p)
            pcie_tx_data <= pcie_tx_data + 1'b1;
    end

    assign pcie_tx_n = pcie_tx_data;
    assign pcie_tx_p = ~pcie_tx_data;

    assign O_DEBUG = 32'b0;
endmodule

module top_module(
    input [4:0] in,
    output out_and,
    output out_or,
    output out_nor
);

wire [3:0] decoder_out;
wire a, b, c, d, e;

decoder_2to4_with_enable decoder(
    .in(in[4]),
    .sel(in[3:0]),
    .out(decoder_out)
);

and_gate_5_input and_gate(
    .in({a, b, c, d, e}),
    .out(out_and)
);

or_gate_5_input or_gate(
    .in({a, b, c, d, e}),
    .out(out_or)
);

nor_gate_5_input nor_gate(
    .in({a, b, c, d, e}),
    .out(out_nor)
);

and_gate_2_input and1(
    .in({decoder_out[0], ~decoder_out[1]}),
    .out(a)
);

and_gate_2_input and2(
    .in({decoder_out[1], ~decoder_out[2]}),
    .out(b)
);

and_gate_2_input and3(
    .in({decoder_out[2], ~decoder_out[3]}),
    .out(c)
);

and_gate_2_input and4(
    .in({decoder_out[3], ~decoder_out[0]}),
    .out(d)
);

and_gate_2_input and5(
    .in({decoder_out[0], decoder_out[1], decoder_out[2], decoder_out[3]}),
    .out(e)
);

endmodule

module decoder_2to4_with_enable(
    input in,
    input [3:0] sel,
    output reg [3:0] out
);

always @ (in or sel) begin
    if (in == 1'b0) begin
        case (sel)
            4'b0000: out = 4'b0001;
            4'b0001: out = 4'b0010;
            4'b0010: out = 4'b0100;
            4'b0011: out = 4'b1000;
            default: out = 4'b0000;
        endcase
    end else begin
        out = 4'b0000;
    end
end

endmodule

module and_gate_5_input(
    input [4:0] in,
    output out
);

assign out = ~(in[0] & in[1] & in[2] & in[3] & in[4]);

endmodule

module or_gate_5_input(
    input [4:0] in,
    output out
);

assign out = ~(~in[0] & ~in[1] & ~in[2] & ~in[3] & ~in[4]);

endmodule

module nor_gate_5_input(
    input [4:0] in,
    output out
);

assign out = ~(in[0] | in[1] | in[2] | in[3] | in[4]);

endmodule

module and_gate_2_input(
    input [1:0] in,
    output out
);

assign out = ~(in[0] & in[1]);

endmodule

module rx_data_receive(
    input posedge_clk,
    input rx_resetn,
    input ready_control_p_r,
    input ready_data_p_r,
    input ready_control,
    input ready_data,
    input parity_rec_c,
    input parity_rec_d,
    input parity_rec_c_gen,
    input parity_rec_d_gen,
    input [2:0] control_p_r,
    input [2:0] control_l_r,
    input [8:0] dta_timec_p,
    output reg [1:0] state_data_process,
    output reg last_is_control,
    output reg last_is_data,
    output reg last_is_timec,
    output reg rx_error_c,
    output reg rx_error_d,
    output reg rx_got_fct,
    output reg [8:0] rx_data_flag,
    output reg [7:0] timecode
);

    reg  [1:0] next_state_data_process;

    always @(*) begin
        next_state_data_process = state_data_process;

        case(state_data_process)
            2'd0: begin
                if (ready_control_p_r || ready_data_p_r) begin
                    next_state_data_process = 2'd1;
                end else begin
                    next_state_data_process = 2'd0;
                end
            end
            2'd1: begin
                if (ready_control || ready_data) begin
                    next_state_data_process = 2'd0;
                end else begin
                    next_state_data_process = 2'd1;
                end
            end
            default: begin
                next_state_data_process = 2'd0;
            end
        endcase
    end

    always @(posedge posedge_clk or negedge rx_resetn) begin
        if (!rx_resetn) begin
            last_is_control  <= 1'b0;
            last_is_data     <= 1'b0;
            last_is_timec    <= 1'b0;
            rx_data_flag     <= 9'd0;
            timecode         <= 8'd0;
            state_data_process <= 2'd0;
            rx_error_c <= 1'b0;
            rx_error_d <= 1'b0;
            rx_got_fct <= 1'b0;
        end else begin
            state_data_process <= next_state_data_process;

            case(state_data_process)
                2'd0: begin
                    rx_error_c <= rx_error_c;
                    rx_error_d <= rx_error_d;

                    if (ready_control_p_r) begin
                        if (control_l_r[2:0] != 3'd7 && control_p_r[2:0] == 3'd4) begin
                            rx_got_fct <= 1'b1;
                        end else begin
                            rx_got_fct <= 1'b0;
                        end

                        if (control_p_r[2:0] == 3'd6) begin
                            rx_data_flag <= 9'b100000001;
                        end else if (control_p_r[2:0] == 3'd5) begin
                            rx_data_flag <= 9'b100000000;
                        end else begin
                            rx_data_flag <= rx_data_flag;
                        end

                        last_is_control <= 1'b1;
                        last_is_data    <= 1'b0;
                        last_is_timec   <= 1'b0;
                    end else if (ready_data_p_r) begin
                        rx_got_fct <= 1'b0;

                        if (control_p_r[2:0] == 3'd7) begin
                            timecode <= {dta_timec_p[7], dta_timec_p[6], dta_timec_p[5], dta_timec_p[4], dta_timec_p[3], dta_timec_p[2], dta_timec_p[1], dta_timec_p[0]};
                            last_is_control <= 1'b0;
                            last_is_data    <= 1'b0;
                            last_is_timec   <= 1'b1;
                        end else begin
                            rx_data_flag <= {dta_timec_p[8], dta_timec_p[7], dta_timec_p[6], dta_timec_p[5], dta_timec_p[4], dta_timec_p[3], dta_timec_p[2], dta_timec_p[1], dta_timec_p[0]};
                            last_is_control <= 1'b0;
                            last_is_data    <= 1'b1;
                            last_is_timec   <= 1'b0;
                        end
                    end else begin
                        rx_got_fct <= 1'b0;
                        timecode <= timecode;
                    end
                end
                2'd1: begin
                    if (ready_control_p_r) begin
                        if (parity_rec_c_gen != parity_rec_c) begin
                            rx_error_c <= 1'b1;
                        end else begin
                            rx_error_c <= rx_error_c;
                        end
                        rx_got_fct <= rx_got_fct;
                    end else if (ready_data_p_r) begin
                        if (parity_rec_d_gen != parity_rec_d) begin
                            rx_error_d <= 1'b1;
                        end else begin
                            rx_error_d <= rx_error_d;
                        end
                        rx_got_fct <= 1'b0;
                    end else begin
                        rx_error_c <= rx_error_c;
                        rx_error_d <= rx_error_d;
                        rx_got_fct <= 1'b0;
                    end
                    rx_data_flag <= rx_data_flag;
                    timecode <= timecode;
                end
                default: begin
                    rx_data_flag <= rx_data_flag;
                    timecode <= timecode;
                    rx_got_fct <= rx_got_fct;
                end
            endcase
        end
    end

endmodule

module pwm
#(parameter MIN_DEAD=16'd63) // intended to be overridden at instantiation
(
    input c,   // clock input
    input [15:0] w_top,
    input [47:0] duty,
    input [15:0] dead,     // intended to be a register
    output [2:0] hi,
    output [2:0] lo
);

    wire [15:0] w, w_next;
    wire w_start = w == 16'h0;
    wire [15:0] w_top_i; // w_top internal signal (synchronized to pwm cycle)
    r #(16) w_top_r(.c(c), .rst(1'b0), .en(w_start), .d(w_top), .q(w_top_i));

    r #(16) w_r(.c(c), .rst(1'b0), .en(1'b1), .d(w_next), .q(w));
    wire w_dir, w_dir_en;
    r w_dir_r(.c(c), .rst(1'b0), .en(w_dir_en), .d(~w_dir), .q(w_dir));
    assign w_next = w_dir == 1'b0 ? w + 1'b1 : w - 1'b1;
    assign w_dir_en = w_next == 16'h0 | w_next == w_top_i;

    wire [47:0] duty_i;
    wire [15:0] a_i = duty_i[15:0];
    wire [15:0] b_i = duty_i[31:16];
    wire [15:0] c_i = duty_i[47:32];
    r #(48) duty_r(.c(c), .rst(1'b0), .en(w_start), .d(duty), .q(duty_i));

    wire [15:0] dead_i; 
    r #(16) dead_i_r(.c(c), .rst(1'b0), .en(1'b1), .q(dead_i),
                   .d(dead > MIN_DEAD ? dead : MIN_DEAD));

    wire ah, al, bh, bl, ch, cl;
    r ah_r(.c(c), .rst(1'b0), .en(1'b1), .d((a_i>dead_i) & (a_i-dead_i)>w), .q(ah));
    r bh_r(.c(c), .rst(1'b0), .en(1'b1), .d((b_i>dead_i) & (b_i-dead_i)>w), .q(bh));
    r ch_r(.c(c), .rst(1'b0), .en(1'b1), .d((c_i>dead_i) & (c_i-dead_i)>w), .q(ch));
    r al_r(.c(c), .rst(1'b0), .en(1'b1), .d(a_i<=w), .q(al));
    r bl_r(.c(c), .rst(1'b0), .en(1'b1), .d(b_i<=w), .q(bl));
    r cl_r(.c(c), .rst(1'b0), .en(1'b1), .d(c_i<=w), .q(cl));

    assign hi = { ah & ~al, bh & ~bl, ch & ~cl };
    assign lo = { al,       bl,       cl       };

endmodule

