module mux4to1 (
    input A,
    input B,
    input C,
    input D,
    input S0,
    input S1,
    output Y
);

    wire notS0, notS1;

    assign notS0 = ~S0;
    assign notS1 = ~S1;

    // Compute the output signal
    assign Y = (A & notS1 & notS0) |
               (B & notS1 & S0) |
               (C & S1 & notS0) |
               (D & S1 & S0);

endmodule

module shift_reg_serial (
    input clk,
    input reset,
    input serial_in,
    output reg serial_out,
    output reg [3:0] parallel_out
);

reg [3:0] shift_reg;

always @(posedge clk) begin
    if (reset) begin
        shift_reg <= 4'b0;
        serial_out <= 1'b0;
    end else begin
        shift_reg <= {shift_reg[2:0], serial_in};
        serial_out <= shift_reg[3];
    end
end

assign parallel_out = shift_reg;

endmodule


