assign clk_out = clk;

always @(posedge clk) begin
  data_delay1 <= data_in;
  data_delay2 <= data_delay1;
  data_delay3 <= data_delay2;
  data_delay4 <= data_delay3;
  data_delay5 <= data_delay4;
