  hilbert_delay8 <= hilbert_sum8;
  hilbert_delay9 <= hilbert_sum9;
  hilbert_delay10 <= hilbert_sum10;

  hilbert_sum1 <= (data_delay1 * hilbert_coeff1) + (hilbert_delay2 * hilbert_coeff2) + (hilbert_delay4 * hilbert_coeff3) + (hilbert_delay6 * hilbert_coeff4) + (hilbert_delay8 * hilbert_coeff5) + (hilbert_delay10 * hilbert_coeff6);
  hilbert_sum2 <= (data_delay2 * hilbert_coeff1) + (data_delay1 * hilbert_coeff2) + (hilbert_delay3 * hilbert_coeff3) + (hilbert_delay5 * hilbert_coeff4) + (hilbert_delay7 * hilbert_coeff5) + (hilbert_delay9 * hilbert_coeff6);
  hilbert_sum3 <= (data_delay3 * hilbert_coeff1) + (data_delay2 * hilbert_coeff2) + (data_delay1 * hilbert_coeff3) + (hilbert_delay4 * hilbert_coeff4) + (hilbert_delay6 * hilbert_coeff5) + (hilbert_delay8 * hilbert_coeff6);
