  hilbert_sum5 <= (data_delay5 * hilbert_coeff1) + (data_delay4 * hilbert_coeff2) + (data_delay3 * hilbert_coeff3) + (data_delay2 * hilbert_coeff4) + (data_delay1 * hilbert_coeff5) + (hilbert_delay6 * hilbert_coeff6);
  hilbert_sum6 <= (data_delay6 * hilbert_coeff1) + (data_delay5 * hilbert_coeff2) + (data_delay4 * hilbert_coeff3) + (data_delay3 * hilbert_coeff4) + (data_delay2 * hilbert_coeff5) + (data_delay1 * hilbert_coeff6);
