module barrel_shift_multiplier (
    input clk,
    input [31:0] data_in,
    input [4:0] shift_amt,
    input [3:0] mult_op,
    input select,
    output reg [7:0] P
);

reg [31:0] shifted_data;
reg [4:0] booth_mult_op;
reg [9:0] booth_mult_res;
reg booth_mult_sign;
reg [3:0] booth_mult_counter;

always @(posedge clk) begin
    if (select) begin
        // Multiplier module
        booth_mult_op = {2'b00, mult_op};
        booth_mult_res = {10'b0, shifted_data};
        booth_mult_sign = shifted_data[31];
        booth_mult_counter = 4;

        while (booth_mult_counter > 0) begin
            if (booth_mult_res[0] != booth_mult_sign) begin
                booth_mult_res = booth_mult_res + (booth_mult_op << 1);
            end else begin
                booth_mult_res = booth_mult_res - (booth_mult_op << 1);
            end
            booth_mult_counter = booth_mult_counter - 1;
        end

        P = booth_mult_res[7:0];
    end else begin
        // Barrel shifter module
        if (shift_amt[4]) begin
            shifted_data = {32{data_in[31]}};
        end else if (shift_amt[3]) begin
            shifted_data = {data_in[31], data_in[31:1]};
        end else if (shift_amt[2]) begin
            shifted_data = {data_in[31:2], data_in[31:2]};
        end else if (shift_amt[1]) begin
            shifted_data = {data_in[31:3], data_in[31:3], data_in[31:1]};
        end else begin
            shifted_data = {data_in[31:4], data_in[31:4], data_in[31:4], data_in[31:1]};
        end

        P = 0;
    end
end

endmodule

