module mux_4bit_xor (input clk, input [3:0] din, input [1:0] sel, output [3:0] dout);
    parameter LOC="SLICE_FIXME";
    parameter N=-1;

    reg [3:0] mux_out;
    reg d_ff_out;
    wire xor_out;

    always @ (sel or din) begin
        case (sel)
            2'b00: mux_out = din[3:0];
            2'b01: mux_out = {din[2:0], din[3]};
            2'b10: mux_out = {din[1:0], din[3:2]};
            2'b11: mux_out = {din[0], din[3:1]};
        endcase
    end

    always @ (posedge clk) begin
        d_ff_out <= mux_out;
    end

    assign xor_out = d_ff_out ^ mux_out;

