            .lut4o(),
            .ff_q(dout[0]));

    myLUT4 #(.LOC(LOC), .N(N))
            myLUT4(.din({1'b0, xor_out, 1'b0, 1'b0}),
            .lut4o(),
            .ff_q(dout[1]));

    myLUT4 #(.LOC(LOC), .N(N))
            myLUT4(.din({1'b0, 1'b0, xor_out, 1'b0}),
            .lut4o(),
            .ff_q(dout[2]));

    myLUT4 #(.LOC(LOC), .N(N))
