module axis_ll_bridge #
(
    parameter DATA_WIDTH = 8
)
(
    input  wire                   clk,
    input  wire                   rst,

    /*
     * AXI input
     */
    input  wire [DATA_WIDTH-1:0]  axis_tdata,
    input  wire                   axis_tvalid,
    output wire                   axis_tready,
    input  wire                   axis_tlast,

    /*
     * LocalLink output
     */
    output wire [DATA_WIDTH-1:0]  ll_data_out,
    output wire                   ll_sof_out_n,
    output wire                   ll_eof_out_n,
    output wire                   ll_src_rdy_out_n,
    input  wire                   ll_dst_rdy_in_n
);

reg last_tlast = 1'b1;
reg [DATA_WIDTH-1:0] last_axis_tdata = 0;

// packet state machine
localparam IDLE = 2'b00, FIRST = 2'b01, MIDDLE = 2'b10, LAST = 2'b11;
reg [1:0] packet_state = IDLE;
reg [DATA_WIDTH-1:0] packet_data = 0;
reg [DATA_WIDTH-1:0] shift_reg = 0;
reg [1:0] shift_cnt = 0;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        last_tlast = 1'b1;
        last_axis_tdata = 0;
        packet_state = IDLE;
        packet_data = 0;
        shift_reg = 0;
        shift_cnt = 0;
    end else begin
        if (axis_tvalid & axis_tready) begin
            last_tlast = axis_tlast;
            last_axis_tdata = axis_tdata;
            if (packet_state == IDLE) begin
                if (axis_tlast) begin
                    ll_sof_out_n <= 1'b0;
                    ll_eof_out_n <= 1'b0;
                    ll_data_out <= axis_tdata;
                    ll_src_rdy_out_n <= 1'b1;
                    packet_state <= IDLE;
                    packet_data <= 0;
                end else begin
                    packet_state <= FIRST;
                    packet_data <= axis_tdata;
                end
            end else if (packet_state == FIRST) begin
                packet_state <= MIDDLE;
                packet_data <= axis_tdata;
            end else if (packet_state == MIDDLE) begin
                packet_state <= MIDDLE;
                packet_data <= {packet_data[(DATA_WIDTH-2):0], axis_tdata};
            end else if (packet_state == LAST) begin
                packet_state <= IDLE;
                packet_data <= {packet_data[(DATA_WIDTH-2):0], axis_tdata};
                ll_sof_out_n <= 1'b0;
                ll_eof_out_n <= 1'b1;
                ll_data_out <= packet_data;
                ll_src_rdy_out_n <= 1'b1;
            end
        end else begin
            if (packet_state == IDLE) begin
                ll_sof_out_n <= 1'b1;
                ll_eof_out_n <= 1'b1;
                ll_src_rdy_out_n <= 1'b0;
            end else if (packet_state == FIRST) begin
                packet_state <= LAST;
                packet_data <= {packet_data[(DATA_WIDTH-2):0], last_axis_tdata};
            end else if (packet_state == MIDDLE) begin
                packet_state <= LAST;
                packet_data <= {packet_data[(DATA_WIDTH-2):0], last_axis_tdata};
            end else if (packet_state == LAST) begin
                packet_state <= IDLE;
                packet_data <= {packet_data[(DATA_WIDTH-2):0], last_axis_tdata};
                ll_sof_out_n <= 1'b0;
                ll_eof_out_n <= 1'b1;
                ll_data_out <= packet_data;
                ll_src_rdy_out_n <= 1'b1;
            end
        end
    end
end

assign axis_tready = ~ll_dst_rdy_in_n;

endmodule

module pll (
    input wire clk_in,
    input wire rst,
    input wire [31:0] freq_div,
    output wire clk_out
);

    reg [31:0] counter;
    reg locked;
    reg [31:0] multiplier;
    reg [31:0] divisor;

    always @(posedge clk_in or posedge rst) begin
        if (rst) begin
            counter <= 0;
            locked <= 0;
            multiplier <= 0;
            divisor <= 0;
        end else begin
            if (locked) begin
                counter <= counter + 1;
                if (counter == freq_div) begin
                    counter <= 0;
                    clk_out <= ~clk_out;
                end
            end else begin
                counter <= 0;
                multiplier <= 0;
                divisor <= 0;
            end
        end
    end

    always @(posedge clk_in or posedge rst) begin
        if (rst) begin
            locked <= 0;
            multiplier <= 0;
            divisor <= 0;
        end else begin
            if (locked) begin
                multiplier <= multiplier + clk_out;
                divisor <= divisor + clk_in;
            end else begin
                multiplier <= 0;
                divisor <= 0;
            end
        end
    end

    always @(posedge clk_in or posedge rst) begin
        if (rst) begin
            locked <= 0;
        end else begin
            if (!locked && divisor != 0) begin
                if (multiplier >= divisor) begin
                    clk_out <= 1;
                    locked <= 1;
                end else begin
                    clk_out <= 0;
                end
            end
        end
    end

endmodule

