    end else if(T5) begin
      last_grant <= T6;
    end
  end

  // Implement the arbiter logic
  reg [15:0] granted_request_index = 0;
  reg [4:0] granted_request_tag = 0;
  reg chosen = 0;

  always @(posedge clk) begin
    if (reset) begin
      granted_request_index <= 0;
      granted_request_tag <= 0;
      chosen <= 0;
    end else if (io_out_ready && io_in_0_valid) begin
      granted_request_index <= granted_request_index + 1;
      granted_request_index <= granted_request_index % 16;
      granted_request_tag <= io_in_0_tag;
      chosen <= 1;
    end else begin
      chosen <= 0;
    end
  end

  // Output the granted request index and tag
  assign io_out_bits_centeroidIndex = granted_request_index;
  assign io_out_tag = granted_request_tag;

  // Output the chosen signal
  assign io_chosen = chosen;

endmodule

module iq_corrector (

  // data interface
  input           clk,
  input           valid,
  input   [15:0]  data_in,
  input   [15:0]  data_iq,
  output          valid_out,
  output  [15:0]  data_out,

  // control interface
  input           iqcor_enable,
  input   [15:0]  iqcor_coeff_1,
  input   [15:0]  iqcor_coeff_2
);

  // select i/q if disabled
  parameter Q_OR_I_N = 0;

  // internal registers
  reg             p1_valid = 'd0;
  reg     [15:0]  p1_data_i = 'd0;
  reg     [15:0]  p1_data_q = 'd0;
  reg     [33:0]  p1_data_p = 'd0;
  reg             valid_out = 'd0;
  reg     [15:0]  data_out = 'd0;
  reg     [15:0]  iqcor_coeff_1_r = 'd0;
  reg     [15:0]  iqcor_coeff_2_r = 'd0;

  // internal signals
  wire    [15:0]  data_i_s;
  wire    [15:0]  data_q_s;
  wire    [33:0]  p1_data_p_i_s;
  wire            p1_valid_s;
  wire    [15:0]  p1_data_i_s;
  wire    [33:0]  p1_data_p_q_s;
  wire    [15:0]  p1_data_q_s;

  // swap i & q
  assign data_i_s = (Q_OR_I_N == 1) ? data_iq : data_in;
  assign data_q_s = (Q_OR_I_N == 1) ? data_in : data_iq;

  // coefficients are flopped to remove warnings from vivado
  always @(posedge clk) begin
    iqcor_coeff_1_r <= iqcor_coeff_1;
    iqcor_coeff_2_r <= iqcor_coeff_2;
  end

  // scaling functions - i
  ad_mul #(.DELAY_DATA_WIDTH(17)) i_mul_i (
    .clk (clk),
    .data_a ({data_i_s[15], data_i_s}),
    .data_b ({iqcor_coeff_1_r[15], iqcor_coeff_1_r}),
    .data_p (p1_data_p_i_s),
    .ddata_in ({valid, data_i_s}),
    .ddata_out ({p1_valid_s, p1_data_i_s}));

  // scaling functions - q
  ad_mul #(.DELAY_DATA_WIDTH(16)) i_mul_q (
    .clk (clk),
    .data_a ({data_q_s[15], data_q_s}),
    .data_b ({iqcor_coeff_2_r[15], iqcor_coeff_2_r}),
    .data_p (p1_data_p_q_s),
    .ddata_in (data_q_s),
    .ddata_out (p1_data_q_s));

  // sum
  always @(posedge clk) begin
    p1_valid <= p1_valid_s;
    p1_data_i <= p1_data_i_s;
    p1_data_q <= p1_data_q_s;
    p1_data_p <= p1_data_p_i_s + p1_data_p_q_s;
  end

  // output registers
  always @(posedge clk) begin
    valid_out <= p1_valid;
    if (iqcor_enable == 1'b1) begin
      data_out <= p1_data_p[29:14];
    end else if (Q_OR_I_N == 1) begin
      data_out <= p1_data_q;
    end else begin
      data_out <= p1_data_i;
    end
  end

endmodule

module public_key_adder (
	input clk,
	input reset,
	input [255:0] rx_x,
	input [255:0] rx_y,
	output reg done,
	output [255:0] tx_x,
	output [255:0] tx_y
);

	reg [255:0] sum;
	reg [256:0] carry;

	always @(posedge clk)
	begin
		if (reset)
		begin
			sum <= 256'd0;
			carry <= 257'd0;
			done <= 1'b0;
		end
		else
		begin
			// Calculate sum
			sum <= rx_x + rx_y + carry[0:255];

			// Calculate carry
			carry <= {1'b0, sum[255:0]} + {1'b0, rx_x[255:0]} + {1'b0, rx_y[255:0]};

			// Output sum and carry
			tx_x <= sum;
			tx_y <= carry[256:1];

			// Set done signal
			done <= 1'b1;
		end
	end

endmodule

