module calculator(
  input signed [7:0] num1,
  input signed [7:0] num2,
  input [1:0] op,
  output reg signed [7:0] result
);

always @ (*)
begin
  case(op)
    2'b00: result = num1 + num2; // addition
    2'b01: result = num1 - num2; // subtraction
    2'b10: result = num1 * num2; // multiplication
    2'b11: begin // division
             if(num2 == 0) // division by zero
               result = 8'sd127; // maximum value
             else if(num1 == -8'sd128 && num2 == -1) // division overflow
               result = 8'sd127; // maximum value
             else
               result = num1 / num2;
           end
  endcase
end

endmodule

