module division_module (
    input [7:0] A,
    input [7:0] B,
    output reg [7:0] quotient,
    output reg [7:0] remainder,
    output reg valid
);

reg [7:0] count;
reg [7:0] temp;
reg [7:0] subtrahend;
reg [15:0] dividend;
reg [15:0] divisor;

always @(A, B) begin
    dividend = {A, 8'b0};
    divisor = {B, 8'b0};
    count = 0;
    quotient = 0;
    remainder = 0;
    valid = 0;
end

always @(posedge clk) begin
    if (dividend >= divisor) begin
        temp = divisor;
        subtrahend = 1;
        while (dividend >= (temp << 1)) begin
            temp = temp << 1;
            subtrahend = subtrahend << 1;
        end
        dividend = dividend - temp;
        quotient = quotient + subtrahend;
    end
    count = count + 1;
    if (count == 8) begin
        remainder = dividend[7:0];
        valid = 1;
    end
end

endmodule

module barrel_shifter (
    input clk,
    input [15:0] A,
    input [3:0] B,
    input S,
    output reg [15:0] P
);

always @(posedge clk) begin
    if (S == 0) begin
        P <= A << B;
    end else begin
        if (A[15] == 1) begin
            P <= {A[15:15], A[15:1] >> B};
        end else begin
            P <= A >> B;
        end
    end
end

endmodule

