module \$shl (A, B, Y);

parameter A_SIGNED = 0;
parameter B_SIGNED = 0;
parameter A_WIDTH = 1;
parameter B_WIDTH = 1;
parameter Y_WIDTH = 1;

input [A_WIDTH-1:0] A;
input [B_WIDTH-1:0] B;
output [Y_WIDTH-1:0] Y;

genvar i;
generate
    // Expand A to be as wide as the output
    wire [Y_WIDTH*(B_WIDTH+1)-1:0] chain;
    \$bu0 #(
        .A_SIGNED(A_SIGNED),
        .A_WIDTH(A_WIDTH),
        .Y_WIDTH(Y_WIDTH)
    ) expand (
        .A(A),
        .Y(chain[Y_WIDTH-1:0])
    );

    // Perform the barrel shift
    assign Y = chain[Y_WIDTH*(B_WIDTH+1)-1 : Y_WIDTH*B_WIDTH];
    for (i = 0; i < B_WIDTH; i = i + 1) begin:V
        wire [Y_WIDTH-1:0] unshifted, shifted, result;
        assign unshifted = chain[Y_WIDTH*i + Y_WIDTH-1 : Y_WIDTH*i];
        assign chain[Y_WIDTH*(i+1) + Y_WIDTH-1 : Y_WIDTH*(i+1)] = result;
        wire BBIT;
        if (i == B_WIDTH-1 && B_WIDTH < Y_WIDTH)
            assign BBIT = |B[B_WIDTH-1:0];
        else
            assign BBIT = B[i];
        \$__shift #(
            .WIDTH(Y_WIDTH),
            .SHIFT(0 - (2 ** (i > 30 ? 30 : i)))
        ) sh (
            .X(0),
            .A(unshifted),
            .Y(shifted)
        );
        \$mux #(
            .WIDTH(Y_WIDTH)
        ) mux (
            .A(unshifted),
            .B(shifted),
            .Y(result),
            .S(BBIT)
        );
    end
endgenerate

endmodule

