reg signed [3:0] remainder;
reg signed [3:0] temp_dividend;
reg signed [4:0] temp_divisor;
reg signed [4:0] temp_quotient;
reg signed [4:0] temp_remainder;
reg [1:0] state;

non_restoring_divider divider(
    .dividend(temp_dividend),
    .divisor(temp_divisor),
    .quotient(temp_quotient),
    .remainder(temp_remainder)
);

