    .binary(temp_quotient[3:0]),
    .bcd(bcd[7:4])
);

bcd_converter remainder_converter(
    .binary(temp_remainder[3:0]),
    .bcd(bcd[3:0])
);

always @(posedge clk) begin
    if (reset) begin
        bcd <= 8'b0;
        quotient <= 4'b0;
        remainder <= 4'b0;
        temp_dividend <= 4'b0;
        temp_divisor <= 5'b0;
        temp_quotient <= 5'b0;
        temp_remainder <= 5'b0;
        state <= 2'b00;
    end else begin
        case (state)
            2'b00: begin // Load dividend and divisor
                temp_dividend <= dividend;
                temp_divisor <= {1'b0, divisor};
                state <= 2'b01;
            end
            2'b01: begin // Initialize quotient and remainder
                quotient <= 4'b0;
                remainder <= temp_dividend;
                state <= 2'b10;
            end
            2'b10: begin // Non-restoring division algorithm
                if (select) begin // Subtraction
                    temp_remainder <= remainder + temp_divisor;
                    if (temp_remainder[4]) begin
                        quotient <= quotient << 1;
                        remainder <= temp_remainder;
                    end else begin
                        quotient <= (quotient << 1) | 1;
                        remainder <= temp_remainder[3:0];
                    end
                end else begin // Addition
                    temp_remainder <= remainder - temp_divisor;
                    if (temp_remainder[4]) begin
                        quotient <= (quotient << 1) | 1;
                        remainder <= temp_remainder;
                    end else begin
                        quotient <= quotient << 1;
                        remainder <= temp_remainder[3:0];
                    end
                end
                if (quotient == 4'b1111 || quotient == -4'b1) begin
                    state <= 2'b11;
                end
            end
            2'b11: begin // Output final value
                bcd <= {temp_quotient[3:0], temp_remainder[3:0]};
                state <= 2'b00;
            end
        endcase
