module non_restoring_divider (
    input signed [3:0] dividend,
    input signed [4:0] divisor,
    output reg signed [4:0] quotient,
    output reg signed [4:0] remainder
);

reg signed [4:0] temp_dividend;
reg signed [4:0] temp_quotient;
reg signed [4:0] temp_remainder;
reg [1:0] state;

always @(*) begin
    temp_dividend = {1'b0, dividend};
end

always @(posedge clk) begin
    case (state)
        2'b00: begin // Initialize
            temp_quotient <= 5'b0;
            temp_remainder <= temp_dividend;
            state <= 2'b01;
        end
        2'b01: begin // Non-restoring division algorithm
            temp_remainder <= temp_remainder << 1;
            if (temp_remainder[4]) begin
                temp_remainder <= temp_remainder - divisor;
                temp_quotient <= (temp_quotient << 1) | 1;
            end else begin
                temp_quotient <= temp_quotient << 1;
            end
            if (temp_quotient == 5'b11111 || temp_quotient == -5'b1) begin
                state <= 2'b10;
            end
        end
        2'b10: begin // Output quotient and remainder
