module booth_multiplier (
  input clk,
  input reset,
  input signed [3:0] A,
  input signed [3:0] B,
  output reg signed [7:0] P
);

reg signed [3:0] AC;
reg signed [3:0] Q;
reg signed [1:0] M;

always @(posedge clk, negedge reset) begin
  if (reset == 1'b0) begin
    AC <= 4'b0;
    Q <= 4'b0;
    M <= 2'b0;
    P <= 8'b0;
  end else begin
    // Booth's algorithm
    M <= {B[3], B[3:2]};
    case (M)
      2'b00: Q <= {Q[2:0], 1'b0};
      2'b01: begin
        AC <= AC + A;
        Q <= {Q[2:0], 1'b1};
      end
      2'b10: begin
        AC <= AC - A;
        Q <= {Q[2:0], 1'b0};
      end
      2'b11: Q <= {Q[2:0], 1'b0};
    endcase
    P <= {AC, Q};
  end
end

endmodule

module clock_divider (
  input clk,
  input reset,
  output reg locked,
  output reg clk_out1,
  output reg clk_out2,
  output reg clk_out3
);

  reg [23:0] count = 0;
  reg [23:0] limit1 = 0;
  reg [23:0] limit2 = 0;
  reg [23:0] limit3 = 0;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      count <= 0;
      clk_out1 <= 0;
      clk_out2 <= 0;
      clk_out3 <= 0;
      locked <= 0;
    end else begin
      count <= count + 1;
      if (count == limit1) begin
        clk_out1 <= ~clk_out1;
      end
      if (count == limit2) begin
        clk_out2 <= ~clk_out2;
      end
      if (count == limit3) begin
        clk_out3 <= ~clk_out3;
      end
      if (count == 0) begin
        locked <= 1;
      end else if (count == limit1/2) begin
        locked <= (clk_out1 == clk);
      end else if (count == limit2/2) begin
        locked <= (clk_out2 == clk);
      end else if (count == limit3/2) begin
        locked <= (clk_out3 == clk);
      end
    end
  end

  // Set the counter limits to generate the desired output frequencies
  initial begin
    limit1 = $floor($pow(2, $clog2($ceil($div(clk, 10e6))))/2);
    limit2 = $floor($pow(2, $clog2($ceil($div(clk, 20e6))))/2);
    limit3 = $floor($pow(2, $clog2($ceil($div(clk, 40e6))))/2);
  end

endmodule

module fifo_bit_sync #
  (parameter DEPTH = 16)
  (D,
   Q,
   wr_clk,
   AR);

  output [9:0] D;
  input [9:0] Q;
  input wr_clk;
  input AR;

  reg [9:0] buf [0:DEPTH-1];
  reg [3:0] front = 0;
  reg [3:0] back = 0;
  reg [3:0] count = 0;

  reg [9:0] Q_sync;
  reg [9:0] Q_reg;
  wire wr_clk_sync;

  // Bit-level synchronizer
  (* ASYNC_REG = "true" *) (* msgon = "true" *)
  FDCE #(.INIT(1'b0)) Q_sync_reg (.C(wr_clk), .CE(1'b1), .CLR(AR), .D(Q[0]), .Q(Q_sync[0]));
  (* ASYNC_REG = "true" *) (* msgon = "true" *)
  FDCE #(.INIT(1'b0)) Q_sync_reg (.C(wr_clk), .CE(1'b1), .CLR(AR), .D(Q[1]), .Q(Q_sync[1]));
  (* ASYNC_REG = "true" *) (* msgon = "true" *)
  FDCE #(.INIT(1'b0)) Q_sync_reg (.C(wr_clk), .CE(1'b1), .CLR(AR), .D(Q[2]), .Q(Q_sync[2]));
  (* ASYNC_REG = "true" *) (* msgon = "true" *)
  FDCE #(.INIT(1'b0)) Q_sync_reg (.C(wr_clk), .CE(1'b1), .CLR(AR), .D(Q[3]), .Q(Q_sync[3]));
  (* ASYNC_REG = "true" *) (* msgon = "true" *)
  FDCE #(.INIT(1'b0)) Q_sync_reg (.C(wr_clk), .CE(1'b1), .CLR(AR), .D(Q[4]), .Q(Q_sync[4]));
  (* ASYNC_REG = "true" *) (* msgon = "true" *)
  FDCE #(.INIT(1'b0)) Q_sync_reg (.C(wr_clk), .CE(1'b1), .CLR(AR), .D(Q[5]), .Q(Q_sync[5]));
  (* ASYNC_REG = "true" *) (* msgon = "true" *)
  FDCE #(.INIT(1'b0)) Q_sync_reg (.C(wr_clk), .CE(1'b1), .CLR(AR), .D(Q[6]), .Q(Q_sync[6]));
  (* ASYNC_REG = "true" *) (* msgon = "true" *)
  FDCE #(.INIT(1'b0)) Q_sync_reg (.C(wr_clk), .CE(1'b1), .CLR(AR), .D(Q[7]), .Q(Q_sync[7]));
  (* ASYNC_REG = "true" *) (* msgon = "true" *)
  FDCE #(.INIT(1'b0)) Q_sync_reg (.C(wr_clk), .CE(1'b1), .CLR(AR), .D(Q[8]), .Q(Q_sync[8]));
  (* ASYNC_REG = "true" *) (* msgon = "true" *)
  FDCE #(.INIT(1'b0)) Q_sync_reg (.C(wr_clk), .CE(1'b1), .CLR(AR), .D(Q[9]), .Q(Q_sync[9]));

  // Synchronized data register
  (* ASYNC_REG = "true" *) (* msgon = "true" *)
  FDCE #(.INIT(1'b0)) Q_reg_reg (.C(wr_clk_sync), .CE(1'b1), .CLR(AR), .D(Q_sync), .Q(Q_reg));

  // Write logic
  always @(posedge wr_clk) begin
    if (count < DEPTH) begin
      buf[back] <= Q_reg;
      back <= (back == DEPTH-1) ? 0 : back + 1;
      count <= count + 1;
    end
  end

  // Read logic
  always @(*) begin
    if (count == 0) begin
      D <= 10'b0;
    end else begin
      D <= buf[front];
    end
  end

  always @(posedge wr_clk) begin
    if (count > 0) begin
      front <= (front == DEPTH-1) ? 0 : front + 1;
      count <= count - 1;
    end
  end

endmodule

