reg [n-1:0] input_reg; // register for input signals

// Define the next state logic for each state
always @ (state or in) begin
  case (state)
    3'b000: if (in == 4'b0000) state <= 3'b000;
            else if (in == 4'b0001) state <= 3'b001;
            else if (in == 4'b0010) state <= 3'b010;
            else if (in == 4'b0011) state <= 3'b011;
            else if (in == 4'b0100) state <= 3'b100;
            else if (in == 4'b0101) state <= 3'b101;
            else if (in == 4'b0110) state <= 3'b110;
            else if (in == 4'b0111) state <= 3'b111;
            else state <= 3'b000;
    3'b001: if (in == 4'b0000) state <= 3'b000;
            else if (in == 4'b0001) state <= 3'b001;
            else if (in == 4'b0010) state <= 3'b010;
            else if (in == 4'b0011) state <= 3'b011;
            else if (in == 4'b0100) state <= 3'b100;
            else if (in == 4'b0101) state <= 3'b101;
            else if (in == 4'b0110) state <= 3'b110;
            else if (in == 4'b0111) state <= 3'b111;
            else state <= 3'b000;
    3'b010: if (in == 4'b0000) state <= 3'b000;
            else if (in == 4'b0001) state <= 3'b001;
            else if (in == 4'b0010) state <= 3'b010;
            else if (in == 4'b0011) state <= 3'b011;
            else if (in == 4'b0100) state <= 3'b100;
            else if (in == 4'b0101) state <= 3'b101;
            else if (in == 4'b0110) state <= 3'b110;
            else if (in == 4'b0111) state <= 3'b111;
            else state <= 3'b000;
    3'b011: if (in == 4'b0000) state <= 3'b000;
            else if (in == 4'b0001) state <= 3'b001;
            else if (in == 4'b0010) state <= 3'b010;
            else if (in == 4'b0011) state <= 3'b011;
            else if (in == 4'b0100) state <= 3'b100;
            else if (in == 4'b0101) state <= 3'b101;
            else if (in == 4'b0110) state <= 3'b110;
            else if (in == 4'b0111) state <= 3'b111;
            else state <= 3'b000;
    3'b100: if (in == 4'b0000) state <= 3'b000;
            else if (in == 4'b0001) state <= 3'b001;
            else if (in == 4'b0010) state <= 3'b010;
            else if (in == 4'b0011) state <= 3'b011;
            else if (in == 4'b0100) state <= 3'b100;
            else if (in == 4'b0101) state <= 3'b101;
            else if (in == 4'b0110) state <= 3'b110;
            else if (in == 4'b0111) state <= 3'b111;
            else state <= 3'b000;
    3'b101: if (in == 4'b0000) state <= 3'b000;
            else if (in == 4'b0001) state <= 3'b001;
            else if (in == 4'b0010) state <= 3'b010;
            else if (in == 4'b0011) state <= 3'b011;
            else if (in == 4'b0100) state <= 3'b100;
            else if (in == 4'b0101) state <= 3'b101;
            else if (in == 4'b0110) state <= 3'b110;
            else if (in == 4'b0111) state <= 3'b111;
            else state <= 3'b000;
    3'b110: if (in == 4'b0000) state <= 3'b000;
            else if (in == 4'b0001) state <= 3'b001;
            else if (in == 4'b0010) state <= 3'b010;
            else if (in == 4'b0011) state <= 3'b011;
            else if (in == 4'b0100) state <= 3'b100;
            else if (in == 4'b0101) state <= 3'b101;
            else if (in == 4'b0110) state <= 3'b110;
            else if (in == 4'b0111) state <= 3'b111;
            else state <= 3'b000;
    3'b111: if (in == 4'b0000) state <= 3'b000;
            else if (in == 4'b0001) state <= 3'b001;
            else if (in == 4'b0010) state <= 3'b010;
            else if (in == 4'b0011) state <= 3'b011;
            else if (in == 4'b0100) state <= 3'b100;
            else if (in == 4'b0101) state <= 3'b101;
            else if (in == 4'b0110) state <= 3'b110;
            else if (in == 4'b0111) state <= 3'b111;
            else state <= 3'b000;
  endcase
end

// Define the output logic for each state
always @ (state or in) begin
  case (state)
    3'b000: out <= 2'b00;
    3'b001: out <= 2'b01;
    3'b010: out <= 2'b10;
    3'b011: out <= 2'b11;
    3'b100: out <= 2'b00;
    3'b101: out <= 2'b01;
    3'b110: out <= 2'b10;
    3'b111: out <= 2'b11;
  endcase
end

// Register input signals
always @ (posedge clk) begin
  input_reg <= in;
end

endmodule

