module ALU_4bit(
    input [3:0] A,
    input [3:0] B,
    input [3:0] CTRL,
    output [3:0] OUT,
    output COUT,
    output ZF
    );

    wire [3:0] notB = ~B;
    wire [3:0] shift_left_B = {B[2:0], 1'b0};
    wire [3:0] shift_right_B = {1'b0, B[3:1]};
    wire [3:0] add_out;
    wire [3:0] sub_out;
    wire [3:0] and_out;
    wire [3:0] or_out;
    wire [3:0] xor_out;
    wire [3:0] not_out;
    wire [3:0] shift_left_out;
    wire [3:0] shift_right_out;

    assign add_out = A + B;
    assign sub_out = A - B;
    assign and_out = A & B;
    assign or_out = A | B;
    assign xor_out = A ^ B;
    assign not_out = ~A;
    assign shift_left_out = A << 1;
    assign shift_right_out = A >> 1;

    assign COUT = add_out[4];
    assign ZF = (OUT == 0);

    always @(*) begin
        case (CTRL)
            4'b0000: OUT = add_out;
            4'b0001: OUT = sub_out;
            4'b0010: OUT = and_out;
            4'b0011: OUT = or_out;
            4'b0100: OUT = xor_out;
            4'b0101: OUT = not_out;
            4'b0110: OUT = shift_left_out;
            4'b0111: OUT = shift_right_out;
            default: OUT = 4'bxxxx;
        endcase
    end

endmodule

module binary_adder_4bit (
    input [3:0] A,
    input [3:0] B,
    input VPB,
    input VPWR,
    input VGND,
    input VNB,
    output reg [3:0] SUM,
    output reg COUT
);

wire [3:0] carry;
wire [3:0] sum;

sky130_fd_sc_ls__ha ha0(.A(A[0]), .B(B[0]), .COUT(carry[0]), .SUM(sum[0]), .VPB(VPB), .VPWR(VPWR), .VGND(VGND), .VNB(VNB));
sky130_fd_sc_ls__ha ha1(.A(A[1]), .B(B[1]), .COUT(carry[1]), .SUM(sum[1]), .VPB(VPB), .VPWR(VPWR), .VGND(VGND), .VNB(VNB));
sky130_fd_sc_ls__ha ha2(.A(A[2]), .B(B[2]), .COUT(carry[2]), .SUM(sum[2]), .VPB(VPB), .VPWR(VPWR), .VGND(VGND), .VNB(VNB));
sky130_fd_sc_ls__ha ha3(.A(A[3]), .B(B[3]), .COUT(carry[3]), .SUM(sum[3]), .VPB(VPB), .VPWR(VPWR), .VGND(VGND), .VNB(VNB));

assign SUM = sum;
assign COUT = carry[3];

always @ (A or B) begin
    sum[0] = A[0] ^ B[0];
    carry[0] = A[0] & B[0];
    sum[1] = A[1] ^ B[1] ^ carry[0];
    carry[1] = (A[1] & B[1]) | (A[1] & carry[0]) | (B[1] & carry[0]);
    sum[2] = A[2] ^ B[2] ^ carry[1];
    carry[2] = (A[2] & B[2]) | (A[2] & carry[1]) | (B[2] & carry[1]);
    sum[3] = A[3] ^ B[3] ^ carry[2];
    carry[3] = (A[3] & B[3]) | (A[3] & carry[2]) | (B[3] & carry[2]);
end

endmodule

