module dct_processor (
  input [29:0] dct_buffer,
  input [3:0] dct_count,
  input test_ending,
  input test_has_ended,
  output reg [15:0] current_coefficient,
  output reg [3:0] total_coefficients
);

  reg [29:0] dct_buffer_reg;
  reg [3:0] dct_count_reg;
  reg [15:0] current_coefficient_reg;
  reg [3:0] total_coefficients_reg;
  reg processing;

  always @(posedge clk) begin
    if (test_ending == 1) begin
      processing <= 0;
    end else if (processing == 1 && dct_count_reg == 0) begin
      processing <= 0;
    end else if (processing == 0 && dct_count_reg > 0) begin
      processing <= 1;
    end
  end

  always @(posedge clk) begin
    if (processing == 1) begin
      current_coefficient_reg <= dct_buffer_reg[15:0];
      dct_buffer_reg <= {dct_buffer_reg[14:0], 0};
      dct_count_reg <= dct_count_reg - 1;
      if (dct_count_reg == 0) begin
        total_coefficients_reg <= total_coefficients_reg + 1;
      end
    end else begin
      current_coefficient_reg <= 0;
      dct_buffer_reg <= dct_buffer;
      dct_count_reg <= dct_count;
      total_coefficients_reg <= 0;
    end
  end

  assign current_coefficient = current_coefficient_reg;
  assign total_coefficients = total_coefficients_reg;

endmodule

module fsm_consecutive_ones_counter (
  input clk,
  input reset,
  input [7:0] in,
  output reg [3:0] count
);

  parameter IDLE = 2'b00;
  parameter COUNTING = 2'b01;
  parameter DONE = 2'b10;

  reg [1:0] state;
  reg [3:0] count_reg;
  reg [3:0] count_next;

  always @(posedge clk) begin
    if (reset) begin
      state <= IDLE;
      count_reg <= 0;
      count <= 0;
    end else begin
      case (state)
        IDLE: begin
          if (in[0] == 1) begin
            state <= COUNTING;
          end
        end
        COUNTING: begin
          if (in[0] == 1) begin
            count_next <= count_reg + 1;
          end else begin
            state <= DONE;
            count_next <= count_reg;
          end
        end
        DONE: begin
          if (in[0] == 1) begin
            state <= COUNTING;
          end else begin
            state <= IDLE;
          end
        end
      endcase
      count_reg <= count_next;
      count <= count_reg;
    end
  end

endmodule

