module modbus_master (
  input reset,
  input clk,
  input start,
  input rw,
  input [7:0] address,
  input [15:0] reg_address,
  input [15:0] num_regs,
  input [15:0] data_in,
  output busy,
  output done,
  output [15:0] data_out
);

  // Define register map
  reg [15:0] reg1;
  reg [15:0] reg2;
  reg [15:0] reg3;
  reg [15:0] reg4;

  // Define communication protocol
  reg [7:0] state;
  parameter IDLE = 8'h00;
  parameter SEND_REQUEST = 8'h01;
  parameter WAIT_RESPONSE = 8'h02;
  parameter SEND_DATA = 8'h03;
  parameter WAIT_ACK = 8'h04;

  // Define internal signals
  reg [7:0] count;
  reg [15:0] data;
  reg [15:0] response;
  reg busy_int;
  reg done_int;

  // Initialize signals
  initial begin
    state <= IDLE;
    count <= 0;
    data <= 0;
    response <= 0;
    busy_int <= 0;
    done_int <= 0;
  end

  // Define state machine
  always @(posedge clk) begin
    case(state)
      IDLE: begin
        if(start) begin
          busy_int <= 1;
          state <= SEND_REQUEST;
        end
      end
      SEND_REQUEST: begin
        count <= 0;
        data <= {rw, address, reg_address[15:8], reg_address[7:0], num_regs[15:8], num_regs[7:0]};
        state <= WAIT_RESPONSE;
      end
      WAIT_RESPONSE: begin
        if(count == 10) begin
          response <= {data[0], data[1], data[2], data[3], data[4], data[5], data[6], data[7]};
          state <= SEND_DATA;
        end
        else begin
          count <= count + 1;
        end
      end
      SEND_DATA: begin
        if(rw == 1) begin
          data <= data_in;
        end
        else begin
          data <= response;
        end
        state <= WAIT_ACK;
      end
      WAIT_ACK: begin
        if(count == 10) begin
          busy_int <= 0;
          done_int <= 1;
          state <= IDLE;
        end
        else begin
          count <= count + 1;
        end
      end
    endcase
  end

  // Assign outputs
  assign busy = busy_int;
  assign done = done_int;
  assign data_out = response;

endmodule

module modbus_slave (
  input reset,
  input clk,
  input start,
  input rw,
  input [7:0] address,
  input [15:0] reg_address,
  input [15:0] num_regs,
  input [15:0] data_in,
  output busy,
  output done,
  output [15:0] data_out
);

  // Define register map
  reg [15:0] reg1;
  reg [15:0] reg2;
  reg [15:0] reg3;
  reg [15:0] reg4;

  // Define communication protocol
  reg [7:0] state;
  parameter IDLE = 8'h00;
  parameter WAIT_REQUEST = 8'h01;
  parameter SEND_RESPONSE = 8'h02;
  parameter WAIT_DATA = 8'h03;
  parameter RECEIVE_DATA = 8'h04;
  parameter WAIT_ACK = 8'h05;

  // Define internal signals
  reg [7:0] count;
  reg [15:0] data;
  reg [15:0] request;
  reg busy_int;
  reg done_int;

  // Initialize signals
  initial begin
    state <= IDLE;
    count <= 0;
    data <= 0;
    request <= 0;
    busy_int <= 0;
    done_int <= 0;
  end

  // Define state machine
  always @(posedge clk) begin
    case(state)
      IDLE: begin
        if(start) begin
          busy_int <= 1;
          state <= WAIT_REQUEST;
        end
      end
      WAIT_REQUEST: begin
        if(count == 10) begin
          request <= data;
          state <= SEND_RESPONSE;
        end
        else begin
          count <= count + 1;
        end
      end
      SEND_RESPONSE: begin
        if(rw == 1) begin
          data <= reg1;
        end
        else begin
          data <= {reg1, reg2, reg3, reg4};
        end
        state <= WAIT_DATA;
      end
      WAIT_DATA: begin
        if(count == 10) begin
          state <= RECEIVE_DATA;
        end
        else begin
          count <= count + 1;
        end
      end
      RECEIVE_DATA: begin
        if(rw == 1) begin
          reg1 <= data_in;
        end
        else begin
          reg1 <= data[15:0];
          reg2 <= data[31:16];
          reg3 <= data[47:32];
          reg4 <= data[63:48];
        end
        state <= WAIT_ACK;
      end
      WAIT_ACK: begin
        if(count == 10) begin
          busy_int <= 0;
          done_int <= 1;
          state <= IDLE;
        end
        else begin
          count <= count + 1;
        end
      end
    endcase
  end

  // Assign outputs
  assign busy = busy_int;
  assign done = done_int;
  assign data_out = data;

endmodule

module UART_fifo_interface (
    input write_flag,
    input read_flag,
    input [7:0] data_in,
    input clock,
    input reset,
    output reg [7:0] data_out,
    output wire empty_flag,
    output wire full_flag
);

reg [7:0] memory [3:0];
reg [1:0] write_pointer;
reg [1:0] read_pointer;
wire [1:0] next_write_pointer;
wire [1:0] next_read_pointer;

assign empty_flag = (write_pointer == read_pointer);
assign full_flag = ((write_pointer == next_read_pointer) && (read_pointer == next_write_pointer));

always @(posedge clock) begin
    if (reset) begin
        write_pointer <= 2'b0;
        read_pointer <= 2'b0;
    end
    else begin
        write_pointer <= next_write_pointer;
        read_pointer <= next_read_pointer;
    end
end

always @(*) begin
    next_write_pointer = write_pointer;
    next_read_pointer = read_pointer;

    if (write_flag && !full_flag) begin
        memory[write_pointer] <= data_in;
        next_write_pointer = write_pointer + 2'b01;
    end

    if (read_flag && !empty_flag) begin
        data_out <= memory[read_pointer];
        next_read_pointer = read_pointer + 2'b01;
    end
end

endmodule

