module binary_counter
    #(parameter WIDTH = 24)
    (ram_empty_i_reg,
     RD_PNTR,
     WR_PNTR_RD,
     out,
     gpregsm1_curr_fwft_state_reg,
     p_8_out,
     aclk);

    output ram_empty_i_reg;
    output [3:0] RD_PNTR;
    input [WIDTH-1:0] WR_PNTR_RD;
    input out;
    input gpregsm1_curr_fwft_state_reg;
    input p_8_out;
    input aclk;

    wire [3:0] RD_PNTR;
    reg [WIDTH-1:0] count_reg;
    reg [WIDTH-1:0] count_d1_reg;
    wire [WIDTH-1:0] plusOp;
    wire ram_empty_i_i_4__2_n_0;
    wire [WIDTH-1:0] rd_pntr_plus1;

    /* Asynchronous reset */
    always @(posedge aclk, negedge p_8_out) begin
        if (!p_8_out) begin
            count_reg <= {WIDTH{1'b0}};
            count_d1_reg <= {WIDTH{1'b0}};
        end else begin
            count_reg <= count_d1_reg + plusOp;
            count_d1_reg <= count_reg;
        end
    end

    /* Output */
    assign RD_PNTR = count_reg[3:0];
    assign ram_empty_i_reg = (count_reg == {WIDTH{1'b0}}) ? 1'b1 : 1'b0;

    /* Counter increment */
    assign plusOp = rd_pntr_plus1 + out;

    /* Counter reset */
    always @(posedge aclk, negedge gpregsm1_curr_fwft_state_reg) begin
        if (!gpregsm1_curr_fwft_state_reg) begin
            count_reg <= {WIDTH{1'b0}};
            count_d1_reg <= {WIDTH{1'b0}};
        end
    end

    /* Counter value */
    always @(posedge aclk) begin
        rd_pntr_plus1[0] <= count_d1_reg[0];
        for (i = 1; i < WIDTH; i = i + 1) begin
            rd_pntr_plus1[i] <= count_d1_reg[i] ^ count_d1_reg[i-1];
        end
    end
endmodule

module traffic_light (
