  always @(posedge clk) begin
    if (reset) begin
      release <= 0;
      release_counter <= 0;
    end else begin
      if (release_counter < release_time) begin
        release <= 0;
        release_counter <= release_counter + 1;
      end else begin
        release <= 1;
      end
    end
  end

