    // Multiplexer
    wire [7:0] mux_sel [7:0];
    wire [3:0] mux_out [7:0];
    wire [3:0] priority_enc_out;

    priority_encoder priority_enc (
        .in(mux_sel),
        .out(priority_enc_out)
    );

    genvar i;
    generate
        for (i = 0; i < 8; i = i + 1) begin : mux_level
            if (i == 0) begin
                assign mux_sel[i] = sel[0:0];
            end else begin
                assign mux_sel[i] = {mux_sel[i-1][6:0], sel[i-1]};
            end

            mux_8to1 mux_inst (
                .in(in[(i*128 + 127):(i*128)]),
                .sel(mux_sel[i]),
                .out(mux_out[i])
            );
        end
