  assign rd_rst_asreg = rst_full_gen_i | rd_rst_asreg_d2;

  // Generate write reset signal
  assign wr_rst_asreg = rst_full_gen_i | wr_rst_asreg_d2;

  // Generate tmp_ram_rd_en signal
  assign p_18_out = 1'b1;
  assign tmp_ram_rd_en = rd_en & rd_rst_asreg & ~rst_full_gen_i & p_18_out;

  // Register read reset signal
  always @(posedge clk) begin
    rd_rst_asreg_d1 <= rd_rst_asreg;
    rd_rst_asreg_d2 <= rd_rst_asreg_d1;
  end

  // Register write reset signal
  always @(posedge clk) begin
    wr_rst_asreg_d1 <= wr_rst_asreg;
    wr_rst_asreg_d2 <= wr_rst_asreg_d1;
  end

