module binary_storage_shift(
    input clk,
    input reset, // Synchronous active-high reset
    input [7:0] d,
    input [1:0] shift_ctrl,
    output reg [7:0] q,
    output reg [7:0] q_shifted // Shifted output
);

reg [3:0] flip_flop; // 4 D flip-flops
reg [7:0] shifted_d; // Shifted input
wire [1:0] shift_amt; // Shift amount

assign shift_amt = (shift_ctrl == 2'b00) ? 2'b00 :
                   (shift_ctrl == 2'b01) ? 2'b01 :
                   (shift_ctrl == 2'b10) ? 2'b10 :
                   2'b11;

always @ (posedge clk) begin
    if (reset) begin
        q <= 8'b0;
        q_shifted <= 8'b0;
        flip_flop <= 4'b0;
    end else begin
        flip_flop <= {flip_flop[2:0], d[7]};
        q <= {flip_flop[3], flip_flop[2], flip_flop[1], flip_flop[0]};
        shifted_d <= {d[5:0], 2'b00};
        q_shifted <= shifted_d << shift_amt;
    end
end

endmodule

module shift_register(clk, reset, load, data_in, shift_out, data_out);

	input clk;
	input reset;
	input load;
	input [3:0] data_in;
	output shift_out;
	output [3:0] data_out;

	reg [3:0] reg_data;

	always @(posedge clk) begin
		if (reset) begin
			reg_data <= 4'b0;
		end else if (load) begin
			reg_data <= data_in;
		end else begin
			reg_data[3] <= reg_data[2];
			reg_data[2] <= reg_data[1];
			reg_data[1] <= reg_data[0];
			reg_data[0] <= 1'b0;
		end
	end

	assign shift_out = reg_data[3];
	assign data_out = reg_data;

endmodule

