module top_module (
    input CLK,
    input RESET,
    input LOAD,
    input SHIFT,
    input [3:0] DATA_IN,
    output reg [7:0] Q
); 

    reg [3:0] counter_data;
    wire [7:0] shifted_data;

    binary_counter counter (
        .CLK(CLK),
        .RESET(RESET),
        .LOAD(LOAD),
        .DATA_IN(DATA_IN),
        .COUNT(counter_data)
    );

    barrel_shifter shifter (
        .CLK(CLK),
        .SHIFT(SHIFT),
        .DATA({4'b0, counter_data}),
        .Q(shifted_data)
    );

    always @(posedge CLK) begin
        if (RESET) begin
            counter_data <= 4'b0;
            Q <= 8'b0;
        end else begin
            if (LOAD) begin
                counter_data <= DATA_IN;
            end else begin
                counter_data <= counter_data + 1;
            end
            Q <= {shifted_data[7:4], shifted_data[3:0]};
        end
    end

endmodule

module binary_counter (
    input CLK,
    input RESET,
    input LOAD,
    input [3:0] DATA_IN,
    output reg [3:0] COUNT
);

    always @(posedge CLK) begin
        if (RESET) begin
            COUNT <= 4'b0;
        end else begin
            if (LOAD) begin
                COUNT <= DATA_IN;
            end else begin
                COUNT <= COUNT + 1;
            end
        end
    end

endmodule

module barrel_shifter (
    input CLK,
    input SHIFT,
    input [7:0] DATA,
    output reg [7:0] Q
);

    always @(posedge CLK) begin
        if (SHIFT) begin
            Q <= {DATA[6:0], DATA[7]};
        end else begin
            Q <= {DATA[1:7], DATA[0]};
        end
    end

endmodule

module four_bit_adder (
  input [3:0] A,
  input [3:0] B,
  input Cin,
  input clk,
  input reset_n,
  output [3:0] S,
  output Cout
);

  wire [3:0] sum;
  wire [3:0] carry;
  wire [3:0] Cin_wire;
  assign Cin_wire = {Cin, 3'b0};

  // 1-bit full adder module
  full_adder FA0(.a(A[0]), .b(B[0]), .Cin(Cin_wire[0]), .sum(sum[0]), .Cout(carry[0]));
  full_adder FA1(.a(A[1]), .b(B[1]), .Cin(carry[0]), .sum(sum[1]), .Cout(carry[1]));
  full_adder FA2(.a(A[2]), .b(B[2]), .Cin(carry[1]), .sum(sum[2]), .Cout(carry[2]));
  full_adder FA3(.a(A[3]), .b(B[3]), .Cin(carry[2]), .sum(sum[3]), .Cout(Cout));

  assign S = sum;

  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      S <= 4'b0;
      Cout <= 1'b0;
    end else begin
      S <= sum;
      Cout <= Cout;
    end
  end

endmodule

// 1-bit full adder module
module full_adder (
  input a,
  input b,
  input Cin,
  output reg sum,
  output reg Cout
);

  always @(*) begin
    sum = a ^ b ^ Cin;
    Cout = (a & b) | (a & Cin) | (b & Cin);
  end

endmodule

module xor8 (
    A,
    B,
    X
);

    input [7:0] A;
    input [7:0] B;
    output [7:0] X;

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire [7:0] temp;

    // Calculate XOR of each bit
    assign temp[0] = (~A[0] & B[0]) | (A[0] & ~B[0]);
    assign temp[1] = (~A[1] & B[1]) | (A[1] & ~B[1]);
    assign temp[2] = (~A[2] & B[2]) | (A[2] & ~B[2]);
    assign temp[3] = (~A[3] & B[3]) | (A[3] & ~B[3]);
    assign temp[4] = (~A[4] & B[4]) | (A[4] & ~B[4]);
    assign temp[5] = (~A[5] & B[5]) | (A[5] & ~B[5]);
    assign temp[6] = (~A[6] & B[6]) | (A[6] & ~B[6]);
    assign temp[7] = (~A[7] & B[7]) | (A[7] & ~B[7]);

    // Assign result to output
    assign X = temp;

endmodule

module PLL (
  input ref_clk,
  input fb_clk,
  output out_clk
);

parameter fvco = 500000000; // VCO frequency
parameter N = 10; // Divider value
parameter M = 10; // Multiplier value

localparam fref = 50000000; // Reference clock frequency
localparam ffb = 55000000; // Feedback clock frequency

reg [31:0] count = 0;
reg [31:0] phase_diff = 0;
reg [31:0] prev_phase_diff = 0;
reg [31:0] control_signal = 0;
reg [31:0] vco_freq = fvco;
reg [31:0] fM = fref * M;
reg [31:0] fN = fvco / N;

always @(posedge ref_clk or posedge fb_clk) begin
  if (count == 0) begin
    prev_phase_diff = phase_diff;
    phase_diff = $countones(fb_clk) - $countones(vco_freq);
    control_signal = phase_diff - prev_phase_diff;
    vco_freq = vco_freq + control_signal;
    fN = vco_freq / N;
  end
  count <= count + 1;
  if (count == N) begin
    count <= 0;
    out_clk <= ~out_clk;
  end
end

endmodule

