module ALU_4bit(input [3:0] A, B, output [3:0] SO, output CO, input CI);

parameter LUT0 = 16'h0000;
parameter LUT1 = 16'h0000;
parameter C = 1'b1; // constant value

wire q0, q1;

// LUT0 implementation
assign q0 = LUT0 >> {D0, C, B, A};

