module CIC (
  input [n-1:0] in,
  output [m-1:0] out
);

parameter n = 4; // number of input samples per cycle
parameter m = 2; // number of output samples per cycle
parameter R = 4; // decimation or interpolation ratio
parameter N = 3; // order of the filter

wire [n-1:0] integrator_out;
wire [m-1:0] comb_out;

// Integrator stage
genvar i;
generate
  for (i = 0; i < N; i = i + 1) begin : integrator_stage
    wire [n-1:0] integrator_in;
    wire [n-1:0] integrator_out_local;
    assign integrator_in = (i == 0) ? in : integrator_out[(i-1)*n : i*n-1];
    assign integrator_out_local = (i == 0) ? integrator_in : integrator_out_local + integrator_out[(i-1)*n : i*n-1];
    assign integrator_out[i*n : (i+1)*n-1] = integrator_out_local;
  end
endgenerate

// Comb stage
genvar j;
generate
  for (j = 0; j < N; j = j + 1) begin : comb_stage
    wire [m-1:0] comb_out_local;
    assign comb_out_local = (j == 0) ? integrator_out[N*n-m : N*n-1] : comb_out_local + comb_out[(j-1)*m : j*m-1];
    assign comb_out[j*m : (j+1)*m-1] = comb_out_local;
  end
endgenerate

assign out = comb_out;

endmodule

module digital_clock (nLoad, Clk, hour2, hour1, minute2, minute1, second2, second1, 
						chour2, chour1, cminute2, cminute1, csecond2, csecond1);
	input Clk, nLoad;
	input [3:0] hour2, hour1, minute2, minute1, second2, second1;
	output reg [3:0] chour2, chour1, cminute2, cminute1, csecond2, csecond1;

	always @ (posedge Clk, negedge nLoad)

	//load initial values of the clock
	//similar to a reset
	begin
	if (~nLoad)
	begin
		chour2 <= hour2; chour1 <= hour1; cminute2 <= minute2; cminute1 <= minute1; csecond2 <= second2; csecond1 <= second1;
	end

	//run the clock
	else
	begin
	csecond1 <= csecond1 + 1;
	//seconds
	if (csecond1 > 8)
		begin
		csecond2 <= csecond2 + 1;
		csecond1 <= 0;
		end
	if ((csecond2 == 5)&(csecond1 == 9))
		begin
		cminute1 <= cminute1 + 1;
		csecond2 <= 0;
		csecond1 <= 0;
		end
	//minutes
	if ((cminute2 < 5) & (cminute1 == 9) & (csecond2 == 5) & (csecond1 == 9))
		begin
		cminute2 <= cminute2 + 1;
		cminute1 <= 0;
		end
	if ((cminute2 == 5)&(cminute1 == 9)&(csecond2 == 5)&(csecond1 == 9))
		begin
		chour1 <= chour1 + 1;
		cminute2 <= 0;
		cminute1 <= 0;
		end
	//hours
	if ((chour2 < 2) & (chour1 == 9) & (cminute2 == 5) & (cminute1 == 9) & (csecond2 == 5) & (csecond1 == 9))
			begin
			chour2 <= chour2 + 1;
			chour1 <= 0;
			end
	if ((chour2 == 2)&(chour1 == 3)&(cminute2 == 5)&(cminute1 == 9)&(csecond2==5)&(csecond1==9))
		begin
		chour2 <= 0;
		chour1 <= 0;
		end
	end
	end
endmodule

