module mealy_state_machine (
  input clk,
  input reset,
  input in1,
  input in2,
  input in3,
  output reg out1,
  output reg out2
);

  parameter S0 = 2'b00;
  parameter S1 = 2'b01;
  parameter S2 = 2'b10;
  parameter S3 = 2'b11;

  reg [1:0] state, state_next;

  always @(posedge clk) begin
    if (reset) begin
      state <= S0;
    end else begin
      state <= state_next;
    end
  end

  always @(*) begin
    case(state)
      S0: begin
        state_next = (in1 & in2) | reset ? S1 : S0;
        out1 = 1'b0;
        out2 = state_next == S3 ? 1'b1 : 1'b0;
      end
      S1: begin
        state_next = in1 & in3 ? S2 : S0;
        out1 = 1'b1;
        out2 = state_next == S3 ? 1'b1 : 1'b0;
      end
      S2: begin
        state_next = in2 & !in3 ? S3 : S0;
        out1 = 1'b1;
        out2 = state_next == S3 ? 1'b1 : 1'b0;
      end
      S3: begin
        state_next = (!in1 & in3) | reset ? S1 : S0;
        out1 = 1'b0;
        out2 = state_next == S3 ? 1'b1 : 1'b0;
      end
    endcase
  end

endmodule

module mealy_state_machine (
  input clk,
  input reset,
  input in1,
  input in2,
  output reg out,
  output reg [4:0] state
);

// State encoding
parameter A = 5'b00001;
parameter B = 5'b00010;
parameter C = 5'b00100;
parameter D = 5'b01000;
parameter E = 5'b10000;

// State variables
reg [4:0] current_state, next_state;

// Output variable
reg next_out;

// State transition logic
always @(posedge clk, negedge reset) begin
  if (!reset) begin
    current_state <= A;
  end else begin
    current_state <= next_state;
  end
end

// Output logic
always @(current_state, in1, in2) begin
  case (current_state)
    A: begin
      next_state = (in1 & in2) ? B : A;
      next_out = 0;
    end
    B: begin
      next_state = in1 ? C : A;
      next_out = in2;
    end
    C: begin
      next_state = in1 ? D : A;
      next_out = in2;
    end
    D: begin
      next_state = in1 ? E : A;
      next_out = in2;
    end
    E: begin
      next_state = A;
      next_out = in1 | in2;
    end
    default: next_state = A;
  endcase
end

// Assign next state and output to current state and output
always @(posedge clk, negedge reset) begin
  if (!reset) begin
    state <= A;
    out <= 0;
  end else begin
    state <= next_state;
    out <= next_out;
  end
end

endmodule

