    wire n_clk;
    wire n_d;
    wire n_q;

    assign n_clk = ~clk;
    assign n_d = ~d;

    nand gate1 (n_q, n_d, n_clk);
    nand gate2 (q, n_q, n_clk);

endmodule

module top_module (
    input clk,
    input [7:0] d,
    output [7:0] q
);

    wire [7:0] q_temp;

    d_flip_flop_nand ff0 (clk, d[0], q_temp[0]);
    d_flip_flop_nand ff1 (clk, d[1], q_temp[1]);
    d_flip_flop_nand ff2 (clk, d[2], q_temp[2]);
    d_flip_flop_nand ff3 (clk, d[3], q_temp[3]);
    d_flip_flop_nand ff4 (clk, d[4], q_temp[4]);
    d_flip_flop_nand ff5 (clk, d[5], q_temp[5]);
    d_flip_flop_nand ff6 (clk, d[6], q_temp[6]);
    d_flip_flop_nand ff7 (clk, d[7], q_temp[7]);

    assign q = q_temp;

endmodule

module eth_rxstatem (MRxClk, Reset, MRxDV, ByteCntEq0, ByteCntGreat2, Transmitting, MRxDEq5, MRxDEqD, 
                     IFGCounterEq24, ByteCntMaxFrame, StateData, StateIdle, StatePreamble, StateSFD, 
                     StateDrop
                    );

input         MRxClk;
input         Reset;
input         MRxDV;
input         ByteCntEq0;
input         ByteCntGreat2;
input         MRxDEq5;
input         Transmitting;
input         MRxDEqD;
input         IFGCounterEq24;
input         ByteCntMaxFrame;

output [1:0]  StateData;
output        StateIdle;
output        StateDrop;
output        StatePreamble;
output        StateSFD;

reg           StateData0;
reg           StateData1;
reg           StateIdle;
reg           StateDrop;
reg           StatePreamble;
reg           StateSFD;

wire          StartIdle;
wire          StartDrop;
wire          StartData0;
wire          StartData1;
wire          StartPreamble;
wire          StartSFD;


// Defining the next state
assign StartIdle = ~MRxDV & (StateDrop | StatePreamble | StateSFD | (|StateData));

assign StartPreamble = MRxDV & ~MRxDEq5 & (StateIdle & ~Transmitting);

assign StartSFD = MRxDV & MRxDEq5 & (StateIdle & ~Transmitting | StatePreamble);

assign StartData0 = MRxDV & (StateSFD & MRxDEqD & IFGCounterEq24 | StateData1);

assign StartData1 = MRxDV & StateData0 & (~ByteCntMaxFrame);

assign StartDrop = MRxDV & (StateIdle & Transmitting | StateSFD & ~IFGCounterEq24 &
                   MRxDEqD |  StateData0 &  ByteCntMaxFrame);

// Rx State Machine
always @ (posedge MRxClk or posedge Reset)
begin
  if(Reset)
    begin
      StateIdle     <=  1'b0;
      StateDrop     <=  1'b1;
      StatePreamble <=  1'b0;
      StateSFD      <=  1'b0;
      StateData0    <=  1'b0;
      StateData1    <=  1'b0;
    end
  else
    begin
      if(StartPreamble | StartSFD | StartDrop)
        StateIdle <=  1'b0;
      else
      if(StartIdle)
        StateIdle <=  1'b1;

      if(StartIdle)
        StateDrop <=  1'b0;
      else
      if(StartDrop)
        StateDrop <=  1'b1;

      if(StartSFD | StartIdle | StartDrop)
        StatePreamble <=  1'b0;
      else
      if(StartPreamble)
        StatePreamble <=  1'b1;

      if(StartPreamble | StartIdle | StartData0 | StartDrop)
        StateSFD <=  1'b0;
      else
      if(StartSFD)
        StateSFD <=  1'b1;

      if(StartIdle | StartData1 | StartDrop)
        StateData0 <=  1'b0;
      else
      if(StartData0)
        StateData0 <=  1'b1;

      if(StartIdle | StartData0 | StartDrop)
        StateData1 <=  1'b0;
      else
      if(StartData1)
        StateData1 <=  1'b1;
    end
end

assign StateData[1:0] = {StateData1, StateData0};

endmodule

module arithmetic_right_shift (
    input [3:0] data_in,
    input [1:0] shift_amount,
    output reg [3:0] data_out
);

    always @(*) begin
        case (shift_amount)
            2'b00: data_out = data_in;
            2'b01: data_out = {data_in[3], data_in[3:1]};
            2'b10: data_out = {data_in[3:2], data_in[3:2]};
            2'b11: data_out = {data_in[3:3], data_in[3:2]};
        endcase
    end

endmodule

module shift_reg (
    input clk,
    input load,
    input data_in,
    input shift_in,
    input reset,
    output reg [7:0] data_out
);

reg [7:0] shift_reg;

always @(posedge clk) begin
    if (reset) begin
        shift_reg <= 8'b0;
    end else if (load) begin
        shift_reg <= data_in;
    end else begin
        shift_reg <= {shift_reg[6:0], shift_in};
    end
end

assign data_out = shift_reg;

endmodule

module four_bit_adder (
    input [3:0] a,
    input [3:0] b,
    input cin,
    output [3:0] sum,
    output cout
);

    wire c1, c2, c3;

    assign sum[0] = a[0] ^ b[0] ^ cin;
    assign sum[1] = a[1] ^ b[1] ^ c1;
    assign sum[2] = a[2] ^ b[2] ^ c2;
    assign sum[3] = a[3] ^ b[3] ^ c3;

    assign cout = (a[0] & b[0]) | (a[0] & cin) | (b[0] & cin) | (c1 & c2) | (c2 & c3) | (c1 & c3);

endmodule

module three_bit_adder (
    input [2:0] a,
    input [2:0] b,
    input cin,
    output [2:0] sum,
    output cout
);

    wire c1, c2;

    assign sum[0] = a[0] ^ b[0] ^ cin;
    assign sum[1] = a[1] ^ b[1] ^ c1;
    assign sum[2] = a[2] ^ b[2] ^ c2;

    assign cout = (a[0] & b[0]) | (a[0] & cin) | (b[0] & cin) | (c1 & c2);

endmodule

module adder_control (
    input [3:0] a,
    input [3:0] b,
    input cin,
    input select,
    output [3:0] sum,
    output cout
);

    wire [2:0] a_3bit, b_3bit, sum_3bit;
    wire cout_3bit;

    assign a_3bit = a[2:0];
    assign b_3bit = b[2:0];

    four_bit_adder four_bit_adder_inst (
        .a(a),
        .b(b),
        .cin(cin),
        .sum(sum),
        .cout(cout)
    );

    three_bit_adder three_bit_adder_inst (
        .a(a_3bit),
        .b(b_3bit),
        .cin(cin),
        .sum(sum_3bit),
        .cout(cout_3bit)
    );

    assign sum = (select) ? {sum_3bit, a[3]} : sum;
    assign cout = (select) ? cout_3bit : cout;

endmodule

