module pedestrian_crossing(
    input clk,
    input rst,
    input sensor,
    input walk_btn,
    output reg led_rm,
    output reg led_ym,
    output reg led_gm,
    output reg led_rs,
    output reg led_gs
);

reg [3:0] state;
reg [3:0] ped_state;
reg [3:0] timer;
reg sensor_last;
reg walk_btn_last;
reg car_waiting;

parameter IDLE = 4'b0000;
parameter GREEN = 4'b0001;
parameter YELLOW = 4'b0010;
parameter RED = 4'b0100;

parameter PED_IDLE = 4'b0000;
parameter WALK = 4'b0001;
parameter HAND = 4'b0010;

always @(posedge clk) begin
    if (rst) begin
        state <= IDLE;
        ped_state <= PED_IDLE;
        timer <= 0;
        led_rm <= 1;
        led_ym <= 0;
        led_gm <= 0;
        led_rs <= 0;
        led_gs <= 0;
        sensor_last <= 0;
        walk_btn_last <= 0;
        car_waiting <= 0;
    end else begin
        case(state)
            IDLE: begin
                led_rm <= 1;
                led_ym <= 0;
                led_gm <= 0;
                led_rs <= 0;
                led_gs <= 1;
                if (timer == 50000000) begin
                    timer <= 0;
                    state <= GREEN;
                end else begin
                    timer <= timer + 1;
                end
            end
            GREEN: begin
                led_rm <= 0;
                led_ym <= 0;
                led_gm <= 1;
                led_rs <= 0;
                led_gs <= 1;
                if (timer == 30000000) begin
                    timer <= 0;
                    state <= YELLOW;
                end else begin
                    timer <= timer + 1;
                end
            end
            YELLOW: begin
                led_rm <= 0;
                led_ym <= 1;
                led_gm <= 0;
                led_rs <= 0;
                led_gs <= car_waiting ? 0 : 1;
                if (timer == 5000000) begin
                    timer <= 0;
                    state <= RED;
                end else begin
                    timer <= timer + 1;
                end
            end
            RED: begin
                led_rm <= 0;
                led_ym <= 0;
                led_gm <= 0;
                led_rs <= 1;
                led_gs <= 0;
                if (timer == 30000000) begin
                    timer <= 0;
                    state <= GREEN;
                end else begin
                    timer <= timer + 1;
                end
            end
        endcase

        case(ped_state)
            PED_IDLE: begin
                led_rs <= 1;
                led_gs <= 0;
                if (sensor) begin
                    ped_state <= WALK;
                end else if (walk_btn) begin
                    ped_state <= WALK;
                    timer <= 0;
                end
            end
            WALK: begin
                led_rs <= 0;
                led_gs <= 1;
                if (!sensor_last && sensor) begin
                    timer <= 0;
                end else if (timer == 100000000) begin
                    timer <= 0;
                    ped_state <= HAND;
                end
                if (!sensor) begin
                    timer <= 0;
                    ped_state <= HAND;
                end
            end
            HAND: begin
                led_rs <= 1;
                led_gs <= 0;
                if (timer == 100000000) begin
                    timer <= 0;
                    ped_state <= PED_IDLE;
                end
            end
        endcase

        if (ped_state == WALK) begin
            led_rm <= 0;
            led_ym <= 0;
            led_gm <= 0;
        end

        if (ped_state == HAND && state == GREEN) begin
            led_gs <= 1;
        end

        if (state == YELLOW && car_waiting) begin
            led_gs <= 0;
        end

        sensor_last <= sensor;
        walk_btn_last <= walk_btn;
        car_waiting <= (state == GREEN && sensor_last) || walk_btn_last;
    end
end

endmodule

module d_flip_flop (CK, D, RST, Q, QN);
input CK, D, RST;
output Q, QN;
reg Q, QN;

always @(posedge CK or negedge RST) begin
  if (!RST) begin
    Q <= 0;
    QN <= 1;
  end
  else begin
    Q <= D;
    QN <= ~D;
  end
end

endmodule

module mult4(
    input [3:0] x,
    input [3:0] y,
    output [7:0] z
);

wire [3:0] p[3:0][3:0]; // product bits
wire [4:0] c[15:0]; // carry bits

// compute product bits
assign p[0][0] = x[0] & y[0];
assign p[0][1] = x[0] & y[1];
assign p[0][2] = x[0] & y[2];
assign p[0][3] = x[0] & y[3];
assign p[1][0] = x[1] & y[0];
assign p[1][1] = x[1] & y[1];
assign p[1][2] = x[1] & y[2];
assign p[1][3] = x[1] & y[3];
assign p[2][0] = x[2] & y[0];
assign p[2][1] = x[2] & y[1];
assign p[2][2] = x[2] & y[2];
assign p[2][3] = x[2] & y[3];
assign p[3][0] = x[3] & y[0];
assign p[3][1] = x[3] & y[1];
assign p[3][2] = x[3] & y[2];
assign p[3][3] = x[3] & y[3];

// compute carry bits
genvar i, j;
generate
    for (i = 0; i < 4; i = i + 1) begin : gen1
        for (j = 0; j < 4; j = j + 1) begin : gen2
            if (i + j > 0) begin
                if (i == 0) begin
                    if (j == 1) begin
                        sumcomp FA(p[i][j], p[i][j-1], p[i][j+1], c[i+j-1], p[i][j+2], c[i+j]);
                    end else begin
                        summed HA(p[i][j], p[i][j-1], p[i][j+1], c[i+j-1]);
                    end
                end else begin
                    if (j == 0) begin
                        summed HA(p[i][j], p[i-1][j], p[i+1][j], c[i+j-1]);
                    end else if (j == 1) begin
                        sumcomp FA(p[i][j], p[i][j-1], p[i-1][j+1], c[i+j-1], p[i+1][j], c[i+j]);
                    end else begin
                        sumcomp FA(p[i][j], p[i-1][j+1], p[i][j-1], c[i+j-1], p[i+1][j], c[i+j]);
                    end
                end
            end
        end
    end
endgenerate

// compute sum bits
assign z[0] = p[0][0];
sumcomp FA(z[1], p[0][1], p[1][0], c[0], p[2][0], c[1]);
sumcomp FA(z[2], p[0][2], p[1][1], c[1], p[2][1], c[2]);
sumcomp FA(z[3], p[0][3], p[1][2], c[2], p[2][2], c[3]);
sumcomp FA(z[4], p[1][3], p[2][3], c[3], p[3][2], c[4]);
sumcomp FA(z[5], p[2][2], p[3][1], c[4], p[3][3], c[5]);
sumcomp FA(z[6], p[3][0], p[2][1], c[5], p[1][3], c[6]);
sumcomp FA(z[7], p[3][1], p[2][0], c[6], p[0][3], c[7]);

endmodule

module eth_random (MTxClk, Reset, StateJam, StateJam_q, RetryCnt, NibCnt, ByteCnt, 
                   RandomEq0, RandomEqByteCnt);

parameter Tp = 1;

input MTxClk;
input Reset;
input StateJam;
input StateJam_q;
input [3:0] RetryCnt;
input [15:0] NibCnt;
input [9:0] ByteCnt;
output RandomEq0;
output RandomEqByteCnt;

wire Feedback;
reg [9:0] x;
wire [9:0] Random;
reg  [9:0] RandomLatched;


always @ (posedge MTxClk or posedge Reset)
begin
  if(Reset)
    x[9:0] <=  0;
  else
    x[9:0] <=  {x[8:0], Feedback};
end

assign Feedback = ~(x[2] ^ x[9]);

assign Random [0] = x[0];
assign Random [1] = (RetryCnt > 1) ? x[1] : 1'b0;
assign Random [2] = (RetryCnt > 2) ? x[2] : 1'b0;
assign Random [3] = (RetryCnt > 3) ? x[3] : 1'b0;
assign Random [4] = (RetryCnt > 4) ? x[4] : 1'b0;
assign Random [5] = (RetryCnt > 5) ? x[5] : 1'b0;
assign Random [6] = (RetryCnt > 6) ? x[6] : 1'b0;
assign Random [7] = (RetryCnt > 7) ? x[7] : 1'b0;
assign Random [8] = (RetryCnt > 8) ? x[8] : 1'b0;
assign Random [9] = (RetryCnt > 9) ? x[9] : 1'b0;


always @ (posedge MTxClk or posedge Reset)
begin
  if(Reset)
    RandomLatched <=  10'h000;
  else
    begin
      if(StateJam & StateJam_q)
        RandomLatched <=  Random;
    end
end

// Random Number == 0      IEEE 802.3 page 68. If 0 we go to defer and not to backoff.
assign RandomEq0 = RandomLatched == 10'h0; 

assign RandomEqByteCnt = ByteCnt[9:0] == RandomLatched & (&NibCnt[6:0]);

endmodule

module combinational_logic_block (
  input clk,
  input [3:0] din,
  input [15:0] config,
  output dout
);

  wire lut_out;
  wire clk_prev;

  // Create the LUT
  assign lut_out = config[din];

  // Create the flip-flop
  DFF ff (
    .clk(clk),
    .d(lut_out),
    .q(dout),
    .rst(~clk_prev)
  );

  // Store the previous clk value for reset
  assign clk_prev = clk;

endmodule

// D flip-flop module
module DFF (
  input clk,
  input d,
  output reg q,
  input rst
);

  always @(posedge clk or negedge rst) begin
    if (~rst) begin
      q <= 1'b0;
    end else begin
      q <= d;
    end
  end

endmodule

module decoder (
    input [1:0] in,
    output reg [15:0] out
);

always @(*) begin
    case (in)
        2'b00: out = 16'b0000000000000001;
        2'b01: out = 16'b0000000000000010;
        2'b10: out = 16'b0000000000000100;
        2'b11: out = 16'b0000000000001000;
        default: out = 16'b0000000000000000;
    endcase
end

endmodule

module counter (
  input clk,
  input reset,
  input enable,
  output reg max_reached,
  output reg [3:0] count
);

  always @(posedge clk) begin
    if (reset) begin
      count <= 4'b0000;
      max_reached <= 1'b0;
    end
    else if (enable) begin
      count <= count + 1;
      if (count == 4'b1111) begin
        max_reached <= 1'b1;
      end
      else begin
        max_reached <= 1'b0;
      end
    end
  end

endmodule

module cinco_relojes
 (// Clock in ports
  input wire        CLK_IN1,
  // Clock out ports
  output wire       CLK_OUT1,
  output wire       CLK_OUT2,
  output wire       CLK_OUT3,
  output wire       CLK_OUT4,
  output wire       CLK_OUT5
 );

  wire clkin1,clkout0;
  // Input buffering
  //------------------------------------
  IBUFG clkin1_buf
   (.O (clkin1),
    .I (CLK_IN1));


  // Clocking primitive
  //------------------------------------
  // Instantiation of the PLL primitive
  //    * Unused inputs are tied off
  //    * Unused outputs are labeled unused
  wire [15:0] do_unused;
  wire        drdy_unused;
  wire        clkfbout;
  wire        clkfbout_buf;

  PLL_BASE
  #(.BANDWIDTH              ("OPTIMIZED"),
    .CLK_FEEDBACK           ("CLKFBOUT"),
    .COMPENSATION           ("SYSTEM_SYNCHRONOUS"),
    .DIVCLK_DIVIDE          (1),
    .CLKFBOUT_MULT          (13),
    .CLKFBOUT_PHASE         (0.000),
    .CLKOUT0_DIVIDE         (25),
    .CLKOUT0_PHASE          (0.000),
    .CLKOUT0_DUTY_CYCLE     (0.500),
    .CLKIN_PERIOD           (20.0),
    .REF_JITTER             (0.010))
  pll_base_inst
    // Output clocks
   (.CLKFBOUT              (clkfbout),
    .CLKOUT0               (clkout0),
    .CLKOUT1               (),
    .CLKOUT2               (),
    .CLKOUT3               (),
    .CLKOUT4               (),
    .CLKOUT5               (),
    .LOCKED                (),
    .RST                   (1'b0),
     // Input clock control
    .CLKFBIN               (clkfbout_buf),
    .CLKIN                 (clkin1));

  reg [3:0] clkdivider = 4'b000;
  always @(posedge clkout0)
   if (clkdivider == 4'b100)
     clkdivider <= 4'b000;
   else
     clkdivider <= clkdivider + 4'b001;

  // Output buffering
  //-----------------------------------
  BUFG clkf_buf
   (.O (clkfbout_buf),
    .I (clkfbout));

  BUFG clkout1_buf
   (.O   (CLK_OUT1),
    .I   (clkout0));

  BUFG clkout2_buf
   (.O   (CLK_OUT2),
    .I   (clkdivider[0]));

