  // Set control signals to command mode
  RS = 0;
  RW = 0;

  // Set data signals to control cursor position
  D = CURSOR_POSITION;

  // Pulse enable signal to send command to screen
  E = 1;
  #1 E = 0;
end

// Implement functionality to control display mode
always @ (DISPLAY_MODE) begin
  // Set control signals to command mode
  RS = 0;
  RW = 0;

  // Set data signals to control display mode
  D = DISPLAY_MODE;

  // Pulse enable signal to send command to screen
  E = 1;
  #1 E = 0;
end

endmodule

module debug_bridge (
  input  clk,
  input  reset_n,
  input  debugack,
  input  d_read,
  input  d_write,
