  input  [31:0] E_st_data,
  output [25:0] cpu_d_address,
  output [31:0] cpu_d_readdata,
  output        cpu_d_read,
  output        cpu_d_write,
  output        cpu_d_wait,
  output [31:0] cpu_d_writedata,
  output        dbrk_break,
  output        dbrk_goto0,
  output        dbrk_goto1,
  output        dbrk_traceme,
  output        dbrk_traceoff,
  output        dbrk_traceon,
  output        dbrk_trigout
);

  wire [31:0] dbrk_data;
  reg  dbrk_break_pulse;
  reg  dbrk_break;
  reg  dbrk_goto0;
  reg  dbrk_goto1;
  reg  dbrk_traceme;
  reg  dbrk_traceoff;
  reg  dbrk_traceon;
  reg  dbrk_trigout;

  assign cpu_d_address    = d_address;
  assign cpu_d_readdata   = av_ld_data_aligned_filtered;
  assign cpu_d_read       = d_read;
  assign cpu_d_writedata  = E_st_data;
  assign cpu_d_write      = d_write;
  assign cpu_d_wait       = d_waitrequest;

  always @(posedge clk, negedge reset_n) begin
    if (!reset_n) begin
      dbrk_break_pulse <= 0;
      dbrk_break       <= 0;
      dbrk_goto0       <= 0;
      dbrk_goto1       <= 0;
      dbrk_traceme     <= 0;
      dbrk_traceoff    <= 0;
      dbrk_traceon     <= 0;
      dbrk_trigout     <= 0;
    end else begin
      dbrk_break_pulse <= dbrk_break ? ~debugack : dbrk_break_pulse;
      dbrk_break       <= dbrk_break_pulse;
    end
  end

  assign dbrk_data = d_write ? E_st_data : av_ld_data_aligned_filtered;

  always @(posedge clk, negedge reset_n) begin
    if (!reset_n) begin
      dbrk_goto0    <= 0;
      dbrk_goto1    <= 0;
      dbrk_traceme  <= 0;
      dbrk_traceoff <= 0;
      dbrk_traceon  <= 0;
    end else begin
      dbrk_goto0    <= 1'b0;
      dbrk_goto1    <= 1'b0;
      dbrk_traceme  <= 1'b0;
      dbrk_traceoff <= 1'b0;
      dbrk_traceon  <= 1'b0;
      if (dbrk_data == 32'hdeadbeef) begin
        dbrk_traceme <= 1'b1;
      end else if (dbrk_data == 32'hfeedface) begin
        dbrk_traceoff <= 1'b1;
      end else if (dbrk_data == 32'hcafebabe) begin
        dbrk_traceon <= 1'b1;
      end else if (dbrk_data == 32'habbaabba) begin
        dbrk_goto0 <= 1'b1;
      end else if (dbrk_data == 32'hcdcdcdcd) begin
        dbrk_goto1 <= 1'b1;
      end else begin
        dbrk_trigout <= 1'b1;
      end
    end
  end

endmodule

