  always @(posedge clk or negedge areset) begin
    if (~areset) begin
      data_out <= 4'b0;
      data_complement <= 4'b0;
    end else begin
      if (shift_reg == data_in) begin
        data_out <= data_in;
        data_complement <= ~data_in;
      end
    end
  end

endmodule

module mux3(
    input in0,
    input in1,
    input in2,
    input [1:0] sel,
    input clr,
    input set,
    output reg out
);

always @(*) begin
    case(sel)
        2'b00: out = in0;
        2'b01: out = in1;
        2'b10: out = in2;
        2'b11: out = 1'b0;
    endcase
end

always @(posedge set) begin
    out <= 1'b1;
end

always @(posedge clr) begin
    out <= 1'b0;
end

endmodule

module uart_mem_interface(
    input clk, arst_n,
    input uart_rx,
    input [31:0] uart_mem_i,
    input [31:0] uart_reg_i,
    output reg [31:0] uart_tx,
    output reg uart_mem_re,
    output reg uart_mem_we,
    output reg [7:0] din_i,
    output reg re_i,
    output reg we_i
);

    // UART signals
    wire [7:0] dout_o;
    wire empty_o;
    wire full_o;
    wire sio_ce;
    wire sio_ce_x4;

    // Command register
    reg [15:0] cmd;

    // Data register
    reg [31:0] uart_dout;

    // State machine states
    parameter [2:0] stIdle = 3'b000;
    parameter [2:0] stCmd1 = 3'b001;
    parameter [2:0] stCmd2 = 3'b010;
    parameter [2:0] stData1 = 3'b011;
    parameter [2:0] stData2 = 3'b100;
    parameter [2:0] stData3 = 3'b101;
    parameter [2:0] stData4 = 3'b110;
    parameter [2:0] stRd = 3'b111;
    parameter [2:0] stWr = 3'b000;

    // State machine state register
    reg [2:0] state;

    // Instantiate UART module
    sasc_top uart_ (
        .txd_o(uart_tx),
        .rts_o(),
        .rxd_i(uart_rx),
        .cts_i(1'b0),
        .rst_n(arst_n),
        .dout_o(dout_o[7:0]),
        .full_o(full_o),
        .empty_o(empty_o),
        .clk(clk),
        .sio_ce(sio_ce),
        .sio_ce_x4(sio_ce_x4),
        .din_i(din_i[7:0]),
        .re_i(re_i),
        .we_i(we_i)
    );

    // Instantiate baud rate generator module
    sasc_brg baud_ (
        .sio_ce(sio_ce),
        .sio_ce_x4(sio_ce_x4),
        .clk(clk),
        .arst_n(arst_n)
    );

    always @ (posedge clk or negedge arst_n) begin
        if (~arst_n) begin
            state <= stIdle;
            cmd <= 0;
            uart_dout <= 0;
        end
        else begin
            case (state)
                stIdle: if (~empty_o) state <= stCmd1;
                stCmd1: if (~empty_o) state <= stCmd2;
                stCmd2: if (cmd[15]) state <= stRd; // read
                        else if (~empty_o) state <= stData1; // write
                stData1: if (cmd[15]) state <= stData2; // read
                        else if (~empty_o) state <= stData2; // write
                stData2: if (cmd[15]) state <= stData3; // read
                        else if (~empty_o) state <= stData3; // write
                stData3: if (cmd[15]) state <= stData4; // read done
                        else if (~empty_o) state <= stData4; // write
                stData4: if (cmd[15]) state <= stIdle;
                        else state <= stWr; // write commit
                stWr: state <= stIdle;
                stRd: state <= stData1;
            endcase
        end
    end

    always @ (posedge clk or negedge arst_n) begin
        if (~arst_n) cmd <= 0;
        else begin
            if (state == stIdle) cmd[15:8] <= dout_o[7:0];
            if (state == stCmd1) cmd[7:0] <= dout_o[7:0];
        end
    end

    assign uart_mem_we = (state == stWr) & cmd[14];
    assign we_i = (state == stWr) & ~cmd[14];

    always @ (cmd[15] or empty_o or state) begin
        case (state)
            stIdle: re_i <= ~empty_o;
            stCmd1: re_i <= ~empty_o;
            stCmd2: re_i <= ~empty_o & ~cmd[15];
            stData1: re_i <= ~empty_o & ~cmd[15];
            stData2: re_i <= ~empty_o & ~cmd[15];
            stData3: re_i <= ~empty_o & ~cmd[15];
            default: re_i <= 0;
        endcase
    end

    always @ (cmd[14] or state or uart_mem_i or uart_reg_i) begin
        case (state)
            stData2: din_i[7:0] <= cmd[14] ? uart_mem_i[23:16] : uart_reg_i[23:16];
            stData3: din_i[7:0] <= cmd[14] ? uart_mem_i[15:8] : uart_reg_i[15:8];
            stData4: din_i[7:0] <= cmd[14] ? uart_mem_i[7:0] : uart_reg_i[7:0];
            default: din_i[7:0] <= cmd[14] ? 0 : 0;
        endcase
    end

    always @ (cmd[15] or state) begin
        case (state)
            stData1: uart_dout[31:24] <= cmd[15] ? {8{1'b0}} : dout_o[7:0];
            stData2: uart_dout[23:16] <= cmd[15] ? {8{1'b0}} : dout_o[7:0];
            stData3: uart_dout[15:8] <= cmd[15] ? {8{1'b0}} : dout_o[7:0];
            stData4: uart_dout[7:0] <= cmd[15] ? {8{1'b0}} : dout_o[7:0];
            default: uart_dout <= 0;
        endcase
    end

    always @ (posedge clk or negedge arst_n) begin
        if (~arst_n) uart_tx <= 0;
        else begin
            if (state == stCmd2 & ~cmd[15]) uart_tx <= uart_dout[31:24];
            if (state == stData1 & ~cmd[15]) uart_tx <= uart_dout[23:16];
            if (state == stData2 & ~cmd[15]) uart_tx <= uart_dout[15:8];
            if (state == stData3 & ~cmd[15]) uart_tx <= uart_dout[7:0];
        end
    end

    assign uart_mem_re = (state == stRd);

endmodule

module complex_multiplier(
    input CLK,
    input RST,
    input ED,
    input START,
    input signed [31:0] DReal,
    input signed [31:0] DImag,
    output reg RDY,
    output reg signed [31:0] DOReal,
    output reg signed [31:0] DOImag
);

    parameter total_bits = 32;

    reg [4:0] ADDR;
    reg [1:0] state;
    reg signed [31:0] re[0:15];
    reg signed [31:0] im[0:15];
    reg signed [total_bits-1 : 0] drd,did;
    reg signed [total_bits-1 : 0] wrd,wid;
    wire signed [2*total_bits-1 : 0] drri,drii,diri,diii;
    reg signed [total_bits:0] drr,dri,dir,dii,dwr,dwi;

    initial begin
        re[0] = 32'h00010000;re[1] = 32'h0000FB15;re[2] = 32'h0000EC83;re[3] = 32'h0000D4DB;
        re[4] = 32'h0000B505;re[5] = 32'h00008E3A;re[6] = 32'h000061F8;re[7] = 32'h000031F1;
        re[8] = 32'h00000000;re[9] = 32'hFFFFCE0F;re[10] = 32'hFFFF9E08;re[11] = 32'hFFFF71C6;
        re[12] = 32'hFFFF4AFB;re[13] = 32'hFFFF2B25;re[14] = 32'hFFFF137D;re[15] = 32'hFFFF04EB;
        im[0] = 32'h00000000;im[1] = 32'hFFFFCE0F;im[2] = 32'hFFFF9E08;im[3] = 32'hFFFF71C6;
        im[4] = 32'hFFFF4AFB;im[5] = 32'hFFFF2B25;im[6] = 32'hFFFF137D;im[7] = 32'hFFFF04EB;
        im[8] = 32'hFFFF0000;im[9] = 32'hFFFF04EB;im[10] = 32'hFFFF137D;im[11] = 32'hFFFF2B25;
        im[12] = 32'hFFFF4AFB;im[13] = 32'hFFFF71C6;im[14] = 32'hFFFF9E08;im[15] = 32'hFFFFCE0F;
    end

    always @(posedge CLK) begin
        if (RST) begin
            ADDR <= 18;
            state <= 0;
            RDY <= 0;
        end
        else if (START) begin
            if (state == 0) begin
                state <= 1;
            end
            else if (state == 1) begin
                state <= 2;
                ADDR <= 0;
            end
            else if (state == 2) begin
                state <= 1;
            end
            RDY <= 0;
        end
        else if (ED) begin
            RDY <= 0;
            if (state == 2) begin
                if (ADDR != 18) begin
                    ADDR <= ADDR + 1;
                end
                drd <= DReal;
                did <= DImag;
                wrd <= re[ADDR];
                wid <= im[ADDR];
                drr <= drri[47:15];
                dri <= drii[47:15];
                dir <= diri[47:15];
                dii <= diii[47:15];
                dwr <= drr - dii;
                dwi <= dri + dir;
            end
        end
        if (ADDR == 1) begin
            RDY <= 1;
        end
    end

    assign drri = drd * wrd;
    assign diri = did * wrd;
    assign drii = drd * wid;
    assign diii = did * wid;

    assign DOReal = dwr[total_bits:1];
    assign DOImag = dwi[total_bits:1];

endmodule

module timer(clk, rst_, data, addr, cs_, oe_, we_, interrupt);
	input clk;
	input rst_;
	inout [7:0] data;
	input [7:0] addr;
	input cs_;
	input oe_;
	input we_;
	output interrupt;

	reg [7:0] r[0:7];
	reg [31:0] counter;

	// Provide read support of memory
	assign data = (~cs_ & ~oe_) ? r[addr] : 8'bzzzzzzzz;

	always @(posedge clk) begin
		if (rst_ == 1'b1) begin
			{ r[3], r[2], r[1], r[0] } <= 32'd0;
			{ r[7], r[6], r[5], r[4] } <= 32'd0;
			counter <= 32'd0;
		end
		else begin
			if (~cs_ & ~we_) begin
				r[addr] <= data;
			end
			else begin
				{ r[3], r[2], r[1], r[0] } <= counter[3:0];
				{ r[7], r[6], r[5], r[4] } <= counter[7:4];
				counter <= counter + 32'd1;
			end
		end
	end

	assign interrupt = ( { r[7], r[6], r[5], r[4] } == 32'd0 ) ? 1'b1 :
						(( { r[3], r[2], r[1], r[0] } >= { r[7], r[6], r[5], r[4] } ) ? 1'b1 : 1'b0);

endmodule

module wide_bus_selector
  (input logic [8*16-1:0] wide_input_bus,
   input logic [3:0]  selector,
   output logic [7:0] selected_out);

   always_comb begin
      case (selector)
        3'b000: selected_out = wide_input_bus[  7:  0];
        3'b001: selected_out = wide_input_bus[ 15:  8];
        3'b010: selected_out = wide_input_bus[ 23: 16];
        3'b011: selected_out = wide_input_bus[ 31: 24];
        3'b100: selected_out = wide_input_bus[ 39: 32];
        3'b101: selected_out = wide_input_bus[ 47: 40];
        3'b110: selected_out = wide_input_bus[ 55: 48];
        3'b111: selected_out = wide_input_bus[ 63: 56];
      endcase // case (selector)

   end

endmodule

module barrel_shifter (
    input [15:0] data,
    input [3:0] shift_amount,
    output reg [15:0] shifted_data
);

reg [15:0] shifted_data_reg1;
reg [15:0] shifted_data_reg2;
reg [15:0] shifted_data_reg3;

always @(*) begin
    shifted_data_reg1 = data << shift_amount;
end

always @(*) begin
    shifted_data_reg2 = shifted_data_reg1 << 1;
end

always @(*) begin
    shifted_data_reg3 = shifted_data_reg2 << 1;
end

always @(posedge clk) begin
    if (shift_amount > 15) begin
        shifted_data <= 0;
    end else begin
        shifted_data <= shifted_data_reg3;
    end
end

endmodule

module axi_protocol_converter_v2_1_b2s_rd_cmd_fsm (
///////////////////////////////////////////////////////////////////////////////
// Port Declarations
///////////////////////////////////////////////////////////////////////////////
  input  wire                                 clk           ,
  input  wire                                 reset         ,
  output wire                                 s_arready       ,
  input  wire                                 s_arvalid       ,
  input  wire [7:0]                           s_arlen         ,
  output wire                                 m_arvalid        ,
  input  wire                                 m_arready      ,
  // signal to increment to the next mc transaction
  output wire                                 next          ,
  // signal to the fsm there is another transaction required
  input  wire                                 next_pending  ,
  // Write Data portion has completed or Read FIFO has a slot available (not
  // full)
  input  wire                                 data_ready    ,
  // status signal for w_channel when command is written.
  output wire                                 a_push        ,
  output wire                                 r_push
);

////////////////////////////////////////////////////////////////////////////////
// Local parameters
////////////////////////////////////////////////////////////////////////////////
// States
localparam SM_IDLE                = 2'b00;
localparam SM_CMD_EN              = 2'b01;
localparam SM_CMD_ACCEPTED        = 2'b10;
localparam SM_DONE                = 2'b11;

////////////////////////////////////////////////////////////////////////////////
// Wires/Reg declarations
////////////////////////////////////////////////////////////////////////////////
reg [1:0]       state;
reg [1:0]       state_r1;
reg [1:0]       next_state;
reg [7:0]       s_arlen_r;

////////////////////////////////////////////////////////////////////////////////
// BEGIN RTL
///////////////////////////////////////////////////////////////////////////////

// register for timing
always @(posedge clk) begin
  if (reset) begin
    state <= SM_IDLE;
    state_r1 <= SM_IDLE;
    s_arlen_r  <= 0;
  end else begin
    state <= next_state;
    state_r1 <= state;
    s_arlen_r  <= s_arlen;
  end
end

// Next state transitions.
always @( * ) begin
  next_state = state;
  case (state)
    SM_IDLE:
      if (s_arvalid & data_ready) begin
        next_state = SM_CMD_EN;
      end else begin
        next_state = state;
      end
    SM_CMD_EN:
    ///////////////////////////////////////////////////////////////////
    // Drive m_arvalid downstream in this state
      ///////////////////////////////////////////////////////////////////
      //If there is no fifo space
      if (~data_ready & m_arready & next_pending) begin
        ///////////////////////////////////////////////////////////////////
        //There is more to do, wait until data space is available drop valid
        next_state = SM_CMD_ACCEPTED;
      end else if (m_arready & ~next_pending)begin
         next_state = SM_DONE;
      end else if (m_arready & next_pending) begin
        next_state = SM_CMD_EN;
      end else begin
        next_state = state;
      end

    SM_CMD_ACCEPTED:
      if (data_ready) begin
        next_state = SM_CMD_EN;
      end else begin
        next_state = state;
      end

    SM_DONE:
        next_state = SM_IDLE;

      default:
        next_state = SM_IDLE;
  endcase
end

// Assign outputs based on current state.

assign m_arvalid  = (state == SM_CMD_EN);
assign next    = m_arready && (state == SM_CMD_EN);
assign         r_push  = next;
assign a_push  = (state == SM_IDLE);
assign s_arready = ((state == SM_CMD_EN) || (state == SM_DONE))  && (next_state == SM_IDLE);

endmodule

module digital_clock_manager (
  input clkin,
  input PSCLK,
  input PSEN,
  input PSINCDEC,
  input RST,
  output reg CLK2X,
  output reg clk0,
  output reg CLKFB
);

parameter TRUE = 1'b1;
parameter FALSE = 1'b0;

wire clkin;
wire clkfb; 
wire clkfbbuf; 

// DCM: Digital Clock Manager Circuit for Virtex-II/II-Pro and Spartan-3/3E
// Xilinx HDL Language Template version 8.1i
DCM DCM_baseClock (
  .CLKIN(clkin), 	// Clock input (from IBUFG, BUFG or DCM)
  .PSCLK(PSCLK), 	// Dynamic phase adjust clock input
  .PSEN(PSEN), 	// Dynamic phase adjust enable input
  .PSINCDEC(PSINCDEC), 	// Dynamic phase adjust increment/decrement
  .RST(RST), 	// DCM asynchronous reset input
  .CLK2X(CLK2X),
  .CLK0(clkfb),
  .CLKFB(clkfbbuf));
  // synthesis attribute declarations
  /* synopsys attribute 
        DESKEW_ADJUST "SYSTEM_SYNCHRONOUS"
    DLL_FREQUENCY_MODE "LOW"
    DUTY_CYCLE_CORRECTION "TRUE"
    STARTUP_WAIT "TRUE"
  */

  BUFG BUFG_clkfb(.I(clkfb), .O(clkfbbuf));

  always @(posedge clkin or posedge RST) begin
    if (RST) begin
      clk0 <= FALSE;
      CLKFB <= FALSE;
      CLK2X <= FALSE;
    end else begin
      if (clkfbbuf) begin
        clk0 <= ~clk0;
      end
      CLKFB <= clk0;
      CLK2X <= ~CLK2X;
    end
  end

endmodule

module blk_mem_gen #(parameter DATA_WIDTH = 8, ADDR_WIDTH = 8, INIT_FILE = "", INIT_HEX = 0, RAM_STYLE = "block") (
    input wire clk,
    input wire rst,
    input wire we,
    input wire [ADDR_WIDTH-1:0] addr,
    input wire [DATA_WIDTH-1:0] din,
    output reg [DATA_WIDTH-1:0] dout
);

    // Declare internal signals
    reg [DATA_WIDTH-1:0] mem [0:(1<<ADDR_WIDTH)-1];

    // Initialize memory from file, if specified
    initial begin
        if (INIT_FILE != "") begin
            $readmemh(INIT_FILE, mem);
        end
    end

    // Read operation
    always @ (posedge clk) begin
        if (we) begin
            mem[addr] <= din;
        end
        dout <= mem[addr];
    end

endmodule

