module axi_stream_interface
   (AXI_En,
    En,
    FrameSize,
    M_AXIS_tdata,
    M_AXIS_tlast,
    M_AXIS_tready,
    M_AXIS_tstrb,
    M_AXIS_tvalid,
    S_AXIS_tdata,
    S_AXIS_tlast,
    S_AXIS_tready,
    S_AXIS_tstrb,
    S_AXIS_tvalid,
    m_axis_aclk,
    m_axis_aresetn);
  input AXI_En;
  input En;
  input [7:0]FrameSize;
  output [31:0]M_AXIS_tdata;
  output M_AXIS_tlast;
  input M_AXIS_tready;
  output [3:0]M_AXIS_tstrb;
  output M_AXIS_tvalid;
  input [31:0]S_AXIS_tdata;
  input S_AXIS_tlast;
  output S_AXIS_tready;
  input [3:0]S_AXIS_tstrb;
  input S_AXIS_tvalid;
  input m_axis_aclk;
  input m_axis_aresetn;

  reg [7:0] frame_count = 0;
  reg [7:0] byte_count = 0;
  reg [31:0] buffer [255:0];
  reg [7:0] buffer_size = 0;
  reg [31:0] temp_data = 0;
  reg [31:0] temp_strb = 0;
  reg temp_last = 0;
  reg [1:0] state = 0;

  wire AXI_En_1;
  wire En_1;
  wire [7:0]FrameSize_1;
  wire [31:0]S_AXIS_1_TDATA;
  wire S_AXIS_1_TLAST;
  wire S_AXIS_1_TREADY;
  wire [3:0]S_AXIS_1_TSTRB;
  wire S_AXIS_1_TVALID;
  wire m_axis_aclk_1;
  wire m_axis_aresetn_1;
  wire [31:0]sample_generator_0_M_AXIS_TDATA;
  wire sample_generator_0_M_AXIS_TLAST;
  wire sample_generator_0_M_AXIS_TREADY;
  wire [3:0]sample_generator_0_M_AXIS_TSTRB;
  wire sample_generator_0_M_AXIS_TVALID;

  assign AXI_En_1 = AXI_En;
  assign En_1 = En;
  assign FrameSize_1 = FrameSize[7:0];
  assign M_AXIS_tdata[31:0] = sample_generator_0_M_AXIS_TDATA;
  assign M_AXIS_tlast = sample_generator_0_M_AXIS_TLAST;
  assign M_AXIS_tstrb[3:0] = sample_generator_0_M_AXIS_TSTRB;
  assign M_AXIS_tvalid = sample_generator_0_M_AXIS_TVALID;
  assign S_AXIS_1_TDATA = S_AXIS_tdata[31:0];
  assign S_AXIS_1_TLAST = S_AXIS_tlast;
  assign S_AXIS_1_TSTRB = S_AXIS_tstrb[3:0];
  assign S_AXIS_1_TVALID = S_AXIS_tvalid;
  assign S_AXIS_tready = S_AXIS_1_TREADY;
  assign m_axis_aclk_1 = m_axis_aclk;
  assign m_axis_aresetn_1 = m_axis_aresetn;
  assign sample_generator_0_M_AXIS_TREADY = M_AXIS_tready;

  always @(posedge m_axis_aclk) begin
    if (!m_axis_aresetn) begin
      state <= 0;
      frame_count <= 0;
      byte_count <= 0;
      buffer_size <= 0;
      temp_data <= 0;
      temp_strb <= 0;
      temp_last <= 0;
    end else begin
      case (state)
        0: begin // Idle state
          if (En && S_AXIS_tvalid && S_AXIS_tready) begin
            state <= 1;
          end
        end
        1: begin // Header state
          if (S_AXIS_tvalid && S_AXIS_tready) begin
            temp_data <= S_AXIS_tdata;
            temp_strb <= S_AXIS_tstrb;
            temp_last <= S_AXIS_tlast;
            byte_count <= byte_count + 1;
            if (byte_count == 3) begin
              buffer_size <= temp_data[7:0];
              state <= 2;
              byte_count <= 0;
            end
          end
        end
        2: begin // Data state
          if (S_AXIS_tvalid && S_AXIS_tready) begin
            buffer[byte_count] <= S_AXIS_tdata;
            byte_count <= byte_count + 1;
            if (byte_count == buffer_size) begin
              state <= 3;
              byte_count <= 0;
            end
          end
        end
        3: begin // Last state
          if (S_AXIS_tvalid && S_AXIS_tready) begin
            temp_data <= S_AXIS_tdata;
            temp_strb <= S_AXIS_tstrb;
            temp_last <= S_AXIS_tlast;
            byte_count <= byte_count + 1;
            if (byte_count == 3) begin
              byte_count <= 0;
              if (temp_last) begin
                state <= 0;
                frame_count <= frame_count + 1;
              end else begin
                state <= 1;
              end
            end
          end
        end
      endcase
    end
  end

  assign sample_generator_0_M_AXIS_TDATA = buffer[byte_count];
  assign sample_generator_0_M_AXIS_TSTRB = temp_strb;
  assign sample_generator_0_M_AXIS_TLAST = (byte_count == buffer_size && temp_last) ? 1 : 0;
  assign sample_generator_0_M_AXIS_TVALID = (byte_count == buffer_size) ? 1 : 0;

endmodule

module traffic_light_controller (
  input clk,
  input reset,
  input [1:0] state_in,
  output reg [1:0] state_out,
  output reg red_led,
  output reg green_led
);

  parameter GREEN = 2'b00;
  parameter YELLOW = 2'b01;
  parameter RED = 2'b10;

  reg [3:0] counter;
  reg [1:0] current_state;

  always @(posedge clk) begin
    if (reset) begin
      counter <= 0;
      current_state <= GREEN;
    end
    else begin
      case (current_state)
        GREEN: begin
          green_led <= 1;
          red_led <= 0;
          if (counter == 20000000) begin
            current_state <= YELLOW;
            counter <= 0;
          end
          else begin
            counter <= counter + 1;
          end
        end
        YELLOW: begin
          green_led <= 0;
          red_led <= 1;
          if (counter == 4000000) begin
            current_state <= RED;
            counter <= 0;
          end
          else begin
            counter <= counter + 1;
          end
        end
        RED: begin
          green_led <= 0;
          red_led <= 1;
          if (counter == 20000000) begin
            current_state <= GREEN;
            counter <= 0;
          end
          else begin
            counter <= counter + 1;
          end
        end
      endcase
    end
  end

  always @(posedge clk) begin
    state_out <= current_state;
  end

endmodule

module top_module ( 
    input [31:0] a, // 32-bit input for adder
    input [31:0] b, // 32-bit input for adder
    input select, // Select input to choose between decoder and functional module
    output [7:0] out // 8-bit output from the active module
);

    wire [31:0] sum; // 32-bit sum output from the adder
    wire [7:0] upper_byte; // 8-bit upper byte output from the decoder
    wire [7:0] lower_byte; // 8-bit lower byte output from the decoder
    wire [7:0] product; // 8-bit product output from the functional module

    carry_select_adder adder(.a(a), .b(b), .sum(sum)); // Instantiate the carry select adder module
    decoder_mux_16bit decoder(.in(sum), .upper_byte(upper_byte), .lower_byte(lower_byte)); // Instantiate the decoder and multiplexer module
    functional_module func(.a(upper_byte), .b(lower_byte), .out(product)); // Instantiate the functional module

    assign out = select ? product : {upper_byte, lower_byte}; // Multiplexer to select between decoder and functional module based on select input

endmodule

module carry_select_adder ( 
    input [31:0] a, // 32-bit input A
    input [31:0] b, // 32-bit input B
    output reg [31:0] sum // 32-bit sum output
);

    wire [31:0] carry_out; // Carry output from the first adder
    wire [31:0] carry_in; // Carry input to the second adder

    assign carry_in[0] = 1'b0; // Set the initial carry input to 0

    // First adder with carry select logic
    genvar i;
    generate
        for (i = 0; i < 16; i = i + 1) begin : adder_block
            ripple_adder adder(.a(a[i*2 +: 2]), .b(b[i*2 +: 2]), .sum(sum[i*2 +: 2]), .carry_out(carry_out[i]));
            assign carry_in[i+1] = carry_out[i];
        end
    endgenerate

    // Second adder with carry select logic
    ripple_adder adder(.a(a[31:16]), .b(b[31:16]), .sum(sum[31:16]), .carry_out(carry_out[15]));
    assign carry_in[16] = carry_out[15];

    generate
        for (i = 0; i < 16; i = i + 1) begin : select_block
            assign sum[i*2 +: 2] = carry_in[i] ? {16'd0, sum[i*2 +: 2]} : {sum[i*2 +: 2], 16'd0};
        end
    endgenerate

endmodule

module ripple_adder ( 
    input [1:0] a, // 2-bit input A
    input [1:0] b, // 2-bit input B
    output reg [1:0] sum, // 2-bit sum output
    output carry_out // Carry output
);

    always @(*) begin
        sum = a + b;
        carry_out = (sum > 2'b11) ? 1'b1 : 1'b0;
    end

endmodule

module decoder_mux_16bit ( 
    input [15:0] in, // 16-bit input
    output reg [7:0] upper_byte, // 8-bit upper byte output
    output reg [7:0] lower_byte // 8-bit lower byte output
);

    always @(*) begin
        case (in[15:12])
            4'b0000: begin
                upper_byte = in[7:0];
                lower_byte = in[15:8];
            end
            4'b0001: begin
                upper_byte = in[8:1];
                lower_byte = in[15:8];
            end
            4'b0010: begin
                upper_byte = in[9:2];
                lower_byte = in[15:8];
            end
            4'b0011: begin
                upper_byte = in[10:3];
                lower_byte = in[15:8];
            end
            4'b0100: begin
                upper_byte = in[11:4];
                lower_byte = in[15:8];
            end
            4'b0101: begin
                upper_byte = in[12:5];
                lower_byte = in[15:8];
            end
            4'b0110: begin
                upper_byte = in[13:6];
                lower_byte = in[15:8];
            end
            4'b0111: begin
                upper_byte = in[14:7];
                lower_byte = in[15:8];
            end
            default: begin
                upper_byte = 8'd0;
                lower_byte = 8'd0;
            end
        endcase
    end

endmodule

module functional_module ( 
    input [7:0] a, // 8-bit input A
    input [7:0] b, // 8-bit input B
    output reg [7:0] out // 8-bit product output
);

    always @(*) begin
        out = a * b;
    end

endmodule

module full_adder(
  input a,
  input b,
  input cin,
  output sum,
  output cout
);

  assign sum = a ^ b ^ cin;
  assign cout = (a & b) | (a & cin) | (b & cin);

endmodule

module carry_lookahead_adder(
  input a,
  input b,
  input cin,
  output sum,
  output cout
);

  wire p, g;

  assign p = a ^ b;
  assign g = a & b;

  assign sum = p ^ cin;
  assign cout = g | (p & cin);

endmodule

module ripple_carry_adder(
  input [15:0] a,
  input [15:0] b,
  input cin,
  output [15:0] sum,
  output cout
);

  wire [15:0] carry;
  wire [15:0] s;

  genvar i;
  generate
    for(i = 0; i < 16; i = i + 1) begin : ripple_carry_adder_gen
      full_adder fa(
        .a(a[i]),
        .b(b[i]),
        .cin(carry[i]),
        .sum(s[i]),
        .cout(carry[i+1])
      );
    end
  endgenerate

  assign sum = s;
  assign cout = carry[15];

endmodule

module adder_16bit(
  input [15:0] A,
  input [15:0] B,
  output [15:0] Y
);

  wire [15:0] carry;

  carry_lookahead_adder cla0(
    .a(A[0]),
    .b(B[0]),
    .cin(1'b0),
    .sum(Y[0]),
    .cout(carry[0])
  );

  genvar i;
  generate
    for(i = 1; i < 16; i = i + 1) begin : adder_16bit_gen
      carry_lookahead_adder cla(
        .a(A[i]),
        .b(B[i]),
        .cin(carry[i-1]),
        .sum(Y[i]),
        .cout(carry[i])
      );
    end
  endgenerate

  ripple_carry_adder rca(
    .a(A),
    .b(B),
    .cin(carry[15]),
    .sum(Y),
    .cout()
  );

endmodule

