// Up-counter module
module up_counter (
    input clk,
    input reset,
    output reg [3:0] out
);

    always @(posedge clk) begin
        if (reset) begin
            out <= 4'b0;
        end else begin
            out <= out + 1;
        end
    end

endmodule

// 2:1 Multiplexer module
module mux_2to1 (
    input a,b,c,
    output x,y,z
);

    assign x = c ? b : a;
    assign y = c ? a : b;
    assign z = c ? a : d;

endmodule

// Functional module
module functional_module (
    input [3:0] counter_out,
    input [3:0] mux_out,
    output reg [15:0] q
);

