module full_adder(
    input A,
    input B,
    input C,
    output F,
    output Cout
);

wire w1, w2, w3;

// First XOR gate
xor(w1, A, B);

// Second XOR gate
xor(F, w1, C);

// AND gate
and(w2, w1, C);

// Third XOR gate
xor(Cout, A, B, C);

// OR gate
or(w3, w2, Cout);

assign Cout = w3;

endmodule

