module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] d,
    input select,     // Select input to choose between modes
    output [7:0] q
);

    // Mode 1: D flip-flops triggered by negative edge of clk
    reg [7:0] mode1_q;
    always @(negedge clk, posedge reset) begin
        if (reset) begin
            mode1_q <= 8'b0;
        end else begin
            mode1_q <= d;
        end
    end

    // Mode 2: D flip-flops created using T flip-flops and logic gates
    reg [7:0] mode2_q;
    wire [7:0] mode2_t;
    assign mode2_t = mode2_q ^ d;
    always @(posedge clk, posedge reset) begin
        if (reset) begin
            mode2_q <= 8'b0;
        end else begin
            mode2_q <= mode2_t;
        end
    end

    // Mode select logic
    wire mode1_select = ~select;
    wire mode2_select = select;

    // Output sum of mode 1 and mode 2
    assign q = mode1_select ? mode1_q : mode2_q + mode1_q;

endmodule

module priority_encoder_multiplier (
    input [7:0] a, b, c, d,
    output [7:0] final_output);

    reg [1:0] index;
    reg [7:0] max_value;
    reg [7:0] constant = 2;

    always @* begin
        if (a >= b && a >= c && a >= d) begin
            max_value = a;
            index = 2'b00;
        end else if (b >= c && b >= d) begin
            max_value = b;
            index = 2'b01;
        end else if (c >= d) begin
            max_value = c;
            index = 2'b10;
        end else begin
            max_value = d;
            index = 2'b11;
        end
    end

    always @* begin
        case (index)
            2'b00: final_output = (max_value * constant) >> 1;
            2'b01: final_output = (max_value * constant) >> 1;
            2'b10: final_output = (max_value * constant) >> 2;
            2'b11: final_output = (max_value * constant) >> 2;
        endcase
    end

endmodule

module up_down_counter (
    input LOAD,
    input UP,
    input DOWN,
    input RESET,
    output reg [3:0] COUNT
);

    always @ (posedge RESET)
    begin
        COUNT <= 4'b0000;
    end

    always @ (posedge LOAD)
    begin
        COUNT <= $random;
    end

    always @ (posedge UP, posedge DOWN)
    begin
        if (UP && !DOWN)
            COUNT <= COUNT + 1;
        else if (!UP && DOWN)
            COUNT <= COUNT - 1;
    end

endmodule

module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out
);

reg [7:0] shift_reg [2:0];
reg [9:0] acc_reg;
reg [1:0] count;

always @(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        acc_reg <= 10'b0;
        count <= 2'b0;
        valid_b <= 1'b0;
        data_out <= 10'b0;
        shift_reg[0] <= 8'b0;
        shift_reg[1] <= 8'b0;
        shift_reg[2] <= 8'b0;
    end
    else begin
        if(valid_a && ready_b) begin
            shift_reg[0] <= data_in;
            shift_reg[1] <= shift_reg[0];
            shift_reg[2] <= shift_reg[1];
            acc_reg <= acc_reg + data_in;
            count <= count + 1;
            if(count == 2) begin
                data_out <= acc_reg;
                valid_b <= 1'b1;
                count <= 2'b0;
            end
            else begin
                valid_b <= 1'b0;
            end
        end
        else begin
            valid_b <= 1'b0;
        end
    end
end

assign ready_a = ~valid_b;

endmodule

module gpio_regs (/*AUTOARG*/
   // Outputs
   data_out, gpio_oen, gpio_data_out, interrupt,
   // Inputs
   clk, reset, port_id, data_in, read_strobe, write_strobe,
   gpio_data_in
   ) ;

   parameter GPIO_BASE_ADDRESS = 8'h00;   

   input clk;
   input reset;

   input [7:0]            port_id;
   input [7:0]            data_in;
   output [7:0]           data_out;
   input                  read_strobe;
   input                  write_strobe;   

   output [7:0]           gpio_oen;
   output [7:0]           gpio_data_out;
   input [7:0]            gpio_data_in;

   output                 interrupt;

   reg                    interrupt  = 0;
   reg [7:0]              data_out   = 8'h00; 


   reg [7:0]              gpio_oen      = 8'h00;
   reg [7:0]              gpio_data_out = 8'h00;
   reg [7:0]              gpio_control  = 8'h00;
   reg [7:0]              gpio_irq_mask = 8'hFF;
   reg [7:0]              gpio_irq      = 8'h00;


   //
   // Address Decode
   //
   wire                   gpio_oen_enable      = (port_id == (GPIO_BASE_ADDRESS + 0));
   wire                   gpio_data_in_enable  = (port_id == (GPIO_BASE_ADDRESS + 1));  //Read Only
   wire                   gpio_data_out_enable = (port_id == (GPIO_BASE_ADDRESS + 1));  //Write Only
   wire                   gpio_control_enable  = (port_id == (GPIO_BASE_ADDRESS + 2));
   wire                   gpio_irq_mask_enable = (port_id == (GPIO_BASE_ADDRESS + 3));
   wire                   gpio_irq_enable      = (port_id == (GPIO_BASE_ADDRESS + 4));


   //
   // GPIO Edge Change detection
   //
   reg [7:0]              gpio_data_in_previous = 1'b0;
   wire [7:0]             gpio_edge_detection = gpio_data_in_previous ^ gpio_data_in;
   always @(posedge clk) begin
      gpio_data_in_previous <= gpio_data_in;      
   end

   //
   // If a positive edge is happening, capture it as a possible interrupt
   // Must write a 1 to the bit to clear it
   //
   always @(posedge clk)
     if (gpio_edge_detection) begin
        gpio_irq <= gpio_edge_detection;        
     end else if (write_strobe & gpio_irq_enable) begin
        gpio_irq <= gpio_irq & ~data_in;        
     end

   //
   // Interrupt logic -- capture positive edge and mask bit is clear
   //

   always @(posedge clk)
     if (gpio_irq & ~gpio_irq_mask) begin
        interrupt <= 1'b1;        
     end else begin
        interrupt <= 1'b0;        
     end

   //
   // Register Writing
   //
   always @(posedge clk)
     if (write_strobe == 1'b1) begin
        if (gpio_oen_enable) begin
           gpio_oen <= data_in;           
        end

        if (gpio_data_out_enable) begin
           gpio_data_out <= data_in;           
        end

        if (gpio_control_enable) begin
           gpio_control <= data_in;           
        end        

        if (gpio_irq_mask_enable) begin
           gpio_irq_mask <= data_in;           
        end 

     end

   //
   // Register Reading
   //
   always @(posedge clk) begin

//      if (read_strobe) begin

         if (gpio_oen_enable) begin
            data_out <= gpio_oen;           
         end

         else if (gpio_data_out_enable) begin
            data_out <= gpio_data_in;           
         end

         else if (gpio_control_enable) begin
            data_out <= gpio_control;           
         end

         else if (gpio_irq_mask_enable) begin
            data_out <= gpio_irq_mask;           
         end

         else if (gpio_irq_enable) begin
            data_out <= gpio_irq;           
         end

         else begin
            data_out <= 8'h00;            
         end

//      end // if (read_strobe)
   end // always @ (posedge clk)



endmodule

