module processingUnit(clk, a_in, a_out, b_out, b_in, enable);

    input clk;
    input [31:0] a_in;
    output [31:0] a_out;
    output [31:0] b_out;
    input [31:0] b_in;
    input enable;

    wire signed [7:0] coeff;
    assign coeff = $signed({32{enable}} & {24'h0, in_coeff});

    reg signed [31:0] a_reg;
    reg signed [31:0] b_reg;

    always @ (posedge clk) begin
        a_reg <= a_in;
        b_reg <= a_reg * coeff + b_in;
        a_out <= a_reg;
        b_out <= b_reg;
    end

endmodule

