module shift_register ( input clk, input d, output q );
  reg [2:0] register;
  wire select;

  // D flip-flops
  always @(posedge clk) begin
    register <= {register[1:0], d};
  end

  // Multiplexer
  assign select = (register == 3'b000) ? 1'b0 :
                  (register == 3'b001) ? 1'b0 :
                  (register == 3'b010) ? 1'b0 :
                  (register == 3'b011) ? 1'b1 :
                  (register == 3'b100) ? 1'b0 :
                  (register == 3'b101) ? 1'b1 :
                  (register == 3'b110) ? 1'b1 :
                  (register == 3'b111) ? 1'b1 : 1'b0;

  assign q = select ? register[2] : (select ? register[1] : register[0]);
endmodule

module mii_sequence(
  input c, // clock signal
  input start, // start signal
  output mdc, // Management Data Clock signal
  inout mdio // Management Data Input/Output signal
);

  // MII interface signals
  wire [4:0] mii_phyad;
  wire [4:0] mii_addr;
  wire [15:0] mii_wdata;
  wire [15:0] mii_rdata;
  wire mii_req, mii_we, mii_ack;

  // MII Management block instantiation
  mii_mgmt #(.CLK_MHZ(125), .MDC_KHZ(500)) mii(
    .clk(c), .phyad(mii_phyad), .addr(mii_addr),
    .wdata(mii_wdata), .rdata(mii_rdata),
    .req(mii_req), .we(mii_we), .ack(mii_ack),
    .mdc(mdc), .mdio(mdio)
  );

  // ROM for the MII sequence
  wire [3:0] seq_addr;
  reg [31:0] seq_q;
  always @(posedge c) begin
    case (seq_addr)
      4'h0: seq_q = 32'h8009_1c00; // disable 1g speed
      4'h1: seq_q = 32'h8109_1c00; // disable 1g speed
      4'h2: seq_q = 32'h8000_0340; // force 100M speed
      4'h3: seq_q = 32'h8100_0340; // force 100M speed
      default: seq_q = 32'h0;
    endcase
  end

  // State machine for controlling the MII sequence
  localparam ST_IDLE  = 3'h0;
  localparam ST_TXRX  = 3'h1;
  localparam ST_CHILL = 3'h2;

  localparam SW=3, CW=4;
  reg [CW+SW-1:0] ctrl;
  wire [SW-1:0] state;
  wire [SW-1:0] next_state = ctrl[SW+CW-1:CW];
  r #(SW) state_r(.c(c), .rst(1'b0), .en(1'b1), .d(next_state), .q(state));

  wire [15:0] chill_cnt;

  always @* begin
    case (state)
      ST_IDLE:
        if (start)   ctrl = { ST_TXRX , 4'b0000 };
        else         ctrl = { ST_IDLE , 4'b0000 };
      ST_TXRX:
        if (mii_ack) ctrl = { ST_CHILL, 4'b0000 };
        else         ctrl = { ST_TXRX , 4'b0000 };
      ST_CHILL:
        if (chill_cnt == 16'h1000)
          if (seq_addr == 4'h3) ctrl = { ST_IDLE , 4'b0000 };
          else                  ctrl = { ST_TXRX , 4'b0001 };
        else                    ctrl = { ST_CHILL, 4'b0000 };
      default:      ctrl = { ST_IDLE, 4'b0000 };
    endcase
  end

  // Counter for the chill state
  r #(16) chill_cnt_r(
    .c(c), .rst(state == ST_TXRX), .d(chill_cnt + 1'b1), .en(1'b1), .q(chill_cnt)
  );

  // Counter for the ROM address
  r #(4) seq_addr_r(
    .c(c), .rst(state == ST_IDLE), .en(ctrl[0]), 
    .d(seq_addr + 1'b1), .q(seq_addr)
  );

  // Control signals for the MII interface
  assign mii_req   = state == ST_TXRX;
  assign mii_we    = seq_q[31];
  assign mii_phyad = seq_q[28:24];
  assign mii_wdata = seq_q[15:0];
  assign mii_addr  = seq_q[20:16];

endmodule

