wire [31:0] mux_out;
wire [31:0] final_out;

subtractor sub(a, b, sub_out);
mux mux_inst(sub_out, a, b, 32'h0, mux_out);
final_output final_inst(sub_out, select, a, b, 32'h0, final_out);

assign result = select ? mux_out : final_out;

endmodule

//Carry select adder module for subtraction
module subtractor (
    input [31:0] a,
    input [31:0] b,
    output [31:0] result
);

wire [31:0] a_inv;
wire [31:0] b_inv;
wire [31:0] carry_in;
wire [31:0] carry_out;
wire [31:0] sum;

assign a_inv = ~a;
assign b_inv = ~b;

//Generate carry select signals
assign carry_in[0] = 1'b0;
genvar i;
generate
    for (i = 1; i < 32; i = i + 1) begin : carry_select
        assign carry_in[i] = (a[i-1] & b[i-1]) | (a[i-1] & carry_out[i-1]) | (b[i-1] & carry_out[i-1]);
    end
endgenerate

//Generate sum signals
assign sum[0] = a[0] ^ b[0] ^ carry_in[0];
generate
    for (i = 1; i < 32; i = i + 1) begin : sum_gen
        assign sum[i] = a[i] ^ b[i] ^ carry_in[i];
    end
endgenerate

//Generate carry out signal
assign carry_out[0] = (a[0] & b[0]) | (a[0] & carry_in[0]) | (b[0] & carry_in[0]);
generate
    for (i = 1; i < 32; i = i + 1) begin : carry_out_gen
        assign carry_out[i] = (a[i] & b[i]) | (a[i] & carry_out[i-1]) | (b[i] & carry_out[i-1]);
    end
endgenerate

assign result = sum;

endmodule

