module periodic_signal_gen
    #(parameter PSC=1)
    (input wire i_clk,
     input wire i_rst,
     output wire o_udf,
     output wire o_ovf,
     output wire o_udf_div2,
     output wire o_ovf_div2,
     output wire o_period);

    localparam PSC_TOP = PSC - 1;

    localparam BITS = $clog2(PSC_TOP+1);

    reg[BITS-1:0] count;
    reg[BITS-1:0] count_div2;

    wire count_is_zero = count == 0;
    wire count_is_top = count == PSC_TOP;
    wire count_div2_is_zero = count_div2 == 0;
    wire count_div2_is_top = count_div2 == PSC_TOP;

    reg period;

    assign o_period = period;

    always @(posedge i_clk or negedge i_rst) begin
        if(!i_rst) begin
            count <= 'd0;
            count_div2 <= 'd0;
            period <= 'd0;
        end else begin
            if(count_is_top) begin
                count <= 'd0;
                if(PSC % 2 == 0) begin
                    count_div2 <= count_div2 + 'd1;
                end
                period <= !period;
            end else begin
                count <= count + 'd1;
                if(PSC % 2 == 0 && count_div2_is_top) begin
                    count_div2 <= 'd0;
                end else if(PSC % 2 == 0) begin
                    count_div2 <= count_div2 + 'd1;
                end
                period <= period;
            end
        end
    end

    assign o_udf = i_rst & count_is_zero;
    assign o_ovf = i_rst & count_is_top;
    assign o_udf_div2 = i_rst & count_div2_is_zero & !period;
    assign o_ovf_div2 = i_rst & count_div2_is_top & period;

endmodule

