module vending_machine (
  input btnA,
  input btnB,
  input btnC,
  output reg dispenseBar,
  output reg dispenseChips,
  output reg dispenseSoda
);

  reg [1:0] state;

  parameter IDLE = 2'b00;
  parameter DISPENSING = 2'b01;
  parameter RESET = 2'b10;

  always @* begin
    case(state)
      IDLE: begin
        dispenseBar = 0;
        dispenseChips = 0;
        dispenseSoda = 0;
        if(btnA) begin
          dispenseBar = 1;
          state = DISPENSING;
        end else if(btnB) begin
          dispenseChips = 1;
          state = DISPENSING;
        end else if(btnC) begin
          dispenseSoda = 1;
          state = DISPENSING;
        end else begin
          state = IDLE;
        end
      end
      DISPENSING: begin
        dispenseBar = 0;
        dispenseChips = 0;
        dispenseSoda = 0;
        state = RESET;
      end
      RESET: begin
        dispenseBar = 0;
        dispenseChips = 0;
        dispenseSoda = 0;
        state = IDLE;
      end
      default: begin
        dispenseBar = 0;
        dispenseChips = 0;
        dispenseSoda = 0;
        state = IDLE;
      end
    endcase
  end

endmodule

module myModule (
    input [1:0] in,
    output [1:0] out
);

reg [63:0] result;
wire [63:0] expected_sum = 64'hbb2d9709592f64bd;
reg [63:0] crc;
reg [63:0] sum;
reg [6:0] cyc;

assign out = result[1:0];

Test test (
    .out(out),
    .in(in)
);

always @(posedge clk) begin
    cyc <= cyc + 1;
    crc <= {crc[62:0], crc[63]^crc[2]^crc[0]};
    sum <= result ^ {sum[62:0],sum[63]^sum[2]^sum[0]};

    if (cyc == 0) begin
        crc <= 64'h5aef0c8d_d70a4497;
    end
    else if (cyc < 10) begin
        sum <= 64'h0;
    end
    else if (cyc < 90) begin
        result <= {62'h0, in};
    end
    else if (cyc == 99) begin
        if (crc !== 64'hc77bb9b3784ea091) $stop;
        if (sum !== expected_sum) $stop;
        $display("*-* All Finished *-*");
        $finish;
    end
end

endmodule

