  assign gray_pipe4[0] = gray_pipe3[0];
  assign gray_pipe4[1] = gray_pipe3[1];
  assign gray_pipe4[2] = gray_pipe3[2];
  assign gray_pipe4[3] = gray_pipe3[3];
