module fifo_bt_txd_blk_mem_gen
   (D,
    wr_clk,
    rd_clk,
    WEA,
    tmp_ram_rd_en,
    SR,
    Q,
    count_d1_reg,
    din);

  parameter ADDR_WIDTH = 9; // depth of the FIFO
  parameter DATA_WIDTH = 8; // width of the data stored in the FIFO

  input wr_clk;
  input rd_clk;
  input [0:0]WEA;
  input tmp_ram_rd_en;
  input [0:0]SR;
  input [DATA_WIDTH-1:0]din;
  input [ADDR_WIDTH-1:0]count_d1_reg;
  output [DATA_WIDTH-1:0]D;
  output [ADDR_WIDTH-1:0]Q;

  reg [ADDR_WIDTH-1:0] write_addr = 0;
  reg [ADDR_WIDTH-1:0] read_addr = 0;
  reg [ADDR_WIDTH-1:0] count = 0;
  reg [DATA_WIDTH-1:0] fifo_mem [0:(1<<ADDR_WIDTH)-1];

  assign Q = count;

  always @(posedge wr_clk) begin
    if (WEA && count < (1<<ADDR_WIDTH)) begin
      fifo_mem[write_addr] <= din;
      write_addr <= write_addr + 1;
      count <= count + 1;
    end
  end

  always @(posedge rd_clk) begin
    if (tmp_ram_rd_en && count > 0) begin
      D <= fifo_mem[read_addr];
      read_addr <= read_addr + 1;
      count <= count - 1;
    end
  end

  always @(posedge wr_clk, posedge rd_clk, posedge SR) begin
    if (SR) begin
      write_addr <= 0;
      read_addr <= 0;
      count <= 0;
    end
  end

endmodule

