module top_module (
    input clk,                     // Clock input
    input reset,                   // Synchronous active-high reset
    input [7:0] in,                // 8-bit data input
    output reg [8:0] out           // 9-bit output with parity bit
);

    wire [7:0] data = in;          // Input data
    wire [2:0] priority;           // Priority encoder output
    wire parity_bit;               // Parity bit output
    wire [8:0] mux_out;            // Multiplexer output

    priority_encoder pe(.in(data), .out(priority));   // Priority encoder module instantiation

    // Multiplexer implementation
    assign mux_out = {data, priority};

    // D flip-flop with synchronous reset implementation
    reg [8:0] dff_out;
    always @(negedge clk) begin
        if (reset) begin
            dff_out <= 9'b0;
        end else begin
            dff_out <= mux_out;
        end
    end

    assign out = dff_out;           // Output assignment

endmodule

// Priority encoder module
module priority_encoder (
    input [7:0] in,                // 8-bit input
    output reg [2:0] out           // Priority encoder output
);

    always @(*) begin
        casez(in)
            8'b00000001: out = 3'b000;
            8'b00000010: out = 3'b001;
            8'b00000100: out = 3'b010;
            8'b00001000: out = 3'b011;
            8'b00010000: out = 3'b100;
            8'b00100000: out = 3'b101;
            8'b01000000: out = 3'b110;
            8'b10000000: out = 3'b111;
            default: out = 3'b000;   // Default case for no bits set to 1
        endcase
    end

endmodule

module traffic_light_controller (
  input clk,
  input reset,
  output reg red,
  output reg yellow,
  output reg green
);

  reg [3:0] state;

  always @(posedge clk) begin
    if (reset) begin
      state <= 4'b0000;
      red <= 1'b0;
      yellow <= 1'b0;
      green <= 1'b0;
    end
    else begin
      case (state)
        4'b0000: begin // Green light on for 10 clock cycles
          green <= 1'b1;
          yellow <= 1'b0;
          red <= 1'b0;
          state <= 4'b0001;
        end
        4'b0001: begin // Yellow light on for 2 clock cycles
          green <= 1'b0;
          yellow <= 1'b1;
          red <= 1'b0;
          state <= 4'b0010;
        end
        4'b0010: begin // Red light on for 8 clock cycles
          green <= 1'b0;
          yellow <= 1'b0;
          red <= 1'b1;
          state <= 4'b0011;
        end
        4'b0011: begin // Yellow light on for 2 clock cycles
          green <= 1'b0;
          yellow <= 1'b1;
          red <= 1'b0;
          state <= 4'b0000;
        end
      endcase
    end
  end

endmodule

