        count_reg1 <= 3'b000;
        count_reg2 <= 3'b000;
    end
    else begin
        count_reg1 <= count_reg2;
        count_reg2 <= count_reg2 + 1;
    end
end

assign count = count_reg1 ^ count_reg2;

endmodule

