module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    output [3:0] q,
    input in,
    output out,
    input [3:0] counter_out,
    output [3:0] sum_out
);

    // 4-bit binary counter with synchronous reset
    reg [3:0] counter;
    always @(posedge clk) begin
        if (reset) begin
            counter <= 4'b0000;
        end else begin
            counter <= counter + 1;
        end
    end

    // 2's complement module
    reg [3:0] twos_comp;
    always @(*) begin
        twos_comp = ~counter + 4'b0001;
    end

    // Multiplexer module
    reg [3:0] mux_out;
    always @(*) begin
        if (in) begin
            mux_out = twos_comp;
        end else begin
            mux_out = counter;
        end
    end

    // Output sum
    assign sum_out = mux_out + in;

    // Output signals
    assign q = counter;
    assign out = twos_comp;

endmodule

module mux4to1 (
  input [3:0] in,
  input [1:0] sel,
  output reg out
);

  always @(*) begin
    case ({sel})
      2'b00: out <= in[0];
      2'b01: out <= in[1];
      2'b10: out <= in[2];
      2'b11: out <= in[3];
    endcase
  end

endmodule

module DataProcessor (
    input clk,
    input reset,
    input [7:0] data_in,
    input enable,
    output [7:0] data_out,
    output reg [3:0] count
);

    always @(posedge clk) begin
        if (reset) begin
            count <= 0;
            data_out <= 0;
        end else if (enable) begin
            data_out <= data_in & 8'h0F;
            count <= count + 1;
        end
    end

endmodule

module mult(
            input wire                        clk,
            input wire                        reset_n,
            input wire                        cs,
            input wire                        we,
            input wire  [7 : 0]               addr,
            input wire  [(API_WIDTH - 1) : 0] write_data,
            output wire [(API_WIDTH - 1) : 0] read_data
           );


  //----------------------------------------------------------------
  // Internal constant and parameter definitions.
  //----------------------------------------------------------------
  parameter API_WIDTH       = 16;
  parameter OPA_WIDTH       = 256;
  parameter OPB_WIDTH       = 256;

  localparam OPA_WORDS      = OPA_WIDTH / API_WIDTH;
  localparam OPA_BASE_ADDR  = 8'h00;
  localparam OPA_TOP_ADDR   = (OPA_BASE_ADDR + OPA_WORDS - 1);

  localparam OPB_WORDS      = OPB_WIDTH / API_WIDTH;
  localparam OPB_BASE_ADDR  = 8'h40;
  localparam OPB_TOP_ADDR   = (OPB_BASE_ADDR + OPB_WORDS - 1);

  localparam PROD_WIDTH     = (OPA_WIDTH + OPB_WIDTH);
  localparam PROD_WORDS     = PROD_WIDTH / API_WIDTH;
  localparam PROD_BASE_ADDR = 8'h80;
  localparam PROD_TOP_ADDR  = (PROD_BASE_ADDR + PROD_WORDS - 1);


  //----------------------------------------------------------------
  // Registers including update variables and write enable.
  //----------------------------------------------------------------
  reg [(OPA_WIDTH - 1) : 0] opa_reg;
  reg [(OPA_WIDTH - 1) : 0] opa_new;
  reg                       opa_we;

  reg [(OPB_WIDTH - 1) : 0] opb_reg;
  reg [(OPB_WIDTH - 1) : 0] opb_new;
  reg                       opb_we;

  reg [(PROD_WIDTH - 1) : 0] prod_reg;
  reg [(PROD_WIDTH - 1) : 0] prod_new;


  //----------------------------------------------------------------
  // Wires.
  //----------------------------------------------------------------
  reg [(API_WIDTH -1) : 0] tmp_read_data;


  //----------------------------------------------------------------
  // Concurrent connectivity for ports etc.
  //----------------------------------------------------------------
  assign read_data = tmp_read_data;


  //----------------------------------------------------------------
  // reg_update
  // Update functionality for all registers in the core.
  // All registers are positive edge triggered with asynchronous
  // active low reset.
  //----------------------------------------------------------------
  always @ (posedge clk or negedge reset_n)
    begin : reg_update
      if (!reset_n)
        begin
          opa_reg  <= {(OPA_WIDTH){1'h0}};
          opb_reg  <= {(OPB_WIDTH){1'h0}};
          prod_reg <= {(PROD_WIDTH){1'h0}};
        end
      else
        begin
          prod_reg <= prod_new;

          if (opa_we)
            opa_reg <= opa_new;

          if (opb_we)
            opb_reg <= opb_new;
        end
    end // reg_update


  //----------------------------------------------------------------
  // mult_logic
  //
  // This is where the action is.
  //----------------------------------------------------------------
  always @*
    begin : mult_logic
      prod_new = opa_reg * opb_reg;
    end


  //----------------------------------------------------------------
  // api
  //
  // The interface command decoding logic.
  //----------------------------------------------------------------
  always @*
    begin : api
      tmp_read_data = {(API_WIDTH){1'h0}};
      opa_new       = opa_reg;
      opa_we        = 0;
      opb_new       = opb_reg;
      opb_we        = 0;

      if (cs)
        begin
          if (we)
            begin
              if ((addr >= OPA_BASE_ADDR) && (addr <= OPA_TOP_ADDR))
                begin
                  opa_new[API_WIDTH * (addr - OPA_BASE_ADDR) +: API_WIDTH] = write_data;
                  opa_we = 1;
                end

              if ((addr >= OPB_BASE_ADDR) && (addr <= OPB_TOP_ADDR))
                begin
                  opb_new[API_WIDTH * (addr - OPB_BASE_ADDR) +: API_WIDTH] = write_data;
                  opb_we = 1;
                end
            end

          else
            begin
              if ((addr >= PROD_BASE_ADDR) && (addr <= PROD_TOP_ADDR))
                tmp_read_data = prod_reg[API_WIDTH * (addr - PROD_BASE_ADDR) +: API_WIDTH];
            end
        end
    end // addr_decoder
endmodule

module top_module (
    input clk,
    input reset,     // Synchronous active-high reset
    input [31:0] in, // Input for the change detector
    output [31:0] out, // Output of the change detector
    output [15:0] q, // Output of the BCD counter
    output [3:1] ena, // Enable signals for the upper three digits
    output [31:0] xor_out // Output of the bitwise XOR operation
);

    // Instantiate the change detector module
    change_detector detector (
        .clk(clk),
        .reset(reset),
        .in(in),
        .out(out)
    );

    // Instantiate the BCD counter module
    bcd_counter counter (
        .clk(clk),
        .reset(reset),
        .q(q),
        .ena(ena)
    );

    // Define the XOR module
    wire [31:0] xor_input;
    assign xor_input = {out, q};
    xor_gate xor (
        .a(xor_input),
        .b(xor_input >> 1),
        .out(xor_out)
    );

endmodule

// Define the change detector module
module change_detector (
    input clk,
    input reset,     // Synchronous active-high reset
    input [31:0] in, // Input signal to detect changes on
    output reg [31:0] out // Output signal indicating a change
);
    reg [31:0] prev_in;

    always @(posedge clk) begin
        if (reset) begin
            out <= 0;
            prev_in <= 0;
        end else begin
            if (in == 0 && prev_in == 1) begin
                out <= 1;
            end else begin
                out <= 0;
            end
            prev_in <= in;
        end
    end
endmodule

// Define the BCD counter module
module bcd_counter (
    input clk,
    input reset,     // Synchronous active-high reset
    output reg [15:0] q, // Output BCD value
    output reg [3:1] ena // Enable signals for upper three digits
);
    reg [3:0] count;

    always @(posedge clk) begin
        if (reset) begin
            q <= 0;
            count <= 0;
            ena <= 3'b0;
        end else begin
            count <= count + 1;
            if (count == 10) begin
                count <= 0;
                q <= q + 1;
            end
            if (q[15:12] == 4'b1000) begin
                ena <= 3'b111;
            end else if (q[15:12] == 4'b0000) begin
                ena <= 3'b000;
            end else begin
                ena <= {ena[1:0], 1'b1};
            end
        end
    end
endmodule

// Define the XOR gate module
module xor_gate (
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] out
);
    always @* begin
        out = a ^ b;
    end
endmodule

module TFF(
