            out_Q <= 1'b0;
            out_QBar <= 1'b1;
        end else begin
            if (in_T) begin
                out_Q <= ~out_Q;
                out_QBar <= ~out_QBar;
            end
        end
    end

endmodule

module test_TFF;

    // Inputs
    reg in_T;
    reg clk;
