module ECC_memory_block (
  input [n-1:0] data_in,
  output [n+k-1:0] data_out
);

parameter n = 8; // number of data signals
parameter k = 2; // number of check bits

reg [n+k-1:0] memory [0:2**n-1]; // Memory array definition

function [k-1:0] parity;
  input [n-1:0] data;
  reg [k-1:0] parity_bits;
  integer i;
  begin
    for (i = 0; i < k; i = i + 1) begin
      parity_bits[i] = ^data[(2**i)-1:0];
    end
    parity = parity_bits;
  end
endfunction

// ECC memory block implementation
reg [n-1:0] data_stored;
reg [k-1:0] check_bits_stored;
wire [k-1:0] check_bits_computed;
wire error_flag;

