                    out <= 4'b0000;
                end else if (out == 4'b0000) begin
                    out <= 4'b1111;
                end else begin
                    if (out < in) begin
                        out <= out + 1;
                    end else if (out > in) begin
                        out <= out - 1;
                    end
                end
            end
        end
    end

