   reg cout_reg;

   always @(*) begin
      sum_reg = A + B + cin;
      if(sum_reg > 3'b1001) begin
         sum_reg = sum_reg + 4'b0110;
         cout_reg = 1'b1;
      end
      else begin
         cout_reg = 1'b0;
      end
   end

   assign sum = sum_reg;
   assign cout = cout_reg;

endmodule

module scfifo (
    aclr,
    clock,
    data,
    rdreq,
    wrreq,
    empty,
    q,
    almost_empty,
    almost_full,
    full,
    sclr,
    usedw
);

    input aclr;
    input clock;
    input [64:0] data;
    input rdreq;
    input wrreq;
    output empty;
    output [64:0] q;
    output almost_empty;
    output almost_full;
    output full;
    output sclr;
    output [7:0] usedw;

    reg [64:0] fifo_mem [0:255];
    reg [7:0] wr_ptr;
    reg [7:0] rd_ptr;
    wire [7:0] count = wr_ptr - rd_ptr;
    wire [7:0] used = count;
    wire [7:0] unused = 256 - count;
    wire [7:0] almost_full_level = 248;
    wire [7:0] almost_empty_level = 8;
    wire [7:0] usedw = wr_ptr - rd_ptr;

    assign empty = (count == 0);
    assign full = (count == 256);
    assign almost_empty = (count <= almost_empty_level);
    assign almost_full = (unused <= almost_full_level);

    assign sclr = 0;

    always @(posedge clock or negedge aclr) begin
        if (~aclr) begin
            wr_ptr <= 0;
            rd_ptr <= 0;
        end else begin
            if (wrreq && ~full) begin
                fifo_mem[wr_ptr] <= data;
                wr_ptr <= wr_ptr + 1;
            end
            if (rdreq && ~empty) begin
                q <= fifo_mem[rd_ptr];
                rd_ptr <= rd_ptr + 1;
            end
        end
    end

endmodule

