module mult_4bit_unsigned_array (
    input [3:0] M,
    input [3:0] N,
    output reg [7:0] P
);

reg [7:0] partial_products [0:3];

integer i, j;

always @(*) begin
    for (i = 0; i < 4; i = i + 1) begin
        for (j = 0; j < 4; j = j + 1) begin
            partial_products[i+j] = partial_products[i+j] + (M[i] * N[j]);
        end
    end
    P = {partial_products[7], partial_products[6], partial_products[5], partial_products[4], partial_products[3], partial_products[2], partial_products[1], partial_products[0]};
end

endmodule

