module TicTacToe_FSM(
    input clk, reset,
    input p1_move, p2_move,
    input p1_win, p1_loss, p1_tie,
    input p2_win, p2_loss, p2_tie,
    output reg turno_p1, turno_p2,
    output reg verifica_status,
    output reg win_game, loss_game, tie_game,
    output reg [2:0] state
);

    // Define FSM states
    parameter P1_Move = 3'b000;
    parameter P1_Status = 3'b001;
    parameter P2_Move = 3'b010;
    parameter P2_Status = 3'b011;
    parameter Win = 3'b100;
    parameter Tie = 3'b101;
    parameter Loss = 3'b110;

    // Define initial state
    reg [2:0] current_state = P1_Move;

    // Define next state
    reg [2:0] next_state = P1_Move;

    // Initialize turno_p1 and turno_p2
    initial begin
        turno_p1 = 1'b1;
        turno_p2 = 1'b0;
    end

    // Synchronous state update
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= P1_Move;
        end else begin
            current_state <= next_state;
        end
    end

    // Asynchronous state update
    always @(*) begin
        case (current_state)
            P1_Move: begin
                verifica_status <= 1'b0;
                if (p1_move) begin
                    next_state = P1_Status;
                    turno_p1 <= 1'b0;
                    turno_p2 <= 1'b1;
                end else begin
                    next_state = P1_Move;
                    turno_p1 <= 1'b1;
                    turno_p2 <= 1'b0;
                end
            end

            P1_Status: begin
                verifica_status <= 1'b1;
                if (p1_win) begin
                    next_state = Win;
                end else if (p1_loss) begin
                    next_state = Loss;
                end else if (p1_tie) begin
                    next_state = Tie;
                end else if (p2_move) begin
                    next_state = P2_Move;
                    turno_p1 <= 1'b0;
                    turno_p2 <= 1'b1;
                end else begin
                    next_state = P1_Status;
                    turno_p1 <= 1'b0;
                    turno_p2 <= 1'b1;
                end
            end

            P2_Move: begin
                verifica_status <= 1'b0;
                if (p2_move) begin
                    next_state = P2_Status;
                    turno_p1 <= 1'b1;
                    turno_p2 <= 1'b0;
                end else begin
                    next_state = P2_Move;
                    turno_p1 <= 1'b0;
                    turno_p2 <= 1'b1;
                end
            end

            P2_Status: begin
                verifica_status <= 1'b1;
                if (p2_win) begin
                    next_state = Win;
                end else if (p2_loss) begin
                    next_state = Loss;
                end else if (p2_tie) begin
                    next_state = Tie;
                end else if (p1_move) begin
                    next_state = P1_Move;
                    turno_p1 <= 1'b1;
                    turno_p2 <= 1'b0;
                end else begin
                    next_state = P2_Status;
                    turno_p1 <= 1'b1;
                    turno_p2 <= 1'b0;
                end
            end

            Win: begin
                win_game <= 1'b1;
                next_state = Win;
            end

            Loss: begin
                loss_game <= 1'b1;
                next_state = Loss;
            end

            Tie: begin
                tie_game <= 1'b1;
                next_state = Tie;
            end

            default: begin
                next_state = P1_Move;
            end
        endcase
    end

endmodule

module ripple_carry_adder (
	input [3:0] A,
	input [3:0] B,
	input Cin,
	output [3:0] Sum,
	output Cout
);

	wire [3:0] carry;

	// first full adder
	full_adder FA0(
		.A(A[0]),
		.B(B[0]),
		.Cin(Cin),
		.Sum(Sum[0]),
		.Cout(carry[0])
	);

	// second full adder
	full_adder FA1(
		.A(A[1]),
		.B(B[1]),
		.Cin(carry[0]),
		.Sum(Sum[1]),
		.Cout(carry[1])
	);

	// third full adder
	full_adder FA2(
		.A(A[2]),
		.B(B[2]),
		.Cin(carry[1]),
		.Sum(Sum[2]),
		.Cout(carry[2])
	);

	// fourth full adder
	full_adder FA3(
		.A(A[3]),
		.B(B[3]),
		.Cin(carry[2]),
		.Sum(Sum[3]),
		.Cout(Cout)
	);

endmodule

module full_adder (
	input A,
	input B,
	input Cin,
	output Sum,
	output Cout
);

	assign Sum = A ^ B ^ Cin;
	assign Cout = (A & B) | (A & Cin) | (B & Cin);

endmodule

module mux4(in0, in1, in2, in3, sel, out);
input in0, in1, in2, in3, sel;
output out;
wire not_sel, a, b, c, d, e, f, g, h, i, j, k, l, m, n, o, p;

not u1(not_sel, sel);
and u2(a, in0, not_sel);
and u3(b, in1, not_sel);
and u4(c, in2, sel);
and u5(d, in3, sel);
or u6(e, a, b);
or u7(f, c, d);
and u8(g, in0, sel);
and u9(h, in1, sel);
and u10(i, in2, not_sel);
and u11(j, in3, not_sel);
or u12(k, g, h);
or u13(l, i, j);
or u14(m, e, f);
and u15(n, in0, in1);
and u16(o, in2, in3);
or u17(p, n, o);
or u18(out, k, l, m, p);
endmodule

