module adder_4bit(
    input [3:0] in1,
    input [3:0] in2,
    input cin,
    output [3:0] out,
    output cout
);

    wire [3:0] sum;
    wire c1, c2, c3;

    // Full-adder for bit 0
    full_adder fa0(.a(in1[0]), .b(in2[0]), .cin(cin), .sum(sum[0]), .cout(c1));

    // Full-adder for bit 1
    full_adder fa1(.a(in1[1]), .b(in2[1]), .cin(c1), .sum(sum[1]), .cout(c2));

    // Full-adder for bit 2
    full_adder fa2(.a(in1[2]), .b(in2[2]), .cin(c2), .sum(sum[2]), .cout(c3));

    // Full-adder for bit 3
    full_adder fa3(.a(in1[3]), .b(in2[3]), .cin(c3), .sum(sum[3]), .cout(cout));

    assign out = sum;

endmodule

module full_adder(
    input a,
    input b,
    input cin,
    output sum,
    output cout
);

    wire s1, s2, s3;

    // XOR gates for sum
    xor x1(.a(a), .b(b), .y(s1));
    xor x2(.a(s1), .b(cin), .y(sum));

    // AND gates for carry-out
    and a1(.a(a), .b(b), .y(s2));
    and a2(.a(s1), .b(cin), .y(s3));
    or o1(.a(s2), .b(s3), .y(cout));

endmodule

module scanline (nextpixel, we, datain, pixeldata, globalreset, clk);

    input nextpixel; 
    input we; 
    input[62:0] datain; 
    output[20:0] pixeldata; 
    reg[20:0] pixeldata;
    input globalreset; 
    input clk; 

    reg[6:0] addr; 
    reg[6:0] waddr; 

    reg[6:0] raddr; 
    reg[1:0] subitem; 
    reg wedelayed; 
    reg[62:0]mem1; 
    reg[62:0]mem2; 
    wire[62:0] mdataout; 

    assign mdataout = mem2 ;

    always @(posedge clk or posedge globalreset)
    begin
       if (globalreset == 1'b1)
       begin
          subitem <= 2'b00 ; 
          waddr <= 1;
          raddr <= 1;
          wedelayed <= 1'b0 ; 
          pixeldata <= 21'b1;
       end
       else
       begin
          wedelayed <= we ; 
          if (nextpixel == 1'b1 | wedelayed == 1'b1)
          begin

             case (subitem)
                2'b00 :
                         begin
                            pixeldata <= {mem2[62:42], pixeldata[20:0]} ; 
                         end
                2'b01 :
                         begin
                            pixeldata <= {mem2[41:21], pixeldata[20:0]} ; 
                         end
                2'b10 :
                         begin
                            pixeldata <= {mem2[20:0], pixeldata[20:0]} ; 

                         end
                default :
                         begin
                            pixeldata <= 21'b1;
                         end
             endcase 
          end 
          if (nextpixel == 1'b1)
          begin
             case (subitem)
                2'b00 :
                         begin

                            subitem <= 2'b01 ; 
                         end
                2'b01 :
                         begin
                            subitem <= 2'b10 ; 
                         end
                2'b10 :
                         begin
                            subitem <= 2'b00 ; 
                            if (raddr != 7'b1101010)
                            begin
                               raddr <= raddr + 1 ; 
                            end
                            else
                            begin
                               raddr <= 7'b0000001;
                            end 
                         end
             endcase 
          end 
          if (we == 1'b1)
          begin
             if (waddr != 7'b1101010)
             begin
                waddr <= waddr + 1 ; 
             end
             else
             begin

                waddr <= 7'b0000001;
             end 
          end 
       end 
     end 

	always @(posedge clk)
	begin
       addr <= raddr ; 
       if (we == 1'b1)
       begin
          mem1 <= datain ; 
          mem2 <= mem1 ; 
       end  
	end
 endmodule

module ram_16bit_4096words
   #(parameter WIDTH = 16)
   (dout,
    clk,
    en,
    addr,
    din,
    we);

  parameter WORDS_PER_BLOCK = 1365;
  parameter BLOCKS = 3;
  parameter BLOCK_ADDR_WIDTH = $clog2(WORDS_PER_BLOCK);

  output reg [WIDTH-1:0] dout;
  input clk;
  input en;
  input [BLOCK_ADDR_WIDTH+1:0] addr;
  input [WIDTH-1:0] din;
  input we;

  wire [BLOCK_ADDR_WIDTH-1:0] block_addr;
  assign block_addr = addr[BLOCK_ADDR_WIDTH+1:1];

  wire [BLOCKS-1:0] block_select;
  assign block_select = addr[BLOCK_ADDR_WIDTH+2:BLOCK_ADDR_WIDTH+1];

  wire [WIDTH-1:0] douta, doutb, doutc;
  wire [BLOCK_ADDR_WIDTH-1:0] addra, addrb, addrc;
  wire [WIDTH-1:0] dina, dinb, dinc;
  wire [0:0] wea, web, wec;
  wire ena, enb, enc;
  wire clka, clkb, clkc;

  bram_4096_blk_mem_gen_prim_width ram_inst0
       (.douta(douta),
        .clka(clka),
        .ena(ena),
        .addra(addra),
        .dina(dina),
        .wea(wea));

  bram_4096_blk_mem_gen_prim_width ram_inst1
       (.douta(doutb),
        .clka(clkb),
        .ena(enb),
        .addra(addr[BIT_WIDTH-1:BLOCK_ADDR_WIDTH+1]),
        .dina(dinb),
        .wea(web));

  bram_4096_blk_mem_gen_prim_width ram_inst2
       (.douta(doutc),
        .clka(clkc),
        .ena(enc),
        .addra(addr[BIT_WIDTH-1:BLOCK_ADDR_WIDTH+1]),
        .dina(dinc),
        .wea(wec));

  always @(posedge clk) begin
    if (en) begin
      case (block_select)
        2'b00: begin
          clka <= 1;
          addra <= addr[BLOCK_ADDR_WIDTH-1:0];
          dina <= din;
          wea <= we;
          ena <= 1;
          dout <= douta;
        end
        2'b01: begin
          clkb <= 1;
          addrb <= addr[BLOCK_ADDR_WIDTH-1:0];
          dinb <= din;
          web <= we;
          enb <= 1;
          dout <= doutb;
        end
        2'b10: begin
          clkc <= 1;
          addrc <= addr[BLOCK_ADDR_WIDTH-1:0];
          dinc <= din;
          wec <= we;
          enc <= 1;
          dout <= doutc;
        end
        default: begin
          dout <= 0;
        end
      endcase
    end else begin
      clka <= 0;
      clkb <= 0;
      clkc <= 0;
      ena <= 0;
      enb <= 0;
      enc <= 0;
      dout <= 0;
    end
  end

endmodule

module GrayCodeConverter (
  input [n-1:0] in,
  output [n-1:0] out
);

parameter n = 4; // number of bits in the input signal

// Binary to Gray conversion algorithm
assign out[0] = in[0];
generate
  genvar i;
  for (i = 1; i < n; i = i + 1) begin
    assign out[i] = in[i] ^ in[i-1];
  end
endgenerate

// Gray to Binary conversion algorithm
assign out[0] = in[0];
generate
  genvar i;
  for (i = 1; i < n; i = i + 1) begin
    assign out[i] = out[i-1] ^ in[i];
  end
endgenerate

endmodule

module top_module (
