    input RST,
    input LD,
    input [3:0] D,
    output [3:0] Q
);

reg [3:0] Q_reg;

always @(posedge CLK or posedge RST) begin
    if (RST) begin
        Q_reg <= 4'b0;
    end else begin
        if (LD) begin
            Q_reg <= D;
        end else begin
            Q_reg <= {Q_reg[2:0], Q_reg[3]};
        end
    end
end

assign Q = Q_reg;

endmodule

module peripheral_audio(clk, rst, d_in, cs, wr, rd, addr, d_out, mclk, ledres, micLRsel, micData);

  input clk;
  input rst;
  input [15:0] d_in;
  input cs;
  input wr;
  input rd;
  input [3:0] addr;
  output reg [15:0] d_out;
  output ledres;
  output mclk;
  output micLRsel;
  input micData;

  wire full;
  wire empty;
  wire dout;
  reg enable;
  reg [2:0] s;

  microfono mic(.reset(rst), .clk(clk), .micLRSel(micLRsel), .empty(empty), .mclk(mclk), .micData(micData), .ledres(ledres), .enable(enable), .full(full));

  always @(*) begin
    case (addr)
      4'h0: s = (cs && wr) ? 3'b001 : 3'b000; // enable
      4'h2: s = (cs && rd) ? 3'b010 : 3'b000; // full
      4'h4: s = (cs && rd) ? 3'b100 : 3'b000; // empty
      4'h8: s = (cs && rd) ? 3'b111 : 3'b000; // dout
      default: s = 3'b000;
    endcase
  end

  always @(negedge clk) begin
    if (s[0] == 1) begin
      enable = 1;
    end else begin
      enable = 0;
    end
  end

  always @(negedge clk) begin
    case (s)
      3'b010: d_out[0] = full;
      3'b100: d_out[0] = empty;
      3'b111: d_out[0] = dout;
      default: d_out = 0;
    endcase
  end

endmodule

module microfono(reset, clk, micLRSel, empty, mclk, micData, ledres, enable, full);

  input reset;
  input clk;
  output micLRSel;
  output empty;
  output mclk;
  input micData;
  output ledres;
  input enable;
  output full;

  reg [15:0] buffer [0:1023];
  reg [9:0] write_ptr;
  reg [9:0] read_ptr;
  reg [9:0] count;
  reg [15:0] data_out;
  reg [1:0] mic_sel;
  reg [1:0] mic_sel_next;
  reg [1:0] mic_sel_prev;
  reg full_reg;
  reg empty_reg;
  reg [15:0] shift_reg;
  reg [3:0] shift_count;

  assign micLRSel = mic_sel;
  assign empty = empty_reg;
  assign mclk = (mic_sel == 2'b01) ? 1 : 0;
  assign full = full_reg;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      write_ptr <= 0;
      read_ptr <= 0;
      count <= 0;
      mic_sel <= 2'b01;
      mic_sel_next <= 2'b01;
      mic_sel_prev <= 2'b01;
      full_reg <= 0;
      empty_reg <= 1;
      shift_reg <= 0;
      shift_count <= 0;
    end else begin
      if (enable) begin
        if (count < 1024) begin
          buffer[write_ptr] <= micData;
          write_ptr <= write_ptr + 1;
          count <= count + 1;
          empty_reg <= 0;
        end else begin
          full_reg <= 1;
        end
      end else begin
        full_reg <= 0;
      end

      if (shift_count == 0) begin
        shift_reg <= buffer[read_ptr];
        read_ptr <= read_ptr + 1;
        count <= count - 1;
        full_reg <= 0;
        if (count == 1) begin
          empty_reg <= 1;
        end
      end else begin
        shift_reg <= {shift_reg[14:0], micData};
      end

      shift_count <= shift_count + 1;
      if (shift_count == 15) begin
        shift_count <= 0;
        data_out <= shift_reg;
      end

      mic_sel_prev <= mic_sel;
      mic_sel <= mic_sel_next;
      if (mic_sel == 2'b01) begin
        mic_sel_next <= mic_sel_prev;
      end else begin
        mic_sel_next <= 2'b01;
      end
    end
  end

  assign ledres = (count > 512) ? 1 : 0;

endmodule

module uart_rx #
(
    parameter DATA_WIDTH = 8
)
(
    input  wire                   clk,
    input  wire                   rst,

    /*
     * AXI output
     */
    output wire [DATA_WIDTH-1:0]  output_axis_tdata,
    output wire                   output_axis_tvalid,
    input  wire                   output_axis_tready,

    /*
     * UART interface
     */
    input  wire                   rxd,

    /*
     * Status
     */
    output wire                   busy,
    output wire                   overrun_error,
    output wire                   frame_error,

    /*
     * Configuration
     */
    input  wire [15:0]            prescale

);

reg [DATA_WIDTH-1:0] output_axis_tdata_reg = 0;
reg output_axis_tvalid_reg = 0;

reg rxd_reg = 1;

reg busy_reg = 0;
reg overrun_error_reg = 0;
reg frame_error_reg = 0;

reg [DATA_WIDTH-1:0] data_reg = 0;
reg [18:0] prescale_reg = 0;
reg [3:0] bit_cnt = 0;

assign output_axis_tdata = output_axis_tdata_reg;
assign output_axis_tvalid = output_axis_tvalid_reg;

assign busy = busy_reg;
assign overrun_error = overrun_error_reg;
assign frame_error = frame_error_reg;

always @(posedge clk) begin
    if (rst) begin
        output_axis_tdata_reg <= 0;
        output_axis_tvalid_reg <= 0;
        rxd_reg <= 1;
        prescale_reg <= 0;
        bit_cnt <= 0;
        busy_reg <= 0;
        overrun_error_reg <= 0;
        frame_error_reg <= 0;
    end else begin
        rxd_reg <= rxd;
        overrun_error_reg <= 0;
        frame_error_reg <= 0;

        if (output_axis_tvalid & output_axis_tready) begin
            output_axis_tvalid_reg <= 0;
        end

        if (prescale_reg > 0) begin
            prescale_reg <= prescale_reg - 1;
        end else if (bit_cnt > 0) begin
            if (bit_cnt > DATA_WIDTH+1) begin
                if (~rxd_reg) begin
                    bit_cnt <= bit_cnt - 1;
                    prescale_reg <= (prescale << 3)-1;
                end else begin
                    bit_cnt <= 0;
                    prescale_reg <= 0;
                end
            end else if (bit_cnt > 1) begin
                bit_cnt <= bit_cnt - 1;
                prescale_reg <= (prescale << 3)-1;
                data_reg <= {rxd_reg, data_reg[DATA_WIDTH-1:1]};
            end else if (bit_cnt == 1) begin
                bit_cnt <= bit_cnt - 1;
                if (rxd_reg) begin
                    output_axis_tdata_reg <= data_reg;
                    output_axis_tvalid_reg <= 1;
                    overrun_error_reg <= output_axis_tvalid_reg;
                end else begin
                    frame_error_reg <= 1;
                end
            end
        end else begin
            busy_reg <= 0;
            if (~rxd_reg) begin
                prescale_reg <= (prescale << 2)-2;
                bit_cnt <= DATA_WIDTH+2;
                data_reg <= 0;
                busy_reg <= 1;
            end
        end
    end
end

endmodule

