module uart_mmio(clk, rst_, TxD, data, addr, cs_, oe_, we_);
	input clk;
	input rst_;
	output TxD;
	inout [7:0] data;
	input [7:0] addr;
	input cs_;
	input oe_;
	input we_;

	parameter Counter = 2604;
	localparam REGS = 8;

	reg [7:0] r[0:REGS - 1];
	reg TxD_start = 0;
	wire TxD_busy;

	integer i;

	assign data = (~cs_ & ~oe_) ? r[addr] : 8'bzzzzzzzz;

	uart #(Counter) u(.clk(clk), .TxD(TxD), .TxD_busy(TxD_busy), .TxD_data(r[4]), .TxD_start(TxD_start));

	always @(posedge clk)
		r[0] = { 7'b0, TxD_busy };

	`ifndef USE_RST_LOGIC
	initial
		for(i = 0; i < REGS; i=i+1) r[i] = 8'd0;
	`endif

	always @(posedge clk or negedge rst_)
	`ifdef USE_RST_LOGIC
		if(~rst_)
			{ r[1], r[2], r[3], r[4], r[5], r[6], r[7], TxD_start } <= { 8'b0, 8'b0, 8'b0, 8'b0, 8'b0, 8'b0, 8'b0, 1'b0 };
		else
	`endif
		if(~cs_ & ~we_)
			case(addr)
				8'd4:
					if(~TxD_busy)
						{ r[4], TxD_start } <= { data, 1'b1 };
					else
						TxD_start <= 1'b0;

				default:
					TxD_start <= 1'b0;
			endcase
		else
			TxD_start <= 1'b0;

endmodule

module flip_flop (
    input clk,
    input reset,           // Asynchronous active-high reset
    input d,               // Single-bit input
    output reg q           // Single-bit output
);

always @(posedge clk or posedge reset) begin
    if (reset) begin
        q <= 0;
    end else begin
        q <= d;
    end
end

endmodule

module transition_detector (
    input clk,
    input reset,           // Synchronous active-high reset
    input [31:0] in,       // 32-bit input vector
    output reg [31:0] out  // 32-bit output vector
);

reg [31:0] prev_in;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        out <= 0;
        prev_in <= 0;
    end else begin
        out <= (in & ~prev_in);
        prev_in <= in;
    end
end

endmodule

module functional_module (
