);

functional_module fm (
    .flip_flop_out(flip_flop_out),
    .transition_detector_out(transition_detector_out),
    .final_out(q)
);

always @(negedge clk) begin
    if (reset) begin
        flip_flop_out <= 0;
    end else begin
        flip_flop_out <= {flip_flop_out[6:0], flip_flop_out[7]};
    end
end

endmodule

