// Implementation of the shift register module
module shift_register (
    input clk,
    input load,
    input [3:0] in,
    output reg [3:0] out,
    output reg [3:0] out_next
);

    always @(posedge clk) begin
        if (load) begin
            out <= in;
        end else begin
            out <= out_next;
        end
    end

    always @(*) begin
        out_next = {out[2:0], in[3]};
    end

endmodule

// Implementation of the gray code converter module
module gray_code (
    input [3:0] A,
    output reg [3:0] Q
);

    always @(*) begin
        Q[0] = A[0];
        Q[1] = A[0] ^ A[1];
        Q[2] = A[1] ^ A[2];
        Q[3] = A[2] ^ A[3];
    end

endmodule

// Implementation of the AND gate module
module and_gate (
    input [3:0] A,
    input [3:0] B,
    output reg [3:0] Y
);

    always @(*) begin
        Y = A & B;
    end

endmodule

