    decoder_2to4 decoder(
        .in(in[3]),
        .enable(in[4]),
        .out(decoder_out)
    );

    // 5-input AND gate
    assign out_and = decoder_out[0] & decoder_out[1] & decoder_out[2] & decoder_out[3] & in[0];

    // 5-input OR gate
    assign out_or = decoder_out[0] | decoder_out[1] | decoder_out[2] | decoder_out[3] | in[0];

