module ultrasonic_peripheral(clk, rst, d_in, cs, addr, rd, wr, d_out, trigg, echo);

  input clk;
  input rst;
  input [15:0] d_in;
  input cs;
  input [3:0] addr;
  input rd;
  input wr;
  output reg [15:0] d_out;
  output trigg;
  input echo;

  // Internal registers and wires
  reg [5:0] s; // Selector for mux_4 and demux_4
  reg enable;
  wire [7:0] dout; // Distance
  wire done;

  // Instantiate ultrasonic sensor
  ultrasonido ultra(.clk(clk), .reset(rst), .d(dout), .trigg(trigg), .ECHO(echo), .ENABLE(enable), .DONE(done));

  // Address decoder
  always @(*) begin
    case(addr)
      4'h0: s = (cs && wr) ? 5'b00001 : 5'b00000; // Enable
      4'h2: s = (cs && rd) ? 5'b00010 : 5'b00000; // Done
      4'h4: s = (cs && rd) ? 5'b00100 : 5'b00000; // Data
      default: s = 5'b00000;
    endcase
  end

  // Register write
  always @(negedge clk) begin
    if(s[0] == 1) begin
      enable = d_in[0];
    end
  end

  // Mux_4: Multiplexes peripheral outputs
  always @(negedge clk) begin
    case(s)
      5'b00010: d_out[0] = done;
      5'b00100: d_out[7:0] = dout;
      default: d_out = 0;
    endcase
  end

endmodule

module spi_mock(
    input clk100mhz,
    input reset,
    input uart_rxd,
    output uart_txd,
    input [31:0] data_in,
    output reg data_in_rdy,
    output reg data_in_ack,
    input data_in_rq,
    output reg [31:0] data_out,
    output reg data_out_rdy,
    input data_out_ack
);

    // UART signals
    reg [7:0] uart_tx_axis_tdata;
    reg uart_tx_axis_tvalid;
    wire uart_tx_axis_tready;
    wire [7:0] uart_rx_axis_tdata;
    wire uart_rx_axis_tvalid;
    reg uart_rx_axis_tready;

    // internal signals
    reg [2:0] uart_state;
    reg [31:0] uart_send_bytes;
    reg [1:0] bytecount;
    reg [31:0] data_out_tmp;
    reg [31:0] data_in_tmp;

    // parameters
    parameter S_RECV = 0;
    parameter S_SND = 1;
    parameter S_RECV_TICK = 2;
    parameter S_SND_TICK = 3;

    // instantiate UART module
    uart uart_inst (
        .clk(clk100mhz),
        .rst(~reset),
        .input_axis_tdata(uart_tx_axis_tdata),
        .input_axis_tvalid(uart_tx_axis_tvalid),
        .input_axis_tready(uart_tx_axis_tready),
        .output_axis_tdata(uart_rx_axis_tdata),
        .output_axis_tvalid(uart_rx_axis_tvalid),
        .output_axis_tready(uart_rx_axis_tready),
        .rxd(uart_rxd),
        .txd(uart_txd),
        .tx_busy(),
        .rx_busy(),
        .rx_overrun_error(),
        .rx_frame_error(),
        .prescale(100000000/(115200*8))
    );

    always @(posedge clk100mhz) begin
        if (!reset) begin
            uart_tx_axis_tdata <= 0;
            uart_tx_axis_tvalid <= 0;
            uart_rx_axis_tready <= 1;
            data_out_rdy <= 0;
            data_out <= 0;
            bytecount <= 0;
            uart_state <= S_RECV;
            uart_send_bytes <= 0;
            data_in_ack <= 0;
            data_out_tmp <= 0;
            data_in_tmp <= 0;
        end else begin
            case(uart_state)
                S_RECV: begin // wait for an input from the Master
                    data_in_ack <= 0;
                    if (bytecount == 0) begin
                        data_in_tmp <= data_in;
                    end
                    if (uart_rx_axis_tvalid) begin // Master has something to say
                        if (bytecount == 3) begin
                            data_out_tmp <= 0;
                            data_out <= {uart_rx_axis_tdata, data_out_tmp[31:8]};
                            data_out_rdy <= 1;
                            uart_state <= S_SND;
                            bytecount <= 0;
                            uart_rx_axis_tready <= 0;
                            uart_send_bytes <= {8'hff,data_in_tmp[31:8]};
                            uart_tx_axis_tdata <= data_in_tmp[7:0];
                            uart_tx_axis_tvalid <= 1;
                        end else begin
                            data_out_tmp <= {uart_rx_axis_tdata, data_out_tmp[31:8]}; // Shift into data output register
                            bytecount <= bytecount + 1;
                            uart_state <= S_RECV_TICK;
                            uart_rx_axis_tready <= 0;
                        end
                    end
                end // case: S_RECV
                S_RECV_TICK: begin
                    uart_state <= S_RECV;
                    uart_rx_axis_tready <= 1;
                end
                S_SND: begin
                    data_out_rdy <= 0;
                    if (data_out_ack) data_out_rdy <= 0;
                    if (uart_tx_axis_tready) begin // just sent
                        bytecount <= bytecount + 1;
                        uart_tx_axis_tdata <= uart_send_bytes[7:0];
                        uart_send_bytes <= {8'hff,uart_send_bytes[31:8]};
                        if (bytecount == 3) begin // done sending, enough is enough
                            uart_tx_axis_tvalid <= 0;
                            uart_rx_axis_tready <= 1;
                            uart_state <= S_RECV;
                            data_in_ack <= 1;
                            bytecount <= 0;
                        end else begin
                            uart_tx_axis_tvalid <= 0;
                            uart_state <= S_SND_TICK;
                        end
                    end
                end // case: S_SND
                S_SND_TICK: begin
                    uart_tx_axis_tvalid <= 1;
                    uart_state <= S_SND;
                end
            endcase // case (uart_state)
        end // else: !if(!reset)
    end // always @ (posedge clk)

    // Ready to receive input data
    assign data_in_rdy = (uart_state == S_RECV) ? 1 : 0;

endmodule

