module top_module (
    input clk,
    input reset,
    input [3:0] a,
    input [3:0] b,
    output [4:0] sum
);

    wire [3:0] fa1_sum, fa2_sum;
    wire fa2_cout;
    wire [4:0] tc_out;

    full_adder fa1(.a(a[0]), .b(b[0]), .cin(1'b0), .sum(fa1_sum[0]), .cout());
    full_adder fa2(.a(a[1]), .b(b[1]), .cin(fa1_sum[0]), .sum(fa2_sum[0]), .cout(fa2_cout));
    full_adder fa3(.a(a[2]), .b(b[2]), .cin(fa2_sum[1]), .sum(fa2_sum[1]), .cout());
    full_adder fa4(.a(a[3]), .b(b[3]), .cin(fa2_sum[2]), .sum(fa2_sum[2]), .cout());

    assign sum = {fa2_cout, fa2_sum};

    twos_complement tc(.in(sum), .out(tc_out));

    always @(posedge clk) begin
        if (reset) begin
            fa1_sum <= 4'b0;
            fa2_sum <= 4'b0;
        end else begin
            fa1_sum <= {fa1.sum, 3'b0};
            fa2_sum <= {fa2.sum, 2'b0};
        end
    end

endmodule

