    output cout
);

    assign {cout, sum} = a + b + cin;

endmodule

module twos_complement (
    input [4:0] in,
    output [4:0] out
);

    assign out = ~in + 1;

endmodule

module timer_module
(
    input        reset,
    input        clk_sys,
    input  [1:0] addr,
    input  [7:0] din,
    output [7:0] dout,
    input        wr,
    input        rd,
    input  [2:0] clk_timer,
    input  [2:0] gate,
    output [2:0] out,
    output [2:0] sound_active
);

reg [7:0] timer0_reg;
reg [7:0] timer1_reg;
reg [7:0] timer2_reg;

reg [7:0] timer0_count;
reg [7:0] timer1_count;
reg [7:0] timer2_count;

always @(posedge clk_sys or posedge reset) begin
    if (reset) begin
        timer0_count <= 0;
        timer1_count <= 0;
        timer2_count <= 0;
    end else begin
        if (gate[0]) begin
            if (timer0_count == 255) begin
                timer0_count <= 0;
                out[0] <= 1;
            end else begin
                timer0_count <= timer0_count + 1;
                out[0] <= 0;
            end
        end else begin
            timer0_count <= 0;
            out[0] <= 0;
        end

        if (gate[1]) begin
            if (timer1_count == 255) begin
                timer1_count <= 0;
                out[1] <= 1;
            end else begin
                timer1_count <= timer1_count + 1;
                out[1] <= 0;
            end
        end else begin
            timer1_count <= 0;
            out[1] <= 0;
        end

        if (gate[2]) begin
            if (timer2_count == 255) begin
                timer2_count <= 0;
                out[2] <= 1;
            end else begin
                timer2_count <= timer2_count + 1;
                out[2] <= 0;
            end
        end else begin
            timer2_count <= 0;
            out[2] <= 0;
        end
    end
end

always @(posedge clk_sys or posedge reset) begin
    if (reset) begin
        timer0_reg <= 0;
        timer1_reg <= 0;
        timer2_reg <= 0;
    end else begin
        if (wr && (addr == 3)) begin
            case (din[7:6])
                2'b00: clk_timer[0] <= din[5:3];
                2'b01: clk_timer[1] <= din[5:3];
                2'b10: clk_timer[2] <= din[5:3];
            endcase
        end

        if (wr && (addr == 0)) begin
            timer0_reg <= din;
        end

        if (wr && (addr == 1)) begin
            timer1_reg <= din;
        end

        if (wr && (addr == 2)) begin
            timer2_reg <= din;
        end
    end
end

always @(addr or rd) begin
    case (addr)
        2'b00: dout <= timer0_reg;
        2'b01: dout <= timer1_reg;
        2'b10: dout <= timer2_reg;
        default: dout <= 0;
    endcase
end

always @(posedge clk_sys or posedge reset) begin
    if (reset) begin
        sound_active <= 0;
    end else begin
        if (gate[0] && (timer0_count != 0)) begin
            sound_active[0] <= 1;
        end else begin
            sound_active[0] <= 0;
        end

        if (gate[1] && (timer1_count != 0)) begin
            sound_active[1] <= 1;
        end else begin
            sound_active[1] <= 0;
        end

        if (gate[2] && (timer2_count != 0)) begin
            sound_active[2] <= 1;
        end else begin
            sound_active[2] <= 0;
        end
    end
end

endmodule

module clock_multiplexer (
  input [n-1:0] clk,
