endmodule

module top_module (
  input clk,
  input reset, // Synchronous active-high reset
  input [255:0] in, // 256-bit input for the multiplexer
  input [7:0] sel, // Select input for the multiplexer
  input [3:0] A, // 4-bit input A for the ripple carry adder
  input [3:0] B, // 4-bit input B for the ripple carry adder
  output [3:0] S, // 4-bit output from the ripple carry adder
  output Cout, // Carry-out output from the ripple carry adder
  output [3:0] out // 4-bit output from the functional module
);

  // 256-to-1 multiplexer
  wire [255:0] mux_out;
  assign mux_out = sel == 8'b00000000 ? in[0] :
                    sel == 8'b11111111 ? in[255] :
                    in[sel];

  // 4-bit ripple carry adder
  wire [3:0] adder_out;
  wire carry_out;
  ripple_carry_adder adder(.A(A), .B(B), .S(adder_out), .Cout(carry_out));

  // Functional module
  assign out = adder_out + mux_out;

endmodule

module ripple_carry_adder (
  input [3:0] A, // 4-bit input A
  input [3:0] B, // 4-bit input B
  output [3:0] S, // 4-bit output sum
  output Cout // Carry-out output
);

  wire [3:0] sum;
  wire [3:0] carry;
  assign sum = A + B;
  assign carry = {A[3], B[3], sum[3]} == 3'b011 || {A[3], B[3], sum[3]} == 3'b110 || {A[3], B[3], sum[3]} == 3'b111;
  assign S = sum;
  assign Cout = carry;

endmodule

module decoder_barrelshifter (
    input A,
    input B,
    input C,
    input [3:0] data_in,
    input dir,
    output [3:0] data_out
);

    // 3-to-8 decoder
    wire [7:0] decoder_out;
    assign decoder_out = ~(A&B&C) << 3 | ~(A&B&~C) << 2 | ~(A&~B&C) << 1 | ~(A&~B&~C) << 0 | ~(~A&B&C) << 4 | ~(~A&B&~C) << 5 | ~(~A&~B&C) << 6 | ~(~A&~B&~C) << 7;

    // Barrel shifter
    wire [3:0] shifted_data;
    assign shifted_data = dir ? data_in >> 1 : data_in << 1;
    assign data_out = (decoder_out & 8'hFF) == 0 ? data_in : shifted_data;

endmodule

module adder4(
  input [3:0] A,
