  assign sum = A + B + CIN;

  assign S = sum[3:0];

  assign COUT = sum[4];

endmodule

module adc_data_fifo (
    aclr,
    data,
    rdclk,
    rdreq,
    wrclk,
    wrreq,
    q,
    rdempty,
    wrfull
);

    parameter WIDTH = 12;
    parameter DEPTH = 16;

    input aclr;
    input [WIDTH-1:0] data;
    input rdclk;
    input rdreq;
    input wrclk;
    input wrreq;
    output [WIDTH-1:0] q;
    output rdempty;
    output wrfull;

    reg [WIDTH-1:0] mem [DEPTH-1:0];
    reg [WIDTH-1:0] q_reg;
    reg [4:0] wrptr;
    reg [4:0] rdptr;
    reg [4:0] count;
    wire [4:0] next_wrptr;
    wire [4:0] next_rdptr;
    wire [4:0] next_count;

    assign rdempty = (count == 0);
    assign wrfull = (count == DEPTH);

    always @(posedge wrclk or negedge aclr) begin
        if (!aclr) begin
            wrptr <= 0;
            count <= 0;
        end else if (wrreq && !wrfull) begin
            mem[wrptr] <= data;
            wrptr <= next_wrptr;
            count <= next_count;
        end
    end

    always @(posedge rdclk or negedge aclr) begin
        if (!aclr) begin
            rdptr <= 0;
        end else if (rdreq && !rdempty) begin
            q_reg <= mem[rdptr];
            rdptr <= next_rdptr;
            count <= next_count;
        end
    end

    assign q = q_reg;

    assign next_wrptr = (wrptr == DEPTH-1) ? 0 : wrptr + 1;
    assign next_rdptr = (rdptr == DEPTH-1) ? 0 : rdptr + 1;
    assign next_count = count + wrreq - rdreq;

endmodule

module BCD_Converter (
  input [3:0] bin,
  output [3:0] bcd
);

  wire [3:0] temp;

  assign temp[3] = bin[3] & bin[2] & bin[1] & bin[0];
  assign temp[2] = (~bin[3] & bin[2] & bin[1] & bin[0]) | (bin[3] & ~bin[2] & bin[1] & bin[0]) | (bin[3] & bin[2] & ~bin[1] & bin[0]) | (bin[3] & bin[2] & bin[1] & ~bin[0]);
  assign temp[1] = (~bin[3] & ~bin[2] & bin[1] & bin[0]) | (bin[3] & ~bin[2] & ~bin[1] & bin[0]) | (bin[3] & bin[2] & ~bin[1] & ~bin[0]) | (~bin[3] & bin[2] & bin[1] & ~bin[0]);
  assign temp[0] = (~bin[3] & ~bin[2] & ~bin[1] & bin[0]) | (bin[3] & ~bin[2] & ~bin[1] & ~bin[0]) | (bin[3] & bin[2] & ~bin[1] & ~bin[0]) | (bin[3] & ~bin[2] & bin[1] & ~bin[0]);

  assign bcd = temp;

endmodule

module calculator (
  input [3:0] A,
  input [3:0] B,
  input [1:0] opcode,
  input clk,
  output reg [3:0] result
);

  reg [4:0] intermediate_result;
  reg overflow;
  reg divide_by_zero;

  always @(posedge clk) begin
    case (opcode)
      2'b00: begin // addition
        intermediate_result = A + B;
        overflow = (intermediate_result > 15);
        result = (overflow) ? 4'b1111 : intermediate_result[3:0];
      end
      2'b01: begin // subtraction
        intermediate_result = A - B;
        overflow = (intermediate_result < 0);
        result = (overflow) ? 4'b1111 : intermediate_result[3:0];
      end
      2'b10: begin // multiplication
        intermediate_result = A * B;
        overflow = (intermediate_result > 15);
        result = (overflow) ? 4'b1111 : intermediate_result[3:0];
      end
      2'b11: begin // division
        if (B == 0) begin
          divide_by_zero = 1;
          result = 4'b1111;
        end else begin
          divide_by_zero = 0;
          result = A / B;
        end
      end
      default: result = 4'bxxxx; // invalid opcode
    endcase
  end

endmodule

