    if (in[0] && !prev_in[0]) begin
        count <= count + 1;
    end
    if (in[1] && !prev_in[1]) begin
        count <= count + 1;
    end
    if (in[2] && !prev_in[2]) begin
        count <= count + 1;
    end
    if (in[3] && !prev_in[3]) begin
        count <= count + 1;
    end
    prev_in <= in;
end

assign out = count;

endmodule

