    wire edge_out;
    edge_detector edge_inst(.clk(clk), .reset(reset), .in(in), .out(edge_out));

    wire [3:0] or_out;
    bitwise_or_logical_or or_inst(.in(in), .out(or_out));

    wire [3:0] and_out;
    functional_module func_inst(.in1(edge_out), .in2(or_out), .out(and_out), .select(select));

    assign match = ~(&and_out == pattern); // Invert the final output using a NOT gate

endmodule

