module keypad_decoder (
    input [3:0] row, // Input lines from keypad scanner module
    output reg [1:0] key_pressed, // Output from keypad scanner module
    output reg out0, // Outputs from 2-to-4 decoder module
    output reg out1,
    output reg out2,
    output reg out3
);

reg [1:0] col;

// Assign column values based on row input
always @(*) begin
    case(row)
        4'b0001: col = 2'b00;
        4'b0010: col = 2'b01;
        4'b0100: col = 2'b10;
        4'b1000: col = 2'b11;
        default: col = 2'b00;
    endcase
end

// Output key pressed value based on row and column input
always @(*) begin
    case({row, col})
        8'b00000001: key_pressed = 2'b00;
        8'b00000010: key_pressed = 2'b01;
        8'b00000100: key_pressed = 2'b10;
        8'b00001000: key_pressed = 2'b11;
        default: key_pressed = 2'b00;
    endcase
end

// Output decoder values based on key pressed value
always @(key_pressed) begin
    case(key_pressed)
        2'b00: begin
            out0 = 1'b1;
            out1 = 1'b0;
            out2 = 1'b0;
            out3 = 1'b0;
        end
        2'b01: begin
            out0 = 1'b0;
            out1 = 1'b1;
            out2 = 1'b0;
            out3 = 1'b0;
        end
        2'b10: begin
            out0 = 1'b0;
            out1 = 1'b0;
            out2 = 1'b1;
            out3 = 1'b0;
        end
        2'b11: begin
            out0 = 1'b0;
            out1 = 1'b0;
            out2 = 1'b0;
            out3 = 1'b1;
        end
        default: begin
            out0 = 1'b0;
            out1 = 1'b0;
            out2 = 1'b0;
            out3 = 1'b0;
        end
    endcase
end

