    input control,      // Control input to select sum or difference output
    output reg [3:0] result,// 4-bit output from the functional module
    output reg sum_diff     // 1-bit output indicating sum or difference output
);

    wire [2:0] johnson_count;
    wire [2:0] gray_code_count;
    wire [2:0] binary_count;

    johnson_counter johnson_inst (
        .clk(clk),
        .reset(reset),
        .count(johnson_count)
    );

    gray_code_counter gray_code_inst (
        .clk(clk),
        .reset(reset),
        .count(gray_code_count)
    );

    binary_counter binary_inst (
        .clk(clk),
        .reset(reset),
        .count(binary_count)
    );

    always @ (posedge clk) begin
        if (reset) begin
            result <= 0;
            sum_diff <= 0;
        end else begin
            if (control) begin
                result <= johnson_count + gray_code_count + binary_count;
                sum_diff <= 1;
            end else begin
                result <= johnson_count - gray_code_count - binary_count;
                sum_diff <= 0;
            end
        end
    end

endmodule

