module axi_to_stream_converter (
  input aclk,
  input areset,
  input m_axi_arvalid,
  input [31:0] m_axi_araddr,
  input [7:0] m_axi_arlen,
  input [1:0] m_axi_arburst,
  input [3:0] m_axi_arid,
  input m_axi_rready,
  input s_axis_tready,
  output m_axi_arready,
  output s_axis_tvalid,
  output [31:0] s_axis_tdata,
  output [3:0] s_axis_tid,
  output s_axis_tlast
);

  // Internal registers
  reg [31:0] araddr_reg;
  reg [7:0] arlen_reg;
  reg [1:0] arburst_reg;
  reg [3:0] arid_reg;
  reg [31:0] data_reg;
  reg [3:0] tid_reg;
  reg tvalid_reg;
  reg tlast_reg;
  reg [1:0] burst_count_reg;
  reg [1:0] beat_count_reg;

  // Internal wires
  wire [1:0] m_axi_arlen_minus_one;
  assign m_axi_arlen_minus_one = m_axi_arlen - 1;

  // AXI read address state machine
  localparam AW_IDLE = 2'b00;
  localparam AW_ADDR = 2'b01;
  localparam AW_BURST = 2'b10;
  reg [1:0] aw_state;
  always @(posedge aclk) begin
    if (areset) begin
      aw_state <= AW_IDLE;
      araddr_reg <= 0;
      arlen_reg <= 0;
      arburst_reg <= 0;
      arid_reg <= 0;
      m_axi_arready <= 0;
    end else begin
      case (aw_state)
        AW_IDLE: begin
          if (m_axi_arvalid) begin
            aw_state <= AW_ADDR;
            araddr_reg <= m_axi_araddr;
            arlen_reg <= m_axi_arlen_minus_one;
            arburst_reg <= m_axi_arburst;
            arid_reg <= m_axi_arid;
            m_axi_arready <= 1;
          end else begin
            m_axi_arready <= 0;
          end
        end
        AW_ADDR: begin
          aw_state <= AW_BURST;
        end
        AW_BURST: begin
          if (beat_count_reg < arlen_reg) begin
            if (m_axi_rready && s_axis_tready) begin
              beat_count_reg <= beat_count_reg + 1;
              tvalid_reg <= 1;
              tlast_reg <= (beat_count_reg == arlen_reg);
              tid_reg <= arid_reg;
              s_axis_tid <= tid_reg;
              case (arburst_reg)
                2'b00: begin // FIXED
                  s_axis_tdata <= araddr_reg + (beat_count_reg << 2);
                end
                2'b01: begin // INCR
                  s_axis_tdata <= araddr_reg + (beat_count_reg << 2);
                end
                2'b10: begin // WRAP
                  s_axis_tdata <= araddr_reg + ((beat_count_reg & ~arlen_reg) << 2);
                end
                2'b11: begin // RESERVED
                  s_axis_tdata <= 0;
                end
              endcase
              if (tvalid_reg && s_axis_tready) begin
                tvalid_reg <= 0;
                tlast_reg <= 0;
                s_axis_tvalid <= 1;
                s_axis_tlast <= tlast_reg;
                beat_count_reg <= beat_count_reg;
              end else begin
                s_axis_tvalid <= 0;
                s_axis_tlast <= 0;
                beat_count_reg <= beat_count_reg - 1;
              end
            end else begin
              s_axis_tvalid <= 0;
              s_axis_tlast <= 0;
              beat_count_reg <= beat_count_reg;
            end
          end else begin
            aw_state <= AW_IDLE;
            m_axi_arready <= 0;
            beat_count_reg <= 0;
          end
        end
      endcase
    end
  end

endmodule

module fifo(datain, rd, wr, rst, clk, full, empty, led_n, wei);

input [3:0] datain;
input rd, wr, rst, clk;

output [6:0] led_n;
output full, empty, wei;

reg [3:0] dataout;
reg full_in, empty_in, wei_in, div;
reg [3:0] mem [15:0];
reg [23:0] cnt;
reg [3:0] rp, wp;
reg [6:0] led_n;

assign full = full_in;
assign empty = empty_in;
assign wei = wei_in;

parameter
    reg0 = 7'b0000001,
    reg1 = 7'b1001111,
    reg2 = 7'b0010010,
    reg3 = 7'b0000110,
    reg4 = 7'b1001100,
    reg5 = 7'b0100100,
    reg6 = 7'b0100000,
    reg7 = 7'b0001101,
    reg8 = 7'b0000000,
    reg9 = 7'b0000100,
    rega = 7'b0001000,
    regb = 7'b1100000,
    regc = 7'b0110001,
    regd = 7'b1000010,
    rege = 7'b0110000,
    regf = 7'b0111000;

// memory read out
always @(posedge clk) begin
    if (~rd && ~empty_in) begin
        dataout <= mem[rp];
        case (dataout)
            4'h0: led_n <= reg0;
            4'h1: led_n <= reg1;
            4'h2: led_n <= reg2;
            4'h3: led_n <= reg3;
            4'h4: led_n <= reg4;
            4'h5: led_n <= reg5;
            4'h6: led_n <= reg6;
            4'h7: led_n <= reg7;
            4'h8: led_n <= reg8;
            4'h9: led_n <= reg9;
            4'ha: led_n <= rega;
            4'hb: led_n <= regb;
            4'hc: led_n <= regc;
            4'hd: led_n <= regd;
            4'he: led_n <= rege;
            4'hf: led_n <= regf;
            default:;
        endcase
    end
end

// memory write in
always @(posedge div) begin
    if (~wr && ~full_in) begin
        mem[wp] <= datain;
        wei_in <= 1'b1;
    end
end

// memory write pointer increment
always @(posedge div) begin
    if (!rst) begin
        wp <= 0;
    end else begin
        if (~wr && ~full_in) begin
            wp <= wp + 1'b1;
        end
    end
end

// memory read pointer increment
always @(posedge div) begin
    if (!rst) begin
        rp <= 0;
    end else begin
        if (~rd && ~empty_in) begin
            rp <= rp + 1'b1;
        end
    end
end

// Full signal generate
always @(posedge div) begin
    if (!rst) begin
        full_in <= 1'b0;
    end else begin
        if (rd && ~wr) begin
            if ((wp == rp - 1) || (rp == 4'h0 && wp == 4'hf)) begin
                full_in <= 1'b1;
            end
        end else if (full_in && ~rd) begin
            full_in <= 1'b0;
        end
    end
end

// Empty signal generate
always @(posedge div) begin
    if (!rst) begin
        empty_in <= 1'b1;
    end else begin
        if (~rd && wr) begin
            if ((rp == wp - 1) || (rp == 4'hf && wp == 4'h0)) begin
                empty_in <= 1'b1;
            end
        end else if (empty_in && ~wr) begin
            empty_in <= 1'b0;
        end
    end
end

always @(posedge clk) begin
    if (cnt == 24'b111111111111111111111111) begin
        div <= ~div;
        cnt <= 0;
    end else begin
        cnt <= cnt + 1;
    end
end

endmodule

module SNPS_CLOCK_GATE_HIGH_d_ff_en_W32_0_26 ( CLK, EN, TE, ENCLK );
