module FletcherChecksum (
  input [n-1:0] data_in,
  input [15:0] checksum_ref,
  output reg [15:0] checksum_out
);

parameter n = 4; // number of input data words

// Divide the input data words into two 8-bit halves
reg [7:0] data_in_l [0:n-1];
reg [7:0] data_in_h [0:n-1];
integer i;
always @* begin
  for (i = 0; i < n; i = i + 1) begin
    data_in_l[i] = data_in[i][7:0];
    data_in_h[i] = data_in[i][15:8];
  end
end

// Compute the running sum of the input data words using a modified version of the Fletcher's algorithm
reg [15:0] sum1 [0:n-1];
reg [15:0] sum2 [0:n-1];
reg [15:0] running_sum1;
reg [15:0] running_sum2;
always @* begin
  for (i = 0; i < n; i = i + 1) begin
    sum1[i] = running_sum1 + data_in_l[i];
    sum2[i] = running_sum2 + sum1[i];
    running_sum1 = sum1[i];
    running_sum2 = sum2[i];
  end
end

// Concatenate the two 8-bit halves of the running sum to form the 16-bit checksum
always @* begin
  checksum_out = {running_sum2, running_sum1};
end

// Compare the computed checksum to a reference checksum to determine if the data is valid or not
always @* begin
  if (checksum_out == checksum_ref) begin
    $display("Data is valid");
  end else begin
    $display("Data is invalid");
  end
end

endmodule

module gray_to_binary (
    input clk,
    input rst, // Synchronous reset
    input ena, // Clock enable
    input [3:0] gray,
    output reg [3:0] binary
);

always @(posedge clk) begin
    if (rst) begin
        binary <= 4'b0;
    end else if (ena) begin
        binary[0] <= gray[0];
        binary[1] <= binary[0] ^ gray[1];
        binary[2] <= binary[1] ^ gray[2];
        binary[3] <= binary[2] ^ gray[3];
    end
end

endmodule

