module axis_fifo #
(
  parameter integer S_AXIS_TDATA_WIDTH = 32,
  parameter integer M_AXIS_TDATA_WIDTH = 32
)
(
  // System signals
  input  wire                          aclk,

  // Slave side
  output wire                          s_axis_tready,
  input  wire [S_AXIS_TDATA_WIDTH-1:0] s_axis_tdata,
  input  wire                          s_axis_tvalid,

  // Master side
  input  wire                          m_axis_tready,
  output wire [M_AXIS_TDATA_WIDTH-1:0] m_axis_tdata,
  output wire                          m_axis_tvalid,

  // FIFO_WRITE port
  input  wire                          fifo_write_full,
  output wire [S_AXIS_TDATA_WIDTH-1:0] fifo_write_data,
  output wire                          fifo_write_wren,

  // FIFO_READ port
  input  wire                          fifo_read_empty,
  input  wire [M_AXIS_TDATA_WIDTH-1:0] fifo_read_data,
  output wire                          fifo_read_rden
);

  reg [S_AXIS_TDATA_WIDTH-1:0] fifo [0:15];
  reg [3:0] write_ptr = 0;
  reg [3:0] read_ptr = 0;
  reg [3:0] level = 0;

  always @(posedge aclk) begin
    if (fifo_write_wren && !fifo_write_full) begin
      fifo[write_ptr] <= fifo_write_data;
      write_ptr <= write_ptr + 1;
      level <= level + 1;
    end
    if (fifo_read_rden && !fifo_read_empty) begin
      m_axis_tdata <= fifo[read_ptr];
      read_ptr <= read_ptr + 1;
      level <= level - 1;
    end
  end

  assign s_axis_tready = level < 16;

  assign m_axis_tvalid = !fifo_read_empty;
  assign m_axis_tdata = fifo_read_empty ? {(M_AXIS_TDATA_WIDTH){1'b0}} : fifo[read_ptr];

  assign fifo_read_rden = m_axis_tready && m_axis_tvalid;

  assign fifo_write_data = s_axis_tdata;
  assign fifo_write_wren = s_axis_tvalid && s_axis_tready && level < 16;

endmodule

