module wb_stream_reader #(
  parameter WB_AW = 32,
  parameter WB_DW = 32
) (
  input wire wb_clk_i,
  input wire wb_rst_i,
  input wire [4:0] wb_adr_i,
  input wire [WB_DW-1:0] wb_dat_i,
  input wire [WB_DW/8-1:0] wb_sel_i,
  input wire wb_we_i,
  input wire wb_cyc_i,
  input wire wb_stb_i,
  input wire [2:0] wb_cti_i,
  input wire [1:0] wb_bte_i,
  output reg [WB_DW-1:0] wb_dat_o,
  output reg wb_ack_o,
  output reg wb_err_o,
  output reg irq,
  input wire busy,
  output reg enable,
  output reg [WB_AW-1:0] start_adr,
  output reg [WB_AW-1:0] buf_size,
  output reg [WB_AW-1:0] burst_size
);

  localparam BURST_TYPES = 4;
  localparam BURST_INCR = 2'b00;
  localparam BURST_INCR4 = 2'b01;
  localparam BURST_INCR8 = 2'b10;
  localparam BURST_INCR16 = 2'b11;

  reg [2:0] burst_type;
  reg [31:0] burst_counter;

  always @(*) begin
    case (wb_bte_i)
      BURST_INCR: burst_type = BURST_INCR;
      BURST_INCR4: burst_type = BURST_INCR4;
      BURST_INCR8: burst_type = BURST_INCR8;
      BURST_INCR16: burst_type = BURST_INCR16;
      default: burst_type = BURST_INCR;
    endcase
  end

  always @(posedge wb_clk_i) begin
    if (wb_rst_i) begin
      wb_ack_o <= 0;
      enable <= 0;
      start_adr <= 0;
      buf_size <= 0;
      burst_size <= 0;
      irq <= 0;
      burst_counter <= 0;
    end else begin
      if (wb_stb_i & wb_cyc_i) begin
        if (wb_we_i) begin
          case (wb_adr_i)
            5'h00: enable <= wb_dat_i[0];
            5'h01: start_adr <= wb_dat_i;
            5'h02: buf_size <= wb_dat_i;
            5'h03: burst_size <= wb_dat_i;
          endcase
        end else begin
          wb_ack_o <= 1;
          case (wb_adr_i)
            5'h00: ;
            5'h01: ;
            5'h02: ;
            5'h03: ;
            default: begin
              if (!busy & (burst_counter == 0)) begin
                irq <= 1;
              end
              if (burst_counter < burst_size) begin
                wb_dat_o <= {burst_counter, 1'b0};
                burst_counter <= burst_counter + 1;
              end else begin
                wb_dat_o <= 0;
                burst_counter <= 0;
                irq <= 0;
              end
            end
          endcase
        end
      end else begin
        wb_ack_o <= 0;
      end
    end
  end

endmodule

