module counter(input [15:0] in, input clock, load, inc, reset, output reg[15:0] out);

  wire[15:0] if1, if2, if3, oInc;

  // Or gate for load and increment signals
  Or g1(load, inc, loadInc);

  // Or gate for loadInc and reset signals
  Or g2(loadInc, reset, loadIncReset);

  // 16-bit incrementer
  Inc16 inc1(out, oInc);

  // 16-bit And gate
  And16 g3(out, out, out);

  // 16-bit Mux gates
  Mux16 g4(out, oInc, inc, if1);
  Mux16 g5(if1, in, load, if2);
  Mux16 g6(if2, 16'b0, reset, if3);

  // 16-bit register
  Register reg1(if3, clock, loadIncReset, out);

endmodule

module shift_mult (
    input clk,
    input load,
    input [3:0] A,
    output reg [7:0] product
);

    reg [3:0] shift_reg;
    reg [3:0] multiplier_input;
    reg multiplication_done;

    // Shift register with parallel load input
    always @(posedge clk) begin
        if (load) begin
            shift_reg <= A;
        end else begin
            shift_reg <= {shift_reg[2:0], shift_reg[3]};
        end
    end

    // Unsigned 4-bit multiplier
    always @(posedge clk) begin
        if (!load) begin
            multiplier_input <= shift_reg;
            multiplication_done <= 0;
        end else begin
            multiplication_done <= 1;
        end
    end

    always @(*) begin
        if (multiplication_done) begin
            product <= multiplier_input * A;
        end
    end

endmodule

