module CDR_block (
  input data_in,
  input clk_ref,
  output reg clk_out,
  output reg data_out
);

parameter f_in = 100; // input frequency of the reference clock signal
parameter f_out = 200; // output frequency of the recovered clock signal

reg [31:0] phase_accumulator;
reg [31:0] phase_increment;

always @(posedge clk_ref) begin
  phase_accumulator <= phase_accumulator + phase_increment;
end

always @(posedge clk_ref) begin
  phase_increment <= round((2**32 * f_out) / f_in);
end

always @(posedge clk_ref) begin
  if (phase_accumulator >= (2**31)) begin
    clk_out <= ~clk_out;
    phase_accumulator <= phase_accumulator - (2**31);
  end
end

always @(posedge clk_out) begin
  data_out <= data_in;
end

endmodule

module memory_module(
    input clk,
    input reset,
    input [7:0] address0,
    input ce0,
    output reg [7:0] q0,
    input [7:0] address1,
    input ce1,
    output reg [7:0] q1,
    input [7:0] address2,
    input ce2,
    output reg [7:0] q2
);

parameter DataWidth = 8;
parameter AddressRange = 256;

reg [DataWidth-1:0] rom0 [AddressRange-1:0];
reg [DataWidth-1:0] rom1 [AddressRange-1:0];
reg [DataWidth-1:0] rom2 [AddressRange-1:0];

integer i;

always @(posedge clk) begin
    if (reset) begin
        // reset all memory banks to 0
        for (i = 0; i < AddressRange; i = i + 1) begin
            rom0[i] <= 8'b0;
            rom1[i] <= 8'b0;
            rom2[i] <= 8'b0;
        end
    end else begin
        // read data from memory banks based on address and chip enable signals
        if (ce0) begin
            q0 <= rom0[address0];
        end
        if (ce1) begin
            q1 <= rom1[address1];
        end
        if (ce2) begin
            q2 <= rom2[address2];
        end
    end
end

// initialize memory banks with default values
initial begin
    for (i = 0; i < AddressRange; i = i + 1) begin
        rom0[i] = 8'b0;
        rom1[i] = 8'b0;
        rom2[i] = 8'b0;
    end
end

endmodule

