module fifo_buffer (
  input wr_clk,
  input rst,
  input wr_en,
  input [31:0] wr_data,
  input rd_en,
  input rd_clk,
  output [31:0] rd_data,
  output full,
  output empty,
  output almost_full
);

  parameter DEPTH = 16;
  parameter WIDTH = 32;
  parameter ADDR_WIDTH = $clog2(DEPTH);

  reg [WIDTH-1:0] mem [0:DEPTH-1];
  reg [ADDR_WIDTH-1:0] wr_ptr;
  reg [ADDR_WIDTH-1:0] rd_ptr;
  reg [ADDR_WIDTH-1:0] wr_ptr_gray;
  reg [ADDR_WIDTH-1:0] rd_ptr_gray;
  reg [ADDR_WIDTH-1:0] wr_ptr_gray_next;
  reg [ADDR_WIDTH-1:0] rd_ptr_gray_next;
  reg [ADDR_WIDTH-1:0] wr_ptr_bin_next;
  reg [ADDR_WIDTH-1:0] rd_ptr_bin_next;
  reg [ADDR_WIDTH-1:0] wr_ptr_bin;
  reg [ADDR_WIDTH-1:0] rd_ptr_bin;
  reg full_reg;
  reg empty_reg;
  reg almost_full_reg;
  wire [ADDR_WIDTH-1:0] buf_avail;
  wire [ADDR_WIDTH-1:0] buf_filled;
  wire [ADDR_WIDTH-2:0] wr_addr;
  wire [ADDR_WIDTH-2:0] rd_addr;

  assign wr_addr = wr_ptr_bin[ADDR_WIDTH-2:0];
  assign rd_addr = rd_ptr_bin[ADDR_WIDTH-2:0];

  assign rd_data = mem[rd_addr];
  assign buf_avail = wr_ptr_gray - rd_ptr_gray + DEPTH;
  assign buf_filled = wr_ptr_gray - rd_ptr_gray;

  always @(posedge wr_clk) begin
    if (rst) begin
      wr_ptr <= 0;
      wr_ptr_gray <= 0;
      wr_ptr_bin <= 0;
      full_reg <= 0;
      almost_full_reg <= 0;
    end else if (wr_en && !full_reg) begin
      mem[wr_ptr_bin[ADDR_WIDTH-2:0]] <= wr_data;
      wr_ptr_bin_next <= wr_ptr_bin + 1;
      wr_ptr_gray_next <= wr_ptr_bin_next ^ (wr_ptr_bin_next >> 1);
    end
  end

  always @(posedge rd_clk) begin
    if (rst) begin
      rd_ptr <= 0;
      rd_ptr_gray <= 0;
      rd_ptr_bin <= 0;
      empty_reg <= 1;
    end else if (rd_en && !empty_reg) begin
      rd_ptr_bin_next <= rd_ptr_bin + 1;
      rd_ptr_gray_next <= rd_ptr_bin_next ^ (rd_ptr_bin_next >> 1);
    end
  end

  always @(posedge wr_clk) begin
    if (rst) begin
      wr_ptr_gray <= 0;
    end else if (wr_en && !full_reg) begin
      wr_ptr_gray <= wr_ptr_gray_next;
    end
  end

  always @(posedge rd_clk) begin
    if (rst) begin
      rd_ptr_gray <= 0;
    end else if (rd_en && !empty_reg) begin
      rd_ptr_gray <= rd_ptr_gray_next;
    end
  end

  always @(posedge wr_clk) begin
    if (rst) begin
      wr_ptr_bin <= 0;
    end else if (wr_en && !full_reg) begin
      wr_ptr_bin <= wr_ptr_bin_next;
    end
  end

  always @(posedge rd_clk) begin
    if (rst) begin
      rd_ptr_bin <= 0;
    end else if (rd_en && !empty_reg) begin
      rd_ptr_bin <= rd_ptr_bin_next;
    end
  end

  always @(posedge wr_clk) begin
    if (rst) begin
      full_reg <= 0;
    end else if (wr_en && buf_avail == DEPTH-1) begin
      full_reg <= 1;
    end else if (rd_en && full_reg) begin
      full_reg <= 0;
    end
  end

  always @(posedge rd_clk) begin
    if (rst) begin
      empty_reg <= 1;
    end else if (rd_en && buf_filled == 1) begin
      empty_reg <= 1;
    end else if (wr_en && empty_reg) begin
      empty_reg <= 0;
    end
  end

  always @(posedge wr_clk) begin
    if (rst) begin
      almost_full_reg <= 0;
    end else if (wr_en && buf_avail == DEPTH-2) begin
      almost_full_reg <= 1;
    end else if (rd_en && almost_full_reg) begin
      almost_full_reg <= 0;
    end
  end

  assign full = full_reg;
  assign empty = empty_reg;
  assign almost_full = almost_full_reg;

endmodule

module CDR (
  input data_in,
  input clk_in,
  input clk_local,
  output reg data_out,
  output reg clk_out
);

  // Phase Detector
  reg phase_error;
  always @(posedge clk_local) begin
    phase_error <= clk_in ^ clk_local;
  end

  // Loop Filter
  reg [7:0] control_voltage;
  always @(posedge clk_local) begin
    control_voltage <= control_voltage + phase_error;
  end

  // Voltage-Controlled Delay Line (VCDL)
  reg [7:0] delay_amount;
  always @(posedge clk_local) begin
    delay_amount <= control_voltage;
  end
  wire delayed_clk_in;
  VCDL #(8) vcdl (
    .in(clk_in),
    .out(delayed_clk_in),
    .delay(delay_amount)
  );

  // Flip-Flop
  reg [1:0] data_in_delay;
  always @(posedge delayed_clk_in) begin
    data_in_delay <= {data_in_delay[0], data_in};
  end
  assign data_out = data_in_delay[1];
  assign clk_out = delayed_clk_in;

endmodule

module DEMUX (
  input in,
  output out0,
  output out1,
  output out2,
  output out3
);

  wire d0, d1, d2, d3;
  wire a0, a1, a2, a3;

  // 2-to-4 decoder
  decoder_2to4 decoder (
    .in(in),
    .out0(d0),
    .out1(d1),
    .out2(d2),
    .out3(d3)
  );

  // AND gates
  assign a0 = d0 & ~d1 & ~d2 & ~d3;
  assign a1 = ~d0 & d1 & ~d2 & ~d3;
  assign a2 = ~d0 & ~d1 & d2 & ~d3;
  assign a3 = ~d0 & ~d1 & ~d2 & d3;

  // Output signals
  assign out0 = a0;
  assign out1 = a1;
  assign out2 = a2;
  assign out3 = a3;

endmodule

// 2-to-4 decoder module
module decoder_2to4 (
  input in,
  output out0,
  output out1,
  output out2,
  output out3
);

  assign out0 = ~in & ~in;
  assign out1 = ~in & in;
  assign out2 = in & ~in;
  assign out3 = in & in;

endmodule

