module shift_register(clk, load, in, shift, out);
    input clk, load, shift;
    input [3:0] in;
    output [3:0] out;
    reg [3:0] reg_out;

    always @(posedge clk) begin
        if (load) begin
            reg_out <= in;
        end else if (shift) begin
            reg_out <= {reg_out[2:0], 1'b0};
        end
    end

    assign out = reg_out;
endmodule

module shift_register (
    input clk,
    input areset,
    input load,
    input ena,
    input [3:0] data,
    output [3:0] q
);

    reg [3:0] q;

    always @(posedge clk or negedge areset) begin
        if (!areset) begin
            q <= 4'b0000;
        end else if (load) begin
            q <= data;
        end else if (ena) begin
            q <= {q[2:0], q[3]};
        end
    end

endmodule

module bcd_counter (
    input clk,
    input reset,
    output reg [3:1] ena,
    output reg [15:0] q
);

    reg [3:0] count;

    always @(posedge clk) begin
        if (reset) begin
            count <= 4'b0000;
        end else begin
            count <= count + 1;
        end
    end

    always @* begin
        case (count)
            4'b0000: ena = 3'b001;
            4'b0001: ena = 3'b010;
            4'b0010: ena = 3'b100;
            4'b0011: ena = 3'b001;
            4'b0100: ena = 3'b010;
            4'b0101: ena = 3'b100;
            4'b0110: ena = 3'b001;
            4'b0111: ena = 3'b010;
            4'b1000: ena = 3'b100;
            4'b1001: ena = 3'b001;
            4'b1010: ena = 3'b010;
            4'b1011: ena = 3'b100;
            4'b1100: ena = 3'b001;
            4'b1101: ena = 3'b010;
            4'b1110: ena = 3'b100;
            4'b1111: ena = 3'b001;
        endcase
    end

    assign q = {ena, 12'b0};

endmodule

module functional_module (
    input [3:0] shift_q,
