module top_module (
    input clk,
    input areset,
    input load,
    input ena,
    input [3:0] data,
    output [3:0] shift_q,
    input reset,
    output [3:1] bcd_ena,
    output [15:0] bcd_q,
    output [15:0] final_q
);

    wire [15:0] bcd_q;
    wire [15:0] final_q;

    shift_register shift_reg (
        .clk(clk),
        .areset(areset),
        .load(load),
        .ena(ena),
        .data(data),
        .q(shift_q)
    );

    bcd_counter bcd_cnt (
        .clk(clk),
        .reset(reset),
        .ena(bcd_ena),
        .q(bcd_q)
    );

    functional_module func_mod (
        .shift_q(shift_q),
        .bcd_q(bcd_q),
        .final_q(final_q)
    );

endmodule

module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

    wire [3:0] sum;
    wire Cout1, Cout2, Cout3;

    // First adder stage
    full_adder FA1 (.A(A[0]), .B(B[0]), .Cin(Cin), .S(sum[0]), .Cout(Cout1));

    // Second adder stage
    full_adder FA2 (.A(A[1]), .B(B[1]), .Cin(Cout1), .S(sum[1]), .Cout(Cout2));

    // Third adder stage
    full_adder FA3 (.A(A[2]), .B(B[2]), .Cin(Cout2), .S(sum[2]), .Cout(Cout3));

    // Fourth adder stage
    full_adder FA4 (.A(A[3]), .B(B[3]), .Cin(Cout3), .S(sum[3]), .Cout(Cout));

    assign S = sum;

endmodule

module full_adder (
    input A,
    input B,
    input Cin,
    output S,
    output Cout
);

    wire sum1, sum2, sum3;

    // XOR gates
    assign sum1 = A ^ B;
    assign sum2 = sum1 ^ Cin;

    // AND gates
    assign Cout = (A & B) | (Cin & sum1);
    assign S = sum2;

endmodule

module bcd_dac (
    input [3:0] in,
    output reg vout
);

    // BCD Converter
    wire [3:0] bcd1, bcd2;
    bcd_converter bcd_inst (
        .in(in),
        .bcd1(bcd1),
        .bcd2(bcd2)
    );

    // 8-bit Converter
    wire [7:0] out8;
    bcd_to_8bit bcd8_inst (
        .bcd1(bcd1),
        .bcd2(bcd2),
        .out8(out8)
    );

    // DAC
    wire [7:0] dac_in;
    assign dac_in = out8;
    dac dac_inst (
        .in(dac_in),
        .vout(vout)
    );

endmodule

module bcd_converter (
    input [3:0] in,
    output reg [3:0] bcd1,
    output reg [3:0] bcd2
);

    always @* begin
        case (in)
            4'b0000: begin
                bcd1 = 4'b0000;
                bcd2 = 4'b0000;
            end
            4'b0001: begin
                bcd1 = 4'b0000;
                bcd2 = 4'b0001;
            end
            4'b0010: begin
                bcd1 = 4'b0001;
                bcd2 = 4'b0000;
            end
            4'b0011: begin
                bcd1 = 4'b0001;
                bcd2 = 4'b0001;
            end
            4'b0100: begin
                bcd1 = 4'b0010;
                bcd2 = 4'b0000;
            end
            4'b0101: begin
                bcd1 = 4'b0010;
                bcd2 = 4'b0001;
            end
            4'b0110: begin
                bcd1 = 4'b0011;
                bcd2 = 4'b0000;
            end
            4'b0111: begin
                bcd1 = 4'b0011;
                bcd2 = 4'b0001;
            end
            4'b1000: begin
                bcd1 = 4'b0100;
                bcd2 = 4'b0000;
            end
            4'b1001: begin
                bcd1 = 4'b0100;
                bcd2 = 4'b0001;
            end
            4'b1010: begin
                bcd1 = 4'b0101;
                bcd2 = 4'b0000;
            end
            4'b1011: begin
                bcd1 = 4'b0101;
                bcd2 = 4'b0001;
            end
            4'b1100: begin
                bcd1 = 4'b0110;
                bcd2 = 4'b0000;
            end
            4'b1101: begin
                bcd1 = 4'b0110;
                bcd2 = 4'b0001;
            end
            4'b1110: begin
                bcd1 = 4'b0111;
                bcd2 = 4'b0000;
            end
            4'b1111: begin
                bcd1 = 4'b0111;
                bcd2 = 4'b0001;
            end
        endcase
    end

