module tracemem (
  input clk,
  input [37:0] jdo,
  input jrst_n,
  input reset_n,
  input take_action_tracectrl,
  input take_action_tracemem_a,
  input take_action_tracemem_b,
  input take_no_action_tracemem_a,
  input [15:0] trc_ctrl,
  input [35:0] tw,
  output tracemem_on,
  output [35:0] tracemem_trcdata,
  output tracemem_tw,
  output trc_enb,
  output [6:0] trc_im_addr,
  output trc_wrap,
  output xbrk_wrap_traceoff
);

  wire trc_on_chip = ~trc_ctrl[8];
  wire tw_valid = |tw[35:32];
  wire jdo_3 = jdo[3];
  wire jdo_4 = jdo[4];

  reg [6:0] trc_im_addr /* synthesis ALTERA_ATTRIBUTE = "SUPPRESS_DA_RULE_INTERNAL=\"D101,D103,R101\""  */;
  reg [16:0] trc_jtag_addr /* synthesis ALTERA_ATTRIBUTE = "SUPPRESS_DA_RULE_INTERNAL=D101"  */;
  reg trc_wrap /* synthesis ALTERA_ATTRIBUTE = "SUPPRESS_DA_RULE_INTERNAL=\"D101,D103,R101\""  */;
  wire trc_enb = trc_ctrl[0];
  assign tracemem_on = trc_enb & trc_on_chip;
  assign tracemem_trcdata = 0;
  assign tracemem_tw = trc_wrap;
  assign xbrk_wrap_traceoff = trc_ctrl[10] & trc_wrap;
  assign trc_im_addr = (trc_enb & trc_on_chip & tw_valid) ? (trc_wrap ? 0 : trc_im_addr+1) : trc_im_addr;

  always @(posedge clk or negedge jrst_n) begin
    if (!jrst_n) begin
      trc_im_addr <= 0;
      trc_wrap <= 0;
    end else if (!take_action_tracectrl && !take_action_tracemem_a && !take_action_tracemem_b && take_no_action_tracemem_a) begin
      trc_jtag_addr <= trc_jtag_addr + 1;
    end else if (take_action_tracectrl && (jdo_4 | jdo_3)) begin
      if (jdo_4) begin
        trc_im_addr <= 0;
      end
      if (jdo_3) begin
        trc_wrap <= 0;
      end
    end else if (trc_enb & trc_on_chip & tw_valid) begin
      trc_im_addr <= trc_im_addr + 1;
      if (&trc_im_addr) begin
        trc_wrap <= 1;
      end
    end
  end

endmodule

