    output tx_interrupt);

    parameter BidirectMode = 0;
    parameter HighSpeedMode = 1;
    parameter NumberOfDataBits = 8;
    parameter ShiftDir = 0;

    // Internal signals
    reg [NumberOfDataBits-1:0] tx_data;
    reg [NumberOfDataBits-1:0] rx_data;
    reg [NumberOfDataBits-1:0] shift_reg;
    reg [NumberOfDataBits-1:0] mask;
    reg [NumberOfDataBits-1:0] count;
    reg [2:0] state;

    // Assign default values to internal signals
    initial begin
        tx_data = 0;
        rx_data = 0;
        shift_reg = 0;
        mask = {NumberOfDataBits{1'b1}};
        count = 0;
        state = 3'b000;
    end

    // Generate clock signal for SPI
    always @(posedge clock) begin
        if (reset) begin
            sclk <= 1'b0;
            count <= 0;
            mask <= {NumberOfDataBits{1'b1}};
            rx_data <= 0;
            shift_reg <= 0;
            state <= 3'b000;
        end else begin
            case (state)
                3'b000: begin // Idle state
                    sclk <= 1'b0;
                    mosi <= 1'b0;
                    ss <= 1'b1;
                    if (BidirectMode) begin
                        sdat <= 1'bz;
                    end
                    if (rx_interrupt) begin
                        rx_data <= miso;
                        state <= 3'b001;
                    end
                    if (tx_interrupt) begin
                        state <= 3'b010;
                    end
                end
                3'b001: begin // Receive state
                    sclk <= 1'b1;
                    mosi <= 1'b0;
                    ss <= 1'b0;
                    if (BidirectMode) begin
                        sdat <= 1'bz;
                    end
                    count <= count + 1;
                    shift_reg <= {shift_reg[NumberOfDataBits-2:0], rx_data};
                    if (count == NumberOfDataBits) begin
                        mask <= {mask[NumberOfDataBits-2:0], 1'b0};
                        state <= 3'b000;
                    end
                end
                3'b010: begin // Transmit state
                    sclk <= 1'b1;
                    mosi <= tx_data[NumberOfDataBits-1];
                    ss <= 1'b0;
                    if (BidirectMode) begin
                        sdat <= tx_data[NumberOfDataBits-1];
                    end
                    count <= count + 1;
                    tx_data <= {tx_data[NumberOfDataBits-2:0], 1'b0};
                    if (count == NumberOfDataBits) begin
                        mask <= {mask[NumberOfDataBits-2:0], 1'b0};
                        state <= 3'b000;
                    end
                end
            endcase
        end
    end

    // Assign output values for bidirectional mode
    assign sdat = (BidirectMode) ? shift_reg[NumberOfDataBits-1] : sdat;

    // Assign default values for unused inputs
    assign rx_interrupt = 1'b0;
    assign tx_interrupt = 1'b0;

endmodule

