module adder_subtractor (
    input [3:0] A,
    input [3:0] B,
    input sub, // 1 for subtraction, 0 for addition
    output [3:0] Q
);

    assign Q = sub ? A - B : A + B;

endmodule

module top_module (
    input [3:0] A,
    input [3:0] B,
    input select, // Select input to choose operation and output format
    output [3:0] Q // Final output in either BCD or binary format
);

    wire [3:0] bcd_A_high;
    wire [3:0] bcd_A_low;
    wire [3:0] bcd_B_high;
    wire [3:0] bcd_B_low;
    wire [3:0] bcd_Q_high;
    wire [3:0] bcd_Q_low;
    wire [3:0] binary_Q;

    binary_bcd_converter converter_A_high(.binary_in(A[3:0]), .bcd_out_high(bcd_A_high));
    binary_bcd_converter converter_A_low(.binary_in(A[3:0]), .bcd_out_low(bcd_A_low));
    binary_bcd_converter converter_B_high(.binary_in(B[3:0]), .bcd_out_high(bcd_B_high));
    binary_bcd_converter converter_B_low(.binary_in(B[3:0]), .bcd_out_low(bcd_B_low));

    adder_subtractor add_sub(.A(A), .B(B), .sub(select), .Q(binary_Q));

    assign bcd_Q_high = binary_Q[3] ? bcd_A_high - bcd_B_high : bcd_A_high + bcd_B_high;
    assign bcd_Q_low = binary_Q[3] ? bcd_A_low - bcd_B_low : bcd_A_low + bcd_B_low;

    assign Q = select ? {bcd_Q_high, bcd_Q_low} : binary_Q;

endmodule

module clk_generator(clk_in, clk_out);
  parameter CLOCK_DIVIDER = 1;
  parameter LOCKED_DELAY = 100;
  parameter MAX_DELAY = 1;

  input clk_in;
  output clk_out;
  output locked;

  reg [31:0] counter;
  reg locked_reg;
  wire clk_out_bb;
  wire locked_bb;

  system_clk_wiz_1_0 clk_wiz_inst (
    .clk_in1(clk_in),
    .clk_out1(clk_out_bb),
    .locked(locked_bb)
  );

  assign locked = locked_reg;

  always @(posedge clk_in) begin
    if (counter == LOCKED_DELAY) begin
      locked_reg <= 1;
    end
    if (counter == (2 * CLOCK_DIVIDER) - 1) begin
      counter <= 0;
    end else begin
      counter <= counter + 1;
    end
  end

  always @(posedge clk_out_bb) begin
    if (counter < MAX_DELAY) begin
      $display("Error: Maximum delay exceeded");
    end
  end

  assign clk_out = clk_out_bb;

endmodule

