module fifo_24_12k
    #(
        parameter WIDTH = 24,
        parameter DEPTH = 12288
    ) (
        input clk,
        input rst,
        input wr_en,
        input rd_en,
        input [WIDTH-1:0] din,
        output [WIDTH-1:0] dout,
        output empty,
        output full,
        output reg [31:0] data_count
    );

    reg [WIDTH-1:0] mem [0:DEPTH-1];
    reg [31:0] head = 0;
    reg [31:0] tail = 0;
    reg [31:0] count = 0;

    always @(posedge clk) begin
        if (rst) begin
            head <= 0;
            tail <= 0;
            count <= 0;
        end else begin
            if (wr_en && !full) begin
                mem[head] <= din;
                head <= head + 1;
                count <= count + 1;
            end
            if (rd_en && !empty) begin
                dout <= mem[tail];
                tail <= tail + 1;
                count <= count - 1;
            end
        end
    end

    assign empty = (count == 0);
    assign full = (count == DEPTH);
    assign data_count = count;

endmodule

module ClapLight(
    input clk_48,
    input rst,
    input [9:0] mic_sample,
    output reg light_state,   // 1 if light should be on, 0 if not on
    output reg [3:0] debug
);

    // State variables
    reg [2:0] state, state_d;
    reg [31:0] delay, delay_d;
    reg light_state_d;

    localparam THRESHOLD = 10'd770; // (770/1023)
    localparam DELAY_SIM = 32'h4;
    localparam DELAY_QUARTERSEC = 32'hB71B00; // 12 million (48 mhz / 4 = 12 mill)
    localparam DELAY_2SEC = 32'h5B8D800; // 96 million (double 48 Mhz, so 2 seconds)

    localparam WAIT_CLAP1 = 3'd0,
                DELAY_CLAP2 = 3'd1,
                WAIT_CLAP2 = 3'd2,
                TOGGLE_STATE = 3'd3,
                DELAY_RESET = 3'd4;

    assign debug = state;

    // sequential logic
    always @ (posedge clk_48 or posedge rst) begin
        if(rst) begin
            state <= WAIT_CLAP1;
            delay <= 32'h0;
            light_state <= 1'b0;
        end else begin
            state <= state_d;
            delay <= delay_d;
            light_state <= light_state_d;
        end
    end

    // combinational logic
    always @ (*) begin
        // set previous values
        state_d = state;
        delay_d = delay;
        light_state_d = light_state;

        case(state)
            WAIT_CLAP1: begin
                if(mic_sample > THRESHOLD) begin
                    state_d = DELAY_CLAP2;
                    delay_d = DELAY_QUARTERSEC; // set up for delay
                end else
                    state_d = WAIT_CLAP1;
            end
            DELAY_CLAP2: begin
                if(delay == 32'b0) begin
                    state_d = WAIT_CLAP2;
                    delay_d = DELAY_2SEC; // set up for delay
                end else
                    delay_d = delay - 1'b1;
            end
            WAIT_CLAP2: begin
                if(delay == 32'b0) begin
                    state_d = WAIT_CLAP1; // took too long for second clap
                end else begin
                    delay_d = delay - 1'b1;
                    if(mic_sample > THRESHOLD)
                        state_d = TOGGLE_STATE;
                    else
                        state_d = WAIT_CLAP2;
                end
            end
            TOGGLE_STATE: begin
                state_d = DELAY_RESET;
                delay_d = DELAY_2SEC;

                if(light_state == 1'b1)
                    light_state_d = 1'b0;
                else
                    light_state_d = 1'b1;
            end
            DELAY_RESET: begin
                if(delay == 32'b0)
                    state_d = WAIT_CLAP1;
                else
                    delay_d = delay - 1'b1;
            end
        endcase
    end

endmodule

module EtherCAT (
  input clk,
  input rst,
  input [7:0] tx_data,
  input tx_valid,
  output tx_ready,
  output [7:0] rx_data,
  output rx_valid,
  input rx_ready,
  output tx_ack,
  input rx_ack
);

  // Define the EtherCAT protocol
  parameter IDLE = 2'b00;
  parameter START = 2'b01;
  parameter DATA = 2'b10;
  parameter END = 2'b11;

  // Define the state machine for the master block
  reg [1:0] tx_state = IDLE;
  reg [7:0] tx_packet;
  reg tx_packet_valid = 0;
  reg tx_packet_sent = 0;

  // Define the state machine for the slave block
  reg [1:0] rx_state = IDLE;
  reg [7:0] rx_packet;
  reg rx_packet_valid = 0;
  reg rx_packet_received = 0;

  // Define the signals for the EtherCAT network
  reg tx_active = 0;
  reg rx_active = 0;

  // Define the logic for the master block
  always @(posedge clk) begin
    if (rst) begin
      tx_state <= IDLE;
      tx_packet_valid <= 0;
      tx_packet_sent <= 0;
      tx_active <= 0;
      tx_ready <= 1;
    end else begin
      case (tx_state)
        IDLE: begin
          if (tx_valid) begin
            tx_packet <= {START, tx_data};
            tx_packet_valid <= 1;
            tx_state <= DATA;
            tx_ready <= 0;
          end else begin
            tx_packet_valid <= 0;
            tx_ready <= 1;
          end
        end
        DATA: begin
          if (tx_packet_sent) begin
            tx_packet_valid <= 0;
            tx_state <= IDLE;
            tx_ready <= 1;
          end else if (tx_active) begin
            tx_ready <= 0;
          end else begin
            tx_packet <= {DATA, tx_data};
            tx_packet_valid <= 1;
            tx_active <= 1;
            tx_ready <= 0;
          end
        end
      endcase
    end
  end

  // Define the logic for the slave block
  always @(posedge clk) begin
    if (rst) begin
      rx_state <= IDLE;
      rx_packet_valid <= 0;
      rx_packet_received <= 0;
      rx_active <= 0;
      rx_valid <= 0;
      tx_ack <= 0;
    end else begin
      case (rx_state)
        IDLE: begin
          if (rx_ready) begin
            rx_state <= START;
          end
        end
        START: begin
          if (rx_active) begin
            rx_state <= DATA;
          end else if (rx_packet_valid && (rx_packet[7:6] == START)) begin
            rx_packet_received <= 1;
            rx_packet_valid <= 0;
            rx_data <= rx_packet[5:0];
            rx_valid <= 1;
            rx_state <= END;
          end
        end
        DATA: begin
          if (rx_active) begin
            rx_state <= DATA;
          end else if (rx_packet_valid && (rx_packet[7:6] == DATA)) begin
            rx_data <= rx_packet[5:0];
            rx_valid <= 1;
            rx_state <= END;
          end
        end
        END: begin
          if (rx_active) begin
            rx_state <= END;
          end else if (rx_packet_valid && (rx_packet[7:6] == END)) begin
            rx_packet_received <= 1;
            rx_packet_valid <= 0;
            tx_ack <= 1;
            rx_state <= IDLE;
            rx_valid <= 0;
          end
        end
      endcase
    end
  end

  // Define the communication between the master and slave blocks
  assign tx_ready = (tx_state == IDLE) && !tx_packet_sent;
  assign rx_ack = rx_packet_received;
  always @(posedge clk) begin
    if (rst) begin
      tx_packet_sent <= 0;
      rx_packet_received <= 0;
    end else begin
      if (tx_active) begin
        tx_packet_sent <= 1;
        tx_active <= 0;
      end
      if (rx_packet_valid) begin
        rx_packet_received <= 0;
        rx_packet_valid <= 0;
      end
    end
  end

endmodule

module mux_4to2 (
    X,
    A0,
    A1,
    A2,
    A3,
    S0,
    S1,
    EN
);

    output X;
    input A0;
    input A1;
    input A2;
    input A3;
    input S0;
    input S1;
    input EN;

    wire X0, X1;

    assign X0 = (S0 & S1) ? A3 : (S0 ? A2 : (S1 ? A1 : A0));
    assign X1 = (EN == 1'b0) ? X0 : 1'b0;
    assign X = X1;

endmodule

module four_bit_adder (
    A,
    B,
    CI,
    SUM,
    COUT
);

    input [3:0] A;
    input [3:0] B;
    input CI;
    output [3:0] SUM;
    output COUT;

    wire [3:0] a_xor_b_i;
    wire [3:0] a_xor_b_xor_ci_i;
    wire [3:0] a_and_b_i;
    wire [3:0] a_and_b_and_ci_i;
    wire [3:0] a_or_b_i;
    wire [3:0] a_or_b_or_ci_i;
    wire a_xor_b_xor_ci_xor_cout_i;

    // Implement the adder logic using only the allowed gates and the named wires
    xor #(.N(4)) xor0 (.out(a_xor_b_i), .in0(A), .in1(B));
    xor #(.N(4)) xor1 (.out(a_xor_b_xor_ci_i), .in0(a_xor_b_i), .in1(CI));
    and #(.N(4)) and0 (.out(a_and_b_i), .in0(A), .in1(B));
    and #(.N(4)) and1 (.out(a_and_b_and_ci_i), .in0(a_and_b_i), .in1(CI));
    or #(.N(4)) or0 (.out(a_or_b_i), .in0(A), .in1(B));
    or #(.N(4)) or1 (.out(a_or_b_or_ci_i), .in0(a_or_b_i), .in1(CI));
    xor xor2 (.out(a_xor_b_xor_ci_xor_cout_i), .in0(a_xor_b_xor_ci_i), .in1(a_and_b_and_ci_i));

    // Assign the output ports
    assign SUM = a_xor_b_xor_ci_i;
    assign COUT = a_xor_b_xor_ci_xor_cout_i;

endmodule

module fourBitCounter(clk, reset, count);
  input clk, reset;
  output reg [3:0] count;
  wire [3:0] q;
  DflipFlop dff1(.dataIn(count[0]), .clk(clk), .dataOut(q[0]));
  DflipFlop dff2(.dataIn(q[0]), .clk(clk), .dataOut(q[1]));
  DflipFlop dff3(.dataIn(q[1]), .clk(clk), .dataOut(q[2]));
  DflipFlop dff4(.dataIn(q[2]), .clk(clk), .dataOut(q[3]));

  always @(posedge clk) begin
    if (reset) begin
      count <= 4'b0;
    end else if (count == 4'b1111) begin
      count <= 4'b0;
    end else begin
      count <= count + 1;
    end
  end
endmodule

module pipelined_adder(
    input CLK, RST, CTRL,
    input [3:0] A,
    input [3:0] B,
    input CIN,
    output reg [3:0] SUM,
    output reg [3:0] DIFF,
    output reg COUT
);

reg [3:0] sum_stage1;
reg [3:0] diff_stage1;
reg [3:0] sum_stage2;
reg [3:0] diff_stage2;

always @(posedge CLK) begin
    if (RST) begin
        SUM <= 4'b0;
        DIFF <= 4'b0;
        COUT <= 1'b0;
        sum_stage1 <= 4'b0;
        diff_stage1 <= 4'b0;
        sum_stage2 <= 4'b0;
        diff_stage2 <= 4'b0;
    end else begin
        case (CTRL)
            2'b00: begin // compute sum and difference
                sum_stage1 <= A + B;
                diff_stage1 <= A - B;
                sum_stage2 <= sum_stage1;
                diff_stage2 <= diff_stage1;
            end
            2'b01: begin // compute sum only
                sum_stage1 <= A + B;
                sum_stage2 <= sum_stage1;
            end
            2'b10: begin // compute difference only
                diff_stage1 <= A - B;
                diff_stage2 <= diff_stage1;
            end
            default: begin // do nothing
                sum_stage1 <= sum_stage2;
                diff_stage1 <= diff_stage2;
                sum_stage2 <= sum_stage2;
                diff_stage2 <= diff_stage2;
            end
        endcase

        SUM <= sum_stage2;
        DIFF <= diff_stage2;
        COUT <= sum_stage1[4];
    end
end

endmodule

module fsm_sequence_detection (
  input clk,
  input reset,
  input data,
  output reg match
);

  parameter A = 3'b000, B = 3'b001, C = 3'b010, D = 3'b011, E = 3'b100;
  reg [2:0] state, next_state;

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      state <= A;
    end else begin
      state <= next_state;
    end
  end

  always @(*) begin
    match = 0;
    next_state = state;
    case (state)
      A: begin
        if (data) begin
          next_state = B;
        end
      end
      B: begin
        if (data) begin
          next_state = B;
        end else begin
          next_state = C;
        end
      end
      C: begin
        if (data) begin
          next_state = D;
        end else begin
          next_state = A;
        end
      end
      D: begin
        if (data) begin
          next_state = E;
        end else begin
          next_state = A;
        end
      end
      E: begin
        if (data) begin
          next_state = B;
          match = 1;
        end else begin
          next_state = A;
        end
      end
    endcase
  end

endmodule

