module PLL_DLL (
  input ref_clk,
  input fb_clk,
  input reset,
  output out_clk,
  output locked
);

parameter n = 10; // number of delay elements in the DLL
parameter m = 4; // multiplication factor of the PLL
parameter p = 2; // division factor of the PLL

reg [n-1:0] delay_line;
reg locked_pll, locked_dll;
wire [n-1:0] delayed_clk;
wire [n-1:0] phase_diff;
wire [n-1:0] filtered_diff;
wire [31:0] vco_count;
wire [31:0] vco_increment;

// Phase Detector
assign phase_diff = fb_clk ^ delayed_clk;

// Low-Pass Filter
assign filtered_diff = {filtered_diff[n-2:0], phase_diff[0]} + {filtered_diff[n-1], phase_diff[n-1]};

// Voltage-Controlled Oscillator
assign vco_increment = (m * ref_clk) / p;
always @(posedge ref_clk) begin
  if (locked_pll) begin
    vco_count <= vco_count + vco_increment;
  end
end
assign out_clk = vco_count[31];
assign locked = locked_pll & locked_dll;

// Delay Locked Loop
assign delayed_clk[0] = ref_clk;
genvar i;
generate
  for (i = 1; i < n; i = i + 1) begin : delay_loop
    assign delayed_clk[i] = delay_line[i-1];
  end
endgenerate
assign phase_diff[0] = fb_clk ^ delayed_clk[0];
always @(posedge ref_clk) begin
  if (locked_dll) begin
    if (filtered_diff[n-1]) begin
      delay_line <= {delay_line[n-2:0], 1'b1};
    end else begin
      delay_line <= {delay_line[n-2:0], 1'b0};
    end
  end
end

// Lock Detection
always @(posedge ref_clk or posedge reset) begin
  if (reset) begin
    locked_pll <= 0;
    locked_dll <= 0;
    vco_count <= 0;
  end else begin
    if (phase_diff == 0) begin
      locked_dll <= 1;
    end else begin
      locked_dll <= 0;
    end
    if (vco_count >= (p-1)) begin
      locked_pll <= 1;
    end else begin
      locked_pll <= 0;
    end
  end
end

endmodule

module s3a_icap_wb
  (input clk, input reset,
   input cyc_i, input stb_i, input we_i, output ack_o,
   input [31:0] dat_i, output [31:0] dat_o);//, output [31:0] debug_out);

   assign dat_o[31:8] = 24'd0;

   wire 	BUSY, CE, WRITE, ICAPCLK;

   //changed this to gray-ish code to prevent glitching
   reg [2:0] 	icap_state;
   localparam ICAP_IDLE  = 0;
   localparam ICAP_WR0 	 = 1;
   localparam ICAP_WR1 	 = 5;
   localparam ICAP_RD0 	 = 2;
   localparam ICAP_RD1 	 = 3;

   always @(posedge clk)
     if(reset)
       icap_state 	<= ICAP_IDLE;
     else
       case(icap_state)
	 ICAP_IDLE :
	   begin
	      if(stb_i & cyc_i)
		if(we_i)
		  icap_state <= ICAP_WR0;
		else
		  icap_state <= ICAP_RD0;
	   end
	 ICAP_WR0 :
	   icap_state <= ICAP_WR1;
	 ICAP_WR1 :
	   icap_state <= ICAP_IDLE;
	 ICAP_RD0 :
	   icap_state <= ICAP_RD1;
	 ICAP_RD1 :
	   icap_state <= ICAP_IDLE;
       endcase // case (icap_state)

   assign WRITE 	 = (icap_state == ICAP_WR0) | (icap_state == ICAP_WR1);
   assign CE 		 = (icap_state == ICAP_WR0) | (icap_state == ICAP_RD0);
   assign ICAPCLK        = CE & (~clk);

   assign ack_o = (icap_state == ICAP_WR1) | (icap_state == ICAP_RD1);

   ICAP_SPARTAN3A ICAP_SPARTAN3A_inst 
     (.BUSY(BUSY),          // Busy output
      .O(dat_o[7:0]),            // 32-bit data output
      .CE(~CE),              // Clock enable input
      .CLK(ICAPCLK),            // Clock input
      .I(dat_i[7:0]),            // 32-bit data input
      .WRITE(~WRITE)         // Write input
      );

endmodule

module binary_converter(
