module calculator (
    input clk,
    input rst,
    input [7:0] a,
    input [7:0] b,
    input [1:0] op,
    output [7:0] result,
    output valid
);

reg [7:0] result_reg;
reg valid_reg;

always @(posedge clk) begin
    if (rst) begin
        result_reg <= 8'b0;
        valid_reg <= 1'b0;
    end else begin
        case (op)
            2'b00: begin // addition
                result_reg <= a + b;
                valid_reg <= 1'b1;
            end
            2'b01: begin // subtraction
                result_reg <= a - b;
                valid_reg <= 1'b1;
            end
            2'b10: begin // multiplication
                result_reg <= a * b;
                valid_reg <= 1'b1;
            end
            2'b11: begin // division
                if (b == 0) begin
                    result_reg <= 8'b0;
                    valid_reg <= 1'b0;
                end else begin
                    result_reg <= a / b;
                    valid_reg <= 1'b1;
                end
            end
        endcase
    end
end

assign result = result_reg;
assign valid = valid_reg;

endmodule

module pipeline_register (
  input clk,
  input [width-1:0] data_in,
  output [width-1:0] data_out
);

parameter width = 8; // width of the data signal
parameter depth = 4; // depth of the pipeline register

reg [width-1:0] pipeline [0:depth-1];

integer i;

always @(posedge clk) begin
  for (i = depth-1; i > 0; i = i - 1) begin
    pipeline[i] <= pipeline[i-1];
  end
  pipeline[0] <= data_in;
end

assign data_out = pipeline[depth-1];

endmodule

