module booth_multiplier (
    input [3:0] A,
    input [3:0] B,
    output [7:0] result
);
    reg [7:0] product;
    reg [4:0] multiplier;
    reg [3:0] multiplicand;
    reg [2:0] state;

    always @(*) begin
        case (state)
            3'b000: begin
                multiplier = {1'b0, B[3:2]};
                multiplicand = {2'b00, A};
                state = 3'b001;
            end
            3'b001: begin
                if (multiplier[0] == 1) begin
                    product = product - multiplicand;
                end
                state = 3'b010;
            end
            3'b010: begin
                multiplier = {multiplier[3:1], multiplier[0]};
                multiplicand = {multiplicand[2:0], 1'b0};
                state = 3'b011;
            end
            3'b011: begin
                if (multiplier == 4'b0001 || multiplier == 4'b1111) begin
                    product = product + multiplicand;
                end
                state = (multiplier == 4'b0001 || multiplier == 4'b1111) ? 3'b100 : 3'b001;
            end
            3'b100: begin
                result = product;
                state = 3'b000;
            end
        endcase
    end

endmodule

module control_logic (
    input [3:0] A,
    input [3:0] B,
    input [1:0] C,
    input select,
    output [7:0] result
);
    wire [1:0] sum;
    wire carry_out;

    add_sub add_sub_inst (
        .A(A[1:0]),
        .B(B[1:0]),
        .control(C[0]),
        .sum(sum),
        .carry_out(carry_out)
    );

    booth_multiplier booth_multiplier_inst (
        .A(A),
        .B(B),
        .result(result)
    );

    reg [1:0] active_sum;
    reg active_carry_out;

    always @(select, A, B) begin
        if (select == 1'b0) begin
            active_sum = sum;
            active_carry_out = carry_out;
        end else begin
            active_sum = booth_multiplier_inst.result[1:0];
            active_carry_out = booth_multiplier_inst.result[2];
        end
    end

    assign result = {active_carry_out, active_sum};

endmodule

