module counter(
    input clk, start_stop, 
    input [31:0] max_count,
    output [31:0] count,
    output max_reached
    );

    reg [31:0] count_reg;
    reg max_reached_reg;

    always @(posedge clk) begin
        if (start_stop) begin
            if (count_reg == max_count) begin
                count_reg <= 0;
                max_reached_reg <= 1;
            end else begin
                count_reg <= count_reg + 1;
                max_reached_reg <= 0;
            end
        end else begin
            max_reached_reg <= 0;
        end
    end

    assign count = count_reg;
    assign max_reached = max_reached_reg;

endmodule

module shift_reg_priority_encoder (
    input clk,
    input load,
    input [7:0] data_in,
    output reg [2:0] priority,
    output reg [7:0] shift_reg_out
);

reg [7:0] shift_reg;

always @(posedge clk) begin
    if (load) begin
        shift_reg <= data_in;
    end else begin
        shift_reg <= {shift_reg[6:0], shift_reg[7]};
    end
end

assign priority = (shift_reg[0]) ? 0 :
                   (shift_reg[1]) ? 1 :
                   (shift_reg[2]) ? 2 :
                   3'b0;

always @(*) begin
    case (priority)
        3'b000: shift_reg_out = shift_reg;
        3'b001: shift_reg_out = {6'b0, 1'b1, shift_reg[7]};
        3'b010: shift_reg_out = {5'b0, 2'b1, shift_reg[7:6]};
        3'b011: shift_reg_out = {4'b0, 3'b1, shift_reg[7:5]};
        3'b100: shift_reg_out = {3'b0, 4'b1, shift_reg[7:4]};
        3'b101: shift_reg_out = {2'b0, 5'b1, shift_reg[7:3]};
        3'b110: shift_reg_out = {1'b0, 6'b1, shift_reg[7:2]};
        3'b111: shift_reg_out = {7'b1, shift_reg[0]};
    endcase
end

endmodule

