    .priority(priority),
    .shift_reg_out(shift_reg_out)
);

always @(posedge clk) begin
    if (load) begin
        data_out <= data_in;
    end else begin
        data_out <= shift_reg_out;
    end
end

always @(*) begin
    case (priority)
        3'b000: data_out = shift_reg_out;
        3'b001: data_out = {6'b0, 1'b1, shift_reg_out[7]};
        3'b010: data_out = {5'b0, 2'b1, shift_reg_out[7:6]};
        3'b011: data_out = {4'b0, 3'b1, shift_reg_out[7:5]};
