        3'b101: data_out = {2'b0, 5'b1, shift_reg_out[7:3]};
        3'b110: data_out = {1'b0, 6'b1, shift_reg_out[7:2]};
        3'b111: data_out = {7'b1, shift_reg_out[0]};
