module NIOS_SYSTEMV3_NIOS_CPU_nios2_oci_im (
  input clk,
  input [37:0] jdo,
  input jrst_n,
  input reset_n,
  input take_action_tracectrl,
  input take_action_tracemem_a,
  input take_action_tracemem_b,
  input take_no_action_tracemem_a,
  input [15:0] trc_ctrl,
  input [35:0] tw,
  output reg tracemem_on,
  output reg [35:0] tracemem_trcdata,
  output reg tracemem_tw,
  output reg trc_enb,
  output reg [6:0] trc_im_addr,
  output reg trc_wrap,
  output reg xbrk_wrap_traceoff
);

  wire trc_on_chip = ~trc_ctrl[8];
  wire tw_valid = |tw[35:32];

  always @(posedge clk or negedge jrst_n) begin
    if (!jrst_n) begin
      trc_im_addr <= 0;
      trc_wrap <= 0;
    end else if (!take_action_tracectrl && !take_action_tracemem_a && !take_action_tracemem_b && !take_no_action_tracemem_a) begin
      trc_im_addr <= 0;
      trc_wrap <= 0;
    end else if (take_action_tracectrl && (jdo[4] | jdo[3])) begin
      if (jdo[4]) trc_im_addr <= 0;
      if (jdo[3]) trc_wrap <= 0;
    end else if (trc_enb & trc_on_chip & tw_valid) begin
      trc_im_addr <= trc_im_addr + 1;
      if (&trc_im_addr) trc_wrap <= 1;
    end
  end

  always @(posedge clk or negedge reset_n) begin
    if (!reset_n) trc_enb <= 0;
    else trc_enb <= trc_ctrl[0];
  end

  always @(posedge clk or negedge reset_n) begin
    if (!reset_n) tracemem_on <= 0;
    else tracemem_on <= trc_enb;
  end

  always @(posedge clk or negedge reset_n) begin
    if (!reset_n) tracemem_trcdata <= 0;
    else tracemem_trcdata <= (trc_enb & tw_valid) ? tw : tracemem_trcdata;
  end

  always @(posedge clk or negedge reset_n) begin
    if (!reset_n) tracemem_tw <= 0;
    else tracemem_tw <= trc_wrap;
  end

  always @(posedge clk or negedge reset_n) begin
    if (!reset_n) xbrk_wrap_traceoff <= 0;
    else xbrk_wrap_traceoff <= trc_ctrl[10] & trc_wrap;
  end

endmodule

module vga_controller_640_60 (rst,pixel_clk,HS,VS,hcounter,vcounter,blank);

	input rst, pixel_clk;	// global reset, pixel clock
	output reg HS, VS, blank;	// sync controls, blank indicator
	output reg [10:0] hcounter, vcounter;	// pixel coordinates

	parameter HMAX = 800; 	// maxium value for the horizontal pixel counter
	parameter HLINES = 640;	// total number of visible columns
	parameter HFP = 648; 	// value for the horizontal counter where front porch ends
	parameter HSP = 744; 	// value for the horizontal counter where the synch pulse ends
	parameter VMAX = 525; 	// maxium value for the vertical pixel counter
	parameter VLINES = 480;	// total number of visible lines
	parameter VFP = 482; 	// value for the vertical counter where the frone proch ends
	parameter VSP = 484; 	// value for the vertical counter where the synch pulse ends
	parameter SPP = 0;		// value for the porch synchronization pulse

	wire video_enable;	// valid region indicator

	initial begin
		hcounter = 0;
		vcounter = 0;
	end

	// create a "blank" indicator
	always@(posedge pixel_clk)begin
		blank <= ~video_enable; 
	end

	// Create a horizontal beam trace (horizontal time):
	always@(posedge pixel_clk, posedge rst)begin
		if(rst == 1) hcounter <= 0;
		else if (hcounter == HMAX) hcounter <= 0;
		else hcounter <= hcounter + 1'b1;
	end

	// Create a vertical beam trace (vertical time):
	always@(posedge pixel_clk, posedge rst)begin
		if(rst == 1) vcounter <=0;
		else if(hcounter == HMAX) begin
			if(vcounter == VMAX) vcounter <= 0;
			else vcounter <= vcounter + 1'b1; 
		end
	end

	// Check if between horizontal porches,
	// if not send horizontal porch synchronization pulse
	always@(posedge pixel_clk)begin
		if(hcounter >= HFP && hcounter < HSP) HS <= SPP;
		else HS <= ~SPP; 
	end

	// Check if between vertical porches,
	// if not send vertical porch synchronization pulse
	always@(posedge pixel_clk)begin
		if(vcounter >= VFP && vcounter < VSP) VS <= SPP;
		else VS <= ~SPP; 
	end

	// create a video enabled region
	assign video_enable = (hcounter < HLINES && vcounter < VLINES) ? 1'b1 : 1'b0;

endmodule

module soft_tbm_queue
#(parameter DATA_WIDTH=36)
(
    input clk,
    input sync,
    input reset,
    input write,
    input read,
    input clear,
    input clear_token,
    output empty,
    output full,
    output [3:0] size,
    input [DATA_WIDTH:0] din,
    output [DATA_WIDTH:0] dout
);

    // internal signals
    wire write_int = write && !full;
    wire read_int = read && !empty;
    wire [(DATA_WIDTH-1):0] fifo_din;
    wire [(DATA_WIDTH-1):0] fifo_dout;
    wire tok_in;
    wire tok_out;

    // assign signals
    assign {fifo_din, tok_in} = din;
    assign dout = {fifo_dout, tok_out};

    // token queue
    reg [15:0] tok_queue;
    reg [3:0] tok_pos;

    // reset token queue
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            tok_queue <= 16'd0;
            tok_pos <= 4'd15;
        end else if (sync) begin
            if (clear) tok_queue <= 16'd0;
            else if (write_int) begin
                if (clear_token) tok_queue <= {15'd0, tok_in};
                else tok_queue <= {tok_queue[14:0], tok_in};
            end else if (clear_token) tok_queue <= 16'd0;

            if (clear) tok_pos <= 4'd15;
            else if (write_int && !read_int) tok_pos <= tok_pos + 4'd1;
            else if (!write_int && read_int) tok_pos <= tok_pos - 4'd1;
        end
    end

    // assign token output
    assign tok_out = tok_queue[tok_pos];

    // scfifo module
    scfifo #(
        .add_ram_output_register("OFF"),
        .intended_device_family("Cyclone III"),
        .lpm_numwords(16),
        .lpm_showahead("ON"),
        .lpm_type("scfifo"),
        .lpm_width(DATA_WIDTH),
        .lpm_widthu(4),
        .overflow_checking("OFF"),
        .underflow_checking("OFF"),
        .use_eab("ON")
    ) fifo (
        .aclr(reset),
        .clock(clk),
        .data(fifo_din),
        .rdreq(read_int && sync),
        .wrreq(write_int && sync),
        .empty(empty),
        .full(full),
        .q(fifo_dout),
        .sclr(clear),
        .usedw(size),
        .almost_full(),
        .almost_empty()
    );

endmodule

module even_parity_checker(
    input D0, D1, D2, D3, RST, ECLK, DQSW,
    output reg Q
);

    reg [3:0] data_reg;
    reg SCLK;

    always @(posedge ECLK) begin
        if (RST) begin
            Q <= 1'b0;
            data_reg <= 4'b0;
        end
        else if (DQSW) begin
            data_reg <= {D3, D2, D1, D0};
        end
    end

    always @(posedge SCLK) begin
        if (DQSW) begin
            Q <= 1'b0;
            data_reg <= {D3, D2, D1, D0};
        end
        else begin
            Q <= ~^data_reg;
            data_reg <= {data_reg[2:0], D3};
        end
    end

endmodule

