module mux4(
    input in0,
    input in1,
    input sel0,
    input sel1,
    output out
);

wire w1, w2, w3;

assign w1 = sel0 & sel1;
assign w2 = sel0 & (~sel1);
assign w3 = (~sel0) & sel1;

assign out = (in0 & (~w1) & (~w2)) | (in1 & (~w1) & (~w3)) | (in0 & w1) | (in1 & w1);

endmodule

module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [4:0] S,
    output Cout
);

    // Define internal signals
    wire [3:0] sum;
    wire [3:0] carry;
    wire [2:0] P;
    wire [2:0] G;

    // Generate the sum bits and carry-out signals using a series of full-adders
    full_adder fa0(.A(A[0]), .B(B[0]), .Cin(Cin), .S(sum[0]), .Cout(carry[0]));
    full_adder fa1(.A(A[1]), .B(B[1]), .Cin(carry[0]), .S(sum[1]), .Cout(carry[1]));
    full_adder fa2(.A(A[2]), .B(B[2]), .Cin(carry[1]), .S(sum[2]), .Cout(carry[2]));
    full_adder fa3(.A(A[3]), .B(B[3]), .Cin(carry[2]), .S(sum[3]), .Cout(Cout));

    // Generate the carry-lookahead signals using the P and G functions
    assign P[0] = A[0] & B[0];
    assign G[0] = A[0] | B[0];
    assign P[1] = A[1] & B[1];
    assign G[1] = A[1] | B[1];
    assign P[2] = A[2] & B[2];
    assign G[2] = A[2] | B[2];

    // Generate the carry-out signal using the carry-lookahead unit
    assign carry[0] = P[0] | (G[0] & Cin);
    assign carry[1] = P[1] | (G[1] & P[0]) | (G[1] & G[0] & Cin);
    assign carry[2] = P[2] | (G[2] & P[1]) | (G[2] & G[1] & P[0]) | (G[2] & G[1] & G[0] & Cin);

    // Assign the output signals
    assign S = {sum, Cout};

endmodule

module full_adder (
    input A,
    input B,
    input Cin,
    output S,
    output Cout
);

    // Define internal signals
    wire s1;
    wire c1;
    wire c2;

    // Generate the sum and carry-out signals using XOR and AND gates
    assign s1 = A ^ B;
    assign Cout = A & B;
    assign c1 = s1 & Cin;
    assign S = s1 ^ Cin;
    assign c2 = Cout | c1;
    assign Cout = c2;

endmodule

module top_module (
    input clk,
    input reset,
    input [7:0] A,
    input [7:0] B,
    input CIN,
    input SUB,
    input up_down,
    output [7:0] output_value
);

    // 8-bit adder/subtractor
    wire [8:0] temp_sum;
    wire temp_overflow;
    assign temp_overflow = (temp_sum[8] == 1);
    assign output_value = (up_down == 1) ? temp_sum[7:0] : counter_value;

    add_sub_module add_sub (
        .A(A),
        .B(B),
        .CIN(CIN),
        .SUB(SUB),
        .SUM(temp_sum[7:0]),
        .OVF(temp_overflow)
    );

    // 3-bit up/down counter
    reg [2:0] counter_value;
    always @(posedge clk or negedge reset) begin
        if (reset == 0) begin
            counter_value <= 0;
        end else if (up_down == 1) begin
            counter_value <= counter_value + 1;
        end else begin
            counter_value <= counter_value - 1;
        end
    end

endmodule

