module fifo_generator
   (O1,
    O2,
    O3,
    I1,
    I2,
    p_18_out,
    I3,
    E,
    clk,
    Q);

  output O1;
  output O2;
  output [5:0]O3;

  input [5:0]I1;
  input I2;
  input p_18_out;
  input [0:0]I3;
  input [0:0]E;
  input clk;
  input [0:0]Q;

  wire [5:0] buffer [0:5];
  reg [2:0] pointer;
  reg [2:0] counter;

  assign O1 = (pointer == counter) ? 1 : 0;
  assign O2 = ((pointer+1) == counter) ? 1 : 0;

  always @(posedge clk) begin
    if (E) begin
      buffer[pointer] <= I1;
      pointer <= (pointer == 5) ? 0 : pointer+1;
    end
    if (Q) begin
      O3 <= buffer[counter];
      counter <= (counter == 5) ? 0 : counter+1;
    end
  end

  assign O3 = (O2) ? 0 : buffer[counter];

endmodule

