module fifo36_to_fifo72
  #(parameter LE=0)
   (input clk, input reset, input clear,
    input [35:0] f36_datain,
    input f36_src_rdy_i,
    output f36_dst_rdy_o,

    output [71:0] f72_dataout,
    output f72_src_rdy_o,
    input f72_dst_rdy_i,
    output [31:0] debug
    );

   // Shortfifo on input to guarantee no deadlock
   wire [35:0] 	  f36_data_int;
   wire 	  f36_src_rdy_int, f36_dst_rdy_int;

   fifo_short #(.WIDTH(36)) head_fifo
     (.clk(clk),.reset(reset),.clear(clear),
      .datain(f36_datain), .src_rdy_i(f36_src_rdy_i), .dst_rdy_o(f36_dst_rdy_o),
      .dataout(f36_data_int), .src_rdy_o(f36_src_rdy_int), .dst_rdy_i(f36_dst_rdy_int),
      .space(),.occupied() );

   // Actual f36 to f72 which could deadlock if not connected to shortfifos
   reg 		  f72_sof_int, f72_eof_int;
   reg [2:0] 	  f72_occ_int;
   wire [71:0] 	  f72_data_int;
   wire 	  f72_src_rdy_int, f72_dst_rdy_int;

   reg [1:0] 	  state;
   reg [31:0] 	  dat0, dat1;

   wire 	  f36_sof_int  = f36_data_int[32];
   wire 	  f36_eof_int  = f36_data_int[33];
   wire [1:0]	  f36_occ_int  = f36_data_int[35:34];

   wire 	  xfer_out = f72_src_rdy_int & f72_dst_rdy_int;

   always @(posedge clk)
     if(f36_src_rdy_int & ((state==0)|xfer_out))
       f72_sof_int 	<= f36_sof_int;

   always @(posedge clk)
     if(f36_src_rdy_int & ((state != 2)|xfer_out))
       f72_eof_int 	<= f36_eof_int;

   always @(posedge clk)
     if(reset)
       begin
	  state 	<= 0;
	  f72_occ_int   <= 0;
       end
     else
       if(f36_src_rdy_int)
	 case(state)
	   0 : 
	     begin
		dat0 <= f36_data_int;
		if(f36_eof_int)
		  begin
		     state <= 2;
		     case (f36_occ_int)
		       0 : f72_occ_int <= 3'd4;
		       1 : f72_occ_int <= 3'd1;
		       2 : f72_occ_int <= 3'd2;
		       3 : f72_occ_int <= 3'd3;
		     endcase // case (f36_occ_int)
		  end
		else
		  state <= 1;
	     end
	   1 : 
	     begin
		dat1 <= f36_data_int;
		state <= 2;
		if(f36_eof_int)
		  case (f36_occ_int)
		    0 : f72_occ_int <= 3'd0;
		    1 : f72_occ_int <= 3'd5;
		    2 : f72_occ_int <= 3'd6;
		    3 : f72_occ_int <= 3'd7;
		  endcase // case (f36_occ_int)
	     end
	   2 : 
	     if(xfer_out)
	       begin
		  dat0 <= f36_data_int;
		  if(f36_eof_int) // remain in state 2 if we are at eof
		    case (f36_occ_int)
		      0 : f72_occ_int <= 3'd4;
		      1 : f72_occ_int <= 3'd1;
		      2 : f72_occ_int <= 3'd2;
		      3 : f72_occ_int <= 3'd3;
		    endcase // case (f36_occ_int)
		  else
		    state 	   <= 1;
	       end
	 endcase // case(state)
       else
	 if(xfer_out)
	   begin
	      state 	   <= 0;
	      f72_occ_int  <= 0;
	   end

   assign    f36_dst_rdy_int  = xfer_out | (state != 2);
   assign    f72_data_int     = LE ? {3'b000,f72_occ_int[2:0],f72_eof_int,f72_sof_int,dat1,dat0} :
				{3'b000,f72_occ_int[2:0],f72_eof_int,f72_sof_int,dat0,dat1};
   assign    f72_src_rdy_int  = (state == 2);

   assign    debug = state;

   // Shortfifo on output to guarantee no deadlock
   fifo_short #(.WIDTH(72)) tail_fifo
     (.clk(clk),.reset(reset),.clear(clear),
      .datain(f72_data_int), .src_rdy_i(f72_src_rdy_int), .dst_rdy_o(f72_dst_rdy_int),
      .dataout(f72_dataout), .src_rdy_o(f72_src_rdy_o), .dst_rdy_i(f72_dst_rdy_i),
      .space(),.occupied() );

endmodule

// Short FIFO module
module fifo_short
  #(parameter WIDTH=8)
   (input clk, input reset, input clear,
    input [WIDTH-1:0] datain,
    input src_rdy_i,
    output dst_rdy_o,
    output [WIDTH-1:0] dataout,
    output src_rdy_o,
    input dst_rdy_i,
    output [31:0] space,
    output [31:0] occupied
    );

   wire [WIDTH-1:0] fifo [0:7];
   wire [2:0] head;
   wire [2:0] tail;
   wire [2:0] next_head;
   wire [2:0] next_tail;
   reg  [31:0] space_int;
   reg  [31:0] occupied_int;
   wire [WIDTH-1:0] dataout_int;
   wire 	  src_rdy_int;
   wire 	  dst_rdy_o_int;

   assign space 	  = space_int;
   assign occupied   = occupied_int;
   assign dataout    = dataout_int;
   assign src_rdy_o  = src_rdy_int;
   assign dst_rdy_o  = dst_rdy_o_int;

   always @(posedge clk)
     if(reset)
       begin
	  head <= 3'b0;
	  tail <= 3'b0;
	  space_int <= 8'd0;
	  occupied_int <= 8'd0;
       end
     else
       begin
	  head <= next_head;
	  tail <= next_tail;
	  space_int <= space_int + src_rdy_i - dst_rdy_i;
	  occupied_int <= occupied_int + dst_rdy_i - src_rdy_i;
       end

   assign src_rdy_int = (head != tail) | (space_int > 0);
   assign dst_rdy_o_int = (head != tail) | (occupied_int > 0);

   assign dataout_int = fifo[tail];

   always @(posedge clk)
     if(src_rdy_i & dst_rdy_i & (head != tail))
       begin
	  fifo[head] <= datain;
	  next_head <= (head == 7) ? 3'b0 : head + 1;
       end
     else
       next_head <= head;

   always @(posedge clk)
     if(src_rdy_i & dst_rdy_i & (head != tail))
       begin
	  next_tail <= (tail == 7) ? 3'b0 : tail + 1;
       end
     else
       next_tail <= tail;

endmodule

module counter_display(clock, ar, button, a1, b1, c1, d1, e1, f1, g1, a2, b2, c2, d2, e2, f2, g2, a3, b3, c3, d3, e3, f3, g3, led);
