module sendPacketArbiter (
    input HCTxReq,
    input [3:0] HC_PID,
    input HC_SP_WEn,
    input SOFTxReq,
    input SOF_SP_WEn,
    input clk,
    input rst,
    output reg HCTxGnt,
    output reg SOFTxGnt,
    output reg [3:0] sendPacketPID,
    output reg sendPacketWEnable
);

// Define state encodings
parameter HC_ACT = 2'b00;
parameter SOF_ACT = 2'b01;
parameter SARB_WAIT_REQ = 2'b10;
parameter START_SARB = 2'b11;

// Define state variables
reg [1:0] currState;
reg [1:0] nextState;

// Define internal signals
reg muxSOFNotHC;
reg [3:0] nextSendPacketPID;
reg nextSendPacketWEnable;

// Define output signals
assign sendPacketPID = currState == HC_ACT ? HC_PID : 4'h2; // 4'h2 is the PID for SOF packets
assign HCTxGnt = currState == HC_ACT;
assign SOFTxGnt = currState == SOF_ACT;

// Define state transition logic
always @(*) begin
    case (currState)
        HC_ACT: begin
            if (HCTxReq == 1'b0) begin
                nextState = SARB_WAIT_REQ;
                HCTxGnt = 1'b0;
            end
        end
        SOF_ACT: begin
            if (SOFTxReq == 1'b0) begin
                nextState = SARB_WAIT_REQ;
                SOFTxGnt = 1'b0;
            end
        end
        SARB_WAIT_REQ: begin
            if (HCTxReq == 1'b1) begin
                nextState = HC_ACT;
                HCTxGnt = 1'b1;
                muxSOFNotHC = 1'b0;
            end else if (SOFTxReq == 1'b1) begin
                nextState = SOF_ACT;
                SOFTxGnt = 1'b1;
                muxSOFNotHC = 1'b1;
            end
        end
        START_SARB: begin
            nextState = SARB_WAIT_REQ;
        end
    endcase
end

// Define state update logic
always @(posedge clk) begin
    if (rst) begin
        currState <= START_SARB;
        muxSOFNotHC <= 1'b0;
        SOFTxGnt <= 1'b0;
        HCTxGnt <= 1'b0;
        nextSendPacketPID <= 4'h0;
        nextSendPacketWEnable <= 1'b0;
    end else begin
        currState <= nextState;
        muxSOFNotHC <= muxSOFNotHC;
        SOFTxGnt <= SOFTxGnt;
        HCTxGnt <= HCTxGnt;
        nextSendPacketPID <= sendPacketPID;
        nextSendPacketWEnable <= sendPacketWEnable;
    end
end

// Define send packet logic
always @(muxSOFNotHC or SOF_SP_WEn or HC_SP_WEn or HC_PID) begin
    if (muxSOFNotHC == 1'b1) begin
        nextSendPacketWEnable <= SOF_SP_WEn;
        nextSendPacketPID <= 4'h2;
    end else begin
        nextSendPacketWEnable <= HC_SP_WEn;
        nextSendPacketPID <= HC_PID;
    end
end

// Assign output signals
assign sendPacketWEnable = nextSendPacketWEnable;

endmodule

module signal_converter(
