    assign out_or = |in;
    assign out_xor = ^in;
endmodule
module add_op (
    input a,
    input b,
    output [7:0] out_add
);
    assign out_add = a + b;
endmodule
module top_module (
    input clk,
    input [99:0] in,
    output reg q,
    output out_and,
    output out_or,
    output out_xor,
    output [7:0] out_add
);
    wire d_ff_out;
    wire comb_and_out;
    wire comb_or_out;
    wire comb_xor_out;

    d_flip_flop d_ff (
        .clk(clk),
        .d(in[0]),
        .q(d_ff_out)
    );

    comb_ops comb (
        .in(in),
        .out_and(comb_and_out),
        .out_or(comb_or_out),
        .out_xor(comb_xor_out)
    );

    add_op add (
        .a(d_ff_out),
        .b({comb_and_out, comb_or_out, comb_xor_out}),
        .out_add(out_add)
    );

    assign q = d_ff_out;
    assign out_and = comb_and_out;
    assign out_or = comb_or_out;
    assign out_xor = comb_xor_out;
endmodule

module battery_management (
  input voltage,
  input current,
  input charge_en,
  input discharge_en,
  input monitor_en,
  output charge_ctrl,
  output discharge_ctrl,
  output monitor
);

  reg charge_ctrl;
  reg discharge_ctrl;
  reg monitor;

  // Charging threshold
  parameter CHARGE_THRESHOLD = 4.2;

  // Discharging threshold
  parameter DISCHARGE_THRESHOLD = 3;

  // Monitoring range
  parameter MONITOR_MIN = 3;
  parameter MONITOR_MAX = 4.2;

  always @(*) begin
    // Charge control
    if (charge_en && voltage < CHARGE_THRESHOLD) begin
      charge_ctrl = 1;
    end else begin
      charge_ctrl = 0;
    end

    // Discharge control
    if (discharge_en && voltage > DISCHARGE_THRESHOLD) begin
      discharge_ctrl = 1;
    end else begin
      discharge_ctrl = 0;
    end

    // Monitor
    if (monitor_en && voltage >= MONITOR_MIN && voltage <= MONITOR_MAX) begin
      monitor = 1;
    end else begin
      monitor = 0;
    end
  end

endmodule

module wb_abrgr (
    input sys_rst,

    input             wbs_clk_i,	    // Wishbone slave interface
    input      [19:1] wbs_adr_i,
    input      [15:0] wbs_dat_i,
    output reg [15:0] wbs_dat_o,
    input      [ 1:0] wbs_sel_i,
    input             wbs_tga_i,
    input             wbs_stb_i,
    input             wbs_cyc_i,
    input             wbs_we_i,
    output            wbs_ack_o,

    input             wbm_clk_i,	    // Wishbone master interface
    output reg [19:1] wbm_adr_o,
    output reg [15:0] wbm_dat_o,
    input      [15:0] wbm_dat_i,
    output reg [ 1:0] wbm_sel_o,
    output reg        wbm_tga_o,
    output            wbm_stb_o,
    output            wbm_cyc_o,
    output reg        wbm_we_o,
    input             wbm_ack_i
  );

  wire       wbs_stb;
  wire       init_tr;
  reg        wbm_stb;
  reg  [2:0] sync_stb;
  reg  [2:0] sync_ack;
  reg        ft_stb;
  reg        ft_ack;
  reg        stb_r;
  reg        ack_r;

  reg [19:1] wbm_adr_o_r;
  reg [15:0] wbm_dat_o_r;
  reg [ 1:0] wbm_sel_o_r;
  reg        wbs_tga_i_r;
  reg        wbm_tga_o_r;
  reg        wbs_we_i_r;
  reg        wbm_we_o_r;
  reg [15:0] wbs_dat_o_r;
  reg [15:0] wbm_dat_i_r;

  assign wbs_stb = wbs_stb_i & wbs_cyc_i;

  // recreate the flag from the level change
  assign wbs_ack_o = (sync_ack[2] ^ sync_ack[1]);
  assign wbm_stb_o = wbm_stb;
  assign wbm_cyc_o = wbm_stb;

  // new wishbone transaction is issued:
  //   -  by changing stb from 0 to 1
  //   - by continue asserting stb after ack is received
  assign init_tr = ~stb_r & wbs_stb | ack_r & ~wbs_ack_o & wbs_stb;

  always @(posedge wbm_clk_i)
    wbm_stb <= sys_rst ? 1'b0 : (wbm_stb ? ~wbm_ack_i : sync_stb[2] ^ sync_stb[1]);

  // old stb and ack state
  always @(posedge wbs_clk_i) stb_r <= wbs_stb;
  always @(posedge wbs_clk_i) ack_r <= wbs_ack_o;

  always @(posedge wbs_clk_i)
    ft_stb <= sys_rst ? 1'b0 : (init_tr ? ~ft_stb : ft_stb);

  // synchronize the last level change
  always @(posedge wbm_clk_i)
    sync_stb <= sys_rst ? 3'h0 : {sync_stb[1:0], ft_stb};

  // this changes level when a flag is seen
  always @(posedge wbm_clk_i)
    ft_ack <= sys_rst ? 1'b0 : (wbm_ack_i ? ~ft_ack : ft_ack);

  // which can then be synched to wbs_clk_i
  always @(posedge wbs_clk_i)
    sync_ack <= sys_rst ? 3'h0 : {sync_ack[1:0], ft_ack};

  // rest of the wishbone signals
  always @(posedge wbm_clk_i)
    {wbm_adr_o, wbm_adr_o_r} <= {wbm_adr_o_r, wbs_adr_i};

  always @(posedge wbm_clk_i)
    {wbm_dat_o, wbm_dat_o_r} <= {wbm_dat_o_r, wbs_dat_i};

  always @(posedge wbm_clk_i)
    {wbm_sel_o, wbm_sel_o_r} <= {wbm_sel_o_r, wbs_sel_i};

  always @(posedge wbs_clk_i) wbs_we_i_r <= wbs_we_i;
  always @(posedge wbm_clk_i)
    {wbm_we_o, wbm_we_o_r} <= {wbm_we_o_r, wbs_we_i_r};

  always @(posedge wbs_clk_i) wbs_tga_i_r <= wbs_tga_i;
  always @(posedge wbm_clk_i)
    {wbm_tga_o, wbm_tga_o_r} <= {wbm_tga_o_r, wbs_tga_i_r};

   // Register input coming from the slave as that can change
   // after the ack is received
  always @(posedge wbm_clk_i)
    wbm_dat_i_r <= wbm_ack_i ? wbm_dat_i : wbm_dat_i_r;

  always @(posedge wbs_clk_i)
    {wbs_dat_o, wbs_dat_o_r} <= {wbs_dat_o_r, wbm_dat_i_r};

// --------------------------------------------------------------------
endmodule

