module add_sub_comp (
    input [3:0] A,
    input [3:0] B,
    input S,
    output [3:0] R,
    output Cout,
    output [3:0] C
);

    wire [3:0] add_out;
    wire [3:0] sub_out;
    wire [3:0] comp_out;
    wire carry;

    // Adder-Subtractor
    full_adder fa0(.a(A[0]), .b(~B[0]), .cin(S), .sum(add_out[0]), .cout(carry));
    full_adder fa1(.a(A[1]), .b(~B[1]), .cin(carry), .sum(add_out[1]), .cout(carry));
    full_adder fa2(.a(A[2]), .b(~B[2]), .cin(carry), .sum(add_out[2]), .cout(carry));
    full_adder fa3(.a(A[3]), .b(~B[3]), .cin(carry), .sum(add_out[3]), .cout(Cout));

    full_adder fa4(.a(A[0]), .b(B[0]), .cin(~S), .sum(sub_out[0]), .cout(carry));
    full_adder fa5(.a(A[1]), .b(B[1]), .cin(carry), .sum(sub_out[1]), .cout(carry));
    full_adder fa6(.a(A[2]), .b(B[2]), .cin(carry), .sum(sub_out[2]), .cout(carry));
    full_adder fa7(.a(A[3]), .b(B[3]), .cin(carry), .sum(sub_out[3]), .cout(carry));

    assign R = (S) ? add_out : sub_out;

    // Comparator
    assign comp_out = (A > B) ? A : (A == B) ? A : B;
    assign C = comp_out;

endmodule

