module lfsr (
   // Inputs
   clk,
   rst,
   in,
   // Outputs
   out
   );

   input clk, rst;
   input [31:0] in;
   output reg [31:0] out;

   reg [31:0] lfsr;

   always @(posedge clk) begin
      if (rst) begin
         lfsr <= 32'hD70A4497;
         out <= lfsr;
      end
      else begin
         lfsr <= {lfsr[30:0], lfsr[31]^lfsr[2]^lfsr[0]};
         out <= lfsr;
      end
   end

   always @ (posedge clk) begin
      if (rst) begin
         lfsr <= in;
      end
   end

endmodule

module fifo(
    input rst, clk, push, pop,
    input [7:0] d,
    output [7:0] q,
    output full, empty,
    output [2:0] count,
    output almost_empty, almost_full
);
    parameter WIDTH = 8;
    parameter DEPTH = 6;
    parameter DEPTH_ADDR_WIDTH = $clog2(DEPTH);
    parameter ALMOST_EMPTY_COUNT = 1;
    parameter ALMOST_FULL_COUNT = 1;

    reg [WIDTH-1:0] r_q;
    reg [DEPTH_ADDR_WIDTH-1:0] r_end, r_beg;
    reg [WIDTH-1:0] ram [DEPTH-1:0];

    always @(posedge clk) begin
        if (rst) begin
            r_end <= 0;
            r_beg <= 0;
        end else begin
            r_q <= ram[r_end];
            if (pop && !empty) r_end <= r_end + 1;
            if (push && !full) begin
                ram[r_beg] <= d;
                r_beg <= r_beg + 1;
            end
        end
    end

    assign q = r_q;
    assign empty = (r_end == r_beg);
    assign full = (r_end[DEPTH_ADDR_WIDTH-1:0] == r_beg[DEPTH_ADDR_WIDTH-1:0]) && (r_end[DEPTH_ADDR_WIDTH] != r_beg[DEPTH_ADDR_WIDTH]);
    assign count = {1'b0, r_beg} - {1'b0, r_end};
    assign almost_empty = (count <= ALMOST_EMPTY_COUNT);
    assign almost_full = (count >= DEPTH-ALMOST_FULL_COUNT);

    always @(posedge clk) begin
        if (full && push) begin
            $display("ERROR: %d Overflow at %m", $time);
            $finish;
        end
        if (empty && pop) begin
            $display("ERROR: %d Underflow at %m", $time);
            $finish;
        end
    end
endmodule

