module crc_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [15:0] data,    // Input data for CRC calculation
    output reg [7:0] crc   // Output CRC result
);

    // Shift register with parallel load input
    reg [15:0] shift_reg;
    input parallel_load;
    always @(posedge clk) begin
        if (reset) begin
            shift_reg <= 16'h0000;
        end else if (parallel_load) begin
            shift_reg <= data;
        end else begin
            shift_reg <= {shift_reg[14:0], data[0]};
        end
    end

    // 4-bit counter with synchronous reset
    reg [3:0] counter;
    always @(posedge clk) begin
        if (reset) begin
            counter <= 4'h0;
        end else begin
            counter <= counter + 1;
        end
    end

    // CRC calculation module
    crc_calculator crc_calc(
        .data_in(shift_reg[15]),    // Input data bit
        .crc_in(counter),           // Current counter value
        .crc_out(crc)               // Output CRC result
    );

endmodule

module crc_calculator (
    input data_in,      // Input data bit
    input [3:0] crc_in, // Current CRC value
    output reg [7:0] crc_out  // Output CRC result
);

    // Predefined CRC polynomial: x^8 + x^2 + x + 1
    reg [7:0] polynomial = 8'h07;

    // CRC calculation logic
    always @(data_in or crc_in) begin
        if (data_in ^ crc_out[7]) begin
            crc_out = {crc_out[6:0], 1'b0} ^ polynomial;
        end else begin
            crc_out = {crc_out[6:0], 1'b0};
        end
    end

endmodule

