module one_shot_pulse_generator (
  input trig,
  input rst,
  output reg out
);

  parameter t = 10; // duration of the generated pulse in time units

  reg [7:0] count; // counter to count the duration of the pulse
  reg state; // flip-flop to store the state of the circuit

  always @(posedge trig or posedge rst) begin
    if (rst) begin // reset the circuit
      count <= 0;
      out <= 0;
      state <= 0;
    end else if (trig && !state) begin // start pulse generation
      count <= t;
      out <= 1;
      state <= 1;
    end else if (count > 0) begin // continue pulse generation
      count <= count - 1;
    end else if (state) begin // end pulse generation
      out <= 0;
      state <= 0;
    end
  end

endmodule

module fifo(clk, rst, din, wr_en, rd_en, dout, full, empty, data_count);
  parameter DEPTH = 4096;
  parameter WIDTH = 24;
  parameter ADDR_WIDTH = $clog2(DEPTH);

  input clk, rst, wr_en, rd_en;
  input [WIDTH-1:0] din;
  output [WIDTH-1:0] dout;
  output full, empty;
  output reg [ADDR_WIDTH-1:0] data_count;

  reg [WIDTH-1:0] mem [0:DEPTH-1];
  reg [ADDR_WIDTH-1:0] wr_ptr, rd_ptr;
  wire [ADDR_WIDTH-1:0] next_wr_ptr = wr_ptr + 1'b1;
  wire [ADDR_WIDTH-1:0] next_rd_ptr = rd_ptr + 1'b1;

  assign dout = mem[rd_ptr];
  assign full = (wr_ptr == next_rd_ptr);
  assign empty = (wr_ptr == rd_ptr);

  always @(posedge clk) begin
    if (rst) begin
      wr_ptr <= 0;
      rd_ptr <= 0;
      data_count <= 0;
    end else begin
      if (wr_en && !full) begin
        mem[wr_ptr] <= din;
        wr_ptr <= next_wr_ptr;
        data_count <= data_count + 1'b1;
      end
      if (rd_en && !empty) begin
        rd_ptr <= next_rd_ptr;
        data_count <= data_count - 1'b1;
      end
    end
  end
endmodule

module ALU(A, B, ZF, OF, F, ALU_OP);
    input [2:0] ALU_OP;
    input [31:0] A, B;
    output reg [31:0] F;
    output reg ZF, OF;
    reg C32;

    always @(*)
    begin
        case(ALU_OP)
            3'd0:begin //and
                F = A&B;
                OF = 0;
            end
            3'd1:begin //or
                F = A|B;
                OF = 0;
            end
            3'd2:begin //xor
                F = A^B;
                OF = 0;
            end
            3'd3:begin //nor
				F = ~(A|B);
				OF = 0;
			end
            3'd4:begin //add
                {C32, F} = A + B;
                OF = A[31]^B[31]^F[31]^C32;
            end
            3'd5:begin //sub
                {C32, F} = A - B;
                OF = A[31]^B[31]^F[31]^C32;
            end
            3'd6:begin //slt
                if (A<B)
                    begin
                        F = 32'd1;
                    end
                else 
                    begin
                        F = 32'd0;
                    end
                OF = 0;
            end
            3'd7:begin //sll
              F=B<<A;
              OF=0;
            end
            default:begin
              F=A;
              OF = 0;
            end

        endcase
        if (F == 32'd0)
            begin
                ZF = 1;
            end
        else 
            begin
                ZF = 0;
            end
    end

endmodule

module scale_counter (
    input clk,
    input reset,
    input [31:0] high,
    input [31:0] low,
    input [31:0] initial_value,
    input [8*6-1:0] mode,
    input [31:0] ph_tap,
    output reg cout
);

    reg [31:0] count;
    reg [31:0] output_shift_count;
    reg [31:0] tmp_cout;
    reg first_rising_edge;
    reg clk_last_value;
    reg init;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= initial_value;
            output_shift_count <= 1;
            tmp_cout <= 0;
            first_rising_edge <= 0;
        end else if (clk_last_value !== clk) begin
            if (init !== 1'b1) begin
                clk_last_value <= 0;
                init <= 1'b1;
            end
            if (mode == "   off") begin
                tmp_cout <= tmp_cout;
            end else if (mode == "bypass") begin
                tmp_cout <= clk;
                first_rising_edge <= 1;
            end else if (first_rising_edge == 0) begin
                if (clk == 1) begin
                    if (output_shift_count == initial_value) begin
                        tmp_cout <= clk;
                        first_rising_edge <= 1;
                    end else begin
                        output_shift_count <= output_shift_count + 1;
                    end
                end
            end else if (output_shift_count < initial_value) begin
                if (clk == 1) begin
                    output_shift_count <= output_shift_count + 1;
                end
            end else begin
                count <= count + 1;
                if (mode == "  even" && (count == (high*2) + 1)) begin
                    tmp_cout <= 0;
                end else if (mode == "   odd" && (count == (high*2))) begin
                    tmp_cout <= 0;
                end else if (count == (high + low)*2 + 1) begin
                    tmp_cout <= 1;
                    count <= 1;
                end
            end
            clk_last_value <= clk;
        end
    end

    always @(*) begin
        if (ph_tap == 0) begin
            cout <= tmp_cout;
        end else begin
            cout <= tmp_cout << ph_tap;
        end
    end

endmodule

