module fsm_4bit_sequence_detection (
  input clk,
  input reset,
  input data,
  output reg match
);

  parameter S0 = 2'b00;
  parameter S1 = 2'b01;
  parameter S2 = 2'b10;
  parameter S3 = 2'b11;

  reg [1:0] state;
  reg [3:0] shift_reg;

  always @(posedge clk, negedge reset) begin
    if (!reset) begin
      state <= S0;
      shift_reg <= 4'b0;
      match <= 1'b0;
    end
    else begin
      case(state)
        S0: begin
          if (data) begin
            shift_reg <= {shift_reg[2:0], data};
            state <= S1;
          end
        end
        S1: begin
          if (data) begin
            shift_reg <= {shift_reg[2:0], data};
            state <= S2;
          end
          else begin
            shift_reg <= 4'b0;
            state <= S0;
          end
        end
        S2: begin
          if (data) begin
            shift_reg <= {shift_reg[2:0], data};
            state <= S3;
          end
          else begin
            shift_reg <= 4'b0;
            state <= S0;
          end
        end
        S3: begin
          if (data) begin
            shift_reg <= {shift_reg[2:0], data};
            match <= 1'b1;
            state <= S0;
          end
          else begin
            shift_reg <= 4'b0;
            state <= S0;
          end
        end
      endcase
    end
