module binary_counter (
  input clk,
  input reset,
  input count_up,
  input count_down,
  output reg [3:0] count_out
);

  // State definition
  localparam INIT = 2'b00;
  localparam COUNT_UP = 2'b01;
  localparam COUNT_DOWN = 2'b10;
  localparam RESET = 2'b11;

  // State register and next state logic
  reg [1:0] state_reg, state_next;
  always @(posedge clk) begin
    if (reset) begin
      state_reg <= RESET;
    end else begin
      state_reg <= state_next;
    end
  end

  // Output logic
  always @(state_reg or count_out) begin
    case (state_reg)
      INIT: count_out <= 4'b0000;
      COUNT_UP: count_out <= count_out + 1;
      COUNT_DOWN: count_out <= count_out - 1;
      RESET: count_out <= 4'b0000;
    endcase
  end

  // Next state logic
  always @(*) begin
    case (state_reg)
      INIT: begin
        if (count_up) begin
          state_next = COUNT_UP;
        end else if (count_down) begin
          state_next = COUNT_DOWN;
        end else begin
          state_next = INIT;
        end
      end
      COUNT_UP: begin
        if (count_up) begin
          state_next = COUNT_UP;
        end else begin
          state_next = INIT;
        end
      end
      COUNT_DOWN: begin
        if (count_down) begin
          state_next = COUNT_DOWN;
        end else begin
          state_next = INIT;
        end
      end
      RESET: begin
        state_next = RESET;
      end
    endcase
  end

endmodule

