    wire P, G;

    lookahead LA(.p(a^b), .g(a&b), .c_in(c_in), .c(c), .p(P), .g(G));

    assign sum[0] = a[0] ^ b[0] ^ c[0];
    assign sum[1] = a[1] ^ b[1] ^ c[1];
    assign sum[2] = a[2] ^ b[2] ^ c[2];
    assign sum[3] = a[3] ^ b[3] ^ c[3];

    assign c_out = G | (P & c[2]) | (P & P & c[1]) | (P & P & P & c[0]);

endmodule

