module bitwise_select (
  input [3:0] input1,
  input [3:0] input2,
  input [2:0] select,
  output [3:0] out
);

  reg [3:0] temp_out;

  always @(*) begin
    case (select)
      0: temp_out = input1 & input2;
      1: temp_out = input1 | input2;
      2: temp_out = input1 ^ input2;
      default: temp_out = 4'b0;
