module memory_controller (
    input clk50_clk,
    input [25:0] mem32_address,
    input mem32_direction,
    input [3:0] mem32_byte_en,
    input [31:0] mem32_wdata,
    input mem32_request,
    input [31:0] pio_in_port,
    input reset_reset_n,
    output [7:0] mem32_dack_tag,
    output [31:0] mem32_rdata,
    output mem32_rack,
    output [7:0] mem32_rack_tag,
    output [31:0] pio_out_port,
    output sys_clock_clk,
    output sys_reset_reset_n
);

    // Define memory controller states
    parameter IDLE = 2'b00;
    parameter READ = 2'b01;
    parameter WRITE = 2'b10;

    // Define memory device latency
    parameter READ_LATENCY = 5;
    parameter WRITE_LATENCY = 3;

    // Define memory device size and data width
    parameter MEM_SIZE = 32'h1000000;
    parameter DATA_WIDTH = 32;

    // Define memory device signals
    reg [DATA_WIDTH-1:0] memory [0:MEM_SIZE-1];
    reg [DATA_WIDTH-1:0] read_data;
    reg [DATA_WIDTH-1:0] write_data;
    reg [3:0] byte_en;
    reg [31:0] address;
    reg [7:0] tag;
    wire [DATA_WIDTH-1:0] data;
    reg [1:0] state;
    reg [2:0] latency_counter;
    reg read_ack;
    reg write_ack;

    // Define input/output signals
    assign mem32_dack_tag = tag;
    assign mem32_rdata = read_data;
    assign mem32_rack = read_ack;
    assign mem32_rack_tag = tag;
    assign pio_out_port = pio_in_port;
    assign sys_clock_clk = clk50_clk;
    assign sys_reset_reset_n = reset_reset_n;

    // Define state machine
    always @(posedge clk50_clk) begin
        if (!reset_reset_n) begin
            state <= IDLE;
            latency_counter <= 0;
            read_ack <= 0;
            write_ack <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (mem32_request) begin
                        address <= mem32_address;
                        byte_en <= mem32_byte_en;
                        tag <= mem32_tag;
                        if (mem32_direction) begin
                            state <= READ;
                            latency_counter <= READ_LATENCY - 1;
                        end else begin
                            state <= WRITE;
                            latency_counter <= WRITE_LATENCY - 1;
                            write_data <= mem32_wdata;
                        end
                    end
                end
                READ: begin
                    if (latency_counter == 0) begin
                        read_data <= data;
                        read_ack <= 1;
                        state <= IDLE;
                    end else begin
                        read_ack <= 0;
                        latency_counter <= latency_counter - 1;
                    end
                end
                WRITE: begin
                    if (latency_counter == 0) begin
                        memory[address] <= write_data;
                        write_ack <= 1;
                        state <= IDLE;
                    end else begin
                        write_ack <= 0;
                        latency_counter <= latency_counter - 1;
                    end
                end
            endcase
        end
    end

    // Define memory data bus
    assign data = {memory[address+3][31:0], memory[address+2][31:0], memory[address+1][31:0], memory[address][31:0]};

    // Define memory write enable signals
    always @(*) begin
        case (byte_en)
            4'b0001: write_data[7:0] = mem32_wdata[7:0];
            4'b0010: write_data[15:8] = mem32_wdata[15:8];
            4'b0100: write_data[23:16] = mem32_wdata[23:16];
            4'b1000: write_data[31:24] = mem32_wdata[31:24];
            4'b0011: write_data[15:0] = mem32_wdata[15:0];
            4'b1100: write_data[31:16] = mem32_wdata[31:16];
            4'b1111: write_data = mem32_wdata;
            default: write_data = 0;
        endcase
    end

endmodule

