module edge_detection (
    input clk,
    input rst_n,
    input a,
    output reg edge
);

    parameter IDLE = 2'b00;
    parameter RISING_EDGE = 2'b01;
    parameter FALLING_EDGE = 2'b10;

    reg [1:0] state;
    reg prev_a;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            state <= IDLE;
            prev_a <= 1'b0;
            edge <= 1'b0;
        end
        else begin
            case (state)
                IDLE: begin
                    if (a != prev_a) begin
                        if (a == 1'b1)
                            state <= RISING_EDGE;
                        else
                            state <= FALLING_EDGE;
                    end
                    prev_a <= a;
                end
                RISING_EDGE: begin
                    state <= IDLE;
                    edge <= 1'b1;
                end
                FALLING_EDGE: begin
                    state <= IDLE;
                    edge <= 1'b1;
                end
            endcase
        end
    end
endmodule

