module top_module ( 
    input clk, 
    input reset, // Synchronous active-high reset 
    input [7:0] M, // 8-bit multiplicand for Booth's algorithm 
    input [7:0] N, // 8-bit multiplier for Booth's algorithm 
    input [3:0] A, // 4-bit input A for multiplexer 
    input [3:0] B, // 4-bit input B for multiplexer 
    input select, // Select input to choose between multiplication result and input values 
    output [15:0] mult_out, // 16-bit output from Booth's algorithm module 
    output [3:0] mux_out, // 4-bit output from multiplexer module 
    output [19:0] final_out // 20-bit final output from functional module 
);

// Instantiate Booth's algorithm module
booth_mult booth_inst (
    .clk(clk),
    .reset(reset),
    .M(M),
    .N(N),
    .mult_out(mult_out)
);

// Instantiate multiplexer module
mux_4to1 mux_inst (
    .in0(mult_out[3:0]),
    .in1(mult_out[7:4]),
    .in2(A),
    .in3(B),
    .select(select),
    .out(mux_out)
);

// Functional module to produce final output
// Takes in both the output of the Booth's algorithm module and the selected 4-bit value
// Produces a final output by concatenating the two inputs
// Output is 20 bits wide to accommodate the maximum possible output from the Booth's algorithm module (2^16)
// and the maximum possible value of the selected 4-bit input (2^4)
assign final_out = {mux_out, mult_out};

endmodule

// Booth's algorithm module for 8-bit unsigned multiplication
module booth_mult (
    input clk,
    input reset,
    input [7:0] M,
    input [7:0] N,
    output reg [15:0] mult_out
);

reg [7:0] A;
reg [7:0] Q;
reg [2:0] count;

always @(posedge clk) begin
    if (reset) begin
        A <= 8'b0;
        Q <= N;
        count <= 3'b0;
        mult_out <= 16'b0;
    end else begin
        // Booth's algorithm
        if (Q[0] == 1 && A[0] == 0) begin
            A <= A + M;
        end else if (Q[0] == 0 && A[0] == 1) begin
            A <= A - M;
        end
        Q <= {Q[6:0], Q[7]};
        A <= {A[6:0], A[7]};
        count <= count + 1;
        if (count == 3) begin
            mult_out <= {A, Q};
        end
    end
end

endmodule

