        2'b01: out = in1;
        2'b10: out = in2;
        2'b11: out = in3;
    endcase
end

endmodule

module top_module (
    input clk,
    input reset,      // Asynchronous active-high reset
    input [254:0] in, // Input vector for the priority encoder
    input select,     // Select input for choosing between counter and priority encoder
    output [3:0] count, // 4-bit binary count from the counter
    output [7:0] index, // 8-bit binary index from the priority encoder
    output [3:0] out // Final output from the functional module
);

    // Counter module
    reg [3:0] counter;
    always @(posedge clk or negedge reset) begin
        if (reset == 1'b0) begin
            counter <= 4'b0000;
        end else begin
            counter <= counter + 1;
        end
    end
    assign count = counter;

    // Priority encoder module
    wire [7:0] priority_encoder_index;
    priority_encoder pe(
        .in(in),
        .out(priority_encoder_index)
    );
    assign index = priority_encoder_index;

    // Functional module
    wire [3:0] functional_output;
    comparator cmp(
        .a(counter),
        .b(priority_encoder_index),
        .select(select),
        .out(functional_output)
    );
    assign out = functional_output;

    // Control logic module
    always @(select or counter or priority_encoder_index) begin
        if (select == 1'b0 && priority_encoder_index > counter) begin
            cmp.select <= 1'b1;
        end else if (select == 1'b1 && priority_encoder_index > counter) begin
            cmp.select <= 1'b0;
        end else begin
            cmp.select <= select;
        end
    end

endmodule

