    output reg [12:0] back_vram_addr,
    output reg [7:0] back_vram_data
);

reg vram_read;

always @(posedge clk) begin
    // Set default values for all outputs
    back_vram_wr_low = 1;
    back_vram_rd_low = 1'bz;
    back_vram_addr = 13'bzzzzzzzzzzzzz;
    back_vram_data = 8'bzzzzzzzz;
    vram_read = 0;

    if (cpu_rd == 1 && cpu_wr == 0 && cpu_mreq == 0 && cpu_addr == 16'h92c1) begin
        // Set copy_enable register
        copy_enable = cpu_data;
    end
    else if (copy_in_progress == 0 && cpu_rd == 1 && cpu_wr == 0 && cpu_mreq == 0 && cpu_addr >= 16'h8000 && cpu_addr <= 16'h92bf) begin
        // Read from video memory
        back_vram_addr = cpu_addr[12:0];
        vram_read = 1;
    end
    else if (copy_in_progress == 0 && cpu_rd == 0 && cpu_wr == 1 && cpu_mreq == 0 && cpu_addr >= 16'h8000 && cpu_addr <= 16'h92bf) begin
        // Write to video memory
        back_vram_addr = cpu_addr[12:0];
        back_vram_data = cpu_data;
        back_vram_wr_low = 0;
    end
end

assign cpu_data = vram_read ? back_vram_data : 8'bzzzzzzzz;

endmodule

module ERROR_DETECT_4BYTE (
    // Lane Init SM Interface
    input ENABLE_ERROR_DETECT,
    input HARD_ERROR_RESET,

    // Global Logic Interface
    output reg SOFT_ERROR,
    output reg HARD_ERROR,

    // MGT Interface
    input RX_DISP_ERR,
    input TX_K_ERR,
    input RX_NOT_IN_TABLE,
    input RX_BUF_STATUS,
    input TX_BUF_ERR,
    input RX_REALIGN,

    // System Interface
    input USER_CLK
);

reg [31:0] data;
reg [3:0] error_count;

always @(posedge USER_CLK) begin
    if (ENABLE_ERROR_DETECT) begin
        if (HARD_ERROR_RESET) begin
            SOFT_ERROR <= 0;
            HARD_ERROR <= 0;
            error_count <= 0;
        end else begin
            if (RX_DISP_ERR || TX_K_ERR || RX_NOT_IN_TABLE || RX_BUF_STATUS || TX_BUF_ERR || RX_REALIGN) begin
                SOFT_ERROR <= 1;
                error_count <= error_count + 1;
                if (error_count == 15) begin
                    HARD_ERROR <= 1;
                end
            end else begin
                SOFT_ERROR <= 0;
                error_count <= 0;
                HARD_ERROR <= 0;
            end
        end
    end else begin
        SOFT_ERROR <= 0;
        HARD_ERROR <= 0;
        error_count <= 0;
    end
end

