    if (reset) begin
        counter <= 0;
        mux_input <= 0;
    end else if (slowena) begin
        counter <= counter + 1;
        if (counter == 4'b1010) begin
            counter <= 0;
        end
    end
end

always @(select) begin
    case (select)
        2'b00: mux_input <= 2'b00;
        2'b01: mux_input <= 2'b01;
        2'b10: mux_input <= 2'b10;
        2'b11: mux_input <= 2'b01;
    endcase
end

mux4to1 mux (
