module byte_order_reverser (
    input [31:0] in, // 32-bit input to be reversed
    output reg [31:0] out // 32-bit output with reversed byte ordering
);

    reg [7:0] byte0, byte1, byte2, byte3; // Four bytes in the input
    reg [31:0] temp; // Temporary variable for byte reordering

    // Assign each byte to a variable
    assign byte0 = in[7:0];
    assign byte1 = in[15:8];
    assign byte2 = in[23:16];
    assign byte3 = in[31:24];

    // Reorder the bytes using a barrel shifter and a multiplexer
    always @* begin
        case(sel[1:0])
            2'b00: temp = {byte3, byte2, byte1, byte0};
            2'b01: temp = {byte1, byte0, data2, data3};
            2'b10: temp = {data4, data5, byte3, byte2};
            default: temp = 0;
        endcase
    end

    // Assign the output to the reversed byte ordering or the selected 4-bit data
    always @* begin
        case(sel[1:0])
            2'b00: out = temp;
            2'b01: out = {temp[31:16], data1, data0, temp[7:0]};
            2'b10: out = {temp[15:0], data5, data4, temp[23:8]};
            default: out = 0;
        endcase
    end

endmodule

