    input [3:0] data5, // 4-bit input
    output reg [3:0] out // 4-bit output selected based on the select input
);

    // Choose the 4-bit input based on the select input
    always @* begin
        case(sel[1:0])
            2'b00: out = {data1, data0};
            2'b01: out = {data3, data2};
            2'b10: out = {data5, data4};
