module io_buffer(
    input clk,
    input reset,
    inout [15:0] pin,
    output reg [3:0] ledg
);

reg [15:0] pin_in;
reg [15:0] pin_out;
reg [15:0] pin_dir;

always @(posedge clk) begin
    if (reset) begin
        // Set all pins to input mode
        pin_dir <= 16'b0000000000000000;
    end else begin
        // Set pins to input or output mode based on pin_dir
        pin_dir <= pin_dir | ~pin_dir & pin;
    end
end

// Bidirectional I/O buffers
genvar i;
generate
    for (i = 0; i < 16; i = i + 1) begin : iogen
        IOBUF io_ (.IO(pin[i]), .O(pin_out[i]), .I(pin_in[i]), .T(~pin_dir[i]));
    end
endgenerate

always @(posedge clk) begin
    // Output values to pins that are set to output mode
    pin <= pin_dir & pin_out | ~pin_dir & pin;

    // Set LED values
    ledg[0] <= pin_in[0];
    ledg[1] <= pin_in[1];
    ledg[2] <= pin_in[2];
    ledg[3] <= pin_in[3];
end

endmodule

