module barrel_shifter (
    input [15:0] D,
    input [1:0] S,
    input DIRECTION,
    output reg [15:0] Q
);

always @(*) begin
    case (S)
        2'b00: Q = D;
        2'b01: Q = DIRECTION ? {D[14:0], 1'b0} : {1'b0, D[15:1]};
        2'b10: Q = DIRECTION ? {D[13:0], 2'b00} : {2'b00, D[15:2]};
        2'b11: Q = DIRECTION ? {D[11:0], 4'b0000} : {4'b0000, D[15:4]};
    endcase
end

endmodule

