module fifo_64w_64r_512d (
    input rst,
    input wr_clk,
    input rd_clk,
    input [63:0] din,
    input wr_en,
    input rd_en,
    output reg [63:0] dout,
    output reg full,
    output reg empty,
    output reg [8:0] rd_data_count,
    output reg [8:0] wr_data_count
);

    reg [9:0] wr_addr;
    reg [9:0] rd_addr;
    reg [9:0] wr_next_addr;
    reg [9:0] rd_next_addr;

    reg [8:0] data_count;

    reg [63:0] ram [511:0];

    assign full = (data_count == 512);
    assign empty = (data_count == 0);

    always @(posedge wr_clk) begin
        if (rst) begin
            wr_addr <= 0;
            wr_next_addr <= 0;
        end else if (wr_en && !full) begin
            ram[wr_addr] <= din;
            wr_addr <= wr_next_addr;
            wr_next_addr <= wr_next_addr + 1;
            wr_data_count <= wr_data_count + 1;
            data_count <= data_count + 1;
        end
    end

    always @(posedge rd_clk) begin
        if (rst) begin
            rd_addr <= 0;
            rd_next_addr <= 0;
        end else if (rd_en && !empty) begin
            dout <= ram[rd_addr];
            rd_addr <= rd_next_addr;
            rd_next_addr <= rd_next_addr + 1;
            rd_data_count <= rd_data_count + 1;
            data_count <= data_count - 1;
        end
    end

endmodule

module data_format_adapter (
    input clk,
    input reset_n,
    input [31:0] in_data,
    input in_valid,
    output reg in_ready,
    input in_startofpacket,
    input in_endofpacket,
    input in_empty,
    output reg [15:0] out_data,
    output reg out_valid,
    input out_ready,
    output reg out_startofpacket,
    output reg out_endofpacket
);

    reg [3:0] state;
    reg [31:0] in_data_reg;
    reg [15:0] out_data_reg;

    parameter IDLE = 2'b00;
    parameter READ_DATA = 2'b01;
    parameter WAIT_FOR_OUTPUT_READY = 2'b10;
    parameter OUTPUT_DATA = 2'b11;

    always @(posedge clk or negedge reset_n) begin
        if (~reset_n) begin
            state <= IDLE;
            in_ready <= 1'b0;
            out_valid <= 1'b0;
            out_startofpacket <= 1'b0;
            out_endofpacket <= 1'b0;
            in_data_reg <= 0;
            out_data_reg <= 0;
        end else begin
            case (state)
                IDLE: begin
                    in_ready <= 1'b0;
                    out_valid <= 1'b0;
                    out_startofpacket <= 1'b0;
                    out_endofpacket <= 1'b0;
                    if (in_valid) begin
                        in_data_reg <= in_data;
                        out_startofpacket <= in_startofpacket;
                        out_endofpacket <= in_endofpacket;
                        state <= READ_DATA;
                    end
                end
                READ_DATA: begin
                    in_ready <= 1'b1;
                    out_valid <= 1'b0;
                    out_startofpacket <= 1'b0;
                    out_endofpacket <= 1'b0;
                    if (in_valid && in_ready) begin
                        out_data_reg[15:0] <= in_data_reg[31:16];
                        state <= WAIT_FOR_OUTPUT_READY;
                    end
                end
                WAIT_FOR_OUTPUT_READY: begin
                    in_ready <= 1'b0;
                    out_valid <= 1'b1;
                    out_startofpacket <= 1'b0;
                    out_endofpacket <= 1'b0;
                    if (out_ready) begin
                        state <= OUTPUT_DATA;
                    end
                end
                OUTPUT_DATA: begin
                    in_ready <= 1'b0;
                    out_valid <= 1'b1;
                    out_startofpacket <= 1'b0;
                    out_endofpacket <= 1'b0;
                    out_data <= out_data_reg;
                    state <= IDLE;
                end
            endcase
        end
    end

endmodule

