    input [3:0] shift_amt,
    output [15:0] data_out
);

    assign data_out = (shift_amt == 0) ? data_in : (shift_amt < 0) ? {data_in, {-shift_amt{1'b0}}} : (shift_amt > 0) ? {data_in[shift_amt-1:0], {shift_amt{1'b0}}} : 16'b0;

