    end
    else if (ack && ack_syn) begin
        reversed_input = {reg_input[7:0], reg_input[15:8], reg_input[23:16], reg_input[31:24]};
        reg_out = reversed_input;
    end
    else begin
        reg_out = reg_input;
    end
end

always @(posedge ack or posedge ack_syn) begin
    if (ack || ack_syn) begin
        reg_out_syn <= 1'b1;
    end
    else begin
        reg_out_syn <= 1'b0;
    end
end

