module ProgramCounter(input clk, input ce,
                      input [1:0] LoadPC,
                      input GotInterrupt,
                      input [7:0] DIN,
                      input [7:0] T,
                      output reg [15:0] PC, output JumpNoOverflow);
  reg [15:0] NewPC;
  assign JumpNoOverflow = ((PC[8] ^ NewPC[8]) == 0) & LoadPC[0] & LoadPC[1];

  always @(*) begin
    // Load PC Control
    case (LoadPC) 
    0,1: NewPC = PC + {15'b0, (LoadPC[0] & ~GotInterrupt)};
    2:   NewPC = {DIN,T};
    3:   NewPC = PC + {{8{T[7]}},T};
    endcase
  end

  always @(posedge clk)
    if (ce)
      PC <= NewPC;    
endmodule

module top_module (
    input clk,
    input reset, // Synchronous active-high reset
    input [3:0] in, // 4-bit input for the barrel shifter
    input [1:0] shift, // 2-bit control signal for the barrel shifter
    output reg [3:0] out // 4-bit output from the functional module
);

    // Instantiate the twos_complement module
    twos_complement twos_comp(
        .in(in),
        .out(tc_out)
    );

    // Instantiate the barrel_shifter_4bit module
    barrel_shifter_4bit barrel_shifter(
        .in(tc_out),
        .shift(shift),
        .out(bs_out)
    );

    reg [3:0] tc_out; // 2's complement output from twos_complement module
    reg [3:0] bs_out; // Output from barrel_shifter_4bit module

    always @(posedge clk) begin
        if (reset) begin
            // Reset both modules
            tc_out <= 4'b0000;
            bs_out <= 4'b0000;
        end else begin
            // Output the result of the selected shift operation on the two's complement representation of the input
            case (shift)
                2'b00: out <= bs_out; // Logical left shift
                2'b01: out <= bs_out; // Logical right shift
                2'b10: out <= bs_out; // Arithmetic left shift
