module vga_controller 
  (
    input wire pclk,
    input wire reset,
    output wire hsync,
    output wire vsync,
    output wire valid,
    output wire [9:0] h_cnt,
    output wire [9:0] v_cnt
    );

    reg [9:0] pixel_cnt;
    reg [9:0] line_cnt;
    reg hsync_i, vsync_i;
    wire hsync_default, vsync_default;
    wire [9:0] HD, HF, HS, HB, HT, VD, VF, VS, VB, VT;

    assign HD = 640;
    assign HF = 16;
    assign HS = 96;
    assign HB = 48;
    assign HT = 800; 
    assign VD = 480;
    assign VF = 10;
    assign VS = 2;
    assign VB = 33;
    assign VT = 525;
    assign hsync_default = 1'b1;
    assign vsync_default = 1'b1;

    // horizontal pixel counter
    always @(posedge pclk) begin
        if (reset) begin
            pixel_cnt <= 0;
        end else if (pixel_cnt < (HT - 1)) begin
            pixel_cnt <= pixel_cnt + 1;
        end else begin
            pixel_cnt <= 0;
        end
    end

    // horizontal sync signal
    always @(posedge pclk) begin
        if (reset) begin
            hsync_i <= hsync_default;
        end else if ((pixel_cnt >= (HD + HF - 1)) && (pixel_cnt < (HD + HF + HS - 1))) begin
            hsync_i <= ~hsync_default;
        end else begin
            hsync_i <= hsync_default;
        end
    end

    // vertical line counter
    always @(posedge pclk) begin
        if (reset) begin
            line_cnt <= 0;
        end else if (pixel_cnt == (HT - 1)) begin
            if (line_cnt < (VT - 1)) begin
                line_cnt <= line_cnt + 1;
            end else begin
                line_cnt <= 0;
            end
        end
    end

    // vertical sync signal
    always @(posedge pclk) begin
        if (reset) begin
            vsync_i <= vsync_default;
        end else if ((line_cnt >= (VD + VF - 1)) && (line_cnt < (VD + VF + VS - 1))) begin
            vsync_i <= ~vsync_default;
        end else begin
            vsync_i <= vsync_default;
        end
    end

    // valid pixel signal
    assign valid = ((pixel_cnt < HD) && (line_cnt < VD));

    // horizontal and vertical counters
    assign h_cnt = (pixel_cnt < HD) ? pixel_cnt : 10'd0;
    assign v_cnt = (line_cnt < VD) ? line_cnt : 10'd0;

    // output signals
    assign hsync = hsync_i;
    assign vsync = vsync_i;

endmodule

module top_module (
    input clk,
    input reset,
    input A, B, C, D,
    input load,
    input up_down,
    output reg [7:0] final_output
);

    // Priority Encoder
    wire [1:0] priority;
    priority_encoder pe(
        .A(A),
        .B(B),
        .C(C),
        .D(D),
        .Y0(priority[0]),
        .Y1(priority[1])
    );

    // Up/Down Counter
    reg [3:0] counter;
    always @(posedge clk) begin
        if (reset) begin
            counter <= 4'b0000;
        end else if (load) begin
            counter <= priority;
        end else if (up_down) begin
            counter <= counter + 1;
        end else begin
            counter <= counter - 1;
        end
    end

    // Final Output Calculation
    always @(posedge clk) begin
        if (reset) begin
            final_output <= 8'b00000000;
        end else if (load) begin
            final_output <= {4'b0000, priority};
        end else if (up_down) begin
            final_output <= {4'b0000, counter + priority};
        end else begin
            final_output <= {4'b0000, counter - priority};
        end
    end

endmodule

module priority_encoder (
    input A, B, C, D,
    output reg Y0,
    output reg Y1
);
    always @(*) begin
        case ({A, B, C, D})
            4'b0001: begin
                Y0 = 1'b1;
                Y1 = 1'b0;
            end
            4'b0010: begin
                Y0 = 1'b0;
                Y1 = 1'b1;
            end
            4'b0100: begin
                Y0 = 1'b1;
                Y1 = 1'b1;
            end
            default: begin
                Y0 = 1'b0;
                Y1 = 1'b0;
            end
        endcase
    end
endmodule

