module adder_subtractor(
    input [3:0] A,
    input [3:0] B,
    input M,
    output [3:0] S
);

    wire [3:0] B_comp;
    wire [3:0] S_add;
    wire [3:0] S_comp;
    wire C_out;

    // 2's complement conversion block
    assign B_comp = M ? (~B + 1) : B;

    // Full adder 0
    full_adder FA0(
        .A(A[0]),
        .B(B_comp[0]),
        .Cin(1'b0),
        .S(S_add[0]),
        .Cout(C_out)
    );

    // Full adder 1
    full_adder FA1(
        .A(A[1]),
        .B(B_comp[1]),
        .Cin(C_out),
        .S(S_add[1]),
        .Cout(C_out)
    );

    // Full adder 2
    full_adder FA2(
        .A(A[2]),
        .B(B_comp[2]),
        .Cin(C_out),
        .S(S_add[2]),
        .Cout(C_out)
    );

    // Full adder 3
    full_adder FA3(
        .A(A[3]),
        .B(B_comp[3]),
        .Cin(C_out),
        .S(S_add[3]),
        .Cout(C_out)
    );

    // 2's complement conversion block for subtraction mode
    assign S_comp = M ? (~S_add + 1) : S_add;

    // Output
    assign S = M ? S_comp : S_add;

endmodule

module top (
    input clk,
    input cpu_reset,
    input data_in,
    output reg [5:0] data_out
);

  wire builder_pll_fb;
  wire main_locked;

  // Clock buffer
  wire clk_ibuf;
  IBUF ibuf_clk(.I(clk), .O(clk_ibuf));

  wire clk_bufg;
  BUFG bufg_clk(.I(clk_ibuf), .O(clk_bufg));

  // Flip-flops for generating data_out[0] and data_out[1]
  reg fdce_0_out;
  reg fdce_1_out;
  always @(posedge clk_bufg) begin
      fdce_0_out <= data_in;
      fdce_1_out <= fdce_0_out;
  end

  // Phase-locked loop
  PLLE2_ADV #(
      .CLKFBOUT_MULT(4'd12),
      .CLKIN1_PERIOD(10.0),
      .CLKOUT0_DIVIDE(4'd12),
      .CLKOUT0_PHASE(90.0),
      .CLKOUT1_DIVIDE(2'd3),
      .CLKOUT1_PHASE(0.0),
      .CLKOUT2_DIVIDE(3'd6),
      .CLKOUT2_PHASE(90.0),
      .DIVCLK_DIVIDE(1'd1),
      .REF_JITTER1(0.01),
      .STARTUP_WAIT("FALSE")
  ) PLLE2_ADV (
      .CLKFBIN(builder_pll_fb),
      .CLKIN1(clk),
      .RST(cpu_reset),
      .CLKFBOUT(builder_pll_fb),
      .CLKOUT0(main_clkout0),
      .CLKOUT1(main_clkout1),
      .CLKOUT2(main_clkout2),
      .LOCKED(main_locked)
  );

  wire main_clkout0_bufg;
  wire main_clkout1_bufg;
  wire main_clkout2_bufg;

  BUFG bufg_clkout0 (.I(main_clkout0), .O(main_clkout0_bufg));
  BUFG bufg_clkout1 (.I(main_clkout1), .O(main_clkout1_bufg));
  BUFG bufg_clkout2 (.I(main_clkout2), .O(main_clkout2_bufg));

  // Flip-flops for generating data_out[2], data_out[3], data_out[4], and data_out[5]
  reg fdce_pll_0_out;
  reg fdce_pll_1_out;
  reg fdce_pll_2_out;
  reg fdce_pll_3_out;
