module program_counter (
    input clk, reset, inc, load,
    input [15:0] in,
    output reg [15:0] out
);

    // Initialize the program counter to 0
    reg [15:0] counter = 0;

    // Assign the output to the program counter
    assign out = counter;

    // Handle the reset signal
    initial begin
        counter = 0;
        @(posedge clk);
        while (reset) begin
            counter <= 0;
            @(posedge clk);
        end
    end

    // Handle the increment signal
    initial begin
        @(posedge clk);
        while (1) begin
            if (inc) begin
                counter <= counter + 1;
            end
            @(posedge clk);
        end
    end

    // Handle the load signal
    initial begin
        @(posedge clk);
        while (1) begin
            if (load) begin
                counter <= in;
            end
            @(posedge clk);
        end
    end

endmodule

