module mealy_3state_sequence_detection (
  input clk,
  input reset,
  input i,
  output reg o,
  output reg [1:0] state
);

  parameter S0 = 2'b00, S1 = 2'b01, S2 = 2'b10;
  reg [1:0] current_state, next_state;

  always @(posedge clk) begin
    if (reset) begin
      current_state <= S0;
      o <= 1'b0;
    end
    else begin
      current_state <= next_state;
      case (current_state)
        S0: begin
          o <= 1'b0;
          if (i) begin
            next_state <= S1;
          end
          else begin
            next_state <= S0;
          end
        end
        S1: begin
          o <= 1'b0;
          if (i) begin
            next_state <= S1;
          end
          else begin
            next_state <= S2;
          end
        end
        S2: begin
          o <= 1'b1;
          if (i) begin
            next_state <= S0;
          end
          else begin
            next_state <= S0;
          end
        end
        default: begin
          o <= 1'b0;
          next_state <= S0;
        end
      endcase
    end
  end

  always @(*) begin
    state = current_state;
  end

endmodule

module math_op (
    A,
    B,
    C,
    X
);

    input A;
    input B;
    input C;
    output X;

    // Signals
    wire A_lt_B;
    wire A_gt_B;
    wire A_eq_B;
    wire A_times_C;
    wire B_plus_C;
    wire A_and_B;

    // Comparator
    assign A_lt_B = (A < B);
    assign A_gt_B = (A > B);
    assign A_eq_B = (A == B);

    // Operations
    assign A_times_C = A_lt_B ? (A & C) : 1'b0;
    assign B_plus_C = A_gt_B ? (B | C) : 1'b0;
    assign A_and_B = A_eq_B ? (A & B) : 1'b0;

    // Output
    assign X = A_times_C | B_plus_C | A_and_B;

endmodule

