module trapezoidal_integration(
    input [15:0] a,
    input [15:0] dt,
    input enable,
    input rst,
    input clk,
    output [31:0] v,
    output reg busy
    );

    // Internal signals and registers
    wire busy_mul;
    reg en;
    reg [63:0] acum;
    reg [63:0] acum_d;
    wire [31:0] varS;
    reg rest;

    // Output calculation
    assign v = acum[63:32];

    // Booth multiplier
    booth_mult Multi(
        .clk(clk),
        .rst(rest),
        .en(en),
        .A(dt),
        .B(a),
        .busy(busy_mul),
        .R(varS)
    );

    // 64-bit divider
    reg div1_rst;
    reg div_en;
    reg [63:0] div_A;
    localparam div_B = 64'd10000000;
    wire div_busy;
    wire [63:0] div_res;

    div_64 divider (
        .clk(clk), 
        .rst(div1_rst), 
        .init_in(div_en), 
        .A({div_A,32'h00000000}), 
        .B(div_B), 
        .Result(div_res), 
        .busy(div_busy)
    );

    // Module initialization
    initial begin
        rest = 1'b1;
        div1_rst = 1'b1;
        acum = 64'd0;
        acum_d = 64'd0;
        div_A = 64'd0;
    end

    // State machine states
    localparam 
        reset = 5'd0,
        ini = 5'd1,
        mulv = 5'd2,
        check_1 = 5'd3,
        div_1 = 5'd4,
        check_2 = 5'd5,
        afterv = 5'd6;

    // State machine registers
    reg[4:0] state;
    reg[4:0] next_state;

    // State machine logic
    always @(posedge clk) begin
        if (rst) state <= reset;
        else state <= next_state;
    end

    always @(*) begin
        case (state)
            reset: begin
                acum <= 64'd0;
                busy <= 1'd1;
                en <= 1'd0;
                rest <= 1'd1;
                div_A <= 64'd0;
                div1_rst <= 1'b1;
                div_en <= 1'b0;
                next_state <= ini;
            end

            ini: begin
                busy <= 1'd0;
                acum <= acum_d;
                en <= 1'd0;
                rest <= 1'd0;
                div_A <= 64'd0;
                div1_rst <= 1'b0;
                div_en <= 1'b0;
                if (enable) next_state <= mulv;
                else next_state <= ini;
            end

            mulv: begin
                acum <= acum_d;
                busy <= 1'd1;
                en <= 1'd1;
                rest <= 1'd0;
                div_A <= 64'd0;
                div1_rst <= 1'b0;
                div_en <= 1'b0;
                if (busy_mul) next_state <= check_1;
                else next_state <= mulv;
            end

            check_1: begin
                acum <= acum_d;
                busy <= 1'd1;
                en <= 1'd0;
                rest <= 1'd0;
                div_A <= 64'd0;
                div1_rst <= 1'b0;
                div_en <= 1'b0;
                if (busy_mul) next_state <= check_1;
                else next_state <= div_1;
            end

            div_1: begin
                busy <= 1'd1;
                en <= 1'd0;
                rest <= 1'd0;
                if (varS[31]) div_A <= (~varS) + 1;
                else div_A <= varS;
                div1_rst <= 1'b0;
                div_en <= 1'b1;
                if (div_busy) next_state <= check_2;
                else next_state <= div_1;
            end

            check_2: begin
                busy <= 1'd1;
                en <= 1'd0;
                rest <= 1'd0;
                div1_rst <= 1'b0;
                div_en <= 1'b1;
                if (div_busy) next_state <= check_2;
                else next_state <= afterv;
            end

            afterv: begin
                if (clk) begin
                    if (varS == 0) acum <= acum_d;
                    else if (varS[31]) acum <= acum_d + 1 + ~div_res;
                    else acum <= acum_d + div_res;
                end
                else acum <= acum_d;
                busy <= 1'd1;
                rest <= 1'd1;
                en <= 1'd0;
                next_state <= ini;
            end

            default: begin
                acum <= acum_d;
                en <= 1'd0;
                rest <= 1'd1;
                busy <= 1'd0;
                next_state <= ini;
            end
        endcase
    end

    always @(negedge clk) begin
        acum_d <= acum;
    end

endmodule

module barrel_shifter (
    input [7:0] data_in,
    input [1:0] shift_amount,
    input select,
    output [7:0] data_out
);

reg [7:0] stage1_out;
reg [7:0] stage2_out;

always @(*) begin
    case (shift_amount)
        2'b00: stage1_out = data_in;
        2'b01: stage1_out = {data_in[6:0], data_in[7]};
        2'b10: stage1_out = {data_in[1:7], data_in[0]};
        2'b11: stage1_out = {data_in[0], data_in[7:1]};
    endcase
end

always @(posedge clk) begin
    if (select == 1'b0) begin
        stage2_out <= stage1_out << shift_amount;
    end else begin
        stage2_out <= stage1_out >> shift_amount;
    end
end

assign data_out = data_in ^ stage2_out;

endmodule

module ilmb_bram_if_cntlr_0(
  input LMB_Clk,
  input LMB_Rst,
  input [31:0]LMB_ABus,
  input [31:0]LMB_WriteDBus,
  input LMB_AddrStrobe,
  input LMB_ReadStrobe,
  input LMB_WriteStrobe,
  input [3:0]LMB_BE,
  output [31:0]Sl_DBus,
  output Sl_Ready,
  output Sl_Wait,
  output Sl_UE,
  output Sl_CE,
  output BRAM_Rst_A,
  output BRAM_Clk_A,
  output [31:0]BRAM_Addr_A,
  output BRAM_EN_A,
  output [3:0]BRAM_WEN_A,
  output [31:0]BRAM_Dout_A,
  input [31:0]BRAM_Din_A
);

  // LMB interface
  reg [31:0] lmb_mem [0:1023];
  reg [31:0] lmb_addr;
  reg [31:0] lmb_data;
  reg lmb_we;
  reg lmb_ce;
  reg lmb_oe;
  reg lmb_wait;

  // BRAM interface
  reg [31:0] bram_mem [0:1023];
  reg [31:0] bram_addr;
  reg [31:0] bram_data;
  reg bram_we;
  reg bram_ce;
  reg bram_oe;

  // State machine
  reg [1:0] state;
  localparam IDLE = 2'b00;
  localparam LMB_READ = 2'b01;
  localparam LMB_WRITE = 2'b10;
  localparam BRAM_READ = 2'b11;

  // LMB read/write logic
  always @ (posedge LMB_Clk) begin
    if (LMB_Rst) begin
      lmb_addr <= 0;
      lmb_data <= 0;
      lmb_we <= 0;
      lmb_ce <= 0;
      lmb_oe <= 0;
      lmb_wait <= 0;
    end else begin
      case (state)
        IDLE: begin
          lmb_wait <= 0;
          lmb_ce <= 0;
          lmb_oe <= 0;
          if (LMB_ReadStrobe) begin
            lmb_addr <= LMB_ABus;
            state <= LMB_READ;
          end else if (LMB_WriteStrobe) begin
            lmb_addr <= LMB_ABus;
            lmb_data <= LMB_WriteDBus;
            lmb_we <= LMB_WriteStrobe;
            state <= LMB_WRITE;
          end
        end
        LMB_READ: begin
          lmb_ce <= 1;
          lmb_oe <= 1;
          Sl_DBus <= lmb_mem[lmb_addr];
          state <= IDLE;
        end
        LMB_WRITE: begin
          lmb_ce <= 1;
          lmb_oe <= 0;
          lmb_mem[lmb_addr] <= lmb_data;
          state <= IDLE;
        end
      endcase
    end
  end

  // BRAM read/write logic
  always @ (posedge BRAM_Clk_A) begin
    if (BRAM_Rst_A) begin
      bram_addr <= 0;
      bram_data <= 0;
      bram_we <= 0;
      bram_ce <= 0;
      bram_oe <= 0;
    end else begin
      bram_ce <= 0;
      bram_oe <= 0;
      case (state)
        IDLE: begin
          if (BRAM_EN_A) begin
            bram_addr <= BRAM_Addr_A;
            if (BRAM_WEN_A != 4'b0000) begin
              bram_data <= BRAM_Din_A;
              bram_we <= BRAM_WEN_A;
              state <= BRAM_WRITE;
            end else begin
              state <= BRAM_READ;
            end
          end
        end
        BRAM_READ: begin
          bram_ce <= 1;
          bram_oe <= 1;
          BRAM_Dout_A <= bram_mem[bram_addr];
          state <= IDLE;
        end
        BRAM_WRITE: begin
          bram_ce <= 1;
          bram_oe <= 0;
          bram_mem[bram_addr] <= bram_data;
          state <= IDLE;
        end
      endcase
    end
  end

  // LMB wait logic
  always @ (posedge LMB_Clk) begin
    if (LMB_Rst) begin
      lmb_wait <= 0;
    end else begin
      if (state == LMB_READ || state == LMB_WRITE) begin
        lmb_wait <= 1;
      end else begin
        lmb_wait <= 0;
      end
    end
  end

  // LMB error logic
  assign Sl_Ready = 1;
  assign Sl_UE = 0;
  assign Sl_CE = 0;

  // BRAM error logic
  assign BRAM_Rst_A = BRAM_EN_A ? 0 : 1;

  // Output signals
  assign BRAM_Clk_A = LMB_Clk;
  assign BRAM_Addr_A = LMB_ABus;
  assign BRAM_EN_A = LMB_ReadStrobe || LMB_WriteStrobe;
  assign BRAM_WEN_A = LMB_BE;

endmodule

module DisplayController (
    input mclk,
    input [3:0] btn,
    input [7:0] sw,
    output [7:0] led,
    output reg [6:0] seg,
    output reg [3:0] an,
    output dp,
    output [2:1] OutBlue,
    output [2:0] OutGreen,
    output [2:0] OutRed,
    output HS,
    output VS
);

    // Declare variables
    reg [1:0] x_pos = 2'b01;
    reg [1:0] y_pos = 2'b01;
    reg [1:0] x_dir = 2'b00;
    reg [1:0] y_dir = 2'b00;
    reg [3:0] digit = 4'b0000;
    reg [7:0] led_out = 8'b00000000;
    reg [26:0] mclk_counter = 27'b0;

    // Set VGA output to black screen with white square in center
    always @ (posedge mclk) begin
        if ((x_pos == 2'b01 || x_pos == 2'b10) && (y_pos == 2'b01 || y_pos == 2'b10)) begin
            OutBlue <= 3'b000;
            OutGreen <= 3'b000;
            OutRed <= 3'b000;
        end else begin
            OutBlue <= 3'b111;
            OutGreen <= 3'b111;
            OutRed <= 3'b111;
        end
        if (x_pos == 2'b01 || x_pos == 2'b10 || y_pos == 2'b01 || y_pos == 2'b10) begin
            HS <= 1'b0;
            VS <= 1'b0;
        end else begin
            HS <= 1'b1;
            VS <= 1'b1;
        end
    end

    // Move white square on VGA output based on input from push buttons
    always @ (posedge mclk) begin
        if (btn[0] == 1'b1 && x_pos != 2'b00) x_dir <= 2'b10;
        else if (btn[1] == 1'b1 && x_pos != 2'b11) x_dir <= 2'b01;
        else x_dir <= 2'b00;
        if (btn[2] == 1'b1 && y_pos != 2'b00) y_dir <= 2'b10;
        else if (btn[3] == 1'b1 && y_pos != 2'b11) y_dir <= 2'b01;
        else y_dir <= 2'b00;
        if (x_dir == 2'b10) x_pos <= x_pos - 1;
        else if (x_dir == 2'b01) x_pos <= x_pos + 1;
        if (y_dir == 2'b10) y_pos <= y_pos - 1;
        else if (y_dir == 2'b01) y_pos <= y_pos + 1;
    end

    // Cycle through digits on 7-segment display based on input from push buttons
    always @ (posedge mclk) begin
        if (btn[2] == 1'b1) begin
            digit <= digit + 1;
            if (digit == 4'b10000) digit <= 4'b0000;
        end
    end

    // Light up LEDs based on input from switches
    always @ (sw) led_out <= sw;

    // Display the appropriate digit on the 7-segment display
    always @ (posedge mclk) begin
        case (digit)
            4'b0000: seg <= 7'b0111111;
            4'b0001: seg <= 7'b0000110;
            4'b0010: seg <= 7'b1011011;
            4'b0011: seg <= 7'b1001111;
            4'b0100: seg <= 7'b1100110;
            4'b0101: seg <= 7'b1101101;
            4'b0110: seg <= 7'b1111101;
            4'b0111: seg <= 7'b0000111;
            4'b1000: seg <= 7'b1111111;
            4'b1001: seg <= 7'b1101111;
            4'b1010: seg <= 7'b1110111;
            4'b1011: seg <= 7'b1111100;
            4'b1100: seg <= 7'b0111001;
            4'b1101: seg <= 7'b1011110;
            4'b1110: seg <= 7'b1111001;
            4'b1111: seg <= 7'b1110001;
            default: seg <= 7'b0000000;
        endcase
        an <= {~digit[3], ~digit[2], ~digit[1], ~digit[0]};
    end

    // Output signals
    assign led = led_out;
    assign dp = 1'b1;

endmodule

module add_sub_module(
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] sum
);

    wire [15:0] a_low;
    wire [15:0] b_low;
    wire [15:0] sum_low;
    wire carry;

    // Split inputs and outputs into high and low bits
    assign a_low = a[15:0];
    assign b_low = (sub) ? (~b[15:0]) : b[15:0];
    assign sum_low = sum[15:0];

    // Ripple carry adder for low bits
    ripple_adder_16bit adder_low(
        .a(a_low),
        .b(b_low),
        .sum(sum_low),
        .carry(carry)
    );

    // Connect carry-out of low bits to carry-in of high bits
    wire carry_in = carry;

    wire [15:0] a_high;
    wire [15:0] b_high;
    wire [15:0] sum_high;

    // Split inputs and outputs into high and low bits
    assign a_high = a[31:16];
    assign b_high = (sub) ? (~b[31:16]) : b[31:16];
    assign sum_high = sum[31:16];

    // Ripple carry adder for high bits
    ripple_adder_16bit adder_high(
        .a(a_high),
        .b(b_high),
        .sum(sum_high),
        .carry(carry_in)
    );

    // Connect carry-out of high bits to carry-in of output
    assign sum[31] = carry_in;

endmodule

module ripple_adder_16bit(
    input [15:0] a,
    input [15:0] b,
    output [15:0] sum,
    output carry
);

    wire [15:0] sum_temp;
    wire carry_temp;

    // Full adder for least significant bit
    full_adder adder_0(
        .a(a[0]),
        .b(b[0]),
        .carry_in(1'b0),
        .sum(sum_temp[0]),
        .carry_out(carry_temp)
    );

    // Full adder for remaining bits
    genvar i;
    generate
        for (i = 1; i < 16; i = i + 1) begin : adder_loop
            full_adder adder(
                .a(a[i]),
                .b(b[i]),
                .carry_in(carry_temp),
                .sum(sum_temp[i]),
                .carry_out(carry_temp)
            );
        end
    endgenerate

    assign sum = sum_temp;
    assign carry = carry_temp;

endmodule

module full_adder(
    input a,
