module adder_subtractor (
    input [3:0] A,
    input [3:0] B,
    input SUB,
    output [3:0] SUM
);

    wire [3:0] carry;
    wire [3:0] diff;

    full_adder fa0 (
        .a(A[0]),
        .b(B[0] ^ SUB),
        .cin(SUB),
        .sum(SUM[0]),
        .cout(carry[0])
    );

    full_adder fa1 (
        .a(A[1]),
        .b(B[1] ^ SUB),
        .cin(carry[0]),
        .sum(SUM[1]),
        .cout(carry[1])
    );

    full_adder fa2 (
        .a(A[2]),
        .b(B[2] ^ SUB),
        .cin(carry[1]),
        .sum(SUM[2]),
        .cout(carry[2])
    );

    full_adder fa3 (
        .a(A[3]),
        .b(B[3] ^ SUB),
        .cin(carry[2]),
        .sum(SUM[3]),
        .cout(carry[3])
    );

    assign diff = {A[3:0], 1'b0} - {B[3:0], SUB};

    assign SUM = SUB ? diff[3:0] : SUM;

endmodule

