module jtag_uart_interface (
  input clk,
  input fifo_rd,
  input rst_n,
  output fifo_EF,
  output reg [7:0] fifo_rdata,
  output rfifo_full,
  output reg [5:0] rfifo_used
);

  reg [31:0] bytes_left;
  reg fifo_rd_d;
  wire [6:0] rfifo_entries;
  wire new_rom;
  wire [31:0] num_bytes;
  wire safe;

  // Simulated circular FIFO buffer
  always @(posedge clk or negedge rst_n) begin
    if (rst_n == 0) begin
      bytes_left <= 32'h0;
      fifo_rd_d <= 1'b0;
    end
    else begin
      fifo_rd_d <= fifo_rd;
      // Decrement on read
      if (fifo_rd_d) bytes_left <= bytes_left - 1'b1;
      // Catch new contents
      if (new_rom) bytes_left <= num_bytes;
    end
  end

  // Generate flags for full and empty
  assign fifo_EF = bytes_left == 32'b0;
  assign rfifo_full = bytes_left > 7'h40;
  assign rfifo_entries = (rfifo_full) ? 7'h40 : bytes_left;
  assign rfifo_used = rfifo_entries[5:0];

  // Output data from FIFO buffer
  always @(posedge clk or negedge rst_n) begin
    if (rst_n == 0) begin
      fifo_rdata <= 8'h0;
    end
    else begin
      if (fifo_rd_d) fifo_rdata <= {fifo_rdata[6:0], 1'b0};
    end
  end

  // Instantiate JTAG UART DROM module
  jtag_uart_drom_module jtag_uart_drom (
    .clk(clk),
    .incr_addr(fifo_rd_d),
    .new_rom(new_rom),
    .num_bytes(num_bytes),
    .q(fifo_rdata),
    .reset_n(rst_n),
    .safe(safe)
  );

endmodule

