module SPIFSM (
  input Reset_n_i,
  input Clk_i,
  input Start_i,
  input SPI_Transmission_i,
  input [7:0] SPI_Data_i,
  input SPI_FIFOFull_i,
  input SPI_FIFOEmpty_i,
  output Done_o,
  output SPI_Write_o,
  output SPI_ReadNext_o,
  output [7:0] SPI_Data_o,
  output ADT7310CS_n_o
);

  // Define states
  parameter IDLE = 2'b00;
  parameter WRITE = 2'b01;
  parameter READ = 2'b10;

  // Define state register
  reg [1:0] state = IDLE;

  // Define SPI FIFO
  reg [7:0] spi_fifo [7:0];
  reg [2:0] spi_fifo_ptr = 3'b000;

  // Define SPI control signals
  reg spi_write = 1'b0;
  reg spi_read_next = 1'b0;
  reg spi_transmission = 1'b0;
  reg [7:0] spi_data = 8'h00;
  reg adt7310cs_n = 1'b1;

  // Define Done signal
  wire done = (state == IDLE);

  // Write data to SPI FIFO
  always @(posedge Clk_i) begin
    if (spi_write && !SPI_FIFOFull_i) begin
      spi_fifo[spi_fifo_ptr] <= spi_data;
      spi_fifo_ptr <= spi_fifo_ptr + 1;
    end
  end

  // Read data from SPI FIFO
  always @(posedge Clk_i) begin
    if (spi_read_next && !SPI_FIFOEmpty_i) begin
      spi_data <= spi_fifo[spi_fifo_ptr];
      spi_fifo_ptr <= spi_fifo_ptr + 1;
    end
  end

  // FSM
  always @(posedge Clk_i) begin
    if (!Reset_n_i) begin
      state <= IDLE;
      spi_write <= 1'b0;
      spi_read_next <= 1'b0;
      spi_transmission <= 1'b0;
      adt7310cs_n <= 1'b1;
    end
    else begin
      case (state)
        IDLE: begin
          if (Start_i) begin
            state <= WRITE;
          end
        end
        WRITE: begin
          spi_write <= 1'b1;
          spi_transmission <= 1'b1;
          adt7310cs_n <= 1'b0;
          if (SPI_FIFOFull_i) begin
            spi_write <= 1'b0;
            spi_transmission <= 1'b0;
            state <= READ;
          end
        end
        READ: begin
          spi_read_next <= 1'b1;
          spi_transmission <= 1'b1;
          adt7310cs_n <= 1'b0;
          if (SPI_FIFOEmpty_i) begin
            spi_read_next <= 1'b0;
            spi_transmission <= 1'b0;
            adt7310cs_n <= 1'b1;
            state <= IDLE;
          end
        end
      endcase
    end
  end

  // Assign outputs
  assign Done_o = done;
  assign SPI_Write_o = spi_write;
  assign SPI_ReadNext_o = spi_read_next;
  assign SPI_Data_o = spi_data;
  assign ADT7310CS_n_o = adt7310cs_n;

endmodule

