module multiplexer #(parameter N = 8, M = 2) (
    input [N-1:0] A,
    input [N-1:0] B,
    input [N-1:0] C,
    input [M-1:0] S,
    output [N-1:0] Y
);

// Declare a wire to hold the selected input
wire [N-1:0] selected_input;

// Implement the multiplexer using conditional statements
// If S is 0, select A
// If S is 1, select B
// If S is 2, select C
