module Counter_1(
  input         clock,
  input         reset,
  input  [10:0] io_max,
  input  [10:0] io_stride,
  output [10:0] io_out,
  output [10:0] io_next,
  input         io_reset,
  input         io_enable,
  input         io_saturate,
  output        io_done
);
  wire  reg$_clock;
  wire  reg$_reset;
  wire [10:0] reg$_io_in;
  wire [10:0] reg$_io_init;
  wire [10:0] reg$_io_out;
  wire  reg$_io_enable;
  wire  _T_18;
  wire [11:0] count;
  wire [11:0] _GEN_2;
  wire [12:0] _T_20;
  wire [11:0] newval;
  wire [11:0] _GEN_3;
  wire  isMax;
  wire [11:0] _T_21;
  wire [11:0] next;
  wire  _T_23;
  wire [11:0] _GEN_1;
  wire  _T_24;

  // Flip-flop module
  FF_13 reg$ (
    .clock(reg$_clock),
    .reset(reg$_reset),
    .io_in(reg$_io_in),
    .io_init(reg$_io_init),
    .io_out(reg$_io_out),
    .io_enable(reg$_io_enable)
  );

  // Output assignments
  assign io_out = count[10:0];
  assign io_next = next[10:0];
  assign io_done = _T_24;

  // Wire assignments
  assign reg$_clock = clock;
  assign reg$_reset = reset;
  assign reg$_io_in = _GEN_1[10:0];
  assign reg$_io_init = 11'h0;
  assign reg$_io_enable = _T_18;
  assign _T_18 = io_reset | io_enable;
  assign count = {1'h0,reg$_io_out};
  assign _GEN_2 = {{1'd0}, io_stride};
  assign _T_20 = count + _GEN_2;
  assign newval = _T_20[11:0];
  assign _GEN_3 = {{1'd0}, io_max};
  assign isMax = newval >= _GEN_3;
  assign _T_21 = io_saturate ? count : 12'h0;
  assign next = isMax ? _T_21 : newval;
  assign _T_23 = io_reset == 1'h0;
  assign _GEN_1 = _T_23 ? next : 12'h0;
  assign _T_24 = io_enable & isMax;
endmodule

module fifo_c (CLK, RST_N, D_IN, ENQ, DEQ, CLR, D_OUT, EMPTY_N, FULL_N);

    parameter DATA_WIDTH = 153;
    parameter ADDR_WIDTH = 8;
    parameter DEPTH = 2**ADDR_WIDTH;

    input CLK;
    input RST_N;
    input [DATA_WIDTH-1:0] D_IN;
    input ENQ;
    input DEQ;
    input CLR;
    output [DATA_WIDTH-1:0] D_OUT;
    output EMPTY_N;
    output FULL_N;

    wire [ADDR_WIDTH-1:0] wr_ptr;
    wire [ADDR_WIDTH-1:0] rd_ptr;
    wire [DEPTH-1:0] mem;
    wire [DEPTH-1:0] mem_next;
    wire [DATA_WIDTH-1:0] data_out;
    wire [DATA_WIDTH-1:0] data_in;

    assign data_in = ENQ ? D_IN : data_out;
    assign D_OUT = data_out;

    generic_fifo_sc_c fifo_1 (
        .clk(CLK),
        .rst(RST_N),
        .clr(CLR),
        .din(data_in),
        .we(ENQ),
        .dout(data_out),
        .re(DEQ),
        .full_r(FULL_N),
        .empty_r(EMPTY_N),
        .wr_ptr(wr_ptr),
        .rd_ptr(rd_ptr),
        .mem(mem),
        .mem_next(mem_next)
    );

    // Write pointer logic
    reg [ADDR_WIDTH-1:0] wr_ptr_reg;
    always @(posedge CLK or negedge RST_N) begin
        if (!RST_N) begin
            wr_ptr_reg <= 0;
        end else if (ENQ && !FULL_N) begin
            wr_ptr_reg <= wr_ptr;
        end
    end
    assign wr_ptr = wr_ptr_reg;

    // Read pointer logic
    reg [ADDR_WIDTH-1:0] rd_ptr_reg;
    always @(posedge CLK or negedge RST_N) begin
        if (!RST_N) begin
            rd_ptr_reg <= 0;
        end else if (DEQ && !EMPTY_N) begin
            rd_ptr_reg <= rd_ptr;
        end
    end
    assign rd_ptr = rd_ptr_reg;

    // Memory logic
    reg [DEPTH-1:0] mem_reg;
    always @(posedge CLK or negedge RST_N) begin
        if (!RST_N) begin
            mem_reg <= 0;
        end else if (ENQ && !FULL_N) begin
            mem_reg[wr_ptr] <= data_in;
        end else if (DEQ && !EMPTY_N) begin
            mem_reg[rd_ptr] <= 0;
        end
    end
    assign mem = mem_reg;
    assign mem_next = {mem[DEPTH-2:0], mem[DEPTH-1]} | {1'b0, mem[DEPTH-1:1]};

endmodule

