module top_module (
    input [3:0] A,
    input [3:0] B,
    input SUBTRACT,
    output reg [3:0] SUM,
    output reg OVERFLOW,
    output reg EQUAL,
    output reg GREATER_THAN,
    output reg LESS_THAN
);

    wire [3:0] add_sub_out;
    wire [1:0] comp_out;

    adder_subtractor add_sub (
        .A(A),
        .B(B),
        .SUBTRACT(SUBTRACT),
        .OUT(add_sub_out),
        .OVERFLOW(OVERFLOW)
    );

    comparator_2bit comp (
        .A(A),
        .B(B),
        .OUT(comp_out)
    );

    always @* begin
        SUM = add_sub_out;
        EQUAL = (comp_out == 2'b01);
        GREATER_THAN = (comp_out == 2'b10);
        LESS_THAN = (comp_out == 2'b00);
    end

endmodule

module adder_subtractor (
    input [3:0] A,
    input [3:0] B,
    input SUBTRACT,
    output reg [3:0] OUT,
    output reg OVERFLOW
);

    reg [3:0] twos_comp_B;
    reg carry_in;

    assign twos_comp_B = (~B) + 1;

    always @* begin
        if (SUBTRACT) begin
            OUT = A + twos_comp_B + carry_in;
        end else begin
            OUT = A + B + carry_in;
        end

        if (OUT[4]) begin
            OVERFLOW = 1;
        end else begin
            OVERFLOW = 0;
        end
    end

endmodule

