module agnus_diskdma
(
    input clk,
    input clk7_en,
    output dma,
    input dmal,
    input dmas,
    input speed,
    input turbo,
    input [8:0] hpos,
    output wr,
    input [8:1] reg_address_in,
    output [8:1] reg_address_out,
    input [15:0] data_in,
    output reg [20:1] address_out
);

parameter DSKPTH = 9'h020;
parameter DSKPTL = 9'h022;
parameter DSKDAT = 9'h026;
parameter DSKDATR = 9'h008;

wire [20:1] address_outnew;
reg dmaslot;

always @(*) begin
    case(hpos[8:1])
        8'h04: dmaslot = speed;
        8'h06: dmaslot = speed;
        8'h08: dmaslot = speed;
        8'h0A: dmaslot = speed;
        8'h0C: dmaslot = 1;
        8'h0E: dmaslot = 1;
        8'h10: dmaslot = 1;
        default: dmaslot = 0;
    endcase
end

assign dma = dmal & (dmaslot & ~(turbo & speed) & hpos[0] | turbo & speed & ~hpos[0]);
assign wr = ~dmas;

always @(posedge clk) begin
    if(clk7_en) begin
        if(dma || (reg_address_in[8:1] == DSKPTH[8:1]))
            address_out[20:16] <= address_outnew[20:16];
    end
end

always @(posedge clk) begin
    if(clk7_en) begin
        if(dma || (reg_address_in[8:1] == DSKPTL[8:1]))
            address_out[15:1] <= address_outnew[15:1];
    end
end

assign reg_address_out[8:1] = wr ? DSKDATR[8:1] : DSKDAT[8:1];

always @(*) begin
    address_outnew[20:1] = dma ? address_out[20:1] + 1'b1 : {data_in[4:0], data_in[15:1]};
end

endmodule

module red_pitaya_lpf_block
#(
    parameter     SHIFTBITS =     4,
    parameter     SIGNALBITS   = 14,
    parameter     MINBW        = 10
    )
(
    input clk_i,
    input rstn_i  ,
    input [SHIFTBITS:0] shift, 
    input filter_on,
    input highpass,
    input signed  [SIGNALBITS-1:0] signal_i,
    output signed [SIGNALBITS-1:0] signal_o
);

localparam MAXSHIFT = $clog2(125000000/MINBW);

reg signed [SIGNALBITS+MAXSHIFT-1:0] y;
reg signed [SIGNALBITS+MAXSHIFT-1:0] delta;
wire signed [SIGNALBITS+MAXSHIFT-1:0] shifted_delta;
wire signed [SIGNALBITS-1:0] y_out;
wire filter_off;

assign y_out = y[MAXSHIFT+SIGNALBITS-1:MAXSHIFT];
assign shifted_delta = delta<<((shift<MAXSHIFT) ? shift : MAXSHIFT);

always @(posedge clk_i) begin
    if (rstn_i == 1'b0) begin
        y <= {MAXSHIFT+SIGNALBITS{1'b0}};
        delta <= {MAXSHIFT+SIGNALBITS{1'b0}};
    end
    else begin
        delta <= signal_i - y_out;
        y <= y + shifted_delta;
    end
end

assign signal_o = (filter_on == 1'b0) ? signal_i : ((highpass==1'b0) ? y_out : delta);

endmodule

module compare_1
   (comp0,
    v1_reg_0);
  output comp0;
  input [4:0]v1_reg_0;

  wire ms_n_0;
  wire [4:0] m1_CARRY4_CO_UNCONNECTED;
  wire [4:0] m1_CARRY4_O_UNCONNECTED;
  wire [3:1] ms_CARRY4_DI_UNCONNECTED;
  wire [3:0] ms_CARRY4_O_UNCONNECTED;
  wire [3:1] ms_CARRY4_S_UNCONNECTED;
  wire [2:0] m1_CARRY4_CO_UNCONNECTED_lsb;

  // MUXCY primitive
  (* XILINX_LEGACY_PRIM = "(MUXCY,XORCY)" *) 
  (* box_type = "PRIMITIVE" *) 
  MUXCY muxcy_inst
       (.CI(1'b0),
        .DI({1'b0,1'b0}),
        .O(m1_CARRY4_CO_UNCONNECTED[4]),
        .S(v1_reg_0[4]));

  // CARRY4 primitive #1
  (* XILINX_LEGACY_PRIM = "(MUXCY,XORCY)" *) 
  (* box_type = "PRIMITIVE" *) 
  CARRY4 carry4_inst1
       (.CI(muxcy_inst.O),
        .CO({ms_n_0, m1_CARRY4_CO_UNCONNECTED_lsb}),
        .CYINIT(1'b1),
        .DI({1'b0,1'b0,1'b0,1'b0}),
        .O(m1_CARRY4_O_UNCONNECTED[4:0]),
        .S(v1_reg_0[3:0]));

  // CARRY4 primitive #2
  (* XILINX_LEGACY_PRIM = "(MUXCY,XORCY)" *) 
  (* box_type = "PRIMITIVE" *) 
  CARRY4 carry4_inst2
       (.CI(muxcy_inst.O),
        .CO({m1_CARRY4_CO_UNCONNECTED[3:1], comp0}),
        .CYINIT(1'b0),
        .DI({ms_CARRY4_DI_UNCONNECTED[3:1], 1'b0}),
        .O(ms_CARRY4_O_UNCONNECTED[3:0]),
        .S({ms_CARRY4_S_UNCONNECTED[3:1], v1_reg_0[4]}));

  // Connect intermediate wires
  assign m1_CARRY4_CO_UNCONNECTED = {ms_n_0, m1_CARRY4_CO_UNCONNECTED_lsb};
  assign ms_CARRY4_DI_UNCONNECTED = {m1_CARRY4_CO_UNCONNECTED[2:0], 1'b0};
  assign ms_CARRY4_S_UNCONNECTED = {m1_CARRY4_CO_UNCONNECTED[3:1], v1_reg_0[4]};

endmodule

