module memory(
    input wire clk,
    input wire rst,
    input wire [4:0] read1,
    input wire [4:0] read2,
    output reg [31:0] data1,
    output reg [31:0] data2,
    output reg [31:0] mem [0:31],
    input wire regwrite,
    input wire [4:0] wrreg,
    input wire [31:0] wrdata
);

   integer i;

   always @(*) begin
      if (read1 == 5'd0)
         data1 = 32'd0;
      else if ((read1 == wrreg) && regwrite)
         data1 = wrdata;
      else
         data1 = mem[read1][31:0];
   end

   always @(*) begin
      if (read2 == 5'd0)
         data2 = 32'd0;
      else if ((read2 == wrreg) && regwrite)
         data2 = wrdata;
      else
         data2 = mem[read2][31:0];
   end

   always @(posedge clk, negedge rst) begin
      if (!rst) begin
         for (i = 0; i < 32; i=i+1) begin
            mem[i] <= 32'h0;
         end
         #1 mem[2] <= 1;
      end
      else if (regwrite && wrreg != 5'd0) begin
         // write a non $zero register
         mem[wrreg] <= wrdata;
      end
   end
endmodule

module top_module (
    input clk,
    input [99:0] a, b, // 100-bit binary numbers for adder input
    input cin, // Carry-in input for adder
    input slowena, // Enable input for counter pause
    input reset, // Synchronous active-high reset
    output [99:0] out_val, // 100-bit binary output of larger value
    output cout // Carry-out signal from adder
);

// Carry-select adder
wire [99:0] sum1, sum2;
wire cout1, cout2;
ripple_carry_adder RCA1(.a(a), .b(b), .cin(cin), .sum(sum1), .cout(cout1));
ripple_carry_adder RCA2(.a(a), .b(b), .cin(~cin), .sum(sum2), .cout(cout2));
mux2x1 mux_sum(.in0(sum1), .in1(sum2), .sel(cout1), .out(out_val));
mux2x1 mux_cout(.in0(cout1), .in1(cout2), .sel(cout1), .out(cout));

// Decade counter
wire [3:0] count;
johnson_counter jc(.clk(clk), .slowena(slowena), .reset(reset), .count(count));

// Additional functional module
wire [99:0] count_ext = {96'b0, count};
wire is_count_larger = (count_ext > out_val);
mux2x1 mux_larger(.in0(out_val), .in1(count_ext), .sel(is_count_larger), .out(out_val));

endmodule

