module timer #
(
    parameter WIDTH = 64,
    parameter USE_2XCLK = 0,
    parameter S_WIDTH_A = 2
)
(
    input clk,
    input clk2x,
    input resetn,

    // Slave port
    input [S_WIDTH_A-1:0] slave_address,  // Word address
    input [WIDTH-1:0] slave_writedata,
    input slave_read,
    input slave_write,
    input [WIDTH/8-1:0] slave_byteenable,
    output slave_waitrequest,
    output [WIDTH-1:0] slave_readdata,
    output slave_readdatavalid
);

reg [WIDTH-1:0] counter;
reg [WIDTH-1:0] counter2x;

reg clock_sel;

always@(posedge clk or negedge resetn)
  if (!resetn)
    clock_sel <= 1'b0;
  else if (slave_write)
    if (|slave_writedata)
      clock_sel <= 1'b1;
    else
      clock_sel <= 1'b0;

always@(posedge clk or negedge resetn)
  if (!resetn)
    counter <= {WIDTH{1'b0}};
  else if (slave_write)
    counter <= {WIDTH{1'b0}};
  else
    counter <= counter + 2'b01;

always@(posedge clk2x or negedge resetn)
  if (!resetn)
    counter2x <= {WIDTH{1'b0}};
  else if (slave_write)
    counter2x <= {WIDTH{1'b0}};
  else
    counter2x <= counter2x + 2'b01;

assign slave_waitrequest = 1'b0;
assign slave_readdata = (USE_2XCLK && clock_sel) ? counter2x : counter;
assign slave_readdatavalid = slave_read;

endmodule

module i2c_slave(
    input clk, rst, release_bus, enable,
    input [6:0] device_address, device_address_mask,
    input [7:0] s_axis_data_tdata,
    input s_axis_data_tvalid, s_axis_data_tlast,
    output reg s_axis_data_tready,
    output reg [7:0] m_axis_data_tdata,
    output reg m_axis_data_tvalid, m_axis_data_tlast,
    input m_axis_data_tready, scl_i, sda_i,
    output reg scl_o, sda_o,
    output scl_t, sda_t, busy,
    output reg [6:0] bus_address,
    output reg bus_addressed, bus_active
);

localparam [2:0]
    IDLE = 3'b000,
    ADDR = 3'b001,
    READ = 3'b010,
    WRITE = 3'b011,
    STOP = 3'b100;

reg [2:0] state = IDLE;
reg [6:0] address;
reg [7:0] data;
reg [2:0] cnt = 3'b000;
reg [6:0] bit_cnt = 7'd0;
reg [6:0] mask;
reg [6:0] bit;
reg [6:0] bit_t;

assign busy = (state != IDLE);

always @(posedge clk or posedge rst) begin
    if (rst) begin
        state <= IDLE;
        address <= 7'd0;
        data <= 8'd0;
        cnt <= 3'b000;
        bit_cnt <= 7'd0;
        mask <= 7'd0;
        bit <= 7'd0;
        bit_t <= 7'd0;
        s_axis_data_tready <= 1'b0;
        m_axis_data_tvalid <= 1'b0;
        m_axis_data_tlast <= 1'b0;
        scl_o <= 1'b1;
        sda_o <= 1'b1;
        scl_t <= 1'b1;
        sda_t <= 1'b1;
        bus_address <= 7'd0;
        bus_addressed <= 1'b0;
        bus_active <= 1'b0;
    end else begin
        case (state)
            IDLE: begin
                if (scl_i == 1'b0 && sda_i == 1'b0) begin
                    state <= ADDR;
                    cnt <= 3'b000;
                    bit_cnt <= 7'd0;
                    mask <= device_address_mask;
                    bit <= device_address;
                    bit_t <= ~bit;
                end
            end

            ADDR: begin
                scl_t <= 1'b0;
                sda_t <= (bit & mask) ? 1'b1 : 1'b0;
                if (scl_i == 1'b1) begin
                    cnt <= cnt + 1;
                    if (cnt == 3'd7) begin
                        state <= READ;
                    end
                    mask <= mask >> 1;
                    bit <= bit >> 1;
                    bit_t <= ~bit;
                end
            end

            READ: begin
                scl_t <= 1'b1;
                sda_t <= 1'b1;
                if (scl_i == 1'b0) begin
                    if (sda_i == 1'b0) begin
                        address <= sda_i;
                        bus_address <= address;
                        bus_addressed <= 1'b1;
                        bus_active <= 1'b1;
                        state <= WRITE;
                    end
                end
            end

            WRITE: begin
                scl_t <= 1'b1;
                sda_t <= (data & (1 << bit_cnt)) ? 1'b1 : 1'b0;
                if (scl_i == 1'b0) begin
                    if (m_axis_data_tready) begin
                        if (bit_cnt == 7'd7) begin
                            bit_cnt <= 7'd0;
                            if (s_axis_data_tlast) begin
                                m_axis_data_tlast <= 1'b1;
                                state <= STOP;
                            end else begin
                                state <= READ;
                            end
                        end else begin
                            bit_cnt <= bit_cnt + 1;
                        end
                        data <= s_axis_data_tdata;
                        m_axis_data_tvalid <= 1'b1;
                    end else begin
                        m_axis_data_tvalid <= 1'b0;
                    end
                end
            end

            STOP: begin
                scl_t <= 1'b0;
                sda_t <= 1'b0;
                if (scl_i == 1'b1) begin
                    s_axis_data_tready <= 1'b1;
                    bus_active <= 1'b0;
                    state <= IDLE;
                end
            end
        endcase
    end
end

always @(posedge clk or posedge rst) begin
    if (rst) begin
        m_axis_data_tdata <= 8'd0;
    end else begin
        if (state == READ) begin
            if (m_axis_data_tready && bus_active) begin
                m_axis_data_tdata <= 8'd0;
                m_axis_data_tvalid <= 1'b0;
                m_axis_data_tlast <= 1'b0;
                s_axis_data_tready <= 1'b0;
            end else if (bus_active) begin
                m_axis_data_tdata <= data;
                m_axis_data_tvalid <= 1'b1;
                m_axis_data_tlast <= (bit_cnt == 7'd7 && s_axis_data_tlast);
                s_axis_data_tready <= 1'b1;
            end
        end else begin
            m_axis_data_tdata <= 8'd0;
            m_axis_data_tvalid <= 1'b0;
            m_axis_data_tlast <= 1'b0;
            s_axis_data_tready <= 1'b0;
        end
    end
end

always @(posedge clk or posedge rst) begin
    if (rst) begin
        scl_o <= 1'b1;
        sda_o <= 1'b1;
    end else begin
        scl_o <= scl_t;
        sda_o <= sda_t;
    end
end

endmodule

module two_input_gate (
    input A,
    input B,
    output Y
);

    wire not_A, not_B, and_1, and_2, or_1;

    assign not_A = ~A;
    assign not_B = ~B;
    assign and_1 = not_A & B;
    assign and_2 = A & not_B;
    assign or_1 = and_1 | and_2;
    assign Y = ~or_1;

endmodule

module binary_to_gray
  (G, B, clk, rst);

  output [3:0] G;
  input [3:0] B;
  input clk, rst;

  reg [3:0] G_reg;
  reg [3:0] B_reg;

  always @(posedge clk, negedge rst) begin
    if (~rst) begin
      G_reg <= 4'b0;
      B_reg <= 4'b0;
    end else begin
      B_reg <= B;
      G_reg <= {B_reg[3], B_reg[3]^B_reg[2], B_reg[2]^B_reg[1], B_reg[1]^B_reg[0]};
    end
  end

  assign G = G_reg;

endmodule

