module radar_statistics_sim;

    localparam DATA_WIDTH = 32;
    localparam DEL = 5;

    localparam US_RATIO = 100;
    localparam TRIG_RATIO = US_RATIO * 5;
    localparam ACP_RATIO = TRIG_RATIO * 5;
    localparam ARP_RATIO = ACP_RATIO * 5;



    // Inputs
    reg in_clk;
    wire us_clk;
    wire arp;  
    wire acp;    
    wire trig;
    wire arp_pe;  
    wire acp_pe;    
    wire trig_pe;
    wire us_pe;

    // Outputs
    wire [DATA_WIDTH-1:0] ARP_US;
    wire [DATA_WIDTH-1:0] ACP_CNT;
    wire [DATA_WIDTH-1:0] TRIG_US;
    wire CALIBRATED;

    // Instantiate the Unit Under Test (UUT)
    radar_statistics #(DATA_WIDTH) uut(
        .RADAR_ARP_PE(arp_pe),
        .RADAR_ACP_PE(acp_pe),
        .RADAR_TRIG_PE(trig_pe),
        .USEC_PE(us_pe),
        .S_AXIS_ACLK(in_clk),
        .CALIBRATED(CALIBRATED),
        .RADAR_ARP_US(ARP_US),
        .RADAR_ACP_CNT(ACP_CNT),
        .RADAR_TRIG_US(TRIG_US)
    );

    clk_divider #(US_RATIO) c1 (in_clk, us_clk);
    edge_detect c1_ed (
        .async_sig(us_clk),
        .clk(in_clk),
        .rise(us_pe)
    );
    clk_divider #(ARP_RATIO) c2 (in_clk, arp);
    edge_detect c2_ed (
        .async_sig(arp),
        .clk(in_clk),
        .rise(arp_pe)
    );    
    clk_divider #(ACP_RATIO) c3 (in_clk, acp);
    edge_detect c3_ed (
        .async_sig(acp),
        .clk(in_clk),
        .rise(acp_pe)
    );     
    clk_divider #(TRIG_RATIO) c4 (in_clk, trig);
    edge_detect c4_ed (
        .async_sig(trig),
        .clk(in_clk),
        .rise(trig_pe)
    );       

    initial
    begin
        in_clk = 0;
        forever
            #DEL in_clk = ~in_clk;
    end

endmodule

module radar_statistics #(parameter DATA_WIDTH = 32) (
    input wire RADAR_ARP_PE,
    input wire RADAR_ACP_PE,
    input wire RADAR_TRIG_PE,
    input wire USEC_PE,
    input wire S_AXIS_ACLK,
    output wire CALIBRATED,
    output wire [DATA_WIDTH-1:0] RADAR_ARP_US,
    output wire [DATA_WIDTH-1:0] RADAR_ACP_CNT,
    output wire [DATA_WIDTH-1:0] RADAR_TRIG_US
);

    // Internal signals
    reg [DATA_WIDTH-1:0] arp_us_reg;
    reg [DATA_WIDTH-1:0] trig_us_reg;
    reg [DATA_WIDTH-1:0] acp_cnt_reg;
    reg calibrated_reg;
    reg [DATA_WIDTH-1:0] arp_us_out;
    reg [DATA_WIDTH-1:0] trig_us_out;
    reg [DATA_WIDTH-1:0] acp_cnt_out;

    // Constants
    localparam ARP_US_INIT = 1000000;
    localparam TRIG_US_INIT = 1000000;
    localparam ACP_CNT_INIT = 0;
    localparam CALIBRATED_INIT = 0;

    // ARP_US calculation
    always @(posedge S_AXIS_ACLK)
    begin
        if (RADAR_ARP_PE)
        begin
            arp_us_out <= arp_us_reg;
            arp_us_reg <= 0;
        end
        else
        begin
            arp_us_reg <= arp_us_reg + USEC_PE;
            arp_us_out <= arp_us_reg;
        end
    end

    // TRIG_US calculation
    always @(posedge S_AXIS_ACLK)
    begin
        if (RADAR_TRIG_PE)
        begin
            trig_us_out <= trig_us_reg;
            trig_us_reg <= 0;
        end
        else
        begin
            trig_us_reg <= trig_us_reg + USEC_PE;
            trig_us_out <= trig_us_reg;
        end
    end

    // ACP_CNT calculation
    always @(posedge S_AXIS_ACLK)
    begin
        if (RADAR_ACP_PE)
        begin
            acp_cnt_out <= acp_cnt_reg;
            acp_cnt_reg <= 0;
        end
        else if (RADAR_TRIG_PE)
        begin
            acp_cnt_out <= acp_cnt_reg;
        end
        else
        begin
            acp_cnt_reg <= acp_cnt_reg + 1;
            acp_cnt_out <= acp_cnt_reg;
        end
    end

    // CALIBRATED calculation
    always @(posedge S_AXIS_ACLK)
    begin
        if (ARP_US_INIT - arp_us_reg > 1000 && TRIG_US_INIT - trig_us_reg > 1000 && acp_cnt_reg == ACP_CNT_INIT)
        begin
            calibrated_reg <= 1;
        end
        else
        begin
            calibrated_reg <= 0;
        end
    end

    // Output signals
    assign RADAR_ARP_US = arp_us_out;
    assign RADAR_TRIG_US = trig_us_out;
    assign RADAR_ACP_CNT = acp_cnt_out;
    assign CALIBRATED = calibrated_reg;

endmodule

module clk_divider #(parameter RATIO = 1) (
    input wire CLK_IN,
    output reg CLK_OUT
);

    reg [31:0] counter;

    always @(posedge CLK_IN)
    begin
        counter <= counter + 1;
        if (counter >= RATIO)
        begin
            counter <= 0;
            CLK_OUT <= ~CLK_OUT;
        end
    end

endmodule

