module crc_encoder (
  //OUTPUTS
  output reg [CRC_SIZE - 1 : 0] crc_out,   // CRC code after one round of calculation
  //INPUTS
  input                    data_in,    // One bit of data block
  input [CRC_SIZE - 1 : 0] crc_in,     // In cascated mode, this input is the previous calculated CRC code
  input [CRC_SIZE - 1 : 0] crc_poly,   // Generator Polynomial
  input [CRC_SIZE - 2 : 0] crc_poly_size
);

reg [CRC_SIZE - 2 : 0] MASK_REVERSED;
reg [CRC_SIZE - 1 : 0] feedback;
reg [CRC_SIZE - 2 : 0] crc_in_masked;
reg [CRC_SIZE - 2 : 0] crc_poly_size_reversed;

generate
  genvar i;
  for(i = 0; i < CRC_SIZE - 1; i = i + 1)
    begin
      assign crc_poly_size_reversed[i] = crc_poly_size[CRC_SIZE - 2 - i];
      assign MASK_REVERSED[i] = MASK[CRC_SIZE - 2 - i]; 
    end
endgenerate

always @(posedge clk or negedge rst_n) begin
  if(!rst_n) begin
    crc_out <= 0;
  end else begin
    crc_in_masked <= crc_in[CRC_SIZE - 2 : 0] & (~(crc_poly_size_reversed[CRC_SIZE - 2 : 0] & MASK_REVERSED)); 
    feedback <= crc_poly & {CRC_SIZE{crc_in[CRC_SIZE - 1] ^ data_in}};
    crc_out <= {crc_in_masked ^ feedback[CRC_SIZE - 1 : 1], feedback[0]};
  end
end

endmodule

