module top_module (
    input clk,
    input reset, // Synchronous active-high reset
    input [3:0] A, B, C, D, // Four 4-bit inputs for the 4:1 multiplexer
    input [1:0] SEL, // Select inputs for the 4:1 multiplexer and adder
    input [1:0] ADD, // 2-bit input for the adder
    output [1:0] out // 2-bit output from the adder
);

    // Control logic for enabling the multiplexer and adder
    reg enable;
    always @ (posedge clk) begin
        if (reset) begin
            enable <= 0;
        end else begin
            enable <= SEL[0] | SEL[1];
        end
    end

    // 4:1 multiplexer
    wire [3:0] mux_out;
    mux_4to1 mux (
        .in0(A),
