        .in2(C),
        .in3(D),
        .sel(SEL),
        .out(mux_out)
    );

    // 2-bit adder
    wire [1:0] add_out;
    add_2bit add (
        .in1(mux_out),
        .in2(ADD),
        .out(add_out)
    );

    // Output
    assign out = enable ? add_out : 2'b0;

endmodule

