module _80_cycloneiv_alu (A, B, CI, BI, X, Y, CO);
        parameter A_SIGNED = 0;
	parameter B_SIGNED = 0;
	parameter A_WIDTH = 1;
	parameter B_WIDTH = 1;
	parameter Y_WIDTH = 1;

	input [A_WIDTH-1:0] A;
	input [B_WIDTH-1:0] B;
	output [Y_WIDTH-1:0] X, Y;

	input CI, BI;
	output [Y_WIDTH:0] CO;

	// Sign extension and zero extension
	wire [Y_WIDTH-1:0] A_buf, B_buf;
	\$pos #(.A_SIGNED(A_SIGNED), .A_WIDTH(A_WIDTH), .Y_WIDTH(Y_WIDTH)) A_conv (.A(A), .Y(A_buf));
	\$pos #(.A_SIGNED(B_SIGNED), .A_WIDTH(B_WIDTH), .Y_WIDTH(Y_WIDTH)) B_conv (.A(B), .Y(B_buf));

	// XOR operation
	assign X = A_buf ^ B_buf;

	// Arithmetic operation
	wire [Y_WIDTH:0] C = {CO, CI};
	wire [Y_WIDTH-1:0] BB = BI ? ~B_buf : B_buf;
	genvar i;
	cycloneiv_lcell_comb #(.lut_mask(16'b0110_0110_1000_1000), .sum_lutc_input("cin")) carry_start  (.cout(CO[0]), .dataa(BB[0]), .datab(1'b1), .datac(1'b1), .datad(1'b1));
	generate for (i = 1; i < Y_WIDTH; i = i + 1) begin:slice
	    cycloneiv_lcell_comb #(.lut_mask(16'b0101_1010_0101_0000), .sum_lutc_input("cin")) arith_cell (.combout(Y[i]), .cout(CO[i]), .dataa(BB[i]), .datab(1'b1), .datac(1'b1), .datad(1'b1), .cin(C[i]));
	end endgenerate

	// Carry-out bit
	assign CO = CI & CO[Y_WIDTH];

endmodule

module sram_interface(
    input rst,
    input clk,
    input [23:0] addr,
    output reg [15:0] dout,
    output reg rdy,
    output reg sram_clk,
    output reg sram_adv,
    output reg sram_cre,
    output reg sram_ce,
    output reg sram_oe,
    output reg sram_lb,
    output reg sram_ub,
    output reg [23:1] sram_addr,
    output reg sram_we,
    inout [15:0] sram_data
);

reg [2:0] state = 3'b000;

always @(posedge clk) begin
    if (!rst) begin
        state <= 3'b000;
        rdy <= 1'b1;
        dout <= 16'h0000;
        sram_ce <= 1'b0;
        sram_oe <= 1'b0;
    end else begin
        case (state)
            3'b000: begin // idle
                rdy <= 1'b1;
                if (addr[0] == 1'b1) begin
                    sram_addr <= {addr[23:1], 1'b0};
                    sram_ce <= 1'b1;
                    sram_oe <= 1'b1;
                    state <= 3'b001;
                end
            end
            3'b001: begin // read
                sram_ce <= 1'b1;
                sram_oe <= 1'b1;
                dout <= sram_data;
                state <= 3'b010;
            end
            3'b010: begin // output
                sram_ce <= 1'b0;
                sram_oe <= 1'b0;
                state <= 3'b000;
            end
        endcase
    end
end

endmodule

module uart_transmitter (
  input clk,
  input reset_n,
  input begintransfer,
  input clk_en,
  input do_force_break,
  input status_wr_strobe,
  input tx_wr_strobe,
  input [7:0] tx_data,
  input [9:0] baud_divisor,
  output reg tx_overrun,
  output reg tx_ready,
  output reg tx_shift_empty,
  output reg txd
);

  // Internal registers and wires
  reg [9:0] baud_rate_counter;
  reg [9:0] shift_reg;
  reg [7:0] tx_data_reg;
  reg do_shift;
  reg do_load;
  reg shift_done;
  reg [7:0] data_out;
  reg [3:0] bit_counter;
  reg [3:0] data_counter;

  // Assignments
  assign shift_done = ~(|shift_reg);
  assign do_shift = (baud_rate_counter == 0) && ~shift_done && ~do_load;
  assign data_out = tx_data_reg;
  assign tx_ready = shift_done && (tx_data_reg == 0) && (data_counter == 0);

  // Baud rate counter
  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      baud_rate_counter <= 0;
    end else if (clk_en) begin
      if (baud_rate_counter == 0) begin
        baud_rate_counter <= baud_divisor;
      end else begin
        baud_rate_counter <= baud_rate_counter - 1;
      end
    end
  end

  // Shift register
  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      shift_reg <= 0;
    end else if (clk_en) begin
      if (do_load) begin
        shift_reg <= data_out;
      end else if (do_shift) begin
        shift_reg <= {shift_reg[8:0], 1'b0};
      end
    end
  end

  // Load and shift control
  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      do_load <= 0;
    end else if (clk_en) begin
      if (begintransfer && shift_done) begin
        tx_data_reg <= tx_data;
        data_counter <= 8;
        bit_counter <= 0;
        do_load <= 1;
        tx_overrun <= 0;
      end else if (do_shift) begin
        bit_counter <= bit_counter + 1;
        if (bit_counter == 4) begin
          data_counter <= data_counter - 1;
          bit_counter <= 0;
        end
        do_load <= 0;
      end else if (shift_done && (data_counter == 0)) begin
        do_load <= 0;
      end else if (~shift_done && begintransfer) begin
        tx_overrun <= 1;
        do_load <= 0;
      end else begin
        do_load <= 0;
      end
    end
  end

  // Output control
  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      txd <= 1;
    end else if (clk_en) begin
      if (do_force_break) begin
        txd <= 0;
      end else if (shift_done && (tx_data_reg == 0) && (data_counter == 0)) begin
        txd <= 1;
      end else begin
        txd <= shift_reg[0];
      end
    end
  end

  // Shift register empty
  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      tx_shift_empty <= 1;
    end else if (clk_en) begin
      tx_shift_empty <= shift_done && (tx_data_reg == 0) && (data_counter == 0);
    end
  end

  // Load control
  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      data_counter <= 0;
    end else if (clk_en) begin
      if (do_load) begin
        data_counter <= data_counter - 1;
      end
    end
  end

  // Status register clear
  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      tx_overrun <= 0;
    end else if (clk_en) begin
      if (status_wr_strobe) begin
        tx_overrun <= 0;
      end
    end
  end

endmodule

module chatgpt_generate_JC_counter(
