    end
  end

endmodule

module unsigned_divider_restoring (
  input [31:0] div, // dividend
  input [31:0] dor, // divisor
  output reg [31:0] quo, // quotient
  output reg [31:0] rem // remainder
);

  reg [31:0] count;
  reg [31:0] temp_div;
  reg [31:0] temp_quo;
  reg [31:0] temp_rem;
  reg [31:0] temp_dor;
  reg [31:0] temp_diff;

  always @(*) begin
    count = 0;
    temp_div = div;
    temp_quo = 0;
    temp_rem = 0;
    temp_dor = dor;
    temp_diff = 0;

    while (temp_div >= temp_dor) begin
      temp_diff = temp_div - temp_dor;
      if (temp_diff >= 0) begin
        temp_div = temp_diff;
        temp_quo = temp_quo + 1;
      end
      count = count + 1;
      temp_dor = temp_dor << 1;
    end

    quo = temp_quo;
    rem = temp_div;
  end

endmodule

module register_file(
  input rst,
  input clk,
  input write_enable,
  input [REG_WIDTH-1 : 0] rs1_offset,
  input [REG_WIDTH-1 : 0] rs2_offset,
  input [REG_WIDTH-1 : 0] rd_offset,
  input [WIDTH-1 : 0] rd_data_in,
  output [WIDTH-1 : 0] rs1_data_out,
  output [WIDTH-1 : 0] rs2_data_out);

  parameter REG_WIDTH = 5;
  parameter WIDTH = 32;
  parameter STACK_REG = 2;
  parameter STACK_START = 1024; //1k
  localparam REG_COUNT = 1 << REG_WIDTH;
  reg [WIDTH-1 : 0] regs [0 : REG_COUNT-1];

  // Initialize stack pointer on reset
  always @(posedge clk) begin
    if (rst) begin
      regs[STACK_REG] <= STACK_START;
    end
  end

  // Write to register on clock edge
  always @(posedge clk) begin
    if (write_enable && (rd_offset != 0)) begin
      regs[rd_offset] <= rd_data_in;
    end
  end

  // Output data on each cycle
  assign rs1_data_out = regs[rs1_offset];
  assign rs2_data_out = regs[rs2_offset];

endmodule

