module add4bit(C, A, B);
  output [3:0] C;
  input [3:0] A;
  input [3:0] B;

  wire c0, c1, c2;

  // First bit addition
  xor(C[0], A[0], B[0]);
  and(c0, A[0], B[0]);

  // Second bit addition
  xor(C[1], A[1], B[1]);
  xor(c1, A[1], B[1]);
  and(c1, c1, c0);

  // Third bit addition
  xor(C[2], A[2], B[2]);
  xor(c2, A[2], B[2]);
  and(c2, c2, c1);

  // Fourth bit addition
  xor(C[3], A[3], B[3]);
  and(C[3], C[3], c2);

endmodule

module top_module (
    input clk,
    input reset, // Synchronous active-high reset
    input [7:0] d, // 8-bit input for the register
    input select, // Select input to choose between register and counter
    output [11:0] final_output // 12-bit output from the functional module
);

// Instantiate the 8-bit register with active high synchronous reset
reg [7:0] reg_out;
register_module reg_inst (
    .clk(clk),
    .reset(reset),
    .d(d),
    .q(reg_out)
);

// Instantiate the 4-bit binary counter with synchronous reset
reg [3:0] counter_out;
counter_module counter_inst (
    .clk(clk),
    .reset(reset),
    .q(counter_out)
);

// Instantiate the carry-select adder for the functional module
wire [11:0] adder_out;
wire carry_out;
carry_select_adder adder_inst (
    .a(reg_out),
    .b(counter_out),
    .sum(adder_out),
    .carry_out(carry_out)
);

// Select the active module based on the select input
assign final_output = select ? adder_out : {8'd0, counter_out};

endmodule

// 8-bit register with active high synchronous reset
module register_module (
    input clk,
    input reset, // Synchronous active-high reset
    input [7:0] d, // 8-bit input
    output reg [7:0] q // 8-bit output
);

always @(posedge clk) begin
    if (reset) begin
        q <= 8'h34; // Reset to 0x34
    end else begin
        q <= d;
    end
end

