// 4-bit binary counter with synchronous reset
module counter_module (
    input clk,
    input reset, // Synchronous active-high reset
    output reg [3:0] q // 4-bit output
);

always @(posedge clk) begin
    if (reset) begin
        q <= 4'h0; // Reset to 0
    end else begin
        q <= q + 1;
    end
end

endmodule

// Carry-select adder for the functional module
module carry_select_adder (
    input [7:0] a, // 8-bit input A
    input [3:0] b, // 4-bit input B
    output [11:0] sum, // 12-bit output sum
    output carry_out // Carry-out output
);

wire [7:0] a_ext;
assign a_ext = {4'd0, a}; // Extend A to 12 bits

wire [3:0] b_ext;
assign b_ext = {8'd0, b}; // Extend B to 12 bits

wire [11:0] sum_ext;
wire [11:0] sum_msb;
carry_select_adder_12bit adder_inst (
    .a(a_ext),
    .b(b_ext),
    .sum(sum_ext),
    .sum_msb(sum_msb),
    .carry_out(carry_out)
);

assign sum = {sum_msb[11], sum_ext[11:0]}; // Remove the extra bit from the sum

endmodule

