module hilbert_transform (
  input in,
  output out1,
  output out2
);

parameter N = 4; // length of FIR filter

reg [N:0] shift_reg; // shift register for FIR filter
wire [N:0] coeffs; // coefficients of FIR filter
wire [N:0] products; // products of input and coefficients

assign coeffs = {2 * {N+1{1'b0}}}; // initialize coefficients to zero

// calculate coefficients
genvar i;
generate
  for (i = -N; i <= N; i = i + 1) begin
    if (i == 0) begin
      assign coeffs[N] = 1'b0;
    end else if (i % 2 == 0) begin
      assign coeffs[N+i] = 1'b0;
    end else begin
      assign coeffs[N+i] = 2 * $sin((i * $pi) / 2) / (i * $pi);
    end
  end
endgenerate

// multiply input by coefficients
genvar j;
generate
  for (j = 0; j <= N; j = j + 1) begin
    assign products[j] = in * coeffs[j];
  end
endgenerate

// shift register for FIR filter
always @(posedge clk) begin
  shift_reg <= {in, shift_reg[N:1]};
end

// output signals
assign out1 = products[N/2]; // output signal shifted by N/2
assign out2 = products[N/2 + 1]; // output signal shifted by N/2 + 1

endmodule

