module Booth_Multiplier (
    input Rst,
    input Clk,
    input Ld,
    input signed [(N-1):0] M,
    input signed [(N-1):0] R,
    output Valid,
    output signed [(2*N-1):0] P
);

reg [(2*N-1):0] P_reg;
wire [(2*N-1):0] P_wire;
wire [(2*N-1):0] P_neg;
reg [(N+1):0] A;
reg [(N+1):0] S;
reg [(N+1):0] P_neg_reg;
reg [(N+1):0] P_neg_reg_old;
reg [(N+1):0] R_shift;
reg [(N+1):0] R_shift_old;
reg [(N+1):0] R_shift_reg;
reg [(N+1):0] R_shift_reg_old;
reg [(N+1):0] R_neg;
reg [(N+1):0] R_neg_old;
reg [(N+1):0] R_neg_reg;
reg [(N+1):0] R_neg_reg_old;
reg [(N+1):0] M_reg;
reg [(N+1):0] M_reg_old;
reg [(N+1):0] S_reg;
reg [(N+1):0] S_reg_old;
reg [(N+1):0] A_reg;
reg [(N+1):0] A_reg_old;
reg Valid_reg;

assign P = P_wire;

// Booth's algorithm
always @(*) begin
    P_neg = -P_reg;
    P_wire = (A[N+1] == 1) ? P_neg : P_reg;
end

// Register for P
always @(posedge Clk) begin
    if (Rst == 1) begin
        P_reg <= 0;
    end else if (Valid_reg == 0 && Valid == 1) begin
        P_reg <= P_wire;
    end
end

// Register for M
always @(posedge Clk) begin
    if (Rst == 1) begin
        M_reg <= 0;
    end else if (Ld == 1) begin
        M_reg <= {1'b0, M};
    end
end

// Register for R
always @(posedge Clk) begin
    if (Rst == 1) begin
        R_neg_reg <= 0;
        R_shift_reg <= 0;
        R_reg <= 0;
    end else if (Ld == 1) begin
        R_neg_reg <= {1'b0, -R};
        R_shift_reg <= {1'b0, R, 1'b0};
        R_reg <= {1'b0, R};
    end
end

// Register for A
always @(posedge Clk) begin
    if (Rst == 1) begin
        A_reg <= 0;
    end else if (Ld == 1) begin
        A_reg <= {1'b0, R};
    end else if (Valid_reg == 0 && Valid == 1) begin
        A_reg <= A;
    end
end

// Register for S
always @(posedge Clk) begin
    if (Rst == 1) begin
        S_reg <= 0;
    end else if (Ld == 1) begin
        S_reg <= {1'b0, M};
    end else if (Valid_reg == 0 && Valid == 1) begin
        S_reg <= S;
    end
end

// Register for P_neg
always @(posedge Clk) begin
    if (Rst == 1) begin
        P_neg_reg <= 0;
    end else if (Valid_reg == 0 && Valid == 1) begin
        P_neg_reg <= P_neg_reg_old;
    end
end

// Register for R_shift
always @(posedge Clk) begin
    if (Rst == 1) begin
        R_shift_reg <= 0;
    end else if (Valid_reg == 0 && Valid == 1) begin
        R_shift_reg <= R_shift_reg_old;
    end
end

// Register for R_neg
always @(posedge Clk) begin
    if (Rst == 1) begin
        R_neg_reg <= 0;
    end else if (Valid_reg == 0 && Valid == 1) begin
        R_neg_reg <= R_neg_reg_old;
    end
end

// Valid signal
always @(posedge Clk) begin
    if (Rst == 1) begin
        Valid_reg <= 0;
    end else if (Valid_reg == 0 && Valid == 1) begin
        Valid_reg <= 1;
    end
end

// Booth's algorithm
always @(*) begin
    R_shift = {R_shift[N+1], R_shift[N:1]};
    R_neg = {R_neg[N+1], -R_shift[N]};
    A = A + R_neg;
    S = S + R_shift;
    if (A[0] == 1) begin
        A = A + R;
        P_neg_reg_old = P_neg_reg;
        P_neg_reg = P_neg_reg + S;
    end else begin
        P_neg_reg_old = P_neg_reg;
        P_neg_reg = P_neg_reg + {1'b0, S};
    end
end

// Output signals
assign Valid = Valid_reg;
assign P_wire = (P_neg_reg[N+1] == 1) ? -P_neg_reg : P_neg_reg;

endmodule

module ram (
    address,
    byteena,
    clock,
    data,
    rden,
    wren,
    q
);

    input [9:0] address;
    input [3:0] byteena;
    input clock;
    input [31:0] data;
    input rden;
    input wren;
    output [31:0] q;

    wire [31:0] sub_wire0;
    wire [31:0] q_reg;
    assign q = q_reg;

    altsyncram altsyncram_component (
        .address_a(address),
        .byteena_a(byteena),
        .clock0(clock),
        .data_a(data),
        .wren_a(wren),
        .rden_a(rden),
        .q_a(sub_wire0),
        .aclr0(1'b0),
        .aclr1(1'b0),
        .address_b(1'b1),
        .addressstall_a(1'b0),
        .addressstall_b(1'b0),
        .byteena_b(1'b1),
        .clock1(1'b1),
        .clocken0(1'b1),
        .clocken1(1'b1),
        .clocken2(1'b1),
        .clocken3(1'b1),
        .data_b(1'b1),
        .eccstatus(),
        .q_b(),
        .rden_b(1'b1),
        .wren_b(1'b0)
    );

    // implement byteena
    reg [31:0] data_reg;
    always @(posedge clock) begin
        if (wren) begin
            data_reg[31:0] <= sub_wire0[31:0];
            case(byteena)
                4'b0001: data_reg[7:0] <= data[7:0];
                4'b0010: data_reg[15:8] <= data[15:8];
                4'b0100: data_reg[23:16] <= data[23:16];
                4'b1000: data_reg[31:24] <= data[31:24];
                4'b0011: data_reg[15:0] <= data[15:0];
                4'b0110: data_reg[23:8] <= data[23:8];
                4'b1100: data_reg[31:16] <= data[31:16];
                4'b1111: data_reg[31:0] <= data[31:0];
            endcase
        end
    end

    // implement q
    always @(posedge clock) begin
        if (rden) begin
            case(byteena)
                4'b0001: q_reg[7:0] <= sub_wire0[7:0];
                4'b0010: q_reg[15:8] <= sub_wire0[15:8];
                4'b0100: q_reg[23:16] <= sub_wire0[23:16];
                4'b1000: q_reg[31:24] <= sub_wire0[31:24];
                4'b0011: q_reg[15:0] <= sub_wire0[15:0];
                4'b0110: q_reg[23:8] <= sub_wire0[23:8];
                4'b1100: q_reg[31:16] <= sub_wire0[31:16];
                4'b1111: q_reg[31:0] <= sub_wire0[31:0];
            endcase
        end
    end

endmodule

module rw_manager_lfsr72(
    clk, 
    nrst, 
    ena, 
    word
);

    input clk;
    input nrst;
    input ena;
    output reg [71:0] word;

    always @(posedge clk or negedge nrst) begin
        if(~nrst) begin
            word <= 72'hAAF0F0AA55F0F0AA55;
        end
        else if(ena) begin
            word[71] <= word[0] ^ word[7] ^ word[48] ^ word[54];
            word[70:66] <= word[71:67];
            word[65] <= word[66] ^ word[1] ^ word[8] ^ word[54];
            word[64:25] <= word[65:26];
            word[24] <= word[25] ^ word[18] ^ word[1] ^ word[7];
            word[23:19] <= word[24:20];
            word[18] <= word[19] ^ word[12] ^ word[1] ^ word[7];
            word[17:0] <= word[18:1];
        end
    end

endmodule

module serial_interface(wren, rden, reset, din, clk, sclr, baud, dout);

input wren, rden, reset, clk, sclr;
input [7:0] din;
output baud;
output [7:0] dout;

reg [7:0] control, dout;
reg [9:0] shift_out;
reg wr_baud, rd_baud, wr_fifo, rd_fifo, wr_control;
reg ld_shift, stop, count, finish, rd_shift, bittime;
reg [3:0] bittimer, bitcounter;
reg [1:0] nstate, pstate;

parameter PERIOD = 8'h1A;

wire [7:0] to_shift, dout_baud;
wire [9:0] shift;
wire baud, full, empty;

`define period 	3'b000
`define TXreg 		3'b001 
`define control 	3'b011
`define WAIT		2'b00
`define SHIFT1		2'b01
`define SHIFT2 	2'b10
`define TXFULL		control[0]
`define TXDONE		control[1]

baudgen #(.PERIOD(PERIOD)) baud1(
	.wren		(wr_baud), 
	.rden		(rd_baud), 
	.reset	(reset), 
	.din		(din), 
	.clk		(clk), 
	.stop		(stop), 
	.baud		(baud), 
	.dout		(dout_baud)
);

fifo fifo1(
  .clk 		(clk),
  .rst		(reset),
  .din		(din),
  .wr_en		(wr_fifo),
  .rd_en		(rd_fifo),
  .dout		(to_shift),
  .full		(full),
  .empty		(empty)
);

// assign shift_in
assign shift = ({1'b1, to_shift, 1'b0});
assign txout = shift_out[0];
// shift register
always @(posedge clk or posedge reset) begin
	if(reset)
		shift_out <= 10'b1111111111;
	else begin
		if (rd_shift)begin
			//txout = shift_out[0];
			shift_out <= {1'b1, shift_out[9:1]};
		end
		if (ld_shift)
			shift_out <= shift;
	end
end


// control register
always @(posedge clk or posedge reset) begin
	if(reset) begin
		control[7:0] = 8'b00000001;
	end
	else begin
		`TXFULL = full;
		if(finish)
			`TXDONE = 1;
		if(wr_control)
			`TXDONE = 0;
	end
end

// address mux logic
always @* begin
	wr_baud = 0;
	wr_fifo = 0; wr_control = 0;
	case(addr)
		`period: begin
			if(wren)
				wr_baud = 1;
			end
		`TXreg: begin
			if(wren)
				wr_fifo = 1;
			end
		`control: begin
			if(wren)
				wr_control = 1;
			end
	endcase
end

// out mux
always @* begin
	rd_baud = 0;
	dout = 8'b00000000;
	case(addr)
		`period: begin
			if(rden)
				rd_baud = 1;
				dout = dout_baud;
			end
		`control: begin
			if(rden)
				dout = control;
			end
	endcase
end

// bittimer
always @(posedge baud or posedge reset) begin
	if(reset)
		bittimer <= 4'b0000;
	else begin
		if(bittime)
			bittimer <= bittimer + 1;
	end
end

// bitcounter
always @(posedge clk or posedge reset) begin
	if(reset)begin
		bitcounter <= 4'b0000;
		end
	else begin
	if(count)
		bitcounter <= bitcounter + 1;
	if(finish)
		bitcounter <= 4'b0000;
	end
end

// set state during startup.
always @(posedge clk or posedge reset) begin
     if (reset)
    	  pstate <= `WAIT;
	  else
		  pstate <= nstate;
end

// fsm
always @* begin
	rd_fifo = 0; ld_shift = 0; 
	stop = 0; count = 0; finish = 0;
	bittime = 0; rd_shift = 0;
	nstate = pstate;
	case (pstate)
	  `WAIT:  begin
			stop = 1;
			if(~empty) begin
				stop = 0;
				rd_fifo = 1;
				ld_shift = 1;
				nstate = `SHIFT1;
				end
			end
	  `SHIFT1: begin
			if(bitcounter == 4'b1010) begin 
				nstate = `WAIT;
				finish = 1;
				end
			else begin
				if(baud)
					nstate = `SHIFT2;
					bittime = 1;
				end
			end
	  `SHIFT2: begin
			bittime = 1;
			if(~baud & (bittimer == 4'b0000)) begin
				count = 1;
				rd_shift = 1;
				nstate = `SHIFT1;
				end
			end 
	endcase 		 
end


endmodule

module gray_code_converter (
    input [3:0] data_in,
    output reg [3:0] gray_out
);

    assign gray_out[0] = data_in[0];
    assign gray_out[1] = data_in[0] ^ data_in[1];
    assign gray_out[2] = data_in[1] ^ data_in[2];
    assign gray_out[3] = data_in[2] ^ data_in[3];

endmodule

