wire [OW:0] converted_data;
wire converted_startofpacket;
wire converted_endofpacket;
wire [EOW:0] converted_empty;
wire converted_valid;
reg [IW:0] data;
reg startofpacket;
reg endofpacket;
reg [EIW:0] empty;
reg valid;

// Internal Modules
altera_up_YCrCb_to_RGB_converter YCrCb_to_RGB (
    // Inputs
    .clk(clk),
    .clk_en(transfer_data),
    .reset(reset),
    .Y(data[7:0]),
    .Cr(data[23:16]),
    .Cb(data[15:8]),
    .stream_in_startofpacket(startofpacket),
    .stream_in_endofpacket(endofpacket),
    .stream_in_empty(empty),
    .stream_in_valid(valid),
    // Outputs
    .R(converted_data[23:16]),
    .G(converted_data[15:8]),
    .B(converted_data[7:0]),
    .stream_out_startofpacket(converted_startofpacket),
    .stream_out_endofpacket(converted_endofpacket),
    .stream_out_empty(converted_empty),
    .stream_out_valid(converted_valid)
);

// Sequential Logic
always @(posedge clk) begin
    if (reset) begin
        stream_out_data <= 'h0;
        stream_out_startofpacket <= 1'b0;
        stream_out_endofpacket <= 1'b0;
        stream_out_empty <= 2'h0;
        stream_out_valid <= 1'b0;
    end else if (transfer_data) begin
        stream_out_data <= converted_data;
        stream_out_startofpacket <= converted_startofpacket;
        stream_out_endofpacket <= converted_endofpacket;
        stream_out_empty <= converted_empty;
        stream_out_valid <= converted_valid;
    end
end

always @(posedge clk) begin
    if (reset) begin
        data <= 'h0;
        startofpacket <= 1'b0;
        endofpacket <= 1'b0;
        empty <= 'h0;
        valid <= 1'b0;
    end else if (stream_in_ready) begin
        data <= stream_in_data;
        startofpacket <= stream_in_startofpacket;
        endofpacket <= stream_in_endofpacket;
        empty <= stream_in_empty;
        valid <= stream_in_valid;
    end else if (transfer_data) begin
        data <= 'b0;
        startofpacket <= 1'b0;
        endofpacket <= 1'b0;
        empty <= 'h0;
        valid <= 1'b0;
    end
end

// Combinational Logic
assign stream_in_ready = stream_in_valid & (~valid | transfer_data);
assign transfer_data = ~stream_out_valid | (stream_out_ready & stream_out_valid);

endmodule

module a25_alu (

    i_a_in,
    i_b_in,
    i_barrel_shift_carry,
    i_status_bits_carry,
    i_function, 
    o_out,
    o_flags
);

/************************* IO Declarations *********************/
input       [31:0]          i_a_in;
input       [31:0]          i_b_in;
input                       i_barrel_shift_carry;
input                       i_status_bits_carry;
input       [8:0]           i_function;

output      [31:0]          o_out;
output      [3:0]           o_flags;

/*********************** Signal Declarations *******************/
wire     [31:0]         a;
wire     [31:0]         b;
wire     [31:0]         b_not;
wire     [31:0]         and_out;
wire     [31:0]         or_out;
wire     [31:0]         xor_out;
wire     [31:0]         sign_ex8_out;
wire     [31:0]         sign_ex_16_out;
wire     [31:0]         zero_ex8_out;
wire     [31:0]         zero_ex_16_out;
wire     [32:0]         fadder_out;
wire                    swap_sel;
wire                    not_sel;
wire     [1:0]          cin_sel;
wire                    cout_sel;
wire     [3:0]          out_sel;
wire                    carry_in;
wire                    carry_out;
wire                    overflow_out;
wire                    fadder_carry_out;

assign  { swap_sel, not_sel, cin_sel, cout_sel, out_sel } = i_function;


assign a     = (swap_sel ) ? i_b_in : i_a_in ;

// ========================================================
// B Select
// ========================================================
assign b     = (swap_sel ) ? i_a_in : i_b_in ;

// ========================================================
// Not Select
// ========================================================
assign b_not     = (not_sel ) ? ~b : b ;

// ========================================================
// Cin Select
// ========================================================
assign carry_in  = (cin_sel==2'd0 ) ? 1'd0                   :
                   (cin_sel==2'd1 ) ? 1'd1                   :
                                      i_status_bits_carry    ;  // add with carry

// ========================================================
// Cout Select
// ========================================================
assign carry_out = (cout_sel==1'd0 ) ? fadder_carry_out     :
                                       i_barrel_shift_carry ;

// For non-addition/subtractions that incorporate a shift 
// operation, C is set to the last bit
// shifted out of the value by the shifter.


// ========================================================
// Overflow out
// ========================================================
// Only assert the overflow flag when using the adder
assign  overflow_out    = out_sel == 4'd1 &&
                            // overflow if adding two positive numbers and get a negative number
                          ( (!a[31] && !b_not[31] && fadder_out[31]) ||
                            // or adding two negative numbers and get a positive number
                            (a[31] && b_not[31] && !fadder_out[31])     );


// ========================================================
// ALU Operations
// ========================================================


assign fadder_out       = { 1'd0,a} + {1'd0,b_not} + {32'd0,carry_in};


assign fadder_carry_out = fadder_out[32];
assign and_out          = a & b_not;
assign or_out           = a | b_not;
assign xor_out          = a ^ b_not;
assign zero_ex8_out     = {24'd0,  b_not[7:0]};
assign zero_ex_16_out   = {16'd0,  b_not[15:0]};
assign sign_ex8_out     = {{24{b_not[7]}},  b_not[7:0]};
assign sign_ex_16_out   = {{16{b_not[15]}}, b_not[15:0]};

// ========================================================
// Out Select
// ========================================================
assign o_out = out_sel == 4'd0 ? b_not            : 
               out_sel == 4'd1 ? fadder_out[31:0] : 
               out_sel == 4'd2 ? zero_ex_16_out   :
               out_sel == 4'd3 ? zero_ex8_out     :
               out_sel == 4'd4 ? sign_ex_16_out   :
               out_sel == 4'd5 ? sign_ex8_out     :
               out_sel == 4'd6 ? xor_out          :
               out_sel == 4'd7 ? or_out           :
                                 and_out          ;

assign o_flags       = {  o_out[31],      // negative
                         |o_out == 1'd0,  // zero
                         carry_out,       // carry
                         overflow_out     // overflow
                         };


endmodule

module priority_encoder (
    input [3:0] A,
    input [3:0] B,
    input [3:0] C,
    input [3:0] D,
    output reg Y0,
    output reg Y1
);

reg [3:0] A_reg, B_reg, C_reg, D_reg;
reg [1:0] stage;

always @(posedge clk) begin
    case (stage)
        0: begin
            A_reg <= A;
            B_reg <= B;
            C_reg <= C;
            D_reg <= D;
            Y0 <= 0;
            Y1 <= 0;
            stage <= 1;
        end
        1: begin
            if (A_reg[3] || B_reg[3]) begin
                Y0 <= 1;
                Y1 <= 0;
            end else if (C_reg[3] || D_reg[3]) begin
                Y0 <= 0;
                Y1 <= 1;
            end else begin
                Y0 <= 0;
                Y1 <= 0;
            end
            stage <= 2;
        end
        2: begin
            if (A_reg[2] || B_reg[2]) begin
                Y0 <= 1;
                Y1 <= 0;
            end else if (C_reg[2] || D_reg[2]) begin
                Y0 <= 0;
                Y1 <= 1;
            end else begin
                Y0 <= 0;
                Y1 <= 0;
            end
            stage <= 3;
        end
        3: begin
            if (A_reg[1] || B_reg[1]) begin
                Y0 <= 1;
                Y1 <= 0;
            end else if (C_reg[1] || D_reg[1]) begin
                Y0 <= 0;
                Y1 <= 1;
            end else begin
                Y0 <= 0;
                Y1 <= 0;
            end
            stage <= 4;
        end
        4: begin
            if (A_reg[0] || B_reg[0]) begin
                Y0 <= 1;
                Y1 <= 0;
            end else if (C_reg[0] || D_reg[0]) begin
                Y0 <= 0;
                Y1 <= 1;
            end else begin
                Y0 <= 0;
                Y1 <= 0;
            end
            stage <= 0;
        end
    endcase
end

endmodule

module adder_4bit (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

wire [3:0] sum;
wire c1, c2, c3;

assign sum = A + B + Cin;
assign Cout = c3;

assign c1 = (A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin);
assign c2 = (A[1] & B[1]) | (A[1] & c1) | (B[1] & c1);
assign c3 = (A[2] & B[2]) | (A[2] & c2) | (B[2] & c2) | (A[3] & B[3]) | (A[3] & c2) | (B[3] & c2);

assign S = sum;

endmodule

module mixer_compressor (
    input wire clk,
    input wire sound_enable,
    input wire [4:0] i0,
    input wire [4:0] i1,
    input wire [4:0] i2,
    input wire [4:0] i3,
    input wire [4:0] i4,
    input wire [4:0] i5,
