);

    wire [7:0] inv_in;
    wire [7:0] and_out;

    // Inverter implementation
    assign inv_in = ~in;

    // AND gate implementation
    and_gate_mux_not and_gate (
        .a(1'b1),
        .b(1'b1),
        .in(in),
        .out(and_out)
    );

    // Priority encoder implementation
    assign pos = $priority_encoder(and_out, inv_in);

endmodule

module final_module (
    input a,
    input b,
    input [7:0] in,
    output [2:0] pos
);

    wire and_out;
    wire [2:0] priority_pos;

    // AND gate and NOT gate implementation
    and_gate_mux_not and_gate (
        .a(a),
        .b(b),
        .in(in),
        .out(and_out)
    );

    // Priority encoder implementation
    priority_encoder priority_enc (
        .in(in),
        .pos(priority_pos)
    );

    // Output assignment
    always @* begin
        if (and_out == 1'b1) begin
            pos = priority_pos;
        end else begin
            pos = 3'b0;
        end
    end

endmodule

module checksum (
  input [n-1:0] data_in,
  output reg [m-1:0] checksum_out
);

parameter n = 8; // number of data signals
parameter m = 8; // width of the checksum value

// Compute the checksum
reg [m-1:0] sum;
integer i;
always @(*) begin
  sum = 0;
  for (i = 0; i < n; i = i + 1) begin
    sum = sum + data_in[i];
  end
  checksum_out = sum % (1 << m);
end

// Check the checksum
reg [m-1:0] sum_check;
always @(*) begin
  sum_check = 0;
  for (i = 0; i < n; i = i + 1) begin
    sum_check = sum_check + data_in[i];
  end
  sum_check = sum_check + checksum_out;
  if (sum_check == (1 << m) - 1) begin
    $display("Checksum is valid");
  end else begin
    $display("Checksum is invalid");
  end
end

endmodule

