module sky130_fd_sc_hs__u_df_p_no_pg (
    buf_Q,
    D_delayed,
    CLK_delayed,
    notifier,
    VPWR,
    VGND
);

    // Module ports
    output buf_Q     ;
    input  D_delayed ;
    input  CLK_delayed;
    output notifier  ;
    input  VPWR      ;
    input  VGND      ;

    // Local signals
    reg buf_Q_reg;
    reg notifier_reg;

    // Generate buf_Q using D flip-flop
    always @(posedge CLK_delayed or negedge notifier) begin
        if (~notifier) begin
            buf_Q_reg <= 1'b0;
        end else begin
            buf_Q_reg <= D_delayed;
        end
    end
    assign buf_Q = buf_Q_reg;

    // Generate notifier using register
    always @(posedge VPWR or negedge buf_Q) begin
        if (VPWR && ~buf_Q) begin
            notifier_reg <= 1'b1;
        end else begin
            notifier_reg <= 1'b0;
        end
    end
    assign notifier = notifier_reg;

endmodule

