module seqPortAlloc(
    numFlit_in,
    availPortVector_in,
    ppv,
    allocatedPortVector,
    availPortVector_out,
    numFlit_out
    );

    input [`PC_INDEX_WIDTH-1:0] numFlit_in;
    input [`NUM_PORT-2:0] availPortVector_in, ppv;
    output [`NUM_PORT-2:0] allocatedPortVector, availPortVector_out;
    output [`PC_INDEX_WIDTH-1:0] numFlit_out;  

    wire [`PC_INDEX_WIDTH-1:0] numFlit [`NUM_PORT-1:0];
    wire [`NUM_PORT-2:0] allocatedPortVector_st1, availPortVector_out_st1;
    wire [`NUM_PORT-2:0] allocatedPortVector_st2, availPortVector_out_st2;

    assign numFlit[0] = numFlit_in;

    genvar i;
    generate   
    // Stage 1: allocate the productive port
    for (i=0; i<`NUM_PORT-1; i=i+1) begin : productiveAlloc   
        assign allocatedPortVector_st1[i] = ppv[i] && availPortVector_in[i] && (numFlit[i] <= `NUM_PORT-1);
        assign numFlit[i+1] = numFlit[i] + allocatedPortVector_st1[i]; 
        assign availPortVector_out_st1[i] =  availPortVector_in[i] && ~allocatedPortVector_st1[i];
    end
    endgenerate

    // Stage 2: deflection: find the first available port in the order of N, E, S, W
    assign allocatedPortVector_st2[0] = availPortVector_out_st1[0];
    assign allocatedPortVector_st2[1] = availPortVector_out_st1[1] && ~availPortVector_out_st1[0];
    assign allocatedPortVector_st2[2] = availPortVector_out_st1[2] && ~availPortVector_out_st1[1] && ~availPortVector_out_st1[0];
    assign allocatedPortVector_st2[3] = availPortVector_out_st1[3] && ~availPortVector_out_st1[2] && ~availPortVector_out_st1[1] && ~availPortVector_out_st1[0];
    assign availPortVector_out_st2 [0] = 1'b0;
    assign availPortVector_out_st2 [1] = availPortVector_out_st1[0] && availPortVector_out_st1[1];
    assign availPortVector_out_st2 [2] = |availPortVector_out_st1[1:0] && availPortVector_out_st1[2];
    assign availPortVector_out_st2 [3] = |availPortVector_out_st1[2:0] && availPortVector_out_st1[3];


    wire get_port_st1;
    assign get_port_st1 = |allocatedPortVector_st1;
    assign allocatedPortVector = (~|ppv || get_port_st1) ? allocatedPortVector_st1 : allocatedPortVector_st2;
    assign availPortVector_out = (~|ppv || get_port_st1) ? availPortVector_out_st1 : availPortVector_out_st2;          
    assign numFlit_out = (~|ppv || get_port_st1) ? numFlit[`NUM_PORT-1] : numFlit[`NUM_PORT-1] + 1'b1;

endmodule

module kcpsm3_registers(
    counter,
    waveforms,
    interrupt_event,
    interrupt_ack,
    clk
);

output reg [7:0] counter;
output reg [7:0] waveforms;
input interrupt_event;
output reg interrupt_ack;
input clk;

reg interrupt;

// Signals used to connect KCPSM3 to program ROM and I/O logic
wire [9:0] address;
wire [17:0] instruction;
wire [7:0] port_id;
wire [7:0] out_port;
wire [7:0] in_port;
wire write_strobe;
wire read_strobe;
wire reset;

// Inserting KCPSM3 and the program memory
kcpsm3 processor(
    .address(address),
    .instruction(instruction),
    .port_id(port_id),
    .write_strobe(write_strobe),
    .out_port(out_port),
    .read_strobe(read_strobe),
    .in_port(in_port),
    .interrupt(interrupt),
    .interrupt_ack(interrupt_ack),
    .reset(reset),
    .clk(clk)
);

// Unused inputs on processor
assign in_port = 8'b00000000;
assign reset = 1'b0;

// Adding the output registers to the processor
always @(posedge clk) begin
    // waveform register at address 02
    if (port_id[1] && write_strobe) begin
        waveforms <= out_port;
    end

    // Interrupt Counter register at address 04
    if (port_id[2] && write_strobe) begin
        counter <= out_port;
    end
end

// Adding the interrupt input
// Note that the initial value of interrupt (low) is defined at signal declaration.
always @(posedge clk) begin
    if (interrupt_ack) begin
        interrupt <= 1'b0;
    end else if (interrupt_event) begin
        interrupt <= 1'b1;
    end else begin
        interrupt <= interrupt;
    end
end

endmodule

module fifo_buffer(
  input  dclock,
  input  rst,
  input  [1:0] w_wfifo_ready,
  input  [7:0] w_wfifo_data,
  input  [4:0] w_wfifo_size,
  output [7:0] r_wfifo_data,
  output [0:0] r_wfifo_ready,
  output [1:0] r_wfifo_activate,
  output [4:0] r_wfifo_count
);

reg [1:0] r_wfifo_activate;
reg [4:0] r_wfifo_count;
reg [7:0] r_wfifo_data;
reg [0:0] r_wfifo_ready;
reg [0:0] r_wfifo_strobe;

always @ (posedge dclock) begin
  if (rst) begin
    r_wfifo_activate  <=  0;
    r_wfifo_strobe    <=  0;
    r_wfifo_data      <=  0;
    r_wfifo_count     <=  0;
    r_wfifo_ready     <=  1;
  end
  else begin
    //Strobes
    r_wfifo_strobe    <=  0;
    if (r_wfifo_strobe) begin
        r_wfifo_data  <=  r_wfifo_data + 1;
    end

    if ((w_wfifo_ready > 0) && (r_wfifo_activate == 0)) begin
      r_wfifo_count   <=  0;
      if (w_wfifo_ready[0]) begin
        r_wfifo_activate[0] <=  1;
      end
      else begin
        r_wfifo_activate[1] <=  1;
      end
    end
    else if (r_wfifo_activate > 0) begin
      if (r_wfifo_count < w_wfifo_size) begin
        r_wfifo_count <=  r_wfifo_count + 1;
        r_wfifo_strobe<=  1;
      end
      else begin
        r_wfifo_activate  <=  0;
      end
    end
  end
end

always @ (posedge dclock) begin
  if (rst) begin
    r_wfifo_ready     <=  1;
  end
  else begin
    if (r_wfifo_ready == 1) begin
      if (r_wfifo_activate[0] == 1) begin
        r_wfifo_data  <=  w_wfifo_data;
        r_wfifo_ready <=  0;
        r_wfifo_activate[0] <=  0;
      end
      else if (r_wfifo_activate[1] == 1) begin
        r_wfifo_data  <=  w_wfifo_data;
        r_wfifo_ready <=  0;
        r_wfifo_activate[1] <=  0;
      end
    end
  end
end

assign r_wfifo_count = r_wfifo_activate + (w_wfifo_size - r_wfifo_count);

endmodule

module calculator(
    input wire clk,
    input wire rst,
    input wire [1:0] op,
    input wire [7:0] a,
    input wire [7:0] b,
    output reg [7:0] result,
    output reg overflow,
    output reg zero,
    output reg carry
    );

    reg [15:0] temp_result;
    reg [7:0] temp_a;
    reg [7:0] temp_b;
    reg [7:0] temp_quotient;
    reg [7:0] temp_remainder;

    always @(posedge clk) begin
        if (rst) begin
            result <= 8'b0;
            overflow <= 1'b0;
            zero <= 1'b0;
            carry <= 1'b0;
        end else begin
            temp_a <= a;
            temp_b <= b;
            case (op)
                2'b00: begin // addition
                    temp_result <= temp_a + temp_b;
                    carry <= (temp_result > 8'hFF);
                    result <= temp_result[7:0];
                    overflow <= (temp_result[8] ^ temp_result[7]);
                    zero <= (result == 8'b0);
                end
                2'b01: begin // subtraction
                    temp_result <= temp_a - temp_b;
                    carry <= (temp_a >= temp_b);
                    result <= temp_result[7:0];
                    overflow <= (temp_result[8] ^ temp_result[7]);
                    zero <= (result == 8'b0);
                end
                2'b10: begin // multiplication
                    temp_result <= temp_a * temp_b;
                    result <= temp_result[7:0];
                    overflow <= (temp_result[15:8] != 8'b0);
                    zero <= (result == 8'b0);
                    carry <= (temp_result[15:8] == 8'b0) && (temp_result[7:0] == 8'b0);
                end
                2'b11: begin // division
                    if (temp_b == 8'b0) begin
                        result <= 8'b0;
                        overflow <= 1'b1;
                        zero <= 1'b0;
                        carry <= 1'b0;
                    end else begin
                        temp_quotient <= temp_a / temp_b;
                        temp_remainder <= temp_a % temp_b;
                        result <= temp_quotient;
                        overflow <= (temp_quotient > 8'hFF);
                        zero <= (result == 8'b0);
                        carry <= (temp_remainder == 8'b0);
                    end
                end
            endcase
        end
    end
endmodule

module adder(
  input [7:0] A,
  input [7:0] B,
  input C,
  output reg [7:0] sum
);

  always @(*)
  begin
    // add the inputs
    sum = A + B;

    // truncate if necessary
    if(sum > 8'b11111111)
      sum = sum[7:0];

    // convert to two's complement if required
    if(C)
      sum = ~sum + 1;
  end

endmodule

module binary_to_gray_converter (
    input [3:0] A,
    output [3:0] G,
    input clk,
    input rst
);

    reg [3:0] G_reg;
    reg [3:0] A_reg;

    always @(posedge clk) begin
        if (rst) begin
            G_reg <= 4'b0000;
            A_reg <= 4'b0000;
        end else begin
            A_reg <= A;
            G_reg <= {A_reg[3], A_reg[3]^A_reg[2], A_reg[2]^A_reg[1], A_reg[1]^A_reg[0]};
        end
    end

    assign G = G_reg;

endmodule

module top_module(
    input wire a, b, c, // Inputs to the multiplexer
    input wire [15:0] in, // Input to the splitter
    output wire [7:0] out_hi, // Upper byte of the splitter output
    output wire [7:0] out_lo, // Lower byte of the splitter output
    output wire [23:0] final_out // Final 24-bit output from the functional module
);

// Multiplexer
wire w, x, y, z;
assign w = a;
assign x = b;
assign y = b;
assign z = c;

// Splitter
wire [7:0] in_hi, in_lo;
assign in_hi = in[15:8];
assign in_lo = in[7:0];

// Functional module
wire [23:0] sum;
assign sum = {8'b0, w} + {8'b0, x} + {8'b0, y} + {8'b0, z} + {8'b0, in_hi} + {8'b0, in_lo};

// Output assignments
assign out_hi = in_hi;
assign out_lo = in_lo;
assign final_out = sum;

endmodule

module bcd_counter (
    input clk,
    input reset,   // Synchronous active-high reset
    output reg [15:0] count, // 16-bit BCD counter output
    output [3:0] ena // Enable signals for BCD counter
);

    always @(posedge clk) begin
        if (reset) begin
            count <= 0;
            ena <= 4'b0001;
        end
        else begin
            if (count == 9999) begin
                count <= 0;
                ena <= 4'b0001;
            end
            else begin
                count <= count + 1;
                ena <= {ena[2:0], ~ena[0]};
            end
        end
    end

endmodule

