// Carry select adder module
module carry_select_adder(
    input [15:0] a,
    input [15:0] b,
    input cin,
    output [15:0] sum
);

    wire [15:0] p;
    wire [15:0] g;
    wire [15:0] c;

    assign p = a + b;
    assign g = a & b;
    assign c[0] = cin;

    genvar i;
    generate
        for (i = 1; i < 16; i = i + 1) begin : carry_select_loop
            assign c[i] = (g[i-1] | (p[i-1] & c[i-1]));
        end
    endgenerate

    assign sum = {c[15], p[15:0]};

endmodule

module communication_protocol #(
    parameter clk_freq = 100000000, // system clock frequency
    parameter divisor = 596 // divisor for generating 16-bit enable signal
) (
    input sys_clk, // system clock signal
    input sys_rst, // system reset signal
    input [13:0] csr_a, // CSR address input
    input csr_we, // CSR write enable signal
    input [31:0] csr_di, // CSR data input
    input rx, // data receive input
    output reg rx_irq, // data receive interrupt output
    output reg [31:0] csr_do // CSR data output
);

// enable16 generator
reg [15:0] enable16_counter;
wire enable16;
assign enable16 = (enable16_counter == 16'd0);

always @(posedge sys_clk) begin
    if (sys_rst) begin
        enable16_counter <= divisor - 1;
    end else begin
        enable16_counter <= enable16_counter - 16'd1;
        if (enable16) begin
            enable16_counter <= divisor - 1;
        end
    end
end

// Synchronize rx
reg rx1;
reg rx2;
always @(posedge sys_clk) begin
    rx1 <= rx;
    rx2 <= rx1;
end

// RX Logic
reg rx_busy;
reg [3:0] rx_count16;
reg [3:0] rx_bitcount;
reg [12:0] rx_reg;
reg [12:0] rx_data;

always @(posedge sys_clk) begin
    if (sys_rst) begin
        rx_irq <= 1'b0;
        rx_busy <= 1'b0;
        rx_count16 <= 4'd0;
        rx_bitcount <= 4'd0;
    end else begin
        rx_irq <= 1'b0;

        if (enable16) begin
            if (~rx_busy) begin // look for start bit
                if (rx2 == 1'b0) begin // start bit found
                    rx_busy <= 1'b1;
                    rx_count16 <= 4'd13;
                    rx_bitcount <= 4'd0;
                end
            end else begin
                rx_count16 <= rx_count16 + 4'd1;

                if (rx_count16 == 4'd0) begin // sample
                    rx_bitcount <= rx_bitcount + 4'd1;

                    if (rx_bitcount == 4'd0) begin // verify start bit
                        if (rx2 == 1'b1)
                            rx_busy <= 1'b0;
                    end else if (rx_bitcount == 4'd14) begin
                        rx_busy <= 1'b0;
                        rx_data <= rx_reg;
                        rx_irq <= 1'b1;
                    end else
                        rx_reg <= {rx_reg[11:0], rx2};
                end
            end
        end
    end
end

// CSR interface
wire csr_selected = csr_a[13:10] == 4'h0;

always @(posedge sys_clk) begin
    if (sys_rst) begin
        csr_do <= 32'd0;
    end else begin
        if (csr_we) begin // write to CSR
            if (csr_selected) begin
                csr_do <= csr_di;
            end
        end else begin // read from CSR
            if (csr_selected) begin
                csr_do <= rx_data;
            end
        end
    end
end

endmodule

module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    output Cout,
    output [3:0] S
);

    wire c_in;
    wire [3:0] sum;

    sky130_fd_sc_hdll__xor3_2 xor1 (.X(sum[0]), .A(A[0]), .B(B[0]), .C(c_in));
    sky130_fd_sc_hdll__xor3_2 xor2 (.X(sum[1]), .A(A[1]), .B(B[1]), .C(sum[0]));
    sky130_fd_sc_hdll__xor3_2 xor3 (.X(sum[2]), .A(A[2]), .B(B[2]), .C(sum[1]));
    sky130_fd_sc_hdll__xor3_2 xor4 (.X(sum[3]), .A(A[3]), .B(B[3]), .C(sum[2]));

    sky130_fd_sc_hdll__and2_2 and1 (.Z(c_in), .A(A[0]), .B(B[0]));
    sky130_fd_sc_hdll__and2_2 and2 (.Z(sum[0]), .A(A[0]), .B(B[0]));
    sky130_fd_sc_hdll__and2_2 and3 (.Z(sum[1]), .A(A[1]), .B(B[1]));
    sky130_fd_sc_hdll__and2_2 and4 (.Z(sum[2]), .A(A[2]), .B(B[2]));
    sky130_fd_sc_hdll__and2_2 and5 (.Z(sum[3]), .A(A[3]), .B(B[3]));

    sky130_fd_sc_hdll__or2_2 or1 (.Z(Cout), .A(c_in), .B(sum[0]));
    sky130_fd_sc_hdll__or2_2 or2 (.Z(sum[1]), .A(and1.Z), .B(and2.Z));
    sky130_fd_sc_hdll__or2_2 or3 (.Z(sum[2]), .A(and3.Z), .B(and4.Z));
    sky130_fd_sc_hdll__or2_2 or4 (.Z(sum[3]), .A(and5.Z), .B(xor4.X));

    assign S = sum;

endmodule

module dna_reader
(
  input  wire        aclk,
  input  wire        aresetn,

  output wire [56:0] dna_data
);

  localparam integer CNTR_WIDTH = 16;
  localparam integer DATA_WIDTH = 57;

  reg int_enbl_reg, int_enbl_next;
  reg int_read_reg, int_read_next;
  reg int_shift_reg, int_shift_next;
  reg [CNTR_WIDTH-1:0] int_cntr_reg, int_cntr_next;
  reg [DATA_WIDTH-1:0] int_data_reg, int_data_next;

  wire int_comp_wire, int_data_wire;

  assign int_comp_wire = int_cntr_reg < 64*DATA_WIDTH;

  DNA_PORT dna_0 (
    .DOUT(int_data_wire),
    .CLK(int_cntr_reg[5]),
    .DIN(1'b0),
    .READ(int_read_reg),
    .SHIFT(int_shift_reg)
  );

  always @(posedge aclk)
  begin
    if(~aresetn)
    begin
      int_enbl_reg <= 1'b0;
      int_read_reg <= 1'b0;
      int_shift_reg <= 1'b0;
      int_cntr_reg <= {(CNTR_WIDTH){1'b0}};
      int_data_reg <= {(DATA_WIDTH){1'b0}};
    end
    else
    begin
      int_enbl_reg <= int_enbl_next;
      int_read_reg <= int_read_next;
      int_shift_reg <= int_shift_next;
      int_cntr_reg <= int_cntr_next;
      int_data_reg <= int_data_next;
    end
  end

  always @*
  begin
    int_enbl_next = int_enbl_reg;
    int_read_next = int_read_reg;
    int_shift_next = int_shift_reg;
    int_cntr_next = int_cntr_reg;
    int_data_next = int_data_reg;

    if(~int_enbl_reg & int_comp_wire)
    begin
      int_enbl_next = 1'b1;
      int_read_next = 1'b1;
    end

    if(int_enbl_reg)
    begin
      int_cntr_next = int_cntr_reg + 1'b1;
    end

    if(&int_cntr_reg[5:0])
    begin
      int_read_next = 1'b0;
      int_shift_next = 1'b1;
      int_data_next = {int_data_reg[DATA_WIDTH-2:0], int_data_wire};
    end

    if(~int_comp_wire)
    begin
      int_enbl_next = 1'b0;
      int_shift_next = 1'b0;
    end
  end

  assign dna_data = int_data_reg;

endmodule

