module shift_reg_comp (
    input clk,
    input reset,
    input load,
    input enable,
    input [3:0] data_in,
    output reg out
);

reg [3:0] data_out;
wire comp_out;

// Shift register module
always @(posedge clk, negedge reset) begin
    if (reset == 0) begin
        data_out <= 4'b0000;
    end else if (load == 1) begin
        data_out <= data_in;
    end else if (enable == 1) begin
        data_out <= {data_out[2:0], data_out[3]};
    end
end

// Comparator module
comparator comp(.in1(data_out), .in2(2'b11), .out(comp_out));

// Output enable
always @(posedge clk, negedge reset) begin
    if (reset == 0) begin
        out <= 0;
    end else if (enable == 1) begin
        out <= comp_out;
    end
end

