wire [15:0] c;

generate
    genvar i;
    for (i = 0; i < 16; i = i + 1) begin: gen
        assign p[i] = a[i] ^ b[i];
        assign g[i] = a[i] & b[i];
        assign c[i] = i == 0 ? g[i] : g[i] | (p[i] & c[i-1]);
    end
endgenerate

assign sum = a + b + c;
assign carry_out = c[15];

endmodule

