module sqrt_16bit (
    input [15:0] a,
    input ctrl,
    output reg [15:0] b
);

    reg [15:0] x;
    reg [3:0] i;
    reg [15:0] temp;

    always @(*) begin
        x = 8'd0;
        i = 4'd0;
        temp = 16'd0;
        while (i < 4'd8) begin
            temp = (x << 1) + (1 << (7 - i));
            if (temp * temp <= a) begin
                x = temp;
            end
            i = i + 1;
        end
        if (ctrl == 1) begin
            if (((x + 1) * (x + 1) - a) <= (a - x * x)) begin
                b = x + 1;
            end else begin
                b = x;
            end
        end else begin
            b = x;
        end
    end

endmodule

module top_module (
    input clk,
    input areset,  // async active-high reset to zero
    input [255:0] in,
    input [7:0] sel,
    input load,
    input ena,
    output reg [3:0] q
);

    // 256-to-1 multiplexer using a decoder and a 2-to-1 multiplexer
    wire [7:0] dec_sel;
    wire [255:0] mux_out;
    decoder dec (
        .in(sel),
        .out(dec_sel)
    );
    genvar i;
    generate
        for (i = 0; i < 256; i = i + 1) begin : mux_gen
            assign mux_out[i] = (dec_sel == i) ? in[i] : 0;
        end
    endgenerate
    wire [7:0] mux_sel;
    mux2to1 mux (
        .in0(mux_out[(2 * mux_sel) +: 2]),
        .in1(mux_out[(2 * mux_sel) +: 2] >> 2),
        .sel(sel[1:0]),
        .out(q)
    );

    // 4-bit right shift register with asynchronous reset, synchronous load, and enable
    reg [3:0] shift_reg;
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            shift_reg <= 4'b0;
        end else if (load) begin
            shift_reg <= in[3:0];
        end else if (ena) begin
            shift_reg <= {shift_reg[2:0], 1'b0};
        end
    end

endmodule

