module decoder (
    input [7:0] in,
    output reg [255:0] out
);
    integer i;
    always @(*) begin
        for (i = 0; i < 256; i = i + 1) begin
            out[i] = (i == in) ? 1'b1 : 1'b0;
        end
    end
endmodule

// 2-to-1 multiplexer module
module mux2to1 (
    input [1:0] sel,
    input [3:0] in0,
    input [3:0] in1,
    output reg [3:0] out
);
    always @(*) begin
        if (sel == 2'b00) begin
            out = in0;
        end else if (sel == 2'b01) begin
            out = in1;
        end
    end
endmodule

