module hyperbolic (
  input x,
  output sineh,
  output cosh,
  output tanh
);

  reg signed [31:0] exp_x, exp_neg_x;
  reg signed [31:0] e_x, e_neg_x;
  reg signed [31:0] sum, diff;

  assign e_x = $exp(x);
  assign e_neg_x = $exp(-x);

  always @(*) begin
    sum = e_x + e_neg_x;
    diff = e_x - e_neg_x;

    sineh = diff >> 1;
    cosh = sum >> 1;
    tanh = sineh / cosh;
  end

endmodule

