module tone_generator (
  input [1:0] tone_type,
  input [n-1:0] tone_duration,
  input [m-1:0] tone_frequency,
  output tone
);

parameter n = 8; // number of bits for tone duration
parameter m = 16; // number of bits for tone frequency

reg [n-1:0] tone_counter;
reg [m-1:0] sine_counter;
reg [m-1:0] square_counter;
reg [m-1:0] dtmf_counter;

wire sine_wave;
wire square_wave;
wire dtmf_wave;

assign tone = (tone_type == 2'b00) ? dtmf_wave : (tone_type == 2'b01) ? sine_wave : square_wave;

// DTMF tone generation
reg [m-1:0] dtmf_frequency1;
reg [m-1:0] dtmf_frequency2;
reg [m-1:0] dtmf_wave1;
reg [m-1:0] dtmf_wave2;
reg [m-1:0] dtmf_mixed_wave;
reg [m-1:0] dtmf_filtered_wave;

always @ (posedge clk) begin
  if (tone_type == 2'b00) begin
    dtmf_counter <= (dtmf_counter == tone_frequency) ? 0 : dtmf_counter + 1;
    dtmf_frequency1 <= (tone_frequency == 697) ? 941 : (tone_frequency == 770) ? 1336 : (tone_frequency == 852) ? 1209 : 0;
    dtmf_frequency2 <= (tone_frequency == 697) ? 1209 : (tone_frequency == 770) ? 1477 : (tone_frequency == 852) ? 1336 : 0;
    dtmf_wave1 <= sin(2 * $pi * dtmf_frequency1 * dtmf_counter / 1000000);
    dtmf_wave2 <= sin(2 * $pi * dtmf_frequency2 * dtmf_counter / 1000000);
    dtmf_mixed_wave <= dtmf_wave1 + dtmf_wave2;
    dtmf_filtered_wave <= (dtmf_filtered_wave + dtmf_mixed_wave) / 2;
    dtmf_wave <= (dtmf_counter < tone_duration) ? dtmf_filtered_wave : 0;
  end
end

// Sine wave generation
always @ (posedge clk) begin
  if (tone_type == 2'b01) begin
    sine_counter <= (sine_counter == tone_frequency) ? 0 : sine_counter + 1;
    sine_wave <= sin(2 * $pi * tone_frequency * sine_counter / 1000000);
    tone <= (sine_counter < tone_duration) ? sine_wave : 0;
  end
end

// Square wave generation
always @ (posedge clk) begin
  if (tone_type == 2'b10) begin
    square_counter <= (square_counter == tone_frequency) ? 0 : square_counter + 1;
    square_wave <= (square_counter < tone_frequency / 2) ? 1 : 0;
    tone <= (square_counter < tone_duration) ? square_wave : 0;
  end
end

endmodule

module xor_inv_multiplexer (
    input clk,
    input [3:0] a,
    input [3:0] b,
    input sel_b1,
    input sel_b2,
    input sel_out,
    output reg out_always,
    output [3:0] out_xor,
    output [3:0] out_xor_inv,
    output out_logical_inv
);

    // 2-to-1 multiplexer to select between a and b
    wire [3:0] selected_input;
    assign selected_input = sel_b1 ? b : a;
    assign selected_input = sel_b2 ? b : selected_input;

    // XOR and inverter operations on the selected input
    assign out_xor = selected_input ^ a;
    assign out_xor_inv = ~out_xor;
    assign out_logical_inv = !out_xor;

    // 2-to-1 multiplexer to select between the bitwise inverse and logical inverse outputs
    always @(posedge clk) begin
        if (sel_out) begin
            out_always <= out_logical_inv;
        end else begin
            out_always <= out_xor_inv;
        end
    end

endmodule

