module PLL (
  input ref_clk,
  input fb_clk,
  output pll_clk
);

parameter f_ref = 1e6; // frequency of reference clock signal (in Hz)
parameter f_out = 10e6; // desired frequency of output signal (in Hz)
parameter k = 10; // multiplication factor of the PLL

reg [31:0] phase_accumulator = 0; // phase accumulator for the VCO
reg [31:0] control_voltage = 0; // control voltage for the VCO

// Phase detector
reg ref_clk_last = 0;
reg fb_clk_last = 0;
reg [31:0] phase_difference = 0;
always @(posedge ref_clk or posedge fb_clk) begin
  if (ref_clk_last == 1'b1 && ref_clk == 1'b0) begin
    phase_difference <= phase_difference + (2**32 / (f_ref / f_out));
  end
  if (fb_clk_last == 1'b1 && fb_clk == 1'b0) begin
    phase_difference <= phase_difference - (2**32 / (f_ref / f_out));
  end
  ref_clk_last <= ref_clk;
  fb_clk_last <= fb_clk;
end

// Charge pump
reg [1:0] charge_pump_out = 2'b00;
always @(posedge ref_clk) begin
  if (phase_difference > 0) begin
    charge_pump_out <= 2'b01;
  end else if (phase_difference < 0) begin
    charge_pump_out <= 2'b10;
  end else begin
    charge_pump_out <= 2'b00;
  end
end

// Loop filter
reg [31:0] loop_filter_out = 0;
reg [31:0] loop_filter_out_last = 0;
parameter loop_filter_gain = 100; // loop filter gain
parameter loop_filter_tc = 1e-3; // loop filter time constant
always @(posedge ref_clk) begin
  loop_filter_out <= loop_filter_out_last + (charge_pump_out - 2'b01) * loop_filter_gain * loop_filter_tc;
  loop_filter_out_last <= loop_filter_out;
end

// VCO
always @(posedge ref_clk) begin
  control_voltage <= loop_filter_out;
  phase_accumulator <= phase_accumulator + control_voltage;
  if (phase_accumulator >= (2**32 / k)) begin
    phase_accumulator <= phase_accumulator - (2**32 / k);
    pll_clk <= ~pll_clk;
  end
end

endmodule

module voltage_regulator (
    input VPWR,
    input VGND,
    input VPB,
    input VNB,
    output reg error
);

reg [1:0] VPWR_range = 2'b00;
reg [1:0] VGND_range = 2'b00;
reg [1:0] VPB_range = 2'b00;
reg [1:0] VNB_range = 2'b00;

always @ (VPWR) begin
    if (VPWR < 0.9) begin
        VPWR_range <= 2'b01;
    end else if (VPWR > 1.1) begin
        VPWR_range <= 2'b10;
    end else begin
        VPWR_range <= 2'b00;
    end
end

always @ (VGND) begin
    if (VGND < 0) begin
        VGND_range <= 2'b01;
    end else if (VGND > 0.1) begin
        VGND_range <= 2'b10;
    end else begin
        VGND_range <= 2'b00;
    end
end

always @ (VPB) begin
    if (VPB < 0.9) begin
        VPB_range <= 2'b01;
    end else if (VPB > 1.1) begin
        VPB_range <= 2'b10;
    end else begin
        VPB_range <= 2'b00;
    end
end

always @ (VNB) begin
    if (VNB < -0.1) begin
        VNB_range <= 2'b01;
    end else if (VNB > 0.1) begin
        VNB_range <= 2'b10;
    end else begin
        VNB_range <= 2'b00;
    end
end

always @ (*) begin
    if (VPWR_range != 2'b00 || VGND_range != 2'b00 || VPB_range != 2'b00 || VNB_range != 2'b00) begin
        error = 1;
    end else begin
        error = 0;
    end
end

endmodule

