  input             clk;

  input   [31:0]    control;
  output  [31:0]    status;

  input             src_adc_enable;
  input             src_adc_valid;
  input   [15:0]    src_adc_data;

  output            dst_adc_enable;
  output            dst_adc_valid;
  output  [15:0]    dst_adc_data;

  reg               dst_adc_enable;
  reg               dst_adc_valid;
  reg     [15:0]    dst_adc_data;

  reg     [31:0]    status            = 0;
  reg     [15:0]    adc_pn_data       = 0;

  reg     [ 3:0]    mode;
  reg     [ 3:0]    channel_sel;

  wire              adc_dvalid;
  wire    [15:0]    adc_pn_data_s;
  wire              adc_pn_oos_s;
  wire              adc_pn_err_s;


  // prbs function

  function [15:0] pn;
    input [15:0] din;
    reg   [15:0] dout;
    begin
      dout[15] = din[14] ^ din[15];
      dout[14] = din[13] ^ din[14];
      dout[13] = din[12] ^ din[13];
      dout[12] = din[11] ^ din[12];
      dout[11] = din[10] ^ din[11];
      dout[10] = din[ 9] ^ din[10];
      dout[ 9] = din[ 8] ^ din[ 9];
      dout[ 8] = din[ 7] ^ din[ 8];
      dout[ 7] = din[ 6] ^ din[ 7];
      dout[ 6] = din[ 5] ^ din[ 6];
      dout[ 5] = din[ 4] ^ din[ 5];
      dout[ 4] = din[ 3] ^ din[ 4];
      dout[ 3] = din[ 2] ^ din[ 3];
      dout[ 2] = din[ 1] ^ din[ 2];
      dout[ 1] = din[ 0] ^ din[ 1];
      dout[ 0] = din[14] ^ din[15] ^ din[ 0];
      pn = dout;
    end
  endfunction

  assign adc_dvalid = src_adc_enable & src_adc_valid;

  always @(posedge clk) begin
    channel_sel  <= control[3:0];
    mode         <= control[7:4];
  end

  // prbs generation
  always @(posedge clk) begin
    if(adc_dvalid == 1'b1) begin
      adc_pn_data <= pn(adc_pn_data_s);
    end
  end

  assign adc_pn_data_s = (adc_pn_oos_s == 1'b1) ? src_adc_data : adc_pn_data;

  ad_pnmon #(
    .DATA_WIDTH(32)
  ) i_pn_mon (
    .adc_clk(clk),
    .adc_valid_in(adc_dvalid),
    .adc_data_in(src_adc_data),
    .adc_data_pn(adc_pn_data),
    .adc_pn_oos(adc_pn_oos_s),
    .adc_pn_err(adc_pn_err_s));

  // rx path are passed through on test mode
  always @(posedge clk) begin
    dst_adc_enable <= src_adc_enable;
    dst_adc_data   <= src_adc_data;
    dst_adc_valid  <= src_adc_valid;
  end

  // setup status bits for gpio_out
  always @(posedge clk) begin
    if((mode == 3'd2) && (channel_sel == CHANNEL_ID)) begin
      status <= {22'h0, adc_pn_err_s, adc_pn_oos_s, RP_ID};
    end else begin
      status <= {24'h0, RP_ID};
    end
  end

endmodule

module edge_detect_mux (
    input clk,
    input [7:0] in,
    input [2:0] sel,
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output reg [3:0] out
);

reg [7:0] prev_in;
reg [2:0] sel_reg;
reg [2:0] edge_detected;
reg [2:0] priority;
reg [2:0] mux_sel;

always @(posedge clk) begin
    prev_in <= in;
    if (in[0] && !prev_in[0]) begin
        edge_detected <= sel;
    end
end

assign priority[0] = (edge_detected == 0) ? 1 : 0;
assign priority[1] = (edge_detected == 1) ? 1 : 0;
assign priority[2] = (edge_detected == 2) ? 1 : 0;

assign mux_sel = (sel_reg > 5) ? 0 : priority;

always @(posedge clk) begin
    sel_reg <= sel;
    out <= {4{1'bz}};
    case (mux_sel)
        3'b000: out <= data0;
        3'b001: out <= data1;
        3'b010: out <= data2;
        3'b011: out <= data3;
        3'b100: out <= data4;
        3'b101: out <= data5;
        default: out <= {4{1'bz}};
    endcase
end

endmodule

module johnson_counter (
  input clk,
  output [n-1:0] out
);

parameter n = 4; // number of output signals

reg [n-1:0] state; // register to hold current state
wire [n-1:0] next_state; // wire to hold next state

// define the flip-flops and their connections
always @(posedge clk) begin
  state <= next_state;
end

// define the logic that generates the sequence of binary numbers
assign next_state = {state[n-2:0], ~state[n-1] ^ state[n-2]};

// use the output signals to indicate the current state of the Johnson counter
assign out = state;

endmodule

module clk_gen (
    input clk_in, rst, enable, go,
    input [1:0] divider,
    output reg clk_out, pos_edge, neg_edge
);

reg [1:0] cnt;
wire cnt_zero = (cnt == 2'h0);
wire cnt_one = (cnt == 2'h1);

always @(posedge clk_in or posedge rst) begin
    if (rst) begin
        cnt <= 2'h3;
        clk_out <= 1'b0;
        pos_edge <= 1'b0;
        neg_edge <= 1'b0;
    end else if (go && enable) begin
        if (cnt_zero) begin
            clk_out <= ~clk_out;
            pos_edge <= 1'b1;
            neg_edge <= 1'b0;
        end else if (cnt_one) begin
            pos_edge <= 1'b0;
            neg_edge <= 1'b1;
        end
        cnt <= cnt - 1;
    end else begin
        clk_out <= 1'b0;
        pos_edge <= 1'b0;
        neg_edge <= 1'b0;
        cnt <= 2'h3;
    end
end

always @(posedge clk_in or posedge rst) begin
    if (rst) begin
        cnt <= 2'h3;
    end else if (go && enable) begin
        if (cnt_zero) begin
            cnt <= divider - 1;
        end else if (cnt_one) begin
            cnt <= 2'h3;
        end
    end else begin
        cnt <= 2'h3;
    end
end

endmodule

module led_blinker(
  input sys_clk,
  input rstn,
  input rstn_it,
  output reg [7:0] leds
);

  wire clk;
  wire [1:0] top;

  // Instantiate the clock divider
  clkdiv #(50000000) clkDiv(
    .rstn(rstn),
    .iclk(sys_clk),
    .oclk(clk)
  );

  // Instantiate the counter
  cnt #(.width(2)) cntUp(
    .clk(clk),
    .top(3),
    .rstn(rstn),
    .clr_it(rstn_it),
    .start(1),
    .freerun(1),
    .cnt(leds[6:4]),
    .it(top[1])
  );

  // Instantiate the LED output module
  m1 #(.width(4)) m1I(
    .clk(clk),
    .rstn(rstn),
    .leds(leds[3:0])
  );

  // Assign the LED outputs
  assign leds[3] = 1'b0;
  assign leds[4] = 1'b1;
  assign leds[5] = rstn_it;
  assign leds[7] = top[1];

endmodule

module full_adder (
    input A,
    input B,
    input C_in,
    output S,
    output C_out
);

assign S = A ^ B ^ C_in;
assign C_out = (A & B) | (C_in & (A ^ B));

endmodule

module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    input C_in,
    output [3:0] S,
    output C_out
);

wire [3:0] carry;
full_adder fa0(A[0], B[0], C_in, S[0], carry[0]);
full_adder fa1(A[1], B[1], carry[0], S[1], carry[1]);
full_adder fa2(A[2], B[2], carry[1], S[2], carry[2]);
full_adder fa3(A[3], B[3], carry[2], S[3], C_out);

endmodule

module twos_complement (
    input [3:0] A,
    input C,
    output [3:0] R
);

assign R = (C) ? (~A + 4'b1) : A;

endmodule

module adder_subtractor (
    input [3:0] A,
    input [3:0] B,
    input C,
    output reg [3:0] R
);

wire [3:0] S;
wire C_out;
ripple_carry_adder rca(A, twos_complement.B, C, S, C_out);
twos_complement tc(S, C, R);

always @(*) begin
    if (C == 1) begin
        R <= tc.R;
    end else begin
        R <= S;
    end
end

endmodule

