module add_sub (
    input [3:0] A,
    input [3:0] B,
    input CTRL,
    output [3:0] OUT,
    output OVF
);

    reg [4:0] temp;

    always @(*) begin
        if (CTRL == 0) begin
            temp = A + B;
            OUT = temp[3:0];
            OVF = temp[4];
        end
        else begin
            temp = A - B;
            OUT = temp[3:0];
            OVF = temp[4];
        end
    end

endmodule

module matrix_multiplier (
    input [7:0] A [3:0][3:0],
    input [7:0] B [3:0][3:0],
    output [7:0] C [3:0][3:0]
);

    reg [7:0] temp [3:0][3:0];

    integer i, j, k;

    always @(*) begin
        for (i = 0; i < 4; i = i + 1) begin
            for (j = 0; j < 4; j = j + 1) begin
                temp[i][j] = 0;
                for (k = 0; k < 4; k = k + 1) begin
                    temp[i][j] = temp[i][j] + A[i][k] * B[k][j];
                end
            end
        end
        for (i = 0; i < 4; i = i + 1) begin
            for (j = 0; j < 4; j = j + 1) begin
                C[i][j] = temp[i][j];
            end
        end
    end

endmodule

module functional_module (
    input [3:0] AS_OUT,
    input [7:0] MM_OUT [3:0][3:0],
    input select,
    input out_select,
    output [7:0] final_out
);

    wire [7:0] temp_out;

    assign temp_out = (select == 0) ? {AS_OUT, 4'b0000} : {MM_OUT};

    assign final_out = (out_select == 0) ? {temp_out[3:0], 4'b0000} : {temp_out};

endmodule

module control_logic (
    input clk,
    input reset,
    input select,
    input out_select,
    output reg add_sub_select,
    output reg [7:0] final_out
);

    reg [7:0] temp_out;

    always @(posedge clk, posedge reset) begin
        if (reset) begin
            add_sub_select <= 0;
            final_out <= 0;
        end
        else begin
            if (select == 0) begin
                add_sub_select <= 1;
                final_out <= {AS_OUT, 4'b0000};
            end
            else begin
                add_sub_select <= 0;
                final_out <= {MM_OUT};
            end
        end
    end

endmodule

module top_module (
    input clk,
    input reset,
    input [3:0] A,
    input [3:0] B,
    input CTRL,
    input [7:0] M_A [3:0][3:0],
    input [7:0] M_B [3:0][3:0],
    input select,
    input out_select,
    output [3:0] AS_OUT,
    output OVF,
    output [7:0] MM_OUT [3:0][3:0],
    output [7:0] final_out
);

    wire [3:0] add_sub_out;
    wire add_sub_ovf;
    wire [7:0] matrix_multiplier_out [3:0][3:0];

    add_sub add_sub_inst (
        .A(A),
        .B(B),
        .CTRL(CTRL),
        .OUT(add_sub_out),
        .OVF(add_sub_ovf)
    );

    matrix_multiplier matrix_multiplier_inst (
        .A(M_A),
        .B(M_B),
        .C(matrix_multiplier_out)
    );

    functional_module functional_module_inst (
        .AS_OUT(add_sub_out),
        .MM_OUT(matrix_multiplier_out),
        .select(select),
        .out_select(out_select),
        .final_out(final_out)
    );

    control_logic control_logic_inst (
        .clk(clk),
        .reset(reset),
        .select(select),
        .out_select(out_select),
        .add_sub_select(AS_OUT),
        .final_out(final_out)
    );

endmodule

