module ripple_carry_adder (
   input [3:0] A,
   input [3:0] B,
   input Cin,
   output [3:0] Sum,
   output Cout
);

   wire [3:0] temp_sum;
   wire [3:0] temp_carry;

   // Full adder for bit 0
   full_adder FA0 (
      .A(A[0]),
      .B(B[0]),
      .Cin(Cin),
      .Sum(temp_sum[0]),
      .Cout(temp_carry[0])
   );

   // Full adder for bit 1
   full_adder FA1 (
      .A(A[1]),
      .B(B[1]),
      .Cin(temp_carry[0]),
      .Sum(temp_sum[1]),
      .Cout(temp_carry[1])
   );

   // Full adder for bit 2
   full_adder FA2 (
      .A(A[2]),
      .B(B[2]),
      .Cin(temp_carry[1]),
      .Sum(temp_sum[2]),
      .Cout(temp_carry[2])
   );

   // Full adder for bit 3
   full_adder FA3 (
      .A(A[3]),
      .B(B[3]),
      .Cin(temp_carry[2]),
      .Sum(temp_sum[3]),
      .Cout(Cout)
   );

   assign Sum = temp_sum;

endmodule

module full_adder (
   input A,
   input B,
   input Cin,
   output Sum,
   output Cout
);

   assign Sum = A ^ B ^ Cin;
   assign Cout = (A & B) | (A & Cin) | (B & Cin);

endmodule

module tx_valid_fifo (
    aclr,
    data,
    rdclk,
    rdreq,
    wrclk,
    wrreq,
    q,
    rdempty,
    wrusedw
);

input aclr;
input [0:0] data;
input rdclk;
input rdreq;
input wrclk;
input wrreq;
output [0:0] q;
output rdempty;
output [7:0] wrusedw;

reg [7:0] wrptr;
reg [7:0] rdptr;
reg [7:0] usedw;
reg [7:0] next_wrptr;
reg [7:0] next_rdptr;
reg [7:0] next_usedw;
reg [7:0] fifo [0:255];

always @(posedge wrclk) begin
    if (wrreq) begin
        fifo[next_wrptr] <= data;
        next_wrptr <= wrptr + 1;
        next_usedw <= usedw + 1;
    end
end

always @(posedge rdclk) begin
    if (rdreq && !rdempty) begin
        q <= fifo[rdptr];
        next_rdptr <= rdptr + 1;
        next_usedw <= usedw - 1;
    end
end

always @(*) begin
    rdempty = (wrptr == rdptr) && (usedw == 0);
    wrusedw = usedw;
end

always @(posedge wrclk or posedge rdclk or posedge aclr) begin
    if (aclr) begin
        wrptr <= 0;
        rdptr <= 0;
        usedw <= 0;
    end else begin
        wrptr <= next_wrptr;
        rdptr <= next_rdptr;
        usedw <= next_usedw;
    end
end

endmodule

module d_ff_en_clk_gate (
  input CLK,
  input EN,
  input TE,
  input [31:0] DATA_IN,
  output reg DATA_OUT
);

  reg d_ff_en;
  wire ENCLK;

  TLATNTSCAX2TS latch (
