FpuFp32_Mul fpmul(clk, srca, fpmSrcB, fpmDst);
FpuFp32_Rcp fprcp(clk, srcb, fpRcpDst);

// Assign inputs to submodules
assign fpaIsSub = (opMode == OP_SUB);
assign fpmSrcB = (opMode == OP_DIV) ? fpRcpDst : srcb;

// Output selection logic
always @ (opMode) begin
    case (opMode)
        OP_ADD: begin
            dst = fpaDst;
        end
        OP_SUB: begin
            dst = fpaDst;
        end
        OP_MUL: begin
            dst = fpmDst;
        end
        OP_DIV: begin
            dst = fpmDst;
        end
        OP_ABS: begin
            dst = (srcb[31] == 1) ? -srcb : srcb;
        end
        OP_NEG: begin
            dst = -srcb;
        end
        OP_RCP: begin
            dst = fpRcpDst;
        end
        OP_SQRT: begin
            dst = ((srcb - 32'h3F80_0000) >>> 1) + 32'h3F80_0000;
        end
        default: begin
            dst = srcb;
        end
    endcase
end

