        upper_byte <= in[15:8];
        lower_byte <= in[7:0];
    end
end

// Behavioral XOR gate
always @(*) begin
    if (upper_byte == lower_byte) begin
        xor_output = 8'b00000000;
    end else begin
        xor_output = 8'b11111111;
    end
end

// Structural XOR gate using MUX
wire [7:0] mux_output;
assign mux_output = (xor_output == 8'b11111111) ? lower_byte : upper_byte;

// Final output
always @(posedge clk, posedge reset) begin
    if (reset) begin
        final_output <= 8'b0;
    end else begin
        final_output <= mux_output;
    end
end

endmodule

module main (
    // Clk Input
    input clk_in,

    // Data Pins
    output reset,
    output sclk, // Half the speed of data_clk, a 20,000th the speed of clk
    output sdata,
    output scmd,

    // Power Pins
    output vbat,
    output vdd,

    // LED String Data Pins
    output status_led,
    output light_clk,
    output light_data
);

    // GPIO OUT MAP
    // 0 - VDD
    // 1 - VBAT
    // 2 - RESET
    // 3 - SCLK
    // 4 - SDATA
    // 5 - SCMD
    // 6 - STATUS_LED
    // 7 - LIGHT_CLK
    // 8 - LIGHT_DATA

    wire [31 : 0] gpio;
    zynq_1_wrapper cpu(.gpio(gpio));

    assign vdd = gpio[0];
    assign vbat = gpio[1];
    assign reset = gpio[2];
    assign sdata = gpio[4];
    assign scmd = gpio[5];
    assign status_led = gpio[6];
    assign light_clk = gpio[7];
    assign light_data = gpio[8];

    // Generate sclk signal
    reg [31:0] counter = 0;
    reg sclk_reg = 0;
    always @(posedge clk_in) begin
        counter <= counter + 1;
        if (counter == 20000) begin
            counter <= 0;
            sclk_reg <= ~sclk_reg;
        end
    end
    assign sclk = sclk_reg;

    // Map signals to gpio vector
    assign gpio[0] = vdd;
    assign gpio[1] = vbat;
    assign gpio[2] = reset;
    assign gpio[3] = sclk;
    assign gpio[4] = sdata;
    assign gpio[5] = scmd;
    assign gpio[6] = status_led;
    assign gpio[7] = light_clk;
    assign gpio[8] = light_data;

endmodule

module memcard_interface(
    input sys_clk,
    input sys_rst,
    input [13:0] csr_a,
    input csr_we,
    input [31:0] csr_di,
    output [31:0] csr_do,
    inout [3:0] mc_d,
    output reg mc_cmd,
    output reg mc_clk
);

// Configuration registers
reg [7:0] cr0;
reg [7:0] cr1;
reg [7:0] cr2;
reg [7:0] cr3;

// Command receiver
reg cmd_rxen;
integer cmd_bitcount;
reg [47:0] cmd_rxreg;
initial begin
    cmd_rxen <= 1'b0;
    cmd_bitcount <= 0;
end
always @(posedge mc_clk) begin
    if(~mc_cmd)
        cmd_rxen = 1'b1;
    if(cmd_rxen) begin
        cmd_rxreg = {cmd_rxreg[46:0], mc_cmd};
        cmd_bitcount = cmd_bitcount + 1;
    end
    if(cmd_bitcount == 48) begin
        $display("CMD RX: %x", cmd_rxreg);
        cmd_bitcount = 0;
        cmd_rxen = 1'b0;
    end
end

// Command transmitter
reg cmd_txen;
reg [47:0] cmd_txreg;
initial cmd_txreg = 48'h7f0102030405;
always @(posedge mc_clk) begin
    if(cmd_txen)
        cmd_txreg <= {cmd_txreg[46:0], 1'b1};
end
assign mc_cmd = cmd_txen ? cmd_txreg[47] : 1'bz;

// Internal signals
reg [7:0] tx_data;
reg [7:0] rx_data;
reg [7:0] tx_index;
reg [7:0] rx_index;
reg [7:0] tx_len;
reg [7:0] rx_len;
reg [7:0] state;
reg [7:0] cmd;

// States
parameter IDLE = 8'h00;
parameter SEND_CMD = 8'h01;
parameter SEND_ADDR = 8'h02;
parameter SEND_DATA = 8'h03;
parameter READ_DATA = 8'h04;

always @(posedge sys_clk) begin
    if(sys_rst) begin
        // Reset state machine
        state <= IDLE;
        tx_len <= 8'h00;
        rx_len <= 8'h00;
        tx_index <= 8'h00;
        rx_index <= 8'h00;
        tx_data <= 8'h00;
        rx_data <= 8'h00;
        cmd <= 8'h00;
        mc_cmd <= 1'b0;
        mc_clk <= 1'b0;
    end else begin
        // State machine
        case(state)
            IDLE: begin
                // Wait for command
                if(cmd_rxen) begin
                    cmd <= cmd_rxreg[47:40];
                    state <= SEND_CMD;
                end
            end
            SEND_CMD: begin
                // Send command to memory card
                tx_len <= 8'h06;
                tx_index <= 8'h00;
                tx_data <= cmd;
                mc_cmd <= 1'b0;
                mc_clk <= 1'b0;
                state <= SEND_ADDR;
            end
            SEND_ADDR: begin
                // Send address to memory card
                tx_len <= 8'h04;
                tx_index <= 8'h00;
                tx_data <= csr_a[13:8];
                mc_cmd <= 1'b0;
                mc_clk <= 1'b0;
                state <= SEND_DATA;
            end
            SEND_DATA: begin
                // Send data to memory card
                tx_len <= 8'h04;
                tx_index <= 8'h00;
                tx_data <= csr_di[31:24];
                mc_cmd <= 1'b0;
                mc_clk <= 1'b0;
                state <= READ_DATA;
            end
            READ_DATA: begin
                // Read data from memory card
                rx_len <= 8'h04;
                rx_index <= 8'h00;
                mc_cmd <= 1'b1;
                mc_clk <= 1'b0;
                state <= IDLE;
            end
            default: begin
                // Default state
                state <= IDLE;
            end
        endcase

        // Memory card interface
        case({mc_cmd, mc_clk})
            {1'b1, 1'b0}: begin
                // Assert chip select and send command
                mc_d <= 4'h0;
                mc_cmd <= 1'b1;
                mc_clk <= 1'b1;
            end
            {1'b0, 1'b1}: begin
                // Send data
                mc_d <= tx_data[7:4];
                tx_data <= {1'b0, tx_data[6:0]};
                tx_index <= tx_index + 1;
                mc_cmd <= 1'b0;
                mc_clk <= 1'b0;
            end
            {1'b0, 1'b0}: begin
                // Send data
                mc_d <= tx_data[3:0];
                tx_data <= {1'b0, tx_data[6:0]};
                tx_index <= tx_index + 1;
                mc_cmd <= 1'b0;
                mc_clk <= 1'b1;
            end
            default: begin
                // Default state
                mc_d <= 4'hf;
                mc_cmd <= 1'bz;
                mc_clk <= 1'bz;
            end
        endcase
    end
end

// Configuration registers
always @(posedge sys_clk) begin
    if(sys_rst) begin
        // Reset configuration registers
        cr0 <= 8'h00;
        cr1 <= 8'h00;
        cr2 <= 8'h00;
        cr3 <= 8'h00;
    end else begin
        // Write to configuration registers
        if(csr_we) begin
            case(csr_a)
                8'h00: cr0 <= csr_di[7:0];
                8'h01: cr1 <= csr_di[7:0];
                8'h02: cr2 <= csr_di[7:0];
                8'h03: cr3 <= csr_di[7:0];
                default: begin
                    // Default case
                end
            endcase
        end

        // Read from configuration registers
        case(csr_a)
            8'h00: csr_do <= {24'h0, cr0};
            8'h01: csr_do <= {24'h0, cr1};
            8'h02: csr_do <= {24'h0, cr2};
            8'h03: csr_do <= {24'h0, cr3};
            default: begin
                // Default case
                csr_do <= 32'h0;
            end
        endcase
    end
end

endmodule

module top_module (
    input [7:0] a, b, c, d, // Four 8-bit inputs
    output reg [7:0] out // XOR of the two minimum values
); 

wire [7:0] min;
wire [7:0] min_XOR;

xor_gate xor1(.a(a), .b(b), .out(min_XOR[0]));
xor_gate xor2(.a(c), .b(d), .out(min_XOR[1]));

priority_encoder priority(.a(a), .b(b), .c(c), .d(d), .min(min));

functional_module func(.min_XOR(min_XOR), .min_priority(min), .out(out));

always @(*) begin
    if(min_XOR[0] < min_XOR[1])
        out = min_XOR[0] ^ min_priority;
    else
        out = min_XOR[1] ^ min_priority;
end

endmodule

module xor_gate(input a, b, output out);
    assign out = a ^ b;
endmodule

module priority_encoder(input [7:0] a, b, c, d, output [7:0] min);
    wire [7:0] temp_min;

    assign temp_min = (a < b) ? a : b;
    assign temp_min = (temp_min < c) ? temp_min : c;
    assign temp_min = (temp_min < d) ? temp_min : d;

    assign min = temp_min;
endmodule

module functional_module(input [7:0] min_XOR, min_priority, output out);
    assign out = min_XOR ^ min_priority;
endmodule

module eight_to_one(
    input A,
    input B,
    input C,
    input D,
    input E,
    input F,
    input G,
    input H,
    output Y
);

wire notA, notB, notC, notD, notE, notF, notG, notH;
wire and1, and2, and3, and4, and5, and6, and7, and8, or1;

not u_notA(A, notA);
not u_notB(B, notB);
not u_notC(C, notC);
not u_notD(D, notD);
not u_notE(E, notE);
not u_notF(F, notF);
not u_notG(G, notG);
not u_notH(H, notH);

and u_and1(notA, notB, notC, notD, notE, notF, notG, notH, and1);
and u_and2(A, notB, notC, notD, notE, notF, notG, notH, and2);
and u_and3(notA, B, notC, notD, notE, notF, notG, notH, and3);
and u_and4(notA, notB, C, notD, notE, notF, notG, notH, and4);
and u_and5(notA, notB, notC, D, notE, notF, notG, notH, and5);
and u_and6(notA, notB, notC, notD, E, notF, notG, notH, and6);
and u_and7(notA, notB, notC, notD, notE, F, notG, notH, and7);
and u_and8(notA, notB, notC, notD, notE, notF, G, notH, and8);

or u_or1(and1, and2, and3, and4, and5, and6, and7, and8, or1);

assign Y = or1;

endmodule

module case_statement;

reg [3:0] value1;
wire [3:0] value2;
reg [3:0] value3;

initial begin
    #0;
    value3 = 0;
    #3;
    value1 = 4'b0000;
    #5;
    $display("check == 0000: at time=%t value2=%h", $time, value2);
    if (value2 !== 4'b0) begin
        $display("FAILED - case_statement - casez 0 at %t", $time);
        value3 = 1;
    end
    #1;
    value1 = 4'b00z1;
    #5;
    $display("check == 0001: at time=%t value2=%h", $time, value2);
    if (value2 !== 4'b0001) begin
        $display("FAILED - case_statement - casez z1 at %t", $time);
        value3 = 1;
    end
    #1;
    value1 = 4'b0100;
    #5;
    $display("check == 0010: at time=%t value2=%h", $time, value2);
    if (value2 !== 4'b0010) begin
        $display("FAILED - case_statement - casez 4 at %t", $time);
        value3 = 1;
    end
    #10;
    if (value3 == 0) begin
        $display("PASSED");
    end
    $finish;
end

always @* begin
    $display("Entering case at time=%t value1=%b", $time, value1);
    casez (value1)
        4'b0000: begin
            #3;
            value2 = 4'b0000;
            $display("case0000: at time=%t", $time);
            #3;
        end
        4'b00z1: begin
            #3;
            value2 = 4'b0001;
            $display("case00z1: at time=%t", $time);
            #3;
        end
        4'b0100: begin
            #3;
            value2 = 4'b0010;
            $display("case100: at time=%t", $time);
            #3;
        end
        default: begin
            #2;
            $display("default: %t", $time);
        end
    endcase
    $display("Leaving case at time=%t", $time);
end

endmodule

module add_sub (
