module watchdog_timer (
  input clk,
  input rst,
  input [31:0] timeout,
  output reg t
);

  reg [31:0] counter;

  always @(posedge clk) begin
    if (rst) begin
      counter <= 0;
      t <= 0;
    end
    else begin
      counter <= counter + 1;
      if (counter == timeout) begin
        t <= 1;
      end
      else begin
        t <= 0;
      end
    end
  end

endmodule

module mux_2to1(
  input A,
  input B,
  input S,
  output Y
);

wire not_S, A_and_not_S, B_and_S;

not (
  not_S,
  S
);

and (
  A_and_not_S,
  A,
  not_S
);

and (
  B_and_S,
  B,
  S
);

or (
  Y,
  A_and_not_S,
  B_and_S
);

endmodule

