module Video_System_Pixel_Buffer (
    // Inputs
    clk,
    reset,

    address,
    byteenable,
    read,
    write,
    writedata,

    // Bi-Directional
    SRAM_DQ,

    // Outputs
    readdata,
    readdatavalid,

    SRAM_ADDR,
    SRAM_LB_N,
    SRAM_UB_N,
    SRAM_CE_N,
    SRAM_OE_N,
    SRAM_WE_N    
);

    // Parameter Declarations
    parameter ADDR_WIDTH = 18;
    parameter DATA_WIDTH = 16;

    // Port Declarations
    // Inputs
    input clk;
    input reset;

    input [ADDR_WIDTH-1:0] address;
    input [1:0] byteenable;
    input read;
    input write;
    input [DATA_WIDTH-1:0] writedata;

    // Bi-Directional
    inout [DATA_WIDTH-1:0] SRAM_DQ;

    // Outputs
    output reg [DATA_WIDTH-1:0] readdata;
    output reg readdatavalid;

    output reg [ADDR_WIDTH-1:0] SRAM_ADDR;
    output reg SRAM_LB_N;
    output reg SRAM_UB_N;
    output reg SRAM_CE_N;
    output reg SRAM_OE_N;
    output reg SRAM_WE_N;

    // Internal Wires and Registers Declarations
    wire [DATA_WIDTH-1:0] SRAM_DQ_reg;
    wire [1:0] byteenable_reg;
    wire read_reg;
    wire write_reg;
    wire [DATA_WIDTH-1:0] writedata_reg;
    wire [ADDR_WIDTH-1:0] address_reg;
    wire SRAM_CE_N_reg;
    wire SRAM_OE_N_reg;
    wire SRAM_WE_N_reg;
    wire [DATA_WIDTH-1:0] SRAM_DQ_out;

    // State Machine Registers
    reg [2:0] state;
    reg [DATA_WIDTH-1:0] pixel_data;

    // Sequential Logic
    always @(posedge clk) begin
        if (reset) begin
            state <= 3'b000;
            readdatavalid <= 1'b0;
            SRAM_LB_N <= 1'b1;
            SRAM_UB_N <= 1'b1;
            SRAM_CE_N <= 1'b1;
            SRAM_OE_N <= 1'b1;
            SRAM_WE_N <= 1'b1;
        end else begin
            case (state)
                3'b000: begin // Idle
                    if (read) begin
                        address_reg <= address;
                        state <= 3'b001;
                    end else if (write) begin
                        address_reg <= address;
                        byteenable_reg <= byteenable;
                        writedata_reg <= writedata;
                        state <= 3'b010;
                    end
                end
                3'b001: begin // Read
                    SRAM_CE_N <= 1'b0;
                    SRAM_OE_N <= 1'b0;
                    SRAM_ADDR <= address_reg;
                    state <= 3'b011;
                end
                3'b010: begin // Write
                    SRAM_CE_N <= 1'b0;
                    SRAM_WE_N <= 1'b0;
                    SRAM_ADDR <= address_reg;
                    SRAM_LB_N <= ~byteenable_reg[0];
                    SRAM_UB_N <= ~byteenable_reg[1];
                    SRAM_DQ <= writedata_reg;
                    state <= 3'b100;
                end
                3'b011: begin // Read Data
                    SRAM_DQ_reg <= SRAM_DQ;
                    SRAM_CE_N_reg <= SRAM_CE_N;
                    SRAM_OE_N_reg <= SRAM_OE_N;
                    if (~SRAM_CE_N_reg | ~SRAM_OE_N_reg) begin
                        pixel_data <= SRAM_DQ_reg;
                        readdatavalid <= 1'b1;
                        state <= 3'b000;
                    end
                end
                3'b100: begin // Write Data
                    SRAM_WE_N_reg <= SRAM_WE_N;
                    if (~SRAM_WE_N_reg) begin
                        SRAM_DQ <= 16'hzzzz;
                        state <= 3'b000;
                    end
                end
            endcase
        end
    end

    // Output Registers
    always @(posedge clk) begin
        readdata <= pixel_data;
    end

    // Combinational Logic
    assign SRAM_DQ_out = (state == 3'b011) ? SRAM_DQ_reg : 16'hzzzz;

    // Internal Assignments
    assign SRAM_DQ = SRAM_DQ_out;

endmodule

module axis_packetizer #
(
  parameter integer AXIS_TDATA_WIDTH = 32,
  parameter integer CNTR_WIDTH = 32
 )
(
  // System signals
  input  wire                        aclk,
  input  wire                        aresetn,

  input  wire [CNTR_WIDTH-1:0]       cfg_data,

  // Slave side
  output wire                        s_axis_tready,
  input  wire [AXIS_TDATA_WIDTH-1:0] s_axis_tdata,
  input  wire                        s_axis_tvalid,

  // Master side
  input  wire                        m_axis_tready,
  output wire [AXIS_TDATA_WIDTH-1:0] m_axis_tdata,
  output wire                        m_axis_tvalid,
  output wire                        m_axis_tlast
);

  reg [CNTR_WIDTH-1:0] int_cntr_reg, int_cntr_next;
  reg int_enbl_reg, int_enbl_next;

  wire int_comp_wire, int_tvalid_wire, int_tlast_wire;

  always @(posedge aclk)
  begin
    if(~aresetn)
    begin
      int_cntr_reg <= {(CNTR_WIDTH){1'b0}};
      int_enbl_reg <= 1'b0;
    end
    else
    begin
      int_cntr_reg <= int_cntr_next;
      int_enbl_reg <= int_enbl_next;
    end
  end

  assign int_comp_wire = int_cntr_reg < cfg_data;
  assign int_tvalid_wire = int_enbl_reg & s_axis_tvalid;
  assign int_tlast_wire = ~int_comp_wire;


  always @*
  begin
    int_cntr_next = int_cntr_reg;
    int_enbl_next = int_enbl_reg;

    if(~int_enbl_reg & int_comp_wire)
    begin
      int_enbl_next = 1'b1;
    end

    if(m_axis_tready & int_tvalid_wire & int_comp_wire)
    begin
      int_cntr_next = int_cntr_reg + 1'b1;
    end

    if(m_axis_tready & int_tvalid_wire & int_tlast_wire)
    begin
      int_cntr_next = {(CNTR_WIDTH){1'b0}};
    end
  end

  assign s_axis_tready = int_enbl_reg & m_axis_tready;
  assign m_axis_tdata = s_axis_tdata;
  assign m_axis_tvalid = int_tvalid_wire;
  assign m_axis_tlast = int_enbl_reg & int_tlast_wire;

endmodule

module clock_gen_select (
                         input clk,
                         input reset,
                         input [2:0] rate_select,
                         output reg clk_out
                         );

// Local signals
wire pulse;
wire dds_clk;

reg delayed_pulse;
reg [`DDS_PRESCALE_BITS-1:0] dds_prescale_count;
reg [`DDS_PRESCALE_BITS-1:0] dds_prescale_ndiv;
reg [`DDS_BITS-1:0] dds_phase;
reg [`DDS_BITS-2:0] dds_phase_increment;

// This part sets up the "dds_phase_increment" and "dds_prescale_ndiv" values
always @(rate_select)
begin
  case (rate_select)
    3'b000  : begin
                dds_phase_increment <=  1;  // 9600
                dds_prescale_ndiv   <=  2604;
              end

    3'b001  : begin
                dds_phase_increment <=  2;  // 19200
                dds_prescale_ndiv   <=  1302;
              end

    3'b010  : begin
                dds_phase_increment <=  4;  // 38400
                dds_prescale_ndiv   <=  651;
              end

    3'b011  : begin
                dds_phase_increment <=  6;  // 57600
                dds_prescale_ndiv   <=  434;
              end

    3'b100  : begin
                dds_phase_increment <= 12;  // 115200
                dds_prescale_ndiv   <=  217;
              end

    3'b101  : begin
                dds_phase_increment <= 12;  // 115200
                dds_prescale_ndiv   <=  217;
              end

    3'b110  : begin
                dds_phase_increment <= 12;  // 115200
                dds_prescale_ndiv   <=  217;
              end

    3'b111  : begin
                dds_phase_increment <= 12;  // 115200
                dds_prescale_ndiv   <=  217;
              end

    default : begin
                dds_phase_increment <= 12;  // 115200
                dds_prescale_ndiv   <=  217;
              end
  endcase 
end 

// This is the DDS prescaler part.  It has a variable divide value.
// The divide factor is "dds_prescale_ndiv" + 1.
always @(posedge clk)
begin
  if (reset) dds_prescale_count <= 0;
  else if (dds_prescale_count == (dds_prescale_ndiv-1))
    dds_prescale_count <= 0;
  else dds_prescale_count <= dds_prescale_count + 1;
end
assign dds_clk = (dds_prescale_count == (dds_prescale_ndiv-1));

// This is the DDS phase accumulator part
always @(posedge clk)
begin
  if (reset) dds_phase <= 0;
  else if (dds_clk) dds_phase <= dds_phase + dds_phase_increment;
end

assign pulse = dds_phase[`DDS_BITS-1];  // Simple renaming for readability

// This is "rising edge detector" part
always @(posedge clk)
begin
  delayed_pulse <= pulse;
end
assign clk_out = (pulse && ~delayed_pulse);  // Choose the rising edge

endmodule

module Touch_Sensor_Interface (
  input touch_signal,
  output processed_signal
);

  // Define the filter parameters
  parameter FILTER_CUTOFF_FREQ = 1000; // Hz
  parameter FILTER_SAMPLE_RATE = 10000; // Hz

  // Define the ADC parameters
  parameter ADC_RESOLUTION = 10; // bits
  parameter ADC_REFERENCE_VOLTAGE = 3.3; // V

  // Define the touch detection threshold
  parameter TOUCH_THRESHOLD = 512; // ADC counts

  // Define the capacitive touch sensor filter
  // This is a simple RC low-pass filter
  reg [15:0] filtered_signal;
  always @(posedge clk) begin
    filtered_signal <= filtered_signal + (touch_signal - filtered_signal) / 16;
  end

  // Define the resistive touch sensor filter
  // This is a current-to-voltage converter followed by a low-pass filter
  reg [15:0] converted_signal;
  always @(posedge clk) begin
    converted_signal <= touch_signal * 10000; // Convert current to voltage
    converted_signal <= converted_signal + (converted_signal - filtered_signal) / 16; // Low-pass filter
  end

  // Define the ADC
  // This is a simple voltage-to-counts converter
  reg [ADC_RESOLUTION-1:0] adc_value;
  always @(posedge clk) begin
    if (touch_sensor_type == CAPACITIVE) begin
      adc_value <= filtered_signal * (2**ADC_RESOLUTION-1) / ADC_REFERENCE_VOLTAGE; // Convert voltage to counts
    end else begin
      adc_value <= converted_signal * (2**ADC_RESOLUTION-1) / ADC_REFERENCE_VOLTAGE; // Convert voltage to counts
    end
  end

  // Define the touch detection logic
  // This simply checks if the ADC value is above the threshold
  always @(posedge clk) begin
    if (adc_value > TOUCH_THRESHOLD) begin
      processed_signal <= 1;
    end else begin
      processed_signal <= 0;
    end
  end

endmodule

module four_bit_adder(
  input [3:0] A,
  input [3:0] B,
  input Cin,
  output [3:0] S,
  output Cout
);

  wire [3:0] sum;
  wire C1, C2, C3;

  // Full-adder for bit 0
  full_adder fa0(A[0], B[0], Cin, sum[0], C1);

  // Full-adder for bit 1
  full_adder fa1(A[1], B[1], C1, sum[1], C2);

  // Full-adder for bit 2
  full_adder fa2(A[2], B[2], C2, sum[2], C3);

  // Full-adder for bit 3
  full_adder fa3(A[3], B[3], C3, sum[3], Cout);

  assign S = sum;

endmodule

// Full-adder module
module full_adder(
  input A,
  input B,
  input Cin,
  output S,
  output Cout
);

  assign S = A ^ B ^ Cin;
  assign Cout = (A & B) | (Cin & (A ^ B));

endmodule

module traffic_light(
    input clk,
    input reset,
    input pedestrian_button,
    output reg red_light,
    output reg yellow_light,
    output reg green_light,
    output reg pedestrian_light
);

    // define state variables
    parameter IDLE = 2'b00;
    parameter TRAFFIC_LIGHT = 2'b01;
    parameter PEDESTRIAN_LIGHT = 2'b10;
    reg [1:0] state = IDLE;

    // define counters for each state
    reg [3:0] red_counter = 0;
    reg [2:0] yellow_counter = 0;
    reg [4:0] green_counter = 0;
    reg [3:0] pedestrian_counter = 0;

    always @(posedge clk) begin

        if(reset) begin
            // reset all counters and set state to idle
            red_counter <= 0;
            yellow_counter <= 0;
            green_counter <= 0;
            pedestrian_counter <= 0;
            state <= IDLE;
        end

        else begin
            case(state)

                IDLE: begin
                    // set traffic light to red and wait for 5 seconds
                    red_light <= 1;
                    yellow_light <= 0;
                    green_light <= 0;
                    pedestrian_light <= 0;
                    red_counter <= red_counter + 1;

                    if(red_counter == 5) begin
                        red_counter <= 0;
                        state <= TRAFFIC_LIGHT;
                    end
                end

                TRAFFIC_LIGHT: begin
                    // set traffic light to yellow and wait for 2 seconds
                    red_light <= 0;
                    yellow_light <= 1;
                    green_light <= 0;
                    pedestrian_light <= 0;
                    yellow_counter <= yellow_counter + 1;

                    if(yellow_counter == 2) begin
                        yellow_counter <= 0;
                        state <= GREEN_LIGHT;
                    end
                end

                GREEN_LIGHT: begin
                    // set traffic light to green and wait for 10 seconds
                    red_light <= 0;
                    yellow_light <= 0;
                    green_light <= 1;
                    pedestrian_light <= 0;
                    green_counter <= green_counter + 1;

                    if(green_counter == 10) begin
                        green_counter <= 0;
                        state <= TRAFFIC_LIGHT_2;
                    end
                end

                TRAFFIC_LIGHT_2: begin
                    // set traffic light to yellow and wait for 2 seconds
                    red_light <= 0;
                    yellow_light <= 1;
                    green_light <= 0;
                    pedestrian_light <= 0;
                    yellow_counter <= yellow_counter + 1;

                    if(yellow_counter == 2) begin
                        yellow_counter <= 0;
                        state <= IDLE;
                    end
                end

                PEDESTRIAN_LIGHT: begin
                    // set pedestrian light to red and wait for 5 seconds
                    red_light <= 1;
                    yellow_light <= 0;
                    green_light <= 0;
                    pedestrian_light <= 1;
                    pedestrian_counter <= pedestrian_counter + 1;

                    if(pedestrian_counter == 5) begin
                        pedestrian_counter <= 0;
                        state <= PEDESTRIAN_LIGHT_2;
                    end
                end

                PEDESTRIAN_LIGHT_2: begin
                    // set pedestrian light to red and wait for 5 seconds
                    red_light <= 1;
                    yellow_light <= 0;
                    green_light <= 0;
                    pedestrian_light <= 0;
                    pedestrian_counter <= pedestrian_counter + 1;

                    if(pedestrian_counter == 5) begin
                        pedestrian_counter <= 0;
                        state <= IDLE;
                    end
                end

            endcase

            // check for pedestrian button press
            if(pedestrian_button) begin
                state <= PEDESTRIAN_LIGHT;
            end
        end
    end
endmodule

