module fsm_traffic_light(
  input clk,
  input reset,
  output reg [2:0] light
);

  // Define the states
  parameter GREEN = 2'b10;
  parameter YELLOW = 2'b01;
  parameter RED = 2'b00;

  // Define the state register and initialize to GREEN
  reg [1:0] state = GREEN;

  // Define the state transition logic
  always @(posedge clk, negedge reset) begin
    if (reset == 0) begin
      state <= GREEN;
    end else begin
      case (state)
        GREEN: state <= YELLOW;
        YELLOW: state <= RED;
        RED: state <= YELLOW;
      endcase
    end
  end

  // Define the output logic
  always @(*) begin
    case (state)
      GREEN: light = 3'b100;
      YELLOW: light = 3'b010;
      RED: light = 3'b001;
    endcase
  end

endmodule

module top_module ( 
    input clk, 
    input reset,  // Synchronous active-high reset 
    input [7:0] a, 
    input [7:0] b, 
    output [15:0] sum 
);

    wire [7:0] adder1_out;
    wire [7:0] adder2_out;
    wire carry_out;

    // Instantiate the two 8-bit adder modules
    adder8 adder1(.clk(clk), .reset(reset), .a(a), .b(b), .carry_in(1'b0), .sum(adder1_out), .carry_out(carry_out));
    adder8 adder2(.clk(clk), .reset(reset), .a(a[7:0]), .b(b[7:0]), .carry_in(carry_out), .sum(adder2_out), .carry_out(sum[8]));

    // Instantiate the functional module to combine the outputs of the two adder modules
    adder8 functional_module(.clk(clk), .reset(reset), .a(adder1_out), .b(adder2_out), .carry_in(carry_out), .sum(sum[7:0]), .carry_out(sum[15]));

endmodule

// 8-bit adder module with active-high synchronous reset
module adder8 (
    input clk,
    input reset,  // Synchronous active-high reset 
    input [7:0] a,
    input [7:0] b,
    input carry_in,
    output [7:0] sum,
    output carry_out
);

    reg [7:0] sum_reg;
    reg carry_out_reg;

    always @(posedge clk) begin
        if (reset) begin
            sum_reg <= 8'b0;
            carry_out_reg <= 1'b0;
        end else begin
            {carry_out_reg, sum_reg} <= a + b + carry_in;
        end
    end

    assign sum = sum_reg;
    assign carry_out = carry_out_reg;

endmodule

module add16(
    input [15:0] a,   // First 16-bit input
    input [15:0] b,   // Second 16-bit input
    output [15:0] sum // 16-bit output sum
);

    assign sum = a + b;   // Add the two inputs and assign the result to the output

endmodule

module top_module(
    input [31:0] a,       // First 32-bit input
    input [31:0] b,       // Second 32-bit input
    input [1:0] select,   // Select input to choose between inputs
    input clk,            // Clock input
    output [31:0] sum     // 32-bit output sum
);

    wire [15:0] adder1_out, adder2_out, adder3_out, adder4_out;  // Intermediate outputs of the 16-bit adders
    wire [31:0] mux_out;                                        // Output of the 2:1 multiplexer

    // Instantiate four 16-bit adders
    add16 adder1(.a(a[15:0]), .b(b[15:0]), .sum(adder1_out));
    add16 adder2(.a(a[31:16]), .b(b[31:16]), .sum(adder2_out));
    add16 adder3(.a(a[47:32]), .b(b[47:32]), .sum(adder3_out));
    add16 adder4(.a(a[63:48]), .b(b[63:48]), .sum(adder4_out));

    // Implement the 2:1 multiplexer using combinational logic
    assign mux_out = (select == 2'b0) ? a[31:0] : b[31:0];

    // Combine the outputs of the adders and the multiplexer to get the final output
    assign sum = {adder4_out, adder3_out, adder2_out, adder1_out} + mux_out;

endmodule

module ripple_adder(A, B, CIN, S, COUT);
  input [3:0] A;
  input [3:0] B;
  input CIN;
  output [3:0] S;
  output COUT;

  wire [3:0] sum;
  wire [3:0] carry;

  // first full adder
  fulladder FA0(A[0], B[0], CIN, sum[0], carry[0]);

  // second full adder
  fulladder FA1(A[1], B[1], carry[0], sum[1], carry[1]);

  // third full adder
  fulladder FA2(A[2], B[2], carry[1], sum[2], carry[2]);

  // fourth full adder
  fulladder FA3(A[3], B[3], carry[2], sum[3], COUT);

  assign S = sum;

endmodule

module fulladder (a, b, ci, s, co);
  input a, b, ci;
  output co, s;

  wire d;

  assign d = a ^ b;
  assign s = d ^ ci;
  assign co = (b & ~d) | (d & ci);
endmodule

module ARM_CU_ALU(
    input MFC,
    input Reset,
    input Clk,
    input MEMSTORE,
    input MEMLOAD,
    input [31:0] MEMDAT,
    output reg [31:0] MEMADD,
    output reg MFA,
    output reg READ_WRITE,
    output reg WORD_BYTE
);

reg [31:0] mem[0:1023];

always @(posedge Clk) begin
    if (Reset) begin
        MEMADD <= 0;
        MFA <= 0;
        READ_WRITE <= 0;
        WORD_BYTE <= 0;
    end else if (MEMSTORE) begin
        mem[MEMADD] <= MEMDAT;
    end else if (MEMLOAD) begin
        MEMDAT <= mem[MEMADD];
    end
end

always @(posedge MFA) begin
    if (READ_WRITE) begin
        MFA <= 1;
        WORD_BYTE <= 1;
        case (MEMADD)
            8'h00: begin
                MEMDAT <= 32'b11100010_00000001_00000000_00000000;
            end
            8'h04: begin
                MEMDAT <= 32'b11100011_10000000_00010000_00101000;
            end
            8'h08: begin
                MEMDAT <= 32'b11100111_11010001_00100000_00000000;
            end
            8'h0C: begin
                MEMDAT <= 32'b11100101_11010001_00110000_00000010;
            end
            8'h10: begin
                MEMDAT <= 32'b11100000_10000000_01010000_00000000;
            end
            8'h14: begin
                MEMDAT <= 32'b11100000_10000010_01010000_00000101;
            end
            8'h18: begin
                MEMDAT <= 32'b11100010_01010011_00110000_00000001;
            end
            8'h1C: begin
                MEMDAT <= 32'b00011010_11111111_11111111_11111101;
            end
            8'h20: begin
                MEMDAT <= 32'b11100101_11000001_01010000_00000011;
            end
            8'h24: begin
                MEMDAT <= 32'b11101010_00000000_00000000_00000001;
            end
            8'h28: begin
                MEMDAT <= 32'b00001011_00000101_00000111_00000100;
            end
            8'h2C: begin
                MEMDAT <= 32'b11101010_11111111_11111111_11111111;
            end
            default: begin
                MEMDAT <= 32'h00000000;
            end
        endcase
    end else begin
        MFA <= 0;
        WORD_BYTE <= 0;
    end
end

endmodule

module bin_to_bcd (
  input [n-1:0] bin,
  output [m-1:0] bcd
);

parameter n = 8; // number of bits in the binary number
parameter m = 3; // number of digits in the BCD number

reg [3:0] bcd_digit [0:m-1];
reg [3:0] decimal_num;
integer i;

always @(*) begin
  decimal_num = 0;
  for (i = 0; i < n; i = i + 1) begin
    decimal_num = decimal_num + (bin[i] * (2 ** i));
  end

  for (i = 0; i < m; i = i + 1) begin
    bcd_digit[i] = decimal_num % 10;
    decimal_num = decimal_num / 10;
  end
end

assign bcd = {bcd_digit[m-1], bcd_digit[m-2], bcd_digit[m-3]};

endmodule

module clock_generators(
    input clk48,
    input IFCLK,
    input clkgen_rst,
    input clksel,
    output fastclk,
    output ifclk_out,
    output clocks_locked
);

  localparam period48 = 1000.0/48.0;

  wire fbclk, fbclk_buf;
  wire fbclk2, fbclk2_buf;
  wire clk100, clk160, clkif180;
  wire clk100_locked, clk160_locked, clk48_locked, clkif_locked;
  wire ifclk_buf;

  // DCM for generating 100 MHz clock
  DCM_SP #( .CLKFX_MULTIPLY(25), .CLKFX_DIVIDE(12), // 48*25/12 = 100
	    .CLKIN_PERIOD(period48), .CLKIN_DIVIDE_BY_2("FALSE"),
	    .CLK_FEEDBACK("NONE"), .CLKDV_DIVIDE(2),
	    .PHASE_SHIFT(0), .CLKOUT_PHASE_SHIFT("NONE"),
	    .DUTY_CYCLE_CORRECTION("TRUE"), .STARTUP_WAIT("FALSE"),
	    .DESKEW_ADJUST("SYSTEM_SYNCHRONOUS"), .FACTORY_JF(16'hc080),
	    .DFS_FREQUENCY_MODE("LOW"), .DLL_FREQUENCY_MODE("LOW") )
   dcm100 (.CLKIN(fbclk_buf), .CLKFB(1'b0), .RST(clkgen_rst),
	   .CLK0(), .CLKFX(clk100), .LOCKED(clk100_locked),
	   .PSEN(1'b0), .PSCLK(1'b0), .PSINCDEC(1'b0), .DSSEN(1'b0));

  // DCM for generating 160 MHz clock
  DCM_SP #( .CLKFX_MULTIPLY(10), .CLKFX_DIVIDE(3), // 48*10/3 = 160
	    .CLKIN_PERIOD(period48), .CLKIN_DIVIDE_BY_2("FALSE"),
	    .CLK_FEEDBACK("NONE"), .CLKDV_DIVIDE(2),
	    .PHASE_SHIFT(0), .CLKOUT_PHASE_SHIFT("NONE"),
	    .DUTY_CYCLE_CORRECTION("TRUE"), .STARTUP_WAIT("FALSE"),
	    .DESKEW_ADJUST("SYSTEM_SYNCHRONOUS"), .FACTORY_JF(16'hc080),
	    .DFS_FREQUENCY_MODE("LOW"), .DLL_FREQUENCY_MODE("LOW") )
   dcm160 (.CLKIN(fbclk_buf), .CLKFB(1'b0), .RST(clkgen_rst),
	   .CLK0(), .CLKFX(clk160), .LOCKED(clk160_locked),
	   .PSEN(1'b0), .PSCLK(1'b0), .PSINCDEC(1'b0), .DSSEN(1'b0));

  // DCM for generating 180 degree out-of-phase clock
  IBUFG ifin_buf(.I(IFCLK), .O(ifclk_buf));
  DCM_SP #( .CLKFX_MULTIPLY(1), .CLKFX_DIVIDE(1),
	    .CLKIN_PERIOD(period48), .CLKIN_DIVIDE_BY_2("FALSE"),
	    .CLK_FEEDBACK("1X"), .CLKDV_DIVIDE(2),
	    .PHASE_SHIFT(0), .CLKOUT_PHASE_SHIFT("NONE"),
	    .DUTY_CYCLE_CORRECTION("TRUE"), .STARTUP_WAIT("FALSE"),
	    .DESKEW_ADJUST("SYSTEM_SYNCHRONOUS"), .FACTORY_JF(16'hc080),
	    .DFS_FREQUENCY_MODE("LOW"), .DLL_FREQUENCY_MODE("LOW") )
   dcmif (.CLKIN(ifclk_buf), .CLKFB(fbclk2_buf), .RST(clkgen_rst),
	  .CLK0(fbclk2), .CLK180(clkif180), .LOCKED(clkif_locked),
	  .PSEN(1'b0), .PSCLK(1'b0), .PSINCDEC(1'b0), .DSSEN(1'b0));
  BUFG ifout_buf(.I(clkif180), .O(ifclk_out));

  // DCM for generating 48 MHz clock
  DCM_SP #( .CLKFX_MULTIPLY(4), .CLKFX_DIVIDE(1),
	    .CLKIN_PERIOD(period48), .CLKIN_DIVIDE_BY_2("FALSE"),
	    .CLK_FEEDBACK("1X"), .CLKDV_DIVIDE(2),
	    .PHASE_SHIFT(0), .CLKOUT_PHASE_SHIFT("NONE"),
	    .DUTY_CYCLE_CORRECTION("TRUE"), .STARTUP_WAIT("FALSE"),
	    .DESKEW_ADJUST("SYSTEM_SYNCHRONOUS"), .FACTORY_JF(16'hc080),
	    .DFS_FREQUENCY_MODE("LOW"), .DLL_FREQUENCY_MODE("LOW") )
   dcm48 (.CLKIN(clk48), .CLKFB(fbclk_buf), .RST(clkgen_rst),
	  .CLK0(fbclk), .LOCKED(clk48_locked),
	  .PSEN(1'b0), .PSCLK(1'b0), .PSINCDEC(1'b0), .DSSEN(1'b0));
  BUFG fb_buf(.I(fbclk), .O(fbclk_buf));

  // BUFGMUX to select between 100 MHz and 160 MHz clocks
  BUFGMUX fastclk_mux(.I0(clk100), .I1(clk160), .S(clksel), .O(fastclk));

  // Output signal indicating all clocks are locked
  assign clocks_locked = clk100_locked & clk160_locked & clk48_locked && clkif_locked;

endmodule

