module gray_to_bcd_counter (
    input clk,
    input reset,   // Synchronous active-high reset
    input enable,   // Enable signal for the counter
    output reg [15:0] q   // Output of the counter in Gray code
);

    reg [3:0] bcd [0:3];   // BCD values for each decimal digit
    reg [3:0] gray [0:3];   // Gray code values for each decimal digit
    reg [3:0] next_gray [0:3];   // Next Gray code values for each decimal digit
    reg [3:0] digit_enable [0:2];   // Enable signals for the upper three digits
    reg [1:0] carry [0:3];   // Carry values for each decimal digit

    always @(posedge clk, posedge reset) begin
        if (reset) begin
            q <= 16'b0000;
            bcd <= 4'b0000;
            gray <= 4'b0000;
            next_gray <= 4'b0000;
            digit_enable <= 3'b000;
            carry <= 2'b00;
        end else begin
            // Gray to BCD conversion
            bcd[0] <= gray[0] ^ gray[1];
            bcd[1] <= gray[1] ^ gray[2];
            bcd[2] <= gray[2] ^ gray[3];
            bcd[3] <= gray[3];

            // Digit enable signals
            digit_enable[0] <= enable;
            digit_enable[1] <= carry[0];
            digit_enable[2] <= carry[1];

            // Carry values
            carry[0] <= bcd[0][3];
            carry[1] <= bcd[1][3];
            carry[2] <= bcd[2][3];

            // Next Gray code values
            next_gray[0] <= gray[0] ^ digit_enable[0];
            next_gray[1] <= gray[1] ^ carry[0];
            next_gray[2] <= gray[2] ^ carry[1];
            next_gray[3] <= gray[3] ^ carry[2];

            // Update Gray code value
            gray <= next_gray;

            // Update output value
            q <= {gray[3], gray[2], gray[1], gray[0], 4'b0000};
        end
    end

endmodule

module dual_edge_triggered_flip_flop (
    input clk,
    input reset,   // Synchronous active-high reset
    input d,   // Data input
    output reg q   // Output of the flip-flop
);

    reg [1:0] state;   // State variable for the flip-flop

    always @(posedge clk, posedge reset) begin
        if (reset) begin
            q <= 1'b0;
            state <= 2'b00;
        end else begin
            case (state)
                2'b00: begin   // Initial state
                    q <= 1'b0;
                    if (d) begin
                        state <= 2'b01;
                    end
                end
                2'b01: begin   // First rising edge detected
                    q <= 1'b1;
                    state <= 2'b10;
                end
                2'b10: begin   // Falling edge detected
                    q <= 1'b1;
                    state <= 2'b11;
                end
                2'b11: begin   // Second rising edge detected
                    q <= 1'b0;
                    state <= 2'b00;
                end
            endcase
        end
    end

endmodule

module final_module (
    input [15:0] gray_to_bcd_q,
    input q_t,
    output reg [11:0] final_q
);

    always @(gray_to_bcd_q, q_t) begin
        final_q <= {gray_to_bcd_q[11:8], q_t, gray_to_bcd_q[3:0]};
    end

endmodule

module top_module (
    input clk,
    input reset,   // Synchronous active-high reset
    output reg [15:0] gray_to_bcd_q,   // Output from Gray to BCD counter module
    output reg q_t,   // Output from dual-edge triggered flip-flop module
    output reg [11:0] final_q    // Final output
);

    reg [3:0] digit_enable;   // Enable signals for the upper three digits

    gray_to_bcd_counter gray_to_bcd_counter_inst (
        .clk(clk),
        .reset(reset),
        .enable(digit_enable[2]),
        .q(gray_to_bcd_q)
    );

    dual_edge_triggered_flip_flop dual_edge_triggered_flip_flop_inst (
        .clk(clk),
        .reset(reset),
        .d(gray_to_bcd_q[15]),
        .q(q_t)
    );

    final_module final_module_inst (
        .gray_to_bcd_q(gray_to_bcd_q),
        .q_t(q_t),
        .final_q(final_q)
    );

    always @(posedge clk, posedge reset) begin
        if (reset) begin
            digit_enable <= 4'b0000;
        end else begin
            // Increment upper three digits every 8 counts
            if (gray_to_bcd_q[2:0] == 3'b111) begin
                digit_enable <= digit_enable + 1;
            end
        end
    end

endmodule

module adder(
    input [7:0] a,
    input [7:0] b,
    input [7:0] c,
    input [7:0] d,
    output [8:0] sum
);

