module multiply (
        ap_start,
        ap_done,
        ap_idle,
        ap_ready,
        a,
        b,
        ap_return
);

input   ap_start;
output   ap_done;
output   ap_idle;
output   ap_ready;
input  [15:0] a;
input  [15:0] b;
output  [31:0] ap_return;

parameter    ap_const_logic_1 = 1'b1;
parameter    ap_const_logic_0 = 1'b0;

reg [31:0] result;
reg [3:0] counter;

assign ap_done = (counter == 16) ? ap_const_logic_1 : ap_const_logic_0;
assign ap_idle = (counter == 0) ? ap_const_logic_1 : ap_const_logic_0;
assign ap_ready = (counter == 0) ? ap_const_logic_1 : ap_const_logic_0;
assign ap_return = result;

always @ (posedge ap_start) begin
    result <= 0;
    counter <= 0;
end

always @ (posedge ap_start) begin
    for (counter = 0; counter < 16; counter = counter + 1) begin
        if (b[counter] == ap_const_logic_1) begin
            result <= result + (a << counter);
        end
    end
end

endmodule

module Manchester (
  input data_in,
  output data_out,
  output clock_out
);

  reg data_out_reg;
  reg clock_out_reg;

  reg data_in_prev;
  reg clock_in_prev;

  always @(posedge data_in) begin
    // Manchester encoding
    data_out_reg <= data_in ^ clock_in_prev;
    clock_out_reg <= ~clock_in_prev;

    // Save previous values
    data_in_prev <= data_in;
    clock_in_prev <= ~clock_in_prev;
  end

  always @(posedge clock_out_reg) begin
    // Manchester decoding
    if (data_out_reg == 1'b0 && data_in_prev == 1'b1) begin
      data_out <= 1'b0;
    end else if (data_out_reg == 1'b1 && data_in_prev == 1'b0) begin
      data_out <= 1'b1;
    end

    // Generate clock signal
    clock_out <= clock_out_reg;
  end

endmodule

module Coprocessor(
	clk,
	rst,
	c0_rd_addr,
	c0_wr_addr,
	c0_w_data,
	pc_i,
	InTcause,
	c0_reg_we,
	WriteEPC,
	WriteCause,
	c0_r_data,
	epc_o,
    WriteInt,
    Int_en_i,
    Int_en_o
);

	// ================ IO interface
	input clk, rst;
	input wire 	[31: 0] c0_w_data, pc_i;
	input wire 	[ 4: 0] c0_rd_addr, c0_wr_addr;
	input wire 	[ 4: 0]	InTcause;
	input wire 			c0_reg_we, WriteEPC, WriteCause,
						WriteInt, Int_en_i;

	output wire [31: 0]	c0_r_data, epc_o, Int_en_o;
    integer             i = 0;
	reg 		[31: 0] c0reg[11:14];
				// 11 Enable, 12 Base, 13 Cause, 14 Epc

	assign c0_r_data 	= c0reg[c0_rd_addr];
	assign epc_o  		= c0reg[14];
	assign Int_en_o  	= c0reg[11];

	initial begin
		for(i = 11; i <= 14; i = i + 1)
			c0reg[i] <= 32'b0;
	end

	always @(posedge clk ) begin
		if (rst) begin
			// reset
			for(i = 11; i <= 14; i = i + 1)
				c0reg[i] <= 32'b0;
		end
		else begin

			if (c0_reg_we == 1)
				c0reg[c0_wr_addr] 	<= c0_w_data;
			if (WriteInt == 1)
            	c0reg[11][0] 		<= Int_en_i;
            if (WriteCause == 1)
            	c0reg[13] 			<= InTcause;
			if (WriteEPC == 1)
            	c0reg[14] 			<= pc_i;

		end
	end

endmodule

module dffs_37 ( clk, set, d, q );
