module image_capture(
    input enable,
    input [7:0] data,
    input rst_cvc,
    input rst_cds,
    input sample,
    input end_adc,
    input lval,
    input pixel_clock,
    input main_clock_source,
    input main_clock,
    input n_reset,
    input load_pulse,
    output reg [7:0] pixel_data,
    output reg pixel_captured
);

reg[7:0] pixel_buffer;
reg[2:0] state;
reg[7:0] pixel_counter;
reg sample_prev;
reg load_pulse_prev;
reg[7:0] data_buffer;

parameter IDLE = 3'b000;
parameter CAPTURE = 3'b001;
parameter LOAD = 3'b010;
parameter WAIT = 3'b011;

always @ (posedge main_clock) begin
    if (n_reset == 1'b0) begin
        state <= IDLE;
        pixel_captured <= 1'b0;
        pixel_data <= 8'h00;
        pixel_counter <= 8'h00;
        pixel_buffer <= 8'h00;
        sample_prev <= 1'b0;
        load_pulse_prev <= 1'b0;
        data_buffer <= 8'h00;
    end else if (enable == 1'b0) begin
        state <= IDLE;
        pixel_captured <= 1'b0;
        pixel_data <= 8'h00;
        pixel_counter <= 8'h00;
        pixel_buffer <= 8'h00;
        sample_prev <= 1'b0;
        load_pulse_prev <= 1'b0;
        data_buffer <= 8'h00;
    end else begin
        case (state)
            IDLE: begin
                if (sample == 1'b1 && sample_prev == 1'b0) begin
                    state <= CAPTURE;
                end
            end
            CAPTURE: begin
                if (end_adc == 1'b1) begin
                    pixel_buffer <= data;
                    state <= LOAD;
                end
            end
            LOAD: begin
                if (load_pulse == 1'b1 && load_pulse_prev == 1'b0) begin
                    data_buffer <= pixel_buffer;
                    pixel_captured <= 1'b1;
                    state <= WAIT;
                end
            end
            WAIT: begin
                if (lval == 1'b1) begin
                    pixel_data <= data_buffer;
                    pixel_counter <= pixel_counter + 1;
                    pixel_captured <= 1'b0;
                    state <= IDLE;
                end
            end
        endcase
        sample_prev <= sample;
        load_pulse_prev <= load_pulse;
    end
end

endmodule

module top_module(
  input wire [15:0] in,
  input wire [1:0] en1,
  input wire en2,
  output wire [7:0] out_hi,
  output wire [7:0] out_lo
);

  wire [3:0] dec1_out;
  wire [15:0] dec2_out;
  wire [7:0] comp_hi;
  wire [7:0] comp_lo;

  decoder1 dec1(.in(en1), .enable(en2), .out(dec1_out));
  decoder2 dec2(.in(dec1_out), .enable(en2), .out(dec2_out));

  assign comp_hi = ~in[15:8];
  assign comp_lo = ~in[7:0];

  assign out_hi = en1 ? dec2_out[15:8] : 8'b0;
  assign out_lo = en1 ? comp_lo : comp_hi;

endmodule

module decoder1 (
  input [1:0] in,
  input enable,
  output [3:0] out
);
  assign out = enable ? {~in[1], ~in[0], in[1], in[0]} : 4'b0;
endmodule

module decoder2 (
  input [3:0] in,
  input enable,
  output [15:0] out
);
  assign out = enable ? {~in[3], ~in[2], ~in[1], ~in[0], in[3], in[2], in[1], in[0], ~in[3], ~in[2], ~in[1], in[0], in[3], in[2], in[1], ~in[0]} : 16'b0;
endmodule

module xor_4bit(
  input [3:0] A,
  input [3:0] B,
  output [3:0] Y
);

  wire w1, w2, w3, w4, w5, w6, w7;

  xor x1(w1, A[0], B[0]);
  xor x2(w2, A[1], B[1]);
  xor x3(w3, A[2], B[2]);
  xor x4(w4, A[3], B[3]);

  and a1(w5, w1, w2);
  and a2(w6, w3, w4);
  and a3(w7, w5, w6);

  xor x5(Y[0], A[0], B[0]);
  xor x6(Y[1], A[1], B[1]);
  xor x7(Y[2], A[2], B[2]);
  xor x8(Y[3], A[3], B[3]);

endmodule

module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    output [3:0] C
);

    wire [3:0] sum;
    wire [3:0] carry;

    full_adder fa0(A[0], B[0], 1'b0, sum[0], carry[0]);
    full_adder fa1(A[1], B[1], carry[0], sum[1], carry[1]);
    full_adder fa2(A[2], B[2], carry[1], sum[2], carry[2]);
    full_adder fa3(A[3], B[3], carry[2], sum[3], C);

endmodule

module full_adder (
    input A,
    input B,
    input Cin,
    output Sum,
    output Cout
);

    assign {Cout, Sum} = A + B + Cin;

endmodule

