module absolute_counter (
    input clk,
    input rst,
    input en,
    input ld,
    input signed [31:0] in,
    input [3:0] load_data,
    output [35:0] out
);

    // Absolute value module
    wire [31:0] abs_val;
    assign abs_val = (in < 0) ? -in : in;

    // Binary counter module
    reg [3:0] counter;
    always @(posedge clk) begin
        if (rst) begin
            counter <= 4'b0000;
        end else if (en) begin
            counter <= counter + 1;
        end else if (ld) begin
            counter <= load_data;
        end
    end

    // Output module
    assign out = abs_val + {32'b0, counter};

endmodule

module mux_4to1_using_2to1 (input [3:0] in, input [1:0] sel, output reg out);

   wire [1:0] s1, s2;
   wire [1:0] not_sel;

   // invert select signals
   assign not_sel = ~sel;

   // connect inputs to 2-to-1 muxes
   assign s1[0] = in[0];
   assign s1[1] = in[1];
   assign s2[0] = in[2];
   assign s2[1] = in[3];

   // connect select signals to 2-to-1 muxes
   assign out = (not_sel[1] & s1[sel[0]]) | (sel[1] & s2[not_sel[0]]);

endmodule

module spi(
  input clk,
  input SCK,
  input MOSI,
  inout MISO,
  input SSEL,
  output cmd_ready,
  output param_ready,
  output [7:0] cmd_data,
  output [7:0] param_data,
  output endmessage,
  output startmessage,
  input [7:0] input_data,
  output [31:0] byte_cnt,
  output [2:0] bit_cnt
);

reg [7:0] cmd_data_r;
reg [7:0] param_data_r;

reg [2:0] SSELr;
reg [2:0] SSELSCKr;

always @(posedge clk) SSELr <= {SSELr[1:0], SSEL};
always @(posedge SCK) SSELSCKr <= {SSELSCKr[1:0], SSEL};

wire SSEL_inactive = SSELr[1];
wire SSEL_active = ~SSELr[1];  // SSEL is active low
wire SSEL_startmessage = (SSELr[2:1]==2'b10);  // message starts at falling edge
wire SSEL_endmessage = (SSELr[2:1]==2'b01);  // message stops at rising edge
assign endmessage = SSEL_endmessage;
assign startmessage = SSEL_startmessage;

// bit count for one SPI byte + byte count for the message
reg [2:0] bitcnt;
initial bitcnt = 3'b000;
wire bitcnt_msb = bitcnt[2];
reg [2:0] bitcnt_wrap_r;
always @(posedge clk) bitcnt_wrap_r <= {bitcnt_wrap_r[1:0], bitcnt_msb};
wire byte_received_sync = (bitcnt_wrap_r[2:1] == 2'b10);

reg [31:0] byte_cnt_r;

reg byte_received;  // high when a byte has been received
reg [7:0] byte_data_received;

assign bit_cnt = bitcnt;

always @(posedge SCK) begin
  if(SSELSCKr[1]) bitcnt <= 3'b000;
  else bitcnt <= bitcnt + 3'b001;
end

always @(posedge SCK) begin
  if(~SSELSCKr[1])
    byte_data_received <= {byte_data_received[6:0], MOSI};
  if(~SSELSCKr[1] && bitcnt==3'b111)
    byte_received <= 1'b1;
  else byte_received <= 1'b0;
end

//reg [2:0] byte_received_r;
//always @(posedge clk) byte_received_r <= {byte_received_r[1:0], byte_received};
//wire byte_received_sync = (byte_received_r[2:1] == 2'b01);

always @(posedge clk) begin
  if(SSEL_inactive)
    byte_cnt_r <= 0;
  else if(byte_received_sync)
    byte_cnt_r <= byte_cnt_r + 1;
end

reg [7:0] byte_data_sent;

assign MISO = ~SSEL ? input_data[7-bitcnt] : 1'bZ;  // send MSB first

reg cmd_ready_r;
reg param_ready_r;
reg cmd_ready_r2;
reg param_ready_r2;
assign cmd_ready = cmd_ready_r;
assign param_ready = param_ready_r;
assign cmd_data = cmd_data_r;
assign param_data = param_data_r;
assign byte_cnt = byte_cnt_r;

always @(posedge clk) cmd_ready_r2 = byte_received_sync && byte_cnt_r == 32'h0;
always @(posedge clk) param_ready_r2 = byte_received_sync && byte_cnt_r > 32'h0;

// fill registers
always @(posedge clk) begin
  if (SSEL_startmessage)
    cmd_data_r <= 8'h00;
  else if(cmd_ready_r2)
    cmd_data_r <= byte_data_received;
  else if(param_ready_r2)
    param_data_r <= byte_data_received;
end

// delay ready signals by one clock
always @(posedge clk) begin
  cmd_ready_r <= cmd_ready_r2;
  param_ready_r <= param_ready_r2;
end

endmodule

module tmu2_clamp(
    input sys_clk,
    input sys_rst,

    output busy,

    input pipe_stb_i,
    output pipe_ack_o,
    input signed [11:0] dx,
    input signed [11:0] dy,
    input signed [17:0] tx,
    input signed [17:0] ty,

    input [10:0] tex_hres,
    input [10:0] tex_vres,
    input [10:0] dst_hres,
    input [10:0] dst_vres,

    output reg pipe_stb_o,
    input pipe_ack_i,
    output reg [10:0] dx_c,
    output reg [10:0] dy_c,
    output reg [16:0] tx_c,
    output reg [16:0] ty_c
);

always @(posedge sys_clk) begin
    if(sys_rst)
        pipe_stb_o <= 1'b0;
    else begin
        if(pipe_ack_i)
            pipe_stb_o <= 1'b0;
        if(pipe_stb_i & pipe_ack_o) begin
            if((dx[11] == 1) || (dy[11] == 1)) begin
                pipe_stb_o <= 1'b0;
            end else if((dx[10:0] >= dst_hres) || (dy[10:0] >= dst_vres)) begin
                pipe_stb_o <= 1'b0;
            end else begin
                pipe_stb_o <= 1'b1;
                dx_c <= dx[10:0];
                dy_c <= dy[10:0];
                if(tx[17] == 1) begin
                    tx_c <= 17'd0;
                end else if(tx[16:0] > {tex_hres - 11'd1, 6'd0}) begin
                    tx_c <= {tex_hres - 11'd1, 6'd0};
                end else begin
                    tx_c <= tx[16:0];
                end
                if(ty[17] == 1) begin
                    ty_c <= 17'd0;
                end else if(ty[16:0] > {tex_vres - 11'd1, 6'd0}) begin
                    ty_c <= {tex_vres - 11'd1, 6'd0};
                end else begin
                    ty_c <= ty[16:0];
                end
            end
        end
    end
end

assign pipe_ack_o = ~pipe_stb_o | pipe_ack_i;

assign busy = pipe_stb_o;

endmodule

module fcs_calculator (
  input wire clk_i,
  input wire rst_n_i,
  input wire sof_i,
  input wire eof_i,
  input wire [15:0] data_i,
  output wire [31:0] res_o,
  output wire [31:0] exp_o,
  output wire [31:0] obs_o,
  output wire val_o
);

  // Constants
  localparam LO = 1'b0;
  localparam HI = 1'b1;
  localparam [31:0] ZEROS = {32{LO}};
  localparam [31:0] ONES = {32{HI}};
  localparam [31:0] POLY = 32'h04c11db7;

  // Registers
  reg [15:0] data_z1;
  reg sof_z1;
  reg [15:0] data_z2;
  reg sof_z2;
  reg val_z3;
  reg [31:0] exp_z3;
  reg [31:0] fcs_z3;
  reg val_z4;
  reg [31:0] exp_z4;
  reg [31:0] fcs_z4;
  reg val_z5;
  reg [31:0] exp_z5;
  reg [31:0] fcs_z5;

  // Combinational Logic
  wire [31:0] data_ext = {data_z2, data_i};
  wire [31:0] fcs_ext = {fcs_z4, ZEROS[0:15]};
  wire [31:0] fcs_xor = fcs_ext ^ data_ext;
  wire [31:0] fcs_shift = fcs_ext << 1;
  wire fcs_bit = fcs_ext[31];
  wire [31:0] poly_shift = {POLY[30:0], LO};
  wire [31:0] fcs_next = fcs_shift;
  assign fcs_next[0] = fcs_bit;
  assign fcs_next = fcs_next ^ (fcs_bit ? poly_shift : ZEROS);

  // State Machine
  localparam IDLE = 2'b00;
  localparam CALC = 2'b01;
  localparam COMP = 2'b10;
  reg [1:0] state = IDLE;
  always @(posedge clk_i or negedge rst_n_i) begin
    if (~rst_n_i) begin
      state <= IDLE;
      data_z1 <= 16'h0000;
      sof_z1 <= LO;
      data_z2 <= 16'h0000;
      sof_z2 <= LO;
      val_z3 <= LO;
      exp_z3 <= 32'h00000000;
      fcs_z3 <= 32'h00000000;
      val_z4 <= LO;
      exp_z4 <= 32'h00000000;
      fcs_z4 <= 32'h00000000;
      val_z5 <= LO;
      exp_z5 <= 32'h00000000;
      fcs_z5 <= 32'h00000000;
    end else begin
      case (state)
        IDLE: begin
          if (sof_i) begin
            state <= CALC;
            data_z1 <= data_i;
            sof_z1 <= sof_i;
          end
        end
        CALC: begin
          data_z2 <= data_z1;
          sof_z2 <= sof_z1;
          fcs_z3 <= (sof_z2) ? fcs32_brev(fcs_next) : fcs_next;
          exp_z3 <= (eof_i) ? fcs_ext : exp_z3;
          val_z3 <= eof_i;
          state <= COMP;
        end
        COMP: begin
          fcs_z4 <= fcs_z3;
          exp_z4 <= exp_z3;
          fcs_z5 <= fcs32_brev(fcs_z4);
          exp_z5 <= exp_z4;
          val_z5 <= val_z4;
          val_z4 <= val_z3;
          exp_z4 <= exp_z3;
          fcs_z4 <= fcs_z3;
          state <= IDLE;
        end
      endcase
      data_z1 <= data_i;
      sof_z1 <= sof_i;
    end
  end

  // Output Assignments
  assign res_o = fcs_z3[31:0];
  assign exp_o = exp_z5[31:0];
  assign obs_o = fcs_z5[31:0];
  assign val_o = val_z5;

endmodule

module vending_machine(
  input clk, // system clock
  input btn_a, // button A
  input btn_b, // button B
  input btn_c, // button C
  input coin_slot, // 25-cent coin slot
  output reg item_x, // dispensed item X
  output reg item_y, // dispensed item Y
  output reg item_z, // dispensed item Z
  output reg out_of_stock // machine is out of stock
);

  reg [1:0] state; // state machine state
  reg [3:0] stock_x = 4; // initial stock of item X
  reg [2:0] stock_y = 3; // initial stock of item Y
  reg [2:0] stock_z = 3; // initial stock of item Z
  reg [7:0] total_money = 0; // total money inserted

  parameter IDLE = 2'b00; // state machine states
  parameter BUTTON_PRESSED = 2'b01;
  parameter ITEM_DISPENSED = 2'b10;

  always @(posedge clk) begin
    case(state)
      IDLE: begin
        if(btn_a || btn_b || btn_c) begin
          state <= BUTTON_PRESSED;
        end
      end
      BUTTON_PRESSED: begin
        if(coin_slot) begin
          total_money <= total_money + 25;
          state <= ITEM_DISPENSED;
        end else if(!btn_a && !btn_b && !btn_c) begin
          state <= IDLE;
        end
      end
      ITEM_DISPENSED: begin
        if(total_money >= 75) begin
          if(btn_a && stock_x > 0) begin
            item_x <= 1;
            stock_x <= stock_x - 1;
            total_money <= total_money - 75;
          end else if(btn_b && stock_y > 0) begin
            item_y <= 1;
            stock_y <= stock_y - 1;
            total_money <= total_money - 75;
          end else if(btn_c && stock_z > 0) begin
            item_z <= 1;
            stock_z <= stock_z - 1;
            total_money <= total_money - 75;
          end
          state <= IDLE;
        end else if(!coin_slot) begin
          state <= BUTTON_PRESSED;
        end
      end
    endcase
  end

  always @(stock_x, stock_y, stock_z) begin
    if(stock_x == 0 && stock_y == 0 && stock_z == 0) begin
      out_of_stock <= 1;
    end else begin
      out_of_stock <= 0;
    end
  end

endmodule

