module mist1032isa_arbiter_matching_queue #(
    //Queue Deap
    parameter D = 8,
    //Queue Deap_N
    parameter DN = 3,
    //Queue Flag_N
    parameter FN = 1    
)(
    input wire iCLOCK,
    input wire inRESET,
    //Flash
    input wire iFLASH,
    //Write
    input wire iWR_REQ,
    input wire [FN-1:0] iWR_FLAG,
    output wire oWR_FULL,
    //Read
    input wire iRD_REQ,
    output wire oRD_VALID,
    output wire [FN-1:0] oRD_FLAG,
    output wire oRD_EMPTY
);

// Internal signals
wire full_flag;
wire empty_flag;
wire [DN:0] count;

reg [DN:0] wr_counter;
reg [DN:0] rd_counter;
reg queue_valid[0:D-1];
reg [FN-1:0] queue_type[0:D-1];

integer i;

// Full flag indicates whether the queue is full
assign full_flag = count[DN];

// Empty flag indicates whether the queue is empty
assign empty_flag = (wr_counter == rd_counter)? 1'b1 : 1'b0;

// Count indicates the number of valid entries in the queue
assign count = wr_counter - rd_counter;

// Sequential logic for write and read operations
always @(posedge iCLOCK or negedge inRESET) begin
    if (~inRESET) begin
        // Reset the queue
        wr_counter <= {DN+1{1'b0}};
        rd_counter <= {DN+1{1'b0}};
        for (i = 0; i < D; i = i + 1) begin
            queue_valid[i] <= 1'b0;
        end
    end
    else begin
        if (iFLASH) begin
            // Clear the queue
            for (i = 0; i < D; i = i + 1) begin
                queue_valid[i] <= 1'b0;
            end
        end
        // Write operation
        if (~full_flag && iWR_REQ) begin
            wr_counter <= wr_counter + {{DN{1'b0}}, 1'b1};
            queue_valid[wr_counter[DN-1:0]] <= 1'b1;
            queue_type[wr_counter[DN-1:0]] <= iWR_FLAG;
        end
        // Read operation
        if (~empty_flag && iRD_REQ) begin
            rd_counter <= rd_counter + {{DN{1'b0}}, 1'b1};
            queue_valid[rd_counter[DN-1:0]] <= 1'b0;
        end
    end
end

// Output assignments
assign oWR_FULL = full_flag;
assign oRD_VALID = queue_valid[rd_counter[DN-1:0]] && ~iFLASH;
assign oRD_FLAG = queue_type[rd_counter[DN-1:0]];
assign oRD_EMPTY = empty_flag;

endmodule

module modbus_master (
  input clk,
  input rst,
  input start,
  input [7:0] addr,
  input [7:0] func,
  input [15:0] data,
  output reg done,
  output reg [15:0] resp
);

  // Internal signals
  reg [7:0] slave_addr;
  reg [7:0] function_code;
  reg [15:0] tx_data;
  reg [15:0] rx_data;
  reg [3:0] state;
  reg [3:0] substate;
  reg [7:0] crc;
  reg [7:0] crc_high;
  reg [7:0] crc_low;
  reg [7:0] byte_count;
  reg [7:0] coil_count;
  reg [7:0] reg_count;
  reg [7:0] byte_index;
  reg [7:0] coil_index;
  reg [7:0] reg_index;
  reg [7:0] data_len;
  reg [7:0] data_index;

  // Constants
  localparam IDLE = 0;
  localparam SEND_REQ = 1;
  localparam SEND_DATA = 2;
  localparam WAIT_RESP = 3;
  localparam PARSE_RESP = 4;
  localparam ERROR = 5;
  localparam READ_COILS = 1;
  localparam READ_HOLD_REGS = 3;

  // State machine
  always @(posedge clk) begin
    if (rst) begin
      state <= IDLE;
      substate <= 0;
      done <= 0;
      resp <= 0;
      tx_data <= 0;
      rx_data <= 0;
      crc <= 0;
      crc_high <= 0;
      crc_low <= 0;
      byte_count <= 0;
      coil_count <= 0;
      reg_count <= 0;
      byte_index <= 0;
      coil_index <= 0;
      reg_index <= 0;
      data_len <= 0;
      data_index <= 0;
    end else begin
      case (state)
        IDLE: begin
          if (start) begin
            slave_addr <= addr;
            function_code <= func;
            case (func)
              READ_COILS: begin
                tx_data <= {coil_index, coil_count};
                data_len <= (coil_count + 7) / 8;
              end
              READ_HOLD_REGS: begin
                tx_data <= {reg_index, reg_count};
                data_len <= reg_count * 2;
              end
              default: begin
                state <= ERROR;
              end
            endcase
            crc <= {8'hFF, slave_addr, function_code, tx_data};
            crc_high <= crc >> 8;
            crc_low <= crc & 8'hFF;
            state <= SEND_REQ;
          end
        end
        SEND_REQ: begin
          if (substate == 0) begin
            resp <= 0;
            substate <= 1;
          end else if (substate == 1) begin
            resp <= {slave_addr, function_code, tx_data, crc_low, crc_high};
            substate <= 2;
          end else if (substate == 2) begin
            done <= 1;
            state <= WAIT_RESP;
          end
        end
        WAIT_RESP: begin
          if (start) begin
            state <= IDLE;
          end else if (substate == 0) begin
            done <= 0;
            substate <= 1;
          end else if (substate == 1) begin
            rx_data <= data;
            substate <= 2;
          end else if (substate == 2) begin
            crc <= {8'hFF, slave_addr, function_code, rx_data};
            crc_high <= crc >> 8;
            crc_low <= crc & 8'hFF;
            state <= PARSE_RESP;
          end
        end
        PARSE_RESP: begin
          if (crc_high == data[7:0] && crc_low == data[15:8]) begin
            case (function_code)
              READ_COILS: begin
                byte_count <= data[7:0];
                state <= SEND_REQ;
              end
              READ_HOLD_REGS: begin
                byte_count <= data[7:0];
                state <= SEND_DATA;
              end
              default: begin
                state <= ERROR;
              end
            endcase
          end else begin
            state <= ERROR;
          end
        end
        SEND_DATA: begin
          if (substate == 0) begin
            resp <= {byte_count, data_len};
            substate <= 1;
          end else if (substate == 1) begin
            resp <= rx_data;
            substate <= 2;
          end else if (substate == 2) begin
            done <= 1;
            state <= WAIT_RESP;
          end
        end
        ERROR: begin
          done <= 1;
          state <= IDLE;
        end
      endcase
    end
  end

endmodule

// Modbus slave block
module modbus_slave (
  input clk,
  input rst,
  input [7:0] addr,
  input [7:0] func,
  input [15:0] data,
  output reg done,
  output reg [15:0] resp
);

  // Internal signals
  reg [7:0] slave_addr;
  reg [7:0] function_code;
  reg [15:0] tx_data;
  reg [15:0] rx_data;
  reg [3:0] state;
  reg [3:0] substate;
  reg [7:0] crc;
  reg [7:0] crc_high;
  reg [7:0] crc_low;
  reg [7:0] byte_count;
  reg [7:0] coil_count;
  reg [7:0] reg_count;
  reg [7:0] byte_index;
  reg [7:0] coil_index;
  reg [7:0] reg_index;
  reg [7:0] data_len;
  reg [7:0] data_index;

  // Constants
  localparam IDLE = 0;
  localparam WAIT_REQ = 1;
  localparam PARSE_REQ = 2;
  localparam SEND_RESP = 3;
  localparam ERROR = 4;
  localparam READ_COILS = 1;
  localparam READ_HOLD_REGS = 3;

  // State machine
  always @(posedge clk) begin
    if (rst) begin
      state <= IDLE;
      substate <= 0;
      done <= 0;
      resp <= 0;
      tx_data <= 0;
      rx_data <= 0;
      crc <= 0;
      crc_high <= 0;
      crc_low <= 0;
      byte_count <= 0;
      coil_count <= 0;
      reg_count <= 0;
      byte_index <= 0;
      coil_index <= 0;
      reg_index <= 0;
      data_len <= 0;
      data_index <= 0;
    end else begin
      case (state)
        IDLE: begin
          if (addr == slave_addr && func == READ_COILS) begin
            coil_index <= data[15:8];
            coil_count <= data[7:0];
            state <= SEND_RESP;
          end else if (addr == slave_addr && func == READ_HOLD_REGS) begin
            reg_index <= data[15:8];
            reg_count <= data[7:0];
            state <= WAIT_REQ;
          end
        end
        WAIT_REQ: begin
          if (addr == slave_addr && func == READ_HOLD_REGS) begin
            state <= PARSE_REQ;
          end else if (addr != slave_addr || func != READ_HOLD_REGS) begin
            state <= ERROR;
          end
        end
        PARSE_REQ: begin
          if (data_index == 0) begin
            byte_count <= data[7:0];
            data_len <= byte_count * 8;
            tx_data <= 0;
            byte_index <= 0;
            data_index <= 1;
            state <= SEND_RESP;
          end
        end
        SEND_RESP: begin
          if (substate == 0) begin
            resp <= {slave_addr, function_code, byte_count, tx_data};
            substate <= 1;
          end else if (substate == 1) begin
            crc <= {8'hFF, slave_addr, function_code, byte_count, tx_data};
            crc_high <= crc >> 8;
            crc_low <= crc & 8'hFF;
            resp <= {crc_low, crc_high};
            substate <= 2;
          end else if (substate == 2) begin
            done <= 1;
            state <= IDLE;
          end
        end
        ERROR: begin
          done <= 1;
          state <= IDLE;
        end
      endcase
    end
  end

endmodule

