module spi_interface #(
    parameter ADDR_SPACE = 256
)(
    input clk,
    input rst,
    input  [ADDR_SPACE_BITS-1:0] reg_addr,
    input  write,
    input  new_req,
    input  [7:0] write_value,
    output [7:0] read_value,
    input  in_transaction,
    output [8*ADDR_SPACE-1:0] rx_arr,
    output rx_busy,
    output new_rx,
    input [8*ADDR_SPACE-1:0] tx_arr,
    output tx_busy
);

parameter ADDR_SPACE_BITS = $clog2(ADDR_SPACE);
parameter WORD_SIZE = 8;
parameter ADDR_BITS = ADDR_SPACE * 8;
parameter ADDR_BIT_COUNT = $clog2(ADDR_BITS);

reg [ADDR_BITS-1:0] rx_arr_q, rx_arr_d;
reg rx_busy_q, rx_busy_d, tx_busy_q, tx_busy_d, new_rx_q, new_rx_d;
assign rx_arr = rx_arr_q;
assign rx_busy = rx_busy_q;
assign new_rx  = new_rx_q;
assign tx_busy = tx_busy_q;

reg [7:0] read_value_d, read_value_q;
assign read_value = read_value_q;

reg old_write_d, old_write_q, old_transaction_d, old_transaction_q;

always @(*) begin
    read_value_d = read_value_q;
    old_write_d  = old_write_q;
    old_transaction_d = in_transaction;
    rx_busy_d = in_transaction;
    tx_busy_d = in_transaction;
    new_rx_d  = new_rx_q;
    rx_arr_d  = rx_arr_q;
    if (new_req) begin
        read_value_d = tx_arr[{reg_addr,3'b0}+:WORD_SIZE];
        if (write) begin
            rx_arr_d[{reg_addr,3'b0}+:WORD_SIZE] = write_value;
        end
    end
    if (in_transaction) begin
        old_write_d = write;
    end else begin
        new_rx_d = old_transaction_q & old_write_q;
    end
end

always @(posedge clk) begin
    if (rst) begin
        read_value_q <= 0;
        rx_busy_q <= 0;
        tx_busy_q <= 0;
        new_rx_q  <= 0;
        rx_arr_q <= 0;
        old_write_q <= 0;
        old_transaction_q <= 0;
    end else begin
        read_value_q <= read_value_d;
        rx_busy_q <= rx_busy_d;
        tx_busy_q <= tx_busy_d;
        new_rx_q  <= new_rx_d;
        rx_arr_q  <= rx_arr_d;
        old_write_q <= old_write_d;
        old_transaction_q <= old_transaction_d;
    end
end

endmodule

module top_module (
  input clk,
  input reset, // Synchronous active-high reset
  input [7:0] in1,
  input [7:0] in2,
  input select,
  output [7:0] out
);

  wire [7:0] adder1_out;
  wire [7:0] adder2_out;
  wire [7:0] and_out;

  // Instantiate the two adder modules
  adder adder1 (
    .clk(clk),
    .reset(reset),
    .in1(in1),
    .in2(in2),
    .out(adder1_out)
  );

  adder adder2 (
    .clk(clk),
    .reset(reset),
    .in1(in1),
    .in2(in2),
    .out(adder2_out)
  );

  // Instantiate the control logic module
  control_logic control (
    .select(select),
    .adder1_out(adder1_out),
    .adder2_out(adder2_out),
    .and_out(and_out)
  );

  // Output the result of the AND operation
  assign out = and_out;

endmodule

module adder (
  input clk,
  input reset, // Synchronous active-high reset
  input [7:0] in1,
  input [7:0] in2,
  output [7:0] out
);

  reg [7:0] sum;

  always @(posedge clk) begin
    if (reset) begin
      sum <= 8'd0;
    end else begin
      sum <= in1 + in2;
    end
  end

  assign out = sum;

endmodule

module control_logic (
  input select,
  input [7:0] adder1_out,
  input [7:0] adder2_out,
  output [7:0] and_out
);

  assign and_out = (select) ? (adder1_out & adder2_out) : (adder2_out & adder1_out);

endmodule

module MUX4_1(A, B, C, D, S1, S0, Y);
  input [3:0] A, B, C, D;
  input [1:0] S1, S0;
  output [3:0] Y;

  wire [3:0] Y1, Y2;
  wire not_S0, not_S1;

  // Implementing two 2-to-1 multiplexers
  assign not_S0 = ~S0;
  assign not_S1 = ~S1;

  assign Y1[0] = (not_S0 & A[0]) | (S0 & B[0]);
  assign Y1[1] = (not_S0 & A[1]) | (S0 & B[1]);
  assign Y1[2] = (not_S0 & A[2]) | (S0 & B[2]);
  assign Y1[3] = (not_S0 & A[3]) | (S0 & B[3]);

  assign Y2[0] = (not_S1 & C[0]) | (S1 & D[0]);
  assign Y2[1] = (not_S1 & C[1]) | (S1 & D[1]);
  assign Y2[2] = (not_S1 & C[2]) | (S1 & D[2]);
  assign Y2[3] = (not_S1 & C[3]) | (S1 & D[3]);

  // Implementing the 4-to-1 multiplexer
  assign Y[0] = (not_S1 & Y1[0]) | (S1 & Y2[0]);
  assign Y[1] = (not_S1 & Y1[1]) | (S1 & Y2[1]);
  assign Y[2] = (not_S1 & Y1[2]) | (S1 & Y2[2]);
  assign Y[3] = (not_S1 & Y1[3]) | (S1 & Y2[3]);

endmodule

module counter(clk, rst, count);
  input clk, rst;
  output reg [3:0] count;

  always @(posedge clk, posedge rst) begin
    if (rst) begin
      count <= 4'b0;
    end else if (count == 4'b1001) begin
      count <= 4'b0;
    end else begin
      count <= count + 1;
    end
  end

endmodule

module axis_ll_bridge #
(
    parameter DATA_WIDTH = 8
)
(
    input  wire                   clk,
    input  wire                   rst,

    /*
     * AXI input
     */
    input  wire [DATA_WIDTH-1:0]  s_axis_tdata,
    input  wire                   s_axis_tvalid,
    output wire                   s_axis_tready,
    input  wire                   s_axis_tlast,

    /*
     * LocalLink output
     */
    output wire [DATA_WIDTH-1:0]  ll_data_out,
    output wire                   ll_sof_out_n,
    output wire                   ll_eof_out_n,
    output wire                   ll_src_rdy_out_n,
    input  wire                   ll_dst_rdy_in_n
);

reg last_tlast = 1'b1;
reg [DATA_WIDTH-1:0] last_data;

always @(posedge clk) begin
    if (rst) begin
        last_tlast = 1'b1;
        last_data = 0;
    end else begin
        if (s_axis_tvalid && s_axis_tready) begin
            last_tlast = s_axis_tlast;
            last_data = s_axis_tdata;
        end
    end
end

// high for packet length 1 -> cannot set SOF and EOF in same cycle
// invalid packets are discarded
wire invalid = s_axis_tvalid && s_axis_tlast && last_tlast;

assign s_axis_tready = !ll_dst_rdy_in_n;

assign ll_data_out = s_axis_tdata;
assign ll_sof_out_n = !(last_tlast && s_axis_tvalid && !invalid) && (s_axis_tvalid && s_axis_tready && !invalid);
assign ll_eof_out_n = !(s_axis_tlast && !invalid) && (s_axis_tvalid && s_axis_tready && !invalid);
assign ll_src_rdy_out_n = !(s_axis_tvalid && !invalid) && (s_axis_tvalid && s_axis_tready && !invalid);

endmodule

module ripple_encoder (
    input [3:0] A,
    input [3:0] B,
    input [7:0] in,
    input select,
    output reg out,
    output reg valid,
    output reg [2:0] index,
    output [3:0] SUM,
    output reg [3:0] result
);

    wire [3:0] ripple_carry_out;
    wire [7:0] priority_encoder_out;

    // Ripple Carry Adder module instantiation
    ripple_carry_adder adder_inst(
        .A(A),
        .B(B),
        .Cin(1'b0),
        .S(SUM),
        .Cout(ripple_carry_out)
    );

    // Priority Encoder module instantiation
    priority_encoder encoder_inst(
        .in(in),
        .out(priority_encoder_out),
        .valid(valid),
        .index(index)
    );

    always @(*) begin
        if (select == 1'b0) begin
            // Enable Ripple Carry Adder
            out = 1'b0;
            result = SUM;
        end else begin
            // Enable Priority Encoder
            out = 1'b1;
            result = index + SUM;
        end
    end

endmodule

// Ripple Carry Adder module
module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output reg [3:0] S,
    output reg Cout
);

    always @(*) begin
        S = A + B + Cin;
        Cout = (S > 4'b1111) ? 1'b1 : 1'b0;
    end

endmodule

// Priority Encoder module
module priority_encoder (
    input [7:0] in,
    output reg [2:0] out,
    output reg valid,
    output reg [2:0] index
);

    always @(*) begin
        casez(in)
            8'b00000001: begin out = 3'b000; valid = 1'b1; index = 3'b000; end
            8'b00000010: begin out = 3'b001; valid = 1'b1; index = 3'b001; end
            8'b00000100: begin out = 3'b010; valid = 1'b1; index = 3'b010; end
            8'b00001000: begin out = 3'b011; valid = 1'b1; index = 3'b011; end
            8'b00010000: begin out = 3'b100; valid = 1'b1; index = 3'b100; end
            8'b00100000: begin out = 3'b101; valid = 1'b1; index = 3'b101; end
            8'b01000000: begin out = 3'b110; valid = 1'b1; index = 3'b110; end
            8'b10000000: begin out = 3'b111; valid = 1'b1; index = 3'b111; end
            default: begin out = 3'b000; valid = 1'b0; index = 3'b000; end
        endcase
    end

endmodule

module quadrature_decoder(
  input clk,
  input enable_i,
  input reset_i,
  input quadA_i,
  input quadB_i,
  output reg direction_o,
  output reg count_pulse_o,
  output reg error_o
);

reg quadA, quadB, quadA_old, quadB_old;
reg [1:0] state;
reg [7:0] count;

parameter IDLE = 2'b00, FORWARD = 2'b01, REVERSE = 2'b10;

always @(posedge clk) begin
  if (reset_i) begin
    state <= IDLE;
    count <= 8'b0;
    direction_o <= 1'b0;
    count_pulse_o <= 8'b0;
    error_o <= 1'b0;
  end else if (enable_i) begin
    quadA <= quadA_i;
    quadB <= quadB_i;
    quadA_old <= quadA;
    quadB_old <= quadB;
    case (state)
      IDLE: begin
        if (quadA == 1'b1 && quadB == 1'b0) begin
          state <= FORWARD;
        end else if (quadA == 1'b0 && quadB == 1'b1) begin
          state <= REVERSE;
        end else if (quadA != quadA_old || quadB != quadB_old) begin
          error_o <= 1'b1;
        end
      end
      FORWARD: begin
        if (quadA == 1'b0 && quadB == 1'b0) begin
          count <= count + 8'b1;
          count_pulse_o <= count;
          direction_o <= 1'b0;
          state <= IDLE;
        end else if (quadA == 1'b1 && quadB == 1'b1) begin
          count <= count - 8'b1;
          count_pulse_o <= count;
          direction_o <= 1'b1;
          state <= IDLE;
        end else if (quadA != quadA_old || quadB != quadB_old) begin
          error_o <= 1'b1;
        end
      end
      REVERSE: begin
        if (quadA == 1'b1 && quadB == 1'b1) begin
          count <= count + 8'b1;
          count_pulse_o <= count;
          direction_o <= 1'b1;
          state <= IDLE;
        end else if (quadA == 1'b0 && quadB == 1'b0) begin
          count <= count - 8'b1;
          count_pulse_o <= count;
          direction_o <= 1'b0;
          state <= IDLE;
        end else if (quadA != quadA_old || quadB != quadB_old) begin
          error_o <= 1'b1;
        end
      end
    endcase
  end
end

endmodule

module shift_register (
  input clk,
  input load,
  input [7:0] data_in,
  output [7:0] data_out
);

  reg [7:0] shift_reg;

  always @(posedge clk) begin
    if (load) begin
      shift_reg <= data_in;
    end else begin
      shift_reg <= {shift_reg[6:0], shift_reg[7]};
    end
  end

  assign data_out = shift_reg;

endmodule

module byte_swap(
