module priority_encoder (
    input [7:0] a, b, c, d,
    output [1:0] min_index);

  wire a_lt_b, a_lt_c, a_lt_d;
  wire b_lt_c, b_lt_d;
  wire c_lt_d;

  assign a_lt_b = a < b;
  assign a_lt_c = a < c;
  assign a_lt_d = a < d;
  assign b_lt_c = b < c;
  assign b_lt_d = b < d;
  assign c_lt_d = c < d;

  always @(*) begin
    if (a_lt_b && a_lt_c && a_lt_d)
      min_index = 2'b00;
    else if (b_lt_c && b_lt_d)
      min_index = 2'b01;
    else if (c_lt_d)
      min_index = 2'b10;
    else
      min_index = 2'b11;
  end

endmodule

