module timetag_interface (
    input clk,
    input cmd_wr,
    input [7:0] cmd_in,
    input data_rdy,
    input [7:0] data,
    output reg data_ack,
    output reg [1:0] photon_pol,
    output reg [15:0] photon_time
);

// Internal state
reg [3:0] state;
reg [15:0] timetag;

// Constants
localparam STATE_IDLE = 4'd0;
localparam STATE_WAIT_CMD_ACK = 4'd1;
localparam STATE_WAIT_DATA_RDY = 4'd2;
localparam STATE_WAIT_DATA_ACK = 4'd3;

// Command constants
localparam CMD_RESET = 8'h00;
localparam CMD_ENABLE = 8'h01;
localparam CMD_DISABLE = 8'h02;
localparam CMD_SET_CLOCK_FREQ = 8'h03;

// Command state
reg [7:0] cmd;
reg cmd_ack;

// Data state
reg data_ack_int;
reg [1:0] photon_pol_int;
reg [15:0] photon_time_int;

// State machine
always @(posedge clk) begin
    case (state)
        STATE_IDLE:
            if (cmd_wr) begin
                cmd <= cmd_in;
                cmd_ack <= 0;
                state <= STATE_WAIT_CMD_ACK;
            end
            else if (data_rdy) begin
                timetag <= data;
                data_ack_int <= 0;
                photon_pol_int <= timetag[15];
                photon_time_int <= timetag[14:0];
                state <= STATE_WAIT_DATA_ACK;
            end
        STATE_WAIT_CMD_ACK:
            if (cmd_ack) begin
                state <= STATE_IDLE;
            end
        STATE_WAIT_DATA_RDY:
            if (data_rdy) begin
                timetag <= data;
                data_ack_int <= 0;
                photon_pol_int <= timetag[15];
                photon_time_int <= timetag[14:0];
                state <= STATE_WAIT_DATA_ACK;
            end
        STATE_WAIT_DATA_ACK:
            if (data_ack_int) begin
                data_ack <= 1;
                photon_pol <= photon_pol_int;
                photon_time <= photon_time_int;
                state <= STATE_IDLE;
            end
    endcase
end

// Command logic
always @(posedge clk) begin
    case (cmd)
        CMD_RESET:
            if (state == STATE_WAIT_CMD_ACK) begin
                cmd_ack <= 1;
            end
        CMD_ENABLE:
            if (state == STATE_WAIT_CMD_ACK) begin
                cmd_ack <= 1;
            end
        CMD_DISABLE:
            if (state == STATE_WAIT_CMD_ACK) begin
                cmd_ack <= 1;
            end
        CMD_SET_CLOCK_FREQ:
            if (state == STATE_WAIT_CMD_ACK) begin
                cmd_ack <= 1;
            end
    endcase
end

// Data acknowledge logic
always @(posedge clk) begin
    if (state == STATE_WAIT_DATA_ACK) begin
        data_ack_int <= 1;
    end
end

endmodule

