module pong(
    input clk,
    input reset,
    input p1_up,
    input p1_down,
    input p2_up,
    input p2_down,
    output reg [9:0] p1_y,
    output reg [9:0] p2_y,
    output reg [9:0] ball_x,
    output reg [9:0] ball_y,
    output reg dir_x,
    output reg dir_y,
    output reg outofbounds
);

// Constants
localparam SCREEN_WIDTH = 640;
localparam SCREEN_HEIGHT = 480;
localparam PADDLE_WIDTH = 10;
localparam PADDLE_HEIGHT = 50;
localparam BALL_DIAMETER = 10;
localparam BALL_RADIUS = BALL_DIAMETER / 2;
localparam BALL_SPEED = 5;

// Variables
reg [9:0] p1_pos;
reg [9:0] p2_pos;
reg [9:0] ball_pos_x;
reg [9:0] ball_pos_y;
reg [1:0] ball_dir;
reg [3:0] ball_speed;
reg [9:0] ball_vel_x;
reg [9:0] ball_vel_y;
reg [3:0] p1_vel;
reg [3:0] p2_vel;

// Initial values
initial begin
    p1_pos = SCREEN_HEIGHT / 2 - PADDLE_HEIGHT / 2;
    p2_pos = SCREEN_HEIGHT / 2 - PADDLE_HEIGHT / 2;
    ball_pos_x = SCREEN_WIDTH / 2 - BALL_RADIUS;
    ball_pos_y = SCREEN_HEIGHT / 2 - BALL_RADIUS;
    ball_dir = 2'b11;
    ball_speed = BALL_SPEED;
    ball_vel_x = BALL_SPEED;
    ball_vel_y = 0;
    p1_vel = 0;
    p2_vel = 0;
end

// Update paddles
always @ (posedge clk) begin
    if (reset) begin
        p1_pos <= SCREEN_HEIGHT / 2 - PADDLE_HEIGHT / 2;
        p2_pos <= SCREEN_HEIGHT / 2 - PADDLE_HEIGHT / 2;
    end else begin
        // Player 1
        if (p1_up && !p1_down) begin
            p1_vel <= -BALL_SPEED;
        end else if (!p1_up && p1_down) begin
            p1_vel <= BALL_SPEED;
        end else begin
            p1_vel <= 0;
        end

        // Player 2
        if (p2_up && !p2_down) begin
            p2_vel <= -BALL_SPEED;
        end else if (!p2_up && p2_down) begin
            p2_vel <= BALL_SPEED;
        end else begin
            p2_vel <= 0;
        end

        p1_pos <= p1_pos + p1_vel;
        p2_pos <= p2_pos + p2_vel;

        // Check for paddle collisions
        if (ball_pos_x <= PADDLE_WIDTH && ball_pos_y + BALL_DIAMETER >= p1_pos && ball_pos_y <= p1_pos + PADDLE_HEIGHT) begin
            ball_dir <= 2'b01;
            ball_speed <= ball_speed + 1;
            ball_vel_x <= -ball_speed;
            ball_vel_y <= (ball_pos_y + BALL_RADIUS - p1_pos - PADDLE_HEIGHT / 2) / 10;
        end else if (ball_pos_x + BALL_DIAMETER >= SCREEN_WIDTH - PADDLE_WIDTH && ball_pos_y + BALL_DIAMETER >= p2_pos && ball_pos_y <= p2_pos + PADDLE_HEIGHT) begin
            ball_dir <= 2'b10;
            ball_speed <= ball_speed + 1;
            ball_vel_x <= ball_speed;
            ball_vel_y <= (ball_pos_y + BALL_RADIUS - p2_pos - PADDLE_HEIGHT / 2) / 10;
        end
    end
end

// Update ball
always @ (posedge clk) begin
    if (reset) begin
        ball_pos_x <= SCREEN_WIDTH / 2 - BALL_RADIUS;
        ball_pos_y <= SCREEN_HEIGHT / 2 - BALL_RADIUS;
        ball_dir <= 2'b11;
        ball_speed <= BALL_SPEED;
        ball_vel_x <= BALL_SPEED;
        ball_vel_y <= 0;
    end else begin
        // Update position
        ball_pos_x <= ball_pos_x + ball_vel_x;
        ball_pos_y <= ball_pos_y + ball_vel_y;

        // Check for wall collisions
        if (ball_pos_y <= 0) begin
            ball_vel_y <= BALL_SPEED;
        end else if (ball_pos_y + BALL_DIAMETER >= SCREEN_HEIGHT) begin
            ball_vel_y <= -BALL_SPEED;
        end

        // Check for out of bounds
        if (ball_pos_x <= 0) begin
            outofbounds <= 1;
        end else if (ball_pos_x + BALL_DIAMETER >= SCREEN_WIDTH) begin
            outofbounds <= 1;
        end

        // Check for scoring
        if (ball_pos_x <= 0 || ball_pos_x + BALL_DIAMETER >= SCREEN_WIDTH) begin
            ball_speed <= BALL_SPEED;
            ball_dir <= 2'b11;
            ball_vel_x <= BALL_SPEED;
            ball_vel_y <= 0;
            if (ball_pos_x <= 0) begin
                p2_y <= p2_y + 1;
            end else begin
                p1_y <= p1_y + 1;
            end
        end

        // Check for paddle collisions
        if (ball_dir == 2'b01 && ball_pos_x <= PADDLE_WIDTH) begin
            ball_dir <= 2'b10;
            ball_speed <= ball_speed + 1;
            ball_vel_x <= ball_speed;
            ball_vel_y <= (ball_pos_y + BALL_RADIUS - p1_pos - PADDLE_HEIGHT / 2) / 10;
        end else if (ball_dir == 2'b10 && ball_pos_x + BALL_DIAMETER >= SCREEN_WIDTH - PADDLE_WIDTH) begin
            ball_dir <= 2'b01;
            ball_speed <= ball_speed + 1;
            ball_vel_x <= -ball_speed;
            ball_vel_y <= (ball_pos_y + BALL_RADIUS - p2_pos - PADDLE_HEIGHT / 2) / 10;
        end
    end
end

// Assign outputs
assign p1_y = p1_pos;
assign p2_y = p2_pos;
assign ball_x = ball_pos_x;
assign ball_y = ball_pos_y;
assign dir_x = (ball_dir == 2'b01) ? -1 : 1;
assign dir_y = (ball_dir == 2'b10) ? -1 : 1;

endmodule

module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] d,    // 8-bit input for the shift register
    input shift,      // Shift input for the shift register
    input select,     // Select input to choose between shift register and counter
    output [7:0] q    // 8-bit output from the active module
);

wire [7:0] shift_reg_output;
wire [3:0] counter_output;

shift_register shift_reg_inst (
    .clk(clk),
    .d(d),
    .shift(shift),
    .q(shift_reg_output)
);

binary_counter counter_inst (
    .clk(clk),
    .reset(reset),
    .q(counter_output)
);

adder adder_inst (
    .a(shift_reg_output),
    .b({4'b0, counter_output}),
    .sum(q)
);

assign q = (select) ? adder_inst.sum : 8'b0;

endmodule

module shift_register (
    input clk,
    input [7:0] d,
    input shift,
    output [7:0] q
);

reg [7:0] q_reg;

always @(posedge clk) begin
    if (shift) begin
        q_reg <= {q_reg[6:0], d};
    end else begin
        q_reg <= d;
    end
end

assign q = q_reg;

endmodule

module binary_counter (
    input clk,
    input reset,
    output [3:0] q
);

reg [3:0] count;

always @(posedge clk) begin
    if (reset) begin
        count <= 4'b0;
    end else begin
        count <= count + 1;
    end
end

assign q = count;

endmodule

module adder (
