        .rst(rst), .to_iram_block(program_counter) );
  increment_pc inc_pc1 ( .from_pc(program_counter), .to_mux_branch(pc_4) );
  iram_block iram_block1 ( .from_pc(program_counter), .flush(flush), .from_iram(
        from_iram), .to_iram({instruction[31:0], to_iram[29:0]}), .to_if_id_reg(instruction_fetch) );
