module CC_Delay(
    input clk,
    input reset,
    input [WIDTH-1:0] data,
    output reg [WIDTH-1:0] out
);

  parameter WIDTH = 4;
  parameter DELAY = 1;

  reg [WIDTH-1:0] buffer [0:DELAY-1];

  integer i;

  always @(posedge clk) begin
    if (reset) begin
      for (i = 0; i < DELAY; i = i + 1) begin
        buffer[i] <= 0;
      end
    end else begin
      buffer[0] <= data;
      for (i = 1; i < DELAY; i = i + 1) begin
        buffer[i] <= buffer[i-1];
      end
    end
  end

  assign out = buffer[DELAY-1];

endmodule

