module instruction_fetch (
    input [31:0] jump_address,
    input [31:0] branch_target,
    input [31:0] from_iram,
    input flush,
    input clk,
    input rst,
    input [1:0] pcsrc,
    input jump,
    input pcwrite,
    output reg [31:0] to_iram,
    output reg [31:0] pc_4,
    output reg [31:0] instruction_fetch
);

    // Internal wires
    wire [31:0] data_mux_branch_i;
    wire [31:0] data_mux_jump_i;
    wire [31:0] data_pc_i;
    wire [31:0] pc_next;
    wire [31:0] pc_branch;
    wire [31:0] pc_jump;

    // Program counter
    always @(posedge clk, posedge rst) begin
        if (rst) begin
            pc_4 <= 32'h0;
        end else if (flush) begin
            pc_4 <= 32'h0;
        end else if (pcwrite) begin
            pc_4 <= pc_next;
        end
    end

    // Increment program counter by 4
    assign pc_next = pc_4 + 32'h4;

    // Branch program counter
    assign pc_branch = pc_4 + branch_target;

    // Jump program counter
    assign pc_jump = jump_address;

    // Mux for branch and jump targets
    mux_branch mux_branch1 (
        .from_increment_pc(pc_4),
        .branch_target(branch_target),
        .pcsrc(pcsrc),
        .to_mux_jump(data_mux_branch_i)
    );
    mux_jump mux_jump1 (
        .jump_address(jump_address),
        .from_mux_branch(data_mux_branch_i),
        .jump(jump),
        .to_pc(data_mux_jump_i)
    );

    // Program counter
    pc pc1 (
        .from_mux_jump(data_mux_jump_i),
        .pcwrite(pcwrite),
        .clk(clk),
        .rst(rst),
        .to_iram_block(data_pc_i),
        .clk__L2_N1(clk__L2_N1),
        .clk__L2_N2(clk__L2_N2),
        .clk__L2_N3(clk__L2_N3),
        .clk__L2_N4(clk__L2_N4)
    );

    // Increment program counter by 4
    increment_pc inc_pc1 (
        .from_pc(data_pc_i),
        .to_mux_branch(pc_4)
    );

    // Instruction memory block
    iram_block iram_block1 (
        .from_pc(data_pc_i),
        .flush(flush),
        .from_iram(from_iram),
        .to_iram({1'b0, 1'b0, to_iram[29:0]}),
        .to_if_id_reg(instruction_fetch)
    );

endmodule

module top_module (
    input A, B,
    input [15:0] data_in_port1,
    input write_en_port1,
    output X,
    output [15:0] Y
);

    // Define the 16-bit dual-port RAM module
    reg [15:0] ram [0:65535];
    always @(posedge write_en_port1) begin
        ram[{A,B}] <= data_in_port1;
    end

    // Define the 4-to-16 decoder module
    reg [15:0] decoder_out;
    always @(*) begin
        case (ram[{A,B}])
            16'h0000: decoder_out = 16'hFFFF;
            16'h0001: decoder_out = 16'hFFF0;
            16'h0002: decoder_out = 16'hFF0F;
            16'h0003: decoder_out = 16'hFF00;
            16'h0004: decoder_out = 16'hF0FF;
            16'h0005: decoder_out = 16'hF0F0;
            16'h0006: decoder_out = 16'hF00F;
            16'h0007: decoder_out = 16'hF000;
            16'h0008: decoder_out = 16'h0FFF;
            16'h0009: decoder_out = 16'h0FF0;
            16'h000A: decoder_out = 16'h0F0F;
            16'h000B: decoder_out = 16'h0F00;
            16'h000C: decoder_out = 16'h00FF;
            16'h000D: decoder_out = 16'h00F0;
            16'h000E: decoder_out = 16'h000F;
            16'h000F: decoder_out = 16'h0000;
            default: decoder_out = 16'h0000;
        endcase
    end

    // Assign the outputs
    assign X = ram[{A,B}];
