module arb_block (
  input [n-1:0] req,
  input clk,
  input rst,
  output gnt
);

  parameter n = 4; // number of devices on the bus

  reg [n-1:0] req_priority;
  reg [n-1:0] req_granted;
  reg [n-1:0] req_latched;
  reg [n-1:0] req_valid;
  reg [n-1:0] req_delay;
  reg [n-1:0] req_delayed;
  reg [n-1:0] req_grant;
  reg [n-1:0] req_grant_latched;
  reg [n-1:0] req_grant_valid;

  always @ (posedge clk or posedge rst) begin
    if (rst) begin
      req_priority <= 0;
      req_granted <= 0;
      req_latched <= 0;
      req_valid <= 0;
      req_delay <= 0;
      req_delayed <= 0;
      req_grant <= 0;
      req_grant_latched <= 0;
      req_grant_valid <= 0;
    end
    else begin
      // priority scheme
      req_priority <= req & ~req_valid;

      // latching
      req_latched <= req_priority;

      // valid flag
      req_valid <= req_priority | req_delayed;

      // delay
      req_delay <= req_valid & ~req_granted;
      req_delayed <= req_delay;

      // grant
      req_grant <= req_latched & req_valid;
      req_grant_latched <= req_grant;
      req_grant_valid <= req_grant_latched;

      // granted flag
      req_granted <= req_grant_valid;
    end
  end

  assign gnt = req_granted;

endmodule

module i2s_tx #(parameter DATA_WIDTH = 16, parameter LR_BIT = 7) (
    input wire clk,
    input wire [DATA_WIDTH-1:0] left_chan,
    input wire [DATA_WIDTH-1:0] right_chan,
    output reg sdata,
    output wire mck,
    output wire sck,
    output wire lrclk
);

    parameter SCK_BIT = LR_BIT - 6;
    parameter MCK_BIT = 0;

    reg [9:0] mck_div = 0;
    reg [DATA_WIDTH-1:0] ch_data = 0;
    reg [31:0] fake_data = 0;
    reg lrclk_prev = 1'b1;
    reg sck_prev = 1'b0;

    wire lrclk_change = ~(lrclk_prev == lrclk);
    wire sck_neg = (sck_prev==1'b1 && sck==1'b0);
    wire [31:0] sgnd_data = fake_data - 32'b10000000000000000000000000000000;

    assign mck = mck_div[MCK_BIT];
    assign lrclk = mck_div[LR_BIT];
    assign sck = mck_div[SCK_BIT];

    always @(posedge clk) begin
        mck_div <= mck_div + 1'b1;
        lrclk_prev <= lrclk;
        sck_prev <= sck;

        if (sck_neg) begin
            if (lrclk_change) begin
                ch_data <= (lrclk) ? left_chan : right_chan;
                sdata <= ch_data[DATA_WIDTH-1];
                fake_data <= fake_data + ((LR_BIT==9) ? 32'd178956972 : 32'd44739243);
            end else begin
                ch_data <= ch_data << 1;
            end
        end
    end

endmodule

