module binary_adder(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout
);

    wire [3:0] xor1_out;
    wire [3:0] and1_out;
    wire [3:0] xor2_out;
    wire [3:0] and2_out;
    wire [3:0] and3_out;
    wire [3:0] or1_out;
    wire [3:0] or2_out;
    wire [3:0] or3_out;
    wire and4_out;

    // First bit
    xor xor1(A[0], B[0], Cin, xor1_out[0]);
    and and1(A[0], B[0], and1_out[0]);
    and and2(A[0], Cin, and2_out[0]);
    xor xor2(xor1_out[0], and1_out[0], and2_out[0], Sum[0]);
    and and3(A[0], B[0], or1_out[0]);
    or or1(and1_out[0], and2_out[0], or1_out[0]);
    or or2(xor1_out[0], and3_out[0], or2_out[0]);
    or or3(or1_out[0], or2_out[0], Cout);

    // Second bit
    xor xor3(A[1], B[1], or2_out[1], xor1_out[1]);
    and and4(A[1], B[1], and4_out);
    and and5(A[1], or2_out[1], and2_out[1]);
    xor xor4(xor1_out[1], and4_out, and5_out[1], Sum[1]);
    and and6(A[1], B[1], or3_out[1]);
    or or4(and4_out, and5_out[1], or1_out[1]);
    or or5(xor1_out[1], and6_out[1], or2_out[1]);
    or or6(or1_out[1], or2_out[1], Cout);

    // Third bit
    xor xor5(A[2], B[2], or2_out[2], xor1_out[2]);
    and and7(A[2], B[2], and7_out);
    and and8(A[2], or2_out[2], and8_out);
    xor xor6(xor1_out[2], and7_out, and8_out, Sum[2]);
    and and9(A[2], B[2], or3_out[2]);
    or or7(and7_out, and8_out, or1_out[2]);
    or or8(xor1_out[2], and9_out[2], or2_out[2]);
    or or9(or1_out[2], or2_out[2], Cout);

    // Fourth bit
    xor xor7(A[3], B[3], or2_out[3], xor1_out[3]);
    and and10(A[3], B[3], and10_out);
    and and11(A[3], or2_out[3], and11_out);
    xor xor8(xor1_out[3], and10_out, and11_out, Sum[3]);
    and and12(A[3], B[3], or3_out[3]);
    or or10(and10_out, and11_out, or1_out[3]);
    or or11(xor1_out[3], and12_out[3], or2_out[3]);
    or or12(or1_out[3], or2_out[3], Cout);

endmodule

module wallace_multiplier (
    input signed [7:0] a,
    input signed [7:0] b,
    input signed_ctrl,
    output signed [15:0] result
);

// Pipeline registers
reg signed [7:0] a_reg, b_reg;
reg signed_ctrl_reg;
reg signed [15:0] partial_sum_reg [0:2];

// Wallace tree multiplier components
wire signed [7:0] a1, b1, a2, b2, a3, b3;
wire signed [11:0] p1, p2, p3, p4, p5;
wire signed [15:0] s1, s2, s3;

// Assign inputs to pipeline registers
always @(posedge clk) begin
    a_reg <= a;
    b_reg <= b;
    signed_ctrl_reg <= signed_ctrl;
end

// Stage 1
assign a1 = a_reg;
assign b1 = signed_ctrl_reg ? b_reg : {1'b0, b_reg[6:0]};
assign p1 = a1 * b1;
assign s1 = {p1[5:0], 4'b0};

// Stage 2
assign a2 = a_reg;
assign b2 = signed_ctrl_reg ? {1'b0, b_reg[7:0]} : b_reg;
assign p2 = a2 * b2;
assign s2 = {p2[5:0], 4'b0};

// Stage 3
assign a3 = a_reg;
assign b3 = signed_ctrl_reg ? {1'b0, b_reg[7:1]} : {1'b0, b_reg[6:0]};
assign p3 = a3 * b3;
assign p4 = a3 * b2;
assign p5 = a1 * b3;
assign s3 = {p3[8:3], p4[8:3], p5[8:3]};

// Stage 4
always @(posedge clk) begin
    partial_sum_reg[0] <= s1;
    partial_sum_reg[1] <= s2;
    partial_sum_reg[2] <= s3;
end

// Final stage
assign result = partial_sum_reg[0] + partial_sum_reg[1] + partial_sum_reg[2];

endmodule

module f3m_mult3(clk, reset, 
                 a0, b0, c0,
                 a1, b1, c1, 
                 a2, b2, c2, 
                 done);
    parameter WIDTH = 8;
    input clk, reset;
    input [WIDTH-1:0] a0, b0, a1, b1, a2, b2;
    output reg [WIDTH-1:0] c0, c1, c2;
    output reg done;
    reg [3:0] K;
    reg mult_reset, delay1, delay2;
    wire e1, e2, e3, mult_done, delay3, rst;
    wire [WIDTH-1:0] in1, in2, o;

    assign rst = delay2;
    assign {e1,e2,e3} = K[3:1];

    f3m_mux3
        ins9 (a0, e1, a1, e2, a2, e3, in1),
        ins10 (b0, e1, b1, e2, b2, e3, in2);
    f3m_mult
        ins11 (clk, mult_reset, in1, in2, o, mult_done); // o == in1 * in2 in GF(3^m)
    func6
        ins12 (clk, reset, mult_done, delay3);

    always @ (posedge clk)
      begin
        if (e1) c0 <= o;
        if (e2) c1 <= o;
        if (e3) c2 <= o;
      end

    always @ (posedge clk)
        if (reset) K <= 4'b1000;
        else if (delay3 | K[0]) K <= {1'b0,K[3:1]};

    always @ (posedge clk)
      begin
        if (rst) mult_reset <= 1;
        else if (mult_done) mult_reset <= 1;
        else mult_reset <= 0;
      end

    always @ (posedge clk)
        if (reset)     done <= 0;
        else if (K[0]) done <= 1;

    always @ (posedge clk)
      begin 
        delay2 <= delay1; delay1 <= reset; 
      end
endmodule

