    input   wren;
    output  [31:0] q;

    reg [31:0] rom [0:63];

    initial begin
        $readmemh(ROM_INIT_FILE_NAME, rom);
    end

    always @(posedge clock) begin
        if (wren) begin
            rom[wraddress] <= data;
        end else begin
            q <= rom[rdaddress];
        end
    end

endmodule

module multiplier (
    input  wire        clk,
    input  wire        rst,
    input  wire [ 7:0] A,
    input  wire [ 7:0] B,
    output reg  [15:0] Z
);

    always @(posedge clk or posedge rst)
        if (rst) Z <= 0;
        else     Z <= A * B;

