module top_module (
    input clk,
    input reset,
    input [15:0] data_in1,
    input [15:0] data_in2,
    output [15:0] data_out,
    output reg EQ,
    output reg GT,
    output reg LT,
    input load,
    input shift
);

    wire [3:0] cmp_out;
    wire [15:0] shift_out;
    reg [15:0] shift_reg;

    // Instantiate the comparator module
    comparator_4bit cmp_inst (
        .a(data_in1[3:0]),
        .b(data_in2[3:0]),
        .eq(EQ),
        .gt(GT),
        .lt(LT),
        .out(cmp_out)
    );

    // Instantiate the shift register module
    shift_register_16bit shift_inst (
        .clk(clk),
        .reset(reset),
        .data_in(data_in2),
        .load(load),
        .shift(shift),
        .data_out(shift_out)
    );

    // Compare the inputs and perform the appropriate action
    always @ (posedge clk) begin
        if (EQ) begin
            shift_reg <= data_in1;
        end else begin
            shift_reg[15:1] <= shift_reg[14:0];
            shift_reg[0] <= data_in2[0];
        end
    end

    assign data_out = shift_out;

endmodule

module fifo36_demux
  #(parameter match_data = 0,
    parameter match_mask = 0)
   (input clk, input reset, input clear,
    input [35:0] data_i, input src_rdy_i, output dst_rdy_o,
    output [35:0] data0_o, output src0_rdy_o, input dst0_rdy_i,
    output [35:0] data1_o, output src1_rdy_o, input dst1_rdy_i);

   localparam DMX_IDLE = 0;
   localparam DMX_DATA0 = 1;
   localparam DMX_DATA1 = 2;

   reg [1:0] 	  state;
   reg [35:0] 	  reg_data0, reg_data1;

   wire 	  match = |( (data_i ^ match_data) & match_mask );
   wire 	  eof = data_i[33];

   always @(posedge clk)
     if(reset | clear)
       state <= DMX_IDLE;
     else
       case(state)
	 DMX_IDLE :
	   if(src_rdy_i)
	     if(match)
	       begin
		 state <= DMX_DATA1;
		 reg_data1 <= data_i;
	       end
	     else
	       begin
		 state <= DMX_DATA0;
		 reg_data0 <= data_i;
	       end
	 DMX_DATA0 :
	   if(src_rdy_i & dst0_rdy_i & eof)
	     begin
	       state <= DMX_IDLE;
	       src0_rdy_o <= 0;
	     end
	   else
	     src0_rdy_o <= 1;
	 DMX_DATA1 :
	   if(src_rdy_i & dst1_rdy_i & eof)
	     begin
	       state <= DMX_IDLE;
	       src1_rdy_o <= 0;
	     end
	   else
	     src1_rdy_o <= 1;
	 default :
	   state <= DMX_IDLE;
       endcase // case (state)

   assign dst_rdy_o = (state==DMX_IDLE) ? 0 : (state==DMX_DATA0) ? dst0_rdy_i : dst1_rdy_i;

   assign data0_o = reg_data0;
   assign data1_o = reg_data1;

endmodule

module comparator_8bit (
    input [7:0] in0,
    input [7:0] in1,
    output reg out
);

always @(*) begin
    if (in0 > in1)
        out = 1;
    else
        out = 0;
end

endmodule

module shift_comp (
    input clk,
    input reset,
    input [15:0] serial_in,
    input shift_direction,
    output [15:0] serial_out,
    output final_output
);

    // Define the 16-bit shift register module
    reg [15:0] shift_reg;
    always @(posedge clk) begin
        if (reset) begin
            shift_reg <= 16'b0;
        end else begin
            if (shift_direction) begin
                shift_reg <= {shift_reg[14:0], serial_in[0]};
            end else begin
                shift_reg <= {serial_in[15], shift_reg[15:1]};
            end
        end
    end
    assign serial_out = shift_reg;

    // Define the 4-bit magnitude comparator module
    reg [3:0] constant = 4'b1010;
    wire equal, greater;
    comparator comp(.a(shift_reg), .b(constant), .equal(equal), .greater(greater));

    // Define the functional module
    reg final_output_reg;
    always @(posedge clk) begin
        if (reset) begin
            final_output_reg <= 1'b0;
        end else begin
            if (equal && greater) begin
                final_output_reg <= 1'b1;
            end else begin
                final_output_reg <= 1'b0;
            end
        end
    end
    assign final_output = final_output_reg;

endmodule

module barrel_shifter (
    input [3:0] in,
    input [1:0] ctrl,
    output reg [3:0] out
);

reg [3:0] stage1_out;
reg [3:0] stage2_out;

always @(*) begin
    case(ctrl)
        2'b00: stage1_out = {in[2:0], 1'b0};
        2'b01: stage1_out = {in[1:0], 2'b0};
        2'b10: stage1_out = {1'b0, in[3:1]};
        2'b11: stage1_out = {2'b0, in[3:2]};
        default: stage1_out = 4'b0;
    endcase
end

always @(posedge clk) begin
    stage2_out <= stage1_out;
end

assign out = stage2_out;

endmodule

module four_bit_adder (
  input [3:0] A,
  input [3:0] B,
  input [3:0] C,
  input [3:0] D,
  input Cin,
  output [3:0] Sum,
  output Cout
);

  wire [3:0] temp_sum1, temp_sum2, temp_sum3;

  // First add A and B
  full_adder fa1(.A(A[0]), .B(B[0]), .Cin(Cin), .Sum(temp_sum1[0]), .Cout(Cout1));
  full_adder fa2(.A(A[1]), .B(B[1]), .Cin(Cout1), .Sum(temp_sum1[1]), .Cout(Cout2));
  full_adder fa3(.A(A[2]), .B(B[2]), .Cin(Cout2), .Sum(temp_sum1[2]), .Cout(Cout3));
  full_adder fa4(.A(A[3]), .B(B[3]), .Cin(Cout3), .Sum(temp_sum1[3]), .Cout(Cout4));

  // Then add C and D
  full_adder fa5(.A(C[0]), .B(D[0]), .Cin(0), .Sum(temp_sum2[0]), .Cout(Cout5));
  full_adder fa6(.A(C[1]), .B(D[1]), .Cin(Cout5), .Sum(temp_sum2[1]), .Cout(Cout6));
  full_adder fa7(.A(C[2]), .B(D[2]), .Cin(Cout6), .Sum(temp_sum2[2]), .Cout(Cout7));
  full_adder fa8(.A(C[3]), .B(D[3]), .Cin(Cout7), .Sum(temp_sum2[3]), .Cout(Cout8));

  // Finally add the two intermediate sums
  full_adder fa9(.A(temp_sum1[0]), .B(temp_sum2[0]), .Cin(Cout4), .Sum(Sum[0]), .Cout(Cout10));
  full_adder fa10(.A(temp_sum1[1]), .B(temp_sum2[1]), .Cin(Cout10), .Sum(Sum[1]), .Cout(Cout11));
  full_adder fa11(.A(temp_sum1[2]), .B(temp_sum2[2]), .Cin(Cout11), .Sum(Sum[2]), .Cout(Cout12));
  full_adder fa12(.A(temp_sum1[3]), .B(temp_sum2[3]), .Cin(Cout12), .Sum(Sum[3]), .Cout(Cout));

endmodule

module full_adder (
  input A,
  input B,
  input Cin,
  output Sum,
  output Cout
);

  assign Sum = A ^ B ^ Cin;
  assign Cout = (A & B) | (Cin & (A ^ B));

endmodule

module alarm_system(
    input wire [7:0] sensor_bus,
    input wire reset,
    input wire clk,
    output reg alarm
);

reg [7:0] sensor_state;

// Read the state of the sensors on every clock cycle
always @(posedge clk) begin
    if (reset) begin
        sensor_state <= 8'h00;
    end else begin
        sensor_state <= sensor_bus;
    end
end

// Set the alarm if any of the sensors are triggered
always @(posedge clk) begin
    if (reset) begin
        alarm <= 0;
    end else begin
        if (sensor_state != 8'h00) begin
            alarm <= 1;
        end else begin
            alarm <= 0;
        end
    end
end

endmodule

