    B,
    Cin,
    S,
    Cout
);

    input [3:0] A;
    input [3:0] B;
    input Cin;
    output [3:0] S;
    output Cout;

    wire [3:0] C;

    CLKBUFX3 clock_buffer(
        .A(Cout),
        .Y()
    );

    assign S = A + B + Cin;

    assign Cout = (C[3] == 1) ? 1'b1 : 1'b0;

    genvar i;
    generate
        for(i=0; i<4; i=i+1) begin: FullAdder
            FullAdder FA(
                .A(A[i]),
                .B(B[i]),
                .Cin(C[i]),
                .S(S[i]),
                .Cout(C[i+1])
            );
        end
    endgenerate

