module video_stream_merger (
	// Inputs
	clk,
	reset,

	stream_in_data_0,
	stream_in_startofpacket_0,
	stream_in_endofpacket_0,
	stream_in_empty_0,
	stream_in_valid_0,

	stream_in_data_1,
	stream_in_startofpacket_1,
	stream_in_endofpacket_1,
	stream_in_empty_1,
	stream_in_valid_1,

	stream_out_ready,

	// Outputs
	sync_ready,

	stream_in_ready_0,

	stream_in_ready_1,

	stream_out_data,
	stream_out_startofpacket,
	stream_out_endofpacket,
	stream_out_empty,
	stream_out_valid
);

parameter DW = 23; // Frame's data width
parameter EW = 1; // Frame's empty width

reg [DW:0] stream_out_data;
reg stream_out_startofpacket;
reg stream_out_endofpacket;
reg [EW:0] stream_out_empty;
reg stream_out_valid;

wire enable_setting_stream_select;
assign sync_ready = enable_setting_stream_select;

reg between_frames;
reg stream_select_reg;

assign stream_in_ready_0 = (stream_select_reg) ? 1'b0 : stream_in_valid_0 & (~stream_out_valid | stream_out_ready);
assign stream_in_ready_1 = (stream_select_reg) ? stream_in_valid_1 & (~stream_out_valid | stream_out_ready) : 1'b0;

assign enable_setting_stream_select =
		  (stream_in_ready_0 & stream_in_endofpacket_0) |
		  (stream_in_ready_1 & stream_in_endofpacket_1) |
		(~(stream_in_ready_0 & stream_in_startofpacket_0) & between_frames) |
		(~(stream_in_ready_1 & stream_in_startofpacket_1) & between_frames);

always @(posedge clk) begin
	if (reset) begin
		stream_out_data <= 'h0;
		stream_out_startofpacket <= 1'b0;
		stream_out_endofpacket <= 1'b0;
		stream_out_empty <= 'h0;
		stream_out_valid <= 1'b0;
	end
	else if (stream_in_ready_0) begin
		stream_out_data <= stream_in_data_0;
		stream_out_startofpacket <= stream_in_startofpacket_0;
		stream_out_endofpacket <= stream_in_endofpacket_0;
		stream_out_empty <= stream_in_empty_0;
		stream_out_valid <= stream_in_valid_0;
	end
	else if (stream_in_ready_1) begin
		stream_out_data <= stream_in_data_1;
		stream_out_startofpacket <= stream_in_startofpacket_1;
		stream_out_endofpacket <= stream_in_endofpacket_1;
		stream_out_empty <= stream_in_empty_1;
		stream_out_valid <= stream_in_valid_1;
	end
	else if (stream_out_ready) begin
		stream_out_valid <= 1'b0;
	end
end

always @(posedge clk) begin
	if (reset) begin
		between_frames <= 1'b1;
	end
	else if (stream_in_ready_0 & stream_in_endofpacket_0) begin
		between_frames <= 1'b1;
	end
	else if (stream_in_ready_1 & stream_in_endofpacket_1) begin
		between_frames <= 1'b1;
	end
	else if (stream_in_ready_0 & stream_in_startofpacket_0) begin
		between_frames <= 1'b0;
	end
	else if (stream_in_ready_1 & stream_in_startofpacket_1) begin
		between_frames <= 1'b0;
	end
end

always @(posedge clk) begin
	if (reset) begin
		stream_select_reg <= 1'b0;
	end
	else if (enable_setting_stream_select & sync_valid) begin
		stream_select_reg <= sync_data;
	end
end

endmodule

module muxed_ctrl_data(
  input [5:0] ByteCnt,
  input DlyCrcEn,
  input [1:0] DlyCrcCnt,
  input [47:0] MAC,
  input [15:0] TxPauseTV,
  input MTxClk,
  input TxReset,
  output reg [7:0] ControlData
);

reg [7:0] MuxedCtrlData;

always @ (ByteCnt or DlyCrcEn or MAC or TxPauseTV or DlyCrcCnt) begin
  case(ByteCnt)
    6'h0: if(~DlyCrcEn | DlyCrcEn & (&DlyCrcCnt[1:0]))
           MuxedCtrlData[7:0] = 8'h01; // Reserved Multicast Address
         else
           MuxedCtrlData[7:0] = 8'h0;
    6'h2: MuxedCtrlData[7:0] = 8'h80;
    6'h4: MuxedCtrlData[7:0] = 8'hC2;
    6'h6: MuxedCtrlData[7:0] = 8'h00;
    6'h8: MuxedCtrlData[7:0] = 8'h00;
    6'hA: MuxedCtrlData[7:0] = 8'h01;
    6'hC: MuxedCtrlData[7:0] = MAC[47:40];
    6'hE: MuxedCtrlData[7:0] = MAC[39:32];
    6'h10: MuxedCtrlData[7:0] = MAC[31:24];
    6'h12: MuxedCtrlData[7:0] = MAC[23:16];
    6'h14: MuxedCtrlData[7:0] = MAC[15:8];
    6'h16: MuxedCtrlData[7:0] = MAC[7:0];
    6'h18: MuxedCtrlData[7:0] = 8'h88; // Type/Length
    6'h1A: MuxedCtrlData[7:0] = 8'h08;
    6'h1C: MuxedCtrlData[7:0] = 8'h00; // Opcode
    6'h1E: MuxedCtrlData[7:0] = 8'h01;
    6'h20: MuxedCtrlData[7:0] = TxPauseTV[15:8]; // Pause timer value
    6'h22: MuxedCtrlData[7:0] = TxPauseTV[7:0];
    default: MuxedCtrlData[7:0] = 8'h0;
  endcase
end

always @ (posedge MTxClk or posedge TxReset) begin
  if(TxReset)
    ControlData[7:0] <= #Tp 8'h0;
  else if(~ByteCnt[0])
    ControlData[7:0] <= #Tp MuxedCtrlData[7:0];
end

endmodule

