module vga_controller(
    input clk,
    input reset,
    input enable,
    input [7:0] pixel_color,
    output hsync,
    output vsync,
    output [2:0] color
);

    // VGA timing parameters
    parameter H_FRONT_PORCH = 16;
    parameter H_SYNC_PULSE = 96;
    parameter H_BACK_PORCH = 48;
    parameter H_ACTIVE = 640;
    parameter V_FRONT_PORCH = 10;
    parameter V_SYNC_PULSE = 2;
    parameter V_BACK_PORCH = 33;
    parameter V_ACTIVE = 480;
    parameter PIXEL_CLOCK = 25_000_000;

    // VGA timing counters
    reg [10:0] h_count;
    reg [9:0] v_count;

    // Color palette
    reg [7:0] red;
    reg [7:0] green;
    reg [7:0] blue;

    // Horizontal timing signals
    wire h_blank = (h_count >= H_ACTIVE + H_FRONT_PORCH + H_SYNC_PULSE + H_BACK_PORCH);
    wire h_sync = (h_count >= H_ACTIVE + H_FRONT_PORCH && h_count < H_ACTIVE + H_FRONT_PORCH + H_SYNC_PULSE);
    wire h_active = (h_count < H_ACTIVE);

    // Vertical timing signals
    wire v_blank = (v_count >= V_ACTIVE + V_FRONT_PORCH + V_SYNC_PULSE + V_BACK_PORCH);
    wire v_sync = (v_count >= V_ACTIVE + V_FRONT_PORCH && v_count < V_ACTIVE + V_FRONT_PORCH + V_SYNC_PULSE);
    wire v_active = (v_count < V_ACTIVE);

    // Color signals
    assign color = {red[5:3], green[5:3], blue[5:2]};

    // Pixel color memory
    reg [7:0] pixel_mem;

    // Pixel memory write enable
    wire pixel_we = (h_active && v_active);

    // Pixel memory write
    always @(posedge clk)
    begin
        if (pixel_we)
            pixel_mem <= pixel_color;
    end

    // Color palette lookup
    always @(pixel_mem)
    begin
        case (pixel_mem)
            8'h00: begin red <= 8'h00; green <= 8'h00; blue <= 8'h00; end // black
            8'h01: begin red <= 8'h00; green <= 8'h00; blue <= 8'hAA; end // blue
            8'h02: begin red <= 8'h00; green <= 8'hAA; blue <= 8'h00; end // green
            8'h03: begin red <= 8'h00; green <= 8'hAA; blue <= 8'hAA; end // cyan
            8'h04: begin red <= 8'hAA; green <= 8'h00; blue <= 8'h00; end // red
            8'h05: begin red <= 8'hAA; green <= 8'h00; blue <= 8'hAA; end // magenta
            8'h06: begin red <= 8'hAA; green <= 8'h55; blue <= 8'h00; end // brown
            8'h07: begin red <= 8'hAA; green <= 8'hAA; blue <= 8'hAA; end // light gray
            8'h08: begin red <= 8'h55; green <= 8'h55; blue <= 8'h55; end // dark gray
            8'h09: begin red <= 8'h55; green <= 8'h55; blue <= 8'hFF; end // bright blue
            8'h0A: begin red <= 8'h55; green <= 8'hFF; blue <= 8'h55; end // bright green
            8'h0B: begin red <= 8'h55; green <= 8'hFF; blue <= 8'hFF; end // bright cyan
            8'h0C: begin red <= 8'hFF; green <= 8'h55; blue <= 8'h55; end // bright red
            8'h0D: begin red <= 8'hFF; green <= 8'h55; blue <= 8'hFF; end // bright magenta
            8'h0E: begin red <= 8'hFF; green <= 8'hFF; blue <= 8'h55; end // yellow
            8'h0F: begin red <= 8'hFF; green <= 8'hFF; blue <= 8'hFF; end // white
            default: begin red <= 8'h00; green <= 8'h00; blue <= 8'h00; end // black
        endcase
    end

    // Horizontal and vertical counters
    always @(posedge clk)
    begin
        if (reset)
        begin
            h_count <= 0;
            v_count <= 0;
        end
        else if (h_blank && v_blank)
        begin
            h_count <= 0;
            v_count <= 0;
        end
        else if (h_blank)
            h_count <= 0;
        else if (v_blank)
            v_count <= 0;
        else if (h_active)
            h_count <= h_count + 1;
        else if (v_active)
            v_count <= v_count + 1;
    end

    // Horizontal sync
    assign hsync = (h_sync) ? 1'b0 : 1'b1;

    // Vertical sync
    assign vsync = (v_sync) ? 1'b0 : 1'b1;

    // Color signals
    assign color = {red[5:3], green[5:3], blue[5:2]};

    // Enable/disable display
    assign color = (enable) ? color : 3'b000;

endmodule

