module edge_detector_priority_encoder (
    input clk,
    input [7:0] in,
    output reg [2:0] pos
);

reg [7:0] prev_in;
reg [7:0] edge_detect;
reg [7:0] edge_detect_delay;
reg [2:0] gray_code;
reg [2:0] binary_code;

parameter IDLE = 3'b000;
parameter RISING_EDGE = 3'b001;
parameter FALLING_EDGE = 3'b010;

// FSM for edge detection
always @(posedge clk) begin
    case (state)
        IDLE: begin
            if (in != prev_in) begin
                edge_detect <= in ^ prev_in;
                edge_detect_delay <= edge_detect;
                state <= RISING_EDGE;
            end
        end
        RISING_EDGE: begin
            edge_detect <= in ^ prev_in;
            edge_detect_delay <= edge_detect;
            if (edge_detect_delay == 0) begin
                state <= IDLE;
            end else begin
                state <= FALLING_EDGE;
            end
        end
        FALLING_EDGE: begin
            edge_detect <= in ^ prev_in;
            edge_detect_delay <= edge_detect;
            if (edge_detect_delay == 0) begin
                state <= IDLE;
            end else begin
                state <= RISING_EDGE;
            end
        end
    endcase
    prev_in <= in;
end

// Binary to Gray code converter
always @(edge_detect) begin
    gray_code[2] <= edge_detect[7];
    gray_code[1] <= edge_detect[7] ^ edge_detect[6];
    gray_code[0] <= edge_detect[6] ^ edge_detect[5];
end

// Gray to binary code converter
always @(gray_code) begin
    case (gray_code)
        3'b000: binary_code <= 3'b000;
        3'b001: binary_code <= 3'b001;
        3'b010: binary_code <= 3'b011;
        3'b011: binary_code <= 3'b010;
        3'b100: binary_code <= 3'b110;
        3'b101: binary_code <= 3'b111;
        3'b110: binary_code <= 3'b101;
        3'b111: binary_code <= 3'b100;
    endcase
end

// Priority encoder
always @(binary_code) begin
    case (binary_code)
        3'b001: pos <= 3'b000;
        3'b010: pos <= 3'b001;
        3'b011: pos <= 3'b010;
        3'b100: pos <= 3'b011;
        3'b101: pos <= 3'b100;
        3'b110: pos <= 3'b101;
        3'b111: pos <= 3'b110;
        default: pos <= 3'b000;
    endcase
end

endmodule

