        else begin
            input_i_tready <= 0;
            input_q_tready <= 0;
        end

        if (i_valid && q_valid && output_tready) begin
            output_i_tdata <= i_data;
            output_q_tdata <= q_data;
            output_tvalid <= 1;
            i_valid <= 0;
            q_valid <= 0;
        end
    end
end

endmodule

module binary_counter(clk, reset, load, data_in, count);

input clk, reset, load;
input [3:0] data_in;
output reg [3:0] count;

always @(posedge clk) begin
    if (reset) begin
        count <= 4'b0;
    end
    else if (load) begin
        count <= data_in;
    end
    else begin
        count <= count + 1;
    end
end

endmodule

module top_module (
    input [2:0] sel, // input for multiplexer select
    input [3:0] data0, // data inputs for multiplexer
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    input [3:0] in, // input for priority encoder
    output [7:0] q  // 8-bit output from the functional module
);

    // 6-to-1 multiplexer
    wire [3:0] mux_out;
    assign mux_out = (sel == 0) ? data0 :
                     (sel == 1) ? data1 :
                     (sel == 2) ? data2 :
                     (sel == 3) ? data3 :
                     (sel == 4) ? data4 :
                     (sel == 5) ? data5 : 4'b0000;

    // 4-bit priority encoder
    wire [1:0] enc_out;
    assign enc_out = (in[3]) ? 2'b11 :
                     (in[2]) ? 2'b10 :
                     (in[1]) ? 2'b01 :
                     (in[0]) ? 2'b00 : 2'b00;

    // Functional module
    assign q = {enc_out, 4'b0000} + mux_out;

endmodule

module up_down_counter (
    input clk,
    input async_reset,
    input [1:0] enable,
    output reg [1:0] count
);

    always @(posedge clk or negedge async_reset) begin
        if (!async_reset) begin
            count <= 2'b00;
        end else begin
            case (enable)
                2'b00: count <= count;
                2'b01: count <= count + 2'b01;
                2'b10: count <= count - 2'b01;
                default: count <= count;
            endcase
        end
    end

endmodule

module average_module(
    input clk,
    input [7:0] d,
    output reg [7:0] average
);

reg [7:0] shift_reg [0:7];
integer i;
reg [11:0] sum;

always @(posedge clk) begin
    // Shift the input data into the shift register
    for (i = 7; i > 0; i = i - 1) begin
        shift_reg[i] <= shift_reg[i - 1];
    end
    shift_reg[0] <= d;

    // Calculate the sum using half adders
    sum <= 0;
    for (i = 0; i < 8; i = i + 1) begin
        sum <= sum + shift_reg[i];
    end

    // Calculate the average
    average <= sum >> 3;
end

endmodule

module bcd_binary_counter (
    input clk,
    input reset,   // Synchronous active-high reset
    input [3:1] ena,
    output reg [11:0] q
);

reg [3:0] bcd_count;
reg [7:0] binary_count;

always @(posedge clk) begin
    if (reset) begin
        bcd_count <= 0;
        binary_count <= 0;
    end else begin
        if (ena) begin
            if (bcd_count == 999) begin
                bcd_count <= 0;
                binary_count <= binary_count + 1;
            end else begin
                bcd_count <= bcd_count + 1;
            end
        end else begin
            binary_count <= binary_count + 1;
        end
    end
end

assign q = {bcd_count, binary_count};

endmodule

module counter_4bit (
    input clk,
    input en,
    input [1:0] compare_val,
    output reg [3:0] Q,
    output reg comp_out
);

reg [3:0] Q_reg1, Q_reg2, Q_reg3;

always @(posedge clk) begin
    Q_reg1 <= Q;
end

always @(posedge clk) begin
    Q_reg2 <= Q_reg1;
end

always @(posedge clk) begin
    Q_reg3 <= Q_reg2;
end

always @(posedge clk) begin
    if (en) begin
        Q <= Q_reg3 + 1;
    end else begin
        Q <= Q;
    end
end

always @(posedge clk) begin
    if (Q >= compare_val) begin
        comp_out <= 1;
    end else begin
        comp_out <= 0;
    end
end

endmodule

module calculator (
    input clk,
    input rst,
    input [1:0] op,
    input [31:0] a,
    input [31:0] b,
    input mem_write,
    input [7:0] mem_addr,
    output [31:0] result,
    output mem_read,
    output [31:0] mem_data
);

    reg [31:0] result_reg;
    reg mem_read_reg;
    reg [31:0] mem_data_reg;
    reg [1:0] op_reg;
    reg [31:0] a_reg;
    reg [31:0] b_reg;
    reg [7:0] mem_addr_reg;
    reg mem_write_reg;

    always @(posedge clk) begin
        if (rst) begin
            result_reg <= 0;
            mem_read_reg <= 0;
            mem_data_reg <= 0;
            op_reg <= 0;
            a_reg <= 0;
            b_reg <= 0;
            mem_addr_reg <= 0;
            mem_write_reg <= 0;
        end else begin
            op_reg <= op;
            a_reg <= a;
            b_reg <= b;
            mem_addr_reg <= mem_addr;
            mem_write_reg <= mem_write;

            case (op_reg)
                2'b00: result_reg <= a_reg + b_reg;
                2'b01: result_reg <= a_reg - b_reg;
                2'b10: result_reg <= a_reg * b_reg;
                2'b11: result_reg <= a_reg / b_reg;
            endcase

            if (mem_write_reg) begin
                mem[mem_addr_reg] <= result_reg;
            end else begin
                mem_read_reg <= 1;
                mem_data_reg <= mem[mem_addr_reg];
            end
        end
    end

    assign result = result_reg;
    assign mem_read = mem_read_reg;
    assign mem_data = mem_data_reg;

endmodule

module mealy_3bit_pattern_detection (
  input clk,
  input reset,
  input data,
  output reg match
);

  parameter IDLE=2'b00, STATE1=2'b01, STATE2=2'b10;
  reg [1:0] state, next_state;

  always @(posedge clk) begin
    if (reset) begin
      state <= IDLE;
      match <= 0;
    end
    else begin
      state <= next_state;
      match <= (state == STATE2);
    end
  end

  always @(*) begin
    case (state)
      IDLE: begin
        if (data) next_state = STATE1;
        else next_state = IDLE;
      end
      STATE1: begin
        if (data) next_state = STATE2;
        else next_state = IDLE;
      end
      STATE2: begin
        if (data) next_state = STATE2;
        else next_state = STATE1;
      end
    endcase
  end

endmodule

module top_module (
    input clk,
    input reset,
    input [7:0] A,
    input [7:0] B,
    output reg [15:0] P
);

reg [7:0] A_reg;
reg [7:0] B_reg;
reg [7:0] B_shift_reg;
reg [3:0] count;

always @(posedge clk) begin
    if (reset) begin
        P <= 0;
        A_reg <= 0;
        B_reg <= 0;
        B_shift_reg <= 0;
        count <= 0;
    end else begin
        A_reg <= A;
        B_reg <= B;
        B_shift_reg <= {B_shift_reg[6:0], B_reg[0]};
        if (count < 8) begin
            if (B_shift_reg[7]) begin
                P <= P + (A_reg << count);
            end
            count <= count + 1;
        end
    end
end

endmodule

module counter (
  output reg [3:0] count,
  input [2:0] index,
  input inc_dec_b,
  input enable,
  input rst,
  input clk
);

  reg [3:0] reg_cnt;
  reg [3:0] reg_cnt_next;
  reg [3:0] reg_cnt_next_next;
  reg [1:0] stage;

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      stage <= 0;
      reg_cnt <= 0;
      count <= 0;
    end else if (stage == 0) begin
      reg_cnt_next <= inc_dec_b ? reg_cnt + index : reg_cnt - index;
      stage <= 1;
    end else if (stage == 1) begin
      reg_cnt_next_next <= (reg_cnt_next == 4'hF && inc_dec_b) || (reg_cnt_next == 4'h0 && !inc_dec_b) ? reg_cnt_next_next : reg_cnt_next;
      stage <= 2;
    end else if (stage == 2) begin
      reg_cnt <= enable ? reg_cnt_next_next : 0;
      count <= reg_cnt;
      stage <= 0;
    end
  end

endmodule

