module Inverse_Clarke_Transform (
    input signed [17:0] alpha_voltage,
    input signed [17:0] beta_voltage,
    output signed [17:0] phase_voltages_0,
    output signed [17:0] phase_voltages_1,
    output signed [17:0] phase_voltages_2
);

    wire signed [35:0] voltage_phase_a;
    wire signed [35:0] Gain1_out1;
    wire signed [35:0] Gain_out1;
    wire signed [35:0] voltage_phase_b;
    wire signed [37:0] Add1_cast;
    wire signed [37:0] Add1_cast_1;
    wire signed [37:0] Add1_sub_cast;
    wire signed [37:0] Add1_sub_temp;
    wire signed [35:0] voltage_phase_c;
    wire signed [35:0] Mux_out1 [0:2];
    wire signed [17:0] Current_Data_Type_out1 [0:2];

    assign voltage_phase_a = {{2{alpha_voltage[17]}}, {alpha_voltage, 16'b0000000000000000}};
    assign Gain1_out1 = 56756 * beta_voltage;
    assign Gain_out1 = {{3{alpha_voltage[17]}}, {alpha_voltage, 15'b000000000000000}};
    assign voltage_phase_b = Gain1_out1 - Gain_out1;
    assign Add1_cast = Gain_out1;
    assign Add1_cast_1 =  - (Add1_cast);
    assign Add1_sub_cast = Gain1_out1;
    assign Add1_sub_temp = Add1_cast_1 - Add1_sub_cast;
    assign voltage_phase_c = Add1_sub_temp[35:0];
    assign Mux_out1[0] = voltage_phase_a;
    assign Mux_out1[1] = voltage_phase_b;
    assign Mux_out1[2] = voltage_phase_c;

    assign Current_Data_Type_out1[0] = ((Mux_out1[0][35] == 1'b0) && (Mux_out1[0][34:30] != 5'b00000) ? 18'sb011111111111111111 :
              ((Mux_out1[0][35] == 1'b1) && (Mux_out1[0][34:30] != 5'b11111) ? 18'sb100000000000000000 :
              $signed(Mux_out1[0][30:13])));
    assign Current_Data_Type_out1[1] = ((Mux_out1[1][35] == 1'b0) && (Mux_out1[1][34:30] != 5'b00000) ? 18'sb011111111111111111 :
              ((Mux_out1[1][35] == 1'b1) && (Mux_out1[1][34:30] != 5'b11111) ? 18'sb100000000000000000 :
              $signed(Mux_out1[1][30:13])));
    assign Current_Data_Type_out1[2] = ((Mux_out1[2][35] == 1'b0) && (Mux_out1[2][34:30] != 5'b00000) ? 18'sb011111111111111111 :
              ((Mux_out1[2][35] == 1'b1) && (Mux_out1[2][34:30] != 5'b11111) ? 18'sb100000000000000000 :
              $signed(Mux_out1[2][30:13])));

    assign phase_voltages_0 = Current_Data_Type_out1[0];
    assign phase_voltages_1 = Current_Data_Type_out1[1];
    assign phase_voltages_2 = Current_Data_Type_out1[2];

endmodule

module i2c_slave (sda, scl, ioout, adr, reset, debug);

	inout sda;	// address or data input on sda is sampled on posedge of scl
	input scl;
	input reset;
	input [6:0] adr; // the device address is always 7 bits wide !
	output reg [7:0] ioout;
	output debug;

	reg start = 1; // l-active, must default to 1 on power up !
	reg adr_match = 1; // defaults to 1 on power up	
	reg [4:0] ct = -1; // must default to -1 on power up (all bit set) !	
	reg [6:0] address = -1;
	reg [7:0] data_rx = -1;	

	// delay m1_pre by 2 negator propagation delays
	wire ct_reset;
	wire m1_pre_neg /* synthesis keep = 1 */;
	assign m1_pre_neg = !ct_reset;
	wire m1 /* synthesis keep = 1 */;
	assign m1 = !m1_pre_neg;

   always @(negedge sda or negedge m1)
      if (!m1) begin		// !m1 sets start register
         start <= 1'b1;
      end else 
		begin
         start <= !scl;	// on bus starting, start goes low for a very short time until set back to high by negedge of m1 
      end

	//assign debug = start;
	//reg debug;
	//always @*
	//	begin
	//		if (ct == 5'h1f) debug <= 1;
	//			else debug <= 0;
	//	end


	always @(posedge scl or negedge reset) // or negedge start)
		begin
			if (!reset)
				begin
					ioout <= -1;
					address <= -1;
					data_rx <= -1;
				end
			else 
			begin
					case (ct)
						5'h00	: address[6] <= sda;
						5'h01	: address[5] <= sda;
						5'h02	: address[4] <= sda;
						5'h03	: address[3] <= sda;
						5'h04	: address[2] <= sda;
						5'h05	: address[1] <= sda;
						5'h06	: address[0] <= sda;
						//5'h07	: rw_bit <= sda;

						5'h09	: data_rx[7] <= sda;
						5'h0a	: data_rx[6] <= sda;
						5'h0b	: data_rx[5] <= sda;
						5'h0c	: data_rx[4] <= sda;
						5'h0d	: data_rx[3] <= sda;
						5'h0e	: data_rx[2] <= sda;
						5'h0f	: data_rx[1] <= sda;
						5'h10	: data_rx[0] <= sda;

						5'h11	: if (address == adr) ioout <= data_rx;
					endcase
			end
		end

	assign ct_reset = start & reset; // ored zeroes
	always @(negedge scl or negedge ct_reset)
		begin
			if (!ct_reset) ct <= -1;
			else ct <= ct +1;  // posedge scl increments counter ct
		end


	always @(ct, adr, address)
		begin
			case (ct)
				5'h08	: if (address == adr) adr_match <= 0;  // address acknowledge

				5'h11	: if (address == adr) adr_match <= 0;  // data acknowledge

				default	: 	adr_match <= 1;							
			endcase
		end

	assign debug = adr_match;

	assign sda = adr_match ? 1'bz : 1'b0;


endmodule

module lookup_table #
(
    parameter integer TDATA_WIDTH = 32,
    parameter integer ADDRESS_WIDTH = 8
)
(
    input wire data_in_aclk,
    input wire data_in_aresetn,
    output wire data_in_tready,
    input wire [ADDRESS_WIDTH-1:0] data_in_tdata,
    input wire data_in_tlast,
    input wire data_in_tvalid,

    output wire data_out_aclk,
    input wire data_out_aresetn,
    input wire data_out_tready,
    output reg [TDATA_WIDTH-1:0] data_out_tdata,
    output reg data_out_tlast,
    output reg data_out_tvalid,

    input wire data_load_aclk,
    input wire data_load_aresetn,
    output wire data_load_tready,
    input wire [TDATA_WIDTH-1:0] data_load_tdata,
    input wire data_load_tlast,
    input wire data_load_tvalid
);

    reg [TDATA_WIDTH-1:0] register_space[2**ADDRESS_WIDTH-1:0];
    reg [ADDRESS_WIDTH-1:0] data_load_address;
    reg [ADDRESS_WIDTH-1:0] data_in_tdata_reg;
    reg [ADDRESS_WIDTH-1:0] data_in_tdata_next;
    reg data_out_tvalid_reg;

    always @(posedge data_load_aclk) begin
        if (!data_load_aresetn) begin
            data_load_address <= 0;
        end else if (data_load_tvalid & data_load_tready) begin
            register_space[data_load_address] <= data_load_tdata;
            data_load_address <= data_load_address + 1;
        end else if (data_load_tlast) begin
            data_load_address <= 0;
        end
    end

    always @(posedge data_in_aclk) begin
        if (!data_in_aresetn) begin
            data_in_tdata_reg <= 0;
        end else if (data_in_tvalid & data_in_tready) begin
            data_in_tdata_reg <= data_in_tdata;
        end
    end

    always @(posedge data_out_aclk) begin
        if (!data_out_aresetn) begin
            data_out_tdata <= 0;
            data_out_tvalid_reg <= 0;
            data_out_tlast <= 0;
        end else if (data_in_tvalid & data_in_tready) begin
            data_out_tdata <= register_space[data_in_tdata_reg];
            data_out_tvalid_reg <= 1;
            data_out_tlast <= data_in_tlast;
        end else if (data_out_tready) begin
            data_out_tvalid_reg <= 0;
            data_out_tlast <= 0;
        end
    end

    assign data_in_tready = !data_in_tvalid | data_out_tready;
    assign data_load_tready = !data_load_tvalid | (data_load_tlast ? 1 : (data_load_tready & data_load_tvalid));

    assign data_out_tvalid = data_out_tvalid_reg;

endmodule

module d_ff_rst_en (
    input CLK,
    input D,
    input RESETn,
    input ENn,
    output Q,
    output Q_N
);

    reg Q;
    wire Q_N;

    assign Q_N = ~Q;

    always @(posedge CLK) begin
        if (!RESETn) begin
            Q <= 1'b0;
        end else if (!ENn) begin
            Q <= Q;
        end else begin
            Q <= D;
        end
    end

endmodule
